		Analysis: "compare", Version: analysis.CompareVersion, Since: analyseSince, Until: analyseUntil,
		Summary:  "Under v1.3.3 duration p95 went from 5m to 9m.",
		Dominant: "duration_p95", Confidence: analysis.High,
