		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusConflict)
		_, _ = w.Write(body)
	}))
	t.Cleanup(srv.Close)
	_, errOut, code := runCLIFailing(t, "analyse", "compare", "--url", srv.URL)
	if code != exitError {
		t.Fatalf("exit %d, want %d", code, exitError)
