		t.Setenv("ZOOMIES_CONFIG_DIR", dir)
	}

	t.Run("it falls back to the installed controller", func(t *testing.T) {
		e, _, _ := newTestEnv(t)
		configDir(t, "server:\n  external_url: https://zoomies.example.com\n")
		client, err := parseClientFlags(t, e).client()
		if err != nil {
			t.Fatal(err)
		}
		if client.base != "https://zoomies.example.com" {
			t.Errorf("base = %q, want the installed controller's address", client.base)
		}
	})

	t.Run("a flag, the environment and the file all beat it", func(t *testing.T) {
		e, _, _ := newTestEnv(t)
		configDir(t, "server:\n  external_url: https://installed.example.com\n")
		writeCLIConfig(t, "url: https://from-file.example.com\n")
		if c, _ := parseClientFlags(t, e).client(); c == nil || c.base != "https://from-file.example.com" {
			t.Errorf("the CLI file must beat the installed controller, got %+v", c)
		}
		t.Setenv("ZOOMIES_URL", "https://from-env.example.com")
		if c, _ := parseClientFlags(t, e).client(); c == nil || c.base != "https://from-env.example.com" {
			t.Errorf("the environment must beat it, got %+v", c)
		}
		if c, _ := parseClientFlags(t, e, "--url", "https://from-flag.example.com").client(); c == nil || c.base != "https://from-flag.example.com" {
			t.Errorf("a flag must beat it, got %+v", c)
		}
	})

	t.Run("no installed controller is no guess", func(t *testing.T) {
		e, _, _ := newTestEnv(t) // an empty configuration directory
		_, err := parseClientFlags(t, e).client()
		if err == nil || !strings.Contains(err.Error(), "no controller configuration was found") {
			t.Errorf("a host with no controller must be told so, not sent to a default address: %v", err)
		}
	})
}

// A certificate the CLI does not trust, and an https address answered in plain HTTP, both used
// to read as "check that it is running", which sent an operator to a controller that was up.
func TestTransportErrorNamesTheFlagThatFixesACertificateOrSchemeMistake(t *testing.T) {
	tls := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {}))
	defer tls.Close()
	e, outBuf, errBuf := newTestEnv(t)
	code := dispatch(context.Background(), e, []string{"problems", "list", "--url", tls.URL})
	out, errOut := outBuf.String(), errBuf.String()
	if code == exitOK {
		t.Fatalf("a self-signed controller was trusted:\n%s", out)
	}
	for _, want := range []string{"certificate is not trusted", "--ca-file", "ca_file"} {
		if !strings.Contains(errOut, want) {
			t.Errorf("the certificate error does not say %q:\n%s", want, errOut)
		}
	}
	if strings.Contains(errOut, "check that it is running") {
		t.Errorf("a controller that answered was described as not running:\n%s", errOut)
	}

	plain := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {}))
	defer plain.Close()
	e, _, errBuf = newTestEnv(t)
	code = dispatch(context.Background(), e, []string{"problems", "list", "--url", "https://" + strings.TrimPrefix(plain.URL, "http://")})
	errOut = errBuf.String()
	if code == exitOK {
		t.Fatal("plain HTTP was accepted for an https address")
	}
	for _, want := range []string{"plain HTTP", "http://"} {
		if !strings.Contains(errOut, want) {
			t.Errorf("the scheme error does not say %q:\n%s", want, errOut)
		}
	}
}

// A host that joined a controller as an agent has a zoomies.yaml too, and what it
// names is the controller it joined. The CLI used to read it for a listener of its
// own, found the default one on loopback, and sent `zoomies doctor --host` there:
// to an address nothing on that host answers.
func TestAnAgentHostFindsTheControllerItJoined(t *testing.T) {
	configDir := func(t *testing.T, yaml string) string {
		t.Helper()
		dir := t.TempDir()
		if err := os.WriteFile(filepath.Join(dir, "zoomies.yaml"), []byte(yaml), 0o600); err != nil {
			t.Fatal(err)
		}
		t.Setenv("ZOOMIES_CONFIG_DIR", dir)
		return filepath.Join(dir, "zoomies.yaml")
	}

	t.Run("it uses the controller the agent joined, and says where that came from", func(t *testing.T) {
		e, _, _ := newTestEnv(t)
		file := configDir(t, "agent:\n  embedded: false\n  controller_url: https://zoomies.example.com\n")
		client, err := parseClientFlags(t, e).client()
		if err != nil {
			t.Fatal(err)
		}
		if client.base != "https://zoomies.example.com" {
			t.Errorf("base = %q, want the controller this host joined and not a listener on loopback", client.base)
		}
		if client.source != file {
			t.Errorf("source = %q, want the file it was read from, %q", client.source, file)
		}
	})

	t.Run("a private connection is said to be one, not guessed at", func(t *testing.T) {
		e, _, _ := newTestEnv(t)
		file := configDir(t, "agent:\n  embedded: false\n  controller_url: tailcat://controller\n")
		_, err := parseClientFlags(t, e).client()
		if err == nil {
			t.Fatal("a controller reached through a tunnel was given an address")
		}
		for _, want := range []string{file, "private connection", "--url"} {
			if !strings.Contains(err.Error(), want) {
				t.Errorf("the error does not mention %q:\n%s", want, err)
			}
		}
		if strings.Contains(err.Error(), "no controller configuration was found") {
			t.Errorf("the file is there, and the error says it is not:\n%s", err)
		}
	})
}

// "Cannot reach the controller" is the error an operator meets when the address is
// wrong, and an address they never typed is the one they cannot fix, so it says
// where it came from.
func TestTheUnreachableErrorSaysWhereTheAddressCameFrom(t *testing.T) {
	gone := httptest.NewServer(http.HandlerFunc(func(http.ResponseWriter, *http.Request) {}))
	address := gone.URL
	gone.Close()

	t.Run("a flag", func(t *testing.T) {
		e, _, errOut := newTestEnv(t)
		dispatch(context.Background(), e, []string{"pools", "list", "--url", address})
		if !strings.Contains(errOut.String(), "the address came from --url") {
			t.Errorf("the error does not say where the address came from:\n%s", errOut)
		}
	})
	t.Run("the environment", func(t *testing.T) {
		e, _, errOut := newTestEnv(t)
		t.Setenv("ZOOMIES_URL", address)
		dispatch(context.Background(), e, []string{"pools", "list"})
		if !strings.Contains(errOut.String(), "the address came from ZOOMIES_URL") {
			t.Errorf("the error does not say where the address came from:\n%s", errOut)
		}
	})
	t.Run("the connection file", func(t *testing.T) {
		e, _, errOut := newTestEnv(t)
		writeCLIConfig(t, "url: "+address+"\n")
		dispatch(context.Background(), e, []string{"pools", "list"})
		if !strings.Contains(errOut.String(), "the address came from "+cliConfigPath()) {
			t.Errorf("the error does not say where the address came from:\n%s", errOut)
		}
	})
}

package main

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"os"
	"regexp"
	"strings"

	"github.com/eyupio/zoomies/internal/version"
)

// commandDoc is one top-level command as the binary describes itself: the help
// it prints, and for a group each subcommand's help in turn. It is what
// `zoomies commands` emits and what skills/zoomies/reference.md is generated
// from, so a reference an agent reads cannot drift from what --help says.
type commandDoc struct {
	Name        string          `json:"name"`
	Group       string          `json:"group"`
	Brief       string          `json:"brief"`
	Help        string          `json:"help"`
	Subcommands []subcommandDoc `json:"subcommands,omitempty"`
}

type subcommandDoc struct {
	Name  string `json:"name"`
	Args  string `json:"args,omitempty"`
	Brief string `json:"brief"`
	Help  string `json:"help"`
}

// runCommands is `zoomies commands`: every command, its subcommands and the
// help the binary prints for each, as JSON or Markdown.
func runCommands(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies commands [--output json|markdown]", "Every command and subcommand with the help text the binary prints for it.")
	output := fs.String("output", "markdown", "json or markdown")
	fs.example("zoomies commands --output json", "zoomies commands > skills/zoomies/reference.md")
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	docs := collectCommandDocs(ctx)
	switch *output {
	case "json":
		enc := json.NewEncoder(e.out)
		enc.SetIndent("", "  ")
		return enc.Encode(docs)
	case "markdown":
		_, err := e.out.Write([]byte(renderCommandReference(docs)))
		return err
	default:
		return usagef("commands", "--output must be json or markdown, not %q", *output)
	}
}

// subcommandLine is a line of printGroupUsage's "Subcommands:" block: the name,
// its arguments if any, two or more spaces, then the brief.
var subcommandLine = regexp.MustCompile(`^  (\S+)((?: \S+)*?)\s{2,}(.+)$`)

// collectCommandDocs runs every command in-process with --help, which every
// one of them answers before doing anything else, and for a group runs each
// subcommand the same way. Nothing here is run with any other argument, so
// collecting the docs can neither touch a controller nor this machine.
func collectCommandDocs(ctx context.Context) []commandDoc {
	restore := pinEnvironmentForHelp()
	defer restore()
	var docs []commandDoc
	for _, c := range commands() {
		if c.name == "commands" {
			continue
		}
		help := helpOf(ctx, c.run, "--help")
		doc := commandDoc{Name: c.name, Group: c.group, Brief: c.brief, Help: help}
		for _, sub := range subcommandsOf(help) {
			sub.Help = helpOf(ctx, c.run, sub.Name, "--help")
			doc.Subcommands = append(doc.Subcommands, sub)
		}
		docs = append(docs, doc)
	}
	return docs
}

// referenceConfigDir and referenceStateDir are the directories the reference
// is written with: the documented defaults for a root install on Linux, which
// is what the help prints there and what every example in docs/ already names.
const (
	referenceConfigDir = "/etc/zoomies"
	referenceStateDir  = "/var/lib/zoomies"
)

// pinEnvironmentForHelp makes the help texts the same wherever they are
// collected. A flag's default can come from the environment -- the controller
// prints its configuration path and the gateway its state path, which are
// /etc/zoomies and /var/lib/zoomies for root on Linux and somewhere under the
// home directory for anyone else -- and a reference that changed with the
// generating machine would fail its test on the next one. Every ZOOMIES_*
// variable is cleared and both directories are pinned until the collection
// ends.
func pinEnvironmentForHelp() (restore func()) {
	var saved []string
	for _, kv := range os.Environ() {
		if strings.HasPrefix(kv, "ZOOMIES_") {
			saved = append(saved, kv)
			os.Unsetenv(kv[:strings.Index(kv, "=")])
		}
	}
	os.Setenv("ZOOMIES_CONFIG_DIR", referenceConfigDir)
	os.Setenv("ZOOMIES_STATE_DIR", referenceStateDir)
	return func() {
		os.Unsetenv("ZOOMIES_CONFIG_DIR")
		os.Unsetenv("ZOOMIES_STATE_DIR")
		for _, kv := range saved {
			i := strings.Index(kv, "=")
			os.Setenv(kv[:i], kv[i+1:])
		}
	}
}

// helpOf captures what a command prints for a help request. A flag set prints
// its usage to stderr and a group prints its list to stdout, so both are read.
func helpOf(ctx context.Context, run func(context.Context, *env, []string) error, args ...string) string {
	var out, errOut bytes.Buffer
	e := &env{out: &out, err: &errOut, in: strings.NewReader("")}
	_ = run(ctx, e, args)
	return strings.TrimRight(out.String()+errOut.String(), "\n") + "\n"
}

// subcommandsOf reads the "Subcommands:" block out of a group's help.
func subcommandsOf(help string) []subcommandDoc {
	var subs []subcommandDoc
	in := false
	for _, line := range strings.Split(help, "\n") {
		switch {
		case line == "Subcommands:":
			in = true
		case in && strings.HasPrefix(line, "  "):
			if m := subcommandLine.FindStringSubmatch(line); m != nil {
				subs = append(subs, subcommandDoc{Name: m[1], Args: strings.TrimSpace(m[2]), Brief: m[3]})
			}
		case in:
			in = false
		}
	}
	return subs
}

// renderCommandReference is the Markdown the skills carry: one section per
// group, one heading per command and subcommand, each with the help verbatim.
func renderCommandReference(docs []commandDoc) string {
	var b strings.Builder
	b.WriteString("# zoomies command reference\n\n")
	fmt.Fprintf(&b, "Generated by `zoomies commands` from %s, with the configuration directory at `%s` and the state directory at `%s` (the defaults for a root install on Linux) and no other `ZOOMIES_*` variable set, so the file is the same wherever it is generated. Do not edit: `make generate` rewrites it, and a test fails when it differs from the binary.\n", version.Short(), referenceConfigDir, referenceStateDir)
	for _, group := range []string{groupRun, groupFleet, groupSetup} {
		fmt.Fprintf(&b, "\n## %s\n", group)
		for _, d := range docs {
			if d.Group != group {
				continue
			}
			fmt.Fprintf(&b, "\n### zoomies %s\n\n%s\n\n```text\n%s```\n", d.Name, d.Brief, d.Help)
			for _, s := range d.Subcommands {
				fmt.Fprintf(&b, "\n#### zoomies %s %s\n\n%s\n\n```text\n%s```\n", d.Name, s.Name, s.Brief, s.Help)
			}
		}
	}
	return b.String()
}

package main

import (
	"bytes"
	"context"
	"encoding/json"
	"os"
	"runtime"
	"sort"
	"strconv"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/mcp"
)

// The reference the skills carry is generated from the binary, so the one
// thing it must do is list every command the binary has -- except itself,
// which is a generator and not something an agent runs on a fleet.
func TestCommandsListsEveryTopLevelCommandExceptItself(t *testing.T) {
	out, _ := runCLI(t, "commands", "--output", "json")
	var docs []commandDoc
	if err := json.Unmarshal([]byte(out), &docs); err != nil {
		t.Fatalf("not JSON: %v\n%s", err, out)
	}
	var got, want []string
	for _, d := range docs {
		got = append(got, d.Name)
		if strings.TrimSpace(d.Help) == "" {
			t.Errorf("%s has no help text", d.Name)
		}
	}
	for _, c := range commands() {
		if c.name != "commands" {
			want = append(want, c.name)
		}
	}
	sort.Strings(got)
	sort.Strings(want)
	if strings.Join(got, ",") != strings.Join(want, ",") {
		t.Fatalf("commands = %v\nwant %v", got, want)
	}
	// A group's subcommands come with it, each with the help the binary prints.
	for _, d := range docs {
		if d.Name == "pools" && len(d.Subcommands) == 0 {
			t.Errorf("pools has no subcommands listed")
		}
		for _, s := range d.Subcommands {
			if strings.TrimSpace(s.Help) == "" || s.Brief == "" {
				t.Errorf("%s %s: brief %q, help %q", d.Name, s.Name, s.Brief, s.Help)
			}
		}
	}
}

// The reference is committed and published, so a help text that quoted the
// machine it was generated on -- a home directory, a temp path -- would ship
// that machine's layout to everyone.
func TestCommandsHelpTextsHoldNoPathsFromThisMachine(t *testing.T) {
	out, _ := runCLI(t, "commands", "--output", "json")
	// /tmp itself is in several help texts on purpose (it is a folder a pool
	// can keep in memory), so the temporary directory is not a needle; the
	// working directory and the home directory are what would give the
	// generating machine away.
	wd, _ := os.Getwd()
	for _, needle := range []string{wd, os.Getenv("HOME")} {
		if needle != "" && needle != "/" && strings.Contains(out, needle) {
			t.Errorf("the help texts mention %q", needle)
		}
	}
}

// skills/zoomies/reference.md is what an agent reads instead of running
// --help on everything; it is generated, and this is what keeps it so.
func TestTheCommandReferenceMatchesTheBinary(t *testing.T) {
	// The reference is the Linux binary's help, which is where Zoomies is
	// operated from; Windows prints the same pinned default with its own
	// separator (\etc\zoomies), so the comparison is a Linux one and the
	// Windows job checks the rest of this package.
	if runtime.GOOS == "windows" {
		t.Skip("the command reference is generated from and compared with the Linux binary")
	}
	want, err := os.ReadFile("../../skills/zoomies/reference.md")
	if err != nil {
		t.Fatal(err)
	}
	// The command pins its own environment while it collects the help, so no
	// harness is needed here; a Windows checkout turns the file's line endings
	// into CRLF, which is not a difference in what the binary says.
	want = bytes.ReplaceAll(want, []byte("\r\n"), []byte("\n"))
	var out, errOut bytes.Buffer
	e := &env{out: &out, err: &errOut, in: strings.NewReader("")}
	if code := dispatch(context.Background(), e, []string{"commands", "--output", "markdown"}); code != exitOK {
		t.Fatalf("exit %d", code)
	}
	if out.String() != string(want) {
		t.Fatalf("skills/zoomies/reference.md is out of date; run `make generate` from the repository root and commit the result\n%s", firstDifference(string(want), out.String()))
	}
}

// firstDifference names the first line the two texts disagree on, so a stale
// reference says which help text moved rather than only that one did.
func firstDifference(a, b string) string {
	al, bl := strings.Split(a, "\n"), strings.Split(b, "\n")
	for i := 0; i < len(al) && i < len(bl); i++ {
		if al[i] != bl[i] {
			return "line " + strconv.Itoa(i+1) + ":\n  file:   " + al[i] + "\n  binary: " + bl[i]
		}
	}
	return "the file has " + strconv.Itoa(len(al)) + " lines and the binary prints " + strconv.Itoa(len(bl))
}

// A subcommand whose name and arguments leave fewer than two spaces before its
// brief does not match the line the generator reads, and drops out of the
// reference with everything under it and no error. Every line a group lists is
// therefore one the generator reads.
//
// Only the subcommands of the top-level groups are checked. A group nested
// inside one ("updates helper") prints its own list through the same
// printGroupUsage, so the padding rule holds for it, but the lines it lists are
// not compared with the reference here.
func TestEverySubcommandAGroupListsIsInTheReference(t *testing.T) {
	docs := collectCommandDocs(context.Background())
	byName := map[string]commandDoc{}
	for _, d := range docs {
		byName[d.Name] = d
	}
	for _, c := range commands() {
		if c.name == "commands" {
			continue
		}
		var listed []string
		in := false
		for _, line := range strings.Split(byName[c.name].Help, "\n") {
			switch {
			case line == "Subcommands:":
				in = true
			case in && strings.HasPrefix(line, "  "):
				listed = append(listed, strings.Fields(line)[0])
			case in:
				in = false
			}
		}
		var got []string
		for _, s := range byName[c.name].Subcommands {
			got = append(got, s.Name)
		}
		if strings.Join(got, ",") != strings.Join(listed, ",") {
			t.Errorf("zoomies %s lists %v, and the reference has %v", c.name, listed, got)
		}
	}
}

// The MCP reference the skill carries is generated from the server's own
// definitions, so an agent reading it reads this release's tools, resources
// and prompts, action tools included (they are offered only with
// --allow-actions, and the reference says so), and not a list somebody once
// typed. Like the command reference, it is compared with the binary.
func TestTheMCPReferenceMatchesTheBinary(t *testing.T) {
	want, err := os.ReadFile("../../skills/zoomies/mcp-reference.md")
	if err != nil {
		t.Fatal(err)
	}
	want = bytes.ReplaceAll(want, []byte("\r\n"), []byte("\n"))
	out, _ := runCLI(t, "mcp", "--describe", "--output", "markdown")
	if out != string(want) {
		t.Fatalf("skills/zoomies/mcp-reference.md is out of date; run `make generate` from the repository root and commit the result\n%s", firstDifference(string(want), out))
	}
}

// The description lists every tool the server has, offered or not, and says
// which ones change the fleet, so an agent can tell what --allow-actions would
// add before anyone restarts the server with it. It needs no controller.
func TestMCPDescribeListsEveryToolResourceAndPrompt(t *testing.T) {
	out, _ := runCLI(t, "mcp", "--describe", "--output", "json")
	var ref struct {
		Tools []struct {
			Name   string `json:"name"`
			Action bool   `json:"action"`
			Admin  bool   `json:"admin"`
		} `json:"tools"`
		Resources []struct {
			URI string `json:"uri"`
		} `json:"resources"`
		Prompts []struct {
			Name string `json:"name"`
		} `json:"prompts"`
	}
	if err := json.Unmarshal([]byte(out), &ref); err != nil {
		t.Fatalf("not JSON: %v\n%s", err, out)
	}
	byName := map[string]bool{}
	actions := map[string]bool{}
	for _, tool := range ref.Tools {
		byName[tool.Name] = true
		if tool.Action {
			actions[tool.Name] = true
		}
		if tool.Admin && !tool.Action {
			t.Errorf("%s is an administrator tool but not an action", tool.Name)
		}
	}
	for _, name := range []string{"fleet_status", "get_job", "get_catalog", "get_usage", "rerun_job", "update_settings"} {
		if !byName[name] {
			t.Errorf("%s is missing from the description", name)
		}
	}
	for _, name := range mcp.ActionTools() {
		if !actions[name] {
			t.Errorf("%s changes the fleet and the description does not say so", name)
		}
	}
	if len(ref.Resources) < 2 || len(ref.Prompts) < 3 {
		t.Errorf("resources %d, prompts %d", len(ref.Resources), len(ref.Prompts))
	}
	for _, r := range ref.Resources {
		if !strings.HasPrefix(r.URI, "zoomies://") {
			t.Errorf("resource %q is not one of this server's", r.URI)
		}
	}
}

package main

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

// jsonRoutes serves a fixed body per path, which is all these commands need:
// what is being tested is what the CLI renders, not what the controller
// decides.
func jsonRoutes(t *testing.T, routes map[string]string) *httptest.Server {
	t.Helper()
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, ok := routes[r.URL.Path]
		if !ok {
			t.Errorf("unexpected request %s %s", r.Method, r.URL.Path)
			w.WriteHeader(http.StatusNotFound)
			_, _ = w.Write([]byte(`{"error":{"code":"not_found","message":"no"}}`))
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(body))
	}))
	t.Cleanup(srv.Close)
	return srv
}

func runCLI(t *testing.T, args ...string) (string, string) {
	t.Helper()
	e, out, errOut := newTestEnv(t)
	if code := dispatch(context.Background(), e, args); code != exitOK {
		t.Fatalf("exit code = %d\n%s", code, errOut)
	}
	return out.String(), errOut.String()
}

// `pools get` is where an operator looks before changing anything, so it has to
// show the settings that weaken the defaults rather than only the safe ones.
func TestPoolsGetShowsTheDangerousSettings(t *testing.T) {
	srv := jsonRoutes(t, map[string]string{
		"/api/v1/pools/pool_1": `{
			"id":"pool_1","name":"zoomies-4vcpu","installation_id":"inst_1",
			"installation_target":"acme","labels":["zoomies-4vcpu"],"backend":"docker",
