func TestHealthcheckAgainstAServer(t *testing.T) {
	t.Run("healthy", func(t *testing.T) {
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			if r.URL.Path != "/healthz" {
				t.Errorf("path = %q, want /healthz", r.URL.Path)
			}
			_, _ = w.Write([]byte(`{"ok":true}`))
		}))
		defer srv.Close()

		e, out, _ := newTestEnv(t)
		if code := dispatch(context.Background(), e, []string{"healthcheck", "--url", srv.URL}); code != exitOK {
			t.Fatalf("exit code = %d, want 0", code)
		}
		if !strings.Contains(out.String(), "is healthy") {
			t.Errorf("output = %q", out)
		}
	})

	t.Run("a URL already ending in /healthz is not doubled", func(t *testing.T) {
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			if r.URL.Path != "/healthz" {
				t.Errorf("path = %q", r.URL.Path)
			}
			_, _ = w.Write([]byte(`{"ok":true}`))
		}))
		defer srv.Close()

		e, _, _ := newTestEnv(t)
		if code := dispatch(context.Background(), e, []string{"healthcheck", "--url", srv.URL + "/healthz"}); code != exitOK {
			t.Fatalf("exit code = %d", code)
		}
	})

	t.Run("not ready", func(t *testing.T) {
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
			w.WriteHeader(http.StatusServiceUnavailable)
			_, _ = w.Write([]byte(`{"ok":false,"message":"the database is not answering"}`))
		}))
		defer srv.Close()

		e, _, errOut := newTestEnv(t)
		if code := dispatch(context.Background(), e, []string{"healthcheck", "--url", srv.URL}); code != exitError {
			t.Fatalf("exit code = %d, want %d", code, exitError)
		}
		if !strings.Contains(errOut.String(), "503") {
			t.Errorf("the failure does not carry the status:\n%s", errOut)
		}
	})

	// The container's health check names http://127.0.0.1:8080 whatever the
	// controller serves, so with TLS on it could never pass: the container
	// read as unhealthy for as long as it ran, and an upgrade waiting on the
	// check would wait until it gave up.
	t.Run("a loopback controller serving TLS is asked over https", func(t *testing.T) {
		srv := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			_, _ = w.Write([]byte(`{"ok":true}`))
		}))
		defer srv.Close()
		plain := "http://" + strings.TrimPrefix(srv.URL, "https://")

		e, out, errOut := newTestEnv(t)
		if code := dispatch(context.Background(), e, []string{"healthcheck", "--url", plain}); code != exitOK {
			t.Fatalf("exit code = %d, want 0: %s", code, errOut)
		}
		if !strings.Contains(out.String(), srv.URL+"/healthz is healthy") {
			t.Errorf("output = %q, want the https URL named", out)
		}
	})

	t.Run("nothing listening", func(t *testing.T) {
		e, _, errOut := newTestEnv(t)
		if code := dispatch(context.Background(), e, []string{"healthcheck", "--url", "http://127.0.0.1:1"}); code != exitError {
			t.Fatalf("exit code = %d, want %d", code, exitError)
		}
		if !strings.Contains(errOut.String(), "did not answer") {
			t.Errorf("output = %s", errOut)
		}
	})
}

// keyStore is an empty database, which is what a first run has: nothing is
// sealed, so a key may be generated.
func keyStore(t *testing.T) *store.Store {
	t.Helper()
	st, err := store.Open(context.Background(), store.Options{Path: ":memory:"})
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })
	return st
}

func TestEncryptionKeyIsGeneratedOnceAndReused(t *testing.T) {
	dir := isolateHost(t)
	cfg := config.Default()
	cfg.Security.EncryptionKeyFile = filepath.Join(dir, "encryption.key")

	ctx := context.Background()
	st := keyStore(t)
	log := discardLogger()
	first, err := loadOrCreateKey(ctx, st, cfg, log)
	if err != nil {
		t.Fatalf("generating: %v", err)
	}

	info, err := os.Stat(cfg.Security.EncryptionKeyFile)
	if err != nil {
		t.Fatalf("the key file was not written: %v", err)
	}
	// Windows has no mode bits to check: Go reports 0666 for every writable
	// file there, and what keeps another local user out is the directory's
	// ACL, which the installer sets and this test cannot see.
	if perm := info.Mode().Perm(); runtime.GOOS != "windows" && perm != 0o600 {
		t.Errorf("key file mode = %04o, want 0600: anything else lets another local user read it", perm)
	}

	second, err := loadOrCreateKey(ctx, st, cfg, log)
	if err != nil {
		t.Fatalf("reloading: %v", err)
	}
	if first.Encode() != second.Encode() {
		t.Error("a second start generated a different key; every sealed secret in the database would be unreadable")
	}
}

func TestEncryptionKeyFromTheEnvironmentIsUsedAsIs(t *testing.T) {
	dir := isolateHost(t)
	key, err := cryptox.GenerateKey()
	if err != nil {
		t.Fatal(err)
	}
	cfg := config.Default()
	cfg.Security.EncryptionKey = key.Encode()
	cfg.Security.EncryptionKeyFile = filepath.Join(dir, "encryption.key")

	got, err := loadOrCreateKey(context.Background(), keyStore(t), cfg, discardLogger())
	if err != nil {
		t.Fatal(err)
	}
	if got.Encode() != key.Encode() {
		t.Error("the configured key was not the one used")
	}
	if _, err := os.Stat(cfg.Security.EncryptionKeyFile); !os.IsNotExist(err) {
		t.Error("a key file was written even though the key came from the configuration")
	}
}

func TestUnusableEncryptionKeyNamesTheSetting(t *testing.T) {
	isolateHost(t)
	cfg := config.Default()
	cfg.Security.EncryptionKey = "not-a-key"

	_, err := loadOrCreateKey(context.Background(), keyStore(t), cfg, discardLogger())
	if err == nil {
		t.Fatal("a nonsense key was accepted")
	}
	if !strings.Contains(err.Error(), "security.encryption_key") {
		t.Errorf("the error does not name the setting: %v", err)
	}
}

// discardLogger keeps the key-generation warning out of the test output while
// still exercising the code path that emits it.
func discardLogger() *slog.Logger {
	return slog.New(slog.NewTextHandler(io.Discard, nil))
}

// secretShaped reports whether a `yaml` name reads like something that must
// never be printed. A path to a secret is not a secret: an operator debugging
// a deployment needs to see which file the key is read from, and printing that
// discloses nothing, so anything ending in _file is deliberately out.
//
// The word list is the weak point, and agent.registry_auth is what proved it:
// a base64 registry credential whose name holds none of secret, token, key or
// password, so this test called it harmless and `config print` disclosed it in
// full, as did every backup manifest. auth and credential are here for that.
// The lesson generalises past the two words -- a credential is not obliged to
// be named like one -- so a new secret-bearing field is worth a thought here
// rather than a hope that its name happens to match.
func secretShaped(name string) bool {
	if strings.HasSuffix(name, "_file") {
		return false
	}
	for _, word := range []string{"secret", "token", "key", "password", "passphrase", "auth", "credential"} {
		if strings.Contains(name, word) {
			return true
		}
	}
	return false
}

// blankSecrets is a hand-written list of fields, and the capacity-demand
// signing secret shows what that costs: it was added to the configuration and
// not to the list, so `zoomies config print` disclosed it for as long as the
// feature has existed. Nobody notices a field that is missing from a list.
//
// So this test does not check the list. It walks the whole configuration by
// reflection, puts a distinctive value in every string field whose name reads
// like a secret, and asserts that none of those values survives the blanking
// anywhere in the output. A secret added tomorrow fails here on the day it is
// added, and a secret copied into some other field fails too, which checking
// the fields one by one would not catch.
func TestEverySecretShapedFieldIsBlanked(t *testing.T) {
	var cfg config.Config
	planted := map[string]string{}
	plant(t, reflect.ValueOf(&cfg).Elem(), "", planted)
	if len(planted) < 5 {
		t.Fatalf("the walk found %d secret-shaped fields, which is fewer than the configuration has: %v", len(planted), planted)
	}

	printed, err := yaml.Marshal(blankSecrets(&cfg))
	if err != nil {
		t.Fatalf("marshalling the blanked configuration: %v", err)
	}
	for path, value := range planted {
		if strings.Contains(string(printed), value) {
			t.Errorf("%s was printed in full; add it to blankSecrets", path)
		}
	}
	// And the operator can still tell that one is set, which is the whole
	// reason the placeholder is not an empty string.
	if !strings.Contains(string(printed), secretPlaceholder) {
		t.Errorf("nothing says a secret is configured:\n%s", printed)
	}
}

// plant fills every secret-shaped string field with a value naming its own
// path, so a failure says which field leaked rather than only that one did.
func plant(t *testing.T, v reflect.Value, prefix string, into map[string]string) {
	t.Helper()
	if v.Kind() != reflect.Struct {
		return
	}
	for i := range v.NumField() {
		f := v.Type().Field(i)
		if !f.IsExported() {
			continue
		}
		name, _, _ := strings.Cut(f.Tag.Get("yaml"), ",")
		if name == "" || name == "-" {
			continue
		}
		path := name
		if prefix != "" {
			path = prefix + "." + name
		}
		field := v.Field(i)
		switch field.Kind() {
		case reflect.Struct:
			plant(t, field, path, into)
		case reflect.Slice:
			// A list of structs is a place secrets hide from a walk that only
			// follows fields: backup.remotes carries an S3 secret and the
			// archive passphrase and was never entered. One element is enough
			// to stand for the list.
			if field.Type().Elem().Kind() == reflect.Struct {
				field.Set(reflect.MakeSlice(field.Type(), 1, 1))
				plant(t, field.Index(0), path+"[0]", into)
			}
		case reflect.String:
			if secretShaped(name) {
				value := "planted-secret-" + strings.ReplaceAll(path, ".", "-")
				field.SetString(value)
				into[path] = value
			}
		}
	}
}

// A restore that brought the database back and left the key behind is
// indistinguishable from a first run at the key file: no file, so generate
// one. The instance that produced would start, report itself healthy, and fail
// inside its first GitHub call with a decryption error nobody could connect to
// the restore that caused it.
func TestAMissingKeyOverASealedDatabaseIsRefusedAtStartup(t *testing.T) {
	dir := isolateHost(t)
	ctx := context.Background()
	st := keyStore(t)
	if err := st.CreateInstallation(ctx, &store.Installation{
		AppID: 1, InstallationID: 2, Target: "acme", TargetType: store.TargetOrg,
		PrivateKeyEnc: []byte("sealed with the key that was not restored"),
	}); err != nil {
		t.Fatalf("CreateInstallation: %v", err)
	}

	cfg := config.Default()
	cfg.Security.EncryptionKeyFile = filepath.Join(dir, "encryption.key")

	_, err := loadOrCreateKey(ctx, st, cfg, discardLogger())
	if err == nil {
		t.Fatal("a new key was generated over a database whose secrets only the old one opens")
	}
	// The message has to name the file to put back, because the operator
	// reading it is mid-restore and has the backup open.
	for _, want := range []string{cfg.Security.EncryptionKeyFile, "ZOOMIES_ENCRYPTION_KEY"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("the refusal does not mention %q: %v", want, err)
		}
	}
	if _, serr := os.Stat(cfg.Security.EncryptionKeyFile); !os.IsNotExist(serr) {
		t.Error("a key file was written anyway, so the next start would find one and read nothing")
	}
}

func TestOnlyALoopbackHealthCheckIsMovedToHTTPS(t *testing.T) {
	for in, want := range map[string]string{
		"http://127.0.0.1:8080/healthz": "https://127.0.0.1:8080/healthz",
		"http://[::1]:8080/healthz":     "https://[::1]:8080/healthz",
		"http://localhost:8080/healthz": "https://localhost:8080/healthz",
		// Off the host, plain HTTP is what the operator asked for, and a
		// certificate left unchecked there would be a real risk.
		"http://10.0.0.5:8080/healthz":       "",
		"http://zoomies.example.com/healthz": "",
		"https://127.0.0.1:8080/healthz":     "",
	} {
		got, ok := loopbackHTTPS(in)
		if ok != (want != "") || got != want {
			t.Errorf("loopbackHTTPS(%q) = %q, %v; want %q", in, got, ok, want)
		}
	}
}

// TestConfigPrintBlanksBackupRemoteSecretsWithoutMutatingTheConfig covers the
// one list of structs in the configuration.
//
// A backup remote carries the bucket's secret key and the passphrase that seals
// every offsite copy, so together they open the whole fleet's database, and
// `config print` is the command whose output gets pasted into an issue. The
// copy blankSecrets returns shares its slice with the configuration it was
// given, so blanking in place would also have blanked the live one.
func TestConfigPrintBlanksBackupRemoteSecretsWithoutMutatingTheConfig(t *testing.T) {
	cfg := config.Default()
	cfg.Backup.Remotes = []config.BackupRemote{{
		Name: "offsite", Endpoint: "https://s3.example.com", Bucket: "zoomies-backups",
		AccessKeyID: "AKIAEXAMPLE", SecretAccessKey: "bucket-secret-value", Passphrase: "archive-passphrase-value",
	}}

	for _, format := range []string{"yaml", "json"} {
		var printed []byte
		var err error
		if format == "yaml" {
			printed, err = yaml.Marshal(blankSecrets(cfg))
		} else {
			printed, err = json.Marshal(blankSecrets(cfg))
		}
		if err != nil {
			t.Fatalf("marshalling as %s: %v", format, err)
		}
		for _, leaked := range []string{"bucket-secret-value", "archive-passphrase-value", "AKIAEXAMPLE"} {
			if strings.Contains(string(printed), leaked) {
				t.Errorf("%s output printed %q:\n%s", format, leaked, printed)
			}
		}
		// What an operator debugging a destination needs is still there.
		for _, kept := range []string{"offsite", "https://s3.example.com", "zoomies-backups", secretPlaceholder} {
			if !strings.Contains(string(printed), kept) {
				t.Errorf("%s output lost %q:\n%s", format, kept, printed)
			}
		}
	}

	got := cfg.Backup.Remotes[0]
	if got.SecretAccessKey != "bucket-secret-value" || got.Passphrase != "archive-passphrase-value" || got.AccessKeyID != "AKIAEXAMPLE" {
		t.Errorf("blankSecrets blanked the caller's configuration as well: %+v", got)
	}
}

package main

import (
	"context"
	"errors"
	"fmt"
	"text/tabwriter"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/cryptox"
	"github.com/eyupio/zoomies/internal/installer"
	"github.com/eyupio/zoomies/internal/store"
)

// `zoomies config get|set|unset|list`: the fleet's settings, from a terminal.
//
// The settings page is where these are normally changed. This exists for the
// two moments when it is not reachable: a stored value that stops the
// controller starting, and a stored value that binds it somewhere nobody can
// get to. Both are recoverable through an environment variable, which is the
// layer above the database -- but a variable is a workaround that has to be
// remembered at every restart, and this is the fix.
//
// It works on a stopped controller. A running one holds the database lock, and
// writing settings under a process that has already read them would leave that
// process and the row disagreeing with no way for either to know.

// openForSettings loads the configuration far enough to open the database and
// the key that unseals what is in it, which is all these commands need.
func openForSettings(ctx context.Context, cfgPath string) (*config.Config, *store.Store, *cryptox.Key, func(), error) {
	cfg, err := config.Load(cfgPath)
	if err != nil {
		return nil, nil, nil, nil, err
	}
	unlock, err := store.Lock(cfg.Database.Path)
	if err != nil {
		if errors.Is(err, store.ErrLocked) {
			return nil, nil, nil, nil, fmt.Errorf(
				"a controller is running against %s, and it has already read the settings this would change; "+
					"stop it first, or change the setting on the settings page", cfg.Database.Path)
		}
		return nil, nil, nil, nil, err
	}
	st, err := store.Open(ctx, store.Options{Path: cfg.Database.Path})
	if err != nil {
		_ = unlock()
		return nil, nil, nil, nil, err
	}
	// A missing key is not fatal here: everything but a credential can still be
	// read and written without one, and refusing the whole command would take
	// away the tool somebody uses when the key is the thing that is wrong.
	key, _ := cfg.ResolveEncryptionKey()
	return cfg, st, key, func() { st.Close(); _ = unlock() }, nil
}

// effective assembles the configuration the way the controller does, so these
// commands answer about what a controller would actually run rather than about
// one layer of it.
func effective(ctx context.Context, cfg *config.Config, st *store.Store, key *cryptox.Key) ([]store.InstanceSetting, error) {
	rows, err := st.InstanceSettings(ctx)
	if err != nil {
		return nil, err
	}
	if _, err := cfg.Rebuild(rows, key); err != nil {
		return nil, err
	}
	return rows, nil
}

func runConfigList(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies config list [--config path] [--all]",
		"List what this fleet has stored. --all lists every setting, including the ones nobody has changed.")
	cfgPath := fs.String("config", "", "path to zoomies.yaml (default: "+config.DefaultConfigFile()+")")
	all := fs.Bool("all", false, "list every setting, not only the ones with a value")
	fs.example("zoomies config list", "zoomies config list --all")
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}

	cfg, st, key, done, err := openForSettings(ctx, *cfgPath)
	if err != nil {
		return err
	}
	defer done()
	if _, err := effective(ctx, cfg, st, key); err != nil {
		return err
	}

	w := tabwriter.NewWriter(e.out, 0, 0, 2, ' ', 0)
	fmt.Fprintln(w, "SETTING\tVALUE\tFROM")
	shown := 0
	for _, s := range config.Settings() {
		source := cfg.Source(s.Key)
		if !*all && source == config.SourceDefault {
			continue
		}
		value, err := cfg.Value(s.Key)
		if err != nil {
			continue
		}
		text := config.Text(s, value)
		if s.Secret {
			text = secretPlaceholder
			if text == "" {
				text = "(not set)"
			}
		}
		if text == "" {
			text = "(not set)"
		}
		fmt.Fprintf(w, "%s\t%s\t%s\n", s.Key, text, source)
		shown++
	}
	if err := w.Flush(); err != nil {
		return err
	}
	if shown == 0 {
		fmt.Fprintln(e.out, "Nothing is set: this fleet is running on the defaults.")
	}
	return nil
}

func runConfigGet(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies config get <key> [--config path]",
		"Print one setting's effective value, and which layer it came from.")
	cfgPath := fs.String("config", "", "path to zoomies.yaml (default: "+config.DefaultConfigFile()+")")
	fs.example("zoomies config get server.bind")
	if err := fs.parse(args); err != nil {
		return err
	}
	key, err := fs.oneArg("a setting, for example server.bind")
	if err != nil {
		return err
	}
	setting, ok := config.LookupSetting(key)
	if !ok {
		return usagef("config get", "%q is not a setting this version has; `zoomies config list --all` lists them", key)
	}

	cfg, st, encKey, done, err := openForSettings(ctx, *cfgPath)
	if err != nil {
		return err
	}
	defer done()
	if _, err := effective(ctx, cfg, st, encKey); err != nil {
		return err
	}

	value, err := cfg.Value(key)
	if err != nil {
		return err
	}
	if setting.Secret {
		if config.Text(setting, value) == "" {
			fmt.Fprintln(e.out, "(not set)")
		} else {
			fmt.Fprintln(e.out, secretPlaceholder)
		}
	} else {
		fmt.Fprintln(e.out, config.Text(setting, value))
	}
	fmt.Fprintf(e.err, "%s -- %s\nfrom: %s\n", setting.Label, setting.Summary, sourceSentence(cfg, setting))
	return nil
}

// sourceSentence says where a value came from in a way that names what to
// change, because "environment" on its own leaves somebody looking for which
// variable.
func sourceSentence(cfg *config.Config, s config.Setting) string {
	switch cfg.Source(s.Key) {
	case config.SourceEnvironment:
		return s.Env + " in the environment, which overrides both the database and the file"
	case config.SourceDatabase:
		return "this fleet's database"
	case config.SourceFile:
		if p := cfg.Path(); p != "" {
			return p
		}
		return "the configuration file"
	default:
		return "the built-in default"
	}
}

func runConfigSet(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies config set <key> <value> [--config path]",
		"Store one setting in this fleet's database. The controller must be stopped.")
	cfgPath := fs.String("config", "", "path to zoomies.yaml (default: "+config.DefaultConfigFile()+")")
	fs.example(
		"zoomies config set server.bind 127.0.0.1:8080",
		"zoomies config set oidc.scopes openid,profile,email",
	)
	if err := fs.parse(args); err != nil {
		return err
	}
	rest, err := fs.atLeastOneArg("a setting and its value, for example server.bind 127.0.0.1:8080")
	if err != nil {
		return err
	}
	if len(rest) != 2 {
		return usagef("config set", "takes a setting and one value; quote a value that contains spaces")
	}
	key, raw := rest[0], rest[1]

	setting, ok := config.LookupSetting(key)
	if !ok {
		return usagef("config set", "%q is not a setting this version has; `zoomies config list --all` lists them", key)
	}
	if !setting.Stored() {
		return usagef("config set", "%s cannot live in the database -- %s; set it in the configuration file or as %s",
			key, scopeReason(setting), setting.Env)
	}

	cfg, st, encKey, done, err := openForSettings(ctx, *cfgPath)
	if err != nil {
		return err
	}
	defer done()
	if _, err := effective(ctx, cfg, st, encKey); err != nil {
		return err
	}

	// Parsed against a copy first, so a value that will not do stops here
	// rather than in the next start.
	candidate := *cfg
	candidate.SetSources(cfg.Sources())
	if _, err := candidate.SetValueString(key, raw); err != nil {
		return err
	}
	parsed, err := candidate.Value(key)
	if err != nil {
		return err
	}
	row, err := config.EncodeStored(setting, parsed, encKey)
	if err != nil {
		return err
	}
	if err := st.PutInstanceSettings(ctx, "zoomies config set", []store.InstanceSetting{row}); err != nil {
		return err
	}

	fmt.Fprintf(e.out, "%s is now %s.\n", setting.Key, displayFor(setting, parsed))
	if cfg.Source(key) == config.SourceEnvironment {
		fmt.Fprintf(e.err, "It will not take effect while %s is set in the environment, which overrides the database.\n", setting.Env)
	} else if !setting.Live {
		fmt.Fprintln(e.err, "It takes effect when the controller next starts.")
	}
	return nil
}

func runConfigUnset(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies config unset <key> [--config path]",
		"Forget a stored setting, so the configuration file or the built-in default decides it again.")
	cfgPath := fs.String("config", "", "path to zoomies.yaml (default: "+config.DefaultConfigFile()+")")
	fs.example("zoomies config unset server.bind")
	if err := fs.parse(args); err != nil {
		return err
	}
	key, err := fs.oneArg("a setting, for example server.bind")
	if err != nil {
		return err
	}
	if _, ok := config.LookupSetting(key); !ok {
		return usagef("config unset", "%q is not a setting this version has; `zoomies config list` lists what is stored", key)
	}

	_, st, _, done, err := openForSettings(ctx, *cfgPath)
	if err != nil {
		return err
	}
	defer done()

	if _, err := st.GetInstanceSetting(ctx, key); errors.Is(err, store.ErrNotFound) {
		fmt.Fprintf(e.out, "%s was not stored, so nothing changed.\n", key)
		return nil
	} else if err != nil {
		return err
	}
	if err := st.DeleteInstanceSettings(ctx, []string{key}); err != nil {
		return err
	}
	fmt.Fprintf(e.out, "%s is no longer stored; the configuration file or the built-in default decides it now.\n", key)
	return nil
}

func scopeReason(s config.Setting) string {
	switch s.Scope {
	case config.ScopeBootstrap:
		return "it is read before the database can be opened"
	case config.ScopeLocal:
		return "it belongs to a standalone agent's own host"
	default:
		return "it is not a setting this fleet stores"
	}
}

func displayFor(s config.Setting, value any) string {
	if s.Secret {
		return secretPlaceholder
	}
	text := config.Text(s, value)
	if text == "" {
		return "empty"
	}
	return text
}

// runConfigImportEnv stores every setting an environment file sets, in one
// write.
//
// It is how a container deployment's settings leave its .env: the installer
// runs it in a one-off container of the new image, against the deployment's
// volume, with the variables on standard input -- never as arguments, which
// any process on the host can read. It is also the command an operator runs
// by hand on an .env of their own. Anything in the file that cannot live in
// the database -- the encryption key, the database path, Compose's own
// variables -- is left alone and named, so nothing is silently dropped.
func runConfigImportEnv(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies config import-env [file] [--config path]",
		"Store the settings an environment file sets in this fleet's database. Reads standard input when no file, or -, is given. The controller must be stopped.")
	cfgPath := fs.String("config", "", "path to zoomies.yaml (default: "+config.DefaultConfigFile()+")")
	fs.example("zoomies config import-env /opt/zoomies/.env", "zoomies config import-env < .env")
	if err := fs.parse(args); err != nil {
		return err
	}
	rest := fs.Args()
	if len(rest) > 1 {
		return usagef("config import-env", "takes at most one file")
	}
	var vars map[string]string
	var err error
	if len(rest) == 0 || rest[0] == "-" {
		if e.in == nil {
			return usagef("config import-env", "give a file, or the variables on standard input")
		}
		vars, err = installer.ParseEnv(e.in)
	} else {
		vars, err = installer.ParseEnvFile(rest[0])
	}
	if err != nil {
		return err
	}

	_, st, encKey, done, err := openForSettings(ctx, *cfgPath)
	if err != nil {
		return err
	}
	defer done()

	rows, imported, left, err := config.ImportEnvironment(vars, encKey)
	if err != nil {
		return err
	}
	if len(rows) > 0 {
		if err := st.PutInstanceSettings(ctx, "zoomies config import-env", rows); err != nil {
			return err
		}
	}
	for _, im := range imported {
		value := im.Text
		switch {
		case im.Setting.Secret:
			value = secretPlaceholder
		case value == "":
			value = "empty"
		}
		fmt.Fprintf(e.out, "%s is now %s (from %s)\n", im.Setting.Key, value, im.Env)
	}
	for _, name := range left {
		fmt.Fprintf(e.err, "left %s where it is: it is not a setting this fleet stores\n", name)
	}
	if len(imported) == 0 {
		fmt.Fprintln(e.out, "Nothing to store: the file sets no setting that lives in the database.")
	}
	return nil
}

package main

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/cryptox"
)

// settingsHost prepares a state directory with a configuration file, so a test
// can run `zoomies config …` against a real database the way an operator does.
func settingsHost(t *testing.T, body string) string {
	t.Helper()
	dir := isolateHost(t)
	path := filepath.Join(dir, "zoomies.yaml")
	if err := os.WriteFile(path, []byte(body), 0o600); err != nil {
		t.Fatalf("writing %s: %v", path, err)
	}
	t.Setenv("ZOOMIES_STATE_DIR", dir)
	t.Setenv("ZOOMIES_CONFIG_DIR", dir)
	return path
}

// The command an operator reaches for when the settings page is the thing that
// is broken: a stored bind address nothing can connect to.
//
// It is the fix rather than the workaround. The environment layer already wins
// over the database, so a bad value is always recoverable by exporting a
// variable -- but a variable has to be remembered at every restart, and this
// puts the database right.
func TestConfigSetStoresASettingWithoutAControllerRunning(t *testing.T) {
	path := settingsHost(t, "database:\n  path: "+filepath.Join(t.TempDir(), "z.db")+"\n")
	ctx := context.Background()

	e, out, _ := newTestEnv(t)
	if err := runConfigSet(ctx, e, []string{"server.bind", "127.0.0.1:9999", "--config", path}); err != nil {
		t.Fatalf("config set: %v", err)
	}
	if !strings.Contains(out.String(), "server.bind is now 127.0.0.1:9999") {
		t.Errorf("config set said: %q", out.String())
	}

	e, out, _ = newTestEnv(t)
	if err := runConfigGet(ctx, e, []string{"server.bind", "--config", path}); err != nil {
		t.Fatalf("config get: %v", err)
	}
	if got := strings.TrimSpace(out.String()); got != "127.0.0.1:9999" {
		t.Errorf("config get printed %q", got)
	}

	e, out, _ = newTestEnv(t)
	if err := runConfigUnset(ctx, e, []string{"server.bind", "--config", path}); err != nil {
		t.Fatalf("config unset: %v", err)
	}
	if !strings.Contains(out.String(), "no longer stored") {
		t.Errorf("config unset said: %q", out.String())
	}
}

// A key that is read before the database opens cannot be stored in it, and the
// refusal says where to put it instead -- because an operator who has just been
// told "no" is about to go looking for the right place.
func TestConfigSetRefusesAKeyThatOpensTheDatabase(t *testing.T) {
	path := settingsHost(t, "database:\n  path: "+filepath.Join(t.TempDir(), "z.db")+"\n")

	e, _, _ := newTestEnv(t)
	err := runConfigSet(context.Background(), e, []string{"database.path", "/tmp/elsewhere.db", "--config", path})
	if err == nil {
		t.Fatal("database.path was stored in the database it names")
	}
	for _, want := range []string{"before the database can be opened", "ZOOMIES_DB_PATH"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("the refusal does not mention %q: %v", want, err)
		}
	}
}

// A value that will not parse stops at the command rather than at the next
// start, when whoever typed it is no longer watching.
func TestConfigSetRefusesAValueThatWillNotParse(t *testing.T) {
	path := settingsHost(t, "database:\n  path: "+filepath.Join(t.TempDir(), "z.db")+"\n")

	e, _, _ := newTestEnv(t)
	err := runConfigSet(context.Background(), e, []string{"scheduler.interval", "soon", "--config", path})
	if err == nil {
		t.Fatal("a nonsense duration was stored")
	}
	if !strings.Contains(err.Error(), "is not a duration") {
		t.Errorf("the refusal does not say what was wrong: %v", err)
	}
}

// The listing says where each value came from, which is the question that
// makes a configuration problem hard: a value in the file and a value in the
// environment are identical once the process is running.
func TestConfigListSaysWhereEachValueCameFrom(t *testing.T) {
	path := settingsHost(t, "database:\n  path: "+filepath.Join(t.TempDir(), "z.db")+
		"\nscheduler:\n  interval: 25s\n")
	ctx := context.Background()

	e, _, _ := newTestEnv(t)
	if err := runConfigSet(ctx, e, []string{"retention.jobs", "720h", "--config", path}); err != nil {
		t.Fatalf("config set: %v", err)
	}

	t.Setenv("ZOOMIES_LOG_LEVEL", "debug")
	e, out, _ := newTestEnv(t)
	if err := runConfigList(ctx, e, []string{"--config", path}); err != nil {
		t.Fatalf("config list: %v", err)
	}
	text := out.String()
	for _, want := range []string{
		"scheduler.interval", "25s", "file",
		"retention.jobs", "720h", "database",
		"log.level", "debug", "environment",
	} {
		if !strings.Contains(text, want) {
			t.Errorf("the listing does not mention %q:\n%s", want, text)
		}
	}
}

// A credential is never printed, and the listing still says one is set --
// which is the fact an operator debugging a configuration actually needs.
func TestConfigCommandsNeverPrintACredential(t *testing.T) {
	dir := t.TempDir()
	keyFile := filepath.Join(dir, "encryption.key")
	key, err := cryptox.GenerateKey()
	if err != nil {
		t.Fatalf("GenerateKey: %v", err)
	}
	if err := cryptox.WriteKeyFile(keyFile, key); err != nil {
		t.Fatalf("WriteKeyFile: %v", err)
	}
	path := settingsHost(t, "database:\n  path: "+filepath.Join(dir, "z.db")+
		"\nsecurity:\n  encryption_key_file: "+keyFile+"\n")
	ctx := context.Background()

	e, _, _ := newTestEnv(t)
	if err := runConfigSet(ctx, e, []string{"capacity_demand.signing_secret", "hunter2", "--config", path}); err != nil {
		t.Fatalf("config set: %v", err)
	}

	for _, run := range []func() string{
		func() string {
			e, out, _ := newTestEnv(t)
			_ = runConfigList(ctx, e, []string{"--config", path})
			return out.String()
		},
		func() string {
			e, out, _ := newTestEnv(t)
			_ = runConfigGet(ctx, e, []string{"capacity_demand.signing_secret", "--config", path})
			return out.String()
		},
	} {
		text := run()
		if strings.Contains(text, "hunter2") {
			t.Errorf("a credential was printed:\n%s", text)
		}
		if !strings.Contains(text, secretPlaceholder) {
			t.Errorf("nothing says the credential is set:\n%s", text)
		}
	}
}

// Setting a credential before there is a key to seal it with is refused, and
// the refusal says what to do. Generating a key here would be the wrong tool
// doing it: only the controller knows whether the database already holds
// something sealed with a different one, and minting a second key over that
// leaves an instance that starts, looks healthy, and cannot read its own
// GitHub credentials.
func TestConfigSetRefusesACredentialWithNoKeyToSealItWith(t *testing.T) {
	path := settingsHost(t, "database:\n  path: "+filepath.Join(t.TempDir(), "z.db")+"\n")

	e, _, _ := newTestEnv(t)
	err := runConfigSet(context.Background(), e,
		[]string{"capacity_demand.signing_secret", "hunter2", "--config", path})
	if err == nil {
		t.Fatal("a credential was stored with nothing to seal it")
	}
	if !strings.Contains(err.Error(), "encryption key") {
		t.Errorf("the refusal does not name what is missing: %v", err)
	}
}

// The upgrade hands a deployment's variables to a one-off container on
// standard input, and this is what stores them. Every setting lands in the
// database; the variables that cannot live there are named and left.
func TestConfigImportEnvStoresWhatAnEnvFileSets(t *testing.T) {
	path := settingsHost(t, "database:\n  path: "+filepath.Join(t.TempDir(), "z.db")+"\n")
	ctx := context.Background()

	e, out, errOut := newTestEnv(t)
	e.in = strings.NewReader("ZOOMIES_BIND=0.0.0.0:8080\nZOOMIES_AGENT_CAPACITY=6\nZOOMIES_IMAGE=ghcr.io/eyupio/zoomies:v1\nDOCKER_GID=998\n")
	if err := runConfigImportEnv(ctx, e, []string{"--config", path}); err != nil {
		t.Fatalf("config import-env: %v", err)
	}
	for _, want := range []string{"server.bind is now 0.0.0.0:8080 (from ZOOMIES_BIND)", "agent.capacity is now 6 (from ZOOMIES_AGENT_CAPACITY)"} {
		if !strings.Contains(out.String(), want) {
			t.Errorf("output does not say %q:\n%s", want, out.String())
		}
	}
	if !strings.Contains(errOut.String(), "left ZOOMIES_IMAGE") || strings.Contains(errOut.String(), "DOCKER_GID") {
		t.Errorf("stderr = %q, want ZOOMIES_IMAGE named and Compose's own variables not", errOut.String())
	}

	e, out, _ = newTestEnv(t)
	if err := runConfigGet(ctx, e, []string{"agent.capacity", "--config", path}); err != nil {
		t.Fatalf("config get: %v", err)
	}
	if got := strings.TrimSpace(out.String()); got != "6" {
		t.Errorf("agent.capacity = %q after the import, want 6", got)
	}
}

// One value the controller could not run with stores nothing at all.
func TestConfigImportEnvStoresNothingWhenAValueIsWrong(t *testing.T) {
	path := settingsHost(t, "database:\n  path: "+filepath.Join(t.TempDir(), "z.db")+"\n")
	ctx := context.Background()

	e, _, _ := newTestEnv(t)
	e.in = strings.NewReader("ZOOMIES_BIND=0.0.0.0:8080\nZOOMIES_AGENT_CAPACITY=lots\n")
	if err := runConfigImportEnv(ctx, e, []string{"--config", path}); err == nil || !strings.Contains(err.Error(), "ZOOMIES_AGENT_CAPACITY") {
		t.Fatalf("err = %v, want a refusal naming the variable", err)
	}
	e, out, _ := newTestEnv(t)
	if err := runConfigList(ctx, e, []string{"--config", path}); err != nil {
		t.Fatal(err)
	}
	if strings.Contains(out.String(), "server.bind") {
		t.Errorf("server.bind was stored although the import was refused:\n%s", out.String())
	}
}

package main

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"os"
	"os/signal"
	"path/filepath"
	"strings"
	"sync"
	"syscall"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/api"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/backup"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/cryptox"
	"github.com/eyupio/zoomies/internal/hosttune"
	"github.com/eyupio/zoomies/internal/logging"
	"github.com/eyupio/zoomies/internal/provider"
	"github.com/eyupio/zoomies/internal/provider/proxmox"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/version"
)

// stopGrace must outlast the embedded agent's admitted create, cleanup and
// result reporting. Exiting sooner can strand a DinD sidecar halfway through
// creation. Existing CI jobs keep running; only lifecycle tasks are awaited.
const stopGrace = agent.ShutdownTimeout + time.Minute

// runController is `zoomies controller`: the control plane, the API, the UI,
// the webhook endpoint and -- unless agent.embedded is false -- an agent.
func runController(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies controller [--config path]",
		"Run the control plane: the scheduler, the API, the web UI and the webhook endpoint.")
	cfgPath := fs.String("config", "", "path to zoomies.yaml (default: "+config.DefaultConfigFile()+", and a missing file is not an error)")
	takeover := fs.Bool("takeover", false, "start even though another controller holds this database's lease, and take it from them")
	fs.example(
		"zoomies controller --config /etc/zoomies/zoomies.yaml",
		"ZOOMIES_BIND=0.0.0.0:8080 zoomies controller     # no file at all: defaults plus environment",
	)
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}

	cfg, err := config.Load(*cfgPath)
	if err != nil {
		return err
	}

	// The configuration is not validated yet, and cannot be: most of it lives
	// in the database, and the database is not open. What Load has produced so
	// far is enough to open it -- the path, and the key that unseals what is
	// inside -- and the whole configuration is assembled and checked below,
	// once both are in hand. A file that fails to parse still stops here,
	// because that is a fault in the one layer this early step does read.

	log, level := setupLogging(cfg)
	startFormat := cfg.Log.Format

	// One controller per database, checked before the store opens.
	//
	// Two schedulers over one database both mint runner credentials, both
	// reclaim hosts they think are lost, and both reap the workloads the other
	// created; every symptom of it looks like a bug somewhere else. The lock
	// catches a second process on this host and the lease catches a copy on a
	// shared filesystem or another machine, which no lock here can see.
	unlock, err := store.Lock(cfg.Database.Path)
	if err != nil {
		if errors.Is(err, store.ErrLocked) {
			return fmt.Errorf("another controller is already running against %s on this host; "+
				"stop it before starting this one", cfg.Database.Path)
		}
		return err
	}
	defer func() { _ = unlock() }()

	// A restore staged from the settings page is applied here, in the gap
	// between the last controller closing the database and this one opening
	// it. The lock above is what makes the gap real: nothing else has the
	// file. Whatever the outcome, this controller then starts -- on the
	// restored database, or on the one it had, with the reason recorded for
	// the page to show.
	if err := applyStagedRestore(ctx, cfg, log); err != nil {
		return err
	}

	st, err := store.Open(ctx, store.Options{Path: cfg.Database.Path})
	if err != nil {
		return err
	}
	defer st.Close()

	lease, err := takeControllerLease(ctx, st, *takeover)
	if err != nil {
		return err
	}
	defer func() {
		// Handed back on a clean stop so the next controller starts at once
		// rather than waiting out a lease nobody holds.
		if err := st.ReleaseControllerLease(context.WithoutCancel(ctx), lease.Holder); err != nil {
			log.Warn("could not hand the controller lease back", "error", err)
		}
	}()

	key, err := loadOrCreateKey(ctx, st, cfg, log)
	if err != nil {
		return err
	}

	// Now the whole configuration exists: the file underneath, this fleet's
	// own settings over it, and the environment over both. Everything from
	// here reads the assembled thing.
	seeded, err := seedSettingsFromFile(ctx, st, cfg, key, log)
	if err != nil {
		return err
	}
	stored, err := st.InstanceSettings(ctx)
	if err != nil {
		return err
	}
	storedFindings, err := cfg.Rebuild(stored, key)
	if err != nil {
		return err
	}
	applyLogLevel(level, cfg)
	if cfg.Log.Format != startFormat {
		// The format is chosen before the database is open, so one stored
		// there -- where a container deployment keeps it -- takes over here,
		// from the first line that says what the configuration is.
		log, level = setupLogging(cfg)
	}

	log.Info("configuration assembled",
		"file", configSource(cfg), "stored", len(stored), "pinned_by_environment", len(cfg.PinnedByEnvironment()))

	findings := append(storedFindings, seeded...)
	findings = append(findings, cfg.Validate()...)
	printFindings(e.err, findings)
	if err := findings.Err(); err != nil {
		return err
	}

	// The registry is built only for an embedded agent. A controller that runs
	// no runners itself has no business probing this host's Docker socket, and
	// building one anyway would produce backend warnings about a host that is
	// never going to start a container.
	var backends *backend.Registry
	if cfg.Agent.Embedded {
		backends, err = buildBackends(ctx, cfg, log)
		if err != nil {
			return err
		}
	}

	providers, err := buildProviders()
	if err != nil {
		return err
	}

	health := hosttune.LocalOptions(cfg.Agent.WorkDir)
	health.DockerHost = cfg.Agent.DockerHost
	health.HostReportPath = filepath.Join(config.SharedDir(), "host-health", "report.json")
	ctrl, err := controller.New(controller.Options{
		Doctor:    hosttune.NewMonitor(hosttune.New(health)),
		Store:     st,
		Config:    cfg,
		Key:       key,
		Backends:  backends,
		Providers: providers,
		Logger:    log,
		LogLevel:  level,
		Lease:     lease,
	})
	if err != nil {
		return err
	}

	srv, err := api.New(api.Options{Controller: ctrl, Logger: log})
	if err != nil {
		return err
	}

	// SIGHUP re-reads the log level and nothing else. Everything else in the
	// configuration is either safe to change through PATCH /settings or needs
	// the process restarted, and pretending otherwise -- rebinding a listener
	// under live connections, say -- is how a reload becomes an outage. The
	// level goes through the controller's live configuration, the same way a
	// PATCH does, so the settings page shows the level the process is at.
	stopHUP := watchSIGHUP(ctx, *cfgPath, func(level string) string {
		var previous string
		ctrl.UpdateConfig(func(c *config.Config) { previous, c.Log.Level = c.Log.Level, level })
		return previous
	}, log)
	defer stopHUP()

	if err := ctrl.Start(ctx); err != nil {
		return err
	}
	// Stop runs on every path out, including a failed listen. It shuts the
	// loops down without touching a single runner: restarting a controller
	// must never kill somebody's build.
	defer func() {
		shutdownCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), stopGrace)
		defer cancel()
		if err := ctrl.Stop(shutdownCtx); err != nil {
			log.Warn("the controller did not shut down cleanly", "error", err)
		}
	}()

	if cfg.Agent.Embedded {
		if err := ctrl.StartEmbeddedAgent(ctx, cfg); err != nil {
			return fmt.Errorf("starting the embedded agent: %w (set agent.embedded to false to run a controller that hosts no runners)", err)
		}
	}

	printBanner(e.out, cfg, backends)
	// The environment's first account is made before the setup token is
	// considered, so an instance that bootstrapped itself never prints a
	// token nobody needs.
	if err := ctrl.BootstrapFromEnvironment(ctx); err != nil {
		return err
	}
	printSetupToken(ctx, e.out, ctrl, log)

	// The settings page can ask this process to stop so that its service
	// manager starts the next one, which is how a staged restore is applied.
	// The request cancels the listener's context exactly as a signal would,
	// and the exit code says which it was.
	serveCtx, stopServing := context.WithCancel(ctx)
	defer stopServing()
	go func() {
		select {
		case <-ctrl.RestartRequested():
			stopServing()
		case <-serveCtx.Done():
		}
	}()
	err = srv.ListenAndServe(serveCtx)
	if restarting, reason := ctrl.Restarting(); restarting {
		if err != nil {
			log.Warn("the listener did not stop cleanly on the way to a restart", "error", err)
		}
		return &restartRequested{reason: reason}
	}
	return err
}

// applyStagedRestore performs the restore the settings page staged, if there
// is one, and says what happened in the log -- loudly, because a database
// changing hands is the one startup event an operator reading the log later
// must not be able to miss.
func applyStagedRestore(ctx context.Context, cfg *config.Config, log *slog.Logger) error {
	staged, err := backup.LoadStaged(cfg.Database.Path)
	if err != nil {
		return err
	}
	if staged == nil {
		return nil
	}
	log.Warn("applying a restore staged from the settings page", "restore", describeStaged(staged))
	outcome, err := backup.ApplyStaged(ctx, cfg, nil)
	if err != nil {
		return err
	}
	if outcome == nil {
		return nil
	}
	if !outcome.OK {
		log.Error("the staged restore did not finish; the error says which database this controller is starting on",
			"backup", outcome.BackupID, "error", outcome.Error,
			"fix", "put right what the error names and stage the restore again from the Backups tab")
		return nil
	}
	log.Warn("restored the database from a backup; this fleet is fenced until an administrator lifts it",
		"backup", outcome.BackupID, "moved_aside", outcome.Report.MovedAside)
	for _, line := range outcome.Report.Invalidated {
		log.Info(line)
	}
	return nil
}

// restartRequested is the error a controller returns when it stopped because
// the settings page asked it to: not a failure, but not a clean exit either,
// because a service manager set to restart on failure has to see a non-zero
// code to bring it back.
type restartRequested struct{ reason string }

func (e *restartRequested) Error() string {
	return "stopped for a restart: " + e.reason
}

// takeControllerLease claims this database for this controller, or refuses to
// start and says who has it.
//
// The message is the whole point of the lease: an operator who has just been
// refused needs to know which machine to go and look at, and "the database is
// locked" would send them to the wrong one.
func takeControllerLease(ctx context.Context, st *store.Store, takeover bool) (*store.ControllerLease, error) {
	host, _ := os.Hostname()
	lease := &store.ControllerLease{
		Holder:  store.NewID(store.PrefixController),
		Host:    host,
		PID:     os.Getpid(),
		Version: version.Version,
	}
	held, err := st.AcquireControllerLease(ctx, lease, controller.LeaseTTL, takeover)
	if errors.Is(err, store.ErrConflict) {
		return nil, fmt.Errorf("another controller holds this database: %s, last seen %s ago. "+
			"Stop it, or start this one with --takeover if you know it is gone",
			held.Describe(), time.Since(held.RenewedAt).Round(time.Second))
	}
	if err != nil {
		return nil, fmt.Errorf("taking the controller lease: %w", err)
	}
	return lease, nil
}

// ---------------------------------------------------------------------------
// Logging
// ---------------------------------------------------------------------------

// setupLogging installs the process logger and returns the level it is filtered
// at, so that SIGHUP can move it without rebuilding every logger the controller
// and the API have already captured.
// applyLogLevel re-tunes the gate after the configuration has been assembled.
//
// The level is set once before the store opens, because the store's own startup
// has things to say and there is nowhere else to say them. That first setting
// can only know the file and the environment, so it has to be made again once
// the layer between them has been read -- otherwise the one setting the
// registry calls live is the one a fresh start ignores.
func applyLogLevel(level *slog.LevelVar, cfg *config.Config) {
	level.Set(config.ParseLogLevel(cfg.Log.Level))
}

func setupLogging(cfg *config.Config) (*slog.Logger, *slog.LevelVar) {
	level := new(slog.LevelVar)
	level.Set(config.ParseLogLevel(cfg.Log.Level))

	// The inner handler is built at debug so that it never filters anything
	// out itself; the wrapper below is the only gate, and it is the one whose
	// mind can be changed at runtime.
	inner := logging.Setup(logging.Options{Level: "debug", Format: cfg.Log.Format}).Handler()
	log := slog.New(&levelHandler{Handler: inner, level: level})
	slog.SetDefault(log)
	return log, level
}

// levelHandler gates a handler on a level that can change while the process
// runs. slog.HandlerOptions.Level accepts a Leveler for exactly this, but the
// handler underneath is built by internal/logging, which owns the redaction
// rules; wrapping is how both stay true.
type levelHandler struct {
	slog.Handler
	level *slog.LevelVar
}

func (h *levelHandler) Enabled(_ context.Context, l slog.Level) bool { return l >= h.level.Level() }

func (h *levelHandler) WithAttrs(attrs []slog.Attr) slog.Handler {
	return &levelHandler{Handler: h.Handler.WithAttrs(attrs), level: h.level}
}

func (h *levelHandler) WithGroup(name string) slog.Handler {
	return &levelHandler{Handler: h.Handler.WithGroup(name), level: h.level}
}

// watchSIGHUP re-reads the configuration on SIGHUP and hands the log level from
// it to apply, which sets it and returns the level that was in force. It
// returns a function that stops watching.
func watchSIGHUP(ctx context.Context, cfgPath string, apply func(level string) (previous string), log *slog.Logger) func() {
	hup := make(chan os.Signal, 1)
	signal.Notify(hup, syscall.SIGHUP)

	var once sync.Once
	stop := func() { once.Do(func() { signal.Stop(hup); close(hup) }) }

	go func() {
		for {
			select {
			case <-ctx.Done():
				return
			case _, ok := <-hup:
				if !ok {
					return
				}
				fresh, err := config.Load(cfgPath)
				if err != nil {
					log.Error("SIGHUP: the configuration did not re-read, so nothing changed",
						"error", err, "fix", "correct the file and send SIGHUP again")
					continue
				}
				was := config.ParseLogLevel(apply(fresh.Log.Level))
				now := config.ParseLogLevel(fresh.Log.Level)
				if was == now {
					log.Info("SIGHUP: log level re-read and unchanged", "log_level", now.String())
				} else {
					// Logged at the new level's own severity would risk the
					// message being filtered out; Info is always visible at
					// debug and info, and Warn covers the rest.
					log.Warn("SIGHUP: log level changed", "from", was.String(), "to", now.String())
				}
			}
		}
	}()
	return stop
}

// ---------------------------------------------------------------------------
// Keys and backends
// ---------------------------------------------------------------------------

// loadOrCreateKey resolves the instance encryption key, generating one the
// first time.
//
// Generating rather than refusing is deliberate: a first run should work. What
// must not happen is a key appearing silently, so the path it went to and the
// fact that it is the only copy are logged at warning level, once.
//
// It takes the store because "a first run" is a question about the database
// rather than about the key file. A restore that brought the database back and
// left the key behind looks identical from here -- no key file, so generate one
// -- and the instance it produces starts, reports itself healthy, and fails
// inside its first GitHub call with a decryption error. Asking whether anything
// is sealed turns that into a refusal at startup that names the missing file.
func loadOrCreateKey(ctx context.Context, st *store.Store, cfg *config.Config, log *slog.Logger) (*cryptox.Key, error) {
	// Which key is in force is decided in one place (config.EncryptionKeyOrigin);
	// what stays here is the part only a controller does: generating a key on a
	// first run.
	origin, path := cfg.EncryptionKeyOrigin()
	switch origin {
	case config.KeyFromValue:
		key, err := cfg.ResolveEncryptionKey()
		if err != nil {
			return nil, fmt.Errorf("security.encryption_key (or ZOOMIES_ENCRYPTION_KEY) is not usable: %w", err)
		}
		return key, nil
	case config.KeyNone:
		return nil, errors.New("no encryption key: GitHub App private keys and webhook secrets are sealed with one, " +
			"so set security.encryption_key_file to a path this process may write, or pass the key itself in ZOOMIES_ENCRYPTION_KEY")
	}

	key, err := cfg.ResolveEncryptionKey()
	switch {
	case err == nil:
		return key, nil
	case !errors.Is(err, os.ErrNotExist):
		return nil, err
	}

	// The one check that separates a first run from a restore missing its key.
	sealed, serr := st.HasSealedSecrets(ctx)
	if serr != nil {
		return nil, serr
	}
	if sealed {
		return nil, fmt.Errorf("this database holds secrets sealed with an encryption key, and %s does not exist: "+
			"generating a new key here would leave them unreadable. Restore the key file from your backup, "+
			"or pass the key in ZOOMIES_ENCRYPTION_KEY; if the key is genuinely lost, delete and re-add the GitHub installations, "+
			"provider credentials and offsite backup remotes, and have an administrator reset two-step for "+
			"the accounts that have it", path)
	}

	key, err = cryptox.GenerateKey()
	if err != nil {
		return nil, fmt.Errorf("generating an encryption key: %w", err)
	}
	if err := cryptox.WriteKeyFile(path, key); err != nil {
		return nil, fmt.Errorf("writing the new encryption key to %s: %w (set security.encryption_key_file to a path this process may write)", path, err)
	}
	log.Warn("generated a new encryption key",
		"path", path,
		"detail", "it is the only copy, and without it the stored GitHub App private keys, webhook secrets, two-step secrets and backup remote credentials cannot be decrypted",
		"fix", "back up "+path+" now, alongside your database")
	return key, nil
}

// seedSettingsFromFile carries an existing zoomies.yaml into the database, once.
//
// It is the upgrade path. An instance that has been running on a configuration
// file meets this build with an empty settings table, and without this it would
// get a settings page showing every value as "From the file" and offering to
// store a second copy of each one. Instead the file's settings are copied in,
// the file stays as the layer underneath them, and nothing about what the
// controller is running changes -- the operator simply gains the ability to
// change them.
//
// It happens once and leaves a note saying so, in the store's own settings
// table rather than in the fleet's: an operator who then clears every setting
// back to its defaults must not have the file silently poured back in at the
// next start.
func seedSettingsFromFile(ctx context.Context, st *store.Store, cfg *config.Config, key *cryptox.Key, log *slog.Logger) (config.Findings, error) {
	if cfg.Path() == "" {
		return nil, nil
	}
	done, err := st.GetSetting(ctx, config.SeedKey)
	if err != nil {
		return nil, err
	}
	if done != "" {
		return nil, nil
	}
	// A database that already holds settings was configured through the API, so
	// there is nothing to import and the file is not in charge of it.
	if has, err := st.HasInstanceSettings(ctx); err != nil {
		return nil, err
	} else if has {
		return nil, st.SetSetting(ctx, config.SeedKey, "skipped: settings were already stored", false)
	}

	rows, err := config.SeedFromFile(cfg, key)
	if err != nil {
		// A file this process has already parsed cannot fail to parse here, so
		// this is a read error -- worth saying, not worth refusing to start
		// over, since the file is still the layer underneath.
		log.Warn("could not import the configuration file into the database",
			"path", cfg.Path(), "error", err)
		return nil, nil
	}
	if len(rows) == 0 {
		return nil, st.SetSetting(ctx, config.SeedKey, "skipped: the file set nothing that belongs in the database", false)
	}
	if err := st.PutInstanceSettings(ctx, "the configuration file", rows); err != nil {
		return nil, err
	}
	if err := st.SetSetting(ctx, config.SeedKey, cfg.Path(), false); err != nil {
		return nil, err
	}
	log.Info("imported the configuration file into the database",
		"path", cfg.Path(), "settings", len(rows),
		"detail", "they can now be changed on the settings page, and the file remains the layer underneath them")
	return config.Findings{config.SeedFinding(cfg.Path(), len(rows))}, nil
}

// socketExists reports whether a unix socket path is present. A TCP endpoint
// has no path and is taken on trust.
func socketExists(path string) bool {
	if path == "" {
		return true
	}
	_, err := os.Stat(path)
	return err == nil
}

// buildProviders is every infrastructure provider this build can rent machines
// from.
//
// It is built whatever the configuration says, and unconditionally: a
// deployment that rents nothing still has to be able to show which kinds it
// could, and a provider row whose kind has no factory here is answered with a
// problem naming the kind rather than with silence. Registering one is a line
// in this list; the registry refuses a factory whose contract range does not
// contain this build's, which is the earliest that mismatch can be caught.
func buildProviders() (*provider.Registry, error) {
	registry, err := provider.NewRegistry(proxmox.NewFactory())
	if err != nil {
		return nil, fmt.Errorf("preparing the infrastructure providers: %w", err)
	}
	return registry, nil
}

// sharedDirFor creates this host's shared folder and the layout this release
// keeps in it, and returns the folder -- or "" and the reason when it cannot be
// used, which leaves every pool's tool cache off on this host rather than
// stopping it.
func sharedDirFor(log *slog.Logger) (string, string) {
	return sharedDirIn(log, inContainer(), backend.IsMountPoint)
}

// inContainer is backend.InContainer, a variable so that a test run inside a
// container can still describe a host that is not one.
var inContainer = backend.InContainer

// sharedDirIn is sharedDirFor with the questions about the host passed in,
// which is what lets a test ask them of a host that is not the one it runs on.
func sharedDirIn(log *slog.Logger, inContainer bool, isMount func(string) bool) (string, string) {
	dir := config.SharedDir()
	// Checked before anything is created: in a container that does not mount
	// it, the folder would be made inside the data volume, where the host's
	// daemon -- which binds it for runners by this path -- cannot see it.
	if problem := backend.SharedFolderProblem(dir, inContainer, isMount); problem != "" {
		log.Warn("the shared folder is not mounted from the host; pools' tool caches are off on this host", "dir", dir, "fix", problem)
		return "", problem
	}
	if err := config.EnsureSharedDir(); err != nil {
		log.Warn("could not create the shared folder; pools' tool caches are off on this host until it exists and is writable",
			"dir", dir, "error", err,
			"fix", "create it and give it to the user Zoomies runs as, or run zoomies upgrade, which offers to")
		return "", fmt.Sprintf("the shared folder %s could not be created (%v); give it to the account Zoomies runs as, or run `zoomies upgrade --yes`, which does", dir, err)
	}
	return dir, ""
}

// buildBackends prepares the runner backends this host can use.
//
// Construction does not contact a daemon -- that is Probe's job -- so a host
// whose Docker is stopped still starts, reports the backend as unavailable and
// says why, instead of refusing to boot.
func buildBackends(ctx context.Context, cfg *config.Config, log *slog.Logger) (*backend.Registry, error) {
	var backends []backend.Backend
	opts := backend.DockerOptions{
		Network:      cfg.Agent.Network,
		WorkDir:      cfg.Agent.WorkDir,
		RegistryAuth: cfg.Agent.RegistryAuth,
		ExtraCAFile:  cfg.Agent.ExtraCAFile,
		DinDImage:    cfg.Agent.DinDImage,
		Logger:       log,
	}
	opts.SharedDir, opts.SharedDirProblem = sharedDirFor(log)
	// An explicit agent.docker_host belongs to the backend it was configured
	// for; the other container backend keeps autodetecting its own socket.
	// Handing one socket to both made the Hosts page report the same denial
	// twice -- once as docker, once as "podman" at /var/run/docker.sock -- and,
	// once the socket was reachable, made a Docker host claim it offered Podman
	// too, since the two speak the same API.
	hostFor := func(kind store.BackendKind) string {
		if cfg.Agent.Backend == "" || cfg.Agent.Backend == string(kind) {
			return cfg.Agent.DockerHost
		}
		return ""
	}
	// A backend nobody configured is registered only when the host visibly
	// has it: a socket that exists, a shell to run the runner with. The
	// configured one is registered regardless, so that a daemon which is not
	// up yet is still re-probed and reported on. Registering the rest anyway
	// put a red row with install advice on every Docker host's Hosts page --
	// "install Podman", "apt-get install libicu" into a distroless image --
	// when the honest answer is that the host does not offer them.
	configured := func(kind store.BackendKind) bool {
		return cfg.Agent.Backend == "" || cfg.Agent.Backend == string(kind)
	}
	docker := opts
	docker.Host = hostFor(store.BackendDocker)
	if b, err := backend.NewDocker(docker); err != nil {
		log.Debug("the Docker backend is not available on this host", "error", err)
	} else if configured(b.Kind()) || socketExists(b.SocketPath()) {
		backends = append(backends, b)
	}
	podman := opts
	podman.Host = hostFor(store.BackendPodman)
	if b, err := backend.NewPodman(podman); err != nil {
		log.Debug("the Podman backend is not available on this host", "error", err)
	} else if configured(b.Kind()) || socketExists(b.SocketPath()) {
		backends = append(backends, b)
	}
	if b, err := backend.NewProcess(backend.ProcessOptions{
		WorkDir:                 cfg.Agent.WorkDir,
		RunnerVersion:           cfg.GitHub.RunnerVersion,
		RunnerSHA256:            cfg.Agent.RunnerSHA256,
		AllowUnverifiedDownload: cfg.Agent.AllowUnverifiedRunnerDownload,
		DownloadBaseURL:         cfg.Agent.RunnerDownloadURL,
		Logger:                  log,
	}); err != nil {
		log.Debug("the process backend could not be prepared", "error", err)
	} else if configured(b.Kind()) || backend.HasShell() {
		backends = append(backends, b)
	}

	reg := backend.NewRegistry(backends...)
	if len(reg.Kinds()) == 0 {
		return nil, errors.New("no runner backend could be prepared on this host, so the embedded agent would have no way to start a runner: " +
			"install Docker or Podman, make sure agent.work_dir is writable, or set agent.embedded to false")
	}
	if kind := strings.TrimSpace(cfg.Agent.Backend); kind != "" {
		if _, err := reg.Get(store.BackendKind(kind)); err != nil {
			return nil, fmt.Errorf("agent.backend is %q, which this host cannot provide: %w", kind, err)
		}
	}
	// Probing here rather than at first use means the startup log says what is
	// actually usable, which is the difference between "why is nothing
	// scheduling" and one line naming the stopped daemon.
	probeCtx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	for _, info := range reg.Probe(probeCtx) {
		if info.Available {
			log.Info("backend available", "kind", info.Kind, "version", info.Version, "rootless", info.Rootless, "endpoint", info.Endpoint)
		} else {
			log.Warn("backend not available", "kind", info.Kind, "detail", info.Detail)
		}
	}
	return reg, nil
}

// ---------------------------------------------------------------------------
// Startup banner
// ---------------------------------------------------------------------------

// printBanner prints the six facts an operator checks when a controller comes
// up, in one block, once. Everything else is a log line.
func printBanner(w io.Writer, cfg *config.Config, backends *backend.Registry) {
	external := cfg.Server.ExternalURL
	if external == "" {
		external = "(not set -- webhook URLs and the UI's links need server.external_url)"
	}
	webhook := cfg.WebhookURL()
	if webhook == "" {
		webhook = "(needs server.external_url) " + cfg.GitHub.WebhookPath
	}

	runners := "none -- this controller hosts no runners (agent.embedded is false)"
	if cfg.Agent.Embedded {
		kind := cfg.Agent.Backend
		if kind == "" && backends != nil {
			if kinds := backends.Kinds(); len(kinds) == 1 {
				kind = string(kinds[0])
			}
		}
		if kind == "" {
			kind = "autodetected"
		}
		runners = fmt.Sprintf("%s, embedded agent %q, capacity %d", kind, cfg.Agent.Name, cfg.Agent.Capacity)
	}

	scheme := "http"
	if cfg.Server.TLS.Mode != config.TLSOff {
		scheme = "https"
	}

	// The block paw mirrors the project's icon without reproducing its fine speed
	// ring, which would muddy the silhouette at terminal resolution.
	fmt.Fprintln(w, "\n        ▄██▄     ▄██▄")
	fmt.Fprintf(w, "       ██████   ██████        zoomies %s\n", version.Short())
	fmt.Fprintln(w, "  ▄██▄ ██████   ██████ ▄██▄  off the lead, on the job.")
	fmt.Fprintln(w, " █████  ▀██▀     ▀██▀  █████")
	fmt.Fprintln(w, "  ▀██▀      ▄██▄       ▀██▀")
	fmt.Fprintln(w, "         ▄████████▄")
	fmt.Fprintln(w, "       ▄████████████▄")
	fmt.Fprintln(w, "      ████████████████")
	fmt.Fprintln(w, "       ▀████████████▀")
	fmt.Fprintln(w, "          ▀▀██▀▀")
	fmt.Fprintln(w)
	for _, row := range [][2]string{
		{"listening on", fmt.Sprintf("%s://%s", scheme, cfg.Server.Bind)},
		{"external URL", external},
		{"webhook URL", webhook},
		{"backend", runners},
		{"database", cfg.Database.Path},
		{"config", configSource(cfg)},
	} {
		fmt.Fprintf(w, "  %-14s %s\n", row[0], row[1])
	}
	fmt.Fprintln(w)
}

// printSetupToken shows the credential the first-run form asks for, but only
// while there is nobody to sign in as.
//
// It goes to both the banner and the log: an operator watching a terminal sees
// it there, and one who ran `docker compose up -d` finds it with
// `docker compose logs`. Printing it on every start while the instance is empty
// is deliberate -- an operator who lost the first one should not have to reset
// anything, and once an account exists the line stops appearing for good.
func printSetupToken(ctx context.Context, w io.Writer, ctrl *controller.Controller, log *slog.Logger) {
	svc := ctrl.Auth()
	need, err := svc.NeedsBootstrap(ctx)
	if err != nil {
		log.Warn("could not check whether this instance has any accounts", "error", err)
		return
	}
	if !need {
		return
	}
	token := svc.SetupToken()
	log.Info("setup token: "+token,
		"why", "this instance has no accounts yet; the first-run page asks for this token",
		"note", "it changes on every restart, and this line stops once an account exists")
	fmt.Fprintf(w, "  %-14s %s\n", "setup token", token)
	fmt.Fprintf(w, "  %-14s %s\n", "", "paste this into the first-run page to create the first administrator")
	fmt.Fprintln(w)
}

// configSource names the file the configuration came from, or says there was
// not one -- which is a supported way to run and should not look like a fault.
func configSource(cfg *config.Config) string {
	if p := cfg.Path(); p != "" {
		if abs, err := filepath.Abs(p); err == nil {
			return abs
		}
		return p
	}
	return "(no file: defaults plus ZOOMIES_* environment)"
}

package main

import (
	"bytes"
	"context"
	"log/slog"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/store"
)

func leaseTestStore(t *testing.T) *store.Store {
	t.Helper()
	st, err := store.Open(t.Context(), store.Options{Path: ":memory:"})
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })
	return st
}

// The message is the whole point of the lease: an operator who has just been
// refused needs to know which machine to go and look at, and "the database is
// locked" would send them to the wrong one.
func TestTheSecondControllerIsToldWhichMachineHasTheDatabase(t *testing.T) {
	ctx := context.Background()
	st := leaseTestStore(t)

	// A live lease held by another machine. It has to be another machine:
	// a predecessor on this host is deliberately not a rival, since whoever is
	// asking holds the file lock and so nothing here is still running.
	other := &store.ControllerLease{
		Holder: store.NewID(store.PrefixController), Host: "vm-elsewhere",
		PID: 4242, Version: "1.0.0",
	}
	if _, err := st.AcquireControllerLease(ctx, other, controller.LeaseTTL, false); err != nil {
		t.Fatalf("seeding the other controller's lease: %v", err)
	}

	_, err := takeControllerLease(ctx, st, false)
	if err == nil {
		t.Fatal("a second controller took a database another machine holds")
	}
	msg := err.Error()
	if !strings.Contains(msg, "another controller holds this database") {
		t.Fatalf("error = %v, want it to name the conflict", err)
	}
	// The two things the operator needs: which machine, and how to proceed if
	// that machine is actually gone.
	if !strings.Contains(msg, "vm-elsewhere") {
		t.Errorf("the refusal must identify the holder: %v", err)
	}
	if !strings.Contains(msg, "--takeover") {
		t.Errorf("the refusal must name the way out: %v", err)
	}

	// --takeover exists for the machine that is really gone, and it has to
	// actually work -- otherwise the advice above is a dead end.
	mine, err := takeControllerLease(ctx, st, true)
	if err != nil {
		t.Fatalf("takeover: %v", err)
	}
	if mine.Holder == "" || mine.PID == 0 {
		t.Fatalf("the takeover produced a lease that says nothing about who holds it: %+v", mine)
	}
}

// A controller that restarts fast enough to beat its own lease's expiry must
// not refuse to start, which is the opposite of what the lease is for. The
// caller holds the file lock, so a predecessor on this host is already gone.
func TestRestartingOnTheSameHostIsNotAConflict(t *testing.T) {
	ctx := context.Background()
	st := leaseTestStore(t)

	first, err := takeControllerLease(ctx, st, false)
	if err != nil {
		t.Fatalf("taking the first lease: %v", err)
	}
	again, err := takeControllerLease(ctx, st, false)
	if err != nil {
		t.Fatalf("a restart on the same host was refused: %v", err)
	}
	if again.Host != first.Host {
		t.Fatalf("host = %q, want this machine's own", again.Host)
	}
}

// The configured level is where logging starts, and the gate it starts behind
// is the one SIGHUP later moves.
func TestSetupLoggingHonoursTheConfiguredLevel(t *testing.T) {
	cfg := config.Default()
	cfg.Log.Level = "warn"

	log, level := setupLogging(cfg)
	if log == nil || level == nil {
		t.Fatal("setupLogging returned nothing to log with")
	}
	if level.Level() != slog.LevelWarn {
		t.Fatalf("level = %v, want warn", level.Level())
	}

	// The inner handler is built at debug so that it never filters anything
	// itself; the wrapper is the only gate, which is what lets SIGHUP move it
	// without rebuilding loggers the controller already captured.
	level.Set(slog.LevelDebug)
	if !log.Enabled(context.Background(), slog.LevelDebug) {
		t.Fatal("the level change did not reach the logger")
	}
}

// A group on a level-gated handler must keep the gate, or a component that
// groups its attributes would quietly log at a level nobody asked for.
func TestGroupingALevelGatedHandlerKeepsTheGate(t *testing.T) {
	level := new(slog.LevelVar)
	level.Set(slog.LevelError)

	var buf bytes.Buffer
	inner := slog.NewTextHandler(&buf, &slog.HandlerOptions{Level: slog.LevelDebug})
	log := slog.New(&levelHandler{Handler: inner, level: level}).WithGroup("agent")

	log.Info("suppressed")
	if buf.Len() != 0 {
		t.Fatalf("a grouped logger ignored the level: %s", buf.String())
	}

	level.Set(slog.LevelInfo)
	log.Info("allowed", "host", "vm-1")
	body := buf.String()
	if !strings.Contains(body, "allowed") {
		t.Fatalf("the grouped logger dropped a line it should have kept: %s", body)
	}
	if !strings.Contains(body, "agent.host") {
		t.Fatalf("the group was lost: %s", body)
	}
}

