	if !strings.Contains(errOut.String(), "cannot be used") {
		t.Errorf("the failure was not reported:\n%s", errOut)
	}
}

// Purging asks the controller whose spent tokens to take; the flags must say
// exactly that and nothing wider, because --all reaches every account's.
func TestTokensPurgeSendsWhoseTokensToTake(t *testing.T) {
	cases := []struct {
		name string
		args []string
		want map[string]any
	}{
		{"your own", nil, map[string]any{}},
		{"one account", []string{"--user", "usr_1"}, map[string]any{"user_id": "usr_1"}},
		{"everything", []string{"--all"}, map[string]any{"all": true}},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			var got map[string]any
			srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				if r.Method != http.MethodPost || r.URL.Path != "/api/v1/tokens/purge" {
					t.Errorf("%s %s, want POST /api/v1/tokens/purge", r.Method, r.URL.Path)
				}
				_ = json.NewDecoder(r.Body).Decode(&got)
				w.Header().Set("Content-Type", "application/json")
				_, _ = w.Write([]byte(`{"deleted":[{"id":"tok_1","name":"old"}]}`))
			}))
			defer srv.Close()

			e, out, errOut := newTestEnv(t)
			args := append([]string{"tokens", "purge", "--url", srv.URL}, c.args...)
			if code := dispatch(context.Background(), e, args); code != exitOK {
				t.Fatalf("exit code = %d\n%s", code, errOut)
			}
			if fmt.Sprint(got) != fmt.Sprint(c.want) {
				t.Errorf("body = %v, want %v", got, c.want)
			}
			if !strings.Contains(out.String(), "tok_1") {
				t.Errorf("the deleted token was not named:\n%s", out)
			}
		})
	}
}

func TestJoinTokenCreatePrintsTheWindowsCommandOnRequest(t *testing.T) {
	const linux = "curl -fsSL https://zoomies.sh/install.sh | sh -s -- --join-token 'zoojoin_x'"
	const windows = "& ([scriptblock]::Create((irm https://zoomies.sh/install.ps1))) -Mode agent -JoinToken 'zoojoin_x'"
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusCreated)
		_ = json.NewEncoder(w).Encode(map[string]any{
			"id": "jt_1", "token": "zoojoin_x", "command": linux,
			"commands":   map[string]string{"linux": linux, "windows": windows},
			"expires_at": time.Now().Add(time.Hour).UTC().Format(time.RFC3339),
		})
	}))
	defer srv.Close()

	for _, tc := range []struct {
		os            string
		wantLinux     bool
		wantWindows   bool
		wantAdminHint bool
	}{
		{"linux", true, false, false},
		{"windows", false, true, true},
		{"all", true, true, true},
	} {
		e, out, errOut := newTestEnv(t)
		code := dispatch(context.Background(), e, []string{"hosts", "join-token", "create", "--url", srv.URL, "--os", tc.os})
		if code != exitOK {
			t.Fatalf("--os %s: exit code = %d\n%s", tc.os, code, errOut)
		}
		if got := strings.Contains(out.String(), "install.sh"); got != tc.wantLinux {
			t.Errorf("--os %s: linux command present = %v\n%s", tc.os, got, out)
		}
		if got := strings.Contains(out.String(), "install.ps1"); got != tc.wantWindows {
			t.Errorf("--os %s: windows command present = %v\n%s", tc.os, got, out)
		}
		if got := strings.Contains(out.String(), "as administrator"); got != tc.wantAdminHint {
			t.Errorf("--os %s: administrator hint present = %v\n%s", tc.os, got, out)
		}
	}

	e, _, errOut := newTestEnv(t)
	if code := dispatch(context.Background(), e, []string{"hosts", "join-token", "create", "--url", srv.URL, "--os", "beos"}); code != exitUsage {
		t.Fatalf("an unknown --os exit code = %d, want %d\n%s", code, exitUsage, errOut)
	}
}

package main

import (
	"context"
	"fmt"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/gateway"
	"github.com/eyupio/zoomies/internal/logging"
)

// runGateway is `zoomies gateway`: the provider-side end of a private
// connection. It runs beside a hypervisor the controller cannot reach -- a
// Proxmox cluster on a home network, typically -- and forwards what arrives
// through the tunnel to that one API. The address it prints is what the
// controller's provider form asks for.
func runGateway(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies gateway --target <host:port> [--state-dir path] [--quiet]",
		"Publish a private provider API, such as a Proxmox cluster on your home network, to a controller over Tailcat.")
	target := fs.String("target", "", "the provider's API as this machine reaches it, e.g. 192.168.1.10:8006 (required)")
	stateDir := fs.String("state-dir", "", "where the gateway keeps its identity, which is its address (default: "+config.StateDir()+")")
	quiet := fs.Bool("quiet", false, "do not print the address; for a service whose log is not the place for a credential")
	logFormat := fs.String("log-format", "text", "log format: text or json")
	fs.example(
		"zoomies gateway --target 192.168.1.10:8006",
		"zoomies gateway --target pve.lan:8006 --state-dir /var/lib/zoomies",
	)
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	if _, err := gateway.ParseTarget(*target); err != nil {
		return usagef("gateway", "%v", err)
	}
	dir := *stateDir
	if dir == "" {
		dir = config.StateDir()
	}
	log := logging.Setup(logging.Options{Level: "info", Format: *logFormat})

	g, err := gateway.Start(ctx, gateway.Options{Target: *target, StateDir: dir, Logger: log})
	if err != nil {
		return err
	}
	defer g.Close()

	if *quiet {
		fmt.Fprintf(e.err, "Private connection ready; forwarding to %s. The address is in %s.\n", g.Target(), gateway.StatePath(dir))
	} else {
		// The address is the capability. It is printed once, to the terminal
		// the operator is sitting at, and never logged: a service should
		// run with --quiet, and the state file is where to read it back.
		fmt.Fprintf(e.out, "Private connection ready; forwarding to %s.\n\n", g.Target())
		fmt.Fprintf(e.out, "On the controller, open the provider, choose Private connection (Tailcat), and paste this address:\n\n  %s\n\n", g.Address())
		fmt.Fprintln(e.out, "Anyone holding that address can open connections to the target. Keep it out of screenshots, issues and source control.")
		fmt.Fprintln(e.out, "Leave this running; ctrl-C stops the connection and the controller reports the provider unreachable.")
	}
	<-ctx.Done()
	return ctx.Err()
}

