		"GET /api/v1/size-pins": `{"total":1,"limit":50,"offset":0,"items":[
		  {"repo":"acme/widgets","workflow":"` + hostile + `","job_name":"` + hostile + `","class":"large","created_by":"` + hostile + `","created_at":"2026-01-01T00:00:00Z"}]}`,
	})
