package main

import (
	"context"
	"fmt"
	"net/url"
	"strings"
	"time"
)

// runTokens is `zoomies tokens ...`: the credentials that let this CLI, and
// anything else, talk to the API.
func runTokens(ctx context.Context, e *env, args []string) error {
	return runGroup(ctx, e, "tokens", "API tokens. The value exists in plaintext exactly once, at creation.", []*subcommand{
		{"list", "", "Your tokens' metadata, or everybody's for an administrator; never the value", tokensList},
		{"create", "--name <n> --role <r>", "Mint a token and print it once", tokensCreate},
		{"revoke", "<token-id>", "Revoke a token immediately", tokensRevoke},
		{"delete", "<token-id>", "Remove a revoked or expired token from the list", tokensDelete},
		{"purge", "[--user <id> | --all]", "Remove every revoked or expired token", tokensPurge},
	}, args)
}

func tokensList(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies tokens list", "List API tokens: your own, or everybody's for an administrator. Metadata only -- the value is not stored.")
	cf := registerClientFlags(fs, true)
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}

	var out listResponse[tokenItem]
	raw, err := client.get(ctx, "/tokens", nil, &out)
	if err != nil {
		return err
	}
	if p.structured() {
		return p.emit(raw)
	}
	if len(out.Items) == 0 {
		p.note("No API tokens. Mint one with: zoomies tokens create --name my-laptop --role operator")
		return nil
	}

	rows := make([][]string, 0, len(out.Items))
	for _, t := range out.Items {
		state := "active"
		switch {
		case t.Revoked:
			state = p.paint(colourDim, "revoked")
		case t.ExpiresAt != nil && t.ExpiresAt.Before(time.Now()):
			state = p.paint(colourRed, "expired")
		}
		expires := "never"
		if t.ExpiresAt != nil {
			expires = p.relTime(*t.ExpiresAt)
		}
		rows = append(rows, []string{
			t.Name,
			t.ID,
			t.Role,
			dash(t.Prefix),
			dash(strings.Join(t.Scopes, ",")),
			state,
			expires,
			p.relTimePtr(t.LastUsedAt),
		})
	}
	p.table([]string{"name", "id", "role", "prefix", "scopes", "state", "expires", "last used"}, rows)
	return nil
}

func tokensCreate(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies tokens create --name <name> --role <viewer|operator|admin|platform>",
		"Mint an API token of your own, at a role no higher than yours. It is printed once and only its hash is kept.")
	cf := registerClientFlags(fs, true)
	name := fs.String("name", "", "what this token is for, e.g. my-laptop or prometheus (required)")
	role := fs.String("role", "viewer", "viewer, operator, admin or platform")
	scopes := &listValue{}
	fs.Var(scopes, "scope", "narrow the token within its role, e.g. runners:read (repeatable)")
	expiresIn := fs.Duration("expires-in", 0, "how long the token lasts; zero means never, which is worth avoiding")
	fs.example(
		"zoomies tokens create --name my-laptop --role operator --expires-in 2160h",
		"zoomies tokens create --name prometheus --role viewer --scope metrics:read",
	)
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	if strings.TrimSpace(*name) == "" {
		return usagef("tokens create", "needs --name; a token nobody can identify is a token nobody dares revoke")
	}
	if !validRole(*role) {
		return usagef("tokens create", "--role %q is not a role; use viewer, operator or admin", *role)
	}

	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}

	body := map[string]any{"name": *name, "role": *role}
	if len(*scopes) > 0 {
		body["scopes"] = []string(*scopes)
	}
	if *expiresIn > 0 {
		body["expires_in"] = expiresIn.String()
	}

	var token tokenItem
	raw, err := client.post(ctx, "/tokens", nil, body, &token)
	if err != nil {
		return err
	}
	if p.structured() {
		return p.emit(raw)
	}

	fmt.Fprintf(e.out, "%s\n\n", token.Token)
	p.keyValues([][2]string{
		{"name", token.Name},
		{"id", token.ID},
		{"role", token.Role},
		{"expires", map[bool]string{true: "never", false: p.relTimePtr(token.ExpiresAt)}[token.ExpiresAt == nil]},
	})
	fmt.Fprintln(e.out, "\nThis is the only time the token is shown. To use it from here:")
	fmt.Fprintf(e.out, "  export ZOOMIES_TOKEN=%s\n", token.Token)
	return nil
}

func tokensRevoke(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies tokens revoke <token-id>", "Revoke a token. It stops working immediately.")
	cf := registerClientFlags(fs, false)
	if err := fs.parse(args); err != nil {
		return err
	}
	id, err := fs.oneArg("a token ID, as shown by `zoomies tokens list`")
	if err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	if _, err := client.del(ctx, "/tokens/"+url.PathEscape(id), nil, nil); err != nil {
		return err
	}
	fmt.Fprintf(e.out, "Revoked token %s.\n", id)
	return nil
}

func tokensDelete(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies tokens delete <token-id>",
		"Remove a revoked or expired token from the list for good. A token that still works is refused: revoke it first.")
	cf := registerClientFlags(fs, false)
	if err := fs.parse(args); err != nil {
		return err
	}
	id, err := fs.oneArg("a token ID, as shown by `zoomies tokens list`")
	if err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	if _, err := client.del(ctx, "/tokens/"+url.PathEscape(id), url.Values{"purge": {"true"}}, nil); err != nil {
		return err
	}
	fmt.Fprintf(e.out, "Deleted token %s. The audit log still records it.\n", id)
	return nil
}

func tokensPurge(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies tokens purge [--user <user-id> | --all]",
		"Remove every revoked or expired token: your own, one account's, or all of them. Tokens that still work are left alone.")
	cf := registerClientFlags(fs, true)
	user := fs.String("user", "", "purge this account's spent tokens instead of your own")
	all := fs.Bool("all", false, "purge every spent token you can see")
	fs.example("zoomies tokens purge", "zoomies tokens purge --all")
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	if *all && *user != "" {
		return usagef("tokens purge", "--user and --all ask different questions; give one")
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}
	body := map[string]any{}
	if *all {
		body["all"] = true
	}
	if *user != "" {
		body["user_id"] = *user
	}
	var out struct {
		Deleted []tokenItem `json:"deleted"`
	}
	raw, err := client.post(ctx, "/tokens/purge", nil, body, &out)
	if err != nil {
		return err
	}
	if p.structured() {
		return p.emit(raw)
	}
	if len(out.Deleted) == 0 {
		p.note("Nothing to delete: no revoked or expired tokens.")
		return nil
	}
	for _, t := range out.Deleted {
		fmt.Fprintf(e.out, "Deleted %s (%s)\n", t.Name, t.ID)
	}
	return nil
}

package main

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/backup"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/cryptox"
	"github.com/eyupio/zoomies/internal/store"
)

func runTransfer(ctx context.Context, e *env, args []string) error {
	return runGroup(ctx, e, "transfer", "Move a complete instance, including its history and fleet credentials.", []*subcommand{
		{"prepare", "", "Drain a running instance in one action without interrupting busy jobs", transferPrepare},
		{"status", "", "Follow runner, job and cleanup progress", transferStatus},
		{"cancel", "", "Resume saved pools before the instance is fenced", transferCancel},
		{"export", "--out <file> --passphrase-file <file>", "Export a drained, fenced instance while its controller is stopped", transferExport},
		{"import", "<file> --source-stopped --passphrase-file <file>", "Import into an empty destination, keeping its operator access and recovery fence", transferImport},
	}, args)
}

func transferConfig(ctx context.Context, path string) (*config.Config, func(), error) {
	cfg, err := config.Load(path)
	if err != nil {
		return nil, nil, err
	}
	if err = os.MkdirAll(filepath.Dir(cfg.Database.Path), 0o750); err != nil {
		return nil, nil, err
	}
	unlock, err := store.Lock(cfg.Database.Path)
	if err != nil {
		return nil, nil, fmt.Errorf("stop the controller before transferring its database: %w", err)
	}
	cleanup := func() { _ = unlock() }
	key, err := cfg.ResolveEncryptionKey()
	if err != nil {
		cleanup()
		return nil, nil, err
	}
	if _, err = os.Stat(cfg.Database.Path); err == nil {
		st, err := store.Open(ctx, store.Options{Path: cfg.Database.Path, ReadOnly: true})
		if err != nil {
			cleanup()
			return nil, nil, err
		}
		rows, err := st.InstanceSettings(ctx)
		_ = st.Close()
		if err == nil {
			findings, e := cfg.Rebuild(rows, key)
			err = e
			for _, f := range findings {
				if f.Severity == config.SeverityError {
					err = fmt.Errorf("cannot load stored settings: %s", f.Title)
				}
			}
		}
		if err != nil {
			cleanup()
			return nil, nil, err
		}
	} else if !errors.Is(err, os.ErrNotExist) {
		cleanup()
		return nil, nil, err
	}
	return cfg, cleanup, nil
}

func transferExport(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies transfer export --out <file> --passphrase-file <file>", "Export a complete instance after draining, raising its recovery fence and stopping its controller.")
	cfgFile := fs.String("config", "", "path to zoomies.yaml")
	out := fs.String("out", "", "new encrypted archive file; existing files are refused")
	passFile := fs.String("passphrase-file", "", "file holding the archive passphrase")
	fs.example("zoomies transfer export --out instance.zbk --passphrase-file ./move.pass")
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	if *out == "" || *passFile == "" {
		return usagef("transfer export", "needs --out and --passphrase-file")
	}
	pass, err := readPassphraseFile(*passFile)
	if err != nil {
		return err
	}
	cfg, cleanup, err := transferConfig(ctx, *cfgFile)
	if err != nil {
		return err
	}
	defer cleanup()
	st, err := store.Open(ctx, store.Options{Path: cfg.Database.Path, ReadOnly: true})
	if err != nil {
		return err
	}
	defer st.Close()
	f, err := os.CreateTemp(filepath.Dir(*out), ".instance-transfer-*")
	if err != nil {
		return err
	}
	defer os.Remove(f.Name())
	defer f.Close()
	if err = backup.WriteTransfer(ctx, st, cfg, pass, f); err != nil {
		return err
	}
	if err = f.Sync(); err != nil {
		return err
	}
	if err = f.Close(); err != nil {
		return err
	}
	// A hard link publishes the complete file without overwriting an existing
	// archive. The temporary file is on the same volume as the destination.
	if err = os.Link(f.Name(), *out); err != nil {
		return fmt.Errorf("publishing the archive without replacing a file: %w", err)
	}
	fmt.Fprintf(e.out, "Exported the complete instance to %s. Keep the source stopped during cutover.\n", *out)
	return nil
}

func transferImport(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies transfer import <file> --source-stopped --passphrase-file <file>", "Import a complete instance into an empty, stopped destination. Its own encryption key and operator access remain in charge.")
	cfgFile := fs.String("config", "", "path to zoomies.yaml")
	passFile := fs.String("passphrase-file", "", "file holding the archive passphrase")
	stopped := fs.Bool("source-stopped", false, "confirm the source controller is stopped and will stay stopped during cutover")
	name := fs.String("operator-name", "", "create a destination operator when this host has no existing operator access")
	passwordFile := fs.String("operator-password-file", "", "file holding the new destination operator's password")
	fs.example("zoomies transfer import instance.zbk --source-stopped --passphrase-file ./move.pass",
		"zoomies transfer import instance.zbk --source-stopped --passphrase-file ./move.pass --operator-name new-operator --operator-password-file ./operator.pass")
	if err := fs.parse(args); err != nil {
		return err
	}
	src, err := fs.oneArg("the encrypted instance archive")
	if err != nil {
		return err
	}
	if !*stopped || *passFile == "" {
		return usagef("transfer import", "needs --source-stopped and --passphrase-file")
	}
	if (*name == "") != (*passwordFile == "") {
		return usagef("transfer import", "give both --operator-name and --operator-password-file")
	}
	var operator *store.User
	if *name != "" {
		pass, err := readPassphraseFile(*passwordFile)
		if err != nil {
			return err
		}
		if len(pass) < 12 {
			return errors.New("use at least 12 characters for the destination operator password")
		}
		hash, err := cryptox.HashPassword(pass)
		if err != nil {
			return err
		}
		operator = &store.User{Username: strings.TrimSpace(*name), Role: store.Roles()[len(store.Roles())-1], PasswordHash: hash}
		if operator.Username == "" {
			return errors.New("give the destination operator a username")
		}
	}
	pass, err := readPassphraseFile(*passFile)
	if err != nil {
		return err
	}
	cfg, cleanup, err := transferConfig(ctx, *cfgFile)
	if err != nil {
		return err
	}
	defer cleanup()
	root, err := os.MkdirTemp(filepath.Dir(cfg.Database.Path), ".transfer-import-*")
	if err != nil {
		return err
	}
	defer os.RemoveAll(root)
	f, err := os.Open(src)
	if err != nil {
		return err
	}
	defer f.Close()
	entry, err := backup.ReadTransfer(ctx, cfg, root, f, pass)
	if err != nil {
		return err
	}
	report, err := backup.Restore(ctx, cfg, entry.Dir, backup.RestoreOptions{Replace: true, SourceStopped: *stopped, TransferOperator: operator})
	if err != nil {
		return err
	}
	printRestoreReport(e, report, cfg.Database.Path)
	return nil
}

func transferPrepare(ctx context.Context, e *env, args []string) error {
	return transferPreparationRequest(ctx, e, args, "prepare")
}
func transferStatus(ctx context.Context, e *env, args []string) error {
	return transferPreparationRequest(ctx, e, args, "status")
}
func transferCancel(ctx context.Context, e *env, args []string) error {
	return transferPreparationRequest(ctx, e, args, "cancel")
}
func transferPreparationRequest(ctx context.Context, e *env, args []string, action string) error {
	fs := newFlagSet(e, "zoomies transfer "+action, "Prepare a running instance for transfer, follow its drain, or cancel before it is fenced.")
	cf := registerClientFlags(fs, true)
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	var progress store.TransferProgress
	p, err := cf.printer(e)
	if err != nil {
		return err
	}
	var raw []byte
	switch action {
	case "prepare":
		raw, err = client.post(ctx, "/transfers/preparation", nil, nil, &progress)
	case "status":
		raw, err = client.get(ctx, "/transfers/preparation", nil, &progress)
	case "cancel":
		_, err = client.del(ctx, "/transfers/preparation", nil, nil)
		if err == nil {
			fmt.Fprintln(e.out, "Preparation cancelled; saved pools resume.")
		}
		return err
	}
	if err != nil {
		return err
	}
	if p.structured() {
		return p.emit(raw)
	}
	if progress.Ready {
		fmt.Fprintln(e.out, "Ready to export. This instance is fenced; keep its controller stopped during cutover.")
		return nil
	}
	if !progress.Draining {
		fmt.Fprintln(e.out, "Preparation has not started.")
		return nil
	}
	// The counts first, then the controller's sentence about them, then each
	// thing in the way with its host: the same three things the page shows.
	fmt.Fprintf(e.out, "Draining: %d busy runners, %d runners remaining, %d awaiting cleanup, %d running jobs and %d machine operations.\n", progress.BusyRunners, progress.LiveRunners, progress.PendingCleanup, progress.ActiveJobs, progress.MachineOperations)
	if progress.Summary != "" {
		fmt.Fprintln(e.out, progress.Summary)
	}
	for _, w := range progress.Waiting {
		since := ""
		if w.Since != nil {
			since = fmt.Sprintf(" (since %s ago)", time.Since(*w.Since).Round(time.Minute))
		}
		fmt.Fprintf(e.out, "  %-8s %s: %s%s\n", w.Kind, w.Name, w.Detail, since)
	}
	return nil
}

