// A dry run is the one update path an operator can try before deciding, so it
// must leave the host exactly as it found it: no replaced binary, no kept
// previous one, no restart, and nothing left beside the binary.
func TestADryRunReplacesNothingAndRestartsNothing(t *testing.T) {
	e, out, _ := newTestEnv(t)
	candidateRelease(t)
	dir := t.TempDir()
	binary := filepath.Join(dir, "zoomies")
	if err := os.WriteFile(binary, []byte("existing binary"), 0755); err != nil {
		t.Fatal(err)
	}
	_, reexecs := stubUpgradeSeams(t, binary, nil)

	if err := selfUpdate(context.Background(), e, binary, "v9.9.9", deploymentSelector{}, true, ""); err != nil {
		t.Fatal(err)
	}
	if b, _ := os.ReadFile(binary); string(b) != "existing binary" {
		t.Fatalf("the binary was replaced by a dry run: %q", b)
	}
	if _, err := os.Stat(binary + installer.PreviousSuffix); !os.IsNotExist(err) {
		t.Fatalf("a dry run kept a previous binary: %v", err)
	}
	if len(*reexecs) != 0 {
		t.Fatalf("a dry run re-executed into the release: %q", *reexecs)
	}
	if entries, _ := os.ReadDir(dir); len(entries) != 1 {
		t.Fatalf("a dry run left files beside the binary: %v", entries)
	}
	if !strings.Contains(out.String(), "Would replace") {
		t.Fatalf("the dry run did not say what it would do: %s", out.String())
	}
}

// The copy before an upgrade must be taken before the binary is replaced: a
// failure after the swap would leave a new binary to migrate a database nothing
// protected. --no-download exercises the order without a real download.
func TestTheBackupRunsBeforeTheDeployment(t *testing.T) {
	e, _, _ := newTestEnv(t)
	oldB, oldU := backupBeforeUpgradeInstall, runUpgradeInstall
	t.Cleanup(func() { backupBeforeUpgradeInstall, runUpgradeInstall = oldB, oldU })
	var order []string
	backupBeforeUpgradeInstall = func(context.Context, installer.UpgradeOptions) (string, error) {
		order = append(order, "backup")
		return "zoomies-20260101-000000", nil
	}
	runUpgradeInstall = func(context.Context, installer.UpgradeOptions) error {
		order = append(order, "deploy")
		return nil
	}
	if err := runUpgrade(context.Background(), e, []string{"--no-download"}); err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(order, []string{"backup", "deploy"}) {
		t.Fatalf("order = %v, want the copy before the deployment", order)
	}
}

func TestNoBackupSkipsTheCopyBeforeTheUpgrade(t *testing.T) {
	e, _, _ := newTestEnv(t)
	oldB, oldU := backupBeforeUpgradeInstall, runUpgradeInstall
	t.Cleanup(func() { backupBeforeUpgradeInstall, runUpgradeInstall = oldB, oldU })
	called := false
	backupBeforeUpgradeInstall = func(context.Context, installer.UpgradeOptions) (string, error) {
		called = true
		return "", nil
	}
	runUpgradeInstall = func(context.Context, installer.UpgradeOptions) error { return nil }
	if err := runUpgrade(context.Background(), e, []string{"--no-download", "--no-backup"}); err != nil {
		t.Fatal(err)
	}
	if called {
		t.Fatal("--no-backup still took a copy")
	}
}

// A dry run is the review it promises: the deployment half is printed where a
// real run would print it, so the mounts and settings it would add are visible,
// rather than a generic line promising they were checked.
func TestADryRunPrintsTheDeploymentReview(t *testing.T) {
	e, out, _ := newTestEnv(t)
	candidateRelease(t)
	old := runUpgradeInstall
	t.Cleanup(func() { runUpgradeInstall = old })
	reviewed := false
	runUpgradeInstall = func(_ context.Context, opts installer.UpgradeOptions) error {
		if opts.Check && opts.Out != nil && opts.Out != io.Discard {
			reviewed = true
			fmt.Fprint(opts.Out, "would add the shared folder\n")
		}
		return nil
	}
	if err := runUpgrade(context.Background(), e, []string{"--dry-run", "--version", "v9.9.9"}); err != nil {
		t.Fatal(err)
	}
	if !reviewed {
		t.Fatal("the dry run never printed the deployment review")
	}
	if !strings.Contains(out.String(), "would add the shared folder") || !strings.Contains(out.String(), "Dry run complete") {
		t.Fatalf("output = %q", out.String())
	}
}

// A dry run must download to preview anything, so the flag that says "do not
// download" is a contradiction rather than a combination.
func TestADryRunRefusesToGoWithoutADownload(t *testing.T) {
	e, _, _ := newTestEnv(t)
	err := runUpgrade(context.Background(), e, []string{"--dry-run", "--no-download"})
	if err == nil || !strings.Contains(err.Error(), "--dry-run") {
		t.Fatalf("error: %v", err)
	}
}

// The case the split exists for: the new release refuses this deployment, and
// the host is left exactly as it was, without a re-exec into the refusal.
func TestACandidateThatRefusesTheDeploymentReplacesNothing(t *testing.T) {
	e, _, _ := newTestEnv(t)
	candidateRelease(t)
	dir := t.TempDir()
	binary := filepath.Join(dir, "zoomies")
	if err := os.WriteFile(binary, []byte("existing binary"), 0755); err != nil {
		t.Fatal(err)
	}
	_, reexecs := stubUpgradeSeams(t, binary, errors.New("the deployment needs a shared folder"))

	err := selfUpdate(context.Background(), e, binary, "v9.9.9", deploymentSelector{}, false, "")
	if err == nil || !strings.Contains(err.Error(), "needs a shared folder") || !strings.Contains(err.Error(), "left in place") {
		t.Fatalf("error: %v", err)
	}
	if b, _ := os.ReadFile(binary); string(b) != "existing binary" {
		t.Fatalf("binary = %q", b)
	}
	if entries, _ := os.ReadDir(dir); len(entries) != 1 {
		t.Fatalf("the folder holds more than the binary: %v", entries)
	}
	if len(*reexecs) != 0 {
		t.Fatalf("re-exec into a refused release: %q", *reexecs)
	}
}

// A check changes nothing, so an operator who typed --yes has already said what
// the preview was told; without it the candidate would refuse a layout change
// the preview let through, and advise the command that was just run.
func TestTheOperatorsYesReachesTheCandidatesCheckAndNothingElseDoes(t *testing.T) {
	for _, tc := range []struct {
		name    string
		yes     bool
		wantYes bool
	}{
		{"the operator passed --yes", true, true},
		{"the operator did not", false, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			e, _, _ := newTestEnv(t)
			candidateRelease(t)
			binary := filepath.Join(t.TempDir(), "zoomies")
			if err := os.WriteFile(binary, []byte("existing binary"), 0755); err != nil {
				t.Fatal(err)
			}
			calls, _ := stubUpgradeSeams(t, binary, nil)
			sel := deploymentSelector{AssumeYes: tc.yes}
			if err := selfUpdate(context.Background(), e, binary, "v9.9.9", sel, false, ""); err != nil {
				t.Fatal(err)
			}
			args := (*calls)[0].args
			if got := slices.Contains(args, "--yes"); got != tc.wantYes {
				t.Fatalf("--yes in %q = %v, want %v", args, got, tc.wantYes)
			}
			if !slices.Contains(args, "--non-interactive") || !slices.Contains(args, "--check") {
				t.Fatalf("the check must stay unattended and read-only: %q", args)
			}
		})
	}
}

// Each flag has to land in the field the candidate will be handed it as; a
// swapped runtime and image would send the check to the wrong deployment.
func TestEachDeploymentFlagLandsInItsOwnSelectorField(t *testing.T) {
	got := newDeploymentSelector("/etc/z", "unix:///d.sock", "podman", "img:tag", "agent", true)
	want := deploymentSelector{ConfigDir: "/etc/z", DockerHost: "unix:///d.sock", Runtime: "podman", Image: "img:tag", Mode: "agent", AssumeYes: true}
	if got != want {
		t.Fatalf("selector = %+v, want %+v", got, want)
	}
}

func scriptCandidate(t *testing.T, body string) string {
	t.Helper()
	if runtime.GOOS == "windows" {
		t.Skip("the fixture is a #!/bin/sh script, which Windows cannot execute")
	}
	path := filepath.Join(t.TempDir(), ".zoomies-update-fixture")
	if err := os.WriteFile(path, []byte("#!/bin/sh\n"+body+"\n"), 0o755); err != nil {
		t.Fatal(err)
	}
	return path
}

// The real runner, not the stub: the environment has to reach the child, and
// what it printed has to reach the person who is told why the upgrade stopped.
func TestTheCandidateRunsWithTheUpgradeMarkersAndItsRefusalIsCarried(t *testing.T) {
	path := scriptCandidate(t, `env | grep '^ZOOMIES_'; echo "needs a shared folder"; exit 1`)
	err := candidatePreflight("/usr/local/bin/zoomies", deploymentSelector{})(context.Background(), path)
	if err == nil {
		t.Fatal("a candidate that exits 1 passed the pre-flight")
	}
	for _, want := range []string{installer.SelfUpdateEnv + "=1", "needs a shared folder"} {
		if !strings.Contains(err.Error(), want) {
			t.Fatalf("error does not carry %q: %v", want, err)
		}
	}
	var refusal *candidateRefusal
	if !errors.As(err, &refusal) {
		t.Fatalf("a non-zero exit is the release refusing the deployment: %T", err)
	}
}

func TestACandidateThatSucceedsPassesThePreflight(t *testing.T) {
	path := scriptCandidate(t, `exit 0`)
	if err := candidatePreflight("/usr/local/bin/zoomies", deploymentSelector{})(context.Background(), path); err != nil {
		t.Fatal(err)
	}
}

// A page of output is for the person reading it; a runaway probe must not turn
// into an error message the size of a log file.
func TestOnlyTheEndOfACandidatesOutputIsCarried(t *testing.T) {
	path := scriptCandidate(t, `i=0; while [ $i -lt 4000 ]; do echo "line $i of the candidate's output"; i=$((i+1)); done; exit 1`)
	err := candidatePreflight("/usr/local/bin/zoomies", deploymentSelector{})(context.Background(), path)
	if err == nil {
		t.Fatal("expected a refusal")
	}
	msg := err.Error()
	if len(msg) > candidateOutputLimit+512 {
		t.Fatalf("error is %d bytes, want about %d", len(msg), candidateOutputLimit)
	}
	if !strings.Contains(msg, "line 3999 of") || strings.Contains(msg, "line 0 of") || !strings.Contains(msg, "...") {
		t.Fatalf("error is not the tail with a marker: %.200q", msg)
	}
	if !utf8.ValidString(msg) {
		t.Fatal("the cut landed inside a character")
	}
}

func tailOf(b []byte, limit int) string {
	t := tailBuffer{max: limit}
	_, _ = t.Write(b)
	return t.String()
}

func TestTheTailOfOutputIsCutOnACharacterBoundary(t *testing.T) {
	in := strings.Repeat("é", 100) // two bytes each, so an odd limit lands inside one
	got := tailOf([]byte(in), 51)
	if !utf8.ValidString(got) || !strings.HasPrefix(got, "...") || !strings.HasSuffix(got, "é") {
		t.Fatalf("tail = %q", got)
	}
	if short := tailOf([]byte("short"), 51); short != "short" {
		t.Fatalf("short output was changed: %q", short)
	}
}

// An unattended run has nobody to press Ctrl-C: a doctor probe that hangs in
// the candidate must end the upgrade, not hold it for ever.
func TestACandidateThatHangsIsStoppedAndSaidSo(t *testing.T) {
	old := candidateTimeout
	candidateTimeout = 300 * time.Millisecond
	t.Cleanup(func() { candidateTimeout = old })
	path := scriptCandidate(t, `exec sleep 30`)
	start := time.Now()
	err := candidatePreflight("/usr/local/bin/zoomies", deploymentSelector{})(context.Background(), path)
	if err == nil || !strings.Contains(err.Error(), "did not finish") {
		t.Fatalf("error: %v", err)
	}
	if elapsed := time.Since(start); elapsed > 10*time.Second {
		t.Fatalf("took %s to give up", elapsed)
	}
	var refusal *candidateRefusal
	if errors.As(err, &refusal) {
		t.Fatal("a timeout is not the release refusing the deployment")
	}
}

// A Ctrl-C during the check kills the child, which then exits non-zero like a
// refusal would. Telling the operator the release needs a change they must make
// would be wrong: they stopped it.
func TestInterruptingTheCheckIsNotTheReleaseRefusingTheDeployment(t *testing.T) {
	path := scriptCandidate(t, `exec sleep 30`)
	ctx, cancel := context.WithCancel(context.Background())
	time.AfterFunc(300*time.Millisecond, cancel)
	t.Cleanup(cancel)
	err := candidatePreflight("/usr/local/bin/zoomies", deploymentSelector{})(ctx, path)
	if err == nil {
		t.Fatal("an interrupted check passed the pre-flight")
	}
	var refusal *candidateRefusal
	if errors.As(err, &refusal) {
		t.Fatalf("an interrupt was reported as the release refusing the deployment: %v", err)
	}
}

// The advice has to fit what happened: --no-download is no answer to a release
// that needs a change, and --yes is no answer to an operator who passed it.
func TestARefusalFromTheCandidateSaysWhatToDo(t *testing.T) {
	for _, tc := range []struct {
		yes         bool
		want, avoid string
	}{
		{false, "zoomies upgrade --yes", "--no-download"},
		{true, "Follow the advice", "zoomies upgrade --yes"},
	} {
		e, _, _ := newTestEnv(t)
		candidateRelease(t)
		binary := filepath.Join(t.TempDir(), "zoomies")
		if err := os.WriteFile(binary, []byte("existing binary"), 0755); err != nil {
			t.Fatal(err)
		}
		stubUpgradeSeams(t, binary, &candidateRefusal{errors.New("exit status 1: the layout needs a shared folder")})
		err := selfUpdate(context.Background(), e, binary, "v9.9.9", deploymentSelector{AssumeYes: tc.yes}, false, "")
		if err == nil || !strings.Contains(err.Error(), tc.want) || strings.Contains(err.Error(), tc.avoid) {
			t.Fatalf("yes=%v: error: %v", tc.yes, err)
		}
	}
}

package main

import (
	"bufio"
	"context"
	"errors"
	"fmt"
	"io"
	"net/url"
	"os"
	"strings"

	"golang.org/x/term"
)

// runUsers is `zoomies users ...`. The API refuses to leave an instance with no
// enabled administrator, so this command does not have to police that itself --
// it just has to report the refusal clearly when it comes.
func runUsers(ctx context.Context, e *env, args []string) error {
	return runGroup(ctx, e, "users", "User accounts.", []*subcommand{
		{"list", "", "Every account and its role", usersList},
		{"create", "--username <n> --role <r>", "Create an account", usersCreate},
		{"passwd", "<user-id>", "Set an account's password", usersPasswd},
		{"reset-two-step", "<user-id>", "Turn off an account's two-step verification", usersResetTwoStep},
		{"delete", "<user-id>", "Delete an account", usersDelete},
	}, args)
}

// usersPasswd is the administrator's reset, from a terminal.
//
// The password is read from the terminal, or from standard input when it is
// piped in; there is deliberately no --password flag. A password in argv is a
// password in /proc/<pid>/cmdline, which every account on the host can read,
// and in the operator's shell history afterwards.
func usersPasswd(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies users passwd <user-id>",
		"Set an account's password. Every session it had ends, and its owner is asked to choose their own at the next sign-in.")
	cf := registerClientFlags(fs, false)
	fs.example(
		"zoomies users passwd usr_7f3a",
		`printf '%s' "$new" | zoomies users passwd usr_7f3a`,
	)
	if err := fs.parse(args); err != nil {
		return err
	}
	id, err := fs.oneArg("a user ID, as shown by `zoomies users list`")
	if err != nil {
		return err
	}
	password, err := readSecret(e, "New password: ")
	if err != nil {
		return err
	}
	if password == "" {
		return usagef("users passwd", "no password was given; type one at the prompt or pipe one in")
	}

	client, err := cf.client()
	if err != nil {
		return err
	}
	body := map[string]any{"new_password": password}
	if _, err := client.post(ctx, "/users/"+url.PathEscape(id)+"/password", nil, body, nil); err != nil {
		return err
	}
	fmt.Fprintf(e.out, "Set a new password for %s. Their sessions have ended, and they choose their own at the next sign-in.\n", id)
	return nil
}

// readSecret reads one line, without echoing it when there is a terminal to
// turn the echo off on, and from standard input otherwise -- which is what
// makes the piped form work in a script.
func readSecret(e *env, prompt string) (string, error) {
	if f, ok := e.in.(*os.File); ok && term.IsTerminal(int(f.Fd())) {
		fmt.Fprint(e.err, prompt)
		typed, err := term.ReadPassword(int(f.Fd()))
		fmt.Fprintln(e.err)
		if err != nil {
			return "", fmt.Errorf("reading the password: %w", err)
		}
		return strings.TrimSpace(string(typed)), nil
	}
	line, err := bufio.NewReader(e.in).ReadString('\n')
	if err != nil && !errors.Is(err, io.EOF) {
		return "", fmt.Errorf("reading the password from standard input: %w", err)
	}
	return strings.TrimSpace(line), nil
}

func usersList(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies users list", "List the accounts that can sign in.")
	cf := registerClientFlags(fs, true)
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}

	var out listResponse[userItem]
	raw, err := client.get(ctx, "/users", nil, &out)
	if err != nil {
		return err
	}
	if p.structured() {
		return p.emit(raw)
	}
	if len(out.Items) == 0 {
		p.note("No users. This instance still needs its first administrator; open the UI to create one.")
		return nil
	}

	rows := make([][]string, 0, len(out.Items))
	for _, u := range out.Items {
		state := "enabled"
		if u.Disabled {
			state = p.paint(colourDim, "disabled")
		}
		if u.MustChangePassword {
			state += p.paint(colourYellow, " (must change password)")
		}
		rows = append(rows, []string{
			u.Username,
			u.ID,
			u.Role,
			dash(u.DisplayName),
			dash(u.Email),
			state,
			p.relTimePtr(u.LastLoginAt),
		})
	}
	p.table([]string{"username", "id", "role", "name", "email", "state", "last login"}, rows)
	return nil
}

func usersCreate(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies users create --username <name> --role <viewer|operator|admin|platform>",
		"Create an account. Omit --password for one that will sign in through single sign-on.")
	cf := registerClientFlags(fs, true)
	username := fs.String("username", "", "the account's login name (required)")
	password := fs.String("password", "", "an initial password of at least 12 characters; omit for an SSO-only account")
	email := fs.String("email", "", "the account's email address")
	displayName := fs.String("display-name", "", "how the account's name is shown")
	role := fs.String("role", "viewer", "viewer, operator, admin or platform")
	fs.example(
		"zoomies users create --username alex --role operator --email alex@example.com",
		"zoomies users create --username ci-readonly --role viewer",
	)
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	if strings.TrimSpace(*username) == "" {
		return usagef("users create", "needs --username")
	}
	if !validRole(*role) {
		return usagef("users create", "--role %q is not a role; use viewer, operator or admin", *role)
	}

	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}

	body := map[string]any{"username": *username, "role": *role}
	if *password != "" {
		body["password"] = *password
	}
	if *email != "" {
		body["email"] = *email
	}
	if *displayName != "" {
		body["display_name"] = *displayName
	}

	var user userItem
	raw, err := client.post(ctx, "/users", nil, body, &user)
	if err != nil {
		return err
	}
	if p.structured() {
		return p.emit(raw)
	}
	fmt.Fprintf(e.out, "Created %s (%s) as %s.\n", user.Username, user.ID, user.Role)
	if *password == "" {
		fmt.Fprintln(e.out, "No password was set, so this account can only sign in through single sign-on.")
	}
	return nil
}

// usersResetTwoStep is the administrator's answer to a lost phone: the
// account's authenticator secret and recovery codes are removed and its
// sessions end, so its owner signs in with the password alone -- or, where the
// instance requires two-step, sets it up again at that sign-in.
func usersResetTwoStep(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies users reset-two-step <user-id>",
		"Turn off two-step verification for an account whose owner has lost their authenticator and their recovery codes. Its sessions end, and the reset is audited.")
	cf := registerClientFlags(fs, false)
	fs.example("zoomies users reset-two-step usr_7f3a")
	if err := fs.parse(args); err != nil {
		return err
	}
	id, err := fs.oneArg("a user ID, as shown by `zoomies users list`")
	if err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	if _, err := client.del(ctx, "/users/"+url.PathEscape(id)+"/two-step", nil, nil); err != nil {
		return err
	}
	fmt.Fprintf(e.out, "Reset two-step verification for %s. Their sessions have ended; they sign in with their password next time.\n", id)
	return nil
}

func usersDelete(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies users delete <user-id>",
		"Delete an account. Refused if it would leave the instance with no enabled administrator.")
	cf := registerClientFlags(fs, false)
	if err := fs.parse(args); err != nil {
		return err
	}
	id, err := fs.oneArg("a user ID, as shown by `zoomies users list`")
	if err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	if _, err := client.del(ctx, "/users/"+url.PathEscape(id), nil, nil); err != nil {
		return err
	}
	fmt.Fprintf(e.out, "Deleted user %s.\n", id)
	return nil
}

func validRole(role string) bool {
	switch strings.ToLower(strings.TrimSpace(role)) {
	case "viewer", "operator", "admin", "platform":
		return true
	}
	return false
}

package main

import (
	"context"
	"errors"
	"fmt"
	"net/url"
	"regexp"
	"strconv"
	"strings"
)

// codedExit carries a command's documented exit code through report: why's 2
// for a job this fleet never saw and 3 for a class the fleet could not
// decide, kennel check's 4 for findings. It is the same seam doctorExit uses,
// so a command-specific outcome never has to be a string the dispatcher
// parses back.
type codedExit struct {
	code int
	msg  string
}

func (w *codedExit) Error() string { return w.msg }

const (
	codedExitNotFound = 2
	codedExitUnknown  = 3
)

// githubJobURL is the two shapes of URL a person has in their clipboard: the
// run, or a job inside it. GitHub's run ID keys a run only within one
// repository, which is why the repository travels with it to the list.
var githubJobURL = regexp.MustCompile(`^https?://github\.com/([^/]+/[^/]+)/actions/runs/(\d+)(?:/jobs?/(\d+))?`)

// runWhy answers "why did this job fail, stall or run slow" from the
// controller's explanation and nothing else: the CLI lays the answer out,
// it does not reason about the fleet, so it and the drawer cannot disagree.
func runWhy(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies why <job> | --latest-failed", "Why a job failed, stalled or is waiting.")
	latestFailed := fs.Bool("latest-failed", false, "explain the newest failed job instead of a named one")
	repo := fs.String("repo", "", "with --latest-failed, only this repository (owner/name)")
	pool := fs.String("pool", "", "with --latest-failed, only jobs this pool claimed (a pool ID)")
	logs := fs.Int("logs", 12, "how many of the runner's last lines to quote, ending on the one that decided the class")
	noLogs := fs.Bool("no-logs", false, "quote none of the runner's output")
	cf := registerClientFlags(fs, true)
	fs.example(
		"zoomies why job_01abc",
		"zoomies why https://github.com/acme/widgets/actions/runs/1234/job/5678",
		"zoomies why --latest-failed --repo acme/widgets",
		"zoomies why job_01abc --output json",
	)
	if err := fs.parse(args); err != nil {
		return err
	}
	var arg string
	if *latestFailed {
		if err := fs.noMoreArgs(); err != nil {
			return err
		}
	} else {
		id, err := fs.oneArg("a job ID, a GitHub run or job URL, or --latest-failed")
		if err != nil {
			return err
		}
		arg = id
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}

	id, err := resolveJob(ctx, client, arg, *latestFailed, *repo, *pool)
	if err != nil {
		return err
	}
	q := url.Values{}
	if *noLogs {
		q.Set("logs", "0")
	} else {
		q.Set("logs", strconv.Itoa(*logs))
	}
	var why explanationItem
	raw, err := client.get(ctx, "/jobs/"+url.PathEscape(id)+"/explanation", q, &why)
	if err != nil {
		var ae *apiError
		if errors.As(err, &ae) && ae.status == 404 {
			return &codedExit{code: codedExitNotFound, msg: fmt.Sprintf("no job %s here; `zoomies jobs list` shows what this fleet saw", id)}
		}
		return err
	}
	// A controller from before why answers without a class. Laying that
	// out as "Class:  ()" would read as a diagnosis, and exit 0 as success.
	if why.Class == "" {
		return errors.New("this controller's explanation carries no class, so it predates zoomies why; upgrade the controller")
	}
	if p.structured() {
		if err := p.emit(raw); err != nil {
			return err
		}
	} else {
		printWhy(p, &why)
	}
	if why.Class == "unknown" {
		return &codedExit{code: codedExitUnknown}
	}
	return nil
}

// resolveJob turns what the person typed into a job ID: an ID as it is, a
// GitHub URL through the jobs list by repository and run, --latest-failed
// through the failed list. Nothing found is why's own exit 2, with the
// command that shows what the fleet did see.
func resolveJob(ctx context.Context, client *apiClient, arg string, latestFailed bool, repo, pool string) (string, error) {
	type listed struct {
		ID          string `json:"id"`
		GitHubJobID int64  `json:"github_job_id"`
	}
	q := url.Values{"include_steps": {"false"}}
	wantJob := int64(0)
	var hint string
	switch {
	case latestFailed:
		q.Set("failed", "true")
		if repo != "" {
			q.Set("repo", repo)
		}
		if pool != "" {
			q.Set("pool_id", pool)
		}
		hint = "no failed job matches; `zoomies jobs list --failed` shows what this fleet saw"
	case githubJobURL.MatchString(arg):
		m := githubJobURL.FindStringSubmatch(arg)
		q.Set("repo", m[1])
		q.Set("run_id", m[2])
		if m[3] != "" {
			wantJob, _ = strconv.ParseInt(m[3], 10, 64)
		}
		hint = fmt.Sprintf("no job matches %s; `zoomies jobs list --repo %s` shows what this fleet saw", arg, m[1])
	default:
		return arg, nil
	}
	var page listResponse[listed]
	if _, err := client.get(ctx, "/jobs", q, &page); err != nil {
		return "", err
	}
	for _, j := range page.Items {
		if wantJob == 0 || j.GitHubJobID == wantJob {
			return j.ID, nil
		}
	}
	return "", &codedExit{code: codedExitNotFound, msg: hint}
}

// printWhy lays the explanation out for a person: the sentence, the class,
// the facts, the lines, the steps. Every string came from the controller,
// which scrubbed it, and goes through plain again here because the terminal
// is the one place a stray escape does damage.
func printWhy(p *printer, why *explanationItem) {
	fmt.Fprintln(p.out, plain(why.Summary))
	if why.Detail != "" {
		fmt.Fprintln(p.out, plain(why.Detail))
	}
	if why.Fix != "" {
		fmt.Fprintln(p.out, p.paint(colourYellow, "Fix: ")+plain(why.Fix))
	}
	class := fmt.Sprintf("%s (%s)", plain(why.Class), plain(why.Confidence))
	if why.ConfidenceReason != "" {
		class += ": " + plain(why.ConfidenceReason)
	}
	fmt.Fprintln(p.out)
	fmt.Fprintln(p.out, p.paint(colourYellow, "Class: ")+class)
	if why.ProblemCode != "" {
		fmt.Fprintln(p.out, p.paint(colourYellow, "Code: ")+plain(why.ProblemCode))
	}
	if len(why.Evidence) > 0 {
		fmt.Fprintln(p.out)
		fmt.Fprintln(p.out, p.paint(colourYellow, "Evidence:"))
		for _, ev := range why.Evidence {
			line := "  " + plain(ev.Label) + ": " + plain(ev.Value)
			if ev.Unit != "" {
				line += " " + plain(ev.Unit)
			}
			if ev.Ref != "" {
				line += "  (" + plain(ev.Ref) + ")"
			}
			fmt.Fprintln(p.out, line)
		}
	}
	if why.LogExcerpt != nil {
		fmt.Fprintln(p.out)
		if n := len(why.LogExcerpt.Lines); n > 0 {
			fmt.Fprintf(p.out, "%s lines %d to %d of the runner's output:\n", p.paint(colourYellow, "Output:"), why.LogExcerpt.Lines[0].N, why.LogExcerpt.Lines[n-1].N)
			for _, l := range why.LogExcerpt.Lines {
				mark := "  "
				if l.Decisive {
					mark = "> "
				}
				fmt.Fprintf(p.out, "%s%d  %s\n", mark, l.N, plain(l.Text))
			}
		}
		if why.LogExcerpt.Note != "" {
			fmt.Fprintln(p.out, "  "+plain(why.LogExcerpt.Note))
		}
	}
	var read []string
	n := 0
	for _, s := range why.NextSteps {
		if s.Kind == "read" && strings.HasPrefix(s.Link, "https://") {
			read = append(read, plain(s.Link))
			continue
		}
		if n == 0 {
			fmt.Fprintln(p.out)
			fmt.Fprintln(p.out, p.paint(colourYellow, "Next:"))
		}
		n++
		line := fmt.Sprintf("  %d. %s", n, plain(s.Text))
		if s.Link != "" {
			line += "  (" + plain(s.Link) + ")"
		}
		fmt.Fprintln(p.out, line)
	}
	for _, r := range read {
		fmt.Fprintln(p.out, p.paint(colourYellow, "Read: ")+r)
	}
}

