  inset: 0;
}
.logo.lockup .art img {
  padding: var(--z-logo-scene-padding);
  box-sizing: border-box;
}
.logo .art img {
  position: relative;
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.logo[data-treatment='pearl'] .art::before {
  background-image: var(--z-logo-pearl);
}
.logo[data-treatment='orbital'] .art::before {
  background-image: var(--z-logo-orbital);
}
.logo .art .white {
  display: none;
}
:root[data-theme='dark'] .logo .black {
  display: none;
}
:root[data-theme='dark'] .logo .white {
  display: block;
}
.logo .wordmark {
  display: block;
  height: var(--word-h);
  aspect-ratio: 1128 / 226;
  background: currentColor;
  mask: url('/brand/wordmark-black-transparent.svg') left center / contain no-repeat;
}

/* Button, from Button.svelte. */
.m-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--z-space-2);
  border: var(--z-border-width) solid transparent;
  border-radius: var(--z-radius-md);
  font-family: inherit;
  font-weight: var(--z-weight-medium);
  line-height: 1;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background-color var(--z-motion-fast) var(--z-ease),
    border-color var(--z-motion-fast) var(--z-ease),
    color var(--z-motion-fast) var(--z-ease);
}
.m-btn[aria-disabled='true'] {
  cursor: not-allowed;
  opacity: 0.55;
  pointer-events: none;
}
.m-btn--full {
  width: 100%;
}
.m-btn--sm {
  height: var(--z-space-6);
  padding: 0 var(--z-space-2);
  font-size: var(--z-text-xs);
}
.m-btn--md {
  height: var(--z-space-8);
  padding: 0 var(--z-space-3);
  font-size: var(--z-text-sm);
}
.m-btn--lg {
  height: var(--z-space-10);
  padding: 0 var(--z-space-4);
  font-size: var(--z-text-base);
}
@media (pointer: coarse) {
  .m-btn--lg {
    height: var(--z-control-touch);
  }
}
.m-btn--primary {
  background: var(--z-accent);
  color: var(--z-accent-contrast);
}
.m-btn--primary:hover {
  background: var(--z-accent-hover);
}
.m-btn--primary:active {
  background: var(--z-accent-active);
}
.m-btn--secondary {
  background: var(--z-surface);
  color: var(--z-text);
  border-color: var(--z-border-strong);
}
.m-btn--secondary:hover {
  background: var(--z-surface-hover);
}
.m-btn--ghost {
  background: transparent;
  color: var(--z-text-muted);
}
.m-btn--ghost:hover {
  background: var(--z-surface-hover);
  color: var(--z-text);
}
.m-btn-content {
  display: inline-flex;
  align-items: center;
  gap: var(--z-space-2);
}
.m-btn-content.is-hidden {
  visibility: hidden;
}
.m-spinner {
  position: absolute;
  inset: 0;
  margin: auto;
  width: var(--z-control-icon);
  height: var(--z-control-icon);
  border: var(--z-border-width-thick) solid currentColor;
  border-top-color: transparent;
  border-radius: var(--z-radius-full);
}
.m-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--z-space-8);
  height: var(--z-space-8);
  padding: 0;
  border: 0;
  border-radius: var(--z-radius-sm);
  background: transparent;
  color: var(--z-text-muted);
  cursor: pointer;
}
.m-icon-btn:hover {
  background: var(--z-surface-hover);
  color: var(--z-text);
}

/* Field and Input, from Field.svelte and Input.svelte. */
.m-field {
  display: flex;
  flex-direction: column;
  gap: var(--z-space-2);
}
.m-label {
  font-size: var(--z-text-xs);
  font-weight: var(--z-weight-medium);
  color: var(--z-text-muted);
}
.m-required {
  color: var(--z-danger);
  margin-inline-start: var(--z-nudge-2);
}
.m-hint,
.m-notice,
.m-error {
  font-size: var(--z-text-xs);
  line-height: var(--z-leading-xs);
}
.m-hint {
  color: var(--z-text-subtle);
}
/* Muted, not a status colour: caps lock is not an alarm, and the status
   palette is a fixed mapping operators learn. */
.m-notice {
  color: var(--z-text-muted);
  font-weight: var(--z-weight-medium);
}
.m-error {
  color: var(--z-danger);
}
.m-input-wrap {
  position: relative;
  display: flex;
  align-items: center;
}
.m-input {
  width: 100%;
  font-family: var(--z-font-sans);
  font-size: var(--z-text-base);
  color: var(--z-text);
  background: var(--z-surface);
  border: var(--z-border-width) solid var(--z-border-strong);
  border-radius: var(--z-radius-sm);
}
.m-input--sm {
  height: var(--z-space-6);
  padding: 0 var(--z-space-2);
  font-size: var(--z-text-sm);
}
.m-input--md {
  height: var(--z-space-8);
  padding: 0 var(--z-space-3);
}
.m-input--lg {
  height: var(--z-space-10);
  padding: 0 var(--z-space-3);
}
.has-trailing .m-input--md {
  padding-right: var(--z-space-8);
}
.has-trailing .m-input--lg {
  padding-right: var(--z-space-10);
}
.m-input--mono {
  font-family: var(--z-font-mono);
  font-size: var(--z-text-sm);
}
.m-input:hover:not(:disabled) {
  border-color: var(--z-text-subtle);
}
.m-input:disabled {
  background: var(--z-surface-sunken);
  color: var(--z-text-subtle);
  cursor: not-allowed;
}
.m-input[aria-invalid='true'] {
  border-color: var(--z-danger);
}
.m-trailing {
  position: absolute;
  right: var(--z-space-1);
  display: inline-flex;
  align-items: center;
}
/* iOS zooms a page when a focused field is under 16px. */
@media (max-width: 768px) {
  .m-input,
  .m-input--mono {
    font-size: var(--z-control-font-touch);
  }
}

/* Callout: the one banner. A failure is danger; a note is quiet. */
.m-callout {
  display: flex;
  align-items: flex-start;
  gap: var(--z-space-2);
  padding: var(--z-space-3);
  border: var(--z-border-width) solid var(--z-border);
  border-radius: var(--z-radius-md);
  font-size: var(--z-text-sm);
  line-height: var(--z-leading-sm);
  color: var(--z-text);
}
.m-callout .icon {
  margin-top: var(--z-nudge-3);
}
.m-callout-body {
  min-width: 0;
  overflow-wrap: anywhere;
}
.m-callout-body p + p {
  margin-top: var(--z-space-2);
}
.m-callout--danger {
  border-color: var(--z-danger-border);
  background: var(--z-danger-subtle);
}
.m-callout--danger .icon {
  color: var(--z-danger);
}
.m-callout--neutral {
  color: var(--z-text-muted);
}

/* Links and small furniture. */
.m-link {
  color: var(--z-accent);
  text-decoration: underline;
  text-underline-offset: var(--z-underline-offset);
}
.m-link:hover {
  color: var(--z-accent-hover);
}
/* "Start again" reads as a link in a sentence and is a button because it
   changes the page rather than going anywhere. */
.m-linkish {
  padding: 0;
  border: 0;
  background: none;
  color: var(--z-accent);
  font: inherit;
  text-decoration: underline;
  text-underline-offset: var(--z-underline-offset);
  cursor: pointer;
}
.m-linkish:hover {
  color: var(--z-accent-hover);
}
.m-divider {
  display: flex;
  align-items: center;
  gap: var(--z-space-3);
  color: var(--z-text-subtle);
  font-size: var(--z-text-xs);
}
.m-divider::before,
.m-divider::after {
  content: '';
  flex: 1;
  height: var(--z-border-width);
  background: var(--z-border);
}
.m-note {
  font-size: var(--z-text-xs);
  line-height: var(--z-leading-xs);
  color: var(--z-text-muted);
  text-wrap: pretty;
}
.m-host {
  overflow-wrap: anywhere;
  min-width: 0;
}
.m-stack {
  display: flex;
  flex-direction: column;
  gap: var(--z-space-4);
}
.m-details {
  border-top: var(--z-border-width) solid var(--z-border);
  padding-top: var(--z-space-2);
  color: var(--z-text-muted);
  font-size: var(--z-text-xs);
  line-height: var(--z-leading-base);
}
.m-details summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: var(--z-control-touch);
  cursor: pointer;
  list-style: none;
}
.m-details summary::-webkit-details-marker {
  display: none;
}
.m-details summary::after {
  content: '+';
  font-size: var(--z-text-lg);
}
.m-details[open] summary::after {
  content: '\2212';
}
.m-details p {
  margin-top: var(--z-space-3);
}

/* Where the form is the page (sign in, first account): the product makes every
   field and button here a full touch target, on a desktop as well. */
.m-form-page .m-input {
  min-height: var(--z-space-12);
  font-size: var(--z-control-font-touch);
}
.m-form-page .m-btn {
  min-height: var(--z-space-12);
  white-space: normal;
  overflow-wrap: anywhere;
}
.m-form-page .m-icon-btn {
  width: var(--z-control-touch);
  height: var(--z-control-touch);
}
.m-form-page .has-trailing .m-input {
  padding-right: calc(var(--z-control-touch) + var(--z-space-2));
}
.m-form-page form {
  display: flex;
  flex-direction: column;
  gap: var(--z-space-4);
}

/* Links to the project, as a brand panel and the footers carry them. */
.m-links {
  display: flex;
  flex-wrap: wrap;
  gap: var(--z-space-3) var(--z-space-5);
  font-size: var(--z-text-xs);
}
.m-links a {
  display: inline-flex;
  align-items: center;
  gap: var(--z-space-2);
  color: inherit;
  text-decoration: none;
}
.m-links a:hover {
  text-decoration: underline;
}
.m-credit {
  flex-basis: 100%;
}
.m-credit a {
  font-weight: var(--z-weight-semibold);
}

/* Two-step: setting up an authenticator, and the recovery codes. */
.m-steps {
  display: flex;
  flex-direction: column;
  gap: var(--z-space-6);
  margin: 0;
  padding: 0;
  list-style: none;
}
.m-step-title {
  display: flex;
  align-items: center;
  gap: var(--z-space-2);
  margin-bottom: var(--z-space-3);
  font-size: var(--z-text-sm);
  font-weight: var(--z-weight-semibold);
}
.m-scan {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: var(--z-space-5);
}
.m-key-side {
  display: flex;
  flex: 1 1 12rem;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--z-space-3);
  min-width: 0;
}
.qr {
  flex: none;
  border: var(--z-border-width) solid var(--z-border-strong);
  border-radius: var(--z-radius-md);
}
.m-codes {
  display: flex;
  flex-direction: column;
  gap: var(--z-space-3);
  padding: var(--z-space-4);
  border: var(--z-border-width) solid var(--z-border);
  border-radius: var(--z-radius-md);
  background: var(--z-surface-sunken);
}
.m-codes-heading {
  display: flex;
  align-items: center;
  gap: var(--z-space-2);
  font-weight: var(--z-weight-semibold);
}
.m-code-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--z-space-2) var(--z-space-4);
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: var(--z-text-sm);
}
.m-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--z-space-2);
}

/* A ghost button beside a paragraph aligns its text with the paragraph, not its own padding. */
.m-key-side .m-btn--ghost {
  margin-left: calc(-1 * var(--z-space-3));
}

/* Where to find the setup token: the commands as tabs, from native radios. The
   radio covers its own label so a press lands on it and the arrow keys move
   between the tabs. It is invisible, and a ring drawn on something invisible is
   not there, so the label draws the ring itself. :has() picks the panel to show. */
.m-install {
  display: flex;
  flex-direction: column;
  gap: var(--z-space-2);
}
.m-install-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: var(--z-space-1);
}
.m-install-tab {
  position: relative;
  display: inline-flex;
  align-items: center;
  min-height: var(--z-space-8);
  padding: 0 var(--z-space-3);
  border: var(--z-border-width) solid var(--z-border);
  border-radius: var(--z-radius-sm);
  background: var(--z-surface);
  color: var(--z-text-muted);
  font-size: var(--z-text-xs);
  font-weight: var(--z-weight-medium);
  cursor: pointer;
}
.m-install-tab input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  opacity: 0;
  cursor: pointer;
}
.m-install-tab:has(input:focus-visible) {
  outline: var(--z-focus-width) solid var(--z-focus-colour);
  outline-offset: var(--z-focus-offset);
}
.m-install-tab:has(input:checked) {
  border-color: var(--z-accent);
  background: var(--z-accent-subtle);
  color: var(--z-text);
}
.m-install-panel {
  display: none;
  align-items: center;
  gap: var(--z-space-3);
  padding: var(--z-space-2) var(--z-space-3);
  border-radius: var(--z-radius-sm);
  background: var(--z-surface-sunken);
}
.m-install:has(input[value='compose']:checked) .p-compose,
.m-install:has(input[value='init']:checked) .p-init,
.m-install:has(input[value='systemd']:checked) .p-systemd,
.m-install:has(input[value='other']:checked) .p-other {
  display: flex;
}
.m-command {
  flex: 1;
  min-width: 0;
  overflow-wrap: anywhere;
  font-size: var(--z-text-xs);
  color: var(--z-text);
}
.m-callout-body .m-btn {
  margin-top: var(--z-space-3);
}

/* The product's touch minimum is for fields and the one button a form is for.
   A Copy button beside a command stays the size of the command. */
.m-form-page .m-install-panel .m-btn {
  min-height: var(--z-space-8);
}

/* Radios, as RadioGroup draws them: the browser's own control in the accent. */
.m-radios {
  display: flex;
  flex-direction: column;
  gap: var(--z-space-3);
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}
.m-radios legend {
  padding: 0;
  margin-bottom: var(--z-space-2);
}
.m-radio {
  display: flex;
  align-items: flex-start;
  gap: var(--z-space-3);
  cursor: pointer;
}
.m-radio input {
  flex: none;
  width: var(--z-control-box);
  height: var(--z-control-box);
  margin: var(--z-nudge-2) 0 0;
  accent-color: var(--z-accent);
}
.m-radio-text {
  display: flex;
  flex-direction: column;
  gap: var(--z-nudge-2);
  min-width: 0;
}
.m-radio-label {
  font-size: var(--z-text-base);
  color: var(--z-text);
  overflow-wrap: anywhere;
}
.m-radio-desc {
  font-size: var(--z-text-sm);
  line-height: var(--z-leading-sm);
  color: var(--z-text-muted);
}

/* A loading state is shapes where the words will be, and never moves. */
.m-skeleton-group {
  display: flex;
  flex-direction: column;
  gap: var(--z-space-3);
}
.m-skeleton {
  display: block;
  border-radius: var(--z-radius-sm);
  background: var(--z-surface-sunken);
}
.m-skeleton--title {
  width: 60%;
  height: var(--z-leading-xl);
}
.m-skeleton--line {
  height: var(--z-space-4);
}
.m-skeleton--short {
  width: 90%;
}
.m-skeleton--block {
  height: 7.5rem;
}

/* Connect an app: the pieces the three concepts share. The client names itself
   and the redirect is whatever it registered, so both wrap wherever they must. */
.ca-client,
.ca-host {
  overflow-wrap: anywhere;
}
.ca-muted {
  font-size: var(--z-text-base);
  line-height: var(--z-leading-base);
  color: var(--z-text-muted);
}
.ca-actions {
  display: flex;
  justify-content: flex-end;
  gap: var(--z-space-3);
  margin-top: var(--z-space-2);
}
@media (max-width: 768px) {
  .ca-actions {
    flex-direction: column-reverse;
  }
  .ca-actions > * {
    width: 100%;
  }
}

/* Fleet status, as StatusPage.svelte draws it: the three tones, the shapes that
   carry the state without colour, the queue's tiles, and the reasons with a rail
   coloured by how serious each is. */
.m-tone-idle {
  background: var(--z-idle-subtle);
  border-color: var(--z-idle-border);
  color: var(--z-idle);
}
.m-tone-pending {
  background: var(--z-pending-subtle);
  border-color: var(--z-pending-border);
  color: var(--z-pending);
}
.m-tone-danger {
  background: var(--z-danger-subtle);
  border-color: var(--z-danger-border);
  color: var(--z-danger);
}
.m-shape {
  flex: none;
  fill: none;
  stroke: currentColor;
  stroke-width: var(--z-border-width-thick);
}
.m-shape[data-shape='triangle'] {
  fill: currentColor;
}
.m-shape .dashed {
  stroke-dasharray: 4 3;
}
.m-state {
  display: flex;
  align-items: flex-start;
  gap: var(--z-space-4);
  padding: var(--z-space-5);
  border: var(--z-border-width) solid;
  border-radius: var(--z-radius-lg);
}
.m-state-word {
  font-size: var(--z-text-xl);
  line-height: var(--z-leading-xl);
  font-weight: var(--z-weight-bold);
  text-transform: capitalize;
}
.m-facts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--z-space-3);
  margin: 0;
}
.m-tile {
  padding: var(--z-space-3);
  border: var(--z-border-width) solid var(--z-border);
  border-radius: var(--z-radius-md);
  background: var(--z-surface);
}
.m-tile dt {
  font-size: var(--z-text-xs);
  color: var(--z-text-muted);
}
.m-tile dd {
  margin: 0;
  font-weight: var(--z-weight-semibold);
}
.m-reasons {
  display: grid;
  gap: var(--z-space-2);
  margin: 0;
  padding: 0;
  list-style: none;
}
.m-reason {
  display: grid;
  gap: var(--z-space-1);
  padding: var(--z-space-3);
  border: var(--z-border-width) solid var(--z-border);
  border-left-width: var(--z-border-width-rail);
  border-radius: var(--z-radius-md);
  background: var(--z-surface);
}
.m-reason.sev-error {
  border-left-color: var(--z-danger);
}
.m-reason.sev-warning {
  border-left-color: var(--z-pending);
}
.m-sev {
  font-size: var(--z-text-xs);
  font-weight: var(--z-weight-semibold);
}
.sev-error .m-sev {
  color: var(--z-danger);
}
.sev-warning .m-sev {
  color: var(--z-pending);
}
.m-sentence {
  overflow-wrap: anywhere;
}
.m-meta {
  font-size: var(--z-text-xs);
  color: var(--z-text-muted);
}
.m-meta code {
  font-family: var(--z-font-mono);
}
.fs-appearance {
  position: absolute;
  top: var(--z-space-4);
  right: var(--z-space-4);
}
.fs-head h1 {
  font-size: var(--z-text-2xl);
  line-height: var(--z-leading-2xl);
  font-weight: var(--z-weight-bold);
}
.fs-h2 {
  margin-bottom: var(--z-space-2);
  font-size: var(--z-text-lg);
  line-height: var(--z-leading-lg);
  font-weight: var(--z-weight-semibold);
}
.fs-headline {
  color: var(--z-text);
}
.fs-since,
.fs-note,
.fs-foot {
  color: var(--z-text-muted);
}
.fs-foot {
  font-size: var(--z-text-xs);
}
.fs-count {
  display: inline-block;
  min-width: var(--z-space-5);
  padding: 0 var(--z-space-2);
  border-radius: var(--z-radius-full);
  background: var(--z-surface-sunken);
  color: var(--z-text-muted);
  font-size: var(--z-text-xs);
  font-weight: var(--z-weight-medium);
  text-align: center;
}

/*
 * Concept A, evolution. Sign in keeps its split layout; a phone gets one
 * compact brand header in place of the black stage that pushed the button below
 * the fold, and the instance being signed in to becomes the line under the title.
 */
.s-a {
  position: relative;
  display: grid;
  grid-template-columns: clamp(20rem, 40vw, 36rem) minmax(0, 1fr);
  min-height: 100%;
  background: var(--z-surface);
}
.s-a .a-brand {
  display: flex;
  flex-direction: column;
  gap: var(--z-space-12);
  padding: var(--z-space-12);
  border-right: var(--z-border-width) solid var(--z-border);
}
/* The backdrop is a glow drawn for a dark ground, so the lockup sits on Zoomies
   Black in both themes: a stage, not a column. */
.s-a .a-stage {
  display: flex;
  justify-content: center;
  align-self: center;
  box-sizing: border-box;
  width: fit-content;
  max-width: 100%;
  padding: var(--z-space-4);
  border-radius: var(--z-radius-lg);
  background: var(--z-panel-bg);
}
.s-a .a-pitch {
  margin-block: auto;
  max-width: 22rem;
}
.s-a .a-eyebrow {
  margin-bottom: var(--z-space-5);
  font-size: var(--z-text-2xs);
  font-weight: var(--z-weight-semibold);
  letter-spacing: var(--z-tracking-wider);
  text-transform: uppercase;
  color: var(--z-text-muted);
}
.s-a .a-tagline {
  font-size: var(--z-text-3xl);
  line-height: var(--z-leading-3xl);
  font-weight: var(--z-weight-semibold);
  letter-spacing: var(--z-tracking-tight);
}
.s-a .a-rule {
  width: var(--z-space-10);
  height: var(--z-border-width-thick);
  margin-block: var(--z-space-8);
  background: var(--z-brand-runner-blue);
}
.s-a .a-pitch-lede {
  font-size: var(--z-text-base);
  line-height: var(--z-leading-lg);
  color: var(--z-text-muted);
}
.s-a .a-brand .m-links {
  color: var(--z-text-muted);
}
.s-a .a-form {
  display: flex;
  flex-direction: column;
  min-width: 0;
  padding: var(--z-space-16) var(--z-space-8) var(--z-space-6);
}
.s-a .a-mark {
  display: none;
}
.s-a .a-column {
  display: flex;
  flex-direction: column;
  gap: var(--z-space-4);
  width: 100%;
  max-width: var(--z-width-dialog-sm);
  min-width: 0;
  margin: auto;
}
.s-a .a-head {
  display: flex;
  flex-direction: column;
  gap: var(--z-space-1);
  margin-bottom: var(--z-space-2);
}
.s-a h1 {
  font-size: var(--z-text-2xl);
  line-height: var(--z-leading-2xl);
  font-weight: var(--z-weight-semibold);
  letter-spacing: var(--z-tracking-tight);
}
.s-a .a-lede {
  font-size: var(--z-text-base);
  line-height: var(--z-leading-base);
  color: var(--z-text-muted);
  text-wrap: pretty;
  overflow-wrap: anywhere;
}
.s-a .a-lede .m-host {
  color: var(--z-text);
  font-weight: var(--z-weight-medium);
}
.s-a .a-meta {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: var(--z-space-2) var(--z-space-4);
  margin-top: var(--z-space-8);
  color: var(--z-text-subtle);
  font-size: var(--z-text-2xs);
  line-height: var(--z-leading-xs);
}
.s-a .a-links-phone {
  display: none;
}
.s-a .a-appearance {
  position: absolute;
  top: var(--z-space-6);
  right: var(--z-space-8);
}
@media (max-width: 800px) {
  .s-a {
    display: flex;
    flex-direction: column;
  }
  .s-a .a-brand {
    display: none;
  }
  .s-a .a-mark {
    display: flex;
    justify-content: center;
    padding: var(--z-space-8) var(--z-space-6) var(--z-space-2);
  }
  .s-a .a-form {
    flex: 1;
    padding: var(--z-space-4) var(--z-space-6) var(--z-space-6);
  }
  .s-a .a-meta {
    flex-direction: column;
    align-items: center;
    text-align: center;
  }
  .s-a .a-links-phone {
    display: block;
    color: var(--z-text-muted);
  }
  .s-a .a-links-phone .m-links {
    justify-content: center;
  }
  .s-a .a-appearance {
    top: var(--z-space-4);
    right: var(--z-space-6);
  }
  .s-a .m-no-account {
    display: none;
  }
}

/*
 * First account, concept A: the same card, shorter. A one-sentence lede, the
 * commands that find the token as tabs under the field that asks for it, the
 * explanation behind a disclosure, and what comes next after the button, where
 * a person who has finished the form is looking.
 */
.s-fa-a {
  position: relative;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  min-height: 100%;
  padding: var(--z-space-6) var(--z-space-4);
  background: var(--z-bg);
}
.s-fa-a .fa-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--z-space-4);
  width: 100%;
  max-width: var(--z-width-dialog-md);
  padding: var(--z-space-8);
  border: var(--z-border-width) solid var(--z-border);
  border-radius: var(--z-radius-lg);
  background: var(--z-surface);
  box-shadow: var(--z-shadow-lg);
}
.s-fa-a .fa-card::before {
  content: '';
  position: absolute;
  inset: 0 0 auto;
  height: var(--z-border-width);
  margin: 0 var(--z-radius-lg);
  background: linear-gradient(90deg, transparent, var(--z-border-strong), transparent);
}
.s-fa-a .fa-brand {
  display: flex;
  justify-content: center;
}
.s-fa-a .fa-head {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--z-space-1);
  text-align: center;
}
.s-fa-a .fa-step {
  font-size: var(--z-text-2xs);
  font-weight: var(--z-weight-medium);
  letter-spacing: var(--z-tracking-wider);
  text-transform: uppercase;
  color: var(--z-text-subtle);
}
.s-fa-a h1 {
  font-size: var(--z-text-xl);
  line-height: var(--z-leading-xl);
  font-weight: var(--z-weight-semibold);
  letter-spacing: var(--z-tracking-tight);
  text-wrap: balance;
}
.s-fa-a .fa-lede {
  font-size: var(--z-text-sm);
  line-height: var(--z-leading-sm);
  color: var(--z-text-muted);
  text-wrap: pretty;
}
.s-fa-a form {
  display: flex;
  flex-direction: column;
  gap: var(--z-space-4);
}
.s-fa-a .fa-then {
  text-align: center;
}
.s-fa-a .fa-version {
  font-size: var(--z-text-2xs);
  color: var(--z-text-subtle);
  text-align: center;
}
.s-fa-a .fa-appearance,
.s-ca-a .fa-appearance {
  position: absolute;
  top: var(--z-space-4);
  right: var(--z-space-4);
}
@media (max-width: 768px) {
  .s-fa-a {
    padding-top: var(--z-space-4);
  }
  .s-fa-a .fa-card {
    padding: var(--z-space-5);
  }
}

/*
 * Connect an app, concept A: the same card. Where the app sends you and the
 * warning about that address are one summary, the warning is shorter, and the
 * primary action names the app it is allowing.
 */
.s-ca-a {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--z-space-5);
  min-height: 100%;
  padding: var(--z-space-8) var(--z-space-4);
  background: var(--z-bg);
}
.s-ca-a .ca-card {
  display: flex;
  flex-direction: column;
  gap: var(--z-space-4);
  width: 100%;
  max-width: var(--z-width-dialog-md);
  padding: var(--z-space-8);
  border: var(--z-border-width) solid var(--z-border);
  border-radius: var(--z-radius-lg);
  background: var(--z-surface);
  box-shadow: var(--z-shadow-md);
}
.s-ca-a .ca-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--z-space-10);
  height: var(--z-space-10);
  border-radius: var(--z-radius-full);
  background: var(--z-accent-subtle);
  color: var(--z-accent);
}
.s-ca-a h1 {
  font-size: var(--z-text-xl);
  line-height: var(--z-leading-xl);
  font-weight: var(--z-weight-semibold);
  overflow-wrap: anywhere;
}
.s-ca-a .ca-lede {
  font-size: var(--z-text-base);
  line-height: var(--z-leading-base);
  color: var(--z-text-muted);
}
.s-ca-a .ca-lede strong {
  color: var(--z-text);
  font-weight: var(--z-weight-medium);
}
.s-ca-a .ca-summary {
  display: flex;
  flex-direction: column;
  gap: var(--z-space-3);
  padding: var(--z-space-4);
  border-radius: var(--z-radius-md);
  background: var(--z-surface-sunken);
}
.s-ca-a .ca-facts {
  display: flex;
  flex-direction: column;
  gap: var(--z-space-3);
  margin: 0;
}
.s-ca-a .ca-facts dt {
  font-size: var(--z-text-2xs);
  font-weight: var(--z-weight-medium);
  letter-spacing: var(--z-tracking-wide);
  text-transform: uppercase;
  color: var(--z-text-muted);
}
.s-ca-a .ca-facts dd {
  margin: var(--z-space-1) 0 0;
  font-size: var(--z-text-sm);
  line-height: var(--z-leading-sm);
  overflow-wrap: anywhere;
}
.s-ca-a .ca-host {
  font-size: var(--z-text-base);
  font-weight: var(--z-weight-medium);
}
@media (max-width: 768px) {
  .s-ca-a {
    padding-top: var(--z-space-6);
  }
  .s-ca-a .ca-card {
    padding: var(--z-space-5);
  }
}

/*
 * Fleet status, concept A: the page gains a brand and a bigger banner, the four
 * facts stay two across on a phone, and the reasons are grouped by how serious
 * they are, with the long group folded so the cause is not two screens down.
 */
.s-fs-a {
  position: relative;
  min-height: 100%;
  background: var(--z-bg);
}
.s-fs-a .fs-page {
  display: grid;
  gap: var(--z-space-6);
  max-width: var(--z-width-dialog-md);
  margin: 0 auto;
  padding: var(--z-space-8) var(--z-space-4);
}
.s-fs-a .fs-head {
  display: flex;
  flex-direction: column;
  gap: var(--z-space-4);
}
.s-fs-a .m-state {
  gap: var(--z-space-5);
  padding: var(--z-space-6);
}
.s-fs-a .m-state-word {
  font-size: var(--z-text-2xl);
  line-height: var(--z-leading-2xl);
}
.s-fs-a .fs-headline {
  margin-top: var(--z-space-1);
  font-size: var(--z-text-lg);
  line-height: var(--z-leading-lg);
  text-wrap: pretty;
}
.s-fs-a .fs-group + .fs-group {
  margin-top: var(--z-space-4);
}
.s-fs-a .fs-group h3 {
  display: inline-flex;
  align-items: center;
  gap: var(--z-space-2);
  margin-bottom: var(--z-space-2);
  font-size: var(--z-text-base);
  font-weight: var(--z-weight-semibold);
}
.s-fs-a details.fs-group > summary {
  display: flex;
  align-items: center;
  min-height: var(--z-control-touch);
  cursor: pointer;
  list-style: none;
}
.s-fs-a details.fs-group > summary::-webkit-details-marker {
  display: none;
}
.s-fs-a details.fs-group > summary h3 {
  margin: 0;
}
.s-fs-a details.fs-group > summary::after {
  content: '+';
  margin-left: auto;
  font-size: var(--z-text-lg);
  color: var(--z-text-muted);
}
.s-fs-a details.fs-group[open] > summary::after {
  content: '\2212';
}

/* The group heading already says Blocking or Slowing, so the word inside each item is for a screen reader. */
.s-fs-a .m-sev {
  position: absolute;
  width: var(--z-nudge-1);
  height: var(--z-nudge-1);
  margin: calc(-1 * var(--z-nudge-1));
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
}

/*
 * Not found, concept A: the same page, with a way back beside the way forward.
 * Somebody who followed a stale link usually came from the page before it.
 */
.s-nf-a {
  position: relative;
  min-height: 100%;
  padding: var(--z-space-8) var(--z-space-6);
  background: var(--z-bg);
}
.s-nf-a .nf-head {
  display: flex;
  flex-direction: column;
  gap: var(--z-space-1);
}
.s-nf-a .nf-head h1 {
  font-size: var(--z-text-2xl);
  line-height: var(--z-leading-2xl);
  font-weight: var(--z-weight-semibold);
  letter-spacing: var(--z-tracking-tight);
}
.s-nf-a .nf-head p {
  color: var(--z-text-muted);
  font-size: var(--z-text-base);
}
.s-nf-a .nf-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--z-space-3);
  max-width: var(--z-width-dialog-md);
  margin: var(--z-space-16) auto 0;
  text-align: center;
}
.s-nf-a .nf-empty h2 {
  font-size: var(--z-text-base);
  font-weight: var(--z-weight-semibold);
}
.s-nf-a .nf-empty p {
  color: var(--z-text-muted);
  font-size: var(--z-text-base);
  line-height: var(--z-leading-base);
  text-wrap: pretty;
}
.s-nf-a .nf-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: var(--z-space-3);
  margin-top: var(--z-space-2);
}

/*
 * Concept B, evolution. No brand panel: one centred frame, the same one the
 * first-account and consent screens use, so every page before sign in looks
 * like the same product. The pitch becomes a single quiet line beneath.
 */
.s-b {
  position: relative;
  display: flex;
  justify-content: center;
  padding: var(--z-space-12) var(--z-space-4) var(--z-space-8);
  background: var(--z-bg);
}
.s-b .b-column {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--z-space-6);
  width: 100%;
  max-width: var(--z-width-dialog-md);
  min-width: 0;
  margin-block: auto;
}
.s-b .b-brand {
  display: flex;
  justify-content: center;
}
.s-b .b-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--z-space-4);
  width: 100%;
  padding: var(--z-space-8);
  border: var(--z-border-width) solid var(--z-border);
  border-radius: var(--z-radius-lg);
  background: var(--z-surface);
  box-shadow: var(--z-shadow-lg);
}
.s-b .b-card::before {
  content: '';
  position: absolute;
  inset: 0 0 auto;
  height: var(--z-border-width);
  margin: 0 var(--z-radius-lg);
  background: linear-gradient(90deg, transparent, var(--z-border-strong), transparent);
}
.s-b h1 {
  font-size: var(--z-text-xl);
  line-height: var(--z-leading-xl);
  font-weight: var(--z-weight-semibold);
  letter-spacing: var(--z-tracking-tight);
  text-align: center;
  text-wrap: balance;
}
.s-b .b-lede {
  margin-top: calc(-1 * var(--z-space-2));
  font-size: var(--z-text-sm);
  line-height: var(--z-leading-sm);
  color: var(--z-text-muted);
  text-align: center;
  text-wrap: pretty;
}
.s-b .b-instance {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--z-space-2);
  font-size: var(--z-text-xs);
  color: var(--z-text-muted);
}
.s-b .b-footer {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--z-space-3);
  max-width: 100%;
  color: var(--z-text-muted);
  font-size: var(--z-text-xs);
  line-height: var(--z-leading-xs);
  text-align: center;
}
.s-b .b-footer .m-links {
  justify-content: center;
}
.s-b .b-version {
  color: var(--z-text-subtle);
  font-size: var(--z-text-2xs);
}
.s-b .b-appearance {
  position: absolute;
  top: var(--z-space-4);
  right: var(--z-space-4);
}
@media (max-width: 768px) {
  .s-b {
    padding-top: var(--z-space-8);
  }
  .s-b .b-card {
    padding: var(--z-space-5);
  }
}

/*
 * First account, concept B: where to find the token sits beside the form, in the
 * same frame sign in uses. From 960px it is two columns; below that the help
 * folds into a disclosure above the token field.
 */
.s-b--wide .b-column {
  max-width: var(--z-width-dialog-lg);
}
.s-b .fa-b-head {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--z-space-1);
  text-align: center;
}
.s-b .fa-step {
  font-size: var(--z-text-2xs);
  font-weight: var(--z-weight-medium);
  letter-spacing: var(--z-tracking-wider);
  text-transform: uppercase;
  color: var(--z-text-subtle);
}
.s-b .fa-b-grid {
  display: grid;
  grid-template-columns: minmax(0, 5fr) minmax(0, 6fr);
  gap: var(--z-space-8);
}
.s-b .fa-b-help {
  display: flex;
  flex-direction: column;
  align-self: start;
  gap: var(--z-space-3);
  padding: var(--z-space-5);
  border-radius: var(--z-radius-md);
  background: var(--z-surface-sunken);
}
.s-b .fa-b-help h2 {
  font-size: var(--z-text-base);
  font-weight: var(--z-weight-semibold);
}
.s-b .fa-b-help-phone {
  display: none;
}
.s-b .fa-b-form {
  display: flex;
  flex-direction: column;
  gap: var(--z-space-4);
  min-width: 0;
}
.s-b .fa-then {
  text-align: center;
}
@media (max-width: 959px) {
  .s-b .fa-b-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .s-b .fa-b-help {
    display: none;
  }
  .s-b .fa-b-help-phone {
    display: block;
  }
}

/*
 * Connect an app, concept B: in the frame sign in and first account share. The
 * role is two cards that say what each allows, what the app can never do is its
 * own short list, and on a phone the buttons stay at the bottom of the screen.
 */
.s-ca-b h1 {
  overflow-wrap: anywhere;
}
.s-ca-b .cb-from {
  font-size: var(--z-text-sm);
  line-height: var(--z-leading-sm);
  color: var(--z-text-muted);
  text-align: center;
  text-wrap: pretty;
  overflow-wrap: anywhere;
}
.s-ca-b .cb-from strong {
  color: var(--z-text);
}
.s-ca-b .cb-where {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--z-space-2);
  vertical-align: middle;
  color: var(--z-text);
}
.s-ca-b .m-radio {
  padding: var(--z-space-4);
  border: var(--z-border-width) solid var(--z-border-strong);
  border-radius: var(--z-radius-md);
  background: var(--z-surface);
}
.s-ca-b .m-radio:has(input:checked) {
  border-color: var(--z-accent);
  background: var(--z-accent-subtle);
}
.s-ca-b .cb-never {
  padding: var(--z-space-4);
  border: var(--z-border-width) solid var(--z-border);
  border-radius: var(--z-radius-md);
}
.s-ca-b .cb-never-title {
  margin-bottom: var(--z-space-2);
  font-size: var(--z-text-xs);
  font-weight: var(--z-weight-semibold);
  letter-spacing: var(--z-tracking-wide);
  text-transform: uppercase;
  color: var(--z-text-muted);
}
.s-ca-b .cb-never ul {
  display: flex;
  flex-direction: column;
  gap: var(--z-space-2);
  margin: 0;
  padding: 0;
  list-style: none;
}
.s-ca-b .cb-never li {
  display: flex;
  align-items: flex-start;
  gap: var(--z-space-2);
  font-size: var(--z-text-sm);
  line-height: var(--z-leading-sm);
  color: var(--z-text-muted);
}
.s-ca-b .cb-never .icon {
  margin-top: var(--z-nudge-3);
  color: var(--z-text-subtle);
}
.s-ca-b .cb-actions {
  display: flex;
  justify-content: flex-end;
  gap: var(--z-space-3);
}
@media (max-width: 768px) {
  /* Stuck to the bottom of the screen while the card is taller than it, and
     resting at the card's foot when it is not. The page scrolls a focused field
     clear of the bar, so the bar never covers what a person is typing in. */
  .s-ca-b .cb-actions:not(.cb-actions--plain) {
    position: sticky;
    bottom: 0;
    margin: 0 calc(-1 * var(--z-space-5)) calc(-1 * var(--z-space-5));
    padding: var(--z-space-3) var(--z-space-5);
    border-top: var(--z-border-width) solid var(--z-border);
    border-radius: 0 0 var(--z-radius-lg) var(--z-radius-lg);
    background: var(--z-surface);
  }
  .s-ca-b .cb-actions .m-btn {
    flex: 1;
  }
  :root[data-concept='b']:has(.s-ca-b) {
    scroll-padding-bottom: 6rem;
  }
}

/*
 * Fleet status, concept B: one plain sentence for the person waiting, written
