// The README is the pack's argument, so what it can be checked against is.
//
// A recommendation that disagrees with the picture set, a capture nobody
// mentions, a link that goes nowhere or a total that is not the one the checker
// wrote down would each make a reader trust the pack less than it deserves, and
// each is the kind of drift a long review document picks up when one part is
// edited and the others are not.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { RECOMMENDED, plan } from '../tools/capture.mjs';
import { BASE_PAIRS } from '../tools/check.mjs';
import { SCREENS } from './screens/index.js';

const here = dirname(fileURLToPath(import.meta.url));
const readme = readFileSync(resolve(here, 'README.md'), 'utf8');
const review = JSON.parse(readFileSync(resolve(here, 'viewport-review.json'), 'utf8'));

/** The text under a `##` or `###` heading, up to the next heading of any level. */
function section(title) {
  const lines = readme.split('\n');
  const start = lines.findIndex((line) => line === `## ${title}` || line === `### ${title}`);
  assert.ok(start >= 0, `the README has no "${title}" section`);
  const end = lines.findIndex((line, i) => i > start && /^#{1,3} /.test(line));
  return lines.slice(start + 1, end < 0 ? undefined : end).join('\n');
}

/** The README with its line wrapping undone, so a phrase is found wherever it broke. */
const flat = readme.replace(/\s+/g, ' ');

test('each screen states one recommendation, and it is the concept that is photographed in the other style', () => {
  for (const screen of SCREENS) {
    const found = [...section(screen.title).matchAll(/\*\*Recommendation: ([ABC])\.\*\*/g)];
    assert.equal(found.length, 1, `${screen.title} must state exactly one recommendation`);
    assert.equal(found[0][1].toLowerCase(), RECOMMENDED[screen.id], `${screen.title}: the README and capture.mjs disagree`);
  }
});

test('every picture the capture script takes is shown in the README', () => {
  for (const shot of plan(SCREENS.map((screen) => screen.id))) {
    assert.ok(readme.includes(shot.file), `${shot.file} is not in the README`);
  }
});

test('every relative link in the README goes to a file that exists', () => {
  const links = [...readme.matchAll(/\]\(([^)\s]+)\)/g)]
    .map((match) => match[1])
    .filter((target) => !/^(https?:|#|mailto:)/.test(target));
  assert.ok(links.length > 10, 'a README with this much to show links to its pictures and its evidence');
  for (const target of links) {
    const file = resolve(here, target.split('#')[0]);
    assert.ok(existsSync(file), `${target} does not exist`);
  }
});

test('the totals in the README are the ones the checker wrote down', () => {
  const combinations = review.combinations.toLocaleString('en-GB');
  assert.ok(flat.includes(`${combinations} combinations`), `the README does not say ${combinations} combinations`);
  assert.ok(flat.includes(`${review.findings.length} findings`), `the README does not say ${review.findings.length} findings`);
  assert.ok(flat.includes(`${review.known.length} known`), `the README does not say ${review.known.length} known`);
  assert.ok(flat.includes(`on the ${BASE_PAIRS.length} pairs of tokens`), `the README does not say ${BASE_PAIRS.length} pairs of tokens`);
});

// The tables compare each concept with today's page, and a number that was typed
// from memory or measured beneath the review bar is a comparison that is wrong in
// the concept's favour or against it. Every number in a row is one a script
// recorded, from the concept for a concept's row and from the photographed page
// for Today's.
const numbersIn = (value, found = new Set()) => {
  if (typeof value === 'number') found.add(value);
  else if (value && typeof value === 'object') Object.values(value).forEach((inner) => numbersIn(inner, found));
  return found;
};
const measuredConcepts = JSON.parse(readFileSync(resolve(here, 'concept-measurements.json'), 'utf8'));
const photographed = JSON.parse(readFileSync(resolve(here, 'current-measurements.json'), 'utf8')).shots;

for (const [title, id] of [
  ['Sign in', 'signin'],
  ['First account', 'first-account'],
  ['Connect an app', 'connect-app'],
  ['Fleet status', 'fleet-status'],
]) {
  test(`${title}: every number in a table row is one that was measured`, () => {
    const rows = section(title).split('\n').filter((line) => /^\| (Today|[ABC],)/.test(line));
    assert.equal(rows.length, 4, `${title} has a Today row and a row for each concept`);
    for (const row of rows) {
      const [label, ...cells] = row.split('|').slice(1, -1).map((cell) => cell.trim());
      const allowed =
        label === 'Today'
          ? numbersIn(Object.entries(photographed).filter(([key]) => key.startsWith(id)).map(([, shot]) => shot))
          : numbersIn(measuredConcepts.screens[id][label[0].toLowerCase()]);
      for (const number of cells.flatMap((cell) => [...cell.matchAll(/\d+/g)].map((match) => Number(match[0])))) {
        assert.ok(allowed.has(number), `${title}, "${label}": ${number} was not measured`);
      }
    }
  });
}

test('the README says what it does not claim', () => {
  const claimed = section('Not claimed').toLowerCase();
  for (const phrase of ['usability study', 'screen reader', 'performance', 'end-to-end']) {
    assert.ok(claimed.includes(phrase), `Not claimed does not mention "${phrase}"`);
  }
});

test('the README names the Classic control edge and its remedy, because no concept can fix it', () => {
  assert.match(flat, /1\.62:1/);
  assert.match(flat, /--z-border-strong/);
});

test('every token concept C proposes is named in the README with the guideline section it would change', () => {
  const css = readFileSync(resolve(here, 'concept-c-tokens.css'), 'utf8');
  const proposed = [...css.matchAll(/^\s+(--z-[a-z-]+):/gm)].map((match) => match[1]);
  assert.ok(proposed.length >= 5, 'concept C defines tokens');
  const table = section('The tokens concept C would add');
  for (const token of new Set(proposed)) {
    const row = table.split('\n').find((line) => line.includes(`\`${token}\``));
    assert.ok(row, `${token} is not in the proposed-token table`);
    assert.match(row, /1\.\d /, `${token} names no section of docs/ui-guidelines.md`);
  }
});

// What the review page is showing, as its address.
//
// A combination of screen, concept, style, mode and state lives in the hash, so
// a capture, a check or a colleague can name one, and a reload keeps it. Nothing
// here touches the page: it is pure so the one thing that must hold, that any
// address at all lands on a combination that exists, can be tested without a
// browser. Values are only ever compared against what the page offers, never
// written back as markup.

export const CONCEPTS = ['current', 'a', 'b', 'c'];
export const STYLES = ['mission-control', 'classic'];
export const MODES = ['light', 'dark'];

const pick = (offered, wanted, fallback) => (offered.includes(wanted) ? wanted : fallback);

/**
 * Read a hash into a combination that exists.
 *
 * @param {string} hash  `location.hash`, with or without the leading `#`.
 * @param {{ id: string, states: string[] }[]} screens  What the page offers, in
 *   order; the first is the default.
 * @param {{ mode?: string, concepts?: string[] }} [defaults]  The mode to use when
 *   the hash names none, which the page takes from the browser's own colour
 *   scheme, and the concepts the pack offers (a pack with one concept of its
 *   own offers Current and that one, and a hash naming any other lands on it).
 */
export function parseHash(hash, screens, { mode = 'dark', concepts = CONCEPTS } = {}) {
  if (screens.length === 0) throw new Error('the review page has no screens to show');
  const query = new URLSearchParams(hash.replace(/^#/, ''));
  const screen = screens.find((s) => s.id === query.get('screen')) ?? screens[0];
  return {
    screen: screen.id,
    concept: pick(concepts, query.get('concept'), concepts.find((c) => c !== 'current') ?? concepts[0]),
    style: pick(STYLES, query.get('style'), 'mission-control'),
    mode: pick(MODES, query.get('mode'), pick(MODES, mode, 'dark')),
    // A state belongs to its screen: `stale` on the sign-in screen is not a
    // state, so it falls back rather than being carried across.
    state: pick(screen.states, query.get('state'), screen.states[0]),
  };
}

/** Write a combination as a hash, in the key order the checker reads. */
export function formatHash({ screen, concept, style, mode, state }) {
  return `#${new URLSearchParams({ screen, concept, style, mode, state })}`;
}

// The review page is driven by its address, so a combination is something a
// capture, a check or a colleague can name. The address is also something
// anybody can type, which is why most of these tests are about junk: whatever
// is in the hash, the page must land on a combination that exists.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { formatHash, parseHash } from './review-state.js';

const SCREENS = [
  { id: 'signin', states: ['password', 'sso'] },
  { id: 'status', states: ['healthy', 'blocked', 'stale'] },
];

const DEFAULTS = {
  screen: 'signin',
  concept: 'a',
  style: 'mission-control',
  mode: 'dark',
  state: 'password',
};

test('an empty hash is the first screen, concept A, Mission Control, dark', () => {
  assert.deepEqual(parseHash('', SCREENS), DEFAULTS);
  assert.deepEqual(parseHash('#', SCREENS), DEFAULTS);
});

test('the mode a browser asked for is the default mode, until the hash says otherwise', () => {
  assert.equal(parseHash('', SCREENS, { mode: 'light' }).mode, 'light');
  assert.equal(parseHash('#mode=dark', SCREENS, { mode: 'light' }).mode, 'dark');
  // A default that is not a mode is not trusted either.
  assert.equal(parseHash('', SCREENS, { mode: 'sepia' }).mode, 'dark');
});

test('a combination survives a round trip through formatHash', () => {
  const chosen = { screen: 'status', concept: 'c', style: 'classic', mode: 'light', state: 'stale' };
  assert.deepEqual(parseHash(formatHash(chosen), SCREENS), chosen);
});

test('formatHash writes all five keys, in the order the checker reads them', () => {
  assert.equal(
    formatHash(DEFAULTS),
    '#screen=signin&concept=a&style=mission-control&mode=dark&state=password',
  );
});

test('the hash may omit the leading # and any key', () => {
  assert.deepEqual(parseHash('screen=status', SCREENS), {
    ...DEFAULTS,
    screen: 'status',
    state: 'healthy',
  });
});

test('a screen, concept, style or mode nobody offers falls back, without throwing', () => {
  assert.deepEqual(parseHash('#screen=nope&concept=z&style=x&mode=y&state=q', SCREENS), DEFAULTS);
});

test('a state that belongs to another screen is not carried over', () => {
  // `stale` is real, but not on the sign-in screen.
  assert.equal(parseHash('#screen=signin&state=stale', SCREENS).state, 'password');
  // And a state the chosen screen does have is kept.
  assert.equal(parseHash('#screen=status&state=blocked', SCREENS).state, 'blocked');
});

test('every concept the page offers is accepted, current included', () => {
  for (const concept of ['current', 'a', 'b', 'c']) {
    assert.equal(parseHash(`#concept=${concept}`, SCREENS).concept, concept);
  }
});

test('malformed percent-encoding and repeated keys do not throw', () => {
  assert.doesNotThrow(() => parseHash('#screen=%E0%A4%A&concept=%', SCREENS));
  assert.deepEqual(parseHash('#screen=status&screen=signin', SCREENS).screen, 'status');
});

test('a hash that tries to be markup is only ever compared, never echoed', () => {
  const state = parseHash('#screen=<img src=x onerror=alert(1)>&state=<script>', SCREENS);
  assert.deepEqual(state, DEFAULTS);
});

test('with no screens there is nothing to land on, which is a programming error', () => {
  assert.throws(() => parseHash('', []), /no screens/);
});

test('a pack that offers fewer concepts turns one it does not offer into the first it does', () => {
  const screens = [{ id: 'overview', states: ['normal'] }];
  const offered = { concepts: ['current', 'a'] };
  assert.equal(parseHash('#concept=b', screens, offered).concept, 'a');
  assert.equal(parseHash('#concept=current', screens, offered).concept, 'current');
  assert.equal(parseHash('', screens, offered).concept, 'a');
  // Without the option nothing changes for pack 1.
  assert.equal(parseHash('#concept=c', screens).concept, 'c');
});

