/* Shown when the tokens did not load, which is exactly when the product's own
   colours are unavailable, so these two fallbacks are the one deliberate raw
   value in the pack. */
#assets-banner {
  margin: 0;
  padding: var(--z-space-4);
  border-bottom: 2px solid var(--z-danger, #bd2018);
