// Draws one combination of screen, concept, style, mode and state into #stage.
//
// The combination lives in the hash (see review-state.js). Once a render is
// done, data-rendered on <html> is set to the hash it drew, which is how the
// checker and the capture script know a change has landed without guessing at a
// delay. The hash is never rewritten behind the caller's back: a caller that
// sets a partial hash waits for exactly that hash to come back.
import { CONCEPTS, MODES, STYLES, formatHash, parseHash } from './review-state.js';
import { esc } from './ui.js';

// The page names its own registry, so a second pack can reuse all of this. The
// default is pack 1's, which is what a page with no such tag means. A registry
// may also say which concepts it offers and what to call them.
const registryUrl =
  document.querySelector('meta[name="review-screens"]')?.getAttribute('content') ??
  './screens/index.js';
const registry = await import(registryUrl);
const { SCREENS } = registry;
const OFFERED = registry.CONCEPTS ?? CONCEPTS;

const root = document.documentElement;
const stage = document.getElementById('stage');
const KEYS = ['screen', 'concept', 'style', 'mode', 'state'];
const controls = Object.fromEntries(KEYS.map((key) => [key, document.getElementById(key)]));
const browserMode = matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';

const LABELS = {
  concept: {
    current: 'Current (capture)',
    a: 'A (evolution)',
    b: 'B (evolution)',
    c: 'C (bold)',
    ...registry.LABELS?.concept,
  },
  style: { 'mission-control': 'Mission Control', classic: 'Classic' },
  mode: { light: 'Light', dark: 'Dark' },
};

const humanise = (id) => {
  const words = id.replaceAll('-', ' ');
  return words[0].toUpperCase() + words.slice(1);
};

function fill(select, values, label) {
  select.innerHTML = values
    .map((value) => `<option value="${esc(value)}">${esc(label(value))}</option>`)
    .join('');
}

/** The real page, as photographed: not live HTML, so it says what it is. */
function currentView(screen) {
  const alt = screen.currentAlt ?? `The current ${screen.title} page, captured from the running controller.`;
  return (
    `<figure class="current"><h1 class="sr-only">${esc(screen.title)}: the current page</h1>` +
    `<picture><source media="(max-width: 799px)" srcset="current-${esc(screen.id)}-375.png">` +
    `<img src="current-${esc(screen.id)}-1440.png" width="1440" height="900" alt="${esc(alt)}"></picture>` +
    `<figcaption>A capture of the real page, taken from a running controller at 1440x900 ` +
    `(375x812 on a phone) in Mission Control, dark. The style and mode controls do not change it, ` +
    `and anything outside the page itself, such as a demo banner, comes from the fixture it was ` +
    `captured from.</figcaption></figure>`
  );
}

fill(controls.screen, SCREENS.map((s) => s.id), (id) => SCREENS.find((s) => s.id === id).title);
fill(controls.concept, OFFERED, (concept) => LABELS.concept[concept]);
fill(controls.style, STYLES, (style) => LABELS.style[style]);
fill(controls.mode, MODES, (mode) => LABELS.mode[mode]);

function draw() {
  const wanted = parseHash(location.hash, SCREENS, { mode: browserMode, concepts: OFFERED });
  const screen = SCREENS.find((s) => s.id === wanted.screen);

  // Classic is the absence of the attribute, exactly as the app does it.
  if (wanted.style === 'classic') root.removeAttribute('data-ui-style');
  else root.setAttribute('data-ui-style', wanted.style);
  root.setAttribute('data-theme', wanted.mode);
  root.setAttribute('data-concept', wanted.concept);

  fill(controls.state, screen.states, (id) => screen.labels?.[id] ?? humanise(id));
  for (const key of KEYS) controls[key].value = wanted[key];

  stage.innerHTML =
    wanted.concept === 'current' ? currentView(screen) : screen.render(wanted.concept, wanted.state);
  root.dataset.rendered = location.hash;
}

for (const select of Object.values(controls)) {
  select.addEventListener('change', () => {
    const chosen = Object.fromEntries(KEYS.map((key) => [key, controls[key].value]));
    // A new screen starts at its own first state.
    if (select === controls.screen) chosen.state = '';
    location.hash = formatHash(
      parseHash(formatHash(chosen), SCREENS, { mode: browserMode, concepts: OFFERED }),
    );
  });
}

addEventListener('hashchange', draw);

// A mockup's links and forms go nowhere: a link to "#" would rewrite the hash
// and throw the combination away, and a submit would reload the page.
stage.addEventListener('click', (event) => {
  if (event.target.closest('a[href^="#"]')) event.preventDefault();
});
stage.addEventListener('submit', (event) => event.preventDefault());

draw();

// Connect an app: the one decision a person arrives at from somebody else's app.
//
// Claude, or any MCP client, sends them here mid-task, signed in, to say yes or
// no. The copy is McpConsent.svelte's own. The captures showed what to design
// for: the primary action is below the fold on a phone (963px on a 812px
// screen), and with the loopback warning showing it drops 5px below the fold on
// a laptop. So every concept keeps the decision in reach, and none makes the
// warning longer.
//
//   A  the same card, with the destination and its warning grouped in one
//      summary, a shorter warning, and a primary button that names the app.
//   B  the role as two cards that say what each allows, a list of what the app
//      can never do, and buttons that stick to the bottom of a phone.
//   C  a diagram with Zoomies at one end and the app at the other, and the
//      address it sends you back to as the checked destination, on the scene.
//
// How the loopback warning should sound is a question the three answer in
// different ways, all inside the fixed status colours.
import { icon } from '../icons.js';
import { button, callout, esc, logo, radioGroup } from '../ui.js';
import { PITCH, VERSION, appearance, links } from './shared.js';

const STATES = ['loading', 'normal', 'loopback', 'stress', 'refused', 'nothing', 'expired'];
const LABELS = {
  loading: 'Loading the request',
  normal: 'A request',
  loopback: 'A request that returns to this computer',
  stress: 'A very long name and address',
  refused: 'Refused before there was anything to decide',
  nothing: 'Nothing to approve',
  expired: 'Expired',
};

const USER = 'ada';
const KIND =
  'It registered itself with this controller when it connected. Its name is its own description; where it sends you is what has been checked.';
const SCOPE =
  'It works on /mcp only, not the API or this interface, and never with more than your own role. Disconnect it any time under Settings, MCP connections.';
const SOURCE =
  'Repository source access starts with no grants. After connecting, use Source access under Settings, MCP connections to choose available repositories explicitly.';
const REFUSED =
  'The app asked to send you back to an address it never registered, or left out part of the request, so this controller will not send you anywhere.';
const ROLES = [
  { value: 'viewer', label: 'Viewer', description: 'Read jobs, runners, pools, hosts, problems and runner logs.' },
  { value: 'operator', label: 'Operator', description: 'Also re-run a failed job and drain an idle runner.' },
];

// Exactly 300 characters, with an 84-character run that has nowhere to break,
// and a redirect host of exactly 120 unbroken characters. A client registers
// itself, so its name is whatever it chose, and the address is the one thing
// the controller has checked.
const LONG_NAME = ('Totally Legitimate Coding Assistant '.repeat(6) + 'A'.repeat(84)).slice(0, 300);
const LONG_HOST = `cb${'0123456789'.repeat(11)}.example`;

/** The request a state describes, or null for a state that has none. */
function request(state) {
  switch (state) {
    case 'normal':
      return { client: 'Claude', host: 'claude.ai', loopback: false };
    case 'loopback':
      return { client: 'Claude Code', host: '127.0.0.1:41821', loopback: true };
    case 'stress':
      return { client: LONG_NAME, host: LONG_HOST, loopback: false };
    default:
      return null;
  }
}

const shortName = (name, max = 28) => (name.length > max ? `${name.slice(0, max).trimEnd()}…` : name);

const roles = (name = 'connection-role') =>
  radioGroup({ name, legend: 'What it may do', options: ROLES, value: 'operator' });

const failure = (html) => callout({ tone: 'danger', icon: 'triangle-alert', html });

/* the states with nothing to decide */

function plain(state) {
  switch (state) {
    case 'refused':
      return {
        h1: 'This connection cannot go ahead',
        hero: 'Nothing was shared.',
        html:
          `${failure(esc(REFUSED))}<p class="ca-muted">Nothing was shared and you have not been sent anywhere else. ` +
          `Go back to the app you came from and try connecting again; if it keeps happening, the app's connector ` +
          `settings need changing. The code was <span class="mono">invalid_request</span>; an administrator can ` +
          `find the reason in the controller's log.</p>`,
        action: button({ label: 'Go to Zoomies', variant: 'secondary', size: 'lg', href: '#' }),
      };
    case 'nothing':
      return {
        h1: 'Nothing to approve',
        hero: 'Nothing to approve.',
        html:
          `<p class="ca-muted">This page is where an app such as Claude sends you to approve a connection to ` +
          `Zoomies. Start from the app: add a connector with this controller's <span class="mono">/mcp</span> address.</p>`,
        action: button({ label: 'Go to Zoomies', variant: 'secondary', size: 'lg', href: '#' }),
      };
    case 'expired':
      return {
        h1: 'This request has expired',
        hero: 'This request has expired.',
        html:
          `<p class="ca-muted">It was answered already, or it waited more than fifteen minutes. Go back to the ` +
          `app you came from and connect again.</p>`,
        action: '',
      };
    case 'loading':
      return {
        h1: 'Loading the request',
        srOnlyH1: true,
        hero: 'Checking the request.',
        html:
          `<div class="m-skeleton-group" aria-busy="true"><span class="m-skeleton m-skeleton--title"></span>` +
          `<span class="m-skeleton m-skeleton--line"></span><span class="m-skeleton m-skeleton--line m-skeleton--short"></span>` +
          `<span class="m-skeleton m-skeleton--block"></span></div>`,
        action: '',
      };
    default:
      return null;
  }
}

const heading = (h1, srOnly) => `<h1${srOnly ? ' class="sr-only"' : ''}>${esc(h1)}</h1>`;

/* concept A: the same card, with the destination and its warning together */

function frameA(state) {
  const r = request(state);
  const brand = `<div class="ca-brand">${logo({ variant: 'full', size: 28 })}</div>`;
  let card;
  if (r) {
    const warning = r.loopback
      ? failure(
          'This app sends you back to an address on <strong>this computer</strong>. Any program running here ' +
            'could claim to be it, so continue only if you started this yourself.',
        )
      : '';
    card =
      `<h1>Connect <span class="ca-client">${esc(r.client)}</span> to Zoomies</h1>` +
      `<p class="ca-lede">It is asking to use this fleet's MCP tools as you, <strong>${USER}</strong>.</p>` +
      `<div class="ca-summary"><dl class="ca-facts"><div><dt>Sends you back to</dt>` +
      `<dd><span class="mono ca-host">${esc(r.host)}</span></dd></div>` +
      `<div><dt>About this app</dt><dd>${esc(KIND)}</dd></div></dl>${warning}</div>` +
      `${roles()}` +
      `${callout({ tone: 'neutral', icon: 'shield-check', html: `<p>${esc(SCOPE)}</p><p>${esc(SOURCE)}</p>` })}` +
      `<div class="ca-actions">${button({ label: 'Deny', variant: 'secondary', size: 'lg' })}` +
      `${button({ label: `Allow ${shortName(r.client)}`, variant: 'primary', size: 'lg' })}</div>`;
  } else {
    const p = plain(state);
    card = `${heading(p.h1, p.srOnlyH1)}${p.html}${p.action ? `<div class="ca-actions">${p.action}</div>` : ''}`;
  }
  return (
    `<div class="m-form-page s-ca-a"><div class="fa-appearance">${appearance()}</div>${brand}` +
    `<section class="ca-card"${state === 'loading' ? ' aria-busy="true"' : ''}>${card}</section></div>`
  );
}

/* concept B: the role as cards, what it can never do, buttons that stay in reach */

const NEVER = [
  'Use the API or this interface: it works on /mcp only.',
  'Do more than your own role.',
  'Read repository source until you choose it, under Settings, MCP connections.',
];

function frameB(state) {
  const r = request(state);
  let card;
  if (r) {
    const where = r.loopback
      ? `<span class="cb-where">${icon('laptop', 14)}<span class="mono m-host">${esc(r.host)}</span></span>`
      : `<span class="cb-where">${icon('globe', 14)}<span class="mono m-host">${esc(r.host)}</span></span>`;
    const note = r.loopback
      ? callout({
          tone: 'neutral',
          icon: 'laptop',
          html:
            'Sends you back to <strong>this computer</strong>. Any program running here could claim to be this ' +
            'app, so continue only if you started this yourself.',
        })
      : '';
    card =
      `<h1>Connect <span class="ca-client">${esc(r.client)}</span> to Zoomies</h1>` +
      `<p class="cb-from">It is asking to use this fleet's MCP tools as you, <strong>${USER}</strong>, and will send you back to ${where}</p>` +
      `${note}${roles()}` +
      `<div class="cb-never"><p class="cb-never-title">What it can never do</p><ul>` +
      `${NEVER.map((item) => `<li>${icon('x', 14)}<span>${esc(item)}</span></li>`).join('')}</ul></div>` +
      `<div class="cb-actions">${button({ label: 'Deny', variant: 'secondary', size: 'lg' })}` +
      `${button({ label: 'Allow', variant: 'primary', size: 'lg' })}</div>`;
  } else {
    const p = plain(state);
    card = `${heading(p.h1, p.srOnlyH1)}${p.html}${p.action ? `<div class="cb-actions cb-actions--plain">${p.action}</div>` : ''}`;
  }
  return (
    `<div class="m-form-page s-b s-ca-b"><div class="b-appearance">${appearance()}</div>` +
    `<div class="b-column"><header class="b-brand">${logo({ variant: 'mark', size: 72 })}</header>` +
    `<section class="b-card"${state === 'loading' ? ' aria-busy="true"' : ''}>${card}</section>` +
    `<footer class="b-footer"><p>${PITCH}</p>${links()}<p class="b-version">Zoomies ${VERSION}</p></footer></div></div>`
  );
}

/* concept C: a diagram of the connection, on the scene */

function diagram(r) {
  const end = r.loopback ? icon('laptop', 20) : icon('globe', 20);
  const where = r.loopback ? 'This computer' : 'Checked destination';
  return (
    `<figure class="cc-diagram" aria-hidden="true"><div class="cc-ends">` +
    `<div class="cc-node">${logo({ variant: 'full', size: 28, label: '' })}</div>` +
    `<svg class="cc-link" viewBox="0 0 120 24" width="120" height="24" focusable="false">` +
    `<line x1="2" y1="12" x2="104" y2="12" stroke-dasharray="5 5"/><path d="M100 5l10 7-10 7"/></svg>` +
    `<div class="cc-node cc-node--client">${end}<span class="m-host">${esc(r.client)}</span></div></div>` +
    `<figcaption class="cc-dest">${icon('shield-check', 15)}<span>${where}: <span class="mono m-host">${esc(r.host)}</span></span></figcaption></figure>`
  );
}

function frameC(state) {
  const r = request(state);
  let hero;
  let panel;
  if (r) {
    hero = `${diagram(r)}<p class="c-lede">It is asking to use this fleet's MCP tools as you, <strong>${USER}</strong>.</p>`;
    const warning = r.loopback
      ? `<p class="cc-local">${icon('laptop', 15)}<span>This address is on <strong>this computer</strong>. Any program running here ` +
        `could claim to be this app, so continue only if you started this yourself.</span></p>`
      : '';
    panel =
      `<h1>Connect <span class="ca-client">${esc(r.client)}</span> to Zoomies</h1>` +
      `<p class="cc-back">Sends you back to <span class="mono m-host">${esc(r.host)}</span></p>${warning}` +
      `${roles()}<p class="m-note">${esc(SOURCE)}</p><p class="m-note">${esc(SCOPE)}</p>` +
      `<div class="ca-actions">${button({ label: 'Deny', variant: 'secondary', size: 'lg' })}` +
      `${button({ label: 'Allow', variant: 'primary', size: 'lg' })}</div>`;
  } else {
    const p = plain(state);
    hero = `<p class="c-tagline cc-hero-line">${esc(p.hero)}</p>`;
    panel = `${heading(p.h1, p.srOnlyH1)}${p.html}${p.action ? `<div class="ca-actions">${p.action}</div>` : ''}`;
  }
  return (
    `<div class="m-form-page s-c s-ca-c"><div class="c-scene" aria-hidden="true"></div>` +
    `<div class="c-appearance">${appearance()}</div><div class="c-hero">${hero}</div>` +
    `<section class="c-panel"${state === 'loading' ? ' aria-busy="true"' : ''}>${panel}</section>` +
    `<footer class="c-footer">${links()}<span class="c-version">Zoomies ${VERSION}</span></footer></div>`
  );
}

const FRAMES = { a: frameA, b: frameB, c: frameC };

export default {
  id: 'connect-app',
  title: 'Connect an app',
  states: STATES,
  labels: LABELS,
  currentAlt:
    'The current Connect an app page: the Zoomies logo above a card titled Connect Claude to Zoomies, with a box saying where it sends you back to and what the app is, a choice between Viewer and Operator, two notes about source access and scope, and Deny and Allow buttons.',
  render(concept, state) {
    const frame = FRAMES[concept];
    if (!frame) throw new Error(`no concept called "${concept}"`);
    if (!STATES.includes(state)) throw new Error(`no connect-app state called "${state}"`);
    return frame(state);
  },
};

// First account: the form that exists only while no account does.
//
// The copy is Bootstrap.svelte's own wherever it survives. What the captures
// showed is what the concepts answer: the hardest field comes first, the
// commands that find the token (all but the Docker Compose one) hide behind a
// small question mark, and five sentences stand between the visitor and the
// first input. Every concept therefore shows where the token is, and none adds
// a line the visitor has to read before the form.
//
//   A  the same card, with a one-sentence lede, the commands as tabs under the
//      token field, and the explanation behind a disclosure.
//   B  two columns from 960px: where to find the token beside the form. On a
//      phone the help folds into a disclosure above the token field.
//   C  a rail of what comes after the account, echoing the Overview checklist,
//      beside the form. It uses concept C's scene and tokens.
import { icon } from '../icons.js';
import { button, callout, esc, field, iconButton, logo } from '../ui.js';
import { NO_ACCOUNT, PITCH, VERSION, appearance, links } from './shared.js';

const STATES = ['empty', 'errors', 'caps-lock', 'weak-password', 'closed'];
const LABELS = {
  empty: 'Empty',
  errors: 'Field errors',
  'caps-lock': 'Caps lock on',
  'weak-password': 'Password too short',
  closed: 'Closed: an account exists',
};

const TOKEN = 'k3p9-x7vq-2mdw';
const TOKEN_HINT = "Printed in the controller's log while no account exists.";
const PASSWORD_HINT = 'At least 12 characters. A phrase works well.';
const CONFIRM_HINT = 'Type it again, so a slip cannot lock you out of your own controller.';
const THEN = 'Then: connect a GitHub App, add a host if Zoomies has no agent of its own, create a pool, and point a workflow at it. The Overview keeps the list and ticks it off.';
const WHY =
  'The setup token is how Zoomies knows you are the one who deployed it: it is printed in the ' +
  "controller's log, which only the person who runs the controller can read. This form is refused " +
  'for ever once an account exists.';

const INSTALLS = [
  { id: 'compose', label: 'Docker Compose', command: "docker compose logs zoomies | grep 'setup token'" },
  { id: 'init', label: 'zoomies init', command: "zoomies logs | grep 'setup token'" },
  { id: 'systemd', label: 'systemd', command: "journalctl -u zoomies | grep 'setup token'" },
  {
    id: 'other',
    label: 'Other',
    text: 'Another container: docker logs and its name. A platform: its log viewer. Look for the line that begins “setup token”.',
  },
];

/**
 * The commands that find the token, as tabs. Native radios inside labels, so
 * the arrow keys and the focus ring come from the browser; the panel that shows
 * is chosen by :has() in components.css. `uid` keeps two copies on one page
 * (a desktop one and a phone one) from sharing a radio group.
 */
function installHelp(uid) {
  const tabs = INSTALLS.map(
    (o, i) =>
      `<label class="m-install-tab"><input type="radio" name="install-${uid}" value="${o.id}"${i === 0 ? ' checked' : ''}>` +
      `<span>${esc(o.label)}</span></label>`,
  ).join('');
  const panels = INSTALLS.map(
    (o) =>
      `<div class="m-install-panel p-${o.id}">` +
      (o.command
        ? `<code class="m-command">${esc(o.command)}</code>${button({ label: 'Copy', icon: 'copy', size: 'sm' })}`
        : `<p class="m-note">${esc(o.text)}</p>`) +
      `</div>`,
  ).join('');
  return (
    `<div class="m-install" role="group" aria-label="Where to find the setup token">` +
    `<div class="m-install-tabs">${tabs}</div>${panels}</div>`
  );
}

/** What each state fills in, and what it complains about. */
function values(state) {
  const filled = { token: TOKEN, username: 'ada', password: 'correct horse battery', confirm: 'correct horse battery' };
  switch (state) {
    case 'empty':
      return { token: '', username: '', password: '', confirm: '' };
    case 'errors':
      return {
        token: '', username: '', password: '', confirm: '',
        errors: {
          token: 'Paste the setup token from the controller log.',
          username: 'Choose a username for the first account.',
          password: 'Choose a password.',
        },
      };
    case 'caps-lock':
      return { ...filled, password: 'correct horse', confirm: '', notice: 'Caps lock is on.' };
    case 'weak-password':
      return {
        ...filled, password: 'sevench', confirm: '',
        errors: { password: 'A few more characters: 5 to go.' },
      };
    case 'closed':
      return { ...filled, closed: true };
    default:
      throw new Error(`no first-account state called "${state}"`);
  }
}

const eye = () => iconButton({ icon: 'eye', label: 'Show password', pressed: false });

/** The four fields in order, with `afterToken` (the install help) under the first. */
function fields(state, { afterToken = '', size = 'md' } = {}) {
  const v = values(state);
  const e = v.errors ?? {};
  return (
    field({
      name: 'setup-token', label: 'Setup token', required: true, mono: true, autocomplete: 'off',
      value: v.token, hint: TOKEN_HINT, error: e.token, size,
    }) +
    afterToken +
    field({
      name: 'username', label: 'Username', required: true, autocomplete: 'username',
      value: v.username, hint: 'You will sign in with this.', error: e.username, size,
    }) +
    field({
      name: 'password', label: 'Password', required: true, type: 'password', autocomplete: 'new-password',
      value: v.password, hint: PASSWORD_HINT, error: e.password, notice: v.notice, trailing: eye(), size,
    }) +
    field({
      name: 'confirm-password', label: 'Confirm the password', required: true, type: 'password',
      autocomplete: 'new-password', value: v.confirm, hint: CONFIRM_HINT, notice: v.notice, size,
    })
  );
}

const closedBanner = (state) =>
  values(state).closed
    ? callout({
        tone: 'danger',
        icon: 'triangle-alert',
        html:
          `<p>An account already exists, so this form has closed. Sign in instead.</p>` +
          button({ label: 'Go to sign in', variant: 'secondary', size: 'sm', href: '#' }),
      })
    : '';

const submit = (size = 'md') =>
  button({ label: 'Create the account', variant: 'primary', size, full: true, type: 'submit' });

/* concept A: the same card, shorter, with the commands where the token is asked for */

function frameA(state) {
  return (
    `<div class="s-fa-a"><div class="fa-appearance">${appearance()}</div>` +
    `<section class="fa-card"><div class="fa-brand">${logo({ variant: 'mark', size: 72 })}</div>` +
    `<div class="fa-head"><p class="fa-step">First step</p><h1>Create the first account</h1>` +
    `<p class="fa-lede">This creates the first account, with the highest role (Platform), and closes for good once it has.</p></div>` +
    `<details class="m-details"><summary>Why is this safe to ask for?</summary><p>${esc(WHY)}</p></details>` +
    `${closedBanner(state)}<form novalidate>${fields(state, { afterToken: installHelp('a') })}${submit()}</form>` +
    `<p class="m-note fa-then">${esc(THEN)}</p><p class="fa-version">Zoomies ${VERSION}</p></section></div>`
  );
}

/* concept B: where to find the token beside the form, in the frame sign in also uses */

function frameB(state) {
  return (
    `<div class="m-form-page s-b s-b--wide"><div class="b-appearance">${appearance()}</div>` +
    `<div class="b-column"><header class="b-brand">${logo({ variant: 'mark', size: 72 })}</header>` +
    `<section class="b-card"><div class="fa-b-head"><p class="fa-step">First step</p><h1>Create the first account</h1>` +
    `<p class="b-lede">This creates the first account, with the highest role (Platform), and closes for good once it has.</p></div>` +
    `<div class="fa-b-grid"><aside class="fa-b-help"><h2>Find your setup token</h2><p class="m-note">${esc(WHY)}</p>` +
    `${installHelp('b')}</aside>` +
    `<div class="fa-b-form">${closedBanner(state)}<details class="m-details fa-b-help-phone">` +
    `<summary>Where do I find the setup token?</summary>${installHelp('bp')}</details>` +
    `<form novalidate>${fields(state, { size: 'lg' })}${submit('lg')}</form></div></div>` +
    `<p class="m-note fa-then">${esc(THEN)}</p></section>` +
    `<footer class="b-footer"><p>${PITCH}</p>${links()}<p class="b-version">Zoomies ${VERSION}</p></footer></div></div>`
  );
}

/* concept C: a rail of what comes next, on the scene */

const RAIL = [
  { label: 'Create the first account', here: true },
  { label: 'Connect a GitHub App' },
  { label: 'Add a host', aside: 'if Zoomies has no agent of its own' },
  { label: 'Create a pool' },
  { label: 'Point a workflow at it' },
];

function frameC(state) {
  const rail = RAIL.map(
    (step) =>
      `<li${step.here ? ' aria-current="step"' : ''}><span class="c-rail-dot" aria-hidden="true">` +
      `${step.here ? icon('arrow-right', 12) : ''}</span><span>${esc(step.label)}` +
      `${step.aside ? ` <small>${esc(step.aside)}</small>` : ''}</span></li>`,
  ).join('');
  return (
    `<div class="m-form-page s-c"><div class="c-scene" aria-hidden="true"></div>` +
    `<div class="c-appearance">${appearance()}</div>` +
    `<div class="c-hero">${logo({ variant: 'mark', size: 96 })}<p class="c-eyebrow">First step</p>` +
    `<p class="c-tagline">First,<br>an account.</p>` +
    `<ol class="c-rail" aria-label="Setting up Zoomies">${rail}</ol>` +
    `<p class="c-lede">The Overview keeps this list and ticks it off.</p></div>` +
    `<section class="c-panel"><h1>Create the first account</h1>` +
    `<p class="c-panel-lede">This creates the first account, with the highest role (Platform), and closes for good once it has.</p>` +
    `${closedBanner(state)}<form novalidate>${fields(state, { afterToken: installHelp('c'), size: 'lg' })}${submit('lg')}</form>` +
    `<p class="m-note c-then-phone">${esc(THEN)}</p></section>` +
    `<footer class="c-footer">${links()}<span class="c-version">Zoomies ${VERSION}</span></footer></div>`
