    };
  });

const jobs = jobBase.map(([id, state, pool_id, runner_id, repo, workflow, job_name, head_branch, queuedMinutes], i) => {
  const pool = poolBase.find((p) => p[0] === pool_id);
  const runner = runner_id ? runnerBase.find((r) => r[0] === runner_id) : null;
  return {
    id,
    github_job_id: 90000 + i,
    github_run_id: 70000 + jobBase.findIndex((row) => row[0] === (SHARED_RUN[id] ?? id)),
    repo,
    workflow,
    job_name,
    labels: pool[3],
    state,
    ...(state === 'completed' ? { conclusion: i % 4 === 0 ? 'failure' : 'success' } : {}),
    installation_id: pool[2],
    pool_id,
    pool_name: pool[1],
    ...(runner ? { runner_id, runner_name: `${pool[1]}-${String(runnerBase.indexOf(runner) + 1).padStart(3, '0')}` } : {}),
    head_branch,
    run_number: 400 + i,
    queued_at: minutesAgo(queuedMinutes),
    ...(state !== 'queued' ? { started_at: minutesAgo(Math.max(queuedMinutes - 1, 1)) } : {}),
    ...(state === 'completed' ? { completed_at: minutesAgo(Math.max(queuedMinutes - 8, 0)), duration_ms: 420000 } : {}),
  };
});

const runners = buildRunners();

/** A run is its jobs, seen together: running if any is, else waiting if any is, else done. */
function deriveRuns(rows) {
  const byRun = new Map();
  for (const job of rows) byRun.set(job.github_run_id, [...(byRun.get(job.github_run_id) ?? []), job]);
  return [...byRun.values()].map((own) => {
    const first = own[0];
    const state = own.some((j) => j.state === 'in_progress')
      ? 'in_progress'
      : own.some((j) => j.state === 'queued')
        ? 'queued'
        : 'completed';
    return {
      repo: first.repo,
      workflow: first.workflow,
      github_run_id: first.github_run_id,
      run_number: first.run_number,
      run_attempt: 1,
      head_branch: first.head_branch,
      installation_id: first.installation_id,
      state,
      ...(state === 'completed' ? { conclusion: own.some((j) => j.conclusion === 'failure') ? 'failure' : 'success' } : {}),
      managed: true,
      hosted: false,
      jobs: own.length,
      queued_at: own.map((j) => j.queued_at).sort()[0],
      ...(state !== 'queued' ? { started_at: own.find((j) => j.started_at)?.started_at } : {}),
      ...(state === 'completed' ? { completed_at: own.map((j) => j.completed_at).sort().at(-1) } : {}),
    };
  });
}

