  margin-left: auto;
  padding: var(--z-space-1) var(--z-space-3);
  border: var(--z-border-width) solid var(--z-border-strong);
  border-radius: var(--z-radius-full);
  background: var(--z-surface-raised);
  font: inherit;
  font-size: var(--z-text-sm);
  color: var(--z-text-muted);
}
.k-search kbd {
  padding: 0 var(--z-space-2);
  border: var(--z-border-width) solid var(--z-border);
  border-radius: var(--z-radius-sm);
  font: inherit;
  font-size: var(--z-text-xs);
}
.k-account {
  display: inline-flex;
  align-items: center;
  gap: var(--z-space-2);
  font-size: var(--z-text-sm);
  color: var(--z-text-muted);
}
.k-page {
  display: flex;
  flex-direction: column;
  gap: var(--z-space-6);
  box-sizing: border-box;
  max-width: 80rem;
  margin-inline: auto;
  padding: var(--z-space-8);
}

/* ---- the page header ---- */
.k-page-head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--z-space-4);
}
.k-page-title {
  min-width: 0;
}
.k-page-title h1 {
  margin: 0;
  font-size: var(--z-text-2xl);
  line-height: var(--z-leading-2xl);
  font-weight: var(--z-weight-medium);
  letter-spacing: var(--z-tracking-tight);
  overflow-wrap: anywhere;
}
.k-eyebrow {
  margin: 0 0 var(--z-space-2);
  font-size: var(--z-text-2xs);
  font-weight: var(--z-weight-semibold);
  letter-spacing: var(--z-tracking-wider);
  text-transform: uppercase;
  color: var(--z-text-muted);
}
.k-rule {
  width: var(--z-space-10);
  height: var(--z-border-width-thick);
  margin-block: var(--z-space-4);
  background: var(--z-brand-runner-blue);
}
.k-subtitle {
  margin: 0;
  max-width: 40rem;
  color: var(--z-text-muted);
  text-wrap: pretty;
}
.k-page-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--z-space-2);
}

/* ---- cards ---- */
.k-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--z-space-4);
  min-width: 0;
  box-sizing: border-box;
  padding: var(--z-space-6);
  border: var(--z-border-width) solid var(--z-border);
  border-radius: var(--z-radius-xl);
  background: var(--z-surface-raised);
}
.k-card[data-tone='danger'] {
  border-color: var(--z-danger-border);
}
.k-card-head {
  display: flex;
  align-items: flex-start;
  gap: var(--z-space-3);
}
.k-card-heading {
  flex: 1;
  min-width: 0;
}
.k-card-title {
  margin: 0;
  font-size: var(--z-text-lg);
  line-height: var(--z-leading-lg);
  font-weight: var(--z-weight-medium);
  letter-spacing: var(--z-tracking-tight);
  overflow-wrap: anywhere;
}
.k-card-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--z-space-2);
}
/* The whole card is the target; the title is its name. */
.k-card-link {
  color: inherit;
  text-decoration: none;
}
.k-card-link::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
}
.is-link:hover,
.k-stat:hover {
  border-color: var(--z-border-strong);
}
.k-tile {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: var(--z-space-10);
  height: var(--z-space-10);
  border: var(--z-border-width) solid var(--z-border-strong);
  border-radius: var(--z-radius-md);
  background: var(--z-surface-sunken);
  color: var(--z-text);
}
.k-stat {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--z-space-2);
  min-width: 0;
  box-sizing: border-box;
  padding: var(--z-space-5);
  border: var(--z-border-width) solid var(--z-border);
  border-radius: var(--z-radius-xl);
  background: var(--z-surface-raised);
}
.k-stat-label {
  display: flex;
  align-items: center;
  gap: var(--z-space-2);
  margin: 0;
  font-size: var(--z-text-sm);
  color: var(--z-text-muted);
}
.k-stat-value {
  margin: 0;
  font-size: var(--z-text-3xl);
  line-height: var(--z-leading-3xl);
  font-weight: var(--z-weight-medium);
  letter-spacing: var(--z-tracking-tight);
  font-variant-numeric: tabular-nums;
}
.k-stat-note {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--z-space-2);
  margin: 0;
  font-size: var(--z-text-xs);
  color: var(--z-text-muted);
}
.k-grid {
  display: grid;
  gap: var(--z-space-4);
  grid-template-columns: repeat(auto-fit, minmax(min(14rem, 100%), 1fr));
}
.k-grid.wide {
  grid-template-columns: repeat(auto-fit, minmax(min(20rem, 100%), 1fr));
}

/* ---- the stage ---- */
.k-stage {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-direction: row-reverse;
  gap: var(--z-space-8);
  box-sizing: border-box;
  padding: var(--z-space-10) var(--z-space-12);
  border: var(--z-border-width) solid var(--z-panel-border);
  border-radius: var(--z-radius-xl);
  background: var(--z-panel-bg);
  color: var(--z-panel-text);
}
.k-stage-art {
  flex: none;
  width: clamp(6rem, 16%, 10rem);
}
.k-stage-art .logo {
  width: 100%;
}
.k-stage-words {
  min-width: 0;
}
.k-stage-eyebrow {
  margin: 0 0 var(--z-space-4);
  font-size: var(--z-text-2xs);
  font-weight: var(--z-weight-semibold);
  letter-spacing: var(--z-tracking-wider);
  text-transform: uppercase;
  color: var(--z-panel-text-muted);
}
.k-stage-headline {
  margin: 0;
  font-size: var(--z-text-3xl);
  line-height: var(--z-leading-3xl);
  font-weight: var(--z-weight-medium);
  letter-spacing: var(--z-tracking-tight);
  text-wrap: balance;
  overflow-wrap: anywhere;
}
.k-accent {
  color: var(--z-brand-runner-blue);
}
.k-stage .k-rule {
  margin-block: var(--z-space-5);
}
.k-stage-lede {
  margin: 0;
  max-width: 32rem;
  color: var(--z-panel-text-muted);
  text-wrap: pretty;
  overflow-wrap: anywhere;
}
.k-stage .m-btn {
  max-width: 100%;
  margin-top: var(--z-space-5);
  white-space: normal;
}

/* ---- pills: a word and a shape ---- */
.k-pill {
  display: inline-flex;
  align-items: center;
  gap: var(--z-space-2);
  box-sizing: border-box;
  padding: var(--z-space-1) var(--z-space-3);
  border: var(--z-border-width) solid var(--k-border, var(--z-neutral-border));
  border-radius: var(--z-radius-full);
  background: var(--k-bg, var(--z-neutral-subtle));
  font-size: var(--z-text-xs);
  font-weight: var(--z-weight-medium);
  color: var(--z-text);
  white-space: nowrap;
}
.k-pill::before {
  content: '';
  flex: none;
  width: var(--z-space-3);
  height: var(--z-space-3);
  background: var(--k-fg, var(--z-neutral));
}
.k-pill[data-state='idle'] {
  --k-fg: var(--z-idle);
  --k-bg: var(--z-idle-subtle);
  --k-border: var(--z-idle-border);
}
.k-pill[data-state='busy'] {
  --k-fg: var(--z-busy);
  --k-bg: var(--z-busy-subtle);
  --k-border: var(--z-busy-border);
}
.k-pill[data-state='pending'] {
  --k-fg: var(--z-pending);
  --k-bg: var(--z-pending-subtle);
  --k-border: var(--z-pending-border);
}
.k-pill[data-state='draining'] {
  --k-fg: var(--z-draining);
  --k-bg: var(--z-draining-subtle);
  --k-border: var(--z-draining-border);
}
.k-pill[data-state='danger'] {
  --k-fg: var(--z-danger);
  --k-bg: var(--z-danger-subtle);
  --k-border: var(--z-danger-border);
}
/* The shapes differ so greyscale and forced colours still tell the states apart:
   idle a disc, busy a diamond, pending a ring, draining a triangle, danger a
   square, neutral a bar. */
.k-pill[data-state='idle']::before {
  border-radius: var(--z-radius-full);
}
.k-pill[data-state='busy']::before {
  clip-path: polygon(50% 0, 100% 50%, 50% 100%, 0 50%);
}
.k-pill[data-state='pending']::before {
  background: transparent;
  border: var(--z-border-width-thick) solid var(--k-fg);
  border-radius: var(--z-radius-full);
  box-sizing: border-box;
}
.k-pill[data-state='draining']::before {
  clip-path: polygon(50% 0, 100% 100%, 0 100%);
}
.k-pill[data-state='danger']::before {
  border-radius: 0;
}
.k-pill[data-state='neutral']::before {
  height: var(--z-border-width-thick);
  align-self: center;
}
@media (forced-colors: active) {
  .k-pill::before {
    background: CanvasText;
  }
  .k-pill[data-state='pending']::before {
    background: transparent;
    border-color: CanvasText;
  }
}

/* ---- meters ---- */
.k-meter {
  display: inline-flex;
  align-items: center;
  gap: var(--z-space-2);
  min-width: 0;
}
.k-meter-track {
  flex: none;
  width: var(--z-space-16);
  height: var(--z-space-2);
  border-radius: var(--z-radius-full);
  background: var(--z-surface-sunken);
  box-shadow: inset 0 0 0 var(--z-border-width) var(--z-border);
}
.k-meter-fill {
  display: block;
  width: var(--k-fill);
  height: 100%;
  border-radius: inherit;
  background: var(--z-text-muted);
}
.k-meter-value {
  font-size: var(--z-text-xs);
  font-variant-numeric: tabular-nums;
  color: var(--z-text-muted);
}

/* ---- steps, checklist ---- */
.k-steps {
  display: grid;
  gap: var(--z-space-5);
  margin: 0;
  padding: 0;
  list-style: none;
}
.k-step {
  display: flex;
  align-items: flex-start;
  gap: var(--z-space-4);
}
.k-numeral {
  flex: none;
  min-width: 3.5rem;
  font-size: var(--z-text-3xl);
  line-height: var(--z-leading-3xl);
  font-weight: var(--z-weight-bold);
  font-variant-numeric: tabular-nums;
  color: transparent;
  -webkit-text-stroke: var(--z-border-width) var(--z-text-muted);
}
.k-step-title {
  margin: 0;
  font-size: var(--z-text-base);
  font-weight: var(--z-weight-semibold);
}
.k-step-text {
  margin: var(--z-space-1) 0 0;
  color: var(--z-text-muted);
  text-wrap: pretty;
}
.k-segments {
  display: flex;
  gap: var(--z-space-1);
}
.k-segment {
  flex: 1;
  height: var(--z-space-2);
  border-radius: var(--z-radius-full);
  background: var(--z-surface-sunken);
  box-shadow: inset 0 0 0 var(--z-border-width) var(--z-border);
}
.k-segment.is-done {
  background: var(--z-brand-runner-blue);
  box-shadow: none;
}
.k-checklist {
  display: flex;
  flex-direction: column;
  gap: var(--z-space-3);
  margin: 0;
  padding: 0;
  list-style: none;
}
.k-check {
  display: flex;
  align-items: center;
  gap: var(--z-space-3);
  padding: var(--z-space-3);
  border: var(--z-border-width) solid transparent;
  border-radius: var(--z-radius-lg);
}
.k-check.is-next {
  border-color: var(--z-border-strong);
  background: var(--z-surface-sunken);
}
.k-check-mark {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: var(--z-space-6);
  height: var(--z-space-6);
  border: var(--z-border-width-thick) solid var(--z-border-strong);
  border-radius: var(--z-radius-full);
  box-sizing: border-box;
}
.k-check.is-done .k-check-mark {
  background: var(--z-text);
  border-color: var(--z-text);
  color: var(--z-surface);
}
.k-check-text {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
  font-size: var(--z-text-sm);
  color: var(--z-text-muted);
}
.k-check-text strong {
  font-size: var(--z-text-base);
  color: var(--z-text);
}
.k-check.is-done .k-check-text strong {
  font-weight: var(--z-weight-normal);
  color: var(--z-text-muted);
}

/* ---- tables ---- */
.k-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--z-space-3);
}
.k-filters {
  display: flex;
  flex-wrap: wrap;
  gap: var(--z-space-2);
}
.k-filter {
  display: inline-flex;
  align-items: center;
  gap: var(--z-space-2);
  min-height: var(--z-space-10);
  padding: var(--z-space-1) var(--z-space-4);
  border: var(--z-border-width) solid var(--z-border-strong);
  border-radius: var(--z-radius-full);
  background: var(--z-surface-raised);
  font: inherit;
  font-size: var(--z-text-sm);
  color: var(--z-text);
}
.k-filter[aria-pressed='true'] {
  border-color: var(--z-text);
  background: var(--z-surface-sunken);
  font-weight: var(--z-weight-semibold);
}
.k-filter-count {
  color: var(--z-text-muted);
  font-variant-numeric: tabular-nums;
}
/* The table scrolls here, inside its card, and the page never does. */
.k-scroll {
  overflow-x: auto;
  margin-inline: calc(-1 * var(--z-space-6));
  padding-inline: var(--z-space-6);
}
.k-scroll:focus-visible {
  outline: var(--z-focus-width) solid var(--z-focus-colour);
  outline-offset: calc(-1 * var(--z-focus-width));
}
.k-table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--z-text-sm);
}
.k-table th {
  padding: var(--z-space-3) var(--z-space-4) var(--z-space-3) 0;
  border-bottom: var(--z-border-width) solid var(--z-border-strong);
  font-size: var(--z-text-xs);
  font-weight: var(--z-weight-semibold);
  letter-spacing: var(--z-tracking-wide);
  text-align: left;
  text-transform: uppercase;
  white-space: nowrap;
  color: var(--z-text-muted);
}
.k-table td {
  padding: var(--z-space-3) var(--z-space-4) var(--z-space-3) 0;
  border-bottom: var(--z-border-width) solid var(--z-border);
  vertical-align: middle;
  white-space: nowrap;
}
.k-table .is-end {
  text-align: right;
}
.k-table .is-mono {
  font-family: var(--z-font-mono, ui-monospace, monospace);
  font-size: var(--z-text-xs);
}
.k-table .is-truncate {
  max-width: 14rem;
}
.k-table .is-wrap {
  min-width: 14rem;
  max-width: 32rem;
  white-space: normal;
  overflow-wrap: anywhere;
}
/* A name clipped to a line is shown whole while its row has keyboard focus, so
   what a mouse reads from the title a keyboard reads by tabbing to the row. */
.k-table tr:focus-within .k-clip {
  white-space: normal;
  overflow-wrap: anywhere;
}
.k-clip {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---- states of a list ---- */
.k-skeleton {
  display: flex;
  flex-direction: column;
  gap: var(--z-space-3);
}
.k-skeleton-row {
  display: block;
  height: var(--z-space-8);
  border-radius: var(--z-radius-md);
  background: var(--z-surface-sunken);
}
@media (prefers-reduced-motion: no-preference) {
  .k-skeleton-row {
    animation: k-pulse 1.4s ease-in-out infinite;
  }
}
@keyframes k-pulse {
  50% {
    opacity: 0.5;
  }
}
.k-empty,
.k-failure {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--z-space-3);
  padding: var(--z-space-6);
  border: var(--z-border-width) dashed var(--z-border-strong);
  border-radius: var(--z-radius-lg);
}
.k-failure {
  flex-direction: row;
  border-style: solid;
  border-color: var(--z-danger-border);
  background: var(--z-danger-subtle);
}
.k-empty-title {
  margin: 0;
  font-size: var(--z-text-base);
  font-weight: var(--z-weight-semibold);
}
.k-empty-text {
  margin: var(--z-space-1) 0 var(--z-space-3);
  max-width: 36rem;
  color: var(--z-text-muted);
  text-wrap: pretty;
}
.k-stale {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--z-space-2);
  padding: var(--z-space-2) var(--z-space-4);
  border: var(--z-border-width) solid var(--z-pending-border);
  border-radius: var(--z-radius-lg);
  background: var(--z-pending-subtle);
  font-size: var(--z-text-sm);
}

/* ---- the phone ---- */
.k-bar,
.k-sheet:not(:popover-open) {
  display: none;
}
@media (max-width: 768px) {
  .k-app,
  .k-app.is-collapsed {
    grid-template-columns: minmax(0, 1fr);
  }
  .k-side {
    display: none;
  }
  .k-top {
    padding: var(--z-space-3) var(--z-space-4);
  }
  .k-top-brand {
    display: flex;
  }
  .k-page {
    padding: var(--z-space-4) var(--z-space-4) calc(var(--z-control-touch) + var(--z-space-12));
  }
  .k-account span:last-child {
    display: none;
  }
  .k-stage {
    flex-direction: row;
    padding: var(--z-space-6);
  }
  .k-stage-art {
    width: 5.5rem;
  }
  .k-stage-headline {
    font-size: var(--z-text-xl);
    line-height: var(--z-leading-xl);
  }
  .k-stage .k-rule {
    display: none;
  }
  .k-bar {
    position: fixed;
    inset: auto 0 0;
    z-index: var(--z-layer-nav);
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    border-top: var(--z-border-width) solid var(--z-border);
    background: var(--z-surface-raised);
  }
  .k-bar-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: var(--z-space-1);
    min-height: var(--z-control-touch);
    padding: var(--z-space-2) 0;
    border: 0;
    background: none;
    font: inherit;
    font-size: var(--z-text-2xs);
    color: var(--z-text-muted);
    text-decoration: none;
  }
  .k-bar-item[aria-current='page'] {
    color: var(--z-text);
    font-weight: var(--z-weight-semibold);
    box-shadow: inset 0 var(--z-border-width-thick) 0 var(--z-brand-runner-blue);
  }
  .k-sheet {
    inset: auto 0 0;
    width: 100%;
    max-height: 80vh;
    margin: 0;
    box-sizing: border-box;
    overflow-y: auto;
    padding: var(--z-space-4);
    border: var(--z-border-width) solid var(--z-border-strong);
    border-radius: var(--z-radius-xl) var(--z-radius-xl) 0 0;
    background: var(--z-surface-raised);
    color: var(--z-text);
  }
  .k-sheet-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: var(--z-space-3);
  }
  .k-sheet .k-nav-item {
    min-height: var(--z-control-touch);
  }
  .k-scroll {
    margin-inline: calc(-1 * var(--z-space-4));
    padding-inline: var(--z-space-4);
  }
  .k-card,
  .k-stat {
    padding: var(--z-space-4);
  }
  .k-grid {
    grid-template-columns: repeat(auto-fit, minmax(min(10rem, 100%), 1fr));
  }
}

/* ---- section headings and rows inside cards ---- */
.k-section-title {
  margin: 0;
  font-size: var(--z-text-lg);
  line-height: var(--z-leading-lg);
  font-weight: var(--z-weight-medium);
  letter-spacing: var(--z-tracking-tight);
}
.k-facts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--z-space-3) var(--z-space-4);
  margin: 0;
  font-size: var(--z-text-sm);
}
.k-facts dt {
  font-size: var(--z-text-xs);
  color: var(--z-text-muted);
}
.k-facts dd {
  margin: 0;
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
}
.k-list {
  display: flex;
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style: none;
}
.k-list > li {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: var(--z-space-3);
  padding-block: var(--z-space-3);
  border-bottom: var(--z-border-width) solid var(--z-border);
}
.k-list > li:last-child {
  border-bottom: 0;
}
.k-list-main {
  flex: 1;
  min-width: 12rem;
}
.k-list-main strong {
  display: block;
  overflow-wrap: anywhere;
}
.k-list-main span {
  font-size: var(--z-text-sm);
  color: var(--z-text-muted);
  overflow-wrap: anywhere;
}

/* ---- a cell that stacks two names ---- */
.k-stack {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.k-stack > .k-clip:first-child {
  font-weight: var(--z-weight-semibold);
}
.k-stack > .k-clip:last-child {
  font-size: var(--z-text-xs);
  color: var(--z-text-muted);
}
.k-table code {
  font-size: var(--z-text-xs);
}
@media (max-width: 768px) {
  .k-table .m-btn {
    min-height: var(--z-control-touch);
  }
}

/* ---- a step the person is on, and the ones behind them ---- */
.k-step[aria-current='step'] .k-numeral {
  -webkit-text-stroke-color: var(--z-text);
}
.k-step[aria-current='step'] .k-step-title {
  font-weight: var(--z-weight-bold);
}
.k-step.is-done .k-numeral {
  color: var(--z-text-muted);
}
.k-wizard {
  display: grid;
  gap: var(--z-space-6);
  grid-template-columns: minmax(0, 1fr) minmax(0, 2fr);
  align-items: start;
}
.k-form {
  display: flex;
  flex-direction: column;
  gap: var(--z-space-5);
}
.k-form-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--z-space-2);
  justify-content: flex-end;
}
.k-savebar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--z-space-3);
  padding: var(--z-space-3) var(--z-space-4);
  border: var(--z-border-width) solid var(--z-border-strong);
  border-radius: var(--z-radius-lg);
  background: var(--z-surface-raised);
}
@media (max-width: 768px) {
  .k-wizard {
    grid-template-columns: minmax(0, 1fr);
  }
}
/* A field a thumb has to hit is the touch size, at any width: a form is where a
   missed tap costs the most. */
.k-form .m-input {
  min-height: var(--z-control-touch);
}

@media (max-width: 768px) {
  .k-filter,
  .k-page-actions .m-btn,
  .k-list .m-btn,
  .k-search,
  .k-stage .m-btn {
    min-height: var(--z-control-touch);
  }
}
/* 2.4 the page behind the More sheet is dimmed, so an open sheet looks open. */
.k-sheet::backdrop {
  background: var(--z-scrim);
}

// The portal-style parts, built once, so every signed-in mock is made of the same
// pieces and the pages share a look because they share parts.
//
// Each function returns markup and takes data through esc(), as pack 1's ui.js
// does. The sidebar's entries are the product's own (web/src/lib/shell/sections.ts),
// in the same order and under the same four headings, so a mock is judged on
// the page and not on a navigation somebody reinvented.
//
// The look is the public pages' (web/src/lib/public/): the dark stage, the
// eyebrow and large headline over a short blue rule, icon tiles, outlined
// numerals and a pill with a word and a shape. What this file adds is what a
// signed-in page needs and a sign-in page does not: a shell, a table card, and
// the four states of a list.
import { icon } from '/review/icons.js';
import { button, esc, logo } from '/review/ui.js';
import { NOW } from '/signed-in/fixture.js';

/** The product's sections, in order. `primary` is what a phone's bottom bar keeps. */
export const pages = [
  { id: 'overview', label: 'Overview', icon: 'layout-dashboard', primary: true },
  { id: 'pools', label: 'Pools', icon: 'boxes', primary: true, group: 'Fleet' },
  { id: 'runners', label: 'Runners', icon: 'server', primary: true, group: 'Fleet' },
  { id: 'queue', label: 'Queue', icon: 'list-ordered', group: 'Fleet' },
  { id: 'workflows', label: 'Workflows', icon: 'workflow', primary: true, group: 'Fleet' },
  { id: 'usage', label: 'Usage', icon: 'chart-no-axes-combined', group: 'Fleet' },
  { id: 'hosts', label: 'Hosts', icon: 'hard-drive', group: 'Infrastructure' },
  { id: 'providers', label: 'Providers', icon: 'cloud', group: 'Infrastructure' },
  { id: 'installations', label: 'Installations', icon: 'plug', group: 'GitHub' },
  { id: 'repairs', label: 'Eli repairs', icon: 'git-pull-request-arrow', group: 'GitHub' },
  { id: 'migrate', label: 'Migrate', icon: 'git-pull-request-arrow', group: 'GitHub' },
  { id: 'kennel', label: 'Kennel Club', icon: 'trophy', group: 'GitHub' },
  { id: 'audit', label: 'Audit', icon: 'scroll-text', group: 'Administration' },
  { id: 'settings', label: 'Settings', icon: 'settings', group: 'Administration' },
];

/** The review page's hash for a page, in the style and mode the reader is in. */
const link = (id) => `#screen=${id}`;

/* ---- small parts ---- */

/**
 * A state, as a word and a shape. The shape is drawn by CSS from data-state and
 * the word is always there, so a pill survives greyscale, forced colours and a
 * screen reader. Colour is the third cue, never the only one.
 */
export function pill({ state = 'neutral', label }) {
  return `<span class="k-pill" data-state="${esc(state)}">${esc(label)}</span>`;
}

/** The square a glyph sits in, as the portal's feature tiles. */
export function tile({ icon: name, size = 18 }) {
  return `<span class="k-tile" aria-hidden="true">${icon(name, size)}</span>`;
}

/** A thin bar with its number beside it: the number is the reading, the bar is the shape of it. */
export function meter({ value, label }) {
  const percent = Math.round(Math.min(Math.max(value, 0), 1) * 100);
  return (
    `<span class="k-meter"><span class="k-meter-track" aria-hidden="true">` +
    `<span class="k-meter-fill" style="--k-fill: ${percent}%"></span></span>` +
    `<span class="k-meter-value">${esc(label ?? `${percent}%`)}</span></span>`
  );
}

/** How long before NOW, in the shortest words that say it. */
export function relative(iso) {
  const minutes = Math.round((new Date(NOW).getTime() - new Date(iso).getTime()) / 60_000);
  if (minutes < 1) return 'just now';
  if (minutes < 60) return `${minutes} min ago`;
  if (minutes < 60 * 48) return `${Math.round(minutes / 60)} h ago`;
  return `${Math.round(minutes / (60 * 24))} d ago`;
}

/* ---- cards ---- */

/**
 * The basic container. `html` is trusted markup; a caller puts data through esc().
 * `href` makes the whole card the link, with the title as its name.
 */
export function card({ title, eyebrow, icon: name, actions = '', html = '', href, tone = 'neutral', headingLevel = 2 }) {
  const heading = title
    ? `<h${headingLevel} class="k-card-title">${href ? `<a class="k-card-link" href="${esc(href)}">${esc(title)}</a>` : esc(title)}</h${headingLevel}>`
    : '';
  const head =
    title || eyebrow || actions
      ? `<header class="k-card-head">${name ? tile({ icon: name }) : ''}<div class="k-card-heading">` +
        `${eyebrow ? `<p class="k-eyebrow">${esc(eyebrow)}</p>` : ''}${heading}</div>` +
        `${actions ? `<div class="k-card-actions">${actions}</div>` : ''}</header>`
      : '';
  return `<section class="k-card${href ? ' is-link' : ''}" data-tone="${esc(tone)}">${head}${html}</section>`;
}

/** A number with its name, as a card the whole of which goes to the page that explains it. */
export function stat({ label, value, note = '', href, state, stateLabel, icon: name }) {
  return (
    `<div class="k-stat">` +
    `<p class="k-stat-label">${name ? tile({ icon: name, size: 16 }) : ''}<span>${esc(label)}</span></p>` +
    `<p class="k-stat-value">${href ? `<a class="k-card-link" href="${esc(href)}">${esc(value)}</a>` : esc(value)}</p>` +
    `<p class="k-stat-note">${state ? pill({ state, label: stateLabel }) : ''}${note ? `<span>${esc(note)}</span>` : ''}</p>` +
    `</div>`
  );
}

/**
 * The dark panel: what the page is about in one headline, as the public pages' stage is.
 * Neutral white and the brand blue only; a status colour here would be legible on
 * the theme it was drawn in and wrong on the other, because the panel never changes.
 */
export function stage({ eyebrow, headline, accent, lede, html = '', art = true }) {
  const lines = Array.isArray(headline) ? headline : [headline];
  return (
    `<section class="k-stage">` +
    (art ? `<div class="k-stage-art">${logo({ variant: 'mark', size: 96, label: '' })}</div>` : '') +
    `<div class="k-stage-words">` +
    (eyebrow ? `<p class="k-stage-eyebrow">${esc(eyebrow)}</p>` : '') +
    `<p class="k-stage-headline">${lines.map(esc).join('<br>')}${accent ? `<br><span class="k-accent">${esc(accent)}</span>` : ''}</p>` +
    `<div class="k-rule" aria-hidden="true"></div>` +
    (lede ? `<p class="k-stage-lede">${esc(lede)}</p>` : '') +
    html +
    `</div></section>`
  );
}

/** Numbered steps, as the portal's outlined 01 02 03. */
export function steps(items, current = -1) {
  return (
    `<ol class="k-steps">` +
    items
      .map(
        (item, i) =>
          `<li class="k-step${i < current ? ' is-done' : ''}"${i === current ? ' aria-current="step"' : ''}><span class="k-numeral" aria-hidden="true">${String(i + 1).padStart(2, '0')}</span>` +
          `<div><h3 class="k-step-title">${esc(item.title)}</h3><p class="k-step-text">${esc(item.text)}</p></div></li>`,
      )
      .join('') +
    `</ol>`
  );
}

/** "Your next step": the checklist, with its progress as segments and as words. */
export function checklist({ title = 'Your next step', items }) {
  const done = items.filter((item) => item.done).length;
  const next = items.find((item) => !item.done);
  return card({
    eyebrow: `${done} of ${items.length} done`,
    title,
    html:
      `<div class="k-segments" role="img" aria-label="${done} of ${items.length} steps done">` +
      items.map((item) => `<span class="k-segment${item.done ? ' is-done' : ''}"></span>`).join('') +
      `</div><ul class="k-checklist">` +
      items
        .map(
          (item) =>
            `<li class="k-check${item.done ? ' is-done' : ''}${item === next ? ' is-next' : ''}">` +
            `<span class="k-check-mark" aria-hidden="true">${item.done ? icon('check', 14) : ''}</span>` +
            `<span class="k-check-text"><strong>${esc(item.label)}</strong>${item.text ? `<span>${esc(item.text)}</span>` : ''}</span>` +
            `${item === next && item.action ? button({ label: item.action, variant: 'primary', size: 'md', href: '#' }) : ''}</li>`,
        )
        .join('') +
      `</ul>`,
  });
}

/** Name and value pairs, two to a row. A value is trusted markup, so a caller escapes data. */
export function facts(pairs) {
  return `<dl class="k-facts">${pairs.map(([name, value]) => `<div><dt>${esc(name)}</dt><dd>${value}</dd></div>`).join('')}</dl>`;
}

/* ---- the four states of a list ---- */

/** Placeholder blocks while the first fetch is out. Still, for anyone who asks for less motion. */
export function skeleton({ rows = 5, label = 'Loading' }) {
  return (
    `<div class="k-skeleton" aria-busy="true"><span class="sr-only" role="status">${esc(label)}</span>` +
    Array.from({ length: rows }, () => `<span class="k-skeleton-row" aria-hidden="true"></span>`).join('') +
    `</div>`
  );
}

/** Nothing here yet, and what to do about it. */
export function empty({ icon: name = 'sparkles', title, text, action }) {
  return (
    `<div class="k-empty">${tile({ icon: name, size: 20 })}<h3 class="k-empty-title">${esc(title)}</h3>` +
    `<p class="k-empty-text">${esc(text)}</p>${action ? button({ label: action, variant: 'primary', href: '#' }) : ''}</div>`
  );
}

/** The fetch failed. Says what, and offers the retry. */
export function failure({ title, text, retry = 'Try again' }) {
  return (
    `<div class="k-failure" role="alert">${icon('triangle-alert', 18)}<div><h3 class="k-empty-title">${esc(title)}</h3>` +
    `<p class="k-empty-text">${esc(text)}</p>${button({ label: retry, variant: 'secondary', icon: 'refresh-cw', href: '#' })}</div></div>`
  );
}

/** The rows you are looking at are the last good ones, and the refresh after them failed. */
export function staleBanner({ ago, text = 'The controller did not answer the last refresh.' }) {
  return (
    `<div class="k-stale" role="status">${icon('clock', 14)}<span>${esc(text)} Showing what it said ${esc(ago)}.</span>` +
    `${button({ label: 'Refresh', variant: 'ghost', size: 'sm', icon: 'refresh-cw', href: '#' })}</div>`
  );
}

/**
 * A table in a card. The table stays a table and scrolls inside the card, never the
 * page; a cell of `truncate` columns holds a long name to one line and keeps all of
 * it in the title, so the full text is reachable by hover, focus and a screen reader.
 * columns: [{ label, truncate?, align?, mono? }]; rows: arrays of trusted markup.
 */
export function tableCard({ title, eyebrow, caption, columns, rows, actions = '', foot = '', icon: name, toolbar = '' }) {
  const head = columns
    .map((column) => `<th scope="col"${column.align === 'end' ? ' class="is-end"' : ''}>${esc(column.label)}</th>`)
    .join('');
  const body = rows
    .map(
      (row) =>
        `<tr>${row
          .map((cell, i) => {
            const column = columns[i];
            const classes = [column.align === 'end' && 'is-end', column.mono && 'is-mono', column.truncate && 'is-truncate', column.wrap && 'is-wrap']
              .filter(Boolean)
              .join(' ');
            return `<td${classes ? ` class="${classes}"` : ''}>${cell}</td>`;
          })
          .join('')}</tr>`,
    )
    .join('');
  return card({
    title,
    eyebrow,
    icon: name,
    actions,
    html:
      (toolbar ? `<div class="k-toolbar">${toolbar}</div>` : '') +
      `<div class="k-scroll" role="region" tabindex="0" aria-label="${esc(caption ?? title)}">` +
      `<table class="k-table"><caption class="sr-only">${esc(caption ?? title)}</caption>` +
      `<thead><tr>${head}</tr></thead><tbody>${body}</tbody></table></div>${foot}`,
  });
}

/** A cell that holds a long name to a line and keeps all of it. */
export const clip = (text) => `<span class="k-clip" title="${esc(text)}">${esc(text)}</span>`;

/** Filter pills. The one that is on says so with aria-pressed and a tick, not a colour. */
export function filters(options, active) {
  return (
    `<div class="k-filters" role="group" aria-label="Filter">` +
    options
      .map(
        ({ id, label, count }) =>
          `<button type="button" class="k-filter" aria-pressed="${id === active}">` +
          `${id === active ? icon('check', 12) : ''}<span>${esc(label)}</span>${count === undefined ? '' : `<span class="k-filter-count">${esc(count)}</span>`}</button>`,
      )
      .join('') +
    `</div>`
  );
}

/* ---- the shell ---- */

function nav(active, collapsed) {
  const groups = [];
  for (const page of pages) {
    const name = page.group ?? '';
    if (!groups.length || groups.at(-1).name !== name) groups.push({ name, items: [] });
    groups.at(-1).items.push(page);
  }
  return groups
    .map(
      (group) =>
        `<div class="k-group">${group.name ? `<p class="k-group-name">${esc(group.name)}</p>` : ''}` +
        group.items
          .map(
            (page) =>
              `<a class="k-nav-item" href="${link(page.id)}"${page.id === active ? ' aria-current="page"' : ''}` +
              `${collapsed ? ` title="${esc(page.label)}"` : ''}>${icon(page.icon, 18)}<span class="k-nav-label">${esc(page.label)}</span></a>`,
          )
          .join('') +
        `</div>`,
    )
    .join('');
}

/**
 * The page: sidebar, top bar, header and body. On a phone the sidebar becomes a
 * bar of the four sections an operator watches a fleet with and a "More" sheet for
 * the rest; the sheet is a native popover, so it opens, closes on Escape and gives
 * focus back to its button without a line of script.
 */
export function shell({ page, title, eyebrow, subtitle, actions = '', body, collapsed = false, banner = '' }) {
  const primaries = pages.filter((p) => p.primary);
  return (
    `<div class="k-app${collapsed ? ' is-collapsed' : ''}">` +
    `<aside class="k-side"><div class="k-side-inner"><a class="k-brand" href="${link('overview')}" aria-label="Zoomies, Overview">${logo({ variant: 'full', size: 28, label: '' })}</a>` +
    `<nav class="k-nav" aria-label="Primary">${nav(page, collapsed)}</nav></div></aside>` +
    `<div class="k-main"><header class="k-top">` +
    `<a class="k-top-brand" href="${link('overview')}" aria-label="Zoomies, Overview">${logo({ variant: 'mark', size: 28, label: '' })}</a>` +
    `<button type="button" class="k-search">${icon('search', 15)}<span>Search</span><kbd>/</kbd></button>` +
    `<span class="k-account">${icon('user-round', 15)}<span>ada</span></span></header>` +
    `<div class="k-page" id="k-page">${banner}<header class="k-page-head"><div class="k-page-title">` +
    (eyebrow ? `<p class="k-eyebrow">${esc(eyebrow)}</p>` : '') +
    `<h1>${esc(title)}</h1><div class="k-rule" aria-hidden="true"></div>` +
    (subtitle ? `<p class="k-subtitle">${esc(subtitle)}</p>` : '') +
    `</div>${actions ? `<div class="k-page-actions">${actions}</div>` : ''}</header>${body}</div></div>` +
    `<nav class="k-bar" aria-label="Primary, phone">` +
    primaries
      .map(
        (p) =>
          `<a class="k-bar-item" href="${link(p.id)}"${p.id === page ? ' aria-current="page"' : ''}>${icon(p.icon, 20)}<span>${esc(p.label)}</span></a>`,
      )
      .join('') +
    `<button type="button" class="k-bar-item" popovertarget="k-more" aria-label="More pages">${icon('menu', 20)}<span>More</span></button></nav>` +
    `<div id="k-more" class="k-sheet" popover aria-label="All pages"><div class="k-sheet-head"><strong>All pages</strong>` +
    `<button type="button" class="m-icon-btn" popovertarget="k-more" popovertargetaction="hide" aria-label="Close" autofocus>${icon('x', 16)}</button></div>` +
    `<nav aria-label="Pages">${nav(page, false)}</nav></div></div>`
  );
}

// What the kit promises that a page's own test would not think to ask: that a
// tile is a tile, that a sentence is not cut off, that a clipped name can be read
// without a mouse, that a thumb can hit what is on a phone, that the More sheet
// takes focus, and that the stylesheet uses the product's own breakpoint and layers.
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { launch } from '../tools/lib/browser.mjs';
import { serve } from '../tools/serve.mjs';

let browser;
let server;
before(async () => {
  browser = await launch();
  server = await serve(0);
});
after(async () => {
  await browser?.close();
  await server?.close();
});

async function open(screen, state = 'rows', width = 1440) {
  const context = await browser.newContext({ viewport: { width, height: 900 } });
  const page = await context.newPage();
  const hash = `#screen=${screen}&concept=a&style=mission-control&mode=dark&state=${state}`;
  await page.goto(`${server.url}/signed-in/mockups.html${hash}`);
  await page.waitForFunction((h) => document.documentElement.dataset.rendered === h, hash);
  return { page, context };
}

const css = readFileSync(fileURLToPath(new URL('./kit.css', import.meta.url)), 'utf8');

test('an icon tile is a tile: bigger than the glyph it holds, with the glyph inside it', async () => {
  const { page, context } = await open('overview', 'attention');
  const { tile, glyph } = await page.evaluate(() => {
    const t = document.querySelector('.k-tile');
    return { tile: t.getBoundingClientRect().width, glyph: t.querySelector('svg').getBoundingClientRect().width };
  });
  assert.ok(tile >= 32, `the tile is ${tile}px`);
  assert.ok(tile > glyph + 8, `the tile is ${tile}px around a ${glyph}px glyph`);
  await context.close();
});

for (const screen of ['queue', 'repairs', 'kennel', 'installations', 'ai-context', 'providers']) {
  test(`${screen}: a sentence is not cut off at 1440 with room to spare`, async () => {
    const { page, context } = await open(screen, screen === 'repairs' || screen === 'kennel' || screen === 'ai-context' ? 'normal' : 'rows');
    const cut = await page.$$eval('.k-table .k-clip', (els) =>
      els
        .filter((el) => el.title.trim().split(/\s+/).length >= 6 && el.scrollWidth > el.clientWidth + 1)
        .map((el) => el.title),
    );
    assert.deepEqual(cut, [], 'sentences the page exists to give are clipped');
    await context.close();
  });
}

test('a clipped name is read in full when its row is focused, without a mouse', async () => {
  const { page, context } = await open('jobs');
  const row = page.locator('.k-table tbody tr', { has: page.locator('.k-clip[title^="acme-corp/a-repository"]') });
  const clip = row.locator('.k-clip[title^="acme-corp/a-repository"]');
  assert.ok((await clip.evaluate((el) => el.scrollWidth - el.clientWidth)) > 0, 'it is clipped at rest');
  await row.getByRole('link', { name: /^Open/ }).focus();
  assert.ok((await clip.evaluate((el) => el.scrollWidth - el.clientWidth)) <= 1, 'focusing the row shows all of it');
  await context.close();
});

test('on a phone, filters, page actions, list buttons and search are 44px or more', async () => {
  for (const [screen, state, selector] of [
    ['runners', 'rows', '.k-filter'],
    ['runners', 'rows', '.k-page-actions .m-btn'],
    ['overview', 'attention', '.k-list .m-btn'],
    ['overview', 'attention', '.k-search'],
  ]) {
    const { page, context } = await open(screen, state, 375);
    const heights = await page.$$eval(`#stage ${selector}`, (els) => els.map((el) => el.getBoundingClientRect().height));
    assert.ok(heights.length > 0, `${selector} on ${screen}`);
    for (const height of heights) assert.ok(height >= 44, `${selector} is ${height}px tall on ${screen}`);
    await context.close();
  }
});

test('the buttons in the Overview problem list are each named for their problem', async () => {
  const { page, context } = await open('overview', 'attention');
  const names = await page.$$eval('.k-list .m-btn', (els) => els.map((el) => el.getAttribute('aria-label')));
  assert.ok(names.length >= 2);
  assert.equal(new Set(names).size, names.length, 'every one has its own name');
  for (const name of names) assert.match(name, /^Open .{10,}/);
  await context.close();
});

test('opening the More sheet moves focus into it, and the page behind it is dimmed', async () => {
  const { page, context } = await open('overview', 'attention', 375);
  await page.getByRole('button', { name: 'More pages' }).click();
  await page.locator('#k-more').waitFor({ state: 'visible' });
  assert.equal(await page.evaluate(() => document.getElementById('k-more').contains(document.activeElement)), true);
