      return {
        page: document.documentElement.scrollWidth - innerWidth,
        scrolls: region.scrollWidth > region.clientWidth,
        tabindex: region.getAttribute('tabindex'),
        name: region.getAttribute('aria-label'),
        role: region.getAttribute('role'),
      };
