  noun: 'Kennel Club',
  normalLabel: 'Findings',
  actions: button({ label: 'Check now', variant: 'secondary', icon: 'refresh-cw', href: '#' }),
  currentAlt: 'Today’s Kennel Club page: tiles of counts above a long table of repositories and checks.',
  empty: {
