        ? 'The first finding is an error: a pull request from a fork can run on your own runners.'
        : 'Nothing is blocking and nothing is waiting on you.',
    }) +
    `<div class="k-grid wide">${repositories.map(repositoryCard).join('')}</div>` +
    tableCard({
