const PORT = 8096;
const SIZES = [
  { width: 1440, height: 900 },
  { width: 375, height: 812 },
];
/** The tallest a picture is allowed to be. The real height is recorded beside it. */
const MAX_HEIGHT = 2400;

/** Pages that need no id. The sidebar's own order, then the setup flows. */
export const STATIC_PAGES = [
  { id: 'overview', path: '/' },
  { id: 'pools', path: '/pools' },
  { id: 'runners', path: '/runners' },
  { id: 'queue', path: '/queue' },
  { id: 'jobs', path: '/jobs' },
  { id: 'workflows', path: '/workflows' },
  { id: 'comparisons', path: '/comparisons' },
  { id: 'usage', path: '/usage' },
  { id: 'hosts', path: '/hosts' },
  { id: 'providers', path: '/providers' },
  { id: 'installations', path: '/installations' },
  { id: 'repairs', path: '/repairs' },
  { id: 'migrate', path: '/migrate' },
  { id: 'kennel', path: '/kennel' },
  { id: 'ai-context', path: '/ai-context' },
  { id: 'audit', path: '/audit' },
  { id: 'settings', path: '/settings' },
  { id: 'pool-new', path: '/pools/new' },
  { id: 'host-new', path: '/hosts/new' },
  { id: 'provider-new', path: '/providers/new' },
];

/** Pages reached through the first thing of a kind the fleet has. */
export const DETAIL_PAGES = [
  { id: 'pool-detail', api: '/api/v1/pools', path: (id) => `/pools/${id}` },
  { id: 'host-detail', api: '/api/v1/hosts', path: (id) => `/hosts/${id}` },
  { id: 'runner-detail', api: '/api/v1/runners?limit=1', path: (id) => `/runners/${id}` },
];

/** Every file name this script writes for the pages it photographs. */
export function files(ids) {
  return ids.flatMap((id) => SIZES.map((size) => `current-${id}-${size.width}.png`));
}

async function startController() {
  const child = spawn('node', [join('tests/support', 'serve.mjs'), String(PORT)], {
    cwd: web,
    stdio: ['ignore', 'ignore', 'inherit'],
  });
  const exited = new Promise((done) => child.once('exit', done));
  const url = `http://127.0.0.1:${PORT}`;
  for (let i = 0; i < 150; i++) {
    if (child.exitCode !== null) throw new Error('the demo controller exited before it was ready');
    try {
      if ((await fetch(`${url}/healthz`)).ok) {
        return {
          url,
          stop: async () => {
            child.kill('SIGTERM');
            await exited;
          },
        };
      }
    } catch {
      /* not listening yet */
    }
    await sleep(200);
  }
  child.kill('SIGTERM');
  throw new Error(`the demo controller did not become healthy on port ${PORT}`);
}

/** What the findings cite, read from the page as rendered. */
function read(viewportHeight) {
  const table = document.querySelector('main table, [role="grid"], [role="table"]');
  const headers = table
    ? [...table.querySelectorAll('th, [role="columnheader"]')].map((el) => el.textContent.trim())
    : [];
  return {
    documentHeight: document.documentElement.scrollHeight,
    viewportHeight,
    scrollsSideways: document.documentElement.scrollWidth > innerWidth,
    heading: document.querySelector('h1')?.textContent.trim() ?? null,
    tables: document.querySelectorAll('main table, main [role="grid"]').length,
    columns: headers.length,
    cards: document.querySelectorAll('main [class*="card"]').length,
    buttons: document.querySelectorAll('main button, main a.btn').length,
  };
}

async function main(argv) {
  const only = (argv[0] ?? '').split(',').filter(Boolean);
  const controller = await startController();
  const browser = await launch();
  const measurements = { generated: new Date().toISOString(), look: 'mission-control dark', shots: {} };
  try {
    const context = await browser.newContext({
      baseURL: controller.url,
      viewport: SIZES[0],
      colorScheme: 'dark',
      deviceScaleFactor: 1,
    });
    await context.addInitScript(rememberLook, storedLook('dark', 'mission-control'));
    const page = await context.newPage();

    const pages = [...STATIC_PAGES];
    for (const detail of DETAIL_PAGES) {
      const body = await (await context.request.get(`${controller.url}${detail.api}`)).json();
      const first = body.items?.[0]?.id;
      if (first) pages.push({ id: detail.id, path: detail.path(first) });
    }

    for (const target of pages.filter((p) => only.length === 0 || only.includes(p.id))) {
      for (const size of SIZES) {
        await page.setViewportSize(size);
        await page.goto(target.path, { waitUntil: 'networkidle' });
        await page.locator('main h1, h1').first().waitFor({ timeout: 15000 }).catch(() => {});
        await assertLook(page, target.id, 'dark', 'mission-control');
        await page.evaluate(() => document.fonts.ready);
        await sleep(500);
        const m = await page.evaluate(read, size.height);
        await page.screenshot({
          path: join(out, `current-${target.id}-${size.width}.png`),
          fullPage: true,
          clip: { x: 0, y: 0, width: size.width, height: Math.min(m.documentHeight, MAX_HEIGHT) },
        });
        measurements.shots[`${target.id}-${size.width}`] = { path: target.path, ...m };
        console.log(`${target.id} ${size.width} (${m.documentHeight}px)`);
      }
    }
    await context.close();
    writeFileSync(
      join(out, only.length ? 'current-measurements.partial.json' : 'current-measurements.json'),
      `${JSON.stringify(measurements, null, 2)}\n`,
    );
  } finally {
    await browser.close();
    await controller.stop();
  }
}

if (process.argv[1] && import.meta.url === new URL(`file://${process.argv[1]}`).href) {
  main(process.argv.slice(2)).catch((error) => {
    console.error(error.message);
    process.exitCode = 2;
  });
}

// Photograph the concepts, from the review page, as the pack's evidence.
//
// Every picture is a whole page: the window is made as tall as the page before
// the stage is photographed, so nothing is cut at a fold and a bar that sticks to
// the bottom of a phone rests where it would if the page were fully scrolled.
// Where a fold matters, the README says it with a measured number, because a
// picture cannot show where a screen ended.
//
//   node design/webui-refresh-review/tools/capture.mjs [--pack signed-in] [--only screen]
import { mkdir } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { formatHash } from '../public/review-state.js';
import { launch } from './lib/browser.mjs';
import { serve } from './serve.mjs';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const WIDTHS = [1440, 375];

/** The state each screen is photographed in: the one that shows the design best. */
export const CAPTURE_STATE = {
  signin: 'password',
  'first-account': 'empty',
  'connect-app': 'normal',
  // The case the page must handle, with twelve reasons, and not the easy one.
  'fleet-status': 'blocked',
  'not-found': 'not-found',
};

/** The concept the README recommends for each screen, which is also shown in the other style and mode. */
export const RECOMMENDED = {
  signin: 'b',
  'first-account': 'b',
  'connect-app': 'b',
  'fleet-status': 'a',
  'not-found': 'b',
};

/** The state each signed-in page is photographed in: the one that has something to say. */
export const SIGNED_IN_STATE = {
  overview: 'attention',
  pools: 'rows',
  'pool-detail': 'working',
  runners: 'rows',
  'runner-detail': 'busy',
  queue: 'rows',
  workflows: 'rows',
  jobs: 'rows',
  hosts: 'rows',
  'host-detail': 'down',
  providers: 'rows',
  usage: 'normal',
  comparisons: 'normal',
  kennel: 'normal',
  repairs: 'normal',
  'ai-context': 'normal',
  installations: 'rows',
  migrate: 'normal',
  audit: 'rows',
  settings: 'unsaved',
  'pool-new': 'invalid',
  'host-new': 'step-2',
  'provider-new': 'step-1',
};

/** Three pictures of each signed-in page: Mission Control dark at 1440 and on a phone, and Classic light at 1440. */
export function signedInPlan(screens) {
  const shots = [];
  for (const screen of screens) {
    const state = SIGNED_IN_STATE[screen];
    if (!state) throw new Error(`no capture state for "${screen}"; add it to SIGNED_IN_STATE`);
    for (const [width, style, mode, look] of [
      [1440, 'mission-control', 'dark', ''],
      [375, 'mission-control', 'dark', ''],
      [1440, 'classic', 'light', '-classic-light'],
    ]) {
      shots.push({
        screen,
        concept: 'a',
        width,
        style,
        mode,
        hash: formatHash({ screen, concept: 'a', style, mode, state }),
        file: `concept-${screen}${look}-${width}.png`,
      });
    }
  }
  return shots;
}

function shot(screen, concept, width, style, mode) {
  const look = style === 'classic' && mode === 'light' ? '-classic-light' : '';
  return {
    screen,
    concept,
    width,
    style,
    mode,
    hash: formatHash({ screen, concept, style, mode, state: CAPTURE_STATE[screen] }),
    file: `concept-${screen}-${concept}${look}-${width}.png`,
  };
}

/** Every picture to take: three concepts at two widths in Mission Control dark, and the recommended one in Classic light. */
export function plan(screens) {
  const shots = [];
  for (const screen of screens) {
    for (const concept of ['a', 'b', 'c']) {
      for (const width of WIDTHS) shots.push(shot(screen, concept, width, 'mission-control', 'dark'));
    }
    shots.push(shot(screen, RECOMMENDED[screen], 1440, 'classic', 'light'));
  }
  return shots;
}

async function main(argv) {
  const signedIn = argv.includes('--pack') && argv[argv.indexOf('--pack') + 1] === 'signed-in';
  const only = argv.includes('--only') ? argv[argv.indexOf('--only') + 1] : undefined;
  const page_ = signedIn ? '/signed-in/mockups.html' : '/review/mockups.html';
  const out = join(root, signedIn ? 'signed-in' : 'public');
  const server = await serve(0);
  const browser = await launch();
  try {
    const survey = await browser.newPage();
    await survey.goto(`${server.url}${page_}`);
    await survey.waitForFunction(() => 'rendered' in document.documentElement.dataset);
    const screens = await survey.$$eval('#screen option', (options) => options.map((o) => o.value));
    await survey.close();
    if (only && !screens.includes(only)) throw new Error(`unknown screen "${only}"; the page offers: ${screens.join(', ')}`);

    await mkdir(out, { recursive: true });
    const chosen = only ? [only] : screens;
    for (const s of signedIn ? signedInPlan(chosen) : plan(chosen)) {
      const context = await browser.newContext({
        viewport: { width: s.width, height: 900 },
        colorScheme: s.mode,
      });
      const page = await context.newPage();
      await page.goto(`${server.url}${page_}${s.hash}`);
      await page.waitForFunction((h) => document.documentElement.dataset.rendered === h, s.hash);
      await page.evaluate(() => document.fonts.ready);
      // As tall as the page, so nothing is cut and nothing sticks across the content.
      const whole = await page.evaluate(() => document.documentElement.scrollHeight);
      await page.setViewportSize({ width: s.width, height: whole });
      await page.evaluate(() => new Promise((done) => requestAnimationFrame(() => requestAnimationFrame(done))));
      await page.locator('#stage').screenshot({ path: join(out, s.file) });
      await context.close();
      console.log(s.file);
    }
  } finally {
    await browser.close();
    await server.close();
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main(process.argv.slice(2)).catch((error) => {
    console.error(error.message);
    process.exitCode = 2;
  });
}

// The set of pictures is a decision, so it is tested before anything is
// photographed: which files exist, what they are called, and that the one the
// README recommends for each screen is shown in the other style and mode too.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { CAPTURE_STATE, RECOMMENDED, SIGNED_IN_STATE, plan, signedInPlan } from './capture.mjs';

const SCREENS = ['signin', 'first-account', 'connect-app', 'fleet-status', 'not-found'];

test('every screen has a capture state and a recommendation', () => {
  for (const screen of SCREENS) {
    assert.ok(CAPTURE_STATE[screen], `${screen} has no capture state`);
    assert.ok(['a', 'b', 'c'].includes(RECOMMENDED[screen]), `${screen} has no recommendation`);
  }
});

test('the plan is three concepts at two widths per screen, plus the recommended one in Classic light', () => {
  const shots = plan(SCREENS);
  assert.equal(shots.length, SCREENS.length * 3 * 2 + SCREENS.length);
  assert.equal(new Set(shots.map((s) => s.file)).size, shots.length, 'every file name is unique');
});

test('files are named concept, screen, concept letter, and the look when it is not the usual one', () => {
  const names = plan(SCREENS).map((s) => s.file);
  assert.ok(names.includes('concept-signin-a-1440.png'));
  assert.ok(names.includes('concept-fleet-status-c-375.png'));
  assert.ok(names.includes('concept-signin-b-classic-light-1440.png'));
  assert.ok(names.every((n) => /^concept-[a-z-]+-[abc](-classic-light)?-(1440|375)\.png$/.test(n)), names.join(', '));
});

test('the usual look is Mission Control dark, and only the recommended concept is shown in Classic light', () => {
  const shots = plan(SCREENS);
  for (const shot of shots.filter((s) => !s.file.includes('classic-light'))) {
    assert.match(shot.hash, /style=mission-control&mode=dark/);
  }
  const light = shots.filter((s) => s.file.includes('classic-light'));
  assert.equal(light.length, SCREENS.length);
  for (const shot of light) {
    assert.match(shot.hash, /style=classic&mode=light/);
    assert.equal(shot.width, 1440);
    assert.equal(shot.concept, RECOMMENDED[shot.screen]);
  }
});

test('each picture is of the state that shows the design best, in the hash the page reads', () => {
  for (const shot of plan(SCREENS)) {
    assert.match(shot.hash, new RegExp(`screen=${shot.screen}&concept=${shot.concept}`));
    assert.match(shot.hash, new RegExp(`state=${CAPTURE_STATE[shot.screen]}$`));
  }
});

/* the second pack: one concept, so a screen is three pictures and not ten */

const SIGNED_IN = Object.keys(SIGNED_IN_STATE);

