    assert.equal(await page.locator('h1').textContent(), 'review');
  } finally {
    await browser.close();
  }
});

// Generate public/icons.js: the Lucide glyphs the concepts draw, as data.
//
// The mockups are plain HTML and cannot import a Svelte component, but a
// concept that drew its own approximation of an icon would be judged on a shape
// the product does not have. So each glyph is read from the installed
// @lucide/svelte package (ISC), and the GitHub mark from the product's own
// GithubMark.svelte, and written out once. To use another icon, add its name
// below and run this again.
//
//   node design/webui-refresh-review/tools/make-icons.mjs
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const web = resolve(fileURLToPath(new URL('.', import.meta.url)), '../../../web');
const lucide = resolve(web, 'node_modules/@lucide/svelte');

const WANTED = [
  'activity', 'arrow-left', 'arrow-right', 'arrow-up-right', 'ban', 'bell', 'boxes', 'cable',
  'chart-no-axes-combined', 'check', 'chevron-down', 'chevron-left', 'chevron-right',
  'circle-alert', 'circle-check', 'circle-question-mark', 'clock', 'cloud', 'compass', 'copy', 'cpu',
  'database', 'download', 'ellipsis', 'external-link', 'eye', 'eye-off', 'file-text', 'funnel',
  'flag', 'gauge', 'git-branch', 'git-pull-request-arrow', 'globe', 'hard-drive', 'clock-fading',
  'house', 'info', 'key-round', 'laptop', 'layers', 'layout-dashboard', 'link', 'list-ordered',
  'lock', 'log-out', 'memory-stick', 'menu', 'moon', 'pause', 'pencil', 'play', 'plug', 'plus',
  'refresh-cw', 'rocket', 'scan-line', 'scroll-text', 'search', 'server', 'settings',
  'shield-check', 'sparkles', 'sun', 'tag', 'terminal', 'trash', 'triangle-alert', 'trophy',
  'user', 'user-round', 'users', 'workflow', 'wrench', 'x', 'zap',
];

function nodesOf(name) {
  const source = readFileSync(resolve(lucide, 'dist/icons', `${name}.svelte`), 'utf8');
  const match = /const iconData = (\{.*\});/.exec(source);
  if (!match) throw new Error(`cannot find the icon data in ${name}.svelte`);
  return JSON.parse(match[1]).node;
}

const githubPath = /<path\s+d="([^"]+)"/.exec(
  readFileSync(resolve(web, 'src/lib/icons/GithubMark.svelte'), 'utf8'),
)?.[1];
if (!githubPath) throw new Error('cannot find the GitHub mark path in GithubMark.svelte');

const version = JSON.parse(readFileSync(resolve(lucide, 'package.json'), 'utf8')).version;
const nodes = Object.fromEntries(WANTED.map((name) => [name, nodesOf(name)]));

const output = `// Generated by tools/make-icons.mjs from @lucide/svelte ${version} (ISC) and the
// product's GithubMark.svelte. Do not edit; add a name to the generator instead.

const NODES = ${JSON.stringify(nodes, null, 1)};

const GITHUB_PATH = ${JSON.stringify(githubPath)};

/** Every glyph this module can draw. */
export const NAMES = Object.keys(NODES);

const attributes = (map) =>
  Object.entries(map)
    .map(([key, value]) => \`\${key}="\${String(value).replaceAll('"', '&quot;')}"\`)
    .join(' ');

/** A Lucide glyph as a decorative inline SVG. A name that was not generated throws. */
export function icon(name, size = 16) {
  const nodes = NODES[name];
  if (!nodes) throw new Error(\`no icon called "\${name}"; add it to tools/make-icons.mjs\`);
  const inner = nodes.map(([tag, attrs]) => \`<\${tag} \${attributes(attrs)}/>\`).join('');
  return (
    \`<svg class="icon" xmlns="http://www.w3.org/2000/svg" width="\${size}" height="\${size}" \` +
    \`viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" \` +
    \`stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">\${inner}</svg>\`
  );
}

/** The GitHub mark: filled, as the product draws it, since Lucide has no brand icons. */
export function githubMark(size = 16) {
  return (
    \`<svg class="icon" xmlns="http://www.w3.org/2000/svg" width="\${size}" height="\${size}" \` +
    \`viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" focusable="false">\` +
    \`<path d="\${GITHUB_PATH}"/></svg>\`
  );
}
`;

writeFileSync(resolve(fileURLToPath(new URL('../public/icons.js', import.meta.url))), output);
console.log(`Wrote ${WANTED.length} Lucide icons and the GitHub mark to public/icons.js`);

// Measure the signed-in mocks, so the README's comparisons with today's pages are
// numbers a script recorded and not numbers anyone remembered.
//
// Each page is measured in the state its picture shows, at 1440 and on a phone,
// the way the capture script frames it: the stage alone, with the review bar
// out of the sum. What it records is what the README cites: how tall the page is
// (the same figure as its picture, which a test holds), how many columns its
// table has, and whether the table scrolls inside its card.
//
//   node design/webui-refresh-review/tools/measure-signed-in.mjs
import { writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { SIGNED_IN_STATE, signedInPlan } from './capture.mjs';
import { launch } from './lib/browser.mjs';
import { serve } from './serve.mjs';

const out = resolve(dirname(fileURLToPath(import.meta.url)), '../signed-in/concept-measurements.json');

/** What the README cites, read from the page as drawn. */
function read() {
  const stage = document.getElementById('stage');
  const table = stage.querySelector('table');
  const region = stage.querySelector('.k-scroll');
  return {
    height: Math.round(stage.getBoundingClientRect().height),
    columns: table ? table.querySelectorAll('thead th').length : 0,
    tables: stage.querySelectorAll('table').length,
    cards: stage.querySelectorAll('.k-card, .k-stat, .k-stage').length,
    scrollsInCard: region ? region.scrollWidth > region.clientWidth : false,
    scrollsSideways: document.documentElement.scrollWidth > innerWidth,
  };
}

export async function measure() {
  const server = await serve(0);
  const browser = await launch();
  const screens = {};
  try {
    const survey = await browser.newPage();
    await survey.goto(`${server.url}/signed-in/mockups.html`);
    await survey.waitForFunction(() => 'rendered' in document.documentElement.dataset);
    const titles = Object.fromEntries(await survey.$$eval('#screen option', (os) => os.map((o) => [o.value, o.textContent])));
    await survey.close();
    for (const shot of signedInPlan(Object.keys(SIGNED_IN_STATE))) {
      if (shot.file.includes('classic-light')) continue;
      const context = await browser.newContext({ viewport: { width: shot.width, height: 900 }, colorScheme: shot.mode });
      const page = await context.newPage();
      await page.goto(`${server.url}/signed-in/mockups.html${shot.hash}`);
      await page.waitForFunction((h) => document.documentElement.dataset.rendered === h, shot.hash);
      await page.evaluate(() => document.fonts.ready);
      screens[shot.screen] ??= { title: titles[shot.screen] };
      screens[shot.screen][String(shot.width)] = await page.evaluate(read);
      await context.close();
    }
  } finally {
    await browser.close();
    await server.close();
  }
  return { generated: new Date().toISOString(), look: 'mission-control dark', screens };
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  measure()
    .then((result) => writeFile(out, `${JSON.stringify(result, null, 2)}\n`))
    .then(() => console.log(`wrote ${join('signed-in', 'concept-measurements.json')}`))
    .catch((error) => {
      console.error(error.message);
      process.exitCode = 2;
    });
}

// Measure where the concepts put things, as a reader's screen would hold them.
//
// The README compares these numbers with today's pages, which were photographed
// with nothing above them. The review page has a bar of controls above the
// stage, 79px tall at 1440 and 263px at 375 where its five selects wrap, and a
// concept that centres its content is moved by half of it. So the bar is hidden
// before anything is read, and every number is a position from the top of the
// page as the product would draw it. Everything measured is written down, and a
// test holds each number in the README to this file.
//
//   node design/webui-refresh-review/tools/measure.mjs
import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { formatHash } from '../public/review-state.js';
import { launch } from './lib/browser.mjs';
import { serve } from './serve.mjs';

const out = resolve(dirname(fileURLToPath(import.meta.url)), '../public/concept-measurements.json');
const SCREENS = { 1440: 900, 375: 812 };

/**
 * What each README table is about. `first` is the field the page asks for first,
 * `action` the button that finishes it (by text, as a regular expression, or by
 * selector) and `last` the bottom-most of a group, such as the blocking causes.
 * The style is the one the table says it was measured in: the status page has
 * only Classic today, so it is compared in Classic.
 */
export const CASES = [
  { screen: 'signin', states: ['password'], style: 'mission-control', first: '#stage input', action: { text: '^sign in$' } },
  {
    screen: 'first-account',
    states: ['empty'],
    style: 'mission-control',
    first: '#f-setup-token',
    action: { selector: 'button[type="submit"]' },
  },
  { screen: 'connect-app', states: ['normal', 'loopback'], style: 'mission-control', action: { text: '^allow' } },
  { screen: 'fleet-status', states: ['blocked'], style: 'classic', last: '#stage .m-reason.sev-error' },
];

/** Every page to measure: each case, three concepts, both widths. */
export function plan(screens = CASES.map((c) => c.screen)) {
  const shots = [];
  for (const spec of CASES.filter((c) => screens.includes(c.screen))) {
    for (const concept of ['a', 'b', 'c']) {
      for (const state of spec.states) {
        for (const [width, height] of Object.entries(SCREENS)) {
          shots.push({
            screen: spec.screen,
            concept,
            state,
            width: Number(width),
            height,
            spec,
            hash: formatHash({ screen: spec.screen, concept, style: spec.style, mode: 'dark', state }),
          });
        }
      }
    }
  }
  return shots;
}

/**
 * Read the positions the spec names from a loaded page, in whole pixels from the
 * top of the page once the review bar is gone. `page` is the document's height,
 * and `fits` says whether it needs no scrolling. An action that sticks to the
 * bottom of the screen is flagged, because its edge is the screen's and not the
 * page's. A missing action is an error: a selector that quietly matches nothing
 * would write a table of nulls that looked like a finding.
 */
export async function measure(page, { first, action, last }) {
  await page.addStyleTag({ content: '.review-bar { display: none !important; }' });
  await page.evaluate(() => new Promise((done) => requestAnimationFrame(() => requestAnimationFrame(done))));
  return page.evaluate(
    ({ first, action, last }) => {
      const at = (el) => {
        const box = el.getBoundingClientRect();
        return { top: Math.round(box.top + scrollY), bottom: Math.round(box.bottom + scrollY) };
      };
      const pinned = (el) => {
        for (let n = el; n && n.id !== 'stage'; n = n.parentElement) {
          if (['sticky', 'fixed'].includes(getComputedStyle(n).position)) return true;
        }
        return false;
      };
      let found = null;
      if (action) {
        const candidates = action.selector
          ? [...document.querySelectorAll(action.selector)]
          : [...document.querySelectorAll('#stage button, #stage a')].filter((el) =>
              new RegExp(action.text, 'i').test(el.textContent.trim()),
            );
        if (!candidates.length) throw new Error(`no action matching ${action.selector ?? action.text}`);
        found = { bottom: at(candidates[0]).bottom, pinned: pinned(candidates[0]) };
      }
      const field = first ? document.querySelector(first) : null;
      const group = last ? [...document.querySelectorAll(last)].filter((el) => el.checkVisibility()).at(-1) : null;
      return {
        first: field ? at(field) : null,
        action: found,
        last: group ? { bottom: at(group).bottom } : null,
        page: Math.round(document.documentElement.scrollHeight),
        // A page cannot be shorter than the window, so a page that needs no
        // scrolling reads as exactly the window tall; this says so outright.
        fits: document.documentElement.scrollHeight <= innerHeight,
      };
    },
    { first, action, last },
  );
}

async function main() {
  const server = await serve(0);
  const browser = await launch();
  try {
    const screens = {};
    for (const shot of plan()) {
      const context = await browser.newContext({
        viewport: { width: shot.width, height: shot.height },
        colorScheme: 'dark',
      });
      const page = await context.newPage();
      await page.goto(`${server.url}/review/mockups.html${shot.hash}`);
      await page.waitForFunction(() => 'rendered' in document.documentElement.dataset);
      await page.evaluate(() => document.fonts.ready);
      const got = await measure(page, shot.spec);
      await context.close();
      const slot = ((screens[shot.screen] ??= {})[shot.concept] ??= {});
      (slot[shot.state] ??= {})[shot.width] = got;
      console.log(`${shot.screen} ${shot.concept} ${shot.state} ${shot.width}`);
    }
    await mkdir(dirname(out), { recursive: true });
    await writeFile(
      out,
      `${JSON.stringify({ generated: new Date().toISOString(), reviewBar: 'hidden', screens }, null, 2)}\n`,
    );
  } finally {
    await browser.close();
    await server.close();
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((error) => {
    console.error(error.message);
    process.exitCode = 2;
  });
}

// A position in the README is compared with a photograph of today's page, which
// has no review bar above it. A number taken beneath the bar was off by whatever
// the bar did to the layout: half its height for a concept that centres, and
// 263px of it on a phone, where the five controls wrap. So the measurement is
// held to one rule, tested before anything is measured: the bar is not there.
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { launch } from './lib/browser.mjs';
import { CASES, measure, plan } from './measure.mjs';

let browser;
before(async () => {
  browser = await launch();
});
after(async () => {
  await browser?.close();
});

async function open(html, width = 400, height = 600) {
  const page = await browser.newPage({ viewport: { width, height } });
  await page.setContent(html);
  return page;
}

const BAR = '<header class="review-bar" style="height:300px">controls</header>';
const SPEC = { first: 'input', action: { text: '^sign in$' } };
const pick = ({ page, fits }) => ({ page, fits });

test('the review bar does not move a number: it is hidden before the page is measured', async () => {
  const page = await open(`${BAR}<main id="stage"><input><button>Sign in</button></main>`);
  const withBar = await measure(page, SPEC);
  const bare = await open(`<main id="stage"><input><button>Sign in</button></main>`);
  assert.deepEqual(withBar, await measure(bare, SPEC));
  assert.ok(withBar.action.bottom < 100, `the button is ${withBar.action.bottom}px down, not ${withBar.action.bottom + 300}`);
  await page.close();
  await bare.close();
});

test('numbers are whole pixels, with the field as a top and a bottom and the page as its full height', async () => {
  const page = await open(`<main id="stage" style="height:1234.4px"><input style="height:32.4px"><button>Sign in</button></main>`);
  const got = await measure(page, SPEC);
  assert.ok(Number.isInteger(got.first.top) && Number.isInteger(got.first.bottom));
  assert.equal(got.first.bottom - got.first.top, 32);
  assert.ok(Number.isInteger(got.action.bottom));
  assert.ok(got.page >= 1234, `the page is ${got.page}px`);
  await page.close();
});

test('a page that fits the window reads as exactly the window tall, and says it fits', async () => {
  // A page cannot be shorter than the window, so "900px" for a 900px window
  // means "needs no scrolling" and not "is 900px of content".
  const short = await open(
    `<style>body{margin:0}main{min-height:100vh}</style><main id="stage"><p style="margin:0;height:300px">x</p></main>`,
    400,
    900,
  );
  assert.deepEqual(pick(await measure(short, {})), { page: 900, fits: true });
  const tall = await open(`<style>body{margin:0}</style><main id="stage" style="height:1500px"></main>`, 400, 900);
  assert.deepEqual(pick(await measure(tall, {})), { page: 1500, fits: false });
  await short.close();
  await tall.close();
});

test('a group folded away behind a disclosure is not measured, because it is not on the page', async () => {
  // Concept B keeps the blocking causes behind a disclosure. They still have
  // boxes when it is closed, and the README must say "behind a disclosure", not
  // quote the place a box would be if it were open.
  const folded = await open(
    `<main id="stage"><p class="cause">shown</p><details><summary>more</summary><p class="cause">folded</p></details></main>`,
  );
  const got = await measure(folded, { last: '.cause' });
  const open_ = await open(
    `<main id="stage"><p class="cause">shown</p><details open><summary>more</summary><p class="cause">folded</p></details></main>`,
  );
  assert.ok(got.last.bottom < (await measure(open_, { last: '.cause' })).last.bottom, 'the folded one is not the last');
  const hidden = await open(`<main id="stage"><details><summary>more</summary><p class="cause">folded</p></details></main>`);
  assert.equal((await measure(hidden, { last: '.cause' })).last, null);
  await folded.close();
  await open_.close();
  await hidden.close();
});

test('an action stuck to the bottom of the screen is recorded as pinned, and one that scrolls is not', async () => {
  const pinned = await open(
    `<main id="stage" style="height:2000px"><div style="position:sticky;bottom:0"><button>Allow</button></div></main>`,
  );
  assert.equal((await measure(pinned, { action: { text: '^allow' } })).action.pinned, true);
  const loose = await open(`<main id="stage" style="height:2000px"><button>Allow</button></main>`);
  assert.equal((await measure(loose, { action: { text: '^allow' } })).action.pinned, false);
  await pinned.close();
  await loose.close();
});

test('a screen that has no first field says so, and a missing action is an error that names it', async () => {
  const page = await open(`<main id="stage"><button>Allow</button></main>`);
  assert.equal((await measure(page, { action: { text: '^allow' } })).first, null);
  await assert.rejects(measure(page, { action: { text: '^nothing$' } }), /no action matching \^nothing\$/);
  await page.close();
});

test('the plan is every screen at both widths, in the state its table is about, for each concept', () => {
  const screens = [...new Set(CASES.map((c) => c.screen))].sort();
  assert.deepEqual(screens, ['connect-app', 'first-account', 'fleet-status', 'signin']);
  const shots = plan(screens);
  for (const screen of screens) {
    for (const concept of ['a', 'b', 'c']) {
      for (const width of [1440, 375]) {
        assert.ok(
          shots.some((s) => s.screen === screen && s.concept === concept && s.width === width),
          `${screen} ${concept} ${width} is not measured`,
        );
      }
    }
  }
  // The consent screen's warning is a second state, because it is the one that drops Allow below the fold.
  assert.deepEqual([...new Set(shots.filter((s) => s.screen === 'connect-app').map((s) => s.state))].sort(), ['loopback', 'normal']);
  assert.equal(new Set(shots.map((s) => `${s.screen}-${s.concept}-${s.state}-${s.width}`)).size, shots.length);
});

// The review server: a read-only file server on loopback.
//
// A review page has to link the repository's own tokens.css, and tokens.css
// names its backdrops as absolute URLs (`/brand/...`), so the page and the real
// files must share one origin. This mounts them where the app would find them
// and nothing else. The earlier theme review hard-coded its colours instead,
// which is exactly the drift linking the tokens removes.
//
//   node design/webui-refresh-review/tools/serve.mjs [port]
import { createServer } from 'node:http';
import { createReadStream } from 'node:fs';
import { stat } from 'node:fs/promises';
import { extname, resolve, sep } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const repository = fileURLToPath(new URL('../../../', import.meta.url));
const at = (path) => resolve(repository, path);

/**
 * Where each URL prefix is read from. The first prefix that matches wins, so
 * `/` has to come last or it would shadow the rest. `/fonts/` is flat across
 * both packages because fonts.css names a bare module path that only Vite can
 * resolve, and the file names do not collide.
 */
const MOUNTS = [
  { prefix: '/web/src/', roots: [at('web/src')] },
  {
    prefix: '/fonts/',
    roots: [
      at('web/node_modules/@fontsource-variable/inter/files'),
      at('web/node_modules/@fontsource/jetbrains-mono/files'),
    ],
  },
  { prefix: '/review/', roots: [at('design/webui-refresh-review/public')] },
  // The second pack, beside the first: it links pack 1's review page code by
  // its /review/ address and its own files by this one.
  { prefix: '/signed-in/', roots: [at('design/webui-refresh-review/signed-in')] },
  { prefix: '/', roots: [at('web/public')] },
];

const TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.txt': 'text/plain; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.webp': 'image/webp',
  '.woff2': 'font/woff2',
};

function reply(res, status, text) {
  res.writeHead(status, { 'Content-Type': 'text/plain; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(`${text}\n`);
}

/** Whether `file` is `root` itself or lies under it, after both are resolved. */
function within(root, file) {
  return file === root || file.startsWith(root + sep);
}

async function regularFile(path) {
  try {
    return (await stat(path)).isFile();
  } catch {
    return false;
  }
}

async function handle(req, res) {
  if (req.method !== 'GET' && req.method !== 'HEAD') {
    res.setHeader('Allow', 'GET, HEAD');
    return reply(res, 405, 'Method not allowed');
  }

  // The path as the client wrote it, so that `..` is still there to be refused.
  let pathname;
  try {
    pathname = decodeURIComponent((req.url ?? '/').split('?')[0].split('#')[0]);
  } catch {
    return reply(res, 400, 'Bad request');
  }
  if (pathname.includes('\0')) return reply(res, 400, 'Bad request');

  const mount = MOUNTS.find((m) => pathname.startsWith(m.prefix));
  const candidates = mount.roots.map((root) => ({
    root,
    file: resolve(root, pathname.slice(mount.prefix.length)),
  }));
  if (candidates.some(({ root, file }) => !within(root, file))) return reply(res, 403, 'Forbidden');

  for (const { file } of candidates) {
    if (!(await regularFile(file))) continue;
    res.writeHead(200, {
      'Content-Type': TYPES[extname(file).toLowerCase()] ?? 'application/octet-stream',
      // A review page is edited and reloaded constantly; a stale copy would
      // make a fixed defect look unfixed.
      'Cache-Control': 'no-store',
      'X-Content-Type-Options': 'nosniff',
    });
    if (req.method === 'HEAD') return res.end();
    const body = createReadStream(file);
    body.on('error', () => res.destroy());
    return body.pipe(res);
  }
  return reply(res, 404, 'Not found');
}

/**
 * Listen on loopback and resolve once the port is open. Pass 0 for a free one;
 * `url` always names the port actually bound.
 */
export function serve(port = 8101) {
  const server = createServer((req, res) => {
    handle(req, res).catch(() => (res.headersSent ? res.destroy() : reply(res, 500, 'Server error')));
  });
  return new Promise((ready, failed) => {
    server.once('error', failed);
    server.listen(port, '127.0.0.1', () => {
      ready({
        url: `http://127.0.0.1:${server.address().port}`,
        close: () =>
          new Promise((closed) => {
            server.close(() => closed());
            server.closeAllConnections();
          }),
      });
    });
  });
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const { url } = await serve(Number(process.argv[2] ?? 8101));
  console.log(`Review pack: ${url}/review/mockups.html`);
}

// The review server mounts the real tokens and brand files, so a review page
// can link them directly. What matters most here is what it refuses: it is a
// file server on loopback, and a path that climbs out of its mounts would hand
// out the rest of the repository.
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { request } from 'node:http';
import { mkdir, rm, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { serve } from './serve.mjs';

const publicDir = fileURLToPath(new URL('../public/', import.meta.url));
const signedInDir = fileURLToPath(new URL('../signed-in/', import.meta.url));
const probe = `${publicDir}_serve-test.txt`;
const signedInProbe = `${signedInDir}_serve-test.txt`;
let server;

before(async () => {
  await mkdir(publicDir, { recursive: true });
  await mkdir(signedInDir, { recursive: true });
  await writeFile(probe, 'probe');
  await writeFile(signedInProbe, 'signed-in probe');
  server = await serve(0);
});

after(async () => {
  await server?.close();
  await rm(probe, { force: true });
  await rm(signedInProbe, { force: true });
});

/**
 * A request whose path reaches the server exactly as written. fetch() collapses
 * `..` and `%2e%2e` segments before sending, so it could never exercise the
 * check that matters.
 */
function raw(path, method = 'GET') {
  const { port } = new URL(server.url);
  return new Promise((resolve, reject) => {
    const req = request({ host: '127.0.0.1', port, path, method }, (res) => {
      let body = '';
      res.setEncoding('utf8');
      res.on('data', (chunk) => (body += chunk));
      res.on('end', () => resolve({ status: res.statusCode, type: res.headers['content-type'], body }));
    });
    req.on('error', reject);
    req.end();
  });
}

