// The agent's token rides on every request, and a create task carries a JIT
// runner configuration -- a live registration credential for the organisation's
// runner group. Neither may cross the network in the clear by accident, so a
// plaintext controller URL is refused rather than warned about.
func TestHTTPTransportRefusesPlaintextToARemoteController(t *testing.T) {
	cases := []struct {
		url     string
		allow   bool
		wantErr bool
	}{
		{url: "https://zoomies.example.com:8080"},
		{url: "http://127.0.0.1:8080"},
		{url: "http://[::1]:8080"},
		{url: "http://localhost:8080"},
		{url: "http://zoomies.example.com:8080", wantErr: true},
		{url: "http://10.0.0.5:8080", wantErr: true},
		// An operator who has decided the hop is already private can say so.
		{url: "http://zoomies.example.com:8080", allow: true},
	}
	for _, tc := range cases {
		name := tc.url
		if tc.allow {
			name += " (opted in)"
		}
		t.Run(name, func(t *testing.T) {
			_, err := NewHTTPTransport(HTTPOptions{ControllerURL: tc.url, AllowInsecureHTTP: tc.allow})
			if (err != nil) != tc.wantErr {
				t.Fatalf("NewHTTPTransport(%q) = %v; want error=%v", tc.url, err, tc.wantErr)
			}
			if tc.wantErr && !strings.Contains(err.Error(), "allow_insecure_http") {
				t.Errorf("the refusal should name the way out: %v", err)
			}
		})
	}
}

// The session is what makes a duplicated credential visible, and it is only
// any use if the agent sends it on every authenticated call: a duplicate that
// only ever polled for tasks would go unseen if the header rode on heartbeats
// alone. It must also be stable for the life of the process -- an id that
// changed under a running agent would look exactly like the duplicate it
// exists to find -- and absent from join, which is what mints the credentials
// the session belongs to.
func TestTheAgentSendsOneStableSessionOnEveryAuthenticatedCall(t *testing.T) {
	var mu sync.Mutex
	seen := map[string]http.Header{}
	mux := http.NewServeMux()
	record := func(path string, body any) {
		mux.HandleFunc(path, func(w http.ResponseWriter, r *http.Request) {
			mu.Lock()
			seen[path] = r.Header.Clone()
			mu.Unlock()
			_ = json.NewEncoder(w).Encode(body)
		})
	}
	record(PathJoin, JoinResponse{HostID: "host-1", AgentToken: "agent-token"})
	record(PathHeartbeat, HeartbeatResponse{OK: true})
	record(PathResults, struct{}{})
	record(PathReport, struct{}{})

	tr, _ := newTestTransport(t, mux)
	ctx := context.Background()
	if _, err := tr.Join(ctx, JoinRequest{Name: "h"}); err != nil {
		t.Fatalf("Join: %v", err)
	}
	if _, err := tr.Heartbeat(ctx, HeartbeatRequest{Capacity: 2}); err != nil {
		t.Fatalf("Heartbeat: %v", err)
	}
	if err := tr.ReportResult(ctx, TaskResult{TaskID: "t1", OK: true}); err != nil {
		t.Fatalf("ReportResult: %v", err)
	}
	if err := tr.ReportRunners(ctx, []RunnerReport{{RunnerID: "run_1"}}); err != nil {
		t.Fatalf("ReportRunners: %v", err)
	}

	mu.Lock()
	defer mu.Unlock()
	if got := seen[PathJoin].Get(HeaderAgentSession); got != "" {
		t.Fatalf("join sent %s = %q; join is what mints the credentials the session belongs to", HeaderAgentSession, got)
	}
	first := seen[PathHeartbeat].Get(HeaderAgentSession)
	if first == "" {
		t.Fatalf("the heartbeat sent no %s", HeaderAgentSession)
	}
	for _, path := range []string{PathResults, PathReport} {
		if got := seen[path].Get(HeaderAgentSession); got != first {
			t.Fatalf("%s %s = %q, want the same session as the heartbeat (%q)", path, HeaderAgentSession, got, first)
		}
	}
}

// A refused join token is what an operator meets most often, and it is a 422
// rather than a 401: the join route is anonymous, so there is no credential to
// be unauthorised -- what was rejected is the token in the body.
//
// The installer's remedy for it ("expired, or already used; mint another")
// keys on ErrUnauthorized, so until the transport mapped this status the
// sentence never fired for the case it was written for and the operator was
// shown "returned HTTP 422" instead.
func TestARefusedJoinTokenIsUnauthorisedToTheCaller(t *testing.T) {
	tr, _ := newTestTransport(t, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusUnprocessableEntity)
		_, _ = io.WriteString(w, `{"error":{"code":"unprocessable","message":"this join token has expired; create a new one"}}`)
	}))

	_, err := tr.Join(context.Background(), JoinRequest{Name: "vm-1", Capacity: 2})
	if err == nil {
		t.Fatal("a refused join token was accepted")
	}
	if !errors.Is(err, ErrUnauthorized) {
		t.Fatalf("join error = %v; the installer keys its \"expired, or already used\" remedy on ErrUnauthorized and would not have printed it", err)
	}
	// The controller's own sentence survives the wrapping, because it is the
	// half that says which of the two happened.
	if !strings.Contains(err.Error(), "expired") {
		t.Errorf("the error drops what the controller said: %v", err)
	}
}

// And 422 anywhere else is a malformed request, not a credential problem:
// calling it one would send the next person to re-mint a token that was never
// the trouble.
func TestAnUnprocessableHeartbeatIsNotACredentialProblem(t *testing.T) {
	tr, _ := newTestTransport(t, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusUnprocessableEntity)
	}))

	_, err := tr.Heartbeat(context.Background(), HeartbeatRequest{})
	if err == nil {
		t.Fatal("a rejected heartbeat body was accepted")
	}
	if errors.Is(err, ErrUnauthorized) {
		t.Fatalf("heartbeat error = %v, reported as a credential problem: the agent would re-join over a malformed request", err)
	}
}

package agent

import (
	"fmt"
	"sync"
)

// relayBuffer is the hand-off between the goroutine reading a runner's output
// and the one writing it to the controller.
//
// It is bounded in bytes, not in reads, because how many reads a backlog takes
// is the source's choice. Docker frames its log stream a record to a frame, so a
// thousand-line backlog is a thousand reads of about a hundred bytes each, and a
// queue of sixty-four reads held sixty-four lines of it however much room there
// was. Output is coalesced into chunks of up to relayChunkSize as it goes in, so
// the writer takes a few large writes where the source made a thousand small
// ones, and catches up with a burst instead of falling further behind it.
//
// The bound is on the bytes queued, which is what a refusal and its notice
// count. The arrays the chunks grow into are larger than what they hold, by up
// to half again, so a stream whose writer has stalled holds about 3 MiB of
// memory for its 2 MiB of output.
type relayBuffer struct {
	// wake carries a token whenever there is something for next to find, so a
	// writer that has just looked and found nothing cannot sleep through an add.
	wake chan struct{}

	mu      sync.Mutex
	chunks  [][]byte // oldest first; the newest is still being filled
	queued  int      // bytes held in chunks
	dropped int64    // bytes refused since the viewer was last told
	closed  bool
}

func newRelayBuffer() *relayBuffer {
	return &relayBuffer{wake: make(chan struct{}, 1)}
}

// add takes a copy of p, or refuses it when the buffer is full. It never waits:
// a container whose stdout nobody drains eventually stops making progress, so a
// slow viewer must not be able to stall a build.
//
// A read that does not fit is refused whole, because half a line is worse than
// a gap. The viewer is told what it missed at the point it missed it: the notice
// goes in ahead of the next output that is accepted.
func (b *relayBuffer) add(p []byte) {
	b.mu.Lock()
	if b.queued+len(p) > relayBufferBytes {
		b.dropped += int64(len(p))
		b.mu.Unlock()
		return
	}
	b.reportDropped()
	b.put(p)
	b.mu.Unlock()
	b.signal()
}

// close ends the buffer. What was refused since the viewer was last told is
// reported however full the buffer is: the runner has stopped producing, so
// making room throttles nothing, and a viewer must always be told what was
// lost, even when it was lost in the last moments of the stream.
func (b *relayBuffer) close() {
	b.mu.Lock()
	b.reportDropped()
	b.closed = true
	b.mu.Unlock()
	b.signal()
}

// next returns the oldest chunk, waiting for one to arrive, and reports false
// once the buffer is closed and everything in it has been taken.
func (b *relayBuffer) next() ([]byte, bool) {
	for {
		b.mu.Lock()
		if len(b.chunks) > 0 {
			chunk := b.chunks[0]
			b.chunks[0] = nil
			b.chunks = b.chunks[1:]
			b.queued -= len(chunk)
			b.mu.Unlock()
			return chunk, true
		}
		closed := b.closed
		b.mu.Unlock()
		if closed {
			return nil, false
		}
		<-b.wake
	}
}

// reportDropped queues the notice for whatever was refused since the last one.
// The caller holds the lock.
func (b *relayBuffer) reportDropped() {
	if b.dropped == 0 {
		return
	}
	b.put([]byte(fmt.Sprintf("\n[log stream fell behind, %d bytes dropped]\n", b.dropped)))
	b.dropped = 0
}

// put copies p onto the chunk being filled, or starts the next one. The caller
// holds the lock. A chunk that next has handed out is no longer in the list, so
// nothing here can touch bytes the writer is still sending.
func (b *relayBuffer) put(p []byte) {
	if n := len(b.chunks); n > 0 && len(b.chunks[n-1])+len(p) <= relayChunkSize {
		b.chunks[n-1] = append(b.chunks[n-1], p...)
	} else {
		b.chunks = append(b.chunks, append([]byte(nil), p...))
	}
	b.queued += len(p)
}

func (b *relayBuffer) signal() {
	select {
	case b.wake <- struct{}{}:
	default:
	}
}

package agent

import (
	"bytes"
	"fmt"
	"regexp"
	"strconv"
	"strings"
	"sync"
	"testing"
	"time"
)

// drain takes everything a closed buffer still holds.
func drain(t *testing.T, b *relayBuffer) [][]byte {
	t.Helper()
	var chunks [][]byte
	for {
		chunk, ok := b.next()
		if !ok {
			return chunks
		}
		chunks = append(chunks, chunk)
	}
}

var fellBehind = regexp.MustCompile(`\n\[log stream fell behind, (\d+) bytes dropped\]\n`)

// accounted splits relayed output into what the runner said and what the relay
// said it had dropped, so a test can ask whether the two add up.
func accounted(output string) (payload string, dropped int) {
	for _, m := range fellBehind.FindAllStringSubmatch(output, -1) {
		n, _ := strconv.Atoi(m[1])
		dropped += n
	}
	return fellBehind.ReplaceAllString(output, ""), dropped
}

// A hundred bytes a read is a thousand writes to the controller if each read is
// passed on as it came, and the writer then runs slower than the source for the
// whole of a backlog. Coalescing is what lets it catch up.
func TestRelayBufferCoalescesShortReadsIntoFewWrites(t *testing.T) {
	b := newRelayBuffer()
	var want strings.Builder
	for i := range 1000 {
		line := fmt.Sprintf("line %04d %s\n", i, strings.Repeat("x", 90))
		want.WriteString(line)
		b.add([]byte(line))
	}
	b.close()

	chunks := drain(t, b)
	var got bytes.Buffer
	for _, c := range chunks {
		if len(c) > relayChunkSize {
			t.Fatalf("a chunk of %d bytes, want at most %d", len(c), relayChunkSize)
		}
		got.Write(c)
	}
	if got.String() != want.String() {
		t.Fatal("the buffer changed the output it was given")
	}
	if limit := want.Len()/relayChunkSize + 2; len(chunks) > limit {
		t.Fatalf("%d chunks for %d bytes, want at most %d", len(chunks), want.Len(), limit)
	}
}

// The reader hands over the same slice on every read, so what the buffer keeps
// has to be its own.
func TestRelayBufferCopiesWhatItIsGiven(t *testing.T) {
	b := newRelayBuffer()
	p := []byte("hello\n")
	b.add(p)
	copy(p, "XXXXXX")

	chunk, ok := b.next()
	if !ok || string(chunk) != "hello\n" {
		t.Fatalf("got %q, want the output as it was when it was added", chunk)
	}
}

// The writer is still sending a chunk while the reader goes on adding, so a
// chunk that has been handed out must never be written to again.
func TestRelayBufferNeverChangesAChunkTheWriterIsHolding(t *testing.T) {
	b := newRelayBuffer()
	b.add([]byte("first\n"))
	held, _ := b.next()
	b.add([]byte("second\n"))

	if string(held) != "first\n" {
		t.Fatalf("the chunk being written became %q", held)
	}
	if next, _ := b.next(); string(next) != "second\n" {
		t.Fatalf("the next chunk was %q", next)
	}
}

// A read that does not fit is refused whole rather than cut, and the viewer is
// told how much it missed at the point it missed it: ahead of the next output
// that is accepted, not at the end of a log it may never reach.
func TestRelayBufferRefusesWholeReadsWhenFullAndSaysWhatItMissed(t *testing.T) {
	b := newRelayBuffer()
	read := bytes.Repeat([]byte("a"), relayChunkSize)
	reads := relayBufferBytes / relayChunkSize
	for range reads {
		b.add(read)
	}
	b.add([]byte("lost one\n"))
	b.add([]byte("lost two\n"))
	for range reads {
		if _, ok := b.next(); !ok {
			t.Fatal("the buffer ended before it was drained")
		}
	}

	b.add([]byte("after the gap\n"))
	b.close()
	chunks := drain(t, b)
	if len(chunks) != 1 {
		t.Fatalf("%d chunks after the gap, want the notice and the output that followed it together", len(chunks))
	}
	if want := "\n[log stream fell behind, 18 bytes dropped]\nafter the gap\n"; string(chunks[0]) != want {
		t.Fatalf("got %q, want %q", chunks[0], want)
	}
}

// The runner has stopped producing, so making room for the notice throttles
// nothing, and a viewer is always told what was lost even when it was lost in
// the last moments of the stream.
func TestRelayBufferReportsWhatItDroppedWhenTheStreamEndsFull(t *testing.T) {
	b := newRelayBuffer()
	read := bytes.Repeat([]byte("a"), relayChunkSize)
	for range relayBufferBytes / relayChunkSize {
		b.add(read)
	}
	b.add([]byte("lost\n"))
	b.close()

	var all bytes.Buffer
	for _, c := range drain(t, b) {
		all.Write(c)
	}
	payload, dropped := accounted(all.String())
	if dropped != 5 {
		t.Fatalf("told %d bytes were dropped, want 5", dropped)
	}
	if len(payload) != relayBufferBytes {
		t.Fatalf("kept %d bytes of payload, want %d", len(payload), relayBufferBytes)
	}
	if !strings.HasSuffix(all.String(), "5 bytes dropped]\n") {
		t.Fatal("the notice was not the last thing the viewer was told")
	}
}

func TestRelayBufferWaitsForOutputAndEndsWhenClosed(t *testing.T) {
	b := newRelayBuffer()
	got := make(chan string)
	go func() {
		defer close(got)
		for {
			chunk, ok := b.next()
			if !ok {
				return
			}
			got <- string(chunk)
		}
	}()

	select {
	case chunk := <-got:
		t.Fatalf("next returned %q with nothing in the buffer", chunk)
	case <-time.After(50 * time.Millisecond):
	}

	b.add([]byte("first\n"))
	select {
	case chunk := <-got:
		if chunk != "first\n" {
			t.Fatalf("got %q", chunk)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("next slept through an add")
	}

	b.close()
	select {
	case _, open := <-got:
		if open {
			t.Fatal("next returned output after the buffer was closed and empty")
		}
	case <-time.After(5 * time.Second):
		t.Fatal("next did not end when the buffer was closed")
	}
}

// A container whose stdout nobody drains eventually stops making progress, so
// the reader must get to the end of a runner's output even when the controller
// has taken none of it. The writer here takes nothing until the reader is done:
// a buffer that waited for room would never let it finish.
func TestRelayBufferNeverMakesTheReaderWaitForAStalledWriter(t *testing.T) {
	b := newRelayBuffer()
	produced := make(chan struct{})
	go func() {
		defer close(produced)
		for range 4 * relayBufferBytes / relayChunkSize {
			b.add(bytes.Repeat([]byte("a"), relayChunkSize))
		}
		b.close()
	}()
	select {
	case <-produced:
	case <-time.After(10 * time.Second):
		t.Fatal("the reader was made to wait for a writer that was not taking anything")
	}

	var all bytes.Buffer
	for _, c := range drain(t, b) {
		all.Write(c)
	}
	payload, dropped := accounted(all.String())
	if len(payload) != relayBufferBytes || dropped != 3*relayBufferBytes {
		t.Fatalf("kept %d bytes and counted %d dropped, want %d kept and %d dropped",
			len(payload), dropped, relayBufferBytes, 3*relayBufferBytes)
	}
}

// Whatever the writer's pace, every byte the runner said is either delivered or
// counted in a notice. Nothing is lost without the viewer being told.
func TestRelayBufferAccountsForEveryByteAgainstASlowWriter(t *testing.T) {
	b := newRelayBuffer()
	const reads, size = 3000, 4 << 10

	var delivered strings.Builder
	var writer sync.WaitGroup
	writer.Add(1)
	go func() {
		defer writer.Done()
		for {
			chunk, ok := b.next()
			if !ok {
				return
			}
			delivered.Write(chunk)
			time.Sleep(time.Millisecond)
		}
	}()

	for i := range reads {
		b.add(bytes.Repeat([]byte{byte('a' + i%26)}, size))
	}
	b.close()
	writer.Wait()

	payload, dropped := accounted(delivered.String())
	if got, want := len(payload)+dropped, reads*size; got != want {
		t.Fatalf("%d bytes delivered or counted as dropped, but the runner said %d", got, want)
	}
}

// An add that lands between next finding the buffer empty and next waiting must
// still wake it. The wake channel holds one token for exactly that gap
// (newRelayBuffer); made unbuffered, or signalled only to a reader that is
// already parked, the writer sleeps with a chunk queued until the next add or
// the close, and a quiet runner's last lines are held back. Every other test
// here passes with an unbuffered channel, so this one stands alone for the
// property.
func TestRelayBufferNextNeverSleepsThroughAnAdd(t *testing.T) {
	b := newRelayBuffer()
	// The mechanism, asserted directly because the gap it closes is a few
	// nanoseconds wide and the loop below finds a lost token most of the time,
	// not every time.
	if cap(b.wake) < 1 {
		t.Fatal("the wake channel holds no token, so an add that lands before the writer waits wakes nobody")
	}
	got := make(chan struct{}, 1)
	done := make(chan struct{})
	go func() {
		defer close(done)
		for {
			if _, ok := b.next(); !ok {
				return
			}
			got <- struct{}{}
		}
	}()
	// Released on failure too, so a lost wake-up leaves no goroutine behind.
	defer func() {
		b.close()
		<-done
	}()

	for i := 0; i < 50000; i++ {
		b.add([]byte("x"))
		select {
		case <-got:
		case <-time.After(3 * time.Second):
			t.Fatalf("add %d was slept through: the writer was not woken for a chunk that was queued", i)
		}
	}
}

package agent

import (
	"context"
	"fmt"
	"io"
	"log/slog"
	"sync"
	"time"

	"github.com/eyupio/zoomies/internal/backend"
)

const (
	// relayChunkSize is how much output one read moves, and the most that one
	// write to the controller carries.
	relayChunkSize = 32 << 10
	// relayBufferBytes is how far the relay may run ahead of the controller
	// before anything is dropped. It is counted in bytes because the size of a
	// read is the source's choice; see relayBuffer.
	relayBufferBytes = 2 << 20
	// relayStopWait bounds how long stopping a stream waits for its copy to
	// wind down before the agent gets on with shutting down.
	relayStopWait = 10 * time.Second
)

// logRelay owns the log streams this agent has open. There is one per viewer
// watching a runner in the browser: the controller cannot dial in, so the agent
// pushes the output out.
type logRelay struct {
	tr  Transport
	log *slog.Logger

	mu      sync.Mutex
	streams map[string]*logStream
}

// logStream is one running relay.
type logStream struct {
	cancel context.CancelFunc
	done   chan struct{}
	once   sync.Once
}

func (s *logStream) finish() { s.once.Do(func() { close(s.done) }) }

func newLogRelay(tr Transport, log *slog.Logger) *logRelay {
	return &logRelay{tr: tr, log: log.With("component", "agent.logs"), streams: make(map[string]*logStream)}
}

// start opens a runner's output and copies it to the controller until the
// runner stops producing, the controller closes its side, or cancel is called.
//
// Starting a stream that is already running is a no-op: the controller
// redelivers tasks, and a second copy of one stream would interleave output.
func (r *logRelay) start(ctx context.Context, streamID string, h backend.Handle, b backend.Backend, opts backend.LogOptions) error {
	r.mu.Lock()
	if _, ok := r.streams[streamID]; ok {
		r.mu.Unlock()
		return nil
	}
	sctx, cancel := context.WithCancel(ctx)
	s := &logStream{cancel: cancel, done: make(chan struct{})}
	r.streams[streamID] = s
	r.mu.Unlock()

	src, err := b.Logs(sctx, h, opts)
	if err != nil {
		r.close(streamID, s)
		return fmt.Errorf("agent: opening logs for %s from the %s backend: %w", h, b.Kind(), err)
	}
	dst, err := r.tr.OpenLogStream(sctx, streamID)
	if err != nil {
		src.Close()
		r.close(streamID, s)
		return fmt.Errorf("agent: opening log stream %s to the controller: %w", streamID, err)
	}

	go r.pump(sctx, streamID, s, src, dst)
	return nil
}

// cancel stops one stream, which is what a viewer closing the browser tab
// becomes on the host.
func (r *logRelay) cancel(streamID string) {
	r.mu.Lock()
	s, ok := r.streams[streamID]
	r.mu.Unlock()
	if !ok {
		return
	}
	s.cancel()
	select {
	case <-s.done:
	case <-time.After(relayStopWait):
		r.log.Warn("log stream did not stop promptly", "stream", streamID, "waited", relayStopWait)
	}
}

// stopAll ends every stream, called on shutdown.
func (r *logRelay) stopAll() {
	r.mu.Lock()
	ids := make([]string, 0, len(r.streams))
	for id := range r.streams {
		ids = append(ids, id)
	}
	r.mu.Unlock()
	for _, id := range ids {
		r.cancel(id)
	}
}

func (r *logRelay) close(streamID string, s *logStream) {
	r.mu.Lock()
	if cur, ok := r.streams[streamID]; ok && cur == s {
		delete(r.streams, streamID)
	}
	r.mu.Unlock()
	s.cancel()
	s.finish()
}

// pump moves output from the runner to the controller through a bounded buffer.
//
// When the buffer is full the relay drops output and says so, rather than
// blocking. Blocking would push back on the runner's own output pipe, and a
// container whose stdout nobody drains eventually stops making progress: one
// operator on a slow connection would then be able to stall a build. Losing the
// middle of a log with a marker saying what was lost is the cheaper failure.
func (r *logRelay) pump(ctx context.Context, streamID string, s *logStream, src io.ReadCloser, dst io.WriteCloser) {
	defer r.close(streamID, s)

	// Unblock a backend read that is not watching the context.
	stopWatch := context.AfterFunc(ctx, func() { src.Close() })
	defer stopWatch()

	out := newRelayBuffer()
	var writer sync.WaitGroup
	writer.Add(1)
	go func() {
		defer writer.Done()
		defer func() {
			if err := dst.Close(); err != nil {
				r.log.Debug("closing log stream reported an error", "stream", streamID, "error", err)
			}
		}()
		for {
			chunk, ok := out.next()
			if !ok {
				return
			}
			if _, err := dst.Write(chunk); err != nil {
				r.log.Debug("controller closed a log stream", "stream", streamID, "error", err)
				// A write that failed once never recovers, and a cancel_logs
				// can have arrived before the stream existed, so nothing else
				// would end this one: it would follow the job's output for
				// hours, discarding every byte. Cancelling closes the source
				// through the AfterFunc above. Nothing drains the buffer from
				// here, which costs nothing: it fills, then drops, and the
				// reader never waits on it.
				s.cancel()
				return
			}
		}
	}()

	buf := make([]byte, relayChunkSize)
	for {
		n, err := src.Read(buf)
		if n > 0 {
			out.add(buf[:n])
		}
		if err != nil {
			if err != io.EOF && ctx.Err() == nil {
				r.log.Debug("log stream ended", "stream", streamID, "error", err)
			}
			break
		}
		if ctx.Err() != nil {
			break
		}
	}

	src.Close()
	out.close()
	writer.Wait()
}

package agent

import (
	"context"
	"errors"
	"io"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/backend"
)

// rejectingTransport answers every log stream the way a controller does that
// has already forgotten it: the first write fails.
type rejectingTransport struct {
	*fakeTransport
}

func (rejectingTransport) OpenLogStream(context.Context, string) (io.WriteCloser, error) {
	return rejectedStream{}, nil
}

type rejectedStream struct{}

func (rejectedStream) Write([]byte) (int, error) { return 0, errors.New("stream unknown") }
func (rejectedStream) Close() error              { return nil }

// A viewer who closes the tab before the agent acts leaves a stream the
// controller no longer knows, and a cancel_logs that found nothing to cancel.
// Nothing else ends that stream, so without this the relay follows a job's
// output for hours and throws every byte away.
func TestLogRelayStopsFollowingOnceTheControllerRejectsTheStream(t *testing.T) {
	be := newFakeBackend("docker")
	pr, pw := io.Pipe()
	be.mu.Lock()
	be.logs = func() io.ReadCloser { return pr }
	be.mu.Unlock()

	relay := newLogRelay(rejectingTransport{newFakeTransport()}, testLogger())
	if err := relay.start(context.Background(), "stream-1", "wl-1", be, backend.LogOptions{Follow: true}); err != nil {
		t.Fatalf("start: %v", err)
	}
	// The runner's next line is the first the relay learns the stream is dead.
	go pw.Write([]byte("a line nobody is reading\n"))

	waitFn(t, "the abandoned stream to be released without a cancel", 5*time.Second, func() bool {
		relay.mu.Lock()
		defer relay.mu.Unlock()
		return len(relay.streams) == 0
	})
	// The source has been closed, so a further write has nowhere to go.
	if _, err := pw.Write([]byte("more\n")); err == nil {
		t.Fatal("the relay is still following the runner's log")
	}
}

package agent

import (
	"context"
	"fmt"
	"io"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/backend"
)

// burstReader produces a fixed number of full chunks as fast as it is read, and
// says when it has been drained.
type burstReader struct {
	mu        sync.Mutex
	remaining int
	drained   chan struct{}
	once      sync.Once
}

func newBurstReader(chunks int) *burstReader {
	return &burstReader{remaining: chunks, drained: make(chan struct{})}
}

func (r *burstReader) Read(p []byte) (int, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.remaining == 0 {
		r.once.Do(func() { close(r.drained) })
		return 0, io.EOF
	}
	r.remaining--
	for i := range p {
		p[i] = 'x'
	}
	return len(p), nil
}

func (r *burstReader) Close() error { return nil }

func waitFn(t *testing.T, what string, d time.Duration, fn func() bool) {
	t.Helper()
	deadline := time.Now().Add(d)
	for time.Now().Before(deadline) {
		if fn() {
			return
		}
		time.Sleep(5 * time.Millisecond)
	}
	t.Fatalf("timed out after %s waiting for %s", d, what)
}

func TestLogRelayCopiesOutputEndToEnd(t *testing.T) {
	tr := newFakeTransport()
	be := newFakeBackend("docker")
	be.mu.Lock()
	be.logs = func() io.ReadCloser { return io.NopCloser(strings.NewReader("cloning repository\nrunning job\n")) }
	be.mu.Unlock()

	relay := newLogRelay(tr, testLogger())
	if err := relay.start(context.Background(), "stream-1", "wl-1", be, backend.LogOptions{Follow: true}); err != nil {
		t.Fatalf("start: %v", err)
	}

	waitFn(t, "the stream to finish", 5*time.Second, func() bool {
		s := tr.stream("stream-1")
		return s != nil && s.isClosed()
	})
	if got := tr.stream("stream-1").String(); got != "cloning repository\nrunning job\n" {
		t.Fatalf("relayed %q", got)
	}
}

func TestLogRelayCancelStopsTheStream(t *testing.T) {
	tr := newFakeTransport()
	be := newFakeBackend("docker")
	pr, pw := io.Pipe()
	be.mu.Lock()
	be.logs = func() io.ReadCloser { return pr }
	be.mu.Unlock()

	relay := newLogRelay(tr, testLogger())
	if err := relay.start(context.Background(), "stream-1", "wl-1", be, backend.LogOptions{Follow: true}); err != nil {
		t.Fatalf("start: %v", err)
	}
	if _, err := pw.Write([]byte("still going\n")); err != nil {
		t.Fatalf("write: %v", err)
	}
	waitFn(t, "the first chunk to arrive", 5*time.Second, func() bool {
		s := tr.stream("stream-1")
		return s != nil && strings.Contains(s.String(), "still going")
	})

	relay.cancel("stream-1")
	if !tr.stream("stream-1").isClosed() {
		t.Fatal("cancel did not close the controller's side of the stream")
	}
	relay.mu.Lock()
	open := len(relay.streams)
	relay.mu.Unlock()
	if open != 0 {
		t.Fatalf("%d streams still registered after cancel", open)
	}
	pw.Close()
}

func TestLogRelayDropsRatherThanBlockingOnASlowController(t *testing.T) {
	tr := newFakeTransport()
	// Every write to the controller takes 10ms: writing all 300 chunks would
	// take three seconds, far longer than the runner should ever wait.
	tr.mu.Lock()
	tr.writeHold = 10 * time.Millisecond
	tr.mu.Unlock()

	be := newFakeBackend("docker")
	src := newBurstReader(300)
	be.mu.Lock()
	be.logs = func() io.ReadCloser { return src }
	be.mu.Unlock()

	relay := newLogRelay(tr, testLogger())
	if err := relay.start(context.Background(), "stream-1", "wl-1", be, backend.LogOptions{Follow: true}); err != nil {
		t.Fatalf("start: %v", err)
	}

	// The copy out of the runner must finish at the runner's pace, not the
	// controller's: a slow viewer must never throttle a job.
	select {
	case <-src.drained:
	case <-time.After(2 * time.Second):
		t.Fatal("the copy from the runner blocked on the slow controller")
	}

	waitFn(t, "the stream to finish", 10*time.Second, func() bool {
		s := tr.stream("stream-1")
		return s != nil && s.isClosed()
	})
	relayed := tr.stream("stream-1").String()
	if !strings.Contains(relayed, "log stream fell behind") {
		t.Fatal("output was dropped without telling the viewer that it was")
	}
	if len(relayed) >= 300*relayChunkSize {
		t.Fatal("nothing was dropped, so the relay must have blocked")
	}
}

// lineReader hands out one line per Read, which is how a container's output
// arrives: Docker frames its log stream a record to a frame, and the
// demultiplexer returns at most the rest of the frame it is in. A source that
// fills the whole buffer on every read, like burstReader, hides what that does
// to the relay.
type lineReader struct {
	mu      sync.Mutex
	lines   []string
	next    int
	drained chan struct{}
	once    sync.Once
}

func newLineReader(count int) *lineReader {
	r := &lineReader{drained: make(chan struct{})}
	for i := range count {
		r.lines = append(r.lines, fmt.Sprintf("ZOOMIES_BUILD_LOG build line %04d %s\n", i, strings.Repeat("x", 60)))
	}
	return r
}

func (r *lineReader) Read(p []byte) (int, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.next == len(r.lines) {
		r.once.Do(func() { close(r.drained) })
		return 0, io.EOF
	}
	n := copy(p, r.lines[r.next])
	r.next++
	return n, nil
}

func (r *lineReader) Close() error { return nil }

func (r *lineReader) all() string { return strings.Join(r.lines, "") }

// connectingTransport is a controller whose request has not gone out yet. A
// real transport writes into a pipe that the HTTP client only starts reading
// once it has connected, so the first write waits for that however much the
// runner has already said.
type connectingTransport struct {
	*fakeTransport
	connected <-chan struct{}
}

func (t connectingTransport) OpenLogStream(ctx context.Context, streamID string) (io.WriteCloser, error) {
	w, err := t.fakeTransport.OpenLogStream(ctx, streamID)
	if err != nil {
		return nil, err
	}
	return &connectingStream{fakeStream: w.(*fakeStream), connected: t.connected}, nil
}

type connectingStream struct {
	*fakeStream
	connected <-chan struct{}
	once      sync.Once
}

func (s *connectingStream) Write(p []byte) (int, error) {
	s.once.Do(func() { <-s.connected })
	return s.fakeStream.Write(p)
}

// Opening a runner asks for its last thousand lines, which the daemon sends as
// fast as the socket takes them, and the controller is not listening for the
// first few milliseconds. A relay that held a fixed number of reads rather than
// a fixed number of bytes kept the first sixty-four lines of that and threw the
// rest away, so the viewer opened on the oldest lines of the backlog and a
// warning, and the job's output was exactly what was missing.
func TestLogRelayKeepsABacklogOfShortLinesWhileTheRequestConnects(t *testing.T) {
	const lines = 1000
	src := newLineReader(lines)
	connected := make(chan struct{})
	tr := connectingTransport{fakeTransport: newFakeTransport(), connected: connected}
	be := newFakeBackend("docker")
	be.mu.Lock()
	be.logs = func() io.ReadCloser { return src }
	be.mu.Unlock()

	relay := newLogRelay(tr, testLogger())
	if err := relay.start(context.Background(), "stream-1", "wl-1", be, backend.LogOptions{Follow: true, Tail: lines}); err != nil {
		t.Fatalf("start: %v", err)
	}

	// The whole backlog is read while nothing is accepting it.
	select {
	case <-src.drained:
	case <-time.After(5 * time.Second):
		t.Fatal("the copy from the runner blocked on a controller that had not connected")
	}
	close(connected)

	waitFn(t, "the stream to finish", 10*time.Second, func() bool {
		s := tr.stream("stream-1")
		return s != nil && s.isClosed()
	})
	got := tr.stream("stream-1").String()
	if want := src.all(); got != want {
		t.Fatalf("relayed %d of %d lines, %d of %d bytes; marker present: %v; want the whole backlog, in order, with nothing said to be missing",
			strings.Count(got, "build line"), lines, len(got), len(want), strings.Contains(got, "fell behind"))
	}
}

func TestLogRelayIgnoresARedeliveredStart(t *testing.T) {
	tr := newFakeTransport()
	be := newFakeBackend("docker")
	pr, pw := io.Pipe()
	t.Cleanup(func() { pw.Close() })
	be.mu.Lock()
	be.logs = func() io.ReadCloser { return pr }
	be.mu.Unlock()

	relay := newLogRelay(tr, testLogger())
	for range 3 {
		if err := relay.start(context.Background(), "stream-1", "wl-1", be, backend.LogOptions{Follow: true}); err != nil {
			t.Fatalf("start: %v", err)
		}
	}
	relay.mu.Lock()
	open := len(relay.streams)
	relay.mu.Unlock()
	if open != 1 {
		t.Fatalf("%d streams open, want 1: a redelivered stream_logs task must not open a second copy", open)
	}
	relay.stopAll()
}

func TestAgentStreamsAndCancelsLogsForARunner(t *testing.T) {
	h := newHarness(t, 1)
	h.be.mu.Lock()
	h.be.logs = func() io.ReadCloser { return io.NopCloser(strings.NewReader("job output\n")) }
	h.be.mu.Unlock()

	h.tr.tasks <- []Task{createTask("task-1", "runner-1")}
	if res := h.nextResult(); !res.OK {
		t.Fatalf("create failed: %+v", res)
	}

	h.tr.tasks <- []Task{{ID: "task-2", Kind: TaskStreamLogs, RunnerID: "runner-1", StreamID: "stream-1"}}
	if res := h.nextResult(); !res.OK {
		t.Fatalf("stream_logs failed: %+v", res)
	}
	waitFn(t, "the log output to arrive", 5*time.Second, func() bool {
		s := h.tr.stream("stream-1")
		return s != nil && strings.Contains(s.String(), "job output")
	})

	h.tr.tasks <- []Task{{ID: "task-3", Kind: TaskCancelLogs, RunnerID: "runner-1", StreamID: "stream-1"}}
	if res := h.nextResult(); !res.OK {
		t.Fatalf("cancel_logs failed: %+v", res)
	}
}

func TestStreamLogsForAnUnknownRunnerIsReported(t *testing.T) {
	h := newHarness(t, 1)
	h.tr.tasks <- []Task{{ID: "task-1", Kind: TaskStreamLogs, RunnerID: "runner-404", StreamID: "stream-1"}}

	res := h.nextResult()
	if res.OK || !strings.Contains(res.Error, "runner-404") {
		t.Fatalf("unexpected result: %+v", res)
	}
}

package agent

import (
	"fmt"
	"math"
	"strings"
	"time"
)

// The memory valve's guard is the one decision the agent makes for itself.
// Everything else about elastic memory is the controller's: which pools may be
// lent to, how much of a host is spare, how far one runner may go. But a kernel
// that is about to kill a compiler does not wait for a heartbeat thirty seconds
// away, so the agent watches each runner's memory itself and raises a limit
// when it has to, inside the rules the last heartbeat gave it.
//
// The decision is a function of its input -- no clock, no daemon, no host -- so
// that every one of its edges can be a row of a table.

// MemoryValveCode is a stable name for a guard decision, for metrics, tests and
// the Runners page. The controller reads it out of a runner's report, which is
// why it is part of the wire format.
type MemoryValveCode string

const (
	// MemoryHealthy: use is well inside the limit, and nothing was done.
	MemoryHealthy MemoryValveCode = "healthy"
	// MemoryRaised: the limit was raised out of the host's pool.
	MemoryRaised MemoryValveCode = "raised"
	// MemorySpilled: the limit could not be raised far enough and the runner was
	// pressing against it, so it was allowed some swap.
	MemorySpilled MemoryValveCode = "spilled"
	// MemoryAtCeiling: the runner wants more and already holds the most it may.
	MemoryAtCeiling MemoryValveCode = "at_ceiling"
	// MemoryPoolEmpty: the host has no spare memory left to lend.
	MemoryPoolEmpty MemoryValveCode = "pool_empty"
	// MemoryHostFloor: lending would leave the host less free memory than its floor.
	MemoryHostFloor MemoryValveCode = "host_floor"
	// MemoryUnmeasured: the host's free memory could not be read, and a loan
	// that cannot be checked against it is not made.
	MemoryUnmeasured MemoryValveCode = "unmeasured"
	// MemoryUnsupported: the container runtime refused to change a live limit.
	MemoryUnsupported MemoryValveCode = "unsupported"
	// MemoryFailed: the runtime refused for another reason, and will be asked again.
	MemoryFailed MemoryValveCode = "failed"
)

// The thresholds the guard works to. They are constants rather than settings:
// they are what makes the valve behave the same on every host, and a pool that
// wants more or less memory has the ceiling for it.
const (
	// MemoryMargin is how far above its use a container's limit is kept: a
	// third as much again, so that the allocation a compiler makes between two
	// looks is inside it. A faster spike than that can still hit the old limit,
	// which is a limit of the idea and not something a poll interval can fix.
	MemoryMargin = 1.3
	// MemoryHotShare is how much of its limit a container must be using to be
	// watched every second rather than every few.
	MemoryHotShare = 0.70
	// MemoryStepMB is the granularity of a raise. Use creeping up a few
	// megabytes at a time would otherwise cost an update for each.
	MemoryStepMB = 64
	// MemoryMinimumRaiseMB is the least a raise adds when it has the room for
	// more, for the same reason: a raise is a call to the daemon, and one that
	// buys a second of margin is not worth it.
	MemoryMinimumRaiseMB = 128
	// MemorySpillShare is how much of its limit a container that cannot be
	// raised further must be using before it is given swap. Short of the whole
	// of it, because swap is the slower way out and is spent when a kill is
	// close, not when memory is merely tight.
	MemorySpillShare = 0.90
)

// MemoryGuardInput is one container at one look. A docker-in-docker runner is
// two containers, each looked at alone, with HeldMB and CeilingMB the pair's.
type MemoryGuardInput struct {
	// UsageMB is the container's working set: its memory without the page
	// cache the kernel gives back when asked.
	UsageMB int64
	// LimitMB is its memory limit now, and SwapMB the swap it may use beyond
	// that. A container with no memory limit is not the guard's business and
	// is never passed in.
	LimitMB, SwapMB int64
	// HeldMB is the limits of every container of this runner added together,
	// and CeilingMB the most they may come to (scheduler.MemoryCeiling).
	HeldMB, CeilingMB int64
	// PoolMB is what the host may still lend: its capacity less what its
	// runners hold already.
	PoolMB int64
	// AvailableMB is the host's free memory as it is right now and FloorMB the
	// least a loan may leave it. Known is false when it could not be read.
	AvailableMB, FloorMB int64
	AvailableKnown       bool
	// SpillMB is the swap the pool allows this container beyond its limit, and
	// SwapFreeMB the swap the host has free; SwapKnown is false when the host's
	// swap could not be read.
	SpillMB, SwapFreeMB int64
	SwapKnown           bool
	// Observing says the decision is to be recorded and not made, so that its
	// reason is worded as what would have been done. A card that says nothing
	// was changed cannot also say a limit was raised.
	Observing bool
}

// MemoryGuardDecision is what the guard would do. LimitMB and SwapMB are what
// the container should have afterwards: never less than it has now, because
// lowering a live limit is what kills the job a loan is meant to save.
type MemoryGuardDecision struct {
	LimitMB, SwapMB int64
	Code            MemoryValveCode
	// Reason is the sentence for an operator: why the limit moved, or why it
	// did not when the container wanted it to.
	Reason string
}

// Changed reports whether the decision asks the daemon for anything.
func (d MemoryGuardDecision) Changed(in MemoryGuardInput) bool {
	return d.LimitMB > in.LimitMB || d.SwapMB > in.SwapMB
}

// MemoryWanted is the limit the guard would keep a container at, given what it
// is using: use plus the margin, rounded up to a step.
func MemoryWanted(usageMB int64) int64 {
	if usageMB <= 0 {
		return 0
	}
	want := int64(math.Ceil(float64(usageMB) * MemoryMargin))
	return (want + MemoryStepMB - 1) / MemoryStepMB * MemoryStepMB
}

// MemoryHot reports whether a container is using enough of its limit to be
// watched closely.
func MemoryHot(usageMB, limitMB int64) bool {
	return limitMB > 0 && float64(usageMB) >= MemoryHotShare*float64(limitMB)
}

// MemoryClimbing reports whether a container is gaining memory fast enough to
// reach its limit before a quiet runner would next be looked at.
//
// Share of the limit alone is not enough to decide how closely to watch. A raise
// leaves a runner with a wide margin and so reading cold, and the build that
// needed the raise has not stopped: at thirty megabytes a second a quiet look
// every five seconds is a hundred and fifty megabytes late. So the pace since
// the last look is read too, and a runner that would be at its limit within two
// quiet intervals at that pace is watched every second until it stops.
//
// Nothing is concluded from a first look, from use that fell, or from two looks
// no time apart.
func MemoryClimbing(prevMB, usageMB, limitMB int64, since time.Duration) bool {
	rise := usageMB - prevMB
	if prevMB <= 0 || rise <= 0 || limitMB <= 0 || since <= 0 {
		return false
	}
	perSecond := float64(rise) / since.Seconds()
	return float64(max(limitMB-usageMB, 0))/perSecond < memoryClimbHorizon.Seconds()
}

// GuardMemory decides whether to raise one container's limit.
//
// A container keeps its limit a third above its use. While it does, nothing
// happens. When use climbs past that point the limit is raised to restore the
// margin, out of the host's pool, within the runner's ceiling, and only so far
// as the host can spare the memory above its floor right now -- the pool is the
// controller's idea of what is spare, and the free memory is the machine's, and
// a loan is made out of the smaller.
//
// If that cannot cover what the container wants and it is nearly at its limit,
// and its pool allows swap and the host has some, it is allowed swap: the last
// resort, which turns a kill into a slowdown.
//
// A decision is always at least what the container has. The guard never asks
// for less, whatever use does.
func GuardMemory(in MemoryGuardInput) MemoryGuardDecision {
	out := MemoryGuardDecision{LimitMB: in.LimitMB, SwapMB: in.SwapMB, Code: MemoryHealthy}
	if in.LimitMB <= 0 {
		return out
	}
	want := MemoryWanted(in.UsageMB)
	if in.LimitMB >= want {
		return out
	}

	// What it wants, and the four things that can say no. They are asked in the
	// order an operator would fix them: the runner's own ceiling, then the
	// host's pool, then whether the host can be measured, then its floor.
	spare := in.AvailableMB - in.FloorMB
	room := max(in.CeilingMB-in.HeldMB, 0)
	var blocked MemoryValveCode
	var because string
	switch {
	case room <= 0:
		blocked, because = MemoryAtCeiling, fmt.Sprintf("it holds %d MB, the most this runner may have", in.HeldMB)
	case in.PoolMB <= 0:
		blocked, because = MemoryPoolEmpty, "the host has no spare memory left to lend"
	case !in.AvailableKnown:
		blocked, because = MemoryUnmeasured, "the host's free memory could not be measured, so none is lent"
	case spare <= 0:
		blocked, because = MemoryHostFloor, fmt.Sprintf("the host has %d MB free and keeps %d MB back", in.AvailableMB, in.FloorMB)
	}
	raised, allowed := "raised", "allowed"
	if in.Observing {
		raised, allowed = "would have raised", "would have allowed"
	}
	var said []string
	if blocked == "" {
		give := max(want-in.LimitMB, MemoryMinimumRaiseMB)
		give = min(give, room, in.PoolMB, spare)
		out.LimitMB, out.Code = in.LimitMB+give, MemoryRaised
		said = append(said, fmt.Sprintf("%s the limit from %d to %d MB: it was using %d MB", raised, in.LimitMB, out.LimitMB, in.UsageMB))
		if out.LimitMB >= want {
			out.Reason = said[0]
			return out
		}
		// Short of what it wanted: whichever of the three bound the raise is
		// why, and the first that did is named.
		switch give {
		case room:
			blocked, because = MemoryAtCeiling, fmt.Sprintf("that is the most this runner may have (%d MB)", in.CeilingMB)
		case in.PoolMB:
			blocked, because = MemoryPoolEmpty, "that was the last of what the host has to lend"
		default:
			blocked, because = MemoryHostFloor, fmt.Sprintf("that leaves the host its floor of %d MB", in.FloorMB)
		}
		said = append(said, because)
	} else {
		out.Code = blocked
		said = append(said, fmt.Sprintf("it is using %d MB of its %d MB limit and wants more, but %s", in.UsageMB, in.LimitMB, because))
	}

	// Not enough, or nothing at all. A kill is close if the container is
	// pressing against what it has now, and swap is the way out that costs
	// speed rather than the job.
	if float64(in.UsageMB) >= MemorySpillShare*float64(out.LimitMB) {
		allowance := min(in.SpillMB, in.SwapFreeMB)
		switch {
		case in.SpillMB <= 0:
			// The pool does not allow swap, so there is nothing to add.
		case !in.SwapKnown || in.SwapFreeMB <= 0:
			said = append(said, "swap is allowed but the host has none free")
		case allowance > in.SwapMB:
			out.SwapMB, out.Code = allowance, MemorySpilled
			said = append(said, fmt.Sprintf("%s %d MB of swap beyond its %d MB limit", allowed, allowance, out.LimitMB))
		}
	}
	out.Reason = strings.Join(said, "; ")
	return out
}

package agent

import (
	"strings"
	"testing"
	"time"
)

// roomy is a container with everything the guard could ask for: a host with
// plenty free, a pool with plenty in it and a ceiling well above the limit. A
// test changes the one thing it is about.
func roomy() MemoryGuardInput {
	return MemoryGuardInput{
		UsageMB: 2000, LimitMB: 4096,
		HeldMB: 4096, CeilingMB: 6144,
		PoolMB:      4096,
		AvailableMB: 12000, FloorMB: 2000, AvailableKnown: true,
	}
}

func TestAContainerWellInsideItsLimitIsLeftAlone(t *testing.T) {
	in := roomy()
	got := GuardMemory(in)
	if got.Code != MemoryHealthy || got.Changed(in) {
		t.Fatalf("decision = %+v, want healthy and unchanged", got)
	}
	// A third above its use is the margin; sitting exactly on it is still inside.
	in.UsageMB = 3150 // wants 4095, rounded to 4096: the limit it has
	if got := GuardMemory(in); got.Changed(in) {
		t.Fatalf("a container exactly at its margin was changed: %+v", got)
	}
}

// The margin is what lets a build allocate between two looks without being
// killed, so the limit is restored to it rather than raised to a round figure.
func TestPastItsMarginTheLimitIsRaisedToRestoreIt(t *testing.T) {
	in := roomy()
	in.UsageMB = 3300 // wants 4290, so 4352 in whole steps
	got := GuardMemory(in)
	if got.Code != MemoryRaised || got.LimitMB != 4352 || got.SwapMB != 0 {
		t.Fatalf("decision = %+v, want the limit raised to 4352", got)
	}
	if !got.Changed(in) || !strings.Contains(got.Reason, "from 4096 to 4352") {
		t.Fatalf("reason = %q, want it to say what moved", got.Reason)
	}
}

// A raise is a call to the daemon, so one that buys less than a short step is
// rounded up to the least worth making when the room is there.
func TestARaiseIsAtLeastTheMinimumWhenThereIsRoom(t *testing.T) {
	in := roomy()
	in.UsageMB = 3200 // wants 4160: 64 more than it has
	if got := GuardMemory(in); got.LimitMB != 4096+MemoryMinimumRaiseMB {
		t.Fatalf("limit = %d, want %d", got.LimitMB, 4096+MemoryMinimumRaiseMB)
	}
}

func TestTheGuardNeverLowersALimitWhateverTheUse(t *testing.T) {
	for _, usage := range []int64{0, 1, 500, 4000, 9000} {
		in := roomy()
		in.UsageMB = usage
		got := GuardMemory(in)
		if got.LimitMB < in.LimitMB || got.SwapMB < in.SwapMB {
			t.Errorf("usage %d lowered something: %+v", usage, got)
		}
	}
	// No limit at all is no business of the guard's.
	in := roomy()
	in.LimitMB = 0
	if got := GuardMemory(in); got.Changed(in) || got.Code != MemoryHealthy {
		t.Fatalf("a container with no limit was changed: %+v", got)
	}
}

func TestARaiseStopsAtTheRunnersCeiling(t *testing.T) {
	in := roomy()
	in.UsageMB = 3300
	in.CeilingMB = 4300 // 204 MB of room
	got := GuardMemory(in)
	if got.Code != MemoryRaised || got.LimitMB != 4300 {
		t.Fatalf("decision = %+v, want a raise to the ceiling of 4300", got)
	}
	if !strings.Contains(got.Reason, "the most this runner may have (4300 MB)") {
		t.Fatalf("reason = %q, want it to say the ceiling stopped the raise", got.Reason)
	}

	// Already there: it wants more and may not have it.
	in.HeldMB = 4300
	in.LimitMB = 4300
	in.UsageMB = 4000
	got = GuardMemory(in)
	if got.Code != MemoryAtCeiling || got.Changed(in) {
		t.Fatalf("decision = %+v, want at_ceiling and nothing changed", got)
	}
}

// A pair's two halves are limited together: the ceiling is the pair's, and what
// the other half holds is room this one does not have.
func TestADockerInDockerPairSharesOneCeiling(t *testing.T) {
	in := roomy()
	in.LimitMB, in.HeldMB = 2048, 4096 // this half, and the pair
	in.CeilingMB = 6144
	in.UsageMB = 1900 // wants 2496
	got := GuardMemory(in)
	if got.Code != MemoryRaised || got.LimitMB != 2496 {
		t.Fatalf("decision = %+v, want the daemon's half raised to 2496", got)
	}
	// With the other half holding enough to bring the pair to its ceiling, this
	// half has no room whatever it is using.
	in.HeldMB = 6144
	if got := GuardMemory(in); got.Code != MemoryAtCeiling || got.Changed(in) {
		t.Fatalf("a pair at its ceiling was raised: %+v", got)
	}
}

func TestAnEmptyPoolLendsNothing(t *testing.T) {
	in := roomy()
	in.UsageMB = 3300
	in.PoolMB = 0
	got := GuardMemory(in)
	if got.Code != MemoryPoolEmpty || got.Changed(in) {
		t.Fatalf("decision = %+v, want pool_empty and nothing changed", got)
	}
	if !strings.Contains(got.Reason, "no spare memory left to lend") {
		t.Fatalf("reason = %q", got.Reason)
	}

	// The last of the pool is lent, and the raise says it was the last.
	in.PoolMB = 100
	got = GuardMemory(in)
	if got.Code != MemoryRaised || got.LimitMB != 4196 || !strings.Contains(got.Reason, "last of what the host has to lend") {
		t.Fatalf("decision = %+v, want the last 100 MB lent", got)
	}
}

// The pool is the controller's idea, which is thirty seconds old at worst. The
// machine's own free memory is checked at the moment of the raise, and a loan is
// made out of the smaller of the two.
func TestAHostAtItsFloorLendsNothingWhateverThePoolSays(t *testing.T) {
	in := roomy()
	in.UsageMB = 3300
	in.AvailableMB, in.FloorMB = 2000, 2000
	got := GuardMemory(in)
	if got.Code != MemoryHostFloor || got.Changed(in) {
		t.Fatalf("decision = %+v, want host_floor and nothing changed", got)
	}
	in.AvailableMB = 2100
	got = GuardMemory(in)
	if got.LimitMB != 4196 || got.Code != MemoryRaised {
		t.Fatalf("decision = %+v, want only the 100 MB above the floor lent", got)
	}
}

func TestAHostThatCannotBeMeasuredLendsNothing(t *testing.T) {
	in := roomy()
	in.UsageMB = 3300
	in.AvailableKnown = false
	got := GuardMemory(in)
	if got.Code != MemoryUnmeasured || got.Changed(in) {
		t.Fatalf("decision = %+v, want unmeasured and nothing changed", got)
	}
}

// Swap is the last resort, and it is spent when a kill is close: nearly at the
// limit, with nothing left in memory to give.
func TestSwapIsAllowedOnlyWhenTheMemoryCannotBeFoundAndAKillIsClose(t *testing.T) {
	in := roomy()
	in.PoolMB = 0
	in.SpillMB, in.SwapFreeMB, in.SwapKnown = 2048, 8192, true

	in.UsageMB = 3300 // 80% of the limit: tight, not about to be killed
	if got := GuardMemory(in); got.Code != MemoryPoolEmpty || got.SwapMB != 0 {
		t.Fatalf("at 80%% decision = %+v, want no swap yet", got)
	}

	in.UsageMB = 3900 // 95%
	got := GuardMemory(in)
	if got.Code != MemorySpilled || got.SwapMB != 2048 || got.LimitMB != 4096 {
		t.Fatalf("at 95%% decision = %+v, want 2048 MB of swap and the limit as it was", got)
	}
	if !strings.Contains(got.Reason, "allowed 2048 MB of swap") {
		t.Fatalf("reason = %q", got.Reason)
	}

	// Once granted it is not granted again.
	in.SwapMB = 2048
	if got := GuardMemory(in); got.Changed(in) {
		t.Fatalf("swap already allowed, yet %+v", got)
	}
}

func TestSwapIsBoundedByWhatTheHostHasAndWhatThePoolAllows(t *testing.T) {
	in := roomy()
	in.PoolMB = 0
	in.UsageMB = 3900
	in.SpillMB, in.SwapKnown = 4096, true
	in.SwapFreeMB = 512
	if got := GuardMemory(in); got.SwapMB != 512 {
		t.Fatalf("swap = %d, want the 512 MB the host has free", got.SwapMB)
	}
	in.SwapFreeMB = 0
	got := GuardMemory(in)
	if got.Changed(in) || !strings.Contains(got.Reason, "none free") {
		t.Fatalf("decision = %+v, want nothing changed and a reason that says why", got)
	}
	// A pool that does not allow swap never has any.
	in.SpillMB, in.SwapFreeMB = 0, 8192
	if got := GuardMemory(in); got.SwapMB != 0 || got.Code != MemoryPoolEmpty {
		t.Fatalf("decision = %+v, want no swap for a pool that did not allow it", got)
	}
	// A host whose swap could not be read is not guessed at.
	in.SpillMB, in.SwapKnown = 4096, false
	if got := GuardMemory(in); got.SwapMB != 0 {
		t.Fatalf("swap = %d on a host whose swap was not read", got.SwapMB)
	}
}

// A raise that could not cover the whole of what was wanted is still made, and
// the container, if it is then close to the end of it, is given swap as well.
func TestAPartialRaiseAndSwapCanComeTogether(t *testing.T) {
	in := roomy()
	in.UsageMB = 4000
	in.CeilingMB = 4200
	in.SpillMB, in.SwapFreeMB, in.SwapKnown = 1024, 8192, true
	got := GuardMemory(in)
	if got.LimitMB != 4200 || got.SwapMB != 1024 || got.Code != MemorySpilled {
		t.Fatalf("decision = %+v, want the limit at its ceiling and 1024 MB of swap", got)
	}
	if !strings.Contains(got.Reason, "raised the limit from 4096 to 4200") || !strings.Contains(got.Reason, "allowed 1024 MB of swap") {
		t.Fatalf("reason = %q, want both halves said", got.Reason)
	}
}

// An observing valve changes nothing, and the reason it gives is the one the
// Runners page puts beside "would have lent": a sentence that said a limit was
// raised would contradict the card it sits on.
func TestAnObservedDecisionIsWordedAsWhatWouldHaveBeenDone(t *testing.T) {
	in := roomy()
	in.UsageMB = 4000
	in.CeilingMB = 4200
	in.SpillMB, in.SwapFreeMB, in.SwapKnown = 1024, 8192, true
	in.Observing = true
	got := GuardMemory(in)
	if got.LimitMB != 4200 || got.SwapMB != 1024 || got.Code != MemorySpilled {
		t.Fatalf("decision = %+v, want the same decision an acting valve makes", got)
	}
	for _, want := range []string{"would have raised the limit from 4096 to 4200", "would have allowed 1024 MB of swap"} {
		if !strings.Contains(got.Reason, want) {
			t.Fatalf("reason = %q, want it to say %q", got.Reason, want)
		}
	}
	if strings.Contains(got.Reason, " raised the limit") && !strings.Contains(got.Reason, "would have raised") {
		t.Fatalf("reason = %q, an observing valve raised nothing", got.Reason)
	}
}

func TestWhatAContainerIsKeptAtAndWhenItIsWatchedClosely(t *testing.T) {
	for _, tc := range []struct {
		usage, want int64
	}{{0, 0}, {-5, 0}, {1000, 1344}, {3000, 3904}} {
		if got := MemoryWanted(tc.usage); got != tc.want {
			t.Errorf("MemoryWanted(%d) = %d, want %d", tc.usage, got, tc.want)
		}
	}
	if !MemoryHot(2900, 4096) || MemoryHot(2800, 4096) || MemoryHot(100, 0) {
		t.Fatal("hot is 70% of the limit, and nothing without one")
	}
}

// Share of the limit says how tight a runner is, not how fast it is going. A
// runner that has just been raised reads cold, and a build still climbing at
// thirty megabytes a second is a hundred and fifty late to a quiet look five
// seconds on, so the pace is read too.
func TestARunnerThatWouldReachItsLimitBeforeTheNextQuietLookIsClimbing(t *testing.T) {
	for _, tc := range []struct {
		name               string
		prev, usage, limit int64
		since              time.Duration
		climbing           bool
	}{
		{"a build climbing at thirty a second under a wide margin", 114, 146, 256, time.Second, true},
		{"the same climb with a limit that is far away", 114, 146, 4096, time.Second, false},
		{"a slow creep is not a climb", 100, 106, 256, time.Second, false},
		{"use that fell is not a climb", 200, 150, 256, time.Second, false},
		{"use that did not move is not a climb", 150, 150, 256, time.Second, false},
		{"a first look has nothing to measure against", 0, 150, 256, time.Second, false},
		{"two looks no time apart say nothing", 100, 140, 256, 0, false},
		{"a climb over a long gap is read at its pace, which is slow", 100, 130, 256, 30 * time.Second, false},
		{"a runner already past its limit is as close as it gets", 200, 260, 256, time.Second, true},
		{"a container with no limit has nothing to reach", 100, 400, 0, time.Second, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := MemoryClimbing(tc.prev, tc.usage, tc.limit, tc.since); got != tc.climbing {
				t.Fatalf("MemoryClimbing(%d, %d, %d, %v) = %v, want %v", tc.prev, tc.usage, tc.limit, tc.since, got, tc.climbing)
			}
		})
	}
}

package agent

import (
	"context"
	"errors"
	"fmt"
	"slices"
	"strings"
	"sync"
	"time"

	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/machine"
	"github.com/eyupio/zoomies/internal/store"
)

// The memory valve's loop. Everything the controller decides arrives in a
// heartbeat (ElasticMemoryDirective); what this file does is look at each
// runner's memory between heartbeats and, inside those rules, raise a limit
// before the kernel kills a process for it.
//
// It is the one loop in the agent that acts without being told to, and so it is
// held to the standard that matters for that: it only ever raises a limit, it
// re-reads the host's free memory before every raise, and everything it needs
// to be right after a restart -- what each container was created with, what it
// holds now -- is read back from the daemon rather than remembered.
const (
	// memoryGuardTick is how often the loop wakes. A runner close to its limit
	// is looked at on every tick, because a compiler can find the end of its
	// limit in the time a longer interval would leave.
	memoryGuardTick = time.Second
	// memoryIdleLook is how often a runner that is not close is looked at. Most
	// are not, and a look is a call to the daemon per container.
	memoryIdleLook = 5 * time.Second
	// memoryRediscover is how long what is known of a runner's containers is
	// trusted: a docker-in-docker sidecar appears a little after its runner, and
	// a limit someone changed by hand is read back rather than argued with.
	memoryRediscover = 30 * time.Second
	// memoryLookTimeout bounds the calls to the daemon for one runner. A daemon
	// that does not answer must cost one look, not the loop.
	memoryLookTimeout = 3 * time.Second
	// memoryClimbHorizon is how soon a climbing runner must be able to reach its
	// limit, at the pace it has been going, to be looked at every second: two
	// quiet intervals, so that it is never left to the first of them.
	memoryClimbHorizon = 2 * memoryIdleLook
	// memoryNearShare is how much of a limit a runner must have used to have
	// "come near" it, for the count an operator reads before trusting the valve.
	memoryNearShare = 0.90
	// memoryWorkers bounds the looks made at once.
	memoryWorkers = 4
	// memoryFailedLooks is how many looks in a row may fail to read a runner's
	// containers before the runner says so. One is a daemon that was busy; three
	// are a daemon that will not answer, or a runtime whose stats this guard
	// cannot read, and a runner reporting "healthy" over that is evidence of
	// nothing -- least of all in observe mode, whose whole product is the claim
	// that a pool never came near a limit.
	memoryFailedLooks = 3
)

// valveContainer is one container of a watched runner: what the daemon says it
// holds, and what an observing agent pretends it holds.
type valveContainer struct {
	backend.MemoryContainer
	// UsageMB is what the container was using at the latest look and PrevUsageMB
	// at the one before: the pace between them is how a runner that is climbing
	// is told from one that is merely tight.
	UsageMB, PrevUsageMB int64
	// VirtualLimitMB and VirtualSwapMB are the limit and swap this container
	// would have if the agent were allowed to act. They start equal to the real
	// ones and move only in observe mode, so that what an observing agent decides
	// builds on what it decided before, as an automatic one's raises do.
	VirtualLimitMB, VirtualSwapMB int64
}

// memoryValve is the guard's record of one runner. It is only ever read or
// written under Agent.mu.
type memoryValve struct {
	// rule is what the controller last said about this runner. Nil when it no
	// longer says anything -- the pool's valve was switched off -- which stops
	// the guard acting on the runner but does not stop it reporting what the
	// runner holds: a raised limit stays raised.
	rule         *ElasticMemoryRunner
	containers   []valveContainer
	discoveredAt time.Time
	lastLook     time.Time
	// hot is whether a container was using enough of its limit at the last look
	// to be worth looking at again at once.
	hot bool
	// code and reason are the latest decision, and the sentence of the latest one
	// that was not "healthy".
	code   MemoryValveCode
	reason string
	// nearLimit is sticky: a runner that came within a tenth of a limit once is
	// one whose pool's jobs use the valve, whatever it did after.
	nearLimit bool
	raises    int
	// lookFailures counts the looks in a row that could not read everything they
	// looked at, and lastFailure is why.
	lookFailures int
	lastFailure  string
	// warned keeps a failing update to one warning per reason per runner.
	warned map[string]bool
}

// lentMB is what the runner's containers hold beyond what they were created
// with, and spillMB the swap they may use beyond their limits. Unlimited swap is
// not a loan, and is not counted as one.
func (v *memoryValve) lentMB() (lent, spill int64) {
	for _, c := range v.containers {
		lent += max(c.LimitMB-c.GuaranteeMB, 0)
		if c.SwapMB < unlimitedSwapMB {
			spill += c.SwapMB
		}
	}
	return lent, spill
}

// wouldLendMB is lentMB for the limits an observing agent decided on.
func (v *memoryValve) wouldLendMB() (lent, spill int64) {
	for _, c := range v.containers {
		lent += max(c.VirtualLimitMB-c.GuaranteeMB, 0)
		if c.VirtualSwapMB < unlimitedSwapMB {
			spill += c.VirtualSwapMB
		}
	}
	return lent, spill
}

// unlimitedSwapMB is what the backend reports for a container whose swap has no
// limit; see backend.swapUnlimited.
const unlimitedSwapMB = int64(1) << 40

// sample is what the heartbeat carries for the runner, nil when the valve has
// nothing to say about it.
func (v *memoryValve) sample() *backend.MemoryValveSample {
	if v == nil {
		return nil
	}
	lent, spill := v.lentMB()
	if v.rule == nil && lent == 0 && spill == 0 {
		return nil
	}
	out := &backend.MemoryValveSample{
		Mode:       string(store.MemoryBurstOff),
		Code:       string(v.code),
		Reason:     v.reason,
		LentBytes:  lent << 20,
		SpillBytes: spill << 20,
		NearLimit:  v.nearLimit,
		Raises:     v.raises,
	}
	if out.Code == "" {
		out.Code = string(MemoryHealthy)
	}
	if v.rule != nil {
		out.Mode = string(v.rule.Mode)
		if v.rule.Mode == store.MemoryBurstObserve {
			would, wouldSpill := v.wouldLendMB()
			out.WouldLendBytes, out.WouldSpillBytes = would<<20, wouldSpill<<20
		}
	}
	return out
}

// memoryRules is the last ElasticMemoryDirective, indexed for the loop.
type memoryRules struct {
	capacityMB, floorMB int64
	runners             map[string]ElasticMemoryRunner
}

// features is what this agent says it can do, which the heartbeat and the join
// both carry. The memory valve is offered wherever the host's memory can be read
// the way it has to be, which is Linux's procfs; elsewhere there is nothing to
// check a loan against, and a loan that cannot be checked is not made.
func (a *Agent) features() []string {
	out := []string{FeatureElasticCPU, FeatureToolCacheFill, FeatureTmpfs, FeatureDaemonShare}
	// Last, so the order the other flags have always had does not move. The
	// flag follows the monitor's own ability to run the checks, never the
	// report it last published: a container's report says container=false when
	// the host-health service wrote it, and that agent still cannot answer.
	if a.canCheckHost() {
		out = append(out, FeatureHostCheck)
	}
	if a.opts.ReadMemory != nil {
		out = append(out, FeatureElasticMemory)
	} else {
		// A daemon on another machine cannot be checked against this one's procfs,
		// so every decision here would be "unmeasured": offering the valve there
		// would have the controller send rules that can never be carried out and
		// say nothing about it.
		a.mu.Lock()
		remote := remoteDaemon(a.backendInfo)
		a.mu.Unlock()
		if machine.MemoryReadable() && !remote {
			out = append(out, FeatureElasticMemory)
		}
	}
	// An older agent answers an update task with a failure, so the controller
	// sends one only where this is offered, and it is offered only while the
	// helper's marker is in a folder a request can be written to: a request
	// nobody reads would sit until the attempt timed out.
	if a.selfUpdateReady() {
		out = append(out, FeatureSelfUpdate)
	}
	return out
}

// applyMemoryDirective replaces the valve's rules with the heartbeat's. A
// controller that sends none is a controller with nothing for the valve to do,
// and clears them; a heartbeat that did not arrive leaves them alone, which is
// what keeps a controller restart from being the thing that kills a job.
func (a *Agent) applyMemoryDirective(d *ElasticMemoryDirective) {
	a.mu.Lock()
	defer a.mu.Unlock()
	rules := memoryRules{}
	if d != nil {
		rules.capacityMB, rules.floorMB = d.CapacityMB, d.FloorMB
		rules.runners = make(map[string]ElasticMemoryRunner, len(d.Runners))
		for _, r := range d.Runners {
			if r.RunnerID != "" && (r.Mode == store.MemoryBurstObserve || r.Mode == store.MemoryBurstAutomatic) && r.CeilingMB > 0 {
				rules.runners[r.RunnerID] = r
			}
		}
	}
	a.memory = rules
	for id, t := range a.runners {
		rule, ok := rules.runners[id]
		switch {
		case ok && t.valve == nil:
			t.valve = &memoryValve{rule: &rule}
		case ok:
			t.valve.rule = &rule
		case t.valve != nil:
			t.valve.rule = nil
		}
	}
}

// guardMemory is one tick of the loop: look at the runners that are due, then
// decide for each, most pressed first, and raise what has to be raised.
func (a *Agent) guardMemory(ctx context.Context) {
	now := a.now()
	jobs := a.dueMemoryLooks(now)
	if len(jobs) == 0 {
		return
	}
	looks, failed := a.takeMemoryLooks(ctx, jobs, now)
	a.noteMemoryLookFailures(failed)
	if len(looks) == 0 {
		return
	}
	host, measured := a.hostMemory()
	a.mu.Lock()
	rules := a.memory
	a.mu.Unlock()

	// The most pressed runner is decided first: when the pool is short, what is
	// left should go to the runner nearest its kill.
	slices.SortStableFunc(looks, func(x, y memoryLook) int {
		switch px, py := x.pressure(), y.pressure(); {
		case px > py:
			return -1
		case px < py:
			return 1
		}
		// Runners as pressed as each other are served in the order of their
		// names, so that which of two a short pool leaves wanting does not depend
		// on the order the goroutines that looked at them finished in.
		return strings.Compare(x.runnerID, y.runnerID)
	})
	for _, look := range looks {
		// The containers are stored before anything is decided about them, so
		// that a raise made now is recorded on a container that is there.
		a.adoptMemoryLook(look, now)
		taken := a.decideMemory(ctx, look, rules, host, measured, now)
		if measured {
			// What a raise took is no longer free for the next decision of this
			// same tick, whose reading of the host was made before it.
			host.AvailableMB = max(host.AvailableMB-taken, 0)
		}
	}
}

// memoryJob is a runner that is due to be looked at.
type memoryJob struct {
	runnerID string
	kind     store.BackendKind
	handle   backend.Handle
	rule     ElasticMemoryRunner
	// known is what is stored of its containers, and rediscov says they are to
	// be found again rather than trusted: the loop has not found them yet, or has
	// not looked for a while.
	known    []valveContainer
	rediscov bool
	// lastLook is when the runner was last looked at, so that a climb can be
	// measured over the time it took.
	lastLook time.Time
}

// memoryLook is what one look found: the runner's containers as the daemon
// holds them now, with how much each is using.
type memoryLook struct {
	memoryJob
	containers []valveContainer
	usageMB    map[string]int64
	// err is the first container the look could not read, kept in the record at
	// the figures it last had rather than dropped from it.
	err error
}

// memoryLookFailure is a look that read nothing, and why.
type memoryLookFailure struct {
	runnerID string
	handle   backend.Handle
	err      error
}

// pressure is how close the runner's most pressed container is to its limit, as
// a share of it.
func (l memoryLook) pressure() float64 {
	worst := 0.0
	for _, c := range l.containers {
		if c.LimitMB > 0 {
			worst = max(worst, float64(l.usageMB[c.ID])/float64(c.LimitMB))
		}
	}
	return worst
}

// dueMemoryLooks picks the runners to look at this tick: those the controller
// has a rule for, that are running, and that are either close to a limit or
// have not been looked at for a few seconds.
func (a *Agent) dueMemoryLooks(now time.Time) []memoryJob {
	a.mu.Lock()
	defer a.mu.Unlock()
	if len(a.memory.runners) == 0 {
		return nil
	}
	var out []memoryJob
	for id, rule := range a.memory.runners {
		t := a.runners[id]
		if t == nil || t.valve == nil || t.terminal || t.hostRemoved || t.handle == "" || !t.phase.Live() {
			continue
		}
		v := t.valve
		if why, refused := a.memoryUnsupported[t.kind]; refused {
			// A runtime that cannot change a live limit is not asked again, and
			// the runners on it say so rather than reading as healthy.
			v.code, v.reason = MemoryUnsupported, why
			continue
		}
		if !v.hot && !v.lastLook.IsZero() && now.Sub(v.lastLook) < memoryIdleLook {
			continue
		}
		out = append(out, memoryJob{
			runnerID: id, kind: t.kind, handle: t.handle, rule: rule,
			known:    slices.Clone(v.containers),
			rediscov: len(v.containers) == 0 || now.Sub(v.discoveredAt) >= memoryRediscover,
			lastLook: v.lastLook,
		})
	}
	return out
}

// takeMemoryLooks reads the memory of every container of the due runners, a few
// at a time. A runner whose look fails is left for the next tick.
func (a *Agent) takeMemoryLooks(ctx context.Context, jobs []memoryJob, now time.Time) ([]memoryLook, []memoryLookFailure) {
	var (
		mu     sync.Mutex
		out    []memoryLook
		failed []memoryLookFailure
		wg     sync.WaitGroup
		queue  = make(chan memoryJob)
	)
	for range min(memoryWorkers, len(jobs)) {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for job := range queue {
				if ctx.Err() != nil {
					continue
				}
				look, ok, err := a.lookAtMemory(ctx, job, now)
				mu.Lock()
				switch {
				case ok:
					out = append(out, look)
				case err != nil:
					failed = append(failed, memoryLookFailure{runnerID: job.runnerID, handle: job.handle, err: err})
				}
				mu.Unlock()
			}
		}()
	}
	for _, job := range jobs {
		select {
		case queue <- job:
		case <-ctx.Done():
		}
	}
	close(queue)
	wg.Wait()
	return out, failed
}

// lookAtMemory finds a runner's containers, if they are not known, and reads
// each one's memory. The error is why a look that read nothing read nothing,
// and is nil when there was simply nothing there to read: a runner that has
// finished is an ordinary end of a job and not a failure.
func (a *Agent) lookAtMemory(ctx context.Context, job memoryJob, now time.Time) (memoryLook, bool, error) {
	b, err := a.opts.Backends.Get(job.kind)
	if err != nil {
		return memoryLook{}, false, nil
	}
	u, ok := b.(backend.MemoryUpdater)
	if !ok {
		return memoryLook{}, false, nil
	}
	lctx, cancel := context.WithTimeout(ctx, memoryLookTimeout)
	defer cancel()

	containers := job.known
	if job.rediscov {
		found, err := u.MemoryContainers(lctx, job.handle)
		if err != nil {
			if errors.Is(err, backend.ErrNotFound) {
				return memoryLook{}, false, nil
			}
			a.log.Debug("could not find a runner's containers for the memory valve", "runner", job.runnerID, "error", err)
			return memoryLook{}, false, fmt.Errorf("finding its containers: %w", err)
		}
		containers = make([]valveContainer, 0, len(found))
		for _, c := range found {
			vc := valveContainer{MemoryContainer: c, VirtualLimitMB: c.LimitMB, VirtualSwapMB: c.SwapMB}
			// Observing is a standing pretence, so what was decided before is
			// kept across a rediscovery rather than forgotten with it.
			for _, old := range job.known {
				if old.ID == c.ID {
					vc.VirtualLimitMB, vc.VirtualSwapMB = max(old.VirtualLimitMB, c.LimitMB), max(old.VirtualSwapMB, c.SwapMB)
					vc.UsageMB = old.UsageMB
				}
			}
			containers = append(containers, vc)
		}
	}
	look := memoryLook{memoryJob: job, usageMB: make(map[string]int64, len(containers))}
	for _, c := range containers {
		reading, err := u.MemoryUsage(lctx, c.ID)
		if err != nil {
			if errors.Is(err, backend.ErrNotFound) {
				continue
			}
			a.log.Debug("could not read a container's memory for the memory valve", "runner", job.runnerID, "error", err)
			if look.err == nil {
				look.err = fmt.Errorf("reading the memory of container %s: %w", shortContainer(c.ID), err)
			}
			// A container that cannot be read this time is still there, and what it
			// was lent is still lent: dropping it from the record would take its
			// loan out of the pool and its limit out of the pair's ceiling until
			// the next rediscovery. It is carried at the figures it last had.
			c.PrevUsageMB = c.UsageMB
			look.usageMB[c.ID] = c.UsageMB
			look.containers = append(look.containers, c)
			continue
		}
		look.usageMB[c.ID] = reading.UsageBytes >> 20
		c.PrevUsageMB, c.UsageMB = c.UsageMB, look.usageMB[c.ID]
		// The limit is what the daemon says it is: a limit somebody else changed
		// is read back, not fought.
		if limit := reading.LimitBytes >> 20; limit > 0 && limit != c.LimitMB {
			c.LimitMB = limit
			c.VirtualLimitMB = max(c.VirtualLimitMB, limit)
		}
		look.containers = append(look.containers, c)
	}
	if len(look.containers) == 0 {
		return memoryLook{}, false, nil
	}
	look.rediscov = job.rediscov
	return look, true, nil
}

// noteMemoryLookFailures counts the looks that read nothing against the runners
// they were of, and has a runner say so once it has gone unread for
// memoryFailedLooks looks in a row. A look that read some of a runner is
// counted by finishMemoryLook.
func (a *Agent) noteMemoryLookFailures(failed []memoryLookFailure) {
	for _, f := range failed {
		if a.countMemoryLookFailure(f.runnerID, f.handle, f.err) {
			a.log.Warn("could not read a runner's memory, so the memory valve is blind to it; it will be tried again",
				"runner", f.runnerID, "error", f.err)
		}
	}
}

// countMemoryLookFailure adds one failed look to a runner's count and reports
// whether the warning for it is due: the first time the runner has gone unread
// for this reason.
func (a *Agent) countMemoryLookFailure(runnerID string, handle backend.Handle, err error) (warn bool) {
	a.mu.Lock()
	defer a.mu.Unlock()
	t := a.runners[runnerID]
	if t == nil || t.valve == nil || t.handle != handle {
		return false
	}
	v := t.valve
	v.lookFailures++
	v.lastFailure = err.Error()
	if v.lookFailures < memoryFailedLooks {
		return false
	}
	v.code, v.reason = MemoryFailed, unreadableReason(v.lastFailure)
	if v.warned == nil {
		v.warned = map[string]bool{}
	}
	first := !v.warned[v.lastFailure]
	v.warned[v.lastFailure] = true
	return first
}

// unreadableReason is the sentence a runner gives when its containers cannot be
// read.
func unreadableReason(why string) string {
	return "its memory could not be read from the container runtime, so the valve cannot protect it: " + why
}

// hostMemory is the host's free memory and swap as it is now, and whether it
// could be read. A host that cannot be read is one nothing is lent from.
func (a *Agent) hostMemory() (machine.Memory, bool) {
	a.mu.Lock()
	infos := a.backendInfo
	a.mu.Unlock()
	_, memoryMB := hostSize(infos, a.machine())
	if a.opts.ReadMemory != nil {
		return a.opts.ReadMemory(memoryMB)
	}
	if remoteDaemon(infos) {
		// A remote daemon's memory cannot be read through this process's procfs.
		return machine.Memory{}, false
	}
	return a.usageSampler.Memory(memoryMB)
}

// decideMemory runs the guard over one runner's containers and applies, or in
// observe mode records, what it decides.
// It returns how much memory it raised limits by.
func (a *Agent) decideMemory(ctx context.Context, look memoryLook, rules memoryRules, host machine.Memory, measured bool, now time.Time) (taken int64) {
	rule := look.rule
	observing := rule.Mode == store.MemoryBurstObserve

	// Most pressed container first, so a pair's daemon, which is doing the
	// building, is not made to wait on the runner beside it.
	order := slices.Clone(look.containers)
	slices.SortStableFunc(order, func(x, y valveContainer) int {
		px, py := float64(look.usageMB[x.ID])/float64(max(x.LimitMB, 1)), float64(look.usageMB[y.ID])/float64(max(y.LimitMB, 1))
		switch {
		case px > py:
			return -1
		case px < py:
			return 1
		}
		return 0
	})

	code, reason := MemoryHealthy, ""
	hot, near := false, false
	for i := range order {
		c := &order[i]
		usage := look.usageMB[c.ID]
		limit, swap := c.LimitMB, c.SwapMB
		if observing {
			limit, swap = c.VirtualLimitMB, c.VirtualSwapMB
		}
		if float64(usage) >= memoryNearShare*float64(c.LimitMB) {
			near = true
		}
		if MemoryHot(usage, limit) || MemoryClimbing(c.PrevUsageMB, usage, limit, now.Sub(look.lastLook)) {
			hot = true
		}

		held := int64(0)
		for _, other := range order {
			if observing {
				held += other.VirtualLimitMB
			} else {
				held += other.LimitMB
			}
		}
		in := MemoryGuardInput{
			UsageMB: usage, LimitMB: limit, SwapMB: swap,
			HeldMB: held, CeilingMB: rule.CeilingMB,
			PoolMB:      a.memoryPoolMB(rules, observing),
			AvailableMB: host.AvailableMB, FloorMB: rules.floorMB, AvailableKnown: measured,
			SpillMB: rule.SpillMB, SwapFreeMB: host.SwapFreeMB, SwapKnown: measured,
			Observing: observing,
		}
		d := GuardMemory(in)
		if d.Code != MemoryHealthy {
			code, reason = d.Code, d.Reason
		}
		if !d.Changed(in) {
			continue
		}
		if observing {
			c.VirtualLimitMB, c.VirtualSwapMB = d.LimitMB, d.SwapMB
			a.setVirtual(look.runnerID, c.ID, d)
			continue
		}
		if err := a.raiseMemory(ctx, look, *c, d); err != nil {
			if errors.Is(err, backend.ErrNotFound) {
				// The runner finished between the look and the raise.
				continue
			}
			code, reason = a.memoryFailure(look, err), err.Error()
			continue
		}
		taken += d.LimitMB - c.LimitMB
		if measured {
			// The second container of a pair is decided on what the first left,
			// not on the reading the tick began with. host is this call's own copy.
			host.AvailableMB = max(host.AvailableMB-(d.LimitMB-c.LimitMB), 0)
		}
		c.LimitMB, c.SwapMB = d.LimitMB, d.SwapMB
		a.setReal(look.runnerID, c.ID, d)
	}
	a.finishMemoryLook(look, code, reason, hot, near, now)
	return taken
}

// memoryPoolMB is what the host may still lend: its capacity less what its
// runners hold. An observing runner draws on the same pool as one that acts, so
// what it would have taken is counted for observers and not for the runners
// that are really taking it.
func (a *Agent) memoryPoolMB(rules memoryRules, observing bool) int64 {
	a.mu.Lock()
	defer a.mu.Unlock()
	var lent int64
	for _, t := range a.runners {
		// A runner whose job has ended is tracked until its workload is removed,
		// and its containers hold no memory: the controller's capacity counts
		// only live runners, so counting its loan here would refuse the next
		// runner memory the host has.
		if t.valve == nil || t.terminal || t.hostRemoved {
			continue
		}
		real, _ := t.valve.lentMB()
		lent += real
		if observing && t.valve.rule != nil && t.valve.rule.Mode == store.MemoryBurstObserve {
			would, _ := t.valve.wouldLendMB()
			lent += max(would-real, 0)
		}
	}
	return max(rules.capacityMB-lent, 0)
}

// raiseMemory asks the daemon to raise one container.
func (a *Agent) raiseMemory(ctx context.Context, look memoryLook, c valveContainer, d MemoryGuardDecision) error {
	b, err := a.opts.Backends.Get(look.kind)
	if err != nil {
		return err
	}
	u, ok := b.(backend.MemoryUpdater)
	if !ok {
		return backend.ErrMemoryUpdateUnsupported
	}
	rctx, cancel := context.WithTimeout(ctx, memoryLookTimeout)
	defer cancel()
	if err := u.RaiseMemory(rctx, c.ID, d.LimitMB, d.SwapMB); err != nil {
		return err
	}
	a.log.Info("raised a runner's memory limit",
		"runner", look.runnerID, "container", shortContainer(c.ID),
		"from_mb", c.LimitMB, "to_mb", d.LimitMB, "swap_mb", d.SwapMB,
		"code", string(d.Code), "reason", d.Reason)
	return nil
}

// memoryFailure files a refused raise: a runtime with no way to do it is not
// asked again; any other refusal is logged once per reason and tried again at
// the next look. It returns the code the failure is reported under.
func (a *Agent) memoryFailure(look memoryLook, err error) MemoryValveCode {
	switch {
	case errors.Is(err, backend.ErrMemoryUpdateUnsupported):
		a.mu.Lock()
		if a.memoryUnsupported == nil {
			a.memoryUnsupported = map[store.BackendKind]string{}
		}
		_, known := a.memoryUnsupported[look.kind]
		a.memoryUnsupported[look.kind] = err.Error()
		a.mu.Unlock()
		if !known {
			a.log.Warn("this host's container runtime cannot change a live container's memory limit, so the memory valve cannot lend runners memory on it; it will not be asked again until the agent restarts",
				"backend", string(look.kind), "error", err)
		}
		return MemoryUnsupported
	}
	a.mu.Lock()
	t := a.runners[look.runnerID]
	first := false
	if t != nil && t.valve != nil {
		if t.valve.warned == nil {
			t.valve.warned = map[string]bool{}
		}
		first = !t.valve.warned[err.Error()]
		t.valve.warned[err.Error()] = true
	}
	a.mu.Unlock()
	if first {
		a.log.Warn("could not raise a runner's memory limit; it will be tried again", "runner", look.runnerID, "error", err)
	}
	return MemoryFailed
}

// setReal and setVirtual record a decision on the tracked runner's container, so
// that the next pool figure and the next report see it before the look that made
// it has finished.
func (a *Agent) setReal(runnerID, containerID string, d MemoryGuardDecision) {
	a.mu.Lock()
	defer a.mu.Unlock()
	t := a.runners[runnerID]
	if t == nil || t.valve == nil {
		return
	}
	for i := range t.valve.containers {
		if c := &t.valve.containers[i]; c.ID == containerID {
			if d.LimitMB > c.LimitMB {
				t.valve.raises++
			}
			c.LimitMB, c.SwapMB = d.LimitMB, d.SwapMB
			c.VirtualLimitMB, c.VirtualSwapMB = max(c.VirtualLimitMB, d.LimitMB), max(c.VirtualSwapMB, d.SwapMB)
		}
	}
}

func (a *Agent) setVirtual(runnerID, containerID string, d MemoryGuardDecision) {
	a.mu.Lock()
	defer a.mu.Unlock()
	t := a.runners[runnerID]
	if t == nil || t.valve == nil {
		return
	}
	for i := range t.valve.containers {
		if c := &t.valve.containers[i]; c.ID == containerID {
			c.VirtualLimitMB, c.VirtualSwapMB = d.LimitMB, d.SwapMB
		}
	}
}

// adoptMemoryLook stores the containers a look found. The guard loop is the one
// writer of them, so what it found is what is stored, with what an observing
// agent has decided carried on each container's own virtual limits.
func (a *Agent) adoptMemoryLook(look memoryLook, now time.Time) {
	a.mu.Lock()
	defer a.mu.Unlock()
	t := a.runners[look.runnerID]
	if t == nil || t.valve == nil || t.handle != look.handle {
		return
	}
	t.valve.containers = slices.Clone(look.containers)
	if look.rediscov {
		t.valve.discoveredAt = now
	}
}

// finishMemoryLook stores what a look decided: when it happened, how close the
// runner is to a limit, and the decision's code and reason.
func (a *Agent) finishMemoryLook(look memoryLook, code MemoryValveCode, reason string, hot, near bool, now time.Time) {
	a.mu.Lock()
	defer a.mu.Unlock()
	t := a.runners[look.runnerID]
	if t == nil || t.valve == nil || t.handle != look.handle {
		return
	}
	v := t.valve
	v.lastLook = now
	v.hot = hot
	v.nearLimit = v.nearLimit || near
	v.code = code
	if reason != "" {
		v.reason = reason
	}
	if look.err == nil {
		v.lookFailures, v.lastFailure = 0, ""
		return
	}
	// Some of what was looked at could not be read. It is carried, and counted;
	// a decision that says something is kept over saying it is unreadable.
	v.lookFailures++
	v.lastFailure = look.err.Error()
	if v.lookFailures >= memoryFailedLooks && code == MemoryHealthy {
		v.code, v.reason = MemoryFailed, unreadableReason(v.lastFailure)
	}
}

// remoteDaemon reports whether any container backend answers over the network.
// Its host's memory cannot be read through this process's procfs, even when the
// two machines happen to be the same size.
func remoteDaemon(infos []backend.Info) bool {
	for _, info := range infos {
		if info.Available && info.Kind != store.BackendProcess && !isLocalEndpoint(info.Endpoint) {
			return true
		}
	}
	return false
}

func isLocalEndpoint(endpoint string) bool {
	return strings.HasPrefix(endpoint, "unix://") || strings.HasPrefix(endpoint, "/")
}

func shortContainer(id string) string {
	if len(id) > 12 {
		return id[:12]
	}
	return id
}

// memoryGuardLoop wakes every tick and runs the guard.
func (a *Agent) memoryGuardLoop(ctx context.Context) error {
	t := time.NewTicker(memoryGuardTick)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return nil
		case <-t.C:
		}
		a.guardMemory(ctx)
	}
}

package agent

import (
	"context"
	"errors"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/machine"
	"github.com/eyupio/zoomies/internal/store"
)

const megabyte = int64(1) << 20

// valveBackend is a container runtime that holds memory limits, as the daemon
// does, and says what each container is using. It is a backend.Backend through
// the plain fake and a backend.MemoryUpdater through the methods below.
type valveBackend struct {
	*fakeBackend
	vmu        sync.Mutex
	containers map[backend.Handle][]backend.MemoryContainer
	usageMB    map[string]int64
	raises     []raisedLimit
	raiseErr   error
	// listErr and usageErr are the daemon failing to answer, as opposed to the
	// container having gone.
	listErr  error
	usageErr map[string]error
	// looks counts the calls made, so a test can see what a tick cost.
	listings, readings int
}

type raisedLimit struct {
	container       string
	limitMB, swapMB int64
}

func newValveBackend() *valveBackend {
	return &valveBackend{
		fakeBackend: newFakeBackend(store.BackendDocker),
		containers:  map[backend.Handle][]backend.MemoryContainer{},
		usageMB:     map[string]int64{},
	}
}

// runner puts a runner's container on the host: created with guaranteeMB and
// holding limitMB, using usageMB.
func (b *valveBackend) runner(h backend.Handle, guaranteeMB, limitMB, usageMB int64) string {
	b.vmu.Lock()
	defer b.vmu.Unlock()
	id := string(h) + "-c"
	b.containers[h] = append(b.containers[h], backend.MemoryContainer{ID: id, GuaranteeMB: guaranteeMB, LimitMB: limitMB})
	b.usageMB[id] = usageMB
	return id
}

func (b *valveBackend) sidecar(h backend.Handle, guaranteeMB, limitMB, usageMB int64) string {
	b.vmu.Lock()
	defer b.vmu.Unlock()
	id := string(h) + "-dind"
	b.containers[h] = append(b.containers[h], backend.MemoryContainer{ID: id, Daemon: true, GuaranteeMB: guaranteeMB, LimitMB: limitMB})
	b.usageMB[id] = usageMB
	return id
}

func (b *valveBackend) use(container string, usageMB int64) {
	b.vmu.Lock()
	defer b.vmu.Unlock()
	b.usageMB[container] = usageMB
}

func (b *valveBackend) limitOf(container string) (limit, swap int64) {
	b.vmu.Lock()
	defer b.vmu.Unlock()
	for _, cs := range b.containers {
		for _, c := range cs {
			if c.ID == container {
				return c.LimitMB, c.SwapMB
			}
		}
	}
	return 0, 0
}

func (b *valveBackend) raised() []raisedLimit {
	b.vmu.Lock()
	defer b.vmu.Unlock()
	return append([]raisedLimit(nil), b.raises...)
}

func (b *valveBackend) MemoryContainers(_ context.Context, h backend.Handle) ([]backend.MemoryContainer, error) {
	b.vmu.Lock()
	defer b.vmu.Unlock()
	b.listings++
	if b.listErr != nil {
		return nil, b.listErr
	}
	cs, ok := b.containers[h]
	if !ok {
		return nil, backend.ErrNotFound
	}
	return append([]backend.MemoryContainer(nil), cs...), nil
}

func (b *valveBackend) MemoryUsage(_ context.Context, container string) (backend.MemoryReading, error) {
	b.vmu.Lock()
	defer b.vmu.Unlock()
	b.readings++
	if err := b.usageErr[container]; err != nil {
		return backend.MemoryReading{}, err
	}
	usage, ok := b.usageMB[container]
	if !ok {
		return backend.MemoryReading{}, backend.ErrNotFound
	}
	for _, cs := range b.containers {
		for _, c := range cs {
			if c.ID == container {
				return backend.MemoryReading{UsageBytes: usage * megabyte, LimitBytes: c.LimitMB * megabyte}, nil
			}
		}
	}
	return backend.MemoryReading{}, backend.ErrNotFound
}

func (b *valveBackend) RaiseMemory(_ context.Context, container string, limitMB, swapMB int64) error {
	b.vmu.Lock()
	defer b.vmu.Unlock()
	if b.raiseErr != nil {
		return b.raiseErr
	}
	for h, cs := range b.containers {
		for i, c := range cs {
			if c.ID != container {
				continue
			}
			if limitMB < c.LimitMB {
				return backend.ErrMemoryLowering
			}
			b.containers[h][i].LimitMB, b.containers[h][i].SwapMB = limitMB, max(swapMB, c.SwapMB)
			b.raises = append(b.raises, raisedLimit{container, limitMB, swapMB})
			return nil
		}
	}
	return backend.ErrNotFound
}

// valveAgent is an agent over a valveBackend whose host has the memory a test
// says it has.
type valveAgent struct {
	*Agent
	be    *valveBackend
	clock *testClock
	host  *machine.Memory
	mu    sync.Mutex
}

func newValveAgent(t *testing.T) *valveAgent {
	t.Helper()
	be := newValveBackend()
	clock := newTestClock()
	v := &valveAgent{be: be, clock: clock, host: &machine.Memory{TotalMB: 16384, AvailableMB: 12000, SwapTotalMB: 4096, SwapFreeMB: 4096}}
	a, err := New(Options{
		Name: "test-host", WorkDir: t.TempDir(), Capacity: 4,
		Backends: backend.NewRegistry(be), DefaultBackend: store.BackendDocker,
		Transport: newFakeTransport(), HeartbeatInterval: time.Second,
		Logger: testLogger(), Clock: clock.Now,
		ReadMemory: func(int64) (machine.Memory, bool) {
			v.mu.Lock()
			defer v.mu.Unlock()
			if v.host == nil {
				return machine.Memory{}, false
			}
			return *v.host, true
		},
	})
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	v.Agent = a
	return v
}

func (v *valveAgent) setHost(m *machine.Memory) {
	v.mu.Lock()
	defer v.mu.Unlock()
	v.host = m
}

// run puts a runner on the host, tracked by the agent as one that is working.
// Its containers are put in the runtime by valveBackend.runner, and the
// controller's rule for it is given by tell.
func (v *valveAgent) run(id string, handle backend.Handle) {
	now := v.now()
	v.mu.Lock()
	v.Agent.mu.Lock()
	v.Agent.runners[id] = &tracked{
		runnerID: id, name: "runner-" + id, kind: store.BackendDocker, handle: handle,
		createdAt: now, state: store.RunnerBusy, phase: backend.PhaseRunning, observedAt: now,
	}
	v.Agent.mu.Unlock()
	v.mu.Unlock()
}

// tell hands the agent a heartbeat's memory rules.
func (v *valveAgent) tell(capacityMB, floorMB int64, rules ...ElasticMemoryRunner) {
	v.applyMemoryDirective(&ElasticMemoryDirective{CapacityMB: capacityMB, FloorMB: floorMB, Runners: rules})
}

// tick runs the guard once, a second after the last.
func (v *valveAgent) tick() {
	v.clock.advance(time.Second)
	v.guardMemory(context.Background())
}

func (v *valveAgent) report(id string) *backend.MemoryValveSample {
	v.Agent.mu.Lock()
	defer v.Agent.mu.Unlock()
	return v.Agent.runners[id].report().Stats.MemoryValve
}

func auto(id string, guarantee, ceiling int64) ElasticMemoryRunner {
	return ElasticMemoryRunner{RunnerID: id, Mode: store.MemoryBurstAutomatic, GuaranteeMB: guarantee, CeilingMB: ceiling}
}

// The valve's whole promise in one runner: a build that is about to pass its
// limit is given more before the kernel kills it, and the loan is counted.
func TestARunnerNearItsLimitIsLentMemoryBeforeTheKernelKillsIt(t *testing.T) {
	v := newValveAgent(t)
	c := v.be.runner("wl-a", 4096, 4096, 3300)
	v.run("run_a", "wl-a")
	v.tell(8192, 2048, auto("run_a", 4096, 6144))

	v.tick()

	if limit, _ := v.be.limitOf(c); limit != 4352 {
		t.Fatalf("limit = %d MB, want 4352: use of 3300 MB plus its margin, in whole steps", limit)
	}
	got := v.report("run_a")
	if got == nil || got.Mode != "automatic" || got.LentBytes != 256*megabyte || got.Raises != 1 || got.Code != string(MemoryRaised) {
		t.Fatalf("report = %+v, want 256 MB lent by one raise", got)
	}
	// 3300 of 4096 is 80%: tight, but not within a tenth of the limit.
	if got.NearLimit {
		t.Fatalf("report = %+v, a runner at 80%% of its limit has not come within a tenth of it", got)
	}
}

// The limit only goes up. A job that grew and then shrank keeps what it was
// lent, because lowering a live limit is what kills.
func TestALoanIsNeverTakenBackWhenUseFalls(t *testing.T) {
	v := newValveAgent(t)
	c := v.be.runner("wl-a", 4096, 4096, 3300)
	v.run("run_a", "wl-a")
	v.tell(8192, 2048, auto("run_a", 4096, 6144))
	v.tick()

	v.be.use(c, 500)
	for range 10 {
		v.tick()
	}
	if limit, _ := v.be.limitOf(c); limit != 4352 {
		t.Fatalf("limit = %d MB after use fell, want it left at 4352", limit)
	}
	if got := len(v.be.raised()); got != 1 {
		t.Fatalf("%d raises, want only the first", got)
	}
}

// A runner using a little of its limit costs the daemon a look every few
// seconds and nothing else; a hot one is looked at every second.
func TestAQuietRunnerIsLookedAtLessOftenThanAHotOne(t *testing.T) {
	v := newValveAgent(t)
	v.be.runner("wl-q", 4096, 4096, 500)
	v.be.runner("wl-h", 4096, 4096, 3000) // 73%: hot, but inside its margin
	v.run("run_q", "wl-q")
	v.run("run_h", "wl-h")
	v.tell(8192, 2048, auto("run_q", 4096, 6144), auto("run_h", 4096, 6144))

	v.tick() // first look at both
	before := v.be.readings
	for range 4 {
		v.tick()
	}
	read := v.be.readings - before
	if read != 4 {
		t.Fatalf("%d readings in four ticks, want 4: the hot runner every second and the quiet one not at all", read)
	}
	v.tick() // the fifth second after the first look
	if got := v.be.readings - before - read; got != 2 {
		t.Fatalf("%d readings on the tick the quiet runner is due, want 2", got)
	}
}

// A raise leaves a runner with a wide margin, so a few looks later it reads
// cold, but what needed the raise has not stopped. Left to the quiet interval a
// build climbing at thirty megabytes a second is a hundred and fifty late to its
// next look, which a real daemon showed: the runner was raised once and killed
// at the new limit before the guard looked again.
func TestARunnerThatIsClimbingIsLookedAtEverySecondWhateverShareOfItsLimitItUses(t *testing.T) {
	v := newValveAgent(t)
	c := v.be.runner("wl-a", 256, 256, 200)
	v.run("run_a", "wl-a")
	v.tell(8192, 2048, auto("run_a", 256, 1024))

	v.tick() // 200 of 256: raised to 384
	if limit, _ := v.be.limitOf(c); limit != 384 {
		t.Fatalf("limit = %d MB, want 384", limit)
	}

	// 60% and then 69% of the new limit: under the share that makes a runner
	// hot, and each a thirty-megabyte climb that would reach the limit in a few
	// seconds.
	for i, usage := range []int64{232, 264} {
		v.be.use(c, usage)
		before := v.be.readings
		v.tick()
		if got := v.be.readings - before; got != 1 {
			t.Fatalf("tick %d: %d readings, want the climbing runner looked at every second", i+2, got)
		}
	}
	if limit, _ := v.be.limitOf(c); limit != 384 {
		t.Fatalf("limit = %d MB, want it still inside its margin at 384", limit)
	}

	// Past its margin again, and raised again; then it stops, and is left to the
	// quiet interval like any other.
	v.be.use(c, 296)
	v.tick()
	if limit, _ := v.be.limitOf(c); limit != 512 {
		t.Fatalf("limit = %d MB, want 512", limit)
	}
	v.tick() // flat: looked at once more, and found not to be climbing
	before := v.be.readings
	for range 3 {
		v.tick()
	}
	if got := v.be.readings - before; got != 0 {
		t.Fatalf("%d readings of a runner that stopped climbing, want none until the quiet interval is up", got)
	}
}

// Observe mode is the evidence an operator reads before letting the valve move
// anything: what it would have lent, and nothing actually changes.
func TestAnObservingValveRecordsWhatItWouldHaveLentAndChangesNothing(t *testing.T) {
	v := newValveAgent(t)
	c := v.be.runner("wl-a", 4096, 4096, 3900)
	v.run("run_a", "wl-a")
	rule := auto("run_a", 4096, 6144)
	rule.Mode = store.MemoryBurstObserve
	v.tell(8192, 2048, rule)

	v.tick()

	if limit, _ := v.be.limitOf(c); limit != 4096 {
		t.Fatalf("limit = %d MB, want it untouched while observing", limit)
	}
	if len(v.be.raised()) != 0 {
		t.Fatalf("raises = %+v, want none", v.be.raised())
	}
	got := v.report("run_a")
	if got == nil || got.Mode != "observe" || got.LentBytes != 0 || got.WouldLendBytes < 1024*megabyte || !got.NearLimit {
		t.Fatalf("report = %+v, want nothing lent, over a gigabyte it would have lent, and the near-limit flag", got)
	}
	if got.Code != string(MemoryRaised) {
		t.Fatalf("code = %q, want the decision it would have made", got.Code)
	}
	if !strings.HasPrefix(got.Reason, "would have raised the limit") {
		t.Fatalf("reason = %q, want it worded as what would have been done", got.Reason)
	}
}

// An observing runner draws on the same pool as the others, so a host does not
// report that every runner on it would have taken all of what is spare.
func TestObserversShareThePoolTheyWouldHaveDrawnOn(t *testing.T) {
	v := newValveAgent(t)
	v.be.runner("wl-a", 4096, 4096, 3900)
	v.be.runner("wl-b", 4096, 4096, 3900)
	v.run("run_a", "wl-a")
	v.run("run_b", "wl-b")
	ra, rb := auto("run_a", 4096, 8192), auto("run_b", 4096, 8192)
	ra.Mode, rb.Mode = store.MemoryBurstObserve, store.MemoryBurstObserve
	v.tell(1500, 2048, ra, rb)

	v.tick()

	wa, wb := v.report("run_a").WouldLendBytes, v.report("run_b").WouldLendBytes
	if (wa+wb)/megabyte > 1500 {
		t.Fatalf("observers would have lent %d and %d MB from a pool of 1500", wa/megabyte, wb/megabyte)
	}
}

// The pool is shared. What one runner has been lent is gone for the next, the
// last of it goes to whoever is next in line, and the runner after that is told
// there is none rather than lent what is not there.
func TestWhatOneRunnerIsLentIsGoneFromThePoolForTheNext(t *testing.T) {
	v := newValveAgent(t)
	a := v.be.runner("wl-a", 4096, 4096, 3900)
	b := v.be.runner("wl-b", 4096, 4096, 3900)
	v.run("run_a", "wl-a")
	v.run("run_b", "wl-b")
	// 1500 MB between two runners that each want a gigabyte.
	v.tell(1500, 2048, auto("run_a", 4096, 8192), auto("run_b", 4096, 8192))

	v.tick()

	la, _ := v.be.limitOf(a)
	lb, _ := v.be.limitOf(b)
	if lent := (la - 4096) + (lb - 4096); lent != 1500 {
		t.Fatalf("%d MB lent (%d and %d) from a pool of 1500, want exactly all of it and no more", lent, la-4096, lb-4096)
	}

	// The first in line was served in full; the second wants more than was left
	// and is told the pool is empty on the looks that follow.
	v.tick()
	v.tick()
	if got := v.report("run_a"); got.Code != string(MemoryHealthy) {
		t.Fatalf("the runner served in full says %q, want healthy", got.Code)
	}
	if got := v.report("run_b"); got.Code != string(MemoryPoolEmpty) {
		t.Fatalf("the runner left short says %q, want pool_empty", got.Code)
	}
	la2, _ := v.be.limitOf(a)
	lb2, _ := v.be.limitOf(b)
	if la2+lb2 != la+lb {
		t.Fatalf("the pair of runners holds %d MB after more ticks, was %d: nothing is left to lend", la2+lb2, la+lb)
	}
}

// A heartbeat is thirty seconds away and the host's memory moves faster: the
// valve checks what is free at the moment of the raise, and the pool the
// controller worked out thirty seconds ago does not override it.
func TestAHostThatHasFilledUpSinceTheLastHeartbeatLendsNothing(t *testing.T) {
	v := newValveAgent(t)
	c := v.be.runner("wl-a", 4096, 4096, 3900)
	v.run("run_a", "wl-a")
	v.tell(8192, 2048, auto("run_a", 4096, 6144))
	v.setHost(&machine.Memory{TotalMB: 16384, AvailableMB: 2048}) // exactly its floor

	v.tick()

	if limit, _ := v.be.limitOf(c); limit != 4096 {
		t.Fatalf("limit = %d MB on a host at its floor, want it untouched", limit)
	}
	if got := v.report("run_a"); got.Code != string(MemoryHostFloor) {
		t.Fatalf("code = %q, want host_floor", got.Code)
	}
}

func TestARunnerOnAHostWithNoReadingOfItsMemoryIsLentNothing(t *testing.T) {
