// An explicit gate keeps the first operation in flight without wall-clock
// sleeps. synctest.Wait proves the other goroutines have reached their waits.
type startupBackend struct {
	*fakeBackend
	entered chan string
	finish  chan error
}

func (b *startupBackend) CreateWithResult(ctx context.Context, spec backend.Spec) (backend.CreateResult, error) {
	b.entered <- spec.RunnerID
	if err := <-b.finish; err != nil {
		return backend.CreateResult{}, err
	}
	return b.fakeBackend.CreateWithResult(ctx, spec)
}

func (b *startupBackend) PrewarmImage(ctx context.Context, image string, policy store.PullPolicy) (string, error) {
	b.entered <- image
	if err := <-b.finish; err != nil {
		return "", err
	}
	return b.fakeBackend.PrewarmImage(ctx, image, policy)
}

func startupAgent(t *testing.T) (*Agent, *fakeTransport, *startupBackend) {
	t.Helper()
	a, tr, be, _ := newAgent(t, 4)
	b := &startupBackend{fakeBackend: be, entered: make(chan string, 8), finish: make(chan error, 8)}
	a.opts.Backends = backend.NewRegistry(b)
	return a, tr, b
}

func startupEntered(t *testing.T, b *startupBackend, want string) {
	t.Helper()
	select {
	case got := <-b.entered:
		if got != want {
			t.Fatalf("started %q, want %q", got, want)
		}
	default:
		t.Fatalf("%q did not start", want)
	}
}

func startupBlocked(t *testing.T, b *startupBackend) {
	t.Helper()
	select {
	case got := <-b.entered:
		t.Fatalf("%q started while this host's startup slot was occupied", got)
	default:
	}
}

func TestRunnerStartsAreSerialAcrossPoolsAndReleaseAfterFailure(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		a, tr, b := startupAgent(t)
		ctx := context.Background()
		a.dispatch(ctx, createTask("first", "run-first"))
		synctest.Wait()
		startupEntered(t, b, "run-first")

		second := createTask("second", "run-second")
		second.Spec.PoolID = "another-pool"
		a.dispatch(ctx, second)
		synctest.Wait()
		startupBlocked(t, b)
		b.finish <- errors.New("daemon refused the first start")
		synctest.Wait()
		startupEntered(t, b, "run-second")
		if res := <-tr.results; res.OK {
			t.Fatal("the first failure was not reported")
		}
		b.finish <- nil
		synctest.Wait()
		if res := <-tr.results; !res.OK {
			t.Fatalf("the next start failed: %+v", res)
		}
		a.tasks.Wait()
	})
}

func dindCreateTask(id, runnerID string) Task {
	task := createTask(id, runnerID)
	task.Spec.DockerMode = store.DockerDinD
	return task
}

func TestARunnerWithoutADaemonDoesNotWaitBehindADinDStart(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		a, tr, b := startupAgent(t)
		ctx := context.Background()
		a.dispatch(ctx, dindCreateTask("dind-first", "run-dind-first"))
		synctest.Wait()
		startupEntered(t, b, "run-dind-first")

		a.dispatch(ctx, dindCreateTask("dind-second", "run-dind-second"))
		synctest.Wait()
		startupBlocked(t, b)

		plain := createTask("plain", "run-plain")
		plain.Spec.PoolID = "another-pool"
		a.dispatch(ctx, plain)
		synctest.Wait()
		startupEntered(t, b, "run-plain")
		startupBlocked(t, b)

		// Two creates are in flight and either may take the next finish, so
		// the second DinD start is counted rather than expected at a step.
		started := map[string]bool{}
		for range 3 {
			b.finish <- nil
			synctest.Wait()
			select {
			case id := <-b.entered:
				started[id] = true
			default:
			}
			if res := <-tr.results; !res.OK {
				t.Fatalf("a start failed: %+v", res)
			}
		}
		if !started["run-dind-second"] || len(started) != 1 {
			t.Fatalf("starts after the first two: %v, want only run-dind-second", started)
		}
		a.tasks.Wait()
	})
}

// The DinD lane belongs to the agent, not to a pool: two pools with a daemon
// each still initialise one daemon at a time on the host.
func TestDinDStartsAreSerialAcrossPools(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		a, tr, b := startupAgent(t)
		ctx := context.Background()
		first := dindCreateTask("dind-first", "run-dind-first")
		first.Spec.PoolID = "pool-a"
		a.dispatch(ctx, first)
		synctest.Wait()
		startupEntered(t, b, "run-dind-first")

		second := dindCreateTask("dind-second", "run-dind-second")
		second.Spec.PoolID = "pool-b"
		a.dispatch(ctx, second)
		synctest.Wait()
		startupBlocked(t, b)

		b.finish <- nil
		synctest.Wait()
		startupEntered(t, b, "run-dind-second")
		b.finish <- nil
		synctest.Wait()
		for range 2 {
			if res := <-tr.results; !res.OK {
				t.Fatalf("a start failed: %+v", res)
			}
		}
		a.tasks.Wait()
	})
}

