package agent

import (
	"context"
	"sync"
	"time"
)

// Sampling has its own bounded budget. A busy host must not spend a second per
// container in the same loop that notices exited jobs and releases disk space.
//
// A non-streaming Docker stats call takes a second at least: the daemon reads
// the cgroup twice, a second apart, to have a CPU rate to report. Two seconds
// left a loaded daemon no headroom and every sample on the host went stale
// together, which read as a fleet of idle runners.
const (
	statsInterval = 30 * time.Second
	statsBudget   = 20 * time.Second
	statsTimeout  = 5 * time.Second
	statsWorkers  = 4
	// statsMissesSaid is how many samples in a row may fail before the agent says so at Info:
	// five is two and a half minutes, which a loaded daemon can cost without anything being
	// wrong and a stuck one cannot.
	statsMissesSaid = 5
)

func (a *Agent) statsLoop(ctx context.Context) error {
	ticker := time.NewTicker(statsInterval)
	defer ticker.Stop()
	for {
		a.sampleStats(ctx)
		select {
		case <-ctx.Done():
			return nil
		case <-ticker.C:
		}
	}
}

func (a *Agent) sampleStats(ctx context.Context) {
	ctx, cancel := context.WithTimeout(ctx, statsBudget)
	defer cancel()
	jobs := make(chan tracked)
	var workers sync.WaitGroup
	for range statsWorkers {
		workers.Add(1)
		go func() {
			defer workers.Done()
			for r := range jobs {
				if ctx.Err() != nil {
					continue
				}
				b, err := a.opts.Backends.Get(r.kind)
				if err != nil {
					continue
				}
				sctx, stop := context.WithTimeout(ctx, statsTimeout)
				stats, err := b.Stats(sctx, r.handle)
				stop()
				if err != nil {
					a.log.Debug("runner stats are unavailable; retaining the last sample",
						"runner", r.runnerID, "error", err)
					a.noteStatsMiss(r)
					continue
				}
				sampledAt := a.now()
				stats.SampledAt = &sampledAt
				a.mu.Lock()
				if current := a.runners[r.runnerID]; current != nil &&
					current.handle == r.handle && !current.terminal && !current.hostRemoved {
					current.stats = stats
					current.statsMisses = 0
				}
				a.mu.Unlock()
			}
		}()
	}
send:
	for _, r := range a.trackedRunners() {
		if r.terminal || r.hostRemoved || r.handle == "" {
			continue
		}
		select {
		case jobs <- r:
		case <-ctx.Done():
			break send
		}
	}
	close(jobs)
	workers.Wait()
}

// noteStatsMiss counts a failed sample and says so once when they have run on. The failure
// itself is logged at Debug, and with the last reading retained nothing shows; but readings
// that stop coming leave the controller sizing from a stale picture, and "not enough
// samples" is all it can say for it.
func (a *Agent) noteStatsMiss(r tracked) {
	a.mu.Lock()
	current := a.runners[r.runnerID]
	if current == nil || current.handle != r.handle {
		a.mu.Unlock()
		return
	}
	current.statsMisses++
	said := current.statsMisses == statsMissesSaid
	a.mu.Unlock()
	if said {
		a.log.Info("runner stats have been unavailable for several samples in a row; the last reading is being kept, and sizing evidence for this runner is going stale",
			"runner", r.runnerID, "samples", statsMissesSaid)
	}
}

package agent

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// The agent is the side holding the evidence when a runner dies: by the time
// the controller hears of it, the container is about to be removed and its
// output with it. A faulted exit therefore travels with its last lines, so
// the explanation of the job can quote the line that decided it; a clean
// exit carries none, because there is nothing to explain.
func TestAFaultedRunnerReportCarriesItsLastLines(t *testing.T) {
	a, _, be, _ := newAgent(t, 2)
	a.polled.Store(true)
	var out bytes.Buffer
	for i := 1; i <= 60; i++ {
		fmt.Fprintf(&out, "line %d\n", i)
	}
	be.mu.Lock()
	be.logs = func() io.ReadCloser { return io.NopCloser(bytes.NewReader(out.Bytes())) }
	be.mu.Unlock()

	track(a, "runner-1", "wl-1", true)
	be.setWorkloads(exited("wl-1", "runner-1", 137))
	reports, err := a.ReconcileOnce(context.Background())
	if err != nil {
		t.Fatalf("ReconcileOnce: %v", err)
	}
	if len(reports) != 1 || reports[0].State != store.RunnerFailed {
		t.Fatalf("reports = %+v, want one failed", reports)
	}
	tail := reports[0].OutputTail
	if len(tail) != outputTailLines || tail[0] != "line 21" || tail[len(tail)-1] != "line 60" {
		t.Fatalf("tail = %d lines, first %q, last %q; want the last %d", len(tail), first(tail), last(tail), outputTailLines)
	}

	track(a, "runner-2", "wl-2", true)
	be.setWorkloads(exited("wl-2", "runner-2", 0))
	reports, err = a.ReconcileOnce(context.Background())
	if err != nil {
		t.Fatalf("ReconcileOnce: %v", err)
	}
	for _, r := range reports {
		if r.RunnerID == "runner-2" && len(r.OutputTail) != 0 {
			t.Fatalf("a clean exit carries no tail: %+v", strings.Join(r.OutputTail, "|"))
		}
	}
}

func first(s []string) string {
	if len(s) == 0 {
		return ""
	}
	return s[0]
}

func last(s []string) string {
	if len(s) == 0 {
		return ""
	}
	return s[len(s)-1]
}

package agent

import (
	"context"
	"errors"
	"net"
	"net/http"
	"strings"
	"sync"

	"github.com/tailscale/tailcat"
)

// TailcatController is deliberately not an address: the actual capability is
// kept alongside the agent token in the mode-0600 credentials file.
const TailcatController = "tailcat://controller"

// DisplayController is safe for banners and errors, including malformed input.
func DisplayController(raw string) string {
	if strings.HasPrefix(strings.ToLower(raw), "tailcat:") {
		return TailcatController
	}
	return raw
}

func newTailcatTransport(opts HTTPOptions) (*HTTPTransport, error) {
	_, address, ok := strings.Cut(opts.ControllerURL, "://")
	if !ok {
		return nil, errors.New("agent: invalid private connection URL; copy the complete enrolment command again")
	}
	if address == "controller" {
		address = opts.TailcatAddress
	}
	if !strings.HasPrefix(address, "tc") {
		return nil, errors.New("agent: no private connection address; re-join using a fresh command from Add a host")
	}
	info, err := tailcat.ParseAddr(tailcat.Addr(address))
	if err != nil || info.PresharedKey.IsZero() {
		return nil, errors.New("agent: invalid private connection address; copy the complete Tailcat enrolment command again")
	}
	client := tailcat.NewClient(tailcat.Addr(address))
	// Upstream diagnostics may contain capability addresses. Only our own
	// errors, which never include those addresses, go to operator logs.
	client.Logf = func(string, ...any) {}
	ht := &http.Transport{
		DialContext: func(ctx context.Context, _, _ string) (net.Conn, error) {
			conn, err := dialTailcat(ctx, client)
			if err != nil {
				if ctx.Err() != nil {
					return nil, ctx.Err()
				}
				return nil, ErrRetryable
			}
			return conn, nil
		},
		// A connection through the tunnel is a WireGuard peer-to-peer flow, not
		// a real TCP socket: when the controller restarts and forgets its
		// peers, nothing here ever sends a FIN, so a pooled idle connection
		// looks perfectly healthy to net/http and gets reused into a silent
		// hang instead of a dial. Dialling fresh every call is what makes
		// dialTailcat's re-announcement below run often enough to matter.
		DisableKeepAlives: true,
	}
	// This synthetic origin never resolves or leaves the process. Every socket
	// is opened by Tailcat; proxies and redirects cannot reroute credentials.
	transport, err := NewHTTPTransport(HTTPOptions{
		ControllerURL: "http://127.0.0.1",
		HTTPClient:    &http.Client{Transport: ht, CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }},
		Logger:        opts.Logger,
	})
	if err != nil {
		_ = client.Close()
		return nil, err
	}
	transport.tailcatAddress = address
	var once sync.Once
	transport.closeTunnel = func() { once.Do(func() { ht.CloseIdleConnections(); _ = client.Close() }) }
	return transport, nil
}

// dialTailcat re-announces this client to the server before every dial.
//
// Client.DialTCPPort only does that once per Client, ever: it is right for a
// single short-lived connection, and wrong for an agent that reuses the same
// Client for as long as it runs. The server's record of which clients have
// introduced themselves lives only in that process's memory, so a controller
// restart forgets every one of them while keeping the same persisted
// address -- and a client that never repeats the introduction can dial
// forever against a server that silently drops its packets, because nothing
// about a dropped WireGuard peer looks like an error to wait out. Ping
// repeats it unconditionally, and it is a no-op on the server's side when
// the peer is already known, so paying for it on every dial is what lets a
// private host recover from a controller restart on its own.
func dialTailcat(ctx context.Context, client *tailcat.Client) (net.Conn, error) {
	if _, err := client.Ping(ctx); err != nil {
		return nil, err
	}
	return client.DialTCPPort(ctx, 80)
}

// Close releases the userspace network stack after daemon or enrolment shutdown.
func (t *HTTPTransport) Close() {
	if t.closeTunnel != nil {
		t.closeTunnel()
	}
}

func (t *HTTPTransport) TailcatAddress() string { return t.tailcatAddress }

package agent

import (
	"net/http"
	"strings"
	"testing"

	"github.com/tailscale/tailcat"
)

func TestPrivateConnectionErrorsNeverContainTheAddress(t *testing.T) {
	for _, address := range []string{"tc-secret-not-valid", "controller", "tc%zz-secret"} {
		_, err := NewHTTPTransport(HTTPOptions{ControllerURL: "TAILCAT://" + address})
		if err == nil {
			t.Fatal("invalid address accepted")
		}
		if strings.Contains(err.Error(), address) {
			t.Fatalf("address leaked: %s", err)
		}
	}
}

func TestPrivateTransportUsesNoProxyAndKeepsCapabilityOutOfDescription(t *testing.T) {
	key := tailcat.NewPrivateKey()
	key.Public.RegionID = 1
	address := string(key.Public.Addr())
	tr, err := NewHTTPTransport(HTTPOptions{ControllerURL: "tailcat://" + address})
	if err != nil {
		t.Fatal(err)
	}
	defer tr.Close()
	if tr.Describe() != TailcatController || tr.TailcatAddress() != address {
		t.Fatal("capability and display address were not separated")
	}
	httpTransport := tr.http.Transport.(*http.Transport)
	if httpTransport.Proxy != nil {
		t.Fatal("proxy can intercept private agent requests")
	}
	if err := tr.http.CheckRedirect(nil, nil); err != http.ErrUseLastResponse {
		t.Fatal("private requests may follow redirects")
	}
	path := StatePath(t.TempDir())
	if err := Save(path, Credentials{HostID: "host_test", AgentToken: "token", Controller: tr.Describe(), TailcatAddress: address}); err != nil {
		t.Fatal(err)
	}
	saved, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	restarted, err := NewHTTPTransport(HTTPOptions{ControllerURL: saved.Controller, TailcatAddress: saved.TailcatAddress})
	if err != nil {
		t.Fatal(err)
	}
	defer restarted.Close()
	if restarted.TailcatAddress() != address {
		t.Fatal("restart lost the private connection")
	}
}

