	"math"
	"sort"
	"time"

	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
)

// applyResourceDirectives atomically replaces the host-pressure and elastic
// decisions from one heartbeat, then reconciles each live workload once. The
// pressure factor wins when it is below one; elasticity is never allowed to
// fight the protection that keeps an overloaded host alive.
//
// A nil throttle is an older controller, and it is left alone rather than
// read as "restore everything": that controller never throttled anything, and
// reconciling every adopted runner against it would be a request per runner
// for nothing. The one exception is a factor that was standing when the nil
// arrived -- a downgraded controller -- which is restored, because a throttle
// nobody will ever lift is a job slowed for ever.
func (a *Agent) applyResourceDirectives(ctx context.Context, d *ThrottleDirective, elastic []ElasticCPUDirective) {
	factor := 1.0
	if d != nil && d.CPUFactor > 0 {
		factor = d.CPUFactor
	}
	next := make(map[string]float64, len(elastic))
	for _, directive := range elastic {
		if directive.RunnerID != "" && directive.CPUFactor > 1 {
			next[directive.RunnerID] = directive.CPUFactor
		}
	}
	a.mu.Lock()
	changed := a.cpuFactor != factor || !maps.Equal(a.elasticCPU, next)
	a.cpuFactor = factor
	a.elasticCPU = next
	a.boostRenewedAt = time.Now()
	a.mu.Unlock()
	if d == nil && !changed {
		return
	}
	if changed {
		level := 0
		if d != nil {
			level = d.Level
		}
		a.log.Debug("throttle directive changed", "level", level, "cpu_factor", factor)
	}
	a.applyThrottle(ctx, changed)
}

// boostExpiryMisses is how many normal heartbeat intervals a boost may go
// without renewal.
const boostExpiryMisses = 3

// expireBoosts checks overdue CPU loans after unanswered heartbeats.
//
// A boost is lent on the controller's say-so, from what it judged the host
// could spare, and is only ever withdrawn by the next plan. With the controller
// down or unreachable no plan comes: the boost stays whatever the host is doing
// now, and the throttle that would rein it in is the controller's too. A few
// missed beats is a restart; more is a controller that is not coming back soon,
// and the runners go back to the guarantee they were created with. A throttle
// standing when the controller went away is left alone -- it is the safe
// direction to be wrong in, and the controller lifts it when it returns.
func (a *Agent) expireBoosts(ctx context.Context) {
	a.mu.Lock()
	a.missedBeats++
	// A quick retry is another attempt, not another normal interval of
	// silence. Keep the same time lease as the independent watchdog so a
	// short controller restart does not take a running job's borrowed CPU.
	expire := a.missedBeats >= boostExpiryMisses &&
		!a.boostRenewedAt.IsZero() && time.Since(a.boostRenewedAt) >= boostExpiryMisses*a.heartbtI
	hadBoost := len(a.elasticCPU) > 0
	if expire {
		a.elasticCPU = map[string]float64{}
	}
	a.mu.Unlock()
	if !expire {
		return
	}
	if hadBoost {
		a.log.Warn("the controller has missed several heartbeats; giving back the CPU it lent this host's runners",
			"missed", boostExpiryMisses)
	}
	a.applyThrottle(ctx, true)
}

// applyThrottle brings every live runner's CPU quota to the standing factor.
//
// It is the one lever a host has left once every runner on it is busy: a
// smaller effective capacity only reaches new work, and the jobs already
// running are what is overwhelming the machine. The backend's update is
// idempotent, so a runner whose applied factor is unknown -- one adopted
// after a restart -- costs an inspect and no more when it already matches.
//
// Nothing here can fail a task or the heartbeat. A daemon that refuses --
// Podman without the endpoint, a rootless daemon that cannot set a quota --
// is logged once per runner per factor and tried again on the next beat, so
// a daemon that recovers is not waited on by anything but time.
func (a *Agent) applyThrottle(ctx context.Context, announce bool) {
	type candidate struct {
		runnerID  string
		handle    backend.Handle
		updater   backend.ResourceUpdater
		res       store.Resources
		warned    bool
		factor    float64
		reduction bool
	}
	a.mu.Lock()
	hostFactor := a.cpuFactor
	now := a.now()
	var todo []candidate
	reclaimPending := false
	for _, r := range a.runners {
		factor := 1.0
		if elastic := a.elasticCPU[r.runnerID]; elastic > 1 {
			factor = elastic
		}
		if hostFactor < 1 {
			factor = hostFactor
		}
		// Container-running is not GitHub-ready. Keep its existing quota
		// during a bounded grace rather than further starving registration.
		if factor < 1 && !r.createdAt.IsZero() && a.opts.BootstrapCPUGrace > 0 && now.Sub(r.createdAt) < a.opts.BootstrapCPUGrace {
			factor = 1
		}
		if r.terminal || r.hostRemoved || !r.phase.Live() || r.resources.CPUs <= 0 {
			// A runner with no CPU limit has no quota to scale; it is the
			// controller's business to say so through its host problems.
			continue
		}
		// Serialise updates even if the grace expires while one is in
		// flight: an older response must not overwrite a newer quota.
		// The next heartbeat reconciles the standing factor.
		if r.pendingCPUFactor != nil {
			reclaimPending = true
			continue
		}
		if r.appliedCPUFactor != nil && *r.appliedCPUFactor == factor {
			continue
		}
		b, err := a.opts.Backends.Get(r.kind)
		if err != nil {
			continue
		}
		u, ok := b.(backend.ResourceUpdater)
		if !ok {
			continue
		}
		res := r.resources
		// A restore sends the base exactly as the container was created with,
		// so a pool's own figure is never rounded up over its own limit; a
		// changed figure is rounded to hundredths, the daemon's granularity for
		// --cpus, so the quota the backend compares against is one it could
		// have written.
		if factor != 1 {
			res.CPUs = math.Round(res.CPUs*factor*100) / 100
		}
		f := factor
		r.pendingCPUFactor = &f
		todo = append(todo, candidate{
			runnerID: r.runnerID, handle: r.handle, updater: u, res: res,
			factor:    factor,
			reduction: factor <= 1 || r.appliedCPUFactor == nil || factor < *r.appliedCPUFactor,
			warned:    r.failedCPUFactor != nil && *r.failedCPUFactor == factor,
		})
	}
	a.mu.Unlock()

	if announce {
		switch {
		case len(todo) == 0 && hostFactor < 1:
			a.log.Info("the controller throttled this host; no runner needs a quota update yet (new runners keep their allocation during startup grace)",
				"cpu_factor", hostFactor)
		case hostFactor < 1:
			a.log.Info(fmt.Sprintf("throttling %d runners to %d%% of their CPU allocation", len(todo), int(math.Round(hostFactor*100))))
		case len(todo) > 0:
			boosted := 0
			for _, c := range todo {
				if c.factor > 1 {
					boosted++
				}
			}
			if boosted > 0 {
				a.log.Info(fmt.Sprintf("adjusting elastic CPU for %d runners", boosted))
			} else {
				a.log.Info(fmt.Sprintf("restoring %d runners to their full CPU allocation", len(todo)))
			}
		}
	}

	sort.SliceStable(todo, func(i, j int) bool { return todo[i].reduction && !todo[j].reduction })
	reclaimFailed := reclaimPending
	for _, c := range todo {
		if reclaimFailed && !c.reduction {
			a.mu.Lock()
			if r := a.runners[c.runnerID]; r != nil {
				r.pendingCPUFactor = nil
			}
			a.mu.Unlock()
			continue
		}
		factor := c.factor
		err := c.updater.UpdateResources(ctx, c.handle, c.res)
		if c.reduction && err != nil && !errors.Is(err, backend.ErrNotFound) {
			reclaimFailed = true
		}
		a.mu.Lock()
		r, ok := a.runners[c.runnerID]
		if ok {
			// Claimed above and released here whatever happened, so a refusal
			// is retried on the next beat rather than held off for ever by a
			// marker nothing clears.
			if r.pendingCPUFactor != nil && *r.pendingCPUFactor == factor {
				r.pendingCPUFactor = nil
			}
			switch {
			case err == nil:
				f := factor
				r.appliedCPUFactor = &f
				r.failedCPUFactor = nil
			case errors.Is(err, backend.ErrNotFound):
				// Finished between the beat and the update; the reconciler
				// will say so, and there is nothing left to throttle.
			default:
				f := factor
				r.failedCPUFactor = &f
			}
		}
		a.mu.Unlock()
		switch {
		case err == nil:
			a.log.Debug("runner CPU quota set", "runner", c.runnerID, "handle", c.handle, "cpus", c.res.CPUs, "cpu_factor", factor)
		case errors.Is(err, backend.ErrNotFound):
			a.log.Debug("runner was gone before its CPU quota could be changed", "runner", c.runnerID, "handle", c.handle)
		case c.warned:
			a.log.Debug("runner CPU quota still could not be changed", "runner", c.runnerID, "handle", c.handle, "error", err)
		default:
			a.log.Warn("could not change a runner's CPU quota; its job continues at its full allocation and the change will be retried on the next heartbeat",
				"runner", c.runnerID, "handle", c.handle, "cpus", c.res.CPUs, "cpu_factor", factor, "error", err)
		}
	}
}

// Independent of heartbeat completion. time.Now retains its monotonic reading,
// so a wall-clock adjustment cannot extend a CPU loan. Backend updates have a
// separate deadline; a failed withdrawal is tried again on the next tick.
func (a *Agent) boostExpiryLoop(ctx context.Context) error {
	interval := min(a.heartbtI, 5*time.Second)
	if interval <= 0 {
		interval = time.Second
	}
	t := time.NewTicker(interval)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return nil
		case <-t.C:
			work, cancel := context.WithTimeout(ctx, 5*time.Second)
			a.expireBoostLease(work, time.Now())
			cancel()
		}
	}
}
func (a *Agent) expireBoostLease(ctx context.Context, now time.Time) {
	a.mu.Lock()
	expired := !a.boostRenewedAt.IsZero() && now.Sub(a.boostRenewedAt) >= boostExpiryMisses*a.heartbtI
	if expired {
		a.elasticCPU = map[string]float64{}
	}
	a.mu.Unlock()
	if expired {
		a.applyThrottle(ctx, false)
	}
}

package agent

import (
	"bytes"
	"context"
	"errors"
	"log/slog"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
)

// createdRunner puts a runner in the tracked set the way handleCreate does,
// without a task round trip: created with these resources, at its full
// allocation.
func createdRunner(a *Agent, runnerID string, handle backend.Handle, res store.Resources) {
	now := a.now()
	a.mu.Lock()
	defer a.mu.Unlock()
	a.runners[runnerID] = &tracked{
		runnerID: runnerID, name: "runner-" + runnerID, kind: store.BackendDocker, handle: handle,
		createdAt: now, state: store.RunnerRegistering, phase: backend.PhaseRunning, observedAt: now,
		resources: res, appliedCPUFactor: new(float64(1)),
	}
}

// beat answers one heartbeat with the given throttle and returns the calls
// the backend received during it.
func beat(t *testing.T, a *Agent, tr *fakeTransport, be *fakeBackend, d *ThrottleDirective, elastic ...ElasticCPUDirective) []resourceUpdate {
	t.Helper()
	tr.mu.Lock()
	tr.beatResp = &HeartbeatResponse{OK: true, Throttle: d, ElasticCPU: elastic}
	tr.mu.Unlock()
	before := len(be.resourceUpdates())
	if err := a.heartbeat(context.Background()); err != nil {
		t.Fatalf("heartbeat: %v", err)
	}
	return be.resourceUpdates()[before:]
}

func TestElasticCPUBoostsAndThenRestoresARunner(t *testing.T) {
	a, tr, be, _ := newAgent(t, 4)
	createdRunner(a, "run_a", "wl-a", store.Resources{CPUs: 2, MemoryMB: 4096})

	got := beat(t, a, tr, be, &ThrottleDirective{CPUFactor: 1}, ElasticCPUDirective{
		RunnerID: "run_a", CPUFactor: 2, BaseCPUs: 2, TargetCPUs: 4,
	})
	if len(got) != 1 || got[0].res.CPUs != 4 || got[0].res.MemoryMB != 4096 {
		t.Fatalf("updates = %+v, want the CPU quota raised to 4 and memory unchanged", got)
	}

	got = beat(t, a, tr, be, &ThrottleDirective{CPUFactor: 1})
	if len(got) != 1 || got[0].res.CPUs != 2 {
		t.Fatalf("updates = %+v, want the runner restored to its 2 CPU guarantee", got)
	}
}

func TestHostPressureWinsOverElasticCPU(t *testing.T) {
	a, tr, be, _ := newAgent(t, 4)
	createdRunner(a, "run_a", "wl-a", store.Resources{CPUs: 2})
	a.opts.BootstrapCPUGrace = 0

	got := beat(t, a, tr, be, &ThrottleDirective{Level: 2, CPUFactor: 0.5}, ElasticCPUDirective{
		RunnerID: "run_a", CPUFactor: 2, BaseCPUs: 2, TargetCPUs: 4,
	})
	if len(got) != 1 || got[0].res.CPUs != 1 {
		t.Fatalf("updates = %+v, want pressure to tighten the runner to 1 CPU", got)
	}
}

// Once every runner on an overwhelmed host is busy, the effective capacity
// reaches nothing: the jobs already running are what is overwhelming it. The
// directive has to reach each of them, once, and the same directive on the
// next beat must cost the daemon nothing.
func TestAThrottleDirectiveReducesEachLimitedRunnerOnceAndNotAgainOnTheSameBeat(t *testing.T) {
	a, tr, be, _ := newAgent(t, 4)
	createdRunner(a, "run_a", "wl-a", store.Resources{CPUs: 2, MemoryMB: 4096, PidsLimit: 512})
	createdRunner(a, "run_b", "wl-b", store.Resources{CPUs: 0.75, MemoryMB: 1900})

	got := beat(t, a, tr, be, &ThrottleDirective{Level: 2, CPUFactor: 0.5})
	if len(got) != 2 {
		t.Fatalf("updates = %+v, want one per limited runner", got)
	}
	want := map[backend.Handle]store.Resources{
		"wl-a": {CPUs: 1, MemoryMB: 4096, PidsLimit: 512},
		// 0.375 is not a quota the daemon or the pool field speaks in.
		"wl-b": {CPUs: 0.38, MemoryMB: 1900},
	}
	for _, u := range got {
		if u.res != want[u.handle] {
			t.Errorf("%s was given %+v, want %+v: the base scaled by the factor, everything else as created", u.handle, u.res, want[u.handle])
		}
	}

	if again := beat(t, a, tr, be, &ThrottleDirective{Level: 2, CPUFactor: 0.5}); len(again) != 0 {
		t.Fatalf("the same directive was applied again on the next beat: %+v", again)
	}
	if lower := beat(t, a, tr, be, &ThrottleDirective{Level: 3, CPUFactor: 0.5}); len(lower) != 0 {
		t.Fatalf("a step that keeps the same factor was applied again: %+v", lower)
	}
}

// A throttle that never lifts is a job slowed for ever. A factor of 1 is the
// controller saying the host is calm, and every throttled runner goes back to
// what it was created with.
func TestAFactorOfOneRestoresEveryThrottledRunner(t *testing.T) {
	a, tr, be, _ := newAgent(t, 4)
	createdRunner(a, "run_a", "wl-a", store.Resources{CPUs: 2})
	beat(t, a, tr, be, &ThrottleDirective{Level: 1, CPUFactor: 0.75})

	got := beat(t, a, tr, be, &ThrottleDirective{Level: 0, CPUFactor: 1})
	if len(got) != 1 || got[0].handle != "wl-a" || got[0].res.CPUs != 2 {
		t.Fatalf("updates = %+v, want wl-a restored to 2 CPUs", got)
	}
	// A directive with no factor at all is a controller that has cleared the
	// throttle without saying so in numbers, and reads the same way.
	beat(t, a, tr, be, &ThrottleDirective{Level: 1, CPUFactor: 0.5})
	if got := beat(t, a, tr, be, &ThrottleDirective{}); len(got) != 1 || got[0].res.CPUs != 2 {
		t.Fatalf("updates = %+v, want a zero factor read as full allocation", got)
	}
}

// A runner with no CPU limit -- defaults off, or a row from before they
// existed -- has no quota to scale. Asking the daemon to set one would be a
// new limit rather than a throttle, and it is the controller's problem panel
// that says such runners exist.
func TestARunnerWithNoCPULimitIsLeftAlone(t *testing.T) {
	a, tr, be, _ := newAgent(t, 4)
	createdRunner(a, "run_unlimited", "wl-u", store.Resources{MemoryMB: 4096})
	createdRunner(a, "run_limited", "wl-l", store.Resources{CPUs: 1})

	got := beat(t, a, tr, be, &ThrottleDirective{Level: 2, CPUFactor: 0.5})
	if len(got) != 1 || got[0].handle != "wl-l" {
		t.Fatalf("updates = %+v, want only the limited runner touched", got)
	}
}

// An adopted runner was made by an agent that may have throttled it and then
// died, and this agent has no record either way. Its base comes from the
// workload's labels, and it is reconciled on the first beat whichever way the
// controller says -- the backend's update costs nothing when it already
// matches, so the safe direction is to ask.
func TestAnAdoptedRunnerIsReconciledOnTheFirstBeat(t *testing.T) {
	a, tr, be, _ := newAgent(t, 4)
	be.setWorkloads(backend.Workload{
		Handle: "wl-old", Name: "runner-old", RunnerID: "run_old",
		Status:    backend.Status{Phase: backend.PhaseRunning, StartedAt: time.Now().Add(-time.Hour)},
		Resources: store.Resources{CPUs: 4, MemoryMB: 8192},
	})
	a.adoptExisting(context.Background())

	got := beat(t, a, tr, be, &ThrottleDirective{Level: 0, CPUFactor: 1})
	if len(got) != 1 || got[0].handle != "wl-old" || got[0].res != (store.Resources{CPUs: 4, MemoryMB: 8192}) {
		t.Fatalf("updates = %+v, want the adopted runner reconciled to its labelled allocation", got)
	}
	if again := beat(t, a, tr, be, &ThrottleDirective{Level: 0, CPUFactor: 1}); len(again) != 0 {
		t.Fatalf("once reconciled the runner was asked about again: %+v", again)
	}
	// And a standing throttle reaches it the same way.
	if got := beat(t, a, tr, be, &ThrottleDirective{Level: 2, CPUFactor: 0.5}); len(got) != 1 || got[0].res.CPUs != 2 {
		t.Fatalf("updates = %+v, want the adopted runner throttled from its labelled base", got)
	}
}

// An older controller sends no directive. It never throttled anything, so
// there is nothing to restore, and reconciling every adopted runner against
// a controller that will never ask for it is a request per runner for nothing.
func TestANilDirectiveFromAnOlderControllerTouchesNothing(t *testing.T) {
	a, tr, be, _ := newAgent(t, 4)
	createdRunner(a, "run_a", "wl-a", store.Resources{CPUs: 2})
	be.setWorkloads(backend.Workload{
		Handle: "wl-old", Name: "runner-old", RunnerID: "run_old",
		Status:    backend.Status{Phase: backend.PhaseRunning, StartedAt: time.Now().Add(-time.Hour)},
		Resources: store.Resources{CPUs: 4},
	})
	a.adoptExisting(context.Background())

	if got := beat(t, a, tr, be, nil); len(got) != 0 {
		t.Fatalf("an older controller's beat changed quotas: %+v", got)
	}
}

// A controller downgraded under a standing throttle would otherwise leave
// every runner slowed for ever: the nil it now sends is the one nil that has
// to mean "restore".
func TestANilDirectiveAfterAThrottleRestoresTheRunners(t *testing.T) {
	a, tr, be, _ := newAgent(t, 4)
	createdRunner(a, "run_a", "wl-a", store.Resources{CPUs: 2})
	beat(t, a, tr, be, &ThrottleDirective{Level: 2, CPUFactor: 0.5})

	got := beat(t, a, tr, be, nil)
	if len(got) != 1 || got[0].res.CPUs != 2 {
		t.Fatalf("updates = %+v, want the runner restored", got)
	}
}

// A daemon that refuses -- Podman without the endpoint, a rootless daemon
// that cannot set a quota -- must not fail the beat that carries the host's
// runners, and must not say so on every one of them either: one line per
// runner per factor is what an operator can read.
func TestARefusedUpdateIsLoggedOnceAndDoesNotBreakTheHeartbeat(t *testing.T) {
	a, tr, be, _ := newAgent(t, 4)
	var logs lockedBuffer
	a.log = slog.New(slog.NewTextHandler(&logs, &slog.HandlerOptions{Level: slog.LevelDebug}))
	createdRunner(a, "run_a", "wl-a", store.Resources{CPUs: 2})
	be.mu.Lock()
	be.updateErr = errors.New("the daemon does not support updating a running container")
	be.mu.Unlock()

	for range 3 {
		beat(t, a, tr, be, &ThrottleDirective{Level: 2, CPUFactor: 0.5})
	}
	if n := strings.Count(logs.String(), "level=WARN msg=\"could not change a runner's CPU quota"); n != 1 {
		t.Fatalf("the refusal was warned about %d times over three beats, want once:\n%s", n, logs.String())
	}
	if !strings.Contains(logs.String(), "throttling 1 runners to 50% of their CPU allocation") {
		t.Fatalf("the throttle was not announced:\n%s", logs.String())
	}

	// A different factor is a different refusal, worth its own line.
	beat(t, a, tr, be, &ThrottleDirective{Level: 1, CPUFactor: 0.75})
	if n := strings.Count(logs.String(), "level=WARN msg=\"could not change a runner's CPU quota"); n != 2 {
		t.Fatalf("a refusal at a new factor was not logged, %d warnings:\n%s", n, logs.String())
	}

	// The runner was never moved off its full allocation, so a factor of 1
	// has nothing to restore and must not pretend otherwise.
	beat(t, a, tr, be, &ThrottleDirective{Level: 0, CPUFactor: 1})
	if strings.Contains(logs.String(), "restoring") {
		t.Fatalf("a runner still at its full allocation was announced as restored:\n%s", logs.String())
	}

	// Once the daemon recovers the retry lands.
	be.mu.Lock()
	be.updateErr = nil
	be.mu.Unlock()
	if got := beat(t, a, tr, be, &ThrottleDirective{Level: 2, CPUFactor: 0.5}); len(got) != 1 || got[0].res.CPUs != 1 {
		t.Fatalf("updates = %+v, want the retry to land once the daemon answers", got)
	}
	if got := beat(t, a, tr, be, &ThrottleDirective{Level: 0, CPUFactor: 1}); len(got) != 1 || got[0].res.CPUs != 2 {
		t.Fatalf("updates = %+v, want the runner restored now that it really was throttled", got)
	}
}

// A runner created while the host is throttled comes up at its full
// allocation, and on an overwhelmed host that is one more full-speed job
// until the next beat. It is throttled as soon as it exists.
func TestARunnerCreatedUnderAThrottleIsThrottledAtOnce(t *testing.T) {
	h := newHarness(t, 2)
	h.tr.mu.Lock()
	h.tr.beatResp = &HeartbeatResponse{OK: true, Throttle: &ThrottleDirective{Level: 2, CPUFactor: 0.5}}
	h.tr.mu.Unlock()
	if err := h.agent.heartbeat(context.Background()); err != nil {
		t.Fatalf("heartbeat: %v", err)
	}

	task := createTask("task-1", "runner-1")
	task.Spec.Resources = store.Resources{CPUs: 2, MemoryMB: 2048}
	h.tr.tasks <- []Task{task}
	res := h.nextResult()
	if !res.OK {
		t.Fatalf("create failed: %+v", res)
	}
	got := h.be.resourceUpdates()
	if len(got) != 1 || got[0].handle != res.Handle || got[0].res != (store.Resources{CPUs: 1, MemoryMB: 2048}) {
		t.Fatalf("updates = %+v, want the new runner throttled to half before its result was reported", got)
	}
}

// A runner created while nothing is throttled already has its full
// allocation; asking the daemon to confirm that on the next beat would be a
// request per create for nothing.
func TestARunnerCreatedWithoutAThrottleIsNotAskedAboutOnTheNextBeat(t *testing.T) {
	h := newHarness(t, 2)
	task := createTask("task-1", "runner-1")
	task.Spec.Resources = store.Resources{CPUs: 2}
	h.tr.tasks <- []Task{task}
	h.nextResult()

	h.tr.mu.Lock()
	h.tr.beatResp = &HeartbeatResponse{OK: true, Throttle: &ThrottleDirective{Level: 0, CPUFactor: 1}}
	h.tr.mu.Unlock()
	if err := h.agent.heartbeat(context.Background()); err != nil {
		t.Fatalf("heartbeat: %v", err)
	}
	if got := h.be.resourceUpdates(); len(got) != 0 {
		t.Fatalf("updates = %+v, want none for a runner created at its full allocation", got)
	}
}

// A finished runner has nothing left to throttle, and a runner the backend
// no longer has is not a refusal: neither is worth a warning or a retry.
func TestFinishedAndGoneRunnersAreNotThrottled(t *testing.T) {
	a, tr, be, _ := newAgent(t, 4)
	var logs lockedBuffer
	a.log = slog.New(slog.NewTextHandler(&logs, nil))
	createdRunner(a, "run_done", "wl-done", store.Resources{CPUs: 2})
	a.markTerminal("run_done", store.RunnerRemoved, backend.PhaseExited, 0, "done", "", a.now())
	createdRunner(a, "run_gone", "wl-gone", store.Resources{CPUs: 2})
	be.mu.Lock()
	be.updateErr = backend.ErrNotFound
	be.mu.Unlock()

	if got := beat(t, a, tr, be, &ThrottleDirective{Level: 2, CPUFactor: 0.5}); len(got) != 0 {
		t.Fatalf("updates = %+v", got)
	}
	if strings.Contains(logs.String(), "level=WARN") {
		t.Fatalf("a gone runner was warned about:\n%s", logs.String())
	}
}

// lockedBuffer is a bytes.Buffer a logger can write from any goroutine.
type lockedBuffer struct {
	mu  sync.Mutex
	buf bytes.Buffer
}

func (b *lockedBuffer) Write(p []byte) (int, error) {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.buf.Write(p)
}

func (b *lockedBuffer) String() string {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.buf.String()
}

// Two callers can want the same runner at the same factor: a create throttling
// the runner it has just made, and the heartbeat that lands while it is doing
// so. applyThrottle chooses its candidates under the lock and then releases it
// to talk to the daemon, so the second caller used to see a runner whose
// applied factor had not been written yet and ask for the same quota again.
//
// The duplicate changes nothing, because the update is idempotent -- which is
// why it went unnoticed, surfacing only as a test that counted the calls and
// failed on a loaded machine. It is still a second daemon call per create on
// exactly the host that is already overwhelmed, which is the one place Zoomies
// should be asking for less.
func TestTwoCallersThrottlingOneRunnerAskTheDaemonOnce(t *testing.T) {
	a, tr, be, _ := newAgent(t, 2)
	createdRunner(a, "run_a", "wl-a", store.Resources{CPUs: 2, MemoryMB: 2048})

	gate := make(chan struct{})
	entered := make(chan struct{}, 1)
	be.mu.Lock()
	be.updateGate, be.updateEntered = gate, entered
	be.mu.Unlock()

	// The first caller, held inside the daemon call.
	a.mu.Lock()
	a.cpuFactor = 0.5
	a.mu.Unlock()
	done := make(chan struct{})
	go func() {
		defer close(done)
		a.applyThrottle(context.Background(), false)
	}()
	select {
	case <-entered:
	case <-time.After(5 * time.Second):
		t.Fatal("the first caller never reached the daemon")
	}

	// The gate is stood down before the second caller runs, so that a build
	// without the marker asks the daemon and fails the count below rather than
	// blocking behind the first caller and hanging the test. The first caller
	// captured its own gate on the way in and is still held.
	be.mu.Lock()
	be.updateGate, be.updateEntered = nil, nil
	be.mu.Unlock()

	// The second, arriving in exactly the window the marker exists to close.
	// It must find the runner spoken for and leave it alone.
	beat(t, a, tr, be, &ThrottleDirective{Level: 2, CPUFactor: 0.5})

	close(gate)
	<-done

	if got := be.resourceUpdates(); len(got) != 1 {
		t.Fatalf("updates = %+v, want one: the second caller asked for a quota already being set", got)
	}

	// And the marker is released, or a refusal would be held off for ever by
	// something nothing clears. The factor is applied by now, so a new one is
	// what proves the runner is still reachable.
	if got := beat(t, a, tr, be, &ThrottleDirective{Level: 0, CPUFactor: 1}); len(got) != 1 {
		t.Fatalf("updates = %+v, want the restore to land: the runner is still claimed by a call that finished", got)
	}
}

func TestStartupGraceKeepsNormalLimitsThenAppliesStandingThrottle(t *testing.T) {
	a, tr, be, clock := newAgent(t, 4)
	a.opts.BootstrapCPUGrace = 2 * time.Minute
	createdRunner(a, "new", "wl-new", store.Resources{CPUs: 1, MemoryMB: 2048})
	createdRunner(a, "old", "wl-old", store.Resources{CPUs: 1, MemoryMB: 2048})
	a.runners["old"].createdAt = clock.Now().Add(-time.Hour)
	directive := &ThrottleDirective{Level: 2, CPUFactor: 0.5}
	if got := beat(t, a, tr, be, directive); len(got) != 1 || got[0].handle != "wl-old" {
		t.Fatalf("startup throttled or old job left alone: %+v", got)
	}
	clock.advance(2 * time.Minute)
	got := beat(t, a, tr, be, directive)
	if len(got) != 1 || got[0].handle != "wl-new" || got[0].res.CPUs != 0.5 || got[0].res.MemoryMB != 2048 {
		t.Fatalf("grace did not expire under unchanged directive: %+v", got)
	}
}

func TestDinDCreationAndAdoptionUseTheSamePerContainerThrottleBudget(t *testing.T) {
	for _, source := range []string{store.AllocationFromHost, store.AllocationFromPool, ""} {
		t.Run(source, func(t *testing.T) {
			a, tr, be, _ := newAgent(t, 4)
			task := createTask("task", "runner")
			task.Spec.DockerMode = store.DockerDinD
			task.Spec.ResourcesSource = source
			task.Spec.Resources = store.Resources{CPUs: 4, MemoryMB: 8192}
			a.handleCreate(context.Background(), task, func() {})
			want := 4.0
			if source == store.AllocationFromHost {
				want = 2
			}
			if got := beat(t, a, tr, be, &ThrottleDirective{CPUFactor: 0.5}); len(got) != 1 || got[0].res.CPUs != want/2 {
				t.Fatalf("throttle: %+v, base %v", got, want)
			}
			if got := beat(t, a, tr, be, &ThrottleDirective{CPUFactor: 1}); len(got) != 1 || got[0].res.CPUs != want {
				t.Fatalf("restoration exceeded container budget: %+v, want %v", got, want)
			}
		})
	}
}

func TestAdoptionDoesNotRestartTheBootstrapGrace(t *testing.T) {
	a, tr, be, clock := newAgent(t, 4)
	a.opts.BootstrapCPUGrace = 2 * time.Minute
	be.setWorkloads(backend.Workload{Handle: "old", RunnerID: "old", Status: backend.Status{Phase: backend.PhaseRunning, StartedAt: clock.Now().Add(-time.Hour)}, Resources: store.Resources{CPUs: 1}})
	a.adoptExisting(context.Background())
	if got := beat(t, a, tr, be, &ThrottleDirective{CPUFactor: 0.5}); len(got) != 1 || got[0].res.CPUs != 0.5 {
		t.Fatalf("old adopted runner gained startup grace: %+v", got)
	}
}

// A boost is lent on the controller's word and only withdrawn by its next plan.
// With the controller gone no plan comes, so the agent gives the CPU back
// itself -- not on the first missed beat, which is a restart, but once enough
// have gone by that nothing is coming. A throttle is left standing: it is the
// safe direction to be wrong in.
func TestBoostsAreGivenBackWhenTheControllerStopsAnswering(t *testing.T) {
	a, tr, be, _ := newAgent(t, 4)
	createdRunner(a, "run_a", "wl-a", store.Resources{CPUs: 2, MemoryMB: 4096})
	if got := beat(t, a, tr, be, &ThrottleDirective{CPUFactor: 1}, ElasticCPUDirective{
		RunnerID: "run_a", CPUFactor: 2, BaseCPUs: 2, TargetCPUs: 4,
	}); len(got) != 1 || got[0].res.CPUs != 4 {
		t.Fatalf("updates = %+v, want the runner lent 4 CPUs", got)
	}

	tr.mu.Lock()
	tr.beatErr = errors.New("controller unreachable")
	tr.mu.Unlock()
	miss := func() []resourceUpdate {
		before := len(be.resourceUpdates())
		if err := a.heartbeat(context.Background()); err == nil {
			t.Fatal("heartbeat succeeded against an unreachable controller")
		}
		return be.resourceUpdates()[before:]
	}
	for i := 1; i < boostExpiryMisses; i++ {
		if got := miss(); len(got) != 0 {
			t.Fatalf("after %d missed beat(s) the agent changed %+v; a restart should not cost a running job its boost", i, got)
		}
	}
	// The third failed attempt only ends a loan once its time lease has
	// elapsed too; quick retries must not shorten that window.
	a.mu.Lock()
	a.boostRenewedAt = time.Now().Add(-boostExpiryMisses * a.heartbtI)
	a.mu.Unlock()
	if got := miss(); len(got) != 1 || got[0].res.CPUs != 2 {
		t.Fatalf("after %d missed beats updates = %+v, want the runner back at its 2 CPU guarantee", boostExpiryMisses, got)
	}
	if got := miss(); len(got) != 0 {
		t.Fatalf("a further missed beat changed %+v; a boost given back is given back once", got)
	}
}

func TestAThrottleOutlastsAControllerThatStopsAnswering(t *testing.T) {
	a, tr, be, _ := newAgent(t, 4)
	createdRunner(a, "run_a", "wl-a", store.Resources{CPUs: 2})
	a.opts.BootstrapCPUGrace = 0
	if got := beat(t, a, tr, be, &ThrottleDirective{Level: 2, CPUFactor: 0.5}); len(got) != 1 || got[0].res.CPUs != 1 {
		t.Fatalf("updates = %+v, want the runner throttled to 1 CPU", got)
	}
	tr.mu.Lock()
	tr.beatErr = errors.New("controller unreachable")
	tr.mu.Unlock()
	before := len(be.resourceUpdates())
	for range boostExpiryMisses + 2 {
		_ = a.heartbeat(context.Background())
	}
	if got := be.resourceUpdates()[before:]; len(got) != 0 {
		t.Fatalf("a missing controller lifted the throttle: %+v; only a boost is given back", got)
	}
}

package agent

import (
	"context"
	"fmt"
	"time"

	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
)

// toolFillTimeout bounds one fill. Several JDKs over a slow link are minutes
// each; a fill still running after this long is stuck, and the next scan
// offers it again.
const toolFillTimeout = 45 * time.Minute

// handleToolFill fills a pool's tool cache on this host and reports what
// became of each request.
func (a *Agent) handleToolFill(ctx context.Context, task Task) {
	a.fill.Lock()
	defer a.fill.Unlock()
	if ctx.Err() != nil {
		a.reportNotStarted(ctx, task)
		return
	}
	kind := task.Backend
	if kind == "" {
		kind = a.opts.DefaultBackend
	}
	b, err := a.opts.Backends.Get(kind)
	if err != nil {
		a.reportToolFill(ctx, task, nil, err)
		return
	}
	filler, ok := b.(backend.ToolCacheFiller)
	if !ok {
		a.reportToolFill(ctx, task, nil, fmt.Errorf("the %s backend keeps no tool cache to fill", kind))
		return
	}
	fctx, cancel := context.WithTimeout(ctx, toolFillTimeout)
	defer cancel()
	started := a.now()
	fills, err := filler.FillToolCache(fctx, *task.Spec, task.Tools)
	a.log.Info("filled a pool's tool cache", "pool", task.Spec.PoolID, "requests", len(task.Tools),
		"answered", len(fills), "took", a.now().Sub(started).Round(time.Second), "error", err)
	a.reportToolFill(ctx, task, fills, err)
}

func (a *Agent) reportToolFill(ctx context.Context, task Task, fills []backend.ToolFill, err error) {
	res := TaskResult{TaskID: task.ID, Kind: task.Kind, OK: err == nil, ToolFills: fills, CompletedAt: a.now()}
	if err != nil {
		res.Error = err.Error()
		res.Fault = backend.Fault(err)
		if res.Fault == "" {
			res.Fault = store.FaultBackend
		}
	}
	a.report(ctx, res)
}

package agent

import (
	"context"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
)

// fillingBackend is the fake backend plus a tool cache fill that waits until
// the test lets it finish.
type fillingBackend struct {
	*fakeBackend
	release chan struct{}
	got     chan []backend.ToolRequest
}

func (f *fillingBackend) FillToolCache(ctx context.Context, spec backend.Spec, tools []backend.ToolRequest) ([]backend.ToolFill, error) {
	f.got <- tools
	select {
	case <-f.release:
	case <-ctx.Done():
		return nil, ctx.Err()
	}
	out := make([]backend.ToolFill, 0, len(tools))
	for _, t := range tools {
		out = append(out, backend.ToolFill{Tool: t.Tool, Request: t.Version, Outcome: backend.ToolInstalled, Version: t.Version + ".0"})
	}
	return out, nil
}

func fillTask(id string) Task {
	return Task{ID: id, Kind: TaskFillToolCache, Backend: store.BackendDocker, PoolID: "pool-1",
		Spec:  &backend.Spec{PoolID: "pool-1", Image: "ghcr.io/example/runner:latest", Cache: store.CacheConfig{Enabled: true, Tools: true}},
		Tools: []backend.ToolRequest{{Tool: "python", Version: "3.12"}, {Tool: "node", Version: "22"}}}
}

// A fill is minutes of downloading. In a lifecycle slot it would hold back
// the runners it exists to speed up: on a one-slot host, a job queued behind
// a fill waited for every JDK to arrive. It runs beside the slots instead.
func TestAFillDoesNotHoldARunnerSlot(t *testing.T) {
	tr := newFakeTransport()
	be := &fillingBackend{fakeBackend: newFakeBackend(store.BackendDocker), release: make(chan struct{}), got: make(chan []backend.ToolRequest, 1)}
	a, err := New(Options{
		Name: "test-host", WorkDir: t.TempDir(), Capacity: 1, Backends: backend.NewRegistry(be),
		DefaultBackend: store.BackendDocker, Transport: tr, HeartbeatInterval: time.Second, Logger: testLogger(), Clock: newTestClock().Now,
	})
	if err != nil {
		t.Fatal(err)
	}
	if err := a.Join(context.Background(), "join-token"); err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan error, 1)
	go func() { done <- a.Run(ctx) }()
	t.Cleanup(func() {
		cancel()
		<-done
	})
	h := &harness{t: t, agent: a, tr: tr, be: be.fakeBackend}

	tr.tasks <- []Task{fillTask("fill-1")}
	select {
	case tools := <-be.got:
		if len(tools) != 2 {
			t.Fatalf("the fill was given %v", tools)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("the fill never reached the backend")
	}

	tr.tasks <- []Task{createTask("create-1", "runner-1")}
	if res := h.nextResult(); res.TaskID != "create-1" || !res.OK {
		t.Fatalf("while a fill ran, the create reported %+v", res)
	}

	close(be.release)
	res := h.nextResult()
	if res.TaskID != "fill-1" || !res.OK || len(res.ToolFills) != 2 || res.ToolFills[0].Version != "3.12.0" {
		t.Fatalf("fill result = %+v", res)
	}
}

// A backend with no tool cache -- the process backend, a fake -- answers the
// task rather than dropping it, or the controller's lease on it never clears.
func TestAFillOnABackendWithoutAToolCacheSaysSo(t *testing.T) {
	h := newHarness(t, 1)
	h.tr.tasks <- []Task{fillTask("fill-1")}
	res := h.nextResult()
	if res.OK || !strings.Contains(res.Error, "keeps no tool cache") {
		t.Fatalf("result = %+v, want a failure saying the backend keeps no tool cache", res)
	}
}

func TestAFillWithNothingToFillIsRefused(t *testing.T) {
	task := fillTask("fill-1")
	task.Tools = nil
	if err := validateTask(task); err == nil {
		t.Error("a fill naming no toolchains was accepted")
	}
	task = fillTask("fill-2")
	task.Spec = nil
	if err := validateTask(task); err == nil {
		t.Error("a fill with no spec was accepted; the backend could not find the pool's cache")
	}
}

// The controller sends fills only to agents that say they understand them.
func TestTheAgentAdvertisesToolCacheFills(t *testing.T) {
	h := newHarness(t, 1)
	h.tr.mu.Lock()
	req := h.tr.joinReq
	h.tr.mu.Unlock()
	if req == nil || !strings.Contains(strings.Join(req.Features, ","), FeatureToolCacheFill) {
		t.Fatalf("join features = %v, want %s", req, FeatureToolCacheFill)
	}
}

package agent

import (
	"context"
	"io"
	"time"
)

// Transport is how an agent reaches its controller.
//
// There are two implementations. The HTTP one is what a standalone agent uses:
// it long-polls for tasks and POSTs results, always outbound, so a host behind
// NAT needs no inbound rule. The direct one is used by the agent embedded in
// the controller process and skips the network entirely, which is what lets the
// single-VM case be exactly one process.
//
// Every method must respect context cancellation; the agent cancels in flight
// when it is shutting down.
type Transport interface {
	// Join redeems a join token and returns the host's identity and its
	// long-lived agent token. It is called once, the first time an agent runs
	// on a host.
	Join(ctx context.Context, req JoinRequest) (*JoinResponse, error)

	// Heartbeat reports liveness, capacity and the agent's own view of its
	// runners. A transport that returns a nil error returns a non-nil
	// response; the agent dereferences the answer unguarded, so this is part
	// of the contract, not a courtesy.
	Heartbeat(ctx context.Context, req HeartbeatRequest) (*HeartbeatResponse, error)

	// PollTasks blocks for up to wait, returning as soon as there is work. An
	// empty batch after the full wait is the normal idle case, not an error.
	PollTasks(ctx context.Context, wait time.Duration) (*TaskBatch, error)

	// ReportResult reports the outcome of one task.
	ReportResult(ctx context.Context, res TaskResult) error

	// ReportRunners pushes runner observations outside the heartbeat cycle,
	// so a state change is visible in the UI immediately rather than up to one
	// heartbeat later.
	ReportRunners(ctx context.Context, reports []RunnerReport) error

	// OpenLogStream returns a writer for one relayed log stream. The agent
	// copies a runner's output into it; the controller fans it out to whoever
	// is watching in the browser. Closing the writer ends the stream.
	OpenLogStream(ctx context.Context, streamID string) (io.WriteCloser, error)

	// SetCredentials installs the identity returned by Join, or restored from
	// the agent's config, for use on subsequent calls.
	SetCredentials(hostID, agentToken string)

	// Describe returns a short string naming where this transport points, for
	// log lines and the agent's startup banner.
	Describe() string
}

// Credentials are what an agent persists between runs so that a restart does
// not need a new join token.
type Credentials struct {
	HostID         string `json:"host_id" yaml:"host_id"`
	AgentToken     string `json:"agent_token" yaml:"agent_token"`
	Controller     string `json:"controller_url" yaml:"controller_url"`
	TailcatAddress string `json:"tailcat_address,omitempty" yaml:"-"`
	// JoinTokenHash and FallbackTokenHash remember which join tokens this host
	// has already spent, as hashes, because the tokens themselves are worth
	// keeping out of the file: the first is the token that was redeemed for
	// these credentials, the second the last one offered after the controller
	// refused them. A host that is refused for good offers the token its
	// environment still holds only if it matches neither, so a deleted host
	// does not ask the controller to enrol it with a spent token on every
	// restart. A file written before they existed has neither, which loads.
	JoinTokenHash     string `json:"join_token_hash,omitempty" yaml:"-"`
	FallbackTokenHash string `json:"fallback_token_hash,omitempty" yaml:"-"`
}

// Valid reports whether the credentials are complete enough to use. A host
// enrolled through a private connection needs its tunnel address too: without
// one, the host ID and agent token alone name a controller this agent has no
// way to dial.
func (c Credentials) Valid() bool {
	if c.HostID == "" || c.AgentToken == "" {
		return false
	}
	return c.Controller != TailcatController || c.TailcatAddress != ""
}

package agent

import (
	"context"
	"encoding/json"
	"errors"
	"runtime"
	"slices"
	"strconv"
	"strings"
	"time"
	"unicode"
	"unicode/utf8"

	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/updates"
	"github.com/eyupio/zoomies/internal/updates/channel"
	"github.com/eyupio/zoomies/internal/version"
)

const (
	// updateReportWindow is how far from now, either way, a result's finish may
	// be and still be news. The controller closes an attempt that has had no
	// answer for 90 minutes, so a result older than that answers an attempt that
	// is already closed; the ten minutes over are for a helper that finished just
	// before the timeout, on a beat that came just after it. A finish as far in
	// the future is a clock or a file that cannot be trusted. A new process cannot
	// know whether the one before it delivered a result, so it sends what it finds
	// within the window once.
	updateReportWindow = 100 * time.Minute
	// maxUpdateErrorRunes bounds the helper's sentence on the wire. The result
	// file can carry far more, and the rest is in the helper's log tail on the
	// host, which is where somebody reading a long failure goes anyway.
	maxUpdateErrorRunes = 1024
	// maxUpdateFieldRunes bounds an id, a tag or a version read back from the
	// result, each of which is a short name when the helper wrote it.
	maxUpdateFieldRunes = 64
	// maxRequestedBy is the most of requested_by the helper accepts.
	// internal/updates refuses anything longer and does not export its limit;
	// WriteRequest checks before it writes, so the two cannot drift apart unseen.
	maxRequestedBy = 128
	// helperInstallCommand is what installs the helper, run by somebody with root
	// on the host. Nothing the agent does can run it, which is the point.
	helperInstallCommand = `"sudo zoomies updates helper install"`
)

// updateDir is the update folder the helper on this host reads, and false when
// there is none to find.
func (a *Agent) updateDir() (string, bool) {
	if a.opts.UpdateDir == nil {
		return "", false
	}
	return a.opts.UpdateDir()
}

// selfUpdateReady says whether the helper is installed beside this agent. The
// marker is the installer's last step, so a folder without one is a helper that
// was never finished, and is treated as none.
func (a *Agent) selfUpdateReady() bool {
	dir, ok := a.updateDir()
	if !ok {
		return false
	}
	_, found, err := channel.Ready(dir)
	return err == nil && found
}

// LocalHelperHost is this machine as updates.HelperSupport reads it, looked at
// the way the installer looks before it refuses: the operating system, and
// whether systemd runs here, which only a service outside a container can see.
// Whether the service runs runners, and under what runtime, is the caller's to
// add.
func LocalHelperHost() updates.HelperHost {
	in := backend.InContainer()
	return updates.HelperHost{GOOS: runtime.GOOS, InContainer: in, Systemd: !in && backend.HasSystemd()}
}

// updateUnsupported is why the helper cannot be installed on this host, for the
// heartbeat to carry, and nothing once it is installed: a marker in a folder a
// request can be written to is a better witness than anything worked out here.
func (a *Agent) updateUnsupported(features []string, infos []backend.Info) updates.HelperUnsupported {
	if a.opts.HelperHost == nil || slices.Contains(features, FeatureSelfUpdate) {
		return ""
	}
	host := a.opts.HelperHost()
	host.RunsRunners = true
	host.RootlessRuntime = rootlessRuntime(infos)
	return updates.HelperSupport(host)
}

// RootlessRuntime is whether the container runtimes this agent last found all
// run without root, for the controller that runs it inside itself and is in the
// same container.
func (a *Agent) RootlessRuntime() bool {
	a.mu.Lock()
	defer a.mu.Unlock()
	return rootlessRuntime(a.backendInfo)
}

// rootlessRuntime says every container runtime that answered runs without root.
// A container deployment runs under one of them, and which is not known here, so
// a root runtime beside a rootless one says nothing; the process backend is not
// a runtime at all, and in a container it is never root whatever runs it.
func rootlessRuntime(infos []backend.Info) bool {
	found := false
	for _, info := range infos {
		if !info.Available || info.Kind == store.BackendProcess {
			continue
		}
		if !info.Rootless {
			return false
		}
		found = true
	}
	return found
}

// handleUpdate hands the helper on this host a request to take it to the
// task's release, and reports whether the request was written. Whether the
// update itself worked is not known here: the helper's upgrade restarts this
// process, and the next one reports the helper's result on its heartbeat.
//
// Only the task's attempt id and tag are taken from it. Both were checked by
// validateTask, and the helper, running as root, checks everything again.
func (a *Agent) handleUpdate(ctx context.Context, task Task) {
	// One at a time: WriteRequest's look for an earlier request is a courtesy and
	// not a lock, so two tasks writing at once could replace each other unseen.
	a.update.Lock()
	defer a.update.Unlock()
	if a.mutationsPaused.Load() {
		a.report(ctx, TaskResult{TaskID: task.ID, Kind: task.Kind, NotStarted: true, CompletedAt: a.now(),
			Error: "the controller has paused every change on this host while it recovers, so the update was not asked for; it is safe to send again"})
		return
	}
	if ctx.Err() != nil {
		a.reportNotStarted(ctx, task)
		return
	}
	// A task the controller redelivers because it did not see the answer finds
	// its own request still waiting, which is what it asked for and not a
	// reason to fail. Only this process's writes are remembered: a request
	// written by the process before an update is that update's, and is answered
	// by the version check below once the new binary is running.
	if a.updateWritten[task.UpdateID] {
		a.log.Info("asked again for an update this agent has already handed to the helper", "attempt", task.UpdateID)
		a.answerUpdate(ctx, task, "")
		return
	}

	running, tag := version.Version, task.UpdateTag
	skew := version.CompareBuilds(running, tag)
	if tag == updates.DevTag {
		// The dev channel moves, so it has no order to check. The controller has
		// already decided this host is behind its build; the agent only refuses to
		// replace a build that is neither a release nor one from main, which may
		// be somebody's work in progress.
		skew = version.SkewBehind
		if _, release := version.Release(running); !release && !version.IsMainBuild(running) {
			a.answerUpdate(ctx, task, "this agent runs the build "+fieldText(running)+
				", which is neither a release nor a build from main, so it does not ask for the dev channel; update it on the host with zoomies upgrade")
			return
		}
	}
	switch skew {
	case version.SkewNone, version.SkewAhead:
		// An agent is never taken backwards, whatever the controller asks: an
		// agent ahead of its controller is merely untested, and one taken back
		// across a release could meet a state file it cannot read.
		a.log.Info("asked to update to a release this agent already runs or is past; nothing to do",
			"attempt", task.UpdateID, "running", running, "tag", tag)
		a.answerUpdate(ctx, task, "")
		return
	case version.SkewDiffers:
		a.answerUpdate(ctx, task, "this agent runs the build "+fieldText(running)+
			", which is not a release, so it cannot tell whether "+tag+" is newer and does not ask for it; update it on the host with zoomies upgrade")
		return
	}

	dir, ok := a.updateDir()
	if !ok {
		a.answerUpdate(ctx, task, "this host has no update folder, so there is no update helper to run the update; run "+
			helperInstallCommand+" on the host")
		return
	}
	switch _, found, err := channel.Ready(dir); {
	case err != nil:
		a.log.Warn("the update folder is not as the installer leaves it", "attempt", task.UpdateID, "error", err)
		a.answerUpdate(ctx, task, "this host's update folder, or the helper's marker in it, is not as the installer leaves it, so the helper is treated as missing; run "+
			helperInstallCommand+" on the host to install it again")
		return
	case !found:
		a.answerUpdate(ctx, task, "the update helper is not installed on this host, so nothing would read the request; run "+
			helperInstallCommand+" on the host")
		return
	}

	// The helper has already answered this attempt: the request was written by an
	// agent process before this one and taken. The answer rides the heartbeat, and
	// a second request would ask for the same update twice.
	if res, found, err := channel.ReadResult(dir); err == nil && found && res.ID == task.UpdateID {
		a.log.Info("asked for an update the helper has already answered; its result goes on the heartbeat", "attempt", task.UpdateID)
		a.answerUpdate(ctx, task, "")
		return
	}

	req := updates.Request{
		V: updates.WireVersion, ID: task.UpdateID, Tag: tag,
		RequestedBy: a.updateRequestedBy(), RequestedAt: a.now().UTC(),
	}
	// WriteRequest refuses this too, but in a sentence about the folder; a
	// request the helper would refuse is the controller's mistake, not the host's.
	if body, err := json.Marshal(req); err != nil {
		a.answerUpdate(ctx, task, "the update request could not be encoded, so nothing was written: "+err.Error())
		return
	} else if _, err := updates.ParseRequest(body); err != nil {
		a.answerUpdate(ctx, task, "the controller asked for an update this host's helper would refuse, so nothing was written: "+err.Error())
		return
	}
	var stuck *UpdateStuck
	if err := channel.WriteRequest(dir, req); err != nil {
		// The request waiting may be this attempt's own, written by an agent
		// process before this one, which a restarted controller asks for again.
		// That is what was asked for, not a reason to fail the attempt.
		if errors.Is(err, channel.ErrRequestPending) {
			if waiting, found, perr := channel.PendingRequest(dir); perr == nil && found &&
				waiting.ID == task.UpdateID && waiting.Tag == task.UpdateTag {
				a.log.Info("asked again for an update whose request is still waiting for the helper", "attempt", task.UpdateID)
				a.answerUpdate(ctx, task, "")
				return
			}
			// Somebody else's request is in the way. Before refusing, look at why
			// the helper has not read it: a helper that has stopped would refuse
			// every attempt from now on, with nobody the wiser.
			heal := a.healStuckHelper(ctx, task, dir, req)
			switch {
			case heal.written:
				err, stuck = nil, heal.stuck
			case heal.stuck != nil:
				a.answerUpdateStuck(ctx, task, heal.reason, heal.stuck)
				return
			}
		}
		if err != nil {
			// The full error names the folder, which is for this host's log. The
			// sentence goes to a page every role reads, so it names only the fix.
			a.log.Warn("could not hand the update request to the helper", "attempt", task.UpdateID, "tag", tag, "error", err)
			if errors.Is(err, channel.ErrRequestPending) {
				a.answerUpdate(ctx, task, "an earlier update request is still waiting in this host's update folder, so the helper has not read it and this one was not written; "+
					`check the helper with "sudo zoomies updates helper status" on the host, and remove the waiting request.json if the helper is not going to read it`)
				return
			}
			a.answerUpdate(ctx, task, "the update request could not be written to this host's update folder, so nothing ran; run "+
				helperInstallCommand+" on the host, which creates the folder with the right owner, and see the agent's log there for the reason")
			return
		}
	}
	if a.updateWritten == nil {
		a.updateWritten = make(map[string]bool)
	}
	a.updateWritten[task.UpdateID] = true
	a.log.Info("asked the update helper to update this host", "attempt", task.UpdateID, "from", running, "to", tag)
	a.answerUpdateStuck(ctx, task, "", stuck)
}

// answerUpdate reports what became of an update task: written, or why not. It
// names no runner and carries no runner state, because the task is the host's,
// and a failure counted against a runner would be counted against its pool.
func (a *Agent) answerUpdate(ctx context.Context, task Task, failure string) {
	a.answerUpdateStuck(ctx, task, failure, nil)
}

// answerUpdateStuck is answerUpdate for a task that found the helper stopped, or
// repaired it: stuck says what was found and done, for the controller to name and
// to record, whether the request was written in the end or not.
func (a *Agent) answerUpdateStuck(ctx context.Context, task Task, failure string, stuck *UpdateStuck) {
	if failure != "" {
		a.log.Warn("did not ask the update helper for an update", "attempt", task.UpdateID, "tag", task.UpdateTag, "reason", failure)
	}
	a.report(ctx, TaskResult{TaskID: task.ID, Kind: task.Kind, OK: failure == "", Error: failure, Stuck: stuck, CompletedAt: a.now()})
}

// updateRequestedBy is who the helper's log says asked. The agent does not know
// which person pressed the button, only that its controller asked; the
// controller's own record of the attempt says who.
func (a *Agent) updateRequestedBy() string {
	return cutBytes(printableText("the controller, through the agent on "+a.opts.Name), maxRequestedBy)
}

// updateReport is the helper's last result, for the next heartbeat to carry,
// and the key to mark it delivered by; nil when there is nothing new to say. A
// result is carried until a beat that carried it has been answered, then not
// again by this process.
//
// result.json is written by root, but the folder belongs to the service account,
// so anything in it may have been put there by something else. It is read with
// the channel's limits; whether it answers an attempt is the controller's to
// decide.
func (a *Agent) updateReport() (*UpdateReport, string) {
	dir, ok := a.updateDir()
	if !ok {
		return nil, ""
	}
	res, found, err := channel.ReadResult(dir)
	if err != nil {
		a.log.Debug("ignoring a result in the update folder that cannot be read", "error", err)
		return nil, ""
	}
	if !found || res.FinishedAt.IsZero() {
		return nil, ""
	}
	if age := a.now().Sub(res.FinishedAt); age > updateReportWindow || age < -updateReportWindow {
		return nil, ""
	}
	key := updateKey(res)
	a.mu.Lock()
	delivered := a.updateDelivered[key]
	a.mu.Unlock()
	if delivered {
		return nil, ""
	}
	// The helper's sentence is relayed, not trusted: it is stripped of what a
	// terminal or a browser would act on and cut to a sentence's length here,
	// and the controller shows it to the platform role only.
	return &UpdateReport{
		ID: fieldText(res.ID), OK: res.OK, Tag: fieldText(res.Tag), From: fieldText(res.From), To: fieldText(res.To),
		Error:      truncateRunes(printableText(res.Error), maxUpdateErrorRunes),
		FinishedAt: res.FinishedAt.UTC(),
	}, key
}

// updateKey names one result by what the helper wrote, not by what is sent.
// The id alone is not enough: a refusal of a request the helper cannot trust
// carries none, and each such refusal answers a different attempt. And the id
// as sent is cleaned and cut, so two ids that differ only where the cleaning
// reaches would otherwise be taken for one.
func updateKey(res updates.Result) string {
	return res.ID + "\x00" + strconv.FormatInt(res.FinishedAt.UnixNano(), 10)
}

// markUpdateDelivered records that a heartbeat carrying the result with this
// key was answered, so later beats leave it out. It is called only after the
// beat succeeded: a beat that failed may never have reached the controller.
func (a *Agent) markUpdateDelivered(key string) {
	a.mu.Lock()
	defer a.mu.Unlock()
	if a.updateDelivered == nil {
		a.updateDelivered = make(map[string]bool)
	}
	a.updateDelivered[key] = true
}

// printableText is s with what a terminal or a page would act on taken out: a
// line break or a tab becomes a space, and an escape sequence, a direction
// override or any other unprintable character is dropped.
func printableText(s string) string {
	return strings.TrimSpace(strings.Map(func(r rune) rune {
		switch {
		case unicode.IsGraphic(r):
			return r
		case unicode.IsSpace(r):
			return ' '
		}
		return -1
	}, s))
}

// fieldText is a short field from a file the agent did not write, made safe to
// pass on and cut to the length a name has.
func fieldText(s string) string {
	return truncateRunes(printableText(s), maxUpdateFieldRunes)
}

// cutBytes is s cut to at most limit bytes, at a character boundary.
func cutBytes(s string, limit int) string {
	if len(s) <= limit {
		return s
	}
	end := limit
	for end > 0 && !utf8.RuneStart(s[end]) {
		end--
	}
	return strings.TrimSpace(s[:end])
}

package agent

import (
	"context"
	"errors"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/updates"
	"github.com/eyupio/zoomies/internal/updates/channel"
)

// defaultRepairWait is how long an update task waits for root to answer a repair
// request. The repair settles for a few seconds after starting the path unit, so
// a healthy repair answers well inside it; one that does not answer has no repair
// unit listening, and the host's owner has to install it again.
const defaultRepairWait = 45 * time.Second

// healOutcome is what looking at a helper that did not read its request came to.
type healOutcome struct {
	// stuck is set when the helper was found stopped or busy; nil means nothing
	// was wrong that the agent can tell, and the ordinary refusal stands.
	stuck *UpdateStuck
	// written says the request was written after a repair.
	written bool
	// reason is the sentence for a failure, without a path.
	reason string
}

// healStuckHelper is what a task does instead of refusing outright when its
// request cannot be written because an earlier one is still there. The agent
// cannot touch the units and does not try: it looks, and when the helper is
// provably stopped it asks root, through the folder, to put it right, waits for
// the answer, and writes its request once if the helper is back.
//
// The caller holds a.update, which is what serialises two tasks: the second one
// to arrive sees the first's repair or the budget it spent, never a repair of
// its own on top.
func (a *Agent) healStuckHelper(ctx context.Context, task Task, dir string, req updates.Request) healOutcome {
	if a.opts.UnitRun == nil {
		return healOutcome{}
	}
	diag, err := channel.Diagnose(ctx, a.opts.UnitRun, dir, a.opts.ConfigDir, a.now(), a.opts.Processes)
	if err != nil {
		a.log.Warn("could not look at the update helper", "attempt", task.UpdateID, "error", err)
		return healOutcome{}
	}
	verdict := updates.Classify(diag, updates.OrphanAfter)
	if verdict.Kind == "" {
		return healOutcome{}
	}
	stuck := &UpdateStuck{
		Kind: verdict.Kind, RequestAgeSeconds: int64(diag.RequestAge / time.Second),
		Path: unitWords(diag.Path), Service: unitWords(diag.Service), LockPresent: diag.LockPresent,
	}
	a.log.Warn("the update request is waiting and the helper may be stopped",
		"attempt", task.UpdateID, "kind", verdict.Kind, "request_age", diag.RequestAge.Round(time.Second),
		"waiting_request", diag.RequestID, "lock", diag.LockPresent, "path_unit", stuck.Path, "service_unit", stuck.Service,
		"engine_running", diag.EngineRunning)

	if !verdict.Repair {
		// A helper at work may be reading the request, and the engine owns the lock.
		stuck.Note = "busy"
		return healOutcome{stuck: stuck, reason: "the update helper on this host is running another update, so this request was not written; it is safe to send again once that one finishes"}
	}
	if ok, next := a.repairs.Admit(a.now()); !ok {
		stuck.Note, stuck.Attempts = "held_back", len(a.repairs.Times)
		a.log.Warn("not asking for another repair of the update helper yet", "attempt", task.UpdateID, "next", next.UTC().Format(time.RFC3339))
		return healOutcome{stuck: stuck, reason: "the update helper on this host is stopped and was already repaired, or the repair was asked for, too recently to try again; the next repair may start at " +
			next.UTC().Format(time.RFC3339) + " (run " + helperInstallCommand + " on the host to put it right now)"}
	}
	stuck.Asked, stuck.Attempts = true, len(a.repairs.Times)

	repair := updates.RepairRequest{V: updates.WireVersion, ID: task.UpdateID, RequestedAt: a.now().UTC()}
	if err := channel.WriteRepair(dir, repair); err != nil && !errors.Is(err, channel.ErrRepairPending) {
		a.log.Warn("could not ask root to repair the update helper", "attempt", task.UpdateID, "error", err)
		stuck.Note = "no_answer"
		return healOutcome{stuck: stuck, reason: "the update helper on this host is stopped and the repair could not be asked for; run " + helperInstallCommand + " on the host"}
	}
	a.log.Info("asked root to repair the update helper", "attempt", task.UpdateID, "kind", verdict.Kind)

	res, answered := a.awaitRepair(ctx, dir, task.UpdateID)
	if !answered {
		channel.WithdrawRepair(dir, task.UpdateID)
		stuck.Note = "no_answer"
		a.log.Warn("root did not answer the repair request; the repair units may not be installed", "attempt", task.UpdateID)
		return healOutcome{stuck: stuck, reason: "the update helper on this host is stopped and nothing answered the request to repair it, which happens when the repair units are not installed on this host; run " +
			helperInstallCommand + " on the host, which also starts the helper"}
	}
	stuck.Repaired = append([]string(nil), res.Actions...)
	a.log.Info("root answered the repair request", "attempt", task.UpdateID, "healed", res.Healed, "actions", res.Actions, "verdict", res.Verdict)
	if !res.Healed {
		stuck.Note = "refused"
		return healOutcome{stuck: stuck, reason: "the update helper on this host is stopped, and the repair did not put it right: " + fieldSentence(res.Error) +
			"; run " + helperInstallCommand + " on the host"}
	}

	// One write, once: the helper is back and the folder is clear, or it is not.
	if err := channel.WriteRequest(dir, req); err != nil {
		a.log.Warn("the helper was repaired but the request could not be written", "attempt", task.UpdateID, "error", err)
		stuck.Note = "refused"
		return healOutcome{stuck: stuck, reason: "the update helper on this host was repaired, but an earlier request is still in its update folder, so this one was not written; it is safe to send again"}
	}
	stuck.Healed = true
	return healOutcome{stuck: stuck, written: true}
}

// awaitRepair waits for root's answer to this attempt's repair, and says whether
// it came. It looks once a second, because the answer is a file and there is
// nothing to be woken by.
func (a *Agent) awaitRepair(ctx context.Context, dir, id string) (updates.RepairResult, bool) {
	wait := a.opts.RepairWait
	if wait <= 0 {
		wait = defaultRepairWait
	}
	// Real time, not the agent's clock: this is a wait on another process.
	deadline := time.Now().Add(wait)
	for {
		if res, found, err := channel.ReadRepairResult(dir); err == nil && found && res.ID == id {
			return res, true
		}
		if !time.Now().Before(deadline) || !sleepCtx(ctx, repairPoll) {
			return updates.RepairResult{}, false
		}
	}
}

// repairPoll is how often an update task looks for root's answer. A variable so
// that a test does not wait a second for each look.
var repairPoll = time.Second

// unitWords is a unit's state as systemd's own words, for a sentence: what a
// person reads at "systemctl status".
func unitWords(u updates.UnitState) string {
	words := make([]string, 0, 3)
	for _, w := range []string{u.Active, u.Enabled} {
		if w = fieldText(w); w != "" {
			words = append(words, w)
		}
	}
	if u.Failed {
		words = append(words, "failed")
	}
	return strings.Join(words, ", ")
}

// fieldSentence is a sentence from root's answer, cleaned and cut.
func fieldSentence(s string) string {
	s = truncateRunes(printableText(s), maxUpdateErrorRunes)
	if s == "" {
		return "no reason was given"
	}
	return strings.TrimRight(s, ". ")
}

package agent

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/updates"
	"github.com/eyupio/zoomies/internal/updates/channel"
)

// fakeUnits stands in for systemctl on a host whose helper has stopped. The
// agent only ever asks it questions; the fake root below is what changes it.
type fakeUnits struct {
	mu                        sync.Mutex
	pathActive, pathEnabled   string
	pathFailed, serviceFailed bool
	serviceActive             string
	asked                     int
}

func newStoppedUnits() *fakeUnits {
	return &fakeUnits{pathActive: "inactive", pathEnabled: "disabled", pathFailed: true, serviceActive: "inactive"}
}

func (f *fakeUnits) run(_ context.Context, _ string, args ...string) (string, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.asked++
	unit := args[len(args)-1]
	switch args[0] {
	case "is-active":
		if unit == channel.PathUnit {
			return f.pathActive, nil
		}
		return f.serviceActive, nil
	case "is-enabled":
		if unit == channel.PathUnit {
			return f.pathEnabled, nil
		}
		return "static", nil
	case "is-failed":
		if (unit == channel.PathUnit && f.pathFailed) || (unit == channel.ServiceUnit && f.serviceFailed) {
			return "failed", nil
		}
		return "active", nil
	}
	return "", nil
}

func (f *fakeUnits) heal() {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.pathActive, f.pathEnabled, f.pathFailed, f.serviceFailed = "active", "enabled", false, false
}

// fakeRoot is the repair unit: it watches the folder for repair.json and answers
// it. fix says what it does to the host, and healed what it reports.
type fakeRoot struct {
	dir     string
	units   *fakeUnits
	healed  bool
	mu      sync.Mutex
	repairs []string
}

func (r *fakeRoot) start(t *testing.T) {
	t.Helper()
	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan struct{})
	t.Cleanup(func() { cancel(); <-done })
	go func() {
		defer close(done)
		for ctx.Err() == nil {
			time.Sleep(2 * time.Millisecond)
			body, err := os.ReadFile(filepath.Join(r.dir, updates.RepairFile))
			if err != nil {
				continue
			}
			req, err := updates.ParseRepairRequest(body)
			if err != nil {
				continue
			}
			_ = os.Remove(filepath.Join(r.dir, updates.RepairFile))
			r.mu.Lock()
			r.repairs = append(r.repairs, req.ID)
			r.mu.Unlock()
			res := updates.RepairResult{V: updates.WireVersion, ID: req.ID, Healed: r.healed, FinishedAt: time.Now().UTC(), Verdict: updates.StuckPathDown}
			if r.healed {
				r.units.heal()
				_ = os.Remove(filepath.Join(r.dir, channel.RequestFile))
				res.Actions = []string{updates.ActionResetFailed, updates.ActionRewroteUnits, updates.ActionStartedPath, updates.ActionRemovedRequest}
			} else {
				res.Error = "the helper's units could not be put right: cannot write the unit"
			}
			b, _ := json.Marshal(res)
			_ = os.WriteFile(filepath.Join(r.dir, updates.RepairResultFile), b, 0o644)
		}
	}()
}

func (r *fakeRoot) asked() []string {
	r.mu.Lock()
	defer r.mu.Unlock()
	return slices.Clone(r.repairs)
}

// stuckHost is a host the way the report found it: a helper installed, its path
// unit dead, and a request three days old in the folder. The agent can ask
// systemd and can write the folder, and nothing else.
type stuckHost struct {
	dir   string
	units *fakeUnits
	root  *fakeRoot
	h     *harness
}

func newStuckHost(t *testing.T, requestAge time.Duration, tweaks ...func(*Options)) *stuckHost {
	t.Helper()
	runningBuild(t, "1.3.0")
	was := repairPoll
	repairPoll = 5 * time.Millisecond
	t.Cleanup(func() { repairPoll = was })

	dir := readyUpdateFolder(t)
	s := &stuckHost{dir: dir, units: newStoppedUnits()}
	s.root = &fakeRoot{dir: dir, units: s.units, healed: true}
	opts := []func(*Options){withUpdateFolder(dir), func(o *Options) {
		o.UnitRun = s.units.run
		o.Processes = func() [][]string { return nil }
		o.RepairWait = 2 * time.Second
	}}
	s.h = newHarness(t, 1, append(opts, tweaks...)...)
	if requestAge > 0 {
		old := []byte(`{"v":1,"id":"upd_stale","tag":"v1.3.4","requested_by":"the controller","requested_at":"2026-01-01T09:00:00Z"}`)
		path := filepath.Join(dir, channel.RequestFile)
		if err := os.WriteFile(path, old, 0o640); err != nil {
			t.Fatal(err)
		}
		at := s.h.clock.Now().Add(-requestAge)
		if err := os.Chtimes(path, at, at); err != nil {
			t.Fatal(err)
		}
	}
	return s
}

func (s *stuckHost) request(t *testing.T) updates.Request {
	t.Helper()
	req, found, err := channel.PendingRequest(s.dir)
	if err != nil || !found {
		t.Fatalf("no readable request in the folder: found %v, err %v", found, err)
	}
	return req
}

// The report: every attempt failed for days with "an update request is already
// waiting for the helper", and nothing was written or started. The agent now
// sees that the path unit is dead, asks root to repair, and writes its request.
func TestAnUpdateTaskAsksForARepairWhenThePathUnitIsDeadAndThenWritesItsRequest(t *testing.T) {
	s := newStuckHost(t, 72*time.Hour)
	s.root.start(t)

	s.h.tr.tasks <- []Task{updateTask("task-1", "upd_abc123", "v1.3.5")}
	res := s.h.nextResult()

	if !res.OK || res.Stuck == nil || !res.Stuck.Healed || res.Stuck.Kind != updates.StuckPathDown {
		t.Fatalf("the update task reported %+v (stuck %+v), want OK with a healed path_down", res, res.Stuck)
	}
	if !slices.Contains(res.Stuck.Repaired, updates.ActionStartedPath) || res.Stuck.Path != "inactive, disabled, failed" {
		t.Errorf("stuck = %+v, want the repair actions and the unit state the agent found", res.Stuck)
	}
	if res.Stuck.RequestAgeSeconds < int64((72*time.Hour)/time.Second) {
		t.Errorf("request age = %ds, want about three days", res.Stuck.RequestAgeSeconds)
	}
	if got := s.request(t); got.ID != "upd_abc123" || got.Tag != "v1.3.5" {
		t.Errorf("the request in the folder is %+v, want this attempt's", got)
	}
	if asked := s.root.asked(); !slices.Equal(asked, []string{"upd_abc123"}) {
		t.Errorf("root was asked to repair for %v, want exactly this attempt", asked)
	}
}

func TestAnUpdateTaskAsksForARepairWhenTheRequestIsStaleUnderHealthyLookingUnits(t *testing.T) {
	s := newStuckHost(t, 3*time.Hour)
	s.units.heal()
	s.root.start(t)

	s.h.tr.tasks <- []Task{updateTask("task-1", "upd_abc123", "v1.3.5")}
	res := s.h.nextResult()

	if !res.OK || res.Stuck == nil || res.Stuck.Kind != updates.StuckStaleRequest || !res.Stuck.Healed {
		t.Fatalf("the update task reported %+v (stuck %+v), want OK after repairing a stale request", res, res.Stuck)
	}
}

// A helper that is mid-upgrade may still be reading the request, and the engine
// owns the lock. The agent leaves everything alone, asks for nothing, and says so.
func TestAnUpdateTaskNeverAsksForARepairWhileTheHelperIsMidUpgrade(t *testing.T) {
	for name, tweak := range map[string]func(*stuckHost){
		"the helper's service is running": func(s *stuckHost) { s.units.serviceActive = "active" },
		"the engine is alive": func(s *stuckHost) {
			s.h.agent.opts.Processes = func() [][]string { return [][]string{{"/usr/local/bin/zoomies", "upgrade", "--version", "v1.3.5"}} }
		},
	} {
		t.Run(name, func(t *testing.T) {
			s := newStuckHost(t, 72*time.Hour)
			s.root.start(t)
			tweak(s)

			s.h.tr.tasks <- []Task{updateTask("task-1", "upd_abc123", "v1.3.5")}
			res := s.h.nextResult()

			if res.OK || res.Stuck == nil || res.Stuck.Kind != updates.StuckBusy || res.Stuck.Asked {
				t.Fatalf("the update task reported %+v (stuck %+v), want a refusal because the helper is busy", res, res.Stuck)
			}
			if asked := s.root.asked(); len(asked) != 0 {
				t.Errorf("root was asked to repair a helper that is mid-upgrade: %v", asked)
			}
			if got := s.request(t); got.ID != "upd_stale" {
				t.Errorf("the request in the folder is %+v; a live helper's request must be left alone", got)
			}
			if _, err := os.Lstat(filepath.Join(s.dir, updates.RepairFile)); err == nil {
				t.Error("a repair request was left in the folder")
			}
		})
	}
}

// Repair units that are not installed answer nothing. The task says so, in words
// that name the fix, and takes its request back so that nothing acts on it later.
func TestAnUpdateTaskReportsThatNothingAnsweredTheRepairRequest(t *testing.T) {
	s := newStuckHost(t, 72*time.Hour, func(o *Options) { o.RepairWait = 60 * time.Millisecond })

	s.h.tr.tasks <- []Task{updateTask("task-1", "upd_abc123", "v1.3.5")}
	res := s.h.nextResult()

	if res.OK || res.Stuck == nil || res.Stuck.Note != "no_answer" || !res.Stuck.Asked {
		t.Fatalf("the update task reported %+v (stuck %+v), want a failure saying nobody answered", res, res.Stuck)
	}
	if !strings.Contains(res.Error, "sudo zoomies updates helper install") || strings.Contains(res.Error, s.dir) {
		t.Errorf("error = %q, want the fix and no path on the host", res.Error)
	}
	if _, err := os.Lstat(filepath.Join(s.dir, updates.RepairFile)); err == nil {
		t.Error("the repair request was left for a unit that might act on it later")
	}
	if got := s.request(t); got.ID != "upd_stale" {
		t.Errorf("the stale request changed to %+v; the agent must never remove it", got)
	}
}

// Never in a loop: a repair that did not put the helper right is not asked for
// again by the next attempt a minute later.
func TestAnUpdateTaskDoesNotAskForASecondRepairSoSoon(t *testing.T) {
	s := newStuckHost(t, 72*time.Hour)
	s.root.healed = false
	s.root.start(t)

	s.h.tr.tasks <- []Task{updateTask("task-1", "upd_one", "v1.3.5")}
	first := s.h.nextResult()
	if first.OK || first.Stuck == nil || first.Stuck.Note != "refused" || len(s.root.asked()) != 1 {
		t.Fatalf("first = %+v (stuck %+v), repairs asked %v; want one repair that did not heal", first, first.Stuck, s.root.asked())
	}

	s.h.clock.advance(time.Minute)
	s.h.tr.tasks <- []Task{updateTask("task-2", "upd_two", "v1.3.5")}
	second := s.h.nextResult()

	if second.OK || second.Stuck == nil || second.Stuck.Note != "held_back" || second.Stuck.Asked {
		t.Fatalf("second = %+v (stuck %+v), want it held back by the budget", second, second.Stuck)
	}
	if asked := s.root.asked(); len(asked) != 1 {
		t.Errorf("root was asked to repair %d times, want 1: %v", len(asked), asked)
	}
}

// Two attempts arriving together are one repair and one request. The update lock
// serialises them, so the second finds the first's repaired helper and its
// request, and refuses in the ordinary way instead of repairing on top of it.
func TestTwoUpdateTasksRacingAreOneRepairAndOneRequest(t *testing.T) {
	s := newStuckHost(t, 72*time.Hour)
	s.root.start(t)

	s.h.tr.tasks <- []Task{updateTask("task-1", "upd_aaaaaa", "v1.3.5"), updateTask("task-2", "upd_bbbbbb", "v1.3.5")}
	a, b := s.h.nextResult(), s.h.nextResult()

	if asked := s.root.asked(); len(asked) != 1 {
		t.Fatalf("root was asked to repair %d times, want exactly 1: %v", len(asked), asked)
	}
	winners := 0
	for _, res := range []TaskResult{a, b} {
		if res.OK {
			winners++
			if res.Stuck == nil || !res.Stuck.Healed {
				t.Errorf("the task that won reported %+v, want the repair recorded on it", res)
			}
		} else if res.Stuck != nil && res.Stuck.Asked {
			t.Errorf("the task that lost asked for a repair of its own: %+v", res.Stuck)
		}
	}
	if winners != 1 {
		t.Fatalf("%d tasks wrote a request (%+v, %+v), want exactly 1", winners, a, b)
	}
	if got := s.request(t); got.ID != s.root.asked()[0] {
		t.Errorf("the request in the folder is %s, want the one whose attempt asked for the repair (%s)", got.ID, s.root.asked()[0])
	}
}

// A helper that is fine, with a request that is merely recent, is the ordinary
// refusal and nothing more: no repair is asked for.
func TestAFreshWaitingRequestUnderAHealthyHelperIsNotRepaired(t *testing.T) {
	s := newStuckHost(t, time.Minute)
	s.units.heal()
	s.root.start(t)

	s.h.tr.tasks <- []Task{updateTask("task-1", "upd_abc123", "v1.3.5")}
	res := s.h.nextResult()

	if res.OK || res.Stuck != nil || !strings.Contains(res.Error, "zoomies updates helper status") {
		t.Fatalf("the update task reported %+v (stuck %+v), want the ordinary refusal", res, res.Stuck)
	}
	if len(s.root.asked()) != 0 {
		t.Errorf("a repair was asked for under a healthy helper: %v", s.root.asked())
	}
}

package agent

