func TestAnUpdateTaskWithAnIDTheHelperWouldRefuseWritesNothing(t *testing.T) {
	runningBuild(t, "1.3.0")
	dir := readyUpdateFolder(t)
	h := newHarness(t, 1, withUpdateFolder(dir))

