func TestSnapshotsAdmitThePilotSizeButStillRefuseSourceBeyondTheBound(t *testing.T) {
	s := fixture()
	s.Files = nil
	content := strings.Repeat("a", MaxFileBytes)
	for i := 0; i < 24; i++ {
