	for _, path := range []string{"../private.go", "/etc/passwd", "web/../main.go", "a\\b", "a\nb", ".git/config", "web/.env.local", "key.pem", "data.sqlite", "node_modules/x.js", ".zoomies/ai-context/manifest.json"} {
