}

package analysis

import (
	"cmp"
	"errors"
	"fmt"
	"math"
	"slices"
	"strconv"
	"strings"
	"time"
)

const CompareVersion = "compare-v1"

// MinCompareJobs is the fewest jobs a side needs before the comparison ranks
// anything: under it, a release that ran three slow jobs would be blamed for
// them. ConfidentCompareJobs is what a side needs for a change to be called
// with high confidence.
const (
	MinCompareJobs       = 30
	ConfidentCompareJobs = 100
)

// Spread is a measure's percentiles over a side's jobs. It mirrors
// store.JobPercentiles, field for field and name for name, so a figure in a
// finding and on the Usage page's table read the same.
type Spread struct {
	Samples int    `json:"samples"`
	P50MS   *int64 `json:"p50_ms"`
	P95MS   *int64 `json:"p95_ms"`
}

// JobFigures is what one side's jobs did. The caller leaves out the
// conclusions it names in CompareSnapshot.Excluded before counting, which is
// why there is no cancelled count: it would always read 0, and a 0 here
// would look like a measurement of none cancelled.
type JobFigures struct {
	Jobs        int    `json:"jobs"`
	Succeeded   int    `json:"succeeded"`
	Failed      int    `json:"failed"`
	FleetFailed int    `json:"fleet_failed"`
	OOMKilled   int    `json:"oom_killed"`
	Duration    Spread `json:"duration"`
	QueueWait   Spread `json:"queue_wait"`
	Startup     Spread `json:"startup"`
}

type CompareSide struct {
	// Label is a release such as v1.3.3, or a period such as "the 24 hours
	// before". A period's label reads after "in", so it is a noun phrase.
	Label string    `json:"label"`
	Since time.Time `json:"since"`
	Until time.Time `json:"until"`
	// Figures on a CountsOnly side hold Jobs and FleetFailed and nothing
	// else: the roll-up it was read from keeps no outcomes, no OOM kills and
	// no times, and a zero there is not a measurement.
	Figures    JobFigures `json:"figures"`
	CountsOnly bool       `json:"counts_only"`
	// JobsGoneBefore is set on a release side reaching past retention.jobs:
	// no roll-up records which release ran a job, so the jobs before it are
	// simply gone. A period side never has it: past retention.jobs it is
	// read from the roll-up instead (CountsOnly), so Compare refuses it.
	JobsGoneBefore *time.Time `json:"jobs_gone_before"`
	// MeanSlots is the fleet's slots on offer, averaged over the side's
	// sampled minutes; nil when no sample covers the side.
	MeanSlots *float64 `json:"mean_slots"`
	// NoRecordBefore is set on a CountsOnly side whose counts begin later
	// than the period asked for: the fleet keeps no counts before it (its
	// first record, or where the roll-up began). With Since not before Until
	// the side could not be read at all, which is not the same as no jobs
	// having run: where the oldest rows were pruned before the roll-up first
	// ran, jobs did run, and nobody can now say how many.
	NoRecordBefore *time.Time `json:"no_record_before"`
	// AskedUntil is where the period asked for ends. A CountsOnly side can
	// end before it, because the roll-up reads whole UTC days: the hours
	// from Until to AskedUntil are then the other side's or neither side's,
	// and only this says so once Until has moved. Zero when not known.
	AskedUntil time.Time `json:"asked_until"`
}

// unread is a side the fleet keeps no counts for at all.
func (s CompareSide) unread() bool { return s.NoRecordBefore != nil && !s.Since.Before(s.Until) }

type CompareSnapshot struct {
	// By is "version" or "period".
	By   string
	A, B CompareSide
	// Excluded names the conclusions the read left out (cancelled and
	// skipped). The analysis cannot see what it was not given, so it says
	// what its caller says it left out, and no more.
	Excluded []string
}

// A change's direction. not_enough is a measure the sample cannot judge,
// which is not the same as one that held still.
const (
	Regressed = "regressed"
	Improved  = "improved"
	Unchanged = "unchanged"
	NotEnough = "not_enough"
)

type Change struct {
	Measure string `json:"measure"`
	// Unit is "ms" for a time, "rate" for a fraction of the side's jobs.
	Unit      string   `json:"unit"`
	Direction string   `json:"direction"`
	From      *float64 `json:"from"`
	To        *float64 `json:"to"`
	// Ratio is how far the measure moved against its bar, whichever way: the
	// larger time over the smaller, or a rate's difference over five points.
	// It is nil when the measure could not be judged, and for a time that
	// moved from nothing, which has no finite ratio.
	Ratio *float64 `json:"ratio"`
}

type CompareEvidence struct {
	By string      `json:"by"`
	A  CompareSide `json:"a"`
	B  CompareSide `json:"b"`
	// Changes holds one row for every measure, in a fixed order, so a
	// reader finds a measure by name whether or not it moved.
	Changes                []Change `json:"changes"`
	Excluded               []string `json:"excluded"`
	PercentilesUnavailable bool     `json:"percentiles_unavailable"`
}

type CompareFinding = Finding[CompareEvidence]

var compareCodes = []string{"jobs.duration_regressed", "pool.queue_wait_high", "jobs.runner_lost",
	"jobs.workflow_failing", "jobs.oom_killed"}

// A rate moved when it differs by five points and the worse side has three
// events: one failure in thirty jobs is three points of noise, not a trend.
const (
	rateStep      = 0.05
	rateParts     = 20 // five points is one part in twenty
	minRateEvents = 3
)

type compareMeasure struct {
	name, words string
	family      string
	// spread and p95 pick a time measure; floor is the least it must move,
	// as well as a quarter, to count.
	spread func(JobFigures) Spread
	p95    bool
	floor  time.Duration
	// events picks a rate measure's count of jobs.
	events func(JobFigures) int
	// fromRollUp is a measure the usage roll-up also keeps, so a counts-only
	// side can still be compared on it.
	fromRollUp bool
}

var compareMeasures = []compareMeasure{
	{name: "duration_p50", words: "duration p50", family: "duration", spread: func(f JobFigures) Spread { return f.Duration }, floor: 30 * time.Second},
	{name: "duration_p95", words: "duration p95", family: "duration", spread: func(f JobFigures) Spread { return f.Duration }, p95: true, floor: 30 * time.Second},
	{name: "queue_wait_p50", words: "queue wait p50", family: "queue_wait", spread: func(f JobFigures) Spread { return f.QueueWait }, floor: 10 * time.Second},
	{name: "queue_wait_p95", words: "queue wait p95", family: "queue_wait", spread: func(f JobFigures) Spread { return f.QueueWait }, p95: true, floor: 10 * time.Second},
	{name: "startup_p50", words: "startup p50", family: "startup", spread: func(f JobFigures) Spread { return f.Startup }, floor: 10 * time.Second},
	{name: "startup_p95", words: "startup p95", family: "startup", spread: func(f JobFigures) Spread { return f.Startup }, p95: true, floor: 10 * time.Second},
	{name: "fleet_failure_rate", words: "fleet failure rate", family: "fleet_failure", events: func(f JobFigures) int { return f.FleetFailed }, fromRollUp: true},
	{name: "failure_rate", words: "failure rate", family: "failure", events: func(f JobFigures) int { return f.Failed }},
	{name: "oom_rate", words: "OOM kill rate", family: "oom", events: func(f JobFigures) int { return f.OOMKilled }},
}

// regressionSteps say what to read for each family of measure that got
// worse. under is "under v1.3.3" or "in the last 24 hours", moved is
// "duration p95 5m to 9m".
var regressionSteps = map[string]func(under, moved string) NextStep{
	"duration": func(under, moved string) NextStep {
		return NextStep{Code: "jobs.duration_regressed", Text: fmt.Sprintf(
			"Jobs ran longer %s (%s); group the slower jobs' runs by host to tell a slower workflow from a slower machine.", under, moved)}
	},
	"queue_wait": func(under, moved string) NextStep {
		return NextStep{Code: "pool.queue_wait_high", Text: fmt.Sprintf(
			"Jobs waited longer to start %s (%s); the queue-wait breakdown over the same period says which cause grew.", under, moved)}
	},
	"startup": func(under, moved string) NextStep {
		return NextStep{Code: "pool.queue_wait_high", Setting: "pool.min_runners", Text: fmt.Sprintf(
			"Runners took longer to start %s (%s); warm runners kept by a pool's minimum runners hide startup from its jobs.", under, moved)}
	},
	"fleet_failure": func(under, moved string) NextStep {
		return NextStep{Code: "jobs.runner_lost", Text: fmt.Sprintf(
			"The fleet lost more jobs %s (%s); the fault kinds of those jobs say whether their runners never started or stopped under them.", under, moved)}
	},
	"failure": func(under, moved string) NextStep {
		return NextStep{Code: "jobs.workflow_failing", Text: fmt.Sprintf(
			"More jobs failed %s (%s); a failure the fleet did not cause is the workflow's own, and the step each job failed at says what to fix.", under, moved)}
	},
	"oom": func(under, moved string) NextStep {
		return NextStep{Code: "jobs.oom_killed", Setting: "pool.resources.memory_mb", Text: fmt.Sprintf(
			"More jobs were killed for their memory limit %s (%s); the memory their pool gives them is what to raise.", under, moved)}
	},
}

// judged is one measure's change with what the sentences need: key ranks it
// unrounded (infinite for a time that moved from nothing), and from and to
// are its figures in words.
type judged struct {
	measure  compareMeasure
	change   Change
	key      float64
	from, to string
}

// Compare says what got worse and what got better between two releases or
// two periods, and refuses to rank either when a side is too small to say.
// A is the earlier, B the one being judged against it.
func Compare(s CompareSnapshot) (CompareFinding, error) {
	f := CompareFinding{Analysis: "compare", Version: CompareVersion, NextSteps: []NextStep{}, Codes: []string{}}
	if s.By != "version" && s.By != "period" {
		return f, fmt.Errorf("compare snapshot is by %q; it is by version or by period", s.By)
	}
	for _, side := range []CompareSide{s.A, s.B} {
		if side.Label == "" {
			return f, errors.New("compare snapshot has a side with no label, which no sentence could name")
		}
		if !side.Since.IsZero() && !side.Until.IsZero() && side.Until.Before(side.Since) {
			return f, fmt.Errorf("compare side %s ends before it starts", side.Label)
		}
		if s.By == "period" && side.JobsGoneBefore != nil {
			return f, fmt.Errorf("compare side %s is a period cut short by retention.jobs; a period past it is read from the roll-up", side.Label)
		}
	}
	f.Since, f.Until = span(s.A, s.B)
	w := wording{by: s.By, a: s.A.Label, b: s.B.Label}
	na, nb := s.A.Figures.Jobs, s.B.Figures.Jobs
	small := na < MinCompareJobs || nb < MinCompareJobs

	var all []judged
	e := CompareEvidence{By: s.By, A: s.A, B: s.B, Excluded: nonNil(slices.Clone(s.Excluded)),
		PercentilesUnavailable: s.A.CountsOnly || s.B.CountsOnly}
	for _, m := range compareMeasures {
		j := judge(m, s.A, s.B, small)
		all = append(all, j)
		e.Changes = append(e.Changes, j.change)
	}
	e.Changes = nonNil(e.Changes)
	f.Evidence = e

	switch {
	case s.A.unread() && s.B.unread():
		f.Summary = fmt.Sprintf("The fleet keeps no counts from before %s, so neither %s nor %s could be read, and there is nothing to compare%s.",
			stamp(*s.B.NoRecordBefore), w.a, w.b, w.cutOff(s, s.B, true))
		f.ConfidenceReason = fmt.Sprintf("the fleet keeps no counts from before %s, so neither side could be read", stamp(*s.B.NoRecordBefore))
	case s.A.unread() || s.B.unread():
		gone, other, later := s.A, w.b, false
		if s.B.unread() {
			gone, other, later = s.B, w.a, true
		}
		f.ConfidenceReason = fmt.Sprintf("the fleet keeps no counts from before %s, so %s could not be read", stamp(*gone.NoRecordBefore), gone.Label)
		f.Summary = fmt.Sprintf("The fleet keeps no counts from before %s, so %s could not be read, and there is nothing to compare %s with%s.",
			stamp(*gone.NoRecordBefore), gone.Label, other, w.cutOff(s, gone, later))
	case na == 0 && nb == 0:
		f.Summary, f.ConfidenceReason = w.neitherRan(), "neither side ran a job"
	case na == 0:
		f.Summary, f.ConfidenceReason = w.oneRanNothing(w.a, w.b), w.ranNothing(w.a)
	case nb == 0:
		f.Summary, f.ConfidenceReason = w.oneRanNothing(w.b, w.a), w.ranNothing(w.b)
	case small:
		// Name the short side: a release hours old beside one that ran
		// hundreds of jobs is the commonest case, and "either side" would be
		// false of the one that ran hundreds.
		where := "on either side"
		if na >= MinCompareJobs {
			where = w.under(w.b)
		} else if nb >= MinCompareJobs {
			where = w.under(w.a)
		}
		ran := w.ran(na, nb) + fmt.Sprintf(": fewer than %d %s", MinCompareJobs, where)
		f.Summary, f.ConfidenceReason = ran+", so the two are not ranked.", ran
	}
	if small {
		f.Confidence = Low
		for _, c := range w.coverage(s) {
			f.ConfidenceReason += "; also, " + c
		}
		f.NextSteps = append(f.NextSteps, NextStep{Setting: "limits.job_stats_window", Text: fmt.Sprintf(
			"Compare again once each side holds at least %d jobs, or over a longer period, up to limits.job_stats_window.", MinCompareJobs)})
		return f, nil
	}

	regressed, improved := moved(all, Regressed), moved(all, Improved)
	switch {
	case len(regressed) > 0:
		f.Dominant, f.Summary = regressed[0].measure.name, w.lead(regressed, true)
	case len(improved) > 0:
		f.Dominant, f.Summary = improved[0].measure.name, w.lead(improved, false)
	default:
		f.Summary = w.alike(all)
	}
	f.Confidence = High
	if reasons := w.doubts(s); len(reasons) > 0 {
		// A retention reason carries a colon and commas of its own, so a bare
		// separator would hide where the next reason begins.
		f.Confidence, f.ConfidenceReason = Medium, strings.Join(reasons, "; also, ")
	}

	// One step for each family that got worse, the furthest first; then,
	// for a release, the one setting that keeps the fleet from taking the
	// next one while this is looked into.
	families := map[string]bool{}
	for _, j := range regressed {
		if families[j.measure.family] {
			continue
		}
		families[j.measure.family] = true
		f.NextSteps = append(f.NextSteps, regressionSteps[j.measure.family](w.under(w.b), j.measure.words+" "+j.from+" to "+j.to))
	}
	if len(regressed) > 0 && s.By == "version" {
		f.NextSteps = append(f.NextSteps, NextStep{Setting: "updates.mode", Text: "Hold automatic updates while the regression is looked into."})
	}
	for _, step := range f.NextSteps {
		if step.Code != "" && !slices.Contains(f.Codes, step.Code) {
			f.Codes = append(f.Codes, step.Code)
		}
	}
	return f, nil
}

// judge decides one measure. Every figure higher is worse, so the direction
// is the sign of B against A.
func judge(m compareMeasure, a, b CompareSide, small bool) judged {
	j := judged{measure: m, change: Change{Measure: m.name, Unit: "ms", Direction: NotEnough}}
	// A counts-only side's zeros are not measurements: compared, a failure
	// rate read from the roll-up would always look like an improvement.
	usable := !small && (m.fromRollUp || (!a.CountsOnly && !b.CountsOnly))
	if m.events == nil {
		va, sa := timeFigure(m, a)
		vb, sb := timeFigure(m, b)
		j.change.From, j.change.To = msFloat(va), msFloat(vb)
		if !usable || va == nil || vb == nil || sa < MinCompareJobs || sb < MinCompareJobs {
			return j
		}
		lo, hi := min(*va, *vb), max(*va, *vb)
		j.from, j.to = Words(time.Duration(*va)*time.Millisecond), Words(time.Duration(*vb)*time.Millisecond)
		switch {
		case lo > 0:
			j.key = float64(hi) / float64(lo)
			j.change.Ratio = round(j.key, 100)
		case hi > 0:
			j.key = math.Inf(1)
		default:
			j.key = 1
			j.change.Ratio = round(1, 1)
		}
		// Integer arithmetic, so a move of exactly a quarter is one.
		if hi*100 >= lo*125 && hi-lo >= m.floor.Milliseconds() {
			j.change.Direction = direction(*va, *vb)
		} else {
			j.change.Direction = Unchanged
		}
		return j
	}

	j.change.Unit = "rate"
	ea, eb := m.events(a.Figures), m.events(b.Figures)
	na, nb := int64(a.Figures.Jobs), int64(b.Figures.Jobs)
	if na > 0 && (m.fromRollUp || !a.CountsOnly) {
		j.change.From = round(float64(ea)/float64(na), 10000)
	}
	if nb > 0 && (m.fromRollUp || !b.CountsOnly) {
		j.change.To = round(float64(eb)/float64(nb), 10000)
	}
	if !usable || na == 0 || nb == 0 {
		return j
	}
	j.from, j.to = percent(ea, na), percent(eb, nb)
	// The rates' difference times na*nb, kept in integers so a move of
	// exactly five points is one, which a float division would not promise.
	cross := int64(eb)*na - int64(ea)*nb
	j.key = float64(abs(cross)) / (rateStep * float64(na*nb))
	j.change.Ratio = round(j.key, 100)
	worse := ea
	if cross > 0 {
		worse = eb
	}
	if cross != 0 && abs(cross)*rateParts >= na*nb && worse >= minRateEvents {
		j.change.Direction = direction(int64(ea)*nb, int64(eb)*na)
	} else {
		j.change.Direction = Unchanged
	}
	return j
}

func timeFigure(m compareMeasure, s CompareSide) (*int64, int) {
	if s.CountsOnly {
		return nil, 0
	}
	sp := m.spread(s.Figures)
	if m.p95 {
		return sp.P95MS, sp.Samples
	}
	return sp.P50MS, sp.Samples
}

func direction(from, to int64) string {
	if to > from {
		return Regressed
	}
	return Improved
}

// moved is the changes in one direction, furthest first; a tie keeps the
// measures' own order, so the same snapshot always leads the same way.
func moved(all []judged, dir string) []judged {
	var out []judged
	for _, j := range all {
		if j.change.Direction == dir {
			out = append(out, j)
		}
	}
	slices.SortStableFunc(out, func(x, y judged) int { return cmp.Compare(y.key, x.key) })
	return out
}

// span is the time both sides cover. A side that ran nothing may carry no
// times at all, and a zero time is not a start.
func span(a, b CompareSide) (time.Time, time.Time) {
	var since, until time.Time
	for _, s := range []CompareSide{a, b} {
		if !s.Since.IsZero() && (since.IsZero() || s.Since.Before(since)) {
			since = s.Since
		}
		if s.Until.After(until) {
			until = s.Until
		}
	}
	return since, until
}

// wording is how a comparison reads. A release is the subject of its
// sentence ("v1.3.3 is worse than v1.3.2"); a period is where jobs ran
// ("jobs did worse in the last 24 hours"), because "the last 24 hours is
// worse" is not English.
type wording struct{ by, a, b string }

func (w wording) period() bool { return w.by == "period" }

// under is the phrase that places something on one side.
func (w wording) under(label string) string {
	if w.period() {
		return "in " + label
	}
	return "under " + label
}

func (w wording) ran(na, nb int) string {
	if w.period() {
		return fmt.Sprintf("%s ran in %s and %d in %s", count(na, "job"), w.a, nb, w.b)
	}
	return fmt.Sprintf("%s ran %s and %s ran %d in this period", w.a, count(na, "job"), w.b, nb)
}

func (w wording) ranNothing(label string) string {
	if w.period() {
		return "no jobs ran in " + label
	}
	return label + " ran no jobs in this period"
}

func (w wording) oneRanNothing(empty, other string) string {
	if w.period() {
		return fmt.Sprintf("No jobs ran in %s, so there is nothing to compare %s with.", empty, other)
	}
	return fmt.Sprintf("%s ran no jobs in this period, so there is nothing to compare %s with.", empty, other)
}

func (w wording) neitherRan() string {
	if w.period() {
		return fmt.Sprintf("No jobs ran in either %s or %s, so there is nothing to compare.", w.a, w.b)
	}
	return fmt.Sprintf("Neither %s nor %s ran a job in this period, so there is nothing to compare.", w.a, w.b)
}

func (w wording) lead(list []judged, worse bool) string {
	top := list[0]
	more := ""
	if len(list) > 1 {
		more = fmt.Sprintf(", and on %d more", len(list)-1)
	}
	how := "better"
	if worse {
		how = "worse"
	}
	if w.period() {
		return fmt.Sprintf("Jobs did %s in %s than in %s on %s (%s to %s)%s.", how, w.b, w.a, top.measure.words, top.from, top.to, more)
	}
	return fmt.Sprintf("%s is %s than %s on %s (%s to %s)%s.", w.b, how, w.a, top.measure.words, top.from, top.to, more)
}

// alike says nothing moved, and how many measures could not be judged, so
// "ran alike" never claims a measure nobody saw.
func (w wording) alike(all []judged) string {
	head := fmt.Sprintf("%s and %s ran alike", w.b, w.a)
	if w.period() {
		head = fmt.Sprintf("Jobs ran alike in %s and %s", w.a, w.b)
	}
	unjudged := 0
	for _, j := range all {
		if j.change.Direction == NotEnough {
			unjudged++
		}
	}
	if unjudged > 0 {
		return fmt.Sprintf("%s: no measure moved past its threshold, though %d of %d could not be compared.", head, unjudged, len(all))
	}
	return head + ": no measure moved past its threshold."
}

// doubts are the reasons a comparison that ranks is still not high
// confidence, each naming the side and the figure it is about.
func (w wording) doubts(s CompareSnapshot) []string {
	var out []string
	if s.A.Figures.Jobs < ConfidentCompareJobs || s.B.Figures.Jobs < ConfidentCompareJobs {
		out = append(out, w.ran(s.A.Figures.Jobs, s.B.Figures.Jobs)+
			fmt.Sprintf(": fewer than %d on a side, so a change named here is less certain", ConfidentCompareJobs))
	}
	for _, side := range []CompareSide{s.A, s.B} {
		if side.CountsOnly {
			out = append(out, side.Label+" reaches past retention.jobs, so it was read from the daily usage roll-up: its percentiles are unavailable, "+
				"it is compared on fleet failure rate alone, and the roll-up counts every job on the day it was first seen, cancelled and unfinished ones included, "+
				"so its counts are defined differently from the job rows'")
		}
	}
	out = append(out, w.coverage(s)...)
	for _, side := range []CompareSide{s.A, s.B} {
		if side.JobsGoneBefore != nil {
			out = append(out, fmt.Sprintf("%s's jobs from before %s are gone (retention.jobs keeps them for a set time, and raising it keeps more next time), so %s's figures cover only the jobs still kept",
				side.Label, side.JobsGoneBefore.UTC().Format("2006-01-02 15:04 UTC"), side.Label))
		}
	}
	switch {
	case s.A.MeanSlots == nil && s.B.MeanSlots == nil:
		out = append(out, "how many slots the fleet offered is not known for either side, because no host samples cover them (retention.samples decides how long they are kept), so queue waits may not be like for like")
	case s.A.MeanSlots == nil || s.B.MeanSlots == nil:
		unknown := s.A.Label
		if s.B.MeanSlots == nil {
			unknown = s.B.Label
		}
		out = append(out, fmt.Sprintf("how many slots the fleet offered %s is not known, because no host samples cover it (retention.samples decides how long they are kept), so queue waits may not be like for like", w.under(unknown)))
	default:
		lo, hi := min(*s.A.MeanSlots, *s.B.MeanSlots), max(*s.A.MeanSlots, *s.B.MeanSlots)
		if hi > lo*1.25 {
			out = append(out, fmt.Sprintf("the fleet offered %s slots %s and %s %s, so queue waits are not like for like",
				slotWords(*s.A.MeanSlots), w.under(s.A.Label), slotWords(*s.B.MeanSlots), w.under(s.B.Label)))
		}
	}
	return out
}

func stamp(t time.Time) string { return t.UTC().Format("2006-01-02 15:04 UTC") }

// cutOff is what an unread side's summary adds when the fleet's counts begin
// inside the hours it asked for, after the midnight its read stopped at:
// those hours are on record, and "could not be read" alone would say they
// were lost. An earlier side's are the later side's when its counts begin
// there; otherwise they are neither side's.
func (w wording) cutOff(s CompareSnapshot, gone CompareSide, later bool) string {
	first, end := *gone.NoRecordBefore, gone.AskedUntil
	if !first.Before(end) {
		return ""
	}
	which, went := "earlier", "on neither side"
	switch {
	case later:
		which = "later"
	case !s.B.Since.After(first):
		went = "in " + w.b
	}
	return fmt.Sprintf("; the roll-up keeps whole UTC days, so the jobs queued from %s to %s, the %s period's last hours, are counted %s",
		stamp(first), stamp(end), which, went)
}

// coverage is what a side read from the roll-up leaves out, or leaves to the
// other side, each with its cause; the dates alone would be the only other
// place it showed. An unread side's summary says its own.
//
// A side whose counts begin later than asked says the fleet keeps none
// before. Between the sides, hours can be in neither count for one of two
// reasons: the later side's counts begin late, and nothing before them is
// on record; or the roll-up keeps whole UTC days, and the earlier side ends
// at the last midnight it could read whole. The same whole days can start
// the later side at its first midnight, before the period asked for, so the
// earlier side's last hours are counted in it, and end it at its last, so
// the hours after are counted on neither side.
func (w wording) coverage(s CompareSnapshot) []string {
	if s.B.unread() {
		return nil
	}
	late := func(side CompareSide) string {
		return fmt.Sprintf("the fleet keeps no counts from before %s, so %s begins there, later than the period asked for",
			stamp(*side.NoRecordBefore), side.Label)
	}
	var out []string
	// An unread earlier side's summary already says what became of its
	// hours; the later side's own end is still this function's to name.
	if !s.A.unread() {
		if s.A.NoRecordBefore != nil {
			out = append(out, late(s.A))
		}
		between := !s.A.Until.IsZero() && s.A.Until.Before(s.B.Since)
		switch {
		case between && s.B.NoRecordBefore != nil:
			out = append(out, fmt.Sprintf("the fleet keeps no counts from before %s, so the hours from %s to %s, between the two periods, are counted on neither side",
				stamp(*s.B.NoRecordBefore), stamp(s.A.Until), stamp(s.B.Since)))
		case s.B.NoRecordBefore != nil:
			out = append(out, late(s.B))
		case between && s.A.CountsOnly:
			out = append(out, fmt.Sprintf("the roll-up keeps whole UTC days, so the jobs queued from %s to %s, between the two periods, are counted on neither side",
				stamp(s.A.Until), stamp(s.B.Since)))
		}
		// The later side read from its first midnight begins before the
		// period asked for, so the earlier side's last hours are its own.
		if s.B.CountsOnly && s.B.Since.Before(s.A.AskedUntil) {
			out = append(out, fmt.Sprintf("the roll-up keeps whole UTC days, so %s begins earlier than the period asked for, and the jobs queued from %s to %s are counted in it, not in %s",
				s.B.Label, stamp(s.B.Since), stamp(s.A.AskedUntil), s.A.Label))
		}
	}
	// The later side ended at the last midnight the roll-up read whole, and
	// nothing comes after it to count the rest.
	if s.B.CountsOnly && s.B.Until.Before(s.B.AskedUntil) {
		out = append(out, fmt.Sprintf("the roll-up keeps whole UTC days, so %s ends earlier than the period asked for, and the jobs queued from %s to %s, after its last whole day, are counted on neither side",
			s.B.Label, stamp(s.B.Until), stamp(s.B.AskedUntil)))
	}
	return out
}

func slotWords(n float64) string {
	return strconv.FormatFloat(math.Round(n*10)/10, 'f', -1, 64)
}

// percent is a rate as a whole percentage, the way the Usage table shows it.
func percent(events int, jobs int64) string {
	return fmt.Sprintf("%d%%", int(math.Round(float64(events)*100/float64(jobs))))
}

func msFloat(v *int64) *float64 {
	if v == nil {
		return nil
	}
	f := float64(*v)
	return &f
}

func round(v, places float64) *float64 {
	r := math.Round(v*places) / places
	return &r
}

func abs(v int64) int64 {
	if v < 0 {
		return -v
	}
	return v
}

package analysis

import (
	"encoding/json"
	"slices"
	"strings"
	"testing"
	"time"
)

var compareBase = time.Date(2026, 10, 11, 8, 0, 0, 0, time.UTC)

func msp(d time.Duration) *int64 { v := d.Milliseconds(); return &v }

func spread(samples int, p50, p95 time.Duration) Spread {
	return Spread{Samples: samples, P50MS: msp(p50), P95MS: msp(p95)}
}

func slots(n float64) *float64 { return &n }

// side is a release that ran jobs jobs, every one of them succeeding, with
// the same figures as every other side this builds, so a test changes only
// the measure it is about.
func side(label string, jobs int) CompareSide {
	return CompareSide{Label: label, Since: compareBase, Until: compareBase.Add(24 * time.Hour),
		Figures: JobFigures{Jobs: jobs, Succeeded: jobs,
			Duration:  spread(jobs, time.Minute, 5*time.Minute),
			QueueWait: spread(jobs, 5*time.Second, 20*time.Second),
			Startup:   spread(jobs, 8*time.Second, 15*time.Second)},
		MeanSlots: slots(10)}
}

func releases(a, b int) CompareSnapshot {
	return CompareSnapshot{By: "version", A: side("v1.3.2", a), B: side("v1.3.3", b)}
}

func periods(a, b int) CompareSnapshot {
	s := CompareSnapshot{By: "period", A: side("the 24 hours before", a), B: side("the last 24 hours", b)}
	s.A.Since, s.A.Until = compareBase.Add(-24*time.Hour), compareBase
	return s
}

func mustCompare(t *testing.T, s CompareSnapshot) CompareFinding {
	t.Helper()
	f, err := Compare(s)
	if err != nil {
		t.Fatal(err)
	}
	assertNoCommand(t, f.NextSteps)
	return f
}

func change(t *testing.T, f CompareFinding, measure string) Change {
	t.Helper()
	for _, c := range f.Evidence.Changes {
		if c.Measure == measure {
			return c
		}
	}
	t.Fatalf("no change for %s in %+v", measure, f.Evidence.Changes)
	return Change{}
}

func hasSetting(steps []NextStep, setting string) bool {
	return slices.ContainsFunc(steps, func(s NextStep) bool { return s.Setting == setting })
}

func TestCompareRefusesToRankFewerThanThirtyJobsOnEitherSide(t *testing.T) {
	s := releases(15, 20)
	// A move this large would be ranked on a bigger sample; under thirty jobs
	// it could be three slow runs, and naming it would send someone to roll
	// back a release over noise.
	s.B.Figures.Duration = spread(20, time.Minute, 20*time.Minute)
	f := mustCompare(t, s)
	if f.Confidence != Low || f.ConfidenceReason == "" || f.Dominant != "" {
		t.Errorf("confidence %q (%q), dominant %q; want low with a reason and nothing dominant", f.Confidence, f.ConfidenceReason, f.Dominant)
	}
	if want := "v1.3.2 ran 15 jobs and v1.3.3 ran 20 in this period: fewer than 30 on either side, so the two are not ranked."; f.Summary != want {
		t.Errorf("summary\n got %q\nwant %q", f.Summary, want)
	}
	if len(f.Evidence.Changes) != 9 {
		t.Fatalf("%d changes, want one for each of the nine measures", len(f.Evidence.Changes))
	}
	for _, c := range f.Evidence.Changes {
		if c.Direction != NotEnough {
			t.Errorf("%s is %s, want not_enough", c.Measure, c.Direction)
		}
	}
	if hasSetting(f.NextSteps, "updates.mode") || len(f.Codes) != 0 {
		t.Errorf("a comparison that ranks nothing names a regression's steps: %+v, codes %v", f.NextSteps, f.Codes)
	}
	// The window is bounded by limits.job_stats_window, so a reader told to
	// widen it is told where the ceiling is.
	if len(f.NextSteps) != 1 || f.NextSteps[0].Setting != "limits.job_stats_window" {
		t.Errorf("next steps %+v, want one naming limits.job_stats_window", f.NextSteps)
	}
}

// The commonest comparison is a release a few hours old against the one
// before it: hundreds of jobs on one side, a dozen on the other. Saying both
// were short would be false of the side that ran hundreds.
func TestASmallSampleNamesTheSideThatIsShort(t *testing.T) {
	for _, c := range []struct {
		snap CompareSnapshot
		want string
	}{
		{releases(400, 12), "v1.3.2 ran 400 jobs and v1.3.3 ran 12 in this period: fewer than 30 under v1.3.3, so the two are not ranked."},
		{releases(12, 400), "v1.3.2 ran 12 jobs and v1.3.3 ran 400 in this period: fewer than 30 under v1.3.2, so the two are not ranked."},
		{releases(12, 15), "v1.3.2 ran 12 jobs and v1.3.3 ran 15 in this period: fewer than 30 on either side, so the two are not ranked."},
		{periods(400, 12), "400 jobs ran in the 24 hours before and 12 in the last 24 hours: fewer than 30 in the last 24 hours, so the two are not ranked."},
		{periods(12, 400), "12 jobs ran in the 24 hours before and 400 in the last 24 hours: fewer than 30 in the 24 hours before, so the two are not ranked."},
	} {
		f := mustCompare(t, c.snap)
		if f.Summary != c.want {
			t.Errorf("summary\n got %q\nwant %q", f.Summary, c.want)
		}
		if f.Confidence != Low || f.ConfidenceReason+", so the two are not ranked." != c.want {
			t.Errorf("confidence %q, reason %q; want low, and the reason the summary gives", f.Confidence, f.ConfidenceReason)
		}
	}
}

// Each bar is met by a move of exactly its size: a quarter longer and the
// floor apart both count, and a fleet exactly a quarter larger is still
// like for like.
func TestAMoveOfExactlyItsBarCounts(t *testing.T) {
	s := releases(120, 120)
	s.A.Figures.Duration = spread(120, 2*time.Minute, 5*time.Minute)
	s.B.Figures.Duration = spread(120, 2*time.Minute+30*time.Second, 5*time.Minute) // 1.25 times, 30s apart
	s.B.MeanSlots = slots(12.5)
	f := mustCompare(t, s)
	if got := change(t, f, "duration_p50").Direction; got != Regressed {
		t.Errorf("duration p50 2m to 2m 30s is %s, want regressed", got)
	}
	if f.Confidence != High {
		t.Errorf("10 and 12.5 slots: confidence %q (%q), want high", f.Confidence, f.ConfidenceReason)
	}
}

// When two measures moved as far as each other, the measures' own order
// decides the lead, so one snapshot always reads the same way.
func TestATieLeadsWithTheMeasureListedFirst(t *testing.T) {
	s := releases(120, 120)
	s.B.Figures.Startup = spread(120, 8*time.Second, 30*time.Second)   // twice as long at p95
	s.B.Figures.QueueWait = spread(120, 5*time.Second, 40*time.Second) // twice as long at p95
	for range 5 {
		if f := mustCompare(t, s); f.Dominant != "queue_wait_p95" {
			t.Fatalf("dominant %q, want queue_wait_p95, listed before startup_p95, which doubled as well", f.Dominant)
		}
	}
}

func TestCompareNamesTheLargestRegression(t *testing.T) {
	s := releases(120, 120)
	s.B.Figures.Duration = spread(120, time.Minute, 9*time.Minute)
	f := mustCompare(t, s)
	if f.Confidence != High || f.ConfidenceReason != "" {
		t.Errorf("confidence %q (%q), want high with no reason", f.Confidence, f.ConfidenceReason)
	}
	if f.Dominant != "duration_p95" {
		t.Errorf("dominant %q, want duration_p95", f.Dominant)
	}
	if want := "v1.3.3 is worse than v1.3.2 on duration p95 (5m to 9m)."; f.Summary != want {
		t.Errorf("summary\n got %q\nwant %q", f.Summary, want)
	}
	c := change(t, f, "duration_p95")
	if c.Direction != Regressed || c.Unit != "ms" || *c.From != 300000 || *c.To != 540000 || c.Ratio == nil || *c.Ratio != 1.8 {
		t.Errorf("duration_p95 change %+v, want regressed ms 300000 to 540000, ratio 1.8", c)
	}
	if len(f.NextSteps) == 0 || f.NextSteps[0].Code != "jobs.duration_regressed" {
		t.Fatalf("next steps %+v, want the first to name jobs.duration_regressed", f.NextSteps)
	}
	if !hasSetting(f.NextSteps, "updates.mode") {
		t.Errorf("next steps %+v name no updates.mode, though a release regressed", f.NextSteps)
	}
	if !slices.Contains(f.Codes, "jobs.duration_regressed") {
		t.Errorf("codes %v leave out jobs.duration_regressed", f.Codes)
	}
}

func TestCompareSaysWhatImproved(t *testing.T) {
	s := releases(120, 120)
	s.A.Figures.QueueWait = spread(120, 40*time.Second, time.Minute)
	s.B.Figures.QueueWait = spread(120, 10*time.Second, time.Minute)
	f := mustCompare(t, s)
	if f.Dominant != "queue_wait_p50" {
		t.Errorf("dominant %q, want queue_wait_p50", f.Dominant)
	}
	if want := "v1.3.3 is better than v1.3.2 on queue wait p50 (40s to 10s)."; f.Summary != want {
		t.Errorf("summary\n got %q\nwant %q", f.Summary, want)
	}
	if c := change(t, f, "queue_wait_p50"); c.Direction != Improved || c.Ratio == nil || *c.Ratio != 4 {
		t.Errorf("queue_wait_p50 change %+v, want improved by a factor of 4", c)
	}
	// Holding updates over an improvement would keep a fleet on the worse
	// release.
	if hasSetting(f.NextSteps, "updates.mode") {
		t.Errorf("next steps %+v hold updates though nothing regressed", f.NextSteps)
	}
}

func TestCompareIgnoresAMoveSmallerThanItsFloor(t *testing.T) {
	for _, c := range []struct {
		name     string
		measure  string
		from, to time.Duration
	}{
		// 1.4 times as long, but four seconds is not a regression anyone
		// should chase.
		{"past the ratio, under the floor", "duration_p50", 10 * time.Second, 14 * time.Second},
		// Thirty seconds more on a five-minute job is a tenth, not a quarter.
		{"past the floor, under the ratio", "duration_p95", 5 * time.Minute, 5*time.Minute + 30*time.Second},
		{"queue wait under its ten-second floor", "queue_wait_p50", 20 * time.Second, 29 * time.Second},
	} {
		t.Run(c.name, func(t *testing.T) {
			s := releases(120, 120)
			if c.measure == "queue_wait_p50" {
				s.A.Figures.QueueWait = spread(120, c.from, time.Minute)
				s.B.Figures.QueueWait = spread(120, c.to, time.Minute)
			} else {
				s.A.Figures.Duration = spread(120, c.from, 5*time.Minute)
				s.B.Figures.Duration = spread(120, c.from, 5*time.Minute)
				if c.measure == "duration_p50" {
					s.B.Figures.Duration.P50MS = msp(c.to)
				} else {
					s.A.Figures.Duration.P95MS, s.B.Figures.Duration.P95MS = msp(c.from), msp(c.to)
				}
			}
			f := mustCompare(t, s)
			if got := change(t, f, c.measure).Direction; got != Unchanged {
				t.Errorf("%s is %s, want unchanged", c.measure, got)
			}
			if want := "v1.3.3 and v1.3.2 ran alike: no measure moved past its threshold."; f.Summary != want {
				t.Errorf("summary\n got %q\nwant %q", f.Summary, want)
			}
			if f.Dominant != "" || f.Confidence != High {
				t.Errorf("dominant %q, confidence %q; want none and high", f.Dominant, f.Confidence)
			}
		})
	}
}

// The store leaves cancelled and skipped jobs out of what it reads for a
// comparison (Task 6 proves that against a real store); the finding has to
// say so, and it can only say what its caller did.
func TestCompareEvidenceNamesTheConclusionsTheReadLeftOut(t *testing.T) {
	s := releases(120, 120)
	s.Excluded = []string{"cancelled", "skipped"}
	if got := mustCompare(t, s).Evidence.Excluded; !slices.Equal(got, []string{"cancelled", "skipped"}) {
		t.Errorf("excluded %v, want [cancelled skipped]", got)
	}
	if got := mustCompare(t, releases(120, 120)).Evidence.Excluded; got == nil || len(got) != 0 {
		t.Errorf("excluded %#v, want an empty list rather than null", got)
	}
}

func TestADifferentlySizedFleetMakesTheComparisonMedium(t *testing.T) {
	s := releases(120, 120)
	s.B.MeanSlots = slots(20)
	f := mustCompare(t, s)
	if f.Confidence != Medium {
		t.Errorf("confidence %q, want medium", f.Confidence)
	}
	if want := "the fleet offered 10 slots under v1.3.2 and 20 under v1.3.3, so queue waits are not like for like"; f.ConfidenceReason != want {
		t.Errorf("reason\n got %q\nwant %q", f.ConfidenceReason, want)
	}
	// A fleet that grew by a fifth is still the same fleet to compare on.
	s.B.MeanSlots = slots(12)
	if f := mustCompare(t, s); f.Confidence != High {
		t.Errorf("10 and 12 slots: confidence %q (%q), want high", f.Confidence, f.ConfidenceReason)
	}
}

func TestAnUnknownFleetSizeMakesTheComparisonMedium(t *testing.T) {
	s := releases(120, 120)
	s.A.MeanSlots = nil
	f := mustCompare(t, s)
	if f.Confidence != Medium {
		t.Errorf("confidence %q, want medium", f.Confidence)
	}
	if !strings.Contains(f.ConfidenceReason, "retention.samples") || !strings.Contains(f.ConfidenceReason, "v1.3.2") {
		t.Errorf("reason %q names neither retention.samples nor the side it is about", f.ConfidenceReason)
	}
}

func TestACountsOnlySideSaysPercentilesAreUnavailable(t *testing.T) {
	s := periods(120, 120)
	// The roll-up keeps how many jobs ran and how many the fleet lost; it
	// has no failures, no OOM kills and no times, so those read zero. Read
	// as figures they would be a fall in failures that never happened.
	s.A.CountsOnly = true
	s.A.Figures = JobFigures{Jobs: 120, FleetFailed: 2}
	s.B.Figures.FleetFailed, s.B.Figures.Failed, s.B.Figures.OOMKilled = 12, 20, 5
	f := mustCompare(t, s)
	for _, c := range f.Evidence.Changes {
		want := NotEnough
		if c.Measure == "fleet_failure_rate" {
			want = Regressed
		}
		if c.Direction != want {
			t.Errorf("%s is %s, want %s", c.Measure, c.Direction, want)
		}
	}
	if !f.Evidence.PercentilesUnavailable {
		t.Error("percentiles_unavailable is false with one side read from the roll-up")
	}
	if f.Confidence != Medium {
		t.Errorf("confidence %q, want medium", f.Confidence)
	}
	for _, want := range []string{"retention.jobs", "percentiles are unavailable", "defined differently"} {
		if !strings.Contains(f.ConfidenceReason, want) {
			t.Errorf("reason %q does not say %q", f.ConfidenceReason, want)
		}
	}
	if want := "Jobs did worse in the last 24 hours than in the 24 hours before on fleet failure rate (2% to 10%)."; f.Summary != want {
		t.Errorf("summary\n got %q\nwant %q", f.Summary, want)
	}

	// With nothing moved, "ran alike" would claim the eight measures it never
	// saw; the sentence says how many could not be compared.
	s.B.Figures.FleetFailed = 2
	if want := "Jobs ran alike in the 24 hours before and the last 24 hours: no measure moved past its threshold, though 8 of 9 could not be compared."; mustCompare(t, s).Summary != want {
		t.Errorf("summary\n got %q\nwant %q", mustCompare(t, s).Summary, want)
	}
}

func TestACompareWithOneSideEmptySaysWhichRanNothing(t *testing.T) {
	for _, c := range []struct {
		a, b int
		want string
	}{
		{120, 0, "v1.3.3 ran no jobs in this period, so there is nothing to compare v1.3.2 with."},
		{0, 120, "v1.3.2 ran no jobs in this period, so there is nothing to compare v1.3.3 with."},
		{0, 0, "Neither v1.3.2 nor v1.3.3 ran a job in this period, so there is nothing to compare."},
	} {
		s := releases(c.a, c.b)
		f := mustCompare(t, s)
		if f.Confidence != Low || f.ConfidenceReason == "" {
			t.Errorf("%d and %d jobs: confidence %q (%q), want low with a reason", c.a, c.b, f.Confidence, f.ConfidenceReason)
		}
		if f.Summary != c.want {
			t.Errorf("%d and %d jobs: summary\n got %q\nwant %q", c.a, c.b, f.Summary, c.want)
		}
	}
}

func TestARateMovesOnlyByFivePointsAndThreeEvents(t *testing.T) {
	for _, c := range []struct {
		name       string
		jobs, a, b int
		want       string
	}{
		{"two and a half points", 120, 0, 3, Unchanged},
		{"five points, six failures", 120, 0, 6, Regressed},
		{"five points, but two failures", 40, 0, 2, Unchanged},
		{"down five points", 120, 10, 4, Improved},
	} {
		t.Run(c.name, func(t *testing.T) {
			s := releases(c.jobs, c.jobs)
			s.A.Figures.Failed, s.B.Figures.Failed = c.a, c.b
			f := mustCompare(t, s)
			if got := change(t, f, "failure_rate").Direction; got != c.want {
				t.Errorf("failure_rate is %s, want %s", got, c.want)
			}
		})
	}
	s := releases(120, 120)
	s.B.Figures.Failed = 6
	f := mustCompare(t, s)
	if want := "v1.3.3 is worse than v1.3.2 on failure rate (0% to 5%)."; f.Summary != want {
		t.Errorf("summary\n got %q\nwant %q", f.Summary, want)
	}
	if c := change(t, f, "failure_rate"); c.Unit != "rate" || c.Ratio == nil || *c.Ratio != 1 {
		t.Errorf("failure_rate change %+v, want unit rate and a ratio of 1 (five points over five)", c)
	}
	if len(f.NextSteps) == 0 || f.NextSteps[0].Code != "jobs.workflow_failing" {
		t.Fatalf("next steps %+v, want the first to name jobs.workflow_failing", f.NextSteps)
	}
	if want := "More jobs failed under v1.3.3 (failure rate 0% to 5%); a failure the fleet did not cause is the workflow's own, and the step each job failed at says what to fix."; f.NextSteps[0].Text != want {
		t.Errorf("step\n got %q\nwant %q", f.NextSteps[0].Text, want)
	}
}

// The catalog's own fix for an OOM kill is the pool's memory, so the step
// names that field rather than leaving the reader to find it.
func TestAnOOMRegressionNamesThePoolsMemory(t *testing.T) {
	s := releases(120, 120)
	s.B.Figures.OOMKilled = 12
	f := mustCompare(t, s)
	if len(f.NextSteps) == 0 || f.NextSteps[0].Code != "jobs.oom_killed" || f.NextSteps[0].Setting != "pool.resources.memory_mb" {
		t.Errorf("next steps %+v, want the first to name jobs.oom_killed and pool.resources.memory_mb", f.NextSteps)
	}
}

func TestTheLeadIsTheRegressionThatMovedFurthest(t *testing.T) {
	s := releases(120, 120)
	s.B.Figures.Duration = spread(120, time.Minute, 9*time.Minute) // 1.8 times
	s.B.Figures.FleetFailed, s.B.Figures.Failed = 12, 12           // ten points: twice the five-point bar
	f := mustCompare(t, s)
	if f.Dominant != "fleet_failure_rate" {
		t.Errorf("dominant %q, want fleet_failure_rate, which moved twice its bar against duration's 1.8", f.Dominant)
	}
	var codes []string
	for _, st := range f.NextSteps {
		codes = append(codes, st.Code)
	}
	if want := []string{"jobs.runner_lost", "jobs.workflow_failing", "jobs.duration_regressed", ""}; !slices.Equal(codes, want) {
		t.Errorf("step codes %q, want %q: one step per regressed measure family, largest first, then hold updates", codes, want)
	}

	// A wait that went from nothing to twenty seconds has no finite ratio,
	// and is the furthest any measure can move.
	s = releases(120, 120)
	s.B.Figures.Duration = spread(120, time.Minute, 9*time.Minute)
	s.A.Figures.QueueWait = spread(120, 0, 20*time.Second)
	s.B.Figures.QueueWait = spread(120, 20*time.Second, 20*time.Second)
	f = mustCompare(t, s)
	if c := change(t, f, "queue_wait_p50"); c.Direction != Regressed || c.Ratio != nil {
		t.Errorf("queue_wait_p50 change %+v, want regressed with no ratio", c)
	}
	if f.Dominant != "queue_wait_p50" {
		t.Errorf("dominant %q, want queue_wait_p50", f.Dominant)
	}
}

func TestCompareSaysHowManyMoreMovedTheSameWay(t *testing.T) {
	s := releases(120, 120)
	s.B.Figures.Duration = spread(120, 2*time.Minute, 9*time.Minute)
	s.B.Figures.QueueWait = spread(120, 5*time.Second, 30*time.Second)
	// An improvement is not counted among the regressions.
	s.A.Figures.Startup = spread(120, 40*time.Second, 50*time.Second)
	// Duration p50 moved 2 times, p95 1.8 times, queue wait p95 1.5 times.
	f := mustCompare(t, s)
	if want := "v1.3.3 is worse than v1.3.2 on duration p50 (1m to 2m), and on 2 more."; f.Summary != want {
		t.Errorf("summary\n got %q\nwant %q", f.Summary, want)
	}
	// Two duration percentiles that both got worse are one thing to read
	// about, not two steps saying the same.
	var codes []string
	for _, st := range f.NextSteps {
		codes = append(codes, st.Code)
	}
	if want := []string{"jobs.duration_regressed", "pool.queue_wait_high", ""}; !slices.Equal(codes, want) {
		t.Errorf("step codes %q, want %q", codes, want)
	}
	if !strings.Contains(f.NextSteps[0].Text, "duration p50 1m to 2m") {
		t.Errorf("first step %q does not give the figures of the measure that led", f.NextSteps[0].Text)
	}
}

func TestFewerThanAHundredJobsASideMakesTheComparisonMedium(t *testing.T) {
	f := mustCompare(t, releases(60, 120))
	if f.Confidence != Medium {
		t.Errorf("confidence %q, want medium", f.Confidence)
	}
	if want := "v1.3.2 ran 60 jobs and v1.3.3 ran 120 in this period: fewer than 100 on a side, so a change named here is less certain"; f.ConfidenceReason != want {
		t.Errorf("reason\n got %q\nwant %q", f.ConfidenceReason, want)
	}
}

func TestATimeMeasureWithFewerThanThirtySamplesIsNotEnough(t *testing.T) {
	s := releases(120, 120)
	// Most jobs ran too briefly for a runner's startup to be measured.
	s.B.Figures.Startup = spread(20, time.Minute, 2*time.Minute)
	f := mustCompare(t, s)
	for _, m := range []string{"startup_p50", "startup_p95"} {
		if c := change(t, f, m); c.Direction != NotEnough || c.Ratio != nil {
			t.Errorf("%s change %+v, want not_enough with no ratio", m, c)
		}
	}
	if f.Dominant != "" {
		t.Errorf("dominant %q, want none", f.Dominant)
	}
}

func TestJobsGonePastRetentionMakeTheComparisonMedium(t *testing.T) {
	s := releases(120, 120)
	gone := time.Date(2026, 10, 9, 14, 0, 0, 0, time.UTC)
	s.A.JobsGoneBefore = &gone
	f := mustCompare(t, s)
	if f.Confidence != Medium {
		t.Errorf("confidence %q, want medium", f.Confidence)
	}
	if want := "v1.3.2's jobs from before 2026-10-09 14:00 UTC are gone (retention.jobs keeps them for a set time, and raising it keeps more next time), so v1.3.2's figures cover only the jobs still kept"; f.ConfidenceReason != want {
		t.Errorf("reason\n got %q\nwant %q", f.ConfidenceReason, want)
	}
}

// A side read from the roll-up ends at the last midnight it read whole, so
// when that falls before the other side begins, the jobs between are in
// neither count; an operator comparing the two must be told, because the
// dates alone are the only other place it shows.
func TestACountsOnlySideNamesTheHoursCountedOnNeitherSide(t *testing.T) {
	gap := "the roll-up keeps whole UTC days, so the jobs queued from 2026-10-11 05:00 UTC to 2026-10-11 08:00 UTC, between the two periods, are counted on neither side"
	for _, n := range []int{120, 15} {
		s := periods(n, n)
		s.A.Label, s.A.CountsOnly = "the 2 days before", true
		s.A.Since, s.A.Until = compareBase.Add(-51*time.Hour), compareBase.Add(-3*time.Hour)
		s.A.Figures = JobFigures{Jobs: n, FleetFailed: 1}
		f := mustCompare(t, s)
		if !strings.Contains(f.ConfidenceReason, gap) {
			t.Errorf("%d jobs a side: reason %q does not name the hours counted on neither side", n, f.ConfidenceReason)
		}
		s.A.Until = s.B.Since
		if f := mustCompare(t, s); strings.Contains(f.ConfidenceReason, "neither side") {
			t.Errorf("%d jobs a side, sides that meet: reason %q names a gap", n, f.ConfidenceReason)
		}
	}
}

// A side the fleet keeps no counts for is not a side where no jobs ran: on a
// fleet whose oldest rows were pruned before the roll-up first ran, jobs did
// run, and nobody can now say how many.
func TestASideTheFleetKeepsNoCountsForIsNotOneWhereNoJobsRan(t *testing.T) {
	first := compareBase.Add(8 * time.Hour)
	s := periods(0, 15)
	s.A.CountsOnly, s.A.Since, s.A.Until, s.A.NoRecordBefore = true, compareBase, compareBase, &first
	s.B.CountsOnly, s.B.Since, s.B.NoRecordBefore = true, first, &first
	s.B.Label = "the 16 hours to 2026-10-12 08:00 UTC"
	f := mustCompare(t, s)
	if want := "The fleet keeps no counts from before 2026-10-11 16:00 UTC, so the 24 hours before could not be read, and there is nothing to compare the 16 hours to 2026-10-12 08:00 UTC with."; f.Summary != want {
		t.Errorf("summary\n got %q\nwant %q", f.Summary, want)
	}
	if want := "the fleet keeps no counts from before 2026-10-11 16:00 UTC, so the 24 hours before could not be read"; f.ConfidenceReason != want || f.Confidence != Low {
		t.Errorf("confidence %s, reason\n got %q\nwant %q", f.Confidence, f.ConfidenceReason, want)
	}
}

// A side whose counts begin later than the period asked for says why, and the
// hours between the sides that no record covers are put down to that, not to
// whole days.
func TestASideWhoseCountsBeginLateSaysTheFleetKeepsNoneBefore(t *testing.T) {
	first := compareBase.Add(-30 * time.Hour)
	s := periods(15, 20)
	s.A.CountsOnly, s.A.Since, s.A.Until, s.A.NoRecordBefore = true, first, compareBase, &first
	s.A.Label = "the 30 hours before"
	f := mustCompare(t, s)
	if want := "the fleet keeps no counts from before 2026-10-10 02:00 UTC, so the 30 hours before begins there, later than the period asked for"; !strings.Contains(f.ConfidenceReason, want) {
		t.Errorf("reason %q does not say %q", f.ConfidenceReason, want)
	}

	later := compareBase.Add(5 * time.Hour)
	s = periods(15, 20)
	s.A.CountsOnly, s.A.Until = true, compareBase.Add(-3*time.Hour)
	s.B.CountsOnly, s.B.Since, s.B.NoRecordBefore = true, later, &later
	f = mustCompare(t, s)
	if want := "the fleet keeps no counts from before 2026-10-11 13:00 UTC, so the hours from 2026-10-11 05:00 UTC to 2026-10-11 13:00 UTC, between the two periods, are counted on neither side"; !strings.Contains(f.ConfidenceReason, want) {
		t.Errorf("reason %q does not say %q", f.ConfidenceReason, want)
	}
	if strings.Contains(f.ConfidenceReason, "whole UTC days") || strings.Contains(f.ConfidenceReason, "begins there") {
		t.Errorf("reason %q blames whole days, or says the gap twice", f.ConfidenceReason)
	}
}

// A side read from the roll-up can end before the end asked for. The hours
// between are then the other side's, or neither side's, and the finding says
// which: a label naming the span read differs from the request whenever
// anything is cut, so it cannot say it alone.
func TestASideEndingBeforeTheEndAskedForSaysWhereThoseHoursWent(t *testing.T) {
	s := periods(15, 20)
	s.A.CountsOnly, s.B.CountsOnly = true, true
	s.A.AskedUntil = compareBase.Add(6 * time.Hour)
	s.B.Label, s.B.AskedUntil = "the 24 hours to 2026-10-12 08:00 UTC", s.B.Until.Add(6*time.Hour)
	f := mustCompare(t, s)
	for _, want := range []string{
		"the roll-up keeps whole UTC days, so the 24 hours to 2026-10-12 08:00 UTC begins earlier than the period asked for, " +
			"and the jobs queued from 2026-10-11 08:00 UTC to 2026-10-11 14:00 UTC are counted in it, not in the 24 hours before",
		"the roll-up keeps whole UTC days, so the 24 hours to 2026-10-12 08:00 UTC ends earlier than the period asked for, " +
			"and the jobs queued from 2026-10-12 08:00 UTC to 2026-10-12 14:00 UTC, after its last whole day, are counted on neither side",
	} {
		if !strings.Contains(f.ConfidenceReason, want) {
			t.Errorf("reason %q does not say %q", f.ConfidenceReason, want)
		}
	}

	// An earlier side that could not be read says where the fleet's counts
	// begin and what became of its hours from there to its asked end.
	first := compareBase.Add(-4 * time.Hour)
	for name, c := range map[string]struct {
		bSince time.Time
		went   string
	}{
		"in the later side": {first, "are counted in the last 24 hours."},
		"on neither side":   {compareBase, "are counted on neither side."},
	} {
		s := periods(0, 20)
		s.A.CountsOnly, s.A.Since, s.A.Until, s.A.NoRecordBefore = true, first.Truncate(24*time.Hour), first.Truncate(24*time.Hour), &first
		s.A.AskedUntil, s.B.Since = compareBase, c.bSince
		f := mustCompare(t, s)
		want := "The fleet keeps no counts from before 2026-10-11 04:00 UTC, so the 24 hours before could not be read, and there is nothing to compare the last 24 hours with; " +
			"the roll-up keeps whole UTC days, so the jobs queued from 2026-10-11 04:00 UTC to 2026-10-11 08:00 UTC, the earlier period's last hours, " + c.went
		if f.Summary != want {
			t.Errorf("%s: summary\n got %q\nwant %q", name, f.Summary, want)
		}
	}

	// With the counts beginning inside the later side's last asked hours,
	// neither side could be read, and those hours are on record all the same.
	later := compareBase.Add(20 * time.Hour)
	s = periods(0, 0)
	s.A.CountsOnly, s.A.Since, s.A.Until, s.A.NoRecordBefore = true, compareBase, compareBase, &later
	s.B.CountsOnly, s.B.Since, s.B.Until, s.B.NoRecordBefore = true, compareBase.Add(16*time.Hour), compareBase.Add(16*time.Hour), &later
	s.B.AskedUntil = compareBase.Add(24 * time.Hour)
	f = mustCompare(t, s)
	if want := "The fleet keeps no counts from before 2026-10-12 04:00 UTC, so neither the 24 hours before nor the last 24 hours could be read, and there is nothing to compare; " +
		"the roll-up keeps whole UTC days, so the jobs queued from 2026-10-12 04:00 UTC to 2026-10-12 08:00 UTC, the later period's last hours, are counted on neither side."; f.Summary != want {
		t.Errorf("neither read: summary\n got %q\nwant %q", f.Summary, want)
	}
}

func TestAPeriodComparisonIsWordedForPeriods(t *testing.T) {
	s := periods(120, 120)
	s.B.Figures.Duration = spread(120, time.Minute, 9*time.Minute)
	f := mustCompare(t, s)
	if want := "Jobs did worse in the last 24 hours than in the 24 hours before on duration p95 (5m to 9m)."; f.Summary != want {
		t.Errorf("summary\n got %q\nwant %q", f.Summary, want)
	}
	// Updates are held over a release, not over a bad day.
	if hasSetting(f.NextSteps, "updates.mode") {
		t.Errorf("a period comparison holds updates: %+v", f.NextSteps)
	}
	if !f.Since.Equal(s.A.Since) || !f.Until.Equal(s.B.Until) {
		t.Errorf("finding covers %v to %v, want %v to %v", f.Since, f.Until, s.A.Since, s.B.Until)
	}
	if want := "15 jobs ran in the 24 hours before and 20 in the last 24 hours: fewer than 30 on either side, so the two are not ranked."; mustCompare(t, periods(15, 20)).Summary != want {
		t.Errorf("summary\n got %q\nwant %q", mustCompare(t, periods(15, 20)).Summary, want)
	}
	if want := "No jobs ran in the last 24 hours, so there is nothing to compare the 24 hours before with."; mustCompare(t, periods(120, 0)).Summary != want {
		t.Errorf("summary\n got %q\nwant %q", mustCompare(t, periods(120, 0)).Summary, want)
	}
}

func TestCompareRefusesASnapshotItCannotRead(t *testing.T) {
	for name, edit := range map[string]func(*CompareSnapshot){
		"an unknown by":       func(s *CompareSnapshot) { s.By = "release" },
		"a side with no name": func(s *CompareSnapshot) { s.B.Label = "" },
		"a side that ends before it starts": func(s *CompareSnapshot) {
			s.A.Until = s.A.Since.Add(-time.Hour)
		},
		// A period past retention.jobs is read from the roll-up, which keeps
		// every day's counts, so no jobs of a period side are ever gone; a
		// snapshot that says so was assembled wrong, and wording it would
		// state something the fleet does not do.
		"a period side cut short by retention": func(s *CompareSnapshot) {
			s.By = "period"
			gone := s.B.Since.Add(time.Hour)
			s.B.JobsGoneBefore = &gone
		},
	} {
		s := releases(120, 120)
		edit(&s)
		if _, err := Compare(s); err == nil {
			t.Errorf("%s: no error", name)
		}
	}
}

// Cancelled jobs are left out of the read, so a cancelled count would always
// be 0, and a 0 in the evidence reads as a measurement of none cancelled.
// What was left out is said once, in excluded.
func TestASidesFiguresCarryNoCancelledCount(t *testing.T) {
	body, err := json.Marshal(JobFigures{})
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(body), `"cancelled"`) {
		t.Errorf("figures %s carry a cancelled count", body)
	}
}

package analysis

import (
	"strconv"
	"strings"
)

// RootDependencies is a reviewed public whitelist independent of private parser
// and store types. Null counts mean unsupported inspection, never known zero.
type RootDependencies struct {
	Version      string                    `json:"version"`
	Basis        string                    `json:"basis"`
	SourceSHA256 string                    `json:"source_sha256"`
	Coverage     string                    `json:"coverage"`
	Counts       *RootDependencyCounts     `json:"counts"`
	RowsOmitted  *bool                     `json:"rows_omitted"`
	References   []RootDependencyReference `json:"references"`
}
type RootDependencyCounts struct {
	Declarations *int `json:"declarations"`
	CommitPins   *int `json:"commit_pins"`
	DigestPins   *int `json:"digest_pins"`
	Floating     *int `json:"floating"`
	Local        *int `json:"local"`
	Expressions  *int `json:"expressions"`
	Unknown      *int `json:"unknown"`
}
type RootDependencyReference struct {
	JobIndex        *int    `json:"job_index"`
	StepIndex       *int    `json:"step_index"`
	Line            *int    `json:"line"`
	Declaration     string  `json:"declaration"`
	Kind            string  `json:"kind"`
	Pin             string  `json:"pin"`
	ReferenceSHA256 string  `json:"reference_sha256"`
	Revision        *string `json:"revision"`
}

const RootDependencyRows = 50

func dependencyHex(s string, n int) bool {
	if len(s) != n {
		return false
	}
	for _, r := range s {
		if !(r >= '0' && r <= '9' || r >= 'a' && r <= 'f') {
			return false
		}
	}
	return true
}
func ValidRootDependencies(e *RootDependencies, digest string) bool {
	if e == nil {
		return true
	}
	if e.Version != "root-dependencies-v1" || e.Basis != "root_uses_declarations" || e.SourceSHA256 != digest || !dependencyHex(digest, 64) || e.RowsOmitted == nil || e.References == nil || len(e.References) > RootDependencyRows {
		return false
	}
	if e.Coverage == "unsupported" {
		return e.Counts == nil && !*e.RowsOmitted && len(e.References) == 0
	}
	c := e.Counts
	if e.Coverage != "enumerated" || c == nil {
		return false
	}
	values := []*int{c.Declarations, c.CommitPins, c.DigestPins, c.Floating, c.Local, c.Expressions, c.Unknown}
	for _, v := range values {
		if v == nil || *v < 0 || *v > 10000 {
			return false
		}
	}
	n := *c.Declarations
	counts := map[string]int{"commit": *c.CommitPins, "digest": *c.DigestPins, "floating": *c.Floating, "local": *c.Local, "expression": *c.Expressions, "unknown": *c.Unknown}
	total := 0
	for _, v := range counts {
		total += v
	}
	if n != total || n < len(e.References) || *e.RowsOmitted != (n > len(e.References)) {
		return false
	}
	seen := map[string]bool{}
	shown := map[string]int{}
	for _, r := range e.References {
		if r.JobIndex == nil || r.StepIndex == nil || r.Line == nil || *r.JobIndex < 0 || *r.JobIndex > 20000 || *r.StepIndex < -1 || *r.StepIndex > 20000 || *r.Line < 1 || *r.Line > 262144 || !dependencyHex(r.ReferenceSHA256, 64) {
			return false
		}
		key := strconv.Itoa(*r.JobIndex) + ":" + strconv.Itoa(*r.StepIndex)
		if seen[key] {
			return false
		}
		seen[key] = true
		if r.Declaration == "job_workflow" {
			if *r.StepIndex != -1 {
				return false
			}
		} else if r.Declaration != "step_action" || *r.StepIndex < 0 {
			return false
		}
		kind := "unknown"
		switch r.Kind {
		case "remote":
			if r.Pin != "commit" && r.Pin != "floating" {
				return false
			}
			kind = r.Pin
		case "docker":
			if r.Declaration != "step_action" || r.Pin != "digest" && r.Pin != "floating" {
				return false
			}
			kind = r.Pin
		case "local", "expression", "unknown":
			if r.Pin != "unresolved" {
				return false
			}
			kind = r.Kind
		default:
			return false
		}
		if r.Pin == "commit" {
			if r.Revision == nil || !dependencyHex(*r.Revision, 40) {
				return false
			}
		} else if r.Pin == "digest" {
			if r.Revision == nil || !strings.HasPrefix(*r.Revision, "sha256:") || !dependencyHex(strings.TrimPrefix(*r.Revision, "sha256:"), 64) {
				return false
			}
		} else if r.Revision != nil {
			return false
		}
		shown[kind]++
	}
	for kind, v := range counts {
		if v < shown[kind] || v-shown[kind] > n-len(e.References) {
			return false
		}
	}
	return true
}

package analysis

import (
	"strings"
