)

func dependencyPointer[T any](v T) *T { return &v }
func dependencyEvidenceFixture() *RootDependencies {
	return &RootDependencies{Version: "root-dependencies-v1", Basis: "root_uses_declarations", SourceSHA256: strings.Repeat("c", 64), Coverage: "enumerated", RowsOmitted: dependencyPointer(false), Counts: &RootDependencyCounts{Declarations: dependencyPointer(1), CommitPins: dependencyPointer(1), DigestPins: dependencyPointer(0), Floating: dependencyPointer(0), Local: dependencyPointer(0), Expressions: dependencyPointer(0), Unknown: dependencyPointer(0)}, References: []RootDependencyReference{{JobIndex: dependencyPointer(0), StepIndex: dependencyPointer(0), Line: dependencyPointer(6), Declaration: "step_action", Kind: "remote", Pin: "commit", ReferenceSHA256: strings.Repeat("d", 64), Revision: dependencyPointer(strings.Repeat("a", 40))}}}
}
func TestDependencyViewsRequireBoundCountsAndKnownPositionsWithoutDefaultingMissingFacts(t *testing.T) {
	for _, mode := range []string{"valid", "version", "binding", "missing_count", "count", "missing_position", "position", "revision", "fingerprint", "omission"} {
		e := dependencyEvidenceFixture()
		switch mode {
		case "version":
			e.Version = "future"
		case "binding":
			e.SourceSHA256 = strings.Repeat("b", 64)
		case "missing_count":
			e.Counts.Floating = nil
		case "count":
			*e.Counts.CommitPins = 0
		case "missing_position":
			e.References[0].JobIndex = nil
		case "position":
			*e.References[0].StepIndex = -1
		case "revision":
			e.References[0].Revision = nil
		case "fingerprint":
			e.References[0].ReferenceSHA256 = "private"
		case "omission":
			*e.RowsOmitted = true
		}
		if ValidRootDependencies(e, strings.Repeat("c", 64)) != (mode == "valid") {
			t.Fatalf("%s validated incorrectly", mode)
		}
	}
	e := dependencyEvidenceFixture()
	e.References = []RootDependencyReference{}
	*e.RowsOmitted = true
	if !ValidRootDependencies(e, e.SourceSHA256) {
		t.Fatal("valid summary truncation refused")
	}
	e.Coverage = "unsupported"
	e.Counts = nil
	*e.RowsOmitted = false
	if !ValidRootDependencies(e, e.SourceSHA256) {
		t.Fatal("unsupported unknown became invalid or zero")
	}
}

package analysis

import (
	"fmt"
	"slices"
	"strings"
	"time"
)

// A version is fixed before looking at a cohort; changing the sample rule
// after seeing its failures would let a caller choose the answer.
const ExperimentRuleVersion = "selected-runs-v2"
const MinExperimentSamples = 30
const MaxExperimentAttempts = 2000

type ExperimentAttempt struct {
	SourceRevision string `json:"source_revision"`
	WorkflowID     int64  `json:"workflow_id"`
	// Nil is missing evidence; zero is an observed zero. Consumption stays
	// attached to failed and excluded attempts rather than disappearing.
	LatencyMS       *int64    `json:"latency_ms"`
	ExecutionMS     *int64    `json:"execution_ms"`
	AllocatedIdleMS *int64    `json:"allocated_idle_ms"`
	RunID           int64     `json:"run_id"`
	Attempt         int       `json:"attempt"`
	ObservedAt      time.Time `json:"observed_at"`
	Outcome         string    `json:"outcome"`
	Cache           string    `json:"cache"`
	HostCondition   string    `json:"host_condition"`
}

type ExperimentArm struct {
	SourceRevision   string `json:"source_revision"`
	WorkflowRevision string `json:"workflow_revision"`
	InputsID         string `json:"inputs_id"`
	TestScopeID      string `json:"test_scope_id"`
	ConfigurationID  string `json:"configuration_id"`
	ImageID          string `json:"image_id"`
	ResourceID       string `json:"resource_id"`
	// The controller must verify this against its retained selection, including
	// failed attempts. The pure calculation cannot discover omitted runs.
	SelectionComplete bool                `json:"selection_complete"`
	Attempts          []ExperimentAttempt `json:"attempts"`
}

type ExperimentSnapshot struct {
	RuleVersion     string        `json:"rule_version"`
	Kind            string        `json:"kind"`
	Repository      string        `json:"repository"`
	InitiatingUser  string        `json:"initiating_user"`
	Hypothesis      string        `json:"hypothesis"`
	IntendedDelta   string        `json:"intended_delta"`
	EvidenceID      string        `json:"evidence_id"`
	RevisionDeltaID string        `json:"revision_delta_id"`
	Since           time.Time     `json:"since"`
	Until           time.Time     `json:"until"`
	Baseline        ExperimentArm `json:"baseline"`
	Candidate       ExperimentArm `json:"candidate"`
}

type ExperimentCounts struct {
	Selected   int `json:"selected"`
	Completed  int `json:"completed"`
	Succeeded  int `json:"succeeded"`
	Failed     int `json:"failed"`
	Cancelled  int `json:"cancelled"`
	Superseded int `json:"superseded"`
	Unknown    int `json:"unknown"`
}

type ExperimentEligibility struct {
	RuleVersion    string           `json:"rule_version"`
	State          string           `json:"state"`
	Reasons        []string         `json:"reasons"`
	MinimumSamples int              `json:"minimum_samples"`
	Baseline       ExperimentCounts `json:"baseline"`
	Candidate      ExperimentCounts `json:"candidate"`
}

// AssessExperiment classifies supplied historical evidence. Eligibility is
// permission to compare figures, not proof of causation, improvement or safety.
// The caller retains the snapshot beside this result for reproducibility.
func AssessExperiment(s ExperimentSnapshot) (ExperimentEligibility, error) {
	r := ExperimentEligibility{RuleVersion: ExperimentRuleVersion, State: "eligible", Reasons: []string{}, MinimumSamples: MinExperimentSamples}
	if s.RuleVersion != ExperimentRuleVersion {
		return r, fmt.Errorf("use comparison rule %s", ExperimentRuleVersion)
	}
	if s.Kind != "runner" && s.Kind != "workflow" {
		return r, fmt.Errorf("choose runner or workflow comparison")
	}
	for _, value := range []string{s.Repository, s.InitiatingUser, s.Hypothesis, s.IntendedDelta, s.EvidenceID} {
		if strings.TrimSpace(value) == "" || len(value) > 4096 {
			return r, fmt.Errorf("retain the repository, initiating user, hypothesis, intended delta and evidence identifier within 4096 bytes each")
		}
	}
	if s.Since.IsZero() || !s.Until.After(s.Since) {
		return r, fmt.Errorf("provide an increasing observation window")
	}
	reasons := map[string]bool{}
	if strings.TrimSpace(s.Baseline.InputsID) != "" && strings.TrimSpace(s.Candidate.InputsID) != "" && s.Baseline.InputsID != s.Candidate.InputsID {
		reasons["inputs_mismatch"] = true
	}
	if strings.TrimSpace(s.Baseline.TestScopeID) != "" && strings.TrimSpace(s.Candidate.TestScopeID) != "" && s.Baseline.TestScopeID != s.Candidate.TestScopeID {
		reasons["test_scope_mismatch"] = true
	}
	if s.Kind == "runner" {
		if strings.TrimSpace(s.Baseline.SourceRevision) != "" && strings.TrimSpace(s.Candidate.SourceRevision) != "" && s.Baseline.SourceRevision != s.Candidate.SourceRevision {
			reasons["source_mismatch"] = true
		}
		if strings.TrimSpace(s.Baseline.WorkflowRevision) != "" && strings.TrimSpace(s.Candidate.WorkflowRevision) != "" && s.Baseline.WorkflowRevision != s.Candidate.WorkflowRevision {
			reasons["workflow_mismatch"] = true
		}
	} else if strings.TrimSpace(s.RevisionDeltaID) == "" {
		reasons["revision_delta_missing"] = true
	}
	if len(s.RevisionDeltaID) > 4096 {
		return r, fmt.Errorf("retain a revision delta identifier within 4096 bytes")
	}
	// Identity includes attempt number: a retry consumes resources and is not
	// erased by the success of a later attempt of the same run.
	seen := map[[2]int64]bool{}
	caches := [2]string{}
	for index, arm := range []ExperimentArm{s.Baseline, s.Candidate} {
		for _, field := range []struct{ value, reason string }{{arm.SourceRevision, "source_unknown"}, {arm.WorkflowRevision, "workflow_revision_unknown"}, {arm.InputsID, "inputs_unknown"}, {arm.TestScopeID, "test_scope_unknown"}, {arm.ConfigurationID, "configuration_unknown"}, {arm.ImageID, "image_unknown"}, {arm.ResourceID, "resource_unknown"}} {
			if len(field.value) > 4096 {
				return r, fmt.Errorf("retain arm evidence identifiers within 4096 bytes")
			}
			if strings.TrimSpace(field.value) == "" {
				reasons[field.reason] = true
			}
		}
		if len(arm.Attempts) > MaxExperimentAttempts {
			return r, fmt.Errorf("select at most %d attempts per arm", MaxExperimentAttempts)
		}
		if !arm.SelectionComplete {
			reasons["selection_incomplete"] = true
		}
		counts := ExperimentCounts{Selected: len(arm.Attempts)}
		for _, a := range arm.Attempts {
			key := [2]int64{a.RunID, int64(a.Attempt)}
			if a.RunID <= 0 || a.Attempt <= 0 || seen[key] {
				return r, fmt.Errorf("select each positive run and attempt identity once across both arms")
			}
			seen[key] = true
			if a.ObservedAt.IsZero() {
				reasons["observation_time_unknown"] = true
			} else if a.ObservedAt.Before(s.Since) || !a.ObservedAt.Before(s.Until) {
				return r, fmt.Errorf("select attempts inside the observation window")
			}
			if len(a.SourceRevision) > 4096 || a.WorkflowID < 0 {
				return r, fmt.Errorf("retain bounded attempt revision and non-negative workflow identity")
			}
			if a.SourceRevision != "" && arm.SourceRevision != "" && a.SourceRevision != arm.SourceRevision {
				reasons["source_mismatch"] = true
			}
			switch a.Outcome {
			case "success":
				counts.Succeeded++
				counts.Completed++
			case "failure":
				counts.Failed++
				counts.Completed++
			case "cancelled":
				counts.Cancelled++
			case "superseded":
				counts.Superseded++
			case "pending", "unknown":
				counts.Unknown++
				reasons["outcome_unknown"] = true
			default:
				return r, fmt.Errorf("use a documented attempt outcome")
			}
			// Excluded attempts still need retained identities and outcomes, but their
			// cache and host state cannot establish the completed cohort's eligibility.
			if a.Outcome != "success" && a.Outcome != "failure" {
				continue
			}
			switch a.Cache {
			case "cold", "warm":
				if caches[index] == "" {
					caches[index] = a.Cache
				} else if caches[index] != a.Cache {
					reasons["cache_mismatch"] = true
				}
			case "", "unknown":
				reasons["cache_unknown"] = true
			default:
				return r, fmt.Errorf("use cold, warm or unknown cache evidence")
			}
			switch a.HostCondition {
			case "quiet":
			case "busy":
				reasons["host_pressure"] = true
			case "", "unknown":
				reasons["host_unknown"] = true
			default:
				return r, fmt.Errorf("use quiet, busy or unknown host evidence")
			}
		}
		if counts.Completed < MinExperimentSamples {
			reasons["insufficient_samples"] = true
		}
		if index == 0 {
			r.Baseline = counts
		} else {
			r.Candidate = counts
		}
	}
	if caches[0] != "" && caches[1] != "" && caches[0] != caches[1] {
		reasons["cache_mismatch"] = true
	}
	for code := range reasons {
		r.Reasons = append(r.Reasons, code)
	}
	slices.Sort(r.Reasons)
	if len(r.Reasons) > 0 {
		r.State = "inconclusive"
	}
	return r, nil
}

package analysis

import (
	"fmt"
	"math"
	"slices"
)

const ExperimentMeasureVersion = "selected-measures-v1"
const ExperimentMaterialRatio = 1.10
const ExperimentFailurePercentagePoints = 5

type ExperimentDistribution struct {
	Samples int    `json:"samples"`
	Missing int    `json:"missing"`
	MinMS   *int64 `json:"min_ms"`
	P50MS   *int64 `json:"p50_ms"`
	P95MS   *int64 `json:"p95_ms"`
	MaxMS   *int64 `json:"max_ms"`
	// A partial sum would look like a smaller bill. Report no total until every
	// relevant attempt is measured, even when the measured subset is zero.
	TotalMS *int64 `json:"total_ms"`
}

type ExperimentMeasures struct {
	Latency       ExperimentDistribution `json:"successful_latency"`
	Execution     ExperimentDistribution `json:"all_attempt_execution"`
	AllocatedIdle ExperimentDistribution `json:"all_attempt_allocated_idle"`
	FailureRate   *float64               `json:"failure_rate"`
}

type ExperimentMeasurement struct {
	Version       string                `json:"version"`
	Eligibility   ExperimentEligibility `json:"eligibility"`
	Baseline      ExperimentMeasures    `json:"baseline"`
	Candidate     ExperimentMeasures    `json:"candidate"`
	LatencyChange string                `json:"latency_change"`
	// Consumption ranks the mean per selected attempt, not totals from cohorts
	// of different sizes. Total consumption and sample counts remain visible.
	ExecutionChange     string `json:"execution_mean_change"`
	AllocatedIdleChange string `json:"allocated_idle_mean_change"`
	FailureChange       string `json:"failure_rate_change"`
}

// MeasureExperiment reports descriptive figures from supplied evidence. It
// supplies no confidence interval, causal inference or cost attribution.
func MeasureExperiment(s ExperimentSnapshot) (ExperimentMeasurement, error) {
	eligibility, err := AssessExperiment(s)
	r := ExperimentMeasurement{Version: ExperimentMeasureVersion, Eligibility: eligibility, LatencyChange: NotEnough, ExecutionChange: NotEnough, AllocatedIdleChange: NotEnough, FailureChange: NotEnough}
	if err != nil {
		return r, err
	}
	r.Baseline, err = measureExperimentArm(s.Baseline, eligibility.Baseline)
	if err != nil {
		return r, err
	}
	r.Candidate, err = measureExperimentArm(s.Candidate, eligibility.Candidate)
	if err != nil {
		return r, err
	}
	if eligibility.State != "eligible" {
		return r, nil
	}
	a, b := r.Baseline, r.Candidate
	if a.Latency.Samples >= MinExperimentSamples && b.Latency.Samples >= MinExperimentSamples && a.Latency.Missing == 0 && b.Latency.Missing == 0 {
		r.LatencyChange = experimentDirection(float64(*a.Latency.P50MS), float64(*b.Latency.P50MS))
	}
	r.ExecutionChange = experimentConsumptionDirection(a.Execution, b.Execution)
	r.AllocatedIdleChange = experimentConsumptionDirection(a.AllocatedIdle, b.AllocatedIdle)
	if a.FailureRate != nil && b.FailureRate != nil {
		ac, bc := eligibility.Baseline, eligibility.Candidate
		// Integer cross-products preserve the exact five-point boundary.
		delta := int64(bc.Failed*ac.Completed-ac.Failed*bc.Completed) * 100
		bar := int64(ac.Completed*bc.Completed) * ExperimentFailurePercentagePoints
		switch {
		case delta >= bar:
			r.FailureChange = Regressed
		case delta <= -bar:
			r.FailureChange = Improved
		default:
			r.FailureChange = Unchanged
		}
	}
	return r, nil
}

func measureExperimentArm(arm ExperimentArm, counts ExperimentCounts) (ExperimentMeasures, error) {
	var latency, execution, idle []*int64
	for _, a := range arm.Attempts {
		for _, v := range []*int64{a.LatencyMS, a.ExecutionMS, a.AllocatedIdleMS} {
			if v != nil && *v < 0 {
				return ExperimentMeasures{}, fmt.Errorf("record non-negative attempt measurements")
			}
		}
		if a.Outcome == "success" {
			latency = append(latency, a.LatencyMS)
		}
		execution = append(execution, a.ExecutionMS)
		idle = append(idle, a.AllocatedIdleMS)
	}
	var r ExperimentMeasures
	var err error
	r.Latency, err = experimentDistribution(latency)
	if err != nil {
		return r, err
	}
	r.Execution, err = experimentDistribution(execution)
	if err != nil {
		return r, err
	}
	r.AllocatedIdle, err = experimentDistribution(idle)
	if err != nil {
		return r, err
	}
	if counts.Completed > 0 {
		rate := float64(counts.Failed) / float64(counts.Completed)
		r.FailureRate = &rate
	}
	return r, nil
}

func experimentDistribution(values []*int64) (ExperimentDistribution, error) {
	r := ExperimentDistribution{}
	observed := make([]int64, 0, len(values))
	var total int64
	for _, v := range values {
		if v == nil {
			r.Missing++
			continue
		}
		if *v > math.MaxInt64-total {
			return r, fmt.Errorf("attempt measurement total exceeds supported milliseconds")
		}
		total += *v
		observed = append(observed, *v)
	}
	r.Samples = len(observed)
	if len(observed) == 0 {
		return r, nil
	}
	slices.Sort(observed)
	copyValue := func(v int64) *int64 { return &v }
	r.MinMS = copyValue(observed[0])
	r.MaxMS = copyValue(observed[len(observed)-1])
	// Nearest rank is ceil(p*n)-1. Integer arithmetic fixes the convention for
	// even sample counts and avoids a library-dependent interpolation rule.
	r.P50MS = copyValue(observed[(50*len(observed)+99)/100-1])
	r.P95MS = copyValue(observed[(95*len(observed)+99)/100-1])
	if r.Missing == 0 {
		r.TotalMS = copyValue(total)
	}
	return r, nil
}

func experimentConsumptionDirection(a, b ExperimentDistribution) string {
	if a.TotalMS == nil || b.TotalMS == nil || a.Samples < MinExperimentSamples || b.Samples < MinExperimentSamples {
		return NotEnough
	}
	return experimentDirection(float64(*a.TotalMS)/float64(a.Samples), float64(*b.TotalMS)/float64(b.Samples))
}
func experimentDirection(a, b float64) string {
	switch {
	case b > a && (a == 0 || b/a >= ExperimentMaterialRatio):
		return Regressed
	case a > b && (b == 0 || a/b >= ExperimentMaterialRatio):
		return Improved
	default:
		return Unchanged
	}
}

package analysis

import (
	"math"
	"testing"
)

func measuredExperiment() ExperimentSnapshot {
	s := experimentFixture()
	for _, arm := range []*ExperimentArm{&s.Baseline, &s.Candidate} {
		for i := range arm.Attempts {
			arm.Attempts[i].LatencyMS = experimentMS(100)
			arm.Attempts[i].ExecutionMS = experimentMS(100)
			arm.Attempts[i].AllocatedIdleMS = experimentMS(0)
		}
	}
	return s
}
func experimentMS(v int64) *int64 { return &v }

func TestFasterLatencyDoesNotHideHigherConsumption(t *testing.T) {
	s := measuredExperiment()
	for i := range s.Candidate.Attempts {
		s.Candidate.Attempts[i].LatencyMS = experimentMS(50)
		s.Candidate.Attempts[i].ExecutionMS = experimentMS(200)
	}
	r, err := MeasureExperiment(s)
	if err != nil {
		t.Fatal(err)
	}
	if r.LatencyChange != "improved" || r.ExecutionChange != "regressed" || *r.Candidate.Execution.TotalMS != 6000 || r.Candidate.Latency.Samples != 30 {
		t.Fatalf("got %+v", r)
	}
}
func TestFailureRegressionRetainsFailedAndCancelledConsumption(t *testing.T) {
	s := measuredExperiment()
	s.Candidate.Attempts[0].Outcome = "failure"
	s.Candidate.Attempts[1].Outcome = "failure"
	a := s.Candidate.Attempts[0]
	a.RunID = 100
	a.Outcome = "cancelled"
	a.ExecutionMS = experimentMS(500)
	s.Candidate.Attempts = append(s.Candidate.Attempts, a)
	r, err := MeasureExperiment(s)
	if err != nil {
		t.Fatal(err)
	}
	if r.FailureChange != "regressed" || r.Candidate.Latency.Samples != 28 || *r.Candidate.Execution.TotalMS != 3500 || r.Candidate.FailureRate == nil {
		t.Fatalf("got %+v", r)
	}
}
func TestMissingConsumptionDoesNotBecomeZeroOrAnImprovement(t *testing.T) {
	s := measuredExperiment()
	s.Candidate.Attempts[0].ExecutionMS = nil
	s.Candidate.Attempts[1].LatencyMS = nil
	r, err := MeasureExperiment(s)
	if err != nil {
		t.Fatal(err)
	}
	if r.Candidate.Execution.TotalMS != nil || r.Candidate.Execution.Missing != 1 || r.ExecutionChange != "not_enough" || r.LatencyChange != "not_enough" || r.Candidate.Latency.Missing != 1 || *r.Candidate.AllocatedIdle.TotalMS != 0 {
		t.Fatalf("got %+v", r)
	}
}
func TestIneligibleCohortsKeepTheirFiguresWithoutRanking(t *testing.T) {
	s := measuredExperiment()
	s.Candidate.InputsID = "different"
	r, err := MeasureExperiment(s)
	if err != nil || r.LatencyChange != "not_enough" || r.ExecutionChange != "not_enough" || r.FailureChange != "not_enough" || r.Candidate.Latency.P50MS == nil {
		t.Fatalf("got %+v, %v", r, err)
	}
}
func TestInvalidMeasurementsAndOverflowAreRefused(t *testing.T) {
	for _, kind := range []string{"negative", "overflow"} {
		s := measuredExperiment()
		if kind == "negative" {
			s.Candidate.Attempts[0].LatencyMS = experimentMS(-1)
		} else {
			s.Candidate.Attempts[0].ExecutionMS = experimentMS(math.MaxInt64)
		}
		if _, err := MeasureExperiment(s); err == nil {
			t.Fatalf("%s accepted", kind)
		}
	}
}
func TestLatencyUsesNearestRankAndIncludesRealZero(t *testing.T) {
	s := measuredExperiment()
	for i := range s.Baseline.Attempts {
		s.Baseline.Attempts[i].LatencyMS = experimentMS(int64(i))
	}
	r, err := MeasureExperiment(s)
	if err != nil {
		t.Fatal(err)
	}
	d := r.Baseline.Latency
	if *d.MinMS != 0 || *d.P50MS != 14 || *d.P95MS != 28 || *d.MaxMS != 29 {
		t.Fatalf("got %+v", d)
	}
}

func TestMaterialLatencyBoundaryAndZeroAreExplicit(t *testing.T) {
	for _, tc := range []struct {
		from, to int64
		want     string
	}{{100, 110, "regressed"}, {100, 109, "unchanged"}, {110, 100, "improved"}, {0, 1, "regressed"}, {1, 0, "improved"}, {0, 0, "unchanged"}} {
		s := measuredExperiment()
		for i := range s.Baseline.Attempts {
			s.Baseline.Attempts[i].LatencyMS = experimentMS(tc.from)
			s.Candidate.Attempts[i].LatencyMS = experimentMS(tc.to)
		}
		r, err := MeasureExperiment(s)
		if err != nil || r.LatencyChange != tc.want {
			t.Fatalf("%+v: %+v, %v", tc, r, err)
		}
	}
}

func TestConsumptionRanksMeansRatherThanDifferentCohortTotals(t *testing.T) {
	s := measuredExperiment()
	for i := range 10 {
		a := s.Candidate.Attempts[0]
		a.RunID = int64(100 + i)
		s.Candidate.Attempts = append(s.Candidate.Attempts, a)
	}
	r, err := MeasureExperiment(s)
	if err != nil || r.ExecutionChange != "unchanged" || *r.Candidate.Execution.TotalMS == *r.Baseline.Execution.TotalMS {
		t.Fatalf("got %+v, %v", r, err)
	}
}

func TestFivePercentagePointFailureBoundaryDoesNotRoundAway(t *testing.T) {
	s := measuredExperiment()
	for i := range 10 {
		a := s.Baseline.Attempts[0]
		a.RunID = int64(100 + i)
		s.Baseline.Attempts = append(s.Baseline.Attempts, a)
		a.RunID += 100
		s.Candidate.Attempts = append(s.Candidate.Attempts, a)
	}
	for i := range 4 {
		s.Baseline.Attempts[i].Outcome = "failure"
	}
	for i := range 6 {
		s.Candidate.Attempts[i].Outcome = "failure"
	}
	r, err := MeasureExperiment(s)
	if err != nil || r.FailureChange != "regressed" {
		t.Fatalf("got %+v, %v", r, err)
	}
}

package analysis

import (
	"slices"
	"strings"
	"testing"
	"time"
)

func experimentFixture() ExperimentSnapshot {
	start := time.Date(2026, 10, 12, 0, 0, 0, 0, time.UTC)
	arm := ExperimentArm{SourceRevision: "commit", WorkflowRevision: "workflow", InputsID: "inputs", TestScopeID: "tests", ConfigurationID: "small", ImageID: "image", ResourceID: "resources", SelectionComplete: true}
	s := ExperimentSnapshot{RuleVersion: ExperimentRuleVersion, Kind: "runner", Repository: "owner/repo", InitiatingUser: "user", Hypothesis: "reduce wait", IntendedDelta: "larger runner", EvidenceID: "selection", Since: start, Until: start.Add(time.Hour), Baseline: arm, Candidate: arm}
	s.Candidate.ConfigurationID = "large"
	for i := 0; i < 30; i++ {
		a := ExperimentAttempt{RunID: int64(i + 1), Attempt: 1, ObservedAt: start.Add(time.Minute), Outcome: "success", Cache: "cold", HostCondition: "quiet"}
		s.Baseline.Attempts = append(s.Baseline.Attempts, a)
		a.RunID += 30
		s.Candidate.Attempts = append(s.Candidate.Attempts, a)
	}
	return s
}

func TestSelectedRunsExplainWhyAComparisonIsInconclusive(t *testing.T) {
	cases := []struct {
		name, reason string
		change       func(*ExperimentSnapshot)
	}{
		{"different source", "source_mismatch", func(s *ExperimentSnapshot) { s.Candidate.SourceRevision = "other" }},
		{"different workflow", "workflow_mismatch", func(s *ExperimentSnapshot) { s.Candidate.WorkflowRevision = "other" }},
		{"different inputs", "inputs_mismatch", func(s *ExperimentSnapshot) { s.Candidate.InputsID = "other" }},
		{"different tests", "test_scope_mismatch", func(s *ExperimentSnapshot) { s.Candidate.TestScopeID = "other" }},
		{"unknown cache", "cache_unknown", func(s *ExperimentSnapshot) { s.Candidate.Attempts[0].Cache = "unknown" }},
		{"warm candidate", "cache_mismatch", func(s *ExperimentSnapshot) {
			for i := range s.Candidate.Attempts {
				s.Candidate.Attempts[i].Cache = "warm"
			}
		}},
		{"busy host", "host_pressure", func(s *ExperimentSnapshot) { s.Candidate.Attempts[0].HostCondition = "busy" }},
		{"missing host", "host_unknown", func(s *ExperimentSnapshot) { s.Candidate.Attempts[0].HostCondition = "unknown" }},
		{"small sample", "insufficient_samples", func(s *ExperimentSnapshot) { s.Candidate.Attempts = s.Candidate.Attempts[:29] }},
		{"selection incomplete", "selection_incomplete", func(s *ExperimentSnapshot) { s.Candidate.SelectionComplete = false }},
		{"pending attempt", "outcome_unknown", func(s *ExperimentSnapshot) { s.Candidate.Attempts[0].Outcome = "pending" }},
		{"unrecorded delta", "revision_delta_missing", func(s *ExperimentSnapshot) { s.Kind = "workflow"; s.Candidate.SourceRevision = "other" }},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			s := experimentFixture()
			tc.change(&s)
			r, err := AssessExperiment(s)
			if err != nil {
				t.Fatal(err)
			}
			if r.State != "inconclusive" || !slices.Contains(r.Reasons, tc.reason) {
				t.Fatalf("got %+v", r)
			}
		})
	}
}

func TestEligibilityKeepsFailuresAndReportsExcludedAttempts(t *testing.T) {
	s := experimentFixture()
	s.Candidate.Attempts[0].Outcome = "failure"
	a := s.Candidate.Attempts[0]
	a.RunID = 100
	a.Outcome = "cancelled"
	s.Candidate.Attempts = append(s.Candidate.Attempts, a)
	a.RunID = 101
	a.Outcome = "superseded"
	s.Candidate.Attempts = append(s.Candidate.Attempts, a)
	r, err := AssessExperiment(s)
	if err != nil {
		t.Fatal(err)
	}
	if r.State != "eligible" || r.Candidate.Completed != 30 || r.Candidate.Failed != 1 || r.Candidate.Cancelled != 1 || r.Candidate.Superseded != 1 {
		t.Fatalf("got %+v", r)
	}
}

func TestAnAttemptCannotAppearTwiceOrInBothArms(t *testing.T) {
	for _, cross := range []bool{false, true} {
		s := experimentFixture()
		if cross {
			s.Candidate.Attempts[0] = s.Baseline.Attempts[0]
		} else {
			s.Baseline.Attempts = append(s.Baseline.Attempts, s.Baseline.Attempts[0])
		}
		if _, err := AssessExperiment(s); err == nil {
			t.Fatal("duplicate accepted")
		}
	}
}

func TestAnExperimentRequiresAReproducibleBoundedRecord(t *testing.T) {
	changes := []func(*ExperimentSnapshot){
		func(s *ExperimentSnapshot) { s.RuleVersion = "future" }, func(s *ExperimentSnapshot) { s.Repository = "" }, func(s *ExperimentSnapshot) { s.EvidenceID = "" }, func(s *ExperimentSnapshot) { s.InitiatingUser = "" }, func(s *ExperimentSnapshot) { s.Hypothesis = "" }, func(s *ExperimentSnapshot) { s.IntendedDelta = "" }, func(s *ExperimentSnapshot) { s.Until = s.Since }, func(s *ExperimentSnapshot) { s.Candidate.ImageID = strings.Repeat("x", 4097) }, func(s *ExperimentSnapshot) { s.Candidate.Attempts[0].ObservedAt = s.Until }, func(s *ExperimentSnapshot) { s.Candidate.Attempts[0].Outcome = "invented" }, func(s *ExperimentSnapshot) { s.Candidate.Attempts = make([]ExperimentAttempt, MaxExperimentAttempts+1) },
	}
	for i, change := range changes {
		s := experimentFixture()
		change(&s)
		if _, err := AssessExperiment(s); err == nil {
			t.Fatalf("case %d accepted", i)
		}
	}
}

func TestWorkflowComparisonsRetainAnExplicitRevisionDelta(t *testing.T) {
	s := experimentFixture()
	s.Kind = "workflow"
	s.Candidate.WorkflowRevision = "changed"
	s.RevisionDeltaID = "retained-diff"
	r, err := AssessExperiment(s)
