// A source reader publishes and reads notes; everyone else sees neither, and a
// token publishes only when it was given the scope to.
func TestReadersPublishAndReadVersionedNotesAndNobodyElseSeesThem(t *testing.T) {
	h, draft, owner, cookie := sourceHarness(t)
	base := "/api/v1/ai-context/source/" + draft.ID + "/notes"
	note := map[string]any{"slug": "auth-review", "kind": "report", "title": "Authentication review", "body": "# Findings\n\n<script>alert(1)</script>"}

	r := h.do(request{method: http.MethodPost, path: base, cookie: cookie, body: note})
	r.mustStatus(t, http.StatusCreated, "a reader publishing")
	var published store.AIContextArtifact
	r.into(t, &published)
	fresh, err := h.st.GetAIContextFreshness(h.ctx, draft.ID)
	if err != nil {
		t.Fatal(err)
	}
	if published.Version != 1 || published.ViaKind != "user" || published.SourceCommit != fresh.PublishedCommit || published.SourceCommit == "" {
		t.Fatalf("published = %+v; want version 1, via user, at the verified commit %s", published, fresh.PublishedCommit)
	}

	note["title"] = "Authentication review, revised"
	h.do(request{method: http.MethodPost, path: base, cookie: cookie, body: note}).mustStatus(t, http.StatusCreated, "a second version")
	var page struct {
		Items []store.AIContextArtifact `json:"items"`
		Total int                       `json:"total"`
	}
	r = h.do(request{method: http.MethodGet, path: base, cookie: cookie})
	r.mustStatus(t, http.StatusOK, "listing notes")
	r.into(t, &page)
	if page.Total != 1 || page.Items[0].Version != 2 || page.Items[0].Versions != 2 || page.Items[0].Body != "" {
		t.Fatalf("listing = %+v", page)
	}
	var first store.AIContextArtifact
	r = h.do(request{method: http.MethodGet, path: base + "/auth-review?version=1", cookie: cookie})
	r.mustStatus(t, http.StatusOK, "reading version 1")
	r.into(t, &first)
	if first.Title != "Authentication review" || first.Body != note["body"] {
		t.Fatalf("version 1 = %+v", first)
	}

	note["kind"] = "essay"
	h.do(request{method: http.MethodPost, path: base, cookie: cookie, body: note}).mustStatus(t, http.StatusUnprocessableEntity, "an unknown kind")
	note["kind"] = "report"

	_, outsider := h.user("notes-outsider", store.RoleAdmin)
	h.do(request{method: http.MethodGet, path: base, cookie: outsider}).mustStatus(t, http.StatusNotFound, "a non-member listing")
	h.do(request{method: http.MethodPost, path: base, cookie: outsider, body: note}).mustStatus(t, http.StatusNotFound, "a non-member publishing")

	_, reading, err := h.ctrl.Auth().CreateAPIToken(h.ctx, auth.NewToken{Name: "reader-only", Role: store.RoleViewer, UserID: owner.ID, Scopes: []string{"context:read"}})
	if err != nil {
		t.Fatal(err)
	}
	h.do(request{method: http.MethodGet, path: base, token: reading}).mustStatus(t, http.StatusOK, "a read-scoped token listing")
	h.do(request{method: http.MethodPost, path: base, token: reading, body: note}).mustStatus(t, http.StatusForbidden, "a read-scoped token publishing")

	_, writing, err := h.ctrl.Auth().CreateAPIToken(h.ctx, auth.NewToken{Name: "ci-reviewer", Role: store.RoleViewer, UserID: owner.ID, Scopes: []string{"context:publish"}})
	if err != nil {
		t.Fatal(err)
	}
	r = h.do(request{method: http.MethodPost, path: base, token: writing, body: note})
	r.mustStatus(t, http.StatusCreated, "a publish-scoped token")
	r.into(t, &published)
	if published.ViaKind != "token" || published.ViaName != "ci-reviewer" {
		t.Fatalf("token note attributed as %s %q", published.ViaKind, published.ViaName)
	}
}

// An MCP connection allowed to read a repository is not thereby allowed to
// write about it. Its owner's separate publish consent is what lets it, and
// the note says which connection wrote it.
func TestAConnectionPublishesNotesOnlyWithItsOwnersPublishConsent(t *testing.T) {
	h, draft, owner, cookie := sourceHarness(t)
	h.cfg.Server.ExternalURL = oauthBase
	client := h.registerClient(claudeReturn)
	req := requestFrom(t, h.authorize(client, claudeReturn, nil))
	pair := pairFrom(t, h.exchange(client, h.approve(cookie, req, store.RoleViewer), nil, nil))
	grants, err := h.st.ListOAuthGrants(h.ctx, owner.ID)
	if err != nil || len(grants) != 1 {
		t.Fatal("grant", err)
	}
	publish := map[string]any{"repository_id": draft.ID, "slug": "plan", "kind": "plan", "title": "Refactor plan", "body": "1. Split the handler."}

	// Read consent only.
	h.do(request{method: http.MethodPut, path: "/api/v1/auth/mcp-connections/" + grants[0].ID + "/repositories", cookie: cookie,
		body: map[string]any{"repository_ids": []string{draft.ID}}}).mustStatus(t, http.StatusNoContent, "read consent")
	if result := h.mcpTool(pair.AccessToken, "context_publish", publish); !result.IsError || !strings.Contains(resultText(result), "Source access") {
		t.Fatal("a connection with read consent alone published, or was not told where to ask", resultText(result))
	}

	// Publishing to a repository it may not read is refused outright.
	h.do(request{method: http.MethodPut, path: "/api/v1/auth/mcp-connections/" + grants[0].ID + "/repositories", cookie: cookie,
		body: map[string]any{"repository_ids": []string{}, "publish_repository_ids": []string{draft.ID}}}).mustStatus(t, http.StatusUnprocessableEntity, "publish without read")

	h.do(request{method: http.MethodPut, path: "/api/v1/auth/mcp-connections/" + grants[0].ID + "/repositories", cookie: cookie,
		body: map[string]any{"repository_ids": []string{draft.ID}, "publish_repository_ids": []string{draft.ID}}}).mustStatus(t, http.StatusNoContent, "publish consent")
	result := h.mcpTool(pair.AccessToken, "context_publish", publish)
	if result.IsError {
		t.Fatal("publish with consent", resultText(result))
	}
	if strings.Contains(resultText(result), "Split the handler") {
		t.Fatal("the reply echoed the body back")
	}
	note, err := h.st.GetAIContextArtifact(h.ctx, draft.ID, "plan", 0)
	if err != nil || note.ViaKind != "connection" || note.ViaName == "" || note.AuthorName == "" {
		t.Fatalf("connection note attributed as %+v, %v", note, err)
	}
	listed := h.mcpTool(pair.AccessToken, "context_notes", map[string]any{"repository_id": draft.ID})
	if listed.IsError || !strings.Contains(resultText(listed), "Refactor plan") {
		t.Fatal("listing notes over MCP", resultText(listed))
	}
	read := h.mcpTool(pair.AccessToken, "context_notes", map[string]any{"repository_id": draft.ID, "slug": "plan"})
	if read.IsError || !strings.Contains(resultText(read), "Split the handler") {
		t.Fatal("reading a note over MCP", resultText(read))
	}

	// Saving read consent from a client that knows nothing of publishing
	// keeps the publish consent; an explicit empty list removes it.
	h.do(request{method: http.MethodPut, path: "/api/v1/auth/mcp-connections/" + grants[0].ID + "/repositories", cookie: cookie,
		body: map[string]any{"repository_ids": []string{draft.ID}}}).mustStatus(t, http.StatusNoContent, "read-only save")
	if result := h.mcpTool(pair.AccessToken, "context_publish", publish); result.IsError {
		t.Fatal("a read-only save dropped publish consent", resultText(result))
	}
	h.do(request{method: http.MethodPut, path: "/api/v1/auth/mcp-connections/" + grants[0].ID + "/repositories", cookie: cookie,
		body: map[string]any{"repository_ids": []string{draft.ID}, "publish_repository_ids": []string{}}}).mustStatus(t, http.StatusNoContent, "clearing publish consent")
	if result := h.mcpTool(pair.AccessToken, "context_publish", publish); !result.IsError {
		t.Fatal("cleared publish consent still published")
	}
}

package api

import (
	"net/http"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/store"
)

// Owning an installation is delegated configuration authority over exactly that
// installation. These tests pin both halves: what an owner can now do, and the
// things that must stay out of reach (other people, tokens, and source itself).
func TestInstallationOwnersEnableTheirRepositoriesWithoutSourceAccess(t *testing.T) {
	h, inst, _ := migrationHarness(t)
	owner, ownerCookie := h.user("context-owner", store.RoleViewer)
	_, outsiderCookie := h.user("context-outsider", store.RoleViewer)
	other, _ := h.user("context-other", store.RoleViewer)
	_, admin := h.user("context-owner-admin", store.RoleAdmin)
	root := "/api/v1/ai-context/"

	h.do(request{method: http.MethodGet, path: root + "discovery?installation_id=" + inst.ID, cookie: ownerCookie}).mustStatus(t, http.StatusNotFound, "owner before delegation")

	h.do(request{method: http.MethodPut, path: root + "installations/" + inst.ID + "/owners", cookie: ownerCookie,
		body: map[string]any{"user_ids": []string{owner.ID}}}).mustStatus(t, http.StatusForbidden, "owners cannot delegate to themselves")
	h.do(request{method: http.MethodPut, path: root + "installations/" + inst.ID + "/owners", cookie: admin,
		body: map[string]any{}}).mustStatus(t, http.StatusUnprocessableEntity, "missing owners must not mean remove all")
	h.do(request{method: http.MethodPut, path: root + "installations/" + inst.ID + "/owners", cookie: admin,
		body: map[string]any{"user_ids": []string{"missing"}}}).mustStatus(t, http.StatusNotFound, "unknown owner")
	h.do(request{method: http.MethodPut, path: root + "installations/" + inst.ID + "/owners", cookie: admin,
		body: map[string]any{"user_ids": []string{owner.ID}}}).mustStatus(t, http.StatusOK, "delegation")

	var installations struct {
		Items []store.AIContextInstallationRef `json:"items"`
	}
	r := h.do(request{method: http.MethodGet, path: root + "installations", cookie: ownerCookie})
	r.mustStatus(t, http.StatusOK, "owned installations")
	r.into(t, &installations)
	if len(installations.Items) != 1 || installations.Items[0].ID != inst.ID {
		t.Fatal("owner should see exactly their installation", installations.Items)
	}
	r = h.do(request{method: http.MethodGet, path: root + "installations", cookie: outsiderCookie})
	r.into(t, &installations)
	if len(installations.Items) != 0 {
		t.Fatal("a non-owner learned of an installation")
	}

	var discovery struct {
		Repositories []struct {
			ID int64 `json:"id"`
		} `json:"repositories"`
	}
	r = h.do(request{method: http.MethodGet, path: root + "discovery?installation_id=" + inst.ID, cookie: ownerCookie})
	r.mustStatus(t, http.StatusOK, "owner discovery")
	r.into(t, &discovery)
	if len(discovery.Repositories) == 0 {
		t.Fatal("no repositories discovered")
	}
	h.do(request{method: http.MethodGet, path: root + "discovery?installation_id=" + inst.ID, cookie: outsiderCookie}).mustStatus(t, http.StatusNotFound, "non-owner discovery")

	draftBody := map[string]any{"installation_id": inst.ID, "repository_id": discovery.Repositories[0].ID}
	h.do(request{method: http.MethodPost, path: root + "repositories", cookie: outsiderCookie, body: draftBody}).mustStatus(t, http.StatusNotFound, "non-owner draft")
	r = h.do(request{method: http.MethodPost, path: root + "repositories", cookie: ownerCookie, body: draftBody})
	r.mustStatus(t, http.StatusCreated, "owner draft")
	var draft store.AIContextRepository
	r.into(t, &draft)

	// Ownership is not membership: creating a draft grants nobody source.
	h.do(request{method: http.MethodGet, path: root + "source/" + draft.ID + "/overview", cookie: ownerCookie}).mustStatus(t, http.StatusNotFound, "owner has no source access")

	for _, path := range []string{"repositories/" + draft.ID, "repositories/" + draft.ID + "/members"} {
		h.do(request{method: http.MethodGet, path: root + path, cookie: ownerCookie}).mustStatus(t, http.StatusOK, "owner "+path)
		h.do(request{method: http.MethodGet, path: root + path, cookie: outsiderCookie}).mustStatus(t, http.StatusNotFound, "outsider "+path)
	}
	// The fake GitHub's loopback host fails the production template gate, so the
	// preview itself answers 422 here; what matters is who gets that far.
	setup := "repositories/" + draft.ID + "/setup"
	if got := h.do(request{method: http.MethodGet, path: root + setup, cookie: ownerCookie}); got.status == http.StatusNotFound || got.status == http.StatusForbidden {
		t.Fatal("owner was refused the setup preview", got.status)
	}
	h.do(request{method: http.MethodGet, path: root + setup, cookie: outsiderCookie}).mustStatus(t, http.StatusNotFound, "outsider setup")
	h.do(request{method: http.MethodGet, path: root + "repositories/missing", cookie: outsiderCookie}).mustStatus(t, http.StatusNotFound, "missing looks the same as unowned")

	var page struct {
		Total int `json:"total"`
	}
	r = h.do(request{method: http.MethodGet, path: root + "repositories", cookie: ownerCookie})
	r.into(t, &page)
	if page.Total != 1 {
		t.Fatal("owner list", page.Total)
	}
	r = h.do(request{method: http.MethodGet, path: root + "repositories?installation_id=" + inst.ID, cookie: outsiderCookie})
	r.mustStatus(t, http.StatusOK, "outsider list")
	r.into(t, &page)
	if page.Total != 0 {
		t.Fatal("outsider listed another installation's repositories")
	}

	// An owner may be their own reader, but cannot choose other people.
	h.do(request{method: http.MethodPut, path: root + "repositories/" + draft.ID + "/members", cookie: ownerCookie,
		body: map[string]any{"user_ids": []string{other.ID}}}).mustStatus(t, http.StatusUnprocessableEntity, "owner assigning someone else")
	if err := h.st.ReplaceAIContextMembers(h.ctx, draft.ID, []string{other.ID}); err != nil {
		t.Fatal(err)
	}
	h.do(request{method: http.MethodPut, path: root + "repositories/" + draft.ID + "/members", cookie: ownerCookie,
		body: map[string]any{"user_ids": []string{owner.ID}}}).mustStatus(t, http.StatusOK, "owner reading their own repository")
	members, _ := h.st.AIContextMembers(h.ctx, draft.ID)
	if len(members) != 2 {
		t.Fatal("an owner's save must keep the administrator's readers", members)
	}
	r = h.do(request{method: http.MethodGet, path: root + "repositories/" + draft.ID + "/members", cookie: ownerCookie})
	if strings.Contains(string(r.body), other.ID) {
		t.Fatal("an owner learned who else reads the repository")
	}
	h.do(request{method: http.MethodPut, path: root + "repositories/" + draft.ID + "/members", cookie: ownerCookie,
		body: map[string]any{"user_ids": []string{}}}).mustStatus(t, http.StatusOK, "owner leaving")
	members, _ = h.st.AIContextMembers(h.ctx, draft.ID)
	if len(members) != 1 || members[0] != other.ID {
		t.Fatal("leaving removed someone else", members)
	}

	// A bearer token never inherits its owner's delegation.
	_, token, err := h.ctrl.Auth().CreateAPIToken(h.ctx, auth.NewToken{Name: "owner-token", Role: store.RoleViewer, UserID: owner.ID, Scopes: []string{"context:manage"}})
	if err != nil {
		t.Fatal(err)
	}
	h.do(request{method: http.MethodGet, path: root + "repositories/" + draft.ID, token: token}).mustStatus(t, http.StatusNotFound, "owner's token")

	// Revocation is immediate.
	h.do(request{method: http.MethodPut, path: root + "installations/" + inst.ID + "/owners", cookie: admin,
		body: map[string]any{"user_ids": []string{}}}).mustStatus(t, http.StatusOK, "removing the owner")
	h.do(request{method: http.MethodGet, path: root + "repositories/" + draft.ID, cookie: ownerCookie}).mustStatus(t, http.StatusNotFound, "former owner")
}

