	cookie   string
}

const (
	uploadBase    = "https://zoomies.example.com"
	uploadBigFile = "assets/bundle.js"
)

// zoomiesOnlyFixture sets a repository up for Zoomies-only output the way an
// owner would -- draft, reviewed setup PR, merge -- and builds the snapshot
// its workflow would upload for the current head of the trusted branch.
func zoomiesOnlyFixture(t *testing.T) *uploadFixture {
	t.Helper()
	return zoomiesOnlyFixtureOn(t, "github.com")
}

// zoomiesOnlyFixtureOn is zoomiesOnlyFixture for a repository on host, whose
// Actions tokens come from an issuer of its own unless host is GitHub.com.
func zoomiesOnlyFixtureOn(t *testing.T, host string) *uploadFixture {
	t.Helper()
	h, inst, _ := migrationHarness(t)
	h.cfg.Server.ExternalURL = uploadBase
	dotcom, issuer := github.NewFakeActionsIssuer(t), github.NewFakeActionsIssuer(t)
	if host == "github.com" {
		issuer = dotcom
	}
	h.ctrl.SetActionsIssuerFor(func(h string) string {
		switch h {
		case "github.com":
			return dotcom.URL
		case host:
			return issuer.URL
		}
		return github.ActionsIssuerFor(h)
	})
	reader, cookie := h.user("upload-reader", store.RoleViewer)

	discovery, err := h.ctrl.DiscoverAIContext(h.ctx, inst.ID)
	if err != nil {
		t.Fatal(err)
	}
	selected := discovery.Repositories[0]
	draft := store.AIContextRepository{Key: aicontext.RepositoryKey{GitHubHost: host, InstallationID: inst.ID, RepositoryID: selected.ID}, FullName: selected.FullName, Config: aicontext.DefaultConfig(selected.DefaultBranch)}
	draft.Config.Destination, draft.Config.UploadURL = aicontext.Zoomies, aicontext.UploadURLFor(uploadBase)
	if err := h.st.CreateAIContextRepository(h.ctx, &draft); err != nil {
		t.Fatal(err)
	}
	if err := h.st.ReplaceAIContextMembers(h.ctx, draft.ID, []string{reader.ID}); err != nil {
		t.Fatal(err)
	}
	plan, err := h.ctrl.PreviewAIContextSetup(h.ctx, draft.ID)
	if err != nil {
		t.Fatal(err)
	}
	plan, err = h.ctrl.CreateAIContextSetupPR(h.ctx, draft.ID, controller.AIContextSetupApproval{Revision: plan.Revision, PlanHash: plan.PlanHash})
	if err != nil {
		t.Fatal(err)
	}
	if !h.gh.MergeContextPull(draft.FullName, plan.Setup.PRNumber) {
		t.Fatal("merge failed")
	}
	h.gh.AddFile(draft.FullName, "src/main.go", "package widgets\n")
	// A file no snapshot can carry, for the tests of what an upload may omit.
	h.gh.AddFile(draft.FullName, uploadBigFile, strings.Repeat("a", aicontext.MaxFileBytes+7))
	client, err := h.ctrl.ClientFor(h.ctx, inst.ID)
	if err != nil {
		t.Fatal(err)
	}
	source, err := client.(github.ContextSetupClient).ReadContextSetup(h.ctx, draft.FullName, draft.Config.SourceBranch)
	if err != nil {
		t.Fatal(err)
	}
	stored, err := h.st.GetAIContextRepository(h.ctx, draft.ID)
	if err != nil {
		t.Fatal(err)
	}
	hash, _ := stored.Config.Hash()
	snapshot := aicontext.Snapshot{Manifest: aicontext.Manifest{SchemaVersion: 1, Repository: draft.Key, SourceBranch: draft.Config.SourceBranch, SourceCommit: source.Commit, ConfigHash: hash, GeneratedAt: time.Now().UTC(), Manager: "zoomies", Generator: "repomix@1.18.1"}, Files: []aicontext.File{{Path: "src/main.go", Content: "package widgets\n", SHA256: aicontext.Hash([]byte("package widgets\n"))}}}
	body, _ := json.Marshal(snapshot)
	return &uploadFixture{h: h, issuer: issuer, dotcom: dotcom, repo: *stored, commit: source.Commit, snapshot: body, cookie: cookie}
}

// claims are what GitHub would put in the token of the managed workflow's
// run on the trusted branch; each test changes one of them.
func (f *uploadFixture) claims() map[string]any {
	return map[string]any{
		"aud":              aicontext.UploadURLFor(uploadBase),
		"repository":       f.repo.FullName,
		"repository_id":    jsonNumber(f.repo.Key.RepositoryID),
		"ref":              "refs/heads/" + f.repo.Config.SourceBranch,
		"sha":              f.commit,
		"event_name":       "push",
		"job_workflow_ref": f.repo.FullName + "/.github/workflows/zoomies-ai-context.yml@refs/heads/" + f.repo.Config.SourceBranch,
		"jti":              "jti-" + time.Now().Format(time.RFC3339Nano),
	}
}

func jsonNumber(n int64) string { b, _ := json.Marshal(n); return string(b) }

func (f *uploadFixture) upload(claims map[string]any, body []byte) *response {
	return f.uploadSignedBy(f.issuer, claims, body)
}

func (f *uploadFixture) uploadSignedBy(issuer *github.FakeActionsIssuer, claims map[string]any, body []byte) *response {
	return f.h.do(request{method: http.MethodPost, path: "/api/v1/ai-context/uploads", rawBody: string(body),
		token: issuer.Sign(f.h.t, claims)})
}

func TestAZoomiesOnlyUploadIsVerifiedAgainstGitHubBeforeAnyoneCanReadIt(t *testing.T) {
	f := zoomiesOnlyFixture(t)
	read := "/api/v1/ai-context/source/" + f.repo.ID + "/read?path=src/main.go"

	// Before any upload, there is nothing to read: Zoomies-only output has no
	// branch to fall back on.
	if r := f.h.do(request{method: http.MethodGet, path: read, cookie: f.cookie}); r.status == http.StatusOK {
		t.Fatal("source was served before anything was uploaded")
	}

	claims := f.claims()
	f.upload(claims, f.snapshot).mustStatus(t, http.StatusAccepted, "the managed workflow's upload")
	r := f.h.do(request{method: http.MethodGet, path: read, cookie: f.cookie})
	r.mustStatus(t, http.StatusOK, "reading the uploaded context")
	if !strings.Contains(string(r.body), "package widgets") {
		t.Fatal("uploaded source missing")
	}

	// The same token again is a replay, whatever it carries.
	f.upload(claims, f.snapshot).mustStatus(t, http.StatusConflict, "a replayed token")
}

func TestUploadsFromAnythingButTheManagedWorkflowOnItsTrustedBranchAreRefused(t *testing.T) {
	f := zoomiesOnlyFixture(t)
	for name, change := range map[string]struct {
		claim  string
		value  any
		status int
	}{
		"a pull request run":            {"event_name", "pull_request", http.StatusForbidden},
		"another branch":                {"ref", "refs/heads/feature", http.StatusForbidden},
		"another workflow file":         {"job_workflow_ref", f.repo.FullName + "/.github/workflows/ci.yml@refs/heads/" + f.repo.Config.SourceBranch, http.StatusForbidden},
		"a reusable workflow elsewhere": {"job_workflow_ref", "evil/repo/.github/workflows/zoomies-ai-context.yml@refs/heads/" + f.repo.Config.SourceBranch, http.StatusForbidden},
		"another repository":            {"repository_id", "999999", http.StatusNotFound},
		"another controller's audience": {"aud", "https://elsewhere.example.com" + aicontext.UploadPath, http.StatusUnauthorized},
		"a commit that is not the head": {"sha", strings.Repeat("d", 40), http.StatusForbidden},
	} {
		claims := f.claims()
		claims[change.claim] = change.value
		f.upload(claims, f.snapshot).mustStatus(t, change.status, name)
	}

	// A self-consistent snapshot whose file is not the blob in that commit.
	var forged aicontext.Snapshot
	if err := json.Unmarshal(f.snapshot, &forged); err != nil {
		t.Fatal(err)
	}
	forged.Files[0].Content = "package widgets // injected\n"
	forged.Files[0].SHA256 = aicontext.Hash([]byte(forged.Files[0].Content))
	body, _ := json.Marshal(forged)
	f.upload(f.claims(), body).mustStatus(t, http.StatusForbidden, "content that is not in the trusted commit")

	if r := f.h.do(request{method: http.MethodGet, path: "/api/v1/ai-context/source/" + f.repo.ID + "/read?path=src/main.go", cookie: f.cookie}); r.status == http.StatusOK {
		t.Fatal("a refused upload became readable source")
	}
}

// A controller that cannot reach GitHub's signing keys says so as a 503 with
// the host to allow, not a 401 that would send the operator to the workflow.
func TestAnUploadTheControllerCannotCheckIsUnavailableNotUnauthorised(t *testing.T) {
	f := zoomiesOnlyFixture(t)
	f.h.ctrl.SetActionsIssuer("http://127.0.0.1:1")
	claims := f.claims()
	claims["iss"] = "http://127.0.0.1:1"
	r := f.upload(claims, f.snapshot)
	r.mustStatus(t, http.StatusServiceUnavailable, "an upload whose token could not be checked")
	if !strings.Contains(string(r.body), "127.0.0.1:1") {
		t.Fatalf("the refusal does not name the host to allow: %s", r.body)
	}
}

func TestAnEnterpriseServerUploadIsCheckedAgainstThatServersOwnKeys(t *testing.T) {
	f := zoomiesOnlyFixtureOn(t, "ghes.example.org")
	if workflow, _ := f.h.gh.FileContent(f.repo.FullName, aicontext.WorkflowPath); !strings.Contains(workflow, "upload-artifact@c6a366c94c3e0affe28c06c8df20a878f24da3cf") {
		t.Fatal("the merged setup did not use the Enterprise Server workflow")
	}
	// GitHub.com's issuer vouches for GitHub.com's repositories. A token it
	// signed with this repository's numeric ID is about some other repository
	// that happens to share it, and must not reach this one.
	f.uploadSignedBy(f.dotcom, f.claims(), f.snapshot).mustStatus(t, http.StatusNotFound, "a GitHub.com token for an Enterprise Server repository")
	f.upload(f.claims(), f.snapshot).mustStatus(t, http.StatusAccepted, "the Enterprise Server workflow's upload")
	r := f.h.do(request{method: http.MethodGet, path: "/api/v1/ai-context/source/" + f.repo.ID + "/read?path=src/main.go", cookie: f.cookie})
	r.mustStatus(t, http.StatusOK, "reading the uploaded context")
}

func TestATokenFromAnIssuerZoomiesDoesNotKnowIsNeverFetched(t *testing.T) {
	f := zoomiesOnlyFixture(t)
	// A stranger can sign a token naming any issuer it likes. Following it
	// would let anyone make the controller fetch keys from an address of
	// their choosing, so only known issuers are ever contacted.
	fetched := false
	stranger := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { fetched = true }))
	t.Cleanup(stranger.Close)
	claims := f.claims()
	claims["iss"] = stranger.URL
	f.upload(claims, f.snapshot).mustStatus(t, http.StatusUnauthorized, "a token from an unknown issuer")
	claims["iss"] = github.ActionsIssuerFor("unknown.example.org")
	f.upload(claims, f.snapshot).mustStatus(t, http.StatusUnauthorized, "a token from an Enterprise Server with no repository here")
	if fetched {
		t.Fatal("the controller fetched keys from an issuer the token named")
	}
}

// omittingSnapshot is the fixture's snapshot with the oversized file listed
// rather than carried, as the generator now writes it.
func (f *uploadFixture) omittingSnapshot(t *testing.T, edit func(*aicontext.Omitted)) []byte {
	t.Helper()
	var snapshot aicontext.Snapshot
	if err := json.Unmarshal(f.snapshot, &snapshot); err != nil {
		t.Fatal(err)
	}
	snapshot.Omitted = []aicontext.Omitted{{Path: uploadBigFile, Bytes: aicontext.MaxFileBytes + 7, Reason: aicontext.OmittedTooLarge}}
	if edit != nil {
		edit(&snapshot.Omitted[0])
	}
	body, err := json.Marshal(snapshot)
	if err != nil {
		t.Fatal(err)
	}
	return body
}

func TestAnUploadThatOmitsAFileTellsEveryReaderWhatIsMissing(t *testing.T) {
	f := zoomiesOnlyFixture(t)
	f.upload(f.claims(), f.omittingSnapshot(t, nil)).mustStatus(t, http.StatusAccepted, "an upload that lists an oversized file")
	source := "/api/v1/ai-context/source/" + f.repo.ID

	r := f.h.do(request{method: http.MethodGet, path: source + "/overview", cookie: f.cookie})
	r.mustStatus(t, http.StatusOK, "the overview")
	var overview struct {
		Total        int `json:"total"`
		OmittedTotal int `json:"omitted_total"`
		Files        []struct {
			Path    string `json:"path"`
			Bytes   int    `json:"bytes"`
			Omitted string `json:"omitted"`
		} `json:"files"`
	}
	if err := json.Unmarshal(r.body, &overview); err != nil {
		t.Fatal(err)
	}
	listed := false
	for _, file := range overview.Files {
		if file.Path == uploadBigFile {
			listed = file.Omitted == aicontext.OmittedTooLarge && file.Bytes == aicontext.MaxFileBytes+7
		}
	}
	if !listed || overview.OmittedTotal != 1 || overview.Total != 2 {
		t.Fatalf("the overview does not show the omitted file: %s", r.body)
	}

	r = f.h.do(request{method: http.MethodGet, path: source + "/read?path=" + uploadBigFile, cookie: f.cookie})
	r.mustStatus(t, http.StatusOK, "reading an omitted file")
	if !strings.Contains(string(r.body), `"omitted":"too_large"`) || !strings.Contains(string(r.body), `"text":""`) || strings.Contains(string(r.body), "aaaa") {
		t.Fatalf("a read of an omitted file should say why there is no text: %s", r.body)
	}

	r = f.h.do(request{method: http.MethodGet, path: source + "/search?query=widgets", cookie: f.cookie})
	r.mustStatus(t, http.StatusOK, "a search")
	if !strings.Contains(string(r.body), `"omitted_total":1`) {
		t.Fatalf("a search does not say the context is incomplete: %s", r.body)
	}
}

func TestAnUploadCannotListFilesTheTrustedCommitDoesNotHave(t *testing.T) {
	f := zoomiesOnlyFixture(t)
	for name, edit := range map[string]func(*aicontext.Omitted){
		"a file that is not in the commit":        func(o *aicontext.Omitted) { o.Path = "assets/never-existed.js" },
		"a size that is not the file's size":      func(o *aicontext.Omitted) { o.Bytes = aicontext.MaxFileBytes + 99 },
		"a carried file claimed to be omitted":    func(o *aicontext.Omitted) { o.Path, o.Bytes = "src/main.go", 16 },
		"a file under the limit labelled as such": func(o *aicontext.Omitted) { o.Bytes = 10 },
	} {
		f.upload(f.claims(), f.omittingSnapshot(t, edit)).mustNotSucceed(t, name)
	}
	if r := f.h.do(request{method: http.MethodGet, path: "/api/v1/ai-context/source/" + f.repo.ID + "/overview", cookie: f.cookie}); r.status == http.StatusOK {
		t.Fatal("a refused upload became readable context")
	}
}

func (r *response) mustNotSucceed(t *testing.T, what string) {
	t.Helper()
	if r.status >= 200 && r.status < 300 {
		t.Fatalf("%s was accepted (status %d): %s", what, r.status, truncate(r.body))
	}
}

package api

import (
	"context"
	"encoding/json"
	"net/http"

	"github.com/eyupio/zoomies/internal/assistant"
	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/mcp"
)

// assistantToolbox is the fleet's read tools for the assistant, as the person
// chatting may use them. It is the MCP server over the in-process API with that
// person's identity and no leave to offer a tool that changes anything, so the
// tools, their refusals and their limits are the ones an agent of theirs meets,
// and a viewer's Eli sees what a viewer's token would.
type assistantToolbox struct {
	server *mcp.Server
}

func (s *Server) assistantToolbox(r *http.Request, as *auth.Identity) *assistantToolbox {
	return &assistantToolbox{server: mcp.New(inProcessAPI{s: s, from: r, as: as, direct: true}, mcp.Options{
		WindowBlock:   controller.AssistantWindowBlock,
		MaxWait:       controller.AssistantMaxWait,
		WithheldKinds: controller.AssistantWithheldKinds,
	})}
}

func (b *assistantToolbox) Tools() []assistant.Tool {
	defs := b.server.Definitions()
	out := make([]assistant.Tool, 0, len(defs))
	for _, d := range defs {
		schema, err := json.Marshal(d.InputSchema)
		if err != nil {
			continue
		}
		out = append(out, assistant.Tool{Name: d.Name, Description: d.Description, Parameters: schema, Live: d.Live})
	}
	return out
}

func (b *assistantToolbox) Call(ctx context.Context, name string, args json.RawMessage) ([]string, bool, error) {
	return b.server.CallTool(ctx, name, args)
}

package api

import (
	"context"
	"net/http"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/store"
)

// The event stream carries every audit row as it is written, and GET /audit
// filters what a caller may read of one. The stream did not: a viewer with the
// Overview open was sent the whole document of a settings change, backup
// directory and all, the moment the platform made it. The browser-level
// audience test found it.
func TestAnAuditFrameIsFilteredAsTheAuditLogIs(t *testing.T) {
	h := newHarness(t)
	viewer, _ := h.user("watcher", store.RoleViewer)
	admin, _ := h.user("fleet-admin", store.RoleAdmin)
	plat, _ := h.user("operator-of-record", store.RolePlatform)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	asViewer, _ := h.openStream(t, ctx, "/api/v1/events", h.session(viewer), nil)
	asAdmin, _ := h.openStream(t, ctx, "/api/v1/events", h.session(admin), nil)
	asPlatform, _ := h.openStream(t, ctx, "/api/v1/events", h.session(plat), nil)
	for _, frames := range []<-chan sseFrame{asViewer, asAdmin, asPlatform} {
		await(t, frames, "the opening comment", func(f sseFrame) bool { return f.comment != "" })
	}

	const where = "/srv/the-platforms-backups"
	h.do(request{
		method: http.MethodPatch, path: "/api/v1/settings", cookie: h.session(plat),
		body: map[string]any{"backup.directory": where, "scheduler.interval": "12s"},
	}).mustStatus(t, http.StatusOK, "change a platform and a fleet setting together")

	isSettings := func(f sseFrame) bool {
		return f.event == string(events.KindAudit) && strings.Contains(f.data, `"target_kind":"settings"`)
	}
	if f := await(t, asViewer, "the viewer's audit frame", isSettings); strings.Contains(f.data, where) || strings.Contains(f.data, "12s") {
		t.Errorf("a viewer's audit frame carries the settings document: %s", f.data)
	}
	f := await(t, asAdmin, "the administrator's audit frame", isSettings)
	if strings.Contains(f.data, where) {
		t.Errorf("an administrator's audit frame carries the platform's backup directory: %s", f.data)
	}
	if !strings.Contains(f.data, "12s") {
		t.Errorf("an administrator's audit frame lost the fleet's own change: %s", f.data)
	}
	if f := await(t, asPlatform, "the platform's audit frame", isSettings); !strings.Contains(f.data, where) {
		t.Errorf("the platform's audit frame is missing its own change: %s", f.data)
	}

	// And the list says the same thing to the same people.
	listed := h.do(request{method: http.MethodGet, path: "/api/v1/audit", cookie: h.session(admin)})
	listed.mustStatus(t, http.StatusOK, "list the audit log as admin")
	if strings.Contains(string(listed.body), where) {
		t.Errorf("an administrator's audit log carries the platform's backup directory")
	}
}

package api

import (
	"context"
	"errors"
	"log/slog"
	"net"
	"net/http"
	"net/url"
	"slices"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/logging"
)

// SessionCookie is the name of the cookie a browser session lives in. It is
// exported because the OpenAPI document names it and the CLI's browser-login
// helper has to read it back.
const SessionCookie = "zoomies_session"

// maxAgentSessionBytes bounds the X-Zoomies-Agent-Session header before it is
// folded into a host's row. The legitimate value is `ses_` plus sixteen hex
// characters, so 128 bytes is a generous ceiling that still refuses one that
// could have come only from an agent trying to pad its own host's row.
const maxAgentSessionBytes = 128

// ctxKey is this package's private context key type, so nothing outside can
// collide with -- or forge -- what the middleware attaches.
type ctxKey int

const (
	ctxRequestInfo ctxKey = iota
	// ctxAgentHost carries the host an agent request authenticated as.
	ctxAgentHost
	// ctxInProcess carries the identity an in-process MCP tool call acts as.
	// It is set only by inProcessAPI, on a request that never touched the
	// network, and the key is private to this package, so nothing a client
	// sends can produce it.
	ctxInProcess
)

// requestInfo is what the middleware chain learns about a request, in one
// place.
//
// It is a pointer in the context and filled in as the chain goes, because the
// outermost middleware (which logs the request) needs the identity that an
// inner one resolves, and a middleware cannot see a context its own callee
// replaced.
type requestInfo struct {
	id string
	ip string
	// identity is nil until the authentication middleware has run, and stays
	// nil on the unauthenticated routes.
	identity *auth.Identity
	log      *slog.Logger
}

func infoFrom(ctx context.Context) *requestInfo {
	info, _ := ctx.Value(ctxRequestInfo).(*requestInfo)
	return info
}

// Identity returns the authenticated caller, or nil on an unauthenticated
// route. Handlers use it for audit attribution and for the checks that depend
// on who is asking rather than on the route alone.
func Identity(ctx context.Context) *auth.Identity {
	if info := infoFrom(ctx); info != nil {
		return info.identity
	}
	return nil
}

// clientIP returns the address a request came from, resolved through the proxies
// the operator has said to trust.
func ClientIP(ctx context.Context) string {
	if info := infoFrom(ctx); info != nil {
		return info.ip
	}
	return ""
}

// RequestID returns the identifier this request is logged under, which is what
// an internal error hands back so an operator can find the log line.
func RequestID(ctx context.Context) string {
	if info := infoFrom(ctx); info != nil {
		return info.id
	}
	return ""
}

// logger returns the request-scoped logger.
func (s *Server) logger(r *http.Request) *slog.Logger {
	if info := infoFrom(r.Context()); info != nil && info.log != nil {
		return info.log
	}
	return s.log
}

// ---------------------------------------------------------------------------
// Authentication
// ---------------------------------------------------------------------------

// authenticate resolves the caller and refuses the request when it cannot.
//
// When security.disable_auth is set, auth.Authenticate hands back the
// "auth-disabled" administrator for every request; the warning about that is
// logged once at startup rather than here, because a line per request is a line
// nobody reads.
func (s *Server) authenticate(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		info := infoFrom(r.Context())
		id, err := s.resolveIdentity(r)
		if err != nil {
			// A credential the controller could not check is not one it
			// refused: a 401 makes the UI drop a session that is still good,
			// and quoting the driver's error hands a caller the database's
			// wording.
			if errors.Is(err, auth.ErrAuthBackend) {
				s.internal(w, r, "checking your credentials", err)
				return
			}
			unauthorized(w, err.Error())
			return
		}
		if info != nil {
			info.identity = id
			info.log = info.log.With("identity", id.String())
		}
		s.forgetLapsedSession(w, r, id)
		next.ServeHTTP(w, r)
	})
}

// forgetLapsedSession clears the session cookie of a browser that sent one and
// was answered as a public view's visitor: the session behind it ran out or was
// ended. Without this the browser presents the dead cookie on every request for
// as long as it keeps it, and the person cannot sign out of it, because there is
// nothing to sign out of.
func (s *Server) forgetLapsedSession(w http.ResponseWriter, r *http.Request, id *auth.Identity) {
	if !auth.IsVisitor(id) {
		return
	}
	if _, err := r.Cookie(SessionCookie); err == nil {
		s.clearSessionCookie(w)
	}
}

// refuseVisitors closes the caller's own routes, the ones under /auth that
// carry no action because each is somebody's own, to a public view's visitor.
// A visitor has no password, no sessions, no preferences and no connections,
// and signing out writes an audit row, so leaving these open would let an
// anonymous loop fill the audit log.
func (s *Server) refuseVisitors(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if auth.IsVisitor(Identity(r.Context())) {
			forbidden(w, "this is a read-only public view; sign in to do this")
			return
		}
		next.ServeHTTP(w, r)
	})
}

// optionalAuth resolves the caller when a credential is present but lets the
// request through when it is not. It is what /meta and the login routes use, so
// that a signed-in operator's actions are still attributed in the audit log.
func (s *Server) optionalAuth(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if id, err := s.resolveIdentity(r); err == nil {
			if info := infoFrom(r.Context()); info != nil {
				info.identity = id
			}
			// The lapsed cookie is not cleared here: these are the sign-in
			// routes, and a clearing header beside the one that sets the new
			// session leaves the browser to settle which wins. GET
			// /auth/session, which the UI asks on every boot, clears it.
		}
		next.ServeHTTP(w, r)
	})
}

// resolveIdentity turns the request's credentials into an identity.
func (s *Server) resolveIdentity(r *http.Request) (*auth.Identity, error) {
	if check, ok := r.Context().Value(contextCredentialCheck{}).(func(context.Context) (*auth.Identity, error)); ok {
		return check(r.Context())
	}
	if id := inProcessIdentity(r); id != nil {
		return id, nil
	}
	in := auth.AuthInput{
		Authorization: r.Header.Get("Authorization"),
		IP:            ClientIP(r.Context()),
	}
	if c, err := r.Cookie(SessionCookie); err == nil {
		in.SessionCookie = c.Value
	}
	return s.auth.Authenticate(r.Context(), in)
}

func hasBearer(r *http.Request) bool {
	scheme, _, ok := strings.Cut(strings.TrimSpace(r.Header.Get("Authorization")), " ")
	return ok && strings.EqualFold(scheme, "bearer")
}

// require refuses a caller whose role or scopes do not reach the action.
//
// The policy lives in internal/auth's table, not here: this middleware only
// asks. That is what makes "every route has a role" a property a test can walk,
// and what stops a new endpoint from shipping without anyone deciding who may
// call it.
func (s *Server) require(action auth.Action) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			id := Identity(r.Context())
			if id == nil {
				unauthorized(w, auth.ErrNoCredentials.Error())
				return
			}
			if !auth.Allowed(id, action) {
				forbidden(w, auth.Explain(id, action))
				return
			}
			next.ServeHTTP(w, r)
		})
	}
}

// ---------------------------------------------------------------------------
// Cross-site request forgery
// ---------------------------------------------------------------------------

// csrf refuses an unsafe cross-origin request that carries the session cookie.
//
// Bearer requests are exempt, and deliberately so: a browser cannot attach an
// Authorization header to a cross-origin request without a CORS preflight,
// which this server never grants, so a token-authenticated call cannot be made
// by a page the operator merely visited. A cookie, by contrast, rides along on
// its own, which is exactly what makes the check necessary here.
//
// The check runs on the whole /api/v1 subtree rather than only on
// cookie-authenticated routes, because POST /auth/login mints the cookie and a
// login CSRF -- signing the victim into the attacker's account -- is worth
// refusing too.
func (s *Server) csrf(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet, http.MethodHead, http.MethodOptions:
			next.ServeHTTP(w, r)
			return
		}
		if hasBearer(r) {
			next.ServeHTTP(w, r)
			return
		}
		if msg := s.checkOrigin(r); msg != "" {
			forbidden(w, msg)
			return
		}
		next.ServeHTTP(w, r)
	})
}

// checkOrigin returns "" when the request is same-origin (or from an origin the
// operator allowed), and otherwise the sentence to refuse it with.
func (s *Server) checkOrigin(r *http.Request) string {
	// Sec-Fetch-Site is the browser's own answer and cannot be set by script.
	// "none" is a user-initiated navigation, which is not a forged request.
	switch strings.ToLower(r.Header.Get("Sec-Fetch-Site")) {
	case "same-origin", "none":
		return ""
	case "":
		// Not sent: either an older browser or a non-browser client. Fall
		// through to the Origin header.
	default:
		if s.originAllowed(r.Header.Get("Origin")) || s.sameOriginAsRequest(r, r.Header.Get("Origin")) {
			return ""
		}
		from := strings.TrimSpace(r.Header.Get("Origin"))
		if from == "" {
			from = "another site"
		}
		return "this request came from " + from + " (Sec-Fetch-Site: " + r.Header.Get("Sec-Fetch-Site") +
			"), which is not this controller's origin. Add it to server.allowed_origins if that is deliberate, or use an API token."
	}

	origin := strings.TrimSpace(r.Header.Get("Origin"))
	if origin == "" {
		if r.Header.Get("Referer") == "" && !hasCookie(r, SessionCookie) && !hasCookie(r, SignInCookie) {
			// No cookie, no browser headers: a plain client that is about to be
			// asked for credentials anyway.
			return ""
		}
		return "this request carried no Origin or Sec-Fetch-Site header, so it cannot be shown to have come from the Zoomies UI. " +
			"Use a browser, or authenticate with an API token, which is exempt from this check."
	}
	if s.originAllowed(origin) || s.sameOriginAsRequest(r, origin) {
		return ""
	}
	return "this request came from " + origin + ", which is not this controller's origin. " +
		"Add it to server.allowed_origins if that is deliberate, or use an API token."
}

// originAllowed reports whether an Origin header names this controller or one
// of the origins the operator listed.
func (s *Server) originAllowed(origin string) bool {
	origin = strings.TrimSpace(origin)
	if origin == "" {
		return false
	}
	for _, allowed := range s.cfg().Server.AllowedOrigins {
		if strings.EqualFold(strings.TrimRight(strings.TrimSpace(allowed), "/"), strings.TrimRight(origin, "/")) {
			return true
		}
		if allowed == "*" {
			return true
		}
	}
	if ext := s.cfg().Server.ExternalURL; ext != "" {
		if u, err := url.Parse(ext); err == nil && sameOrigin(u, origin) {
			return true
		}
	}
	return false
}

// sameOrigin compares an Origin header with a URL's scheme and host.
func sameOrigin(u *url.URL, origin string) bool {
	o, err := url.Parse(origin)
	if err != nil {
		return false
	}
	return strings.EqualFold(o.Scheme, u.Scheme) && strings.EqualFold(o.Host, u.Host)
}

// sameOriginAsRequest reports whether origin matches the host the request was
// addressed to. It is the fallback when server.external_url is not configured,
// which is the common case on a loopback development instance.
func (s *Server) sameOriginAsRequest(r *http.Request, origin string) bool {
	o, err := url.Parse(origin)
	if err != nil || o.Host == "" {
		return false
	}
	if !strings.EqualFold(o.Host, r.Host) {
		return false
	}
	return strings.EqualFold(o.Scheme, s.requestScheme(r))
}

func hasCookie(r *http.Request, name string) bool {
	_, err := r.Cookie(name)
	return err == nil
}

// ---------------------------------------------------------------------------
// The session cookie
// ---------------------------------------------------------------------------

// setSessionCookie installs a browser session.
//
// SameSite=Lax rather than Strict so that following a link into Zoomies from
// another tab does not land on a login page; the same-origin check above is
// what defends the unsafe methods, and it does not depend on the cookie policy.
func (s *Server) setSessionCookie(w http.ResponseWriter, token string) {
	http.SetCookie(w, &http.Cookie{
		Name:     SessionCookie,
		Value:    token,
		Path:     "/",
		HttpOnly: true,
		Secure:   s.cfg().CookieSecureValue(),
		SameSite: http.SameSiteLaxMode,
		MaxAge:   int(s.auth.SessionTTL() / time.Second),
	})
}

// startBrowserSession installs the session a completed sign-in has just
// created, and ends the one the browser was holding.
//
// Replacing the cookie is not enough: the session behind the old value stays
// valid in the database until it expires, so a person who signs in on a shared
// browser after somebody else leaves that person's access usable by anyone who
// still has the value. Called only once the new session exists, so a refused
// sign-in leaves the holder's session alone.
func (s *Server) startBrowserSession(w http.ResponseWriter, r *http.Request, token string) {
	if c, err := r.Cookie(SessionCookie); err == nil && c.Value != "" && c.Value != token {
		if err := s.auth.Logout(r.Context(), c.Value); err != nil {
			s.logger(r).Warn("could not end the session this browser held before signing in", "error", err)
		}
	}
	s.setSessionCookie(w, token)
}

// clearSessionCookie expires the cookie. The attributes have to match the ones
// it was set with or the browser keeps the old cookie alongside the new one.
func (s *Server) clearSessionCookie(w http.ResponseWriter) {
	http.SetCookie(w, &http.Cookie{
		Name:     SessionCookie,
		Value:    "",
		Path:     "/",
		HttpOnly: true,
		Secure:   s.cfg().CookieSecureValue(),
		SameSite: http.SameSiteLaxMode,
		MaxAge:   -1,
		Expires:  time.Unix(0, 0),
	})
}

// ---------------------------------------------------------------------------
// Agent authentication
// ---------------------------------------------------------------------------

// agentAuth resolves an agent's own token to its host.
//
// Agent credentials are a separate class from user ones: they are accepted on
// /api/v1/agent/* and nowhere else, and an identity from here carries the
// viewer role purely so that audit rows have an actor. The host is what the
// handlers actually work with, which is why it goes into the context too.
func (s *Server) agentAuth(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		h, err := s.auth.AuthenticateAgent(r.Context(), r.Header.Get("Authorization"))
		if err != nil {
			switch {
			case errors.Is(err, auth.ErrNoCredentials):
				unauthorized(w, "this endpoint is for agents; send the agent token issued at join as a bearer token")
			case errors.Is(err, auth.ErrInvalidCredentials):
				unauthorized(w, "this controller does not recognise that agent token; re-join the host with a fresh join token (zoomies agent join <controller-url> --token <join-token>)")
			default:
				s.internal(w, r, "authenticating an agent", err)
			}
			return
		}
		info := infoFrom(r.Context())
		id := auth.AgentIdentity(h, ClientIP(r.Context()))
		if info != nil {
			info.identity = id
			info.log = info.log.With("host", h.ID, "host_name", h.Name)
		}
		// Every authenticated agent request carries the session, so recording
		// it here catches a duplicate whichever call it makes first rather
		// than only on the heartbeat.
		//
		// The header is capped so that an authenticated agent cannot keep
		// writing arbitrarily large values into its host's row by alternating
		// them: a legitimate session is `ses_` plus sixteen hex characters,
		// well under this ceiling.
		if session := r.Header.Get(agent.HeaderAgentSession); len(session) <= maxAgentSessionBytes {
			s.ctrl.NoteAgentSession(r.Context(), h.ID, session)
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), ctxAgentHost, h)))
	})
}

// ---------------------------------------------------------------------------
// Client addresses
// ---------------------------------------------------------------------------

// resolveClientIP is the real-IP resolver.
//
// X-Forwarded-For is believed only when the connection itself came from a CIDR
// in server.trusted_proxies, and then only the right-most entry that is not
// itself a trusted proxy is taken. Anything else lets a client pick its own
// address, and with it defeat the login rate limiter and forge the address in
// every audit row it causes.
func (s *Server) resolveClientIP(r *http.Request) string {
	remote, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		remote = r.RemoteAddr
	}
	if len(s.trusted) == 0 || !s.isTrustedProxy(remote) {
		return remote
	}

	// Cloudflare sets CF-Connecting-IP to the true client address and cannot be
	// talked out of it, whereas X-Forwarded-For arrives as whatever the client
	// sent with Cloudflare's own value appended. Both resolve correctly here,
	// but only one of them is a single unambiguous value, so prefer it -- and
	// only when the connection itself came from one of Cloudflare's own
	// addresses. A trusted proxy that is not Cloudflare -- nginx, HAProxy --
	// forwards a header it does not recognise untouched, so from behind one of
	// those the header is whatever the client chose to send, and believing it
	// would let anyone pick the address the rate limiter and the audit log see.
	if cf := strings.TrimSpace(r.Header.Get("CF-Connecting-IP")); cf != "" && s.isCloudflare(remote) {
		if ip := net.ParseIP(strings.Trim(cf, "[]")); ip != nil {
			return ip.String()
		}
	}

	forwarded := r.Header.Values("X-Forwarded-For")
	var chain []string
	for _, header := range forwarded {
		for _, part := range strings.Split(header, ",") {
			if part = strings.TrimSpace(part); part != "" {
				chain = append(chain, part)
			}
		}
	}
	for i := len(chain) - 1; i >= 0; i-- {
		if ip := net.ParseIP(strings.Trim(chain[i], "[]")); ip != nil && !s.isTrustedProxy(chain[i]) {
			return ip.String()
		}
	}
	if real := strings.TrimSpace(r.Header.Get("X-Real-IP")); real != "" {
		if ip := net.ParseIP(real); ip != nil {
			return ip.String()
		}
	}
	return remote
}

// isCloudflare reports whether addr is one of Cloudflare's published edge
// addresses -- the only peer whose CF-Connecting-IP means anything.
func (s *Server) isCloudflare(addr string) bool {
	ip := net.ParseIP(strings.Trim(addr, "[]"))
	if ip == nil {
		return false
	}
	return slices.ContainsFunc(s.cloudflare, func(n *net.IPNet) bool { return n.Contains(ip) })
}

// requestScheme is the scheme the client actually used, as far as this
// controller can honestly tell.
//
// X-Forwarded-Proto is believed only when the connection itself came from a
// CIDR in server.trusted_proxies, exactly as X-Forwarded-For is. Anything else
// lets a client choose the scheme the controller thinks it was reached on --
// and that scheme decides whether an https:// Origin counts as same-origin,
// which is a CSRF check, and whether the response carries HSTS.
//
// A deployment behind a TLS-terminating proxy that has set neither
// trusted_proxies nor external_url now reads as http here. That is the honest
// answer: nothing about such a request distinguishes the proxy from anyone
// else who can reach the listener. It costs little in practice -- an Origin
// matching server.external_url is allowed before this is consulted, and a
// browser new enough to send Sec-Fetch-Site never reaches it at all -- and a
// missing external_url already raises a startup warning of its own.
func (s *Server) requestScheme(r *http.Request) string {
	if r.TLS != nil {
		return "https"
	}
	remote, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		remote = r.RemoteAddr
	}
	if len(s.trusted) == 0 || !s.isTrustedProxy(remote) {
		return "http"
	}
	// The left-most value, which is the scheme the original client used: a
	// chain of proxies appends, and the entries after the first describe hops
	// inside the operator's own network.
	proto := r.Header.Get("X-Forwarded-Proto")
	if i := strings.IndexByte(proto, ','); i >= 0 {
		proto = proto[:i]
	}
	if strings.EqualFold(strings.TrimSpace(proto), "https") {
		return "https"
	}
	return "http"
}

func (s *Server) isTrustedProxy(addr string) bool {
	ip := net.ParseIP(strings.Trim(addr, "[]"))
	if ip == nil {
		return false
	}
	return slices.ContainsFunc(s.trusted, func(n *net.IPNet) bool { return n.Contains(ip) })
}

// withRequestLogger attaches the request-scoped logger to the context so that
// anything downstream -- including the controller, which reads it through
// logging.FromContext -- logs with the request ID attached.
func withRequestLogger(ctx context.Context, l *slog.Logger) context.Context {
	return logging.WithLogger(ctx, l)
}

package api

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"reflect"
	"sort"
	"sync"
	"time"

	"github.com/go-chi/chi/v5"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/store"
)

// The controller proposes changes -- a sidecar share, a smallest runner, a warm
// runner -- each priced against the fleet before it is said. With
// security.auto_apply_remedies on it also makes them, and this file is how, with
// every limit that makes that something an operator can leave on:
//
//   - It is the controller's own proposal and nothing else. The change is never
//     composed here: this asks POST /problems/apply for the remedy the problems now
//     carry, so the route's checks, its refusal of a change that leaves a pool with
//     nowhere to run, and its audit row are the ones a person's click meets.
//   - A proposal has to stand unchanged for autopilotSteady first. The remedy's ID
//     covers the change it makes, so a proposal that moved starts again, and one
//     noisy window cannot make a change.
//   - A pool or host is changed at most once in autopilotCooldown, so a proposal
//     that keeps being re-worked cannot walk a size back and forth.
//   - What it replaced is written down, and a change is only ever undone to that,
//     only while nobody has edited the target since. A proposal that has been made
//     once is never made again, whether it was undone here or put back by hand:
//     whoever reversed it has answered the question.
//   - A memory share it gave a sidecar is taken back if a job in that pool is killed
//     for memory afterwards, to what it replaced and only while nobody has edited the
//     pool since. Autopilot sizes by what jobs used, and a kill is the proof that it was
//     wrong; leaving the change for an operator to notice is how one wrong guess
//     becomes a week of dead jobs.
//   - It makes one change a pass. Each one changes what the next proposal would
//     be, and the next pass is the controller's chance to see that.
const (
	autopilotInterval = 5 * time.Minute
	autopilotSteady   = 2 * time.Hour
	autopilotCooldown = 24 * time.Hour
	autopilotRetry    = time.Hour
	// autopilotWatch is how long after a memory share change a kill in the pool is blamed
	// on it. A week spans the weekly build that a window of light jobs would not.
	autopilotWatch = 7 * 24 * time.Hour
	// autoAppliedHistory is how far back the list of automatic changes reaches,
	// which is also how long an undo is offered.
	autoAppliedHistory = 30 * 24 * time.Hour

	auditAutoApplied = "problem.remedy_auto_applied"
	// auditAutoShadowed is a change shadow mode would have made, written once for each
	// proposal. It is not an applied change and nothing reads it as one: the cooldown,
	// the once-only rule and the undo list look only at auditAutoApplied.
	auditAutoShadowed = "problem.remedy_auto_shadowed"
	auditAutoUndone   = "problem.remedy_undone"
)

// autopilotIdentity is who the controller acts as: an operator, which is the role
// the apply route asks of anybody, and named so the audit log says whose change
// it was.
var autopilotIdentity = &auth.Identity{Kind: auth.KindSystem, ID: "autopilot", Name: "zoomies autopilot", Role: store.RoleOperator}

// autopilotState is what the loop remembers between passes: when each proposal
// was first seen, and when one that was refused may be tried again. Neither
// outlives a restart, which only makes the controller more patient.
type autopilotState struct {
	mu       sync.Mutex
	seen     map[string]time.Time
	retryAt  map[string]time.Time
	lastPass time.Time
}

func (s *Server) runAutopilot(ctx context.Context) {
	t := time.NewTicker(autopilotInterval)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-t.C:
			if err := s.autopilotPass(ctx); err != nil {
				s.log.Warn("applying suggested changes automatically", "error", err)
			}
		}
	}
}

// autopilotPass looks at the proposals now and makes at most one.
func (s *Server) autopilotPass(ctx context.Context) error {
	st := &s.autopilot
	st.mu.Lock()
	defer st.mu.Unlock()
	if st.seen == nil {
		st.seen, st.retryAt = map[string]time.Time{}, map[string]time.Time{}
	}
	mode := s.cfg().Security.AutoApplyMode()
	if mode == "off" {
		// Off forgets what it had seen, so turning it on later starts the wait afresh
		// rather than acting on a proposal that stood while nobody had asked.
		clear(st.seen)
		clear(st.retryAt)
		return nil
	}
	now := s.ctrl.Now()
	st.lastPass = now

	// Taking a harmful change back comes before making a new one, and does not wait on
	// the proposals below: it is about what already happened, not about what is proposed.
	if mode == "on" {
		if err := s.revertShareAfterMemoryKill(ctx, now); err != nil {
			return err
		}
	}

	items, err := s.ctrl.Problems(ctx)
	if err != nil {
		return fmt.Errorf("gathering the current problems: %w", err)
	}
	for i := range items {
		if items[i].Code == "controller.problems_partial" {
			// A part the controller could not read leaves its proposals out; acting on
			// what is left would be acting on half a picture.
			return nil
		}
	}
	present := map[string]bool{}
	var due []*controller.Problem
	for i := range items {
		p := &items[i]
		if p.Remedy == nil || !p.Audience.For(false) {
			continue
		}
		id := p.Remedy.ID
		present[id] = true
		first, ok := st.seen[id]
		if !ok {
			st.seen[id] = now
			continue
		}
		if now.Sub(first) >= autopilotSteady && !now.Before(st.retryAt[id]) {
			due = append(due, p)
		}
	}
	for id := range st.seen {
		if !present[id] {
			delete(st.seen, id)
			delete(st.retryAt, id)
		}
	}
	sort.Slice(due, func(i, j int) bool { return st.seen[due[i].Remedy.ID].Before(st.seen[due[j].Remedy.ID]) })

	for _, p := range due {
		if ok, err := s.mayAutoApply(ctx, p, now); err != nil {
			return err
		} else if !ok {
			continue
		}
		if mode == "shadow" {
			if err := s.recordShadowed(ctx, p); err != nil {
				return err
			}
			continue
		}
		if err := s.autoApply(ctx, p); err != nil {
			st.retryAt[p.Remedy.ID] = now.Add(autopilotRetry)
			s.log.Info("a suggested change was not applied automatically", "code", p.Code, "target", p.TargetID, "reason", err.Error())
			continue
		}
		return nil
	}
	return nil
}

// revertShareAfterMemoryKill takes back a sidecar memory share autopilot gave a pool
// when a job in the pool has been killed for memory since.
//
// The advice is sized on what jobs used, and a kill says that was too little for some
// job. The change is put back to what it replaced through the pool's own update, exactly
// as an operator's undo is, so it is refused where that is and it never runs over an
// edit: a pool somebody has changed since is left as they have it, and the change is
// recorded as superseded so it is not looked at again. Either way the proposal is not
// made again, because the record names it.
func (s *Server) revertShareAfterMemoryKill(ctx context.Context, now time.Time) error {
	records, undone, err := s.autoAppliedRecords(ctx)
	if err != nil {
		return fmt.Errorf("reading the automatic changes: %w", err)
	}
	for _, rec := range records {
		if undone[rec.row.ID] || rec.kind != controller.RemedyPoolUpdate || rec.code != "pool.daemon_share_suggested" || rec.applied == nil {
			continue
		}
		if now.Sub(rec.row.CreatedAt) > autopilotWatch || !changedMemoryShare(rec.before, rec.applied) {
			continue
		}
		since := rec.row.CreatedAt
		stats, err := s.ctrl.Store().JobStatsOf(ctx, store.JobFilter{Since: &since, PoolIDs: []string{rec.row.TargetID}}, []string{store.GroupByPool}, store.MeasurePeaks)
		if err != nil {
			return fmt.Errorf("reading what the pool's jobs have done since the change: %w", err)
		}
		killed := 0
		for _, g := range stats.Groups {
			killed += g.OOMKilled
		}
		if killed == 0 {
			continue
		}
		fields := map[string]any{"undoes": rec.row.ID, "remedy": rec.remedy, "label": rec.label, "auto": true,
			"reason": fmt.Sprintf("%d job(s) in the pool were killed for memory after the change", killed)}
		if !s.untouchedSince(ctx, rec) {
			fields["superseded"] = true
			s.auth.Auditor().Record(ctx, autopilotIdentity, auditAutoUndone, "pool", rec.row.TargetID, nil, fields)
			s.log.Info("a memory kill followed an automatic share change, but the pool was edited since so it is left as it is", "pool", rec.row.TargetID)
			continue
		}
		payload, err := json.Marshal(rec.before)
		if err != nil {
			return err
		}
		if status, answer := s.callAs(ctx, autopilotIdentity, http.MethodPatch, "/api/v1/pools/"+rec.row.TargetID, payload); status >= 400 {
			s.log.Warn("could not take back an automatic share change after a memory kill", "pool", rec.row.TargetID, "status", status, "answer", string(bytes.TrimSpace(answer)))
			continue
		}
		s.auth.Auditor().Record(ctx, autopilotIdentity, auditAutoUndone, "pool", rec.row.TargetID, rec.applied, fields)
		s.log.Info("took back an automatic share change: a job was killed for memory after it", "pool", rec.row.TargetID, "killed", killed)
		return nil
	}
	return nil
}

// changedMemoryShare reports whether a pool's resources, before and after an automatic
// change, differ in a share that decides what the sidecar's memory is.
func changedMemoryShare(before, applied map[string]any) bool {
	for _, key := range []string{"daemon_share_percent", "daemon_memory_share_percent"} {
		if !reflect.DeepEqual(resourceField(before, key), resourceField(applied, key)) {
			return true
		}
	}
	return false
}

func resourceField(snapshot map[string]any, key string) any {
	res, _ := snapshot["resources"].(map[string]any)
	return res[key]
}

// mayAutoApply is the cooldown and the once-only rule: false when this target has
// been changed automatically within autopilotCooldown, or when this very proposal
// has already been made to it.
func (s *Server) mayAutoApply(ctx context.Context, p *controller.Problem, now time.Time) (bool, error) {
	since := now.Add(-autopilotCooldown)
	recent, _, err := s.ctrl.Store().ListAudit(ctx, store.AuditFilter{Actions: []string{auditAutoApplied}, TargetID: p.Remedy.TargetID, Since: &since}, store.Page{Limit: 1})
	if err != nil {
		return false, fmt.Errorf("reading the automatic changes already made: %w", err)
	}
	if len(recent) > 0 {
		return false, nil
	}
	// A proposal that has been made, or made and then undone, is not made again. The
	// remedy's ID covers the change itself, so the same ID coming back means
	// somebody has put the target back as it was -- by undoing it or by editing it --
	// and that is an answer, whichever way it was given.
	for _, action := range []string{auditAutoApplied, auditAutoUndone} {
		rows, _, err := s.ctrl.Store().ListAudit(ctx, store.AuditFilter{Actions: []string{action}, TargetID: p.Remedy.TargetID}, store.Page{Limit: 500})
		if err != nil {
			return false, fmt.Errorf("reading the changes already made: %w", err)
		}
		for _, row := range rows {
			var a struct {
				Remedy string `json:"remedy"`
			}
			if json.Unmarshal([]byte(row.After), &a) == nil && a.Remedy == p.Remedy.ID {
				return false, nil
			}
		}
	}
	return true, nil
}

// recordShadowed writes down that a proposal is one shadow mode would have made, once for
// each proposal: the remedy's ID covers the change, so the same ID is the same change,
// and a proposal that moves is a new one. Nothing is changed. The record is what lets an
// operator read what turning the setting on would do before it does, and it is written
// with the same before-snapshot an applied change carries.
func (s *Server) recordShadowed(ctx context.Context, p *controller.Problem) error {
	r := p.Remedy
	rows, _, err := s.ctrl.Store().ListAudit(ctx, store.AuditFilter{Actions: []string{auditAutoShadowed}, TargetID: r.TargetID}, store.Page{Limit: 500})
	if err != nil {
		return fmt.Errorf("reading the changes shadow mode has recorded: %w", err)
	}
	for _, row := range rows {
		var a struct {
			Remedy string `json:"remedy"`
		}
		if json.Unmarshal([]byte(row.After), &a) == nil && a.Remedy == r.ID {
			return nil
		}
	}
	var body map[string]json.RawMessage
	if err := json.Unmarshal(r.Body, &body); err != nil {
		return nil
	}
	keys := make([]string, 0, len(body))
	for k := range body {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	before, err := s.targetSnapshot(ctx, r, keys)
	if err != nil {
		return err
	}
	s.auth.Auditor().Record(ctx, autopilotIdentity, auditAutoShadowed, targetKindOf(r), r.TargetID, before, map[string]any{
		"code": p.Code, "remedy": r.ID, "label": r.Label, "effect": r.Effect, "kind": r.Kind,
	})
	s.log.Info("a suggested change would have been applied automatically (shadow)", "code", p.Code, "target", r.TargetID, "change", r.Label)
	return nil
}

// autoApply makes one change and writes down what it replaced.
func (s *Server) autoApply(ctx context.Context, p *controller.Problem) error {
	r := p.Remedy
	var body map[string]json.RawMessage
	if err := json.Unmarshal(r.Body, &body); err != nil {
		return fmt.Errorf("the proposal's request is unreadable: %w", err)
	}
	keys := make([]string, 0, len(body))
	for k := range body {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	before, err := s.targetSnapshot(ctx, r, keys)
	if err != nil {
		return err
	}
	payload, err := json.Marshal(map[string]string{"code": p.Code, "target_id": p.TargetID, "remedy_id": r.ID})
	if err != nil {
		return err
	}
	if status, answer := s.callAs(ctx, autopilotIdentity, http.MethodPost, "/api/v1/problems/apply", payload); status >= 400 {
		return fmt.Errorf("the route answered %d: %s", status, bytes.TrimSpace(answer))
	}
	applied, err := s.targetSnapshot(ctx, r, keys)
	if err != nil {
		// The change is made; what it left is only needed to undo it safely, and
		// without it the undo is withheld, which is the careful way to fail.
		s.log.Warn("could not read back an automatic change", "target", r.TargetID, "error", err)
		applied = nil
	}
	s.auth.Auditor().Record(ctx, autopilotIdentity, auditAutoApplied, targetKindOf(r), r.TargetID, before, map[string]any{
		"code": p.Code, "remedy": r.ID, "label": r.Label, "effect": r.Effect, "kind": r.Kind, "applied": applied,
	})
	s.log.Info("applied a suggested change automatically", "code", p.Code, "target", r.TargetID, "change", r.Label)
	return nil
}

func targetKindOf(r *controller.Remedy) string {
	if r.Kind == controller.RemedyHostUpdate {
		return "host"
	}
	return "pool"
}

// targetSnapshot is the named top-level fields of the pool or host a remedy
// changes, as the store holds them. The fields are the request's own names, so
// what was there before can be sent back as an update.
//
// They are decoded values and not raw JSON, because the audit log redacts what it
// is given and a raw message is a byte slice to it: it would be written down as
// "[40 bytes]", which is not something to put back.
func (s *Server) targetSnapshot(ctx context.Context, r *controller.Remedy, keys []string) (map[string]any, error) {
	var v any
	var err error
	if r.Kind == controller.RemedyHostUpdate {
		v, err = s.ctrl.Store().GetHost(ctx, r.TargetID)
	} else {
		v, err = s.ctrl.Store().GetPool(ctx, r.TargetID)
	}
	if err != nil {
		return nil, fmt.Errorf("reading %s %s: %w", targetKindOf(r), r.TargetID, err)
	}
	raw, err := json.Marshal(v)
	if err != nil {
		return nil, err
	}
	var all map[string]any
	if err := json.Unmarshal(raw, &all); err != nil {
		return nil, err
	}
	out := make(map[string]any, len(keys))
	for _, k := range keys {
		out[k] = all[k]
	}
	return out, nil
}

// callAs is a request to this server's own router as an identity that has no
// credential to send: the controller itself.
func (s *Server) callAs(ctx context.Context, id *auth.Identity, method, path string, body []byte) (int, []byte) {
	ctx = context.WithValue(ctx, chi.RouteCtxKey, (*chi.Context)(nil))
	ctx = context.WithValue(noConfirm(ctx), ctxInProcess, id)
	req, err := http.NewRequestWithContext(ctx, method, path, bytes.NewReader(body))
	if err != nil {
		return http.StatusInternalServerError, []byte(err.Error())
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Accept", "application/json")
	req.RemoteAddr = "127.0.0.1:0"
	rec := &bufferedResponse{header: http.Header{}, limit: mcpResponseLimit}
	s.handler.ServeHTTP(rec, req)
	if rec.status == 0 {
		rec.status = http.StatusOK
	}
	return rec.status, rec.body.Bytes()
}

// autoAppliedChange is one automatic change as the list shows it.
type autoAppliedChange struct {
	ID       string                `json:"id"`
	At       time.Time             `json:"at"`
	Code     string                `json:"code"`
	Label    string                `json:"label"`
	Effect   string                `json:"effect,omitempty"`
	Kind     controller.RemedyKind `json:"kind"`
	TargetID string                `json:"target_id"`
	// Undone is true once somebody has reversed it. Undoable is false then, and
	// also when what the change left has been edited since or was never read back.
	Undone   bool `json:"undone"`
	Undoable bool `json:"undoable"`
}

type autoAppliedRecord struct {
	row     *store.AuditEvent
	before  map[string]any
	applied map[string]any
	remedy  string
	code    string
	label   string
	effect  string
	kind    controller.RemedyKind
}

// autoAppliedRecords is the automatic changes of the last autoAppliedHistory,
// newest first, and the set of them that have been undone.
func (s *Server) autoAppliedRecords(ctx context.Context) ([]autoAppliedRecord, map[string]bool, error) {
	since := s.ctrl.Now().Add(-autoAppliedHistory)
	rows, _, err := s.ctrl.Store().ListAudit(ctx, store.AuditFilter{Actions: []string{auditAutoApplied}, Since: &since}, store.Page{Limit: 500})
	if err != nil {
		return nil, nil, err
	}
	undoneRows, _, err := s.ctrl.Store().ListAudit(ctx, store.AuditFilter{Actions: []string{auditAutoUndone}, Since: &since}, store.Page{Limit: 500})
	if err != nil {
		return nil, nil, err
	}
	undone := map[string]bool{}
	for _, u := range undoneRows {
		var a struct {
			Undoes string `json:"undoes"`
		}
		if json.Unmarshal([]byte(u.After), &a) == nil && a.Undoes != "" {
			undone[a.Undoes] = true
		}
	}
	var out []autoAppliedRecord
	for _, row := range rows {
		rec := autoAppliedRecord{row: row}
		var after struct {
			Code    string                `json:"code"`
			Remedy  string                `json:"remedy"`
			Label   string                `json:"label"`
			Effect  string                `json:"effect"`
			Kind    controller.RemedyKind `json:"kind"`
			Applied map[string]any        `json:"applied"`
		}
		if json.Unmarshal([]byte(row.After), &after) != nil {
			continue
		}
		if json.Unmarshal([]byte(row.Before), &rec.before) != nil {
			continue
		}
		rec.applied, rec.remedy, rec.code, rec.label, rec.effect, rec.kind = after.Applied, after.Remedy, after.Code, after.Label, after.Effect, after.Kind
		out = append(out, rec)
	}
	return out, undone, nil
}

// handleAutoApplied answers GET /api/v1/problems/auto-applied.
func (s *Server) handleAutoApplied(w http.ResponseWriter, r *http.Request) {
	records, undone, err := s.autoAppliedRecords(r.Context())
	if err != nil {
		s.internal(w, r, "reading the automatic changes", err)
		return
	}
	out := make([]autoAppliedChange, 0, len(records))
	for _, rec := range records {
		c := autoAppliedChange{ID: rec.row.ID, At: rec.row.CreatedAt, Code: rec.code, Label: rec.label, Effect: rec.effect, Kind: rec.kind, TargetID: rec.row.TargetID, Undone: undone[rec.row.ID]}
		c.Undoable = !c.Undone && rec.applied != nil && s.untouchedSince(r.Context(), rec)
		out = append(out, c)
	}
	mode := s.cfg().Security.AutoApplyMode()
	would, err := s.shadowedChanges(r.Context())
	if err != nil {
		s.internal(w, r, "reading the changes shadow mode would have made", err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"enabled": mode == "on", "mode": mode, "items": out, "would_apply": would})
}

// shadowedChange is a change shadow mode would have made, as the list shows it.
type shadowedChange struct {
	ID       string                `json:"id"`
	At       time.Time             `json:"at"`
	Code     string                `json:"code"`
	Label    string                `json:"label"`
	Effect   string                `json:"effect,omitempty"`
	Kind     controller.RemedyKind `json:"kind"`
	TargetID string                `json:"target_id"`
}

// shadowedChanges is what shadow mode recorded in the last autoAppliedHistory, newest first.
func (s *Server) shadowedChanges(ctx context.Context) ([]shadowedChange, error) {
	since := s.ctrl.Now().Add(-autoAppliedHistory)
	rows, _, err := s.ctrl.Store().ListAudit(ctx, store.AuditFilter{Actions: []string{auditAutoShadowed}, Since: &since}, store.Page{Limit: 500})
	if err != nil {
		return nil, err
	}
	out := make([]shadowedChange, 0, len(rows))
	for _, row := range rows {
		var after struct {
			Code   string                `json:"code"`
			Label  string                `json:"label"`
			Effect string                `json:"effect"`
			Kind   controller.RemedyKind `json:"kind"`
		}
		if json.Unmarshal([]byte(row.After), &after) != nil {
			continue
		}
		out = append(out, shadowedChange{ID: row.ID, At: row.CreatedAt, Code: after.Code, Label: after.Label, Effect: after.Effect, Kind: after.Kind, TargetID: row.TargetID})
	}
	return out, nil
}

// untouchedSince reports whether the target still holds what the automatic change
// left in it.
func (s *Server) untouchedSince(ctx context.Context, rec autoAppliedRecord) bool {
	keys := make([]string, 0, len(rec.applied))
	for k := range rec.applied {
		keys = append(keys, k)
	}
	now, err := s.targetSnapshot(ctx, &controller.Remedy{Kind: rec.kind, TargetID: rec.row.TargetID}, keys)
	if err != nil {
		return false
	}
	return sameFields(now, rec.applied)
}

// sameFields compares two sets of fields as the JSON values they decode to.
func sameFields(a, b map[string]any) bool {
	return len(a) == len(b) && reflect.DeepEqual(a, b)
}

// handleUndoAutoApplied answers POST /api/v1/problems/auto-applied/{id}/undo.
//
// It puts back what the change replaced, through the pool's or host's own update
// as the caller, so it needs the role that update needs and is refused for what that
// update refuses. It will not run over an edit: if anyone has changed the target
// since, putting the old value back would undo their work too.
func (s *Server) handleUndoAutoApplied(w http.ResponseWriter, r *http.Request) {
	id := chi.URLParam(r, "id")
	records, undone, err := s.autoAppliedRecords(r.Context())
	if err != nil {
		s.internal(w, r, "reading the automatic changes", err)
		return
	}
	var rec *autoAppliedRecord
	for i := range records {
		if records[i].row.ID == id {
			rec = &records[i]
			break
		}
	}
	if rec == nil {
		notFound(w, "there is no automatic change "+id+" in the last 30 days; GET /problems/auto-applied lists them")
		return
	}
	if undone[id] {
		conflict(w, "that change has already been undone")
		return
	}
	action := auth.ActionPoolsWrite
	if rec.kind == controller.RemedyHostUpdate {
		action = auth.ActionHostsWrite
	}
	if who := Identity(r.Context()); !auth.Allowed(who, action) {
		forbidden(w, auth.Explain(who, action))
		return
	}
	if rec.applied == nil || !s.untouchedSince(r.Context(), *rec) {
		conflict(w, "that change cannot be undone safely: the "+targetKindOf(&controller.Remedy{Kind: rec.kind})+" was edited after it was made, and putting the old value back would undo that edit too. Change it by hand instead.")
		return
	}
	payload, err := json.Marshal(rec.before)
	if err != nil {
		s.internal(w, r, "undoing the change", err)
		return
	}
	req := r.Clone(noConfirm(r.Context()))
	req.URL.RawQuery = ""
	req.Body = io.NopCloser(bytes.NewReader(payload))
	req.Header.Set("Content-Type", "application/json")
	out := &bufferedResponse{header: http.Header{}, limit: mcpResponseLimit}

	target := rec.row.TargetID
	switch rec.kind {
	case controller.RemedyPoolUpdate:
		existing, gerr := s.ctrl.Store().GetPool(r.Context(), target)
		if gerr != nil {
			s.fail(w, r, "reading the pool", gerr)
			return
		}
		var body poolInput
		if !decode(out, req, &body) {
			s.relay(w, out)
			return
		}
		s.applyPoolUpdate(out, req, target, existing, &body)
	case controller.RemedyHostUpdate:
		h, gerr := s.ctrl.Store().GetHost(r.Context(), target)
		if gerr != nil {
			s.fail(w, r, "reading the host", gerr)
			return
		}
		var body hostUpdateRequest
		if !decode(out, req, &body) {
			s.relay(w, out)
			return
		}
		s.applyHostUpdate(out, req, target, h, &body)
	default:
		s.internal(w, r, "undoing the change", fmt.Errorf("a change of unknown kind %q", rec.kind))
		return
	}
	if out.status >= http.StatusBadRequest {
		s.relay(w, out)
		return
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), auditAutoUndone, targetKindOf(&controller.Remedy{Kind: rec.kind}), target, map[string]any{
		"undoes": id, "remedy": rec.remedy, "label": rec.label,
	})
	writeJSON(w, http.StatusOK, map[string]any{"undone": true, "id": id, "target_id": target})
}

package api

import (
	"encoding/json"
	"net/http"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/store"
)

// autopilotFleet is remedyFleet with the switch on, and a way to say a proposal
// has stood for as long as the controller waits for: the steady wait is the part a
// test cannot sit through, so it is aged by hand and everything else is real.
func autopilotFleet(t *testing.T, on bool) (*harness, *store.Host, string) {
	t.Helper()
	h, host := remedyFleet(t)
	h.cfg.Security.AutoApplyRemedies = map[bool]string{true: "on", false: "off"}[on]
	viewer := h.token("reader", store.RoleViewer)
	id, _ := h.remedyFor(viewer, "host.slots_below_capacity", host.ID)
	if id == "" {
		t.Fatal("the fixture must carry a remedy")
	}
	return h, host, id
}

func (h *harness) ageProposal(id string) {
	h.api.autopilot.mu.Lock()
	defer h.api.autopilot.mu.Unlock()
	h.api.autopilot.seen[id] = time.Now().Add(-3 * autopilotSteady)
}

func (h *harness) autoApplied() []autoAppliedChange {
	h.t.Helper()
	r := h.do(request{method: http.MethodGet, path: "/api/v1/problems/auto-applied", token: h.token("lister", store.RoleViewer)})
	if r.status != http.StatusOK {
		h.t.Fatalf("GET /problems/auto-applied = %d: %s", r.status, r.body)
	}
	var out struct {
		Items []autoAppliedChange `json:"items"`
	}
	if err := json.Unmarshal(r.body, &out); err != nil {
		h.t.Fatal(err)
	}
	return out.Items
}

// Off, the controller only proposes: a proposal can stand as long as it likes.
func TestTheControllerMakesNoChangeWhileAutomaticApplyIsOff(t *testing.T) {
	h, host, id := autopilotFleet(t, false)
	if err := h.api.autopilotPass(h.ctx); err != nil {
		t.Fatal(err)
	}
	h.api.autopilot.mu.Lock()
	h.api.autopilot.seen = map[string]time.Time{id: time.Now().Add(-3 * autopilotSteady)}
	h.api.autopilot.mu.Unlock()
	if err := h.api.autopilotPass(h.ctx); err != nil {
		t.Fatal(err)
	}
	if got, _ := h.st.GetHost(h.ctx, host.ID); got.RunnerProfile.Standard.CPUs != 6 {
		t.Errorf("the host was changed with the switch off: %+v", got.RunnerProfile)
	}
}

// The first pass only notes a proposal; one that has not stood long enough is left
// alone, and the change is then made as the route makes it, recorded with what it
// replaced.
func TestAProposalIsAppliedOnlyOnceItHasStoodAndIsRecordedWithWhatItReplaced(t *testing.T) {
	h, host, id := autopilotFleet(t, true)
	if err := h.api.autopilotPass(h.ctx); err != nil {
		t.Fatal(err)
	}
	if got, _ := h.st.GetHost(h.ctx, host.ID); got.RunnerProfile.Standard.CPUs != 6 {
		t.Fatal("a proposal seen for the first time was applied")
	}

	h.ageProposal(id)
	if err := h.api.autopilotPass(h.ctx); err != nil {
		t.Fatal(err)
	}
	after, _ := h.st.GetHost(h.ctx, host.ID)
	if after.RunnerProfile.Standard.CPUs >= 6 {
		t.Fatalf("the steady proposal was not applied: %+v", after.RunnerProfile)
	}
	rows, _, err := h.st.ListAudit(h.ctx, store.AuditFilter{Actions: []string{auditAutoApplied}}, store.Page{Limit: 5})
	if err != nil || len(rows) != 1 {
		t.Fatalf("audit rows = %v, %v; want one", rows, err)
	}
	if rows[0].ActorKind != "system" || rows[0].TargetID != host.ID || !strings.Contains(rows[0].Before, `"cpus":6`) {
		t.Errorf("the row must say who, where and what it replaced: %+v", rows[0])
	}
	// The route's own row is there too: this went through the apply route, not
	// around it.
	if rows, _, _ := h.st.ListAudit(h.ctx, store.AuditFilter{Actions: []string{"problem.remedy_applied"}}, store.Page{Limit: 5}); len(rows) != 1 {
		t.Errorf("the apply route's audit rows = %d; want 1", len(rows))
	}
	items := h.autoApplied()
	if len(items) != 1 || items[0].Undone || !items[0].Undoable || items[0].TargetID != host.ID {
		t.Errorf("list = %+v", items)
	}
}

// Undo puts back what was there, as the caller; and an undone proposal is never
// made again, which is the one answer an administrator gave.
func TestUndoPutsBackWhatTheChangeReplacedAndIsNotMadeAgain(t *testing.T) {
	h, host, id := autopilotFleet(t, true)
	h.api.autopilotPass(h.ctx)
	h.ageProposal(id)
	h.api.autopilotPass(h.ctx)
	items := h.autoApplied()
	if len(items) != 1 {
		t.Fatalf("items = %+v", items)
	}
	path := "/api/v1/problems/auto-applied/" + items[0].ID + "/undo"

	viewer := h.token("reader2", store.RoleViewer)
	if r := h.do(request{method: http.MethodPost, path: path, token: viewer}); r.status != http.StatusForbidden {
		t.Errorf("a viewer undoing = %d %s; want 403", r.status, r.body)
	}
	operator := h.token("actor", store.RoleOperator)
	if r := h.do(request{method: http.MethodPost, path: path, token: operator}); r.status != http.StatusOK {
		t.Fatalf("undoing = %d: %s", r.status, r.body)
	}
	if got, _ := h.st.GetHost(h.ctx, host.ID); got.RunnerProfile.Standard.CPUs != 6 {
		t.Errorf("the host was not put back: %+v", got.RunnerProfile)
	}
	if r := h.do(request{method: http.MethodPost, path: path, token: operator}); r.status != http.StatusConflict {
		t.Errorf("a second undo = %d; want 409", r.status)
	}
	if items := h.autoApplied(); !items[0].Undone || items[0].Undoable {
		t.Errorf("list after undo = %+v", items)
	}

	// The proposal is back, because the problem is: it is the same change, and it
	// stands as long as you like. It is not made again.
	newID, _ := h.remedyFor(h.token("reader3", store.RoleViewer), "host.slots_below_capacity", host.ID)
	if newID != id {
		t.Fatalf("the fixture should propose the same change again: %q vs %q", newID, id)
	}
	h.api.autopilotPass(h.ctx)
	h.ageProposal(id)
	h.api.autopilotPass(h.ctx)
	if got, _ := h.st.GetHost(h.ctx, host.ID); got.RunnerProfile.Standard.CPUs != 6 {
		t.Errorf("an undone proposal was applied again: %+v", got.RunnerProfile)
	}
}

// Putting the old value back over somebody's edit would undo the edit.
func TestUndoIsRefusedOverAnEditMadeSince(t *testing.T) {
	h, host, id := autopilotFleet(t, true)
	h.api.autopilotPass(h.ctx)
	h.ageProposal(id)
	h.api.autopilotPass(h.ctx)
	items := h.autoApplied()
	if len(items) != 1 {
		t.Fatalf("items = %+v", items)
	}
	edited := store.RunnerProfile{Standard: store.RunnerStandard{CPUs: 1, MemoryMB: 1024}}
	if err := h.st.PatchHost(h.ctx, host.ID, store.HostChanges{RunnerProfile: &edited}); err != nil {
		t.Fatal(err)
	}
	r := h.do(request{method: http.MethodPost, path: "/api/v1/problems/auto-applied/" + items[0].ID + "/undo", token: h.token("actor", store.RoleOperator)})
	if r.status != http.StatusConflict || !strings.Contains(string(r.body), "edited") {
		t.Errorf("undo over an edit = %d %s; want 409 naming the edit", r.status, r.body)
	}
	if h.autoApplied()[0].Undoable {
		t.Error("an edited target must not be offered an undo")
	}
}

// A pool or host is changed at most once a day: a second proposal for the same
// target waits.
func TestATargetIsChangedAutomaticallyAtMostOncePerCooldown(t *testing.T) {
	h, host, id := autopilotFleet(t, true)
	h.api.autopilotPass(h.ctx)
	h.ageProposal(id)
	h.api.autopilotPass(h.ctx)
	// A new, different proposal for the same host, as if the fleet had moved on.
	h.api.autopilot.mu.Lock()
	h.api.autopilot.seen["rem_other"] = time.Now().Add(-3 * autopilotSteady)
	h.api.autopilot.mu.Unlock()
	other := &controller.Problem{Remedy: &controller.Remedy{ID: "rem_other", TargetID: host.ID}}
	ok, err := h.api.mayAutoApply(h.ctx, other, time.Now())
	if err != nil || ok {
		t.Errorf("mayAutoApply within the cooldown = %v, %v; want false", ok, err)
	}
	ok, err = h.api.mayAutoApply(h.ctx, other, time.Now().Add(autopilotCooldown+time.Hour))
	if err != nil || !ok {
		t.Errorf("mayAutoApply after the cooldown = %v, %v; want true", ok, err)
	}
}

func TestAutomaticApplyIsShadowByDefaultAndNeverChangesAnythingThere(t *testing.T) {
	if mode := config.Default().Security.AutoApplyMode(); mode != "shadow" {
		t.Errorf("automatic apply defaults to %q; it must only record what it would do until an administrator turns it on", mode)
	}
	// The older spellings are still read, as on and off.
	for in, want := range map[string]string{"true": "on", "false": "off", "on": "on", "off": "off", "shadow": "shadow", "": "shadow", "bogus": "shadow"} {
		if got := (config.Security{AutoApplyRemedies: in}).AutoApplyMode(); got != want {
			t.Errorf("AutoApplyMode(%q) = %q, want %q", in, got, want)
		}
	}
}

// A person who puts an automatic change back by hand has said no as plainly as one
// who clicked Undo: the same proposal returning after the cooldown is not made again.
func TestAProposalAlreadyMadeIsNotMadeAgainAfterTheCooldownEvenIfRevertedByHand(t *testing.T) {
	h, host, id := autopilotFleet(t, true)
	h.api.autopilotPass(h.ctx)
	h.ageProposal(id)
	h.api.autopilotPass(h.ctx)
	original := store.RunnerProfile{Standard: store.RunnerStandard{CPUs: 6, MemoryMB: 6656}}
	if err := h.st.PatchHost(h.ctx, host.ID, store.HostChanges{RunnerProfile: &original}); err != nil {
		t.Fatal(err)
	}
	same := &controller.Problem{Remedy: &controller.Remedy{ID: id, TargetID: host.ID}}
	ok, err := h.api.mayAutoApply(h.ctx, same, time.Now().Add(autopilotCooldown+time.Hour))
	if err != nil || ok {
		t.Errorf("mayAutoApply for a proposal already made = %v, %v; want false", ok, err)
	}
}

// Shadow mode does the whole of the work except the change: a proposal that has stood is
// recorded as one it would have made, once, and the target is left exactly as it was. The
// record is not an applied change, so the cooldown and the undo list do not see it and
// turning the setting on afterwards still makes the change.
func TestShadowModeRecordsWhatItWouldHaveDoneOnceAndChangesNothing(t *testing.T) {
	h, host, id := autopilotFleet(t, true)
	h.cfg.Security.AutoApplyRemedies = "shadow"
	if err := h.api.autopilotPass(h.ctx); err != nil {
		t.Fatal(err)
	}
	h.ageProposal(id)
	for i := 0; i < 3; i++ {
		if err := h.api.autopilotPass(h.ctx); err != nil {
			t.Fatal(err)
		}
	}
	if got, _ := h.st.GetHost(h.ctx, host.ID); got.RunnerProfile.Standard.CPUs != 6 {
		t.Fatalf("shadow mode changed the host: %+v", got.RunnerProfile)
	}
	rows, _, err := h.st.ListAudit(h.ctx, store.AuditFilter{Actions: []string{auditAutoShadowed}}, store.Page{Limit: 10})
	if err != nil || len(rows) != 1 {
		t.Fatalf("shadow rows after three passes = %d, %v; want one for the one proposal", len(rows), err)
	}
	if applied, _, _ := h.st.ListAudit(h.ctx, store.AuditFilter{Actions: []string{auditAutoApplied, "problem.remedy_applied"}}, store.Page{Limit: 10}); len(applied) != 0 {
		t.Errorf("shadow mode wrote an applied row: %+v", applied)
	}
	if len(h.autoApplied()) != 0 {
		t.Error("a shadowed change is listed as applied")
	}

	// Turned on, the same proposal is made: shadow did not use it up.
	h.cfg.Security.AutoApplyRemedies = "on"
	h.ageProposal(id)
	if err := h.api.autopilotPass(h.ctx); err != nil {
		t.Fatal(err)
	}
	if got, _ := h.st.GetHost(h.ctx, host.ID); got.RunnerProfile.Standard.CPUs >= 6 {
		t.Errorf("turning it on after shadow did not make the change: %+v", got.RunnerProfile)
	}
}

// sharePool is a docker-in-docker pool whose sidecar memory share autopilot has just
// raised from 50% to 80%, recorded as an applied change, so the revert has something to
// look at without sitting through the evidence a real proposal needs.
func sharePool(t *testing.T) (*harness, *store.Pool, string) {
	t.Helper()
	h := newHarness(t)
	pool := h.pool(h.installation(), "builders")
	pool.DockerMode = store.DockerDinD
	r := &controller.Remedy{Kind: controller.RemedyPoolUpdate, TargetID: pool.ID}
	before, err := h.api.targetSnapshot(h.ctx, r, []string{"resources"})
	if err != nil {
		t.Fatal(err)
	}
	pool.Resources.DaemonMemorySharePercent = 80
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	applied, err := h.api.targetSnapshot(h.ctx, r, []string{"resources"})
	if err != nil {
		t.Fatal(err)
	}
	h.cfg.Security.AutoApplyRemedies = "on"
	h.api.auth.Auditor().Record(h.ctx, autopilotIdentity, auditAutoApplied, "pool", pool.ID, before,
		map[string]any{"code": "pool.daemon_share_suggested", "remedy": "rem_share", "label": "Give the sidecar 80% of the memory", "kind": controller.RemedyPoolUpdate, "applied": applied})
	return h, pool, "rem_share"
}

func (h *harness) killForMemory(pool *store.Pool, n int64) {
	h.t.Helper()
	started := time.Now().Add(time.Minute)
	runner := "run_killed"
	if _, _, err := h.st.ApplyJob(h.ctx, &store.Job{GitHubJobID: n, Repo: "acme/widgets", Workflow: "ci", JobName: "build",
		Labels: store.StringSlice{"self-hosted"}, State: store.JobInProgress, PoolID: pool.ID, Matched: true,
		RunnerID: runner, QueuedAt: started, StartedAt: &started}); err != nil {
		h.t.Fatal(err)
	}
	if err := h.st.RecordJobUsage(h.ctx, runner, 1, 3000); err != nil {
		h.t.Fatal(err)
	}
	done := started.Add(time.Minute)
	if _, _, err := h.st.ApplyJob(h.ctx, &store.Job{GitHubJobID: n, Repo: "acme/widgets", State: store.JobCompleted,
		Conclusion: "failure", StartedAt: &started, CompletedAt: &done}); err != nil {
		h.t.Fatal(err)
	}
	if _, _, err := h.st.MarkJobOOMKilled(h.ctx, runner, "killed for memory"); err != nil {
		h.t.Fatal(err)
	}
}

// Autopilot sized the share by what jobs used, and a kill for memory is the proof it
// was wrong: the share is put back to what it replaced, as an undo would, and the
// proposal is not made again.
func TestAMemoryShareIsTakenBackWhenAJobInThePoolIsKilledAfterIt(t *testing.T) {
	h, pool, remedy := sharePool(t)
	if err := h.api.autopilotPass(h.ctx); err != nil {
		t.Fatal(err)
	}
	if got, _ := h.st.GetPool(h.ctx, pool.ID); got.Resources.DaemonMemorySharePercent != 80 {
		t.Fatalf("a share nothing has killed was taken back: %+v", got.Resources)
	}
	h.killForMemory(pool, 9001)
	if err := h.api.autopilotPass(h.ctx); err != nil {
		t.Fatal(err)
	}
	if got, _ := h.st.GetPool(h.ctx, pool.ID); got.Resources.DaemonMemorySharePercent != 0 {
		t.Fatalf("the share was not taken back after a memory kill: %+v", got.Resources)
	}
	items := h.autoApplied()
	if len(items) != 1 || !items[0].Undone || items[0].Undoable {
		t.Errorf("list = %+v; want the change shown as undone", items)
	}
	rows, _, _ := h.st.ListAudit(h.ctx, store.AuditFilter{Actions: []string{auditAutoUndone}}, store.Page{Limit: 5})
	if len(rows) != 1 || !strings.Contains(rows[0].After, remedy) || !strings.Contains(rows[0].After, "killed for memory") {
		t.Errorf("audit rows = %+v; want one saying why", rows)
	}
	// Nothing is left to do, and a second pass does not do it again.
	if err := h.api.autopilotPass(h.ctx); err != nil {
		t.Fatal(err)
	}
	if rows, _, _ := h.st.ListAudit(h.ctx, store.AuditFilter{Actions: []string{auditAutoUndone}}, store.Page{Limit: 5}); len(rows) != 1 {
		t.Errorf("the change was taken back %d times", len(rows))
	}
}

// A pool somebody has edited since is theirs: putting the old value back would undo
// their work, so the change is only recorded as superseded.
func TestAMemoryShareIsNotTakenBackOverAnEditMadeSince(t *testing.T) {
	h, pool, _ := sharePool(t)
	pool, _ = h.st.GetPool(h.ctx, pool.ID)
	pool.Resources.DaemonMemorySharePercent = 90
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	h.killForMemory(pool, 9002)
	if err := h.api.autopilotPass(h.ctx); err != nil {
		t.Fatal(err)
	}
	if got, _ := h.st.GetPool(h.ctx, pool.ID); got.Resources.DaemonMemorySharePercent != 90 {
		t.Errorf("an operator's edit was overwritten: %+v", got.Resources)
	}
	rows, _, _ := h.st.ListAudit(h.ctx, store.AuditFilter{Actions: []string{auditAutoUndone}}, store.Page{Limit: 5})
	if len(rows) != 1 || !strings.Contains(rows[0].After, "superseded") {
		t.Errorf("audit rows = %+v; want one marking the change superseded", rows)
	}
}

// Shadow mode makes no change, so it takes none back either.
func TestShadowModeTakesNothingBack(t *testing.T) {
	h, pool, _ := sharePool(t)
	h.cfg.Security.AutoApplyRemedies = "shadow"
	h.killForMemory(pool, 9003)
	if err := h.api.autopilotPass(h.ctx); err != nil {
		t.Fatal(err)
	}
	if got, _ := h.st.GetPool(h.ctx, pool.ID); got.Resources.DaemonMemorySharePercent != 80 {
		t.Errorf("shadow mode changed a pool: %+v", got.Resources)
	}
}

package api

import (
	"net/http"
	"slices"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/backup"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/controller"
)

// Adding a destination from the page, which is the half a file could not do:
// typed, tested, stored with its secret sealed, and used by the next pass.
func TestADestinationAddedOnThePageIsTestedStoredAndUsed(t *testing.T) {
	fake := backup.NewFakeS3("backups")
	t.Cleanup(fake.Close)
	h := newHarness(t, allowPrivateEgress)
	h.installation()
	cookie := h.platform()

	// Distinctive values, so "is the secret in the response?" is a question
	// with an exact answer rather than a search for the word "secret" among
	// field names that also contain it.
	const (
		secretKey  = "s3cr3t-value-never-served"
		passphrase = "passphrase-value-never-served"
	)
	body := map[string]any{
		"name": "offsite", "endpoint": fake.Endpoint(), "bucket": fake.Bucket(),
		"prefix": "fleet", "access_key_id": "AKIAEXAMPLE", "secret_access_key": secretKey,
		"passphrase": passphrase, "keep": 30,
	}

	// Tested before it is saved, which is the whole reason the button is there.
	resp := h.do(request{method: http.MethodPost, path: "/api/v1/backups/remotes/check", cookie: cookie, body: body})
	resp.mustStatus(t, http.StatusOK, "test a destination that is not saved yet")
	var check remoteCheckResponse
	resp.into(t, &check)
	if !check.OK {
		t.Fatalf("the draft was refused: %+v", check)
	}

	resp = h.do(request{method: http.MethodPost, path: "/api/v1/backups/remotes", cookie: cookie, body: body})
	resp.mustStatus(t, http.StatusCreated, "add a destination")
	var added controller.RemoteBackupStatus
	resp.into(t, &added)
	if added.Source != controller.RemoteSourceDatabase || added.ID == "" {
		t.Fatalf("what came back is %+v; a destination added here is a stored one", added)
	}
	if !added.Encrypted || !added.HasSecretKey || added.Keep != 30 {
		t.Errorf("the destination reads %+v", added)
	}

	// Neither secret ever comes back, in any shape. They are sealed at rest
	// and one-way on the wire: what a page can act on is whether one is set.
	if strings.Contains(string(resp.body), secretKey) || strings.Contains(string(resp.body), passphrase) {
		t.Fatalf("a secret was served back: %s", string(resp.body))
	}
	listing := h.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: cookie})
	if strings.Contains(string(listing.body), secretKey) || strings.Contains(string(listing.body), passphrase) {
		t.Fatalf("the backups page carries a secret: %s", string(listing.body))
	}

	// And it is a destination the fleet actually uses: taking a backup and
	// running the pass puts a copy in the bucket.
	taken := h.takeBackup(t, cookie)
	resp = h.do(request{method: http.MethodPost, path: "/api/v1/backups/offsite", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "copy offsite")
	var shipped shipResponse
	resp.into(t, &shipped)
	if shipped.Error != "" || len(shipped.Sent) != 1 || shipped.Sent[0].ID != taken.ID {
		t.Fatalf("the pass sent %+v (%s)", shipped.Sent, shipped.Error)
	}
	if keys := fake.Keys(); len(keys) != 1 || !strings.HasSuffix(keys[0], ".tar.gz"+backup.EncryptedExt) {
		t.Errorf("the bucket holds %v; the destination has a passphrase, so the archive is sealed", keys)
	}
}

// The two secrets follow the credential convention, and the difference between
// "leave it" and "clear it" is the difference between a sealed archive and a
// readable one -- so it is pinned rather than assumed.
func TestChangingADestinationLeavesTheSecretsItDoesNotMention(t *testing.T) {
	fake := backup.NewFakeS3("backups")
	t.Cleanup(fake.Close)
	h := newHarness(t, allowPrivateEgress)
	cookie := h.platform()

	create := map[string]any{
		"name": "offsite", "endpoint": fake.Endpoint(), "bucket": fake.Bucket(),
		"access_key_id": "AKIAEXAMPLE", "secret_access_key": "secret", "passphrase": "a long passphrase",
	}
	h.do(request{method: http.MethodPost, path: "/api/v1/backups/remotes", cookie: cookie, body: create}).
		mustStatus(t, http.StatusCreated, "add a destination")

	// A PATCH about the retention says nothing about the secrets, so both stay.
	resp := h.do(request{method: http.MethodPatch, path: "/api/v1/backups/remotes/offsite", cookie: cookie,
		body: map[string]any{"keep": 3}})
	resp.mustStatus(t, http.StatusOK, "change the retention")
	var patched controller.RemoteBackupStatus
	resp.into(t, &patched)
	if !patched.Encrypted || !patched.HasSecretKey || patched.Keep != 3 {
		t.Fatalf("the destination reads %+v after a change about the retention alone", patched)
	}

	// An explicit empty passphrase clears it, which is how a destination is
	// told to send the plain archive.
	resp = h.do(request{method: http.MethodPatch, path: "/api/v1/backups/remotes/offsite", cookie: cookie,
		body: map[string]any{"passphrase": ""}})
	resp.mustStatus(t, http.StatusOK, "clear the passphrase")
	resp.into(t, &patched)
	if patched.Encrypted {
		t.Error("an explicit empty passphrase did not clear the stored one")
	}
	if !patched.HasSecretKey {
		t.Error("clearing the passphrase also cleared the secret key")
	}
}

// A destination the file describes is not editable here, and a stored one may
// not take a name the file has: the file has the last word, and a page that
// let somebody write a row which would then be ignored would be lying.
func TestTheConfigurationFileHasTheLastWordOnADestinationsName(t *testing.T) {
	fake := backup.NewFakeS3("backups")
	t.Cleanup(fake.Close)
	h := newHarness(t, func(c *config.Config) {
		c.Backup.Remotes = []config.BackupRemote{{
			Name: "offsite", Endpoint: fake.Endpoint(), Bucket: fake.Bucket(),
			AccessKeyID: "AKIAEXAMPLE", SecretAccessKey: "secret",
		}}
		c.Normalize()
	})
	cookie := h.platform()

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/backups/remotes", cookie: cookie,
		body: map[string]any{
			"name": "offsite", "endpoint": fake.Endpoint(), "bucket": fake.Bucket(),
			"access_key_id": "a", "secret_access_key": "b",
		}})
	resp.mustStatus(t, http.StatusUnprocessableEntity, "add a destination the file already names")
	if !strings.Contains(string(resp.body), "zoomies.yaml") {
		t.Errorf("the refusal reads %s, which does not say where the other one is", string(resp.body))
	}

	// And editing the file's destination is refused with the same explanation
	// rather than a 404, which would read as "it is not there".
	resp = h.do(request{method: http.MethodPatch, path: "/api/v1/backups/remotes/offsite", cookie: cookie,
		body: map[string]any{"keep": 3}})
	resp.mustStatus(t, http.StatusConflict, "edit a destination the file describes")

	// The page says which is which.
	resp = h.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "list backups")
	var listed backupsResponse
	resp.into(t, &listed)
	if len(listed.Remotes) != 1 || listed.Remotes[0].Source != controller.RemoteSourceFile {
		t.Fatalf("the page shows %+v", listed.Remotes)
	}
}

// A destination that cannot work is refused with the reason under the field
// that is wrong, because the alternative is a form that saves and a bucket
// that never receives anything.
func TestADestinationThatCouldNotWorkIsRefusedByField(t *testing.T) {
	h := newHarness(t)
	cookie := h.platform()

	for _, tc := range []struct {
		name  string
		body  map[string]any
		field string
	}{
		{"no bucket", map[string]any{"name": "offsite", "endpoint": "https://s3.example.com", "secret_access_key": "s"}, "bucket"},
		{"an endpoint that is not a URL", map[string]any{"name": "offsite", "endpoint": "s3.example.com", "bucket": "b", "secret_access_key": "s"}, "endpoint"},
		{"no secret key", map[string]any{"name": "offsite", "endpoint": "https://s3.example.com", "bucket": "b"}, "secret_access_key"},
		{"a name that is not a name", map[string]any{"name": "Off Site!", "endpoint": "https://s3.example.com", "bucket": "b", "secret_access_key": "s"}, "name"},
		{"a name the API already uses", map[string]any{"name": "check", "endpoint": "https://s3.example.com", "bucket": "b", "secret_access_key": "s"}, "name"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			resp := h.do(request{method: http.MethodPost, path: "/api/v1/backups/remotes", cookie: cookie, body: tc.body})
			resp.mustStatus(t, http.StatusUnprocessableEntity, tc.name)
			if !strings.Contains(string(resp.body), `"`+tc.field+`"`) {
				t.Errorf("the refusal is %s, which does not name the %s field", string(resp.body), tc.field)
			}
		})
	}
}

// Removing a destination forgets where the copies are; it does not delete
// them. An operator who meant the other thing removes them from the listing,
// where each one is named.
func TestRemovingADestinationLeavesTheCopiesInTheBucket(t *testing.T) {
	fake := backup.NewFakeS3("backups")
	t.Cleanup(fake.Close)
	h := newHarness(t, allowPrivateEgress)
	cookie := h.platform()

	h.do(request{method: http.MethodPost, path: "/api/v1/backups/remotes", cookie: cookie,
		body: map[string]any{
			"name": "offsite", "endpoint": fake.Endpoint(), "bucket": fake.Bucket(),
			"access_key_id": "AKIAEXAMPLE", "secret_access_key": "secret",
		}}).mustStatus(t, http.StatusCreated, "add a destination")

	h.takeBackup(t, cookie)
	h.do(request{method: http.MethodPost, path: "/api/v1/backups/offsite", cookie: cookie}).
		mustStatus(t, http.StatusOK, "copy offsite")
	if fake.Count() != 1 {
		t.Fatalf("the bucket holds %d copies before the destination is removed", fake.Count())
	}

	h.do(request{method: http.MethodDelete, path: "/api/v1/backups/remotes/offsite", cookie: cookie}).
		mustStatus(t, http.StatusNoContent, "remove the destination")
	if fake.Count() != 1 {
		t.Errorf("removing the destination deleted %d copies from the bucket", 1-fake.Count())
	}

	resp := h.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "list backups")
	var listed backupsResponse
	resp.into(t, &listed)
	if len(listed.Remotes) != 0 {
		t.Errorf("the page still shows %+v", listed.Remotes)
	}
}

// "Backups are taken but never leave this host" is raised by the validator,
// which reads the configuration file and cannot see a destination stored in
// the database. Telling somebody to do a thing they have already done is how a
// page teaches them to stop reading it, so the settings API drops that finding
// once the fleet has a destination -- wherever it came from.
func TestTheNoRemoteFindingGoesAwayWhenADestinationIsAdded(t *testing.T) {
	fake := backup.NewFakeS3("backups")
	t.Cleanup(fake.Close)
	h := newHarness(t, allowPrivateEgress)
	cookie := h.platform()

	codes := func() []string {
		resp := h.do(request{method: http.MethodGet, path: "/api/v1/settings", cookie: cookie})
		resp.mustStatus(t, http.StatusOK, "read the settings")
		var out struct {
			Findings []struct {
				Code string `json:"code"`
			} `json:"findings"`
		}
		resp.into(t, &out)
		var found []string
		for _, f := range out.Findings {
			found = append(found, f.Code)
		}
		return found
	}

	if !slices.Contains(codes(), config.NoRemoteFinding) {
		t.Fatalf("a fleet whose backups never leave the host is not told: %v", codes())
	}

	h.do(request{method: http.MethodPost, path: "/api/v1/backups/remotes", cookie: cookie,
		body: map[string]any{
			"name": "offsite", "endpoint": fake.Endpoint(), "bucket": fake.Bucket(),
			"access_key_id": "AKIAEXAMPLE", "secret_access_key": "secret",
		}}).mustStatus(t, http.StatusCreated, "add a destination")

	if slices.Contains(codes(), config.NoRemoteFinding) {
		t.Errorf("the fleet added a destination and is still told its backups never leave the host: %v", codes())
	}

	// Switched off is not answered: a destination nothing is sent to is not a
	// destination.
	h.do(request{method: http.MethodPatch, path: "/api/v1/backups/remotes/offsite", cookie: cookie,
		body: map[string]any{"enabled": false}}).mustStatus(t, http.StatusOK, "switch it off")
	if !slices.Contains(codes(), config.NoRemoteFinding) {
		t.Errorf("a fleet whose only destination is switched off is told nothing: %v", codes())
	}
}

// allowPrivateEgress is what a harness needs to talk to a fake that httptest
// has bound to 127.0.0.1 -- the same switch an operator with a MinIO beside
// the controller sets, rather than a hole in the guard only tests can use.
func allowPrivateEgress(c *config.Config) { c.Security.AllowPrivateEgress = true }

// A destination on this machine or its network is somewhere the controller
// would send the whole fleet's backup and its access key on an
// administrator's say-so, so it is refused by field, naming the switch, and
// admitted once the platform has set it.
func TestADestinationOnAPrivateAddressIsRefusedUntilThePlatformAllowsIt(t *testing.T) {
	for _, tc := range []struct {
		name  string
		allow bool
		want  int
	}{
		{"refused by default", false, http.StatusUnprocessableEntity},
		{"admitted by security.allow_private_egress", true, http.StatusCreated},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t, func(c *config.Config) { c.Security.AllowPrivateEgress = tc.allow })
			h.installation()
			cookie := h.platform()
			resp := h.do(request{method: http.MethodPost, path: "/api/v1/backups/remotes", cookie: cookie, body: map[string]any{
				"name": "lan", "endpoint": "http://169.254.169.254", "bucket": "b",
				"access_key_id": "AKIAEXAMPLE", "secret_access_key": "secret",
			}})
			resp.mustStatus(t, tc.want, "create a destination at the metadata address")
			if tc.allow {
				return
			}
			if body := string(resp.body); !strings.Contains(body, `"field":"endpoint"`) || !strings.Contains(body, "security.allow_private_egress") {
				t.Errorf("the refusal does not name the field and the setting that would allow it: %s", body)
			}
		})
	}
}

package api

import (
	"net/http"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/backup"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/store"
)

// The Backups tab's offsite half. What these protect is the sequence an
// operator actually performs on the day the local copies are gone: see which
// destinations exist, prove one can be reached, look at what it holds, and
// bring a copy back -- landing as an ordinary backup, so that the restore is
// still the staged, confirmed one rather than something that happened inside a
// download.

// withRemote gives the harness a fleet whose backups go to a fake bucket.
func withRemote(t *testing.T) (*harness, *backup.FakeS3) {
	t.Helper()
	fake := backup.NewFakeS3("backups")
	t.Cleanup(fake.Close)
	h := newHarness(t, func(c *config.Config) {
		c.Backup.Remotes = []config.BackupRemote{{
			Name: "offsite", Endpoint: fake.Endpoint(), Bucket: fake.Bucket(), Prefix: "fleet",
			AccessKeyID: "AKIAEXAMPLE", SecretAccessKey: "secret",
		}}
		c.Normalize()
	})
	return h, fake
}

func TestABackupIsSentOffsiteListedThereAndBroughtBack(t *testing.T) {
	h, fake := withRemote(t)
	h.installation()
	cookie := h.platform()
	taken := h.takeBackup(t, cookie)

	// The page says where copies go before any has gone.
	resp := h.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "list backups")
	var listed backupsResponse
	resp.into(t, &listed)
	if len(listed.Remotes) != 1 || listed.Remotes[0].Name != "offsite" || listed.Remotes[0].Encrypted {
		t.Fatalf("the page shows %+v as its destinations", listed.Remotes)
	}

	resp = h.do(request{method: http.MethodPost, path: "/api/v1/backups/remotes/offsite/check", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "check the remote")
	var check remoteCheckResponse
	resp.into(t, &check)
	if !check.OK || check.Where != "backups/fleet" {
		t.Errorf("the check says %+v about a bucket that answers", check)
	}

	resp = h.do(request{method: http.MethodPost, path: "/api/v1/backups/offsite", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "copy the backups offsite")
	var shipped shipResponse
	resp.into(t, &shipped)
	if shipped.Error != "" || len(shipped.Sent) != 1 || shipped.Sent[0].ID != taken.ID {
		t.Fatalf("the pass sent %+v (%s)", shipped.Sent, shipped.Error)
	}

	resp = h.do(request{method: http.MethodGet, path: "/api/v1/backups/remotes/offsite/copies", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "list what the remote holds")
	var copies remoteCopiesResponse
	resp.into(t, &copies)
	if len(copies.Items) != 1 || copies.Items[0].ID != taken.ID || copies.Bytes == 0 {
		t.Fatalf("the remote lists %+v", copies)
	}
	if copies.Remote.Name != "offsite" {
		t.Errorf("the listing does not say which remote it came from: %+v", copies.Remote)
	}

	// The local copy goes, as it would if the disk had. What comes back is an
	// ordinary backup: verified, listed, and marked as having come from
	// offsite so that retention leaves it alone.
	if err := backup.Delete(h.ctrl.BackupDir(), taken.ID); err != nil {
		t.Fatalf("Delete: %v", err)
	}
	resp = h.do(request{
		method: http.MethodPost,
		path:   "/api/v1/backups/remotes/offsite/copies/" + taken.ID + "/fetch",
		cookie: cookie,
	})
	resp.mustStatus(t, http.StatusCreated, "bring the copy back")
	var back backupView
	resp.into(t, &back)
	if back.ID != taken.ID || back.Source != backup.SourceFetched || !back.Restorable {
		t.Fatalf("what came back reads %+v", back)
	}

	// And removing the offsite copy is a write, audited like any other.
	resp = h.do(request{
		method: http.MethodDelete,
		path:   "/api/v1/backups/remotes/offsite/copies/" + taken.ID,
		cookie: cookie,
	})
	resp.mustStatus(t, http.StatusNoContent, "remove the offsite copy")
	if fake.Count() != 0 {
		t.Errorf("the bucket still holds %d objects", fake.Count())
	}
}

// A bucket that refuses is not this API failing. The check reports it as a
// result, and the listing as a refusal the operator can act on -- both
// carrying the service's own words, because "500" is not a fix.
func TestARemoteThatRefusesIsReportedRatherThanHidden(t *testing.T) {
	h, fake := withRemote(t)
	cookie := h.platform()
	fake.BreakWith(http.StatusForbidden, "SignatureDoesNotMatch", "no")

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/backups/remotes/offsite/check", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "check a remote that refuses")
	var check remoteCheckResponse
	resp.into(t, &check)
	if check.OK || check.Error == "" {
		t.Fatalf("the check says %+v about a bucket that refused it", check)
	}

	resp = h.do(request{method: http.MethodGet, path: "/api/v1/backups/remotes/offsite/copies", cookie: cookie})
	resp.mustStatus(t, http.StatusUnprocessableEntity, "list a remote that refuses")
}

// A name that is not a remote is a 404 rather than a 500, and a fleet with no
// remotes configured says so in its listing rather than pretending.
func TestAnUnknownRemoteIsNotFoundAndNoRemotesIsAnEmptyList(t *testing.T) {
	h, _ := withRemote(t)
	cookie := h.platform()
	for _, path := range []string{
		"/api/v1/backups/remotes/nowhere/copies",
		"/api/v1/backups/remotes/nowhere/check",
	} {
		method := http.MethodGet
		if path == "/api/v1/backups/remotes/nowhere/check" {
			method = http.MethodPost
		}
		resp := h.do(request{method: method, path: path, cookie: cookie})
		resp.mustStatus(t, http.StatusNotFound, "a remote that is not configured")
	}

	plain := newHarness(t)
	resp := plain.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: plain.platform()})
	resp.mustStatus(t, http.StatusOK, "list backups with no remotes")
	var listed backupsResponse
	resp.into(t, &listed)
	if len(listed.Remotes) != 0 {
		t.Errorf("a fleet with no remotes reports %+v", listed.Remotes)
	}
}

// Retention on demand, which exists because lowering the number of copies a
// fleet keeps otherwise does nothing at all until the next backup -- and on a
// fleet with the schedule off, nothing ever. The route has to reach both
// halves, and say what it removed from each: the local ceiling and the
// bucket's are separate numbers and a single total would read as a fault.
func TestRetentionIsAppliedOnDemandToBothHalves(t *testing.T) {
	h, fake := withRemote(t)
	h.installation()
	cookie := h.platform()

	h.ctrl.UpdateConfig(func(c *config.Config) { c.Backup.Keep = 0 })
	var taken []string
	for range 3 {
		taken = append(taken, h.takeBackup(t, cookie).ID)
		// The directory name carries the clock's second.
		time.Sleep(1100 * time.Millisecond)
	}
	resp := h.do(request{method: http.MethodPost, path: "/api/v1/backups/offsite", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "copy the backups offsite")
	if got := fake.Count(); got != 3 {
		t.Fatalf("setting up: the bucket holds %d copies", got)
	}

	h.ctrl.UpdateConfig(func(c *config.Config) {
		c.Backup.Keep = 1
		c.Backup.Remotes[0].Keep = 2
	})
	resp = h.do(request{method: http.MethodPost, path: "/api/v1/backups/prune", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "apply retention")
	var report controller.BackupPruning
	resp.into(t, &report)

	if report.Keep != 1 || len(report.Removed) != 2 || report.Error != "" {
		t.Errorf("the local half of the report reads %+v", report)
	}
	if len(report.Remotes) != 1 || report.Remotes[0].Keep != 2 || len(report.Remotes[0].Removed) != 1 {
		t.Fatalf("the offsite half of the report reads %+v", report.Remotes)
	}
	if got := fake.Count(); got != 2 {
		t.Errorf("the bucket holds %d copies with keep: 2", got)
	}

	// And the page agrees: one backup left here, the newest.
	resp = h.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "list backups")
	var listed backupsResponse
	resp.into(t, &listed)
	if len(listed.Items) != 1 || listed.Items[0].ID != taken[len(taken)-1] {
		t.Errorf("the page lists %d backups after retention was applied", len(listed.Items))
	}
}

// Pruning deletes copies of the whole fleet, so it is a write rather than
// something a read-only token can set off.
func TestRetentionOnDemandNeedsTheAdministratorRole(t *testing.T) {
	h, _ := withRemote(t)
	h.installation()
	u, _ := h.user("viewer", store.RoleViewer)
	resp := h.do(request{method: http.MethodPost, path: "/api/v1/backups/prune", cookie: h.session(u)})
	resp.mustStatus(t, http.StatusForbidden, "prune as a viewer")
}

package api

import (
	"bytes"
	"context"
	"encoding/json"
	"io"
	"mime/multipart"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/backup"
	"github.com/eyupio/zoomies/internal/store"
)

// The Backups tab is the one place in the product where a copy of the whole
// database leaves the machine and where one comes back to replace the fleet,
// so what these tests protect is the sequence: a backup taken from the page is
// the same backup the command line restores, a download round-trips through
// an upload, and a restore is staged with every check made now and nothing
// moved until the restart.

// admin is a signed-in administrator's cookie.
// platform is a session for the role the backup routes now need. A backup is
// the whole database under the key this host holds, so it belongs to whoever
// runs the process rather than to the fleet's administrator.
func (h *harness) platform() string {
	h.t.Helper()
	u, _ := h.user("platform", store.RolePlatform)
	return h.session(u)
}

// takeBackup presses the button and returns what the page would show.
func (h *harness) takeBackup(t *testing.T, cookie string) backupView {
	t.Helper()
	resp := h.do(request{method: http.MethodPost, path: "/api/v1/backups", cookie: cookie})
	resp.mustStatus(t, http.StatusCreated, "take a backup")
	var v backupView
	resp.into(t, &v)
	return v
}

func TestABackupTakenFromThePageIsListedWithWhatARestoreNeedsToKnow(t *testing.T) {
	h := newHarness(t)
	h.installation()
	cookie := h.platform()

	taken := h.takeBackup(t, cookie)
	if taken.Source != backup.SourceManual || taken.TakenBy != "platform" || taken.Bytes == 0 {
		t.Errorf("taken = %+v", taken)
	}
	if taken.KeyMatches == nil || !*taken.KeyMatches || taken.Secrets != 1 || !taken.Restorable {
		t.Errorf("the row does not say the key matches and the backup is restorable: %+v", taken)
	}

	resp := h.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "list backups")
	var listed backupsResponse
	resp.into(t, &listed)
	if len(listed.Items) != 1 || listed.Items[0].ID != taken.ID {
		t.Fatalf("listed = %+v", listed.Items)
	}
	if listed.Directory != h.ctrl.BackupDir() || listed.DatabaseBytes == 0 && listed.Directory == "" {
		t.Errorf("the page does not know where backups go: %+v", listed)
	}
	if !listed.Schedule.Enabled || listed.Schedule.Interval != "24h" || listed.Schedule.NextDueAt == nil {
		t.Errorf("schedule = %+v", listed.Schedule)
	}
	if listed.StagedRestore != nil || listed.LastRestore != nil || listed.Restarting {
		t.Errorf("a fresh instance claims a restore is in progress: %+v", listed)
	}

	// The manifest on disk is the one the command line reads.
	m, err := backup.ReadManifest(filepath.Join(listed.Directory, taken.ID))
	if err != nil || m.Source != backup.SourceManual {
		t.Errorf("the backup on disk is not what the page reported: %+v, %v", m, err)
	}

	// And the whole page's shape is what the contract promises.
	doc := loadSpec(t)
	assertShape(t, doc, "Backups", resp.body)
	one := h.do(request{method: http.MethodGet, path: "/api/v1/backups/" + taken.ID, cookie: cookie})
	one.mustStatus(t, http.StatusOK, "get backup")
	assertShape(t, doc, "Backup", one.body)
}

// A download is the backup leaving the machine and an upload is it coming
// back, so the two have to agree exactly: plain, and encrypted with a
// passphrase that is then required.
func TestADownloadRoundTripsThroughAnUploadPlainAndEncrypted(t *testing.T) {
	h := newHarness(t)
	h.installation()
	cookie := h.platform()
	taken := h.takeBackup(t, cookie)

	plain := h.do(request{method: http.MethodGet, path: "/api/v1/backups/" + taken.ID + "/download", cookie: cookie})
	plain.mustStatus(t, http.StatusOK, "download")
	if cd := plain.header.Get("Content-Disposition"); !strings.Contains(cd, taken.ID+".tar.gz") {
		t.Errorf("Content-Disposition = %q", cd)
	}
	if !bytes.HasPrefix(plain.body, []byte("\x1f\x8b")) {
		t.Fatal("the download is not a gzipped archive")
	}

	enc := h.do(request{method: http.MethodPost, path: "/api/v1/backups/" + taken.ID + "/download", cookie: cookie,
		body: map[string]any{"passphrase": "correct horse battery staple"}})
	enc.mustStatus(t, http.StatusOK, "encrypted download")
	if cd := enc.header.Get("Content-Disposition"); !strings.Contains(cd, ".tar.gz.enc") {
		t.Errorf("Content-Disposition = %q", cd)
	}
	if bytes.HasPrefix(enc.body, []byte("\x1f\x8b")) || bytes.Contains(enc.body, []byte("manifest.json")) {
		t.Fatal("the encrypted download is readable")
	}
	short := h.do(request{method: http.MethodPost, path: "/api/v1/backups/" + taken.ID + "/download", cookie: cookie,
		body: map[string]any{"passphrase": "1234"}})
	short.mustStatus(t, http.StatusUnprocessableEntity, "a four-character passphrase")

	// The original gone, both come back under the original's name.
	del := h.do(request{method: http.MethodDelete, path: "/api/v1/backups/" + taken.ID, cookie: cookie})
	del.mustStatus(t, http.StatusNoContent, "delete")

	up := h.upload(t, cookie, "backup.tar.gz", plain.body, "")
	up.mustStatus(t, http.StatusCreated, "plain upload")
	var uploaded backupView
	up.into(t, &uploaded)
	if uploaded.ID != taken.ID || uploaded.Source != backup.SourceUploaded || uploaded.TakenBy != "platform" {
		t.Errorf("uploaded = %+v", uploaded)
	}

	wrong := h.upload(t, cookie, "backup.tar.gz.enc", enc.body, "not the passphrase")
	wrong.mustStatus(t, http.StatusUnprocessableEntity, "encrypted upload with the wrong passphrase")
	if msg := string(wrong.body); !strings.Contains(msg, "passphrase") {
		t.Errorf("the refusal does not name the passphrase: %s", msg)
	}
	missing := h.upload(t, cookie, "backup.tar.gz.enc", enc.body, "")
	missing.mustStatus(t, http.StatusUnprocessableEntity, "encrypted upload with no passphrase")

	right := h.upload(t, cookie, "backup.tar.gz.enc", enc.body, "correct horse battery staple")
	right.mustStatus(t, http.StatusCreated, "encrypted upload")
	var second backupView
	right.into(t, &second)
	if second.ID == uploaded.ID || !strings.HasPrefix(second.ID, taken.ID) {
		t.Errorf("a second upload of the same backup landed as %s", second.ID)
	}

	// The uploads are audited as what they are, and so was the download.
	audit := h.do(request{method: http.MethodGet, path: "/api/v1/audit?action=backup.download&action=backup.upload", cookie: cookie})
	audit.mustStatus(t, http.StatusOK, "audit")
	var rows struct {
		Total int `json:"total"`
	}
	audit.into(t, &rows)
	if rows.Total != 4 {
		t.Errorf("audit rows = %d, want two downloads and two uploads", rows.Total)
	}
}

// Garbage in is refused as garbage, and nothing lands in the directory.
func TestAnUploadThatIsNotABackupIsRefused(t *testing.T) {
	h := newHarness(t)
	cookie := h.platform()
	resp := h.upload(t, cookie, "notes.txt", []byte("not an archive"), "")
	resp.mustStatus(t, http.StatusUnprocessableEntity, "upload of a text file")
	if !strings.Contains(string(resp.body), "gzipped") {
		t.Errorf("the refusal does not say what was wrong: %s", resp.body)
	}
	if entries, _ := os.ReadDir(h.ctrl.BackupDir()); len(entries) != 0 {
		t.Errorf("something was left behind: %v", entries)
	}
	raw := h.do(request{method: http.MethodPost, path: "/api/v1/backups/upload", cookie: cookie,
		rawBody: "raw bytes", headers: map[string]string{"Content-Type": "application/octet-stream"}})
	raw.mustStatus(t, http.StatusBadRequest, "a non-multipart upload")
}

// upload posts a multipart form the way the page does.
func (h *harness) upload(t *testing.T, cookie, filename string, archive []byte, passphrase string) *response {
	t.Helper()
	var body bytes.Buffer
	mw := multipart.NewWriter(&body)
	if passphrase != "" {
		if err := mw.WriteField("passphrase", passphrase); err != nil {
			t.Fatal(err)
		}
	}
	fw, err := mw.CreateFormFile("file", filename)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := fw.Write(archive); err != nil {
		t.Fatal(err)
	}
	if err := mw.Close(); err != nil {
		t.Fatal(err)
	}
	return h.do(request{method: http.MethodPost, path: "/api/v1/backups/upload", cookie: cookie,
		rawBody: body.String(), headers: map[string]string{"Content-Type": mw.FormDataContentType()}})
}

// Verify re-reads the file. A backup somebody has altered has to come back as
// not OK with a sentence, not as a 500.
func TestVerifyNoticesAnAlteredBackup(t *testing.T) {
	h := newHarness(t)
	cookie := h.platform()
	taken := h.takeBackup(t, cookie)

	ok := h.do(request{method: http.MethodPost, path: "/api/v1/backups/" + taken.ID + "/verify", cookie: cookie})
	ok.mustStatus(t, http.StatusOK, "verify")
	var v backup.Verification
	ok.into(t, &v)
	if !v.OK || !v.DigestMatches {
		t.Errorf("a fresh backup does not verify: %+v", v)
	}
	assertShape(t, loadSpec(t), "BackupVerification", ok.body)

	db := filepath.Join(h.ctrl.BackupDir(), taken.ID, backup.DBName)
	f, err := os.OpenFile(db, os.O_WRONLY|os.O_APPEND, 0)
	if err != nil {
		t.Fatal(err)
	}
	_, _ = f.Write([]byte("altered"))
	f.Close()
	bad := h.do(request{method: http.MethodPost, path: "/api/v1/backups/" + taken.ID + "/verify", cookie: cookie})
	bad.mustStatus(t, http.StatusOK, "verify an altered backup")
	bad.into(t, &v)
	if v.OK || v.DigestMatches || len(v.Problems) == 0 {
		t.Errorf("an altered backup verified: %+v", v)
	}
}

// Staging is the whole of what the page can do about a restore, and it is
// checked now: the wrong key is refused with the sentence, a good backup is
// written down for the next start, the page says so, and cancelling forgets it.
func TestARestoreIsStagedWithEveryCheckMadeNowAndNothingMoved(t *testing.T) {
	h := newHarness(t)
	h.installation()
	cookie := h.platform()
	taken := h.takeBackup(t, cookie)

	// A backup that says it was sealed with another key.
	other := h.takeBackup(t, cookie)
	manifestPath := filepath.Join(h.ctrl.BackupDir(), other.ID, backup.ManifestName)
	raw, _ := os.ReadFile(manifestPath)
	var m map[string]any
	_ = json.Unmarshal(raw, &m)
	m["key"] = map[string]any{"fingerprint": "deadbeefcafe", "from": "elsewhere"}
	raw, _ = json.Marshal(m)
	_ = os.WriteFile(manifestPath, raw, 0o600)

	listed := h.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: cookie})
	var page backupsResponse
	listed.into(t, &page)
	for _, item := range page.Items {
		if item.ID == other.ID && (item.Restorable || !strings.Contains(item.RestoreProblem, "deadbeefcafe")) {
			t.Errorf("the list does not warn about the wrong key: %+v", item)
		}
	}
	refused := h.do(request{method: http.MethodPost, path: "/api/v1/backups/" + other.ID + "/restore", cookie: cookie})
	refused.mustStatus(t, http.StatusUnprocessableEntity, "restore with the wrong key")
	if !strings.Contains(refused.errorMessage(t)+string(refused.body), "not the one that sealed this backup") {
		t.Errorf("the refusal does not say why: %s", refused.body)
	}
	// Nothing to apply yet, and a restart with nothing to apply is refused.
	nothing := h.do(request{method: http.MethodPost, path: "/api/v1/backups/restore/apply", cookie: cookie})
	nothing.mustStatus(t, http.StatusConflict, "apply with nothing staged")

	staged := h.do(request{method: http.MethodPost, path: "/api/v1/backups/" + taken.ID + "/restore", cookie: cookie,
		body: map[string]any{"revoke_api_tokens": true}})
	staged.mustStatus(t, http.StatusAccepted, "stage a restore")
	assertShape(t, loadSpec(t), "StagedRestore", staged.body)
	var s backup.Staged
	staged.into(t, &s)
	if s.BackupID != taken.ID || s.RequestedBy != "platform" || !s.RevokeAPITokens || s.ResetAgentTokens {
		t.Errorf("staged = %+v", s)
	}
	// The live database is untouched: the fleet is still running on it.
	if f := h.ctrl.Fenced(); f.Fenced {
		t.Error("staging fenced the running fleet")
	}
	// The staged backup cannot be deleted from under the restart.
	held := h.do(request{method: http.MethodDelete, path: "/api/v1/backups/" + taken.ID, cookie: cookie})
	held.mustStatus(t, http.StatusConflict, "delete a staged backup")
	// A second backup cannot be staged over it.
	over := h.do(request{method: http.MethodPost, path: "/api/v1/backups/" + other.ID + "/restore", cookie: cookie})
	over.mustStatus(t, http.StatusConflict, "stage a second restore")

	listed = h.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: cookie})
	listed.into(t, &page)
	if page.StagedRestore == nil || page.StagedRestore.BackupID != taken.ID {
		t.Errorf("the page does not show the staged restore: %+v", page.StagedRestore)
	}
	problems := h.do(request{method: http.MethodGet, path: "/api/v1/problems", cookie: cookie})
	if !strings.Contains(string(problems.body), "backup.restore_staged") {
		t.Error("the staged restore is not in the problems drawer")
	}

	cancel := h.do(request{method: http.MethodDelete, path: "/api/v1/backups/restore", cookie: cookie})
	cancel.mustStatus(t, http.StatusNoContent, "cancel")
	if staged, _ := backup.LoadStaged(h.ctrl.DatabasePath()); staged != nil {
		t.Error("the staged restore survived being cancelled")
	}
	again := h.do(request{method: http.MethodDelete, path: "/api/v1/backups/restore", cookie: cookie})
	again.mustStatus(t, http.StatusNoContent, "cancel when nothing is staged")
}

// Applying is the one act that stops the process. It answers before it does,
// and the command that runs the controller sees the request.
func TestApplyingAStagedRestoreAsksForARestart(t *testing.T) {
	h := newHarness(t)
	cookie := h.platform()
	taken := h.takeBackup(t, cookie)
	h.do(request{method: http.MethodPost, path: "/api/v1/backups/" + taken.ID + "/restore", cookie: cookie}).
		mustStatus(t, http.StatusAccepted, "stage")

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/backups/restore/apply", cookie: cookie})
	resp.mustStatus(t, http.StatusAccepted, "apply")
	assertShape(t, loadSpec(t), "Restarting", resp.body)
	select {
	case <-h.ctrl.RestartRequested():
	default:
		t.Fatal("the controller was not asked to restart")
	}
	listed := h.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: cookie})
	var page backupsResponse
	listed.into(t, &page)
	if !page.Restarting {
		t.Error("the page does not say the controller is restarting")
	}

	// The next start applies it, and the outcome is what the page shows.
	outcome, err := backup.ApplyStaged(context.Background(), h.cfg, nil)
	if err != nil || outcome == nil || !outcome.OK {
		t.Fatalf("ApplyStaged = %+v, %v", outcome, err)
	}
	listed = h.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: cookie})
	listed.into(t, &page)
	if page.LastRestore == nil || !page.LastRestore.OK || page.LastRestore.BackupID != taken.ID {
		t.Errorf("last restore = %+v", page.LastRestore)
	}
	dismiss := h.do(request{method: http.MethodDelete, path: "/api/v1/backups/restore/outcome", cookie: cookie})
	dismiss.mustStatus(t, http.StatusNoContent, "dismiss")
	listed = h.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: cookie})
	listed.into(t, &page)
	if page.LastRestore != nil {
		t.Error("the outcome survived being dismissed")
	}
}

// The store's pre-migration copies are backups too, and they have no manifest:
// they are listed as what they are and can be downloaded, with the caveat
// that nothing about them can be checked before restoring.
func TestPreMigrationCopiesAreListedBesideTheBackups(t *testing.T) {
	h := newHarness(t)
	cookie := h.platform()
	dir := filepath.Join(backup.PreMigrationDir(h.ctrl.DatabasePath()), backup.DirPrefix+"20260101-000000")
	if err := os.MkdirAll(dir, 0o700); err != nil {
		t.Fatal(err)
	}
	if err := h.st.Backup(h.ctx, filepath.Join(dir, backup.DBName)); err != nil {
		t.Fatal(err)
	}
	listed := h.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: cookie})
	var page backupsResponse
	listed.into(t, &page)
	if len(page.Items) != 1 || page.Items[0].Location != locationPreMigration || page.Items[0].Source != backup.SourcePreMigration {
		t.Fatalf("items = %+v", page.Items)
	}
	if !page.Items[0].Restorable || page.Items[0].RestoreProblem == "" {
		t.Errorf("a copy with no manifest should be restorable with a caveat: %+v", page.Items[0])
	}
	dl := h.do(request{method: http.MethodGet, path: "/api/v1/backups/" + page.Items[0].ID + "/download", cookie: cookie})
	dl.mustStatus(t, http.StatusOK, "download a pre-migration copy")
	if _, err := io.ReadAll(bytes.NewReader(dl.body)); err != nil {
		t.Fatal(err)
	}
}

// The id is a path component. One that is not a backup id is refused before
// it touches the filesystem, and one that names nothing is a 404.
func TestBackupIDsThatAreNotBackupIDsAreRefused(t *testing.T) {
	h := newHarness(t)
	cookie := h.platform()
	for _, bad := range []string{"..", "zoomies.db", "zoomies-1"} {
		resp := h.do(request{method: http.MethodGet, path: "/api/v1/backups/" + bad, cookie: cookie})
		if resp.status != http.StatusBadRequest && resp.status != http.StatusNotFound {
			t.Errorf("GET /backups/%s = %d", bad, resp.status)
		}
	}
	gone := h.do(request{method: http.MethodGet, path: "/api/v1/backups/zoomies-19990101-000000", cookie: cookie})
	gone.mustStatus(t, http.StatusNotFound, "a backup that is not there")
}

