import (
	"context"
	"errors"
	"net/http"
	"strconv"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/aicontext"
	"github.com/eyupio/zoomies/internal/auth"
)

func (s *Server) contextSourceAccess(w http.ResponseWriter, r *http.Request, id string) bool {
	actor, err := s.resolveIdentity(r)
	if err != nil {
		if errors.Is(err, auth.ErrAuthBackend) {
			s.internal(w, r, "checking source credentials", err)
			return false
		}
		unauthorized(w, "source credentials are no longer valid")
		return false
	}
	if !auth.Allowed(actor, auth.ActionContextRead) {
		forbidden(w, "source credentials no longer allow context.read")
		return false
	}
	allowed, err := s.auth.ContextAccess(r.Context(), actor, id)
	if err != nil {
		s.internal(w, r, "checking source access", err)
		return false
	}
	if !allowed {
		if actor.UserID == "" {
			forbidden(w, "source access requires an owned account")
			return false
		}
		notFound(w, "source repository is unavailable to this credential")
		return false
	}
	return true
}

func (s *Server) handleAIContextSource(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Cache-Control", "no-store")
	id := chiURLParam(r, "id")
	if !s.contextSourceAccess(w, r, id) {
		return
	}
	q := r.URL.Query()
	number := func(name string, fallback, min, max int) (int, bool) {
		text := q.Get(name)
		if text == "" {
			return fallback, true
		}
		n, err := strconv.Atoi(text)
		if err != nil || n < min || n > max {
			unprocessable(w, "choose a valid "+name, nil)
			return 0, false
		}
		return n, true
	}
	budget, ok := number("budget", 8000, 1024, aicontext.MaxResponseBytes)
	if !ok {
		return
	}
	offset, ok := number("offset", 0, 0, 1000000)
	if !ok {
		return
	}
	maxLimit := 100
	if strings.HasSuffix(r.URL.Path, "/search") {
		maxLimit = 12
	}
	limit, ok := number("limit", 12, 1, maxLimit)
	if !ok {
		return
	}
	if offset > 0 && q.Get("commit") == "" {
		unprocessable(w, "pin the returned commit when continuing a page", nil)
		return
	}
	ctx, cancel := context.WithTimeout(r.Context(), 45*time.Second)
	defer cancel()
	snapshot, fresh, err := s.ctrl.VerifiedAIContextSnapshot(ctx, id)
	// Revocation during network verification must close the response as well.
	if !s.contextSourceAccess(w, r, id) {
		return
	}
	if err != nil {
		conflict(w, "current source could not be verified; ask an administrator to recheck AI Context")
		return
	}
	if expected := q.Get("commit"); expected != "" && expected != snapshot.Manifest.SourceCommit {
		conflict(w, "source changed; restart retrieval using the current commit")
		return
	}
	var body []byte
	switch r.URL.Path[strings.LastIndex(r.URL.Path, "/")+1:] {
	case "overview":
		body, err = snapshot.FilePage(fresh.Digest, offset, limit, budget)
	case "read":
		body, err = snapshot.ReadPage(fresh.Digest, []string{q.Get("path")}, offset, budget)
	case "pack":
		body, err = snapshot.ReadPage(fresh.Digest, q["path"], offset, budget)
	case "search":
		body, err = snapshot.SearchResult(fresh.Digest, q.Get("query"), q.Get("prefix"), offset, limit, budget)
	default:
		notFound(w, "source operation")
		return
	}
	if err != nil {
		unprocessable(w, err.Error(), nil)
		return
	}
	if !s.contextSourceAccess(w, r, id) {
		return
	}
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(body)
}

package api

import (
	"context"
	"errors"
	"io"
	"net/http"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/aicontext"
	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

// handleAIContextUpload receives a Zoomies-only snapshot from the managed
// workflow. It has no session and no API token: the only credential is the
// run's GitHub Actions OIDC token, minted for this controller's upload address,
// which the controller checks before it reads anything else the request says.
// It is mounted outside the API's body limit because a snapshot can be up to
// aicontext.MaxSnapshotBytes; this handler bounds the body itself.
func (s *Server) handleAIContextUpload(w http.ResponseWriter, r *http.Request) {
	audience := aicontext.UploadURLFor(s.cfg().Server.ExternalURL)
	if audience == "" {
		notFound(w, "this controller accepts Zoomies-only uploads only when server.external_url is an https address GitHub's runners can reach")
		return
	}
	raw, ok := strings.CutPrefix(r.Header.Get("Authorization"), "Bearer ")
	if !ok || raw == "" {
		unauthorized(w, "send the workflow run's GitHub Actions OIDC token, minted for this upload address, as a bearer token")
		return
	}
	// The token first: nobody without one gets the controller to buffer a body.
	if err := s.ctrl.CheckAIContextUploadToken(r.Context(), raw, audience); err != nil {
		if errors.Is(err, github.ErrActionsKeysUnavailable) {
			actionsKeysUnavailable(w, err)
			return
		}
		if errors.Is(err, github.ErrActionsToken) {
			unauthorized(w, "the GitHub Actions OIDC token is not valid for this controller: check that the workflow requests it for this upload address and that it has not expired")
			return
		}
		s.fail(w, r, "verifying the upload's GitHub Actions token", err)
		return
	}
	body, err := io.ReadAll(io.LimitReader(r.Body, aicontext.MaxSnapshotBytes+1))
	if err != nil {
		badRequest(w, "the upload body could not be read")
		return
	}
	if len(body) > aicontext.MaxSnapshotBytes {
		payloadTooLarge(w, "the snapshot is larger than 32 MiB; add exclusions to the repository's AI Context configuration")
		return
	}
	ctx, cancel := context.WithTimeout(r.Context(), 2*time.Minute)
	defer cancel()
	out, err := s.ctrl.IngestAIContextUpload(ctx, raw, audience, body)
	switch {
	case err == nil:
	case errors.Is(err, github.ErrActionsKeysUnavailable):
		actionsKeysUnavailable(w, err)
		return
	case errors.Is(err, github.ErrActionsToken):
		unauthorized(w, "the GitHub Actions OIDC token is not valid for this controller: check that the workflow requests it for this upload address and that it has not expired")
		return
	case errors.Is(err, store.ErrNotFound):
		notFound(w, "no repository on this controller is set up for Zoomies-only output with this GitHub repository ID")
		return
	case errors.Is(err, controller.ErrAIContextUploadSuperseded):
		conflict(w, err.Error())
		return
	case errors.Is(err, controller.ErrAIContextUploadRefused):
		forbidden(w, err.Error())
		return
	default:
		s.fail(w, r, "verifying the uploaded AI context", err)
		return
	}
	var commit, snapshot string
	if out.Freshness != nil {
		commit, snapshot = out.Freshness.PublishedCommit, out.Freshness.Digest
	}
	s.auth.Auditor().Act(r.Context(), &auth.Identity{Kind: auth.KindSystem, Name: "github-actions"}, "context.upload", "ai_context", out.ID,
		map[string]any{"commit": commit, "snapshot_id": snapshot})
	writeJSON(w, http.StatusAccepted, map[string]any{"repository_id": out.ID, "commit": commit, "snapshot_id": snapshot})
}

// actionsKeysUnavailable is a 503 rather than a 401: the token was not judged,
// and the run's log should send the operator to this controller's network.
func actionsKeysUnavailable(w http.ResponseWriter, err error) {
	host := "token.actions.githubusercontent.com"
	var keys *github.ActionsKeysError
	if errors.As(err, &keys) {
		host = keys.Host
	}
	writeError(w, http.StatusServiceUnavailable, errorEnvelope{Error: errorBody{
		Code:    codeInternal,
		Message: "this controller could not fetch GitHub's Actions signing keys from " + host + ", so the upload's token could not be checked; allow outbound https to that host and re-run the workflow",
	}})
}

package api

import (
	"errors"
	"fmt"
	"net/http"
	"time"

	"github.com/eyupio/zoomies/internal/analysis"
	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/store"
)

// maxReleaseName bounds a and b. Neither internal/version nor the jobs'
// controller_version column bounds a release's name, so this is the bound the
// installer holds a binary's reported version to, which is a few characters
// for any real build. A longer name names no release this fleet stamped, and
// would be carried into every sentence and label of the answer.
const maxReleaseName = 128

// defaultAnalysisSpan is the period an analysis reads when the caller names
// none: a day is what "why was it slow today" means, and short enough that the
// per-minute reads behind a finding stay small.
const defaultAnalysisSpan = 24 * time.Hour

// statsWindowFits refuses a period the job statistics and the analyses cannot
// read: one that does not end after it starts, and one longer than
// limits.job_stats_window, which bounds both. what is the reader and its verb
// ("job statistics cover"), so each says the one sentence in its own words.
func (s *Server) statsWindowFits(w http.ResponseWriter, since, until time.Time, what string) bool {
	if !since.Before(until) {
		badRequestField(w, "since", "since must be before until")
		return false
	}
	if span, limit := until.Sub(since), s.cfg().Limits.JobStatsSpan(); span > limit {
		badRequestField(w, "since", controller.SpanRefusal(span, limit, what))
		return false
	}
	return true
}

// analysisWindow is the period an analysis route reads: until defaults to now
// and since to a day before it, never further back than the limit allows, so a
// request that named nothing is never refused for a period it did not ask for.
//
// An until past now ends now here as it does in the controller, and before the
// default and the span are worked out from it: otherwise an until two days out
// would default since into the future and be refused on a field the caller
// never sent, and a since at the limit would be refused as too long for hours
// nobody reads.
func (s *Server) analysisWindow(w http.ResponseWriter, r *http.Request) (controller.AnalysisWindow, bool) {
	since, err := queryTime(r, "since")
	if err != nil {
		badRequestField(w, "since", err.Error())
		return controller.AnalysisWindow{}, false
	}
	until, err := queryTime(r, "until")
	if err != nil {
		badRequestField(w, "until", err.Error())
		return controller.AnalysisWindow{}, false
	}
	now := s.ctrl.Now()
	out := controller.AnalysisWindow{Until: now}
	if until != nil && until.Before(now) {
		out.Until = *until
	}
	out.Since = out.Until.Add(-min(defaultAnalysisSpan, s.cfg().Limits.JobStatsSpan()))
	if since != nil {
		out.Since = *since
		if !out.Since.Before(now) {
			badRequestField(w, "since", controller.ErrSinceNotPast.Error())
			return controller.AnalysisWindow{}, false
		}
	}
	if !s.statsWindowFits(w, out.Since, out.Until, "an analysis covers") {
		return controller.AnalysisWindow{}, false
	}
	return out, true
}

// answerAnalysis renders a finding, or what stopped it.
//
// The three comparison refusals carry the controller's own sentence, which
// says what to change, under a code of their own. A pair that is one release
// is a 400: no data makes it answerable. A fleet without two releases to
// choose, or a period past retention.jobs with no midnight to end on, is a
// 409: the request is well formed and the fleet's records refuse it, as
// update.nothing_newer is a 409 for a fleet with nothing newer to take. A 422
// here means a form's fields are wrong, and these name no field to fix.
func (s *Server) answerAnalysis(w http.ResponseWriter, r *http.Request, doing string, finding any, err error) {
	var missing controller.NotFoundError
	switch {
	case err == nil:
		writeJSON(w, http.StatusOK, finding)
	case errors.As(err, &missing):
		notFound(w, fmt.Sprintf("there is no %s %s in this fleet; it may have been removed, or the id is wrong", missing.Kind, missing.ID))
	case errors.Is(err, store.ErrNotFound):
		notFound(w, err.Error())
	case errors.Is(err, controller.ErrSinceNotPast):
		badRequestField(w, "since", err.Error())
	case errors.Is(err, controller.ErrSameRelease):
		writeError(w, http.StatusBadRequest, errorEnvelope{Error: errorBody{
			Code: codeAnalysisSameRelease, Message: err.Error(), Field: "a"}})
	case errors.Is(err, controller.ErrTooFewReleases):
		writeError(w, http.StatusConflict, errorEnvelope{Error: errorBody{
			Code: codeAnalysisTooFewReleases, Message: err.Error()}})
	case errors.Is(err, controller.ErrWholeDaysOnly):
		writeError(w, http.StatusConflict, errorEnvelope{Error: errorBody{
			Code: codeAnalysisWholeDaysOnly, Message: err.Error(), Field: "since"}})
	default:
		s.internal(w, r, doing, err)
	}
}

// handleAnalyseQueueWait answers GET /api/v1/analysis/queue-wait.
func (s *Server) handleAnalyseQueueWait(w http.ResponseWriter, r *http.Request) {
	win, ok := s.analysisWindow(w, r)
	if !ok {
		return
	}
	f, err := s.ctrl.AnalyseQueueWait(r.Context(), win, r.URL.Query().Get("pool_id"))
	s.answerAnalysis(w, r, "analysing queue wait", f, err)
}

// handleAnalyseCompare answers GET /api/v1/analysis/compare.
func (s *Server) handleAnalyseCompare(w http.ResponseWriter, r *http.Request) {
	win, ok := s.analysisWindow(w, r)
	if !ok {
		return
	}
	q := r.URL.Query()
	req := controller.CompareRequest{By: q.Get("by"), A: q.Get("a"), B: q.Get("b"), Since: win.Since, Until: win.Until}
	switch req.By {
	case "", "version":
	case "period":
		// A release named to a comparison by period would be quietly
		// ignored, and the answer read as one about that release.
		for _, name := range []string{"a", "b"} {
			if q.Get(name) != "" {
				badRequestField(w, name, "a and b name releases, which a comparison by period does not read; leave them out, or compare by=version")
				return
			}
		}
	default:
		badRequestField(w, "by", fmt.Sprintf("a comparison is by version or period, not %q", req.By))
		return
	}
	for _, name := range []string{"a", "b"} {
		if len(q.Get(name)) > maxReleaseName {
			badRequestField(w, name, fmt.Sprintf("%s is longer than a release's name can be (%d bytes at most); name a release such as v1.3.2", name, maxReleaseName))
			return
		}
	}
	f, err := s.ctrl.AnalyseCompare(r.Context(), req)
	s.answerAnalysis(w, r, "comparing", f, err)
}

// handleAnalyseHostPressure answers GET /api/v1/analysis/host-pressure.
func (s *Server) handleAnalyseHostPressure(w http.ResponseWriter, r *http.Request) {
	hostID := r.URL.Query().Get("host_id")
	if hostID == "" {
		badRequestField(w, "host_id", "name the host to read with host_id; the pressure analysis is about one host")
		return
	}
	win, ok := s.analysisWindow(w, r)
	if !ok {
		return
	}
	f, err := s.ctrl.AnalyseHostPressure(r.Context(), win, hostID)
	// The route is gated on hosts.read, and a host's view names no job: a
	// token narrowed to hosts:read is told when things went wrong and how,
	// never which jobs they were, which only jobs.read may read.
	if err == nil && !auth.Allowed(Identity(r.Context()), auth.ActionJobsRead) {
		f = analysis.WithholdJobNames(f)
	}
	s.answerAnalysis(w, r, "analysing host pressure", f, err)
}

// handleAnalyseStartupFailures answers GET /api/v1/analysis/startup-failures.
func (s *Server) handleAnalyseStartupFailures(w http.ResponseWriter, r *http.Request) {
	win, ok := s.analysisWindow(w, r)
	if !ok {
		return
	}
	q := r.URL.Query()
	f, err := s.ctrl.AnalyseStartupFailures(r.Context(), win, q.Get("pool_id"), q.Get("host_id"))
	s.answerAnalysis(w, r, "analysing startup failures", f, err)
}

package api

import (
	"errors"
	"fmt"
	"net/http"
	"net/url"
	"slices"
	"strings"

	"github.com/eyupio/zoomies/internal/assistant"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/store"
)

// assistantProviderInput is the body of a create, a patch and a draft check.
// On a patch every field is optional; APIKey empty leaves the sealed key
// alone, so a form with a blank key box does not erase one.
type assistantProviderInput struct {
	// ID names the saved provider a draft check is about, so a blank key box
	// borrows the sealed key the row holds rather than testing with none.
	ID      *string `json:"id"`
	Name    *string `json:"name"`
	Kind    *string `json:"kind"`
	BaseURL *string `json:"base_url"`
	Model   *string `json:"model"`
	Enabled *bool   `json:"enabled"`
	APIKey  *string `json:"api_key"`
	// FleetAccess lets the assistant read this fleet through the provider. It
	// is the administrator's decision per provider, and absent leaves it as it was.
	FleetAccess *bool `json:"fleet_access"`
	// ReasoningEffort is how hard the model should think, in the provider's
	// words; empty is its default. Absent leaves it as it was.
	ReasoningEffort *string `json:"reasoning_effort"`
	// MaxOutputTokens is how much the model may write in one round; zero or
	// absent-on-create is automatic, which the controller works out. Absent
	// leaves it as it was.
	MaxOutputTokens *int `json:"max_output_tokens"`
}

func (in assistantProviderInput) apply(p *store.AssistantProvider) {
	if in.Name != nil {
		p.Name = strings.TrimSpace(*in.Name)
	}
	if in.Kind != nil {
		p.Kind = strings.TrimSpace(*in.Kind)
	}
	if in.BaseURL != nil {
		p.BaseURL = strings.TrimSpace(*in.BaseURL)
	}
	if in.Model != nil {
		p.Model = strings.TrimSpace(*in.Model)
	}
	if in.Enabled != nil {
		p.Enabled = *in.Enabled
	}
	if in.FleetAccess != nil {
		p.FleetAccess = *in.FleetAccess
	}
	if in.ReasoningEffort != nil {
		p.ReasoningEffort = strings.TrimSpace(*in.ReasoningEffort)
	}
	if in.MaxOutputTokens != nil {
		p.MaxOutputTokens = *in.MaxOutputTokens
	}
}

// validateAssistantProvider says what is wrong with a row as it would be
// saved. The fake kind is admitted only where the demo seeded one, because
// a person creating "a model that answers without a network" on a real
// fleet has misunderstood what it is for.
//
// The egress check runs only when the address is being saved (checkAddress):
// a row that holds a private address with the switch since turned off can
// still be disabled, renamed or re-keyed, and only re-saving the address is
// refused, which is what the switch's own text says.
func (s *Server) validateAssistantProvider(r *http.Request, p *store.AssistantProvider, checkAddress bool, apiKey *string) []fieldError {
	var errs []fieldError
	if p.Name == "" || len(p.Name) > 80 {
		errs = append(errs, fieldError{"name", "give the provider a name of 1 to 80 characters; it is how the cards tell two apart"})
	}
	kind := assistant.Kind(p.Kind)
	known := kind == assistant.KindFake && controller.DemoRequested()
	for _, k := range assistant.Kinds {
		if k == kind {
			known = true
		}
	}
	if !known {
		names := make([]string, len(assistant.Kinds))
		for i, k := range assistant.Kinds {
			names[i] = string(k)
		}
		errs = append(errs, fieldError{"kind", "choose one of " + strings.Join(names, ", ")})
	}
	// A subscription's tool has a model of its own when none is named.
	if p.Model == "" && !assistant.Subscription(kind) {
		errs = append(errs, fieldError{"model", "name the model, as the provider calls it (llama3.1, claude-sonnet-4-5, gpt-4o)"})
	}
	switch {
	case p.BaseURL == "" && kind == assistant.KindOpenAICompatible:
		errs = append(errs, fieldError{"base_url", "an OpenAI-compatible provider needs the address its server listens on, such as http://localhost:11434/v1"})
	case p.BaseURL != "":
		u, err := url.Parse(p.BaseURL)
		if err != nil || (u.Scheme != "http" && u.Scheme != "https") || u.Host == "" {
			errs = append(errs, fieldError{"base_url", "that is not an HTTP URL; the scheme is what decides whether the connection is encrypted, so it has to be there"})
		} else if u.User != nil {
			// The address is saved in clear and shown on the card; the key box is
			// the one place a secret belongs. The message never echoes the URL.
			errs = append(errs, fieldError{"base_url", "the address carries a username or password; leave those out and put the key in the API key field, which is sealed"})
		} else if f := config.CheckProviderURL(p.BaseURL, s.cfg().Assistant.AllowPrivateProvider); checkAddress && f != nil {
			errs = append(errs, fieldError{"base_url", f.Title + ". " + f.Fix})
		}
	}
	if p.ReasoningEffort != "" {
		switch {
		case !slices.Contains(assistant.ReasoningEfforts, p.ReasoningEffort):
			errs = append(errs, fieldError{"reasoning_effort", "choose none, low, medium or high, or leave it empty for the provider's default; the provider reads the word, so what each does is its own"})
		case !assistant.SupportsReasoningEffort(kind):
			errs = append(errs, fieldError{"reasoning_effort", "only a provider that speaks the OpenAI chat protocol can be told how hard to think; leave this empty for this kind"})
		}
	}
	if p.MaxOutputTokens != 0 {
		switch {
		case p.MaxOutputTokens < controller.AssistantOutputTokensMin || p.MaxOutputTokens > controller.AssistantOutputTokensMax:
			errs = append(errs, fieldError{"max_output_tokens", fmt.Sprintf("give a number of tokens from %d to %d, or 0 to let Eli work it out; a thinking model's reasoning counts against it", controller.AssistantOutputTokensMin, controller.AssistantOutputTokensMax)})
		case assistant.Subscription(kind):
			errs = append(errs, fieldError{"max_output_tokens", "a subscription's tool decides how much its model writes; leave this at 0 for this kind"})
		}
	}
	if assistant.Subscription(kind) && p.ID != "" && p.OwnerID == "" {
		errs = append(errs, fieldError{"kind", "Add a new personal subscription provider rather than converting an installation provider."})
	}
	if assistant.Subscription(kind) && !s.isAssistantAdmin(r) {
		errs = append(errs, fieldError{"kind", "Subscription tools on the controller require an administrator; use your personal API provider instead."})
	}
	if assistant.Subscription(kind) {
		errs = append(errs, subscriptionErrors(p, apiKey)...)
	}
	return errs
}

// subscriptionErrors are what is wrong with a provider that is somebody's own
// subscription, used through the vendor's own tool: it has no address, since the
// tool knows where it goes; no key, since Zoomies holds none of a subscription's
// credentials and the sign-in is made in the vendor's own tool; and no fleet
// access, since the tool is run with its own tools off and cannot be given Eli's.
func subscriptionErrors(p *store.AssistantProvider, apiKey *string) []fieldError {
	var errs []fieldError
	if p.BaseURL != "" {
		errs = append(errs, fieldError{"base_url", "this provider has no address: the tool it runs knows where it goes"})
	}
	if apiKey != nil && strings.TrimSpace(*apiKey) != "" {
		errs = append(errs, fieldError{"api_key", "Zoomies never holds a subscription's credentials: sign in with the vendor's own tool on the machine the controller runs on instead"})
	}
	if p.FleetAccess {
		errs = append(errs, fieldError{"fleet_access", "this provider cannot be given Eli's tools yet, so it cannot read the fleet"})
	}
	return errs
}

// ownerOnly refuses a person who is not the owner of a provider that is somebody's
// own subscription, and says so. Everyone else's use of one would be routing their
// requests through another person's plan, which its terms do not permit.
func (s *Server) ownerOnly(w http.ResponseWriter, r *http.Request, row *store.AssistantProvider) bool {
	if assistant.Subscription(assistant.Kind(row.Kind)) && !s.isAssistantAdmin(r) {
		forbidden(w, "Subscription tools on the controller require an administrator.")
		return false
	}
	if id := Identity(r.Context()); id != nil && controller.UsableBy(row, id.UserID) {
		return true
	}
	writeError(w, http.StatusForbidden, errorEnvelope{Error: errorBody{Code: codeAssistantNotYours, Message: controller.ErrAssistantNotYours.Error()}})
	return false
}

// assistantView renders a provider for the person asking: whose it is, and
// whether it is theirs to use.
func (s *Server) assistantView(r *http.Request, row *store.AssistantProvider) controller.AssistantProviderView {
	uid := ""
	if id := Identity(r.Context()); id != nil {
		uid = id.UserID
	}
	return s.ctrl.AssistantProviderViewFor(r.Context(), row, uid)
}

func (s *Server) handleListAssistantProviders(w http.ResponseWriter, r *http.Request) {
	rows, err := s.ctrl.Store().ListAssistantProviders(r.Context())
	if err != nil {
		s.internal(w, r, "listing the assistant's providers", err)
		return
	}
	items := make([]controller.AssistantProviderView, 0, len(rows))
	for _, row := range rows {
		if !strings.Contains(r.URL.Path, "/assistant/personal/") && row.OwnerID != "" && !assistant.Subscription(assistant.Kind(row.Kind)) {
			continue
		}
		if !s.cfg().Security.DisableAuth && strings.Contains(r.URL.Path, "/assistant/personal/") && row.OwnerID != s.assistantOwner(r) {
			continue
		}
		items = append(items, s.assistantView(r, row))
	}
	writeJSON(w, http.StatusOK, map[string]any{"items": items})
}

func (s *Server) handleAssistantProviderKinds(w http.ResponseWriter, r *http.Request) {
	kinds := make([]map[string]string, 0, len(assistant.Kinds))
	for _, k := range assistant.Kinds {
		if assistant.Subscription(k) && !s.isAssistantAdmin(r) {
			continue
		}
		kinds = append(kinds, map[string]string{"kind": string(k), "default_base_url": assistant.DefaultBaseURL(k)})
	}
	writeJSON(w, http.StatusOK, map[string]any{"items": kinds})
}

func (s *Server) handleGetAssistantProvider(w http.ResponseWriter, r *http.Request) {
	row, err := s.ownedAssistantProvider(r, chiURLParam(r, "id"))
	if err != nil {
		s.fail(w, r, "reading the assistant provider", err)
		return
	}
	writeJSON(w, http.StatusOK, s.assistantView(r, row))
}

func (s *Server) handleCreateAssistantProvider(w http.ResponseWriter, r *http.Request) {
	var in assistantProviderInput
	if !decode(w, r, &in) {
		return
	}
	p := &store.AssistantProvider{Enabled: true, OwnerID: s.assistantOwner(r)}
	in.apply(p)
	if assistant.Subscription(assistant.Kind(p.Kind)) && !s.isAssistantAdmin(r) {
		forbidden(w, "Subscription tools on the controller require an administrator; use your personal API provider instead.")
		return
	}
	if errs := s.validateAssistantProvider(r, p, true, in.APIKey); len(errs) > 0 {
		unprocessable(w, "this provider cannot be created as described", errs)
		return
	}
	if assistant.Subscription(assistant.Kind(p.Kind)) {
		// It belongs to the person who adds it. A caller that is not a person, or a
		// token that has no owner, has nobody for it to belong to.
		id := Identity(r.Context())
		if id == nil || id.UserID == "" {
			forbidden(w, "a subscription belongs to a person: add it signed in as yourself, and not with a token that has no owner")
			return
		}
		p.OwnerID = id.UserID
	}
	if err := s.ctrl.Store().CreateAssistantProvider(r.Context(), p); err != nil {
		s.fail(w, r, "creating the assistant provider", err)
		return
	}
	if in.APIKey != nil && strings.TrimSpace(*in.APIKey) != "" {
		if !s.sealAssistantKey(w, r, p.ID, *in.APIKey) {
			// The caller was told the create failed, so a row that exists without
			// the key it was given would be a surprise on the next load: a card
			// that looks saved and cannot answer. Take it back; a second failure
			// here is logged rather than reported, the response is already sent.
			if err := s.ctrl.Store().DeleteAssistantProvider(r.Context(), p.ID); err != nil {
				s.log.Warn("removing the provider whose key could not be saved", "id", p.ID, "err", err)
			}
			return
		}
	}
	fresh, err := s.ctrl.Store().GetAssistantProvider(r.Context(), p.ID)
	if err != nil {
		s.internal(w, r, "reading the assistant provider back", err)
		return
	}
	view := s.ctrl.AssistantProviderView(fresh)
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "assistant.provider.create", "assistant_provider", p.ID, view)
	writeJSON(w, http.StatusCreated, s.assistantView(r, fresh))
}

func (s *Server) handleUpdateAssistantProvider(w http.ResponseWriter, r *http.Request) {
	row, err := s.ownedAssistantProvider(r, chiURLParam(r, "id"))
	if err != nil {
		s.fail(w, r, "reading the assistant provider", err)
		return
	}
	if !s.ownerOnly(w, r, row) {
		return
	}
	var in assistantProviderInput
	if !decode(w, r, &in) {
		return
	}
	before := s.ctrl.AssistantProviderView(row)
	in.apply(row)
	if errs := s.validateAssistantProvider(r, row, in.BaseURL != nil, in.APIKey); len(errs) > 0 {
		unprocessable(w, "this provider cannot be changed as described", errs)
		return
	}
	if err := s.ctrl.Store().UpdateAssistantProvider(r.Context(), row); err != nil {
		s.fail(w, r, "saving the assistant provider", err)
		return
	}
	if in.APIKey != nil && strings.TrimSpace(*in.APIKey) != "" {
		if !s.sealAssistantKey(w, r, row.ID, *in.APIKey) {
			return
		}
	}
	fresh, err := s.ctrl.Store().GetAssistantProvider(r.Context(), row.ID)
	if err != nil {
		s.internal(w, r, "reading the assistant provider back", err)
		return
	}
	view := s.ctrl.AssistantProviderView(fresh)
	s.auth.Auditor().Updated(r.Context(), Identity(r.Context()), "assistant_provider", row.ID, before, view)
	if before.FleetAccess != view.FleetAccess {
		// Its own row, because it is the one setting that decides whether a
		// stranger's model is shown this fleet, and it should be findable as that.
		s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "assistant.provider.fleet_access", "assistant_provider", row.ID,
			map[string]any{"name": view.Name, "fleet_access": view.FleetAccess, "local": view.Local})
	}
	writeJSON(w, http.StatusOK, s.assistantView(r, fresh))
}

// sealAssistantKey seals a key with the instance key and writes it through
// the row's own setter, auditing that a key changed and never what it is.
func (s *Server) sealAssistantKey(w http.ResponseWriter, r *http.Request, id, key string) bool {
	sealed, err := s.key.SealString(strings.TrimSpace(key))
	if err != nil {
		s.internal(w, r, "sealing the provider's key", err)
		return false
	}
	if err := s.ctrl.Store().SetAssistantProviderKey(r.Context(), id, sealed); err != nil {
		s.fail(w, r, "saving the provider's key", err)
		return false
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "assistant.provider.key", "assistant_provider", id, nil)
	return true
}

// deleteAssistantProviderRequest carries the name typed to confirm: a
// delete that could be sent by a stray click on the wrong card is not one.
type deleteAssistantProviderRequest struct {
	Name string `json:"name"`
}

func (s *Server) handleDeleteAssistantProvider(w http.ResponseWriter, r *http.Request) {
	row, err := s.ownedAssistantProvider(r, chiURLParam(r, "id"))
	if err != nil {
		s.fail(w, r, "reading the assistant provider", err)
		return
	}
	var in deleteAssistantProviderRequest
	if !decode(w, r, &in) {
		return
	}
	if strings.TrimSpace(in.Name) != row.Name {
		conflict(w, fmt.Sprintf("the name typed does not match %q, so the provider was not removed; type its name exactly to confirm", row.Name))
		return
	}
	if err := s.ctrl.Store().DeleteAssistantProvider(r.Context(), row.ID); err != nil {
		s.fail(w, r, "removing the assistant provider", err)
		return
	}
	s.auth.Auditor().Deleted(r.Context(), Identity(r.Context()), "assistant_provider", row.ID, s.ctrl.AssistantProviderView(row))
	noContent(w)
}

func (s *Server) handleCheckAssistantProvider(w http.ResponseWriter, r *http.Request) {
	row, err := s.ownedAssistantProvider(r, chiURLParam(r, "id"))
	if err != nil {
		s.fail(w, r, "reading the assistant provider", err)
		return
	}
	if !s.ownerOnly(w, r, row) {
		return
	}
	check := s.ctrl.CheckAssistantProvider(r.Context(), row)
	if err := s.ctrl.RecordAssistantProviderCheck(r.Context(), row.ID, check); err != nil {
		s.internal(w, r, "recording the check", err)
		return
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "assistant.provider.check", "assistant_provider", row.ID,
		map[string]any{"name": row.Name, "ok": check.OK, "model": check.Model})
	writeJSON(w, http.StatusOK, check)
}

// handleCheckAssistantDraft checks a provider as the form has it, with the
// key the form holds, so a key need not be saved to be tested. Nothing is
// written and nothing is audited as a change; the check is still the
// administrator's and is audited as one.
func (s *Server) handleCheckAssistantDraft(w http.ResponseWriter, r *http.Request) {
	var in assistantProviderInput
	if !decode(w, r, &in) {
		return
	}
	draft := &store.AssistantProvider{Enabled: true}
	if in.ID != nil && *in.ID != "" {
		// The Edit dialog's Test: the draft is the saved row with the form's
		// fields over it, so a blank key box means the key the row holds.
		row, err := s.ownedAssistantProvider(r, *in.ID)
		if err != nil {
			s.fail(w, r, "reading the assistant provider", err)
			return
		}
		if !s.ownerOnly(w, r, row) {
			return
		}
		draft = row
	}
	in.apply(draft)
	if draft.Name == "" {
		draft.Name = "draft"
	}
	if errs := s.validateAssistantProvider(r, draft, in.BaseURL != nil, in.APIKey); len(errs) > 0 {
		unprocessable(w, "this provider cannot be checked as described", errs)
		return
	}
	key := ""
	if in.APIKey != nil {
		key = *in.APIKey
	}
	check := s.ctrl.CheckAssistantDraft(r.Context(), draft, key)
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "assistant.provider.check", "assistant_provider", "",
		map[string]any{"draft": true, "kind": draft.Kind, "ok": check.OK, "model": check.Model})
	writeJSON(w, http.StatusOK, check)
}

// handleAssistantModels lists the models a provider, as the form has it, says it
// serves. It spends the form's key the way a draft check does, so it is the same
// role, and writes nothing. A provider that would not answer is a 502 with the
// adapter's words, which never carry the request or the key.
func (s *Server) handleAssistantModels(w http.ResponseWriter, r *http.Request) {
	var in assistantProviderInput
	if !decode(w, r, &in) {
		return
	}
	draft := &store.AssistantProvider{Enabled: true}
	if in.ID != nil && *in.ID != "" {
		row, err := s.ownedAssistantProvider(r, *in.ID)
		if err != nil {
			s.fail(w, r, "reading the assistant provider", err)
			return
		}
		if !s.ownerOnly(w, r, row) {
			return
		}
		draft = row
	}
	in.apply(draft)
	if draft.Name == "" {
		draft.Name = "draft"
	}
	if draft.Model == "" {
		// The list is how a model is chosen, so asking for it before one is
		// chosen must not be refused for want of one.
		draft.Model = "unset"
	}
	if errs := s.validateAssistantProvider(r, draft, in.BaseURL != nil, in.APIKey); len(errs) > 0 {
		unprocessable(w, "the models of this provider cannot be listed as described", errs)
		return
	}
	key := ""
	if in.APIKey != nil {
		key = *in.APIKey
	}
	models, err := s.ctrl.ListAssistantModels(r.Context(), draft, key)
	switch {
	case errors.Is(err, controller.ErrAssistantCannotList):
		conflict(w, err.Error())
		return
	case err != nil:
		writeError(w, http.StatusBadGateway, errorEnvelope{Error: errorBody{Code: codeAssistantProviderFailed, Message: err.Error()}})
		return
	}
	if models == nil {
		models = []string{}
	}
	writeJSON(w, http.StatusOK, map[string]any{"items": models})
}

func (s *Server) handleDefaultAssistantProvider(w http.ResponseWriter, r *http.Request) {
	row, err := s.ownedAssistantProvider(r, chiURLParam(r, "id"))
	if err != nil {
		s.fail(w, r, "reading the assistant provider", err)
		return
	}
	if !s.ownerOnly(w, r, row) {
		return
	}
	if err := s.ctrl.Store().SetDefaultAssistantProvider(r.Context(), row.ID); err != nil {
		s.fail(w, r, "choosing the default provider", err)
		return
	}
	fresh, err := s.ctrl.Store().GetAssistantProvider(r.Context(), row.ID)
	if err != nil {
		s.internal(w, r, "reading the assistant provider back", err)
		return
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "assistant.provider.default", "assistant_provider", row.ID, map[string]any{"name": row.Name})
	writeJSON(w, http.StatusOK, s.assistantView(r, fresh))
}

// A personal provider's scope comes from authentication and routing, never from its JSON body.
func (s *Server) assistantOwner(r *http.Request) string {
	if s.cfg().Security.DisableAuth {
		return ""
	}
	if strings.Contains(r.URL.Path, "/assistant/personal/") {
		return Identity(r.Context()).UserID
	}
	return ""
}
func (s *Server) requirePersonalAssistantOwner(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if Identity(r.Context()).UserID == "" && !s.cfg().Security.DisableAuth {
			writeError(w, http.StatusForbidden, errorEnvelope{Error: errorBody{Code: codeForbidden, Message: "Personal Eli providers require a credential owned by a user."}})
			return
		}
		next.ServeHTTP(w, r)
	})
}
func (s *Server) ownedAssistantProvider(r *http.Request, id string) (*store.AssistantProvider, error) {
	row, err := s.ctrl.Store().GetAssistantProvider(r.Context(), id)
	if err != nil {
		return nil, err
	}
	if !s.cfg().Security.DisableAuth && strings.Contains(r.URL.Path, "/assistant/personal/") && row.OwnerID != s.assistantOwner(r) {
		return nil, store.ErrNotFound
	}
	if !strings.Contains(r.URL.Path, "/assistant/personal/") && row.OwnerID != "" && !assistant.Subscription(assistant.Kind(row.Kind)) {
		return nil, store.ErrNotFound
	}
	return row, nil
}

func (s *Server) isAssistantAdmin(r *http.Request) bool {
	id := Identity(r.Context())
	return s.cfg().Security.DisableAuth || id != nil && id.Role == "admin"
}

package api

import (
	"encoding/json"
	"errors"
	"net/http"
	"slices"
	"strings"

	"github.com/eyupio/zoomies/internal/controller"
)

// assistantChatInput is the body of a chat: the conversation so far, ending in
// the person's question, and optionally which provider to ask. Nothing is kept
// between requests; the page holds the history and sends it again.
type assistantChatInput struct {
	ProviderID string `json:"provider_id"`
	// Page is the path of the page the question was asked from, so the model
	// knows what "here" is. It is a path and nothing else, or empty.
	Page string `json:"page"`
	// Style is how the person wants the answer written, from their settings.
	Style    *assistantStyleInput `json:"style"`
	Messages []struct {
		Role    string `json:"role"`
		Content string `json:"content"`
	} `json:"messages"`
}

// assistantStyleInput is a person's answer style as the UI sends it, with the
// chat and in their preferences. Empty is the default.
type assistantStyleInput struct {
	Length string `json:"length,omitempty"`
	Tone   string `json:"tone,omitempty"`
}

// validate says which part of a style this build does not know, or nothing.
func (in *assistantStyleInput) validate(field string) []fieldError {
	if in == nil {
		return nil
	}
	var errs []fieldError
	if in.Length != "" && !slices.Contains(controller.AssistantLengths, in.Length) {
		errs = append(errs, fieldError{field + ".length", "one of " + strings.Join(controller.AssistantLengths, ", ")})
	}
	if in.Tone != "" && !slices.Contains(controller.AssistantTones, in.Tone) {
		errs = append(errs, fieldError{field + ".tone", "one of " + strings.Join(controller.AssistantTones, ", ")})
	}
	return errs
}

// assistantPageMaxBytes bounds the page path a chat may name: a route of this
// UI is far shorter, and the path goes into the prompt as it is.
const assistantPageMaxBytes = 200

// handleAssistantChat answers a conversation as a stream of Server-Sent Events:
// `delta` frames carrying text, `tool` frames as Eli looks at the fleet (with
// the tool's name and running, done or failed), one `usage` frame when the
// provider reports it, and `done` (saying whether the fleet could be read and
// which tools were used), or `error` if the answer failed after it began.
//
// Anything that can be refused is refused before the stream opens, with a status
// and a code a client can act on, so a stream that opens has an answer coming.
// A failure after that is a frame and not a status, because the status went out
// with the first byte.
func (s *Server) handleAssistantChat(w http.ResponseWriter, r *http.Request) {
	var in assistantChatInput
	if !decode(w, r, &in) {
		return
	}
	if in.Page != "" && (!strings.HasPrefix(in.Page, "/") || len(in.Page) > assistantPageMaxBytes || strings.ContainsAny(in.Page, "\n\r")) {
		unprocessable(w, "page is the path of the page the question is asked from", []fieldError{{"page", "send a path starting with /, at most 200 characters"}})
		return
	}
	if errs := in.Style.validate("style"); len(errs) > 0 {
		unprocessable(w, "style names an answer length or tone this build does not have", errs)
		return
	}
	req := controller.AssistantChatRequest{ProviderID: in.ProviderID, OwnerID: s.assistantOwner(r), AllowSubscription: s.isAssistantAdmin(r), Personal: !s.cfg().Security.DisableAuth && strings.Contains(r.URL.Path, "/assistant/personal/"), Page: in.Page}
	if in.Style != nil {
		req.Style = controller.AssistantStyle{Length: in.Style.Length, Tone: in.Style.Tone}
	}
	// The tools are the person's own: the same routes with the same identity.
	// Whether the provider may be shown the fleet through them is decided by the
	// controller, per provider.
	if id := Identity(r.Context()); id != nil {
		req.Tools = s.assistantToolbox(r, id)
		req.UserID = id.UserID
		req.Role = string(id.Role)
	}
	for _, m := range in.Messages {
		req.Messages = append(req.Messages, controller.AssistantChatMessage{Role: m.Role, Content: m.Content})
	}
	chat, err := s.ctrl.StartAssistantChat(r.Context(), req)
	var invalid *controller.AssistantChatInvalid
	switch {
	case errors.As(err, &invalid):
		unprocessable(w, invalid.Message, []fieldError{{invalid.Field, invalid.Message}})
		return
	case errors.Is(err, controller.ErrAssistantSubscriptionRestricted):
		forbidden(w, err.Error())
		return
	case errors.Is(err, controller.ErrAssistantNotYours):
		writeError(w, http.StatusForbidden, errorEnvelope{Error: errorBody{Code: codeAssistantNotYours, Message: err.Error()}})
		return
	case errors.Is(err, controller.ErrAssistantNoModel):
		conflict(w, "no assistant model is set up; add a provider, test it and make it the default under Settings, Assistant")
		return
	case err != nil:
		// The model's end failed, not this controller. The adapters write their
		// errors for a person and never carry the request or the key.
		writeError(w, http.StatusBadGateway, errorEnvelope{Error: errorBody{Code: codeAssistantProviderFailed, Message: err.Error()}})
		return
	}
	defer chat.Close()

	stream := startSSE(w, r)
	send := func(kind string, v any) bool {
		b, err := json.Marshal(v)
		if err != nil {
			return false
		}
		return stream.event(kind, "", b) == nil
	}
	outcome := "answered"
	// The audit row says who asked which provider to read what, and never what
	// was said: it is written however the answer ends.
	defer func() {
		s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "assistant.chat", "assistant_provider", chat.ProviderID, map[string]any{
			"provider": chat.Provider, "model": chat.Model, "fleet_access": chat.FleetAccess,
			"tools": chat.ToolsUsed(), "outcome": outcome,
			"credentials_hidden_count": chat.Redactions().Credentials, "emails_hidden_count": chat.Redactions().Emails,
		})
	}()
	for {
		ev, ok := chat.Next(r.Context())
		if !ok {
			outcome = "abandoned"
			return
		}
		switch {
		case ev.Err != nil:
			outcome = "failed"
			send("error", map[string]string{"message": ev.Err.Error()})
			return
		case ev.Tool != nil:
			frame := map[string]string{"name": ev.Tool.Name, "status": ev.Tool.Status}
			if ev.Tool.Reason != "" {
				frame["reason"] = ev.Tool.Reason
			}
			if !send("tool", frame) {
				outcome = "abandoned"
				return
			}
		case ev.Usage != nil:
			if !send("usage", map[string]int{"input_tokens": ev.Usage.InputTokens, "output_tokens": ev.Usage.OutputTokens}) {
				outcome = "abandoned"
				return
			}
		case ev.Done:
			hidden := chat.Redactions()
			if ev.Cut {
				outcome = "cut"
			}
			send("done", map[string]any{
				"provider": chat.Provider, "model": chat.Model, "fleet_access": chat.FleetAccess, "tools": chat.ToolsUsed(),
				"redacted": map[string]int{"credentials": hidden.Credentials, "emails": hidden.Emails},
				"cut":      ev.Cut, "provider_id": chat.ProviderID, "output_limit": chat.OutputLimit,
			})
			return
		case ev.Delta != "":
			if !send("delta", map[string]string{"text": ev.Delta}) {
				outcome = "abandoned"
				return
			}
		}
	}
}

package api

import (
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/assistant/assistanttest"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// withClaudeCode puts a stand-in for Claude Code first on the PATH, signed in as
// the method says and answering with what it is told.
func withClaudeCode(t *testing.T, method string) {
	t.Helper()
	dir := t.TempDir()
	script := `#!/bin/sh
case "$1" in
  --version) echo "2.1.300 (Claude Code)"; exit 0 ;;
  auth) echo '{"loggedIn":true,"authMethod":"` + method + `"}'; exit 0 ;;
esac
cat > /dev/null
echo '{"type":"stream_event","event":{"type":"content_block_delta","delta":{"type":"text_delta","text":"Hello from"}}}'
echo '{"type":"stream_event","event":{"type":"content_block_delta","delta":{"type":"text_delta","text":" Claude"}}}'
echo '{"type":"result","subtype":"success","is_error":false,"result":"Hello from Claude","usage":{"input_tokens":9,"output_tokens":4}}'
`
	if err := os.WriteFile(filepath.Join(dir, "claude"), []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", dir+string(os.PathListSeparator)+os.Getenv("PATH"))
}

func claudeBody(name string) map[string]any {
	return map[string]any{"name": name, "kind": "claude_code", "model": "sonnet"}
}

// claudeHarness is two administrators and a Claude subscription that is Alice's.
func claudeHarness(t *testing.T) (h *harness, alice, bob, id string) {
	t.Helper()
	withClaudeCode(t, "claude.ai")
	h = newHarness(t, func(c *config.Config) { c.Assistant.AllowPrivateProvider = true })
	_, alice = h.user("alice", store.RoleAdmin)
	_, bob = h.user("bob", store.RoleAdmin)
	resp := h.do(request{method: http.MethodPost, path: assistantProviders, cookie: alice, body: claudeBody("Alice's Claude")})
	resp.mustStatus(t, http.StatusCreated, "adding a Claude subscription")
	return h, alice, bob, resp.json(t)["id"].(string)
}

// A Claude subscription has no address and no key for Zoomies to hold, and cannot
// be given the fleet: each is refused with the field to fix, and the sign-in is
// said to be made in Claude Code.
func TestAClaudeSubscriptionHasNoAddressNoKeyAndNoFleetAccess(t *testing.T) {
	withClaudeCode(t, "claude.ai")
	h := newHarness(t)
	_, alice := h.user("alice", store.RoleAdmin)
	for field, body := range map[string]map[string]any{
		"base_url":     {"base_url": "https://api.anthropic.com"},
		"api_key":      {"api_key": "sk-ant-oat01-a-subscription-token"},
		"fleet_access": {"fleet_access": true},
	} {
		b := claudeBody("Claude")
		for k, v := range body {
			b[k] = v
		}
		resp := h.do(request{method: http.MethodPost, path: assistantProviders, cookie: alice, body: b})
		resp.mustStatus(t, http.StatusUnprocessableEntity, "a subscription with a "+field)
		if !strings.Contains(string(resp.body), `"`+field+`"`) {
			t.Errorf("the refusal does not name %s: %s", field, resp.body)
		}
		if strings.Contains(string(resp.body), "a-subscription-token") {
			t.Errorf("the refusal repeats the key: %s", resp.body)
		}
	}
	if rows, _ := h.st.ListAssistantProviders(h.ctx); len(rows) != 0 {
		t.Errorf("%d providers were saved", len(rows))
	}
}

// It is the person's who added it, and says so; everybody else sees that it
// exists and whose it is, and that it is not theirs.
func TestAClaudeSubscriptionBelongsToWhoAddedIt(t *testing.T) {
	h, alice, bob, id := claudeHarness(t)
	row, _ := h.st.GetAssistantProvider(h.ctx, id)
	users, _ := h.st.ListUsers(h.ctx)
	var aliceID string
	for _, u := range users {
		if u.Username == "alice" {
			aliceID = u.ID
		}
	}
	if row.OwnerID == "" || row.OwnerID != aliceID {
		t.Fatalf("owner = %q, want alice's %q", row.OwnerID, aliceID)
	}
	for who, cookie := range map[string]string{"alice": alice, "bob": bob} {
		resp := h.do(request{method: http.MethodGet, path: assistantProviders + "/" + id, cookie: cookie})
		resp.mustStatus(t, http.StatusOK, who+" reading it")
		v := resp.json(t)
		mine := who == "alice"
		if v["subscription"] != true || v["owner"] != "alice" || v["owned_by_you"] != mine || v["usable"] != mine {
			t.Errorf("%s sees %v", who, v)
		}
		if v["key_configured"] != false || v["base_url"] != "" {
			t.Errorf("a subscription shows a key or an address: %v", v)
		}
	}
	// A provider that is shared is usable by everybody, and nobody's.
	shared := h.do(request{method: http.MethodPost, path: assistantProviders, cookie: alice, body: map[string]any{
		"name": "Hosted", "kind": "anthropic", "model": "m", "api_key": "sk-test"}})
	shared.mustStatus(t, http.StatusCreated, "adding a shared provider")
	if v := shared.json(t); v["subscription"] != false || v["usable"] != true || v["owned_by_you"] != false || v["owner"] != nil {
		t.Errorf("a shared provider says %v", v)
	}
}

// Nobody but the owner uses it, changes it, tests it or makes it the default, and
// the refusal has a code that says why. Any administrator may remove it: it holds
// no credential, and a person who has gone leaves it behind.
func TestAnotherAdministratorCannotUseSomeonesClaudeSubscription(t *testing.T) {
	h, alice, bob, id := claudeHarness(t)
	path := assistantProviders + "/" + id
	for name, req := range map[string]request{
		"change it":          {method: http.MethodPatch, path: path, body: map[string]any{"model": "opus"}},
		"test it":            {method: http.MethodPost, path: path + "/check", body: map[string]any{}},
		"make it default":    {method: http.MethodPost, path: path + "/default", body: map[string]any{}},
		"test it as a draft": {method: http.MethodPost, path: assistantProviders + "/check", body: map[string]any{"id": id, "kind": "claude_code", "model": "sonnet", "name": "x"}},
		"list its models":    {method: http.MethodPost, path: assistantProviders + "/models", body: map[string]any{"id": id, "kind": "claude_code", "model": "sonnet", "name": "x"}},
		"chat through it":    {method: http.MethodPost, path: assistantChat, body: map[string]any{"provider_id": id, "messages": []map[string]string{{"role": "user", "content": "hi"}}}},
	} {
		req.cookie = bob
		resp := h.do(req)
		resp.mustStatus(t, http.StatusForbidden, "bob trying to "+name)
		if !strings.Contains(string(resp.body), "assistant.provider_not_yours") {
			t.Errorf("bob trying to %s: %s", name, resp.body)
		}
	}
	// Nothing he tried changed it.
	if row, _ := h.st.GetAssistantProvider(h.ctx, id); row.Model != "sonnet" || row.IsDefault {
		t.Errorf("the provider was changed: %+v", row)
	}
	// Alice can do all of that.
	h.do(request{method: http.MethodPatch, path: path, cookie: alice, body: map[string]any{"model": "opus"}}).mustStatus(t, http.StatusOK, "alice changing it")
	h.do(request{method: http.MethodPost, path: path + "/default", cookie: alice, body: map[string]any{}}).mustStatus(t, http.StatusOK, "alice making it the default")
	// And an administrator who is not the owner can take it away, with its name typed.
	h.do(request{method: http.MethodDelete, path: path, cookie: bob, body: map[string]any{"name": "Alice's Claude"}}).mustStatus(t, http.StatusNoContent, "bob removing it")
}

// The test reads how Claude Code is signed in and spends nothing; a copy signed in
// with an API key is turned away with what to do.
func TestTestingAClaudeSubscriptionReadsHowClaudeCodeIsSignedIn(t *testing.T) {
	h, alice, _, id := claudeHarness(t)
	resp := h.do(request{method: http.MethodPost, path: assistantProviders + "/" + id + "/check", cookie: alice, body: map[string]any{}})
	resp.mustStatus(t, http.StatusOK, "testing it")
	if v := resp.json(t); v["ok"] != true || !strings.Contains(v["model"].(string), "Claude Code 2.1.300") {
		t.Errorf("check = %v", v)
	}

	withClaudeCode(t, "api_key")
	resp = h.do(request{method: http.MethodPost, path: assistantProviders + "/" + id + "/check", cookie: alice, body: map[string]any{}})
	resp.mustStatus(t, http.StatusOK, "testing it again")
	if v := resp.json(t); v["ok"] != false || !strings.Contains(strings.ToLower(v["error"].(string)), "api key") {
		t.Errorf("a copy signed in with a key passed: %v", v)
	}
}

// Eli answers through the owner's Claude Code, in the words it streams, and the
// chat says it could not read the fleet; the audit row says which provider and
// that no tool was used.
func TestEliAnswersThroughTheOwnersClaudeCode(t *testing.T) {
	h, alice, _, id := claudeHarness(t)
	h.do(request{method: http.MethodPost, path: assistantProviders + "/" + id + "/default", cookie: alice, body: map[string]any{}}).
		mustStatus(t, http.StatusOK, "making it the default")
	resp := h.do(request{method: http.MethodPost, path: assistantChat, cookie: alice, readStream: true, body: chatBody("user", "What is a runner?")})
	resp.mustStatus(t, http.StatusOK, "asking")
	var text string
	var done map[string]any
	for _, f := range frames(t, resp.body) {
		switch f.kind {
		case "delta":
			text += f.data["text"].(string)
		case "done":
			done = f.data
		case "error":
			t.Fatalf("the answer failed: %v", f.data)
		}
	}
	if text != "Hello from Claude" || done["provider"] != "Alice's Claude" || done["model"] != "sonnet" || done["fleet_access"] != false {
		t.Errorf("text = %q, done = %v", text, done)
	}
	rows, _, _ := h.st.ListAudit(h.ctx, store.AuditFilter{Actions: []string{"assistant.chat"}}, store.Page{Limit: 5})
	if len(rows) != 1 || !strings.Contains(rows[0].After, `"provider":"Alice's Claude"`) || !strings.Contains(rows[0].After, `"fleet_access":false`) {
		t.Errorf("audit rows = %+v", rows)
	}
}

// When the default is somebody else's subscription, a chat is answered by the
// first shared provider the person may use; with none, there is no model for them
// and they are not given the other person's.
func TestWhenTheDefaultIsSomeoneElsesSubscriptionAChatFallsBackOrHasNoModel(t *testing.T) {
	h, alice, bob, id := claudeHarness(t)
	h.do(request{method: http.MethodPost, path: assistantProviders + "/" + id + "/default", cookie: alice, body: map[string]any{}}).
		mustStatus(t, http.StatusOK, "making it the default")
	ask := func(cookie string) *response {
		return h.do(request{method: http.MethodPost, path: assistantChat, cookie: cookie, readStream: true, body: chatBody("user", "hi")})
	}
	ask(bob).mustStatus(t, http.StatusConflict, "bob with nothing but alice's subscription")

	srvURL := startShared(t, h, alice)
	resp := ask(bob)
	resp.mustStatus(t, http.StatusOK, "bob with a shared provider")
	var done map[string]any
	for _, f := range frames(t, resp.body) {
		if f.kind == "done" {
			done = f.data
		}
	}
	if done == nil || done["provider"] != "Shared" {
		t.Errorf("done = %v (shared provider at %s)", done, srvURL)
	}
	// Alice, with her own as the default, still gets hers.
	for _, f := range frames(t, ask(alice).body) {
		if f.kind == "done" && f.data["provider"] != "Alice's Claude" {
			t.Errorf("alice was answered by %v", f.data["provider"])
		}
	}
}

// The fallback is a provider that is on: a switched-off one that sorts first is not
// asked, or a person would be answered by a model an administrator had turned off.
func TestTheFallbackIsNeverAProviderThatIsSwitchedOff(t *testing.T) {
	h, alice, bob, id := claudeHarness(t)
	h.do(request{method: http.MethodPost, path: assistantProviders + "/" + id + "/default", cookie: alice, body: map[string]any{}}).
		mustStatus(t, http.StatusOK, "making it the default")
	off := assistanttest.NewOpenAI(t)
	body := providerBody(off, "Aaa switched off")
	body["enabled"] = false
	h.do(request{method: http.MethodPost, path: assistantProviders, cookie: alice, body: body}).
		mustStatus(t, http.StatusCreated, "adding a provider that is off")
	startShared(t, h, alice)

	resp := h.do(request{method: http.MethodPost, path: assistantChat, cookie: bob, readStream: true, body: chatBody("user", "hi")})
	resp.mustStatus(t, http.StatusOK, "bob with one provider on")
	for _, f := range frames(t, resp.body) {
		if f.kind == "done" && f.data["provider"] != "Shared" {
			t.Errorf("answered by %v, want the one that is on", f.data["provider"])
		}
	}
}

// Local models only refuses it, because Claude Code dials Anthropic itself, which
// no promise about the dialer can cover.
func TestLocalModelsOnlyRefusesClaudeCode(t *testing.T) {
	withClaudeCode(t, "claude.ai")
	h := newHarness(t, func(c *config.Config) { c.Assistant.LocalOnly = true })
	_, alice := h.user("alice", store.RoleAdmin)
	resp := h.do(request{method: http.MethodPost, path: assistantProviders, cookie: alice, body: claudeBody("Alice's Claude")})
	resp.mustStatus(t, http.StatusCreated, "adding it")
	id := resp.json(t)["id"].(string)
	resp = h.do(request{method: http.MethodPost, path: assistantProviders + "/" + id + "/check", cookie: alice, body: map[string]any{}})
	resp.mustStatus(t, http.StatusOK, "testing it")
	if v := resp.json(t); v["ok"] != false || !strings.Contains(v["error"].(string), "Local models only") {
		t.Errorf("check = %v", v)
	}
	h.do(request{method: http.MethodPost, path: assistantProviders + "/" + id + "/default", cookie: alice, body: map[string]any{}}).
		mustStatus(t, http.StatusOK, "making it the default")
	h.do(request{method: http.MethodPost, path: assistantChat, cookie: alice, readStream: true, body: chatBody("user", "hi")}).
		mustStatus(t, http.StatusBadGateway, "asking with local only on")
}

// startShared adds a provider every administrator may use, and returns where it is.
func startShared(t *testing.T, h *harness, cookie string) string {
	t.Helper()
	srv := assistanttest.NewOpenAI(t)
	h.do(request{method: http.MethodPost, path: assistantProviders, cookie: cookie, body: providerBody(srv, "Shared")}).
		mustStatus(t, http.StatusCreated, "adding a shared provider")
	return srv.URL
}

// Even if a Claude subscription somehow had the fleet switch on, as a row written
// around the API could, it is not offered Eli's tools: the tool it runs has its
// own turned off and takes a question as text.
func TestAClaudeSubscriptionIsNeverOfferedTheFleet(t *testing.T) {
	h, alice, _, id := claudeHarness(t)
	row, _ := h.st.GetAssistantProvider(h.ctx, id)
	row.FleetAccess = true
	if err := h.st.UpdateAssistantProvider(h.ctx, row); err != nil {
		t.Fatal(err)
	}
	h.do(request{method: http.MethodPost, path: assistantProviders + "/" + id + "/default", cookie: alice, body: map[string]any{}}).
		mustStatus(t, http.StatusOK, "making it the default")
	resp := h.do(request{method: http.MethodPost, path: assistantChat, cookie: alice, readStream: true, body: chatBody("user", "How is the fleet?")})
	resp.mustStatus(t, http.StatusOK, "asking")
	for _, f := range frames(t, resp.body) {
		if f.kind == "tool" || (f.kind == "done" && f.data["fleet_access"] != false) {
			t.Errorf("Claude Code was given the fleet: %v %v", f.kind, f.data)
		}
	}
}

// A token that belongs to nobody cannot add a subscription: there is nobody for
// it to belong to.
func TestATokenWithNoOwnerCannotAddASubscription(t *testing.T) {
	withClaudeCode(t, "claude.ai")
	h := newHarness(t)
	token := h.token("ci", store.RoleAdmin)
	resp := h.do(request{method: http.MethodPost, path: assistantProviders, token: token, body: claudeBody("Claude")})
	resp.mustStatus(t, http.StatusForbidden, "a token with no owner adding a subscription")
	if rows, _ := h.st.ListAssistantProviders(h.ctx); len(rows) != 0 {
		t.Errorf("%d providers were saved", len(rows))
	}
}

package api

import (
	"encoding/json"
	"errors"
	"net/http"
	"strings"
	"time"
	"unicode/utf8"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/redact"
	"github.com/eyupio/zoomies/internal/store"
)

// A person's saved conversations with Eli. The chat itself keeps nothing
// between requests; the page holds the conversation and, once an answer has
// landed, asks for it to be kept here, under the account, so a reload or
// another device finds it. What is kept is the transcript the page would send
// back, bounded the same way and redacted the same way, so nothing is in the
// database that was not already in front of a model. Only a signed-in account
// has somewhere to keep one: a token or an auth-disabled session reads an empty
// list and may not write.

// assistantConversationTitleRunes bounds the title: the first question, cut
// to what a list row can show.
const assistantConversationTitleRunes = 80

type assistantConversationInput struct {
	Title    string                            `json:"title"`
	Messages []controller.AssistantChatMessage `json:"messages"`
}

// assistantConversationView is one conversation as the API renders it: the
// summary alone in a list, the messages too when one is read or written.
type assistantConversationView struct {
	ID           string                            `json:"id"`
	Title        string                            `json:"title"`
	MessageCount int                               `json:"message_count"`
	CreatedAt    time.Time                         `json:"created_at"`
	UpdatedAt    time.Time                         `json:"updated_at"`
	Messages     []controller.AssistantChatMessage `json:"messages,omitempty"`
}

func conversationView(c *store.AssistantConversation) assistantConversationView {
	v := assistantConversationView{ID: c.ID, Title: c.Title, MessageCount: c.MessageCount, CreatedAt: c.CreatedAt, UpdatedAt: c.UpdatedAt}
	if len(c.Messages) > 0 {
		// A row this process wrote parses; one that does not is shown empty
		// rather than failing the read, so a person can still delete it.
		_ = json.Unmarshal(c.Messages, &v.Messages)
	}
	return v
}

// conversationOwner is the account that may keep conversations, or empty.
func conversationOwner(r *http.Request) string {
	id := Identity(r.Context())
	if id == nil || id.Kind != auth.KindUser || !store.HasPrefix(id.ID, store.PrefixUser) {
		return ""
	}
	return id.ID
}

func (s *Server) handleListAssistantConversations(w http.ResponseWriter, r *http.Request) {
	owner := conversationOwner(r)
	items := []assistantConversationView{}
	if owner == "" {
		writeJSON(w, http.StatusOK, map[string]any{"items": items})
		return
	}
	rows, err := s.ctrl.Store().ListAssistantConversations(r.Context(), owner)
	if err != nil {
		s.internal(w, r, "listing the conversations", err)
		return
	}
	for _, row := range rows {
		items = append(items, conversationView(row))
	}
	writeJSON(w, http.StatusOK, map[string]any{"items": items})
}

func (s *Server) handleGetAssistantConversation(w http.ResponseWriter, r *http.Request) {
	owner := conversationOwner(r)
	if owner == "" {
		notFound(w, "only a signed-in account keeps conversations")
		return
	}
	row, err := s.ctrl.Store().GetAssistantConversation(r.Context(), owner, chiURLParam(r, "id"))
	if err != nil {
		s.fail(w, r, "reading the conversation", err)
		return
	}
	writeJSON(w, http.StatusOK, conversationView(row))
}

// handleSaveAssistantConversation is both POST (a new one) and PUT (a
// replacement of one of the person's own): the page does not know whether an
// answer is the first it is keeping until it has been told an id.
func (s *Server) handleSaveAssistantConversation(w http.ResponseWriter, r *http.Request) {
	owner := conversationOwner(r)
	if owner == "" {
		forbidden(w, "only a signed-in account can keep conversations")
		return
	}
	var in assistantConversationInput
	if !decode(w, r, &in) {
		return
	}
	messages, err := controller.ValidateAssistantTranscript(in.Messages)
	var invalid *controller.AssistantChatInvalid
	if errors.As(err, &invalid) {
		unprocessable(w, invalid.Message, []fieldError{{invalid.Field, invalid.Message}})
		return
	}
	// Nothing is kept that was not already shown to a model: the same hiding
	// the chat applies, so a token pasted into a question is not in the
	// database either.
	for i := range messages {
		messages[i].Content, _ = redact.Text(messages[i].Content)
	}
	title := strings.TrimSpace(in.Title)
	if title == "" {
		for _, m := range messages {
			if m.Role == "user" {
				title = m.Content
				break
			}
		}
	}
	title, _ = redact.Text(title)
	if r := []rune(title); len(r) > assistantConversationTitleRunes {
		title = string(r[:assistantConversationTitleRunes-1]) + "\u2026"
	}
	if !utf8.ValidString(title) {
		unprocessable(w, "the title must be text", []fieldError{{"title", "must be text"}})
		return
	}
	raw, err := json.Marshal(messages)
	if err != nil {
		s.internal(w, r, "encoding the conversation", err)
		return
	}
	row := &store.AssistantConversation{ID: chiURLParam(r, "id"), UserID: owner, Title: title, Messages: raw, MessageCount: len(messages)}
	if err := s.ctrl.Store().SaveAssistantConversation(r.Context(), row); err != nil {
		s.fail(w, r, "keeping the conversation", err)
		return
	}
	status := http.StatusOK
	if r.Method == http.MethodPost {
		status = http.StatusCreated
	}
	writeJSON(w, status, conversationView(row))
}

func (s *Server) handleDeleteAssistantConversation(w http.ResponseWriter, r *http.Request) {
	owner := conversationOwner(r)
	if owner == "" {
		notFound(w, "only a signed-in account keeps conversations")
		return
	}
	if err := s.ctrl.Store().DeleteAssistantConversation(r.Context(), owner, chiURLParam(r, "id")); err != nil {
		s.fail(w, r, "removing the conversation", err)
		return
	}
	noContent(w)
}

