func TestPersonalProvidersCannotBeUsedOrChangedByAnotherAccount(t *testing.T) {
	h := newHarness(t, func(c *config.Config) { c.Assistant.AllowPrivateProvider = true })
	_, alice := h.user("alice", store.RoleViewer)
	_, bob := h.user("bob", store.RoleAdmin)
	srv := assistanttest.NewOpenAI(t)
	base := "/api/v1/assistant/personal/providers"
	create := h.do(request{method: "POST", path: base, cookie: alice, body: providerBody(srv, "My model")})
	create.mustStatus(t, 201, "viewer creating own provider")
	id := create.json(t)["id"].(string)
	for _, tc := range []struct {
		method, path string
		body         any
	}{
		{"GET", base + "/" + id, nil}, {"PATCH", base + "/" + id, map[string]any{"enabled": false}},
		{"DELETE", base + "/" + id, map[string]any{"name": "My model"}}, {"POST", base + "/" + id + "/check", nil}, {"POST", base + "/" + id + "/default", nil},
		{"POST", base + "/check", map[string]any{"id": id}}, {"POST", base + "/models", map[string]any{"id": id}},
	} {
		h.do(request{method: tc.method, path: tc.path, cookie: bob, body: tc.body}).mustStatus(t, http.StatusNotFound, "another account cannot access provider")
	}
	h.do(request{method: "GET", path: assistantProviders + "/" + id, cookie: bob}).mustStatus(t, 404, "installation admin cannot read personal provider")
	list := h.do(request{method: "GET", path: base, cookie: bob}).json(t)
	if len(list["items"].([]any)) != 0 {
		t.Fatal("another account's provider listed")
	}
	h.do(request{method: "POST", path: "/api/v1/assistant/personal/chat", cookie: bob, body: map[string]any{"provider_id": id, "messages": []map[string]string{{"role": "user", "content": "hello"}}}}).mustStatus(t, 409, "another account cannot charge provider")
	h.do(request{method: "GET", path: base, token: h.token("unowned", store.RoleAdmin, "*")}).mustStatus(t, 403, "unowned token")
}
func TestPersonalProviderDefaultsDoNotChangeInstallationDefaults(t *testing.T) {
	h, admin := assistantAdmin(t, func(c *config.Config) { c.Assistant.AllowPrivateProvider = true })
	_, viewer := h.user("viewer", store.RoleViewer)
	srv := assistanttest.NewOpenAI(t)
	shared := h.do(request{method: "POST", path: assistantProviders, cookie: admin, body: providerBody(srv, "Same name")}).json(t)
	ownBase := "/api/v1/assistant/personal/providers"
	own := h.do(request{method: "POST", path: ownBase, cookie: viewer, body: providerBody(srv, "Same name")})
	own.mustStatus(t, 201, "same name across owners")
	for _, entry := range []struct{ base, id, cookie string }{{assistantProviders, shared["id"].(string), admin}, {ownBase, own.json(t)["id"].(string), viewer}} {
		h.do(request{method: "POST", path: entry.base + "/" + entry.id + "/default", cookie: entry.cookie}).mustStatus(t, 200, "set independent default")
	}
	row, _ := h.st.GetAssistantProvider(h.ctx, shared["id"].(string))
	if !row.IsDefault {
		t.Fatal("personal default cleared installation default")
	}
}

func TestOnlyThePersonalProviderOwnerCanConfirmTheirGitHubLink(t *testing.T) {
	h := newHarness(t)
	owner, cookie := h.user("owner", store.RoleViewer)
	_, admin := h.user("admin", store.RoleAdmin)
	if e := h.st.SetEliIdentity(h.ctx, store.EliIdentity{UserID: owner.ID, GitHubUserID: 42, GitHubLogin: "octo"}); e != nil {
		t.Fatal(e)
	}
	path := "/api/v1/assistant/repairs/consent"
	h.do(request{method: "PUT", path: path, cookie: admin, body: map[string]any{"github_user_id": 42, "enabled": true, "user_id": owner.ID}}).mustStatus(t, 400, "cannot choose another owner in the body")
	h.do(request{method: "PUT", path: path, cookie: admin, body: map[string]any{"github_user_id": 42, "enabled": true}}).mustStatus(t, 404, "administrator cannot confirm on behalf of another user")
	h.do(request{method: "PUT", path: path, cookie: cookie, body: map[string]any{"github_user_id": 43, "enabled": true}}).mustStatus(t, 404, "stale link")
	h.do(request{method: "PUT", path: path, cookie: cookie, body: map[string]any{"github_user_id": 42, "enabled": true}}).mustStatus(t, 204, "own link")
	h.do(request{method: "PUT", path: path, cookie: cookie, body: map[string]any{"github_user_id": 42, "enabled": false}}).mustStatus(t, 204, "revoke own link")
	rows, _ := h.st.EliIdentities(h.ctx)
	if rows[0].Confirmed {
		t.Fatal("consent not revoked")
	}
}

func TestPersonalProviderDraftsCannotRunControllerSubscriptionToolsForAViewer(t *testing.T) {
	h := newHarness(t)
	_, viewer := h.user("viewer", store.RoleViewer)
	for _, path := range []string{"/api/v1/assistant/personal/providers/check", "/api/v1/assistant/personal/providers/models"} {
		for _, kind := range []string{"claude_code", "codex", "copilot"} {
			h.do(request{method: "POST", path: path, cookie: viewer, body: map[string]any{"name": "My plan", "kind": kind}}).mustStatus(t, 422, "controller credentials stay behind administrator permission")
		}
	}
}

func TestAnOwnedViewerTokenCannotRunItsAdministratorsSubscriptionTool(t *testing.T) {
	h := newHarness(t)
	owner, _ := h.user("owner", store.RoleAdmin)
	p := &store.AssistantProvider{Name: "Own subscription", Kind: "claude_code", Model: "sonnet", OwnerID: owner.ID, Enabled: true}
	if err := h.st.CreateAssistantProvider(h.ctx, p); err != nil {
		t.Fatal(err)
	}
	h.st.SetDefaultAssistantProvider(h.ctx, p.ID)
	_, token, err := h.ctrl.Auth().CreateAPIToken(h.ctx, auth.NewToken{Name: "restricted", Role: store.RoleViewer, UserID: owner.ID, Scopes: []string{"*"}})
	if err != nil {
		t.Fatal(err)
	}
	h.do(request{method: "POST", path: "/api/v1/assistant/personal/chat", token: token, body: map[string]any{"messages": []map[string]string{{"role": "user", "content": "hello"}}}}).mustStatus(t, 403, "token role applies to subscription tools")
}

package api

import (
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// subscriptionTool is one of the tools besides Claude Code that a person's own
// subscription is used through, with a stand-in for it.
type subscriptionTool struct {
	kind, name, bin string
	// script is the stand-in: signed in or not, and answering with "Hello from <tool>".
	script func(signedIn bool) string
}

var subscriptionTools = []subscriptionTool{
	{"codex", "Codex", "codex", func(signedIn bool) string {
		status := `echo "Logged in using ChatGPT"; exit 0`
		if !signedIn {
			status = `echo "Not logged in"; exit 1`
		}
		return `#!/bin/sh
case "$1" in
  --version) echo "codex-cli 0.99.0"; exit 0 ;;
  login) ` + status + ` ;;
esac
cat > /dev/null
echo '{"type":"item.completed","item":{"type":"command_execution","command":"ls"}}'
echo '{"type":"item.completed","item":{"type":"agent_message","text":"Hello from Codex"}}'
echo '{"type":"turn.completed","usage":{"input_tokens":9,"output_tokens":4}}'
`
	}},
	{"copilot", "GitHub Copilot", "copilot", func(signedIn bool) string {
		ask := `printf 'Hello from Copilot'`
		if !signedIn {
			ask = `echo "not logged in" >&2; exit 1`
		}
		return `#!/bin/sh
case "$1" in
  version) echo "GitHub Copilot CLI 1.2.3"; exit 0 ;;
esac
` + ask + "\n"
	}},
}

func (tl subscriptionTool) install(t *testing.T, signedIn bool) {
	t.Helper()
	dir := t.TempDir()
	if err := os.WriteFile(filepath.Join(dir, tl.bin), []byte(tl.script(signedIn)), 0o755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", dir+string(os.PathListSeparator)+os.Getenv("PATH"))
}

func (tl subscriptionTool) body(name string) map[string]any {
	return map[string]any{"name": name, "kind": tl.kind}
}

// Codex and Copilot are somebody's own subscription like Claude Code: nothing to
// type but a name, no address, no key and no fleet, and the model is left to the
// tool when none is named, which a model API's provider cannot do.
func TestCodexAndCopilotAreSubscriptionsWithNoAddressNoKeyAndNoFleetAccess(t *testing.T) {
	for _, tl := range subscriptionTools {
		t.Run(tl.kind, func(t *testing.T) {
			tl.install(t, true)
			h := newHarness(t, func(c *config.Config) { c.Assistant.AllowPrivateProvider = true })
			_, alice := h.user("alice", store.RoleAdmin)
			for field, extra := range map[string]map[string]any{
				"base_url":     {"base_url": "https://example.test"},
				"api_key":      {"api_key": "sk-a-key-it-must-not-hold"},
				"fleet_access": {"fleet_access": true},
			} {
				b := tl.body(tl.name)
				for k, v := range extra {
					b[k] = v
				}
				resp := h.do(request{method: http.MethodPost, path: assistantProviders, cookie: alice, body: b})
				resp.mustStatus(t, http.StatusUnprocessableEntity, tl.kind+" with a "+field)
				if !strings.Contains(string(resp.body), `"`+field+`"`) || strings.Contains(string(resp.body), "a-key-it-must-not-hold") {
					t.Errorf("the refusal for %s: %s", field, resp.body)
				}
			}
			resp := h.do(request{method: http.MethodPost, path: assistantProviders, cookie: alice, body: tl.body(tl.name)})
			resp.mustStatus(t, http.StatusCreated, "adding it with no model")
			v := resp.json(t)
			if v["subscription"] != true || v["owned_by_you"] != true || v["usable"] != true || v["model"] != "" {
				t.Errorf("view = %v", v)
			}
			// A provider that is a model API still has to name its model.
			srvBody := map[string]any{"name": "Local", "kind": "openai_compatible", "base_url": "http://localhost:11434/v1"}
			resp = h.do(request{method: http.MethodPost, path: assistantProviders, cookie: alice, body: srvBody})
			resp.mustStatus(t, http.StatusUnprocessableEntity, "a model API with no model")
			if !strings.Contains(string(resp.body), `"model"`) {
				t.Errorf("the refusal does not name the model: %s", resp.body)
			}
		})
	}
}

// Each is its owner's alone, as Claude Code is.
func TestCodexAndCopilotBelongToWhoAddedThem(t *testing.T) {
	for _, tl := range subscriptionTools {
		t.Run(tl.kind, func(t *testing.T) {
			tl.install(t, true)
			h := newHarness(t, func(c *config.Config) { c.Assistant.AllowPrivateProvider = true })
			_, alice := h.user("alice", store.RoleAdmin)
			_, bob := h.user("bob", store.RoleAdmin)
			resp := h.do(request{method: http.MethodPost, path: assistantProviders, cookie: alice, body: tl.body("Alice's " + tl.name)})
			resp.mustStatus(t, http.StatusCreated, "adding it")
			id := resp.json(t)["id"].(string)
			path := assistantProviders + "/" + id
			for name, req := range map[string]request{
				"test it":         {method: http.MethodPost, path: path + "/check", body: map[string]any{}},
				"make it default": {method: http.MethodPost, path: path + "/default", body: map[string]any{}},
				"chat through it": {method: http.MethodPost, path: assistantChat, body: map[string]any{"provider_id": id, "messages": []map[string]string{{"role": "user", "content": "hi"}}}},
			} {
				req.cookie = bob
				r := h.do(req)
				r.mustStatus(t, http.StatusForbidden, "bob trying to "+name)
				if !strings.Contains(string(r.body), "assistant.provider_not_yours") {
					t.Errorf("bob trying to %s: %s", name, r.body)
				}
			}
			h.do(request{method: http.MethodPost, path: path + "/check", cookie: alice, body: map[string]any{}}).
				mustStatus(t, http.StatusOK, "alice testing it")
		})
	}
}

// Eli answers through the owner's tool and says so in the audit log, with the tool's
// own default model named as such, and the fleet is not offered.
func TestEliAnswersThroughTheOwnersCodexOrCopilot(t *testing.T) {
	for _, tl := range subscriptionTools {
		t.Run(tl.kind, func(t *testing.T) {
			tl.install(t, true)
			h := newHarness(t)
			_, alice := h.user("alice", store.RoleAdmin)
			resp := h.do(request{method: http.MethodPost, path: assistantProviders, cookie: alice, body: tl.body("Alice's " + tl.name)})
			resp.mustStatus(t, http.StatusCreated, "adding it")
			id := resp.json(t)["id"].(string)
			h.do(request{method: http.MethodPost, path: assistantProviders + "/" + id + "/default", cookie: alice, body: map[string]any{}}).
				mustStatus(t, http.StatusOK, "making it the default")
			resp = h.do(request{method: http.MethodPost, path: assistantChat, cookie: alice, readStream: true, body: chatBody("user", "What is a runner?")})
			resp.mustStatus(t, http.StatusOK, "asking")
			var text string
			var done map[string]any
			for _, f := range frames(t, resp.body) {
				switch f.kind {
				case "delta":
					text += f.data["text"].(string)
				case "done":
					done = f.data
				case "error":
					t.Fatalf("the answer failed: %v", f.data)
				}
			}
			if text != "Hello from "+strings.TrimPrefix(tl.name, "GitHub ") || done["provider"] != "Alice's "+tl.name ||
				done["model"] != "its default model" || done["fleet_access"] != false {
				t.Errorf("text = %q, done = %v", text, done)
			}
			rows, _, _ := h.st.ListAudit(h.ctx, store.AuditFilter{Actions: []string{"assistant.chat"}}, store.Page{Limit: 5})
			if len(rows) != 1 || !strings.Contains(rows[0].After, `"fleet_access":false`) {
				t.Errorf("audit rows = %+v", rows)
			}
		})
	}
}

// Testing says who is not signed in, and Codex signed in with an API key is turned
// away, because that is not the plan; Local models only refuses both.
func TestTestingCodexAndCopilotSaysWhatIsWrong(t *testing.T) {
	for _, tl := range subscriptionTools {
		t.Run(tl.kind+" not signed in", func(t *testing.T) {
			tl.install(t, false)
			h := newHarness(t)
			_, alice := h.user("alice", store.RoleAdmin)
			resp := h.do(request{method: http.MethodPost, path: assistantProviders, cookie: alice, body: tl.body(tl.name)})
			id := resp.json(t)["id"].(string)
			resp = h.do(request{method: http.MethodPost, path: assistantProviders + "/" + id + "/check", cookie: alice, body: map[string]any{}})
			resp.mustStatus(t, http.StatusOK, "testing it")
			if v := resp.json(t); v["ok"] != false || !strings.Contains(v["error"].(string), "nobody is signed in") {
				t.Errorf("check = %v", v)
			}
		})
		t.Run(tl.kind+" local only", func(t *testing.T) {
			tl.install(t, true)
			h := newHarness(t, func(c *config.Config) { c.Assistant.LocalOnly = true })
			_, alice := h.user("alice", store.RoleAdmin)
			resp := h.do(request{method: http.MethodPost, path: assistantProviders, cookie: alice, body: tl.body(tl.name)})
			id := resp.json(t)["id"].(string)
			resp = h.do(request{method: http.MethodPost, path: assistantProviders + "/" + id + "/check", cookie: alice, body: map[string]any{}})
			resp.mustStatus(t, http.StatusOK, "testing it")
			if v := resp.json(t); v["ok"] != false || !strings.Contains(v["error"].(string), "Local models only") {
				t.Errorf("check = %v", v)
			}
		})
	}
}

package api

import (
	"net/http"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/assistant/assistanttest"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

const assistantProviders = "/api/v1/assistant/providers"

func assistantAdmin(t *testing.T, opts ...func(*config.Config)) (*harness, string) {
	t.Helper()
	h := newHarness(t, opts...)
	_, cookie := h.user("alice", store.RoleAdmin)
	return h, cookie
}

func providerBody(srv *assistanttest.Server, name string) map[string]any {
	return map[string]any{"name": name, "kind": "openai_compatible", "base_url": srv.URL + "/v1", "model": "m", "api_key": "sk-test"}
}

// Which model answers, and with what key, is an administrator's decision
// until the step-up slice makes it cost more than an admin cookie. The kinds
// are admin's too: only the page that adds a provider asks for them, and the
// rail locks that page from its own table.
func TestAssistantProvidersAreAdminOnly(t *testing.T) {
	h := newHarness(t, func(c *config.Config) { c.Assistant.AllowPrivateProvider = true })
	srv := assistanttest.NewOpenAI(t)
	for _, role := range []store.Role{store.RoleViewer, store.RoleOperator} {
		_, cookie := h.user("user-"+string(role), role)
		h.do(request{method: http.MethodGet, path: assistantProviders, cookie: cookie}).mustStatus(t, http.StatusForbidden, string(role)+" listing")
		h.do(request{method: http.MethodPost, path: assistantProviders, cookie: cookie, body: providerBody(srv, "x")}).mustStatus(t, http.StatusForbidden, string(role)+" creating")
		h.do(request{method: http.MethodGet, path: assistantProviders + "/kinds", cookie: cookie}).mustStatus(t, http.StatusForbidden, string(role)+" reading the kinds")
	}
}

func TestCreatingAProviderSealsTheKeyAndNeverReturnsIt(t *testing.T) {
	h, cookie := assistantAdmin(t, func(c *config.Config) { c.Assistant.AllowPrivateProvider = true })
	srv := assistanttest.NewOpenAI(t)
	resp := h.do(request{method: http.MethodPost, path: assistantProviders, cookie: cookie, body: providerBody(srv, "Ollama")})
	resp.mustStatus(t, http.StatusCreated, "creating")
	if strings.Contains(string(resp.body), "sk-test") {
		t.Fatalf("the key is in the response: %s", resp.body)
	}
	view := resp.json(t)
	if view["key_configured"] != true || view["name"] != "Ollama" || view["kind"] != "openai_compatible" || view["local"] != true {
		t.Errorf("view %v", view)
	}
	row, err := h.st.GetAssistantProvider(h.ctx, view["id"].(string))
	if err != nil {
		t.Fatal(err)
	}
	if key, err := h.key.OpenString(row.KeyEnc); err != nil || key != "sk-test" {
		t.Errorf("sealed key opens to %q, %v", key, err)
	}
	list := h.do(request{method: http.MethodGet, path: assistantProviders, cookie: cookie})
	list.mustStatus(t, http.StatusOK, "listing")
	if strings.Contains(string(list.body), "sk-test") {
		t.Errorf("the key is in the list: %s", list.body)
	}
}

func TestAPrivateBaseURLIsRefusedUntilTheAssistantSwitchIsOn(t *testing.T) {
	h, cookie := assistantAdmin(t)
	srv := assistanttest.NewOpenAI(t)
	resp := h.do(request{method: http.MethodPost, path: assistantProviders, cookie: cookie, body: providerBody(srv, "Ollama")})
	resp.mustStatus(t, http.StatusUnprocessableEntity, "a loopback address with the switch off")
	if body := string(resp.body); !strings.Contains(body, "assistant.allow_private_provider") || !strings.Contains(body, `"base_url"`) {
		t.Errorf("the refusal does not name the switch and the field: %s", body)
	}
	h2, cookie2 := assistantAdmin(t, func(c *config.Config) { c.Assistant.AllowPrivateProvider = true })
