func validComparisonID(id string) bool {
	return strings.HasPrefix(id, store.PrefixComparison+"_") && len(id) <= 128 && !strings.ContainsAny(id, " /\r\n\x00")
}

func validPreviewID(id string) bool {
	return strings.HasPrefix(id, store.PrefixOptimisationPreview+"_") && len(id) <= 128 && !strings.ContainsAny(id, " /\r\n\x00")
}

func validDigest(s string, n int) bool {
	if len(s) != n || s != strings.ToLower(s) {
		return false
	}
	_, err := hex.DecodeString(s)
	return err == nil
}

func (s *Server) optimisationError(w http.ResponseWriter, r *http.Request, err error) {
	var admission *controller.PRDelayAdmissionError
	var shardingRefusal *optimisation.ShardingRefusal
	switch {
	case errors.Is(err, controller.ErrOptimisationPolicy):
		forbidden(w, "Reviewed workflow optimisations are off. An administrator turns on optimisation.source_reads and optimisation.workflow_edits in Settings.")
	case errors.Is(err, controller.ErrOptimisationPublishPermission):
		forbidden(w, "The installation cannot open a draft pull request. "+github.OptimisationPublishPermissionHint)
	case errors.Is(err, controller.ErrOptimisationPublishPolicy):
		forbidden(w, "Publishing an optimisation draft is off. An administrator turns on optimisation.source_reads, optimisation.workflow_edits and optimisation.publish in Settings.")
	case errors.Is(err, controller.ErrOptimisationNotApproved):
		conflict(w, "Approve this preview before publishing it.")
	case errors.Is(err, controller.ErrOptimisationApproval):
		conflict(w, "The commit and source digest do not match this retained preview. Open it again and approve exactly what it shows.")
	case errors.Is(err, controller.ErrOptimisationShardingApproval):
		conflict(w, "The commit and source digest do not match this retained sharding preview. Open it again and approve exactly what it shows.")
	case errors.Is(err, controller.ErrOptimisationReadinessApproval):
		conflict(w, "The commit and source digest do not match this retained readiness preview. Open it again and approve exactly what it shows.")
	case errors.Is(err, controller.ErrOptimisationCacheApproval):
		conflict(w, "The commit and source digest do not match this retained cache preview. Open it again and approve exactly what it shows.")
	case errors.Is(err, github.ErrSetupCacheNotFound):
		conflict(w, "No supported root lockfile was found at the selected commit. Cache previews need package-lock.json, npm-shrinkwrap.json, yarn.lock or pnpm-lock.yaml at the repository root.")
	case errors.Is(err, github.ErrSetupCacheAmbiguous):
		conflict(w, "More than one supported root lockfile was found at the selected commit. Remove or rename the extra lockfile before previewing a cache change.")
	case errors.Is(err, github.ErrSetupCacheChanged):
		conflict(w, "The attempt changed while its source was read. Try the preview again.")
	case errors.Is(err, controller.ErrOptimisationCache):
		conflict(w, "This cache preview cannot be computed from the selected job. It needs a successful push job the fleet ran, one pinned actions/setup-node step with literal job and step names, one root lockfile, and at least two matching setup timings from the last ninety days.")
	case errors.As(err, &shardingRefusal):
		conflict(w, "This job cannot be sharded: "+shardingRefusal.Reason+".")
	case errors.Is(err, optimisation.ErrShardingUnsupported), errors.Is(err, controller.ErrOptimisationSharding):
		conflict(w, "This sharding preview cannot be computed from the selected job. It needs a successful push job the fleet ran, one Playwright test step on an Ubuntu runner, at least ten matching successful runs from the last ninety days, and a pool that could start at least two runners at once.")
	case errors.Is(err, controller.ErrOptimisationReadiness):
		conflict(w, "This readiness preview cannot be computed from the selected job. It needs a successful push job the fleet ran, one literal sleep step on an Ubuntu runner, an operator-supplied readiness command, and at least two matching wait timings from the last ninety days.")
	case errors.Is(err, controller.ErrOptimisationPublish):
		conflict(w, err.Error())
	case errors.Is(err, controller.ErrOptimisationVerification):
		conflict(w, err.Error())
	case errors.Is(err, store.ErrConflict):
		conflict(w, "This preview already carries a different approval or no longer matches its retained evidence. Open it again before approving.")
	case errors.As(err, &admission):
		rateLimited(w, err.Error(), admission.RetryAfter.Truncate(time.Second)+time.Second)
	case errors.Is(err, github.ErrRateLimited):
		rateLimited(w, "The GitHub installation is holding diagnostic reads. Try again later.", time.Minute)
	case errors.Is(err, github.ErrForbidden):
		forbidden(w, "The installation cannot read this repository's contents or Actions metadata; check the App's Contents and Actions read permissions.")
	case errors.Is(err, store.ErrNotFound):
		notFound(w, "The preview or installation is unavailable; a preview is kept for fourteen days and the oldest are evicted first.")
	case errors.Is(err, github.ErrCheckoutNotFound):
		conflict(w, "That job has no checkout step that can be previewed. It needs a commit-pinned actions/checkout with a literal fetch-depth: 0, in a job with a literal name, and the same line must not appear twice in the file.")
	case errors.Is(err, github.ErrCheckoutAmbiguous):
		conflict(w, "That job has more than one checkout step that could be previewed, and Zoomies will not guess which. Choose a job with a single full-history checkout.")
	case errors.Is(err, controller.ErrOptimisationPreview):
		conflict(w, "This step cannot be previewed. It needs a successful run on a push commit, a root workflow file with literal job and step names, a commit-pinned actions/checkout with fetch-depth: 0, and a source that has not changed since you reviewed it.")
	case errors.Is(err, context.DeadlineExceeded):
		conflict(w, "Reading the workflow exceeded its time limit. Try again later.")
	default:
		s.fail(w, r, "processing a checkout preview", err)
	}
}

// OptimisationEnablement is whether this instance lets Zoomies read workflow
// source and keep a proposed edit, and whether the caller can change that. The
// two settings are separate grants in the registry; the page asks for them
// together because one is no use without the other, and says so in words.
type OptimisationEnablement struct {
	SourceReads    bool   `json:"source_reads"`
	WorkflowEdits  bool   `json:"workflow_edits"`
	Publish        bool   `json:"publish"`
	Enabled        bool   `json:"enabled"`
	PublishEnabled bool   `json:"publish_enabled"`
	CanChange      bool   `json:"can_change"`
	CanPublish     bool   `json:"can_publish"`
	Reason         string `json:"reason,omitempty"`
	PublishReason  string `json:"publish_reason,omitempty"`
}

type OptimisationEnablementRequest struct {
	Enabled *bool `json:"enabled"`
	Publish *bool `json:"publish"`
}

const optimisationSourceKey, optimisationEditsKey, optimisationPublishKey = "optimisation.source_reads", "optimisation.workflow_edits", "optimisation.publish"

func (s *Server) optimisationEnablement(r *http.Request) OptimisationEnablement {
	cfg := s.cfg()
	out := OptimisationEnablement{SourceReads: cfg.Optimisation.SourceReads, WorkflowEdits: cfg.Optimisation.WorkflowEdits, Publish: cfg.Optimisation.Publish, CanChange: true, CanPublish: true}
	out.Enabled = out.SourceReads && out.WorkflowEdits
	out.PublishEnabled = out.Enabled && out.Publish
	role := callerRole(r)
	if !role.AtLeast(store.RoleAdmin) {
		out.CanChange, out.CanPublish = false, false
		out.Reason = "Only an administrator can turn this on. Ask one to press the button on this page, or to switch on optimisation.source_reads and optimisation.workflow_edits in Settings."
		out.PublishReason = "Only an administrator can turn this on. Ask one to press the button on this page, or to switch on optimisation.source_reads, optimisation.workflow_edits and optimisation.publish in Settings."
		return out
	}
	for _, key := range []string{optimisationSourceKey, optimisationEditsKey} {
		st, ok := config.LookupSetting(key)
		if !ok {
			continue
		}
		if editable, reason := s.editable(st, cfg, role); !editable {
			out.CanChange, out.Reason = false, reason
			break
		}
	}
	for _, key := range []string{optimisationSourceKey, optimisationEditsKey, optimisationPublishKey} {
		st, ok := config.LookupSetting(key)
		if !ok {
			continue
		}
		if editable, reason := s.editable(st, cfg, role); !editable {
			out.CanPublish, out.PublishReason = false, reason
			break
		}
	}
	return out
}

func (s *Server) handleGetOptimisationEnablement(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Cache-Control", "no-store")
	writeJSON(w, http.StatusOK, s.optimisationEnablement(r))
}

// handleSetOptimisationEnablement is the settings write, narrowed to the one
// question this page asks. It plans and applies through the same path as
// PATCH /settings, so the environment lock, validation and audit row are the
// settings page's own, and a change is live for the very next request.
func (s *Server) handleSetOptimisationEnablement(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Cache-Control", "no-store")
	var in OptimisationEnablementRequest
	if !decodeOptimisationBody(w, r, &in) {
		return
	}
	if in.Enabled == nil && in.Publish == nil {
		badRequest(w, "Say whether to turn workflow previews or publishing on or off with enabled or publish: true or false.")
		return
	}
	current := s.cfg()
	flat := map[string]any{}
	if in.Enabled != nil {
		flat[optimisationSourceKey], flat[optimisationEditsKey] = *in.Enabled, *in.Enabled
	}
	if in.Publish != nil {
		flat[optimisationPublishKey] = *in.Publish
		// Publication is no use without the two preview grants, so its press
		// turns them on too. Turning it off leaves them where they are.
		if *in.Publish {
			flat[optimisationSourceKey], flat[optimisationEditsKey] = true, true
		}
	}
	candidate, staged, fields := s.planSettings(current, flat, callerRole(r))
	if len(fields) > 0 {
		unprocessable(w, "these settings could not be changed", fields)
		return
	}
	if len(staged) > 0 {
		if fields := validatePlan(current, candidate, staged); len(fields) > 0 {
			unprocessable(w, "that would leave a controller that will not start", fields)
			return
		}
		if err := s.applyPlan(r.Context(), Identity(r.Context()), staged); err != nil {
			s.internal(w, r, "storing the optimisation settings", err)
			return
		}
	}
	writeJSON(w, http.StatusOK, s.optimisationEnablement(r))
}

package api

import (
	"net/http"
	"time"

	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/store"
)

// defaultStatsWindow matches the OpenAPI document's default for ?window=.
const defaultStatsWindow = time.Hour

// handleStats answers the Overview's cards: what the queue is doing, what the
// fleet is doing, and how long jobs are waiting.
//
// controller.Stats is already the response shape -- its JSON tags are the
// Stats schema -- so there is no translation layer here to fall out of step
// with the document.
func (s *Server) handleStats(w http.ResponseWriter, r *http.Request) {
	window, err := queryDuration(r, "window", defaultStatsWindow)
	if err != nil {
		badRequestField(w, "window", err.Error())
		return
	}
	stats, err := s.ctrl.Stats(r.Context(), window)
	if err != nil {
		s.internal(w, r, "computing fleet statistics", err)
		return
	}
	writeJSON(w, http.StatusOK, stats)
}

// handleSamples returns the sparkline points.
//
// `since` wins over `window` when both are given, because a client that names
// an exact instant is resuming a chart it already has and re-sending points it
// has already drawn would make the line jump.
func (s *Server) handleSamples(w http.ResponseWriter, r *http.Request) {
	since, err := queryTime(r, "since")
	if err != nil {
		badRequestField(w, "since", err.Error())
		return
	}
	if since == nil {
		window, werr := queryDuration(r, "window", defaultStatsWindow)
		if werr != nil {
			badRequestField(w, "window", werr.Error())
			return
		}
		t := s.ctrl.Now().Add(-window)
		since = &t
	}

	samples, err := s.ctrl.Samples(r.Context(), *since)
	if err != nil {
		s.internal(w, r, "reading fleet samples", err)
		return
	}
	writeJSON(w, http.StatusOK, newList(samples))
}

// handleProblems answers the UI's problems drawer.
//
// The body is controller.ProblemsView, which is also what a problems.updated
// frame carries, so the drawer cannot see two shapes for the same list.
//
// Which problems are on it depends on who is asking: the process's own
// troubles go to whoever runs the process, and the fleet's to whoever runs
// the fleet. On a single-team instance the one account holds platform and the
// list is undivided, which is what it was before the role existed.
func (s *Server) handleProblems(w http.ResponseWriter, r *http.Request) {
	items, err := s.ctrl.SharedProblems(r.Context())
	if err != nil {
		s.internal(w, r, "gathering the current problems", err)
		return
	}
	writeJSON(w, http.StatusOK, controller.NewProblemsViewFor(items, isPlatform(r)))
}

// handleScalingEvents lists the scheduler's recent decisions, each with the
// sentence that justified it.
func (s *Server) handleScalingEvents(w http.ResponseWriter, r *http.Request) {
	limit := clamp(queryInt(r, "limit", defaultLimit), 1, maxLimit)
	events, err := s.ctrl.Store().ListScalingEvents(r.Context(), r.URL.Query().Get("pool_id"), limit)
	if err != nil {
		s.internal(w, r, "reading the scaling history", err)
		return
	}
	writeJSON(w, http.StatusOK, newList(events))
}

// poolNames indexes pools by ID, which several responses need in order to show
// a name next to an ID.
func poolNames(pools []*store.Pool) map[string]string {
	out := make(map[string]string, len(pools))
	for _, p := range pools {
		out[p.ID] = p.Name
	}
	return out
}

package api

import (
	"net/http"
	"reflect"
	"strings"

	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/store"
)

// autoPoolEditable is the fields of a pool the controller keeps that an operator
// may change. Every other field of poolInput is refused by name, which is the
// right default for one added later: a field nobody has thought about for these
// pools is one the reconciler would put back.
//
// The memory valve is one of them because it is a policy and not a figure worked
// out from the hosts: the reconciler writes no column it lives in, and without
// this the pools most fleets run on would be the ones that could never turn it on.
var autoPoolEditable = map[string]bool{"idle_timeout": true, "auto": true, "enabled": true, "memory_burst": true}

// autoPoolWorkedOut is the refused fields the controller itself sets, from the
// hosts and the class a pool is kept for. They are said to be worked out because
// they are; the others are refused for a different reason, which is that these
// pools are all set up one way, and the sentence for them says that instead.
var autoPoolWorkedOut = map[string]bool{
	"name": true, "installation_id": true, "labels": true, "backend": true, "platform": true,
	"min_runners": true, "max_runners": true, "ephemeral": true, "docker_mode": true,
	"resources": true, "host_selector": true, "size_from_profile": true,
}

// isSet reports whether a field of a request was named. A request names a field
// with a pointer, but a field added later need not be one, and a non-nillable
// kind must not make the check panic -- or, worse, be taken for unnamed.
func isSet(v reflect.Value) bool {
	switch v.Kind() {
	case reflect.Pointer, reflect.Map, reflect.Slice, reflect.Interface, reflect.Func, reflect.Chan:
		return !v.IsNil()
	}
	return !v.IsZero()
}

// refusedForAutoPool lists the fields a request names that are not an operator's
// to change on a pool the controller keeps.
func refusedForAutoPool(in *poolInput) []fieldError {
	v := reflect.ValueOf(in).Elem()
	t := v.Type()
	var errs []fieldError
	for i := 0; i < t.NumField(); i++ {
		name := strings.Split(t.Field(i).Tag.Get("json"), ",")[0]
		if name == "" || name == "-" || !isSet(v.Field(i)) || autoPoolEditable[name] {
			continue
		}
		msg := "the controller sets this pool up and takes no change to this; its idle timeout, warm runners, cap, pause and memory valve are the settings that are yours. To change anything else, make a pool of your own."
		switch {
		case name == "min_runners" || name == "max_runners":
			msg = "this pool's minimum and maximum are worked out from the hosts in it; ask for runners to keep ready with auto.warm and for a ceiling with auto.cap"
		case autoPoolWorkedOut[name]:
			msg = "this pool is kept by the controller from your hosts, so this is worked out and not typed; its idle timeout, warm runners, cap, pause and memory valve are the settings that are yours. To change anything else, make a pool of your own."
		}
		errs = append(errs, fieldError{name, msg})
	}
	return errs
}

// updateAutoPool is PATCH /pools/{id} for a pool the controller keeps.
//
// The operator's side is stored beside what the controller derives, and a pass of
// the reconciler is run before answering, so that a pause or a cap has taken
// effect in the response and not only on the next tick. The pool is not run
// through the validation a pool somebody made is: a pool whose last host has gone
// has a maximum of nought, which is right for it and is what that validation
// exists to refuse.
func (s *Server) updateAutoPool(w http.ResponseWriter, r *http.Request, existing *store.Pool, in *poolInput) {
	errs := refusedForAutoPool(in)
	if in.Enabled != nil {
		if in.Auto != nil && in.Auto.Paused != nil {
			errs = append(errs, fieldError{"enabled", "give auto.paused or enabled, not both: enabled false is a pause"})
		} else {
			if in.Auto == nil {
				in.Auto = &autoPoolInput{}
			}
			paused := !*in.Enabled
			in.Auto.Paused = &paused
		}
		in.Enabled = nil
	}
	before := *existing
	updated := *existing
	errs = append(errs, in.apply(&updated)...)
	if in.MemoryBurst != nil {
		validateMemoryBurst(&updated, func(field, msg string) { errs = append(errs, fieldError{field, msg}) })
	}
	if in.Auto != nil {
		if in.Auto.Warm != nil {
			if *in.Auto.Warm < 0 {
				errs = append(errs, fieldError{"auto.warm", "warm runners cannot be negative; use 0 to keep none ready"})
			}
			updated.AutoMin = *in.Auto.Warm
		}
		if in.Auto.Cap != nil {
			if *in.Auto.Cap < 0 {
				errs = append(errs, fieldError{"auto.cap", "a cap cannot be negative; use 0 for none"})
			}
			updated.AutoCap = *in.Auto.Cap
		}
		if in.Auto.Paused != nil {
			updated.AutoPaused = *in.Auto.Paused
			s.pauseNow(&updated, existing.AutoPaused)
		}
	}
	if updated.Ephemeral && updated.AutoMin > 0 && updated.IdleTimeout.Duration() == 0 {
		errs = append(errs, fieldError{"idle_timeout", "warm ephemeral runners with no idle timeout are replaced after every job and never reaped; give an idle timeout, or ask for no warm runners"})
	}
	if len(errs) > 0 {
		unprocessable(w, "this pool cannot be changed as described", errs)
		return
	}
	// What the controller derives is left as it was read; the pass below is what
	// moves it, from the hosts as they are.
	if err := s.ctrl.Store().UpdatePool(r.Context(), &updated); err != nil {
		s.fail(w, r, "saving the pool", err)
		return
	}
	s.auth.Auditor().Updated(r.Context(), Identity(r.Context()), "pool", existing.ID, poolForAudit(&before), poolForAudit(&updated))
	s.finishAutoPoolEdit(w, r, existing.ID)
}

// setAutoPoolPaused is the Enable and Disable buttons for a pool the controller
// keeps: an operator's pause, which the controller honours whatever its hosts do.
func (s *Server) setAutoPoolPaused(w http.ResponseWriter, r *http.Request, p *store.Pool, paused bool) {
	if p.AutoPaused != paused {
		before := *p
		p.AutoPaused = paused
		s.pauseNow(p, before.AutoPaused)
		if err := s.ctrl.Store().UpdatePool(r.Context(), p); err != nil {
			s.fail(w, r, "saving the pool", err)
			return
		}
		action := "pool.enable"
		if paused {
			action = "pool.disable"
		}
		s.auth.Auditor().Act(r.Context(), Identity(r.Context()), action, "pool", p.ID, map[string]any{
			"name": p.Name, "paused": paused, "was": before.AutoPaused,
		})
	}
	s.finishAutoPoolEdit(w, r, p.ID)
}

// pauseNow makes a pause, or the end of one, take effect at once for a pool the
// controller is not keeping.
//
// For a pool it keeps, the reconciler turns the pause into a pool that is out of
// use, and the pass the edit runs does it before the response. For one it is not
// keeping -- the switch is off or only watching -- no pass will, so the pool would
// go on taking work for as long as it stayed "paused", and the operator was told
// it was saved. was is the pause as it stood before the edit; a request that does
// not change it leaves the pool's own switch as it was.
func (s *Server) pauseNow(p *store.Pool, was bool) {
	if p.AutoPaused == was || s.ctrl.AutoPoolKept(p) {
		return
	}
	// Resuming puts back what the pool had, which is in use only if it has room
	// for a runner: a leftover whose last host went has none.
	p.Enabled = !p.AutoPaused && p.MaxRunners > 0
}

// finishAutoPoolEdit runs a pass of the reconciler so the operator's change has
// taken effect, then answers with the pool as it now is.
func (s *Server) finishAutoPoolEdit(w http.ResponseWriter, r *http.Request, id string) {
	if err := s.ctrl.ReconcileAutoPools(r.Context()); err != nil {
		// The edit is saved and the controller's next pass applies it.
		s.logger(r).Warn("a pool the controller keeps was edited but the pass that applies it failed", "pool", id, "error", err)
	}
	fresh, err := s.ctrl.Store().GetPool(r.Context(), id)
	if err != nil {
		s.fail(w, r, "reading the pool back", err)
		return
	}
	s.ctrl.PublishPool(r.Context(), events.KindPoolUpdated, fresh)
	s.ctrl.Nudge()
	view, err := s.ctrl.PoolRenderer(r.Context())
	if err != nil {
		s.internal(w, r, "reading the pool back", err)
		return
	}
	writeJSON(w, http.StatusOK, poolFor(r, view.View(fresh)))
}

package api

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"maps"
	"net/http"
	"reflect"
	"slices"
	"sort"
	"strings"
	"time"

	"gopkg.in/yaml.v3"

	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/version"
)

// Moving a fleet's pools between instances, or keeping them in version control.
//
// This is the settings export's other half, built the same way on purpose: a
// versioned document, a plan shown before anything is written, and one change
// or none. What differs is what a pool refers to. A pool belongs to an
// installation, and an installation's ins_ id means nothing on another
// instance, so the document names the installation by the organisation or
// repository it covers -- the one fact that is the same on both sides. And a
// pool's environment is the one place a secret can hide in it, so the
// document carries the variable names and never their values.

// poolsExportVersion is the pools document's own shape number. It moves when
// a field is removed or renamed, not when one is added.
const poolsExportVersion = 1

// poolsExport is the JSON form of a pools export.
type poolsExport struct {
	ExportVersion int       `json:"export_version"`
	ExportedAt    time.Time `json:"exported_at"`
	// ExportedFrom names the instance, so a file found in a repository a year
	// later says where it came from.
	ExportedFrom string         `json:"exported_from,omitempty"`
	Version      string         `json:"version"`
	Pools        []poolDocument `json:"pools"`
}

// poolDocument is one pool as the document carries it: the pool's own
// settings and nothing the instance made up about it -- no id, no counts, no
// timestamps -- because those are what differ between two instances running
// the same pool.
type poolDocument struct {
	Name string `json:"name"`
	// Installation is the organisation ("acme") or repository ("acme/widgets")
	// the pool's installation covers.
	Installation           string               `json:"installation"`
	Labels                 []string             `json:"labels"`
	RunnerGroup            string               `json:"runner_group"`
	Backend                store.BackendKind    `json:"backend"`
	Platform               store.Platform       `json:"platform"`
	Image                  string               `json:"image"`
	PullPolicy             store.PullPolicy     `json:"pull_policy"`
	RunnerVersion          string               `json:"runner_version"`
	DinDImage              string               `json:"dind_image"`
	MinRunners             int                  `json:"min_runners"`
	MaxRunners             int                  `json:"max_runners"`
	RepositoryScaleUpLimit int                  `json:"repository_scale_up_limit"`
	CostPerRunnerHour      *float64             `json:"cost_per_runner_hour"`
	Priority               int                  `json:"priority"`
	IdleTimeout            string               `json:"idle_timeout"`
	Ephemeral              bool                 `json:"ephemeral"`
	DockerMode             store.DockerMode     `json:"docker_mode"`
	Resources              store.Resources      `json:"resources"`
	CPUBurst               store.CPUBurstPolicy `json:"cpu_burst"`
	// MemoryBurst is written like CPUBurst, and for the same reason: a pool
	// that lends memory, imported without it, would be one that did not.
	MemoryBurst store.MemoryBurstPolicy `json:"memory_burst"`
	// RunnerSettings writes every override, with null for one the pool does
	// not make, so that importing the document hands a setting back to the
	// fleet on a pool that overrides it rather than leaving it alone.
	RunnerSettings poolDocumentTimings `json:"runner_settings"`
	Cache          store.CacheConfig   `json:"cache"`
	Tmpfs          store.TmpfsConfig   `json:"tmpfs"`
	HostSelector   map[string]string   `json:"host_selector"`
	// ProviderSelector is the pool's half of its agreement with a provider.
	ProviderSelector map[string]string `json:"provider_selector"`
	// EnvKeys names the variables the pool injects. Their values stay behind:
	// a pool's environment is where a registry password ends up, and a file
	// meant for version control cannot be a place a password ends up.
	EnvKeys   []string `json:"env_keys"`
	RunAsRoot bool     `json:"run_as_root"`
	Enabled   bool     `json:"enabled"`
	// NoDefaultLabels travels with the labels it qualifies: a pool that
	// registers with its own labels only, imported without this, would start
	// answering to self-hosted and linux again on the other instance.
	NoDefaultLabels bool `json:"no_default_labels"`
	// SizeFromProfile travels with the sizes it replaces: a pool that takes its
	// runners' size from each host, imported without this, would be sized by a
	// slot's share of the host instead, which is a different size on every
	// machine the other instance has.
	SizeFromProfile bool `json:"size_from_profile"`
}

type poolDocumentTimings struct {
	ProvisionTimeout  *string `json:"provision_timeout"`
	DrainTimeout      *string `json:"drain_timeout"`
	MaxRunnerLifetime *string `json:"max_runner_lifetime"`
	ScaleUpDelay      *string `json:"scale_up_delay"`
	DockerWait        *string `json:"docker_wait"`
}

func durationText(d *store.Duration) *string {
	if d == nil {
		return nil
	}
	s := d.String()
	return &s
}

// documentPool renders a pool as the document carries it.
func documentPool(p *store.Pool, installation string) poolDocument {
	envKeys := make([]string, 0, len(p.Env))
	for k := range p.Env {
		envKeys = append(envKeys, k)
	}
	sort.Strings(envKeys)
	return poolDocument{
		Name:                   p.Name,
		Installation:           installation,
		Labels:                 emptySlice([]string(p.Labels)),
		RunnerGroup:            p.RunnerGroup,
		Backend:                p.Backend,
		Platform:               p.Platform,
		Image:                  p.Image,
		PullPolicy:             p.PullPolicy,
		RunnerVersion:          p.RunnerVersion,
		DinDImage:              p.DinDImage,
		MinRunners:             p.MinRunners,
		MaxRunners:             p.MaxRunners,
		RepositoryScaleUpLimit: p.RepositoryScaleUpLimit,
		CostPerRunnerHour:      p.CostPerRunnerHour,
		Priority:               p.Priority,
		IdleTimeout:            p.IdleTimeout.String(),
		Ephemeral:              p.Ephemeral,
		DockerMode:             p.DockerMode,
		Resources:              p.Resources,
		CPUBurst:               p.CPUBurst,
		MemoryBurst:            p.MemoryBurst,
		RunnerSettings: poolDocumentTimings{
			ProvisionTimeout:  durationText(p.RunnerSettings.ProvisionTimeout),
			DrainTimeout:      durationText(p.RunnerSettings.DrainTimeout),
			MaxRunnerLifetime: durationText(p.RunnerSettings.MaxRunnerLifetime),
			ScaleUpDelay:      durationText(p.RunnerSettings.ScaleUpDelay),
			DockerWait:        durationText(p.RunnerSettings.DockerWait),
		},
		Cache:            p.Cache,
		Tmpfs:            p.Tmpfs,
		HostSelector:     emptyMap(p.HostSelector),
		ProviderSelector: emptyMap(p.ProviderSelector),
		EnvKeys:          envKeys,
		RunAsRoot:        p.RunAsRoot,
		Enabled:          p.Enabled,
		NoDefaultLabels:  p.NoDefaultLabels,
		SizeFromProfile:  p.SizeFromProfile,
	}
}

// handleExportPools answers GET /api/v1/pools/export.
func (s *Server) handleExportPools(w http.ResponseWriter, r *http.Request) {
	format := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("format")))
	if format == "" {
		format = "json"
	}
	if format != "json" && format != "yaml" {
		badRequestField(w, "format", "the export is written as json or yaml")
		return
	}
	doc, err := s.exportPools(r)
	if err != nil {
		s.internal(w, r, "reading the pools to export", err)
		return
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "pools.export", "pool", "pools", map[string]any{
		"format": format, "pools": len(doc.Pools),
	})

	stamp := doc.ExportedAt.Format("20060102-150405")
	w.Header().Set("Cache-Control", "no-store")
	raw, err := json.MarshalIndent(doc, "", "  ")
	if err != nil {
		s.internal(w, r, "rendering the export", err)
		return
	}
	if format == "yaml" {
		// Through JSON, so the YAML has the field names the API has rather
		// than a second set of tags to keep in step with them.
		var tree map[string]any
		if err := json.Unmarshal(raw, &tree); err != nil {
			s.internal(w, r, "rendering the export", err)
			return
		}
		body, err := yaml.Marshal(map[string]any{"export_version": tree["export_version"], "pools": tree["pools"]})
		if err != nil {
			s.internal(w, r, "rendering the export", err)
			return
		}
		header := fmt.Sprintf("# Zoomies pools, exported %s from %s (Zoomies %s).\n"+
			"# Installations are named by the organisation or repository they cover, so this file can be imported\n"+
			"# on another instance with the same GitHub App installed. Environment values are never in here;\n"+
			"# env_keys names the variables to set by hand. Import it on the Pools page or with zoomies pools import.\n",
			doc.ExportedAt.Format(time.RFC3339), orPhrase(doc.ExportedFrom, "an unnamed instance"), doc.Version)
		w.Header().Set("Content-Type", "application/yaml; charset=utf-8")
		w.Header().Set("Content-Disposition", `attachment; filename="zoomies-pools-`+stamp+`.yaml"`)
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(header))
		_, _ = w.Write(body)
		return
	}
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.Header().Set("Content-Disposition", `attachment; filename="zoomies-pools-`+stamp+`.json"`)
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(append(raw, '\n'))
}

func (s *Server) exportPools(r *http.Request) (poolsExport, error) {
	doc := poolsExport{
		ExportVersion: poolsExportVersion,
		ExportedAt:    s.ctrl.Now(),
		ExportedFrom:  s.cfg().Server.ExternalURL,
		Version:       version.Short(),
		Pools:         []poolDocument{},
	}
	pools, err := s.ctrl.Store().ListPools(r.Context())
	if err != nil {
		return doc, err
	}
	targets, err := s.installationTargets(r)
	if err != nil {
		return doc, err
	}
	for _, p := range pools {
		// A pool the controller keeps is worked out from the hosts it has, which
		// are not the destination's, so exporting it would hand the other instance
		// a pool of somebody's own that the controller there then finds in its way.
		// The destination makes its own from its own hosts.
		if p.FromHosts() {
			continue
		}
		doc.Pools = append(doc.Pools, documentPool(p, targets[p.InstallationID]))
	}
	return doc, nil
}

// installationTargets maps each installation's id to the target a document
// names it by.
func (s *Server) installationTargets(r *http.Request) (map[string]string, error) {
	insts, err := s.ctrl.Store().ListInstallations(r.Context())
	if err != nil {
		return nil, err
	}
	out := make(map[string]string, len(insts))
	for _, i := range insts {
		out[i.ID] = i.Target
	}
	return out, nil
}

// ---------------------------------------------------------------------------
// Import
// ---------------------------------------------------------------------------

// poolsImportRequest is what the page sends: the file's text, whether this
// is only a look, and the pools to leave out.
type poolsImportRequest struct {
	// Document is a pools export, as JSON or YAML text.
	Document string `json:"document"`
	// DryRun plans and reports without writing anything.
	DryRun bool `json:"dry_run"`
	// Skip names pools in the document to ignore -- the ones the preview
	// refused, or the ones the operator unticked.
	Skip []string `json:"skip"`
}

// poolImportField is one setting of one pool that applying would change.
type poolImportField struct {
	Field string `json:"field"`
	// Current is nil for a pool that does not exist yet.
	Current  any `json:"current"`
	Incoming any `json:"incoming"`
}

// poolImportChange is one pool's fate.
type poolImportChange struct {
	Pool string `json:"pool"`
	// Action is what applying would do: create, change, unchanged, or refused.
	Action string `json:"action"`
	// Fields is what differs, setting by setting: every setting for a create,
	// the ones that move for a change, none for the rest.
	Fields []poolImportField `json:"fields"`
	// Reason says why it is refused, in a sentence.
	Reason string `json:"reason,omitempty"`
	// Warnings are things that would not stop the import but that the
	// operator should know before it happens -- chiefly that no host in this
	// fleet could run a pool about to be created.
	Warnings []string `json:"warnings"`
	// EnvKeys names the environment variables the source pool injected, whose
	// values the document could not carry.
	EnvKeys []string `json:"env_keys"`
}

// The actions a planned pool can have.
const (
	poolCreateAction    = "create"
	poolChangeAction    = "change"
	poolUnchangedAction = "unchanged"
	poolRefusedAction   = "refused"
)

type poolsImportResponse struct {
	Applied bool               `json:"applied"`
	Changes []poolImportChange `json:"changes"`
	Summary poolsImportSummary `json:"summary"`
}

type poolsImportSummary struct {
	Create    int `json:"create"`
	Change    int `json:"change"`
	Unchanged int `json:"unchanged"`
	Refused   int `json:"refused"`
	Skipped   int `json:"skipped"`
}

// The document fields an import reads for itself rather than as a pool
// setting, or ignores: an id and an installation id belong to the instance
// that wrote them, and env is never read, because a document that could set
// an environment could be carrying a credential into a file.
var poolDocumentOwnFields = []string{"installation", "installation_id", "id", "env", "env_keys"}

// plannedPool is one pool the import would write.
type plannedPool struct {
	before *store.Pool // nil for a create
	after  *store.Pool
}

// handleImportPools answers POST /api/v1/pools/import.
//
// A dry run plans and reports; a real run refuses the whole document while
// any pool in it is refused, as the settings import does, so an import is one
// change rather than the pools that happened to validate. Pools the document
// does not name are left alone: an import adds and changes, and never deletes.
func (s *Server) handleImportPools(w http.ResponseWriter, r *http.Request) {
	var req poolsImportRequest
	if !decode(w, r, &req) {
		return
	}
	if strings.TrimSpace(req.Document) == "" {
		unprocessable(w, "there is nothing to import", []fieldError{{"document", "paste or upload a pools export"}})
		return
	}
	entries, err := parsePoolsImport(req.Document)
	if err != nil {
		unprocessable(w, "that is not a pools document", []fieldError{{"document", err.Error()}})
		return
	}
	insts, err := s.ctrl.Store().ListInstallations(r.Context())
	if err != nil {
		s.internal(w, r, "reading the installations", err)
		return
	}
	targets := map[string]string{}
	for _, i := range insts {
		targets[i.ID] = i.Target
	}

	out := poolsImportResponse{Changes: []poolImportChange{}}
	skip := map[string]bool{}
	for _, name := range req.Skip {
		skip[store.BrandedName(name)] = true
	}
	seen := map[string]bool{}
	var planned []plannedPool
	for i, entry := range entries {
		name, _ := entry["name"].(string)
		name = strings.TrimSpace(name)
		if name == "" {
			out.Changes = append(out.Changes, poolImportChange{Pool: fmt.Sprintf("pool %d", i+1),
				Action: poolRefusedAction, Reason: "every pool in the document needs a name; it is what the import matches pools by",
				Fields: []poolImportField{}, Warnings: []string{}, EnvKeys: []string{}})
			out.Summary.Refused++
			continue
		}
		name = store.BrandedName(name)
		if skip[name] {
			out.Summary.Skipped++
			continue
		}
		ch, plan := s.planPool(r, name, entry, insts, targets)
		if seen[name] {
			ch.Action, ch.Reason, ch.Fields = poolRefusedAction,
				fmt.Sprintf("the document names %s more than once; keep one of them", name), []poolImportField{}
			plan = nil
		}
		seen[name] = true
		switch ch.Action {
		case poolCreateAction:
			out.Summary.Create++
		case poolChangeAction:
			out.Summary.Change++
		case poolUnchangedAction:
			out.Summary.Unchanged++
		case poolRefusedAction:
			out.Summary.Refused++
		}
		if plan != nil && ch.Action != poolUnchangedAction {
			planned = append(planned, *plan)
		}
		out.Changes = append(out.Changes, ch)
	}

	// Before the dry-run return, so a preview says what the real run will:
	// otherwise an operator is shown "create" for pools the ceiling then
	// refuses. It waits for a document with nothing refused in it, so the
	// fixable problems are reported first, as a create reports validation
	// before room.
	if out.Summary.Refused == 0 {
		if err := s.ctrl.AdmitPools(r.Context(), out.Summary.Create); err != nil {
			if !asLimit(w, err) {
				s.internal(w, r, "checking limits.pools", err)
			}
			return
		}
	}
	if req.DryRun {
		writeJSON(w, http.StatusOK, out)
		return
	}
	if out.Summary.Refused > 0 {
		var fields []fieldError
		for _, ch := range out.Changes {
			if ch.Action == poolRefusedAction {
				fields = append(fields, fieldError{ch.Pool, ch.Reason})
			}
		}
		unprocessable(w, "some of the document was refused; skip those pools or fix the document", fields)
		return
	}
	var create, update []*store.Pool
	for _, p := range planned {
		if p.before == nil {
			create = append(create, p.after)
		} else {
			update = append(update, p.after)
		}
	}
	if len(planned) > 0 {
		if err := s.ctrl.Store().ApplyPools(r.Context(), create, update); err != nil {
			s.fail(w, r, "storing the imported pools", err)
			return
		}
	}
	id := Identity(r.Context())
	for _, p := range planned {
		if p.before == nil {
			s.auth.Auditor().Created(r.Context(), id, "pool", p.after.ID, poolForAudit(p.after))
			s.ctrl.PublishPool(r.Context(), events.KindPoolCreated, p.after)
			_, _ = s.ctrl.PrewarmPool(r.Context(), p.after)
			continue
		}
		s.auth.Auditor().Updated(r.Context(), id, "pool", p.after.ID, poolForAudit(p.before), poolForAudit(p.after))
		s.ctrl.PublishPool(r.Context(), events.KindPoolUpdated, p.after)
		// The same test a PATCH makes: only a change to what the runners are
		// made from, or where, is worth pulling an image for.
		b, a := p.before, p.after
		if b.Image != a.Image || b.DockerMode.GivesDaemon() != a.DockerMode.GivesDaemon() ||
			b.PullPolicy != a.PullPolicy || b.Backend != a.Backend || !maps.Equal(b.HostSelector, a.HostSelector) {
			_, _ = s.ctrl.PrewarmPool(r.Context(), a)
		}
	}
	if len(planned) > 0 {
		s.ctrl.Nudge()
	}
	s.auth.Auditor().Act(r.Context(), id, "pools.import", "pool", "pools", map[string]any{
		"created": out.Summary.Create, "changed": out.Summary.Change, "unchanged": out.Summary.Unchanged,
		"skipped": out.Summary.Skipped,
	})
	out.Applied = true
	writeJSON(w, http.StatusOK, out)
}

// planPool works out one document entry's fate through the same fold and the
// same validation a POST or PATCH of that pool would go through, so that the
// import can accept nothing the pools API would refuse.
func (s *Server) planPool(r *http.Request, name string, entry map[string]any,
	insts []*store.Installation, targets map[string]string) (poolImportChange, *plannedPool) {
	ctx := r.Context()
	ch := poolImportChange{Pool: name, Fields: []poolImportField{}, Warnings: []string{}, EnvKeys: []string{}}
	refuse := func(reason string) (poolImportChange, *plannedPool) {
		ch.Action, ch.Reason, ch.Fields = poolRefusedAction, reason, []poolImportField{}
		return ch, nil
	}
	if raw, ok := entry["env_keys"].([]any); ok {
		for _, k := range raw {
			if str, ok := k.(string); ok {
				ch.EnvKeys = append(ch.EnvKeys, str)
			}
		}
	}

	target, _ := entry["installation"].(string)
	target = strings.TrimSpace(target)
	if target == "" {
		return refuse("name the installation this pool belongs to by what it covers, as installation: acme or installation: acme/widgets")
	}
	var inst *store.Installation
	for _, i := range insts {
		if strings.EqualFold(i.Target, target) {
			inst = i
			break
		}
	}
	if inst == nil {
		return refuse(fmt.Sprintf("no installation on this instance covers %s; install the GitHub App there and connect it on the Installations page, or skip this pool", target))
	}

	settings := map[string]any{}
	for k, v := range entry {
		if !slices.Contains(poolDocumentOwnFields, k) {
			settings[k] = v
		}
	}
	raw, err := json.Marshal(settings)
	if err != nil {
		return refuse("its settings could not be read: " + err.Error())
	}
	var in poolInput
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&in); err != nil {
		return refuse("its settings could not be read: " + err.Error())
	}
	in.InstallationID = &inst.ID
	in.Env = nil

	existing, err := s.ctrl.Store().GetPoolByName(ctx, name)
	if err != nil && !errors.Is(err, store.ErrNotFound) {
		return refuse("the pool of that name here could not be read: " + err.Error())
	}
	// A pool the controller keeps is worked out from the hosts it has, and an
	// import that edited one would be undone by its next pass or, worse, would
	// change a figure the pool's page says is not typed. Its name is the one the
	// controller would use, so a document made by hand can reach it by accident.
	if existing != nil && existing.FromHosts() {
		return refuse(fmt.Sprintf("%s is a pool the controller keeps from your hosts, so it is not imported over; leave it out of the document, or rename the pool in the file to make one of your own", existing.Name))
	}
	var candidate *store.Pool
	var errs []fieldError
	if existing == nil {
		candidate = s.defaultPool()
		errs = in.apply(candidate)
		defaultNewPoolBurst(&in, candidate)
		// The same default a create through the API gets: an organisation's
		// pool goes in Zoomies' own runner group unless the document says.
		if in.RunnerGroup == nil && inst.TargetType == store.TargetOrg {
			candidate.RunnerGroup = controller.ManagedRunnerGroupName
		}
		errs = append(errs, s.validatePool(ctx, candidate, "")...)
	} else {
		copied := *existing
		candidate = &copied
		errs = in.apply(candidate)
		errs = append(errs, s.validatePool(ctx, candidate, existing.ID)...)
	}
	if len(errs) > 0 {
		parts := make([]string, 0, len(errs))
		for _, e := range errs {
			parts = append(parts, e.Field+": "+e.Message)
		}
		return refuse(strings.Join(parts, "; "))
	}
	// What the store would make of it, so an unchanged pool compares equal to
	// itself rather than to its own un-normalised spelling.
	candidate.Name = store.BrandedName(candidate.Name)
	candidate.Labels = store.NormalizeLabels(candidate.Labels)
	candidate.Platform = candidate.Platform.Normalized()
	if candidate.PullPolicy == "" {
		candidate.PullPolicy = store.PullIfNotPresent
	}

	incoming := documentFields(documentPool(candidate, inst.Target))
	if existing == nil {
		ch.Action = poolCreateAction
		for _, k := range sortedKeys(incoming) {
			ch.Fields = append(ch.Fields, poolImportField{Field: k, Incoming: incoming[k]})
		}
		fit, ferr := s.ctrl.HostFit(ctx, candidate)
		if ferr == nil && fit.Count == 0 && candidate.Enabled {
			// A warning, not a refusal, exactly as the wizard treats a new
			// pool: the host that runs it may be the next thing joined.
			why, _ := noHostWarning(candidate, fit)
			ch.Warnings = append(ch.Warnings, why)
		}
		return ch, &plannedPool{after: candidate}
	}

	current := documentFields(documentPool(existing, targets[existing.InstallationID]))
	for _, k := range sortedKeys(incoming) {
		if !reflect.DeepEqual(current[k], incoming[k]) {
			ch.Fields = append(ch.Fields, poolImportField{Field: k, Current: current[k], Incoming: incoming[k]})
		}
	}
	if len(ch.Fields) == 0 {
		ch.Action = poolUnchangedAction
		return ch, nil
	}
	// The pools API refuses an edit that takes a pool's last host away, and
	// an import is an edit: it gets the same refusal, with skip in place of
	// confirm as the way to go on without it.
	stranded, serr := s.ctrl.PoolStranding(ctx, existing, candidate)
	if serr != nil {
		return refuse("whether any host could still run it could not be checked: " + serr.Error())
	}
	if len(stranded) > 0 {
		st := stranded[0]
		fields := ch.Fields
		ch, _ = refuse(fmt.Sprintf("applying this would leave %s with nowhere to run: %s %s, and no other host in "+
			"this fleet could run it either. Change the document, adjust %s to match, or skip this pool.",
			st.Pool, st.Host, st.Reason, st.Host))
		ch.Fields = fields
		return ch, nil
	}
	ch.Action = poolChangeAction
	return ch, &plannedPool{before: existing, after: candidate}
}

// documentFields is a document pool as the plan compares it: field by field,
// in the JSON the document is written in, less the name it is matched by and
// the environment names it cannot apply.
func documentFields(d poolDocument) map[string]any {
	raw, _ := json.Marshal(d)
	var out map[string]any
	_ = json.Unmarshal(raw, &out)
	delete(out, "name")
	delete(out, "env_keys")
	return out
}

// parsePoolsImport reads a pools document and returns its entries.
//
// YAML is the parser, because JSON is YAML and a file kept in a repository is
// more likely to be the former. The version field is optional, so a file
// somebody wrote by hand with a pools list and nothing else is read too.
func parsePoolsImport(text string) ([]map[string]any, error) {
	var doc map[string]any
	if err := yaml.Unmarshal([]byte(text), &doc); err != nil {
		return nil, fmt.Errorf("it does not parse as YAML or JSON: %w", err)
	}
	if doc == nil {
		return nil, fmt.Errorf("it is empty")
	}
	if v, ok := doc["export_version"]; ok {
		n, isNum := v.(int)
		if !isNum || n > poolsExportVersion {
			return nil, fmt.Errorf("it is a pools export of version %v, and this build reads version %d", v, poolsExportVersion)
		}
	}
	raw, ok := doc["pools"]
	if !ok {
		if _, settings := doc["settings"]; settings {
			return nil, fmt.Errorf("it is a settings export; import it on the Settings page")
		}
		return nil, fmt.Errorf("it has no pools list")
	}
	list, ok := raw.([]any)
	if !ok {
		return nil, fmt.Errorf("its pools are not a list")
	}
	out := make([]map[string]any, 0, len(list))
	for i, item := range list {
		entry, ok := item.(map[string]any)
		if !ok {
			return nil, fmt.Errorf("pool %d is not an object", i+1)
		}
		out = append(out, entry)
	}
	return out, nil
}

