// The capacity map asks for every host at once and a detail page for one, so
// the same route answers both, and a bad window is refused with the field
// named rather than answered with an empty chart.
func TestHostSamplesAreListedForTheFleetOrOneHost(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("root", store.RoleAdmin)
	cookie := h.session(admin)
	now := h.ctrl.Now()
	cpu, ioWait := 55.0, 34.0
	if err := h.ctrl.Store().RecordHostSamples(h.ctx, []store.HostSample{
		{HostID: "host_a", At: now.Add(-2 * time.Minute), Capacity: 4, ActiveRunners: 2, CPUPercent: &cpu, IOWaitPercent: &ioWait},
		{HostID: "host_b", At: now.Add(-2 * time.Minute), Capacity: 2},
		{HostID: "host_a", At: now.Add(-3 * time.Hour), Capacity: 4},
	}); err != nil {
		t.Fatalf("RecordHostSamples: %v", err)
	}

	type page struct {
		Items []store.HostSample `json:"items"`
	}
	list := func(path string) page {
		t.Helper()
		res := h.do(request{method: http.MethodGet, path: path, cookie: cookie})
		res.mustStatus(t, http.StatusOK, path)
		var out page
		if err := json.Unmarshal(res.body, &out); err != nil {
			t.Fatalf("%s: %v: %s", path, err, truncate(res.body))
		}
		return out
	}
	all := list("/api/v1/hosts/samples?window=1h")
	if len(all.Items) != 2 {
		t.Fatalf("items in the hour = %d, want the two recent samples: %+v", len(all.Items), all.Items)
	}
	one := list("/api/v1/hosts/samples?window=6h&host_id=host_a")
	if len(one.Items) != 2 || one.Items[0].HostID != "host_a" || one.Items[1].HostID != "host_a" {
		t.Fatalf("items for host_a over 6h = %+v, want both of its samples", one.Items)
	}
	if one.Items[1].CPUPercent == nil || *one.Items[1].CPUPercent != cpu {
		t.Errorf("newest sample = %+v, want its CPU measurement", one.Items[1])
	}
	if one.Items[1].IOWaitPercent == nil || *one.Items[1].IOWaitPercent != ioWait {
		t.Errorf("newest sample = %+v, want its I/O wait measurement", one.Items[1])
	}
	bad := h.do(request{method: http.MethodGet, path: "/api/v1/hosts/samples?window=soon", cookie: cookie})
	bad.mustStatus(t, http.StatusBadRequest, "unparseable window")
}

// The host route is the other half of the pulse: the current judgement, not
// just the history. An assistant reading list_hosts sees the same fields,
// because that tool is a pass-through of GET /hosts.
func TestAHostViewCarriesItsDiskPulse(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("root", store.RoleAdmin)
	cookie := h.session(admin)
	host := h.host("vm-disk")
	wait := 33.0
	since := h.ctrl.Now().Add(-11 * time.Minute)
	if err := h.ctrl.Store().SetHostUsage(h.ctx, host.ID, store.HostUsage{
		SampledAt: h.ctrl.Now(), IOWaitPercent: &wait, IOWaitHighSince: &since,
	}); err != nil {
		t.Fatalf("SetHostUsage: %v", err)
	}

	res := h.do(request{method: http.MethodGet, path: "/api/v1/hosts/" + host.ID, cookie: cookie})
	res.mustStatus(t, http.StatusOK, "get the host")
	var view hostResponse
	res.into(t, &view)
	if !view.UsageFresh || !view.DiskBound {
		t.Fatalf("usage_fresh=%v disk_bound=%v, want a fresh disk-bound host", view.UsageFresh, view.DiskBound)
	}
	if view.Usage == nil || view.Usage.IOWaitPercent == nil || *view.Usage.IOWaitPercent != wait {
		t.Fatalf("usage = %+v, want I/O wait %v", view.Usage, wait)
	}
}

package api

import (
	"encoding/json"
	"net/http"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// throttledHost is a host on the second rung, as the controller would have
// left it after two steps of sustained pressure. The row is written directly:
// the ladder is the scheduler's and is tested there, and what these tests
// are about is what an operator can do to the rung once it exists.
func throttledHost(t *testing.T, h *harness) *store.Host {
	t.Helper()
	host := h.host("vm-1")
	host.CPUs, host.MemoryMB = 8, 16*1024
	if err := h.st.UpdateHost(h.ctx, host); err != nil {
		t.Fatalf("UpdateHost: %v", err)
	}
	since := time.Now().Add(-7 * time.Minute)
	changed := time.Now().Add(-3 * time.Minute)
	throttle := store.HostThrottle{
		Level: 2, Since: &since, ChangedAt: &changed,
		Reason: "the 1-minute load average is 30.0, at least twice the host's 8 CPUs",
	}
	if err := h.st.SetHostThrottle(h.ctx, host.ID, throttle, 0); err != nil {
		t.Fatalf("SetHostThrottle: %v", err)
	}
	host.Throttle = throttle
	return host
}

// lastAudit is the newest audit row for an action, or nil.
func lastAudit(t *testing.T, h *harness, action string) *store.AuditEvent {
	t.Helper()
	rows, _, err := h.st.ListAudit(h.ctx, store.AuditFilter{Actions: []string{action}}, store.Page{Limit: 1})
	if err != nil {
		t.Fatalf("ListAudit(%s): %v", action, err)
	}
	if len(rows) == 0 {
		return nil
	}
	return rows[0]
}

// A throttle lifts itself after five minutes of calm, which is the right
// answer for a host nobody is looking at and the wrong one for a host whose
// operator has just cancelled the runaway job: they know the pressure is gone
// and should not have to wait for the fleet to notice. The route is the
// difference, and the audit row is what says who decided the fleet was wrong.
func TestAnOperatorCanLiftAHostsThrottle(t *testing.T) {
	h := newHarness(t)
	host := throttledHost(t, h)
	operator, _ := h.user("operator", store.RoleOperator)

	before := h.do(request{method: http.MethodGet, path: "/api/v1/hosts/" + host.ID, cookie: h.session(operator)})
	before.mustStatus(t, http.StatusOK, "read the throttled host")
	var was hostResponse
	before.into(t, &was)
	if was.Throttle == nil || was.Throttle.Level != 2 || was.EffectiveCapacity != 2 || was.ThrottleReason == "" {
		t.Fatalf("the view does not show the throttle it was given: %+v", was)
	}

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/hosts/" + host.ID + "/throttle/clear",
		cookie: h.session(operator)})
	resp.mustStatus(t, http.StatusOK, "lift the throttle")
	var view hostResponse
	resp.into(t, &view)
	if view.Throttle != nil || view.ThrottleReason != "" {
		t.Errorf("the response still carries a throttle: %+v", view)
	}
	if view.EffectiveCapacity != view.Capacity || view.Capacity != 4 {
		t.Errorf("effective capacity = %d of %d, want the configured 4 of 4 once the throttle is lifted",
			view.EffectiveCapacity, view.Capacity)
	}

	// It survives the write: the next scheduling pass reads the row, not the
	// response.
	stored, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if stored.Throttle.Active() {
		t.Fatalf("the stored host is still throttled: %+v", stored.Throttle)
	}

	// The audit row is under the operator, not the system: a colleague reading
	// the log should see who lifted it early and what rung it was on.
	row := lastAudit(t, h, "host.throttle_clear")
	if row == nil {
		t.Fatal("no host.throttle_clear audit row was written")
	}
	if row.TargetKind != "host" || row.TargetID != host.ID || row.ActorID != operator.ID {
		t.Errorf("audit row = kind %q target %q actor %q, want host %s by %s",
			row.TargetKind, row.TargetID, row.ActorID, host.ID, operator.ID)
	}
	var detail struct {
		Name              string `json:"name"`
		Level             int    `json:"level"`
		Reason            string `json:"reason"`
		EffectiveCapacity int    `json:"effective_capacity"`
	}
	if err := json.Unmarshal([]byte(row.After), &detail); err != nil {
		t.Fatalf("the audit detail is not JSON: %v: %s", err, row.After)
	}
	if detail.Name != host.Name || detail.Level != 2 || detail.Reason == "" || detail.EffectiveCapacity != 2 {
		t.Errorf("the audit detail does not describe the throttle it cleared: %s", row.After)
	}

	// Lifting a throttle that is not there is answered with the host as it is
	// and writes no second row, exactly as uncordoning an uncordoned host does.
	again := h.do(request{method: http.MethodPost, path: "/api/v1/hosts/" + host.ID + "/throttle/clear",
		cookie: h.session(operator)})
	again.mustStatus(t, http.StatusOK, "lift a throttle that is not there")
	rows, _, err := h.st.ListAudit(h.ctx, store.AuditFilter{Actions: []string{"host.throttle_clear"}}, store.Page{Limit: 10})
	if err != nil {
		t.Fatalf("ListAudit: %v", err)
	}
	if len(rows) != 1 {
		t.Errorf("a no-op clear wrote an audit row: %d rows", len(rows))
	}
}

// Lifting a throttle changes what the fleet places on a host, which is an
// operator's decision and not a viewer's; and a host that does not exist is
// a 404, not a 500, because the id came from somewhere and that somewhere
// is stale.
func TestLiftingAThrottleIsForOperatorsAndNamedHosts(t *testing.T) {
	h := newHarness(t)
	host := throttledHost(t, h)
	viewer, _ := h.user("viewer", store.RoleViewer)
	operator, _ := h.user("operator", store.RoleOperator)

	refused := h.do(request{method: http.MethodPost, path: "/api/v1/hosts/" + host.ID + "/throttle/clear",
		cookie: h.session(viewer)})
	refused.mustStatus(t, http.StatusForbidden, "a viewer lifting a throttle")
	stored, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if !stored.Throttle.Active() {
		t.Fatal("a refused request lifted the throttle anyway")
	}
	if row := lastAudit(t, h, "host.throttle_clear"); row != nil {
		t.Errorf("a refused request wrote an audit row: %+v", row)
	}

	missing := h.do(request{method: http.MethodPost, path: "/api/v1/hosts/host_nope/throttle/clear",
		cookie: h.session(operator)})
	missing.mustStatus(t, http.StatusNotFound, "a host that does not exist")
}

// A change to the capacity or the reserve is the operator answering the
// pressure that throttled the host, so it lifts the rung with it; left
// standing, the new figures would take effect only once the old episode had
// spent five minutes calm. A label says nothing about the machine and lifts
// nothing.
func TestChangingCapacityOrTheReserveLiftsTheThrottle(t *testing.T) {
	cases := []struct {
		name  string
		body  map[string]any
		lifts bool
		// audited is whether the PATCH changed anything at all: a request
		// that repeats the host's own figures writes no host.update row.
		audited bool
	}{
		{"capacity", map[string]any{"capacity": 3}, true, true},
		{"a CPU reserve", map[string]any{"reserve_cpus": 2}, true, true},
		{"a memory reserve", map[string]any{"reserve_memory_mb": 4096}, true, true},
		{"labels alone", map[string]any{"labels": map[string]string{"zone": "eu"}}, false, true},
		// The edit dialog sends every field it shows, so an operator who
		// added a label sends the capacity too; only a figure that moved is
		// an answer to the pressure, and the same figure again is not.
		{"the capacity it already has", map[string]any{"capacity": 4}, false, false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			host := throttledHost(t, h)
			operator, _ := h.user("operator", store.RoleOperator)

			resp := h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID,
				cookie: h.session(operator), body: tc.body})
			resp.mustStatus(t, http.StatusOK, "patch the host")
			var view hostResponse
			resp.into(t, &view)

			stored, err := h.st.GetHost(h.ctx, host.ID)
			if err != nil {
				t.Fatalf("GetHost: %v", err)
			}
			if stored.Throttle.Active() == tc.lifts {
				t.Fatalf("stored throttle active = %v after changing %s, want %v", stored.Throttle.Active(), tc.name, !tc.lifts)
			}
			if (view.Throttle == nil) != tc.lifts {
				t.Errorf("the response's throttle does not match the row: %+v", view.Throttle)
			}

			// The PATCH's own audit row says so, rather than leaving a reader
			// to work out that {} against {level: 2} means "lifted".
			row := lastAudit(t, h, "host.update")
			if !tc.audited {
				if row != nil {
					t.Fatalf("a PATCH that changed nothing wrote an audit row: %+v", row)
				}
				return
			}
			if row == nil {
				t.Fatal("no host.update audit row was written")
			}
			var after map[string]any
			if err := json.Unmarshal([]byte(row.After), &after); err != nil {
				t.Fatalf("the audit's after is not JSON: %v: %s", err, row.After)
			}
			if _, ok := after["throttle_cleared"]; ok != tc.lifts {
				t.Errorf("throttle_cleared present = %v in the audit detail, want %v: %s", ok, tc.lifts, row.After)
			}
			if lifted := lastAudit(t, h, "host.throttle_clear"); lifted != nil {
				t.Errorf("a PATCH wrote a host.throttle_clear row of its own; the lift is the PATCH's to record: %+v", lifted)
			}
		})
	}
}

package api

import (
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"net/url"
	"reflect"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// otherKey is a second instance key, so an import proves the archive did not
// lean on the exporting instance's.
const otherKey = "ZmVkY2JhOTg3NjU0MzIxMGZlZGNiYTk4NzY1NDMyMTA="

// secondInstallation is the neighbour: its own target, its own pool and job,
// sealed with the same key as the first.
func (h *harness) secondInstallation(target string) *store.Installation {
	h.t.Helper()
	pem, _ := h.key.SealString("-----BEGIN RSA PRIVATE KEY-----\nother\n-----END RSA PRIVATE KEY-----")
	inst := &store.Installation{AppID: h.gh.AppID(), InstallationID: h.gh.InstallationID() + 1, Target: target,
		TargetType: store.TargetOrg, APIBaseURL: h.gh.URL(), PrivateKeyEnc: pem}
	if err := h.st.CreateInstallation(h.ctx, inst); err != nil {
		h.t.Fatalf("CreateInstallation: %v", err)
	}
	return inst
}

func (h *harness) installationRows(id string) string {
	h.t.Helper()
	tables, err := h.st.ExportInstallation(h.ctx, id)
	if err != nil {
		h.t.Fatalf("ExportInstallation: %v", err)
	}
	raw, _ := json.Marshal(tables)
	return string(raw)
}

// installationFigures renders one installation's usage report over a fixed
// window as JSON, so two readings compare byte for byte.
func (h *harness) installationFigures(id string, from, to time.Time) string {
	h.t.Helper()
	rows, err := h.st.Usage(h.ctx, from, to, store.UsageByInstallation)
	if err != nil {
		h.t.Fatalf("Usage: %v", err)
	}
	var out []store.UsageRow
	for _, r := range rows {
		if r.Key == id {
			out = append(out, r)
		}
	}
	if len(out) == 0 {
		h.t.Fatal("the installation has no figures, so comparing them would prove nothing")
	}
	raw, _ := json.Marshal(out)
	return string(raw)
}

// The package's acceptance, end to end through the API: one installation is
// exported under a passphrase and purged, its neighbour's rows and figures do
// not move by a byte, and the archive imports onto a fresh instance with a
// different key and verifies against GitHub there.
func TestAnExportedInstallationPurgesCleanlyAndVerifiesOnAFreshInstance(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("root", store.RoleAdmin)
	a := h.installation()
	b := h.secondInstallation("globex")
	aPool, bPool := h.pool(a, "acme-linux"), h.pool(b, "globex-linux")
	aJob, _ := h.job(aPool, store.JobCompleted), h.job(bPool, store.JobCompleted)

	from, to := time.Now().Add(-24*time.Hour), time.Now().Add(time.Hour)
	beforeRows, beforeFigures := h.installationRows(b.ID), h.installationFigures(b.ID, from, to)

	res := h.do(request{method: http.MethodPost, path: "/api/v1/installations/" + a.ID + "/export",
		cookie: h.session(admin), body: map[string]any{"passphrase": "move it carefully"}})
	res.mustStatus(t, http.StatusOK, "export")
	archive := res.body
	if strings.Contains(string(archive), "BEGIN RSA") || strings.Contains(string(archive), b.ID) {
		t.Fatal("the archive carries a key in the clear, or names the other installation")
	}
	if !strings.Contains(string(archive), aJob.ID) {
		t.Fatal("the archive does not carry the installation's job")
	}

	// A purge is confirmed by typing the target, as a machine release is.
	res = h.do(request{method: http.MethodDelete, path: "/api/v1/installations/" + a.ID + "?purge=true",
		cookie: h.session(admin)})
	res.mustStatus(t, http.StatusUnprocessableEntity, "purge without confirmation")
	if _, err := h.st.GetInstallation(h.ctx, a.ID); err != nil {
		t.Fatalf("an unconfirmed purge removed the installation: %v", err)
	}
	res = h.do(request{method: http.MethodDelete, path: "/api/v1/installations/" + a.ID + "?purge=true&confirm=" + url.QueryEscape(a.Target),
		cookie: h.session(admin)})
	res.mustStatus(t, http.StatusOK, "purge")
	if _, err := h.st.GetJob(h.ctx, aJob.ID); err == nil {
		t.Error("the purged installation's job is still here")
	}
	if got := h.installationRows(b.ID); got != beforeRows {
		t.Errorf("the neighbour's rows changed:\nbefore %s\nafter  %s", beforeRows, got)
	}
	if got := h.installationFigures(b.ID, from, to); got != beforeFigures {
		t.Errorf("the neighbour's figures changed:\nbefore %+v\nafter  %+v", beforeFigures, got)
	}
	audit, _, err := h.st.ListAudit(h.ctx, store.AuditFilter{TargetID: a.ID}, store.Page{Limit: 10})
	if err != nil {
		t.Fatal(err)
	}
	var actions []string
	for _, e := range audit {
		actions = append(actions, e.Action)
	}
	if !reflect.DeepEqual(actions, []string{"installation.purge"}) {
		t.Errorf("after the purge the audit rows naming it are %v, want only the purge itself", actions)
	}

	// The exporting installation points at the fake GitHub on loopback.
	fresh := newHarness(t, allowPrivateEgress, func(c *config.Config) { c.Security.EncryptionKey = otherKey })
	root, _ := fresh.user("root", store.RoleAdmin)
	res = fresh.do(request{method: http.MethodPost, path: "/api/v1/installations/import", cookie: fresh.session(root),
		body: map[string]any{"archive": json.RawMessage(archive), "passphrase": "the wrong one"}})
	res.mustStatus(t, http.StatusUnprocessableEntity, "import under the wrong passphrase")
	if list, _ := fresh.st.ListInstallations(fresh.ctx); len(list) != 0 {
		t.Fatal("a refused import left an installation behind")
	}
	res = fresh.do(request{method: http.MethodPost, path: "/api/v1/installations/import", cookie: fresh.session(root),
		body: map[string]any{"archive": json.RawMessage(archive), "passphrase": "move it carefully"}})
	res.mustStatus(t, http.StatusCreated, "import")
	if _, err := fresh.st.GetJob(fresh.ctx, aJob.ID); err != nil {
		t.Errorf("the job did not arrive with the installation: %v", err)
	}

	res = fresh.do(request{method: http.MethodPost, path: "/api/v1/installations/" + a.ID + "/verify", cookie: fresh.session(root)})
	res.mustStatus(t, http.StatusOK, "verify on the fresh instance")
	var out struct {
		OK      bool   `json:"ok"`
		Message string `json:"message"`
	}
	res.into(t, &out)
	if !out.OK {
		t.Errorf("the imported installation did not verify: %s", out.Message)
	}
}

// Without a passphrase the history travels and the credential does not, and
// the import says the key has to be entered by hand by leaving it empty.
func TestAnExportWithoutAPassphraseCarriesNoCredential(t *testing.T) {
