	resp.mustStatus(t, http.StatusConflict, "delete a machine that is already deleted")
	if msg := resp.errorMessage(t); !strings.Contains(msg, "already deleted") {
		t.Errorf("the refusal does not say the machine is already deleted: %q", msg)
	}
}

package api

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"net/url"
	"strings"

	"github.com/go-chi/chi/v5"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/mcp"
	"github.com/eyupio/zoomies/internal/version"
)

// mcpToolActions is the action each MCP tool that changes the fleet needs. A
// token whose role reaches it is offered the tool; one whose role does not is
// not, and is told why if its agent asks anyway. The controller still decides
// each call on its own route -- this only keeps the list an agent chooses from
// honest.
var mcpToolActions = map[string]auth.Action{
	"rerun_job":       auth.ActionJobsRerun,
	"drain_runner":    auth.ActionRunnersDrain,
	"update_pool":     auth.ActionPoolsWrite,
	"apply_remedy":    auth.ActionProblemsApply,
	"update_host":     auth.ActionHostsWrite,
	"context_publish": auth.ActionContextPublish,

	// The administrator tools: offered only to an administrator, and only while
	// security.mcp_admin_tools is on. See mcp.IsAdminTool.
	"edit_host":           auth.ActionSettingsWrite,
	"clear_host_throttle": auth.ActionSettingsWrite,
	"get_settings":        auth.ActionSettingsRead,
	"update_settings":     auth.ActionSettingsWrite,
}

// mcpResponseLimit bounds what one tool call reads back from a route. It is
// the stdio server's log limit: a runner's log is the only answer that is ever
// large, and the tool keeps only its tail.
const mcpResponseLimit = 32 << 20

// handleMCP is the fleet over MCP's Streamable HTTP transport, for an agent
// that can reach the controller but cannot, or would rather not, launch
// `zoomies mcp` beside itself -- a cloud session, a hosted agent.
//
// It adds no authority. The caller's bearer token is resolved exactly as the
// API resolves it, and every tool call is handed back to this server's own
// router as the documented route with that same token, so it passes through
// the same role check, scope check, audit trail and access log that
// `zoomies jobs list` does. A session cookie is not accepted: the endpoint is
// for agents, and refusing the cookie means a page the operator happens to
// visit cannot drive it, whatever the browser sends along.
func (s *Server) handleMCP(w http.ResponseWriter, r *http.Request) {
	// The specification asks a server to check Origin, so that a page
	// rebinding its own name to this address cannot reach a server that
	// trusts where a request came from. A bearer token already stops that;
	// this is the second lock the specification asks for, and an agent sends
	// no Origin at all.
	if origin := strings.TrimSpace(r.Header.Get("Origin")); origin != "" && !s.originAllowed(origin) && !s.sameOriginAsRequest(r, origin) {
		forbidden(w, "this MCP request came from "+origin+", which is not this controller's origin. "+
			"Add it to server.allowed_origins if that is deliberate.")
		return
	}
	id, err := s.authenticateMCP(r)
	if err != nil {
		// Before the challenge: on a 500 it would send the client off to start
		// a sign-in that cannot help.
		if errors.Is(err, auth.ErrAuthBackend) {
			s.internal(w, r, "checking your credentials", err)
			return
		}
		// The challenge is what tells an MCP client to ask for credentials
		// rather than give up. With OAuth on it names the metadata that starts
		// a browser sign-in; with it off, an API token is the only way in.
		errCode := ""
		if hasBearer(r) {
			errCode = "invalid_token"
		}
		w.Header().Set("WWW-Authenticate", s.mcpChallenge(r, errCode))
		msg := err.Error() + "; send an API token as Authorization: Bearer zoo_... -- " +
			"create one with `zoomies tokens create --role viewer` or on the API tokens settings page"
		if s.cfg().MCPOAuthEnabled() {
			msg = err.Error() + "; sign in through the client's OAuth flow, whose metadata is at " + s.resourceMetadataURL(r) +
				", or send an API token as Authorization: Bearer zoo_..."
		}
		unauthorized(w, msg)
		return
	}
	if info := infoFrom(r.Context()); info != nil {
		info.identity = id
		info.log = info.log.With("identity", id.String())
	}

	mcp.New(inProcessAPI{s: s, from: r, as: id}, mcp.Options{
		Offer: func(tool string) bool {
			_, ok := mcpMissingAction(id, tool)
			return ok && (!mcp.IsAdminTool(tool) || s.cfg().Security.MCPAdminTools)
		},
		Refusal: func(tool string) string {
			missing, ok := mcpMissingAction(id, tool)
			if ok && mcp.IsAdminTool(tool) {
				return tool + " is an administrator tool, and this controller does not offer those over MCP. " +
					"An administrator turns it on at Settings, Security, \"Offer administrator tools over MCP\" (security.mcp_admin_tools)."
			}
			if id.Kind == auth.KindConnection {
				return tool + " changes the fleet, and is not offered to this connection: " + auth.Explain(id, missing) +
					". Disconnect and connect again choosing the operator role to be offered it."
			}
			return tool + " changes the fleet, and is not offered to this token: " + auth.Explain(id, missing)
		},
	}).ServeHTTP(w, r)
}

// mcpMissingAction says whether the caller may use a tool and, when not, the action
// they lack. apply_remedy is the one tool that needs two: the route's own
// problems.apply and then the update it makes, which is a pool's or a host's. A
// token with the first alone would be offered the tool and refused when it called it,
// which is not the honest list the tools list promises.
func mcpMissingAction(id *auth.Identity, tool string) (auth.Action, bool) {
	a, known := mcpToolActions[tool]
	if !known {
		return a, false
	}
	if !auth.Allowed(id, a) {
		return a, false
	}
	if tool == "apply_remedy" && !auth.Allowed(id, auth.ActionPoolsWrite) && !auth.Allowed(id, auth.ActionHostsWrite) {
		return auth.ActionPoolsWrite, false
	}
	return a, true
}

// authenticateMCP resolves /mcp's caller: an MCP access token when OAuth is
// on and the credential is one, and otherwise exactly as the API resolves a
// bearer token.
func (s *Server) authenticateMCP(r *http.Request) (*auth.Identity, error) {
	header := r.Header.Get("Authorization")
	if tok := auth.BearerToken(header); auth.IsMCPAccessToken(tok) && s.cfg().MCPOAuthEnabled() && !s.cfg().Security.DisableAuth {
		return s.auth.AuthenticateMCP(r.Context(), s.oauthPolicy(r), tok, ClientIP(r.Context()))
	}
	return s.auth.Authenticate(r.Context(), auth.AuthInput{Authorization: header, IP: ClientIP(r.Context())})
}

type contextCredentialCheck struct{}

func inProcessIdentity(r *http.Request) *auth.Identity {
	id, _ := r.Context().Value(ctxInProcess).(*auth.Identity)
	return id
}

// inProcessAPI is the REST API as the MCP tools see it from inside the
// controller: each call is a request to this server's own router, carrying the
// MCP request's credential and client address, so nothing about it differs
// from the same call made over the network except the network.
type inProcessAPI struct {
	s    *Server
	from *http.Request
	// as is the /mcp caller. An MCP connection's token is not forwarded: it
	// is accepted on /mcp alone, and the specification forbids passing it on,
	// so the route sees the connection's identity instead.
	as *auth.Identity
	// direct is a caller that was already authenticated by this server, such
	// as the assistant acting for the person chatting: its identity is handed
	// to the route as it is, and no credential is forwarded, so what the route
	// allows is what that person is allowed and nothing about the request that
	// carried it matters.
	direct bool
}

func (a inProcessAPI) Call(ctx context.Context, method, path string, q url.Values) ([]byte, error) {
	return a.do(ctx, method, path, q, "application/json", nil)
}

func (a inProcessAPI) CallBody(ctx context.Context, method, path string, q url.Values, body []byte) ([]byte, error) {
	return a.do(ctx, method, path, q, "application/json", body)
}

func (a inProcessAPI) Stream(ctx context.Context, path, accept string) (io.ReadCloser, error) {
	// A log download ends when the relay goes quiet, so reading it whole is
	// what the stdio server's client does too; there is no connection here to
	// hold open for it.
	body, err := a.do(ctx, http.MethodGet, path, nil, accept, nil)
	if err != nil {
		return nil, err
	}
	return io.NopCloser(bytes.NewReader(body)), nil
}

func (a inProcessAPI) do(ctx context.Context, method, path string, q url.Values, accept string, body []byte) ([]byte, error) {
	target := "/api/v1" + path
	if len(q) > 0 {
		target += "?" + q.Encode()
	}
	// The tool's context descends from the /mcp request's, which carries the
	// router's own state for that request; left there, the router would take
	// this for the rest of that dispatch rather than a request of its own.
	ctx = context.WithValue(ctx, chi.RouteCtxKey, (*chi.Context)(nil))
	// The tools never send confirm=true, so a refusal that says to send it again with
	// it is advice an agent cannot follow, and one that loops it.
	ctx = noConfirm(ctx)
	var reader io.Reader
	if body != nil {
		reader = bytes.NewReader(body)
	}
	req, err := http.NewRequestWithContext(ctx, method, target, reader)
	if err != nil {
		return nil, err
	}
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	// The address and the proxy headers go along so that the client address
	// the audit trail records is the agent's, resolved through the same
	// trusted proxies, rather than this process's own.
	req.RemoteAddr = a.from.RemoteAddr
	req.Host = a.from.Host
	req.TLS = a.from.TLS
	forward := []string{"Authorization", "Forwarded", "X-Forwarded-For", "X-Forwarded-Proto", "X-Forwarded-Host", "X-Real-IP"}
	if a.direct {
		forward = forward[1:]
		req = req.WithContext(context.WithValue(req.Context(), ctxInProcess, a.as))
	} else if a.as != nil && a.as.Kind == auth.KindConnection {
		forward = forward[1:]
		req = req.WithContext(context.WithValue(req.Context(), ctxInProcess, a.as))
		req = req.WithContext(context.WithValue(req.Context(), contextCredentialCheck{}, func(ctx context.Context) (*auth.Identity, error) { return a.s.authenticateMCP(a.from.WithContext(ctx)) }))
	}
	for _, h := range forward {
		if v := a.from.Header.Values(h); len(v) > 0 {
			req.Header[h] = v
		}
	}
	req.Header.Set("Accept", accept)
	req.Header.Set("User-Agent", "zoomies-mcp/"+version.Version)

	// Every tool call buffers a whole answer, so a caller that opens many at
	// once pins that much memory on the process that owns the SQLite writer.
	// The agent routes refuse this with a 429 before reading a byte; this is
	// the same refusal for the two model-facing entry points, which reach
	// every route through here, whether the call arrives over /mcp or
	// through the assistant's toolbox.
	key := ""
	if a.as != nil {
		key = a.as.String()
	}
	if ok, retry := a.s.inProcessBudget.take(key); !ok {
		a.s.logger(a.from).Warn("in-process call budget exhausted", "identity", key, "retry_after", retry)
		return nil, &mcpRefusal{status: http.StatusTooManyRequests,
			message: "this caller already has tool answers being read; wait for one to finish and ask again"}
	}
	defer a.s.inProcessBudget.give(key)

	rec := &bufferedResponse{header: http.Header{}, limit: mcpResponseLimit}
	a.s.handler.ServeHTTP(rec, req)
	if a.as != nil && a.as.Kind == auth.KindConnection && method != http.MethodGet {
		// The route audits what it did as the connection already; this row
		// says it was an MCP tool that asked, and how the route answered,
		// so a refused attempt is on the record too.
		a.s.auth.Auditor().Act(ctx, a.as, "mcp_connection.call", "mcp_connection", a.as.ID,
			map[string]any{"method": method, "path": target, "status": rec.status})
	}
	if rec.status >= 400 {
		return nil, refusalFrom(rec.status, rec.body.Bytes())
	}
	return rec.body.Bytes(), nil
}

// bufferedResponse collects a route's answer for a tool to read. It stops
// taking bytes at its limit, which ends a log download the way a closed
// connection would.
type bufferedResponse struct {
	header http.Header
	status int
	body   bytes.Buffer
	limit  int
}

var errResponseFull = errors.New("the answer is larger than an MCP tool reads")

func (b *bufferedResponse) Header() http.Header { return b.header }

func (b *bufferedResponse) WriteHeader(status int) {
	if b.status == 0 {
		b.status = status
	}
}

func (b *bufferedResponse) Write(p []byte) (int, error) {
	b.WriteHeader(http.StatusOK)
	room := b.limit - b.body.Len()
	if room <= 0 {
		return 0, errResponseFull
	}
	if len(p) > room {
		b.body.Write(p[:room])
		return room, errResponseFull
	}
	return b.body.Write(p)
}

// mcpRefusal is a route's refusal, carrying the controller's own sentence --
// which role is missing, which field is wrong -- to the agent intact.
type mcpRefusal struct {
	status  int
	message string
}

func (e *mcpRefusal) Error() string   { return e.message }
func (e *mcpRefusal) HTTPStatus() int { return e.status }

func refusalFrom(status int, body []byte) error {
	var envelope errorEnvelope
	msg := ""
	if json.Unmarshal(body, &envelope) == nil {
		msg = envelope.Error.Message
		if envelope.Error.Field != "" {
			msg += " (field " + envelope.Error.Field + ")"
		}
		if envelope.Error.Detail != "" {
			msg += ": " + envelope.Error.Detail
		}
	}
	if msg == "" {
		msg = http.StatusText(status)
	}
	return &mcpRefusal{status: status, message: msg}
}

package api

import (
	"sync"
	"time"
)

// inProcessBudget bounds how many route answers one caller may be holding
// at once. Every tool call buffers a whole answer (mcpResponseLimit is 32
// MiB), and the agent routes answer a caller that tries this with 429
// before reading a byte; the MCP and assistant paths funnelled through
// inProcessAPI were the two entry points with no such ceiling, and they run
// on the process that owns the SQLite writer. A keyed semaphore rather than
// auth.RateLimiter, which bounds how often a key may call, not how many
// calls it may hold.
//
// The map needs no sweeping: every take is paired with a give, a key's count
// returns to zero, and the entry goes with it.
type inProcessBudget struct {
	mu        sync.Mutex
	held      map[string]int
	totalHeld int
}

const (
	// inProcessPerCaller is the ceiling per identity. Two concurrent large
	// log reads (one live, one download) are a plausible legitimate pair;
	// a third held answer from the same caller is a loop, not a reader.
	inProcessPerCaller = 2
	// inProcessTotal is the fleet-wide ceiling, so many callers together
	// still pin a bounded slice of this process's memory.
	inProcessTotal = 16
)

// inProcessRetryAfter is how long a refused caller is told to wait. The
// refusal is about calls in flight rather than about a window of calls, so
// the wait is short: an answer that is being read is usually nearly ready,
// and a caller that waits longer than that has a problem the wait will not
// fix.
const inProcessRetryAfter = 2 * time.Second

// take spends one slot for key and reports how long to wait when the
// ceiling refuses. key is the caller's identity string; the empty string is
// every call without an identity, which cannot happen on a real path but
// must not bypass the budget.
func (b *inProcessBudget) take(key string) (ok bool, retryAfter time.Duration) {
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.held == nil {
		b.held = map[string]int{}
	}
	if b.held[key] >= inProcessPerCaller || b.totalHeld >= inProcessTotal {
		return false, inProcessRetryAfter
	}
	b.held[key]++
	b.totalHeld++
	return true, 0
}

// give returns one slot for key. It is safe to call without a matching take
// (a give for a key holding nothing is a no-op), because release runs on
// every exit path of do, including the ones a panic-free rewrite of do
// might add later.
func (b *inProcessBudget) give(key string) {
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.held == nil {
		return
	}
	n := b.held[key]
	if n == 0 {
		return
	}
	if n == 1 {
		delete(b.held, key)
	} else {
		b.held[key] = n - 1
	}
	b.totalHeld--
}

package api

import (
	"fmt"
	"maps"
	"testing"
)

// budgetStep is one move the budget is asked to make: a take, which must be
// allowed or refused, or a give, which returns a slot.
type budgetStep struct {
	// take spends a slot for key; when it is false the step gives one back.
	take bool
	key  string
	// wantOK is what a take must answer.
	wantOK bool
}

// The budget is a keyed semaphore, not a rate limiter: what it bounds is how
// many answers one caller may be holding at once, so a caller that asks for
// a third is refused while a caller that has given one back is let in.
func TestTheInProcessBudgetRefusesTheThirdCallOfOneCaller(t *testing.T) {
	// Sixteen callers, then a seventeenth, which the fleet-wide ceiling
	// refuses even though each of them holds only one answer.
	fleet := make([]budgetStep, 0, inProcessTotal+1)
	for i := 0; i < inProcessTotal; i++ {
		fleet = append(fleet, budgetStep{take: true, key: fmt.Sprintf("caller %d", i), wantOK: true})
	}
	fleet = append(fleet, budgetStep{take: true, key: fmt.Sprintf("caller %d", inProcessTotal), wantOK: false})

	cases := []struct {
		name  string
		steps []budgetStep
	}{
		{
			name: "a caller may hold two answers and no more",
			steps: []budgetStep{
				{take: true, key: "token agent (viewer)", wantOK: true},
				{take: true, key: "token agent (viewer)", wantOK: true},
				{take: true, key: "token agent (viewer)", wantOK: false},
			},
		},
		{
			name:  "the fleet ceiling refuses a seventeenth caller",
			steps: fleet,
		},
		{
			name: "giving a slot back makes room for the same caller",
			steps: []budgetStep{
				{take: true, key: "token agent (viewer)", wantOK: true},
				{take: true, key: "token agent (viewer)", wantOK: true},
				{take: false, key: "token agent (viewer)"},
				{take: true, key: "token agent (viewer)", wantOK: true},
				{take: true, key: "token agent (viewer)", wantOK: false},
			},
		},
		{
			name: "a call without an identity is bounded like any other caller",
			steps: []budgetStep{
				{take: true, key: "", wantOK: true},
				{take: true, key: "", wantOK: true},
				{take: true, key: "", wantOK: false},
			},
		},
		{
			name: "a give for a caller holding nothing changes nothing",
			steps: []budgetStep{
				{take: false, key: "token nobody (viewer)"},
				{take: true, key: "token agent (viewer)", wantOK: true},
				{take: true, key: "token agent (viewer)", wantOK: true},
				{take: true, key: "token agent (viewer)", wantOK: false},
			},
		},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			b := &inProcessBudget{}
			outstanding := map[string]int{}
			for i, s := range c.steps {
				if s.take {
					ok, retry := b.take(s.key)
					if ok != s.wantOK {
						t.Fatalf("step %d: taking for %q was allowed %v, wanted %v", i, s.key, ok, s.wantOK)
					}
					if !ok && retry <= 0 {
						t.Errorf("step %d: a refusal must say how long to wait", i)
					}
					if ok {
						outstanding[s.key]++
					}
				} else {
					b.give(s.key)
					if outstanding[s.key] > 0 {
						outstanding[s.key]--
						if outstanding[s.key] == 0 {
							delete(outstanding, s.key)
						}
					}
				}
				if !maps.Equal(b.held, outstanding) {
					t.Fatalf("step %d: the budget holds %v, wanted %v", i, b.held, outstanding)
				}
				slots := 0
				for _, n := range outstanding {
					slots += n
				}
				if b.totalHeld != slots {
					t.Fatalf("step %d: the budget holds %d answers in all, wanted %d", i, b.totalHeld, slots)
				}
			}
		})
	}
}

package api

import (
	"encoding/json"
	"slices"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

var providerReadTools = []string{"list_providers", "provider_pairings", "list_machines"}

// The provider tools are reads, so they are offered to every role and the routes
// behind them decide, exactly as list_hosts is. A viewer holds providers.read and
// machines.read, and sees what the Providers page shows it: never a credential.
func TestAViewerTokenReadsProvidersAndMachinesOverMCPWithoutAnyCredential(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	prov := h.provider("proxmox-lab")
	m := h.machine(prov, "zoomies-proxmox-lab-1")
	viewer := h.token("reader", store.RoleViewer)

	names := h.mcpToolNames(viewer)
	for _, tool := range providerReadTools {
		if !slices.Contains(names, tool) {
			t.Errorf("%s must be offered to a viewer token, got %v", tool, names)
		}
	}

	got := h.mcpTool(viewer, "list_providers", map[string]any{})
	if got.IsError {
		t.Fatalf("list_providers failed: %s", resultText(got))
	}
	text := resultText(got)
	var list struct {
		Items []struct {
			ID                    string `json:"id"`
			Name                  string `json:"name"`
			CredentialsConfigured bool   `json:"credentials_configured"`
			Owned                 int    `json:"owned"`
		} `json:"items"`
		ProvidersAvailable *bool `json:"providers_available"`
		Renting            *struct {
			State string          `json:"state"`
			Pools json.RawMessage `json:"pools"`
		} `json:"renting"`
	}
	if err := json.Unmarshal([]byte(text), &list); err != nil {
		t.Fatalf("not JSON: %v\n%s", err, text)
	}
	if len(list.Items) != 1 || list.Items[0].ID != prov.ID || !list.Items[0].CredentialsConfigured {
		t.Errorf("providers = %+v, want %s with its credential reported as configured", list.Items, prov.ID)
	}
	if list.ProvidersAvailable == nil {
		t.Errorf("list_providers must say whether this controller can rent at all: %s", text)
	}
	// A viewer cannot read provider.enabled, so renting is how an assistant
	// learns whether it is the cause. A fresh harness has a provider and renting
	// off, so the answer is one of the states and never a missing key.
	if list.Renting == nil || list.Renting.State == "" || string(list.Renting.Pools) == "null" {
		t.Errorf("list_providers must carry the renting answer, with pools never null: %s", text)
	}
	// The credential was sealed from this string; nothing a tool returns may carry
	// it, in the clear or by any other name.
	if strings.Contains(text, "prv-token-proxmox-lab") {
		t.Errorf("a provider's credential reached an MCP client: %s", text)
	}

	pairs := h.mcpTool(viewer, "provider_pairings", map[string]any{"pool_id": pool.ID})
	if pairs.IsError || !strings.Contains(resultText(pairs), prov.ID) || !strings.Contains(resultText(pairs), pool.ID) {
		t.Errorf("provider_pairings for the pool = %q (error %v)", resultText(pairs), pairs.IsError)
	}

	machines := h.mcpTool(viewer, "list_machines", map[string]any{"provider_id": prov.ID})
	if machines.IsError || !strings.Contains(resultText(machines), m.ID) {
		t.Errorf("list_machines = %q (error %v), want machine %s", resultText(machines), machines.IsError, m.ID)
	}
}

// A token narrowed to other resources is offered the tools and refused on the
// route, in the controller's own words: the scope it is missing, not "forbidden".
// providers:read and machines:read are separate scopes, and one does not open the
// other, so a token minted to watch providers cannot also list the machines'
// addresses.
func TestProviderToolsFollowTheTokensScopesOnTheRoute(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	prov := h.provider("proxmox-lab")
	h.machine(prov, "zoomies-proxmox-lab-1")

	poolsOnly := h.token("pools-only", store.RoleOperator, "pools:read")
	providersOnly := h.token("providers-only", store.RoleViewer, "providers:read")

	for tool, scope := range map[string]string{
		"list_providers":    "providers:read",
		"provider_pairings": "providers:read",
		"list_machines":     "machines:read",
	} {
		r := h.mcpTool(poolsOnly, tool, map[string]any{})
		if !r.IsError || !strings.Contains(resultText(r), scope) {
			t.Errorf("%s with a pools:read token = %q (error %v), want a refusal naming %s", tool, resultText(r), r.IsError, scope)
		}
	}
	// The token can still do what it was minted for.
	if r := h.mcpTool(poolsOnly, "list_pools", map[string]any{}); r.IsError || !strings.Contains(resultText(r), pool.ID) {
		t.Errorf("list_pools with a pools:read token = %q", resultText(r))
	}

	if r := h.mcpTool(providersOnly, "list_providers", map[string]any{}); r.IsError {
		t.Errorf("list_providers with a providers:read token was refused: %s", resultText(r))
	}
	if r := h.mcpTool(providersOnly, "list_machines", map[string]any{}); !r.IsError || !strings.Contains(resultText(r), "machines:read") {
		t.Errorf("list_machines with a providers:read token = %q (error %v), want a refusal naming machines:read", resultText(r), r.IsError)
	}
}

// No MCP tool configures, pauses or drains a provider or a machine. Those routes
// are an administrator's or an operator's and stay with a person, so a role that
// reaches them over REST still finds nothing here to reach them with.
func TestNoMCPToolReachesAProviderOrMachineWriteRoute(t *testing.T) {
	h := newHarness(t)
	admin := h.token("boss", store.RoleAdmin)
	for _, name := range h.mcpToolNames(admin) {
		if strings.Contains(name, "provider") || strings.Contains(name, "machine") {
			if !slices.Contains(providerReadTools, name) {
				t.Errorf("%s is an MCP tool about providers or machines and is not one of the read tools", name)
			}
		}
	}
}

package api

import (
	"encoding/json"
	"net/http"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/mcp"
	"github.com/eyupio/zoomies/internal/store"
)

// mcpCall posts one JSON-RPC request to /mcp the way an MCP client does.
func (h *harness) mcpCall(token, method string, params any) *response {
	h.t.Helper()
	return h.do(request{
		method: http.MethodPost, path: "/mcp", token: token, noOrigin: true,
		body:    map[string]any{"jsonrpc": "2.0", "id": 1, "method": method, "params": params},
		headers: map[string]string{"Accept": "application/json, text/event-stream"},
	})
}

type mcpReply struct {
	Result json.RawMessage `json:"result"`
	Error  *mcp.RPCError   `json:"error"`
}

func decodeMCP(t *testing.T, resp *response) mcpReply {
	t.Helper()
	if resp.status != http.StatusOK {
		t.Fatalf("MCP request answered %d: %s", resp.status, resp.body)
	}
	var r mcpReply
	if err := json.Unmarshal(resp.body, &r); err != nil {
		t.Fatalf("the answer was not JSON-RPC: %v\n%s", err, resp.body)
	}
	if r.Error != nil {
		t.Fatalf("protocol error %d: %s", r.Error.Code, r.Error.Message)
	}
	return r
}

func (h *harness) mcpTool(token, name string, args any) mcp.CallResult {
	h.t.Helper()
	var r mcp.CallResult
	if err := json.Unmarshal(decodeMCP(h.t, h.mcpCall(token, "tools/call", map[string]any{"name": name, "arguments": args})).Result, &r); err != nil {
		h.t.Fatal(err)
	}
	return r
}

func (h *harness) mcpToolNames(token string) []string {
	h.t.Helper()
	var list struct {
		Tools []struct {
			Name string `json:"name"`
		} `json:"tools"`
	}
	if err := json.Unmarshal(decodeMCP(h.t, h.mcpCall(token, "tools/list", nil)).Result, &list); err != nil {
		h.t.Fatal(err)
	}
	var names []string
	for _, tool := range list.Tools {
		names = append(names, tool.Name)
	}
	return names
}

func resultText(r mcp.CallResult) string {
	var b strings.Builder
	for _, c := range r.Content {
		b.WriteString(c.Text)
		b.WriteString("\n")
	}
	return b.String()
}

// The endpoint is for agents, which send a token. A session cookie is refused
// even though it would authenticate anywhere else, so that a page the operator
// visits cannot drive an agent's endpoint with the operator's own session.
func TestMCPOverHTTPTakesABearerTokenAndNothingElse(t *testing.T) {
	h := newHarness(t)

	anon := h.mcpCall("", "tools/list", nil)
	if anon.status != http.StatusUnauthorized {
		t.Fatalf("no credential must be 401, got %d: %s", anon.status, anon.body)
	}
	if !strings.HasPrefix(anon.header.Get("WWW-Authenticate"), "Bearer") {
		t.Errorf("a 401 must carry a Bearer challenge so the client knows to ask for a token, got %q", anon.header.Get("WWW-Authenticate"))
	}
	if !strings.Contains(string(anon.body), "tokens create") {
		t.Errorf("the refusal must say how to get a token: %s", anon.body)
	}

	admin, _ := h.user("alice", store.RoleAdmin)
	cookie := h.do(request{
		method: http.MethodPost, path: "/mcp", cookie: h.session(admin),
		body: map[string]any{"jsonrpc": "2.0", "id": 1, "method": "tools/list"},
	})
	if cookie.status != http.StatusUnauthorized {
		t.Errorf("a session cookie must not open the MCP endpoint, got %d", cookie.status)
	}

	if names := h.mcpToolNames(h.token("agent", store.RoleViewer)); !slices.Contains(names, "get_job") {
		t.Errorf("a viewer token must be offered the read-only tools, got %v", names)
	}
}

// The actions follow the token: a tool the role cannot use is not offered, so
// the model never plans around it, and asking anyway says which role is
// missing. Every action tool needs an entry, or a new one would be offered to
// nobody without anyone deciding that.
func TestMCPOverHTTPOffersActionsAsFarAsTheTokensRoleReaches(t *testing.T) {
	for _, tool := range mcp.ActionTools() {
		if _, ok := mcpToolActions[tool]; !ok {
			t.Errorf("MCP action tool %s has no entry in mcpToolActions", tool)
		}
	}

	h := newHarness(t)
	viewer := h.token("reader", store.RoleViewer)
	operator := h.token("actor", store.RoleOperator)

	// Each tool is offered exactly as far as its own action's role reaches:
	// the fleet's actions are an operator's, while publishing a note is a
	// reader's, gated again on the route by membership and consent.
	names := h.mcpToolNames(viewer)
	for tool, action := range mcpToolActions {
		want := store.RoleViewer.AtLeast(action.MinRole())
		if slices.Contains(names, tool) != want {
			t.Errorf("%s offered to a viewer token = %v, want %v (it needs %s): %v", tool, !want, want, action.MinRole(), names)
		}
	}
	r := h.mcpTool(viewer, "drain_runner", map[string]any{"runner_id": "run_x"})
	if !r.IsError || !strings.Contains(resultText(r), "operator") {
		t.Errorf("asking for an action the role cannot use must name the role, got %s", resultText(r))
	}

	names = h.mcpToolNames(operator)
	for tool := range mcpToolActions {
		if mcp.IsAdminTool(tool) {
			continue
		}
		if !slices.Contains(names, tool) {
			t.Errorf("%s must be offered to an operator token, got %v", tool, names)
		}
	}
}

// A tool call is the route itself, with the caller's token: the record comes
// back as the API renders it, and a refusal the route makes -- a busy runner
// is not drained without a person confirming it -- reaches the agent intact.
func TestMCPOverHTTPCallsTheRoutesWithTheCallersToken(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux")
	host := h.host("boogie")
	job := h.job(pool, store.JobQueued)
	idle := h.runner(pool, host, store.RunnerIdle)
	busy := h.runner(pool, host, store.RunnerBusy)
	operator := h.token("actor", store.RoleOperator)

	got := h.mcpTool(operator, "get_job", map[string]any{"job_id": job.ID})
	if got.IsError {
		t.Fatalf("get_job failed: %s", resultText(got))
	}
	var doc struct {
		Job struct {
			ID string `json:"id"`
		} `json:"job"`
		Explanation json.RawMessage `json:"explanation"`
	}
	if err := json.Unmarshal([]byte(got.Content[0].Text), &doc); err != nil || doc.Job.ID != job.ID || len(doc.Explanation) == 0 {
		t.Errorf("get_job must return the job and its explanation, got %s (%v)", got.Content[0].Text, err)
	}

	missing := h.mcpTool(operator, "get_job", map[string]any{"job_id": "job_nope"})
	if !missing.IsError || !strings.Contains(resultText(missing), "list_jobs") {
		t.Errorf("an unknown job must say where the IDs come from, got %s", resultText(missing))
	}

	if r := h.mcpTool(operator, "drain_runner", map[string]any{"runner_id": idle.ID}); r.IsError {
		t.Fatalf("draining an idle runner failed: %s", resultText(r))
	}
	if after, _ := h.st.GetRunner(h.ctx, idle.ID); after.State != store.RunnerDraining {
		t.Errorf("the drain must have happened, runner is %s", after.State)
	}

	r := h.mcpTool(operator, "drain_runner", map[string]any{"runner_id": busy.ID})
	if !r.IsError || !strings.Contains(resultText(r), "five minutes") {
		t.Errorf("a busy runner's drain must come back as the route's own refusal, got %s", resultText(r))
	}
	if after, _ := h.st.GetRunner(h.ctx, busy.ID); after.State != store.RunnerBusy {
		t.Errorf("a refused drain must leave the busy runner alone, it is %s", after.State)
	}
}

// What the transport itself answers, before any tool runs.
func TestMCPOverHTTPAnswersTheTransportsOwnCases(t *testing.T) {
	h := newHarness(t)
	viewer := h.token("reader", store.RoleViewer)

	var init struct {
		ProtocolVersion string `json:"protocolVersion"`
		Instructions    string `json:"instructions"`
	}
	if err := json.Unmarshal(decodeMCP(t, h.mcpCall(viewer, "initialize", map[string]any{"protocolVersion": "2025-06-18"})).Result, &init); err != nil {
		t.Fatal(err)
	}
	if init.ProtocolVersion != "2025-06-18" || !strings.Contains(init.Instructions, "untrusted") {
		t.Errorf("initialize must negotiate and carry the untrusted-data instructions: %+v", init)
	}

	note := h.do(request{method: http.MethodPost, path: "/mcp", token: viewer, noOrigin: true,
		body: map[string]any{"jsonrpc": "2.0", "method": "notifications/initialized"}})
	if note.status != http.StatusAccepted || len(note.body) != 0 {
		t.Errorf("a notification must be 202 with no body, got %d %q", note.status, note.body)
	}

	get := h.do(request{method: http.MethodGet, path: "/mcp", token: viewer, noOrigin: true})
	if get.status != http.StatusMethodNotAllowed || get.header.Get("Allow") != http.MethodPost {
		t.Errorf("a GET must be 405 naming POST, not the SPA, got %d %q", get.status, get.header.Get("Allow"))
	}

	old := h.do(request{method: http.MethodPost, path: "/mcp", token: viewer, noOrigin: true,
		body:    map[string]any{"jsonrpc": "2.0", "id": 1, "method": "ping"},
		headers: map[string]string{"MCP-Protocol-Version": "1999-01-01"}})
	if old.status != http.StatusBadRequest {
		t.Errorf("an unsupported MCP-Protocol-Version must be 400, got %d", old.status)
	}

	// The specification asks for the Origin check, against DNS rebinding.
	foreign := h.do(request{method: http.MethodPost, path: "/mcp", token: viewer, origin: "https://evil.example",
		body: map[string]any{"jsonrpc": "2.0", "id": 1, "method": "ping"}})
	if foreign.status != http.StatusForbidden {
		t.Errorf("a request from a foreign origin must be 403, got %d", foreign.status)
	}
	if cache := h.mcpCall(viewer, "ping", nil).header.Get("Cache-Control"); cache != "no-store" {
		t.Errorf("an MCP answer carries fleet data and must not be cached, got %q", cache)
	}
}

// A hundred jobs with their steps overflowed a client's output limit at about
// ten. Without them a full page of a hundred has to fit well inside 25k tokens;
// JSON runs at three bytes a token or worse, so 75 KB is the ceiling.
func TestMCPListJobsWithoutStepsFitsAHundredJobsInAModelsContext(t *testing.T) {
	h := newHarness(t)
	pool := h.pool(h.installation(), "linux")
	h.releaseJobs(pool, "v1.3.3", 100, 10_000, time.Now().Add(-2*time.Hour))
	viewer := h.token("reader", store.RoleViewer)

	const budget = 25_000 * 3
	summary := h.mcpTool(viewer, "list_jobs", map[string]any{"limit": 100})
	if summary.IsError {
		t.Fatalf("list_jobs failed: %s", resultText(summary))
	}
	text := resultText(summary)
	var page struct {
		Items []map[string]any `json:"items"`
	}
	if err := json.Unmarshal([]byte(text), &page); err != nil || len(page.Items) != 100 {
		t.Fatalf("want 100 jobs, got %d (%v)", len(page.Items), err)
	}
	if _, has := page.Items[0]["steps"]; has {
		t.Errorf("steps must be off by default for MCP: %v", page.Items[0])
	}
	if len(text) > budget {
		t.Errorf("100 summaries are %d bytes, over the %d-byte proxy for 25k tokens", len(text), budget)
	}
	t.Logf("100 job summaries: %d bytes", len(text))

	full := resultText(h.mcpTool(viewer, "list_jobs", map[string]any{"limit": 10, "include_steps": true}))
	if !strings.Contains(full, `"steps":[{`) {
		t.Errorf("include_steps=true must bring the steps back")
	}
}

