// An agent that changes a pool's sizing goes through the pool's own route with
// the caller's token, and the pool keeps everything it had: the API replaces
// `resources` whole, so a tool that sent only the share would have cleared the
// pool's smallest runner in the same call.
func TestMCPUpdatePoolChangesTheNamedSettingAndKeepsTheRest(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "builders")
	pool.DockerMode = store.DockerDinD
	pool.Resources.MinCPUs, pool.Resources.MinMemoryMB = 1, 1536
	pool.Resources.DaemonCPUSharePercent, pool.Resources.DaemonMemorySharePercent = 35, 15
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	operator := h.token("actor", store.RoleOperator)
	viewer := h.token("reader", store.RoleViewer)

	if r := h.mcpTool(viewer, "update_pool", map[string]any{"pool_id": pool.ID, "daemon_cpu_share_percent": 20, "expect": map[string]any{"daemon_cpu_share_percent": 35}}); !r.IsError || !strings.Contains(resultText(r), "operator") {
		t.Errorf("a viewer asking to change a pool must be told which role is missing, got %s", resultText(r))
	}

	r := h.mcpTool(operator, "update_pool", map[string]any{"pool_id": pool.ID, "daemon_cpu_share_percent": 20, "expect": map[string]any{"daemon_cpu_share_percent": 35}})
	if r.IsError {
		t.Fatalf("update_pool failed: %s", resultText(r))
	}
	after, err := h.st.GetPool(h.ctx, pool.ID)
	if err != nil {
		t.Fatal(err)
	}
	res := after.Resources
	if res.DaemonCPUSharePercent != 20 {
		t.Errorf("the share must have changed, is %d", res.DaemonCPUSharePercent)
	}
	if res.MinCPUs != 1 || res.MinMemoryMB != 1536 || res.DaemonMemorySharePercent != 15 {
		t.Errorf("everything the call did not name must be kept: %+v", res)
	}
	if !strings.Contains(resultText(r), `"daemon_cpu_share_percent":{"before":35,"after":20}`) {
		t.Errorf("the answer must say what changed, got %s", resultText(r))
	}

	// The smallest runner can be lowered on its own, and the shares survive it.
	if r := h.mcpTool(operator, "update_pool", map[string]any{"pool_id": pool.ID, "min_cpus": 0.75, "min_memory_mb": 1024, "expect": map[string]any{"min_cpus": 1, "min_memory_mb": 1536}}); r.IsError {
		t.Fatalf("lowering the minimum failed: %s", resultText(r))
	}
	after, _ = h.st.GetPool(h.ctx, pool.ID)
	if after.Resources.MinCPUs != 0.75 || after.Resources.MinMemoryMB != 1024 || after.Resources.DaemonCPUSharePercent != 20 {
		t.Errorf("the minimum must move and the shares stay: %+v", after.Resources)
	}
}

func TestMCPUpdateHostChangesTheNamedSettingAndKeepsTheRest(t *testing.T) {
	h := newHarness(t)
	host := h.host("boogie")
	host.CPUs, host.MemoryMB = 8, 32768
	if err := h.st.UpdateHost(h.ctx, host); err != nil {
		t.Fatal(err)
	}
	profile := store.RunnerProfile{
		Minimum:  store.RunnerSize{CPUs: 1},
		Standard: store.RunnerStandard{CPUs: 6},
		Tmpfs:    store.HostTmpfs{MaxMB: 2048},
	}
	if err := h.st.PatchHost(h.ctx, host.ID, store.HostChanges{RunnerProfile: &profile}); err != nil {
		t.Fatal(err)
	}
	operator := h.token("actor", store.RoleOperator)

	r := h.mcpTool(operator, "update_host", map[string]any{"host_id": host.ID, "standard_cpus": 2.25, "reserve_cpus": 2, "expect": map[string]any{"standard_cpus": 6, "reserve_cpus": 0}})
	if r.IsError {
		t.Fatalf("update_host failed: %s", resultText(r))
	}
	after, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	if after.RunnerProfile.Standard.CPUs != 2.25 || after.ReserveCPUs != 2 {
		t.Errorf("the named settings must change: standard %v reserve %d", after.RunnerProfile.Standard.CPUs, after.ReserveCPUs)
	}
	if after.RunnerProfile.Minimum.CPUs != 1 || after.RunnerProfile.Tmpfs.MaxMB != 2048 {
		t.Errorf("the rest of the profile must be kept: %+v", after.RunnerProfile)
	}

	// Stopping a host taking runners is a person's decision, not an agent's.
	if r := h.mcpTool(operator, "update_host", map[string]any{"host_id": host.ID, "capacity": 0, "expect": map[string]any{"capacity": host.Capacity}}); !r.IsError {
		t.Errorf("a capacity of zero must be refused, got %s", resultText(r))
	}
	if got, _ := h.st.GetHost(h.ctx, host.ID); got.Capacity != host.Capacity {
		t.Errorf("a refused call must change nothing, capacity is %d", got.Capacity)
	}
}

// The administrator tools need two things at once: a role that reaches them and
// the controller's switch. Either alone offers nothing, and an agent that asks
// anyway is told which of the two is missing, so the person can fix the right one.
func TestMCPAdministratorToolsNeedTheSwitchAndTheRole(t *testing.T) {
	admin := func(h *harness) string { return h.token("boss", store.RoleAdmin) }

	off := newHarness(t)
	for _, tool := range mcp.ActionTools() {
		if mcp.IsAdminTool(tool) && slices.Contains(off.mcpToolNames(admin(off)), tool) {
			t.Errorf("%s must not be offered while security.mcp_admin_tools is off", tool)
		}
	}
	r := off.mcpTool(admin(off), "update_settings", map[string]any{"changes": map[string]any{"retention.jobs": "720h"}})
	if !r.IsError || !strings.Contains(resultText(r), "security.mcp_admin_tools") {
		t.Errorf("asking while the switch is off must name it, got %s", resultText(r))
	}

	on := newHarness(t, func(c *config.Config) { c.Security.MCPAdminTools = true })
	names := on.mcpToolNames(admin(on))
	for _, tool := range mcp.ActionTools() {
		if mcp.IsAdminTool(tool) && !slices.Contains(names, tool) {
			t.Errorf("%s must be offered to an administrator once the switch is on, got %v", tool, names)
		}
	}
	operator := on.mcpToolNames(on.token("actor", store.RoleOperator))
	for _, tool := range mcp.ActionTools() {
		if mcp.IsAdminTool(tool) && slices.Contains(operator, tool) {
			t.Errorf("%s must not be offered to an operator even with the switch on", tool)
		}
	}

	denied := on.mcpTool(admin(on), "update_settings", map[string]any{"changes": map[string]any{"security.disable_auth": true}})
	if !denied.IsError || !strings.Contains(resultText(denied), "cannot be changed over MCP") {
		t.Errorf("a security key must be refused even for an administrator, got %s", resultText(denied))
	}
}

// The tools never send confirm=true, so a refusal that says to send it again with it is
// advice an agent cannot follow. The refusal itself still stands: the change is not made.
func TestAnAgentRefusedAChangeIsNotToldToSendConfirm(t *testing.T) {
	h := newHarness(t)
	host := h.measuredHost("only")
	pool := h.pool(h.installation(), "small")
	pool.Resources = store.Resources{CPUs: 2, MemoryMB: 2048}
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	operator := h.token("agent", store.RoleOperator)

	r := h.mcpTool(operator, "update_host", map[string]any{"host_id": host.ID, "min_cpus": 3, "expect": map[string]any{"min_cpus": 0}})
	if !r.IsError || !strings.Contains(resultText(r), "nowhere to run") {
		t.Fatalf("a change that strands the only pool must be refused: %s", resultText(r))
	}
	if strings.Contains(resultText(r), "confirm=true") || !strings.Contains(resultText(r), "a person") {
		t.Errorf("the agent is sent to a flag it cannot send: %s", resultText(r))
	}
	if stored, _ := h.st.GetHost(h.ctx, host.ID); stored.RunnerProfile.Set() {
		t.Fatalf("a refused change was written: %+v", stored.RunnerProfile)
	}
}

// The two-call wait on a fleet that has been busy. With more frames in the
// ring than one answer carries, a first call that started from the ring would
// hand back a page of the past and a cursor in the middle of it, and the second
// call would answer at once with the next page instead of waiting. Started from
// the present, the second call is held until something new happens and is
// answered with that alone.
func TestMCPWaitForChangeOnABusyFleetHoldsTheSecondCallForWhatIsNew(t *testing.T) {
	h := newHarness(t)
	token := h.token("watcher", store.RoleViewer)
	bus := h.ctrl.Events()
	publishJobs(h, 120)

	// The first call is a cursor, at once: one that waited here would hold for
	// the whole of its seconds on an idle bus and still look like a cursor.
	asked := time.Now()
	first := h.mcpTool(token, "wait_for_change", map[string]any{})
	if elapsed := time.Since(asked); elapsed > 2*time.Second {
		t.Errorf("the first call took %v, want a cursor at once", elapsed)
	}
	if first.IsError {
		t.Fatalf("the first call failed: %s", resultText(first))
	}
	text := resultText(first)
	if strings.Contains(text, "job.updated") {
		t.Fatalf("the first call answered the past:\n%.400s", text)
	}
	cursor := ""
	for line := range strings.SplitSeq(text, "\n") {
		if c, ok := strings.CutPrefix(line, "next: "); ok {
			cursor = c
		}
	}
	if cursor != bus.WireID(bus.LastID()) {
		t.Fatalf("the first call's cursor is %q, want the present %q:\n%s", cursor, bus.WireID(bus.LastID()), text)
	}

	go func() {
		time.Sleep(300 * time.Millisecond)
		bus.Publish(events.KindJobUpdated, "job:job_new", map[string]any{"id": "job_new", "state": "queued"})
	}()
	started := time.Now()
	second := h.mcpTool(token, "wait_for_change", map[string]any{"since": cursor, "seconds": 10})
	if elapsed := time.Since(started); elapsed < 250*time.Millisecond {
		t.Errorf("the second call answered after %v, want it held until the new frame", elapsed)
	}
	got := resultText(second)
	if n := strings.Count(got, "job.updated"); n != 1 || !strings.Contains(got, "job:job_new") {
		t.Errorf("the second call answered %d frames, want only the new one:\n%.600s", n, got)
	}
}

// A caller that holds more answers at once than the budget allows is told to
// wait, rather than being allowed to pin this process's memory: every tool
// call buffers a whole answer, and both model-facing entry points reach every
// route through the same place.
func TestAToolCallBeyondItsCallersBudgetIsRefusedWithTheSentence(t *testing.T) {
	h := newHarness(t)
	token := h.token("agent", store.RoleViewer)

	// The identity the endpoint resolves, which is the key the budget counts
	// by, taken from the same call the endpoint makes.
	id, err := h.ctrl.Auth().Authenticate(h.ctx, auth.AuthInput{Authorization: "Bearer " + token})
	if err != nil {
		t.Fatalf("authenticating the token: %v", err)
	}
	key := id.String()
	for i := 0; i < inProcessPerCaller; i++ {
		if ok, _ := h.api.inProcessBudget.take(key); !ok {
			t.Fatalf("slot %d for the caller must be allowed", i+1)
		}
	}

	r := h.mcpTool(token, "list_runners", nil)
	if !r.IsError {
		t.Fatalf("a call beyond the caller's budget must be refused, got %s", resultText(r))
	}
	if !strings.Contains(resultText(r), "wait for one to finish and ask again") {
		t.Errorf("the refusal must say what to do about it, got %s", resultText(r))
	}

	// With the answers in flight handed back, the same caller is served again.
	h.api.inProcessBudget.give(key)
	h.api.inProcessBudget.give(key)
	if after := h.mcpTool(token, "list_runners", nil); after.IsError {
		t.Errorf("a call within the caller's budget must be answered: %s", resultText(after))
	}
}

package api

import (
	"fmt"
	"net/http"
	"slices"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/migrate"
	"github.com/eyupio/zoomies/internal/store"
)

const (
	ciBefore = `name: CI

on: [push]

jobs:
  build:
    runs-on: ubuntu-latest      # the cheap one
    steps:
      - uses: actions/checkout@v4
  windows:
    runs-on: windows-latest
    steps:
      - run: build.ps1
  matrix:
    runs-on: ${{ matrix.os }}
    steps:
      - run: make test
`
	releaseBefore = "jobs:\n  ship:\n    runs-on: [ubuntu-22.04]\n"
)

// migrationHarness is a fleet with one Linux pool, two repositories with
// workflows and one without.
func migrationHarness(t *testing.T) (*harness, *store.Installation, string) {
	t.Helper()
	h := newHarness(t)
	inst := h.installation()

	pool := h.pool(inst, "zoomies-linux-x64")
	pool.Labels = store.StringSlice(store.BrandLabels([]string{"zoomies-linux-x64", "linux", "x64"}))
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}

	h.gh.AddWorkflow("acme/widgets", ".github/workflows/ci.yml", ciBefore)
	h.gh.AddWorkflow("acme/widgets", ".github/workflows/release.yml", releaseBefore)
	h.gh.AddWorkflow("acme/api", ".github/workflows/ci.yml", ciBefore)
	h.gh.AddRepo("acme/site")

	_, cookie := h.user("migrator", store.RoleOperator)
	return h, inst, cookie
}

func TestMigrationPlanProposesAMappingAndADiff(t *testing.T) {
	h, inst, cookie := migrationHarness(t)

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/migrations/plan", cookie: cookie,
		body: map[string]any{"installation_id": inst.ID}})
	resp.mustStatus(t, http.StatusOK, "plan")

	var plan migrationPlanResponse
	resp.into(t, &plan)

	// Every repository is reported, including the one with nothing to do:
	// "no workflows" is an answer, not an omission.
	if len(plan.Repositories) != 3 {
		t.Fatalf("repositories = %d, want all three", len(plan.Repositories))
	}

	// The server proposed the only pool for the Ubuntu labels, and nothing at
	// all for Windows, because no pool in this fleet runs it.
	if plan.Mapping["ubuntu-latest"] != "zoomies-linux-x64" {
		t.Errorf("mapping = %v, want ubuntu-latest on the Linux pool", plan.Mapping)
	}
	if plan.Mapping["ubuntu-22.04"] != "zoomies-linux-x64" {
		t.Errorf("mapping = %v, want ubuntu-22.04 on the Linux pool", plan.Mapping)
	}
	if _, ok := plan.Mapping["windows-latest"]; ok {
		t.Errorf("mapping = %v, want no proposal for windows-latest: nothing here runs Windows", plan.Mapping)
	}
	if !slices.Contains(plan.Unmapped, "windows-latest") {
		t.Errorf("unmapped = %v, want windows-latest named so the operator can decide", plan.Unmapped)
	}

	// Two repositories, three files, three Ubuntu jobs.
	if plan.Counts.Repos != 2 || plan.Counts.Workflows != 3 || plan.Counts.Jobs != 3 {
		t.Errorf("counts = %+v, want 2 repos / 3 workflows / 3 jobs", plan.Counts)
	}

	widgets := repoPlan(t, plan, "acme/widgets")
	ci := workflowPlan(t, widgets, ".github/workflows/ci.yml")
	if len(ci.Rewrites) != 1 || ci.Rewrites[0].Job != "build" {
		t.Fatalf("rewrites = %+v, want just the build job", ci.Rewrites)
	}
	if ci.Rewrites[0].To != "zoomies-linux-x64" {
		t.Errorf("to = %q, want the pool's label", ci.Rewrites[0].To)
	}
	// The Windows job and the matrix job are both left alone, each with a
	// reason a person can act on.
	if len(ci.Skips) != 2 {
		t.Fatalf("skips = %+v, want the windows and matrix jobs", ci.Skips)
	}
	if !strings.Contains(ci.Diff, "-    runs-on: ubuntu-latest      # the cheap one") ||
		!strings.Contains(ci.Diff, "+    runs-on: zoomies-linux-x64      # the cheap one") {
		t.Errorf("diff does not show the change with its comment intact:\n%s", ci.Diff)
	}

	if len(plan.Pools) != 1 || plan.Pools[0].RunsOn != "zoomies-linux-x64" {
		t.Errorf("pools = %+v, want the one pool with its runs-on value", plan.Pools)
	}
	// Nothing was written.
	if got, _ := h.gh.FileContent("acme/widgets", ".github/workflows/ci.yml"); got != ciBefore {
		t.Error("the plan endpoint modified a workflow")
	}
}

