package api

import (
	"encoding/json"
	"net/http"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

type problemsBody struct {
	OK    bool `json:"ok"`
	Items []struct {
		Code     string `json:"code"`
		Audience string `json:"audience"`
	} `json:"items"`
}

func problemsSeenBy(t *testing.T, h *harness, role store.Role) problemsBody {
	t.Helper()
	u, _ := h.user(string(role)+"-reader", role)
	resp := h.do(request{method: http.MethodGet, path: "/api/v1/problems", cookie: h.session(u)})
	if resp.status != http.StatusOK {
		t.Fatalf("GET /problems as %s = %d: %s", role, resp.status, resp.body)
	}
	var out problemsBody
	if err := json.Unmarshal(resp.body, &out); err != nil {
		t.Fatalf("decoding the problems list: %v", err)
	}
	return out
}

// The problems drawer is the page an operator opens when something is wrong,
// and on an instance one team operates for another there are two things
// wrong and two people to tell. A fleet told the controller's lease was lost
// can do nothing about it; it also learns how the process is deployed.
func TestTheProblemsDrawerIsTwoListsNotOne(t *testing.T) {
	h := newHarness(t)
	// A fleet problem to actually have one. A bare harness raises none, so
	// the comparison below was passing by iterating over nothing -- which is
	// how "the platform sees the fleet's too" went out believed and wrong.
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	h.job(pool, store.JobQueued)

	asAdmin := problemsSeenBy(t, h, store.RoleAdmin)
	if len(asAdmin.Items) == 0 {
		t.Fatal("the fleet's list is empty, so nothing below is being compared")
	}
	for _, p := range asAdmin.Items {
		if p.Audience == "platform" {
			t.Errorf("an administrator was shown %q, which is the platform's", p.Code)
		}
		if p.Audience == "" {
			t.Errorf("%q reached the fleet with no audience decided for it", p.Code)
		}
	}

	// A validator finding is the clearest case: every one names a setting,
	// and the dangerous ones name what the process binds and trusts. The
	// harness runs with authentication off, so auth.disabled is raised.
	asPlatform := problemsSeenBy(t, h, store.RolePlatform)
	var platformSaw bool
	for _, p := range asPlatform.Items {
		if p.Audience == "platform" {
			platformSaw = true
		}
	}
	if !platformSaw {
		t.Fatal("the platform's own list carries nothing, so this proves nothing about the split")
	}
	// And it still sees the fleet's, which is the half a first draft lost:
	// the account that installed a single-team instance holds platform, and
	// its drawer is the only one there is.
	for _, want := range asAdmin.Items {
		var found bool
		for _, got := range asPlatform.Items {
			if got.Code == want.Code {
				found = true
				break
			}
		}
		if !found {
			t.Errorf("the platform cannot see %q, which the fleet can; on a single-team instance that is the whole drawer gone", want.Code)
		}
	}
	if len(asPlatform.Items) <= len(asAdmin.Items) {
		t.Errorf("the platform saw %d problems and the fleet %d; the platform sees its own as well as theirs is not the claim, but it must see more here",
			len(asPlatform.Items), len(asAdmin.Items))
	}
}

// OK is what the drawer renders "nothing needs your attention" from. Computed
// before the filter it would say the opposite of what the list shows, and
// send somebody looking for a problem they are not allowed to see.
func TestAFleetWithNothingWrongIsToldSoEvenWhileTheProcessHasTroubles(t *testing.T) {
	h := newHarness(t)

	asAdmin := problemsSeenBy(t, h, store.RoleAdmin)
	if asAdmin.OK != (len(asAdmin.Items) == 0) {
		t.Errorf("ok = %v with %d items: the flag and the list disagree", asAdmin.OK, len(asAdmin.Items))
	}

	// And the platform's own view is computed the same way.
	asPlatform := problemsSeenBy(t, h, store.RolePlatform)
	if asPlatform.OK != (len(asPlatform.Items) == 0) {
		t.Errorf("ok = %v with %d items for the platform", asPlatform.OK, len(asPlatform.Items))
	}
}

// The support bundle stays the fleet's to collect -- "send me a bundle" is
// the platform's first support question -- but what it carries about the
// machine the process runs on is reduced to the build it all ran on.
func TestTheFleetsBundleIdentifiesTheBuildAndNotTheMachine(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("fleet-admin", store.RoleAdmin)

	resp := h.do(request{method: http.MethodGet, path: "/api/v1/diagnostics/bundle", cookie: h.session(admin)})
	if resp.status != http.StatusOK {
		t.Fatalf("the fleet cannot collect a bundle: %d %s", resp.status, resp.body)
	}
	var doc struct {
		Instance struct {
			Version          string `json:"version"`
			Go               string `json:"go"`
			OS               string `json:"os"`
			CPUs             int    `json:"cpus"`
			DatabasePath     string `json:"database_path"`
			EventSubscribers int    `json:"event_subscribers"`
		} `json:"instance"`
	}
	if err := json.Unmarshal(resp.body, &doc); err != nil {
		t.Fatalf("decoding the bundle: %v", err)
	}
	if doc.Instance.Version == "" || doc.Instance.Go == "" {
		t.Error("the fleet's bundle does not identify the build, which is the point of sending one")
	}
	for name, got := range map[string]any{
		"os": doc.Instance.OS, "cpus": doc.Instance.CPUs,
		"database_path": doc.Instance.DatabasePath, "event_subscribers": doc.Instance.EventSubscribers,
	} {
		switch v := got.(type) {
		case string:
			if v != "" {
				t.Errorf("the fleet's bundle describes the machine: %s = %q", name, v)
			}
		case int:
			if v != 0 {
				t.Errorf("the fleet's bundle describes the machine: %s = %d", name, v)
			}
		}
	}

	// The platform's bundle is whole, which is what makes it worth asking for.
	plat, _ := h.user("operator-of-record", store.RolePlatform)
	whole := h.do(request{method: http.MethodGet, path: "/api/v1/diagnostics/bundle", cookie: h.session(plat)})
	if !strings.Contains(string(whole.body), `"cpus"`) {
		t.Error("the platform's own bundle lost the machine it is about")
	}
}

// The bundle's problems are the drawer's, split the same way. A failed
// scheduled backup names the directory it could not write, so a bundle that
// carried the undivided list handed the fleet the machine's paths inside a
// document built to leave them out.
func TestTheFleetsBundleCarriesOnlyTheFleetsProblems(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("bundle-admin", store.RoleAdmin)

	resp := h.do(request{method: http.MethodGet, path: "/api/v1/diagnostics/bundle", cookie: h.session(admin)})
	if resp.status != http.StatusOK {
		t.Fatalf("the fleet cannot collect a bundle: %d %s", resp.status, resp.body)
	}
	var doc struct {
		Problems problemsBody `json:"problems"`
	}
	if err := json.Unmarshal(resp.body, &doc); err != nil {
		t.Fatalf("decoding the bundle: %v", err)
	}
	// The harness runs with authentication off, which raises a platform
	// finding, so an unfiltered list would carry at least that one.
	for _, p := range doc.Problems.Items {
		if p.Audience == "platform" {
			t.Errorf("the fleet's bundle carries %q, which is the platform's", p.Code)
		}
	}
}

package api

import (
	"net/http"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

const pastedKey = "-----BEGIN PRIVATE KEY-----\nbm90IGEgcmVhbCBrZXk=\n-----END PRIVATE KEY-----"

// The certificate this controller trusts for the hypervisor and the one a
// machine trusts for this controller are different certificates: a cluster's own
// authority has no reason to have signed the controller. Both are returned, both
// are kept by an edit that does not name them, and each is cleared only by
// being emptied itself.
func TestAProviderKeepsTheCertificateItsMachinesTrustApartFromTheOneItTrusts(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("admin", store.RoleAdmin)
	cookie := h.session(admin)
	clusters := strings.TrimSpace(setupCertificate(t))
	controllers := strings.TrimSpace(setupCertificate(t))

	created := h.do(request{method: http.MethodPost, path: "/api/v1/providers", cookie: cookie,
		body: map[string]any{"kind": "fake", "name": "proxmox-lab", "endpoint": "https://pve.example.com:8006",
			"credential": "zoomies@pve!ci=secret", "ca_pem": clusters, "machine_ca_pem": controllers,
			"settings": map[string]string{"zone": "zone-a"}}})
	created.mustStatus(t, http.StatusCreated, "create provider")
	var made providerResponse
	created.into(t, &made)
	if made.CAPEM != clusters || made.MachineCAPEM != controllers {
		t.Fatalf("the created provider answers ca_pem %q and machine_ca_pem %q", made.CAPEM, made.MachineCAPEM)
	}

	h.do(request{method: http.MethodPatch, path: "/api/v1/providers/" + made.ID, cookie: cookie,
		body: map[string]any{"name": "proxmox-lab-2"}}).mustStatus(t, http.StatusOK, "rename the provider")
	row, err := h.st.GetProvider(h.ctx, made.ID)
	if err != nil {
		t.Fatalf("GetProvider: %v", err)
	}
	if row.CAPEM != clusters || row.MachineCAPEM != controllers {
		t.Errorf("a rename changed the certificates to %q and %q", row.CAPEM, row.MachineCAPEM)
	}

	h.do(request{method: http.MethodPatch, path: "/api/v1/providers/" + made.ID, cookie: cookie,
		body: map[string]any{"machine_ca_pem": ""}}).mustStatus(t, http.StatusOK, "clear the machines' certificate")
	row, err = h.st.GetProvider(h.ctx, made.ID)
	if err != nil {
		t.Fatalf("GetProvider: %v", err)
	}
	if row.MachineCAPEM != "" {
		t.Errorf("an empty machine certificate left %q stored", row.MachineCAPEM)
	}
	if row.CAPEM != clusters {
		t.Errorf("clearing the machines' certificate changed the one for the hypervisor to %q", row.CAPEM)
	}
}

// Text that is not a certificate was accepted and stored, and found out later:
// a key in the box is copied into every machine, and a note in it fails on the
// first call to the hypervisor, with the reason in a log. It is refused on save
// instead, naming the box it is in, because two boxes now hold certificates and
// "invalid certificate" would not say which.
func TestACertificateFieldHoldingSomethingElseIsRefusedBySayingWhichAndWhy(t *testing.T) {
	for _, field := range []string{"ca_pem", "machine_ca_pem"} {
		for name, tc := range map[string]struct {
			text string
			want string
		}{
			"a private key":                  {pastedKey, "private key"},
			"a certificate with a key after": {strings.TrimSpace(setupCertificate(t)) + "\n" + pastedKey, "private key"},
			"text that is no certificate":    {"this is not a certificate", "BEGIN CERTIFICATE"},
		} {
			t.Run(field+" with "+name, func(t *testing.T) {
				h := newHarness(t)
				admin, _ := h.user("admin", store.RoleAdmin)
				cookie := h.session(admin)

				resp := h.do(request{method: http.MethodPost, path: "/api/v1/providers", cookie: cookie,
					body: map[string]any{"kind": "fake", "name": "proxmox-lab", "endpoint": "https://pve.example.com:8006",
						"credential": "zoomies@pve!ci=secret", field: tc.text, "settings": map[string]string{"zone": "zone-a"}}})
				resp.mustStatus(t, http.StatusUnprocessableEntity, "create a provider with "+name+" in "+field)
				body := string(resp.body)
				if !strings.Contains(body, `"field":"`+field+`"`) {
					t.Errorf("the refusal does not name %s: %s", field, truncate(resp.body))
				}
				if !strings.Contains(body, tc.want) {
					t.Errorf("the refusal does not say %q: %s", tc.want, truncate(resp.body))
				}
				if strings.Contains(body, "bm90IGEgcmVhbCBrZXk") {
					t.Errorf("the refusal repeats the key back: %s", truncate(resp.body))
				}
				if rows, err := h.st.ListProviders(h.ctx); err != nil || len(rows) != 0 {
					t.Errorf("a refused provider was stored anyway (%d rows, err %v)", len(rows), err)
				}
			})
		}
	}
}

// The check is of what a request names. A provider whose stored text is already
// not a certificate (it was accepted before this was checked) must still be
// renamable, paused and resumed: refusing every edit until the box is fixed
// would lock the operator out of the form that fixes it.
func TestRenamingAProviderIsNotRefusedForACertificateItAlreadyHolds(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("admin", store.RoleAdmin)
	cookie := h.session(admin)
	prov := h.provider("proxmox-lab")
	row, err := h.st.GetProvider(h.ctx, prov.ID)
	if err != nil {
		t.Fatalf("GetProvider: %v", err)
	}
	row.CAPEM, row.MachineCAPEM = pastedKey, "this is not a certificate"
	if err := h.st.UpdateProvider(h.ctx, row); err != nil {
		t.Fatalf("UpdateProvider: %v", err)
	}

	h.do(request{method: http.MethodPatch, path: "/api/v1/providers/" + prov.ID, cookie: cookie,
		body: map[string]any{"name": "proxmox-lab-2"}}).mustStatus(t, http.StatusOK, "rename a provider holding text that is no certificate")
}

// The audit trail is read by every signed-in viewer and redacts by field name,
// which says nothing about a box called machine_ca_pem. An upgrade copies
// whatever ca_pem held into it, so a key pasted there by mistake long ago is
// copied too, and clearing the new box (which the docs tell an operator with a
// public certificate to do) would write that key into the audit as the "before".
func TestClearingAMachineCertificateThatHoldsAKeyDoesNotAuditTheKey(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("admin", store.RoleAdmin)
	viewer, _ := h.user("viewer", store.RoleViewer)
	cookie := h.session(admin)
	prov := h.provider("proxmox-lab")
	row, err := h.st.GetProvider(h.ctx, prov.ID)
	if err != nil {
		t.Fatalf("GetProvider: %v", err)
	}
	row.CAPEM, row.MachineCAPEM = pastedKey, pastedKey // what the upgrade copy leaves behind
	if err := h.st.UpdateProvider(h.ctx, row); err != nil {
		t.Fatalf("UpdateProvider: %v", err)
	}

	h.do(request{method: http.MethodPatch, path: "/api/v1/providers/" + prov.ID, cookie: cookie,
		body: map[string]any{"machine_ca_pem": ""}}).mustStatus(t, http.StatusOK, "clear the machines' certificate")

	res := h.do(request{method: http.MethodGet, path: "/api/v1/audit?action=provider.update", cookie: h.session(viewer)})
	res.mustStatus(t, http.StatusOK, "read the audit as a viewer")
	var events page[store.AuditEvent]
	res.into(t, &events)
	recorded := false
	for _, e := range events.Items {
		for _, picture := range []string{e.Before, e.After} {
			if strings.Contains(picture, "PRIVATE KEY") || strings.Contains(picture, "bm90IGEgcmVhbCBrZXk") {
				t.Errorf("a viewer can read the pasted key in the audit: %s", picture)
			}
		}
		if strings.Contains(e.Before, "machine_ca_pem") {
			recorded = true
		}
	}
	if !recorded {
		t.Errorf("the change to machine_ca_pem is not in the audit at all: %s", truncate(res.body))
	}
}

package api

import (
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/pem"
	"math/big"
	"net/http"
	"net/http/httptest"
	"reflect"
	"regexp"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/provider"
	"github.com/eyupio/zoomies/internal/provider/proxmox"
	"github.com/eyupio/zoomies/internal/proxmoxsetup"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/tailscale/tailcat"
)

func setupCertificate(t *testing.T) string {
	t.Helper()
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	cert := &x509.Certificate{SerialNumber: big.NewInt(1), Subject: pkix.Name{CommonName: "pve"}, DNSNames: []string{"pve.example"}, NotBefore: time.Now().Add(-time.Hour), NotAfter: time.Now().Add(time.Hour)}
	der, err := x509.CreateCertificate(rand.Reader, cert, cert, key.Public(), key)
	if err != nil {
		t.Fatal(err)
	}
	return string(pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der}))
}

func TestProviderSetupSealsConnectionAndDoesNotReenrolRunner(t *testing.T) {
	h := newHarnessWithProviders(t, []provider.Factory{proxmox.NewFactory()})
	admin, _ := h.user("admin", store.RoleAdmin)
	viewer, _ := h.user("viewer", store.RoleViewer)
	cookie := h.session(admin)
	before := h.host("pve-1")
	before, _ = h.st.GetHost(h.ctx, before.ID)
	address := privateAddress(t)
	h.api.private.node = &tailcat.Server{}
	h.api.private.address = address
	defer func() { h.api.private.node = nil }()
	h.do(request{method: "POST", path: "/api/v1/provider-setups", cookie: h.session(viewer), body: map[string]any{}}).mustStatus(t, 403, "viewer")
	created := h.do(request{method: "POST", path: "/api/v1/provider-setups", cookie: cookie, body: map[string]any{}})
	created.mustStatus(t, 201, "create setup")
	var setup providerSetupView
	created.into(t, &setup)
	match := regexp.MustCompile(`--token '([0-9a-f]+)'`).FindStringSubmatch(setup.Command)
	if len(match) != 2 || !strings.Contains(setup.Command, "tailcat://"+address) {
		t.Fatal("missing private setup capability")
	}
	token := match[1]
	path := "/api/v1/provider-setups/" + setup.ID
	conn := proxmoxsetup.Connection{Name: "proxmox-pve-1", Endpoint: "https://pve.example:8006", Credential: "zoomies@pve!provider=secret", CAPEM: setupCertificate(t), TailcatAddress: address, Templates: []proxmoxsetup.Template{{VMID: 9000, Name: "runner", Node: "pve-1"}}}
	h.do(request{method: "POST", path: path + "/complete", cookie: cookie, body: conn}).mustStatus(t, 401, "session is not a setup token")
	h.do(request{method: "POST", path: path + "/complete", token: "wrong", body: conn}).mustStatus(t, 401, "wrong capability")
	h.do(request{method: "POST", path: path + "/complete", token: token, body: conn}).mustStatus(t, 204, "complete setup")
	h.do(request{method: "POST", path: path + "/complete", token: token, body: conn}).mustStatus(t, 204, "identical retry")
	altered := conn
	altered.Name = "another-host"
	h.do(request{method: "POST", path: path + "/complete", token: token, body: altered}).mustStatus(t, 401, "retry cannot replace connection")
	h.do(request{method: "GET", path: path, token: token}).mustStatus(t, 401, "capability cannot read user API")
	got := h.do(request{method: "GET", path: path, cookie: cookie})
	got.mustStatus(t, 200, "ready setup")
	var ready providerSetupView
	got.into(t, &ready)
	if !ready.Ready || ready.Name != conn.Name || ready.Endpoint != conn.Endpoint || ready.Command != "" || len(ready.Templates) != 1 || ready.Templates[0].VMID != 9000 {
		t.Fatalf("ready response: %+v", ready)
	}
	for _, secret := range []string{token, conn.Credential, address} {
		if strings.Contains(string(got.body), secret) {
			t.Fatal("setup response leaked a secret")
		}
	}
	stored, err := h.st.GetProviderSetup(h.ctx, setup.ID)
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(stored.PayloadEnc), conn.Credential) || strings.Contains(string(stored.TokenHash), token) {
		t.Fatal("setup persisted plaintext secrets")
	}
	req := httptest.NewRequest(http.MethodPost, "/api/v1/providers/validate", nil)
	w := httptest.NewRecorder()
	badEndpoint := "https://attacker.example:8006"
	in := providerInput{SetupID: &setup.ID, Endpoint: &badEndpoint}
	if !h.api.resolveProviderSetup(w, req, &in) || *in.Endpoint != conn.Endpoint || *in.Credential != conn.Credential || *in.CAPEM != conn.CAPEM || *in.InsecureSkipVerify {
		t.Fatal("staged credential was not bound to its verified endpoint")
	}
	saved := h.do(request{method: "POST", path: "/api/v1/providers", cookie: cookie, body: map[string]any{
		"setup_id": setup.ID, "endpoint": badEndpoint,
		"settings": map[string]string{"nodes": "pve-1", "template_id": "9000", "storage": "local-lvm", "bridge": "vmbr0", "vmid_min": "9100", "vmid_max": "9199"},
	}})
	saved.mustStatus(t, 201, "save staged provider")
	var made providerResponse
	saved.into(t, &made)
	if !made.CredentialsConfigured || made.Connection != "tailcat" || made.Endpoint != conn.Endpoint || made.MaxMachines != 0 {
		t.Fatalf("saved provider: %+v", made)
	}
	for _, secret := range []string{token, conn.Credential, address} {
		if strings.Contains(string(saved.body), secret) {
			t.Fatal("provider response leaked a setup secret")
		}
	}
	if _, err := h.st.GetProviderSetup(h.ctx, setup.ID); err == nil {
		t.Fatal("saved provider retained its staged credential")
	}
	after, err := h.st.GetHost(h.ctx, before.ID)
	if err != nil || !reflect.DeepEqual(before, after) {
		t.Fatal("existing runner host changed")
	}
	hosts, _ := h.st.ListHosts(h.ctx)
	if len(hosts) != 1 {
		t.Fatal("provider setup enrolled another runner host")
	}
}

