	"strings"
	"testing"
)

func TestProvisioningAPIControlsOnlyDemand(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux")
	job := h.job(pool, store.JobQueued)
	_, operator := h.user("operator", store.RoleOperator)
	_, viewer := h.user("viewer", store.RoleViewer)
	body := map[string]any{"ids": []string{job.ID}, "action": "pause"}
	h.do(request{method: "POST", path: "/api/v1/provisioning/bulk", body: body, cookie: viewer}).mustStatus(t, http.StatusForbidden, "viewer control")
	before := len(h.gh.Requests())
	for _, action := range []string{"pause", "run_now", "delete", "resume"} {
		body["action"] = action
		resp := h.do(request{method: "POST", path: "/api/v1/provisioning/bulk", body: body, cookie: operator})
		resp.mustStatus(t, http.StatusOK, action)
		var result struct {
			Results []store.ProvisioningResult `json:"results"`
		}
		if err := json.Unmarshal(resp.body, &result); err != nil {
			t.Fatal(err)
		}
		if len(result.Results) != 1 || !result.Results[0].OK {
			t.Fatalf("%s: %s", action, resp.body)
		}
		got, err := h.st.GetJob(h.ctx, job.ID)
		if err != nil || got.State != store.JobQueued {
			t.Fatalf("GitHub state changed: %+v %v", got, err)
		}
		view := h.do(request{method: "GET", path: "/api/v1/jobs/" + job.ID, cookie: viewer})
		var wire map[string]any
		if err := json.Unmarshal(view.body, &wire); err != nil {
			t.Fatal(err)
		}
		if wire["provisioning"] != got.Provisioning || wire["provision_now"] != got.ProvisionNow {
			t.Fatalf("operator state missing from API: %s", view.body)
		}
		if action == "pause" {
			explain := h.do(request{method: "GET", path: "/api/v1/jobs/" + job.ID + "/explanation", cookie: viewer})
			if !strings.Contains(string(explain.body), "Provisioning is paused") {
				t.Fatalf("explanation: %s", explain.body)
			}
		}
	}
	if len(h.gh.Requests()) != before {
		t.Fatal("provisioning controls called GitHub")
	}
	for _, query := range []string{"?state=completed&managed=false", "?provisioning=ready"} {
		resp := h.do(request{method: "GET", path: "/api/v1/provisioning" + query, cookie: viewer})
		resp.mustStatus(t, 200, "queue")
		var page struct {
			Items  []store.Job    `json:"items"`
			Counts map[string]int `json:"counts"`
		}
		if err := json.Unmarshal(resp.body, &page); err != nil {
			t.Fatal(err)
		}
		if len(page.Items) != 1 || page.Items[0].ID != job.ID || page.Counts["ready"] != 1 {
			t.Fatalf("queue scope: %s", resp.body)
		}
	}
	h.do(request{method: "GET", path: "/api/v1/provisioning?provisioning=bogus", cookie: viewer}).mustStatus(t, 400, "invalid provisioning state")
	h.do(request{method: "GET", path: "/api/v1/provisioning/selection?repo=other/repo", cookie: viewer}).mustStatus(t, 200, "empty selection")
}

// The Overview is where an operator looks after clearing the queue, and the
// queue depth it draws has to have moved. It used to count every row GitHub
// still called queued, so a fleet whose queue had just been emptied went on
// reporting the number it had before -- the removal looked like a button that
// did nothing. The pool's own count is the same claim in a second place.
func TestRemovingQueuedItemsEmptiesTheOverviewsQueueDepth(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux")
	first, second := h.job(pool, store.JobQueued), h.job(pool, store.JobQueued)
	_, operator := h.user("operator", store.RoleOperator)

	stats := func() (queued, fleetQueued, poolQueued int) {
		t.Helper()
		resp := h.do(request{method: "GET", path: "/api/v1/stats", cookie: operator})
		resp.mustStatus(t, http.StatusOK, "stats")
		var out struct {
			QueuedJobs int `json:"queued_jobs"`
			Fleet      struct {
				QueuedJobs int `json:"queued_jobs"`
			} `json:"fleet"`
			Pools []struct {
				PoolID string `json:"pool_id"`
				Queued int    `json:"queued"`
			} `json:"pools"`
		}
		if err := json.Unmarshal(resp.body, &out); err != nil {
			t.Fatal(err)
		}
		for _, p := range out.Pools {
			if p.PoolID == pool.ID {
				poolQueued = p.Queued
			}
		}
		return out.QueuedJobs, out.Fleet.QueuedJobs, poolQueued
	}

	if q, f, p := stats(); q != 2 || f != 2 || p != 2 {
		t.Fatalf("before removing anything: queued=%d fleet=%d pool=%d, want 2 each", q, f, p)
	}
	body := map[string]any{"ids": []string{first.ID, second.ID}, "action": "delete"}
	h.do(request{method: "POST", path: "/api/v1/provisioning/bulk", body: body, cookie: operator}).
		mustStatus(t, http.StatusOK, "delete")
	if q, f, p := stats(); q != 0 || f != 0 || p != 0 {
		t.Fatalf("after emptying the queue: queued=%d fleet=%d pool=%d, want 0 each", q, f, p)
	}

	// Restoring one brings it back, so the tile is reporting the queue rather
	// than remembering a decision.
	body["ids"], body["action"] = []string{first.ID}, "resume"
	h.do(request{method: "POST", path: "/api/v1/provisioning/bulk", body: body, cookie: operator}).
		mustStatus(t, http.StatusOK, "resume")
	if q, f, p := stats(); q != 1 || f != 1 || p != 1 {
		t.Fatalf("after restoring one: queued=%d fleet=%d pool=%d, want 1 each", q, f, p)
	}
}

package api

import (
	"context"
	"net/http"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/store"
)

// staffName is an account of the kind a public view promises to say nothing
// about. It is distinctive on purpose: the assertions below search whole bodies
// for it, and a common word would find itself in somebody's job name.
const staffName = "ada-lovelace"

// failedJobOnARunner is a failed job and the runner that was executing it,
// which the runner's page and frames still point at.
func (h *harness) failedJobOnARunner(t *testing.T) (*store.Job, *store.Runner) {
	t.Helper()
	inst := h.installation()
	pool := h.pool(inst, "linux")
	run := h.runner(pool, h.host("vm-1"), store.RunnerIdle)
	done := time.Now().UTC().Add(-time.Minute)
	started := done.Add(-2 * time.Minute)
	failed, err := h.st.UpsertJob(h.ctx, &store.Job{
		GitHubJobID: 7201, GitHubRunID: 56, Repo: "acme/widgets", Workflow: "CI", JobName: "build",
		Labels: store.StringSlice{"self-hosted", "linux", "x64"}, State: store.JobCompleted,
		Conclusion: "failure", InstallationID: inst.ID, PoolID: pool.ID, Matched: true,
		QueuedAt: started.Add(-time.Minute), StartedAt: &started, CompletedAt: &done, RunAttempt: 1,
	})
	if err != nil {
		t.Fatalf("UpsertJob failed: %v", err)
	}
	if run, _, err = h.st.StartRunnerJob(h.ctx, run.ID, failed.ID, ""); err != nil {
		t.Fatalf("StartRunnerJob failed: %v", err)
	}
	return failed, run
}

// markAsKnown has the operator named staffName press the button, through the
// route, so the timeline entry and the job.updated frame are the real ones.
func (h *harness) markAsKnown(t *testing.T, failed *store.Job) {
	t.Helper()
	_, operator := h.user(staffName, store.RoleOperator)
	h.do(request{method: "POST", path: "/api/v1/jobs/" + failed.ID + "/acknowledge", cookie: operator}).
		mustStatus(t, http.StatusOK, "marking the failure as known")
}

// publishRunner puts the runner's frame on the bus as the controller renders
// it, which is how a runner still pointed at a failed job reaches the stream
// and the recent-events route.
func (h *harness) publishRunner(t *testing.T, run *store.Runner) {
	t.Helper()
	view, err := h.ctrl.RunnerRenderer(h.ctx, []*store.Runner{run})
	if err != nil {
		t.Fatalf("RunnerRenderer failed: %v", err)
	}
	h.ctrl.Events().Publish(events.KindRunnerUpdated, "runner:"+run.ID, view.View(run))
}

// A public view promises that nothing about the people who run the fleet is
// shown, and the name of the operator who marked a failure as known is one of
// them. A visitor is told that a failure was marked and when, which is the
// fleet's state, and never by whom. Every place the API renders a job, a
// runner's current job or a job's timeline is a place the name can leave by, so
// this walks them all, and each is asked again as a signed-in viewer, who is
// owed the name: a test that only watched it disappear would pass for a route
// that had stopped carrying it for everybody.
func TestAVisitorIsToldAFailureWasMarkedAsKnownButNeverWhoMarkedIt(t *testing.T) {
	h := newHarness(t, publicView)
	failed, run := h.failedJobOnARunner(t)
	h.markAsKnown(t, failed)
	h.publishRunner(t, run)
	viewer, _ := h.user("viewer", store.RoleViewer)

	for _, tc := range []struct {
		name, path string
		// keeps is what a visitor is still owed: that it happened, and when.
		keeps string
		// named is whether a signed-in viewer reads the name here at all.
		named bool
	}{
		{"the job", "/api/v1/jobs/" + failed.ID, `"acknowledged_at"`, true},
		{"the failed list", "/api/v1/jobs?failed=true", `"acknowledged_at"`, true},
		{"the job's timeline", "/api/v1/jobs/" + failed.ID + "/events", "marked this failure as known", true},
		{"the runner that ran it", "/api/v1/runners/" + run.ID, `"acknowledged_at"`, true},
		{"the runners list", "/api/v1/runners", `"acknowledged_at"`, true},
		{"the recent events", "/api/v1/events/recent?kinds=job.updated,runner.updated", `"acknowledged_at"`, true},
		{"the workflow runs", "/api/v1/workflow-runs?failed=true", `"github_run_id"`, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			seen := h.do(request{method: http.MethodGet, path: tc.path})
			seen.mustStatus(t, http.StatusOK, "a visitor reading "+tc.name)
			if strings.Contains(string(seen.body), staffName) {
				t.Errorf("a visitor reading %s was told who marked the failure as known: %s", tc.name, truncate(seen.body))
			}
			if !strings.Contains(string(seen.body), tc.keeps) {
				t.Errorf("a visitor reading %s lost %s along with the name: %s", tc.name, tc.keeps, truncate(seen.body))
			}

			staff := h.do(request{method: http.MethodGet, path: tc.path, cookie: h.session(viewer)})
			staff.mustStatus(t, http.StatusOK, "a signed-in viewer reading "+tc.name)
			if got := strings.Contains(string(staff.body), staffName); got != tc.named {
				t.Errorf("a signed-in viewer reading %s was shown the name = %v, want %v: %s", tc.name, got, tc.named, truncate(staff.body))
			}
		})
	}
}

// The assistant's get_job reads the same routes as the page, as the caller, so
// a visitor's assistant is held to what the visitor is shown without a rule of
// its own, and a token's assistant still reads the name.
func TestAVisitorsAssistantIsNotToldWhoMarkedAFailureAsKnownEither(t *testing.T) {
	h := newHarness(t, publicView)
	failed, _ := h.failedJobOnARunner(t)
	h.markAsKnown(t, failed)

	visitor := h.mcpTool("", "get_job", map[string]any{"job_id": failed.ID})
	if visitor.IsError || !strings.Contains(resultText(visitor), "marked this failure as known") {
		t.Fatalf("a visitor's get_job did not answer with the timeline: %s", resultText(visitor))
	}
	if strings.Contains(resultText(visitor), staffName) {
		t.Errorf("a visitor's assistant was told who marked the failure as known: %s", resultText(visitor))
	}

	staff := h.mcpTool(h.token("agent", store.RoleViewer), "get_job", map[string]any{"job_id": failed.ID})
	if !strings.Contains(resultText(staff), staffName) {
		t.Errorf("a token's assistant lost the name: %s", resultText(staff))
	}
}

// A page that is open when a failure is marked as known learns of it from a
// frame, and a frame is the resource's GET in miniature, so it answers the
// GET's question about who is asking. The job's own frame and the frame of a
// runner still pointed at the job both carry the job.
func TestAVisitorsLiveStreamIsNotToldWhoMarkedAFailureAsKnownEither(t *testing.T) {
	h := newHarness(t, publicView)
	failed, run := h.failedJobOnARunner(t)
	viewer, _ := h.user("viewer", store.RoleViewer)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	open := func(cookie string) <-chan sseFrame {
		t.Helper()
		frames, resp := h.openStream(t, ctx, "/api/v1/events", cookie, nil)
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("opening the stream answered %d", resp.StatusCode)
		}
		await(t, frames, "the opening comment", func(f sseFrame) bool { return f.comment != "" })
		return frames
	}
	audiences := []struct {
		name   string
		frames <-chan sseFrame
		named  bool
	}{
		{"a visitor", open(""), false},
		{"a signed-in viewer", open(h.session(viewer)), true},
	}

	h.markAsKnown(t, failed)
	h.publishRunner(t, run)

	for _, a := range audiences {
		for _, kind := range []events.Kind{events.KindJobUpdated, events.KindRunnerUpdated} {
			frame := await(t, a.frames, "the "+string(kind)+" frame carrying the acknowledgement", func(f sseFrame) bool {
				return f.event == string(kind) && strings.Contains(f.data, `"acknowledged_at"`)
			})
			if got := strings.Contains(frame.data, staffName); got != a.named {
				t.Errorf("%s was shown a %s frame naming the acknowledger = %v, want %v: %s", a.name, kind, got, a.named, frame.data)
			}
		}
	}
}

// A frame that names somebody and cannot be looked through is dropped for a
// visitor rather than sent as it is: the whole document is exactly what the
// narrowing exists to withhold, and the page repairs itself from the GET on any
// reload. Whoever may read the name is sent it as ever.
func TestAJobFrameThatCannotBeNarrowedIsNotSentToAVisitor(t *testing.T) {
	h := newHarness(t, publicView)
	viewer, _ := h.user("viewer", store.RoleViewer)
	h.ctrl.Events().Publish(events.KindJobUpdated, "job:odd", []map[string]string{{"acknowledged_by": staffName}})

	visitor := h.recent(t, "", "?kinds=job.updated")
	if len(visitor.Items) != 0 {
		t.Errorf("a visitor was sent a frame that could not be narrowed: %v", visitor.Items)
	}
	staff := h.recent(t, h.session(viewer), "?kinds=job.updated")
	if len(staff.Items) != 1 || !strings.Contains(string(staff.Items[0].Data), staffName) {
		t.Errorf("a signed-in viewer was not sent the frame: %v", staff.Items)
	}
}

package api

import (
	"context"
	"go/ast"
	"go/parser"
	"go/token"
	"net/http"
	"slices"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/store"
)

func publicView(c *config.Config) { c.Security.PublicView = true }

// The visitor walk: every route in the table, asked by somebody with nothing
// to present, on a controller whose fleet is meant to be looked at.
//
// A route a visitor's scopes reach answers them; every other route refuses
// them with 403 and never 401, because a 401 would send the UI to a sign-in
// form the visitor did not ask for, and the 403 is where they are told why.
func TestAVisitorReadsTheFleetAndIsRefusedEverythingElse(t *testing.T) {
	h := newHarness(t, publicView)
	ids := h.fixtures()
	reach := auth.VisitorScopes()

	for _, rt := range routeTable(ids) {
		if rt.public {
			continue
		}
		t.Run(rt.method+" "+rt.path, func(t *testing.T) {
			resp := h.do(request{method: rt.method, path: rt.path, body: rt.body})
			allowed := rt.path == "/api/v1/auth/session" ||
				(rt.action != "" && !rt.accountOnly && !rt.visitorDenied && rt.role == store.RoleViewer && slices.Contains(reach, rt.action.Scope()))
			if allowed {
				if resp.status == http.StatusUnauthorized || resp.status == http.StatusForbidden {
					t.Fatalf("a visitor was refused %d: %s", resp.status, truncate(resp.body))
				}
				return
			}
			if resp.status != http.StatusForbidden {
				t.Fatalf("a visitor got %d, want 403: %s", resp.status, truncate(resp.body))
			}
			if msg := resp.errorMessage(t); !strings.Contains(msg, "public view") || !strings.Contains(msg, "sign in") {
				t.Errorf("the refusal does not tell a visitor to sign in: %q", msg)
			}
		})
	}
}

// Without the setting nothing changes: the same caller is told to sign in.
func TestWithoutAPublicViewNobodyIsAVisitor(t *testing.T) {
	h := newHarness(t)
	h.do(request{method: "GET", path: "/api/v1/pools"}).mustStatus(t, http.StatusUnauthorized, "an anonymous caller on a private controller")
	if got := h.do(request{method: "GET", path: "/api/v1/meta"}).json(t)["public_view"]; got != false {
		t.Errorf("meta public_view = %v on a private controller; want false", got)
	}
}

// The UI decides what to show from these two answers: the controller says it
// is public, and the session says who is looking.
func TestAPublicViewSaysSoAndNamesTheVisitor(t *testing.T) {
	h := newHarness(t, publicView)
	if got := h.do(request{method: "GET", path: "/api/v1/meta"}).json(t)["public_view"]; got != true {
		t.Errorf("meta public_view = %v; want true", got)
	}
	who := h.do(request{method: "GET", path: "/api/v1/auth/session"})
	who.mustStatus(t, http.StatusOK, "a visitor asking who they are")
	body := who.json(t)
	if body["kind"] != auth.KindPublic || body["role"] != string(store.RoleViewer) {
		t.Errorf("session = %v; want kind %q at the viewer role", body, auth.KindPublic)
	}
}

// Signing out writes an audit row. A visitor who could call it would let an
// anonymous loop fill the audit log with nothing.
func TestAVisitorCannotSignOutIntoTheAuditLog(t *testing.T) {
	h := newHarness(t, publicView)
	_, before, err := h.st.ListAudit(h.ctx, store.AuditFilter{}, store.Page{Limit: 1})
	if err != nil {
		t.Fatalf("reading the audit log: %v", err)
	}
	for range 3 {
		h.do(request{method: "POST", path: "/api/v1/auth/logout"}).mustStatus(t, http.StatusForbidden, "a visitor signing out")
	}
	_, after, err := h.st.ListAudit(h.ctx, store.AuditFilter{}, store.Page{Limit: 1})
	if err != nil {
		t.Fatalf("reading the audit log: %v", err)
	}
	if after != before {
		t.Errorf("the audit log grew from %d to %d rows while a visitor signed out", before, after)
	}
}

// A browser whose session lapsed keeps sending the cookie until it is told to
// forget it. On a public view the request is answered as a visitor and the
// cookie is cleared in the same response.
func TestALapsedSessionIsForgottenOnAPublicView(t *testing.T) {
	h := newHarness(t, publicView)
	resp := h.do(request{method: "GET", path: "/api/v1/auth/session", cookie: "a-session-that-ended-long-ago"})
	resp.mustStatus(t, http.StatusOK, "a lapsed session on a public view")
	if kind := resp.json(t)["kind"]; kind != auth.KindPublic {
		t.Errorf("a lapsed session resolved to %v; want the visitor", kind)
	}
	if resp.cookie == nil || resp.cookie.MaxAge >= 0 {
		t.Errorf("the dead cookie was not cleared: %+v", resp.cookie)
	}

	// A token is different: a broken automation must hear it was refused.
	h.do(request{method: "GET", path: "/api/v1/pools", token: auth.APITokenPrefix + "notarealtoken"}).
		mustStatus(t, http.StatusUnauthorized, "an unknown token on a public view")
}

// A frame is the resource's GET in miniature. Before, holding events.read was
// enough for every frame, so a token scoped to events:read alone received the
// audit log a row at a time, and a visitor would have too.
func TestAStreamSendsAFrameOnlyToSomebodyWhoCouldReadIt(t *testing.T) {
	h := newHarness(t, publicView)
	scoped := h.token("events only", store.RoleAdmin, "events:read", "pools:read")
	viewer, _ := h.user("viewer", store.RoleViewer)

	callers := []struct {
		name      string
		cookie    string
		headers   map[string]string
		wantAudit bool
	}{
		{name: "visitor"},
		{name: "token scoped to events and pools", headers: map[string]string{"Authorization": "Bearer " + scoped}},
		{name: "viewer", cookie: h.session(viewer), wantAudit: true},
	}
	for _, c := range callers {
		t.Run(c.name, func(t *testing.T) {
			ctx, cancel := context.WithCancel(context.Background())
			defer cancel()
			frames, resp := h.openStream(t, ctx, "/api/v1/events", c.cookie, c.headers)
			if resp.StatusCode != http.StatusOK {
				t.Fatalf("opening the stream answered %d", resp.StatusCode)
			}
			await(t, frames, "the opening comment", func(f sseFrame) bool { return f.comment != "" })

			h.ctrl.Events().Publish(events.KindAudit, "audit:1", store.AuditEvent{ID: "aud_1", Action: "auth.login", ActorName: "alice", IP: "198.51.100.4"})
			h.ctrl.Events().Publish(events.KindPoolCreated, "pool:p", map[string]any{"id": "p"})

			sawAudit := false
			await(t, frames, "the pool frame", func(f sseFrame) bool {
				if f.event == string(events.KindAudit) {
					sawAudit = true
				}
				return f.event == string(events.KindPoolCreated)
			})
			if sawAudit != c.wantAudit {
				t.Errorf("audit frame delivered = %v; want %v", sawAudit, c.wantAudit)
			}
		})
	}
}

// A new kind of frame reaches nobody until somebody decides who may read it.
// This walks every kind the bus declares, read from its source so a new one
// cannot be added without a row here.
func TestEveryKindOfFrameSaysWhoMayReadIt(t *testing.T) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "../events/bus.go", nil, 0)
	if err != nil {
		t.Fatalf("reading the bus's kinds: %v", err)
	}
	found := 0
	ast.Inspect(f, func(n ast.Node) bool {
		spec, ok := n.(*ast.ValueSpec)
		if !ok {
			return true
		}
		if id, ok := spec.Type.(*ast.Ident); !ok || id.Name != "Kind" {
			return true
		}
		for i, name := range spec.Names {
			lit, ok := spec.Values[i].(*ast.BasicLit)
			if !ok {
				continue
			}
			found++
			k := events.Kind(strings.Trim(lit.Value, `"`))
			if _, mapped := frameReads[k]; !mapped && !framesForEveryone[k] {
				t.Errorf("%s (%s) has no read action, so no stream will ever carry it", name.Name, k)
			}
		}
		return true
	})
	if found == 0 {
		t.Fatal("found no kinds in internal/events/bus.go, so this checked nothing")
	}
}

// Signing in from a browser still holding a dead cookie must answer with the
// new session alone. A clearing header beside the one that sets it would leave
// the browser to settle which wins.
func TestSigningInOverALapsedSessionSetsOneCookie(t *testing.T) {
	h := newHarness(t, publicView)
	h.user("alice", store.RoleAdmin)
	resp := h.do(request{method: "POST", path: "/api/v1/auth/login", cookie: "a-session-that-ended-long-ago",
		body: map[string]any{"username": "alice", "password": testPassword}})
	resp.mustStatus(t, http.StatusOK, "signing in over a lapsed session")
	set := 0
	for _, c := range resp.header.Values("Set-Cookie") {
		if strings.HasPrefix(c, SessionCookie+"=") {
			set++
		}
	}
	if set != 1 {
		t.Errorf("the sign-in set the session cookie %d times; want once", set)
	}
	if resp.cookie == nil || resp.cookie.Value == "" || resp.cookie.MaxAge < 0 {
		t.Errorf("the session cookie set was %+v; want the new session", resp.cookie)
	}
}

// A public demo invites people nobody can ask to close a tab. Their streams
// have a ceiling of their own, and however full it is, somebody who runs the
// fleet still gets the stream the ordinary ceiling keeps for them.
func TestVisitorsCannotTakeTheStreamsStaffNeed(t *testing.T) {
	h := newHarness(t, publicView, func(c *config.Config) {
		c.Limits.VisitorEventSubscribers = 1
		c.Limits.EventSubscribers = 1
	})
	admin, _ := h.user("admin", store.RoleAdmin)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	frames, first := h.openStream(t, ctx, "/api/v1/events", "", nil)
	if first.StatusCode != http.StatusOK {
		t.Fatalf("the first visitor's stream answered %d", first.StatusCode)
	}
	await(t, frames, "the first visitor's opening comment", func(f sseFrame) bool { return f.comment != "" })

	second := h.do(request{method: "GET", path: "/api/v1/events"})
	second.mustStatus(t, http.StatusConflict, "a second visitor past the visitors' ceiling")
	if msg := second.errorMessage(t); !strings.Contains(msg, "limits.visitor_event_subscribers") {
		t.Errorf("the refusal does not name the visitors' ceiling: %q", msg)
	}

	_, staff := h.openStream(t, ctx, "/api/v1/events", h.session(admin), nil)
	if staff.StatusCode != http.StatusOK {
		t.Fatalf("an administrator's stream answered %d while visitors were at their ceiling", staff.StatusCode)
	}
}

