	h.do(request{method: http.MethodDelete, path: "/api/v1/pools/" + pool.ID, cookie: cookie}).mustStatus(t, http.StatusOK, "deleting a pool while only watching")
	if err := h.ctrl.ReconcileAutoPools(h.ctx); err != nil {
