func TestASizeTagMustBeAClassWhileTheControllerWorksClassesOut(t *testing.T) {
	on := newHarness(t, sizeOn)
	host := on.host("build-1")
	operator, _ := on.user("operator", store.RoleOperator)
	cookie := on.session(operator)

	resp := on.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID, cookie: cookie,
		body: map[string]any{"labels": map[string]string{"size": "huge"}}})
	resp.mustStatus(t, http.StatusUnprocessableEntity, "a size tag that is not a class")
	if !strings.Contains(string(resp.body), "small, medium or large") {
		t.Fatalf("the refusal does not say what the tag may be: %s", resp.body)
	}
	if stored, _ := on.st.GetHost(on.ctx, host.ID); stored.Labels["size"] != "" {
		t.Fatalf("a refused tag was written: %v", stored.Labels)
	}
	on.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID, cookie: cookie,
		body: map[string]any{"labels": map[string]string{"size": "large", "rack": "b4"}}}).
		mustStatus(t, http.StatusOK, "a size tag that is a class")

	// The class has to be written as it is, because the pool's host selector
	// compares a label exactly: "Large" would be counted towards the large pool
	// and never matched by it.
	for _, loose := range []string{"Large", " large", "LARGE"} {
		on.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID, cookie: cookie,
			body: map[string]any{"labels": map[string]string{"size": loose}}}).
			mustStatus(t, http.StatusUnprocessableEntity, "a size tag written as "+loose)
	}

	// And the token that will put the label on a host is held to the same rule,
	// where the host would otherwise land in no pool and say nothing at the time.
	admin, _ := on.user("admin", store.RoleAdmin)
	adminCookie := on.session(admin)
	on.do(request{method: http.MethodPost, path: "/api/v1/join-tokens", cookie: adminCookie,
		body: map[string]any{"labels": map[string]string{"size": "huge"}}}).
		mustStatus(t, http.StatusUnprocessableEntity, "a join token carrying a size tag that is not a class")
	on.do(request{method: http.MethodPost, path: "/api/v1/join-tokens", cookie: adminCookie,
		body: map[string]any{"labels": map[string]string{"size": "small"}}}).
		mustStatus(t, http.StatusCreated, "a join token carrying a size tag that is a class")

	// With both switches off the key is an ordinary label.
	off := newHarness(t)
	host = off.host("build-1")
	operator, _ = off.user("operator", store.RoleOperator)
	cookie = off.session(operator)
	off.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID, cookie: cookie,
		body: map[string]any{"labels": map[string]string{"size": "huge"}}}).
		mustStatus(t, http.StatusOK, "a size label with the feature off")
	offAdmin, _ := off.user("admin", store.RoleAdmin)
	off.do(request{method: http.MethodPost, path: "/api/v1/join-tokens", cookie: off.session(offAdmin),
		body: map[string]any{"labels": map[string]string{"size": "huge"}}}).
		mustStatus(t, http.StatusCreated, "a join token with a size label and the feature off")
}

package api

import (
	"fmt"
	"slices"
	"strconv"
	"strings"
	"testing"

	"gopkg.in/yaml.v3"
)

// cutDescriptionBaseline is how many one-line descriptions in api/openapi.yaml
// are known to have been cut short, counted as the entries each one leaves
// behind (a description cut at two commas leaves two).
//
// YAML ends an unquoted scalar at its first comma when it stands inside a flow
// mapping, so
//
//	cpus: { type: integer, description: The processors a node has, when the provider said. }
//
// describes the property as "The processors a node has" and adds a second key,
// "when the provider said.", with no value. That is valid YAML, so nothing
// complains: the document parses, the generated client builds, and the rest of
// the sentence is missing from the API reference and from the client's comments
// without anybody having removed it. Quote the description to keep all of it, as
// the lines of api/openapi.yaml that already carry a comma do:
//
//	cpus: { type: integer, description: "The processors a node has, when the provider said." }
//
// The entries counted here were written before this test and are corrected as
// the lines around them are rewritten, not in one sweep that would bury their
// history. The number only ever goes down: lower it when you quote some, and
// never raise it to let a new one through.
const cutDescriptionBaseline = 246

// valuelessEntry is a key that a flow mapping holds with nothing after it.
type valuelessEntry struct {
	line int    // where the key is in the document
	path string // the mapping that holds it, written as a JSON pointer like a $ref
	key  string
}

// jsonPointerEscape is how RFC 6901 writes a "/" or a "~" inside one segment of
// a pointer, which is how this file's own $refs would spell a path such as
// /jobs/stats.
var jsonPointerEscape = strings.NewReplacer("~", "~0", "/", "~1")

// flowEntriesWithoutAValue finds every entry of a flow mapping in a YAML
// document that was written as a bare key, which YAML reads as a key whose
// value is null.
//
// The rule is "written with nothing after it" and not "is null" so that an
// explicit null (`default: null`), which somebody chose, is left alone. It does
// not ask for a space in the key either: the tail of a cut description is
// usually a phrase, but "resolved." and "rounded." are tails too, and the
// document has some. Block mappings are skipped, because a comma does not end a
// scalar there and so cannot have cut anything.
func flowEntriesWithoutAValue(doc []byte) ([]valuelessEntry, error) {
	var root yaml.Node
	if err := yaml.Unmarshal(doc, &root); err != nil {
		return nil, err
	}
	var found []valuelessEntry
	var walk func(n *yaml.Node, path string)
	walk = func(n *yaml.Node, path string) {
		switch n.Kind {
		case yaml.DocumentNode:
			for _, child := range n.Content {
				walk(child, path)
			}
		case yaml.SequenceNode:
			for i, child := range n.Content {
				walk(child, path+"/"+strconv.Itoa(i))
			}
		case yaml.MappingNode:
			flow := n.Style&yaml.FlowStyle != 0
			for i := 0; i+1 < len(n.Content); i += 2 {
				key, value := n.Content[i], n.Content[i+1]
				if flow && value.Kind == yaml.ScalarNode && value.Tag == "!!null" && value.Value == "" {
					found = append(found, valuelessEntry{line: key.Line, path: path, key: key.Value})
				}
				walk(value, path+"/"+jsonPointerEscape.Replace(key.Value))
			}
		}
	}
	walk(&root, "#")
	return found, nil
}

// TestNoNewDescriptionInTheSpecIsCutAtItsFirstComma stops the pattern described
// at cutDescriptionBaseline from growing. It counts and does not list the old
// ones, so the failure can show only the first few, in file order: they say what
// to look for, and the one that tipped the count is the description you wrote
// with a comma in it and no quotes.
func TestNoNewDescriptionInTheSpecIsCutAtItsFirstComma(t *testing.T) {
	spec, err := openapiSpec()
	if err != nil {
		t.Fatalf("openapiSpec: %v", err)
	}
	cut, err := flowEntriesWithoutAValue(spec)
	if err != nil {
		t.Fatalf("parsing the OpenAPI document: %v", err)
	}
	if len(cut) <= cutDescriptionBaseline {
		return
	}

	var examples []string
	for _, e := range cut[:min(len(cut), 5)] {
		examples = append(examples, fmt.Sprintf("api/openapi.yaml:%d, %s, has the key %q and nothing after it", e.line, e.path, e.key))
	}
	t.Errorf("api/openapi.yaml has %d flow-mapping entries with no value, up from %d. "+
		"That is what a one-line description leaves behind when it has a comma in it and no quotes: "+
		"YAML ends the text at the comma and reads the rest as a key with nothing after it, "+
		"so the sentence is cut short in the API reference and in the generated client. "+
		"Put the description in double quotes, as its neighbours do. "+
		"The first %d, to show what to look for:\n  %s",
		len(cut), cutDescriptionBaseline, len(examples), strings.Join(examples, "\n  "))
}

// The count is only as good as the rule under it, so the rule is held to the
// cases that decided it: a description cut in each of the shapes the document
// has them in, and the YAML beside it that is fine.
func TestACutDescriptionIsToldApartFromYamlThatMerelyLooksLikeOne(t *testing.T) {
	for _, tc := range []struct {
		name string
		doc  string
		want []string // each as "path: key"
	}{
		{"a comma ends the text and the rest is a key with no value",
			`a: { type: string, description: Where approving sends you, and why }`,
			[]string{"#/a: and why"}},
		{"a tail of one word has no space and is still a tail",
			`a: { type: integer, description: The count, rounded. }`,
			[]string{"#/a: rounded."}},
		{"every further comma leaves one more entry",
			`a: { description: One, two, three }`,
			[]string{"#/a: two", "#/a: three"}},
		{"a quoted description is whole",
			`a: { type: string, description: "Where approving sends you, and why" }`,
			nil},
		{"an explicit null is a value somebody wrote",
			`a: { type: [string, "null"], default: null, example: ~ }`,
			nil},
		{"a flow sequence is not a mapping",
			`a: { type: string, enum: [one, two], required: [x, y] }`,
			nil},
		{"an empty value in a block mapping cannot have been cut by a comma",
			"a:\n  b:\n  c: d\n",
			nil},
		{"a slash in a key is escaped the way a $ref spells it",
			"paths:\n  /jobs/stats:\n    get: { description: Foo, bar }\n",
			[]string{"#/paths/~1jobs~1stats/get: bar"}},
		{"a list entry is named by its position",
			"parameters:\n  - { name: a, description: Foo }\n  - { name: b, description: Foo, bar }\n",
			[]string{"#/parameters/1: bar"}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			found, err := flowEntriesWithoutAValue([]byte(tc.doc))
			if err != nil {
				t.Fatalf("parsing %q: %v", tc.doc, err)
			}
			var got []string
			for _, e := range found {
				got = append(got, e.path+": "+e.key)
			}
			if !slices.Equal(got, tc.want) {
				t.Errorf("%q: found %q, want %q", tc.doc, got, tc.want)
			}
		})
	}
}

package api

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"
	"unicode/utf8"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/store"
)

// heartbeatInterval is how often a live stream sends something.
//
// Twenty seconds is comfortably inside the idle timeout of every proxy and load
// balancer anyone puts in front of this, which is what keeps a quiet fleet's
// event stream from being closed under the operator every minute. The UI's
// watchdog is set from the same number.
const heartbeatInterval = 20 * time.Second

// sseWriter is one Server-Sent Events response.
//
// It exists so that the two streams -- fleet events and a runner's log tail --
// cannot disagree about framing, flushing or heartbeats, which is the usual way
// one of two SSE endpoints ends up subtly buffered.
type sseWriter struct {
	w  http.ResponseWriter
	rc *http.ResponseController
}

// startSSE writes the headers and returns the stream, or nil when the client
// cannot be streamed to.
func startSSE(w http.ResponseWriter, r *http.Request) *sseWriter {
	h := w.Header()
	h.Set("Content-Type", "text/event-stream; charset=utf-8")
	h.Set("Cache-Control", "no-cache, no-transform")
	h.Set("Connection", "keep-alive")
	// nginx buffers proxied responses by default, which turns a live stream
	// into one that arrives in lumps minutes late. This is the header that
	// turns that off, and it costs nothing when there is no nginx.
	h.Set("X-Accel-Buffering", "no")

	s := &sseWriter{w: w, rc: http.NewResponseController(w)}
	// A stream has no length and no deadline. The server's WriteTimeout is
	// already 0 for exactly this reason; clearing it here as well means a
	// caller that serves this handler from a listener of their own cannot cut
	// the stream off by setting one.
	_ = s.rc.SetWriteDeadline(time.Time{})

	w.WriteHeader(http.StatusOK)
	// The first flush is what makes the browser's EventSource fire onopen,
	// which the UI's connection indicator is driven by.
	s.flush()
	return s
}

// event writes one named event with its id and JSON payload. An empty id
// leaves the client's last id where it was, which is what a heartbeat or a
// log chunk wants.
func (s *sseWriter) event(kind string, id string, data []byte) error {
	var b strings.Builder
	if id != "" {
		b.WriteString("id: ")
		b.WriteString(id)
		b.WriteByte('\n')
	}
	if kind != "" {
		b.WriteString("event: ")
		b.WriteString(kind)
		b.WriteByte('\n')
	}
	if len(data) == 0 {
		data = []byte("{}")
	}
	// A payload containing a newline has to be split across data: lines or the
	// frame ends early and the client sees truncated JSON.
	for line := range strings.SplitSeq(string(data), "\n") {
		b.WriteString("data: ")
		b.WriteString(strings.TrimSuffix(line, "\r"))
		b.WriteByte('\n')
	}
	b.WriteByte('\n')
	if _, err := io.WriteString(s.w, b.String()); err != nil {
		return err
	}
	s.flush()
	return nil
}

// comment writes a heartbeat. A comment frame keeps the connection alive
// without the client having to know about a keep-alive event kind.
func (s *sseWriter) comment(text string) error {
	if _, err := fmt.Fprintf(s.w, ": %s\n\n", text); err != nil {
		return err
	}
	s.flush()
	return nil
}

// retry tells the browser how long to wait before reconnecting on its own.
func (s *sseWriter) retry(d time.Duration) error {
	if _, err := fmt.Fprintf(s.w, "retry: %d\n\n", d.Milliseconds()); err != nil {
		return err
	}
	s.flush()
	return nil
}

func (s *sseWriter) flush() { _ = s.rc.Flush() }

// ---------------------------------------------------------------------------
// GET /api/v1/events
// ---------------------------------------------------------------------------

// endIfRevoked re-resolves the credential this stream was opened with and, when
// it no longer stands, ends the stream with a frame saying so.
//
// A live stream is authorised once, at the moment it is opened, and then held
// for as long as the tab is. Without this, signing out, revoking the token,
// disabling the account or letting the session expire leaves the stream running
// -- the fleet's every movement still arriving at a browser whose credential
// the operator has just taken away, until something else happens to break the
// connection. Every other route re-checks on every request; a stream's
// heartbeat is the closest thing it has to one, so it re-checks there.
//
// The reason is deliberately the same whichever way the credential failed: an
// ended stream tells a client to stop and sign in again, and which of the four
// happened is not something the far end can do anything different about.
func (s *Server) endIfRevoked(stream *sseWriter, r *http.Request, action auth.Action) bool {
	id, err := s.resolveIdentity(r)
	if err == nil && auth.Allowed(id, action) {
		return false
	}
	// A failed read is not a revoked credential. Ending here would tell every
	// open tab to sign in again because the database blinked once; the stream
	// stays up and the next heartbeat asks again. A revocation is noticed a
	// beat late rather than missed, and the frames that carry anything
	// sensitive are still filtered per subscriber, failing closed, as they go
	// out.
	if errors.Is(err, auth.ErrAuthBackend) {
		s.logger(r).Warn("could not re-check a live stream's credential; keeping the stream open", "error", err)
		return false
	}
	_ = stream.event("end", "", []byte(`{"reason":"this stream's credential is no longer valid; sign in again"}`))
	return true
}

// subscribeStream takes one of the live-update slots the caller is held to,
// for the stream and for a wait on GET /events/recent alike, or says why there
// is none. A crowd of a public view's visitors is held to a ceiling of its own
// and never counted against the one the people who run the fleet need.
func (s *Server) subscribeStream(ctx context.Context, id *auth.Identity, opts events.SubscribeOptions) (*events.Subscription, *controller.LimitError) {
	limit := s.cfg().Limits.EventSubscribers
	visitor := auth.IsVisitor(id)
	if visitor {
		opts.Class = visitorStreams
		opts.ClassLimit = s.cfg().Limits.VisitorEventSubscribers
	}
	if sub, ok := s.ctrl.Events().SubscribeWithin(ctx, opts, limit); ok {
		return sub, nil
	}
	if visitor {
		return nil, &controller.LimitError{
			Setting: "limits.visitor_event_subscribers", Limit: opts.ClassLimit,
			What: "live-update streams for visitors",
			Free: "reload in a minute, since every page still works without live updates",
		}
	}
	return nil, &controller.LimitError{
		Setting: "limits.event_subscribers", Limit: limit, What: "live-update streams",
		Free: "close a browser tab that is no longer needed",
	}
}

// handleEvents streams every change the operator would want to see.
//
// There is no polling anywhere in the UI, so this endpoint is the whole of the
// dashboard's liveness. It replays from Last-Event-ID on reconnect, which is
// what makes a dropped connection invisible rather than a hole in the history.
func (s *Server) handleEvents(w http.ResponseWriter, r *http.Request) {
	bus := s.ctrl.Events()
	replay, sameEpoch := lastEventID(r, bus)
	opts := events.SubscribeOptions{
		Kinds:       parseKinds(r.URL.Query().Get("kinds")),
		TopicPrefix: strings.TrimSpace(r.URL.Query().Get("topic")),
		Replay:      replay,
		Incomplete:  replay > 0 && !sameEpoch,
	}

	ctx := r.Context()
	// The subscription is unsubscribed by cancelling the context it was made
	// with, which the bus watches and acts on. That is one owner of the
	// teardown rather than two: closing it here as well would mean this
	// handler and the bus's own watcher racing to do the same thing, and the
	// point of the cancel is that it happens on every exit from this function,
	// including a write failure to a browser that has already gone.
	subCtx, unsubscribe := context.WithCancel(ctx)
	defer unsubscribe()
	// Refused before the stream starts, while a status code can still be
	// sent. The browser's EventSource gives up on a non-200 rather than
	// retrying, which is what an instance with no room wants from it.
	sub, refused := s.subscribeStream(subCtx, Identity(ctx), opts)
	if refused != nil {
		limitReached(w, refused)
		return
	}

	stream := startSSE(w, r)
	_ = stream.retry(2 * time.Second)
	// An immediate heartbeat lets the client start its stall watchdog without
	// waiting twenty seconds to learn the stream works.
	if err := stream.comment("connected"); err != nil {
		return
	}
	if !sub.Complete {
		// The client asked to resume from an id the ring no longer reaches
		// back to, or from another run of this process. Saying so is what
		// lets it fetch afresh instead of quietly showing a fleet that has
		// moved on; the frame carries no id, so the client's own stays put.
		if err := stream.event(string(events.KindResync), "", []byte(`{"reason":"the events since your last id could not all be replayed; fetch the resources again"}`)); err != nil {
			return
		}
	}

	ticker := time.NewTicker(s.streamHeartbeat)
	defer ticker.Stop()

	// Who the frames are chosen for. Resolved when the stream opens and again
	// on every heartbeat, which is when the stream re-checks its credential
	// anyway, rather than once per frame: a busy fleet sends many frames a
	// second, and each resolution of a session is a database read.
	//
	// This is who the narrowed frames are chosen for as well as which kinds
	// they may be sent, so a demotion reaches both on the tick the revocation
	// check already runs on, rather than one frame at a time.
	reader := Identity(ctx)

	for {
		select {
		case <-ctx.Done():
			// The browser navigated away, or the process is shutting down.
			return
		case ev, ok := <-sub.C:
			if !ok {
				// The bus dropped this subscriber for falling behind. Ending
				// the response makes the client reconnect with its last event
				// ID and catch up, which is better than silently going stale.
				return
			}
			if !frameReadable(reader, ev.Kind) {
				continue
			}
			data, ok := s.frameFor(r, ev, reader)
			if !ok {
				continue
			}
			if err := stream.event(string(ev.Kind), bus.WireID(ev.ID), data); err != nil {
				return
			}
		case <-ticker.C:
			if s.endIfRevoked(stream, r, auth.ActionEventsRead) {
				return
			}
			if fresh, err := s.resolveIdentity(r); err == nil {
				reader = fresh
			}
			if err := stream.comment("heartbeat"); err != nil {
				return
			}
			// The UI's watchdog is driven by heartbeat *events*, not comment
			// frames, so one is sent as well; it carries the server's clock,
			// which is what the top bar's "live" indicator shows.
			if err := stream.event(string(events.KindHeartbeat), "", heartbeatPayload(s)); err != nil {
				return
			}
		}
	}
}

// frameFor is one event as this caller may be shown it: the payload narrowed to
// their audience, or false when the frame is not theirs to see at all.
//
// It is shared by the live stream and GET /events/recent, so the two cannot
// disagree about who is entitled to what. A second route that read the same ring
// without these checks would be the way round every one of them.
//
// id is who the frames are narrowed for. The caller resolves it: once per
// heartbeat on the live stream, once per request on the replay. A nil id is
// nobody, and nobody fails closed exactly as a failed resolution did when this
// resolved per frame. The pool frames are the exception: they carry
// credentials, so their block resolves for the frame itself.
func (s *Server) frameFor(r *http.Request, ev events.Event, id *auth.Identity) ([]byte, bool) {
	data := []byte(ev.Data)
	if ev.Kind == events.KindProblems {
		// The same two lists the REST route serves, chosen per
		// subscriber. Narrowed for the identity the caller resolved, for
		// the reason the pool frames are: a viewer may keep the stream
		// open across a demotion. The demotion reaches these fields on
		// the same tick the reader and the revocation check already
		// accept, and an identity that could not be resolved is nobody.
		platform := id != nil && id.Role.AtLeast(store.RolePlatform)
		filtered, ok := problemsFor(data, platform)
		if !ok && !platform {
			// Unfilterable, and this subscriber is not entitled to
			// the unfiltered list. Unlike the pool frames below,
			// passing it through would hand the fleet the whole of
			// the platform's list rather than leak one field, so the
			// frame is dropped instead. The drawer keeps what it had
			// until the next change, and GET /problems -- which
			// filters the same way -- repairs it on any reload.
			return nil, false
		}
		data = filtered
	}
	if ev.Kind == events.KindTransfer {
		// A transfer's preparation names runners, hosts and jobs
		// the route itself only shows the process operator, so the
		// frame goes to that audience and nobody below it. Narrowed
		// for the identity the caller resolved, as the others are.
		if id == nil || !id.Role.AtLeast(store.RolePlatform) {
			return nil, false
		}
	}
	if ev.Kind == events.KindUpdates {
		// The same status GET /updates serves this caller, chosen per
		// subscriber. Narrowed for the identity the caller resolved, like
		// the problems list, for the reason it is: a platform account may
		// keep the stream open across a demotion.
		platform := id != nil && id.Role.AtLeast(store.RolePlatform)
		filtered, ok := updatesFor(data, platform)
		if !ok && !platform {
			// Unfilterable, and the unfiltered frame is exactly what this
			// subscriber is not entitled to, so it is dropped. The page
			// keeps what it had until the next change, and GET /updates
			// repairs it on any reload.
			return nil, false
		}
		data = filtered
	}
	if ev.Kind == events.KindHostUpdated {
		// The same host GET /hosts serves this caller: the bus carries the
		// platform's form, and the reason an ended update recorded, which
		// can name a path on the host, is withheld from everybody else.
		// Narrowed for the identity the caller resolved, replay included,
		// like the update status.
		platform := id != nil && id.Role.AtLeast(store.RolePlatform)
		filtered, ok := hostsFor(data, platform)
		if !ok && !platform {
			// Unfilterable, so possibly carrying exactly what is withheld.
			// The card keeps what it had until the next change, and
			// GET /hosts repairs it on any reload.
			return nil, false
		}
		data = filtered
	}
	if ev.Kind == events.KindJobUpdated || ev.Kind == events.KindRunnerCreated || ev.Kind == events.KindRunnerUpdated {
		// The same job GET /jobs/{id} serves this caller, or the one a runner
		// frame carries as its current job: the bus holds the form that names
		// who marked a failure as known, and a visitor is not told. Only a
		// frame that names somebody is looked at, because job frames are the
		// busiest on the stream and almost none of them name anyone. The
		// identity is the one the caller resolved, on the same tick for
		// every frame of the page; a caller who cannot be resolved is
		// answered as a visitor, because the name is what is withheld.
		if bytes.Contains(data, []byte(`"acknowledged_by"`)) {
			if id == nil || auth.IsVisitor(id) {
				filtered, ok := withoutAcknowledger(data)
				if !ok {
					// Unfilterable, so possibly carrying exactly what is
					// withheld. The page keeps what it had until the next
					// change, and GET /jobs/{id} repairs it on any reload.
					return nil, false
				}
				data = filtered
			}
		}
	}
	if ev.Kind == events.KindAudit {
		// The same row GET /audit serves this caller, narrowed for the
		// identity the caller resolved, for the reason the others are. A
		// frame that will not decode is dropped rather than passed
		// through: the whole document is exactly what the filter exists
		// to withhold.
		var row store.AuditEvent
		if err := json.Unmarshal(data, &row); err != nil {
			return nil, false
		}
		filtered, err := json.Marshal(auditRowFor(row, id))
		if err != nil {
			return nil, false
		}
		data = filtered
	}
	if ev.Kind == events.KindPoolCreated || ev.Kind == events.KindPoolUpdated {
		// A viewer may keep watching after a demotion, but must not
		// keep the environment access they opened this stream with.
		//
		// The pool frame is the one narrowed frame that carries
		// credentials, so it is resolved for the frame rather than
		// taken from the identity the caller passes in: a demoted
		// watcher must not be handed a registry password in the frame
		// that follows the demotion, and the heartbeat is too late for
		// that. TestPoolEventsFollowTheWatchersCurrentRole holds this
		// to. Every other kind withholds a list, a path, an address or
		// a name, and reaching those a heartbeat late is the staleness
		// the stream already accepts for the reader and for the
		// revocation check.
		caller, err := s.resolveIdentity(r)
		if err != nil || caller == nil || !auth.Allowed(caller, auth.ActionPoolsWrite) {
			data = withoutEnvValues(data)
		}
	}
	return data, true
}

func heartbeatPayload(s *Server) []byte {
	return []byte(`{"at":"` + s.ctrl.Now().Format(time.RFC3339) + `"}`)
}

// lastEventID reads where a reconnecting client left off, and whether that
// place is in this process's sequence at all.
//
// The header is what the browser's own EventSource retry sends. The query
// parameter is what the UI sends when it has given up and opened a fresh
// EventSource, which cannot carry the header; honouring both is what makes a
// reconnect seamless either way. A malformed id means "start from now" rather
// than an error: the alternative is a client that can never reconnect until it
// is reloaded by hand.
func lastEventID(r *http.Request, bus *events.Bus) (id uint64, sameEpoch bool) {
	raw := strings.TrimSpace(r.Header.Get("Last-Event-ID"))
	if raw == "" {
		raw = strings.TrimSpace(r.URL.Query().Get("last_event_id"))
	}
	if raw == "" {
		return 0, true
	}
	id, sameEpoch = bus.ParseWireID(raw)
	if id == 0 && !sameEpoch {
		return 0, true
	}
	return id, sameEpoch
}

func parseKinds(raw string) []events.Kind {
	var out []events.Kind
	for _, k := range strings.Split(raw, ",") {
		if k = strings.TrimSpace(k); k != "" {
			out = append(out, events.Kind(k))
		}
	}
	return out
}

// ---------------------------------------------------------------------------
// GET /api/v1/runners/{id}/logs
// ---------------------------------------------------------------------------

// logChunkKind is the event name a log frame carries. It is not one of the
// fleet event kinds: this is a different stream with a payload of its own.
const logChunkKind = "log"

// handleRunnerLogs tails a runner's output.
//
// The controller never dials an agent, so this asks the controller to have the
// runner's agent open an outbound relay and then fans that out here. The two
// things this handler must get right are ending the stream when the runner's
// output ends, and unsubscribing on every exit -- a leaked subscription keeps a
// relay open on a host for a browser tab that closed hours ago.
func (s *Server) handleRunnerLogs(w http.ResponseWriter, r *http.Request) {
	id := chiURLParam(r, "id")
	opts := backend.LogOptions{
		Follow: queryBool(r, "follow", true),
		Tail:   queryInt(r, "tail", 1000),
	}
	if opts.Tail < 0 {
		opts.Tail = 0
	}

	ctx := r.Context()
	ch, cancel, err := s.ctrl.OpenLogStream(ctx, id, opts)
	if err != nil {
		s.logStreamFailed(w, r, err)
		return
	}
	// Always, on every path out: this is what tells the agent to stop reading
	// the container's output once the last viewer has gone.
	defer cancel()

	stream := startSSE(w, r)
	_ = stream.retry(2 * time.Second)
	if err := stream.comment("attached to " + id); err != nil {
		return
	}

	ticker := time.NewTicker(s.streamHeartbeat)
	defer ticker.Stop()

	// carry is the incomplete tail of the last chunk: the first bytes of a
	// character whose rest is in the next one. The relay forwards whatever a
	// read returned, so a boundary can fall inside a character, and rendering
	// each half as its own JSON string would turn it into two U+FFFD.
	var carry []byte
	for {
		select {
		case <-ctx.Done():
			return
		case chunk, ok := <-ch:
			if !ok {
				// The runner's output finished -- for an ephemeral runner that
				// means the job is over. Say so and end the response, rather
				// than leaving the browser holding a connection that will never
				// carry another byte.
				if len(carry) > 0 {
					// Nothing more is coming to complete it, so it is what it
					// is: a truncated character, shown as one replacement.
					_ = stream.event(logChunkKind, "", jsonString(string(carry)))
				}
				_ = stream.event("end", "", []byte(`{"reason":"the runner's output ended"}`))
				return
			}
			data := chunk
			if len(carry) > 0 {
				data = append(append(make([]byte, 0, len(carry)+len(chunk)), carry...), chunk...)
			}
			whole, rest := splitIncompleteRune(data)
			carry = append(carry[:0], rest...)
			if len(whole) == 0 {
				continue
			}
			if err := stream.event(logChunkKind, "", jsonString(string(whole))); err != nil {
				return
			}
		case <-ticker.C:
			if s.endIfRevoked(stream, r, auth.ActionLogsRead) {
				return
			}
			if err := stream.comment("heartbeat"); err != nil {
				return
			}
		}
	}
}

// handleDownloadRunnerLogs returns a snapshot of a runner's output as a file.
//
// It is the same relay as the live tail, read until it goes quiet rather than
// followed: "download" has to terminate, and a runner that is still producing
// output would otherwise stream forever into a file the browser never finishes.
func (s *Server) handleDownloadRunnerLogs(w http.ResponseWriter, r *http.Request) {
	id := chiURLParam(r, "id")
	run, err := s.ctrl.Store().GetRunner(r.Context(), id)
	if err != nil {
		s.fail(w, r, "reading the runner", err)
		return
	}

	// tail is what lets a caller who wants the end of a long build ask for
	// just that: without it the only way to the last lines was to read the
	// whole log and keep whatever fitted. Absent, or not a positive number, it
	// is the whole log, as a download always was.
	tail := max(queryInt(r, "tail", 0), 0)
	ch, cancel, err := s.ctrl.OpenLogStream(r.Context(), id, backend.LogOptions{Follow: false, Tail: tail})
	if err != nil {
		s.logStreamFailed(w, r, err)
		return
	}
	defer cancel()

	// The headers are held back until the first chunk arrives. A relay that
	// never starts used to answer 200 with a file-shaped empty attachment,
	// which looks like a build that printed nothing; a 503 below says the
	// host did not answer, which is something an operator can act on.
	const firstChunkWait = 10 * time.Second
	const quietFor = 2 * time.Second

	rc := http.NewResponseController(w)
	// The write deadline is cleared before the wait, not after the first
	// chunk: the refusal below is a write too, and it must not fall foul of a
	// server timeout that is shorter than the wait it answers.
	_ = rc.SetWriteDeadline(time.Time{})
	timer := time.NewTimer(firstChunkWait)
	defer timer.Stop()
	started := false
	for {
		select {
		case <-r.Context().Done():
			return
		case chunk, ok := <-ch:
			if !ok {
				return
			}
			if !started {
				w.Header().Set("Content-Type", "text/plain; charset=utf-8")
				w.Header().Set("Content-Disposition", `attachment; filename="`+logFilename(run.Name)+`"`)
				w.WriteHeader(http.StatusOK)
				started = true
			}
			if _, err := w.Write(chunk); err != nil {
				return
			}
			_ = rc.Flush()
			if !timer.Stop() {
				select {
				case <-timer.C:
				default:
				}
			}
			timer.Reset(quietFor)
		case <-timer.C:
			if !started {
				// Nothing arrived in the whole first-chunk window: the agent
				// may be in poll backoff (up to 30 seconds) or the host may be
				// restarting. That is a try-again, not an empty log.
				writeError(w, http.StatusServiceUnavailable, errorEnvelope{Error: errorBody{
					Code: codeInternal,
					Message: fmt.Sprintf("the runner's host did not begin sending its log within %d seconds; it may be busy or restarting, so try the download again, or read the log live",
						int(firstChunkWait.Seconds())),
				}})
			}
			return
		}
	}
}

// logStreamFailed answers a stream that could not be opened.
//
// A runner that has been removed, or that never reached a host, cannot produce
// output; that is a 409 with the controller's own sentence rather than a 500,
// because it is a fact about the runner and not a fault in the server.
func (s *Server) logStreamFailed(w http.ResponseWriter, r *http.Request, err error) {
	if errors.Is(err, store.ErrNotFound) || errors.Is(err, controller.ErrStreamUnknown) {
		s.fail(w, r, "opening the log stream", err)
		return
	}
	conflict(w, err.Error())
}

// logFilename renders the Content-Disposition name, keeping it to characters
// that survive every filesystem and every quoting rule on the way.
func logFilename(runnerName string) string {
	safe := strings.Map(func(r rune) rune {
		switch {
		case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9', r == '-', r == '_', r == '.':
			return r
		default:
			return '-'
		}
	}, runnerName)
	if safe == "" {
		safe = "runner"
	}
	return safe + ".log"
}

// splitIncompleteRune cuts off a trailing sequence that is the start of a
// multi-byte character and cannot be finished yet, so a caller can hold it
// until the next read. At most three bytes are ever held back, and bytes that
// are simply invalid are not: they pass through, so a stream of garbage is
// never delayed waiting for a character that will not come.
func splitIncompleteRune(b []byte) (whole, rest []byte) {
	for i := len(b) - 1; i >= 0 && i >= len(b)-(utf8.UTFMax-1); i-- {
		if !utf8.RuneStart(b[i]) {
			continue
		}
		if !utf8.FullRune(b[i:]) {
			return b[:i], b[i:]
		}
		break
	}
	return b, nil
}

// jsonString renders a log chunk as a JSON string, which is what keeps a line
// containing a newline or a quote from breaking the frame.
func jsonString(s string) []byte {
	b, err := marshalJSON(s)
	if err != nil {
		return []byte(`""`)
	}
	return b
}

// problemsFor narrows an already-rendered problems frame to one audience,
// and reports whether it could. It works on the encoded bytes for the reason
// withoutEnvValues does: the frame is rendered once and fanned out, so
// filtering per connection is what one subscriber's presence costs rather
// than what every subscriber pays.
//
// ok is false when the payload is not a problems frame this version
// understands. The caller decides what that means, and the two audiences
// decide differently.
func problemsFor(data []byte, platform bool) ([]byte, bool) {
	var view struct {
		OK    bool                 `json:"ok"`
		Items []controller.Problem `json:"items"`
	}
	if err := json.Unmarshal(data, &view); err != nil {
		return data, false
	}
	out, err := json.Marshal(controller.NewProblemsViewFor(view.Items, platform))
	if err != nil {
		return data, false
	}
	return out, true
}

// updatesFor narrows an already-rendered update status to one audience, and
// reports whether it could, as problemsFor does for the problems list.
//
// A platform subscriber is sent the frame as it came, untouched. ok is false
// when the payload is not a status this version understands, and the caller drops
// it for anybody below the platform rather than guess what is in it.
func updatesFor(data []byte, platform bool) ([]byte, bool) {
	if platform {
		return data, true
	}
	var view controller.UpdatesView
	if err := json.Unmarshal(data, &view); err != nil {
		return data, false
	}
	out, err := json.Marshal(view.For(false))
	if err != nil {
		return data, false
	}
	return out, true
}

// hostsFor narrows an already-rendered host frame to one audience, and reports
// whether it could, as updatesFor does for the update status. Only the update
// block can differ between audiences, and only for an attempt that ended, so a
// frame that names no ended state is passed on untouched without being decoded:
// a host frame goes out on every heartbeat that moves anything, to every tab.
//
// The frame is re-encoded as a map of its raw fields, so that only the update
// block is rewritten and every other field reaches the browser as the
// controller wrote it.
func hostsFor(data []byte, platform bool) ([]byte, bool) {
	if platform {
		return data, true
	}
	if !bytes.Contains(data, []byte(`"`+store.UpdateFailed+`"`)) &&
		!bytes.Contains(data, []byte(`"`+store.UpdateTimedOut+`"`)) &&
		!bytes.Contains(data, []byte(`"`+store.UpdateCancelled+`"`)) {
		return data, true
	}
	var frame map[string]json.RawMessage
	if err := json.Unmarshal(data, &frame); err != nil {
		return data, false
	}
	raw, ok := frame["update"]
	if !ok || string(raw) == "null" {
		return data, true
	}
	var update controller.HostUpdateView
	if err := json.Unmarshal(raw, &update); err != nil {
		return data, false
	}
	narrowed, err := json.Marshal(update.For(false))
	if err != nil {
		return data, false
	}
	frame["update"] = narrowed
	out, err := json.Marshal(frame)
	if err != nil {
		return data, false
	}
	return out, true
}

// withoutAcknowledger drops who marked a failure as known from an
// already-rendered job frame, and from the job a runner frame carries as its
// current_job. The acknowledgement's time stays: a visitor is told that a
// failure was marked, and when.
//
// It re-encodes the frame as a map of its raw fields, as hostsFor does, so that
// nothing else in it is rewritten. ok is false when the frame will not decode,
// and the caller drops it rather than send what it could not look through.
func withoutAcknowledger(data []byte) ([]byte, bool) {
	var frame map[string]json.RawMessage
	if err := json.Unmarshal(data, &frame); err != nil {
		return nil, false
	}
	delete(frame, "acknowledged_by")
	if raw, ok := frame["current_job"]; ok && string(raw) != "null" {
		job, ok := withoutAcknowledger(raw)
		if !ok {
			return nil, false
		}
		frame["current_job"] = job
	}
	out, err := json.Marshal(frame)
	if err != nil {
		return nil, false
	}
	return out, true
}

// withoutEnvValues blanks the env values in an already-rendered pool frame,
// keeping every key.
//
// It works on the encoded bytes because that is what the bus carries: a frame
// is rendered once and fanned out to every subscriber, so the alternative --
// rendering per connection -- would make one viewer's presence cost every
// other subscriber a re-render. Only a viewer's connection pays for this, and
// only on a pool frame.
//
// A payload that does not parse is passed through untouched rather than
// dropped: it cannot be a pool view, and swallowing frames would be a worse
// failure than the one this guards against.
func withoutEnvValues(data []byte) []byte {
	var frame map[string]json.RawMessage
	if err := json.Unmarshal(data, &frame); err != nil {
		return data
	}
	raw, ok := frame["env"]
	if !ok {
		return data
	}
	var env map[string]string
	if err := json.Unmarshal(raw, &env); err != nil || len(env) == 0 {
		return data
	}
	for k := range env {
		env[k] = ""
	}
	blanked, err := json.Marshal(env)
	if err != nil {
		return data
	}
	frame["env"] = blanked
	out, err := json.Marshal(frame)
	if err != nil {
		return data
	}
	return out
}

