func TestTheRobotsDirectiveFollowsTheSetting(t *testing.T) {
	for _, tc := range []struct {
		name    string
		allowed bool
		want    string
	}{
		{"the default keeps the controller out of search results", false, `content="noindex, nofollow"`},
		{"an operator can invite indexing", true, `content="index, follow"`},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h, err := newSPAHandler("https://zoomies.test", tc.allowed)
			if err != nil {
				t.Fatalf("newSPAHandler: %v", err)
			}
			page := string(h.index)
			if strings.Contains(page, robotsToken) {
				t.Errorf("the served page still carries %s", robotsToken)
			}
			if !h.built {
				return
			}
			if !strings.Contains(page, tc.want) {
				t.Errorf("the page does not carry %s", tc.want)
			}
		})
	}
}

// TestStructuredDataIsNotAllowedToRun covers a policy that has to stay
// truthful: JSON-LD is data the browser never executes, so hashing it into
// script-src would widen the policy to cover something that is not a script.
func TestStructuredDataIsNotAllowedToRun(t *testing.T) {
	page := []byte(`<script type="application/ld+json">{"@type":"WebApplication"}</script>` +
		`<script>console.log(1)</script>`)
	got := inlineScriptHashes(page)
	if len(got) != 1 {
		t.Fatalf("%d hashes for one executable script: %v", len(got), got)
	}
}

// TestAnUpgradedControllerStopsServing304ForIndex is the regression test for
// the bug that made a route fail to load after every upgrade.
//
// index.html is sent no-cache, so a browser revalidates it on every visit. It
// used to be given a Last-Modified taken from buildTime(), a constant, which
// meant an upgraded controller answered that revalidation 304 and the browser
// kept the previous build's page -- and with it the names of content-hashed
// chunks that are no longer in the binary. The shell booted anyway from its own
// immutable cached bundle, so what the operator saw was one route, the first
// one they had not already visited, failing with "That page could not be
// loaded" until they bypassed the cache by hand.
func TestAnUpgradedControllerStopsServing304ForIndex(t *testing.T) {
	before, err := newSPAHandler("https://zoomies.test", false)
	if err != nil {
		t.Fatalf("newSPAHandler: %v", err)
	}

	first := httptest.NewRecorder()
	before.ServeHTTP(first, httptest.NewRequest(http.MethodGet, "/", nil))
	if first.Code != http.StatusOK {
		t.Fatalf("first load = %d, want 200", first.Code)
	}
	etag := first.Header().Get("ETag")
	if etag == "" {
		t.Fatal("index.html was served with no ETag, so nothing but the clock can validate it")
	}
	// Sending one would re-open the hole: a browser holding the old page sends
	// only If-Modified-Since, and ServeContent honours it whenever a
	// modification time is set.
	if got := first.Header().Get("Last-Modified"); got != "" {
		t.Errorf("Last-Modified = %q, want it absent so If-Modified-Since cannot decide this", got)
	}

	// The operator upgrades. The page changes, because it names new chunks.
	after := *before
	after.index = []byte("<!doctype html><script type=module src=/assets/index.NEW.js></script>")
	sum := sha256.Sum256(after.index)
	after.indexETag = `"` + base64.RawURLEncoding.EncodeToString(sum[:16]) + `"`

	// A browser that cached before the fix has no ETag to send, only a date.
	stale := httptest.NewRequest(http.MethodGet, "/", nil)
	stale.Header.Set("If-Modified-Since", buildTime().UTC().Format(http.TimeFormat))
	staleResp := httptest.NewRecorder()
	after.ServeHTTP(staleResp, stale)
	if staleResp.Code != http.StatusOK {
		t.Errorf("a browser holding the old page got %d; it keeps the previous build's chunk URLs, which 404",
			staleResp.Code)
	}

	// And one that has the new validator is told, correctly, that the page it
	// is holding is no longer the page being served.
	revalidate := httptest.NewRequest(http.MethodGet, "/", nil)
	revalidate.Header.Set("If-None-Match", etag)
	revalidateResp := httptest.NewRecorder()
	after.ServeHTTP(revalidateResp, revalidate)
	if revalidateResp.Code != http.StatusOK {
		t.Errorf("revalidating a changed page = %d, want 200", revalidateResp.Code)
	}
}

// TestAnUnchangedIndexStillRevalidatesTo304 is the other half: the fix must not
// turn every visit into a full download of a page that has not changed.
func TestAnUnchangedIndexStillRevalidatesTo304(t *testing.T) {
	h, err := newSPAHandler("https://zoomies.test", false)
	if err != nil {
		t.Fatalf("newSPAHandler: %v", err)
	}
	first := httptest.NewRecorder()
	h.ServeHTTP(first, httptest.NewRequest(http.MethodGet, "/", nil))
	etag := first.Header().Get("ETag")

	again := httptest.NewRequest(http.MethodGet, "/", nil)
	again.Header.Set("If-None-Match", etag)
	againResp := httptest.NewRecorder()
	h.ServeHTTP(againResp, again)
	if againResp.Code != http.StatusNotModified {
		t.Errorf("revalidating an unchanged page = %d, want 304", againResp.Code)
	}
}

// TestTwoExternalURLsGetDifferentIndexValidators covers the reason the ETag is
// computed after the startup substitution rather than from the embedded file:
// the same binary serves a different page depending on what it was told its
// address is.
func TestTwoExternalURLsGetDifferentIndexValidators(t *testing.T) {
	one, err := newSPAHandler("https://one.example", false)
	if err != nil {
		t.Fatalf("newSPAHandler: %v", err)
	}
	two, err := newSPAHandler("https://two.example", false)
	if err != nil {
		t.Fatalf("newSPAHandler: %v", err)
	}
	// A build with no UI has no sharing tags to substitute into, so there is
	// nothing that could differ.
	if !one.built {
		t.Skip("the UI was not built; the placeholder page has no address in it")
	}
	if one.indexETag == two.indexETag {
		t.Error("two controllers on different addresses serve the same validator for different pages")
	}
}

package api

import (
	"net/http"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// The Workflows page lists runs and opens each to its jobs, and both halves
// come from the same rows: a run's row sums the jobs GET /jobs?run_id= lists
// under it, so the two cannot disagree about how the run is getting on.
func TestWorkflowRunsAreListedAndOpenToTheirJobs(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux")
	running := h.job(pool, store.JobInProgress) // run 1, queued a minute ago

	queued := time.Now().Add(-2 * time.Minute)
	started := queued.Add(time.Second)
	done := queued.Add(30 * time.Second)
	for _, j := range []*store.Job{
		{GitHubJobID: 201, JobName: "build", State: store.JobCompleted, Conclusion: "success"},
		{GitHubJobID: 202, JobName: "test", State: store.JobCompleted, Conclusion: "failure"},
	} {
		j.GitHubRunID, j.RunNumber, j.RunAttempt = 2, 42, 1
		j.Repo, j.Workflow, j.HeadBranch = "acme/widgets", "ci", "main"
		j.Labels = store.StringSlice{"self-hosted", "linux", "x64"}
		j.InstallationID, j.PoolID, j.Matched = pool.InstallationID, pool.ID, true
		j.QueuedAt, j.StartedAt, j.CompletedAt = queued, &started, &done
		j.HTMLURL = "https://github.com/acme/widgets/actions/runs/2/job/" + j.JobName
		if _, err := h.st.UpsertJob(h.ctx, j); err != nil {
			t.Fatalf("recording %s: %v", j.JobName, err)
		}
	}
	_, cookie := h.user("viewer", store.RoleViewer)

	type run struct {
		GitHubRunID int64  `json:"github_run_id"`
		RunNumber   int64  `json:"run_number"`
		State       string `json:"state"`
		Conclusion  string `json:"conclusion"`
		HTMLURL     string `json:"html_url"`
		Managed     bool   `json:"managed"`
		Jobs        struct {
			Total     int `json:"total"`
			Succeeded int `json:"succeeded"`
			Failed    int `json:"failed"`
		} `json:"jobs"`
		DurationMS int64 `json:"duration_ms"`
	}
	var page struct {
		Items []run `json:"items"`
		Total int   `json:"total"`
	}
	resp := h.do(request{method: http.MethodGet, path: "/api/v1/workflow-runs?sort=queued_at&order=asc", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "listing workflow runs")
	resp.into(t, &page)
	if page.Total != 2 || len(page.Items) != 2 {
		t.Fatalf("runs = %+v (total %d), want the two runs", page.Items, page.Total)
	}
	failed := page.Items[0]
	if failed.GitHubRunID != 2 || failed.RunNumber != 42 || failed.State != "completed" || failed.Conclusion != "failure" {
		t.Fatalf("first run = %+v, want run 2 (#42) completed as a failure", failed)
	}
	if failed.Jobs.Total != 2 || failed.Jobs.Succeeded != 1 || failed.Jobs.Failed != 1 || !failed.Managed {
		t.Fatalf("run 2 = %+v, want two jobs, one each way, on this fleet", failed)
	}
	if failed.HTMLURL != "https://github.com/acme/widgets/actions/runs/2" {
		t.Fatalf("run 2 links to %q, want the run's own page", failed.HTMLURL)
	}
	if failed.DurationMS != 29_000 {
		t.Fatalf("run 2 took %dms, want the 29s from first start to last finish", failed.DurationMS)
	}
	if got := page.Items[1]; got.GitHubRunID != running.GitHubRunID || got.State != "in_progress" || got.Conclusion != "" {
		t.Fatalf("second run = %+v, want run 1 still in progress", got)
	}

	// The status views name the run's own status.
	for _, tc := range []struct {
		query string
		want  int64
	}{
		{"failed=true", 2},
		{"state=in_progress", 1},
		{"conclusion=failure", 2},
	} {
		resp := h.do(request{method: http.MethodGet, path: "/api/v1/workflow-runs?" + tc.query, cookie: cookie})
		resp.mustStatus(t, http.StatusOK, "listing runs by "+tc.query)
		resp.into(t, &page)
		if page.Total != 1 || len(page.Items) != 1 || page.Items[0].GitHubRunID != tc.want {
			t.Errorf("%s: runs = %+v (total %d), want run %d alone", tc.query, page.Items, page.Total, tc.want)
		}
	}

	// Opening a run is the job listing narrowed to it.
	var jobs struct {
		Items []struct {
			GitHubRunID int64  `json:"github_run_id"`
			JobName     string `json:"job_name"`
		} `json:"items"`
		Total int `json:"total"`
	}
	resp = h.do(request{method: http.MethodGet, path: "/api/v1/jobs?repo=acme/widgets&run_id=2&sort=queued_at&order=asc", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "listing a run's jobs")
	resp.into(t, &jobs)
	if jobs.Total != 2 || len(jobs.Items) != 2 || jobs.Items[0].GitHubRunID != 2 || jobs.Items[1].GitHubRunID != 2 {
		t.Fatalf("jobs of run 2 = %+v (total %d), want its two", jobs.Items, jobs.Total)
	}

	// A run ID that is not one is refused rather than matching nothing.
	h.do(request{method: http.MethodGet, path: "/api/v1/jobs?run_id=latest", cookie: cookie}).
		mustStatus(t, http.StatusBadRequest, "a run ID that is not a number")
	h.do(request{method: http.MethodGet, path: "/api/v1/workflow-runs?state=running", cookie: cookie}).
		mustStatus(t, http.StatusBadRequest, "a state GitHub does not have")
	h.do(request{method: http.MethodGet, path: "/api/v1/workflow-runs"}).
		mustStatus(t, http.StatusUnauthorized, "listing runs without signing in")
}

// The Workflows page offers Run now, Pause and Resume on a run's own row, so
// an operator who knows the run from a pull request can hold or hurry all of
// it without opening it and pressing the same button on each job inside. It
// is the Queue page's control over the run's queued jobs, and no more: what
// GitHub thinks of the run does not change, and a job an operator removed
// from the queue on purpose is not swept back in by a Run now on its run.
func TestAWorkflowRunsQueuedJobsAreControlledTogether(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux")
	queued := time.Now().Add(-time.Minute)
	for _, j := range []*store.Job{
		{GitHubJobID: 301, JobName: "build", State: store.JobQueued},
		{GitHubJobID: 302, JobName: "test", State: store.JobQueued},
		{GitHubJobID: 303, JobName: "lint", State: store.JobQueued},
		{GitHubJobID: 304, JobName: "package", State: store.JobCompleted, Conclusion: "success"},
	} {
		j.GitHubRunID, j.RunNumber, j.RunAttempt = 7, 77, 1
		j.Repo, j.Workflow, j.HeadBranch = "acme/widgets", "ci", "main"
		j.Labels = store.StringSlice{"self-hosted", "linux", "x64"}
		j.InstallationID, j.PoolID, j.Matched = pool.InstallationID, pool.ID, true
		j.QueuedAt = queued
		if j.State == store.JobCompleted {
			started, done := queued.Add(time.Second), queued.Add(30*time.Second)
			j.StartedAt, j.CompletedAt = &started, &done
		}
		if _, err := h.st.UpsertJob(h.ctx, j); err != nil {
			t.Fatalf("recording %s: %v", j.JobName, err)
		}
	}
	lint, err := h.st.GetJobByGitHubID(h.ctx, 303)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := h.st.ControlProvisioning(h.ctx, []string{lint.ID}, "delete"); err != nil {
		t.Fatal(err)
	}
	_, operator := h.user("operator", store.RoleOperator)
	_, viewer := h.user("viewer", store.RoleViewer)

	body := map[string]any{"repo": "acme/widgets", "run_id": 7, "action": "pause"}
	h.do(request{method: http.MethodPost, path: "/api/v1/workflow-runs/provisioning", body: body, cookie: viewer}).
		mustStatus(t, http.StatusForbidden, "a viewer pausing a run")
	h.do(request{method: http.MethodPost, path: "/api/v1/workflow-runs/provisioning", cookie: operator,
		body: map[string]any{"repo": "acme/widgets", "run_id": 7, "action": "delete"}}).
		mustStatus(t, http.StatusBadRequest, "removing a whole run from the queue")
	h.do(request{method: http.MethodPost, path: "/api/v1/workflow-runs/provisioning", cookie: operator,
		body: map[string]any{"repo": "acme/widgets", "run_id": 999, "action": "pause"}}).
		mustStatus(t, http.StatusNotFound, "a run this fleet has never heard of")

	before := len(h.gh.Requests())
	var out struct {
		Results []store.ProvisioningResult `json:"results"`
	}
	type run struct {
		Jobs store.RunJobCounts `json:"jobs"`
	}
	var page struct {
		Items []run `json:"items"`
	}
	counts := func(when string) store.RunJobCounts {
		t.Helper()
		resp := h.do(request{method: http.MethodGet, path: "/api/v1/workflow-runs?repo=acme/widgets&run_id=7", cookie: viewer})
		resp.mustStatus(t, http.StatusOK, "listing the run "+when)
		resp.into(t, &page)
		if len(page.Items) != 1 {
			t.Fatalf("%s: runs = %+v, want the one", when, page.Items)
		}
		return page.Items[0].Jobs
	}
	if got := counts("before anything"); got.Queued != 3 || got.Removed != 1 || got.Paused != 0 || got.Expedited != 0 {
		t.Fatalf("before anything: %+v, want three queued of which one removed", got)
	}

	for _, tc := range []struct {
		action                     string
		expedited, paused, removed int
	}{
		{"pause", 0, 2, 1},
		{"run_now", 2, 0, 1},
		{"resume", 0, 0, 1},
	} {
		body["action"] = tc.action
		resp := h.do(request{method: http.MethodPost, path: "/api/v1/workflow-runs/provisioning", body: body, cookie: operator})
		resp.mustStatus(t, http.StatusOK, tc.action)
		resp.into(t, &out)
		// The two queued jobs still in the queue, and never the removed one
		// or the one that finished.
		if len(out.Results) != 2 {
			t.Fatalf("%s: results = %+v, want the two queued jobs", tc.action, out.Results)
		}
		for _, r := range out.Results {
			if !r.OK || r.ID == lint.ID {
				t.Fatalf("%s: results = %+v", tc.action, out.Results)
			}
		}
		got := counts("after " + tc.action)
		if got.Queued != 3 || got.Expedited != tc.expedited || got.Paused != tc.paused || got.Removed != tc.removed {
			t.Fatalf("after %s: %+v, want expedited=%d paused=%d removed=%d", tc.action, got, tc.expedited, tc.paused, tc.removed)
		}
	}
	if len(h.gh.Requests()) != before {
		t.Fatal("a run's provisioning controls called GitHub")
	}

	// Once the removed job is all that is left queued, there is nothing for
	// the run's row to act on, and the answer says so rather than doing
	// nothing quietly.
	var ids []string
	for _, gh := range []int64{301, 302} {
		j, err := h.st.GetJobByGitHubID(h.ctx, gh)
		if err != nil {
			t.Fatal(err)
		}
		ids = append(ids, j.ID)
	}
	if _, err := h.st.ControlProvisioning(h.ctx, ids, "delete"); err != nil {
		t.Fatal(err)
	}
	h.do(request{method: http.MethodPost, path: "/api/v1/workflow-runs/provisioning", body: body, cookie: operator}).
		mustStatus(t, http.StatusConflict, "a run with nothing left in the queue")
}

// Package assistanttest holds fake model servers for tests: one speaking the
// OpenAI chat-completions protocol, one speaking the Anthropic Messages
// protocol. Each records what it was asked so a test can assert the path,
// the headers and the body, and each answers the contract's prompts so the
// adapters' contract runs are about plumbing and not a model's mood.
package assistanttest

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"testing"
)

// Recorded is one request the server saw.
type Recorded struct {
	Method string
	Path   string
	Header http.Header
	Body   map[string]any
}

// Server is a fake model server. Status, when set, is what every request
// answers with, and Body its body; NoUsage leaves usage out of the stream.
type Server struct {
	*httptest.Server
	Model   string
	Status  int
	Body    string
	NoUsage bool
	// ModelsStatus, when set, is what the model list alone answers with, for a
	// gateway that serves completions and nothing else.
	ModelsStatus int
	// Models, when set, is what the model list answers with, in the order given;
	// otherwise it lists Model alone.
	Models []string
	// CallTool, when set, makes the OpenAI-protocol server answer a request that
	// offers a tool of that name, and has no tool's answer in it yet, by calling
	// it with no arguments. The request after that is answered in words.
	CallTool string
	// Cut, when set, ends an answer the way a provider does at its output
	// ceiling: the OpenAI-protocol server streams reasoning and no words and
	// finishes with length, the Anthropic one stops with max_tokens.
	Cut bool
	// Script, when set, is what the OpenAI-protocol server answers each chat
	// request with, in order: a round of tool calls with arguments, or words.
	// The last round answers every request after it. It takes precedence over
	// CallTool, and is what an evaluation scenario drives the loop with.
	Script []Round

	mu       sync.Mutex
	requests []Recorded
	chats    int
}

// Round is one scripted reply: the calls the model asks for, or, with none,
// the words it writes.
type Round struct {
	Calls []Call
	Text  string
}

// Call is one scripted tool call, its arguments as the JSON the model would send.
type Call struct {
	Name      string
	Arguments string
}

// Requests returns what the server has seen so far.
func (s *Server) Requests() []Recorded {
	s.mu.Lock()
	defer s.mu.Unlock()
	return append([]Recorded(nil), s.requests...)
}

func (s *Server) record(r *http.Request) Recorded {
	rec := Recorded{Method: r.Method, Path: r.URL.Path, Header: r.Header.Clone()}
	raw, _ := io.ReadAll(r.Body)
	if len(raw) > 0 {
		_ = json.Unmarshal(raw, &rec.Body)
	}
	s.mu.Lock()
	s.requests = append(s.requests, rec)
	s.mu.Unlock()
	return rec
}

func (s *Server) refuse(w http.ResponseWriter) bool {
	if s.Status == 0 {
		return false
	}
	w.WriteHeader(s.Status)
	fmt.Fprint(w, s.Body)
	return true
}

func (s *Server) refuseModels(w http.ResponseWriter) bool {
	if s.ModelsStatus == 0 {
		return s.refuse(w)
	}
	w.WriteHeader(s.ModelsStatus)
	fmt.Fprint(w, s.Body)
	return true
}

// lastUser finds the last user message's text in either protocol's body.
func lastUser(body map[string]any) string {
	msgs, _ := body["messages"].([]any)
	for i := len(msgs) - 1; i >= 0; i-- {
		m, _ := msgs[i].(map[string]any)
		if m["role"] != "user" {
			continue
		}
		switch c := m["content"].(type) {
		case string:
			return c
		case []any:
			for _, b := range c {
				bm, _ := b.(map[string]any)
				if bm["type"] == "text" {
					return bm["text"].(string)
				}
			}
		}
	}
	return ""
}

func wantsTool(body map[string]any) bool {
	tools, _ := body["tools"].([]any)
	return len(tools) > 0 && strings.HasPrefix(lastUser(body), "Call the echo tool")
}

func sse(w http.ResponseWriter, event string, data any) {
	raw, _ := json.Marshal(data)
	if event != "" {
		fmt.Fprintf(w, "event: %s\n", event)
	}
	fmt.Fprintf(w, "data: %s\n\n", raw)
	if f, ok := w.(http.Flusher); ok {
		f.Flush()
	}
}

// NewOpenAI starts a server speaking the OpenAI chat-completions protocol
// under /v1, and closes it when the test ends.
func NewOpenAI(t testing.TB) *Server {
	t.Helper()
	s := &Server{Model: "fake-gpt"}
	mux := http.NewServeMux()
	mux.HandleFunc("GET /v1/models", func(w http.ResponseWriter, r *http.Request) {
		s.record(r)
		if s.refuseModels(w) {
			return
		}
		ids := s.Models
		if ids == nil {
			ids = []string{s.Model}
		}
		data := []map[string]any{}
		for _, id := range ids {
			data = append(data, map[string]any{"id": id, "object": "model"})
		}
		_ = json.NewEncoder(w).Encode(map[string]any{"object": "list", "data": data})
	})
	mux.HandleFunc("POST /v1/chat/completions", func(w http.ResponseWriter, r *http.Request) {
		rec := s.record(r)
		if s.refuse(w) {
			return
		}
		w.Header().Set("Content-Type", "text/event-stream")
		chunk := func(delta map[string]any, finish any) map[string]any {
			return map[string]any{"id": "chatcmpl-1", "object": "chat.completion.chunk", "model": s.Model,
				"choices": []any{map[string]any{"index": 0, "delta": delta, "finish_reason": finish}}}
		}
		s.mu.Lock()
		turn := s.chats
		s.chats++
		s.mu.Unlock()
		if len(s.Script) > 0 {
			round := s.Script[min(turn, len(s.Script)-1)]
			if len(round.Calls) > 0 {
				for i, call := range round.Calls {
					sse(w, "", chunk(map[string]any{"tool_calls": []any{map[string]any{"index": i, "id": fmt.Sprintf("call_%d_%d", turn, i), "type": "function",
						"function": map[string]any{"name": call.Name, "arguments": call.Arguments}}}}, nil))
				}
				sse(w, "", chunk(map[string]any{}, "tool_calls"))
			} else {
				for _, word := range strings.SplitAfter(round.Text, " ") {
					sse(w, "", chunk(map[string]any{"content": word}, nil))
				}
				sse(w, "", chunk(map[string]any{}, "stop"))
			}
		} else if s.CallTool != "" && offersTool(rec.Body, s.CallTool) && !hasToolAnswer(rec.Body) {
			sse(w, "", chunk(map[string]any{"tool_calls": []any{map[string]any{"index": 0, "id": "call_fleet", "type": "function",
				"function": map[string]any{"name": s.CallTool, "arguments": `{}`}}}}, nil))
			sse(w, "", chunk(map[string]any{}, "tool_calls"))
		} else if wantsTool(rec.Body) {
			sse(w, "", chunk(map[string]any{"tool_calls": []any{map[string]any{"index": 0, "id": "call_1", "type": "function",
				"function": map[string]any{"name": "echo", "arguments": `{"text":`}}}}, nil))
			sse(w, "", chunk(map[string]any{"tool_calls": []any{map[string]any{"index": 0,
				"function": map[string]any{"arguments": `"ping"}`}}}}, nil))
			sse(w, "", chunk(map[string]any{}, "tool_calls"))
		} else if s.Cut {
			for _, word := range []string{"Thinking", " about it"} {
				sse(w, "", chunk(map[string]any{"reasoning_content": word}, nil))
			}
			sse(w, "", chunk(map[string]any{}, "length"))
		} else {
			for _, word := range []string{"Hello", " from", " the", " fake"} {
				sse(w, "", chunk(map[string]any{"content": word}, nil))
			}
			sse(w, "", chunk(map[string]any{}, "stop"))
		}
		if !s.NoUsage {
			sse(w, "", map[string]any{"id": "chatcmpl-1", "object": "chat.completion.chunk", "model": s.Model, "choices": []any{},
				"usage": map[string]any{"prompt_tokens": 7, "completion_tokens": 4}})
		}
		fmt.Fprint(w, "data: [DONE]\n\n")
	})
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		s.record(r)
		http.Error(w, `{"error":{"message":"no such route"}}`, http.StatusNotFound)
	})
	s.Server = httptest.NewServer(mux)
	t.Cleanup(s.Close)
	return s
}

// NewAnthropic starts a server speaking the Anthropic Messages protocol, and
// closes it when the test ends.
func NewAnthropic(t testing.TB) *Server {
	t.Helper()
	s := &Server{Model: "fake-claude"}
	mux := http.NewServeMux()
	mux.HandleFunc("GET /v1/models", func(w http.ResponseWriter, r *http.Request) {
		s.record(r)
		if s.refuseModels(w) {
			return
		}
		ids := s.Models
		if ids == nil {
			ids = []string{s.Model}
		}
		data := []map[string]any{}
		for _, id := range ids {
			data = append(data, map[string]any{"type": "model", "id": id})
		}
		_ = json.NewEncoder(w).Encode(map[string]any{"data": data, "has_more": false})
	})
	mux.HandleFunc("POST /v1/messages", func(w http.ResponseWriter, r *http.Request) {
		rec := s.record(r)
		if s.refuse(w) {
			return
		}
		w.Header().Set("Content-Type", "text/event-stream")
		usage := map[string]any{"input_tokens": 7}
		if s.NoUsage {
			usage = nil
		}
		sse(w, "message_start", map[string]any{"type": "message_start", "message": map[string]any{"id": "msg_1", "type": "message",
			"role": "assistant", "model": s.Model, "content": []any{}, "usage": usage}})
		if wantsTool(rec.Body) {
			sse(w, "content_block_start", map[string]any{"type": "content_block_start", "index": 0,
				"content_block": map[string]any{"type": "tool_use", "id": "toolu_1", "name": "echo", "input": map[string]any{}}})
			sse(w, "content_block_delta", map[string]any{"type": "content_block_delta", "index": 0,
				"delta": map[string]any{"type": "input_json_delta", "partial_json": `{"text":`}})
			sse(w, "content_block_delta", map[string]any{"type": "content_block_delta", "index": 0,
				"delta": map[string]any{"type": "input_json_delta", "partial_json": `"ping"}`}})
			sse(w, "content_block_stop", map[string]any{"type": "content_block_stop", "index": 0})
		} else {
			sse(w, "content_block_start", map[string]any{"type": "content_block_start", "index": 0,
				"content_block": map[string]any{"type": "text", "text": ""}})
			for _, word := range []string{"Hello", " from", " the", " fake"} {
				sse(w, "content_block_delta", map[string]any{"type": "content_block_delta", "index": 0,
					"delta": map[string]any{"type": "text_delta", "text": word}})
			}
			sse(w, "content_block_stop", map[string]any{"type": "content_block_stop", "index": 0})
		}
		stop := "end_turn"
		if s.Cut {
			stop = "max_tokens"
		}
		delta := map[string]any{"type": "message_delta", "delta": map[string]any{"stop_reason": stop}}
		if !s.NoUsage {
			delta["usage"] = map[string]any{"output_tokens": 4}
		}
		sse(w, "message_delta", delta)
		sse(w, "message_stop", map[string]any{"type": "message_stop"})
	})
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		s.record(r)
		http.Error(w, `{"type":"error","error":{"type":"not_found_error","message":"no such route"}}`, http.StatusNotFound)
	})
	s.Server = httptest.NewServer(mux)
	t.Cleanup(s.Close)
	return s
}

// offersTool reports whether a chat request lists a tool by that name.
func offersTool(body map[string]any, name string) bool {
	tools, _ := body["tools"].([]any)
	for _, t := range tools {
		fn, _ := t.(map[string]any)["function"].(map[string]any)
		if fn["name"] == name {
			return true
		}
	}
	return false
}

// hasToolAnswer reports whether a chat request already carries a tool's answer.
func hasToolAnswer(body map[string]any) bool {
	msgs, _ := body["messages"].([]any)
	for _, m := range msgs {
		if mm, _ := m.(map[string]any); mm["role"] == "tool" {
			return true
		}
	}
	return false
}

package assistant

import (
	"context"
	"encoding/json"
	"errors"
	"testing"
	"time"
)

// ContractPrompt is the one prompt the contract sends with a tool offered: a
// real adapter's contract run answers it from a fake server that calls the
// tool, so the test is about the adapter's plumbing and not a model's mood.
const ContractPrompt = `Call the echo tool with "ping"`

// RunContractTests is the conformance suite every provider passes. It lives
// beside the interface so that the interface's promises (a stream ends, usage
// precedes Done, cancellation is honoured, Close is safe) are tested the same
// way for each adapter rather than described in a comment.
func RunContractTests(t *testing.T, name string, open func(t *testing.T) Provider) {
	t.Helper()
	ask := func(text string, tools ...Tool) Request {
		return Request{Messages: []Message{{Role: RoleUser, Content: text}}, Tools: tools}
	}
	t.Run(name+"/a chat streams at least one delta and ends with Done", func(t *testing.T) {
		events := drain(t, open(t), ask("Say hello"))
		deltas := 0
		for _, e := range events {
			if e.Delta != "" {
				deltas++
			}
		}
		if deltas == 0 {
			t.Error("no text delta")
		}
		if last := events[len(events)-1]; !last.Done {
			t.Errorf("last event %+v is not Done", last)
		}
	})
	t.Run(name+"/usage, when reported, arrives before Done", func(t *testing.T) {
		seenDone := false
		for _, e := range drain(t, open(t), ask("Say hello")) {
			if e.Usage != nil && seenDone {
				t.Error("usage after Done")
			}
			if e.Done {
				seenDone = true
			}
		}
	})
	t.Run(name+"/a cancelled context ends the stream", func(t *testing.T) {
		ctx, cancel := context.WithCancel(context.Background())
		s, err := open(t).Chat(ctx, ask("Count to one hundred slowly"))
		if err != nil {
			t.Fatal(err)
		}
		defer s.Close()
		cancel()
		deadline := time.After(2 * time.Second)
		for {
			type result struct {
				e  Event
				ok bool
			}
			ch := make(chan result, 1)
			go func() { e, ok := s.Next(ctx); ch <- result{e, ok} }()
			select {
			case r := <-ch:
				if !r.ok {
					t.Fatal("the stream ended without an error event")
				}
				if r.e.Err != nil {
					if !errors.Is(r.e.Err, context.Canceled) {
						t.Errorf("error %v is not context.Canceled", r.e.Err)
					}
					if _, ok := s.Next(ctx); ok {
						t.Error("Next returned an event after the error")
					}
					return
				}
				if r.e.Done {
					t.Fatal("the stream finished instead of being cancelled")
				}
			case <-deadline:
				t.Fatal("Next did not return within two seconds of cancellation")
			}
		}
	})
	t.Run(name+"/Close after Done returns nil", func(t *testing.T) {
		s, err := open(t).Chat(context.Background(), ask("Say hello"))
		if err != nil {
			t.Fatal(err)
		}
		for {
			e, ok := s.Next(context.Background())
			if !ok || e.Done || e.Err != nil {
				break
			}
		}
		if err := s.Close(); err != nil {
			t.Errorf("Close: %v", err)
		}
	})
	t.Run(name+"/Check names the model", func(t *testing.T) {
		res, err := open(t).Check(context.Background())
		if err != nil {
			t.Fatal(err)
		}
		if res.Model == "" {
			t.Error("Check returned no model")
		}
	})
	t.Run(name+"/a tool offered with the contract prompt is called", func(t *testing.T) {
		tool := Tool{Name: "echo", Description: "Echo the text", Parameters: json.RawMessage(`{"type":"object","properties":{"text":{"type":"string"}}}`)}
		var call *ToolCall
		for _, e := range drain(t, open(t), ask(ContractPrompt, tool)) {
			if e.ToolCall != nil {
				call = e.ToolCall
			}
		}
		if call == nil || call.Name != "echo" {
			t.Fatalf("tool call %+v", call)
		}
		if !json.Valid(call.Arguments) {
			t.Errorf("arguments %q are not JSON", call.Arguments)
		}
	})
}

// drain reads a chat to its end and fails on an error event.
func drain(t *testing.T, p Provider, req Request) []Event {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	s, err := p.Chat(ctx, req)
	if err != nil {
		t.Fatal(err)
	}
	defer s.Close()
	var events []Event
	for {
		e, ok := s.Next(ctx)
		if !ok {
			t.Fatal("the stream ended without Done")
		}
		if e.Err != nil {
			t.Fatalf("stream error: %v", e.Err)
		}
		events = append(events, e)
		if e.Done {
			return events
		}
	}
}

package assistant

import (
	"encoding/json"
	"fmt"
	"strings"
	"time"
)

// Only named fleet-status fields become prose. Missing figures stay missing,
// and repository names or arbitrary tool text cannot become demo advice.
type demoJobStats struct {
	Queued     *int   `json:"queued_jobs"`
	Running    *int   `json:"running_jobs"`
	Completed  *int   `json:"completed"`
	Passed     *int   `json:"succeeded"`
	Failed     *int   `json:"failed"`
	FleetFault *int   `json:"fleet_failed"`
	Cancelled  *int   `json:"cancelled"`
	Unknown    *int   `json:"unknown"`
	MedianWait *int64 `json:"median_wait_ms"`
	P95Wait    *int64 `json:"p95_wait_ms"`
}

func demoFleetSummary(raw string) string {
	var status struct {
		demoJobStats
		Window string        `json:"window"`
		Fleet  *demoJobStats `json:"fleet"`
		Hosts  *struct {
			Healthy *int `json:"healthy"`
			Total   *int `json:"total"`
		} `json:"hosts"`
		Runners *struct {
			Total *int `json:"total"`
			Busy  *int `json:"busy"`
			Idle  *int `json:"idle"`
		} `json:"runners"`
		Faults map[string]int `json:"faults"`
	}
	const unavailable = "The fleet lookup returned a response the demo model cannot summarise. Try again, or use a configured model provider for a fuller investigation."
	if err := json.Unmarshal([]byte(raw), &status); err != nil {
		return unavailable
	}
	jobs := status.demoJobStats
	if status.Fleet != nil {
		// The top-level counts include jobs on other runners. When supplied,
		// this scope answers the question about this Zoomies fleet.
		jobs = *status.Fleet
	}
	var now, recent []string
	line := func(lines *[]string, label, text string) {
		if text != "" {
			*lines = append(*lines, "- **"+label+":** "+text+".")
		}
	}
	line(&now, "Jobs", demoCounts(demoCount{jobs.Queued, "waiting"}, demoCount{jobs.Running, "running"}))
	if status.Runners != nil {
		r := status.Runners
		line(&now, "Runners", demoCounts(demoCount{r.Total, "total"}, demoCount{r.Busy, "busy"}, demoCount{r.Idle, "idle"}))
	}
	if h := status.Hosts; h != nil && h.Healthy != nil && h.Total != nil && *h.Healthy >= 0 && *h.Total >= *h.Healthy {
		line(&now, "Hosts", fmt.Sprintf("%d of %d healthy", *h.Healthy, *h.Total))
	}
	line(&recent, "Completed jobs", demoCounts(demoCount{jobs.Completed, "finished"}, demoCount{jobs.Passed, "passed"}, demoCount{jobs.Failed, "failed"}, demoCount{jobs.Cancelled, "cancelled"}, demoCount{jobs.Unknown, "with an unknown outcome"}))
	if jobs.FleetFault != nil && *jobs.FleetFault >= 0 {
		line(&recent, "Runner-related job failures", fmt.Sprintf("%d", *jobs.FleetFault))
	}
	if jobs.MedianWait != nil && jobs.P95Wait != nil && *jobs.MedianWait >= 0 && *jobs.P95Wait >= 0 {
		line(&recent, "Queue wait", fmt.Sprintf("median %s; 95%% of measured waits were %s or less", demoSeconds(*jobs.MedianWait), demoSeconds(*jobs.P95Wait)))
	}
	if len(now)+len(recent) == 0 {
		return unavailable
	}
	sections := []string{"**Fleet summary**"}
	if len(now) > 0 {
		sections = append(sections, "**Right now**\n\n"+strings.Join(now, "\n"))
	}
	if len(recent) > 0 {
		label := "Recent outcomes"
		if window, err := time.ParseDuration(status.Window); err == nil && window > 0 {
			if window%time.Hour == 0 {
				label = "Over the last " + demoPeriod(int64(window/time.Hour), "hour")
			} else if window%time.Minute == 0 {
				label = "Over the last " + demoPeriod(int64(window/time.Minute), "minute")
			}
		}
		sections = append(sections, "**"+label+"**\n\n"+strings.Join(recent, "\n"))
	}
	next := "Open Jobs for individual results and Overview for current capacity."
	switch {
	case status.Faults["out_of_memory"] > 0:
		next = "A runner ran out of memory. Open the failed job in Jobs and review its memory limit and runner logs before changing its size."
	case jobs.FleetFault != nil && *jobs.FleetFault > 0:
		next = "Open the failed job in Jobs and review its runner fault and logs to understand the cause."
	case status.Hosts != nil && status.Hosts.Healthy != nil && status.Hosts.Total != nil && *status.Hosts.Healthy >= 0 && *status.Hosts.Healthy < *status.Hosts.Total:
		next = "Check the host health details in Hosts before relying on that capacity."
	case jobs.Queued != nil && *jobs.Queued > 0:
		next = "For waiting jobs, check Queue and Pools for matching labels and available capacity."
	}
	sections = append(sections, "**Next step**\n\n"+next)
	return strings.Join(sections, "\n\n")
}

func demoSeconds(ms int64) string {
	if ms > 0 && ms < 1000 {
		if ms == 1 {
			return "1 millisecond"
		}
		return fmt.Sprintf("%d milliseconds", ms)
	}
	number := strings.TrimSuffix(fmt.Sprintf("%.1f", float64(ms)/1000), ".0")
	if number == "1" {
		return "1 second"
	}
	return number + " seconds"
}

func demoPeriod(count int64, unit string) string {
	if count == 1 {
		return unit
	}
	return fmt.Sprintf("%d %ss", count, unit)
}

// Cancelled and unknown outcomes are useful when present, not as empty noise.
type demoCount struct {
	count *int
	label string
}

func demoCounts(values ...demoCount) string {
	parts := []string{}
	for _, v := range values {
		if v.count == nil || *v.count < 0 {
			continue
		}
		if *v.count == 0 && (v.label == "cancelled" || v.label == "with an unknown outcome") {
			continue
		}
		parts = append(parts, fmt.Sprintf("%d %s", *v.count, v.label))
	}
	return strings.Join(parts, "; ")
}

