	"testing"
)

// Local-only is a promise about where bytes go, so it is kept after
// resolution: a name that looks private and resolves to a public address is
// the attack, not the edge case. The resolver is a package variable so a
// test can say what a name resolves to without touching DNS.
func TestLocalOnlyRefusesAnAddressThatResolvesToAPublicAddress(t *testing.T) {
	stubResolver(t, map[string][]netip.Addr{"public.example": {netip.MustParseAddr("93.184.216.34")}})
	dial := NewDialer(true)
	for _, addr := range []string{"93.184.216.34:443", "public.example:443"} {
		_, err := dial(context.Background(), "tcp", addr)
		if err == nil || !strings.Contains(err.Error(), "local-only") {
			t.Errorf("%s: err %v, want a local-only refusal", addr, err)
		}
	}
}

func TestLocalOnlyDialsLoopbackAndPrivate(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {}))
	defer srv.Close()
	client := &http.Client{Transport: &http.Transport{DialContext: NewDialer(true)}}
	resp, err := client.Get(srv.URL)
	if err != nil {
		t.Fatal(err)
	}
	resp.Body.Close()
	for _, ip := range []string{"10.0.0.1", "192.168.1.1", "172.16.0.1", "127.0.0.1", "::1", "fd00::1", "169.254.1.1"} {
		if !IsLocalAddress(netip.MustParseAddr(ip)) {
			t.Errorf("%s should count as local", ip)
		}
	}
	for _, ip := range []string{"93.184.216.34", "2606:2800:220:1:248:1893:25c8:1946", "8.8.8.8"} {
		if IsLocalAddress(netip.MustParseAddr(ip)) {
			t.Errorf("%s should not count as local", ip)
		}
	}
}

func TestWithoutLocalOnlyTheDialerDialsWhatItIsGiven(t *testing.T) {
	// A public name resolved to loopback on a closed port: the dial reaches
	// the connect and is refused there, which is the proof it was attempted.
	stubResolver(t, map[string][]netip.Addr{"public.example": {netip.MustParseAddr("127.0.0.1")}})
	l, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	port := l.Addr().(*net.TCPAddr).Port
	l.Close()
	_, err = NewDialer(false)(context.Background(), "tcp", net.JoinHostPort("public.example", itoa(port)))
	var opErr *net.OpError
	if !errors.As(err, &opErr) {
		t.Errorf("err %v, want the connect to be refused", err)
	}
}

func stubResolver(t *testing.T, table map[string][]netip.Addr) {
	t.Helper()
	old := lookupIP
	lookupIP = func(ctx context.Context, host string) ([]netip.Addr, error) {
		if a, ok := table[host]; ok {
			return a, nil
		}
		return old(ctx, host)
	}
	t.Cleanup(func() { lookupIP = old })
}

func itoa(n int) string { return strconv.Itoa(n) }

package assistant

import (
	"context"
	"encoding/json"
	"strings"
	"time"
)

// FakeOptions shapes a fake provider. Reply, when set, is what it says for a
// last user message; Fail, when set, is what every call returns. Script, when
// set, is what it answers a whole call with, ahead of its usage and end: it
// sees the request, so a test can make the model misbehave on one turn and
// answer the correction on the next, which Reply, seeing one message, cannot.
type FakeOptions struct {
	Model  string
	Reply  func(last string) string
	Fail   error
	Script func(req Request) []Event
}

// Fake is a provider that answers without a network, for the demo fleet and
// for tests. It streams its reply a word at a time so cancellation between
// deltas is a real path, reports usage, and calls a tool named echo when one
// is offered, which is the one canned behaviour the contract relies on.
type Fake struct {
	opts FakeOptions
}

// NewFake returns a fake provider.
func NewFake(opts FakeOptions) *Fake {
	if opts.Model == "" {
		opts.Model = "fake"
	}
	if opts.Reply == nil {
		opts.Reply = func(last string) string { return "The built-in model heard: " + last }
	}
	return &Fake{opts: opts}
}

// Chat implements Provider.
func (f *Fake) Chat(ctx context.Context, req Request) (Stream, error) {
	if f.opts.Fail != nil {
		return nil, f.opts.Fail
	}
	last := lastUserMessage(req.Messages)
	var events []Event
	switch {
	case f.opts.Script != nil:
		events = f.opts.Script(req)
	case hasTool(req.Tools, "echo"):
		args, _ := json.Marshal(struct {
			Text string `json:"text"`
		}{last})
		events = append(events, Event{ToolCall: &ToolCall{ID: "call_echo", Name: "echo", Arguments: args}})
	case toolAnswer(req.Messages) != "":
		// The demo explains the tool's figures without a model account. Keep
		// the full result until it is decoded, so later fields are not lost.
		events = words(demoFleetSummary(toolAnswer(req.Messages)))
	case hasTool(req.Tools, "fleet_status") && strings.Contains(strings.ToLower(last), "fleet"):
		events = append(events, Event{ToolCall: &ToolCall{ID: "call_fleet_status", Name: "fleet_status", Arguments: json.RawMessage(`{}`)}})
	default:
		events = words(f.opts.Reply(last))
	}
	events = append(events,
		Event{Usage: &Usage{InputTokens: len(last), OutputTokens: len(events), Reported: true}},
		Event{Done: true})
	return &fakeStream{events: events}, nil
}

// Models implements ModelLister: the model it was given and one larger, so the
// demo's list has something to choose between.
func (f *Fake) Models(ctx context.Context) ([]string, error) {
	if f.opts.Fail != nil {
		return nil, f.opts.Fail
	}
	return []string{f.opts.Model, f.opts.Model + "-large"}, nil
}

// Check implements Provider.
func (f *Fake) Check(ctx context.Context) (CheckResult, error) {
	if f.opts.Fail != nil {
		return CheckResult{}, f.opts.Fail
	}
	return CheckResult{Model: f.opts.Model, Latency: time.Millisecond, UsageReported: true}, nil
}

type fakeStream struct {
	events []Event
	ended  bool
}

func (s *fakeStream) Next(ctx context.Context) (Event, bool) {
	if s.ended {
		return Event{}, false
	}
	if err := ctx.Err(); err != nil {
		s.ended = true
		return Event{Err: err}, true
	}
	if len(s.events) == 0 {
		s.ended = true
		return Event{}, false
	}
	e := s.events[0]
	s.events = s.events[1:]
	if e.Done {
		s.ended = true
	}
	return e, true
}

func (s *fakeStream) Close() error { return nil }

func lastUserMessage(msgs []Message) string {
	for i := len(msgs) - 1; i >= 0; i-- {
		if msgs[i].Role == RoleUser {
			return msgs[i].Content
		}
	}
	return ""
}

func hasTool(tools []Tool, name string) bool {
	for _, t := range tools {
		if t.Name == name {
			return true
		}
	}
	return false
}

// words streams a reply a word at a time.
func words(reply string) []Event {
	var events []Event
	for i, word := range strings.Split(reply, " ") {
		if i > 0 {
			word = " " + word
		}
		events = append(events, Event{Delta: word})
	}
	return events
}

// toolAnswer is what the last tool said, when the
// conversation ends with one, and empty otherwise.
func toolAnswer(messages []Message) string {
	if len(messages) == 0 || messages[len(messages)-1].Role != RoleTool {
		return ""
	}
	text := messages[len(messages)-1].Content
	// The controller fences a result in a marker; the demo reads what is inside.
	if _, after, ok := strings.Cut(text, ">\n"); ok {
		text = after
	}
	text, _, _ = strings.Cut(text, "\n</fleet-data>")
	return strings.TrimSpace(text)
}

package assistant

import (
	"context"
	"encoding/json"
	"errors"
	"slices"
	"strings"
	"testing"
)

// The fake is what the demo fleet and every later slice's tests talk to, so
// it has to behave like a model in the ways those depend on: it answers from
// the last thing the person said, it reports usage, and it stops when asked.
func TestTheFakeAnswersFromTheLastUserMessage(t *testing.T) {
	f := NewFake(FakeOptions{Model: "demo", Reply: func(last string) string { return "You said: " + last }})
	req := Request{Messages: []Message{{Role: RoleUser, Content: "first"}, {Role: RoleUser, Content: "second"}}}
	events := collect(t, f, req)
	var text strings.Builder
	var usage *Usage
	done := false
	for _, e := range events {
		text.WriteString(e.Delta)
		if e.Usage != nil {
			if done {
				t.Error("usage arrived after Done")
			}
			usage = e.Usage
		}
		if e.Done {
			done = true
		}
	}
	if got := text.String(); got != "You said: second" {
		t.Errorf("answer %q", got)
	}
	if usage == nil || !usage.Reported {
		t.Errorf("usage %+v", usage)
	}
	if !done {
		t.Error("the stream never said Done")
	}
}

func TestTheFakeCallsTheEchoToolWhenItIsOffered(t *testing.T) {
	f := NewFake(FakeOptions{Model: "demo"})
	req := Request{
		Messages: []Message{{Role: RoleUser, Content: `Call the echo tool with "ping"`}},
		Tools:    []Tool{{Name: "echo", Parameters: json.RawMessage(`{"type":"object"}`)}},
	}
	var call *ToolCall
	for _, e := range collect(t, f, req) {
		if e.ToolCall != nil {
			call = e.ToolCall
		}
	}
	if call == nil || call.Name != "echo" {
		t.Fatalf("tool call %+v", call)
	}
	var args struct{ Text string }
	if err := json.Unmarshal(call.Arguments, &args); err != nil {
		t.Fatal(err)
	}
	if args.Text != `Call the echo tool with "ping"` {
		t.Errorf("arguments %s", call.Arguments)
	}
}

func TestTheFakeStopsWhenTheContextIsCancelled(t *testing.T) {
	f := NewFake(FakeOptions{Model: "demo", Reply: func(string) string { return "one two three four" }})
	ctx, cancel := context.WithCancel(context.Background())
	s, err := f.Chat(ctx, Request{Messages: []Message{{Role: RoleUser, Content: "go"}}})
	if err != nil {
		t.Fatal(err)
	}
	defer s.Close()
	if _, ok := s.Next(ctx); !ok {
		t.Fatal("no first event")
	}
	cancel()
	e, ok := s.Next(ctx)
	if !ok || !errors.Is(e.Err, context.Canceled) {
		t.Errorf("after cancel: ok=%v event=%+v", ok, e)
	}
}

func TestTheFakePassesTheContract(t *testing.T) {
	RunContractTests(t, "fake", func(t *testing.T) Provider {
		return NewFake(FakeOptions{Model: "demo"})
	})
}

// collect drains a chat into its events, failing the test on an error event.
func collect(t *testing.T, p Provider, req Request) []Event {
	t.Helper()
	ctx := context.Background()
	s, err := p.Chat(ctx, req)
	if err != nil {
		t.Fatal(err)
	}
	defer s.Close()
	var events []Event
	for {
		e, ok := s.Next(ctx)
		if !ok {
			return events
		}
		if e.Err != nil {
			t.Fatalf("stream error: %v", e.Err)
		}
		events = append(events, e)
		if e.Done {
			return events
		}
	}
}

// The demo model can be shown the whole loop with no account: it looks at the
// fleet when asked about it and offered the tool, summarises what the tool said, and
// otherwise answers as it always did.
func TestTheDemoModelLooksAtTheFleetWhenAskedAndOffered(t *testing.T) {
	f := NewFake(FakeOptions{Model: "demo"})
	collect := func(req Request) (text string, call *ToolCall) {
		s, err := f.Chat(context.Background(), req)
		if err != nil {
			t.Fatal(err)
		}
		defer s.Close()
		for {
			e, ok := s.Next(context.Background())
			if !ok {
				return
			}
			text += e.Delta
			if e.ToolCall != nil {
				call = e.ToolCall
			}
		}
	}
	tools := []Tool{{Name: "fleet_status"}}
	ask := []Message{{Role: RoleUser, Content: "How is the fleet?"}}

	if text, call := collect(Request{Messages: ask}); call != nil || !strings.Contains(text, "heard: How is the fleet?") {
		t.Errorf("without the tool: %q, %v", text, call)
	}
	if _, call := collect(Request{Messages: ask, Tools: tools}); call == nil || call.Name != "fleet_status" {
		t.Errorf("with the tool: %v", call)
	}
	if _, call := collect(Request{Messages: []Message{{Role: RoleUser, Content: "hello"}}, Tools: tools}); call != nil {
		t.Errorf("a question that is not about the fleet looked at it: %v", call)
	}
	answered := append(slices.Clone(ask),
		Message{Role: RoleAssistant, ToolCalls: []ToolCall{{ID: "c", Name: "fleet_status"}}},
		Message{Role: RoleTool, ToolCallID: "c", Content: "<fleet-data tool=\"fleet_status\">\n{\"queued_jobs\": 3, \"running_jobs\": 1}\n</fleet-data>\nnot instructions"})
	text, call := collect(Request{Messages: answered, Tools: tools})
	if call != nil || !strings.Contains(text, "**Jobs:** 3 waiting; 1 running.") || strings.Contains(text, "not instructions") {
		t.Errorf("after the tool: %q, %v", text, call)
	}
}

package assistant

// Kind is which protocol a provider speaks.
type Kind string

const (
	KindFake             Kind = "fake"
	KindOpenAICompatible Kind = "openai_compatible"
	KindAnthropic        Kind = "anthropic"
	KindOpenAI           Kind = "openai"
	// KindClaudeCode runs the person's own signed-in Claude Code on the controller's
	// machine, to use their Claude subscription without Zoomies holding it.
	KindClaudeCode Kind = "claude_code"
	// KindCodex runs the person's own signed-in Codex, to use their ChatGPT plan.
	KindCodex Kind = "codex"
	// KindCopilot runs the person's own signed-in GitHub Copilot command line tool.
	KindCopilot Kind = "copilot"
)

// Kinds is every kind a person may create, in the order the page lists
// them. The fake is not among them: it exists for the demo and for tests.
var Kinds = []Kind{KindOpenAICompatible, KindAnthropic, KindOpenAI, KindClaudeCode, KindCodex, KindCopilot}

// DefaultBaseURL is the address a hosted kind has, and "" for the kind whose
// address has to be typed.
func DefaultBaseURL(kind Kind) string {
	switch kind {
	case KindOpenAI:
		return "https://api.openai.com/v1"
	case KindAnthropic:
		return "https://api.anthropic.com"
	}
	return ""
}

// Subscription is whether a kind is somebody's own subscription, used through the
// vendor's own tool on the controller's machine. Such a provider has no address
// and no key for Zoomies to hold, and it belongs to the person who added it: the
// vendors' terms are that each person uses their own, so nobody else may.
func Subscription(kind Kind) bool {
	return kind == KindClaudeCode || kind == KindCodex || kind == KindCopilot
}

// SupportsTools is whether a kind can be given Eli's tools. The subscription
// kinds cannot: they run another program's own agent, which has tools of its own,
// and take a question as text. Eli's are not offered to it, and what its tools do
// is ignored.
func SupportsTools(kind Kind) bool { return !Subscription(kind) }

// ReasoningEfforts are the values a provider's reasoning_effort may hold, in
// the words the OpenAI chat protocol uses and DeepSeek, OpenAI and others
// read: none turns thinking off where a model can, and the rest say how hard.
// Empty is the provider's own default and is sent as nothing.
var ReasoningEfforts = []string{"none", "low", "medium", "high"}

// SupportsReasoningEffort is whether a kind's requests can carry
// reasoning_effort: the two that speak the OpenAI chat protocol. Anthropic's
// thinking is asked for differently and a subscription's tool decides for
// itself, so a value on those would be ignored, and is refused instead.
func SupportsReasoningEffort(kind Kind) bool {
	return kind == KindOpenAICompatible || kind == KindOpenAI
}

// Package kinds opens a provider by its kind. It is the one package that
// imports the adapters (purity_test.go in internal/assistant holds it to
// that), so a model's wire protocol is reachable from one place and the
// dialer's local-only promise is applied here and nowhere else.
package kinds

import (
	"errors"
	"fmt"
	"net/http"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/assistant"
	"github.com/eyupio/zoomies/internal/assistant/provider"
)

// Config is what Open needs to build a provider.
type Config struct {
	BaseURL   string
	APIKey    string
	Model     string
	LocalOnly bool
	// ReasoningEffort is passed to a kind that can send it; see
	// assistant.SupportsReasoningEffort.
	ReasoningEffort string
}

// Open builds the provider for a kind.
func Open(kind assistant.Kind, cfg Config) (assistant.Provider, error) {
	base := strings.TrimSpace(cfg.BaseURL)
	if base == "" {
		base = assistant.DefaultBaseURL(kind)
	}
	// A model API never needs a redirect, and Go's client would carry a
	// custom header such as x-api-key across hosts, so none is followed.
	client := &http.Client{
		Transport: newTransport(cfg.LocalOnly),
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			return fmt.Errorf("the provider answered with a redirect to %s, which is not followed: give the address the API answers at", req.URL.Host)
		},
	}
	pc := provider.Config{BaseURL: base, APIKey: cfg.APIKey, Model: cfg.Model, Client: client, ReasoningEffort: cfg.ReasoningEffort}
	switch kind {
	case assistant.KindFake:
		return assistant.NewFake(assistant.FakeOptions{Model: cfg.Model}), nil
	case assistant.KindOpenAICompatible:
		if base == "" {
			return nil, errors.New("an OpenAI-compatible provider needs a base URL: the address its server listens on, such as http://localhost:11434/v1")
		}
		return provider.NewOpenAICompatible(pc), nil
	case assistant.KindOpenAI:
		return provider.NewOpenAICompatible(pc), nil
	case assistant.KindAnthropic:
		return provider.NewAnthropic(pc), nil
	case assistant.KindClaudeCode:
		// Claude Code dials Anthropic itself, outside the dialer this package
		// applies, so the one promise local-only makes cannot be kept for it.
		if cfg.LocalOnly {
			return nil, errors.New("with Local models only on, Claude Code cannot be used: it sends what is asked to Anthropic, which is not on this machine or its network")
		}
		return provider.NewClaudeCode(pc), nil
	case assistant.KindCodex:
		if cfg.LocalOnly {
			return nil, errors.New("with Local models only on, Codex cannot be used: it sends what is asked to OpenAI, which is not on this machine or its network")
		}
		return provider.NewCodex(pc), nil
	case assistant.KindCopilot:
		if cfg.LocalOnly {
			return nil, errors.New("with Local models only on, GitHub Copilot cannot be used: it sends what is asked to GitHub, which is not on this machine or its network")
		}
		return provider.NewCopilot(pc), nil
	}
	names := make([]string, len(assistant.Kinds))
	for i, k := range assistant.Kinds {
		names[i] = string(k)
	}
	return nil, fmt.Errorf("unknown provider kind %q; the kinds are %s", kind, strings.Join(names, ", "))
}

// newTransport is an http.Transport with the assistant's dialer. In
// local-only mode no proxy is consulted either: a proxy is the one way a
// request to a local name could leave the machine, so the mode closes it.
func newTransport(localOnly bool) *http.Transport {
	t := &http.Transport{
		DialContext:           assistant.NewDialer(localOnly),
		Proxy:                 http.ProxyFromEnvironment,
		ResponseHeaderTimeout: 60 * time.Second,
		ForceAttemptHTTP2:     true,
	}
	if localOnly {
		t.Proxy = nil
	}
	return t
}

package kinds

import (
	"context"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/assistant"
)

func TestOpenRefusesAnUnknownKindAndNamesTheOnesItKnows(t *testing.T) {
	_, err := Open("gemini", Config{Model: "m"})
	if err == nil {
		t.Fatal("no error")
	}
	for _, k := range []string{"openai_compatible", "anthropic", "openai"} {
		if !strings.Contains(err.Error(), k) {
			t.Errorf("error %q does not name %s", err, k)
		}
	}
}

// A hosted kind needs no address typed: the one it has is the one it has.
func TestOpenGivesTheHostedKindsTheirBaseURL(t *testing.T) {
	if got := assistant.DefaultBaseURL(assistant.KindOpenAI); got != "https://api.openai.com/v1" {
		t.Errorf("openai %q", got)
	}
	if got := assistant.DefaultBaseURL(assistant.KindAnthropic); got != "https://api.anthropic.com" {
		t.Errorf("anthropic %q", got)
	}
	if got := assistant.DefaultBaseURL(assistant.KindOpenAICompatible); got != "" {
		t.Errorf("compatible has a default %q; it must be typed", got)
	}
	for _, k := range []assistant.Kind{assistant.KindFake, assistant.KindOpenAI, assistant.KindAnthropic} {
		if _, err := Open(k, Config{Model: "m"}); err != nil {
			t.Errorf("%s with no base URL: %v", k, err)
		}
	}
	if _, err := Open(assistant.KindOpenAICompatible, Config{Model: "m"}); err == nil {
		t.Error("a compatible provider with no base URL opened")
	}
}

// Review: Go's client drops Authorization on a cross-host redirect but not a
// custom header, so a base URL that redirected elsewhere would hand the
// Anthropic key to that host. A model API never needs a redirect, so none is
// followed, on either adapter.
func TestAnOpenedProviderFollowsNoRedirect(t *testing.T) {
	var leaked http.Header
	sink := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { leaked = r.Header.Clone() }))
	defer sink.Close()
	hop := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		http.Redirect(w, r, sink.URL+r.URL.Path, http.StatusTemporaryRedirect)
	}))
	defer hop.Close()
	for _, k := range []assistant.Kind{assistant.KindAnthropic, assistant.KindOpenAICompatible} {
		p, err := Open(k, Config{BaseURL: hop.URL, APIKey: "sk-secret", Model: "m"})
		if err != nil {
			t.Fatal(err)
		}
		_, err = p.Check(context.Background())
		if err == nil || !strings.Contains(err.Error(), "redirect") {
			t.Errorf("%s: err %v, want a refused redirect", k, err)
		}
		if leaked != nil {
			t.Errorf("%s: the redirect target received headers %v", k, leaked)
		}
	}
}

package assistant

import "testing"

// A subscription kind is somebody's own, and cannot be given tools; every kind
// that speaks to an API with a key is shared and can. The controller's rules rest
// on these two answers, so they are held here.
func TestSubscriptionKindsAreOwnedAndHaveNoTools(t *testing.T) {
	for _, k := range Kinds {
		sub := k == KindClaudeCode || k == KindCodex || k == KindCopilot
		if Subscription(k) != sub || SupportsTools(k) == sub {
			t.Errorf("%s: subscription = %v, tools = %v", k, Subscription(k), SupportsTools(k))
		}
	}
	if Subscription(KindFake) || !SupportsTools(KindFake) {
		t.Error("the fake model is not somebody's subscription")
	}
	for _, k := range []Kind{KindClaudeCode, KindCodex, KindCopilot} {
		if !Subscription(k) || DefaultBaseURL(k) != "" {
			t.Errorf("%s: a subscription has no address", k)
		}
	}
}

// Package assistant defines what a model provider is to the assistant: one
// streaming chat call with tool calls, usage and cancellation, and one check.
// Every adapter satisfies Provider and passes RunContractTests, so the panel,
// the tools and the limits in later slices never branch on which model
// answers. Nothing outside this package imports an adapter (purity_test.go).
package assistant

import (
	"context"
	"encoding/json"
	"time"
)

// Role is who a message is from. The names are the ones both wire protocols
// use, so an adapter maps nothing.
type Role string

const (
	RoleSystem    Role = "system"
	RoleUser      Role = "user"
	RoleAssistant Role = "assistant"
	RoleTool      Role = "tool"
)

// Message is one turn. A tool's answer is a message of RoleTool carrying the
// ToolCallID it answers; an assistant turn that called tools carries them.
type Message struct {
	Role       Role
	Content    string
	ToolCalls  []ToolCall
	ToolCallID string
}

// Tool is a function the model may call. Parameters is a JSON Schema object.
type Tool struct {
	Name        string
	Description string
	Parameters  json.RawMessage
	// Live is true for a tool whose answer changes while a conversation goes
	// on, so the same call made twice is two questions. It is for the caller
	// running the calls; no adapter sends it to a model.
	Live bool
}

// ToolCall is the model asking for a tool, with its arguments as the JSON
// the model wrote. The caller parses them; a model may escape strings in
// ways a substring match would miss.
type ToolCall struct {
	ID        string
	Name      string
	Arguments json.RawMessage
}

// Request is one chat call. System is the operator's framing, sent the way
// each protocol wants it. MaxTokens zero means the adapter's default.
type Request struct {
	Model     string
	System    string
	Messages  []Message
	Tools     []Tool
	MaxTokens int
}

// Usage is what the provider said it counted. Reported is false when the
// provider sends no usage at all, which is distinct from zero tokens.
type Usage struct {
	InputTokens  int
	OutputTokens int
	Reported     bool
}

// Event is one thing a stream yields: a text delta, a complete tool call,
// the usage, the end, or an error. An error ends the stream; Done does too.
// Cut, on the end, says the provider stopped the answer at its output ceiling
// rather than because the model had finished: a thinking model can spend the
// whole ceiling on reasoning the adapter never shows and send no words at all,
// and an end that does not say so makes that silence look like an answer.
type Event struct {
	Delta    string
	ToolCall *ToolCall
	Usage    *Usage
	Done     bool
	Cut      bool
	Err      error
}

// Stream is a chat in progress. Next blocks for the next event and reports
// false once the stream has ended; the caller closes it whichever way the
// stream ended, so an adapter can release its connection.
type Stream interface {
	Next(ctx context.Context) (Event, bool)
	Close() error
}

// CheckResult is what a check learned: which model answered, how long the
// round trip took, and whether usage came back with it.
type CheckResult struct {
	Model         string
	Latency       time.Duration
	UsageReported bool
}

// Provider is a model the assistant can talk to.
type Provider interface {
	Chat(ctx context.Context, req Request) (Stream, error)
	Check(ctx context.Context) (CheckResult, error)
}

// ModelLister is optional: a provider that can say which models it serves, so
// the settings page can offer them in a list and not ask a person to remember
// how the provider spells one. A provider that cannot is typed into.
type ModelLister interface {
	// Models returns the model names, sorted and without repeats. The list is
	// the provider's own and is a choice for a person to make, not a fact the
	// assistant relies on.
	Models(ctx context.Context) ([]string, error)
}

package provider

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/assistant"
)

// anthropicVersion is the API version header every request carries.
const anthropicVersion = "2023-06-01"

// anthropicDefaultMaxTokens bounds an answer when the request did not: the
// Messages API requires the field.
const anthropicDefaultMaxTokens = 4096

// Anthropic speaks the Messages API over plain HTTP, as the Docker and
// Proxmox clients do their APIs: a few hundred lines rather than a module.
type Anthropic struct {
	cfg  Config
	base string
}

// NewAnthropic returns an adapter for the API at cfg.BaseURL.
//
// A gateway in front of the API usually publishes its address ending in /v1,
// and the Messages path begins with it, so a trailing /v1 is taken off once
// rather than doubled.
func NewAnthropic(cfg Config) *Anthropic {
	base := strings.TrimRight(strings.TrimSpace(cfg.BaseURL), "/")
	base = strings.TrimSuffix(base, "/v1")
	return &Anthropic{cfg: cfg, base: base}
}

func (p *Anthropic) body(req assistant.Request, maxTokens int) ([]byte, error) {
	if maxTokens <= 0 {
		maxTokens = anthropicDefaultMaxTokens
	}
	msgs := make([]map[string]any, 0, len(req.Messages))
	for _, m := range req.Messages {
		switch m.Role {
		case assistant.RoleSystem:
			// The API takes the system prompt as its own field; a system
			// message in the turns is folded into it.
			continue
		case assistant.RoleTool:
			msgs = append(msgs, map[string]any{"role": "user", "content": []any{
				map[string]any{"type": "tool_result", "tool_use_id": m.ToolCallID, "content": m.Content},
			}})
		case assistant.RoleAssistant:
			if len(m.ToolCalls) == 0 {
				msgs = append(msgs, map[string]any{"role": "assistant", "content": m.Content})
				continue
			}
			var blocks []any
			if m.Content != "" {
				blocks = append(blocks, map[string]any{"type": "text", "text": m.Content})
			}
			for _, c := range m.ToolCalls {
				input := c.Arguments
				if len(input) == 0 {
					input = json.RawMessage("{}")
				}
				blocks = append(blocks, map[string]any{"type": "tool_use", "id": c.ID, "name": c.Name, "input": input})
			}
			msgs = append(msgs, map[string]any{"role": "assistant", "content": blocks})
		default:
			msgs = append(msgs, map[string]any{"role": "user", "content": m.Content})
		}
	}
	out := map[string]any{"model": p.model(req.Model), "max_tokens": maxTokens, "messages": msgs, "stream": true}
	system := req.System
	for _, m := range req.Messages {
		if m.Role == assistant.RoleSystem {
			system = strings.TrimSpace(system + "\n\n" + m.Content)
		}
	}
	if system != "" {
		out["system"] = system
	}
	if len(req.Tools) > 0 {
		tools := make([]map[string]any, 0, len(req.Tools))
		for _, t := range req.Tools {
			schema := t.Parameters
			if len(schema) == 0 {
				schema = json.RawMessage(`{"type":"object"}`)
			}
			tools = append(tools, map[string]any{"name": t.Name, "description": t.Description, "input_schema": schema})
		}
		out["tools"] = tools
	}
	return json.Marshal(out)
}

func (p *Anthropic) model(override string) string {
	if override != "" {
		return override
	}
	return p.cfg.Model
}

func (p *Anthropic) chat(ctx context.Context, req assistant.Request, maxTokens int) (assistant.Stream, error) {
	body, err := p.body(req, maxTokens)
	if err != nil {
		return nil, err
	}
	hr, err := http.NewRequestWithContext(ctx, http.MethodPost, p.base+"/v1/messages", bytes.NewReader(body))
	if err != nil {
		return nil, err
	}
	hr.Header.Set("Content-Type", "application/json")
	hr.Header.Set("Accept", "text/event-stream")
	hr.Header.Set("x-api-key", p.cfg.APIKey)
	hr.Header.Set("anthropic-version", anthropicVersion)
	resp, err := p.cfg.client().Do(hr)
	if err != nil {
		return nil, fmt.Errorf("reaching the provider: %w", err)
	}
	if err := StatusError(resp, p.cfg.APIKey != ""); err != nil {
		resp.Body.Close()
		return nil, err
	}
	return NewStream(resp, newAnthropicDecoder()), nil
}

// Chat implements assistant.Provider.
func (p *Anthropic) Chat(ctx context.Context, req assistant.Request) (assistant.Stream, error) {
	return p.chat(ctx, req, req.MaxTokens)
}

// newAnthropicDecoder decodes the Messages stream: text deltas as they come,
// a tool_use block gathered from its input_json_delta fragments and emitted
// at its content_block_stop, usage from message_start and message_delta
// together, and message_stop as Done.
func newAnthropicDecoder() Decoder {
	type block struct {
		id, name string
		args     strings.Builder
		tool     bool
	}
	blocks := map[int]*block{}
	usage := assistant.Usage{}
	cut := false
	return func(e ServerEvent) ([]assistant.Event, error) {
		var frame struct {
			Type         string `json:"type"`
			Index        int    `json:"index"`
			ContentBlock *struct {
				Type string `json:"type"`
				ID   string `json:"id"`
				Name string `json:"name"`
			} `json:"content_block"`
			Delta *struct {
				Type        string `json:"type"`
				Text        string `json:"text"`
				PartialJSON string `json:"partial_json"`
				StopReason  string `json:"stop_reason"`
			} `json:"delta"`
			Message *struct {
				Usage *struct {
					Input int `json:"input_tokens"`
				} `json:"usage"`
			} `json:"message"`
			Usage *struct {
				Output int `json:"output_tokens"`
			} `json:"usage"`
			Error *struct {
				Message string `json:"message"`
			} `json:"error"`
		}
		if e.Data == "" {
			return nil, nil
		}
		if err := json.Unmarshal([]byte(e.Data), &frame); err != nil {
			return nil, fmt.Errorf("the provider sent a frame that is not JSON: %w", err)
		}
		switch frame.Type {
		case "error":
			msg := "unknown error"
			if frame.Error != nil {
				msg = frame.Error.Message
			}
			return nil, fmt.Errorf("the provider answered with an error: %s", msg)
		case "message_start":
			if frame.Message != nil && frame.Message.Usage != nil {
				usage.InputTokens, usage.Reported = frame.Message.Usage.Input, true
			}
		case "content_block_start":
			if frame.ContentBlock != nil && frame.ContentBlock.Type == "tool_use" {
				blocks[frame.Index] = &block{id: frame.ContentBlock.ID, name: frame.ContentBlock.Name, tool: true}
			}
		case "content_block_delta":
			if frame.Delta == nil {
				return nil, nil
			}
			switch frame.Delta.Type {
			case "text_delta":
				return []assistant.Event{{Delta: frame.Delta.Text}}, nil
			case "input_json_delta":
				if b := blocks[frame.Index]; b != nil {
					b.args.WriteString(frame.Delta.PartialJSON)
				}
			}
		case "content_block_stop":
			if b := blocks[frame.Index]; b != nil && b.tool {
				delete(blocks, frame.Index)
				args := b.args.String()
				if args == "" {
					args = "{}"
				}
				return []assistant.Event{{ToolCall: &assistant.ToolCall{ID: b.id, Name: b.name, Arguments: json.RawMessage(args)}}}, nil
			}
		case "message_delta":
			// max_tokens is the provider's ceiling ending the answer, not the
			// model finishing; the end that follows says so.
			if frame.Delta != nil && frame.Delta.StopReason == "max_tokens" {
				cut = true
			}
			if frame.Usage != nil {
				usage.OutputTokens, usage.Reported = frame.Usage.Output, true
			}
			if usage.Reported {
				u := usage
				return []assistant.Event{{Usage: &u}}, nil
			}
		case "message_stop":
			return []assistant.Event{{Done: true, Cut: cut}}, nil
		}
		return nil, nil
	}
}

// Models implements assistant.ModelLister. The list is the first hundred the API
// returns, which is more than a person picks from.
func (p *Anthropic) Models(ctx context.Context) ([]string, error) {
	hr, err := http.NewRequestWithContext(ctx, http.MethodGet, p.base+"/v1/models?limit=100", nil)
	if err != nil {
		return nil, err
	}
	hr.Header.Set("Accept", "application/json")
	hr.Header.Set("x-api-key", p.cfg.APIKey)
	hr.Header.Set("anthropic-version", anthropicVersion)
	resp, err := p.cfg.client().Do(hr)
	if err != nil {
		return nil, fmt.Errorf("reaching the provider: %w", err)
	}
	if err := StatusError(resp, p.cfg.APIKey != ""); err != nil {
		resp.Body.Close()
		return nil, err
	}
	return modelsFrom(resp)
}

// Check implements assistant.Provider with one request of one token: the
// Messages API has no model list worth a second round trip.
func (p *Anthropic) Check(ctx context.Context) (assistant.CheckResult, error) {
	start := time.Now()
	reported, err := completeOneToken(ctx, func(ctx context.Context) (assistant.Stream, error) {
		return p.chat(ctx, assistant.Request{Messages: []assistant.Message{{Role: assistant.RoleUser, Content: "Say OK."}}}, 1)
	})
	if err != nil {
		return assistant.CheckResult{}, err
	}
	return assistant.CheckResult{Model: p.cfg.Model, Latency: time.Since(start), UsageReported: reported}, nil
}

package provider

import (
	"context"
	"encoding/json"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/assistant"
	"github.com/eyupio/zoomies/internal/assistant/assistanttest"
)

func TestAnthropicSendsTheMessagesRequestWithItsHeaders(t *testing.T) {
	srv := assistanttest.NewAnthropic(t)
	p := NewAnthropic(Config{BaseURL: srv.URL, APIKey: "sk-ant", Model: "m"})
	tool := assistant.Tool{Name: "echo", Description: "Echo", Parameters: json.RawMessage(`{"type":"object"}`)}
	req := assistant.Request{
		System: "Be brief.",
		Messages: []assistant.Message{
			{Role: assistant.RoleUser, Content: "hi"},
			{Role: assistant.RoleAssistant, ToolCalls: []assistant.ToolCall{{ID: "toolu_0", Name: "echo", Arguments: json.RawMessage(`{"text":"x"}`)}}},
			{Role: assistant.RoleTool, ToolCallID: "toolu_0", Content: "x"},
			{Role: assistant.RoleUser, Content: "Say hello"},
		},
		Tools: []assistant.Tool{tool},
	}
	drain(t, p, req)
	rec := srv.Requests()[0]
	if rec.Path != "/v1/messages" || rec.Header.Get("x-api-key") != "sk-ant" || rec.Header.Get("anthropic-version") != "2023-06-01" {
		t.Errorf("request %s %v", rec.Path, rec.Header)
	}
	if rec.Body["system"] != "Be brief." || rec.Body["stream"] != true || rec.Body["model"] != "m" {
		t.Errorf("body %v", rec.Body)
	}
	tools, _ := rec.Body["tools"].([]any)
	if len(tools) != 1 || tools[0].(map[string]any)["input_schema"] == nil {
		t.Errorf("tools %v", rec.Body["tools"])
	}
	msgs, _ := rec.Body["messages"].([]any)
	if len(msgs) != 4 {
		t.Fatalf("messages %v", msgs)
	}
	second, _ := msgs[1].(map[string]any)
	blocks, _ := second["content"].([]any)
	if second["role"] != "assistant" || len(blocks) != 1 || blocks[0].(map[string]any)["type"] != "tool_use" {
		t.Errorf("assistant tool turn %v", second)
	}
	third, _ := msgs[2].(map[string]any)
	blocks, _ = third["content"].([]any)
	if third["role"] != "user" || len(blocks) != 1 || blocks[0].(map[string]any)["type"] != "tool_result" || blocks[0].(map[string]any)["tool_use_id"] != "toolu_0" {
		t.Errorf("tool result turn %v", third)
	}
}

func TestAnthropicStreamsContentBlockEventsIntoDeltasToolCallsAndUsage(t *testing.T) {
	srv := assistanttest.NewAnthropic(t)
	p := NewAnthropic(Config{BaseURL: srv.URL, APIKey: "k", Model: "m"})
	var text strings.Builder
	var usage *assistant.Usage
	for _, e := range drain(t, p, hello()) {
		text.WriteString(e.Delta)
		if e.Usage != nil {
			usage = e.Usage
		}
	}
	if text.String() != "Hello from the fake" {
		t.Errorf("text %q", text.String())
	}
	if usage == nil || !usage.Reported || usage.InputTokens != 7 || usage.OutputTokens != 4 {
		t.Errorf("usage %+v", usage)
	}
	tool := assistant.Tool{Name: "echo", Parameters: json.RawMessage(`{"type":"object"}`)}
	req := assistant.Request{Messages: []assistant.Message{{Role: assistant.RoleUser, Content: assistant.ContractPrompt}}, Tools: []assistant.Tool{tool}}
	var call *assistant.ToolCall
	for _, e := range drain(t, p, req) {
		if e.ToolCall != nil {
			call = e.ToolCall
		}
	}
	if call == nil || call.Name != "echo" || call.ID != "toolu_1" || string(call.Arguments) != `{"text":"ping"}` {
		t.Errorf("tool call %+v", call)
	}
}

func TestAnthropicCheckIsOneRequestOfOneToken(t *testing.T) {
	srv := assistanttest.NewAnthropic(t)
	res, err := NewAnthropic(Config{BaseURL: srv.URL, APIKey: "k", Model: "m"}).Check(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	reqs := srv.Requests()
	if len(reqs) != 1 || reqs[0].Body["max_tokens"] != float64(1) {
		t.Errorf("requests %+v", reqs)
	}
	if res.Model != "m" || !res.UsageReported {
		t.Errorf("result %+v", res)
	}
}

func TestAnthropicPassesTheContract(t *testing.T) {
	assistant.RunContractTests(t, "anthropic", func(t *testing.T) assistant.Provider {
		return NewAnthropic(Config{BaseURL: assistanttest.NewAnthropic(t).URL, APIKey: "k", Model: "m"})
	})
}

// Review Focus 1 on the second adapter: a gateway in front of the API
// usually publishes its address ending in /v1, and the Messages path must
// not double it.
func TestAnthropicAppendsTheMessagesPathOnceWhateverThePathGiven(t *testing.T) {
	srv := assistanttest.NewAnthropic(t)
	for given, wantPath := range map[string]string{
		"":       "/v1/messages",
		"/":      "/v1/messages",
		"/v1":    "/v1/messages",
		"/v1/":   "/v1/messages",
		"/gw":    "/gw/v1/messages",
		"/gw/v1": "/gw/v1/messages",
	} {
		before := len(srv.Requests())
		p := NewAnthropic(Config{BaseURL: srv.URL + given, APIKey: "k", Model: "m"})
		if s, err := p.Chat(context.Background(), hello()); err == nil {
			s.Close()
		}
		reqs := srv.Requests()
		if len(reqs) != before+1 || reqs[before].Path != wantPath {
			t.Errorf("base %q: requested %q, want %q", given, reqs[len(reqs)-1].Path, wantPath)
		}
	}
}

func TestAnthropicSaysAKeyIsNeededWhenNoneIsConfigured(t *testing.T) {
	srv := assistanttest.NewAnthropic(t)
	srv.Status, srv.Body = 401, `{"type":"error","error":{"message":"missing key"}}`
	_, err := NewAnthropic(Config{BaseURL: srv.URL, Model: "m"}).Check(context.Background())
	if err == nil || !strings.Contains(err.Error(), "needs an API key") {
		t.Errorf("err %v", err)
	}
}

// Anthropic says an answer stopped at its ceiling with stop_reason max_tokens;
// the adapter says it the one way the loop reads, so the page is never shown
// a half answer as a whole one.
func TestAnthropicSaysWhenTheProviderCutTheAnswer(t *testing.T) {
	srv := assistanttest.NewAnthropic(t)
	srv.Cut = true
	p := NewAnthropic(Config{BaseURL: srv.URL, Model: "m", APIKey: "k"})
	var done *assistant.Event
	for _, e := range drain(t, p, hello()) {
		if e.Done {
			d := e
			done = &d
		}
	}
	if done == nil || !done.Cut {
		t.Errorf("the end of a cut answer does not say it was cut: %+v", done)
	}
}

package provider

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/assistant"
)

// ClaudeCode answers by running Claude Code, the person's own signed-in copy, on
// the machine the controller runs on.
//
// It exists so that somebody with a Claude subscription can use it through Eli
// without Zoomies ever holding it. The sign-in lives in Claude Code's own store
// and is made through Anthropic's own flow; this package never reads it, never
// asks for a key and never sends one. It runs the binary as published, with
// every tool turned off, in an empty directory and with an environment of its
// own, so the model cannot read a file, run a command or reach a server on this
// machine, whatever it is asked.
//
// Who may use it is not decided here: Anthropic's terms are that each person
// uses their own subscription, and the controller refuses anybody else.
type ClaudeCode struct {
	cfg Config
}

// NewClaudeCode returns the adapter. cfg.Command, when set, is the binary to
// run, and otherwise it is looked for.
func NewClaudeCode(cfg Config) *ClaudeCode { return &ClaudeCode{cfg: cfg} }

// claudeAliases are the model names Claude Code documents. They follow Claude Code
// as it is updated, which a full model name does not.
var claudeAliases = []string{"sonnet", "opus", "haiku", "fable"}

// ErrClaudeNotFound is Claude Code not being on this machine.
var ErrClaudeNotFound = errors.New("the machine the controller runs on has no Claude Code: " +
	"install it there, sign in as the user the controller runs as with `claude auth login`, and test again")

var errClaudeNotSignedIn = errors.New("nobody is signed in to Claude Code on this machine: " +
	"sign in as the user the controller runs as with `claude auth login`, and test again")

// claudeBinary finds the executable: the one named, or one on the PATH, or one
// where its installers put it.
func claudeBinary(override string) (string, error) {
	return cliBinary(override, "claude", claudeCandidates(), ErrClaudeNotFound)
}

// claudeCandidates are the places Claude Code's installers put it, for a service
// whose PATH does not include them. A variable so a test is not at the mercy of a
// Claude Code that happens to be installed where it runs.
var claudeCandidates = func() []string {
	var out []string
	if home, err := os.UserHomeDir(); err == nil {
		out = append(out, filepath.Join(home, ".local", "bin", "claude"), filepath.Join(home, ".claude", "local", "claude"))
	}
	return append(out, "/usr/local/bin/claude", "/opt/homebrew/bin/claude")
}

// claudeEnv is the only part of this process's environment Claude Code is given:
// where it lives and where its sign-in is kept, and nothing of the controller's. In
// particular no ZOOMIES_ variable and no Anthropic key: a key in the environment
// would make it bill an API account instead of the person's subscription, which is
// not what was asked for.
func claudeEnv(environ []string) []string { return cliEnv(environ, "CLAUDE_CONFIG_DIR") }

// claudeArgs is how Claude Code is run. Every flag is there for a reason: the
// print mode and stream so there is something to read, no built-in tool and no
// MCP server so there is nothing to do, safe mode so no file on this machine
// (a CLAUDE.md, a hook, a plugin) changes that, no saved session so the question
// is not kept, and no prompts so nothing waits for a person who is not there.
func claudeArgs(system, model string) []string {
	args := []string{
		"-p", "--output-format", "stream-json", "--verbose", "--include-partial-messages",
		"--tools", "",
		"--strict-mcp-config",
		"--safe-mode",
		"--no-session-persistence",
		"--permission-prompts", "none",
	}
	if system != "" {
		args = append(args, "--system-prompt", system)
	}
	if model != "" {
		args = append(args, "--model", model)
	}
	return append(args, "Reply to the last message of the conversation you are given on standard input.")
}

// claudePrompt is the conversation as text for standard input: Claude Code takes
// one prompt, and the controller keeps no session for it.
func claudePrompt(messages []assistant.Message) string {
	var b strings.Builder
	b.WriteString("This is the conversation so far. Reply as the assistant to the last message from the user.\n")
	for _, m := range messages {
		switch m.Role {
		case assistant.RoleUser:
			b.WriteString("\nUser: ")
		case assistant.RoleAssistant:
			b.WriteString("\nAssistant: ")
		default:
			continue
		}
		b.WriteString(m.Content)
		b.WriteString("\n")
	}
	return b.String()
}

// Chat implements assistant.Provider.
func (p *ClaudeCode) Chat(ctx context.Context, req assistant.Request) (assistant.Stream, error) {
	bin, err := claudeBinary(p.cfg.Command)
	if err != nil {
		return nil, err
	}
	model := req.Model
	if model == "" {
		model = p.cfg.Model
	}
	parse := &claudeParse{}
	return startCLI(ctx, cliCommand{
		tool:   "Claude Code",
		bin:    bin,
		args:   claudeArgs(req.System, model),
		env:    claudeEnv(os.Environ()),
		stdin:  claudePrompt(req.Messages),
		reader: readLines(parse),
		exit:   claudeExit,
	})
}

// claudeParse reads the lines of Claude Code's stream-json output, one at a time,
// and says what each is. It is a value so a test can feed it lines.
type claudeParse struct {
	sawText bool
	sawPart bool
}

type claudeLine struct {
	Type    string `json:"type"`
	Subtype string `json:"subtype"`
	IsError bool   `json:"is_error"`
	Result  string `json:"result"`
	Event   struct {
		Type  string `json:"type"`
		Delta struct {
			Type string `json:"type"`
			Text string `json:"text"`
		} `json:"delta"`
	} `json:"event"`
	Message struct {
		Content []struct {
			Type string `json:"type"`
			Text string `json:"text"`
		} `json:"content"`
	} `json:"message"`
	Usage *struct {
		InputTokens  int `json:"input_tokens"`
		OutputTokens int `json:"output_tokens"`
	} `json:"usage"`
}

// answered is whether anything was said as an answer.
func (c *claudeParse) answered() bool { return c.sawText }

// line interprets one line. A line it does not understand is nothing: a newer
// Claude Code may print more than this one knows, and that is not an error.
func (c *claudeParse) line(raw []byte) []assistant.Event {
	raw = bytes.TrimSpace(raw)
	if len(raw) == 0 || raw[0] != '{' {
		return nil
	}
	var l claudeLine
	if json.Unmarshal(raw, &l) != nil {
		return nil
	}
	switch l.Type {
	case "stream_event":
		if l.Event.Type == "content_block_delta" && l.Event.Delta.Type == "text_delta" && l.Event.Delta.Text != "" {
			c.sawText, c.sawPart = true, true
			return []assistant.Event{{Delta: l.Event.Delta.Text}}
		}
	case "assistant":
		// With partial messages on, this repeats what the deltas said.
		if c.sawPart {
			return nil
		}
		var out []assistant.Event
		for _, b := range l.Message.Content {
			if b.Type == "text" && b.Text != "" {
				c.sawText = true
				out = append(out, assistant.Event{Delta: b.Text})
			}
		}
		return out
	case "result":
		if l.IsError || (l.Subtype != "" && l.Subtype != "success") {
			return []assistant.Event{{Err: claudeFailure(l.Result)}}
		}
		var out []assistant.Event
		if !c.sawText && l.Result != "" {
			c.sawText = true
			out = append(out, assistant.Event{Delta: l.Result})
		}
		if l.Usage != nil {
			out = append(out, assistant.Event{Usage: &assistant.Usage{InputTokens: l.Usage.InputTokens, OutputTokens: l.Usage.OutputTokens, Reported: true}})
		}
		return append(out, assistant.Event{Done: true})
	}
	return nil
}

// claudeFailure is what Claude Code said when it could not answer, for the
// person. The two it says most often are given their remedy; anything else is
// shown as it was said, shortened, because it is written for a person too.
func claudeFailure(said string) error {
	said = strings.TrimSpace(said)
	lower := strings.ToLower(said)
	switch {
	case strings.Contains(lower, "not logged in"), strings.Contains(lower, "/login"), strings.Contains(lower, "invalid api key"):
		return errClaudeNotSignedIn
	case said == "":
		return errors.New("the answer failed in Claude Code")
	}
	return fmt.Errorf("the answer failed in Claude Code: %s", clip(said, 300))
}

// claudeExit is a process that ended badly with nothing said in the stream. Its
// stderr is what it complained of, and is shown to a person who can act on it,
// which is the controller's operator.
func claudeExit(err error, stderr string) error {
	stderr = strings.TrimSpace(stderr)
	lower := strings.ToLower(stderr)
	switch {
	case strings.Contains(lower, "unknown option"), strings.Contains(lower, "unknown argument"), strings.Contains(lower, "unrecognized"):
		return errors.New("this version of Claude Code does not accept the options Zoomies needs to run it safely; update it with `claude update` and test again")
	case strings.Contains(lower, "not logged in"), strings.Contains(lower, "/login"):
		return errClaudeNotSignedIn
	case stderr != "":
		first, _, _ := strings.Cut(stderr, "\n")
		return fmt.Errorf("the run stopped in Claude Code: %s", clip(first, 300))
	}
	return fmt.Errorf("the run stopped in Claude Code without an answer (%v)", err)
}

// Check implements assistant.Provider. It spends no usage: it asks Claude Code
// which version it is and how it is signed in, and says so if it is not signed in
// with a subscription.
func (p *ClaudeCode) Check(ctx context.Context) (assistant.CheckResult, error) {
	start := time.Now()
	bin, err := claudeBinary(p.cfg.Command)
	if err != nil {
		return assistant.CheckResult{}, err
	}
	run := func(args ...string) ([]byte, error) {
		ctx, cancel := context.WithTimeout(ctx, 20*time.Second)
		defer cancel()
		cmd := exec.CommandContext(ctx, bin, args...)
		cmd.Env = claudeEnv(os.Environ())
		cmd.Dir = os.TempDir()
		return cmd.Output()
	}
	ver, err := run("--version")
	if err != nil {
		return assistant.CheckResult{}, fmt.Errorf("no version from Claude Code: %w", err)
	}
	version := strings.TrimSpace(string(ver))
	status, err := run("auth", "status")
	var auth struct {
		LoggedIn   bool   `json:"loggedIn"`
		AuthMethod string `json:"authMethod"`
	}
	_ = json.Unmarshal(status, &auth)
	if err != nil || (auth.AuthMethod == "" && !auth.LoggedIn) || auth.AuthMethod == "none" {
		return assistant.CheckResult{}, errClaudeNotSignedIn
	}
	switch auth.AuthMethod {
	case "claude.ai", "oauth_token", "":
	default:
		return assistant.CheckResult{}, fmt.Errorf("this machine\u2019s Claude Code is signed in with %s, not with a Claude subscription; "+
			"sign in with your Claude account (`claude auth login`), or use the Anthropic provider for an API key", strings.ReplaceAll(auth.AuthMethod, "_", " "))
	}
	return assistant.CheckResult{Model: "Claude Code " + version, Latency: time.Since(start), UsageReported: false}, nil
}

// Models implements assistant.ModelLister with Claude Code's own aliases.
func (p *ClaudeCode) Models(context.Context) ([]string, error) {
	return append([]string(nil), claudeAliases...), nil
}

