// The check spends nothing: it reads the version and how Claude Code is signed
// in, and it turns away anything that is not a subscription.
func TestClaudeCodeCheckReadsHowItIsSignedIn(t *testing.T) {
	script := func(status string, code int) string {
		return `
case "$1" in
  --version) echo "2.1.300 (Claude Code)" ;;
  auth) echo '` + status + `'; exit ` + string(rune('0'+code)) + ` ;;
esac
`
	}
	for _, tc := range []struct {
		name, status string
		code         int
		wantErr      string
	}{
		{"a subscription", `{"loggedIn":true,"authMethod":"claude.ai"}`, 0, ""},
		{"a long-lived token from a subscription", `{"loggedIn":true,"authMethod":"oauth_token"}`, 0, ""},
		{"an API key", `{"loggedIn":true,"authMethod":"api_key"}`, 0, "api key"},
		{"a cloud provider", `{"loggedIn":true,"authMethod":"third_party"}`, 0, "third party"},
		{"nobody", `{"loggedIn":false,"authMethod":"none"}`, 1, "claude auth login"},
		// A version that says "none" and exits cleanly is still nobody.
		{"nobody, said politely", `{"loggedIn":false,"authMethod":"none"}`, 0, "nobody is signed in"},
		{"nothing readable and a failure", `oops`, 1, "claude auth login"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			bin, _ := fakeClaude(t, script(tc.status, tc.code))
			res, err := NewClaudeCode(Config{Command: bin}).Check(context.Background())
			if tc.wantErr == "" {
				if err != nil || res.Model != "Claude Code 2.1.300 (Claude Code)" || res.UsageReported {
					t.Errorf("res = %+v, err = %v", res, err)
				}
				return
			}
			if err == nil || !strings.Contains(strings.ToLower(err.Error()), tc.wantErr) {
				t.Errorf("err = %v, want one with %q", err, tc.wantErr)
			}
		})
	}
}

// Closing a stream that is still running ends the process, takes its directory
// away and gives its place to the next question, however long it had to go.
func TestClosingAClaudeCodeStreamEndsTheProcessAndFreesItsPlace(t *testing.T) {
	bin, rec := fakeClaude(t, "pwd > \"$REC/cwd\"\ncat > /dev/null\nsleep 60\n")
	s, err := NewClaudeCode(Config{Command: bin}).Chat(context.Background(), assistant.Request{
		Messages: []assistant.Message{{Role: assistant.RoleUser, Content: "hi"}},
	})
	if err != nil {
		t.Fatal(err)
	}
	if len(cliSlots) != 1 {
		t.Errorf("slots in use = %d, want 1", len(cliSlots))
	}
	started := time.Now()
	_ = s.Close()
	if time.Since(started) > 10*time.Second {
		t.Errorf("closing took %v", time.Since(started))
	}
	if len(cliSlots) != 0 {
		t.Errorf("slots in use after closing = %d", len(cliSlots))
	}
	cwd, _ := os.ReadFile(filepath.Join(rec, "cwd"))
	if dir := strings.TrimSpace(string(cwd)); dir != "" {
		if _, err := os.Stat(dir); err == nil {
			t.Errorf("%s was left behind", dir)
		}
	}
	// Closing again is nothing.
	_ = s.Close()
}

// A reader that gives up while Claude Code is still talking does not leave it
// stuck with nowhere to put what it says.
func TestAReaderThatStopsDoesNotHoldTheProcess(t *testing.T) {
	bin, _ := fakeClaude(t, `cat > /dev/null
i=0
while [ $i -lt 400 ]; do
  echo '{"type":"stream_event","event":{"type":"content_block_delta","delta":{"type":"text_delta","text":"word "}}}'
  i=$((i+1))
done
sleep 5
`)
	s, err := NewClaudeCode(Config{Command: bin}).Chat(context.Background(), assistant.Request{
		Messages: []assistant.Message{{Role: assistant.RoleUser, Content: "hi"}},
	})
	if err != nil {
		t.Fatal(err)
	}
	time.Sleep(300 * time.Millisecond)
	closed := make(chan struct{})
	go func() { _ = s.Close(); close(closed) }()
	select {
	case <-closed:
	case <-time.After(10 * time.Second):
		t.Fatal("closing a stream nobody was reading hung")
	}
}

// No more than two run at once; a third waits for a place, and gives up when the
// person who asked does.
func TestOnlyTwoClaudeCodesRunAtOnce(t *testing.T) {
	bin, _ := fakeClaude(t, "cat > /dev/null\nsleep 30\n")
	open := func(ctx context.Context) (assistant.Stream, error) {
		return NewClaudeCode(Config{Command: bin}).Chat(ctx, assistant.Request{
			Messages: []assistant.Message{{Role: assistant.RoleUser, Content: "hi"}},
		})
	}
	a, err := open(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	b, err := open(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 300*time.Millisecond)
	defer cancel()
	if _, err := open(ctx); !errors.Is(err, context.DeadlineExceeded) {
		t.Errorf("a third run was not made to wait: %v", err)
	}
	_ = a.Close()
	c, err := open(context.Background())
	if err != nil {
		t.Fatalf("a place that was given back was not given out: %v", err)
	}
	_ = b.Close()
	_ = c.Close()
}

func TestClaudeCodeOffersItsOwnModelAliases(t *testing.T) {
	got, err := NewClaudeCode(Config{}).Models(context.Background())
	if err != nil || !slices.Equal(got, []string{"sonnet", "opus", "haiku", "fable"}) {
		t.Errorf("models = %v, %v", got, err)
	}
	// What it hands out is its own copy.
	got[0] = "changed"
	if again, _ := NewClaudeCode(Config{}).Models(context.Background()); again[0] != "sonnet" {
		t.Error("the list can be changed from outside")
	}
}

package provider

import (
	"bufio"
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"strings"
	"sync"
	"time"
	"unicode/utf8"

	"github.com/eyupio/zoomies/internal/assistant"
)

// This file is what the providers that run a vendor's own command line tool on
// the controller's machine have in common: Claude Code, Codex and Copilot. Each
// of them is somebody's own subscription, signed in through the vendor's flow, so
// none of them is given a key or an address, and each is run the same careful way:
// in an empty directory, with an environment of its own and in a process group
// that is ended with it. What differs is the arguments, what the tool prints and
// how it says it is signed in, which is each adapter's own file.

// cliSlots bounds how many copies of any tool run at once. Each is a process of its
// own that can hold a few hundred megabytes, and the questions of one controller
// are few; the rest wait their turn.
var cliSlots = make(chan struct{}, 2)

// cliEnvBase is the part of this process's environment every tool is given: where
// it lives, where its home is, and how it reaches the network. Nothing of the
// controller's, and in particular no ZOOMIES_ variable and no token of any vendor.
var cliEnvBase = []string{
	"HOME", "PATH", "USER", "LOGNAME", "LANG", "LC_ALL", "TZ", "TMPDIR",
	"XDG_CONFIG_HOME", "XDG_DATA_HOME", "XDG_CACHE_HOME", "XDG_STATE_HOME",
	"SSL_CERT_FILE", "SSL_CERT_DIR", "HTTPS_PROXY", "https_proxy", "NO_PROXY", "no_proxy",
}

// cliEnv is environ narrowed to cliEnvBase and the names the tool itself adds, which
// are where its own sign-in is kept.
func cliEnv(environ []string, extra ...string) []string {
	keep := make(map[string]bool, len(cliEnvBase)+len(extra))
	for _, k := range cliEnvBase {
		keep[k] = true
	}
	for _, k := range extra {
		keep[k] = true
	}
	var out []string
	for _, kv := range environ {
		if k, _, ok := strings.Cut(kv, "="); ok && keep[k] {
			out = append(out, kv)
		}
	}
	return out
}

// cliBinary finds the executable: the one named, or one on the PATH, or one where
// its installers put it. notFound is what the person is told when there is none.
func cliBinary(override, name string, candidates []string, notFound error) (string, error) {
	if override != "" {
		return override, nil
	}
	if p, err := exec.LookPath(name); err == nil {
		return p, nil
	}
	for _, c := range candidates {
		if st, err := os.Stat(c); err == nil && !st.IsDir() && st.Mode()&0o111 != 0 {
			return c, nil
		}
	}
	return "", notFound
}

// cliReader turns what a tool prints into events and hands each to emit, which
// says false once nobody is reading any more. answered is whether the tool said
// anything as an answer; finished is whether a last event (the end, or a failure)
// has been handed over already, so that what is left is the process leaving.
type cliReader func(out io.Reader, emit func(assistant.Event) bool) (answered, finished bool)

// cliLines is a tool that prints one JSON object a line.
type cliLines interface {
	line(raw []byte) []assistant.Event
	answered() bool
}

// readLines is a cliReader for a tool that prints lines. A line it does not
// understand is the parser's to ignore: a newer tool may print more than this knows.
func readLines(p cliLines) cliReader {
	return func(out io.Reader, emit func(assistant.Event) bool) (bool, bool) {
		sc := bufio.NewScanner(out)
		sc.Buffer(make([]byte, 64<<10), 4<<20)
		for sc.Scan() {
			for _, ev := range p.line(sc.Bytes()) {
				if !emit(ev) || ev.Done || ev.Err != nil {
					return p.answered(), true
				}
			}
		}
		return p.answered(), false
	}
}

// readText is a cliReader for a tool that prints its answer as plain text, which
// is passed on as it comes.
func readText(out io.Reader, emit func(assistant.Event) bool) (bool, bool) {
	var answered bool
	buf := make([]byte, 4<<10)
	var carry []byte
	for {
		n, err := out.Read(buf)
		if n > 0 {
			chunk := append(carry, buf[:n]...)
			// Never cut a character in two: what is left of one waits for the rest.
			cut := completePrefix(chunk)
			carry = append([]byte(nil), chunk[cut:]...)
			if text := string(chunk[:cut]); text != "" {
				if strings.TrimSpace(text) != "" {
					answered = true
				}
				if !emit(assistant.Event{Delta: text}) {
					return answered, true
				}
			}
		}
		if err != nil {
			if len(carry) > 0 {
				answered = answered || strings.TrimSpace(string(carry)) != ""
				if !emit(assistant.Event{Delta: strings.ToValidUTF8(string(carry), "")}) {
					return answered, true
				}
			}
			return answered, false
		}
	}
}

// completePrefix is how many leading bytes of b are whole characters: a character
// cut by the end of a read has its start at the end of b and the rest still to come.
func completePrefix(b []byte) int {
	for i := 1; i <= 3 && i <= len(b); i++ {
		if utf8.RuneStart(b[len(b)-i]) {
			if utf8.FullRune(b[len(b)-i:]) {
				return len(b)
			}
			return len(b) - i
		}
	}
	return len(b)
}

// cliCommand is one question to a tool.
type cliCommand struct {
	// tool is its name as the person knows it, for the messages.
	tool string
	bin  string
	args []string
	env  []string
	// stdin is what is piped to it, and may be empty.
	stdin  string
	reader cliReader
	// exit is what a run that ended badly with nothing said as an answer means.
	exit func(err error, stderr string) error
}

// startCLI runs the tool and returns the answer as it arrives. It waits for one of
// the slots, and gives it back when the stream is closed.
func startCLI(ctx context.Context, c cliCommand) (assistant.Stream, error) {
	select {
	case cliSlots <- struct{}{}:
	case <-ctx.Done():
		return nil, ctx.Err()
	}
	dir, err := os.MkdirTemp("", "zoomies-eli-")
	if err != nil {
		<-cliSlots
		return nil, fmt.Errorf("making a directory for %s to run in: %w", c.tool, err)
	}
	cmd := exec.CommandContext(ctx, c.bin, c.args...)
	cmd.Dir = dir
	cmd.Env = c.env
	if c.stdin != "" {
		cmd.Stdin = strings.NewReader(c.stdin)
	}
	cmd.WaitDelay = 3 * time.Second
	ownGroup(cmd)
	stderr := &limitedBuffer{limit: 8 << 10}
	cmd.Stderr = stderr
	out, err := cmd.StdoutPipe()
	if err != nil {
		_ = os.RemoveAll(dir)
		<-cliSlots
		return nil, err
	}
	if err := cmd.Start(); err != nil {
		_ = os.RemoveAll(dir)
		<-cliSlots
		return nil, fmt.Errorf("starting %s: %w", c.tool, err)
	}
	s := &cliStream{cmd: cmd, dir: dir, events: make(chan assistant.Event, 16), done: make(chan struct{}), quit: make(chan struct{})}
	go s.read(c, out, stderr)
	return s, nil
}

// limitedBuffer keeps the first limit bytes written to it and drops the rest.
type limitedBuffer struct {
	mu    sync.Mutex
	buf   bytes.Buffer
	limit int
}

func (b *limitedBuffer) Write(p []byte) (int, error) {
	b.mu.Lock()
	defer b.mu.Unlock()
	if room := b.limit - b.buf.Len(); room > 0 {
		b.buf.Write(p[:min(len(p), room)])
	}
	return len(p), nil
}

func (b *limitedBuffer) String() string {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.buf.String()
}

// cliStream is a question in progress: the process, and what it has said.
type cliStream struct {
	cmd    *exec.Cmd
	dir    string
	events chan assistant.Event
	done   chan struct{}
	quit   chan struct{}
	once   sync.Once
}

// send hands an event to whoever is reading, unless they have closed the stream:
// a reader that stopped must not leave the process waiting for a place to put
// what it says.
func (s *cliStream) send(ev assistant.Event) bool {
	select {
	case s.events <- ev:
		return true
	case <-s.quit:
		return false
	}
}

// Next implements assistant.Stream.
func (s *cliStream) Next(ctx context.Context) (assistant.Event, bool) {
	select {
	case ev, ok := <-s.events:
		return ev, ok
	case <-ctx.Done():
		return assistant.Event{}, false
	}
}

// Close implements assistant.Stream: it ends the process if it is still running,
// waits for it, and gives the directory and the slot back.
func (s *cliStream) Close() error {
	s.once.Do(func() {
		close(s.quit)
		_ = killGroup(s.cmd)
		<-s.done
		_ = os.RemoveAll(s.dir)
		<-cliSlots
	})
	return nil
}

// read turns what the tool prints into events, and says how it ended.
func (s *cliStream) read(c cliCommand, out io.Reader, stderr *limitedBuffer) {
	defer close(s.done)
	defer close(s.events)
	answered, finished := c.reader(out, s.send)
	if finished {
		// The answer is over, or nobody is listening; what is left is the process
		// leaving, and it is not waited for.
		_ = killGroup(s.cmd)
		_ = s.cmd.Wait()
		return
	}
	err := s.cmd.Wait()
	switch {
	case answered:
		s.send(assistant.Event{Done: true})
	case err != nil:
		s.send(assistant.Event{Err: c.exit(err, stderr.String())})
	default:
		s.send(assistant.Event{Err: errors.New("the run ended in " + c.tool + " without an answer")})
	}
}

// clip shortens s to n bytes for a message, without cutting a character in two.
func clip(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return strings.ToValidUTF8(s[:n], "") + "..."
}

package provider

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/assistant"
)

// Codex answers by running Codex, the person's own signed-in copy, on the machine
// the controller runs on, so that somebody with a ChatGPT plan can use it through
// Eli without Zoomies holding the login. See cli.go for what the tools share.
//
// Unlike Claude Code, Codex has no way to run with every tool off. It is run in
// its read-only sandbox, in an empty directory, with nothing of the controller in
// its environment, and what it says about running a command or changing a file is
// ignored: it is not shown, and nothing Eli does follows from it. That is a
// narrower promise than "it cannot read a file", and the documentation says so.
type Codex struct {
	cfg Config
}

// NewCodex returns the adapter. cfg.Command, when set, is the binary to run.
func NewCodex(cfg Config) *Codex { return &Codex{cfg: cfg} }

// ErrCodexNotFound is Codex not being on this machine.
var ErrCodexNotFound = errors.New("the machine the controller runs on has no Codex: " +
	"install it there, sign in as the user the controller runs as with `codex login`, and test again")

var errCodexNotSignedIn = errors.New("nobody is signed in to Codex on this machine: " +
	"sign in as the user the controller runs as with `codex login`, and test again")

var errCodexAPIKey = errors.New("this machine’s Codex is signed in with an API key, not with a ChatGPT plan; " +
	"sign in with your ChatGPT account (`codex login`), or use the OpenAI provider for an API key")

func codexBinary(override string) (string, error) {
	return cliBinary(override, "codex", codexCandidates(), ErrCodexNotFound)
}

// codexCandidates are the places Codex's installers put it, for a service whose PATH
// does not include them. A variable so a test is not at the mercy of a Codex that
// happens to be installed where it runs.
var codexCandidates = func() []string {
	var out []string
	if home, err := os.UserHomeDir(); err == nil {
		out = append(out, filepath.Join(home, ".local", "bin", "codex"), filepath.Join(home, ".npm-global", "bin", "codex"))
	}
	return append(out, "/usr/local/bin/codex", "/opt/homebrew/bin/codex")
}

// codexEnv is Codex's environment: where it lives and where its sign-in is kept
// (CODEX_HOME), and no key. An API key in the environment would make it bill that
// account and not the person's plan, which is not what was asked for.
func codexEnv(environ []string) []string { return cliEnv(environ, "CODEX_HOME") }

// codexArgs is how Codex is run. The prompt is on standard input ("-"). The sandbox
// is the read-only one, nothing is saved, and neither the person's own
// configuration nor their rules files are read, so what a Codex on this machine
// has been set up to do cannot widen any of it. There is no approval flag: exec has
// nobody to ask, and a command the sandbox does not allow does not run.
func codexArgs(model string) []string {
	args := []string{
		"exec", "--json", "--sandbox", "read-only", "--skip-git-repo-check", "--ephemeral",
		"--ignore-user-config", "--ignore-rules",
	}
	if model != "" {
		args = append(args, "--model", model)
	}
	return append(args, "-")
}

// toolFreePrompt is the conversation as text for a tool that takes one prompt, with
// what the assistant is told about itself first and a plain request, which is all
// it is, not to use the machine.
func toolFreePrompt(system string, messages []assistant.Message) string {
	var b strings.Builder
	if system != "" {
		b.WriteString(system)
		b.WriteString("\n\n")
	}
	b.WriteString(claudePrompt(messages))
	b.WriteString("\nAnswer in plain text from what you know. Do not run commands, read files or search the web.\n")
	return b.String()
}

// Chat implements assistant.Provider.
func (p *Codex) Chat(ctx context.Context, req assistant.Request) (assistant.Stream, error) {
	bin, err := codexBinary(p.cfg.Command)
	if err != nil {
		return nil, err
	}
	model := req.Model
	if model == "" {
		model = p.cfg.Model
	}
	parse := &codexParse{}
	return startCLI(ctx, cliCommand{
		tool:   "Codex",
		bin:    bin,
		args:   codexArgs(model),
		env:    codexEnv(os.Environ()),
		stdin:  toolFreePrompt(req.System, req.Messages),
		reader: readLines(parse),
		exit:   parse.exit,
	})
}

// codexParse reads the lines of `codex exec --json`, one at a time. It is a value
// so a test can feed it lines.
type codexParse struct {
	sawText bool
	// failed is the last error Codex reported without ending the turn, kept for a
	// run that then ends badly with nothing else to say.
	failed string
}

type codexLine struct {
	Type string `json:"type"`
	Item struct {
		Type string `json:"type"`
		Text string `json:"text"`
	} `json:"item"`
	Usage *struct {
		InputTokens  int `json:"input_tokens"`
		OutputTokens int `json:"output_tokens"`
	} `json:"usage"`
	Error   *struct{ Message string } `json:"error"`
	Message string                    `json:"message"`
}

func (c *codexParse) answered() bool { return c.sawText }

// line interprets one line. Only what the agent says as its answer is kept. The
// commands it ran, the files it changed, its tool calls, searches, plans and
// reasoning are ignored on purpose: Eli takes an answer and does nothing on the
// strength of what a tool did. A line it does not understand is nothing, because a
// newer Codex may print more than this knows.
func (c *codexParse) line(raw []byte) []assistant.Event {
	raw = []byte(strings.TrimSpace(string(raw)))
	if len(raw) == 0 || raw[0] != '{' {
		return nil
	}
	var l codexLine
	if json.Unmarshal(raw, &l) != nil {
		return nil
	}
	switch l.Type {
	case "item.completed":
		if l.Item.Type != "agent_message" || l.Item.Text == "" {
			return nil
		}
		text := l.Item.Text
		if c.sawText {
			// An answer that is said in more than one message reads as paragraphs.
			text = "\n\n" + text
		}
		c.sawText = true
		return []assistant.Event{{Delta: text}}
	case "turn.completed":
		if !c.sawText {
			return []assistant.Event{{Err: errors.New("Codex finished the turn without an answer")}}
		}
		var out []assistant.Event
		if l.Usage != nil {
			out = append(out, assistant.Event{Usage: &assistant.Usage{InputTokens: l.Usage.InputTokens, OutputTokens: l.Usage.OutputTokens, Reported: true}})
		}
		return append(out, assistant.Event{Done: true})
	case "turn.failed":
		said := ""
		if l.Error != nil {
			said = l.Error.Message
		}
		if said == "" {
			said = c.failed
		}
		return []assistant.Event{{Err: codexFailure(said)}}
	case "error":
		// Codex reports some trouble it then recovers from, such as a dropped
		// connection it retries, so this alone does not end the answer.
		c.failed = l.Message
	}
	return nil
}

// codexFailure is what Codex said when it could not answer, for the person.
func codexFailure(said string) error {
	said = strings.TrimSpace(said)
	lower := strings.ToLower(said)
	switch {
	case strings.Contains(lower, "codex login"), strings.Contains(lower, "not logged in"), strings.Contains(lower, "unauthorized"),
		strings.Contains(lower, "401"), strings.Contains(lower, "log in again"), strings.Contains(lower, "sign in again"):
		return errCodexNotSignedIn
	case said == "":
		return errors.New("the answer failed in Codex")
	}
	return fmt.Errorf("the answer failed in Codex: %s", clip(said, 300))
}

// exit is a run that ended badly with nothing said as an answer. Codex's standard
// error is its progress, which says little about why, so what it reported in the
// stream comes first.
func (c *codexParse) exit(err error, stderr string) error {
	lower := strings.ToLower(stderr)
	switch {
	case c.failed != "":
		return codexFailure(c.failed)
	case strings.Contains(lower, "unexpected argument"), strings.Contains(lower, "unknown option"), strings.Contains(lower, "unrecognized"):
		return errors.New("this version of Codex does not accept the options Zoomies needs to run it safely; update it and test again")
	case strings.Contains(lower, "codex login"), strings.Contains(lower, "not logged in"):
		return errCodexNotSignedIn
	}
	return fmt.Errorf("the run stopped in Codex without an answer (%v)", err)
}

// Check implements assistant.Provider. It spends no usage: it asks Codex which
// version it is and whether anyone is signed in, and says so if it is an API key.
func (p *Codex) Check(ctx context.Context) (assistant.CheckResult, error) {
	start := time.Now()
	bin, err := codexBinary(p.cfg.Command)
	if err != nil {
		return assistant.CheckResult{}, err
	}
	run := func(args ...string) ([]byte, error) {
		ctx, cancel := context.WithTimeout(ctx, 20*time.Second)
		defer cancel()
		cmd := exec.CommandContext(ctx, bin, args...)
		cmd.Env = codexEnv(os.Environ())
		cmd.Dir = os.TempDir()
		return cmd.CombinedOutput()
	}
	ver, err := run("--version")
	if err != nil {
		return assistant.CheckResult{}, fmt.Errorf("no version from Codex: %w", err)
	}
	status, err := run("login", "status")
	if err != nil {
		return assistant.CheckResult{}, errCodexNotSignedIn
	}
	// The text of the status is not shown: for an API key it can carry part of the key.
	if strings.Contains(strings.ToLower(string(status)), "api key") {
		return assistant.CheckResult{}, errCodexAPIKey
	}
	first, _, _ := strings.Cut(strings.TrimSpace(string(ver)), "\n")
	return assistant.CheckResult{Model: first, Latency: time.Since(start), UsageReported: false}, nil
}

package provider

import (
	"context"
	"errors"
	"os"
	"path/filepath"
	"runtime"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/assistant"
)

// fakeTool writes an executable called name that stands in for a vendor's tool: the
// script is what it does, and $REC is a directory it may record what it was given in.
func fakeTool(t *testing.T, name, script string) (bin, rec string) {
	t.Helper()
	if runtime.GOOS == "windows" {
		t.Skip("the fake tools are shell scripts")
	}
	dir := t.TempDir()
	rec = filepath.Join(dir, "rec")
	if err := os.Mkdir(rec, 0o755); err != nil {
		t.Fatal(err)
	}
	bin = filepath.Join(dir, name)
	if err := os.WriteFile(bin, []byte("#!/bin/sh\nREC='"+rec+"'\n"+script), 0o755); err != nil {
		t.Fatal(err)
	}
	return bin, rec
}

// codexAnswering is a script that records how it was run and answers as `codex exec
// --json` does, including the lines about a command it ran and a file it changed,
// which are what an agent with tools produces.
const codexAnswering = `
printf '%s\n' "$@" > "$REC/args"
pwd > "$REC/cwd"
env > "$REC/env"
cat > "$REC/stdin"
echo '{"type":"thread.started","thread_id":"t"}'
echo '{"type":"turn.started"}'
echo '{"type":"item.started","item":{"id":"item_1","type":"command_execution","command":"bash -lc ls","status":"in_progress"}}'
echo '{"type":"item.completed","item":{"id":"item_1","type":"command_execution","command":"bash -lc ls","aggregated_output":"SECRET-LISTING","status":"completed"}}'
echo '{"type":"item.completed","item":{"id":"item_2","type":"file_change","changes":[{"path":"x","kind":"add"}],"status":"completed"}}'
echo '{"type":"item.completed","item":{"id":"item_3","type":"reasoning","text":"thinking about it"}}'
echo '{"type":"item.completed","item":{"id":"item_4","type":"agent_message","text":"A runner is a machine."}}'
echo '{"type":"item.completed","item":{"id":"item_5","type":"agent_message","text":"An ephemeral one lives for one job."}}'
echo '{"type":"turn.completed","usage":{"input_tokens":24,"cached_input_tokens":20,"output_tokens":7,"reasoning_output_tokens":0}}'
`

func codexRequest() assistant.Request {
	return assistant.Request{
		System: "You are Eli.",
		Messages: []assistant.Message{
			{Role: assistant.RoleUser, Content: "What is a runner?"},
			{Role: assistant.RoleAssistant, Content: "A machine."},
			{Role: assistant.RoleUser, Content: "And an ephemeral one?"},
		},
	}
}

// Only what the agent says as its answer reaches Eli. What a tool did, and what it
// printed, is ignored: nothing Eli shows or does follows from it.
func TestCodexAnswersWithWhatTheAgentSaidAndNothingItsToolsDid(t *testing.T) {
	bin, rec := fakeTool(t, "codex", codexAnswering)
	s, err := NewCodex(Config{Command: bin}).Chat(context.Background(), codexRequest())
	if err != nil {
		t.Fatal(err)
	}
	text, usage, rerr, done := collect(t, s)
	_ = s.Close()
	if rerr != nil || !done {
		t.Fatalf("err = %v, done = %v", rerr, done)
	}
	if text != "A runner is a machine.\n\nAn ephemeral one lives for one job." {
		t.Errorf("text = %q", text)
	}
	for _, leaked := range []string{"SECRET-LISTING", "bash -lc", "thinking about it"} {
		if strings.Contains(text, leaked) {
			t.Errorf("the answer carries %q, which a tool did or the agent thought", leaked)
		}
	}
	if usage == nil || usage.InputTokens != 24 || usage.OutputTokens != 7 || !usage.Reported {
		t.Errorf("usage = %+v", usage)
	}
	stdin, _ := os.ReadFile(filepath.Join(rec, "stdin"))
	for _, want := range []string{"You are Eli.", "User: What is a runner?", "Assistant: A machine.", "User: And an ephemeral one?", "Do not run commands"} {
		if !strings.Contains(string(stdin), want) {
			t.Errorf("the prompt does not say %q:\n%s", want, stdin)
		}
	}
}

// Codex has no way to run without tools, so it is run in its read-only sandbox, with
// nothing saved and none of the machine's own configuration or rules, from an empty
// directory, and never with a flag that widens any of that.
func TestCodexIsRunReadOnlyInAnEmptyDirectory(t *testing.T) {
	bin, rec := fakeTool(t, "codex", codexAnswering)
	req := codexRequest()
	req.Model = "gpt-test"
	s, err := NewCodex(Config{Command: bin}).Chat(context.Background(), req)
	if err != nil {
		t.Fatal(err)
	}
	collect(t, s)
	_ = s.Close()
	raw, _ := os.ReadFile(filepath.Join(rec, "args"))
	args := strings.Split(strings.TrimSpace(string(raw)), "\n")
	for _, want := range []string{"exec", "--json", "--skip-git-repo-check", "--ephemeral", "--ignore-user-config", "--ignore-rules"} {
		if !slices.Contains(args, want) {
			t.Errorf("args lack %q: %q", want, args)
		}
	}
	if i := slices.Index(args, "--sandbox"); i < 0 || args[i+1] != "read-only" {
		t.Errorf("the sandbox is not read-only: %q", args)
	}
	if i := slices.Index(args, "--model"); i < 0 || args[i+1] != "gpt-test" {
		t.Errorf("the model is not passed: %q", args)
	}
	if args[len(args)-1] != "-" {
		t.Errorf("the prompt is not read from standard input: %q", args)
	}
	for _, bad := range []string{"--yolo", "--dangerously-bypass-approvals-and-sandbox", "--full-auto", "workspace-write", "danger-full-access"} {
		if slices.Contains(args, bad) {
			t.Errorf("args carry %q: %q", bad, args)
		}
	}
	cwd, _ := os.ReadFile(filepath.Join(rec, "cwd"))
	dir := strings.TrimSpace(string(cwd))
	if !strings.Contains(dir, "zoomies-eli-") {
		t.Errorf("run in %q, want a directory of its own", dir)
	}
	if _, err := os.Stat(dir); !os.IsNotExist(err) {
		t.Errorf("the directory %q was left behind", dir)
	}

	// Without a model named, none is passed and Codex chooses.
	bin, rec = fakeTool(t, "codex", codexAnswering)
	s, _ = NewCodex(Config{Command: bin}).Chat(context.Background(), codexRequest())
	collect(t, s)
	_ = s.Close()
	raw, _ = os.ReadFile(filepath.Join(rec, "args"))
	if strings.Contains(string(raw), "--model") {
		t.Errorf("a model was passed though none was named: %q", raw)
	}
}

// Codex is given where it lives and where its sign-in is kept, and nothing of the
// controller's: a key in the environment would bill that account and not the plan.
