			if err != nil {
				t.Fatal(err)
			}
			_, _, rerr, _ := collect(t, s)
			_ = s.Close()
			if rerr == nil || !strings.Contains(rerr.Error(), tc.want) {
				t.Errorf("err = %v, want one with %q", rerr, tc.want)
			}
