package provider

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"regexp"
)

// HTTPError is a response that was not a success, with the status kept so a
// caller can tell a missing route from a refusal without parsing the words.
type HTTPError struct {
	Status  int
	Message string
}

func (e *HTTPError) HTTPStatus() int { return e.Status }

func (e *HTTPError) Error() string { return e.Message }

// StatusError turns a response that is not a success into an error written
// for the person who will read it on the settings page. The request is
// never part of it: its headers hold the key, and a 401's body often quotes
// the key back, so the two statuses that mean "the key" say only that.
// hasKey is whether a key was sent at all: a refusal with no key configured
// sends the person to add one, not to rotate one they never set.
func StatusError(resp *http.Response, hasKey bool) error {
	if resp.StatusCode >= 200 && resp.StatusCode < 300 {
		return nil
	}
	return &HTTPError{Status: resp.StatusCode, Message: statusMessage(resp, hasKey)}
}

func statusMessage(resp *http.Response, hasKey bool) string {
	body, _ := io.ReadAll(io.LimitReader(resp.Body, 64*1024))
	switch resp.StatusCode {
	case http.StatusUnauthorized, http.StatusForbidden:
		if !hasKey {
			return fmt.Sprintf("the provider needs an API key (HTTP %d)", resp.StatusCode)
		}
		return fmt.Sprintf("the provider refused the key (HTTP %d)", resp.StatusCode)
	case http.StatusNotFound:
		if m := modelName.FindSubmatch(body); m != nil {
			return fmt.Sprintf("no model named %s at the provider", m[1])
		}
		return "the provider answered 404: check the base URL and the model name"
	case http.StatusTooManyRequests:
		return "the provider rate limited the request (HTTP 429); try again shortly"
	}
	if msg := errorMessage(body); msg != "" {
		return fmt.Sprintf("the provider answered %d: %s", resp.StatusCode, msg)
	}
	return fmt.Sprintf("the provider answered %d", resp.StatusCode)
}

// modelName finds the quoted model in the sentences both APIs write for an
// unknown model, so the error can say which name was wrong.
var modelName = regexp.MustCompile(`[mM]odel[: ]+['"\x60]?([A-Za-z0-9._:/-]+)['"\x60]?`)

// errorMessage reads the message both APIs put at error.message, and nothing
// when the body is not that shape.
func errorMessage(body []byte) string {
	var env struct {
		Error struct {
			Message string `json:"message"`
		} `json:"error"`
	}
	if err := json.Unmarshal(body, &env); err != nil {
		return ""
	}
	return env.Error.Message
}

package provider

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

// A provider's refusal is shown to an administrator on the settings page and
// kept on the row, so it says what went wrong in words and never carries the
// request, whose headers hold the key.
func TestStatusErrorsNameTheCauseAndNotTheRequest(t *testing.T) {
	for _, tt := range []struct {
		status int
		body   string
		want   string
	}{
		{401, `{"error":{"message":"Incorrect API key provided: sk-abc. Authorization: Bearer sk-abc"}}`, "the provider refused the key"},
		{403, `{"error":{"message":"forbidden"}}`, "the provider refused the key"},
		{404, `{"error":{"message":"The model 'gpt-nope' does not exist"}}`, "no model named"},
		{429, `{"error":{"message":"slow down"}}`, "rate limited"},
		{500, `{"error":{"message":"upstream exploded"}}`, "500: upstream exploded"},
		{503, `not json`, "503"},
	} {
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			w.WriteHeader(tt.status)
			w.Write([]byte(tt.body))
		}))
		resp, err := http.Get(srv.URL)
		srv.Close()
		if err != nil {
			t.Fatal(err)
		}
		got := StatusError(resp, true)
		if got == nil || !strings.Contains(got.Error(), tt.want) {
			t.Errorf("%d: got %v, want it to contain %q", tt.status, got, tt.want)
		}
		if got != nil && (strings.Contains(got.Error(), "sk-abc") || strings.Contains(got.Error(), "Authorization")) {
			t.Errorf("%d: the error carries the key or the header: %v", tt.status, got)
		}
	}
}

func TestStatusErrorIsNilForASuccess(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {}))
	defer srv.Close()
	resp, _ := http.Get(srv.URL)
	if err := StatusError(resp, true); err != nil {
		t.Errorf("got %v", err)
	}
}

package provider

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"sort"
	"strings"
)

// maxModels bounds a model list: a gateway such as OpenRouter serves hundreds,
// and a page does not need more than a screenful's worth of choice to be useful.
const maxModels = 1000

// modelsFrom reads the list both protocols answer with, `{"data":[{"id":...}]}`,
// into sorted, distinct names. A body that is not that is an error saying so,
// and never repeats the body: it came from a server the person pointed us at.
func modelsFrom(resp *http.Response) ([]string, error) {
	defer resp.Body.Close()
	raw, err := io.ReadAll(io.LimitReader(resp.Body, 4<<20))
	if err != nil {
		return nil, fmt.Errorf("reading the model list: %w", err)
	}
	var list struct {
		Data []struct {
			ID string `json:"id"`
		} `json:"data"`
	}
	if err := json.Unmarshal(raw, &list); err != nil || list.Data == nil {
		return nil, fmt.Errorf("the provider answered, but not with a list of models; type the model's name instead")
	}
	seen := map[string]bool{}
	var out []string
	for _, m := range list.Data {
		id := strings.TrimSpace(m.ID)
		if id == "" || seen[id] {
			continue
		}
		seen[id] = true
		out = append(out, id)
	}
	sort.Strings(out)
	if len(out) > maxModels {
		out = out[:maxModels]
	}
	return out, nil
}

