package provider

import "os/exec"

// ownGroup is nothing where there are no process groups to use.
func ownGroup(cmd *exec.Cmd) {}

// killGroup ends the command.
func killGroup(cmd *exec.Cmd) error {
	if cmd.Process == nil {
		return nil
	}
	return cmd.Process.Kill()
}

//go:build unix

package provider

import (
	"os/exec"
	"syscall"
)

// ownGroup puts a command in a process group of its own, so that ending it ends
// what it started as well. Claude Code is a Node program that starts others, and
// a process that is killed while its children hold its output open is waited for
// until they let go.
func ownGroup(cmd *exec.Cmd) {
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	cmd.Cancel = func() error { return killGroup(cmd) }
}

// killGroup ends the command and everything in its group.
func killGroup(cmd *exec.Cmd) error {
	if cmd.Process == nil {
		return nil
	}
	if err := syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL); err != nil {
		return cmd.Process.Kill()
	}
	return nil
}

// Package provider holds the adapters that speak to a model over HTTP and
// the pieces they share: a server-sent event reader, the stream that turns
// events into the assistant's, and the words a status code gets. Only
// internal/assistant imports it.
package provider

import (
	"bufio"
	"io"
	"iter"
	"strings"
)

// ServerEvent is one event as a server wrote it: its name, when it gave one,
// and its data lines joined with newlines.
type ServerEvent struct {
	Name string
	Data string
}

// maxLine bounds one line of a stream. A delta is a few hundred bytes; a
// megabyte is a server misbehaving, and the reader says so rather than
// growing without bound.
const maxLine = 1 << 20

// ReadEvents yields the events in r until it ends. Comment lines (a leading
// colon) are skipped, which is what keep-alives are; an event the stream
// ends in the middle of is still yielded, because the terminal event of both
// protocols is often the one a server forgets to put a blank line after.
func ReadEvents(r io.Reader) iter.Seq2[ServerEvent, error] {
	return func(yield func(ServerEvent, error) bool) {
		sc := bufio.NewScanner(r)
		sc.Buffer(make([]byte, 0, 64*1024), maxLine)
		var cur ServerEvent
		var data []string
		pending := false
		flush := func() bool {
			if !pending {
				return true
			}
			cur.Data = strings.Join(data, "\n")
			ok := yield(cur, nil)
			cur, data, pending = ServerEvent{}, nil, false
			return ok
		}
		for sc.Scan() {
			line := sc.Text()
			switch {
			case line == "":
				if !flush() {
					return
				}
			case strings.HasPrefix(line, ":"):
				// A comment: keep-alives are written this way.
			default:
				field, value, _ := strings.Cut(line, ":")
				value = strings.TrimPrefix(value, " ")
				switch field {
				case "event":
					cur.Name = value
					pending = true
				case "data":
					data = append(data, value)
					pending = true
				}
			}
		}
		if err := sc.Err(); err != nil {
			yield(ServerEvent{}, err)
			return
		}
		flush()
	}
}

package provider

import (
	"strings"
	"testing"
)

// Both wire protocols stream server-sent events, and the differences between
// how servers write them (comments as keep-alives, data split over lines, a
// last event with no blank line after it) are the reader's to absorb once.
func TestReadEventsJoinsMultiLineDataAndSkipsComments(t *testing.T) {
	in := ": keep-alive\n\nevent: delta\ndata: {\"a\":\n\ndata: 1}\n\n: ping\ndata: second\n\n"
	var got []ServerEvent
	for e, err := range ReadEvents(strings.NewReader(in)) {
		if err != nil {
			t.Fatal(err)
		}
		got = append(got, e)
	}
	want := []ServerEvent{{Name: "delta", Data: "{\"a\":"}, {Name: "", Data: "1}"}, {Name: "", Data: "second"}}
	if len(got) != len(want) {
		t.Fatalf("got %+v, want %+v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Errorf("event %d: got %+v, want %+v", i, got[i], want[i])
		}
	}
}

func TestReadEventsJoinsDataLinesWithinOneEvent(t *testing.T) {
	in := "data: line one\ndata: line two\n\n"
	for e, err := range ReadEvents(strings.NewReader(in)) {
		if err != nil {
			t.Fatal(err)
		}
		if e.Data != "line one\nline two" {
			t.Errorf("data %q", e.Data)
		}
	}
}

func TestReadEventsStopsAtEOFWithTheUnterminatedEvent(t *testing.T) {
	in := "data: first\n\ndata: last without a blank line"
	var datas []string
	for e, err := range ReadEvents(strings.NewReader(in)) {
		if err != nil {
			t.Fatal(err)
		}
		datas = append(datas, e.Data)
	}
	if len(datas) != 2 || datas[1] != "last without a blank line" {
		t.Errorf("got %q", datas)
	}
}

package provider

import (
	"context"
	"errors"
	"iter"
	"net/http"

	"github.com/eyupio/zoomies/internal/assistant"
)

// Decoder turns one server event into the assistant's events: none for a
// keep-alive or a frame the adapter ignores, several when one frame carries
// a delta and the usage, and one with Done when the server is finished.
type Decoder func(ServerEvent) ([]assistant.Event, error)

// NewStream wraps a streaming response. Events are read in the caller's
// goroutine on Next, so there is nothing to leak; cancellation closes the
// body from a context.AfterFunc, which is what makes a blocked read return.
func NewStream(resp *http.Response, decode Decoder) assistant.Stream {
	s := &stream{resp: resp, decode: decode}
	s.next, s.stop = iter.Pull2(ReadEvents(resp.Body))
	return s
}

type stream struct {
	resp   *http.Response
	decode Decoder
	next   func() (ServerEvent, error, bool)
	stop   func()
	queue  []assistant.Event
	ended  bool
}

func (s *stream) Next(ctx context.Context) (assistant.Event, bool) {
	if s.ended {
		return assistant.Event{}, false
	}
	for len(s.queue) == 0 {
		if err := ctx.Err(); err != nil {
			return s.end(assistant.Event{Err: err})
		}
		// The read below blocks on the body; closing the body is what frees
		// it when the context ends first.
		stopWatch := context.AfterFunc(ctx, func() { s.resp.Body.Close() })
		ev, err, ok := s.next()
		stopWatch()
		if ctx.Err() != nil {
			return s.end(assistant.Event{Err: ctx.Err()})
		}
		if err != nil {
			return s.end(assistant.Event{Err: err})
		}
		if !ok {
			// The server went away before it said it was done. A reply that
			// happens to be short is not the same thing, so this is an error.
			return s.end(assistant.Event{Err: errors.New("the provider closed the stream before it finished answering")})
		}
		events, err := s.decode(ev)
		if err != nil {
			return s.end(assistant.Event{Err: err})
		}
		s.queue = append(s.queue, events...)
	}
	e := s.queue[0]
	s.queue = s.queue[1:]
	if e.Done || e.Err != nil {
		return s.end(e)
	}
	return e, true
}

func (s *stream) end(e assistant.Event) (assistant.Event, bool) {
	s.ended = true
	s.stop()
	s.resp.Body.Close()
	return e, true
}

// Close releases the connection. After the stream ended it is a no-op, and
// before, it drains nothing: a reply nobody is reading is not worth the
// bytes.
func (s *stream) Close() error {
	if !s.ended {
		s.ended = true
		s.stop()
	}
	s.resp.Body.Close()
	return nil
}

package provider

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/assistant"
)

// decodeData turns each event's data into one delta, with "done" ending the
// stream, which is enough shape to test the plumbing every adapter shares.
func decodeData(e ServerEvent) ([]assistant.Event, error) {
	if e.Data == "done" {
		return []assistant.Event{{Done: true}}, nil
	}
	return []assistant.Event{{Delta: e.Data}}, nil
}

func open(t *testing.T, handler http.HandlerFunc) (assistant.Stream, context.CancelFunc) {
	t.Helper()
	srv := httptest.NewServer(handler)
	t.Cleanup(srv.Close)
	ctx, cancel := context.WithCancel(context.Background())
	req, _ := http.NewRequestWithContext(ctx, http.MethodGet, srv.URL, nil)
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatal(err)
	}
	return NewStream(resp, decodeData), cancel
}

// A connection cut before the server says it is done is a failure the person
// should see as one, not a reply that happens to be short.
func TestAStreamCutBeforeItsTerminalEventReturnsAnError(t *testing.T) {
	s, cancel := open(t, func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/event-stream")
		fmt.Fprint(w, "data: one\n\ndata: two\n\n")
	})
	defer cancel()
	defer s.Close()
	var deltas []string
	for {
		e, ok := s.Next(context.Background())
		if !ok {
			t.Fatal("the stream ended with neither Done nor an error")
		}
		if e.Err != nil {
			if len(deltas) != 2 {
				t.Errorf("deltas before the error: %q", deltas)
			}
			return
		}
		if e.Done {
			t.Fatal("a cut stream reported Done")
		}
		deltas = append(deltas, e.Delta)
	}
}

func TestCancellingTheContextEndsTheStream(t *testing.T) {
	s, cancel := open(t, func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/event-stream")
		w.(http.Flusher).Flush()
		<-r.Context().Done()
	})
	defer s.Close()
	cancel()
	done := make(chan assistant.Event, 1)
	go func() { e, _ := s.Next(context.Background()); done <- e }()
	select {
	case e := <-done:
		if !errors.Is(e.Err, context.Canceled) {
			t.Errorf("error %v is not context.Canceled", e.Err)
		}
	case <-time.After(time.Second):
		t.Fatal("Next did not return within a second of cancellation")
	}
}

func TestADoneEventEndsTheStreamAndCloseIsNil(t *testing.T) {
	s, cancel := open(t, func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, "data: hi\n\ndata: done\n\n")
	})
	defer cancel()
	var last assistant.Event
	for {
		e, ok := s.Next(context.Background())
		if !ok {
			break
		}
		last = e
	}
	if !last.Done {
		t.Errorf("last event %+v is not Done", last)
	}
	if err := s.Close(); err != nil {
		t.Errorf("Close: %v", err)
	}
}

package assistant

import (
	"go/parser"
	"go/token"
	"io/fs"
	"os"
	"path/filepath"
	"slices"
	"strconv"
	"strings"
	"testing"
)

// The package that defines what a provider is must not know about any one
// provider's wire protocol, a database or the controller: the adapters,
// the store and the API all import it, and a cycle or a hidden dependency
// here is one every later slice inherits.
func TestTheAssistantPackageImportsOnlyWhatItMayImport(t *testing.T) {
	allowed := []string{
		"bufio", "bytes", "context", "crypto/tls", "encoding/json", "errors", "fmt", "io", "iter",
		"net", "net/http", "net/netip", "net/url", "slices", "strings", "sync", "testing", "time",
	}
	all, err := filepath.Glob("*.go")
	if err != nil {
		t.Fatal(err)
	}
	fset := token.NewFileSet()
	for _, name := range all {
		if strings.HasSuffix(name, "_test.go") {
			continue
		}
		file, err := parser.ParseFile(fset, name, nil, parser.ImportsOnly)
		if err != nil {
			t.Fatal(err)
		}
		for _, imp := range file.Imports {
			path, _ := strconv.Unquote(imp.Path.Value)
			if !slices.Contains(allowed, path) {
				t.Errorf("%s imports %s; the assistant package may import only %v", name, path, allowed)
			}
		}
	}
}

// Section 9.2: nothing else may import a provider package but the assistant,
// and within it only the kinds package, which opens one by kind, so that a
// model's wire protocol is reachable from one place and the rule that every
// provider passes the contract has teeth.
func TestNothingButTheAssistantImportsAnAdapter(t *testing.T) {
	fset := token.NewFileSet()
	for _, root := range []string{"../../internal", "../../cmd"} {
		err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			if d.IsDir() || !strings.HasSuffix(path, ".go") {
				return nil
			}
			slash := filepath.ToSlash(path)
			if strings.Contains(slash, "/internal/assistant/kinds/") || strings.Contains(slash, "/internal/assistant/provider/") {
				return nil
			}
			file, err := parser.ParseFile(fset, path, nil, parser.ImportsOnly)
			if err != nil {
				return err
			}
			for _, imp := range file.Imports {
				p, _ := strconv.Unquote(imp.Path.Value)
				if strings.HasPrefix(p, "github.com/eyupio/zoomies/internal/assistant/provider") {
					t.Errorf("%s imports %s; only internal/assistant/kinds may", path, p)
				}
			}
			return nil
		})
		if err != nil {
			t.Fatal(err)
		}
	}
	if _, err := os.Stat("provider.go"); err != nil {
		t.Fatal("provider.go is missing: the package this test guards does not exist yet")
	}
}

package auth

import (
	"context"
	"fmt"
)

// ContextAccess adds the source-specific gate to the ordinary action policy.
// Admins still need membership to read source; configuring the feature is a
// separate authority. An unowned automation token has nobody's source access.
func (s *Service) ContextAccess(ctx context.Context, id *Identity, repositoryID string) (bool, error) {
	if !Allowed(id, ActionContextRead) || id.UserID == "" {
		return false, nil
	}
	switch id.Kind {
	case KindUser, KindToken:
		return s.store.AIContextUserAccess(ctx, repositoryID, id.UserID)
	case KindConnection:
		return s.store.AIContextConnectionAccess(ctx, repositoryID, id.ID, id.UserID)
	default:
		return false, nil
	}
}

// ContextPublishAccess is the gate on writing a note about a repository. A
// person or their own token needs only membership: they are the author. A
// connection needs its owner's separate consent to publish to this
// repository, because reading consent must never become writing consent.
func (s *Service) ContextPublishAccess(ctx context.Context, id *Identity, repositoryID string) (bool, error) {
	if !Allowed(id, ActionContextPublish) || id.UserID == "" {
		return false, nil
	}
	switch id.Kind {
	case KindUser, KindToken:
		return s.store.AIContextUserAccess(ctx, repositoryID, id.UserID)
	case KindConnection:
		return s.store.AIContextConnectionPublishAccess(ctx, repositoryID, id.ID, id.UserID)
	default:
		return false, nil
	}
}

// SetContextConnectionRepositories is a person's explicit source consent,
// independent of the role already approved for fleet tools. An agent must not
// be able to widen its own access by using the same token it wants to widen.
//
// publish is the subset the connection may also write notes to; nil keeps the
// publish consent already given (see store.ReplaceAIContextConnectionAccess).
func (s *Service) SetContextConnectionRepositories(ctx context.Context, actor *Identity, grantID string, repositories, publish []string) error {
	if actor == nil || actor.Kind != KindUser || actor.UserID == "" {
		return fmt.Errorf("%w: sign in as the connection's owner to choose its source repositories", ErrInvalidInput)
	}
	readable := map[string]bool{}
	for _, id := range repositories {
		readable[id] = true
	}
	for _, id := range publish {
		if !readable[id] {
			return fmt.Errorf("%w: a connection can only publish notes to repositories it may also read; choose %s for reading too", ErrInvalidInput, id)
		}
	}
	if err := s.store.ReplaceAIContextConnectionAccess(ctx, grantID, actor.UserID, repositories, publish); err != nil {
		return err
	}
	s.audit.Act(ctx, actor, "mcp_connection.context", "mcp_connection", grantID, map[string]any{"repositories": len(repositories), "publish": publish})
	return nil
}

package auth

import (
	"testing"

	"github.com/eyupio/zoomies/internal/aicontext"
	"github.com/eyupio/zoomies/internal/store"
)

func TestSourceAccessRequiresMembershipBeyondFleetRolesAndTokenScopes(t *testing.T) {
	s, st, _ := newService(t)
	u := addUser(t, st, "reader", store.RoleAdmin, nil)
	i := &store.Installation{AppID: 1, InstallationID: 2, Target: "acme", TargetType: store.TargetOrg}
	if err := st.CreateInstallation(t.Context(), i); err != nil {
		t.Fatal(err)
	}
	r := &store.AIContextRepository{Key: aicontext.RepositoryKey{GitHubHost: "github.com", InstallationID: i.ID, RepositoryID: 1}, FullName: "acme/private", Config: aicontext.DefaultConfig("main")}
	if err := st.CreateAIContextRepository(t.Context(), r); err != nil {
		t.Fatal(err)
	}
	st.SetAIContextAvailable(t.Context(), r.ID, true)
	id := &Identity{Kind: KindUser, ID: u.ID, UserID: u.ID, Role: u.Role}
	if allowed, err := s.ContextAccess(t.Context(), id, r.ID); err != nil || allowed {
		t.Fatal("admin implicitly gained source access")
	}
	if err := st.ReplaceAIContextMembers(t.Context(), r.ID, []string{u.ID}); err != nil {
		t.Fatal(err)
	}
	if allowed, err := s.ContextAccess(t.Context(), id, r.ID); err != nil || !allowed {
		t.Fatal("member refused")
	}
	for _, id := range []*Identity{nil, {Kind: KindToken, Role: store.RoleAdmin}, {Kind: KindToken, UserID: u.ID, Role: store.RoleAdmin, Scopes: []string{"jobs:read"}}, {Kind: KindConnection, ID: "old-connection", UserID: u.ID, Role: store.RoleViewer}, {Kind: KindAgent, UserID: u.ID, Role: store.RoleAdmin}} {
		if allowed, err := s.ContextAccess(t.Context(), id, r.ID); err != nil || allowed {
			t.Fatalf("source granted to %#v: %v", id, err)
		}
	}
	id = &Identity{Kind: KindToken, UserID: u.ID, Role: store.RoleViewer, Scopes: []string{"context:read"}}
	if allowed, err := s.ContextAccess(t.Context(), id, r.ID); err != nil || !allowed {
		t.Fatal("owned scoped token refused")
	}
	u.Disabled = true
	if err := st.UpdateUser(t.Context(), u); err != nil {
		t.Fatal(err)
	}
	if allowed, err := s.ContextAccess(t.Context(), id, r.ID); err != nil || allowed {
		t.Fatal("cached identity outlived disabled user")
	}
}

func TestAnAgentCannotGrantItselfSourceConsent(t *testing.T) {
	s, _, _ := newService(t)
	for _, actor := range []*Identity{nil, {Kind: KindToken, UserID: "owner", Role: store.RoleAdmin}, {Kind: KindConnection, UserID: "owner", Role: store.RoleOperator}} {
		if err := s.SetContextConnectionRepositories(t.Context(), actor, "grant", []string{"repository"}, nil); err == nil {
			t.Fatal("agent widened its own consent")
		}
	}
}

package auth

import (
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"reflect"
	"regexp"
	"slices"
	"strings"

	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/store"
)

// Auditor writes the audit trail: one row per mutating action, with the actor,
// the target and a before/after picture whose secrets have been blanked.
type Auditor struct {
	store  *store.Store
	events *events.Bus
	logger *slog.Logger
}

// NewAuditor returns an auditor. bus may be nil, in which case rows are still
// written but the UI's audit page will only see them on its next fetch.
func NewAuditor(st *store.Store, bus *events.Bus, logger *slog.Logger) *Auditor {
	if logger == nil {
		logger = slog.Default()
	}
	return &Auditor{store: st, events: bus, logger: logger}
}

// maxAuditPayload caps a single before/after document. A pool with a very large
// environment map should not be able to turn the audit table into the biggest
// thing in the database.
const maxAuditPayload = 16 << 10

// Record writes one audit row and publishes it to the event bus.
//
// It returns an error for tests and for callers that genuinely want to know,
// but nothing in a request path should act on it: refusing an operator's change
// because the audit write failed would turn a logging problem into an outage,
// and the failure is already logged here. The convenience helpers below
// therefore discard it.
func (a *Auditor) Record(ctx context.Context, id *Identity, action, targetKind, targetID string, before, after any) error {
	ev := &store.AuditEvent{
		Action:     action,
		TargetKind: targetKind,
		TargetID:   targetID,
		Before:     a.encode(before),
		After:      a.encode(after),
		ActorKind:  KindSystem,
		ActorName:  "zoomies",
	}
	if id != nil {
		ev.ActorID, ev.ActorName, ev.ActorKind, ev.IP = id.ID, id.Name, id.Kind, id.IP
		if ev.ActorKind == "" {
			ev.ActorKind = KindSystem
		}
	}
	if err := a.store.AppendAudit(ctx, ev); err != nil {
		a.logger.Error("could not write audit entry", "action", action,
			"target_kind", targetKind, "target_id", targetID, "error", err)
		return err
	}
	if a.events != nil {
		a.events.Publish(events.KindAudit, "audit:"+targetKind, ev)
	}
	return nil
}

// Created records the creation of an object.
func (a *Auditor) Created(ctx context.Context, id *Identity, targetKind, targetID string, after any) {
	_ = a.Record(ctx, id, targetKind+".create", targetKind, targetID, nil, after)
}

// Updated records a change, keeping only the fields that actually differ so the
// audit page shows "max_runners 4 -> 8" rather than the whole object twice.
func (a *Auditor) Updated(ctx context.Context, id *Identity, targetKind, targetID string, before, after any) {
	b, af := Diff(before, after)
	if b == nil && af == nil {
		// Nothing changed. A row saying so is noise in the one log an operator
		// reads when something has gone wrong.
		return
	}
	_ = a.Record(ctx, id, targetKind+".update", targetKind, targetID, b, af)
}

// Deleted records a removal, keeping the object as it was.
func (a *Auditor) Deleted(ctx context.Context, id *Identity, targetKind, targetID string, before any) {
	_ = a.Record(ctx, id, targetKind+".delete", targetKind, targetID, before, nil)
}

// Act records an action that is not a create/update/delete -- draining a
// runner, cordoning a host, verifying an installation -- with whatever detail
// the caller wants preserved.
func (a *Auditor) Act(ctx context.Context, id *Identity, action, targetKind, targetID string, detail any) {
	_ = a.Record(ctx, id, action, targetKind, targetID, nil, detail)
}

// Auth records an authentication event: a login, a logout, a refused password.
// The identity may be partial -- a failed login knows the username and the
// address but not a user ID -- which is exactly what makes these rows useful.
func (a *Auditor) Auth(ctx context.Context, id *Identity, action string, detail any) {
	targetID := ""
	if id != nil {
		targetID = id.ID
	}
	_ = a.Record(ctx, id, action, "auth", targetID, nil, detail)
}

// encode renders a before/after document: redacted, JSON, and capped.
func (a *Auditor) encode(v any) string {
	if v == nil {
		return ""
	}
	b, err := json.Marshal(Redact(v))
	if err != nil {
		a.logger.Warn("could not render audit payload", "error", err)
		return ""
	}
	if len(b) > maxAuditPayload {
		// Truncating JSON in the middle would leave a document nothing can
		// parse, so say what happened instead of storing a broken one.
		a.logger.Warn("audit payload too large to store in full", "bytes", len(b))
		return fmt.Sprintf(`{"truncated":true,"bytes":%d}`, len(b))
	}
	return string(b)
}

// ---------------------------------------------------------------------------
// Redaction
// ---------------------------------------------------------------------------

// redactedMarker replaces a secret value. It matches what the logging package
// substitutes, so an operator sees the same word in both places.
const redactedMarker = "[redacted]"

// maxRedactDepth stops a cyclic structure from recursing forever. Nothing in
// the domain model is anywhere near this deep.
const maxRedactDepth = 12

// sensitiveTerms mark a field or map key as carrying a credential. They are
// matched as substrings of the name with punctuation removed, so "password"
// catches PasswordHash and new_password, and "secret" catches both
// client_secret and WebhookSecretEnc.
var sensitiveTerms = []string{
	"password", "token", "secret", "privatekey", "jitconfig",
	"encryptionkey", "clientsecret", "webhooksecret", "credential",
	"passphrase", "apikey",
}

// nameExceptions are suffixes that turn a would-be secret name back into a
// harmless one. A token's ID, its display name and its visible prefix are the
// things that make an audit row readable; blanking them would leave an entry
// that records that something happened to some token.
var nameExceptions = []string{
	"id", "ids", "name", "names", "prefix", "count", "at",
	"file", "path", "url", "type", "kind", "hint",
}

// privateKeyBlock matches the opening line of a PEM private key: PKCS#8, RSA,
// EC, encrypted, OpenSSH, and a PGP key block. A certificate's header does not
// match it, and neither does a sentence that only mentions a private key, which
// has no "-----BEGIN" in front of it.
var privateKeyBlock = regexp.MustCompile(`-----BEGIN [A-Z0-9 ]*PRIVATE KEY`)

// holdsPrivateKey reports whether a string contains a PEM private key block.
//
// A name cannot say so. A box meant for a certificate is called "ca_pem", which
// reads as public, and a key pasted into it by mistake is exactly as secret as
// one pasted into a field called "private_key". The audit trail is readable by
// every signed-in viewer, so the value is judged as well as the name.
func holdsPrivateKey(s string) bool {
	// The cheap test first: this runs on every string in every audit payload.
	return strings.Contains(s, "PRIVATE KEY") && privateKeyBlock.MatchString(s)
}

// Redact returns a copy of v -- as maps, slices and scalars -- with every value
// whose field or key name looks like a credential replaced by "[redacted]", and
// every string that contains a PEM private key block blanked whatever its field
// is called. The whole string goes, not the block: what surrounds a pasted key
// is no more worth keeping than the key.
//
// It works on the shape a JSON document would have, not on the Go types, so the
// audit trail matches what the API shows. Fields tagged `json:"-"` are dropped
// entirely: in this codebase those are exactly the hashes and the sealed blobs,
// and they are absent from API responses for the same reason.
func Redact(v any) any { return redactValue(reflect.ValueOf(v), 0) }

var jsonMarshaler = reflect.TypeOf((*json.Marshaler)(nil)).Elem()

func redactValue(rv reflect.Value, depth int) any {
	if !rv.IsValid() {
		return nil
	}
	if depth > maxRedactDepth {
		return "[truncated]"
	}
	switch rv.Kind() {
	case reflect.Pointer, reflect.Interface:
		if rv.IsNil() {
			return nil
		}
		return redactValue(rv.Elem(), depth)
	}
	// A type that marshals itself -- time.Time, store.Duration -- is kept whole
	// so the audit entry shows "5m" and an RFC 3339 timestamp rather than a
	// nanosecond count. Containers are excluded: their contents still need
	// walking.
	if rv.Type().Implements(jsonMarshaler) && !isContainer(rv.Kind()) {
		if rv.CanInterface() {
			return rv.Interface()
		}
	}

	switch rv.Kind() {
	case reflect.Struct:
		return redactStruct(rv, depth)
	case reflect.Map:
		out := make(map[string]any, rv.Len())
		iter := rv.MapRange()
		for iter.Next() {
			key := fmt.Sprint(iter.Key().Interface())
			if isSensitiveName(key) {
				out[key] = redactedValue(iter.Value())
				continue
			}
			out[key] = redactValue(iter.Value(), depth+1)
		}
		return out
	case reflect.Slice, reflect.Array:
		if rv.Kind() == reflect.Slice && rv.IsNil() {
			return nil
		}
		// A byte slice in this codebase is a sealed secret. Its length is
		// occasionally useful; its content never is.
		if rv.Type().Elem().Kind() == reflect.Uint8 {
			return fmt.Sprintf("[%d bytes]", rv.Len())
		}
		out := make([]any, rv.Len())
		for i := range rv.Len() {
			out[i] = redactValue(rv.Index(i), depth+1)
		}
		return out
	case reflect.Func, reflect.Chan, reflect.UnsafePointer:
		return nil
	default:
		if !rv.CanInterface() {
			return nil
		}
		if rv.Kind() == reflect.String && holdsPrivateKey(rv.String()) {
			return redactedMarker
		}
		return rv.Interface()
	}
}

func redactStruct(rv reflect.Value, depth int) map[string]any {
	t := rv.Type()
	out := make(map[string]any, t.NumField())
	for i := range t.NumField() {
		f := t.Field(i)
		if !f.IsExported() {
			continue
		}
		tag := f.Tag.Get("json")
		name, _, _ := strings.Cut(tag, ",")
		if name == "-" {
			continue
		}
		if f.Anonymous && name == "" {
			// An embedded struct is flattened, which is what encoding/json does.
			if inner, ok := redactValue(rv.Field(i), depth+1).(map[string]any); ok {
				for k, v := range inner {
					if _, taken := out[k]; !taken {
						out[k] = v
					}
				}
				continue
			}
		}
		if name == "" {
			name = f.Name
		}
		if isSensitiveName(name) || isSensitiveName(f.Name) {
			out[name] = redactedValue(rv.Field(i))
			continue
		}
		out[name] = redactValue(rv.Field(i), depth+1)
	}
	return out
}

// redactedValue blanks one value.
//
// An empty value stays empty: an audit entry that shows "password": "[redacted]"
// for an account that has no password would be a lie. A bool or a number is
// returned unchanged, because neither can carry a credential and blanking
// store.Setting.Secret -- a flag whose name matches -- would make the entry
// less readable rather than safer.
func redactedValue(rv reflect.Value) any {
	if !rv.IsValid() {
		return nil
	}
	switch rv.Kind() {
	case reflect.Bool,
		reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
		reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64,
		reflect.Float32, reflect.Float64:
		if rv.CanInterface() {
			return rv.Interface()
		}
		return nil
	}
	if isEmptyValue(rv) {
		if rv.Kind() == reflect.String {
			return ""
		}
		return nil
	}
	return redactedMarker
}

func isEmptyValue(rv reflect.Value) bool {
	switch rv.Kind() {
	case reflect.Slice, reflect.Map, reflect.Array, reflect.String:
		return rv.Len() == 0
	case reflect.Pointer, reflect.Interface:
		return rv.IsNil()
	}
	return rv.IsZero()
}

func isContainer(k reflect.Kind) bool {
	return k == reflect.Map || k == reflect.Slice || k == reflect.Array
}

// isSensitiveName reports whether a field or key name means "this holds a
// credential".
func isSensitiveName(name string) bool {
	n := normalizeName(name)
	if n == "" {
		return false
	}
	matched := false
	for _, term := range sensitiveTerms {
		if strings.Contains(n, term) {
			matched = true
			break
		}
	}
	if !matched {
		return false
	}
	for _, ex := range nameExceptions {
		if n != ex && strings.HasSuffix(n, ex) {
			return false
		}
	}
	return true
}

// normalizeName lowercases a name and drops everything that is not a letter or
// a digit, so PasswordHash, password_hash and password-hash all compare equal.
func normalizeName(s string) string {
	var b strings.Builder
	for _, r := range strings.ToLower(s) {
		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') {
			b.WriteRune(r)
		}
	}
	return b.String()
}

// ---------------------------------------------------------------------------
// Diffing
// ---------------------------------------------------------------------------

// Diff returns the parts of before and after that differ, already redacted.
//
// An audit entry for "the operator raised max_runners" should say that and
// nothing else; printing two whole pool objects and leaving a human to spot the
// one changed number is how audit logs stop being read. Both results are nil
// when nothing changed.
func Diff(before, after any) (any, any) {
	b, a := Redact(before), Redact(after)
	bm, bok := b.(map[string]any)
	am, aok := a.(map[string]any)
	if !bok || !aok {
		if reflect.DeepEqual(b, a) {
			return nil, nil
		}
		return b, a
	}
	db, da := diffMaps(bm, am)
	var rb, ra any
	if len(db) > 0 {
		rb = db
	}
	if len(da) > 0 {
		ra = da
	}
	return rb, ra
}

func diffMaps(before, after map[string]any) (map[string]any, map[string]any) {
	db, da := map[string]any{}, map[string]any{}
	keys := make([]string, 0, len(before)+len(after))
	for k := range before {
		keys = append(keys, k)
	}
	for k := range after {
		if _, ok := before[k]; !ok {
			keys = append(keys, k)
		}
	}
	slices.Sort(keys)

	for _, k := range keys {
		bv, bok := before[k]
		av, aok := after[k]
		if bok && aok {
			bsub, bIsMap := bv.(map[string]any)
			asub, aIsMap := av.(map[string]any)
			if bIsMap && aIsMap {
				sb, sa := diffMaps(bsub, asub)
				if len(sb) > 0 {
					db[k] = sb
				}
				if len(sa) > 0 {
					da[k] = sa
				}
				continue
			}
			if reflect.DeepEqual(bv, av) {
				continue
			}
		}
		if bok {
			db[k] = bv
		}
		if aok {
			da[k] = av
		}
	}
	return db, da
}

package auth

import (
	"encoding/json"
	"reflect"
	"strings"
