// A new password, and signing out everywhere else, end the account's MCP
// connections along with its sessions: a connection is a credential that
// outlives any session, and the person doing either suspects one is loose.
func TestChangingThePasswordOrSigningOutElsewhereEndsMCPConnections(t *testing.T) {
	for _, tc := range []struct {
		name   string
		reason string
		act    func(t *testing.T, s *Service, u *store.User)
	}{
		{"a password change", "password changed", func(t *testing.T, s *Service, u *store.User) {
			if err := s.ChangePassword(t.Context(), u.ID, testPassword, "a different password entirely", "10.0.0.1"); err != nil {
				t.Fatal(err)
			}
		}},
		{"an administrator's reset", "password reset by an administrator", func(t *testing.T, s *Service, u *store.User) {
			if err := s.ResetPassword(t.Context(), u.ID, "a different password entirely"); err != nil {
				t.Fatal(err)
			}
		}},
		{"signing out other sessions", "signed out of other sessions", func(t *testing.T, s *Service, u *store.User) {
			id := &Identity{Kind: KindUser, ID: u.ID, UserID: u.ID, Name: u.Username, Role: u.Role}
			n, err := s.LogoutOthers(t.Context(), id, "")
			if err != nil || n != 2 {
				t.Fatalf("LogoutOthers = %d, %v; want both connections ended", n, err)
			}
		}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			s, st, _ := newService(t)
			ctx := t.Context()
			u := addUser(t, st, "olive", store.RoleOperator, nil)
			other := addUser(t, st, "pat", store.RoleOperator, nil)
			cl, mine := connectForTest(t, s, u)
			_, alsoMine := connectForTest(t, s, u)
			_, theirs := connectForTest(t, s, other)

			tc.act(t, s, u)

			for _, pair := range []*TokenResponse{mine, alsoMine} {
				if _, err := s.AuthenticateMCP(ctx, testPolicy, pair.AccessToken, ""); err == nil {
					t.Error("the account's MCP access token must stop working")
				}
				if _, err := s.Token(ctx, testPolicy, ClientCredentials{ClientID: cl.ClientID}, TokenRequest{GrantType: "refresh_token", RefreshToken: pair.RefreshToken}, ""); err == nil {
					t.Error("the account's MCP refresh token must stop working")
				}
			}
			if _, err := s.AuthenticateMCP(ctx, testPolicy, theirs.AccessToken, ""); err != nil {
				t.Errorf("somebody else's connection must be left alone: %v", err)
			}
			rows, _, err := st.ListAudit(ctx, store.AuditFilter{Actions: []string{"mcp_connection.revoke_all"}}, store.Page{})
			if err != nil {
				t.Fatal(err)
			}
			if len(rows) != 1 || rows[0].TargetID != u.ID || !strings.Contains(rows[0].After, tc.reason) {
				t.Errorf("want one mcp_connection.revoke_all row for %s saying %q, got %+v", u.ID, tc.reason, rows)
			}
		})
	}
}

// An edit rescues an app configured with a client_id whose registered redirect
// does not match what the client sends, without a delete and a recreate that
// would leave the app pointing at an ID the portal no longer knows. Only what
// an administrator created is editable, and the live client after the edit is
// what the token endpoint will see on that app's next sign-in.
func TestEditingAnMCPClientChangesItsNameAndRedirects(t *testing.T) {
	s, st, _ := newService(t)
	ctx := t.Context()
	admin := &Identity{Kind: KindUser, ID: "usr_admin", Name: "admin", Role: store.RoleAdmin}
	c, secret, err := s.CreateMCPClient(ctx, admin, NewMCPClient{
		Name: "Claude", RedirectURIs: []string{ClaudeCallback}, Confidential: true,
	})
	if err != nil {
		t.Fatal(err)
	}
	if secret == "" {
		t.Fatal("a confidential client must come with a secret")
	}

	after, err := s.UpdateMCPClient(ctx, admin, c.ID, NewMCPClient{
		Name: "Claude Code", RedirectURIs: []string{"http://localhost:3118/callback"},
	})
	if err != nil {
		t.Fatalf("editing an admin client: %v", err)
	}
	if after.Name != "Claude Code" {
		t.Errorf("name after the edit: %q", after.Name)
	}
	if len(after.RedirectURIs) != 1 || after.RedirectURIs[0] != "http://localhost:3118/callback" {
		t.Errorf("redirects after the edit: %v", after.RedirectURIs)
	}
	// The identity the app holds is not disturbed by an edit: only a rotate
	// invalidates the secret it was given.
	if !after.Confidential() || after.SecretPrefix != c.SecretPrefix {
		t.Error("an edit must leave the client's secret alone")
	}

	// The audit carries both ends, so an app that starts failing can have its
	// old redirection read back from the log.
	rows, _, err := st.ListAudit(ctx, store.AuditFilter{Actions: []string{"mcp_client.update"}}, store.Page{})
	if err != nil {
		t.Fatal(err)
	}
	if len(rows) != 1 || !strings.Contains(rows[0].After, "localhost:3118") || !strings.Contains(rows[0].After, ClaudeCallback) {
		t.Errorf("want one mcp_client.update row naming both redirections, got %+v", rows)
	}

	// Only a client an administrator created is editable: a dynamic one owns
	// its registration, and a revoked one has nothing left to grant.
	if err := s.RevokeMCPClient(ctx, admin, c.ID); err != nil {
		t.Fatal(err)
	}
	if _, err := s.UpdateMCPClient(ctx, admin, c.ID, NewMCPClient{Name: "Again"}); !errors.Is(err, ErrInvalidInput) {
		t.Errorf("editing a revoked client: %v", err)
	}
	registered, err := s.RegisterClient(ctx, testPolicy, ClientRegistration{
		ClientName: "Self", RedirectURIs: []string{ClaudeCallback},
	}, "203.0.113.9")
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s.UpdateMCPClient(ctx, admin, registered.ID, NewMCPClient{Name: "Again"}); !errors.Is(err, ErrInvalidInput) {
		t.Errorf("editing a dynamic client: %v", err)
	}
}

// An edit that removes a redirect URI is meant for the sign-ins already under
// way as much as for the ones that start afterwards. A fresh request for the
// address is refused at once, but a request begun in the last fifteen minutes
// and a code issued in the last five carry the address with them, and unless
// they are looked at again they deliver an authorisation code to the very place
// the administrator took away. What the edit still does not do is end a
// connection already made: its refresh token names no redirect, and the API
// promises that an edit leaves connections alone.
func TestRemovingARedirectRefusesTheSignInsAlreadyUnderWayForIt(t *testing.T) {
	s, st, _ := newService(t)
	ctx := t.Context()
	u := addUser(t, st, "olive", store.RoleOperator, nil)
	person := &Identity{Kind: KindUser, ID: u.ID, Name: u.Username, Role: u.Role}
	admin := &Identity{Kind: KindUser, ID: "usr_admin", Name: "admin", Role: store.RoleAdmin}
	const loopback = "http://localhost:3118/callback"

	client, _, err := s.CreateMCPClient(ctx, admin, NewMCPClient{Name: "Claude", RedirectURIs: []string{ClaudeCallback, loopback}})
	if err != nil {
		t.Fatal(err)
	}
	begin := func(redirect string) (*store.OAuthRequest, error) {
		return s.BeginAuthorization(ctx, testPolicy, AuthorizeParams{ClientID: client.ClientID, RedirectURI: redirect,
			ResponseType: "code", CodeChallenge: PKCEChallenge(verifier), CodeChallengeMethod: "S256"})
	}
	waitingFor := func(redirect string) *store.OAuthRequest {
		t.Helper()
		r, err := begin(redirect)
		if err != nil {
			t.Fatalf("starting a sign-in for %s: %v", redirect, err)
		}
		return r
	}
	codeFor := func(redirect string) string {
		t.Helper()
		d, err := s.ApproveAuthorization(ctx, testPolicy, person, waitingFor(redirect).ID, store.RoleViewer)
		if err != nil {
			t.Fatalf("approving a sign-in for %s: %v", redirect, err)
		}
		back, _ := url.Parse(d.RedirectTo)
		return back.Query().Get("code")
	}
	exchange := func(code, redirect string) (*TokenResponse, error) {
		return s.Token(ctx, testPolicy, ClientCredentials{ClientID: client.ClientID}, TokenRequest{
			GrantType: "authorization_code", Code: code, CodeVerifier: verifier, RedirectURI: redirect}, "203.0.113.9")
	}

	// Everything in flight when the edit lands: a connection already made
	// through the address that is about to go, a request waiting for consent
	// and a code not yet exchanged for it, and the same two for the address that
	// stays.
	connected, err := exchange(codeFor(loopback), loopback)
	if err != nil {
		t.Fatal(err)
	}
	waiting := waitingFor(loopback)
	issued := codeFor(loopback)
	stayingRequest := waitingFor(ClaudeCallback)
	stayingCode := codeFor(ClaudeCallback)

	if _, err := s.UpdateMCPClient(ctx, admin, client.ID, NewMCPClient{Name: "Claude", RedirectURIs: []string{ClaudeCallback}}); err != nil {
		t.Fatalf("removing the loopback redirect: %v", err)
	}

	// The front door was always shut: a new sign-in for the address is refused.
	var refusal *AuthorizeRefusal
	if _, err := begin(loopback); !errors.As(err, &refusal) {
		t.Fatalf("a new sign-in for a removed redirect must be refused, got %v", err)
	}

	// The consent screen for the waiting request says where approving would send
	// the person, which is the address the request holds and not whatever the
	// client lists today.
	view, err := s.DescribeAuthorization(ctx, person, waiting.ID)
	if err != nil {
		t.Fatal(err)
	}
	if !view.LoopbackOnly || view.RedirectHost != "localhost:3118" {
		t.Errorf("the screen for a request to localhost:3118 says loopback=%v host=%q, want true and localhost:3118", view.LoopbackOnly, view.RedirectHost)
	}

	// Approving it would hand a code to the removed address. It is refused, in
	// words that say what happened and what to do, and nothing is written.
	d, err := s.ApproveAuthorization(ctx, testPolicy, person, waiting.ID, store.RoleViewer)
	if d != nil || !errors.Is(err, ErrInvalidInput) || !strings.Contains(err.Error(), "redirect URIs") || !strings.Contains(err.Error(), "again") {
		t.Errorf("approving a request for a removed redirect = %+v, %v; want it refused as invalid input saying to start again", d, err)
	}
	if _, err := st.GetOAuthRequest(ctx, waiting.ID); err != nil {
		t.Errorf("a refused approval must leave the request as it was: %v", err)
	}

	// The code issued before the edit is refused at the token endpoint, whether
	// the exchange names the address or leaves it out, because the code's own
	// address is what is checked.
	for _, named := range []string{loopback, ""} {
		_, err = exchange(issued, named)
		var oe *OAuthError
		if !errors.As(err, &oe) || oe.Code != "invalid_grant" || oe.Status != 400 || !strings.Contains(oe.Description, "sign in again") {
			t.Errorf("exchanging a code for a removed redirect (redirect_uri %q) = %v; want 400 invalid_grant saying to sign in again", named, err)
		}
	}

	// What the edit leaves alone. The address that stayed is approved and
	// exchanged as before, and the connection made before the edit is still a
	// connection: it works, and it refreshes.
	if _, err := s.ApproveAuthorization(ctx, testPolicy, person, stayingRequest.ID, store.RoleViewer); err != nil {
		t.Errorf("a request for an address that is still registered must still be approved: %v", err)
	}
	if _, err := exchange(stayingCode, ClaudeCallback); err != nil {
		t.Errorf("a code for an address that is still registered must still be exchanged: %v", err)
	}
	if _, err := s.AuthenticateMCP(ctx, testPolicy, connected.AccessToken, ""); err != nil {
		t.Errorf("an edit must not end a connection already made: %v", err)
	}
	if _, err := s.Token(ctx, testPolicy, ClientCredentials{ClientID: client.ClientID},
		TokenRequest{GrantType: "refresh_token", RefreshToken: connected.RefreshToken}, ""); err != nil {
		t.Errorf("an edit must not stop a connection already made from refreshing: %v", err)
	}
}

// The consent screen warns that the code is going to the person's own machine,
// where any program can listen. That is a fact about the address this request
// sends them to: a client that also registered an https address is not made
// safe on its loopback one by it, and is not made unsafe on the https one.
func TestTheConsentScreenWarnsAboutTheAddressThisRequestSendsThePersonTo(t *testing.T) {
	s, st, _ := newService(t)
	ctx := t.Context()
	u := addUser(t, st, "olive", store.RoleOperator, nil)
	person := &Identity{Kind: KindUser, ID: u.ID, Name: u.Username, Role: u.Role}
	admin := &Identity{Kind: KindUser, ID: "usr_admin", Name: "admin", Role: store.RoleAdmin}

	client, _, err := s.CreateMCPClient(ctx, admin, NewMCPClient{
		Name: "Claude", RedirectURIs: []string{ClaudeCallback, "http://localhost/callback", "http://127.0.0.1/callback"}})
	if err != nil {
		t.Fatal(err)
	}
	for redirect, want := range map[string]bool{
		ClaudeCallback:                    false,
		"http://localhost:3118/callback":  true,
		"http://127.0.0.1:50000/callback": true,
	} {
		r, err := s.BeginAuthorization(ctx, testPolicy, AuthorizeParams{ClientID: client.ClientID, RedirectURI: redirect,
			ResponseType: "code", CodeChallenge: PKCEChallenge(verifier), CodeChallengeMethod: "S256"})
		if err != nil {
			t.Fatalf("starting a sign-in for %s: %v", redirect, err)
		}
		v, err := s.DescribeAuthorization(ctx, person, r.ID)
		if err != nil {
			t.Fatal(err)
		}
		if v.LoopbackOnly != want {
			t.Errorf("the screen for a request to %s says loopback=%v, want %v", redirect, v.LoopbackOnly, want)
		}
	}
}

package auth

import (
	"context"
	"crypto/subtle"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"strings"
	"sync"
	"time"

	"github.com/coreos/go-oidc/v3/oidc"
	"golang.org/x/oauth2"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// OIDCCallbackPath is where the identity provider sends the browser back to.
// It has to match the redirect URI registered with the provider, so it is a
// constant rather than something an operator can drift out of sync.
const OIDCCallbackPath = "/api/v1/auth/oidc/callback"

// OIDCStateTTL is how long a login may sit half-finished at the identity
// provider before its state and nonce are forgotten.
const OIDCStateTTL = 10 * time.Minute

// maxPendingStates caps the state cache to bound its memory against a stream
// of unauthenticated calls to /auth/oidc/start. Real signins are a handful in
// flight at any moment on any real deployment; anything above this is a client
// that will not finish, and refusing new entries is what keeps the map from
// growing until the process runs out of memory.
const maxPendingStates = 1024

// ErrTooManyPendingSignIns reports that the state cache is at capacity, so a
// fresh sign-in cannot be remembered. It is returned from Start rather than
// from the cache itself so callers can shape the refusal.
var ErrTooManyPendingSignIns = errors.New("too many single sign-ins in flight; wait a moment and try again")

// ErrOIDCDiscovery marks a NewOIDC failure that is the identity provider's
// rather than the configuration's: it could not be reached, or did not answer
// with an OpenID configuration. It is the one kind worth trying again without
// anybody changing anything, and errors.Is tells the two apart.
var ErrOIDCDiscovery = errors.New("the identity provider's OpenID configuration could not be read")

// discoveryError keeps the sentence written for the operator as the message
// while answering errors.Is for both the cause and ErrOIDCDiscovery.
type discoveryError struct {
	msg   string
	cause error
}

func (e *discoveryError) Error() string   { return e.msg }
func (e *discoveryError) Unwrap() []error { return []error{e.cause, ErrOIDCDiscovery} }

// backchannelLogoutEvent is the member of a logout token's events claim that
// makes it one (OpenID Connect Back-Channel Logout 1.0, section 2.4).
const backchannelLogoutEvent = "http://schemas.openid.net/event/backchannel-logout"

// logoutTokenMaxAge is how old a logout token may be and still be believed.
const logoutTokenMaxAge = 5 * time.Minute

// Claims is what a completed OIDC login tells us about the person, already
// mapped onto Zoomies' own vocabulary.
type Claims struct {
	// Subject is the provider's stable identifier for the person. It is what
	// accounts are linked by, because usernames and email addresses change.
	Subject string
	// Username is the account name inside Zoomies, from cfg.UsernameClaim.
	Username string
	Email    string
	// Name is the display name, if the provider sent one.
	Name string
	// SessionID is the provider's own session this login belongs to (the sid
	// claim), empty when it sends none. A back-channel logout names it.
	SessionID string
	// Groups are the raw group values from cfg.GroupsClaim.
	Groups []string
	// Role is what those groups map to.
	Role store.Role
}

// OIDCProvider is optional single sign-on. A nil *OIDCProvider is a valid
// "SSO is switched off" value: every method tolerates it, so callers do not
// need a branch for the common case.
type OIDCProvider struct {
	cfg      config.OIDC
	oauth    oauth2.Config
	verifier *oidc.IDTokenVerifier
	states   *stateCache
	// logouts remembers the identifier of every logout token accepted, so one
	// replayed from a proxy log ends nothing a second time.
	logouts *stateCache
	logger  *slog.Logger
}

// NewOIDC builds the provider, discovering the issuer's endpoints over the
// network. It returns (nil, nil) when SSO is disabled, so a caller can assign
// the result unconditionally.
//
// It is named NewOIDC rather than New because New is already this package's
// Service constructor.
func NewOIDC(ctx context.Context, cfg config.OIDC, externalURL string) (*OIDCProvider, error) {
	if !cfg.Enabled {
		return nil, nil
	}
	if strings.TrimSpace(cfg.Issuer) == "" {
		return nil, errors.New("oidc.enabled is on but oidc.issuer is empty; set it to your identity provider's issuer URL, e.g. https://login.example.com")
	}
	if cfg.ClientID == "" || cfg.ClientSecret == "" {
		return nil, errors.New("oidc.enabled is on but oidc.client_id or oidc.client_secret is empty; register Zoomies as an application with your identity provider and paste both here")
	}

	redirect := strings.TrimSpace(cfg.RedirectURL)
	if redirect == "" {
		if externalURL == "" {
			return nil, errors.New("oidc needs a redirect URL; set server.external_url so it can be derived, or set oidc.redirect_url explicitly")
		}
		redirect = strings.TrimRight(externalURL, "/") + OIDCCallbackPath
	}

	provider, err := oidc.NewProvider(ctx, strings.TrimRight(cfg.Issuer, "/"))
	if err != nil {
		return nil, &discoveryError{
			msg:   fmt.Sprintf("could not read the OpenID configuration from %s: %v; check oidc.issuer and that this host can reach it", cfg.Issuer, err),
			cause: err,
		}
	}

	scopes := cfg.Scopes
	if len(scopes) == 0 {
		scopes = []string{oidc.ScopeOpenID, "profile", "email"}
	}
	// Without the openid scope the provider returns no ID token at all, which
	// fails much later and much less clearly.
	if !containsFold(scopes, oidc.ScopeOpenID) {
		scopes = append([]string{oidc.ScopeOpenID}, scopes...)
	}

	return &OIDCProvider{
		cfg: cfg,
		oauth: oauth2.Config{
			ClientID:     cfg.ClientID,
			ClientSecret: cfg.ClientSecret,
			Endpoint:     provider.Endpoint(),
			RedirectURL:  redirect,
			Scopes:       scopes,
		},
		verifier: provider.Verifier(&oidc.Config{ClientID: cfg.ClientID}),
		states:   newStateCache(OIDCStateTTL, time.Now),
		logouts:  newStateCache(2*logoutTokenMaxAge, time.Now),
		logger:   slog.Default(),
	}, nil
}

// Enabled reports whether single sign-on is configured.
func (p *OIDCProvider) Enabled() bool { return p != nil }

// RedirectURL is where the provider sends the browser back to; the settings
// page shows it so an operator can paste it into the provider's console.
func (p *OIDCProvider) RedirectURL() string {
	if p == nil {
		return ""
	}
	return p.oauth.RedirectURL
}

// AllowSignup reports whether a successful login may create an account.
func (p *OIDCProvider) AllowSignup() bool { return p != nil && p.cfg.AllowSignup }

// Start begins a login: it mints a single-use state and nonce, remembers them,
// and returns the URL to redirect the browser to.
func (p *OIDCProvider) Start() (authURL, state string, err error) {
	return p.StartAfterSignOut(false)
}

// StartAfterSignOut is Start for a sign-in that follows a sign-out from this
// controller: reauthenticate asks the provider to authenticate the person
// again even if it still holds a session for them (prompt=login).
func (p *OIDCProvider) StartAfterSignOut(reauthenticate bool) (authURL, state string, err error) {
	if p == nil {
		return "", "", errors.New("single sign-on is not configured on this instance")
	}
	state = store.NewSecret(secretBytes)
	nonce := store.NewSecret(secretBytes)
	if err := p.states.put(state, nonce); err != nil {
		return "", "", err
	}
	return p.AuthCodeURL(state, nonce, reauthenticate), state, nil
}

// AuthCodeURL renders the provider's authorisation URL for a state and nonce.
func (p *OIDCProvider) AuthCodeURL(state, nonce string, reauthenticate bool) string {
	if p == nil {
		return ""
	}
	opts := []oauth2.AuthCodeOption{oidc.Nonce(nonce)}
	if reauthenticate {
		opts = append(opts, oauth2.SetAuthURLParam("prompt", "login"))
	}
	return p.oauth.AuthCodeURL(state, opts...)
}

// Complete finishes a login begun by Start: it spends the state, exchanges the
// code and returns the claims. A state that is unknown, already spent or too
// old is refused -- that is what makes the flow single-use. It proves the
// handshake began on this controller, not that it began in this browser; the
// API layer adds that half by binding the state to a cookie set at Start.
func (p *OIDCProvider) Complete(ctx context.Context, state, code string) (*Claims, error) {
	if p == nil {
		return nil, errors.New("single sign-on is not configured on this instance")
	}
	nonce, ok := p.states.take(state)
	if !ok {
		return nil, errors.New("this sign-in link has already been used or has expired; start again from the login page")
	}
	return p.Exchange(ctx, code, nonce)
}

// VerifyLogoutToken checks a back-channel logout token from the identity
// provider and returns the subject whose sessions it ends.
//
// The token is signed by the same keys as an ID token and is verified the same
// way (signature, issuer, audience, expiry). It must then say it is a logout
// token, and must not be an ID token that is being passed off as one: it
// carries the logout event and no nonce. It is refused when it is old, when it
// names no subject, and when its identifier has been seen, so that a captured
// token cannot be played again.
func (p *OIDCProvider) VerifyLogoutToken(ctx context.Context, raw string) (subject, sessionID string, err error) {
	if p == nil {
		return "", "", errors.New("single sign-on is not configured on this instance")
	}
	tok, err := p.verifier.Verify(ctx, raw)
	if err != nil {
		return "", "", fmt.Errorf("the logout token did not verify: %w", err)
	}
	var claims struct {
		Events map[string]json.RawMessage `json:"events"`
		Nonce  *string                    `json:"nonce"`
		JTI    string                     `json:"jti"`
		SID    string                     `json:"sid"`
	}
	if err := tok.Claims(&claims); err != nil {
		return "", "", fmt.Errorf("could not read the logout token's claims: %w", err)
	}
	if _, ok := claims.Events[backchannelLogoutEvent]; !ok {
		return "", "", errors.New("the token is not a logout token: it has no back-channel logout event")
	}
	if claims.Nonce != nil {
		return "", "", errors.New("the token carries a nonce, so it is an ID token and not a logout token")
	}
	if tok.Subject == "" {
		return "", "", errors.New("the logout token names no subject")
	}
	if claims.JTI == "" {
		return "", "", errors.New("the logout token has no identifier")
	}
	now := time.Now()
	if tok.IssuedAt.IsZero() || now.Sub(tok.IssuedAt) > logoutTokenMaxAge || tok.IssuedAt.Sub(now) > time.Minute {
		return "", "", errors.New("the logout token was not issued within the last few minutes")
	}
	if ok, err := p.logouts.firstUse(claims.JTI); err != nil {
		return "", "", err
	} else if !ok {
		return "", "", errors.New("that logout token has already been used")
	}
	return tok.Subject, claims.SID, nil
}

// Exchange swaps an authorisation code for an ID token, verifies it, and maps
// its claims onto a Zoomies identity. The nonce must be the one that was sent
// with the authorisation request.
func (p *OIDCProvider) Exchange(ctx context.Context, code, nonce string) (*Claims, error) {
	if p == nil {
		return nil, errors.New("single sign-on is not configured on this instance")
	}
	tok, err := p.oauth.Exchange(ctx, code)
	if err != nil {
		return nil, fmt.Errorf("the identity provider rejected the sign-in: %w", err)
	}
	raw, ok := tok.Extra("id_token").(string)
	if !ok || raw == "" {
		return nil, errors.New("the identity provider returned no ID token; check that Zoomies is asking for the openid scope and that the application is an OpenID Connect one")
	}
	idToken, err := p.verifier.Verify(ctx, raw)
	if err != nil {
		return nil, fmt.Errorf("the ID token did not verify: %w", err)
	}
	// A constant-time comparison is not strictly necessary for a value the
	// client already knows, but it costs nothing and keeps the habit.
	if subtle.ConstantTimeCompare([]byte(idToken.Nonce), []byte(nonce)) != 1 {
		return nil, errors.New("the ID token's nonce does not match the sign-in that started it; start again from the login page")
	}

	var raws map[string]any
	if err := idToken.Claims(&raws); err != nil {
		return nil, fmt.Errorf("could not read the ID token's claims: %w", err)
	}
	return p.claimsFrom(idToken.Subject, raws)
}

// claimsFrom maps a raw claim set onto Claims. It is separate from Exchange so
// the mapping can be tested without an identity provider.
func (p *OIDCProvider) claimsFrom(subject string, raw map[string]any) (*Claims, error) {
	usernameClaim := p.cfg.UsernameClaim
	if usernameClaim == "" {
		usernameClaim = "preferred_username"
	}
	groupsClaim := p.cfg.GroupsClaim
	if groupsClaim == "" {
		groupsClaim = "groups"
	}

	c := &Claims{
		Subject:   subject,
		Username:  claimString(raw, usernameClaim),
		Email:     claimString(raw, "email"),
		Name:      claimString(raw, "name"),
		SessionID: claimString(raw, "sid"),
		Groups:    claimStrings(raw, groupsClaim),
	}
	if c.Username == "" && claimBool(raw, "email_verified") {
		// Providers that do not send preferred_username almost always send an
		// email; falling back beats failing a login the operator cannot debug.
		// Only a verified one, though: an address the provider has not checked
		// is a value the person typed, and Zoomies matches accounts by username.
		c.Username = c.Email
	}
	if c.Username == "" {
		c.Username = subject
	}
	if c.Subject == "" {
		return nil, fmt.Errorf("the identity provider sent no subject claim, so this login cannot be linked to an account")
	}
	c.Role = p.RoleFor(c.Groups)
	return c, nil
}

// RoleFor maps the identity provider's groups onto a Zoomies role. The higher
// role wins wherever somebody is in two mapped groups, and anyone in no mapped
// group is a viewer -- so misconfiguring the group names produces read-only
// access rather than accidental admins.
func (p *OIDCProvider) RoleFor(groups []string) store.Role {
	if p == nil {
		return store.RoleViewer
	}
	for _, g := range groups {
		if containsFold(p.cfg.PlatformGroups, g) {
			return store.RolePlatform
		}
	}
	for _, g := range groups {
		if containsFold(p.cfg.AdminGroups, g) {
			return store.RoleAdmin
		}
	}
	for _, g := range groups {
		if containsFold(p.cfg.OperatorGroups, g) {
			return store.RoleOperator
		}
	}
	return store.RoleViewer
}

// mapsRoles reports whether the operator configured any group mapping at all.
// When they did not, EnsureUser leaves an existing account's role alone rather
// than demoting everyone to viewer on their next login.
func (p *OIDCProvider) mapsRoles() bool {
	return p != nil && (len(p.cfg.PlatformGroups) > 0 || len(p.cfg.AdminGroups) > 0 || len(p.cfg.OperatorGroups) > 0)
}

// EnsureUser resolves a set of verified claims to a local account.
//
// It links by subject first, because that is the only identifier a provider
// promises not to reuse. Failing that it adopts an existing account with the
// same username, but only one made for single sign-on -- one with no password
// -- unless oidc.link_by_username says otherwise: with a provider whose users
// can influence their own username claim, adopting any account by name would
// let a login as "admin" inherit the local admin's role. Only then, if
// allowSignup is on, does it create one.
func (p *OIDCProvider) EnsureUser(ctx context.Context, st *store.Store, claims *Claims, allowSignup bool) (*store.User, error) {
	if claims == nil || claims.Subject == "" {
		return nil, errors.New("no verified claims to sign in with")
	}
	username, err := normalizeUsername(claims.Username)
	if err != nil {
		return nil, fmt.Errorf("the identity provider's username claim is not usable: %w", err)
	}

	u, err := st.GetUserByOIDCSubject(ctx, claims.Subject)
	switch {
	case err == nil:
		return p.sync(ctx, st, u, claims, username)
	case !errors.Is(err, store.ErrNotFound):
		return nil, fmt.Errorf("looking up the linked account: %w", err)
	}

	u, err = st.GetUserByUsername(ctx, username)
	switch {
	case err == nil:
		if u.OIDCSubject != "" && u.OIDCSubject != claims.Subject {
			return nil, fmt.Errorf("the account %q is already linked to a different single sign-on identity; an administrator must unlink or rename it", username)
		}
		// Adopting an account by username is how an administrator pre-creates
		// somebody's account and how an instance moves from local passwords to
		// SSO. It is also how a matching username at the identity provider
		// could claim a local account -- so an account that has a password of
		// its own is only adopted when the operator has asked for exactly that.
		if u.PasswordHash != "" && !p.cfg.LinkByUsername {
			return nil, fmt.Errorf("an account named %q already exists and signs in with a password, so this single sign-on identity was not linked to it; "+
				"an administrator can set oidc.link_by_username for the migration, or create an SSO account under another name", username)
		}
		u.OIDCSubject = claims.Subject
		return p.sync(ctx, st, u, claims, username)
	case !errors.Is(err, store.ErrNotFound):
		return nil, fmt.Errorf("looking up the account: %w", err)
	}

	if !allowSignup {
		return nil, fmt.Errorf("no Zoomies account exists for %q; an administrator must create it first, or turn on oidc.allow_signup to create accounts on first sign-in", username)
	}
	role := claims.Role
	if !role.Valid() {
		role = store.RoleViewer
	}
	u = &store.User{
		Username:    username,
		Email:       claims.Email,
		DisplayName: claims.Name,
		Role:        role,
		OIDCSubject: claims.Subject,
	}
	if err := st.CreateUser(ctx, u); err != nil {
		return nil, fmt.Errorf("creating the account for %q: %w", username, err)
	}
	return u, nil
}

// sync updates a linked account from the provider's claims. The identity
// provider is authoritative for the profile, and for the role too when group
// mappings are configured.
func (p *OIDCProvider) sync(ctx context.Context, st *store.Store, u *store.User, claims *Claims, username string) (*store.User, error) {
	if u.Disabled {
		return nil, ErrAccountDisabled
	}
	before := *u
	u.OIDCSubject = claims.Subject
	u.Username = username
	if claims.Email != "" {
		u.Email = claims.Email
	}
	if claims.Name != "" {
		u.DisplayName = claims.Name
	}
	// The role follows the identity provider only when the operator actually
	// mapped groups to roles, and only when the mapping produced a real role;
	// otherwise an existing account keeps the role an administrator gave it.
	if p.mapsRoles() && claims.Role.Valid() {
		u.Role = claims.Role
	}
	if before == *u {
		return u, nil
	}
	if err := st.UpdateUser(ctx, u); err != nil {
		return nil, fmt.Errorf("updating the account for %q: %w", username, err)
	}
	return u, nil
}

// ---------------------------------------------------------------------------
// State and nonce cache
// ---------------------------------------------------------------------------

// stateCache remembers the state and nonce of logins that are in flight.
//
// It is deliberately in memory: a state lives for one redirect, and losing the
// lot on restart means everyone mid-login clicks the button again. Entries are
// single-use, so a replayed callback is refused.
type stateCache struct {
	mu      sync.Mutex
	ttl     time.Duration
	now     func() time.Time
	entries map[string]stateEntry
}

type stateEntry struct {
	nonce   string
	expires time.Time
}

func newStateCache(ttl time.Duration, clock func() time.Time) *stateCache {
	if clock == nil {
		clock = time.Now
	}
	return &stateCache{ttl: ttl, now: clock, entries: map[string]stateEntry{}}
}

func (c *stateCache) put(state, nonce string) error {
	now := c.now()
	c.mu.Lock()
	defer c.mu.Unlock()
	for k, e := range c.entries {
		if now.After(e.expires) {
			delete(c.entries, k)
		}
	}
	// The sweep above has already dropped every entry a legitimate caller was
	// going to lose. If the cache is still full, the ones left are all in flight
	// and refusing this one is what keeps a stream of unauthenticated Starts
	// from growing the map without bound.
	if len(c.entries) >= maxPendingStates {
		return ErrTooManyPendingSignIns
	}
	c.entries[state] = stateEntry{nonce: nonce, expires: now.Add(c.ttl)}
	return nil
}

// firstUse records a key and reports whether it was new. A key still held
// from an earlier call is not new. Like put it refuses when the cache is full
// of live entries, which is an error and not a "seen" so a flood cannot make a
// genuine token look replayed.
func (c *stateCache) firstUse(key string) (bool, error) {
	now := c.now()
	c.mu.Lock()
	defer c.mu.Unlock()
	for k, e := range c.entries {
		if now.After(e.expires) {
			delete(c.entries, k)
		}
	}
	if _, seen := c.entries[key]; seen {
		return false, nil
	}
	if len(c.entries) >= maxPendingStates {
		return false, ErrTooManyPendingSignIns
	}
	c.entries[key] = stateEntry{expires: now.Add(c.ttl)}
	return true, nil
}

// take returns the nonce for a state and forgets it, so a state can be spent
// exactly once.
func (c *stateCache) take(state string) (string, bool) {
	if state == "" {
		return "", false
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	e, ok := c.entries[state]
	if !ok {
		return "", false
	}
	delete(c.entries, state)
	if c.now().After(e.expires) {
		return "", false
	}
	return e.nonce, true
}

// ---------------------------------------------------------------------------
// Claim helpers
// ---------------------------------------------------------------------------

// claimBool reads a boolean claim. Some providers send it as the string "true"
// rather than a JSON boolean, which is worth tolerating: the alternative is a
// login that fails for a reason nobody can see.
func claimBool(raw map[string]any, key string) bool {
	switch v := raw[key].(type) {
	case bool:
		return v
	case string:
		return strings.EqualFold(strings.TrimSpace(v), "true")
	}
	return false
}

func claimString(raw map[string]any, key string) string {
	if key == "" {
		return ""
	}
	switch v := raw[key].(type) {
	case string:
		return strings.TrimSpace(v)
	case fmt.Stringer:
		return strings.TrimSpace(v.String())
	}
	return ""
}

// claimStrings reads a claim that may be a list or, with some providers, a
// single string.
func claimStrings(raw map[string]any, key string) []string {
	switch v := raw[key].(type) {
	case []string:
		return v
	case string:
		if v == "" {
			return nil
		}
		return []string{v}
	case []any:
		out := make([]string, 0, len(v))
		for _, item := range v {
			if s, ok := item.(string); ok && s != "" {
				out = append(out, s)
			}
		}
		return out
	}
	return nil
}

func containsFold(list []string, want string) bool {
	for _, s := range list {
		if strings.EqualFold(strings.TrimSpace(s), strings.TrimSpace(want)) {
			return true
		}
	}
	return false
}

