// The runner is not the agent. A folder the agent or the daemon creates for a
// bind is theirs, and the runner -- uid 1001 in the stock images -- could not
// write to its own cache. A new folder is opened to it; one an operator made
// is left as they made it.
func TestACacheFolderIsCreatedWritableByTheRunner(t *testing.T) {
	// The runner is another uid on a Linux host; Windows has no mode bits to
	// open up, and the Docker backend runs Linux runners.
	requirePOSIX(t)
	root := t.TempDir()
	dir := filepath.Join(root, "cache", "tools", "pool-one")
	if err := ensureRunnerWritableDir(dir); err != nil {
		t.Fatalf("ensureRunnerWritableDir: %v", err)
	}
	fi, err := os.Stat(dir)
	if err != nil {
		t.Fatal(err)
	}
	if fi.Mode().Perm() != 0o777 {
		t.Errorf("new folder mode = %v, want writable by every user", fi.Mode().Perm())
	}

	mine := filepath.Join(root, "operators")
	if err := os.Mkdir(mine, 0o700); err != nil {
		t.Fatal(err)
	}
	if err := ensureRunnerWritableDir(mine); err != nil {
		t.Fatal(err)
	}
	if fi, _ := os.Stat(mine); fi.Mode().Perm() != 0o700 {
		t.Errorf("an existing folder's mode was changed to %v", fi.Mode().Perm())
	}
}

// A tool cache folder the runner cannot write to is worse than none: every
// setup action that downloads fails with EACCES instead of downloading. It is
// what a host's daemon leaves, root's, when the agent's container does not
// mount the shared folder -- and it outlives the mount being fixed, because a
// folder that exists is left as its owner made it. The runner starts without
// it, and the host says why.
func TestAToolCacheTheRunnerCannotWriteIsLeftOut(t *testing.T) {
	requirePOSIX(t)
	shared := t.TempDir()
	spec := Spec{Name: "r", PoolID: "pool_1", Cache: store.CacheConfig{Enabled: true, Tools: true, Scope: store.CacheScopePool}}
	dir, _ := toolCacheDir(spec, shared)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	b := &DockerBackend{sharedDir: shared, log: quietLogger()}

	var opts containerOptions
	b.prepareCacheDirs(spec, &opts)
	if os.Getuid() != stockRunnerUID {
		if opts.ToolCacheDir != "" {
			t.Fatalf("a folder the runner cannot write to was bound: %s", opts.ToolCacheDir)
		}
		if p := b.lastToolCacheProblem(); !strings.Contains(p, "chmod 0777") {
			t.Errorf("problem = %q, want one naming the fix", p)
		}
	}

	// Opened up, it is used again and the problem clears.
	if err := os.Chmod(dir, 0o777); err != nil {
		t.Fatal(err)
	}
	opts = containerOptions{}
	b.prepareCacheDirs(spec, &opts)
	if opts.ToolCacheDir != dir || b.lastToolCacheProblem() != "" {
		t.Errorf("dir = %q, problem = %q; want the folder bound and no problem", opts.ToolCacheDir, b.lastToolCacheProblem())
	}
}

// A create that dies before the container exists has nothing carrying the farm's
// label, so Remove and the cleanup helper never find it, and a replacement runner
// has a new name and never rebuilds over it. The failure-cleanup defer is the
// only thing that can reap it, so the farm must not be built until that defer is
// in place -- an exhausted address pool or a stalled daemon on the network call
// would otherwise leave a tree of directories and links per attempt, for ever.
func TestAFailedNetworkSetupLeavesNoToolFarmBehind(t *testing.T) {
	requirePOSIX(t)
	shared := t.TempDir()
	spec := jitSpec()
	spec.Network = "zoomies-net"
	spec.Cache = store.CacheConfig{Enabled: true, Tools: true, Scope: store.CacheScopePool}
	dir, err := toolCacheDir(spec, shared)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Join(dir, "go", "1.27.1", "x64"), 0o777); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "go", "1.27.1", "x64.complete"), nil, 0o666); err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(dir, 0o777); err != nil {
		t.Fatal(err)
	}

	f := newFakeEngine(t, map[string]http.HandlerFunc{
		"DELETE " + v + "/containers/{id}": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusNotFound, map[string]string{"message": "no such container"})
		},
		"GET " + v + "/images/{ref...}": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusOK, map[string]string{"Id": "sha256:cached"})
		},
		"GET " + v + "/networks/{name}": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusNotFound, map[string]string{"message": "no such network"})
		},
		"POST " + v + "/networks/create": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusInternalServerError, map[string]string{"message": "could not find an available, non-overlapping IPv4 address pool"})
		},
	})
	b := dockerBackendFor(t, f, DockerOptions{SharedDir: shared})

	if _, err := b.CreateWithResult(context.Background(), spec); err == nil || !strings.Contains(err.Error(), "preparing network") {
		t.Fatalf("create err = %v, want the network failure", err)
	}
	if _, err := os.Stat(toolFarmDir(shared, spec.Name)); !os.IsNotExist(err) {
		t.Fatalf("the failed create left its tool farm behind: %v", err)
	}
}

package backend

import (
	"context"
	"net/http"
	"os"
	"path/filepath"
	"sync/atomic"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

func TestCancelledContainerStartStillRemovesContainerAndScratch(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	spec := jitSpec()
	spec.WorkDir = filepath.Join(t.TempDir(), "scratch")
	var created, removed atomic.Bool
	f := newFakeEngine(t, map[string]http.HandlerFunc{
		"GET " + v + "/images/{ref...}": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, 200, map[string]any{"Id": "sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"})
		},
		"POST " + v + "/containers/create": func(w http.ResponseWriter, r *http.Request) {
			created.Store(true)
			writeJSON(w, 201, map[string]string{"Id": "c1"})
		},
		"POST " + v + "/containers/c1/start": func(w http.ResponseWriter, r *http.Request) {
			cancel()
			w.WriteHeader(500)
		},
		"GET " + v + "/containers/{id}/json": func(w http.ResponseWriter, r *http.Request) {
			if !created.Load() || r.PathValue("id") != containerName(spec.Name) {
				w.WriteHeader(404)
				return
			}
			labels := spec.Labels(time.Now())
			labels[LabelRole] = roleRunner
			labels[LabelWorkDir] = spec.WorkDir
			writeJSON(w, 200, ContainerInspect{ID: "c1", State: &ContainerState{Status: "created"}, Config: &ContainerConfig{Labels: labels}})
		},
		"DELETE " + v + "/containers/{id}": func(w http.ResponseWriter, r *http.Request) {
			if created.Load() && r.PathValue("id") == "c1" {
				removed.Store(true)
			}
			w.WriteHeader(204)
		},
	})
	b := dockerBackendFor(t, f, DockerOptions{PullPolicy: PullNever})
	if _, err := b.Create(ctx, spec); err == nil {
		t.Fatal("cancelled start succeeded")
	}
	if !removed.Load() {
		t.Fatal("expired create context prevented container removal")
	}
	if _, err := os.Stat(spec.WorkDir); !os.IsNotExist(err) {
		t.Fatalf("scratch survived failed start: %v", err)
	}
}

func TestFailedDinDPreparationCleansOnlyOwnedScratch(t *testing.T) {
	for _, preexisting := range []bool{false, true} {
		t.Run(map[bool]string{false: "owned", true: "operator directory"}[preexisting], func(t *testing.T) {
			spec := jitSpec()
			spec.DockerMode = store.DockerDinD
			spec.WorkDir = filepath.Join(t.TempDir(), "scratch")
			if preexisting {
				if err := os.Mkdir(spec.WorkDir, 0700); err != nil {
					t.Fatal(err)
				}
			}
			f := newFakeEngine(t, map[string]http.HandlerFunc{
				"GET " + v + "/images/{ref...}": func(w http.ResponseWriter, r *http.Request) {
					if r.PathValue("ref") == DefaultDinDImage+"/json" {
						w.WriteHeader(404)
						return
					}
					writeJSON(w, 200, map[string]string{"Id": "sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"})
				},
				"DELETE " + v + "/containers/{id}": func(w http.ResponseWriter, r *http.Request) { w.WriteHeader(404) },
			})
			b := dockerBackendFor(t, f, DockerOptions{PullPolicy: PullNever})
			if _, err := b.Create(context.Background(), spec); err == nil {
				t.Fatal("missing DinD image was accepted")
			}
			_, err := os.Stat(spec.WorkDir)
			if preexisting && err != nil {
				t.Fatalf("operator directory was removed: %v", err)
			}
			if !preexisting && !os.IsNotExist(err) {
				t.Fatalf("allocated scratch leaked: %v", err)
			}
		})
	}
}

func TestBuildCachePruningUsesBudgetWithoutPruningOtherResources(t *testing.T) {
	var calls int
	f := newFakeEngine(t, map[string]http.HandlerFunc{
		"POST " + v + "/build/prune": func(w http.ResponseWriter, r *http.Request) {
			calls++
			if r.URL.Query().Get("keep-storage") != "5368709120" || r.URL.Query().Get("all") != "true" {
				t.Errorf("wrong cache prune parameters: %s", r.URL.RawQuery)
			}
			writeJSON(w, 200, map[string]int64{"SpaceReclaimed": 1234})
		},
	})
	b := dockerBackendFor(t, f, DockerOptions{})
	freed, err := b.PruneBuildCache(context.Background(), 5<<30)
	if err != nil || freed != 1234 {
		t.Fatalf("prune = %d, %v", freed, err)
	}
	_, _ = b.PruneBuildCache(context.Background(), 0)
	b.fl.kind = store.BackendPodman
	_, _ = b.PruneBuildCache(context.Background(), 5<<30)
	if calls != 1 {
		t.Fatalf("disabled/Podman pruning made %d calls", calls)
	}
	if len(f.seen) != 1 {
		t.Fatalf("cleanup accessed other resources: %d calls", len(f.seen))
	}
}

func TestRunnerAndSidecarLogsAreBounded(t *testing.T) {
	for _, cfg := range []ContainerCreateRequest{buildRunnerConfig(jitSpec(), dockerFlavor(), containerOptions{}), buildDinDConfig(jitSpec(), dockerFlavor(), containerOptions{})} {
		logs := cfg.HostConfig.LogConfig
		if logs == nil || logs.Type != "json-file" || logs.Config["max-size"] != "10m" || logs.Config["max-file"] != "3" {
			t.Fatalf("unbounded container logs: %+v", logs)
		}
	}
}

package backend

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"strings"
	"time"
)

// How long a create waits for a name the daemon is still holding, and how it
// spaces its attempts.
//
// Removing a container is asynchronous on both daemons this backend speaks to:
// the delete call returns once the container is marked, and the name leaves the
// daemon's index only when the last of the container's filesystem has gone. A
// privileged docker-in-docker sidecar carries a whole nested image store and its
// anonymous volumes, so that can take seconds. Recovery that gave up inside a
// second therefore failed runners over a name whose container had already been
// removed -- and told the operator to go looking for a duplicate agent that was
// never there.
const (
	nameReleaseBudget   = 20 * time.Second
	nameReleaseFirstGap = 100 * time.Millisecond
	nameReleaseMaxGap   = 2 * time.Second
	// maxOwnedRemovals bounds the other shape of this failure. Removing a
	// container we own and finding the name taken again is not a name waiting to
	// be released: something else is creating it, which is the duplicate agent
	// the operator should be told about rather than raced against forever.
	maxOwnedRemovals = 3
)

// How long a create waits for a create of its own that the daemon has not
// finished, and how long the fact that there was one is remembered.
//
// A create the client stops waiting on is not a create the daemon stops: it
// reserves the name first and registers the container -- the point at which
// an inspect can see it -- only at the very end, and on a host running several
// nested daemons that end can be minutes away. In between, a second create of
// the name is refused with a 409 naming a container that inspects as absent,
// which is exactly what a name leaked by a duplicate agent looks like. Telling
// the two apart takes remembering that the first create was ours, and that is
// what the abandoned-create record is for.
//
// The settle window is anchored on the record rather than on the call that
// meets the 409, because the agent's busy retries re-enter this loop ten,
// twenty and forty seconds apart and must share one window: three minutes
// each would outrun the agent's create budget before the sidecar readiness
// wait and the runner's own create had had their turn. Three minutes is a
// daemon that is slow, not one that is gone; past it the create fails as busy
// so the scheduler steers the replacement to another host. The record outlives
// the window because a retry that arrives after it must still know the create
// was ours -- that is the difference between a busy host and a conflict
// finding -- and fifteen minutes is the whole of the create budget.
const (
	nameSettleBudget      = 3 * time.Minute
	abandonedCreateMemory = 15 * time.Minute
)

// recordAbandonedCreate remembers that a create of name was given up on at the
// given time, unless a live record already says so: a second timeout on the
// same name must not move the window the settle wait is measured from, or a
// daemon that keeps taking longer than the header timeout would be waited on
// for ever. Records the memory has outgrown go at the same time, so an agent
// that runs for months does not carry every name it ever gave up on.
func (b *DockerBackend) recordAbandonedCreate(name string, at time.Time) {
	b.abandonedMu.Lock()
	defer b.abandonedMu.Unlock()
	now := time.Now()
	for n, t := range b.abandoned {
		if now.Sub(t) >= abandonedCreateMemory {
			delete(b.abandoned, n)
		}
	}
	if _, ok := b.abandoned[name]; ok {
		return
	}
	if b.abandoned == nil {
		b.abandoned = make(map[string]time.Time)
	}
	b.abandoned[name] = at
}

// abandonedCreateAt reports when a create of name was given up on, if that was
// recently enough for the daemon to still be finishing it.
func (b *DockerBackend) abandonedCreateAt(name string) (time.Time, bool) {
	b.abandonedMu.Lock()
	defer b.abandonedMu.Unlock()
	at, ok := b.abandoned[name]
	if !ok || time.Since(at) >= abandonedCreateMemory {
		return time.Time{}, false
	}
	return at, true
}

// forgetAbandonedCreate drops the record for each name. A create that has
// been seen through -- answered with a 201, adopted, or removed by any path of
// ours -- leaves the daemon nothing to finish, and a name still held after that
// is the daemon unlinking, which gets the release budget rather than the settle
// window and is never reported as a create it was slow to make.
func (b *DockerBackend) forgetAbandonedCreate(names ...string) {
	b.abandonedMu.Lock()
	defer b.abandonedMu.Unlock()
	for _, n := range names {
		delete(b.abandoned, n)
	}
}

// removeOwnedForCreate frees a name before a create, when the name is held by a
// container this runner owns and is done with. It never adopts: it tidies
// before or after a create rather than standing in for one.
func (b *DockerBackend) removeOwnedForCreate(ctx context.Context, spec Spec, sidecar bool) error {
	_, _, err := b.removeOwnedOccupant(ctx, spec, sidecar, "", nil)
	return err
}

// removeOwnedOccupant never treats a name as proof of ownership. Delete by the
// inspected immutable ID so a replacement taking the name cannot be removed.
//
// occupant is the container the daemon itself named as holding the contested
// name, empty when nothing has named one. It is inspected in preference to the
// name because the two can disagree: a name can still be indexed for a container
// that an inspect by that name no longer resolves, and in that window the ID is
// the only handle left to prove ownership with.
//
// want, when given, is what the caller was about to create. An owned container
// that passes every ownership check, was never started and matches it is handed
// back to be started instead of removed and made again: it is the create this
// agent stopped waiting on, finished late by a slow daemon, and removing it
// would only ask that daemon to make the same thing a second time. It reports
// the adopted container's ID, or whether a container was removed.
func (b *DockerBackend) removeOwnedOccupant(ctx context.Context, spec Spec, sidecar bool, occupant string, want *ContainerCreateRequest) (string, bool, error) {
	name := containerName(spec.Name)
	role := roleRunner
	if sidecar {
		name = dindName(name)
		role = roleDinD
	}
	ref := name
	if occupant != "" {
		ref = occupant
	}
	insp, err := b.api.ContainerInspect(ctx, ref)
	if errors.Is(err, ErrNotFound) {
		return "", false, nil
	}
	if err != nil {
		return "", false, err
	}
	refuse := func(reason string) error {
		return tagged{kind: ErrContainerConflict, err: fmt.Errorf("backend: container name %s is occupied; %s; existing container retained", name, reason)}
	}
	if insp.ID == "" || insp.Config == nil || spec.RunnerID == "" || spec.PoolID == "" {
		return "", false, refuse("ownership could not be verified")
	}
	// An ID came from the daemon's own conflict reply, so it must still answer to
	// the name we are contesting. If it has been renamed since, whatever holds the
	// name now is a different container and this one is not ours to remove.
	if occupant != "" && strings.TrimPrefix(insp.Name, "/") != name {
		return "", false, nil
	}
	labels := insp.Config.Labels
	if labels[LabelManaged] != "true" || labels[LabelRunnerID] != spec.RunnerID || labels[LabelPoolID] != spec.PoolID || labels[LabelRole] != role {
		return "", false, refuse("ownership labels do not match this runner, pool and role")
	}
	expectedName := spec.Name
	if sidecar {
		expectedName = dindName(spec.Name)
	}
	if labels[LabelName] != expectedName || (sidecar && labels[LabelDinDFor] != spec.Name) {
		return "", false, refuse("runner name labels do not match")
	}
	if sidecar {
		// A running sidecar from a lost create response is reclaimable only when
		// there is no parent workload. Never disrupt a runner already using it.
		if _, err := b.api.ContainerInspect(ctx, containerName(spec.Name)); err == nil {
			return "", false, refuse("its parent runner still exists")
		} else if !errors.Is(err, ErrNotFound) {
			return "", false, err
		}
	} else if insp.State == nil || insp.State.Running || insp.State.Restarting || insp.State.Paused {
		return "", false, refuse("the runner may still be active")
	}
	if want != nil && adoptable(insp, *want) {
		return insp.ID, false, nil
	}
	if err := b.api.ContainerRemove(ctx, insp.ID, true); err != nil && !errors.Is(err, ErrNotFound) {
		return "", false, err
	}
	// The record is what says a still-held name is a create of ours the daemon
	// has not finished. Removing the container finishes it: whatever holds the
	// name after this is the daemon unlinking, which is a different wait.
	b.forgetAbandonedCreate(name)
	b.log.Info("removed a stale owned container before creation", "container", insp.ID, "runner", spec.RunnerID, "role", role)
	return "", true, nil
}

// adoptable reports whether an owned container can stand in for the one the
// caller was about to create. It must have been created and never started -- a
// runner that ran may have taken a job, and a sidecar that ran has a daemon's
// state a fresh one would not -- from the same image, and where either side
// binds the container into another's network namespace the two must name the
// same one, because a runner bound to a sidecar that has since gone would start
// into a namespace that is not there. That binding is the one network spelling
// this backend chose and both daemons store verbatim. Every other pair is left
// alone: the daemon rewrites those -- an empty request comes back as "default"
// or "bridge", Podman reports "bridge" for a named network -- and the labels
// have already proved whose container it is. A Podman-normalised image name
// fails the comparison and is removed and recreated, which costs a create and
// never a job.
func adoptable(insp *ContainerInspect, want ContainerCreateRequest) bool {
	st := insp.State
	if st == nil || st.Status != "created" || st.Running || st.Restarting || st.Paused {
		return false
	}
	if insp.Config == nil || insp.Config.Image != want.Image || insp.HostConfig == nil {
		return false
	}
	var mode string
	if want.HostConfig != nil {
		mode = want.HostConfig.NetworkMode
	}
	got := insp.HostConfig.NetworkMode
	if strings.HasPrefix(mode, "container:") || strings.HasPrefix(got, "container:") {
		return got == mode
	}
	return true
}

// createWithConflictRecovery resolves the late-create race: a timed-out daemon
// request may acquire its name after the preflight inspection. Credentials are
// not replayed into an existing runner; only an inactive owned runner or an
// owned sidecar without a parent may be removed and freshly created.
//
// A create the daemon did not answer in time is not a create that failed, so it
// is asked again once, and the daemon's own reply says what became of it: a
// 201 means the first never landed, a 409 means it did. A 409 naming a
// container nobody can inspect is then a create the daemon has not finished
// registering, a removal it has not finished, or a name it has leaked, and
// which of those it is decides how long to wait and how to fail: a name with a
// create of ours on record gets the settle window measured from that record
// and fails as busy, so the agent retries and the scheduler steers the
// replacement elsewhere; a name with none gets the release budget and fails as
// the conflict finding it always was. A container that becomes inspectable is
// judged by its labels as before, with one addition -- one that is ours, was
// never started and matches what this call would make is started rather than
// removed and made again. A name held by a container this runner must not
// touch still fails immediately: waiting on somebody else's workload only
// delays the finding an operator has to act on.
func (b *DockerBackend) createWithConflictRecovery(ctx context.Context, spec Spec, cfg ContainerCreateRequest, sidecar bool) (string, error) {
	name := containerName(spec.Name)
	role := roleRunner
	if sidecar {
		name = dindName(name)
		role = roleDinD
	}
	var (
		started  = time.Now()
		released = started
		gap      = nameReleaseFirstGap
		occupant string
		removals int
		reasked  bool
		// refused is the last 409, kept so the daemon's own words survive in
		// whatever this returns.
		refused error
	)
	// deadline is read afresh each time it is needed, because the evidence it
	// comes from moves: a re-ask writes the record and a removal clears it.
	deadline := func() time.Time {
		d := released.Add(b.nameRelease)
		if at, ok := b.abandonedCreateAt(name); ok {
			d = at.Add(b.nameSettle)
		}
		// Waiting past either only produces a runner the agent will refuse to
		// start.
		for _, limit := range []time.Time{spec.StartBefore, spec.Credentials.ExpiresAt} {
			if !limit.IsZero() && limit.Before(d) {
				d = limit
			}
		}
		return d
	}
	wording := func() string {
		waited := time.Since(started)
		if at, ok := b.abandonedCreateAt(name); ok {
			return slowDaemonReport(name, at, waited)
		}
		return conflictReport(name, occupant, removals, waited)
	}
	// exhausted is the exit when the budget runs out. The fault kind is decided
	// by the evidence, because the kind is what acts on it: a live record says
	// the name is held by a create of ours the daemon is too slow to finish,
	// which the agent retries and the scheduler steers away from; anything else
	// -- a settling name with no create of ours behind it, a name still held
	// after our own removal, a name taken again as fast as we free it -- is the
	// conflict finding an operator has to look at.
	exhausted := func() (string, error) {
		failure := fmt.Errorf("backend: %s: %w", wording(), refused)
		if _, ok := b.abandonedCreateAt(name); ok {
			return "", busyErr(failure)
		}
		return "", tagged{kind: ErrContainerConflict, err: failure}
	}
	// ended is the exit for a context that ran out while the name was being
	// waited on. A deadline was spent waiting on the daemon, so it is busy, with
	// the same wording the budget exit would have used; a cancellation is the
	// caller giving up, which is not a finding about the name at all.
	ended := func() (string, error) {
		if errors.Is(ctx.Err(), context.DeadlineExceeded) {
			return "", busyErr(fmt.Errorf("backend: %s: %w (%w)", wording(), refused, ctx.Err()))
		}
		return "", ctx.Err()
	}
	for {
		id, err := b.api.ContainerCreate(ctx, name, cfg)
		if err == nil {
			b.forgetAbandonedCreate(name)
			return id, nil
		}
		var apiErr *APIError
		if !errors.As(err, &apiErr) || apiErr.Status != http.StatusConflict {
			// The daemon does not stop a create because the client stopped
			// waiting for it, so a request that timed out is asked once more:
			// the reply to that is what says whether the first landed. A second
			// timeout goes back unchanged, and the agent's busy retry re-enters
			// here with the record still standing. A context that has ended is
			// not the daemon being slow, whatever the transport called it.
			if errors.Is(err, ErrDaemonBusy) && ctx.Err() == nil {
				// Every timeout is a create the daemon may still finish, so
				// every one is recorded; the record refuses to move a live
				// entry, so a second timeout does not widen the window.
				b.recordAbandonedCreate(name, time.Now())
			}
			if errors.Is(err, ErrDaemonBusy) && ctx.Err() == nil && !reasked {
				reasked = true
				b.log.Warn("the daemon did not answer a create in time; asking it again, because a create the client stopped waiting on is one the daemon may still finish",
					"container", name, "runner", spec.RunnerID, "role", role, "error", err)
				continue
			}
			if refused != nil && ctx.Err() != nil {
				return ended()
			}
			return "", err
		}
		refused = err
		if named := conflictOccupant(apiErr.Message); named != "" {
			occupant = named
		}
		adopted, removed, rerr := b.removeOwnedOccupant(ctx, spec, sidecar, occupant, &cfg)
		switch {
		case adopted != "":
			b.forgetAbandonedCreate(name)
			b.log.Info("adopted a container the daemon finished creating after this agent stopped waiting for it",
				"container", shortID(adopted), "runner", spec.RunnerID, "role", role)
			return adopted, nil
		case ctx.Err() != nil:
			return ended()
		case rerr != nil && errors.Is(rerr, ErrDaemonBusy):
			// An inspect or remove the daemon did not answer is the slowness
			// this loop exists to wait out, not a reason to call the name
			// contested: nothing has been learned about who holds it. A daemon
			// answer that cannot be verified -- a 500, a body with no labels --
			// is a different thing and still fails below.
			b.log.Warn("the daemon did not answer in time while the holder of a container name was being checked; waiting rather than treating the name as contested",
				"container", name, "runner", spec.RunnerID, "role", role, "error", rerr)
			if !time.Now().Before(deadline()) {
				return "", fmt.Errorf("backend: could not establish who holds container name %s: %w", name, rerr)
			}
		case rerr != nil:
			// Preserve conflicting containers even when ownership inspection failed.
			return "", tagged{kind: ErrContainerConflict, err: fmt.Errorf("backend: could not safely recover container name %s: %w", name, rerr)}
		case removed:
			removals++
			if removals >= maxOwnedRemovals {
				// The removal just cleared the record, so this is always the
				// conflict wording.
				return exhausted()
			}
			// The late-create race is resolved the moment its container has gone,
			// so retry at once and start the release budget from here: what was
			// spent proving ownership is not what the daemon has had to unlink in.
			released, gap = time.Now(), nameReleaseFirstGap
			continue
		default:
			if !time.Now().Before(deadline()) {
				return exhausted()
			}
		}
		timer := time.NewTimer(gap)
		select {
		case <-ctx.Done():
			timer.Stop()
			return ended()
		case <-timer.C:
		}
		if gap *= 2; gap > nameReleaseMaxGap {
			gap = nameReleaseMaxGap
		}
	}
}

// conflictReport says which conflict an operator is looking at, because the
// three have different answers: a name the daemon has not finished releasing
// needs nothing but time, a name taken again after we removed our own container
// is a second agent driving this daemon, and a name held by a container we can
// still point at is one they can go and inspect. A name nobody can inspect only
// reaches here when no create of ours is on record for it -- a create the
// daemon was slow to finish has slowDaemonReport's wording and fails as busy --
// so the duplicate-agent advice is given only when a duplicate agent is what
// the evidence leaves.
func conflictReport(name, occupant string, removals int, waited time.Duration) string {
	spent := waited.Round(100 * time.Millisecond)
	switch {
	case removals >= maxOwnedRemovals:
		return fmt.Sprintf("container name %s was taken again after removing the container holding it %d times; something else is creating containers with this runner's name -- check for duplicate agents sharing this daemon", name, removals)
	case removals > 0:
		return fmt.Sprintf("container name %s was still held %s after the container holding it was removed; the daemon has not finished releasing the name, and the host may be too busy to unlink it", name, spent)
	case occupant != "":
		return fmt.Sprintf("container name %s was still held by container %s after %s; inspect that container's Zoomies ownership labels, and check for duplicate agents sharing this daemon", name, shortID(occupant), spent)
	default:
		return fmt.Sprintf("container name %s remained occupied for %s, but no container of that name could be inspected; check for duplicate agents sharing this daemon", name, spent)
	}
}

// slowDaemonReport is the exit for a name held by a create of our own that the
// daemon has not finished. It names nothing to inspect and no duplicate agent,
// because there is neither: the container the 409 names is the one this agent
// asked for, and the only thing wrong is how long the host is taking to make
// it. A replacement runner always gets a fresh name, so a name the daemon
// eventually leaks costs one runner row and not the job.
func slowDaemonReport(name string, abandonedAt time.Time, waited time.Duration) string {
	ago := time.Since(abandonedAt).Round(100 * time.Millisecond)
	return fmt.Sprintf("container name %s was reserved to a create this agent gave up waiting on %s ago, and the daemon had still not finished it after %s; the host is too slow to create containers -- look at its load, not for a duplicate agent", name, ago, waited.Round(100*time.Millisecond))
}

// conflictOccupant pulls the occupying container's ID out of a 409 reply. Both
// daemons name it -- Docker as `by container "<id>"`, Podman as `by <id>` --
// and it is the one handle that survives a name whose container an inspect by
// that name no longer resolves. It only says which container to check: whether
// that container may be removed is still decided by its ownership labels.
func conflictOccupant(message string) string {
	const marker = "already in use by"
	i := strings.Index(message, marker)
	if i < 0 {
		return ""
	}
	for _, field := range strings.Fields(message[i+len(marker):]) {
		if id := strings.Trim(field, `"'.,:`); isHexID(id) {
			return id
		}
	}
	return ""
}

// isHexID accepts what a daemon prints for a container ID -- the full 64
// characters or a truncated form -- and nothing that merely looks like a word.
func isHexID(s string) bool {
	if len(s) < 12 || len(s) > 64 {
		return false
	}
	for _, r := range s {
		if !(r >= '0' && r <= '9' || r >= 'a' && r <= 'f' || r >= 'A' && r <= 'F') {
			return false
		}
	}
	return true
}

package backend

// Autodetection for container sockets.
//
// The ordering in here encodes a policy decision rather than a preference:
// Zoomies looks for a rootless daemon first and only falls back to the system
// one. A rootless socket means a compromised job gets the agent's user account,
// not the machine.

import (
	"errors"
	"fmt"
	"io/fs"
	"net"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"syscall"
)

// hostEnv is the small slice of the world autodetection depends on, injected so
// the ordering can be tested without a container runtime on the machine.
type hostEnv struct {
	getenv func(string) string
	uid    int
	// exists reports whether a path is present on the host.
	exists func(string) bool
}

func realHostEnv() hostEnv {
	return hostEnv{
		getenv: os.Getenv,
		uid:    os.Geteuid(),
		exists: func(p string) bool {
			_, err := os.Stat(p)
			return err == nil
		},
	}
}

// DetectDockerHost returns Docker endpoints to try, most preferred first.
//
// DOCKER_HOST always comes first when set, because an operator who configured
// it must see the error from their own choice rather than a silent fallback.
// After that come the rootless sockets, then the system socket.
//
// Only endpoints that exist are returned. When none do, the full candidate list
// comes back anyway so that the caller can name what it looked for.
func DetectDockerHost() []string { return detectHost(realHostEnv(), dockerCandidates) }

// DetectPodmanHost returns Podman endpoints to try, most preferred first.
// Podman is rootless by default, so its user socket is the normal case and the
// system socket the exception.
func DetectPodmanHost() []string { return detectHost(realHostEnv(), podmanCandidates) }

func detectHost(e hostEnv, candidates func(hostEnv) []string) []string {
	all := candidates(e)
	var live []string
	for _, c := range all {
		// A non-unix endpoint cannot be stat'd, and an explicitly configured one
		// is never filtered out.
		if !strings.HasPrefix(c, "unix://") || e.exists(strings.TrimPrefix(c, "unix://")) {
			live = append(live, c)
		}
	}
	if len(live) > 0 {
		return live
	}
	return all
}

func dockerCandidates(e hostEnv) []string {
	var out []string
	add := func(s string) {
		if s == "" {
			return
		}
		for _, have := range out {
			if have == s {
				return
			}
		}
		out = append(out, s)
	}

	add(strings.TrimSpace(e.getenv("DOCKER_HOST")))
	if xdg := strings.TrimSpace(e.getenv("XDG_RUNTIME_DIR")); xdg != "" {
		add("unix://" + filepath.Join(xdg, "docker.sock"))
	}
	add("unix://" + filepath.Join("/run/user", strconv.Itoa(e.uid), "docker.sock"))
	if home := strings.TrimSpace(e.getenv("HOME")); home != "" {
		// Docker Desktop on macOS puts a user-owned socket here.
		add("unix://" + filepath.Join(home, ".docker/run/docker.sock"))
	}
	add("unix:///var/run/docker.sock")
	return out
}

func podmanCandidates(e hostEnv) []string {
	var out []string
	add := func(s string) {
		if s == "" {
			return
		}
		for _, have := range out {
			if have == s {
				return
			}
		}
		out = append(out, s)
	}

	add(strings.TrimSpace(e.getenv("CONTAINER_HOST")))
	if xdg := strings.TrimSpace(e.getenv("XDG_RUNTIME_DIR")); xdg != "" {
		add("unix://" + filepath.Join(xdg, "podman/podman.sock"))
	}
	add("unix://" + filepath.Join("/run/user", strconv.Itoa(e.uid), "podman/podman.sock"))
	add("unix:///run/podman/podman.sock")
	return out
}

// IsRootless reports whether a daemon described by info runs without root.
//
// Docker advertises it in SecurityOptions as "name=rootless"; Podman's
// compatibility endpoint sets the Rootless field. A root directory under
// /run/user or in a home directory is the third tell, for daemons that report
// neither.
func IsRootless(info SystemInfo) bool {
	if info.Rootless {
		return true
	}
	for _, o := range info.SecurityOptions {
		if strings.Contains(strings.ToLower(o), "rootless") {
			return true
		}
	}
	return IsRootlessEndpoint(info.DockerRootDir)
}

// IsRootlessEndpoint reports whether a socket path or data directory belongs to
// a per-user daemon. It is the check that works before /info has been read.
func IsRootlessEndpoint(path string) bool {
	p := strings.TrimPrefix(path, "unix://")
	if p == "" {
		return false
	}
	if strings.HasPrefix(p, "/run/user/") || strings.HasPrefix(p, "/var/run/user/") {
		return true
	}
	home := strings.TrimSpace(os.Getenv("HOME"))
	return home != "" && home != "/" && home != "/root" && strings.HasPrefix(p, home+string(filepath.Separator))
}

// HasSystemd reports whether this host is running systemd, which decides
// whether the installer can offer to write a unit file.
func HasSystemd() bool {
	fi, err := os.Stat("/run/systemd/system")
	return err == nil && fi.IsDir()
}

// CanUseDockerSocket explains, in terms the operator can act on, why a socket
// cannot be used. It returns nil when the socket accepts a connection.
//
// It speaks of "Docker or Podman" because a caller here has not chosen a
// backend yet. A probe that already knows which daemon it is checking --
// docker.go's unreachableDetail -- calls canUseSocket directly instead, so
// its message never suggests installing or starting the other one.
func CanUseDockerSocket(path string) error {
	return canUseSocket(path, "Docker or Podman", "systemctl --user start docker, or systemctl start docker")
}

// canUseSocket is CanUseDockerSocket's implementation, named for one specific
// daemon so its remedy -- install it, this is the command that starts it --
// stays true to what actually failed.
//
// This exists because the three failures look identical in a bare dial error
// and have three completely different remedies.
func canUseSocket(path, name, startHint string) error {
	p := strings.TrimSpace(path)
	switch {
	case p == "":
		return fmt.Errorf("backend: no %s socket configured; set agent.docker_host or install %s", name, name)
	case strings.HasPrefix(p, "tcp://"), strings.HasPrefix(p, "http://"), strings.HasPrefix(p, "https://"):
		// A TCP endpoint has nothing to stat; reachability is the Ping's job.
		return nil
	}
	p = strings.TrimPrefix(p, "unix://")

	fi, err := os.Stat(p)
	switch {
	case errors.Is(err, fs.ErrNotExist):
		return fmt.Errorf("%w: no socket at %s; install %s, start it (`%s`), or point agent.docker_host at the right socket", ErrUnavailable, p, name, startHint)
	case errors.Is(err, fs.ErrPermission):
		return fmt.Errorf("%w: %s", ErrUnavailable, deniedDetail(realIdentity(), p))
	case err != nil:
		return fmt.Errorf("%w: cannot look at %s: %w", ErrUnavailable, p, err)
	case fi.Mode()&fs.ModeSocket == 0:
		return fmt.Errorf("%w: %s is not a socket; agent.docker_host must point at a Docker or Podman API socket", ErrUnavailable, p)
	}

	conn, err := net.DialTimeout("unix", p, dialTimeout)
	if err == nil {
		_ = conn.Close()
		return nil
	}
	switch {
	case errors.Is(err, syscall.EACCES), errors.Is(err, syscall.EPERM), errors.Is(err, fs.ErrPermission):
		return fmt.Errorf("%w: %s", ErrUnavailable, deniedDetail(realIdentity(), p))
	case errors.Is(err, syscall.ECONNREFUSED):
		return fmt.Errorf("%w: %s exists but nothing is listening; start it with `%s`", ErrUnavailable, p, startHint)
	default:
		return fmt.Errorf("%w: cannot connect to %s: %w", ErrUnavailable, p, err)
	}
}

// pickEndpoint chooses the first candidate that answers a connection, falling
// back to the first candidate so that a later Probe reports a concrete failure
// against a concrete socket rather than against nothing at all.
func pickEndpoint(candidates []string, fallback string) string {
	for _, c := range candidates {
		if CanUseDockerSocket(c) == nil {
			return c
		}
	}
	if len(candidates) > 0 {
		return candidates[0]
	}
	return fallback
}

package backend

import (
	"errors"
	"net"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"testing"
)

// fakeEnv builds a hostEnv from a map of variables and a set of paths that
// exist, so the ordering can be checked on a machine with no container runtime.
func fakeEnv(vars map[string]string, uid int, present ...string) hostEnv {
	return hostEnv{
		getenv: func(k string) string { return vars[k] },
		uid:    uid,
		exists: func(p string) bool { return slices.Contains(present, p) },
	}
}

func TestDockerCandidateOrder(t *testing.T) {
	requirePOSIX(t)
	e := fakeEnv(map[string]string{
		"XDG_RUNTIME_DIR": "/run/user/1000",
		"HOME":            "/home/ops",
	}, 1000)

	got := dockerCandidates(e)
	want := []string{
		"unix:///run/user/1000/docker.sock",
		"unix:///home/ops/.docker/run/docker.sock",
		"unix:///var/run/docker.sock",
	}
	if !slices.Equal(got, want) {
		t.Fatalf("got %v, want %v", got, want)
	}
	// The point of the ordering: the system socket is the last resort.
	if got[len(got)-1] != "unix:///var/run/docker.sock" {
		t.Fatal("the rootful socket must come last")
	}
}

func TestDockerCandidatePrefersExplicitHost(t *testing.T) {
	e := fakeEnv(map[string]string{
		"DOCKER_HOST":     "tcp://10.0.0.5:2375",
		"XDG_RUNTIME_DIR": "/run/user/1000",
	}, 1000)

	got := dockerCandidates(e)
	if got[0] != "tcp://10.0.0.5:2375" {
		t.Fatalf("DOCKER_HOST must win, got %v", got)
	}
}

func TestDockerCandidateDeduplicates(t *testing.T) {
	// XDG_RUNTIME_DIR normally is /run/user/<uid>, which would otherwise be
	// offered twice.
	e := fakeEnv(map[string]string{"XDG_RUNTIME_DIR": "/run/user/1000"}, 1000)
	got := dockerCandidates(e)
	seen := map[string]bool{}
	for _, c := range got {
		if seen[c] {
			t.Fatalf("duplicate candidate %s in %v", c, got)
		}
		seen[c] = true
	}
}

func TestPodmanCandidateOrder(t *testing.T) {
	requirePOSIX(t)
	e := fakeEnv(map[string]string{"XDG_RUNTIME_DIR": "/run/user/1000"}, 1000)
	got := podmanCandidates(e)
	want := []string{
		"unix:///run/user/1000/podman/podman.sock",
		"unix:///run/podman/podman.sock",
	}
	if !slices.Equal(got, want) {
		t.Fatalf("got %v, want %v", got, want)
	}

	e = fakeEnv(map[string]string{"CONTAINER_HOST": "unix:///tmp/podman.sock"}, 1000)
	if got := podmanCandidates(e); got[0] != "unix:///tmp/podman.sock" {
		t.Fatalf("CONTAINER_HOST must win, got %v", got)
	}
}

func TestDetectHostFiltersToWhatExists(t *testing.T) {
	requirePOSIX(t)
	t.Run("only existing sockets", func(t *testing.T) {
		e := fakeEnv(map[string]string{"XDG_RUNTIME_DIR": "/run/user/1000"}, 1000, "/var/run/docker.sock")
		got := detectHost(e, dockerCandidates)
		if !slices.Equal(got, []string{"unix:///var/run/docker.sock"}) {
			t.Fatalf("got %v", got)
		}
	})

	t.Run("rootless first when both exist", func(t *testing.T) {
		e := fakeEnv(map[string]string{"XDG_RUNTIME_DIR": "/run/user/1000"}, 1000,
			"/var/run/docker.sock", "/run/user/1000/docker.sock")
		got := detectHost(e, dockerCandidates)
		if got[0] != "unix:///run/user/1000/docker.sock" {
			t.Fatalf("the rootless socket must be preferred, got %v", got)
		}
	})

	t.Run("nothing exists still names the candidates", func(t *testing.T) {
		e := fakeEnv(map[string]string{"XDG_RUNTIME_DIR": "/run/user/1000"}, 1000)
		got := detectHost(e, dockerCandidates)
		if len(got) != len(dockerCandidates(e)) {
			t.Fatalf("got %v, want every candidate so the error can name them", got)
		}
	})

	t.Run("a tcp endpoint is never filtered out", func(t *testing.T) {
		e := fakeEnv(map[string]string{"DOCKER_HOST": "tcp://10.0.0.5:2375"}, 1000)
		got := detectHost(e, dockerCandidates)
		if got[0] != "tcp://10.0.0.5:2375" {
			t.Fatalf("got %v", got)
		}
	})
}

func TestIsRootless(t *testing.T) {
	cases := []struct {
		name string
		info SystemInfo
		want bool
	}{
		{"docker rootless security option", SystemInfo{SecurityOptions: []string{"name=seccomp,profile=builtin", "name=rootless"}}, true},
		{"podman flag", SystemInfo{Rootless: true}, true},
		{"root dir under /run/user", SystemInfo{DockerRootDir: "/run/user/1000/docker"}, true},
		{"rootful", SystemInfo{SecurityOptions: []string{"name=seccomp,profile=builtin"}, DockerRootDir: "/var/lib/docker"}, false},
		{"empty", SystemInfo{}, false},
	}
	for _, c := range cases {
		if got := IsRootless(c.info); got != c.want {
			t.Errorf("%s: got %v, want %v", c.name, got, c.want)
		}
	}
}

func TestIsRootlessEndpoint(t *testing.T) {
	if !IsRootlessEndpoint("unix:///run/user/1000/podman/podman.sock") {
		t.Error("a /run/user socket is rootless")
	}
	if IsRootlessEndpoint("/var/run/docker.sock") {
		t.Error("the system socket is not rootless")
	}
	if IsRootlessEndpoint("") {
		t.Error("an empty path is not rootless")
	}
}

func TestCanUseDockerSocket(t *testing.T) {
	requirePOSIX(t)
	dir := t.TempDir()

	t.Run("missing", func(t *testing.T) {
		err := CanUseDockerSocket(filepath.Join(dir, "absent.sock"))
		if !errors.Is(err, ErrUnavailable) {
			t.Fatalf("got %v", err)
		}
		if !strings.Contains(err.Error(), "no socket at") || !strings.Contains(err.Error(), "absent.sock") {
			t.Fatalf("the message must name the path and the fix: %v", err)
		}
	})

	t.Run("not a socket", func(t *testing.T) {
		path := filepath.Join(dir, "regular-file")
		if err := os.WriteFile(path, []byte("x"), 0o600); err != nil {
			t.Fatal(err)
		}
		err := CanUseDockerSocket(path)
		if err == nil || !strings.Contains(err.Error(), "is not a socket") {
			t.Fatalf("got %v", err)
		}
	})

	t.Run("listening", func(t *testing.T) {
		path := filepath.Join(dir, "live.sock")
		l, err := net.Listen("unix", path)
		if err != nil {
			t.Skipf("unix sockets unavailable here: %v", err)
		}
		defer l.Close()
		if err := CanUseDockerSocket(path); err != nil {
			t.Fatalf("a listening socket must be usable: %v", err)
		}
		// The unix:// form must work too, since that is what config carries.
		if err := CanUseDockerSocket("unix://" + path); err != nil {
			t.Fatalf("unix:// form rejected: %v", err)
		}
	})

	t.Run("nothing listening", func(t *testing.T) {
		path := filepath.Join(dir, "dead.sock")
		l, err := net.Listen("unix", path)
		if err != nil {
			t.Skipf("unix sockets unavailable here: %v", err)
		}
		// Closing the listener without unlinking leaves the socket file behind,
		// which is exactly the state a crashed daemon leaves.
		addr := l.Addr().(*net.UnixAddr)
		l.(*net.UnixListener).SetUnlinkOnClose(false)
		_ = l.Close()
		if _, err := os.Stat(addr.Name); err != nil {
			t.Skipf("socket file did not survive close: %v", err)
		}
		err = CanUseDockerSocket(path)
		if err == nil || !strings.Contains(err.Error(), "nothing is listening") {
			t.Fatalf("got %v", err)
		}
	})

	t.Run("empty", func(t *testing.T) {
		if err := CanUseDockerSocket(""); err == nil {
			t.Fatal("an empty path must be an error")
		}
	})

	t.Run("tcp is left to the ping", func(t *testing.T) {
		if err := CanUseDockerSocket("tcp://10.0.0.5:2375"); err != nil {
			t.Fatalf("got %v", err)
		}
	})
}

func TestCanUseDockerSocketPermissionDenied(t *testing.T) {
	requirePOSIX(t)
	if os.Geteuid() == 0 {
		t.Skip("root bypasses filesystem permissions, so this check cannot fail here")
	}
	dir := t.TempDir()
	sub := filepath.Join(dir, "locked")
	if err := os.Mkdir(sub, 0o700); err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(sub, "docker.sock")
	l, err := net.Listen("unix", path)
	if err != nil {
		t.Skipf("unix sockets unavailable here: %v", err)
	}
	defer l.Close()
	if err := os.Chmod(sub, 0o000); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.Chmod(sub, 0o700) })

	err = CanUseDockerSocket(path)
	if !errors.Is(err, ErrUnavailable) {
		t.Fatalf("a permission failure must report an unavailable backend, got %v", err)
	}
	// This integration test runs on both bare hosts and container runners.
	// Their remedies differ (usermod versus --group-add); permissions_test.go
	// verifies each remedy using explicit identities, independently of CI's host.
	for _, want := range []string{"permission denied", path} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("a permission failure must identify %q, got %v", want, err)
		}
	}
}

func TestPickEndpoint(t *testing.T) {
	dir := t.TempDir()
	live := filepath.Join(dir, "live.sock")
	l, err := net.Listen("unix", live)
	if err != nil {
		t.Skipf("unix sockets unavailable here: %v", err)
	}
	defer l.Close()

	got := pickEndpoint([]string{filepath.Join(dir, "absent.sock"), live}, "/var/run/docker.sock")
	if got != live {
		t.Fatalf("got %q, want the socket that answers", got)
	}

	// With nothing reachable, the first candidate is returned so that Probe
	// reports a concrete failure rather than an empty one.
	got = pickEndpoint([]string{"unix:///a.sock", "unix:///b.sock"}, "/var/run/docker.sock")
	if got != "unix:///a.sock" {
		t.Fatalf("got %q", got)
	}
	if got := pickEndpoint(nil, "/var/run/docker.sock"); got != "/var/run/docker.sock" {
		t.Fatalf("got %q", got)
	}
}

package backend

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"strings"
	"sync/atomic"
	"testing"
)

// The exec calls are how the agent asks a runner's own container a question
// the host cannot answer from outside: how full a folder it mounted in memory
// is. They run a command to its end and hand back what it printed and how it
// ended, and they have to keep two things straight that a plain log reader
// does not: which stream a line came on, and what the daemon says when the
// command could not be started at all.
func TestACommandRunInAContainerReturnsWhatItPrintedAndHowItEnded(t *testing.T) {
	var created struct {
		AttachStdin  bool
		AttachStdout bool
		AttachStderr bool
		Tty          bool
		Cmd          []string
		Env          []string
	}
	var started struct {
		Detach bool
		Tty    bool
	}
	f := newFakeEngine(t, map[string]http.HandlerFunc{
		"POST " + v + "/containers/c1/exec": func(w http.ResponseWriter, r *http.Request) {
			_ = json.NewDecoder(r.Body).Decode(&created)
			writeJSON(w, http.StatusCreated, map[string]string{"Id": "e1"})
		},
		"POST " + v + "/exec/e1/start": func(w http.ResponseWriter, r *http.Request) {
			_ = json.NewDecoder(r.Body).Decode(&started)
			w.Header().Set("Content-Type", "application/vnd.docker.raw-stream")
			_, _ = w.Write(append(frame(1, "out\n"), frame(2, "warning\n")...))
		},
		"GET " + v + "/exec/e1/json": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusOK, map[string]any{"Running": false, "ExitCode": 3})
		},
	})

	got, err := f.client(t).ContainerExec(context.Background(), "c1", []string{"df", "-P"}, []string{"LC_ALL=C"})
	if err != nil {
		t.Fatalf("exec: %v", err)
	}
	if got.Stdout != "out\n" || got.Stderr != "warning\n" || got.ExitCode != 3 {
		t.Fatalf("result = %+v, want the two streams kept apart and the exit code 3", got)
	}
	if created.AttachStdin || !created.AttachStdout || !created.AttachStderr || created.Tty {
		t.Fatalf("create asked for %+v: output on both streams, no input, no terminal", created)
	}
	if strings.Join(created.Cmd, " ") != "df -P" || strings.Join(created.Env, " ") != "LC_ALL=C" {
		t.Fatalf("create sent cmd %v env %v", created.Cmd, created.Env)
	}
	if started.Detach || started.Tty {
		t.Fatalf("start asked for %+v; it has to stay attached to read the output, without a terminal", started)
	}
}

// The stream ends when the command's output does, which can be a moment before
// the daemon has recorded that the command exited. Read at once, the exit code
// is the zero of a command still running, and a df that failed would be read
// as one that worked.
func TestTheExitCodeIsReadOnceTheDaemonSaysTheCommandHasEnded(t *testing.T) {
	var polls atomic.Int32
	f := newFakeEngine(t, map[string]http.HandlerFunc{
		"POST " + v + "/containers/c1/exec": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusCreated, map[string]string{"Id": "e1"})
		},
		"POST " + v + "/exec/e1/start": func(w http.ResponseWriter, r *http.Request) {
			_, _ = w.Write(frame(1, "x\n"))
		},
		"GET " + v + "/exec/e1/json": func(w http.ResponseWriter, r *http.Request) {
			if polls.Add(1) < 3 {
				writeJSON(w, http.StatusOK, map[string]any{"Running": true, "ExitCode": 0})
				return
			}
			writeJSON(w, http.StatusOK, map[string]any{"Running": false, "ExitCode": 127})
		},
	})
	got, err := f.client(t).ContainerExec(context.Background(), "c1", []string{"df"}, nil)
	if err != nil || got.ExitCode != 127 {
		t.Fatalf("result = %+v, err = %v; want the exit code of the finished command, 127", got, err)
	}
}

// When the command cannot be started the daemon has already taken the
// connection over, so it cannot send an error status. It writes the reason as
// plain text on the stream instead, which is no frame at all, and the exit code
// afterwards is the shell's 127 for a command that is not there.
func TestADaemonThatCouldNotStartTheCommandIsReadAsText(t *testing.T) {
	const reason = `OCI runtime exec failed: exec failed: unable to start container process: exec: "df": executable file not found in $PATH: unknown`
	f := newFakeEngine(t, map[string]http.HandlerFunc{
		"POST " + v + "/containers/c1/exec": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusCreated, map[string]string{"Id": "e1"})
		},
		"POST " + v + "/exec/e1/start": func(w http.ResponseWriter, r *http.Request) {
			_, _ = w.Write([]byte(reason + "\r\n"))
		},
		"GET " + v + "/exec/e1/json": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusOK, map[string]any{"Running": false, "ExitCode": 127})
		},
	})
	got, err := f.client(t).ContainerExec(context.Background(), "c1", []string{"df"}, nil)
	if err != nil {
		t.Fatalf("exec: %v", err)
	}
	if got.Stdout != "" || !strings.Contains(got.Stderr, "executable file not found") || got.ExitCode != 127 {
		t.Fatalf("result = %+v, want the daemon's sentence kept as the error text and no output", got)
	}
}

// Docker itself reports a command it could not start as a message on the
// stdout stream, in a frame like any other output, and the exit code afterwards
// is the one that says the command never ran. Caught against a real engine: the
// text is not outside the framing, as an older reading of the protocol had it.
func TestADockerThatCouldNotStartTheCommandSaysSoOnStdoutAndByItsExitCode(t *testing.T) {
	const reason = `OCI runtime exec failed: exec failed: unable to start container process: exec: "df": executable file not found in $PATH`
	f := newFakeEngine(t, map[string]http.HandlerFunc{
		"POST " + v + "/containers/c1/exec": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusCreated, map[string]string{"Id": "e1"})
		},
		"POST " + v + "/exec/e1/start": func(w http.ResponseWriter, r *http.Request) {
			_, _ = w.Write(frame(1, reason+"\r\n"))
		},
		"GET " + v + "/exec/e1/json": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusOK, map[string]any{"Running": false, "ExitCode": 127})
		},
	})
	got := measureScratch(context.Background(), f.client(t), "c1", []string{"/tmp"})
	if got.unmeasured != ScratchNoDF || len(got.use) != 0 {
		t.Fatalf("reading = %+v, want the image named as having no df", got)
	}
}

// A real daemon hijacks the connection for the output: it answers 200 with no
// length and no chunking, writes the stream, and closes the connection when the
// command's output ends. The client has to read that to the end of the
// connection, which a handler that merely writes a body does not prove.
func TestAnExecStreamTheDaemonHijacksIsReadToTheEndOfTheConnection(t *testing.T) {
	var upgrade string
	f := newFakeEngine(t, map[string]http.HandlerFunc{
		"POST " + v + "/containers/c1/exec": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusCreated, map[string]string{"Id": "e1"})
		},
		"POST " + v + "/exec/e1/start": func(w http.ResponseWriter, r *http.Request) {
			upgrade = r.Header.Get("Upgrade")
			conn, rw, err := w.(http.Hijacker).Hijack()
			if err != nil {
				t.Errorf("hijack: %v", err)
				return
			}
			defer conn.Close()
			_, _ = rw.WriteString("HTTP/1.1 200 OK\r\nContent-Type: application/vnd.docker.raw-stream\r\n\r\n")
			_, _ = rw.Write(frame(1, "first\n"))
			_, _ = rw.Write(frame(1, "second\n"))
			_ = rw.Flush()
		},
		"GET " + v + "/exec/e1/json": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusOK, map[string]any{"Running": false, "ExitCode": 0})
		},
	})
	got, err := f.client(t).ContainerExec(context.Background(), "c1", []string{"df"}, nil)
	if err != nil || got.Stdout != "first\nsecond\n" {
		t.Fatalf("result = %+v, err = %v; want everything the daemon wrote before it closed the connection", got, err)
	}
	if upgrade != "" {
		t.Fatalf("the start asked to upgrade the connection (%q); the client reads a plain response", upgrade)
	}
}

// A command that never stops printing must not fill the agent's memory: the
// output is cut at a fixed size, and what was read before the cut is kept.
func TestACommandsOutputIsBoundedNotUnlimited(t *testing.T) {
	chunk := strings.Repeat("x", 1<<10)
	f := newFakeEngine(t, map[string]http.HandlerFunc{
		"POST " + v + "/containers/c1/exec": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusCreated, map[string]string{"Id": "e1"})
		},
		"POST " + v + "/exec/e1/start": func(w http.ResponseWriter, r *http.Request) {
			for range 4 * execOutputLimit / len(chunk) {
				if _, err := w.Write(frame(1, chunk)); err != nil {
					return
				}
			}
		},
		"GET " + v + "/exec/e1/json": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusOK, map[string]any{"Running": false, "ExitCode": 0})
		},
	})
	got, err := f.client(t).ContainerExec(context.Background(), "c1", []string{"yes"}, nil)
	if err != nil {
		t.Fatalf("exec: %v", err)
	}
	if n := len(got.Stdout); n == 0 || n > execOutputLimit {
		t.Fatalf("kept %d bytes of output, want some and no more than %d", n, execOutputLimit)
	}
}

// What the daemon says when it will not run a command is the caller's to act
// on, so it arrives as the daemon's own error with its status, and a container
// that has gone is the usual not-found.
func TestAnExecTheDaemonRefusesCarriesItsStatus(t *testing.T) {
	for _, tc := range []struct {
		name   string
		status int
		gone   bool
	}{
		{"forbidden by a proxy or plugin", http.StatusForbidden, false},
		{"no such container", http.StatusNotFound, true},
		{"container not running", http.StatusConflict, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			f := newFakeEngine(t, map[string]http.HandlerFunc{
				"POST " + v + "/containers/c1/exec": func(w http.ResponseWriter, r *http.Request) {
					writeJSON(w, tc.status, map[string]string{"message": "no"})
				},
			})
			_, err := f.client(t).ContainerExec(context.Background(), "c1", []string{"df"}, nil)
			if StatusCode(err) != tc.status || errors.Is(err, ErrNotFound) != tc.gone {
				t.Fatalf("err = %v (status %d), want status %d", err, StatusCode(err), tc.status)
			}
		})
	}
}

package backend

import (
	"context"
	"errors"
	"io"
	"net/http"
	"strings"
	"testing"
	"time"
)

type lifetimeTransport func(*http.Request) (*http.Response, error)

func (f lifetimeTransport) RoundTrip(r *http.Request) (*http.Response, error) { return f(r) }

type lifetimeBody struct {
	ctx context.Context
	io.Reader
}

func (b *lifetimeBody) Read(p []byte) (int, error) {
	if err := b.ctx.Err(); err != nil {
		return 0, err
	}
	return b.Reader.Read(p)
}

func (b *lifetimeBody) Close() error { return nil }

func TestDockerResponseOwnsItsContextUntilTheBodyIsClosed(t *testing.T) {
	c, err := NewAPIClient("http://docker.invalid")
	if err != nil {
		t.Fatal(err)
	}
	var requestCtx context.Context
	c.http.Transport = lifetimeTransport(func(r *http.Request) (*http.Response, error) {
		requestCtx = r.Context()
		return &http.Response{
			StatusCode: http.StatusOK,
			Body:       &lifetimeBody{ctx: requestCtx, Reader: strings.NewReader("body after headers")},
		}, nil
	})
	resp, err := c.doRaw(context.Background(), http.MethodGet, "/version", nil, nil, nil, false)
	if err != nil {
		t.Fatal(err)
	}
	if requestCtx.Err() != nil {
		t.Fatal("request was cancelled before the caller could read its body")
	}
	body, err := io.ReadAll(resp.Body)
	if err != nil || string(body) != "body after headers" {
		t.Fatalf("reading delayed response: %q, %v", body, err)
	}
	if err := resp.Body.Close(); err != nil {
		t.Fatal(err)
	}
	if !errors.Is(requestCtx.Err(), context.Canceled) {
		t.Fatal("closing the body did not release its deadline")
	}
}

func TestDockerCallsPreserveExplicitLifecycleBudgets(t *testing.T) {
	c, err := NewAPIClient("http://docker.invalid")
	if err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithTimeout(context.Background(), time.Hour)
	defer cancel()
	c.http.Transport = lifetimeTransport(func(r *http.Request) (*http.Response, error) {
		deadline, ok := r.Context().Deadline()
		want, _ := ctx.Deadline()
		if !ok || !deadline.Equal(want) {
			t.Fatal("an explicit lifecycle budget was replaced")
		}
		return &http.Response{
			StatusCode: http.StatusOK,
			Body:       &lifetimeBody{ctx: r.Context(), Reader: strings.NewReader("{}")},
		}, nil
	})
	if _, err := c.Version(ctx); err != nil {
		t.Fatal(err)
	}
}

func TestDockerStreamingCallsKeepTheCallersDeadline(t *testing.T) {
	c, err := NewAPIClient("http://docker.invalid")
	if err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithTimeout(context.Background(), time.Hour)
	defer cancel()
	want, _ := ctx.Deadline()
	c.http.Transport = lifetimeTransport(func(r *http.Request) (*http.Response, error) {
		got, ok := r.Context().Deadline()
		if !ok || !got.Equal(want) {
			t.Fatal("streaming call lost its caller's deadline")
		}
		return &http.Response{StatusCode: http.StatusOK, Body: io.NopCloser(strings.NewReader(""))}, nil
	})
	resp, err := c.doRaw(ctx, http.MethodGet, "/logs", nil, nil, nil, true)
	if err != nil {
		t.Fatal(err)
	}
	_ = resp.Body.Close()
}

