// Measuring is an extra, and an extra must never cost the sample: the agent
// sizes runners and lends them CPU and memory from these figures, and a
// sample lost to a refused exec would read as a fleet of idle runners.
func TestAFolderThatCannotBeMeasuredNeverCostsTheSample(t *testing.T) {
	routes := map[string]http.HandlerFunc{
		"GET " + v + "/containers/c1/stats": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, 200, map[string]any{"memory_stats": map[string]any{"usage": 1 << 30, "limit": 4 << 30}})
		},
		"GET " + v + "/containers/c1/json": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, 200, inspectWith(map[string]string{LabelName: "runner-1"}, map[string]string{"/tmp": "rw,size=1024m"}))
		},
		"POST " + v + "/containers/c1/exec": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusForbidden, map[string]string{"message": "exec is not allowed through this socket"})
		},
	}
	b := dockerBackendFor(t, newFakeEngine(t, routes), DockerOptions{})

	got, err := b.Stats(context.Background(), "c1")
	if err != nil {
		t.Fatalf("stats failed over a refused exec: %v", err)
	}
	if got.MemoryBytes != 1<<30 || len(got.Scratch) != 0 || got.ScratchUnmeasured != ScratchExecRefused {
		t.Fatalf("stats = %+v; want the sample whole, no folders, and the reason they are missing", got)
	}
}

// An engine that never answers the exec is waited for only so long. The
// sample's own budget is shared with the stats call that runs beside it.
func TestAnExecThatNeverAnswersIsGivenUpOn(t *testing.T) {
	old := scratchTimeout
	scratchTimeout = 100 * time.Millisecond
	t.Cleanup(func() { scratchTimeout = old })

	routes := map[string]http.HandlerFunc{
		"GET " + v + "/containers/c1/stats": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, 200, map[string]any{"memory_stats": map[string]any{"usage": 1 << 30}})
		},
		"GET " + v + "/containers/c1/json": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, 200, inspectWith(map[string]string{LabelName: "runner-1"}, map[string]string{"/tmp": "rw,size=1024m"}))
		},
		"POST " + v + "/containers/c1/exec": func(w http.ResponseWriter, r *http.Request) {
			// A server only notices its client has gone once it has read the
			// request, so a handler that waits for that has to read first.
			_, _ = io.Copy(io.Discard, r.Body)
			<-r.Context().Done()
		},
	}
	b := dockerBackendFor(t, newFakeEngine(t, routes), DockerOptions{})

	began := time.Now()
	got, err := b.Stats(context.Background(), "c1")
	if err != nil || got.ScratchUnmeasured != ScratchTimedOut || got.MemoryBytes != 1<<30 {
		t.Fatalf("stats = %+v, err = %v; want the sample whole and the reason a timeout", got, err)
	}
	if time.Since(began) > 3*time.Second {
		t.Fatalf("the sample took %v; a hung exec held it", time.Since(began))
	}
}

// The likelier way for an exec to hang is not before it starts but after: the
// command is running, a frame has arrived and the output never ends. That is
// the same timeout, named the same, and it ends when the budget does.
func TestAnExecWhoseOutputStallsIsGivenUpOnAsATimeout(t *testing.T) {
	old := scratchTimeout
	scratchTimeout = 150 * time.Millisecond
	t.Cleanup(func() { scratchTimeout = old })

	routes := map[string]http.HandlerFunc{
		"GET " + v + "/containers/c1/stats": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, 200, map[string]any{"memory_stats": map[string]any{"usage": 1 << 30}})
		},
		"GET " + v + "/containers/c1/json": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, 200, inspectWith(map[string]string{LabelName: "runner-1"}, map[string]string{"/tmp": "rw,size=1024m"}))
		},
		"POST " + v + "/containers/c1/exec": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusCreated, map[string]string{"Id": "e1"})
		},
		"POST " + v + "/exec/e1/start": func(w http.ResponseWriter, r *http.Request) {
			_, _ = io.Copy(io.Discard, r.Body)
			_, _ = w.Write(frame(1, "Filesystem 1024-blocks Used Available Capacity Mounted on\n"))
			w.(http.Flusher).Flush()
			<-r.Context().Done()
		},
	}
	b := dockerBackendFor(t, newFakeEngine(t, routes), DockerOptions{})

	got, err := b.Stats(context.Background(), "c1")
	if err != nil || got.ScratchUnmeasured != ScratchTimedOut || len(got.Scratch) != 0 {
		t.Fatalf("stats = %+v, err = %v; want the sample whole and the folders unmeasured for a timeout", got, err)
	}
}

// The command runs beside the stats call and not after it: that call is a
// second of the daemon's time at the least, and the agent gives the whole
// sample five. Here the stats call is held until the exec has arrived, which a
// measurement that waited for the stats would never let happen.
func TestFoldersAreMeasuredWhileTheDaemonSamplesTheRunner(t *testing.T) {
	execAsked := make(chan struct{})
	var once sync.Once
	routes := map[string]http.HandlerFunc{
		"GET " + v + "/containers/c1/stats": func(w http.ResponseWriter, r *http.Request) {
			select {
			case <-execAsked:
			case <-time.After(5 * time.Second):
				http.Error(w, "the folders were never asked about while the stats call was out", http.StatusGatewayTimeout)
				return
			}
			writeJSON(w, 200, map[string]any{})
		},
		"GET " + v + "/containers/c1/json": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, 200, inspectWith(map[string]string{LabelName: "runner-1"}, map[string]string{"/tmp": "rw,size=1024m"}))
		},
	}
	var e execEngine
	e.routes("c1", "e1", "Filesystem 1024-blocks Used Available Capacity Mounted on\ntmpfs 1024 1 1023 1% /tmp\n", 0, routes)
	create := routes["POST "+v+"/containers/c1/exec"]
	routes["POST "+v+"/containers/c1/exec"] = func(w http.ResponseWriter, r *http.Request) {
		once.Do(func() { close(execAsked) })
		create(w, r)
	}
	b := dockerBackendFor(t, newFakeEngine(t, routes), DockerOptions{})

	got, err := b.Stats(context.Background(), "c1")
	if err != nil || len(got.Scratch) != 1 {
		t.Fatalf("stats = %+v, err = %v; want the folder measured", got, err)
	}
}

// A runner with nothing in memory has nothing to measure, and the engine is
// not asked to run anything in it.
func TestARunnerWithNoInMemoryFolderIsNotAskedAnything(t *testing.T) {
	var execs int
	var mu sync.Mutex
	routes := map[string]http.HandlerFunc{
		"GET " + v + "/containers/c1/stats": func(w http.ResponseWriter, r *http.Request) { writeJSON(w, 200, map[string]any{}) },
		"GET " + v + "/containers/c1/json": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, 200, inspectWith(map[string]string{LabelName: "runner-1"}, nil))
		},
		"POST " + v + "/containers/c1/exec": func(w http.ResponseWriter, r *http.Request) {
			mu.Lock()
			execs++
			mu.Unlock()
			writeJSON(w, http.StatusCreated, map[string]string{"Id": "e1"})
		},
	}
	b := dockerBackendFor(t, newFakeEngine(t, routes), DockerOptions{})

	got, err := b.Stats(context.Background(), "c1")
	if err != nil || got.Scratch != nil || got.ScratchUnmeasured != "" {
		t.Fatalf("stats = %+v, err = %v; want nothing said about folders that do not exist", got, err)
	}
	mu.Lock()
	defer mu.Unlock()
	if execs != 0 {
		t.Fatalf("the engine was asked to run %d commands in a container with nothing to measure", execs)
	}
}

package backend

import (
	"strconv"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

func scratchSpec(memoryMB int64, tmpfs store.TmpfsConfig) Spec {
	return Spec{Resources: store.Resources{MemoryMB: memoryMB}, ResourcesSource: store.AllocationFromPool, Tmpfs: tmpfs}
}

func folder(s store.RunnerScratch, kind store.ScratchKind) (store.ScratchFolder, bool) {
	for _, f := range s.Folders {
		if f.Kind == kind {
			return f, true
		}
	}
	return store.ScratchFolder{}, false
}

// A pool that keeps nothing in memory says nothing, and a runner that asks for
// nothing records nothing.
func TestAPoolThatKeepsNothingInMemoryHasNoScratchToPlan(t *testing.T) {
	if got := PlanScratch(scratchSpec(8192, store.TmpfsConfig{}), store.TmpfsConfig{}); got.Any() {
		t.Fatalf("scratch = %+v, want none", got)
	}
}

// What the runner is told it has is what the mount is asked for: the plan reads
// the placement the daemon is given, not a copy of its arithmetic.
func TestThePlanSaysWhatTheMountsAreAskedFor(t *testing.T) {
	pool := store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true, Auto: true}, Tmp: store.TmpfsMount{Enabled: true, SizeMB: 2048}}
	spec := scratchSpec(16384, pool)

	got := PlanScratch(spec, pool)
	mounts := tmpfsMounts(spec, 16384, false)

	work, ok := folder(got, store.ScratchWork)
	if !ok || !work.InMemory() || !work.Auto || work.Why != "" {
		t.Fatalf("work = %+v, want it in memory", work)
	}
	if want := "size=" + strconv.FormatInt(work.SizeMB, 10) + "m"; mounts[RunnerWorkMount][:len(want)] != want {
		t.Fatalf("the mount is %q, the plan says %d MB", mounts[RunnerWorkMount], work.SizeMB)
	}
	tmp, ok := folder(got, store.ScratchTmp)
	if !ok || tmp.SizeMB != 2048 || tmp.AskedMB != 2048 || tmp.Auto {
		t.Fatalf("tmp = %+v, want the typed 2048 MB", tmp)
	}
	if _, listed := folder(got, store.ScratchDaemon); listed {
		t.Fatal("a pool that did not ask for the image store has one in its plan")
	}
}

// An automatic folder is where the runner has room for it to be useful, and on
// disk where it has not: the same pool, a smaller runner, a different answer --
// with the reason, which is what an operator comparing two runners wants.
func TestAnAutomaticFolderStaysOnDiskOnARunnerTooSmallForIt(t *testing.T) {
	pool := store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true, Auto: true}}
	got := PlanScratch(scratchSpec(2048, pool), pool)
	work, ok := folder(got, store.ScratchWork)
	if !ok || work.InMemory() || work.Why != store.ScratchAutoTooSmall || work.AskedMB != store.DefaultTmpfsWorkMB {
		t.Fatalf("work = %+v, want it on disk because the runner is too small, having asked for the default", work)
	}
	if got.InMemory() != 0 {
		t.Fatalf("%d folders in memory on a runner too small for any", got.InMemory())
	}
}

// The host's owner has the last word, and what the pool wanted is still said.
func TestAFolderTheHostTurnedOffIsRecordedAsWanted(t *testing.T) {
	pool := store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true, SizeMB: 4096}}
	spec := scratchSpec(16384, store.TmpfsConfig{}) // what the host's policy left of it
	got := PlanScratch(spec, pool)
	work, ok := folder(got, store.ScratchWork)
	if !ok || work.InMemory() || work.Why != store.ScratchHostOff || work.AskedMB != 4096 {
		t.Fatalf("work = %+v, want it on disk because the host said no", work)
	}
}

// A host's own standard replaces the default for a folder the pool leaves to
// size itself, and a ceiling lowers what is given and not what was asked.
func TestAHostsStandardAndCeilingShapeWhatIsAskedAndGiven(t *testing.T) {
	pool := store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true}}
	spec := scratchSpec(64*1024, pool)
	spec.TmpfsHost = store.HostTmpfs{WorkMB: 16384, MaxMB: 8192}
	work, _ := folder(PlanScratch(spec, pool), store.ScratchWork)
	if work.AskedMB != 16384 || work.SizeMB != 8192 {
		t.Fatalf("work = %+v, want 16384 asked (the host's standard) and 8192 given (its ceiling)", work)
	}
}

// A work folder bound from a host directory is left to that bind, and says so.
func TestABoundWorkFolderIsNotAMemoryFolder(t *testing.T) {
	pool := store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true, SizeMB: 4096}, Tmp: store.TmpfsMount{Enabled: true, SizeMB: 1024}}
	spec := scratchSpec(16384, pool)
	spec.WorkDir = "/srv/runner-work"
	got := PlanScratch(spec, pool)
	work, _ := folder(got, store.ScratchWork)
	tmp, _ := folder(got, store.ScratchTmp)
	if work.InMemory() || work.Why != store.ScratchBound || !tmp.InMemory() {
		t.Fatalf("work = %+v, tmp = %+v, want the bind to win the work folder and /tmp to be in memory", work, tmp)
	}
}

// The image store is the sidecar's, charged to its own limit, which for a pair
// sized by its host is half of the slot.
func TestTheImageStoreIsPlacedOnTheSidecarsLimitNotTheRunners(t *testing.T) {
	pool := store.TmpfsConfig{Daemon: store.TmpfsMount{Enabled: true, Auto: true}}
	spec := scratchSpec(16384, pool)
	spec.DockerMode = store.DockerDinD
	spec.ResourcesSource = store.AllocationFromHost // one slot, split between the two
	spec.Resources = store.Resources{MemoryMB: 32768}
	got := PlanScratch(spec, pool)
	image, ok := folder(got, store.ScratchDaemon)
	if !ok || !image.InMemory() || image.AskedMB != store.DefaultTmpfsDaemonMB {
		t.Fatalf("image store = %+v, want it in memory on a 16 GB daemon half", image)
	}

	// Without docker-in-docker there is no sidecar to keep it in.
	spec.DockerMode = store.DockerNone
	if _, listed := folder(PlanScratch(spec, pool), store.ScratchDaemon); listed {
		t.Fatal("a runner with no sidecar has an image store in its plan")
	}
}

package backend

import (
	"context"
	"net/http"
	"strings"
	"sync"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// sidecarEngine is a fake daemon holding one docker-in-docker runner and its
// sidecar, each as inspect reports it, and counting how often each is asked
// about.
type sidecarEngine struct {
	*fakeEngine
	mu      sync.Mutex
	inspect map[string]int
}

func newSidecarEngine(t *testing.T, runnerState, sidecarState ContainerState) *sidecarEngine {
	t.Helper()
	e := &sidecarEngine{inspect: map[string]int{}}
	runnerLabels := map[string]string{
		LabelRole: roleRunner, LabelName: "runner-1", LabelRunnerID: "run_1",
		LabelDockerMode: string(store.DockerDinD), LabelLimitsFrom: "host",
	}
	sidecarLabels := map[string]string{
		LabelRole: roleDinD, LabelName: "runner-1-dind", LabelDinDFor: "runner-1", LabelRunnerID: "run_1",
		LabelLimitsFrom: "host",
	}
	serve := func(id string, state ContainerState, labels map[string]string) http.HandlerFunc {
		return func(w http.ResponseWriter, r *http.Request) {
			e.mu.Lock()
			e.inspect[id]++
			e.mu.Unlock()
			writeJSON(w, 200, &ContainerInspect{ID: id, State: &state, Config: &ContainerConfig{Labels: labels}})
		}
	}
	e.fakeEngine = newFakeEngine(t, map[string]http.HandlerFunc{
		"GET " + v + "/containers/json": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, 200, []ContainerSummary{
				{ID: "run1", State: runnerState.Status, Labels: runnerLabels},
				{ID: "dind1", State: sidecarState.Status, Labels: sidecarLabels},
			})
		},
		"GET " + v + "/containers/run1/json":  serve("run1", runnerState, runnerLabels),
		"GET " + v + "/containers/dind1/json": serve("dind1", sidecarState, sidecarLabels),
	})
	return e
}

func (e *sidecarEngine) inspected(id string) int {
	e.mu.Lock()
	defer e.mu.Unlock()
	return e.inspect[id]
}

func runnerWorkload(t *testing.T, e *sidecarEngine) Workload {
	t.Helper()
	b := dockerBackendFor(t, e.fakeEngine, DockerOptions{})
	got, err := b.List(context.Background())
	if err != nil {
		t.Fatalf("list: %v", err)
	}
	for _, w := range got {
		if !w.Sidecar {
			return w
		}
	}
	t.Fatalf("list returned no runner: %+v", got)
	return Workload{}
}

// A docker build that runs out of memory runs out in the sidecar, under the
// sidecar's own limit, and the runner beside it finishes its job and exits
// cleanly. Only the runner's flag was ever read, so the kill was never
// recorded: the job read as the workflow's own failure.
func TestAKillInTheSidecarIsAttributedToTheRunnerThatFinishedItsJob(t *testing.T) {
	e := newSidecarEngine(t,
		ContainerState{Status: "exited", ExitCode: 0},
		ContainerState{Status: "running", Running: true, OOMKilled: true})

	w := runnerWorkload(t, e)
	if !w.Status.OOMKilled || !w.Status.SidecarOOMKilled {
		t.Fatalf("status = %+v, want the sidecar's kill carried onto the runner", w.Status)
	}
	if w.Status.Phase != PhaseFailed {
		t.Errorf("phase = %q, want failed: a clean exit with a kill behind it is not a clean job", w.Status.Phase)
	}
	// What to change is the sidecar's half of the slot, not a pool field nobody set.
	for _, want := range []string{"Docker sidecar", "its half of the host's share", "Docker sidecar's share"} {
		if !strings.Contains(w.Status.Message, want) {
			t.Errorf("message %q does not say %q", w.Status.Message, want)
		}
	}
}

// The runner's own flag says which container was killed, and asking the sidecar
// as well would be a request that cannot change the answer.
func TestARunnersOwnKillIsNotQuestionedAgainstItsSidecar(t *testing.T) {
	e := newSidecarEngine(t,
		ContainerState{Status: "exited", ExitCode: 137, OOMKilled: true},
		ContainerState{Status: "running", Running: true, OOMKilled: true})

	w := runnerWorkload(t, e)
	if !w.Status.OOMKilled || w.Status.SidecarOOMKilled {
		t.Fatalf("status = %+v, want the runner's own kill, not the sidecar's", w.Status)
	}
	if got := e.inspected("dind1"); got != 0 {
		t.Fatalf("the sidecar was inspected %d times; the runner's flag had already answered", got)
	}
}

// A running fleet is where this is called most, and a runner that has not
// stopped has no end of job to attribute a kill to: nothing extra is asked.
func TestARunnerThatIsStillRunningCostsNoRequestAboutItsSidecar(t *testing.T) {
	e := newSidecarEngine(t,
		ContainerState{Status: "running", Running: true},
		ContainerState{Status: "running", Running: true, OOMKilled: true})

	w := runnerWorkload(t, e)
	if w.Status.OOMKilled {
		t.Fatalf("status = %+v, want a live runner left as it is", w.Status)
	}
	if got := e.inspected("dind1"); got != 0 {
		t.Fatalf("the sidecar was inspected %d times for a runner that is still running", got)
	}
}

// A sidecar that was never killed leaves a clean exit a clean exit.
func TestASidecarThatWasNotKilledLeavesACleanExitClean(t *testing.T) {
	e := newSidecarEngine(t,
		ContainerState{Status: "exited", ExitCode: 0},
		ContainerState{Status: "running", Running: true})

	w := runnerWorkload(t, e)
	if w.Status.OOMKilled || w.Status.SidecarOOMKilled || w.Status.Phase != PhaseExited {
		t.Fatalf("status = %+v, want a clean exit", w.Status)
	}
}

package backend

import (
	"encoding/json"
	"testing"
	"time"
)

func TestCPUThrottlingCountersDistinguishUnsupportedFromZero(t *testing.T) {
	for _, tc := range []struct {
		payload   string
		supported bool
		ns        uint64
	}{
		{`{"cpu_stats":{}}`, false, 0},
		{`{"cpu_stats":{"throttling_data":{"periods":0,"throttled_periods":0,"throttled_time":0}}}`, true, 0},
		{`{"cpu_stats":{"throttling_data":{"periods":100,"throttled_periods":70,"throttled_time":9000000000}}}`, true, 9000000000},
	} {
		var raw statsJSON
		if err := json.Unmarshal([]byte(tc.payload), &raw); err != nil {
			t.Fatal(err)
		}
		got := raw.sample()
		if (got.CPUThrottling != nil) != tc.supported {
			t.Fatalf("capability: %+v", got)
		}
		if tc.supported && got.CPUThrottling.ThrottledNanoseconds != tc.ns {
			t.Fatalf("counter: %+v", got)
		}
	}
}

func TestDinDStatsAddIntoOneLogicalRunner(t *testing.T) {
	runnerAt := time.Unix(10, 0)
	daemonAt := runnerAt.Add(time.Second)
	got := addStats(
		Stats{SampledAt: &runnerAt, CPUPercent: 40, MemoryBytes: 100, MemoryLimit: 200, CPUThrottling: &CPUThrottling{Periods: 10, ThrottledPeriods: 2, ThrottledNanoseconds: 3}},
		Stats{SampledAt: &daemonAt, CPUPercent: 160, MemoryBytes: 300, MemoryLimit: 400, CPUThrottling: &CPUThrottling{Periods: 20, ThrottledPeriods: 4, ThrottledNanoseconds: 5}},
	)
	if got.CPUPercent != 200 || got.MemoryBytes != 400 || got.MemoryLimit != 600 || got.SampledAt == nil || !got.SampledAt.Equal(daemonAt) {
		t.Fatalf("combined stats = %+v", got)
	}
	if got.CPUThrottling == nil || got.CPUThrottling.Periods != 30 || got.CPUThrottling.ThrottledPeriods != 6 || got.CPUThrottling.ThrottledNanoseconds != 8 {
		t.Fatalf("combined throttling = %+v", got.CPUThrottling)
	}
}

package backend

import (
	"encoding/json"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

func tmpfsSpec(cfg store.TmpfsConfig) Spec {
	s := jitSpec()
	s.Tmpfs = cfg
	return s
}

// The default for every existing pool: nothing is mounted over the runner's
// folders, and the request carries no Tmpfs key at all, so an upgrade changes no
// container the daemon is asked to make.
func TestARunnerWithNoTmpfsGetsNoTmpfsMounts(t *testing.T) {
	for _, fl := range []flavor{dockerFlavor(), podmanFlavor()} {
		cfg := buildRunnerConfig(jitSpec(), fl, containerOptions{Now: time.Now()})
		if cfg.HostConfig.Tmpfs != nil {
			t.Errorf("%s: tmpfs = %v, want none", fl.kind, cfg.HostConfig.Tmpfs)
		}
		body, err := json.Marshal(cfg)
		if err != nil {
			t.Fatal(err)
		}
		if strings.Contains(string(body), "Tmpfs") {
			t.Errorf("%s: the create request mentions Tmpfs: %s", fl.kind, body)
		}
	}
}

// Docker and Podman take the same map, and neither is given a uid: that number
// is read in the mount's user namespace, which rootless Podman shifts.
func TestTheWorkFolderIsMountedInMemoryOnDockerAndPodman(t *testing.T) {
	spec := tmpfsSpec(store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true, SizeMB: 2048}})
	for _, fl := range []flavor{dockerFlavor(), podmanFlavor()} {
		got := buildRunnerConfig(spec, fl, containerOptions{Now: time.Now()}).HostConfig.Tmpfs
		want := map[string]string{RunnerWorkMount: "size=2048m,rw,exec,nosuid,nodev,mode=1777"}
		if len(got) != 1 || got[RunnerWorkMount] != want[RunnerWorkMount] {
			t.Errorf("%s: tmpfs = %v, want %v", fl.kind, got, want)
		}
		if strings.Contains(got[RunnerWorkMount], "uid=") || strings.Contains(got[RunnerWorkMount], "noexec") {
			t.Errorf("%s: options %q must carry neither a uid nor noexec", fl.kind, got[RunnerWorkMount])
		}
	}
}

// Only the work folder is the default an operator opts into; /tmp is its own
// choice.
func TestTmpIsMountedOnlyWhenAskedFor(t *testing.T) {
	work := buildRunnerConfig(tmpfsSpec(store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true, SizeMB: 1024}}),
		dockerFlavor(), containerOptions{Now: time.Now()}).HostConfig.Tmpfs
	if _, ok := work[RunnerTmpMount]; ok {
		t.Errorf("tmpfs = %v, want /tmp left on disk", work)
	}

	both := buildRunnerConfig(tmpfsSpec(store.TmpfsConfig{
		Work: store.TmpfsMount{Enabled: true, SizeMB: 1024},
		Tmp:  store.TmpfsMount{Enabled: true, SizeMB: 512},
	}), dockerFlavor(), containerOptions{Now: time.Now()}).HostConfig.Tmpfs
	if both[RunnerTmpMount] != "size=512m,rw,exec,nosuid,nodev,mode=1777" || both[RunnerWorkMount] == "" {
		t.Errorf("tmpfs = %v, want both folders", both)
	}

	tmpOnly := buildRunnerConfig(tmpfsSpec(store.TmpfsConfig{Tmp: store.TmpfsMount{Enabled: true, SizeMB: 512}}),
		dockerFlavor(), containerOptions{Now: time.Now()}).HostConfig.Tmpfs
	if _, ok := tmpOnly[RunnerWorkMount]; ok || tmpOnly[RunnerTmpMount] == "" {
		t.Errorf("tmpfs = %v, want only /tmp", tmpOnly)
	}
}

// A mount with no size of its own is fitted to the runner's memory limit, so the
// default can never be a tmpfs bigger than the cgroup it is charged to.
func TestAnAutomaticTmpfsIsFittedToTheRunnersMemoryLimit(t *testing.T) {
	cases := []struct {
		name     string
		memoryMB int64
		want     string
	}{
		{"a small limit shrinks it to half", 4096, "size=2048m,rw,exec,nosuid,nodev,mode=1777"},
		{"a roomy limit takes the default", 32768, "size=4096m,rw,exec,nosuid,nodev,mode=1777"},
		{"no limit takes the default", 0, "size=4096m,rw,exec,nosuid,nodev,mode=1777"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			spec := tmpfsSpec(store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true}})
			spec.Resources.MemoryMB = tc.memoryMB
			got := buildRunnerConfig(spec, dockerFlavor(), containerOptions{Now: time.Now()}).HostConfig.Tmpfs
			if got[RunnerWorkMount] != tc.want {
				t.Errorf("tmpfs = %q, want %q", got[RunnerWorkMount], tc.want)
			}
		})
	}
}

// With docker-in-docker the runner is given its half of the pair, and the tmpfs
// is charged to the runner's cgroup, so it is fitted to that half. Fitted to the
// whole it would promise room the runner does not have.
func TestADinDRunnersTmpfsIsFittedToItsHalfOfTheLimit(t *testing.T) {
	spec := tmpfsSpec(store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true}})
	spec.DockerMode = store.DockerDinD
	spec.ResourcesSource = store.AllocationFromHost
	spec.Resources = store.Resources{CPUs: 4, MemoryMB: 4096}
	cfg := buildRunnerConfig(spec, dockerFlavor(), containerOptions{Now: time.Now()})
	// The runner holds 2048 MB, so half of it is 1024.
	if got, want := cfg.HostConfig.Tmpfs[RunnerWorkMount], "size=1024m,rw,exec,nosuid,nodev,mode=1777"; got != want {
		t.Errorf("tmpfs = %q, want %q", got, want)
	}
}

// A host directory bound at the work folder wins: both at one path is an error
// the daemon raises only when the container is created.
func TestAWorkFolderBoundFromTheHostIsNotAlsoMountedInMemory(t *testing.T) {
	spec := tmpfsSpec(store.TmpfsConfig{
		Work: store.TmpfsMount{Enabled: true, SizeMB: 1024},
		Tmp:  store.TmpfsMount{Enabled: true, SizeMB: 512},
	})
	cfg := buildRunnerConfig(spec, dockerFlavor(), containerOptions{Now: time.Now(), WorkDirMount: "/srv/zoomies/runners/r1"})
	if _, ok := cfg.HostConfig.Tmpfs[RunnerWorkMount]; ok {
		t.Errorf("tmpfs = %v, want the bound work folder left alone", cfg.HostConfig.Tmpfs)
	}
	if cfg.HostConfig.Tmpfs[RunnerTmpMount] == "" {
		t.Errorf("tmpfs = %v, want /tmp still in memory", cfg.HostConfig.Tmpfs)
	}
}

// The setting travels to the agent inside the task, and an agent that predates
// it must still be able to read a task from a controller that has it.
func TestTheSpecCarriesTmpfsToTheAgentAndOmitsItWhenOff(t *testing.T) {
	off, err := json.Marshal(jitSpec())
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(off), "tmpfs") {
		t.Errorf("a spec with nothing in memory still carries tmpfs: %s", off)
	}

	on := tmpfsSpec(store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true, SizeMB: 2048}})
	body, err := json.Marshal(on)
	if err != nil {
		t.Fatal(err)
	}
	var back Spec
	if err := json.Unmarshal(body, &back); err != nil {
		t.Fatal(err)
	}
	if back.Tmpfs != on.Tmpfs {
		t.Errorf("tmpfs = %+v after the round trip, want %+v", back.Tmpfs, on.Tmpfs)
	}
}

func dindTmpfsSpec(cfg store.TmpfsConfig) Spec {
	s := tmpfsSpec(cfg)
	s.DockerMode = store.DockerDinD
	return s
}

// The image store is on the sidecar, not the runner: it is where a dind job's
// pulls and builds are written, and it is a different container with its own
// memory limit.
func TestTheSidecarsImageStoreIsMountedInMemoryAndTheRunnersIsNot(t *testing.T) {
	spec := dindTmpfsSpec(store.TmpfsConfig{Daemon: store.TmpfsMount{Enabled: true, SizeMB: 6144}})
	spec.Resources = store.Resources{CPUs: 4, MemoryMB: 16384}
	side := buildDinDConfig(spec, dockerFlavor(), containerOptions{Now: time.Now(), DinDImage: DefaultDinDImage})
	if got, want := side.HostConfig.Tmpfs[DaemonStoreMount], "size=6144m,rw,exec,suid,dev,mode=0710"; got != want {
		t.Errorf("sidecar tmpfs = %q, want %q", got, want)
	}
	run := buildRunnerConfig(spec, dockerFlavor(), containerOptions{Now: time.Now()})
	if len(run.HostConfig.Tmpfs) != 0 {
		t.Errorf("runner tmpfs = %v, want none: the image store is the sidecar's", run.HostConfig.Tmpfs)
	}
}

// Off is off: the sidecar's create carries no Tmpfs key at all, so an upgrade
// changes no container the daemon is asked to make.
func TestASidecarWithNoImageStoreInMemoryGetsNoTmpfs(t *testing.T) {
	spec := dindTmpfsSpec(store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true}})
	side := buildDinDConfig(spec, dockerFlavor(), containerOptions{Now: time.Now(), DinDImage: DefaultDinDImage})
	if side.HostConfig.Tmpfs != nil {
		t.Errorf("sidecar tmpfs = %v, want none", side.HostConfig.Tmpfs)
	}
	body, err := json.Marshal(side)
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(body), "Tmpfs") {
		t.Errorf("the sidecar's create request mentions Tmpfs: %s", body)
	}
}

// The store is fitted to the daemon's own limit. For a pool sized by its host
// that is the daemon's half of one slot's share; for a typed limit it is the
// whole of it, because a typed limit is given to both containers.
func TestTheImageStoreIsFittedToTheDaemonsOwnHalf(t *testing.T) {
	auto := dindTmpfsSpec(store.TmpfsConfig{Daemon: store.TmpfsMount{Enabled: true}})
	auto.ResourcesSource = store.AllocationFromHost
	auto.Resources = store.Resources{CPUs: 4, MemoryMB: 6001}
	side := buildDinDConfig(auto, dockerFlavor(), containerOptions{Now: time.Now(), DinDImage: DefaultDinDImage})
	// The daemon takes the remainder of an odd split: 6001 - 3000 = 3001, and the
	// store is half of what the daemon has, 1500.
	if got, want := side.HostConfig.Tmpfs[DaemonStoreMount], "size=1500m,rw,exec,suid,dev,mode=0710"; got != want {
		t.Errorf("automatic pool: sidecar tmpfs = %q, want %q", got, want)
	}

	typed := dindTmpfsSpec(store.TmpfsConfig{Daemon: store.TmpfsMount{Enabled: true}})
	typed.Resources = store.Resources{CPUs: 4, MemoryMB: 32768}
	side = buildDinDConfig(typed, dockerFlavor(), containerOptions{Now: time.Now(), DinDImage: DefaultDinDImage})
	if got, want := side.HostConfig.Tmpfs[DaemonStoreMount], "size=8192m,rw,exec,suid,dev,mode=0710"; got != want {
		t.Errorf("typed pool: sidecar tmpfs = %q, want %q", got, want)
	}
}

// The host's ceiling is applied after the folder is fitted to the runner's
// limit, so it lowers a size however the size was arrived at -- typed, or fitted
// -- and cannot raise one.
func TestAHostCeilingLowersEveryInMemoryFolderAndNeverRaisesOne(t *testing.T) {
	spec := dindTmpfsSpec(store.TmpfsConfig{
		Work:   store.TmpfsMount{Enabled: true},
		Tmp:    store.TmpfsMount{Enabled: true, SizeMB: 512},
		Daemon: store.TmpfsMount{Enabled: true, SizeMB: 6000},
	})
	spec.Resources = store.Resources{CPUs: 4, MemoryMB: 32768}
	spec.TmpfsMaxMB = 2048

	run := buildRunnerConfig(spec, dockerFlavor(), containerOptions{Now: time.Now()})
	// The fitted default is 4096 and is lowered; the typed 512 is under the ceiling.
	if got, want := run.HostConfig.Tmpfs[RunnerWorkMount], "size=2048m,rw,exec,nosuid,nodev,mode=1777"; got != want {
		t.Errorf("work = %q, want %q", got, want)
	}
	if got, want := run.HostConfig.Tmpfs[RunnerTmpMount], "size=512m,rw,exec,nosuid,nodev,mode=1777"; got != want {
		t.Errorf("tmp = %q, want %q", got, want)
	}
	side := buildDinDConfig(spec, dockerFlavor(), containerOptions{Now: time.Now(), DinDImage: DefaultDinDImage})
	if got, want := side.HostConfig.Tmpfs[DaemonStoreMount], "size=2048m,rw,exec,suid,dev,mode=0710"; got != want {
		t.Errorf("image store = %q, want %q", got, want)
	}

	// With no ceiling nothing is lowered.
	spec.TmpfsMaxMB = 0
	run = buildRunnerConfig(spec, dockerFlavor(), containerOptions{Now: time.Now()})
	if got, want := run.HostConfig.Tmpfs[RunnerWorkMount], "size=4096m,rw,exec,nosuid,nodev,mode=1777"; got != want {
		t.Errorf("without a ceiling, work = %q, want %q", got, want)
	}
}

// The ceiling travels to the agent in the task, and a spec with none carries no
// key, so an agent that predates it reads the same document as before.
func TestTheHostCeilingTravelsInTheSpecAndIsOmittedWhenNone(t *testing.T) {
	plain, err := json.Marshal(tmpfsSpec(store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true}}))
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(plain), "tmpfs_max_mb") {
		t.Errorf("a spec with no ceiling carries one: %s", plain)
	}
	capped := tmpfsSpec(store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true}})
	capped.TmpfsMaxMB = 1024
	body, err := json.Marshal(capped)
	if err != nil {
		t.Fatal(err)
	}
	var back Spec
	if err := json.Unmarshal(body, &back); err != nil {
		t.Fatal(err)
	}
	if back.TmpfsMaxMB != 1024 {
		t.Errorf("ceiling = %d after the round trip, want 1024", back.TmpfsMaxMB)
	}
}

// A pool that gives its daemon most of a host-sized slot gets it in the real
// limits, and a typed limit is untouched by the share.
func TestPairLimitsFollowThePoolsDaemonShare(t *testing.T) {
	spec := Spec{Resources: store.Resources{CPUs: 10, MemoryMB: 10000}, ResourcesSource: store.AllocationFromHost, DaemonSharePercent: 75}
	r, d := pairLimits(spec)
	if d.MemoryMB != 7500 || r.MemoryMB != 2500 {
		t.Fatalf("host-sized pair = runner %d MB, daemon %d MB; want 2500 and 7500", r.MemoryMB, d.MemoryMB)
	}
	spec.ResourcesSource = ""
	r, d = pairLimits(spec)
	if r.MemoryMB != 10000 || d.MemoryMB != 10000 {
		t.Fatalf("typed pair = %d / %d MB; a typed limit goes to both in full", r.MemoryMB, d.MemoryMB)
	}
}

// Docker and Podman start every tmpfs from noexec,nosuid,nodev and merge the
// options they are given over that, so a mount that merely omits noexec is
// still noexec. Pools that turned the folders on found every `go test` dying
// with "permission denied" on a binary it had just built in /tmp. Each option
// that has to override a default is asserted by name.
func TestInMemoryFoldersOverrideTheNoexecDefaultOfATmpfs(t *testing.T) {
	has := func(opts, want string) bool {
		for _, o := range strings.Split(opts, ",") {
			if o == want {
				return true
			}
		}
		return false
	}
	for _, opts := range []string{tmpfsOptions, daemonTmpfsOptions} {
		if !has(opts, "exec") || has(opts, "noexec") {
			t.Errorf("options %q must say exec, or the runtime mounts the folder noexec", opts)
		}
	}
	for _, want := range []string{"suid", "dev"} {
		if !has(daemonTmpfsOptions, want) {
			t.Errorf("the image store's options %q must say %s: the nested daemon keeps setuid files and device nodes in image layers", daemonTmpfsOptions, want)
		}
	}
	if !has(tmpfsOptions, "nosuid") || !has(tmpfsOptions, "nodev") {
		t.Errorf("the runner's folders keep the runtime's nosuid and nodev: %q", tmpfsOptions)
	}
}

// Auto is decided where the runner's real limit is known: on a runner too small
// the folder is simply not mounted, which is what makes it safe to leave on for
// a pool whose hosts differ.
func TestAnAutomaticFolderIsNotMountedOnARunnerTooSmallForIt(t *testing.T) {
	spec := Spec{Tmpfs: store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true, Auto: true}, Tmp: store.TmpfsMount{Enabled: true, Auto: true}}}
	if got := tmpfsMounts(spec, 2048, false); got != nil {
		t.Errorf("a 2 GB runner was given %v, want disk", got)
	}
	got := tmpfsMounts(spec, 32768, false)
	if got[RunnerWorkMount] != "size=4096m,rw,exec,nosuid,nodev,mode=1777" || got[RunnerTmpMount] != "size=4096m,rw,exec,nosuid,nodev,mode=1777" {
		t.Errorf("a 32 GB runner was given %v", got)
	}
	// The host's own standard replaces the default an untyped folder is asked for.
	spec.TmpfsHost = store.HostTmpfs{WorkMB: 8192}
	if got := tmpfsMounts(spec, 65536, false); got[RunnerWorkMount] != "size=8192m,rw,exec,nosuid,nodev,mode=1777" {
		t.Errorf("a host standard of 8 GB gave %v", got)
	}
	// An older controller sends only the ceiling, and it still applies.
	old := Spec{Tmpfs: spec.Tmpfs, TmpfsMaxMB: 2560}
	if got := tmpfsMounts(old, 65536, false); got[RunnerWorkMount] != "size=2560m,rw,exec,nosuid,nodev,mode=1777" {
		t.Errorf("a ceiling from an older controller gave %v", got)
	}
}

// A host-sized pair is split per resource: the daemon can have most of the CPU
// while the runner keeps most of the memory.
func TestPairLimitsSplitCPUAndMemoryOnTheirOwnShares(t *testing.T) {
	spec := Spec{Resources: store.Resources{CPUs: 10, MemoryMB: 10000}, ResourcesSource: store.AllocationFromHost,
		DaemonCPUSharePercent: 70, DaemonMemorySharePercent: 30}
	r, d := pairLimits(spec)
	if d.CPUs != 7 || r.CPUs != 3 || d.MemoryMB != 3000 || r.MemoryMB != 7000 {
		t.Fatalf("pair = runner %+v, daemon %+v; want 70%% of the CPU and 30%% of the memory to the daemon", r, d)
	}
	// The general share still means both, for a spec from before the split.
	old := Spec{Resources: spec.Resources, ResourcesSource: store.AllocationFromHost, DaemonSharePercent: 75}
	if r, d := pairLimits(old); d.CPUs != 7.5 || d.MemoryMB != 7500 || r.MemoryMB != 2500 {
		t.Fatalf("a single share = runner %+v, daemon %+v", r, d)
	}
}

package backend

import (
	"context"
	"crypto/sha256"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"
)

const roleToolCleanup = "toolcache-cleanup"

// This mount contains only one stopped runner's disposable cache. In
// particular, the symlinks into its pool's kept cache must be unlinked, never
// followed. Include dotfiles, but not . or .., and never remove the mountpoint.
const toolCleanupScript = `rm -rf -- /cleanup/* /cleanup/.[!.]* /cleanup/..?*`

// removeRunnerToolFarm is called after Stop, while the runner still retains
// its labels for retries. A setup action can create uid-1001 (or root) 0755
// directories below our 0777 farm. An unprivileged agent cannot unlink their
// contents, and chmod on the farm cannot fix that. Ask the existing daemon to
// remove only those contents in the runner's already-local immutable image.
// removeAll is injectable so tests exercise permission failures even as root.
func (b *DockerBackend) removeRunnerToolFarm(ctx context.Context, runner ContainerInspect, removeAll func(string) error) error {
	farm := runner.Config.Labels[LabelToolFarm]
	err := removeAll(farm)
	if err == nil || !errors.Is(err, os.ErrPermission) {
		return err
	}
	if validationErr := b.validateToolCleanup(runner); validationErr != nil {
		return errors.Join(err, validationErr)
	}
	b.log.Info("recovering runner tool cache permissions", "runner", runner.Config.Labels[LabelName], "path", farm)
	if cleanupErr := b.cleanToolFarmInContainer(ctx, runner); cleanupErr != nil {
		return errors.Join(err, cleanupErr)
	}
	// The helper cannot unlink its own mountpoint. Verify the actual filesystem
	// result and remove the now-empty directory as the agent before losing the
	// runner's labels. A successful helper exit alone is not proof of cleanup.
	return removeAll(farm)
}

func (b *DockerBackend) validateToolCleanup(runner ContainerInspect) error {
	labels := runner.Config.Labels
	name, farm := labels[LabelName], labels[LabelToolFarm]
	if labels[LabelManaged] != "true" || labels[LabelRole] != roleRunner || name == "" || runner.ID == "" || runner.Image == "" {
		return errors.New("refusing tool cache recovery without a managed runner identity and immutable image")
	}
	if b.sharedDir == "" || !filepath.IsAbs(farm) || filepath.Clean(farm) != toolFarmDir(b.sharedDir, name) || strings.ContainsAny(farm, ":\n\r") {
		return errors.New("refusing tool cache recovery outside this runner's disposable cache")
	}
	// The shared root may itself be an operator-configured symlink, but none
	// of the cache components below it may redirect the daemon's bind mount.
	for _, path := range []string{filepath.Join(b.sharedDir, "cache"), filepath.Join(b.sharedDir, "cache", "tool-runs"), farm} {
		fi, err := os.Lstat(path)
		if err != nil {
			return fmt.Errorf("checking tool cache recovery path: %w", err)
		}
		if !fi.IsDir() || fi.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("refusing tool cache recovery through a non-directory or symlink: %s", path)
		}
	}
	return nil
}

func toolCleanupName(runner ContainerInspect) string {
	sum := sha256.Sum256([]byte(runner.ID + "\x00" + runner.Config.Labels[LabelToolFarm]))
	return fmt.Sprintf("zoomies-toolcleanup-%x", sum[:12])
}

func (b *DockerBackend) cleanToolFarmInContainer(ctx context.Context, runner ContainerInspect) (resultErr error) {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
	defer cancel()
	farm := runner.Config.Labels[LabelToolFarm]
	name := toolCleanupName(runner)
	// A cancelled create can have reached the daemon despite losing its reply.
	// Recover that helper on the next attempt, without touching a foreign name.
	old, err := b.api.ContainerInspect(ctx, name)
	if err == nil {
		if old.Config == nil || old.Config.Labels[LabelRole] != roleToolCleanup || old.Config.Labels[LabelToolFarm] != farm {
			return errors.New("refusing to replace an unrelated tool cache cleanup container")
		}
		if err := b.removeContainer(ctx, old.ID); err != nil && !errors.Is(err, ErrNotFound) {
			return fmt.Errorf("removing previous tool cache cleanup container: %w", err)
		}
	} else if !errors.Is(err, ErrNotFound) {
		return fmt.Errorf("checking previous tool cache cleanup container: %w", err)
	}

	pids := int64(32)
	cfg := ContainerCreateRequest{
		Image:       runner.Image,
		User:        "0:0",
		Entrypoint:  []string{"/bin/sh", "-c", toolCleanupScript},
		WorkingDir:  "/",
		Healthcheck: &HealthConfig{Test: []string{"NONE"}},
		Labels:      map[string]string{LabelRole: roleToolCleanup, LabelToolFarm: farm},
		HostConfig: &HostConfig{
			Binds:          []string{farm + ":/cleanup" + b.fl.mountSuffix},
			NetworkMode:    "none",
			ReadonlyRootfs: true,
			CapDrop:        []string{"ALL"},
			CapAdd:         []string{"DAC_OVERRIDE", "FOWNER"},
			SecurityOpt:    []string{"no-new-privileges"},
			AutoRemove:     true,
			RestartPolicy:  RestartPolicy{Name: "no"},
			NanoCPUs:       nanoCPUs(1),
			Memory:         128 * 1024 * 1024,
			MemorySwap:     128 * 1024 * 1024,
			PidsLimit:      &pids,
			LogConfig:      runnerLogConfig(b.fl),
		},
	}
	id, err := b.api.ContainerCreate(ctx, name, cfg)
	if err != nil {
		return fmt.Errorf("creating tool cache cleanup container: %w", err)
	}
	defer func() {
		cleanupCtx, stop := context.WithTimeout(context.WithoutCancel(ctx), 30*time.Second)
		defer stop()
		// The helper is AutoRemove, so the daemon starts removing it the
		// moment it exits; a DELETE that meets that removal waits it out
		// rather than failing the runner's cleanup over a container that is
		// already on its way. One still going when the wait ends is not a
		// failure either -- the daemon finishes it -- and it must not ride
		// along into the runner's error, where it would make a real cleanup
		// failure read as a removal the agent should simply wait for.
		err := b.removeContainer(cleanupCtx, id)
		if errors.Is(err, ErrRemovalInProgress) {
			b.log.Info("the daemon is still removing the tool cache cleanup container; it finishes on its own", "container", shortID(id), "error", err)
			return
		}
		if err != nil && !errors.Is(err, ErrNotFound) {
			resultErr = errors.Join(resultErr, fmt.Errorf("removing tool cache cleanup container: %w", err))
		}
	}()
	if err := b.api.ContainerStart(ctx, id); err != nil {
		return fmt.Errorf("starting tool cache cleanup container: %w", err)
	}
	code, err := b.api.ContainerWait(ctx, id)
	if errors.Is(err, ErrNotFound) {
		// AutoRemove can win the race with Wait. The caller still verifies that
		// the cache was emptied; a missing helper cannot hide a cleanup failure.
		return nil
	}
	if err != nil {
		return fmt.Errorf("waiting for tool cache cleanup container: %w", err)
	}
	if code != 0 {
		return fmt.Errorf("tool cache cleanup container exited with status %d", code)
	}
	return nil
}

package backend

import (
	"context"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"slices"
	"testing"

	"golang.org/x/sys/unix"
)

// Exercise Remove itself with a real unlinkat permission failure, followed by
// a failed helper and a successful retry. Even root CI can run this: a child
// test drops DAC override capabilities on its locked OS thread. Other tests
// and the parent process keep their original credentials.
func TestToolCleanupRetainsRunnerUntilRetrySucceeds(t *testing.T) {
	if os.Geteuid() == 0 {
		if os.Getenv("ZOOMIES_TEST_CLEANUP_UNPRIVILEGED") != "1" {
			cmd := exec.Command(os.Args[0], "-test.run=^TestToolCleanupRetainsRunnerUntilRetrySucceeds$", "-test.v")
			cmd.Env = append(os.Environ(), "ZOOMIES_TEST_CLEANUP_UNPRIVILEGED=1")
			if out, err := cmd.CombinedOutput(); err != nil {
				t.Fatalf("unprivileged cleanup regression: %v\n%s", err, out)
			} else {
				t.Logf("%s", out)
			}
			return
		}
		runtime.LockOSThread()
		// Do not unlock: Go retires this thread when the test goroutine ends.
		caps := [2]unix.CapUserData{}
		if err := unix.Capset(&unix.CapUserHeader{Version: unix.LINUX_CAPABILITY_VERSION_3}, &caps[0]); err != nil {
			t.Fatalf("dropping test process capabilities: %v", err)
		}
	}
	shared := t.TempDir()
	runner := cleanupRunner(t, shared)
	farm := runner.Config.Labels[LabelToolFarm]
	apiDir := filepath.Join(farm, "go/1.27.1/x64/api")
	if err := os.WriteFile(filepath.Join(apiDir, "go1.txt"), []byte("cached tool"), 0644); err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(apiDir, 0555); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.Chmod(apiDir, 0755) })
	var stopped, recover bool
	var deleted []string
	f := newFakeEngine(t, map[string]http.HandlerFunc{
		"GET " + v + "/containers/{id}/json": func(w http.ResponseWriter, r *http.Request) {
			if r.PathValue("id") == runner.ID {
				writeJSON(w, 200, runner)
				return
			}
			w.WriteHeader(404)
		},
		"POST " + v + "/containers/runner-id/stop": func(w http.ResponseWriter, r *http.Request) {
			stopped = true
			w.WriteHeader(204)
		},
		"POST " + v + "/containers/create": func(w http.ResponseWriter, r *http.Request) {
			if !stopped {
				t.Error("cleanup began before the runner was stopped")
			}
			writeJSON(w, 201, map[string]string{"Id": "helper"})
		},
		"POST " + v + "/containers/helper/start": func(w http.ResponseWriter, r *http.Request) { w.WriteHeader(204) },
		"POST " + v + "/containers/helper/wait": func(w http.ResponseWriter, r *http.Request) {
			if !recover {
				writeJSON(w, 200, map[string]int{"StatusCode": 1})
				return
			}
			// Model the daemon clearing the cache under its own credentials.
			if err := os.Chmod(apiDir, 0755); err != nil {
				t.Error(err)
			}
			if err := os.RemoveAll(filepath.Join(farm, "go")); err != nil {
				t.Error(err)
			}
			writeJSON(w, 200, map[string]int{"StatusCode": 0})
		},
		"DELETE " + v + "/containers/{id}": func(w http.ResponseWriter, r *http.Request) {
			deleted = append(deleted, r.PathValue("id"))
			w.WriteHeader(204)
		},
	})
	b := dockerBackendFor(t, f, DockerOptions{SharedDir: shared})
	if err := b.Remove(context.Background(), Handle(runner.ID)); err == nil {
		t.Fatal("permission failure disappeared")
	}
	if slices.Contains(deleted, runner.ID) {
		t.Fatal("failed cleanup lost the runner's retry labels")
	}
	if !slices.Contains(deleted, "helper") {
		t.Fatal("real permission error did not trigger helper cleanup")
	}
	recover = true
	if err := b.Remove(context.Background(), Handle(runner.ID)); err != nil {
		t.Fatal(err)
	}
	if !slices.Contains(deleted, runner.ID) {
		t.Fatal("successful retry retained the runner")
	}
	if _, err := os.Stat(farm); !os.IsNotExist(err) {
		t.Fatalf("farm survived successful retry: %v", err)
	}
}

