	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

func toolFillSpec() Spec {
	return Spec{
		PoolID:     "pool_1",
		PoolName:   "linux-x64",
		Image:      "ghcr.io/eyupio/zoomies-runner:v1",
		PullPolicy: store.PullIfNotPresent,
		Cache:      store.CacheConfig{Enabled: true, Tools: true, Scope: store.CacheScopePool},
		Env:        map[string]string{"HTTPS_PROXY": "http://proxy.pool:3128", "SECRET_TOKEN": "not-for-the-fill"},
		RunAsRoot:  true,
	}
}

// The fill writes what the runners read, so it runs as the image's runner
// user even for a pool whose jobs run as root -- a cache of root's files is
// one a later job cannot update. It sees the tool cache and nothing else of
// the host's, and carries no managed label, so the agent's reconciliation
// never mistakes it for a runner and reaps it mid-download.
func TestTheFillContainerIsTheRunnerUserWithOnlyTheToolCache(t *testing.T) {
	tools := []ToolRequest{{Tool: "python", Version: "3.12"}, {Tool: "java", Version: "21", Distribution: "temurin"}}
	cfg := buildToolFillConfig(toolFillSpec(), dockerFlavor(), "/var/lib/zoomies/shared/cache/tools/pool-1", "", nil, tools)

	if cfg.User != "runner" {
		t.Errorf("user = %q, want the runner user", cfg.User)
	}
	if _, managed := cfg.Labels[LabelManaged]; managed {
		t.Error("the fill carries the managed label, so reconciliation would treat it as a runner")
	}
	if !slices.Equal(cfg.HostConfig.Binds, []string{"/var/lib/zoomies/shared/cache/tools/pool-1:" + RunnerToolCacheMount}) {
		t.Errorf("binds = %v, want only the tool cache", cfg.HostConfig.Binds)
	}
	env := envMap(cfg.Env)
	if env[EnvToolsDirectory] != RunnerToolCacheMount {
		t.Errorf("%s = %q", EnvToolsDirectory, env[EnvToolsDirectory])
	}
	if env["ZOOMIES_TOOL_REQUESTS"] != "python 3.12 \njava 21 temurin\n" {
		t.Errorf("requests = %q", env["ZOOMIES_TOOL_REQUESTS"])
	}
	// The pool's proxy is its way out; the rest of its env is its jobs'.
	if env["HTTPS_PROXY"] != "http://proxy.pool:3128" {
		t.Errorf("the pool's proxy was not passed on: %v", env)
	}
	if _, ok := env["SECRET_TOKEN"]; ok {
		t.Error("a pool variable that is not a proxy reached the fill")
	}
	if cfg.HostConfig.NanoCPUs == 0 || cfg.HostConfig.Memory == 0 {
		t.Error("the fill has no resource limit, so it can take a running job's share of the host")
	}
	if len(cfg.Entrypoint) < 3 || cfg.Entrypoint[0] != "/bin/bash" || cfg.Entrypoint[2] != toolFillScript {
		t.Errorf("entrypoint = %.60q, want the embedded script run by bash", cfg.Entrypoint)
	}
}

func TestTheFillTrustsTheHostsExtraCA(t *testing.T) {
	cfg := buildToolFillConfig(toolFillSpec(), dockerFlavor(), "/tools", "/etc/acme/proxy-ca.pem", nil, []ToolRequest{{Tool: "node", Version: "22"}})
	if !slices.Contains(cfg.HostConfig.Binds, "/etc/acme/proxy-ca.pem:"+ExtraCAPath+":ro") {
		t.Errorf("binds = %v, want the CA mounted read-only", cfg.HostConfig.Binds)
	}
	if envMap(cfg.Env)[EnvExtraCAFile] != ExtraCAPath {
		t.Errorf("%s is not set, so the script cannot find the CA", EnvExtraCAFile)
	}
}

func TestParseToolFillsReadsEachOutcome(t *testing.T) {
	out := strings.Join([]string{
		"Collecting pip",
		"zoomies-fill installed python 3.12 3.12.7",
		"zoomies-fill present node 22 22.11.0",
		"zoomies-fill skipped dotnet 8.0 setup-dotnet installs into its own folder, not the tool cache",
		"zoomies-fill failed go 1.27 could not download go1.27.1.linux-amd64.tar.gz",
		"zoomies-fill nonsense line",
		"curl: (6) Could not resolve host",
	}, "\n")
	fills, tail := parseToolFills(strings.NewReader(out))
	want := []ToolFill{
		{Tool: "python", Request: "3.12", Outcome: ToolInstalled, Version: "3.12.7"},
		{Tool: "node", Request: "22", Outcome: ToolPresent, Version: "22.11.0"},
		{Tool: "dotnet", Request: "8.0", Outcome: ToolSkipped, Reason: "setup-dotnet installs into its own folder, not the tool cache"},
		{Tool: "go", Request: "1.27", Outcome: ToolFailed, Reason: "could not download go1.27.1.linux-amd64.tar.gz"},
	}
	if !slices.Equal(fills, want) {
		t.Errorf("fills = %+v\nwant %+v", fills, want)
	}
	if !slices.Equal(tail, []string{"Collecting pip", "curl: (6) Could not resolve host"}) {
		t.Errorf("tail = %q", tail)
	}
}

func TestFillToolCacheRunsTheFillInThePoolsToolCache(t *testing.T) {
	shared := t.TempDir()
	var created ContainerCreateRequest
	var removed []string
	f := newFakeEngine(t, map[string]http.HandlerFunc{
		"DELETE " + v + "/containers/{id}": func(w http.ResponseWriter, r *http.Request) {
			removed = append(removed, r.PathValue("id"))
			writeJSON(w, http.StatusNotFound, map[string]string{"message": "no such container"})
		},
		"GET " + v + "/images/{ref...}": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusOK, map[string]any{"Id": "sha256:cached", "RepoDigests": []string{"ghcr.io/eyupio/zoomies-runner@sha256:abc"}})
		},
		"POST " + v + "/containers/create": func(w http.ResponseWriter, r *http.Request) {
			_ = json.NewDecoder(r.Body).Decode(&created)
			writeJSON(w, http.StatusCreated, map[string]any{"Id": "fill1"})
		},
		"POST " + v + "/containers/fill1/start": func(w http.ResponseWriter, r *http.Request) {
			w.WriteHeader(http.StatusNoContent)
		},
		"POST " + v + "/containers/fill1/wait": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusOK, map[string]any{"StatusCode": 0})
		},
		"GET " + v + "/containers/fill1/json": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusOK, map[string]any{"Id": "fill1", "Config": map[string]any{"Tty": false}})
		},
		"GET " + v + "/containers/fill1/logs": func(w http.ResponseWriter, r *http.Request) {
			w.Header().Set("Content-Type", "application/vnd.docker.multiplexed-stream")
			_, _ = w.Write(frame(1, "zoomies-fill installed node 22 22.11.0\n"))
			_, _ = w.Write(frame(1, "zoomies-fill skipped java 17 only the temurin distribution is filled, and this asks for zulu\n"))
		},
	})
	b := dockerBackendFor(t, f, DockerOptions{SharedDir: shared})

	ctx, cancel := context.WithTimeout(context.Background(), 10e9)
	defer cancel()
	fills, err := b.FillToolCache(ctx, toolFillSpec(), []ToolRequest{{Tool: "node", Version: "22"}, {Tool: "java", Version: "17", Distribution: "zulu"}})
	if err != nil {
		t.Fatalf("FillToolCache: %v", err)
	}
	if len(fills) != 2 || fills[0].Version != "22.11.0" || fills[1].Outcome != ToolSkipped {
		t.Errorf("fills = %+v", fills)
	}
	// The folder a runner of this pool is bound, created before the daemon is
	// asked to bind it, or the daemon makes it root's.
	resolved := toolFillSpec()
	resolved.Image = created.Image
	dir, _ := toolCacheDir(resolved, shared)
	if fi, err := os.Stat(dir); err != nil || !fi.IsDir() {
		t.Fatalf("the tool cache folder was not created: %v", err)
	}
	if !slices.Contains(created.HostConfig.Binds, dir+":"+RunnerToolCacheMount) {
		t.Errorf("binds = %v, want %s", created.HostConfig.Binds, dir)
	}
	// Removed before, in case a cancelled fill left one, and after.
	if len(removed) != 2 || removed[0] != "zoomies-toolfill-v2-pool-1-75ea1320805b60dd113424f239f9236f" {
		t.Errorf("removed = %v", removed)
	}
}

func TestFillToolCacheRefusesAPoolWithoutAToolCache(t *testing.T) {
	b := &DockerBackend{sharedDir: t.TempDir(), log: quietLogger()}
	spec := toolFillSpec()
	spec.Cache.Tools = false
	if _, err := b.FillToolCache(context.Background(), spec, []ToolRequest{{Tool: "go", Version: "1.27"}}); err == nil ||
		!strings.Contains(err.Error(), "keeps no tool cache") {
		t.Fatalf("err = %v, want one saying the pool keeps no tool cache", err)
	}
}

// Waiting on a container is the one Engine call with no natural end, so it
// has no default deadline to fall back on either: the caller must give one.
func TestContainerWaitNeedsADeadline(t *testing.T) {
	c, err := NewAPIClient("tcp://127.0.0.1:1")
	if err != nil {
		t.Fatal(err)
	}
	if _, err := c.ContainerWait(context.Background(), "c1"); err == nil || !strings.Contains(err.Error(), "deadline") {
		t.Fatalf("ContainerWait without a deadline = %v, want a refusal", err)
	}
}

package backup

import (
	"archive/tar"
	"bufio"
	"bytes"
	"compress/gzip"
	"context"
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"encoding/binary"
	"errors"
	"fmt"
	"io"
	"os"
	"path"
	"path/filepath"
	"strings"
	"time"

	"golang.org/x/crypto/argon2"
)

// A backup leaves the machine as one file, because that is what a browser
// downloads and what an operator copies somewhere else: a gzipped tar of the
// backup's directory, holding the manifest, the database and -- only when the
// backup was taken with it -- the key.
//
// The archive is optionally wrapped in passphrase encryption, and the wrapping
// is deliberately a separate layer with its own magic rather than a flag in
// the manifest: an encrypted file has to be recognisable as one before
// anything inside it can be read, and a plain archive has to keep working with
// nothing but tar.

// The members an archive may carry, in the order they are written. Anything
// else is refused on the way in: an archive is written by this package and
// read by this package, and a member it did not write is a member somebody
// else put there.
var archiveMembers = []string{ManifestName, DBName, KeyName}

// memberName says which of archiveMembers the header names, or "" when it
// names none of them. The string returned is the package's own constant, never
// the header's: the only name that ever reaches the filesystem is one this
// package wrote, so a hand-made archive cannot choose a path however it spells
// its members. A directory prefix is allowed, because WriteArchive puts the
// members under one; a path that climbs, or an absolute one, is not.
func memberName(hdr *tar.Header) string {
	clean := path.Clean(strings.ReplaceAll(hdr.Name, "\\", "/"))
	if strings.HasPrefix(clean, "..") || path.IsAbs(clean) {
		return ""
	}
	base := path.Base(clean)
	for _, member := range archiveMembers {
		if member == base {
			return member
		}
	}
	return ""
}

// ArchiveName is the file name a backup downloads as.
func ArchiveName(id string, encrypted bool) string {
	name := id + ".tar.gz"
	if encrypted {
		name += EncryptedExt
	}
	return name
}

// WriteArchive writes the backup's directory to w as a gzipped tar. The
// members sit under a directory named for the backup, so extracting it by
// hand gives the same layout `zoomies restore` takes.
func WriteArchive(w io.Writer, entry *Entry) error {
	gz := gzip.NewWriter(w)
	tw := tar.NewWriter(gz)
	// The manifest first, so a reader that wants only the description does
	// not have to read the database to reach it.
	for _, name := range archiveMembers {
		p := filepath.Join(entry.Dir, name)
		info, err := os.Stat(p)
		if errors.Is(err, os.ErrNotExist) {
			continue
		}
		if err != nil {
			return fmt.Errorf("backup: reading %s: %w", p, err)
		}
		hdr := &tar.Header{
			Name:    entry.ID + "/" + name,
			Mode:    0o600,
			Size:    info.Size(),
			ModTime: info.ModTime(),
			Format:  tar.FormatPAX,
		}
		if err := tw.WriteHeader(hdr); err != nil {
			return err
		}
		f, err := os.Open(p)
		if err != nil {
			return err
		}
		// io.CopyN rather than io.Copy: the header promised a size, and a
		// database that grows under the copy would leave a tar the reader
		// cannot parse. The backup's database is never written to, so the
		// two agree; this is the belt to that brace.
		_, err = io.CopyN(tw, f, info.Size())
		f.Close()
		if err != nil {
			return fmt.Errorf("backup: archiving %s: %w", p, err)
		}
	}
	if err := tw.Close(); err != nil {
		return err
	}
	return gz.Close()
}

// UnpackOptions says who brought an archive and where to put it.
type UnpackOptions struct {
	// Source and TakenBy overwrite the manifest's: an uploaded backup is an
	// uploaded backup wherever it was taken.
	Source  string
	TakenBy string
	// MaxBytes bounds the unpacked database, so an archive that claims a
	// terabyte is refused before it fills the disk. Zero is unbounded.
	MaxBytes int64
	// Now is the clock; nil uses the wall clock.
	Now func() time.Time
}

// Unpack reads a gzipped tar written by WriteArchive into a new directory
// under root and returns it, verified.
//
// The archive's own directory name is ignored. The new backup is named for the
// instant its manifest says it was taken, so that an archive downloaded from
// one controller and uploaded to another lands under the name the first one
// gave it, and two uploads of the same file are two directories rather than
// one overwriting the other.
func Unpack(ctx context.Context, root string, r io.Reader, opts UnpackOptions) (*Entry, error) {
	now := opts.Now
	if now == nil {
		now = time.Now
	}
	if err := os.MkdirAll(root, 0o700); err != nil {
		return nil, fmt.Errorf("backup: creating %s: %w", root, err)
	}
	// Into a staging directory first, so a truncated upload never leaves a
	// half backup under a name List would show.
	staging, err := os.MkdirTemp(root, ".upload-*")
	if err != nil {
		return nil, fmt.Errorf("backup: creating a staging directory in %s: %w", root, err)
	}
	defer os.RemoveAll(staging)

	gz, err := gzip.NewReader(r)
	if err != nil {
		return nil, fmt.Errorf("backup: this is not a gzipped archive: %w", err)
	}
	var inflated io.Reader = gz
	if opts.MaxBytes > 0 {
		inflated = &transferLimitReader{r: gz, left: opts.MaxBytes + (3 << 20)}
	}
	tr := tar.NewReader(inflated)
	seen := map[string]bool{}
	for {
		hdr, err := tr.Next()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return nil, fmt.Errorf("backup: reading the archive: %w", err)
		}
		if hdr.Typeflag != tar.TypeReg && hdr.Typeflag != tar.TypeDir {
			return nil, fmt.Errorf("backup: the archive holds %q, which is not a plain file", hdr.Name)
		}
		if hdr.Typeflag == tar.TypeDir {
			continue
		}
		// The member's own name, whatever directory the archive put it in,
		// resolved to the constant this package knows it by.
		name := memberName(hdr)
		if name == "" {
			return nil, fmt.Errorf("backup: the archive holds %q, which is not part of a Zoomies backup", hdr.Name)
		}
		if seen[name] {
			return nil, fmt.Errorf("backup: the archive holds %s twice", name)
		}
		seen[name] = true
		if opts.MaxBytes > 0 && hdr.Size > opts.MaxBytes {
			return nil, fmt.Errorf("backup: %s is %d bytes, over the %d byte limit", name, hdr.Size, opts.MaxBytes)
		}
		if name != DBName && hdr.Size > 1<<20 {
			return nil, fmt.Errorf("backup: metadata member %s exceeds 1 MiB", name)
		}
		dest := filepath.Join(staging, name)
		f, err := os.OpenFile(dest, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
		if err != nil {
			return nil, err
		}
		// Bounded by the header's own size, so a member that lies about
		// itself cannot write past what it declared.
		n, err := io.Copy(f, io.LimitReader(tr, hdr.Size))
		if cerr := f.Close(); err == nil {
			err = cerr
		}
		if err != nil {
			return nil, fmt.Errorf("backup: extracting %s: %w", name, err)
		}
		if n != hdr.Size {
			return nil, fmt.Errorf("backup: %s is truncated: the archive promised %d bytes and held %d", name, hdr.Size, n)
		}
	}
	if _, err := io.Copy(io.Discard, inflated); err != nil {
		return nil, fmt.Errorf("backup: finishing the archive: %w", err)
	}
	if !seen[DBName] {
		return nil, errors.New("backup: the archive holds no database; a Zoomies backup is " + DBName + " and its manifest")
	}

	taken := now().UTC()
	m, err := ReadManifest(staging)
	switch {
	case err == nil:
		if !m.TakenAt.IsZero() {
			taken = m.TakenAt.UTC()
		}
		m.Source = opts.Source
		m.TakenBy = opts.TakenBy
		if err := writeManifest(staging, m); err != nil {
			return nil, err
		}
	case errors.Is(err, os.ErrNotExist):
		// A database with no manifest is still a database. Nothing about it
		// can be checked beyond opening it, and the entry says so.
	default:
		return nil, err
	}

	// Checked before it is given a name, so a broken archive is refused
	// rather than listed.
	probe := &Entry{ID: "upload", Dir: staging, Manifest: m}
	v, err := verifyDir(ctx, probe)
	if err != nil {
		return nil, err
	}
	if !v.OK {
		return nil, fmt.Errorf("backup: the uploaded backup is not usable: %s", strings.Join(v.Problems, "; "))
	}

	dest, err := newDir(root, taken)
	if err != nil {
		return nil, err
	}
	// Rename the members rather than the directory: newDir has already made
	// the destination, and it is the name that has been reserved.
	for name := range seen {
		if err := os.Rename(filepath.Join(staging, name), filepath.Join(dest, name)); err != nil {
			_ = os.RemoveAll(dest)
			return nil, fmt.Errorf("backup: moving %s into place: %w", name, err)
		}
	}
	return Get(root, filepath.Base(dest))
}

// ---------------------------------------------------------------------------
// Passphrase encryption
// ---------------------------------------------------------------------------

// The encrypted form. A backup leaving the machine over a browser download
// may end up on a laptop, in a chat window or in a shared drive, and the
// database inside it holds every account's password hash and every sealed
// credential. The instance key keeps the credentials sealed; this keeps the
// rest.
//
// The format is a header and then chunks:
//
//	magic       "zoomies-backup-enc-v1\n"
//	salt        16 bytes, for the passphrase derivation
//	nonce base  4 bytes, the random half of every chunk's nonce
//	chunks      4-byte big-endian length, then that many bytes of AES-256-GCM
//	            ciphertext (tag included)
//
// The key is argon2id over the passphrase and the salt. Each chunk's nonce is
// the 4-byte base followed by the chunk's 8-byte counter, and its additional
// data says whether it is the last one -- so a file cut short, or one with a
// chunk moved or repeated, fails to open rather than opening as a shorter
// backup. Chunked rather than one GCM call over the whole file because a
// database can be gigabytes, and GCM needs the whole message in memory.
const (
	EncryptedExt   = ".enc"
	encMagic       = "zoomies-backup-enc-v1\n"
	encSaltLen     = 16
	encNonceBase   = 4
	encChunk       = 1 << 20
	encArgonTime   = 3
	encArgonMemory = 64 * 1024 // KiB
	encArgonLanes  = 4
	encKeyLen      = 32
)

// ErrWrongPassphrase is a file that did not open with the passphrase given.
// A wrong passphrase and a tampered file are the same failure here, by design:
// the authentication tag cannot tell them apart and neither can this.
var ErrWrongPassphrase = errors.New("backup: the passphrase does not open this file, or the file has been altered")

// ErrNotEncrypted is a file offered with a passphrase that has no encryption
// header to apply it to.
var ErrNotEncrypted = errors.New("backup: this file is not an encrypted backup")

// IsEncrypted reports whether r begins with the encrypted header, and returns
// a reader that still yields the whole stream, header included.
func IsEncrypted(r io.Reader) (bool, io.Reader) {
	br := bufio.NewReaderSize(r, len(encMagic))
	head, _ := br.Peek(len(encMagic))
	return string(head) == encMagic, br
}

func deriveKey(passphrase string, salt []byte) []byte {
	return argon2.IDKey([]byte(passphrase), salt, encArgonTime, encArgonMemory, encArgonLanes, encKeyLen)
}

// NewEncryptor wraps w so that everything written to the returned writer is
// encrypted under passphrase. Close writes the final chunk and must be called,
// or the file is truncated and will not open.
func NewEncryptor(w io.Writer, passphrase string) (io.WriteCloser, error) {
	if strings.TrimSpace(passphrase) == "" {
		return nil, errors.New("backup: a passphrase is needed to encrypt")
	}
	salt := make([]byte, encSaltLen)
	base := make([]byte, encNonceBase)
	if _, err := rand.Read(salt); err != nil {
		return nil, err
	}
	if _, err := rand.Read(base); err != nil {
		return nil, err
	}
	aead, err := newAEAD(passphrase, salt)
	if err != nil {
		return nil, err
	}
	if _, err := w.Write([]byte(encMagic)); err != nil {
		return nil, err
	}
	if _, err := w.Write(salt); err != nil {
		return nil, err
	}
	if _, err := w.Write(base); err != nil {
		return nil, err
	}
	return &encWriter{w: w, aead: aead, base: base, buf: make([]byte, 0, encChunk)}, nil
}

func newAEAD(passphrase string, salt []byte) (cipher.AEAD, error) {
	block, err := aes.NewCipher(deriveKey(passphrase, salt))
	if err != nil {
		return nil, err
	}
	return cipher.NewGCM(block)
}

type encWriter struct {
	w       io.Writer
	aead    cipher.AEAD
	base    []byte
	buf     []byte
	counter uint64
	closed  bool
}

func (e *encWriter) Write(p []byte) (int, error) {
	if e.closed {
		return 0, errors.New("backup: write after close")
	}
	written := 0
	for len(p) > 0 {
		room := encChunk - len(e.buf)
		n := min(room, len(p))
		e.buf = append(e.buf, p[:n]...)
		p = p[n:]
		written += n
		if len(e.buf) == encChunk {
			if err := e.flush(false); err != nil {
				return written, err
			}
		}
	}
	return written, nil
}

// Close seals whatever is buffered as the final chunk. The final chunk may be
// empty, and is written even so: it is what tells the reader the file ended
// where the writer meant it to.
func (e *encWriter) Close() error {
	if e.closed {
		return nil
	}
	e.closed = true
	return e.flush(true)
}

func (e *encWriter) flush(final bool) error {
	nonce, aad := chunkNonce(e.base, e.counter, final)
	sealed := e.aead.Seal(nil, nonce, e.buf, aad)
	var length [4]byte
	binary.BigEndian.PutUint32(length[:], uint32(len(sealed)))
	if _, err := e.w.Write(length[:]); err != nil {
		return err
	}
	if _, err := e.w.Write(sealed); err != nil {
		return err
	}
	e.counter++
	e.buf = e.buf[:0]
	return nil
}

func chunkNonce(base []byte, counter uint64, final bool) (nonce, aad []byte) {
	nonce = make([]byte, encNonceBase+8)
	copy(nonce, base)
	binary.BigEndian.PutUint64(nonce[encNonceBase:], counter)
	aad = make([]byte, 9)
	binary.BigEndian.PutUint64(aad, counter)
	if final {
		aad[8] = 1
	}
	return nonce, aad
}

// NewDecryptor wraps r, which must begin with the encrypted header, so that
// reading from the returned reader yields the plaintext. A wrong passphrase is
// reported on the first read, not on open: nothing in the header proves a
// passphrase, only a chunk does.
func NewDecryptor(r io.Reader, passphrase string) (io.Reader, error) {
	head := make([]byte, len(encMagic)+encSaltLen+encNonceBase)
	if _, err := io.ReadFull(r, head); err != nil {
		return nil, ErrNotEncrypted
	}
	if string(head[:len(encMagic)]) != encMagic {
		return nil, ErrNotEncrypted
	}
	salt := head[len(encMagic) : len(encMagic)+encSaltLen]
	base := head[len(encMagic)+encSaltLen:]
	aead, err := newAEAD(passphrase, salt)
	if err != nil {
		return nil, err
	}
	return &decReader{r: bufio.NewReader(r), aead: aead, base: base}, nil
}

type decReader struct {
	r       *bufio.Reader
	aead    cipher.AEAD
	base    []byte
	counter uint64
	plain   bytes.Reader
	done    bool
}

func (d *decReader) Read(p []byte) (int, error) {
	for d.plain.Len() == 0 {
		if d.done {
			return 0, io.EOF
		}
		if err := d.next(); err != nil {
			return 0, err
		}
	}
	return d.plain.Read(p)
}

// next opens one chunk. Either nonce variant is tried -- the final flag is in
// the additional data, so an ordinary chunk and a final one differ only there
// -- and a chunk that opens as neither is the wrong passphrase or a file that
// has been altered.
func (d *decReader) next() error {
	var length [4]byte
	if _, err := io.ReadFull(d.r, length[:]); err != nil {
		if errors.Is(err, io.EOF) {
			return errors.New("backup: the encrypted file ends before its final chunk; it was cut short")
		}
		return err
	}
	n := binary.BigEndian.Uint32(length[:])
	if n > encChunk+uint32(d.aead.Overhead()) {
		return ErrWrongPassphrase
	}
	sealed := make([]byte, n)
	if _, err := io.ReadFull(d.r, sealed); err != nil {
		return errors.New("backup: the encrypted file ends inside a chunk; it was cut short")
	}
	for _, final := range []bool{false, true} {
		nonce, aad := chunkNonce(d.base, d.counter, final)
		plain, err := d.aead.Open(nil, nonce, sealed, aad)
		if err != nil {
			continue
		}
		d.counter++
		d.plain.Reset(plain)
		d.done = final
		if final {
			if _, err := d.r.Peek(1); !errors.Is(err, io.EOF) {
				if err != nil {
					return err
				}
				return errors.New("backup: bytes follow the encrypted final chunk")
			}
		}
		return nil
	}
	return ErrWrongPassphrase
}

// Package backup is one copy of the database, and everything that has to be
// true about it before it is worth keeping.
//
// It is shared by three callers that used to have one: `zoomies backup` on the
// command line, the controller's own scheduled copies, and the API the settings
// page takes a backup through. One implementation is the point. A copy taken
// automatically is restorable by exactly the command that restores one taken by
// hand, and a manifest written by the controller says the same things in the
// same fields as one written on a host where the controller will not start.
//
// A backup here is a directory: the database, copied with VACUUM INTO so that
// it is one whole file with no write-ahead log beside it, and a manifest saying
// which build wrote it, how far the schema had got, which encryption key opens
// it, what that key is needed for, and what the instance was configured to be.
// The encryption key itself is never in there unless it was asked for, because
// a backup that carries its own key is a credential rather than a copy.
package backup

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"runtime"
	"slices"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/cryptox"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/version"
)

// ManifestVersion is the manifest's own shape number. It moves when a field is
// removed or renamed, not when one is added.
const ManifestVersion = 1

// The names inside one backup directory. They are fixed rather than derived
// from the instance, so a restore takes a directory and nothing else, and so an
// operator looking at an unlabelled folder can tell what it is.
const (
	// DBName and DirPrefix are the store's, because it writes this layout
	// itself before a migration: one naming for one thing, so a copy taken
	// automatically is restorable by the command that restores one taken by
	// hand.
	DBName    = store.BackupDBName
	DirPrefix = store.BackupDirPrefix

	ManifestName = "manifest.json"
	KeyName      = "encryption.key"

	// DefaultDirName is the directory beside the database where backups go
	// when nothing says otherwise. Beside the database rather than in a
	// temporary directory, because the one property a backup needs is to
	// survive the process that took it, and on a container deployment the
	// state directory is the mounted volume.
	DefaultDirName = "backups"
)

// Where a backup came from. It is recorded in the manifest so that a list of
// backups can say which were the operator's own and which the controller
// took, and so that retention can be told to leave the former alone.
const (
	SourceCLI          = "cli"
	SourceManual       = "manual"
	SourceScheduled    = "scheduled"
	SourceUploaded     = "uploaded"
	SourcePreMigration = "pre-migration"
	// SourceUpgrade is the copy an upgrade takes before it changes anything.
	// It is its own source so a list can tell an operator's own copies from
	// the fleet's, and so retention treats it as one of the fleet's own
	// copies rather than as a file somebody carried here.
	SourceUpgrade = "upgrade"
	// SourceFetched is a copy pulled back out of a remote. It is its own
	// source rather than "uploaded" because the two are answers to different
	// questions on the day they matter: an uploaded backup is one a person
	// carried here, and a fetched one is the offsite copy of a fleet that has
	// lost the local ones.
	SourceFetched = "fetched"
)

// ErrNotFound is a backup id that names nothing in the directory.
var ErrNotFound = errors.New("backup: no such backup")

// ErrInvalidID is a backup id that is not the shape this package writes. It is
// refused before anything touches the filesystem, because the id becomes a
// path component and this is the one place a path traversal could start.
var ErrInvalidID = errors.New("backup: not a backup id")

// idPattern is the directory name Take writes: the prefix, the instant, and a
// counter when two were taken inside one second.
var idPattern = regexp.MustCompile(`^` + regexp.QuoteMeta(DirPrefix) + `\d{8}-\d{6}(-\d+)?$`)

// ValidID reports whether id is a name this package could have written.
func ValidID(id string) bool { return idPattern.MatchString(id) }

// Manifest is what turns a copy of a database into a backup somebody can act
// on months later.
//
// Everything in it answers a question asked during a restore and nowhere else:
// which build wrote this, how far the schema had got, whether the key file in
// my hand is the right one, what the key is needed for at all, and what this
// instance was configured to be. None of it can be recovered from the database
// file itself once the instance that produced it is gone.
type Manifest struct {
	Transfer        *TransferInfo   `json:"transfer,omitempty"`
	ManifestVersion int             `json:"manifest_version"`
	TakenAt         time.Time       `json:"taken_at"`
	Source          string          `json:"source,omitempty"`
	TakenBy         string          `json:"taken_by,omitempty"`
	Zoomies         Build           `json:"zoomies"`
	Database        Database        `json:"database"`
	Key             KeyInfo         `json:"key"`
	Secrets         []Secret        `json:"secrets"`
	ConfigPath      string          `json:"config_path,omitempty"`
	Config          json.RawMessage `json:"config,omitempty"`
}

// Build is the build that took the copy. A restore has to run this release or
// a later one: the store refuses a database whose ledger names migrations the
// binary does not have.
type Build struct {
	Version   string `json:"version"`
	Commit    string `json:"commit,omitempty"`
	BuildDate string `json:"build_date,omitempty"`
	Go        string `json:"go"`
	OS        string `json:"os"`
	Arch      string `json:"arch"`
}

// Database describes the copy itself.
type Database struct {
	SourcePath string   `json:"source_path"`
	Bytes      int64    `json:"bytes"`
	SHA256     string   `json:"sha256"`
	Integrity  string   `json:"integrity"`
	Migrations []string `json:"migrations"`
}

// KeyInfo says which key opens this database, and whether it is in the
// backup.
//
// The fingerprint is always here and the key itself is not, unless it was
// asked for. That asymmetry is the whole design: a backup that always carried
// the key would put the database and the thing that decrypts it in one file
// nobody thinks of as a credential, and a backup that said nothing about the
// key would leave an operator holding two files with no way to tell whether
// they belong together.
type KeyInfo struct {
	Fingerprint string `json:"fingerprint"`
	SourcePath  string `json:"source_path,omitempty"`
	Included    bool   `json:"included"`
	// From says where this instance's key came from, because a key passed in
	// the environment has no file to copy and an operator restoring needs to
	// know that is what they are looking for.
	From string `json:"from"`
}

// Secret is one thing in this database that only the key opens. It is a list
// of what will be unreadable without it, never of the secrets themselves.
type Secret struct {
	Kind          string `json:"kind"`
	ID            string `json:"id"`
	Target        string `json:"target,omitempty"`
	AppID         int64  `json:"app_id,omitempty"`
	PrivateKey    bool   `json:"private_key"`
	WebhookSecret bool   `json:"webhook_secret"`
}

// LastMigration is the newest migration the copy had taken, or "" when the
// manifest recorded none.
func (m *Manifest) LastMigration() string {
	if m == nil || len(m.Database.Migrations) == 0 {
		return ""
	}
	return m.Database.Migrations[len(m.Database.Migrations)-1]
}

// DefaultDir is where backups go for a database at dbPath when nothing says
// otherwise.
func DefaultDir(dbPath string) string {
	return filepath.Join(filepath.Dir(dbPath), DefaultDirName)
}

// Dir resolves the backup directory the configuration names, or the default
// beside the database. A relative path in the configuration is relative to
// the database's own directory rather than to wherever the process happened
// to be started from, because "backups" in a unit file and "backups" in a
// terminal would otherwise be two different places.
func Dir(cfg *config.Config) string {
	dir := strings.TrimSpace(cfg.Backup.Directory)
	if dir == "" {
		return DefaultDir(cfg.Database.Path)
	}
	if !filepath.IsAbs(dir) {
		dir = filepath.Join(filepath.Dir(cfg.Database.Path), dir)
	}
	return dir
}

// PreMigrationDir is where the store keeps the copies it takes before
// migrating, for a database at dbPath.
func PreMigrationDir(dbPath string) string {
	return filepath.Join(filepath.Dir(dbPath), store.PreMigrationDir)
}

// TakeOptions says where a copy goes and what to record about it.
type TakeOptions struct {
	// Config is the configuration the copy is of. It names the database, the
	// key, and everything the manifest records the instance as being.
	Config *config.Config
	// Dir is the directory the new backup's own directory is created in.
	// Empty is Dir(Config).
	Dir string
	// IncludeKey copies the encryption key in as well. Convenient and
	// dangerous: the copy then decrypts itself.
	IncludeKey bool
	// Source and TakenBy are recorded in the manifest.
	Source  string
	TakenBy string
	// Now is the clock; nil uses the wall clock.
	Now func() time.Time
}

// Take writes a consistent copy of st into a new timestamped directory and
// returns it, with its manifest read back.
//
// The copy is checked before it is reported, because the moment to find out
// that a backup is unreadable is while the original is still there.
func Take(ctx context.Context, st *store.Store, opts TakeOptions) (*Entry, error) {
	if opts.Config == nil {
		return nil, errors.New("backup: a configuration is needed to say what is being backed up")
	}
	now := opts.Now
	if now == nil {
		now = time.Now
	}
	root := opts.Dir
	if root == "" {
		root = Dir(opts.Config)
	}
	if err := os.MkdirAll(root, 0o700); err != nil {
		return nil, fmt.Errorf("backup: creating %s: %w", root, err)
	}

	taken := now().UTC()
	dest, err := newDir(root, taken)
	if err != nil {
		return nil, err
	}
	// Anything that fails from here leaves a directory with no manifest in
	// it, which List would show as broken. Removing it is right: a half
	// backup is worse than none, because it looks like one.
	ok := false
	defer func() {
		if !ok {
			_ = os.RemoveAll(dest)
		}
	}()

	dbPath := filepath.Join(dest, DBName)
	if err := st.Backup(ctx, dbPath); err != nil {
		return nil, err
	}
	m, err := buildManifest(ctx, opts.Config, dbPath, dest, opts, taken)
	if err != nil {
		return nil, err
	}
	if err := writeManifest(dest, m); err != nil {
		return nil, err
	}
	ok = true
	return Get(root, filepath.Base(dest))
}

// newDir makes the backup's directory, named for the instant it was taken and
// suffixed when that instant is already taken: two backups inside one second
// is what pressing the button twice looks like, and the second must not fail
// or overwrite the first.
func newDir(root string, taken time.Time) (string, error) {
	base := filepath.Join(root, DirPrefix+taken.Format("20060102-150405"))
	for n := 0; n < 1000; n++ {
		dest := base
		if n > 0 {
			dest = fmt.Sprintf("%s-%d", base, n+1)
		}
		err := os.Mkdir(dest, 0o700)
		if err == nil {
			return dest, nil
		}
		if !errors.Is(err, os.ErrExist) {
			return "", fmt.Errorf("backup: creating %s: %w", dest, err)
		}
	}
	return "", fmt.Errorf("backup: %s and a thousand suffixes of it already exist", base)
}

// buildManifest gathers everything the restore will want to know.
func buildManifest(ctx context.Context, cfg *config.Config, dbPath, dest string, opts TakeOptions, taken time.Time) (*Manifest, error) {
	m := &Manifest{
		ManifestVersion: ManifestVersion,
		TakenAt:         taken,
		Source:          opts.Source,
		TakenBy:         opts.TakenBy,
		Zoomies: Build{
			Version: version.Version, Commit: version.Commit, BuildDate: version.Date,
			Go: runtime.Version(), OS: runtime.GOOS, Arch: runtime.GOARCH,
		},
		Database:   Database{SourcePath: cfg.Database.Path},
		ConfigPath: cfg.Path(),
		Secrets:    []Secret{},
	}

	// The copy is checked here rather than trusted, because the moment to find
	// out that a backup is unreadable is while the original is still there.
	copied, err := store.Open(ctx, store.Options{Path: dbPath, ReadOnly: true})
	if err != nil {
		return nil, fmt.Errorf("backup: opening the copy at %s: %w", dbPath, err)
	}
	defer func() { _ = copied.Close() }()
	if err := copied.IntegrityCheck(ctx); err != nil {
		return nil, err
	}
	m.Database.Integrity = "ok"

	applied, err := copied.AppliedMigrations(ctx)
	if err != nil {
		return nil, err
	}
	for _, a := range applied {
		m.Database.Migrations = append(m.Database.Migrations, a.Name)
	}

	info, err := os.Stat(dbPath)
	if err != nil {
		return nil, err
	}
	m.Database.Bytes = info.Size()
	// The digest is for the operator moving this file somewhere else, so a
	// copy that arrived truncated is caught before it is restored rather than
	// after.
	if m.Database.SHA256, err = FileSHA256(dbPath); err != nil {
		return nil, err
	}

	insts, err := copied.ListInstallations(ctx)
	if err != nil {
		return nil, err
	}
	for _, i := range insts {
		if len(i.PrivateKeyEnc) == 0 && len(i.WebhookSecretEnc) == 0 {
			continue
		}
		m.Secrets = append(m.Secrets, Secret{
			Kind: "installation", ID: i.ID, Target: i.Target, AppID: i.AppID,
			PrivateKey: len(i.PrivateKeyEnc) > 0, WebhookSecret: len(i.WebhookSecretEnc) > 0,
		})
	}

	// The offsite destinations an administrator stored are sealed with the
	// same key, so they belong on the same list: restoring this database onto
	// a host holding a different key gives a fleet that cannot reach its own
	// backups, and the manifest is where that is said in advance.
	remotes, err := copied.ListBackupRemotes(ctx)
	if err != nil {
		return nil, err
	}
	for _, r := range remotes {
		if len(r.SecretKeyEnc) == 0 && len(r.PassphraseEnc) == 0 {
			continue
		}
		m.Secrets = append(m.Secrets, Secret{Kind: "backup_remote", ID: r.ID, Target: r.Name})
	}

	if err := describeKey(cfg, dest, opts.IncludeKey, m); err != nil {
		return nil, err
	}

	// The configuration, with every secret absent, so a restore has the
	// record of what this instance was without the backup becoming a place
	// secrets live.
	blob, err := json.Marshal(config.Redacted(cfg))
	if err != nil {
		return nil, err
	}
	m.Config = blob
	return m, nil
}

// describeKey records which key opens this database and, if asked, copies it
// in.
//
// A backup with no secrets in it needs no key, and saying so is better than an
// empty fingerprint that reads like a failure.
func describeKey(cfg *config.Config, dest string, includeKey bool, m *Manifest) error {
	origin, path := cfg.EncryptionKeyOrigin()
	if len(m.Secrets) == 0 && origin == config.KeyNone {
		m.Key.From = "none: nothing in this database is sealed"
		return nil
	}

	if origin == config.KeyFromValue {
		m.Key.From = "the environment or zoomies.yaml"
	} else {
		m.Key.From = "security.encryption_key_file"
		m.Key.SourcePath = path
	}
	key, err := cfg.ResolveEncryptionKey()
	if err != nil {
		// A backup of a database whose key cannot be read is still worth
		// taking, and is exactly the moment to say the key is missing.
		return fmt.Errorf("reading the encryption key so the backup can record which one this is: %w "+
			"(the database has been copied; put the key where security.encryption_key_file points and take the backup again)", err)
	}
	m.Key.Fingerprint = key.Fingerprint()

	if !includeKey {
		return nil
	}
	if path == "" {
		return errors.New("include the key: this instance's key comes from the environment rather than a file, " +
			"so there is nothing to copy; store it wherever you keep the rest of your secrets")
	}
	if err := cryptox.WriteKeyFile(filepath.Join(dest, KeyName), key); err != nil {
		return fmt.Errorf("copying the encryption key into the backup: %w", err)
	}
	m.Key.Included = true
	return nil
}

func writeManifest(dir string, m *Manifest) error {
	raw, err := json.MarshalIndent(m, "", "  ")
	if err != nil {
		return err
	}
	if err := os.WriteFile(filepath.Join(dir, ManifestName), append(raw, '\n'), 0o600); err != nil {
		return fmt.Errorf("backup: writing the manifest: %w", err)
	}
	return nil
}

// ReadManifest reads the manifest beside a backup's database.
func ReadManifest(dir string) (*Manifest, error) {
	raw, err := os.ReadFile(filepath.Join(dir, ManifestName))
	if err != nil {
		return nil, err
	}
	var m Manifest
	if err := json.Unmarshal(raw, &m); err != nil {
		return nil, fmt.Errorf("backup: %s is not a manifest: %w", filepath.Join(dir, ManifestName), err)
	}
	return &m, nil
}

// FileSHA256 is the hex digest of a file's contents.
func FileSHA256(path string) (string, error) {
	f, err := os.Open(path)
	if err != nil {
		return "", err
	}
	defer f.Close()
	h := sha256.New()
	if _, err := io.Copy(h, f); err != nil {
		return "", err
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

// ---------------------------------------------------------------------------
// The directory
// ---------------------------------------------------------------------------

// Entry is one backup as the directory holds it: what List renders and what
// every other operation is addressed to.
type Entry struct {
	// ID is the directory's name, and the only thing a caller needs to name
	// it by.
	ID string `json:"id"`
	// Dir is the directory itself.
	Dir string `json:"-"`
	// TakenAt is from the manifest when there is one, and from the name
	// otherwise, which is what a pre-migration copy has.
	TakenAt time.Time `json:"taken_at"`
	// Source is where it came from; SourcePreMigration for the store's own
	// copies, which have no manifest to say so.
	Source string `json:"source"`
	// Bytes is the database's size, and TotalBytes the whole directory's.
	Bytes      int64 `json:"bytes"`
	TotalBytes int64 `json:"total_bytes"`
	// KeyIncluded says the backup carries the encryption key, and is a
	// credential.
	KeyIncluded bool `json:"key_included"`
	// Manifest is nil when there is none, or none readable; Problem then
	// says which.
	Manifest *Manifest `json:"manifest,omitempty"`
	Problem  string    `json:"problem,omitempty"`
}

// List returns every backup under root, newest first. A directory that has
// the right name but no database in it is not listed: it is not a backup.
//
// A missing root is an empty list rather than an error, because a fleet that
// has never taken a backup has no directory yet and that is not a fault.
func List(root string) ([]Entry, error) {
	entries, err := os.ReadDir(root)
	if errors.Is(err, os.ErrNotExist) {
		return []Entry{}, nil
	}
	if err != nil {
		return nil, fmt.Errorf("backup: reading %s: %w", root, err)
	}
	out := []Entry{}
	for _, e := range entries {
		if !e.IsDir() || !ValidID(e.Name()) {
			continue
		}
		entry, err := describe(root, e.Name())
		if errors.Is(err, ErrNotFound) {
			continue
		}
		if err != nil {
			return nil, err
		}
		out = append(out, *entry)
	}
	// The names carry the timestamp, so sorting them sorts by age without
	// trusting a modification time that a copy between machines rewrites.
	slices.SortFunc(out, func(a, b Entry) int { return strings.Compare(b.ID, a.ID) })
	return out, nil
}

// Get returns one backup by id, or ErrNotFound.
func Get(root, id string) (*Entry, error) {
	if !ValidID(id) {
		return nil, fmt.Errorf("%w: %q", ErrInvalidID, id)
	}
	return describe(root, id)
}

func describe(root, id string) (*Entry, error) {
	dir := filepath.Join(root, id)
	entry := &Entry{ID: id, Dir: dir, TakenAt: takenFromName(id)}
	dbInfo, dbErr := os.Stat(filepath.Join(dir, DBName))
	switch {
	case dbErr == nil:
		entry.Bytes = dbInfo.Size()
	case errors.Is(dbErr, os.ErrNotExist):
		// A directory with a manifest and no database is a backup that lost
		// its half -- listed, so retention can remove it and an operator can
		// see it, and refused by everything that would open it. One with
		// neither is not a backup at all.
		if _, err := os.Stat(filepath.Join(dir, ManifestName)); err != nil {
			return nil, fmt.Errorf("%w: %s", ErrNotFound, id)
		}
		entry.Problem = "the database is missing from this backup; only its manifest is left"
	default:
		return nil, fmt.Errorf("backup: reading %s: %w", dir, dbErr)
	}

	m, err := ReadManifest(dir)
	switch {
	case err == nil:
		entry.Manifest = m
		if !m.TakenAt.IsZero() {
			entry.TakenAt = m.TakenAt
		}
		entry.Source = m.Source
		if entry.Source == "" {
			entry.Source = SourceCLI
		}
		entry.KeyIncluded = m.Key.Included
	case errors.Is(err, os.ErrNotExist):
		// The store's pre-migration copies have no manifest and never did;
		// the name and the database are all there is to say about them.
		entry.Source = SourcePreMigration
	default:
		if entry.Problem == "" {
			entry.Problem = err.Error()
		}
		entry.Source = SourceCLI
	}
	if _, err := os.Stat(filepath.Join(dir, KeyName)); err == nil {
		entry.KeyIncluded = true
	}

	total := int64(0)
	if files, err := os.ReadDir(dir); err == nil {
		for _, f := range files {
			if info, err := f.Info(); err == nil && !f.IsDir() {
				total += info.Size()
			}
		}
	}
	entry.TotalBytes = total
	return entry, nil
}

// takenFromName reads the instant out of a backup's name.
func takenFromName(id string) time.Time {
	stamp := strings.TrimPrefix(id, DirPrefix)
	if i := strings.Index(stamp[9:], "-"); i >= 0 {
		stamp = stamp[:9+i]
	}
	t, err := time.Parse("20060102-150405", stamp)
	if err != nil {
		return time.Time{}
	}
	return t
}

// Delete removes one backup. It removes only a directory this package names
// and that holds a database, so an id pointing at anything else is refused
// before anything is deleted.
func Delete(root, id string) error {
	entry, err := Get(root, id)
	if err != nil {
		return err
	}
	if err := os.RemoveAll(entry.Dir); err != nil {
		return fmt.Errorf("backup: removing %s: %w", entry.Dir, err)
	}
	return nil
}

// Prune deletes all but the newest keep backups under root and returns the
// ids it removed. Zero keeps every one.
//
// It only ever removes a directory this package made: the name has to match
// and a manifest has to be inside it. Retention that guessed would eventually
// delete the wrong thing, and the directory an operator points at is often
// shared with somebody else's copies. Uploaded and fetched backups are kept
// too: retention is for the copies the fleet takes of itself, and a file
// somebody carried here -- or pulled back out of a bucket -- is here for a
// reason that retention does not know about.
func Prune(root string, keep int) ([]string, error) {
	if keep <= 0 {
		return nil, nil
	}
	all, err := List(root)
	if err != nil {
		return nil, err
	}
	var ours []Entry
	for _, e := range all {
		if e.Manifest == nil || e.Source == SourceUploaded || e.Source == SourceFetched {
			continue
		}
		ours = append(ours, e)
	}
	if len(ours) <= keep {
		return nil, nil
	}
	var removed []string
	for _, e := range ours[keep:] {
		if err := os.RemoveAll(e.Dir); err != nil {
			return removed, fmt.Errorf("backup: removing the old backup %s: %w", e.ID, err)
		}
		removed = append(removed, e.ID)
	}
	return removed, nil
}

// ---------------------------------------------------------------------------
// Verification
// ---------------------------------------------------------------------------

// Verification is what re-reading a backup found.
type Verification struct {
	CheckedAt time.Time `json:"checked_at"`
	// OK is every check below passing.
	OK bool `json:"ok"`
	// Integrity is SQLite's own answer: "ok", or what it found.
	Integrity string `json:"integrity"`
	// DigestMatches says the file is byte for byte what the manifest
	// recorded. False on a backup with no manifest to compare against, and
	// DigestKnown says whether the comparison was possible at all.
	DigestKnown   bool `json:"digest_known"`
	DigestMatches bool `json:"digest_matches"`
	// SchemaReadable says this build can open it: a backup from a newer
	// release is sound and still not restorable here.
	SchemaReadable bool `json:"schema_readable"`
	// Migrations is how many the copy has taken, and Latest the newest.
	Migrations int    `json:"migrations"`
	Latest     string `json:"latest,omitempty"`
	// Problems is every check that failed, in words.
	Problems []string `json:"problems"`
}

// Verify opens a backup's database and asks it the questions a restore would.
//
// It is what makes a backup a backup rather than a file: a copy nobody has
// opened is a copy nobody knows about, and an operator who verifies the copies
// in the corner finds the bad one before the day it is needed.
func Verify(ctx context.Context, root, id string) (*Verification, error) {
	entry, err := Get(root, id)
	if err != nil {
		return nil, err
	}
	return verifyDir(ctx, entry)
}

func verifyDir(ctx context.Context, entry *Entry) (*Verification, error) {
	v := &Verification{CheckedAt: time.Now().UTC(), Problems: []string{}}
	dbPath := filepath.Join(entry.Dir, DBName)

	if entry.Manifest != nil && entry.Manifest.Database.SHA256 != "" {
		v.DigestKnown = true
		sum, err := FileSHA256(dbPath)
		if err != nil {
			return nil, err
		}
		v.DigestMatches = sum == entry.Manifest.Database.SHA256
		if !v.DigestMatches {
			v.Problems = append(v.Problems, "the database is not the file the manifest recorded: its digest has changed, so it was altered or truncated after it was taken")
		}
	}

	st, err := store.Open(ctx, store.Options{Path: dbPath, ReadOnly: true})
	if err != nil {
		if errors.Is(err, store.ErrSchemaNewer) {
			v.SchemaReadable = false
			v.Integrity = "not checked"
			v.Problems = append(v.Problems, "this backup was written by a newer release than "+version.Short()+": "+err.Error())
		} else {
			v.Integrity = "unreadable"
			v.Problems = append(v.Problems, "the database does not open: "+err.Error())
		}
		v.OK = false
		return v, nil
	}
	defer func() { _ = st.Close() }()
	v.SchemaReadable = true

	if err := st.IntegrityCheck(ctx); err != nil {
		v.Integrity = err.Error()
		v.Problems = append(v.Problems, err.Error())
	} else {
		v.Integrity = "ok"
	}
	if applied, err := st.AppliedMigrations(ctx); err == nil {
		v.Migrations = len(applied)
		if n := len(applied); n > 0 {
			v.Latest = applied[n-1].Name
		}
	}
	v.OK = len(v.Problems) == 0
	return v, nil
}

