func TestACompleteExportRequiresTheSourceFence(t *testing.T) {
	cfg, st, _ := host(t)
	var out bytes.Buffer
	if err := WriteTransfer(context.Background(), st, cfg, transferPassphrase, &out); err == nil {
		t.Fatal("unfenced source exported")
