import (
	"bytes"
	"encoding/json"
	"os"
	"regexp"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/kennel"
)

// The embedded catalog is a build product checked into the tree, like the
// OpenAPI document and the image catalogue, so that the binary serves exactly
// what the site publishes. This test is what makes a stale copy a failure
// rather than a surprise: it rebuilds the catalog from the page and the
// registry and compares, ignoring only the commit the generator stamped.
func TestTheCatalogIsCurrent(t *testing.T) {
	md, err := os.ReadFile("../../docs/problem-codes.md")
	if err != nil {
		t.Fatal(err)
	}
	fresh, err := Build(md, kennel.Checks(), "")
	if err != nil {
		t.Fatal(err)
	}
	want, err := Marshal(fresh)
	if err != nil {
		t.Fatal(err)
	}
	got := blankCommit(t, Embedded())
	if !bytes.Equal(got, want) {
		t.Fatalf("internal/catalog/catalog.json is out of date; run `make generate` from the repository root and commit the result")
	}
}

// blankCommit returns the catalog bytes with generated_from set to "", so a
// rebase that changes nothing but the commit does not fail the build.
func blankCommit(t *testing.T, b []byte) []byte {
	t.Helper()
	var c Catalog
	if err := json.Unmarshal(b, &c); err != nil {
		t.Fatal(err)
	}
	c.GeneratedFrom = ""
	out, err := Marshal(&c)
	if err != nil {
		t.Fatal(err)
	}
	return out
}

// schema.json is published beside the catalog for readers who validate with a
// JSON Schema tool. Nothing here validates with one -- that would be a
// dependency for a test -- so this test holds the two to the same shape by
// hand: the enums, the required keys and the rule that an entry carries no
// key the schema does not name.
func TestTheCatalogMatchesItsSchema(t *testing.T) {
	schema := readJSON(t, "schema.json")
	entrySchema := schema["$defs"].(map[string]any)["entry"].(map[string]any)
	properties := entrySchema["properties"].(map[string]any)
	enum := func(key string) map[string]bool {
		out := map[string]bool{}
		for _, v := range properties[key].(map[string]any)["enum"].([]any) {
			out[v.(string)] = true
		}
		return out
	}
	kinds, categories, detections := enum("kind"), enum("category"), enum("detection")
	var doc struct {
		Entries []map[string]any `json:"entries"`
	}
	if err := json.Unmarshal(Embedded(), &doc); err != nil {
		t.Fatal(err)
	}
	seen := map[string]bool{}
	for _, e := range doc.Entries {
		id, _ := e["id"].(string)
		if seen[id] {
			t.Errorf("%s appears twice", id)
		}
		seen[id] = true
		for key := range e {
			if _, ok := properties[key]; !ok {
				t.Errorf("%s carries %q, which schema.json does not name", id, key)
			}
		}
		for _, r := range entrySchema["required"].([]any) {
			if _, ok := e[r.(string)]; !ok {
				t.Errorf("%s lacks required %q", id, r)
			}
		}
		if !kinds[e["kind"].(string)] || !categories[e["category"].(string)] || !detections[e["detection"].(string)] {
			t.Errorf("%s: kind/category/detection outside the schema's enums: %v %v %v", id, e["kind"], e["category"], e["detection"])
		}
	}
	if len(doc.Entries) < 250 {
		t.Errorf("only %d entries; the page documents far more", len(doc.Entries))
	}
}

func readJSON(t *testing.T, path string) map[string]any {
	t.Helper()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var out map[string]any
	if err := json.Unmarshal(b, &out); err != nil {
		t.Fatalf("%s: %v", path, err)
	}
	return out
}

var checkHeading = regexp.MustCompile("(?m)^### `([a-z_.]+)` \\{ #[a-z_-]+ \\}$")

// The Kennel Club page's check list is generated from the registry between two
// markers, so every check has a heading an anchor can reach and nothing else
// is there.
func TestTheKennelClubPageListsEveryCheck(t *testing.T) {
	b, err := os.ReadFile("../../docs/kennel-club.md")
	if err != nil {
		t.Fatal(err)
	}
	page := string(b)
	begin, end := strings.Index(page, "<!-- zoomies:catalogue-begin -->"), strings.Index(page, "<!-- zoomies:catalogue-end -->")
	if begin < 0 || end < begin {
		t.Fatal("the page has no generated block between the catalogue markers")
	}
	block := page[begin:end]
	found := map[string]bool{}
	for _, m := range checkHeading.FindAllStringSubmatch(block, -1) {
		found[m[1]] = true
	}
	for _, c := range kennel.Checks() {
		if !found[string(c.Code)] {
			t.Errorf("%s has no heading on the page; run `make generate`", c.Code)
		}
		delete(found, string(c.Code))
	}
	for code := range found {
		t.Errorf("the page lists %s, which the registry does not have", code)
	}
}

package catalog

import (
	_ "embed"
	"encoding/json"
)

// catalog.json is written by gen_catalog.go and checked in, so the binary
// serves the same document the site publishes; TestTheCatalogIsCurrent fails
// the build when it falls behind the page or the registry.
//
//go:embed catalog.json
var embedded []byte

// Embedded returns the generated catalog exactly as it was written.
func Embedded() []byte { return embedded }

// Current parses the embedded catalog.
func Current() (*Catalog, error) {
	var c Catalog
	if err := json.Unmarshal(embedded, &c); err != nil {
		return nil, err
	}
	return &c, nil
}

// Marshal renders a catalog the one way it is ever written, so the generator,
// the test that checks it and anything that rewrites it agree byte for byte.
func Marshal(c *Catalog) ([]byte, error) {
	b, err := json.MarshalIndent(c, "", "  ")
	if err != nil {
		return nil, err
	}
	return append(b, '\n'), nil
}

//go:build ignore

// Command gen_catalog writes the catalog of problem codes and Kennel checks
// into internal/catalog/catalog.json, where the binary embeds it and the docs
// site publishes it from, and the check list on docs/kennel-club.md.
//
// Run it from the repository root after editing docs/problem-codes.md or the
// Kennel registry:
//
//	go run internal/catalog/gen_catalog.go
//
// TestTheCatalogIsCurrent and TestTheKennelClubPageListsEveryCheck fail,
// naming this command, when either file has drifted.
package main

import (
	"fmt"
	"log"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/eyupio/zoomies/internal/catalog"
	"github.com/eyupio/zoomies/internal/kennel"
)

const (
	beginMarker = "<!-- zoomies:catalogue-begin -->"
	endMarker   = "<!-- zoomies:catalogue-end -->"
)

func main() {
	root, err := repoRoot()
	if err != nil {
		log.Fatal(err)
	}
	md, err := os.ReadFile(filepath.Join(root, "docs", "problem-codes.md"))
	if err != nil {
		log.Fatal(err)
	}
	c, err := catalog.Build(md, kennel.Checks(), gitHead(root))
	if err != nil {
		log.Fatal(err)
	}
	b, err := catalog.Marshal(c)
	if err != nil {
		log.Fatal(err)
	}
	out := filepath.Join(root, "internal", "catalog", "catalog.json")
	if err := os.WriteFile(out, b, 0o644); err != nil {
		log.Fatal(err)
	}
	fmt.Printf("wrote %s (%d entries)\n", out, len(c.Entries))

	page := filepath.Join(root, "docs", "kennel-club.md")
	if err := rewriteBlock(page, checksBlock(kennel.Checks())); err != nil {
		log.Fatal(err)
	}
	fmt.Printf("rewrote the check list on %s\n", page)
}

// checksBlock is one heading per check, so a link can land on it, and a
// definition list under each, because a table row has no anchor of its own.
func checksBlock(checks []kennel.Check) string {
	var b strings.Builder
	for _, c := range checks {
		// toc's slug would drop the dot (cino_timeout); the attr_list id is the
		// one the registry's Docs field and the catalog's links name.
		fmt.Fprintf(&b, "### `%s` { #%s }\n\n", c.Code, strings.ReplaceAll(string(c.Code), ".", "-"))
		fmt.Fprintf(&b, "Area\n:   %s\n\n", c.Area)
		fmt.Fprintf(&b, "Severity\n:   %s\n\n", c.Severity)
		fmt.Fprintf(&b, "Detects\n:   %s\n\n", c.Detects)
		fmt.Fprintf(&b, "Fix\n:   %s\n\n", c.Fix)
		fmt.Fprintf(&b, "Verify\n:   %s\n\n", c.Verify)
	}
	return b.String()
}

func rewriteBlock(path, body string) error {
	raw, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	s := string(raw)
	begin := strings.Index(s, beginMarker)
	end := strings.Index(s, endMarker)
	if begin < 0 || end < begin {
		return fmt.Errorf("%s: no %s / %s block to rewrite", path, beginMarker, endMarker)
	}
	s = s[:begin+len(beginMarker)] + "\n\n" + body + s[end:]
	return os.WriteFile(path, []byte(s), 0o644)
}

func gitHead(root string) string {
	cmd := exec.Command("git", "rev-parse", "--short", "HEAD")
	cmd.Dir = root
	out, err := cmd.Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(out))
}

// repoRoot finds the directory holding go.mod, so the command works from the
// root or from this package's directory.
func repoRoot() (string, error) {
	dir, err := os.Getwd()
	if err != nil {
		return "", err
	}
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return dir, nil
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", fmt.Errorf("no go.mod above %s", dir)
		}
		dir = parent
	}
}

package catalog

import (
	"bufio"
	"bytes"
	"errors"
	"regexp"
	"strconv"
	"strings"
)

// The problem-codes page is a sequence of sections, each with one table whose
// header names its columns. The columns differ by section -- a configuration
// code names its setting, a runtime code does not, some tables split "what it
// means" from "what to do" and some do not -- so a row is read by its header's
// names rather than by position, and a table that gains a column needs a name
// here and nothing else.
const (
	colCode     = "code"
	colSeverity = "severity"
	colSetting  = "setting"
	colWhatToDo = "what to do"
	colMeaning  = "what it means"
	colVerify   = "how to see it worked"
	colStatus   = "what the status page says"
)

// sectionCategories is what each section's codes are about. Every
// "Configuration:" heading is configuration; the rest are named one by one, and
// a heading not listed here fails the build, so a new section is placed on
// purpose rather than landing somewhere by default.
var sectionCategories = map[string]Category{
	"Runtime: hosts and installations":  CategoryReliability,
	"Runtime: pools, jobs and runners":  CategoryCapacity,
	"Runtime: infrastructure providers": CategoryReliability,
	"A provider's preflight":            CategoryConfiguration,
}

// codeOverrides place a code by what it is about when its section's category
// would mislead: a dangerous toggle is a security matter wherever it is
// documented, and the one piece of advice about money is cost.
var codeOverrides = []struct {
	prefix   string
	category Category
}{
	{"security.", CategorySecurity},
	{"oidc.", CategorySecurity},
	{"pool.dangerous", CategorySecurity},
	{"pool.cache_shared", CategorySecurity},
	{"jobs.label_advice", CategoryCost},
}

var codeCell = regexp.MustCompile("`([a-z0-9_.]+)`")

// ParseProblemTables reads every code row on the page into an entry, attaching
// the status page's sentence to the entry it repeats rather than adding one.
func ParseProblemTables(markdown []byte) ([]Entry, error) {
	var (
		entries  []Entry
		index    = map[string]int{}
		section  string
		headers  []string
		inStatus bool
	)
	sc := bufio.NewScanner(bytes.NewReader(markdown))
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	for sc.Scan() {
		line := sc.Text()
		switch {
		case strings.HasPrefix(line, "## "):
			section = strings.TrimSpace(strings.TrimPrefix(line, "## "))
			headers = nil
			inStatus = false
		case strings.HasPrefix(line, "| ") && headers == nil:
			headers = splitRow(line)
			for i := range headers {
				headers[i] = strings.ToLower(headers[i])
			}
			if headers[0] != colCode {
				// A table that is not keyed by code, such as the severity legend.
				headers = nil
				continue
			}
			inStatus = len(headers) == 2 && headers[1] == colStatus
		case strings.HasPrefix(line, "| `") && headers != nil:
			cells := splitRow(line)
			if len(cells) != len(headers) {
				return nil, errors.New("catalog: a row in " + section + " has " + strconv.Itoa(len(cells)) + " cells under " + strconv.Itoa(len(headers)) + " headers: " + line)
			}
			m := codeCell.FindStringSubmatch(cells[0])
			if m == nil {
				return nil, errors.New("catalog: no code in row: " + line)
			}
			id := m[1]
			byName := map[string]string{}
			for i, h := range headers {
				byName[h] = cells[i]
			}
			if inStatus {
				i, ok := index[id]
				if !ok {
					return nil, errors.New("catalog: the status page names " + id + ", which no table above documents")
				}
				s := byName[colStatus]
				entries[i].StatusSentence = &s
				continue
			}
			if _, dup := index[id]; dup {
				return nil, errors.New("catalog: " + id + " is documented twice")
			}
			e, err := problemEntry(id, section, byName)
			if err != nil {
				return nil, err
			}
			index[id] = len(entries)
			entries = append(entries, e)
		}
	}
	return entries, sc.Err()
}

func problemEntry(id, section string, cells map[string]string) (Entry, error) {
	category, detection, err := placement(id, section)
	if err != nil {
		return Entry{}, err
	}
	meaning := cells[colMeaning]
	fix := cells[colWhatToDo]
	if meaning == "" {
		// A configuration row says what to do and that is also what it means.
		meaning = fix
	}
	if fix == "" {
		fix = meaning
	}
	anchor := slug(section)
	return Entry{
		ID:        id,
		Kind:      KindProblem,
		Title:     id,
		Category:  category,
		Severity:  strings.ToLower(strings.Trim(cells[colSeverity], "* ")),
		Detection: detection,
		Detects:   meaning,
		Fix:       fix,
		Verify:    nonEmpty(cells[colVerify]),
		Setting:   strings.Trim(cells[colSetting], "` "),
		DocsHTML:  siteBase + "/problem-codes/#" + anchor,
		DocsMD:    repoBase + "/problem-codes.md#" + anchor,
	}, nil
}

func placement(id, section string) (Category, Detection, error) {
	var category Category
	detection := DetectionRuntime
	switch {
	case strings.HasPrefix(section, "Configuration:"):
		category, detection = CategoryConfiguration, DetectionStatic
	case section == "A provider's preflight":
		category, detection = CategoryConfiguration, DetectionStatic
	default:
		c, ok := sectionCategories[section]
		if !ok {
			return "", "", errors.New("catalog: section " + section + " has no category; add it to sectionCategories")
		}
		category = c
	}
	for _, o := range codeOverrides {
		if strings.HasPrefix(id, o.prefix) {
			category = o.category
		}
	}
	return category, detection, nil
}

// splitRow splits a Markdown table row on its unescaped pipes and trims each
// cell, keeping an escaped pipe as the character it stands for.
func splitRow(line string) []string {
	line = strings.TrimSpace(line)
	line = strings.TrimPrefix(line, "|")
	line = strings.TrimSuffix(line, "|")
	const placeholder = "\x00"
	line = strings.ReplaceAll(line, `\|`, placeholder)
	parts := strings.Split(line, "|")
	for i := range parts {
		parts[i] = strings.TrimSpace(strings.ReplaceAll(parts[i], placeholder, "|"))
	}
	return parts
}

var slugDrop = regexp.MustCompile(`[^a-z0-9 -]`)

// slug is the anchor Material gives a heading: lower case, punctuation gone,
// spaces as dashes.
func slug(heading string) string {
	s := strings.ToLower(heading)
	s = slugDrop.ReplaceAllString(s, "")
	s = strings.ReplaceAll(strings.TrimSpace(s), " ", "-")
	return s
}

