package config

import (
	"strings"
	"testing"
	"time"
)

// Update history is what an operator reads to learn why a host is behind, so
// it outlives the job history around it. The floor is there because a value of
// a few seconds is a duration and also an instruction to delete every finished
// attempt on the next pass.
func TestTheRetentionKeyHasAFloor(t *testing.T) {
	if got := Default().Retention.UpdateAttempts; got != 90*24*time.Hour {
		t.Errorf("the default update history window = %s, want 90 days", got)
	}

	for _, tc := range []struct {
		value   string
		wantErr string
	}{
		{"1h", "too short"},
		{"23h", "too short"},
		{"24h", ""},
		{"2160h", ""},
		{"0", ""}, // keep every attempt
	} {
		c := Default()
		_, err := c.SetValueString("retention.update_attempts", tc.value)
		switch {
		case tc.wantErr == "" && err != nil:
			t.Errorf("%q: unexpected error: %v", tc.value, err)
		case tc.wantErr != "" && (err == nil || !strings.Contains(err.Error(), tc.wantErr)):
			t.Errorf("%q: error = %v, want one mentioning %q", tc.value, err, tc.wantErr)
		}
	}

	s, ok := LookupSetting("retention.update_attempts")
	if !ok {
		t.Fatal("retention.update_attempts is not in the settings registry")
	}
	if s.Floor != 24*time.Hour || s.Env != "ZOOMIES_RETENTION_UPDATE_ATTEMPTS" {
		t.Errorf("registry row has floor %s and env %s, want 24h and ZOOMIES_RETENTION_UPDATE_ATTEMPTS", s.Floor, s.Env)
	}
}

// The environment is the last word and the floor is not a courtesy of the
// Settings page: a deployment that sets the variable to an hour must be refused
// at start, naming the variable, and not deleted down to an hour of history.
func TestTheEnvironmentOverrideOfTheRetentionKeyKeepsTheFloor(t *testing.T) {
	override := func(value string) func(string) (string, bool) {
		return func(k string) (string, bool) {
			if k == "ZOOMIES_RETENTION_UPDATE_ATTEMPTS" {
				return value, true
			}
			return "", false
		}
	}

	c := Default()
	err := c.applyEnvFrom(override("1h"))
	if err == nil || !strings.Contains(err.Error(), "ZOOMIES_RETENTION_UPDATE_ATTEMPTS") || !strings.Contains(err.Error(), "too short") {
		t.Fatalf("an hour of update history from the environment: err = %v, want a refusal naming the variable", err)
	}
	if got := c.Retention.UpdateAttempts; got != 90*24*time.Hour {
		t.Errorf("a refused override left the window at %s, want the default 90 days", got)
	}

	c = Default()
	if err := c.applyEnvFrom(override("48h")); err != nil || c.Retention.UpdateAttempts != 48*time.Hour {
		t.Errorf("two days from the environment: window %s, err %v, want 48h and no error", c.Retention.UpdateAttempts, err)
	}
}

package config

import (
	"testing"
	"time"
)

// The runner image refuses a wait outside one second to one hour with a
// configuration exit, and a refused wait is a Docker pool that starts no
// runner at all. The validator has to say so before the fleet finds out.
func TestDockerWaitIsBoundedByWhatTheImageAccepts(t *testing.T) {
	c := Default()
	if c.Runners.DockerWait != 3*time.Minute {
		t.Fatalf("default docker wait = %s, want three minutes for loaded hosts", c.Runners.DockerWait)
	}
	for _, value := range []time.Duration{-time.Second, time.Hour + time.Second, 48 * time.Hour} {
		c.Runners.DockerWait = value
		if !hasCode(c.Validate(), "runners.docker_wait") {
			t.Fatalf("a wait of %s the image would refuse was accepted", value)
		}
	}
	for _, value := range []time.Duration{0, time.Second, 2 * time.Minute, time.Hour} {
		c.Runners.DockerWait = value
		if hasCode(c.Validate(), "runners.docker_wait") {
			t.Fatalf("a wait of %s the image accepts was refused", value)
		}
	}
}

// ZOOMIES_DOCKER_WAIT named the runner image's own whole-seconds wait long
// before runners.docker_wait existed, and an operator's or an embedded
// controller's environment carrying that exact spelling is not a typo to
// refuse: it is read as seconds, on this setting and no other.
func TestDockerWaitEnvAcceptsWholeSecondsForBackwardsCompatibility(t *testing.T) {
	c := Default()
	if _, err := c.SetValueString("runners.docker_wait", "120"); err != nil {
		t.Fatalf("SetValueString(\"120\"): %v", err)
	}
	if c.Runners.DockerWait != 120*time.Second {
		t.Fatalf("runners.docker_wait = %s, want 2m from a bare \"120\"", c.Runners.DockerWait)
	}
	// A duration string still wins in its own right.
	if _, err := c.SetValueString("runners.docker_wait", "3m"); err != nil {
		t.Fatalf("SetValueString(\"3m\"): %v", err)
	}
	if c.Runners.DockerWait != 3*time.Minute {
		t.Fatalf("runners.docker_wait = %s, want 3m", c.Runners.DockerWait)
	}
	// No other duration setting gains this leniency: a bare number elsewhere
	// is still refused, the way an operator setting it is told to expect.
	if _, err := c.SetValueString("scheduler.provision_timeout", "120"); err == nil {
		t.Fatal("scheduler.provision_timeout accepted a bare number")
	}
}

// One value for the whole fleet is wrong for every runner in it when the
// variable is the runner's own name or credentials. Case does not matter:
// the image reads the upper-case name, and a lower-case spelling would not
// be a harmless second variable, it would be a typo that hid the refusal.
func TestRunnerEnvMayNotNameTheRunnerContract(t *testing.T) {
	c := Default()
	c.Runners.Env = map[string]string{"HTTPS_PROXY": "http://proxy:3128", "zoomies_runner_name": "one-name-for-all"}
	fs := c.Validate()
	if !hasCode(fs, "runners.env_reserved") {
		t.Fatal("a fleet-wide runner name was accepted")
	}
	c.Runners.Env = map[string]string{"HTTPS_PROXY": "http://proxy:3128", "GOFLAGS": "-mod=mod"}
	if hasCode(c.Validate(), "runners.env_reserved") {
		t.Fatal("ordinary variables were refused")
	}
}

// The two settings are the page's, not the file's: they are stored, editable,
// and in force without a restart, because the controller reads them when it
// builds each create task.
func TestRunnerSettingsAreStoredAndLive(t *testing.T) {
	for _, key := range []string{"runners.docker_wait", "runners.env"} {
		s, ok := LookupSetting(key)
		if !ok {
			t.Fatalf("%s is not registered", key)
		}
		if !s.Stored() || !s.Live || s.Secret {
			t.Fatalf("%s = %+v, want stored, live and not secret", key, s)
		}
	}
	c := Default()
	if _, err := c.SetValueString("runners.env", "HTTPS_PROXY=http://proxy:3128,NO_PROXY=localhost"); err != nil {
		t.Fatalf("SetValueString: %v", err)
	}
	if c.Runners.Env["NO_PROXY"] != "localhost" {
		t.Fatalf("runners.env = %v", c.Runners.Env)
	}
}

// The size a pool that says nothing gets, and the fleet's right to change it.
//
// It is a setting rather than a constant because the right answer is the shape
// of the machines and the jobs: a fleet of small boxes, or one of compilers,
// says so once here rather than on every pool it creates.
func TestTheDefaultRunnerSizeIsTwoCoresAndFourGigabytes(t *testing.T) {
	c := Default()
	cpus, memoryMB := c.Runners.DefaultRunnerSize()
	if cpus != DefaultRunnerCPUs || memoryMB != DefaultRunnerMemoryMB {
		t.Fatalf("default runner size = %v CPU, %d MB, want %v and %d",
			cpus, memoryMB, DefaultRunnerCPUs, DefaultRunnerMemoryMB)
	}
}

// Zero is not "no limit" here, because no limit is the state this setting
// exists to make unreachable: a runner without one takes the whole machine
// while the fleet charges it one slot's share. Nothing having been said falls
// back to the built-in figures.
func TestAnUnsetDefaultRunnerSizeFallsBackRatherThanMeaningUnlimited(t *testing.T) {
	c := Default()
	c.Runners.DefaultCPUs, c.Runners.DefaultMemoryMB = 0, 0
	cpus, memoryMB := c.Runners.DefaultRunnerSize()
	if cpus != DefaultRunnerCPUs || memoryMB != DefaultRunnerMemoryMB {
		t.Fatalf("an unset default gave %v CPU and %d MB, want the built-in %v and %d",
			cpus, memoryMB, DefaultRunnerCPUs, DefaultRunnerMemoryMB)
	}
}

// A share of a CPU is the one figure in this configuration that is genuinely
// fractional, so the environment has to carry it as one -- rounding it to
// whole cores would take half a core from every operator running small jobs on
// a small machine.
func TestTheDefaultRunnerSizeIsSettableFromTheEnvironment(t *testing.T) {
	t.Setenv("ZOOMIES_RUNNER_DEFAULT_CPUS", "1.5")
	t.Setenv("ZOOMIES_RUNNER_DEFAULT_MEMORY_MB", "3072")

	c := Default()
	if err := c.applyEnv(); err != nil {
		t.Fatalf("applyEnv: %v", err)
	}
	cpus, memoryMB := c.Runners.DefaultRunnerSize()
	if cpus != 1.5 || memoryMB != 3072 {
		t.Fatalf("size from the environment = %v CPU, %d MB, want 1.5 and 3072", cpus, memoryMB)
	}
}

func TestBootstrapGraceDefaultsCanBeOverriddenAndAreBounded(t *testing.T) {
	c := Default()
	c.Agent.Embedded = true
	if c.Agent.BootstrapCPUGrace != 2*time.Minute {
		t.Fatalf("grace = %s", c.Agent.BootstrapCPUGrace)
	}
	t.Setenv("ZOOMIES_AGENT_BOOTSTRAP_CPU_GRACE", "0s")
	if err := c.applyEnv(); err != nil {
		t.Fatal(err)
	}
	if c.Agent.BootstrapCPUGrace != 0 || !hasCode(c.Validate(), "agent.bootstrap_cpu_grace_short") {
		t.Fatal("disabled grace not loaded or explained")
	}
	for _, d := range []time.Duration{-time.Second, 11 * time.Minute} {
		c.Agent.BootstrapCPUGrace = d
		if !hasCode(c.Validate(), "agent.bootstrap_cpu_grace") {
			t.Fatalf("accepted %s", d)
		}
	}
	c.Agent.BootstrapCPUGrace = 2 * time.Minute
	if hasCode(c.Validate(), "agent.bootstrap_cpu_grace_short") {
		t.Fatal("recommended grace warned")
	}
}

package config

import (
	"reflect"
	"testing"
)

// A comma inside a list item or a label value is ordinary: NO_PROXY is a comma
// separated list, and an LDAP-style group name is `CN=Admins,OU=Groups`. The
// stored text joins items with commas, so a value that carried one used to be
// split on the next restart -- the whole runners.env row was refused and the
// fleet silently lost its proxy, or a group name became two groups.
func TestAValueContainingACommaSurvivesItsStoredText(t *testing.T) {
	for _, tc := range []struct {
		key   string
		value any
		text  string
	}{
		{"runners.env", map[string]any{"HTTP_PROXY": "http://proxy:3128", "NO_PROXY": "localhost,127.0.0.1"},
			`HTTP_PROXY=http://proxy:3128,NO_PROXY=localhost\,127.0.0.1`},
		{"runners.env", map[string]any{"FOO": "a,b=c"}, `FOO=a\,b=c`},
		{"oidc.admin_groups", []any{"CN=Admins,OU=Groups", "plain"}, `CN=Admins\,OU=Groups,plain`},
		{"agent.labels", map[string]any{"path": `C:\tools\,x`}, `path=C:\\tools\\\,x`},
		{"oidc.scopes", []any{`ends-with-backslash\`, "next"}, `ends-with-backslash\\,next`},
	} {
		s, ok := LookupSetting(tc.key)
		if !ok {
			t.Fatalf("%s: not a setting", tc.key)
		}
		c := Default()
		if _, err := c.SetValue(tc.key, tc.value); err != nil {
			t.Fatalf("%s: %v", tc.key, err)
		}
		before, _ := c.Value(tc.key)
		text := Text(s, before)
		if text != tc.text {
			t.Errorf("%s stored as %q, want %q", tc.key, text, tc.text)
		}
		d := Default()
		if _, err := d.SetValueString(tc.key, text); err != nil {
			t.Errorf("%s: %q does not parse back: %v", tc.key, text, err)
			continue
		}
		after, _ := d.Value(tc.key)
		if !reflect.DeepEqual(before, after) {
			t.Errorf("%s: %#v stored as %q and came back as %#v", tc.key, before, text, after)
		}
	}
}

// Rows written before escaping existed, and environment variables typed by
// hand, hold no backslash-comma or double backslash. They must read exactly as
// they always did, so no migration is needed.
func TestAStoredRowWithoutEscapesReadsAsItAlwaysDid(t *testing.T) {
	c := Default()
	if _, err := c.SetValueString("agent.labels", `path=C:\tools, tier=build`); err != nil {
		t.Fatal(err)
	}
	got, _ := c.Value("agent.labels")
	want := map[string]string{"path": `C:\tools`, "tier": "build"}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("got %#v, want %#v", got, want)
	}
}

package config

import (
	"slices"
	"testing"
)

// The split between the two audiences is a judgement about each key, and the
// judgement is the thing worth holding: a key is the platform's when changing
// it changes what the process binds, trusts, stores, logs or dials from its
// own machine, or how much of that machine it spends. A key added to one of
// these sections without a thought about which audience owns it lands in the
// wrong one, and the first person to find out is an operator who cannot
// change something they could change yesterday.
func TestEverySettingBelongsToTheAudienceItsSectionSays(t *testing.T) {
	// assistant.* is two switches about where this process may dial a model
	// from and whether a private address may be saved for one: the
	// platform's by the rule above, like security.allow_private_egress.
	platformSections := []string{"server", "security", "log", "backup", "retention", "limits", "updates", "capacity_demand", "status", "assistant"}
	// The embedded agent is the controller's own half of agent.*: where this
	// process puts its work and which daemon it dials. The rest of agent.*
	// sizes and labels the fleet's runners.
	platformAgentKeys := map[string]bool{
		"agent.embedded": true, "agent.backend": true,
		"agent.work_dir": true, "agent.docker_host": true,
	}

	for _, st := range Settings() {
		// Bootstrap and local are settled by where they are read, not by
		// whose they are.
		if st.Scope == ScopeBootstrap || st.Scope == ScopeLocal {
			continue
		}
		section := st.Section()
		want := false
		switch {
		case slices.Contains(platformSections, section):
			want = true
		case st.Key == "metrics.public":
			want = true
		case platformAgentKeys[st.Key]:
			want = true
		}
		if got := st.Platform(); got != want {
			whose := map[bool]string{true: "the platform's", false: "the fleet's"}
			t.Errorf("%s is %s, and should be %s", st.Key, whose[got], whose[want])
		}
	}
}

// The scope says who may change a key, not where it lives. If a platform key
// stopped being stored, the export, the import and the file seed would each
// quietly start carrying only half an instance's configuration.
func TestAPlatformSettingIsStoredLikeAnyOther(t *testing.T) {
	var platform int
	for _, st := range Settings() {
		if !st.Platform() {
			continue
		}
		platform++
		if !st.Stored() {
			t.Errorf("%s is the platform's and is not stored; the export would leave it behind", st.Key)
		}
	}
	if platform == 0 {
		t.Fatal("no setting is platform-scoped, so this proves nothing")
	}

	// StoredSettings is what the database layer and the export walk, and it
	// has to carry both audiences.
	var sawPlatform, sawFleet bool
	for _, st := range StoredSettings() {
		if st.Platform() {
			sawPlatform = true
		} else {
			sawFleet = true
		}
	}
	if !sawPlatform || !sawFleet {
		t.Errorf("StoredSettings carries platform=%v fleet=%v; it must carry both", sawPlatform, sawFleet)
	}
}

// A reader of the settings page sees the scope as a word. Keeping the set
// closed means the UI and the OpenAPI enum can be trusted to list them all.
func TestEverySettingHasAKnownScope(t *testing.T) {
	known := map[Scope]bool{ScopeInstance: true, ScopePlatform: true, ScopeBootstrap: true, ScopeLocal: true}
	for _, st := range Settings() {
		if !known[st.Scope] {
			t.Errorf("%s has scope %q, which nothing knows how to render", st.Key, st.Scope)
		}
	}
}

package config

import (
	"reflect"
	"slices"
	"strings"
	"testing"
	"time"
)

// The registry is the one list, so it has to actually cover the struct.
//
// The whole reason it exists is that five hand-maintained lists of the same
// fact had drifted. A sixth that could drift from the struct it describes would
// be no better than the five: a field with no row has no environment variable,
// no place on the settings page and no way into the database, and nothing would
// say so until somebody went looking for a setting that was never there.
func TestEverySettingIsRegistered(t *testing.T) {
	keys := SettingKeys()
	if len(keys) < 80 {
		t.Fatalf("the walk found %d keys, which is fewer than the configuration has", len(keys))
	}

	var unlisted []string
	for _, key := range keys {
		if _, ok := LookupSetting(key); !ok && !unregistered[key] {
			unlisted = append(unlisted, key)
		}
	}
	if len(unlisted) > 0 {
		t.Errorf("these fields of Config have no row in the settings registry:\n  %s\n"+
			"add one, or add the key to `unregistered` with the reason", strings.Join(unlisted, "\n  "))
	}

	// And the reverse: a row naming a field that no longer exists would render
	// a setting on the page that nothing reads.
	for _, s := range Settings() {
		if !slices.Contains(keys, s.Key) {
			t.Errorf("the registry has %s, but Config has no such field", s.Key)
		}
	}
}

// Two settings must never share an environment variable: whichever applyEnv
// reached second would silently win, and the other would be a setting that
// cannot be set from the environment at all.
func TestEverySettingHasItsOwnEnvironmentVariable(t *testing.T) {
	seen := map[string]string{}
	for _, s := range Settings() {
		if s.Env == "" {
			t.Errorf("%s has no environment variable, so there is no way past a bad stored value", s.Key)
			continue
		}
		if !strings.HasPrefix(s.Env, "ZOOMIES_") {
			t.Errorf("%s uses %s, which is not a ZOOMIES_* name", s.Key, s.Env)
		}
		if other, dup := seen[s.Env]; dup {
			t.Errorf("%s and %s both use %s", other, s.Key, s.Env)
		}
		seen[s.Env] = s.Key
	}
}

// Every value survives the trip it makes on every restart: out of the
// configuration as text, into a database row, and back.
//
// A value that does not round-trip is a setting that changes itself. The one
// that caught this was oidc.scopes, which reached the database as the Go
// rendering of a slice -- "[openid profile email]" -- and came back as a
// one-item list whose only item was the whole list.
func TestEverySettingRoundTripsThroughItsStoredText(t *testing.T) {
	c := Default()
	for _, s := range Settings() {
		before, err := c.Value(s.Key)
		if err != nil {
			t.Fatalf("%s: %v", s.Key, err)
		}
		text := Text(s, before)
		if _, err := c.SetValueString(s.Key, text); err != nil {
			t.Errorf("%s: the text it renders as (%q) does not parse back: %v", s.Key, text, err)
			continue
		}
		after, err := c.Value(s.Key)
		if err != nil {
			t.Fatalf("%s: %v", s.Key, err)
		}
		if !reflect.DeepEqual(before, after) {
			t.Errorf("%s: %#v rendered as %q and came back as %#v", s.Key, before, text, after)
		}
	}
}

// Values that arrive as JSON are not the Go types the configuration holds: a
// list is []any and a number is float64. The settings API hands those straight
// through, so they have to be understood.
func TestAValueFromJSONIsUnderstood(t *testing.T) {
	c := Default()
	for _, tc := range []struct {
		key   string
		value any
		want  string
	}{
		{"oidc.scopes", []any{"openid", "profile"}, "openid,profile"},
		{"agent.capacity", float64(6), "6"},
		{"agent.labels", map[string]any{"tier": "build"}, "tier=build"},
		{"scheduler.interval", "45s", "45s"},
		{"security.cookie_secure", true, "true"},
		{"server.tls.mode", "Self-Signed", "self-signed"},
	} {
		s, ok := LookupSetting(tc.key)
		if !ok {
			t.Fatalf("no setting %s", tc.key)
		}
		if _, err := c.SetValue(tc.key, tc.value); err != nil {
			t.Errorf("%s = %#v: %v", tc.key, tc.value, err)
			continue
		}
		got, _ := c.Value(tc.key)
		if text := Text(s, got); text != tc.want {
			t.Errorf("%s = %#v stored as %q, want %q", tc.key, tc.value, text, tc.want)
		}
	}
}

// A duration is shown the way somebody writes it. Go's own rendering is exact
// and unreadable past an hour, and an operator who typed 720h and was shown
// 720h0m0s has to work out whether the product changed their mind.
func TestADurationIsRenderedTheWayItIsWritten(t *testing.T) {
	for _, tc := range []struct {
		in   time.Duration
		want string
	}{
		{0, "0s"},
		{30 * time.Second, "30s"},
		{2 * time.Minute, "2m"},
		{720 * time.Hour, "720h"},
		{90 * time.Minute, "1h30m"},
		{time.Hour + 30*time.Second, "1h0m30s"},
	} {
		if got := TidyDuration(tc.in); got != tc.want {
			t.Errorf("TidyDuration(%s) = %q, want %q", tc.in, got, tc.want)
		}
		if _, err := time.ParseDuration(TidyDuration(tc.in)); err != nil {
			t.Errorf("TidyDuration(%s) does not parse back: %v", tc.in, err)
		}
	}
}

// The three keys that get the database open cannot live in it, and nothing
// else may quietly join them: a setting marked bootstrap is one an
// administrator cannot change from the settings page, so the list is a
// deliberate one rather than something that grows by accident.
func TestOnlyTheKeysThatOpenTheDatabaseAreBootstrap(t *testing.T) {
	var got []string
	for _, s := range Settings() {
		if s.Scope == ScopeBootstrap {
			got = append(got, s.Key)
		}
	}
	slices.Sort(got)
	want := []string{"database.path", "security.encryption_key", "security.encryption_key_file"}
	if !slices.Equal(got, want) {
		t.Errorf("bootstrap settings = %v, want %v", got, want)
	}
}

// A setting that says it applies at once has to be one the running controller
// actually re-reads. Saying "saved" about a value nothing is using is worse
// than refusing the edit, because there is nothing left to fix.
func TestALiveSettingGivesNoReasonItNeedsARestart(t *testing.T) {
	for _, s := range Settings() {
		if s.Live && s.RestartReason != "" {
			t.Errorf("%s is live and also explains why it needs a restart", s.Key)
		}
		if !s.Live && s.Stored() && s.RestartReason == "" {
			t.Errorf("%s waits for a restart and does not say why; the settings page has nothing to tell an operator", s.Key)
		}
	}
}

// Every setting has something to call it and something to say about it, so the
// settings page never has to fall back to the dotted key and an empty line.
func TestEverySettingHasALabelAndASummary(t *testing.T) {
	for _, s := range Settings() {
		if strings.TrimSpace(s.Label) == "" {
			t.Errorf("%s has no label", s.Key)
		}
		if strings.TrimSpace(s.Summary) == "" {
			t.Errorf("%s has no summary", s.Key)
		}
		if s.Kind == KindEnum && len(s.Choices) == 0 {
			t.Errorf("%s is an enum with no choices, so the page cannot offer a menu", s.Key)
		}
	}
}

// Settings are listed in the order the documentation lists them, not
// alphabetically: server before database before security, because that is the
// order somebody reads a configuration in.
func TestSettingsAreOrderedTheWayTheDocumentationOrdersThem(t *testing.T) {
	if CompareKeys("server.bind", "database.path") >= 0 {
		t.Error("server should sort before database")
	}
	if CompareKeys("retention.jobs", "retention.runners") >= 0 {
		t.Error("within a section, keys sort alphabetically")
	}
	for _, s := range Settings() {
		if !slices.Contains(SectionOrder, s.Section()) {
			t.Errorf("%s is in section %q, which has no place in SectionOrder", s.Key, s.Section())
		}
	}
}

// A refusal names the setting, says what it is for, and says what was wrong --
// because "5 munutes is not a duration" is a sentence somebody has to open the
// documentation to act on.
func TestARefusalSaysWhatTheSettingIsFor(t *testing.T) {
	c := Default()
	_, err := c.SetValueString("scheduler.provision_timeout", "5 munutes")
	if err == nil {
		t.Fatal("a nonsense duration was accepted")
	}
	for _, want := range []string{"scheduler.provision_timeout", "never finishes registering", "30s, 5m, 2h"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("the refusal does not mention %q: %v", want, err)
		}
	}
}

package config

import (
	"fmt"
	"reflect"
	"sort"
	"strconv"
	"strings"
	"time"
)

// Reading and writing one setting on a Config, by its dotted key.
//
// The walk is by reflection over the yaml tags rather than a closure per key,
// for the reason the registry itself exists: two hand-written halves drift, and
// a getter that was forgotten is a setting that reports the wrong value rather
// than one that fails to compile. The yaml tag is already the name of the key
// in the file, so the field a key names is not a mapping anybody has to keep --
// it is the same fact the file format is built on.

// Value returns the value of one setting in the shape the API and the database
// carry: a string for a duration, a bool or nil for an optional bool, a list
// for a list, and the plain value for everything else.
//
// A secret's value is returned as it is. Callers that render for a person go
// through SettingsView, which never carries one.
func (c *Config) Value(key string) (any, error) {
	s, ok := LookupSetting(key)
	if !ok {
		return nil, &SettingError{key, "is not a setting this build knows about"}
	}
	f, ok := fieldFor(c, key)
	if !ok {
		return nil, &SettingError{key, "is registered but names no field; this is a bug in Zoomies"}
	}
	return encode(s, f), nil
}

// SetValue parses value and assigns it, returning what the setting was before.
//
// It never mutates a slice or map the caller already handed out: a list is
// rebuilt, which is what makes it safe to call inside config.Live's shallow
// copy, where the old snapshot may still be being read.
func (c *Config) SetValue(key string, value any) (before any, err error) {
	s, ok := LookupSetting(key)
	if !ok {
		return nil, &SettingError{key, "is not a setting this build knows about"}
	}
	f, ok := fieldFor(c, key)
	if !ok {
		return nil, &SettingError{key, "is registered but names no field; this is a bug in Zoomies"}
	}
	before = encode(s, f)
	if err := decode(s, f, value); err != nil {
		return nil, err
	}
	return before, nil
}

// SetValueString parses a value written as text -- from an environment
// variable, a command line or a database row -- and assigns it.
func (c *Config) SetValueString(key, raw string) (before any, err error) {
	s, ok := LookupSetting(key)
	if !ok {
		return nil, &SettingError{key, "is not a setting this build knows about"}
	}
	v, err := parseString(s, raw)
	if err != nil {
		return nil, err
	}
	return c.SetValue(key, v)
}

// SettingKeys returns every dotted key the Config struct actually has, found by
// walking it. It is what the registry is checked against, so a field added
// without a row fails a test rather than quietly having no environment
// variable and no place in the UI.
func SettingKeys() []string {
	var out []string
	walk(reflect.ValueOf(&Config{}).Elem(), "", func(path string, _ reflect.Value) {
		out = append(out, path)
	})
	return out
}

// fieldFor resolves a dotted key to the settable field behind it.
func fieldFor(c *Config, key string) (reflect.Value, bool) {
	v := reflect.ValueOf(c).Elem()
	for _, part := range strings.Split(key, ".") {
		if v.Kind() != reflect.Struct {
			return reflect.Value{}, false
		}
		next, ok := childNamed(v, part)
		if !ok {
			return reflect.Value{}, false
		}
		v = next
	}
	return v, true
}

func childNamed(v reflect.Value, name string) (reflect.Value, bool) {
	t := v.Type()
	for i := range t.NumField() {
		f := t.Field(i)
		if !f.IsExported() {
			continue
		}
		if yamlName(f) == name {
			return v.Field(i), true
		}
	}
	return reflect.Value{}, false
}

// walk visits every leaf field, which is every field that is not a plain
// struct: a duration is a struct-free int64, a map and a slice are leaves, and
// only the grouping structs (Server, TLS, Agent…) are descended into.
func walk(v reflect.Value, prefix string, fn func(path string, field reflect.Value)) {
	t := v.Type()
	for i := range t.NumField() {
		f := t.Field(i)
		if !f.IsExported() {
			continue
		}
		name := yamlName(f)
		if name == "" || name == "-" {
			continue
		}
		path := name
		if prefix != "" {
			path = prefix + "." + name
		}
		field := v.Field(i)
		if field.Kind() == reflect.Struct && field.Type() != reflect.TypeOf(time.Duration(0)) {
			walk(field, path, fn)
			continue
		}
		fn(path, field)
	}
}

func yamlName(f reflect.StructField) string {
	name, _, _ := strings.Cut(f.Tag.Get("yaml"), ",")
	return name
}

// encode turns a field into the shape the wire and the database carry.
func encode(s Setting, f reflect.Value) any {
	switch s.Kind {
	case KindDuration:
		return TidyDuration(time.Duration(f.Int()))
	case KindOptionalBool:
		if f.IsNil() {
			return nil
		}
		return f.Elem().Bool()
	case KindBool:
		return f.Bool()
	case KindInt:
		return int(f.Int())
	case KindFloat:
		return f.Float()
	case KindStrings:
		out := make([]string, f.Len())
		for i := range out {
			out[i] = f.Index(i).String()
		}
		return out
	case KindLabels:
		out := make(map[string]string, f.Len())
		for _, k := range f.MapKeys() {
			out[k.String()] = f.MapIndex(k).String()
		}
		return out
	default: // KindString, KindEnum, and TLSMode, which is a named string.
		return f.String()
	}
}

// decode parses one value and assigns it. The messages are the ones an operator
// reads, so they say what shape was wanted and give an example of it.
func decode(s Setting, f reflect.Value, value any) error {
	fail := func(format string, args ...any) error {
		return &SettingError{s.Key, fmt.Sprintf(format, args...)}
	}

	switch s.Kind {
	case KindDuration:
		text, ok := value.(string)
		if !ok {
			return fail("%v is not a duration; write it as text, like 30s, 5m or 2h", value)
		}
		text = strings.TrimSpace(text)
		d, err := time.ParseDuration(text)
		if err != nil && s.Key == "runners.docker_wait" {
			// ZOOMIES_DOCKER_WAIT named the runner image's own whole-seconds
			// wait for a Docker daemon long before this became a fleet
			// setting, and a pool's own env still writes it that way. An
			// operator -- or a runner's own environment, inherited by an
			// embedded controller -- who already has "120" set there is
			// carrying that contract forward, not making a mistake, so it is
			// read as seconds rather than refused.
			if n, serr := strconv.ParseInt(text, 10, 64); serr == nil {
				d, err = time.Duration(n)*time.Second, nil
			}
		}
		if err != nil {
			return fail("%q is not a duration (try 30s, 5m, 2h)", text)
		}
		if d < 0 {
			return fail("%q cannot be negative; use 0 to switch it off", text)
		}
		// Zero is always allowed: switching a timer off is a real answer. The
		// floor refuses what is technically a duration and practically an
		// outage.
		if s.Floor > 0 && d > 0 && d < s.Floor {
			return fail("%s is too short; the smallest useful value is %s", d, s.Floor)
		}
		f.SetInt(int64(d))

	case KindOptionalBool:
		if value == nil {
			f.Set(reflect.Zero(f.Type()))
			return nil
		}
		b, err := asBool(value)
		if err != nil {
			return fail("%v is not true, false or unset", value)
		}
		f.Set(reflect.ValueOf(&b))

	case KindBool:
		b, err := asBool(value)
		if err != nil {
			return fail("%v is not a boolean (use true or false)", value)
		}
		f.SetBool(b)

	case KindInt:
		n, err := asInt(value)
		if err != nil {
			return fail("%v is not a whole number", value)
		}
		// Every whole number in this configuration counts something -- runners,
		// attempts, megabytes -- so none of them can be negative.
		if n < 0 {
			return fail("%d cannot be negative", n)
		}
		f.SetInt(int64(n))

	case KindFloat:
		n, err := asFloat(value)
		if err != nil {
			return fail("%v is not a number", value)
		}
		// The one fractional setting measures a share of a machine, so a
		// negative one is not a smaller share but a different question.
		if n < 0 {
			return fail("%v cannot be negative", n)
		}
		f.SetFloat(n)

	case KindEnum:
		if b, isBool := value.(bool); isBool && len(s.Aliases) > 0 {
			value = strconv.FormatBool(b)
		}
		text, ok := value.(string)
		if !ok {
			return fail("expected a string, got %T", value)
		}
		text = strings.ToLower(strings.TrimSpace(text))
		if canonical, ok := s.Aliases[text]; ok {
			text = canonical
		}
		found := false
		for _, c := range s.Choices {
			if c == text {
				found = true
				break
			}
		}
		if !found {
			// Named, not enumerated: "is not a log level" is what somebody
			// searches for and what they will recognise, and the list of what
			// it could have been comes after it.
			return fail("%q is not a %s; use %s", text, strings.ToLower(s.Label), orList(s.Choices))
		}
		f.SetString(text)

	case KindStrings:
		list, err := asStrings(value)
		if err != nil {
			return fail("%v is not a list of values", value)
		}
		// A fresh slice: the snapshot this field belongs to may be a shallow
		// copy of one somebody is still reading.
		out := reflect.MakeSlice(f.Type(), len(list), len(list))
		for i, item := range list {
			out.Index(i).SetString(item)
		}
		if len(list) == 0 {
			out = reflect.Zero(f.Type())
		}
		f.Set(out)

	case KindLabels:
		pairs, err := asLabels(value)
		if err != nil {
			return fail("%s", err)
		}
		out := reflect.MakeMapWithSize(f.Type(), len(pairs))
		for k, v := range pairs {
			out.SetMapIndex(reflect.ValueOf(k), reflect.ValueOf(v))
		}
		if len(pairs) == 0 {
			out = reflect.Zero(f.Type())
		}
		f.Set(out)

	default: // KindString
		text, ok := value.(string)
		if !ok {
			return fail("%v is not text", value)
		}
		f.SetString(strings.TrimSpace(text))
	}
	return nil
}

// blankSaysNothing reports whether raw, the text of an environment variable,
// is an empty value of a setting that has no empty spelling, which a number does
// not. The compose file hands the container every line of .env, and Compose
// passes an empty value (or a bare ${NAME} that .env never sets) as the empty
// string rather than leaving the variable out. .env.example relies on that for
// ZOOMIES_AGENT_CAPACITY, where empty means the agent works the figure out from
// the machine, and refusing it stopped the documented first run. Such a value
// says nothing, so the layers beneath it stand; a string or a list keeps its
// empty form, because empty is a value there.
//
// Reading the environment and importing it into the database both ask, because
// the import promises to parse a variable as the controller does.
func (s Setting) blankSaysNothing(raw string) bool {
	return (s.Kind == KindInt || s.Kind == KindFloat) && strings.TrimSpace(raw) == ""
}

// parseString reads a value written as text. It is what an environment
// variable, a `zoomies config set` argument and a database row all go through,
// so one spelling means one thing in all three.
func parseString(s Setting, raw string) (any, error) {
	fail := func(format string, args ...any) (any, error) {
		return nil, &SettingError{s.Key, fmt.Sprintf(format, args...)}
	}
	switch s.Kind {
	case KindOptionalBool:
		// Empty text is how "nothing has been said about this" is written, and
		// for a tri-state that is an answer rather than a mistake: it puts the
		// setting back to being derived from the ones it follows.
		if strings.TrimSpace(raw) == "" {
			return nil, nil
		}
		b, err := strconv.ParseBool(strings.TrimSpace(raw))
		if err != nil {
			return fail("%q is not true, false or empty", raw)
		}
		return b, nil
	case KindBool:
		b, err := strconv.ParseBool(strings.TrimSpace(raw))
		if err != nil {
			return fail("%q is not a boolean (use true or false)", raw)
		}
		return b, nil
	case KindInt:
		n, err := strconv.Atoi(strings.TrimSpace(raw))
		if err != nil {
			return fail("%q is not an integer", raw)
		}
		return n, nil
	case KindFloat:
		n, err := strconv.ParseFloat(strings.TrimSpace(raw), 64)
		if err != nil {
			return fail("%q is not a number", raw)
		}
		return n, nil
	case KindStrings:
		return splitList(raw), nil
	case KindLabels:
		m, err := parseKV(raw)
		if err != nil {
			return fail("%s", err)
		}
		return m, nil
	default: // strings, enums and durations are carried as text already.
		return raw, nil
	}
}

// Text renders a value the way parseString reads it back, so what the database
// stores round-trips through what an operator would have typed.
//
// It dispatches on the setting's kind rather than on the value's Go type. A
// value that arrived as JSON is []any and map[string]any rather than []string
// and map[string]string, and a type switch that fell through to fmt.Sprint for
// those wrote "[openid profile email groups]" into the database -- a list that
// read back as one item whose name was the whole list.
func Text(s Setting, value any) string {
	if value == nil {
		return ""
	}
	switch s.Kind {
	case KindStrings:
		list, err := asStrings(value)
		if err != nil {
			return ""
		}
		escaped := make([]string, len(list))
		for i, item := range list {
			escaped[i] = escapeList(item)
		}
		return strings.Join(escaped, ",")
	case KindLabels:
		pairs, err := asLabels(value)
		if err != nil {
			return ""
		}
		keys := make([]string, 0, len(pairs))
		for k := range pairs {
			keys = append(keys, k)
		}
		// Sorted, so the same map always renders the same text: a row that
		// re-encodes differently every restart would look like a change.
		sort.Strings(keys)
		parts := make([]string, 0, len(keys))
		for _, k := range keys {
			parts = append(parts, escapeList(k)+"="+escapeList(pairs[k]))
		}
		return strings.Join(parts, ",")
	case KindDuration:
		switch v := value.(type) {
		case string:
			return v
		case time.Duration:
			return TidyDuration(v)
		}
	case KindBool, KindOptionalBool:
		if b, err := asBool(value); err == nil {
			return strconv.FormatBool(b)
		}
		return ""
	case KindInt:
		if n, err := asInt(value); err == nil {
			return strconv.Itoa(n)
		}
		return ""
	case KindFloat:
		if n, err := asFloat(value); err == nil {
			// The shortest text that reads back as the same number, so 2
			// stores as "2" rather than as "2.0" and a half core keeps its
			// half.
			return strconv.FormatFloat(n, 'f', -1, 64)
		}
		return ""
	}
	if text, ok := value.(string); ok {
		return text
	}
	return fmt.Sprint(value)
}

// TidyDuration is a duration as an operator writes it: 168h, not 168h0m0s.
//
// Go's own rendering is exact and unreadable past an hour, and it is what both
// the settings page and the stored row would otherwise carry -- so a retention
// window somebody typed as "720h" came back as "720h0m0s" and looked like
// something the product had decided rather than something they had said. The
// result still parses, which is the only constraint: it is what goes into the
// database and what comes back out of it.
func TidyDuration(d time.Duration) string {
	s := d.String()
	// Only a whole trailing unit is dropped, never digits: "30s" must not
	// become "3". Go writes the units largest first, so a zero seconds can only
	// follow a minutes unit, and a zero minutes can only follow an hours one.
	if strings.HasSuffix(s, "m0s") {
		s = strings.TrimSuffix(s, "0s")
	}
	if strings.HasSuffix(s, "h0m") {
		s = strings.TrimSuffix(s, "0m")
	}
	return s
}

// orList reads the way somebody would say it: "debug, info, warn or error".
func orList(items []string) string {
	switch len(items) {
	case 0:
		return ""
	case 1:
		return items[0]
	}
	return strings.Join(items[:len(items)-1], ", ") + " or " + items[len(items)-1]
}

func asBool(value any) (bool, error) {
	switch v := value.(type) {
	case bool:
		return v, nil
	case string:
		return strconv.ParseBool(strings.TrimSpace(v))
	}
	return false, fmt.Errorf("not a boolean")
}

func asInt(value any) (int, error) {
	switch v := value.(type) {
	case int:
		return v, nil
	case int64:
		return int(v), nil
	case float64:
		// JSON has one number type, so an integer arrives as a float. A
		// fractional one is a mistake rather than a rounding opportunity.
		if v != float64(int(v)) {
			return 0, fmt.Errorf("not a whole number")
		}
		return int(v), nil
	case string:
		return strconv.Atoi(strings.TrimSpace(v))
	}
	return 0, fmt.Errorf("not a number")
}

func asFloat(value any) (float64, error) {
	switch v := value.(type) {
	case float64:
		return v, nil
	case float32:
		return float64(v), nil
	case int:
		return float64(v), nil
	case int64:
		return float64(v), nil
	case string:
		return strconv.ParseFloat(strings.TrimSpace(v), 64)
	}
	return 0, fmt.Errorf("not a number")
}

func asStrings(value any) ([]string, error) {
	switch v := value.(type) {
	case nil:
		return nil, nil
	case []string:
		return v, nil
	case string:
		return splitList(v), nil
	case []any:
		out := make([]string, 0, len(v))
		for _, item := range v {
			s, ok := item.(string)
			if !ok {
				return nil, fmt.Errorf("not a list of text")
			}
			if s = strings.TrimSpace(s); s != "" {
				out = append(out, s)
			}
		}
		return out, nil
	}
	return nil, fmt.Errorf("not a list")
}

func asLabels(value any) (map[string]string, error) {
	switch v := value.(type) {
	case nil:
		return nil, nil
	case map[string]string:
		return v, nil
	case string:
		return parseKV(v)
	case map[string]any:
		out := make(map[string]string, len(v))
		for k, item := range v {
			s, ok := item.(string)
			if !ok {
				return nil, fmt.Errorf("the value of %q is not text", k)
			}
			out[k] = s
		}
		return out, nil
	}
	return nil, fmt.Errorf("not a set of key=value labels")
}

// Redacted renders the configuration as a nested object shaped like the file,
// with every secret absent.
//
// It is generated from the registry, and a secret cannot appear in it: the
// registry says which keys are credentials, and this writes `<key>_configured`
// -- a boolean -- for each of them instead of the value. A hand-written
// version got the same safety from being hand-written, which held right up
// until somebody added a key and forgot. It is what the settings page, the
// support bundle and a backup's manifest all carry, so the three cannot
// disagree about what is safe to show.
func Redacted(c *Config) map[string]any {
	out := map[string]any{}
	for _, st := range Settings() {
		v, err := c.Value(st.Key)
		if err != nil {
			continue
		}
		if st.Secret {
			SetNested(out, st.Key+"_configured", Text(st, v) != "")
			continue
		}
		SetNested(out, st.Key, v)
	}
	return out
}

// SetNested writes a dotted key into a tree of maps.
func SetNested(into map[string]any, key string, value any) {
	parts := strings.Split(key, ".")
	for _, part := range parts[:len(parts)-1] {
		child, ok := into[part].(map[string]any)
		if !ok {
			child = map[string]any{}
			into[part] = child
		}
		into = child
	}
	into[parts[len(parts)-1]] = value
}

package config

import (
	"testing"
	"time"
)

// A fleet that has not asked for size routing sees nothing about it: every mode
// is off, and every figure the defaults carry is one the validator accepts, so
// there is no finding on a fresh install.
func TestSizeRoutingIsOffAndItsDefaultsAreAcceptedByDefault(t *testing.T) {
	c := Default()
	if c.Scheduler.SizeRouting != "off" || c.Scheduler.AutoPools != "off" {
		t.Fatalf("size routing is %q and automatic pools %q by default; both must be off", c.Scheduler.SizeRouting, c.Scheduler.AutoPools)
	}
	for _, code := range []string{
		"scheduler.size_routing", "scheduler.auto_pools", "scheduler.auto_pools_docker_mode", "scheduler.size_default_class",
		"scheduler.size_class_limits", "runners.class_sizes", "scheduler.auto_pools_host_grace",
		"scheduler.size_wait_negative", "scheduler.size_routing_without_pools",
	} {
		if hasCode(c.Validate(), code) {
			t.Errorf("the defaults raise %s", code)
		}
	}
}

func TestEverySizeRoutingSettingIsRefusedWithTheCodeThatNamesIt(t *testing.T) {
	cases := []struct {
		name     string
		change   func(*Config)
		code     string
		severity Severity
	}{
		{"an unknown size routing mode", func(c *Config) { c.Scheduler.SizeRouting = "auto" }, "scheduler.size_routing", SeverityError},
		{"an unknown automatic pools mode", func(c *Config) { c.Scheduler.AutoPools = "true" }, "scheduler.auto_pools", SeverityError},
		{"the host socket for automatic pools", func(c *Config) { c.Scheduler.AutoPoolsDockerMode = "host-socket" }, "scheduler.auto_pools_docker_mode", SeverityError},
		{"an unknown default class", func(c *Config) { c.Scheduler.SizeDefaultClass = "huge" }, "scheduler.size_default_class", SeverityError},
		{"a medium host limit below the small one, in CPUs", func(c *Config) { c.Scheduler.SizeMediumMaxCPUs = 2 }, "scheduler.size_class_limits", SeverityError},
		{"a medium host limit below the small one, in memory", func(c *Config) { c.Scheduler.SizeMediumMaxMemoryMB = 1024 }, "scheduler.size_class_limits", SeverityError},
		{"a limit of nothing", func(c *Config) { c.Scheduler.SizeSmallMaxCPUs = 0 }, "scheduler.size_class_limits", SeverityError},
		{"a large runner smaller than a medium one", func(c *Config) { c.Runners.LargeCPUs = 1 }, "runners.class_sizes", SeverityError},
		{"a medium runner with less memory than a small one", func(c *Config) { c.Runners.MediumMemoryMB = 512 }, "runners.class_sizes", SeverityError},
		{"a runner of nothing", func(c *Config) { c.Runners.SmallMemoryMB = 0 }, "runners.class_sizes", SeverityError},
		{"a grace inside the fleet's own", func(c *Config) { c.Scheduler.AutoPoolsHostGrace = 5 * time.Minute }, "scheduler.auto_pools_host_grace", SeverityError},
		{"a grace of nothing", func(c *Config) { c.Scheduler.AutoPoolsHostGrace = 0 }, "scheduler.auto_pools_host_grace", SeverityError},
		{"a negative hold", func(c *Config) { c.Scheduler.SizeClassHold = -time.Minute }, "scheduler.size_wait_negative", SeverityError},
		{"a negative wait", func(c *Config) { c.Scheduler.SizeFallbackWait = -time.Second }, "scheduler.size_wait_negative", SeverityError},
		{"routing with no pools to route to", func(c *Config) { c.Scheduler.SizeRouting = "on" }, "scheduler.size_routing_without_pools", SeverityInfo},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			c := Default()
			tc.change(c)
			f := find(c.Validate(), tc.code)
			if f.Code != tc.code || f.Severity != tc.severity || f.Fix == "" {
				t.Fatalf("finding = %+v, want %s at %s with a fix", f, tc.code, tc.severity)
			}
		})
	}

	// A hold and a wait of nothing are answers: a host moves at once, and no
	// job waits for room.
	c := Default()
	c.Scheduler.SizeClassHold, c.Scheduler.SizeFallbackWait = 0, 0
	if hasCode(c.Validate(), "scheduler.size_wait_negative") {
		t.Error("zero is refused as a negative wait")
	}
	// Routing with pools to route to has nothing to say.
	c = Default()
	c.Scheduler.SizeRouting, c.Scheduler.AutoPools = "on", "on"
	if hasCode(c.Validate(), "scheduler.size_routing_without_pools") {
		t.Error("routing with automatic pools on still raises the note")
	}
}

// The settings are in the registry, live, and carry their environment
// variable, so the Settings page offers them and a change is in force on the
// next pass.
func TestTheSizeRoutingSettingsAreLiveAndOnTheSettingsPage(t *testing.T) {
	want := map[string]string{
		"scheduler.size_routing": "ZOOMIES_SIZE_ROUTING", "scheduler.auto_pools": "ZOOMIES_AUTO_POOLS",
		"scheduler.auto_pools_installation": "ZOOMIES_AUTO_POOLS_INSTALLATION", "scheduler.size_class_hold": "ZOOMIES_SIZE_CLASS_HOLD",
		"scheduler.size_fallback_wait": "ZOOMIES_SIZE_FALLBACK_WAIT", "runners.large_memory_mb": "ZOOMIES_RUNNER_LARGE_MEMORY_MB",
	}
	found := 0
	for _, s := range Settings() {
		if env, ok := want[s.Key]; ok {
			found++
			if s.Env != env || !s.Live || s.Summary == "" {
				t.Errorf("%s = %+v", s.Key, s)
			}
		}
	}
	if found != len(want) {
		t.Fatalf("found %d of the %d settings asked about", found, len(want))
	}
}

package config

import (
	"sort"

	"gopkg.in/yaml.v3"
)

// Where a setting's value came from.
//
// Four layers stack, in this order: the built-in defaults, then zoomies.yaml,
// then the fleet's database, then the ZOOMIES_* environment. Each one wins over
// the one before it.
//
// Recording which layer won is not bookkeeping for its own sake. It is the
// answer to the question that makes a configuration problem hard -- "I changed
// it and nothing happened" -- and it is what lets the settings page say *why*
// a field it would otherwise let an administrator edit is not editable: a value
// pinned by an environment variable would be silently overwritten at the next
// restart, so the page names the variable instead of accepting a change it
// knows will not survive.
type Source string

const (
	// SourceDefault is the value Zoomies ships with. Nothing has been said
	// about this setting anywhere.
	SourceDefault Source = "default"
	// SourceFile is zoomies.yaml.
	SourceFile Source = "file"
	// SourceDatabase is this fleet's own database, which is where a change made
	// in the UI goes and where everything belongs that can live there.
	SourceDatabase Source = "database"
	// SourceEnvironment is a ZOOMIES_* variable. It is deliberately the last
	// word: it is the way back in when a stored setting has locked an operator
	// out of the interface that would let them fix it.
	SourceEnvironment Source = "environment"
)

// note records which layer set a key. A nil map is the zero Config's, so this
// allocates on first use rather than asking every constructor to remember.
func (c *Config) note(key string, from Source) {
	if c.sources == nil {
		c.sources = map[string]Source{}
	}
	c.sources[key] = from
}

// Source returns the layer a setting's value came from.
func (c *Config) Source(key string) Source {
	if from, ok := c.sources[key]; ok {
		return from
	}
	return SourceDefault
}

// Sources returns every key that came from somewhere other than the defaults.
func (c *Config) Sources() map[string]Source {
	out := make(map[string]Source, len(c.sources))
	for k, v := range c.sources {
		out[k] = v
	}
	return out
}

// PinnedByEnvironment returns the stored settings an environment variable is
// currently overriding, ordered as the documentation orders them.
//
// These are the ones an administrator cannot change in the UI, because the
// change would be accepted, written, and then lost behind the variable at the
// next restart.
func (c *Config) PinnedByEnvironment() []Setting {
	var out []Setting
	for _, s := range StoredSettings() {
		if c.Source(s.Key) == SourceEnvironment {
			out = append(out, s)
		}
	}
	sort.Slice(out, func(i, j int) bool { return CompareKeys(out[i].Key, out[j].Key) < 0 })
	return out
}

// copySources gives a snapshot its own map, so that a Live update which records
// a new source cannot be seen half-written by a reader holding the old one.
func (c *Config) copySources() map[string]Source {
	out := make(map[string]Source, len(c.sources))
	for k, v := range c.sources {
		out[k] = v
	}
	return out
}

// keysIn returns the dotted keys a YAML document actually mentions.
//
// The struct decode cannot answer this: a key absent from the file and a key
// written with its default value produce the same struct, and the settings page
// has to tell them apart to say whether the file or the database is in charge
// of a setting. So the same bytes are read twice -- once strictly into the
// struct, which is what catches a typo, and once loosely into a tree, which is
// what says which keys were spelled.
func keysIn(doc []byte) []string {
	var tree map[string]any
	if err := yaml.Unmarshal(doc, &tree); err != nil {
		return nil
	}
	var out []string
	var walkTree func(prefix string, node map[string]any)
	walkTree = func(prefix string, node map[string]any) {
		for k, v := range node {
			path := k
			if prefix != "" {
				path = prefix + "." + k
			}
			// A nested map is a section unless it is a setting whose value is
			// a map -- agent.labels is the only one, and the registry is what
			// knows the difference.
			if child, ok := v.(map[string]any); ok {
				if s, known := LookupSetting(path); !known || s.Kind != KindLabels {
					walkTree(path, child)
					continue
				}
			}
			out = append(out, path)
		}
	}
	walkTree("", tree)
	sort.Strings(out)
	return out
}

// Note records where a value came from. It is exported for the settings API,
// which assigns a value and then has to say which layer it now belongs to --
// the database when it was stored, or the defaults when it was cleared.
func (c *Config) Note(key string, from Source) { c.note(key, from) }

// SetSources replaces the record wholesale, for a caller building a candidate
// configuration out of a running one. The map is copied, so the two snapshots
// do not share it.
func (c *Config) SetSources(from map[string]Source) {
	c.sources = make(map[string]Source, len(from))
	for k, v := range from {
		c.sources[k] = v
	}
}

package config

import (
	"strings"
	"testing"
)

// The status projection is a new way to read a fleet fact without an
// account, so the default serves none of it: an existing installation that
// upgrades gains no route anybody can reach.
func TestTheStatusProjectionIsOffByDefault(t *testing.T) {
	if got := Default().Status.Mode; got != StatusOff {
		t.Fatalf("status.mode defaults to %q, want off", got)
	}
	for _, f := range Default().Validate() {
		if strings.HasPrefix(f.Code, "status.") {
			t.Errorf("the default configuration raised %s: %s", f.Code, f.Title)
		}
	}
}

// Each mode says what it costs, and only public costs anything worth a
// warning. Public on an address strangers can reach, with nothing
// terminating TLS, is refused outright and the refusal names the settings
// that fix it -- a warning that leaves the listener open to exactly the
// people it invites would be the silent dangerous toggle the validator
// exists to prevent.
func TestTheStatusModeRaisesWhatItCosts(t *testing.T) {
	cases := []struct {
		name     string
		mode     StatusMode
		bind     string
		tls      TLSMode
		code     string
		severity Severity
		mentions []string
	}{
		{"authenticated raises nothing", StatusAuthenticated, "0.0.0.0:8080", TLSOff, "", "", nil},
		{"public on loopback is a warning", StatusPublic, "127.0.0.1:8080", TLSOff, "status.public", SeverityWarning, []string{"/api/v1/status", "No pool, host, repository"}},
		{"public with TLS on a public bind is a warning", StatusPublic, "0.0.0.0:8443", TLSSelfSigned, "status.public", SeverityWarning, nil},
		{"public on a public bind without TLS is refused", StatusPublic, "0.0.0.0:8080", TLSOff, "status.public_no_tls", SeverityError, []string{"server.tls.mode", "server.bind", "status.mode"}},
		{"a mode that is not one is refused", StatusMode("everyone"), "127.0.0.1:8080", TLSOff, "status.mode", SeverityError, []string{"off, authenticated or public"}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			c := Default()
			c.Status.Mode = tc.mode
			c.Server.Bind = tc.bind
			c.Server.TLS.Mode = tc.tls
			var got []Finding
			for _, f := range c.Validate() {
				if strings.HasPrefix(f.Code, "status.") {
					got = append(got, f)
				}
			}
			if tc.code == "" {
				if len(got) != 0 {
					t.Fatalf("raised %v, want nothing", got)
				}
				return
			}
			if len(got) != 1 || got[0].Code != tc.code || got[0].Severity != tc.severity {
				t.Fatalf("raised %v, want exactly %s at %s", got, tc.code, tc.severity)
			}
			text := got[0].Title + " " + got[0].Detail + " " + got[0].Fix
			for _, want := range tc.mentions {
				if !strings.Contains(text, want) {
					t.Errorf("the finding does not mention %q: %s", want, text)
				}
			}
		})
	}
}

// The environment is how a container deployment turns it on.
func TestTheStatusModeIsReadFromTheEnvironment(t *testing.T) {
	c := Default()
	env := map[string]string{"ZOOMIES_STATUS_MODE": "Public"}
	if err := c.applyEnvFrom(func(k string) (string, bool) { v, ok := env[k]; return v, ok }); err != nil {
		t.Fatalf("applyEnv: %v", err)
	}
	if c.Status.Mode != StatusPublic {
		t.Fatalf("ZOOMIES_STATUS_MODE=Public gave %q", c.Status.Mode)
	}
}

package config

import (
	"os"
	"path/filepath"
	"slices"
	"strings"
	"testing"
	"time"
)

// An upgrade does not start updating a fleet because the release it installed
// learned how to: the mode is off until somebody chooses otherwise, and the wait
// that protects the unattended mode is already a day by the time anyone gets
// there. A fresh install raises nothing about a feature nobody asked for, or the
// list would teach people to stop reading it.
func TestUpdatesDefaultToOffWithADaySoak(t *testing.T) {
	u := Default().Updates
	if u.Mode != "off" {
		t.Errorf("mode = %q, want off: replacing the running binary is a choice, never a default", u.Mode)
	}
	if u.Soak != 24*time.Hour {
		t.Errorf("soak = %s, want a day", u.Soak)
	}
	if u.CheckInterval != 24*time.Hour {
		t.Errorf("check interval = %s, want a day", u.CheckInterval)
	}
	for _, f := range Default().Validate() {
		if strings.HasPrefix(f.Code, "updates.") {
			t.Errorf("the defaults raise %s: %s", f.Code, f.Title)
		}
	}
}

// The environment has always lower-cased an enum, so the same word typed into
// zoomies.yaml has to mean the same thing rather than stop the controller
// starting over a capital letter.
func TestUpdatesModeFromYAMLIsLowerCasedAndTrimmed(t *testing.T) {
	path := filepath.Join(t.TempDir(), "zoomies.yaml")
	if err := os.WriteFile(path, []byte("updates:\n  mode: \" Auto \"\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	c, err := Load(path)
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if c.Updates.Mode != "auto" {
		t.Fatalf("mode = %q, want auto", c.Updates.Mode)
	}
	if hasCode(c.Validate(), "updates.mode") {
		t.Error("a mode that only needed tidying was refused")
	}

	// A blank is not a choice of anything, and the one safe thing it can mean is
	// the default: a template that renders an empty value must not turn updating
	// on, or stop the controller starting.
	if err := os.WriteFile(path, []byte("updates:\n  mode: \"\"\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	c, err = Load(path)
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if c.Updates.Mode != "off" {
		t.Errorf("an empty mode became %q, want off", c.Updates.Mode)
	}
}

// The refusal quotes the choices because the person reading it has just typed
// one that does not exist -- "automatic" is the likeliest -- and a finding that
// only says "unknown" sends them to the documentation to learn what they could
// have typed.
func TestAnUnknownUpdatesModeIsAnErrorThatNamesTheChoices(t *testing.T) {
	c := Default()
	c.Updates.Mode = "automatic"
	f := find(c.Validate(), "updates.mode")
	if f.Code == "" {
		t.Fatal("an unknown mode raised no finding")
	}
	if f.Severity != SeverityError || f.Setting != "updates.mode" {
		t.Errorf("finding = %+v, want an error about updates.mode", f)
	}
	if !strings.Contains(f.Title, `"automatic"`) {
		t.Errorf("the title does not quote what was written: %q", f.Title)
	}
	for _, choice := range []string{"off", "manual", "auto"} {
		if !strings.Contains(f.Fix, choice) {
			t.Errorf("the fix does not name %q: %q", choice, f.Fix)
		}
	}
}

// The settings layer refuses a negative duration at a write, so a negative soak
// can only arrive from the file, and the file is what has to be tried. It is an
// error whatever the mode: a value that is wrong while updating is off is still
// wrong on the day somebody switches it on.
func TestANegativeSoakFromYAMLIsAnError(t *testing.T) {
	path := filepath.Join(t.TempDir(), "zoomies.yaml")
	if err := os.WriteFile(path, []byte("updates:\n  soak: -1h\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	c, err := Load(path)
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if c.Updates.Mode != "off" {
		t.Fatalf("mode = %q; this case is about a mode that is off", c.Updates.Mode)
	}
	f := find(c.Validate(), "updates.soak_negative")
	if f.Code == "" {
		t.Fatal("a negative soak raised no finding")
	}
	if f.Severity != SeverityError || f.Setting != "updates.soak" || f.Fix == "" {
		t.Errorf("finding = %+v, want an error about updates.soak with a fix", f)
	}
}

// updates.check_interval is the air-gap switch. At zero the controller never
// learns that a release exists, so a mode that acts on one is a setting that
// quietly does nothing -- and that is worth a warning only when a mode asks for
// it. An air-gapped fleet that leaves the mode off is configured correctly.
func TestAModeWithoutAReleaseCheckIsAWarning(t *testing.T) {
	for _, mode := range []string{"manual", "auto"} {
		t.Run(mode, func(t *testing.T) {
			c := Default()
			c.Updates.Mode, c.Updates.CheckInterval = mode, 0
			f := find(c.Validate(), "updates.mode_without_check")
			if f.Code == "" {
				t.Fatalf("%s with the release check off raised no finding", mode)
			}
			if f.Severity != SeverityWarning || f.Setting != "updates.mode" || f.Fix == "" {
				t.Errorf("finding = %+v, want a warning about updates.mode with a fix", f)
			}
			if !strings.Contains(f.Fix, "updates.check_interval") {
				t.Errorf("the fix does not say how to give the mode a release to act on: %q", f.Fix)
			}
			// The release check only feeds the controller's own update. Hosts follow
			// the release the controller runs, which needs no list, so a warning that
			// said the mode did nothing would be wrong about every host with a helper.
			if !strings.Contains(f.Detail, "taken to the release the controller runs") {
				t.Errorf("the finding does not say that hosts are still taken to the controller's release: %q", f.Detail)
			}
		})
	}

	c := Default()
	c.Updates.Mode, c.Updates.CheckInterval = "off", 0
	if hasCode(c.Validate(), "updates.mode_without_check") {
		t.Error("an air-gapped fleet with updating off was warned about its release check")
	}
	c = Default()
	c.Updates.Mode = "manual"
	if hasCode(c.Validate(), "updates.mode_without_check") {
		t.Error("a mode beside a working release check was warned about it")
	}
}

// Unattended updating is never silent: the rule in this package's CLAUDE.md is
// that a default which surprises people gets an info finding, and a controller
// that replaces itself with nobody pressing anything is the largest surprise on
// offer. manual has somebody pressing a button, so it has nothing to say.
func TestAutoRaisesAnInfoFindingNamingTheSetting(t *testing.T) {
	c := Default()
	c.Updates.Mode = "auto"
	f := find(c.Validate(), "updates.auto")
	if f.Code == "" {
		t.Fatal("auto raised no finding")
	}
	if f.Severity != SeverityInfo || f.Setting != "updates.mode" {
		t.Errorf("finding = %+v, want an info finding naming updates.mode", f)
	}
	if f.Title != strings.ToLower(f.Title) || strings.HasSuffix(f.Title, ".") {
		t.Errorf("an info title is lower case with no full stop: %q", f.Title)
	}

	c.Updates.Mode = "manual"
	for _, f := range c.Validate() {
		if strings.HasPrefix(f.Code, "updates.") {
			t.Errorf("manual raises %s: %s", f.Code, f.Title)
		}
	}
}

// The soak is the only wait between a release being published and every host
// running it, so removing it from the unattended mode is said out loud. It
// applies to auto alone -- pressing the button is the soak for manual -- so a
// zero beside any other mode is a legitimate answer and raises nothing.
func TestAutoWithNoSoakIsAWarning(t *testing.T) {
	c := Default()
	c.Updates.Mode, c.Updates.Soak = "auto", 0
	f := find(c.Validate(), "updates.auto_without_soak")
	if f.Code == "" {
		t.Fatal("auto with no soak raised no finding")
	}
	if f.Severity != SeverityWarning || f.Setting != "updates.soak" || f.Fix == "" {
		t.Errorf("finding = %+v, want a warning about updates.soak with a fix", f)
	}

	for _, tc := range []struct {
		name string
		mode string
		soak time.Duration
	}{
		{"auto with a soak", "auto", 24 * time.Hour},
		{"manual with none, because pressing the button is the soak", "manual", 0},
		{"off with none", "off", 0},
	} {
		c := Default()
		c.Updates.Mode, c.Updates.Soak = tc.mode, tc.soak
		if hasCode(c.Validate(), "updates.auto_without_soak") {
			t.Errorf("%s raised updates.auto_without_soak", tc.name)
		}
	}
}

// Both are the platform's: whether this process may replace its own binary is a
// decision about the machine it runs on, not about the fleet's runners. And both
// are live, because an operator who switches updating off has to find it off on
// the next pass and not after a restart -- which an update would itself be.
func TestTheUpdateModeAndSoakArePlatformSettingsThatApplyAtOnce(t *testing.T) {
	for key, env := range map[string]string{
		"updates.mode": "ZOOMIES_UPDATE_MODE",
		"updates.soak": "ZOOMIES_UPDATE_SOAK",
	} {
		s, ok := LookupSetting(key)
		if !ok {
			t.Errorf("%s is not registered, so there is no way to change it on the Settings page", key)
			continue
		}
		if s.Scope != ScopePlatform || !s.Platform() {
			t.Errorf("%s has scope %q, want the platform's", key, s.Scope)
		}
		if !s.Live {
			t.Errorf("%s waits for a restart", key)
		}
		if s.Env != env {
			t.Errorf("%s is overridden by %s, want %s", key, s.Env, env)
		}
		if s.Section() != "updates" {
			t.Errorf("%s is in section %q, so it would not sit beside updates.check_interval", key, s.Section())
		}
	}
}

// The Settings page offers the registry's choices and the validator accepts a
// list of its own, so a choice added to one and not the other would be offered,
// saved, and then refused at the next start. Each choice has to be one the
// validator lets through, and the two lists have to be the same.
func TestEveryUpdateModeTheSettingsPageOffersIsOneTheValidatorAccepts(t *testing.T) {
	s, ok := LookupSetting("updates.mode")
	if !ok {
		t.Fatal("updates.mode is not registered")
	}
	if s.Kind != KindEnum {
		t.Fatalf("updates.mode is a %s, want an enum, so the page draws a menu", s.Kind)
	}
	if want := []string{"off", "manual", "auto"}; !slices.Equal(s.Choices, want) {
		t.Errorf("the page offers %v, want %v", s.Choices, want)
	}
	for _, choice := range s.Choices {
		if !strings.Contains(s.Summary, choice) {
			t.Errorf("the summary does not say what %q does", choice)
		}
		c := Default()
		if _, err := c.SetValueString("updates.mode", choice); err != nil {
			t.Errorf("%q is offered and refused when saved: %v", choice, err)
		}
		if hasCode(c.Validate(), "updates.mode") {
			t.Errorf("%q is offered and refused by the validator", choice)
		}
	}

	// And the refusal reads as a sentence, which is why the label is what it is:
	// "an update mode" would read "a update mode".
	c := Default()
	_, err := c.SetValueString("updates.mode", "dev")
	if err == nil {
		t.Fatal("a mode that is not one of the choices was accepted")
	}
	for _, want := range []string{`"dev" is not a release update mode`, "off, manual or auto"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("the refusal does not say %q: %v", want, err)
		}
	}
}

// Zero is a real answer for a soak -- take a release the moment it is seen,
// which is what a fleet that runs its own staging first wants -- and no floor
// stands between an operator and a short one. The warning is the guard, not the
// settings layer.
func TestTheSoakHasNoFloorAndZeroIsAnAnswer(t *testing.T) {
	c := Default()
	for _, written := range []string{"0", "1m", "72h"} {
		if _, err := c.SetValueString("updates.soak", written); err != nil {
			t.Errorf("a soak of %s was refused: %v", written, err)
		}
	}
	if c.Updates.Soak != 72*time.Hour {
		t.Errorf("soak = %s after the last write, want 72h", c.Updates.Soak)
	}
	if _, err := c.SetValueString("updates.soak", "tomorrow"); err == nil {
		t.Error("a soak that is not a duration was accepted")
	}
}

// Every place that describes the modes says, in the same words, that auto moves
// a machine only through its update helper and that a failure halts the rollout
// for a person: an operator who reads only "every host follows a release" would
// wait for an update a missing helper can never make. The sentence is one
// constant so that changing it is one search; the docs quote it and are held to
// the same text here.
func TestEveryPlaceThatDescribesAutoSaysItNeedsAHelperAndHaltsOnAFailure(t *testing.T) {
	// What the planner does, said in the sentence: it needs a helper, it does
	// nothing while fenced, a failure halts it, and a person resumes or cancels.
	for _, says := range []string{"only through its own update helper", "auto waits and updates no host",
		"nothing starts while the controller is fenced", "a failed update halts the rollout", "resumes or cancels it on the Hosts page (or with zoomies updates resume or cancel)"} {
		if !strings.Contains(updatesAutoNeedsHelper, says) {
			t.Errorf("the sentence about auto never says %q: %s", says, updatesAutoNeedsHelper)
		}
	}
	mode, ok := LookupSetting("updates.mode")
	if !ok {
		t.Fatal("updates.mode is not a setting")
	}
	c := Default()
	c.Updates.Mode = "auto"
	auto := find(c.Validate(), "updates.auto")
	c.Updates.Mode = "weekly"
	invalid := find(c.Validate(), "updates.mode")

	for _, tc := range []struct{ where, text string }{
		{"the updates.mode summary", mode.Summary},
		{"the updates.auto detail", auto.Detail},
		{"the updates.mode fix", invalid.Fix},
	} {
		if !strings.Contains(tc.text, updatesAutoNeedsHelper) {
			t.Errorf("%s = %q, want it to say %q", tc.where, tc.text, updatesAutoNeedsHelper)
		}
	}
	// The title is printed at start-up on its own, so it must not promise
	// installing, which auto does only where an update helper is installed.
	if auto.Title != "the update mode is auto" || strings.Contains(strings.ToLower(auto.Title), "install") {
		t.Errorf("the updates.auto title = %q, want it to state the mode and promise no installing", auto.Title)
	}
	if strings.Contains(auto.Title, updatesAutoNeedsHelper) {
		t.Errorf("the updates.auto title carries the clause; a title is short, so it belongs in the detail")
	}

	// Each place is pinned, not the page: a clause that survives in one row
	// would let the others drop it unnoticed.
	configuration := docLines(t, "configuration.md")
	problems := docLines(t, "problem-codes.md")
	for _, tc := range []struct {
		where string
		line  string
	}{
		{"the updates.mode row of docs/configuration.md", lineStarting(t, configuration, "| `updates.mode` |")},
		{"the paragraph under the mode table of docs/configuration.md", lineAfter(t, configuration, "### `updates.mode`", "Auto updates a machine")},
		{"the updates.mode row of docs/problem-codes.md", lineStarting(t, problems, "| `updates.mode` |")},
		{"the updates.auto row of docs/problem-codes.md", lineStarting(t, problems, "| `updates.auto` |")},
	} {
		if !strings.Contains(tc.line, updatesAutoNeedsHelper) {
			t.Errorf("%s never says %q: %s", tc.where, updatesAutoNeedsHelper, tc.line)
		}
	}
}

func docLines(t *testing.T, page string) []string {
	t.Helper()
	body, err := os.ReadFile(filepath.Join("..", "..", "docs", page))
	if err != nil {
		t.Fatal(err)
	}
	return strings.Split(string(body), "\n")
}

func lineStarting(t *testing.T, lines []string, prefix string) string {
	t.Helper()
	for _, l := range lines {
		if strings.HasPrefix(l, prefix) {
			return l
		}
	}
	t.Fatalf("no line starts %q", prefix)
	return ""
}

// lineAfter is the first line at or after the heading that starts with prefix.
// The paragraph under the mode table is found by where it sits, so a version
// of it that lost the clause is reported rather than not found.
func lineAfter(t *testing.T, lines []string, heading, prefix string) string {
	t.Helper()
	seen := false
	for _, l := range lines {
		if strings.HasPrefix(l, heading) {
			seen = true
		}
		if seen && strings.HasPrefix(l, prefix) {
			return l
		}
	}
	t.Fatalf("no line starting %q after %q", prefix, heading)
	return ""
}

// A soak of nothing is warned about because it takes a release before anyone
// can look at it. The words must not claim the release is installed, which this
// release does not do, in the finding or on the page that explains it.
func TestTheNoSoakWarningDoesNotSayAReleaseIsInstalled(t *testing.T) {
	c := Default()
	c.Updates.Mode, c.Updates.Soak = "auto", 0
	const want = "would be taken before anyone has had the chance to notice"
	if got := find(c.Validate(), "updates.auto_without_soak").Detail; !strings.Contains(got, want) || strings.Contains(got, "is installed") {
		t.Errorf("detail = %q, want %q and no claim of an install", got, want)
	}
	row := lineStarting(t, docLines(t, "problem-codes.md"), "| `updates.auto_without_soak` |")
	if !strings.Contains(row, want) || strings.Contains(row, "is installed") {
		t.Errorf("docs/problem-codes.md row = %q, want %q and no claim of an install", row, want)
	}
}

// "Once it has been public for 0s" reads as a wait, when the whole point of a
// soak of nothing is that there is none.
func TestTheAutoNoticeDoesNotCallNoSoakAWait(t *testing.T) {
	c := Default()
	c.Updates.Mode, c.Updates.Soak = "auto", 0
	got := find(c.Validate(), "updates.auto").Detail
	if strings.Contains(got, "0s") || !strings.Contains(got, "as soon as it is seen") {
		t.Errorf("detail = %q, want the release taken as soon as it is seen and no 0s", got)
	}

	c.Updates.Soak = 36 * time.Hour
	if got := find(c.Validate(), "updates.auto").Detail; !strings.Contains(got, "once it has been public for 36h") {
		t.Errorf("detail = %q, want the wait named when there is one", got)
	}
}

package config

import (
	"slices"
	"sort"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// The enum settings Validate refuses a wrong value of, each with how to put a
// value straight into the field. They go straight in, not through SetValueString,
// because that normalises a value before it is stored and a file does not.
var validatedEnums = map[string]func(c *Config, v string){
	"scheduler.history_sizing":         func(c *Config, v string) { c.Scheduler.HistorySizing = v },
	"scheduler.host_order":             func(c *Config, v string) { c.Scheduler.HostOrder = v },
	"scheduler.placement_mode":         func(c *Config, v string) { c.Scheduler.PlacementMode = v },
	"scheduler.size_routing":           func(c *Config, v string) { c.Scheduler.SizeRouting = v },
	"scheduler.auto_pools":             func(c *Config, v string) { c.Scheduler.AutoPools = v },
	"scheduler.auto_pools_docker_mode": func(c *Config, v string) { c.Scheduler.AutoPoolsDockerMode = v },
	"scheduler.size_default_class":     func(c *Config, v string) { c.Scheduler.SizeDefaultClass = v },
	"security.auto_apply_remedies":     func(c *Config, v string) { c.Security.AutoApplyRemedies = v },
}

func findingsFor(c *Config, code string) Findings {
	var out Findings
	for _, f := range c.Validate() {
		if f.Code == code {
			out = append(out, f)
		}
	}
	return out
}

// Validate used to restate each of these lists by hand beside the settings
// registry, and the two had to be kept equal by whoever remembered. The
// validator now asks the registry, and this holds that: every choice, and every
// older spelling, is accepted; anything else is refused with the choices named.
func TestTheValidatorAcceptsExactlyWhatTheRegistryListsForEachEnum(t *testing.T) {
	for key, set := range validatedEnums {
		s, ok := LookupSetting(key)
		if !ok || s.Kind != KindEnum || len(s.Choices) == 0 {
			t.Errorf("%s is not an enum setting in the registry, so Validate cannot be asking it", key)
			continue
		}
		accepted := append([]string{""}, s.Choices...)
		for alias := range s.Aliases {
			accepted = append(accepted, alias)
		}
		for _, value := range accepted {
			c := Default()
			set(c, value)
			if got := findingsFor(c, key); len(got) != 0 {
				t.Errorf("%s=%q is a choice or alias the registry lists, and Validate refused it: %s", key, value, got[0].Title)
			}
		}
		c := Default()
		set(c, "bogus")
		got := findingsFor(c, key)
		if len(got) != 1 || got[0].Severity != SeverityError {
			t.Errorf("%s=bogus should be one error finding, got %+v", key, got)
			continue
		}
		if !strings.HasPrefix(got[0].Fix, "choose ") {
			t.Errorf("%s: the fix %q does not start with \"choose \"", key, got[0].Fix)
		}
		for _, choice := range s.Choices {
			if !strings.Contains(got[0].Fix, choice) {
				t.Errorf("%s: the fix %q does not name the choice %q", key, got[0].Fix, choice)
			}
		}
	}
}

// security.auto_apply_remedies accepted yes and no from the settings page (the
// registry lists them) and from the runtime (AutoApplyMode reads them), and
// Validate refused both as an error, which stops startup: a zoomies.yaml that
// said `auto_apply_remedies: yes` could not start the controller. The three
// places have to agree about every spelling.
func TestEverySpellingOfTheAutomaticApplyModeIsReadTheSameInAllThreePlaces(t *testing.T) {
	s, _ := LookupSetting("security.auto_apply_remedies")
	if len(s.Aliases) == 0 {
		t.Fatal("security.auto_apply_remedies has no aliases any more; this test has nothing to compare")
	}
	for spelling, canonical := range s.Aliases {
		for _, written := range []string{spelling, strings.ToUpper(spelling), " " + spelling + " "} {
			c := Default()
			c.Security.AutoApplyRemedies = written
			if got := findingsFor(c, "security.auto_apply_remedies"); len(got) != 0 {
				t.Errorf("%q is an alias of %q in the registry and Validate refused it, which would stop the controller starting", written, canonical)
			}
			if got := c.Security.AutoApplyMode(); got != canonical {
				t.Errorf("%q is read as %q at runtime but the registry says it means %q", written, got, canonical)
			}
		}
	}
}

// The registry's lists are also what the scheduler's own constants say, and the
// two live in different packages. config cannot import the scheduler in its
// non-test code, which is why they were copied; a test can.
func TestTheRegistryChoicesAreTheOnesTheSchedulerAndStoreDefine(t *testing.T) {
	choices := func(key string) []string {
		s, ok := LookupSetting(key)
		if !ok {
			t.Fatalf("no setting %s", key)
		}
		return s.Choices
	}
	sameSet := func(key string, want []string) {
		t.Helper()
		got := append([]string{}, choices(key)...)
		want = append([]string{}, want...)
		sort.Strings(got)
		sort.Strings(want)
		if !slices.Equal(got, want) {
			t.Errorf("%s offers %v and the code that acts on it knows %v", key, got, want)
		}
	}
	sameSet("scheduler.host_order", scheduler.HostOrders)
	sameSet("scheduler.size_routing", scheduler.SizeModes)
	sameSet("scheduler.auto_pools", scheduler.SizeModes)
	sameSet("scheduler.size_default_class", []string{string(store.SizeSmall), string(store.SizeMedium), string(store.SizeLarge)})
}

package config

import (
	"testing"
	"time"
)

// Validate is a list of calls to one method per part of the configuration, and
// the order of the calls is the order findings are reported in: the problems
// panel and the startup log print them as they come. Splitting a 1,100-line
// function into parts must not shuffle them, and a part added in the wrong place
// should be seen. Each part below is represented by one finding it raises, all
// of them raised at once, and they have to come out in the parts' order.
func TestValidateReportsFindingsInTheOrderOfItsParts(t *testing.T) {
	c := Default()
	for key, raw := range map[string]string{
		"server.bind":                     "",
		"server.external_url":             "x",
		"database.path":                   "",
		"security.session_ttl":            "0s",
		"agent.work_dir":                  "",
		"scheduler.interval":              "0s",
		"images.refresh_interval":         "0s",
		"retention.jobs":                  "1ms",
		"capacity_demand.destination_url": "x",
		"security.allow_private_egress":   "true",
		"provider.enabled":                "true",
	} {
		if _, err := c.SetValueString(key, raw); err != nil {
			t.Fatalf("setting %s=%q: %v", key, raw, err)
		}
	}
	c.Scheduler.HostOrder = "bogus"        // validateChoicesAndBounds
	c.Updates.CheckInterval = -time.Second // validateUpdateCheck

	// One finding from each part, in the order the parts run.
	order := []struct{ part, code string }{
		{"choices and bounds", "scheduler.host_order"},
		{"listener", "bind.empty"},
		{"external URL", "external_url.malformed"},
		{"storage", "db.path_missing"},
		{"authentication", "auth.session_ttl"},
		{"agent", "agent.workdir"},
		{"scheduler", "scheduler.interval"},
		{"runner images", "images.refresh_off"},
		{"retention", "retention.jobs_short"},
		{"update check", "updates.interval_negative"},
		{"capacity provisioner", "capacity_demand.url"},
		{"outbound addresses", "egress.private_allowed"},
		{"providers", "provider.no_ceiling"},
	}
	position := map[string]int{}
	for i, f := range c.Validate() {
		if _, seen := position[f.Code]; !seen {
			position[f.Code] = i
		}
	}
	previous := -1
	for _, want := range order {
		at, ok := position[want.code]
		if !ok {
			t.Errorf("the %s part raised no %s, so the order cannot be checked through it", want.part, want.code)
			continue
		}
		if at < previous {
			t.Errorf("%s (the %s part) is reported at %d, before an earlier part's finding at %d: the parts run in a different order from the one this test records",
				want.code, want.part, at, previous)
		}
		previous = at
	}
}

package controller

import (
	"fmt"
	"sync"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/auth"
)

// agentCallsPerSecond sizes the per-host budget for heartbeats, results and
// reports: this many calls per second of agent.heartbeat_interval, and never
// fewer than minAgentCallsPerInterval in one interval.
//
// A well-behaved agent sends one heartbeat an interval, a result per task and
// a report when a runner changes, so even a host that starts and removes a
// full complement of runners in one interval spends a small fraction of it.
// What the budget is for is the agent that is not well behaved -- a bug in a
// retry loop, or a stolen token -- whose every call is a store write that
// queues behind the single writer every other host is also waiting for.
const (
	agentCallsPerSecond      = 20
	minAgentCallsPerInterval = 200
)

// Limit labels on zoomies_agent_requests_limited_total.
const (
	limitRate    = "rate"
	limitPoll    = "poll"
	limitRunners = "runners"
)

// ErrReportTooLarge is a heartbeat or runner report carrying more runners than
// agent.MaxRunnersPerReport. The API answers it with a 413.
var ErrReportTooLarge = fmt.Errorf("controller: a report carried more than %d runners", agent.MaxRunnersPerReport)

// agentLimiter is the per-host budget. It is rebuilt when the heartbeat
// interval changes, because the interval is a live setting and a budget sized
// for thirty seconds would be the wrong shape at five.
type agentLimiter struct {
	mu       sync.Mutex
	interval time.Duration
	limiter  *auth.RateLimiter
}

// agentCallBudget returns how many calls one host may make in one interval.
func agentCallBudget(interval time.Duration) int {
	return max(minAgentCallsPerInterval, int(interval/time.Second)*agentCallsPerSecond)
}

// AllowAgentCall spends one call from a host's budget for heartbeats, results
// and reports. When it is refused, the duration says how long until the next
// call would be accepted, for a Retry-After header.
func (c *Controller) AllowAgentCall(hostID string) (bool, time.Duration) {
	interval := c.heartbeatInterval()
	c.agentCalls.mu.Lock()
	if c.agentCalls.limiter == nil || c.agentCalls.interval != interval {
		c.agentCalls.interval = interval
		c.agentCalls.limiter = auth.NewRateLimiter(agentCallBudget(interval), interval, c.Now)
	}
	l := c.agentCalls.limiter
	c.agentCalls.mu.Unlock()

	if l.Allow(hostID) {
		return true, 0
	}
	c.metrics.agentLimited.WithLabelValues(limitRate).Inc()
	return false, l.RetryAfter(hostID)
}

// checkReportSize refuses a report that carries more runners than any host
// could be running.
func (c *Controller) checkReportSize(n int) error {
	if n <= agent.MaxRunnersPerReport {
		return nil
	}
	c.metrics.agentLimited.WithLabelValues(limitRunners).Inc()
	return fmt.Errorf("%w (it carried %d); a host cannot be running that many, so the agent is misbehaving -- check its log and version", ErrReportTooLarge, n)
}

package controller

import (
	"bytes"
	"errors"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/prometheus/client_golang/prometheus/testutil"
)

// The budget exists for the agent that is not behaving; the one that is must
// never meet it, or the limit turns a busy host into a broken one. One
// heartbeat, a result for every task in two full batches and a report for each
// of them is far more than a real interval holds, and it still has to fit.
func TestTheAgentCallBudgetFitsABusyWellBehavedAgentAtEveryInterval(t *testing.T) {
	busy := 1 + 2*maxTasksPerPoll + 2*maxTasksPerPoll
	for _, interval := range []time.Duration{time.Second, 5 * time.Second, 30 * time.Second, 5 * time.Minute} {
		if got := agentCallBudget(interval); got < busy {
			t.Errorf("agentCallBudget(%s) = %d, want at least %d so a busy agent never meets it", interval, got, busy)
		}
	}
	if got, want := agentCallBudget(time.Minute), 60*agentCallsPerSecond; got != want {
		t.Errorf("agentCallBudget(1m) = %d, want %d: the budget scales with the interval", got, want)
	}
}

// One host spending its budget is refused with a wait to honour, and a second
// host is not touched by it: the whole point of keying by host is that one
// misbehaving agent is its own problem.
func TestAHostOverItsCallBudgetIsRefusedAndOtherHostsAreNot(t *testing.T) {
	h := newHarness(t)
	budget := agentCallBudget(h.c.heartbeatInterval())

	for i := range budget {
		if ok, _ := h.c.AllowAgentCall("host_noisy"); !ok {
			t.Fatalf("call %d of a budget of %d was refused", i+1, budget)
		}
	}
	ok, retry := h.c.AllowAgentCall("host_noisy")
	if ok {
		t.Fatalf("call %d was allowed; the budget is %d", budget+1, budget)
	}
	if retry <= 0 || retry > h.c.heartbeatInterval() {
		t.Errorf("retry after = %s, want a wait within one heartbeat interval", retry)
	}
	if ok, _ := h.c.AllowAgentCall("host_quiet"); !ok {
		t.Error("a quiet host was refused because another host spent its budget")
	}
	if got := testutil.ToFloat64(h.c.metrics.agentLimited.WithLabelValues(limitRate)); got != 1 {
		t.Errorf("zoomies_agent_requests_limited_total{limit=rate} = %v, want 1", got)
	}

	h.advance(h.c.heartbeatInterval() + time.Second)
	if ok, _ := h.c.AllowAgentCall("host_noisy"); !ok {
		t.Error("the noisy host was still refused a full interval later")
	}
}

// A host has one agent and an agent polls one at a time, so a second held poll
// is a bug or an abuse. It is answered at once rather than held, and it does
// not take the first one's place: a task queued afterwards still reaches the
// poll that was there first.
func TestASecondPollWhileOneIsHeldIsAnsweredAtOnceAndEmpty(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()

	first := make(chan *agent.TaskBatch, 1)
	go func() {
		b, err := h.c.PollTasks(h.ctx, host.ID, 10*time.Second)
		if err != nil {
			t.Errorf("first PollTasks: %v", err)
		}
		first <- b
	}()
	deadline := time.Now().Add(2 * time.Second)
	for !h.c.queues.get(host.ID).polling.Load() {
		if time.Now().After(deadline) {
			t.Fatal("the first poll never started being held")
		}
		time.Sleep(time.Millisecond)
	}

	started := time.Now()
	second, err := h.c.PollTasks(h.ctx, host.ID, 10*time.Second)
	if err != nil {
		t.Fatalf("second PollTasks: %v", err)
	}
	if took := time.Since(started); took > time.Second {
		t.Errorf("the second poll was held for %s; it should be answered at once", took)
	}
	if len(second.Tasks) != 0 {
		t.Errorf("the second poll got %d tasks, want none", len(second.Tasks))
	}
	if got := testutil.ToFloat64(h.c.metrics.agentLimited.WithLabelValues(limitPoll)); got != 1 {
		t.Errorf("zoomies_agent_requests_limited_total{limit=poll} = %v, want 1", got)
	}

	h.c.enqueue(host.ID, agent.Task{Kind: agent.TaskCreateRunner, RunnerID: "run_example"})
	select {
	case b := <-first:
		if len(b.Tasks) != 1 {
			t.Errorf("the held poll got %d tasks, want the one queued", len(b.Tasks))
		}
	case <-time.After(5 * time.Second):
		t.Fatal("the held poll never received the task queued after the refused one")
	}
}

// Every entry in a report is a store read and maybe a write behind the single
// writer, so one host sending a huge one holds the writer for every other.
func TestAReportWithMoreRunnersThanAnyHostRunsIsRefused(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	tooMany := make([]agent.RunnerReport, agent.MaxRunnersPerReport+1)

	if err := h.c.ReportRunners(h.ctx, host.ID, tooMany); !errors.Is(err, ErrReportTooLarge) {
		t.Errorf("ReportRunners with %d runners = %v, want ErrReportTooLarge", len(tooMany), err)
	}
	beat := agent.HeartbeatRequest{ProtocolVersion: agent.ProtocolVersion, Runners: tooMany}
	if _, err := h.c.Heartbeat(h.ctx, host.ID, beat); !errors.Is(err, ErrReportTooLarge) {
		t.Errorf("Heartbeat with %d runners = %v, want ErrReportTooLarge", len(tooMany), err)
	}
	if err := h.c.checkReportSize(agent.MaxRunnersPerReport); err != nil {
		t.Errorf("a report of exactly the cap was refused: %v", err)
	}
	if got := testutil.ToFloat64(h.c.metrics.agentLimited.WithLabelValues(limitRunners)); got != 2 {
		t.Errorf("zoomies_agent_requests_limited_total{limit=runners} = %v, want 2", got)
	}
}

// spendStep is one call to logStream.spend, after a pause.
type spendStep struct {
	after time.Duration
	n     int
	want  bool
}

func TestALogStreamSpendsItsBudgetAndRefillsWithTime(t *testing.T) {
	tests := []struct {
		name  string
		steps []spendStep
	}{
		{"the burst is there from the first byte", []spendStep{
			{0, logStreamBurst, true}, {0, 1, false}}},
		{"a second refills a second's worth", []spendStep{
			{0, logStreamBurst, true}, {time.Second, logStreamBytesPerSecond, true}, {0, 1, false}}},
		{"idling never saves more than the burst", []spendStep{
			{0, 1, true}, {time.Hour, logStreamBurst, true}, {0, 2, false}}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			s := &logStream{}
			now := time.Unix(1_000_000, 0)
			for i, step := range tt.steps {
				now = now.Add(step.after)
				if got := s.spend(step.n, now); got != step.want {
					t.Fatalf("step %d: spend(%d) = %v, want %v", i, step.n, got, step.want)
				}
			}
		})
	}
}

// One goroutine is meant to read an agent's POST, but nothing makes that so:
// an agent that opens a stream again while this side is still blocked on the
// first connection, a half-open one that has not failed yet, puts a second
// reader on the same stream. Two readers have to share one budget; with no lock
// they read the same balance and each spend it, and the byte limit that exists
// to protect the controller from a noisy agent doubles.
func TestTwoReadersOfOneLogStreamShareItsBudget(t *testing.T) {
	const chunk = 8 << 10 // the burst is 1024 of these
	s := &logStream{}
	now := time.Unix(1_000_000, 0) // a clock that never moves refills nothing

	var spent atomic.Int64
	var wg sync.WaitGroup
	for range 2 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for range 2 * logStreamBurst / chunk {
				if s.spend(chunk, now) {
					spent.Add(chunk)
				}
			}
		}()
	}
	wg.Wait()

	if got := spent.Load(); got != logStreamBurst {
		t.Errorf("two readers spent %d bytes against a budget of %d", got, logStreamBurst)
	}
}

// An agent pushing output faster than the budget is read and dropped, never
// waited on: the relay returns as soon as the agent stops writing, the viewer
// gets the burst's worth, and the rest is counted.
func TestALogStreamOverItsByteBudgetIsDroppedRatherThanBlocked(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerBusy)

	ch, cancel, err := h.c.OpenLogStream(h.ctx, r.ID, backend.LogOptions{Follow: true})
	if err != nil {
		t.Fatalf("OpenLogStream: %v", err)
	}
	defer cancel()
	task := h.taskOfKind(host.ID, agent.TaskStreamLogs)

	flood := logStreamBurst + 4*logStreamBytesPerSecond
	done := make(chan error, 1)
	go func() {
		done <- h.c.AcceptLogStream(host.ID, task.StreamID, bytes.NewReader(bytes.Repeat([]byte("x"), flood)))
	}()
	select {
	case err := <-done:
		if err != nil {
			t.Fatalf("AcceptLogStream: %v", err)
		}
	case <-time.After(3 * time.Second):
		t.Fatal("the relay blocked on a stream over its budget instead of dropping")
	}

	got := 0
	// The relay now says in band how much it refused, so the viewer's bytes
	// are the accepted flood plus that notice. The notice is the corrected
	// expectation: a silently gapped log is what the marker exists to prevent.
	noticed := 0
	for chunk := range ch {
		got += len(chunk)
		if bytes.Contains(chunk, []byte("dropped")) {
			noticed += len(chunk)
		}
	}
	// A little refills while the flood is read, so the bound is the burst plus
	// a second's worth rather than the burst exactly. The notice is not part
	// of the flood, so it does not count against the bound.
	if accepted := got - noticed; accepted > logStreamBurst+logStreamBytesPerSecond {
		t.Errorf("the viewer received %d of %d bytes; the budget is a burst of %d", accepted, flood, logStreamBurst)
	}
	if dropped := testutil.ToFloat64(h.c.metrics.logRelayDropped); int(dropped) != flood-(got-noticed) {
		t.Errorf("zoomies_log_relay_dropped_bytes_total = %v, want %d", dropped, flood-(got-noticed))
	}
}

package controller

import (
	"context"
	"fmt"
	"net/url"
	"sort"
	"strings"

	"github.com/eyupio/zoomies/internal/aicontext"
	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

// AIContextDiscovery describes candidates only; discovery never grants source
// access, enables a repository or changes the GitHub App's permissions.
type AIContextDiscovery struct {
	Repositories            []github.Repository `json:"repositories"`
	CanReadContents         bool                `json:"can_read_contents"`
	MissingSetupPermissions []string            `json:"missing_setup_permissions"`
	DefaultExclusions       []string            `json:"default_exclusions"`
	DefaultKeepSnapshots    int                 `json:"default_keep_snapshots"`
	Capped                  bool                `json:"capped"`
	// ZoomiesUploadAvailable says whether this controller can take
	// Zoomies-only uploads at all: GitHub's runners need an https address.
	ZoomiesUploadAvailable bool `json:"zoomies_upload_available"`
}

func (c *Controller) DiscoverAIContext(ctx context.Context, installationID string) (*AIContextDiscovery, error) {
	client, err := c.ClientFor(ctx, installationID)
	if err != nil {
		return nil, err
	}
	// The fleet's Verify operation may create/adopt a runner group. Discovery
	// probes the client directly so opening the wizard cannot mutate a fleet.
	info, err := client.Probe(ctx)
	if err != nil {
		return nil, err
	}
	repos, err := client.ListRepositories(ctx, 0)
	if err != nil {
		return nil, err
	}
	// ListRepositories has a hard ceiling. Conservatively report that ceiling
	// even when an installation happens to have exactly this many repositories.
	defaults := aicontext.DefaultConfig("main")
	out := &AIContextDiscovery{DefaultExclusions: defaults.Exclude, DefaultKeepSnapshots: defaults.KeepSnapshots, Repositories: repos, CanReadContents: info.CanReadContents(), MissingSetupPermissions: info.MissingForMigration(), Capped: len(repos) >= github.RepositoryDiscoveryLimit, ZoomiesUploadAvailable: aicontext.UploadURLFor(c.cfg().Server.ExternalURL) != ""}
	if out.Repositories == nil {
		out.Repositories = []github.Repository{}
	}
	if out.MissingSetupPermissions == nil {
		out.MissingSetupPermissions = []string{}
	}
	sort.Slice(out.Repositories, func(i, j int) bool { return out.Repositories[i].FullName < out.Repositories[j].FullName })
	return out, nil
}

// AIContextDraftRequest selects a discovered identity, never a caller-supplied
// host or name. Those fields must come from the installation's own metadata.
type AIContextDraftRequest struct {
	InstallationID string `json:"installation_id"`
	RepositoryID   int64  `json:"repository_id"`
}

func (c *Controller) CreateAIContextDraft(ctx context.Context, req AIContextDraftRequest) (*store.AIContextRepository, error) {
	if req.InstallationID == "" || req.RepositoryID <= 0 {
		return nil, fmt.Errorf("%w: choose a known installation and repository", auth.ErrInvalidInput)
	}
	discovery, err := c.DiscoverAIContext(ctx, req.InstallationID)
	if err != nil {
		return nil, err
	}
	if !discovery.CanReadContents {
		return nil, fmt.Errorf("%w: grant the GitHub App Contents read permission before preparing this repository", auth.ErrInvalidInput)
	}
	var selected *github.Repository
	for i := range discovery.Repositories {
		if discovery.Repositories[i].ID == req.RepositoryID {
			selected = &discovery.Repositories[i]
			break
		}
	}
	if selected == nil {
		return nil, fmt.Errorf("%w: this repository is not in the installation's discovered selection", auth.ErrInvalidInput)
	}
	if selected.Archived {
		return nil, fmt.Errorf("%w: choose an active repository; archived repositories cannot receive setup pull requests", auth.ErrInvalidInput)
	}
	cfg := aicontext.DefaultConfig(selected.DefaultBranch)
	if err := cfg.Validate(); err != nil {
		return nil, fmt.Errorf("%w: %s", auth.ErrInvalidInput, err)
	}
	inst, err := c.st.GetInstallation(ctx, req.InstallationID)
	if err != nil {
		return nil, err
	}
	host, err := aiContextGitHubHost(inst.APIBaseURL)
	if err != nil {
		return nil, err
	}
	draft := &store.AIContextRepository{Key: aicontext.RepositoryKey{GitHubHost: host, InstallationID: inst.ID, RepositoryID: selected.ID}, FullName: selected.FullName, Config: cfg}
	if err := c.st.CreateAIContextRepository(ctx, draft); err != nil {
		return nil, err
	}
	return draft, nil
}

func aiContextGitHubHost(baseURL string) (string, error) {
	if baseURL == "" {
		return "github.com", nil
	}
	u, err := url.Parse(baseURL)
	if err != nil || u.Host == "" || u.User != nil {
		return "", fmt.Errorf("%w: correct the installation's GitHub API URL", auth.ErrInvalidInput)
	}
	host := strings.ToLower(u.Host)
	if host == "api.github.com" {
		host = "github.com"
	}
	return host, nil
}

func (c *Controller) FindAIContextDraft(ctx context.Context, installationID string, repositoryID int64) (*store.AIContextRepository, error) {
	inst, err := c.st.GetInstallation(ctx, installationID)
	if err != nil {
		return nil, err
	}
	host, err := aiContextGitHubHost(inst.APIBaseURL)
	if err != nil {
		return nil, err
	}
	if repositoryID <= 0 {
		return nil, fmt.Errorf("%w: choose a known repository ID", auth.ErrInvalidInput)
	}
	return c.st.FindAIContextRepository(ctx, aicontext.RepositoryKey{GitHubHost: host, InstallationID: installationID, RepositoryID: repositoryID})
}

package controller

import (
	"context"
	"fmt"
	"strconv"
	"time"

	"github.com/eyupio/zoomies/internal/aicontext"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

// aiContextDiagnosis is what the controller last read about the newest run of a
// repository's managed workflow for one commit. It is kept so that the five
// minute loop does not download the same log again and again: a run that has
// finished does not change, so it is read once and looked up after that.
type aiContextDiagnosis struct {
	commit string
	// runKey changes whenever the run does -- a new run, or the same one moving
	// from queued to finished -- and is what makes a cached reading still true.
	runKey    string
	outcome   aicontext.Outcome
	diagnosis *aicontext.Diagnosis
	// finished is when the run ended, which is what waiting before the next
	// attempt is counted from.
	finished time.Time
}

// diagnoseAIContext reads the newest run for commit and says why it failed, if it
// did. It returns nil when nothing is known -- the repository has no run for that
// commit, or GitHub could not be asked -- and the caller then does what it always
// did. A diagnosis only ever adds to what Zoomies knew; it is never required.
func (c *Controller) diagnoseAIContext(ctx context.Context, r *store.AIContextRepository, commit string) *aiContextDiagnosis {
	client, err := c.ClientFor(ctx, r.Key.InstallationID)
	if err != nil {
		return nil
	}
	reader, ok := client.(github.ContextRunReader)
	if !ok {
		return nil
	}
	run, err := reader.LatestContextRun(ctx, r.FullName, commit)
	if err != nil {
		// Reading is a courtesy: the check that found the context stale already
		// reported what it could, and a log line per pass would bury it.
		c.log.Debug("could not read the AI Context workflow's runs", "repository", r.ID, "error", err)
		return nil
	}
	if run == nil {
		c.forgetAIContextDiagnosis(r.ID)
		return nil
	}
	key := strconv.FormatInt(run.ID, 10) + "/" + run.Facts.Status + "/" + run.Facts.Conclusion + "/" + strconv.FormatInt(run.UpdatedAt.Unix(), 10)
	c.aiContextRunsMu.Lock()
	cached := c.aiContextDiagnoses[r.ID]
	c.aiContextRunsMu.Unlock()
	if cached != nil && cached.commit == commit && cached.runKey == key {
		return cached
	}

	facts := run.Facts
	// Only the job Diagnose will look at is worth a download, and only if it ran:
	// a job that never started has no log, and the answer is already in its shape.
	if i := aicontext.FirstFailedJob(facts.Jobs); facts.Status == "completed" && i >= 0 && facts.Jobs[i].Started() {
		if lines, err := reader.ContextJobErrors(ctx, r.FullName, run.JobIDs[i]); err == nil {
			facts.Jobs[i].Errors = lines
		}
	}
	outcome, d := aicontext.Diagnose(facts)
	entry := &aiContextDiagnosis{commit: commit, runKey: key, outcome: outcome, diagnosis: d, finished: run.UpdatedAt}
	if d != nil {
		d.Commit, d.RunURL, d.FailedAt, d.ObservedAt = commit, run.URL, run.UpdatedAt, c.Now()
		if d.Cause == aicontext.CauseArtifactQuota {
			// "Full" is half an answer; what holds it is the other half.
			if usage, err := reader.ContextArtifactUsage(ctx, r.FullName); err == nil {
				*d = d.WithArtifactUsage(*usage)
			}
		}
	}
	c.aiContextRunsMu.Lock()
	c.aiContextDiagnoses[r.ID] = entry
	c.aiContextRunsMu.Unlock()
	return entry
}

// noteAIContextStart records that the workflow was just started, by Zoomies or
// by a person pressing Regenerate.
//
// GitHub can take a few seconds to list a run it has just accepted. In that gap
// the next pass would read the run before it -- still failed, and long enough ago
// -- and start another, which the workflow's concurrency group would answer by
// cancelling the first. Counting the start towards spacing closes the gap, and
// puts the old failure out of the card until the new run can be read. It is not
// counted as an attempt: those are Zoomies' own, and a person asking is not one.
func (c *Controller) noteAIContextStart(ctx context.Context, id string) {
	f, err := c.st.GetAIContextFreshness(ctx, id)
	if err != nil || f.DesiredCommit == "" {
		c.forgetAIContextDiagnosis(id)
		return
	}
	now := c.Now()
	c.aiContextRunsMu.Lock()
	defer c.aiContextRunsMu.Unlock()
	run := c.aiContextRuns[id]
	if run == nil || run.commit != f.DesiredCommit {
		run = &aiContextRun{commit: f.DesiredCommit, since: now}
		c.aiContextRuns[id] = run
	}
	run.lastStart = now
	c.aiContextDiagnoses[id] = &aiContextDiagnosis{commit: f.DesiredCommit, runKey: "started", outcome: aicontext.OutcomeRunning}
}

func (c *Controller) forgetAIContextDiagnosis(id string) {
	c.aiContextRunsMu.Lock()
	delete(c.aiContextDiagnoses, id)
	c.aiContextRunsMu.Unlock()
}

// aiContextRunDue is whether Zoomies should start the workflow now.
//
// What it knows decides how long it waits. A run still working is left alone --
// the workflow's concurrency group would cancel it -- and a failure is judged by
// its cause: one a new run could not change is not retried, one GitHub needs
// time to clear is waited out for as long as GitHub says, and the rest are tried
// at the pace Zoomies has always used. With no reading at all -- no run exists
// for the commit, or the last one succeeded and the context is still behind --
// it is the original rule: a grace for the push-triggered run, then a bounded
// number of attempts.
func aiContextRunDue(now time.Time, grace time.Duration, run *aiContextRun, known *aiContextDiagnosis) bool {
	if known != nil {
		switch {
		case known.outcome == aicontext.OutcomeRunning:
			return false
		case known.diagnosis != nil:
			p := known.diagnosis.Cause.Policy()
			return p.Automatic && run.attempts < p.Attempts &&
				!now.Before(known.finished.Add(p.After)) &&
				(run.lastStart.IsZero() || now.Sub(run.lastStart) >= p.After)
		}
	}
	return now.Sub(run.since) >= grace && run.attempts < aiContextRunAttempts &&
		(run.lastStart.IsZero() || now.Sub(run.lastStart) >= aiContextRunSpacing)
}

// AIContextDiagnosis is what the repository's card and the API show about the
// failed run, with what Zoomies means to do about it. It is nil unless the
// context is behind and a run for the commit it is waiting for failed.
func (c *Controller) AIContextDiagnosis(r *store.AIContextRepository) *aicontext.Diagnosis {
	if r == nil || r.Freshness == nil || r.Freshness.State != "stale" || r.Config.Disabled {
		return nil
	}
	c.aiContextRunsMu.Lock()
	defer c.aiContextRunsMu.Unlock()
	known := c.aiContextDiagnoses[r.ID]
	if known == nil || known.diagnosis == nil || known.commit != r.Freshness.DesiredCommit {
		return nil
	}
	out := *known.diagnosis
	out.Retry = c.aiContextRetryPlanLocked(r.ID, known)
	return &out
}

// aiContextRetryPlanLocked is what Zoomies will do about a failure unprompted.
func (c *Controller) aiContextRetryPlanLocked(id string, known *aiContextDiagnosis) *aicontext.RetryPlan {
	p := known.diagnosis.Cause.Policy()
	plan := &aicontext.RetryPlan{}
	if !p.Automatic {
		return plan
	}
	attempts, last := 0, time.Time{}
	if run := c.aiContextRuns[id]; run != nil && run.commit == known.commit {
		attempts, last = run.attempts, run.lastStart
	}
	plan.AttemptsLeft = max(p.Attempts-attempts, 0)
	if plan.AttemptsLeft == 0 {
		return plan
	}
	next := known.finished.Add(p.After)
	if !last.IsZero() && last.Add(p.After).After(next) {
		next = last.Add(p.After)
	}
	// A time already gone means the next pass, not a date in the past.
	next = later(next, c.Now())
	plan.Automatic, plan.NextAt = true, &next
	return plan
}

func later(a, b time.Time) time.Time {
	if a.After(b) {
		return a
	}
	return b
}

// aiContextStaleReason is the sentence the card carries while the context is
// behind. With a diagnosis for the commit it is that, and otherwise the generic
// reason the check produced; the suffix says what became of the old snapshot.
func (c *Controller) aiContextStaleReason(id, commit, generic, suffix string) string {
	c.aiContextRunsMu.Lock()
	known := c.aiContextDiagnoses[id]
	c.aiContextRunsMu.Unlock()
	if known != nil && known.diagnosis != nil && known.commit == commit {
		return known.diagnosis.Summary() + suffix
	}
	return generic
}

// aiContextProblemShapes is each cause as a problem: its code and how loudly it
// should be said. The codes are literal here, and not built from the cause, so
// that the documentation test can find every one.
//
// A cause that needs a person before a run can succeed is an error, because the
// context stays stale until somebody acts. One Zoomies expects to clear by
// itself is a warning: worth knowing, not worth waking anybody.
var aiContextProblemShapes = map[aicontext.Cause]Problem{
	aicontext.CauseArtifactQuota:      {Code: "ai_context.artifact_quota", Severity: config.SeverityError},
	aicontext.CauseArtifactUpload:     {Code: "ai_context.artifact_upload_failed", Severity: config.SeverityWarning},
	aicontext.CauseRunnerUnavailable:  {Code: "ai_context.runner_unavailable", Severity: config.SeverityWarning},
	aicontext.CauseStartupFailed:      {Code: "ai_context.startup_failed", Severity: config.SeverityError},
	aicontext.CauseSetupFailed:        {Code: "ai_context.setup_failed", Severity: config.SeverityWarning},
	aicontext.CauseOversizedFile:      {Code: "ai_context.oversized_file", Severity: config.SeverityError},
	aicontext.CauseTooMuchSource:      {Code: "ai_context.too_much_source", Severity: config.SeverityError},
	aicontext.CauseGenerationRefused:  {Code: "ai_context.generation_refused", Severity: config.SeverityError},
	aicontext.CausePublicationRefused: {Code: "ai_context.publication_refused", Severity: config.SeverityError},
	aicontext.CauseDeliveryFailed:     {Code: "ai_context.delivery_failed", Severity: config.SeverityError},
	aicontext.CauseTimedOut:           {Code: "ai_context.timed_out", Severity: config.SeverityWarning},
	aicontext.CauseUnknown:            {Code: "ai_context.run_failed", Severity: config.SeverityWarning},
}

// aiContextProblems raises one problem per repository whose context is behind
// because the managed workflow failed. The card already says it; this is the same
// sentence where an operator who is not looking at that page will see it, and
// where an assistant asking for problems will.
func (c *Controller) aiContextProblems(ctx context.Context, out *[]Problem) error {
	c.aiContextRunsMu.Lock()
	ids := make([]string, 0, len(c.aiContextDiagnoses))
	for id, known := range c.aiContextDiagnoses {
		if known.diagnosis != nil {
			ids = append(ids, id)
		}
	}
	c.aiContextRunsMu.Unlock()
	for _, id := range ids {
		r, err := c.st.GetAIContextRepository(ctx, id)
		if err != nil {
			// A repository that has gone has no problem; one that could not be
			// read is a database fault the other sections will report.
			continue
		}
		d := c.AIContextDiagnosis(r)
		if d == nil {
			continue
		}
		shape, ok := aiContextProblemShapes[d.Cause]
		if !ok {
			shape = aiContextProblemShapes[aicontext.CauseUnknown]
		}
		failed := d.FailedAt
		*out = append(*out, Problem{
			Code: shape.Code, Severity: shape.Severity,
			Title:      d.Title + " (" + r.FullName + ")",
			Detail:     d.Detail,
			Fix:        d.Fix + " " + aiContextRetrySentence(d),
			TargetKind: "ai_context", TargetID: r.ID, Since: &failed,
		})
	}
	return nil
}

// aiContextRetrySentence says what Zoomies will do next, so that "it will fix
// itself" and "it will not" are never left for the reader to guess.
func aiContextRetrySentence(d *aicontext.Diagnosis) string {
	switch {
	case d.Retry != nil && d.Retry.Automatic && d.Retry.NextAt != nil:
		return fmt.Sprintf("Zoomies will start the workflow again from %s (%s left for this commit).",
			d.Retry.NextAt.UTC().Format("2 Jan 15:04 MST"), plural(d.Retry.AttemptsLeft, "attempt"))
	case d.Cause.Policy().Automatic:
		return "Zoomies has started the workflow as often as it will for this commit; use Regenerate once the cause is fixed."
	default:
		return "Zoomies will not start the workflow again until this is fixed, because it would fail the same way."
	}
}

package controller

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/aicontext"
)

func failedRead(cause aicontext.Cause, finished time.Time) *aiContextDiagnosis {
	return &aiContextDiagnosis{outcome: aicontext.OutcomeFailed, diagnosis: &aicontext.Diagnosis{Cause: cause}, finished: finished}
}

// How long Zoomies waits, and how often it tries, is a decision about money and
// patience rather than about code, so each row says what it is protecting.
func TestRunDueWaitsAsLongAsTheCauseNeeds(t *testing.T) {
	now := time.Date(2026, 10, 6, 12, 0, 0, 0, time.UTC)
	ago := func(d time.Duration) time.Time { return now.Add(-d) }
	tests := []struct {
		name  string
		run   aiContextRun
		known *aiContextDiagnosis
		grace time.Duration
		want  bool
	}{
		{
			// A run in progress is the one thing that must never be started over:
			// the concurrency group cancels it, and with it the work it has done.
			name:  "a run still working is left alone however long it has taken",
			run:   aiContextRun{since: ago(48 * time.Hour)},
			known: &aiContextDiagnosis{outcome: aicontext.OutcomeRunning},
			want:  false,
		},
		{
			// GitHub recalculates storage every six to twelve hours; an hour-old
			// failure would only fail again.
			name:  "a full quota is not retried within GitHub's recalculation window",
			run:   aiContextRun{since: ago(2 * time.Hour)},
			known: failedRead(aicontext.CauseArtifactQuota, ago(5*time.Hour+59*time.Minute)),
			want:  false,
		},
		{
			name:  "a full quota is retried once the window has passed",
			run:   aiContextRun{since: ago(8 * time.Hour)},
			known: failedRead(aicontext.CauseArtifactQuota, ago(6*time.Hour)),
			want:  true,
		},
		{
			name:  "a full quota is tried three times and then left to a person",
			run:   aiContextRun{since: ago(40 * time.Hour), attempts: 3, lastStart: ago(7 * time.Hour)},
			known: failedRead(aicontext.CauseArtifactQuota, ago(7*time.Hour)),
			want:  false,
		},
		{
			name:  "a second quota attempt waits the window from the first, not from the failure",
			run:   aiContextRun{since: ago(12 * time.Hour), attempts: 1, lastStart: ago(3 * time.Hour)},
			known: failedRead(aicontext.CauseArtifactQuota, ago(8*time.Hour)),
			want:  false,
		},
		{
			// The point of the change: the old rule would have started this one
			// after the grace and again half an hour later, for ever the same.
			name:  "an oversized file is never retried",
			run:   aiContextRun{since: ago(72 * time.Hour)},
			known: failedRead(aicontext.CauseOversizedFile, ago(72*time.Hour)),
			want:  false,
		},
		{
			name:  "a runner GitHub failed to give is retried after half an hour",
			run:   aiContextRun{since: ago(time.Hour)},
			known: failedRead(aicontext.CauseRunnerUnavailable, ago(31*time.Minute)),
			want:  true,
		},
		{
			// A cause Zoomies has read replaces the grace it would otherwise sit
			// out: the grace is for a push-triggered run nobody has looked at.
			name:  "a diagnosed failure ignores the grace period",
			run:   aiContextRun{since: ago(time.Minute)},
			known: failedRead(aicontext.CauseRunnerUnavailable, ago(40*time.Minute)),
			grace: time.Hour,
			want:  true,
		},
		{
			name:  "a runner failure gets four attempts, not two",
			run:   aiContextRun{since: ago(4 * time.Hour), attempts: 3, lastStart: ago(31 * time.Minute)},
			known: failedRead(aicontext.CauseRunnerUnavailable, ago(31*time.Minute)),
			want:  true,
		},
		{
			name:  "nothing known keeps the original rule: wait out the grace",
			run:   aiContextRun{since: ago(10 * time.Minute)},
			grace: 30 * time.Minute,
			want:  false,
		},
		{
			name:  "nothing known keeps the original rule: then start it",
			run:   aiContextRun{since: ago(31 * time.Minute)},
			grace: 30 * time.Minute,
			want:  true,
		},
		{
			name: "nothing known keeps the original rule: twice at most",
			run:  aiContextRun{since: ago(5 * time.Hour), attempts: aiContextRunAttempts, lastStart: ago(2 * time.Hour)},
			want: false,
		},
		{
			// The run succeeded and the context is still behind, so the run is
			// not the explanation; fall back to waiting for publication.
			name:  "a successful run gives no reason to start another before the grace",
			run:   aiContextRun{since: ago(time.Minute)},
			known: &aiContextDiagnosis{outcome: aicontext.OutcomeSucceeded},
			grace: time.Hour,
			want:  false,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := aiContextRunDue(now, tt.grace, &tt.run, tt.known); got != tt.want {
				t.Errorf("due = %v, want %v", got, tt.want)
			}
		})
	}
}

func TestRetryPlanSaysWhenAndHowOftenZoomiesWillTryAgain(t *testing.T) {
	now := time.Date(2026, 10, 6, 12, 0, 0, 0, time.UTC)
	c := &Controller{clock: func() time.Time { return now }, aiContextRuns: map[string]*aiContextRun{}}
	known := failedRead(aicontext.CauseArtifactQuota, now.Add(-time.Hour))
	known.commit = "abc"

	plan := c.aiContextRetryPlanLocked("r", known)
	if !plan.Automatic || plan.AttemptsLeft != 3 || plan.NextAt == nil || !plan.NextAt.Equal(now.Add(5*time.Hour)) {
		t.Fatalf("plan = %+v, want three attempts, the first at 17:00", plan)
	}

	// Having started it, the wait counts from then, and the attempt is used.
	c.aiContextRuns["r"] = &aiContextRun{commit: "abc", attempts: 1, lastStart: now.Add(-time.Minute)}
	plan = c.aiContextRetryPlanLocked("r", known)
	if plan.AttemptsLeft != 2 || !plan.NextAt.Equal(now.Add(6*time.Hour-time.Minute)) {
		t.Fatalf("after one attempt: %+v", plan)
	}

	// Attempts for another commit are not this commit's.
	c.aiContextRuns["r"] = &aiContextRun{commit: "other", attempts: 3, lastStart: now}
	if plan = c.aiContextRetryPlanLocked("r", known); plan.AttemptsLeft != 3 {
		t.Errorf("another commit's attempts were counted: %+v", plan)
	}

	// Used up, or never going to happen: no time is promised.
	c.aiContextRuns["r"] = &aiContextRun{commit: "abc", attempts: 3}
	if plan = c.aiContextRetryPlanLocked("r", known); plan.Automatic || plan.NextAt != nil {
		t.Errorf("exhausted plan promises a retry: %+v", plan)
	}
	stuck := failedRead(aicontext.CauseOversizedFile, now)
	stuck.commit = "abc"
	if plan = c.aiContextRetryPlanLocked("r", stuck); plan.Automatic || plan.NextAt != nil || plan.AttemptsLeft != 0 {
		t.Errorf("a cause no run can fix promises a retry: %+v", plan)
	}

	// A time already gone means the next pass.
	old := failedRead(aicontext.CauseRunnerUnavailable, now.Add(-5*time.Hour))
	old.commit = "abc"
	c.aiContextRuns["r"] = nil
	if plan = c.aiContextRetryPlanLocked("r", old); plan.NextAt == nil || plan.NextAt.Before(now) {
		t.Errorf("next attempt in the past: %+v", plan)
	}
}

func TestEveryCauseHasAProblemCodeWithItsOwnSentence(t *testing.T) {
	seen := map[string]aicontext.Cause{}
	for _, cause := range aicontext.Causes {
		shape, ok := aiContextProblemShapes[cause]
		if !ok || shape.Code == "" || !strings.HasPrefix(shape.Code, "ai_context.") {
			t.Errorf("%s has no problem code: %+v", cause, shape)
			continue
		}
		if other, dup := seen[shape.Code]; dup {
			t.Errorf("%s and %s share the code %s", cause, other, shape.Code)
		}
		seen[shape.Code] = cause
		if audienceFor(shape.Code) != AudienceFleet {
			t.Errorf("%s: an AI Context failure is the fleet's to act on, got %q", shape.Code, audienceFor(shape.Code))
		}
	}
}

func TestRetrySentenceNeverLeavesTheReaderGuessing(t *testing.T) {
	next := time.Date(2026, 10, 6, 18, 0, 0, 0, time.UTC)
	tests := []struct {
		name string
		d    aicontext.Diagnosis
		want string
	}{
		{"will retry", aicontext.Diagnosis{Cause: aicontext.CauseArtifactQuota, Retry: &aicontext.RetryPlan{Automatic: true, NextAt: &next, AttemptsLeft: 2}}, "from 6 Oct 18:00 UTC (2 attempts left"},
		{"will not", aicontext.Diagnosis{Cause: aicontext.CauseOversizedFile, Retry: &aicontext.RetryPlan{}}, "will not start the workflow again until this is fixed"},
		{"gave up", aicontext.Diagnosis{Cause: aicontext.CauseArtifactQuota, Retry: &aicontext.RetryPlan{}}, "as often as it will"},
	}
	for _, tt := range tests {
		if got := aiContextRetrySentence(&tt.d); !strings.Contains(got, tt.want) {
			t.Errorf("%s: %q does not contain %q", tt.name, got, tt.want)
		}
	}
}

