		{"deleted provider", func(t *testing.T, h *harness, instID string) string {
			return installationProvider(t, h, "Gone", true).ID
		}, func(t *testing.T, h *harness, providerID string) {
			if err := h.st.DeleteAssistantProvider(h.ctx, providerID); err != nil {
				t.Fatal(err)
			}
		}},
		{"disabled provider", func(t *testing.T, h *harness, instID string) string {
			return installationProvider(t, h, "Sleepy", false).ID
		}, nil},
		{"personal provider", func(t *testing.T, h *harness, instID string) string {
			user := &store.User{Username: "octo", Role: store.RoleViewer}
			if err := h.st.CreateUser(h.ctx, user); err != nil {
				t.Fatal(err)
			}
			p := &store.AssistantProvider{Name: "Mine", OwnerID: user.ID, Kind: "openai", Model: "m", Enabled: true}
			if err := h.st.CreateAssistantProvider(h.ctx, p); err != nil {
				t.Fatal(err)
			}
			return p.ID
		}, nil},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			inst := h.installation()
			repo := inst.Target + "/repo"
			fake := &repairFake{Client: h.gh.Client(inst.Target, inst.TargetType)}
			h.c.clients.entries[inst.ID] = &clientEntry{client: fake, updatedAt: inst.UpdatedAt.Truncate(time.Millisecond)}
			providerID := tc.setup(t, h, inst.ID)
			savePolicy(t, h, store.EliRepairPolicy{Repo: repo, InstallationID: inst.ID, ProviderID: providerID, Enabled: true, Automatic: true, DailyLimit: 3})
			if tc.after != nil {
				tc.after(t, h, providerID)
			}
			body, _ := json.Marshal(map[string]any{"action": "completed", "repository": map[string]any{"full_name": repo}, "workflow_job": map[string]any{"id": 12, "run_id": 9, "head_sha": "old", "conclusion": "failure"}})
			if err := h.c.enqueueRepairWebhook(h.ctx, inst, "workflow_job", body); err != nil {
				t.Fatal(err)
			}
			rows, _, _ := h.st.ListEliRepairsPage(h.ctx, store.EliRepairFilter{Limit: store.MaxEliRepairPage})
			if len(rows) != 0 {
				t.Fatalf("a repair was queued with no provider able to pay: %+v", rows)
			}
		})
	}
}

// The dialog promises that a repair which has not pushed yet stops without
// changing the branch. The queued checkpoint is pinned above; this pins the one
// the worker reaches after the model has answered, the last before the first
// write, for both ways of stopping.
func TestAStopWhileTheModelIsWorkingPublishesNothing(t *testing.T) {
	for _, then := range []string{EliStopAskFirst, EliStopOff} {
		t.Run(then, func(t *testing.T) {
			h := newHarness(t)
			inst := h.installation()
			repo := inst.Target + "/repo"
			fake := &repairFake{Client: h.gh.Client(inst.Target, inst.TargetType), check: "failed"}
			h.c.clients.entries[inst.ID] = &clientEntry{client: fake, updatedAt: inst.UpdatedAt.Truncate(time.Millisecond)}
			srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				// The administrator presses Stop while the model is still answering.
				if _, err := h.c.StopEliAutomatic(h.ctx, []string{repo}, then); err != nil {
					t.Error(err)
				}
				w.Header().Set("Content-Type", "text/event-stream")
				chunk, _ := json.Marshal(map[string]any{"choices": []any{map[string]any{"index": 0, "delta": map[string]string{"content": `{"summary":"Fix cause","files":[{"path":"main.go","content":"fixed"}]}`}, "finish_reason": nil}}})
				fmt.Fprintf(w, "data: %s\n\ndata: [DONE]\n\n", chunk)
			}))
			defer srv.Close()
			team := &store.AssistantProvider{Name: "Team", Kind: "openai_compatible", BaseURL: srv.URL, Model: "team-model", Enabled: true}
			if err := h.st.CreateAssistantProvider(h.ctx, team); err != nil {
				t.Fatal(err)
			}
			savePolicy(t, h, store.EliRepairPolicy{Repo: repo, InstallationID: inst.ID, ProviderID: team.ID, Enabled: true, Automatic: true})
			row := &store.EliRepair{DedupKey: "automatic:" + repo + ":old", Repo: repo, InstallationID: inst.ID, PullNumber: 1, HeadSHA: "old", RunID: 9, Trigger: "automatic"}
			if _, err := h.st.EnqueueEliRepair(h.ctx, row, 5); err != nil {
				t.Fatal(err)
			}

			h.c.runEliRepair(h.ctx, row)
			if row.State != "failed" || fake.commits != 0 {
				t.Fatalf("a repair stopped while the model worked ended %q with %d commits: %q", row.State, fake.commits, row.Message)
			}
		})
	}
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"slices"
	"strconv"
	"sync"
	"time"

	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/prrepair"
	"github.com/eyupio/zoomies/internal/store"
)

const (
	// errorOutputFor is how long a read of a job's error output is reused. Opening
	// a failure twice, or two people opening the same one, is one download of the
	// log; a minute is short enough that a re-run's output is not hidden for long.
	errorOutputFor = time.Minute
	// errorOutputKept bounds the copies held, so a long run of different
	// failures cannot grow the controller's memory.
	errorOutputKept = 256
)

// ErrEliErrorOutputDenied is a caller who may not read a job's error output:
// no confirmed GitHub account, no write access to the repository through it, or
// a repository no installation serves. They are one error on purpose; which of
// them it was is not something to tell a person who may not know the repository.
var ErrEliErrorOutputDenied = errors.New("controller: error output is only for people who can write to the repository")

// EliErrorOutput is the lines of a failed job's log that say why it failed.
// Note is a sentence for the person when there are none to show.
type EliErrorOutput struct {
	Lines []string `json:"lines"`
	Note  string   `json:"note,omitempty"`
}

// EliErrorOutput reads the error lines of one job for a person who could fix
// the pull request. It is on demand and it keeps nothing: the lines are never
// stored and never logged, because a log is where a job's secrets end up and
// the repair record is read by more people than could read the job. They are
// passed through the same redaction the model's evidence gets, held in memory
// for a minute so a second look is not a second download, and handed back.
//
// The access check runs on every call, before the copy in memory is looked at.
// The copy belongs to a job, not to a person, and the one person who could read
// it must not be how another one does.
func (c *Controller) EliErrorOutput(ctx context.Context, user, repo string, jobID int64) (EliErrorOutput, error) {
	repo = normaliseRepairRepo(repo)
	if jobID < 1 {
		return EliErrorOutput{}, fmt.Errorf("controller: a job id is needed to read its error output")
	}
	id, err := c.eliIdentity(ctx, user)
	if errors.Is(err, store.ErrNotFound) {
		return EliErrorOutput{}, ErrEliErrorOutputDenied
	}
	if err != nil {
		return EliErrorOutput{}, err
	}
	inst, err := c.st.FindInstallationByTarget(ctx, repo)
	if errors.Is(err, store.ErrNotFound) {
		return EliErrorOutput{}, ErrEliErrorOutputDenied
	}
	if err != nil {
		return EliErrorOutput{}, err
	}
	raw, err := c.ClientFor(ctx, inst.ID)
	if err != nil {
		return EliErrorOutput{}, fmt.Errorf("the GitHub installation for %s is unavailable: %w", repo, err)
	}
	client, ok := raw.(github.RepairClient)
	if !ok {
		return EliErrorOutput{}, ErrEliErrorOutputDenied
	}
	actor, err := client.RepairActor(ctx, repo, id.GitHubLogin)
	if err != nil || !actor.CanWrite || actor.ID != id.GitHubUserID {
		return EliErrorOutput{}, ErrEliErrorOutputDenied
	}

	key := repo + "#" + strconv.FormatInt(jobID, 10)
	if out, ok := c.errorOutput.get(key, c.Now()); ok {
		return out, nil
	}
	lines, err := client.RepairFailures(ctx, repo, github.RepairPull{}, jobID)
	if err != nil {
		return EliErrorOutput{}, err
	}
	out := EliErrorOutput{Lines: make([]string, 0, len(lines))}
	for _, line := range lines {
		out.Lines = append(out.Lines, prrepair.Redact(line))
	}
	if len(out.Lines) == 0 {
		out.Note = "GitHub no longer has this log, or the job printed no error lines."
	}
	c.errorOutput.put(key, out, c.Now())
	return out, nil
}

// errorOutputCache is the last few reads of a job's error output. It is the
// only place those lines live, in memory, and a restart forgets them.
type errorOutputCache struct {
	mu      sync.Mutex
	entries map[string]errorOutputEntry
}

type errorOutputEntry struct {
	out     EliErrorOutput
	expires time.Time
}

func (k *errorOutputCache) get(key string, now time.Time) (EliErrorOutput, bool) {
	k.mu.Lock()
	defer k.mu.Unlock()
	e, ok := k.entries[key]
	if !ok || !now.Before(e.expires) {
		return EliErrorOutput{}, false
	}
	e.out.Lines = slices.Clone(e.out.Lines)
	return e.out, true
}

// put keeps out for errorOutputFor. It first drops every copy that has
// expired, then the oldest of the rest while the cache is full, so the bound
// holds however fast different jobs are asked for.
func (k *errorOutputCache) put(key string, out EliErrorOutput, now time.Time) {
	k.mu.Lock()
	defer k.mu.Unlock()
	if k.entries == nil {
		k.entries = map[string]errorOutputEntry{}
	}
	for held, e := range k.entries {
		if !now.Before(e.expires) {
			delete(k.entries, held)
		}
	}
	for len(k.entries) >= errorOutputKept {
		oldest, oldestAt := "", time.Time{}
		for held, e := range k.entries {
			if oldest == "" || e.expires.Before(oldestAt) {
				oldest, oldestAt = held, e.expires
			}
		}
		delete(k.entries, oldest)
	}
	out.Lines = slices.Clone(out.Lines)
	k.entries[key] = errorOutputEntry{out: out, expires: now.Add(errorOutputFor)}
}

func (k *errorOutputCache) size() int {
	k.mu.Lock()
	defer k.mu.Unlock()
	return len(k.entries)
}

package controller

import (
	"bytes"
	"errors"
	"fmt"
	"log/slog"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// errorOutputSetup is a person who may read a job's error output: linked,
// confirmed and able to write to the repository. A test then takes one of those
// away, and counts how often GitHub was asked and for which job.
func errorOutputSetup(t *testing.T) (*commandSetup, *[]int64) {
	t.Helper()
	s := newCommandSetup(t, 5)
	s.link(t, true)
	var reads []int64
	s.fake.onFailures = func(jobID int64) ([]string, error) {
		reads = append(reads, jobID)
		return []string{"npm ERR! test failed", "Error: expected 3 got 4"}, nil
	}
	return s, &reads
}

// Error output is the log of a job, and a log is where credentials end up. It
// is read for the people who could fix the pull request and nobody else, so a
// caller who is not linked, has not confirmed the link, or cannot write to the
// repository gets nothing, and a copy another person's read left in memory is
// not a way round that.
func TestErrorOutputRefusesAnUnlinkedOrReadOnlyCaller(t *testing.T) {
	s, reads := errorOutputSetup(t)
	other := &store.User{Username: "stranger", Role: store.RoleViewer}
	if err := s.h.st.CreateUser(s.h.ctx, other); err != nil {
		t.Fatal(err)
	}
	unconfirmed := &store.User{Username: "unconfirmed", Role: store.RoleViewer}
	if err := s.h.st.CreateUser(s.h.ctx, unconfirmed); err != nil {
		t.Fatal(err)
	}
	if err := s.h.st.SetEliIdentity(s.h.ctx, store.EliIdentity{UserID: unconfirmed.ID, GitHubUserID: 43, GitHubLogin: "unconfirmed"}); err != nil {
		t.Fatal(err)
	}

	// Warm the cache with a read that is allowed.
	if _, err := s.h.c.EliErrorOutput(s.h.ctx, s.user.ID, s.repo, 7); err != nil {
		t.Fatal(err)
	}
	if len(*reads) != 1 {
		t.Fatalf("%d reads of GitHub, want 1", len(*reads))
	}

	for name, tc := range map[string]struct {
		user    string
		noWrite bool
	}{
		"nobody linked":        {user: other.ID},
		"a link not confirmed": {user: unconfirmed.ID},
		"no such user":         {user: "usr_nobody"},
		"read-only on GitHub":  {user: s.user.ID, noWrite: true},
	} {
		s.fake.noWrite = tc.noWrite
		got, err := s.h.c.EliErrorOutput(s.h.ctx, tc.user, s.repo, 7)
		if !errors.Is(err, ErrEliErrorOutputDenied) {
			t.Errorf("%s: error %v, want ErrEliErrorOutputDenied", name, err)
		}
		if len(got.Lines) != 0 {
			t.Errorf("%s: handed %d lines to someone who may not read them", name, len(got.Lines))
		}
	}
	s.fake.noWrite = false
	if len(*reads) != 1 {
		t.Errorf("%d reads of GitHub, want only the allowed one: a refused caller must not cost a read", len(*reads))
	}
}

// A log can hold anything the job printed, and the page that shows it is not
// where a leaked token should be found.
func TestErrorOutputRedactsWhatItReturns(t *testing.T) {
	s, _ := errorOutputSetup(t)
	token := "ghp_" + strings.Repeat("a1B2", 9)
	s.fake.onFailures = func(int64) ([]string, error) {
		return []string{"npm ERR! publish failed with token " + token, "Error: plain line"}, nil
	}
	got, err := s.h.c.EliErrorOutput(s.h.ctx, s.user.ID, s.repo, 7)
	if err != nil {
		t.Fatal(err)
	}
	if len(got.Lines) != 2 || strings.Contains(strings.Join(got.Lines, "\n"), token) {
		t.Fatalf("lines = %q, want the token gone", got.Lines)
	}
	if !strings.Contains(got.Lines[0], "[redacted credential]") || got.Lines[1] != "Error: plain line" {
		t.Errorf("lines = %q, want the token replaced and the other line untouched", got.Lines)
	}
}

// Opening a failure twice, or two people opening the same one, should not cost
// GitHub a log download each: the second read inside a minute is the first.
func TestErrorOutputReadsGitHubOncePerMinute(t *testing.T) {
	s, reads := errorOutputSetup(t)
	read := func(job int64) EliErrorOutput {
		t.Helper()
		got, err := s.h.c.EliErrorOutput(s.h.ctx, s.user.ID, s.repo, job)
		if err != nil {
			t.Fatal(err)
		}
		return got
	}
	first := read(7)
	s.h.advance(30 * time.Second)
	second := read(7)
	if len(*reads) != 1 || strings.Join(first.Lines, "|") != strings.Join(second.Lines, "|") {
		t.Fatalf("two reads inside a minute made %d requests of GitHub", len(*reads))
	}
	read(8)
	if len(*reads) != 2 || (*reads)[1] != 8 {
		t.Fatalf("another job was served from the first job's copy: reads %v", *reads)
	}
	s.h.advance(31 * time.Second)
	read(7)
	if len(*reads) != 3 || (*reads)[2] != 7 {
		t.Fatalf("a read after the minute was served from memory: reads %v", *reads)
	}
}

// Nothing here keeps what it reads: a copy lives a minute in memory, never more
// than a few hundred of them, and expired ones go as new ones arrive, so a long
// run of different failures cannot grow it.
func TestErrorOutputKeepsAFewCopiesForAMinuteAtMost(t *testing.T) {
	s, reads := errorOutputSetup(t)
	for job := int64(1); job <= 300; job++ {
		if _, err := s.h.c.EliErrorOutput(s.h.ctx, s.user.ID, s.repo, job); err != nil {
			t.Fatal(err)
		}
	}
	if n := s.h.c.errorOutput.size(); n > 256 {
		t.Fatalf("%d copies held, want at most 256", n)
	}
	s.h.advance(2 * time.Minute)
	if _, err := s.h.c.EliErrorOutput(s.h.ctx, s.user.ID, s.repo, 1000); err != nil {
		t.Fatal(err)
	}
	if n := s.h.c.errorOutput.size(); n != 1 {
		t.Fatalf("%d copies held after a minute with no reads, want only the new one", n)
	}
	if len(*reads) != 301 {
		t.Errorf("%d reads of GitHub, want one for each of 301 different jobs", len(*reads))
	}
}

// An expired log, or a job that printed no error lines, is an answer. It comes
// back as an empty list and a sentence, never as null, so the page can say it.
func TestErrorOutputSaysSoWhenTheLogIsGone(t *testing.T) {
	s, _ := errorOutputSetup(t)
	s.fake.onFailures = func(int64) ([]string, error) { return nil, nil }
	got, err := s.h.c.EliErrorOutput(s.h.ctx, s.user.ID, s.repo, 7)
	if err != nil {
		t.Fatal(err)
	}
	if got.Lines == nil || len(got.Lines) != 0 {
		t.Errorf("lines = %#v, want an empty list that is not null", got.Lines)
	}
	if got.Note != "GitHub no longer has this log, or the job printed no error lines." {
		t.Errorf("note = %q", got.Note)
	}
}

// A failure to read is not an answer and is not kept: the next ask tries again.
func TestErrorOutputDoesNotRememberAFailedRead(t *testing.T) {
	s, reads := errorOutputSetup(t)
	broken := true
	s.fake.onFailures = func(job int64) ([]string, error) {
		*reads = append(*reads, job)
		if broken {
			return nil, fmt.Errorf("github is unavailable")
		}
		return []string{"Error: x"}, nil
	}
	if _, err := s.h.c.EliErrorOutput(s.h.ctx, s.user.ID, s.repo, 7); err == nil || errors.Is(err, ErrEliErrorOutputDenied) {
		t.Fatalf("error %v, want the read's own failure", err)
	}
	broken = false
	got, err := s.h.c.EliErrorOutput(s.h.ctx, s.user.ID, s.repo, 7)
	if err != nil || len(got.Lines) != 1 || len(*reads) != 2 {
		t.Fatalf("lines %v, error %v, reads %v: the failure was kept", got.Lines, err, *reads)
	}
}

// What a job printed is the workflow's, and may be a secret that redaction does
// not know. It is shown to the person who asked and kept nowhere: not in a
// store row, and not in a log line the controller writes.
func TestErrorOutputLogsNoLinesAndWritesNothing(t *testing.T) {
	s, _ := errorOutputSetup(t)
	var logged bytes.Buffer
	s.h.c.log = slog.New(slog.NewTextHandler(&logged, &slog.HandlerOptions{Level: slog.LevelDebug}))
	s.fake.onFailures = func(int64) ([]string, error) {
		return []string{"password=hunter2 rejected by registry"}, nil
	}
	if _, err := s.h.c.EliErrorOutput(s.h.ctx, s.user.ID, s.repo, 7); err != nil {
		t.Fatal(err)
	}
	if strings.Contains(logged.String(), "hunter2") {
		t.Errorf("a line of the log reached the controller's log: %s", logged.String())
	}
	if rows := s.rows(t); len(rows) != 0 {
		t.Errorf("reading error output wrote %d repairs", len(rows))
	}
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

type EliReadiness struct {
	Ready      bool   `json:"ready"`
	Repo       string `json:"repo"`
	PullNumber int    `json:"pull_number"`
	HeadSHA    string `json:"head_sha"`
	// Pull is the pull request in its own words. It is set only after the
	// caller's linked GitHub account has been shown to write to the repository,
	// so a person who may not see the repository is never told what is in it.
	Pull           *EliReadinessPull `json:"pull,omitempty"`
	Provider       string            `json:"provider"`
	Model          string            `json:"model"`
	AllowWorkflows bool              `json:"allow_workflows"`
	Remaining      int               `json:"remaining"`
	ResetAt        *time.Time        `json:"reset_at,omitempty"`
	// PolicyMode is how the repository's policy lets Eli help: automatic,
	// ask_first or manual. A page that offers to start a repair needs it to say
	// whether the repository would have started one itself. It is set once
	// readiness reaches the policy check, and not before.
	PolicyMode string `json:"policy_mode,omitempty"`
	// Blockers is what stands in the way, as it always has been. When the target
	// has changed (fixed, closed, superseded) it is that alone, which is the
	// answer to what the person asked; Checks still say what each check found.
	Blockers []EliBlocker `json:"blockers"`
	// Checks is every check readiness makes, in the order it makes them, so a
	// page can show what passed as well as what did not.
	Checks []EliCheck `json:"checks"`
}
type EliBlocker struct {
	Code    string `json:"code"`
	Message string `json:"message"`
}

// EliReadinessPull is the pull request a readiness answer is about.
type EliReadinessPull struct {
	Number int    `json:"number"`
	Title  string `json:"title"`
	Author string `json:"author"`
	Branch string `json:"branch"`
	Base   string `json:"base"`
	URL    string `json:"url"`
	Open   bool   `json:"open"`
}

// EliCheck is one thing readiness looks at and what it found. Status is
// EliCheckOK, EliCheckBlocked, or EliCheckUnchecked for a check readiness never
// reached because an earlier one stopped it: a check that was not made is not a
// check that passed, and the page must not draw it as one.
type EliCheck struct {
	Code    string `json:"code"`
	Status  string `json:"status"`
	Message string `json:"message"`
	// Blocker is the code of the blocker that stopped a blocked check. A check
	// says where readiness stopped and a blocker says why, and the two are not
	// the same thing: GitHub not answering is folded into whichever check it was
	// making. When the target has changed the answer's Blockers hold that change
	// alone, and a check blocked before it was found still names what stopped it.
	Blocker string `json:"blocker,omitempty"`
}

const (
	EliCheckOK        = "ok"
	EliCheckBlocked   = "blocked"
	EliCheckUnchecked = "unchecked"
)

// eliCheckCodes are the checks in the order readiness makes them, which is the
// order a page lists them in.
var eliCheckCodes = []string{"identity", "provider", "installation", "access", "policy", "budget", "pull", "checks", "permissions"}

// eliChecks records what readiness found as it goes. Anything it never reached
// is reported as not checked, whichever way the function returned.
type eliChecks map[string]EliCheck

func (c eliChecks) set(code, status, message string) {
	c[code] = EliCheck{Code: code, Status: status, Message: message}
}

// block marks a check blocked, and says by which blocker.
func (c eliChecks) block(code, blocker, message string) {
	c[code] = EliCheck{Code: code, Status: EliCheckBlocked, Message: message, Blocker: blocker}
}

func (c eliChecks) list() []EliCheck {
	out := make([]EliCheck, 0, len(eliCheckCodes))
	for _, code := range eliCheckCodes {
		check, ok := c[code]
		if !ok {
			check = EliCheck{Code: code, Status: EliCheckUnchecked, Message: "Not checked yet."}
		}
		out = append(out, check)
	}
	return out
}

func shortSHA(sha string) string {
	if len(sha) > 7 {
		return sha[:7]
	}
	return sha
}

// repairMode is the same distinction in the words the API uses.
func repairMode(p *store.EliRepairPolicy) string {
	switch {
	case p.Automatic:
		return "automatic"
	case p.AskFirst:
		return "ask_first"
	}
	return "manual"
}

// repairModeWords names how a repository's policy lets Eli help, for a finding.
func repairModeWords(p *store.EliRepairPolicy) string {
	switch {
	case p.Automatic:
		return "Automatic repair"
	case p.AskFirst:
		return "Ask me first"
	}
	return "Manual repair"
}

func (c *Controller) eliIdentity(ctx context.Context, user string) (*store.EliIdentity, error) {
	ids, err := c.st.EliIdentities(ctx)
	if err != nil {
		return nil, err
	}
	for _, id := range ids {
		if id.UserID == user && id.Confirmed {
			return &id, nil
		}
	}
	return nil, store.ErrNotFound
}
func (c *Controller) EliReadiness(ctx context.Context, user, repo string, pull int, run int64) (out EliReadiness) {
	out = EliReadiness{Repo: repo, PullNumber: pull, Blockers: []EliBlocker{}}
	checks := eliChecks{}
	defer func() { out.Checks = checks.list() }()
	// block records a blocker exactly as before and marks the check it belongs to.
	block := func(check, code, message string) {
		out.Blockers = append(out.Blockers, EliBlocker{code, message})
		checks.block(check, code, message)
	}
	id, err := c.eliIdentity(ctx, user)
	if err != nil {
		block("identity", "identity", "Link and confirm your GitHub account in repair setup.")
	} else {
		checks.set("identity", EliCheckOK, "@"+id.GitHubLogin+" is linked and has allowed repairs.")
	}
	provider, err := c.personalChatProvider(ctx, "", user)
	if err != nil {
		block("provider", "provider", "Add an enabled personal model provider in Eli settings.")
	} else {
		out.Provider = provider.Name
		out.Model = provider.Model
		checks.set("provider", EliCheckOK, provider.Name+" is enabled. Eli uses your provider, never a shared one.")
	}
	inst, err := c.st.FindInstallationByTarget(ctx, repo)
	if err != nil {
		block("installation", "installation", "Connect the GitHub installation that serves this repository.")
		return out
	}
	checks.set("installation", EliCheckOK, repo+" is served by the "+inst.Target+" GitHub installation.")
	if id == nil {
		return out
	}
	raw, err := c.ClientFor(ctx, inst.ID)
	if err != nil {
		block("installation", "github", "The GitHub installation is unavailable.")
		return out
	}
	client, ok := raw.(github.RepairClient)
	if !ok {
		block("installation", "github", "This installation cannot repair PRs.")
		return out
	}
	actor, err := client.RepairActor(ctx, repo, id.GitHubLogin)
	if err != nil || !actor.CanWrite || actor.ID != id.GitHubUserID {
		block("access", "access", "Your linked GitHub account needs write access to this repository.")
		return out
	}
	checks.set("access", EliCheckOK, "@"+id.GitHubLogin+" can write to "+repo+".")
	policy, err := c.repairPolicy(ctx, repo, inst.ID)
	if err != nil {
		block("policy", "policy", "An administrator needs to enable repairs for this repository.")
	} else {
		out.AllowWorkflows = policy.AllowWorkflows
		out.PolicyMode = repairMode(policy)
		checks.set("policy", EliCheckOK, repairModeWords(policy)+" is on for this repository. Workflow file edits are "+map[bool]string{true: "on", false: "off"}[policy.AllowWorkflows]+".")
		used, personal, reset, e := c.st.EliRepairBudget(ctx, repo, user)
		if e != nil {
			block("budget", "budget_unavailable", "Repair allowance could not be checked. Try again.")
		} else {
			out.Remaining = max(0, min(policy.DailyLimit-used, store.EliPersonDailyLimit-personal))
			out.ResetAt = reset
			if out.Remaining == 0 {
				block("budget", "budget", "The repair allowance is exhausted. Wait until an attempt leaves the 24-hour window.")
			} else {
				checks.set("budget", EliCheckOK, plural(out.Remaining, "attempt")+" left in the 24-hour window.")
			}
		}
	}
	checked := c.st.Now()
	var pr github.RepairPull
	if run > 0 {
		pr, err = client.RepairPullForRun(ctx, repo, run)
	} else if pull > 0 {
		pr, err = client.RepairPull(ctx, repo, pull)
	} else {
		block("pull", "pull", "Choose an open pull request or paste its GitHub URL.")
		return out
	}
	out.PullNumber = pr.Number
	out.HeadSHA = pr.HeadSHA
	if pr.Number > 0 {
		out.Pull = &EliReadinessPull{Number: pr.Number, Title: pr.Title, Author: pr.Author, Branch: pr.Branch, Base: pr.Base, URL: pr.URL, Open: pr.Open}
	}
	if err != nil {
		var changed *github.RepairTargetChanged
		if errors.As(err, &changed) {
			// A changed target is the answer to the person's original question,
			// even when their provider or repository setup is also incomplete.
			out.Blockers = []EliBlocker{{Code: changed.Code, Message: changed.Message}}
			checks.block("pull", changed.Code, changed.Message)
			if run > 0 {
				_ = c.st.RecordJobAttentionRun(ctx, repo, run, changed.Code, checked, true)
			}
		} else if errors.Is(err, github.ErrRepairUnsupported) {
			message := strings.TrimPrefix(err.Error(), github.ErrRepairUnsupported.Error()+": ")
			if message == github.ErrRepairUnsupported.Error() {
				message = "Choose an open PR in this repository at its current head; forks cannot be repaired."
			}
			block("pull", "pull", message)
		} else {
			block("pull", "github", "GitHub could not resolve this repair target. Try checking readiness again.")
		}
		return out
	}
	checks.set("pull", EliCheckOK, fmt.Sprintf("#%d is open on %s and still at %s.", pr.Number, pr.Branch, shortSHA(pr.HeadSHA)))
	state, err := client.RepairChecks(ctx, repo, pr.HeadSHA)
	if err != nil {
		block("checks", "github", "GitHub could not check whether this failure still needs fixing. Try checking readiness again.")
		return out
	}
	if state == "passed" {
		if run > 0 {
			_ = c.st.RecordJobAttentionRun(ctx, repo, run, "fixed", checked, true)
		}
		out.Blockers = []EliBlocker{{Code: "fixed", Message: "The latest checks on this PR have passed. This failure has already been fixed; no repair is needed."}}
		checks.block("checks", out.Blockers[0].Code, out.Blockers[0].Message)
		return out
	}
	if run > 0 {
		_ = c.st.RecordJobAttentionRun(ctx, repo, run, "", checked, state == "failed")
	}
	if state != "failed" {
		block("checks", "checks_pending", "No current failed check is available to repair. Checks may still be running, cancelled or skipped. Check the PR on GitHub, then check readiness again.")
	} else {
		checks.set("checks", EliCheckOK, "The checks on "+shortSHA(pr.HeadSHA)+" are failing.")
	}
	info, err := raw.Probe(ctx)
	if err != nil {
		block("permissions", "permissions", "GitHub App permissions could not be checked.")
	} else {
		var missing []string
		for _, permission := range []string{"contents", "pull_requests", "actions"} {
			value := info.Permissions[permission]
			if value != "write" && (permission != "actions" || value != "read") {
				message := "Update the GitHub App permission: " + permission + map[bool]string{true: " read", false: " write"}[permission == "actions"]
				out.Blockers = append(out.Blockers, EliBlocker{"permissions", message})
				missing = append(missing, message)
			}
		}
		if len(missing) > 0 {
			checks.block("permissions", "permissions", strings.Join(missing, " "))
		} else {
			checks.set("permissions", EliCheckOK, "Contents, pull requests and actions are granted.")
		}
	}
	out.Ready = len(out.Blockers) == 0
	return out
}

// Offers contain repository data, so even administrators must have current
// access through their linked GitHub account before seeing personal offers.
func (c *Controller) EliOpportunities(ctx context.Context, user string) ([]store.EliRepairOpportunity, error) {
	out := []store.EliRepairOpportunity{}
	id, err := c.eliIdentity(ctx, user)
	if errors.Is(err, store.ErrNotFound) {
		return out, nil
	}
	if err != nil {
		return nil, err
	}
	rows, err := c.st.EliRepairOpportunities(ctx, user)
	if err != nil {
		return nil, err
	}
	access := map[string]bool{}
	for _, o := range rows {
		key := o.InstallationID + ":" + o.Repo
		allowed, seen := access[key]
		if !seen {
			raw, err := c.ClientFor(ctx, o.InstallationID)
			if err == nil {
				if client, ok := raw.(github.RepairClient); ok {
					actor, e := client.RepairActor(ctx, o.Repo, id.GitHubLogin)
					allowed = e == nil && actor.ID == id.GitHubUserID && actor.CanWrite
				}
			}
			access[key] = allowed
		}
		if allowed {
			out = append(out, o)
		}
	}
	return out, nil
}
func (c *Controller) ActEliOpportunity(ctx context.Context, user, id, action string, admin bool) (*store.EliRepair, error) {
	rows, err := c.EliOpportunities(ctx, user)
	if err != nil {
		return nil, err
	}
	for _, o := range rows {
		if o.ID == id {
			if action == "dismiss" {
				return nil, c.st.DismissEliOpportunity(ctx, id, user)
			}
			if action != "accept" {
				return nil, store.ErrConflict
			}
			row, err := c.requestPinnedEliRepair(ctx, user, o.Repo, o.PullNumber, "", o.HeadSHA, "offer:"+o.ID, o.RunID, admin)
			if err != nil {
				return nil, err
			}
			if err = c.st.SetEliOpportunityState(ctx, id, "accepted"); err != nil {
				return nil, err
			}
			return row, nil
		}
	}
	return nil, store.ErrNotFound
}

// A bounded reconciliation catches jobs learnt through polling and failures
// that existed before setup. It runs independently of opening the UI.
func (c *Controller) reconcileEliOpportunities(parent context.Context) {
	ctx, cancel := context.WithTimeout(parent, 30*time.Second)
	defer cancel()
	policies, err := c.st.EliRepairPolicies(ctx)
	if err != nil {
		return
	}
	repos := []string{}
	byRepo := map[string]store.EliRepairPolicy{}
	for _, p := range policies {
		if p.Enabled && p.AskFirst {
			repos = append(repos, p.Repo)
			byRepo[p.Repo] = p
		}
	}
	if len(repos) == 0 {
		return
	}
	since := c.st.Now().Add(-24 * time.Hour)
	jobs, _, err := c.st.ListJobs(ctx, store.JobFilter{Repos: repos, Conclusions: []string{"failure", "timed_out"}, Since: &since}, store.Page{Limit: 50, Sort: "queued_at", Desc: true})
	if err != nil {
		return
	}
	seen := map[string]bool{}
	for _, j := range jobs {
		key := fmt.Sprintf("%s:%d", j.Repo, j.GitHubRunID)
		if seen[key] || j.GitHubRunID == 0 || j.FaultKind != "" {
			continue
		}
		seen[key] = true
		p := byRepo[j.Repo]
		raw, err := c.ClientFor(ctx, p.InstallationID)
		if err != nil {
			continue
		}
		client, ok := raw.(github.RepairClient)
		if !ok {
			continue
		}
		pr, err := client.RepairPullForRun(ctx, j.Repo, j.GitHubRunID)
		if err != nil {
			continue
		}
		own, e := c.st.IsEliRepairCommit(ctx, j.Repo, pr.HeadSHA)
		if e != nil || own {
			continue
		}
		state, e := client.RepairChecks(ctx, j.Repo, pr.HeadSHA)
		if e != nil || state == "passed" {
			continue
		}
		_ = c.st.OfferEliRepair(ctx, store.EliRepairOpportunity{Repo: j.Repo, InstallationID: p.InstallationID, PullNumber: pr.Number, HeadSHA: pr.HeadSHA, RunID: j.GitHubRunID, Title: pr.Title})
	}
	// Dismissals remain tied to their original head, never to a future commit.
	rows, _ := c.st.EliRepairOpportunities(ctx, "")
	for _, o := range rows {
		raw, e := c.ClientFor(ctx, o.InstallationID)
		if e != nil {
			continue
		}
		client, ok := raw.(github.RepairClient)
		if !ok {
			continue
		}
		pr, e := client.RepairPull(ctx, o.Repo, o.PullNumber)
		if errors.Is(e, github.ErrRepairUnsupported) || e == nil && pr.HeadSHA != o.HeadSHA {
			_ = c.st.SetEliOpportunityState(ctx, o.ID, "superseded")
			continue
		}
		if e == nil {
			state, e := client.RepairChecks(ctx, o.Repo, o.HeadSHA)
			if e == nil && state == "passed" {
				_ = c.st.SetEliOpportunityState(ctx, o.ID, "superseded")
			}
		}
	}
}

