)

// A heartbeat for a host this controller has never seen must carry
// agent.ErrHostGone. The HTTP transport derives that sentinel from a 404, but
// the embedded agent has no status code to derive it from, so if the controller
// does not wrap it the in-process agent retries a host that will never exist
// again instead of stopping and telling the operator to re-join.
func TestHeartbeatForUnknownHostIsErrHostGone(t *testing.T) {
	h := newHarness(t)

	_, err := h.c.Heartbeat(context.Background(), "host_doesnotexist", agent.HeartbeatRequest{
		ProtocolVersion: agent.ProtocolVersion,
		Capacity:        1,
	})
	if err == nil {
		t.Fatal("heartbeat for an unknown host succeeded; it must fail")
	}
	if !errors.Is(err, agent.ErrHostGone) {
		t.Fatalf("error = %v, want it to wrap agent.ErrHostGone so the embedded agent stops rather than retrying", err)
	}
}

package controller

import (
	"context"
	"errors"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
	"sync"
	"time"
)

// Bounded workers keep optional remote lookups out of webhook and heartbeat
// acknowledgements. Durable leases also cover controller restarts and 429s.
func (c *Controller) enrichmentLoop(ctx context.Context) {
	tick := time.NewTicker(time.Second)
	defer tick.Stop()
	for {
		c.enrichOnce(ctx)
		select {
		case <-ctx.Done():
			return
		case <-tick.C:
		}
	}
}
func (c *Controller) enrichOnce(ctx context.Context) {
	if !c.mayAct() {
		return
	}
	items, err := c.st.ClaimEnrichment(ctx, 4)
	if err != nil {
		c.log.Warn("could not claim GitHub enrichment", "error", err)
		return
	}
	var wg sync.WaitGroup
	for _, item := range items {
		wg.Add(1)
		go func(v store.Enrichment) {
			defer wg.Done()
			defer c.recoverDetached("enrichment-worker")
			cctx, cancel := context.WithTimeout(ctx, 5*time.Second)
			defer cancel()
			err := c.enrich(cctx, v)
			if err != nil {
				c.log.Debug("GitHub enrichment will retry", "kind", v.Kind, "target", v.Target, "error", err)
			}
			if e := c.st.FinishEnrichment(ctx, v, err == nil); e != nil {
				c.log.Warn("could not acknowledge enrichment", "error", e)
			}
		}(item)
	}
	wg.Wait()
}
func (c *Controller) enrich(ctx context.Context, v store.Enrichment) error {
	if !c.mayAct() {
		return errors.New("controller authority is paused")
	}
	switch v.Kind {
	case "registration":
		r, err := c.st.GetRunner(ctx, v.Target)
		if errors.Is(err, store.ErrNotFound) {
			return nil
		}
		if err != nil {
			return err
		}
		if r.RegistrationDeletedAt != nil {
			return nil
		}
		c.deleteRegistration(ctx, r, nil)
		r, err = c.st.GetRunner(ctx, v.Target)
		if err != nil {
			return err
		}
		if r.RegistrationDeletedAt == nil {
			return errors.New("registration cleanup not yet confirmed")
		}
		return nil
	case "ready":
		r, err := c.st.GetRunner(ctx, v.Target)
		if errors.Is(err, store.ErrNotFound) {
			return nil
		}
		if err != nil {
			return err
		}
		if r.State != store.RunnerRegistering {
			return nil
		}
		if !c.runnerOnline(ctx, r, make(map[string][]github.Runner)) {
			return errors.New("runner not yet confirmed online")
		}
		return c.applyRunnerState(ctx, r, store.RunnerIdle, "GitHub confirmed the runner online", "")
	case "job":
		j, err := c.st.GetJob(ctx, v.Target)
		if errors.Is(err, store.ErrNotFound) {
			return nil
		}
		if err != nil {
			return err
		}
		if j.InstallationID == "" || j.GitHubRunID == 0 {
			return nil
		}
		cancelled := j.State == store.JobCompleted && j.Conclusion == "cancelled"
		if j.RunNumber != 0 && !cancelled {
			return nil
		}
		if c.githubHeld(j.InstallationID, c.Now()) {
			return errors.New("GitHub rate limit hold")
		}
		client, err := c.ClientFor(ctx, j.InstallationID)
		if err != nil {
			return err
		}
		run, err := client.GetWorkflowRun(ctx, j.Repo, j.GitHubRunID)
		c.observeGitHub(j.InstallationID, err)
		if err != nil {
			if errors.Is(err, github.ErrRateLimited) {
				c.holdRateLimited(j.InstallationID, err, c.Now(), "enriching workflow")
			}
			return err
		}
		if run.RunNumber > 0 || run.Event != "" {
			if err := c.st.SetRunNumberForRun(ctx, j.Repo, j.GitHubRunID, run.RunNumber); err != nil {
				return err
			}
			if err := c.st.SetRunEventForRun(ctx, j.Repo, j.GitHubRunID, run.Event); err != nil {
				return err
			}
			j.RunNumber, j.RunEvent = run.RunNumber, run.Event
			c.publishJob(ctx, j)
		}
		if cancelled && run.Cancelled() {
			if !c.mayAct() {
				return errors.New("controller authority is paused")
			}
			return c.cancelWorkflowRunLocally(ctx, j.Repo, j.GitHubRunID, true)
		}
	}
	return nil
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

var ErrExperimentEvidence = errors.New("comparison evidence is incomplete or inconsistent")

const maxExperimentSelectedAttempts = 100
const maxExperimentCollectedJobs = 2000

type ExperimentAttemptSelection struct {
	RunID   int64 `json:"run_id"`
	Attempt int   `json:"attempt"`
}

type ExperimentRetainedJob struct {
	RunnerCreation *store.RunnerCreationObservation `json:"runner_creation,omitempty"`
	RunnerID       string                           `json:"runner_id,omitempty"`
	PoolID         string                           `json:"pool_id,omitempty"`
	HostID         string                           `json:"host_id,omitempty"`
	RecordedGrant  *ExperimentRecordedGrant         `json:"recorded_grant,omitempty"`
	JobID          string                           `json:"job_id"`
	GitHubJobID    int64                            `json:"github_job_id"`
	HeadSHA        string                           `json:"head_sha"`
	State          store.JobState                   `json:"state"`
	Conclusion     string                           `json:"conclusion"`
	QueuedAt       time.Time                        `json:"queued_at"`
	StartedAt      *time.Time                       `json:"started_at"`
	CompletedAt    *time.Time                       `json:"completed_at"`
}

type ExperimentRetainedAttempt struct {
	Selection ExperimentAttemptSelection `json:"selection"`
	// retained_only is never full workflow coverage, even when the query fits.
	Coverage string                  `json:"coverage"`
	Jobs     []ExperimentRetainedJob `json:"jobs"`
}

type ExperimentRetainedEvidence struct {
	Repository        string                      `json:"repository"`
	InstallationID    string                      `json:"installation_id"`
	SelectionComplete bool                        `json:"selection_complete"`
	Attempts          []ExperimentRetainedAttempt `json:"attempts"`
}

// CollectExperimentAttempts is for a caller already authorised to read jobs.
// It checks installation/repository joins, not the caller's role. No transport
// exposes this yet. The report omits names, log tails and workflow output. A
// later adapter must treat the repository and revision strings as untrusted.
func (c *Controller) CollectExperimentAttempts(ctx context.Context, installation, repo string, selected []ExperimentAttemptSelection) (*ExperimentRetainedEvidence, error) {
	if len(selected) < 1 || len(selected) > maxExperimentSelectedAttempts {
		return nil, fmt.Errorf("%w: select 1 to %d attempts", ErrExperimentEvidence, maxExperimentSelectedAttempts)
	}
	seen := map[ExperimentAttemptSelection]bool{}
	for _, s := range selected {
		if s.RunID <= 0 || s.Attempt <= 0 || seen[s] {
			return nil, fmt.Errorf("%w: select each positive run/attempt identity once", ErrExperimentEvidence)
		}
		seen[s] = true
	}
	if installation == "" || repo == "" {
		return nil, ErrExperimentEvidence
	}
	ctx, cancel := context.WithTimeout(ctx, 20*time.Second)
	defer cancel()
	inst, err := c.st.GetInstallation(ctx, installation)
	if err != nil {
		return nil, err
	}
	owner, name, kind := github.SplitTarget(repo)
	if kind != store.TargetRepo || name == "" || !(inst.TargetType == store.TargetRepo && inst.Target == repo || inst.TargetType == store.TargetOrg && inst.Target == owner) {
		return nil, fmt.Errorf("%w: the installation does not cover the selected repository", ErrExperimentEvidence)
	}
	r := &ExperimentRetainedEvidence{Repository: repo, InstallationID: installation, Attempts: make([]ExperimentRetainedAttempt, 0, len(selected))}
	budget := maxExperimentCollectedJobs
	for _, s := range selected {
		a := ExperimentRetainedAttempt{Selection: s, Coverage: "held_back", Jobs: []ExperimentRetainedJob{}}
		if budget > 0 {
			jobs, cut, err := c.st.ListExperimentAttemptJobs(ctx, repo, installation, s.RunID, s.Attempt, min(budget, store.MaxExperimentAttemptJobs))
			if err != nil {
				return nil, err
			}
			for _, j := range jobs {
				grant, err := experimentRecordedGrant(j)
				if err != nil {
					return nil, err
				}
				observation, err := c.experimentRunnerCreation(ctx, installation, j)
				if err != nil {
					return nil, err
				}
				row := ExperimentRetainedJob{RecordedGrant: grant, JobID: j.ID, GitHubJobID: j.GitHubJobID, HeadSHA: j.HeadSHA, State: j.State, Conclusion: j.Conclusion, QueuedAt: j.QueuedAt, StartedAt: j.StartedAt, CompletedAt: j.CompletedAt}
				if observation != nil {
					row.RunnerCreation, row.RunnerID, row.PoolID, row.HostID = observation, j.RunnerID, j.PoolID, j.HostID
				}
				a.Jobs = append(a.Jobs, row)
			}
			budget -= len(jobs)
			switch {
			case cut:
				a.Coverage = "truncated"
			case len(jobs) == 0:
				a.Coverage = "not_available"
			default:
				a.Coverage = "retained_only"
			}
		}
		r.Attempts = append(r.Attempts, a)
	}
	// Retention, non-fleet jobs and missing deliveries can each hide attempts.
	// An uncapped SQL result proves none of those absent records did not exist.
	return r, nil
}

package controller

import (
	"encoding/json"
	"errors"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

func TestExperimentCollectionPreservesFailuresAndCannotAssertFullCoverage(t *testing.T) {
	h := newHarness(t)
	inst := h.installationOn("acme/repo", store.TargetRepo)
	// Each job is queued a second after the one before: the store keeps
	// milliseconds and lists by queued time then id, so jobs queued together
	// come back in the order of their random ids and the failure is first
	// only some of the time.
	queued := time.Now()
	for i, outcome := range []string{"failure", "success", "cancelled"} {
		_, err := h.st.UpsertJob(h.ctx, &store.Job{GitHubJobID: int64(100 + i), GitHubRunID: 10, RunAttempt: 1, InstallationID: inst.ID, Repo: inst.Target, QueuedAt: queued.Add(time.Duration(i) * time.Second), State: store.JobCompleted, Conclusion: outcome, JobName: "private workflow text"})
		if err != nil {
			t.Fatal(err)
		}
	}
	r, err := h.c.CollectExperimentAttempts(h.ctx, inst.ID, inst.Target, []ExperimentAttemptSelection{{RunID: 10, Attempt: 1}, {RunID: 10, Attempt: 2}})
	if err != nil || r.SelectionComplete || len(r.Attempts) != 2 || len(r.Attempts[0].Jobs) != 3 || len(r.Attempts[1].Jobs) != 0 || r.Attempts[1].Coverage != "not_available" {
		t.Fatalf("got %+v, %v", r, err)
	}
	payload, err := json.Marshal(r)
	if err != nil || strings.Contains(string(payload), "private workflow text") {
		t.Fatalf("workflow text leaked: %s, %v", payload, err)
	}
	if r.Attempts[0].Coverage != "retained_only" || r.Attempts[0].Jobs[0].Conclusion != "failure" {
		t.Fatalf("got %+v", r)
	}
}

