func experimentCreationFixture(t *testing.T, clock func() time.Time) (*harness, *store.Installation, *store.Job, *store.RunnerCreationObservation) {
	t.Helper()
	h := newHarnessAt(t, clock)
	inst, pool, host := h.fleet()
