// problem returns the one problem with a code, failing the test when the list
// does not carry it. Tests that assert on an entry's words need the entry, not
// only that its code is present.
func (h *harness) problem(t *testing.T, code string) Problem {
	t.Helper()
	ps, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	for _, p := range ps {
		if p.Code == code {
			return p
		}
	}
	t.Fatalf("no %s problem in %v", code, h.problemCodes())
	return Problem{}
}

// The controller's GitHub API client is already fake. Its independent public
// release checker uses this client, so intercept the three URLs it asks about
// as well. The list is only asked for when updates.mode is not off, which is a
// test's own doing; it gets an empty one, so that turning the mode on does not
// send a housekeeping pass to the real api.github.com.
type harnessTransport struct{}

func (harnessTransport) RoundTrip(r *http.Request) (*http.Response, error) {
	switch r.URL.String() {
	case latestReleaseURL, mainCommitURL:
		return jsonResponse(http.StatusNotFound, `{}`), nil
	case releaseListURL:
		return jsonResponse(http.StatusOK, `[]`), nil
	}
	return http.DefaultTransport.RoundTrip(r)
}

package controller

import (
	"encoding/json"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/hosttune"
	"github.com/eyupio/zoomies/internal/store"
)

// accept stores an operator's acceptance of a check as the operation does,
// without the operation, so these tests are about judging and not about the
// door the acceptance came in by.
func (h *harness) accept(t *testing.T, host *store.Host, checkID, current string, ends time.Time) {
	t.Helper()
	a := &store.HostCheckAcceptance{HostID: host.ID, CheckID: checkID, Current: current,
		Reason: "pinned on purpose", By: "usr_1", ByName: "Sam", ExpiresAt: ends}
	if err := h.st.UpsertHostCheckAcceptance(h.ctx, a); err != nil {
		t.Fatalf("UpsertHostCheckAcceptance: %v", err)
	}
}

// The failure this is designed out is two surfaces disagreeing: a page that
// calls a warning accepted while the problems list, the metrics or the CLI
// still count it. All of them read the judged report, so one acceptance has to
// move every one of them together.
func TestAnAcceptedWarningLeavesTheProblemTheMetricsAndTheViewTogether(t *testing.T) {
	h := newHarness(t)
	host := h.host("accepting")
	h.reports(t, host, report(h.c.Now(), check("docker.logs", hosttune.Safe, hosttune.Warn, false)))
	if got := h.problemsOf(t, "host.os_health"); len(got) != 1 {
		t.Fatalf("before the acceptance there are %d host.os_health problems, want 1", len(got))
	}

	h.accept(t, host, "docker.logs", "AGENT CURRENT docker.logs", h.c.Now().Add(24*time.Hour))

	if got := h.problemsOf(t, "host.os_health"); len(got) != 0 {
		t.Errorf("an accepted warning still raises host.os_health: %+v", got)
	}
	for state, want := range map[string]float64{"warning": 0, "accepted": 1, "error": 0} {
		got, ok := gatherValue(t, h.c, "zoomies_host_os_checks", map[string]string{"host": host.ID, "state": state})
		if !ok || got != want {
			t.Errorf("zoomies_host_os_checks{state=%q} = %v (present=%v), want %v", state, got, ok, want)
		}
	}
	got, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	v := h.c.HostView(got).Doctor
	if v == nil || v.Summary.Accepted != 1 || v.Summary.Warnings != 0 || v.Summary.Counted != 1 {
		t.Fatalf("the view counts %+v, want one counted check, accepted and not a warning", v)
	}
	if r := v.Results[0]; r.Accepted == nil || r.Accepted.By != "Sam" || r.Accepted.Reason != "pinned on purpose" {
		t.Errorf("the view's result carries no acceptance: %+v", r)
	}
	// The stored report is the agent's and stays what it sent.
	if got.Doctor.Results[0].Accepted != nil {
		t.Error("judging wrote the acceptance into the stored report")
	}
}

// Accepting a warning must not hide a different one. The problem is raised for
// what is still unaccepted, and its words name only that.
func TestAnAcceptedWarningDoesNotHideAnotherOnTheSameHost(t *testing.T) {
	h := newHarness(t)
	host := h.host("two-findings")
	h.reports(t, host, report(h.c.Now(),
		check("docker.logs", hosttune.Safe, hosttune.Warn, false),
		check("inotify.watches", hosttune.Safe, hosttune.Warn, false)))
	h.accept(t, host, "docker.logs", "AGENT CURRENT docker.logs", h.c.Now().Add(time.Hour))

	ps := h.problemsOf(t, "host.os_health")
	if len(ps) != 1 || ps[0].Title != "host two-findings has an OS health check that needs attention" {
		t.Fatalf("problems = %+v, want one for the single unaccepted warning", ps)
	}
}

// An acceptance ends when the value moves or the date passes. Either way the
// check counts again straight away, without anyone revoking anything, which is
// what makes an acceptance safe to grant.
func TestAnAcceptanceThatNoLongerHoldsCountsAgain(t *testing.T) {
	h := newHarness(t)
	host := h.host("lapsing")
	h.reports(t, host, report(h.c.Now(), check("docker.logs", hosttune.Safe, hosttune.Warn, false)))
	h.accept(t, host, "docker.logs", "it read something else", h.c.Now().Add(24*time.Hour))
	if got := h.problemsOf(t, "host.os_health"); len(got) != 1 {
		t.Errorf("a value that changed since the acceptance left %d problems, want 1", len(got))
	}

	h.accept(t, host, "docker.logs", "AGENT CURRENT docker.logs", h.c.Now().Add(2*time.Second))
	if got := h.problemsOf(t, "host.os_health"); len(got) != 0 {
		t.Fatalf("a live acceptance left %d problems, want 0", len(got))
	}
	// Short enough that the host is still connected when the term is up.
	h.advance(5 * time.Second)
	if got := h.problemsOf(t, "host.os_health"); len(got) != 1 {
		t.Errorf("an expired acceptance left %d problems, want 1", len(got))
	}
}

// The reboot is a fact about the machine and not a setting someone can
// decide to live with. Even a stored acceptance for it (which the operation
// refuses to make) must leave the problem, the metric and the flag alone.
func TestARebootIsNeverSilencedByAnAcceptance(t *testing.T) {
	h := newHarness(t)
	host := h.host("rebooting")
	r := report(h.c.Now(), check(hosttune.KernelPending, hosttune.Safe, hosttune.Warn, false))
	r.RebootPending = true
	h.reports(t, host, r)
	h.accept(t, host, hosttune.KernelPending, "AGENT CURRENT "+hosttune.KernelPending, h.c.Now().Add(24*time.Hour))

	if got := h.problemsOf(t, "host.reboot_pending"); len(got) != 1 {
		t.Errorf("host.reboot_pending problems = %d, want 1", len(got))
	}
	if got, ok := gatherValue(t, h.c, "zoomies_host_reboot_pending", map[string]string{"host": host.ID}); !ok || got != 1 {
		t.Errorf("zoomies_host_reboot_pending = %v (present=%v), want 1", got, ok)
	}
	if got, ok := gatherValue(t, h.c, "zoomies_host_os_checks", map[string]string{"host": host.ID, "state": "accepted"}); !ok || got != 0 {
		t.Errorf("accepted = %v (present=%v), want 0", got, ok)
	}
}

// A heartbeat replaces the stored report and publishes the host straight from
// memory. If that in-memory host lacked its acceptances the frame would
// un-accept every row on the page for a beat, and the next beat would put it
// back, so the table would flicker at the heartbeat rate.
func TestAHeartbeatFrameKeepsAnAcceptedRowAccepted(t *testing.T) {
	h := newHarness(t)
	host := h.host("beating")
	h.reports(t, host, report(h.c.Now().Add(-time.Minute), check("docker.logs", hosttune.Safe, hosttune.Warn, false)))
	h.accept(t, host, "docker.logs", "AGENT CURRENT docker.logs", h.c.Now().Add(24*time.Hour))

	sub := h.c.Events().Subscribe(h.ctx, events.SubscribeOptions{Kinds: []events.Kind{events.KindHostUpdated}})
	defer sub.Close()
	// A report that only moved its own time is not published at all, so this one
	// also carries a new finding to have a frame to inspect.
	next := report(h.c.Now(), check("docker.logs", hosttune.Safe, hosttune.Warn, false), check("files.watches", hosttune.Safe, hosttune.OK, false))
	if _, err := h.c.Heartbeat(h.ctx, host.ID, agent.HeartbeatRequest{ProtocolVersion: agent.ProtocolVersion, Doctor: next}); err != nil {
		t.Fatal(err)
	}
	select {
	case e := <-sub.C:
		var live HostView
		if err := json.Unmarshal(e.Data, &live); err != nil {
			t.Fatal(err)
		}
		if live.Doctor == nil || live.Doctor.Summary.Accepted != 1 || live.Doctor.Summary.Warnings != 0 || live.Doctor.Results[0].Accepted == nil {
			t.Errorf("the heartbeat frame un-accepted the row: %+v", live.Doctor)
		}
	case <-time.After(time.Second):
		t.Fatal("no host.updated frame after the heartbeat")
	}
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"unicode/utf8"

	"time"

	"github.com/eyupio/zoomies/internal/hosttune"
	"github.com/eyupio/zoomies/internal/store"
)

const (
	// Bounds on an acceptance's reason, in characters, are the Kennel waiver's:
	// ten is a sentence's worth, so "ok" is not a reason, and five hundred is a
	// paragraph, which is what an audit row should carry and a row can render.
	HostAcceptMinReason = KennelMinReason
	HostAcceptMaxReason = KennelMaxReason
)

// HostCheckChangedError is an acceptance asked for a value the check no longer
// has. The operator decided about what they saw, and an agent has reported since:
// accepting what they did not see would be a decision about nothing.
type HostCheckChangedError struct{ Now string }

func (e *HostCheckChangedError) Error() string {
	return fmt.Sprintf("That check changed while you were deciding. It now reads %q. Review it and accept again.", e.Now)
}

// HostAcceptInvalidError is a request to accept that is wrong in a way the
// person can fix, each in the words of the field it belongs to.
type HostAcceptInvalidError struct{ Fields []KennelFieldError }

func (e *HostAcceptInvalidError) Error() string {
	if len(e.Fields) == 0 {
		return "that is not a valid request"
	}
	return e.Fields[0].Field + " " + e.Fields[0].Message
}

// ErrHostAcceptLimit is a host that already holds as many acceptances as it may.
var ErrHostAcceptLimit = errors.New("this host already has as many accepted checks as it may; revoke one that is no longer needed first")

// HostActor is who is making a decision about a host: the name is kept with the
// acceptance, so it still reads right after the person's account is gone.
type HostActor struct{ ID, Name string }

// AcceptInput is a request to accept one host's check as deliberate.
type AcceptInput struct {
	CheckID string
	// SeenCurrent is what the person read when they decided. The acceptance is
	// recorded against the stored report's text, never this, and only when the
	// two agree.
	SeenCurrent string
	Reason      string
	ExpiresAt   time.Time
}

// checkHostAcceptInput is everything wrong with a request that can be said
// without looking at the host, all of it at once so a form does not send a
// person round it three times.
func checkHostAcceptInput(in AcceptInput, now time.Time) []KennelFieldError {
	var bad []KennelFieldError
	if in.CheckID == "" {
		bad = append(bad, KennelFieldError{"check_id", "is required"})
	}
	if n := utf8.RuneCountInString(in.Reason); n < HostAcceptMinReason || n > HostAcceptMaxReason {
		bad = append(bad, KennelFieldError{"reason", fmt.Sprintf("must be %d to %d characters: say why this is deliberate, for whoever reads it on this host's page", HostAcceptMinReason, HostAcceptMaxReason)})
	} else if badReasonCharacter(in.Reason) {
		bad = append(bad, KennelFieldError{"reason", "may not contain control or direction-changing characters"})
	}
	switch {
	case in.ExpiresAt.IsZero():
		bad = append(bad, KennelFieldError{"expires_at", "is required: an acceptance that never ends is a decision nobody is asked to make again"})
	case !in.ExpiresAt.After(now):
		bad = append(bad, KennelFieldError{"expires_at", "must be in the future"})
	case in.ExpiresAt.After(now.Add(hosttune.MaxAcceptance)):
		bad = append(bad, KennelFieldError{"expires_at", "is more than 365 days away; decide again before then"})
	}
	return bad
}

// AcceptHostCheck records that a counted warning on one host is deliberate. It
// changes nothing on the host -- the controller never runs a command there -- it
// only stops Zoomies counting the check until the value changes or the term ends.
//
// The value stored is the stored report's, not the request's, so an acceptance
// cannot be made to cover text the host never reported.
func (c *Controller) AcceptHostCheck(ctx context.Context, hostID string, in AcceptInput, by HostActor) (HostView, *store.HostCheckAcceptance, error) {
	if bad := checkHostAcceptInput(in, c.Now()); len(bad) > 0 {
		return HostView{}, nil, &HostAcceptInvalidError{Fields: bad}
	}
	h, err := c.st.GetHost(ctx, hostID)
	if err != nil {
		return HostView{}, nil, err
	}
	rep := h.Doctor.Report
	if rep == nil {
		return HostView{}, nil, &HostAcceptInvalidError{Fields: []KennelFieldError{{"check_id", "cannot be accepted yet: this host has not sent a health report"}}}
	}
	if rep.Container {
		return HostView{}, nil, &HostAcceptInvalidError{Fields: []KennelFieldError{{"check_id", "cannot be accepted here: a container agent's report is partial, so there is nothing here to accept"}}}
	}
	var stored *hosttune.Result
	for i := range rep.Results {
		if rep.Results[i].ID == in.CheckID {
			stored = &rep.Results[i]
		}
	}
	if ok, why := hosttune.Acceptable(in.CheckID); !ok {
		return HostView{}, nil, &HostAcceptInvalidError{Fields: []KennelFieldError{{"check_id", why}}}
	}
	if stored == nil {
		return HostView{}, nil, &HostAcceptInvalidError{Fields: []KennelFieldError{{"check_id", "That check is not a warning on this host right now."}}}
	}
	if why := hosttune.AcceptRefusal(*stored); why != "" {
		return HostView{}, nil, &HostAcceptInvalidError{Fields: []KennelFieldError{{"check_id", why}}}
	}
	if stored.Current != in.SeenCurrent {
		return HostView{}, nil, &HostCheckChangedError{Now: stored.Current}
	}
	a := &store.HostCheckAcceptance{
		HostID: h.ID, CheckID: in.CheckID, Current: stored.Current, Reason: in.Reason,
		By: by.ID, ByName: by.Name, ExpiresAt: in.ExpiresAt.UTC(),
	}
	if err := c.st.UpsertHostCheckAcceptance(ctx, a); err != nil {
		if errors.Is(err, store.ErrTooManyHostAcceptances) {
			return HostView{}, nil, ErrHostAcceptLimit
		}
		return HostView{}, nil, err
	}
	v, err := c.hostAfterAcceptance(ctx, h.ID)
	return v, a, err
}

// RevokeHostCheck ends an acceptance and returns the one it ended, which is what
// the audit row records as what was. Revoking one that is not there is not an
// error: two operators pressing the button agree on the outcome, and the second
// is told the host as it stands. The returned acceptance is nil then.
func (c *Controller) RevokeHostCheck(ctx context.Context, hostID, checkID string) (HostView, *store.HostCheckAcceptance, error) {
	h, err := c.st.GetHost(ctx, hostID)
	if err != nil {
		return HostView{}, nil, err
	}
	var ended *store.HostCheckAcceptance
	for i := range h.Acceptances {
		if h.Acceptances[i].CheckID == checkID {
			ended = &h.Acceptances[i]
		}
	}
	if err := c.st.DeleteHostCheckAcceptance(ctx, hostID, checkID); err != nil {
		if !errors.Is(err, store.ErrNotFound) {
			return HostView{}, nil, err
		}
		ended = nil
	}
	v, err := c.hostAfterAcceptance(ctx, hostID)
	return v, ended, err
}

// hostAfterAcceptance re-reads the host so the frame and the answer carry the
// acceptances as they now stand, and announces it: every open page repaints from
// the same payload the person who decided gets.
func (c *Controller) hostAfterAcceptance(ctx context.Context, hostID string) (HostView, error) {
	h, err := c.st.GetHost(ctx, hostID)
	if err != nil {
		return HostView{}, err
	}
	c.publishHost(h)
	return c.HostView(h), nil
}

package controller

import (
	"errors"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/hosttune"
	"github.com/eyupio/zoomies/internal/store"
)

var sam = HostActor{ID: "usr_1", Name: "Sam"}

const goodReason = "pinned below the baseline on purpose"

func (h *harness) acceptIn(check, seen string) AcceptInput {
	return AcceptInput{CheckID: check, SeenCurrent: seen, Reason: goodReason, ExpiresAt: h.c.Now().Add(30 * 24 * time.Hour)}
}

func acceptFieldsOf(t *testing.T, err error) map[string]string {
	t.Helper()
	var bad *HostAcceptInvalidError
	if !errors.As(err, &bad) {
		t.Fatalf("error = %v, want a HostAcceptInvalidError", err)
	}
	m := map[string]string{}
	for _, f := range bad.Fields {
		m[f.Field] = f.Message
	}
	return m
}

// The value that is stored is the report's, because an acceptance that could be
// made to cover text the host never reported would be a way to pre-accept a
// future warning.
func TestAcceptingACheckStoresTheReportsValueAndPublishesTheHost(t *testing.T) {
	h := newHarness(t)
	host := h.host("accepting-op")
	h.reports(t, host, report(h.c.Now(), check("docker.logs", hosttune.Safe, hosttune.Warn, false)))

	v, a, err := h.c.AcceptHostCheck(h.ctx, host.ID, h.acceptIn("docker.logs", "AGENT CURRENT docker.logs"), sam)
	if err != nil {
		t.Fatalf("AcceptHostCheck: %v", err)
	}
	if a.Current != "AGENT CURRENT docker.logs" || a.ByName != "Sam" || a.Reason != goodReason {
		t.Errorf("stored %+v", a)
	}
	if v.Doctor == nil || v.Doctor.Summary.Accepted != 1 || v.Doctor.Summary.Warnings != 0 {
		t.Errorf("the answer counts %+v, want one accepted and no warning", v.Doctor)
	}
	if got := h.problemsOf(t, "host.os_health"); len(got) != 0 {
		t.Errorf("an accepted warning raises %+v", got)
	}
}

// Everything wrong that can be said without the host is said at once, so a form
// does not send a person round it three times.
func TestAcceptingReportsEveryFieldErrorAtOnce(t *testing.T) {
	h := newHarness(t)
	host := h.host("accept-fields")
	h.reports(t, host, report(h.c.Now(), check("docker.logs", hosttune.Safe, hosttune.Warn, false)))
	now := h.c.Now()

	cases := []struct {
		name  string
		edit  func(*AcceptInput)
		field string
	}{
		{"a reason of nine characters", func(in *AcceptInput) { in.Reason = "123456789" }, "reason"},
		{"a reason of 501 characters", func(in *AcceptInput) { in.Reason = strings.Repeat("a", 501) }, "reason"},
		{"a reason with a direction override", func(in *AcceptInput) { in.Reason = goodReason + "\u202e" }, "reason"},
		{"no end", func(in *AcceptInput) { in.ExpiresAt = time.Time{} }, "expires_at"},
		{"an end in the past", func(in *AcceptInput) { in.ExpiresAt = now.Add(-time.Hour) }, "expires_at"},
		{"an end past 365 days", func(in *AcceptInput) { in.ExpiresAt = now.Add(hosttune.MaxAcceptance + time.Hour) }, "expires_at"},
		{"no check", func(in *AcceptInput) { in.CheckID = "" }, "check_id"},
	}
	for _, tc := range cases {
		in := h.acceptIn("docker.logs", "AGENT CURRENT docker.logs")
		tc.edit(&in)
		_, _, err := h.c.AcceptHostCheck(h.ctx, host.ID, in, sam)
		if _, ok := acceptFieldsOf(t, err)[tc.field]; !ok {
			t.Errorf("%s: no error on %s: %v", tc.name, tc.field, err)
		}
	}

	in := h.acceptIn("docker.logs", "x")
	in.Reason, in.ExpiresAt = "short", time.Time{}
	_, _, err := h.c.AcceptHostCheck(h.ctx, host.ID, in, sam)
	if got := acceptFieldsOf(t, err); len(got) != 2 {
		t.Errorf("fields = %v, want reason and expires_at together", got)
	}

	// Exactly 365 days is the last instant that is allowed.
	in = h.acceptIn("docker.logs", "AGENT CURRENT docker.logs")
	in.ExpiresAt = now.Add(hosttune.MaxAcceptance)
	if _, _, err := h.c.AcceptHostCheck(h.ctx, host.ID, in, sam); err != nil {
		t.Errorf("an end exactly 365 days away is refused: %v", err)
	}
}

// Only a counted Warn on a catalogue check may be accepted. Each refusal names
// what the person can do instead, and none of them writes a row.
func TestOnlyACountedWarnOnACatalogueCheckCanBeAccepted(t *testing.T) {
	h := newHarness(t)
	host := h.host("accept-refusals")
	h.reports(t, host, report(h.c.Now(),
		check("docker.logs", hosttune.Safe, hosttune.Error, false),
		check("files.service", hosttune.Safe, hosttune.Skip, false),
		check("cgroup.version", hosttune.Safe, hosttune.OK, false),
		check("disk.space", hosttune.Safe, hosttune.Warn, false),
		check("disk.inodes", hosttune.Safe, hosttune.Warn, false),
		check(hosttune.KernelPending, hosttune.Safe, hosttune.Warn, false),
		check("vm.swappiness", hosttune.Safe, hosttune.Warn, false),
		check("tmp.tmpfs", hosttune.Aggressive, hosttune.Warn, false),
	))
	for _, tc := range []struct{ id, want string }{
		{"docker.logs", "could not run"},
		{"files.service", "not a warning"},
		{"cgroup.version", "not a warning"},
		{"disk.space", "Free space moves"},
		{"disk.inodes", "Free space moves"},
		{hosttune.KernelPending, "pending reboot"},
		{"vm.swappiness", "does not know a check"},
		{"tmp.tmpfs", "suggestion"},
		{"never.reported", "does not know a check"},
	} {
		_, _, err := h.c.AcceptHostCheck(h.ctx, host.ID, h.acceptIn(tc.id, "AGENT CURRENT "+tc.id), sam)
		if msg := acceptFieldsOf(t, err)["check_id"]; !strings.Contains(msg, tc.want) {
			t.Errorf("%s: %q does not say %q", tc.id, msg, tc.want)
		}
	}
	got, _ := h.st.GetHost(h.ctx, host.ID)
	if len(got.Acceptances) != 0 {
		t.Errorf("a refused request left %+v", got.Acceptances)
	}
}

// A catalogue check the host has not reported at all is refused too: there is
// no value to hold the acceptance to.
func TestAcceptingACheckTheHostDidNotReportIsRefused(t *testing.T) {
	h := newHarness(t)
	host := h.host("accept-absent")
	h.reports(t, host, report(h.c.Now(), check("cgroup.version", hosttune.Safe, hosttune.Warn, false)))
	_, _, err := h.c.AcceptHostCheck(h.ctx, host.ID, h.acceptIn("docker.logs", "x"), sam)
	if !strings.Contains(acceptFieldsOf(t, err)["check_id"], "not a warning") {
		t.Errorf("error = %v", err)
	}
}

func TestAHostWithoutAFullReportHasNothingToAccept(t *testing.T) {
	h := newHarness(t)
	none := h.host("accept-no-report")
	_, _, err := h.c.AcceptHostCheck(h.ctx, none.ID, h.acceptIn("docker.logs", "x"), sam)
	if _, ok := acceptFieldsOf(t, err)["check_id"]; !ok {
		t.Errorf("no report: %v", err)
	}
	box := h.host("accept-container")
	r := report(h.c.Now(), check("docker.logs", hosttune.Safe, hosttune.Warn, false))
	r.Container = true
	h.reports(t, box, r)
	_, _, err = h.c.AcceptHostCheck(h.ctx, box.ID, h.acceptIn("docker.logs", "AGENT CURRENT docker.logs"), sam)
	if !strings.Contains(acceptFieldsOf(t, err)["check_id"], "partial") {
		t.Errorf("container: %v", err)
	}
	if _, _, err := h.c.AcceptHostCheck(h.ctx, "host_missing", h.acceptIn("docker.logs", "x"), sam); !errors.Is(err, store.ErrNotFound) {
		t.Errorf("unknown host: %v, want not found", err)
	}
}

// The person decided about what they read. If an agent has reported since, the
// acceptance would be about a value they did not see.
func TestAcceptingAValueThatChangedWhileDecidingIsRefusedWithTheNewValue(t *testing.T) {
	h := newHarness(t)
	host := h.host("accept-stale")
	h.reports(t, host, report(h.c.Now(), check("docker.logs", hosttune.Safe, hosttune.Warn, false)))
	_, _, err := h.c.AcceptHostCheck(h.ctx, host.ID, h.acceptIn("docker.logs", "something older"), sam)
	var changed *HostCheckChangedError
	if !errors.As(err, &changed) || changed.Now != "AGENT CURRENT docker.logs" {
		t.Fatalf("error = %v, want a HostCheckChangedError naming the current value", err)
	}
}

// Deciding again renews: one row, the new reason and end.
func TestAcceptingTwiceReplacesTheFirstDecision(t *testing.T) {
	h := newHarness(t)
	host := h.host("accept-twice")
	h.reports(t, host, report(h.c.Now(), check("docker.logs", hosttune.Safe, hosttune.Warn, false)))
	in := h.acceptIn("docker.logs", "AGENT CURRENT docker.logs")
	_, first, err := h.c.AcceptHostCheck(h.ctx, host.ID, in, sam)
	if err != nil {
		t.Fatal(err)
	}
	in.Reason = "a different reason, given later"
	_, second, err := h.c.AcceptHostCheck(h.ctx, host.ID, in, HostActor{ID: "usr_2", Name: "Alex"})
	if err != nil {
		t.Fatal(err)
	}
	got, _ := h.st.GetHost(h.ctx, host.ID)
	if len(got.Acceptances) != 1 || got.Acceptances[0].Reason != in.Reason || got.Acceptances[0].ByName != "Alex" || second.ID != first.ID {
		t.Errorf("acceptances = %+v", got.Acceptances)
	}
}

// Two operators pressing Revoke want the same outcome, so the second is not told
// it failed; only a revoke that ended something has an acceptance to audit.
func TestRevokingIsIdempotentAndCountsTheCheckAgain(t *testing.T) {
	h := newHarness(t)
	host := h.host("revoking")
	h.reports(t, host, report(h.c.Now(), check("docker.logs", hosttune.Safe, hosttune.Warn, false)))
	if _, _, err := h.c.AcceptHostCheck(h.ctx, host.ID, h.acceptIn("docker.logs", "AGENT CURRENT docker.logs"), sam); err != nil {
		t.Fatal(err)
	}
	v, ended, err := h.c.RevokeHostCheck(h.ctx, host.ID, "docker.logs")
	if err != nil || ended == nil || ended.Reason != goodReason {
		t.Fatalf("revoke = %+v, %v", ended, err)
	}
	if v.Doctor.Summary.Warnings != 1 || v.Doctor.Summary.Accepted != 0 {
		t.Errorf("after revoking the summary is %+v", v.Doctor.Summary)
	}
	if got := h.problemsOf(t, "host.os_health"); len(got) != 1 {
		t.Errorf("after revoking there are %d problems, want 1", len(got))
	}
	v, ended, err = h.c.RevokeHostCheck(h.ctx, host.ID, "docker.logs")
	if err != nil || ended != nil || v.ID != host.ID {
		t.Errorf("second revoke = %v, %v, %v", v.ID, ended, err)
	}
	if _, _, err := h.c.RevokeHostCheck(h.ctx, "host_missing", "docker.logs"); !errors.Is(err, store.ErrNotFound) {
		t.Errorf("unknown host: %v", err)
	}
}

func TestTheSixtyFifthAcceptanceOnAHostIsRefused(t *testing.T) {
	h := newHarness(t)
	host := h.host("accept-limit")
	for i := 0; i < store.MaxHostCheckAcceptances; i++ {
		h.accept(t, host, "fake.check"+string(rune('a'+i%26))+string(rune('a'+i/26)), "x", h.c.Now().Add(time.Hour))
	}
	h.reports(t, host, report(h.c.Now(), check("docker.logs", hosttune.Safe, hosttune.Warn, false)))
	_, _, err := h.c.AcceptHostCheck(h.ctx, host.ID, h.acceptIn("docker.logs", "AGENT CURRENT docker.logs"), sam)
	if !errors.Is(err, ErrHostAcceptLimit) {
		t.Errorf("error = %v, want ErrHostAcceptLimit", err)
	}
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"sync"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/naming"
	"github.com/eyupio/zoomies/internal/store"
)

const (
	// HostCheckCooldown is how soon after a request the same host may be asked
	// again. It runs from the request, lives in controller memory, and is not
	// cleared by a failure: clearing on failure would let a token in a loop hammer
	// an agent that fails fast. It is a judgement value, not a measurement.
	HostCheckCooldown = 15 * time.Second
	// hostCheckPatience is how long a request may stay "asked" before the view
	// says it failed. It sits above the agent's 45 s bound on one run, so a slow
	// but healthy host is not reported as silent.
	hostCheckPatience = 60 * time.Second
	// hostCheckKeep is how long a finished request stays on the host's view. The
	// page shows it as "Checked just now"; after this the host is idle again and
	// the view carries nothing.
	hostCheckKeep = 30 * time.Second
)

// Reasons a request is refused, as the stable codes HostCheckError carries.
const (
	HostCheckNotConnected = "not_connected"
	HostCheckIncompatible = "incompatible"
	HostCheckUnsupported  = "unsupported"
	HostCheckFenced       = "fenced"
	HostCheckBusy         = "busy"
)

// HostCheckError is a refusal the operator can act on. The API renders it as a
// conflict with Message as the sentence.
type HostCheckError struct{ Code, Message string }

func (e *HostCheckError) Error() string { return e.Message }

// HostCheckCooldownError says the host was asked a moment ago.
type HostCheckCooldownError struct {
	Name  string
	Until time.Time
	now   time.Time
}

func (e *HostCheckCooldownError) Error() string {
	n := max(int((e.Until.Sub(e.now)+time.Second-1)/time.Second), 1)
	return fmt.Sprintf("%s was asked to check itself a moment ago. Ask again in %d s.", e.Name, n)
}

// hostCheck is what the controller remembers about the last request to a host.
// It is memory only, on purpose: a request is a conversation with a live agent,
// and nothing about it survives a restart worth persisting.
type hostCheck struct {
	TaskID, State, Outcome, Message string // State: asked | done | failed
	AskedAt, DoneAt, NextAt         time.Time
}

const (
	hostCheckAsked  = "asked"
	hostCheckDone   = "done"
	hostCheckFailed = "failed"
)

type hostChecks struct {
	mu     sync.Mutex
	byHost map[string]*hostCheck
}

func (hc *hostChecks) get(hostID string) (hostCheck, bool) {
	hc.mu.Lock()
	defer hc.mu.Unlock()
	if e := hc.byHost[hostID]; e != nil {
		return *e, true
	}
	return hostCheck{}, false
}

func (hc *hostChecks) set(hostID string, e hostCheck) {
	hc.mu.Lock()
	defer hc.mu.Unlock()
	if hc.byHost == nil {
		hc.byHost = map[string]*hostCheck{}
	}
	hc.byHost[hostID] = &e
}

func (hc *hostChecks) forget(hostID string) {
	hc.mu.Lock()
	delete(hc.byHost, hostID)
	hc.mu.Unlock()
}

// HostCheckView is the in-flight or just-finished request on a host's view.
type HostCheckView struct {
	State   string     `json:"state"`
	AskedAt time.Time  `json:"asked_at"`
	Outcome string     `json:"outcome,omitempty"`
	Message string     `json:"message,omitempty"`
	NextAt  *time.Time `json:"next_at,omitempty"`
}

// hostCheckView renders the request for the host view, or nil when there is
// nothing to say.
//
// The time-based changes -- asked turning to failed once patience runs out, a
// finished request dropping off -- are worked out here from the clock rather
// than by a timer, so GET and the event render the same thing and
// publishHostChanges re-sends a frame when the bytes move, at most one pass late.
func (c *Controller) hostCheckView(h *store.Host) *HostCheckView {
	e, ok := c.hostChecks.get(h.ID)
	if !ok {
		return nil
	}
	now := c.Now()
	switch e.State {
	case hostCheckAsked:
		if now.Sub(e.AskedAt) > hostCheckPatience {
			e.State = hostCheckFailed
			e.DoneAt = e.AskedAt.Add(hostCheckPatience)
			e.Message = fmt.Sprintf("%s did not answer in time. Check that its agent is running; the last report is still shown.", naming.ForSentence(h.Name))
		}
	}
	if e.State != hostCheckAsked && now.Sub(e.DoneAt) > hostCheckKeep {
		return nil
	}
	v := &HostCheckView{State: e.State, AskedAt: e.AskedAt, Outcome: e.Outcome, Message: e.Message}
	if now.Before(e.NextAt) {
		next := e.NextAt
		v.NextAt = &next
	}
	return v
}

// RequestHostCheck asks a host's agent to run its OS checks once. queued is true
// only when a task was actually put on the host's queue, which is what the
// caller audits: a repeat press and every refusal queue nothing.
//
// Nothing is dialled. The task goes out on the agent's own poll.
func (c *Controller) RequestHostCheck(ctx context.Context, hostID string) (h store.Host, queued bool, err error) {
	hp, err := c.st.GetHost(ctx, hostID)
	if err != nil {
		return store.Host{}, false, err
	}
	h = *hp
	now := c.Now()
	switch {
	case !c.mayAct():
		return h, false, &HostCheckError{HostCheckFenced, "This controller is recovering and is not handing out work yet. Try again in a minute."}
	case !h.Healthy(now):
		return h, false, &HostCheckError{HostCheckNotConnected, fmt.Sprintf("%s is not connected, so it cannot be asked. Its agent last reported %s. Check that the agent is running.", naming.ForSentence(h.Name), heartbeatWhen(h.LastHeartbeat, now))}
	case h.Incompatible:
		return h, false, &HostCheckError{HostCheckIncompatible, incompatibleReason(&h)}
	case !h.Supports(agent.FeatureHostCheck):
		return h, false, &HostCheckError{HostCheckUnsupported, fmt.Sprintf("The agent on %s cannot check on request. Agents running in a container, and agents older than this release, send their report on their own schedule instead. The last report is still shown.", naming.ForSentence(h.Name))}
	}
	if e, ok := c.hostChecks.get(h.ID); ok {
		if e.State == hostCheckAsked && now.Sub(e.AskedAt) <= hostCheckPatience {
			return h, false, nil
		}
		if now.Before(e.NextAt) {
			return h, false, &HostCheckCooldownError{Name: naming.ForSentence(h.Name), Until: e.NextAt, now: now}
		}
	}
	task := agent.Task{Kind: agent.TaskCheckHost, ID: "task_" + store.NewSecret(8), IssuedAt: now}
	if !c.enqueue(h.ID, task) {
		return h, false, &HostCheckError{HostCheckBusy, fmt.Sprintf("The previous request to %s is still being cleaned up. Try again in a few seconds.", naming.ForSentence(h.Name))}
	}
	c.hostChecks.set(h.ID, hostCheck{TaskID: task.ID, State: hostCheckAsked, AskedAt: now, NextAt: now.Add(HostCheckCooldown)})
	c.publishHost(&h)
	return h, true, nil
}

// heartbeatWhen says how long ago a host last reported, for a sentence an
// operator reads.
func heartbeatWhen(last, now time.Time) string {
	if last.IsZero() {
		return "never"
	}
	d := now.Sub(last).Round(time.Second)
	switch {
	case d < time.Minute:
		return fmt.Sprintf("%d s ago", int(d/time.Second))
	case d < time.Hour:
		return fmt.Sprintf("%d min ago", int(d/time.Minute))
	default:
		return fmt.Sprintf("%d h ago", int(d/time.Hour))
	}
}

// failHostCheck records a failure for the request taskID and announces it. A
// result for an older request must not overwrite a newer one, so an entry for a
// different task is left alone; an empty taskID matches whatever is there.
func (c *Controller) failHostCheck(ctx context.Context, hostID, taskID, message string) {
	e, ok := c.hostChecks.get(hostID)
	if ok && taskID != "" && e.TaskID != taskID {
		return
	}
	if !ok {
		e = hostCheck{TaskID: taskID, AskedAt: c.Now()}
	}
	e.State, e.Message, e.Outcome, e.DoneAt = hostCheckFailed, message, "", c.Now()
	c.hostChecks.set(hostID, e)
	if h, err := c.st.GetHost(ctx, hostID); err == nil {
		c.publishHost(h)
	}
}

// expireHostCheck is the sweep's word that a request was never answered.
//
// It speaks only while the request is still within the patience the view gives
// it, which is the case of a task that was never delivered. Past that the view
// already says "did not answer in time" and has started its keep window, and
// overwriting it here would restart the window and swap in a sentence that is
// false for a task the agent did take.
func (c *Controller) expireHostCheck(ctx context.Context, hostID, taskID string) {
	if e, ok := c.hostChecks.get(hostID); ok && e.TaskID == taskID &&
		(e.State != hostCheckAsked || c.Now().Sub(e.AskedAt) > hostCheckPatience) {
		return
	}
	c.failHostCheck(ctx, hostID, taskID, fmt.Sprintf("%s did not pick the request up. Check that its agent is running; the last report is still shown.", c.hostName(ctx, hostID)))
}

// applyHostCheck takes the agent's answer to a check_host task.
//
// A result reaches the controller through ReportResult, which has no host row
// and is not a heartbeat, so this does its own fresh read, validates, ingests,
// and records freshness with a narrow write -- never HeartbeatWithReport, which
// would let a task result pose as a heartbeat.
func (c *Controller) applyHostCheck(ctx context.Context, hostID string, res agent.TaskResult, issuedAt time.Time) {
	h, err := c.st.GetHost(ctx, hostID)
	if err != nil {
		// The host was deleted while the agent was working; its entry went with it.
		return
	}
	switch {
	case !res.OK && res.NotStarted:
		c.failHostCheck(ctx, hostID, res.TaskID, fmt.Sprintf("The agent on %s was restarting and gave the request back. Ask again in a moment.", naming.ForSentence(h.Name)))
		return
	case !res.OK && strings.Contains(res.Error, "unknown task kind"):
		c.failHostCheck(ctx, hostID, res.TaskID, fmt.Sprintf("The agent on %s is older than this controller and does not know how to check on request. Update it.", naming.ForSentence(h.Name)))
		return
	case !res.OK:
		c.failHostCheck(ctx, hostID, res.TaskID, fmt.Sprintf("%s could not run its checks: %s", naming.ForSentence(h.Name), res.Error))
		return
	case res.Doctor == nil:
		c.failHostCheck(ctx, hostID, res.TaskID, fmt.Sprintf("%s answered without a report.", naming.ForSentence(h.Name)))
		return
	}
	now := c.Now()
	in := res.Doctor
	// This also clears the acceptance fields, so an agent cannot smuggle an
	// acceptance in through the result path.
	if err := validateDoctor(in, now); err != nil {
		c.failHostCheck(ctx, hostID, res.TaskID, fmt.Sprintf("%s sent a report this controller refused: %v. Check the clock on that host.", naming.ForSentence(h.Name), err))
		return
	}
	outcome := "changed"
	switch {
	case h.Doctor.Report == nil:
		outcome = "first"
	case !in.CheckedAt.After(h.Doctor.CheckedAt):
		outcome = "not_newer"
	case h.Doctor.SameFindings(*in):
		outcome = "unchanged"
	}
	// Recorded before ingestDoctor, so the frame it publishes on a write already
	// carries the answer. A late result after the page gave up still lands: it
	// is fresh, read-only data.
	e, ok := c.hostChecks.get(hostID)
	switch {
	case ok && e.TaskID != res.TaskID:
		// A newer request owns the entry; this report is ingested all the same.
	default:
		if !ok {
			e = hostCheck{TaskID: res.TaskID, AskedAt: issuedAt}
			if e.AskedAt.IsZero() {
				e.AskedAt = now
			}
		}
		e.State, e.Outcome, e.Message, e.DoneAt = hostCheckDone, outcome, "", now
		c.hostChecks.set(hostID, e)
	}
	freshAt, err := c.ingestDoctor(ctx, h, in)
	if err != nil {
		c.log.Warn("could not store a host's on-request report", "host", hostID, "error", err)
		c.failHostCheck(ctx, hostID, res.TaskID, fmt.Sprintf("%s answered, but the controller could not store its report: %v", naming.ForSentence(h.Name), err))
		return
	}
	switch {
	case !freshAt.IsZero():
		if err := c.st.SetHostDoctorChecked(ctx, h.ID, freshAt); err != nil && !errors.Is(err, store.ErrNotFound) {
			c.log.Warn("could not record when a host was last checked", "host", hostID, "error", err)
		}
		c.publishHost(h)
	case outcome == "not_newer":
		c.publishHost(h)
	}
}

package controller

import (
	"encoding/json"
	"errors"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/hosttune"
	"github.com/eyupio/zoomies/internal/store"
)

// checkHost seeds a connected host whose agent can answer a check.
func (h *harness) checkHost(name string) *store.Host {
	h.t.Helper()
	return h.hostWith(name, agent.FeatureHostCheck)
}

// takeChecks hands the host's pending tasks to its "agent", as a poll would.
func (h *harness) takeChecks(hostID string) []agent.Task {
	return h.c.queues.get(hostID).take(maxTasksPerPoll, h.c.Now())
}

func (h *harness) view(hostID string) HostView {
	h.t.Helper()
	host, err := h.st.GetHost(h.ctx, hostID)
	if err != nil {
		h.t.Fatal(err)
	}
	return h.c.HostView(host)
}

// answer reports a successful check carrying rep, the way the agent does.
func (h *harness) answer(hostID string, task agent.Task, rep *hosttune.Report) {
	h.t.Helper()
	res := agent.TaskResult{TaskID: task.ID, Kind: agent.TaskCheckHost, OK: true, Doctor: rep}
	if err := h.c.ReportResult(h.ctx, hostID, res); err != nil {
		h.t.Fatal(err)
	}
}

// A refusal must queue nothing: the button is for an agent that is there and
// can answer, and a task left behind for one that is not would run hours later.
func TestAHostThatCannotAnswerIsRefusedWithAReasonAndNothingIsQueued(t *testing.T) {
	cases := []struct {
		name  string
		setup func(h *harness) *store.Host
		code  string
		want  string
	}{
		{"an agent that has gone quiet", func(h *harness) *store.Host {
			host := h.checkHost("quiet")
			h.advance(store.HeartbeatTimeout + time.Second)
			return host
		}, HostCheckNotConnected, "not connected"},
		{"an agent on another protocol", func(h *harness) *store.Host {
			host := h.checkHost("skewed")
			if err := h.st.SetHostProtocol(h.ctx, host.ID, 9, true); err != nil {
				t.Fatal(err)
			}
			return host
		}, HostCheckIncompatible, "protocol version 9"},
		{"an agent that does not advertise the feature", func(h *harness) *store.Host {
			return h.hostWith("container")
		}, HostCheckUnsupported, "container"},
		{"a controller behind the fence", func(h *harness) *store.Host {
			host := h.checkHost("fenced")
			h.fence("restored")
			return host
		}, HostCheckFenced, "recovering"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			host := tc.setup(h)
			_, queued, err := h.c.RequestHostCheck(h.ctx, host.ID)
			var he *HostCheckError
			if !errors.As(err, &he) || he.Code != tc.code || !strings.Contains(he.Message, tc.want) {
				t.Fatalf("err = %v, want a %s refusal mentioning %q", err, tc.code, tc.want)
			}
			if queued || len(h.tasksFor(host.ID)) != 0 {
				t.Fatal("a refused request queued a task")
			}
			if v := h.view(host.ID); v.HealthCheck != nil {
				t.Fatalf("a refusal left %+v on the host view", v.HealthCheck)
			}
		})
	}
}

func TestAskingAnUnknownHostIsNotFound(t *testing.T) {
	h := newHarness(t)
	if _, _, err := h.c.RequestHostCheck(h.ctx, "host_nope"); !errors.Is(err, store.ErrNotFound) {
		t.Fatalf("err = %v, want not found", err)
	}
}

// Pressing twice is one request: the second press restates the first rather
// than queueing a second check or reporting an error for a double click.
func TestAskingAHostTwiceQueuesOneTaskAndTheSecondPressChangesNothing(t *testing.T) {
	h := newHarness(t)
	host := h.checkHost("twice")
	got, queued, err := h.c.RequestHostCheck(h.ctx, host.ID)
	if err != nil || !queued || got.ID != host.ID {
		t.Fatalf("first press: queued=%v err=%v", queued, err)
	}
	if v := h.view(host.ID); v.HealthCheck == nil || v.HealthCheck.State != "asked" || v.HealthCheck.NextAt == nil {
		t.Fatalf("view after asking = %+v, want asked with a next_at", v.HealthCheck)
	}
	if _, queued, err := h.c.RequestHostCheck(h.ctx, host.ID); err != nil || queued {
		t.Fatalf("second press: queued=%v err=%v, want an idempotent no-op", queued, err)
	}
	if n := len(h.tasksFor(host.ID)); n != 1 {
		t.Fatalf("%d tasks queued, want 1", n)
	}
}

// A cordoned host is still checkable: cordoning stops new work, and a check is
// read-only and takes no slot.
func TestACordonedHostCanStillBeChecked(t *testing.T) {
	h := newHarness(t)
	host := h.checkHost("cordoned")
	if err := h.st.SetHostCordoned(h.ctx, host.ID, true); err != nil {
		t.Fatal(err)
	}
	if _, queued, err := h.c.RequestHostCheck(h.ctx, host.ID); err != nil || !queued {
		t.Fatalf("queued=%v err=%v", queued, err)
	}
}

// The cooldown runs from the request and a failure does not clear it. Clearing
// it would let a loop with a token hammer an agent that fails at once.
func TestTheCooldownRunsFromTheRequestAndAFailureDoesNotClearIt(t *testing.T) {
	h := newHarness(t)
	host := h.checkHost("cool")
	_, _, err := h.c.RequestHostCheck(h.ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	task := h.takeChecks(host.ID)[0]
	if err := h.c.ReportResult(h.ctx, host.ID, agent.TaskResult{TaskID: task.ID, Kind: agent.TaskCheckHost, OK: false, Error: "boom"}); err != nil {
		t.Fatal(err)
	}
	h.advance(5 * time.Second)
	_, queued, err := h.c.RequestHostCheck(h.ctx, host.ID)
	var cd *HostCheckCooldownError
	if !errors.As(err, &cd) || queued {
		t.Fatalf("err = %v queued=%v, want the cooldown", err, queued)
	}
	if !strings.Contains(err.Error(), "Ask again in 10 s") {
		t.Fatalf("message = %q, want the seconds left", err.Error())
	}
	h.advance(HostCheckCooldown)
	if _, queued, err := h.c.RequestHostCheck(h.ctx, host.ID); err != nil || !queued {
		t.Fatalf("after the cooldown: queued=%v err=%v", queued, err)
	}
}

// Whatever the agent does, a check is delivered once: a third delivery to an
// operator who gave up long ago would be a check nobody is waiting for.
func TestACheckGetsOneAttemptAndEveryOtherKindKeepsThree(t *testing.T) {
	if maxAttempts(agent.TaskCheckHost) != 1 {
		t.Fatalf("check_host attempts = %d, want 1", maxAttempts(agent.TaskCheckHost))
	}
	for _, k := range []agent.TaskKind{agent.TaskCreateRunner, agent.TaskStopRunner, agent.TaskRemoveRunner, agent.TaskPrewarmImage, agent.TaskFillToolCache} {
		if maxAttempts(k) != maxTaskAttempts {
			t.Errorf("%s attempts = %d, want %d", k, maxAttempts(k), maxTaskAttempts)
		}
	}
	h := newHarness(t)
	host := h.checkHost("once")
	if _, _, err := h.c.RequestHostCheck(h.ctx, host.ID); err != nil {
		t.Fatal(err)
	}
	task := h.takeChecks(host.ID)[0]
	// The agent gives it back unstarted: out of attempts, so it is not offered again.
	err := h.c.ReportResult(h.ctx, host.ID, agent.TaskResult{TaskID: task.ID, Kind: agent.TaskCheckHost, NotStarted: true})
	if err != nil {
		t.Fatal(err)
	}
	if len(h.tasksFor(host.ID)) != 0 {
		t.Fatal("a check given back was queued for a second delivery")
	}
	if v := h.view(host.ID); v.HealthCheck == nil || v.HealthCheck.State != "failed" {
		t.Fatalf("view = %+v, want failed", v.HealthCheck)
	}
}

// A check with no runner behind it needs a lease or its key stays outstanding
// for ever and the button is dead on that host.
func TestALostCheckExpiresAndTheHostCanBeAskedAgain(t *testing.T) {
	h := newHarness(t)
	host := h.checkHost("lost")
	if _, _, err := h.c.RequestHostCheck(h.ctx, host.ID); err != nil {
		t.Fatal(err)
	}
	h.takeChecks(host.ID)
	h.advance(hostCheckLease + time.Second)
	// Keep the host connected so the second request is not refused for silence.
	if _, err := h.c.Heartbeat(h.ctx, host.ID, agent.HeartbeatRequest{ProtocolVersion: agent.ProtocolVersion, Features: []string{agent.FeatureHostCheck}}); err != nil {
		t.Fatal(err)
	}
	h.c.sweepTasks(h.ctx, h.c.Now())
	// The view gave up at sixty seconds and let the failure go thirty later, so
	// by the lease there is nothing left to show; what matters is that it is
	// not "asked" and the queue is clear.
	if v := h.view(host.ID).HealthCheck; v != nil && v.State == "asked" {
		t.Fatalf("view = %+v, want the request no longer asked after the lease", v)
	}
	if h.c.queues.get(host.ID).depthTotal() != 0 {
		t.Fatal("the lost check is still outstanding")
	}
	if _, queued, err := h.c.RequestHostCheck(h.ctx, host.ID); err != nil || !queued {
		t.Fatalf("asking again: queued=%v err=%v", queued, err)
	}
}

// A task the agent took and never answered is already shown as "did not answer
// in time" at sixty seconds; the lease sweep at ninety must not bring the line
// back for a second window with a sentence that says the agent never picked it up.
func TestALeaseExpiringAfterTheViewGaveUpDoesNotRewriteTheFailure(t *testing.T) {
	h := newHarness(t)
	host := h.checkHost("hung")
	if _, _, err := h.c.RequestHostCheck(h.ctx, host.ID); err != nil {
		t.Fatal(err)
	}
	h.takeChecks(host.ID)
	h.advance(hostCheckPatience + time.Second)
	if v := h.view(host.ID).HealthCheck; v == nil || !strings.Contains(v.Message, "did not answer in time") {
		t.Fatalf("view = %+v, want the patience failure", v)
	}
	h.advance(hostCheckKeep)
	if v := h.view(host.ID).HealthCheck; v != nil {
		t.Fatalf("view = %+v, want the failure to have dropped off", v)
	}
	h.advance(hostCheckLease)
	h.c.sweepTasks(h.ctx, h.c.Now())
	if v := h.view(host.ID).HealthCheck; v != nil {
		t.Fatalf("view = %+v, want the sweep to leave a finished failure alone", v)
	}
}

func (q *taskQueue) depthTotal() int { p, f := q.depth(); return p + f }

// Nobody listening means the task would run when the agent next appears, long
// after the press. It is dropped and the page is told why.
func TestACheckNobodyPickedUpIsDroppedAfterTwentySeconds(t *testing.T) {
	h := newHarness(t)
	host := h.checkHost("deaf")
	if _, _, err := h.c.RequestHostCheck(h.ctx, host.ID); err != nil {
		t.Fatal(err)
	}
	h.advance(hostCheckPendingTTL - time.Second)
	h.c.sweepTasks(h.ctx, h.c.Now())
	if len(h.tasksFor(host.ID)) != 1 {
		t.Fatal("a check was dropped before its twenty seconds")
	}
	h.advance(2 * time.Second)
	h.c.sweepTasks(h.ctx, h.c.Now())
	if len(h.tasksFor(host.ID)) != 0 {
		t.Fatal("a stale pending check was kept")
	}
	v := h.view(host.ID)
	if v.HealthCheck == nil || v.HealthCheck.State != "failed" || !strings.Contains(v.HealthCheck.Message, "did not pick the request up") {
		t.Fatalf("view = %+v, want a failure saying the request was not picked up", v.HealthCheck)
	}
}

// What the page does with the answer depends on how it compares with the last
// report, and the first frame carrying a changed report must already say so.
func TestAnAnsweredCheckIsIngestedAndSaysHowItComparedWithTheLastReport(t *testing.T) {
	cases := []struct {
		name  string
		prior func(h *harness, host *store.Host, base time.Time)
		rep   func(base time.Time) *hosttune.Report
		want  string
	}{
		{"the first report", func(*harness, *store.Host, time.Time) {}, func(b time.Time) *hosttune.Report {
			return reportAt(b.Add(time.Second), "61% free", hosttune.Warn)
		}, "first"},
		{"a report that changes a finding", func(h *harness, host *store.Host, b time.Time) {
			h.sendCheckableReport(host.ID, reportAt(b, "61% free", hosttune.Warn))
		}, func(b time.Time) *hosttune.Report { return reportAt(b.Add(time.Second), "61% free", hosttune.OK) }, "changed"},
		{"a report that says the same", func(h *harness, host *store.Host, b time.Time) {
			h.sendCheckableReport(host.ID, reportAt(b, "61% free", hosttune.Warn))
		}, func(b time.Time) *hosttune.Report { return reportAt(b.Add(time.Second), "60% free", hosttune.Warn) }, "unchanged"},
		{"a report from a clock that is behind", func(h *harness, host *store.Host, b time.Time) {
			h.sendCheckableReport(host.ID, reportAt(b, "61% free", hosttune.Warn))
		}, func(b time.Time) *hosttune.Report { return reportAt(b.Add(-time.Second), "61% free", hosttune.OK) }, "not_newer"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			host := h.checkHost("answers")
			base := h.c.Now().Truncate(time.Millisecond)
			tc.prior(h, host, base)
			if _, _, err := h.c.RequestHostCheck(h.ctx, host.ID); err != nil {
				t.Fatal(err)
			}
			task := h.takeChecks(host.ID)[0]
			beatBefore := h.mustHost(host.ID).LastHeartbeat
			sub := h.c.Events().Subscribe(h.ctx, events.SubscribeOptions{Kinds: []events.Kind{events.KindHostUpdated}})
			defer sub.Close()
			rep := tc.rep(base)
			h.answer(host.ID, task, rep)

			var last HostView
			frames := 0
			for {
				select {
				case ev := <-sub.C:
					frames++
					if err := json.Unmarshal(ev.Data, &last); err != nil {
						t.Fatal(err)
					}
				case <-time.After(200 * time.Millisecond):
					goto done
				}
			}
		done:
			if frames == 0 {
				t.Fatal("an answered check published no host frame")
			}
			if last.HealthCheck == nil || last.HealthCheck.State != "done" || last.HealthCheck.Outcome != tc.want {
				t.Fatalf("last frame health_check = %+v, want done/%s", last.HealthCheck, tc.want)
			}
			got := h.mustHost(host.ID)
			if !got.LastHeartbeat.Equal(beatBefore) {
				t.Fatal("a task result moved last_heartbeat; it must not pose as a heartbeat")
			}
			if tc.want == "unchanged" && !got.Doctor.CheckedAt.Equal(rep.CheckedAt) {
				t.Fatalf("freshness = %v, want the report's %v", got.Doctor.CheckedAt, rep.CheckedAt)
			}
			if tc.want == "not_newer" && got.Doctor.CheckedAt.Equal(rep.CheckedAt) {
				t.Fatal("a report from a clock behind the last one moved the stored time")
			}
			if h.c.queues.get(host.ID).depthTotal() != 0 {
				t.Fatal("the lease was not cleared")
			}
		})
	}
}

// sendCheckableReport is a heartbeat that keeps the host-check feature, which a
// heartbeat omitting its features would otherwise withdraw.
func (h *harness) sendCheckableReport(hostID string, r *hosttune.Report) {
	h.t.Helper()
	req := agent.HeartbeatRequest{ProtocolVersion: agent.ProtocolVersion, Doctor: r, Features: []string{agent.FeatureHostCheck}}
	if _, err := h.c.Heartbeat(h.ctx, hostID, req); err != nil {
		h.t.Fatal(err)
	}
}

func (h *harness) mustHost(id string) *store.Host {
	h.t.Helper()
	host, err := h.st.GetHost(h.ctx, id)
	if err != nil {
		h.t.Fatal(err)
	}
	return host
}

