// The count is the controller's, worked out on each read, so it cannot be
// stored and read back wrong and cannot outlive the results it counted. A host
// that has fixed its disk reads zero warnings on the next report with nothing
// else to clear.
func TestTheCountIsNeverStoredAndFollowsTheLatestReport(t *testing.T) {
	h := newHarness(t)
	host := h.host("recounted")
	beat := func(r *hosttune.Report) {
		t.Helper()
		if _, err := h.c.Heartbeat(h.ctx, host.ID, agent.HeartbeatRequest{ProtocolVersion: agent.ProtocolVersion, Doctor: r}); err != nil {
			t.Fatal(err)
		}
	}
	warningsNow := func() int {
		t.Helper()
		got, err := h.st.GetHost(h.ctx, host.ID)
		if err != nil {
			t.Fatal(err)
		}
		return h.c.HostView(got).Doctor.Summary.Warnings
	}

	now := h.c.Now()
	beat(&hosttune.Report{CheckedAt: now, OS: "linux", Results: []hosttune.Result{{ID: "disk.space", Tier: hosttune.Safe, Status: hosttune.Warn}}})
	if got := warningsNow(); got != 1 {
		t.Fatalf("warnings after a failing report = %d, want 1", got)
	}

	// What is written to the hosts table is the report and nothing the
	// controller worked out from it.
	got, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	stored, err := got.Doctor.Value()
	if err != nil {
		t.Fatal(err)
	}
	var column map[string]json.RawMessage
	if err := json.Unmarshal([]byte(stored.(string)), &column); err != nil {
		t.Fatal(err)
	}
	if _, ok := column["summary"]; ok {
		t.Errorf("the stored report carries a summary: %s", stored)
	}

	beat(&hosttune.Report{CheckedAt: now.Add(time.Second), OS: "linux", Results: []hosttune.Result{{ID: "disk.space", Tier: hosttune.Safe, Status: hosttune.OK}}})
	if got := warningsNow(); got != 0 {
		t.Errorf("warnings after the host fixed it = %d, want 0", got)
	}
}

// A host.updated frame is the resource's GET shape, summary included, because
// the UI drops the frame straight into its cache. A frame without the count
// would leave a badge counting the previous report until the next refetch.
func TestHostUpdatedCarriesTheSameDoctorCountAsGET(t *testing.T) {
	h := newHarness(t)
	host := h.host("live-count")
	sub := h.c.Events().Subscribe(h.ctx, events.SubscribeOptions{Kinds: []events.Kind{events.KindHostUpdated}})
	defer sub.Close()
	if _, err := h.c.Heartbeat(h.ctx, host.ID, agent.HeartbeatRequest{ProtocolVersion: agent.ProtocolVersion, Doctor: doctorTestReport(h.c.Now())}); err != nil {
		t.Fatal(err)
	}
	select {
	case event := <-sub.C:
		var live HostView
		if err := json.Unmarshal(event.Data, &live); err != nil {
			t.Fatal(err)
		}
		got, err := h.st.GetHost(h.ctx, host.ID)
		if err != nil {
			t.Fatal(err)
		}
		fetched := h.c.HostView(got)
		if live.Doctor == nil || fetched.Doctor == nil {
			t.Fatalf("a view lost the report: live=%v fetched=%v", live.Doctor, fetched.Doctor)
		}
		if live.Doctor.Summary != fetched.Doctor.Summary {
			t.Errorf("host.updated counted %+v, GET counts %+v", live.Doctor.Summary, fetched.Doctor.Summary)
		}
		if live.Doctor.Summary.Counted == 0 {
			t.Errorf("the frame carried an empty count: %+v", live.Doctor.Summary)
		}
	case <-time.After(time.Second):
		t.Fatal("no host health event")
	}
}

// Only an operator can accept a check. An agent that sends the marks itself --
// to silence its own alarm -- has them dropped before the report is stored, so
// they are neither counted nor ever read back.
func TestAnAgentCannotClaimToHaveAcceptedItsOwnWarning(t *testing.T) {
	h := newHarness(t)
	host := h.host("claimant")
	claim := hosttune.Result{ID: "docker.logs", Tier: hosttune.Safe, Status: hosttune.Warn, Current: "none",
		Accepted:   &hosttune.Acceptance{Reason: "trust me", By: "the host"},
		Ended:      &hosttune.Ended{Why: "changed"},
		Acceptable: true}
	r := &hosttune.Report{CheckedAt: h.c.Now(), OS: "linux", Results: []hosttune.Result{claim}}
	if _, err := h.c.Heartbeat(h.ctx, host.ID, agent.HeartbeatRequest{ProtocolVersion: agent.ProtocolVersion, Doctor: r}); err != nil {
		t.Fatal(err)
	}
	got, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	stored, err := got.Doctor.Value()
	if err != nil {
		t.Fatal(err)
	}
	for _, k := range []string{`"accepted"`, `"ended"`, `"acceptable"`} {
		if strings.Contains(stored.(string), k) {
			t.Errorf("the stored report kept %s: %s", k, stored)
		}
	}
	s := h.c.HostView(got).Doctor.Summary
	if s.Warnings != 1 || s.Accepted != 0 {
		t.Errorf("summary = %+v, want the warning counted and nothing accepted", s)
	}
}

// reportAt is a one-warning report whose free-space text moves with every call,
// the way a real host's does.
func reportAt(at time.Time, free string, status hosttune.Status) *hosttune.Report {
	return &hosttune.Report{CheckedAt: at, OS: "linux", Results: []hosttune.Result{
		{ID: "disk.space", Title: "Disk space", Tier: hosttune.Safe, Status: hosttune.OK, Current: free},
		{ID: "docker.logs", Title: "Docker log rotation", Tier: hosttune.Safe, Status: status, Current: "json-file"},
	}}
}

func (h *harness) sendReport(hostID string, r *hosttune.Report) {
	h.t.Helper()
	if _, err := h.c.Heartbeat(h.ctx, hostID, agent.HeartbeatRequest{ProtocolVersion: agent.ProtocolVersion, Doctor: r}); err != nil {
		h.t.Fatal(err)
	}
}

// drainHostUpdates counts the host frames that arrive within a short quiet
// period: the bus delivers from its own goroutine, so an instant read would
// miss a frame that is on its way.
func drainHostUpdates(sub *events.Subscription) (n int) {
	for {
		select {
		case <-sub.C:
			n++
		case <-time.After(150 * time.Millisecond):
			return n
		}
	}
}

// A report that says what the last one said is not news: the body is not
// rewritten and no frame goes out for it, but the host still reads as checked
// just now, because "Checked" and the stale pill and problem all read that time.
func TestAReportThatSaysNothingNewMovesFreshnessAndWritesNoBody(t *testing.T) {
	h := newHarness(t)
	host := h.host("quiet")
	sub := h.c.Events().Subscribe(h.ctx, events.SubscribeOptions{Kinds: []events.Kind{events.KindHostUpdated}})
	defer sub.Close()

	first := h.c.Now().Truncate(time.Millisecond)
	h.sendReport(host.ID, reportAt(first, "61% free (210.0 GiB)", hosttune.Warn))
	if drainHostUpdates(sub) == 0 {
		t.Fatal("the first report should publish")
	}

	h.advance(60 * time.Second)
	second := first.Add(60 * time.Second)
	h.sendReport(host.ID, reportAt(second, "60% free (209.0 GiB)", hosttune.Warn))
	if n := drainHostUpdates(sub); n != 0 {
		t.Fatalf("an unchanged report published %d host frames", n)
	}
	got, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	if !got.Doctor.CheckedAt.Equal(second) {
		t.Fatalf("checked_at = %v, want the second report's %v", got.Doctor.CheckedAt, second)
	}
	if !got.DoctorBodyAt.Equal(first) {
		t.Fatalf("body was rewritten at %v; it should still be the first report's %v", got.DoctorBodyAt, first)
	}
	if got.Doctor.Results[0].Current != "61% free (210.0 GiB)" {
		t.Fatalf("the stored disk text moved to %q", got.Doctor.Results[0].Current)
	}
}

func TestAReportThatChangesAFindingIsWrittenAndPublished(t *testing.T) {
	h := newHarness(t)
	host := h.host("changed")
	sub := h.c.Events().Subscribe(h.ctx, events.SubscribeOptions{Kinds: []events.Kind{events.KindHostUpdated}})
	defer sub.Close()
	first := h.c.Now().Truncate(time.Millisecond)
	h.sendReport(host.ID, reportAt(first, "61% free", hosttune.Warn))
	drainHostUpdates(sub)

	h.advance(60 * time.Second)
	second := first.Add(60 * time.Second)
	h.sendReport(host.ID, reportAt(second, "61% free", hosttune.OK))
	if drainHostUpdates(sub) == 0 {
		t.Fatal("a warning clearing is news and must be published")
	}
	got, _ := h.st.GetHost(h.ctx, host.ID)
	if got.Doctor.Results[1].Status != hosttune.OK || !got.DoctorBodyAt.Equal(second) {
		t.Fatalf("the new body was not stored: %v at %v", got.Doctor.Results[1].Status, got.DoctorBodyAt)
	}
}

// The body is rewritten at least every doctorBodyMaxAge, so a drifting disk
// figure on the page is never older than that beside a fresh "Checked".
func TestAnUnchangedBodyIsStillRewrittenWhenItReachesTheMaximumAge(t *testing.T) {
	h := newHarness(t)
	host := h.host("aged")
	first := h.c.Now().Truncate(time.Millisecond)
	h.sendReport(host.ID, reportAt(first, "61% free", hosttune.Warn))
	h.advance(doctorBodyMaxAge)
	late := first.Add(doctorBodyMaxAge)
	h.sendReport(host.ID, reportAt(late, "55% free", hosttune.Warn))
	got, _ := h.st.GetHost(h.ctx, host.ID)
	if !got.DoctorBodyAt.Equal(late) || got.Doctor.Results[0].Current != "55% free" {
		t.Fatalf("body still at %v reading %q", got.DoctorBodyAt, got.Doctor.Results[0].Current)
	}
}

package controller

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/hosttune"
	"github.com/eyupio/zoomies/internal/naming"
	"github.com/eyupio/zoomies/internal/store"
)

// maxNamedFindings is how many checks an OS health problem names. The rest are
// counted: a title is read at a glance, and a host with a dozen findings is
// better served by its own page than by a dozen names in a drawer.
const maxNamedFindings = 3

// hostHealthReport is the report a host's OS health is judged on, or nil when
// there is nothing fair to say: no report yet, a host that is not connected
// (host.unhealthy speaks, and a report from before it went quiet describes a
// machine nobody can see), or a report that is only the container's view, which
// skips most checks and warns about the image's distribution for ever.
//
// The problems and the metrics share it so they cannot disagree about which
// hosts may speak: an alert on a metric that fires for a host the drawer says
// nothing about is the failure this is here to design out.
//
// It is also the one place an operator's acceptances are applied. The report
// returned is a judged copy, so a warning someone has accepted is counted by
// nothing downstream, and a problem can never be raised from a check the page
// shows as accepted. The reboot is judged before acceptances and is never
// acceptable, so it is untouched.
func hostHealthReport(h *store.Host, now time.Time) *hosttune.Report {
	r := h.Doctor.Report
	if r == nil || r.Container || !h.Healthy(now) {
		return nil
	}
	return h.JudgedDoctor(now)
}

// hostHealthProblems raises, for each connected host with a full OS report,
// what the report says needs attention, that the reports have stopped coming,
// and that a reboot is due.
//
// None of the three carries a Remedy. The controller never changes a host's
// operating system -- only a person on the host does, with consent, through
// zoomies doctor --interactive or zoomies tune -- and the autopilot only acts
// on problems that carry one, so each Fix is a sentence that sends a person to
// the host rather than a button.
func (c *Controller) hostHealthProblems(ctx context.Context, out *[]Problem) error {
	hosts, err := c.fleetHosts(ctx)
	if err != nil {
		return fmt.Errorf("listing hosts: %w", err)
	}
	// Read once from the controller's own clock, never the store's: the
	// staleness of a report is a statement about this controller's view of the
	// host, and a test that moves the clock has to move all of it together.
	now := c.Now()
	for _, h := range hosts {
		r := hostHealthReport(h, now)
		if r == nil {
			continue
		}
		// A cordoned host is not skipped. A cordoned, idle host is exactly
		// where a pending reboot belongs, and cordoning says nothing about
		// whether its settings are right.
		if p, ok := osHealthProblem(h, r); ok {
			*out = append(*out, p)
		}
		if p, ok := healthStaleProblem(h, r, now); ok {
			*out = append(*out, p)
		}
		if p, ok := rebootPendingProblem(h, r); ok {
			*out = append(*out, p)
		}
	}
	return nil
}

// osHealthProblem is the checks that count -- the ones zoomies doctor counts by
// default -- that found something. A warning is a setting below the
// recommendation and an error is a check that could not run, so the severity
// follows the errors: a host with only warnings is one an operator should look
// at, not one to be woken for.
//
// Nothing the host wrote is repeated here. A report is the agent's own text and
// this reaches every signed-in viewer, so checks are named from this build's
// catalogue and never from the report, which also makes the sentence a function
// of the check ids alone. A "current" value such as the free disk space moves
// with every report, and text that moved would send the whole problems list to
// every open tab each time. There is no Since for the same reason: nothing
// records when a finding first appeared, and CheckedAt moves on every report.
func osHealthProblem(h *store.Host, r *hosttune.Report) (Problem, bool) {
	// A host name is the agent's to choose, so it goes into prose, never into a
	// code span the UI would offer to copy.
	label := naming.ForSentence(h.Name)
	findings := r.Findings()
	if len(findings) == 0 {
		return Problem{}, false
	}
	severity := config.SeverityWarning
	if r.Summary().Errors > 0 {
		severity = config.SeverityError
	}

	title := fmt.Sprintf("host %s has an OS health check that needs attention", label)
	if len(findings) > 1 {
		title = fmt.Sprintf("host %s has %s that need attention", label, plural(len(findings), "OS health check"))
	}
	detail := fmt.Sprintf("%s's latest OS report flags %s. "+
		"Only the safe checks count here -- the ones zoomies doctor counts by default -- "+
		"so settings in the aggressive and dedicated tiers, and anything optional, are suggestions "+
		"that show on the host's page and never raise a problem.", label, nameFindings(findings))
	if severity == config.SeverityError {
		detail += " A check that could not run failed to read what it looks at, or found a file that is not valid, " +
			"such as /etc/docker/daemon.json; that is different from a setting below the recommendation."
	}
	return Problem{
		Code:     "host.os_health",
		Severity: severity,
		Title:    title,
		Detail:   detail,
		Fix: fmt.Sprintf("on %s, run `sudo zoomies doctor --verbose` to see what each check found, why any could not run "+
			"and what would be better, then `sudo zoomies doctor --interactive` to be offered each fix it can make, "+
			"with the changes shown first. From another machine, the host's page has the command to read the report, with the "+
			"controller's address and a short-lived token already in it. Zoomies never changes a host's operating system "+
			"without that consent.", label),
		TargetKind: "host", TargetID: h.ID,
	}, true
}

// healthStaleProblem is a connected host that has stopped producing reports. It
// is judged against the controller's clock, so a host whose own clock is behind
// reads old, which is also true: what Zoomies shows of it cannot be trusted.
//
// A report up to a minute in the future is accepted on arrival, so its age here
// is negative and it is not stale. The boundary is strict: a report exactly
// ReportStaleAfter old is the last one that is not.
//
// A stale report does not silence the other two. A collector that has stopped
// does not fix an OS setting, and dropping them would turn "I can no longer see"
// into "all clear".
func healthStaleProblem(h *store.Host, r *hosttune.Report, now time.Time) (Problem, bool) {
	label := naming.ForSentence(h.Name)
	if now.Sub(r.CheckedAt) <= hosttune.ReportStaleAfter {
		return Problem{}, false
	}
	// The time of the newest report rather than how long ago it was, for the
	// reason host.unhealthy gives the time of the last heartbeat: the list is
	// sent only when it changes, and "for 11 minutes" would be a new problem
	// every minute the collector stays silent. Since is the same time, which
	// does not move while no report arrives.
	since := r.CheckedAt
	return Problem{
		Code:     "host.health_stale",
		Severity: config.SeverityWarning,
		Title: fmt.Sprintf("host %s has sent no OS health report for over %d minutes",
			label, int(hosttune.ReportStaleAfter.Minutes())),
		Detail: fmt.Sprintf("the newest OS health report from %s is dated %s by the host's own clock, "+
			"but the host is still sending heartbeats, so its health collector has stopped producing reports "+
			"and what Zoomies shows of its operating system may no longer be true. "+
			"The age is judged against the controller's clock, so a host whose clock is wrong reads old.",
			label, r.CheckedAt.UTC().Format(time.RFC3339)),
		Fix: fmt.Sprintf("on %s, restart the agent (`sudo systemctl restart zoomies-agent`) and check that its clock "+
			"is right (`timedatectl`). It clears with the next report.", label),
		TargetKind: "host", TargetID: h.ID, Since: &since,
	}, true
}

// rebootPendingProblem is an update that has been installed and not yet taken
// up. It is a note and not a fault: the host keeps working, and nothing here
// can reboot it.
//
// It is raised whether or not anything is running on the host, because a plain
// dismissal is dropped when its entry stops being reported, so an entry that
// appeared only while the host was idle would come back, and need dismissing
// again, every time the host swung from busy to idle. Title and detail are the
// same either way; only the fix says whether the host can be rebooted now.
func rebootPendingProblem(h *store.Host, r *hosttune.Report) (Problem, bool) {
	label := naming.ForSentence(h.Name)
	if !r.RebootPending {
		return Problem{}, false
	}
	// Cordon, not drain: drain cordons the host and then stops a runner that
	// is still busy after five minutes, which is the wrong advice for waiting
	// for jobs to finish. Both sentences are true whether or not the host is
	// already cordoned, so cordoning it does not make the text move a third way.
	// ActiveRunners is the field ListHosts fills; the sentence never says how
	// many, because a count would change with every runner that came and went.
	fix := fmt.Sprintf("nothing is running on %s, so it can be rebooted now. "+
		"If it is not cordoned, `zoomies hosts cordon %s` first keeps a job from landing on it meanwhile, "+
		"and `zoomies hosts uncordon %s` lets it take work again afterwards.", label, h.ID, h.ID)
	if h.ActiveRunners > 0 {
		// ActiveRunners counts every live runner, and a runner kept warm for a pool
		// with a minimum sits idle between jobs and never finishes by itself, so a
		// count cannot say whether a job is running. Telling an operator to wait
		// "until they finish" sent a quiet fleet to wait for ever. The runners list
		// has each runner's state, and takes the host's id, which the controller
		// made, rather than its name, which the agent chose.
		fix = fmt.Sprintf("runners are on %s, and one kept warm for a pool waits for work and never finishes by itself, "+
			"so this cannot tell a runner that holds a job from one that does not. "+
			"If it is not cordoned, `zoomies hosts cordon %s` stops new jobs arriving; "+
			"reboot it when `zoomies runners list --host %s --state busy` shows nothing, then `zoomies hosts uncordon %s`. "+
			"Zoomies never reboots a host itself.", label, h.ID, h.ID, h.ID)
	}
	return Problem{
		Code:     "host.reboot_pending",
		Severity: config.SeverityInfo,
		Title:    fmt.Sprintf("host %s is waiting for a reboot", label),
		Detail: fmt.Sprintf("an update installed on %s takes effect only after it restarts, usually a newer kernel "+
			"than the one running. It keeps working until then, so this is a note and not a fault. "+
			"Zoomies never reboots a host itself.", label),
		Fix:        fix,
		TargetKind: "host", TargetID: h.ID,
	}, true
}

// nameFindings says which checks a problem is about, in the order given -- errors
// first, because Findings puts them there -- naming at most maxNamedFindings and
// counting the rest.
//
// A name is the catalogue's own and never the report's. An id this build has
// never heard of -- from an agent newer than the controller, or one lying -- is
// counted in "and N more" and never named, so a host cannot put its own words in
// front of everyone who can read the problems list.
func nameFindings(fs []hosttune.Result) string {
	var named []string
	for _, x := range fs {
		if len(named) == maxNamedFindings {
			break
		}
		title, ok := hosttune.Title(x.ID)
		if !ok {
			continue
		}
		if x.Status == hosttune.Error {
			title += " (could not run)"
		}
		named = append(named, title)
	}
	if len(named) == 0 {
		return plural(len(fs), "check") + " this controller does not recognise"
	}
	if more := len(fs) - len(named); more > 0 {
		named = append(named, fmt.Sprintf("%d more", more))
	}
	if len(named) == 1 {
		return named[0]
	}
	last := len(named) - 1
	return strings.Join(named[:last], ", ") + " and " + named[last]
}

package controller

import (
	"encoding/json"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/hosttune"
	"github.com/eyupio/zoomies/internal/store"
)

// osHealthCodes are the three problems a host's OS report can raise.
var osHealthCodes = []string{"host.os_health", "host.health_stale", "host.reboot_pending"}

// check builds a result the way the engine stamps one: an id the controller
// knows, a tier, an outcome and whether it is only a suggestion. Title,
// Current and Rationale are filled with text that must never reach a problem,
// because they are the agent's.
func check(id string, tier hosttune.Tier, status hosttune.Status, optional bool) hosttune.Result {
	return hosttune.Result{
		ID: id, Tier: tier, Status: status, Optional: optional,
		Title: "AGENT TITLE " + id, Current: "AGENT CURRENT " + id,
		Recommended: "AGENT RECOMMENDED " + id, Rationale: "AGENT RATIONALE " + id, Reason: "AGENT REASON " + id,
	}
}

// report is a full report from a native agent, taken now.
func report(now time.Time, rs ...hosttune.Result) *hosttune.Report {
	return &hosttune.Report{CheckedAt: now, OS: "linux", Distro: "ubuntu 24.04", Results: rs}
}

// reports stores a host's latest OS report the way a heartbeat leaves it. The
// host row is read again by every problems pass, so this is the whole setup.
func (h *harness) reports(t *testing.T, host *store.Host, r *hosttune.Report) {
	t.Helper()
	if err := h.st.SetHostDoctor(h.ctx, host.ID, r); err != nil {
		t.Fatalf("SetHostDoctor: %v", err)
	}
}

// silence makes a host miss its heartbeats, which is all "offline" means.
func (h *harness) silence(t *testing.T, host *store.Host) {
	t.Helper()
	host.LastHeartbeat = time.Now().Add(-2 * store.HeartbeatTimeout)
	if err := h.st.UpdateHost(h.ctx, host); err != nil {
		t.Fatalf("UpdateHost: %v", err)
	}
}

// problemsOf is every problem in the list with a code, for the tests that care
// how many there are as much as what they say.
func (h *harness) problemsOf(t *testing.T, code string) []Problem {
	t.Helper()
	ps, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	var out []Problem
	for _, p := range ps {
		if p.Code == code {
			out = append(out, p)
		}
	}
	return out
}

// raised is which of the three OS health codes the list carries.
func (h *harness) raised(t *testing.T) []string {
	t.Helper()
	var out []string
	for _, code := range osHealthCodes {
		if len(h.problemsOf(t, code)) > 0 {
			out = append(out, code)
		}
	}
	return out
}

// A counted warning is a warning and only a counted error is an error. The
// owner's rule is that a stock host carries some warnings for ever, so a page
// for one would train people to ignore the page; what is worth waking for is a
// check that could not run, because then nobody knows what the host is doing.
func TestACountedWarningIsAWarningAndOnlyACountedErrorIsAnError(t *testing.T) {
	cases := []struct {
		name    string
		results []hosttune.Result
		want    config.Severity
		title   string
		isError bool
	}{
		{"one counted warning", []hosttune.Result{
			check("inotify.watches", hosttune.Safe, hosttune.Warn, false),
		}, config.SeverityWarning, "host build-04 has an OS health check that needs attention", false},
		{"three counted warnings", []hosttune.Result{
			check("inotify.watches", hosttune.Safe, hosttune.Warn, false),
			check("disk.space", hosttune.Safe, hosttune.Warn, false),
			check("docker.logs", hosttune.Safe, hosttune.Warn, false),
		}, config.SeverityWarning, "host build-04 has 3 OS health checks that need attention", false},
		{"one counted error", []hosttune.Result{
			check("docker.logs", hosttune.Safe, hosttune.Error, false),
		}, config.SeverityError, "host build-04 has an OS health check that needs attention", true},
		{"an error among warnings", []hosttune.Result{
			check("inotify.watches", hosttune.Safe, hosttune.Warn, false),
			check("docker.logs", hosttune.Safe, hosttune.Error, false),
		}, config.SeverityError, "host build-04 has 2 OS health checks that need attention", true},
		{"an error that is only a suggestion does not make it one", []hosttune.Result{
			check("inotify.watches", hosttune.Safe, hosttune.Warn, false),
			check("service.snapd", hosttune.Dedicated, hosttune.Error, false),
		}, config.SeverityWarning, "host build-04 has an OS health check that needs attention", false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			host := h.host("build-04")
			h.reports(t, host, report(h.c.Now(), tc.results...))

			ps := h.problemsOf(t, "host.os_health")
			if len(ps) != 1 {
				t.Fatalf("host.os_health entries = %d, want 1: %v", len(ps), h.problemCodes())
			}
			p := ps[0]
			if p.Severity != tc.want || p.Title != tc.title {
				t.Errorf("severity %s, title %q; want %s, %q", p.Severity, p.Title, tc.want, tc.title)
			}
			if p.TargetKind != "host" || p.TargetID != host.ID || p.Audience != AudienceFleet {
				t.Errorf("target %s/%s, audience %q; want this host, for the fleet", p.TargetKind, p.TargetID, p.Audience)
			}
			// The controller never changes the operating system, and the autopilot
			// acts only on a problem that carries a remedy, so none may.
			if p.Remedy != nil || p.Setting != "" || p.Since != nil {
				t.Errorf("remedy %v, setting %q, since %v; want none of them", p.Remedy, p.Setting, p.Since)
			}
			if got := strings.Contains(p.Detail, "could not run failed"); got != tc.isError {
				t.Errorf("detail explains a check that could not run = %v, want %v: %q", got, tc.isError, p.Detail)
			}
			// The command that works where the person is: on the host, which needs no
			// address and no token. `--host` reads through the controller and needs
			// both, so it is not offered as text to be typed -- the host's page has
			// it written out, with a token made on the spot -- and an advice that
			// led with it was how somebody ended up running it on the host, with
			// neither, and being told the controller was unreachable.
			if !strings.Contains(p.Fix, "on "+host.Name+", run `sudo zoomies doctor --verbose`") || !strings.Contains(p.Fix, "`sudo zoomies doctor --interactive`") {
				t.Errorf("fix %q should name the two commands to run on the host, and the host", p.Fix)
			}
			if !strings.Contains(p.Fix, "the host's page has the command") || !strings.Contains(p.Fix, "short-lived token") {
				t.Errorf("fix %q should send a person on another machine to the page that has the command", p.Fix)
			}
			if strings.Contains(p.Fix, "--host") {
				t.Errorf("fix %q hands over a command that cannot work as written", p.Fix)
			}
			if strings.Contains(strings.ToLower(p.Fix), "controller log") {
				t.Errorf("fix %q sends the fleet to a log it cannot read", p.Fix)
			}
		})
	}
}

// The aggressive and dedicated tiers and the optional checks are choices an
// operator has not made, not faults, and a stock host carries some for ever.
// Raising a problem for them would put a permanent entry on every fleet.
func TestSuggestionsNeverRaiseAProblem(t *testing.T) {
	h := newHarness(t)
	host := h.host("stock")
	h.reports(t, host, report(h.c.Now(),
		check("cgroup.version", hosttune.Safe, hosttune.OK, false),
		check("cpu.governor", hosttune.Aggressive, hosttune.Warn, false),
		check("memory.swappiness", hosttune.Aggressive, hosttune.Error, false),
		check("tmp.tmpfs", hosttune.Aggressive, hosttune.Warn, true),
		check("service.snapd", hosttune.Dedicated, hosttune.Warn, false),
		check("memory.swap-off", hosttune.Dedicated, hosttune.Warn, true),
		check("kernel.hwe-install", hosttune.Dedicated, hosttune.Skip, true),
		// A skipped counted check is not a finding either: it is a check that
		// could not be made, which the host's page says and a problem does not.
		check("files.service", hosttune.Safe, hosttune.Skip, false),
	))
	if got := h.raised(t); len(got) != 0 {
		t.Fatalf("a host with only suggestions raised %v", got)
	}
}

// A pending reboot is one fact that a report carries twice, as the
// kernel.pending warning and as the reboot flag. It is counted once, as the
// reboot: a host whose only finding is a reboot is not unwell, and an entry
// saying "an OS health check needs attention" over a reboot would put the same
// thing on the page twice.
func TestAPendingRebootIsCountedOnceAsTheReboot(t *testing.T) {
	t.Run("a reboot alone raises the reboot and not a health problem", func(t *testing.T) {
		h := newHarness(t)
		host := h.host("reboot-only")
		r := report(h.c.Now(), check(hosttune.KernelPending, hosttune.Safe, hosttune.Warn, false))
		r.RebootPending = true
		h.reports(t, host, r)

		if got := h.raised(t); !slices.Equal(got, []string{"host.reboot_pending"}) {
			t.Fatalf("raised %v, want only host.reboot_pending", got)
		}
		p := h.problem(t, "host.reboot_pending")
		if p.Severity != config.SeverityInfo || p.Title != "host reboot-only is waiting for a reboot" {
			t.Errorf("reboot problem = %s %q", p.Severity, p.Title)
		}
		if p.Remedy != nil || p.Setting != "" || p.Since != nil || p.TargetID != host.ID {
			t.Errorf("remedy %v, setting %q, since %v, target %q", p.Remedy, p.Setting, p.Since, p.TargetID)
		}
	})
	t.Run("a reboot beside a real finding raises both, and the health one does not name it", func(t *testing.T) {
		h := newHarness(t)
		host := h.host("both")
		r := report(h.c.Now(),
			check("inotify.watches", hosttune.Safe, hosttune.Warn, false),
			check(hosttune.KernelPending, hosttune.Safe, hosttune.Warn, false),
		)
		r.RebootPending = true
		h.reports(t, host, r)

		if got := h.raised(t); !slices.Equal(got, []string{"host.os_health", "host.reboot_pending"}) {
			t.Fatalf("raised %v, want the health problem and the reboot", got)
		}
		p := h.problem(t, "host.os_health")
		if !strings.Contains(p.Title, "has an OS health check that needs") {
			t.Errorf("title %q counts the reboot as a finding", p.Title)
		}
		if strings.Contains(p.Detail, "Installed kernel awaiting reboot") {
			t.Errorf("detail %q names the reboot as a finding", p.Detail)
		}
	})
	t.Run("a kernel warning with no reboot flag is a finding like any other", func(t *testing.T) {
		// A report that does not say a reboot is pending is judged by its rows.
		h := newHarness(t)
		host := h.host("unflagged")
		h.reports(t, host, report(h.c.Now(), check(hosttune.KernelPending, hosttune.Safe, hosttune.Warn, false)))
		if got := h.raised(t); !slices.Equal(got, []string{"host.os_health"}) {
			t.Fatalf("raised %v, want host.os_health", got)
		}
	})
}

// Nothing is raised where there is nothing fair to say, and the three cases are
// the ones where saying something would be wrong rather than merely unhelpful.
func TestAHostWithNothingFairToJudgeRaisesNothing(t *testing.T) {
	findings := func() []hosttune.Result {
		return []hosttune.Result{
			check("inotify.watches", hosttune.Safe, hosttune.Warn, false),
			check("docker.logs", hosttune.Safe, hosttune.Error, false),
			check(hosttune.KernelPending, hosttune.Safe, hosttune.Warn, false),
		}
	}
	cases := []struct {
		name  string
		setup func(t *testing.T, h *harness, host *store.Host)
	}{
		{"a host that has sent no report", func(t *testing.T, h *harness, host *store.Host) {}},
		{"an offline host, whatever its last report said", func(t *testing.T, h *harness, host *store.Host) {
			h.silence(t, host)
			// An old report as well: an offline host is silent about all three,
			// because host.unhealthy already speaks and a report from before it
			// went quiet describes a machine nobody can see.
			r := report(h.c.Now().Add(-time.Hour), findings()...)
			r.RebootPending = true
			h.reports(t, host, r)
		}},
		{"a container's partial report", func(t *testing.T, h *harness, host *store.Host) {
			// The container's own view skips most checks and warns about the
			// image's distribution for ever, and the monitor falls back to it
			// when the host's own file goes stale, so it is also fresh.
			r := report(h.c.Now(), findings()...)
			r.Container, r.RebootPending = true, true
			h.reports(t, host, r)
		}},
		{"a stale container report", func(t *testing.T, h *harness, host *store.Host) {
			r := report(h.c.Now().Add(-time.Hour), findings()...)
			r.Container, r.RebootPending = true, true
			h.reports(t, host, r)
		}},
		{"a full report with nothing to say", func(t *testing.T, h *harness, host *store.Host) {
			h.reports(t, host, report(h.c.Now(), check("cgroup.version", hosttune.Safe, hosttune.OK, false)))
		}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			host := h.host("quiet")
			tc.setup(t, h, host)
			if got := h.raised(t); len(got) != 0 {
				t.Fatalf("raised %v, want none", got)
			}
		})
	}
}

// The age is judged against the controller's clock, and only a report older than
// ReportStaleAfter is stale. A report a minute in the future is accepted on
// arrival, so its age is negative and it must not read as stale: a host whose
// clock runs a little fast is not a host whose collector has stopped.
func TestAReportIsStaleOnlyOnceItIsOlderThanTheThreshold(t *testing.T) {
	now := time.Date(2026, 10, 6, 14, 30, 0, 0, time.UTC)
	host := &store.Host{ID: "host_k3f9qz2mx7ab", Name: "build-04"}
	cases := []struct {
		name  string
		age   time.Duration
		stale bool
	}{
		{"a report taken now", 0, false},
		{"a report a minute in the future", -time.Minute, false},
		{"a report a nanosecond short of the threshold", hosttune.ReportStaleAfter - time.Nanosecond, false},
		{"a report exactly as old as the threshold", hosttune.ReportStaleAfter, false},
		{"a report a nanosecond past the threshold", hosttune.ReportStaleAfter + time.Nanosecond, true},
		{"a report an hour old", time.Hour, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			r := report(now.Add(-tc.age))
			p, ok := healthStaleProblem(host, r, now)
			if ok != tc.stale {
				t.Fatalf("stale = %v, want %v", ok, tc.stale)
			}
			if !ok {
				return
			}
			if p.Severity != config.SeverityWarning || p.Code != "host.health_stale" {
				t.Errorf("problem = %s %s, want a warning", p.Code, p.Severity)
			}
			if p.Since == nil || !p.Since.Equal(r.CheckedAt) {
				t.Errorf("since = %v, want the report's own time %v", p.Since, r.CheckedAt)
			}
		})
	}

	// The words, once: an absolute time and never an age, because the list is sent
	// only when it changes and an age is a new problem every minute.
	p, _ := healthStaleProblem(host, report(now.Add(-time.Hour)), now)
	if p.Title != "host build-04 has sent no OS health report for over 10 minutes" {
		t.Errorf("title = %q", p.Title)
	}
	if !strings.Contains(p.Detail, "is dated 2026-10-06T13:30:00Z by the host's own clock") {
		t.Errorf("detail = %q, want the report's absolute time", p.Detail)
	}
	if !strings.Contains(p.Fix, "`sudo systemctl restart zoomies-agent`") || !strings.Contains(p.Fix, "`timedatectl`") {
		t.Errorf("fix = %q", p.Fix)
	}
	if p.Remedy != nil || p.Setting != "" {
		t.Errorf("remedy %v, setting %q", p.Remedy, p.Setting)
	}
}

// Through the whole controller: a connected host whose newest report is old
// raises the stale problem, and the findings in that old report are still
// standing. A collector that has stopped does not fix an OS setting, and hiding
// them would turn "I can no longer see" into "all clear".
func TestAStaleReportOnAConnectedHostRaisesTheStaleProblemAndKeepsTheRest(t *testing.T) {
	h := newHarness(t)
	host := h.host("quiet-collector")
	r := report(h.c.Now().Add(-hosttune.ReportStaleAfter-time.Minute),
		check("inotify.watches", hosttune.Safe, hosttune.Warn, false),
		check(hosttune.KernelPending, hosttune.Safe, hosttune.Warn, false))
	r.RebootPending = true
	h.reports(t, host, r)

	if got := h.raised(t); !slices.Equal(got, osHealthCodes) {
		t.Fatalf("raised %v, want all three", got)
	}
	p := h.problem(t, "host.health_stale")
	if p.Since == nil || !p.Since.Equal(r.CheckedAt) || p.TargetID != host.ID {
		t.Errorf("stale problem = %+v", p)
	}
}

// One entry per host per code. A fleet of hosts that all need attention is a
// list with one line for each, not a line for every check on every host.
func TestEachHostRaisesAtMostOneEntryPerCode(t *testing.T) {
	h := newHarness(t)
	var ids []string
	for _, name := range []string{"a", "b", "c"} {
		host := h.host(name)
		ids = append(ids, host.ID)
		r := report(h.c.Now().Add(-time.Hour),
			check("inotify.watches", hosttune.Safe, hosttune.Warn, false),
			check("docker.logs", hosttune.Safe, hosttune.Error, false),
			check("disk.space", hosttune.Safe, hosttune.Warn, false),
			check("disk.inodes", hosttune.Safe, hosttune.Warn, false),
			check(hosttune.KernelPending, hosttune.Safe, hosttune.Warn, false))
		r.RebootPending = true
		h.reports(t, host, r)
	}
	for _, code := range osHealthCodes {
		ps := h.problemsOf(t, code)
		var targets []string
		for _, p := range ps {
			targets = append(targets, p.TargetID)
		}
		slices.Sort(targets)
		want := slices.Clone(ids)
		slices.Sort(want)
		if !slices.Equal(targets, want) {
			t.Errorf("%s targets = %v, want one for each of %v", code, targets, want)
		}
	}
}

// The list is sent to every open tab whenever its JSON differs from the last one
// sent. A report arrives about once a minute with a new time on it and often with
// new numbers in the agent's own text -- disk.space's current value is "9% free
// (47244816)" and moves with every file written -- so a sentence that carried
// either would re-send the whole list every minute for as long as the host had a
// finding.
func TestTheHealthProblemDoesNotMoveWhenOnlyTheReportDoes(t *testing.T) {
	host := &store.Host{ID: "host_k3f9qz2mx7ab", Name: "build-04"}
	at := time.Date(2026, 10, 6, 14, 0, 0, 0, time.UTC)
	build := func(checkedAt time.Time, current string) []byte {
		first := check("disk.space", hosttune.Safe, hosttune.Warn, false)
		first.Current = current
		first.Title = "disk space as this agent chooses to word it at " + current
		r := report(checkedAt, first, check("docker.logs", hosttune.Safe, hosttune.Error, false))
		r.RebootPending = true
		var out []Problem
		if p, ok := osHealthProblem(host, r); ok {
			out = append(out, p)
		}
		if p, ok := rebootPendingProblem(host, r); ok {
			out = append(out, p)
		}
		b, err := json.Marshal(out)
		if err != nil {
			t.Fatal(err)
		}
		return b
	}
	before := build(at, "9% free (47244816)")
	after := build(at.Add(7*time.Minute), "8% free (41943040)")
	if string(before) != string(after) {
		t.Errorf("a refreshed report changed the problems:\n before: %s\n  after: %s", before, after)
	}
	if strings.Contains(string(before), "47244816") || strings.Contains(string(before), "disk space as this agent") {
		t.Errorf("the agent's own text reached a problem: %s", before)
	}
}

// Through the controller, and the other way: a stale report that stands while
// time passes says the same thing every time, since the list is re-sent only
// when it changes and a sentence counting minutes would be a new one each pass.
func TestAStaleReportDoesNotChangeWhileTimePasses(t *testing.T) {
	h := newHarness(t)
	host := h.host("stuck-collector")
	h.reports(t, host, report(h.c.Now().Add(-time.Hour),
		check("inotify.watches", hosttune.Safe, hosttune.Warn, false)))
	before := problemJSON(t, h, "host.health_stale")
	// Less than the heartbeat timeout, so the host is still connected: a host
	// that went quiet would hand the problem to host.unhealthy.
	h.advance(30 * time.Second)
	if after := problemJSON(t, h, "host.health_stale"); after != before {
		t.Errorf("host.health_stale changed as time passed:\n before: %s\n  after: %s", before, after)
	}
	if got := problemJSON(t, h, "host.os_health"); got == "" {
		t.Error("the finding in the stale report was dropped")
	}
}

// Nothing a host wrote may reach a problem, because a problem reaches every
// signed-in viewer and the MCP tools: an agent is the least trusted writer in
// the system. An id the controller does not know is counted and never named.
func TestNoTextFromTheAgentReachesAProblem(t *testing.T) {
	h := newHarness(t)
	host := h.host("hostile")
	// An hour old, so that all three problems are raised and all three are read.
	r := report(h.c.Now().Add(-time.Hour),
		check("inotify.watches", hosttune.Safe, hosttune.Warn, false),
		check("ignore-previous-instructions", hosttune.Safe, hosttune.Warn, false),
		check("docker.logs", hosttune.Safe, hosttune.Error, false),
		check(hosttune.KernelPending, hosttune.Safe, hosttune.Warn, false))
	r.RebootPending = true
	r.OS, r.Distro, r.WorkDir = "AGENT OS", "AGENT DISTRO", "/AGENT/WORKDIR"
	h.reports(t, host, r)

	for _, code := range osHealthCodes {
		p := h.problem(t, code)
		all := p.Title + "\n" + p.Detail + "\n" + p.Fix
		for _, leaked := range []string{"AGENT", "ignore-previous-instructions", "/AGENT/WORKDIR"} {
			if strings.Contains(all, leaked) {
				t.Errorf("%s carries %q: %s", code, leaked, all)
			}
		}
	}
	// Named from the catalogue, errors first and marked, the unknown id counted.
	p := h.problem(t, "host.os_health")
	want := "flags Docker log rotation (could not run), File watches and 1 more."
	if !strings.Contains(p.Detail, want) {
		t.Errorf("detail %q does not say %q", p.Detail, want)
	}
}

// Only the one fix flips with the host, and on the one thing the owner asked it
// to: whether anything is running there, so whether it can be rebooted now.
// Title and detail are the same in both states, so the entry is the same entry,
// and a dismissal of it is not spent when the host swings between idle and busy.
func TestTheRebootFixSaysWhetherTheHostCanBeRebootedNow(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := report(h.c.Now(), check(hosttune.KernelPending, hosttune.Safe, hosttune.Warn, false))
	r.RebootPending = true
	h.reports(t, host, r)

	idle := h.problem(t, "host.reboot_pending")
	if !strings.Contains(idle.Fix, "nothing is running on vm-1, so it can be rebooted now") {
		t.Errorf("idle fix = %q", idle.Fix)
	}

	h.runnerRow(pool, host, store.RunnerIdle)
	busy := h.problem(t, "host.reboot_pending")
	// A runner kept warm for a pool is idle and never finishes by itself, so the
	// fix must not promise that waiting for the runners to finish ends: it sends
	// the operator to the runners that hold a job, by the host's id.
	if !strings.Contains(busy.Fix, "runners are on vm-1") ||
		!strings.Contains(busy.Fix, "`zoomies runners list --host "+host.ID+" --state busy`") ||
		strings.Contains(busy.Fix, "once they have finished") {
		t.Errorf("busy fix = %q", busy.Fix)
	}

	if idle.Title != busy.Title || idle.Detail != busy.Detail {
		t.Errorf("title or detail moved with the host's load:\n idle: %q %q\n busy: %q %q", idle.Title, idle.Detail, busy.Title, busy.Detail)
	}
	for _, fix := range []string{idle.Fix, busy.Fix} {
		// Cordon, not drain: drain cordons and then stops a busy runner after
		// five minutes, which is the wrong advice for waiting for jobs.
		if !strings.Contains(fix, "`zoomies hosts cordon "+host.ID+"`") || !strings.Contains(fix, "`zoomies hosts uncordon "+host.ID+"`") {
			t.Errorf("fix %q should name cordon and uncordon with the host's id", fix)
		}
		if strings.Contains(fix, "drain") {
			t.Errorf("fix %q advises drain", fix)
		}
		// A count would change with every runner that came and went, and the
		// entry would be re-sent each time; the host's own name and id are the
		// only digits there may be.
		if bare := strings.NewReplacer(host.ID, "", host.Name, "").Replace(fix); strings.ContainsAny(bare, "0123456789") {
			t.Errorf("fix %q carries a number", fix)
		}
	}
	if busy.Severity != config.SeverityInfo {
		t.Errorf("severity = %s, want info", busy.Severity)
	}
}

// A cordoned host is exactly where a reboot belongs, so it is not skipped.
func TestACordonedHostStillRaisesTheRebootAndItsFindings(t *testing.T) {
	h := newHarness(t)
	host := h.host("cordoned")
	if err := h.st.SetHostCordoned(h.ctx, host.ID, true); err != nil {
		t.Fatal(err)
	}
	r := report(h.c.Now(), check("inotify.watches", hosttune.Safe, hosttune.Warn, false))
	r.RebootPending = true
	h.reports(t, host, r)
	if got := h.raised(t); !slices.Equal(got, []string{"host.os_health", "host.reboot_pending"}) {
		t.Fatalf("raised %v", got)
	}
}

// What a problem says about which checks, from the catalogue and never the
// report, in the order Findings gives them.
func TestNamingTheFindings(t *testing.T) {
	warn := func(id string) hosttune.Result { return check(id, hosttune.Safe, hosttune.Warn, false) }
	fail := func(id string) hosttune.Result { return check(id, hosttune.Safe, hosttune.Error, false) }
	cases := []struct {
		name string
		in   []hosttune.Result
		want string
	}{
		{"one", []hosttune.Result{warn("inotify.watches")}, "File watches"},
		{"a check that could not run says so", []hosttune.Result{fail("docker.logs")}, "Docker log rotation (could not run)"},
		{"two", []hosttune.Result{warn("inotify.watches"), warn("disk.space")}, "File watches and Work directory free space"},
		{"three are all named", []hosttune.Result{warn("inotify.watches"), warn("disk.space"), warn("docker.logs")},
			"File watches, Work directory free space and Docker log rotation"},
		{"the rest are counted", []hosttune.Result{warn("inotify.watches"), warn("disk.space"), warn("docker.logs"), warn("disk.inodes")},
			"File watches, Work directory free space, Docker log rotation and 1 more"},
		{"an id nothing here knows is counted and never named", []hosttune.Result{warn("made.up"), warn("inotify.watches")},
			"File watches and 1 more"},
		{"unknown ids are skipped when naming, so they do not use up the three", []hosttune.Result{
			warn("a.b"), warn("c.d"), warn("inotify.watches"), warn("disk.space"), warn("docker.logs")},
			"File watches, Work directory free space, Docker log rotation and 2 more"},
		{"none known", []hosttune.Result{warn("a.b")}, "1 check this controller does not recognise"},
		{"none known, several", []hosttune.Result{warn("a.b"), fail("c.d")}, "2 checks this controller does not recognise"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := nameFindings(tc.in); got != tc.want {
				t.Errorf("nameFindings = %q, want %q", got, tc.want)
			}
		})
	}
}

// The three are the fleet's, and they never reach the public status page: they
// say whether a machine's settings match a recommendation, not whether a job
// will run, and a stock fleet carries some of them for ever. Were they on it, the
// page would read "degraded" for people with no account over a sysctl, and
// "blocked" over a check that could not read a file.
func TestTheOSHealthProblemsNeverMoveThePublicStatus(t *testing.T) {
	for _, code := range osHealthCodes {
		if audienceFor(code) != AudienceFleet {
			t.Errorf("%s is %q, want the fleet's", code, audienceFor(code))
		}
		if !statusExempt(code) {
			t.Errorf("%s is not exempt from the status page", code)
		}
		if _, has := publicSentences[code]; has {
			t.Errorf("%s has a public sentence it can never show", code)
		}
	}

	h := newHarness(t)
	host := h.host("noisy")
	r := report(h.c.Now().Add(-time.Hour), check("docker.logs", hosttune.Safe, hosttune.Error, false))
	r.RebootPending = true
	h.reports(t, host, r)

	ps, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	if got := h.raised(t); !slices.Equal(got, osHealthCodes) {
		t.Fatalf("raised %v, want all three, or the rest of this proves nothing", got)
	}
	var sawError bool
	for _, p := range ps {
		sawError = sawError || (p.Code == "host.os_health" && p.Severity == config.SeverityError)
	}
	if !sawError {
		t.Fatal("no error-severity host.os_health, so this does not exercise the case that would turn the page to blocked")
	}
	st := ProjectStatus(ps, nil)
	if st.State != FleetHealthy || len(st.Reasons) != 0 || len(st.Explanations) != 0 {
		t.Fatalf("status = %+v, want healthy with no reasons", st)
	}
	body, _ := json.Marshal(st)
	if strings.Contains(string(body), "host.os_health") || strings.Contains(string(body), "noisy") {
		t.Errorf("the status carries an OS health problem: %s", body)
	}

	// And they do not hide a real problem beside them.
	st = ProjectStatus([]Problem{
		{Code: "host.os_health", Severity: config.SeverityError, Audience: AudienceFleet},
		{Code: "host.unhealthy", Severity: config.SeverityWarning, Audience: AudienceFleet},
	}, nil)
	if st.State != FleetDegraded || len(st.Reasons) != 1 || st.Reasons[0].Code != "host.unhealthy" {
		t.Errorf("status = %+v, want degraded by the host alone", st)
	}
}

package controller

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// A host given more slots than its machine has cores, or than its memory has
// 2 GB slots, is the shape the owner's report described: eight runners each
// promised a share under a core, and a daemon that stops answering. The
// warning names the machine, the capacity and the share each runner gets, and
// the fix names the largest capacity that would fit.
func TestAnOverprovisionedHostIsNamedWithTheCapacityThatFits(t *testing.T) {
	h := newHarness(t)
	// Four cores less the half-core floor is 3.5, so three slots fit; the
	// memory would take seven. Eight slots is more than either.
	host := h.measuredHost("crowded", 4, 16384, 8, enforcesEverything)

	p := h.problem(t, "host.overprovisioned")
	if p.Severity != config.SeverityWarning || p.TargetKind != "host" || p.TargetID != host.ID {
		t.Fatalf("problem = %+v; want a warning pointing at the host", p)
	}
	for _, want := range []string{"crowded", "capacity 8", "3.5 allocatable CPUs", "4 CPUs", "default share is 0.43 CPUs", "1945 MB"} {
		if !strings.Contains(p.Detail, want) {
			t.Errorf("detail %q does not say %q", p.Detail, want)
		}
	}
	if !strings.Contains(p.Fix, "capacity to 3") || !strings.Contains(p.Fix, host.ID) {
		t.Errorf("fix %q does not name the capacity that fits and where to set it", p.Fix)
	}
	if strings.Contains(p.Fix, "too small") {
		t.Errorf("fix %q calls a machine that fits three runners too small", p.Fix)
	}

	// With defaults off the runners are not merely small: nothing limits
	// them at all, which is the shape that stops Docker answering, and the
	// detail has to say so rather than quote a share nobody is given.
	h.c.UpdateConfig(func(cfg *config.Config) { cfg.Scheduler.DefaultRunnerLimits = false })
	p = h.problem(t, "host.overprovisioned")
	if !strings.Contains(p.Detail, "nothing limits its runners") || strings.Contains(p.Detail, "default share") {
		t.Errorf("with defaults off the detail is %q", p.Detail)
	}
}

// When even one runner would not fit -- under a core, or under 2 GB, after
// the reserve -- lowering the capacity is not the whole answer, and the fix
// says the machine is too small rather than pretending a capacity of one is.
// The named capacity still never goes below one: zero is a cordon, and the
// operator has a cordon.
func TestAHostTooSmallForOneRunnerIsToldSo(t *testing.T) {
	h := newHarness(t)
	// One core less the half-core floor leaves half a core, and 2 GB less
	// the 512 MB floor leaves 1536 MB: neither is a runner's worth.
	h.measuredHost("tiny", 1, 2048, 2, enforcesEverything)

	p := h.problem(t, "host.overprovisioned")
	if !strings.Contains(p.Fix, "too small") || !strings.Contains(p.Fix, "capacity to 1") {
		t.Errorf("fix %q should say the machine is too small and still name capacity 1", p.Fix)
	}
}

// The warning is about hosts that do not fit, and only those: a host whose
// slots fit its cores and its memory raises nothing, a cordoned host is
// somebody's problem already, and the demo fleet is sized so that none of
// its hosts trips it.
func TestAHostWhoseSlotsFitRaisesNoOverprovisioningWarning(t *testing.T) {
	h := newHarness(t)
	h.host("roomy")
	h.measuredHost("exact", 4, 8192, 3, enforcesEverything)
	crowded := h.measuredHost("crowded-but-cordoned", 4, 16384, 8, enforcesEverything)
	if err := h.st.SetHostCordoned(h.ctx, crowded.ID, true); err != nil {
		t.Fatal(err)
	}
	if codes := h.problemCodes(); contains(codes, "host.overprovisioned") {
		t.Fatalf("problems = %v; every uncordoned host here fits", codes)
	}

	demo := newHarness(t)
	if err := demo.c.SeedDemo(demo.ctx); err != nil {
		t.Fatalf("SeedDemo: %v", err)
	}
	// The demo seeds no OS report, and a host with none raises none of the three
	// OS health codes.
	for _, code := range []string{"host.overprovisioned", "host.limits_unverified", "host.limits_unenforceable", "host.resources_unknown",
		"host.os_health", "host.health_stale", "host.reboot_pending"} {
		if contains(demo.problemCodes(), code) {
			t.Errorf("the demo fleet raises %s; it exists to look like a fleet with nothing wrong", code)
		}
	}
}

// A daemon that has said it cannot apply a CPU quota refuses a runner that
// asks for one, so a pool with an explicit limit fails every create there
// and the default is withheld. The fix is the cgroup delegation a rootless
// daemon needs, spelled out.
func TestADaemonThatCannotApplyLimitsIsAWarningWithTheDelegationFix(t *testing.T) {
	h := newHarness(t)
	host := h.measuredHost("userns", 8, 16384, 4, store.LimitSupport{Known: true, CPU: false, Memory: true, Pids: true})
	// The probe says rootless, which picks the drop-in fix.
	host.BackendInfo[0].Rootless = true
	if err := h.st.SetHostReported(h.ctx, host); err != nil {
		t.Fatal(err)
	}

	p := h.problem(t, "host.limits_unenforceable")
	if p.Severity != config.SeverityWarning || p.TargetID != host.ID {
		t.Fatalf("problem = %+v", p)
	}
	if !strings.Contains(p.Detail, "rootless docker daemon on userns") || !strings.Contains(p.Detail, "CPU quota") || strings.Contains(p.Detail, "memory limit") {
		t.Errorf("detail %q should name the daemon and the one limit it cannot apply", p.Detail)
	}
	if !strings.Contains(p.Fix, "Delegate=cpu cpuset io memory pids") {
		t.Errorf("fix %q does not name the systemd delegation", p.Fix)
	}
	if contains(h.problemCodes(), "host.limits_unverified") {
		t.Error("a daemon that answered the probe is also reported as not having answered")
	}
}

// An agent too old to ask its daemon about limits is read as "default
// nothing", which is what every host did before defaults existed. That is
// worth a note while defaults are on, because it is the one reason a pool
// with no limits is still running unlimited there; with defaults off nothing
// is different about the host and there is nothing to say.
func TestAnUnverifiedProbeIsANoteOnlyWhileDefaultsAreOn(t *testing.T) {
	h := newHarness(t)
	h.measuredHost("old-probe", 8, 16384, 4, store.LimitSupport{})

	p := h.problem(t, "host.limits_unverified")
	if p.Severity != config.SeverityInfo || !strings.Contains(p.Detail, "old-probe") || !strings.Contains(p.Detail, "no default") {
		t.Fatalf("problem = %+v", p)
	}
	h.c.UpdateConfig(func(cfg *config.Config) { cfg.Scheduler.DefaultRunnerLimits = false })
	if contains(h.problemCodes(), "host.limits_unverified") {
		t.Error("with defaults off an unverified probe changes nothing and should say nothing")
	}
}

// A host with room to spare in every dimension and a daemon that can apply
// everything is the host the resource model was written for, and it raises
// none of the model's problems: the drawer is for the three things wrong
// among the twenty that are right.
func TestAFullyInQuotaHostRaisesNoResourceProblem(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	pool.MinRunners = 4
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	h.measuredHost("well-sized", 16, 65536, 4, enforcesEverything)
	// Registration admission may defer demand to the next pass. Fill the
	// host before checking its resource accounting, without depending on
	// how quickly the fake GitHub answers detached credential requests.
	for range pool.MinRunners {
		if err := h.c.Reconcile(h.ctx); err != nil {
			t.Fatal(err)
		}
		h.c.lifecycleCalls.Wait()
		if len(h.runners()) == pool.MinRunners {
			break
		}
	}
	if got := len(h.runners()); got != 4 {
		t.Fatalf("created %d runners, want the host full at 4", got)
	}
	for _, code := range h.problemCodes() {
		if strings.HasPrefix(code, "host.") {
			t.Errorf("a full, in-quota host raised %s", code)
		}
	}
}

// A docker-in-docker slot is two containers whatever the pool typed, and the
// machine has to be sized for both either way.
//
// This is the host from the report that started the work: twelve slots' worth
// of cores on paper, every one of them a pair in practice, a Hosts page reading
// half committed, and a daemon that stopped answering creates. A pool that
// typed its own figures was always charged for the sidecar a second time; a
// pool sized by its host used to be let off the count entirely, on the theory
// that the pair splitting one slot between them made a slot worth one runner
// like everybody else's -- but stability over performance means each half of
// that split still has to be a runner's worth, not half of one, so an
// automatic pool now makes a slot a pair too. See scheduler.ShareFloor for the
// other half of that: a slot too thin for the split is refused outright rather
// than merely counted here.
func TestADockerInDockerPoolMakesEachSlotAPairInTheOverprovisioningCount(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	// Eight cores less the floor is 7.5, so six plain runners fit and this
	// host raises nothing at all.
	h.measuredHost("builders", 8, 32768, 6, enforcesEverything)
	if codes := h.problemCodes(); contains(codes, "host.overprovisioned") {
		t.Fatalf("problems = %v; six plain slots fit this machine", codes)
	}

	p := h.pool(inst, "dind-builders")
	p.DockerMode = store.DockerDinD
	if err := h.st.UpdatePool(h.ctx, p); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	// Sized by its host: the pair still splits one slot between them, but
	// stability over performance means each half of that slot has to clear a
	// runner's own comfortable floor, and six slots of 7.5 allocatable cores
	// does not.
	auto := h.problem(t, "host.overprovisioned")
	for _, want := range []string{"dind-builders", "docker in docker", "two containers", "without limits of its own"} {
		if !strings.Contains(auto.Detail, want) {
			t.Errorf("detail %q does not mention %q", auto.Detail, want)
		}
	}
	if strings.Contains(auto.Detail, "each given what the pool asked for") {
		t.Errorf("detail %q describes a typed charge for a pool that set none", auto.Detail)
	}
	// 7.5 cores in pairs is three, and 31.5 GB in pairs of 2 GB slots is
	// seven: the cores run out first, as they did on the real host, and the
	// same figure applies whether or not the pool typed its own limits --
	// the fix is the same slot count either way.
	if !strings.Contains(auto.Fix, "capacity to 3") {
		t.Errorf("fix %q does not name the capacity the pairs fit in", auto.Fix)
	}

	p.Resources = store.Resources{CPUs: 1, MemoryMB: 2048}
	if err := h.st.UpdatePool(h.ctx, p); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}

	got := h.problem(t, "host.overprovisioned")
	for _, want := range []string{"dind-builders", "docker in docker", "two containers", "each given what the pool asked for"} {
		if !strings.Contains(got.Detail, want) {
			t.Errorf("detail %q does not mention %q", got.Detail, want)
		}
	}
	if !strings.Contains(got.Fix, "capacity to 3") {
		t.Errorf("fix %q does not name the capacity the pairs fit in", got.Fix)
	}
}

// The count follows the pools, not the host alone: a dind pool that cannot
// place here says nothing about how big a slot on this host is. A pool for
// another platform is the case an operator hits first -- one arm64 dind pool
// should not re-size every amd64 host in the fleet.
func TestAPoolThatCannotPlaceHereDoesNotMakeItsSlotsPairs(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	h.measuredHost("builders", 8, 32768, 6, enforcesEverything)

	p := h.pool(inst, "dind-arm")
	p.DockerMode = store.DockerDinD
	p.HostSelector = store.StringMap{"arch": "arm64"}
	if err := h.st.UpdatePool(h.ctx, p); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}

	if codes := h.problemCodes(); contains(codes, "host.overprovisioned") {
		t.Fatalf("problems = %v; the dind pool cannot place on an amd64 host", codes)
	}
}

// agent.capacity is read when the embedded host first enrols and not again, so a
// single-VM operator who is sent to edit it and restart finds the warning unchanged.
// The fix names what does move an enrolled host's capacity, and no setting is
// offered as the place to change it.
func TestTheEmbeddedHostsCapacityWarningDoesNotSendAnOperatorToASettingThatDoesNothing(t *testing.T) {
	host := &store.Host{
		ID: "host_embedded", Name: "controller", Embedded: true, Capacity: 8, CPUs: 4, MemoryMB: 16384,
		Backends: store.StringSlice{"docker"},
	}
	p, ok := overprovisionedProblem(host, nil, true)
	if !ok {
		t.Fatal("eight slots on four cores must be warned about")
	}
	if p.Setting != "" {
		t.Errorf("the warning offers the setting %q, which does nothing once the host has enrolled", p.Setting)
	}
	if strings.Contains(p.Fix, "zoomies.yaml") || !strings.Contains(p.Fix, "zoomies hosts edit host_embedded --capacity 2") {
		t.Errorf("the fix must name the command that changes an enrolled host's capacity: %q", p.Fix)
	}
}

// The scheduler divides a docker-in-docker pair's slot by the pool's own shares and charges a
// minimum to both halves, so the warning counts the same slot. Two flat containers said
// "lower to 3" for a sidecar given 70% of the CPU, which still left the pool no room on a
// 4-slot host, and stayed silent where a 3 GB minimum had made every slot 6 GB.
func TestAnAutomaticDockerInDockerPoolsOwnSlotDecidesTheOverprovisionedCapacity(t *testing.T) {
	tests := []struct {
		name     string
		res      store.Resources
		capacity int
		want     string // the capacity the fix names; "" means no warning
	}{
		{"an even split asks two cores a slot", store.Resources{}, 4, "capacity to 3"},
		{"a sidecar given 70% of the CPU asks more of the slot", store.Resources{DaemonCPUSharePercent: 70, DaemonMemorySharePercent: 50}, 4, "capacity to 2"},
		{"a 3 GB minimum a container makes every slot 6 GB", store.Resources{MinMemoryMB: 3072}, 3, "capacity to 2"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			h.measuredHost("big", 8, 16384, tc.capacity, enforcesEverything)
			p := h.pool(h.installation(), "builders")
			p.DockerMode = store.DockerDinD
			p.Resources = tc.res
			if err := h.st.UpdatePool(h.ctx, p); err != nil {
				t.Fatal(err)
			}
			got := h.problemOrNil("host.overprovisioned")
			if got == nil {
				t.Fatalf("no warning at capacity %d", tc.capacity)
			}
			if !strings.Contains(got.Fix, tc.want) {
				t.Errorf("fix %q does not say %q", got.Fix, tc.want)
			}
		})
	}
}

package controller

import (
	"context"

	"github.com/eyupio/zoomies/internal/store"
)

// RecheckHostPriority recomputes what a host's specs currently rank it at and
// republishes the card for it.
//
// There is nothing stored to recompute against: the priority is read back out
// of the reported specs, which every heartbeat re-measures, so the score is
// always the machine's current one and an upgrade the host ever has is
// re-placed on its own with the next report after it. What this forces is the
// frame at once, for the UI's re-check button, and a nudge so the next pass
// places against the figure now on the card rather than by whatever the last
// one carried.
func (c *Controller) RecheckHostPriority(ctx context.Context, hostID string) (store.Host, error) {
	h, err := c.st.GetHost(ctx, hostID)
	if err != nil {
		return store.Host{}, err
	}
	c.publishHost(h)
	c.Nudge()
	return *h, nil
}

package controller

import (
	"testing"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
)

// The speed figures are what a host's priority is scored from, so a heartbeat
// that reports new ones lands them and then republishes the host: the card
// carries the score it was worked out from, and it is One renderer's answer,
// not a stale row.
func TestAHeartbeatWithNewSpeedFiguresRecordsAndRepublishesThem(t *testing.T) {
	h := newHarness(t)
	tr := h.c.EmbeddedTransport()

	resp, err := tr.Join(h.ctx, agent.JoinRequest{
		ProtocolVersion: agent.ProtocolVersion,
		Name:            "builder-1",
		Capacity:        4,
		OS:              "linux",
		Arch:            "amd64",
		Backends:        []backend.Info{{Kind: store.BackendDocker, Available: true, Version: "27.1.1"}},
	})
	if err != nil {
		t.Fatalf("Join: %v", err)
	}
	tr.SetCredentials(resp.HostID, resp.AgentToken)

	if _, err := tr.Heartbeat(h.ctx, agent.HeartbeatRequest{
		ProtocolVersion: agent.ProtocolVersion,
		Capacity:        4,
		CPUs:            8,
		MemoryMB:        16 * 1024,
		CPUMHz:          2900,
		MemoryMTs:       2133,
		DiskKind:        "hdd",
		Backends:        []backend.Info{{Kind: store.BackendDocker, Available: true, Version: "27.1.1"}},
	}); err != nil {
		t.Fatalf("Heartbeat: %v", err)
	}

	host, err := h.st.GetHost(h.ctx, resp.HostID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if host.CPUMHz != 2900 || host.MemoryMTs != 2133 || host.DiskKind != "hdd" {
		t.Errorf("host = clock %d mhz, %d MT/s, %q of disk, want what the agent reported",
			host.CPUMHz, host.MemoryMTs, host.DiskKind)
	}
	view := h.c.HostView(host)
	if view.Priority == 0 {
		t.Errorf("the card reads priority %d from a host with specs, want the score", view.Priority)
	}
	if got := view.PrioritySource; got != "computed" {
		t.Errorf("PrioritySource = %q, want computed", got)
	}

	// An upgrade that leaves the figures alone changes nothing: a heartbeat
	// that repeats the same figures rewrites nothing, and the score stays
	// what the machine earns.
	before := h.c.HostView(host)
	if _, err := tr.Heartbeat(h.ctx, agent.HeartbeatRequest{
		ProtocolVersion: agent.ProtocolVersion,
		Capacity:        4,
		CPUs:            8,
		MemoryMB:        16 * 1024,
		CPUMHz:          2900,
		MemoryMTs:       2133,
		DiskKind:        "hdd",
	}); err != nil {
		t.Fatalf("repeated Heartbeat: %v", err)
	}
	after := h.c.HostView(host)
	if after.Priority != before.Priority {
		t.Errorf("the priority moved from %d to %d on a friendly band", before.Priority, after.Priority)
	}
}

// A pin is the operator's: a heartbeat, join and re-join all leave it, and a
// rebuilt machine reclaiming its row keeps it the way it keeps its labels.
func TestAHeartbeatAndARejoinLeaveThePinAlone(t *testing.T) {
	h := newHarness(t)
	tr := h.c.EmbeddedTransport()

	resp, err := tr.Join(h.ctx, agent.JoinRequest{
		ProtocolVersion: agent.ProtocolVersion,
		Name:            "builder-1",
		Capacity:        4,
		OS:              "linux",
		Arch:            "amd64",
	})
	if err != nil {
		t.Fatalf("Join: %v", err)
	}
	tr.SetCredentials(resp.HostID, resp.AgentToken)
	pin := 90
	if err := h.st.PatchHost(h.ctx, resp.HostID, store.HostChanges{PriorityOverride: &pin}); err != nil {
		t.Fatalf("PatchHost: %v", err)
	}

	if _, err := tr.Heartbeat(h.ctx, agent.HeartbeatRequest{
		ProtocolVersion: agent.ProtocolVersion,
		Capacity:        4,
		CPUs:            8,
		CPUMHz:          1000,
	}); err != nil {
		t.Fatalf("Heartbeat: %v", err)
	}

	// The agent re-joined: the row is fresh, and the pin must survive it.
	rejoined := joinRequest("builder-1", h.joinToken(t, nil, 0))
	rejoined.PreviousToken = resp.AgentToken
	rejoined.PreviousHostID = resp.HostID
	second, err := h.c.Join(h.ctx, rejoined, "10.0.0.9")
	if err != nil {
		t.Fatalf("re-join: %v", err)
	}
	if second.HostID != resp.HostID {
		t.Fatalf("re-joined, got %s; want the row reclaimed", second.HostID)
	}

	got, err := h.st.GetHost(h.ctx, second.HostID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if got.PriorityOverride == nil || *got.PriorityOverride != 90 {
		t.Errorf("the pin did not survive a re-join: %+v", got.PriorityOverride)
	}
	view := h.c.HostView(got)
	if view.PrioritySource != "overridden" || view.Priority != 90 {
		t.Errorf("the card reads %d from %q after the re-join, want the operator's 90", view.Priority, view.PrioritySource)
	}
}

package controller

import "context"

// RetireRecoveryHost fences even a queue held by a request authenticated before
// retirement. Unfence cannot resume delivery until this queue has been sealed.
func (c *Controller) RetireRecoveryHost(ctx context.Context, id, confirm, actor string) error {
	c.recoveryMu.Lock()
	defer c.recoveryMu.Unlock()
	if err := c.st.RetireRecoveryHost(ctx, id, confirm, actor); err != nil {
		return err
	}
	q := c.queues.get(id)
	q.mu.Lock()
	q.retired = true
	q.pending = nil
	clear(q.inflight)
	q.mu.Unlock()
	c.hostChecks.forget(id)
	c.dropMemoryState(id)
	return nil
}

package controller

import (
	"context"
	"errors"
	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

func TestTransferredHostReenrolmentProvesOwnershipAndKeepsHistory(t *testing.T) {
	now := time.Date(2026, 10, 13, 12, 0, 0, 0, time.UTC)
	h := newHarnessAt(t, func() time.Time { return now })
	first, err := h.c.Join(h.ctx, joinRequest("recovered", h.joinToken(t, nil, 0)), "10.0.0.3")
	if err != nil {
		t.Fatal(err)
	}
	host, err := h.st.GetHost(h.ctx, first.HostID)
	if err != nil {
		t.Fatal(err)
	}
	inst := h.installation()
	pool := h.pool(inst, "history")
	runner := h.runnerRow(pool, host, store.RunnerRemoved)
	if err := h.st.MarkTransferredHosts(h.ctx); err != nil {
		t.Fatal(err)
	}
	if err := h.st.SetRecoveryFence(h.ctx, true, "transfer"); err != nil {
		t.Fatal(err)
	}
	if err := h.c.LoadFence(h.ctx); err != nil {
		t.Fatal(err)
	}
	if err := h.c.Unfence(h.ctx); !errors.Is(err, store.ErrConflict) {
		t.Fatalf("unresolved host: %v", err)
	}
	req := joinRequest("recovered", h.joinToken(t, nil, 0))
	req.PreviousHostID = first.HostID
	if _, err := h.c.Join(h.ctx, req, "10.0.0.3"); err == nil {
		t.Fatal("join token claimed imported host without ownership proof")
	}
	req.PreviousToken = first.AgentToken
	second, err := h.c.Join(h.ctx, req, "10.0.0.3")
	if err != nil {
		t.Fatal(err)
	}
	if second.HostID != first.HostID {
		t.Fatal("re-enrolment changed historical identity")
	}
	if _, err := h.st.GetRunner(h.ctx, runner.ID); err != nil {
		t.Fatalf("re-enrolment destroyed history: %v", err)
	}
	if err := h.st.CheckHostRecovery(h.ctx); err != nil {
		t.Fatal(err)
	}
	h.c.NoteAgentSession(h.ctx, second.HostID, "a")
	h.c.NoteAgentSession(h.ctx, second.HostID, "b")
	h.c.NoteAgentSession(h.ctx, second.HostID, "a")
	if err := h.c.Unfence(h.ctx); !errors.Is(err, store.ErrConflict) {
		t.Fatalf("duplicate ownership warning ignored: %v", err)
	}
	now = now.Add(time.Hour + time.Minute)
	if _, err := h.c.Heartbeat(h.ctx, second.HostID, agent.HeartbeatRequest{ProtocolVersion: agent.ProtocolVersion, Capacity: 2}); err != nil {
		t.Fatal(err)
	}
	if err := h.c.Unfence(h.ctx); err != nil {
		t.Fatal(err)
	}
}

func TestRetirementNeverDeliversCleanupAndCannotReenrol(t *testing.T) {
	h := newHarness(t)
	first, err := h.c.Join(h.ctx, joinRequest("offline", h.joinToken(t, nil, 0)), "10.0.0.3")
	if err != nil {
		t.Fatal(err)
	}
	if err := h.st.MarkTransferredHosts(h.ctx); err != nil {
		t.Fatal(err)
	}
	if err := h.st.SetRecoveryFence(h.ctx, true, "transfer"); err != nil {
		t.Fatal(err)
	}
	if err := h.c.LoadFence(h.ctx); err != nil {
		t.Fatal(err)
	}
	q := h.c.queues.get(first.HostID)
	q.enqueue(agent.Task{Kind: agent.TaskStopRunner, RunnerID: "run_previous"})
	if err := h.c.RetireRecoveryHost(h.ctx, first.HostID, first.HostID, "administrator"); err != nil {
		t.Fatal(err)
	}
	if q.enqueue(agent.Task{Kind: agent.TaskCreateRunner, RunnerID: "run_new"}) {
		t.Fatal("retired queue accepted work")
	}
	if tasks := q.take(10, h.c.Now()); len(tasks) != 0 {
		t.Fatalf("a request holding the old queue could modify the remote machine: %+v", tasks)
	}
	req := joinRequest("offline", h.joinToken(t, nil, 0))
	req.PreviousHostID = first.HostID
	req.PreviousToken = first.AgentToken
	if _, err := h.c.Join(h.ctx, req, "10.0.0.3"); err == nil {
		t.Fatal("retired host re-enrolled")
	}
	if _, err := h.c.Heartbeat(h.ctx, first.HostID, agent.HeartbeatRequest{}); !errors.Is(err, agent.ErrHostGone) {
		t.Fatalf("retired host heartbeat: %v", err)
	}
	if err := h.c.Unfence(h.ctx); err != nil {
		t.Fatal(err)
	}
	if tasks, err := h.c.PollTasks(h.ctx, first.HostID, 0); !errors.Is(err, agent.ErrHostGone) || tasks != nil {
		t.Fatalf("retirement sent work or cleanup: %+v %v", tasks, err)
	}
	host, err := h.st.GetHost(h.ctx, first.HostID)
	if err != nil {
		t.Fatal(err)
	}
	if host.Available(h.c.Now()) || host.Healthy(h.c.Now()) {
		t.Fatal("retired host became active")
	}
}

func TestRecoveryWaitsForAnInflightTaskPollBeforeRetiring(t *testing.T) {
	now := time.Date(2026, 10, 13, 12, 0, 0, 0, time.UTC)
	var block atomic.Bool
	var enteredOnce sync.Once
	entered, release := make(chan struct{}), make(chan struct{})
	clock := func() time.Time {
		if block.Load() {
			enteredOnce.Do(func() { close(entered) })
			<-release
		}
		return now
	}
	h := newHarnessAt(t, clock)
	joined, err := h.c.Join(h.ctx, joinRequest("polling", h.joinToken(t, nil, 0)), "10.0.0.3")
	if err != nil {
		t.Fatal(err)
	}
	if err := h.st.MarkTransferredHosts(h.ctx); err != nil {
		t.Fatal(err)
	}
	if err := h.st.SetRecoveryFence(h.ctx, true, "transfer"); err != nil {
		t.Fatal(err)
	}
	h.c.queues.get(joined.HostID).enqueue(agent.Task{Kind: agent.TaskStopRunner, RunnerID: "run_previous"})
	block.Store(true)
	pollDone := make(chan struct {
		batch *agent.TaskBatch
		err   error
	}, 1)
	go func() {
		batch, err := h.c.PollTasks(h.ctx, joined.HostID, 0)
		pollDone <- struct {
			batch *agent.TaskBatch
			err   error
		}{batch, err}
	}()
	<-entered
	// The fence rides into the controller only now, with the poll already
	// admitted: the recovery row is written before the block goes on, and
	// this is the read that activates it, so nothing in it answers the
	// clock. A poll admitted before the fence is the ordering the
	// serialisation is for; with the fence in memory before the poll began,
	// PollTasks would return at mayAct before it reached the clock and the
	// hook above would never fire.
	if err := h.c.LoadFence(h.ctx); err != nil {
		t.Fatal(err)
	}
	retireDone := make(chan error, 1)
	go func() {
		retireDone <- h.c.RetireRecoveryHost(h.ctx, joined.HostID, joined.HostID, "administrator")
	}()
	select {
	case err := <-retireDone:
		t.Fatalf("retirement overtook the in-flight task poll: %v", err)
	case <-time.After(50 * time.Millisecond):
	}
	block.Store(false)
	close(release)
	poll := <-pollDone
	if poll.err != nil || poll.batch == nil || len(poll.batch.Tasks) != 1 {
		t.Fatalf("task poll failed: %+v", poll)
	}
	if err := <-retireDone; err != nil {
		t.Fatal(err)
	}
}

// A long poll with nothing to hand over looks at nothing while it waits, so it
// must not keep recovery waiting for the lock. It used to hold the read lock
// through the whole wait, which made every retirement and every lifting of the
// fence wait up to the poll interval, and a writer that is waiting holds every
// other agent call behind it: the heartbeats, results and reports of every host
// stood still for as long.
func TestAnIdleLongPollDoesNotKeepRecoveryWaitingForTheLock(t *testing.T) {
	h := newHarness(t)
	joined, err := h.c.Join(h.ctx, joinRequest("idle", h.joinToken(t, nil, 0)), "10.0.0.3")
	if err != nil {
		t.Fatal(err)
	}
	pollCtx, stop := context.WithCancel(h.ctx)
	pollDone := make(chan error, 1)
	go func() {
		_, err := h.c.PollTasks(pollCtx, joined.HostID, agent.DefaultPollWait)
		pollDone <- err
	}()
	t.Cleanup(func() { stop(); <-pollDone })

	eventually(t, 5*time.Second, "the poll to be admitted", func() bool { return h.c.pollsInFlight.Load() == 1 })
	eventually(t, 2*time.Second, "recovery to be able to take the lock while the poll waits", func() bool {
		if !h.c.recoveryMu.TryLock() {
			return false
		}
		h.c.recoveryMu.Unlock()
		return true
	})
}

// What a poll does once it wakes is an observation like any other: it takes
// tasks off the queue, and a retirement must not commit in the middle of it.
// Only the wait is outside the lock. The clock holds the poll inside its second
// look at the queue, which is where the lock has to be held again.
func TestAPollThatHasWokenHoldsTheRecoveryLockWhileItTakesItsTasks(t *testing.T) {
	var block atomic.Bool
	var enteredOnce sync.Once
	entered, release := make(chan struct{}), make(chan struct{})
	clock := func() time.Time {
		if block.Load() {
			enteredOnce.Do(func() { close(entered) })
			<-release
		}
		return time.Date(2026, 10, 13, 12, 0, 0, 0, time.UTC)
	}
	h := newHarnessAt(t, clock)
	joined, err := h.c.Join(h.ctx, joinRequest("waking", h.joinToken(t, nil, 0)), "10.0.0.3")
	if err != nil {
		t.Fatal(err)
	}
	type polled struct {
		batch *agent.TaskBatch
		err   error
	}
	pollDone := make(chan polled, 1)
	go func() {
		batch, err := h.c.PollTasks(h.ctx, joined.HostID, agent.DefaultPollWait)
		pollDone <- polled{batch, err}
	}()
	eventually(t, 5*time.Second, "the poll to be admitted", func() bool { return h.c.pollsInFlight.Load() == 1 })
	eventually(t, 2*time.Second, "the poll to be waiting with the lock let go", func() bool {
		if !h.c.recoveryMu.TryLock() {
			return false
		}
		h.c.recoveryMu.Unlock()
		return true
	})

	block.Store(true)
	h.c.queues.get(joined.HostID).enqueue(agent.Task{Kind: agent.TaskStopRunner, RunnerID: "run_previous"})
	select {
	case <-entered:
	case <-time.After(5 * time.Second):
		t.Fatal("the task did not wake the poll into its second look at the queue")
	}
	if h.c.recoveryMu.TryLock() {
		h.c.recoveryMu.Unlock()
		t.Error("recovery could take the lock while the woken poll was taking its tasks")
	}

	block.Store(false)
	close(release)
	poll := <-pollDone
	if poll.err != nil || poll.batch == nil || len(poll.batch.Tasks) != 1 {
		t.Fatalf("the woken poll returned %+v, want the one task that woke it", poll)
	}
}

func TestAgentReportsWaitForRecoveryRetirementLock(t *testing.T) {
	h := newHarness(t)
	joined, err := h.c.Join(h.ctx, joinRequest("reporting", h.joinToken(t, nil, 0)), "10.0.0.3")
	if err != nil {
		t.Fatal(err)
	}
	h.c.recoveryMu.Lock()
	resultDone := make(chan error, 1)
	go func() {
		resultDone <- h.c.ReportResult(h.ctx, joined.HostID, agent.TaskResult{})
	}()
	runnersDone := make(chan error, 1)
	go func() {
		runnersDone <- h.c.ReportRunners(h.ctx, joined.HostID, nil)
	}()
	select {
	case err := <-resultDone:
		t.Fatalf("task result crossed the recovery lock: %v", err)
	case err := <-runnersDone:
		t.Fatalf("runner report crossed the recovery lock: %v", err)
	case <-time.After(50 * time.Millisecond):
	}
	h.c.recoveryMu.Unlock()
	if err := <-resultDone; err != nil {
		t.Fatal(err)
	}
	if err := <-runnersDone; err != nil {
		t.Fatal(err)
	}
}

func TestRetiredHostDoesNotCauseAutomaticMachineRelease(t *testing.T) {
	p := demandProvider("lab")
	pool := demandPool("alpha")
	host := demandHost("host_1", 2, 0)
	host.LastHeartbeat = machineNow.Add(-24 * time.Hour)
	m := demandMachine("mach_1", p, store.MachineReady, 48*time.Hour)
	m.HostID = host.ID
	m.IdleSince = ptrTime(machineNow.Add(-24 * time.Hour))
	s := MachineSnapshot{Now: machineNow, Pools: []*store.Pool{pool}, Hosts: []*store.Host{host}, Providers: []*store.Provider{p}, Machines: []*store.Machine{m}, Limits: demandLimits(), Plan: scheduler.Plan{Pools: []scheduler.PoolPlan{demandPoolPlan(pool, 0, 0, 0, "")}}}
	if got := planFor(t, DecideMachines(s), p.ID); len(got.Drain) != 1 {
