	}
	host.Retired = true
	if got := planFor(t, DecideMachines(s), p.ID); len(got.Drain) != 0 {
		t.Fatalf("retirement would modify remote machine: %+v", got)
	}
}

func TestRecoveryWaitsForAnInflightHeartbeatBeforeRetiringOrResuming(t *testing.T) {
	now := time.Date(2026, 10, 13, 12, 0, 0, 0, time.UTC)
	var block atomic.Bool
	var enteredOnce sync.Once
	entered, release := make(chan struct{}), make(chan struct{})
	clock := func() time.Time {
		if block.Load() {
			enteredOnce.Do(func() { close(entered) })
			<-release
		}
		return now
	}
	h := newHarnessAt(t, clock)
	joined, err := h.c.Join(h.ctx, joinRequest("returning", h.joinToken(t, nil, 0)), "10.0.0.3")
	if err != nil {
		t.Fatal(err)
	}
	if err := h.st.MarkTransferredHosts(h.ctx); err != nil {
		t.Fatal(err)
	}
	if err := h.st.SetRecoveryFence(h.ctx, true, "transfer"); err != nil {
		t.Fatal(err)
	}
	if err := h.c.LoadFence(h.ctx); err != nil {
		t.Fatal(err)
	}
	block.Store(true)
	type beatResult struct {
		response *agent.HeartbeatResponse
		err      error
	}
	beatDone := make(chan beatResult, 1)
	go func() {
		response, err := h.c.Heartbeat(h.ctx, joined.HostID, agent.HeartbeatRequest{ProtocolVersion: agent.ProtocolVersion, Capacity: 2})
		beatDone <- beatResult{response, err}
	}()
	<-entered
	retireDone, unfenceDone := make(chan error, 1), make(chan error, 1)
	go func() { retireDone <- h.c.RetireRecoveryHost(h.ctx, joined.HostID, joined.HostID, "administrator") }()
	go func() { unfenceDone <- h.c.Unfence(h.ctx) }()
	select {
	case err := <-retireDone:
		t.Errorf("retirement overtook the returning host's heartbeat: %v", err)
		retireDone <- err
	case err := <-unfenceDone:
		t.Errorf("recovery resumed before the in-flight heartbeat completed: %v", err)
		unfenceDone <- err
	case <-time.After(50 * time.Millisecond):
	}
	block.Store(false)
	close(release)
	beat := <-beatDone
	if beat.err != nil || beat.response == nil || !beat.response.MutationsPaused || len(beat.response.UnknownRunners) != 0 {
		t.Fatalf("in-flight response authorised work or cleanup: %+v %v", beat.response, beat.err)
	}
	if err := <-retireDone; !errors.Is(err, store.ErrConflict) {
		t.Fatalf("a returning host was retired: %v", err)
	}
	if err := <-unfenceDone; err != nil {
		t.Fatal(err)
	}
}

package controller

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// An operator can see what a host is and what is left on it; without this they
// could not see what the fleet has already promised away, which is the number
// that explains a host with free slots taking nothing.
//
// It is the scheduler's own sum rather than a second one computed for the page:
// a figure on screen that disagreed with the one the pass placed against would
// be worse than no figure, because it would be believed.
func TestTheHostViewCarriesWhatTheFleetHasPromisedAway(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	pool.Resources = store.Resources{CPUs: 2, MemoryMB: 4096}
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	host := h.host("vm-1")
	h.runnerRow(pool, host, store.RunnerIdle)
	h.runnerRow(pool, host, store.RunnerBusy)
	// A failed runner is not charged for, exactly as it does not hold a slot.
	failed := h.runnerRow(pool, host, store.RunnerIdle)
	if _, err := h.st.TransitionRunner(h.ctx, failed.ID, store.RunnerFailed, "failed"); err != nil {
		t.Fatalf("TransitionRunner: %v", err)
	}

	// Before a pass has run there is no answer, and saying zero would read as
	// an idle machine rather than as a question nobody has asked yet.
	if view := h.c.HostView(host); view.ReservedKnown {
		t.Error("a controller that has decided nothing reported a reservation anyway")
	}
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}

	view := h.c.HostView(host)
	if !view.ReservedKnown {
		t.Fatal("a pass has run and the host still reports no reservation")
	}
	if view.ReservedCPUs != 4 || view.ReservedMemoryMB != 8192 {
		t.Errorf("reserved = %v CPUs / %d MB, want the two live runners' 4 and 8192 (the failed one is not charged)",
			view.ReservedCPUs, view.ReservedMemoryMB)
	}
	if !view.ResourcesKnown {
		t.Error("a host that reported its machine says its resources are unknown")
	}
	// The memory reserve scales with the machine, so a 64 GB host holds back a
	// twentieth rather than the flat floor a small one does.
	if want := int64(64*1024) - (&store.Host{MemoryMB: 64 * 1024}).MemoryReserve(); view.AllocatableMemoryMB != want {
		t.Errorf("allocatable memory = %d, want the machine less its reserve, %d", view.AllocatableMemoryMB, want)
	}
}

// A host whose agent predates the resource fields is placed by slots alone,
// which is what keeps an upgrade from emptying a fleet -- and the page has to
// say so, because a card with every figure missing reads as broken rather than
// as old.
//
// How loudly it says so depends on what the fleet does with a measurement.
// With default limits on, an unmeasured host is the one host whose runners
// get no default -- their share of a machine nobody has measured cannot be
// computed -- so a pool with no limits of its own runs unlimited there, and
// that is a warning. With defaults off nothing is different about the host and
// it stays a note.
func TestAHostThatHasNotMeasuredItselfSaysSo(t *testing.T) {
	h := newHarness(t)
	silent := &store.Host{Name: "old-agent", Capacity: 2, Backends: store.StringSlice{"docker"},
		Labels: store.StringMap{}, OS: "linux", Arch: "amd64", LastHeartbeat: h.c.Now()}
	if err := h.st.CreateHost(h.ctx, silent); err != nil {
		t.Fatalf("CreateHost: %v", err)
	}

	if h.c.HostView(silent).ResourcesKnown {
		t.Error("a host that has reported nothing claims its resources are known")
	}
	for _, tc := range []struct {
		defaults bool
		want     string
		because  string
	}{
		{true, "warning", "its runners are given no default limit, so a pool without limits runs unlimited there"},
		{false, "info", "nothing is wrong with an old agent, it is just unmeasured"},
	} {
		h.c.UpdateConfig(func(cfg *config.Config) { cfg.Scheduler.DefaultRunnerLimits = tc.defaults })
		p := h.problem(t, "host.resources_unknown")
		if !strings.Contains(p.Detail, "old-agent") {
			t.Errorf("the note does not name the host: %q", p.Detail)
		}
		if string(p.Severity) != tc.want {
			t.Errorf("defaults=%v: severity = %q, want %s: %s", tc.defaults, p.Severity, tc.want, tc.because)
		}
		if tc.defaults && !strings.Contains(p.Detail, "no default") {
			t.Errorf("with defaults on the detail does not say the runners get none: %q", p.Detail)
		}
	}
}

// A pool's resources become cgroup limits on the container backends and
// nothing at all on the process backend. The reservation still holds the room,
// so the fleet does not oversubscribe -- but the room is bookkeeping, and
// saying so is the difference between a limit and a wish.
func TestAProcessPoolWithLimitsIsWarnedAbout(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "on-metal")
	pool.Backend = store.BackendProcess
	pool.Resources = store.Resources{MemoryMB: 4096}
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}

	if !contains(h.problemCodes(), "pool.resources_unenforced") {
		t.Fatalf("problems = %v, want pool.resources_unenforced", h.problemCodes())
	}

	// The same pool on a backend that enforces them raises nothing: the
	// warning is about the backend, not about setting limits.
	pool.Backend = store.BackendDocker
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	if contains(h.problemCodes(), "pool.resources_unenforced") {
		t.Errorf("problems = %v; a docker pool enforces its limits and needs no warning", h.problemCodes())
	}
}

// The UI tells two problems apart by code, target and setting, and dismisses
// or snoozes by that identity. Two process pools with limits used to raise two
// problems that shared all three (with no target at all), so muting one pool's
// warning muted the other's and neither got an "Open the pool" link.
func TestTwoProcessPoolsWithLimitsAreTwoProblemsWithTheirOwnTargets(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	want := map[string]string{}
	for _, name := range []string{"on-metal", "on-metal-too"} {
		pool := h.pool(inst, name)
		pool.Backend = store.BackendProcess
		pool.Resources = store.Resources{MemoryMB: 4096}
		if err := h.st.UpdatePool(h.ctx, pool); err != nil {
			t.Fatalf("UpdatePool: %v", err)
		}
		want[pool.ID] = name
	}

	ps, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	seen := map[string]bool{}
	for _, p := range ps {
		if p.Code != "pool.resources_unenforced" {
			continue
		}
		name, ok := want[p.TargetID]
		if !ok || p.TargetKind != "pool" {
			t.Errorf("problem targets %s %q, want one of the pools %v", p.TargetKind, p.TargetID, want)
			continue
		}
		if seen[p.TargetID] {
			t.Errorf("two problems target pool %s", p.TargetID)
		}
		seen[p.TargetID] = true
		if !strings.Contains(p.Title, name) {
			t.Errorf("title %q does not name pool %s, so the drawer cannot tell its rows apart", p.Title, name)
		}
	}
	if len(seen) != len(want) {
		t.Errorf("problems cover pools %v, want %v", seen, want)
	}
}

// A host whose docker and podman daemons both have something wrong raises one
// problem per backend for the same host. The UI keys a drawer row by code,
// target and title, so the titles have to differ or the two rows collide.
func TestAHostWithTwoAffectedBackendsRaisesProblemsWithDistinctTitles(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	for _, kind := range []store.BackendKind{store.BackendDocker, store.BackendPodman} {
		p := h.pool(inst, "cached-"+string(kind))
		p.Backend = kind
		p.Cache = store.CacheConfig{Enabled: true, Tools: true, Scope: store.CacheScopePool}
		if err := h.st.UpdatePool(h.ctx, p); err != nil {
			t.Fatalf("UpdatePool: %v", err)
		}
	}
	limits := store.LimitSupport{Known: true, CPU: false, Memory: true, Pids: true}
	host := h.measuredHost("both", 16, 65536, 4, limits)
	host.Backends = store.StringSlice{"docker", "podman"}
	host.BackendInfo = store.HostBackends{
		{Kind: store.BackendDocker, Available: true, SharedFolder: "the shared folder is not mounted", Limits: limits},
		{Kind: store.BackendPodman, Available: true, SharedFolder: "the shared folder is not mounted", Limits: limits},
	}
	if err := h.st.SetHostReported(h.ctx, host); err != nil {
		t.Fatal(err)
	}

	ps, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	for _, code := range []string{"host.limits_unenforceable", "host.shared_folder_unmounted"} {
		titles := map[string]bool{}
		n := 0
		for _, p := range ps {
			if p.Code == code {
				n++
				titles[p.Title] = true
			}
		}
		if n != 2 || len(titles) != 2 {
			t.Errorf("%s: %d problems with %d distinct titles, want two of each", code, n, len(titles))
		}
	}
}

package controller

import (
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// The minute sampler writes one row per host, and a measurement that has
// gone stale is left out of it rather than carried forward. A host that
// stopped reporting would otherwise draw a flat line at its last reading,
// which is what a healthy, quiet machine draws too -- so the two would be
// indistinguishable on the chart the sample exists to feed.
func TestSamplingRecordsEveryHostAndLeavesStaleMeasurementsAsGaps(t *testing.T) {
	h := newHarness(t)
	fresh := h.host("vm-fresh")
	stale := h.host("vm-stale")
	now := h.c.Now()

	cpu, ioWait, load, mem := 72.5, 41.0, 3.2, int64(20_000)
	if err := h.st.SetHostUsage(h.ctx, fresh.ID, store.HostUsage{
		CPUPercent: &cpu, IOWaitPercent: &ioWait, LoadAverage1: &load, MemoryAvailableMB: &mem, SampledAt: now,
	}); err != nil {
		t.Fatalf("SetHostUsage: %v", err)
	}
	old := 99.0
	if err := h.st.SetHostUsage(h.ctx, stale.ID, store.HostUsage{
		CPUPercent: &old, SampledAt: now.Add(-store.HostUsageMaxAge - time.Minute),
	}); err != nil {
		t.Fatalf("SetHostUsage (stale): %v", err)
	}

	if err := h.c.sample(h.ctx); err != nil {
		t.Fatalf("sample: %v", err)
	}
	samples, err := h.st.ListHostSamples(h.ctx, now.Add(-time.Minute), "")
	if err != nil {
		t.Fatalf("ListHostSamples: %v", err)
	}
	if len(samples) != 2 {
		t.Fatalf("samples = %d, want one per host: %+v", len(samples), samples)
	}
	byHost := map[string]store.HostSample{}
	for _, s := range samples {
		byHost[s.HostID] = s
	}
	got := byHost[fresh.ID]
	if got.CPUPercent == nil || *got.CPUPercent != cpu || got.MemoryAvailableMB == nil || *got.MemoryAvailableMB != mem {
		t.Errorf("fresh host sample = %+v, want the measurement it just reported", got)
	}
	if got.IOWaitPercent == nil || *got.IOWaitPercent != ioWait {
		t.Errorf("fresh host sample I/O wait = %v, want %v", got.IOWaitPercent, ioWait)
	}
	if got.Capacity != 4 || got.CPUs != 16 || got.AllocatableCPUs <= 0 {
		t.Errorf("fresh host sample = %+v, want its slots and size carried", got)
	}
	if s := byHost[stale.ID]; s.CPUPercent != nil || s.IOWaitPercent != nil {
		t.Errorf("stale host sample carries CPU %v and I/O wait %v, want gaps", s.CPUPercent, s.IOWaitPercent)
	}
}

func TestPruningHostSamplesFollowsTheSampleRetention(t *testing.T) {
	h := newHarness(t)
	host := h.host("vm-1")
	now := h.c.Now()
	if err := h.st.RecordHostSamples(h.ctx, []store.HostSample{
		{HostID: host.ID, At: now.Add(-48 * time.Hour)},
		{HostID: host.ID, At: now.Add(-time.Hour)},
	}); err != nil {
		t.Fatalf("RecordHostSamples: %v", err)
	}
	h.c.UpdateConfig(func(c *config.Config) {
		c.Retention.Samples = 24 * time.Hour
	})
	h.c.prune(h.ctx)
	left, err := h.st.ListHostSamples(h.ctx, now.Add(-72*time.Hour), "")
	if err != nil {
		t.Fatalf("ListHostSamples: %v", err)
	}
	if len(left) != 1 {
		t.Fatalf("samples after the prune = %d, want the one inside the window", len(left))
	}
}

// The store keys a sample on the minute and the chart draws a point per
// minute, so the sampler has to land in every minute. It used to fire once
// sixty seconds had passed since the last sample, from a thirty-second
// ticker: a tick that arrived a few milliseconds short skipped, the next one
// wrote, and the rows fell ninety seconds apart -- every third minute on the
// capacity map an empty slot. Jitter is a property of every ticker, so the
// passes here are given exactly that jitter.
func TestSamplingLandsInEveryMinuteWhateverTheTickerJitter(t *testing.T) {
	h := newHarness(t)
	host := h.host("vm-1")
	now := h.c.Now()
	// Start 200ms into a minute, then let the second tick come 100ms early,
	// which is all it took to lose a minute.
	first := now.Truncate(time.Minute).Add(time.Minute + 200*time.Millisecond)
	h.advance(first.Sub(now))
	var last housekeeping
	h.c.housekeep(h.ctx, &last)
	for _, d := range []time.Duration{
		30 * time.Second,
		30*time.Second - 100*time.Millisecond,
		30 * time.Second,
		30 * time.Second,
	} {
		h.advance(d)
		h.c.housekeep(h.ctx, &last)
	}

	// Five passes at :00.2, :30.2, :00.1, :30.1 and :00.1 span three minutes,
	// and every one of them wants a row.
	samples, err := h.st.ListHostSamples(h.ctx, first.Add(-time.Minute), host.ID)
	if err != nil {
		t.Fatalf("ListHostSamples: %v", err)
	}
	var minutes []time.Time
	for _, s := range samples {
		minutes = append(minutes, s.At.UTC())
	}
	if len(minutes) != 3 {
		t.Fatalf("sampled minutes = %v, want one row in each of the three minutes the passes covered", minutes)
	}
	for i, at := range minutes {
		if want := first.UTC().Truncate(time.Minute).Add(time.Duration(i) * time.Minute); !at.Equal(want) {
			t.Errorf("sample %d at %v, want %v: a minute was skipped", i, at, want)
		}
	}
}

package controller

import (
	"fmt"
	"strings"

	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/version"
)

// hostUpgrade tells the operator how to align a remote host. An ahead agent
// needs its controller upgraded, never a command that silently downgrades it.
//
// rented is the machine this host is, when Zoomies rents it. A machine gets no
// command, because there is nowhere to run one: nobody logs into a clone, it
// is destroyed once it has been idle, and the machine that replaces it is
// cloned from the template its provider builds from. What an operator does
// instead is prepare that template again, which is where the machine's agent
// comes from, and the sentence says so rather than offering a command that
// would be run on a host that is about to stop existing.
func hostUpgrade(host *store.Host, controllerVersion string, rented rentedHost) (command, target, note string) {
	if host.Embedded {
		return "", "", ""
	}
	skew := version.CompareBuilds(host.Version, controllerVersion)
	if skew == version.SkewNone && !host.Incompatible {
		return "", "", ""
	}
	if skew == version.SkewAhead {
		if rented.rented() {
			return "", "", "This machine runs an agent newer than this controller, which is the direction nothing is tested in. Prepare " +
				"its provider's template from a newer release, or upgrade this controller."
		}
		return "", "", "This agent is newer than the controller. Upgrade the controller first."
	}
	if rented.rented() {
		// The tag is what a setup command would prepare the template from,
		// and it is what the operator has to type; a build that is neither a
		// release nor one from main has none, and says so.
		tag, ok := version.InstallTag(controllerVersion)
		if !ok {
			return "", "", rentedMachineAdvice(rented, "")
		}
		return "", "", rentedMachineAdvice(rented, tag)
	}
	tag, ok := version.InstallTag(controllerVersion)
	if !ok {
		return "", "", fmt.Sprintf("The controller is %s, a local or unpublished build. Install the matching agent from that build; there is no published upgrade command.", controllerVersion)
	}
	quoted := "'" + strings.ReplaceAll(tag, "'", "'\"'\"'") + "'"
	if host.OS == "windows" {
		// Windows has no sudo, and zoomies upgrade replaces a service it finds
		// under systemd or launchd and knows no Windows one, so that command
		// fails there. The installer script is what upgrades an enrolled
		// Windows machine: it stops the service, swaps the binary, keeps the
		// credentials and starts it again, and needs no token to do so.
		command = "& ([scriptblock]::Create((irm https://zoomies.sh/install.ps1))) -Mode agent -Version " + quoted
		note = "Run this in PowerShell opened as administrator on the host. zoomies upgrade knows no Windows service, so the installer does it instead: " +
			"it keeps the existing credentials, replaces zoomies.exe and restarts the agent. Running runner processes are adopted when the agent starts again."
		return command, controllerVersion, note
	}
	command = "sudo zoomies upgrade --mode agent --version " + quoted
	note = "Run this on the host. It keeps the existing configuration and credentials, refreshes stock runner images and restarts the agent."
	if tag == "dev" {
		note += " The dev channel moves with main, so it may contain a newer build than this controller."
	}
	return command, controllerVersion, note
}

// rentedMachineAdvice is what an operator does about a machine this fleet rents
// that runs an older agent than its controller: the card's sentence and the
// note under it, and the provider's problem, all say this one thing, so that
// the three cannot drift apart.
//
// It names no command, and that is the point. A machine is created by Zoomies,
// holds no shell anybody can reach, and is destroyed when it goes idle, so
// every command that updates an agent elsewhere has nobody to run it: the way
// to change what a machine runs is the image it was cloned from.
//
// build is the release an operator would prepare the template from, which is
// this controller's own tag, and empty when this controller is a build no
// release carries.
func rentedMachineAdvice(rented rentedHost, build string) string {
	what := "This is a machine " + rented.Provider() + " rents, and its agent is the one its provider's template carried when the " +
		"machine was cloned. Zoomies installs nothing of its own inside a rented machine, so nothing updates it in place: it is deleted " +
		"once it has been idle, and the machine that replaces it is cloned from that same template."
	if build == "" {
		return what + " This controller runs a build no release carries, so prepare the template from a release."
	}
	return what + " Prepare that template again from " + build + ", and the machines built afterwards carry it."
}

package controller

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

func TestHostUpgradeCommandsMatchTheControllerWithoutDowngradingAheadAgents(t *testing.T) {
	for _, tt := range []struct {
		name, agent, controller, want string
		embedded, incompatible        bool
	}{
		{"older release", "1.0", "1.2.3", "--version 'v1.2.3'", false, false},
		{"development", "main-sha-1234567", "main-sha-abcdef0", "--version 'dev'", false, false},
		{"matching", "1.2.3", "1.2.3", "", false, false},
		{"newer agent", "2.0", "1.2.3", "", false, false},
		{"local controller", "1.0", "local-dirty", "", false, false},
		{"embedded", "1.0", "1.2.3", "", true, false},
		{"protocol mismatch", "1.2.3", "1.2.3", "--version 'v1.2.3'", false, true},
	} {
		t.Run(tt.name, func(t *testing.T) {
			cmd, _, note := hostUpgrade(&store.Host{Version: tt.agent, Embedded: tt.embedded, Incompatible: tt.incompatible}, tt.controller, rentedHost{})
			if tt.want == "" {
				if cmd != "" {
					t.Fatalf("unexpected command %q", cmd)
				}
			} else if !strings.Contains(cmd, tt.want) || !strings.Contains(cmd, "zoomies upgrade --mode agent") {
				t.Fatalf("command %q", cmd)
			}
			if strings.Contains(cmd, "join-token") {
				t.Fatal("upgrade must not enrol again")
			}
			if tt.name == "local controller" && !strings.Contains(note, "unpublished") {
				t.Fatalf("missing explanation: %s", note)
			}
		})
	}
}

// A machine this fleet rents is given no command at all, and a sentence that
// says where its agent actually comes from. Nobody logs into a clone, it is
// destroyed when it goes idle, and every command that updates an agent
// elsewhere would be run on a host that is about to stop existing.
func TestHostUpgradeOnARentedMachineOffersNoCommandAndNamesTheTemplate(t *testing.T) {
	rented := rentedHost{MachineID: "mach_1", ProviderID: "prv_1", ProviderName: "proxmox-pve"}
	cmd, _, note := hostUpgrade(&store.Host{Version: "1.3.1"}, "1.4.0", rented)
	if cmd != "" {
		t.Fatalf("a rented machine was given a command to run somewhere: %q", cmd)
	}
	for _, want := range []string{"proxmox-pve", "template", "cloned", "v1.4.0", "idle", "replaces"} {
		if !strings.Contains(note, want) {
			t.Errorf("the note does not say %q: %s", want, note)
		}
	}
	if strings.Contains(note, "sudo") || strings.Contains(note, "zoomies upgrade") {
		t.Fatalf("the note offers a command nobody can run: %s", note)
	}
	// The same advice, in the same words, is what the update block and the
	// provider's problem give: one fact, three surfaces, one spelling.
	if why := rentedMachineAdvice(rented, "v1.4.0"); !strings.Contains(why, "proxmox-pve") {
		t.Fatalf("the shared sentence does not name the provider: %s", why)
	}
}

// A Windows agent is not offered sudo or zoomies upgrade, which knows no
// Windows service. It is offered the installer script, which upgrades an
// enrolled machine without a token, so the command never enrols it twice.
func TestHostUpgradeOnWindowsIsTheInstallerScript(t *testing.T) {
	cmd, version, note := hostUpgrade(&store.Host{OS: "windows", Version: "1.0"}, "1.2.3", rentedHost{})
	want := "& ([scriptblock]::Create((irm https://zoomies.sh/install.ps1))) -Mode agent -Version 'v1.2.3'"
	if cmd != want {
		t.Fatalf("command = %q, want %q", cmd, want)
	}
	if version != "1.2.3" || !strings.Contains(note, "administrator") {
		t.Fatalf("version %q, note %q", version, note)
	}
}

package controller

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

func TestHeartbeatUsageReachesPlacementViewsAndMetrics(t *testing.T) {
	h := newHarness(t)
	tr := h.c.EmbeddedTransport()
	joined, err := tr.Join(h.ctx, agent.JoinRequest{ProtocolVersion: agent.ProtocolVersion,
		Name: "shared-host", Capacity: 4, CPUs: 8, MemoryMB: 16384,
		Backends: []backend.Info{{Kind: store.BackendDocker, Available: true}}})
	if err != nil {
		t.Fatal(err)
	}
	tr.SetCredentials(joined.HostID, joined.AgentToken)
	cpu, memory := 99.0, int64(8192)
	beat := func() *store.Host {
		t.Helper()
		if _, err := tr.Heartbeat(h.ctx, agent.HeartbeatRequest{Usage: &store.HostUsage{CPUPercent: &cpu, MemoryAvailableMB: &memory}}); err != nil {
			t.Fatal(err)
		}
		host, err := h.st.GetHost(h.ctx, joined.HostID)
		if err != nil {
			t.Fatal(err)
		}
		return host
	}
	if host := beat(); !scheduler.HostAvailable(host, h.c.Now()) {
		t.Fatal("one spike held the host")
	}
	h.advance(31 * time.Second)
	host := beat()
	view := h.c.HostView(host)
	if !host.Healthy(h.c.Now()) || scheduler.HostAvailable(host, h.c.Now()) || !view.UsageFresh || !strings.Contains(view.AdmissionReason, "CPU") {
		t.Fatalf("connected and pressure-held were conflated: %+v", view)
	}
	for name, want := range map[string]float64{
		"zoomies_host_cpu_usage_percent":      99,
		"zoomies_host_memory_available_bytes": 8192 * (1 << 20),
		"zoomies_host_admission_held":         1,
		"zoomies_host_usage_fresh":            1,
	} {
		if got, ok := gatherValue(t, h.c, name, map[string]string{"host": host.ID}); !ok || got != want {
			t.Fatalf("%s = %v (%v), want %v", name, got, ok, want)
		}
	}
	// An older peer omits usage. It must not restamp the old reading as fresh.
	h.advance(store.HostUsageMaxAge)
	if _, err := tr.Heartbeat(h.ctx, agent.HeartbeatRequest{}); err != nil {
		t.Fatal(err)
	}
	host, err = h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	if h.c.HostView(host).UsageFresh {
		t.Fatal("heartbeat freshened an omitted usage sample")
	}
	if _, ok := gatherValue(t, h.c, "zoomies_host_cpu_usage_percent", map[string]string{"host": host.ID}); ok {
		t.Fatal("stale CPU still exported as current")
	}
	if err := h.st.SetHostCordoned(h.ctx, host.ID, true); err != nil {
		t.Fatal(err)
	}
	cpu = 20
	host = beat()
	if host.Usage.CPUHeld || !host.Cordoned || scheduler.HostAvailable(host, h.c.Now()) {
		t.Fatal("CPU recovery undid the operator's cordon")
	}
}

// The disk figures the pulse already carries have to be reachable from the two
// places an operator or an assistant asks: the host's API view and the
// Prometheus endpoint. Disk-bound is the judgement the scratch advice rests on,
// and I/O wait is the figure that separates it from a CPU-bound host.
func TestTheDiskPulseIsReadableFromTheViewAndMetrics(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	wait := 31.0
	since := h.c.Now().Add(-11 * time.Minute)
	if err := h.st.SetHostUsage(h.ctx, host.ID, store.HostUsage{
		SampledAt:       h.c.Now(),
		IOWaitPercent:   &wait,
		IOWaitHighSince: &since,
	}); err != nil {
		t.Fatalf("SetHostUsage: %v", err)
	}
	host, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	view := h.c.HostView(host)
	if !view.UsageFresh || !view.DiskBound {
		t.Fatalf("view usage_fresh=%v disk_bound=%v, want a fresh disk-bound host", view.UsageFresh, view.DiskBound)
	}
	if view.Usage == nil || view.Usage.IOWaitPercent == nil || *view.Usage.IOWaitPercent != wait {
		t.Fatalf("view usage = %+v, want I/O wait %v", view.Usage, wait)
	}
	for name, want := range map[string]float64{
		"zoomies_host_io_wait_percent":  wait,
		"zoomies_host_disk_total_bytes": float64(host.DiskTotalMB) * (1 << 20),
		"zoomies_host_disk_free_bytes":  float64(host.DiskFreeMB) * (1 << 20),
		"zoomies_host_disk_bound":       1,
	} {
		if got, ok := gatherValue(t, h.c, name, map[string]string{"host": host.ID}); !ok || got != want {
			t.Errorf("%s = %v (%v), want %v", name, got, ok, want)
		}
	}
}

package controller

import (
	"context"
	"fmt"
	"math"
	"slices"
	"sort"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/naming"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// A host has two numbers that say how many runners it takes: the capacity an
// operator typed, and what its machine holds of the standard runner size it was
// given. The smaller wins, and when it is the second the operator's capacity is a
// promise the machine was never asked to keep -- a host set to three slots that
// holds one, because its standard runner is six of its seven CPUs. Nothing is
// broken: that may be exactly the big runners somebody wanted. It matters when
// jobs are waiting for a runner while the machine has the room, which is the one
// case worth saying something about.

// pressureWindow is how far back a pool's jobs having waited counts. Long enough
// to span a quiet hour in a working day, short enough that a pool that has since
// been left alone stops being advised on.
const pressureWindow = 6 * time.Hour

// Pressure is evidence, not a mood: a pool is under it when the typical job it ran
// in the window waited for a runner, over enough jobs that it is not one slow
// start. The median, so a single job held up by GitHub does not count; and read
// from the jobs themselves rather than from what the scheduler last saw, so a
// restart does not forget it and a test can make it with the jobs it has.
const (
	pressureMedianWait = 30 * time.Second
	pressureMinJobs    = 5
)

// poolsUnderPressure is the pools whose typical job waited at least pressureMedianWait
// within the window.
func (c *Controller) poolsUnderPressure(ctx context.Context) (map[string]bool, error) {
	since := c.Now().Add(-pressureWindow)
	res, err := c.st.JobStatsOf(ctx, store.JobFilter{Since: &since}, []string{store.GroupByPool}, store.MeasureQueueWait)
	if err != nil {
		return nil, fmt.Errorf("reading how long jobs waited: %w", err)
	}
	out := map[string]bool{}
	for _, g := range res.Groups {
		id := g.Keys[store.GroupByPool]
		if id == "" || id == store.UnknownVersion {
			continue
		}
		w := g.QueueWait
		if w.Samples >= pressureMinJobs && w.P50MS != nil && time.Duration(*w.P50MS)*time.Millisecond >= pressureMedianWait {
			out[id] = true
		}
	}
	return out, nil
}

// floorTo rounds v down to a multiple of step, which keeps a proposed size a number
// an operator would type and never rounds up into the capacity it is meant to fit.
func floorTo(v, step float64) float64 { return math.Floor(v/step+1e-9) * step }

// hostCapacityAdviceProblems is host.slots_below_capacity: a host whose standard
// runner size holds it below its capacity while a pool that reaches it has had jobs
// waiting, with the size that would give it the capacity -- if every pool that
// reaches it keeps the room it has and the host gains some.
func (c *Controller) hostCapacityAdviceProblems(ctx context.Context, out *[]Problem) error {
	hosts, err := c.fleetHosts(ctx)
	if err != nil {
		return fmt.Errorf("listing hosts: %w", err)
	}
	pools, err := c.fleetPools(ctx)
	if err != nil {
		return fmt.Errorf("listing pools: %w", err)
	}
	now := c.Now()
	fleet := c.cfg().Runners
	// Which hosts could be advised comes first, and costs nothing: the jobs' waits
	// are a database read, and on a fleet where no host has been given a runner size
	// -- the default -- there is nothing to read them for.
	var short []*store.Host
	for _, h := range hosts {
		// A host the controller has stepped down is held back by load, not by its
		// runner size, and changing its profile lifts the step-down in the same write:
		// the priced gain would be wrong and the protection gone. host.throttled already
		// says what to do about it.
		if h.Cordoned || h.Capacity <= 0 || h.Throttle.Active() || !scheduler.HostAvailable(h, now) || !h.RunnerProfile.Standard.Sized() {
			continue
		}
		if h.Slots() < h.Capacity {
			short = append(short, h)
		}
	}
	if len(short) == 0 {
		return nil
	}
	pressure, err := c.poolsUnderPressure(ctx)
	if err != nil {
		return err
	}
	if len(pressure) == 0 {
		return nil
	}
	for _, h := range short {
		slots := h.Slots()
		var reaching []*store.Pool
		var waiting []string
		for _, p := range pools {
			if !p.Enabled || !reaches(h, p) {
				continue
			}
			reaching = append(reaching, sizingPool(p, fleet))
			if pressure[p.ID] {
				waiting = append(waiting, p.Name)
			}
		}
		if len(waiting) == 0 {
			continue
		}
		sort.Strings(waiting)

		alloc := h.Allocatable()
		std := h.RunnerProfile.Standard
		var limits []string
		next := std
		if std.CPUs > 0 && alloc.CPUsKnown && int((alloc.CPUs+1e-6)/std.CPUs) < h.Capacity {
			limits = append(limits, "CPU")
			next.CPUs = floorTo(alloc.CPUs/float64(h.Capacity), 0.25)
		}
		if std.MemoryMB > 0 && alloc.MemoryKnown && int(alloc.MemoryMB/std.MemoryMB) < h.Capacity {
			limits = append(limits, "memory")
			next.MemoryMB = int64(floorTo(float64(alloc.MemoryMB)/float64(h.Capacity), 256))
		}
		if len(limits) == 0 {
			continue
		}

		remedy, why := c.priceHostSize(h, reaching, next, limits)
		if remedy != nil {
			if blocked, berr := c.hostSizeKillsJobs(ctx, reaching, std, next); berr != nil {
				return berr
			} else if blocked != "" {
				remedy, why = nil, blocked
			}
		}
		detail := fmt.Sprintf("it is set to %s, and its machine has %s CPU and %s to place runners on, but one runner here is %s CPU and %s, which holds %s. "+
			"Typical jobs waited %s or more for a runner in the last %s: pools %s.",
			plural(h.Capacity, "slot"), scheduler.FormatCPUs(alloc.CPUs), scheduler.FormatMB(alloc.MemoryMB),
			scheduler.FormatCPUs(std.CPUs), scheduler.FormatMB(std.MemoryMB), plural(slots, "runner"),
			pressureMedianWait, pressureWindow, strings.Join(waiting, ", "))
		fix := fmt.Sprintf("give each runner here less (the host's Runner sizes), or lower its capacity to %d if the big runners are what you want. "+
			"A host's slots are limited by whichever of CPU, memory or capacity runs out first.", slots)
		if remedy != nil {
			fix = fmt.Sprintf("set this host's standard runner to %s CPU and %s, or zoomies hosts edit %s --standard-cpus %s --standard-memory-mb %d. ",
				scheduler.FormatCPUs(next.CPUs), scheduler.FormatMB(next.MemoryMB), h.ID, scheduler.FormatCPUs(next.CPUs), next.MemoryMB) +
				"It applies to runners created after the change."
		} else if why != "" {
			detail += " " + capitalise(why) + "."
		}
		*out = append(*out, Problem{
			Code:     "host.slots_below_capacity",
			Severity: config.SeverityInfo,
			Title: fmt.Sprintf("host %s holds %d of its %d slots, because its runners are larger than the machine divides into",
				naming.ForSentence(h.Name), slots, h.Capacity),
			Detail: detail, Fix: fix,
			Remedy:     remedy,
			TargetKind: "host", TargetID: h.ID,
		})
	}
	return nil
}

// hostSizeKillsJobs says why a smaller runner on a host would put the jobs of a pool that
// takes its size from the host at risk, or "" when the evidence says it would not.
//
// The gain is counted in runners, and a smaller runner holds more of them -- which is no use to a
// job that needed the memory. Memory is a limit a job is killed at, so what a week of a pool's
// jobs used, with the headroom every floor here carries, has to fit in the new size; a pool
// that has had a job killed for memory is not one to give less. CPU is not asked: a build's
// CPU peak is a burst, and the slot is not sized by it.
func (c *Controller) hostSizeKillsJobs(ctx context.Context, reaching []*store.Pool, std, next store.RunnerStandard) (string, error) {
	if next.MemoryMB <= 0 || next.MemoryMB >= std.MemoryMB {
		return "", nil
	}
	if !c.sizingHistoryKept() {
		// Not asked and answered "fine": a smaller runner cannot be checked against a week of
		// jobs that are no longer there, and unchecked is the one answer that is not safe.
		return fmt.Sprintf("job history is kept for %s, less than the %s needed to check that a smaller runner would hold the jobs",
			c.cfg().Retention.Jobs, minimumEvidenceWindow), nil
	}
	names := map[string]string{}
	var ids []string
	for _, p := range reaching {
		if p.SizeFromProfile {
			ids = append(ids, p.ID)
			names[p.ID] = p.Name
		}
	}
	if len(ids) == 0 {
		return "", nil
	}
	since := c.Now().Add(-minimumEvidenceWindow)
	stats, err := c.st.JobStatsOf(ctx, store.JobFilter{Since: &since, PoolIDs: ids}, []string{store.GroupByPool}, store.MeasurePeaks)
	if err != nil {
		return "", fmt.Errorf("reading what jobs used: %w", err)
	}
	for _, g := range stats.Groups {
		name := names[g.Keys[store.GroupByPool]]
		if g.OOMKilled > 0 {
			return fmt.Sprintf("pool %s had a job killed for memory in the last %s, and a smaller runner would give it less", name, minimumEvidenceWindow), nil
		}
		if g.PeakMemoryMB != nil && float64(*g.PeakMemoryMB)*minimumHeadroom > float64(next.MemoryMB) {
			return fmt.Sprintf("jobs in pool %s used up to %s in the last %s, which a runner of %s would not hold with room to spare",
				name, scheduler.FormatMB(*g.PeakMemoryMB), minimumEvidenceWindow, scheduler.FormatMB(next.MemoryMB)), nil
		}
	}
	return "", nil
}

// priceHostSize prices giving a host the runner size next: every pool that
// reaches it is asked how many runners it would have room for there, before and
// after, and the size is only proposed if none loses any and the host gains.
// Where it cannot be proposed the second answer says what stands in the way, so the
// notice can say it instead of leaving an operator to find out by trying.
func (c *Controller) priceHostSize(h *store.Host, reaching []*store.Pool, next store.RunnerStandard, limits []string) (*Remedy, string) {
	cand := *h
	cand.RunnerProfile.Standard = next
	if m := h.RunnerProfile.Minimum; (m.CPUs > 0 && next.CPUs > 0 && next.CPUs < m.CPUs) || (m.MemoryMB > 0 && next.MemoryMB > 0 && next.MemoryMB < m.MemoryMB) {
		return nil, "the size that would give it its slots is below this host's own smallest runner"
	}
	if next.CPUs > 0 && next.CPUs < store.MinRunnerCPUs || next.MemoryMB > 0 && next.MemoryMB < store.MinRunnerMemoryMB {
		return nil, "the size that would give it its slots is below the least a runner is given"
	}
	var before, after int
	for _, p := range reaching {
		b, a := poolHostRoom(h, p), poolHostRoom(&cand, p)
		if scheduler.ExcludedBySize(&cand, p) != nil && scheduler.ExcludedBySize(h, p) == nil {
			return nil, "a pool that reaches it would no longer be given runners there, because the smaller size is below that pool's smallest runner"
		}
		if a.Room < b.Room {
			return nil, fmt.Sprintf("a pool that reaches it would have room for fewer runners there (%d, from %d)", a.Room, b.Room)
		}
		before += b.Room
		after += a.Room
	}
	if after <= before {
		return nil, "a pool's own minimum charges each runner more than the standard, so a smaller standard would not give the host more slots; lower that pool's smallest runner"
	}
	profile := h.RunnerProfile
	profile.Standard = next
	// The host's own count, not the pools' rooms added up: two pools that reach one
	// machine each have room for what it holds, and their sum is not a number of
	// runners it can run.
	effect := fmt.Sprintf("the host holds %s instead of %s, and no pool that reaches it loses room", plural(cand.Slots(), "runner"), plural(h.Slots(), "runner"))
	return newRemedy(RemedyHostUpdate, h.ID,
		fmt.Sprintf("Give each runner %s CPU and %s", scheduler.FormatCPUs(next.CPUs), scheduler.FormatMB(next.MemoryMB)),
		effect, map[string]any{"runner_profile": profile}, h.RunnerProfile), ""
}

// A host that has been throttled is a host that was given more than it could do.
// The scheduler's default order, headroom, prefers whichever host would have the
// most left afterwards -- so the largest machine is the first choice every time,
// and goes on being the first choice while it is throttled, because even a
// throttled large host has more left than a small idle one. The result is the
// pattern worth saying aloud: the biggest host, which is often the one that also
// runs the controller, pinned, while three smaller ones sit idle.
//
// There is no remedy. What would help is a decision -- the placement order, or how
// many slots the large host should have -- and both depend on what the large host
// is for, which only its operator knows.

// idleCPUPercent is how little CPU a host is using to count as idle for this.
const idleCPUPercent = 30.0

// hostConcentrationProblems is host.work_concentrated.
func (c *Controller) hostConcentrationProblems(ctx context.Context, out *[]Problem) error {
	order := c.cfg().Scheduler.HostOrder
	if order != "" && order != "headroom" {
		return nil
	}
	hosts, err := c.fleetHosts(ctx)
	if err != nil {
		return fmt.Errorf("listing hosts: %w", err)
	}
	now := c.Now()
	var pinned, idle []*store.Host
	for _, h := range hosts {
		if h.Cordoned || !scheduler.HostAvailable(h, now) || !h.Usage.Fresh(now) {
			continue
		}
		switch {
		case h.Throttle.Active() && h.ActiveRunners > 0:
			pinned = append(pinned, h)
		case h.ActiveRunners == 0 && h.Capacity > 0 && h.Usage.CPUPercent != nil && *h.Usage.CPUPercent < idleCPUPercent:
			idle = append(idle, h)
		}
	}
	if len(pinned) == 0 || len(idle) == 0 {
		return nil
	}
	pools, err := c.fleetPools(ctx)
	if err != nil {
		return fmt.Errorf("listing pools: %w", err)
	}
	sort.Slice(idle, func(i, j int) bool { return idle[i].Name < idle[j].Name })
	for _, h := range pinned {
		label := naming.ForSentence(h.Name)
		// An idle host only counts if work that runs on this one could run there: a
		// Windows or arm64 machine beside a throttled amd64 one is idle for a reason.
		var reaching []*store.Pool
		for _, p := range pools {
			if p.Enabled && reaches(h, p) {
				reaching = append(reaching, p)
			}
		}
		var names []string
		for _, other := range idle {
			if slices.ContainsFunc(reaching, func(p *store.Pool) bool { return reaches(other, p) }) {
				names = append(names, naming.ForSentence(other.Name))
			}
		}
		if len(names) == 0 {
			continue
		}
		*out = append(*out, Problem{
			Code:     "host.work_concentrated",
			Severity: config.SeverityInfo,
			Title:    fmt.Sprintf("host %s is throttled while %s idle", label, plural(len(names), "other host")+verbIs(len(names))),
			Detail: fmt.Sprintf("%s is running %s and has been stepped down after sustained pressure, while %s with no runners and under %.0f%% CPU, and work that runs on %s could run there. "+
				"The placement order is headroom, which prefers the host with the most left afterwards, so the largest machine is the first choice again as soon as a job needs a runner, throttled or not.",
				label, plural(h.ActiveRunners, "runner"), strings.Join(names, ", ")+verbIs(len(names)), idleCPUPercent, label),
			Fix: fmt.Sprintf("lower %s's capacity so it takes fewer runners at once. Changing scheduler.host_order is not the answer on its own: best_fit packs the fullest host first "+
				"and largest_standard prefers the host where a pool's runner is biggest, and both keep choosing a large host that headroom would have left. "+
				"Which capacity is right depends on what %s is for, so none is proposed for you.", label, label),
			TargetKind: "host", TargetID: h.ID,
		})
	}
	return nil
}

// reaches is whether a pool's runners could be placed on a host at all: the
// host's selector, its backend and its platform, and none of its sizes or load.
func reaches(h *store.Host, p *store.Pool) bool {
	return scheduler.HostSelects(h, p) && scheduler.HostOffers(h, p) && scheduler.HostIsPlatform(h, p)
}

// verbIs is " is" or " are", for a sentence that counts hosts.
func verbIs(n int) string {
	if n == 1 {
		return " is"
	}
	return " are"
}

package controller

import (
	"encoding/json"
	"fmt"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// capacityFleet is the host in the report this is written from: a machine set to
// three slots whose standard runner is most of it, so it holds one -- and a pool
// that takes its size from the host.
func capacityFleet(t *testing.T, mutate func(*store.RunnerProfile)) (*harness, *store.Host, *store.Pool) {
	t.Helper()
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "builders")
	pool.SizeFromProfile = true
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	host := h.measuredHost("dev-box", 8, 32768, 3, enforcesEverything)
	profile := store.RunnerProfile{Standard: store.RunnerStandard{CPUs: 6, MemoryMB: 6656}}
	if mutate != nil {
		mutate(&profile)
	}
	if err := h.st.PatchHost(h.ctx, host.ID, store.HostChanges{RunnerProfile: &profile}); err != nil {
		t.Fatal(err)
	}
	host, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	return h, host, pool
}

// waiting makes the evidence the advice rests on: jobs of the pool that each
// waited two minutes for a runner, within the window.
func waiting(h *harness, pool *store.Pool) {
	h.t.Helper()
	for i := 0; i < pressureMinJobs+1; i++ {
		queued := h.c.Now().Add(-time.Hour)
		started, done := queued.Add(2*time.Minute), queued.Add(5*time.Minute)
		if _, err := h.st.UpsertJob(h.ctx, &store.Job{
			GitHubJobID: int64(1000 + i), GitHubRunID: 1, Repo: "acme/widgets", Workflow: "ci", JobName: "build",
			Labels: store.StringSlice{"self-hosted", "linux", "x64"}, State: store.JobCompleted, Conclusion: "success",
			InstallationID: pool.InstallationID, PoolID: pool.ID, Matched: true,
			QueuedAt: queued, StartedAt: &started, CompletedAt: &done,
		}); err != nil {
			h.t.Fatal(err)
		}
	}
}

// With jobs having waited for a runner, a host that holds fewer runners than its capacity
// because of how big each one is is told so, with the size that would give it
// the capacity and what that costs: here, nothing.
func TestAHostHoldingFewerRunnersThanItsCapacityIsOfferedTheSizeThatFixesIt(t *testing.T) {
	h, host, pool := capacityFleet(t, nil)
	if host.Slots() >= host.Capacity {
		t.Fatalf("the fixture must hold fewer than its capacity: slots %d, capacity %d", host.Slots(), host.Capacity)
	}
	waiting(h, pool)

	p := h.problemOrNil("host.slots_below_capacity")
	if p == nil || p.TargetID != host.ID {
		t.Fatalf("problem = %+v; want one for the host", p)
	}
	if p.Remedy == nil || p.Remedy.Kind != RemedyHostUpdate || p.Remedy.TargetID != host.ID {
		t.Fatalf("remedy = %+v; want a host update", p.Remedy)
	}
	var body struct {
		RunnerProfile store.RunnerProfile `json:"runner_profile"`
	}
	if err := json.Unmarshal(p.Remedy.Body, &body); err != nil {
		t.Fatal(err)
	}
	alloc := host.Allocatable()
	std := body.RunnerProfile.Standard
	if std.CPUs <= 0 || std.CPUs > alloc.CPUs/float64(host.Capacity)+1e-9 || std.CPUs >= 6 {
		t.Errorf("standard CPU %v must be smaller than 6 and at most %v, the capacity's share", std.CPUs, alloc.CPUs/float64(host.Capacity))
	}
	// Applied, the host would hold what it was set to.
	cand := *host
	cand.RunnerProfile = body.RunnerProfile
	if cand.Slots() != host.Capacity {
		t.Errorf("the proposed size holds %d runners, want the capacity %d", cand.Slots(), host.Capacity)
	}
	if !strings.Contains(p.Remedy.Effect, "no pool that reaches it loses room") || !strings.Contains(p.Detail, "builders") {
		t.Errorf("the effect and the pool that waited must be said:\neffect: %s\ndetail: %s", p.Remedy.Effect, p.Detail)
	}
}

// Without jobs having waited, big runners may be what somebody wanted, and a capacity
// above what they allow is only a ceiling: nothing is said.
func TestAHostIsOnlyAdvisedWhileJobsHaveBeenWaiting(t *testing.T) {
	h, _, _ := capacityFleet(t, nil)
	if p := h.problemOrNil("host.slots_below_capacity"); p != nil {
		t.Fatalf("advised with nothing waiting: %+v", p)
	}
}

func TestAHostThatHoldsItsCapacityIsNotAdvised(t *testing.T) {
	h, _, pool := capacityFleet(t, func(p *store.RunnerProfile) { p.Standard = store.RunnerStandard{CPUs: 2, MemoryMB: 4096} })
	waiting(h, pool)
	if p := h.problemOrNil("host.slots_below_capacity"); p != nil {
		t.Fatalf("a host holding all its slots was advised: %+v", p)
	}
}

// The size that would give the host its slots must still be one a runner may be
// given. Where it is not, the notice says what stands in the way and offers nothing
// to apply, because a change that is refused or that costs a pool its runners is not
// a suggestion.
func TestNoRemedyIsOfferedForASizeBelowTheHostsOwnSmallestRunner(t *testing.T) {
	h, _, pool := capacityFleet(t, func(p *store.RunnerProfile) { p.Minimum = store.RunnerSize{CPUs: 4} })
	waiting(h, pool)
	p := h.problemOrNil("host.slots_below_capacity")
	if p == nil {
		t.Fatal("the squeeze is real and the host should still be told")
	}
	if p.Remedy != nil {
		t.Errorf("a remedy below the host's own smallest runner was offered: %+v", p.Remedy)
	}
	if !strings.Contains(p.Detail, "smallest runner") {
		t.Errorf("what stands in the way must be said: %s", p.Detail)
	}
}

// minimumFleet is the pool in the report this was written from: a Docker-in-Docker
// pool whose smallest runner is 1.5 GB a container with a sidecar holding 15% of the
// memory, which makes every slot at least ten gigabytes on machines that could hold
// three runners at a third of that.
func minimumFleet(t *testing.T, peakMB int64, jobs int, oom bool) (*harness, *store.Pool) {
	t.Helper()
	return minimumFleetMeasured(t, peakMB, jobs, jobs, oom)
}

// minimumFleetMeasured is minimumFleet where only the first measured of the jobs had
// a peak recorded: a job too short to be sampled has none.
func minimumFleetMeasured(t *testing.T, peakMB int64, jobs, measured int, oom bool) (*harness, *store.Pool) {
	t.Helper()
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "builders")
	pool.DockerMode = store.DockerDinD
	pool.Resources.MinMemoryMB = 1536
	pool.Resources.DaemonMemorySharePercent = 15
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	host := h.measuredHost("box-1", 8, 16384, 3, enforcesEverything)
	for i := 0; i < jobs; i++ {
		// A peak is measured while the job runs, so the job goes through its life: it
		// starts on a runner, the runner's use is recorded, and then it completes.
		runner := &store.Runner{PoolID: pool.ID, HostID: host.ID, Name: fmt.Sprintf("r%d", i), State: store.RunnerBusy}
		if err := h.st.CreateRunner(h.ctx, runner); err != nil {
			t.Fatal(err)
		}
		queued := h.c.Now().Add(-time.Hour)
		started, done := queued.Add(2*time.Minute), queued.Add(5*time.Minute)
		job := &store.Job{
			GitHubJobID: int64(5000 + i), GitHubRunID: 1, Repo: "acme/widgets", Workflow: "ci", JobName: "build",
			Labels: store.StringSlice{"self-hosted", "linux", "x64"}, State: store.JobInProgress, RunnerID: runner.ID,
			InstallationID: pool.InstallationID, PoolID: pool.ID, Matched: true, QueuedAt: queued, StartedAt: &started,
		}
		if _, err := h.st.UpsertJob(h.ctx, job); err != nil {
			t.Fatal(err)
		}
		if i < measured {
			if err := h.st.RecordJobUsage(h.ctx, runner.ID, 1, peakMB); err != nil {
				t.Fatal(err)
			}
			if err := h.st.RecordJobHalfPeaks(h.ctx, runner.ID, peakMB*8/10, peakMB*2/10); err != nil {
				t.Fatal(err)
			}
		}
		job.State, job.Conclusion, job.CompletedAt = store.JobCompleted, "success", &done
		if _, err := h.st.UpsertJob(h.ctx, job); err != nil {
			t.Fatal(err)
		}
		if oom && i == 0 {
			if _, _, err := h.st.MarkJobOOMKilled(h.ctx, runner.ID, "killed for memory"); err != nil {
				t.Fatal(err)
			}
		}
	}
	// The halves the jobs used: most of the peak in the runner, a fifth in the
	// daemon, which is inside the share it is given.
	seedPairs(h, pool, peakMB*8/10, peakMB*2/10)
	return h, pool
}

// seedPairs is the window of what each container of the pool's pairs used, from
// enough runners to count as the pool's. The limits are the slot a 15% sidecar
// divides, which is all a sample's use is judged against.
func seedPairs(h *harness, pool *store.Pool, runnerMB, daemonMB int64) {
	h.c.pairMu.Lock()
	defer h.c.pairMu.Unlock()
	h.c.pairs = map[string][]pairSample{}
	for i := 0; i < pairMinSamples+10; i++ {
		h.c.pairs[pool.ID] = append(h.c.pairs[pool.ID], pairSample{at: h.c.Now(), sampled: h.c.Now().Add(time.Duration(i) * 30 * time.Second), runner: fmt.Sprintf("r%d", i%pairMinRunners+1), halves: backend.PairHalves{
			Runner: backend.HalfUse{MemoryBytes: runnerMB << 20, MemoryLimit: 8704 << 20},
			Daemon: backend.HalfUse{MemoryBytes: daemonMB << 20, MemoryLimit: 1536 << 20},
		}})
	}
}

// A job's peak is the two containers added together, but a thin sidecar has a limit
// of its own: a pool whose jobs fit the slot in sum can still keep nearly all of
// its peak in a daemon holding 15%, and a floor sized from the sum would have it
// killed. So the floor follows the half that needs the most, and a pool whose
// daemon wants more than it is charged now is not told to charge less.
func TestPoolMinimumAdviceIsSizedByTheThinnerContainerNotJustTheSum(t *testing.T) {
	h, pool := minimumFleet(t, 2048, 25, false)
	seedPairs(h, pool, 600, 1448)
	if p := h.problemOrNil("pool.minimum_overcharges"); p != nil {
		t.Errorf("advised a floor the sidecar would be killed under: %+v", p)
	}
}

// Without what each container used there is nothing to size the halves by, and the
// sum alone is the assumption this advice does not rest on.
func TestPoolMinimumAdviceWaitsForWhatEachContainerUsed(t *testing.T) {
	h, pool := minimumFleet(t, 2048, 25, false)
	h.c.pairMu.Lock()
	delete(h.c.pairs, pool.ID)
	h.c.pairMu.Unlock()
	if p := h.problemOrNil("pool.minimum_overcharges"); p != nil {
		t.Errorf("advised on the sum alone: %+v", p)
	}
}

func TestAPoolWhoseMinimumChargesFarMoreThanItsJobsUsedIsOfferedALowerOne(t *testing.T) {
	h, pool := minimumFleet(t, 2048, 25, false)
	p := h.problemOrNil("pool.minimum_overcharges")
	if p == nil || p.TargetID != pool.ID {
		t.Fatalf("problem = %+v; want one for the pool", p)
	}
	if p.Remedy == nil || p.Remedy.Kind != RemedyPoolUpdate {
		t.Fatalf("remedy = %+v; want a pool update", p.Remedy)
	}
	var body struct {
		Resources store.Resources `json:"resources"`
	}
	if err := json.Unmarshal(p.Remedy.Body, &body); err != nil {
		t.Fatal(err)
	}
	if body.Resources.MinMemoryMB >= 1536 || body.Resources.MinMemoryMB < store.MinRunnerMemoryMB {
		t.Errorf("the proposed minimum is %d MB; want it lower than 1536 and at least the least a runner is given", body.Resources.MinMemoryMB)
	}
	// An update replaces resources whole, so the rest of them must come back as they were.
	if body.Resources.DaemonMemorySharePercent != 15 {
		t.Errorf("the pool's own settings were not carried: %+v", body.Resources)
	}
	cand := *pool
	cand.Resources = body.Resources
	before, _ := h.c.poolRoom(h.ctx, pool)
	after, _ := h.c.poolRoom(h.ctx, &cand)
	if after.Runners <= before.Runners || !strings.Contains(p.Remedy.Effect, "instead of") {
		t.Errorf("the proposal must give the hosts room for more runners and say so: %d -> %d (%s)", before.Runners, after.Runners, p.Remedy.Effect)
	}
}

// The advice rests on what jobs used, so it is silent without enough of them, and
// for a pool whose jobs were killed for memory it is never given: what they used is
// then the limit they hit and not what they needed.
func TestPoolMinimumAdviceNeedsEvidenceAndNeverShrinksAKilledPool(t *testing.T) {
	for name, tc := range map[string]struct {
		peak int64
		jobs int
		oom  bool
	}{
		"too few jobs":               {2048, 10, false},
		"a job killed for memory":    {2048, 25, true},
		"jobs that use what it asks": {9000, 25, false},
	} {
		t.Run(name, func(t *testing.T) {
			h, _ := minimumFleet(t, tc.peak, tc.jobs, tc.oom)
			if p := h.problemOrNil("pool.minimum_overcharges"); p != nil {
				t.Errorf("advised without the evidence for it: %+v", p)
			}
		})
	}
}

// The pattern from the report this was written from: the biggest host, throttled and
// running runners, while smaller ones sit idle, under an order that keeps choosing it.
func concentratedFleet(t *testing.T, bigBusy bool) (*harness, *store.Host) {
	t.Helper()
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "builders")
	big := h.measuredHost("big", 12, 32768, 5, enforcesEverything)
	small := h.measuredHost("small", 4, 16384, 1, enforcesEverything)
	now := h.c.Now()
	cpu := func(v float64) store.HostUsage { return store.HostUsage{CPUPercent: &v, SampledAt: now} }
	if err := h.st.SetHostUsage(h.ctx, big.ID, cpu(80)); err != nil {
		t.Fatal(err)
	}
	if err := h.st.SetHostUsage(h.ctx, small.ID, cpu(2)); err != nil {
		t.Fatal(err)
	}
	if bigBusy {
		if err := h.st.SetHostThrottle(h.ctx, big.ID, store.HostThrottle{Level: 1, Since: &now, ChangedAt: &now, Reason: "load"}, 0); err != nil {
			t.Fatal(err)
		}
		if err := h.st.CreateRunner(h.ctx, &store.Runner{PoolID: pool.ID, HostID: big.ID, Name: "busy-1", State: store.RunnerBusy}); err != nil {
			t.Fatal(err)
		}
	}
	return h, big
}

func TestAThrottledHostIsNamedWhileSmallerOnesSitIdleUnderTheDefaultOrder(t *testing.T) {
