import (
	"encoding/json"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
)

// The failure this was built for, end to end: a heavy job runs on a small
// host, the agent's samples record what it used, a step is killed for memory
// and the runner finishes the job anyway. The job has to come out of it with
// its peaks, marked as the fleet's failure, explained as a memory kill, and
// listed as a problem on the host -- because GitHub will call it a failed
// step like any other.
func TestAJobKilledForMemoryIsRecordedExplainedAndReported(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.seedRunner(t, pool, host, store.RunnerBusy)
	started := h.c.Now().Add(-time.Hour)
	job, err := h.st.UpsertJob(h.ctx, &store.Job{
		GitHubJobID: 4242, Repo: "eyupio/zoomies", Workflow: "CI", JobName: "Go (controller)",
		Labels: pool.Labels, State: store.JobInProgress, PoolID: pool.ID, Matched: true,
		RunnerID: r.ID, RunnerName: r.Name, QueuedAt: started, StartedAt: &started, HostID: host.ID,
	})
	if err != nil {
		t.Fatalf("UpsertJob: %v", err)
	}

	at := h.c.Now()
	for _, s := range []backend.Stats{
		{SampledAt: &at, CPUPercent: 390, MemoryBytes: 2900 << 20},
		{SampledAt: &at, CPUPercent: 120, MemoryBytes: 1200 << 20},
	} {
		if err := h.c.ReportRunners(h.ctx, host.ID, []agent.RunnerReport{{RunnerID: r.ID, Stats: s}}); err != nil {
			t.Fatalf("ReportRunners: %v", err)
		}
	}

	done := h.c.Now()
	if _, err := h.st.UpsertJob(h.ctx, &store.Job{GitHubJobID: 4242, State: store.JobCompleted, Conclusion: "failure",
		Repo: job.Repo, StartedAt: &started, CompletedAt: &done}); err != nil {
		t.Fatalf("completing the job: %v", err)
	}
	if err := h.c.ReportRunners(h.ctx, host.ID, []agent.RunnerReport{{
		RunnerID: r.ID, State: store.RunnerRemoved, Fault: store.FaultOutOfMemory,
		Message: "runner exited after its job, but the kernel killed a process in it for its memory limit",
	}}); err != nil {
		t.Fatalf("ReportRunners: %v", err)
	}

	got, err := h.st.GetJob(h.ctx, job.ID)
	if err != nil {
		t.Fatal(err)
	}
	if !got.OOMKilled || got.FaultKind != store.FaultOutOfMemory || got.PeakMemoryMB != 2900 || got.PeakCPUs != 3.9 {
		t.Fatalf("job = oom %t, fault %q, peaks %v CPU %d MB", got.OOMKilled, got.FaultKind, got.PeakCPUs, got.PeakMemoryMB)
	}

	// The view is the API's shape, and the UI and the MCP tools read these
	// three fields from it.
	raw, err := json.Marshal(NewJobView(got, pool.Name))
	if err != nil {
		t.Fatal(err)
	}
	for _, field := range []string{`"peak_cpus":3.9`, `"peak_memory_mb":2900`, `"oom_killed":true`} {
		if !strings.Contains(string(raw), field) {
			t.Errorf("the job view has no %s: %s", field, raw)
		}
	}

	events, err := h.st.ListJobEvents(h.ctx, job.ID)
	if err != nil {
		t.Fatal(err)
	}
	kills := 0
	for _, e := range events {
		if e.Kind == store.JobEventOOMKilled {
			kills++
		}
	}
	if kills != 1 {
		t.Fatalf("timeline has %d memory kills, want 1", kills)
	}

	ex, err := h.c.ExplainJob(h.ctx, job.ID, 0)
	if err != nil {
		t.Fatalf("ExplainJob: %v", err)
	}
	if !strings.Contains(ex.Summary, "for its memory limit") || !strings.Contains(ex.Summary, "2.8 GB") {
		t.Errorf("the explanation does not lead with the kill: %q", ex.Summary)
	}

	problems, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	found := false
	for _, p := range problems {
		if p.Code == "jobs.oom_killed" {
			found = true
			if !strings.Contains(p.Title, host.ID) {
				t.Errorf("the problem does not name the host: %q", p.Title)
			}
		}
	}
	if !found {
		t.Error("no jobs.oom_killed problem was raised")
	}
}

package controller

import (
	"context"

	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/version"
)

// stampJobVersions records which build handled a job, once each, so that jobs
// can be compared across releases.
//
// It runs from recordJobChange, which every path that changes a job passes
// through, rather than from the webhook handler alone: the poller, the
// recovery sweep and the agent's own reports all move jobs, and a stamp that
// only one of them wrote would leave whichever saw the job first unlabelled.
//
// The controller's pair is stamped once something here has a claim on the job
// -- a pool matched it or a runner took it -- and never for a job nothing
// here touched, so a hosted job stays "unknown" instead of being credited to
// a release that never saw it. The host's pair waits for the runner, and is
// read from the host row as its last heartbeat left it. The store writes each
// column only while it is NULL, so calling this on every change is safe; the
// checks here only keep it from writing when there is nothing to add.
//
// j is updated in place, because the callers publish it next and the event
// frame is the job's GET shape.
func (c *Controller) stampJobVersions(ctx context.Context, j *store.Job, runner *store.Runner) {
	if j == nil || IsDemoID(j.InstallationID) {
		return
	}
	claimed := j.Matched || j.RunnerID != ""
	var v store.JobVersions
	if claimed && j.ControllerVersion == "" {
		v.ControllerVersion, v.ControllerChannel = version.Version, version.Channel(version.Version)
	}
	if j.RunnerID != "" && (j.HostID == "" || j.AgentVersion == "") {
		if runner == nil || runner.ID != j.RunnerID {
			if r, err := c.st.GetRunner(ctx, j.RunnerID); err == nil {
				runner = r
			} else {
				runner = nil
			}
		}
		if runner != nil && runner.HostID != "" {
			v.HostID = runner.HostID
			if h, err := c.st.GetHost(ctx, runner.HostID); err == nil {
				v.AgentVersion = h.Version
			}
		}
	}
	if v == (store.JobVersions{}) {
		return
	}
	stamped, err := c.st.StampJobVersions(ctx, j.ID, v)
	if err != nil {
		// Not worth failing the delivery over: the job is recorded, and the
		// next change to it tries again.
		c.log.Warn("could not stamp a job with its release", "job", j.ID, "error", err)
		return
	}
	j.ControllerVersion, j.ControllerChannel = stamped.ControllerVersion, stamped.ControllerChannel
	j.AgentVersion, j.HostID = stamped.AgentVersion, stamped.HostID
}

// stampJobGranted records the size of the runner a job ran on, once, so the job
// can say how big its machine was after the runner row is gone and a size can
// be compared across jobs: what was granted, and where that figure came from.
//
// It is read from the runner row, which is the only record of what a runner
// was created with -- recomputing it from the pool and the host would answer
// with today's profile rather than the one the job ran under. It runs from
// recordJobChange beside stampJobVersions for the same reason, and the store
// writes it only while it is still empty, so calling it on every change is
// safe; the checks here only keep it from reading when there is nothing to add.
//
// A runner created with no limits, or one from before allocations were
// recorded, has no source and so nothing to stamp: the job stays "not
// recorded" rather than claiming a size nobody applied.
//
// j is updated in place, because the callers publish it next and the event
// frame is the job's GET shape.
func (c *Controller) stampJobGranted(ctx context.Context, j *store.Job, runner *store.Runner) {
	if j == nil || j.RunnerID == "" || j.GrantedSource != "" || IsDemoID(j.InstallationID) {
		return
	}
	if runner == nil || runner.ID != j.RunnerID {
		r, err := c.st.GetRunner(ctx, j.RunnerID)
		if err != nil {
			return
		}
		runner = r
	}
	if runner.AllocationSource == "" || (runner.AllocatedCPUs <= 0 && runner.AllocatedMemoryMB <= 0) {
		return
	}
	var pool *store.Pool
	if p, err := c.st.GetPool(ctx, runner.PoolID); err == nil {
		pool = p
	}
	cpus, memoryMB := grantedSize(pool, runner)
	stamped, err := c.st.StampJobGranted(ctx, j.ID, cpus, memoryMB, runner.AllocationSource)
	if err != nil {
		// Not worth failing the delivery over: the next change to the job
		// tries again.
		c.log.Warn("could not stamp a job with the size it was granted", "job", j.ID, "error", err)
		return
	}
	j.GrantedCPUs, j.GrantedMemoryMB, j.GrantedSource = stamped.GrantedCPUs, stamped.GrantedMemoryMB, stamped.GrantedSource
}

// grantedSize is the guaranteed size of the machine a runner gave its job: what
// its row says it was created with, and for a docker-in-docker runner with
// limits somebody typed, twice that, because the daemon is given the same
// figure as the runner and the job's work is in both. A size taken from the
// host -- a share or a profile's standard -- is already the whole slot, split
// between the pair, so it is not doubled. CPU lent to the runner later is not
// part of it: this is the guarantee, which is what two jobs can be compared by.
func grantedSize(p *store.Pool, r *store.Runner) (cpus float64, memoryMB int64) {
	cpus, memoryMB = r.AllocatedCPUs, r.AllocatedMemoryMB
	if p == nil || p.DockerMode != store.DockerDinD {
		return cpus, memoryMB
	}
	if typedAllocation(r, p.Resources.CPUs > 0) {
		cpus *= 2
	}
	if typedAllocation(r, p.Resources.MemoryMB > 0) {
		memoryMB *= 2
	}
	return cpus, memoryMB
}

// typedAllocation reports whether one field of a runner's allocation is a figure
// somebody typed, which a docker-in-docker pair gives to each of its containers,
// rather than one slot's worth the pair splits. A reduced or history runner
// keeps the nature of the pool's field: it is smaller or larger than the typed
// size, and still typed.
func typedAllocation(r *store.Runner, fieldTyped bool) bool {
	return r.AllocationSource == store.AllocationFromPool ||
		((r.AllocationSource == store.AllocationReduced || r.AllocationSource == store.AllocationHistory) && fieldTyped)
}

package controller

import (
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/version"
)

// A job is stamped where the fleet first has a claim on it -- the controller's
// build when a pool matches it, the host and its agent when a runner takes it --
// and an upgrade half way through must not move it to another release.
func TestAJobIsStampedAtClaimAndAtPickupAndNeverAgain(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	host.Version = "v1.3.1"
	if err := h.st.UpdateHost(h.ctx, host); err != nil {
		t.Fatal(err)
	}
	labels := []string{"self-hosted", "linux", "x64", "demo"}

	h.deliverJob(jobEvent{Action: "queued", JobID: 9301, Labels: labels})
	job, err := h.st.GetJobByGitHubID(h.ctx, 9301)
	if err != nil {
		t.Fatal(err)
	}
	if job.ControllerVersion != version.Version || job.ControllerChannel != version.Channel(version.Version) {
		t.Fatalf("claimed job carries %q/%q, want this build's %q", job.ControllerVersion, job.ControllerChannel, version.Version)
	}
	if job.HostID != "" || job.AgentVersion != "" {
		t.Fatalf("a job with no runner yet has a host: %+v", job)
	}

	// The controller is upgraded while the job runs.
	defer func(v string) { version.Version = v }(version.Version)
	version.Version = "v9.9.9"

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatal(err)
	}
	h.advance(5 * time.Second)
	if _, err := h.c.PollTasks(h.ctx, host.ID, time.Second); err != nil {
		t.Fatal(err)
	}
	r := h.onlyRunner()
	h.deliverJob(jobEvent{Action: "in_progress", JobID: 9301, RunnerName: r.Name, Labels: labels})
	h.deliverJob(jobEvent{Action: "completed", JobID: 9301, RunnerName: r.Name, Labels: labels, Conclusion: "success"})

	got, err := h.st.GetJobByGitHubID(h.ctx, 9301)
	if err != nil {
		t.Fatal(err)
	}
	if got.HostID != host.ID || got.AgentVersion != "v1.3.1" {
		t.Errorf("picked-up job is on %q at agent %q, want %q at v1.3.1", got.HostID, got.AgentVersion, host.ID)
	}
	if got.ControllerVersion == "v9.9.9" || got.ControllerVersion != job.ControllerVersion {
		t.Errorf("the controller's release moved from %q to %q on later deliveries", job.ControllerVersion, got.ControllerVersion)
	}
	if got.State != store.JobCompleted {
		t.Errorf("state = %s", got.State)
	}
}

// Hosted work belongs to somebody else's runners, so crediting it to a release
// of this controller would put numbers it never produced into that release.
func TestAJobNoPoolClaimsIsNotStamped(t *testing.T) {
	h := newHarness(t)
	h.fleet()
	h.deliverJob(jobEvent{Action: "queued", JobID: 9302, Labels: []string{"ubuntu-latest"}})
	job, err := h.st.GetJobByGitHubID(h.ctx, 9302)
	if err != nil {
		t.Fatal(err)
	}
	if job.ControllerVersion != "" || job.HostID != "" {
		t.Fatalf("an unclaimed hosted job was stamped: %+v", job)
	}
}

package controller

import (
	"reflect"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// The webhook and the poller read the pools to claim a job, and then name the
// pool in the frame they publish for it. Reading that pool again, whole, to
// learn a name the pools in hand already hold was a fifth of a poller sweep.

func TestAJobIsViewedWithItsPoolsNameFromThePoolsAlreadyRead(t *testing.T) {
	h := newHarness(t)
	p := h.pool(h.installation(), "gpu", "self-hosted", "gpu")
	pools, err := h.st.ListPools(h.ctx)
	if err != nil {
		t.Fatalf("ListPools: %v", err)
	}
	// With its row gone, a name can only have come from the pools in hand.
	if _, _, err := h.st.DeletePool(h.ctx, p.ID); err != nil {
		t.Fatalf("DeletePool: %v", err)
	}

	job := &store.Job{ID: "job_1", PoolID: p.ID, Matched: true}
	if got := h.c.jobViewIn(h.ctx, job, pools).PoolName; got != p.Name {
		t.Errorf("PoolName = %q, want %q from the pools in hand", got, p.Name)
	}
}

func TestAJobWhosePoolIsNotAmongThePoolsInHandIsStillNamed(t *testing.T) {
	h := newHarness(t)
	p := h.pool(h.installation(), "gpu", "self-hosted", "gpu")
	job := &store.Job{ID: "job_1", PoolID: p.ID, Matched: true}

	for name, pools := range map[string][]*store.Pool{
		"no pools read":             nil,
		"only another pool is read": {{ID: "pool_other", Name: "other"}},
	} {
		if got := h.c.jobViewIn(h.ctx, job, pools).PoolName; got != p.Name {
			t.Errorf("%s: PoolName = %q, want %q read from the store", name, got, p.Name)
		}
	}
}

// The frame is the same one: only where the name comes from differs.
func TestAJobViewFromThePoolsInHandIsTheViewAPlainReadGives(t *testing.T) {
	h := newHarness(t)
	p := h.pool(h.installation(), "gpu", "self-hosted", "gpu")
	pools, err := h.st.ListPools(h.ctx)
	if err != nil {
		t.Fatalf("ListPools: %v", err)
	}

	for name, job := range map[string]*store.Job{
		"a claimed job":    {ID: "job_1", PoolID: p.ID, Matched: true, Labels: []string{"self-hosted", "gpu"}},
		"an unclaimed one": {ID: "job_2", Labels: []string{"self-hosted", "tpu"}},
	} {
		if got, want := h.c.jobViewIn(h.ctx, job, pools), h.c.jobView(h.ctx, job); !reflect.DeepEqual(got, want) {
			t.Errorf("%s: the view from the pools in hand is\n%+v\nwant what a plain read gives\n%+v", name, got, want)
		}
	}
}

package controller

import (
	"errors"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/store"
)

func kindsOfEvents(events []*store.JobEvent) []store.JobEventKind {
	out := make([]store.JobEventKind, 0, len(events))
	for _, e := range events {
		out = append(out, e.Kind)
	}
	return out
}

// runnerLostTotal reads the lost-runner counter back through the registry, the
// way a scrape would, so the test needs nothing the production code does not.
func (h *harness) runnerLostTotal() float64 {
	h.t.Helper()
	families, err := h.c.metrics.reg.Gather()
	if err != nil {
		h.t.Fatalf("Gather: %v", err)
	}
	total := 0.0
	for _, mf := range families {
		if mf.GetName() != "zoomies_jobs_runner_lost_total" {
			continue
		}
		for _, m := range mf.GetMetric() {
			total += m.GetCounter().GetValue()
		}
	}
	return total
}

func (h *harness) timeline(jobID string) []*store.JobEvent {
	h.t.Helper()
	events, err := h.c.JobEvents(h.ctx, jobID)
	if err != nil {
		h.t.Fatalf("JobEvents: %v", err)
	}
	return events
}

// The timeline is the answer to "what happened to my job?", and it has to stay
// honest under GitHub's delivery guarantees: at least once, and out of order. A
// redelivery must not add a line, and a completed job must say where it failed
// in the words of the step that failed.
func TestJobDeliveriesWriteTheTimelineOnceEach(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	labels := []string{"self-hosted", "linux", "x64", "demo"}

	h.deliverJob(jobEvent{Action: "queued", JobID: 7007, Name: "test", Workflow: "CI", Labels: labels})
	job, err := h.st.GetJobByGitHubID(h.ctx, 7007)
	if err != nil {
		t.Fatalf("GetJobByGitHubID: %v", err)
	}
	events := h.timeline(job.ID)
	if got := kindsOfEvents(events); !slices.Equal(got, []store.JobEventKind{store.JobEventQueued, store.JobEventClaimed}) {
		t.Fatalf("after queued: %v, want queued then claimed", got)
	}
	if !strings.Contains(events[0].Message, "CI / test") || !strings.Contains(events[0].Message, "acme/widgets") {
		t.Fatalf("queued entry does not name the job: %q", events[0].Message)
	}
	if !strings.Contains(events[1].Message, pool.Name) || events[1].Source != sourceWebhook {
		t.Fatalf("claimed entry = %+v, want the pool named and the webhook as source", events[1])
	}

	// GitHub sends the same delivery again.
	h.deliverJob(jobEvent{Action: "queued", JobID: 7007, Name: "test", Workflow: "CI", Labels: labels})
	if got := h.timeline(job.ID); len(got) != 2 {
		t.Fatalf("a redelivered queued added a timeline entry: %v", kindsOfEvents(got))
	}

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	r := h.onlyRunner()
	mustReport(t, h, host.ID, r.ID, store.RunnerRegistering)
	mustReportRunning(t, h, host.ID, r.ID)

	h.deliverJob(jobEvent{Action: "in_progress", JobID: 7007, Name: "test", Workflow: "CI", Labels: labels, RunnerName: r.Name})
	events = h.timeline(job.ID)
	if got := kindsOfEvents(events); !slices.Equal(got, []store.JobEventKind{store.JobEventQueued, store.JobEventClaimed, store.JobEventStarted}) {
		t.Fatalf("after in_progress: %v", got)
	}
	started := events[2]
	if !strings.Contains(started.Message, r.Name) || !strings.Contains(started.Message, host.Name) || started.RunnerID != r.ID {
		t.Fatalf("started entry = %+v, want the runner and its host named", started)
	}

	h.deliverJob(jobEvent{Action: "completed", JobID: 7007, Name: "test", Workflow: "CI", Labels: labels,
		RunnerName: r.Name, Conclusion: "failure", Steps: failingSteps()})
	events = h.timeline(job.ID)
	if got := kindsOfEvents(events); len(got) != 4 || got[3] != store.JobEventCompleted {
		t.Fatalf("after completed: %v", got)
	}
	if want := "failed at step 2, Run tests"; !strings.Contains(events[3].Message, want) {
		t.Fatalf("completed entry = %q, want it to say %q", events[3].Message, want)
	}

	// And the row itself carries what the drawer shows.
	job, _ = h.st.GetJobByGitHubID(h.ctx, 7007)
	if step := job.FailedStep(); step == nil || step.Name != "Run tests" {
		t.Fatalf("FailedStep = %+v", step)
	}
	view := h.c.jobView(h.ctx, job)
	if view.FailedStep == nil || view.FailedStep.Number != 2 || len(view.Steps) != 3 {
		t.Fatalf("job view = %+v, want the failed step named and every step carried", view)
	}

	// A duplicate completed delivery is the commonest redelivery of all.
	h.deliverJob(jobEvent{Action: "completed", JobID: 7007, Name: "test", Workflow: "CI", Labels: labels,
		RunnerName: r.Name, Conclusion: "failure", Steps: failingSteps()})
	if got := h.timeline(job.ID); len(got) != 4 {
		t.Fatalf("a redelivered completed added a timeline entry: %v", kindsOfEvents(got))
	}
}

// An unmatched job says so on its timeline, and says when that changed: the
// operator who creates the missing pool should see the job claimed without
// having to work out which delivery did it.
func TestAnUnmatchedJobIsClaimedWhenAPoolAppears(t *testing.T) {
	h := newHarness(t)
	inst, _, _ := h.fleet()
	labels := []string{"self-hosted", "linux", "gpu"}

	h.deliverJob(jobEvent{Action: "queued", JobID: 8008, Labels: labels})
	job, err := h.st.GetJobByGitHubID(h.ctx, 8008)
	if err != nil {
		t.Fatalf("GetJobByGitHubID: %v", err)
	}
	events := h.timeline(job.ID)
	if got := kindsOfEvents(events); !slices.Equal(got, []store.JobEventKind{store.JobEventQueued, store.JobEventUnmatched}) {
		t.Fatalf("timeline = %v, want queued then unmatched", got)
	}
	if !strings.Contains(events[1].Message, "no enabled pool") {
		t.Fatalf("unmatched entry does not explain itself: %q", events[1].Message)
	}

	gpu := h.pool(inst, "gpu", labels...)
	// GitHub redelivers, or the poller re-lists the queue; either way the
	// same payload arrives again and this time a pool answers it.
	h.deliverJob(jobEvent{Action: "queued", JobID: 8008, Labels: labels})
	events = h.timeline(job.ID)
	if got := kindsOfEvents(events); !slices.Equal(got, []store.JobEventKind{store.JobEventQueued, store.JobEventUnmatched, store.JobEventClaimed}) {
		t.Fatalf("timeline = %v, want a claimed entry added", got)
	}
	if !strings.Contains(events[2].Message, gpu.Name) {
		t.Fatalf("claimed entry = %q, want the new pool named", events[2].Message)
	}
}

// startJobOnRunner takes a job from queued to running on a runner this fleet
// started, the way the real sequence does.
func startJobOnRunner(t *testing.T, h *harness, hostID string, jobID int64, labels []string) (*store.Job, *store.Runner) {
	t.Helper()
	h.deliverJob(jobEvent{Action: "queued", JobID: jobID, Name: "test", Workflow: "CI", Labels: labels})
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	// The pass detaches the credential call that finishes creating the runner. Until it
	// has returned the runner's row is still being written, and a test that changes the
	// runner's state first (a drain, say) races it: on a loaded machine the call lands
	// late, finds the runner draining and removes it as a late credential for a runner
	// nobody wants -- which is the right thing for it to do, and not what the test is about.
	h.c.lifecycleCalls.Wait()
	r := h.onlyRunner()
	mustReport(t, h, hostID, r.ID, store.RunnerRegistering)
	mustReportRunning(t, h, hostID, r.ID)
	h.deliverJob(jobEvent{Action: "in_progress", JobID: jobID, Name: "test", Workflow: "CI", Labels: labels, RunnerName: r.Name})
	job, err := h.st.GetJobByGitHubID(h.ctx, jobID)
	if err != nil {
		t.Fatalf("GetJobByGitHubID: %v", err)
	}
	if job.RunnerID != r.ID {
		t.Fatalf("the job was not linked to runner %s", r.ID)
	}
	return job, r
}

// A runner that dies under a job produces a failure GitHub cannot tell from a
// test failure. The job has to say the fleet did it: on the row, on the
// timeline, in the problems drawer, and in the failed filter -- before GitHub
// has even noticed.
func TestARunnerFailingUnderItsJobIsRecordedOnTheJob(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	labels := []string{"self-hosted", "linux", "x64", "demo"}
	job, r := startJobOnRunner(t, h, host.ID, 9009, labels)

	err := h.c.ReportRunners(h.ctx, host.ID, []agent.RunnerReport{{
		RunnerID: r.ID, State: store.RunnerFailed, ExitCode: 137,
		Message:    "runner exited with code 137: the container was killed for exceeding its memory limit",
		ObservedAt: time.Now(),
	}})
	if err != nil {
		t.Fatalf("ReportRunners: %v", err)
	}

	after, err := h.st.GetJob(h.ctx, job.ID)
	if err != nil {
		t.Fatalf("GetJob: %v", err)
	}
	if after.State != store.JobInProgress {
		t.Fatalf("job state = %q; GitHub has not said the job is over, so Zoomies must not", after.State)
	}
	if !strings.Contains(after.RunnerFault, r.Name) || !strings.Contains(after.RunnerFault, "code 137") {
		t.Fatalf("runner fault = %q, want the runner named and the agent's message kept", after.RunnerFault)
	}

	events := h.timeline(job.ID)
	last := events[len(events)-1]
	if last.Kind != store.JobEventRunnerLost || last.Source != sourceAgent || last.RunnerID != r.ID {
		t.Fatalf("last timeline entry = %+v, want runner_lost from the agent", last)
	}

	// The agent reports the same exit again -- a runner report and then the
	// task result that carries it both arrive -- and the failed runner is
	// terminal, so the second report is dropped by the state machine. The
	// job must still carry exactly one line and one count for it.
	before := h.runnerLostTotal()
	if before != 1 {
		t.Fatalf("zoomies_jobs_runner_lost_total = %v after one lost runner, want 1", before)
	}
	h.c.noteRunnerLost(h.ctx, r, sourceAgent, "runner exited with code 137: reported again", store.FaultOutOfMemory)
	if got := h.timeline(job.ID); len(got) != len(events) {
		t.Fatalf("a repeated report added a timeline entry: %v", kindsOfEvents(got))
	}
	if after := h.runnerLostTotal(); after != before {
		t.Fatalf("a repeated report counted the runner as lost again: %v -> %v", before, after)
	}
	if again, _ := h.st.GetJob(h.ctx, job.ID); !strings.Contains(again.RunnerFault, "memory limit") {
		t.Fatalf("a repeated report replaced the first fault: %q", again.RunnerFault)
	}

	if codes := h.problemCodes(); !slices.Contains(codes, "jobs.runner_lost") {
		t.Fatalf("problems = %v, want jobs.runner_lost", codes)
	}
	failed, total, err := h.st.ListJobs(h.ctx, store.JobFilter{FailedOnly: true}, store.Page{})
	if err != nil {
		t.Fatalf("ListJobs: %v", err)
	}
	if total != 1 || failed[0].ID != job.ID {
		t.Fatalf("failed jobs = %+v, want the orphaned job before GitHub reports it", failed)
	}

	// GitHub catches up, and the completed entry says the fleet's part in it.
	h.deliverJob(jobEvent{Action: "completed", JobID: 9009, Name: "test", Workflow: "CI", Labels: labels,
		RunnerName: r.Name, Conclusion: "failure"})
	events = h.timeline(job.ID)
	done := events[len(events)-1]
	if done.Kind != store.JobEventCompleted || !strings.Contains(done.Message, "the runner had stopped under it") {
		t.Fatalf("completed entry = %+v", done)
	}
	if after, _ = h.st.GetJob(h.ctx, job.ID); after.RunnerFault == "" {
		t.Fatal("the completed delivery erased the fault")
	}
}

// An ephemeral runner exits after every job, and GitHub's completed delivery
// races the agent noticing. A clean exit is never a fault, whichever arrives
// first -- or every finished job would be reported as a runner lost.
func TestACleanExitUnderAJobIsNotAFault(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	labels := []string{"self-hosted", "linux", "x64", "demo"}
	job, r := startJobOnRunner(t, h, host.ID, 1010, labels)

	err := h.c.ReportRunners(h.ctx, host.ID, []agent.RunnerReport{{
		RunnerID: r.ID, State: store.RunnerRemoved, Message: "ephemeral runner exited cleanly after its job", ObservedAt: time.Now(),
	}})
	if err != nil {
		t.Fatalf("ReportRunners: %v", err)
	}
	after, _ := h.st.GetJob(h.ctx, job.ID)
	if after.RunnerFault != "" {
		t.Fatalf("a clean exit was recorded as a fault: %q", after.RunnerFault)
	}
	for _, e := range h.timeline(job.ID) {
		if e.Kind == store.JobEventRunnerLost {
			t.Fatalf("a clean exit wrote a runner_lost entry: %+v", e)
		}
	}
	if codes := h.problemCodes(); slices.Contains(codes, "jobs.runner_lost") {
		t.Fatalf("problems = %v; a clean exit is not a lost runner", codes)
	}
}

// Force-removing a busy runner is the operator's decision, and the job it was
// running is the one that pays for it. The job's timeline should say so rather
// than leaving GitHub's "failure" to be blamed on the tests.
func TestForceRemovingABusyRunnerIsRecordedOnItsJob(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	labels := []string{"self-hosted", "linux", "x64", "demo"}
	job, r := startJobOnRunner(t, h, host.ID, 1111, labels)

	if _, err := h.c.RemoveRunner(h.ctx, r.ID, "removed by an operator", true, false); err != nil {
		t.Fatalf("RemoveRunner: %v", err)
	}
	after, _ := h.st.GetJob(h.ctx, job.ID)
	if !strings.Contains(after.RunnerFault, "removed by an operator") {
		t.Fatalf("runner fault = %q, want the operator's reason", after.RunnerFault)
	}
	// The agent did not see this one go; the controller did it, and the
	// timeline says so rather than blaming the host.
	events := h.timeline(job.ID)
	if last := events[len(events)-1]; last.Kind != store.JobEventRunnerLost || last.Source != sourceController {
		t.Fatalf("last timeline entry = %+v, want runner_lost from the controller", last)
	}

	// Without force the runner drains, the job keeps running, and nothing is
	// written against it.
	h2 := newHarness(t)
	_, _, host2 := h2.fleet()
	job2, r2 := startJobOnRunner(t, h2, host2.ID, 1212, labels)
	if _, err := h2.c.RemoveRunner(h2.ctx, r2.ID, "removed by an operator", false, true); err != nil {
		t.Fatalf("RemoveRunner without force: %v", err)
	}
	if after2, _ := h2.st.GetJob(h2.ctx, job2.ID); after2.RunnerFault != "" {
		t.Fatalf("a drain was recorded as a fault: %q", after2.RunnerFault)
	}
}

func TestCompletionMessagesReadAsSentences(t *testing.T) {
	started := time.Date(2026, 1, 1, 10, 0, 0, 0, time.UTC)
	done := started.Add(3*time.Minute + 10*time.Second)
	base := store.Job{State: store.JobCompleted, StartedAt: &started, CompletedAt: &done}
	cases := []struct {
		name string
		mod  func(j *store.Job)
		want string
	}{
		{"success", func(j *store.Job) { j.Conclusion = "success" }, "succeeded after 3m 10s"},
		{"failure without steps", func(j *store.Job) { j.Conclusion = "failure" }, "failed after 3m 10s"},
		{"failure at a step", func(j *store.Job) {
			j.Conclusion = "failure"
			j.Steps = store.JobSteps{{Number: 1, Name: "Checkout", Conclusion: "success"}, {Number: 2, Name: "Run tests", Conclusion: "failure"}}
		}, "failed at step 2, Run tests, after 3m 10s"},
		{"timed out", func(j *store.Job) { j.Conclusion = "timed_out" }, "timed out after 3m 10s"},
		{"cancelled", func(j *store.Job) { j.Conclusion = "cancelled" }, "cancelled after 3m 10s"},
		{"runner lost", func(j *store.Job) { j.Conclusion = "failure"; j.RunnerFault = "x" }, "the runner had stopped under it"},
	}
	for _, tc := range cases {
		j := base
		tc.mod(&j)
		if got := completionMessage(&j); !strings.Contains(got, tc.want) {
			t.Errorf("%s: %q does not contain %q", tc.name, got, tc.want)
		}
	}
	if got := roundDuration(90 * time.Minute); got != "1h 30m" {
		t.Errorf("roundDuration(90m) = %q", got)
	}
}

// A job GitHub holds for a deployment review spends that time on GitHub, not
// in the queue. The timeline says so, and the approval is the moment the queue
// wait and the claim start, so a redelivered approval must not repeat either.
func TestAHeldJobsTimelineSaysWhoItWasWaitingFor(t *testing.T) {
	h := newHarness(t)
	_, pool, _ := h.fleet()
	labels := []string{"self-hosted", "linux", "x64", "demo"}

	h.deliverJob(jobEvent{Action: "waiting", JobID: 8201, Name: "deploy", Workflow: "Release", Labels: labels})
	job, err := h.st.GetJobByGitHubID(h.ctx, 8201)
	if err != nil {
		t.Fatalf("GetJobByGitHubID: %v", err)
	}
	events := h.timeline(job.ID)
	if got := kindsOfEvents(events); !slices.Equal(got, []store.JobEventKind{store.JobEventWaiting}) {
		t.Fatalf("after waiting: %v, want one waiting entry and no queued one", got)
	}
	if !strings.Contains(events[0].Message, "deployment review") || !strings.Contains(events[0].Message, "Release / deploy") {
		t.Fatalf("waiting entry does not say who is holding the job: %q", events[0].Message)
	}

	h.deliverJob(jobEvent{Action: "queued", JobID: 8201, Name: "deploy", Workflow: "Release", Labels: labels})
	events = h.timeline(job.ID)
	if got := kindsOfEvents(events); !slices.Equal(got, []store.JobEventKind{store.JobEventWaiting, store.JobEventApproved, store.JobEventClaimed}) {
		t.Fatalf("after approval: %v, want waiting, approved, then the claim", got)
	}
	if !strings.Contains(events[1].Message, "approved") || !strings.Contains(events[2].Message, pool.Name) {
		t.Fatalf("approval entries = %q, %q; want the approval said and the pool named", events[1].Message, events[2].Message)
	}

	// GitHub sends the approval again.
	h.deliverJob(jobEvent{Action: "queued", JobID: 8201, Name: "deploy", Workflow: "Release", Labels: labels})
	if got := h.timeline(job.ID); len(got) != 3 {
		t.Fatalf("a redelivered approval added a timeline entry: %v", kindsOfEvents(got))
	}
}

// Acknowledging a failure is the fleet's triage record, so it has to be
// visible on the job's own timeline, name the person who looked, and stay put
// under a second press. Reopening is the undo, and it says so too. Neither
// changes the failure: the conclusion and the row are exactly what they were.
func TestAcknowledgingAFailureIsRecordedOnceWithTheFirstName(t *testing.T) {
	h := newHarness(t)
	done := time.Now().UTC().Add(-time.Minute)
	job, err := h.st.UpsertJob(h.ctx, &store.Job{
		GitHubJobID: 9001, GitHubRunID: 44, Repo: "acme/widgets", Workflow: "CI", JobName: "test",
		State: store.JobCompleted, Conclusion: "failure",
		QueuedAt: done.Add(-time.Minute), CompletedAt: &done,
	})
	if err != nil {
		t.Fatalf("UpsertJob: %v", err)
	}

	got, recorded, err := h.c.AcknowledgeJob(h.ctx, job.ID, "alice")
	if err != nil || !recorded {
		t.Fatalf("AcknowledgeJob recorded = %v (err %v), want the first press to be the one that recorded", recorded, err)
	}
	if got.AcknowledgedAt == nil || got.AcknowledgedBy != "alice" {
		t.Fatalf("acknowledgement = %+v, want alice named", got)
	}
	if got.Conclusion != "failure" || got.State != store.JobCompleted {
		t.Fatalf("acknowledging changed the job: %+v", got)
	}
	events := h.timeline(job.ID)
	last := events[len(events)-1]
	if last.Kind != store.JobEventAcknowledged || !strings.Contains(last.Message, "alice") {
		t.Fatalf("timeline entry = %+v, want an acknowledged entry naming alice", last)
	}

	got, recorded, err = h.c.AcknowledgeJob(h.ctx, job.ID, "bob")
	if err != nil || recorded {
		t.Fatalf("second AcknowledgeJob recorded = %v (err %v), want a press that changed nothing to say so", recorded, err)
	}
	if got.AcknowledgedBy != "alice" {
		t.Fatalf("a second acknowledgement replaced the first: %+v", got)
	}
	if entries := h.timeline(job.ID); len(entries) != len(events) {
		t.Fatalf("a second acknowledgement added a timeline entry: %v", kindsOfEvents(entries))
	}

	got, recorded, err = h.c.ReopenJobAttention(h.ctx, job.ID, "bob")
	if err != nil || !recorded {
		t.Fatalf("ReopenJobAttention recorded = %v (err %v), want the acknowledgement taken back", recorded, err)
	}
	if got.AcknowledgedAt != nil || got.AcknowledgedBy != "" {
		t.Fatalf("reopening left an acknowledgement behind: %+v", got)
	}
	events = h.timeline(job.ID)
	last = events[len(events)-1]
	if last.Kind != store.JobEventReopened || !strings.Contains(last.Message, "bob") {
		t.Fatalf("timeline entry = %+v, want a reopened entry naming bob", last)
	}
	if _, recorded, err := h.c.ReopenJobAttention(h.ctx, job.ID, "bob"); err != nil || recorded {
		t.Fatalf("second ReopenJobAttention recorded = %v (err %v), want a press that changed nothing to say so", recorded, err)
	}
	if entries := h.timeline(job.ID); len(entries) != len(events) {
		t.Fatalf("reopening twice added a timeline entry: %v", kindsOfEvents(entries))
	}
	if _, _, err := h.st.AcknowledgeJob(h.ctx, job.ID, "alice"); err != nil {
		t.Fatalf("acknowledging after reopening: %v", err)
	}

	// A job that has not failed has nothing to triage yet.
	queued, err := h.st.UpsertJob(h.ctx, &store.Job{GitHubJobID: 9002, State: store.JobQueued})
	if err != nil {
		t.Fatalf("UpsertJob queued: %v", err)
	}
	if _, _, err := h.c.AcknowledgeJob(h.ctx, queued.ID, "alice"); !errors.Is(err, ErrJobDidNotFail) {
		t.Fatalf("acknowledging a queued job: %v, want ErrJobDidNotFail", err)
	}
}

package controller

import (
	"context"
	"fmt"
	"sort"
	"sync"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// Two things an operator looking at the numbers sees that nothing in the controller
// said: a workflow that fails at the same step every time it runs, and a job that
// has got much slower than it was. Neither is the fleet's fault by itself, and
// neither has a change the controller can make -- so both are information, with no
// remedy, and both say whose to fix and what to look at. They exist because the
// person who owns the workflow is not always the person watching the fleet, and the
// fleet is the one place both the failures and the timings are already recorded.

const (
	// failingWindow is how far back a failure counts; failingRuns is how many at
	// the same step make it a pattern rather than a bad commit.
	failingWindow = 6 * time.Hour
	failingRuns   = 3

	// slowerRecent is the window a job's typical time is read over, and slowerBase
	// the week before it that it is compared with. A day against a week, so one
	// busy morning on a shared host is not a regression.
	slowerRecent = 24 * time.Hour
	slowerBase   = 7 * 24 * time.Hour
	// slowerMinJobs is how many measured runs each side needs: a median of three is
	// not evidence. slowerRatio and slowerMinGain are both required, so a one-second
	// job that doubled and a long job that crept up a few percent are both left alone.
	slowerMinJobs = 10
	slowerRatio   = 1.5
	slowerMinGain = 60 * time.Second
)

// slowerFor is how long what the slower-job check found is reused. It reads eight
// days of jobs, which is the dearest thing a pass that someone is watching does
// (about two thirds of one over 10,000 jobs, and more of it the more jobs there
// are), and it sets a day of runs against the week before, which a minute moves
// very little. The rest of the problems list is worked out afresh for every
// request (see problems_flight.go); this check is up to a minute old.
const slowerFor = time.Minute

// slowerMemo is what the slower-job check last found, and when it read the jobs.
type slowerMemo struct {
	mu    sync.Mutex
	read  time.Time
	found []Problem
}

// workflowFailingProblems is jobs.workflow_failing: a job that failed at the same
// step failingRuns times or more in the window and did not succeed once.
func (c *Controller) workflowFailingProblems(ctx context.Context, out *[]Problem) error {
	since := c.Now().Add(-failingWindow)
	base := store.JobFilter{Since: &since, States: []store.JobState{store.JobCompleted}}

	failed := base
	failed.Conclusions = []string{"failure"}
	bad, _, err := c.st.ListJobs(ctx, failed, store.Page{Limit: 500, Sort: "completed_at", Desc: true})
	if err != nil {
		return fmt.Errorf("listing failed jobs: %w", err)
	}
	if len(bad) < failingRuns {
		return nil
	}
	succeeded := base
	succeeded.Conclusions = []string{"success"}
	good, _, err := c.st.ListJobs(ctx, succeeded, store.Page{Limit: 500})
	if err != nil {
		return fmt.Errorf("listing jobs that passed: %w", err)
	}
	passed := map[string]bool{}
	for _, j := range good {
		passed[jobKey(j)] = true
	}

	type pattern struct {
		jobs []*store.Job
		step string
	}
	byStep := map[string]*pattern{}
	for _, j := range bad {
		if passed[jobKey(j)] {
			continue
		}
		step := "(no step recorded)"
		if st := j.FailedStep(); st != nil {
			step = st.Name
		}
		k := jobKey(j) + "\x00" + step
		if byStep[k] == nil {
			byStep[k] = &pattern{step: step}
		}
		byStep[k].jobs = append(byStep[k].jobs, j)
	}
	var patterns []*pattern
	for _, p := range byStep {
		if len(p.jobs) >= failingRuns {
			patterns = append(patterns, p)
		}
	}
	// Most failures first, then by name, so the list does not reorder between passes.
	sort.Slice(patterns, func(i, j int) bool {
		if len(patterns[i].jobs) != len(patterns[j].jobs) {
			return len(patterns[i].jobs) > len(patterns[j].jobs)
		}
		return jobKey(patterns[i].jobs[0]) < jobKey(patterns[j].jobs[0])
	})
	for _, p := range patterns {
		latest := p.jobs[0]
		where := "on this fleet's runners"
		fix := "open the failing step's log in the run, which is the workflow's own: the fleet did nothing wrong here."
		if hostedJob(latest.Labels) {
			where = "on GitHub's hosted runners, not this fleet's"
			fix = "open the failing step's log in the run: this fleet only saw the job, because GitHub runs it. If its output is a missing file or an expired token the fix is in the workflow or the repository's settings."
		}
		*out = append(*out, Problem{
			Code:     "jobs.workflow_failing",
			Severity: config.SeverityInfo,
			Title: fmt.Sprintf("%s in %s has failed at %s %d times in a row",
				workflowText(latest.JobName), workflowText(latest.Repo), workflowText(p.step), len(p.jobs)),
			Detail: fmt.Sprintf("%d runs in the last %s failed at that step and none of the job's runs passed, %s. Workflow %s.",
				len(p.jobs), failingWindow, where, workflowText(latest.Workflow)),
			Fix:        fix,
			TargetKind: "job", TargetID: latest.ID, Since: latest.CompletedAt,
		})
	}
	return nil
}

func jobKey(j *store.Job) string { return j.Repo + "\x00" + j.Workflow + "\x00" + j.JobName }

// jobsSlowerProblems is jobs.duration_regressed: a job whose typical run over the
// last day took at least half as long again, and a minute more, than over the week
// before, on the jobs this fleet ran. It reads the jobs at most once in slowerFor.
func (c *Controller) jobsSlowerProblems(ctx context.Context, out *[]Problem) error {
	m := &c.slower
	// Held while the jobs are read, so a request that arrives meanwhile waits for
	// the answer and does not read them a second time.
	m.mu.Lock()
	defer m.mu.Unlock()
	now := c.Now()
	// A clock that has gone back is no reason to trust what was found before it.
	if !m.read.IsZero() && !now.Before(m.read) && now.Sub(m.read) < slowerFor {
		*out = append(*out, m.found...)
		return nil
	}
	var found []Problem
	if err := c.readSlowerJobs(ctx, &found); err != nil {
		// Not kept: the next request reads the jobs again.
		return err
	}
	m.read, m.found = now, found
	*out = append(*out, found...)
	return nil
}

// readSlowerJobs reads the last day of jobs and the week before it, and says which
// jobs got slower.
func (c *Controller) readSlowerJobs(ctx context.Context, out *[]Problem) error {
	now := c.Now()
	recentFrom, baseFrom := now.Add(-slowerRecent), now.Add(-slowerRecent-slowerBase)
	read := func(from, until time.Time) (map[string]store.JobStatsGroup, error) {
		res, err := c.st.JobStatsOf(ctx, store.JobFilter{Since: &from, Until: &until, ManagedOnly: true}, []string{store.GroupByJobName}, store.MeasureDuration)
		if err != nil {
			return nil, fmt.Errorf("reading how long jobs took: %w", err)
		}
		byName := map[string]store.JobStatsGroup{}
		for _, g := range res.Groups {
			byName[g.Keys[store.GroupByJobName]] = g
		}
		return byName, nil
	}
	recent, err := read(recentFrom, now.Add(time.Minute))
	if err != nil {
		return err
	}
	baseline, err := read(baseFrom, recentFrom)
	if err != nil {
		return err
	}
	var names []string
	for name := range recent {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		r, b := recent[name], baseline[name]
		if name == "" || r.Duration.Samples < slowerMinJobs || b.Duration.Samples < slowerMinJobs || r.Duration.P50MS == nil || b.Duration.P50MS == nil {
			continue
		}
		now, was := time.Duration(*r.Duration.P50MS)*time.Millisecond, time.Duration(*b.Duration.P50MS)*time.Millisecond
		if was <= 0 || float64(now) < slowerRatio*float64(was) || now-was < slowerMinGain {
			continue
		}
		*out = append(*out, Problem{
			Code:     "jobs.duration_regressed",
			Severity: config.SeverityInfo,
			Title: fmt.Sprintf("%s now takes %s, up from %s",
				workflowText(name), now.Round(time.Second), was.Round(time.Second)),
			Detail: fmt.Sprintf("the typical run of this job over the last %s took %s across %d runs, against %s across %d runs in the %s before. "+
				"The fleet's own failures and memory use are on the Jobs page; this is the job taking longer, whatever the cause.",
				slowerRecent, now.Round(time.Second), r.Duration.Samples, was.Round(time.Second), b.Duration.Samples, slowerBase),
			Fix: "compare a recent run with an older one on the Jobs page: a step that grew points at the workflow or its dependencies, and every step slower together points at the host, " +
				"so group the job's runs by host and by controller version (job_stats, or the Jobs page's filters) to tell which.",
		})
	}
	return nil
}

package controller

import (
	"context"
	"sync"
	"testing"
	"time"
)

// The slower-job check reads eight days of jobs, which is most of what a pass that
// someone is watching does on a fleet with a lot of them, and what it finds does
// not change in a minute, so it keeps its answer for slowerFor. Everything else in
// the problems list is worked out afresh for each request, so these hold the
// exception to what it promises and no further: the answer lasts the minute and
// not longer, a failure is not kept, and nobody is handed the copy the next
// caller reads.

const slowerCode = "jobs.duration_regressed"

// seedRegression is a job that took five minutes two days ago and eleven in the last
// twelve hours, which is the shape the check reports.
func seedRegression(t *testing.T, h *harness, inst string) {
	t.Helper()
	n := int64(1000)
	for i := 0; i < 12; i++ {
		n++
		seedJob(t, h, inst, n, "Go (api)", "success", 2*24*time.Hour+time.Duration(i)*time.Hour, 5*time.Minute, "")
		n++
		seedJob(t, h, inst, n, "Go (api)", "success", time.Duration(i+1)*time.Hour, 11*time.Minute, "")
	}
}

// seedRecovery is forty more runs of the same job in the last day that took the five
// minutes it used to, which put its typical time back and end the regression.
func seedRecovery(t *testing.T, h *harness, inst string) {
	t.Helper()
	for i := 0; i < 40; i++ {
		seedJob(t, h, inst, int64(2000+i), "Go (api)", "success", 13*time.Hour+time.Duration(i)*time.Minute, 5*time.Minute, "")
	}
}

// forgetSlowerJobs makes the next slower-job check read the jobs, as it does a
// minute after the last time.
func forgetSlowerJobs(c *Controller) {
	c.slower.mu.Lock()
	defer c.slower.mu.Unlock()
	c.slower.read = time.Time{}
}

// slowerReadAt is when the slower-job check last read the jobs.
func slowerReadAt(c *Controller) time.Time {
	c.slower.mu.Lock()
	defer c.slower.mu.Unlock()
	return c.slower.read
}

// checkSlowerMix fails a benchmark that is about to time passes with the mix it
// says it times: one pass that reads the jobs for every five that reuse what it
// found. Without it a memo that never forgot, or one that never kept anything,
// would be timed under the same name.
func checkSlowerMix(b *testing.B, h *harness) {
	b.Helper()
	before := slowerReadAt(h.c)
	forgetSlowerJobs(h.c)
	if err := h.c.Reconcile(h.ctx); err != nil {
		b.Fatalf("Reconcile: %v", err)
	}
	read := slowerReadAt(h.c)
	if !read.After(before) {
		b.Fatal("a pass after the slower-job check was made to forget did not read the jobs again")
	}
	if err := h.c.Reconcile(h.ctx); err != nil {
		b.Fatalf("Reconcile: %v", err)
	}
	if !slowerReadAt(h.c).Equal(read) {
		b.Fatal("the pass after one that read the jobs read them again, so five passes in six are not the cheap ones")
	}
}

func TestWhatTheSlowerJobCheckFoundIsReusedForAMinuteAndNoLonger(t *testing.T) {
	h := newHarness(t)
	inst := h.installation().ID
	seedRegression(t, h, inst)
	if h.problemOrNil(slowerCode) == nil {
		t.Fatal("a job that got much slower was not said to be")
	}

	// The jobs now say it has recovered, but what was found is reused for the minute.
	seedRecovery(t, h, inst)
	h.offset.Add(int64(slowerFor - time.Second))
	if h.problemOrNil(slowerCode) == nil {
		t.Error("the jobs were read again before the minute was up")
	}

	h.offset.Add(int64(2 * time.Second))
	if p := h.problemOrNil(slowerCode); p != nil {
		t.Errorf("after the minute the check still said %q, though the jobs say the job has recovered", p.Title)
	}
}

// The jobs are read again after a failure, and the failure is not what is reused:
// an answer of nothing, kept for a minute, would hide a regression for that long.
func TestAFailedReadOfTheJobsIsNotKeptByTheSlowerJobCheck(t *testing.T) {
	h := newHarness(t)
	inst := h.installation().ID
	seedRegression(t, h, inst)

	cancelled, cancel := context.WithCancel(h.ctx)
	cancel()
	var out []Problem
	if err := h.c.jobsSlowerProblems(cancelled, &out); err == nil {
		t.Fatal("a read with a cancelled context said it worked")
	}
	if len(out) != 0 {
		t.Errorf("a failed read added %d problems", len(out))
	}
	if h.problemOrNil(slowerCode) == nil {
		t.Error("the check reused the failure and did not read the jobs again")
	}
}

func TestEachCallerOfTheSlowerJobCheckGetsItsOwnCopy(t *testing.T) {
	h := newHarness(t)
	inst := h.installation().ID
	seedRegression(t, h, inst)

	var first, second []Problem
	if err := h.c.jobsSlowerProblems(h.ctx, &first); err != nil || len(first) != 1 {
		t.Fatalf("the first call gave %d problems, err = %v; want 1", len(first), err)
	}
	first[0].Title = "changed by the first caller"
	if err := h.c.jobsSlowerProblems(h.ctx, &second); err != nil || len(second) != 1 {
		t.Fatalf("the second call gave %d problems, err = %v; want 1", len(second), err)
	}
	if second[0].Title == first[0].Title {
		t.Error("the second caller was handed the first caller's copy")
	}

	// It adds to what the caller has, and does not replace it.
	out := []Problem{{Code: "already.there"}}
	if err := h.c.jobsSlowerProblems(h.ctx, &out); err != nil || len(out) != 2 || out[0].Code != "already.there" || out[1].Code != slowerCode {
		t.Errorf("appending to a list gave %+v, err = %v", out, err)
	}
}

// A clock that is put back, by an operator or by the network time service, is not a
// reason to go on trusting an answer from before it: the minute is measured from a
// moment that, as far as the clock now says, has not come yet.
func TestTheSlowerJobCheckReadsAgainWhenTheClockGoesBack(t *testing.T) {
	h := newHarness(t)
	inst := h.installation().ID
	seedRegression(t, h, inst)
	if h.problemOrNil(slowerCode) == nil {
		t.Fatal("a job that got much slower was not said to be")
	}
	seedRecovery(t, h, inst)

	h.offset.Add(-int64(time.Hour))
	if p := h.problemOrNil(slowerCode); p != nil {
		t.Errorf("an answer from an hour in the future was reused: %q", p.Title)
	}
}

// Callers that arrive together read the jobs once between them, and all get the answer.
func TestCallersOfTheSlowerJobCheckThatArriveTogetherAllGetTheAnswer(t *testing.T) {
	h := newHarness(t)
	inst := h.installation().ID
	seedRegression(t, h, inst)

	const callers = 8
	got := make([][]Problem, callers)
	errs := make([]error, callers)
	var wg sync.WaitGroup
	for i := range got {
		wg.Add(1)
		go func() {
			defer wg.Done()
			errs[i] = h.c.jobsSlowerProblems(h.ctx, &got[i])
		}()
	}
	wg.Wait()
	for i := range got {
		if errs[i] != nil || len(got[i]) != 1 || got[i][0].Code != slowerCode {
			t.Errorf("caller %d got %+v, err = %v; want the one problem", i, got[i], errs[i])
		}
	}
}

package controller

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// seedJob completes a job of the given name at an offset into the past, with the
// steps it ran, which is all the trend problems read.
func seedJob(t *testing.T, h *harness, inst string, id int64, name, conclusion string, ago, took time.Duration, failedStep string, labels ...string) {
	t.Helper()
	if len(labels) == 0 {
		labels = []string{"self-hosted", "linux", "x64"}
	}
	queued := h.c.Now().Add(-ago)
	started, done := queued.Add(2*time.Second), queued.Add(2*time.Second+took)
	job := &store.Job{
		GitHubJobID: id, GitHubRunID: id, Repo: "acme/widgets", Workflow: "ci", JobName: name, Labels: store.StringSlice(labels),
		State: store.JobCompleted, Conclusion: conclusion, Matched: true, InstallationID: inst,
		QueuedAt: queued, StartedAt: &started, CompletedAt: &done,
	}
	if failedStep != "" {
		job.Steps = []store.JobStep{{Number: 1, Name: "Set up job", Conclusion: "success"}, {Number: 2, Name: failedStep, Conclusion: "failure"}}
	}
	if _, err := h.st.UpsertJob(h.ctx, job); err != nil {
		t.Fatal(err)
	}
}

// Three failures at the same step with nothing passing is the pattern worth
// saying; the same job passing once, or three different steps, is an ordinary bad day.
func TestAJobFailingAtTheSameStepRepeatedlyIsSaidOnceAsInformation(t *testing.T) {
	h := newHarness(t)
	inst := h.installation().ID
	for i := 0; i < 3; i++ {
		seedJob(t, h, inst, int64(100+i), "generate", "failure", time.Duration(i+1)*20*time.Minute, 20*time.Second, "Run actions/upload-artifact@v4")
	}
	p := h.problemOrNil("jobs.workflow_failing")
	if p == nil {
		t.Fatal("no jobs.workflow_failing problem")
	}
	if p.Remedy != nil || p.TargetKind != "job" {
		t.Errorf("problem = %+v; want information about a job with no remedy", p)
	}
	for _, want := range []string{"upload-artifact", "3 times"} {
		if !strings.Contains(p.Title+p.Detail, want) {
			t.Errorf("the problem should say %q: %s / %s", want, p.Title, p.Detail)
		}
	}
}

func TestAJobThatPassedSinceIsNotSaidToBeFailing(t *testing.T) {
	h := newHarness(t)
	inst := h.installation().ID
	for i := 0; i < 3; i++ {
		seedJob(t, h, inst, int64(200+i), "generate", "failure", time.Duration(i+2)*20*time.Minute, 20*time.Second, "Run actions/upload-artifact@v4")
	}
	seedJob(t, h, inst, 299, "generate", "success", 5*time.Minute, 30*time.Second, "")
	if p := h.problemOrNil("jobs.workflow_failing"); p != nil {
		t.Errorf("a job that has since passed was reported: %+v", p)
	}
}

func TestDifferentStepsAreNotOnePattern(t *testing.T) {
	h := newHarness(t)
	inst := h.installation().ID
	for i, step := range []string{"Build", "Test", "Lint"} {
		seedJob(t, h, inst, int64(300+i), "generate", "failure", time.Duration(i+1)*20*time.Minute, 20*time.Second, step)
	}
	if p := h.problemOrNil("jobs.workflow_failing"); p != nil {
		t.Errorf("three different failures were reported as one pattern: %+v", p)
	}
}

// A job that took twice as long as the week before is said; one that crept up a
// little, or has too few runs to tell, is not.
func TestAJobThatGotMuchSlowerIsSaidAsInformation(t *testing.T) {
	h := newHarness(t)
	inst := h.installation().ID
	n := int64(1000)
	for i := 0; i < 12; i++ {
		n++
		seedJob(t, h, inst, n, "Go (api)", "success", 2*24*time.Hour+time.Duration(i)*time.Hour, 5*time.Minute, "")
		n++
		seedJob(t, h, inst, n, "Go (api)", "success", time.Duration(i+1)*time.Hour, 11*time.Minute, "")
	}
	p := h.problemOrNil("jobs.duration_regressed")
	if p == nil {
		t.Fatal("no jobs.duration_regressed problem")
	}
	if p.Remedy != nil || !strings.Contains(p.Title, "Go (api)") || !strings.Contains(p.Title, "11m0s") || !strings.Contains(p.Title, "5m0s") {
		t.Errorf("problem = %+v", p)
	}
}

func TestAJobWithTooFewRunsOrTooSmallAChangeIsNotSaidToBeSlower(t *testing.T) {
	h := newHarness(t)
	inst := h.installation().ID
	n := int64(2000)
	// Few runs: a median of three says nothing.
	for i := 0; i < 3; i++ {
		n++
		seedJob(t, h, inst, n, "rare", "success", 2*24*time.Hour+time.Duration(i)*time.Hour, 5*time.Minute, "")
		n++
		seedJob(t, h, inst, n, "rare", "success", time.Duration(i+1)*time.Hour, 15*time.Minute, "")
	}
	// A big ratio on a tiny job: nobody waits for ten seconds going to twenty.
	for i := 0; i < 12; i++ {
		n++
		seedJob(t, h, inst, n, "tiny", "success", 2*24*time.Hour+time.Duration(i)*time.Hour, 10*time.Second, "")
		n++
		seedJob(t, h, inst, n, "tiny", "success", time.Duration(i+1)*time.Hour, 20*time.Second, "")
	}
	if p := h.problemOrNil("jobs.duration_regressed"); p != nil {
		t.Errorf("reported %+v", p)
	}
}

package controller

import (
	"time"

	"github.com/eyupio/zoomies/internal/github"
)

// kennelDefaultLimit is GitHub's primary limit for an App installation, which is
// what the budget is a share of until the installation has reported its own. A
// client that has never made a request has nothing to report, and the first
// request Kennel Club makes is what tells it.
const kennelDefaultLimit = 5000

// kennelReserveDivisor says what must be left whatever the budget is: a half
// (one over this). Below it Kennel Club stops altogether until the limit
// resets, because scaling, registration and the poller come first and have
// nothing to fall back on when the installation is nearly out.
const kennelReserveDivisor = 2

// kennelBudget is how much of one installation's hourly request limit Kennel
// Club has spent this hour.
//
// It is a rule and not a hope: the limit is shared with everything else this
// installation does -- the poller, every JIT configuration, the registration
// reap -- and a read that is slow to finish must not be able to starve them.
// Zoomies' own comments say the quota is "shared with every other call Zoomies
// makes", and the toolchain scan "does not ration itself"; this does.
//
// It is memory only, and cheap to lose: a restart forgets what was spent this
// hour, which at worst lets one hour spend its share twice, and the percentage
// is small enough that twice is still inside the limit.
type kennelBudget struct {
	window time.Time
	spent  int
}

// take reports whether one more request may start, and counts it if so.
//
// percent is the share of the limit this hour may spend, and rl is what the
// installation last reported. Every request is counted, including the ones
// GitHub answers "not modified", which cost nothing against its limit: the
// budget is Zoomies' own ceiling and a conservative count only makes it lower.
func (b *kennelBudget) take(now time.Time, percent int, rl github.RateLimit) bool {
	limit := rl.Limit
	if limit <= 0 {
		limit = kennelDefaultLimit
	}
	// Under half the limit left, and the reset not yet reached: stand down. A
	// reset time GitHub did not give is treated as not yet reached, because the
	// alternative is guessing that the quota came back.
	if rl.Limit > 0 && rl.Remaining < rl.Limit/kennelReserveDivisor && (rl.ResetAt.IsZero() || now.Before(rl.ResetAt)) {
		return false
	}
	if window := now.Truncate(time.Hour); !window.Equal(b.window) {
		b.window, b.spent = window, 0
	}
	if b.spent >= limit*percent/100 {
		return false
	}
	b.spent++
	return true
}

package controller

import (
	"errors"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/github"
)

// The budget is a share of what the installation last reported, and a limit
// nobody has reported yet is GitHub's own, so a fresh controller does not start
// with a budget of nothing.
func TestTheBudgetIsAShareOfTheLimitTheInstallationLastReported(t *testing.T) {
	now := time.Date(2026, 10, 6, 12, 10, 0, 0, time.UTC)
	for _, tc := range []struct {
		name    string
		percent int
		rl      github.RateLimit
		want    int
	}{
		{"nothing reported yet", 20, github.RateLimit{}, 1000},
		{"a larger limit", 20, github.RateLimit{Limit: 15000, Remaining: 15000, ResetAt: now.Add(time.Hour)}, 3000},
		{"the smallest share", 5, github.RateLimit{Limit: 5000, Remaining: 5000, ResetAt: now.Add(time.Hour)}, 250},
		{"the largest share", 50, github.RateLimit{Limit: 5000, Remaining: 5000, ResetAt: now.Add(time.Hour)}, 2500},
	} {
		t.Run(tc.name, func(t *testing.T) {
			var b kennelBudget
			got := 0
			for b.take(now, tc.percent, tc.rl) {
				got++
				if got > 100000 {
					t.Fatal("the budget never ran out")
				}
			}
			if got != tc.want {
				t.Errorf("%d requests allowed, want %d", got, tc.want)
			}
		})
	}
}

// What was spent is what was spent this hour: the next hour starts again. A
// budget that carried over would let a quiet night pay for a burst, which is the
// opposite of a ceiling.
func TestTheBudgetStartsAgainWhenTheHourTurns(t *testing.T) {
	rl := github.RateLimit{Limit: 5000, Remaining: 5000, ResetAt: time.Date(2026, 10, 6, 14, 0, 0, 0, time.UTC)}
	var b kennelBudget
	late := time.Date(2026, 10, 6, 12, 59, 59, 0, time.UTC)
	for i := 0; b.take(late, 5, rl); i++ {
		if i > 10000 {
			t.Fatal("the budget never ran out")
		}
	}
	if b.take(late, 5, rl) {
		t.Fatal("the budget was not spent")
	}
	if b.take(late.Add(-time.Minute), 5, rl) {
		t.Error("a request earlier in the same hour was allowed after the budget ran out")
	}
	if !b.take(late.Add(time.Second), 5, rl) {
		t.Error("the new hour did not start with a budget")
	}
}

// Under half the limit left is a stop, not a slowdown, until GitHub says the
// limit has reset. The poller, the JIT configurations and the registration reap
// have nothing else to draw on.
func TestKennelClubStopsWhenLessThanHalfTheLimitIsLeft(t *testing.T) {
	now := time.Date(2026, 10, 6, 12, 10, 0, 0, time.UTC)
	reset := now.Add(20 * time.Minute)
	for _, tc := range []struct {
		name string
		rl   github.RateLimit
		now  time.Time
		want bool
	}{
		{"exactly half left", github.RateLimit{Limit: 5000, Remaining: 2500, ResetAt: reset}, now, true},
		{"one under half", github.RateLimit{Limit: 5000, Remaining: 2499, ResetAt: reset}, now, false},
		{"almost none", github.RateLimit{Limit: 5000, Remaining: 3, ResetAt: reset}, now, false},
		{"low, but the reset has passed", github.RateLimit{Limit: 5000, Remaining: 3, ResetAt: reset}, reset, true},
		{"low and no reset time given", github.RateLimit{Limit: 5000, Remaining: 3}, now, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			var b kennelBudget
			if got := b.take(tc.now, 20, tc.rl); got != tc.want {
				t.Errorf("take = %v, want %v", got, tc.want)
			}
		})
	}
}

// A request that was refused is not a request that was made: a held budget does
// not spend itself down by being asked.
func TestARefusedRequestDoesNotUseUpTheBudget(t *testing.T) {
	now := time.Date(2026, 10, 6, 12, 10, 0, 0, time.UTC)
	low := github.RateLimit{Limit: 5000, Remaining: 10, ResetAt: now.Add(time.Minute)}
	var b kennelBudget
	for range 50 {
		b.take(now, 20, low)
	}
	if b.spent != 0 {
		t.Errorf("%d requests were counted while Kennel Club was standing down", b.spent)
	}
}

// A GitHub that is answering 500 is not helped by being asked again every
// minute, and the registration path shares it. Kennel Club therefore stands down
// from the installation, for longer each time, and nobody else is held.
func TestKennelClubStandsDownWhenGitHubFailsAndOnlyKennelClub(t *testing.T) {
	f := newKennelFixture(t)
	in := kennelPassInput{cfg: config.Kennel{APIBudgetPercent: 20}}
	if !f.c.kennelTake(f.inst.ID, in, github.RateLimit{}) {
		t.Fatal("a healthy installation was refused")
	}
	f.c.observeKennel(f.inst.ID, github.NewServerError(errors.New("500 []")))
	if f.c.kennelTake(f.inst.ID, in, github.RateLimit{}) {
		t.Error("Kennel Club carried on after a 500")
	}
	if f.c.githubHeld(f.inst.ID, f.c.Now()) {
		t.Error("a 500 on a Kennel Club read paused the poller and scheduler too")
	}
	f.advance(kennelUnwellBase + time.Second)
	if !f.c.kennelTake(f.inst.ID, in, github.RateLimit{}) {
		t.Fatal("Kennel Club never came back")
	}
	f.c.observeKennel(f.inst.ID, github.NewServerError(errors.New("500 []")))
	f.advance(kennelUnwellBase + time.Second)
	if f.c.kennelTake(f.inst.ID, in, github.RateLimit{}) {
		t.Error("the second failure in a row waited no longer than the first")
	}
}

package controller

import (
	"context"
	"errors"
	"strings"

	"github.com/eyupio/zoomies/internal/agentguidance"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/kennel"
	"github.com/eyupio/zoomies/internal/store"
)

func kennelGuidanceEnabled(p kennel.Policy) bool { return kennelSourceWanted(p, kennel.SourceGuidance) }
func kennelGuidanceDue(row *store.KennelRepository, in kennelPassInput) bool {
	return kennelGuidanceEnabled(in.policy) && parseKennelWatermark(row.Watermark).GuidanceState == ""
}

func guidanceFacts(issues []agentguidance.Issue) *kennel.GuidanceFacts {
	out := &kennel.GuidanceFacts{}
	for _, issue := range issues {
		loc := kennel.GuidanceLocation{SHA: issue.SHA, Line: issue.Line}
		switch issue.Kind {
		case "missing":
			out.Missing = true
		case "broken_reference":
			out.Broken = append(out.Broken, loc)
		case "duplicated":
			out.Duplicated = append(out.Duplicated, loc)
		case "unreadable":
			out.Unreadable = append(out.Unreadable, loc)
		}
	}
	return out
}

func (c *Controller) kennelReadGuidance(ctx context.Context, inst *store.Installation, row *store.KennelRepository, wm *kennelWatermark, l *kennelListing, in kennelPassInput) kennel.CoverageState {
	wm.Guidance = nil
	wm.GuidanceFiles = nil
	wm.GuidanceState = kennel.CoverageNotRead
	if l == nil {
		return wm.GuidanceState
	}
	if l.State != kennel.CoverageOK {
		wm.GuidanceState = l.State
		return wm.GuidanceState
	}
	reader, ok := l.Client.(github.KennelGuidanceReader)
	if !ok {
		wm.GuidanceState = kennel.CoverageUnavailable
		return wm.GuidanceState
	}
	repo, ok := l.Repos[strings.ToLower(row.FullName)]
	if !ok {
		wm.GuidanceState = kennel.CoverageUnavailable
		return wm.GuidanceState
	}
	take := func() bool {
		return c.cfg().Kennel.Enabled && c.cfg().Kennel.AgentGuidance && ctx.Err() == nil && c.mayAct() && !c.githubHeld(inst.ID, in.now) && c.kennelTake(inst.ID, in, l.Limit)
	}
	failed := func(err error) kennel.CoverageState {
		c.observeKennel(inst.ID, err)
		c.holdIfRateLimited(inst.ID, err, in.now, "reading agent guidance for Kennel Club")
		state := kennelState(err)
		if errors.Is(err, github.ErrNotFound) {
			state = kennel.CoverageUnavailable
		}
		return state
	}
	if !take() {
		wm.GuidanceState = kennel.CoverageHeld
		return wm.GuidanceState
	}
	inv, err := reader.KennelGuidanceInventory(ctx, row.FullName, repo.DefaultBranch)
	if err != nil {
		wm.GuidanceState = failed(err)
		return wm.GuidanceState
	}
	if inv == nil {
		wm.GuidanceState = kennel.CoverageError
		return wm.GuidanceState
	}
	c.observeKennel(inst.ID, nil)
	state := kennel.CoverageOK
	if inv.Partial {
		state = kennel.CoveragePartial
	}
	var files []agentguidance.File
	var issues []agentguidance.Issue
	remember := func(ref github.WorkflowFileRef) {
		p := ""
		if agentguidance.SafePath(ref.Path) {
			p = ref.Path
		}
		wm.GuidanceFiles = append(wm.GuidanceFiles, kennelWorkflowRef{SHA: ref.SHA, Path: p})
	}
	for _, ref := range inv.Skipped {
		remember(ref)
		issues = append(issues, agentguidance.Issue{Kind: "unreadable", SHA: ref.SHA})
	}
	for _, ref := range inv.Files {
		if !take() {
			state = kennel.CoverageHeld
			break
		}
		data, err := reader.KennelWorkflowBlob(ctx, row.FullName, ref)
		if err != nil {
			state = failed(err)
			break
		}
		c.observeKennel(inst.ID, nil)
		remember(ref)
		files = append(files, agentguidance.File{Path: ref.Path, SHA: ref.SHA, Content: string(data)})
	}
	outcome := state
	if len(files) > 0 && state != kennel.CoverageOK {
		state = kennel.CoveragePartial
	}
	if state == kennel.CoverageOK || state == kennel.CoveragePartial {
		issues = append(issues, agentguidance.Inspect(files, inv.Paths, !inv.TreePartial)...)
		wm.Guidance = guidanceFacts(issues)
	}
	wm.GuidanceState = state
	return outcome
}

package controller

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"

	"github.com/eyupio/zoomies/internal/agentguidance"
	"github.com/eyupio/zoomies/internal/aicontext"
	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

type KennelGuidancePreview struct {
	BaseCommit  string                 `json:"base_commit"`
	Base        string                 `json:"base"`
	Branch      string                 `json:"branch"`
	PlanHash    string                 `json:"plan_hash"`
	Issues      []agentguidance.Issue  `json:"issues"`
	Files       []agentguidance.Change `json:"files"`
	PullRequest *github.PullRequest    `json:"pull_request,omitempty"`
}

type KennelGuidanceApproval struct {
	PlanHash string `json:"plan_hash"`
}

func (c *Controller) guidanceRepository(ctx context.Context, id string) (*store.KennelRepository, error) {
	if !c.cfg().Kennel.Enabled {
		return nil, ErrKennelOff
	}
	if !c.cfg().Kennel.AgentGuidance {
		return nil, fmt.Errorf("%w: an administrator can turn on kennel.agent_guidance to check and propose agent guidance", store.ErrConflict)
	}
	row, err := c.st.GetKennelRepository(ctx, id)
	if err != nil {
		return nil, err
	}
	if row.Untracked != nil {
		return nil, ErrKennelNotTracked
	}
	return row, nil
}

func (c *Controller) prepareGuidance(ctx context.Context, id string) (*KennelGuidancePreview, github.AgentGuidanceClient, *store.KennelRepository, error) {
	row, err := c.guidanceRepository(ctx, id)
	if err != nil {
		return nil, nil, nil, err
	}
	if c.githubHeld(row.InstallationID, c.Now()) {
		return nil, nil, nil, fmt.Errorf("%w: requests for this installation are held for a GitHub rate limit; try again after the hold ends", store.ErrConflict)
	}
	client, err := c.ClientFor(ctx, row.InstallationID)
	if err != nil {
		return nil, nil, nil, err
	}
	info, err := client.Probe(ctx)
	if err != nil {
		return nil, nil, nil, err
	}
	if info == nil || !info.CanReadContents() {
		return nil, nil, nil, fmt.Errorf("%w: agent guidance preview needs Contents read permission on the installation", auth.ErrInvalidInput)
	}
	writer, ok := client.(github.AgentGuidanceClient)
	if !ok {
		return nil, nil, nil, fmt.Errorf("%w: this GitHub client does not support agent guidance proposals", auth.ErrInvalidInput)
	}
	// The reader resolves and pins the current default branch. Verify the
	// installation's stored repository identity before proposing any write.
	source, err := writer.ReadAgentGuidance(ctx, row.FullName, "")
	if err != nil {
		if errors.Is(err, github.ErrSetupConflict) {
			err = fmt.Errorf("%w: %s", store.ErrConflict, err)
		}
		return nil, nil, nil, err
	}
	if source == nil || source.Repository.ID != row.RepositoryID || !strings.EqualFold(source.Repository.FullName, row.FullName) || source.Repository.Archived || source.Repository.DefaultBranch == "" {
		return nil, nil, nil, store.ErrConflict
	}
	files := make([]agentguidance.File, 0, len(source.Files))
	for _, f := range source.Files {
		files = append(files, agentguidance.File{Path: f.Path, SHA: f.SHA, Mode: f.Mode, Content: f.Content})
	}
	plan := &KennelGuidancePreview{BaseCommit: source.Commit, Base: source.Repository.DefaultBranch, Issues: nonNilSlice(agentguidance.Inspect(files, source.Inventory, true)), Files: nonNilSlice(agentguidance.Plan(files, source.Inventory))}
	raw, _ := json.Marshal(struct {
		Repository   string
		Installation string
		RepositoryID int64
		Plan         *KennelGuidancePreview
	}{id, row.InstallationID, row.RepositoryID, plan})
	if len(raw) > 4<<20 {
		return nil, nil, nil, fmt.Errorf("%w: guidance preview exceeds 4 MiB; shorten instruction files before proposing changes", store.ErrConflict)
	}
	plan.PlanHash = aicontext.Hash(raw)
	branchInput, _ := json.Marshal(struct {
		RepositoryID int64
		Files        []agentguidance.Change
	}{row.RepositoryID, plan.Files})
	branchHash := aicontext.Hash(branchInput)
	plan.Branch = fmt.Sprintf("zoomies-agent-guidance-%d-%s", row.RepositoryID, branchHash[:16])
	return plan, writer, row, nil
}

func (c *Controller) PreviewKennelGuidance(ctx context.Context, id string) (*KennelGuidancePreview, error) {
	plan, _, _, err := c.prepareGuidance(ctx, id)
	return plan, err
}

func (c *Controller) CreateKennelGuidancePR(ctx context.Context, id string, approval KennelGuidanceApproval) (*KennelGuidancePreview, error) {
	plan, writer, row, err := c.prepareGuidance(ctx, id)
	if err != nil {
		return nil, err
	}
	if approval.PlanHash != plan.PlanHash {
		return nil, fmt.Errorf("%w: repository or proposal changed after review; preview it again", store.ErrConflict)
	}
	if len(plan.Files) == 0 {
		return nil, fmt.Errorf("%w: there are no automatic guidance changes to propose; review the findings manually", store.ErrConflict)
	}
	client, err := c.ClientFor(ctx, row.InstallationID)
	if err != nil {
		return nil, err
	}
	info, err := client.Probe(ctx)
	if err != nil {
		return nil, err
	}
	if info == nil || info.Permissions["contents"] != "write" || info.Permissions["pull_requests"] != "write" {
		return nil, fmt.Errorf("%w: guidance draft pull requests need Contents write and Pull requests write permission; Workflows write is not required", auth.ErrInvalidInput)
	}
	// Recheck local consent immediately before the external write. The GitHub
	// writer checks the pinned base before publishing and reconciles retries.
	current, err := c.guidanceRepository(ctx, id)
	if err != nil {
		return nil, err
	}
	if current.InstallationID != row.InstallationID || current.RepositoryID != row.RepositoryID || current.FullName != row.FullName {
		return nil, store.ErrConflict
	}
	changes := make([]aicontext.SetupChange, 0, len(plan.Files))
	for _, f := range plan.Files {
		changes = append(changes, aicontext.SetupChange{Path: f.Path, Mode: f.Mode, PreviousSHA: f.PreviousSHA, Content: f.Content})
	}
	pr, err := writer.OpenContextSetup(ctx, github.ContextSetupRequest{Action: "agent-guidance", Repo: row.FullName, Base: plan.Base, BaseCommit: plan.BaseCommit, Head: plan.Branch, PlanHash: plan.PlanHash, Files: changes})
	if errors.Is(err, github.ErrSetupConflict) {
		return nil, fmt.Errorf("%w: %s", store.ErrConflict, err)
	}
	if err != nil {
		return nil, err
	}
	plan.PullRequest = pr
	return plan, nil
}

package controller

import (
	"errors"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/kennel"
	"github.com/eyupio/zoomies/internal/store"
)

func TestGuidanceReadsRequireOptInAndKeepFileEvidenceWithoutRepositoryProse(t *testing.T) {
	f := newKennelFixture(t)
	f.repo("acme/api", "private")
	f.ran("acme/api", 1, f.pool)
	f.gh.AddFile("acme/api", "CLAUDE.md", "@AGENTS.md\n\nNever repeat hostile prose.\n")
	f.pass()
	if f.requestsTo("/git/blobs/") != 0 {
		t.Fatal("guidance read without opt-in")
	}
	f.c.UpdateConfig(func(c *config.Config) { c.Kennel.AgentGuidance = true })
	f.pass()
	v := f.view("acme/api")
	if v.State != kennel.StateAttention || len(v.Files) != 1 || v.Files[0].Path != "CLAUDE.md" {
		t.Fatalf("view=%+v", v)
	}
	for _, finding := range v.Findings {
		if finding.Code == kennel.CodeGuidanceBroken && !strings.Contains(finding.Prompt, "CLAUDE.md") {
			t.Fatal("guidance file missing from copied finding prompt")
		}
	}
	if raw := string(f.row("acme/api").Watermark); strings.Contains(raw, "hostile") {
		t.Fatal("repository prose persisted in the watermark")
	}
	f.c.UpdateConfig(func(c *config.Config) { c.Kennel.AgentGuidance = false })
	before := f.requestsTo("/git/blobs/")
	f.dueAgain()
	f.pass()
	if f.requestsTo("/git/blobs/") != before {
		t.Fatal("guidance read after switching off")
	}
}

func TestGuidanceProposalPreservesCustomTextRejectsStaleReviewAndRechecksAfterMerge(t *testing.T) {
	f := newKennelFixture(t)
	f.repo("acme/api", "private")
	f.ran("acme/api", 1, f.pool)
	f.gh.SetPermissions(map[string]string{"contents": "write", "pull_requests": "write"})
	f.gh.AddFile("acme/api", "AGENTS.md", "# Rules\n\nKeep existing rules.\n")
	f.gh.AddFile("acme/api", ".claude/CLAUDE.md", "@AGENTS.md\n\nKeep Claude-only rules.\n")
	f.c.UpdateConfig(func(c *config.Config) { c.Kennel.AgentGuidance = true })
	f.pass()
	id := f.row("acme/api").ID
	plan, err := f.c.PreviewKennelGuidance(f.ctx, id)
	if err != nil {
		t.Fatal(err)
	}
	if len(plan.Files) != 1 || plan.Files[0].Content != "@../AGENTS.md\n\nKeep Claude-only rules.\n" {
		t.Fatalf("plan=%+v", plan)
	}
	if _, err := f.c.CreateKennelGuidancePR(f.ctx, id, KennelGuidanceApproval{PlanHash: "wrong"}); !errors.Is(err, store.ErrConflict) {
		t.Fatalf("stale hash: %v", err)
	}
	result, err := f.c.CreateKennelGuidancePR(f.ctx, id, KennelGuidanceApproval{PlanHash: plan.PlanHash})
	if err != nil {
		t.Fatal(err)
	}
	again, err := f.c.CreateKennelGuidancePR(f.ctx, id, KennelGuidanceApproval{PlanHash: plan.PlanHash})
	if err != nil || again.PullRequest.Number != result.PullRequest.Number {
		t.Fatalf("retry=%+v %v", again, err)
	}

	f.gh.AddFile("acme/api", "unrelated.go", "package unrelated\n")
	fresh, err := f.c.PreviewKennelGuidance(f.ctx, id)
	if err != nil || fresh.Branch != plan.Branch || fresh.PlanHash == plan.PlanHash {
		t.Fatalf("proposal identity after unrelated push: %+v %v", fresh, err)
	}
	if _, err := f.c.CreateKennelGuidancePR(f.ctx, id, KennelGuidanceApproval{PlanHash: fresh.PlanHash}); !errors.Is(err, store.ErrConflict) {
		t.Fatalf("duplicate proposal after base change: %v", err)
	}
	if !f.gh.MergeContextPull("acme/api", result.PullRequest.Number) {
		t.Fatal("merge failed")
	}
	f.dueAgain()
	f.pass()
	for _, finding := range f.view("acme/api").Findings {
		if finding.Code == kennel.CodeGuidanceBroken {
			t.Fatal("merged repair did not clear finding")
		}
	}
	if _, err := f.c.CreateKennelGuidancePR(f.ctx, id, KennelGuidanceApproval{PlanHash: plan.PlanHash}); !errors.Is(err, store.ErrConflict) {
		t.Fatalf("changed base accepted: %v", err)
	}
}

func TestGuidancePreviewNeedsOnlyReadPermissionAndNoChangesOnUntrackedRepositories(t *testing.T) {
	f := newKennelFixture(t)
	f.repo("acme/api", "private")
	f.ran("acme/api", 1, f.pool)
	f.gh.SetPermissions(map[string]string{"contents": "read"})
	f.c.UpdateConfig(func(c *config.Config) { c.Kennel.AgentGuidance = true })
	f.pass()
	id := f.row("acme/api").ID
	plan, err := f.c.PreviewKennelGuidance(f.ctx, id)
	if err != nil || len(plan.Files) != 2 {
		t.Fatalf("preview=%+v %v", plan, err)
	}
	if _, err := f.c.CreateKennelGuidancePR(f.ctx, id, KennelGuidanceApproval{PlanHash: plan.PlanHash}); err == nil {
		t.Fatal("read-only installation published a PR")
	}
	_, _, _, err = f.c.SetKennelTracking(f.ctx, id, KennelTrackingInput{Tracked: false, Reason: "This repository is deliberately excluded."}, KennelActor{CanUntrack: true})
	if err != nil {
		t.Fatal(err)
	}
	before := len(f.gh.Requests())
	if _, err := f.c.PreviewKennelGuidance(f.ctx, id); !errors.Is(err, ErrKennelNotTracked) {
		t.Fatalf("untracked preview: %v", err)
	}
	if len(f.gh.Requests()) != before {
		t.Fatal("untracked repository read")
	}
}

package controller

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"
	"unicode"
	"unicode/utf8"

	"github.com/eyupio/zoomies/internal/kennel"
	"github.com/eyupio/zoomies/internal/store"
)

// What a person can do with Kennel Club: read it, ask for a repository to be read
// again, and make or end a waiver. The rules for each live here and not in the
// handlers, so they are tested without HTTP and an assistant or a script cannot
// reach a different answer by another route.

var (
	// ErrKennelOff is the answer to anything that needs Kennel Club's rows while
	// it is off. The API turns it into a 409 that says where to turn it on.
	ErrKennelOff = errors.New("kennel club is off")
	// ErrKennelWaiverLimit means a repository already has as many waivers as it
	// may.
	ErrKennelWaiverLimit = errors.New("kennel club: this repository has as many waivers as it may")
	// ErrKennelNotTracked is the answer to anything that needs Kennel Club's
	// findings for a repository it has been told not to look at: it has none, and
	// reading or deciding about findings that are not there would be guessing.
	ErrKennelNotTracked = errors.New("kennel club: this repository is not tracked")
	// ErrKennelUntrackNeedsAdmin is a request to stop Kennel Club looking at a
	// repository by somebody who may only start it again.
	ErrKennelUntrackNeedsAdmin = errors.New("kennel club: stopping tracking a repository takes the administrator role")
)

const (
	// KennelRecheckCooldown is the least time between two requests to read one
	// repository again. A read costs GitHub requests the scheduler shares, and a
	// person pressing the button every few seconds is not asking a different
	// question each time.
	KennelRecheckCooldown = 5 * time.Minute
	// KennelMaxWaiverDays is the longest a waiver may last. A waiver that never
	// ends is a decision nobody is asked to make again.
	KennelMaxWaiverDays = 365
	// KennelMaxWaivers is how many a repository may carry: a waiver is made for a
	// finding that exists, and a repository with fifty of them has a different
	// problem from one more of them.
	KennelMaxWaivers = 50
	// Bounds on a waiver's reason, in characters. Ten is a sentence's worth, so
	// "ok" and "fine" are not reasons; five hundred is a paragraph, which is what
	// an audit row should carry and the page should render.
	KennelMinReason  = 10
	KennelMaxReason  = 500
	kennelMaxSubject = 200
)

// KennelCooldownError is a recheck asked for too soon.
type KennelCooldownError struct{ Until time.Time }

func (e *KennelCooldownError) Error() string {
	return "this repository was asked to be read again a moment ago; it can be asked again at " + e.Until.UTC().Format("15:04:05 MST")
}

// KennelFieldError is one thing wrong with a request, in the words the field it
// belongs to should show.
type KennelFieldError struct{ Field, Message string }

// KennelInvalidError is a request the controller understood and will not act on.
type KennelInvalidError struct{ Fields []KennelFieldError }

func (e *KennelInvalidError) Error() string {
	parts := make([]string, 0, len(e.Fields))
	for _, f := range e.Fields {
		parts = append(parts, f.Field+": "+f.Message)
	}
	return strings.Join(parts, "; ")
}

// KennelNeedsAdminError is a waiver of an error finding by somebody who may waive
// only the lesser ones. It says which finding, so the answer is about something.
type KennelNeedsAdminError struct{ Code kennel.Code }

func (e *KennelNeedsAdminError) Error() string {
	return "waiving " + string(e.Code) + ", which is an error, takes a more senior role than waiving a warning does"
}

// KennelListFilter narrows the list of repositories. Every field is validated
// here, because the values reach SQL as parameters and a typo in one should be an
// answer and not an empty page.
type KennelListFilter struct {
	Q, Severity, Code, State, InstallationID string
	// Active, when set, keeps the repositories the fleet has served a job for in
	// Kennel Club's window (true) or the ones it has not (false). The window is
	// the one every sentence on the Overview names: thirty days, or as long as the
	// fleet keeps its jobs if that is shorter.
	Active *bool
	// Tracked, when set, keeps the repositories Kennel Club is looking at (true) or
	// the ones it has been told not to (false). Left alone, both are listed.
	Tracked *bool
	// Incomplete keeps the repositories that are only partly checked: something could
	// not be read (partial) or has not been looked at yet (pending). It is what the
	// Overview's "Partly checked" card adds up, and State can name only one of the two.
	Incomplete bool
	// Waived keeps the repositories with a waived finding (true) or none (false).
	Waived *bool
}

// KennelRepositories lists what Kennel Club has concluded, in the shape of GET
// /kennel/repositories/{id}.
func (c *Controller) KennelRepositories(ctx context.Context, f KennelListFilter, page store.Page) ([]KennelRepositoryView, int, error) {
	if !c.cfg().Kennel.Enabled {
		return nil, 0, ErrKennelOff
	}
	filter := store.KennelFilter{Q: f.Q, InstallationID: f.InstallationID, Tracked: f.Tracked}
	if f.Active != nil {
		filter.Served = f.Active
		filter.ServedSince = c.Now().Add(-kennelWindow(c.cfg().Retention.Jobs))
	}
	switch f.Severity {
	case "", "error", "warning", "info":
		filter.Severity = f.Severity
	default:
		return nil, 0, &KennelInvalidError{Fields: []KennelFieldError{{"severity", "is not error, warning or info"}}}
	}
	if f.Code != "" {
		if _, ok := kennel.Lookup(kennel.Code(f.Code)); !ok {
			return nil, 0, &KennelInvalidError{Fields: []KennelFieldError{{"code", "is not a check Kennel Club has; GET /kennel/checks lists them"}}}
		}
		filter.Code = f.Code
	}
	filter.Waived = f.Waived
	if f.Incomplete {
		if f.State != "" {
			return nil, 0, &KennelInvalidError{Fields: []KennelFieldError{{"incomplete", "cannot be combined with state, which already names a standing"}}}
		}
		filter.States = []string{string(kennel.StatePartial), string(kennel.StatePending)}
	}
	if f.State != "" {
		switch kennel.State(f.State) {
		case kennel.StatePending, kennel.StatePartial, kennel.StateAttention, kennel.StateBestInShow:
			filter.States = []string{f.State}
		default:
			return nil, 0, &KennelInvalidError{Fields: []KennelFieldError{{"state", "is not pending, partial, attention or best_in_show"}}}
		}
	}
	rows, total, err := c.st.ListKennelRepositories(ctx, filter, page)
	if err != nil {
		return nil, 0, err
	}
	out := make([]KennelRepositoryView, 0, len(rows))
	for _, r := range rows {
		out = append(out, newKennelRepositoryView(r))
	}
	return out, total, nil
}

// KennelRepository is one repository, in the shape the event stream carries.
func (c *Controller) KennelRepository(ctx context.Context, id string) (*KennelRepositoryView, error) {
	if !c.cfg().Kennel.Enabled {
		return nil, ErrKennelOff
	}
	row, err := c.st.GetKennelRepository(ctx, id)
	if err != nil {
		return nil, err
	}
	v := newKennelRepositoryView(row)
	return &v, nil
}

// KennelNeed is a source a check reads, and the permission it takes.
type KennelNeed struct {
	Source kennel.Source `json:"source"`
	Label  string        `json:"label"`
	// Permission is empty for what this fleet already knows, which needs none.
	Permission string `json:"permission"`
	// Conditional says it is read only for the repositories the check applies to:
	// the run history, for example, is read for public repositories and no others.
	Conditional bool `json:"conditional"`
}

// KennelCheckInfo is one entry in the catalogue of what is checked.
type KennelCheckInfo struct {
	Code     kennel.Code     `json:"code"`
	Area     kennel.Area     `json:"area"`
	Severity kennel.Severity `json:"severity"`
	Detects  string          `json:"detects"`
	Fix      string          `json:"fix"`
	Verify   string          `json:"verify"`
	Docs     string          `json:"docs"`
	Needs    []KennelNeed    `json:"needs"`
	// Disabled says the operator turned it off, by its code or its area.
	Disabled bool `json:"disabled"`
}

// KennelChecks is the catalogue. It is built from the registry the evaluator runs,
// so the page that says what is checked, the documentation and the checks cannot
// disagree.
func (c *Controller) KennelChecks() []KennelCheckInfo {
	disabled := kennelDisabled(c.cfg().Kennel)
	checks := kennel.Checks()
	out := make([]KennelCheckInfo, 0, len(checks))
	for _, ck := range checks {
		info := KennelCheckInfo{
			Code: ck.Code, Area: ck.Area, Severity: ck.Severity, Detects: ck.Detects,
			Fix: ck.Fix, Verify: ck.Verify, Docs: ck.Docs,
			Needs:    make([]KennelNeed, 0, len(ck.Needs)),
			Disabled: disabled[string(ck.Code)] || disabled[string(ck.Area)],
		}
		for _, src := range ck.Needs {
			info.Needs = append(info.Needs, KennelNeed{Source: src, Label: src.Label(), Permission: src.Permission()})
		}
		for _, src := range ck.Conditional {
			info.Needs = append(info.Needs, KennelNeed{Source: src, Label: src.Label(), Permission: src.Permission(), Conditional: true})
		}
		out = append(out, info)
	}
	return out
}

// RecheckKennelRepository asks for a repository's reads from GitHub to happen
// again. It makes the repository due and wakes the loop; it reads nothing itself,
// so a person pressing the button waits on the same budget and the same hold as
// everything else.
func (c *Controller) RecheckKennelRepository(ctx context.Context, id string) (*KennelRepositoryView, error) {
	if !c.cfg().Kennel.Enabled {
		return nil, ErrKennelOff
	}
	row, err := c.st.GetKennelRepository(ctx, id)
	if err != nil {
		return nil, err
	}
	if row.Untracked != nil {
		return nil, ErrKennelNotTracked
	}
	now := c.Now()
	c.kennel.mu.Lock()
	if last, ok := c.kennel.rechecks[id]; ok && now.Before(last.Add(KennelRecheckCooldown)) {
		c.kennel.mu.Unlock()
		return nil, &KennelCooldownError{Until: last.Add(KennelRecheckCooldown)}
	}
	c.kennel.rechecks[id] = now
	c.kennel.mu.Unlock()

	if err := c.st.RequestKennelRecheck(ctx, row.ID); err != nil {
		return nil, err
	}
	c.KickKennel()
	c.PublishKennelRepository(ctx, row.ID)
	return c.KennelRepository(ctx, row.ID)
}

// KennelWaiverInput is a request to waive a finding.
type KennelWaiverInput struct {
	Code      string
	Subject   string
	Reason    string
	ExpiresAt time.Time
}

// KennelActor is who is waiving, as far as the rules need to know.
type KennelActor struct {
	ID, Name string
	// CanWaiveErrors is whether the caller holds kennel.waive_error. The policy
	// table says who does; the controller only asks.
	CanWaiveErrors bool
	// CanUntrack is whether the caller holds kennel.untrack. Stopping Kennel Club
	// looking at a repository silences its errors, which is what makes it the
	// administrator's; starting it again only makes Kennel Club stricter.
	CanUntrack bool
}

// WaiveKennelFinding records a decision that a finding is acceptable here, and
// works the repository out again so the answer already says so.
//
// It is for a finding that exists. A waiver made ahead of one is a standing
// exception nobody has looked at, so a code and subject that match no open or
// waived finding are refused; and one for an error needs the senior role, because
// an error is a stranger running code on the fleet and the decision that it is
// acceptable is not an operator's to take alone.
func (c *Controller) WaiveKennelFinding(ctx context.Context, repositoryID string, in KennelWaiverInput, by KennelActor) (*KennelRepositoryView, *store.KennelWaiver, error) {
	if !c.cfg().Kennel.Enabled {
		return nil, nil, ErrKennelOff
	}
	row, err := c.st.GetKennelRepository(ctx, repositoryID)
	if err != nil {
		return nil, nil, err
	}
	if row.Untracked != nil {
		return nil, nil, ErrKennelNotTracked
	}
	now := c.Now()
	in.Subject = strings.TrimSpace(in.Subject)
	in.Reason = strings.TrimSpace(in.Reason)
	if bad := checkKennelWaiverInput(in, now); len(bad) > 0 {
		return nil, nil, &KennelInvalidError{Fields: bad}
	}
	code := kennel.Code(in.Code)

	var ev kennel.Evaluation
	_ = json.Unmarshal(row.Evaluation, &ev)
	severity, found := kennelFindingSeverity(ev, code, in.Subject)
	if !found {
		return nil, nil, &KennelInvalidError{Fields: []KennelFieldError{{"code", "matches no open finding on this repository, so there is nothing to waive; a waiver is a decision about a finding that exists"}}}
	}
	if severity == kennel.SeverityError && !by.CanWaiveErrors {
		return nil, nil, &KennelNeedsAdminError{Code: code}
	}

	existing, err := c.st.ListKennelWaivers(ctx, row.ID)
	if err != nil {
		return nil, nil, err
	}
	renewing := false
	for _, w := range existing {
		if w.Code == in.Code && w.Subject == in.Subject {
			renewing = true
		}
	}
	if !renewing && len(existing) >= KennelMaxWaivers {
		return nil, nil, ErrKennelWaiverLimit
	}

	w := &store.KennelWaiver{
		RepositoryPK: row.ID, Code: in.Code, Subject: in.Subject, Severity: string(severity),
		Reason: in.Reason, CreatedBy: by.ID, CreatedByName: by.Name, ExpiresAt: in.ExpiresAt,
	}
	if err := c.st.UpsertKennelWaiver(ctx, w); err != nil {
		return nil, nil, err
	}
	v, err := c.kennelReevaluated(ctx, row.ID)
	return v, w, err
}

// KennelTrackingInput is a request to stop Kennel Club looking at a repository,
// or to start again.
type KennelTrackingInput struct {
	Tracked bool
	// Reason is why it should not look, and is only read when stopping: starting
	// again is a return to what every repository is.
	Reason string
}

// SetKennelTracking stops Kennel Club looking at a repository, or starts it
// again. It returns the repository as it now stands, the decision it replaced
// (nil if the repository was tracked), and whether anything changed: asking for
// the state a repository is already in is answered and is not a second decision,
// so the caller has no audit row to write for it.
//
// Stopping silences the repository's errors, so it takes the administrator role
// and a reason in the words a waiver's is held to, and it is checked before the
// reason is: a person who may not do it is told so and not told how to ask better.
// Starting again takes an operator, because the only thing it can do is make Kennel
// Club stricter, and it makes the repository due at once so the next pass reads it.
func (c *Controller) SetKennelTracking(ctx context.Context, repositoryID string, in KennelTrackingInput, by KennelActor) (*KennelRepositoryView, *store.KennelUntracked, bool, error) {
	if !c.cfg().Kennel.Enabled {
		return nil, nil, false, ErrKennelOff
	}
	row, err := c.st.GetKennelRepository(ctx, repositoryID)
	if err != nil {
		return nil, nil, false, err
	}
	was := row.Untracked

	var changed bool
	if in.Tracked {
		changed, err = c.st.TrackKennelRepository(ctx, row.ID)
	} else {
		if !by.CanUntrack {
			return nil, nil, false, ErrKennelUntrackNeedsAdmin
		}
		reason := strings.TrimSpace(in.Reason)
		if f := checkKennelReason(reason, "say why Kennel Club should not look at this repository, for whoever finds it quiet in a year"); f != nil {
			return nil, nil, false, &KennelInvalidError{Fields: []KennelFieldError{*f}}
		}
		changed, err = c.st.UntrackKennelRepository(ctx, row.ID, store.KennelUntracked{Reason: reason, By: by.ID, ByName: by.Name})
	}
	if err != nil {
		return nil, nil, false, err
	}
	if changed {
		c.PublishKennelRepository(ctx, row.ID)
		if in.Tracked {
			// Due at once is only a flag; the loop is what reads, and it looks once a
			// minute unless it is woken.
			c.KickKennel()
		}
		c.publishDerived(ctx)
	}
	v, err := c.KennelRepository(ctx, row.ID)
	return v, was, changed, err
}

// checkKennelWaiverInput is everything wrong with a request to waive that can be
// said without looking at the repository, all of it at once so a form does not
// send a person round it three times. It is a function of the request and the
// moment, and nothing else, so the edges of each rule -- the shortest reason, the
// last day a waiver may run to -- are tested at the exact instant.
func checkKennelWaiverInput(in KennelWaiverInput, now time.Time) []KennelFieldError {
	var bad []KennelFieldError
	if _, ok := kennel.Lookup(kennel.Code(in.Code)); !ok {
		bad = append(bad, KennelFieldError{"code", "is not a check Kennel Club has; GET /kennel/checks lists them"})
	}
	if len(in.Subject) > kennelMaxSubject {
		bad = append(bad, KennelFieldError{"subject", fmt.Sprintf("is longer than %d bytes", kennelMaxSubject)})
	}
	if f := checkKennelReason(in.Reason, "say why this is acceptable here, for whoever reads the audit log in a year"); f != nil {
		bad = append(bad, *f)
	}
	switch {
	case in.ExpiresAt.IsZero():
		bad = append(bad, KennelFieldError{"expires_at", "is required: a waiver that never ends is a decision nobody is asked to make again"})
	case !in.ExpiresAt.After(now):
		bad = append(bad, KennelFieldError{"expires_at", "must be in the future"})
	case in.ExpiresAt.After(now.AddDate(0, 0, KennelMaxWaiverDays)):
		bad = append(bad, KennelFieldError{"expires_at", fmt.Sprintf("is more than %d days away; decide again before then", KennelMaxWaiverDays)})
	}
	return bad
}

// checkKennelReason is the rule for the words a person gives for a decision they
// record: a waiver, or stopping tracking. Both end up in the audit log and on the
// page, so they are held to the same length and the same characters, and advice
// is what the message tells the person to say.
func checkKennelReason(reason, advice string) *KennelFieldError {
	if n := utf8.RuneCountInString(reason); n < KennelMinReason || n > KennelMaxReason {
		return &KennelFieldError{"reason", fmt.Sprintf("must be %d to %d characters: %s", KennelMinReason, KennelMaxReason, advice)}
	}
	if badReasonCharacter(reason) {
		return &KennelFieldError{"reason", "may not contain control or direction-changing characters"}
	}
	return nil
}

// UnwaiveKennelFinding ends a waiver. It returns the waiver it ended, which is
// what the audit row records as what was.
func (c *Controller) UnwaiveKennelFinding(ctx context.Context, repositoryID, waiverID string) (*KennelRepositoryView, *store.KennelWaiver, error) {
	if !c.cfg().Kennel.Enabled {
		return nil, nil, ErrKennelOff
	}
	row, err := c.st.GetKennelRepository(ctx, repositoryID)
	if err != nil {
		return nil, nil, err
	}
	if row.Untracked != nil {
		// Ending a waiver works the repository out again, and there is nothing to
		// work out for one nobody is tracking. Its waivers wait, and come back into
		// force when it is tracked.
		return nil, nil, ErrKennelNotTracked
	}
	w, err := c.st.GetKennelWaiver(ctx, waiverID)
	if err != nil {
		return nil, nil, err
	}
	// A waiver is found by its own ID, and it has to be this repository's: a
	// request that names the wrong repository is a 404, and not a way to end
	// somebody else's decision by guessing at one.
	if w.RepositoryPK != repositoryID {
		return nil, nil, fmt.Errorf("kennel waiver %s: %w", waiverID, store.ErrNotFound)
	}
	if err := c.st.DeleteKennelWaiver(ctx, waiverID); err != nil {
		return nil, nil, err
	}
	v, err := c.kennelReevaluated(ctx, repositoryID)
	return v, w, err
}

// kennelReevaluated works one repository out again from what is already known --
// no request to GitHub -- and returns it as it now stands. A change the operator
// made is looked at by the operator at once, so it cannot wait for the loop.
func (c *Controller) kennelReevaluated(ctx context.Context, id string) (*KennelRepositoryView, error) {
	row, err := c.st.GetKennelRepository(ctx, id)
	if err != nil {
		return nil, err
	}
	in, err := c.kennelInput(ctx)
	if err != nil {
		return nil, err
	}
	inst, err := c.st.GetInstallation(ctx, row.InstallationID)
	if err != nil {
		return nil, err
	}
	if err := c.kennelEvaluate(ctx, inst, row, parseKennelWatermark(row.Watermark), nil, false, 0, in); err != nil {
		return nil, err
	}
	return c.KennelRepository(ctx, id)
}

// kennelFindingSeverity is the severity of the finding a waiver would be about,
// whether it is open or already waived (a renewal).
func kennelFindingSeverity(ev kennel.Evaluation, code kennel.Code, subject string) (kennel.Severity, bool) {
	for _, f := range ev.Findings {
		if f.Code == code && f.Subject == subject {
			return f.Severity, true
		}
	}
	for _, w := range ev.Waived {
		if w.Finding.Code == code && w.Finding.Subject == subject {
			return w.Finding.Severity, true
		}
	}
	return "", false
}

// badReasonCharacter is whether a reason has a character that does not belong in
// a sentence a person reads: a control character other than a line break, or one
// of the characters that change which way text runs, which is how a reason can be
// made to look like something it is not.
func badReasonCharacter(s string) bool {
	for _, r := range s {
		if (unicode.IsControl(r) && r != '\n') || isBidiControl(r) {
			return true
		}
	}
	return false
}

