package controller

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"slices"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/kennel"
	"github.com/eyupio/zoomies/internal/store"
)

// The constants Kennel Club's loop is built from. They are constants with a
// documented value and not settings: the measures in the plan say when one earns
// a knob, and a setting nobody can reason about is worse than a number somebody
// can.
const (
	// kennelRetention is how long a repository's row is kept after the fleet last
	// served it, so a quiet repository keeps its waivers. A repository somebody
	// told Kennel Club not to look at is kept however long it has been quiet.
	kennelRetention = 90 * 24 * time.Hour
	// kennelLocalInterval is the least time between two evaluations of what the
	// fleet itself observed. They cost no GitHub request, but a busy fleet changes
	// the facts every second and a finding that flickered would be worse than one
	// ten minutes behind.
	kennelLocalInterval = 10 * time.Minute
	// kennelMaxWindow is the longest the evidence reaches back.
	kennelMaxWindow = 30 * 24 * time.Hour
	// kennelUnservedWindow is how far back a job that waited for a label no pool
	// serves still counts: a label somebody fixed last month is not news.
	kennelUnservedWindow = 7 * 24 * time.Hour
	// kennelRunsPerRefresh caps the runs read for one repository in one refresh.
	kennelRunsPerRefresh = 100
	// kennelRunsKept caps the runs remembered for one repository. Only the ones a
	// check can use are kept -- fork pull requests and the four events a stranger
	// can trigger -- so this is a long way above what a repository produces.
	kennelRunsKept = 500
	// kennelListingLimit bounds a repository listing, as the discovery of AI
	// Context does.
	kennelListingLimit = 500
)

// kennelWindow is how far back the evidence reaches: thirty days, or the fleet's
// job retention if that is shorter, because the jobs table cannot answer about
// a day it has already pruned. A sentence that says "in the last N days" says
// this one.
func kennelWindow(retentionJobs time.Duration) time.Duration {
	if retentionJobs > 0 && retentionJobs < kennelMaxWindow {
		return retentionJobs
	}
	return kennelMaxWindow
}

// kennelWatermark is what the controller keeps about the facts it has read for a
// repository, in the row's own document. The store keeps it whole and has no
// opinion about what is in it.
//
// Only runs a check can use are remembered. A run's trigger and head repository
// never change, so each is read once; the watermark is what stops a restart
// reading the same hundred again.
type kennelWatermark struct {
	// After is the highest run ID read in an unbroken run from the lowest one
	// taken. The next read asks only for runs above it.
	After         int64                 `json:"after"`
	Workflows     *kennel.WorkflowFacts `json:"workflows,omitempty"`
	WorkflowState kennel.CoverageState  `json:"workflow_state,omitempty"`
	// WorkflowFiles is the inventory the workflows were read from, by SHA, with
	// each path as the gate let it through or "" where it did not. It is what
	// the page resolves a finding's file to; it is never in the snapshot.
	WorkflowFiles []kennelWorkflowRef `json:"workflow_files,omitempty"`
	// WorkflowFormat says which shape Workflows holds. A watermark from before
	// the files were kept by SHA holds counts the evaluator can no longer read,
	// so one below kennelWorkflowFormat is read again once.
	WorkflowFormat int                   `json:"workflow_format,omitempty"`
	Setup          *kennel.SetupFacts    `json:"setup,omitempty"`
	SetupState     kennel.CoverageState  `json:"setup_state,omitempty"`
	Guidance       *kennel.GuidanceFacts `json:"guidance,omitempty"`
	GuidanceState  kennel.CoverageState  `json:"guidance_state,omitempty"`
	GuidanceFiles  []kennelWorkflowRef   `json:"guidance_files,omitempty"`
	// Settings are the repository's Actions settings as flags and one enumerated
	// word. They are never a name or a line of text a repository wrote.
	Settings      *kennel.SettingsFacts `json:"settings,omitempty"`
	SettingsState kennel.CoverageState  `json:"settings_state,omitempty"`
	// Protection is the default branch's required status checks. It holds names a
	// repository chose, so it stays in this document and is turned into counts
	// before anything is evaluated.
	Protection      *kennelProtection    `json:"protection,omitempty"`
	ProtectionState kennel.CoverageState `json:"protection_state,omitempty"`
	// Runs are the fork pull requests and stranger-triggered runs found, newest
	// first.
	Runs []kennelSeenRun `json:"runs"`
	// GapQueuedAt is, in milliseconds, when the newest run was queued that a read
	// had to leave unread because there were more than the cap. While that is
	// still inside the window the runs are a sample. Zero means nothing was
	// skipped.
	GapQueuedAt int64 `json:"gap_queued_at,omitempty"`
	// ReadAt is when a read of the runs last got anywhere, in milliseconds. Zero
	// means never.
	ReadAt int64 `json:"read_at,omitempty"`
	// State is how the last attempt to read the runs ended, when it did not end
	// well. Empty means it did.
	State kennel.CoverageState `json:"state,omitempty"`
}

// kennelWorkflowFormat is the shape of Workflows this release writes.
const kennelWorkflowFormat = 2

// kennelWorkflowRef is one workflow file in the inventory: its blob SHA and
// its path after the gate.
type kennelWorkflowRef struct {
	SHA  string `json:"sha"`
	Path string `json:"path,omitempty"`
}

// kennelSeenRun is one run worth remembering.
type kennelSeenRun struct {
	ID    int64  `json:"id"`
	Event string `json:"event"`
	Fork  bool   `json:"fork,omitempty"`
	// QueuedAt is in milliseconds; a run ages out of the window by it.
	QueuedAt int64 `json:"queued_at"`
}

// parseKennelWatermark reads the stored document. One that does not parse is a
// repository nothing has been read for, which costs one re-read and not a
// refusal to evaluate.
func parseKennelWatermark(raw []byte) kennelWatermark {
	var w kennelWatermark
	if err := json.Unmarshal(raw, &w); err != nil {
		return kennelWatermark{}
	}
	return w
}

func (w kennelWatermark) marshal() json.RawMessage {
	if w.Runs == nil {
		w.Runs = []kennelSeenRun{}
	}
	raw, err := json.Marshal(w)
	if err != nil {
		return json.RawMessage(`{}`)
	}
	return raw
}

// remember adds runs, newest first, keeping only those inside the window and no
// more than kennelRunsKept of them. A run already remembered is kept once.
func (w *kennelWatermark) remember(found []kennelSeenRun, now time.Time, window time.Duration) {
	cutoff := now.Add(-window).UnixMilli()
	all := append(slices.Clone(found), w.Runs...)
	slices.SortStableFunc(all, func(a, b kennelSeenRun) int {
		switch {
		case a.ID > b.ID:
			return -1
		case a.ID < b.ID:
			return 1
		}
		return 0
	})
	out := make([]kennelSeenRun, 0, len(all))
	for _, r := range all {
		if r.QueuedAt < cutoff || (len(out) > 0 && out[len(out)-1].ID == r.ID) {
			continue
		}
		if len(out) == kennelRunsKept {
			break
		}
		out = append(out, r)
	}
	w.Runs = out
}

// facts is what the evaluator is given: the runs remembered that are still inside
// the window, with their events put through the allow-list. nil means nothing
// has been read, which is different from none having been found.
func (w kennelWatermark) facts(now time.Time, window time.Duration) *kennel.RunFacts {
	if w.ReadAt == 0 {
		return nil
	}
	cutoff := now.Add(-window).UnixMilli()
	out := &kennel.RunFacts{Window: window}
	for _, r := range w.Runs {
		if r.QueuedAt < cutoff {
			continue
		}
		out.Runs = append(out.Runs, kennel.Run{ID: r.ID, Event: kennel.NormalizeEvent(r.Event), FromFork: r.Fork})
	}
	return out
}

// coverage is how far the runs could be read.
//
// A failure after a read that did get somewhere is partial and not the failure's
// own state: what was found stands, and what was not found is not an all-clear.
// A repository that was never read has nothing to stand, so it says why, which
// is the sentence that names the permission to grant.
func (w kennelWatermark) coverage(now time.Time, window time.Duration) kennel.CoverageState {
	if w.ReadAt == 0 {
		if w.State == "" {
			return kennel.CoverageNotRead
		}
		return w.State
	}
	if w.State != "" {
		return kennel.CoveragePartial
	}
	if w.GapQueuedAt > now.Add(-window).UnixMilli() {
		return kennel.CoveragePartial
	}
	return kennel.CoverageOK
}

// kennelDangers reduces a pool to the words the evaluator knows. The evaluator
// never sees a pool: it sees what is weak about it, so a pool's name, labels and
// image cannot reach a sentence by the way.
//
// The first four are exactly what Pool.Dangerous says, which is held by a test,
// so a new way a pool can be dangerous is a failing test and not a gap in what
// Kennel Club notices. The last has no sentence there: a process backend runs a
// job directly on the host, which Dangerous does not call dangerous because it
// is what that backend is, and which is the strongest thing there is to say
// about a pool that runs a stranger's code.
func kennelDangers(p *store.Pool) []kennel.PoolDanger {
	var out []kennel.PoolDanger
	if !p.Ephemeral {
		out = append(out, kennel.DangerPersistent)
	}
	if p.DockerMode == store.DockerHostSocket {
		out = append(out, kennel.DangerHostSocket)
	}
	if p.DockerMode == store.DockerDinD {
		out = append(out, kennel.DangerPrivileged)
	}
	if p.RunAsRoot {
		out = append(out, kennel.DangerRoot)
	}
	if p.Backend == store.BackendProcess {
		out = append(out, kennel.DangerNoContainer)
	}
	return out
}

// kennelDigests is what the loop compares to know whether anything it would
// evaluate has changed, in two halves that are throttled differently.
//
// Facts is what GitHub and the fleet said, and a busy fleet changes it every
// second, so it is re-evaluated at most every ten minutes. Policy is what the
// operator decided -- a check turned off, a waiver made or ended -- and an
// operator who has just changed it is looking at the page, so it is
// re-evaluated at once: a setting that is "saved" while the page still shows the
// old answer for ten minutes is a setting that does not seem to work.
type kennelDigests struct {
	Facts  string
	Policy string
}

// String is the form kept in the row's inputs_digest column.
func (d kennelDigests) String() string { return d.Facts + "/" + d.Policy }

// parseKennelDigests reads what String wrote. One that does not parse is a
// digest that matches nothing, which costs one evaluation.
func parseKennelDigests(s string) kennelDigests {
	facts, policy, ok := strings.Cut(s, "/")
	if !ok {
		return kennelDigests{}
	}
	return kennelDigests{Facts: facts, Policy: policy}
}

// kennelDigest covers the snapshot, and separately the policy and the
// evaluator's version, with a waiver counted by whether it still covers
// anything so that one ending is a change and its finding comes back within one
// pass.
func kennelDigest(s kennel.Snapshot, p kennel.Policy, now time.Time) kennelDigests {
	s.At = time.Time{}
	s.Fleet.Pools = slices.Clone(s.Fleet.Pools)
	slices.SortFunc(s.Fleet.Pools, func(a, b kennel.PoolFact) int { return strings.Compare(a.ID, b.ID) })
	type waiver struct {
		ID       string
		Code     kennel.Code
		Subject  string
		Severity kennel.Severity
		Ends     int64
		Active   bool
	}
	var waivers []waiver
	for _, w := range p.Waivers {
		waivers = append(waivers, waiver{w.ID, w.Code, w.Subject, w.Severity, w.ExpiresAt.UnixMilli(), now.Before(w.ExpiresAt)})
	}
	slices.SortFunc(waivers, func(a, b waiver) int { return strings.Compare(a.ID, b.ID) })
	var disabled []string
	for name, off := range p.Disabled {
		if off {
			disabled = append(disabled, name)
		}
	}
	slices.Sort(disabled)
	return kennelDigests{
		Facts: hashOf(s),
		Policy: hashOf(struct {
			Version  int
			Disabled []string
			Waivers  []waiver
		}{kennel.Version, disabled, waivers}),
	}
}

func hashOf(v any) string {
	raw, _ := json.Marshal(v)
	sum := sha256.Sum256(raw)
	return hex.EncodeToString(sum[:8])
}

package controller

import (
	"encoding/json"
	"slices"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/kennel"
	"github.com/eyupio/zoomies/internal/store"
)

var kennelNow = time.Date(2026, 10, 6, 12, 0, 0, 0, time.UTC)

// The jobs table cannot answer about a day it has already pruned, so the
// evidence never reaches back further than the fleet keeps jobs, and never
// further than thirty days however long they are kept.
func TestTheEvidenceWindowIsThirtyDaysOrTheJobRetentionIfThatIsShorter(t *testing.T) {
	for _, tc := range []struct {
		name      string
		retention time.Duration
		want      time.Duration
	}{
		{"the default retention", 30 * 24 * time.Hour, 30 * 24 * time.Hour},
		{"a longer retention", 90 * 24 * time.Hour, 30 * 24 * time.Hour},
		{"a shorter retention", 7 * 24 * time.Hour, 7 * 24 * time.Hour},
		{"retention switched off, which keeps everything", 0, 30 * 24 * time.Hour},
		{"a negative retention", -time.Hour, 30 * 24 * time.Hour},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := kennelWindow(tc.retention); got != tc.want {
				t.Errorf("window = %s, want %s", got, tc.want)
			}
		})
	}
}

func seen(id int64, event string, fork bool, age time.Duration) kennelSeenRun {
	return kennelSeenRun{ID: id, Event: event, Fork: fork, QueuedAt: kennelNow.Add(-age).UnixMilli()}
}

// A run is remembered once, newest first, and forgotten when it leaves the
// window: the finding it supports has to age out with it, or "in the last 30
// days" would be a lie.
func TestRunsAreRememberedOnceNewestFirstAndForgottenWhenTheyLeaveTheWindow(t *testing.T) {
	window := 30 * 24 * time.Hour
	var w kennelWatermark
	w.remember([]kennelSeenRun{seen(5, "pull_request", true, time.Hour), seen(3, "issues", false, 2*time.Hour)}, kennelNow, window)
	w.remember([]kennelSeenRun{seen(9, "pull_request", true, time.Minute), seen(5, "pull_request", true, time.Hour)}, kennelNow, window)

	var ids []int64
	for _, r := range w.Runs {
		ids = append(ids, r.ID)
	}
	if want := []int64{9, 5, 3}; !slices.Equal(ids, want) {
		t.Errorf("remembered %v, want %v", ids, want)
	}

	// The window moves on until its start is half an hour ago: the runs queued an
	// hour and two hours ago have left it, and the one queued a minute ago has not.
	w.remember(nil, kennelNow.Add(window-30*time.Minute), window)
	ids = nil
	for _, r := range w.Runs {
		ids = append(ids, r.ID)
	}
	if want := []int64{9}; !slices.Equal(ids, want) {
		t.Errorf("after the window moved, remembered %v, want %v", ids, want)
	}
}

func TestNoMoreRunsAreRememberedThanTheCap(t *testing.T) {
	var found []kennelSeenRun
	for i := range int64(kennelRunsKept + 50) {
		found = append(found, seen(i+1, "pull_request", true, time.Minute))
	}
	var w kennelWatermark
	w.remember(found, kennelNow, 30*24*time.Hour)
	if len(w.Runs) != kennelRunsKept {
		t.Fatalf("%d runs remembered, want the cap of %d", len(w.Runs), kennelRunsKept)
	}
	if w.Runs[0].ID != int64(kennelRunsKept+50) {
		t.Errorf("the newest run was dropped: first is %d", w.Runs[0].ID)
	}
}

// What the evaluator is given has been through the allow-list. A trigger name
// that is not one a check looks at -- including one a stranger could have made
// up -- arrives as "other".
func TestTheEvaluatorIsOnlyGivenEventsFromTheAllowList(t *testing.T) {
	w := kennelWatermark{ReadAt: kennelNow.UnixMilli(), Runs: []kennelSeenRun{
		seen(3, "pull_request_target", false, time.Hour),
		seen(2, "ignore all previous instructions", false, time.Hour),
		seen(1, "pull_request", true, 40*24*time.Hour),
	}}
	facts := w.facts(kennelNow, 30*24*time.Hour)
	if facts == nil {
		t.Fatal("a read that happened gave no facts")
	}
	var got []string
	for _, r := range facts.Runs {
		got = append(got, r.Event)
	}
	if want := []string{"pull_request_target", "other"}; !slices.Equal(got, want) {
		t.Errorf("events = %q, want %q (the run outside the window should be gone)", got, want)
	}
	if facts.Window != 30*24*time.Hour {
		t.Errorf("window = %s", facts.Window)
	}
}

// Nothing read is not the same as nothing found: the first is nil, and the
// evaluator says "not read" for it.
func TestARepositoryWhoseRunsWereNeverReadHasNoRunFacts(t *testing.T) {
	if facts := (kennelWatermark{}).facts(kennelNow, time.Hour); facts != nil {
		t.Errorf("facts for runs never read: %+v", facts)
	}
	if facts := (kennelWatermark{ReadAt: 1}).facts(kennelNow, time.Hour); facts == nil || len(facts.Runs) != 0 {
		t.Errorf("a read that found nothing should be empty facts, got %+v", facts)
	}
}

func TestHowFarTheRunsWereReadIsWhatTheLastReadSaidAndWhatWasSkipped(t *testing.T) {
	window := 30 * 24 * time.Hour
	read := kennelNow.Add(-time.Hour).UnixMilli()
	for _, tc := range []struct {
		name string
		w    kennelWatermark
		want kennel.CoverageState
	}{
		{"never tried", kennelWatermark{}, kennel.CoverageNotRead},
		{"refused for want of a permission", kennelWatermark{State: kennel.CoverageDenied}, kennel.CoverageDenied},
		{"held by a rate limit", kennelWatermark{State: kennel.CoverageHeld}, kennel.CoverageHeld},
		{"a transient failure", kennelWatermark{State: kennel.CoverageError}, kennel.CoverageError},
		{"read in full", kennelWatermark{ReadAt: read}, kennel.CoverageOK},
		// What was found stands; what was not found is not an all-clear. A
		// failure after a read that got somewhere must not erase the findings
		// by calling the whole source unreadable.
		{"a failure after a good read", kennelWatermark{ReadAt: read, State: kennel.CoverageDenied}, kennel.CoveragePartial},
		{"a gap still inside the window", kennelWatermark{ReadAt: read, GapQueuedAt: kennelNow.Add(-24 * time.Hour).UnixMilli()}, kennel.CoveragePartial},
		{"a gap that has aged out", kennelWatermark{ReadAt: read, GapQueuedAt: kennelNow.Add(-window - time.Hour).UnixMilli()}, kennel.CoverageOK},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := tc.w.coverage(kennelNow, window); got != tc.want {
				t.Errorf("coverage = %s, want %s", got, tc.want)
			}
		})
	}
}

func TestAStoredWatermarkThatDoesNotParseIsARepositoryNothingWasReadFor(t *testing.T) {
	for _, raw := range []string{"", "not json", `{"after":"x"}`, "[]"} {
		if w := parseKennelWatermark([]byte(raw)); w.After != 0 || w.ReadAt != 0 || len(w.Runs) != 0 {
			t.Errorf("%q parsed as %+v", raw, w)
		}
	}
	w := kennelWatermark{After: 7, ReadAt: 1, Runs: []kennelSeenRun{seen(7, "issues", false, time.Hour)}}
	if back := parseKennelWatermark(w.marshal()); back.After != 7 || len(back.Runs) != 1 || back.Runs[0].Event != "issues" {
		t.Errorf("round trip lost it: %+v", back)
	}
	if string((kennelWatermark{}).marshal()) == "null" || !json.Valid((kennelWatermark{}).marshal()) {
		t.Error("an empty watermark must still be a document the store will keep")
	}
}

// Pool.Dangerous is the sentence list an operator reads about a pool; the words
// the evaluator is given are the same four things. A fifth way for a pool to be
// dangerous must be a failing test here and not a hole in what Kennel Club
// notices about a stranger's code.
func TestEveryWayAPoolIsDangerousIsAWordTheEvaluatorKnows(t *testing.T) {
	for _, tc := range []struct {
		name string
		pool store.Pool
		want []kennel.PoolDanger
	}{
		{"the safe defaults", store.Pool{Ephemeral: true, DockerMode: store.DockerNone, Backend: store.BackendDocker}, nil},
		{"persistent", store.Pool{Ephemeral: false, Backend: store.BackendDocker}, []kennel.PoolDanger{kennel.DangerPersistent}},
		{"the host socket", store.Pool{Ephemeral: true, DockerMode: store.DockerHostSocket, Backend: store.BackendDocker}, []kennel.PoolDanger{kennel.DangerHostSocket}},
		{"a privileged sidecar", store.Pool{Ephemeral: true, DockerMode: store.DockerDinD, Backend: store.BackendDocker}, []kennel.PoolDanger{kennel.DangerPrivileged}},
		{"root", store.Pool{Ephemeral: true, RunAsRoot: true, Backend: store.BackendDocker}, []kennel.PoolDanger{kennel.DangerRoot}},
		{"no container", store.Pool{Ephemeral: true, Backend: store.BackendProcess}, []kennel.PoolDanger{kennel.DangerNoContainer}},
		{"all of them", store.Pool{Ephemeral: false, DockerMode: store.DockerHostSocket, RunAsRoot: true, Backend: store.BackendProcess},
			[]kennel.PoolDanger{kennel.DangerPersistent, kennel.DangerHostSocket, kennel.DangerRoot, kennel.DangerNoContainer}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			got := kennelDangers(&tc.pool)
			if !slices.Equal(got, tc.want) {
				t.Errorf("dangers = %v, want %v", got, tc.want)
			}
			// Everything Dangerous reports is something kennelDangers reports,
			// bar the process backend, which Dangerous does not call dangerous.
			words := len(got)
			if tc.pool.Backend == store.BackendProcess {
				words--
			}
			if sentences := len(tc.pool.Dangerous()); sentences != words {
				t.Errorf("Pool.Dangerous reports %d, and %d words come from it", sentences, words)
			}
		})
	}
}

func digestOf(s kennel.Snapshot, p kennel.Policy) kennelDigests { return kennelDigest(s, p, kennelNow) }

// The digest is what says "nothing has changed, do not evaluate again", so it
// has to ignore what is not a change -- the moment the facts were taken, the
// order the pools arrived in -- and see everything that is.
func TestTheDigestIgnoresWhatIsNotAChangeAndSeesWhatIs(t *testing.T) {
	base := kennel.Snapshot{
		At:   kennelNow,
		Repo: kennel.Repo{Visibility: kennel.VisibilityPublic},
		Fleet: kennel.Fleet{Window: 30 * 24 * time.Hour, Jobs: kennel.JobFacts{Ran: 3},
			Pools: []kennel.PoolFact{{ID: "pool_a", JobsRun: 2}, {ID: "pool_b", JobsRun: 1}}},
		Coverage: kennel.Coverage{kennel.SourceFleet: {State: kennel.CoverageOK}},
	}
	want := digestOf(base, kennel.Policy{})

	same := base
	same.At = kennelNow.Add(time.Hour)
	same.Fleet.Pools = []kennel.PoolFact{{ID: "pool_b", JobsRun: 1}, {ID: "pool_a", JobsRun: 2}}
	if got := digestOf(same, kennel.Policy{}); got != want {
		t.Error("the moment the facts were taken, or the pool order, changed the digest")
	}
	if base.Fleet.Pools[0].ID != "pool_a" {
		t.Error("working out the digest reordered the caller's pools")
	}

	for name, mutate := range map[string]func(*kennel.Snapshot){
		"visibility": func(s *kennel.Snapshot) { s.Repo.Visibility = kennel.VisibilityPrivate },
		"jobs ran":   func(s *kennel.Snapshot) { s.Fleet.Jobs.Ran++ },
		"a pool":     func(s *kennel.Snapshot) { s.Fleet.Pools = s.Fleet.Pools[:1] },
		"a danger": func(s *kennel.Snapshot) {
			s.Fleet.Pools = []kennel.PoolFact{{ID: "pool_a", JobsRun: 2, Dangers: []kennel.PoolDanger{kennel.DangerRoot}}, {ID: "pool_b", JobsRun: 1}}
		},
		"coverage": func(s *kennel.Snapshot) {
			s.Coverage = kennel.Coverage{kennel.SourceFleet: {State: kennel.CoveragePartial}}
		},
		"a run":  func(s *kennel.Snapshot) { s.Runs = &kennel.RunFacts{Runs: []kennel.Run{{ID: 1, Event: "issues"}}} },
		"a wait": func(s *kennel.Snapshot) { s.Fleet.Jobs.Unserved = []kennel.Unserved{{Waited: time.Hour}} },
	} {
		changed := base
		changed.Fleet.Pools = slices.Clone(base.Fleet.Pools)
		mutate(&changed)
		got := digestOf(changed, kennel.Policy{})
		if got.Facts == want.Facts {
			t.Errorf("a change of %s did not change the facts digest", name)
		}
		if got.Policy != want.Policy {
			t.Errorf("a change of %s changed the policy digest, which would skip the ten-minute rule", name)
		}
	}
}

// What the operator decided is a different half of the digest from what the
// fleet did, because the two are throttled differently: a change of policy is
// evaluated at once, and a change of facts waits for the ten-minute rule.
func TestTheDigestSeesTheOperatorsDecisionsAndWhenAWaiverStopsCounting(t *testing.T) {
	s := kennel.Snapshot{Repo: kennel.Repo{Visibility: kennel.VisibilityPublic}}
	waiver := kennel.Waiver{ID: "kcw_1", Code: kennel.CodeForkCodeRan, Severity: kennel.SeverityError, ExpiresAt: kennelNow.Add(time.Hour)}
	none := kennelDigest(s, kennel.Policy{}, kennelNow)

	with := kennelDigest(s, kennel.Policy{Waivers: []kennel.Waiver{waiver}}, kennelNow)
	if with.Policy == none.Policy {
		t.Error("a waiver did not change the policy digest")
	}
	if with.Facts != none.Facts {
		t.Error("a waiver changed the facts digest")
	}
	// The same waiver after it ends: nothing in the snapshot moved, and the
	// finding must come back, so the digest has to.
	if after := kennelDigest(s, kennel.Policy{Waivers: []kennel.Waiver{waiver}}, kennelNow.Add(2*time.Hour)); after.Policy == with.Policy {
		t.Error("a waiver ending did not change the digest, so the finding would stay hidden until something else moved")
	}
	off := kennelDigest(s, kennel.Policy{Disabled: map[string]bool{"exposure": true}}, kennelNow)
	if off.Policy == none.Policy || off.Facts != none.Facts {
		t.Errorf("turning an area off should change only the policy half: %+v against %+v", off, none)
	}
	if same := kennelDigest(s, kennel.Policy{Disabled: map[string]bool{"exposure": false}}, kennelNow); same != none {
		t.Error("a check recorded as not turned off changed the digest")
	}
}

func TestADigestSurvivesBeingStoredAndRead(t *testing.T) {
	d := kennelDigest(kennel.Snapshot{}, kennel.Policy{}, kennelNow)
	if got := parseKennelDigests(d.String()); got != d {
		t.Errorf("round trip gave %+v, want %+v", got, d)
	}
	for _, junk := range []string{"", "no separator", "/"} {
		if got := parseKennelDigests(junk); got == d {
			t.Errorf("%q parsed as a real digest", junk)
		}
	}
}

package controller

import (
	"errors"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/kennel"
	"github.com/eyupio/zoomies/internal/store"
)

// An administrator may stop Kennel Club looking at a repository and an operator
// may only start it again, which is the whole of the rule: the controller is told
// what the caller holds and does not look it up.
var (
	trackingAdmin    = KennelActor{ID: "usr_ada", Name: "ada", CanUntrack: true}
	trackingOperator = KennelActor{ID: "usr_oscar", Name: "oscar"}
)

const sandboxReason = "a sandbox nobody keeps up, and its jobs are not ours to judge"

// stopTracking is an administrator saying Kennel Club is not to look at a
// repository, and returns the repository as the page would then show it.
func (f *kennelFixture) stopTracking(name string) KennelRepositoryView {
	f.t.Helper()
	v, _, changed, err := f.c.SetKennelTracking(f.ctx, f.row(name).ID, KennelTrackingInput{Reason: sandboxReason}, trackingAdmin)
	if err != nil || !changed {
		f.t.Fatalf("stopping tracking %s: changed %v, %v", name, changed, err)
	}
	return *v
}

func (f *kennelFixture) startTracking(name string) {
	f.t.Helper()
	if _, _, changed, err := f.c.SetKennelTracking(f.ctx, f.row(name).ID, KennelTrackingInput{Tracked: true}, trackingOperator); err != nil || !changed {
		f.t.Fatalf("starting tracking %s: changed %v, %v", name, changed, err)
	}
}

// ---------------------------------------------------------------------------
// The loop leaves what is not tracked alone
// ---------------------------------------------------------------------------

// A stopped row is put back to before anything evaluated it, which is a row that
// reads as due. If that were enough to make the pass list the installation from
// GitHub, a repository nobody is looking at would cost a request every minute
// for as long as it was untracked.
func TestARepositoryNobodyTracksNeverMakesAPassListTheInstallation(t *testing.T) {
	f := newKennelFixture(t)
	f.repo("acme/sandbox", "private")
	f.ran("acme/sandbox", 1, f.pool)
	f.pass()
	if n := f.requestsTo("/installation/repositories"); n != 1 {
		t.Fatalf("listed %d times in the first pass, want 1", n)
	}
	f.stopTracking("acme/sandbox")

	// It is still served, and its row is still there, so it is neither a repository
	// the pass has no row for nor one that is due.
	for range 3 {
		f.advance(time.Minute)
		f.pass()
	}
	if n := f.requestsTo("/installation/repositories"); n != 1 {
		t.Errorf("the installation was listed %d times with only an untracked repository to look at, want the first alone", n)
	}
}

// A failure noted for an installation is cleared by a listing that works, and a
// pass with nothing due makes none. That is right while a tracked repository is
// waiting for its time, since the failure may still be true of it. It is wrong
// once the last tracked repository on an installation is let go: nothing there is
// read any more, so nothing would ever clear the note, and the Overview would go
// on saying that the repositories on it cannot be read.
func TestAnInstallationWithNothingLeftToTrackIsNotReportedAsUnreadable(t *testing.T) {
	f := newKennelFixture(t)
	failed := func() {
		f.c.kennel.mu.Lock()
		f.c.kennel.notes[f.inst.ID] = kennelNote{State: kennel.CoverageError, Since: f.c.Now().Add(-7 * time.Hour)}
		f.c.kennel.mu.Unlock()
	}

	// An installation Kennel Club has no row for has not been let go by anybody, and
	// a pass that read nothing there still says nothing about whether reading works.
	failed()
	f.pass()
	if got := kennelProblemsOf(t, f, "kennel.unavailable"); len(got) != 1 {
		t.Fatalf("with no repository at all, the failure was %+v, want it kept", got)
	}

	f.repo("acme/sandbox", "private")
	f.repo("acme/kept", "private")
	f.ran("acme/sandbox", 1, f.pool)
	f.ran("acme/kept", 2, f.pool)
	f.pass()
	failed()

	f.stopTracking("acme/sandbox")
	f.pass()
	if got := kennelProblemsOf(t, f, "kennel.unavailable"); len(got) != 1 {
		t.Fatalf("with a repository still tracked and none due, the failure was %+v, want it kept: a pass that read nothing says nothing about reading", got)
	}

	f.stopTracking("acme/kept")
	f.pass()
	if got := kennelProblemsOf(t, f, "kennel.unavailable"); len(got) != 0 {
		t.Errorf("with every repository let go, the installation was still reported as unreadable: %+v", got)
	}
}

// What is tracked beside it is read as it was. The untracked repository is not:
// no run is read for it, even a new one, and nothing is evaluated.
func TestAPassThatReadsOnePublicRepositoryDoesNotReadTheOneNobodyTracks(t *testing.T) {
	f := newKennelFixture(t)
	f.persistent()
	for i, name := range []string{"acme/sandbox", "acme/live"} {
		f.repo(name, "public")
		f.ran(name, int64(10+i), f.pool)
		f.trigger(name, int64(10+i), "push", false)
	}
	f.pass()
	f.stopTracking("acme/sandbox")
	liveBefore := f.view("acme/live").EvaluatedAt

	// A new run in each, and a day on, so both would be due.
	f.ran("acme/sandbox", 20, f.pool)
	f.trigger("acme/sandbox", 20, "push", false)
	f.ran("acme/live", 21, f.pool)
	f.trigger("acme/live", 21, "push", false)
	f.dueAgain()
	before := f.runReads()
	f.pass()

	if n := f.requestsTo("acme/sandbox/actions/runs/"); n != 1 {
		t.Errorf("%d reads of the sandbox's runs in all, want only the one made before it was untracked", n)
	}
	if got := f.runReads() - before; got != 1 {
		t.Errorf("%d runs read in the pass, want the one run of the repository that is tracked", got)
	}
	if live := f.view("acme/live"); live.EvaluatedAt == nil || liveBefore == nil || !live.EvaluatedAt.After(*liveBefore) {
		t.Errorf("the repository that is tracked was not evaluated again in the pass: was %v, now %v", liveBefore, live.EvaluatedAt)
	}
	if got := f.row("acme/sandbox"); got.EvaluatedAt != nil || got.State != "pending" {
		t.Errorf("the untracked repository was evaluated: state %s, at %v", got.State, got.EvaluatedAt)
	}
}

