// migrationClient resolves the installation and its GitHub client.
func (c *Controller) migrationClient(ctx context.Context, id string) (*store.Installation, github.Client, error) {
	inst, err := c.st.GetInstallation(ctx, strings.TrimSpace(id))
	if err != nil {
		return nil, nil, err
	}
	client, err := c.ClientFor(ctx, inst.ID)
	if err != nil {
		return nil, nil, fmt.Errorf("authenticating as the GitHub App: %w", err)
	}
	return inst, client, nil
}

// migrationPools returns the enabled pools belonging to an installation, which
// are the only places a job could actually be sent.
func (c *Controller) migrationPools(ctx context.Context, installationID string) ([]*store.Pool, error) {
	all, err := c.st.ListPools(ctx)
	if err != nil {
		return nil, err
	}
	var out []*store.Pool
	for _, p := range all {
		if p.InstallationID == installationID && p.Enabled {
			out = append(out, p)
		}
	}
	return out, nil
}

func poolOptions(pools []*store.Pool) []MigrationPoolOption {
	out := make([]MigrationPoolOption, 0, len(pools))
	for _, p := range pools {
		out = append(out, MigrationPoolOption{
			ID:      p.ID,
			Name:    p.Name,
			Labels:  emptySlice(p.Labels),
			RunsOn:  store.RunsOn(p.Labels),
			Enabled: p.Enabled,
		})
	}
	return out
}

// migrationRepos resolves the repositories a request names, or one page of
// what the installation can see when it names none.
//
// It returns the page, the cursor for the page after it -- empty when there is
// none -- and how many repositories the installation can see in total, so the
// wizard can say which slice of an organisation is on screen and go and get
// the next one. Paging rather than one big scan is deliberate: reading every
// workflow file in a thousand repositories is the most expensive thing Zoomies
// asks GitHub for, and it spends the quota the scheduler shares.
func migrationRepos(ctx context.Context, client github.Client, named []string, cursor string, limit int) ([]github.Repository, string, int, error) {
	all, err := client.ListRepositories(ctx, 0)
	if err != nil {
		return nil, "", 0, err
	}
	byName := make(map[string]github.Repository, len(all))
	for _, r := range all {
		byName[strings.ToLower(r.FullName)] = r
	}

	if len(named) > 0 {
		out := make([]github.Repository, 0, len(named))
		for _, want := range named {
			want = strings.TrimSpace(want)
			if want == "" {
				continue
			}
			repo, ok := byName[strings.ToLower(want)]
			if !ok {
				// A repository the App cannot see is named, not silently
				// dropped: the operator picked it, and it disappearing from the
				// results with no explanation is worse than a failure.
				return nil, "", 0, fmt.Errorf("%w: this installation cannot see %s; check the App is installed on it", github.ErrNotFound, want)
			}
			out = append(out, repo)
		}
		return out, "", len(out), nil
	}

	// Sorted by the lowercased name, because that is the order the cursor
	// below is compared in. GitHub's names are mixed case, and ordering by raw
	// bytes puts every capitalised name before every lowercase one -- so the
	// search for the cursor would run over an order it does not share, and the
	// repositories between the two orders would appear on no page at all. A
	// repository the wizard never lists is one nobody can migrate.
	sort.Slice(all, func(i, j int) bool {
		return strings.ToLower(all[i].FullName) < strings.ToLower(all[j].FullName)
	})
	total := len(all)

	// The cursor is a name rather than an offset, so a repository added or
	// removed between two pages shifts nothing: the next page is whatever
	// sorts after the last name the operator has already seen.
	if after := strings.ToLower(strings.TrimSpace(cursor)); after != "" {
		i := sort.Search(len(all), func(i int) bool { return strings.ToLower(all[i].FullName) > after })
		all = all[i:]
	}
	if len(all) > limit {
		return all[:limit], all[limit-1].FullName, total, nil
	}
	return all, "", total, nil
}

// workflowSelection turns the apply request's per-repository workflow paths
// into a lookup, refusing anything that is not a file GitHub would run.
//
// A path that is not a workflow is a client bug, and accepting it silently
// would mean a repository whose pull request quietly changes nothing.
func workflowSelection(in map[string][]string) (map[string]map[string]bool, error) {
	if len(in) == 0 {
		return nil, nil
	}
	out := make(map[string]map[string]bool, len(in))
	for repo, paths := range in {
		repo = strings.ToLower(strings.TrimSpace(repo))
		if repo == "" {
			continue
		}
		set := make(map[string]bool, len(paths))
		for _, p := range paths {
			p = strings.TrimSpace(p)
			if p == "" {
				continue
			}
			if !migrate.IsWorkflowPath(p) {
				return nil, fmt.Errorf("%w: %q is not one", ErrNotAWorkflow, p)
			}
			set[p] = true
		}
		if len(set) == 0 {
			return nil, fmt.Errorf("%w: %s named none, so leave it out to migrate every file the mapping covers", ErrNotAWorkflow, repo)
		}
		out[repo] = set
	}
	if len(out) == 0 {
		return nil, nil
	}
	return out, nil
}

// selectWorkflows keeps only the files the operator chose, so the pull request
// body still reports the jobs left behind in the files it did touch.
func selectWorkflows(plan migrate.RepoPlan, only map[string]bool) migrate.RepoPlan {
	out := plan
	out.Workflows = make([]migrate.WorkflowPlan, 0, len(plan.Workflows))
	for _, wf := range plan.Workflows {
		if only[wf.Path] {
			out.Workflows = append(out.Workflows, wf)
		}
	}
	return out
}

// workflowSource is one repository's workflows, or why they could not be read.
type workflowSource struct {
	repo      github.Repository
	workflows []migrate.Workflow
	err       string
}

// workflowReadCancelled is what a repository says when the request ended before
// it was read, so that an organisation shown as partly read can be told from
// one with nothing to migrate.
const workflowReadCancelled = "the request was cancelled before this repository was read"

// readWorkflows reads every repository's workflows, a few at a time.
//
// One repository failing is recorded against that repository rather than
// failing the scan: in an organisation of any size there is always one the App
// was removed from, and one with a .github/workflows that is a file rather
// than a directory.
//
// An archived repository is not read at all. Nothing could be opened against
// it whatever its workflows say, and a scan of an organisation that has been
// tidying up for years would otherwise spend most of its GitHub quota on
// repositories the wizard is about to grey out.
func readWorkflows(ctx context.Context, client github.Client, repos []github.Repository, log *slog.Logger) []workflowSource {
	out := make([]workflowSource, len(repos))
	sem := make(chan struct{}, planConcurrency)
	var wg sync.WaitGroup

	for i, repo := range repos {
		// The slot is taken here, before the goroutine exists. Taken inside it,
		// an organisation of ten thousand repositories parked ten thousand
		// goroutines on the semaphore to read four at a time, and a request that
		// had been given up on still queued every one of them.
		select {
		case sem <- struct{}{}:
		case <-ctx.Done():
			out[i] = workflowSource{repo: repo}
			if !repo.Archived {
				out[i].err = workflowReadCancelled
			}
			continue
		}
		wg.Add(1)
		go func() {
			defer wg.Done()
			defer func() { <-sem }()
			// Nothing above this goroutine can recover a panic in it, and a
			// listing that panics for one repository should cost that
			// repository, as one that cannot be read already does, and not the
			// process.
			defer func() {
				if r := recover(); r != nil {
					log.Error("reading a repository's workflows panicked; it is recorded against that repository and the read carries on",
						"repo", repo.FullName, "panic", r, "stack", string(debug.Stack()))
					out[i].err = fmt.Sprintf("reading this repository's workflows panicked: %v", r)
				}
			}()

			out[i] = workflowSource{repo: repo}
			if repo.Archived {
				return
			}
			if ctx.Err() != nil {
				out[i].err = workflowReadCancelled
				return
			}
			files, err := client.ListWorkflows(ctx, repo.FullName)
			switch {
			case errors.Is(err, github.ErrNoWorkflows):
				// Not an error: most repositories have no workflows.
			case err != nil:
				out[i].err = err.Error()
			default:
				out[i].workflows = asMigrateWorkflows(files)
			}
		}()
	}
	wg.Wait()
	return out
}

func asMigrateWorkflows(files []github.WorkflowFile) []migrate.Workflow {
	out := make([]migrate.Workflow, 0, len(files))
	for _, f := range files {
		if !migrate.IsWorkflowPath(f.Path) {
			continue
		}
		out = append(out, migrate.Workflow{Path: f.Path, SHA: f.SHA, Content: f.Content})
	}
	return out
}

// hostedLabelsAcross collects every GitHub-hosted label the scan found, sorted
// so the mapping step is in the same order every time it is opened.
func hostedLabelsAcross(sources []workflowSource) []string {
	seen := map[string]bool{}
	var out []string
	for _, src := range sources {
		for _, wf := range src.workflows {
			for _, l := range migrate.HostedLabelsIn(wf.Content) {
				if !seen[l] {
					seen[l] = true
					out = append(out, l)
				}
			}
		}
	}
	sort.Strings(out)
	return out
}

// normaliseOverrides trims the overrides a request carries and refuses the ones
// that name nothing.
//
// A malformed override is refused rather than dropped. The operator picked that
// job on the review screen, and a migration that quietly ignored the exception
// they asked for -- sending the job to the consolidated pool instead -- is the
// kind of surprise every other decision in this file is shaped to avoid.
func normaliseOverrides(in []migrate.Override) ([]migrate.Override, error) {
	out := make([]migrate.Override, 0, len(in))
	seen := make(map[string]bool, len(in))
	for i, o := range in {
		o = migrate.Override{
			Repo: strings.TrimSpace(o.Repo),
			Path: strings.TrimSpace(o.Path),
			Job:  strings.TrimSpace(o.Job),
			To:   strings.TrimSpace(o.To),
		}
		switch {
		case o.Repo == "":
			return nil, fmt.Errorf("%w, and override %d names no repository", ErrBadOverride, i+1)
		case o.Job == "":
			// Not every runs-on can be attributed to a job, and one that cannot
			// has no name that survives the file being read again at apply time.
			return nil, fmt.Errorf("%w, and override %d names no job; a runs-on the plan could not attribute to one cannot be overridden", ErrBadOverride, i+1)
		case !migrate.IsWorkflowPath(o.Path):
			return nil, fmt.Errorf("%w, and override %d names %q, which is not a workflow file GitHub runs", ErrBadOverride, i+1, o.Path)
		}
		key := strings.ToLower(o.Repo) + "\x00" + o.Path + "\x00" + o.Job
		if seen[key] {
			// Two answers for one job is not a preference, it is a bug in
			// whatever built the request, and picking one of them silently
			// would hide it.
			return nil, fmt.Errorf("%w, and %s in %s is overridden twice", ErrBadOverride, o.Job, o.Path)
		}
		seen[key] = true
		out = append(out, o)
	}
	return out, nil
}

// anyOverrideWrites reports whether any override would actually move a job. One
// that says "stay where you are" is a decision, but it is not a reason to open
// a pull request.
func anyOverrideWrites(in []migrate.Override) bool {
	for _, o := range in {
		if o.To != "" {
			return true
		}
	}
	return false
}

// normaliseMapping lowercases the keys and drops the entries the browser sends
// for a label the operator chose not to map, which arrive as empty strings.
func normaliseMapping(in map[string]string) map[string]string {
	out := make(map[string]string, len(in))
	for k, v := range in {
		k, v = strings.ToLower(strings.TrimSpace(k)), strings.TrimSpace(v)
		if k == "" || v == "" {
			continue
		}
		out[k] = v
	}
	return out
}

package controller

import (
	"context"
	"fmt"
	"log/slog"
	"runtime"
	"strings"
	"sync/atomic"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/migrate"
	"github.com/eyupio/zoomies/internal/store"
)

// Paging through an organisation has to reach every repository in it, whatever
// case its name is written in.
//
// The cursor is a repository name, and it is compared in lowercase so that the
// one the browser sends back matches whatever GitHub returned. That only works
// if the listing is ordered the same way: sorted by raw bytes, every
// capitalised name sorts before every lowercase one, the binary search for the
// cursor runs over an order it does not share, and the repositories caught
// between the two are returned on no page at all. They are not merely
// misordered -- they are unreachable, and a repository the wizard never lists
// is one nobody can migrate.
func TestMigrationPagingReachesEveryRepositoryWhateverItsCase(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()

	// Names GitHub would really return: some capitalised, some not, mixed
	// together so that no single ordering happens to work by luck.
	var want []string
	for i := 0; i < 12; i++ {
		name := fmt.Sprintf("acme/repo%02d", i)
		if i%2 == 0 {
			name = fmt.Sprintf("acme/Repo%02d", i)
		}
		h.gh.AddRepo(name)
		want = append(want, strings.ToLower(name))
	}

	client, err := h.c.ClientFor(h.ctx, inst.ID)
	if err != nil {
		t.Fatalf("ClientFor: %v", err)
	}

	// A page size that does not divide the fleet evenly, so the last page is a
	// partial one and the cursor is exercised more than once.
	const perPage = 5
	seen := map[string]int{}
	cursor := ""
	for page := 0; ; page++ {
		if page > len(want) {
			t.Fatalf("paging did not terminate after %d pages", page)
		}
		repos, next, total, err := migrationRepos(h.ctx, client, nil, cursor, perPage)
		if err != nil {
			t.Fatalf("migrationRepos(cursor=%q): %v", cursor, err)
		}
		if total != len(want) {
			t.Errorf("total = %d on page %d, want %d: the wizard reports which slice of the organisation is on screen", total, page, len(want))
		}
		for _, r := range repos {
			seen[strings.ToLower(r.FullName)]++
		}
		if next == "" {
			break
		}
		cursor = next
	}

	for _, name := range want {
		switch seen[name] {
		case 1:
		case 0:
			t.Errorf("%s appeared on no page, so it can never be migrated", name)
		default:
			t.Errorf("%s appeared on %d pages, so the wizard offers it twice", name, seen[name])
		}
	}
}

// The cursor is matched without regard to case, so a client that lowercases the
// name it was handed still gets the page after it rather than a repeat of the
// one it has.
func TestMigrationPagingAcceptsACursorInAnyCase(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()

	for _, name := range []string{"acme/Alpha", "acme/Bravo", "acme/Charlie", "acme/Delta"} {
		h.gh.AddRepo(name)
	}

	client, err := h.c.ClientFor(h.ctx, inst.ID)
	if err != nil {
		t.Fatalf("ClientFor: %v", err)
	}

	first, next, _, err := migrationRepos(h.ctx, client, nil, "", 2)
	if err != nil {
		t.Fatalf("first page: %v", err)
	}
	if next == "" {
		t.Fatalf("first page of four repositories at two a page says it is the whole organisation")
	}

	for _, cursor := range []string{next, strings.ToLower(next), strings.ToUpper(next)} {
		rest, _, _, err := migrationRepos(h.ctx, client, nil, cursor, 2)
		if err != nil {
			t.Fatalf("second page (cursor %q): %v", cursor, err)
		}
		for _, r := range rest {
			for _, had := range first {
				if strings.EqualFold(r.FullName, had.FullName) {
					t.Errorf("cursor %q returned %s again, which the operator has already seen", cursor, r.FullName)
				}
			}
		}
	}
}

// A repository the operator named by hand is matched without regard to case:
// GitHub resolves a repository URL that way, and an operator who typed the name
// into the wizard should not be told their own repository does not exist.
func TestMigrationReposMatchesANamedRepositoryWhateverItsCase(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	h.gh.AddRepo("acme/Widgets")

	client, err := h.c.ClientFor(h.ctx, inst.ID)
	if err != nil {
		t.Fatalf("ClientFor: %v", err)
	}

	for _, named := range []string{"acme/Widgets", "acme/widgets", "ACME/WIDGETS"} {
		repos, next, total, err := migrationRepos(h.ctx, client, []string{named}, "", MaxPlanRepos)
		if err != nil {
			t.Fatalf("migrationRepos(%q): %v", named, err)
		}
		if len(repos) != 1 || !strings.EqualFold(repos[0].FullName, "acme/Widgets") {
			t.Fatalf("migrationRepos(%q) = %v, want the one repository", named, repos)
		}
		// A named request is not a page of a listing: there is nothing after it.
		if next != "" || total != 1 {
			t.Errorf("migrationRepos(%q) = cursor %q total %d, want no cursor and a total of 1", named, next, total)
		}
	}
}

// A pool that belongs to another installation is not somewhere this one's jobs
// could be sent, so it is not offered as a migration target. Getting this wrong
// would point one organisation's workflows at another's runners.
func TestMigrationPoolsAreScopedToTheirInstallation(t *testing.T) {
	h := newHarness(t)
	mine := h.installation()
	theirs := h.installationOn("globex", store.TargetOrg)

	wanted := h.pool(mine, "mine-linux")
	h.pool(theirs, "theirs-linux")

	disabled := h.pool(mine, "mine-windows")
	disabled.Enabled = false
	if err := h.st.UpdatePool(h.ctx, disabled); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}

	pools, err := h.c.migrationPools(h.ctx, mine.ID)
	if err != nil {
		t.Fatalf("migrationPools: %v", err)
	}
	if len(pools) != 1 || pools[0].ID != wanted.ID {
		var got []string
		for _, p := range pools {
			got = append(got, p.Name)
		}
		t.Fatalf("migrationPools = %v, want only the enabled pool of this installation (%s)", got, wanted.Name)
	}
}

// The badge is on by default and rides in the same pull request as the
// runs-on change, in the README GitHub renders, at the end of the row of
// badges that is already there.
func TestApplyMigrationAddsTheBadgeByDefault(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	h.pool(inst, "linux-x64", "zoomies-linux-x64")
	h.gh.AddWorkflow("acme/widgets", ".github/workflows/ci.yml", "jobs:\n  build:\n    runs-on: ubuntu-latest\n")
	h.gh.AddFile("acme/widgets", "README.md", "# Widgets\n\n[![CI](https://x/ci.svg)](https://x)\n\nProse.\n")

	out, err := h.c.ApplyMigration(h.ctx, MigrationApplyRequest{
		InstallationID: inst.ID,
		Repos:          []string{"acme/widgets"},
		Mapping:        map[string]string{"ubuntu-latest": "zoomies-linux-x64"},
	})
	if err != nil {
		t.Fatalf("ApplyMigration: %v", err)
	}
	if len(out.Results) != 1 || out.Results[0].Status != "opened" {
		t.Fatalf("results = %+v", out.Results)
	}
	res := out.Results[0]
	if res.Badge != BadgeAdded || res.BadgeReason != "" {
		t.Errorf("badge = %q (%q), want %q", res.Badge, res.BadgeReason, BadgeAdded)
	}
	// The pull request changed one workflow file; the README is not counted
	// as one, because "files" on the results screen means workflow files.
	if res.Workflows != 1 || res.Jobs != 1 {
		t.Errorf("workflows=%d jobs=%d, want 1 and 1", res.Workflows, res.Jobs)
	}
	got, _ := h.gh.FileContent("acme/widgets", "README.md")
	want := "# Widgets\n\n[![CI](https://x/ci.svg)](https://x)\n" + migrate.BadgeMarkdown + "\n\nProse.\n"
	if got != want {
		t.Errorf("README on GitHub:\n%s\nwant:\n%s", got, want)
	}
	if wf, _ := h.gh.FileContent("acme/widgets", ".github/workflows/ci.yml"); !strings.Contains(wf, "zoomies-linux-x64") {
		t.Errorf("the workflow was not rewritten alongside the badge: %q", wf)
	}
	if body := h.gh.PullRequestBody("acme/widgets", 1); !strings.Contains(body, migrate.BadgeMarkdown) {
		t.Errorf("the pull request body does not say the badge is in it:\n%s", body)
	}
}

// The README is somebody else's front page, so one word from the operator
// leaves it alone -- and a README that is missing, not Markdown, or already
// badged is reported rather than either failing the migration or being
// written into anyway.
func TestApplyMigrationBadgeIsDeclinedAndReported(t *testing.T) {
	no := false
	cases := map[string]struct {
		readme  string // "" for no README
		path    string
		badge   *bool
		want    string
		touched bool
	}{
		"declined":         {readme: "# W\n", path: "README.md", badge: &no, want: BadgeOff},
		"no readme":        {want: BadgeNoReadme},
		"not markdown":     {readme: "Widgets\n=======\n", path: "README.rst", want: BadgeNoReadme},
		"already there":    {readme: "# W\n\n" + migrate.BadgeMarkdown + "\n", path: "README.md", want: BadgePresent},
		"explicitly asked": {readme: "# W\n", path: "README.md", badge: ptr(true), want: BadgeAdded, touched: true},
	}
	for name, tc := range cases {
		t.Run(name, func(t *testing.T) {
			h := newHarness(t)
			inst := h.installation()
			h.pool(inst, "linux-x64", "zoomies-linux-x64")
			h.gh.AddWorkflow("acme/widgets", ".github/workflows/ci.yml", "jobs:\n  build:\n    runs-on: ubuntu-latest\n")
			if tc.path != "" {
				h.gh.AddFile("acme/widgets", tc.path, tc.readme)
			}
			out, err := h.c.ApplyMigration(h.ctx, MigrationApplyRequest{
				InstallationID: inst.ID,
				Repos:          []string{"acme/widgets"},
				Mapping:        map[string]string{"ubuntu-latest": "zoomies-linux-x64"},
				Badge:          tc.badge,
			})
			if err != nil {
				t.Fatalf("ApplyMigration: %v", err)
			}
			res := out.Results[0]
			if res.Status != "opened" {
				t.Fatalf("the migration itself must go ahead whatever the badge does: %+v", res)
			}
			if res.Badge != tc.want {
				t.Errorf("badge = %q (%q), want %q", res.Badge, res.BadgeReason, tc.want)
			}
			if tc.want == BadgeNoReadme && res.BadgeReason == "" {
				t.Error("no_readme carries no reason, so the results screen cannot say which kind of nowhere")
			}
			if tc.path != "" {
				got, _ := h.gh.FileContent("acme/widgets", tc.path)
				if touched := got != tc.readme; touched != tc.touched {
					t.Errorf("README changed = %v, want %v:\n%s", touched, tc.touched, got)
				}
			}
			if body := h.gh.PullRequestBody("acme/widgets", 1); strings.Contains(body, "### The badge") != tc.touched {
				t.Errorf("the body mentions the badge = %v, want %v", !tc.touched, tc.touched)
			}
		})
	}
}

// workflowGate is a GitHub client that is asked only for workflows and holds
// each answer until it is released, which is what reading a large organisation
// looks like from this side. Every other method is the embedded nil
// interface's, so a read that strayed into asking for anything else fails loudly.
type workflowGate struct {
	github.Client
	release chan struct{}
	calls   atomic.Int32
	// panicOn is the repository whose listing blows up.
	panicOn string
}

func (g *workflowGate) ListWorkflows(ctx context.Context, repo string) ([]github.WorkflowFile, error) {
	g.calls.Add(1)
	if repo == g.panicOn {
		panic("a nil pointer where a workflow listing should be")
	}
	select {
	case <-g.release:
		return nil, github.ErrNoWorkflows
	case <-ctx.Done():
		return nil, ctx.Err()
	}
}

var quietLog = slog.New(slog.DiscardHandler)

func reposNamed(n int) []github.Repository {
	repos := make([]github.Repository, n)
	for i := range repos {
		repos[i] = github.Repository{FullName: fmt.Sprintf("acme/repo%03d", i)}
	}
	return repos
}

// Reading an organisation's workflows is meant to be a few repositories at a
// time. It used to start a goroutine for every repository at once and leave all
// but four parked on the semaphore, so ten thousand repositories cost ten
// thousand goroutines for a job that never reads more than four.
func TestReadingWorkflowsStartsNoMoreWorkersThanItMayRunAtOnce(t *testing.T) {
	gate := &workflowGate{release: make(chan struct{})}
	repos := reposNamed(20 * planConcurrency)
	before := runtime.NumGoroutine()

	done := make(chan []workflowSource, 1)
	go func() { done <- readWorkflows(context.Background(), gate, repos, quietLog) }()
	eventually(t, 5*time.Second, "the first readers to be waiting on GitHub", func() bool {
		return int(gate.calls.Load()) == planConcurrency
	})

	// The readers, and the goroutine above that is running readWorkflows.
	if extra := runtime.NumGoroutine() - before; extra > 2*planConcurrency {
		t.Errorf("%d goroutines started for %d repositories, of which %d may be read at once", extra, len(repos), planConcurrency)
	}

	close(gate.release)
	got := <-done
	for i, src := range got {
		if src.repo.FullName != repos[i].FullName || src.err != "" {
			t.Fatalf("repository %d came back as %+v, want it read and in order", i, src)
		}
	}
}

// A request that is given up on stops waiting for a slot. The repositories it
// never reached have to say so: the wizard shows an organisation as partly
// read, where a silent empty result would show repositories with nothing to
// migrate.
func TestACancelledReadSaysWhichRepositoriesItNeverReached(t *testing.T) {
	gate := &workflowGate{release: make(chan struct{})}
	repos := reposNamed(3 * planConcurrency)
	archived := repos[2*planConcurrency+1].FullName
	repos[2*planConcurrency+1].Archived = true // never read, so it never has anything to report
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	done := make(chan []workflowSource, 1)
	go func() { done <- readWorkflows(ctx, gate, repos, quietLog) }()
	eventually(t, 5*time.Second, "the first readers to be waiting on GitHub", func() bool {
		return int(gate.calls.Load()) == planConcurrency
	})
	cancel()
	got := <-done

	if calls := int(gate.calls.Load()); calls != planConcurrency {
		t.Errorf("GitHub was asked about %d repositories; none should be asked once the request is cancelled", calls)
	}
	inFlight, unreached := 0, 0
	for _, src := range got {
		switch {
		case src.err == context.Canceled.Error():
			inFlight++
		case strings.Contains(src.err, "cancelled"):
			unreached++
		case src.err != "":
			t.Errorf("%s reported %q, want a cancellation", src.repo.FullName, src.err)
		case src.repo.FullName != archived:
			t.Errorf("%s was neither read nor reported as unread", src.repo.FullName)
		}
	}
	if inFlight != planConcurrency || unreached != len(repos)-planConcurrency-1 {
		t.Errorf("%d reads were cut off and %d repositories were never reached, want %d and %d",
			inFlight, unreached, planConcurrency, len(repos)-planConcurrency-1)
	}
}

// The reads run on goroutines of their own, which a request cannot recover: a
// listing that panics for one repository has to cost that repository and not
// the process, the way one unreadable repository already does.
func TestAPanicReadingOneRepositoryIsRecordedAgainstThatRepository(t *testing.T) {
	repos := reposNamed(5)
	gate := &workflowGate{release: make(chan struct{}), panicOn: repos[2].FullName}
	close(gate.release)

	got := readWorkflows(context.Background(), gate, repos, quietLog)

	for i, src := range got {
		switch {
		case i == 2 && !strings.Contains(src.err, "nil pointer"):
			t.Errorf("the repository whose listing panicked reported %q, want the panic said", src.err)
		case i != 2 && src.err != "":
			t.Errorf("%s reported %q, but nothing was wrong with it", src.repo.FullName, src.err)
		}
	}
}

func ptr[T any](v T) *T { return &v }

package controller

import (
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// EffectiveMinimum is the minimum size a pool's runners are actually held to:
// the pool's own figure on a field where it set one, and otherwise the fleet's
// runners.minimum_cpus / runners.minimum_memory_mb.
//
// The fleet figure is read live rather than copied into the pool when it is
// created, so changing it moves every pool that never said otherwise on the
// next pass -- and saving a pool never freezes today's value into it. A fleet
// minimum at or above a pool's typed standard size means nothing for that pool
// (the same rule the wizard's opening value follows), and is ignored there. On
// an automatic field it applies as-is: below a host's slot share it is how far
// a runner may be reduced, and above it the scheduler gives each runner the
// minimum (scheduler.MinimumSlot).
func EffectiveMinimum(r store.Resources, fleet config.Runners) (cpus float64, memoryMB int64) {
	cpus, memoryMB = r.MinCPUs, r.MinMemoryMB
	if cpus <= 0 && fleet.MinimumCPUs > 0 && (r.CPUs <= 0 || fleet.MinimumCPUs < r.CPUs) {
		cpus = fleet.MinimumCPUs
	}
	if memoryMB <= 0 && fleet.MinimumMemoryMB > 0 && (r.MemoryMB <= 0 || fleet.MinimumMemoryMB < r.MemoryMB) {
		memoryMB = fleet.MinimumMemoryMB
	}
	return cpus, memoryMB
}

// fleetStandard is the size of one runner of a pool that takes its size from the
// host, on a host whose profile names none: the fleet's default runner size, or,
// for a pool the controller keeps for a size class, that class's runner, so that
// a runner on a large host is a large runner and not the fleet's default one.
// It is the one place the two are told apart, because the scheduler sizes by it
// and the pages that say what a runner will be must say the same figure.
func fleetStandard(p *store.Pool, fleet config.Runners) (cpus float64, memoryMB int64) {
	cpus, memoryMB = fleet.DefaultRunnerSize()
	if _, class, ok := store.ParseAutoKey(p.AutoKey); ok {
		if c, m := fleet.ClassRunnerSize(string(class)); c > 0 || m > 0 {
			cpus, memoryMB = c, m
		}
	}
	return cpus, memoryMB
}

// sizingPool returns p as the fleet sizes it: a copy with the inherited
// minimum filled in, and -- for a pool that takes its size from the host --
// the fleet's default runner size laid beside it for a host whose profile names
// none. It is p itself when nothing is inherited. It is for the callers that
// decide or report on a runner's size -- scheduling, room, fit, problems -- and
// never for one that stores, exports or renders the pool's own settings: a copy
// written back would turn "the fleet's figure" into a figure of the pool's own,
// and the fleet setting would stop moving it.
//
// The copy also remembers which minimum was the fleet's (Pool.FleetMinimum),
// so that a host left out of a pool for being under it can say whose figure it
// was under.
func sizingPool(p *store.Pool, fleet config.Runners) *store.Pool {
	if p == nil {
		return nil
	}
	cpus, memoryMB := EffectiveMinimum(p.Resources, fleet)
	var standard, inherited store.RunnerSize
	if p.SizeFromProfile {
		standard.CPUs, standard.MemoryMB = fleetStandard(p, fleet)
	}
	if p.Resources.MinCPUs <= 0 && cpus > 0 {
		inherited.CPUs = cpus
	}
	if p.Resources.MinMemoryMB <= 0 && memoryMB > 0 {
		inherited.MemoryMB = memoryMB
	}
	if cpus == p.Resources.MinCPUs && memoryMB == p.Resources.MinMemoryMB &&
		standard == p.FleetStandard && inherited == p.FleetMinimum {
		return p
	}
	cp := *p
	cp.Resources.MinCPUs, cp.Resources.MinMemoryMB = cpus, memoryMB
	cp.FleetStandard, cp.FleetMinimum = standard, inherited
	return &cp
}

// sizingPools is sizingPool over a listing, against the settings in force now.
func (c *Controller) sizingPools(pools []*store.Pool) []*store.Pool {
	fleet := c.cfg().Runners
	out := make([]*store.Pool, len(pools))
	for i, p := range pools {
		out[i] = sizingPool(p, fleet)
	}
	return out
}

package controller

import (
	"testing"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// The rule a pool's minimum in force follows, field by field. A pool's own
// figure always wins; a zero follows the fleet, unless the fleet's figure is
// at or above the pool's typed standard, where a minimum means nothing and
// following it would only have made the pool's size a lie.
func TestAPoolsMinimumFollowsTheFleetWhereItSetsNone(t *testing.T) {
	fleet := config.Runners{MinimumCPUs: 2, MinimumMemoryMB: 4096}
	cases := []struct {
		name       string
		pool       store.Resources
		fleet      config.Runners
		wantCPUs   float64
		wantMemory int64
	}{
		{name: "an automatic pool with none takes the fleet's", fleet: fleet, wantCPUs: 2, wantMemory: 4096},
		{name: "a fixed pool with none takes the fleet's below its standard",
			pool: store.Resources{CPUs: 8, MemoryMB: 16384}, fleet: fleet, wantCPUs: 2, wantMemory: 4096},
		{name: "a pool's own minimum wins",
			pool:  store.Resources{CPUs: 8, MemoryMB: 16384, MinCPUs: 6, MinMemoryMB: 8192},
			fleet: fleet, wantCPUs: 6, wantMemory: 8192},
		{name: "the two fields are independent",
			pool:  store.Resources{MinMemoryMB: 1024},
			fleet: fleet, wantCPUs: 2, wantMemory: 1024},
		{name: "a fleet minimum at the standard is ignored",
			pool: store.Resources{CPUs: 2, MemoryMB: 4096}, fleet: fleet, wantCPUs: 0, wantMemory: 0},
		{name: "a fleet minimum above the standard is ignored",
			pool: store.Resources{CPUs: 1, MemoryMB: 2048}, fleet: fleet, wantCPUs: 0, wantMemory: 0},
		{name: "a fleet with no minimum changes nothing", pool: store.Resources{CPUs: 8}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			cpus, memoryMB := EffectiveMinimum(tc.pool, tc.fleet)
			if cpus != tc.wantCPUs || memoryMB != tc.wantMemory {
				t.Errorf("EffectiveMinimum(%+v) = %v cores, %d MB; want %v, %d",
					tc.pool, cpus, memoryMB, tc.wantCPUs, tc.wantMemory)
			}
		})
	}
}

// The fleet's minimum is read on every pass, not copied into the pool: a pool
// that set none waits for a whole standard while the fleet has none, is placed
// reduced on the pass after an operator sets one, and its stored row still
// says zero -- which is what keeps it following the next change too.
func TestTheFleetMinimumPlacesAPoolReducedOnTheNextPassWithoutRewritingIt(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	pool.MinRunners = 1
	pool.Resources = store.Resources{CPUs: 2, MemoryMB: 32 * 1024}
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	// 16 GB less its reserve is well short of 32 GB and well above 8.
	h.measuredHost("short", 8, 16384, 1, enforcesEverything)

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	h.c.lifecycleCalls.Wait()
	if rs, _ := h.st.ListRunnersForPool(h.ctx, pool.ID); len(rs) != 0 {
		t.Fatalf("placed %d runners with no minimum anywhere; want none", len(rs))
	}

	h.c.UpdateConfig(func(c *config.Config) { c.Runners.MinimumMemoryMB = 8 * 1024 })
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	h.c.lifecycleCalls.Wait()
	r := h.onlyRunner()
	if r.AllocationSource != store.AllocationReduced {
		t.Fatalf("allocation source = %q, want %q", r.AllocationSource, store.AllocationReduced)
	}
	if r.AllocatedMemoryMB >= 32*1024 || r.AllocatedMemoryMB < 8*1024 {
		t.Errorf("memory = %d MB, want between the fleet's 8 GB minimum and the 32 GB standard", r.AllocatedMemoryMB)
	}
	stored, err := h.st.GetPool(h.ctx, pool.ID)
	if err != nil {
		t.Fatalf("GetPool: %v", err)
	}
	if stored.Resources.MinCPUs != 0 || stored.Resources.MinMemoryMB != 0 {
		t.Errorf("stored minimum = %+v; the fleet's figure was frozen into the pool", stored.Resources)
	}
}

// A minimum typed on the pool is the operator's answer for that pool, and a
// fleet figure must not lower it: here the pool's own 24 GB is more than the
// short host can spare, so it stays queued even though the fleet would take 8.
func TestAPoolsOwnMinimumOverridesTheFleets(t *testing.T) {
	h := newHarness(t)
	h.c.UpdateConfig(func(c *config.Config) { c.Runners.MinimumMemoryMB = 8 * 1024 })
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	pool.MinRunners = 1
	pool.Resources = store.Resources{CPUs: 2, MemoryMB: 32 * 1024, MinMemoryMB: 24 * 1024}
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	h.measuredHost("short", 8, 16384, 1, enforcesEverything)

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	h.c.lifecycleCalls.Wait()
	if rs, _ := h.st.ListRunnersForPool(h.ctx, pool.ID); len(rs) != 0 {
		t.Fatalf("placed %d runners below the pool's own 24 GB minimum; want none", len(rs))
	}
}

// A fleet minimum at or above a fixed pool's standard is not a minimum for that
// pool, so it must not make the pool reducible -- or the pool page would offer
// "lower this pool's minimum" for a figure nobody set on it.
func TestAFleetMinimumAtAPoolsStandardIsIgnored(t *testing.T) {
	h := newHarness(t)
	h.c.UpdateConfig(func(c *config.Config) { c.Runners.MinimumMemoryMB = 32 * 1024 })
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	pool.MinRunners = 1
	pool.Resources = store.Resources{CPUs: 2, MemoryMB: 32 * 1024}
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	if sizingPool(pool, h.c.cfg().Runners).Resources.Reducible() {
		t.Fatal("the pool is reducible by a fleet minimum equal to its own standard")
	}
	h.measuredHost("short", 8, 16384, 1, enforcesEverything)
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	h.c.lifecycleCalls.Wait()
	if rs, _ := h.st.ListRunnersForPool(h.ctx, pool.ID); len(rs) != 0 {
		t.Fatalf("placed %d runners on a host short of the standard; want none", len(rs))
	}
}

package controller

import (
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/optimisation"
	"github.com/eyupio/zoomies/internal/prrepair"
	"github.com/eyupio/zoomies/internal/store"
)

func optimisationApprovalFixture(t *testing.T) (*harness, string, string, optimisation.Source, optimisation.Timing, optimisation.HistoryReview, *store.AuditEvent, *RetainedOptimisationPreview) {
	t.Helper()
	h := newHarness(t)
	inst := h.installationOn("acme/repo", store.TargetRepo)
	file := prrepair.File{Path: ".github/workflows/private.yml", Mode: "100644", Content: "on: push\njobs:\n  private:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@" + strings.Repeat("b", 40) + "\n        with:\n          fetch-depth: 0\n"}
	source := optimisation.Source{HeadSHA: strings.Repeat("a", 40), File: file}
	sum := sha256.Sum256([]byte(file.Content))
	digest := hex.EncodeToString(sum[:])
	ms, needs := int64(4200), false
	timing := optimisation.Timing{EvidenceID: "fixture", HeadSHA: source.HeadSHA, SourceSHA256: digest, RunID: "10", Attempt: 2, JobIndex: 0, StepIndex: 0, Outcome: "success", CheckoutMS: &ms}
	history := optimisation.HistoryReview{HeadSHA: source.HeadSHA, SourceSHA256: digest, Scope: "repository_and_downstream_consumers", NeedsHistory: &needs}
	actor := &store.AuditEvent{ActorID: "usr_reviewer", ActorKind: "user", ActorName: "reviewer"}
	saved, err := h.c.RetainOptimisationPreview(h.ctx, actor, inst.ID, "acme/repo", source, timing, history, optimisation.Policy{SourceAllowed: true, WorkflowEditsAllowed: true})
	if err != nil {
		t.Fatal(err)
	}
	return h, inst.ID, "acme/repo", source, timing, history, actor, saved
}

func TestOptimisationApprovalRecordsTheReviewerAndApproverAndDoesNotPublish(t *testing.T) {
	h, installation, repo, source, _, _, _, saved := optimisationApprovalFixture(t)
	approver := &store.AuditEvent{ActorID: "usr_approver", ActorKind: "user", ActorName: "approver"}
	approved, err := h.c.ApproveOptimisationPreview(h.ctx, approver, installation, repo, saved.ID, source.HeadSHA, saved.Preview.SourceSHA256)
	if err != nil {
		t.Fatal(err)
	}
	if approved.Approval == nil || approved.Approval.ApprovedBy != "usr_approver" || approved.ReviewedBy != "usr_reviewer" || approved.Approval.HeadSHA != source.HeadSHA || approved.Approval.SourceSHA256 != saved.Preview.SourceSHA256 || approved.Approval.PreviewSHA256 != saved.SHA256 {
		t.Fatalf("approval does not record both people and the exact binding: %+v", approved)
	}
	if approved.Currentness != "not_checked" || approved.Preview.Verification != "inconclusive" || approved.Preview.State != "preview_ready" {
		t.Fatal("approval promoted currentness, verification or the preview state")
	}
	replayed, err := h.c.ReplayOptimisationPreview(h.ctx, installation, repo, saved.ID)
	if err != nil || replayed.Approval == nil || replayed.Approval.ApprovedBy != "usr_approver" || !replayed.Approval.ApprovedAt.Equal(approved.Approval.ApprovedAt) {
		t.Fatalf("replay lost the approval: %+v, %v", replayed, err)
	}
	for action, want := range map[string]int{"optimisation.preview_retained": 1, "optimisation.preview_approved": 1} {
		_, total, err := h.st.ListAudit(h.ctx, store.AuditFilter{Actions: []string{action}}, store.Page{Limit: 10})
		if err != nil || total != want {
			t.Fatalf("%s audit total=%d err=%v", action, total, err)
		}
	}
}

func TestOptimisationApprovalRefusesAMovedBindingAndKeepsOneAct(t *testing.T) {
	h, installation, repo, source, _, _, _, saved := optimisationApprovalFixture(t)
	actor := &store.AuditEvent{ActorID: "usr_approver", ActorKind: "user"}
	for _, tc := range []struct {
		name string
		head string
		src  string
	}{
		{"head", strings.Repeat("c", 40), saved.Preview.SourceSHA256},
		{"source", source.HeadSHA, strings.Repeat("d", 64)},
		{"malformed", "not-a-commit", saved.Preview.SourceSHA256},
	} {
		if _, err := h.c.ApproveOptimisationPreview(h.ctx, actor, installation, repo, saved.ID, tc.head, tc.src); !errors.Is(err, ErrOptimisationApproval) {
			t.Fatalf("%s: %v", tc.name, err)
		}
	}
	if _, err := h.c.ApproveOptimisationPreview(h.ctx, nil, installation, repo, saved.ID, source.HeadSHA, saved.Preview.SourceSHA256); !errors.Is(err, ErrOptimisationApproval) {
		t.Fatalf("anonymous approval: %v", err)
	}
	_, total, err := h.st.ListAudit(h.ctx, store.AuditFilter{Actions: []string{"optimisation.preview_approved"}}, store.Page{Limit: 10})
	if err != nil || total != 0 {
		t.Fatalf("a refused approval wrote an audit row: %d, %v", total, err)
	}
	first, err := h.c.ApproveOptimisationPreview(h.ctx, actor, installation, repo, saved.ID, source.HeadSHA, saved.Preview.SourceSHA256)
	if err != nil {
		t.Fatal(err)
	}
	again, err := h.c.ApproveOptimisationPreview(h.ctx, actor, installation, repo, saved.ID, source.HeadSHA, saved.Preview.SourceSHA256)
	if err != nil || again.Approval == nil || !again.Approval.ApprovedAt.Equal(first.Approval.ApprovedAt) {
		t.Fatalf("repeated approval did not return the first act: %+v, %v", again, err)
	}
	_, total, err = h.st.ListAudit(h.ctx, store.AuditFilter{Actions: []string{"optimisation.preview_approved"}}, store.Page{Limit: 10})
	if err != nil || total != 1 {
		t.Fatalf("a repeated approval wrote a second audit row: %d, %v", total, err)
	}
}

func TestOptimisationApprovalExpiresWithThePreviewAndStaysScoped(t *testing.T) {
	now := time.Date(2026, 10, 23, 9, 0, 0, 0, time.UTC)
	h := newHarnessAt(t, func() time.Time { return now })
	inst := h.installationOn("acme/repo", store.TargetRepo)
	file := prrepair.File{Path: ".github/workflows/private.yml", Mode: "100644", Content: "on: push\njobs:\n  private:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@" + strings.Repeat("b", 40) + "\n        with:\n          fetch-depth: 0\n"}
	source := optimisation.Source{HeadSHA: strings.Repeat("a", 40), File: file}
	sum := sha256.Sum256([]byte(file.Content))
	digest := hex.EncodeToString(sum[:])
	ms, needs := int64(4200), false
	timing := optimisation.Timing{EvidenceID: "fixture", HeadSHA: source.HeadSHA, SourceSHA256: digest, RunID: "10", Attempt: 2, JobIndex: 0, StepIndex: 0, Outcome: "success", CheckoutMS: &ms}
	history := optimisation.HistoryReview{HeadSHA: source.HeadSHA, SourceSHA256: digest, Scope: "repository_and_downstream_consumers", NeedsHistory: &needs}
	actor := &store.AuditEvent{ActorID: "usr_reviewer", ActorKind: "user"}
	saved, err := h.c.RetainOptimisationPreview(h.ctx, actor, inst.ID, "acme/repo", source, timing, history, optimisation.Policy{SourceAllowed: true, WorkflowEditsAllowed: true})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := h.c.ApproveOptimisationPreview(h.ctx, actor, "other", "acme/repo", saved.ID, source.HeadSHA, saved.Preview.SourceSHA256); !errors.Is(err, store.ErrNotFound) {
		t.Fatalf("cross-installation approval: %v", err)
	}
	if _, err := h.c.ApproveOptimisationPreview(h.ctx, actor, inst.ID, "acme/other", saved.ID, source.HeadSHA, saved.Preview.SourceSHA256); !errors.Is(err, store.ErrNotFound) {
		t.Fatalf("cross-repository approval: %v", err)
	}
	now = now.Add(store.OptimisationPreviewRetention)
	if _, err := h.c.ApproveOptimisationPreview(h.ctx, actor, inst.ID, "acme/repo", saved.ID, source.HeadSHA, saved.Preview.SourceSHA256); !errors.Is(err, store.ErrNotFound) {
		t.Fatalf("expired approval: %v", err)
	}
}

package controller

import (
	"context"
	"errors"
	"strconv"
	"time"

	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/optimisation"
	"github.com/eyupio/zoomies/internal/store"
)

var (
	ErrOptimisationCache         = errors.New("cache preview evidence is unavailable, inconsistent or unsupported")
	ErrOptimisationCacheApproval = errors.New("the cache preview's head and source digest do not match the retained preview")
)

// CacheInspection is what an operator is shown before keeping a cache preview.
// It carries the source identity, the retained setup evidence and the computed
// preview, but never the full workflow file in a transport.
type CacheInspection struct {
	Source   github.SetupCacheSource
	Evidence optimisation.SetupEvidence
	Samples  []optimisation.SetupSample
	Preview  optimisation.CachePreview
}

// InspectCachePreview binds one selected fleet job and one pinned GitHub
// attempt to the pure cache preview. The source read is the only GitHub work;
// repeated setup cost comes from the fleet's retained job history. Nothing is
// retained here.
func (c *Controller) InspectCachePreview(ctx context.Context, installation, repo string, selection github.SetupCacheSelection, githubJobID int64) (*optimisation.CachePreview, error) {
	inspection, err := c.inspectCachePreview(ctx, installation, repo, selection, githubJobID)
	if err != nil {
		return nil, err
	}
	return &inspection.Preview, nil
}

func (c *Controller) inspectCachePreview(ctx context.Context, installation, repo string, selection github.SetupCacheSelection, githubJobID int64) (*CacheInspection, error) {
	if installation == "" || repo == "" || githubJobID <= 0 || !github.ValidSetupCacheSelection(selection) {
		return nil, ErrOptimisationCache
	}
	inst, err := c.st.GetInstallation(ctx, installation)
	if err != nil {
		return nil, err
	}
	owner, name, kind := github.SplitTarget(repo)
	if kind != store.TargetRepo || name == "" || !(inst.TargetType == store.TargetRepo && inst.Target == repo || inst.TargetType == store.TargetOrg && inst.Target == owner) {
		return nil, ErrOptimisationCache
	}
	policy, err := c.OptimisationPolicy(ctx)
	if err != nil {
		return nil, err
	}
	if !policy.SourceAllowed || !policy.WorkflowEditsAllowed {
		return nil, ErrOptimisationPolicy
	}
	if c.githubHeld(installation, c.Now()) {
		return nil, github.ErrRateLimited
	}
	client, err := c.ClientFor(ctx, installation)
	if err != nil {
		return nil, err
	}
	reader, ok := client.(github.SetupCacheSourceReader)
	if !ok {
		return nil, ErrOptimisationCache
	}
	ctx, cancel := context.WithTimeout(ctx, 20*time.Second)
	defer cancel()
	release, err := c.admitPRDelay(installation)
	if err != nil {
		return nil, err
	}
	defer release()
	quota, err := client.RateLimit(ctx)
	if err != nil {
		c.holdIfRateLimited(installation, err, c.Now(), "reading cache preview quota")
		return nil, err
	}
	if quota == nil || quota.Limit <= 0 || quota.Remaining < 0 || quota.Remaining > quota.Limit || quota.Remaining-github.SetupCacheEvidenceMaximumRequests < quota.Limit/2+quota.Limit%2 {
		retry := time.Minute
		if quota != nil && quota.ResetAt.After(c.Now()) {
			retry = quota.ResetAt.Sub(c.Now())
		}
		return nil, &PRDelayAdmissionError{RetryAfter: retry}
	}
	if c.githubHeld(installation, c.Now()) {
		return nil, github.ErrRateLimited
	}
	source, err := reader.ReadSetupCacheSource(ctx, repo, selection)
	if err != nil {
		c.holdIfRateLimited(installation, err, c.Now(), "reading cache preview source")
		return nil, err
	}
	if !github.ValidSetupCacheSource(source, repo, selection) {
		return nil, ErrOptimisationCache
	}
	job, err := c.st.GetJobByGitHubID(ctx, githubJobID)
	if err != nil {
		return nil, err
	}
	if job.Repo != repo || job.InstallationID != installation || job.GitHubRunID != selection.RunID || job.RunAttempt != selection.Attempt || job.HeadSHA != source.HeadSHA || job.Workflow == "" || job.JobName != source.JobName || job.State != store.JobCompleted || job.Conclusion != "success" {
		return nil, ErrOptimisationCache
	}
	var setup *store.JobStep
	for i := range job.Steps {
		step := &job.Steps[i]
		if step.Name != source.StepName {
			continue
		}
		if setup != nil {
			return nil, ErrOptimisationCache
		}
		setup = step
	}
	if setup == nil || setup.Number <= 0 || setup.StartedAt == nil || setup.CompletedAt == nil || !setup.CompletedAt.After(*setup.StartedAt) {
		return nil, ErrOptimisationCache
	}
	samples, err := c.st.RecentSetupStepSamples(ctx, repo, job.Workflow, source.JobName, source.StepName, c.Now().Add(-90*24*time.Hour), 100)
	if err != nil {
		return nil, err
	}
	evidenceSamples := make([]optimisation.SetupSample, 0, len(samples))
	selectedFound := false
	for _, sample := range samples {
		if sample.RunAttempt < 1 || sample.SetupMS <= 0 {
			continue
		}
		if sample.JobID == job.ID {
			selectedFound = true
		}
		evidenceSamples = append(evidenceSamples, optimisation.SetupSample{
			JobID: sample.JobID, RunID: strconv.FormatInt(sample.GitHubRunID, 10), Attempt: sample.RunAttempt,
			StepNumber: sample.StepNumber, SetupMS: sample.SetupMS,
		})
	}
	if !selectedFound {
		return nil, ErrOptimisationCache
	}
	evidence, err := optimisation.SetupEvidenceFromSamples(source.HeadSHA, source.WorkflowSHA256, source.LockfileSHA256, evidenceSamples)
	if err != nil {
		return nil, ErrOptimisationCache
	}
	preview, err := optimisation.PreviewCache(optimisation.CacheSource{HeadSHA: source.HeadSHA, Workflow: source.Workflow, Lockfile: source.Lockfile}, evidence, policy)
	if err != nil {
		return nil, ErrOptimisationCache
	}
	return &CacheInspection{Source: *source, Evidence: evidence, Samples: evidenceSamples, Preview: preview}, nil
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

// PublishCachePreview opens one draft pull request for an approved retained
// cache preview. It re-reads the selected job, its branch, the workflow and the
// lockfile, rechecks the live settings and the approval, and refuses any change.
// It never merges and never force-pushes; a retry after an uncertain response
// reconciles the branch and pull request the earlier attempt left behind.
func (c *Controller) PublishCachePreview(ctx context.Context, actor *store.AuditEvent, installation, repo, id, headSHA, sourceSHA256 string, check OptimisationPolicyCheck) (*RetainedCachePreview, error) {
	if actor == nil || actor.ActorID == "" || installation == "" || repo == "" || id == "" || check == nil || !knownHash(headSHA, 40) || !knownHash(sourceSHA256, 64) {
		return nil, ErrOptimisationPublish
	}
	current, err := c.ReplayCachePreview(ctx, installation, repo, id)
	if err != nil {
		return nil, err
	}
	if current.Preview.HeadSHA != headSHA || current.Preview.SourceSHA256 != sourceSHA256 {
		return nil, ErrOptimisationCacheApproval
	}
	if current.Approval == nil {
		return nil, ErrOptimisationNotApproved
	}
	if current.Approval.HeadSHA != headSHA || current.Approval.SourceSHA256 != sourceSHA256 {
		return nil, ErrOptimisationCacheApproval
	}
	if current.Publication != nil {
		return current, nil
	}
	if current.Provenance == nil {
		return nil, fmt.Errorf("%w: this preview predates branch recording; make a new cache preview before publishing", ErrOptimisationPublish)
	}
	policy, err := check(ctx)
	if err != nil {
		return nil, err
	}
	if !policy.SourceAllowed || !policy.WorkflowEditsAllowed || !policy.PublishAllowed {
		return nil, ErrOptimisationPublishPolicy
	}
	ctx, cancel := context.WithTimeout(ctx, time.Minute)
	defer cancel()
	fresh, err := c.inspectCachePreview(ctx, installation, repo, current.Provenance.Selection, current.Provenance.GitHubJobID)
	if err != nil {
		return nil, err
	}
	afterPolicy, err := check(ctx)
	if err != nil {
		return nil, err
	}
	if !afterPolicy.PublishAllowed {
		return nil, ErrOptimisationPublishPolicy
	}
	if fresh.Source.HeadSHA != current.Preview.HeadSHA || fresh.Source.WorkflowSHA256 != current.Preview.SourceSHA256 || fresh.Source.LockfileSHA256 != current.Preview.LockfileSHA256 || fresh.Source.HeadBranch != current.Provenance.HeadBranch {
		return nil, fmt.Errorf("%w: the run or its branch changed since the cache preview; preview it again", ErrOptimisationPublish)
	}
	if fresh.Preview.Edit.Path != current.Preview.Edit.Path || fresh.Preview.File.Mode != current.Preview.File.Mode || fresh.Preview.File.Content != current.Preview.File.Content || fresh.Preview.AfterSHA256 != current.Preview.AfterSHA256 || fresh.Preview.PackageManager != current.Preview.PackageManager || fresh.Preview.JobName != current.Preview.JobName || fresh.Preview.StepName != current.Preview.StepName || fresh.Preview.Line != current.Preview.Line {
		return nil, fmt.Errorf("%w: the setup block no longer matches the cache preview; preview it again", ErrOptimisationPublish)
	}
	// Re-read the approval and retained record after the source read: a preview
	// that expired or was evicted meanwhile must not be published, and another
	// request may already have opened its draft.
	latest, err := c.ReplayCachePreview(ctx, installation, repo, id)
	if err != nil {
		return nil, err
	}
	if latest.Preview.HeadSHA != headSHA || latest.Preview.SourceSHA256 != sourceSHA256 || latest.SHA256 != current.SHA256 {
		return nil, ErrOptimisationCacheApproval
	}
	if latest.Approval == nil || latest.Approval.HeadSHA != headSHA || latest.Approval.SourceSHA256 != sourceSHA256 {
		return nil, ErrOptimisationNotApproved
	}
	if latest.Publication != nil {
		return latest, nil
	}
	if latest.Provenance == nil || latest.Provenance.HeadBranch == "" {
		return nil, fmt.Errorf("%w: this preview predates branch recording; make a new cache preview before publishing", ErrOptimisationPublish)
	}
	client, err := c.ClientFor(ctx, installation)
	if err != nil {
		return nil, err
	}
	publisher, ok := client.(github.OptimisationPublisher)
	if !ok {
		return nil, fmt.Errorf("%w: this GitHub client cannot open draft pull requests", ErrOptimisationPublish)
	}
	info, err := client.Probe(ctx)
	if err != nil {
		if errors.Is(err, github.ErrForbidden) {
			return nil, fmt.Errorf("%w: %s", ErrOptimisationPublishPermission, github.OptimisationPublishPermissionHint)
		}
		return nil, fmt.Errorf("%w: %v", ErrOptimisationPublish, err)
	}
	if info == nil {
		return nil, fmt.Errorf("%w: GitHub did not report the App's permissions", ErrOptimisationPublish)
	}
	if missing := info.MissingForMigration(); len(missing) > 0 {
		return nil, fmt.Errorf("%w: %s; %s", ErrOptimisationPublishPermission, github.OptimisationPublishPermissionHint, strings.Join(missing, ", "))
	}
	branch := "zoomies/cache-" + id
	title := "Cache Node dependencies in CI"
	body := fmt.Sprintf("This draft was opened from approved Zoomies cache preview `%s` at commit `%s`.\n\n"+
		"It adds the setup action's own package cache to one `actions/setup-node` step, using the root lockfile the preview named. "+
		"Zoomies measured no saving: the setup time is descriptive, verification is inconclusive, and passing CI alone cannot establish improvement. "+
		"The cache is shared with whoever can write this repository's cache. Zoomies will not merge this pull request; review the diff and let the repository's own checks decide.\n\n"+
		"<!-- zoomies-cache-optimisation:%s -->\n", id, latest.Preview.HeadSHA, id)
	commitMessage := "Cache Node dependencies in CI\n\nZoomies cache preview " + id
	pr, err := publisher.PublishOptimisation(ctx, github.OptimisationPublishRequest{
		Repo: repo, Base: latest.Provenance.HeadBranch, BaseCommit: latest.Preview.HeadSHA, Head: branch,
		Title: title, Body: body, CommitMessage: commitMessage, PreviewID: id,
		Path: latest.Preview.Edit.Path, Mode: latest.Preview.File.Mode, Content: latest.Preview.File.Content,
		SourceSHA256: latest.Preview.SourceSHA256,
	})
	if err != nil {
		if errors.Is(err, github.ErrForbidden) {
			return nil, fmt.Errorf("%w: %s", ErrOptimisationPublishPermission, github.OptimisationPublishPermissionHint)
		}
		return nil, fmt.Errorf("%w: %w", ErrOptimisationPublish, err)
	}
	if pr == nil || pr.Number <= 0 || pr.HTMLURL == "" || pr.Branch != branch {
		return nil, fmt.Errorf("%w: GitHub did not return a usable draft pull request", ErrOptimisationPublish)
	}
	record := &store.OptimisationCachePublication{
		PreviewID: id, InstallationID: installation, Repository: repo, PublishedBy: actor.ActorID,
		Branch: pr.Branch, BaseBranch: latest.Provenance.HeadBranch, BaseSHA: latest.Preview.HeadSHA, HeadSHA: latest.Preview.HeadSHA,
		SourceSHA256: latest.Preview.SourceSHA256, PreviewSHA256: latest.SHA256,
		PullNumber: pr.Number, PullURL: pr.HTMLURL,
	}
	if err := c.st.PutOptimisationCachePublication(ctx, record, actor); err != nil {
		c.log.Error("recording a cache publication", "error", err, "preview", id, "pull_request", pr.Number)
		return nil, fmt.Errorf("%w: the draft pull request #%d was opened, but its record could not be saved; press publish again to reconcile it", ErrOptimisationPublish, pr.Number)
	}
	latest.Publication = &RetainedCachePublication{
		PublishedBy: record.PublishedBy, PublishedAt: record.CreatedAt, Branch: record.Branch, BaseBranch: record.BaseBranch,
		BaseSHA: record.BaseSHA, HeadSHA: record.HeadSHA, SourceSHA256: record.SourceSHA256, PreviewSHA256: record.PreviewSHA256,
		PullNumber: record.PullNumber, PullURL: record.PullURL,
	}
	return latest, nil
}

package controller

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"io"
	"time"

	"github.com/eyupio/zoomies/internal/aicontext"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/optimisation"
	"github.com/eyupio/zoomies/internal/prrepair"
	"github.com/eyupio/zoomies/internal/store"
)

type optimisationCacheRetainedSource struct {
	HeadSHA string `json:"head_sha"`
	Path    string `json:"path"`
	Mode    string `json:"mode"`
	Content string `json:"content"`
}

type optimisationCacheRetainedLockfile struct {
	Path   string `json:"path"`
	Mode   string `json:"mode"`
	SHA256 string `json:"sha256"`
}

type optimisationCacheRetainedEnvelope struct {
	Version        string                               `json:"version"`
	ID             string                               `json:"id"`
	InstallationID string                               `json:"installation_id"`
	Repository     string                               `json:"repository"`
	ReviewedBy     string                               `json:"reviewed_by"`
	ModelFunding   string                               `json:"model_funding"`
	Provenance     *optimisationCacheRetainedProvenance `json:"provenance,omitempty"`
	Source         optimisationCacheRetainedSource      `json:"source"`
	Lockfile       optimisationCacheRetainedLockfile    `json:"lockfile"`
	Evidence       optimisation.SetupEvidence           `json:"evidence"`
	Samples        []optimisation.SetupSample           `json:"samples"`
	Preview        optimisation.CachePreview            `json:"preview"`
}

type optimisationCacheRetainedProvenance struct {
	SelectionRunID   int64  `json:"selection_run_id"`
	SelectionAttempt int    `json:"selection_attempt"`
	GitHubJobID      int64  `json:"github_job_id"`
	HeadBranch       string `json:"head_branch"`
}

// RetainedCachePreview is a kept cache preview. The full after source stays in
// the private envelope; a transport renders the edit, metadata and evidence
// summary only.
type RetainedCachePreview struct {
	ID             string
	InstallationID string
	Repository     string
	ReviewedBy     string
	SHA256         string
	CreatedAt      time.Time
	Currentness    string
	Preview        optimisation.CachePreview
	Approval       *RetainedCacheApproval
	Publication    *RetainedCachePublication
	Provenance     *CacheProvenance
}

// CacheProvenance is the selected fleet job and branch a cache preview was
// bound to. Previews retained before this was recorded have no provenance and
// cannot be published, because their branch cannot be rechecked.
type CacheProvenance struct {
	Selection   github.SetupCacheSelection
	GitHubJobID int64
	HeadBranch  string
}

// RetainedCacheApproval is one attributed decision about the exact retained
// cache preview. It is not a publication and expires with the preview.
// RetainedCachePublication is the one draft pull request opened for an
// approved cache preview. It is not a merge and does not claim a saving.
type RetainedCachePublication struct {
	PublishedBy   string
	PublishedAt   time.Time
	Branch        string
	BaseBranch    string
	BaseSHA       string
	HeadSHA       string
	SourceSHA256  string
	PreviewSHA256 string
	PullNumber    int
	PullURL       string
}

type RetainedCacheApproval struct {
	ApprovedBy    string
	ApprovedAt    time.Time
	HeadSHA       string
	SourceSHA256  string
	PreviewSHA256 string
}

// CaptureCachePreview re-reads the source and setup history, requires the same
// head, workflow digest and lockfile digest the operator reviewed, and keeps an
// immutable private preview for fourteen days.
func (c *Controller) CaptureCachePreview(ctx context.Context, actor *store.AuditEvent, installation, repo string, selection github.SetupCacheSelection, githubJobID int64, headSHA, sourceSHA256, lockfileSHA256 string) (*RetainedCachePreview, error) {
	if actor == nil || actor.ActorID == "" || !knownHash(headSHA, 40) || !knownHash(sourceSHA256, 64) || !knownHash(lockfileSHA256, 64) {
		return nil, ErrOptimisationCache
	}
	inspection, err := c.inspectCachePreview(ctx, installation, repo, selection, githubJobID)
	if err != nil {
		return nil, err
	}
	if inspection.Source.HeadSHA != headSHA || inspection.Source.WorkflowSHA256 != sourceSHA256 || inspection.Source.LockfileSHA256 != lockfileSHA256 {
		return nil, ErrOptimisationCache
	}
	envelope := optimisationCacheRetainedEnvelope{
		Version: store.OptimisationCachePreviewVersion, ID: store.NewID(store.PrefixOptimisationCachePreview),
		InstallationID: installation, Repository: repo, ReviewedBy: actor.ActorID, ModelFunding: "no_model_call",
		Provenance: &optimisationCacheRetainedProvenance{SelectionRunID: selection.RunID, SelectionAttempt: selection.Attempt, GitHubJobID: githubJobID, HeadBranch: inspection.Source.HeadBranch},
		Source:     optimisationCacheRetainedSource{HeadSHA: inspection.Source.HeadSHA, Path: inspection.Source.Workflow.Path, Mode: inspection.Source.Workflow.Mode, Content: inspection.Source.Workflow.Content},
		Lockfile:   optimisationCacheRetainedLockfile{Path: inspection.Source.Lockfile.Path, Mode: inspection.Source.Lockfile.Mode, SHA256: inspection.Source.LockfileSHA256},
		Evidence:   inspection.Evidence, Samples: inspection.Samples, Preview: inspection.Preview,
	}
	payload, err := json.Marshal(envelope)
	if err != nil {
		return nil, err
	}
	if len(payload) > store.MaxOptimisationCachePreviewBytes {
		return nil, ErrOptimisationCache
	}
	row := &store.OptimisationCachePreview{ID: envelope.ID, InstallationID: installation, Repository: repo, InitiatingUser: actor.ActorID, Version: envelope.Version, Payload: payload}
	if err := c.st.PutOptimisationCachePreview(ctx, row, actor); err != nil {
		return nil, err
	}
	return retainedCacheView(row, inspection.Preview), nil
}

// ReplayCachePreview validates historical calculation, not the current head or
// policy. It never reads replacement source.
func (c *Controller) ReplayCachePreview(ctx context.Context, installation, repo, id string) (*RetainedCachePreview, error) {
	row, err := c.st.GetOptimisationCachePreview(ctx, installation, repo, id)
	if err != nil {
		return nil, err
	}
	var e optimisationCacheRetainedEnvelope
	dec := json.NewDecoder(bytes.NewReader(row.Payload))
	dec.DisallowUnknownFields()
	if dec.Decode(&e) != nil || dec.Decode(new(any)) != io.EOF || row.Version != store.OptimisationCachePreviewVersion || e.Version != row.Version || e.ID != row.ID || e.InstallationID != row.InstallationID || e.Repository != row.Repository || e.ReviewedBy != row.InitiatingUser || e.ModelFunding != "no_model_call" {
		return nil, ErrOptimisationCache
	}
	if p := e.Provenance; p != nil && (p.SelectionRunID <= 0 || p.SelectionAttempt <= 0 || p.GitHubJobID <= 0 || !aicontext.ValidBranch(p.HeadBranch)) {
		return nil, ErrOptimisationCache
	}
	evidence, err := optimisation.SetupEvidenceFromSamples(e.Source.HeadSHA, hashString(e.Source.Content), e.Lockfile.SHA256, e.Samples)
	if err != nil {
		return nil, ErrOptimisationCache
	}
	oldEvidence, _ := json.Marshal(e.Evidence)
	newEvidence, _ := json.Marshal(evidence)
	if !bytes.Equal(oldEvidence, newEvidence) {
		return nil, ErrOptimisationCache
	}
	source := optimisation.CacheSource{
		HeadSHA:        e.Source.HeadSHA,
		Workflow:       prrepair.File{Path: e.Source.Path, Mode: e.Source.Mode, Content: e.Source.Content},
		Lockfile:       prrepair.File{Path: e.Lockfile.Path, Mode: e.Lockfile.Mode},
		LockfileSHA256: e.Lockfile.SHA256,
	}
	preview, err := optimisation.PreviewCache(source, evidence, optimisation.Policy{SourceAllowed: true, WorkflowEditsAllowed: true})
	if err != nil {
		return nil, ErrOptimisationCache
	}
	oldPreview, _ := json.Marshal(e.Preview)
	newPreview, _ := json.Marshal(preview)
	if !bytes.Equal(oldPreview, newPreview) {
		return nil, ErrOptimisationCache
	}
	view := retainedCacheView(row, preview)
	if p := e.Provenance; p != nil {
		view.Provenance = &CacheProvenance{Selection: github.SetupCacheSelection{RunID: p.SelectionRunID, Attempt: p.SelectionAttempt}, GitHubJobID: p.GitHubJobID, HeadBranch: p.HeadBranch}
	}
	return view, nil
}

func retainedCacheView(row *store.OptimisationCachePreview, preview optimisation.CachePreview) *RetainedCachePreview {
	v := &RetainedCachePreview{ID: row.ID, InstallationID: row.InstallationID, Repository: row.Repository, ReviewedBy: row.InitiatingUser, SHA256: row.SHA256, CreatedAt: row.CreatedAt, Currentness: "not_checked", Preview: preview}
	if a := row.Approval; a != nil {
		v.Approval = &RetainedCacheApproval{ApprovedBy: a.ApprovedBy, ApprovedAt: a.CreatedAt, HeadSHA: a.HeadSHA, SourceSHA256: a.SourceSHA256, PreviewSHA256: a.PreviewSHA256}
	}
	if p := row.Publication; p != nil {
		v.Publication = &RetainedCachePublication{PublishedBy: p.PublishedBy, PublishedAt: p.CreatedAt, Branch: p.Branch, BaseBranch: p.BaseBranch, BaseSHA: p.BaseSHA, HeadSHA: p.HeadSHA, SourceSHA256: p.SourceSHA256, PreviewSHA256: p.PreviewSHA256, PullNumber: p.PullNumber, PullURL: p.PullURL}
	}
	return v
}

// ApproveCachePreview records an operator's explicit approval of the exact
// retained cache preview they name. It reads no source and calls no GitHub
// reader, so an approval cannot publish, edit a workflow or start a job.
func (c *Controller) ApproveCachePreview(ctx context.Context, actor *store.AuditEvent, installation, repo, id, headSHA, sourceSHA256 string) (*RetainedCachePreview, error) {
	if actor == nil || actor.ActorID == "" || installation == "" || repo == "" || id == "" || !knownHash(headSHA, 40) || !knownHash(sourceSHA256, 64) {
		return nil, ErrOptimisationCacheApproval
	}
	current, err := c.ReplayCachePreview(ctx, installation, repo, id)
	if err != nil {
		return nil, err
	}
	if current.Preview.HeadSHA != headSHA || current.Preview.SourceSHA256 != sourceSHA256 {
		return nil, ErrOptimisationCacheApproval
	}
	approval, err := c.st.ApproveOptimisationCachePreview(ctx, installation, repo, id, headSHA, sourceSHA256, current.SHA256, actor)
	if err != nil {
		return nil, err
	}
	current.Approval = &RetainedCacheApproval{ApprovedBy: approval.ApprovedBy, ApprovedAt: approval.CreatedAt, HeadSHA: approval.HeadSHA, SourceSHA256: approval.SourceSHA256, PreviewSHA256: approval.PreviewSHA256}
	return current, nil
}

func hashString(s string) string {
	sum := sha256.Sum256([]byte(s))
	return hex.EncodeToString(sum[:])
}

