		t.Fatalf("branch changed: %v", err)
	}
	f.evidence.HeadBranch = "main"
	f.evidence.Source.File.Content = strings.Replace(f.evidence.Source.File.Content, "fetch-depth: 0", "fetch-depth: 2", 1)
	if _, err := h.c.PublishOptimisationPreview(h.ctx, actor, inst.ID, inst.Target, saved.ID, saved.Preview.HeadSHA, saved.Preview.SourceSHA256, optimisationPublishCheck(true)); !errors.Is(err, ErrOptimisationPublish) && !errors.Is(err, ErrOptimisationPreview) {
		t.Fatalf("source changed: %v", err)
	}
	if f.publishes != 0 {
		t.Fatal("a moved source opened a draft")
	}
}

func TestPublishOptimisationRefusesAPreviewWithoutABranchAndAMissingPermission(t *testing.T) {
	c, installation, source, timing, history, policy, actor := optimisationRetentionFixture(t)
	saved, err := c.RetainOptimisationPreview(context.Background(), actor, installation, "acme/repo", source, timing, history, policy)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := c.ApproveOptimisationPreview(context.Background(), actor, installation, "acme/repo", saved.ID, source.HeadSHA, saved.Preview.SourceSHA256); err != nil {
		t.Fatal(err)
	}
	if _, err := c.PublishOptimisationPreview(context.Background(), actor, installation, "acme/repo", saved.ID, source.HeadSHA, saved.Preview.SourceSHA256, optimisationPublishCheck(true)); !errors.Is(err, ErrOptimisationPublish) || !strings.Contains(err.Error(), "predates branch recording") {
		t.Fatalf("pre-branch preview: %v", err)
	}

	h, inst, _, sel, review, publisher := checkoutCaptureFixture(t)
	fresh, err := h.c.CaptureOptimisationPreview(h.ctx, publisher, inst.ID, inst.Target, sel, review, optimisationPublishCheck(true))
	if err != nil {
		t.Fatal(err)
	}
	if _, err := h.c.ApproveOptimisationPreview(h.ctx, publisher, inst.ID, inst.Target, fresh.ID, fresh.Preview.HeadSHA, fresh.Preview.SourceSHA256); err != nil {
		t.Fatal(err)
	}
	h.gh.SetPermissions(map[string]string{"contents": "read", "pull_requests": "write", "workflows": "write"})
	if _, err := h.c.PublishOptimisationPreview(h.ctx, publisher, inst.ID, inst.Target, fresh.ID, fresh.Preview.HeadSHA, fresh.Preview.SourceSHA256, optimisationPublishCheck(true)); !errors.Is(err, ErrOptimisationPublish) || !strings.Contains(err.Error(), "Contents") {
		t.Fatalf("missing permission: %v", err)
	}
}

func TestPublishOptimisationDoesNotRecordAFailedGitHubWrite(t *testing.T) {
	h, inst, f, sel, review, actor := checkoutCaptureFixture(t)
	saved, err := h.c.CaptureOptimisationPreview(h.ctx, actor, inst.ID, inst.Target, sel, review, optimisationPublishCheck(true))
	if err != nil {
		t.Fatal(err)
	}
	if _, err := h.c.ApproveOptimisationPreview(h.ctx, actor, inst.ID, inst.Target, saved.ID, saved.Preview.HeadSHA, saved.Preview.SourceSHA256); err != nil {
		t.Fatal(err)
	}
	f.publishErr = github.ErrOptimisationPublishConflict
	if _, err := h.c.PublishOptimisationPreview(h.ctx, actor, inst.ID, inst.Target, saved.ID, saved.Preview.HeadSHA, saved.Preview.SourceSHA256, optimisationPublishCheck(true)); !errors.Is(err, github.ErrOptimisationPublishConflict) {
		t.Fatalf("publisher refusal: %v", err)
	}
	if _, total, err := h.st.ListAudit(h.ctx, store.AuditFilter{Actions: []string{"optimisation.preview_published"}}, store.Page{Limit: 10}); err != nil || total != 0 {
		t.Fatal("a failed write was recorded")
	}
}

package controller

import (
	"context"
	"errors"
	"strconv"
	"time"

	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/optimisation"
	"github.com/eyupio/zoomies/internal/store"
)

var (
	ErrOptimisationReadiness         = errors.New("readiness preview evidence is unavailable, inconsistent or unsupported")
	ErrOptimisationReadinessApproval = errors.New("the readiness preview's head and source digest do not match the retained preview")
)

// ReadinessInspection is what an operator is shown before keeping a readiness
// preview. It carries the source identity, the retained wait evidence and the
// computed preview, but never the full workflow file in a transport.
type ReadinessInspection struct {
	Source   github.ReadinessSource
	Evidence optimisation.ReadinessEvidence
	Samples  []optimisation.SetupSample
	Preview  optimisation.ReadinessPreview
}

// InspectReadinessPreview binds one selected fleet job and one pinned GitHub
// attempt to the pure readiness preview. The source read is the only GitHub
// work; repeated wait cost comes from the fleet's retained job history. It
// reads no lockfile, retains nothing and guesses no condition.
func (c *Controller) InspectReadinessPreview(ctx context.Context, installation, repo string, selection github.SetupCacheSelection, githubJobID int64, condition string) (*optimisation.ReadinessPreview, error) {
	inspection, err := c.inspectReadinessPreview(ctx, installation, repo, selection, githubJobID, condition)
	if err != nil {
		return nil, err
	}
	return &inspection.Preview, nil
}

func (c *Controller) inspectReadinessPreview(ctx context.Context, installation, repo string, selection github.SetupCacheSelection, githubJobID int64, condition string) (*ReadinessInspection, error) {
	if installation == "" || repo == "" || githubJobID <= 0 || !github.ValidSetupCacheSelection(selection) || condition == "" {
		return nil, ErrOptimisationReadiness
	}
	inst, err := c.st.GetInstallation(ctx, installation)
	if err != nil {
		return nil, err
	}
	owner, name, kind := github.SplitTarget(repo)
	if kind != store.TargetRepo || name == "" || !(inst.TargetType == store.TargetRepo && inst.Target == repo || inst.TargetType == store.TargetOrg && inst.Target == owner) {
		return nil, ErrOptimisationReadiness
	}
	policy, err := c.OptimisationPolicy(ctx)
	if err != nil {
		return nil, err
	}
	if !policy.SourceAllowed || !policy.WorkflowEditsAllowed {
		return nil, ErrOptimisationPolicy
	}
	if c.githubHeld(installation, c.Now()) {
		return nil, github.ErrRateLimited
	}
	client, err := c.ClientFor(ctx, installation)
	if err != nil {
		return nil, err
	}
	reader, ok := client.(github.ReadinessSourceReader)
	if !ok {
		return nil, ErrOptimisationReadiness
	}
	ctx, cancel := context.WithTimeout(ctx, 20*time.Second)
	defer cancel()
	release, err := c.admitPRDelay(installation)
	if err != nil {
		return nil, err
	}
	defer release()
	quota, err := client.RateLimit(ctx)
	if err != nil {
		c.holdIfRateLimited(installation, err, c.Now(), "reading readiness preview quota")
		return nil, err
	}
	if quota == nil || quota.Limit <= 0 || quota.Remaining < 0 || quota.Remaining > quota.Limit || quota.Remaining-github.ReadinessEvidenceMaximumRequests < quota.Limit/2+quota.Limit%2 {
		retry := time.Minute
		if quota != nil && quota.ResetAt.After(c.Now()) {
			retry = quota.ResetAt.Sub(c.Now())
		}
		return nil, &PRDelayAdmissionError{RetryAfter: retry}
	}
	if c.githubHeld(installation, c.Now()) {
		return nil, github.ErrRateLimited
	}
	source, err := reader.ReadReadinessSource(ctx, repo, selection)
	if err != nil {
		c.holdIfRateLimited(installation, err, c.Now(), "reading readiness preview source")
		return nil, err
	}
	if !github.ValidReadinessSource(source, repo, selection) {
		return nil, ErrOptimisationReadiness
	}
	job, err := c.st.GetJobByGitHubID(ctx, githubJobID)
	if err != nil {
		return nil, err
	}
	if job.Repo != repo || job.InstallationID != installation || job.GitHubRunID != selection.RunID || job.RunAttempt != selection.Attempt || job.HeadSHA != source.HeadSHA || job.Workflow == "" || job.JobName != source.JobName || job.State != store.JobCompleted || job.Conclusion != "success" {
		return nil, ErrOptimisationReadiness
	}
	var wait *store.JobStep
	for i := range job.Steps {
		step := &job.Steps[i]
		if step.Name != source.StepName {
			continue
		}
		if wait != nil {
			return nil, ErrOptimisationReadiness
		}
		wait = step
	}
	if wait == nil || wait.Number <= 0 || wait.StartedAt == nil || wait.CompletedAt == nil || !wait.CompletedAt.After(*wait.StartedAt) {
		return nil, ErrOptimisationReadiness
	}
	samples, err := c.st.RecentSetupStepSamples(ctx, repo, job.Workflow, source.JobName, source.StepName, c.Now().Add(-90*24*time.Hour), 100)
	if err != nil {
		return nil, err
	}
	evidenceSamples := make([]optimisation.SetupSample, 0, len(samples))
	selectedFound := false
	for _, sample := range samples {
		if sample.RunAttempt < 1 || sample.SetupMS <= 0 {
			continue
		}
		if sample.JobID == job.ID {
			selectedFound = true
		}
		evidenceSamples = append(evidenceSamples, optimisation.SetupSample{
			JobID: sample.JobID, RunID: strconv.FormatInt(sample.GitHubRunID, 10), Attempt: sample.RunAttempt,
			StepNumber: sample.StepNumber, SetupMS: sample.SetupMS,
		})
	}
	if !selectedFound {
		return nil, ErrOptimisationReadiness
	}
	evidence, err := optimisation.ReadinessEvidenceFromSamples(source.HeadSHA, source.WorkflowSHA256, evidenceSamples)
	if err != nil {
		return nil, ErrOptimisationReadiness
	}
	evidence.Condition = condition
	preview, err := optimisation.PreviewReadiness(optimisation.ReadinessSource{HeadSHA: source.HeadSHA, Workflow: source.Workflow}, evidence, policy)
	if err != nil {
		return nil, ErrOptimisationReadiness
	}
	return &ReadinessInspection{Source: *source, Evidence: evidence, Samples: evidenceSamples, Preview: preview}, nil
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

// PublishReadinessPreview opens one draft pull request for an approved retained
// readiness preview. It re-reads the selected job, its branch and the workflow
// with the stored provenance, rechecks the live settings and the approval, and
// refuses any change to the head, workflow, condition, bound or edit. It never
// merges and never force-pushes; a retry after an uncertain response reconciles
// the branch and pull request the earlier attempt left behind.
func (c *Controller) PublishReadinessPreview(ctx context.Context, actor *store.AuditEvent, installation, repo, id, headSHA, sourceSHA256 string, check OptimisationPolicyCheck) (*RetainedReadinessPreview, error) {
	if actor == nil || actor.ActorID == "" || installation == "" || repo == "" || id == "" || check == nil || !knownHash(headSHA, 40) || !knownHash(sourceSHA256, 64) {
		return nil, ErrOptimisationPublish
	}
	current, err := c.ReplayReadinessPreview(ctx, installation, repo, id)
	if err != nil {
		return nil, err
	}
	if current.Preview.HeadSHA != headSHA || current.Preview.SourceSHA256 != sourceSHA256 {
		return nil, ErrOptimisationReadinessApproval
	}
	if current.Approval == nil {
		return nil, ErrOptimisationNotApproved
	}
	if current.Approval.HeadSHA != headSHA || current.Approval.SourceSHA256 != sourceSHA256 {
		return nil, ErrOptimisationReadinessApproval
	}
	if current.Publication != nil {
		return current, nil
	}
	if current.Provenance == nil {
		return nil, errReadinessNoProvenance
	}
	policy, err := check(ctx)
	if err != nil {
		return nil, err
	}
	if !policy.SourceAllowed || !policy.WorkflowEditsAllowed || !policy.PublishAllowed {
		return nil, ErrOptimisationPublishPolicy
	}
	ctx, cancel := context.WithTimeout(ctx, time.Minute)
	defer cancel()
	fresh, err := c.inspectReadinessPreview(ctx, installation, repo, current.Provenance.Selection, current.Provenance.GitHubJobID, current.Preview.Condition)
	if err != nil {
		return nil, err
	}
	afterPolicy, err := check(ctx)
	if err != nil {
		return nil, err
	}
	if !afterPolicy.SourceAllowed || !afterPolicy.WorkflowEditsAllowed || !afterPolicy.PublishAllowed {
		return nil, ErrOptimisationPublishPolicy
	}
	if fresh.Source.HeadSHA != current.Preview.HeadSHA || fresh.Source.WorkflowSHA256 != current.Preview.SourceSHA256 || fresh.Source.HeadBranch != current.Provenance.HeadBranch {
		return nil, fmt.Errorf("%w: the run or its branch changed since the readiness preview; preview it again", ErrOptimisationPublish)
	}
	if fresh.Preview.Condition != current.Preview.Condition || fresh.Preview.WaitSeconds != current.Preview.WaitSeconds || fresh.Preview.Edit.Path != current.Preview.Edit.Path || fresh.Preview.File.Mode != current.Preview.File.Mode || fresh.Preview.File.Content != current.Preview.File.Content || fresh.Preview.AfterSHA256 != current.Preview.AfterSHA256 || fresh.Preview.Edit.After != current.Preview.Edit.After || fresh.Preview.JobName != current.Preview.JobName || fresh.Preview.StepName != current.Preview.StepName || fresh.Preview.Line != current.Preview.Line {
		return nil, fmt.Errorf("%w: the wait step no longer matches the readiness preview; preview it again", ErrOptimisationPublish)
	}
	// Re-read the approval and retained record after the source read: a preview
	// that expired or was evicted meanwhile must not be published, and another
	// request may already have opened its draft.
	latest, err := c.ReplayReadinessPreview(ctx, installation, repo, id)
	if err != nil {
		return nil, err
	}
	if latest.Preview.HeadSHA != headSHA || latest.Preview.SourceSHA256 != sourceSHA256 || latest.SHA256 != current.SHA256 {
		return nil, ErrOptimisationReadinessApproval
	}
	if latest.Approval == nil || latest.Approval.HeadSHA != headSHA || latest.Approval.SourceSHA256 != sourceSHA256 {
		return nil, ErrOptimisationNotApproved
	}
	if latest.Publication != nil {
		return latest, nil
	}
	if latest.Provenance == nil || latest.Provenance.HeadBranch == "" {
		return nil, errReadinessNoProvenance
	}
	client, err := c.ClientFor(ctx, installation)
	if err != nil {
		return nil, err
	}
	publisher, ok := client.(github.OptimisationPublisher)
	if !ok {
		return nil, fmt.Errorf("%w: this GitHub client cannot open draft pull requests", ErrOptimisationPublish)
	}
	info, err := client.Probe(ctx)
	if err != nil {
		if errors.Is(err, github.ErrForbidden) {
			return nil, fmt.Errorf("%w: %s", ErrOptimisationPublishPermission, github.OptimisationPublishPermissionHint)
		}
		return nil, fmt.Errorf("%w: %v", ErrOptimisationPublish, err)
	}
	if info == nil {
		return nil, fmt.Errorf("%w: GitHub did not report the App's permissions", ErrOptimisationPublish)
	}
	if missing := info.MissingForMigration(); len(missing) > 0 {
		return nil, fmt.Errorf("%w: %s; %s", ErrOptimisationPublishPermission, github.OptimisationPublishPermissionHint, strings.Join(missing, ", "))
	}
	branch := "zoomies/readiness-" + id
	title := "Poll for readiness instead of sleeping in CI"
	body := fmt.Sprintf("This draft was opened from approved Zoomies readiness preview `%s` at commit `%s`.\n\n"+
		"It replaces one fixed `sleep %d` with a poll of a readiness command an operator supplied, bounded by `timeout %d`: the old duration is the limit, and a timeout fails the step. "+
		"Zoomies did not choose or infer the command; check that it really means the service is ready. "+
		"Zoomies measured no saving: the wait time is descriptive, verification is inconclusive, and passing CI alone cannot establish improvement. "+
		"Zoomies will not merge this pull request; review the diff and let the repository's own checks decide.\n\n"+
		"<!-- zoomies-readiness-optimisation:%s -->\n", id, latest.Preview.HeadSHA, latest.Preview.WaitSeconds, latest.Preview.WaitSeconds, id)
	commitMessage := "Poll for readiness instead of sleeping in CI\n\nZoomies readiness preview " + id
	pr, err := publisher.PublishOptimisation(ctx, github.OptimisationPublishRequest{
		Repo: repo, Base: latest.Provenance.HeadBranch, BaseCommit: latest.Preview.HeadSHA, Head: branch,
		Title: title, Body: body, CommitMessage: commitMessage, PreviewID: id,
		Path: latest.Preview.Edit.Path, Mode: latest.Preview.File.Mode, Content: latest.Preview.File.Content,
		SourceSHA256: latest.Preview.SourceSHA256,
	})
	if err != nil {
		if errors.Is(err, github.ErrForbidden) {
			return nil, fmt.Errorf("%w: %s", ErrOptimisationPublishPermission, github.OptimisationPublishPermissionHint)
		}
		return nil, fmt.Errorf("%w: %w", ErrOptimisationPublish, err)
	}
	if pr == nil || pr.Number <= 0 || pr.HTMLURL == "" || pr.Branch != branch {
		return nil, fmt.Errorf("%w: GitHub did not return a usable draft pull request", ErrOptimisationPublish)
	}
	record := &store.OptimisationReadinessPublication{
		PreviewID: id, InstallationID: installation, Repository: repo, PublishedBy: actor.ActorID,
		Branch: pr.Branch, BaseBranch: latest.Provenance.HeadBranch, BaseSHA: latest.Preview.HeadSHA, HeadSHA: latest.Preview.HeadSHA,
		SourceSHA256: latest.Preview.SourceSHA256, PreviewSHA256: latest.SHA256,
		PullNumber: pr.Number, PullURL: pr.HTMLURL,
	}
	if err := c.st.PutOptimisationReadinessPublication(ctx, record, actor); err != nil {
		c.log.Error("recording a readiness publication", "error", err, "preview", id, "pull_request", pr.Number)
		return nil, fmt.Errorf("%w: the draft pull request #%d was opened, but its record could not be saved; press publish again to reconcile it", ErrOptimisationPublish, pr.Number)
	}
	latest.Publication = &RetainedReadinessPublication{
		PublishedBy: record.PublishedBy, PublishedAt: record.CreatedAt, Branch: record.Branch, BaseBranch: record.BaseBranch,
		BaseSHA: record.BaseSHA, HeadSHA: record.HeadSHA, SourceSHA256: record.SourceSHA256, PreviewSHA256: record.PreviewSHA256,
		PullNumber: record.PullNumber, PullURL: record.PullURL,
	}
	return latest, nil
}

// errReadinessNoProvenance refuses a preview kept before the selected job and
// branch were recorded: its branch cannot be rechecked, so it cannot be published.
var errReadinessNoProvenance = fmt.Errorf("%w: this preview predates branch recording; make a new readiness preview before publishing", ErrOptimisationPublish)

package controller

import (
	"bytes"
	"context"
	"encoding/json"
	"io"
	"time"

	"github.com/eyupio/zoomies/internal/aicontext"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/optimisation"
	"github.com/eyupio/zoomies/internal/prrepair"
	"github.com/eyupio/zoomies/internal/store"
)

type optimisationReadinessRetainedProvenance struct {
	SelectionRunID   int64  `json:"selection_run_id"`
	SelectionAttempt int    `json:"selection_attempt"`
	GitHubJobID      int64  `json:"github_job_id"`
	HeadBranch       string `json:"head_branch"`
}

type optimisationReadinessRetainedSource struct {
	HeadSHA string `json:"head_sha"`
	Path    string `json:"path"`
	Mode    string `json:"mode"`
	Content string `json:"content"`
}

type optimisationReadinessRetainedEnvelope struct {
	Version        string                                   `json:"version"`
	ID             string                                   `json:"id"`
	InstallationID string                                   `json:"installation_id"`
	Repository     string                                   `json:"repository"`
	ReviewedBy     string                                   `json:"reviewed_by"`
	ModelFunding   string                                   `json:"model_funding"`
	Provenance     *optimisationReadinessRetainedProvenance `json:"provenance,omitempty"`
	Source         optimisationReadinessRetainedSource      `json:"source"`
	Evidence       optimisation.ReadinessEvidence           `json:"evidence"`
	Samples        []optimisation.SetupSample               `json:"samples"`
	Preview        optimisation.ReadinessPreview            `json:"preview"`
}

// RetainedReadinessPreview is a kept bounded readiness preview. The full source
// stays in the private envelope; a transport renders the edit, metadata and
// evidence summary only.
type RetainedReadinessPreview struct {
	ID             string
	InstallationID string
	Repository     string
	ReviewedBy     string
	SHA256         string
	CreatedAt      time.Time
	Currentness    string
	Preview        optimisation.ReadinessPreview
	Provenance     *ReadinessProvenance
	Approval       *RetainedReadinessApproval
	Publication    *RetainedReadinessPublication
}

// RetainedReadinessApproval is one attributed decision about the exact retained
// readiness preview. It is not a publication and expires with the preview.
type RetainedReadinessApproval struct {
	ApprovedBy    string
	ApprovedAt    time.Time
	HeadSHA       string
	SourceSHA256  string
	PreviewSHA256 string
}

// ReadinessProvenance is the selected fleet job and branch a kept preview was
// bound to. Previews retained before this was recorded cannot be published.
type ReadinessProvenance struct {
	Selection   github.SetupCacheSelection
	GitHubJobID int64
	HeadBranch  string
}

// CaptureReadinessPreview re-reads the source and wait history, requires the same
// head, workflow digest and condition the operator reviewed, and keeps an
// immutable private preview for fourteen days.
func (c *Controller) CaptureReadinessPreview(ctx context.Context, actor *store.AuditEvent, installation, repo string, selection github.SetupCacheSelection, githubJobID int64, condition, headSHA, sourceSHA256 string) (*RetainedReadinessPreview, error) {
	if actor == nil || actor.ActorID == "" || !knownHash(headSHA, 40) || !knownHash(sourceSHA256, 64) || condition == "" {
		return nil, ErrOptimisationReadiness
	}
	inspection, err := c.inspectReadinessPreview(ctx, installation, repo, selection, githubJobID, condition)
	if err != nil {
		return nil, err
	}
	if inspection.Source.HeadSHA != headSHA || inspection.Source.WorkflowSHA256 != sourceSHA256 || inspection.Preview.Condition != condition {
		return nil, ErrOptimisationReadiness
	}
	envelope := optimisationReadinessRetainedEnvelope{
		Version: store.OptimisationReadinessPreviewVersion, ID: store.NewID(store.PrefixOptimisationReadinessPreview),
		InstallationID: installation, Repository: repo, ReviewedBy: actor.ActorID, ModelFunding: "no_model_call",
		Provenance: &optimisationReadinessRetainedProvenance{SelectionRunID: selection.RunID, SelectionAttempt: selection.Attempt, GitHubJobID: githubJobID, HeadBranch: inspection.Source.HeadBranch},
		Source:     optimisationReadinessRetainedSource{HeadSHA: inspection.Source.HeadSHA, Path: inspection.Source.Workflow.Path, Mode: inspection.Source.Workflow.Mode, Content: inspection.Source.Workflow.Content},
		Evidence:   inspection.Evidence, Samples: inspection.Samples, Preview: inspection.Preview,
	}
	payload, err := json.Marshal(envelope)
	if err != nil {
		return nil, err
	}
	if len(payload) > store.MaxOptimisationReadinessPreviewBytes {
		return nil, ErrOptimisationReadiness
	}
	row := &store.OptimisationReadinessPreview{ID: envelope.ID, InstallationID: installation, Repository: repo, InitiatingUser: actor.ActorID, Version: envelope.Version, Payload: payload}
	if err := c.st.PutOptimisationReadinessPreview(ctx, row, actor); err != nil {
		return nil, err
	}
	return retainedReadinessView(row, inspection.Preview, envelope.Provenance), nil
}

// ReplayReadinessPreview validates historical calculation, not the current head
// or policy. It never reads replacement source.
func (c *Controller) ReplayReadinessPreview(ctx context.Context, installation, repo, id string) (*RetainedReadinessPreview, error) {
	row, err := c.st.GetOptimisationReadinessPreview(ctx, installation, repo, id)
	if err != nil {
		return nil, err
	}
	var e optimisationReadinessRetainedEnvelope
	dec := json.NewDecoder(bytes.NewReader(row.Payload))
	dec.DisallowUnknownFields()
	if dec.Decode(&e) != nil || dec.Decode(new(any)) != io.EOF || row.Version != store.OptimisationReadinessPreviewVersion || e.Version != row.Version || e.ID != row.ID || e.InstallationID != row.InstallationID || e.Repository != row.Repository || e.ReviewedBy != row.InitiatingUser || e.ModelFunding != "no_model_call" {
		return nil, ErrOptimisationReadiness
	}
	if p := e.Provenance; p != nil && (p.SelectionRunID <= 0 || p.SelectionAttempt <= 0 || p.GitHubJobID <= 0 || !aicontext.ValidBranch(p.HeadBranch)) {
		return nil, ErrOptimisationReadiness
	}
	evidence, err := optimisation.ReadinessEvidenceFromSamples(e.Source.HeadSHA, hashString(e.Source.Content), e.Samples)
	if err != nil {
		return nil, ErrOptimisationReadiness
	}
	evidence.Condition = e.Evidence.Condition
	oldEvidence, _ := json.Marshal(e.Evidence)
	newEvidence, _ := json.Marshal(evidence)
	if !bytes.Equal(oldEvidence, newEvidence) {
		return nil, ErrOptimisationReadiness
	}
	source := optimisation.ReadinessSource{HeadSHA: e.Source.HeadSHA, Workflow: prrepair.File{Path: e.Source.Path, Mode: e.Source.Mode, Content: e.Source.Content}}
	preview, err := optimisation.PreviewReadiness(source, evidence, optimisation.Policy{SourceAllowed: true, WorkflowEditsAllowed: true})
	if err != nil {
		return nil, ErrOptimisationReadiness
	}
	oldPreview, _ := json.Marshal(e.Preview)
	newPreview, _ := json.Marshal(preview)
	if !bytes.Equal(oldPreview, newPreview) {
		return nil, ErrOptimisationReadiness
	}
	return retainedReadinessView(row, preview, e.Provenance), nil
}

func retainedReadinessView(row *store.OptimisationReadinessPreview, preview optimisation.ReadinessPreview, p *optimisationReadinessRetainedProvenance) *RetainedReadinessPreview {
	v := &RetainedReadinessPreview{ID: row.ID, InstallationID: row.InstallationID, Repository: row.Repository, ReviewedBy: row.InitiatingUser, SHA256: row.SHA256, CreatedAt: row.CreatedAt, Currentness: "not_checked", Preview: preview}
	if p != nil {
		v.Provenance = &ReadinessProvenance{Selection: github.SetupCacheSelection{RunID: p.SelectionRunID, Attempt: p.SelectionAttempt}, GitHubJobID: p.GitHubJobID, HeadBranch: p.HeadBranch}
	}
	if a := row.Approval; a != nil {
		v.Approval = &RetainedReadinessApproval{ApprovedBy: a.ApprovedBy, ApprovedAt: a.CreatedAt, HeadSHA: a.HeadSHA, SourceSHA256: a.SourceSHA256, PreviewSHA256: a.PreviewSHA256}
	}
	if p := row.Publication; p != nil {
		v.Publication = &RetainedReadinessPublication{PublishedBy: p.PublishedBy, PublishedAt: p.CreatedAt, Branch: p.Branch, BaseBranch: p.BaseBranch, BaseSHA: p.BaseSHA, HeadSHA: p.HeadSHA, SourceSHA256: p.SourceSHA256, PreviewSHA256: p.PreviewSHA256, PullNumber: p.PullNumber, PullURL: p.PullURL}
	}
	return v
}

// RetainedReadinessPublication is the one draft pull request opened for an
// approved readiness preview. It is not a merge and does not claim a saving.
type RetainedReadinessPublication struct {
	PublishedBy   string
	PublishedAt   time.Time
	Branch        string
	BaseBranch    string
	BaseSHA       string
	HeadSHA       string
	SourceSHA256  string
	PreviewSHA256 string
	PullNumber    int
	PullURL       string
}

// ApproveReadinessPreview records an operator's explicit approval of the exact
// retained readiness preview they name. It reads no source and calls no GitHub
// reader, so an approval cannot publish, edit a workflow or start a job.
func (c *Controller) ApproveReadinessPreview(ctx context.Context, actor *store.AuditEvent, installation, repo, id, headSHA, sourceSHA256 string) (*RetainedReadinessPreview, error) {
	if actor == nil || actor.ActorID == "" || installation == "" || repo == "" || id == "" || !knownHash(headSHA, 40) || !knownHash(sourceSHA256, 64) {
		return nil, ErrOptimisationReadinessApproval
	}
	current, err := c.ReplayReadinessPreview(ctx, installation, repo, id)
	if err != nil {
		return nil, err
	}
	if current.Preview.HeadSHA != headSHA || current.Preview.SourceSHA256 != sourceSHA256 {
		return nil, ErrOptimisationReadinessApproval
	}
	approval, err := c.st.ApproveOptimisationReadinessPreview(ctx, installation, repo, id, headSHA, sourceSHA256, current.SHA256, actor)
	if err != nil {
		return nil, err
	}
	current.Approval = &RetainedReadinessApproval{ApprovedBy: approval.ApprovedBy, ApprovedAt: approval.CreatedAt, HeadSHA: approval.HeadSHA, SourceSHA256: approval.SourceSHA256, PreviewSHA256: approval.PreviewSHA256}
	return current, nil
}

package controller

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"io"
	"time"

	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/optimisation"
	"github.com/eyupio/zoomies/internal/prrepair"
	"github.com/eyupio/zoomies/internal/store"
)

var (
	ErrOptimisationPreview  = errors.New("optimisation preview evidence is unavailable, inconsistent or unsupported")
	ErrOptimisationApproval = errors.New("the approval does not name the retained preview")
)

type optimisationRetainedSource struct {
	HeadSHA string `json:"head_sha"`
	Path    string `json:"path"`
	Mode    string `json:"mode"`
	Content string `json:"content"`
}

func (s optimisationRetainedSource) source() optimisation.Source {
	return optimisation.Source{HeadSHA: s.HeadSHA, File: prrepair.File{Path: s.Path, Mode: s.Mode, Content: s.Content}}
}

// OptimisationCheckoutProvenance contains no raw API names, URLs or logs.
// Nil remains unknown for previews retained before evidence admission.
type OptimisationCheckoutProvenance struct {
	Version        string                   `json:"version"`
	Basis          string                   `json:"basis"`
	Selection      github.CheckoutSelection `json:"selection"`
	StepNumber     int64                    `json:"step_number"`
	BlobSHA        string                   `json:"blob_sha"`
	JobNameSHA256  string                   `json:"job_name_sha256"`
	StepNameSHA256 string                   `json:"step_name_sha256"`
	SourceFunding  string                   `json:"source_funding"`
	// HeadBranch is the branch the push ran on. A preview retained before this
	// was recorded has none, stays readable and is not publishable.
	HeadBranch string `json:"head_branch,omitempty"`
}

func (p *OptimisationCheckoutProvenance) evidence(repo string, source optimisation.Source, timing optimisation.Timing) *github.CheckoutEvidence {
	return &github.CheckoutEvidence{Version: p.Version, Basis: p.Basis, Repository: repo, Selection: p.Selection, StepNumber: p.StepNumber, BlobSHA: p.BlobSHA, JobNameSHA256: p.JobNameSHA256, StepNameSHA256: p.StepNameSHA256, Source: source, Timing: timing, HeadBranch: p.HeadBranch}
}

type optimisationRetainedEnvelope struct {
	Collection     *OptimisationCheckoutProvenance `json:"collection,omitempty"`
	Version        string                          `json:"version"`
	ID             string                          `json:"id"`
	InstallationID string                          `json:"installation_id"`
	Repository     string                          `json:"repository"`
	ReviewedBy     string                          `json:"reviewed_by"`
	ModelFunding   string                          `json:"model_funding"`
	Source         optimisationRetainedSource      `json:"source"`
	Timing         optimisation.Timing             `json:"timing"`
	History        optimisation.HistoryReview      `json:"history"`
	Preview        optimisation.Preview            `json:"preview"`
}

// RetainedOptimisationApproval is a separate, attributed act from keeping the
// preview. It names the exact preview, head and source digest that were
// approved, and it grants no publication authority by itself.
type RetainedOptimisationApproval struct {
	ApprovedBy    string
	ApprovedAt    time.Time
	HeadSHA       string
	SourceSHA256  string
	PreviewSHA256 string
}

// RetainedOptimisationPublication is the one draft pull request opened for an
// approved preview. It is a record of the external write, not a merge and not
// a claim that the change saves time.
type RetainedOptimisationPublication struct {
	PublishedBy   string
	PublishedAt   time.Time
	Branch        string
	BaseBranch    string
	BaseSHA       string
	HeadSHA       string
	SourceSHA256  string
	PreviewSHA256 string
	PullNumber    int
	PullURL       string
}

type RetainedOptimisationVerification struct {
	ComparisonID string
	LinkedBy     string
	LinkedAt     time.Time
}

type RetainedOptimisationPreview struct {
	Collection     *OptimisationCheckoutProvenance
	Approval       *RetainedOptimisationApproval
	Publication    *RetainedOptimisationPublication
	Verification   *RetainedOptimisationVerification
	ID             string
	InstallationID string
	Repository     string
	ReviewedBy     string
	SHA256         string
	CreatedAt      time.Time
	Currentness    string
	Preview        optimisation.Preview
}

// RetainOptimisationPreview is an internal adapter for already admitted source,
// timing and policy. It is not a collector and has no route. A future transport
// must independently authorise source-bearing history and obtain evidence; request
// booleans or client-submitted timing must never stand in for server admission.
func (c *Controller) RetainOptimisationPreview(ctx context.Context, actor *store.AuditEvent, installation, repo string, source optimisation.Source, timing optimisation.Timing, history optimisation.HistoryReview, policy optimisation.Policy) (*RetainedOptimisationPreview, error) {
	return c.retainOptimisationPreview(ctx, actor, installation, repo, source, timing, history, policy, nil)
}
func (c *Controller) retainOptimisationPreview(ctx context.Context, actor *store.AuditEvent, installation, repo string, source optimisation.Source, timing optimisation.Timing, history optimisation.HistoryReview, policy optimisation.Policy, collection *OptimisationCheckoutProvenance) (*RetainedOptimisationPreview, error) {
	if collection != nil && (collection.SourceFunding != "installation_github_read" || !github.ValidCheckoutEvidence(collection.evidence(repo, source, timing), repo, collection.Selection)) {
		return nil, ErrOptimisationPreview
	}
	if actor == nil || actor.ActorID == "" || source.File.Partial || source.File.StartLine != 0 {
		return nil, ErrOptimisationPreview
	}
	preview, err := optimisation.PreviewCheckout(source, timing, history, policy)
	if err != nil {
		return nil, ErrOptimisationPreview
	}
	envelope := optimisationRetainedEnvelope{
		Collection: collection,
		Version:    store.OptimisationPreviewVersion, ID: store.NewID(store.PrefixOptimisationPreview),
		InstallationID: installation, Repository: repo, ReviewedBy: actor.ActorID,
		ModelFunding: "no_model_call",
		Source:       optimisationRetainedSource{HeadSHA: source.HeadSHA, Path: source.File.Path, Mode: source.File.Mode, Content: source.File.Content},
		Timing:       timing, History: history, Preview: preview,
	}
	payload, err := json.Marshal(envelope)
	if err != nil {
		return nil, err
	}
	row := &store.OptimisationPreview{ID: envelope.ID, InstallationID: installation, Repository: repo, InitiatingUser: actor.ActorID, Version: envelope.Version, Payload: payload}
	if err := c.st.PutOptimisationPreview(ctx, row, actor); err != nil {
		return nil, err
	}
	return retainedOptimisationView(row, preview, collection), nil
}

// ReplayOptimisationPreview validates historical calculation, not current head
// or current publication policy. It never reads replacement source. Its private
// source-bearing result requires separate authorisation before any future route.
func (c *Controller) ReplayOptimisationPreview(ctx context.Context, installation, repo, id string) (*RetainedOptimisationPreview, error) {
	row, err := c.st.GetOptimisationPreview(ctx, installation, repo, id)
	if err != nil {
		return nil, err
	}
	var e optimisationRetainedEnvelope
	dec := json.NewDecoder(bytes.NewReader(row.Payload))
	dec.DisallowUnknownFields()
	if dec.Decode(&e) != nil || dec.Decode(new(any)) != io.EOF || row.Version != store.OptimisationPreviewVersion || e.Version != row.Version || e.ID != row.ID || e.InstallationID != row.InstallationID || e.Repository != row.Repository || e.ReviewedBy != row.InitiatingUser || e.ModelFunding != "no_model_call" {
		return nil, ErrOptimisationPreview
	}
	if e.Collection != nil && (e.Collection.SourceFunding != "installation_github_read" || !github.ValidCheckoutEvidence(e.Collection.evidence(row.Repository, e.Source.source(), e.Timing), row.Repository, e.Collection.Selection)) {
		return nil, ErrOptimisationPreview
	}
	// Policy here permits recomputation only. Replay neither grants future edit
	// authority nor claims the historical preview remains current.
	preview, err := optimisation.PreviewCheckout(e.Source.source(), e.Timing, e.History, optimisation.Policy{SourceAllowed: true, WorkflowEditsAllowed: true})
	if err != nil {
		return nil, ErrOptimisationPreview
	}
	oldJSON, err := json.Marshal(e.Preview)
	if err != nil {
		return nil, err
	}
	newJSON, err := json.Marshal(preview)
	if err != nil {
		return nil, err
	}
	if !bytes.Equal(oldJSON, newJSON) {
		return nil, ErrOptimisationPreview
	}
	return retainedOptimisationView(row, preview, e.Collection), nil
}

// ApproveOptimisationPreview records an explicit, attributed approval of the
// exact retained preview the caller names. It reads no source and calls no
// GitHub reader, so an approval cannot publish, edit a workflow or start a job.
// The head and source digest must be the ones the retained preview already
// binds; a mismatch is refused rather than approved by accident.
func (c *Controller) ApproveOptimisationPreview(ctx context.Context, actor *store.AuditEvent, installation, repo, id, headSHA, sourceSHA256 string) (*RetainedOptimisationPreview, error) {
	if actor == nil || actor.ActorID == "" || id == "" || installation == "" || repo == "" || !knownHash(headSHA, 40) || !knownHash(sourceSHA256, 64) {
		return nil, ErrOptimisationApproval
	}
	current, err := c.ReplayOptimisationPreview(ctx, installation, repo, id)
	if err != nil {
		return nil, err
	}
	if current.Preview.HeadSHA != headSHA || current.Preview.SourceSHA256 != sourceSHA256 {
		return nil, ErrOptimisationApproval
	}
	approval, err := c.st.ApproveOptimisationPreview(ctx, installation, repo, id, headSHA, sourceSHA256, current.SHA256, actor)
	if err != nil {
		return nil, err
	}
	current.Approval = &RetainedOptimisationApproval{
		ApprovedBy: approval.ApprovedBy, ApprovedAt: approval.CreatedAt,
		HeadSHA: approval.HeadSHA, SourceSHA256: approval.SourceSHA256, PreviewSHA256: approval.PreviewSHA256,
	}
	return current, nil
}

func retainedOptimisationView(row *store.OptimisationPreview, preview optimisation.Preview, collection *OptimisationCheckoutProvenance) *RetainedOptimisationPreview {
	v := &RetainedOptimisationPreview{Collection: collection, ID: row.ID, InstallationID: row.InstallationID, Repository: row.Repository, ReviewedBy: row.InitiatingUser, SHA256: row.SHA256, CreatedAt: row.CreatedAt, Currentness: "not_checked", Preview: preview}
	if a := row.Approval; a != nil {
		v.Approval = &RetainedOptimisationApproval{ApprovedBy: a.ApprovedBy, ApprovedAt: a.CreatedAt, HeadSHA: a.HeadSHA, SourceSHA256: a.SourceSHA256, PreviewSHA256: a.PreviewSHA256}
	}
	if p := row.Publication; p != nil {
		v.Publication = &RetainedOptimisationPublication{PublishedBy: p.PublishedBy, PublishedAt: p.CreatedAt, Branch: p.Branch, BaseBranch: p.BaseBranch, BaseSHA: p.BaseSHA, HeadSHA: p.HeadSHA, SourceSHA256: p.SourceSHA256, PreviewSHA256: p.PreviewSHA256, PullNumber: p.PullNumber, PullURL: p.PullURL}
	}
	if x := row.Verification; x != nil {
		v.Verification = &RetainedOptimisationVerification{ComparisonID: x.ComparisonID, LinkedBy: x.LinkedBy, LinkedAt: x.CreatedAt}
	}
	return v
}

package controller

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/optimisation"
	"github.com/eyupio/zoomies/internal/prrepair"
	"github.com/eyupio/zoomies/internal/store"
)

func optimisationRetentionFixture(t *testing.T) (*Controller, string, optimisation.Source, optimisation.Timing, optimisation.HistoryReview, optimisation.Policy, *store.AuditEvent) {
	t.Helper()
	s, err := store.Open(context.Background(), store.Options{Path: ":memory:"})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { s.Close() })
	inst := &store.Installation{AppID: 1, InstallationID: 2, Target: "acme/repo", TargetType: store.TargetRepo}
	if err := s.CreateInstallation(context.Background(), inst); err != nil {
		t.Fatal(err)
	}
	file := prrepair.File{Path: ".github/workflows/private.yml", Mode: "100644", Content: "on: push\njobs:\n  private:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@" + strings.Repeat("b", 40) + "\n        with:\n          fetch-depth: 0\n      - run: npm test\n"}
	source := optimisation.Source{HeadSHA: strings.Repeat("a", 40), File: file}
	sum := sha256.Sum256([]byte(file.Content))
	digest := hex.EncodeToString(sum[:])
	ms, needs := int64(4200), false
	timing := optimisation.Timing{EvidenceID: "fixture", HeadSHA: source.HeadSHA, SourceSHA256: digest, RunID: "9223372036854775807", Attempt: 2, JobIndex: 0, StepIndex: 0, Outcome: "success", CheckoutMS: &ms}
	history := optimisation.HistoryReview{HeadSHA: source.HeadSHA, SourceSHA256: digest, Scope: "repository_and_downstream_consumers", NeedsHistory: &needs}
	return &Controller{st: s}, inst.ID, source, timing, history, optimisation.Policy{SourceAllowed: true, WorkflowEditsAllowed: true}, &store.AuditEvent{ActorID: "usr_operator", ActorKind: "user", ActorName: "operator"}
}
func TestRetainedOptimisationReplaysExactPrivateSourceWithoutGitHubOrCurrentPolicy(t *testing.T) {
	c, installation, source, timing, history, policy, actor := optimisationRetentionFixture(t)
	saved, err := c.RetainOptimisationPreview(context.Background(), actor, installation, "acme/repo", source, timing, history, policy)
	if err != nil {
		t.Fatal(err)
	}
	*timing.CheckoutMS = 9999
	*history.NeedsHistory = true
	source.File.Content = "changed"
	policy.WorkflowEditsAllowed = false
	actor.ActorID = "changed"
	replay, err := c.ReplayOptimisationPreview(context.Background(), installation, "acme/repo", saved.ID)
	if err != nil {
		t.Fatal(err)
	}
	a, _ := json.Marshal(saved)
	b, _ := json.Marshal(replay)
	if string(a) != string(b) || replay.Preview.File.Mode != "100644" || replay.ReviewedBy != "usr_operator" || replay.Preview.Verification != "inconclusive" || replay.Currentness != "not_checked" || replay.Preview.RunID != "9223372036854775807" {
		t.Fatal("offline replay changed the preview or authority")
	}
	if _, err := c.ReplayOptimisationPreview(context.Background(), "other", "acme/repo", saved.ID); !errors.Is(err, store.ErrNotFound) {
		t.Fatal("cross-installation read", err)
	}
	if _, err := c.ReplayOptimisationPreview(context.Background(), installation, "other/repo", saved.ID); !errors.Is(err, store.ErrNotFound) {
		t.Fatal("cross-repository read", err)
	}
	events, total, err := c.st.ListAudit(context.Background(), store.AuditFilter{TargetID: saved.ID}, store.Page{Limit: 10})
	if err != nil || total != 1 || strings.Contains(events[0].Before+events[0].After, "fetch-depth") || events[0].Action != "optimisation.preview_retained" {
		t.Fatal("source in audit or missing atomic audit", err)
	}
}
func TestOptimisationReplayRefusesAlteredCalculationAndBindingsEvenWithAValidStorageDigest(t *testing.T) {
	c, installation, source, timing, history, policy, actor := optimisationRetentionFixture(t)
	saved, err := c.RetainOptimisationPreview(context.Background(), actor, installation, "acme/repo", source, timing, history, policy)
	if err != nil {
		t.Fatal(err)
	}
	original, err := c.st.GetOptimisationPreview(context.Background(), installation, "acme/repo", saved.ID)
	if err != nil {
		t.Fatal(err)
	}
	for _, mode := range []string{"preview", "history", "source", "installation", "repository", "actor", "funding", "future"} {
		t.Run(mode, func(t *testing.T) {
			var e optimisationRetainedEnvelope
			if err := json.Unmarshal(original.Payload, &e); err != nil {
				t.Fatal(err)
			}
			row := *original
			row.ID = store.NewID(store.PrefixOptimisationPreview)
			e.ID = row.ID
			switch mode {
			case "preview":
				e.Preview.Verification = "improved"
			case "history":
				*e.History.NeedsHistory = true
			case "source":
				e.Source.Mode = "120000"
			case "installation":
				e.InstallationID = "other"
			case "repository":
				e.Repository = "other/repo"
			case "actor":
				e.ReviewedBy = "other"
			case "funding":
				e.ModelFunding = "someone_else"
			}
			row.Payload, _ = json.Marshal(e)
			if mode == "future" {
				row.Payload = append(row.Payload[:len(row.Payload)-1], []byte(`,"future":true}`)...)
			}
			if err := c.st.PutOptimisationPreview(context.Background(), &row, actor); err != nil {
				t.Fatal(err)
			}
			if _, err := c.ReplayOptimisationPreview(context.Background(), installation, "acme/repo", row.ID); !errors.Is(err, ErrOptimisationPreview) {
				t.Fatal("altered evidence accepted", err)
			}
		})
	}
}
func TestOptimisationRetentionRefusesInvalidInputsBeforeWritingHistory(t *testing.T) {
	for _, mode := range []string{"actor", "history", "policy", "partial", "window", "scope"} {
		t.Run(mode, func(t *testing.T) {
			c, installation, source, timing, history, policy, actor := optimisationRetentionFixture(t)
			repo := "acme/repo"
			switch mode {
			case "actor":
				actor = nil
			case "history":
				history.NeedsHistory = nil
			case "policy":
				policy.WorkflowEditsAllowed = false
			case "partial":
				source.File.Partial = true
			case "window":
				source.File.StartLine = 1
			case "scope":
				repo = "other/repo"
			}
			if r, err := c.RetainOptimisationPreview(context.Background(), actor, installation, repo, source, timing, history, policy); err == nil || r != nil {
				t.Fatal("unsupported preview retained")
			}
			_, total, err := c.st.ListAudit(context.Background(), store.AuditFilter{Actions: []string{"optimisation.preview_retained"}}, store.Page{Limit: 10})
			if err != nil || total != 0 {
				t.Fatal("refusal wrote an audit", err)
			}
		})
	}
}

package controller

import (
	"context"
	"errors"
	"strconv"
	"time"

	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/kennel/workflow"
	"github.com/eyupio/zoomies/internal/optimisation"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

var (
	ErrOptimisationSharding         = errors.New("sharding preview evidence is unavailable, inconsistent or unsupported")
	ErrOptimisationShardingApproval = errors.New("the sharding preview's head and source digest do not match the retained preview")
)

// ShardingInspection is what an operator is shown before keeping a sharding
// preview. It carries the source identity, the retained timing evidence and the
// computed preview, but never the full workflow file in a transport.
type ShardingInspection struct {
	Source   github.ShardSource
	Evidence optimisation.ShardEvidence
	Samples  []optimisation.ShardSample
	Preview  optimisation.ShardPreview
}

// InspectShardingPreview binds one selected fleet job and one pinned GitHub
// attempt to the pure sharding preview. The source read is the only GitHub work;
// the test and setup timings come from the fleet's retained job history and the
// headroom from the fleet's own pools and hosts. It retains nothing.
func (c *Controller) InspectShardingPreview(ctx context.Context, installation, repo string, selection github.SetupCacheSelection, githubJobID int64) (*optimisation.ShardPreview, error) {
	inspection, err := c.inspectShardingPreview(ctx, installation, repo, selection, githubJobID)
	if err != nil {
		return nil, err
	}
	return &inspection.Preview, nil
}

func (c *Controller) inspectShardingPreview(ctx context.Context, installation, repo string, selection github.SetupCacheSelection, githubJobID int64) (*ShardingInspection, error) {
	if installation == "" || repo == "" || githubJobID <= 0 || !github.ValidSetupCacheSelection(selection) {
		return nil, ErrOptimisationSharding
	}
	inst, err := c.st.GetInstallation(ctx, installation)
	if err != nil {
		return nil, err
	}
	owner, name, kind := github.SplitTarget(repo)
	if kind != store.TargetRepo || name == "" || !(inst.TargetType == store.TargetRepo && inst.Target == repo || inst.TargetType == store.TargetOrg && inst.Target == owner) {
		return nil, ErrOptimisationSharding
	}
	policy, err := c.OptimisationPolicy(ctx)
	if err != nil {
		return nil, err
	}
	if !policy.SourceAllowed || !policy.WorkflowEditsAllowed {
		return nil, ErrOptimisationPolicy
	}
	if c.githubHeld(installation, c.Now()) {
		return nil, github.ErrRateLimited
	}
	client, err := c.ClientFor(ctx, installation)
	if err != nil {
		return nil, err
	}
	reader, ok := client.(github.ShardSourceReader)
	if !ok {
		return nil, ErrOptimisationSharding
	}
	ctx, cancel := context.WithTimeout(ctx, 20*time.Second)
	defer cancel()
	release, err := c.admitPRDelay(installation)
	if err != nil {
		return nil, err
	}
	defer release()
	quota, err := client.RateLimit(ctx)
	if err != nil {
		c.holdIfRateLimited(installation, err, c.Now(), "reading sharding preview quota")
		return nil, err
	}
	if quota == nil || quota.Limit <= 0 || quota.Remaining < 0 || quota.Remaining > quota.Limit || quota.Remaining-github.ShardEvidenceMaximumRequests < quota.Limit/2+quota.Limit%2 {
		retry := time.Minute
		if quota != nil && quota.ResetAt.After(c.Now()) {
			retry = quota.ResetAt.Sub(c.Now())
		}
		return nil, &PRDelayAdmissionError{RetryAfter: retry}
	}
	if c.githubHeld(installation, c.Now()) {
		return nil, github.ErrRateLimited
	}
	source, err := reader.ReadShardSource(ctx, repo, selection)
	if err != nil {
		c.holdIfRateLimited(installation, err, c.Now(), "reading sharding preview source")
		return nil, shardingSourceError(err)
	}
	if !github.ValidShardSource(source, repo, selection) {
		return nil, ErrOptimisationSharding
	}
	job, err := c.st.GetJobByGitHubID(ctx, githubJobID)
	if err != nil {
		return nil, err
	}
	if job.Repo != repo || job.InstallationID != installation || job.GitHubRunID != selection.RunID || job.RunAttempt != selection.Attempt || job.HeadSHA != source.HeadSHA || job.Workflow == "" || job.JobName != source.JobName || job.State != store.JobCompleted || job.Conclusion != "success" {
		return nil, ErrOptimisationSharding
	}
	history, err := c.st.RecentSetupStepSamples(ctx, repo, job.Workflow, source.JobName, source.StepName, c.Now().Add(-90*24*time.Hour), 100)
	if err != nil {
		return nil, err
	}
	samples := make([]optimisation.ShardSample, 0, len(history))
	selectedFound := false
	for _, h := range history {
		// A run whose test step had nothing recorded before it has no setup
		// figure to repeat, so it cannot size the shards.
		if h.RunAttempt < 1 || h.SetupMS <= 0 || h.LeadMS <= 0 {
			continue
		}
		if h.JobID == job.ID {
			selectedFound = true
		}
		samples = append(samples, optimisation.ShardSample{
			JobID: h.JobID, RunID: strconv.FormatInt(h.GitHubRunID, 10), Attempt: h.RunAttempt,
			StepNumber: h.StepNumber, TestMS: h.SetupMS, SetupMS: h.LeadMS,
		})
	}
	if !selectedFound {
		return nil, ErrOptimisationSharding
	}
	headroom, err := c.shardHeadroom(ctx, installation, job.Labels)
	if err != nil {
		return nil, err
	}
	evidence, err := optimisation.ShardEvidenceFromSamples(source.HeadSHA, source.WorkflowSHA256, headroom, samples)
	if err != nil {
		return nil, err
	}
	preview, err := optimisation.PreviewSharding(optimisation.ShardSource{HeadSHA: source.HeadSHA, Workflow: source.Workflow}, evidence, policy)
	if err != nil {
		return nil, err
	}
	return &ShardingInspection{Source: *source, Evidence: evidence, Samples: samples, Preview: preview}, nil
}

// shardHeadroom is how many more runners the best pool for the job's labels
// could start right now: its configured maximum less the runners it already
// has, held down by the free slots on hosts that are healthy and not cordoned.
// It is an upper bound read at one moment, not a reservation, and the preview
// says so; shards that cannot all start at once queue behind each other.
func (c *Controller) shardHeadroom(ctx context.Context, installation string, labels []string) (int, error) {
	pools, err := c.st.ListPools(ctx)
	if err != nil {
		return 0, err
	}
	counts, err := c.st.CountRunnersByPool(ctx)
	if err != nil {
		return 0, err
	}
	best := 0
	for _, p := range pools {
		if !p.Enabled || p.InstallationID != installation || !scheduler.PoolMatches(p, labels) {
			continue
		}
		if room := p.MaxRunners - counts[p.ID].Live(); room > best {
			best = room
		}
	}
	if best == 0 {
		return 0, nil
	}
	hosts, err := c.st.ListHosts(ctx)
	if err != nil {
		return 0, err
	}
	now, free := c.Now(), 0
	for _, h := range hosts {
		if h.Healthy(now) && !h.Cordoned {
			free += h.Free()
		}
	}
	return min(best, free), nil
}

// shardingSourceError turns the workflow's own refusal into the one the
// operator is shown, so they are told what to change in the file instead of that
// a read failed. Every other error is passed on unchanged.
func shardingSourceError(err error) error {
	var refusal *workflow.ShardRefusal
	switch {
	case errors.As(err, &refusal):
		return &optimisation.ShardingRefusal{Reason: refusal.Reason}
	case errors.Is(err, workflow.ErrShardNotFound):
		return &optimisation.ShardingRefusal{Reason: "no single Playwright test step on an Ubuntu runner was found in the workflow"}
	case errors.Is(err, workflow.ErrShardAmbiguous):
		return &optimisation.ShardingRefusal{Reason: "more than one Playwright test step was found, and Zoomies will not guess which to shard"}
	}
	return err
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

// PublishShardingPreview opens one draft pull request for an approved retained
// sharding preview. It re-reads the selected job, its branch, the workflow and
// the history with the stored provenance, rechecks the live settings and the
// approval, and refuses a change to the head, the workflow, the branch or the
// step. It never merges and never force-pushes; a retry after an uncertain
// response reconciles the branch and pull request the earlier attempt left.
//
// The shard count is the one thing allowed to differ on the fresh read, and
// only upwards: the pool's headroom moves with the fleet's load, so insisting on
// the same count would refuse a good change whenever a runner happened to be
// busy. A count the pool or the history no longer supports is refused, and what
// is published is always the approved change, never a recomputed one.
func (c *Controller) PublishShardingPreview(ctx context.Context, actor *store.AuditEvent, installation, repo, id, headSHA, sourceSHA256 string, check OptimisationPolicyCheck) (*RetainedShardingPreview, error) {
	if actor == nil || actor.ActorID == "" || installation == "" || repo == "" || id == "" || check == nil || !knownHash(headSHA, 40) || !knownHash(sourceSHA256, 64) {
		return nil, ErrOptimisationPublish
	}
	current, err := c.ReplayShardingPreview(ctx, installation, repo, id)
	if err != nil {
		return nil, err
	}
	if current.Preview.HeadSHA != headSHA || current.Preview.SourceSHA256 != sourceSHA256 {
		return nil, ErrOptimisationShardingApproval
	}
	if current.Approval == nil {
		return nil, ErrOptimisationNotApproved
	}
	if current.Approval.HeadSHA != headSHA || current.Approval.SourceSHA256 != sourceSHA256 {
		return nil, ErrOptimisationShardingApproval
	}
	if current.Publication != nil {
		return current, nil
	}
	policy, err := check(ctx)
	if err != nil {
		return nil, err
	}
	if !policy.SourceAllowed || !policy.WorkflowEditsAllowed || !policy.PublishAllowed {
		return nil, ErrOptimisationPublishPolicy
	}
	ctx, cancel := context.WithTimeout(ctx, time.Minute)
	defer cancel()
	fresh, err := c.inspectShardingPreview(ctx, installation, repo, current.Provenance.Selection, current.Provenance.GitHubJobID)
	if err != nil {
		return nil, err
	}
	afterPolicy, err := check(ctx)
	if err != nil {
		return nil, err
	}
	if !afterPolicy.SourceAllowed || !afterPolicy.WorkflowEditsAllowed || !afterPolicy.PublishAllowed {
		return nil, ErrOptimisationPublishPolicy
	}
	if fresh.Source.HeadSHA != current.Preview.HeadSHA || fresh.Source.WorkflowSHA256 != current.Preview.SourceSHA256 || fresh.Source.HeadBranch != current.Provenance.HeadBranch {
		return nil, fmt.Errorf("%w: the run or its branch changed since the sharding preview; preview it again", ErrOptimisationPublish)
	}
	if fresh.Preview.JobName != current.Preview.JobName || fresh.Preview.StepName != current.Preview.StepName || fresh.Preview.Line != current.Preview.Line || fresh.Preview.Edit.Path != current.Preview.Edit.Path || fresh.Preview.File.Mode != current.Preview.File.Mode {
		return nil, fmt.Errorf("%w: the test step no longer matches the sharding preview; preview it again", ErrOptimisationPublish)
	}
	if fresh.Preview.Shards < current.Preview.Shards {
		return nil, fmt.Errorf("%w: the pool or the job's history no longer supports %d shards (it would now choose %d); preview it again", ErrOptimisationPublish, current.Preview.Shards, fresh.Preview.Shards)
	}
	// Re-read the approval and retained record after the source read: a preview
	// that expired or was evicted meanwhile must not be published, and another
	// request may already have opened its draft.
	latest, err := c.ReplayShardingPreview(ctx, installation, repo, id)
	if err != nil {
		return nil, err
	}
	if latest.Preview.HeadSHA != headSHA || latest.Preview.SourceSHA256 != sourceSHA256 || latest.SHA256 != current.SHA256 {
		return nil, ErrOptimisationShardingApproval
	}
	if latest.Approval == nil || latest.Approval.HeadSHA != headSHA || latest.Approval.SourceSHA256 != sourceSHA256 {
		return nil, ErrOptimisationNotApproved
	}
	if latest.Publication != nil {
		return latest, nil
	}
	client, err := c.ClientFor(ctx, installation)
	if err != nil {
		return nil, err
	}
	publisher, ok := client.(github.OptimisationPublisher)
	if !ok {
		return nil, fmt.Errorf("%w: this GitHub client cannot open draft pull requests", ErrOptimisationPublish)
	}
	info, err := client.Probe(ctx)
	if err != nil {
		if errors.Is(err, github.ErrForbidden) {
			return nil, fmt.Errorf("%w: %s", ErrOptimisationPublishPermission, github.OptimisationPublishPermissionHint)
		}
		return nil, fmt.Errorf("%w: %v", ErrOptimisationPublish, err)
	}
	if info == nil {
		return nil, fmt.Errorf("%w: GitHub did not report the App's permissions", ErrOptimisationPublish)
	}
	if missing := info.MissingForMigration(); len(missing) > 0 {
		return nil, fmt.Errorf("%w: %s; %s", ErrOptimisationPublishPermission, github.OptimisationPublishPermissionHint, strings.Join(missing, ", "))
	}
	p := latest.Preview
	branch := "zoomies/sharding-" + id
	title := "Shard the " + p.JobName + " Playwright tests in CI"
	body := fmt.Sprintf("This draft was opened from approved Zoomies sharding preview `%s` at commit `%s`.\n\n"+
		"It splits the `%s` step of `%s` into %d Playwright shards using Playwright's own `--shard` flag, so together they run the whole suite. "+
		"A job with the original name stays behind and fails unless every shard passed, so a required check that names the job still resolves.\n\n"+
		"Zoomies chose the count from the job's retained history and the pool's headroom. It costs more runner time, not less: every shard repeats the setup, so a run goes from about %ds to about %ds of runner time, and it needs %d runners at once. "+
		"The wall-clock figure (about %ds to about %ds) is an estimate from medians, verification is inconclusive, and passing CI alone cannot establish an improvement. "+
		"Zoomies will not merge this pull request; review the diff and let the repository's own checks decide.\n\n"+
		"<!-- zoomies-sharding-optimisation:%s -->\n", id, p.HeadSHA, p.StepName, p.JobName, p.Shards,
		p.RunnerMSBefore/1000, p.RunnerMSAfter/1000, p.Shards, p.WallMSBefore/1000, p.WallMSAfter/1000, id)
	commitMessage := "Shard the " + p.JobName + " Playwright tests in CI\n\nZoomies sharding preview " + id
	pr, err := publisher.PublishOptimisation(ctx, github.OptimisationPublishRequest{
		Repo: repo, Base: latest.Provenance.HeadBranch, BaseCommit: p.HeadSHA, Head: branch,
		Title: title, Body: body, CommitMessage: commitMessage, PreviewID: id,
		Path: p.Edit.Path, Mode: p.File.Mode, Content: p.File.Content,
		SourceSHA256: p.SourceSHA256,
	})
	if err != nil {
		if errors.Is(err, github.ErrForbidden) {
			return nil, fmt.Errorf("%w: %s", ErrOptimisationPublishPermission, github.OptimisationPublishPermissionHint)
		}
		return nil, fmt.Errorf("%w: %w", ErrOptimisationPublish, err)
	}
	if pr == nil || pr.Number <= 0 || pr.HTMLURL == "" || pr.Branch != branch {
		return nil, fmt.Errorf("%w: GitHub did not return a usable draft pull request", ErrOptimisationPublish)
	}
	record := &store.OptimisationShardingPublication{
		PreviewID: id, InstallationID: installation, Repository: repo, PublishedBy: actor.ActorID,
		Branch: pr.Branch, BaseBranch: latest.Provenance.HeadBranch, BaseSHA: p.HeadSHA, HeadSHA: p.HeadSHA,
		SourceSHA256: p.SourceSHA256, PreviewSHA256: latest.SHA256,
		PullNumber: pr.Number, PullURL: pr.HTMLURL,
	}
	if err := c.st.PutOptimisationShardingPublication(ctx, record, actor); err != nil {
		c.log.Error("recording a sharding publication", "error", err, "preview", id, "pull_request", pr.Number)
		return nil, fmt.Errorf("%w: the draft pull request #%d was opened, but its record could not be saved; press publish again to reconcile it", ErrOptimisationPublish, pr.Number)
	}
	latest.Publication = &RetainedShardingPublication{
		PublishedBy: record.PublishedBy, PublishedAt: record.CreatedAt, Branch: record.Branch, BaseBranch: record.BaseBranch,
		BaseSHA: record.BaseSHA, HeadSHA: record.HeadSHA, SourceSHA256: record.SourceSHA256, PreviewSHA256: record.PreviewSHA256,
		PullNumber: record.PullNumber, PullURL: record.PullURL,
	}
	return latest, nil
}

package controller

import (
	"bytes"
	"context"
	"encoding/json"
	"io"
	"time"

	"github.com/eyupio/zoomies/internal/aicontext"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/optimisation"
	"github.com/eyupio/zoomies/internal/prrepair"
	"github.com/eyupio/zoomies/internal/store"
)

type optimisationShardingRetainedProvenance struct {
	SelectionRunID   int64  `json:"selection_run_id"`
	SelectionAttempt int    `json:"selection_attempt"`
	GitHubJobID      int64  `json:"github_job_id"`
	HeadBranch       string `json:"head_branch"`
}

type optimisationShardingRetainedSource struct {
	HeadSHA string `json:"head_sha"`
	Path    string `json:"path"`
	Mode    string `json:"mode"`
	Content string `json:"content"`
}

type optimisationShardingRetainedEnvelope struct {
	Version        string                                 `json:"version"`
	ID             string                                 `json:"id"`
	InstallationID string                                 `json:"installation_id"`
	Repository     string                                 `json:"repository"`
	ReviewedBy     string                                 `json:"reviewed_by"`
	ModelFunding   string                                 `json:"model_funding"`
	Provenance     optimisationShardingRetainedProvenance `json:"provenance"`
	Source         optimisationShardingRetainedSource     `json:"source"`
	Evidence       optimisation.ShardEvidence             `json:"evidence"`
	Samples        []optimisation.ShardSample             `json:"samples"`
	Preview        optimisation.ShardPreview              `json:"preview"`
}

// RetainedShardingPreview is a kept sharding preview. The full source stays in
// the private envelope; a transport renders the edit, metadata and evidence
// summary only.
type RetainedShardingPreview struct {
	ID             string
	InstallationID string
	Repository     string
	ReviewedBy     string
	SHA256         string
	CreatedAt      time.Time
	Currentness    string
	Preview        optimisation.ShardPreview
	Provenance     ShardingProvenance
	Approval       *RetainedShardingApproval
	Publication    *RetainedShardingPublication
}

// RetainedShardingApproval is one attributed decision about the exact retained
// sharding preview. It is not a publication and expires with the preview.
type RetainedShardingApproval struct {
	ApprovedBy    string
	ApprovedAt    time.Time
	HeadSHA       string
	SourceSHA256  string
	PreviewSHA256 string
}

// ShardingProvenance is the selected fleet job and branch a kept preview was
// bound to. Every sharding preview records it, so every one can be rechecked
// before anything is published.
type ShardingProvenance struct {
	Selection   github.SetupCacheSelection
	GitHubJobID int64
	HeadBranch  string
}

// CaptureShardingPreview re-reads the source and history, requires the same
// head, workflow digest and shard count the operator reviewed, and keeps an
// immutable private preview for fourteen days. The count is part of what was
// reviewed: the pool's headroom can move between the inspection and the keep,
// and a different number of shards is a different change.
func (c *Controller) CaptureShardingPreview(ctx context.Context, actor *store.AuditEvent, installation, repo string, selection github.SetupCacheSelection, githubJobID int64, headSHA, sourceSHA256 string, shards int) (*RetainedShardingPreview, error) {
	if actor == nil || actor.ActorID == "" || !knownHash(headSHA, 40) || !knownHash(sourceSHA256, 64) || shards < optimisation.MinShards || shards > optimisation.MaxShards {
		return nil, ErrOptimisationSharding
	}
	inspection, err := c.inspectShardingPreview(ctx, installation, repo, selection, githubJobID)
	if err != nil {
		return nil, err
	}
	if inspection.Source.HeadSHA != headSHA || inspection.Source.WorkflowSHA256 != sourceSHA256 || inspection.Preview.Shards != shards {
		return nil, ErrOptimisationSharding
	}
	envelope := optimisationShardingRetainedEnvelope{
		Version: store.OptimisationShardingPreviewVersion, ID: store.NewID(store.PrefixOptimisationShardingPreview),
		InstallationID: installation, Repository: repo, ReviewedBy: actor.ActorID, ModelFunding: "no_model_call",
		Provenance: optimisationShardingRetainedProvenance{SelectionRunID: selection.RunID, SelectionAttempt: selection.Attempt, GitHubJobID: githubJobID, HeadBranch: inspection.Source.HeadBranch},
		Source:     optimisationShardingRetainedSource{HeadSHA: inspection.Source.HeadSHA, Path: inspection.Source.Workflow.Path, Mode: inspection.Source.Workflow.Mode, Content: inspection.Source.Workflow.Content},
		Evidence:   inspection.Evidence, Samples: inspection.Samples, Preview: inspection.Preview,
	}
	payload, err := json.Marshal(envelope)
	if err != nil {
		return nil, err
	}
	if len(payload) > store.MaxOptimisationShardingPreviewBytes {
		return nil, ErrOptimisationSharding
	}
	row := &store.OptimisationShardingPreview{ID: envelope.ID, InstallationID: installation, Repository: repo, InitiatingUser: actor.ActorID, Version: envelope.Version, Payload: payload}
	if err := c.st.PutOptimisationShardingPreview(ctx, row, actor); err != nil {
		return nil, err
	}
	return retainedShardingView(row, inspection.Preview, envelope.Provenance), nil
}

// ReplayShardingPreview validates historical calculation, not the current head
// or policy. It never reads replacement source. The pool's headroom cannot be
// derived from the samples, so the stored figure is taken as given and the rest
// of the evidence, and the whole preview, are recomputed from it and compared.
func (c *Controller) ReplayShardingPreview(ctx context.Context, installation, repo, id string) (*RetainedShardingPreview, error) {
	row, err := c.st.GetOptimisationShardingPreview(ctx, installation, repo, id)
	if err != nil {
		return nil, err
	}
	var e optimisationShardingRetainedEnvelope
	dec := json.NewDecoder(bytes.NewReader(row.Payload))
	dec.DisallowUnknownFields()
	if dec.Decode(&e) != nil || dec.Decode(new(any)) != io.EOF || row.Version != store.OptimisationShardingPreviewVersion || e.Version != row.Version || e.ID != row.ID || e.InstallationID != row.InstallationID || e.Repository != row.Repository || e.ReviewedBy != row.InitiatingUser || e.ModelFunding != "no_model_call" {
		return nil, ErrOptimisationSharding
	}
	if p := e.Provenance; p.SelectionRunID <= 0 || p.SelectionAttempt <= 0 || p.GitHubJobID <= 0 || !aicontext.ValidBranch(p.HeadBranch) {
		return nil, ErrOptimisationSharding
	}
	evidence, err := optimisation.ShardEvidenceFromSamples(e.Source.HeadSHA, hashString(e.Source.Content), e.Evidence.Headroom, e.Samples)
	if err != nil {
		return nil, ErrOptimisationSharding
	}
	oldEvidence, _ := json.Marshal(e.Evidence)
	newEvidence, _ := json.Marshal(evidence)
	if !bytes.Equal(oldEvidence, newEvidence) {
		return nil, ErrOptimisationSharding
	}
	source := optimisation.ShardSource{HeadSHA: e.Source.HeadSHA, Workflow: prrepair.File{Path: e.Source.Path, Mode: e.Source.Mode, Content: e.Source.Content}}
	preview, err := optimisation.PreviewSharding(source, evidence, optimisation.Policy{SourceAllowed: true, WorkflowEditsAllowed: true})
	if err != nil {
		return nil, ErrOptimisationSharding
	}
	oldPreview, _ := json.Marshal(e.Preview)
	newPreview, _ := json.Marshal(preview)
	if !bytes.Equal(oldPreview, newPreview) {
		return nil, ErrOptimisationSharding
	}
	return retainedShardingView(row, preview, e.Provenance), nil
}

func retainedShardingView(row *store.OptimisationShardingPreview, preview optimisation.ShardPreview, p optimisationShardingRetainedProvenance) *RetainedShardingPreview {
	v := &RetainedShardingPreview{
		ID: row.ID, InstallationID: row.InstallationID, Repository: row.Repository, ReviewedBy: row.InitiatingUser, SHA256: row.SHA256, CreatedAt: row.CreatedAt, Currentness: "not_checked", Preview: preview,
		Provenance: ShardingProvenance{Selection: github.SetupCacheSelection{RunID: p.SelectionRunID, Attempt: p.SelectionAttempt}, GitHubJobID: p.GitHubJobID, HeadBranch: p.HeadBranch},
	}
	if a := row.Approval; a != nil {
		v.Approval = &RetainedShardingApproval{ApprovedBy: a.ApprovedBy, ApprovedAt: a.CreatedAt, HeadSHA: a.HeadSHA, SourceSHA256: a.SourceSHA256, PreviewSHA256: a.PreviewSHA256}
	}
	if p := row.Publication; p != nil {
		v.Publication = &RetainedShardingPublication{PublishedBy: p.PublishedBy, PublishedAt: p.CreatedAt, Branch: p.Branch, BaseBranch: p.BaseBranch, BaseSHA: p.BaseSHA, HeadSHA: p.HeadSHA, SourceSHA256: p.SourceSHA256, PreviewSHA256: p.PreviewSHA256, PullNumber: p.PullNumber, PullURL: p.PullURL}
	}
	return v
}

// RetainedShardingPublication is the one draft pull request opened for an
// approved sharding preview. It is not a merge and does not claim a saving.
type RetainedShardingPublication struct {
	PublishedBy   string
	PublishedAt   time.Time
	Branch        string
	BaseBranch    string
	BaseSHA       string
	HeadSHA       string
	SourceSHA256  string
	PreviewSHA256 string
	PullNumber    int
	PullURL       string
}

// ApproveShardingPreview records an operator's explicit approval of the exact
// retained sharding preview they name. It reads no source and calls no GitHub
// reader, so an approval cannot publish, edit a workflow or start a job.
func (c *Controller) ApproveShardingPreview(ctx context.Context, actor *store.AuditEvent, installation, repo, id, headSHA, sourceSHA256 string) (*RetainedShardingPreview, error) {
	if actor == nil || actor.ActorID == "" || installation == "" || repo == "" || id == "" || !knownHash(headSHA, 40) || !knownHash(sourceSHA256, 64) {
		return nil, ErrOptimisationShardingApproval
	}
	current, err := c.ReplayShardingPreview(ctx, installation, repo, id)
	if err != nil {
		return nil, err
	}
	if current.Preview.HeadSHA != headSHA || current.Preview.SourceSHA256 != sourceSHA256 {
		return nil, ErrOptimisationShardingApproval
	}
	approval, err := c.st.ApproveOptimisationShardingPreview(ctx, installation, repo, id, headSHA, sourceSHA256, current.SHA256, actor)
	if err != nil {
		return nil, err
	}
	current.Approval = &RetainedShardingApproval{ApprovedBy: approval.ApprovedBy, ApprovedAt: approval.CreatedAt, HeadSHA: approval.HeadSHA, SourceSHA256: approval.SourceSHA256, PreviewSHA256: approval.PreviewSHA256}
	return current, nil
}

package controller

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/kennel/workflow"
	"github.com/eyupio/zoomies/internal/optimisation"
	"github.com/eyupio/zoomies/internal/prrepair"
	"github.com/eyupio/zoomies/internal/store"
)

const shardingControllerWorkflow = "on: push\njobs:\n  e2e:\n    name: End to end\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@" + "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa" + "\n      - name: Browser tests\n        run: npx playwright test\n"

// shardControllerFixture is a fleet that ran the same job runs times: two
// seconds to set up the job, forty to install, six minutes of browser tests.
func shardControllerFixture(t *testing.T, runs int) (*harness, *store.Installation, *cacheSourceReader, github.SetupCacheSelection, int64) {
	t.Helper()
	h, inst, _ := experimentJoinFixture(t)
	now := h.c.Now().UTC()
	file := prrepair.File{Path: ".github/workflows/ci.yml", Mode: "100644", Content: shardingControllerWorkflow}
	source := &github.ShardSource{
		Version: "shard-evidence-v1", Basis: "push_head_root_workflow_literal_names", Repository: inst.Target,
		RunID: "10", Attempt: 2, HeadSHA: strings.Repeat("a", 40), HeadBranch: "main",
		WorkflowPath: file.Path, Workflow: file, WorkflowBlobSHA: cacheBlobSHA(file.Content), WorkflowSHA256: cacheSHA256(file.Content),
		JobIndex: 0, StepIndex: 1, JobName: "End to end", StepName: "Browser tests",
	}
	steps := func() store.JobSteps {
		begin := now.Add(-402 * time.Second)
		return store.JobSteps{
			{Number: 1, Name: "Set up job", Status: "completed", Conclusion: "success", StartedAt: &begin, CompletedAt: ptr(begin.Add(2 * time.Second))},
			{Number: 2, Name: "Install", Status: "completed", Conclusion: "success", StartedAt: ptr(begin.Add(2 * time.Second)), CompletedAt: ptr(begin.Add(42 * time.Second))},
			{Number: 3, Name: "Browser tests", Status: "completed", Conclusion: "success", StartedAt: ptr(begin.Add(42 * time.Second)), CompletedAt: ptr(begin.Add(402 * time.Second))},
		}
	}
	for i := 0; i < runs; i++ {
		id := int64(100 + i)
		run := int64(10)
		attempt := 2
		if i > 0 {
			run, attempt = int64(10+i), 1
		}
		if _, err := h.st.UpsertJob(h.ctx, &store.Job{GitHubJobID: id, GitHubRunID: run, Repo: inst.Target, Workflow: "CI", JobName: "End to end", Labels: store.StringSlice{"ubuntu-latest"},
			State: store.JobCompleted, Conclusion: "success", InstallationID: inst.ID, HeadBranch: "main", HeadSHA: source.HeadSHA, RunAttempt: attempt,
			QueuedAt: now.Add(-10 * time.Minute), CompletedAt: &now, Steps: steps()}); err != nil {
			t.Fatal(err)
		}
	}
	reader := &cacheSourceReader{Client: h.gh.Client(inst.Target, inst.TargetType), shardSource: source, quota: &github.RateLimit{Limit: 5000, Remaining: 5000, ResetAt: now.Add(time.Hour)}}
	h.c.clients.entries[inst.ID] = &clientEntry{client: reader, updatedAt: inst.UpdatedAt.Truncate(time.Millisecond)}
	h.c.UpdateConfig(func(c *config.Config) { c.Optimisation.SourceReads, c.Optimisation.WorkflowEdits = true, true })
	h.pool(inst, "browsers", "self-hosted", "linux", "ubuntu-latest")
	h.host("browser-host")
	return h, inst, reader, github.SetupCacheSelection{RunID: 10, Attempt: 2}, 100
}

func TestInspectShardingPreviewSizesTheShardsFromTheFleetsOwnHistoryAndHeadroom(t *testing.T) {
	h, inst, reader, selection, jobID := shardControllerFixture(t, 12)
	inspection, err := h.c.inspectShardingPreview(h.ctx, inst.ID, inst.Target, selection, jobID)
	if err != nil {
		t.Fatal(err)
	}
	p, e := inspection.Preview, inspection.Evidence
	if e.Runs != 12 || e.TestMS != 360_000 || e.SetupMS != 42_000 || e.Headroom != 4 || len(inspection.Samples) != 12 {
		t.Fatalf("evidence %+v", e)
	}
	// Four shards at 90s each is the most the floor allows, and the pool has room for four.
	if p.Shards != 4 || p.JobName != "End to end" || p.StepName != "Browser tests" || p.Verification != "inconclusive" || !strings.Contains(p.Edit.After, "--shard=${{ matrix.shard }}/4") {
		t.Fatalf("preview %+v", p)
	}
	if reader.calls != 1 || reader.quotaCalls != 1 {
		t.Fatalf("reads=%d quota=%d", reader.calls, reader.quotaCalls)
	}
	again, err := h.c.inspectShardingPreview(h.ctx, inst.ID, inst.Target, selection, jobID)
	if err != nil || again.Evidence.EvidenceID != e.EvidenceID {
		t.Fatalf("the same history gave a different evidence ID: %v", err)
	}
}

