	if _, err := h.c.PublishOptimisationPreview(h.ctx, actor, inst.ID, inst.Target, saved.ID, saved.Preview.HeadSHA, saved.Preview.SourceSHA256, optimisationPublishCheck(true)); err != nil {
		t.Fatal(err)
	}
	comparison := retainedWorkflowComparison(t, h.c, actor, inst.ID, saved.ID)
	linked, err := h.c.LinkOptimisationVerification(h.ctx, actor, inst.ID, inst.Target, saved.ID, comparison.ID)
	if err != nil {
		t.Fatal(err)
	}
	if linked.Verification == nil || linked.Verification.ComparisonID != comparison.ID || linked.Verification.LinkedBy != actor.ActorID {
		t.Fatalf("verification %+v", linked.Verification)
	}
	replayed, err := h.c.ReplayOptimisationPreview(h.ctx, inst.ID, inst.Target, saved.ID)
	if err != nil || replayed.Verification == nil || replayed.Verification.ComparisonID != comparison.ID {
		t.Fatalf("replay lost the link: %+v, %v", replayed, err)
	}
	if _, total, err := h.st.ListAudit(h.ctx, store.AuditFilter{Actions: []string{"optimisation.comparison_linked"}}, store.Page{Limit: 10}); err != nil || total != 1 {
		t.Fatalf("audit total=%d err=%v", total, err)
	}
	again, err := h.c.LinkOptimisationVerification(h.ctx, actor, inst.ID, inst.Target, saved.ID, comparison.ID)
	if err != nil || again.Verification == nil || !again.Verification.LinkedAt.Equal(linked.Verification.LinkedAt) {
		t.Fatalf("repeat %+v, %v", again, err)
	}
}

func TestOptimisationVerificationRefusesAnUnpublishedPreviewOrAnUnrelatedComparison(t *testing.T) {
	h, inst, f, sel, review, actor := checkoutCaptureFixture(t)
	saved, err := h.c.CaptureOptimisationPreview(h.ctx, actor, inst.ID, inst.Target, sel, review, optimisationPublishCheck(true))
	if err != nil {
		t.Fatal(err)
	}
	comparison := retainedWorkflowComparison(t, h.c, actor, inst.ID, saved.ID)
	if _, err := h.c.LinkOptimisationVerification(h.ctx, actor, inst.ID, inst.Target, saved.ID, comparison.ID); !errors.Is(err, ErrOptimisationVerification) {
		t.Fatalf("unpublished preview: %v", err)
	}
	if _, err := h.c.ApproveOptimisationPreview(h.ctx, actor, inst.ID, inst.Target, saved.ID, saved.Preview.HeadSHA, saved.Preview.SourceSHA256); err != nil {
		t.Fatal(err)
	}
	f.publishPR = &github.PullRequest{Number: 12, HTMLURL: "https://github.com/acme/repo/pull/12", Branch: "zoomies/checkout-" + saved.ID}
	if _, err := h.c.PublishOptimisationPreview(h.ctx, actor, inst.ID, inst.Target, saved.ID, saved.Preview.HeadSHA, saved.Preview.SourceSHA256, optimisationPublishCheck(true)); err != nil {
		t.Fatal(err)
	}
	record, a, b := experimentSnapshotFixture()
	record.Kind = "workflow"
	record.RevisionDeltaID = "other-preview"
	a.InstallationID, b.InstallationID = inst.ID, inst.ID
	unrelated, err := h.c.RetainExperimentComparison(h.ctx, actor, record, a, b)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := h.c.LinkOptimisationVerification(h.ctx, actor, inst.ID, inst.Target, saved.ID, unrelated.ID); !errors.Is(err, ErrOptimisationVerification) || !strings.Contains(err.Error(), "does not name this preview") {
		t.Fatalf("unrelated comparison: %v", err)
	}
	record, a, b = experimentSnapshotFixture()
	record.Kind = "runner"
	record.RevisionDeltaID = saved.ID
	a.InstallationID, b.InstallationID = inst.ID, inst.ID
	runnerComparison, err := h.c.RetainExperimentComparison(h.ctx, actor, record, a, b)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := h.c.LinkOptimisationVerification(h.ctx, actor, inst.ID, inst.Target, saved.ID, runnerComparison.ID); !errors.Is(err, ErrOptimisationVerification) || !strings.Contains(err.Error(), "workflow comparison") {
		t.Fatalf("runner comparison: %v", err)
	}
}

package controller

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// host.overprovisioned judges a slot against a core and 2 GB because that is
// what a runner nobody sized needs to do real work. A pool whose operator set
// a minimum below that has been sized: its runners are accepted at the
// minimum, and a host whose slots each cover it is a host the pool runs on as
// configured. Calling it too small -- the report this test exists for -- sends
// the operator to lower a capacity the fleet is using. The warning stays
// wherever any pool that reaches the host has no such minimum, because that
// pool's runners still get a slot too thin to work in.
func TestAHostWhoseSlotsCoverEveryPoolsMinimumIsNotOverprovisioned(t *testing.T) {
	small := store.Resources{CPUs: 1, MemoryMB: 2048, MinCPUs: 0.5, MinMemoryMB: 1024}
	tests := []struct {
		name  string
		pools []store.Resources
		warn  bool
	}{
		{"with no pool the default judgement stands", nil, true},
		{"a pool with a minimum the slots cover raises nothing", []store.Resources{small}, false},
		{"a pool without a minimum beside it keeps the warning", []store.Resources{small, {CPUs: 1, MemoryMB: 2048}}, true},
		{"a minimum above the slot share keeps the warning", []store.Resources{{CPUs: 1, MemoryMB: 2048, MinMemoryMB: 1536}}, true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			// Two cores less the reserve and 4 GB less the reserve: one slot
			// at a core and 2 GB, three at half a core and 1 GB.
			h.measuredHost("small", 2, 4096, 3, enforcesEverything)
			inst := h.installation()
			for i, r := range tc.pools {
				p := h.pool(inst, "pool-"+string(rune('a'+i)))
				p.Resources = r
				if err := h.st.UpdatePool(h.ctx, p); err != nil {
					t.Fatal(err)
				}
			}
			got := contains(h.problemCodes(), "host.overprovisioned")
			if got != tc.warn {
				t.Errorf("host.overprovisioned raised = %v, want %v", got, tc.warn)
			}
			if tc.warn && len(tc.pools) > 0 {
				p := h.problem(t, "host.overprovisioned")
				if strings.Contains(p.Fix, "capacity to 3") {
					t.Errorf("fix %q names the capacity the host already has", p.Fix)
				}
			}
		})
	}
}

package controller

import (
	"context"
	"fmt"
	"sort"
	"strings"

	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// PairingView is one provider and one pool, and whether the provider would
// rent a machine for it.
//
// A pool uses a provider only when three things are true, and an operator
// looking at an empty Machines list needs to know which one is not. The two
// selectors are the opt-in each side gives (the provider's pool_selector, the
// pool's provider_selector); the third is that the machine the provider builds
// is one the pool's runners could be placed on at all. They are reported apart
// because the first two are choices somebody made and the third is a mismatch
// of shape.
type PairingView struct {
	ProviderID   string `json:"provider_id"`
	ProviderName string `json:"provider_name"`
	PoolID       string `json:"pool_id"`
	PoolName     string `json:"pool_name"`
	// Serves is the answer: this provider would rent a machine for this pool.
	Serves bool `json:"serves"`
	// Agrees is whether the two selectors allow it. By says which side refused,
	// "provider" or "pool", and Why and Fix say what did not match and what to
	// change.
	Agrees bool   `json:"agrees"`
	By     string `json:"by,omitempty"`
	// Fits is whether the machine the provider would build suits the pool.
	// FitWhy is the first thing that does not, in the setting's own terms.
	Fits   bool   `json:"fits"`
	FitWhy string `json:"fit_why,omitempty"`
	Why    string `json:"why,omitempty"`
	Fix    string `json:"fix,omitempty"`
}

// ProviderPairings answers, for every provider and pool, whether the provider
// would rent for the pool and, if not, whose setting says so. It asks the same
// rules the machine decision does (scheduler.Pair and scheduler.HostCouldRun),
// so the page that explains a pairing and the pass that acts on it cannot
// disagree.
func (c *Controller) ProviderPairings(ctx context.Context) ([]PairingView, error) {
	providers, err := c.st.ListProviders(ctx)
	if err != nil {
		return nil, fmt.Errorf("listing providers: %w", err)
	}
	pools, err := c.st.ListPools(ctx)
	if err != nil {
		return nil, fmt.Errorf("listing pools: %w", err)
	}
	now := c.Now()
	out := make([]PairingView, 0, len(providers)*len(pools))
	for _, p := range providers {
		synth := providerSynthHost(p, now)
		for _, pool := range pools {
			pair := scheduler.Pair(p, pool)
			misfit := machineFit(p, synth, pool)
			v := PairingView{
				ProviderID: p.ID, ProviderName: p.Name, PoolID: pool.ID, PoolName: pool.Name,
				Agrees: pair.Agrees, By: pair.By, Fits: misfit.Why == "", FitWhy: misfit.Why,
			}
			v.Serves = v.Agrees && v.Fits
			switch {
			case !pair.Agrees:
				v.Why, v.Fix = sentence(pair.Why), sentence(pair.Fix)
			case misfit.Why != "":
				v.Why, v.Fix = misfit.Why, misfit.Fix
			}
			out = append(out, v)
		}
	}
	sort.SliceStable(out, func(i, j int) bool {
		if out[i].PoolName != out[j].PoolName {
			return out[i].PoolName < out[j].PoolName
		}
		return out[i].ProviderName < out[j].ProviderName
	})
	return out, nil
}

// machineMisfit is why the machine a provider would build could not run a
// pool's runners, in the setting's own terms. Fix is set where there is one
// thing to change that the sentence can name, and Size says the machine is the
// right kind and too small, which is the one mismatch a ceiling sits on top of:
// a provider whose machines are too small fills its maximum with machines that
// never run a job, and the fix that ceiling would otherwise suggest buys more.
type machineMisfit struct {
	Why  string
	Fix  string
	Size bool
}

// machineFit says why the machine a provider would build could not run a
// pool's runners, or returns a zero misfit when it could. It reads the same
// four tests as scheduler.HostCouldRun, in its order, and names the first that
// fails.
//
// The size test is placement's own (scheduler.HostFits), asked of a machine of
// the size the provider builds: the host reserve, the slot share and a
// docker-in-docker runner's split with its daemon are all in it. A provider
// whose size nothing has said is judged as a host that measured nothing, which
// fits by slots alone, exactly as such a host is placed on.
func machineFit(p *store.Provider, machine *store.Host, pool *store.Pool) machineMisfit {
	switch {
	case !scheduler.HostOffers(machine, pool):
		return machineMisfit{Why: fmt.Sprintf("The machines it builds run %s, and this pool needs %s.",
			strings.Join(machine.Backends, ", "), pool.Backend)}
	case !scheduler.HostIsPlatform(machine, pool):
		return machineMisfit{Why: "The machines it builds are not the operating system or architecture this pool asks for."}
	case !scheduler.HostSelects(machine, pool):
		return machineMisfit{Why: "The machine labels it gives its machines do not satisfy this pool's host selector."}
	case !scheduler.HostFits(machine, pool):
		why := "A machine it builds is too small for one of this pool's runners"
		if size := machineSizeSaid(p); size != "" {
			why += ": " + size
		}
		if short := scheduler.HostShortfall(machine, pool); short != "" {
			why += "; " + short
		}
		return machineMisfit{Why: sentence(why), Fix: machineSizeFix(p, machine, pool), Size: true}
	}
	return machineMisfit{}
}

// machineSizeSaid is where the size a provider's machine is judged at came
// from, so a sentence that says the machine is too small also says which
// figure to go and change: a size typed on the provider, the template's, or
// what a machine it built measured itself as.
func machineSizeSaid(p *store.Provider) string {
	cpus, memoryMB := providerMachineSize(p)
	diskMB := providerMachineDisk(p)
	if cpus <= 0 && memoryMB <= 0 && diskMB <= 0 {
		return ""
	}
	size := machineSize(cpus, memoryMB, diskMB)
	switch {
	case p.MachineCPUs > 0 || p.MachineMemoryMB > 0 || p.MachineDiskMB > 0:
		return "its machine size is " + size
	case p.SeenFrom == store.MachineSizeFromMachine:
		return "its machines measure " + size + " once they join"
	case p.SeenFrom == store.MachineSizeFromTemplate:
		return "the template it clones gives " + size
	}
	return "its machines have " + size
}

// machineSizeFix is what to change about a provider whose machines are too
// small for a pool: the size they would have to be, found by asking placement
// itself (scheduler.MachineFor), and where that size is set. Its other half is
// the pool's, because a minimum somebody set is as much the size as the
// machine is.
//
// It never says to raise the provider's maximum machines. Every machine it
// would buy is the one that is too small.
func machineSizeFix(p *store.Provider, machine *store.Host, pool *store.Pool) string {
	need, ok := scheduler.MachineFor(machine, pool)
	if !ok {
		where := "set its machine size, or enlarge the template it clones"
		if p.MachineCPUs > 0 || p.MachineMemoryMB > 0 || p.MachineDiskMB > 0 {
			where = "raise its machine size"
		}
		return fmt.Sprintf("Give %s's machines a larger size (%s), or lower this pool's minimum runner size.", p.Name, where)
	}
	// The template's half of the sentence names what it has to give, so an
	// operator short only of disk is not sent to add processors as well.
	var more []string
	if need.CPUs > 0 || need.MemoryMB > 0 {
		more = append(more, "processors", "memory")
	}
	if need.DiskMB > 0 {
		more = append(more, "disk")
	}
	where := "set its machine size, or give the template it clones more " + andList(more)
	if p.MachineCPUs > 0 || p.MachineMemoryMB > 0 || p.MachineDiskMB > 0 {
		where = "raise its machine size"
	}
	size := machineSize(need.CPUs, need.MemoryMB, need.DiskMB)
	return fmt.Sprintf("Give %s's machines at least %s (%s), or lower this pool's minimum runner size.", p.Name, size, where)
}

// andList joins words the way a sentence does: "a", "a and b", "a, b and c".
func andList(words []string) string {
	switch len(words) {
	case 0:
		return ""
	case 1:
		return words[0]
	}
	return strings.Join(words[:len(words)-1], ", ") + " and " + words[len(words)-1]
}

// machineSize writes a machine's processors, memory and disk as an operator
// would order them, leaving out a field nothing said.
func machineSize(cpus int, memoryMB, diskMB int64) string {
	var parts []string
	if cpus > 0 {
		parts = append(parts, plural(cpus, "CPU"))
	}
	if memoryMB > 0 {
		parts = append(parts, scheduler.FormatMB(memoryMB)+" of memory")
	}
	if diskMB > 0 {
		parts = append(parts, scheduler.FormatMB(diskMB)+" of disk")
	}
	return andList(parts)
}

// sentence makes a finding's clause into one an operator reads on a page: the
// scheduler writes them to continue a log line, which starts lower-case and
// ends without a stop.
func sentence(s string) string {
	if s == "" {
		return s
	}
	s = strings.ToUpper(s[:1]) + s[1:]
	if !strings.HasSuffix(s, ".") {
		s += "."
	}
	return s
}

package controller

import (
	"context"
	"fmt"
	"math"
	"slices"
	"sort"
	"strings"

	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
	"time"
)

// A docker-in-docker runner is two containers dividing one slot, and the right
// division is a fact about the jobs, not the machine: a pool whose builds all
// run in the daemon wants most of the slot there, and one that compiles in the
// runner wants the opposite. Nothing on the host can tell which -- only what
// each container actually used can -- so the controller keeps a window of that
// per pool and says when the division is visibly wrong. It only says: the
// split is a pool setting (resources.daemon_share_percent), and an operator,
// who knows what the pool is for, makes the change.

const (
	// pairWindow is how far back a pool's samples count. A day's jobs would hide
	// a change of workload; an hour could be one unusual build.
	pairWindow = 6 * time.Hour
	// pairMaxSamples bounds the window per pool. A busy runner is sampled every 30
	// seconds, so this holds six hours of about eleven busy runners, and a pool with
	// more has a shorter window and its newest samples; the bound keeps a busy
	// fleet's memory flat.
	pairMaxSamples = 8000
	// pairMinSamples and pairMinRunners keep one long job from speaking for a
	// pool: its samples are all the same job, and a pool's advice should rest on
	// several.
	pairMinSamples = 60
	pairMinRunners = 3
	// pairMinSpan and pairMaxRunnerShare are the same idea in time and in share: a
	// pool just restarted has sixty samples from three runners within minutes, all of
	// them the first phase of their jobs, and one long job with stragglers can be
	// most of a window. The count is a floor and these are what make it a pool's
	// evidence -- an hour "could be one unusual build", and half an hour is the
	// least that is not.
	pairMinSpan        = 30 * time.Minute
	pairMaxRunnerShare = 0.5
	// pairHot is a container's use of its own limit, at its 95th percentile,
	// above which it is the one being squeezed; pairIdle is the most the other
	// may use for the squeeze to be the division's fault rather than the job's.
	pairHot  = 0.85
	pairIdle = 0.50
	// pairHeadroom is what a container is proposed above what it used, so a
	// proposal is not a limit the job would sit exactly at.
	pairHeadroom = 1.25
	// pairMinMove is the least change worth proposing, in percentage points.
	pairMinMove = 10
)

// pairSample is one heartbeat of one busy pair.
type pairSample struct {
	at time.Time
	// sampled is when the agent took the sample, which is how a sample that reaches
	// the controller twice is told from two.
	sampled time.Time
	runner  string
	halves  backend.PairHalves
}

// observePair records a busy runner's two halves. Only a runner sized from the
// host counts, by its share or by its profile's standard size: a typed limit
// goes to both containers in full, so there is no division to judge.
func (c *Controller) observePair(r *store.Runner, st backend.Stats) {
	if st.Halves == nil || !store.SizedByHost(r.AllocationSource) || st.SampledAt == nil {
		return
	}
	h := *st.Halves
	if !(h.Runner.CPULimit > 0 || h.Runner.MemoryLimit > 0) || !(h.Daemon.CPULimit > 0 || h.Daemon.MemoryLimit > 0) {
		return
	}
	now := c.Now()
	c.pairMu.Lock()
	defer c.pairMu.Unlock()
	if c.pairs == nil {
		c.pairs = make(map[string][]pairSample)
	}
	// The agent sends its last sample with the heartbeat and again with each
	// reconcile report, and keeps sending it when the next one fails, so the same
	// reading arrives more than once. Counting each arrival would make 60 samples
	// half an hour of one runner and let a stale reading speak for the pool.
	for i := len(c.pairs[r.PoolID]) - 1; i >= 0; i-- {
		if prev := c.pairs[r.PoolID][i]; prev.runner == r.ID {
			if prev.sampled.Equal(*st.SampledAt) {
				return
			}
			break
		}
	}
	w := append(c.pairs[r.PoolID], pairSample{at: now, sampled: *st.SampledAt, runner: r.ID, halves: h})
	cut := 0
	for cut < len(w) && now.Sub(w[cut].at) > pairWindow {
		cut++
	}
	w = w[cut:]
	if len(w) > pairMaxSamples {
		w = w[len(w)-pairMaxSamples:]
	}
	c.pairs[r.PoolID] = w
}

// resourceAdvice is a proposed division of one resource, CPU or memory, and the
// evidence for it. The two are judged apart because they are split apart: a pool
// whose builds are CPU in the daemon while its runner holds the memory has a
// daemon short of CPU and a runner short of memory, and one share cannot say it.
type resourceAdvice struct {
	Resource                string
	Current, Proposed       int
	DaemonHot               bool
	HotPercent, IdlePercent float64
	// HotUse and OtherUse are the 95th percentile use of the squeezed container and
	// of the one beside it, in bytes for memory and cores for CPU: what a proposed
	// share is checked against once it is turned into the limits it would give.
	HotUse, OtherUse float64
	// Held is set when no share worth proposing keeps every runner the pool's
	// hosts hold now, or gives the squeezed container more where it counts: the
	// figure the use points at, and what it would leave.
	Held *shareCost
}

// shareCost is what a share the use points at would cost the pool on its hosts.
type shareCost struct {
	Wanted, Runners, RunnersNow int
	// Pinned is set when the share is not what limits the squeezed container: the
	// thinner half of a slot is held to the pool's smallest runner, so on a host
	// where that decides the slot every share gives it the same, and the share
	// would only take from the half beside it.
	Pinned bool
}

// pairAdvice is what the window shows about how a slot is divided: a proposal
// for each resource it found wrong, and what it rested on.
type pairAdvice struct {
	CPU, Memory      *resourceAdvice
	Samples, Runners int
	// Span is the time the judged samples cover, which is what the notice says
	// rather than the window it could have had.
	Span time.Duration
}

// pairPercentile is the p-th (0..1) value of xs, which it sorts.
func pairPercentile(xs []float64, p float64) float64 {
	if len(xs) == 0 {
		return 0
	}
	sort.Float64s(xs)
	return xs[min(int(math.Ceil(p*float64(len(xs))))-1, len(xs)-1)]
}

// pairCover is how much of a pool a set of samples covers: how many there are, how
// many runners they came from and how much of the time between the first and the
// last. Both detectors that rest on the window ask the same question of it.
type pairCover struct {
	n           int
	perRunner   map[string]int
	first, last time.Time
}

func (c *pairCover) add(s pairSample) {
	if c.perRunner == nil {
		c.perRunner = map[string]int{}
	}
	c.n++
	c.perRunner[s.runner]++
	if c.first.IsZero() || s.sampled.Before(c.first) {
		c.first = s.sampled
	}
	if s.sampled.After(c.last) {
		c.last = s.sampled
	}
}

func (c *pairCover) span() time.Duration { return c.last.Sub(c.first) }

// enough says whether the samples are a pool's evidence rather than one job's.
func (c *pairCover) enough() bool {
	if c.n < pairMinSamples || len(c.perRunner) < pairMinRunners || c.span() < pairMinSpan {
		return false
	}
	most := 0
	for _, n := range c.perRunner {
		most = max(most, n)
	}
	return float64(most) <= pairMaxRunnerShare*float64(c.n)
}

// pairCPUShare and pairMemShare are the share of the slot the daemon was created
// with, as a whole percent, read from the two limits the sample carries. Zero is
// "not divided": a limit that was not set has no share to judge.
func pairCPUShare(s pairSample) int {
	d, r := s.halves.Daemon.CPULimit, s.halves.Runner.CPULimit
	if d > 0 && r > 0 {
		return int(math.Round(100 * d / (d + r)))
	}
	return 0
}

func pairMemShare(s pairSample) int {
	d, r := float64(s.halves.Daemon.MemoryLimit), float64(s.halves.Runner.MemoryLimit)
	if d > 0 && r > 0 {
		return int(math.Round(100 * d / (d + r)))
	}
	return 0
}

// freshPairs is the samples still inside the window. The window is trimmed when a
// pool's runner reports, so a pool that has gone quiet keeps its last six hours
// until something reads them with the clock in hand.
func freshPairs(window []pairSample, now time.Time) []pairSample {
	cut := 0
	for cut < len(window) && now.Sub(window[cut].at) > pairWindow {
		cut++
	}
	return window[cut:]
}

// judgePair says whether a window of samples shows the slot divided against the
// work, for CPU and for memory. It is pure, like the scheduler's decisions: the
// window and nothing else.
//
// Only the samples taken at the division in force now count. The newest
// sample's division is the pool's current one, and a window that straddles an
// edit would judge the old split with the new one's name.
func judgePair(window []pairSample) (pairAdvice, bool) {
	if len(window) == 0 {
		return pairAdvice{}, false
	}
	cpuShare, memShare := pairCPUShare, pairMemShare
	newest := window[len(window)-1]
	curCPU, curMem := cpuShare(newest), memShare(newest)
	if curCPU == 0 && curMem == 0 {
		return pairAdvice{}, false
	}
	var rCPU, dCPU, rMem, dMem []float64
	var slotCPU, slotMem float64
	var cover pairCover
	runners := map[string]bool{}
	n := 0
	for _, s := range window {
		if cpuShare(s) != curCPU || memShare(s) != curMem {
			continue
		}
		n++
		runners[s.runner] = true
		cover.add(s)
		rCPU, dCPU = append(rCPU, s.halves.Runner.CPUs), append(dCPU, s.halves.Daemon.CPUs)
		rMem, dMem = append(rMem, float64(s.halves.Runner.MemoryBytes)), append(dMem, float64(s.halves.Daemon.MemoryBytes))
		slotCPU = max(slotCPU, s.halves.Runner.CPULimit+s.halves.Daemon.CPULimit)
		slotMem = max(slotMem, float64(s.halves.Runner.MemoryLimit+s.halves.Daemon.MemoryLimit))
	}
	if !cover.enough() {
		return pairAdvice{}, false
	}
	// Use as a part of each container's own limit, which is what "squeezed" means.
	over := func(used []float64, limit float64) []float64 {
		out := make([]float64, len(used))
		for i, u := range used {
			if limit > 0 {
				out[i] = u / limit
			}
		}
		return out
	}
	adv := pairAdvice{Samples: n, Runners: len(runners), Span: cover.span()}
	if curCPU > 0 && slotCPU > 0 {
		rLimit, dLimit := slotCPU*float64(100-curCPU)/100, slotCPU*float64(curCPU)/100
		adv.CPU = judgeResource("CPU", curCPU, over(rCPU, rLimit), over(dCPU, dLimit), rCPU, dCPU, slotCPU)
	}
	if curMem > 0 && slotMem > 0 {
		rLimit, dLimit := slotMem*float64(100-curMem)/100, slotMem*float64(curMem)/100
		adv.Memory = judgeResource("memory", curMem, over(rMem, rLimit), over(dMem, dLimit), rMem, dMem, slotMem)
	}
	return adv, adv.CPU != nil || adv.Memory != nil
}

// judgeResource judges one resource: it is wrong when one container's 95th
// percentile use of its own limit is at least pairHot and the other's is at most
// pairIdle, and the proposal is each container's own 95th percentile use with
// headroom, as a part of the slot, rounded to five and kept in range. It has to
// move the slot toward the squeezed container by enough to matter; anything else
// is a number to second-guess for no gain.
func judgeResource(name string, current int, rUse, dUse, rUsed, dUsed []float64, slot float64) *resourceAdvice {
	rHot, dHot := pairPercentile(slices.Clone(rUse), 0.95), pairPercentile(slices.Clone(dUse), 0.95)
	adv := &resourceAdvice{Resource: name, Current: current}
	// What a container is sized to hold. CPU is a burst the elastic valve lends for, so
	// its 95th percentile will do. Memory is a limit a job is killed at: a half that
	// held its 95th percentile and was given less than its peak -- 3.5 GiB in four
	// samples of a hundred and twenty -- is killed the next time the heavy phase runs,
	// and one click would have done it.
	q := 0.95
	if name == "memory" {
		q = 1
	}
	switch {
	case dHot >= pairHot && rHot <= pairIdle:
		adv.DaemonHot, adv.HotPercent, adv.IdlePercent = true, dHot*100, rHot*100
		adv.HotUse, adv.OtherUse = pairPercentile(slices.Clone(dUsed), 0.95), pairPercentile(slices.Clone(rUsed), q)
	case rHot >= pairHot && dHot <= pairIdle:
		adv.HotPercent, adv.IdlePercent = rHot*100, dHot*100
		adv.HotUse, adv.OtherUse = pairPercentile(slices.Clone(rUsed), 0.95), pairPercentile(slices.Clone(dUsed), q)
	default:
		return nil
	}
	need := func(used []float64) float64 {
		return max(pairPercentile(slices.Clone(used), q)/slot*pairHeadroom, 0.05)
	}
	d, r := need(dUsed), need(rUsed)
	proposed := int(math.Round(100*d/(d+r)/5) * 5)
	proposed = min(max(proposed, store.MinDaemonSharePercent), store.MaxDaemonSharePercent)
	if adv.DaemonHot && proposed < current+pairMinMove || !adv.DaemonHot && proposed > current-pairMinMove {
		return nil
	}
	adv.Proposed = proposed
	return adv
}

// sameShare says whether the share the containers were created with is the one
// the pool names. Two points of slack, because the halves are rounded to the
// core and the byte and a slot raised to a minimum is not divided to the digit.
func sameShare(observed, configured int) bool { return abs(observed-configured) <= 2 }

// affordShare prices r's proposal on the pool's hosts and brings it back to one
// they can carry. The window says what the containers use; it cannot say what a
// thinner half is charged, and that is the larger half of the arithmetic: a
// half is held to the pool's smallest runner, so a 10% sidecar on a four-core
// slot is a request for a ten-core one, and the notice that proposed it was
// followed by a warning that three hosts in four could no longer run the pool.
// Advice that costs the fleet its runners is not advice, so the proposal is
// stepped back toward the current share until the hosts hold as many runners as
// they do now, and when no step that still matters does, r says what the
// figure would have cost and proposes nothing.
func (c *Controller) affordShare(ctx context.Context, p *store.Pool, now PoolRoom, r *resourceAdvice) error {
	step := 5
	if r.Proposed < r.Current {
		step = -step
	}
	var cost *shareCost
	for s := r.Proposed; abs(s-r.Current) >= pairMinMove; s -= step {
		cand := *p
		if r.Resource == "CPU" {
			cand.Resources.DaemonCPUSharePercent = s
		} else {
			cand.Resources.DaemonMemorySharePercent = s
		}
		room, err := c.poolRoom(ctx, &cand)
		if err != nil {
			return err
		}
		if room.Runners >= now.Runners {
			if shareHelps(now, room, r, s) {
				r.Proposed = s
				return nil
			}
			if cost == nil {
				cost = &shareCost{Wanted: s, Runners: room.Runners, RunnersNow: now.Runners, Pinned: true}
			}
			continue
		}
		if cost == nil {
			cost = &shareCost{Wanted: s, Runners: room.Runners, RunnersNow: now.Runners}
		}
	}
	// judgeResource only proposes a move of at least pairMinMove, so the loop
	// priced the proposal itself at least once and cost is set.
	r.Held = cost
	return nil
}

// shareHelps says whether a share, turned into the limits each container would
// really be given on the pool's hosts, gives the squeezed container more somewhere
// and leaves the other enough everywhere.
//
// The window judges a share as a part of one slot, but a slot is not fixed by the
// share: where the pool has a smallest runner, the thinner half is held to it and
// the slot grows to carry it. A daemon at 15% of a slot whose floor is its 1.5 GB
// minimum is given 1.5 GB at any share of 50% or less, and a proposal to raise it
// only took the memory from the runner -- which was then the half the detector
// would call squeezed next, and the notice went quiet because both halves were.
func shareHelps(now, candidate PoolRoom, r *resourceAdvice, share int) bool {
	charge := func(e PoolHostRoom) float64 {
		if r.Resource == "CPU" {
			return e.ChargeCPUs
		}
		return float64(e.ChargeMemoryMB)
	}
	use := func(v float64) float64 {
		if r.Resource == "CPU" {
			return v
		}
		return v / (1 << 20)
	}
	hotFrac := func(daemonPercent int) float64 {
		if r.DaemonHot {
			return float64(daemonPercent) / 100
		}
		return 1 - float64(daemonPercent)/100
	}
	before := map[string]PoolHostRoom{}
	for _, e := range now.Hosts {
		before[e.HostID] = e
	}
	grew := false
	for _, e := range candidate.Hosts {
		was, ok := before[e.HostID]
		if e.Room <= 0 || !ok || charge(e) <= 0 || charge(was) <= 0 {
			continue
		}
		if charge(e)*hotFrac(share) > charge(was)*hotFrac(r.Current)*1.02 {
			grew = true
		}
		otherFrac := 1 - hotFrac(share)
		if charge(e)*otherFrac < use(r.OtherUse)*pairHeadroom {
			return false
		}
	}
	return grew
}

// daemonShareAdviceProblems is the standing advice on how a pool divides its
// slot. Recomputed every pass, so it stays while the window shows it and clears
// itself when the split is changed, or the work is.
func (c *Controller) daemonShareAdviceProblems(ctx context.Context, out *[]Problem) error {
	pools, err := c.fleetPools(ctx)
	if err != nil {
		return fmt.Errorf("listing pools: %w", err)
	}
	for _, p := range pools {
		// A pool the controller keeps divides its slot evenly and has no setting
		// for it: the advice would send an operator to an edit that is refused, and
		// one that was accepted would be put back with the rest of the pool's fixed
		// settings. They make a pool of their own where the split matters.
		if !p.Enabled || p.DockerMode != store.DockerDinD || p.FromHosts() {
			continue
		}
		c.pairMu.Lock()
		window := slices.Clone(freshPairs(c.pairs[p.ID], c.Now()))
		c.pairMu.Unlock()
		adv, ok := judgePair(window)
		if !ok {
			continue
		}
		// The window is judged at the newest sample's division, which stays the old
		// one until a runner made after an edit reports. A share that is not the
		// pool's now has been changed since, so what it shows is about a split the
		// pool no longer has and the notice would offer the change just made.
		if adv.CPU != nil && !sameShare(adv.CPU.Current, p.Resources.DaemonCPUPercent()) {
			adv.CPU = nil
		}
		if adv.Memory != nil && !sameShare(adv.Memory.Current, p.Resources.DaemonMemoryPercent()) {
			adv.Memory = nil
		}
		if adv.CPU == nil && adv.Memory == nil {
			continue
		}
		room, err := c.poolRoom(ctx, p)
		if err != nil {
			return fmt.Errorf("sizing pool %s's sidecar share: %w", p.Name, err)
		}
		// A share changes what a host's agent gives the sidecar only if the agent divides by
		// it. Where one that does not is among the hosts the pool can land on, a proposal is
		// a proposal to change a number that host ignores, and pool.daemon_share_unsupported
		// says so; it is not made.
		if _, unsupported := heldWithoutDaemonShare(p, room.Placeable()); unsupported {
			continue
		}
		var lines, flags, held []string
		pinned := false
		titles := []string{}
		for _, r := range []*resourceAdvice{adv.CPU, adv.Memory} {
			if r == nil {
				continue
			}
			if err := c.affordShare(ctx, p, room, r); err != nil {
				return fmt.Errorf("sizing pool %s's sidecar %s share: %w", p.Name, strings.ToLower(r.Resource), err)
			}
			hot, idle, raise, flag := "runner", "Docker sidecar", "lower", "--daemon-"+strings.ToLower(r.Resource)+"-share"
			if r.DaemonHot {
				hot, idle, raise = "Docker sidecar", "runner", "raise"
			}
			titles = append(titles, fmt.Sprintf("its %s is short of %s while the %s beside it is not", hot, r.Resource, idle))
			line := fmt.Sprintf("%s: the %s used at least %.0f%% of its own limit for one sample in twenty, while the %s used at most %.0f%% of its; "+
				"it is divided %d%% to the sidecar now",
				r.Resource, hot, r.HotPercent, idle, r.IdlePercent, r.Current)
			if r.Held != nil {
				// Said, not dropped: the squeeze is real, and an operator who is told
				// nothing has no way to know the share was priced and found too dear.
				if r.Held.Pinned {
					lines = append(lines, line+fmt.Sprintf(", and the use points at about %d%%, but on these hosts the thinner half is held to this pool's smallest runner, "+
						"so a different share would not give it more and would only take from the half beside it", r.Held.Wanted))
					pinned = true
				} else {
					lines = append(lines, line+fmt.Sprintf(", and the use points at about %d%%, but the thinner half is held to this pool's smallest runner and the slot grows to carry it, "+
						"which would leave its hosts room for %s where they hold %d now",
						r.Held.Wanted, plural(r.Held.Runners, "runner"), r.Held.RunnersNow))
				}
				held = append(held, strings.ToLower(r.Resource))
				continue
			}
			lines = append(lines, fmt.Sprintf("%s, and %s it to about %d%%", line, raise, r.Proposed))
			flags = append(flags, fmt.Sprintf("%s %d", flag, r.Proposed))
		}
		// Two resources that want the same figure are one share, which is also the
		// shorter command and the one that leaves the pool a single setting.
		if adv.CPU != nil && adv.Memory != nil && adv.CPU.Held == nil && adv.Memory.Held == nil && adv.CPU.Proposed == adv.Memory.Proposed {
			flags = []string{fmt.Sprintf("--daemon-share %d", adv.CPU.Proposed)}
		}
		var fix []string
		if len(flags) > 0 {
			fix = append(fix, fmt.Sprintf("change the sidecar's share in the pool editor (Size step), or zoomies pools edit %s %s, and watch the next few jobs. "+
				"It applies to runners created after the change.", p.Name, strings.Join(flags, " ")))
		}
		if len(held) > 0 {
			if pinned {
				fix = append(fix, fmt.Sprintf("Leave the %s share where it is: the thinner half is given the pool's smallest runner whatever the share. To give it more, raise the pool's smallest runner "+
					"in the pool editor (Size step), which is what sets it, or run the pool on larger machines.", strings.Join(held, " and ")))
			} else {
				fix = append(fix, fmt.Sprintf("Leave the %s share where it is: moving it would cost runners. To give the squeezed container more room, lower the pool's smallest runner "+
					"in the pool editor (Size step), which is what holds the thinner half up, or run the pool on larger machines.", strings.Join(held, " and ")))
			}
		}
		var change *DaemonShareChange
		if len(flags) > 0 {
			change = &DaemonShareChange{}
			if adv.CPU != nil && adv.CPU.Held == nil {
				change.CPUPercent = adv.CPU.Proposed
			}
			if adv.Memory != nil && adv.Memory.Held == nil {
				change.MemoryPercent = adv.Memory.Proposed
			}
		}
		var remedy *Remedy
		if change != nil {
			// The request is the pool's own resources with only the proposed shares
			// changed, because an update replaces them whole.
			res := p.Resources
			var words []string
			if change.CPUPercent > 0 {
				res.DaemonCPUSharePercent = change.CPUPercent
				words = append(words, fmt.Sprintf("%d%% of the CPU", change.CPUPercent))
			}
			if change.MemoryPercent > 0 {
				res.DaemonMemorySharePercent = change.MemoryPercent
				words = append(words, fmt.Sprintf("%d%% of the memory", change.MemoryPercent))
			}
			effect := ""
			if room.Runners > 0 {
				effect = fmt.Sprintf("the pool's hosts keep room for all %s", plural(room.Runners, "runner"))
			}
			remedy = newRemedy(RemedyPoolUpdate, p.ID, "Give the sidecar "+strings.Join(words, " and "), effect, map[string]any{"resources": res}, p.Resources)
		}
		*out = append(*out, Problem{
			DaemonShare: change,
			Remedy:      remedy,
			Code:        "pool.daemon_share_suggested",
			Severity:    config.SeverityInfo,
			Title:       fmt.Sprintf("pool %s: %s", p.Name, strings.Join(titles, "; and ")),
			Detail: fmt.Sprintf("across at least %d samples from %d or more runners over at least %s. A runner and its sidecar divide one slot, CPU and memory each on their own share. %s.",
				pairMinSamples, pairMinRunners, pairMinSpan, strings.Join(lines, ". ")),
			Fix:        strings.Join(fix, " "),
			TargetKind: "pool",
			TargetID:   p.ID,
		})
	}
	return nil
}

package controller

import (
	"fmt"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

const gib = int64(1 << 30)

// pairWindowOf is n samples from runners runners of a slot divided evenly
// (2 cores and 4 GiB each side) in which the two halves use what is given.
func pairWindowOf(n, runners int, runnerUse, daemonUse backend.HalfUse) []pairSample {
	out := make([]pairSample, 0, n)
	for i := 0; i < n; i++ {
		r, d := runnerUse, daemonUse
		r.CPULimit, r.MemoryLimit = 2, 4*gib
		d.CPULimit, d.MemoryLimit = 2, 4*gib
		out = append(out, pairSample{sampled: time.Unix(1_700_000_000, 0).Add(time.Duration(i) * 30 * time.Second), runner: fmt.Sprintf("r%d", i%runners), halves: backend.PairHalves{Runner: r, Daemon: d}})
	}
	return out
}

// A build that runs flat out in the daemon while the runner idles is the case
// the sums hide, and the proposal has to move the slot toward the daemon.
func TestASidecarSqueezedWhileTheRunnerIdlesIsOfferedALargerShare(t *testing.T) {
	w := pairWindowOf(100, 5,
		backend.HalfUse{CPUs: 0.1, MemoryBytes: gib / 4},
		backend.HalfUse{CPUs: 1.9, MemoryBytes: 3*gib + gib/2})
	adv, ok := judgePair(w)
	if !ok || adv.CPU == nil || adv.Memory == nil || !adv.CPU.DaemonHot || !adv.Memory.DaemonHot {
		t.Fatalf("advice = %+v, ok = %v; want a daemon short of both CPU and memory", adv, ok)
	}
	for _, r := range []*resourceAdvice{adv.CPU, adv.Memory} {
		if r.Current != 50 || r.Proposed < 70 || r.Proposed > 90 || r.Proposed%5 != 0 {
			t.Errorf("%s: proposed %d from %d; want a multiple of five between 70 and 90", r.Resource, r.Proposed, r.Current)
		}
	}
}

func TestARunnerSqueezedWhileTheSidecarIdlesIsOfferedASmallerShare(t *testing.T) {
	w := pairWindowOf(100, 5,
		backend.HalfUse{CPUs: 1.9, MemoryBytes: 3*gib + gib/2},
		backend.HalfUse{CPUs: 0.1, MemoryBytes: gib / 4})
	adv, ok := judgePair(w)
	if !ok || adv.CPU == nil || adv.Memory == nil {
		t.Fatalf("advice = %+v, ok = %v; want advice for both resources", adv, ok)
	}
	for _, r := range []*resourceAdvice{adv.CPU, adv.Memory} {
		if r.DaemonHot || r.Proposed > 30 || r.Proposed < store.MinDaemonSharePercent {
			t.Errorf("%s: %+v; want a smaller share for the sidecar", r.Resource, r)
		}
	}
}

// CPU and memory are judged apart, which is the point of splitting them: a
// daemon running a build flat out on CPU while the runner holds the memory is
// told to take more CPU and give memory back, in one notice, with a flag for each.
func TestCPUAndMemoryAreAdvisedOnTheirOwn(t *testing.T) {
	// Daemon: CPU-bound, little memory. Runner: nearly idle on CPU, memory-heavy.
	w := pairWindowOf(100, 5,
		backend.HalfUse{CPUs: 0.1, MemoryBytes: 3*gib + gib/2},
		backend.HalfUse{CPUs: 1.9, MemoryBytes: gib / 4})
	adv, ok := judgePair(w)
	if !ok || adv.CPU == nil || adv.Memory == nil {
		t.Fatalf("advice = %+v, ok = %v; want both resources advised", adv, ok)
	}
	if !adv.CPU.DaemonHot || adv.CPU.Proposed < 70 {
		t.Errorf("CPU: %+v; the daemon is short of CPU and should be offered more", adv.CPU)
	}
	if adv.Memory.DaemonHot || adv.Memory.Proposed > 30 {
		t.Errorf("memory: %+v; the runner is short of memory and the daemon's share should come down", adv.Memory)
	}

	// Only the resource that is wrong is advised.
	w = pairWindowOf(100, 5,
		backend.HalfUse{CPUs: 0.1, MemoryBytes: gib},
		backend.HalfUse{CPUs: 1.9, MemoryBytes: gib})
	adv, ok = judgePair(w)
	if !ok || adv.CPU == nil || adv.Memory != nil {
		t.Fatalf("advice = %+v, ok = %v; want CPU alone", adv, ok)
	}
}

// Advice rests on several runners and enough samples, and on a squeeze that is
// one-sided: both halves busy is a pool that needs a bigger slot, which no
// division fixes.
func TestNoShareAdviceWithoutEvidenceOrWhenBothHalvesAreBusy(t *testing.T) {
	hot := backend.HalfUse{CPUs: 1.9, MemoryBytes: 3*gib + gib/2}
	idle := backend.HalfUse{CPUs: 0.1, MemoryBytes: gib / 4}
	for name, w := range map[string][]pairSample{
		"too few samples":      pairWindowOf(10, 5, idle, hot),
		"one runner only":      pairWindowOf(100, 1, idle, hot),
		"both halves busy":     pairWindowOf(100, 5, hot, hot),
		"both halves idle":     pairWindowOf(100, 5, idle, idle),
		"an empty window":      nil,
		"daemon moderately in": pairWindowOf(100, 5, idle, backend.HalfUse{CPUs: 1, MemoryBytes: 2 * gib}),
	} {
		if adv, ok := judgePair(w); ok {
			t.Errorf("%s: advised %+v", name, adv)
		}
	}
}

// After an edit the old samples describe a division that is gone; judging them
// would propose a change to a setting that has already been changed.
func TestSamplesFromBeforeAShareWasChangedAreIgnored(t *testing.T) {
	hot := backend.HalfUse{CPUs: 1.9, MemoryBytes: 3*gib + gib/2}
	idle := backend.HalfUse{CPUs: 0.1, MemoryBytes: gib / 4}
	w := pairWindowOf(100, 5, idle, hot)
	// The newest samples are from a 75/25 slot, too few to judge on their own.
	for i := 0; i < 5; i++ {
		s := w[0]
		s.halves.Daemon.CPULimit, s.halves.Runner.CPULimit = 3, 1
		w = append(w, s)
	}
	if adv, ok := judgePair(w); ok {
		t.Fatalf("advised %+v from a window that straddles an edit", adv)
	}
}

// End to end: heartbeats from busy host-sized pairs fill the pool's window, and
// the standing problem names the pool and the command that changes it, then
// clears when the pool's daemon is given the share.
func TestASqueezedSidecarShowsUpAsAStandingProblemUntilTheShareMoves(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	// One slot to a machine, so that a lopsided share is one the host can carry:
	// the notice does not propose what would cost the pool its runners.
	host.Capacity = 1
	if err := h.st.UpdateHost(h.ctx, host); err != nil {
		t.Fatal(err)
	}
	pool.DockerMode = store.DockerDinD
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	now := h.c.Now()
	for i, s := range pairWindowOf(100, 5,
		backend.HalfUse{CPUs: 0.1, MemoryBytes: gib / 4},
		backend.HalfUse{CPUs: 1.9, MemoryBytes: 3*gib + gib/2}) {
		r := &store.Runner{ID: fmt.Sprintf("run-%d", i%5), PoolID: pool.ID, AllocationSource: store.AllocationFromHost}
		sampled := now.Add(time.Duration(i) * 30 * time.Second)
		h.c.observePair(r, backend.Stats{SampledAt: &sampled, Halves: &s.halves})
	}
	p := h.problemOrNil("pool.daemon_share_suggested")
	if p == nil || p.TargetID != pool.ID {
		t.Fatalf("problem = %+v; want one for the pool", p)
	}
	// Both resources want the same figure here, so it is one share and one flag.
	if want := "zoomies pools edit " + pool.Name + " --daemon-share"; !strings.Contains(p.Fix, want) {
		t.Errorf("fix %q does not carry the command %q", p.Fix, want)
	}

	// Typed pools have no division to judge: nothing is recorded for them.
	typed := &store.Runner{ID: "typed", PoolID: "other", AllocationSource: ""}
	h.c.observePair(typed, backend.Stats{SampledAt: &now, Halves: &backend.PairHalves{}})
	if len(h.c.pairs["other"]) != 0 {
		t.Error("a sample from a typed-limit runner was recorded")
	}
}

// A pool that takes its size from its hosts' runner profiles gives each runner
// a share of a slot exactly as one sized by the host's plain share does, so the
// advice about how the pair divides it has to hear from both. Comparing the
// runner's source with "host" alone left every profile-sized pool -- the pools
// the runner-sizes screen makes -- with an empty window and no advice, ever.
func TestASqueezedSidecarIsAdvisedWhetherTheHostsShareOrItsProfileSizedTheRunners(t *testing.T) {
	for _, source := range []string{store.AllocationFromHost, store.AllocationFromProfile} {
		t.Run(source, func(t *testing.T) {
			h := newHarness(t)
			_, pool, _ := h.fleet()
			pool.DockerMode = store.DockerDinD
			if err := h.st.UpdatePool(h.ctx, pool); err != nil {
				t.Fatal(err)
			}
			now := h.c.Now()
			for i, s := range pairWindowOf(100, 5,
				backend.HalfUse{CPUs: 0.1, MemoryBytes: gib / 4},
				backend.HalfUse{CPUs: 1.9, MemoryBytes: 3*gib + gib/2}) {
				r := &store.Runner{ID: fmt.Sprintf("run-%d", i%5), PoolID: pool.ID, AllocationSource: source}
				sampled := now.Add(time.Duration(i) * 30 * time.Second)
				h.c.observePair(r, backend.Stats{SampledAt: &sampled, Halves: &s.halves})
			}
			if p := h.problemOrNil("pool.daemon_share_suggested"); p == nil || p.TargetID != pool.ID {
				t.Fatalf("problem = %+v; want one for the pool whose runners are sized by %q", p, source)
			}
		})
	}
}

// When the two resources want different figures the notice says so, with a flag
// for each: more CPU for a daemon that is building, less memory for one that is not.
func TestAMixedSqueezeIsOneNoticeWithAFlagForEachResource(t *testing.T) {
