package controller

import (
	"context"
	"time"

	"github.com/eyupio/zoomies/internal/config"
)

// PrivateConnectionFault is why the private-connection listener cannot be
// reached by the hosts that enrolled through it, and since when.
//
// The listener belongs to the API server, which owns the socket-shaped half of
// the process; the controller only keeps the fact, because the problems list is
// built here and a listener that fails with nothing but a log line is the
// failure this exists to design out.
type PrivateConnectionFault struct {
	Since  time.Time
	Reason string
}

// SetPrivateConnectionFault records the private-connection listener's state:
// a fault while no relay answers, nil once one does. It is safe to call from
// any goroutine.
func (c *Controller) SetPrivateConnectionFault(f *PrivateConnectionFault) {
	if f == nil {
		c.privateFault.Store(nil)
		return
	}
	// Keep the first moment it went wrong: a retry that fails again is the
	// same outage, not a new one, and "since" should say how long hosts have
	// been cut off rather than when somebody last looked.
	if prev := c.privateFault.Load(); prev != nil {
		f = &PrivateConnectionFault{Since: prev.Since, Reason: f.Reason}
	}
	c.privateFault.Store(f)
}

// PrivateConnectionFault is the listener's current fault, or nil.
func (c *Controller) PrivateConnectionFault() *PrivateConnectionFault {
	return c.privateFault.Load()
}

// privateConnectionProblems says the private connection is down.
//
// It is a warning rather than an error because nothing about the direct half of
// the fleet depends on it, and a host that enrolled privately keeps its jobs
// running through an interruption; what stops is its heartbeats and its next
// task, which host.unhealthy reports on its own. This entry is the cause those
// symptoms otherwise leave an operator to guess.
func (c *Controller) privateConnectionProblems(_ context.Context, out *[]Problem) error {
	f := c.privateFault.Load()
	if f == nil {
		return nil
	}
	since := f.Since
	*out = append(*out, Problem{
		Code:     "tailcat.unavailable",
		Severity: config.SeverityWarning,
		Title:    "private hosts cannot reach this controller",
		Detail: "the private-connection listener has no Tailcat relay it can reach, so hosts enrolled with a " +
			"private connection cannot heartbeat or take work. " +
			"The last attempt said: " + f.Reason,
		Fix: "check that this controller has outbound HTTPS to Tailcat's relays, a firewall, proxy or DNS change is " +
			"the usual cause. The controller keeps retrying, trying the relay its identity was sealed with first, " +
			"and this clears on its own once one answers; no restart is needed.",
		Since: &since,
	})
	return nil
}

package controller

import (
	"testing"
	"time"
)

// A relay that stays down is retried every twenty seconds, and each retry
// reports again. "Since" has to stay at the first failure, or the entry would
// say the private hosts were cut off moments ago however long it had been.
func TestAPrivateConnectionFaultKeepsWhenItStartedAcrossRetries(t *testing.T) {
	h := newHarness(t)
	first := time.Date(2026, 9, 1, 10, 0, 0, 0, time.UTC)
	h.c.SetPrivateConnectionFault(&PrivateConnectionFault{Since: first, Reason: "relay did not answer"})
	h.c.SetPrivateConnectionFault(&PrivateConnectionFault{Since: first.Add(time.Minute), Reason: "still no answer"})

	var got *Problem
	problems, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	for i := range problems {
		if problems[i].Code == "tailcat.unavailable" {
			got = &problems[i]
		}
	}
	if got == nil {
		t.Fatal("a recorded private-connection fault raised no tailcat.unavailable")
	}
	if got.Since == nil || !got.Since.Equal(first) {
		t.Errorf("since = %v, want the first failure %v", got.Since, first)
	}
	if got.Audience != AudiencePlatform {
		t.Errorf("audience = %q; the listener is the process's, so the platform's", got.Audience)
	}

	h.c.SetPrivateConnectionFault(nil)
	problems, _ = h.c.Problems(h.ctx)
	for _, p := range problems {
		if p.Code == "tailcat.unavailable" {
			t.Fatal("tailcat.unavailable stayed after the relay answered")
		}
	}
}

package controller

import (
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
)

var codeLiteral = regexp.MustCompile(`Code: *"([a-z_]+\.[a-z_.]+)"`)

// raisedCodes is every problem code this package and the providers construct,
// found by walking rather than listed, for the reason internal/docs walks the
// same trees: a hand-written list catches up to a new file only after somebody
// notices, and by then the code has shipped to whichever audience the default
// chose.
func raisedCodes(t *testing.T) []string {
	t.Helper()
	seen := map[string]bool{}
	for _, root := range []string{".", "../provider"} {
		err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			if d.IsDir() || !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") {
				return nil
			}
			body, err := os.ReadFile(path)
			if err != nil {
				return err
			}
			for _, m := range codeLiteral.FindAllStringSubmatch(string(body), -1) {
				seen[m[1]] = true
			}
			return nil
		})
		if err != nil {
			t.Fatalf("walking %s: %v", root, err)
		}
	}
	out := make([]string, 0, len(seen))
	for c := range seen {
		out = append(out, c)
	}
	return out
}

// Whose a problem is has to be decided by somebody, once, for every code. The
// default is the platform, so a code nobody classified goes to the smaller
// audience rather than leaking -- but a gap in the fleet's list is still a
// bug, and this is what stops one reaching a release.
func TestEveryProblemCodeHasAnAudience(t *testing.T) {
	var missing []string
	for _, code := range raisedCodes(t) {
		if _, ok := problemAudience[code]; !ok {
			missing = append(missing, code)
		}
	}
	if len(missing) > 0 {
		t.Errorf("these problem codes are raised with no audience decided for them, so they default to the platform and the fleet never sees them:\n  %s",
			strings.Join(missing, "\n  "))
	}
}

// And the other way: a row for a code nothing raises any more is a decision
// about nothing, and the next person to read the table has to work out
// whether the code went away or the raise did.
func TestTheAudienceTableNamesNothingThatIsGone(t *testing.T) {
	raised := map[string]bool{}
	for _, c := range raisedCodes(t) {
		raised[c] = true
	}
	var stale []string
	for code := range problemAudience {
		if !raised[code] {
			stale = append(stale, code)
		}
	}
	if len(stale) > 0 {
		t.Errorf("the audience table names codes nothing raises:\n  %s", strings.Join(stale, "\n  "))
	}
}

// The split is a judgement, and these are the ones worth pinning: each is a
// case where getting it wrong is a leak or a silence rather than a matter of
// taste.
func TestTheAudienceOfTheOnesThatMatter(t *testing.T) {
	for _, tc := range []struct {
		code string
		want Audience
		why  string
	}{
		{"backup.remote_unreadable", AudiencePlatform, "a backup remote is the process's, and its existence is not the fleet's to learn"},
		{"backup.failed", AudiencePlatform, "the fleet cannot take a backup and cannot fix one failing"},
		{"controller.lease_lost", AudiencePlatform, "the lease is between the process and its database"},
		{"controller.loop_panicked", AudiencePlatform, "a panic in a loop is the operator's to read the log for"},
		{"controller.update_available", AudiencePlatform, "only whoever runs the process can upgrade it"},
		{"capacity_demand.delivery_failed", AudiencePlatform, "the receiver and its signing secret are the platform's"},
		{"crypto.key_mismatch", AudiencePlatform, "the encryption key is the process's"},
		{"controller.problems_partial", AudienceBoth, "a truncated list must say so to whoever is reading it"},
		{"pool.no_capacity", AudienceFleet, "a pool with nowhere to run is the fleet's to resize or re-label"},
		{"host.unhealthy", AudienceFleet, "the fleet's own hosts"},
		{"runners.failed", AudienceFleet, "the fleet's own runners"},
		{"jobs.unmatched", AudienceFleet, "a job no pool claims is a labelling question for whoever wrote the workflow"},
		{"recovery.fenced", AudienceFleet, "the fence stops the fleet's work, so the fleet has to be told it is why nothing is running"},
	} {
		if got := audienceFor(tc.code); got != tc.want {
			t.Errorf("%s is %q, want %q: %s", tc.code, got, tc.want, tc.why)
		}
	}
}

// For is what every filter below is written in terms of, so its own edges are
// worth holding: the platform sees an unclassified problem, the fleet does
// not, and both see the ones marked both.
func TestWhoSeesWhat(t *testing.T) {
	for _, tc := range []struct {
		a                     Audience
		platform, fleetMember bool
	}{
		{AudiencePlatform, true, false},
		// The platform sees the fleet's too. This row is the one that
		// matters: without it, "platform sees platform problems" passes every
		// other assertion here and takes every pool, host, runner and job
		// problem off the drawer of every operator running their own fleet,
		// because the account that installed a single-team instance holds
		// platform. A drill caught that; this row is so the next one does not
		// have to.
		{AudienceFleet, true, true},
		{AudienceBoth, true, true},
		{Audience(""), true, false},
	} {
		if got := tc.a.For(true); got != tc.platform {
			t.Errorf("%q for the platform = %v, want %v", tc.a, got, tc.platform)
		}
		if got := tc.a.For(false); got != tc.fleetMember {
			t.Errorf("%q for the fleet = %v, want %v", tc.a, got, tc.fleetMember)
		}
	}
}

package controller

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// failedMachine writes a machine the fleet gave up on. With a resource it is a
// VM that may still be running and billed; without one it is a row that never
// got as far as the hypervisor.
func (h *harness) failedMachine(t *testing.T, withResource bool, fields store.Machine) *store.Machine {
	t.Helper()
	h.enableProviders(t)
	row := h.providerRow(t, "lab")
	fields.ProviderID = row.ID
	fields.State = store.MachineFailed
	fields.Labels = store.StringMap{}
	if withResource {
		fields.ResourceZone, fields.ResourceID = "zone-a", "143"
	}
	if err := h.st.CreateMachine(h.ctx, &fields); err != nil {
		t.Fatalf("CreateMachine: %v", err)
	}
	return &fields
}

// fixFor is the advice a problem gives for one machine.
func (h *harness) fixFor(t *testing.T, code, machineID string) string {
	t.Helper()
	for _, p := range h.problemsOf(t, code) {
		if p.TargetID == machineID {
			return p.Fix
		}
	}
	t.Fatalf("no %s problem for machine %s; the list has %v", code, machineID, h.problemCodes())
	return ""
}

// The advice used to be to release a failed row once the console had been
// checked. Release forgets a row and touches nothing, which is the escape hatch
// for a machine nobody can safely delete, and a failed machine that never got a
// resource is the opposite case: there is nothing to check and nothing to leave
// running, and the thing to do with the row is to delete it. Sending people to
// release it meant a pile of them, each opened and released by hand.
func TestAFailedMachineWithNothingBehindItIsToldToDeleteItNotToReleaseIt(t *testing.T) {
	h := newHarness(t)
	m := h.failedMachine(t, false, store.Machine{ProviderError: "no space on pve-1"})

	fix := h.fixFor(t, "provider.machine_failed", m.ID)
	for _, want := range []string{"nothing was created", "Delete it", "together"} {
		if !strings.Contains(fix, want) {
			t.Errorf("the advice for a failed machine with no resource does not say %q: %s", want, fix)
		}
	}
	for _, unwanted := range []string{"Release", "may still exist", "console"} {
		if strings.Contains(fix, unwanted) {
			t.Errorf("the advice for a failed machine with no resource still mentions %q: %s", unwanted, fix)
		}
	}
}

// A failed machine that does have a resource is the one that costs money, so
// the console is worth a look. What to do afterwards is still to delete the
// machine, which asks the provider again before it destroys anything. Releasing
// it would forget a VM that goes on running and billing with nothing tracking it.
func TestAFailedMachineWithAResourceIsToldToCheckTheConsoleAndThenDeleteIt(t *testing.T) {
	h := newHarness(t)
	m := h.failedMachine(t, true, store.Machine{ProviderError: "the clone timed out"})

	fix := h.fixFor(t, "provider.machine_failed", m.ID)
	for _, want := range []string{"may still be running", "console", "Press Delete", "asks the provider again"} {
		if !strings.Contains(fix, want) {
			t.Errorf("the advice for a failed machine with a resource does not say %q: %s", want, fix)
		}
	}
	if strings.Contains(fix, "Release") || strings.Contains(fix, "release") {
		t.Errorf("the advice for a failed machine with a resource still tells the operator to release it: %s", fix)
	}
}

// The agent never coming up leaves a running VM, and the advice was all about
// the template. Once that is fixed the failed machine still has to be deleted,
// or it goes on being paid for.
func TestAMachineWhoseAgentNeverCameUpIsToldToDeleteItOnceTheTemplateIsFixed(t *testing.T) {
	h := newHarness(t)
	m := h.failedMachine(t, true, store.Machine{BootstrapError: "the agent did not answer in time"})

	fix := h.fixFor(t, "provider.bootstrap_failed", m.ID)
	if !strings.Contains(fix, "agent.json") {
		t.Fatalf("the advice about the template has gone: %s", fix)
	}
	for _, want := range []string{"delete this machine", "stop paying"} {
		if !strings.Contains(fix, want) {
			t.Errorf("the advice does not say %q: %s", want, fix)
		}
	}
}

package controller

import (
	"context"
	"errors"
	"runtime/debug"
	"slices"
	"sync"
	"time"
)

// problemsFlight lets callers that ask for the problems list at the same moment
// share one computation of it.
//
// The list is a few dozen queries, and every browser that opens the Overview
// asks for it, so eight people arriving together used to be eight computations
// and a queue of several seconds each. There is deliberately no time-to-live: a
// caller that arrives after a computation has finished starts a new one, so the
// answer is never older than the moment it was asked for, and a test that
// changes something and asks again sees the change. The one exception is a single
// section, the slower-job check, which keeps what it found for a minute (see
// jobtrends.go).
type problemsFlight struct {
	mu     sync.Mutex
	active *problemsCall
}

type problemsCall struct {
	done  chan struct{}
	items []Problem
	err   error
}

// problemsTimeout bounds a shared computation. It is not any one caller's
// request, so it is not cut short when the caller that happened to start it
// gives up.
const problemsTimeout = 30 * time.Second

// errProblemsPanicked is what the requests waiting on a computation that
// panicked are told. The panic and its stack are in the log.
var errProblemsPanicked = errors.New("the problems list could not be worked out because the controller hit an internal error; " +
	"its log has the stack under \"" + detachedPanicMessage + "\"")

// SharedProblems is Problems for callers that may overlap: the API handler and
// the event stream. Callers that arrive while a computation is running wait for
// it rather than starting another, and each gets its own copy of the list.
func (c *Controller) SharedProblems(ctx context.Context) ([]Problem, error) {
	f := &c.problemsFlight
	f.mu.Lock()
	call := f.active
	if call == nil {
		call = &problemsCall{done: make(chan struct{})}
		f.active = call
		go func() {
			// However the computation ends, the requests waiting on it are
			// released and the next one starts afresh. A call left registered
			// would make every request after it wait for a result that is
			// never coming.
			defer func() {
				f.mu.Lock()
				f.active = nil
				f.mu.Unlock()
				close(call.done)
			}()
			// Recovered here and not by recoverDetached, because the requests
			// waiting are owed an error and not an empty list.
			defer func() {
				if r := recover(); r != nil {
					c.reportDetachedPanic("problems-list", r, debug.Stack())
					call.items, call.err = nil, errProblemsPanicked
				}
			}()
			// Detached from the caller's cancellation but not from its values.
			run, cancel := context.WithTimeout(context.WithoutCancel(ctx), problemsTimeout)
			defer cancel()
			call.items, call.err = c.Problems(run)
		}()
	}
	f.mu.Unlock()

	select {
	case <-call.done:
		return slices.Clone(call.items), call.err
	case <-ctx.Done():
		return nil, ctx.Err()
	}
}

package controller

import (
	"context"
	"sync"
	"testing"
	"time"
)

// Eight operators opening the Overview at once used to mean eight computations
// of the list. They must all get the answer, and each must get a list of its
// own: the API filters and the event stream marshals what it is handed, and
// neither is allowed to see another's edits.
func TestOverlappingProblemRequestsEachGetTheirOwnCopyOfTheList(t *testing.T) {
	h := newHarness(t)
	h.cfg.Security.DisableAuth = true
	want, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	if len(want) == 0 {
		t.Fatal("the harness reports no problems, so there is nothing for a copy to be wrong about")
	}

	results := make([][]Problem, 8)
	var wg sync.WaitGroup
	for i := range results {
		wg.Add(1)
		go func() {
			defer wg.Done()
			got, err := h.c.SharedProblems(h.ctx)
			if err != nil {
				t.Errorf("SharedProblems: %v", err)
				return
			}
			results[i] = got
		}()
	}
	wg.Wait()

	for i, got := range results {
		if len(got) != len(want) {
			t.Fatalf("caller %d got %d problems, want %d", i, len(got), len(want))
		}
	}
	results[0][0].Title = "edited by the first caller"
	for i, got := range results[1:] {
		if got[0].Title == "edited by the first caller" {
			t.Fatalf("caller %d saw the first caller's edit: the list is shared, not copied", i+1)
		}
	}
}

// The list is computed on a goroutine of its own, so neither a loop's guard nor
// net/http's recovery of a request reaches it, and a panic in it used to end
// the process. It has to fail the requests waiting on it and nothing more. It
// also has to leave the flight clear: a computation that stayed registered
// would make every request after it wait for a result that is never coming.
func TestAPanicWhileComputingTheProblemsListFailsThoseRequestsAndNotTheProcess(t *testing.T) {
	h := newHarness(t)
	live := h.c.live
	h.c.live = nil // the configuration every pass reads; nil is what a bug leaves behind

	if _, err := h.c.SharedProblems(h.ctx); err == nil {
		t.Fatal("a computation that panicked reported no error to the request that waited for it")
	}

	h.c.live = live
	ctx, cancel := context.WithTimeout(h.ctx, 5*time.Second)
	defer cancel()
	if _, err := h.c.SharedProblems(ctx); err != nil {
		t.Fatalf("the request after the panic got %v: the failed computation was left registered", err)
	}
}

// A caller that arrives after a computation has finished starts its own: there
// is no cache, so the list is never older than the question.
func TestAProblemsRequestAfterTheLastFinishedSeesWhatChangedSince(t *testing.T) {
	h := newHarness(t)
	h.cfg.Security.DisableAuth = true
	before, err := h.c.SharedProblems(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	if len(before) == 0 {
		t.Fatal("disabling auth raised no problem")
	}
	h.cfg.Security.DisableAuth = false
	after, err := h.c.SharedProblems(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	if len(after) != 0 {
		t.Fatalf("the list still holds %d problems after the cause was removed: a finished computation was reused", len(after))
	}
}

