	h.queueWork(t)

	if p, ok := h.rentingOffProblem(t); ok {
		t.Fatalf("before a pass: %+v", p)
	}
	h.machinePass(t)
	if p, ok := h.rentingOffProblem(t); ok {
		t.Fatalf("after a pass: %+v", p)
