// A heartbeat carries what an agent measures about its machine and never
// writes how big the operator wants a runner there to be, or a host could
// resize its own runners by what it said about itself.
func TestAHeartbeatNeverWritesTheOperatorsRunnerProfile(t *testing.T) {
	h := newHarness(t)
	tr, id := joinedHost(t, h, 500_000, 200_000)
	host, err := h.st.GetHost(h.ctx, id)
	if err != nil {
		t.Fatal(err)
	}
	h.profile(host, bigProfile)

	if _, err := tr.Heartbeat(h.ctx, agent.HeartbeatRequest{
		ProtocolVersion: agent.ProtocolVersion,
		CPUs:            16,
		MemoryMB:        65536,
		DiskTotalMB:     500_000,
		DiskFreeMB:      40_000,
	}); err != nil {
		t.Fatalf("Heartbeat: %v", err)
	}
	after, err := h.st.GetHost(h.ctx, id)
	if err != nil {
		t.Fatal(err)
	}
	if after.RunnerProfile != bigProfile {
		t.Fatalf("a heartbeat replaced the operator's profile with %+v", after.RunnerProfile)
	}
	if after.CPUs != 16 {
		t.Fatalf("the heartbeat's own observation was lost: %d CPUs", after.CPUs)
	}
}

// A re-join replaces the row wholesale. The profile is the operator's, and it
// costs more to lose than the reserve: a host that forgot its standard would be
// sized by the fleet's default again with nothing to say why.
func TestARejoinKeepsTheOperatorsRunnerProfile(t *testing.T) {
	h := newHarness(t)
	_, id := joinedHost(t, h, 500_000, 200_000)
	host, err := h.st.GetHost(h.ctx, id)
	if err != nil {
		t.Fatal(err)
	}
	want := store.RunnerProfile{
		Minimum:  store.RunnerSize{CPUs: 1, MemoryMB: 2048},
		Standard: store.RunnerStandard{CPUs: 3, MemoryMB: 8192, BurstMaxCPUs: 6},
	}
	h.profile(host, want)

	again := h.c.EmbeddedTransport()
	resp, err := again.Join(h.ctx, agent.JoinRequest{
		ProtocolVersion: agent.ProtocolVersion,
		Name:            "vm-1",
		Capacity:        4,
		Backends:        []backend.Info{{Kind: store.BackendDocker, Available: true}},
	})
	if err != nil {
		t.Fatalf("re-Join: %v", err)
	}
	after, err := h.st.GetHost(h.ctx, resp.HostID)
	if err != nil {
		t.Fatal(err)
	}
	if after.RunnerProfile != want {
		t.Fatalf("the profile after a re-join is %+v, want the operator's %+v", after.RunnerProfile, want)
	}
}

package controller

import (
	"bytes"
	"crypto/x509"
	"encoding/pem"
	"fmt"
	"strings"
)

// CertificateProblem says what is wrong with text that is meant to be one or
// more PEM certificates, or returns "" when there is nothing wrong. Nothing at
// all is fine: an empty box means the system's trust store.
//
// It is written for a person looking at the box the text is in. A private key is
// named as one, because that is the mistake a cluster invites (its authority
// keeps the private half beside the public one), and the text itself is never
// repeated, so a key pasted by mistake is not echoed into a response or a log.
func CertificateProblem(text string) string {
	rest := []byte(strings.TrimSpace(text))
	if len(rest) == 0 {
		return ""
	}
	found := 0
	for {
		block, after := pem.Decode(rest)
		if block == nil {
			break
		}
		switch {
		case strings.Contains(block.Type, "PRIVATE KEY"):
			return "that is a private key, not a certificate. Paste the certificate, which begins -----BEGIN CERTIFICATE-----; " +
				"a key must not leave the machine it belongs to."
		case block.Type != "CERTIFICATE":
			return fmt.Sprintf("that holds a %s block, and only certificates belong here. Paste what begins -----BEGIN CERTIFICATE-----.", block.Type)
		}
		if _, err := x509.ParseCertificate(block.Bytes); err != nil {
			return fmt.Sprintf("a certificate in it could not be read (%v). Paste it again, whole, from -----BEGIN CERTIFICATE----- to -----END CERTIFICATE-----.", err)
		}
		found++
		rest = after
	}
	switch {
	// What pem.Decode could not read as a block is only text between and around
	// them unless it still carries a header, which is a block that did not parse.
	case bytes.Contains(rest, []byte("-----BEGIN")):
		return "part of it is a PEM block that is cut short or damaged. Paste it again, whole, from -----BEGIN CERTIFICATE----- to -----END CERTIFICATE-----."
	case found == 0:
		return "that holds no PEM certificate. It must begin with -----BEGIN CERTIFICATE-----."
	}
	return ""
}

// certificateAuthority is the certificate text a provider trusts, or nothing
// when what is stored is not entirely certificates.
//
// It is returned so that an edit form can keep it: a form cannot keep what it was
// never shown, and a box that opens empty reads as "nothing is trusted". That is
// safe only because it is a certificate, the public half of a cluster's own
// authority. The field is free text that was not always checked on the way in,
// and a cluster keeps the private half in the same directory as the public one,
// so a key pasted by mistake can already be stored. It is withheld here rather
// than sent to every response, event and audit row that renders a provider, and
// it is the same check that decides what is copied into a machine.
func certificateAuthority(text string) string {
	if strings.TrimSpace(text) == "" || CertificateProblem(text) != "" {
		return ""
	}
	return text
}

package controller

import (
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/pem"
	"math/big"
	"strings"
	"testing"
	"time"
)

func testCertificatePEM(t *testing.T, name string) string {
	t.Helper()
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	cert := &x509.Certificate{
		SerialNumber: big.NewInt(1), Subject: pkix.Name{CommonName: name},
		NotBefore: time.Now().Add(-time.Hour), NotAfter: time.Now().Add(time.Hour),
	}
	der, err := x509.CreateCertificate(rand.Reader, cert, cert, key.Public(), key)
	if err != nil {
		t.Fatal(err)
	}
	return string(pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der}))
}

// The certificate a provider trusts is returned so that a form can keep it, and
// that is safe only because it is a certificate. The field was never checked on
// the way in, so a key pasted into it by mistake (a cluster's authority keeps its
// private half beside the public one) can already be stored; it must never leave
// the controller in a response, an event or an audit row.
func TestOnlyACertificateIsEverReturnedAsTheAuthorityAProviderTrusts(t *testing.T) {
	one := testCertificatePEM(t, "pve-root-ca")
	two := testCertificatePEM(t, "pve-leaf")
	key := "-----BEGIN PRIVATE KEY-----\nbm90IGEgcmVhbCBrZXk=\n-----END PRIVATE KEY-----\n"

	for _, tc := range []struct {
		name string
		in   string
		want string
	}{
		{"nothing stored is nothing returned", "", ""},
		{"one certificate comes back as it was stored", one, one},
		{"a bundle of two comes back whole", one + two, one + two},
		{"a note above the certificate does not hide it", "pve-root-ca.pem\n" + one, "pve-root-ca.pem\n" + one},
		{"a private key is never returned", key, ""},
		{"a certificate with a key after it is not returned at all", one + key, ""},
		{"text that is no PEM at all is not returned", "this is not a certificate", ""},
		{"a block that is not a certificate inside is not returned", "-----BEGIN CERTIFICATE-----\nbm90IGEgY2VydGlmaWNhdGU=\n-----END CERTIFICATE-----\n", ""},
	} {
		t.Run(tc.name, func(t *testing.T) {
			got := certificateAuthority(tc.in)
			if got != tc.want {
				t.Errorf("certificateAuthority(%q) = %q, want %q", truncateForTest(tc.in), truncateForTest(got), truncateForTest(tc.want))
			}
			if strings.Contains(got, "PRIVATE KEY") {
				t.Errorf("a private key was returned: %q", truncateForTest(got))
			}
		})
	}
}

func truncateForTest(s string) string {
	if len(s) > 60 {
		return s[:60] + "..."
	}
	return s
}

// Each way text can fail to be a certificate has its own sentence, because the
// box it is pasted into is read by a person who has to know what to paste
// instead. None of them repeats the text: it may be a key.
func TestACertificateProblemIsSaidInWordsAndNeverEchoesTheText(t *testing.T) {
	good := testCertificatePEM(t, "pve-root-ca")
	key := "-----BEGIN PRIVATE KEY-----\nc2VjcmV0LWtleS1tYXRlcmlhbA==\n-----END PRIVATE KEY-----\n"

	for _, tc := range []struct {
		name string
		in   string
		want string // "" means there is nothing wrong
	}{
		{"nothing is fine, it means the system's trust", "", ""},
		{"blank text is the same as nothing", "  \n ", ""},
		{"one certificate is fine", good, ""},
		{"a bundle of certificates is fine", good + testCertificatePEM(t, "pve-leaf"), ""},
		{"a note above the certificate is fine", "pve-root-ca.pem\n" + good, ""},
		{"a private key is named as one", key, "private key"},
		{"a key after a certificate is still named", good + key, "private key"},
		{"an RSA key is named as a key too", "-----BEGIN RSA PRIVATE KEY-----\nc2VjcmV0LWtleS1tYXRlcmlhbA==\n-----END RSA PRIVATE KEY-----\n", "private key"},
		{"another kind of block is named by its type", "-----BEGIN CERTIFICATE REQUEST-----\nc2VjcmV0LWtleS1tYXRlcmlhbA==\n-----END CERTIFICATE REQUEST-----\n", "CERTIFICATE REQUEST"},
		{"a certificate that does not parse says so", "-----BEGIN CERTIFICATE-----\nc2VjcmV0LWtleS1tYXRlcmlhbA==\n-----END CERTIFICATE-----\n", "could not be read"},
		{"a block cut short is called damaged", "-----BEGIN CERTIFICATE-----\nc2VjcmV0LWtleS1tYXRlcmlhbA==", "cut short or damaged"},
		{"text with no PEM in it says what is expected", "this is not a certificate", "BEGIN CERTIFICATE"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			got := CertificateProblem(tc.in)
			if tc.want == "" {
				if got != "" {
					t.Fatalf("CertificateProblem found a problem with text that is fine: %s", got)
				}
				return
			}
			if !strings.Contains(got, tc.want) {
				t.Errorf("CertificateProblem = %q, want it to say %q", got, tc.want)
			}
			if strings.Contains(got, "c2VjcmV0LWtleS1tYXRlcmlhbA") || strings.Contains(got, "secret-key-material") {
				t.Errorf("the problem repeats the text it was given: %q", got)
			}
		})
	}
}

package controller

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"slices"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/provider"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// This file is the operator's half of the provider feature: the four questions
// a person asks that the reconciler never does -- what can this build rent
// from, are these answers sensible, does this credential actually work, and
// what is out there that no row accounts for.
//
// It lives here rather than in internal/api because every one of them needs a
// built provider, and building one needs the registry, the instance key and the
// operator's deadlines. The API is transport: it renders what these return and
// has no opinion about the fleet, which is why each of them answers in a view
// type rather than in provider's own vocabulary.

// ErrProviderKindUnknown is a provider row, or a draft, naming a kind this
// build has no driver for. It is a conflict rather than a validation failure
// for a stored row -- the row was legal when it was written -- and the message
// names the kind so an operator knows which build they need.
var ErrProviderKindUnknown = errors.New("this build has no driver for that provider kind")

// ErrDiscoveryUnsupported is a provider whose driver cannot list what a
// credential can see. The guided form asks the operator to type identifiers
// instead, so this is reported rather than hidden.
var ErrDiscoveryUnsupported = errors.New("this provider cannot list what its credential can see")

// ---------------------------------------------------------------------------
// The kinds this build ships
// ---------------------------------------------------------------------------

// ProviderKindView is one provider driver this build carries, with the
// questions its configuration form has to ask. The form, the CLI and
// docs/providers.md all render this one description, so a setting cannot
// appear in one of them and be missing from the others.
type ProviderKindView struct {
	Kind  store.ProviderKind `json:"kind"`
	Label string             `json:"label"`
	// Bootstrap says how the enrolment payload reaches a guest, which is the
	// one capability an operator has to care about before they buy anything:
	// "metadata" means the payload is readable by anyone who can read the
	// machine's metadata.
	Bootstrap        string `json:"bootstrap"`
	CanStartStop     bool   `json:"can_start_stop"`
	CanDiscover      bool   `json:"can_discover"`
	CanMarkOwnership bool   `json:"can_mark_ownership"`
	AsyncOperations  bool   `json:"async_operations"`
	CostUnit         string `json:"cost_unit,omitempty"`
	EndpointExample  string `json:"endpoint_example,omitempty"`
	// Where the three answers every kind is asked for are found, in the
	// provider's own console's terms.
	EndpointSource   string `json:"endpoint_source,omitempty"`
	CredentialSource string `json:"credential_source,omitempty"`
	CASource         string `json:"ca_source,omitempty"`
	// Guide is what has to exist before this kind can rent anything, in the
	// order it is done, so the wizard can say it before its first question.
	Guide    []ProviderGuideStepView `json:"guide"`
	Settings []ProviderSettingView   `json:"settings"`
}

// ProviderGuideStepView is one thing to do before a provider of a kind works.
type ProviderGuideStepView struct {
	Title   string `json:"title"`
	Detail  string `json:"detail,omitempty"`
	Command string `json:"command,omitempty"`
}

// ProviderSettingView is one answer a provider needs.
type ProviderSettingView struct {
	Key      string `json:"key"`
	Label    string `json:"label"`
	Kind     string `json:"kind"`
	Required bool   `json:"required"`
	Advanced bool   `json:"advanced"`
	Help     string `json:"help,omitempty"`
	// Consequence says what choosing this costs, in the voice the pool form
	// already uses. A list of identifiers with no consequences is a list
	// somebody guesses at.
	Consequence string `json:"consequence,omitempty"`
	Discovers   string `json:"discovers,omitempty"`
	Default     string `json:"default,omitempty"`
	// Source says where to find the answer when discovery cannot offer it.
	Source string `json:"source,omitempty"`
}

// ProviderKinds is every driver this build can speak, in the registry's stable
// order.
func (c *Controller) ProviderKinds() []ProviderKindView {
	kinds := c.providers.Kinds()
	out := make([]ProviderKindView, 0, len(kinds))
	for _, k := range kinds {
		f, err := c.providers.Get(k)
		if err != nil {
			continue
		}
		caps := f.Describe()
		v := ProviderKindView{
			Kind:             k,
			Label:            caps.Label,
			Bootstrap:        string(caps.Bootstrap),
			CanStartStop:     caps.CanStartStop,
			CanDiscover:      caps.CanDiscover,
			CanMarkOwnership: caps.CanMarkOwnership,
			AsyncOperations:  caps.AsyncOperations,
			CostUnit:         caps.CostUnit,
			EndpointExample:  caps.EndpointExample,
			EndpointSource:   caps.EndpointSource,
			CredentialSource: caps.CredentialSource,
			CASource:         caps.CASource,
			Guide:            make([]ProviderGuideStepView, 0, len(caps.Guide)),
			Settings:         make([]ProviderSettingView, 0, len(f.Settings())),
		}
		for _, step := range caps.Guide {
			v.Guide = append(v.Guide, ProviderGuideStepView{Title: step.Title, Detail: step.Detail, Command: step.Command})
		}
		for _, spec := range f.Settings() {
			v.Settings = append(v.Settings, ProviderSettingView{
				Key:         spec.Key,
				Label:       spec.Label,
				Kind:        string(spec.Kind),
				Required:    spec.Required,
				Advanced:    spec.Advanced,
				Help:        spec.Help,
				Consequence: spec.Consequence,
				Discovers:   spec.Discovers,
				Default:     spec.Default,
				Source:      spec.Source,
			})
		}
		out = append(out, v)
	}
	return out
}

// ProvidersAvailable reports whether this deployment can rent machines at all:
// a driver to rent from, and an operator who has switched provider.enabled on.
// The page that would otherwise offer to buy machines nothing would ever create
// asks this first.
func (c *Controller) ProvidersAvailable() bool {
	return len(c.providers.Kinds()) > 0 && c.cfg().Provider.Enabled
}

// ValidateProviderSettings runs a driver's own offline check over a draft's
// answers. It dials nothing and needs no credential, which is what lets the
// wizard run it as somebody types; CheckProvider is the call that talks to the
// hypervisor.
func (c *Controller) ValidateProviderSettings(kind store.ProviderKind, settings map[string]string) ([]config.Finding, error) {
	f, err := c.providers.Get(kind)
	if err != nil {
		return nil, fmt.Errorf("%w: %s", ErrProviderKindUnknown, kind)
	}
	return f.Validate(settings), nil
}

// ---------------------------------------------------------------------------
// The live preflight
// ---------------------------------------------------------------------------

// ProviderCheckView is a preflight result: whether the hypervisor answered,
// what it said it is, and everything an operator has to fix before a machine
// will ever be created. The findings are config.Finding so that "what is wrong
// with this provider" reads exactly like "what is wrong with this
// configuration", in the wizard, in the problems drawer and in the CLI.
type ProviderCheckView struct {
	ProviderID string           `json:"provider_id"`
	OK         bool             `json:"ok"`
	Reachable  bool             `json:"reachable"`
	Version    string           `json:"version,omitempty"`
	Findings   []config.Finding `json:"findings"`
	CheckedAt  time.Time        `json:"checked_at"`
}

// CheckProvider asks a provider what it would refuse, changing nothing.
//
// The result is recorded on the row as well as returned, because the page, the
// problems drawer and the reconciler's own "this template has not been verified
// since the configuration changed" warning all read it from there -- a check an
// operator ran in a terminal should quiet the warning the UI is showing.
func (c *Controller) CheckProvider(ctx context.Context, row *store.Provider) (ProviderCheckView, error) {
	pr, err := c.providerFor(ctx, row)
	if err != nil {
		return ProviderCheckView{}, providerBuildError(row, err)
	}
	callCtx, cancel := context.WithTimeout(ctx, c.stepTimeout(pr))
	defer cancel()
	report := pr.p.Preflight(callCtx)

	now := c.Now()
	out := ProviderCheckView{
		ProviderID: row.ID,
		OK:         report.OK(),
		Reachable:  report.Reachable,
		Version:    report.Version,
		Findings:   report.Findings,
		CheckedAt:  now,
	}
	if out.Findings == nil {
		out.Findings = []config.Finding{}
	}
	if f, ok := machineCertificateFinding(row); ok {
		out.Findings = append(out.Findings, f)
	}
	if f, ok := machineDiskFinding(row, report); ok {
		out.Findings = append(out.Findings, f)
	}
	// The recorded error is the worst thing the check found, in one sentence,
	// because that is what a card has room for; the findings are the whole of
	// it and are returned to the caller who asked.
	//
	// The whole result is kept too, because the sentence is only a title and
	// the detail that says what to do ("it offers vmbr1") would otherwise
	// exist for as long as one browser tab did.
	if err := c.st.SetProviderChecked(ctx, row.ID, now, checkComplaint(report), encodeCheckReport(out)); err != nil {
		c.log.Warn("could not record a provider check", "provider", row.ID, "error", err)
	}
	// The size a machine is built at when the row names none. It is what the
	// fit check judges a provider's next machine by until one of its machines
	// has joined and measured itself, and a check made after the template
	// changed is newer than any machine built before it. A template whose
	// disk the provider could not read reports none, which is not a smaller
	// disk, so the disk already known is carried rather than forgotten.
	if report.BuildsCPUs > 0 && report.BuildsMemoryMB > 0 {
		disk := report.BuildsDiskMB
		if disk <= 0 {
			disk = row.SeenDiskMB
		}
		if _, err := c.st.SetProviderMachineSizeSeen(ctx, row.ID, report.BuildsCPUs, report.BuildsMemoryMB,
			disk, store.MachineSizeFromTemplate, now); err != nil {
			c.log.Warn("could not record the size a provider builds", "provider", row.ID, "error", err)
		}
	}
	if fresh, err := c.st.GetProvider(ctx, row.ID); err == nil {
		c.PublishProvider(ctx, fresh)
	}
	return out, nil
}

// machineCertificateFinding warns of a provider whose machines are told to
// trust the certificate the controller uses for the hypervisor.
//
// A machine verifies the controller against its certificate and nothing else
// once one is set, and a cluster's own authority has no reason to have signed
// the controller. Set to the same text as the cluster's, it is almost always a
// copy: an upgrade that split the one field into two gave existing providers
// their cluster certificate here as well. The result is a machine that boots,
// is bootstrapped and never joins, with the cause visible only in its own log
// as "certificate signed by unknown authority".
func machineCertificateFinding(row *store.Provider) (config.Finding, bool) {
	machines := strings.TrimSpace(certificateAuthority(row.MachineCAPEM))
	if machines == "" || machines != strings.TrimSpace(certificateAuthority(row.CAPEM)) {
		return config.Finding{}, false
	}
	return config.Finding{
		Code:     "provider.machine_ca_same_as_cluster",
		Severity: config.SeverityWarning,
		Title:    "machines are told to trust only the cluster's certificate for this controller",
		Detail: "the certificate for machines is the same one this controller uses to reach the hypervisor. A machine " +
			"trusts the file it is given for the controller and nothing else, so unless the cluster's authority also " +
			"signed this controller's certificate, its agent will refuse the controller, never join, and log " +
			"\"certificate signed by unknown authority\".",
		Fix: "clear the certificate for machines if the controller is on a public certificate, or paste the authority " +
			"that signed the controller's certificate.",
	}, true
}

// machineDiskFinding warns of a provider whose machines have less disk than
// their slots are charged for.
//
// Each runner is given scheduler.RunnerDiskMB of working room above the host's
// own reserve, and a machine with less fills its disk part-way through a job,
// which fails with "no space left on device" long after the machine was rented
// and looked healthy. The disk is the shape's when the operator typed one, and
// otherwise what the template was seen to build; with neither there is nothing
// to judge, and a warning built on a guess would teach people to ignore the
// card.
func machineDiskFinding(row *store.Provider, report provider.Report) (config.Finding, bool) {
	disk := row.MachineDiskMB
	typed := disk > 0
	if !typed {
		disk = report.BuildsDiskMB
	}
	if disk <= 0 {
		// A check that could not read the template's disk is not evidence
		// that the disk is fine. What a machine or an earlier check measured
		// is what the scheduler judges the provider by, so the warning is
		// held to the same figure, or the card says nothing while the pool
		// page says the provider cannot serve.
		disk = row.SeenDiskMB
	}
	if disk <= 0 {
		return config.Finding{}, false
	}
	slots := providerSlots(row)
	need := store.MinHostReserveDiskMB + int64(slots)*scheduler.RunnerDiskMB
	if disk >= need {
		return config.Finding{}, false
	}
	fix := "raise the machine's disk to at least " + scheduler.FormatMB(need)
	if typed {
		fix += " or give the machine fewer slots."
	} else {
		fix += ", give the machine fewer slots, or enlarge the template it clones."
	}
	verb := "need"
	if slots == 1 {
		verb = "needs"
	}
	return config.Finding{
		Code:     "provider.machine_disk_small",
		Severity: config.SeverityWarning,
		Setting:  "machine_disk_mb",
		Title: fmt.Sprintf("the machines this provider builds have %s of disk, and %s %s %s",
			scheduler.FormatMB(disk), plural(slots, "runner"), verb, scheduler.FormatMB(need)),
		Detail: fmt.Sprintf("each runner is given %s of working room above the host's %s reserve. A job on a machine "+
			"with less fills the disk part-way through and fails with \"no space left on device\".",
			scheduler.FormatMB(scheduler.RunnerDiskMB), scheduler.FormatMB(store.MinHostReserveDiskMB)),
		Fix: fix,
	}, true
}

// storedCheck is what is kept of a preflight. The time and the provider are
// the row's own (last_check_at, id), so they are not stored a second time to
// disagree with it.
type storedCheck struct {
	OK        bool             `json:"ok"`
	Reachable bool             `json:"reachable"`
	Version   string           `json:"version,omitempty"`
	Findings  []config.Finding `json:"findings"`
}

func encodeCheckReport(v ProviderCheckView) string {
	b, err := json.Marshal(storedCheck{OK: v.OK, Reachable: v.Reachable, Version: v.Version, Findings: v.Findings})
	if err != nil {
		return ""
	}
	return string(b)
}

// decodeCheckReport reads back what encodeCheckReport kept, or nil when the
// provider has never been checked or the stored text is not a report. A row
// from before the report was kept reads as the second, which the page shows as
// its one sentence, as it always did.
func decodeCheckReport(p *store.Provider) *ProviderCheckView {
	if p.LastCheckReport == "" || p.LastCheckAt == nil {
		return nil
	}
	var s storedCheck
	if err := json.Unmarshal([]byte(p.LastCheckReport), &s); err != nil {
		return nil
	}
	if s.Findings == nil {
		s.Findings = []config.Finding{}
	}
	return &ProviderCheckView{ProviderID: p.ID, OK: s.OK, Reachable: s.Reachable,
		Version: s.Version, Findings: s.Findings, CheckedAt: *p.LastCheckAt}
}

// checkComplaint is the one sentence a preflight leaves on the row. A provider
// that could not be reached has one problem rather than eleven, so that is what
// it says; otherwise it is the first error, and warnings alone leave the row
// clean because they never stopped anything.
func checkComplaint(r provider.Report) string {
	if !r.Reachable {
		return "could not be reached"
	}
	for _, f := range r.Findings {
		if f.Severity == config.SeverityError {
			return f.Title
		}
	}
	return ""
}

// ---------------------------------------------------------------------------
// Discovery
// ---------------------------------------------------------------------------

// ProviderDiscoveryView is what a credential can actually see. A provider with
// no such concept leaves a list empty rather than inventing one.
type ProviderDiscoveryView struct {
	Nodes     []ProviderChoiceView `json:"nodes"`
	Storages  []ProviderChoiceView `json:"storages"`
	Bridges   []ProviderChoiceView `json:"bridges"`
	Templates []ProviderChoiceView `json:"templates"`
	// Unavailable is why the lists are empty when the provider could not be
	// asked: the address did not answer, the credential was refused. A draft
	// in a wizard is expected to be wrong at first, and a sentence beside the
	// form is what corrects it; the form asks for identifiers meanwhile.
	Unavailable string `json:"unavailable,omitempty"`
}

// ProviderChoiceView is one option in a guided form.
type ProviderChoiceView struct {
	Value       string `json:"value"`
	Label       string `json:"label,omitempty"`
	Consequence string `json:"consequence,omitempty"`
	// CPUs and MemoryMB are the size of a node's hardware or a template's
	// shape, for the limits step's arithmetic. Absent when the provider did
	// not say.
	CPUs     int   `json:"cpus,omitempty"`
	MemoryMB int64 `json:"memory_mb,omitempty"`
}

// DiscoverProvider asks a provider what this credential can see, so the form
// offers a menu rather than asking somebody to go and look an identifier up.
func (c *Controller) DiscoverProvider(ctx context.Context, row *store.Provider) (ProviderDiscoveryView, error) {
	pr, err := c.providerFor(ctx, row)
	if err != nil {
		return ProviderDiscoveryView{}, providerBuildError(row, err)
	}
	return c.discover(ctx, pr)
}

// DiscoverDraft asks a provider that has not been saved what its credential
// can see, so the wizard can offer the nodes, storages, bridges and templates
// as a menu before there is a row to save them on.
//
// The secrets arrive in plaintext because there is no row to unseal them
// from, and they go nowhere: the client is built for this one call and
// dropped, and a private connection opened for it is closed with it. Nothing
// is cached, because a draft has no identity to cache under and its
// credential may be about to be corrected.
func (c *Controller) DiscoverDraft(ctx context.Context, row *store.Provider, credential, address string) (ProviderDiscoveryView, error) {
	if address != "" && !c.cfg().Server.TailcatEnabled {
		return ProviderDiscoveryView{}, errPrivateConnectionsDisabled(row)
	}
	f, err := c.providers.Get(row.Kind)
	if err != nil {
		return ProviderDiscoveryView{}, providerBuildError(row, err)
	}
	if dd, ok := f.(provider.DraftDiscoverer); ok {
		// The address and the credential are enough: the placement answers
		// a built provider would insist on are the ones the menu is for.
		cfg, tunnel, err := c.providerConfig(row, credential, address)
		if err != nil {
			return ProviderDiscoveryView{}, err
		}
		if tunnel != nil {
			defer tunnel.Close()
		}
		callCtx, cancel := context.WithTimeout(ctx, c.providerDeadlines().Call)
		defer cancel()
		got, err := dd.DiscoverDraft(callCtx, cfg)
		if err != nil {
			return ProviderDiscoveryView{}, err
		}
		return discoveryView(got), nil
	}
	p, tunnel, err := c.buildProvider(ctx, row, credential, address)
	if err != nil {
		return ProviderDiscoveryView{}, providerBuildError(row, err)
	}
	if tunnel != nil {
		defer tunnel.Close()
	}
	return c.discover(ctx, &machineProvider{row: row, p: p})
}

func (c *Controller) discover(ctx context.Context, pr *machineProvider) (ProviderDiscoveryView, error) {
	row := pr.row
	d, ok := pr.p.(provider.Discoverer)
	if !ok {
		return ProviderDiscoveryView{}, fmt.Errorf("%w: %s is a %s provider", ErrDiscoveryUnsupported, row.Name, row.Kind)
	}
	callCtx, cancel := context.WithTimeout(ctx, c.stepTimeout(pr))
	defer cancel()
	got, err := d.Discover(callCtx)
	if err != nil {
		return ProviderDiscoveryView{}, err
	}
	return discoveryView(got), nil
}

func discoveryView(got provider.Discovery) ProviderDiscoveryView {
	return ProviderDiscoveryView{
		Nodes:     choiceViews(got.Nodes),
		Storages:  choiceViews(got.Storages),
		Bridges:   choiceViews(got.Bridges),
		Templates: choiceViews(got.Templates),
	}
}

func choiceViews(in []provider.Choice) []ProviderChoiceView {
	out := make([]ProviderChoiceView, 0, len(in))
	for _, c := range in {
		out = append(out, ProviderChoiceView{Value: c.Value, Label: c.Label, Consequence: c.Consequence, CPUs: c.CPUs, MemoryMB: c.MemoryMB})
	}
	return out
}

// providerBuildError explains a provider that could not be built at all, which
// is a different failure from one that answered badly: the credential would not
// unseal, or this build has no driver for the row's kind.
func providerBuildError(row *store.Provider, err error) error {
	if errors.Is(err, provider.ErrUnsupported) {
		return fmt.Errorf("%w: %s is a %s provider", ErrProviderKindUnknown, row.Name, row.Kind)
	}
	return err
}

// ---------------------------------------------------------------------------
// The orphan review
// ---------------------------------------------------------------------------

// OrphanReportView is the review page in one answer: the three ways a row and a
// resource can fail to agree. Nothing here is ever acted on automatically --
// each section is a list of things for a person to look at, and the only
// destructive act on the page asks for a name to be typed.
type OrphanReportView struct {
	ProviderID   string     `json:"provider_id"`
	ProviderName string     `json:"provider_name"`
	LastSweepAt  *time.Time `json:"last_sweep_at,omitempty"`
	// Untracked is a resource wearing this fleet's naming grammar that no row
	// accounts for. It is never deleted from here: the row is the only record
	// of what was rented, and a resource with no row may be another fleet's.
	Untracked []OrphanView `json:"untracked"`
	// NoResource is a row that believes it holds nothing, which is a row an
	// operator can release without anything being lost.
	NoResource []MachineView `json:"no_resource"`
	// Unverified is a machine whose ownership nothing has confirmed, including
	// every quarantined one. Until a person decides, nothing will touch them.
	Unverified []MachineView `json:"unverified"`
}

// OrphanView is one untracked resource, as the last sweep saw it.
type OrphanView struct {
	Name string `json:"name"`
	// Note is what an operator should do about it, which for an untracked
	// resource is always "look at it yourself": Zoomies will not delete a
	// machine it has no record of creating.
	Note string `json:"note"`
}

// OrphanReport gathers a provider's three disagreements. The untracked half
// comes from the last ownership sweep rather than from a call made now, because
// the page is read far more often than the hypervisor should be asked -- the
// sweep's own timestamp is returned so a stale answer says so.
func (c *Controller) OrphanReport(ctx context.Context, row *store.Provider) (OrphanReportView, error) {
	machines, err := c.st.ListMachinesForProvider(ctx, row.ID)
	if err != nil {
		return OrphanReportView{}, fmt.Errorf("listing the provider's machines: %w", err)
	}
	renderer, err := c.MachineRenderer(ctx)
	if err != nil {
		return OrphanReportView{}, err
	}
	out := OrphanReportView{
		ProviderID:   row.ID,
		ProviderName: row.Name,
		LastSweepAt:  row.LastSweepAt,
		Untracked:    []OrphanView{},
		NoResource:   []MachineView{},
		Unverified:   []MachineView{},
	}
	names := c.ProviderOrphans()[row.ID]
	slices.Sort(names)
	for _, name := range names {
		out.Untracked = append(out.Untracked, OrphanView{
			Name: name,
			Note: "this resource wears the naming Zoomies gives its machines but no row accounts for it. " +
				"Zoomies will never delete it; look at it in " + row.Name + " and remove it there if it is yours and idle.",
		})
	}
	for _, m := range machines {
		switch {
		case m.State == store.MachineDeleted:
			// History. The resource is confirmed gone and the row goes with
			// the next prune.
		case !m.Owns():
			out.NoResource = append(out.NoResource, renderer.View(m))
		case m.State == store.MachineQuarantined || m.OwnershipError != "" || m.OwnershipVerifiedAt == nil:
			out.Unverified = append(out.Unverified, renderer.View(m))
		}
	}
	return out, nil
}

package controller

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/provider"
	"github.com/eyupio/zoomies/internal/store"
)

// The detail and the fix are what an operator acts on; the title on the card is
// only what they are about. A stored check that dropped them would send the
// operator back to pressing Check on every page load.
func TestAStoredCheckKeepsEachFindingsDetailAndFix(t *testing.T) {
	when := time.Date(2026, 10, 9, 9, 0, 0, 0, time.UTC)
	view := ProviderCheckView{
		ProviderID: "prov_1", OK: false, Reachable: true, Version: "9.1.4", CheckedAt: when,
		Findings: []config.Finding{{
			Code: "proxmox.bridge_missing", Severity: config.SeverityError,
			Title:  `node pve1 has no bridge called "vmbr0"`,
			Detail: "It offers vmbr1.", Fix: "use a bridge that exists on every node.",
		}},
	}
	row := &store.Provider{ID: "prov_1", LastCheckAt: &when, LastCheckReport: encodeCheckReport(view)}

	got := decodeCheckReport(row)
	if got == nil {
		t.Fatal("a stored report read back as nothing")
	}
	if len(got.Findings) != 1 || got.Findings[0].Detail != "It offers vmbr1." || got.Findings[0].Fix == "" {
		t.Errorf("the finding lost its detail or its fix: %+v", got.Findings)
	}
	if got.Version != "9.1.4" || !got.Reachable || got.OK || !got.CheckedAt.Equal(when) {
		t.Errorf("the verdict changed on the way through: %+v", got)
	}
}

// A row last checked before the report was kept, or one holding text that is
// not a report, must read as "no report" and leave the card on its sentence.
func TestAProviderWithNoUsableStoredCheckReadsAsNone(t *testing.T) {
	when := time.Now()
	for name, row := range map[string]*store.Provider{
		"never checked":             {ID: "p"},
		"checked before the report": {ID: "p", LastCheckAt: &when},
		"not json":                  {ID: "p", LastCheckAt: &when, LastCheckReport: "{"},
	} {
		if got := decodeCheckReport(row); got != nil {
			t.Errorf("%s: read back %+v", name, got)
		}
	}
}

// A shape that is too small for its slots is the failure an operator finds out
// about from a job dying with "no space left on device", an hour after the
// machine was rented. The check says so while nothing is running on it.
func TestTheCheckWarnsWhenAShapeIsTooSmallForItsSlots(t *testing.T) {
	row := &store.Provider{MachineCapacity: 2}
	got, ok := machineDiskFinding(row, provider.Report{BuildsDiskMB: 8192})
	if !ok {
		t.Fatal("no finding for two slots on an 8 GB disk")
	}
	if got.Code != "provider.machine_disk_small" || got.Severity != config.SeverityWarning || got.Setting != "machine_disk_mb" {
		t.Errorf("finding = %+v, want the warning provider.machine_disk_small on machine_disk_mb", got)
	}
	// 2048 reserve + 2 * 10240 working room.
	if !strings.Contains(got.Title, "8 GB") || !strings.Contains(got.Title, "22 GB") || !strings.Contains(got.Title, "2 runners need ") {
		t.Errorf("title = %q, want the disk it has (8 GB), what 2 runners need (22 GB)", got.Title)
	}
	if !strings.Contains(got.Detail, "no space left on device") {
		t.Errorf("detail = %q, want the failure the operator would otherwise meet", got.Detail)
	}
	if !strings.Contains(got.Fix, "disk") || !strings.Contains(got.Fix, "slots") || !strings.Contains(got.Fix, "template") {
		t.Errorf("fix = %q, want the disk, the slots and the template as the three ways out", got.Fix)
	}
}

// A disk the operator typed is not the template's to change, so the fix does
// not send them to enlarge it.
func TestTheCheckDoesNotSuggestEnlargingTheTemplateForADiskTheShapeTyped(t *testing.T) {
	row := &store.Provider{MachineCapacity: 2, MachineDiskMB: 8192}
	got, ok := machineDiskFinding(row, provider.Report{BuildsDiskMB: 100_000})
	if !ok {
		t.Fatal("no finding for two slots on a typed 8 GB disk")
	}
	if strings.Contains(got.Fix, "template") {
		t.Errorf("fix = %q, want no template clause when the shape typed the disk", got.Fix)
	}
}

// A check that could not read the template's disk does not unsay what a
// machine measured. The scheduler judges the provider by the learned figure,
// so a card that went quiet on the same figure would contradict the pool page.
func TestTheCheckWarnsOnTheDiskAMachineMeasuredWhenItCannotReadTheTemplates(t *testing.T) {
	row := &store.Provider{MachineCapacity: 2, SeenDiskMB: 8192}
	got, ok := machineDiskFinding(row, provider.Report{})
	if !ok {
		t.Fatal("no finding for two slots on a measured 8 GB disk the check could not re-read")
	}
	if !strings.Contains(got.Title, "8 GB") || !strings.Contains(got.Title, "22 GB") {
		t.Errorf("title = %q, want the measured 8 GB against the 22 GB two runners need", got.Title)
	}
}

// Silence is right when nothing says how big the disk is: a warning built on a
// guess would be one the operator learns to ignore.
func TestTheCheckIsSilentWhenNothingSaysTheDisk(t *testing.T) {
	if f, ok := machineDiskFinding(&store.Provider{MachineCapacity: 4}, provider.Report{}); ok {
		t.Fatalf("a finding with no disk figure: %+v", f)
	}
}

func TestTheCheckCountsAShapeWithNoSlotsAsOne(t *testing.T) {
	// 2048 reserve + one runner's 10240.
	if f, ok := machineDiskFinding(&store.Provider{MachineDiskMB: 12288}, provider.Report{}); ok {
		t.Errorf("12288 MB is enough for one slot, got %+v", f)
	}
	f, ok := machineDiskFinding(&store.Provider{MachineDiskMB: 12287}, provider.Report{})
	if !ok {
		t.Fatal("12287 MB is a megabyte short of one slot and drew no finding")
	}
	if !strings.Contains(f.Title, "1 runner needs ") {
		t.Errorf("title = %q, want the single runner counted in the singular, verb and all", f.Title)
	}
}

package controller

import (
	"context"
	"errors"

	"github.com/eyupio/zoomies/internal/store"
)

func (c *Controller) ControlProvisioning(ctx context.Context, ids []string, action string) ([]store.ProvisioningResult, error) {
	// Serialize with snapshot AND apply, so an old plan cannot create runners
	// after a pause has been acknowledged. Already-issued tasks are unaffected.
	c.reconcileMu.Lock()
	defer c.reconcileMu.Unlock()
	results, err := c.st.ControlProvisioning(ctx, ids, action)
	if err != nil {
		return nil, err
	}
	for _, result := range results {
		if result.OK {
			if j, err := c.st.GetJob(ctx, result.ID); err == nil {
				c.publishJob(ctx, j)
			}
		}
	}
	c.Nudge()
	return results, nil
}

// ErrRunHasNoQueuedJobs is a run-level provisioning action on a run none of
// whose jobs is waiting for a runner here: every job has started or finished,
// or the ones still queued were removed from the queue and are restored from
// the Queue page rather than swept back in with their siblings.
var ErrRunHasNoQueuedJobs = errors.New("no job of this workflow run is queued for this fleet")

// runProvisioningStates is what a run-level action reaches: the run's queued
// jobs in every provisioning state but removed. See RunJobCounts.Controllable.
var runProvisioningStates = []string{"ready", "expedited", store.ProvisioningPaused}

// ControlWorkflowRunProvisioning is ControlProvisioning for every queued job
// of one run: what the Workflows page's run rows call, since a run has no ID
// of its own to select by, only repo + GitHub's run ID.
//
// store.ErrNotFound for a run this fleet has never heard of, and
// ErrRunHasNoQueuedJobs when it knows the run but nothing in it is waiting
// for a runner here -- the two are different answers for an operator, and a
// 200 with no results would read as a button that did nothing.
func (c *Controller) ControlWorkflowRunProvisioning(ctx context.Context, repo string, runID int64, action string) ([]store.ProvisioningResult, error) {
	jobs, err := c.st.ListJobsForRun(ctx, repo, runID)
	if err != nil {
		return nil, err
	}
	if len(jobs) == 0 {
		return nil, store.ErrNotFound
	}
	ids, err := c.st.ProvisioningSelection(ctx, store.JobFilter{
		Repos:        []string{repo},
		RunIDs:       []int64{runID},
		Provisioning: runProvisioningStates,
	})
	if err != nil {
		return nil, err
	}
	if len(ids) == 0 {
		return nil, ErrRunHasNoQueuedJobs
	}
	return c.ControlProvisioning(ctx, ids, action)
}

package controller

import (
	"errors"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/store"
)

// The prune loop is the only caller of five delete queries, and its shape
// carries two rules that live nowhere else: a zero window means keep
// everything, and a pruned runner is announced so the Runners page stops
// showing rows that no longer exist. Neither was tested, and both fail
// silently: history that quietly disappears looks like history nobody wrote,
// and a stale page looks like a page nobody reloaded.
func TestPruningHonoursEachWindowAndKeepsEverythingWhenOneIsZero(t *testing.T) {
	h := newHarness(t)
	_, pool, _ := h.fleet()
	now := h.c.Now()

	seed := func() {
		t.Helper()
		if err := h.st.AppendScalingEvent(h.ctx, &store.ScalingEvent{
			PoolID: pool.ID, PoolName: pool.Name, To: 1, Reason: "old",
			CreatedAt: now.Add(-48 * time.Hour),
		}); err != nil {
			t.Fatalf("AppendScalingEvent: %v", err)
		}
		if err := h.st.RecordSample(h.ctx, store.FleetSample{At: now.Add(-48 * time.Hour), TotalRunners: 1}); err != nil {
			t.Fatalf("RecordSample: %v", err)
		}
		if err := h.st.RecordDelivery(h.ctx, &store.WebhookDelivery{
			DeliveryID: "old", Event: "workflow_job", Status: "accepted",
			ReceivedAt: now.Add(-48 * time.Hour),
		}); err != nil {
			t.Fatalf("RecordDelivery: %v", err)
		}
	}

	// A cleared window means "keep everything", which is what an operator who
	// emptied the setting meant -- not "delete everything older than now".
	h.c.UpdateConfig(func(c *config.Config) {
		c.Retention = config.Retention{}
	})
	seed()
	h.c.prune(h.ctx)

	events, err := h.st.ListScalingEvents(h.ctx, "", 10)
	if err != nil {
		t.Fatalf("ListScalingEvents: %v", err)
	}
	samples, err := h.st.ListSamples(h.ctx, now.Add(-72*time.Hour))
	if err != nil {
		t.Fatalf("ListSamples: %v", err)
	}
	deliveries, err := h.st.ListDeliveries(h.ctx, "", 10)
	if err != nil {
		t.Fatalf("ListDeliveries: %v", err)
	}
	if len(events) != 1 || len(samples) != 1 || len(deliveries) != 1 {
		t.Fatalf("a zero window deleted history: %d scaling events, %d samples, %d deliveries left, want 1 of each",
			len(events), len(samples), len(deliveries))
	}

	// And a window that is set takes exactly what is older than it.
	h.c.UpdateConfig(func(c *config.Config) {
		c.Retention = config.Retention{
			ScalingEvents: 24 * time.Hour, Samples: 24 * time.Hour, Webhooks: 24 * time.Hour,
			Jobs: 24 * time.Hour, Runners: 24 * time.Hour,
		}
	})
	h.c.prune(h.ctx)

	if events, err = h.st.ListScalingEvents(h.ctx, "", 10); err != nil || len(events) != 0 {
		t.Errorf("scaling events after the prune = %d (err %v), want none: they follow the scaling-events window", len(events), err)
	}
	if samples, err = h.st.ListSamples(h.ctx, now.Add(-72*time.Hour)); err != nil || len(samples) != 0 {
		t.Errorf("samples after the prune = %d (err %v), want none", len(samples), err)
	}
	if deliveries, err = h.st.ListDeliveries(h.ctx, "", 10); err != nil || len(deliveries) != 0 {
		t.Errorf("deliveries after the prune = %d (err %v), want none", len(deliveries), err)
	}
}

// Every pruned runner is announced. The delete happens in the database, which
// tells nobody, so without this the Runners page keeps showing runners that
// were deleted an hour ago until somebody reloads it.
func TestAPrunedRunnerIsAnnounced(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerIdle)
	if _, err := h.st.TransitionRunner(h.ctx, r.ID, store.RunnerRemoved, "removed"); err != nil {
		t.Fatalf("TransitionRunner: %v", err)
	}

	sub := h.listen(events.KindRunnerDeleted)

	// An hour of retention and an hour on the clock: the row is old enough to
	// go without the test having to wait for it.
	h.c.UpdateConfig(func(c *config.Config) {
		c.Retention = config.Retention{Runners: time.Hour}
	})
	h.advance(2 * time.Hour)
	h.c.prune(h.ctx)

	select {
	case <-sub.C:
	case <-time.After(2 * time.Second):
		t.Fatal("the pruned runner was never announced; every open Runners page still shows it")
	}
}

// A prune that takes thousands of rows must not take every open tab with it.
//
// A subscriber's queue is 256 deep and the bus drops a subscriber that falls
// behind. The hourly prune deletes everything past the retention window in one
// pass, and announcing each row filled that queue several times over: every
// tab was cut off, showed itself as disconnected, reconnected and refetched six
// endpoints. The storm was the announcement rather than the deletion, so the
// announcement is bounded.
func TestABulkPruneAnnouncesOnceRatherThanDroppingEverySubscriber(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()

	for i := range announceEach + 5 {
		r := h.runnerRow(pool, host, store.RunnerIdle)
		if _, err := h.st.TransitionRunner(h.ctx, r.ID, store.RunnerRemoved, "removed"); err != nil {
			t.Fatalf("TransitionRunner %d: %v", i, err)
		}
	}

	sub := h.listen(events.KindRunnerDeleted, events.KindResync)
	h.c.UpdateConfig(func(c *config.Config) {
		c.Retention = config.Retention{Runners: time.Hour}
	})
	h.advance(2 * time.Hour)
	h.c.prune(h.ctx)

	// One frame, and it is the one that means "fetch the resources again".
	select {
	case ev := <-sub.C:
		if ev.Kind != events.KindResync {
			t.Fatalf("the first frame was %q; a row-by-row announcement of a bulk prune fills every subscriber's queue and cuts it off", ev.Kind)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("a bulk prune announced nothing at all, so every open page keeps showing rows that are gone")
	}
	select {
	case ev := <-sub.C:
		t.Fatalf("a second frame (%q) followed the resync; one is the whole point", ev.Kind)
	case <-time.After(200 * time.Millisecond):
	}
}

// A machine's row outlives its resource on purpose: it is the only record of
// what was rented, when, and what it cost, and an operator reconciling a
// hypervisor bill against the fleet is reading exactly that. What retention
// takes is the confirmed-gone rows, and never one that still names a resource.
func TestPruningKeepsEveryMachineThatMayStillHaveAResource(t *testing.T) {
	h := newHarness(t)
	row := h.providerRow(t, "lab")
	now := h.c.Now()

	gone := &store.Machine{ProviderID: row.ID, State: store.MachinePlanned}
	if err := h.st.CreateMachine(h.ctx, gone); err != nil {
		t.Fatalf("CreateMachine: %v", err)
	}
	if err := h.st.SetMachineResource(h.ctx, gone.ID, "zone-a", "143", "fp", "ctl_test"); err != nil {
		t.Fatalf("SetMachineResource: %v", err)
	}
	if _, err := h.st.ConfirmMachineDeleted(h.ctx, gone.ID, now.Add(-48*time.Hour)); err != nil {
		t.Fatalf("ConfirmMachineDeleted: %v", err)
	}
	for _, to := range []store.MachineState{store.MachineFailed, store.MachineDeleted} {
		if _, err := h.st.TransitionMachine(h.ctx, gone.ID, to, ""); err != nil {
			t.Fatalf("TransitionMachine(%s): %v", to, err)
		}
	}

	// Failed, old, and still naming a resource: the one row a prune must never
	// take, because deleting it is how a fleet loses a machine it is paying for.
	kept := &store.Machine{ProviderID: row.ID, State: store.MachinePlanned}
	if err := h.st.CreateMachine(h.ctx, kept); err != nil {
		t.Fatalf("CreateMachine: %v", err)
	}
	if err := h.st.SetMachineResource(h.ctx, kept.ID, "zone-a", "144", "fp", "ctl_test"); err != nil {
		t.Fatalf("SetMachineResource: %v", err)
	}
	if _, err := h.st.TransitionMachine(h.ctx, kept.ID, store.MachineFailed, "the guest never joined"); err != nil {
		t.Fatalf("TransitionMachine: %v", err)
	}

	h.c.UpdateConfig(func(c *config.Config) { c.Retention = config.Retention{Machines: 24 * time.Hour} })
	h.c.prune(h.ctx)

	if _, err := h.st.GetMachine(h.ctx, gone.ID); !errors.Is(err, store.ErrNotFound) {
		t.Errorf("a machine confirmed gone 48 hours ago survived a 24-hour window: %v", err)
	}
	if _, err := h.st.GetMachine(h.ctx, kept.ID); err != nil {
		t.Errorf("a failed machine that still names a resource was pruned: %v", err)
	}
}

// An update that is still in flight is the only record that one is, and the
// controller's timeout is what closes it, not its age. The finished ones are
// history and follow retention.update_attempts.
func TestPruningTakesOldUpdateAttemptsButNeverAnOpenOne(t *testing.T) {
	h := newHarness(t)
	finished := &store.UpdateAttempt{Scope: store.UpdateScopeHost, HostID: "host_a", ToVersion: "v1.3.5", Trigger: store.UpdateTriggerManual}
	open := &store.UpdateAttempt{Scope: store.UpdateScopeController, ToVersion: "v1.3.5", Trigger: store.UpdateTriggerManual}
	for _, a := range []*store.UpdateAttempt{finished, open} {
		if err := h.st.CreateUpdateAttempt(h.ctx, a); err != nil {
			t.Fatalf("CreateUpdateAttempt: %v", err)
		}
	}
	if ok, err := h.st.FinishUpdateAttempt(h.ctx, finished.ID, store.UpdateSucceeded, ""); err != nil || !ok {
		t.Fatalf("FinishUpdateAttempt = %v, %v", ok, err)
	}

	h.c.UpdateConfig(func(c *config.Config) { c.Retention = config.Retention{UpdateAttempts: 24 * time.Hour} })
	h.advance(12 * time.Hour)
	h.c.prune(h.ctx)
	if got, err := h.st.ListUpdateAttempts(h.ctx, "", "", 10); err != nil || len(got) != 2 {
		t.Fatalf("inside the window %d attempts remain (%v), want both", len(got), err)
	}

	h.advance(48 * time.Hour)
	h.c.prune(h.ctx)
	got, err := h.st.ListUpdateAttempts(h.ctx, "", "", 10)
	if err != nil || len(got) != 1 || got[0].ID != open.ID {
		t.Fatalf("after the window %+v remain (%v), want only the open attempt", got, err)
	}
}

// Two failures on the release a host would be taken to hand it to an
// operator. The retention pass must not count them down to none: it keeps the
// failures on the hosts' target, and lets one on an older release go.
func TestPruningKeepsTheFailuresThatHandAHostToAnOperator(t *testing.T) {
	withVersion(t, "1.3.5")
	h := newHarness(t)
	for _, to := range []string{"v1.3.5", "v1.3.5", "v1.3.4"} {
		a := &store.UpdateAttempt{Scope: store.UpdateScopeHost, HostID: "host_a", ToVersion: to, Trigger: store.UpdateTriggerAuto}
		if err := h.st.CreateUpdateAttempt(h.ctx, a); err != nil {
			t.Fatalf("CreateUpdateAttempt: %v", err)
		}
		if ok, err := h.st.FinishUpdateAttempt(h.ctx, a.ID, store.UpdateFailed, "no space left on device"); err != nil || !ok {
			t.Fatalf("FinishUpdateAttempt = %v, %v", ok, err)
		}
	}

	h.c.UpdateConfig(func(c *config.Config) { c.Retention = config.Retention{UpdateAttempts: 24 * time.Hour} })
	h.advance(60 * time.Hour)
	h.c.prune(h.ctx)
	got, err := h.st.ListUpdateAttempts(h.ctx, "", "", 10)
	if err != nil || len(got) != 2 {
		t.Fatalf("after the window %+v remain (%v), want the two failures on v1.3.5", got, err)
	}
	for _, a := range got {
		if a.ToVersion != "v1.3.5" {
			t.Errorf("the failure on %s survived the window, want only the target's kept", a.ToVersion)
		}
	}
}

// With updating off the release list is not read, so the planner's choice
// names nothing. A controller's failures on the release it last tried must
// still outlive the window, or turning updating back on would find the cap
// counted down and ask the helper a third time.
func TestPruningKeepsTheControllersLastFailuresWhileUpdatingIsOff(t *testing.T) {
	withVersion(t, "1.3.5")
	h := newHarness(t)
	h.inMode("off")
	var failed []string
	for range 2 {
		a := &store.UpdateAttempt{Scope: store.UpdateScopeController, ToVersion: "v1.3.6", Trigger: store.UpdateTriggerAuto}
		if err := h.st.CreateUpdateAttempt(h.ctx, a); err != nil {
			t.Fatalf("CreateUpdateAttempt: %v", err)
		}
		if ok, err := h.st.FinishUpdateAttempt(h.ctx, a.ID, store.UpdateFailed, "the download failed"); err != nil || !ok {
			t.Fatalf("FinishUpdateAttempt = %v, %v", ok, err)
		}
		failed = append(failed, a.ID)
	}

	h.c.UpdateConfig(func(c *config.Config) { c.Retention = config.Retention{UpdateAttempts: 24 * time.Hour} })
	h.advance(60 * time.Hour)
	h.c.prune(h.ctx)
	got, err := h.st.ListUpdateAttempts(h.ctx, store.UpdateScopeController, "", 10)
	if err != nil || len(got) != len(failed) {
		t.Fatalf("after the window with updating off %+v remain (%v), want both failures on v1.3.6", got, err)
	}
}

// A halted rollout is a fleet waiting for a person, and the only record that
// it is. It follows retention.update_attempts once it has ended, like the
// attempts it was made of, and not before.
func TestPruningTakesOldRolloutsButNeverAnOpenOne(t *testing.T) {
	h := newHarness(t)
	finished := &store.UpdateRollout{Target: "v1.3.5", Trigger: store.UpdateTriggerManual}
	if err := h.st.CreateUpdateRollout(h.ctx, finished); err != nil {
		t.Fatalf("CreateUpdateRollout: %v", err)
	}
	if ok, err := h.st.FinishUpdateRollout(h.ctx, finished.ID, store.RolloutDone); err != nil || !ok {
		t.Fatalf("FinishUpdateRollout = %v, %v", ok, err)
	}
	open := &store.UpdateRollout{Target: "v1.3.6", Trigger: store.UpdateTriggerAuto}
	if err := h.st.CreateUpdateRollout(h.ctx, open); err != nil {
		t.Fatalf("CreateUpdateRollout: %v", err)
	}
	if ok, err := h.st.HaltUpdateRollout(h.ctx, open.ID, "a host did not come back"); err != nil || !ok {
		t.Fatalf("HaltUpdateRollout = %v, %v", ok, err)
	}

	h.c.UpdateConfig(func(c *config.Config) { c.Retention = config.Retention{UpdateAttempts: 24 * time.Hour} })
	h.advance(12 * time.Hour)
	h.c.prune(h.ctx)
	if got, err := h.st.OpenUpdateRollout(h.ctx); err != nil || got.ID != open.ID {
		t.Fatalf("inside the window the open rollout = %+v (%v), want it kept", got, err)
	}

	h.advance(48 * time.Hour)
	h.c.prune(h.ctx)
	if got, err := h.st.OpenUpdateRollout(h.ctx); err != nil || got.ID != open.ID || got.State != store.RolloutHalted {
		t.Fatalf("after the window the open rollout = %+v (%v), want the halted one kept", got, err)
	}
	// Cancelling the open one makes it prunable, so a cutoff a year out takes
	// exactly one row: the finished rollout went in the pass above.
	if ok, err := h.st.FinishUpdateRollout(h.ctx, open.ID, store.RolloutCancelled); err != nil || !ok {
		t.Fatalf("FinishUpdateRollout = %v, %v", ok, err)
	}
	if n, err := h.st.PruneUpdateRollouts(h.ctx, time.Now().Add(365*24*time.Hour)); err != nil || n != 1 {
		t.Errorf("PruneUpdateRollouts = %d, %v, want only the rollout just cancelled to remain", n, err)
	}
}

// The prune pass is what rolls usage up. Without it the roll-up never moves,
// the report falls back to rows a week's retention has already taken, and last
// month's runner-hours quietly disappear.
func TestPruningRollsUsageUpSoARunnerOutlivesItsRow(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := &store.Runner{PoolID: pool.ID, HostID: host.ID, Name: "rolled-up"}
	if err := h.st.CreateRunner(h.ctx, r); err != nil {
		t.Fatalf("CreateRunner: %v", err)
	}
	for _, to := range []store.RunnerState{store.RunnerRegistering, store.RunnerRemoved} {
		if _, err := h.st.TransitionRunner(h.ctx, r.ID, to, ""); err != nil {
			t.Fatalf("TransitionRunner(%s): %v", to, err)
		}
	}
	for _, side := range []bool{true, false} {
		if _, err := h.st.ConfirmRunnerCleanup(h.ctx, r.ID, side); err != nil {
			t.Fatalf("ConfirmRunnerCleanup: %v", err)
		}
	}

	h.advance(10 * 24 * time.Hour)
	h.c.UpdateConfig(func(c *config.Config) { c.Retention = config.Retention{Runners: 7 * 24 * time.Hour} })
	h.c.prune(h.ctx)

	if _, err := h.st.GetRunner(h.ctx, r.ID); !errors.Is(err, store.ErrNotFound) {
		t.Fatalf("a runner ten days gone survived a seven-day window: %v", err)
	}
	_, until, ok, err := h.st.UsageRollupRange(h.ctx)
	if err != nil || !ok || until.Before(h.c.Now().Add(-24*time.Hour)) {
		t.Fatalf("the prune did not roll usage up to today: until %v, ok %v, %v", until, ok, err)
	}
}

// A job the jobs retention takes is counted in the installation report's
// roll-up by the same pass, so a month's report still has it. The pass that
// could prune it before counting it -- a roll-up that failed, or one that has
// not reached its day -- prunes nothing instead.
func TestPruningCountsAJobForTheInstallationReportBeforeDeletingIt(t *testing.T) {
	h := newHarness(t)
	inst, pool, _ := h.fleet()
	queued := h.c.Now()
	done := queued.Add(time.Minute)
	if _, err := h.st.UpsertJob(h.ctx, &store.Job{GitHubJobID: 77, Repo: "acme/app", State: store.JobCompleted,
		Matched: true, InstallationID: inst.ID, PoolID: pool.ID, QueuedAt: queued, StartedAt: &done,
		CompletedAt: &done, RunnerName: "GitHub Actions 1"}); err != nil {
		t.Fatalf("UpsertJob: %v", err)
	}

	h.advance(10 * 24 * time.Hour)
	h.c.UpdateConfig(func(c *config.Config) { c.Retention = config.Retention{Jobs: 7 * 24 * time.Hour} })
	h.c.prune(h.ctx)

	if _, n, err := h.st.ListJobs(h.ctx, store.JobFilter{}, store.Page{Limit: 10}); err != nil || n != 0 {
		t.Fatalf("%d jobs left after a seven-day window, %v; want the ten-day-old one pruned", n, err)
	}
	rep, err := h.st.InstallationReport(h.ctx, inst.ID, queued, h.c.Now())
	if err != nil {
		t.Fatalf("InstallationReport: %v", err)
	}
	if rep.Counts.Observed != 1 || rep.Counts.RanElsewhere != 1 {
		t.Fatalf("after the prune the report counts %+v; want the pruned job, from the roll-up", rep.Counts)
	}
}

package controller

import (
	"fmt"
	"sync/atomic"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// Every reconcile pass records, for each pool, whether the pool was held at its
// limit, and it used to do it with a write of its own per pool. The number of
// writes in a pass that changed nothing therefore grew with the size of the
// fleet, and in a profile of a quiet pass at a hundred pools they were a
// quarter of it. These hold the pass to recording the same observations, and to
// recording them without a write for each pool.

// sampledCapacity is what the capacity history holds for a pool: how many
// minutes were observed, and in how many of them the pool was held at its limit.
func sampledCapacity(t *testing.T, h *harness, pool *store.Pool, around time.Time) (samples, reached int) {
	t.Helper()
	rows, err := h.st.Usage(h.ctx, around.Add(-2*time.Hour), around.Add(time.Hour), store.UsageByPool)
	if err != nil {
		t.Fatalf("Usage: %v", err)
	}
	for _, r := range rows {
		if r.Key != pool.ID {
			continue
		}
		for _, b := range r.History {
			samples += b.CapacitySamples
			reached += b.CapacityReached
		}
	}
	return samples, reached
}

func TestAReconcilePassRecordsWhetherEachPoolWasHeldAtItsLimit(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	h.host("vm-1") // room for four runners

	wide := h.pool(inst, "wide", "self-hosted", "linux", "x64", "wide")
	wide.MaxRunners = 10
	if err := h.st.UpdatePool(h.ctx, wide); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	idle := h.pool(inst, "idle", "self-hosted", "linux", "x64", "idle")

	// Six jobs for a pool that may have ten runners, on a host with room for
	// four: two of them have nowhere to go, which is what "held at its limit"
	// means. The other pool has no work and is not.
	for i := 1; i <= 6; i++ {
		rec := h.deliverJob(jobEvent{Action: "queued", JobID: int64(i), RunID: int64(i), Name: fmt.Sprintf("build-%d", i),
			Labels: []string{"self-hosted", "linux", "x64", "wide"}})
		if rec.Code != 200 && rec.Code != 202 {
			t.Fatalf("delivering job %d: %d %s", i, rec.Code, rec.Body)
		}
	}

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}

	now := h.c.Now()
	if samples, reached := sampledCapacity(t, h, wide, now); samples != 1 || reached != 1 {
		t.Errorf("the pool that jobs could not be placed for has %d samples of which %d held at its limit, want 1 and 1", samples, reached)
	}
	if samples, reached := sampledCapacity(t, h, idle, now); samples != 1 || reached != 0 {
		t.Errorf("the pool with no work has %d samples of which %d held at its limit, want 1 and 0", samples, reached)
	}
}

// writesInAQuietPass is how many times the pass takes the writer when it has
// nothing to change, for a fleet of the given number of pools. The first pass is
// let go by: it is the one that settles whatever a fresh fleet settles.
func writesInAQuietPass(t *testing.T, pools int) int32 {
	t.Helper()
	h := newHarness(t)
	inst := h.installation()
	h.host("vm-1")
	for i := range pools {
		name := fmt.Sprintf("pool-%02d", i)
		h.pool(inst, name, "self-hosted", "linux", "x64", name)
	}
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile (settling): %v", err)
	}

	var writes atomic.Int32
	h.st.ObserveWrites(func(_, _ time.Duration) { writes.Add(1) })
	defer h.st.ObserveWrites(nil)
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile (quiet): %v", err)
	}
	return writes.Load()
}

func TestAQuietReconcilePassTakesTheWriterNoMoreOftenForABiggerFleet(t *testing.T) {
	small, large := writesInAQuietPass(t, 2), writesInAQuietPass(t, 12)
	if small == 0 {
		t.Fatal("a quiet pass took the writer 0 times; the pass records capacity, so the count means nothing")
	}
	if large != small {
		t.Errorf("a quiet pass over 12 pools took the writer %d times and over 2 pools %d: the capacity of every pool is recorded in one write, whatever the number of pools", large, small)
	}
}

package controller

import (
	"errors"
	"fmt"
	"github.com/eyupio/zoomies/internal/github"
	"time"
)

var errRegistrationHeld = fmt.Errorf("installation rate-limit hold: %w", github.ErrRateLimited)

var errRegistrationDeferred = errors.New("registration admission deferred until a later scheduling pass")

// Admission happens before creating a row or goroutine. The scheduler retains
// excess demand, so a slow installation cannot build an unbounded waiter queue.
func (c *Controller) admitCredentialMint(id string) bool {
	limit := max(1, min(16, c.cfg().Scheduler.RegistrationConcurrency))
	if c.githubHeld(id, c.Now()) {
		return false
	}
	c.githubMu.Lock()
	defer c.githubMu.Unlock()
	if c.Now().Before(c.githubPaused[id]) {
		return false
	}
	if c.credentialMints[id] >= limit {
		// Held at our own limit rather than GitHub's, which is the case
		// nothing else in the fleet can see. Counted so the metric and the
		// problems list can both say it is happening; the caller retains the
		// demand and a later pass takes it.
		c.noteDeferredMintLocked(id)
		return false
	}
	if c.credentialMints == nil {
		c.credentialMints = make(map[string]int)
	}
	c.credentialMints[id]++
	return true
}

func (c *Controller) releaseCredentialMint(id string) {
	c.githubMu.Lock()
	defer c.githubMu.Unlock()
	c.credentialMints[id]--
	if c.credentialMints[id] <= 0 {
		delete(c.credentialMints, id)
	}
}

// noteDeferredMintLocked records one creation held back at the minting limit.
// Called with githubMu held.
func (c *Controller) noteDeferredMintLocked(id string) {
	if c.deferredMints == nil {
		c.deferredMints = make(map[string]int)
		c.deferredSince = make(map[string]time.Time)
	}
	if c.deferredMints[id] == 0 {
		if _, ok := c.deferredSince[id]; !ok {
			c.deferredSince[id] = c.Now()
		}
	}
	c.deferredMints[id]++
	if c.metrics != nil {
		c.metrics.registrationsDeferred.WithLabelValues(id).Inc()
	}
}

// resetDeferredMints clears the last pass's count, keeping the moment the
// holding back started for as long as it is still happening. A pass that
// defers nothing forgets both, so the problem clears itself the moment the
// fleet catches up.
func (c *Controller) resetDeferredMints() {
	c.githubMu.Lock()
	defer c.githubMu.Unlock()
	for id, n := range c.deferredMints {
		if n == 0 {
			delete(c.deferredSince, id)
		}
		c.deferredMints[id] = 0
	}
}

// deferredMintsNow is what the last pass held back, and since when.
func (c *Controller) deferredMintsNow() (map[string]int, map[string]time.Time) {
	c.githubMu.Lock()
	defer c.githubMu.Unlock()
	out := make(map[string]int, len(c.deferredMints))
	since := make(map[string]time.Time, len(c.deferredSince))
	for id, n := range c.deferredMints {
		if n > 0 {
			out[id] = n
			if t, ok := c.deferredSince[id]; ok {
				since[id] = t
			}
		}
	}
	return out, since
}

package controller

import (
	"errors"
	"net/http"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

func TestRegistrationAdmissionIsBoundedAndInstallationScoped(t *testing.T) {
	h := newHarness(t)
	if !h.c.admitCredentialMint("one") || h.c.admitCredentialMint("one") {
		t.Fatal("default must admit exactly one mint")
	}
	if !h.c.admitCredentialMint("two") {
		t.Fatal("unrelated installation was blocked")
	}
	h.c.releaseCredentialMint("one")
	h.c.holdGitHub("one", h.c.Now().Add(time.Minute))
	if h.c.admitCredentialMint("one") {
		t.Fatal("held installation admitted")
	}
	h.advance(2 * time.Minute)
	if !h.c.admitCredentialMint("one") {
		t.Fatal("expired hold did not recover")
	}
	h.c.releaseCredentialMint("one")
	h.c.releaseCredentialMint("two")
	if len(h.c.credentialMints) != 0 {
		t.Fatal("admission bookkeeping leaked")
	}
}

func TestRegistrationRateLimitCreatesSharedHold(t *testing.T) {
	for _, ephemeral := range []bool{true, false} {
		h := newHarness(t)
		inst, pool, _ := h.fleet()
		pool.Ephemeral = ephemeral
		reset := h.c.Now().Add(10 * time.Minute)
		h.gh.SetRateLimit(5000, 0, reset)
		pattern := "registration-token"
		if ephemeral {
			pattern = "generate-jitconfig"
		}
		h.gh.SetError(pattern, http.StatusForbidden, "rate limit exceeded")
		_, _, err := h.c.mintCredentials(h.ctx, inst, pool, "limited")
		if !errors.Is(err, github.ErrRateLimited) {
			t.Fatalf("mint error: %v", err)
		}
		if !h.c.githubHeld(inst.ID, h.c.Now()) {
			t.Fatal("registration did not hold installation")
		}
		before := h.c.heldInstallations(h.c.Now())[inst.ID]
		if before.Before(reset.Truncate(time.Second)) {
			t.Fatal("hold ignored GitHub reset")
		}
		h.gh.ClearErrors()
		_, _, err = h.c.mintCredentials(h.ctx, inst, pool, "still-held")
		if !errors.Is(err, github.ErrRateLimited) {
			t.Fatalf("held mint error: %v", err)
		}
		if after := h.c.heldInstallations(h.c.Now())[inst.ID]; !after.Equal(before) {
			t.Fatal("skipped call extended hold")
		}
	}
}

func TestRegistrationGroupLookupRateLimitPreventsMint(t *testing.T) {
	h := newHarness(t)
	inst, pool, _ := h.fleet()
	h.gh.SetRateLimit(5000, 0, h.c.Now().Add(time.Minute))
	h.gh.SetError("runner-groups", http.StatusForbidden, "rate limit exceeded")
	_, _, err := h.c.mintCredentials(h.ctx, inst, pool, "group-limited")
	if !errors.Is(err, github.ErrRateLimited) || !h.c.githubHeld(inst.ID, h.c.Now()) {
		t.Fatalf("group quota not held: %v", err)
	}
	if len(h.gh.Runners()) != 0 {
		t.Fatal("minted after group lookup rate limit")
	}
}

// A full admission budget defers demand without losing it or allocating rows.
func TestRegistrationDeferredDemandResumesOnLaterPass(t *testing.T) {
	h := newHarness(t)
	inst, pool, _ := h.fleet()
	pool.MinRunners = 2
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	if !h.c.admitCredentialMint(inst.ID) {
		t.Fatal("could not occupy admission")
	}
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatal(err)
	}
	if len(h.runners()) != 0 {
		t.Fatal("deferred demand allocated provisioning rows")
	}
	h.c.releaseCredentialMint(inst.ID)
	for range pool.MinRunners {
		if err := h.c.Reconcile(h.ctx); err != nil {
			t.Fatal(err)
		}
		h.c.lifecycleCalls.Wait()
	}
	if got := len(h.runners()); got != pool.MinRunners {
		t.Fatalf("created %d runners, want %d", got, pool.MinRunners)
	}
	h.c.githubMu.Lock()
	defer h.c.githubMu.Unlock()
	if len(h.c.credentialMints) != 0 {
		t.Fatal("completed lifecycle retained admission")
	}
}

func TestRegistrationAdmissionPreservesPoolFairness(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	a, b := h.pool(inst, "a"), h.pool(inst, "b")
	h.host("host")
	for _, p := range []*store.Pool{a, b} {
		p.MinRunners = 2
		if err := h.st.UpdatePool(h.ctx, p); err != nil {
			t.Fatal(err)
		}
	}
	h.gh.SetDelay("", "generate-jitconfig", 500*time.Millisecond)
	for pass := 0; pass < 2; pass++ {
		if err := h.c.Reconcile(h.ctx); err != nil {
			t.Fatal(err)
		}
		h.c.lifecycleCalls.Wait()
	}
	counts := map[string]int{}
	for _, r := range h.runners() {
		counts[r.PoolID]++
	}
	if counts[a.ID] != 1 || counts[b.ID] != 1 {
		t.Fatalf("admission starved a pool: %v", counts)
	}
}

func TestCreateTaskCarriesProvisionDeadlineAndTokenExpiry(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	pool.Ephemeral = false
	pool.MinRunners = 1
	timeout := store.Duration(17 * time.Minute)
	pool.RunnerSettings.ProvisionTimeout = &timeout
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatal(err)
	}
	h.c.lifecycleCalls.Wait()
	tasks := h.tasksFor(host.ID)
	for _, task := range tasks {
		if task.Spec == nil || task.Spec.Credentials.RegistrationToken == "" {
			continue
		}
		runners := h.runners()
		if len(runners) != 1 {
			t.Fatalf("runners: %d", len(runners))
		}
		if !task.Spec.StartBefore.Truncate(time.Millisecond).Equal(runners[0].CreatedAt.Add(time.Duration(timeout))) {
			t.Fatalf("deadline %s, created %s, timeout %s", task.Spec.StartBefore, runners[0].CreatedAt, timeout)
		}
		if task.Spec.Credentials.ExpiresAt.IsZero() {
			t.Fatal("GitHub token expiry was discarded")
		}
		return
	}
	t.Fatal("no credential-bearing create task")
}

package controller

import (
	"strings"
	"testing"
	"time"
)

// scheduler.registration_concurrency is the one limit in this fleet that used
// to bind without saying so. The pool reports jobs waiting and nowhere to run
// them, an operator reads that, looks at the idle hosts and adds more -- and
// the new hosts do not help, because hosts were never what ran out.
func TestAHeldBackRegistrationSaysSoRatherThanJustNotHappening(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()

	// One in flight, which is the default limit, so the next is held.
	if !h.c.admitCredentialMint(inst.ID) {
		t.Fatal("the first mint was refused, so nothing below is testing the limit")
	}
	if h.c.admitCredentialMint(inst.ID) {
		t.Fatal("a second mint was admitted at a limit of one")
	}

	problems, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	var found *Problem
	for i := range problems {
		if problems[i].Code == "scheduler.registration_throttled" {
			found = &problems[i]
		}
	}
	if found == nil {
		var codes []string
		for _, p := range problems {
			codes = append(codes, p.Code)
		}
		t.Fatalf("nothing said the registration was held back; the list was %s", strings.Join(codes, ", "))
	}

	// The entry has to name the setting, or an operator reading it still does
	// not know which number to change.
	if found.Setting != "scheduler.registration_concurrency" {
		t.Errorf("the entry names setting %q", found.Setting)
	}
	if found.TargetID != inst.ID {
		t.Errorf("the entry targets %q, not the installation it is about", found.TargetID)
	}
	// And it has to say the thing that stops somebody buying hosts.
	if !strings.Contains(found.Detail, "hosts are not what ran out") {
		t.Errorf("the entry does not say adding hosts will not help: %q", found.Detail)
	}
	if found.Since == nil {
		t.Error("the entry does not say since when, so nobody can tell a blip from a standing condition")
	}
}

// A throttle that is no longer binding must stop being reported, or it becomes
// one more line an operator learns to scroll past.
func TestTheHeldBackRegistrationClearsWhenItStops(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()

	if !h.c.admitCredentialMint(inst.ID) {
		t.Fatal("the first mint was refused")
	}
	if h.c.admitCredentialMint(inst.ID) {
		t.Fatal("a second mint was admitted at a limit of one")
	}
	h.c.releaseCredentialMint(inst.ID)

	// A pass that defers nothing forgets it.
	h.c.resetDeferredMints()
	h.c.resetDeferredMints()

	problems, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	for _, p := range problems {
		if p.Code == "scheduler.registration_throttled" {
			t.Errorf("the fleet is no longer holding registrations back and still says it is: %q", p.Title)
		}
	}
}

// GitHub's own rate-limit hold is a different thing with a different fix, and
// counting it here would send an operator to raise a limit that is not the one
// refusing them.
func TestAGitHubRateLimitHoldIsNotCountedAsOurThrottle(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()

	h.c.holdGitHub(inst.ID, h.c.Now().Add(time.Hour))
	if h.c.admitCredentialMint(inst.ID) {
		t.Fatal("a mint was admitted while the installation was held by GitHub")
	}

	held, _ := h.c.deferredMintsNow()
	if n := held[inst.ID]; n != 0 {
		t.Errorf("a GitHub rate-limit hold was counted as %d of our own deferrals", n)
	}
}

package controller

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
)

// A problem tells an operator what is wrong and what to change. Most of the time
// the change is one the controller has already worked out in full -- it priced it
// against the hosts before it said so -- and an operator who has to retype it into
// a form, or paste a command, is doing the part of the job a machine did better.
//
// A Remedy is that change as data: the update, in the exact shape the route that
// makes it takes, and the sentence that says what it costs. Applying one is not a
// second way of changing a pool or a host. It is the pool's or the host's own
// update route, called as the person who asked, with everything that route does --
// its validation, its refusal of a change that leaves a pool with nowhere to run,
// its audit row -- and never with the override that lifts the refusal.

// RemedyKind says which update a remedy is, and so which role may apply it.
type RemedyKind string

const (
	// RemedyPoolUpdate is a PATCH of a pool; Body is its request.
	RemedyPoolUpdate RemedyKind = "pool.update"
	// RemedyHostUpdate is a PATCH of a host; Body is its request.
	RemedyHostUpdate RemedyKind = "host.update"
)

// Remedy is one change a problem proposes.
type Remedy struct {
	// ID names this exact change, so that an apply is for what the person was
	// shown: if the controller has since worked out a different one, the ID is
	// different and the apply is refused as out of date rather than made.
	ID string `json:"id"`
	// Label is the button: what the change is, in a few words.
	Label string `json:"label"`
	// Effect is what the controller priced it at -- what it keeps and what it
	// gains -- said before it is applied, because a change whose cost is found
	// out afterwards is not a suggestion.
	Effect   string          `json:"effect,omitempty"`
	Kind     RemedyKind      `json:"kind"`
	TargetID string          `json:"target_id"`
	Body     json.RawMessage `json:"body"`
	// Base is what the body was built from -- the pool's resources or the host's
	// runner profile as the controller read them -- as RemedyBase hashes it. The body
	// replaces that whole object, so applying it to one that has been edited since
	// would put back whatever the edit changed; the apply compares the two and
	// refuses. It is the controller's own check and never leaves it.
	Base string `json:"-"`
}

// RemedyBase is the fingerprint a remedy's Base and the object it will replace are
// compared by.
func RemedyBase(v any) string {
	raw, err := json.Marshal(v)
	if err != nil {
		return ""
	}
	sum := sha256.Sum256(raw)
	return hex.EncodeToString(sum[:8])
}

// newRemedy builds a remedy for a pool or host from the request that makes it, and
// the object the request was built from.
func newRemedy(kind RemedyKind, targetID, label, effect string, body, base any) *Remedy {
	raw, err := json.Marshal(body)
	if err != nil {
		// A request built from the controller's own types does not fail to
		// encode; if it somehow did, there is no remedy to offer, which is the
		// safe answer.
		return nil
	}
	sum := sha256.Sum256([]byte(string(kind) + "\x00" + targetID + "\x00" + string(raw)))
	return &Remedy{ID: "rem_" + hex.EncodeToString(sum[:6]), Label: label, Effect: effect, Kind: kind, TargetID: targetID, Body: raw, Base: RemedyBase(base)}
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"slices"
	"time"

	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// A pool with jobs queued and no machine rented for it looks the same on every
// screen whatever the reason, and the reasons call for opposite things: the
// hosts that could run it are only cordoned, the fleet may rent nothing, or no
// provider builds a machine that suits it. A verdict is the machine planner
// saying which, in one sentence, for each pool the scheduler could not place,
// so an operator is not left to work it out from the provider's settings, the
// pool's and the scheduler's sentence laid side by side.
//
// DecideMachines records each verdict at the branch that decided it rather than
// working it out again afterwards, because a second reading of the snapshot
// would be a second rule, and the one that explains would drift from the one
// that buys.

// RentingState is what the planner decided about renting for one pool.
type RentingState string

const (
	// RentingBuying is a pool this pass rents machines for: all it is short
	// of, or as much as the ceilings allow.
	RentingBuying RentingState = "renting"
	// RentingOnItsWay is a pool the machines already being built cover.
	RentingOnItsWay RentingState = "on_its_way"
	// RentingWaiting is a pool the scheduler could not place for a reason a
	// machine does not answer: a host that could run it is cordoned, silent,
	// incompatible, held or still starting runners. Mending a host is cheaper
	// than renting one, so nothing is rented until every host that could run
	// the pool is full. A pool no provider could ever serve is unserved
	// instead, because waiting would promise it a machine that never comes.
	RentingWaiting RentingState = "waiting"
	// RentingCeiling is a pool whose machine a limit stopped.
	RentingCeiling RentingState = "ceiling"
	// RentingUnserved is a pool no provider will rent for: a selector says no,
	// or no provider builds a machine that suits it.
	RentingUnserved RentingState = "unserved"
	// RentingHeld and RentingOff are never decided by the planner. The
	// controller lays them over a verdict (overlayRenting), because it knows
	// what the pure planner does not: that a provider may not buy at the
	// moment, or that renting is switched off.
	RentingHeld RentingState = "held"
	RentingOff  RentingState = "off"
)

// PoolRenting is the verdict on one pool: what the planner decided about
// renting for it, why, and what would change that.
type PoolRenting struct {
	PoolID   string       `json:"pool_id"`
	PoolName string       `json:"pool_name"`
	State    RentingState `json:"state"`
	// Summary is the one sentence an operator reads and Fix what to change,
	// both written to be shown as they are. Setting is the one setting the
	// fix changes, when there is one: a provider's own limits are on its own
	// form, not in Settings, so a fix to one of them names none.
	Summary string `json:"summary"`
	Fix     string `json:"fix,omitempty"`
	Setting string `json:"setting,omitempty"`
	// ProviderID and ProviderName are the provider the pool's shortfall was
	// charged to or, for on_its_way, the one building the oldest machine that
	// covers it. A pool that is waiting, or that no provider will rent for,
	// was charged to none.
	ProviderID   string `json:"provider_id,omitempty"`
	ProviderName string `json:"provider_name,omitempty"`
	// Queued is the queued jobs the pool claims, counted as the purchase
	// sentence counts them, so that a job two pools could run is counted for
	// one. Short is the runner slots it is missing. For a pool the scheduler
	// is waiting on hosts for, that is the scheduler's own shortfall, whether
	// the verdict is waiting or, because no provider could serve it,
	// unserved. Otherwise it is what the free slots on hosts that could run
	// it leave and, for every state but on_its_way, what the machines on
	// their way leave as well.
	Queued int `json:"queued"`
	Short  int `json:"short"`
	// Machines is, for renting, the machines this pool alone needs, at most
	// what the provider rents this pass. Pools that share a machine each
	// count it, so the figures are never to be added up. For on_its_way it is
	// how many of the named provider's machines are coming. For held and off
	// it is what the pass would have rented had nothing stood in the way,
	// which is none for a pool a ceiling stopped or one the machines already
	// on their way cover.
	Machines int `json:"machines"`
	// Since is when the oldest machine on its way for this pool was asked for.
	// It is a field rather than a phrase in the summary because a sentence with
	// a clock in it would differ on every pass, and whatever reaches the
	// problems list is sent again each time it differs.
	Since *time.Time `json:"since,omitempty"`
	// Because is, for ceiling only, the ceiling that stopped the purchase
	// without the summary's prefix or full stop, so that a sentence laid over
	// the verdict (renting switched off as well) can say it in its own words.
	// It is not sent, because the summary already says it.
	Because string `json:"-"`
}

// Aside is what a page already showing the scheduler's sentence adds to it. A
// waiting verdict's summary quotes that sentence, so only its tail is news;
// every other verdict is news in full.
func (v PoolRenting) Aside() string {
	if v.State == RentingWaiting {
		return waitingTail
	}
	return v.Summary
}

// The sentences that take no value. The waiting tail is both the end of a
// summary and the whole of an aside, and is written once so that the two
// cannot come to say different things.
const (
	waitingTail    = "A machine is rented only once every host that could run this pool is full."
	waitingFix     = "Wait for those hosts to clear, or uncordon, repair or remove the ones that are unavailable."
	unservedFitFix = "Give a provider machines that suit this pool, or change the pool."
)

// poolReason is what one pool's verdict says it is short of: demandReason for
// a single pool without the pool's name, because the verdict is shown beside
// the pool already.
//
// The queue is mentioned only when something is queued. A pool below its
// min_runners with nothing waiting is renting for the runners it keeps warm,
// and "with 0 jobs queued" would read as a machine rented for no work at all.
func poolReason(d poolDemand) string {
	reason := plural(d.slots, "runner slot") + " short"
	if d.queued > 0 {
		reason += " with " + plural(d.queued, "job") + " queued"
	}
	if d.nowhere {
		return reason + ", and no host in the fleet can run it"
	}
	return reason + ", and every host that can run it is full"
}

// waitingVerdict is a pool the scheduler could not place for a reason a
// machine does not answer. The scheduler's own sentence says what is in the
// way, so the summary quotes it rather than describing the hosts again.
func waitingVerdict(pool *store.Pool, pp scheduler.PoolPlan, queued int) PoolRenting {
	return PoolRenting{
		PoolID: pool.ID, PoolName: pool.Name, State: RentingWaiting,
		Summary: "Not renting yet: " + pp.Blocked + ". " + waitingTail,
		Fix:     waitingFix,
		Queued:  queued, Short: pp.Desired - pp.Current,
	}
}

// onItsWayVerdict is a pool the machines already being built cover. since
// arrives by value, so the verdict points at a copy of its own and never into
// the machine row: the verdict outlives the pass, and the row is the
// controller's.
func onItsWayVerdict(pool *store.Pool, p *store.Provider, coming int, since time.Time, short, queued int) PoolRenting {
	verb := "are"
	if coming == 1 {
		verb = "is"
	}
	return PoolRenting{
		PoolID: pool.ID, PoolName: pool.Name, State: RentingOnItsWay,
		Summary: fmt.Sprintf("%s from %s %s on the way for this pool, so the next runners start there.",
			plural(coming, "machine"), p.Name, verb),
		ProviderID: p.ID, ProviderName: p.Name,
		Queued: queued, Short: short, Machines: coming, Since: &since,
	}
}

// unservedVerdict is the verdict on a pool no provider will rent for, with the
// selector's refusal when that is the reason, for the caller that also lists
// it. Both places a pool can turn out unserved ask this one function, so the
// two cannot come to say different things.
//
// A selector that says no was somebody's choice, so it is quoted with its own
// fix. Otherwise no provider builds a machine the pool could use, and one
// provider's mismatch is the example given: the first by name whose selectors
// allow the pool, because that is the provider an operator means to rent from,
// or the first of all when none does. Every provider's machine has failed a
// test of shape to get here, so its mismatch always has something to say.
// There is always a first, because DecideMachines decides nothing for a fleet
// with no provider.
//
// A machine too small for the pool is said as that, with the size it would
// have to be, and with the machines the provider already owns, which are the
// same size. Those are what fill its ceiling, and a pool told only that the
// ceiling was reached would be sent to raise it and buy more of them.
func unservedVerdict(providers []*store.Provider, synth map[string]*store.Host, pool *store.Pool, owned map[string]int, now time.Time, short, queued int) (PoolRenting, *UnservedPool) {
	v := PoolRenting{PoolID: pool.ID, PoolName: pool.Name, State: RentingUnserved, Queued: queued, Short: short}
	if refused, ok := unservedBy(providers, synth, pool, now); ok {
		v.Summary = "No provider will rent for this pool. " + sentence(refused.Why)
		v.Fix = sentence(refused.Fix)
		return v, &refused
	}
	first := providers[0]
	for _, p := range providers {
		if scheduler.Pair(p, pool).Agrees {
			first = p
			break
		}
	}
	misfit := machineFit(first, synth[first.ID], pool)
	v.Summary = "No provider builds a machine this pool could use. " + first.Name + ": " + misfit.Why
	v.Fix = unservedFitFix
	if misfit.Fix != "" {
		v.Fix = misfit.Fix
	}
	if n := owned[first.ID]; misfit.Size && n > 0 {
		owns := fmt.Sprintf("The %d machines it owns are", n)
		if n == 1 {
			owns = "The machine it owns is"
		}
		v.Summary += " " + owns + " the same size, so a higher maximum would only buy more machines this pool cannot use."
	}
	return v, nil
}

// chargedVerdict is a pool whose shortfall was charged to p, once every
// ceiling has had its say. create, want (what the pools charged to p need
// between them) and the ceiling's words are the provider's, decided once for
// all of those pools, and shared says there is more than one. Machines is the
// pool's own share whatever the sentence: the machines it alone needs, and as
// many of those as create covers.
//
// When the whole purchase is made, each pool quotes that share, because the
// provider's whole order would tell a pool one slot short that it needs two
// machines. When it is held back, no one of several pools can be said to be
// covered: the machines bought serve whichever pool the scheduler places on
// them first. So each is told about the pools together, and only a provider
// charged with a single pool says what "it" needs.
func chargedVerdict(p *store.Provider, d poolDemand, create, want int, shared bool, because, fix, setting string) PoolRenting {
	need := ceilDiv(d.slots, providerSlots(p))
	v := PoolRenting{
		PoolID: d.poolID, PoolName: d.pool, State: RentingBuying,
		ProviderID: p.ID, ProviderName: p.Name,
		Queued: d.queued, Short: d.slots, Machines: min(create, need),
	}
	switch {
	case create == 0:
		v.State, v.Because = RentingCeiling, because
		v.Summary = "Not renting: " + because + "."
		v.Fix, v.Setting = sentence(fix), setting
	case create >= want:
		v.Summary = fmt.Sprintf("Renting %s from %s, which covers this pool: %s.", plural(need, "machine"), p.Name, poolReason(d))
	case shared:
		v.Summary = fmt.Sprintf("Renting %d of the %d machines this pool and others need from %s: %s. The rest are held back: %s.",
			create, want, p.Name, poolReason(d), because)
		v.Fix, v.Setting = sentence(fix), setting
	default:
		v.Summary = fmt.Sprintf("Renting %d of the %d machines it needs from %s, which covers this pool: %s. The rest are held back: %s.",
			create, want, p.Name, poolReason(d), because)
		v.Fix, v.Setting = sentence(fix), setting
	}
	return v
}

// ---------------------------------------------------------------------------
// The fleet's view
// ---------------------------------------------------------------------------

// The sentences the fleet says about itself, and the one a machine on its way
// says once renting is switched off. The other sentences laid over a verdict
// take a value, and are written where they are laid over it.
const (
	fleetNone         = "No provider is configured, so nothing is rented."
	fleetOff          = "Renting is switched off: this controller is not allowed to rent machines, so work with nowhere to run waits for the hosts it has."
	fleetOffFix       = "Turn on Rent machines in Settings, and set Machines the fleet may rent to the most you are willing to pay for."
	fleetNoCeiling    = "Renting is on, but the fleet may rent no machines: a maximum of none is none."
	fleetNoCeilingFix = "Set Machines the fleet may rent to the most machines you are willing to pay for at once."
	fleetOn           = "Renting is on."
	fencedOnItsWay    = "A machine for this pool was being built, but this fleet is fenced for recovery, so nothing is finishing it."
	offOnItsWay       = "A machine for this pool was being built, but renting is switched off, so nothing is finishing it."
)

// RentingView is the whole of what the fleet says about renting machines: which
// switch, if any, is holding it back, and the verdict on each pool the last
// machine pass had something to say about, with the switches laid over it.
//
// The switches are read with the view and the verdicts are as old as the last
// pass. An operator who has just switched renting on reads the page to see
// that it took, so the view cannot wait for the loop to wake before it says
// so; and the verdicts are never worked out again for a read, because the
// decision that explains has to be the one that buys.
type RentingView struct {
	// State is "none" when no provider may rent (a demo fixture, or a provider
	// whose own row is disabled, is not one that may), "off" when renting is
	// switched off, "no_ceiling" when it is on and the fleet may rent no
	// machines, and "on" otherwise.
	State string `json:"state"`
	// Summary is the state in one sentence, Fix what to change, and Setting
	// the one setting the fix changes.
	Summary string `json:"summary"`
	Fix     string `json:"fix,omitempty"`
	Setting string `json:"setting,omitempty"`
	// Enabled, Paused and MaxMachines are provider.enabled, provider.paused
	// and provider.max_machines as they stand.
	Enabled     bool `json:"enabled"`
	Paused      bool `json:"paused"`
	MaxMachines int  `json:"max_machines"`
	// SuggestedMaxMachines is the fleet ceiling a page offers to set: the
	// ceilings of the providers that may rent, added up, and never less than
	// one, so that the click that switches renting on cannot leave a fleet
	// that may rent nothing.
	SuggestedMaxMachines int `json:"suggested_max_machines,omitempty"`
	// Owned is how many machines still own a resource, and so are still being
	// paid for, as the last pass counted them: zero before the first.
	Owned int `json:"owned"`
	// DecidedAt is when the pass the verdicts come from ran, and absent before
	// the first one.
	DecidedAt *time.Time `json:"decided_at,omitempty"`
	// Pools is never nil, so that a page is sent an empty list rather than
	// null before the first pass.
	Pools []PoolRenting `json:"pools"`
}

// rentingReport is what one machine pass decided about renting, kept for the
// reads until the next pass. A pass replaces it whole and nothing changes it
// after, so a reader that has taken it from under the lock may keep it.
type rentingReport struct {
	// At is when the pass ran.
	At time.Time
	// Pools is the planner's verdicts, before anything is laid over them,
	// with the demo fixture's pools left out.
	Pools []PoolRenting
	// Providers is every provider the pass read but the demo fixture, and
	// Usable those of them whose own row is enabled: the ones that may rent.
	// A disabled row stays in Providers because the planner may still charge
	// a pool to it, and the view then has to say why that buys nothing.
	Providers []*store.Provider
	Usable    []*store.Provider
	// Owned is how many machines of those providers own a resource.
	Owned int
}

// rentingInput is everything buildRentingView reads, gathered by the caller so
// that the view is a function of it alone.
type rentingInput struct {
	// Report is the last pass's, or nil before the first one.
	Report *rentingReport
	// Usable is the providers that may rent: the report's, or the database's
	// before there is a report.
	Usable []*store.Provider
	// Enabled, Paused and MaxMachines are the switches as they stand.
	Enabled     bool
	Paused      bool
	MaxMachines int
	// Fenced is whether the fleet is fenced for recovery, which stops every
	// machine step at every provider and so strands one on its way.
	Fenced bool
	// Held is what provisioningHeld says of each provider the pass read, by
	// id, a row-disabled one included, without the countdown of a provider
	// standing down. It is gathered only while renting is on: while it is off
	// every provider would answer with the switch, and the overlay says that
	// in words of its own.
	Held map[string]string
}

// buildRentingView says which switch is holding renting back, and lays the
// switches over the last pass's verdicts.
func buildRentingView(in rentingInput) RentingView {
	out := RentingView{
		Enabled: in.Enabled, Paused: in.Paused, MaxMachines: in.MaxMachines,
		Pools: []PoolRenting{},
	}
	for _, p := range in.Usable {
		out.SuggestedMaxMachines += max(p.MaxMachines, 0)
	}
	out.SuggestedMaxMachines = max(out.SuggestedMaxMachines, 1)
	switch {
	case len(in.Usable) == 0:
		out.State, out.Summary = "none", fleetNone
	case !in.Enabled:
		out.State, out.Summary, out.Fix, out.Setting = "off", fleetOff, fleetOffFix, "provider.enabled"
	case in.MaxMachines <= 0:
		out.State, out.Summary, out.Fix, out.Setting = "no_ceiling", fleetNoCeiling, fleetNoCeilingFix, "provider.max_machines"
	default:
		out.State, out.Summary = "on", fleetOn
	}
	if in.Report == nil {
		return out
	}
	out.Owned = in.Report.Owned
	at := in.Report.At
	out.DecidedAt = &at
	// With no provider that may rent, nothing is rented whatever a pool needs,
	// and the fleet's own sentence is the whole answer. A verdict the planner
	// reached against a disabled row would send an operator to the renting
	// switch, or promise a machine, for a provider that rents nothing either way.
	if len(in.Usable) == 0 {
		return out
	}
	for _, v := range in.Report.Pools {
		out.Pools = append(out.Pools, overlayRenting(v, in.Enabled, in.Fenced, in.Held))
	}
	return out
}

// overlayRenting lays over one of the planner's verdicts what the pure planner
// cannot know: that renting is switched off, or that the provider charged with
// the pool may not buy at the moment.
//
// Switched off, a purchase says how many machines it would have been, a
// ceiling that would also have stopped it is still named, and a machine on its
// way is stranded, because nothing finishes a machine while renting is off.
// Each names the one setting that changes it. A pool waiting on its hosts, or
// one no provider serves, is in the same place whichever way the switch is, and
// is told what it would have been told anyway.
//
// Switched on, a purchase the provider may not make is held rather than
// renting, and the fix a partial purchase named goes with it: raising a ceiling
// does nothing for a provider that is paused.
func overlayRenting(v PoolRenting, enabled, fenced bool, held map[string]string) PoolRenting {
	if enabled {
		if fenced && v.State == RentingOnItsWay {
			// Nothing is created or deleted while the fleet is fenced, so the
			// machines counted as coming are not being finished. Held, as a
			// provider that may not buy is, because it ends the same way: when
			// whatever holds it is lifted.
			v.State, v.Summary, v.Machines = RentingHeld, fencedOnItsWay, 0
			return v
		}
		if why := held[v.ProviderID]; why != "" && v.State == RentingBuying {
			v.State, v.Summary, v.Fix, v.Setting = RentingHeld, "Not renting: "+why+".", "", ""
		}
		return v
	}
	switch v.State {
	case RentingBuying:
		v.Summary = fmt.Sprintf("Would rent %s for this pool, but renting is switched off.", plural(v.Machines, "machine"))
	case RentingCeiling:
		v.Summary = "Renting is switched off, and " + v.Because + "."
	case RentingOnItsWay:
		// The machines were counted as coming, and while renting is off
		// nothing brings them. Nor are they machines the pass would rent, so
		// the pool would rent none.
		v.Summary, v.Machines = offOnItsWay, 0
	default:
		return v
	}
	v.State, v.Fix, v.Setting = RentingOff, fleetOffFix, "provider.enabled"
	return v
}

// Renting is the fleet's renting view as it stands: the switches now, laid over
// the last machine pass's verdicts. It reads the database only when there is
// no report to read, for the providers that say whether there is anything to
// rent from at all.
func (c *Controller) Renting(ctx context.Context) (RentingView, error) {
	in := c.rentingNow()
	if in.Report == nil {
		usable, err := c.usableProviders(ctx)
		if err != nil {
			return RentingView{}, err
		}
		in.Usable = usable
	}
	return buildRentingView(in), nil
}

// rentingFor is one pool's verdict with the switches laid over it, or nil when
// the last pass had nothing to say about the pool. It is the view's own entry
// for the pool, so a page explaining one pool and the page listing them all
// cannot disagree, and it reads no database, so a page explaining a pool can
// ask it for every pool it shows.
func (c *Controller) rentingFor(poolID string) *PoolRenting {
	in := c.rentingNow()
	if in.Report == nil {
		return nil
	}
	for _, v := range buildRentingView(in).Pools {
		if v.PoolID == poolID {
			return &v
		}
	}
	return nil
}

// rentingNow gathers what the view is built from: the last pass's report, and
// the switches as they stand with what holds each provider back at this moment.
func (c *Controller) rentingNow() rentingInput {
	c.mu.Lock()
	report := c.renting
	c.mu.Unlock()
	cfg := c.cfg()
	in := rentingInput{
		Report:      report,
		Enabled:     cfg.Provider.Enabled,
		Paused:      cfg.Provider.Paused,
		MaxMachines: cfg.Provider.MaxMachines,
		Fenced:      c.Fenced().Fenced,
	}
	if report == nil {
		return in
	}
	in.Usable = report.Usable
	if in.Enabled {
		now := c.Now()
		in.Held = make(map[string]string, len(report.Providers))
		for _, p := range report.Providers {
			// Without the countdown a provider standing down carries: a held
			// verdict's summary reaches the problems list, which may carry no
			// clock.
			if why := c.provisioningHeldWith(p, now, false); why != "" {
				in.Held[p.ID] = why
			}
		}
	}
	return in
}

// usableProviders is the providers that may rent, in name order. It is the
// last pass's list when there is a report, so that the fleet's state and the
// verdicts it carries agree about which providers there are, and the
// database's when there is not. The slice is the caller's own to keep; the
// rows in it may be the report's, and are only to be read.
func (c *Controller) usableProviders(ctx context.Context) ([]*store.Provider, error) {
	c.mu.Lock()
	report := c.renting
	c.mu.Unlock()
	if report != nil {
		return slices.Clone(report.Usable), nil
	}
	rows, err := c.st.ListProviders(ctx)
	if err != nil {
		return nil, fmt.Errorf("listing providers: %w", err)
	}
	return usableRows(rows), nil
}

// usableRows is the providers among rows that may rent: neither a demo fixture
// nor disabled on its own row.
//
// The row is asked, never provisioningHeld. With renting off, that answers
// with the switch for a disabled row as for every other, and a fleet whose
// only provider is disabled would read as one waiting for renting to be
// switched on, when switching it on would rent nothing.
func usableRows(rows []*store.Provider) []*store.Provider {
	var out []*store.Provider
	for _, p := range rows {
		if p != nil && p.Enabled && !IsDemoID(p.ID) {
			out = append(out, p)
		}
	}
	return out
}

// noteRenting keeps what this pass decided about renting for the reads until
// the next, and sends again, as the database has it now, each provider whose
// held sentence the pass finds changed. It is called with machines.mu held.
//
// The report is guarded by c.mu alone, taken here inside machines.mu and never
// the other way round, so that a page asking why nothing is rented waits on
// nothing a hypervisor holds up.
//
// Held is computed rather than stored, so no row write announces that it has
// moved: a provider's page open when renting was switched on would otherwise go
// on saying it was off until somebody reloaded it. A provider with no sentence
// from an earlier pass has nothing to differ from, and is only remembered. The
// sentence compared is the card's own, countdown and all, unlike the verdict's,
// so a provider standing down is sent again each pass with the time it has left.
func (c *Controller) noteRenting(ctx context.Context, env *machineEnv, plan MachinePlan) {
	report := &rentingReport{At: env.now}
	for _, p := range env.rows {
		if !IsDemoID(p.ID) {
			report.Providers = append(report.Providers, p)
		}
	}
	report.Usable = usableRows(report.Providers)
	for _, v := range plan.Pools {
		if !IsDemoID(v.PoolID) {
			report.Pools = append(report.Pools, v)
		}
	}
	for _, m := range env.list {
		if m.Owns() {
			report.Owned++
		}
	}
	c.mu.Lock()
	c.renting = report
	c.mu.Unlock()

	held := make(map[string]string, len(report.Providers))
	for _, p := range report.Providers {
		held[p.ID] = c.provisioningHeld(p, env.now)
		was, ok := c.machines.lastHeld[p.ID]
		if !ok || was == held[p.ID] {
			continue
		}
		// The row as it is now, not the pass's own copy. That was read when the
		// pass began, and anything written since (an operator's edit or check,
		// or the breaker, which reads afresh on purpose) has gone out in a
		// frame of its own that the older row would overwrite on every open
		// page. A provider deleted since has had its deletion announced, and
		// sending it again would bring it back.
		fresh, err := c.st.GetProvider(ctx, p.ID)
		if err != nil {
			if !errors.Is(err, store.ErrNotFound) {
				c.log.Warn("could not read a provider to send it again", "provider", p.ID, "error", err)
			}
			continue
		}
		c.publishProvider(ctx, fresh)
	}
	c.machines.lastHeld = held
}

// forgetRenting drops the report once the fleet has no provider other than the
// demo fixture, so that the view reads the providers for itself rather than
// describing ones that have gone. It is called with machines.mu held.
func (c *Controller) forgetRenting() {
	c.mu.Lock()
	c.renting = nil
	c.mu.Unlock()
	c.machines.lastHeld = nil
}

package controller

import (
	"fmt"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// theVerdict is the one verdict a snapshot of one pool should produce, so a
// test says what it expects rather than indexing a slice.
func theVerdict(t *testing.T, plan MachinePlan) PoolRenting {
	t.Helper()
	if len(plan.Pools) != 1 {
		t.Fatalf("verdicts = %+v, want exactly one", plan.Pools)
	}
	return plan.Pools[0]
}

// The fleet this was reported from: three Linux hosts with every slot busy, a
// fourth throttled to its last rung, and a Windows host that only offers the
// process backend. The Windows host can never run the pool. While it kept the
// fleet from reading as full, the queued job waited for a slot only a rented
// machine could give, and none was ever rented. With it or without it, the
// answer is one machine, and the verdict says so.
func TestAMixedFleetBuysAMachineForABusyPool(t *testing.T) {
	for _, tc := range []struct {
		name    string
		windows bool
	}{
		{name: "beside a Windows host", windows: true},
		{name: "with its Linux hosts alone"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			pool := demandPool("zoomies-linux-x64", "zoomies", "zoomies-linux-x64")
			pool.MinRunners, pool.MaxRunners = 2, 15

			throttled := demandHost("linux_4", 4, 2)
			throttled.Throttle = store.HostThrottle{Level: store.MaxThrottleLevel}
			hosts := []*store.Host{demandHost("linux_1", 2, 2), demandHost("linux_2", 1, 1), demandHost("linux_3", 2, 2), throttled}
			var runners []*store.Runner
			for _, h := range hosts {
				for i := range h.ActiveRunners {
					id := fmt.Sprintf("run_%s_%d", h.ID, i)
					runners = append(runners, &store.Runner{
						ID: id, Name: id, PoolID: pool.ID, HostID: h.ID, State: store.RunnerBusy,
						CreatedAt: machineNow.Add(-10 * time.Minute),
					})
				}
			}
			if tc.windows {
				windows := demandHost("windows_1", 4, 0)
				windows.Backends = store.StringSlice{string(store.BackendProcess)}
				windows.OS, windows.Distro = "windows", "windows"
				hosts = append(hosts, windows)
			}
			jobs := []*store.Job{{
				ID: "job_1", Repo: "acme/widgets", State: store.JobQueued, InstallationID: "inst_1",
				Labels: store.StringSlice{"zoomies-linux-x64"}, QueuedAt: machineNow.Add(-3 * time.Minute),
			}}
			fleet := scheduler.Snapshot{
				Now: machineNow, Pools: []*store.Pool{pool}, Hosts: hosts, Jobs: jobs,
				Runners: map[string][]*store.Runner{pool.ID: runners},
				Policy: scheduler.Policy{
					MaxRunnerLifetime: 6 * time.Hour, ProvisionTimeout: 5 * time.Minute,
					DrainTimeout: 15 * time.Minute, MaxCreatesPerTick: 10,
				},
			}
			placed := scheduler.Decide(fleet)
			if len(placed.Pools) != 1 || !placed.Pools[0].BlockedAtCapacity {
				t.Fatalf("pool plans = %+v, want the one pool blocked at capacity", placed.Pools)
			}

			lab := demandProvider("proxmox-lab")
			lab.MaxMachines, lab.MaxCreatesInFlight = 2, 1
			limits := demandLimits()
			limits.MaxMachines, limits.MaxCreatesInFlight = 2, 2
			plan := DecideMachines(MachineSnapshot{
				Now: machineNow, Plan: placed, Pools: fleet.Pools, Hosts: hosts, Runners: fleet.Runners,
				Jobs: jobs, Providers: []*store.Provider{lab}, Limits: limits,
			})

			got := planFor(t, plan, lab.ID)
			if got.Create != 1 {
				t.Fatalf("create = %d, want 1: the pool is one runner short and every host that could run it is full", got.Create)
			}
			want := "buy 1 machine on proxmox-lab: pool zoomies-linux-x64 is 1 runner slot short with 1 job queued, and every host that can run it is full"
			if got.Reason != want {
				t.Fatalf("reason = %q,\n want %q", got.Reason, want)
			}
			v := theVerdict(t, plan)
			if v.State != RentingBuying {
				t.Fatalf("verdict = %+v, want %s", v, RentingBuying)
			}
			summary := "Renting 1 machine from proxmox-lab, which covers this pool: 1 runner slot short with 1 job queued, and every host that can run it is full."
			if v.Summary != summary {
				t.Fatalf("summary = %q,\n want %q", v.Summary, summary)
			}
		})
	}
}

// Each verdict is the sentence an operator reads when a pool queues and no
// machine arrives for it, so each is pinned word for word: the pool page, the
// problem and the Providers page all quote these words, and a verdict that
// named the wrong setting would send somebody to the wrong screen.
func TestEveryVerdictStateSaysItsSentence(t *testing.T) {
	// snapshot is provider lab and pool alpha and nothing else, with alpha as
	// the scheduler left it. Each row adds what makes its case.
	snapshot := func(current, desired, queued int, blocked string) MachineSnapshot {
		pool := demandPool("alpha", "linux", "x64")
		return MachineSnapshot{
			Now: machineNow, Pools: []*store.Pool{pool}, Providers: []*store.Provider{demandProvider("lab")},
			Jobs: demandJobs(queued), Limits: demandLimits(),
			Plan: scheduler.Plan{Pools: []scheduler.PoolPlan{demandPoolPlan(pool, current, desired, queued, blocked)}},
		}
	}
	for _, tc := range []struct {
		name     string
		snapshot func() MachineSnapshot
		// want leaves out the pool, which is alpha in every row, and the
		// provider's id, which follows from its name.
		want PoolRenting
		// aside is what a page already showing the scheduler's sentence adds,
		// when that is not the whole summary.
		aside string
	}{
		{
			name:     "renting a machine",
			snapshot: func() MachineSnapshot { return snapshot(0, 1, 1, "nowhere") },
			want: PoolRenting{
				State:        RentingBuying,
				Summary:      "Renting 1 machine from lab, which covers this pool: 1 runner slot short with 1 job queued, and no host in the fleet can run it.",
				ProviderName: "lab", Queued: 1, Short: 1, Machines: 1,
			},
		},
		{
			name: "renting part of what it needs, held back by the provider's maximum",
			snapshot: func() MachineSnapshot {
				s := snapshot(0, 4, 4, "nowhere")
				s.Providers[0].MaxMachines = 1
				return s
			},
			want: PoolRenting{
				State:        RentingBuying,
				Summary:      "Renting 1 of the 2 machines it needs from lab, which covers this pool: 4 runner slots short with 4 jobs queued, and no host in the fleet can run it. The rest are held back: lab may own only 1 machine.",
				Fix:          "Raise this provider's maximum machines.",
				ProviderName: "lab", Queued: 4, Short: 4, Machines: 1,
			},
		},
		{
			name: "renting part of what it needs, held back by what the fleet may build at once",
			snapshot: func() MachineSnapshot {
				s := snapshot(0, 4, 4, "nowhere")
				s.Limits.MaxCreatesInFlight = 1
				return s
			},
			want: PoolRenting{
				State:        RentingBuying,
				Summary:      "Renting 1 of the 2 machines it needs from lab, which covers this pool: 4 runner slots short with 4 jobs queued, and no host in the fleet can run it. The rest are held back: provider.max_creates_in_flight allows only 1 machine at a time.",
				Fix:          "Raise provider.max_creates_in_flight.",
				Setting:      "provider.max_creates_in_flight",
				ProviderName: "lab", Queued: 4, Short: 4, Machines: 1,
			},
		},
		{
			// A provider's own limit is on its own form rather than in
			// Settings, so no setting is named.
			name: "renting part of what it needs, held back by what the provider may build at once",
			snapshot: func() MachineSnapshot {
				s := snapshot(0, 4, 4, "nowhere")
				s.Providers[0].MaxCreatesInFlight = 1
				return s
			},
			want: PoolRenting{
				State:        RentingBuying,
				Summary:      "Renting 1 of the 2 machines it needs from lab, which covers this pool: 4 runner slots short with 4 jobs queued, and no host in the fleet can run it. The rest are held back: lab may build only 1 machine at a time.",
				Fix:          "Raise this provider's maximum creates in flight.",
				ProviderName: "lab", Queued: 4, Short: 4, Machines: 1,
			},
		},
		{
			name: "one machine on its way",
			snapshot: func() MachineSnapshot {
				s := snapshot(0, 2, 2, "nowhere")
				m := demandMachine("mach_1", s.Providers[0], store.MachineCreating, 3*time.Minute)
				m.Capacity = 2
				s.Machines = []*store.Machine{m}
				return s
			},
			want: PoolRenting{
				State:        RentingOnItsWay,
				Summary:      "1 machine from lab is on the way for this pool, so the next runners start there.",
				ProviderName: "lab", Queued: 2, Short: 2, Machines: 1,
				Since: ptrTime(machineNow.Add(-3 * time.Minute)),
			},
		},
		{
			// Handed over newest first, so the time given is the oldest
			// machine's because it is the oldest and not because it came first.
			name: "two machines on their way",
			snapshot: func() MachineSnapshot {
				s := snapshot(0, 4, 3, "nowhere")
				s.Machines = []*store.Machine{
					demandMachine("mach_newer", s.Providers[0], store.MachinePlanned, time.Minute),
					demandMachine("mach_older", s.Providers[0], store.MachineStarting, 6*time.Minute),
				}
				return s
			},
			want: PoolRenting{
				State:        RentingOnItsWay,
				Summary:      "2 machines from lab are on the way for this pool, so the next runners start there.",
				ProviderName: "lab", Queued: 3, Short: 4, Machines: 2,
				Since: ptrTime(machineNow.Add(-6 * time.Minute)),
			},
		},
		{
			// Two providers' machines cover the pool between them, and the
			// sentence names one provider, so it counts only that provider's:
			// "2 machines from alpha-lab" would send an operator looking for a
			// machine alpha-lab is not building.
			name: "machines from two providers on their way",
			snapshot: func() MachineSnapshot {
				s := snapshot(0, 4, 4, "nowhere")
				alpha, beta := demandProvider("alpha-lab"), demandProvider("beta-lab")
				s.Providers = []*store.Provider{beta, alpha}
				s.Machines = []*store.Machine{
					demandMachine("mach_beta", beta, store.MachinePlanned, time.Minute),
					demandMachine("mach_alpha", alpha, store.MachineCreating, 5*time.Minute),
				}
				return s
			},
			want: PoolRenting{
				State:        RentingOnItsWay,
				Summary:      "1 machine from alpha-lab is on the way for this pool, so the next runners start there.",
				ProviderName: "alpha-lab", Queued: 4, Short: 4, Machines: 1,
				Since: ptrTime(machineNow.Add(-5 * time.Minute)),
			},
		},
		{
			name: "waiting for hosts that could run it",
			snapshot: func() MachineSnapshot {
				s := snapshot(1, 2, 1, "")
				s.Plan.Pools[0].Blocked = "no host can take a new docker runner (1 cordoned, 3 at capacity)"
				return s
			},
			want: PoolRenting{
				State:   RentingWaiting,
				Summary: "Not renting yet: no host can take a new docker runner (1 cordoned, 3 at capacity). A machine is rented only once every host that could run this pool is full.",
				Fix:     "Wait for those hosts to clear, or uncordon, repair or remove the ones that are unavailable.",
				Queued:  1, Short: 1,
			},
			aside: "A machine is rented only once every host that could run this pool is full.",
		},
		{
			name: "held back by the fleet's maximum",
			snapshot: func() MachineSnapshot {
				s := snapshot(0, 1, 1, "nowhere")
				s.Limits.MaxMachines = 0
				return s
			},
			want: PoolRenting{
				State:        RentingCeiling,
				Summary:      "Not renting: provider.max_machines is 0, so this fleet rents nothing.",
				Fix:          "Set provider.max_machines to the number of machines this fleet may pay for.",
				Setting:      "provider.max_machines",
				Because:      "provider.max_machines is 0, so this fleet rents nothing",
				ProviderName: "lab", Queued: 1, Short: 1,
			},
		},
		{
			// lab's one machine is a host already, and busy, so the pool is
			// still short and lab may not own another.
			name: "held back by the provider's maximum",
			snapshot: func() MachineSnapshot {
				s := snapshot(2, 3, 1, "capacity")
				p := s.Providers[0]
				p.MaxMachines = 1
				host := demandHost("host_1", 2, 2)
				ready := demandMachine("mach_1", p, store.MachineReady, time.Hour)
				ready.HostID = host.ID
				s.Hosts, s.Machines = []*store.Host{host}, []*store.Machine{ready}
				return s
			},
			want: PoolRenting{
				State:        RentingCeiling,
				Summary:      "Not renting: lab owns 1 machine and its maximum is 1.",
				Fix:          "Raise this provider's maximum machines, or wait for one of its machines to be released.",
				Because:      "lab owns 1 machine and its maximum is 1",
				ProviderName: "lab", Queued: 1, Short: 1,
			},
		},
		{
			name: "refused by a provider's pool selector",
			snapshot: func() MachineSnapshot {
				s := snapshot(0, 1, 1, "nowhere")
				s.Providers[0].PoolSelector = store.StringMap{"tier": "large"}
				return s
			},
			want: PoolRenting{
				State:   RentingUnserved,
				Summary: "No provider will rent for this pool. Provider lab only rents for pools matching tier=large, and pool alpha does not have tier=large.",
				Fix:     "Edit the provider's pool selector, or give the pool the label tier=large.",
				Queued:  1, Short: 1,
			},
		},
		{
			name: "no provider builds a machine that suits it",
			snapshot: func() MachineSnapshot {
				s := snapshot(0, 1, 1, "nowhere")
				s.Pools[0].Backend = store.BackendProcess
				return s
			},
			want: PoolRenting{
				State:   RentingUnserved,
				Summary: "No provider builds a machine this pool could use. lab: The machines it builds run docker, and this pool needs process.",
				Fix:     "Give a provider machines that suit this pool, or change the pool.",
				Queued:  1, Short: 1,
			},
		},
		{
			// Handed over out of order, so the provider named is the first by
			// name and not the first in the slice.
			name: "no provider of two builds a machine that suits it",
			snapshot: func() MachineSnapshot {
				s := snapshot(0, 1, 1, "nowhere")
				s.Pools[0].Backend = store.BackendProcess
				s.Providers = []*store.Provider{demandProvider("beta-lab"), demandProvider("alpha-lab")}
				return s
			},
			want: PoolRenting{
				State:   RentingUnserved,
				Summary: "No provider builds a machine this pool could use. alpha-lab: The machines it builds run docker, and this pool needs process.",
				Fix:     "Give a provider machines that suit this pool, or change the pool.",
				Queued:  1, Short: 1,
			},
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			s := tc.snapshot()
			got := theVerdict(t, DecideMachines(s))

			want := tc.want
			want.PoolID, want.PoolName = "pool_alpha", "alpha"
			if want.ProviderName != "" {
				want.ProviderID = "prv_" + want.ProviderName
			}
			// Since is compared as an instant below; everything else must
			// match exactly.
			gotRest, wantRest := got, want
			gotRest.Since, wantRest.Since = nil, nil
			if gotRest != wantRest {
				t.Errorf("verdict:\n got %+v\nwant %+v", gotRest, wantRest)
			}
			switch {
			case (got.Since == nil) != (want.Since == nil):
				t.Errorf("since = %v, want %v", got.Since, want.Since)
			case got.Since != nil && !got.Since.Equal(*want.Since):
				t.Errorf("since = %v, want %v", *got.Since, *want.Since)
			}

			aside := tc.aside
			if aside == "" {
				aside = want.Summary
			}
			if got.Aside() != aside {
				t.Errorf("aside = %q,\n want %q", got.Aside(), aside)
			}

			// The verdict outlives the pass and the machine rows are the
			// controller's own, so a since that pointed into a row would let
			// whatever holds the verdict rewrite when the machine was made.
			if got.Since != nil {
				*got.Since = time.Time{}
				for _, m := range s.Machines {
					if m.CreatedAt.IsZero() {
						t.Errorf("writing the verdict's since rewrote machine %s's created_at", m.ID)
					}
				}
			}
		})
	}
}

// Two providers that could both rent for a pool are one purchase charged to
// one of them, and so one verdict: two would tell an operator that two
// machines were on order for work one of them answers.
func TestTwoProvidersThatServeOnePoolGiveOneVerdict(t *testing.T) {
	alpha, beta := demandProvider("alpha-lab"), demandProvider("beta-lab")
	pool := demandPool("linux-x64", "linux", "x64")
	s := MachineSnapshot{
		Now: machineNow, Pools: []*store.Pool{pool},
		// Handed over out of order, so the provider charged is the first by
		// name and not the first in the slice.
		Providers: []*store.Provider{beta, alpha},
		Jobs:      demandJobs(2), Limits: demandLimits(),
		Plan: scheduler.Plan{Pools: []scheduler.PoolPlan{demandPoolPlan(pool, 0, 2, 2, "nowhere")}},
	}

	plan := DecideMachines(s)
	if len(plan.Pools) != 1 {
		t.Fatalf("verdicts = %+v, want one for the one pool", plan.Pools)
	}
	if got := plan.Pools[0].ProviderName; got != "alpha-lab" {
		t.Fatalf("charged to %q, want alpha-lab, the first by name", got)
	}
}

// One provider buying for several pools makes one purchase for all of them.
// When the whole purchase is made, each pool is told its own share: the
// provider's whole order would tell a pool one slot short that it needs two
// machines. When it is held back, the machines bought serve whichever pool the
// scheduler places on them first, so none of the pools is told it is covered,
// and each is told about the pools together. Either way the provider's own
// order is the group's, because it is one purchase.
func TestPoolsSharingAProviderQuoteTheirOwnShareOrSpeakForTheGroupWhenItIsHeldBack(t *testing.T) {
	// queuedFor is n queued jobs that only the pool advertising label claims.
	queuedFor := func(label string, n int) []*store.Job {
		jobs := demandJobs(n)
		for _, j := range jobs {
			j.ID += "_" + label
			j.Labels = append(j.Labels, label)
		}
		return jobs
	}
	for _, tc := range []struct {
		name   string
		limits func(*MachineLimits)
		// alpha and beta are how many runner slots each pool is short, with
		// as many jobs queued.
		alpha, beta int
		// create and wanted are the provider's own order.
		create, wanted int
		want           []PoolRenting
	}{
		{
			name:   "the fleet may build one machine at a time",
			limits: func(l *MachineLimits) { l.MaxCreatesInFlight = 1 },
			alpha:  1, beta: 3,
			create: 1, wanted: 2,
			want: []PoolRenting{
