						t.Errorf("pool %s says it is covered by a purchase that was held back: %q", v.PoolName, v.Summary)
					}
				}
			}
		})
	}
}

// A pool the scheduler is waiting on hosts for is told that a machine follows
// once they are full, which is only true if some provider could build one it
// could use. Where none could, that would promise a machine that never comes,
// so the pool is told what is really in the way. It is a verdict only:
// MachinePlan.Unserved is the pools whose work a machine would answer, and
// this pool's waits on its hosts, so that list and the purchase stay as they
// were.
func TestAPoolNoProviderCouldServeIsToldSoRatherThanToWait(t *testing.T) {
	// The plan is what the scheduler says of a pool with one host busy and one
	// cordoned: blocked, in a way an uncordon or a finished job clears, so
	// neither capacity flag is set. A fleet whose only host is cordoned is one
	// with no eligible host instead, and never takes this branch.
	waitingOn := func(pool *store.Pool) scheduler.PoolPlan {
		pp := demandPoolPlan(pool, 1, 2, 1, "")
		pp.Blocked = "no host can take a new " + string(pool.Backend) + " runner (1 cordoned, 1 at capacity)"
		return pp
	}
	for _, tc := range []struct {
		name     string
		pool     func(*store.Pool)
		provider func(*store.Provider)
		want     PoolRenting
	}{
		{
			name:     "no provider builds a machine it could use",
			pool:     func(p *store.Pool) { p.Backend = store.BackendProcess },
			provider: func(*store.Provider) {},
			want: PoolRenting{
				State:   RentingUnserved,
				Summary: "No provider builds a machine this pool could use. lab: The machines it builds run docker, and this pool needs process.",
				Fix:     "Give a provider machines that suit this pool, or change the pool.",
				Queued:  1, Short: 1,
			},
		},
		{
			name:     "a selector rules the provider out",
			pool:     func(*store.Pool) {},
			provider: func(p *store.Provider) { p.PoolSelector = store.StringMap{"tier": "large"} },
			want: PoolRenting{
				State:   RentingUnserved,
				Summary: "No provider will rent for this pool. Provider lab only rents for pools matching tier=large, and pool alpha does not have tier=large.",
				Fix:     "Edit the provider's pool selector, or give the pool the label tier=large.",
				Queued:  1, Short: 1,
			},
		},
		{
			name:     "a provider could serve it",
			pool:     func(*store.Pool) {},
			provider: func(*store.Provider) {},
			want: PoolRenting{
				State:   RentingWaiting,
				Summary: "Not renting yet: no host can take a new docker runner (1 cordoned, 1 at capacity). A machine is rented only once every host that could run this pool is full.",
				Fix:     "Wait for those hosts to clear, or uncordon, repair or remove the ones that are unavailable.",
				Queued:  1, Short: 1,
			},
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			p := demandProvider("lab")
			tc.provider(p)
			pool := demandPool("alpha", "linux", "x64")
			tc.pool(pool)
			s := MachineSnapshot{
				Now: machineNow, Pools: []*store.Pool{pool}, Providers: []*store.Provider{p},
				Jobs: demandJobs(1), Limits: demandLimits(),
				Plan: scheduler.Plan{Pools: []scheduler.PoolPlan{waitingOn(pool)}},
			}

			plan := DecideMachines(s)
			want := tc.want
			want.PoolID, want.PoolName = pool.ID, pool.Name
			if got := theVerdict(t, plan); got != want {
				t.Errorf("verdict:\n got %+v\nwant %+v", got, want)
			}
			if len(plan.Unserved) != 0 {
				t.Errorf("unserved = %+v, want none: this pool's work waits on its hosts, not on a machine", plan.Unserved)
			}
			if got := planFor(t, plan, p.ID); got.Create != 0 || got.Reason != "" || got.Blocked != "" {
				t.Errorf("provider plan = %+v, want nothing bought and nothing said", got)
			}
		})
	}
}

// A pool charged to a provider is decided after every pool the walk passed
// over, so a list in the order decisions were made would put beta before alpha
// here. The pages that show verdicts list pools by name, and so does this.
func TestVerdictsAreInPoolNameOrderWhicheverWayTheyWereDecided(t *testing.T) {
	p := demandProvider("lab")
	alpha, beta := demandPool("alpha", "linux", "x64"), demandPool("beta", "linux", "x64")
	waiting := demandPoolPlan(beta, 1, 2, 0, "")
	waiting.Blocked = "no host can take a new docker runner (1 cordoned, 1 at capacity)"
	s := MachineSnapshot{
		Now: machineNow, Pools: []*store.Pool{alpha, beta}, Providers: []*store.Provider{p},
		Jobs: demandJobs(1), Limits: demandLimits(),
		Plan: scheduler.Plan{Pools: []scheduler.PoolPlan{demandPoolPlan(alpha, 0, 1, 1, "nowhere"), waiting}},
	}

	plan := DecideMachines(s)
	var got []string
	for _, v := range plan.Pools {
		got = append(got, v.PoolName+" "+string(v.State))
	}
	if want := []string{"alpha renting", "beta waiting"}; !slices.Equal(got, want) {
		t.Fatalf("verdicts = %v, want %v", got, want)
	}
}

// A pool below its min_runners with nothing queued is renting for the runners
// it keeps warm. "With 0 jobs queued" would read as a machine rented for no
// work at all.
func TestAPoolShortOfItsMinimumWithNothingQueuedDoesNotMentionAQueue(t *testing.T) {
	p := demandProvider("lab")
	pool := demandPool("alpha")
	s := MachineSnapshot{
		Now: machineNow, Pools: []*store.Pool{pool}, Providers: []*store.Provider{p}, Limits: demandLimits(),
		Plan: scheduler.Plan{Pools: []scheduler.PoolPlan{demandPoolPlan(pool, 0, 2, 0, "nowhere")}},
	}

	want := "Renting 1 machine from lab, which covers this pool: 2 runner slots short, and no host in the fleet can run it."
	if got := theVerdict(t, DecideMachines(s)).Summary; got != want {
		t.Fatalf("summary = %q,\n want %q", got, want)
	}
}

// A pool the scheduler is placing runners for needs nothing rented and nothing
// said about renting: a verdict there would list a pool that is fine among the
// pools to look at.
func TestAPoolTheSchedulerCanPlaceItselfGetsNoVerdict(t *testing.T) {
	p := demandProvider("lab")
	pool := demandPool("alpha", "linux", "x64")
	s := MachineSnapshot{
		Now: machineNow, Pools: []*store.Pool{pool}, Providers: []*store.Provider{p},
		Jobs: demandJobs(2), Limits: demandLimits(),
		// Short, but only of this pass's create budget, which clears itself.
		Plan: scheduler.Plan{Pools: []scheduler.PoolPlan{demandPoolPlan(pool, 0, 2, 2, "")}},
	}

	if plan := DecideMachines(s); len(plan.Pools) != 0 {
		t.Fatalf("verdicts = %+v, want none", plan.Pools)
	}
}

// A free slot on a host that could run the pool is the fleet's own answer to
// its queue. Nothing is rented against it, and a verdict there would send an
// operator looking for a fault that is not there.
func TestAPoolCoveredByFreeSlotsGetsNoVerdict(t *testing.T) {
	p := demandProvider("lab")
	pool := demandPool("alpha", "linux", "x64")
	host := demandHost("host_1", 4, 2) // two slots free
	s := MachineSnapshot{
		Now: machineNow, Pools: []*store.Pool{pool}, Hosts: []*store.Host{host}, Providers: []*store.Provider{p},
		Jobs: demandJobs(2), Limits: demandLimits(),
		Plan: scheduler.Plan{Pools: []scheduler.PoolPlan{demandPoolPlan(pool, 2, 4, 2, "capacity")}},
	}

	plan := DecideMachines(s)
	if got := planFor(t, plan, p.ID).Create; got != 0 {
		t.Fatalf("create = %d, want 0: the free slots cover the pool", got)
	}
	if len(plan.Pools) != 0 {
		t.Fatalf("verdicts = %+v, want none", plan.Pools)
	}
}

// A fenced fleet creates and deletes nothing at any provider, so a machine that
// was on its way is not being finished. Told it was on the way, an operator
// would wait for runners that cannot start until the fence is lifted.
func TestAFencedFleetDoesNotSayAMachineIsOnItsWay(t *testing.T) {
	onItsWay := PoolRenting{
		PoolID: "pool_alpha", PoolName: "alpha", State: RentingOnItsWay, ProviderID: "prv_lab",
		ProviderName: "lab", Summary: "1 machine from lab is on the way for this pool, so the next runners start there.",
		Queued: 2, Short: 2, Machines: 1,
	}
	view := buildRentingView(rentingInput{
		Enabled: true, MaxMachines: 10, Fenced: true,
		Usable: []*store.Provider{demandProvider("lab")},
		Report: &rentingReport{Pools: []PoolRenting{onItsWay}},
	})
	if len(view.Pools) != 1 {
		t.Fatalf("pools = %+v, want one", view.Pools)
	}
	got := view.Pools[0]
	if got.State != RentingHeld {
		t.Fatalf("state = %q (%q), want held: nothing finishes a machine while the fleet is fenced", got.State, got.Summary)
	}
	if !strings.Contains(got.Summary, "fenced") || strings.Contains(got.Summary, "on the way") {
		t.Fatalf("summary = %q, want it to say the fleet is fenced and not that a machine is on the way", got.Summary)
	}
}

package controller

import (
	"encoding/json"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// The fleet's sentences, written out here rather than read from the code so
// that a change to the wording is a change to this file as well: the Providers
// page, the renting problem and the MCP tools all quote them.
const (
	wantFleetNone         = "No provider is configured, so nothing is rented."
	wantFleetOff          = "Renting is switched off: this controller is not allowed to rent machines, so work with nowhere to run waits for the hosts it has."
	wantFleetOffFix       = "Turn on Rent machines in Settings, and set Machines the fleet may rent to the most you are willing to pay for."
	wantFleetNoCeiling    = "Renting is on, but the fleet may rent no machines: a maximum of none is none."
	wantFleetNoCeilingFix = "Set Machines the fleet may rent to the most machines you are willing to pay for at once."
	wantFleetOn           = "Renting is on."
)

// rentingProvider is a provider with a ceiling of its own, for the tests that
// add ceilings up.
func rentingProvider(name string, ceiling int) *store.Provider {
	p := demandProvider(name)
	p.MaxMachines = ceiling
	return p
}

// lastPass is the report of a pass that reached these verdicts.
func lastPass(verdicts ...PoolRenting) *rentingReport {
	return &rentingReport{At: machineNow, Pools: verdicts}
}

// The fleet's state is the first thing an operator reads about renting, and the
// four call for different things: add a provider, switch renting on, give the
// fleet a ceiling, or nothing at all. Each is pinned with its words and the one
// setting its fix changes, because the Providers page offers to change exactly
// that setting, and with the ceiling it offers, because that is what the one
// click sets.
func TestTheRentingViewSaysWhichSwitchIsHoldingRentingBack(t *testing.T) {
	disabled := rentingProvider("lab", 2)
	disabled.Enabled = false
	demo := rentingProvider("demo-pve", 2)
	demo.ID = "prv_demofixture"
	verdict := PoolRenting{
		PoolID: "pool_alpha", PoolName: "alpha", State: RentingBuying,
		Summary:    "Renting 1 machine from lab, which covers this pool: 1 runner slot short, and no host in the fleet can run it.",
		ProviderID: "prv_lab", ProviderName: "lab", Short: 1, Machines: 1,
	}

	for _, tc := range []struct {
		name                         string
		providers                    []*store.Provider
		enabled                      bool
		maxMachines                  int
		state, summary, fix, setting string
		suggested                    int
		// pools is how many of the pass's verdicts the view carries: every one
		// while some provider may rent, and none when nothing can be.
		pools int
	}{
		{
			name:      "renting switched off",
			providers: []*store.Provider{rentingProvider("lab", 2)},
			state:     "off", summary: wantFleetOff, fix: wantFleetOffFix, setting: "provider.enabled",
			suggested: 2, pools: 1,
		},
		{
			name:      "renting on with no ceiling",
			providers: []*store.Provider{rentingProvider("lab", 2)},
			enabled:   true,
			state:     "no_ceiling", summary: wantFleetNoCeiling, fix: wantFleetNoCeilingFix, setting: "provider.max_machines",
			suggested: 2, pools: 1,
		},
		{
			name:      "renting on with a ceiling",
			providers: []*store.Provider{rentingProvider("lab", 2)},
			enabled:   true, maxMachines: 2,
			state: "on", summary: wantFleetOn,
			suggested: 2, pools: 1,
		},
		{
			name:    "no provider at all",
			enabled: true, maxMachines: 2,
			state: "none", summary: wantFleetNone,
			suggested: 1,
		},
		{
			// Review Focus 1. With renting off, provisioningHeld answers with
			// the switch for this row as for any other, so a state read from
			// it would be off, and the page would offer to switch renting on
			// for a provider that would still rent nothing.
			name:      "a provider whose own row is disabled",
			providers: []*store.Provider{disabled},
			state:     "none", summary: wantFleetNone,
			suggested: 1,
		},
		{
			name:      "the demo fixture alone",
			providers: []*store.Provider{demo},
			state:     "none", summary: wantFleetNone,
			suggested: 1,
		},
		{
			name:      "two providers suggest their ceilings added up",
			providers: []*store.Provider{rentingProvider("lab", 2), rentingProvider("rack", 3)},
			state:     "off", summary: wantFleetOff, fix: wantFleetOffFix, setting: "provider.enabled",
			suggested: 5, pools: 1,
		},
		{
			// A click that set the fleet's ceiling to the sum of none would
			// switch renting on and leave it renting nothing.
			name:      "a provider with no ceiling of its own still suggests one machine",
			providers: []*store.Provider{rentingProvider("lab", 0)},
			state:     "off", summary: wantFleetOff, fix: wantFleetOffFix, setting: "provider.enabled",
			suggested: 1, pools: 1,
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			got := buildRentingView(rentingInput{
				Report: lastPass(verdict), Usable: usableRows(tc.providers),
				Enabled: tc.enabled, MaxMachines: tc.maxMachines,
			})
			if got.State != tc.state {
				t.Errorf("state = %q, want %q", got.State, tc.state)
			}
			if got.Summary != tc.summary {
				t.Errorf("summary = %q,\n want %q", got.Summary, tc.summary)
			}
			if got.Fix != tc.fix {
				t.Errorf("fix = %q,\n want %q", got.Fix, tc.fix)
			}
			if got.Setting != tc.setting {
				t.Errorf("setting = %q, want %q", got.Setting, tc.setting)
			}
			if got.SuggestedMaxMachines != tc.suggested {
				t.Errorf("suggested max machines = %d, want %d", got.SuggestedMaxMachines, tc.suggested)
			}
			if got.Enabled != tc.enabled || got.MaxMachines != tc.maxMachines {
				t.Errorf("switches = enabled %v, max %d; want them as they stand, %v and %d",
					got.Enabled, got.MaxMachines, tc.enabled, tc.maxMachines)
			}
			if len(got.Pools) != tc.pools {
				t.Errorf("pools = %+v, want %d of them", got.Pools, tc.pools)
			}
		})
	}
}

// A pass decides whether or not renting is switched on, and with it off, what it
// decided is what renting being off prevents: so many machines it would rent, a
// ceiling that would have stopped it as well, or a machine nothing is
// finishing. Those three say so and name the one setting that changes it. A
// pool waiting on its hosts, or one no provider serves, is in the same place
// whichever way the switch is, and is told the same thing. With renting on, a
// purchase the provider may not make is held rather than renting.
func TestTheOverlayTurnsWhatWouldBeBoughtIntoWhatRentingBeingOffPrevents(t *testing.T) {
	since := machineNow.Add(-4 * time.Minute)
	renting := PoolRenting{
		PoolID: "pool_alpha", PoolName: "alpha", State: RentingBuying,
		Summary:    "Renting 1 machine from lab, which covers this pool: 1 runner slot short with 1 job queued, and no host in the fleet can run it.",
		ProviderID: "prv_lab", ProviderName: "lab", Queued: 1, Short: 1, Machines: 1,
	}
	partial := PoolRenting{
		PoolID: "pool_beta", PoolName: "beta", State: RentingBuying,
		Summary:    "Renting 2 of the 3 machines it needs from lab, which covers this pool: 6 runner slots short with 6 jobs queued, and no host in the fleet can run it. The rest are held back: provider.max_creates_in_flight allows only 2 machines at a time.",
		Fix:        "Raise provider.max_creates_in_flight.",
		Setting:    "provider.max_creates_in_flight",
		ProviderID: "prv_lab", ProviderName: "lab", Queued: 6, Short: 6, Machines: 2,
	}
	ceiling := PoolRenting{
		PoolID: "pool_gamma", PoolName: "gamma", State: RentingCeiling,
		Summary:    "Not renting: provider.max_machines is 0, so this fleet rents nothing.",
		Fix:        "Set provider.max_machines to the number of machines this fleet may pay for.",
		Setting:    "provider.max_machines",
		Because:    "provider.max_machines is 0, so this fleet rents nothing",
		ProviderID: "prv_lab", ProviderName: "lab", Queued: 1, Short: 1,
	}
	coming := PoolRenting{
		PoolID: "pool_delta", PoolName: "delta", State: RentingOnItsWay,
		Summary:    "1 machine from lab is on the way for this pool, so the next runners start there.",
		ProviderID: "prv_lab", ProviderName: "lab", Queued: 2, Short: 2, Machines: 1, Since: &since,
	}
	waiting := PoolRenting{
		PoolID: "pool_epsilon", PoolName: "epsilon", State: RentingWaiting,
		Summary: "Not renting yet: no host can take a new docker runner (1 cordoned, 1 at capacity). A machine is rented only once every host that could run this pool is full.",
		Fix:     "Wait for those hosts to clear, or uncordon, repair or remove the ones that are unavailable.",
		Queued:  1, Short: 1,
	}
	unserved := PoolRenting{
		PoolID: "pool_zeta", PoolName: "zeta", State: RentingUnserved,
		Summary: "No provider will rent for this pool. Provider lab only rents for pools matching tier=large, and pool zeta does not have tier=large.",
		Fix:     "Edit the provider's pool selector, or give the pool the label tier=large.",
		Queued:  1, Short: 1,
	}
	report := lastPass(renting, partial, ceiling, coming, waiting, unserved)
	decided := slices.Clone(report.Pools)
	usable := []*store.Provider{demandProvider("lab")}

	for _, tc := range []struct {
		name    string
		enabled bool
		held    map[string]string
		want    []PoolRenting
	}{
		{
			name: "renting switched off",
			want: func() []PoolRenting {
				off := func(v PoolRenting, summary string) PoolRenting {
					v.State, v.Summary, v.Fix, v.Setting = RentingOff, summary, wantFleetOffFix, "provider.enabled"
					return v
				}
				// The machines on their way were counted as coming, and while
				// renting is off nothing brings them. They are not machines the
				// pass would rent either, so the pool is said to want none.
				stranded := off(coming, "A machine for this pool was being built, but renting is switched off, so nothing is finishing it.")
				stranded.Machines = 0
				return []PoolRenting{
					off(renting, "Would rent 1 machine for this pool, but renting is switched off."),
					off(partial, "Would rent 2 machines for this pool, but renting is switched off."),
					off(ceiling, "Renting is switched off, and provider.max_machines is 0, so this fleet rents nothing."),
					stranded,
					waiting,
					unserved,
				}
			}(),
		},
		{
			// The fix a partial purchase named goes with it: raising a ceiling
			// does nothing for a provider that is paused.
			name:    "renting on, and the provider may not buy",
			enabled: true,
			held:    map[string]string{"prv_lab": "lab is paused: over budget"},
			want: func() []PoolRenting {
				held := func(v PoolRenting) PoolRenting {
					v.State, v.Summary, v.Fix, v.Setting = RentingHeld, "Not renting: lab is paused: over budget.", "", ""
					return v
				}
				return []PoolRenting{held(renting), held(partial), ceiling, coming, waiting, unserved}
			}(),
		},
		{
			// Another provider being held holds back none of lab's purchases.
			name:    "renting on, and nothing holds the provider back",
			enabled: true,
			held:    map[string]string{"prv_rack": "rack is paused: over budget"},
			want:    decided,
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			got := buildRentingView(rentingInput{
				Report: report, Usable: usable, Enabled: tc.enabled, MaxMachines: 10, Held: tc.held,
			}).Pools
			if !slices.Equal(got, tc.want) {
				t.Errorf("pools:\n got %+v\nwant %+v", got, tc.want)
			}
			// The report is the pass's, and every read lays the switches over it
			// afresh, so a read that wrote its overlay back would leave the
			// next one describing a switch that has since moved.
			if !slices.Equal(report.Pools, decided) {
				t.Errorf("building the view rewrote the report:\n got %+v\nwant %+v", report.Pools, decided)
			}
		})
	}
}

// Before the first machine pass there is no verdict yet, but the switches are
// known, and a page that asks is told them rather than left waiting for the
// loop. The pools are an empty list and never null (Review Focus 3), so a page
// that lists them needs no case of its own for the first moments after a start.
func TestTheViewBeforeTheFirstPassHasTheSwitchesAndNoPools(t *testing.T) {
	got := buildRentingView(rentingInput{
		Usable: []*store.Provider{rentingProvider("lab", 3)}, Enabled: true, Paused: true, MaxMachines: 2,
	})
	if got.State != "on" || !got.Enabled || !got.Paused || got.MaxMachines != 2 || got.SuggestedMaxMachines != 3 {
		t.Errorf("view = %+v, want the switches as they stand: on, paused, a ceiling of 2, and 3 suggested", got)
	}
	if got.Pools == nil || len(got.Pools) != 0 {
		t.Errorf("pools = %#v, want an empty list", got.Pools)
	}
	if got.DecidedAt != nil || got.Owned != 0 {
		t.Errorf("decided at %v with %d owned, want neither before a pass has run", got.DecidedAt, got.Owned)
	}

	raw, err := json.Marshal(got)
	if err != nil {
		t.Fatalf("marshalling the view: %v", err)
	}
	if !strings.Contains(string(raw), `"pools":[]`) {
		t.Errorf("the view renders as %s, want pools as an empty list", raw)
	}
	if strings.Contains(string(raw), `"decided_at"`) {
		t.Errorf("the view renders as %s, want no decision time before there is a decision", raw)
	}
}

package controller

import (
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/store"
)

// The restart boundary table.
//
// A controller restart drops the task queue, by design: every task is derived
// from state the database already holds, so persisting the queue would add a
// second source of truth that could disagree with the runners table. The price
// is that a result arriving after the restart answers a task the new
// controller has never heard of, and it must still be applied -- the agent did
// the work, and the row is the only place that fact can land.
//
// Each row here puts a runner at one boundary with a task in flight, restarts
// the controller over the same store, replays the agent's result, and asserts
// the fleet converges: the state the result implies, and never two live rows
// for one runner name. Duplicate live rows are the failure this guards
// against, because a name is a GitHub registration, and two of them means one
// runner executing jobs that the fleet is accounting for twice.
func TestALateResultAfterARestartLeavesOneLiveRowPerRunner(t *testing.T) {
	cases := []struct {
		name string
		// state the runner is in when the controller goes down.
		state store.RunnerState
		// kind of the task the agent is still working on.
		kind agent.TaskKind
		// inflight polls the task, so it is in flight rather than queued.
		inflight bool
		// result the agent reports once the controller is back.
		ok        bool
		reports   store.RunnerState
		wantState store.RunnerState
	}{
		{
			name:  "create enqueued but never collected",
			state: store.RunnerProvisioning, kind: agent.TaskCreateRunner,
			ok: true, reports: store.RunnerRegistering, wantState: store.RunnerRegistering,
		},
		{
			name:  "create acknowledged and in flight",
			state: store.RunnerProvisioning, kind: agent.TaskCreateRunner, inflight: true,
			ok: true, reports: store.RunnerRegistering, wantState: store.RunnerRegistering,
		},
		{
			name:  "create failed on the host",
			state: store.RunnerProvisioning, kind: agent.TaskCreateRunner, inflight: true,
			ok: false, wantState: store.RunnerFailed,
		},
		{
			name:  "registering when the controller went down",
			state: store.RunnerRegistering, kind: agent.TaskCreateRunner, inflight: true,
			ok: true, reports: store.RunnerIdle, wantState: store.RunnerIdle,
		},
		{
			name:  "busy with a stop in flight",
			state: store.RunnerBusy, kind: agent.TaskStopRunner, inflight: true,
			ok: true, reports: store.RunnerDraining, wantState: store.RunnerDraining,
		},
		{
			name:  "draining with a stop in flight",
			state: store.RunnerDraining, kind: agent.TaskStopRunner, inflight: true,
			ok: true, reports: store.RunnerRemoved, wantState: store.RunnerRemoved,
		},
		{
			name:  "remove in flight",
			state: store.RunnerDraining, kind: agent.TaskRemoveRunner, inflight: true,
			ok: true, reports: store.RunnerRemoved, wantState: store.RunnerRemoved,
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			_, pool, host := h.fleet()
			r := h.runnerRow(pool, host, tc.state)

			task := agent.Task{ID: "task_boundary", Kind: tc.kind, RunnerID: r.ID, Backend: pool.Backend}
			h.c.enqueueLifecycle(h.ctx, host.ID, task)
			if tc.inflight {
				if _, err := h.c.PollTasks(h.ctx, host.ID, time.Second); err != nil {
					t.Fatalf("PollTasks: %v", err)
				}
			}

			// The restart. The rows are all that crosses it.
			c := h.restart()

			// The agent finishes the work it was already doing and reports a
			// result for a task this controller has never issued. Kind is
			// carried on the result precisely so it can still be understood.
			err := c.ReportResult(h.ctx, host.ID, agent.TaskResult{
				TaskID: task.ID, Kind: tc.kind, RunnerID: r.ID,
				OK: tc.ok, State: tc.reports, Error: errorFor(tc.ok),
			})
			if err != nil {
				t.Fatalf("ReportResult after the restart: %v", err)
			}

			got := h.runnerByID(t, r.ID)
			if got.State != tc.wantState {
				t.Errorf("state = %q, want %q: the agent's work was lost across the restart", got.State, tc.wantState)
			}
			assertOneLiveRowPerName(t, h)
		})
	}
}

func errorFor(ok bool) string {
	if ok {
		return ""
	}
	return "the workload could not be created"
}

// assertOneLiveRowPerName is the invariant the table exists for. A runner name
// is a GitHub registration, so two live rows sharing one would have the fleet
// account twice for a single runner -- and place work against capacity that
// does not exist.
func assertOneLiveRowPerName(t *testing.T, h *harness) {
	t.Helper()
	live := map[string]string{}
	for _, r := range h.runners() {
		if !r.State.Live() {
			continue
		}
		if other, dup := live[r.Name]; dup {
			t.Fatalf("runners %s and %s are both live as %q", other, r.ID, r.Name)
		}
		live[r.Name] = r.ID
	}
}

// The other half of the boundary: a result that arrives after the fleet has
// already given up on the runner. The five-minute host-lost reclaim is shorter
// than the twenty-minute create lease, so a create in flight on a host that
// goes quiet is failed before its lease has even expired -- and the agent,
// which never heard any of that, reports success when it comes back.
//
// The terminal row stands. It is what the operator and the job's timeline were
// told, and a success arriving afterwards does not make it untrue that this
// fleet stopped counting on the runner.
func TestALateSuccessDoesNotResurrectARunnerTheFleetGaveUpOn(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerProvisioning)

	task := agent.Task{ID: "task_late", Kind: agent.TaskCreateRunner, RunnerID: r.ID, Backend: pool.Backend}
	h.c.enqueueLifecycle(h.ctx, host.ID, task)
	if _, err := h.c.PollTasks(h.ctx, host.ID, time.Second); err != nil {
		t.Fatalf("PollTasks: %v", err)
	}
	if err := h.c.failRunnerID(h.ctx, r.ID, "host went quiet for longer than hostLostAfter", store.FaultHostLost); err != nil {
		t.Fatalf("failRunnerID: %v", err)
	}

	c := h.restart()
	if err := c.ReportResult(h.ctx, host.ID, agent.TaskResult{
		TaskID: task.ID, Kind: agent.TaskCreateRunner, RunnerID: r.ID,
		OK: true, State: store.RunnerRegistering,
	}); err != nil {
		t.Fatalf("ReportResult: %v", err)
	}

	got := h.runnerByID(t, r.ID)
	if got.State != store.RunnerFailed {
		t.Fatalf("state = %q, want it to stay failed; the fleet had already told an operator this runner was gone", got.State)
	}
	assertOneLiveRowPerName(t, h)
}

package controller

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"math"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
)

// Projection after authenticating and correlating a live create result. No full Spec, credentials, environment,
// workload handle, names, errors, logs or current pool settings enter the record.
func buildRunnerCreationObservation(host string, task agent.Task, res agent.TaskResult) (*store.RunnerCreationObservationData, error) {
	if task.Kind != agent.TaskCreateRunner || !res.OK || res.NotStarted {
		return nil, nil
	}
	if task.ID != res.TaskID || task.RunnerID != res.RunnerID || task.Spec == nil || task.Spec.RunnerID != task.RunnerID || task.Spec.PoolID != task.PoolID || (res.Kind != "" && res.Kind != task.Kind) {
		return nil, fmt.Errorf("%w: create result identity does not match the issued task", store.ErrInvalidRunnerCreationObservation)
	}
	spec := task.Spec
	d := &store.RunnerCreationObservationData{Version: store.RunnerCreationObservationVersion, HostID: host, RunnerID: task.RunnerID, PoolID: task.PoolID, TaskID: task.ID, IssuedAt: task.IssuedAt, Issued: store.IssuedRunnerConfiguration{Backend: task.Backend, DockerMode: spec.DockerMode, CPUTyped: spec.CPUTyped, MemoryTyped: spec.MemoryTyped}, Reported: store.ReportedRunnerCreation{DigestCoverage: "not_reported"}}
	if len(spec.Image) > 4096 || math.IsNaN(spec.Resources.CPUs) || math.IsInf(spec.Resources.CPUs, 0) || spec.Resources.CPUs < 0 || spec.Resources.MemoryMB < 0 {
		return nil, store.ErrInvalidRunnerCreationObservation
	}
	if spec.Image != "" {
		sum := sha256.Sum256([]byte(spec.Image))
		d.Issued.ImageReferenceSHA256 = hex.EncodeToString(sum[:])
	}
	if spec.Resources.CPUs > 0 {
		v := spec.Resources.CPUs
		d.Issued.CPUs = &v
	}
	if spec.Resources.MemoryMB > 0 {
		v := spec.Resources.MemoryMB
		d.Issued.MemoryMB = &v
	}
	if knownExperimentGrantSource(spec.ResourcesSource) {
		d.Issued.ResourceSource = spec.ResourcesSource
	}
	copyTime := func(t *time.Time) *time.Time {
		if t == nil || t.IsZero() {
			return nil
		}
		v := *t
		return &v
	}
	d.Reported.CompletedAt = copyTime(&res.CompletedAt)
	d.Reported.ContainerStartedAt = copyTime(res.ContainerStartedAt)
	if res.Digest != "" {
		d.Reported.DigestCoverage = "unsupported"
		if strings.HasPrefix(res.Digest, "sha256:") && len(res.Digest) == 71 {
			if _, err := hex.DecodeString(res.Digest[7:]); err == nil {
				v := strings.ToLower(res.Digest)
				d.Reported.ImageDigest = &v
				d.Reported.DigestCoverage = "reported"
			}
		}
	}
	if !store.ValidRunnerCreationObservation(d) {
		return nil, store.ErrInvalidRunnerCreationObservation
	}
	return d, nil
}

// The embedded agent shares task pointers with the controller. Freeze only the
// fields this evidence permits, before handing the task to either transport.
func freezeRunnerCreationTask(t agent.Task) agent.Task {
	if t.Kind != agent.TaskCreateRunner || t.Spec == nil {
		return agent.Task{}
	}
	spec := t.Spec
	return agent.Task{ID: t.ID, Kind: t.Kind, RunnerID: t.RunnerID, PoolID: t.PoolID, Backend: t.Backend, IssuedAt: t.IssuedAt, Spec: &backend.Spec{RunnerID: spec.RunnerID, PoolID: spec.PoolID, Image: spec.Image, Resources: store.Resources{CPUs: spec.Resources.CPUs, MemoryMB: spec.Resources.MemoryMB}, ResourcesSource: spec.ResourcesSource, DockerMode: spec.DockerMode, CPUTyped: spec.CPUTyped, MemoryTyped: spec.MemoryTyped}}
}

// Evidence collection must not trap a live runner or block cleanup. Missing
// observations remain missing; no fallback to current configuration is allowed.
// Lifecycle writes retain their existing error/lease retry behaviour.
func (c *Controller) recordRunnerCreationResult(ctx context.Context, host string, r *store.Runner, res agent.TaskResult) {
	if !res.OK || res.NotStarted || r.HostID != host {
		return
	}
	task, known := c.queues.get(host).creationTaskSnapshot(res.TaskID)
	if !known || task.RunnerID != r.ID || task.PoolID != r.PoolID {
		return
	}
	data, err := buildRunnerCreationObservation(host, task, res)
	if err != nil {
		c.log.Warn("runner creation observation unavailable", "runner", r.ID, "task", res.TaskID, "reason", "invalid_projection")
		return
	}
	if data == nil {
		return
	}
	// Scope is current ownership at receipt, not proof of installation ownership
	// at issue. Store checks it again atomically with the first observation write.
	pool, err := c.st.GetPool(ctx, r.PoolID)
	if err != nil || pool.InstallationID == "" {
		c.log.Warn("runner creation observation unavailable", "runner", r.ID, "task", res.TaskID, "reason", "scope_unavailable")
		return
	}
	if _, err := c.st.PutRunnerCreationObservation(ctx, pool.InstallationID, data); err != nil {
		reason := "storage_failure"
		switch {
		case errors.Is(err, store.ErrConflict):
			reason = "immutable_conflict"
		case errors.Is(err, store.ErrNotFound):
			reason = "expired_observation"
		case errors.Is(err, store.ErrInvalidRunnerCreationObservation):
			reason = "invalid_observation"
		}
		c.log.Warn("runner creation observation unavailable", "runner", r.ID, "task", res.TaskID, "reason", reason)
	}
}

