// Losing the lease means another controller is running against the same
// database and both are scheduling. It is the one condition this process
// cannot recover from on its own, so it says so and keeps saying so.
func TestLosingTheLeaseIsReportedAsAnErrorThatNamesTheNewHolder(t *testing.T) {
	h := newHarness(t)
	if got := h.problemCodes(); contains(got, "controller.lease_lost") {
		t.Fatalf("a controller that holds its lease reported losing it: %v", got)
	}

	h.c.leaseLost.Store(&store.ControllerLease{
		Holder: "ctl_rival", Host: "vm-b", PID: 991,
	})

	ps, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	var found *Problem
	for i, p := range ps {
		if p.Code == "controller.lease_lost" {
			found = &ps[i]
		}
	}
	if found == nil {
		t.Fatalf("problems = %v, want the lost-lease error", h.problemCodes())
	}
	if found.Severity != config.SeverityError {
		t.Errorf("severity = %q, want an error: two controllers are scheduling", found.Severity)
	}
	if !strings.Contains(found.Detail, "vm-b") || !strings.Contains(found.Detail, "991") {
		t.Errorf("detail = %q, want it to name the machine and process now holding it", found.Detail)
	}
	if !strings.Contains(found.Fix, "--takeover") {
		t.Errorf("fix = %q, want it to name the flag that resolves this", found.Fix)
	}
}

// The agent adopts what it finds running, so the controller is the only party
// that knows a runner was deleted while the agent was down. It answers with
// the ones it does not know, and the agent reaps only those.
func TestTheHeartbeatNamesOnlyTheRunnersThisControllerDoesNotKnow(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	live := h.runnerRow(pool, host, store.RunnerBusy)
	other := h.host("vm-other")
	theirs := h.runnerRow(pool, other, store.RunnerBusy)

	resp, err := h.c.Heartbeat(h.ctx, host.ID, agent.HeartbeatRequest{
		ProtocolVersion: agent.ProtocolVersion,
		Runners: []agent.RunnerReport{
			{RunnerID: live.ID, State: store.RunnerBusy},
			{RunnerID: "run_deletedwhiledown", State: store.RunnerBusy},
			{RunnerID: theirs.ID, State: store.RunnerBusy},
		},
	})
	if err != nil {
		t.Fatalf("Heartbeat: %v", err)
	}

	if len(resp.UnknownRunners) != 1 || resp.UnknownRunners[0] != "run_deletedwhiledown" {
		t.Fatalf("unknown = %v, want only the runner with no row", resp.UnknownRunners)
	}
	// A runner belonging to another host is a different fault, already logged
	// where reports are applied. Answering "unknown" would invite one host to
	// remove another's work.
	for _, id := range resp.UnknownRunners {
		if id == theirs.ID {
			t.Error("a runner owned by another host was named as unknown")
		}
	}
}

package controller

import (
	"context"
	"errors"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

// Share one registration listing per installation in this report batch.
// Failed checks leave the runner registering; the next report retries.
func (c *Controller) runnerOnline(ctx context.Context, r *store.Runner, cache map[string][]github.Runner) bool {
	pool, err := c.st.GetPool(ctx, r.PoolID)
	if err != nil || c.githubHeld(pool.InstallationID, c.Now()) {
		return false
	}
	remote, checked := cache[pool.InstallationID]
	if !checked {
		cache[pool.InstallationID] = nil
		inst, err := c.st.GetInstallation(ctx, pool.InstallationID)
		if err != nil {
			return false
		}
		client, err := c.clients.get(ctx, inst)
		if err != nil {
			return false
		}
		checkCtx, cancel := context.WithTimeout(ctx, 5*time.Second)
		defer cancel()
		remote, err = client.ListRunners(checkCtx)
		c.observeGitHub(inst.ID, err)
		if err != nil {
			if errors.Is(err, github.ErrRateLimited) {
				c.holdRateLimited(inst.ID, err, c.Now(), "confirming runner readiness")
			}
			c.log.Warn("could not confirm runner readiness with GitHub", "runner", r.ID, "error", err)
			return false
		}
		cache[pool.InstallationID] = remote
	}
	for _, gr := range remote {
		if gr.Name == r.Name && (r.GitHubRunnerID == 0 || gr.ID == r.GitHubRunnerID) && strings.EqualFold(gr.Status, "online") {
			if r.GitHubRunnerID == 0 {
				_ = c.st.SetRunnerGitHubID(ctx, r.ID, gr.ID)
			}
			return true
		}
	}
	return false
}

package controller

import (
	"math"
	"strconv"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// EnvDockerWait is the variable the runner image reads for how long to wait
// for its pool's Docker daemon, in whole seconds. The fleet's runners.docker_wait
// is rendered into it; a pool's own env may name it to say otherwise.
const EnvDockerWait = "ZOOMIES_DOCKER_WAIT"

// runnerEnv is the environment a runner of this pool starts with: the fleet's
// runners.env, then the Docker wait for a pool that provides a daemon, then
// the pool's own env over the top. The pool wins every collision, because it
// is the more specific thing an operator said, and the fleet-wide layer is
// what lets one setting on the Settings page reach every pool at once rather
// than being pasted into each.
//
// Nothing here is a credential. The runner's own identity and JIT
// configuration are written by the backend from the spec's Credentials, and
// the validator refuses a runners.env that names them.
func runnerEnv(r config.Runners, pool *store.Pool) map[string]string {
	wait := dockerWait(r, pool)
	if len(r.Env) == 0 && wait <= 0 && len(pool.Env) == 0 {
		return nil
	}
	out := make(map[string]string, len(r.Env)+len(pool.Env)+1)
	for k, v := range r.Env {
		out[k] = v
	}
	// Only a pool with a daemon needs to know how long to wait for one; the
	// image ignores the variable otherwise, but a runner's environment should
	// say what applies to it and nothing else.
	if wait > 0 && pool.DockerMode != "" && pool.DockerMode != store.DockerNone {
		// The image takes whole seconds and refuses zero, so a wait under a
		// second rounds up to one rather than down to a refusal.
		seconds := max(1, int64((wait+time.Second-1)/time.Second))
		out[EnvDockerWait] = strconv.FormatInt(seconds, 10)
	}
	for k, v := range pool.Env {
		out[k] = v
	}
	return out
}

// dockerWait is how long this pool's runners wait for their daemon: the pool's
// own override where it has one, and the fleet's figure otherwise.
//
// A pool that overrides it to zero leaves the image's own default in place,
// which is exactly what the fleet's zero means, so the two agree about what
// nothing means. The pool's `env` may still name ZOOMIES_DOCKER_WAIT directly
// and win over both -- it is layered last -- which is the escape hatch that
// existed before this setting did.
func dockerWait(r config.Runners, pool *store.Pool) time.Duration {
	if d := pool.RunnerSettings.DockerWait; d != nil {
		return d.Duration()
	}
	return r.DockerWait
}

// The variables that tell a toolchain how many CPUs to size its workers for.
// Each of these reads the container's CPU quota once, at start, and never
// again, so a job started at its guarantee has workers for its guarantee and
// no worker to use a loan that arrives a minute later.
const (
	EnvCargoBuildJobs      = "CARGO_BUILD_JOBS"
	EnvDotnetProcessors    = "DOTNET_PROCESSOR_COUNT"
	EnvJavaToolOptions     = "JAVA_TOOL_OPTIONS"
	javaActiveProcessorArg = "-XX:ActiveProcessorCount="
)

// GOMAXPROCS is deliberately not among them. Go 1.25 and later read the quota
// at start and again as it changes, so a loan reaches them without help, and
// pinning GOMAXPROCS would switch that off. Go before 1.25 ignored the quota
// and started a thread per host core -- more than any ceiling -- so it needs
// no help either.

// buildSizedCPUs is the CPU count a runner of pool p started on h tells its
// toolchains to size for: its ceiling, in whole cores, or zero when the pool
// does not ask for it. It is never below the guarantee, which a ceiling
// cannot take a runner under.
func buildSizedCPUs(p *store.Pool, h *store.Host, guarantee float64) int {
	if p == nil || h == nil || !p.Automatic() || !p.CPUBurst.SizesForCeiling() ||
		(p.Backend != store.BackendDocker && p.Backend != store.BackendPodman) {
		return 0
	}
	alloc := h.Allocatable()
	if !alloc.CPUsKnown || alloc.CPUs <= 0 {
		return 0
	}
	ceiling := max(elasticCeiling(p, h, alloc.CPUs), guarantee)
	// Floored: a worker for a fraction of a core is a worker queued behind the
	// others, and the guarantee's own rounding already gives the job one.
	n := int(math.Floor(ceiling + 1e-9))
	if n < 1 || float64(n) <= guarantee {
		// A ceiling no higher than the guarantee is what the toolchain would
		// read for itself; saying it again only hides where it came from.
		return 0
	}
	return n
}

// withBuildSizing adds the toolchain sizing for n CPUs to env, which is the
// runner's environment as runnerEnv built it. A variable the fleet or the pool
// already sets is left as it is: that is an operator's explicit choice. The
// one exception is JAVA_TOOL_OPTIONS, which carries every other JVM flag too,
// so the processor count is appended to it unless it already names one.
func withBuildSizing(env map[string]string, n int) map[string]string {
	if n <= 0 {
		return env
	}
	if env == nil {
		env = make(map[string]string, 3)
	}
	count := strconv.Itoa(n)
	for _, k := range []string{EnvCargoBuildJobs, EnvDotnetProcessors} {
		if _, set := env[k]; !set {
			env[k] = count
		}
	}
	arg := javaActiveProcessorArg + count
	switch opts, set := env[EnvJavaToolOptions]; {
	case !set || strings.TrimSpace(opts) == "":
		env[EnvJavaToolOptions] = arg
	case !strings.Contains(opts, "ActiveProcessorCount"):
		env[EnvJavaToolOptions] = strings.TrimSpace(opts) + " " + arg
	}
	return env
}

package controller

import (
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// The fleet's runner settings reach a runner through its create task, with
// the pool's own env over the top: one setting on the Settings page is what
// every pool gets, and a pool that says otherwise is believed.
func TestRunnerEnvLayersTheFleetUnderThePool(t *testing.T) {
	fleet := config.Runners{
		DockerWait: 90 * time.Second,
		Env:        map[string]string{"HTTPS_PROXY": "http://fleet-proxy:3128", "GOFLAGS": "-mod=mod"},
	}
	pool := &store.Pool{DockerMode: store.DockerDinD, Env: map[string]string{"HTTPS_PROXY": "http://pool-proxy:3128"}}

	got := runnerEnv(fleet, pool)
	if got["HTTPS_PROXY"] != "http://pool-proxy:3128" {
		t.Fatalf("the pool's proxy lost to the fleet's: %v", got)
	}
	if got["GOFLAGS"] != "-mod=mod" {
		t.Fatalf("the fleet's variable did not reach the runner: %v", got)
	}
	if got[EnvDockerWait] != "90" {
		t.Fatalf("docker wait = %q, want whole seconds", got[EnvDockerWait])
	}

	// A pool with no daemon has nothing to wait for, and a zero wait leaves
	// the image's own default rather than handing it a value it refuses.
	pool.DockerMode = store.DockerNone
	if _, set := runnerEnv(fleet, pool)[EnvDockerWait]; set {
		t.Fatal("a pool with no daemon was told how long to wait for one")
	}
	pool.DockerMode = store.DockerHostSocket
	fleet.DockerWait = 0
	if _, set := runnerEnv(fleet, pool)[EnvDockerWait]; set {
		t.Fatal("a zero wait was written, which the image refuses")
	}
	fleet.DockerWait = 300 * time.Millisecond
	if got := runnerEnv(fleet, pool)[EnvDockerWait]; got != "1" {
		t.Fatalf("a wait under a second became %q, want 1", got)
	}
	// The pool's own ZOOMIES_DOCKER_WAIT is still the last word.
	fleet.DockerWait = 2 * time.Minute
	pool.Env[EnvDockerWait] = "600"
	if got := runnerEnv(fleet, pool)[EnvDockerWait]; got != "600" {
		t.Fatalf("the pool's own wait lost to the fleet's: %q", got)
	}
	if runnerEnv(config.Runners{}, &store.Pool{}) != nil {
		t.Fatal("nothing to say became an empty map rather than none")
	}
}

// End to end: the setting changed on the Settings page is in the next create
// task's spec, so it is live in the sense the registry promises.
func TestACreateTaskCarriesTheFleetsRunnerEnvironment(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "builders")
	pool.DockerMode = store.DockerDinD
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	host := h.host("vm-1")
	h.c.UpdateConfig(func(c *config.Config) {
		c.Runners.DockerWait = 3 * time.Minute
		c.Runners.Env = map[string]string{"NO_PROXY": "localhost"}
	})

	h.deliverJob(jobEvent{Action: "queued", JobID: 11, Labels: []string{"self-hosted", "linux", "x64", "demo"}})
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	h.c.lifecycleCalls.Wait()
	task := h.taskOfKind(host.ID, agent.TaskCreateRunner)
	if task.Spec == nil {
		t.Fatal("no create task")
	}
	if task.Spec.Env[EnvDockerWait] != "180" || task.Spec.Env["NO_PROXY"] != "localhost" {
		t.Fatalf("create task env = %v", task.Spec.Env)
	}
}

// A pool that overrides the Docker wait is believed over the fleet, because a
// pool whose jobs need a daemon on a slow machine is the thing that knows how
// long that takes -- and the fleet's one figure has to serve every other pool
// at the same time.
func TestAPoolsOwnDockerWaitWinsOverTheFleets(t *testing.T) {
	fleet := config.Runners{DockerWait: 90 * time.Second}
	pool := &store.Pool{DockerMode: store.DockerDinD}
	if got := runnerEnv(fleet, pool)[EnvDockerWait]; got != "90" {
		t.Fatalf("docker wait = %q, want the fleet's 90 on a pool that overrides nothing", got)
	}

	wait := store.Duration(5 * time.Minute)
	pool.RunnerSettings.DockerWait = &wait
	if got := runnerEnv(fleet, pool)[EnvDockerWait]; got != "300" {
		t.Fatalf("docker wait = %q, want the pool's 300", got)
	}

	// Zero means the same on the pool as on the fleet: leave the image's own
	// default in place. The two must agree, or an operator clearing a pool's
	// override would get an image that refuses the value it was handed.
	zero := store.Duration(0)
	pool.RunnerSettings.DockerWait = &zero
	if _, set := runnerEnv(fleet, pool)[EnvDockerWait]; set {
		t.Fatal("a pool that overrode the wait to zero was still sent one")
	}

	// And the pool's own env is still the last word over both.
	pool.RunnerSettings.DockerWait = &wait
	pool.Env = map[string]string{EnvDockerWait: "600"}
	if got := runnerEnv(fleet, pool)[EnvDockerWait]; got != "600" {
		t.Fatalf("docker wait = %q, want the pool env's 600", got)
	}
}

package controller

import (
	"context"
	"fmt"
	"math"
	"slices"
	"strconv"

	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// A folder a pool keeps in memory has a ceiling, and a job that writes past it
// fails a step with "no space left on device". GitHub records that as an
// ordinary failure, the runner's own output never carries a step's words, and
// a compiler deletes its work directory as the link fails, so by the time the
// job is reported failed nothing says the folder was full. What survives is
// the agent's samples: the fullest each folder got is kept on the job, and
// everything here reads from that.

// scratchFullFraction is how full a folder has to have been, at some sample
// before a failed job ended, for the failure to be read as the folder's. The
// fill itself falls between samples: a cold Go build that died at the link in
// a 1 GB /tmp was measured at 94% a sample earlier, and a job that used half
// of its folder failed for its own reasons.
const scratchFullFraction = 0.9

// scratchSample is a backend's measurement of a runner's folders as the store
// keeps it, in megabytes.
func scratchSample(use []backend.ScratchUse) []store.ScratchPeak {
	out := make([]store.ScratchPeak, 0, len(use))
	for _, u := range use {
		out = append(out, store.ScratchPeak{Path: u.Path, PeakMB: u.UsedBytes >> 20, SizeMB: u.SizeBytes >> 20})
	}
	return out
}

// scratchFilled is the folder a failed job filled, if one of its folders came
// within scratchFullFraction of its ceiling, and how full it got.
func scratchFilled(job *store.Job) (store.ScratchPeak, float64, bool) {
	if job == nil || job.State != store.JobCompleted || !store.IsFailedConclusion(job.Conclusion) {
		return store.ScratchPeak{}, 0, false
	}
	peak, fraction, ok := job.ScratchPeaks.Fullest()
	if !ok || fraction < scratchFullFraction {
		return store.ScratchPeak{}, 0, false
	}
	return peak, fraction, true
}

// scratchPercent is a folder's fullness as the whole number an operator reads.
func scratchPercent(fraction float64) int {
	return int(math.Round(fraction * 100))
}

// scratchKindOf is which of a runner's folders a path in the container is.
func scratchKindOf(path string) (store.ScratchKind, bool) {
	switch path {
	case backend.RunnerWorkMount:
		return store.ScratchWork, true
	case backend.RunnerTmpMount:
		return store.ScratchTmp, true
	case backend.DaemonStoreMount:
		return store.ScratchDaemon, true
	}
	return "", false
}

// scratchName is a folder as a sentence names it: its path, and what it is
// where the path alone does not say.
func scratchName(path string) string {
	kind, ok := scratchKindOf(path)
	if !ok {
		return path
	}
	label, _, _ := scratchFolder(kind)
	return fmt.Sprintf("%s (the %s)", path, lowerFirst(label))
}

// scratchFullFix is what gives a folder room, which is the pool's choice three
// ways: a bigger runner fits a bigger folder, a typed size asks for one
// outright, and disk has no ceiling.
func scratchFullFix(pool string) string {
	return fmt.Sprintf("give the folder room: raise the pool's memory per runner, so the folder is fitted larger; type a larger size for it under the pool's in-memory folders; or keep it on disk (Placement: Auto, or zoomies pools edit %s --tmpfs-tmp=false for /tmp). A folder is charged to the runner's memory limit, so a bigger one may need a bigger limit, which the pool editor proposes.", pool)
}

// explainScratchFull adds a folder that ran out of room to a finished job's
// explanation, as explainOOM adds a kill: it is the one fact about the job
// the conclusion GitHub recorded cannot tell anybody. A kill registered after
// it still wins the summary, because a kill is the surer fact.
func explainScratchFull(job *store.Job, out *JobExplanation) {
	peak, fraction, ok := scratchFilled(job)
	if !ok {
		return
	}
	out.Summary = fmt.Sprintf("An in-memory folder on this job's runner ran out of room: %s, kept in memory at %s, was %d%% full at the last sample before the job failed.",
		scratchName(peak.Path), humanMB(peak.SizeMB), scratchPercent(fraction))
	out.Fix = scratchFullFix(job.PoolID)
}

// scratchFullProblems reports, pool by pool, the jobs whose in-memory folder
// filled in the last hour. Per pool because the fix is the pool's: the folder's
// size, or whether it is in memory at all, is a setting of the pool, and the
// jobs it fails are the ones the pool runs.
func (c *Controller) scratchFullProblems(ctx context.Context, out *[]Problem) error {
	since := c.Now().Add(-problemWindow)
	jobs, err := c.st.FailedJobsWithScratchSince(ctx, since, 100)
	if err != nil {
		return fmt.Errorf("listing jobs whose in-memory folder filled: %w", err)
	}
	byPool := map[string][]*store.Job{}
	var pools []string
	for _, j := range jobs {
		if _, _, ok := scratchFilled(j); !ok {
			continue
		}
		if byPool[j.PoolID] == nil {
			pools = append(pools, j.PoolID)
		}
		byPool[j.PoolID] = append(byPool[j.PoolID], j)
	}
	slices.Sort(pools)
	for _, poolID := range pools {
		jobs := byPool[poolID]
		example := jobs[0]
		peak, fraction, _ := scratchFilled(example)
		name := poolID
		if p, err := c.st.GetPool(ctx, poolID); err == nil {
			name = p.Name
		}
		title := fmt.Sprintf("1 job filled an in-memory folder in pool %s in the last hour", name)
		if len(jobs) > 1 {
			title = fmt.Sprintf("%d jobs filled an in-memory folder in pool %s in the last hour", len(jobs), name)
		}
		detail := fmt.Sprintf("The most recent is %s in %s: %s, kept in memory at %s, was %d%% full at the last sample before the job failed. "+
			"A job that writes past a folder's ceiling fails a step with \"no space left on device\", which GitHub records as an ordinary failure.",
			workflowText(example.JobName), workflowText(example.Repo), scratchName(peak.Path), humanMB(peak.SizeMB), scratchPercent(fraction))
		*out = append(*out, Problem{
			Code:       "jobs.scratch_full",
			Severity:   config.SeverityWarning,
			Title:      title,
			Detail:     detail,
			Fix:        scratchFullFix(name),
			TargetKind: "pool", TargetID: poolID, Since: example.CompletedAt,
		})
	}
	return nil
}

// ScratchPeakView is how full one of a job's in-memory folders got, for the
// job's page: the folder, what was written in it at most, its ceiling, and the
// one as a share of the other.
type ScratchPeakView struct {
	Kind    store.ScratchKind `json:"kind,omitempty"`
	Label   string            `json:"label,omitempty"`
	Path    string            `json:"path"`
	PeakMB  int64             `json:"peak_mb"`
	SizeMB  int64             `json:"size_mb"`
	Percent int               `json:"percent"`
}

func scratchPeakViews(peaks store.ScratchPeaks) []ScratchPeakView {
	if len(peaks) == 0 {
		return nil
	}
	out := make([]ScratchPeakView, 0, len(peaks))
	for _, p := range peaks {
		v := ScratchPeakView{Path: p.Path, PeakMB: p.PeakMB, SizeMB: p.SizeMB, Percent: scratchPercent(p.Fraction())}
		if kind, ok := scratchKindOf(p.Path); ok {
			v.Kind = kind
			v.Label, _, _ = scratchFolder(kind)
		}
		out = append(out, v)
	}
	return out
}

// scratchEvidence is the fullest folder as facts a person can check.
func scratchEvidence(peak store.ScratchPeak, fraction float64) []Evidence {
	return []Evidence{
		{Kind: "scratch_peak", Label: scratchName(peak.Path) + " in memory, at its fullest", Value: strconv.Itoa(scratchPercent(fraction)), Unit: "%"},
		{Kind: "scratch_size", Label: scratchName(peak.Path) + " ceiling", Value: strconv.FormatInt(peak.SizeMB, 10), Unit: "MB"},
	}
}

// scratchFilledFor is scratchFilled as the class table asks it.
func scratchFilledFor(job *store.Job) bool {
	_, _, ok := scratchFilled(job)
	return ok
}

package controller

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
)

// The failure this was built for, end to end: a pool keeps /tmp in memory at
// 1 GB, a cold Go build fills it, the link fails with "no space left on
// device" and the runner exits cleanly after a failed job. GitHub records an
// ordinary failure, the runner's own output never carried the step's words,
// and the folder is empty again by the time anybody looks. The samples the
// agent took while the job ran have to be enough: the job comes out of it with
// the fullest each folder got, explained as a folder that ran out of room, and
// listed as a problem on its pool, because the pool's setting is the fix.
func TestAJobWhoseInMemoryFolderFilledIsRecordedExplainedAndReported(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.seedRunner(t, pool, host, store.RunnerBusy)
	started := h.c.Now().Add(-10 * time.Minute)
	job, err := h.st.UpsertJob(h.ctx, &store.Job{
		GitHubJobID: 5151, Repo: "eyupio/zoomies", Workflow: "CI", JobName: "Publish dev binaries",
		Labels: pool.Labels, State: store.JobInProgress, PoolID: pool.ID, Matched: true,
		RunnerID: r.ID, RunnerName: r.Name, QueuedAt: started, StartedAt: &started, HostID: host.ID,
		HTMLURL: "https://github.com/eyupio/zoomies/actions/runs/1/job/2",
	})
	if err != nil {
		t.Fatalf("UpsertJob: %v", err)
	}
	at := h.c.Now()
	for _, s := range []backend.Stats{
		{SampledAt: &at, MemoryBytes: 900 << 20, Scratch: []backend.ScratchUse{
			{Path: backend.RunnerWorkMount, UsedBytes: 300 << 20, SizeBytes: 4096 << 20},
			{Path: backend.RunnerTmpMount, UsedBytes: 400 << 20, SizeBytes: 1024 << 20}}},
		{SampledAt: &at, MemoryBytes: 1800 << 20, Scratch: []backend.ScratchUse{
			{Path: backend.RunnerWorkMount, UsedBytes: 310 << 20, SizeBytes: 4096 << 20},
			{Path: backend.RunnerTmpMount, UsedBytes: 980 << 20, SizeBytes: 1024 << 20}}},
		{SampledAt: &at, MemoryBytes: 600 << 20, Scratch: []backend.ScratchUse{
			{Path: backend.RunnerWorkMount, UsedBytes: 310 << 20, SizeBytes: 4096 << 20},
			{Path: backend.RunnerTmpMount, UsedBytes: 12 << 20, SizeBytes: 1024 << 20}}},
	} {
		if err := h.c.ReportRunners(h.ctx, host.ID, []agent.RunnerReport{{RunnerID: r.ID, Stats: s}}); err != nil {
			t.Fatalf("ReportRunners: %v", err)
		}
	}
	done := h.c.Now()
	if _, err := h.st.UpsertJob(h.ctx, &store.Job{GitHubJobID: 5151, State: store.JobCompleted, Conclusion: "failure",
		Repo: job.Repo, StartedAt: &started, CompletedAt: &done}); err != nil {
		t.Fatalf("completing the job: %v", err)
	}
	if err := h.c.ReportRunners(h.ctx, host.ID, []agent.RunnerReport{{
		RunnerID: r.ID, State: store.RunnerRemoved, Message: "ephemeral runner exited cleanly after its job",
	}}); err != nil {
		t.Fatalf("ReportRunners: %v", err)
	}

	got, err := h.st.GetJob(h.ctx, job.ID)
	if err != nil {
		t.Fatal(err)
	}
	fullest, fraction, ok := got.ScratchPeaks.Fullest()
	if !ok || fullest.Path != backend.RunnerTmpMount || fullest.PeakMB != 980 || fullest.SizeMB != 1024 || fraction < 0.95 {
		t.Fatalf("scratch peaks = %+v, want /tmp at 980 of 1024 MB as the fullest", got.ScratchPeaks)
	}

	why, err := h.c.ExplainJob(h.ctx, job.ID, 0)
	if err != nil {
		t.Fatal(err)
	}
	if why.Class != WhyScratchFull || why.ProblemCode != "jobs.scratch_full" || why.Confidence != WhyMedium {
		t.Fatalf("class %s (%s) code %q, want scratch-full at medium confidence with jobs.scratch_full", why.Class, why.Confidence, why.ProblemCode)
	}
	if !strings.Contains(why.Summary, "/tmp") || !strings.Contains(why.Summary, "1 GB") || !strings.Contains(why.Summary, "96%") {
		t.Fatalf("summary = %q, want the folder, its size and how full it got", why.Summary)
	}
	if !strings.Contains(why.Fix, "room") {
		t.Fatalf("fix = %q, want what gives the folder room", why.Fix)
	}
	if e := findEvidence(why.Evidence, "scratch_peak"); e.Value != "96" || e.Unit != "%" || !strings.Contains(e.Label, "/tmp") {
		t.Fatalf("evidence = %+v, want the fullest folder as a percentage", why.Evidence)
	}
	if len(why.NextSteps) == 0 || why.NextSteps[0].Kind != "change" || why.NextSteps[0].Link != "/pools/"+pool.ID {
		t.Fatalf("next_steps = %+v, want a change on the pool first", why.NextSteps)
	}

	problems, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	var found *Problem
	for i := range problems {
		if problems[i].Code == "jobs.scratch_full" {
			found = &problems[i]
		}
	}
	if found == nil || found.TargetKind != "pool" || found.TargetID != pool.ID || !strings.Contains(found.Detail, "/tmp") {
		t.Fatalf("problems = %+v, want jobs.scratch_full on the pool naming /tmp", problems)
	}
}

// A folder that merely had traffic is not a folder that filled. The threshold
// is nine tenths: a cold Go build that failed at the link was measured at 94%
// a sample before, and a job that used half of its folder failed for its own
// reasons.
func TestAFolderUsedButNotFilledLeavesTheWorkflowsFailureAlone(t *testing.T) {
	now := time.Date(2026, 10, 11, 12, 0, 0, 0, time.UTC)
	started, done := now.Add(-10*time.Minute), now.Add(-time.Minute)
	job := &store.Job{ID: "job_1", State: store.JobCompleted, Conclusion: "failure", QueuedAt: now.Add(-12 * time.Minute), StartedAt: &started, CompletedAt: &done, PoolID: "pool_1",
		ScratchPeaks: store.ScratchPeaks{{Path: backend.RunnerTmpMount, PeakMB: 512, SizeMB: 1024}}}
	if v := classify(whySnapshot{Job: job, Now: now}); v.Class != WhyWorkflowFailure || v.ProblemCode != "" {
		t.Fatalf("class %s code %q, want the workflow's own failure", v.Class, v.ProblemCode)
	}
	job.ScratchPeaks[0].PeakMB = 930
	if v := classify(whySnapshot{Job: job, Now: now}); v.Class != WhyScratchFull {
		t.Fatalf("class %s, want scratch-full at nine tenths", v.Class)
	}
	// A success with a full folder is a job that fitted, just: nothing to say.
	job.Conclusion = "success"
	if v := classify(whySnapshot{Job: job, Now: now}); v.Class != WhySucceeded {
		t.Fatalf("class %s, want succeeded", v.Class)
	}
}

package controller

import (
	"context"
	"encoding/json"
	"fmt"
	"slices"
	"time"

	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/naming"
	"github.com/eyupio/zoomies/internal/store"
)

// A folder that fills is only ever seen by a sample, so a host whose agent
// cannot measure its runners' folders is a host where full-folder detection is
// off, and off silently: no jobs.scratch_full ever appears, which reads as
// folders that never fill. An agent says why it could not measure with every
// sample (backend.Stats.ScratchUnmeasured), and everything here turns that
// into a sentence on the host.

const (
	// scratchUnmeasuredAfter is how old a runner has to be before its folders
	// being unmeasured counts. The first samples arrive within a minute, and a
	// host judged on a runner's first would flap with every create.
	scratchUnmeasuredAfter = 2 * time.Minute
	// scratchSampleFresh is how recent a runner's sample has to be to be
	// evidence. The agent reports its last reading again when sampling fails,
	// with the time it was taken, and a reading from an hour ago says nothing
	// about whether the folders can be measured now; the host's other entries
	// say that its samples have stopped.
	scratchSampleFresh = 10 * time.Minute
)

// scratchUnmeasuredProblems names each host that cannot measure the in-memory
// folders of its runners.
func (c *Controller) scratchUnmeasuredProblems(ctx context.Context, out *[]Problem) error {
	hosts, err := c.fleetHosts(ctx)
	if err != nil {
		return fmt.Errorf("listing hosts: %w", err)
	}
	now := c.Now()
	for _, h := range hosts {
		// A host already excluded from placement, or being dealt with, has its
		// own entries; this one would only repeat them.
		if h.Incompatible || h.Cordoned {
			continue
		}
		runners, err := c.fleetRunnersUpOn(ctx, h.ID)
		if err != nil {
			return fmt.Errorf("listing the runners on %s: %w", naming.ForSentence(h.Name), err)
		}
		reason, ok := hostScratchUnmeasured(runners, now)
		if !ok {
			continue
		}
		name := naming.ForSentence(h.Name)
		detail, fix := scratchUnmeasuredWhy(reason, name)
		*out = append(*out, Problem{
			Code:       "host.scratch_unmeasured",
			Severity:   config.SeverityInfo,
			Title:      name + " cannot tell how full its in-memory folders get",
			Detail:     detail,
			Fix:        fix,
			TargetKind: "host",
			TargetID:   h.ID,
		})
	}
	return nil
}

// hostScratchUnmeasured is why a host cannot measure its runners' folders, if
// it cannot. It cannot when it has runners that keep folders in memory, at
// least one has said why its folders were not measured, and none has had a
// folder measured: one that has proves the host can, and the others are that
// runner's own matter. A runner that keeps nothing in memory, one too young to
// have been sampled, one with no recent sample, and an agent that predates the
// measurement and says nothing either way are not evidence, so none of them
// counts for or against.
func hostScratchUnmeasured(runners []*store.Runner, now time.Time) (string, bool) {
	measured := false
	reasons := map[string]int{}
	for _, r := range runners {
		if r.Scratch.InMemory() == 0 || r.Age(now) < scratchUnmeasuredAfter {
			continue
		}
		var sample backend.Stats
		if len(r.ResourceSample) == 0 || json.Unmarshal(r.ResourceSample, &sample) != nil ||
			sample.SampledAt == nil || now.Sub(*sample.SampledAt) > scratchSampleFresh {
			continue
		}
		switch {
		case len(sample.Scratch) > 0:
			measured = true
		case sample.ScratchUnmeasured != "":
			reasons[sample.ScratchUnmeasured]++
		}
	}
	if measured || len(reasons) == 0 {
		return "", false
	}
	// The commonest reason is the one to fix first; a tie goes to the reason
	// that sorts first, so the sentence does not change between two reads of
	// the same fleet.
	var codes []string
	for code := range reasons {
		codes = append(codes, code)
	}
	slices.SortFunc(codes, func(a, b string) int {
		if reasons[a] != reasons[b] {
			return reasons[b] - reasons[a]
		}
		if a < b {
			return -1
		}
		return 1
	})
	return codes[0], true
}

// scratchUnmeasuredWhy is what happened and what to change for one of the
// reasons an agent gives. All four end the same way for a job: it fails as it
// would have, and nothing says the folder was why.
func scratchUnmeasuredWhy(reason, host string) (detail, fix string) {
	const consequence = " A job that fills one of those folders still fails with \"no space left on device\", but Zoomies cannot then say the folder was the cause, so jobs.scratch_full and the job's explanation stay silent."
	switch reason {
	case backend.ScratchExecRefused:
		return "The container engine on " + host + " refused to run a command in a runner. Zoomies measures an in-memory folder by running df in the runner's container, so it cannot see how full any of them get." + consequence,
			"allow exec through whatever answers for the engine's socket: a socket proxy that blocks the exec endpoint, or an authorisation plugin. The next sample clears this."
	case backend.ScratchNoDF:
		return "The runner image on " + host + " has no df command. Zoomies measures an in-memory folder by running df in the runner's container, so it cannot see how full any of them get." + consequence,
			"use an image that has df, which any with coreutils or busybox does and the stock runner image does. The next runner created from it clears this."
	case backend.ScratchTimedOut:
		return "The container engine on " + host + " did not answer, in time, a request to measure a runner's in-memory folders, on any runner it has. Zoomies cannot see how full any of them get." + consequence,
			"an engine that cannot answer a one-line command is overloaded or stalled; the host's other entries say how. This clears on its own once it answers."
	default:
		return "Zoomies ran df in a runner on " + host + " and could not read what it printed, so it cannot see how full the runner's in-memory folders get." + consequence,
			"on the host, run `docker exec <runner container> df -P -k /tmp` (or `podman exec`). Zoomies reads the table it prints, a row per folder with the mount point last; if the output is anything else, that image's df differs from the usual one."
	}
}

package controller

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
)

// keepsTmpInMemory records that a runner was given its /tmp in memory, as the
// controller does when it builds the create task.
func (h *harness) keepsTmpInMemory(t *testing.T, r *store.Runner) {
	t.Helper()
	scratch := store.RunnerScratch{Folders: []store.ScratchFolder{{Kind: store.ScratchTmp, AskedMB: 1024, SizeMB: 1024}}}
	if err := h.st.SetRunnerScratch(h.ctx, r.ID, scratch); err != nil {
		t.Fatalf("SetRunnerScratch: %v", err)
	}
}

// sampleOf reports one sample for a runner, taken ago before now.
func (h *harness) sampleOf(t *testing.T, host *store.Host, r *store.Runner, ago time.Duration, s backend.Stats) {
	t.Helper()
	at := h.c.Now().Add(-ago)
	s.SampledAt = &at
	if s.MemoryBytes == 0 {
		s.MemoryBytes = 512 << 20
	}
	if err := h.c.ReportRunners(h.ctx, host.ID, []agent.RunnerReport{{RunnerID: r.ID, Stats: s}}); err != nil {
		t.Fatalf("ReportRunners: %v", err)
	}
}

func problemFor(problems []Problem, code, targetID string) *Problem {
	for i := range problems {
		if problems[i].Code == code && problems[i].TargetID == targetID {
			return &problems[i]
		}
	}
	return nil
}

// A folder that fills is only ever seen by a sample, so a host that cannot
// measure its folders is a host where the whole of full-folder detection is
// off, and it is off silently: no jobs.scratch_full ever appears, which reads
// as folders that never fill. The host says so, with the reason its agent gave,
// once its runners have had time to be sampled.
func TestAHostThatCannotMeasureItsFoldersSaysWhyOnceItHasHadTimeToSample(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.seedRunner(t, pool, host, store.RunnerIdle)
	h.keepsTmpInMemory(t, r)

	// A runner a few seconds old has not been sampled long enough to say.
	h.sampleOf(t, host, r, 0, backend.Stats{ScratchUnmeasured: backend.ScratchExecRefused})
	problems, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	if p := problemFor(problems, "host.scratch_unmeasured", host.ID); p != nil {
		t.Fatalf("flagged a runner seconds old: %+v", p)
	}

	h.advance(3 * time.Minute)
	h.sampleOf(t, host, r, 0, backend.Stats{ScratchUnmeasured: backend.ScratchExecRefused})
	problems, err = h.c.Problems(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	p := problemFor(problems, "host.scratch_unmeasured", host.ID)
	if p == nil {
		t.Fatalf("problems = %+v, want host.scratch_unmeasured on the host", problems)
	}
	if p.TargetKind != "host" || p.Severity != "info" || p.Audience != AudienceFleet {
		t.Fatalf("problem = %+v, want an info entry on the host for the fleet", p)
	}
	for _, want := range []string{host.Name, "refused", "exec"} {
		if !strings.Contains(p.Title+" "+p.Detail+" "+p.Fix, want) {
			t.Fatalf("problem %+v does not mention %q", p, want)
		}
	}
}

// Each reason is a different change, so each is told differently, and none of
// the sentences blames the operator for a setting they were never given.
func TestEachReasonAHostCannotMeasureItsFoldersHasItsOwnAdvice(t *testing.T) {
	seen := map[string]string{}
	for reason, wantInFix := range map[string]string{
		backend.ScratchExecRefused: "exec",
		backend.ScratchNoDF:        "df",
		backend.ScratchUnreadable:  "df -P -k",
		backend.ScratchTimedOut:    "overloaded",
	} {
		detail, fix := scratchUnmeasuredWhy(reason, "vm-1")
		if !strings.Contains(fix, wantInFix) || !strings.Contains(detail, "vm-1") {
			t.Fatalf("%s: detail %q fix %q, want the host named and %q in the fix", reason, detail, fix, wantInFix)
		}
		if strings.Contains(detail+fix, "\u2014") {
			t.Fatalf("%s: an em dash in %q %q", reason, detail, fix)
		}
		if other, dup := seen[fix]; dup {
			t.Fatalf("%s and %s give the same advice: %q", reason, other, fix)
		}
		seen[fix] = reason
	}
}

// One runner that can be measured is proof the host can, and the others are
// then a runner's own matter: an image without df, say. Only a host where none
// of its runners can be measured has lost detection.
func TestAHostThatMeasuresAnyRunnerIsNotFlagged(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	blind := h.seedRunner(t, pool, host, store.RunnerIdle)
	seeing := h.seedRunner(t, pool, host, store.RunnerIdle)
	h.keepsTmpInMemory(t, blind)
	h.keepsTmpInMemory(t, seeing)
	h.advance(3 * time.Minute)
	h.sampleOf(t, host, blind, 0, backend.Stats{ScratchUnmeasured: backend.ScratchNoDF})
	h.sampleOf(t, host, seeing, 0, backend.Stats{Scratch: []backend.ScratchUse{{Path: backend.RunnerTmpMount, UsedBytes: 1 << 20, SizeBytes: 1024 << 20}}})

	problems, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	if p := problemFor(problems, "host.scratch_unmeasured", host.ID); p != nil {
		t.Fatalf("flagged a host that measures one of its runners: %+v", p)
	}
}

// A runner whose pool keeps nothing in memory has nothing to measure, and an
// agent that predates the measurement says nothing either way: neither is a
// host that cannot measure.
func TestOnlyFoldersInMemoryAndAnAgentThatSaysWhyCountAsUnmeasured(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	onDisk := h.seedRunner(t, pool, host, store.RunnerIdle)
	oldAgent := h.seedRunner(t, pool, host, store.RunnerIdle)
	h.keepsTmpInMemory(t, oldAgent)
	h.advance(3 * time.Minute)
	h.sampleOf(t, host, onDisk, 0, backend.Stats{ScratchUnmeasured: backend.ScratchNoDF})
	h.sampleOf(t, host, oldAgent, 0, backend.Stats{})

	problems, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	if p := problemFor(problems, "host.scratch_unmeasured", host.ID); p != nil {
		t.Fatalf("flagged a host with no evidence either way: %+v", p)
	}
}

// A sample the agent has not refreshed in a long while is an agent that is
// failing to sample, which other entries say. It is no evidence about folders.
func TestAStaleSampleSaysNothingAboutWhetherFoldersCanBeMeasured(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.seedRunner(t, pool, host, store.RunnerIdle)
	h.keepsTmpInMemory(t, r)
	h.advance(time.Hour)
	h.sampleOf(t, host, r, 30*time.Minute, backend.Stats{ScratchUnmeasured: backend.ScratchExecRefused})

	problems, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	if p := problemFor(problems, "host.scratch_unmeasured", host.ID); p != nil {
		t.Fatalf("flagged on a half-hour-old sample: %+v", p)
	}
}

package controller

import (
	"context"
	"fmt"
	"slices"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// The demo is where a person first meets the four analyses, so each one is
// given a cause to find: a pool whose runners are slow to register, a pool
// held at its ceiling, a host whose failures came while it was overwhelmed,
// and a host that cannot pull the runner image. They are placed in one window
// a day back, from demoAnalysisFrom to demoAnalysisTo ago, outside the six
// hours the rest of the seed's jobs and runners cover, so that morning reads
// as it always has and an analysis asked about the window reads only what was
// put there for it. Host samples are the exception: seedHostSamples draws a
// whole day of them, and one host's are rewritten in the window.
//
// Every number below is chosen against what the controller reads for each
// analysis (internal/controller/analysis.go), not against what an analysis
// might be imagined to read: a fixture that only looked right would let the
// demo name the wrong cause, or the right one with a hedge.
//
// The jobs here carry no release. The demo's release comparison is meant to
// say its sample is too small to rank (decision 7), and stamping these would
// tip one side past the line.
const demoAnalysisFrom, demoAnalysisTo = 22 * time.Hour, 20 * time.Hour

// Where the fixture's GitHub numbers start: past every job and run the rest
// of the seed writes, and run numbers under the morning's 300, because these
// runs came first.
const (
	demoAnalysisGitHubJob = 82000
	demoAnalysisGitHubRun = 42000
	demoAnalysisRunNumber = 280
	// The runner names' index, past the dozen seedRunners names.
	demoAnalysisRunnerIndex = 20
)

// seedAnalyses writes the analysis fixture. It runs after seedHostSamples,
// because one host's samples in the window are rewritten here.
func (c *Controller) seedAnalyses(ctx context.Context, now time.Time, linux, arm *store.Pool, hosts []*store.Host) error {
	byID := hostsByID(hosts)
	a, b, arm64 := byID[demoHostPrefix+"a"], byID[demoHostPrefix+"b"], byID[demoHostPrefix+"c"]
	if a == nil || b == nil || arm64 == nil {
		return fmt.Errorf("seeding the analysis fixture: the demo hosts %sa, %sb and %sc are not all there", demoHostPrefix, demoHostPrefix, demoHostPrefix)
	}
	s := &analysisSeed{c: c, from: now.Add(-demoAnalysisFrom), to: now.Add(-demoAnalysisTo)}
	if err := s.slowStarts(ctx, linux, a); err != nil {
		return err
	}
	if err := s.poolCeiling(ctx, arm, arm64); err != nil {
		return err
	}
	if err := s.hostPressure(ctx, now, linux, b); err != nil {
		return err
	}
	return s.imageFailures(ctx, linux, b)
}

// analysisSeed is the window and the numbering the fixture's four parts
// share, so no two of them can hand out the same run or runner name.
type analysisSeed struct {
	c        *Controller
	from, to time.Time
	jobs     int
	runs     int
	runners  int
}

// run starts a new workflow run and returns its number in the fixture.
func (s *analysisSeed) run() int {
	s.runs++
	return s.runs - 1
}

// job is one of the fixture's jobs, claimed by pool the moment it was queued:
// eligible a second later, as a webhook claims one, and stamped so rather
// than left to the store, which would stamp it now.
func (s *analysisSeed) job(id string, pool *store.Pool, repo, workflow, name string, run int, queued time.Time) *store.Job {
	n := s.jobs
	s.jobs++
	eligible := queued.Add(time.Second)
	return &store.Job{
		ID:             id,
		GitHubJobID:    int64(demoAnalysisGitHubJob + n),
		GitHubRunID:    int64(demoAnalysisGitHubRun + run),
		RunNumber:      int64(demoAnalysisRunNumber + run),
		Repo:           repo,
		Workflow:       workflow,
		JobName:        name,
		Labels:         pool.Labels,
		InstallationID: pool.InstallationID,
		PoolID:         pool.ID,
		Matched:        true,
		QueuedAt:       queued,
		EligibleAt:     &eligible,
		HTMLURL:        fmt.Sprintf("https://github.com/%s/actions/runs/%d", repo, demoAnalysisGitHubRun+run),
		HeadBranch:     "main",
		HeadSHA:        fmt.Sprintf("%040x", 0xFACADE+run*7919),
		RunAttempt:     1,
	}
}

// finish completes a job with its steps, and writes it with its timeline.
func (s *analysisSeed) finish(ctx context.Context, j *store.Job, conclusion string, started, completed time.Time) error {
	j.State, j.Conclusion = store.JobCompleted, conclusion
	j.StartedAt, j.CompletedAt = &started, &completed
	j.Steps = demoSteps(j.JobName, conclusion, started, completed)
	saved, change, err := s.c.st.ApplyJob(ctx, j)
	if err != nil {
		return fmt.Errorf("seeding the analysis job %s: %w", j.ID, err)
	}
	return s.c.seedJobTimeline(ctx, saved, change)
}

// runner is a runner of pool on host, asked for at requested. How it came
// up and how it ended are the caller's.
func (s *analysisSeed) runner(id string, pool *store.Pool, host *store.Host, requested time.Time) *store.Runner {
	n := demoAnalysisRunnerIndex + s.runners
	s.runners++
	return &store.Runner{
		ID:                 id,
		PoolID:             pool.ID,
		HostID:             host.ID,
		Name:               demoRunnerName(pool, n),
		State:              store.RunnerRemoved,
		Ephemeral:          pool.Ephemeral,
		Labels:             pool.Labels,
		Image:              s.c.RunnerImage(pool),
		AllocatedCPUs:      pool.Resources.CPUs,
		AllocatedMemoryMB:  pool.Resources.MemoryMB,
		AllocationSource:   store.AllocationFromPool,
		ContainerID:        fmt.Sprintf("demo%032d", n),
		GitHubRunnerID:     int64(9000 + n),
		CreateTaskIssuedAt: &requested,
	}
}

// cameUp is a runner whose container started and which registered.
func cameUp(r *store.Runner, containerStarted, registered time.Time) {
	r.StartedAt, r.ContainerStartedAt, r.RegisteredAt = &containerStarted, &containerStarted, &registered
}

// ended is a runner that finished at, cleaned up on its host and on GitHub a
// few seconds later, as a finished runner is: a row left half cleaned would
// be something the reconcile loop went back to, and a problem the demo does
// not have.
func ended(r *store.Runner, at time.Time) {
	registrationDeleted, hostRemoved, cleaned := at.Add(time.Second), at.Add(2*time.Second), at.Add(3*time.Second)
	r.FinishedAt, r.RegistrationDeletedAt, r.HostRemovedAt, r.CleanedUpAt = &at, &registrationDeleted, &hostRemoved, &cleaned
}

// saveRunner writes a runner and moves its creation to when it was asked
// for. The store stamps creation itself, and the analyses read a runner by
// it: one created at seeding would be a runner of today, not of the window.
func (s *analysisSeed) saveRunner(ctx context.Context, r *store.Runner) error {
	if err := s.c.st.CreateRunner(ctx, r); err != nil {
		return fmt.Errorf("seeding the analysis runner %s: %w", r.ID, err)
	}
	if err := s.c.st.SetRunnerCreatedAt(ctx, r.ID, *r.CreateTaskIssuedAt); err != nil {
		return fmt.Errorf("dating the analysis runner %s: %w", r.ID, err)
	}
	return nil
}

// slowStarts is the queue-wait fixture's runner startup: twelve jobs on the
// linux pool, each given a runner of its own on the first builder that takes
// four minutes to register, most of it pulling the image. Startup is carved
// out of a wait from the runner's request to its registration, so with the
// request a second after the job became eligible and the job taken eight
// seconds after registration, each wait is about 96% startup, and twelve is
// past the ten jobs the analysis needs before it calls one cause dominant.
// Nine minutes apart, no two of them are alive at once, so the pool never
// comes near its ceiling of eight and its waits are not the ceiling's.
func (s *analysisSeed) slowStarts(ctx context.Context, linux *store.Pool, host *store.Host) error {
	names := []string{"build", "test"}
	run := 0
	for i := range 12 {
		if i%2 == 0 {
			run = s.run()
		}
		queued := s.from.Add(5*time.Minute + time.Duration(i)*9*time.Minute)
		requested := queued.Add(2 * time.Second)
		registered := requested.Add(4 * time.Minute)
		started := registered.Add(8 * time.Second)
		completed := started.Add(150*time.Second + time.Duration(i%4)*40*time.Second)

		r := s.runner(fmt.Sprintf("run_demowait%02d", i+1), linux, host, requested)
		pull := 3*time.Minute + 30*time.Second
		r.ImagePullDuration = &pull
		cameUp(r, requested.Add(pull+5*time.Second), registered)
		ended(r, completed.Add(4*time.Second))
		r.Message, r.JobsHandled = "ephemeral runner exited cleanly after its job", 1
		if err := s.saveRunner(ctx, r); err != nil {
			return err
		}

		j := s.job(fmt.Sprintf("job_demowait%02d", i+1), linux, demoRepos[0], "CI", names[i%2], run, queued)
		j.RunnerID, j.RunnerName, j.HostID = r.ID, r.Name, host.ID
		if err := s.finish(ctx, j, "success", started, completed); err != nil {
			return err
		}
	}
	return nil
}

// poolCeiling is the queue-wait fixture's ceiling: the arm pool's four
// runners, its max_runners, taken from before the window to after it by a
// nightly run's four long shards, while twelve release jobs queue behind
// them. The pool keeps its runners, so they hold their places whether busy or
// idle; the shards are what make them busy, so the waiting jobs have nowhere
// to go. The twelve start only after the window, so every second of their
// waits inside it is the ceiling's, and none of them is a job that ran on a
// kept runner inside it, which the analysis could not split and would hedge
// on.
func (s *analysisSeed) poolCeiling(ctx context.Context, arm *store.Pool, host *store.Host) error {
	const holders = 4
	nightly := s.run()
	queued := s.from.Add(-31 * time.Minute)
	shardEnds := make([]time.Time, holders)
	runners := make([]*store.Runner, holders)
	for k := range holders {
		requested := s.from.Add(-30*time.Minute + time.Duration(k)*20*time.Second)
		registered := requested.Add(50 * time.Second)
		r := s.runner(fmt.Sprintf("run_demohold%d", k+1), arm, host, requested)
		cameUp(r, requested.Add(25*time.Second), registered)
		runners[k] = r
		shardEnds[k] = s.to.Add(10*time.Minute + time.Duration(k)*20*time.Second)

		j := s.job(fmt.Sprintf("job_demohold%d", k+1), arm, demoRepos[2], "Nightly", fmt.Sprintf("e2e-%d", k+1), nightly, queued)
		j.RunnerID, j.RunnerName, j.HostID = r.ID, r.Name, host.ID
		if err := s.finish(ctx, j, "success", registered.Add(5*time.Second), shardEnds[k]); err != nil {
			return err
		}
	}

	// Each runner takes three of the queued jobs once its shard is done, one
	// after the other, then idles out past the pool's ten-minute timeout.
	lastDone := slices.Clone(shardEnds)
	names := []string{"build", "test", "package"}
	run := 0
	for i := range 12 {
		if i%3 == 0 {
			run = s.run()
		}
		k, batch := i%holders, i/holders
		started := shardEnds[k].Add(15*time.Second + time.Duration(batch)*12*time.Minute)
		completed := started.Add(9*time.Minute + time.Duration(i)*5*time.Second)
		lastDone[k] = completed

		j := s.job(fmt.Sprintf("job_democeil%02d", i+1), arm, demoRepos[2], "Release", names[i%3], run,
			s.from.Add(10*time.Minute+time.Duration(i)*5*time.Minute))
		r := runners[k]
		j.RunnerID, j.RunnerName, j.HostID = r.ID, r.Name, host.ID
		if err := s.finish(ctx, j, "success", started, completed); err != nil {
			return err
		}
	}

	for k, r := range runners {
		ended(r, lastDone[k].Add(11*time.Minute))
		r.Message, r.JobsHandled = "idle for 11m, over the 10m idle timeout", 4
		if err := s.saveRunner(ctx, r); err != nil {
			return err
		}
	}
	return nil
}

// hostPressure is the host-pressure fixture: the second builder's two hours
// of samples rewritten, the first twenty minutes at a load of 20 on its 8
// cores and the rest at 4, against the throttle's line of 2 a core, with six
// failed jobs completing in the busy minutes and one in a calm one. Six of
// the seven in a sixth of the minutes is a cluster by any reading, and seven
// is past the five the analysis needs to be sure of one.
//
// The rewrite overwrites the day's curve that seedHostSamples drew there,
// and leaves CPU and memory unmeasured on purpose: the curve's figures follow
// the local hour, so whichever line they drew could depend on when the demo
// was seeded, and load is the measure the throttle itself reads (P19).
//
// The jobs have no runner rows, so they bring no startups to judge, and the
// host's only starts in the window are the image fixture's. Each was queued
// as it started, so the queue-wait analysis of their pool reads them as jobs
// that did not wait, and neither counts them nor hedges on them (P17).
//
// No throttle is seeded on the host, though a real fleet with throttling on
// would have stepped it down at this load. A throttle episode in the window
// is evidence the startup and queue-wait analyses also read, so seeding one
// would change what each of them names here; no finding over this window
// claims the host was throttled, so leaving it out misleads nobody.
func (s *analysisSeed) hostPressure(ctx context.Context, now time.Time, linux *store.Pool, host *store.Host) error {
	const minutes, busy = 120, 20
	first := s.from.Truncate(time.Minute)
	alloc := host.Allocatable()
	samples := make([]store.HostSample, 0, minutes)
	for m := range minutes {
		at := first.Add(time.Duration(m) * time.Minute)
		load, active := 4.0, 1
		if m < busy {
			load, active = 20.0, host.Capacity
		}
		reservedCPUs, reservedMem := float64(active)*2, int64(active)*4096
		samples = append(samples, store.HostSample{
			HostID:              host.ID,
			At:                  at,
			Capacity:            host.Capacity,
			ActiveRunners:       active,
			LoadAverage1:        &load,
			CPUs:                int64(host.CPUs),
			MemoryMB:            host.MemoryMB,
			AllocatableCPUs:     alloc.CPUs,
			AllocatableMemoryMB: alloc.MemoryMB,
			ReservedCPUs:        &reservedCPUs,
			ReservedMemoryMB:    &reservedMem,
			DiskTotalMB:         host.DiskTotalMB,
			// The disk line seedHostSamples draws, so the rewrite does not
			// step it.
			DiskFreeMB: host.DiskFreeMB + int64(now.Truncate(time.Minute).Sub(at)/time.Minute)*8,
		})
	}
	if err := s.c.st.RecordHostSamples(ctx, samples); err != nil {
		return fmt.Errorf("seeding the pressured host's samples: %w", err)
	}

	// When each failure completed, from the window's first minute: six inside
	// the busy twenty, and one an hour into the calm.
	failures := []time.Duration{
		3*time.Minute + 10*time.Second, 5*time.Minute + 40*time.Second, 8*time.Minute + 20*time.Second,
		11*time.Minute + 5*time.Second, 13*time.Minute + 50*time.Second, 16*time.Minute + 30*time.Second,
		70*time.Minute + 15*time.Second,
	}
	for i, at := range failures {
		completed := first.Add(at)
		started := completed.Add(-(90*time.Second + time.Duration(i)*10*time.Second))
		j := s.job(fmt.Sprintf("job_demopress%d", i+1), linux, demoRepos[0], "Nightly", "integration", s.run(), started)
		j.EligibleAt, j.HostID = &started, host.ID
		if err := s.finish(ctx, j, "failure", started, completed); err != nil {
			return err
		}
	}
	return nil
}

// imageFailures is the startup fixture: the second builder starts one of the
// linux pool's runners and then fails six in a row before their containers
// start, because it cannot pull the runner image. The start that registered
// comes first, so the run of failures has a start before it to be failing
// since (P20). The pool's runners started on the first builder all window, so
// the host, not the pool, is what keeps failing: six of seven there, and
// under half of the pool's nineteen. Each failure records the image fault,
// which explains all six, so the finding has nothing to hedge on.
//
// They are failed rows, as a failed start stays until retention.runners
// prunes it, cleaned up on the host and on GitHub as the fleet does.
func (s *analysisSeed) imageFailures(ctx context.Context, linux *store.Pool, host *store.Host) error {
	requested := s.from.Add(30 * time.Minute)
	registered := requested.Add(40 * time.Second)
	r := s.runner("run_demopull1", linux, host, requested)
	cameUp(r, requested.Add(12*time.Second), registered)
	ended(r, registered.Add(6*time.Minute+5*time.Second))
	r.Message = "idle for 6m, over the 5m idle timeout"
	if err := s.saveRunner(ctx, r); err != nil {
		return err
	}

	image := s.c.RunnerImage(linux)
	for k := range 6 {
		requested := s.from.Add(45*time.Minute + time.Duration(k)*10*time.Minute)
		r := s.runner(fmt.Sprintf("run_demopull%d", k+2), linux, host, requested)
		// The pull is what failed, so there was never a container.
		r.State, r.FaultKind, r.ContainerID = store.RunnerFailed, store.FaultImage, ""
		ended(r, requested.Add(35*time.Second))
		r.Message = fmt.Sprintf("backend: pulling %s: Error response from daemon: unauthorized: authentication required", image)
		if err := s.saveRunner(ctx, r); err != nil {
			return err
		}
	}
	return nil
}

package controller

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/analysis"
)

// demoSeededAt is off the minute, as the clock a demo is seeded on almost
// always is: a window of two hours then overlaps a hundred and twenty-one
// sampled minutes, and the seeded causes have to hold all the same.
var demoSeededAt = time.Date(2026, 10, 12, 14, 37, 23, 0, time.UTC)

// seededDemo is the demo fleet on a clock the test holds, with the window the
// analysis fixture was placed in.
func seededDemo(t *testing.T) (*harness, AnalysisWindow) {
	t.Helper()
	h := newHarnessAt(t, func() time.Time { return demoSeededAt })
	if err := h.c.SeedDemo(h.ctx); err != nil {
		t.Fatalf("SeedDemo: %v", err)
	}
	return h, AnalysisWindow{Since: demoSeededAt.Add(-demoAnalysisFrom), Until: demoSeededAt.Add(-demoAnalysisTo)}
}

// The demo is where a person first sees an analysis, so each must lead with
// the cause seeded for it, and say it firmly: a demo that hedges, or names
// another cause, teaches that the analyses cannot be leaned on.
func TestEachSeededCauseIsNamedDominantAtHighConfidence(t *testing.T) {
	h, w := seededDemo(t)

	for _, tc := range []struct {
		pool string
		want analysis.WaitCause
	}{
		{demoPoolLinuxID, analysis.CauseRunnerStartup},
		{demoPoolArmID, analysis.CausePoolCeiling},
	} {
		f, err := h.c.AnalyseQueueWait(h.ctx, w, tc.pool)
		if err != nil {
			t.Fatalf("AnalyseQueueWait(%s): %v", tc.pool, err)
		}
		if f.Dominant != string(tc.want) || f.Confidence != analysis.High {
			t.Errorf("queue wait on %s leads with %q at %s (%s): %q; want %s at high",
				tc.pool, f.Dominant, f.Confidence, f.ConfidenceReason, f.Summary, tc.want)
		}
	}

	host := demoHostPrefix + "b"
	p, err := h.c.AnalyseHostPressure(h.ctx, w, host)
	if err != nil {
		t.Fatalf("AnalyseHostPressure(%s): %v", host, err)
	}
	if p.Dominant != analysis.HostPressured || p.Confidence != analysis.High {
		t.Errorf("host pressure on %s leads with %q at %s (%s): %q; want %s at high",
			host, p.Dominant, p.Confidence, p.ConfidenceReason, p.Summary, analysis.HostPressured)
	}

	s, err := h.c.AnalyseStartupFailures(h.ctx, w, "", "")
	if err != nil {
		t.Fatalf("AnalyseStartupFailures: %v", err)
	}
	if s.Dominant != "host:"+host || s.Confidence != analysis.High {
		t.Errorf("startup failures lead with %q at %s (%s): %q; want host:%s at high",
			s.Dominant, s.Confidence, s.ConfidenceReason, s.Summary, host)
	}
	// The image fault is said as Task 4 words it, and no more than that: a
	// pull that failed or an image that would not start.
	if want := "the runner image could not be pulled or would not start"; !strings.Contains(s.Summary, want) {
		t.Errorf("startup failures say %q; want the image fault's own words, %q", s.Summary, want)
	}
}

// Decision 7: over the last day the demo has a dozen jobs or so on each of
// its two releases, and the comparison says that is too few to rank rather
// than ranking them. The analysis fixture's jobs carry no release, so they
// cannot tip it.
func TestTheDemoComparisonSaysItsSampleIsSmall(t *testing.T) {
	h, _ := seededDemo(t)

	f, err := h.c.AnalyseCompare(h.ctx, CompareRequest{Since: demoSeededAt.Add(-24 * time.Hour), Until: demoSeededAt})
	if err != nil {
		t.Fatalf("AnalyseCompare: %v", err)
	}
	if f.Evidence.A.Label != "v1.3.2" || f.Evidence.B.Label != "v1.3.3" {
		t.Errorf("the comparison set %s against %s; want v1.3.2 against v1.3.3", f.Evidence.A.Label, f.Evidence.B.Label)
	}
	if f.Confidence != analysis.Low {
		t.Errorf("the comparison is at %s (%s); want low", f.Confidence, f.ConfidenceReason)
	}
	if want := "fewer than 30 on either side, so the two are not ranked"; !strings.Contains(f.Summary, want) {
		t.Errorf("the comparison says %q; want it to say %q", f.Summary, want)
	}
}

package controller

import (
	"context"
	"errors"
	"testing"

	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

func TestIsDemoID(t *testing.T) {
	for _, tc := range []struct {
		id   string
		want bool
	}{
		{"ins_demoacme", true},
		{"pool_demolinux", true},
		{"host_demo1", true},
		{"run_demo09", true},
		{"pool_k3f9qz2mx7ab", false},
		{"ins_democracy", true}, // readable, and not the shape NewID makes
		{"job_demostuckheldjob", true},
		// A real identifier whose random part happens to begin "demo". One row
		// in a million does, and it used to be skipped by the prober, the
		// poller and the reap, and never reclaimed if it was a host.
		{"ins_demoq2mx7abk3", false},
		{"host_demozzzzzzzzz", false},
		{"nounderscore", false},
		{"", false},
	} {
		if got := IsDemoID(tc.id); got != tc.want {
			t.Errorf("IsDemoID(%q) = %v, want %v", tc.id, got, tc.want)
		}
	}
}

// Every identifier the seed writes has to be one IsDemoID recognises, and the
// rule it recognises them by is the shape, so no fixture may be exactly the
// shape NewID produces. This is the test that stops a future fixture named
// with thirteen readable letters from becoming a real row overnight.
func TestEveryDemoFixtureIsRecognisedAsOne(t *testing.T) {
	h := newHarness(t)
	t.Setenv(StuckSeedEnvVar, "1")
	if err := h.c.SeedDemo(h.ctx); err != nil {
		t.Fatalf("SeedDemo: %v", err)
	}
	if err := h.c.SeedStuck(h.ctx); err != nil {
		t.Fatalf("seedStuck: %v", err)
	}
	var ids []string
	insts, _ := h.st.ListInstallations(h.ctx)
	for _, i := range insts {
		ids = append(ids, i.ID)
	}
	pools, _ := h.st.ListPools(h.ctx)
	for _, p := range pools {
		ids = append(ids, p.ID)
	}
	hosts, _ := h.st.ListHosts(h.ctx)
	for _, hh := range hosts {
		ids = append(ids, hh.ID)
	}
	for _, r := range h.runners() {
		ids = append(ids, r.ID)
	}
	jobs, _, _ := h.st.ListJobs(h.ctx, store.JobFilter{}, store.Page{Limit: 500})
	for _, j := range jobs {
		ids = append(ids, j.ID)
	}
	if len(ids) < 60 {
		t.Fatalf("collected only %d fixture identifiers; the seed is not what this test thinks it is", len(ids))
	}
	for _, id := range ids {
		if !IsDemoID(id) {
			t.Errorf("fixture %q is not recognised as demo data", id)
		}
		if store.LooksGenerated(id) {
			t.Errorf("fixture %q has the shape of a real identifier; a fixture must never be mistakable for one", id)
		}
	}
}

// The demo fixtures have no GitHub behind them. If the credential prober were
// allowed to check them, every demo instance and every UI test run would open
// on a problems drawer led by "this installation is not usable" -- a failure
// that says nothing about the operator's fleet and hides the ones that do.
func TestDemoInstallationIsNotProbed(t *testing.T) {
	h := newHarness(t)
	ctx := context.Background()

	if err := h.c.SeedDemo(ctx); err != nil {
		t.Fatalf("SeedDemo: %v", err)
	}
	h.c.probeInstallations(ctx)

	inst, err := h.st.GetInstallation(ctx, demoInstallationID)
	if err != nil {
		t.Fatalf("GetInstallation: %v", err)
	}
	if inst.LastError != "" {
		t.Errorf("the demo installation was probed and recorded %q; it must be skipped", inst.LastError)
	}

	problems, err := h.c.Problems(ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	for _, p := range problems {
		if p.Code == "installation.unhealthy" {
			t.Errorf("the demo fleet reports %q: %s", p.Code, p.Title)
		}
	}
}

// The demo installation must answer every read the UI makes without reaching
// GitHub. Before this, the Installations page 500'd on the rate limit and the
// poller logged a credential failure every thirty seconds, which makes a demo
// instance read as broken software rather than as a working fleet.
func TestDemoInstallationAnswersReadsWithoutGitHub(t *testing.T) {
	h := newHarness(t)
	ctx := context.Background()
	if err := h.c.SeedDemo(ctx); err != nil {
		t.Fatalf("SeedDemo: %v", err)
	}

	client, err := h.c.ClientFor(ctx, demoInstallationID)
	if err != nil {
		t.Fatalf("ClientFor: %v", err)
	}

	if _, err := client.Probe(ctx); err != nil {
		t.Errorf("Probe: %v", err)
	}
	rl, err := client.RateLimit(ctx)
	if err != nil {
		t.Fatalf("RateLimit: %v", err)
	}
	if rl.Remaining <= 0 || rl.Remaining > rl.Limit {
		t.Errorf("rate limit = %d/%d, want a plausible pair", rl.Remaining, rl.Limit)
	}
	if _, err := client.ListRunners(ctx); err != nil {
		t.Errorf("ListRunners: %v", err)
	}
	if _, err := client.ListRunnerGroups(ctx); err != nil {
		t.Errorf("ListRunnerGroups: %v", err)
	}
	if _, err := client.ListQueuedJobs(ctx); err != nil {
		t.Errorf("ListQueuedJobs: %v", err)
	}
	if err := client.DeleteRunner(ctx, 42); err != nil {
		t.Errorf("DeleteRunner on a registration that never existed should succeed: %v", err)
	}

	// Writes must refuse, and say why. Silently pretending to mint a runner
	// credential would leave runners stuck in provisioning with no explanation.
	if _, err := client.CreateJITConfig(ctx, github.JITRequest{Name: "x"}); err == nil {
		t.Error("CreateJITConfig succeeded on a demo fixture; it must refuse")
	} else if !errors.Is(err, ErrDemoFixture) {
		t.Errorf("CreateJITConfig error = %v, want it to wrap ErrDemoFixture", err)
	}
}

package controller

import (
	"context"
	"encoding/json"
	"fmt"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
)

// seedMemory gives the demo fleet something to show for the memory valve and for
// in-memory folders: what a runner's row says when its pool uses either.
//
// The folders are worked out by the function the backend mounts them from, so a
// demo runner says what a real one would; the valve's figures are the agent's to
// report, which a fixture has no agent to do, so they are written the way a
// report would write them. Each runner below is a state worth seeing -- a loan,
// a loan and swap, a loan that has reached its ceiling, a valve watching, a valve
// only observing -- and none of them is a failure.
func (c *Controller) seedMemory(ctx context.Context, now time.Time, pools []*store.Pool, hosts []*store.Host, runners []*store.Runner) error {
	poolByID := make(map[string]*store.Pool, len(pools))
	for _, p := range pools {
		poolByID[p.ID] = p
	}
	// What the valve has done for the runner at each position of the fixture's
	// runner list. Positions are the fixture's own, as they are in seedRunners.
	type valve struct {
		sample   backend.MemoryValveSample
		memoryMB int64
	}
	mb := int64(1) << 20
	states := map[int]valve{
		0: {backend.MemoryValveSample{Mode: "automatic", Code: string(agent.MemoryRaised), Raises: 2, LentBytes: 1536 * mb,
			Reason: "raised the limit from 5120 to 5632 MB: it was using 4300 MB"}, 5000},
		1: {backend.MemoryValveSample{Mode: "automatic", Code: string(agent.MemorySpilled), Raises: 3, LentBytes: 2048 * mb, SpillBytes: 2048 * mb, NearLimit: true,
			Reason: "that is the most this runner may have (6144 MB); allowed 2048 MB of swap beyond its 6144 MB limit"}, 5900},
		2: {backend.MemoryValveSample{Mode: "automatic", Code: string(agent.MemoryHealthy)}, 1800},
		3: {backend.MemoryValveSample{Mode: "automatic", Code: string(agent.MemoryHealthy)}, 400},
		4: {backend.MemoryValveSample{Mode: "automatic", Code: string(agent.MemoryAtCeiling), Raises: 4, LentBytes: 2048 * mb, NearLimit: true,
			Reason: "it holds 6144 MB, the most this runner may have"}, 6000},
		5: {backend.MemoryValveSample{Mode: "observe", Code: string(agent.MemoryRaised), NearLimit: true, WouldLendBytes: 1024 * mb,
			Reason: "would have raised the limit from 8192 to 9216 MB: it was using 7400 MB"}, 7400},
		8: {backend.MemoryValveSample{Mode: "automatic", Code: string(agent.MemoryRaised), Raises: 1, LentBytes: 512 * mb,
			Reason: "raised the limit from 4096 to 4608 MB: it was using 3500 MB"}, 4000},
	}
	for i, r := range runners {
		p := poolByID[r.PoolID]
		if p == nil || r.State.Terminal() {
			continue
		}
		if v, ok := states[i]; ok {
			at := now
			raw, err := json.Marshal(backend.Stats{SampledAt: &at, CPUPercent: r.CPUPercent, MemoryBytes: v.memoryMB * mb, MemoryValve: &v.sample})
			if err != nil {
				return fmt.Errorf("encoding the demo memory sample for %s: %w", r.Name, err)
			}
			if err := c.st.SetRunnerResourceSample(ctx, r.ID, r.CPUPercent, v.memoryMB*mb, raw); err != nil {
				return fmt.Errorf("seeding the demo memory sample for %s: %w", r.Name, err)
			}
			if lent := v.sample.LentBytes / mb; lent > 0 {
				if err := c.st.SetRunnerLentMemory(ctx, r.ID, lent); err != nil {
					return fmt.Errorf("seeding the memory lent to %s: %w", r.Name, err)
				}
			}
		}
		if p.Tmpfs.Any() {
			spec := backend.Spec{
				Resources: p.Resources, ResourcesSource: store.AllocationFromPool,
				Tmpfs: p.Tmpfs, DockerMode: p.DockerMode,
			}
			if scratch := backend.PlanScratch(spec, p.Tmpfs); scratch.Any() {
				if err := c.st.SetRunnerScratch(ctx, r.ID, scratch); err != nil {
					return fmt.Errorf("seeding the in-memory folders of %s: %w", r.Name, err)
				}
			}
		}
	}
	// Each host's pool, from the same plan a heartbeat makes, so the Hosts page
	// shows what the controller would have worked out rather than a number
	// written here.
	for _, h := range hosts {
		c.elasticMemoryDirective(ctx, h, agent.HeartbeatRequest{Features: []string{agent.FeatureElasticMemory}}, now)
	}
	return nil
}

package controller

import (
	"context"
	"fmt"
	"os"
	"slices"
	"strconv"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/version"
)

// StuckSeedEnvVar names the environment variable that adds the diagnostics
// fixture on top of the demo fleet.
//
// It is separate from ZOOMIES_SEED_DEMO on purpose, and it is the opposite of
// what a demo wants. The demo deliberately keeps its two starting runners young
// (see freshenDemoRunners) so an instance left open never reports a fault in a
// fleet that has no agent to have one. Every diagnostic this project has for a
// fleet in trouble -- the problems drawer, the stuck-runner shapes, the blocked
// pool, the held job -- is therefore unreachable from the demo, which is why
// they went untested until this existed.
//
// Nothing here is for an operator. It exists so a test can open the pages an
// operator opens on their worst day.
const StuckSeedEnvVar = "ZOOMIES_SEED_STUCK"

// The diagnostics fixture's own identifiers. They begin "demo" after the
// prefix, so IsDemoID covers them and every guard that keeps a fixture out of a
// real fleet applies to them unchanged.
const (
	stuckPoolID    = "pool_demostuckblocked"
	stuckPoolName  = "zoomies-demo-stuck-blocked"
	stuckHeldJobID = "job_demostuckheldjob"
	// stuckBlockedJobID is the job waiting on the pool nothing can place: the
	// fixture for an explanation whose class is the scheduler's own reason.
	stuckBlockedJobID = "job_demostuckblocked"
	// StuckThrottledHostName is the fixture's throttled host, named here so
	// a browser test can find its card.
	StuckThrottledHostName = "demo-throttled-1"
	stuckThrottledHostID   = demoHostPrefix + "stuckthrottled"
)

// stuckSeedRequested reports whether the diagnostics fixture was asked for.
func stuckSeedRequested() bool {
	v, ok := os.LookupEnv(StuckSeedEnvVar)
	if !ok {
		return false
	}
	b, err := strconv.ParseBool(v)
	return err == nil && b
}

// SeedStuck ages the demo's starting runners into the two stuck shapes and adds
// the two fixtures the demo has no room for: a pool nothing can place, and a
// job GitHub is holding.
//
// It runs after SeedDemo and depends on it, because a fleet in trouble is only
// legible against one that is working: the point of the problems drawer is that
// it names the three things wrong among the twenty that are right.
func (c *Controller) SeedStuck(ctx context.Context) error {
	now := c.Now()

	// The demo's two starting runners are the two shapes exactly: one with no
	// container yet, one whose container came up and never registered. They are
	// already the right shape and only ever the wrong age, so this back-dates
	// them rather than writing more rows -- a fixture that duplicated them
	// would drift from the demo's the first time either was edited.
	starting, _, err := c.st.ListRunners(ctx, store.RunnerFilter{
		States: []store.RunnerState{store.RunnerProvisioning, store.RunnerRegistering},
	}, store.Page{Limit: 100})
	if err != nil {
		return fmt.Errorf("listing the runners to age: %w", err)
	}
	// Three quarters of the provision timeout: past half, which is when
	// runners.not_progressing starts saying so, and short of the whole, which
	// is when the reconcile loop gives up and fails the runner. Ageing them to
	// the full timeout produced a fixture with one stuck runner rather than
	// two, because the next pass failed the one with no container -- which is
	// the correct behaviour and the wrong fixture.
	stuckSince := now.Add(-c.cfg().Scheduler.ProvisionTimeout * 3 / 4)
	aged := 0
	for _, r := range starting {
		if !IsDemoID(r.ID) {
			continue
		}
		if r.ContainerStartedAt != nil {
			err = c.st.SetRunnerStartup(ctx, r.ID, r.ImagePullDuration, &stuckSince)
		} else {
			err = c.st.SetRunnerCreatedAt(ctx, r.ID, stuckSince)
		}
		if err != nil {
			return fmt.Errorf("ageing runner %s into a stuck one: %w", r.ID, err)
		}
		aged++
	}
	if aged == 0 {
		return fmt.Errorf("no demo runner was starting up, so there is nothing to make stuck; is %s set too?", SeedEnvVar)
	}

	if err := c.seedBlockedPool(ctx); err != nil {
		return err
	}
	if err := c.seedHeldJob(ctx, now); err != nil {
		return err
	}
	if err := c.seedThrottledHost(ctx, now); err != nil {
		return err
	}
	c.log.Info("seeded the diagnostics fixture", "env", StuckSeedEnvVar, "stuck_runners", aged)
	return nil
}

// seedBlockedPool writes a pool no host can take, so the scheduler's own
// sentence for that -- and the pool warning the drawer renders from it -- has
// something to say.
//
// The selector is what makes it unplaceable, rather than a disabled pool or a
// ceiling of zero: those are choices an operator made, and the page says so
// differently. A selector nothing answers is the misconfiguration, and it is
// the one the reason string exists to explain.
func (c *Controller) seedBlockedPool(ctx context.Context) error {
	if _, err := c.st.GetPool(ctx, stuckPoolID); err == nil {
		return nil
	}
	p := &store.Pool{
		ID:             stuckPoolID,
		Name:           stuckPoolName,
		InstallationID: demoInstallationID,
		Labels:         store.StringSlice(store.BrandLabels([]string{"linux", "x64", stuckPoolName})),
		Backend:        store.BackendDocker,
		MinRunners:     1,
		MaxRunners:     2,
		IdleTimeout:    store.Duration(5 * time.Minute),
		Ephemeral:      true,
		DockerMode:     store.DockerNone,
		// No host answers this, and none is meant to.
		HostSelector: store.StringMap{"zone": "nowhere"},
		Enabled:      true,
	}
	if err := c.st.CreatePool(ctx, p); err != nil {
		return fmt.Errorf("seeding the blocked pool: %w", err)
	}
	return c.seedBlockedJob(ctx, p)
}

// seedBlockedJob queues one job the blocked pool claims, so that the pool's
// reason for placing nothing has a job to be the explanation of.
func (c *Controller) seedBlockedJob(ctx context.Context, p *store.Pool) error {
	if _, err := c.st.GetJob(ctx, stuckBlockedJobID); err == nil {
		return nil
	}
	queued := c.Now().Add(-10 * time.Minute)
	job := &store.Job{
		ID: stuckBlockedJobID, GitHubJobID: 80095, GitHubRunID: 40050, RunNumber: 350,
		Repo: demoRepos[0], Workflow: "CI", JobName: "build",
		Labels: p.Labels, InstallationID: p.InstallationID, PoolID: p.ID, Matched: true,
		State: store.JobQueued, QueuedAt: queued, EligibleAt: &queued,
		HTMLURL:    fmt.Sprintf("https://github.com/%s/actions/runs/%d", demoRepos[0], 40050),
		HeadBranch: "main", HeadSHA: fmt.Sprintf("%040x", 0xC0FFEE+95*7919), RunAttempt: 1,
	}
	saved, change, err := c.st.ApplyJob(ctx, job)
	if err != nil {
		return fmt.Errorf("seeding the blocked job: %w", err)
	}
	return c.seedJobTimeline(ctx, saved, change)
}

// seedHeldJob writes a job GitHub is holding for a deployment review.
//
// It is the one job state the demo has never carried, and the one that reads
// as a fleet fault when it is not: every panel that explains a wait keys on
// `queued`, so a held job used to sit in the drawer with nothing said about it.
func (c *Controller) seedHeldJob(ctx context.Context, now time.Time) error {
	held := &store.Job{
		ID:             stuckHeldJobID,
		GitHubJobID:    80099,
		GitHubRunID:    40099,
		RunNumber:      399,
		Repo:           demoRepos[0],
		Workflow:       "Deploy",
		JobName:        "deploy-production",
		Labels:         store.StringSlice(store.BrandLabels([]string{"linux", "x64", "zoomies-demo-linux-x64"})),
		InstallationID: demoInstallationID,
		State:          store.JobWaiting,
		QueuedAt:       now.Add(-18 * time.Minute),
		HTMLURL:        fmt.Sprintf("https://github.com/%s/actions/runs/%d", demoRepos[0], 40099),
		HeadBranch:     "main",
		HeadSHA:        fmt.Sprintf("%040x", 0xDEC1DE),
		RunAttempt:     1,
	}
	saved, change, err := c.st.ApplyJob(ctx, held)
	if err != nil {
		return fmt.Errorf("seeding the held job: %w", err)
	}
	return c.seedJobTimeline(ctx, saved, change)
}

// seedThrottledHost writes a host the controller has stepped down after
// sustained pressure, with a live runner on it that was given one slot's
// share of the machine, so the host card's throttle notice, the runner
// detail's allocation and the problems drawer's host.throttled entry all
// have something to render.
//
// It is throttled for its load average rather than for a CPU hold, because
// that is the signal the ladder was added for: a machine whose CPU pinned at
// 100% and stopped saying anything, while the runnable queue kept growing.
// The measurements are the shape of that machine -- CPU at 60% because the
// throttle has already halved every runner's quota, load still at thirty on
// eight cores because the work is still there -- and the demo heartbeat keeps
// the sample fresh so the card can keep explaining itself. Housekeeping leaves
// the demo's hosts alone, so the rung does not climb or lift on its own.
func (c *Controller) seedThrottledHost(ctx context.Context, now time.Time) error {
	if _, err := c.st.GetHost(ctx, stuckThrottledHostID); err == nil {
		return nil
	}
	cpu, load, memory := 60.0, 30.0, int64(4096)
	since := now.Add(-7 * time.Minute)
	changed := now.Add(-3 * time.Minute)
	h := &store.Host{
		ID:       stuckThrottledHostID,
		Name:     StuckThrottledHostName,
		Address:  "10.0.0.14",
		Capacity: 4,
		Backends: store.StringSlice{"docker"},
		BackendInfo: store.HostBackends{
			{Kind: store.BackendDocker, Available: true, Version: "27.1.1",
				Rootless: true, Endpoint: "unix:///run/user/1000/docker.sock", SupportsDinD: true,
				Limits: store.LimitSupport{Known: true, CPU: true, Memory: true, Pids: true}},
		},
		Labels:      store.StringMap{"arch": "amd64", "zone": "demo"},
		OS:          "linux",
		Distro:      "ubuntu",
		OSVersion:   "24.04",
		Arch:        "amd64",
		CPUs:        8,
		MemoryMB:    16384,
		DiskTotalMB: 524_288,
		DiskFreeMB:  301_989,
		Usage: store.HostUsage{
			CPUPercent:        &cpu,
			LoadAverage1:      &load,
			MemoryAvailableMB: &memory,
			SampledAt:         now,
		},
		Throttle: store.HostThrottle{
			Level:     2,
			Since:     &since,
			ChangedAt: &changed,
			Reason:    "the 1-minute load average is 30.0, at least twice the host's 8 CPUs",
		},
		Version:         version.Version,
		ProtocolVersion: agent.ProtocolVersion,
		LastHeartbeat:   now,
	}
	if err := c.st.CreateHost(ctx, h); err != nil {
		return fmt.Errorf("seeding the throttled host: %w", err)
	}
	// One of the demo's busy runners moves here and is given the share a
	// four-slot host of this size hands out: (8 - 0.5) / 4 CPUs, floored to
	// the hundredth, and (16384 - 512) / 4 MB. Moved rather than written
	// afresh so the fixture's runner count stays what the demo's tests pin.
	runners, _, err := c.st.ListRunners(ctx, store.RunnerFilter{
		States: []store.RunnerState{store.RunnerBusy},
	}, store.Page{Limit: 100})
	if err != nil {
		return fmt.Errorf("listing the runners to place on the throttled host: %w", err)
	}
	slices.SortFunc(runners, func(a, b *store.Runner) int { return strings.Compare(a.ID, b.ID) })
	for _, r := range runners {
		if !IsDemoID(r.ID) {
			continue
		}
		r.HostID = h.ID
		r.AllocatedCPUs = 1.87
		r.AllocatedMemoryMB = 3968
		r.AllocationSource = store.AllocationFromHost
		if err := c.st.UpdateRunner(ctx, r); err != nil {
			return fmt.Errorf("placing runner %s on the throttled host: %w", r.ID, err)
		}
		return nil
	}
	return fmt.Errorf("no demo runner was busy, so none can be placed on the throttled host; is %s set too?", SeedEnvVar)
}

package controller

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// The diagnostics fixture carries one throttled host with a runner on it that
// was given the host's default share, so the host card's throttle notice, the
// runner detail's allocation and the drawer's host.throttled entry can all be
// looked at -- and it has to stay that way for as long as the instance is
// open, or a screenshot taken a minute after start shows a different fleet.
func TestSeedStuckAddsAThrottledHostThatStaysThrottled(t *testing.T) {
	h := newHarness(t)
	t.Setenv(StuckSeedEnvVar, "1")
	if err := h.c.SeedDemo(h.ctx); err != nil {
		t.Fatalf("SeedDemo: %v", err)
	}
	if err := h.c.SeedStuck(h.ctx); err != nil {
		t.Fatalf("SeedStuck: %v", err)
	}
	host, err := h.st.GetHostByName(h.ctx, StuckThrottledHostName)
	if err != nil {
		t.Fatalf("the fixture's throttled host is missing: %v", err)
	}
	if host.Throttle.Level != 2 || host.EffectiveCapacity() != 2 || !host.Usage.Fresh(h.c.Now()) {
		t.Fatalf("host = throttle %+v, effective %d, fresh %v; want rung 2 of 4 with a fresh sample", host.Throttle, host.EffectiveCapacity(), host.Usage.Fresh(h.c.Now()))
	}
	view := h.c.HostView(host)
	if !strings.Contains(view.ThrottleReason, "30.0") || view.Throttle == nil || view.EffectiveCapacity != 2 {
		t.Fatalf("view = reason %q, throttle %+v, effective %d", view.ThrottleReason, view.Throttle, view.EffectiveCapacity)
	}
	if !contains(h.problemCodes(), "host.throttled") {
		t.Fatalf("problems = %v, want host.throttled", h.problemCodes())
	}
	var placed *store.Runner
	for _, r := range h.runners() {
		if r.HostID == host.ID {
			placed = r
		}
	}
	if placed == nil || placed.State != store.RunnerBusy || placed.AllocationSource != store.AllocationFromHost ||
		placed.AllocatedCPUs != 1.87 || placed.AllocatedMemoryMB != 3968 {
		t.Fatalf("runner on the throttled host = %+v; want a busy one allocated the host's share", placed)
	}
	if got := len(h.runners()); got != 35 {
		t.Fatalf("the fixture has %d runners, want the demo's 35: the runner was to be moved, not added", got)
	}

	// Seeding again is a no-op.
	if err := h.c.SeedStuck(h.ctx); err != nil {
		t.Fatalf("second SeedStuck: %v", err)
	}
	hosts, err := h.st.ListHosts(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	if len(hosts) != 4 {
		t.Fatalf("seeded %d hosts, want the demo's 3 and the throttled one", len(hosts))
	}

	// Long enough for the sample to have gone stale and the reset to be due:
	// the demo beat keeps the sample fresh and housekeeping leaves the
	// fixture's rung alone, so the card keeps explaining itself.
	future := time.Now().Add(scheduler.StaleThrottleReset * 2)
	h.c.clock = func() time.Time { return future }
	h.c.beatDemoHosts(h.ctx)
	h.c.settleThrottles(h.ctx, future)
	host, err = h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	if host.Throttle.Level != 2 || !host.Usage.Fresh(future) || !host.Healthy(future) {
		t.Fatalf("after housekeeping: throttle %+v, fresh %v, healthy %v; the fixture did not hold", host.Throttle, host.Usage.Fresh(future), host.Healthy(future))
	}
}

package controller

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// The fixture has to survive the loop that reads it.
//
// A pool holding more runners than its queue justifies has the ones that have
// not finished starting drained on the very first pass -- "queued demand
// disappeared before this runner finished starting" -- so a demo seeded with a
// runner in provisioning and one in registering showed neither a second later.
// That is both states missing from the grid and from the screenshots, and it
// leaves the diagnostics fixture, which ages exactly those two into stuck
// runners, with nothing to age.
func TestSeedDemoKeepsItsStartingRunnersThroughAReconcilePass(t *testing.T) {
	h := newHarness(t)
	if err := h.c.SeedDemo(h.ctx); err != nil {
		t.Fatalf("SeedDemo: %v", err)
	}

	starting := map[string]store.RunnerState{}
	for _, r := range h.runners() {
		if r.State == store.RunnerProvisioning || r.State == store.RunnerRegistering {
			starting[r.ID] = r.State
		}
	}
	if len(starting) != 2 {
		t.Fatalf("the fixture starts %d runners, want the two states the UI has to show", len(starting))
	}

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}

	for _, r := range h.runners() {
		want, ok := starting[r.ID]
		if !ok {
			continue
		}
		if r.State != want {
			t.Fatalf("runner %s was %s before the pass and is %s after it (%q); the fixture does not add up to the scheduler",
				r.ID, want, r.State, r.Message)
		}
	}
}

// The Playwright suite and a demo instance both need a fleet with something in
// it. This is that fixture, and it has to be the same fixture every time.
func TestSeedDemoBuildsAFleet(t *testing.T) {
	h := newHarness(t)

	if err := h.c.SeedDemo(h.ctx); err != nil {
		t.Fatalf("SeedDemo: %v", err)
	}

	pools, err := h.st.ListPools(h.ctx)
	if err != nil {
		t.Fatalf("ListPools: %v", err)
	}
	if len(pools) != 2 {
		t.Fatalf("seeded %d pools, want 2", len(pools))
	}

	hosts, err := h.st.ListHosts(h.ctx)
	if err != nil {
		t.Fatalf("ListHosts: %v", err)
	}
	if len(hosts) != 3 {
		t.Fatalf("seeded %d hosts, want 3", len(hosts))
	}

	// A dozen across the state machine, and the analysis fixture's twenty-three
	// from a day back: twelve slow starts, the four that held the arm pool at
	// its ceiling, and seven starts on the host that could not pull the image.
	runners := h.runners()
	if len(runners) != 35 {
		t.Fatalf("seeded %d runners, want 35", len(runners))
	}
	states := map[store.RunnerState]int{}
	for _, r := range runners {
		states[r.State]++
	}
	for _, want := range []store.RunnerState{
		store.RunnerProvisioning, store.RunnerRegistering, store.RunnerIdle,
		store.RunnerBusy, store.RunnerDraining, store.RunnerFailed, store.RunnerRemoved,
	} {
		if states[want] == 0 {
			t.Fatalf("no seeded runner is %q; the UI has nothing to render for that state", want)
		}
	}

	jobs, total, err := h.st.ListJobs(h.ctx, store.JobFilter{}, store.Page{Limit: 100})
	if err != nil {
		t.Fatalf("ListJobs: %v", err)
	}
	// Fifty of a morning's history, the two on a vendor's runners, the backlog
	// that explains the runners this fleet has not finished starting, the two
	// older failures seeded for why (a job GitHub timed out and a job whose
	// runner never registered), and the analysis fixture's thirty-five from a
	// day back: twelve slow to start, four nightly shards and the twelve they
	// held up, and seven that failed on a host under pressure.
	if total != 92 {
		t.Fatalf("seeded %d jobs, want 92", total)
	}
	// The checks below walk one page; a seed that outgrew it would drop rows
	// from them silently rather than fail.
	if len(jobs) != total {
		t.Fatalf("read %d of %d seeded jobs; raise the page limit", len(jobs), total)
	}
	var completed, queued, running, unmatched, elsewhere int
	for _, j := range jobs {
		switch j.State {
		case store.JobCompleted:
			completed++
		case store.JobQueued:
			queued++
		case store.JobInProgress:
			running++
		}
		if !j.Matched {
			unmatched++
		}
		// A job on a vendor's runner: no pool claimed it and no runner here
		// ran it. The Overview's panels are built to tell these apart, so the
		// fixture has to contain some -- one finished, one still running, and
		// one still queued, which is the one the default view used to show.
		if store.HostedJob(j.Labels) {
			elsewhere++
		}
	}
	if completed == 0 || queued == 0 || running == 0 {
		t.Fatalf("job mix = %d completed, %d queued, %d running; the Overview needs all three",
			completed, queued, running)
	}
	if unmatched == 0 {
		t.Fatal("no seeded job is unmatched, so the problems drawer has nothing to show")
	}
	if elsewhere != 3 {
		t.Fatalf("%d jobs belong to somebody else's runners, want 3 (one finished, one running, one queued)", elsewhere)
	}

	// The Overview's history and the audit page both need rows.
	evs, err := h.st.ListScalingEvents(h.ctx, "", 50)
	if err != nil {
		t.Fatalf("ListScalingEvents: %v", err)
	}
	if len(evs) == 0 {
		t.Fatal("no scaling history was seeded")
	}
	audit, auditTotal, err := h.st.ListAudit(h.ctx, store.AuditFilter{}, store.Page{Limit: 50})
	if err != nil {
		t.Fatalf("ListAudit: %v", err)
	}
	if auditTotal == 0 || len(audit) == 0 {
		t.Fatal("no audit rows were seeded")
	}

	// The shared browser controller lives for the whole suite. Keep the burst
	// close enough to the fixture's present that its one-hour view still has a
	// queued-with-nothing-idle spell when the mobile project reaches it.
	samples, err := h.st.ListSamples(h.ctx, h.c.Now().Add(-30*time.Minute))
	if err != nil {
		t.Fatalf("ListSamples: %v", err)
	}
	starved := 0
	for _, sample := range samples {
		if sample.FleetQueuedJobs > 0 && sample.IdleRunners == 0 {
			starved++
		}
	}
	if starved == 0 {
		t.Fatal("the recent demo history has no queued work with nothing idle")
	}

	// Stats has to work over the fixture, since that is what the Overview does.
	if _, err := h.c.Stats(h.ctx, 24*time.Hour); err != nil {
		t.Fatalf("Stats over the fixture: %v", err)
	}
}

// Seeding twice must not double the fixture: the Playwright suite restarts the
// binary and would otherwise accumulate a fleet.
func TestSeedDemoIsIdempotent(t *testing.T) {
	h := newHarness(t)
	if err := h.c.SeedDemo(h.ctx); err != nil {
		t.Fatalf("first SeedDemo: %v", err)
	}
	before := len(h.runners())

	if err := h.c.SeedDemo(h.ctx); err != nil {
		t.Fatalf("second SeedDemo: %v", err)
	}
	if got := len(h.runners()); got != before {
		t.Fatalf("runners went from %d to %d on a second seed", before, got)
	}
}

// Fixtures appearing in somebody's real fleet would be indistinguishable from
// a compromise, so an instance that is already in use is refused.
func TestSeedDemoRefusesARealFleet(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	h.pool(inst, "production-linux")

	err := h.c.SeedDemo(h.ctx)
	if err == nil {
		t.Fatal("SeedDemo seeded an instance that already had a real pool")
	}
	if !strings.Contains(err.Error(), "production-linux") || !strings.Contains(err.Error(), SeedEnvVar) {
		t.Fatalf("error = %q, want it to name the pool and how to turn seeding off", err)
	}
	if got := len(h.runners()); got != 0 {
		t.Fatalf("the refused seed still wrote %d runners", got)
	}
}

// The Jobs page's drawer, its failed filter and the problems drawer's "runner
// lost" entry all need a fixture behind them, and the timeline needs one job
// whose story it can tell in full.
func TestSeedDemoGivesJobsStepsATimelineAndOneLostRunner(t *testing.T) {
	h := newHarness(t)
	if err := h.c.SeedDemo(h.ctx); err != nil {
		t.Fatalf("SeedDemo: %v", err)
	}

	failed, total, err := h.st.ListJobs(h.ctx, store.JobFilter{FailedOnly: true}, store.Page{Limit: 100})
	if err != nil {
		t.Fatalf("ListJobs: %v", err)
	}
	if total == 0 {
		t.Fatal("the seed has no failed job for the failed filter to find")
	}
	var lost *store.Job
	for _, j := range failed {
		if j.Conclusion == "failure" && j.FailedStep() == nil {
			t.Errorf("failed job %s names no failed step", j.ID)
		}
		// The runner lost under the job, not the one that never registered:
		// the registration failure has no runner to have lost.
		if j.RunnerFault != "" && j.RunnerID != "" {
			lost = j
		}
	}
	if lost == nil {
		t.Fatal("no seeded job lost its runner, so the runner_lost badge has no fixture")
	}

	events, err := h.c.JobEvents(h.ctx, lost.ID)
	if err != nil {
		t.Fatalf("JobEvents: %v", err)
	}
	kinds := kindsOfEvents(events)
	for _, want := range []store.JobEventKind{store.JobEventQueued, store.JobEventClaimed, store.JobEventStarted, store.JobEventRunnerLost, store.JobEventCompleted} {
		found := false
		for _, k := range kinds {
			found = found || k == want
		}
		if !found {
			t.Errorf("the lost-runner job's timeline %v lacks %s", kinds, want)
		}
	}
	for i := 1; i < len(events); i++ {
		if events[i].At.Before(events[i-1].At) {
			t.Errorf("timeline out of order at %d: %v after %v", i, events[i].At, events[i-1].At)
		}
	}

	running, _, err := h.st.ListJobs(h.ctx, store.JobFilter{States: []store.JobState{store.JobInProgress}}, store.Page{})
	if err != nil {
		t.Fatalf("ListJobs running: %v", err)
	}
	for _, j := range running {
		if len(j.Steps) == 0 || j.FailedStep() != nil {
			t.Errorf("running job %s has steps %+v, want some in flight and none failed", j.ID, j.Steps)
		}
	}
}

// A pool was the only thing the guard looked at. A production controller that
// has an installation, a host and an administrator but no pool yet -- the
// state every fresh install passes through -- got a fixture fleet if its
// compose file kept ZOOMIES_SEED_DEMO from a trial run.
func TestSeedDemoRefusesAnInstanceWithRealStateButNoPool(t *testing.T) {
	cases := []struct {
		name string
		set  func(h *harness)
		want string
	}{
		{"an installation", func(h *harness) { h.installation() }, "installation"},
		{"a host", func(h *harness) { h.host("build-1") }, `host "build-1"`},
		{"an account", func(h *harness) {
			if err := h.st.CreateUser(h.ctx, &store.User{Username: "root", Role: store.RoleAdmin}); err != nil {
				h.t.Fatalf("CreateUser: %v", err)
			}
		}, "1 account"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			tc.set(h)
			err := h.c.SeedDemo(h.ctx)
			if err == nil {
				t.Fatalf("SeedDemo seeded an instance that already had %s", tc.name)
			}
			if !strings.Contains(err.Error(), tc.want) || !strings.Contains(err.Error(), SeedEnvVar) {
				t.Fatalf("error = %q, want it to name %s and how to turn seeding off", err, tc.want)
			}
			pools, err := h.st.ListPools(h.ctx)
			if err != nil || len(pools) != 0 {
				t.Fatalf("the refused seed still wrote %d pools (%v)", len(pools), err)
			}
		})
	}
}

// And the demo's own fixtures are not "real state": a seeded instance is
// still recognised as seeded on its next start.
func TestSeedDemoStillRecognisesItsOwnFixtures(t *testing.T) {
	h := newHarness(t)
