		t.Fatal(err)
	}
	if err := h.c.SeedDemo(h.ctx); err != nil {
		t.Fatalf("seeding over a leftover row: %v", err)
	}
	rows, _ := h.c.st.ListAssistantProviders(h.ctx)
	if len(rows) != 1 || rows[0].ID != leftover.ID || !rows[0].IsDefault {
		t.Errorf("rows after seeding: %+v", rows)
	}
}

package controller

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/updates"
	"github.com/eyupio/zoomies/internal/updates/channel"
	"github.com/eyupio/zoomies/internal/version"
)

// UpdatesSeedEnvVar names the environment variable that gives a controller a
// release list of its own to be behind, for the browser suite's Updates
// project.
//
// The binary that suite drives is a dev build, which no release comparison
// accepts, so without this the Updates page could only ever say that the build
// is left alone. The value is not a flag: it is the folder the controller will
// do its updating through, which the suite makes and names, and unset or empty
// switches the fixture off. Like the other seeds it is not a setting, and
// nothing in a real deployment's configuration reads it.
const UpdatesSeedEnvVar = "ZOOMIES_SEED_UPDATES"

// updatesSeedVersion is the release the seeded controller says it was built
// from, one behind both of the releases it is offered.
const updatesSeedVersion = "1.3.0"

// updatesSeedReleases are the two releases the fixture offers, newest first as
// GitHub lists them. v1.3.1 has been public for longer than a day and v1.3.2 for
// less, which is the pair the design uses to show what auto's wait costs: the
// newer release restarts it, and the older is passed over for it.
var updatesSeedReleases = []struct {
	tag string
	age time.Duration
}{
	{"v1.3.2", 6 * time.Hour},
	{"v1.3.1", 30 * time.Hour},
}

// updatesSeedRequested reports the folder the fixture was given, or false when
// it was not asked for.
func updatesSeedRequested() (folder string, ok bool) {
	folder = strings.TrimSpace(os.Getenv(UpdatesSeedEnvVar))
	return folder, folder != ""
}

// seedUpdates makes a dev build a release behind two others, and reads their
// list once so the page has something to show before the first scheduled check.
//
// It also stands in for the update helper. The folder it was given becomes the
// controller's update folder and holds the marker an installed helper leaves, so
// the Update button is offered and a press writes its request where the suite
// can read it. Nothing answers that request: the suite plays the helper by
// writing a result.json of its own, which is how it makes an attempt end.
//
// That check is half a minute after start and the page is opened sooner; a
// status that says the list has not been read yet is true, and is not what the
// browser suite is there to look at. It does nothing unless the fixture was
// asked for.
func (c *Controller) seedUpdates(ctx context.Context) error {
	folder, ok := updatesSeedRequested()
	if !ok {
		return nil
	}
	binary := updates.AssetName(runtime.GOOS, runtime.GOARCH)
	if binary == "" {
		return fmt.Errorf("no release is published for %s/%s, so the fixture has none to offer; run it on linux or darwin",
			runtime.GOOS, runtime.GOARCH)
	}

	now := c.Now()
	listed := make([]map[string]any, 0, len(updatesSeedReleases))
	for _, r := range updatesSeedReleases {
		listed = append(listed, map[string]any{
			"tag_name":     r.tag,
			"html_url":     "https://example.invalid/releases/" + r.tag,
			"published_at": now.Add(-r.age).UTC().Format(time.RFC3339),
			"prerelease":   false,
			"draft":        false,
			// Complete for the system the controller runs on, which is the one
			// it is asked about.
			"assets": []map[string]string{{"name": "checksums.txt"}, {"name": binary}},
		})
	}
	body, err := json.Marshal(listed)
	if err != nil {
		return fmt.Errorf("writing the fixture's release list: %w", err)
	}

	// The client the release check and the capacity-demand events share, with
	// only its transport changed, so that whatever else leaves by it still does.
	client := *c.httpClient
	next := client.Transport
	if next == nil {
		next = http.DefaultTransport
	}
	client.Transport = releaseListFixture{body: body, next: next}
	c.httpClient = &client
	// Written before the loops start, so nothing is reading them.
	version.Version = updatesSeedVersion
	c.updateFolder = folder
	if err := writeFixtureMarker(folder, now); err != nil {
		return err
	}

	if err := c.checkForRelease(ctx); err != nil {
		return fmt.Errorf("reading the fixture's release list: %w", err)
	}
	c.log.Info("seeded the update fixture", "env", UpdatesSeedEnvVar,
		"update_folder", folder, "running", updatesSeedVersion)
	return nil
}

// writeFixtureMarker leaves the marker the installer writes last, which is all
// the controller looks for to call the helper installed.
func writeFixtureMarker(folder string, now time.Time) error {
	body, err := json.Marshal(channel.Marker{
		V: updates.WireVersion, Version: updatesSeedVersion,
		Binary: "/nonexistent/zoomies-fixture", InstalledAt: now.UTC(),
	})
	if err != nil {
		return fmt.Errorf("writing the fixture's helper marker: %w", err)
	}
	if err := os.WriteFile(filepath.Join(folder, channel.MarkerFile), body, 0o600); err != nil {
		return fmt.Errorf("writing the fixture's helper marker into %s, which the browser suite makes before it starts the controller: %w", folder, err)
	}
	return nil
}

// releaseListFixture answers the request for the release list from a list made
// once, and sends every other request on to the transport the controller had.
type releaseListFixture struct {
	body []byte
	next http.RoundTripper
}

func (f releaseListFixture) RoundTrip(r *http.Request) (*http.Response, error) {
	if r.URL.String() != releaseListURL {
		return f.next.RoundTrip(r)
	}
	return &http.Response{
		StatusCode: http.StatusOK,
		Status:     "200 OK",
		Header:     http.Header{"Content-Type": []string{"application/json"}},
		Body:       io.NopCloser(bytes.NewReader(f.body)),
		Request:    r,
	}, nil
}

package controller

import (
	"context"
	"net/http"
	"os"
	"path/filepath"
	"slices"
	"strconv"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/version"
)

// A fixture that changes the version a controller reports must be something a
// real controller cannot be talked into by a variable that was left set, so it
// is inert until it is asked for -- and an empty value is not asking.
func TestTheUpdatesFixtureDoesNothingUntilItIsAskedFor(t *testing.T) {
	for name, prepare := range map[string]func(t *testing.T){
		"the variable is not set": func(t *testing.T) {
			t.Setenv(UpdatesSeedEnvVar, "")
			if err := os.Unsetenv(UpdatesSeedEnvVar); err != nil {
				t.Fatal(err)
			}
		},
		"the variable is empty": func(t *testing.T) { t.Setenv(UpdatesSeedEnvVar, "") },
		"the variable is blank": func(t *testing.T) { t.Setenv(UpdatesSeedEnvVar, "  ") },
	} {
		t.Run(name, func(t *testing.T) {
			h := newHarness(t)
			withVersion(t, "dev")
			h.inMode("manual")
			client := h.c.httpClient
			prepare(t)

			if err := h.c.seedUpdates(h.ctx); err != nil {
				t.Fatalf("seedUpdates: %v", err)
			}

			if version.Version != "dev" {
				t.Errorf("version = %q, want the build's own", version.Version)
			}
			if h.c.httpClient != client {
				t.Error("the controller's HTTP client was replaced although the fixture was not asked for")
			}
			if h.c.latestRelease() != nil {
				t.Error("a release check ran although the fixture was not asked for")
			}
		})
	}
}

// The binary the browser suite drives is a dev build, which no comparison
// accepts, so the fixture has to make it a build that is behind a release and
// give it a release to be behind -- and read the list itself, because the first
// scheduled read is half a minute after start and the page is opened sooner.
func TestTheUpdatesFixtureMakesTheBuildBehindARelease(t *testing.T) {
	h := newHarness(t)
	withVersion(t, "dev")
	h.inMode("manual")
	t.Setenv(UpdatesSeedEnvVar, t.TempDir())

	if err := h.c.seedUpdates(h.ctx); err != nil {
		t.Fatalf("seedUpdates: %v", err)
	}

	got := h.status()
	if got.Running != (UpdatesRunning{Version: "1.3.0", Release: true}) {
		t.Errorf("running = %+v, want 1.3.0 from a release", got.Running)
	}
	if got.Latest == nil || got.Latest.Tag != "v1.3.2" || got.Latest.URL != "https://example.invalid/releases/v1.3.2" {
		t.Fatalf("latest = %+v, want v1.3.2 and the https page its notes are on", got.Latest)
	}
	if got.Target == nil || got.Target.Tag != "v1.3.2" || !got.Target.Newer || got.Target.DueAt != nil {
		t.Errorf("target = %+v, want v1.3.2, newer, with no due time because manual waits for a person", got.Target)
	}
	if got.CheckedAt == nil {
		t.Error("no list was read, so the page opens on a status that says it has not read one")
	}
	if !strings.HasPrefix(got.Reason, "Available: v1.3.2 is newer than the v1.3.0 running now") {
		t.Errorf("reason = %q, want the sentence for a manual target that is ahead", got.Reason)
	}
}

// The two releases are not arbitrary: v1.3.1 has been public for longer than a
// soak and v1.3.2 for less, which is the case the design uses to show what
// auto's wait costs. If either were dated otherwise the fixture would stop
// showing it, and nothing else would notice.
func TestTheUpdatesFixtureHoldsAutoBackAndSaysWhyThroughTheNewerRelease(t *testing.T) {
	h := newHarness(t)
	withVersion(t, "dev")
	// A frozen clock, because the sentence counts whole hours and the fixture is
	// dated from the moment it is made.
	now := time.Date(2026, time.October, 8, 12, 0, 0, 0, time.UTC)
	h.c.clock = func() time.Time { return now }
	h.inMode("auto")
	t.Setenv(UpdatesSeedEnvVar, t.TempDir())

	if err := h.c.seedUpdates(h.ctx); err != nil {
		t.Fatalf("seedUpdates: %v", err)
	}

	got := h.status()
	want := "Waiting: v1.3.2 has been public for 6 hours and auto waits for 24; it can be taken in 18 hours. " +
		"It replaced v1.3.1, which is skipped, and a newer release would start the wait again."
	if got.Reason != want {
		t.Errorf("reason = %q, want %q", got.Reason, want)
	}
	if got.Target == nil || got.Target.DueAt == nil || !got.Target.DueAt.Equal(now.Add(18*time.Hour)) {
		t.Errorf("target = %+v, want v1.3.2 due 18 hours from now", got.Target)
	}

	// The sentence is the same whatever age v1.3.1 is, so the ages are held here:
	// it has been public for more than the soak, which is why it is the release
	// that the newer one cost its turn, and v1.3.2 for less.
	age := map[string]time.Duration{}
	for _, r := range h.c.latestRelease().Releases {
		age[r.Tag] = now.Sub(r.PublishedAt)
	}
	if age["v1.3.1"] <= 24*time.Hour || age["v1.3.2"] >= 24*time.Hour || age["v1.3.1"] <= age["v1.3.2"] {
		t.Errorf("ages = %v, want v1.3.1 older than the 24h soak and v1.3.2 younger than it", age)
	}
}

// The browser suite presses Update, and the controller refuses to ask for an
// update unless a helper's marker is in its update folder. The fixture has no
// helper, so it has to stand one in at the folder it was given, and send the
// controller's requests there: a request written anywhere else would be one
// the suite cannot answer.
func TestTheUpdatesFixtureStandsInAHelperAtTheFolderItWasGiven(t *testing.T) {
	h := newHarness(t)
	withVersion(t, "dev")
	h.inMode("manual")
	folder := t.TempDir()
	t.Setenv(UpdatesSeedEnvVar, folder)

	if err := h.c.seedUpdates(h.ctx); err != nil {
		t.Fatalf("seedUpdates: %v", err)
	}

	if got, ok := h.c.updateDir(); !ok || got != folder {
		t.Errorf("updateDir = %q, %v, want %q: requests must go where the suite will read them", got, ok, folder)
	}
	if got := h.status().Helper; got.State != HelperReady || got.InstallCommand != "" {
		t.Errorf("helper = %+v, want ready with nothing to install", got)
	}
	view, err := h.c.RequestControllerUpdate(h.ctx, UpdateActor{ID: "usr_e2e", Name: "e2e"}, "v1.3.2")
	if err != nil {
		t.Fatalf("RequestControllerUpdate: %v", err)
	}
	if view.Controller == nil || view.Controller.State != "requested" || view.Controller.To != "v1.3.2" {
		t.Errorf("controller = %+v, want a requested attempt for v1.3.2", view.Controller)
	}
	if _, err := os.Stat(filepath.Join(folder, "request.json")); err != nil {
		t.Errorf("the request was not written into the fixture's folder: %v", err)
	}
}

// The client it replaces is also the one capacity-demand events leave by, so
// whatever the fixture does not know about has to go where it would have gone.
func TestTheUpdatesFixtureOnlyAnswersTheReleaseList(t *testing.T) {
	h := newHarness(t)
	withVersion(t, "dev")
	h.inMode("manual")
	var asked []string
	h.c.httpClient = &http.Client{Transport: roundTripFunc(func(r *http.Request) *http.Response {
		asked = append(asked, r.URL.String())
		return jsonResponse(http.StatusOK, `{}`)
	})}
	t.Setenv(UpdatesSeedEnvVar, t.TempDir())

	if err := h.c.seedUpdates(h.ctx); err != nil {
		t.Fatalf("seedUpdates: %v", err)
	}
	if len(asked) != 0 {
		t.Fatalf("the replaced client was asked for %v; the list is the fixture's to answer", asked)
	}

	const other = "https://hooks.example.invalid/capacity"
	resp, err := h.c.httpClient.Post(other, "application/json", strings.NewReader(`{}`))
	if err != nil {
		t.Fatalf("a request the fixture does not know: %v", err)
	}
	resp.Body.Close()
	if !slices.Equal(asked, []string{other}) {
		t.Errorf("the replaced client was asked for %v, want exactly %s", asked, other)
	}
}

// The demo fleet is what refuses to run on a real one, so the fixture rides on
// it: a controller that is not a demo never has its version rewritten, whatever
// is left in its environment.
func TestTheUpdatesFixtureStartsWithTheDemoFleetAndNowhereElse(t *testing.T) {
	for _, tc := range []struct {
		name    string
		demo    bool
		version string
	}{
		{"with the demo fleet", true, "1.3.0"},
		{"without the demo fleet", false, "dev"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			withVersion(t, "dev")
			h.inMode("manual")
			t.Setenv(SeedEnvVar, strconv.FormatBool(tc.demo))
			t.Setenv(UpdatesSeedEnvVar, t.TempDir())

			ctx, cancel := context.WithCancel(context.Background())
			defer cancel()
			if err := h.c.Start(ctx); err != nil {
				t.Fatalf("Start: %v", err)
			}
			stopCtx, stopCancel := context.WithTimeout(context.Background(), 5*time.Second)
			defer stopCancel()
			if err := h.c.Stop(stopCtx); err != nil {
				t.Fatalf("Stop: %v", err)
			}

			if version.Version != tc.version {
				t.Errorf("version = %q after Start, want %q", version.Version, tc.version)
			}
		})
	}
}

package controller

import (
	"context"
	"log/slog"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
)

// PATCH /settings used to write the level into the configuration struct and
// nothing else, so the settings page said "debug" while the process went on
// logging at info. The level's gate is moved with the snapshot now.
func TestASettingChangedAtRuntimeMovesTheLogLevel(t *testing.T) {
	h := newHarness(t)
	level := new(slog.LevelVar)
	level.Set(slog.LevelInfo)
	h.c.logLevel = level

	h.c.UpdateConfig(func(c *config.Config) { c.Log.Level = "debug" })

	if level.Level() != slog.LevelDebug {
		t.Fatalf("the process is still logging at %s after log.level was set to debug", level.Level())
	}
	if got := h.c.Config().Log.Level; got != "debug" {
		t.Fatalf("Config().Log.Level = %q, want debug", got)
	}
	// Copy on write: the configuration the controller was built with is left
	// as it was, which is what makes reading it from every loop safe while
	// this write happens.
	if h.cfg.Log.Level == "debug" {
		t.Fatal("UpdateConfig wrote into the caller's configuration instead of publishing a new snapshot")
	}
}

// The scheduler's ticker was built once from the interval at startup, so an
// operator who set scheduler.interval to 2s to watch a scale-up was told it
// had worked and saw nothing change until a restart.
func TestANewSchedulerIntervalTakesEffectWithoutARestart(t *testing.T) {
	h := newHarness(t)
	h.cfg.Scheduler.Interval = time.Hour
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	if err := h.c.Start(ctx); err != nil {
		t.Fatalf("Start: %v", err)
	}
	t.Cleanup(func() { h.c.Stop(context.Background()) })
	eventually(t, 2*time.Second, "the first reconcile pass", func() bool {
		return h.c.passes.Load() >= 1
	})

	h.c.UpdateConfig(func(c *config.Config) { c.Scheduler.Interval = 20 * time.Millisecond })

	// The change itself nudges one pass; anything beyond that within a second
	// can only be the retuned timer, since the old one is an hour out.
	base := h.c.passes.Load()
	eventually(t, 3*time.Second, "passes on the new interval", func() bool {
		return h.c.passes.Load() >= base+5
	})
}

// The same for the poller, whose loop has no nudge of its own: the change
// wakes it so the timer is rebuilt at once rather than after one more hour.
func TestANewPollIntervalTakesEffectWithoutARestart(t *testing.T) {
	h := newHarness(t)
	h.cfg.GitHub.PollFallback = true
	h.cfg.GitHub.PollInterval = time.Hour
	h.cfg.Scheduler.Interval = time.Hour
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	if err := h.c.Start(ctx); err != nil {
		t.Fatalf("Start: %v", err)
	}
	t.Cleanup(func() { h.c.Stop(context.Background()) })

	h.c.UpdateConfig(func(c *config.Config) { c.GitHub.PollInterval = 20 * time.Millisecond })

	eventually(t, 3*time.Second, "poller sweeps on the new interval", func() bool {
		return h.c.polls.Load() >= 3
	})
}

// A channel send wakes one receiver, so with a provider enabled the machine
// loop and the poller used to compete for the single "settings changed" token.
// Whichever lost stayed on its old interval, and which one lost was down to
// the scheduler. Each loop owns its own flag now; the test runs several
// controllers so that a shared token cannot pass by luck.
func TestANewPollIntervalReachesThePollerEvenWithAProviderEnabled(t *testing.T) {
	for i := 0; i < 5; i++ {
		h := newHarness(t)
		h.cfg.GitHub.PollFallback = true
		h.cfg.GitHub.PollInterval = time.Hour
		h.cfg.Scheduler.Interval = time.Hour
		h.cfg.Provider.Enabled = true
		h.cfg.Provider.Interval = time.Hour
		ctx, cancel := context.WithCancel(context.Background())
		if err := h.c.Start(ctx); err != nil {
			cancel()
			t.Fatalf("Start: %v", err)
		}

		h.c.UpdateConfig(func(c *config.Config) { c.GitHub.PollInterval = 20 * time.Millisecond })

		eventually(t, 3*time.Second, "poller sweeps on the new interval", func() bool {
			return h.c.polls.Load() >= 3
		})
		cancel()
		h.c.Stop(context.Background())
	}
}

// Known-job recovery is the loop that spends the most installation quota, so
// an operator who raises github.poll_interval to relieve a rate limit needs it
// to notice. It built its ticker once and kept the startup interval until a
// restart, whether or not the fallback poller was on.
func TestANewPollIntervalReachesJobRecoveryWithoutARestart(t *testing.T) {
	h := newHarness(t)
	h.cfg.GitHub.PollInterval = time.Hour
	h.cfg.Scheduler.Interval = time.Hour
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	if err := h.c.Start(ctx); err != nil {
		t.Fatalf("Start: %v", err)
	}
	t.Cleanup(func() { h.c.Stop(context.Background()) })

	// The loop sweeps once as it starts, before any interval applies.
	eventually(t, 3*time.Second, "the startup sweep", func() bool {
		return h.c.recoveries.Load() >= 1
	})
	base := h.c.recoveries.Load()

	h.c.UpdateConfig(func(c *config.Config) { c.GitHub.PollInterval = 20 * time.Millisecond })

	eventually(t, 3*time.Second, "job recovery sweeps on the new interval", func() bool {
		return h.c.recoveries.Load() >= base+3
	})
}

// The behavioural tests above cannot force the scheduler to hand the shared
// token to the wrong loop, so this one asks the question directly: a change
// leaves a wake waiting for every loop, not one of them.
func TestASettingsChangeLeavesAWakeForEveryLoopThatTunesFromIt(t *testing.T) {
	h := newHarness(t)
	h.c.UpdateConfig(func(c *config.Config) { c.GitHub.PollInterval = time.Minute })

	for name, wake := range map[string]chan struct{}{
		"poller":       h.c.pollSettingsChanged,
		"job recovery": h.c.recoverySettingsChanged,
		"machines":     h.c.machineSettingsChanged,
	} {
		select {
		case <-wake:
		default:
			t.Errorf("the %s loop was not woken by a settings change", name)
		}
	}
}

package controller

import (
	"slices"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// A containerised agent that cannot hand runners the shared folder keeps no
// tool cache, which costs something only to a pool that keeps one: that is
// when the Problems panel says so, naming the host and the fix, and not
// before.
func TestAnUnmountedSharedFolderIsAProblemOnlyForAPoolThatKeepsAToolCache(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	p := h.pool(inst, "linux")
	host := h.host("zoomies-in-compose")
	host.BackendInfo = store.HostBackends{{
		Kind: store.BackendDocker, Available: true,
		SharedFolder: "the shared folder /var/lib/zoomies/shared is not mounted into this container from the host",
	}}
	if err := h.st.UpdateHost(h.ctx, host); err != nil {
		t.Fatalf("UpdateHost: %v", err)
	}
	if slices.Contains(h.problemCodes(), "host.shared_folder_unmounted") {
		t.Fatal("raised with no pool keeping a tool cache")
	}

	p.Cache = store.CacheConfig{Enabled: true, Tools: true, Scope: store.CacheScopePool}
	if err := h.st.UpdatePool(h.ctx, p); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	got := h.problem(t, "host.shared_folder_unmounted")
	if got.TargetID != host.ID || got.Fix == "" {
		t.Errorf("problem = %+v, want it on the host with a fix", got)
	}
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"strings"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// modeOf reads one of the two switches. An unset or unknown value is off: a
// setting this build has not heard of must not turn a feature on.
func modeOf(v string) string {
	switch v {
	case scheduler.SizeShadow, scheduler.SizeOn:
		return v
	}
	return scheduler.SizeOff
}

// sizeMode is scheduler.size_routing: whether jobs are classed, and whether
// they are sent anywhere on the strength of it.
func (c *Controller) sizeMode() string { return modeOf(c.cfg().Scheduler.SizeRouting) }

// autoMode is scheduler.auto_pools.
func (c *Controller) autoMode() string { return modeOf(c.cfg().Scheduler.AutoPools) }

// AutoPoolsMode is scheduler.auto_pools as the controller reads it, for the
// handlers that must refuse what the reconciler would only undo.
func (c *Controller) AutoPoolsMode() string { return c.autoMode() }

// TracksClasses reports whether hosts are being given a size class, which is
// when a host's size tag has to be one.
func (c *Controller) TracksClasses() bool { return c.tracksClasses() }

// tracksClasses reports whether hosts are given a class at all: either switch
// being on, or being watched, is a reason to know what class each host is in,
// and neither is a reason to write a column nobody reads.
func (c *Controller) tracksClasses() bool {
	return c.sizeMode() != scheduler.SizeOff || c.autoMode() != scheduler.SizeOff
}

// sizeConfig is the settings the pure functions cannot read, gathered for them.
func (c *Controller) sizeConfig() scheduler.SizeConfig {
	cfg := c.cfg()
	s, r := cfg.Scheduler, cfg.Runners
	return scheduler.SizeConfig{
		SmallMax:     scheduler.HostLimit{CPUs: s.SizeSmallMaxCPUs, MemoryMB: s.SizeSmallMaxMemoryMB},
		MediumMax:    scheduler.HostLimit{CPUs: s.SizeMediumMaxCPUs, MemoryMB: s.SizeMediumMaxMemoryMB},
		Small:        store.RunnerSize{CPUs: r.SmallCPUs, MemoryMB: r.SmallMemoryMB},
		Medium:       store.RunnerSize{CPUs: r.MediumCPUs, MemoryMB: r.MediumMemoryMB},
		Large:        store.RunnerSize{CPUs: r.LargeCPUs, MemoryMB: r.LargeMemoryMB},
		Hold:         s.SizeClassHold,
		DefaultClass: store.SizeClass(s.SizeDefaultClass),
		FallbackWait: s.SizeFallbackWait,
	}
}

// routable is a job as the scheduler should claim it: sent to its class while
// size routing is on, and exactly as it always was otherwise. The class is on
// the row either way -- the Jobs page shows it while it is only being watched
// -- so this is where "watching" is kept from becoming "acting", and every
// place that asks which pool a job belongs to asks through it.
func (c *Controller) routable(j *store.Job) *store.Job {
	if j == nil || j.RoutedClass == "" || c.sizeMode() == scheduler.SizeOn {
		return j
	}
	cp := *j
	cp.RoutedClass = ""
	return &cp
}

// routableJobs is routable over a listing, copying only the jobs that need it.
func (c *Controller) routableJobs(jobs []*store.Job) []*store.Job {
	if c.sizeMode() == scheduler.SizeOn {
		return jobs
	}
	out := make([]*store.Job, len(jobs))
	for i, j := range jobs {
		out[i] = c.routable(j)
	}
	return out
}

// bestPool is scheduler.BestPool for a job read from the store.
func (c *Controller) bestPool(pools []*store.Pool, j *store.Job) *store.Pool {
	return scheduler.BestPool(pools, c.routable(j))
}

// sizeOnArrival works out the class a job joins the queue in, before it is
// claimed, so the claim can use it. It writes nothing: it fills the size fields
// on the job in hand and returns what ApplyJob has to stamp once the job has a
// row, or nil when there is nothing to stamp.
//
// A job that is already known keeps whatever classed it first, and the claim
// reads that, so a later delivery for the same job cannot send it somewhere
// else than its first did. That holds for every delivery and not only for a
// queued one: the in_progress and completed deliveries of a job that a runner of
// its class took are claimed afresh too, and a claim made without the route would
// credit the job to whichever pool of its labels sorts first, so the Jobs page,
// the per-pool counters and the usage history would all name a pool the job
// never ran in. A job first seen already running was answered by whatever is
// running it, and has no class to be routed to.
//
// A job that no pool of this fleet answers is not this fleet's work -- a job for
// GitHub's own runners, or another provider's, or one whose labels name nothing
// here -- and is not classed: every such job in every repository the installation
// covers would otherwise carry a class badge, a line on its timeline and a count
// in the metric, for a decision nobody was making about it.
func (c *Controller) sizeOnArrival(ctx context.Context, job *store.Job, pools []*store.Pool) *store.JobClassing {
	mode := c.sizeMode()
	if mode == scheduler.SizeOff {
		return nil
	}
	existing, err := c.st.GetJobByGitHubID(ctx, job.GitHubJobID)
	switch {
	case err == nil:
		job.SizeClass, job.SizeReason, job.SizeBasis, job.SizeFloorMB = existing.SizeClass, existing.SizeReason, existing.SizeBasis, existing.SizeFloorMB
		job.RoutedClass, job.RoutedNote = existing.RoutedClass, existing.RoutedNote
		if existing.SizeBasis != "" {
			return nil
		}
		// Known, but from before size routing was on: classed now.
	case !errors.Is(err, store.ErrNotFound):
		c.log.Warn("could not look up a job before classing it; it is claimed without a class", "github_job_id", job.GitHubJobID, "error", err)
		return nil
	}
	if job.State != store.JobQueued && job.State != store.JobWaiting {
		return nil
	}
	if c.bestPool(pools, job) == nil {
		return nil
	}

	cl := c.sizeConfig().AtQueue(job.Labels, c.sizePinFor(ctx, job.Repo, job.Workflow, job.JobName), c.keptClass(ctx, job.Repo, job.Workflow, job.JobName))
	classing := store.JobClassing{Class: cl.Class, Reason: cl.Reason, Basis: cl.Basis, FloorMB: cl.FloorMB, Route: mode == scheduler.SizeOn}
	job.SizeClass, job.SizeReason, job.SizeBasis, job.SizeFloorMB = cl.Class, cl.Reason, cl.Basis, cl.FloorMB
	job.RoutedClass = ""
	if classing.Route {
		job.RoutedClass = cl.Class
	}
	return &classing
}

// stampSize writes what sizeOnArrival decided, and returns the job as it is
// stored. A failure costs the job its class and nothing else: it is claimed
// and run as it always was.
func (c *Controller) stampSize(ctx context.Context, saved *store.Job, classing *store.JobClassing) *store.Job {
	if classing == nil || saved == nil {
		return saved
	}
	stamped, wrote, err := c.st.StampJobClass(ctx, saved.ID, *classing)
	if err != nil {
		c.log.Warn("could not record a job's size class", "job", saved.ID, "error", err)
		return saved
	}
	// Counted by the delivery that classed the job: the webhook and the poller
	// both see a queued job, and the second finds it already stamped, as does a
	// late delivery for a job that has since started and was never classed.
	if wrote {
		c.metrics.jobsSized.WithLabelValues(stamped.SizeBasis, string(stamped.SizeClass), c.sizeMode()).Inc()
	}
	return stamped
}

// sizePinFor is the pin that applies to a job, nil for none. A failed read
// answers as none, and says so: a class worked out without the pin is wrong in
// a way an operator can see and undo, where a job refused for it is not.
func (c *Controller) sizePinFor(ctx context.Context, repo, workflow, job string) *store.SizePin {
	pin, err := c.st.SizePinFor(ctx, repo, workflow, job)
	if err != nil {
		if !errors.Is(err, store.ErrNotFound) {
			c.log.Warn("could not read the size pins; classing a job without them", "repo", repo, "error", err)
		}
		return nil
	}
	return pin
}

// keptClass is the class kept from a job's earlier runs, nil for a job that has
// none.
func (c *Controller) keptClass(ctx context.Context, repo, workflow, job string) *store.JobClass {
	kept, err := c.st.GetJobClass(ctx, repo, workflow, job)
	if err != nil {
		if !errors.Is(err, store.ErrNotFound) {
			c.log.Warn("could not read a job's kept class", "repo", repo, "job_name", job, "error", err)
		}
		return nil
	}
	return kept
}

// sizeMessage is the line the job's timeline carries for how it was classed.
func (c *Controller) sizeMessage(j *store.Job) string {
	msg := fmt.Sprintf("classed %s because %s", j.SizeClass, j.SizeReason)
	if j.RoutedClass == "" {
		msg += "; size routing is only watching, so nothing was sent anywhere on its account"
	}
	return msg
}

// refreshJobClass works a job's class out again from its runs, when one of them
// has just finished, and keeps the answer for the next time the job is queued.
// Only a measured run is evidence, and an unmeasured one changes nothing.
//
// The pin and the job's own labels are left out of this on purpose: the kept
// class is what the runs say, so that removing a pin hands the job back to its
// history and not to a default.
func (c *Controller) refreshJobClass(ctx context.Context, j *store.Job) {
	if j == nil || j.Repo == "" || c.sizeMode() == scheduler.SizeOff || IsDemoID(j.InstallationID) {
		return
	}
	if j.PeakCPUs <= 0 && j.PeakMemoryMB <= 0 && !j.OOMKilled {
		return
	}
	now := c.Now()
	runs, err := c.st.JobClassHistory(ctx, j.Repo, j.Workflow, j.JobName, now.Add(-scheduler.ClassWindow), store.JobClassHistoryLimit)
	if err != nil {
		c.log.Warn("could not read a job's history to class it", "job", j.ID, "error", err)
		return
	}
	cl := c.sizeConfig().Classify(scheduler.ClassifyInput{Runs: runs, Current: c.keptClass(ctx, j.Repo, j.Workflow, j.JobName), Now: now})
	if cl.Basis != store.SizeBasisHistory {
		return
	}
	kept := &store.JobClass{Repo: j.Repo, Workflow: j.Workflow, JobName: j.JobName,
		Class: cl.Class, Reason: cl.Reason, Basis: cl.Basis, FloorMB: cl.FloorMB, Runs: cl.Runs}
	previous, err := c.st.PutJobClass(ctx, kept)
	if err != nil {
		c.log.Warn("could not keep a job's class", "job", j.ID, "error", err)
		return
	}
	if previous != cl.Class {
		key := strings.Join([]string{j.Repo, j.Workflow, j.JobName}, " / ")
		from := "no class"
		if previous != "" {
			from = string(previous)
		}
		c.systemAudit(ctx, "size_class.move", "job_class", key,
			map[string]any{"class": string(previous)},
			map[string]any{"class": string(cl.Class), "cause": fmt.Sprintf("%s was in %s, and is now %s because %s", j.JobName, from, cl.Class, cl.Reason)})
	}
}

// stampJobRan records the class of the host that took a job, once.
func (c *Controller) stampJobRan(ctx context.Context, j *store.Job, runner *store.Runner) {
	if j == nil || j.RunnerID == "" || j.RanClass != "" || !c.tracksClasses() || IsDemoID(j.InstallationID) {
		return
	}
	if runner == nil || runner.ID != j.RunnerID {
		r, err := c.st.GetRunner(ctx, j.RunnerID)
		if err != nil {
			return
		}
		runner = r
	}
	host, err := c.st.GetHost(ctx, runner.HostID)
	if err != nil {
		return
	}
	class, _ := host.EffectiveSizeClass()
	if !class.Valid() {
		return
	}
	stamped, wrote, err := c.st.StampJobRan(ctx, j.ID, class)
	if err != nil {
		c.log.Warn("could not record the class of the host that took a job", "job", j.ID, "error", err)
		return
	}
	if j.RanClass == "" {
		j.RanClass = stamped.RanClass
	}
	// Counted by the delivery that wrote it, because the webhook and the poller
	// both see the job start and the second finds it already recorded.
	if wrote && j.SizeClass.Valid() {
		c.metrics.jobsRan.WithLabelValues(string(j.SizeClass), string(stamped.RanClass), c.sizeMode()).Inc()
	}
}

// ReclassifyQueuedJobs puts the jobs waiting for a runner back through the
// classification, for the jobs of one repository, one workflow or one job. It is
// what makes an operator's pin reach the queue and not only the jobs that arrive
// afterwards: a pin made to fix a job that is stuck in the wrong class has to fix
// that one. It returns how many jobs changed class.
func (c *Controller) ReclassifyQueuedJobs(ctx context.Context, repo, workflow, jobName string) (int, error) {
	// A pin is what the label advice leaves a job alone for, whichever way it
	// changed.
	c.forgetLabelAdvice()
	if c.sizeMode() == scheduler.SizeOff {
		return 0, nil
	}
	return c.reclassifyWaiting(ctx, func(j *store.Job) bool {
		return strings.EqualFold(j.Repo, repo) &&
			(workflow == "" || j.Workflow == workflow) && (jobName == "" || j.JobName == jobName)
	})
}

// ReclassifyWaitingJobs does it for every job waiting for a runner, which is what
// a change to scheduler.size_routing has to do. The switch is read as each job
// arrives, so without this a job that was already waiting when routing was turned
// on would have no route for as long as it waited and be placed as it always was,
// and one that was waiting when routing was turned off would go on saying it had
// been sent to a class. It returns how many jobs changed.
func (c *Controller) ReclassifyWaitingJobs(ctx context.Context) (int, error) {
	c.forgetLabelAdvice()
	return c.reclassifyWaiting(ctx, func(*store.Job) bool { return true })
}

// reclassifyWaiting works out again, as it would be if it arrived now, the class
// of each job waiting for a runner that want selects.
//
// A job is touched only if a pool of this fleet answers it, as when it arrived: a
// pin for a repository must not stamp a class on its jobs for GitHub's own
// runners, and a change of mode would otherwise do that to every one in the
// queue. With routing off there is no class to send a job to, so what is done is
// to take back the route it had. The scheduler already ignores one while routing
// is not on; this is so that the row, and the pool the Jobs page lists the job
// under, say what the scheduler does. The job keeps its class, which is a record
// of what it was taken to need and not an instruction.
func (c *Controller) reclassifyWaiting(ctx context.Context, want func(*store.Job) bool) (int, error) {
	mode := c.sizeMode()
	queued, err := c.st.ListQueuedJobs(ctx)
	if err != nil {
		return 0, err
	}
	// Jobs held for a deployment review are classed when they arrive, and a pin
	// made while they wait for an approver is what they should be queued by.
	held, err := c.st.ListHeldJobs(ctx)
	if err != nil {
		return 0, err
	}
	queued = append(queued, held...)
	pools, err := c.st.ListPools(ctx)
	if err != nil {
		return 0, err
	}
	cfg := c.sizeConfig()
	// A queue is mostly the same few jobs over and over -- a matrix, a busy
	// repository -- so each pin and each kept class is read once.
	type key struct{ repo, workflow, job string }
	pins, kept := map[key]*store.SizePin{}, map[key]*store.JobClass{}
	classOf := func(j *store.Job) scheduler.Classification {
		k := key{j.Repo, j.Workflow, j.JobName}
		pin, ok := pins[k]
		if !ok {
			pin = c.sizePinFor(ctx, j.Repo, j.Workflow, j.JobName)
			pins[k] = pin
		}
		class, ok := kept[k]
		if !ok {
			class = c.keptClass(ctx, j.Repo, j.Workflow, j.JobName)
			kept[k] = class
		}
		return cfg.AtQueue(j.Labels, pin, class)
	}
	changed := 0
	// The pools of the classes the jobs were put in have demand they did not have,
	// whether or not the loop got to the end of the queue.
	defer func() {
		if changed > 0 {
			c.Nudge()
		}
	}()
	for _, j := range queued {
		if (j.State != store.JobQueued && j.State != store.JobWaiting) || !want(j) || c.bestPool(pools, j) == nil {
			continue
		}
		var moved bool
		var err error
		if mode == scheduler.SizeOff {
			moved, err = c.st.ClearJobRoute(ctx, j.ID)
		} else {
			cl := classOf(j)
			moved, err = c.st.SetQueuedJobClass(ctx, j.ID, store.JobClassing{
				Class: cl.Class, Reason: cl.Reason, Basis: cl.Basis, FloorMB: cl.FloorMB, Route: mode == scheduler.SizeOn,
			})
		}
		if err != nil {
			return changed, err
		}
		if !moved {
			continue
		}
		changed++
		if updated, err := c.st.GetJob(ctx, j.ID); err == nil {
			updated = c.reclaim(ctx, pools, updated)
			msg := "size routing was turned off, so the job is no longer sent to the pool of a class and is placed by its labels alone"
			if mode != scheduler.SizeOff {
				msg = c.sizeMessage(updated)
			}
			c.appendJobEvent(ctx, updated, store.JobEventSized, msg)
			c.publishJob(ctx, updated)
		}
	}
	return changed, nil
}

// sizeModeLoop puts the jobs already waiting through the classification again
// whenever scheduler.size_routing changes. It is a loop of its own, woken by
// UpdateConfig, because a queue can be long and the request that changed the
// setting should not wait for every job in it to be read; a wake that arrives
// while it works costs one more run, which starts from the mode as it then is.
func (c *Controller) sizeModeLoop(ctx context.Context) {
	for {
		select {
		case <-ctx.Done():
			return
		case <-c.sizeModeChanged:
		}
		n, err := c.ReclassifyWaitingJobs(ctx)
		switch {
		case err != nil && ctx.Err() == nil:
			c.log.Warn("could not put every job already waiting through size routing again; changing scheduler.size_routing again will try once more",
				"mode", c.sizeMode(), "changed", n, "error", err)
		case err == nil:
			c.log.Info("jobs already waiting were put through size routing again", "mode", c.sizeMode(), "changed", n)
		}
	}
}

// reclaim points a job whose route has just changed at the pool that claims it
// now, and returns the job as it is stored. The scheduler does not need it --
// every pass works the claim out afresh -- but the Jobs page and a pool's queue
// count read the row, and they would otherwise go on listing the job under the
// pool it was sent away from.
func (c *Controller) reclaim(ctx context.Context, pools []*store.Pool, j *store.Job) *store.Job {
	var poolID string
	if p := c.bestPool(pools, j); p != nil {
		poolID = p.ID
	}
	moved, err := c.st.SetJobClaim(ctx, j.ID, poolID)
	if err != nil {
		c.log.Warn("could not point a re-routed job at the pool that claims it", "job", j.ID, "error", err)
		return j
	}
	if !moved {
		return j
	}
	if fresh, err := c.st.GetJob(ctx, j.ID); err == nil {
		return fresh
	}
	return j
}

// appendJobEvent adds a line to a job's timeline from the controller itself.
func (c *Controller) appendJobEvent(ctx context.Context, j *store.Job, kind store.JobEventKind, message string) {
	e := &store.JobEvent{JobID: j.ID, Kind: kind, Source: "controller", Message: message, At: c.Now()}
	if err := c.st.AppendJobEvent(ctx, e); err != nil {
		c.log.Warn("could not record a job timeline entry", "job", j.ID, "kind", kind, "error", err)
	}
}

// routeFallbacks sends the jobs the plan found stuck to another class, and says
// so on each one's timeline. It acts only while size routing is on and this
// controller may act, and it writes the routing only: the next pass claims the
// job for the pool of its new class, so a move costs one pass and no second
// scheduling decision is made outside the scheduler.
func (c *Controller) routeFallbacks(ctx context.Context, snap scheduler.Snapshot, plan scheduler.Plan) {
	if c.sizeMode() != scheduler.SizeOn || !c.mayAct() {
		return
	}
	moves := scheduler.Fallbacks(scheduler.RoutingInput{
		Now: snap.Now, Pools: snap.Pools, Hosts: snap.Hosts, Jobs: snap.Jobs, Plan: plan, Config: c.sizeConfig(),
	})
	if len(moves) == 0 {
		return
	}
	for _, m := range moves {
		moved, err := c.st.SetJobRouted(ctx, m.Job.ID, m.From, m.To, m.Note)
		if err != nil {
			c.log.Warn("could not send a job to another size class", "job", m.Job.ID, "to", m.To, "error", err)
			continue
		}
		if !moved {
			continue
		}
		if updated, err := c.st.GetJob(ctx, m.Job.ID); err == nil {
			updated = c.reclaim(ctx, snap.Pools, updated)
			c.appendJobEvent(ctx, updated, store.JobEventSized, fmt.Sprintf("sent to the %s pool: %s", m.To, m.Note))
			c.publishJob(ctx, updated)
		}
		c.metrics.jobsRerouted.WithLabelValues(string(m.From), string(m.To)).Inc()
	}
	// The pools of the classes the jobs were sent to have demand they did not
	// have a moment ago.
	c.Nudge()
}

// systemAudit records something the controller did on its own, under the system
// identity -- the one the throttle's and the capacity receiver's rows carry, so
// that an audit filtered by actor finds all of them -- with the same row an
// operator's action leaves.
func (c *Controller) systemAudit(ctx context.Context, action, targetKind, targetID string, before, after any) {
	_ = auth.NewAuditor(c.st, c.bus, c.log).Record(ctx, auth.SystemIdentity(), action, targetKind, targetID, before, after)
}

package controller

import (
	"context"
	"fmt"
	"strings"
	"sync"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// HostSizeClassView says which size class a host is in and why, in the terms
// the Hosts page shows it.
type HostSizeClassView struct {
	// Class is the class in force: an operator's size tag where there is one, and
	// the class the host's measurements put it in otherwise.
	Class store.SizeClass `json:"class"`
	// Source is "tag" when an operator's tag decided it and "measured" when the
	// host's own CPUs and memory did.
	Source string `json:"source"`
	// Measured is what the host's measurements name right now, set only when it
	// is not the class in force: because a tag replaces it, or because a change
	// is being held back.
	Measured store.SizeClass `json:"measured,omitempty"`
	// Pending is a different class the measurements have named without a break
	// since PendingSince, and PendingUntil is when the host moves if they keep
	// doing so. The times are carried rather than written into Reason, so the
	// page can count down against the viewer's own clock.
	Pending      store.SizeClass `json:"pending,omitempty"`
	PendingSince *time.Time      `json:"pending_since,omitempty"`
	PendingUntil *time.Time      `json:"pending_until,omitempty"`
	// Reason is what put the host in Class, as a sentence.
	Reason string `json:"reason"`
}

// HostAutoPoolView says which automatic pool a host counts towards, or why it
// counts towards none.
type HostAutoPoolView struct {
	Counted bool `json:"counted"`
	// Pool is the pool's name, or under shadow the name it would have. PoolID is
	// empty until there is a pool.
	Pool   string `json:"pool,omitempty"`
	PoolID string `json:"pool_id,omitempty"`
	// Reason is, for a host that counts towards none, why, and ReasonCode the
	// stable form of the same thing.
	Reason     string `json:"reason,omitempty"`
	ReasonCode string `json:"reason_code,omitempty"`
}

// PoolAutoView is what is particular to a pool the controller keeps: what an
// operator has asked of it, and what the hosts in it give.
type PoolAutoView struct {
	// Key is the architecture and class the pool is kept for.
	Key   string          `json:"key"`
	Arch  string          `json:"arch"`
	Class store.SizeClass `json:"class"`
	// Warm, Cap and Paused are the operator's: runners to keep ready, the most
	// runners to allow however many slots the hosts give, and a pause. Zero is
	// none for the first two.
	Warm   int  `json:"warm"`
	Cap    int  `json:"cap"`
	Paused bool `json:"paused"`
	// Kept says whether the controller is keeping the pool now: automatic pools
	// are on, and it belongs to the installation they are kept for. A pool that is
	// not kept holds the figures it had, takes a pause the moment it is asked for,
	// and applies a cap or a warm count when it is kept again; and deleting it is
	// not undone by the next pass, because nothing will make it again.
	Kept bool `json:"kept"`
	// Hosts are the hosts that count towards the pool and Slots what they hold
	// between them, as of the last pass of the reconciler.
	Hosts   []string `json:"hosts"`
	Slots   int      `json:"slots"`
	Summary string   `json:"summary"`
}

// SizeClassLimits is what one class is: how large a host in it is, and how
// large a runner.
type SizeClassLimits struct {
	Class store.SizeClass `json:"class"`
	// Label is the runs-on label that asks for the class by name.
	Label string `json:"label"`
	// HostMaxCPUs and HostMaxMemoryMB are the most allocatable a host in the
	// class has; both are absent for the largest, which has no limit above.
	HostMaxCPUs     float64 `json:"host_max_cpus,omitempty"`
	HostMaxMemoryMB int64   `json:"host_max_memory_mb,omitempty"`
	RunnerCPUs      float64 `json:"runner_cpus"`
	RunnerMemoryMB  int64   `json:"runner_memory_mb"`
}

// AutoPoolsView is the state of size routing and of the pools the controller
// keeps, as GET /auto-pools returns it.
type AutoPoolsView struct {
	SizeRouting string `json:"size_routing"`
	AutoPools   string `json:"auto_pools"`
	// Installation is the target the pools belong to, and Problem says why there
	// is none. At is when the last pass ran, null before the first.
	Installation string                      `json:"installation,omitempty"`
	Problem      string                      `json:"problem,omitempty"`
	At           *time.Time                  `json:"at"`
	Pools        []AutoPoolSummary           `json:"pools"`
	Findings     []scheduler.AutoPoolFinding `json:"findings"`
	Skipped      []AutoPoolSkip              `json:"skipped"`
	Pending      []AutoPoolPending           `json:"pending"`
	Classes      []SizeClassLimits           `json:"classes"`
	DefaultClass store.SizeClass             `json:"default_class"`
	Hold         store.Duration              `json:"hold"`
	FallbackWait store.Duration              `json:"fallback_wait"`
	HostGrace    store.Duration              `json:"host_grace"`
}

// AutoPools reports the state of both switches and of the pools the controller
// keeps. It reads what the last pass found and does not run one.
func (c *Controller) AutoPools() AutoPoolsView {
	st := c.AutoPoolStatus()
	cfg := c.sizeConfig()
	out := AutoPoolsView{
		SizeRouting:  c.sizeMode(),
		AutoPools:    c.autoMode(),
		Installation: st.Installation,
		Problem:      st.Problem,
		Pools:        emptySlice(st.Pools),
		Findings:     emptySlice(st.Findings),
		Skipped:      emptySlice(st.Skipped),
		Pending:      emptySlice(st.Pending),
		DefaultClass: cfg.DefaultClass,
		Hold:         store.Duration(cfg.Hold),
		FallbackWait: store.Duration(cfg.FallbackWait),
		HostGrace:    store.Duration(c.cfg().Scheduler.AutoPoolsHostGrace),
	}
	if !st.At.IsZero() {
		at := st.At
		out.At = &at
	}
	for _, class := range store.SizeClasses() {
		run := cfg.Runner(class)
		limits := SizeClassLimits{Class: class, Label: class.Label(), RunnerCPUs: run.CPUs, RunnerMemoryMB: run.MemoryMB}
		switch class {
		case store.SizeSmall:
			limits.HostMaxCPUs, limits.HostMaxMemoryMB = cfg.SmallMax.CPUs, cfg.SmallMax.MemoryMB
		case store.SizeMedium:
			limits.HostMaxCPUs, limits.HostMaxMemoryMB = cfg.MediumMax.CPUs, cfg.MediumMax.MemoryMB
		}
		out.Classes = append(out.Classes, limits)
	}
	return out
}

// hostSizeClassView says which class a host is in, nil for one that is in none:
// before the controller has worked it out, with both switches off, or because
// the host's size tag is not a class, which the host's auto pool says.
func (c *Controller) hostSizeClassView(h *store.Host) *HostSizeClassView {
	if !c.tracksClasses() {
		return nil
	}
	class, operator := h.EffectiveSizeClass()
	if !class.Valid() {
		return nil
	}
	cfg := c.sizeConfig()
	measured, known := cfg.HostClass(h)
	alloc := h.Allocatable()
	machine := fmt.Sprintf("%s CPUs and %s of memory allocatable", scheduler.FormatCPUs(alloc.CPUs), scheduler.FormatMB(alloc.MemoryMB))

	out := &HostSizeClassView{Class: class, Source: "measured"}
	if operator {
		out.Source = "tag"
	}
	if known && measured != class {
		out.Measured = measured
	}
	switch {
	case operator && out.Measured != "":
		out.Reason = fmt.Sprintf("the size tag on this host says %s; its machine, at %s, would be %s", class, machine, out.Measured)
	case operator && known:
		out.Reason = fmt.Sprintf("the size tag on this host says %s, which is also what its machine measures (%s)", class, machine)
	case operator:
		out.Reason = fmt.Sprintf("the size tag on this host says %s", class)
	default:
		out.Reason = fmt.Sprintf("%s put it in the %s class (small goes up to %s CPUs and %s, medium to %s CPUs and %s)",
			machine, class, scheduler.FormatCPUs(cfg.SmallMax.CPUs), scheduler.FormatMB(cfg.SmallMax.MemoryMB),
			scheduler.FormatCPUs(cfg.MediumMax.CPUs), scheduler.FormatMB(cfg.MediumMax.MemoryMB))
	}
	if h.SizeClass.Pending.Valid() && h.SizeClass.PendingSince != nil && !operator {
		out.Pending = h.SizeClass.Pending
		since := *h.SizeClass.PendingSince
		until := since.Add(cfg.Hold)
		out.PendingSince, out.PendingUntil = &since, &until
		out.Reason += fmt.Sprintf("; its measurements now name %s, and it moves when they have done so for %s", out.Pending, scheduler.FormatDuration(cfg.Hold))
	}
	return out
}

// hostAutoPoolView says which pool a host counts towards, nil while automatic
// pools are off or before a pass has looked at the host.
func (c *Controller) hostAutoPoolView(h *store.Host) *HostAutoPoolView {
	if c.autoMode() == scheduler.SizeOff {
		return nil
	}
	// Read under the lock and not through AutoPoolStatus, which copies every list
	// it holds: a page of hosts renders one of these for each, and a copy of the
	// whole status for each would grow with the square of the fleet.
	c.autoPools.statusMu.RLock()
	defer c.autoPools.statusMu.RUnlock()
	st := &c.autoPools.status
	if key, ok := st.hostPool[h.ID]; ok {
		for _, p := range st.Pools {
			if p.Key == key {
				return &HostAutoPoolView{Counted: true, Pool: p.Name, PoolID: p.PoolID}
			}
		}
	}
	if skip, ok := st.skipByHost[h.ID]; ok {
		return &HostAutoPoolView{Reason: skip.Message, ReasonCode: skip.Reason}
	}
	return nil
}

// auto renders what is particular to a pool the controller keeps, nil for any
// other.
func (v *PoolRenderer) auto(p *store.Pool) *PoolAutoView {
	if !p.FromHosts() {
		return nil
	}
	arch, class, ok := store.ParseAutoKey(p.AutoKey)
	if !ok {
		return nil
	}
	out := &PoolAutoView{Key: p.AutoKey, Arch: arch, Class: class, Warm: p.AutoMin, Cap: p.AutoCap, Paused: p.AutoPaused, Hosts: []string{}}
	for _, s := range v.autoStatus.Pools {
		if s.PoolID == p.ID {
			out.Hosts, out.Slots = emptySlice(s.Hosts), s.Slots
		}
	}
	var why string
	out.Kept, why = v.autoStatus.keeps(p)
	out.Summary = autoPoolSentence(p, arch, class, out.Hosts, out.Slots, why)
	return out
}

// autoPoolSentence says what a pool the controller keeps is and where its
// maximum comes from. notKept is why the controller is not keeping it at the
// moment, empty when it is: a pool it is not keeping has no hosts counted
// towards it and no maximum being worked out, which is not the same thing as
// having none, and the sentence must not say that it is out of use for want of
// hosts when nobody is looking.
func autoPoolSentence(p *store.Pool, arch string, class store.SizeClass, hosts []string, slots int, notKept string) string {
	which := fmt.Sprintf("%s %s hosts", class, archWord(arch))
	var parts []string
	switch {
	case notKept != "":
		parts = append(parts, fmt.Sprintf("Made by the controller for %s, and not being kept now: %s. It holds the limits it had.", which, notKept))
	case len(hosts) == 0:
		parts = append(parts, fmt.Sprintf("Kept by the controller for %s. No host of that kind counts at the moment, so the pool is out of use.", which))
	default:
		parts = append(parts, fmt.Sprintf("Kept by the controller for %s: %s (%s) hold %s between them.",
			which, plural(len(hosts), "host"), strings.Join(hosts, ", "), plural(slots, "runner")))
	}
	// What an operator asked for is said as it is, but when nothing is working a
	// maximum out the cap and the warm count are not yet doing anything.
	later := ""
	if notKept != "" {
		later = ", which takes effect when the controller keeps it"
	}
	if p.AutoCap > 0 && (notKept != "" || slots > p.AutoCap) {
		parts = append(parts, fmt.Sprintf("You capped it at %s%s.", plural(p.AutoCap, "runner"), later))
	}
	if p.AutoMin > 0 {
		parts = append(parts, fmt.Sprintf("You asked for %s kept warm%s.", plural(p.AutoMin, "runner"), later))
	}
	if p.AutoPaused {
		parts = append(parts, "You paused it, so it takes no new work whatever its hosts do.")
	}
	return strings.Join(parts, " ")
}

// archWord is an architecture as a person says it.
func archWord(arch string) string {
	if arch == "amd64" {
		return "x64"
	}
	return arch
}

// ---------------------------------------------------------------------------
// What a workflow could say better
// ---------------------------------------------------------------------------

// AdviceOptions narrows a request for label advice: a window the figures
// behind each row are read over (zero is scheduler.ClassWindow, the span the
// class itself is decided over) and a repository, compared as GitHub does.
type AdviceOptions struct {
	Window time.Duration
	Repo   string
}

// What bounded the window the figures were read over.
const (
	AdviceBoundAsked     = "asked"
	AdviceBoundRetention = "retention"
)

// AdviceWindow is the span the figures behind a page of advice cover: what
// was asked, what applied, and which of the two bounded it. A window longer
// than the history the fleet keeps would promise figures over runs that were
// pruned, so retention is the ceiling and the answer says when it was hit.
type AdviceWindow struct {
	Asked   store.Duration `json:"asked"`
	Applied store.Duration `json:"applied"`
	Bound   string         `json:"bound"`
}

// adviceWindow applies retention to the window asked for.
func (c *Controller) adviceWindow(asked time.Duration) AdviceWindow {
	if asked <= 0 {
		asked = scheduler.ClassWindow
	}
	w := AdviceWindow{Asked: store.Duration(asked), Applied: store.Duration(asked), Bound: AdviceBoundAsked}
	if keep := c.cfg().Retention.Jobs; keep > 0 && keep < asked {
		w.Applied, w.Bound = store.Duration(keep), AdviceBoundRetention
	}
	return w
}

// LabelAdvice says what to change in the runs-on of the jobs whose measured
// runs call for something other than what they ask for, the costliest first,
// with the figures each row rests on and whether any host carries the class
// it recommends. There is none while size routing is off, because nothing is
// classed to compare with.
func (c *Controller) LabelAdvice(ctx context.Context, opts AdviceOptions) ([]*scheduler.Advice, AdviceWindow, error) {
	window := c.adviceWindow(opts.Window)
	rows, err := c.adviceRows(ctx, opts.Repo)
	if err != nil || len(rows) == 0 {
		return rows, window, err
	}
	hosts, err := c.st.ListHosts(ctx)
	if err != nil {
		return nil, window, fmt.Errorf("listing hosts: %w", err)
	}
	// The fit is whether the fleet has such a host at all; a host that is
	// cordoned or quiet still counts, because the question is about buying a
	// machine, not about this minute's room.
	carried := map[store.SizeClass]bool{}
	for _, h := range hosts {
		if class, _ := h.EffectiveSizeClass(); class.Valid() {
			carried[class] = true
		}
	}
	since := c.Now().Add(-window.Applied.Duration())
	for _, a := range rows {
		runs, err := c.st.JobClassHistory(ctx, a.Repo, a.Workflow, a.JobName, since, store.JobClassHistoryLimit)
		if err != nil {
			return nil, window, fmt.Errorf("reading the runs behind %s/%s/%s: %w", a.Repo, a.Workflow, a.JobName, err)
		}
		obs := scheduler.Observe(runs)
		a.Observed = &obs
		fit := &scheduler.Fit{OK: carried[a.RecommendedClass]}
		if !fit.OK {
			fit.Missing = a.RecommendedClass
		}
		a.Fits = fit
	}
	return rows, window, nil
}

// adviceRows is the advice without its figures: what the problems list
// counts after every pass. It reads the kept classes and the pins and
// nothing per job, so a count on a fleet with hundreds of advised jobs is
// two queries and not hundreds of history scans for a number.
func (c *Controller) adviceRows(ctx context.Context, repoFilter string) ([]*scheduler.Advice, error) {
	if c.sizeMode() == scheduler.SizeOff {
		return nil, nil
	}
	kept, err := c.st.ListJobClassesAsked(ctx)
	if err != nil {
		return nil, fmt.Errorf("listing the classes kept for jobs: %w", err)
	}
	pins, err := c.st.ListSizePins(ctx)
	if err != nil {
		return nil, fmt.Errorf("listing size pins: %w", err)
	}
	repo := strings.ToLower(strings.TrimSpace(repoFilter))
	cfg := c.sizeConfig()
	var out []*scheduler.Advice
	for _, k := range kept {
		if repo != "" && strings.ToLower(k.Repo) != repo {
			continue
		}
		if a := cfg.LabelAdvice(k, pins); a != nil {
			out = append(out, a)
		}
	}
	scheduler.SortAdvice(out)
	return out, nil
}

// labelAdviceMemoFor is how long the problems list reuses the count of label
// advice. It reads every class kept for every job, with the labels of each job's
// latest run, and the list is built after every pass; a hint about a workflow's
// runs-on that is a minute old is as good as a fresh one, and a fleet with tens
// of thousands of jobs does not pay for it once a second.
const labelAdviceMemoFor = time.Minute

// adviceMemo is the last count of label advice by kind, and when it was made.
// The page of advice itself is never taken from it: whoever opens that page is
// asking for the answer now.
type adviceMemo struct {
	mu     sync.Mutex
	at     time.Time
	counts map[string]int
	total  int
}

// labelAdviceCounts is how much advice there is of each kind, and in all. It is
// worked out again once the last answer is a minute old, or when a pin changes
// what a job is advised on.
func (c *Controller) labelAdviceCounts(ctx context.Context) (map[string]int, int, error) {
	m := &c.adviceMemo
	m.mu.Lock()
	defer m.mu.Unlock()
	now := c.Now()
	if age := now.Sub(m.at); m.counts != nil && age >= 0 && age < labelAdviceMemoFor {
		return m.counts, m.total, nil
	}
	advice, err := c.adviceRows(ctx, "")
	if err != nil {
		return nil, 0, err
	}
	// A row with too few runs is counted under its state and not as advice:
	// the problem entry is about workflows that could say something better,
	// and a job the fleet has not seen enough of is not yet one of them.
	counts := map[string]int{}
	total := 0
	for _, a := range advice {
		if a.State != scheduler.AdviceStateOK {
			counts[a.State]++
			continue
		}
		counts[a.Kind]++
		total++
	}
	m.at, m.counts, m.total = now, counts, total
	return counts, total, nil
}

// forgetLabelAdvice drops the memo, for a change that alters what a job is
// advised on at once: a pin, which advice leaves the job it covers alone.
func (c *Controller) forgetLabelAdvice() {
	c.adviceMemo.mu.Lock()
	c.adviceMemo.counts = nil
	c.adviceMemo.mu.Unlock()
}

// labelAdviceProblems raises one entry, at most, however many jobs there is
// advice for: the advice itself is a page of its own, and a drawer with a line
// for every workflow would bury the problems that are about the fleet.
func (c *Controller) labelAdviceProblems(ctx context.Context, out *[]Problem) error {
	if c.sizeMode() == scheduler.SizeOff {
		return nil
	}
	counts, total, err := c.labelAdviceCounts(ctx)
	if err != nil || total == 0 {
		return err
	}
	var parts []string
	if n := counts[scheduler.AdviceTooSmall]; n > 0 {
		parts = append(parts, fmt.Sprintf("%s asks for a class too small for what it uses", plural(n, "job")))
	}
	if n := counts[scheduler.AdviceUnguaranteed]; n > 0 {
		parts = append(parts, fmt.Sprintf("%s needs more than the default class and is only routed there best effort", plural(n, "job")))
	}
	if n := counts[scheduler.AdviceTooLarge]; n > 0 {
		parts = append(parts, fmt.Sprintf("%s asks for more than it uses", plural(n, "job")))
	}
	*out = append(*out, Problem{
		Code:     "jobs.label_advice",
		Severity: config.SeverityInfo,
		Title:    fmt.Sprintf("%s could say something better in runs-on", plural(total, "workflow job")),
		Detail:   capitalise(strings.Join(parts, "; ")) + ".",
		Fix:      "open the label advice on the Jobs page, or run `zoomies jobs advice`, which says what to write instead for each.",
	})
	return nil
}

