func TestAJobViewCarriesHowItWasClassedAndWhereItRan(t *testing.T) {
	h := newHarness(t)
	h.classFleet(scheduler.SizeOn)
	h.deliverJob(jobEvent{Action: "queued", JobID: 8101, Name: "build", Workflow: "CI", Labels: baseLabels})
