package controller

import (
	"encoding/json"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// Every code the fleet's list can carry has a public sentence, and no code
// that only the platform is shown has one. The second half is the one that
// matters: a sentence for a platform code is a sentence somebody meant to
// show without an account, about a machine that is not the fleet's.
func TestEveryFleetCodeHasAPublicSentence(t *testing.T) {
	for code, audience := range problemAudience {
		_, has := publicSentences[code]
		switch {
		case statusExempt(code) && has:
			t.Errorf("%s is exempt from the status page and has a public sentence it can never show", code)
		case statusExempt(code):
			// The fleet sees it; the page does not. TestAnAIContextFailure...
			// holds the other half.
		case audience.For(false) && !has:
			t.Errorf("%s reaches the fleet's list and has no public sentence", code)
		case !audience.For(false) && has:
			t.Errorf("%s is the platform's and has a public sentence; the status page can never show it", code)
		}
	}
	for code := range publicSentences {
		if _, ok := problemAudience[code]; !ok {
			t.Errorf("%s has a public sentence and no audience; it is not a code the controller raises", code)
		}
	}
}

// The projection reads the fleet half of the problems split and nothing
// else, so a platform finding -- however bad -- neither shows as a reason
// nor moves the state.
func TestTheStatusCannotCarryAPlatformProblem(t *testing.T) {
	st := ProjectStatus([]Problem{
		{Code: "backup.remote_failed", Severity: config.SeverityError, Title: "remote s3-backups-secret failed", Audience: AudiencePlatform},
		{Code: "controller.lease_lost", Severity: config.SeverityError, Audience: AudiencePlatform},
		{Code: "metrics.public", Severity: config.SeverityWarning, Audience: AudiencePlatform},
		// An unclassified code is withheld, which is audienceFor's default.
		{Code: "something.new", Severity: config.SeverityError},
	}, nil)
	if st.State != FleetHealthy || len(st.Reasons) != 0 || len(st.Explanations) != 0 {
		t.Fatalf("status = %+v, want healthy with no reasons", st)
	}
}

// A repository's AI Context workflow failing is an error for whoever set it up
// and nothing to a developer waiting on a job. Were it on the status page, a full
// artifact quota would turn the public state to "blocked" while every runner was
// healthy.
func TestAnAIContextFailureNeverMovesThePublicStatus(t *testing.T) {
	st := ProjectStatus([]Problem{
		{Code: "ai_context.artifact_quota", Severity: config.SeverityError, Title: "GitHub's artifact storage is full (acme/private-repo)", Audience: AudienceFleet},
		{Code: "ai_context.runner_unavailable", Severity: config.SeverityWarning, Audience: AudienceFleet},
	}, nil)
	if st.State != FleetHealthy || len(st.Reasons) != 0 || len(st.Explanations) != 0 {
		t.Fatalf("status = %+v, want healthy with no reasons", st)
	}
	body, _ := json.Marshal(st)
	if strings.Contains(string(body), "private-repo") || strings.Contains(string(body), "ai_context") {
		t.Errorf("the status carries an AI Context problem: %s", body)
	}

	// And it does not hide a real problem beside it.
	st = ProjectStatus([]Problem{
		{Code: "ai_context.artifact_quota", Severity: config.SeverityError, Audience: AudienceFleet},
		{Code: "host.unhealthy", Severity: config.SeverityWarning, Audience: AudienceFleet},
	}, nil)
	if st.State != FleetDegraded || len(st.Reasons) != 1 || st.Reasons[0].Code != "host.unhealthy" {
		t.Errorf("status = %+v, want degraded by the host alone", st)
	}
}

// The state is the worst severity among the fleet's own problems, and a code
// that several pools share is one reason, not one per pool -- a count of
// reasons would be a count of pools.
func TestTheStateIsTheWorstOfTheFleetsProblems(t *testing.T) {
	early := time.Date(2026, 9, 1, 10, 0, 0, 0, time.UTC)
	late := early.Add(time.Hour)
	cases := []struct {
		name     string
		problems []Problem
		want     FleetState
		reasons  []string
	}{
		{"nothing", nil, FleetHealthy, nil},
		{"info only", []Problem{{Code: "host.limits_unverified", Severity: config.SeverityInfo}}, FleetHealthy, nil},
		{"a warning", []Problem{{Code: "host.throttled", Severity: config.SeverityWarning}}, FleetDegraded, []string{"host.throttled"}},
		{"an error beats a warning", []Problem{
			{Code: "host.throttled", Severity: config.SeverityWarning},
			{Code: "pool.no_capacity", Severity: config.SeverityError, Since: &late},
			{Code: "pool.no_capacity", Severity: config.SeverityWarning, Since: &early},
		}, FleetBlocked, []string{"pool.no_capacity", "host.throttled"}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			st := ProjectStatus(tc.problems, nil)
			if st.State != tc.want {
				t.Fatalf("state = %s, want %s", st.State, tc.want)
			}
			var got []string
			for _, r := range st.Reasons {
				got = append(got, r.Code)
				if st.Explanations[r.Code] == "" {
					t.Errorf("%s has no explanation", r.Code)
				}
			}
			if !slices.Equal(got, tc.reasons) {
				t.Fatalf("reasons = %v, want %v", got, tc.reasons)
			}
			if tc.want == FleetBlocked {
				r := st.Reasons[0]
				if r.Severity != config.SeverityError || r.Since == nil || !r.Since.Equal(early) {
					t.Errorf("merged reason = %+v, want the worst severity and the earliest since", r)
				}
			}
		})
	}
}

// Counts are bands, and a queue longer than every slot the fleet has is the
// one band a developer most needs: it means waiting is not going to be short.
func TestCountsAreBandsAndWaitsAreWholeMinutes(t *testing.T) {
	cases := []struct {
		queued, capacity, running int
		wantQueued, wantRunning   Band
	}{
		{0, 8, 0, BandNone, BandNone},
		{3, 8, 5, BandFew, BandFew},
		{7, 8, 6, BandMany, BandMany},
		{9, 8, 40, BandBackedUp, BandMany},
		// A handful is a handful even on a fleet with one slot.
		{4, 1, 1, BandFew, BandFew},
	}
	for _, tc := range cases {
		stats := &Stats{Hosts: HostStats{Capacity: tc.capacity}}
		stats.Fleet.QueuedJobs, stats.Fleet.RunningJobs = tc.queued, tc.running
		stats.Fleet.MedianWaitMS, stats.Fleet.P95WaitMS = 89_000, 29_000
		st := ProjectStatus(nil, stats)
		if st.Queued != tc.wantQueued || st.Running != tc.wantRunning {
			t.Errorf("queued %d of %d, running %d: got %s/%s, want %s/%s",
				tc.queued, tc.capacity, tc.running, st.Queued, st.Running, tc.wantQueued, tc.wantRunning)
		}
		if st.MedianWaitMinutes != 1 || st.P95WaitMinutes != 0 {
			t.Errorf("waits = %d/%d minutes, want 1/0", st.MedianWaitMinutes, st.P95WaitMinutes)
		}
	}
}

// The fixture names every test below searches for. Distinctive on purpose: a
// name that is also an ordinary word would pass the search by accident the
// day a sentence used the word.
const (
	fixtureTarget = "quokkaorg"
	fixturePool   = "narwhalpool"
	fixtureHost   = "axolotlhost"
	fixtureRepo   = fixtureTarget + "/pangolinrepo"
	fixtureJob    = "capybarajob"
	fixtureFlow   = "okapiworkflow"
)

// statusFixture is one of the four reasons a job waits, built for real on a
// fleet whose every name is distinctive.
type statusFixture struct {
	name string
	code string
	make func(t *testing.T, h *harness)
}

func (h *harness) namedFleet() (*store.Installation, *store.Pool) {
	inst := h.installationOn(fixtureTarget, store.TargetOrg)
	return inst, h.pool(inst, fixturePool)
}

func (h *harness) queueNamedJob(id int64, labels []string, queued time.Time) {
	h.deliverJob(jobEvent{
		Action: "queued", JobID: id, RunID: id, Repo: fixtureRepo,
		Name: fixtureJob, Workflow: fixtureFlow, Labels: labels, QueuedAt: queued,
	})
}

var statusFixtures = []statusFixture{
	{"capacity", "pool.no_capacity", func(t *testing.T, h *harness) {
		_, p := h.namedFleet()
		h.queueNamedJob(1, p.Labels, time.Now().Add(-time.Minute))
		if err := h.c.Reconcile(h.ctx); err != nil {
			t.Fatalf("Reconcile: %v", err)
		}
	}},
	{"labels", "jobs.unmatched", func(t *testing.T, h *harness) {
		h.namedFleet()
		h.host(fixtureHost)
		h.queueNamedJob(2, []string{"self-hosted", "gpu"}, time.Now().Add(-unmatchedGrace-time.Minute))
	}},
	{"permission", "installation.unhealthy", func(t *testing.T, h *harness) {
		inst, p := h.namedFleet()
		h.host(fixtureHost)
		h.queueNamedJob(3, p.Labels, time.Now().Add(-time.Minute))
		if err := h.st.SetInstallationHealth(h.ctx, inst.ID, "the App lost access to "+fixtureRepo); err != nil {
			t.Fatalf("SetInstallationHealth: %v", err)
		}
	}},
	{"webhook secret", "webhook.rejected", func(t *testing.T, h *harness) {
		_, p := h.namedFleet()
		h.host(fixtureHost)
		h.deliver("workflow_job", jobEvent{Action: "queued", JobID: 4, Repo: fixtureRepo, Name: fixtureJob, Labels: p.Labels}.body(), "not-the-secret")
	}},
	// Not a reason a job waits: a fleet doing its job, so that runners -- and
	// the names they are given -- are in the fixture too.
	{"busy", "", func(t *testing.T, h *harness) {
		_, p := h.namedFleet()
		h.host(fixtureHost)
		h.queueNamedJob(5, p.Labels, time.Now().Add(-time.Minute))
		if err := h.c.Reconcile(h.ctx); err != nil {
			t.Fatalf("Reconcile: %v", err)
		}
		if len(h.runners()) == 0 {
			t.Fatal("no runner was created, so the fixture has no runner names to search for")
		}
	}},
}

// fixtureNames is every name the fixture's rows carry, read back from the
// store rather than listed, so a name the controller makes up -- a runner's
// -- is searched for too.
func fixtureNames(t *testing.T, h *harness) []string {
	t.Helper()
	names := []string{fixtureTarget, fixturePool, fixtureHost, fixtureRepo, "pangolinrepo", fixtureJob, fixtureFlow}
	pools, _ := h.st.ListPools(h.ctx)
	for _, p := range pools {
		names = append(names, p.Name, p.ID)
	}
	hosts, _ := h.st.ListHosts(h.ctx)
	for _, x := range hosts {
		names = append(names, x.Name, x.ID)
	}
	insts, _ := h.st.ListInstallations(h.ctx)
	for _, i := range insts {
		names = append(names, i.Target, i.ID)
	}
	for _, r := range h.runners() {
		names = append(names, r.Name, r.ID)
	}
	jobs, _, _ := h.st.ListJobs(h.ctx, store.JobFilter{}, store.Page{Limit: 100})
	for _, j := range jobs {
		names = append(names, j.Repo, j.JobName, j.Workflow, j.ID)
	}
	out := names[:0]
	for _, n := range names {
		if n != "" {
			out = append(out, n)
		}
	}
	return out
}

// The acceptance test for the disclosure boundary: a fleet whose every pool,
// host, repository, runner and job is named something distinctive produces a
// status body containing none of those names, and each of the four reasons a
// job waits -- capacity, labels, a lost permission, a webhook secret that
// stopped verifying -- produces a state a reader can tell from the other
// three.
func TestTheStatusNamesNothingAndTellsTheFourWaitsApart(t *testing.T) {
	causes := map[string]bool{}
	for _, f := range statusFixtures {
		if f.code != "" {
			causes[f.code] = true
		}
	}
	for _, f := range statusFixtures {
		t.Run(f.name, func(t *testing.T) {
			h := newHarness(t)
			f.make(t, h)
			st, err := h.c.Status(h.ctx)
			if err != nil {
				t.Fatalf("Status: %v", err)
			}
			body, err := json.Marshal(st)
			if err != nil {
				t.Fatal(err)
			}
			names := fixtureNames(t, h)
			for _, n := range names {
				if strings.Contains(string(body), n) {
					t.Errorf("the status body contains %q:\n%s", n, body)
				}
			}
			if len(names) < 8 {
				t.Fatalf("only %d names were collected, so the search proves little: %v", len(names), names)
			}

			var got []string
			for _, r := range st.Reasons {
				got = append(got, r.Code)
			}
			if f.code != "" && !slices.Contains(got, f.code) {
				t.Fatalf("reasons = %v, want %s", got, f.code)
			}
			// Distinguishable: this cause's code is present and no other
			// cause's is, so the page says a different thing for each.
			for code := range causes {
				if code != f.code && slices.Contains(got, code) {
					t.Errorf("reasons = %v carry %s as well as %s; the four waits must read differently", got, code, f.code)
				}
			}
			if f.code != "" && st.State == FleetHealthy {
				t.Errorf("a fleet whose jobs wait on %s reads as healthy", f.name)
			}
		})
	}
}

// Since is when the state last changed, not when somebody asked: a page that
// refreshes every thirty seconds would otherwise always say "just now".
func TestSinceHoldsUntilTheStateChanges(t *testing.T) {
	h := newHarness(t)
	first, err := h.c.Status(h.ctx)
	if err != nil {
		t.Fatalf("Status: %v", err)
	}
	h.advance(10 * time.Minute)
	second, _ := h.c.Status(h.ctx)
	if !second.Since.Equal(first.Since) {
		t.Fatalf("since moved from %s to %s with the state unchanged", first.Since, second.Since)
	}
	inst := h.installation()
	if err := h.st.SetInstallationHealth(h.ctx, inst.ID, "gone"); err != nil {
		t.Fatal(err)
	}
	third, _ := h.c.Status(h.ctx)
	if third.State == second.State || !third.Since.After(second.Since) {
		t.Fatalf("state %s since %s, want a new state with a later since", third.State, third.Since)
	}
}

package controller

import (
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/store"
)

// The task queue is in memory by design: every task is derived from state the
// database already holds, so persisting the queue would add a second source of
// truth that could disagree with the runners table.
//
// What a restart must not lose is the time. Without a stamp on the row, a
// provisioning runner whose create was issued twenty minutes ago and one whose
// create went out a second ago are the same row, and the operator reading the
// page -- or a controller that has just come back -- has no way to tell how
// long this runner has actually been waiting on its host.
func TestIssuingARunnersTaskIsRecordedOnItsRow(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	h.deliverJob(jobEvent{Action: "queued", JobID: 9101, Labels: []string{"self-hosted", "linux", "x64", "demo"}})
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	h.c.lifecycleCalls.Wait()

	r := h.onlyRunner()
	if r.TaskIssuedAt == nil {
		t.Fatal("task_issued_at is unset after the create was queued; the row cannot say when its host was asked")
	}
	first := *r.TaskIssuedAt

	batch, err := h.c.PollTasks(h.ctx, host.ID, time.Second)
	if err != nil || len(batch.Tasks) != 1 {
		t.Fatalf("PollTasks: %v, %d tasks", err, len(batch.Tasks))
	}
	after := h.onlyRunner()
	if after.TaskIssuedAt == nil || after.TaskIssuedAt.Before(first) {
		t.Fatalf("task_issued_at = %v after the poll, want it at or after the enqueue stamp %v", after.TaskIssuedAt, first)
	}
}

// The redelivery half. A create whose lease expires is offered again, and the
// second offer is the one that matters: counting the provision timeout from
// the first would fail a runner whose host only just received the work.
func TestRedeliveringATaskMovesTheRunnersIssueStampForward(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerProvisioning)

	task := agent.Task{Kind: agent.TaskCreateRunner, RunnerID: r.ID, Backend: pool.Backend}
	if !h.c.enqueueLifecycle(h.ctx, host.ID, task) {
		t.Fatal("the task was not queued")
	}
	if _, err := h.c.PollTasks(h.ctx, host.ID, time.Second); err != nil {
		t.Fatalf("PollTasks: %v", err)
	}
	issued := h.runnerByID(t, r.ID).TaskIssuedAt
	if issued == nil {
		t.Fatal("task_issued_at is unset after the first delivery")
	}

	// Wind the clock past the create lease and sweep, which is what puts the
	// task back on the queue for a second attempt.
	h.advance(createLease + time.Minute)
	if requeued, _ := h.c.queues.get(host.ID).sweep(h.c.Now()); requeued != 1 {
		t.Fatalf("sweep re-queued %d tasks, want 1", requeued)
	}
	if _, err := h.c.PollTasks(h.ctx, host.ID, time.Second); err != nil {
		t.Fatalf("PollTasks: %v", err)
	}

	again := h.runnerByID(t, r.ID).TaskIssuedAt
	if again == nil {
		t.Fatal("task_issued_at is unset after the redelivery")
	}
	if !again.After(*issued) {
		t.Fatalf("task_issued_at = %v after redelivery, want it later than the first issue %v; "+
			"the provision timeout would be counted from an attempt the host never received", again, issued)
	}
}

// A log relay says nothing about whether a runner is progressing -- the
// container is where it was, doing what it was doing -- so it must not move a
// clock that decides whether the runner is written off.
func TestALogTaskDoesNotTouchTheRunnersIssueStamp(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerIdle)

	h.c.enqueueLifecycle(h.ctx, host.ID, agent.Task{
		Kind: agent.TaskStreamLogs, RunnerID: r.ID, StreamID: "stream_x",
	})
	if got := h.runnerByID(t, r.ID).TaskIssuedAt; got != nil {
		t.Fatalf("task_issued_at = %v after a log task, want it untouched", got)
	}
}

func TestFirstCreateDeliverySurvivesRetriesAndRemoval(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerProvisioning)
	h.c.enqueueLifecycle(h.ctx, host.ID, agent.Task{Kind: agent.TaskCreateRunner, RunnerID: r.ID})
	if h.runnerByID(t, r.ID).CreateTaskIssuedAt != nil {
		t.Fatal("enqueue was counted as delivery to the host")
	}
	h.advance(5 * time.Second)
	batch, err := h.c.PollTasks(h.ctx, host.ID, time.Second)
	if err != nil || len(batch.Tasks) != 1 {
		t.Fatalf("PollTasks: %v, batch: %+v", err, batch)
	}
	first := h.runnerByID(t, r.ID).CreateTaskIssuedAt
	if first == nil || !first.Equal(batch.Tasks[0].IssuedAt.Truncate(time.Millisecond)) {
		t.Fatalf("first delivery = %v, want %v", first, batch.Tasks[0].IssuedAt)
	}
	for _, kind := range []agent.TaskKind{agent.TaskCreateRunner, agent.TaskStopRunner, agent.TaskRemoveRunner} {
		h.advance(time.Minute)
		issued := h.c.Now()
		h.c.stampIssued(h.ctx, []agent.Task{{Kind: kind, RunnerID: r.ID, IssuedAt: issued}})
		got := h.runnerByID(t, r.ID)
		if got.CreateTaskIssuedAt == nil || !got.CreateTaskIssuedAt.Equal(*first) {
			t.Fatalf("%s overwrote the first create delivery: %v", kind, got.CreateTaskIssuedAt)
		}
		if got.TaskIssuedAt == nil || !got.TaskIssuedAt.Equal(issued.Truncate(time.Millisecond)) {
			t.Fatal("the retry clock must still advance independently")
		}
	}
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// A test machine is the one machine an operator asks for by hand, to find out
// whether a provider works before a job depends on it.
//
// It is built by the same loop as any other (clone, start, install the agent,
// enrol as a host), so a pass proves every step a real machine needs rather than
// a lookalike. What differs is only what happens around it: it is not kept warm
// and not drained for idleness (see DecideMachines), it counts against every
// ceiling because it costs like any other, and it is released the moment it
// reports ready. A test that fails is left in place, because the machine's own
// message and errors are what the operator reads to fix it, and the page offers
// the release.

// ErrTestMachineRefused is a test that cannot be started, with the sentence that
// says why and what to change. The API answers it with a 409.
var ErrTestMachineRefused = errors.New("a test machine cannot be started")

func refuseTest(format string, args ...any) error {
	return fmt.Errorf("%w: %s", ErrTestMachineRefused, fmt.Sprintf(format, args...))
}

// StartTestMachine reserves one test machine on a provider and wakes the machine
// loop to build it.
//
// Only one runs at a time per provider: two would race for the same ceiling and
// each would leave the operator unsure which machine the answer was about. The
// checks read what exists and the reservation writes after, so a second request
// arriving between them would see nothing on the way; one lock holds them
// together, and a request that waits for it is answered by what the first made.
func (c *Controller) StartTestMachine(ctx context.Context, row *store.Provider) (*store.Machine, error) {
	c.machines.testMu.Lock()
	defer c.machines.testMu.Unlock()
	now := c.Now()
	if held := c.provisioningHeld(row, now); held != "" {
		return nil, refuseTest("%s", held)
	}
	machines, err := c.st.ListMachinesForProvider(ctx, row.ID)
	if err != nil {
		return nil, fmt.Errorf("listing machines for provider %s: %w", row.Name, err)
	}
	owned := 0
	for _, m := range machines {
		if m.Test && !m.State.Terminal() && m.State != store.MachineFailed && m.State != store.MachineQuarantined {
			return nil, refuseTest("a test machine (%s) is already on its way, so wait for it to finish", m.Name)
		}
		if m.Owns() || m.State.Pending() {
			owned++
		}
	}
	if row.MaxMachines <= owned {
		return nil, refuseTest("%s may own %s and already has %d, so there is no room for a test machine; "+
			"raise its maximum machines first", row.Name, plural(row.MaxMachines, "machine"), owned)
	}
	// A maximum of none is none, as it is for the planner: provider.max_machines
	// is 0 until somebody sets it, and a fleet that rents nothing has no room
	// for a machine that is billed like any other.
	limits := MachineLimits{MaxMachines: c.cfg().Provider.MaxMachines}
	counts, err := c.st.CountOwnedMachines(ctx)
	if err != nil {
		return nil, fmt.Errorf("counting owned machines: %w", err)
	}
	fleet := 0
	for _, n := range counts {
		fleet += n
	}
	if fleet >= limits.MaxMachines {
		what, how := fleetMachineCeiling(limits, fleet)
		return nil, refuseTest("%s; %s", what, how)
	}

	expires := now.Add(c.cfg().Provider.CreateTimeout)
	m := &store.Machine{
		ProviderID:           row.ID,
		State:                store.MachinePlanned,
		Message:              "a test machine, built to prove this provider works; it is released as soon as it reports ready",
		Capacity:             row.MachineCapacity,
		Labels:               row.MachineLabels,
		Test:                 true,
		ReservationExpiresAt: &expires,
	}
	if err := c.st.CreateMachine(ctx, m); err != nil {
		return nil, fmt.Errorf("reserving a test machine: %w", err)
	}
	c.publishMachine(ctx, m)
	c.log.Info("a test machine was reserved", "machine", m.ID, "name", m.Name, "provider", row.Name)
	c.NudgeMachines()
	return m, nil
}

// releaseTestMachine is a test machine's pass: it reported ready, so the
// provider can build, start, bootstrap and enrol a machine, and it is not paid
// for a minute longer than that took.
func (c *Controller) releaseTestMachine(ctx context.Context, env *machineEnv, m *store.Machine) {
	took := ""
	if m.ReadyAt != nil {
		took = " in " + roundDuration(m.ReadyAt.Sub(m.CreatedAt).Truncate(time.Second))
	}
	c.beginDrain(ctx, env, m.ID, fmt.Sprintf("the test passed: this machine was built, started, enrolled as a host and reported ready%s; it is being released", took))
}

package controller

import (
	"errors"
	"fmt"
	"strings"
	"sync"
	"sync/atomic"
	"testing"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// testFleet is machineFleet without the queued job: a test machine is asked for
// by a person, so any machine that appears must be the one they asked for.
func (h *harness) testFleet(t *testing.T) *store.Provider {
	t.Helper()
	h.enableProviders(t)
	h.pool(h.installation(), "linux-x64")
	return h.providerRow(t, "lab")
}

// The point of the test is that it goes through every step a real machine does,
// so it is driven the way the other machine tests are: built, bootstrapped,
// joined by the agent inside the guest, and then released without anyone asking.
func TestATestMachineIsBuiltEnrolledAndThenReleased(t *testing.T) {
	h := newHarness(t)
	row := h.testFleet(t)

	m, err := h.c.StartTestMachine(h.ctx, row)
	if err != nil {
		t.Fatalf("StartTestMachine: %v", err)
	}
	if !m.Test {
		t.Fatal("the machine reserved for a test is not marked as one")
	}

	m = h.drive(t, m.ID, store.MachineEnrolling, 8)
	h.joinAsMachine(t, m)
	h.machinePass(t)
	m = h.drive(t, m.ID, store.MachineDeleted, 12)
	if m.ReadyAt == nil {
		t.Fatal("the test machine was released without ever reporting ready, so the test proved nothing")
	}
	if m.DeletedAt == nil {
		t.Fatal("the test machine was not confirmed deleted; a trial must not be left costing money")
	}
	h.assertOneResourcePerMachine(t)
}

// Two at once would race for the same ceiling and leave the operator unsure
// which machine an answer was about.
func TestASecondTestMachineWaitsForTheFirst(t *testing.T) {
	h := newHarness(t)
	row := h.testFleet(t)
	if _, err := h.c.StartTestMachine(h.ctx, row); err != nil {
		t.Fatalf("StartTestMachine: %v", err)
	}
	_, err := h.c.StartTestMachine(h.ctx, row)
	if !errors.Is(err, ErrTestMachineRefused) {
		t.Fatalf("a second test machine was %v, want it refused", err)
	}
	if !strings.Contains(err.Error(), "already on its way") {
		t.Fatalf("the refusal does not say why: %v", err)
	}
}

// A provider that may own no machines has no room for a test, and the sentence
// says which setting to raise rather than leaving a button that does nothing.
func TestATestMachineNeedsRoomUnderTheProvidersMaximum(t *testing.T) {
	h := newHarness(t)
	row := h.testFleet(t)
	row.MaxMachines = 0
	if err := h.st.UpdateProvider(h.ctx, row); err != nil {
		t.Fatalf("UpdateProvider: %v", err)
	}
	_, err := h.c.StartTestMachine(h.ctx, row)
	if !errors.Is(err, ErrTestMachineRefused) || !strings.Contains(err.Error(), "maximum machines") {
		t.Fatalf("a provider with no room started a test machine: %v", err)
	}
	if got := len(h.machines()); got != 0 {
		t.Fatalf("a refused test left %d machines behind", got)
	}
}

// A paused provider builds nothing, and a test is a build.
func TestATestMachineIsRefusedWhileTheProviderIsPaused(t *testing.T) {
	h := newHarness(t)
	row := h.testFleet(t)
	h.pauseProvider(t, row, "the hypervisor is being patched")
	got, err := h.st.GetProvider(h.ctx, row.ID)
	if err != nil {
		t.Fatalf("GetProvider: %v", err)
	}
	if _, err := h.c.StartTestMachine(h.ctx, got); !errors.Is(err, ErrTestMachineRefused) {
		t.Fatalf("a paused provider started a test machine: %v", err)
	}
}

// A test machine is not supply. If it were counted towards a provider's
// minimum, the warm floor would be met by a machine released a minute later and
// the first real job would wait for a clone after all.
func TestATestMachineDoesNotCountTowardsTheWarmMinimum(t *testing.T) {
	h := newHarness(t)
	row := h.testFleet(t)
	row.MinMachines = 1
	if err := h.st.UpdateProvider(h.ctx, row); err != nil {
		t.Fatalf("UpdateProvider: %v", err)
	}
	if _, err := h.c.StartTestMachine(h.ctx, row); err != nil {
		t.Fatalf("StartTestMachine: %v", err)
	}
	h.machinePass(t)
	var real int
	for _, m := range h.machines() {
		if !m.Test {
			real++
		}
	}
	if real != 1 {
		t.Fatalf("with a minimum of 1 and a test machine on its way the provider bought %d real machines, want 1", real)
	}
}

// provider.max_machines is 0 until somebody sets it, and 0 means this fleet
// rents nothing: the planner buys no machine under it and the validator says
// so. A test machine is a real billed machine, so it has no more room under a
// maximum of none than any other, and the sentence names the setting to raise
// rather than leaving a button that quietly spends.
func TestATestMachineNeedsRoomUnderTheFleetsMaximumToo(t *testing.T) {
	h := newHarness(t)
	row := h.testFleet(t)
	h.c.UpdateConfig(func(c *config.Config) { c.Provider.MaxMachines = 0 })

	_, err := h.c.StartTestMachine(h.ctx, row)
	if !errors.Is(err, ErrTestMachineRefused) || !strings.Contains(err.Error(), "provider.max_machines") {
		t.Fatalf("a fleet that may rent nothing started a test machine: %v", err)
	}
	if got := len(h.machines()); got != 0 {
		t.Fatalf("a refused test left %d machines behind", got)
	}
}

// The same ceiling once it is not none: a fleet that already owns as many
// machines as it may is refused, whichever provider they belong to, and is
// served again when the maximum is raised, as the sentence says to do.
func TestATestMachineIsRefusedWhenTheFleetIsAtItsMaximum(t *testing.T) {
	h := newHarness(t)
	row := h.testFleet(t)
	other := h.providerRow(t, "lab-2")
	h.c.UpdateConfig(func(c *config.Config) { c.Provider.MaxMachines = 1 })

	first, err := h.c.StartTestMachine(h.ctx, row)
	if err != nil {
		t.Fatalf("StartTestMachine: %v", err)
	}
	h.machinePass(t)
	if !h.machineByID(t, first.ID).Owns() {
		t.Fatal("the first test machine does not own a resource yet, so the fleet is not at its maximum")
	}

	_, err = h.c.StartTestMachine(h.ctx, other)
	if !errors.Is(err, ErrTestMachineRefused) || !strings.Contains(err.Error(), "provider.max_machines") {
		t.Fatalf("a fleet at its maximum started a second provider's test machine: %v", err)
	}

	h.c.UpdateConfig(func(c *config.Config) { c.Provider.MaxMachines = 2 })
	if _, err := h.c.StartTestMachine(h.ctx, other); err != nil {
		t.Fatalf("with room under the maximum the test machine was refused: %v", err)
	}
}

// Two operators, or one double click, asking for a test at the same moment.
// The checks read what exists and the reservation writes after, so without
// something holding them together every caller sees no test machine on the way
// and each reserves one: real machines, billed, on a provider that was to have
// one. Released together so that they overlap, and repeated because an overlap
// is a matter of luck where a lock is not.
func TestConcurrentTestMachineRequestsReserveOnlyOne(t *testing.T) {
	h := newHarness(t)
	h.testFleet(t)

	const callers = 16
	for round := range 5 {
		row := h.providerRow(t, fmt.Sprintf("lab-round-%d", round))
		var (
			wg      sync.WaitGroup
			gate    = make(chan struct{})
			started atomic.Int32
		)
		for range callers {
			wg.Add(1)
			go func() {
				defer wg.Done()
				<-gate
				_, err := h.c.StartTestMachine(h.ctx, row)
				switch {
				case err == nil:
					started.Add(1)
				case !errors.Is(err, ErrTestMachineRefused):
					t.Errorf("a test machine request failed instead of being refused: %v", err)
				}
			}()
		}
		close(gate)
		wg.Wait()

		tests := 0
		for _, m := range h.machines() {
			if m.Test && m.ProviderID == row.ID {
				tests++
			}
		}
		if started.Load() != 1 || tests != 1 {
			t.Fatalf("round %d: %d of %d simultaneous requests were accepted and %d test machines were reserved, want 1 of each",
				round, started.Load(), callers, tests)
		}
	}
}

package controller

import (
	"context"
	"errors"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// The throttle is decided in the scheduler (NextThrottle, pure) and applied
// here, from two places: every heartbeat, which is where a fresh measurement
// arrives, and the housekeeping pass, which is what lifts a throttle whose
// host has stopped sending measurements at all. Both go through settleThrottle
// so that a step is persisted, logged, audited and published in exactly one
// way -- a rung the Hosts page showed and the audit trail did not would be a
// decision nobody could account for afterwards.

// settleThrottle runs the ladder for one host as it stands now and records
// whatever moved. It reports whether the rung changed.
//
// h is updated in place, so a caller that goes on to render or answer with
// the host sees the rung it is actually on. A change that moves no rung -- a
// calm streak starting -- is persisted and published but neither logged nor
// audited: the streak is bookkeeping for the next step down, and a log line
// per heartbeat about a host that is merely recovering would bury the lines
// about the ones that are not.
func (c *Controller) settleThrottle(ctx context.Context, h *store.Host, now time.Time) bool {
	next := scheduler.NextThrottle(h, now)
	if sameThrottle(next, h.Throttle) {
		return false
	}
	if err := c.st.SetHostThrottle(ctx, h.ID, next, h.Throttle.Level); err != nil {
		if errors.Is(err, store.ErrThrottleMoved) {
			// Somebody else decided first: a heartbeat racing the
			// housekeeping tick, or an operator's clear. Their decision
			// stands, and the next sample decides from it.
			c.log.Debug("a host's throttle was decided elsewhere first", "host", h.ID)
			return false
		}
		c.log.Warn("could not record a host's throttle; the next heartbeat will decide again", "host", h.ID, "error", err)
		return false
	}
	was := h.Throttle
	h.Throttle = next
	if next.Level == was.Level {
		c.publishHost(h)
		return false
	}
	c.recordThrottleStep(ctx, h, was, next, true)
	return true
}

// recordThrottleStep is the log line, the audit row, the event and the nudge
// for a rung that moved in either direction. audit is false for an operator's
// clear, whose caller writes the row itself under the operator's own name:
// a lift the ladder decided and a lift somebody asked for are two different
// facts, and an audit trail with both attributed to the system could not
// tell an operator which of their colleagues cleared a throttle early.
func (c *Controller) recordThrottleStep(ctx context.Context, h *store.Host, was, next store.HostThrottle, audit bool) {
	action := "host.throttle"
	switch {
	case next.Level > was.Level:
		c.log.Info("throttled a host after sustained pressure",
			"host", h.ID, "name", h.Name, "level", next.Level, "was", was.Level,
			"effective_capacity", h.EffectiveCapacity(), "capacity", h.Capacity,
			"cpu_factor", next.CPUFactor(), "reason", next.Reason)
	case next.Active():
		action = "host.throttle_lift"
		c.log.Info("lifted a host's throttle one step after a stretch of calm",
			"host", h.ID, "name", h.Name, "level", next.Level, "was", was.Level,
			"effective_capacity", h.EffectiveCapacity(), "capacity", h.Capacity)
	default:
		action = "host.throttle_lift"
		c.log.Info("lifted a host's throttle",
			"host", h.ID, "name", h.Name, "was", was.Level, "capacity", h.Capacity)
	}
	if audit {
		c.authsvc.Auditor().Act(ctx, auth.SystemIdentity(), action, "host", h.ID, map[string]any{
			"level":              next.Level,
			"reason":             firstNonEmpty(next.Reason, was.Reason),
			"effective_capacity": h.EffectiveCapacity(),
		})
	}
	// The slots the host offers just changed, and both the Hosts page and the
	// next pass have to know: a lift is room a queued job may be waiting for.
	c.publishHost(h)
	c.Nudge()
}

// settleThrottles is the housekeeping half: every host on a rung is run
// through the ladder, so that a host whose agent stopped sending measurements
// -- downgraded, or gone -- is lifted after StaleThrottleReset rather than
// staying throttled for as long as nobody heartbeats. A host with no throttle
// needs nothing here; the heartbeat that could put it on a rung runs the
// ladder itself.
//
// Throttling switched off at runtime is also settled here, by lifting every
// throttle that stands: the heartbeat path stops deciding when the setting is
// off, and a rung nothing will ever step down from again is a cordon nobody
// applied.
func (c *Controller) settleThrottles(ctx context.Context, now time.Time) {
	hosts, err := c.st.ListHosts(ctx)
	if err != nil {
		c.log.Warn("could not list hosts to settle their throttles", "error", err)
		return
	}
	enabled := c.cfg().Scheduler.HostThrottling
	for _, h := range hosts {
		if !h.Throttle.Active() {
			continue
		}
		// The demo fleet's hosts are left alone, as they are everywhere else
		// in housekeeping: its throttled host is a fixture, on a rung so the
		// UI can be looked at with one, and it would otherwise lift itself
		// the moment its seeded measurement went stale.
		if IsDemoID(h.ID) {
			continue
		}
		if !enabled {
			c.log.Info("lifting a host's throttle because scheduler.host_throttling is off", "host", h.ID, "name", h.Name)
			if _, err := c.clearThrottle(ctx, h, true); err != nil {
				c.log.Warn("could not lift a host's throttle", "host", h.ID, "error", err)
			}
			continue
		}
		// A host with a fresh sample is being decided by its heartbeats, and
		// housekeeping has nothing to add but a second decider racing the
		// first. This pass is for the host that has stopped sending samples.
		if h.Usage.Fresh(now) {
			continue
		}
		c.settleThrottle(ctx, h, now)
	}
}

// ClearHostThrottle lifts a host's throttle by hand, whatever rung it is on.
//
// It is the operator's way out once the cause is fixed -- a pool given the
// limits it lacked, a capacity lowered to what the machine can carry --
// without waiting out the recovery the ladder would otherwise ask for. The
// caller audits, because it knows who asked; this writes nothing to the audit
// trail itself. It logs the lift, publishes the host and nudges a pass, since
// the slots it gives back are room a queued job may be waiting on. A host
// that is not throttled is returned unchanged.
//
// Nothing pins a throttle the other way: if the pressure is still there, the
// next heartbeat puts the host back on the first rung, which is the honest
// answer to a clear that was premature.
func (c *Controller) ClearHostThrottle(ctx context.Context, id string) (*store.Host, error) {
	h, err := c.st.GetHost(ctx, id)
	if err != nil {
		return nil, err
	}
	return c.clearThrottle(ctx, h, false)
}

func (c *Controller) clearThrottle(ctx context.Context, h *store.Host, audit bool) (*store.Host, error) {
	if !h.Throttle.Active() {
		return h, nil
	}
	if err := c.st.SetHostThrottle(ctx, h.ID, store.HostThrottle{}, h.Throttle.Level); err != nil {
		if errors.Is(err, store.ErrThrottleMoved) {
			// The rung moved between the read and the clear. Read it again
			// and clear from where it is now: a clear is an instruction
			// about the host, not about the rung it happened to be on.
			fresh, rerr := c.st.GetHost(ctx, h.ID)
			if rerr != nil {
				return nil, rerr
			}
			return c.clearThrottle(ctx, fresh, audit)
		}
		return nil, err
	}
	was := h.Throttle
	h.Throttle = store.HostThrottle{}
	c.recordThrottleStep(ctx, h, was, h.Throttle, audit)
	return h, nil
}

// throttleDirective is what a heartbeat answers about the host's rung. It is
// always sent, level 0 and factor 1 included: an agent that was told to run
// its runners at half their quota has to be told when to stop, and "no field"
// from a controller too old to send one already means "no throttle".
//
// The CPU factor is the ladder's, raised where the host's profile sets a
// minimum runner size so that no runner is throttled below it (see
// scheduler.ThrottleFloorFactor). That is decided here and not on the agent:
// the agent already scales each runner by whatever one factor it is sent, so a
// controller-side floor needs no new field, no feature flag and no protocol
// bump, and an agent that has never heard of profiles obeys it unchanged.
func (c *Controller) throttleDirective(ctx context.Context, h *store.Host) *agent.ThrottleDirective {
	factor := h.Throttle.CPUFactor()
	if floor := h.RunnerProfile.Minimum.CPUs; floor > 0 && factor < 1 {
		factor = max(factor, scheduler.ThrottleFloorFactor(floor, c.limitedContainerCPUs(ctx, h)))
	}
	return &agent.ThrottleDirective{Level: h.Throttle.Level, CPUFactor: factor}
}

// limitedContainerCPUs is the CPU quota each limited container on h was created
// with: one per runner, or two for a docker-in-docker pair -- a typed figure is
// given to both halves, a share is split between them. A runner created with no
// limit has nothing to scale and is left out. A read that fails answers with
// nothing, which leaves the ladder's own factor standing: a throttle that
// cannot find its floor is still a throttle.
func (c *Controller) limitedContainerCPUs(ctx context.Context, h *store.Host) []float64 {
	runners, err := c.st.ListRunnersForHost(ctx, h.ID)
	if err != nil {
		c.log.Warn("could not read a host's runners to find its throttle floor", "host", h.ID, "error", err)
		return nil
	}
	pools := map[string]*store.Pool{}
	var out []float64
	for _, r := range runners {
		if !r.State.Live() || r.AllocatedCPUs <= 0 {
			continue
		}
		p, seen := pools[r.PoolID]
		if !seen {
			p, _ = c.st.GetPool(ctx, r.PoolID)
			pools[r.PoolID] = p
		}
		perHalf := r.AllocatedCPUs
		if p != nil && p.DockerMode == store.DockerDinD && !typedAllocation(r, p.Resources.CPUs > 0) {
			// One slot split between the runner and its daemon.
			perHalf /= 2
		}
		out = append(out, perHalf)
	}
	return out
}

// sameThrottle reports whether two rungs are the same row: the ladder returns
// a fresh value on every call, and only a value that differs is worth a write.
func sameThrottle(a, b store.HostThrottle) bool {
	return a.Level == b.Level && a.Reason == b.Reason &&
		sameInstant(a.Since, b.Since) && sameInstant(a.ChangedAt, b.ChangedAt) && sameInstant(a.CalmSince, b.CalmSince)
}

func sameInstant(a, b *time.Time) bool {
	if a == nil || b == nil {
		return a == b
	}
	return a.Equal(*b)
}

package controller

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// throttleFixture is a joined host and the means to heartbeat it with a
// measurement, which is the only way a throttle is ever decided.
type throttleFixture struct {
	h      *harness
	tr     agent.Transport
	hostID string
	cpu    float64
	load   float64
	memory int64
}

func newThrottleFixture(t *testing.T) *throttleFixture {
	t.Helper()
	h := newHarness(t)
	tr := h.c.EmbeddedTransport()
	joined, err := tr.Join(h.ctx, agent.JoinRequest{ProtocolVersion: agent.ProtocolVersion,
		Name: "pressed", Capacity: 4, CPUs: 8, MemoryMB: 16384,
		Backends: []backend.Info{{Kind: store.BackendDocker, Available: true, Limits: enforcesEverything}}})
	if err != nil {
		t.Fatal(err)
	}
	tr.SetCredentials(joined.HostID, joined.AgentToken)
	// Calm to begin with: CPU well under the bar, one runnable task per two
	// cores, half the memory free.
	return &throttleFixture{h: h, tr: tr, hostID: joined.HostID, cpu: 30, load: 4, memory: 8192}
}

// beat sends the fixture's current measurement and returns the answer and
// the host as the store now has it.
func (f *throttleFixture) beat(t *testing.T) (*agent.HeartbeatResponse, *store.Host) {
	t.Helper()
	cpu, load, memory := f.cpu, f.load, f.memory
	resp, err := f.tr.Heartbeat(f.h.ctx, agent.HeartbeatRequest{Usage: &store.HostUsage{
		CPUPercent: &cpu, LoadAverage1: &load, MemoryAvailableMB: &memory}})
	if err != nil {
		t.Fatal(err)
	}
	host, err := f.h.st.GetHost(f.h.ctx, f.hostID)
	if err != nil {
		t.Fatal(err)
	}
	return resp, host
}

func (f *throttleFixture) audits(t *testing.T, action string) int {
	t.Helper()
	rows, _, err := f.h.st.ListAudit(f.h.ctx, store.AuditFilter{Actions: []string{action}, TargetID: f.hostID}, store.Page{Limit: 50})
	if err != nil {
		t.Fatalf("ListAudit: %v", err)
	}
	return len(rows)
}

// A host whose load average has run past twice its cores is a host being
// pushed harder than it can go, and the pressure holds alone would only
// bounce it in and out of admission. The ladder takes a quarter of its slots
// and tells its agent to run the jobs at three quarters of their quota, and
// every surface an operator reads -- the row, the view, the problems drawer,
// the audit trail, the metrics -- says the same thing about it.
func TestASustainedLoadAverageThrottlesAHost(t *testing.T) {
	f := newThrottleFixture(t)
	h := f.h
	f.load = 20
	resp, host := f.beat(t)

	if resp.Throttle == nil || resp.Throttle.Level != 1 || resp.Throttle.CPUFactor != 0.75 {
		t.Fatalf("heartbeat answered %+v, want the agent told about rung 1 at three quarters", resp.Throttle)
	}
	if host.Throttle.Level != 1 || host.EffectiveCapacity() != 3 || host.Throttle.Since == nil {
		t.Fatalf("host row = %+v with effective capacity %d, want rung 1 of 4 slots leaving 3", host.Throttle, host.EffectiveCapacity())
	}
	view := h.c.HostView(host)
	if view.Throttle == nil || view.Throttle.Level != 1 || view.EffectiveCapacity != 3 || view.Free != 3 ||
		!strings.Contains(view.ThrottleReason, "load average is 20.0") {
		t.Fatalf("host view = throttle %+v, effective %d, free %d, reason %q", view.Throttle, view.EffectiveCapacity, view.Free, view.ThrottleReason)
	}
	p := h.problem(t, "host.throttled")
	if p.Severity != config.SeverityWarning || !strings.Contains(p.Detail, "pressed") || !strings.Contains(p.Detail, "3 of 4 slots") {
		t.Fatalf("host.throttled = %+v; it has to name the host and what it was stepped down to", p)
	}
	if f.audits(t, "host.throttle") != 1 {
		t.Fatalf("host.throttle audit rows = %d, want 1", f.audits(t, "host.throttle"))
	}
	for name, want := range map[string]float64{
		"zoomies_host_throttle_level":     1,
		"zoomies_host_load_average_1m":    20,
		"zoomies_host_effective_capacity": 3,
		"zoomies_host_capacity":           4,
	} {
		labels := map[string]string{}
		if strings.HasSuffix(name, "_level") || strings.HasSuffix(name, "_1m") {
			labels["host"] = host.ID
		}
		if got, ok := gatherValue(t, h.c, name, labels); !ok || got != want {
			t.Errorf("%s = %v (%v), want %v", name, got, ok, want)
		}
	}
	stats, err := h.c.Stats(h.ctx, time.Hour)
	if err != nil {
		t.Fatal(err)
	}
	if stats.Hosts.Capacity != 3 {
		t.Errorf("Stats.Hosts.Capacity = %d, want the 3 slots the throttle leaves rather than the 4 configured", stats.Hosts.Capacity)
	}
	pool := h.pool(h.installation(), "linux-x64")
	if got := eligibleCapacity(pool, []*store.Host{host}, h.c.Now()); got != 3 {
		t.Errorf("capacity-demand eligible capacity = %d, want 3; a provisioner told 4 would never be asked for the slot the queue is short of", got)
	}

	// The next rung waits for ThrottleStep, because a quota lowered on a
	// live container takes a while to show in a load average that itself
	// averages over a minute.
	if resp, _ := f.beat(t); resp.Throttle.Level != 1 {
		t.Fatalf("a second overwhelmed beat inside ThrottleStep moved the rung to %d", resp.Throttle.Level)
	}
	h.advance(scheduler.ThrottleStep)
	resp, host = f.beat(t)
	if resp.Throttle.Level != 2 || resp.Throttle.CPUFactor != 0.5 || host.EffectiveCapacity() != 2 {
		t.Fatalf("after ThrottleStep: %+v, effective %d; want rung 2 at half quota leaving 2 slots", resp.Throttle, host.EffectiveCapacity())
	}
}

// A throttle comes off one rung at a time, and only after a stretch of calm
// long enough to mean something: a host that recovered for a minute and was
// pushed straight back over would otherwise oscillate with the ladder. The
// step down is audited as a lift, so the trail reads as a pair.
func TestAThrottleLiftsOneStepAfterCalm(t *testing.T) {
	f := newThrottleFixture(t)
	h := f.h
	f.load = 20
	f.beat(t)
	h.advance(scheduler.ThrottleStep)
	if _, host := f.beat(t); host.Throttle.Level != 2 {
		t.Fatalf("setup: level %d, want 2", host.Throttle.Level)
	}

	f.load = 2
	_, host := f.beat(t)
	if host.Throttle.Level != 2 || host.Throttle.CalmSince == nil {
		t.Fatalf("one calm beat: %+v; want the rung kept and the calm streak started", host.Throttle)
	}
	h.advance(scheduler.ThrottleRecovery / 2)
	if _, host := f.beat(t); host.Throttle.Level != 2 {
		t.Fatalf("half a recovery of calm already stepped the host down to %d", host.Throttle.Level)
	}
	h.advance(scheduler.ThrottleRecovery / 2)
	resp, host := f.beat(t)
	if host.Throttle.Level != 1 || resp.Throttle.Level != 1 || resp.Throttle.CPUFactor != 0.75 {
		t.Fatalf("after ThrottleRecovery of calm: row %+v, answer %+v; want rung 1", host.Throttle, resp.Throttle)
	}
	if f.audits(t, "host.throttle_lift") != 1 {
		t.Fatalf("host.throttle_lift audit rows = %d, want 1", f.audits(t, "host.throttle_lift"))
	}
	h.advance(scheduler.ThrottleRecovery)
	resp, host = f.beat(t)
	if host.Throttle.Active() || resp.Throttle.Level != 0 || resp.Throttle.CPUFactor != 1 {
		t.Fatalf("after a second recovery: row %+v, answer %+v; want no throttle and the agent told to restore every quota", host.Throttle, resp.Throttle)
	}
	if h.c.HostView(host).Throttle != nil || contains(h.problemCodes(), "host.throttled") {
		t.Fatal("a lifted throttle is still on the view or in the problems drawer")
	}
}

// An operator who has fixed the cause -- a pool given limits, a capacity
// lowered -- should not have to wait out the recovery. The clear lifts every
// rung at once, publishes the host, and writes no audit row of its own: the
// API records who asked, and a system row beside it would say the ladder
// decided something a person did.
func TestAnOperatorCanClearAThrottle(t *testing.T) {
	f := newThrottleFixture(t)
	h := f.h
	f.load = 20
	f.beat(t)
	h.advance(scheduler.ThrottleStep)
	f.beat(t)

	// Drain the nudge the heartbeats left, so the one below is the clear's.
	select {
	case <-h.c.nudges:
	default:
	}
	host, err := h.c.ClearHostThrottle(h.ctx, f.hostID)
	if err != nil {
		t.Fatalf("ClearHostThrottle: %v", err)
	}
	if host.Throttle.Active() || host.EffectiveCapacity() != 4 {
		t.Fatalf("cleared host = %+v with effective capacity %d", host.Throttle, host.EffectiveCapacity())
	}
	stored, err := h.st.GetHost(h.ctx, f.hostID)
	if err != nil {
		t.Fatal(err)
	}
	if stored.Throttle.Active() {
		t.Fatal("the clear was not persisted")
	}
	if f.audits(t, "host.throttle_lift") != 0 || f.audits(t, "host.throttle_clear") != 0 {
		t.Fatal("ClearHostThrottle wrote an audit row; that is the caller's, under the operator's name")
	}
	if len(h.c.nudges) != 1 {
		t.Fatal("the clear did not nudge a pass; the slots it gave back would wait for the interval")
	}

	// Nothing pins it: the pressure is still there, so the next beat puts
	// the host straight back on the first rung.
	if resp, _ := f.beat(t); resp.Throttle.Level != 1 {
		t.Fatalf("after a premature clear the next beat answered %+v, want rung 1 again", resp.Throttle)
	}
	// And an unthrottled host is returned unchanged rather than refused.
	if _, err := h.c.ClearHostThrottle(h.ctx, f.hostID); err != nil {
		t.Fatalf("clearing again: %v", err)
	}
}

// A host whose agent stopped sending measurements -- downgraded to a build
// without them, or gone -- must not stay throttled for as long as nobody
// heartbeats. Housekeeping runs the ladder for it, and the ladder lifts a
// throttle its measurements have been stale on for StaleThrottleReset.
func TestHousekeepingLiftsAThrottleWhoseHostStoppedMeasuring(t *testing.T) {
	f := newThrottleFixture(t)
	h := f.h
	f.load = 20
	if _, host := f.beat(t); host.Throttle.Level != 1 {
		t.Fatalf("setup: %+v", host.Throttle)
	}

	h.advance(scheduler.StaleThrottleReset - time.Second)
	h.c.settleThrottles(h.ctx, h.c.Now())
	host, err := h.st.GetHost(h.ctx, f.hostID)
	if err != nil {
		t.Fatal(err)
	}
	if !host.Throttle.Active() {
		t.Fatal("a stale sample lifted the throttle before StaleThrottleReset; a host that merely missed a few beats would be handed its slots back")
	}
	h.advance(2 * time.Second)
	h.c.settleThrottles(h.ctx, h.c.Now())
	host, err = h.st.GetHost(h.ctx, f.hostID)
	if err != nil {
		t.Fatal(err)
	}
	if host.Throttle.Active() {
		t.Fatalf("after StaleThrottleReset the host is still on rung %d", host.Throttle.Level)
	}
	if f.audits(t, "host.throttle_lift") != 1 {
		t.Fatalf("host.throttle_lift audit rows = %d, want 1 for the stale reset", f.audits(t, "host.throttle_lift"))
	}
}

// scheduler.host_throttling off means no host is ever put on a rung, and a
// host already on one when the setting is turned off is lifted rather than
// left there for ever with nothing to step it down.
func TestThrottlingOffDecidesNothingAndLiftsWhatStands(t *testing.T) {
	f := newThrottleFixture(t)
	h := f.h
	h.c.UpdateConfig(func(cfg *config.Config) { cfg.Scheduler.HostThrottling = false })
	f.load = 20
	resp, host := f.beat(t)
	if host.Throttle.Active() || resp.Throttle == nil || resp.Throttle.Level != 0 || resp.Throttle.CPUFactor != 1 {
		t.Fatalf("with throttling off: row %+v, answer %+v; want no rung and the agent still told so", host.Throttle, resp.Throttle)
	}

	// A rung left over from before the setting was turned off.
	now := h.c.Now()
	if err := h.st.SetHostThrottle(h.ctx, f.hostID, store.HostThrottle{Level: 2, Since: &now, ChangedAt: &now, Reason: "earlier"}, 0); err != nil {
		t.Fatal(err)
	}
	h.c.settleThrottles(h.ctx, h.c.Now())
	host, err := h.st.GetHost(h.ctx, f.hostID)
	if err != nil {
		t.Fatal(err)
	}
	if host.Throttle.Active() {
		t.Fatalf("housekeeping left a host on rung %d with throttling off", host.Throttle.Level)
	}
	if f.audits(t, "host.throttle_lift") != 1 {
		t.Fatalf("host.throttle_lift audit rows = %d, want 1", f.audits(t, "host.throttle_lift"))
	}
}

// A host that joins again starts on no rung: the throttle was decided from
// measurements of a machine that has just been rebuilt or restarted. If the
// pressure is still there its first heartbeats put it straight back.
func TestARejoiningHostStartsOnNoRung(t *testing.T) {
	f := newThrottleFixture(t)
	h := f.h
	f.load = 20
	if _, host := f.beat(t); !host.Throttle.Active() {
		t.Fatal("setup: not throttled")
	}
	joined, err := f.tr.Join(h.ctx, agent.JoinRequest{ProtocolVersion: agent.ProtocolVersion,
		Name: "pressed", Capacity: 4, CPUs: 8, MemoryMB: 16384,
		Backends: []backend.Info{{Kind: store.BackendDocker, Available: true, Limits: enforcesEverything}}})
	if err != nil {
		t.Fatal(err)
	}
	host, err := h.st.GetHost(h.ctx, joined.HostID)
	if err != nil {
		t.Fatal(err)
	}
	if host.Throttle.Active() {
		t.Fatalf("a re-joined host is still on rung %d", host.Throttle.Level)
	}
}

// The reason a host takes no new runner used to fall through to "upgrade its
// agent" for every case the sentence had no words for, so a host held for
// pressure or throttled to its last slot was told to upgrade. Each is its own
// job and gets its own sentence.
func TestUnavailableReasonNamesAHoldAndAThrottle(t *testing.T) {
	now := time.Now()
	fresh := now.Add(-time.Second)
	held := &store.Host{Name: "held", Capacity: 4, CPUs: 8, MemoryMB: 16384, LastHeartbeat: now,
		Usage: store.HostUsage{SampledAt: fresh, CPUHeld: true}}
	throttled := &store.Host{Name: "throttled", Capacity: 4, CPUs: 8, MemoryMB: 16384, LastHeartbeat: now,
		ActiveRunners: 2, Throttle: store.HostThrottle{Level: 2}}
	roomy := &store.Host{Name: "roomy", Capacity: 4, CPUs: 8, MemoryMB: 16384, LastHeartbeat: now,
		ActiveRunners: 1, Throttle: store.HostThrottle{Level: 2}}
	old := &store.Host{Name: "old", Capacity: 4, LastHeartbeat: now, Incompatible: true}
	for _, tc := range []struct {
		host *store.Host
		want string
	}{
		{held, "under pressure"},
		{throttled, "throttled to 2 of its 4 slots"},
		{old, "protocol"},
		// A throttled host with a slot free is not unavailable at all; the
		// sentence for it is the last resort, never the upgrade advice.
		{roomy, "takes no new runners right now"},
	} {
		if got := unavailableReason(tc.host, now); !strings.Contains(got, tc.want) {
			t.Errorf("%s: reason %q does not say %q", tc.host.Name, got, tc.want)
		}
	}
	if !roomy.Available(now) {
		t.Error("a throttled host with a slot left under its effective capacity should still be available")
	}
	if throttled.Available(now) {
		t.Error("a throttled host at its effective capacity should not be available")
	}
}

package controller

import (
	"context"

	"github.com/eyupio/zoomies/internal/store"
)

func (c *Controller) confirmCleanup(ctx context.Context, id string, host bool) error {
	completed, err := c.st.ConfirmRunnerCleanup(ctx, id, host)
	if err != nil {
		c.log.Warn("could not record confirmed cleanup", "runner", id, "host_confirmation", host, "error", err)
		return err
	}
	r, err := c.st.GetRunner(ctx, id)
	if err != nil {
		return err
	}
	if completed && r.FinishedAt != nil && r.CleanedUpAt != nil {
		if p, err := c.st.GetPool(ctx, r.PoolID); err == nil && !IsDemoID(p.InstallationID) {
			observeDuration(c.metrics.cleanupDuration, p.Name, string(p.Backend), *r.FinishedAt, *r.CleanedUpAt)
		}
	}
	c.publishRunnerByID(ctx, id)
	return nil
}

// Observe the job's actual runner once the association is known, not the
// first queued job found when any runner in its pool was created. Prewarmed
// runners and jobs whose eligibility was never observed have no sample.
func (c *Controller) observeScheduling(ctx context.Context, j *store.Job, change store.JobChange, r *store.Runner) {
	firstStart := (j.State == store.JobInProgress || j.State == store.JobCompleted) &&
		(change.RunnerLinked || ((change.Created || change.StateChanged) &&
			change.PreviousState != store.JobInProgress && change.PreviousState != store.JobCompleted))
	if !firstStart || j.EligibleAt == nil || j.RunnerID == "" || IsDemoID(j.InstallationID) {
		return
	}
	if r == nil {
		var err error
		r, err = c.st.GetRunner(ctx, j.RunnerID)
		if err != nil {
			return
		}
	}
	if r.CreateTaskIssuedAt == nil {
		return
	}
	if p, err := c.st.GetPool(ctx, r.PoolID); err == nil && p.InstallationID == j.InstallationID {
		observeDuration(c.metrics.schedulingLatency, p.Name, string(p.Backend), *j.EligibleAt, *r.CreateTaskIssuedAt)
	}
}

package controller

import (
	"context"
	"testing"
	"time"

	"github.com/prometheus/client_golang/prometheus"
	dto "github.com/prometheus/client_model/go"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/store"
)

func timingSample(t *testing.T, h *prometheus.HistogramVec, pool, backend string) (uint64, float64) {
	t.Helper()
	var m dto.Metric
	if err := h.WithLabelValues(pool, backend).(prometheus.Metric).Write(&m); err != nil {
		t.Fatal(err)
	}
	return m.GetHistogram().GetSampleCount(), m.GetHistogram().GetSampleSum()
}

func TestSchedulingTimingUsesTheJobsActualRunnerOnce(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	h.deliverJob(jobEvent{Action: "queued", JobID: 9201, Labels: []string{"self-hosted", "linux", "x64", "demo"}})
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatal(err)
	}
	h.advance(5 * time.Second)
	if _, err := h.c.PollTasks(h.ctx, host.ID, time.Second); err != nil {
		t.Fatal(err)
	}
	r := h.onlyRunner()
	first := *r.CreateTaskIssuedAt
	h.advance(time.Minute)
	h.c.stampIssued(h.ctx, []agent.Task{{Kind: agent.TaskCreateRunner, RunnerID: r.ID, IssuedAt: h.c.Now()}})
	h.deliverJob(jobEvent{Action: "in_progress", JobID: 9201, RunnerName: r.Name, Labels: []string{"self-hosted", "linux", "x64", "demo"}})
	h.deliverJob(jobEvent{Action: "in_progress", JobID: 9201, RunnerName: r.Name, Labels: []string{"self-hosted", "linux", "x64", "demo"}})
	jobs, _, err := h.st.ListJobs(h.ctx, store.JobFilter{}, store.Page{})
	if err != nil || len(jobs) != 1 || jobs[0].EligibleAt == nil {
		t.Fatalf("job eligibility: %+v, %v", jobs, err)
	}
	count, sum := timingSample(t, h.c.metrics.schedulingLatency, pool.Name, string(pool.Backend))
	if count != 1 || sum != first.Sub(*jobs[0].EligibleAt).Seconds() {
		t.Fatalf("scheduling histogram = %d samples, %v seconds; want one first-delivery interval", count, sum)
	}
}

func TestCleanupMetricWaitsForBothSidesAndDoesNotCountRetries(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerIdle)
	if _, err := h.st.TransitionRunner(h.ctx, r.ID, store.RunnerRemoved, "finished"); err != nil {
		t.Fatal(err)
	}
	h.c.confirmCleanup(h.ctx, r.ID, false)
	if count, _ := timingSample(t, h.c.metrics.cleanupDuration, pool.Name, string(pool.Backend)); count != 0 {
		t.Fatal("registration removal alone produced a cleanup timing")
	}
	h.advance(2 * time.Minute)
	h.c.confirmCleanup(h.ctx, r.ID, true)
	h.c.confirmCleanup(h.ctx, r.ID, true)
	h.c.confirmCleanup(h.ctx, r.ID, false)
	count, sum := timingSample(t, h.c.metrics.cleanupDuration, pool.Name, string(pool.Backend))
	finished := h.runnerByID(t, r.ID)
	want := finished.CleanedUpAt.Sub(*finished.FinishedAt).Seconds()
	if count != 1 || sum != want {
		t.Fatalf("cleanup histogram = %d samples, %v seconds; want one confirmed interval of %v seconds", count, sum, want)
	}
}

func TestCleanupReportsAreNotAcknowledgedWhenTheStoreCannotBeRead(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerRemoved)
	report := agent.RunnerReport{RunnerID: r.ID, State: store.RunnerRemoved, HostRemoved: true}
	ctx, cancel := context.WithCancel(h.ctx)
	cancel()
	if err := h.c.ReportRunners(ctx, host.ID, []agent.RunnerReport{report}); err == nil {
		t.Fatal("a failed database read acknowledged the cleanup receipt")
	}
	if err := h.c.ReportRunners(h.ctx, host.ID, []agent.RunnerReport{report}); err != nil {
		t.Fatal(err)
	}
	if h.runnerByID(t, r.ID).HostRemovedAt == nil {
		t.Fatal("the retried receipt was not stored")
	}
}

package controller

import (
	"context"
	"fmt"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/naming"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/version"
)

// A pool that keeps its work folder or /tmp in memory spends its memory limit
// on disk speed. Three things can go wrong with that without anything failing
// loudly, and each is said where the pool is edited rather than found out from
// a job that ran out of memory.

// tmpfsMemoryWarning proposes the memory limit a pool's in-memory folders need.
//
// A tmpfs is charged to the runner's own cgroup, so the room it may fill comes
// out of the limit the pool was sized with for the job. Switching it on without
// raising the limit leaves the job less than it had, which shows up much later
// as an out-of-memory kill in a build that always passed. The proposal is the
// limit plus what the folders may fill: the same room for the job, with the
// folders on top. It is a proposal and never an edit, because the limit is also
// what the scheduler charges the host for, and raising it changes how many
// runners fit.
//
// Two cases speak. Sizes an operator typed that take more than half the limit
// are a warning, because a job that fills them is out of memory. Folders left
// to size themselves are fitted into half the limit, so they cannot do that;
// when the limit is too small to give them their defaults the fitting is only
// information -- they work, and are smaller than they would be.
func tmpfsMemoryWarning(p *store.Pool) (Problem, bool) {
	limit := p.Resources.MemoryMB
	if limit <= 0 || !p.Tmpfs.Any() {
		return Problem{}, false
	}
	// A typed limit is given to the runner and to the daemon alike, and each is
	// charged for its own folders, so each is judged against it separately: the
	// work folder and /tmp are the runner's, the image store is the daemon's.
	// Placed as the agent places them, so an automatic folder that is on disk
	// here takes no memory and is not a reason to warn: autoKeptOnDisk says it.
	var runner, daemon int64
	short := false
	for _, o := range outcomes(p.Tmpfs, limit, limit, store.HostTmpfs{}) {
		if o.Daemon {
			daemon += o.Got
		} else {
			runner += o.Got
		}
		short = short || o.Got > 0 && o.Got < o.Ask
	}
	severity := config.SeverityInfo
	var title, detail string
	switch {
	case runner*2 > limit || daemon*2 > limit:
		severity = config.SeverityWarning
		title = fmt.Sprintf("pool %s: its in-memory folders may take more than half of its memory limit", p.Name)
		detail = fmt.Sprintf("a tmpfs is charged to the memory limit of the container it is in, so the job has what the folders leave. "+
			"This pool's limit is %s and %s, so a job that fills them is killed for want of memory.",
			formatRoomMB(limit), tightFolders(runner, daemon, limit))
	case short:
		title = fmt.Sprintf("pool %s: its in-memory folders were fitted to a small memory limit", p.Name)
		detail = fmt.Sprintf("a tmpfs is charged to the memory limit of the container it is in, so folders left to size themselves are fitted into half of it. "+
			"This pool's limit is %s, which is not enough to give them the size they would be given with room.",
			formatRoomMB(limit))
	default:
		return Problem{}, false
	}
	return Problem{
		Code:     "pool.tmpfs_memory_tight",
		Severity: severity,
		Title:    title,
		Detail:   detail,
		Fix: fmt.Sprintf("raise the pool's memory limit to %s, which leaves the job the %s it has now with the folders on top, or shrink the folders.",
			formatRoomMB(p.Tmpfs.RecommendedMemoryMB(limit)), formatRoomMB(limit)),
		TargetKind: "pool",
		TargetID:   p.ID,
	}, true
}

// tightFolders says which container's folders take more than half the limit.
func tightFolders(runner, daemon, limit int64) string {
	switch {
	case runner*2 > limit && daemon*2 > limit:
		return fmt.Sprintf("the runner's folders may fill %s and the Docker image store %s", formatRoomMB(runner), formatRoomMB(daemon))
	case daemon*2 > limit:
		return fmt.Sprintf("the Docker image store may fill %s", formatRoomMB(daemon))
	default:
		return fmt.Sprintf("its folders may fill %s", formatRoomMB(runner))
	}
}

// cacheInMemoryWarning is a pool cache kept in a memory-backed directory with
// nothing to stop it growing.
//
// The pool cache is shared by one runner after another, which is why it cannot
// be a tmpfs of each container's own -- every runner would start with it cold.
// The form that works is a directory the host mounts in memory, such as
// /dev/shm, given as the cache source. There the host's RAM is the disk, and
// the only thing evicting from it is the cache's size limit: without one the
// cache grows until the host is out of memory, which takes every runner and the
// agent with it. The limit is refused on a named volume because it cannot be
// measured there, and is accepted on this path because it can.
func cacheInMemoryWarning(p *store.Pool) (Problem, bool) {
	if !p.Cache.Enabled || p.Cache.SizeLimit > 0 {
		return Problem{}, false
	}
	source := filepath.Clean(strings.TrimSpace(p.Cache.Source))
	if source != "/dev/shm" && !strings.HasPrefix(source, "/dev/shm/") {
		return Problem{}, false
	}
	return Problem{
		Code:     "pool.cache_memory_unbounded",
		Severity: config.SeverityWarning,
		Title:    fmt.Sprintf("pool %s: its cache is kept in memory and has no size limit", p.Name),
		Detail: "the cache source is under /dev/shm, which is the host's memory. The cache is evicted only down to its size limit, " +
			"so with none it grows until the host has no memory left, and that takes the runners and the agent with it.",
		Fix:        "set the cache's size limit, keeping it well inside what the smallest host can spare in memory, or move the cache source to a directory on disk.",
		TargetKind: "pool",
		TargetID:   p.ID,
	}, true
}

// heldWithoutTmpfs names the hosts on which an in-memory pool is not in memory.
//
// Mounting the folders is the agent's work, and an agent too old to advertise
// that it can ignores the setting and starts the runner on disk: a safe
// outcome, and an invisible one, for the same reason heldByOldAgents gives for
// elastic CPU. The warning is where the pool is saved, with the hosts named.
//
// Only the hosts the pool can be placed on count: one its runner profile keeps
// the pool off is listed in the room with no room, and is not a host the pool
// will ever land on, so naming it would be a warning about nothing.
func heldWithoutTmpfs(p *store.Pool, hosts []PoolHostRoom) (Problem, bool) {
	if !p.Tmpfs.Any() {
		return Problem{}, false
	}
	var names []string
	for _, h := range hosts {
		// A host whose operator turned the folders off is not running an old agent
		// as far as the pool is concerned: that is its own, deliberate, answer.
		if !h.Tmpfs && !h.TmpfsOff {
			names = append(names, h.Host)
		}
	}
	if len(names) == 0 {
		return Problem{}, false
	}
	runs := "run"
	if len(names) == 1 {
		runs = "runs"
	}
	return Problem{
		Code:     "pool.tmpfs_unsupported",
		Severity: config.SeverityWarning,
		Title: fmt.Sprintf("pool %s: %d of its %s %s an agent that cannot keep folders in memory",
			p.Name, len(names), plural(len(hosts), "host"), runs),
		Detail: "the agent on a host mounts the in-memory folders, and these agents are too old to say they can: " +
			strings.Join(names, ", ") + ". A runner placed there starts with its folders on disk, exactly as with the setting off, " +
			"and nothing on the pool says which of its runners that happened to.",
		Fix: "upgrade the agent on those hosts -- the command is on each host's card under Hosts -- " +
			"or point the pool at other hosts with its host selector until they are.",
		TargetKind: "pool",
		TargetID:   p.ID,
	}, true
}

// heldWithoutDaemonShare names the hosts on which a docker-in-docker pool's sidecar
// share is not honoured.
//
// The share is applied by the agent that creates the pair. An agent too old to
// advertise that it can splits the slot evenly whatever the pool says, while the ledger
// charges the pair by the share: the pool reads 80% and the daemon is given half, with
// nothing to say so. Only a pool that asks for something other than the even split is
// affected, and only the hosts it can be placed on count.
func heldWithoutDaemonShare(p *store.Pool, hosts []PoolHostRoom) (Problem, bool) {
	if p.DockerMode != store.DockerDinD || p.FromHosts() {
		return Problem{}, false
	}
	if p.Resources.DaemonCPUPercent() == store.DefaultDaemonSharePercent && p.Resources.DaemonMemoryPercent() == store.DefaultDaemonSharePercent {
		return Problem{}, false
	}
	var names []string
	for _, h := range hosts {
		if !h.DaemonShare {
			names = append(names, h.Host)
		}
	}
	if len(names) == 0 {
		return Problem{}, false
	}
	return Problem{
		Code:     "pool.daemon_share_unsupported",
		Severity: config.SeverityWarning,
		Title: fmt.Sprintf("pool %s: %d of its %s %s an agent that does not divide a slot by the sidecar's share",
			p.Name, len(names), plural(len(hosts), "host"), map[bool]string{true: "runs", false: "run"}[len(names) == 1]),
		Detail: "the agent on a host divides a docker-in-docker slot between the runner and its daemon, and these agents are too old to say they follow the pool's shares: " +
			strings.Join(names, ", ") + ". A runner placed there is given half of the slot for each container whatever the share says, while the host is charged by the share.",
		Fix: "upgrade the agent on those hosts -- the command is on each host's card under Hosts -- " +
			"or point the pool at other hosts with its host selector until they are.",
		TargetKind: "pool",
		TargetID:   p.ID,
	}, true
}

// daemonShareHostProblems is the standing form of heldWithoutDaemonShare: the dry run
// warns while a pool is being edited, and this keeps saying so afterwards, because an
// agent that is not upgraded splits the slot evenly with nothing on the pool to show it.
func (c *Controller) daemonShareHostProblems(ctx context.Context, out *[]Problem) error {
	pools, err := c.fleetPools(ctx)
	if err != nil {
		return fmt.Errorf("listing pools: %w", err)
	}
	for _, p := range pools {
		if !p.Enabled || p.DockerMode != store.DockerDinD {
			continue
		}
		room, err := c.PoolRoom(ctx, p)
		if err != nil {
			return fmt.Errorf("counting the room pool %s has: %w", p.Name, err)
		}
		if w, ok := heldWithoutDaemonShare(p, room.Placeable()); ok {
			*out = append(*out, w)
		}
	}
	return nil
}

// keptOnDiskByHost names the hosts where an operator has turned in-memory
// folders off.
//
// It is information and not a warning: a machine's owner knows how much memory
// it has and the pool's does not, so the host having the last word is the design,
// not a mistake. It is said anyway, where the pool is saved, because a pool that
// asks for folders in memory and is placed on such a host runs there exactly as
// it always did, and nothing on the pool says which of its runners that was.
func keptOnDiskByHost(p *store.Pool, hosts []PoolHostRoom) (Problem, bool) {
	if !p.Tmpfs.Any() {
		return Problem{}, false
	}
	var names []string
	for _, h := range hosts {
		if h.TmpfsOff {
			names = append(names, h.Host)
		}
	}
	if len(names) == 0 {
		return Problem{}, false
	}
	return Problem{
		Code:     "pool.tmpfs_host_off",
		Severity: config.SeverityInfo,
		Title: fmt.Sprintf("pool %s: %s keep in-memory folders off", p.Name,
			plural(len(names), "host")),
		Detail: "an operator turned in-memory folders off in the runner profile of " + strings.Join(names, ", ") +
			", so a runner of this pool placed there has its folders on disk, as it would with the setting off.",
		Fix: "nothing, if that is what the host's owner meant. To use memory there, clear \"Keep in-memory folders off this machine\" under Runner sizes on the host's card " +
			"-- or run zoomies hosts edit with --tmpfs-off=false -- or point this pool at other hosts with its host selector.",
		TargetKind: "pool",
		TargetID:   p.ID,
	}, true
}

// hostSupportsTmpfs is whether a host's agent mounts in-memory folders.
func hostSupportsTmpfs(h *store.Host) bool { return h.Supports(agent.FeatureTmpfs) }

const (
	// tmpfsAdviceWindow is how far back a pool must have run jobs on a host for
	// that host to say anything about the pool. I/O wait is the whole machine's,
	// and a host can be waiting on a disk that none of this pool's jobs touch.
	tmpfsAdviceWindow = 6 * time.Hour
	// tmpfsAdviceMinJobs keeps a single job that happened to land there from
	// speaking for the pool.
	tmpfsAdviceMinJobs = 3
)

// tmpfsAdviceProblems suggests keeping the work folder in memory, to the pool
// that would gain from it.
//
// It speaks only when three things are all true of one host: the pool has run
// jobs there recently, the host has been waiting on its disk for a sustained
// stretch (HostUsage.DiskBound -- the figure CPU occupancy hides, since it
// counts that wait as busy), and it has the memory to spare for the folder
// beyond its own reserve. Each is there because without it the advice is wrong
// or unusable: a pool whose jobs never touched that disk is not helped by
// moving its folder, and a host with no memory left cannot take one.
//
// Nothing is stored. The list is recomputed every pass, so the suggestion stays
// for exactly as long as the three are true -- continued, as an operator asked,
// rather than raised once and forgotten -- and goes the moment the pool turns
// the setting on, the disk calms, or the memory is spent. Since is when the
// earliest of those hosts began waiting, which a standing condition does not
// move, so the list is not rewritten while it stands.
//
// It is information, never a warning: nothing is failing, only slower than it
// needs to be, and the setting trades memory for it.
func (c *Controller) tmpfsAdviceProblems(ctx context.Context, out *[]Problem) error {
	pools, err := c.fleetPools(ctx)
	if err != nil {
		return fmt.Errorf("listing pools: %w", err)
	}
	var candidates []*store.Pool
	for _, p := range pools {
		if !p.Enabled || p.Tmpfs.Work.Enabled {
			continue
		}
		if p.Backend != store.BackendDocker && p.Backend != store.BackendPodman {
			continue
		}
		candidates = append(candidates, p)
	}
	if len(candidates) == 0 {
		return nil
	}
	hosts, err := c.fleetHosts(ctx)
	if err != nil {
		return fmt.Errorf("listing hosts: %w", err)
	}
	now := c.Now()
	var bound []*store.Host
	for _, h := range hosts {
		// A host whose operator turned the folders off cannot be helped by a
		// suggestion to use them.
		if h.Cordoned || h.Incompatible || h.RunnerProfile.Tmpfs.Disabled || !h.Usage.DiskBound(now) {
			continue
		}
		bound = append(bound, h)
	}
	if len(bound) == 0 {
		return nil
	}
	since := now.Add(-tmpfsAdviceWindow)
	stats, err := c.st.JobStatsOf(ctx, store.JobFilter{Since: &since}, []string{store.GroupByPool, store.GroupByHost}, store.MeasureCounts)
	if err != nil {
		return fmt.Errorf("counting recent jobs: %w", err)
	}
	ran := make(map[[2]string]int, len(stats.Groups))
	for _, g := range stats.Groups {
		ran[[2]string{g.Keys[store.GroupByPool], g.Keys[store.GroupByHost]}] += g.Count
	}

	// What the folder would be given on an empty runner is what the host must
	// have to spare: the default, since the pool has not chosen a size.
	room := store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true}}
	for _, p := range candidates {
		var names []string
		var earliest *time.Time
		for _, h := range bound {
			if ran[[2]string{p.ID, h.ID}] < tmpfsAdviceMinJobs {
				continue
			}
			// What the folder needs from this host is what it would be given here, which
			// the host's own ceiling may lower.
			need := room.ReserveMB()
			if ceiling := h.RunnerProfile.Tmpfs.MaxMB; ceiling > 0 {
				need = min(need, ceiling)
			}
			avail := h.Usage.MemoryAvailableMB
			if avail == nil || *avail-h.MemoryReserve() < need {
				continue
			}
			names = append(names, naming.ForSentence(h.Name))
			if at := h.Usage.IOWaitHighSince; at != nil && (earliest == nil || at.Before(*earliest)) {
				earliest = at
			}
		}
		if len(names) == 0 {
			continue
		}
		sort.Strings(names)
		fix := fmt.Sprintf("turn on the in-memory work folder for pool %s -- Keep the work folder in memory in the pool editor, or zoomies pools edit with --tmpfs-work -- and compare a few runs.", p.Name)
		if p.DockerMode == store.DockerDinD {
			// The sidecar's image store is where a dind job's pulls and builds are
			// written, so on a pool like this it is likely the larger share of the
			// traffic; it is its own choice because an image bigger than the mount
			// does not pull.
			fix += " This pool builds inside Docker-in-Docker, where the daemon writes every pulled image and built layer: its image store can be kept in memory too (--tmpfs-docker), if the images it pulls fit."
		}
		if rec := room.RecommendedMemoryMB(p.Resources.MemoryMB); rec > 0 {
			fix += fmt.Sprintf(" The folder is charged to the runner memory limit, so raise that limit to %s to leave the job the room it has now.", formatRoomMB(rec))
		}
		*out = append(*out, Problem{
			Code:     "pool.tmpfs_suggested",
			Severity: config.SeverityInfo,
			Title:    fmt.Sprintf("pool %s: its jobs have been waiting on disk while its machines have memory to spare", p.Name),
			Detail: fmt.Sprintf("%s: the disk has been the bottleneck for at least ten minutes, with I/O wait above %.0f%%, and this pool has run jobs there since. "+
				"A checkout, an install or a build writes a great many small files, and on a disk that cannot keep up that is where a job spends its time. "+
				"Each of these machines has memory free beyond its reserve -- at least %s -- which is room for the work folder to live in memory instead.",
				strings.Join(names, ", "), store.IOWaitHighPercent, formatRoomMB(room.ReserveMB())),
			Fix:        fix,
			TargetKind: "pool",
			TargetID:   p.ID,
			Since:      earliest,
		})
	}
	return nil
}

// tmpfsHostProblems says, for as long as it is true, which hosts a pool that
// keeps folders in memory is not in memory on. The same two sentences come back
// from a dry run, but a pool created or edited without one -- the normal CLI
// path -- would otherwise claim memory while some runners quietly use disk.
func (c *Controller) tmpfsHostProblems(ctx context.Context, out *[]Problem) error {
	pools, err := c.fleetPools(ctx)
	if err != nil {
		return fmt.Errorf("listing pools: %w", err)
	}
	for _, p := range pools {
		if !p.Enabled || !p.Tmpfs.Any() {
			continue
		}
		room, err := c.PoolRoom(ctx, p)
		if err != nil {
			return fmt.Errorf("counting the room pool %s has: %w", p.Name, err)
		}
		placeable := room.Placeable()
		if w, ok := heldWithoutTmpfs(p, placeable); ok {
			*out = append(*out, w)
		}
		if w, ok := keptOnDiskByHost(p, placeable); ok {
			*out = append(*out, w)
		}
		if w, ok := hostSizedTmpfsWarning(p, placeable); ok {
			*out = append(*out, w)
		}
		if w, ok := autoKeptOnDisk(p, placeable, room.TmpfsPlan); ok {
			*out = append(*out, w)
		}
	}
	return nil
}

// folderOutcome is what one in-memory folder is asked for and what a runner is
// given: Got zero is on disk.
type folderOutcome struct {
	Name     string
	Ask, Got int64
	Auto     bool
	Daemon   bool
}

// outcomes places a pool's in-memory folders on a runner and a daemon of the
// given memory limits, on a host with policy h, and says what each was asked
// for and given. Only the folders the pool keeps in memory are listed. It is
// the one place the controller's warnings reckon sizes, and it uses
// TmpfsConfig.PlaceRunner and PlaceDaemon, which the agent mounts from, so what
// an operator is told is what a runner gets.
func outcomes(c store.TmpfsConfig, runnerMB, daemonMB int64, h store.HostTmpfs) []folderOutcome {
	work, tmp := c.PlaceRunner(runnerMB, h)
	var out []folderOutcome
	if c.Work.Enabled {
		out = append(out, folderOutcome{"work folder", c.Work.AskedMB(h.WorkMB, store.DefaultTmpfsWorkMB), work, c.Work.Auto, false})
	}
	if c.Tmp.Enabled {
		out = append(out, folderOutcome{"/tmp", c.Tmp.AskedMB(h.TmpMB, store.DefaultTmpfsTmpMB), tmp, c.Tmp.Auto, false})
	}
	if c.Daemon.Enabled {
		out = append(out, folderOutcome{"Docker image store", c.Daemon.AskedMB(h.DaemonMB, store.DefaultTmpfsDaemonMB), c.PlaceDaemon(daemonMB, h), c.Daemon.Auto, true})
	}
	return out
}

// runnerLimitsOn is the memory limits a runner of p is given on a host: the
// pool's typed limit to both containers, or one runner's charge there divided
// between runner and daemon by the pool's share. False where there is nothing to
// judge by, a host that has measured no memory.
func runnerLimitsOn(p *store.Pool, h PoolHostRoom) (runnerMB, daemonMB int64, ok bool) {
	dind := p.DockerMode == store.DockerDinD
	if p.Resources.MemoryMB > 0 {
		return p.Resources.MemoryMB, p.Resources.MemoryMB, true
	}
	if h.ChargeMemoryMB <= 0 {
		return 0, 0, false
	}
	if !dind {
		return h.ChargeMemoryMB, 0, true
	}
	r, d := store.Resources{MemoryMB: h.ChargeMemoryMB}.SplitWithDaemonShare(p.Resources.DaemonMemoryPercent())
	return r.MemoryMB, d.MemoryMB, true
}

// hostSizedTmpfsWarning is tmpfsMemoryWarning for a pool whose runners are sized
// by their host. Such a pool stores no memory limit, so the warning above has
// nothing to judge and says nothing -- on exactly the pools whose runners get a
// small limit, because a slot is a share of a machine and, for a
// docker-in-docker pair, the runner has only its part of that share.
//
// The limit is worked out per host, as the scheduler gives it: one runner's
// charge, divided between the runner and its daemon by the pool's share. The
// folders are placed as the agent places them, and the hosts they come out too
// small on are named. A folder that is automatic and was kept on disk is not
// here: that is the setting working, and autoKeptOnDisk says it. The proposal is
// a slot at which the folders fit unreduced, which is a runner profile's
// standard size to raise (or a share to move), never a number written into the
// pool: the pool does not store one.
func hostSizedTmpfsWarning(p *store.Pool, hosts []PoolHostRoom) (Problem, bool) {
	if p == nil || !p.Tmpfs.Any() || p.Resources.MemoryMB > 0 {
		return Problem{}, false
	}
	dind := p.DockerMode == store.DockerDinD
	share := int64(p.Resources.DaemonMemoryPercent())
	var cut []string
	var worst, needSlot int64
	severity := config.SeverityInfo
	for _, h := range hosts {
		if !h.Tmpfs || h.TmpfsOff {
			continue
		}
		runnerMB, daemonMB, ok := runnerLimitsOn(p, h)
		if !ok {
			continue
		}
		var lines []string
		var slot int64
		for _, o := range outcomes(p.Tmpfs, runnerMB, daemonMB, h.TmpfsPolicy) {
			if o.Got == 0 || o.Got >= o.Ask {
				continue
			}
			lines = append(lines, fmt.Sprintf("%s %s of the %s asked for", o.Name, formatRoomMB(o.Got), formatRoomMB(o.Ask)))
			// A folder that came out under half of what was asked is one the jobs
			// notice: a checkout or a build that fills it fails with "no space left
			// on device", which names neither the mount nor the setting.
			if o.Got*2 < o.Ask {
				severity = config.SeverityWarning
			}
			need := 2 * o.Ask
			switch {
			case !dind:
				slot = max(slot, need)
			case o.Daemon:
				slot = max(slot, need*100/max(share, 1))
			default:
				slot = max(slot, need*100/max(100-share, 1))
			}
		}
		if len(lines) == 0 {
			continue
		}
		cut = append(cut, fmt.Sprintf("%s (a runner has %s: %s)", h.Host, formatRoomMB(runnerMB), strings.Join(lines, ", ")))
		worst = max(worst, h.ChargeMemoryMB)
		needSlot = max(needSlot, slot)
	}
	if len(cut) == 0 {
		return Problem{}, false
	}
	sort.Strings(cut)
	return Problem{
		Code:     "pool.tmpfs_memory_tight",
		Severity: severity,
		Title:    fmt.Sprintf("pool %s: its in-memory folders were fitted to small runners on %s", p.Name, plural(len(cut), "host")),
		Detail: "a tmpfs is charged to the memory limit of the container it is in, and this pool's runners are sized by their host, so the limit is a share of the machine -- " +
			"for a docker-in-docker runner only its part of that share. Folders left to size themselves are fitted into half of it, and these came out smaller than asked for: " +
			strings.Join(cut, "; ") + ". A job that fills a folder fails with \"no space left on device\".",
		Fix: fmt.Sprintf("let the folders decide per runner (Placement: Auto in the pool editor, or zoomies pools edit %s --tmpfs-auto), which keeps a folder on disk where it would be too small; "+
			"or give these hosts runners of about %s or more (Runner sizes on each host, or fewer slots); move the sidecar's memory share toward the container that needs the room (Runner and Docker sidecar on the pool's Size step); or turn off the folder that does not fit (zoomies pools edit %s --tmpfs-tmp=false). "+
			"The largest runner here is charged %s now.", p.Name, formatRoomMB(needSlot), p.Name, formatRoomMB(worst)),
		TargetKind: "pool",
		TargetID:   p.ID,
	}, true
}

// autoKeptOnDisk names the hosts where an automatic folder is on disk because
// the runner there has no room for it to be worth having. It is information:
// the setting working as designed. It is said because a pool that asked for
// memory and got disk on some machines is otherwise indistinguishable from one
// that is broken, and the operator who wants memory there has one lever --
// bigger runners on that host -- which the line names.
func autoKeptOnDisk(p *store.Pool, hosts []PoolHostRoom, plan *TmpfsPlan) (Problem, bool) {
	if p == nil || !p.Tmpfs.Any() {
		return Problem{}, false
	}
	var lines []string
	var needSlot int64
	for _, h := range hosts {
		if !h.Tmpfs || h.TmpfsOff {
			continue
		}
		runnerMB, daemonMB, ok := runnerLimitsOn(p, h)
		if !ok {
			continue
		}
		var names []string
		for _, o := range outcomes(p.Tmpfs, runnerMB, daemonMB, h.TmpfsPolicy) {
			if o.Auto && o.Got == 0 {
				names = append(names, o.Name)
			}
		}
		if len(names) == 0 {
			continue
		}
		lines = append(lines, fmt.Sprintf("%s (%s on disk: a runner has %s)", h.Host, strings.Join(names, " and "), formatRoomMB(runnerMB)))
		needSlot = max(needSlot, h.ChargeMemoryMB)
	}
	if len(lines) == 0 {
		return Problem{}, false
	}
	sort.Strings(lines)
	return Problem{
		Remedy:   autoOnDiskRemedy(p, plan),
		Code:     "pool.tmpfs_auto_on_disk",
		Severity: config.SeverityInfo,
		Title:    fmt.Sprintf("pool %s: its automatic in-memory folders are on disk on %s", p.Name, plural(len(lines), "host")),
		Detail: "this pool lets each runner decide, and a folder goes in memory only where the runner has room for it to be useful -- below that it would fill and fail jobs with " +
			"\"no space left on device\" while saving little disk traffic. On these hosts the runner is too small, so the folder is on disk: " + strings.Join(lines, "; ") + ".",
		Fix:        autoOnDiskFix(p, plan),
		TargetKind: "pool",
		TargetID:   p.ID,
	}, true
}

// autoOnDiskRemedy is the daemon share the plan found, as a change that can be
// applied rather than a sentence to retype. The plan only offers a share that
// loses no runners, which is the whole of what makes it safe to offer. A pool
// the controller keeps is left to its prose: it refuses edits to its resources,
// so a remedy that edited them would only be refused when applied.
func autoOnDiskRemedy(p *store.Pool, plan *TmpfsPlan) *Remedy {
	if plan == nil || plan.Share == nil || p.DockerMode != store.DockerDinD || p.FromHosts() {
		return nil
	}
	sh := plan.Share
	res := p.Resources
	res.DaemonMemorySharePercent = sh.Percent
	effect := fmt.Sprintf("puts %d of %d folders in memory, up from %d, with room for all %s", sh.InMemory, plan.Total, sh.Now, plural(sh.Runners, "runner"))
	return newRemedy(RemedyPoolUpdate, p.ID, fmt.Sprintf("Give the sidecar %d%% of the memory", sh.Percent), effect, map[string]any{"resources": res}, p.Resources)
}

// recordScratch writes on a runner's row which of its folders its pool keeps in
// memory and what it was given of each, worked out from the spec its create task
// will carry. Recorded, not recomputed, because a pool or a host edited since
// would give a different answer than the one the running job was started with.
//
// A write that fails costs the Runners page a badge and nothing else: the
// runner is created as it would have been.
func (c *Controller) recordScratch(ctx context.Context, r *store.Runner, pool *store.Pool, host *store.Host, spec backend.Spec) {
	if pool.Backend != store.BackendDocker && pool.Backend != store.BackendPodman {
		return
	}
	scratch := backend.PlanScratch(spec, pool.Tmpfs)
	if host != nil {
		// Whose rule placed the folders, and whose will mount them. The view
		// calls the row an estimate while the two are different builds.
		scratch.ControllerVersion, scratch.AgentVersion = version.Version, host.Version
	}
	if host != nil && !hostSupportsTmpfs(host) {
		// An agent too old to mount a tmpfs starts the runner with its folders
		// on disk, which is what the row has to say rather than what the pool
		// asked for.
		for i := range scratch.Folders {
			scratch.Folders[i].SizeMB, scratch.Folders[i].Why = 0, store.ScratchUnsupported
		}
	}
	if !scratch.Any() {
		return
	}
	if err := c.st.SetRunnerScratch(ctx, r.ID, scratch); err != nil {
		c.log.Warn("could not record a runner's in-memory folders", "runner", r.ID, "error", err)
	}
}

// autoOnDiskFix says what would put the folders in memory, from the plan: the
// daemon share that does it and what it costs in runners, and per host the
// runner size that does. Without a plan it says only where to look.
func autoOnDiskFix(p *store.Pool, plan *TmpfsPlan) string {
	fix := "Nothing is broken: a folder is in memory only where it would be useful. To have more in memory"
	var options []string
	if plan != nil && plan.Share != nil {
		sh := plan.Share
		line := fmt.Sprintf("give the Docker sidecar %d%% of a slot's memory (Runner and Docker sidecar on the pool's Size step, or zoomies pools edit %s --daemon-memory-share %d), which puts %d of %d folders in memory and loses no runners",
			sh.Percent, p.Name, sh.Percent, sh.InMemory, plan.Total)
		options = append(options, line)
	}
	if plan != nil && len(plan.Sizes) > 0 {
		// How the size changes depends on where the pool takes it from: a pool that
		// takes it from its hosts' runner profiles has it raised there, and one
		// sized by a slot's share has it raised by having fewer, bigger slots.
		var standard, capacity []string
		for _, o := range plan.Sizes {
			if o.Lever == "standard" {
				standard = append(standard, fmt.Sprintf("%s to %s (%s, now %d)", o.Host, formatRoomMB(o.MemoryMB), plural(o.Slots, "slot"), o.SlotsNow))
			} else {
				capacity = append(capacity, fmt.Sprintf("%s to %s (each runner about %s)", o.Host, plural(o.Slots, "slot"), formatRoomMB(o.MemoryMB)))
			}
		}
		if len(standard) > 0 {
			options = append(options, "raise the standard runner memory on a host so the work folder fits (Runner sizes on the host, or zoomies hosts edit <host> --standard-memory-mb): "+strings.Join(standard, "; "))
		}
		if len(capacity) > 0 {
			options = append(options, "lower a host's capacity so each runner is bigger (zoomies hosts edit <host> --capacity): "+strings.Join(capacity, "; "))
		}
	}
	options = append(options, "or lower the folders' sizes on the host (Runner sizes, in-memory folders)")
	if len(options) == 1 {
		return fix + ", " + options[0] + "."
	}
	return fix + ": " + strings.Join(options, "; ") + "."
}

package controller

import (
	"encoding/json"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// diskBoundHost gives a host the usage the advice rests on: waiting on disk
// since a while ago, with memory to spare.
func (h *harness) diskBoundHost(host *store.Host, waitingFor time.Duration, availableMB int64) {
	h.t.Helper()
	now := h.c.Now()
	cpu, wait := 60.0, 35.0
	since := now.Add(-waitingFor)
	if err := h.st.SetHostUsage(h.ctx, host.ID, store.HostUsage{
		CPUPercent: &cpu, IOWaitPercent: &wait, IOWaitHighSince: &since,
		MemoryAvailableMB: &availableMB, SampledAt: now,
	}); err != nil {
		h.t.Fatalf("SetHostUsage: %v", err)
	}
}

// ranJobs records n finished jobs of the pool on the host, as the runner would.
func (h *harness) ranJobs(pool *store.Pool, host *store.Host, n int) {
	h.t.Helper()
	for i := 0; i < n; i++ {
		queued := h.c.Now().Add(-time.Duration(i+1) * 20 * time.Minute)
		started, done := queued.Add(10*time.Second), queued.Add(5*time.Minute)
		if _, err := h.st.UpsertJob(h.ctx, &store.Job{
			GitHubJobID: time.Now().UnixNano() + int64(i),
			Repo:        "acme/widgets", Workflow: "CI", JobName: "build",
			Labels: store.NormalizeLabels(pool.Labels),
			State:  store.JobCompleted, Conclusion: "success",
			PoolID: pool.ID, HostID: host.ID, Matched: true,
			QueuedAt: queued, StartedAt: &started, CompletedAt: &done,
		}); err != nil {
			h.t.Fatalf("UpsertJob: %v", err)
		}
	}
}

func (h *harness) problemOrNil(code string) *Problem {
	h.t.Helper()
	ps, err := h.c.Problems(h.ctx)
	if err != nil {
		h.t.Fatalf("Problems: %v", err)
	}
	for _, p := range ps {
		if p.Code == code {
			p := p
			return &p
		}
	}
	return nil
}

// The advice needs all three: the disk is the bottleneck, the pool ran there,
// and there is memory to put the folder in. It is information, it names the
// pool and the one setting, and where the pool has a memory limit it proposes
// the limit that leaves the job the room it has.
func TestAPoolWhoseHostsWaitOnDiskIsToldItsWorkFolderCouldLiveInMemory(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	pool.Resources.MemoryMB = 8192
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	h.diskBoundHost(host, 25*time.Minute, 20_000)
	h.ranJobs(pool, host, 4)

	p := h.problemOrNil("pool.tmpfs_suggested")
	if p == nil {
		t.Fatal("a pool that has run on a disk-bound host with memory to spare was not told")
	}
	if p.Severity != config.SeverityInfo || p.TargetKind != "pool" || p.TargetID != pool.ID {
		t.Errorf("severity/target = %s %s/%s, want info on the pool", p.Severity, p.TargetKind, p.TargetID)
	}
	for _, want := range []string{host.Name, "I/O wait"} {
		if !strings.Contains(p.Detail, want) {
			t.Errorf("detail %q does not mention %q", p.Detail, want)
		}
	}
	// 8192 + 4096 for the folder: the same room for the job, with it on top.
	for _, want := range []string{pool.Name, "--tmpfs-work", "12 GB"} {
		if !strings.Contains(p.Fix, want) {
			t.Errorf("fix %q does not mention %q", p.Fix, want)
		}
	}
	if p.Since == nil {
		t.Error("the problem carries no since, so the list would be rewritten as time passes")
	}
}

// Each condition is there because without it the advice is wrong or unusable.
func TestTheTmpfsAdviceIsSilentUnlessEveryConditionHolds(t *testing.T) {
	cases := []struct {
		name  string
		setup func(h *harness, pool *store.Pool, host *store.Host)
	}{
		{"the disk has not been busy long enough", func(h *harness, pool *store.Pool, host *store.Host) {
			h.diskBoundHost(host, 2*time.Minute, 20_000)
			h.ranJobs(pool, host, 4)
		}},
		{"the host has no memory to spare", func(h *harness, pool *store.Pool, host *store.Host) {
			h.diskBoundHost(host, time.Hour, 1500)
			h.ranJobs(pool, host, 4)
		}},
		{"the pool never ran on that host", func(h *harness, pool *store.Pool, host *store.Host) {
			h.diskBoundHost(host, time.Hour, 20_000)
		}},
		{"a single job is not the pool", func(h *harness, pool *store.Pool, host *store.Host) {
			h.diskBoundHost(host, time.Hour, 20_000)
			h.ranJobs(pool, host, 1)
		}},
		{"the work folder is already in memory", func(h *harness, pool *store.Pool, host *store.Host) {
			pool.Tmpfs.Work = store.TmpfsMount{Enabled: true}
			if err := h.st.UpdatePool(h.ctx, pool); err != nil {
				t.Fatal(err)
			}
			h.diskBoundHost(host, time.Hour, 20_000)
			h.ranJobs(pool, host, 4)
		}},
		{"the reading is stale", func(h *harness, pool *store.Pool, host *store.Host) {
			h.diskBoundHost(host, time.Hour, 20_000)
			h.ranJobs(pool, host, 4)
			h.advance(store.HostUsageMaxAge + time.Minute)
		}},
		{"the host is cordoned", func(h *harness, pool *store.Pool, host *store.Host) {
			h.diskBoundHost(host, time.Hour, 20_000)
			h.ranJobs(pool, host, 4)
			host.Cordoned = true
			if err := h.st.UpdateHost(h.ctx, host); err != nil {
				t.Fatal(err)
			}
		}},
		{"the pool is disabled", func(h *harness, pool *store.Pool, host *store.Host) {
			pool.Enabled = false
			if err := h.st.UpdatePool(h.ctx, pool); err != nil {
				t.Fatal(err)
			}
			h.diskBoundHost(host, time.Hour, 20_000)
			h.ranJobs(pool, host, 4)
		}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			_, pool, host := h.fleet()
			tc.setup(h, pool, host)
			if p := h.problemOrNil("pool.tmpfs_suggested"); p != nil {
				t.Fatalf("advice raised: %+v", *p)
			}
		})
	}
}

// Persistent means the suggestion stands for as long as it is true, unchanged,
// and goes the moment it is not. The list is re-sent when its text changes, so
// a standing suggestion must not change as time passes.
func TestTheTmpfsAdviceStandsWhileTrueAndClearsItself(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	h.diskBoundHost(host, 25*time.Minute, 20_000)
	h.ranJobs(pool, host, 4)

	first := h.problemOrNil("pool.tmpfs_suggested")
	if first == nil {
		t.Fatal("no advice")
	}
	// Refresh the heartbeat each minute, as an agent would, keeping the same
	// stretch of waiting: the clock the controller keeps does not move.
	since := *first.Since
	for i := 0; i < 5; i++ {
		h.advance(time.Minute)
		cpu, wait, mem := 60.0, 35.0, int64(20_000)
		if err := h.st.SetHostUsage(h.ctx, host.ID, store.HostUsage{
			CPUPercent: &cpu, IOWaitPercent: &wait, IOWaitHighSince: &since,
			MemoryAvailableMB: &mem, SampledAt: h.c.Now(),
		}); err != nil {
			t.Fatal(err)
		}
	}
	later := h.problemOrNil("pool.tmpfs_suggested")
	if later == nil {
		t.Fatal("the advice went away while it was still true")
	}
	a, _ := json.Marshal(first)
	b, _ := json.Marshal(later)
	if string(a) != string(b) {
		t.Errorf("a standing suggestion changed as time passed:\n%s\n%s", a, b)
	}

	// Turning the setting on is what it asked for, and clears it.
	pool.Tmpfs.Work = store.TmpfsMount{Enabled: true}
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	if p := h.problemOrNil("pool.tmpfs_suggested"); p != nil {
		t.Fatalf("the suggestion stayed after the pool took it: %+v", *p)
	}
}

// A tmpfs is charged to the runner's memory limit. Sizes an operator typed that
// take over half of it are a warning; folders left to size themselves cannot,
// and are only information when the limit is too small to give them their
// defaults. Either way the proposal is the limit plus what they may fill.
func TestAPoolIsProposedAMemoryLimitThatLeavesTheJobItsRoom(t *testing.T) {
	pool := func(limit int64, tmpfs store.TmpfsConfig) *store.Pool {
		return &store.Pool{Name: "zoomies-big", Backend: store.BackendDocker,
			Resources: store.Resources{MemoryMB: limit}, Tmpfs: tmpfs}
	}
	cases := []struct {
		name     string
		pool     *store.Pool
		want     bool
		severity config.Severity
		propose  string
	}{
		{"nothing in memory", pool(8192, store.TmpfsConfig{}), false, "", ""},
		{"no limit to spend", pool(0, store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true}}), false, "", ""},
		{"a roomy limit takes the default", pool(32768, store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true}}), false, "", ""},
		{"a typed size over half the limit", pool(8192, store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true, SizeMB: 6000}}), true, config.SeverityWarning, "13.9 GB"},
		{"a small limit fits the default down", pool(4096, store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true}}), true, config.SeverityInfo, "8 GB"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			w, ok := tmpfsMemoryWarning(tc.pool)
			if ok != tc.want {
				t.Fatalf("warned = %v, want %v: %+v", ok, tc.want, w)
			}
			if !ok {
				return
			}
			if w.Severity != tc.severity {
				t.Errorf("severity = %s, want %s", w.Severity, tc.severity)
			}
			if !strings.Contains(w.Fix, tc.propose) {
				t.Errorf("fix %q does not propose %s", w.Fix, tc.propose)
			}
			if w.TargetKind != "pool" || w.Code != "pool.tmpfs_memory_tight" {
				t.Errorf("warning = %+v", w)
			}
		})
	}
}

// A cache source under /dev/shm is the host's memory. The cache is evicted only
// down to its size limit, so without one it grows until the host is out.
func TestACacheKeptInMemoryNeedsASizeLimit(t *testing.T) {
	cases := []struct {
		source string
		limit  int64
		want   bool
	}{
		{"/dev/shm/zoomies-cache", 0, true},
		{"/dev/shm", 0, true},
		{"/dev/shm/../etc", 0, false},
		{"/dev/shm/zoomies-cache", 1 << 30, false},
		{"/var/lib/zoomies/cache", 0, false},
		{"/dev/shmem/cache", 0, false},
		{"", 0, false},
	}
	for _, tc := range cases {
		p := &store.Pool{Name: "zoomies-ci", Cache: store.CacheConfig{Enabled: true, Source: tc.source, SizeLimit: tc.limit}}
		if _, ok := cacheInMemoryWarning(p); ok != tc.want {
			t.Errorf("source %q limit %d: warned = %v, want %v", tc.source, tc.limit, ok, tc.want)
		}
	}
	off := &store.Pool{Name: "zoomies-ci", Cache: store.CacheConfig{Source: "/dev/shm/x"}}
	if _, ok := cacheInMemoryWarning(off); ok {
		t.Error("a disabled cache was warned about")
	}
}

// An agent too old to mount the folders starts the runner on disk, which is
// safe and invisible; the pool is told where it is saved. Only hosts the pool
// can be placed on count: one its runner profile keeps it off is listed with no
// room, and naming it would be a warning about a machine it never lands on.
func TestAPoolOnAnAgentThatCannotMountInMemoryFoldersIsWarned(t *testing.T) {
	pool := &store.Pool{Name: "zoomies-ci", Tmpfs: store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true}}}
	hosts := []PoolHostRoom{
		{Host: "new", Tmpfs: true},
		{Host: "old", Tmpfs: false},
	}
	w, ok := heldWithoutTmpfs(pool, hosts)
	if !ok || !strings.Contains(w.Detail, "old") || strings.Contains(w.Detail, "new,") {
		t.Fatalf("warning = %+v, ok = %v; want only the old host named", w, ok)
	}
	if w.Code != "pool.tmpfs_unsupported" || w.TargetKind != "pool" {
		t.Errorf("warning = %+v", w)
	}
	if _, ok := heldWithoutTmpfs(&store.Pool{Name: "zoomies-ci"}, hosts); ok {
		t.Error("a pool with nothing in memory was warned about its hosts")
	}
	if _, ok := heldWithoutTmpfs(pool, []PoolHostRoom{{Host: "new", Tmpfs: true}}); ok {
		t.Error("a pool whose hosts all support it was warned")
	}
	// The room hands the warning only the placeable hosts, so an excluded old
	// agent is never named.
	room := PoolRoom{Hosts: []PoolHostRoom{
		{Host: "new", Tmpfs: true},
		{Host: "excluded-old", Tmpfs: false, ExcludedBy: ExcludedProfile},
	}}
	if _, ok := heldWithoutTmpfs(pool, room.Placeable()); ok {
		t.Error("a host the pool is kept off was named as one it would land on")
	}
}

// The seeded demo fleet and a real agent both advertise it, so a current host
// never carries the warning above.
func TestTheEmbeddedAgentAdvertisesTmpfs(t *testing.T) {
	host := &store.Host{Features: store.StringSlice{agent.FeatureTmpfs}}
	if !hostSupportsTmpfs(host) {
		t.Fatal("a host advertising the feature is not taken as supporting it")
	}
	if hostSupportsTmpfs(&store.Host{}) {
		t.Fatal("a host advertising nothing is taken as supporting it")
	}
}

// The runner's folders and the daemon's image store are charged to different
// containers, each with the typed limit, so each is judged against it on its
// own, and the proposal covers whichever needs more rather than both.
func TestTheImageStoreHasItsOwnShareOfTheMemoryLimit(t *testing.T) {
	pool := func(tmpfs store.TmpfsConfig) *store.Pool {
		return &store.Pool{Name: "zoomies-dind", Backend: store.BackendDocker, DockerMode: store.DockerDinD,
			Resources: store.Resources{MemoryMB: 8192}, Tmpfs: tmpfs}
	}
	// 5 GB of image store in a 8 GB daemon is over half of it.
	tight, ok := tmpfsMemoryWarning(pool(store.TmpfsConfig{Daemon: store.TmpfsMount{Enabled: true, SizeMB: 5000}}))
	if !ok || tight.Severity != config.SeverityWarning || !strings.Contains(tight.Detail, "Docker image store") {
		t.Fatalf("a 5 GB image store in an 8 GB limit was not warned about by name: %+v, ok = %v", tight, ok)
	}
	// 8192 + 5000: the daemon's folder added once.
	if !strings.Contains(tight.Fix, "12.9 GB") {
		t.Errorf("fix %q does not propose 12.9 GB", tight.Fix)
	}
	// Each container fits its own half of the limit: nothing to say, although the
	// two add up to more than the limit, because they are not charged together.
	if w, ok := tmpfsMemoryWarning(pool(store.TmpfsConfig{
		Work:   store.TmpfsMount{Enabled: true, SizeMB: 3000},
		Daemon: store.TmpfsMount{Enabled: true, SizeMB: 4000},
	})); ok {
		t.Errorf("folders in different containers were added together: %+v", w)
	}
}

// On a Docker-in-Docker pool the image store is likely most of the disk
// traffic, so the advice to keep the work folder in memory says it can be kept
// there too -- and why it is a choice of its own.
func TestTheAdviceForADockerInDockerPoolMentionsTheImageStore(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	pool.DockerMode = store.DockerDinD
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	h.diskBoundHost(host, 25*time.Minute, 20_000)
	h.ranJobs(pool, host, 4)

	p := h.problemOrNil("pool.tmpfs_suggested")
	if p == nil {
		t.Fatal("no advice for a pool that ran on a disk-bound host")
	}
	for _, want := range []string{"--tmpfs-docker", "Docker-in-Docker", "fit"} {
		if !strings.Contains(p.Fix, want) {
			t.Errorf("fix %q does not mention %q", p.Fix, want)
		}
	}

	// A pool with no daemon has no image store to suggest.
	pool.DockerMode = store.DockerNone
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	if p := h.problemOrNil("pool.tmpfs_suggested"); p == nil || strings.Contains(p.Fix, "--tmpfs-docker") {
		t.Errorf("a pool with no daemon was told about an image store: %+v", p)
	}
}

// A host that has memory to spare and one that has not cannot both be served by
// one pool setting, so the host has the last word: off keeps its runners on
// disk, a ceiling lowers every folder, and neither changes what the pool says
// for the hosts that say nothing.
func TestAHostHasTheLastWordOnAPoolsInMemoryFolders(t *testing.T) {
	cases := []struct {
		name    string
		profile store.HostTmpfs
		want    store.TmpfsConfig
		wantMax int64
	}{
		{"a host that says nothing leaves the pool's setting alone", store.HostTmpfs{},
			store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true}, Tmp: store.TmpfsMount{Enabled: true, SizeMB: 512}}, 0},
		{"a host with a ceiling hands the agent the pool's setting and the ceiling", store.HostTmpfs{MaxMB: 2048},
			store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true}, Tmp: store.TmpfsMount{Enabled: true, SizeMB: 512}}, 2048},
		{"a host that turned them off gets no folders and no ceiling", store.HostTmpfs{Disabled: true}, store.TmpfsConfig{}, 0},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			inst := h.installation()
			pool := h.pool(inst, "linux-x64")
			pool.MinRunners = 1
			pool.Tmpfs = store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true}, Tmp: store.TmpfsMount{Enabled: true, SizeMB: 512}}
			if err := h.st.UpdatePool(h.ctx, pool); err != nil {
				t.Fatalf("UpdatePool: %v", err)
			}
			host := h.measuredHost("measured", 8, 32768, 4, enforcesEverything)
			profile := store.RunnerProfile{Tmpfs: tc.profile}
			if err := h.st.PatchHost(h.ctx, host.ID, store.HostChanges{RunnerProfile: &profile}); err != nil {
				t.Fatalf("PatchHost: %v", err)
			}

			if err := h.c.Reconcile(h.ctx); err != nil {
				t.Fatalf("Reconcile: %v", err)
			}
			h.c.lifecycleCalls.Wait()
			task := h.taskOfKind(host.ID, agent.TaskCreateRunner)
			if task.Spec == nil {
				t.Fatal("the create task carries no spec")
			}
			if task.Spec.Tmpfs != tc.want || task.Spec.TmpfsMaxMB != tc.wantMax {
				t.Errorf("spec tmpfs = %+v max %d, want %+v max %d", task.Spec.Tmpfs, task.Spec.TmpfsMaxMB, tc.want, tc.wantMax)
			}
		})
	}
}

// A pool that keeps nothing in memory is not changed by a host that has a
// ceiling: the ceiling is a limit on folders, not a setting that creates them.
func TestAHostCeilingDoesNotTurnOnFoldersThePoolDidNotAskFor(t *testing.T) {
