// A pool whose runners are sized by their host stores no memory limit, so the
// typed-limit warning had nothing to judge and was silent on exactly the pools
// that get small runners. A 5 GB slot with 60% to the daemon leaves the runner
// 2 GB, half of which the folders may take: /tmp came out near 200 MB and every
// Go build died with "no space left on device".
func TestAHostSizedPoolWhoseFoldersAreFittedToSmallRunnersIsWarned(t *testing.T) {
	pool := &store.Pool{Name: "zoomies-ci", DockerMode: store.DockerDinD,
		Resources: store.Resources{DaemonSharePercent: 60},
		Tmpfs: store.TmpfsConfig{
			Work: store.TmpfsMount{Enabled: true}, Tmp: store.TmpfsMount{Enabled: true}, Daemon: store.TmpfsMount{Enabled: true},
		}}
	small := PoolHostRoom{Host: "twelve-core", Tmpfs: true, ChargeMemoryMB: 5120}
	w, ok := hostSizedTmpfsWarning(pool, []PoolHostRoom{small})
	if !ok || w.Code != "pool.tmpfs_memory_tight" || w.Severity != config.SeverityWarning {
		t.Fatalf("warning = %+v, ok = %v; want a warning on the small slot", w, ok)
	}
	for _, want := range []string{"twelve-core", "2 GB", "no space left on device"} {
		if !strings.Contains(w.Detail, want) {
			t.Errorf("detail %q does not say %q", w.Detail, want)
		}
	}
	if !strings.Contains(w.Fix, "--tmpfs-auto") || !strings.Contains(w.Fix, "--tmpfs-tmp=false") || !strings.Contains(w.Fix, "zoomies-ci") {
		t.Errorf("fix %q names no way out", w.Fix)
	}

	roomy := PoolHostRoom{Host: "big", Tmpfs: true, ChargeMemoryMB: 65536}
	if _, ok := hostSizedTmpfsWarning(pool, []PoolHostRoom{roomy}); ok {
		t.Error("a runner with room for the folders unreduced was warned")
	}
	// A host that keeps the folders off, or whose agent cannot mount them, is
	// said elsewhere in its own words, and a slot there is not a size they get.
	off := small
	off.TmpfsOff = true
	old := small
	old.Tmpfs = false
	if _, ok := hostSizedTmpfsWarning(pool, []PoolHostRoom{off, old}); ok {
		t.Error("hosts that do not mount the folders were judged")
	}
	// A typed limit is the other warning's: this one is for what the host decides.
	typed := *pool
	typed.Resources.MemoryMB = 4096
	if _, ok := hostSizedTmpfsWarning(&typed, []PoolHostRoom{small}); ok {
		t.Error("a pool with its own memory limit was judged by its hosts")
	}
	if _, ok := hostSizedTmpfsWarning(&store.Pool{Name: "p"}, []PoolHostRoom{small}); ok {
		t.Error("a pool with nothing in memory was warned")
	}
}

// With no sidecar the runner has the whole slot, so the same slot that starves a
// pair is enough here: the folders are fitted, not cut to a fraction.
func TestAHostSizedPoolWithoutASidecarGetsTheWholeSlot(t *testing.T) {
	pool := &store.Pool{Name: "plain", Tmpfs: store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true}}}
	if _, ok := hostSizedTmpfsWarning(pool, []PoolHostRoom{{Host: "h", Tmpfs: true, ChargeMemoryMB: 16384}}); ok {
		t.Error("a 16 GB runner with a default work folder was warned")
	}
	w, ok := hostSizedTmpfsWarning(pool, []PoolHostRoom{{Host: "h", Tmpfs: true, ChargeMemoryMB: 4096}})
	if !ok || w.Severity != config.SeverityInfo {
		t.Fatalf("warning = %+v, ok = %v; a 4 GB runner fits half of 4 GB, which is small but not under half of the ask", w, ok)
	}
}

// An automatic folder on disk is the setting working, and is said as such, once,
// with the hosts and what their runners have -- not as a fault.
func TestAutomaticFoldersOnDiskAreSaidAsInformation(t *testing.T) {
	pool := &store.Pool{Name: "zoomies-ci", DockerMode: store.DockerDinD, Resources: store.Resources{DaemonSharePercent: 60},
		Tmpfs: store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true, Auto: true}, Daemon: store.TmpfsMount{Enabled: true, Auto: true}}}
	small := PoolHostRoom{Host: "twelve-core", Tmpfs: true, ChargeMemoryMB: 5120}
	roomy := PoolHostRoom{Host: "big", Tmpfs: true, ChargeMemoryMB: 65536}
	w, ok := autoKeptOnDisk(pool, []PoolHostRoom{small, roomy}, nil)
	if !ok || w.Code != "pool.tmpfs_auto_on_disk" || w.Severity != config.SeverityInfo {
		t.Fatalf("warning = %+v, ok = %v", w, ok)
	}
	if !strings.Contains(w.Detail, "twelve-core") || strings.Contains(w.Detail, "big") {
		t.Errorf("detail %q should name only the small host", w.Detail)
	}
	// The tight-fit warning is not raised for what auto put on disk.
	if _, ok := hostSizedTmpfsWarning(pool, []PoolHostRoom{small}); ok {
		t.Error("a folder auto kept on disk was also reported as fitted too small")
	}
	// A pool that is not automatic has nothing to say here.
	manual := *pool
	manual.Tmpfs = store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true}}
	if _, ok := autoKeptOnDisk(&manual, []PoolHostRoom{small}, nil); ok {
		t.Error("a manual pool was told its folders were put on disk")
	}
	// A host's own standard changes what is asked, so what counts as small.
	big := small
	big.ChargeMemoryMB = 40960
	big.TmpfsPolicy = store.HostTmpfs{WorkMB: 4096}
	if _, ok := autoKeptOnDisk(pool, []PoolHostRoom{big}, nil); ok {
		t.Error("a 40 GB slot with a 4 GB host standard should have room for the folders")
	}
}

// The notice has to say what to do, not only that a folder is on disk: on the
// fleet that raised this, 6 GB runners split evenly leave the runner 3 GB, and
// the work folder needs the runner to have 4. The plan works that out per host
// and the problem says it, with what it costs in slots.
func TestAnAutomaticFolderOnDiskSaysWhatWouldPutItInMemory(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	host := &store.Host{
		Name: "vm-1", Capacity: 4, Backends: store.StringSlice{"docker"}, Labels: store.StringMap{},
		OS: "linux", Arch: "amd64", CPUs: 12, MemoryMB: 32048, DiskTotalMB: 500 * 1024, DiskFreeMB: 400 * 1024,
		LastHeartbeat: time.Now(), Features: store.StringSlice{agent.FeatureTmpfs},
		RunnerProfile: store.RunnerProfile{
			Minimum:  store.RunnerSize{CPUs: 1, MemoryMB: 2048},
			Standard: store.RunnerStandard{CPUs: 2, MemoryMB: 6144},
		},
	}
	if err := h.st.CreateHost(h.ctx, host); err != nil {
		t.Fatal(err)
	}
	pool.DockerMode = store.DockerDinD
	pool.SizeFromProfile = true
	pool.Resources = store.Resources{MinCPUs: 1, MinMemoryMB: 2048}
	pool.Tmpfs = store.TmpfsConfig{
		Work: store.TmpfsMount{Enabled: true, Auto: true},
		Tmp:  store.TmpfsMount{Enabled: true, Auto: true},
	}
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}

	room, err := h.c.PoolRoom(h.ctx, pool)
	if err != nil {
		t.Fatal(err)
	}
	plan := room.TmpfsPlan
	if plan == nil || len(plan.Hosts) != 1 || plan.InMemory != 0 || plan.Total != 2 {
		t.Fatalf("plan = %+v; want one host with both folders on disk", plan)
	}
	if len(plan.Sizes) != 1 || plan.Sizes[0].MemoryMB != 8192 || plan.Sizes[0].Host != host.Name {
		t.Fatalf("sizes = %+v; want 8 GB on %s, the runner at which the work folder fits", plan.Sizes, host.Name)
	}
	if plan.Sizes[0].Lever != "standard" {
		t.Errorf("lever = %q; a pool that takes its size from the host profile is changed there", plan.Sizes[0].Lever)
	}
	if plan.Sizes[0].Slots < 1 || plan.Sizes[0].Slots > plan.Sizes[0].SlotsNow {
		t.Errorf("slots = %+v; an 8 GB runner cannot leave more slots than 6 GB did", plan.Sizes[0])
	}
	if plan.Share != nil && plan.Share.InMemory <= plan.Share.Now {
		t.Errorf("share = %+v; a share is only offered if it puts more in memory", plan.Share)
	}

	p := h.problemOrNil("pool.tmpfs_auto_on_disk")
	if p == nil {
		t.Fatal("no pool.tmpfs_auto_on_disk problem")
	}
	// A share that would cost runners is not offered: at 6 GB runners every share
	// that puts the folder in memory raises the slot and loses most of the fleet.
	if plan.Share != nil && plan.Share.Runners < plan.Share.RunnersNow {
		t.Errorf("share = %+v; a share that loses runners must not be offered", plan.Share)
	}
	for _, want := range []string{"standard runner memory", "--standard-memory-mb", host.Name, "8 GB"} {
		if !strings.Contains(p.Fix, want) {
			t.Errorf("fix %q does not say %q", p.Fix, want)
		}
	}
}

// A pool sized by a slot's share of the machine has no standard to raise: its
// runners are bigger when the host has fewer slots, so that is the lever named.
func TestAPoolSizedBySlotShareIsToldToLowerCapacity(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	host := &store.Host{
		Name: "vm-8", Capacity: 8, Backends: store.StringSlice{"docker"}, Labels: store.StringMap{},
		OS: "linux", Arch: "amd64", CPUs: 16, MemoryMB: 32048, DiskTotalMB: 500 * 1024, DiskFreeMB: 400 * 1024,
		LastHeartbeat: time.Now(), Features: store.StringSlice{agent.FeatureTmpfs},
	}
	if err := h.st.CreateHost(h.ctx, host); err != nil {
		t.Fatal(err)
	}
	pool.DockerMode = store.DockerDinD
	pool.Tmpfs = store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true, Auto: true}}
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	room, err := h.c.PoolRoom(h.ctx, pool)
	if err != nil {
		t.Fatal(err)
	}
	if room.TmpfsPlan == nil || len(room.TmpfsPlan.Sizes) != 1 {
		t.Fatalf("plan = %+v; want one size option", room.TmpfsPlan)
	}
	o := room.TmpfsPlan.Sizes[0]
	if o.Lever != "capacity" || o.Slots >= o.SlotsNow {
		t.Fatalf("option = %+v; want fewer slots as the lever", o)
	}
	p := h.problemOrNil("pool.tmpfs_auto_on_disk")
	if p == nil || !strings.Contains(p.Fix, "--capacity") || strings.Contains(p.Fix, "--standard-memory-mb") {
		t.Fatalf("problem = %+v; want capacity named and no standard size", p)
	}
}

// The presets are priced on the hosts, and the one preselected is one that costs
// nothing: a CPU-skewed split raises a thin half to its minimum and grows the slot,
// which on a small slot loses runners and on a roomy one loses none.
func TestSplitPresetsArePricedOnTheHostsAndTheCheapestSuitableIsPreselected(t *testing.T) {
	plan := func(hostCPUs float64, memoryMB int64, std store.RunnerStandard) *SplitPlan {
		h := newHarness(t)
		inst := h.installation()
		pool := h.pool(inst, "linux-x64")
		host := &store.Host{
			Name: "vm", Capacity: 4, Backends: store.StringSlice{"docker"}, Labels: store.StringMap{},
			OS: "linux", Arch: "amd64", CPUs: int(hostCPUs), MemoryMB: memoryMB, DiskTotalMB: 500 * 1024, DiskFreeMB: 400 * 1024,
			LastHeartbeat: time.Now(), Features: store.StringSlice{agent.FeatureTmpfs},
			RunnerProfile: store.RunnerProfile{Minimum: store.RunnerSize{CPUs: 1, MemoryMB: 2048}, Standard: std},
		}
		if err := h.st.CreateHost(h.ctx, host); err != nil {
			t.Fatal(err)
		}
		pool.DockerMode, pool.SizeFromProfile = store.DockerDinD, true
		pool.Resources = store.Resources{MinCPUs: 1, MinMemoryMB: 2048}
		if err := h.st.UpdatePool(h.ctx, pool); err != nil {
			t.Fatal(err)
		}
		room, err := h.c.PoolRoom(h.ctx, pool)
		if err != nil {
			t.Fatal(err)
		}
		return room.SplitPlan
	}

	roomy := plan(32, 128*1024, store.RunnerStandard{CPUs: 4, MemoryMB: 16384})
	if roomy == nil || len(roomy.Options) != 3 {
		t.Fatalf("plan = %+v; want three priced presets", roomy)
	}
	if roomy.Options[0].ID != "even" || roomy.Options[0].Loses {
		t.Errorf("even = %+v; the pool's own division can never lose against itself", roomy.Options[0])
	}
	if roomy.Recommended != "build" {
		t.Errorf("recommended = %q on a roomy fleet, want build: %+v", roomy.Recommended, roomy.Options)
	}

	// A 2-CPU slot cannot give a 70% daemon its comfortable CPU without growing, and on
	// a 12-core host the slots that grow no longer all fit.
	tight := plan(12, 32*1024, store.RunnerStandard{CPUs: 2, MemoryMB: 6144})
	var build *SplitOption
	for i := range tight.Options {
		if tight.Options[i].ID == "build" {
			build = &tight.Options[i]
		}
	}
	if build == nil || !build.Loses {
		t.Fatalf("build = %+v on a small slot; want it priced as losing runners", build)
	}
	if tight.Recommended != "even" {
		t.Errorf("recommended = %q; a preset that loses runners must not be preselected", tight.Recommended)
	}

	// A typed size has no division to choose.
	h := newHarness(t)
	inst := h.installation()
	typed := h.pool(inst, "typed")
	typed.DockerMode, typed.Resources = store.DockerDinD, store.Resources{CPUs: 2, MemoryMB: 4096}
	if err := h.st.UpdatePool(h.ctx, typed); err != nil {
		t.Fatal(err)
	}
	h.host("vm-1")
	if room, err := h.c.PoolRoom(h.ctx, typed); err != nil || room.SplitPlan != nil {
		t.Errorf("a typed pool has a split plan: %+v (err %v)", room.SplitPlan, err)
	}
}

// The share the plan found is offered as a change that can be applied, with what it
// costs, but only on a dind pool somebody made, since one the controller keeps
// refuses edits to its resources. The plan only ever offers a share that loses no runners,
// so the remedy never needs a warning about capacity.
func TestAnAutomaticFolderOnDiskOffersTheDaemonShareAsARemedy(t *testing.T) {
	pool := &store.Pool{ID: "pool_x", Name: "zoomies-ci", DockerMode: store.DockerDinD, Resources: store.Resources{DaemonMemorySharePercent: 50, MinCPUs: 0.5},
		Tmpfs: store.TmpfsConfig{Work: store.TmpfsMount{Enabled: true, Auto: true}}}
	small := PoolHostRoom{Host: "twelve-core", Tmpfs: true, ChargeMemoryMB: 5120}
	plan := &TmpfsPlan{Total: 8, Share: &TmpfsShareOption{Percent: 15, InMemory: 7, Now: 4, Runners: 6, RunnersNow: 6}}

	w, ok := autoKeptOnDisk(pool, []PoolHostRoom{small}, plan)
	if !ok || w.Remedy == nil {
		t.Fatalf("problem = %+v, ok = %v; want a remedy", w, ok)
	}
	if w.Remedy.Kind != RemedyPoolUpdate || w.Remedy.TargetID != "pool_x" || !strings.Contains(w.Remedy.Effect, "7 of 8 folders") {
		t.Errorf("remedy = %+v", w.Remedy)
	}
	var body struct {
		Resources store.Resources `json:"resources"`
	}
	if err := json.Unmarshal(w.Remedy.Body, &body); err != nil {
		t.Fatal(err)
	}
	if body.Resources.DaemonMemorySharePercent != 15 || body.Resources.MinCPUs != 0.5 {
		t.Errorf("the request must be the pool's own resources with only the share changed: %+v", body.Resources)
	}

	if w, _ := autoKeptOnDisk(pool, []PoolHostRoom{small}, nil); w.Remedy != nil {
		t.Error("without a plan there is nothing priced to offer")
	}
	kept := *pool
	kept.AutoKey = "amd64/large"
	if w, _ := autoKeptOnDisk(&kept, []PoolHostRoom{small}, plan); w.Remedy != nil {
		t.Error("a pool the controller keeps refuses edits to its resources, so none is offered")
	}
}

// An agent too old to divide a slot by the pool's sidecar shares splits it evenly,
// which is safe and invisible: the pool reads 80% and the daemon is given half. The
// pool is told, but only if it asked for something other than the even split, and only
// for hosts it can land on.
func TestADindPoolWithAShareOnAnAgentThatIgnoresItIsWarned(t *testing.T) {
	shared := &store.Pool{Name: "zoomies-ci", DockerMode: store.DockerDinD, Resources: store.Resources{DaemonSharePercent: 80}}
	hosts := []PoolHostRoom{{Host: "new", DaemonShare: true}, {Host: "old"}}
	w, ok := heldWithoutDaemonShare(shared, hosts)
	if !ok || w.Code != "pool.daemon_share_unsupported" || !strings.Contains(w.Detail, "old") || strings.Contains(w.Detail, "new,") {
		t.Fatalf("warning = %+v, ok = %v; want only the old host named", w, ok)
	}
	even := &store.Pool{Name: "zoomies-ci", DockerMode: store.DockerDinD}
	if _, ok := heldWithoutDaemonShare(even, hosts); ok {
		t.Error("a pool on the even split was warned about a split every agent already makes")
	}
	if _, ok := heldWithoutDaemonShare(shared, []PoolHostRoom{{Host: "new", DaemonShare: true}}); ok {
		t.Error("a pool whose hosts all follow the share was warned")
	}
	plain := &store.Pool{Name: "zoomies-ci", Resources: store.Resources{DaemonSharePercent: 80}}
	if _, ok := heldWithoutDaemonShare(plain, hosts); ok {
		t.Error("a pool with no sidecar was warned about its share")
	}
	room := PoolRoom{Hosts: []PoolHostRoom{{Host: "new", DaemonShare: true}, {Host: "excluded-old", ExcludedBy: ExcludedProfile}}}
	if _, ok := heldWithoutDaemonShare(shared, room.Placeable()); ok {
		t.Error("a host the pool is kept off was named as one it would land on")
	}
}

package controller

import (
	"context"
	"math"
	"sort"

	"github.com/eyupio/zoomies/internal/store"
)

// An automatic folder decides per runner, which is only as useful as the
// operator's picture of what it decided. A pool that asks for memory and gets
// disk on every host is working as designed and doing nothing for anyone, and the
// words "a runner is too small" do not say what to change. So the controller
// works the answer out: what each host gives each folder now, and the smallest
// change that would give more -- one setting on the pool, or one size on a host --
// with what that costs in runners, because the cost is what decides whether it is
// worth doing. It informs; every change is the operator's.

// TmpfsFolderPlan is one folder on one host.
type TmpfsFolderPlan struct {
	Name string `json:"name"`
	// AskMB is what the folder is asked for there and MB what a runner is given;
	// zero is disk.
	AskMB int64 `json:"ask_mb"`
	MB    int64 `json:"mb"`
	Auto  bool  `json:"auto"`
}

// TmpfsHostPlan is what a runner of the pool is given on one host.
type TmpfsHostPlan struct {
	Host     string            `json:"host"`
	RunnerMB int64             `json:"runner_mb"`
	DaemonMB int64             `json:"daemon_mb,omitempty"`
	Folders  []TmpfsFolderPlan `json:"folders"`
}

// TmpfsShareOption is a daemon share that would put more folders in memory.
type TmpfsShareOption struct {
	Percent int `json:"percent"`
	// InMemory is how many folder placements are in memory across the hosts at
	// this share, against Now at the pool's. Runners is how many the hosts could
	// hold at it, against RunnersNow: moving a share can raise what a runner is
	// charged, which is how it costs capacity.
	InMemory   int `json:"in_memory"`
	Now        int `json:"now"`
	Runners    int `json:"runners"`
	RunnersNow int `json:"runners_now"`
}

// TmpfsSizeOption is the runner size on one host at which the work folder would
// be in memory there.
type TmpfsSizeOption struct {
	Host     string `json:"host"`
	MemoryMB int64  `json:"memory_mb"`
	Slots    int    `json:"slots"`
	SlotsNow int    `json:"slots_now"`
	// Lever is what changes the runner's size on this pool: "standard", the host's
	// standard runner size in its runner profile, for a pool that takes its size
	// from its hosts; or "capacity", the host's slot count, for a pool sized by a
	// slot's share of the machine, where fewer slots are bigger ones.
	Lever string `json:"lever"`
}

// TmpfsPlan is what a pool's in-memory folders come to, host by host, and what
// would change it.
type TmpfsPlan struct {
	Hosts []TmpfsHostPlan `json:"hosts"`
	// InMemory and Total count folder placements across the hosts: how many of the
	// folders asked for are in memory.
	InMemory int `json:"in_memory"`
	Total    int `json:"total"`
	// Share is the daemon share that would put the most folders in memory, when
	// moving it would put more than now. Sizes are, per host, the runner size
	// that would put the work folder there. Either may be empty: the plan says
	// only what would help.
	Share *TmpfsShareOption `json:"share,omitempty"`
	Sizes []TmpfsSizeOption `json:"sizes,omitempty"`
}

// planHosts places the pool's folders on each host of room and counts them.
func planHosts(p *store.Pool, room PoolRoom) (hosts []TmpfsHostPlan, inMemory, total int) {
	for _, h := range room.Placeable() {
		if !h.Tmpfs || h.TmpfsOff {
			continue
		}
		runnerMB, daemonMB, ok := runnerLimitsOn(p, h)
		if !ok {
			continue
		}
		hp := TmpfsHostPlan{Host: h.Host, RunnerMB: runnerMB, DaemonMB: daemonMB}
		for _, o := range outcomes(p.Tmpfs, runnerMB, daemonMB, h.TmpfsPolicy) {
			hp.Folders = append(hp.Folders, TmpfsFolderPlan{Name: o.Name, AskMB: o.Ask, MB: o.Got, Auto: o.Auto})
			total++
			if o.Got > 0 {
				inMemory++
			}
		}
		hosts = append(hosts, hp)
	}
	return hosts, inMemory, total
}

// tmpfsPlan is the plan for a pool whose room is already counted, or nil when
// there is nothing to say: no host places its folders, or nothing is on disk.
func (c *Controller) tmpfsPlan(ctx context.Context, p *store.Pool, room PoolRoom) *TmpfsPlan {
	hosts, inMemory, total := planHosts(p, room)
	if len(hosts) == 0 {
		return nil
	}
	plan := &TmpfsPlan{Hosts: hosts, InMemory: inMemory, Total: total}
	onDisk := false
	for _, h := range hosts {
		for _, f := range h.Folders {
			onDisk = onDisk || f.Auto && f.MB == 0
		}
	}
	if !onDisk {
		return plan
	}

	// The share. A pool sized by its hosts splits one slot between the runner and
	// its daemon, so moving the split moves memory between the two; whether that
	// is affordable is what the room says, since a thinner half is raised to its
	// minimum and the slot grows with it. Each candidate is judged by asking the
	// room again under it.
	if p.DockerMode == store.DockerDinD && p.Resources.MemoryMB <= 0 {
		now := p.Resources.DaemonMemoryPercent()
		best := TmpfsShareOption{Percent: now, InMemory: inMemory, Now: inMemory, Runners: room.Runners, RunnersNow: room.Runners}
		for s := store.MinDaemonSharePercent; s <= store.MaxDaemonSharePercent; s += 5 {
			if s == now {
				continue
			}
			cand := *p
			cand.Resources.DaemonMemorySharePercent = s
			r2, err := c.poolRoom(ctx, &cand)
			// A share that costs runners is not offered: a pool that gains a folder in
			// memory and loses most of its fleet has not been helped. It happens
			// because a thinner half is raised to its minimum and the slot grows
			// with it; the size option below says its cost in slots instead.
			if err != nil || r2.Runners < room.Runners {
				continue
			}
			_, in2, _ := planHosts(&cand, r2)
			better := in2 > best.InMemory ||
				in2 == best.InMemory && best.Percent != now && r2.Runners > best.Runners ||
				in2 == best.InMemory && best.Percent != now && r2.Runners == best.Runners && abs(s-now) < abs(best.Percent-now)
			if better {
				best = TmpfsShareOption{Percent: s, InMemory: in2, Now: inMemory, Runners: r2.Runners, RunnersNow: room.Runners}
			}
		}
		if best.Percent != now {
			plan.Share = &best
		}
	}

	// The runner size, per host: the smallest at which the work folder is in
	// memory there, in half-gigabyte steps, and the slots that leaves.
	if p.Tmpfs.Work.Enabled && p.Tmpfs.Work.Auto {
		for _, h := range room.Placeable() {
			if !h.Tmpfs || h.TmpfsOff || h.MemoryMB <= 0 || h.ChargeMemoryMB <= 0 {
				continue
			}
			if _, _, ok := runnerLimitsOn(p, h); !ok {
				continue
			}
			if onDiskHere(plan.Hosts, h.Host, "work folder") {
				for charge := (h.ChargeMemoryMB/512 + 1) * 512; charge <= 65536; charge += 512 {
					probe := h
					probe.ChargeMemoryMB = charge
					r, d, _ := runnerLimitsOn(p, probe)
					if w, _ := p.Tmpfs.PlaceRunner(r, h.TmpfsPolicy); w > 0 {
						_ = d
						if slots := int(h.MemoryMB / charge); slots >= 1 {
							lever := "capacity"
							if p.SizeFromProfile {
								lever = "standard"
							}
							plan.Sizes = append(plan.Sizes, TmpfsSizeOption{Host: h.Host, MemoryMB: charge, Slots: min(slots, h.Slots), SlotsNow: h.Slots, Lever: lever})
						}
						break
					}
				}
			}
		}
		sort.Slice(plan.Sizes, func(i, j int) bool { return plan.Sizes[i].Host < plan.Sizes[j].Host })
	}
	return plan
}

func onDiskHere(hosts []TmpfsHostPlan, host, folder string) bool {
	for _, h := range hosts {
		if h.Host != host {
			continue
		}
		for _, f := range h.Folders {
			if f.Name == folder && f.Auto && f.MB == 0 {
				return true
			}
		}
	}
	return false
}

func abs(n int) int { return int(math.Abs(float64(n))) }

// A host-sized Docker-in-Docker pool divides each slot between the runner and its
// daemon, CPU and memory on their own shares, and what is a sensible division
// depends on where the jobs do their work -- which Zoomies cannot know when a
// pool is made. What it can know is what each division would cost on these hosts:
// a skewed split raises a thin half to its minimum and the slot grows with it, so
// the same preset keeps every runner on one fleet and loses most of them on
// another. So the presets are priced against the hosts, and the one preselected is
// one that costs nothing.

// SplitOption is one way of dividing a slot, priced on the pool's hosts.
type SplitOption struct {
	ID            string `json:"id"`
	CPUPercent    int    `json:"cpu_percent"`
	MemoryPercent int    `json:"memory_percent"`
	// Runners is how many runners the hosts could hold under this division, and
	// Loses is whether that is fewer than under the pool's own now.
	Runners int  `json:"runners"`
	Loses   bool `json:"loses"`
}

// SplitPlan prices the presets and names the one to start from.
type SplitPlan struct {
	Options []SplitOption `json:"options"`
	// RunnersNow is the room under the division the pool has now.
	RunnersNow int `json:"runners_now"`
	// Recommended is the preset to preselect: the first that suits a pool that
	// builds images and loses no runner, or "even" when none does.
	Recommended string `json:"recommended"`
}

// splitPresets are the divisions offered, in the order a pool is preselected from.
// "build" gives the daemon most of the CPU, because a build is CPU in the daemon,
// and leaves memory even; "runner" gives the runner most of both, for jobs whose
// work -- compiles, tests, installs, an in-memory work folder charged to the
// runner -- is in the runner while the daemon mostly idles.
var splitPresets = []SplitOption{
	{ID: "build", CPUPercent: 70, MemoryPercent: 50},
	{ID: "runner", CPUPercent: 35, MemoryPercent: 35},
	{ID: "even", CPUPercent: 50, MemoryPercent: 50},
}

// splitPlan prices the presets for a host-sized docker-in-docker pool, or returns
// nil: a pool with a typed size gives its daemon the whole limit and has no
// division to choose.
func (c *Controller) splitPlan(ctx context.Context, p *store.Pool, room PoolRoom) *SplitPlan {
	if p.DockerMode != store.DockerDinD || !p.Automatic() || len(room.Placeable()) == 0 {
		return nil
	}
	plan := &SplitPlan{RunnersNow: room.Runners, Recommended: "even"}
	for _, preset := range splitPresets {
		cand := *p
		cand.Resources.DaemonSharePercent = 0
		cand.Resources.DaemonCPUSharePercent, cand.Resources.DaemonMemorySharePercent = preset.CPUPercent, preset.MemoryPercent
		r2, err := c.poolRoom(ctx, &cand)
		if err != nil {
			return nil
		}
		opt := preset
		opt.Runners, opt.Loses = r2.Runners, r2.Runners < room.Runners
		plan.Options = append(plan.Options, opt)
	}
	// A pool that is being made with a daemon is one that builds images: start from
	// the division that gives that work the CPU, if the fleet can afford it.
	for _, o := range plan.Options {
		if o.ID == "build" && !o.Loses {
			plan.Recommended = "build"
		}
	}
	sort.SliceStable(plan.Options, func(i, j int) bool { return splitOrder(plan.Options[i].ID) < splitOrder(plan.Options[j].ID) })
	return plan
}

func splitOrder(id string) int {
	switch id {
	case "even":
		return 0
	case "build":
		return 1
	}
	return 2
}

package controller

import (
	"context"
	"errors"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/toolscan"
)

// A toolchain scan reads every workflow every installation can see and says,
// per pool, which setup-python, setup-node, setup-go, setup-java and
// setup-dotnet versions its jobs will ask for. It is what lets a pool's cache
// be filled with those versions before the jobs arrive, rather than each
// ephemeral runner downloading them again.
//
// The result lives in memory. It is a reading of GitHub that the next scan
// replaces, not fleet state: nothing schedules from it, and a controller that
// restarts without it has lost a cache hint, not a record. Keeping it out of
// the store also keeps a scan -- the most GitHub-expensive thing the
// controller does on its own initiative -- from contending with the one
// writer.

// ToolchainDemand is one toolchain version a pool's jobs ask for.
type ToolchainDemand struct {
	Tool         string `json:"tool"`
	Version      string `json:"version,omitempty"`
	Distribution string `json:"distribution,omitempty"`
	// Unresolved says why the version is not known from the workflows; see
	// toolscan.Requirement.
	Unresolved string `json:"unresolved,omitempty"`
	// Jobs is how many workflow jobs ask for it, counting each matrix
	// combination once, and Repositories which repositories they are in.
	Jobs         int      `json:"jobs"`
	Repositories []string `json:"repositories"`
}

// ToolchainScanInstallation is how the scan went for one installation.
type ToolchainScanInstallation struct {
	InstallationID string `json:"installation_id"`
	Target         string `json:"target"`
	Repositories   int    `json:"repositories"`
	Workflows      int    `json:"workflows"`
	// Error is why this installation was not read, or only partly: GitHub
	// refusing it, a rate-limit hold, or an App without the Contents
	// permission, whose every repository would otherwise look empty.
	Error string `json:"error,omitempty"`
	// Unreadable lists repositories GitHub would not give up workflows for,
	// with the reason.
	Unreadable map[string]string `json:"unreadable,omitempty"`
}

// ToolchainScan is the latest scan.
type ToolchainScan struct {
	Running    bool       `json:"running"`
	StartedAt  *time.Time `json:"started_at,omitempty"`
	FinishedAt *time.Time `json:"finished_at,omitempty"`
	// Pools maps a pool ID to what its jobs ask for.
	Pools map[string][]ToolchainDemand `json:"pools"`
	// Unmatched is what jobs ask for that no pool would run: jobs on
	// GitHub-hosted labels, on labels no pool carries, or on labels an
	// expression chooses.
	Unmatched     []ToolchainDemand           `json:"unmatched"`
	Installations []ToolchainScanInstallation `json:"installations"`
	// Fills maps a pool ID to its tool cache's latest fill on each host,
	// for the pools that keep one; see toolfill.go.
	Fills map[string][]ToolCacheFill `json:"fills"`
}

// scannedRequirement is one requirement and the repository it was found in.
type scannedRequirement struct {
	installationID string
	repo           string
	req            toolscan.Requirement
}

// toolchainScans holds the latest scan and whether one is running.
type toolchainScans struct {
	mu      sync.Mutex
	running bool
	latest  ToolchainScan
	// fills is pool ID to host ID to that host's latest fill.
	fills map[string]map[string]ToolCacheFill
}

// ErrToolchainScanRunning is returned when a scan is asked for while one is
// already under way; the running one's result is the answer.
var ErrToolchainScanRunning = errors.New("a toolchain scan is already running")

// ToolchainScanResult returns the latest scan, and whether one is running.
func (c *Controller) ToolchainScanResult() ToolchainScan {
	c.toolchains.mu.Lock()
	defer c.toolchains.mu.Unlock()
	out := c.toolchains.latest
	out.Running = c.toolchains.running
	if out.Pools == nil {
		out.Pools = map[string][]ToolchainDemand{}
	}
	if out.Unmatched == nil {
		out.Unmatched = []ToolchainDemand{}
	}
	if out.Installations == nil {
		out.Installations = []ToolchainScanInstallation{}
	}
	out.Fills = c.toolFillsByPool()
	return out
}

// StartToolchainScan begins a scan in the background and returns at once. A
// scan reads every workflow file in every repository, which on a large
// organisation is minutes of GitHub calls: far longer than a request should
// hold a connection open, so the scan is detached from the request.
func (c *Controller) StartToolchainScan(ctx context.Context) error {
	return c.startToolchainScan(ctx)
}

// startToolchainScan runs a scan in the background. It outlives the request or
// pass that asked for it and ends with the controller; see goTracked.
func (c *Controller) startToolchainScan(ctx context.Context) error {
	c.toolchains.mu.Lock()
	if c.toolchains.running {
		c.toolchains.mu.Unlock()
		return ErrToolchainScanRunning
	}
	c.toolchains.running = true
	c.toolchains.mu.Unlock()

	c.goTracked(ctx, "toolchain-scan", func(ctx context.Context) {
		// A scan that panics must not leave the next one refused as already
		// running for the rest of the process's life.
		finished := false
		defer func() {
			if !finished {
				c.toolchains.mu.Lock()
				c.toolchains.running = false
				c.toolchains.mu.Unlock()
			}
		}()
		scan := c.scanToolchains(ctx)
		c.toolchains.mu.Lock()
		c.toolchains.latest = scan
		c.toolchains.running = false
		c.toolchains.mu.Unlock()
		finished = true
		// What the scan found is what the pools' caches are filled with, so
		// every scan, scheduled or asked for, is followed by a fill.
		c.fillToolCaches(ctx, scan)
	})
	return nil
}

// scanToolchains is one scan, start to finish.
func (c *Controller) scanToolchains(ctx context.Context) ToolchainScan {
	started := c.Now()
	scan := ToolchainScan{StartedAt: &started}

	var found []scannedRequirement
	insts, err := c.st.ListInstallations(ctx)
	if err != nil {
		c.log.Warn("could not list installations to scan their workflows", "error", err)
	}
	for _, inst := range insts {
		if ctx.Err() != nil {
			break
		}
		if IsDemoID(inst.ID) {
			continue
		}
		report, reqs := c.scanInstallation(ctx, inst)
		scan.Installations = append(scan.Installations, report)
		found = append(found, reqs...)
	}

	pools, err := c.st.ListPools(ctx)
	if err != nil {
		c.log.Warn("could not list pools to match scanned workflows against", "error", err)
	}
	scan.Pools, scan.Unmatched = aggregateToolchains(pools, found)
	finished := c.Now()
	scan.FinishedAt = &finished
	c.log.Info("scanned workflows for the toolchains they install",
		"installations", len(scan.Installations), "pools", len(scan.Pools),
		"took", finished.Sub(started).Round(time.Second))
	return scan
}

// scanInstallation reads one installation's workflows.
func (c *Controller) scanInstallation(ctx context.Context, inst *store.Installation) (ToolchainScanInstallation, []scannedRequirement) {
	report := ToolchainScanInstallation{InstallationID: inst.ID, Target: inst.Target}
	now := c.Now()
	if c.githubHeld(inst.ID, now) {
		report.Error = "GitHub is rate-limiting this installation; it will be read on the next scan"
		return report, nil
	}
	client, err := c.clients.get(ctx, inst)
	if err != nil {
		report.Error = err.Error()
		return report, nil
	}
	// The same question the migration wizard asks first, for the same
	// reason: GitHub answers an App without Contents with a 404, exactly as
	// it answers a repository with no workflows, so without asking every
	// repository would read as needing nothing.
	if info, err := client.Probe(ctx); err == nil && !info.CanReadContents() {
		report.Error = "the GitHub App cannot read repository contents, so no workflow can be read; grant it Contents: read on the installation"
		return report, nil
	}
	repos, err := client.ListRepositories(ctx, 0)
	c.observeGitHub(inst.ID, err)
	if err != nil {
		c.holdRateLimited(inst.ID, err, now, "scanning workflows for toolchains")
		report.Error = err.Error()
		return report, nil
	}
	report.Repositories = len(repos)

	var out []scannedRequirement
	for _, src := range readWorkflows(ctx, client, repos, c.log) {
		if src.err != "" {
			if report.Unreadable == nil {
				report.Unreadable = map[string]string{}
			}
			report.Unreadable[src.repo.FullName] = src.err
			continue
		}
		for _, wf := range src.workflows {
			report.Workflows++
			reqs, err := toolscan.Scan(wf.Path, wf.Content)
			if err != nil {
				// A workflow GitHub itself would refuse to run asks for
				// nothing; it is not worth failing the repository over.
				continue
			}
			for _, r := range reqs {
				out = append(out, scannedRequirement{installationID: inst.ID, repo: src.repo.FullName, req: r})
			}
		}
	}
	return report, out
}

// aggregateToolchains decides which pool would run each job and totals what
// each pool's jobs ask for. It is the scan without GitHub, which is what makes
// it testable.
//
// A job goes to the pool the scheduler would give it -- scheduler.BestPool, on
// the same labels and installation a queued job would carry -- so the answer
// here and the pool a real job lands on cannot disagree.
func aggregateToolchains(pools []*store.Pool, found []scannedRequirement) (map[string][]ToolchainDemand, []ToolchainDemand) {
	type key struct{ pool, tool, version, distribution, unresolved string }
	type tally struct {
		jobs  map[string]bool
		repos map[string]bool
	}
	tallies := map[key]*tally{}
	for _, f := range found {
		pool := ""
		if f.req.Labels != nil {
			job := &store.Job{Repo: f.repo, Labels: store.StringSlice(f.req.Labels), InstallationID: f.installationID}
			if p := scheduler.BestPool(pools, job); p != nil {
				pool = p.ID
			}
		}
		k := key{pool, string(f.req.Tool), f.req.Version, f.req.Distribution, f.req.Unresolved}
		t := tallies[k]
		if t == nil {
			t = &tally{jobs: map[string]bool{}, repos: map[string]bool{}}
			tallies[k] = t
		}
		// A job is its repository, file, key and labels: the same job with
		// two matrix combinations asking for one version counts once per
		// combination's labels, which is how many runners it takes.
		t.jobs[f.repo+"\x00"+f.req.Workflow+"\x00"+f.req.Job+"\x00"+strings.Join(f.req.Labels, ",")] = true
		t.repos[f.repo] = true
	}

	byPool := map[string][]ToolchainDemand{}
	var unmatched []ToolchainDemand
	for k, t := range tallies {
		repos := make([]string, 0, len(t.repos))
		for r := range t.repos {
			repos = append(repos, r)
		}
		sort.Strings(repos)
		d := ToolchainDemand{Tool: k.tool, Version: k.version, Distribution: k.distribution,
			Unresolved: k.unresolved, Jobs: len(t.jobs), Repositories: repos}
		if k.pool == "" {
			unmatched = append(unmatched, d)
		} else {
			byPool[k.pool] = append(byPool[k.pool], d)
		}
	}
	for id := range byPool {
		sortDemand(byPool[id])
	}
	sortDemand(unmatched)
	return byPool, unmatched
}

// sortDemand orders by tool, then the most-asked-for first, then version, so
// the list reads as "what matters most for each toolchain".
func sortDemand(ds []ToolchainDemand) {
	sort.Slice(ds, func(i, j int) bool {
		a, b := ds[i], ds[j]
		if a.Tool != b.Tool {
			return a.Tool < b.Tool
		}
		if a.Jobs != b.Jobs {
			return a.Jobs > b.Jobs
		}
		if a.Version != b.Version {
			return a.Version < b.Version
		}
		return a.Unresolved < b.Unresolved
	})
}

package controller

import (
	"context"
	"errors"
	"reflect"
	"strconv"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/toolscan"
)

// demandBrief renders what a pool's jobs ask for as "tool version xN" lines,
// which is what these tests compare.
func demandBrief(ds []ToolchainDemand) []string {
	var out []string
	for _, d := range ds {
		v := d.Version
		if d.Unresolved != "" {
			v = "? " + d.Unresolved
		}
		out = append(out, d.Tool+" "+v+" x"+strconv.Itoa(d.Jobs))
	}
	return out
}

// The pool a scanned job is counted against has to be the one the scheduler
// would give that job when it is queued -- otherwise the pool's cache is
// filled for jobs another pool runs.
func TestAggregateToolchainsGivesEachJobThePoolTheSchedulerWould(t *testing.T) {
	x64 := &store.Pool{ID: "pool_x64", Name: "x64", InstallationID: "ins_1", Enabled: true, Labels: []string{"linux", "x64"}}
	arm := &store.Pool{ID: "pool_arm", Name: "arm", InstallationID: "ins_1", Enabled: true, Labels: []string{"linux", "arm64"}}
	req := func(repo, job string, labels []string, tool toolscan.Tool, version string) scannedRequirement {
		return scannedRequirement{installationID: "ins_1", repo: repo,
			req: toolscan.Requirement{Workflow: ".github/workflows/ci.yml", Job: job, Labels: labels, Tool: tool, Version: version}}
	}
	found := []scannedRequirement{
		req("acme/a", "test", []string{"linux", "x64"}, toolscan.Python, "3.12"),
		req("acme/b", "test", []string{"linux", "x64"}, toolscan.Python, "3.12"),
		req("acme/b", "lint", []string{"linux", "x64"}, toolscan.Node, "22"),
		req("acme/a", "arm", []string{"linux", "arm64"}, toolscan.Go, "1.27"),
		req("acme/a", "hosted", []string{"ubuntu-latest"}, toolscan.Python, "3.13"),
		req("acme/a", "dynamic", nil, toolscan.Python, "3.11"),
	}
	pools, unmatched := aggregateToolchains([]*store.Pool{x64, arm}, found)

	if got, want := demandBrief(pools["pool_x64"]), []string{"node 22 x1", "python 3.12 x2"}; !reflect.DeepEqual(got, want) {
		t.Errorf("x64 pool: got %q, want %q", got, want)
	}
	if got := pools["pool_x64"][1].Repositories; !reflect.DeepEqual(got, []string{"acme/a", "acme/b"}) {
		t.Errorf("x64 python repositories = %q", got)
	}
	if got, want := demandBrief(pools["pool_arm"]), []string{"go 1.27 x1"}; !reflect.DeepEqual(got, want) {
		t.Errorf("arm pool: got %q, want %q", got, want)
	}
	// A hosted label no pool carries, and labels an expression chooses, are
	// not guessed onto a pool.
	if got, want := demandBrief(unmatched), []string{"python 3.11 x1", "python 3.13 x1"}; !reflect.DeepEqual(got, want) {
		t.Errorf("unmatched: got %q, want %q", got, want)
	}
}

func TestToolchainScanReadsTheWorkflowsOfEveryRepository(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64", "zoomies-linux-x64")
	h.gh.AddWorkflow("acme/widgets", ".github/workflows/ci.yml", `
jobs:
  test:
    runs-on: zoomies-linux-x64
    strategy:
      matrix:
        python: ["3.12", "3.13"]
    steps:
      - uses: actions/setup-python@v6
        with:
          python-version: ${{ matrix.python }}
  hosted:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/setup-node@v5
        with:
          node-version: "24"
`)
	h.gh.AddWorkflow("acme/gadgets", ".github/workflows/build.yml", `
jobs:
  build:
    runs-on: zoomies-linux-x64
    steps:
      - uses: actions/setup-go@v6
        with:
          go-version-file: go.mod
`)

	scan := h.c.scanToolchains(h.ctx)

	want := []string{"go ? read from go.mod in the repository x1", "python 3.12 x1", "python 3.13 x1"}
	if got := demandBrief(scan.Pools[pool.ID]); !reflect.DeepEqual(got, want) {
		t.Errorf("pool demand: got %q, want %q", got, want)
	}
	if got := demandBrief(scan.Unmatched); !reflect.DeepEqual(got, []string{"node 24 x1"}) {
		t.Errorf("unmatched: got %q", got)
	}
	if len(scan.Installations) != 1 || scan.Installations[0].Workflows != 2 || scan.Installations[0].Error != "" {
		t.Errorf("installation report = %+v", scan.Installations)
	}
	if scan.StartedAt == nil || scan.FinishedAt == nil {
		t.Error("a finished scan says when it ran")
	}
}

// GitHub answers an App without Contents exactly as it answers a repository
// with no workflows. Without asking first, the scan would report an
// organisation that needs nothing, when the truth is that it could not look.
func TestToolchainScanSaysWhenTheAppCannotReadWorkflows(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	h.pool(inst, "linux-x64", "zoomies-linux-x64")
	h.gh.AddWorkflow("acme/widgets", ".github/workflows/ci.yml", "jobs: {}\n")
	h.gh.SetPermissions(map[string]string{"metadata": "read", "organization_self_hosted_runners": "write"})

	scan := h.c.scanToolchains(h.ctx)

	if len(scan.Installations) != 1 || scan.Installations[0].Error == "" {
		t.Fatalf("installation report = %+v, want an error naming the missing permission", scan.Installations)
	}
	if len(scan.Pools) != 0 {
		t.Errorf("pools = %+v, want nothing from an installation that was not read", scan.Pools)
	}
}

// A scan is minutes of GitHub calls on a large organisation; a second one
// started beside it would spend the same quota twice for the same answer.
func TestOnlyOneToolchainScanRunsAtATime(t *testing.T) {
	h := newHarness(t)
	h.c.toolchains.mu.Lock()
	h.c.toolchains.running = true
	h.c.toolchains.mu.Unlock()

	if err := h.c.StartToolchainScan(h.ctx); !errors.Is(err, ErrToolchainScanRunning) {
		t.Fatalf("StartToolchainScan = %v, want ErrToolchainScanRunning", err)
	}
	if !h.c.ToolchainScanResult().Running {
		t.Error("the result does not say a scan is running")
	}
}

// With an interval set, the background loop scans on its own; left at 0 it
// never spends the quota a scan costs unless somebody asks.
func TestHousekeepingScansToolchainsOnlyWhenAnIntervalIsSet(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64", "zoomies-linux-x64")
	h.gh.AddWorkflow("acme/widgets", ".github/workflows/ci.yml", `
jobs:
  test:
    runs-on: zoomies-linux-x64
    steps:
      - uses: actions/setup-node@v5
        with:
          node-version: "24"
`)

	h.c.live.Update(func(c *config.Config) { c.GitHub.ToolchainScanInterval = 0 })
	h.c.housekeep(h.ctx, &housekeeping{})
	if r := h.c.ToolchainScanResult(); r.Running || r.StartedAt != nil {
		t.Fatalf("a scan ran with the interval at 0: %+v", r)
	}

	h.c.live.Update(func(c *config.Config) { c.GitHub.ToolchainScanInterval = 24 * time.Hour })
	h.c.housekeep(h.ctx, &housekeeping{})
	deadline := time.Now().Add(10 * time.Second)
	for {
		r := h.c.ToolchainScanResult()
		if !r.Running && r.FinishedAt != nil {
			if got := demandBrief(r.Pools[pool.ID]); !reflect.DeepEqual(got, []string{"node 24 x1"}) {
				t.Fatalf("scheduled scan found %q", got)
			}
			return
		}
		if time.Now().After(deadline) {
			t.Fatal("the scheduled scan did not finish")
		}
		time.Sleep(10 * time.Millisecond)
	}
}

// A scan is minutes of GitHub calls on a large organisation. The one an
// operator asked for ran on a context cut loose from everything the controller
// owns, and Stop waited for no scan at all, so the process could believe it had
// stopped while a scan went on reading workflows and then filling tool caches
// behind it.
func TestStopCancelsARunningToolchainScanAndWaitsForIt(t *testing.T) {
	h := newHarness(t)
	h.installation()
	// Held open far longer than the test, so only a cancellation can end it.
	h.gh.SetDelay("", "/installation/repositories", time.Minute)
	if err := h.c.Start(h.ctx); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { h.c.Stop(context.Background()) })

	if err := h.c.StartToolchainScan(h.ctx); err != nil {
		t.Fatalf("StartToolchainScan: %v", err)
	}
	stopCtx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()
	if err := h.c.Stop(stopCtx); err != nil {
		t.Fatalf("Stop: %v", err)
	}

	if h.c.ToolchainScanResult().Running {
		t.Error("Stop returned while a toolchain scan was still running")
	}
}

// A request that reaches the API while the controller is stopping, or just
// after, must not start a scan that outlives it: nothing is left to cancel it
// or to wait for it.
func TestAToolchainScanAskedForAfterStopEndsAtOnce(t *testing.T) {
	h := newHarness(t)
	h.installation()
	h.gh.SetDelay("", "/installation/repositories", time.Minute)
	if err := h.c.Start(h.ctx); err != nil {
		t.Fatal(err)
	}
	if err := h.c.Stop(h.ctx); err != nil {
		t.Fatalf("Stop: %v", err)
	}

	if err := h.c.StartToolchainScan(h.ctx); err != nil {
		t.Fatalf("StartToolchainScan: %v", err)
	}
	eventually(t, 5*time.Second, "a scan asked for after Stop to end instead of running on", func() bool {
		return !h.c.ToolchainScanResult().Running
	})
}

// panickingGitHub is a factory whose client cannot be built, which is what a
// bug in building one looks like from the scan's side.
type panickingGitHub struct{}

func (panickingGitHub) For(context.Context, *store.Installation, []byte) (github.Client, error) {
	panic("a nil pointer where a GitHub client should be")
}

// A scan that panics ends the scan, not the process, and must not leave the
// next one refused as already running for the rest of the process's life.
func TestAPanickingToolchainScanLeavesRoomForTheNext(t *testing.T) {
	h := newHarness(t)
	h.installation()
	h.c.factory = panickingGitHub{}

	if err := h.c.StartToolchainScan(h.ctx); err != nil {
		t.Fatalf("StartToolchainScan: %v", err)
	}
	eventually(t, 5*time.Second, "the scan that panicked to be over", func() bool {
		return !h.c.ToolchainScanResult().Running
	})

	if err := h.c.StartToolchainScan(h.ctx); err != nil {
		t.Fatalf("a scan asked for after the panic got %v: the one that failed is still counted as running", err)
	}
	eventually(t, 5*time.Second, "the second scan that panicked to be over", func() bool {
		return !h.c.ToolchainScanResult().Running
	})
}

package controller

import (
	"context"
	"sort"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// A finished toolchain scan is turned into work: every pool that keeps a tool
// cache is sent the versions its jobs ask for, to each host that could run
// it, and each host's agent fills its copy of that cache ahead of the jobs.
//
// Which fills ran, and how each went, lives beside the scan in memory, for
// the same reason the scan does: it describes a cache the next fill brings
// up to date, and losing it on a restart loses a report, not a record.

// maxToolFillRequests caps what one pool is sent. A pool whose jobs ask for
// forty versions between them wants the ones most of them ask for, not an
// hour of downloads on every host for the long tail.
const maxToolFillRequests = 12

// ToolCacheFill is one pool's fill on one host.
type ToolCacheFill struct {
	HostID   string `json:"host_id"`
	HostName string `json:"host_name"`
	// State is pending while the agent works, then succeeded or failed. A
	// fill that succeeded may still have skipped or failed requests; Tools
	// says which.
	State      string             `json:"state"`
	Requested  int                `json:"requested"`
	Tools      []backend.ToolFill `json:"tools"`
	Error      string             `json:"error,omitempty"`
	QueuedAt   time.Time          `json:"queued_at"`
	FinishedAt *time.Time         `json:"finished_at,omitempty"`
}

// fillToolCaches sends every pool that keeps a tool cache the versions scan
// found its jobs asking for, and returns how many fills it queued.
func (c *Controller) fillToolCaches(ctx context.Context, scan ToolchainScan) int {
	pools, err := c.st.ListPools(ctx)
	if err != nil {
		c.log.Warn("could not list pools to fill their tool caches", "error", err)
		return 0
	}
	hosts, err := c.st.ListHosts(ctx)
	if err != nil {
		c.log.Warn("could not list hosts to fill tool caches on", "error", err)
		return 0
	}
	now := c.Now()
	queued := 0
	for _, p := range pools {
		if !p.Enabled || !p.Cache.Enabled || !p.Cache.Tools || p.Backend == store.BackendProcess {
			continue
		}
		tools := toolRequests(scan.Pools[p.ID])
		if len(tools) == 0 {
			continue
		}
		spec, err := c.toolFillSpec(ctx, p)
		if err != nil {
			c.log.Warn("could not describe a pool to fill its tool cache", "pool", p.Name, "error", err)
			continue
		}
		for _, h := range hosts {
			// An older agent refuses the task outright; asking it would
			// only put a failure on every host that has not upgraded.
			if !scheduler.HostCanRun(h, p, now) || !h.Supports(agent.FeatureToolCacheFill) {
				continue
			}
			task := agent.Task{Kind: agent.TaskFillToolCache, PoolID: p.ID, Backend: p.Backend,
				Spec: &spec, Tools: tools, IssuedAt: now}
			if !c.enqueue(h.ID, task) {
				continue
			}
			queued++
			c.noteToolFill(p.ID, ToolCacheFill{HostID: h.ID, HostName: h.Name, State: "pending",
				Requested: len(tools), Tools: []backend.ToolFill{}, QueuedAt: now})
		}
	}
	if queued > 0 {
		c.log.Info("asked hosts to fill their pools' tool caches", "fills", queued)
	}
	return queued
}

// toolFillSpec is what a fill needs of the pool: the parts of a runner's spec
// that decide its image, its way out to the internet and which tool cache it
// is given. It has to name the same folder a runner of the pool is bound, or
// the fill warms a cache no job reads.
func (c *Controller) toolFillSpec(ctx context.Context, p *store.Pool) (backend.Spec, error) {
	target := ""
	if p.InstallationID != "" {
		inst, err := c.st.GetInstallation(ctx, p.InstallationID)
		if err != nil {
			return backend.Spec{}, err
		}
		target = inst.Target
	}
	return backend.Spec{
		PoolID:     p.ID,
		PoolName:   p.Name,
		Image:      c.RunnerImage(p),
		PullPolicy: p.PullPolicy,
		Env:        runnerEnv(c.cfg().Runners, p),
		Cache:      p.Cache,
		Repository: firstNonEmpty(strings.TrimSpace(p.Cache.Repository), target),
		Network:    c.cfg().Agent.Network,
	}, nil
}

// toolRequests is what a fill can act on, most-asked-for first: a version the
// workflows state, of a toolchain the tool cache holds. A version only a run
// knows -- read from a file, passed as an input -- has nothing to fill yet.
func toolRequests(demand []ToolchainDemand) []backend.ToolRequest {
	var ds []ToolchainDemand
	for _, d := range demand {
		if d.Unresolved != "" || d.Version == "" || strings.ContainsAny(d.Version, " \t\n") {
			continue
		}
		switch d.Tool {
		case "python", "node", "go", "java":
			ds = append(ds, d)
		}
	}
	sort.SliceStable(ds, func(i, j int) bool { return ds[i].Jobs > ds[j].Jobs })
	if len(ds) > maxToolFillRequests {
		ds = ds[:maxToolFillRequests]
	}
	out := make([]backend.ToolRequest, 0, len(ds))
	for _, d := range ds {
		out = append(out, backend.ToolRequest{Tool: d.Tool, Version: d.Version, Distribution: d.Distribution})
	}
	return out
}

// noteToolFill records a fill's latest state for its pool and host.
func (c *Controller) noteToolFill(poolID string, f ToolCacheFill) {
	c.toolchains.mu.Lock()
	defer c.toolchains.mu.Unlock()
	if c.toolchains.fills == nil {
		c.toolchains.fills = map[string]map[string]ToolCacheFill{}
	}
	if c.toolchains.fills[poolID] == nil {
		c.toolchains.fills[poolID] = map[string]ToolCacheFill{}
	}
	c.toolchains.fills[poolID][f.HostID] = f
}

// recordToolFill is an agent's answer to a fill.
func (c *Controller) recordToolFill(hostID string, task agent.Task, res agent.TaskResult) {
	c.toolchains.mu.Lock()
	f, ok := c.toolchains.fills[task.PoolID][hostID]
	c.toolchains.mu.Unlock()
	if !ok {
		f = ToolCacheFill{HostID: hostID, Requested: len(task.Tools), QueuedAt: task.IssuedAt}
		if h, err := c.st.GetHost(context.Background(), hostID); err == nil {
			f.HostName = h.Name
		}
	}
	f.State = "succeeded"
	if !res.OK {
		f.State = "failed"
	}
	f.Error = res.Error
	f.Tools = res.ToolFills
	if f.Tools == nil {
		f.Tools = []backend.ToolFill{}
	}
	done := res.CompletedAt
	if done.IsZero() {
		done = c.Now()
	}
	f.FinishedAt = &done
	c.noteToolFill(task.PoolID, f)
	if !res.OK {
		c.log.Warn("a host could not fill a pool's tool cache", "host", hostID, "pool", task.PoolID, "error", res.Error)
	}
}

// toolFillsByPool is the fills as the API shows them: per pool, by host name.
// The caller holds c.toolchains.mu.
func (c *Controller) toolFillsByPool() map[string][]ToolCacheFill {
	out := make(map[string][]ToolCacheFill, len(c.toolchains.fills))
	for pool, byHost := range c.toolchains.fills {
		list := make([]ToolCacheFill, 0, len(byHost))
		for _, f := range byHost {
			list = append(list, f)
		}
		sort.Slice(list, func(i, j int) bool {
			if list[i].HostName != list[j].HostName {
				return list[i].HostName < list[j].HostName
			}
			return list[i].HostID < list[j].HostID
		})
		out[pool] = list
	}
	return out
}

package controller

import (
	"reflect"
	"strconv"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
)

// hostWith seeds a healthy docker host whose agent advertises features.
func (h *harness) hostWith(name string, features ...string) *store.Host {
	h.t.Helper()
	host := &store.Host{
		Name: name, Capacity: 4, Backends: store.StringSlice{"docker"}, Labels: store.StringMap{},
		OS: "linux", Arch: "amd64", CPUs: 16, MemoryMB: 64 * 1024, DiskTotalMB: 500 * 1024, DiskFreeMB: 400 * 1024,
		LastHeartbeat: time.Now(), Features: store.StringSlice(features),
	}
	if err := h.st.CreateHost(h.ctx, host); err != nil {
		h.t.Fatalf("CreateHost: %v", err)
	}
	return host
}

func (h *harness) keepToolCache(p *store.Pool) {
	h.t.Helper()
	p.Cache = store.CacheConfig{Enabled: true, Tools: true, Scope: store.CacheScopePool}
	if err := h.st.UpdatePool(h.ctx, p); err != nil {
		h.t.Fatalf("UpdatePool: %v", err)
	}
}

// A scan is what a pool's jobs ask for; a fill is that put in the cache the
// pool's runners are given. Only a pool that keeps a tool cache has one to
// fill, and only an agent that understands the task is sent it -- an older
// one refuses the kind, which would read as a fill failing on every host
// that has not upgraded yet.
func TestAScanFillsThePoolsThatKeepAToolCacheOnHostsThatCanRunThem(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	kept := h.pool(inst, "kept", "zoomies-kept")
	h.keepToolCache(kept)
	plain := h.pool(inst, "plain", "zoomies-plain")
	current := h.hostWith("current", agent.FeatureToolCacheFill)
	older := h.hostWith("older")

	demand := []ToolchainDemand{{Tool: "python", Version: "3.12", Jobs: 3}, {Tool: "node", Version: "22", Jobs: 5}}
	scan := ToolchainScan{Pools: map[string][]ToolchainDemand{kept.ID: demand, plain.ID: demand}}
	if n := h.c.fillToolCaches(h.ctx, scan); n != 1 {
		t.Fatalf("fillToolCaches queued %d fills, want 1", n)
	}
	if h.hasTaskOfKind(older.ID, agent.TaskFillToolCache) {
		t.Error("a fill was sent to an agent that does not advertise it")
	}
	task := h.taskOfKind(current.ID, agent.TaskFillToolCache)
	if task.PoolID != kept.ID || task.Spec == nil || task.Spec.PoolID != kept.ID || !task.Spec.Cache.Tools {
		t.Fatalf("task = %+v, want the kept pool's cache", task)
	}
	if task.Spec.Image != h.c.RunnerImage(kept) {
		t.Errorf("image = %q, want the one the pool's runners use", task.Spec.Image)
	}
	want := []backend.ToolRequest{{Tool: "node", Version: "22"}, {Tool: "python", Version: "3.12"}}
	if !reflect.DeepEqual(task.Tools, want) {
		t.Errorf("tools = %+v, want the most-asked-for first: %+v", task.Tools, want)
	}

	fills := h.c.ToolchainScanResult().Fills[kept.ID]
	if len(fills) != 1 || fills[0].State != "pending" || fills[0].HostName != "current" || fills[0].Requested != 2 {
		t.Fatalf("fills = %+v, want one pending fill on current", fills)
	}

	// A second scan while that fill is still downloading leaves it be.
	if n := h.c.fillToolCaches(h.ctx, scan); n != 0 {
		t.Errorf("a second scan queued %d more fills behind the running one", n)
	}

	batch, err := h.c.PollTasks(h.ctx, current.ID, 0)
	if err != nil || len(batch.Tasks) == 0 {
		t.Fatalf("PollTasks = %v, %v", batch, err)
	}
	result := []backend.ToolFill{
		{Tool: "node", Request: "22", Outcome: backend.ToolInstalled, Version: "22.11.0"},
		{Tool: "python", Request: "3.12", Outcome: backend.ToolFailed, Reason: "could not download it"},
	}
	if err := h.c.ReportResult(h.ctx, current.ID, agent.TaskResult{TaskID: task.ID, Kind: task.Kind, OK: true, ToolFills: result, CompletedAt: h.c.Now()}); err != nil {
		t.Fatalf("ReportResult: %v", err)
	}
	fills = h.c.ToolchainScanResult().Fills[kept.ID]
	if len(fills) != 1 || fills[0].State != "succeeded" || fills[0].FinishedAt == nil || !reflect.DeepEqual(fills[0].Tools, result) {
		t.Fatalf("fills after the report = %+v", fills)
	}
}

func TestAFailedFillSaysWhy(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	p := h.pool(inst, "kept", "zoomies-kept")
	h.keepToolCache(p)
	host := h.hostWith("current", agent.FeatureToolCacheFill)
	h.c.fillToolCaches(h.ctx, ToolchainScan{Pools: map[string][]ToolchainDemand{p.ID: {{Tool: "go", Version: "1.27", Jobs: 1}}}})
	task := h.taskOfKind(host.ID, agent.TaskFillToolCache)
	if _, err := h.c.PollTasks(h.ctx, host.ID, 0); err != nil {
		t.Fatal(err)
	}
	if err := h.c.ReportResult(h.ctx, host.ID, agent.TaskResult{TaskID: task.ID, Kind: task.Kind, OK: false, Error: "backend: pulling the image: denied"}); err != nil {
		t.Fatal(err)
	}
	f := h.c.ToolchainScanResult().Fills[p.ID]
	if len(f) != 1 || f[0].State != "failed" || f[0].Error != "backend: pulling the image: denied" {
		t.Fatalf("fills = %+v", f)
	}
	// A fill is not a runner, so its failure fails none.
	if len(h.runners()) != 0 {
		t.Errorf("runners = %v, want none", h.runners())
	}
}

// A fill acts only on what it can put in a tool cache, and on the versions
// most jobs ask for when there are more than it is worth fetching on every
// host.
func TestToolRequestsKeepWhatAFillCanActOnMostAskedFirst(t *testing.T) {
	demand := []ToolchainDemand{
		{Tool: "go", Unresolved: "read from go.mod in the repository", Jobs: 50},
		{Tool: "dotnet", Version: "8.0", Jobs: 40},
		{Tool: "java", Version: "21", Distribution: "temurin", Jobs: 2},
		{Tool: "python", Version: "3.12", Jobs: 9},
	}
	got := toolRequests(demand)
	want := []backend.ToolRequest{{Tool: "python", Version: "3.12"}, {Tool: "java", Version: "21", Distribution: "temurin"}}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("toolRequests = %+v, want %+v", got, want)
	}

	var many []ToolchainDemand
	for i := range 20 {
		many = append(many, ToolchainDemand{Tool: "node", Version: strconv.Itoa(10 + i), Jobs: i})
	}
	got = toolRequests(many)
	if len(got) != maxToolFillRequests || got[0].Version != "29" {
		t.Errorf("toolRequests over the cap = %d, first %+v; want %d starting with the most-asked-for", len(got), got[0], maxToolFillRequests)
	}
}

package controller

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"strings"

	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/store"
)

type TransferProgress = store.TransferProgress

// TransferProgress is where preparation stands, with the sentence that says
// so. The store counts and names what is in the way; the words are written
// here, where the fleet's other reasons are, so the page and the CLI show the
// same ones.
func (c *Controller) TransferProgress(ctx context.Context) (TransferProgress, error) {
	p, err := c.st.TransferProgress(ctx)
	if err != nil {
		return p, err
	}
	c.transferWords(&p)
	return p, nil
}

// publishTransfer sends the preparation to every open page now, for the
// handlers that changed it: a click should repaint before the next pass does.
func (c *Controller) publishTransfer(ctx context.Context) {
	if c.bus == nil || c.bus.Subscribers() == 0 || ctx.Err() != nil {
		return
	}
	c.derivedMu.Lock()
	defer c.derivedMu.Unlock()
	c.sendTransfer(ctx)
}

// sendTransfer publishes a preparation that differs from the one last sent.
// Called with derivedMu held, and with a subscriber on the bus.
//
// Nothing is computed, and nothing sent, while no transfer is being prepared
// and none was when the last frame went out: a controller that is not moving
// anywhere should not read its fleet on every pass to say so.
func (c *Controller) sendTransfer(ctx context.Context) {
	if c.bus == nil {
		return
	}
	if !c.transferDraining.Load() && c.lastTransfer == nil {
		return
	}
	p, err := c.TransferProgress(ctx)
	if err != nil {
		c.log.Warn("could not work out the transfer preparation for the event stream", "error", err)
		return
	}
	if raw, changed := c.derivedChanged(&c.lastTransfer, p); changed {
		c.bus.Publish(events.KindTransfer, "", json.RawMessage(raw))
	}
}

// transferWords writes the sentence for where preparation stands and one for
// each thing it is waiting on. They are written for the operator who has
// clicked the button and is watching: what is still happening, and whether
// any of it needs them.
func (c *Controller) transferWords(p *TransferProgress) {
	now := c.Now()
	for i := range p.Waiting {
		w := &p.Waiting[i]
		// A machine is not on a host; the question does not arise for it.
		w.HostHealthy = w.Kind == store.TransferWaitMachine ||
			(w.HostID != "" && now.Sub(w.HostLastHeartbeat) < store.HeartbeatTimeout)
		w.Detail = transferWaitDetail(*w)
	}
	switch {
	case !p.Draining:
		p.Summary = "Preparation has not started."
		return
	case p.Ready:
		p.Summary = "Ready to export. The instance is fenced."
		return
	case p.Quiescent():
		p.Summary = "The fleet is drained; the recovery fence is being raised."
		return
	}
	var parts []string
	if p.BusyRunners > 0 {
		parts = append(parts, fmt.Sprintf("%s finishing %s", plural(p.BusyRunners, "busy runner"), plural(p.ActiveJobs, "job")))
	}
	if idle := p.LiveRunners - p.BusyRunners; idle > 0 {
		parts = append(parts, plural(idle, "idle runner")+" being withdrawn")
	}
	if p.PendingCleanup > 0 {
		var sides []string
		if p.CleanupAwaitingHost > 0 {
			sides = append(sides, fmt.Sprintf("%d by the host", p.CleanupAwaitingHost))
		}
		if p.CleanupAwaitingGitHub > 0 {
			sides = append(sides, fmt.Sprintf("%d by GitHub", p.CleanupAwaitingGitHub))
		}
		part := plural(p.PendingCleanup, "runner") + " waiting to be confirmed gone"
		if len(sides) > 0 {
			part += " (" + strings.Join(sides, ", ") + ")"
		}
		parts = append(parts, part)
	}
	if p.MachineOperations > 0 {
		parts = append(parts, plural(p.MachineOperations, "machine operation")+" finishing")
	}
	summary := "Preparing: " + strings.Join(parts, "; ") + "."

	// What, if anything, the operator has to do. A silent host is the one
	// thing waiting cannot fix: nobody but its agent can confirm its runners
	// gone, so it is named first; a failed cleanup is the other.
	silent := map[string]bool{}
	var silentNames []string
	for _, w := range p.Waiting {
		if (w.Kind == store.TransferWaitCleanup && !w.HostConfirmed || w.Kind == store.TransferWaitRunner) &&
			w.HostName != "" && !w.HostHealthy && !silent[w.HostName] {
			silent[w.HostName] = true
			silentNames = append(silentNames, w.HostName)
		}
	}
	sort.Strings(silentNames)
	switch {
	case len(silentNames) == 1:
		summary += fmt.Sprintf(" Host %s has stopped sending heartbeats and has runners to confirm gone: start its agent again, or remove the host so its runners are forgotten.", silentNames[0])
	case len(silentNames) > 1:
		summary += fmt.Sprintf(" Hosts %s have stopped sending heartbeats and have runners to confirm gone: start their agents again, or remove the hosts so their runners are forgotten.", strings.Join(silentNames, ", "))
	case p.CleanupFailed > 0:
		summary += fmt.Sprintf(" %s could not be cleaned up; the Runners page says what is left behind and where.", plural(p.CleanupFailed, "runner"))
	default:
		summary += " Nothing needs you yet: the fence is raised on its own when the counts reach zero."
	}
	p.Summary = summary
}

// transferWaitDetail is the sentence for one wait. How long it has waited is
// left to the reader: the page counts from `since` on its own clock, and a
// sentence that named the minutes would change every minute and be sent
// every minute for a page that could already say it.
func transferWaitDetail(w store.TransferWait) string {
	host := func() string {
		if w.HostName == "" {
			return "its host"
		}
		if w.HostHealthy {
			return w.HostName
		}
		return w.HostName + ", which has stopped sending heartbeats"
	}
	switch w.Kind {
	case store.TransferWaitRunner:
		if w.State == string(store.RunnerBusy) {
			return "running a job on " + host() + "; it is left to finish"
		}
		return w.State + " on " + host() + "; being withdrawn"
	case store.TransferWaitCleanup:
		if w.Error != "" {
			return "cleanup failed on " + host() + ": " + w.Error
		}
		switch {
		case !w.HostConfirmed && !w.RegistrationConfirmed:
			return "waiting for " + host() + " to confirm it is gone, and for GitHub to confirm its registration is"
		case !w.HostConfirmed:
			return "waiting for " + host() + " to confirm it is gone"
		default:
			return "waiting for GitHub to confirm its registration is gone"
		}
	case store.TransferWaitJob:
		return "running on " + host() + "; it is left to finish"
	case store.TransferWaitMachine:
		return w.State + "; the provider operation is left to finish"
	}
	return ""
}

// Preparing changes the scheduler's view, never the saved pool configuration.
// Existing jobs finish naturally; the ordinary idle-runner withdrawal handshake
// keeps the last job that raced with the button from being killed.
func (c *Controller) PrepareTransfer(ctx context.Context) (TransferProgress, error) {
	p, err := c.prepareTransfer(ctx)
	if err != nil {
		return p, err
	}
	c.publishTransfer(ctx)
	return p, nil
}

func (c *Controller) prepareTransfer(ctx context.Context) (TransferProgress, error) {
	c.reconcileMu.Lock()
	defer c.reconcileMu.Unlock()
	c.machines.mu.Lock()
	if c.Fenced().Fenced && !c.transferDraining.Load() {
		c.machines.mu.Unlock()
		return TransferProgress{}, errors.New("resolve the existing recovery fence before preparing a transfer")
	}
	err := c.st.SetSetting(ctx, store.SettingTransferDraining, "true", false)
	if err == nil {
		c.transferDraining.Store(true)
		// A reservation that has never issued a provider call is still only intent.
		// Cancelling it here avoids leaving preparation waiting on its own pause.
		var cancelled []*store.Machine
		cancelled, err = c.st.CancelUnstartedTransferMachines(ctx)
		if err == nil {
			for _, m := range cancelled {
				c.publishMachine(ctx, m)
			}
		}
	}
	c.machines.mu.Unlock()
	if err != nil {
		return TransferProgress{}, err
	}
	c.Nudge()
	c.NudgeMachines()
	if err = c.finishTransferDrain(ctx); err != nil {
		return TransferProgress{}, err
	}
	return c.TransferProgress(ctx)
}

func (c *Controller) CancelTransfer(ctx context.Context) error {
	if err := c.cancelTransfer(ctx); err != nil {
		return err
	}
	c.publishTransfer(ctx)
	return nil
}

func (c *Controller) cancelTransfer(ctx context.Context) error {
	c.reconcileMu.Lock()
	defer c.reconcileMu.Unlock()
	c.machines.mu.Lock()
	defer c.machines.mu.Unlock()
	if c.Fenced().Fenced {
		return errors.New("this instance is already fenced for cutover; verify that no destination is running before lifting its recovery fence")
	}
	if err := c.st.DeleteSetting(ctx, store.SettingTransferDraining); err != nil {
		return err
	}
	c.transferDraining.Store(false)
	c.Nudge()
	c.NudgeMachines()
	return nil
}

// reconcileMu is held by each caller. Serialising with the machine pass keeps
// a plan from starting another provider operation between the last count and
// the fence. Operations already launched leave nonterminal rows until finished.
func (c *Controller) finishTransferDrain(ctx context.Context) error {
	if !c.transferDraining.Load() || c.Fenced().Fenced {
		return nil
	}
	c.machines.mu.Lock()
	defer c.machines.mu.Unlock()
	p, err := c.st.TransferProgress(ctx)
	if err != nil {
		return err
	}
	if !p.Quiescent() {
		return nil
	}
	if err = c.st.SetRecoveryFence(ctx, true, "instance drained for transfer; keep the source stopped during cutover"); err != nil {
		return err
	}
	return c.LoadFence(ctx)
}

package controller

import (
	"context"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/store"
)

func TestRestartLoadsTransferPreparationBeforeSchedulingWork(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerBusy)
	if err := h.st.SetSetting(h.ctx, store.SettingTransferDraining, "true", false); err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithCancel(h.ctx)
	defer cancel()
	if err := h.c.Start(ctx); err != nil {
		t.Fatal(err)
	}
	if !h.c.transferDraining.Load() {
		t.Fatal("scheduler started without persisted preparation")
	}
	stop, done := context.WithTimeout(h.ctx, 5*time.Second)
	defer done()
	if err := h.c.Stop(stop); err != nil {
		t.Fatal(err)
	}
	saved, err := h.st.GetPool(h.ctx, pool.ID)
	if err != nil || !saved.Enabled {
		t.Fatal("restart rewrote the saved pool", err)
	}
	busy, err := h.st.GetRunner(h.ctx, r.ID)
	if err != nil || busy.State != store.RunnerBusy {
		t.Fatal("restart interrupted busy work", err)
	}
}

func TestOneClickTransferPreparationLetsBusyJobsFinishAndKeepsPoolSettings(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerBusy)
	p, err := h.c.PrepareTransfer(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	if !p.Draining || p.Ready || p.BusyRunners != 1 {
		t.Fatalf("unexpected progress: %+v", p)
	}
	if err = h.c.Reconcile(h.ctx); err != nil {
		t.Fatal(err)
	}
	current, err := h.st.GetRunner(h.ctx, r.ID)
	if err != nil || current.State != store.RunnerBusy {
		t.Fatal("preparation interrupted a busy job", err)
	}
	stored, err := h.st.GetPool(h.ctx, pool.ID)
	if err != nil || !stored.Enabled {
		t.Fatal("preparation rewrote pool settings", err)
	}
	snap, err := h.c.snapshot(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	if snap.Pools[0].Enabled {
		t.Fatal("preparation allowed new demand")
	}
	if h.c.Fenced().Fenced {
		t.Fatal("fence stopped cleanup before the running job finished")
	}
	for _, state := range []store.RunnerState{store.RunnerDraining, store.RunnerRemoved} {
		if _, err = h.st.TransitionRunner(h.ctx, r.ID, state, "job finished"); err != nil {
			t.Fatal(err)
		}
	}
	p, err = h.c.TransferProgress(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	if p.Ready || p.PendingCleanup != 1 {
		t.Fatal("unfinished cleanup was ignored", p)
	}
	if _, err = h.st.ConfirmRunnerCleanup(h.ctx, r.ID, true); err != nil {
		t.Fatal(err)
	}
	if err = h.st.RecordRegistrationDeleted(h.ctx, r.ID); err != nil {
		t.Fatal(err)
	}
	if err = h.c.Reconcile(h.ctx); err != nil {
		t.Fatal(err)
	}
	p, err = h.c.TransferProgress(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	if !p.Ready || !h.c.Fenced().Fenced {
		t.Fatalf("drained fleet not fenced: %+v", p)
	}
	if err = h.st.TransferReady(h.ctx); err != nil {
		t.Fatal(err)
	}
	if err = h.c.CancelTransfer(h.ctx); err == nil {
		t.Fatal("cancel silently lifted a cutover fence")
	}
	if err = h.c.Unfence(h.ctx); err != nil {
		t.Fatal(err)
	}
	if h.c.transferDraining.Load() {
		t.Fatal("explicit recovery did not resume scheduling")
	}
}

func TestCancellingPreparationResumesSavedPoolsWithoutChangingThem(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	h.runnerRow(pool, host, store.RunnerBusy)
	if _, err := h.c.PrepareTransfer(h.ctx); err != nil {
		t.Fatal(err)
	}
	if err := h.c.CancelTransfer(h.ctx); err != nil {
		t.Fatal(err)
	}
	p, err := h.c.TransferProgress(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	if p.Draining || h.c.transferDraining.Load() {
		t.Fatal("preparation was not cancelled")
	}
	snap, err := h.c.snapshot(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	if !snap.Pools[0].Enabled {
		t.Fatal("saved pool did not resume")
	}
}

func TestAnEmptyInstanceIsReadyAfterOnePrepareClick(t *testing.T) {
	h := newHarness(t)
	p, err := h.c.PrepareTransfer(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	if !p.Ready || !p.Draining {
		t.Fatalf("empty instance not ready: %+v", p)
	}
	again, err := h.c.PrepareTransfer(h.ctx)
	if err != nil || !again.Ready {
		t.Fatalf("repeat preparation not idempotent: %+v %v", again, err)
	}
}

func TestPreparationCancelsOnlyMachineReservationsThatNeverIssuedACall(t *testing.T) {
	h := newHarness(t)
	p := h.providerRow(t, "transfer-provider")
	unissued := &store.Machine{ProviderID: p.ID, Name: "unissued", State: store.MachinePlanned}
	issued := &store.Machine{ProviderID: p.ID, Name: "issued", State: store.MachinePlanned}
	for _, m := range []*store.Machine{unissued, issued} {
		if err := h.st.CreateMachine(h.ctx, m); err != nil {
			t.Fatal(err)
		}
	}
	if _, err := h.st.ClaimMachineOperation(h.ctx, issued.ID, store.MachineOperation{Kind: store.MachineOpCreate, Holder: "worker", Timeout: time.Minute}, h.c.Now()); err != nil {
		t.Fatal(err)
	}
	progress, err := h.c.PrepareTransfer(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	if progress.Ready || progress.MachineOperations != 1 {
		t.Fatalf("in-flight operation ignored: %+v", progress)
	}
	row, err := h.st.GetMachine(h.ctx, unissued.ID)
	if err != nil || row.State != store.MachineFailed {
		t.Fatal("unissued reservation not cancelled", err)
	}
	row, err = h.st.GetMachine(h.ctx, issued.ID)
	if err != nil || row.State != store.MachinePlanned || row.OpID == "" {
		t.Fatal("issued reservation changed", err)
	}
}

// Every count in a transfer's preparation moves as runners are confirmed gone
// and jobs finish, and no row says "the transfer moved": the page an operator
// watches while the fleet drains was the one page that sat still until it was
// reloaded. A pass sends the preparation when it changes, in the shape
// GET /transfers/preparation returns, with the sentence that says what is
// happening and whether any of it needs them.
func TestTransferPreparationIsSentToThePageAsItMoves(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	sub := h.listen(events.KindTransfer)
	pass := func(doing string) {
		t.Helper()
		if err := h.c.Reconcile(h.ctx); err != nil {
			t.Fatalf("Reconcile %s: %v", doing, err)
		}
	}

	// Nothing is being prepared, so a pass has nothing to say and reads
	// nothing to say it.
	pass("with no transfer")
	nothingFor(t, sub)

	r := h.runnerRow(pool, host, store.RunnerIdle)
	if _, err := h.c.PrepareTransfer(h.ctx); err != nil {
		t.Fatal(err)
	}
	// The click itself is announced, before any pass.
	first := nextOfKind(t, sub, events.KindTransfer)
	if first["draining"] != true || first["live_runners"] != float64(1) {
		t.Errorf("first frame = %v, want draining with one live runner", first)
	}
	if summary, _ := first["summary"].(string); !strings.HasPrefix(summary, "Preparing: 1 idle runner being withdrawn.") {
		t.Errorf("first frame summary = %q", summary)
	}

	// The runner is withdrawn and removed; nobody has confirmed it gone yet.
	for _, state := range []store.RunnerState{store.RunnerDraining, store.RunnerRemoved} {
		if _, err := h.st.TransitionRunner(h.ctx, r.ID, state, "withdrawn"); err != nil {
			t.Fatal(err)
		}
	}
	pass("after the runner was removed")
	cleanup := nextOfKind(t, sub, events.KindTransfer)
	if cleanup["pending_cleanup"] != float64(1) || cleanup["cleanup_awaiting_host"] != float64(1) {
		t.Errorf("frame after removal = %v, want one runner awaiting its host", cleanup)
	}
	waits, _ := cleanup["waiting"].([]any)
	if len(waits) != 1 {
		t.Fatalf("frame after removal names %d waits, want the one runner: %v", len(waits), cleanup["waiting"])
	}
	wait, _ := waits[0].(map[string]any)
	if wait["kind"] != "cleanup" || wait["name"] != r.Name || wait["host"] != "vm-1" || wait["host_healthy"] != true {
		t.Errorf("the wait = %v, want the runner on vm-1", wait)
	}
	if detail, _ := wait["detail"].(string); !strings.Contains(detail, "vm-1 to confirm it is gone") {
		t.Errorf("the wait's detail = %q", detail)
	}
	if summary, _ := cleanup["summary"].(string); !strings.Contains(summary, "Nothing needs you yet") {
		t.Errorf("summary with a healthy host = %q, want it to say nothing is needed", summary)
	}

	// Nothing has moved, so nothing is said.
	pass("with nothing changed")
	nothingFor(t, sub)

	// The host goes quiet. Nothing is written anywhere, and the sentence has
	// to change: nobody but that host can confirm its runner gone.
	h.advance(2 * store.HeartbeatTimeout)
	pass("after the host fell silent")
	silent := nextOfKind(t, sub, events.KindTransfer)
	if summary, _ := silent["summary"].(string); !strings.Contains(summary, "Host vm-1 has stopped sending heartbeats") {
		t.Errorf("summary with a silent host = %q, want it to name vm-1", summary)
	}

	// Both sides confirm, and the pass that finds the fleet drained raises the
	// fence and says so.
	if _, err := h.st.ConfirmRunnerCleanup(h.ctx, r.ID, true); err != nil {
		t.Fatal(err)
	}
	if err := h.st.RecordRegistrationDeleted(h.ctx, r.ID); err != nil {
		t.Fatal(err)
	}
	pass("after cleanup was confirmed")
	ready := nextOfKind(t, sub, events.KindTransfer)
	if ready["ready"] != true || len(ready["waiting"].([]any)) != 0 {
		t.Errorf("frame after cleanup = %v, want ready with nothing waiting", ready)
	}
	if summary, _ := ready["summary"].(string); !strings.HasPrefix(summary, "Ready to export.") {
		t.Errorf("summary when ready = %q", summary)
	}
}

// A runner withdrawn while idle ran no job, and until now nothing asked its
// host about it again if the one report of its removal was lost: the row sat
// at "awaiting cleanup" with nothing on the host, and a transfer behind it
// never finished preparing. After a grace the host is asked again.
func TestAFinishedRunnerNobodyConfirmedGoneIsAskedAboutAgain(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerIdle)
	for _, state := range []store.RunnerState{store.RunnerDraining, store.RunnerRemoved} {
		if _, err := h.st.TransitionRunner(h.ctx, r.ID, state, "withdrawn"); err != nil {
			t.Fatal(err)
		}
	}
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatal(err)
	}
	for _, task := range h.tasksFor(host.ID) {
		if task.Kind == agent.TaskRemoveRunner && task.RunnerID == r.ID {
			t.Fatal("the host was asked inside the grace, while it may still be keeping the container for its logs")
		}
	}
	h.advance(hostCleanupGrace + time.Minute)
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatal(err)
	}
	if task := h.taskOfKind(host.ID, agent.TaskRemoveRunner); task.RunnerID != r.ID {
		t.Fatalf("the remove task is for %q, want %q", task.RunnerID, r.ID)
	}
}

package controller

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"runtime"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/updates"
	"github.com/eyupio/zoomies/internal/version"
)

// The release check asks github.com which release of Zoomies is current, so an
// operator learns that their controller is behind from the UI rather than from
// a changelog they were not reading.
//
// It is deliberately the only thing in Zoomies that talks to github.com
// regardless of github.api_base_url: the releases of this software live there
// whichever GitHub a fleet is pointed at. An Enterprise Server deployment with
// no route to github.com should switch it off, and updates.check_interval: 0
// says so plainly.
//
// What it asks depends on updates.mode. Off asks for the latest release, as it
// always has. Manual and auto read the last ten instead, because "latest" is
// GitHub's pick and not necessarily one that can be installed -- a release is
// public before its files have all been uploaded -- and a single answer leaves
// nothing to fall back to. A fleet that has not asked to update never requests
// the list.
const (
	// latestReleaseURL is the API redirect GitHub maintains for the newest
	// release that is neither a draft nor a prerelease.
	latestReleaseURL = "https://api.github.com/repos/eyupio/zoomies/releases/latest"
	// releaseListURL is the ten most recent releases. Ten covers about a month at
	// the current cadence, which is far more than an update chooses between, and
	// one request a day is a small share of the limit on requests that do not
	// sign in.
	releaseListURL = "https://api.github.com/repos/eyupio/zoomies/releases?per_page=10"
	mainCommitURL  = "https://api.github.com/repos/eyupio/zoomies/commits/main"
	// updateCheckTimeout bounds the request. Nothing waits on this, so it can
	// afford to be patient, but not to hold a housekeeping pass open.
	updateCheckTimeout = 15 * time.Second
	// releaseListMaxBytes bounds how much of the list is read. Ten releases with
	// their notes and assets run to a few hundred kilobytes; this is the ceiling
	// the installer puts on reading the same endpoint, and a body beyond it is not
	// ten releases.
	releaseListMaxBytes = 4 << 20
	// releaseAskCooldown is the least time between two requests the button lets
	// through. The request carries no credentials, so the limit it spends is
	// shared with everything else on the controller's address, and a button
	// pressed twice is one question.
	releaseAskCooldown = time.Minute
)

// releaseState is what the last successful check learned.
//
// A state is replaced as a whole and never edited, so one that has been read can
// be kept, slices and all, without holding the lock.
type releaseState struct {
	// Tag is the release's tag, e.g. "v0.2-beta". When Releases is non-nil it is
	// the newest release in it that an update could take, always of the form
	// vX.Y.Z, and it is empty when the list holds none.
	Tag string
	// URL is its release page, so the UI can link to the notes.
	URL string
	// At is when this was learned, so a stale answer can be recognised.
	At time.Time
	// Releases is the list the check read, whole and in GitHub's order, so that
	// the rule in internal/updates can be asked again later -- as the clock moves
	// on and a soak ends -- without asking GitHub. It is nil when the check asked
	// only for the latest release, and an empty slice when GitHub's list was
	// empty: a list never read and a list that came back empty are different
	// things to tell an operator.
	Releases []updates.Release
}

// developmentState is what the last successful main-branch check learned.
type developmentState struct {
	SHA string
	URL string
	At  time.Time
}

// developmentCommit returns the commit stamped into a published main build.
func developmentCommit(v string) (string, bool) {
	const prefix = "main-sha-"
	sha := strings.TrimPrefix(strings.TrimSpace(v), prefix)
	if sha == v || len(sha) < 7 {
		return "", false
	}
	for _, r := range sha {
		if (r < '0' || r > '9') && (r < 'a' || r > 'f') {
			return "", false
		}
	}
	return sha, true
}

// releaseVersion reports the release this binary was built from, and whether it
// was built from one at all.
//
// This is the whole honesty of the feature. A controller running :dev or
// :main is stamped main-sha-abc1234 and is usually *ahead* of the newest
// release, so telling it that a release is available would be telling it to
// downgrade. Only a build that came from a release tag has anything to compare.
//
// The join command needs the same answer -- an agent is installed from a
// release asset, so a controller that is not a release cannot pin a host to
// itself -- so the rule lives in internal/version and this is its name here.
func releaseVersion(v string) (string, bool) { return version.Release(v) }

// updateMode is updates.mode as the rule in internal/updates reads it. The
// configuration refuses a word it does not know when it loads, so one arriving
// here is a bug, and the reading that asks for the least is the safe one: the
// list is only ever requested because somebody chose a mode that needs it.
func (c *Controller) updateMode() updates.Mode { return updateModeOf(c.cfg().Updates.Mode) }

// readUpdateMode is updateMode for a caller that must read the mode once and
// act on that one reading. It is a variable so that a test can switch the mode
// between two readings, which is the race the single reading designs out.
var readUpdateMode = (*Controller).updateMode

// updateModeOf reads one loaded updates.mode, for a caller that has already
// loaded the configuration and must not load it a second time.
func updateModeOf(word string) updates.Mode {
	switch mode := updates.Mode(word); mode {
	case updates.ModeManual, updates.ModeAuto:
		return mode
	}
	return updates.ModeOff
}

// checkForRelease asks GitHub for the current release and records it.
//
// With updates.mode off it asks for the latest release, and a development build
// asks about main in every mode, both exactly as they always have. Manual and
// auto read the release list instead and keep all of it, naming in Tag and URL
// the release an update could take.
//
// A failure is logged at debug and the previous answer stays until a later pass
// replaces it: a controller that cannot reach github.com is not a controller
// with a problem. Only a failed read of the list is returned, so that a person
// who asked for the check can be told it did not happen; the two older questions
// have always failed quietly and still do.
func (c *Controller) checkForRelease(ctx context.Context) error {
	ctx, cancel := context.WithTimeout(ctx, updateCheckTimeout)
	defer cancel()
	if _, ok := developmentCommit(version.Version); ok {
		c.checkForMain(ctx)
		// The list too once updates are on, because a build from main can now be
		// moved onto the newest release by hand.
		if c.updateMode() != updates.ModeOff {
			return c.checkForReleaseList(ctx)
		}
		return nil
	}
	if c.updateMode() != updates.ModeOff {
		return c.checkForReleaseList(ctx)
	}

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, latestReleaseURL, nil)
	if err != nil {
		c.log.Debug("could not build the release check request", "error", err)
		return nil
	}
	req.Header.Set("Accept", "application/vnd.github+json")
	req.Header.Set("User-Agent", version.UserAgent())

	resp, err := c.httpClient.Do(req)
	if err != nil {
		c.log.Debug("could not ask GitHub which release is current", "error", err)
		return nil
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		// 404 is what a repository with no published release answers, and it is
		// not a failure: there is simply nothing to compare against yet.
		c.log.Debug("the release check was refused", "status", resp.StatusCode)
		return nil
	}

	var body struct {
		TagName string `json:"tag_name"`
		HTMLURL string `json:"html_url"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
		c.log.Debug("could not read the release check answer", "error", err)
		return nil
	}
	if strings.TrimSpace(body.TagName) == "" {
		return nil
	}

	c.mu.Lock()
	c.release = &releaseState{Tag: body.TagName, URL: body.HTMLURL, At: c.Now()}
	c.mu.Unlock()
	return nil
}

// checkForReleaseList reads GitHub's release list and records all of it.
//
// What it returns is written for the person who pressed the button, who cannot
// read the log: what failed, that nothing has changed, and what to try.
func (c *Controller) checkForReleaseList(ctx context.Context) error {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, releaseListURL, nil)
	if err != nil {
		c.log.Debug("could not build the release list request", "error", err)
		return fmt.Errorf("could not build the request for the release list: %w", err)
	}
	req.Header.Set("Accept", "application/vnd.github+json")
	req.Header.Set("User-Agent", version.UserAgent())

	resp, err := c.httpClient.Do(req)
	if err != nil {
		c.log.Debug("could not ask GitHub for the release list", "error", err)
		return checkFailed(err, "could not reach GitHub for the release list (%v); check that this controller may make outbound HTTPS requests to api.github.com", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		c.log.Debug("the release list request was refused", "status", resp.StatusCode)
		return checkFailed(nil, "GitHub answered %d to the request for the release list, so nothing has changed; try again later", resp.StatusCode)
	}

	var listed []githubRelease
	err = json.NewDecoder(io.LimitReader(resp.Body, releaseListMaxBytes)).Decode(&listed)
	if err == nil && listed == nil {
		// A null decodes without an error, and it is not the empty list [] that
		// GitHub answers when a repository has no releases.
		err = errors.New("the answer was null")
	}
	if err != nil {
		c.log.Debug("could not read the release list", "error", err)
		return checkFailed(err, "GitHub's answer was not a list of releases, so nothing has changed; try again later")
	}

	releases := make([]updates.Release, 0, len(listed))
	for _, g := range listed {
		releases = append(releases, g.release())
	}
	state := &releaseState{Releases: releases, At: c.Now()}
	// This controller's own system is the one asked about: it is the binary a
	// controller update installs, and the release the notice is about.
	if best, ok := updates.Newest(releases, runtime.GOOS, runtime.GOARCH); ok {
		state.Tag, state.URL = best.Tag, best.URL
	}

	c.mu.Lock()
	c.release = state
	c.mu.Unlock()
	return nil
}

// githubRelease is one entry of GitHub's release list as it arrives, cut down to
// what internal/updates reads. GitHub's names for it stop here, because that
// package takes no JSON.
//
// published_at is decoded as it comes. A null, a missing key and the zero date
// all become the zero time without an error, and updates.Newest declines a
// release it cannot date, so nothing here filters on it.
type githubRelease struct {
	TagName     string    `json:"tag_name"`
	HTMLURL     string    `json:"html_url"`
	PublishedAt time.Time `json:"published_at"`
	Prerelease  bool      `json:"prerelease"`
	Draft       bool      `json:"draft"`
	Assets      []struct {
		Name string `json:"name"`
	} `json:"assets"`
}

func (g githubRelease) release() updates.Release {
	r := updates.Release{
		Tag: g.TagName, URL: g.HTMLURL, PublishedAt: g.PublishedAt,
		Prerelease: g.Prerelease, Draft: g.Draft,
	}
	for _, a := range g.Assets {
		r.Assets = append(r.Assets, a.Name)
	}
	return r
}

// CheckForReleases asks GitHub now instead of at the next scheduled check, for a
// person who asked for one.
//
// It refuses while updates.check_interval is 0, because that setting says this
// controller must never make the request, and it lets one request through a
// minute. A press inside the minute is not an error: what it would have learnt
// is what the last one learnt a moment ago, so it returns as though it had asked.
// The minute is counted from the request and not from its success, because a
// refusal from GitHub is a reason to ask less often.
func (c *Controller) CheckForReleases(ctx context.Context) error {
	asked, err := c.askForReleases(ctx)
	if asked && err == nil {
		// What the list says has changed for every page that is open, not only for
		// the one that pressed the button, and no row is written to say so.
		if _, err := c.publishUpdates(context.WithoutCancel(ctx)); err != nil {
			c.log.Warn("read the release list, but could not work out the update status for the event stream", "error", err)
		}
	}
	return err
}

// askForReleases is CheckForReleases, saying as well whether the request was
// made or the minute held it back, for a caller that must not take a held-back
// press for an answer.
func (c *Controller) askForReleases(ctx context.Context) (asked bool, err error) {
	if c.cfg().Updates.CheckInterval <= 0 {
		return false, ErrUpdateCheckDisabled
	}
	now := c.Now()
	c.mu.Lock()
	// The zero time is far enough back that the first press always asks. A clock
	// stepped backwards leaves the last request in the future; that is long
	// enough, or the button would stay dead until the clock caught up with a
	// time that was never real.
	if elapsed := now.Sub(c.releaseAsked); elapsed >= 0 && elapsed < releaseAskCooldown {
		c.mu.Unlock()
		return false, nil
	}
	c.releaseAsked = now
	c.mu.Unlock()
	return true, c.checkForRelease(ctx)
}

// checkForMain gives a moving dev build a source of truth. The registry tag
// can remain perfectly reachable while CI has failed to advance it, so asking
// the branch rather than the tag is what detects that failure mode.
func (c *Controller) checkForMain(ctx context.Context) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, mainCommitURL, nil)
	if err != nil {
		c.log.Debug("could not build the main branch check request", "error", err)
		return
	}
	req.Header.Set("Accept", "application/vnd.github+json")
	req.Header.Set("User-Agent", version.UserAgent())
	resp, err := c.httpClient.Do(req)
	if err != nil {
		c.log.Debug("could not ask GitHub which commit is on main", "error", err)
		return
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		c.log.Debug("the main branch check was refused", "status", resp.StatusCode)
		return
	}
	var body struct {
		SHA     string `json:"sha"`
		HTMLURL string `json:"html_url"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
		c.log.Debug("could not read the main branch check answer", "error", err)
		return
	}
	if strings.TrimSpace(body.SHA) == "" {
		return
	}
	c.mu.Lock()
	c.development = &developmentState{SHA: body.SHA, URL: body.HTMLURL, At: c.Now()}
	c.mu.Unlock()
}

// latestRelease returns what the last check learned, or nil.
func (c *Controller) latestRelease() *releaseState {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.release
}

func (c *Controller) latestDevelopment() *developmentState {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.development
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"runtime"
	"strings"
	"time"
	"unicode"
	"unicode/utf8"

	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/updates"
	"github.com/eyupio/zoomies/internal/updates/channel"
	"github.com/eyupio/zoomies/internal/version"
)

const (
	// updateAttemptTimeout is how long an attempt may stay open. The engine's own
	// worst case is fifty minutes, so a shorter limit would fail an update that
	// was still working; the helper's unit allows two hours, so this ends first.
	updateAttemptTimeout = 90 * time.Minute
	// helperInstallCommand is what installs the helper, run by somebody with root
	// on the host. Nothing the controller does can run it, which is the point.
	helperInstallCommand = "sudo zoomies updates helper install"
	// maxRequestedBy is the most of a name the helper accepts in requested_by.
	// internal/updates refuses anything longer, and does not export its limit;
	// WriteRequest would refuse a longer name rather than write it, so the two
	// cannot drift apart without a test noticing.
	maxRequestedBy = 128
)

// The helper's states as the status names them.
const (
	HelperReady   = "ready"
	HelperMissing = "missing"
	// HelperUnsupported is a controller the helper can never be installed
	// beside, where the install command would only refuse.
	HelperUnsupported = "unsupported"
)

// UpdateActor is who asked for an update, as the request and the attempt record
// it. It is only ever written down: the API checks the caller's role and writes
// the audit row before it gets here.
type UpdateActor struct {
	ID, Name string
}

// updateAsk is how an update was asked for: by a person pressing a button, or by
// the planner, and as a step of which rollout, if any. A button press is never a
// rollout's step, so that a person's update does not count for or against one.
type updateAsk struct {
	trigger   string
	rolloutID string
}

var askedByHand = updateAsk{trigger: store.UpdateTriggerManual}

// updateDir is the update folder this controller would write a request into, and
// false when there is none to find. A test names its own; a real controller finds
// it the way the installer recorded it.
func (c *Controller) updateDir() (string, bool) {
	if c.updateFolder != "" {
		return c.updateFolder, true
	}
	return channel.Locate(channel.Locator{
		ConfigPath:  c.cfg().Path(),
		SharedDir:   config.SharedDir(),
		InContainer: backend.InContainer(),
	})
}

// helperProbe is what looking for the helper found: the folder, whether the
// helper is ready, what the status says about it, and, when it is not ready, the
// refusal a person pressing the button reads.
type helperProbe struct {
	dir     string
	ready   bool
	view    UpdatesHelper
	refusal string
}

// probeUpdateHelper looks for the helper beside this controller. The marker is
// the installer's last step, so a folder without one is a helper that was never
// finished, and is treated as none.
//
// Where the helper is not there and can never be (see updates.HelperSupport),
// the status says why, and offers the upgrade by hand in place of an install
// that would refuse. A marker found is a better witness than that reasoning,
// except about an operating system that cannot run the units at all.
//
// The status is shown to every role, so its sentence names no path; the refusal
// goes only to the person who pressed the button, and names the folder so that
// they can find it.
func (c *Controller) probeUpdateHelper() helperProbe {
	facts := c.helperHostFacts()
	cause := updates.HelperSupport(facts)
	missing := func(p helperProbe) helperProbe {
		if cause == "" {
			return p
		}
		why := helperUnsupportedWhy(cause, "this controller")
		status, refusal := controllerByHand(facts.GOOS)
		return helperProbe{dir: p.dir, view: UpdatesHelper{
			State:          HelperUnsupported,
			Reason:         "The update helper cannot be installed here: " + why + ". " + status,
			UpgradeCommand: controllerUpgradeCommand(facts.GOOS),
		}, refusal: "the update helper cannot be installed here: " + why + "; " + refusal}
	}
	view := UpdatesHelper{
		State: HelperMissing,
		Reason: "No update helper is installed on this controller's host, so the controller cannot update itself. " +
			"Somebody with root on the host can install it with the command below; until then, update it with zoomies upgrade.",
		InstallCommand: helperInstallCommand,
	}
	if cause == updates.HelperUnsupportedOS {
		return missing(helperProbe{})
	}
	dir, ok := c.updateDir()
	if !ok {
		return missing(helperProbe{view: view, refusal: "this controller has no update folder, which installing the helper records; run \"" +
			helperInstallCommand + "\" on the controller's host"})
	}
	// Ready and not the marker alone: a folder that is a link reads its target's
	// marker, and WriteRequest refuses to write through one, so the status would
	// offer an update that every press then refuses.
	_, found, err := channel.Ready(dir)
	switch {
	case err != nil:
		c.log.Debug("the update folder is not as the installer leaves it", "error", err)
		view.Reason = "The update folder on this controller's host, or the helper's marker in it, is not as the installer leaves it, so the helper is treated as missing. " +
			"Install it again with the command below."
		return missing(helperProbe{dir: dir, view: view, refusal: fmt.Sprintf("the update folder %s, or its marker, is not as the installer leaves it (%v); run \"%s\" on the controller's host to install it again",
			dir, err, helperInstallCommand)})
	case !found:
		return missing(helperProbe{dir: dir, view: view, refusal: fmt.Sprintf("there is no %s in the update folder %s, so the helper is not installed; run \"%s\" on the controller's host",
			channel.MarkerFile, dir, helperInstallCommand)})
	}
	return helperProbe{dir: dir, ready: true, view: UpdatesHelper{
		State:  HelperReady,
		Reason: "The update helper is installed on this controller's host, so the controller can update itself.",
	}}
}

// RequestControllerUpdate is RequestControllerUpdateAttempt for a caller that
// wants only the status.
func (c *Controller) RequestControllerUpdate(ctx context.Context, by UpdateActor, tag string) (*UpdatesView, error) {
	view, _, err := c.RequestControllerUpdateAttempt(ctx, by, tag)
	return view, err
}

// RequestControllerUpdateAttempt asks the helper beside this controller to take it to
// tag, or to the newest release that can be installed here when tag is empty,
// and returns the status with the attempt in it.
//
// The order is the design. Everything that can refuse does so before anything is
// written. The attempt is recorded before the request, because the store's rule
// of one open attempt per target is what stops two callers each writing one. And
// a request that cannot be written closes the attempt it opened, so a failed
// button leaves nothing in flight.
//
// The helper's unit stops after five starts in ten minutes. One open attempt at a
// time, each closed by an answer or after 90 minutes, keeps requests well below it.
//
// The attempt's id comes back beside the status so that a caller that audits the
// press does not have to find it in the status, where it is only the latest.
func (c *Controller) RequestControllerUpdateAttempt(ctx context.Context, by UpdateActor, tag string) (*UpdatesView, string, error) {
	return c.requestControllerUpdate(ctx, by, tag, askedByHand)
}

// requestControllerUpdate is RequestControllerUpdateAttempt for either asker:
// the button and the planner go through every refusal alike.
func (c *Controller) requestControllerUpdate(ctx context.Context, by UpdateActor, tag string, ask updateAsk) (*UpdatesView, string, error) {
	if !c.mayAct() {
		return nil, "", fmt.Errorf("%w: %s", ErrUpdateFenced, c.notActingReason())
	}
	if c.updateMode() == updates.ModeOff {
		return nil, "", ErrUpdateModeOff
	}
	helper := c.probeUpdateHelper()
	if !helper.ready {
		return nil, "", fmt.Errorf("%w: %s", ErrUpdateHelperMissing, helper.refusal)
	}
	target, err := c.controllerTarget(tag)
	if err != nil {
		return nil, "", err
	}

	attempt := &store.UpdateAttempt{
		Scope: store.UpdateScopeController, FromVersion: version.Version, ToVersion: target,
		Trigger: ask.trigger, RequestedBy: requestedBy(by), RolloutID: ask.rolloutID,
	}
	if err := c.st.CreateUpdateAttempt(ctx, attempt); err != nil {
		if errors.Is(err, store.ErrConflict) {
			return nil, "", ErrUpdateInProgress
		}
		return nil, "", fmt.Errorf("recording the update attempt: %w", err)
	}
	// A new attempt supersedes the last one's failure in the problems list now,
	// not at the next pass.
	c.lookAtUpdates(context.WithoutCancel(ctx))
	// The time as the row keeps it, to the millisecond, so that the request and
	// the attempt it belongs to say the same thing when they are read side by side.
	err = channel.WriteRequest(helper.dir, updates.Request{
		V: updates.WireVersion, ID: attempt.ID, Tag: target,
		RequestedBy: attempt.RequestedBy, RequestedAt: attempt.RequestedAt.Truncate(time.Millisecond),
	})
	if err != nil {
		// Closed even if the caller has gone, or the attempt would sit open for 90
		// minutes and refuse every press until then.
		c.finishUpdateAttempt(context.WithoutCancel(ctx), *attempt, store.UpdateFailed,
			"The request could not be handed to the update helper, so nothing ran: "+err.Error())
		// WriteRequest leaves nothing of its own behind when it fails, so this
		// only ever finds another request, which it leaves; it is here so that no
		// path that closes an attempt can strand that attempt's request. An earlier
		// request still waiting is the ordinary refusal and has already been said to
		// the person, so it is not also a warning about a request that is not ours.
		if !errors.Is(err, channel.ErrRequestPending) {
			c.withdrawRequest(*attempt)
		}
		c.lookAtUpdates(context.WithoutCancel(ctx))
		_, _ = c.publishUpdates(context.WithoutCancel(ctx))
		return nil, "", fmt.Errorf("%w: %w", ErrUpdateHelperMissing, err)
	}
	c.log.Info("asked the update helper to update this controller",
		"attempt", attempt.ID, "from", attempt.FromVersion, "to", target, "requested_by", attempt.RequestedBy)
	// The loop watches for the answer from now on; a refusal comes back in seconds.
	c.KickUpdates()
	view, err := c.publishUpdates(ctx)
	if err != nil {
		// The request is in the folder and the helper may already be running it,
		// so this is not a failure to report: an error here would tell the person
		// to press again, and the press would be refused as in flight. They get
		// the attempt they made, and the next pass sends the whole status.
		c.log.Warn("asked for the update, but could not work out the status to return", "attempt", attempt.ID, "error", err)
		return c.requestedView(*attempt, helper.view), attempt.ID, nil
	}
	return view, attempt.ID, nil
}

// requestedView is the status as far as it is known without reading anything:
// the settings, the build, the helper and the attempt just made.
func (c *Controller) requestedView(a store.UpdateAttempt, helper UpdatesHelper) *UpdatesView {
	cfg := c.cfg().Updates
	_, fromRelease := version.Release(version.Version)
	return &UpdatesView{
		Mode:       string(updateModeOf(cfg.Mode)),
		Soak:       config.TidyDuration(cfg.Soak),
		Running:    UpdatesRunning{Version: version.Version, Release: fromRelease},
		Reason:     fmt.Sprintf("The update to %s has been asked for, and the update helper will answer.", a.ToVersion),
		Helper:     helper,
		Controller: attemptView(a),
	}
}

// controllerTarget is the tag an update of this controller takes: the one asked
// for, or the newest release that can be installed here. It has to be a release
// in the list this controller read and complete for this system, so that the
// helper is never sent to a download that cannot work, and newer than the build
// that is running.
//
// The soak is not applied. It is how long auto waits on its own; a person
// pressing the button has decided.
func (c *Controller) controllerTarget(tag string) (string, error) {
	// DEV is an explicit manual choice and never enters the release planner.
	if tag == updates.DevTag {
		return tag, nil
	}
	state := c.latestRelease()
	if state == nil || state.Releases == nil {
		return "", fmt.Errorf("%w: this controller has not read the release list yet; check for releases, then try again", ErrUpdateNothingNewer)
	}
	var pick updates.Release
	var found bool
	if tag == "" {
		pick, found = updates.Newest(state.Releases, runtime.GOOS, runtime.GOARCH)
		if !found {
			return "", fmt.Errorf("%w: the release list holds no release that can be installed on %s/%s", ErrUpdateNothingNewer, runtime.GOOS, runtime.GOARCH)
		}
	} else {
		if !updates.ValidTag(tag) {
			return "", fmt.Errorf("%w: %q is not a release tag of the form vMAJOR.MINOR.PATCH", ErrUpdateNothingNewer, tag)
		}
		var named []updates.Release
		for _, r := range state.Releases {
			if r.Tag == tag {
				named = append(named, r)
			}
		}
		// Newest over the one release asks the same question of it that it asks of
		// the whole list, so a tag is taken here only if it would be offered there.
		pick, found = updates.Newest(named, runtime.GOOS, runtime.GOARCH)
		if !found {
			return "", fmt.Errorf("%w: %s is not a release in the list this controller read that can be installed on %s/%s; check for releases, or choose one the status names",
				ErrUpdateNothingNewer, tag, runtime.GOOS, runtime.GOARCH)
		}
	}
	// A build that is not from a release has no place in the order, and the
	// person pressing the button has chosen to move it onto one.
	if _, fromRelease := version.Release(version.Version); fromRelease && version.CompareBuilds(version.Version, pick.Tag) != version.SkewBehind {
		return "", fmt.Errorf("%w: this controller runs %s, and %s is not newer", ErrUpdateNothingNewer, version.Version, pick.Tag)
	}
	return pick.Tag, nil
}

// notActingReason says why mayAct is false, for the refusal.
func (c *Controller) notActingReason() string {
	if c.Fenced().Fenced {
		return "this fleet is fenced for recovery; check what the restore did not bring with it, then lift the fence"
	}
	return "this controller does not hold the database's lease, so another may be running against it; update from the controller that holds it"
}

// requestedBy is who asked, as the helper will log it: a name it accepts.
//
// The helper refuses a requested_by over 128 bytes or with a character that is
// not printable, because root writes it into a log; a name from single sign-on
// can be either. Refused there, the button would fail for that person every time,
// so the name is cut to fit here instead, dropping what cannot be printed and
// stopping at a whole character. The ID stands in for a name with nothing left.
func requestedBy(by UpdateActor) string {
	for _, s := range []string{by.Name, by.ID} {
		if v := printableWithin(s, maxRequestedBy); v != "" {
			return v
		}
	}
	return "unknown"
}

// printableWithin is s without its unprintable characters, cut to at most limit
// bytes at a character boundary. Invalid UTF-8 comes back as U+FFFD, which is
// what encoding/json would have made of it anyway.
func printableWithin(s string, limit int) string {
	var b strings.Builder
	for _, r := range s {
		if !unicode.IsGraphic(r) {
			continue
		}
		if b.Len()+utf8.RuneLen(r) > limit {
			break
		}
		b.WriteRune(r)
	}
	return strings.TrimSpace(b.String())
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"runtime"
	"slices"
	"time"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/updates"
	"github.com/eyupio/zoomies/internal/version"
)

// autoUpdateActor is the planner as an attempt, a request and a rollout record
// who asked: the auto-update identity's name, which the audit log uses too.
func autoUpdateActor() UpdateActor {
	id := auth.AutoUpdateIdentity()
	return UpdateActor{ID: id.ID, Name: id.Name}
}

var askedByPlanner = updateAsk{trigger: store.UpdateTriggerAuto}

// updatesPicture is the rows a snapshot was made from, kept beside it, so that
// the applier acts on the attempts and the rollout the planner saw and the
// status counts the rollout from the same reading.
type updatesPicture struct {
	snap updates.Snapshot
	// rollout is the open rollout and last the latest that ended; either may be
	// nil.
	rollout, last *store.UpdateRollout
	hosts         []*store.Host
	// attempts is the attempts to the releases machines would be taken to now
	// and the rollouts' steps, open and ended, with every open attempt.
	attempts []store.UpdateAttempt
}

// updatesSnapshot reads everything the planner decides on. It decides
// nothing itself: the rows go into the snapshot as they are, and Decide works
// out from them which failures count, so the rule that halts a rollout is one
// a table of pure tests can try.
//
// The settings and the helper are passed in, because the status has just read
// both: a second reading of the settings could give the snapshot another mode
// than the status beside it, and a second probe would read the folder twice.
func (c *Controller) updatesSnapshot(ctx context.Context, cfg config.Updates, helper helperProbe) (*updatesPicture, error) {
	pic := &updatesPicture{}
	s := updates.Snapshot{
		Now: c.Now(), Mode: updateModeOf(cfg.Mode), Soak: cfg.Soak, Running: version.Version,
		GOOS: runtime.GOOS, GOARCH: runtime.GOARCH, Fenced: !c.mayAct(), HostGraceUntil: c.hostGraceUntil(),
	}
	if state := c.latestRelease(); state != nil {
		s.Releases = state.Releases
	}
	switch {
	case helper.ready:
		s.Helper = updates.HelperStateReady
	case helper.view.State == HelperUnsupported:
		s.Helper = updates.HelperStateUnsupported
		s.HelperWhyNot = helperUnsupportedWhy(updates.HelperSupport(c.helperHostFacts()), "this controller")
	default:
		s.Helper = updates.HelperStateMissing
	}

	var err error
	if pic.rollout, err = c.st.OpenUpdateRollout(ctx); errors.Is(err, store.ErrNotFound) {
		pic.rollout = nil
	} else if err != nil {
		return nil, fmt.Errorf("reading the open rollout: %w", err)
	}
	if pic.last, err = c.st.LastEndedUpdateRollout(ctx); errors.Is(err, store.ErrNotFound) {
		pic.last = nil
	} else if err != nil {
		return nil, fmt.Errorf("reading the last rollout: %w", err)
	}
	s.Rollout, s.LastRollout = rolloutFacts(pic.rollout), rolloutFacts(pic.last)

	// What the planner decides on is a machine's attempts to the release it
	// would be taken to now (the hosts' target and the controller's choice) and
	// the rollouts' steps, not the newest attempts fleet-wide: a host's two
	// failures must hold however many other attempts are newer.
	tags := tagsInQuestion(s)
	var rollouts []string
	for _, r := range []*store.UpdateRollout{pic.rollout, pic.last} {
		if r != nil {
			rollouts = append(rollouts, r.ID)
		}
	}
	recent, err := c.st.UpdateAttemptsFor(ctx, tags, rollouts)
	if err != nil {
		return nil, fmt.Errorf("reading the update attempts: %w", err)
	}
	open, err := c.st.OpenUpdateAttempts(ctx)
	if err != nil {
		return nil, fmt.Errorf("reading the open update attempts: %w", err)
	}
	pic.attempts = recent
	for _, a := range open {
		if !slices.ContainsFunc(recent, func(r store.UpdateAttempt) bool { return r.ID == a.ID }) {
			pic.attempts = append(pic.attempts, a)
		}
	}

	if pic.hosts, err = c.fleetHosts(ctx); err != nil {
		return nil, fmt.Errorf("listing the hosts: %w", err)
	}
	byHost := make(map[string]*updates.HostFacts, len(pic.hosts))
	target := hostTarget()
	for _, h := range pic.hosts {
		can, why, _ := hostCanSelfUpdate(h, target, c.hostHelperUnsupported(h), s.Mode, c.rentedHost(h.ID))
		s.Hosts = append(s.Hosts, updates.HostFacts{
			ID: h.ID, Name: h.Name, Version: h.Version, GOOS: h.OS, GOARCH: h.Arch,
			Embedded: h.Embedded, Healthy: h.Healthy(s.Now), CanSelfUpdate: can, WhyNot: why,
			ActiveRunners: h.ActiveRunners,
		})
	}
	for i := range s.Hosts {
		byHost[s.Hosts[i].ID] = &s.Hosts[i]
	}
	var gone []updates.HostFacts
	for _, a := range pic.attempts {
		facts := attemptFacts(a)
		switch {
		case a.Scope == store.UpdateScopeController && a.State == store.UpdateRequested:
			s.Controller = &facts
		case a.Scope == store.UpdateScopeController:
			s.ControllerEnded = append(s.ControllerEnded, facts)
		case byHost[a.HostID] == nil && a.State == store.UpdateRequested:
			// A host with no row and an attempt still open: deleting a host
			// cancels its attempt in the same transaction, so this is a race
			// or a fault, and something may still be restarting. It blocks the
			// next start as any open attempt does, and times out as one.
			gone = append(gone, updates.HostFacts{ID: a.HostID, Name: a.HostID, Open: &facts})
		case byHost[a.HostID] == nil:
		case a.State == store.UpdateRequested:
			byHost[a.HostID].Open = &facts
		default:
			byHost[a.HostID].Ended = append(byHost[a.HostID].Ended, facts)
		}
	}
	s.Hosts = append(s.Hosts, gone...)
	pic.snap = s
	return pic, nil
}

// tagsInQuestion is the releases a machine would be taken to now: the hosts'
// target and the controller's choice. The planner reads the attempts to them,
// and the retention pass keeps their failures, so both ask the same question
// of the same snapshot fields.
func tagsInQuestion(s updates.Snapshot) []string {
	var tags []string
	if target := hostTarget(); target != "" {
		tags = append(tags, target)
	}
	choice := updates.Choose(updates.ChooseInput{Mode: s.Mode, Soak: s.Soak, Now: s.Now, Running: s.Running,
		Releases: s.Releases, GOOS: s.GOOS, GOARCH: s.GOARCH})
	if tag := choice.Release.Tag; tag != "" && !slices.Contains(tags, tag) {
		tags = append(tags, tag)
	}
	return tags
}

// retainedUpdateTags is the releases whose failed attempts the retention pass
// keeps: tagsInQuestion, read from the settings and releases the snapshot would
// be made from, and the release the controller's latest attempt was for. The
// last is there because with updating off no release list is read, so the
// choice names nothing, and the controller's failures would otherwise age out
// and the cap restart when updating is turned on again.
func (c *Controller) retainedUpdateTags(ctx context.Context, now time.Time) ([]string, error) {
	cfg := c.cfg().Updates
	s := updates.Snapshot{Now: now, Mode: updateModeOf(cfg.Mode), Soak: cfg.Soak, Running: version.Version,
		GOOS: runtime.GOOS, GOARCH: runtime.GOARCH}
	if state := c.latestRelease(); state != nil {
		s.Releases = state.Releases
	}
	tags := tagsInQuestion(s)
	last, err := c.st.ListUpdateAttempts(ctx, store.UpdateScopeController, "", 1)
	if err != nil {
		return nil, fmt.Errorf("reading the controller's latest update attempt: %w", err)
	}
	if len(last) == 1 && !slices.Contains(tags, last[0].ToVersion) {
		tags = append(tags, last[0].ToVersion)
	}
	return tags, nil
}

func rolloutFacts(r *store.UpdateRollout) *updates.Rollout {
	if r == nil {
		return nil
	}
	return &updates.Rollout{
		ID: r.ID, Target: r.Target, Trigger: r.Trigger, State: r.State, HaltedReason: r.HaltedReason,
		HostIDs: slices.Clone([]string(r.HostIDs)), Since: r.ResumedAt, CancelledBy: r.CancelledBy,
	}
}

func attemptFacts(a store.UpdateAttempt) updates.Attempt {
	out := updates.Attempt{
		ID: a.ID, Scope: a.Scope, HostID: a.HostID, To: a.ToVersion, State: a.State,
		RequestedAt: a.RequestedAt, Error: a.Error,
	}
	if a.FinishedAt != nil {
		out.FinishedAt = *a.FinishedAt
	}
	return out
}

// runUpdatePlan asks the planner what to do and does it, and says whether
// anything changed. A snapshot that cannot be read is a pass that does nothing:
// the next one reads it again.
func (c *Controller) runUpdatePlan(ctx context.Context) bool {
	if !c.mayAct() {
		return false
	}
	pic, err := c.updatesSnapshot(ctx, c.cfg().Updates, c.probeUpdateHelper())
	if err != nil {
		if ctx.Err() == nil {
			c.log.Warn("could not read what automatic updating decides on; the next pass will try again", "error", err)
		}
		return false
	}
	return c.applyUpdatePlan(ctx, pic, updates.Decide(pic.snap))
}

// applyUpdatePlan carries out a plan, in order. Each step is the method a
// button calls, with the auto-update identity, so the planner can do nothing a
// person pressing the same button could not, and is refused by the same rules.
//
// The controller writes the audit row itself here, and only here: a person's
// press is audited by the handler that took it.
func (c *Controller) applyUpdatePlan(ctx context.Context, pic *updatesPicture, plan updates.Plan) bool {
	// Checked again, because the snapshot was read a moment ago and a fence or a
	// lost lease since then must stop the plan, not the next one.
	if !c.mayAct() {
		return false
	}
	changed, requested := false, false
	for _, step := range plan.Actions {
		switch step.Kind {
		case updates.ActionTimeOut:
			changed = c.autoTimeOut(ctx, pic, step) || changed
		case updates.ActionRequestController, updates.ActionUpdateHost:
			// The helper's path unit allows five starts in ten minutes, so a pass
			// writes at most one request, whatever a plan holds.
			if requested {
				continue
			}
			requested = true
			if step.Kind == updates.ActionRequestController {
				changed = c.autoRequestController(ctx, step) || changed
			} else {
				changed = c.autoUpdateHost(ctx, pic, step) || changed
			}
		case updates.ActionStartRollout:
			changed = c.autoStartRollout(ctx, step) || changed
		case updates.ActionHalt, updates.ActionFinishRollout, updates.ActionCancelRollout:
			changed = c.autoEndRollout(ctx, pic, step) || changed
		}
	}
	return changed
}

// autoAudit writes the audit row of one of the planner's own steps.
func (c *Controller) autoAudit(ctx context.Context, action, targetID string, detail map[string]any) {
	auth.NewAuditor(c.st, c.bus, c.log).Act(context.WithoutCancel(ctx), auth.AutoUpdateIdentity(), action, "update", targetID, detail)
}

func (c *Controller) autoTimeOut(ctx context.Context, pic *updatesPicture, step updates.Action) bool {
	i := slices.IndexFunc(pic.attempts, func(a store.UpdateAttempt) bool { return a.ID == step.AttemptID })
	if i < 0 || pic.attempts[i].State != store.UpdateRequested {
		return false
	}
	a := pic.attempts[i]
	// Not audited: the pass's own closer records the same time-out without a
	// row, and which of the two saw the ninetieth minute first is chance. The
	// attempt's state and error are the record.
	return c.endAttempt(ctx, a, store.UpdateTimedOut, timedOutText(a))
}

func (c *Controller) autoRequestController(ctx context.Context, step updates.Action) bool {
	_, id, err := c.requestControllerUpdate(ctx, autoUpdateActor(), step.Tag, askedByPlanner)
	if err != nil {
		c.log.Warn("automatic updating could not ask for the controller's update; the next pass will decide again", "to", step.Tag, "error", err)
		return false
	}
	c.autoAudit(ctx, "update.controller_requested", id, map[string]any{"from": version.Version, "to": step.Tag, "reason": step.Reason})
	return true
}

// beforeRolloutStep runs between autoUpdateHost's second reading of the
// rollout and the host's attempt being written. It does nothing; it is a
// variable so that a test can land a cancel in that gap.
var beforeRolloutStep = func(*Controller) {}

func (c *Controller) autoUpdateHost(ctx context.Context, pic *updatesPicture, step updates.Action) bool {
	if pic.rollout == nil {
		return false
	}
	// Read again: a person may have cancelled or halted the rollout, or switched
	// to manual, since the snapshot, and a host asked now would restart after
	// they said stop. Only the same rollout, still running, and in manual one a
	// person started, is moved on.
	now, err := c.st.OpenUpdateRollout(ctx)
	if err != nil || now.ID != pic.rollout.ID || now.State != store.RolloutRunning ||
		(c.updateMode() != updates.ModeAuto && now.Trigger != store.UpdateTriggerManual) {
		if err != nil && !errors.Is(err, store.ErrNotFound) {
			c.log.Warn("automatic updating could not read the open rollout again before asking a host; the next pass will decide again", "error", err)
		}
		return false
	}
	beforeRolloutStep(c)
	// A cancel or halt can still land here, after the read above. The store
	// writes the step only while the rollout runs, in the insert's own
	// transaction, so a host is never asked for a rollout a person stopped.
	_, attempt, err := c.requestHostUpdate(ctx, autoUpdateActor(), step.HostID,
		updateAsk{trigger: store.UpdateTriggerAuto, rolloutID: pic.rollout.ID})
	if errors.Is(err, store.ErrRolloutNotRunning) {
		c.log.Info("the rollout stopped before its next host was asked, so that host was not asked",
			"host", step.HostID, "rollout", pic.rollout.ID)
		return false
	}
	if err != nil {
		c.log.Warn("automatic updating could not ask a host to update; the next pass will decide again",
			"host", step.HostID, "rollout", pic.rollout.ID, "error", err)
		return false
	}
	c.autoAudit(ctx, "update.host_requested", attempt.ID, map[string]any{
		"host": step.HostID, "from": attempt.FromVersion, "to": attempt.ToVersion, "rollout": pic.rollout.ID, "reason": step.Reason,
	})
	return true
}

func (c *Controller) autoStartRollout(ctx context.Context, step updates.Action) bool {
	r := &store.UpdateRollout{Target: step.Tag, Trigger: store.UpdateTriggerAuto, StartedBy: requestedBy(autoUpdateActor())}
	if err := c.st.CreateUpdateRollout(ctx, r); err != nil {
		// A conflict is a person's rollout started since the snapshot, which is
		// the one to carry on.
		if !errors.Is(err, store.ErrConflict) {
			c.log.Warn("automatic updating could not start a rollout; the next pass will decide again", "to", step.Tag, "error", err)
		}
		return false
	}
	c.log.Info("automatic updating started a rollout", "rollout", r.ID, "to", r.Target)
	c.autoAudit(ctx, "update.rollout_started", r.ID, map[string]any{"to": r.Target, "reason": step.Reason})
	// The first host goes on the next pass, which is now rather than in ten
	// seconds.
	c.KickUpdates()
	return true
}

// autoEndRollout halts, finishes or cancels the rollout the planner saw. Each
// move is guarded by the state it is from, so one a person made since the
// snapshot stands, and this one is dropped.
func (c *Controller) autoEndRollout(ctx context.Context, pic *updatesPicture, step updates.Action) bool {
	if pic.rollout == nil {
		return false
	}
	id := pic.rollout.ID
	var moved bool
	var err error
	var action string
	switch step.Kind {
	case updates.ActionHalt:
		action = "update.rollout_halted"
		moved, err = c.st.HaltUpdateRollout(ctx, id, step.Reason)
	case updates.ActionFinishRollout:
		action = "update.rollout_finished"
		moved, err = c.st.FinishUpdateRollout(ctx, id, store.RolloutDone)
	default:
		action = "update.rollout_cancelled"
		moved, err = c.st.FinishUpdateRollout(ctx, id, store.RolloutCancelled)
	}
	if err != nil {
		c.log.Warn("automatic updating could not record where a rollout stands; the next pass will decide again", "rollout", id, "error", err)
		return false
	}
	if !moved {
		return false
	}
	c.log.Info("automatic updating moved a rollout on", "rollout", id, "to", pic.rollout.Target, "action", action, "reason", step.Reason)
	c.autoAudit(ctx, action, id, map[string]any{"to": pic.rollout.Target, "host": step.HostID, "reason": step.Reason})
	return true
}

// RolloutChange is what a person's start, resume or cancel did: the rollout it
// acted on, and whether that moved. The handler audits it, so a press that
// moved nothing (a resume of a rollout already running) is still recorded, and
// says so rather than claiming it resumed something.
type RolloutChange struct {
	ID, Target string
	Changed    bool
}

// ErrUnknownHost refuses a rollout of a host id that names no host. It is not
// store.ErrNotFound, which the API answers as the route's own 404: an id the
// caller sent is the body to fix.
var ErrUnknownHost = errors.New("no host has that id")

// unknownHostError reads as the sentence that names the id, and is still
// ErrUnknownHost to errors.Is, so the handler needs no prefix trimmed off.
type unknownHostError struct{ id string }

func (e *unknownHostError) Error() string {
	return fmt.Sprintf("no host has the id %q; list the hosts to find it", cutAt(e.id, 64))
}
func (e *unknownHostError) Is(target error) bool { return target == ErrUnknownHost }

// StartHostRollout starts a rollout of every host behind this controller's
// release, or of hostIDs, and returns the status with it. The planner moves it
// on from the next pass, one host at a time; nothing is asked of a host here.
//
// by is only written down, as the rollout's started_by. The handler that took
// the request audits it with the caller's identity. Once the rollout is written
// the change names it even when the status after it cannot be worked out, so
// that the handler can audit a rollout that exists before it reports the
// failure.
func (c *Controller) StartHostRollout(ctx context.Context, by UpdateActor, hostIDs []string) (*UpdatesView, RolloutChange, error) {
	var none RolloutChange
	if !c.mayAct() {
		return nil, none, fmt.Errorf("%w: %s", ErrUpdateFenced, c.notActingReason())
	}
	mode := readUpdateMode(c)
	if mode == updates.ModeOff {
		return nil, none, ErrUpdateModeOff
	}
	target := hostTarget()
	if target == "" {
		return nil, none, ErrUpdateNotARelease
	}
	if err := c.refuseOverOpenRollout(ctx); err != nil {
		return nil, none, err
	}
	// One listing of the fleet, and the ids read against it: a repeated id is
	// one host, and the list can never be longer than the fleet.
	fleet, err := c.st.ListHosts(ctx)
	if err != nil {
		return nil, none, fmt.Errorf("listing the hosts: %w", err)
	}
	hosts := fleet
	var ids store.StringSlice
	if len(hostIDs) > 0 {
		byID := make(map[string]*store.Host, len(fleet))
		for _, h := range fleet {
			byID[h.ID] = h
		}
		hosts = nil
		for _, id := range hostIDs {
			h, ok := byID[id]
			if !ok {
				return nil, none, &unknownHostError{id: id}
			}
			if slices.Contains(ids, id) {
				continue
			}
			hosts, ids = append(hosts, h), append(ids, id)
		}
	}
	behind, able := 0, 0
	for _, h := range hosts {
		if !hostBehind(h, target) {
			continue
		}
		behind++
		if can, _, _ := hostCanSelfUpdate(h, target, c.hostHelperUnsupported(h), mode, c.rentedHost(h.ID)); can {
			able++
		}
	}
	switch {
	case behind == 0:
		return nil, none, fmt.Errorf("%w: no host asked for runs a release behind %s", ErrUpdateNothingNewer, target)
	case able == 0:
		return nil, none, &hostCannotUpdateError{sentence: fmt.Sprintf("No host behind %s can update itself, because none has the update helper installed. "+
			"Run sudo zoomies updates helper install on each Linux host, or update them by hand as their cards say.", target)}
	}
	r := &store.UpdateRollout{Target: target, Trigger: store.UpdateTriggerManual, StartedBy: requestedBy(by), HostIDs: ids}
	if err := c.st.CreateUpdateRollout(ctx, r); err != nil {
		if errors.Is(err, store.ErrConflict) {
			if err := c.refuseOverOpenRollout(ctx); err != nil {
				return nil, none, err
			}
			return nil, none, ErrUpdateInProgress
		}
		return nil, none, fmt.Errorf("recording the rollout: %w", err)
	}
	c.log.Info("a rollout was started", "rollout", r.ID, "to", target, "hosts", len(ids), "started_by", r.StartedBy)
	c.KickUpdates()
	change := RolloutChange{ID: r.ID, Target: r.Target, Changed: true}
	view, err := c.publishUpdates(ctx)
	return view, change, err
}

// refuseOverOpenRollout is the refusal for a rollout asked for while one is
// open: halted is waiting for a person to look, and running is in progress.
func (c *Controller) refuseOverOpenRollout(ctx context.Context) error {
	r, err := c.st.OpenUpdateRollout(ctx)
	switch {
	case errors.Is(err, store.ErrNotFound):
		return nil
	case err != nil:
		return fmt.Errorf("reading the open rollout: %w", err)
	case r.State == store.RolloutHalted:
		return ErrUpdateRolloutHalted
	}
	return ErrUpdateInProgress
}

// openRolloutFor is the open rollout, for a person resuming or cancelling it,
// with the refusals they share.
func (c *Controller) openRolloutFor(ctx context.Context, doing string) (*store.UpdateRollout, error) {
	if !c.mayAct() {
		return nil, fmt.Errorf("%w: %s", ErrUpdateFenced, c.notActingReason())
	}
	if c.updateMode() == updates.ModeOff {
		return nil, ErrUpdateModeOff
	}
	r, err := c.st.OpenUpdateRollout(ctx)
	if errors.Is(err, store.ErrNotFound) {
		return nil, fmt.Errorf("%w: there is no rollout to %s", store.ErrNotFound, doing)
	}
	if err != nil {
		return nil, fmt.Errorf("reading the open rollout: %w", err)
	}
	return r, nil
}

// ResumeRollout lets a halted rollout carry on. The failure it halted on stays
// on the host's attempt, and the planner reads only failures after the resume,
// so the host that failed waits out its retry and the rollout goes on. A
// rollout already running is left as it is, and the change says nothing moved.
func (c *Controller) ResumeRollout(ctx context.Context, by UpdateActor) (*UpdatesView, RolloutChange, error) {
	r, err := c.openRolloutFor(ctx, "resume")
	if err != nil {
		return nil, RolloutChange{}, err
	}
	moved, err := c.st.ResumeUpdateRollout(ctx, r.ID)
	if err != nil {
		return nil, RolloutChange{}, fmt.Errorf("resuming the rollout: %w", err)
	}
	if moved {
		c.log.Info("a rollout was resumed", "rollout", r.ID, "to", r.Target, "resumed_by", requestedBy(by))
		c.KickUpdates()
	}
	view, err := c.publishUpdates(ctx)
	return view, RolloutChange{ID: r.ID, Target: r.Target, Changed: moved}, err
}

// CancelRollout ends the open rollout. An update a helper has already been
// handed finishes by itself and is recorded; nothing new starts for the rollout.
// Who cancelled is kept, because auto does not start again what a person
// stopped.
func (c *Controller) CancelRollout(ctx context.Context, by UpdateActor) (*UpdatesView, RolloutChange, error) {
	r, err := c.openRolloutFor(ctx, "cancel")
	if err != nil {
		return nil, RolloutChange{}, err
	}
	moved, err := c.st.CancelUpdateRollout(ctx, r.ID, requestedBy(by))
	if err != nil {
		return nil, RolloutChange{}, fmt.Errorf("cancelling the rollout: %w", err)
	}
	if moved {
		c.log.Info("a rollout was cancelled", "rollout", r.ID, "to", r.Target, "cancelled_by", requestedBy(by))
		c.KickUpdates()
	}
	view, err := c.publishUpdates(ctx)
	return view, RolloutChange{ID: r.ID, Target: r.Target, Changed: moved}, err
}

package controller

import (
	"errors"
	"fmt"
)

// ErrUpdateCheckDisabled is the answer to asking for a release check while
// updates.check_interval is 0. That setting is the air-gap switch: it keeps the
// one request Zoomies makes to github.com that is not about the fleet from ever
// being made, and a button must not make it either.
var ErrUpdateCheckDisabled = errors.New("the release check is switched off, so this controller does not ask github.com which release is current; set updates.check_interval to a duration such as 24h to turn it on")

// ErrUpdateCheckFailed is the answer to a release check that GitHub, or the
// network to it, did not allow to finish. It is not a refusal of the person's
// request: the request was fine, and what failed is outside this controller. The
// error that carries it keeps its own sentence, which says what failed and what
// to try, because that is what the person who pressed the button can act on.
var ErrUpdateCheckFailed = errors.New("the release check could not be completed")

// updateCheckError is a failed release check that reads as its own sentence and
// is still ErrUpdateCheckFailed to errors.Is. Wrapping the sentinel with %w would
// put its generic text in front of the sentence the person needs.
type updateCheckError struct {
	sentence string
	cause    error
}

func (e *updateCheckError) Error() string        { return e.sentence }
func (e *updateCheckError) Unwrap() error        { return e.cause }
func (e *updateCheckError) Is(target error) bool { return target == ErrUpdateCheckFailed }

// checkFailed is a release check that failed, in the sentence that explains it.
func checkFailed(cause error, format string, args ...any) error {
	return &updateCheckError{sentence: fmt.Sprintf(format, args...), cause: cause}
}

// The refusals of an update. Each is a sentinel so that the API can give it a
// stable code, and each is written for the person who pressed the button: what
// stopped it, and what to change. A refusal that needs a detail (which folder,
// which release) wraps its sentinel, so the code survives the detail.
var (
	// ErrUpdateModeOff refuses every update while updates.mode is off, which is
	// the promise that mode makes: Zoomies says a release exists and does nothing
	// about it.
	ErrUpdateModeOff = errors.New("updates.mode is off, so this controller updates nothing; set updates.mode to manual on the Settings page to update from here")
	// ErrUpdateHelperMissing refuses an update nothing on the host could carry
	// out. Only the helper, installed by the host's owner, may replace a binary.
	ErrUpdateHelperMissing = errors.New("the update helper is not ready on this host")
	// ErrUpdateInProgress refuses a second update while one is open for the same
	// target, so that two people, or a person and the planner, never send two
	// requests.
	ErrUpdateInProgress = errors.New("an update is already in flight for this target; wait for it to finish, or for it to time out after 90 minutes, before asking again")
	// ErrUpdateNotARelease refuses to update a build that did not come from a
	// release. A build from main is usually ahead of every release, and taking one
	// would be a downgrade.
	ErrUpdateNotARelease = errors.New("this controller is not running a release, so no release can be compared with it: a build from main is usually ahead of every release; install a release with zoomies upgrade to update from here")
	// ErrUpdateNothingNewer refuses an update that would change nothing, or would
	// go backwards.
	ErrUpdateNothingNewer = errors.New("there is no newer release to take")
	// ErrUpdateHostCannotUpdate refuses to update a host whose agent cannot
	// update itself, because no helper has been installed on it.
	ErrUpdateHostCannotUpdate = errors.New("this host cannot update itself: its agent does not offer it, which it does only once the update helper is installed on the host; run \"sudo zoomies updates helper install\" there, or update it by hand")
	// ErrUpdateRolloutHalted refuses to start an update while a rollout is halted
	// after a failure, which is waiting for a person to look.
	ErrUpdateRolloutHalted = errors.New("the rollout is halted after a failed update; resume it or cancel it before starting another")
	// ErrUpdateFenced refuses an update while this controller may not act: the
	// fleet is fenced for recovery, or another controller holds the database's
	// lease. A restored copy must not replace the binary of a live deployment.
	ErrUpdateFenced = errors.New("this controller may not act right now, so it starts no update")
)

package controller

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"
	"unicode"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/naming"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/updates"
	"github.com/eyupio/zoomies/internal/version"
)

// hostSightLimit is how many of the newest host attempts a look reads to find
// each host's latest. A host whose last attempt is older than that many others
// shows none, which is history and not something in flight: every open attempt
// is read as well, however old.
const hostSightLimit = 500

// HostUpdateView is a host's part in updating, as its card shows it: the latest
// attempt that still says something about the host, whether it can be updated
// now, and why in a sentence.
//
// It holds nothing that moves with the clock or with a heartbeat, so the card
// is sent again only when one of these changes.
type HostUpdateView struct {
	// State is the latest attempt's state while it says something about the
	// host: requested, succeeded, failed, timed_out or cancelled. It is none when
	// there is no such attempt, including one that failed before the host
	// reached its release some other way (attemptIsHistory says what counts as
	// that), and unsupported in its place for a host behind the controller that
	// the helper can never be installed on.
	State string `json:"state"`
	// Reason is the sentence the card shows. For an attempt that ended without
	// the update it is the reason recorded for it, often the helper's own, which
	// can name a path on the host: only the platform role reads it (see For).
	Reason string `json:"reason"`
	// CanUpdate says whether asking for an update now would be taken.
	CanUpdate bool `json:"can_update"`
	// AttemptID is the attempt State describes, and empty with none.
	AttemptID string `json:"attempt_id"`
	// Code is the problem code of the failure State describes when it has a
	// cause of its own worth naming, and empty otherwise. Today that is
	// host.update_helper_stuck: the helper on the host had stopped reading
	// requests. Its Reason is built from fixed words and numbers, so every role
	// reads it, unlike the helper's own sentence.
	Code string `json:"code"`
}

// The states of a host with no attempt worth showing.
const (
	HostUpdateNone = "none"
	// HostUpdateUnsupported is a host behind the controller that the update
	// helper can never be installed on, so the command on its card is the way.
	HostUpdateUnsupported = "unsupported"
)

// For is the update block as one audience may read it. The platform reads it
// whole; every other role is given a fixed sentence for an ended attempt in
// place of its reason, and still learns that it ended and how. It works on the
// fields alone, so the event stream can apply it to a frame it has decoded.
func (u HostUpdateView) For(platform bool) HostUpdateView {
	switch {
	case platform:
		return u
	case u.Code != "":
		// Built from fixed words and numbers by the controller, never the helper's.
		return u
	case u.State == store.UpdateFailed, u.State == store.UpdateTimedOut, u.State == store.UpdateCancelled:
		u.Reason = withheldAttemptError(u.State)
	}
	return u
}

// For is the host as one audience may read it: HostView renders the platform's
// form, and every handler that answers with a host passes it through here with
// the caller's role. The view it returns has an update block of its own, so the
// one it was called on, which may be shared, is never changed.
func (v HostView) For(platform bool) HostView {
	if v.Update == nil {
		return v
	}
	u := v.Update.For(platform)
	v.Update = &u
	return v
}

// hostUpdateGap is what stands between a host that is behind and its update,
// where the update helper is part of the answer. The card and the problems list
// both read it, so the note that a host cannot be updated from here is raised
// for exactly the hosts whose card says so.
type hostUpdateGap int

const (
	// hostGapNone is a host with nothing about the helper to say: it can be
	// updated, it has nothing to update, or something else is in the way.
	hostGapNone hostUpdateGap = iota
	// hostGapHelperMissing is a host whose agent does not offer to update
	// itself, which an install of the helper would change.
	hostGapHelperMissing
	// hostGapHelperImpossible is a host the helper can never be installed on.
	hostGapHelperImpossible
)

// modeOffForHosts is the card's sentence for a host that could be asked but for
// the mode. Every role reads it, so it names the setting and no path.
const modeOffForHosts = "Updating is off, so hosts are not updated from here. Somebody with the platform role can turn it on by " +
	"setting updates.mode to manual or auto on the Configuration page."

// hostCanSelfUpdate is the single place that says whether a host can be updated
// from here, and if not, why, in a sentence for the card. The view, the request,
// the problems list and the planner all ask it, so the button, the note and the
// planner never disagree.
//
// target is the release the host would be taken to, empty when this controller
// is not a release; unsupported is why the helper can never be installed on the
// host, or nothing known. A host that cannot have it is said to be so only where
// that is why it cannot be updated, so the card never explains a helper to a
// host that has nothing to update.
//
// The mode is asked after everything that turning updating on would not
// change, so a host the helper can never serve keeps saying the command is the
// way, and before the helper is: while updating is off nothing is offered, and
// a card asking for a root unit to be installed would be offering something.
//
// A machine this fleet rents is asked about before any of it. It is behind, it
// can never have the helper and no mode makes a difference: its agent is the
// one its provider's template carried, and the template is what an operator
// changes. Its card and the provider's problem both read that answer from
// here and rentedMachineAdvice.
func hostCanSelfUpdate(h *store.Host, target string, unsupported updates.HelperUnsupported, mode updates.Mode, rented rentedHost) (can bool, why string, gap hostUpdateGap) {
	switch {
	case h.Embedded:
		return false, "This is the agent inside the controller, so it is updated with the controller, from Settings → Updates.", hostGapNone
	case rented.rented():
		// Nothing about the helper, the mode or a command has anything to do
		// with a machine Zoomies rents, so none of it is asked. The answer is
		// the template its provider clones from, and the gap stays none: the
		// problem list names that template once for the provider, and an entry
		// per rented machine would say the same thing a hundred times.
		return false, rentedMachineAdvice(rented, target), hostGapNone
	case target == "":
		return false, "This controller is not running a release or a build from main, so there is nothing to take its hosts to. Install a release on the controller with zoomies upgrade first.", hostGapNone
	case strings.TrimSpace(h.Version) == "":
		return false, "This host's agent has not said which version it runs, so Zoomies cannot tell whether " + target + " is newer. " +
			"Update it on the host with the command below.", hostGapNone
	}
	// Only a release build can be behind. CompareBuilds reads what follows a
	// hyphen as a pre-release, so a describe build such as 1.3.5-3-gabcdef1,
	// which is ahead of v1.3.5, would otherwise read as behind it, and the
	// button would take it back. The planner keeps the same gate of its own.
	switch skew := updates.HostSkew(h.Version, target); {
	case skew == version.SkewDiffers && version.IsMainBuild(target):
		return false, "This host runs the build " + reportedVersion(h.Version) + ", which is neither a release nor a build from main, so Zoomies leaves it alone. " +
			byHand(h), hostGapNone
	case skew == version.SkewDiffers:
		return false, "This host runs the build " + reportedVersion(h.Version) + ", which is not a release build, so Zoomies cannot tell whether " +
			target + " is newer. " + byHand(h), hostGapNone
	}
	switch updates.HostSkew(h.Version, target) {
	case version.SkewNone, version.SkewAhead:
		return false, "This host already runs " + target + " or a later release, so there is nothing to update.", hostGapNone
	case version.SkewDiffers:
		return false, "This host runs the build " + reportedVersion(h.Version) + ", which is not a release build, so Zoomies cannot tell whether " +
			target + " is newer. " + byHand(h), hostGapNone
	}
	selfUpdates := h.Supports(agent.FeatureSelfUpdate)
	if !selfUpdates && unsupported != "" {
		return false, "The update helper cannot be installed on this host: " + helperUnsupportedWhy(unsupported, "its agent") +
			". " + byHand(h), hostGapHelperImpossible
	}
	if mode == updates.ModeOff {
		return false, modeOffForHosts, hostGapNone
	}
	if !selfUpdates {
		return false, "This host's agent does not offer to update itself, which it does only once the update helper is installed on the host. " +
			"Run sudo zoomies updates helper install there, or update it with the command below.", hostGapHelperMissing
	}
	return true, "This host runs " + reportedVersion(h.Version) + " and can be updated to " + target + ".", hostGapNone
}

// byHand is the end of a card's sentence that sends a person to update the
// host on the host itself. Every host has a command at the foot of its card
// (see hostUpgrade): sudo zoomies upgrade, or the installer script on Windows.
func byHand(*store.Host) string {
	return "Update it on the host with the command below."
}

// hostBehind says whether a host runs a release build older than target: the
// hosts a rollout to target is for, whether or not each can update itself.
// hostCanSelfUpdate asks the same of the version, so the two never disagree.
func hostBehind(h *store.Host, target string) bool {
	if h.Embedded || target == "" {
		return false
	}
	return updates.HostSkew(h.Version, target) == version.SkewBehind
}

// hostTarget is the build every host is taken to: the release this controller
// runs, or its exact build when that is from main, and nothing when it is
// neither.
func hostTarget() string {
	tag, _ := updates.HostTarget(version.Version)
	return tag
}

// attemptIsHistory says whether an attempt that ended without the update has
// stopped saying anything about a host whose agent reports running. target is
// what the controller would take the host to now, empty when it is neither a
// release nor a build from main. The card and the problems list both ask it, so
// that neither shows a failure the other has forgotten.
//
// An attempt is history once the host runs the release or build it asked for, or
// a later release, however the host got there. That cannot be the whole rule when
// a build from main is on either side, because CompareBuilds orders one against
// nothing: a host an operator brought to a later build by hand (sudo zoomies
// upgrade, after the helper refused the update) is never "at least" the build the
// attempt asked for, and a host on the build the controller has since moved to is
// never "at least" a release it was asked for before. The failure would stay for
// ever beside a card that says there is nothing to update and offers no button to
// press. So when the attempt or the controller's target is a build from main, the
// attempt is also history when the host runs at least what the controller would
// take it to now, since nothing is left to do for it. That is judged against the
// controller as it is now, so it can stop holding: once the controller moves to a
// newer build the host is behind again, and the failure shows until a new attempt
// opens, as after any failure of a host that is behind.
//
// Two releases are ordered, so an attempt at a release under a controller on a
// release is judged by that release alone, as it always was, and a host on an
// older release keeps its failure.
func attemptIsHistory(a store.UpdateAttempt, running, target string) bool {
	if runsAtLeast(running, a.ToVersion) {
		return true
	}
	if !version.IsMainBuild(a.ToVersion) && !version.IsMainBuild(target) {
		return false
	}
	return runsAtLeast(running, target)
}

// hostCannotUpdateError is a refusal that reads as the card's own sentence and is
// still ErrUpdateHostCannotUpdate to errors.Is, so the API gives it the stable
// code and the person reads what the card would have told them.
type hostCannotUpdateError struct{ sentence string }

func (e *hostCannotUpdateError) Error() string        { return e.sentence }
func (e *hostCannotUpdateError) Is(target error) bool { return target == ErrUpdateHostCannotUpdate }

// RequestHostUpdate asks a host's agent to have its helper take it to this
// controller's release, and returns the host with the attempt on it.
//
// The order is RequestControllerUpdateAttempt's: everything that can refuse does
// so before anything is written, and the attempt is recorded before the task is
// queued, because the store's one open attempt per host is what stops two callers
// each sending one. Nothing is dialled: the task goes out on the agent's own poll,
// and success is the host heartbeating the release, not the task's answer.
//
// The helper's path unit stops after five starts in ten minutes. One open attempt
// per host, and the planner's 30-minute wait after a failure, keep a host far below it.
func (c *Controller) RequestHostUpdate(ctx context.Context, by UpdateActor, hostID string) (*HostView, error) {
	view, _, err := c.requestHostUpdate(ctx, by, hostID, askedByHand)
	return view, err
}

// requestHostUpdate is RequestHostUpdate for either asker, returning the attempt
// it opened as well: the button and the planner go through every refusal alike,
// so the card and the planner never disagree about a host.
func (c *Controller) requestHostUpdate(ctx context.Context, by UpdateActor, hostID string, ask updateAsk) (*HostView, *store.UpdateAttempt, error) {
	if !c.mayAct() {
		return nil, nil, fmt.Errorf("%w: %s", ErrUpdateFenced, c.notActingReason())
	}
	// Read once, and the one reading answers both questions below. Read twice, a
	// switch to off between the two would pass the gate and then be refused as a
	// host that cannot update, with the wrong code for what happened.
	mode := readUpdateMode(c)
	if mode == updates.ModeOff {
		return nil, nil, ErrUpdateModeOff
	}
	h, err := c.st.GetHost(ctx, hostID)
	if err != nil {
		return nil, nil, err
	}
	target := hostTarget()
	if target == "" {
		return nil, nil, ErrUpdateNotARelease
	}
	if can, why, _ := hostCanSelfUpdate(h, target, c.hostHelperUnsupported(h), mode, c.rentedHost(h.ID)); !can {
		return nil, nil, &hostCannotUpdateError{sentence: why}
	}

	attempt := &store.UpdateAttempt{
		Scope: store.UpdateScopeHost, HostID: h.ID, FromVersion: h.Version, ToVersion: target,
		Trigger: ask.trigger, RequestedBy: requestedBy(by), RolloutID: ask.rolloutID,
	}
	if err := c.st.CreateUpdateAttempt(ctx, attempt); err != nil {
		if errors.Is(err, store.ErrConflict) {
			return nil, nil, ErrUpdateInProgress
		}
		return nil, nil, fmt.Errorf("recording the update attempt: %w", err)
	}
	c.log.Info("asked a host's agent to update it", "attempt", attempt.ID, "host", h.ID, "name", h.Name,
		"from", attempt.FromVersion, "to", target, "requested_by", attempt.RequestedBy)
	// Seen before the task is queued, so that a result coming back at once finds
	// the attempt it answers.
	c.lookAtHostUpdates(context.WithoutCancel(ctx))
	c.sendHostUpdate(h, *attempt)
	c.publishHost(h)
	view := c.HostView(h)
	return &view, attempt, nil
}

// sendHostUpdate queues the task for an open attempt, unless the host's agent
// has already taken it or would refuse it. It is called on every pass, because
// the queue lives in memory: a restart, or a task the agent never answered, is
// made good by queueing it again.
//
// enqueue stamps nothing and checks nothing, so the gates are here. An agent
// that does not advertise the feature answers an unknown kind with a failure,
// and the agent inside the controller is updated with the controller.
func (c *Controller) sendHostUpdate(h *store.Host, a store.UpdateAttempt) bool {
	if h == nil || !c.mayAct() || h.Embedded || !h.Supports(agent.FeatureSelfUpdate) {
		return false
	}
	if c.handedOver(a.ID) {
		return false
	}
	return c.enqueue(h.ID, agent.Task{Kind: agent.TaskUpdateAgent, UpdateID: a.ID, UpdateTag: updates.WireTag(a.ToVersion)})
}

// handedOver says whether the agent answered that it wrote this attempt's
// request, or already runs its release. After that the task is not sent again:
// the outcome comes on the heartbeat, and a second request would wait behind the
// first.
func (c *Controller) handedOver(attemptID string) bool {
	c.updates.handedMu.Lock()
	defer c.updates.handedMu.Unlock()
	return c.updates.handed[attemptID]
}

func (c *Controller) noteHandedOver(attemptID string) {
	c.updates.handedMu.Lock()
	defer c.updates.handedMu.Unlock()
	if c.updates.handed == nil {
		c.updates.handed = make(map[string]bool)
	}
	c.updates.handed[attemptID] = true
}

// withdrawHostUpdate takes an ended attempt's task back from its host's queue,
// waiting or held by the agent, so that a host that comes back after its attempt
// timed out is not then updated with nothing recording it.
func (c *Controller) withdrawHostUpdate(a store.UpdateAttempt) {
	c.updates.handedMu.Lock()
	delete(c.updates.handed, a.ID)
	c.updates.handedMu.Unlock()
	c.withdrawUpdateTasks(a.HostID, func(t agent.Task) bool { return t.UpdateID == a.ID }, true)
}

// withdrawHostUpdates takes back every update task of a host whose registration
// is going away, and forgets what the loop saw of it.
func (c *Controller) withdrawHostUpdates(hostID string) {
	c.withdrawUpdateTasks(hostID, func(agent.Task) bool { return true }, true)
	c.forgetHostUpdates(hostID)
}

// withdrawUpdateTasks drops a host's update tasks that match, without making a
// queue for a host that has none.
func (c *Controller) withdrawUpdateTasks(hostID string, match func(agent.Task) bool, inFlight bool) {
	q, ok := c.queues.all()[hostID]
	if !ok {
		return
	}
	q.withdraw(func(t agent.Task) bool { return t.Kind == agent.TaskUpdateAgent && match(t) }, inFlight)
}

// applyUpdateTaskResult takes the agent's answer to an update task. The answer
// says only whether the request reached the helper; whether the update worked
// comes on a later heartbeat, from the agent the update started.
func (c *Controller) applyUpdateTaskResult(ctx context.Context, hostID string, task agent.Task, known bool, res agent.TaskResult) {
	if !known || task.UpdateID == "" {
		// Not a task this process handed out, so the attempt it answers is not
		// known. The pass sends a task of its own while the attempt is open.
		return
	}
	switch {
	case res.OK:
		c.noteHandedOver(task.UpdateID)
		// A request written after the helper was found stopped and repaired: the
		// attempt goes on, and the repair is recorded for whoever asks why a
		// host's update took longer than usual.
		if res.Stuck != nil && c.mayAct() {
			c.noteHelperStuck(ctx, hostID, task.UpdateID, res.Stuck)
		}
		return
	case res.NotStarted:
		// Given back unstarted too often to offer again; the pass queues it anew.
		return
	case !c.mayAct():
		return
	}
	latest, err := c.st.ListUpdateAttempts(ctx, store.UpdateScopeHost, hostID, 1)
	if err != nil {
		c.log.Warn("could not read the update attempt an agent answered; it stays open until the host reports or it times out", "host", hostID, "error", err)
		return
	}
	// Only the open attempt of this host, and only the one the task was for: an
	// answer to an older task must not close a newer attempt.
	if len(latest) == 0 || latest[0].ID != task.UpdateID || latest[0].State != store.UpdateRequested {
		return
	}
	name := c.hostName(ctx, hostID)
	var text string
	// The agent found the helper stopped or busy. The sentence is the
	// controller's own, from the checked record, so that it names no path and
	// every role may read it.
	stuck := c.noteHelperStuck(ctx, hostID, latest[0].ID, res.Stuck)
	switch said := reportedSentence(res.Error); {
	case stuck != nil:
		text = stuckSentence(name, stuck)
	case strings.Contains(said, "unknown task kind"):
		text = "The agent on " + name + " is older than this controller and cannot update itself. Update it with the command on its card."
	case said == "":
		text = "The agent on " + name + " did not hand the request to its update helper, and gave no reason. Look at the agent's log on the host."
	default:
		text = cutAt("The agent on "+name+" did not hand the request to its update helper: "+said, maxHelperSentence)
	}
	_, _ = c.closeHostAttempt(ctx, latest[0], store.UpdateFailed, text)
}

// noteHostUpdate is what a heartbeat says about the host's open attempt: the
// host running the release, which is the only proof of success, or the helper's
// answer relayed by the agent. It says whether a report the beat carried was
// held rather than recorded, which the answer passes on so that the agent sends
// it again instead of taking it as delivered.
//
// The open attempt is the one the loop last saw, so a beat with nothing to say
// reads nothing. A beat that carries a result reads the store instead, because
// the agent sends a result until a beat has been answered without it held: one
// matched against a stale picture would be lost.
func (c *Controller) noteHostUpdate(ctx context.Context, h *store.Host, rep *agent.UpdateReport) (held bool) {
	if !c.mayAct() {
		if rep != nil {
			// So that the pass after the fence lifts gives the agent a beat to send
			// it again, however briefly the fence stood.
			c.updates.fenceSeen.Store(true)
			c.warnReportHeld(h, "this controller is fenced or does not hold the lease, so it records nothing until it may act again", nil)
		}
		return rep != nil
	}
	a, ok := c.hostAttempt(h.ID)
	if rep != nil {
		latest, err := readHostAttempt(c, ctx, h.ID)
		if err != nil {
			c.warnReportHeld(h, "the host's update attempt could not be read to match the result against", err)
			return true
		}
		if len(latest) == 1 {
			a, ok = latest[0], true
		}
	}
	if !ok || a.State != store.UpdateRequested {
		// A report with no open attempt of this host's to answer is ignored: an
		// agent relays whatever its update folder holds, which can be a result
		// for an attempt already closed, or for the controller itself where the
		// two share a folder.
		return false
	}
	state, text, ended := hostReportOutcome(a, h.Version, rep)
	if !ended {
		return false
	}
	closed, err := c.closeHostAttempt(ctx, a, state, text)
	if closed {
		c.publishHost(h)
	}
	return rep != nil && err != nil
}

// readHostAttempt is a host's latest attempt from the store. It is a variable
// so that a test can make the read fail once.
var readHostAttempt = func(c *Controller, ctx context.Context, hostID string) ([]store.UpdateAttempt, error) {
	return c.st.ListUpdateAttempts(ctx, store.UpdateScopeHost, hostID, 1)
}

// heldReportWarnEvery is how often one host's held report is logged. A fenced
// controller holds it on every beat until it may act, and a line every few
// seconds for each host would bury the one that says why it is fenced.
const heldReportWarnEvery = 10 * time.Minute

// warnReportHeld logs that a host's update result was held, and why, at most
// once per heldReportWarnEvery for each host.
func (c *Controller) warnReportHeld(h *store.Host, why string, err error) {
	now := c.Now()
	c.updates.heldMu.Lock()
	last, seen := c.updates.heldWarned[h.ID]
	if seen && now.Sub(last) < heldReportWarnEvery {
		c.updates.heldMu.Unlock()
		return
	}
	if c.updates.heldWarned == nil {
		c.updates.heldWarned = make(map[string]time.Time)
	}
	c.updates.heldWarned[h.ID] = now
	c.updates.heldMu.Unlock()
	attrs := []any{"host", h.ID, "name", h.Name, "reason", why}
	if err != nil {
		attrs = append(attrs, "error", err)
	}
	c.log.Warn("did not record the update result a host's agent reported; the agent sends it again until it is recorded", attrs...)
}

// hostReportOutcome says whether a host's open attempt has ended, from the
// version the host reports and the result its agent relays.
//
// Running the release, or a later one, is success, whatever the result says: an
// agent asked to update to a release it already runs answers with nothing
// written, and no result ever follows. Versions are compared with CompareBuilds,
// because a release binary reports 1.3.5 where the tag is v1.3.5.
//
// A result answers the attempt that carries its id. A failure without an id is
// the helper refusing a request it could not trust, which echoes no id; one
// finished after the attempt was asked for can only be the answer to it.
func hostReportOutcome(a store.UpdateAttempt, running string, rep *agent.UpdateReport) (state, text string, ended bool) {
	if runsAtLeast(running, a.ToVersion) {
		return store.UpdateSucceeded, "", true
	}
	if rep == nil {
		return "", "", false
	}
	switch {
	case rep.ID == a.ID:
	case rep.ID == "" && !rep.OK && rep.FinishedAt.After(a.RequestedAt):
	default:
		return "", "", false
	}
	if rep.OK {
		if channelMovedOn(a, running, rep) {
			return store.UpdateFailed, fmt.Sprintf("The update helper on the host installed %s from the dev channel and its agent runs it, "+
				"but this controller ran %s when the update was asked for, so the channel served a different build from the controller's. "+
				"The channel has moved on since this controller was built, or main CI has not published that build yet. "+
				"Once the controller and the channel agree (zoomies upgrade on the controller's host, or wait for main CI), update this host again.",
				reportedVersion(running), a.ToVersion), true
		}
		return store.UpdateFailed, fmt.Sprintf("The update helper on the host says %s is installed, but its agent still reports %s, so the new release is not the one running. "+
			"Restart the zoomies agent on the host, and look at journalctl -u zoomies-update there if it does not come back on %s.",
			a.ToVersion, reportedVersion(running), a.ToVersion), true
	}
	if msg := reportedSentence(rep.Error); msg != "" {
		return store.UpdateFailed, msg, true
	}
	return store.UpdateFailed, "The update helper on the host says the update failed, and gave no reason. Look at journalctl -u zoomies-update on the host.", true
}

// channelMovedOn says whether a helper's success took a host to a build from main
// other than the one the controller asked for. A controller built from main asks
// for its own exact build, but the helper can only name the dev channel, and the
// channel moves with every push, so the host can land on a different build from
// the controller's: a later one, or an earlier one when main CI has not yet
// published the controller's. Builds from main cannot be ordered, so which is not
// known. The helper's account and the agent agree on that build, which is what
// tells it from an agent that never restarted, and it is the only case the
// moved-channel sentence is true of.
func channelMovedOn(a store.UpdateAttempt, running string, rep *agent.UpdateReport) bool {
	running = strings.TrimSpace(running)
	return version.IsMainBuild(a.ToVersion) && version.IsMainBuild(running) &&
		running != strings.TrimSpace(a.ToVersion) && strings.TrimSpace(rep.To) == running
}

// reportedSentence is text an agent relayed, made fit to keep. The agent cleans
// it before sending, but the controller does not take an agent's word for what
// is safe to store and show: invalid UTF-8 is replaced, a control or
// direction-changing character becomes a space, and it is cut to the length the
// controller keeps of its own helper's sentence.
func reportedSentence(s string) string {
	s = strings.Map(func(r rune) rune {
		if unicode.IsControl(r) || isBidiControl(r) {
			return ' '
		}
		return r
	}, strings.ToValidUTF8(s, "�"))
	return strings.TrimSpace(cutAt(strings.TrimSpace(s), maxHelperSentence))
}

// reportedVersion is a version an agent reported, cut to a name's length for a
// sentence. It is the agent's word and may be anything.
func reportedVersion(s string) string {
	return cutAt(naming.ForSentence(s), 64)
}

// closeHostAttempt ends a host's open attempt, takes its task back, and brings
// what the loop knows up to date so that the card rendered next says so. It
// says whether this call was the one that closed it, and the store's error
// when the ending could not be written.
func (c *Controller) closeHostAttempt(ctx context.Context, a store.UpdateAttempt, state, text string) (bool, error) {
	closed, err := c.recordUpdateEnding(ctx, a, state, text)
	if !closed {
		return false, err
	}
	c.withdrawHostUpdate(a)
	c.lookAtHostUpdates(ctx)
	return true, nil
}

// keepHostUpdateGoing is what a pass does for a host's attempt that has not
// ended. With updating switched off nothing new is started: a task the agent has
// not yet taken is taken back, and the attempt ends by itself at its time-out.
// One the agent has taken, or still holds, carries on, and its outcome is
// recorded however it ends.
func (c *Controller) keepHostUpdateGoing(h *store.Host, a store.UpdateAttempt) {
	if c.updateMode() == updates.ModeOff {
		c.withdrawUpdateTasks(a.HostID, func(t agent.Task) bool { return t.UpdateID == a.ID }, false)
		return
	}
	c.sendHostUpdate(h, a)
}

// hostAttemptOutcome is how a pass judges a host's open attempt: the host gone,
// the host on the release, or the time-out. A host that has merely gone quiet is
// none of these, because an update restarts the agent and the planner counts
// only the attempt's own time-out as failure.
func (c *Controller) hostAttemptOutcome(a store.UpdateAttempt, h *store.Host) (state, text string, ended bool) {
	if h == nil {
		return store.UpdateCancelled, "The host was removed before the update finished, so nothing will report on it. Enrol the host again to update it.", true
	}
	if state, text, ended := hostReportOutcome(a, h.Version, nil); ended {
		return state, text, true
	}
	if c.Now().Before(c.hostGraceUntil()) {
		return "", "", false
	}
	return c.updateOutcome(a)
}

// lookAtHostUpdates refreshes what the loop knows of each host's latest attempt,
// which the host view and the problems list read without a query each.
//
// A failed read keeps what was last seen, as lookAtUpdates does.
func (c *Controller) lookAtHostUpdates(ctx context.Context) {
	c.updates.hostLookMu.Lock()
	defer c.updates.hostLookMu.Unlock()
	recent, err := c.st.ListUpdateAttempts(ctx, store.UpdateScopeHost, "", hostSightLimit)
	if err != nil {
		if ctx.Err() == nil {
			c.log.Warn("could not read the hosts' update attempts; the next pass will try again", "error", err)
		}
		return
	}
	open, err := c.st.OpenUpdateAttempts(ctx)
	if err != nil {
		if ctx.Err() == nil {
			c.log.Warn("could not read the hosts' open update attempts; the next pass will try again", "error", err)
		}
		return
	}
	latest := make(map[string]store.UpdateAttempt)
	for _, a := range recent {
		if _, seen := latest[a.HostID]; !seen {
			latest[a.HostID] = a
		}
	}
	// An open attempt is the latest of its host by the store's own rule, so this
	// only matters for one older than every attempt read above.
	for _, a := range open {
		if a.Scope == store.UpdateScopeHost {
			latest[a.HostID] = a
		}
	}
	c.updates.hostMu.Lock()
	c.updates.hostLast = latest
	c.updates.hostMu.Unlock()

	// An attempt can end without passing through closeHostAttempt: the host's
	// row deleted with it, or another process closing it. What is remembered of
	// it goes when it is no longer open, whichever way it ended.
	stillOpen := make(map[string]bool, len(open))
	for _, a := range open {
		stillOpen[a.ID] = true
	}
	c.updates.handedMu.Lock()
	for id := range c.updates.handed {
		if !stillOpen[id] {
			delete(c.updates.handed, id)
		}
	}
	c.updates.handedMu.Unlock()
}

// hostAttempt is the latest attempt the loop saw for a host.
func (c *Controller) hostAttempt(hostID string) (store.UpdateAttempt, bool) {
	c.updates.hostMu.RLock()
	defer c.updates.hostMu.RUnlock()
	a, ok := c.updates.hostLast[hostID]
	return a, ok
}

// forgetHostUpdates drops a deleted host from what the loop knows. Its open
// attempt was cancelled with the row, in the same transaction.
func (c *Controller) forgetHostUpdates(hostID string) {
	c.updates.hostMu.Lock()
	delete(c.updates.hostLast, hostID)
	delete(c.updates.hostUnsupported, hostID)
	c.updates.hostMu.Unlock()
	c.updates.heldMu.Lock()
	delete(c.updates.heldWarned, hostID)
	c.updates.heldMu.Unlock()
}

// hostUpdateView renders a host's part in updating from what the loop last saw.
func (c *Controller) hostUpdateView(h *store.Host) *HostUpdateView {
	target := hostTarget()
	can, why, gap := hostCanSelfUpdate(h, target, c.hostHelperUnsupported(h), c.updateMode(), c.rentedHost(h.ID))
	out := &HostUpdateView{State: HostUpdateNone, Reason: why, CanUpdate: can}
	if gap == hostGapHelperImpossible {
		out.State = HostUpdateUnsupported
	}
	a, ok := c.hostAttempt(h.ID)
	if !ok {
		return out
	}
	switch a.State {
	case store.UpdateRequested:
		out.State, out.AttemptID, out.CanUpdate = a.State, a.ID, false
		out.Reason = "The update to " + a.ToVersion + " has been asked for. The host is updated once its agent reports " + a.ToVersion + "."
	case store.UpdateSucceeded:
		out.State, out.AttemptID = a.State, a.ID
	case store.UpdateFailed, store.UpdateTimedOut, store.UpdateCancelled:
		// Once the host has got there some other way, by hand for instance, the
		// failure is history and the card says what is true now. attemptIsHistory
		// says what getting there is.
		if attemptIsHistory(a, h.Version, target) {
			return out
		}
		out.State, out.AttemptID = a.State, a.ID
		out.Reason = withoutDirectionControls(a.Error)
		if strings.TrimSpace(out.Reason) == "" {
			out.Reason = withheldAttemptError(a.State)
		}
		if s := stuckOf(a); stuckIsFault(s) && a.State == store.UpdateFailed {
			out.Code, out.Reason = CodeHostUpdateHelperStuck, stuckSentence(naming.ForSentence(h.Name), s)
		}
	}
	return out
}

package controller

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"sync"
	"sync/atomic"
	"time"
	"unicode/utf8"

	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/updates"
	"github.com/eyupio/zoomies/internal/updates/channel"
	"github.com/eyupio/zoomies/internal/version"
)

// updatesInterval is how often the update loop looks when nothing has woken it.
// It is short because somebody is usually watching: a helper that refuses a
// request, or an upgrade whose pre-flight fails, answers in seconds, and the page
// should say so in seconds. A pass with nothing open is one query.
const updatesInterval = 10 * time.Second

// heldReportGraceMargin is what a host's time-out waits after a fence lifts on
// top of one heartbeat interval: room for the beat's own round trip, and for a
// controller slow to answer it.
const heldReportGraceMargin = 15 * time.Second

// updatesState is the update loop's own memory: the wake-up flag, the lock that
// keeps two passes from overlapping, and whether the next pass should read the
// release list first.
type updatesState struct {
	kick   chan struct{}
	passMu sync.Mutex
	// checkReleases is set when updating is turned on. The scheduled check may be
	// a day away, and until the list is read the status can only say that it has
	// not been, so the next pass reads it.
	checkReleases atomic.Bool

	// lookMu keeps two lookers (a pass and a press of the button) from reading the
	// database in one order and storing in the other, which would leave the older
	// answer as the one the problems list sees.
	lookMu sync.Mutex
	// sightMu guards sight, which the problems pass reads after every scheduling
	// pass and so must never wait on a read of the database or the folder.
	sightMu sync.Mutex
	sight   updateSight

	// hostLast is each host's latest attempt as the loop last saw it, which the
	// host view reads under hostMu for every host in every list and every pass;
	// a query per host there would be a query per host per pass. hostLookMu
	// keeps two lookers from storing in the wrong order, as lookMu does.
	hostLookMu sync.Mutex
	hostMu     sync.RWMutex
	hostLast   map[string]store.UpdateAttempt
	// handed is the attempts whose request an agent has said it wrote, so that
	// the pass stops queueing their task. It is memory only: after a restart the
	// task is sent once more. The process that wrote the request, and an agent
	// already on the release, answer it without writing a second one; an agent
	// restarted for another reason in between finds its request still waiting and
	// says so, which closes the attempt as failed with that sentence.
	handedMu sync.Mutex
	handed   map[string]bool
	// hostUnsupported is why each host's agent last said the helper cannot be
	// installed on its host, under hostMu. Memory only, like handed: every beat
	// says it again.
	hostUnsupported map[string]updates.HelperUnsupported
	// heldWarned is when each host's held update result was last logged, so a
	// fenced controller says so once in a while rather than on every beat.
	heldMu     sync.Mutex
	heldWarned map[string]time.Time

	// fenceSeen says a pass, or a beat whose report was held, found this
	// controller unable to act since the last pass that could.
	fenceSeen atomic.Bool
	// hostGraceUntil is when hosts' attempts may be timed out again after the
	// fence last lifted, or nil. See heldReportGrace.
	hostGraceUntil atomic.Pointer[time.Time]
}

// updateSight is what the update loop last saw of the things the problems list
// reports on. The list is worked out after every scheduling pass, and a probe of
// the update folder and a query for the last attempt do not belong in that path;
// the loop looks every ten seconds and whenever an attempt opens, so this is at
// most that stale.
type updateSight struct {
	// looked says the loop has looked at all. Before it has, nothing is known and
	// nothing is raised: a controller that has only just started has not seen a
	// helper missing.
	looked bool
	// helper is the helper's state: ready, missing or unsupported.
	helper string
	// last is the controller's latest update attempt, open or ended, or nil.
	last *store.UpdateAttempt
}

func newUpdatesState() updatesState {
	return updatesState{kick: make(chan struct{}, 1)}
}

// KickUpdates asks for a pass of the update loop now. It never blocks and never
// queues, like Nudge.
func (c *Controller) KickUpdates() {
	select {
	case c.updates.kick <- struct{}{}:
	default:
	}
}

// updatesLoop watches the attempts in flight, on a timer and whenever something
// asks. It runs whatever updates.mode says: switching updating off stops new
// requests, and an attempt already in flight still has to be closed.
//
// It is a loop of its own, apart from the scheduling pass, because nothing here
// may wait on reconcileMu: a pass holds it for as long as GitHub takes to answer.
func (c *Controller) updatesLoop(ctx context.Context) {
	ticker := time.NewTicker(updatesInterval)
	defer ticker.Stop()
	// At once, because a controller that has just started may be the new build an
	// update asked for, and the page that asked is waiting to hear.
	c.runUpdates(ctx)
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		case <-c.updates.kick:
		}
		c.runUpdates(ctx)
	}
}

func (c *Controller) runUpdates(ctx context.Context) {
	if err := c.ReconcileUpdates(ctx); err != nil && ctx.Err() == nil {
		c.log.Error("the update attempts could not be checked; the next pass will try again", "error", err)
	}
}

// ReconcileUpdates runs one pass: read the release list if updating has just
// been turned on, then close every open attempt that has ended. It is exported so
// that tests can force a pass and know it has finished.
//
// Every attempt is judged on what can be seen now, so a pass missed, run twice,
// or run by the next process after a restart comes to the same answer, and the
// store keeps the first ending if two passes race.
func (c *Controller) ReconcileUpdates(ctx context.Context) error {
	c.updates.passMu.Lock()
	defer c.updates.passMu.Unlock()
	// Last, so that the problems list and the host cards see the attempts this
	// pass closed. A controller that may not act still looks: what it reports is
	// what is there.
	defer c.lookAtUpdates(ctx)
	defer c.lookAtHostUpdates(ctx)

	// Reading the list changes nothing in the fleet, so a controller that may not
	// act still does it: the status it shows should not be a day stale.
	if c.updates.checkReleases.Swap(false) && c.updateMode() != updates.ModeOff {
		asked, err := c.askForReleases(ctx)
		switch {
		case err != nil:
			if !errors.Is(err, ErrUpdateCheckDisabled) {
				c.log.Info("could not read the release list after updating was turned on; the scheduled check will try again", "error", err)
			}
		case !asked:
			// A press of the button took the minute, perhaps for the latest release
			// alone while updating was still off. The list is still unread, so the
			// flag stays, and a pass after the minute asks.
			c.updates.checkReleases.Store(true)
		default:
			if _, err := c.publishUpdates(ctx); err != nil {
				c.log.Warn("could not work out the update status for the event stream", "error", err)
			}
		}
	}

	if !c.mayAct() {
		c.updates.fenceSeen.Store(true)
		return nil
	}
	if c.updates.fenceSeen.Swap(false) {
		until := c.Now().Add(c.heldReportGrace())
		c.updates.hostGraceUntil.Store(&until)
	}
	open, err := c.st.OpenUpdateAttempts(ctx)
	if err != nil {
		return fmt.Errorf("listing the update attempts in flight: %w", err)
	}
	closed := false
	var hosts map[string]*store.Host
	var hostsUnread bool
	var closedHosts []*store.Host
	for _, a := range open {
		if a.Scope == store.UpdateScopeHost {
			// Read once a pass, and only when a host has something in flight.
			if hosts == nil && !hostsUnread {
				list, err := c.st.ListHosts(ctx)
				if err != nil {
					// The hosts' attempts wait for the next pass; the controller's own
					// does not depend on the list, and is still judged.
					c.log.Warn("could not list the hosts with an update in flight; the next pass will try again", "error", err)
					hostsUnread = true
					continue
				}
				hosts = make(map[string]*store.Host, len(list))
				for _, h := range list {
					hosts[h.ID] = h
				}
			}
			if hostsUnread {
				continue
			}
			h := hosts[a.HostID]
			state, text, ended := c.hostAttemptOutcome(a, h)
			if !ended {
				c.keepHostUpdateGoing(h, a)
				continue
			}
			if c.endAttempt(ctx, a, state, text) {
				closed = true
				if h != nil {
					closedHosts = append(closedHosts, h)
				}
			}
			continue
		}
		state, text, ended := c.updateOutcome(a)
		if !ended {
			continue
		}
		if c.endAttempt(ctx, a, state, text) {
			closed = true
		}
	}
	// An update's own process can start before the helper writes its answer, so
	// an attempt closed on the running version alone can miss the copy the engine
	// took and whether it rolled back. The answer is read again here until it
	// lands, so the page's copy arrives even when the attempt closed first.
	c.recordLateHelperFacts(ctx)
	for _, h := range closedHosts {
		c.publishHost(h)
	}
	// After the closing, so that the planner decides on what is true now: the
	// attempt that just ended is the one it would otherwise wait on.
	if c.runUpdatePlan(ctx) {
		c.publishDerived(ctx)
		closed = true
	}
	if closed {
		if _, err := c.publishUpdates(ctx); err != nil {
			c.log.Warn("could not work out the update status for the event stream", "error", err)
		}
	}
	return nil
}

// endAttempt is the one closer of an attempt, for the pass and for the
// planner's time-out alike, so the two can never record an ending two ways. It
// is idempotent: the store keeps the first ending, and only the call that made
// it takes back the request or the task.
func (c *Controller) endAttempt(ctx context.Context, a store.UpdateAttempt, state, text string) bool {
	if a.Scope == store.UpdateScopeHost {
		closed, _ := c.closeHostAttempt(ctx, a, state, text)
		return closed
	}
	if !c.finishUpdateAttempt(ctx, a, state, text) {
		return false
	}
	// What the helper reported about the engine's run, for the page: the copy it
	// took before it changed anything, and whether it rolled back. A result that
	// is not there leaves both empty, which is what an attempt that timed out or
	// was answered before this release happened to carry.
	if res, ok := c.resultFor(a); ok {
		if err := c.st.SetUpdateAttemptFacts(ctx, a.ID, res.Backup, res.RolledBack); err != nil {
			c.log.Warn("could not record what the update helper reported", "attempt", a.ID, "error", err)
		}
	}
	c.withdrawRequest(a)
	return true
}

// heldReportGrace is how long, after a fence lifts, a host's attempt is not
// timed out. A fenced controller times nothing out, so an attempt can pass its
// 90 minutes under the fence; the agent sends a report the fence held again on
// its next beat, but the first pass after the lift comes within ten seconds and
// would close the attempt as timed out first, losing the helper's sentence. One
// heartbeat interval (the configured one, because an operator can lengthen it)
// and a margin are long enough for that beat to arrive. The controller's own
// attempt is answered through the folder the pass reads, and needs none.
func (c *Controller) heldReportGrace() time.Duration {
	return c.heartbeatInterval() + heldReportGraceMargin
}

// hostGraceUntil is when hosts' attempts may be timed out again, or the zero
// time when no fence has lifted.
func (c *Controller) hostGraceUntil() time.Time {
	if until := c.updates.hostGraceUntil.Load(); until != nil {
		return *until
	}
	return time.Time{}
}

// lookAtUpdates refreshes what the problems list reports on: whether the helper
// is installed, and how the controller's latest attempt stands.
//
// A failed read of the attempts keeps the last one seen. Clearing it would drop
// an error the operator has not yet read because the database was busy.
func (c *Controller) lookAtUpdates(ctx context.Context) {
	c.updates.lookMu.Lock()
	defer c.updates.lookMu.Unlock()

	helper := c.probeUpdateHelper().view.State
	attempts, err := c.st.ListUpdateAttempts(ctx, store.UpdateScopeController, "", 1)
	if err != nil && ctx.Err() == nil {
		c.log.Warn("could not read the controller's latest update attempt for the problems list; the next pass will try again", "error", err)
	}

	c.updates.sightMu.Lock()
	defer c.updates.sightMu.Unlock()
	c.updates.sight.looked = true
	c.updates.sight.helper = helper
	if err != nil {
		return
	}
	c.updates.sight.last = nil
	if len(attempts) > 0 {
		last := attempts[0]
		c.updates.sight.last = &last
	}
}

// updateSightNow is a copy of what the loop last saw.
func (c *Controller) updateSightNow() updateSight {
	c.updates.sightMu.Lock()
	defer c.updates.sightMu.Unlock()
	return c.updates.sight
}

// updateOutcome says whether an open attempt has ended, and how.
//
// The time-out is the last word and is checked after everything else, so an
// answer that arrived in the same pass as the ninetieth minute is the one kept.
// It needs no mode: an attempt asked for before updating was switched off is
// still in flight, and still has to be recorded however it ends.
func (c *Controller) updateOutcome(a store.UpdateAttempt) (state, text string, ended bool) {
	if a.Scope == store.UpdateScopeController {
		if state, text, ended := c.controllerOutcome(a); ended {
			return state, text, true
		}
	}
	if c.Now().Sub(a.RequestedAt) <= updateAttemptTimeout {
		return "", "", false
	}
	return store.UpdateTimedOut, timedOutText(a), true
}

// timedOutText is what an attempt that timed out records, whichever closer saw
// the ninetieth minute first.
func timedOutText(a store.UpdateAttempt) string {
	if a.Scope == store.UpdateScopeController {
		return fmt.Sprintf("No answer came from the update helper within 90 minutes, and this controller still runs %s. "+
			"Look at journalctl -u zoomies-update and zoomies updates helper status on the controller's host.", version.Version)
	}
	return fmt.Sprintf("The host did not come back on %s within 90 minutes. "+
		"Look at journalctl -u zoomies-update and zoomies updates helper status on the host.", a.ToVersion)
}

// controllerOutcome is how the controller's own attempt ended, if it has.
//
// Success is this process running the tag or something later. The helper's word
// alone is not enough, since a result can say done while the old build is still
// the one running; and its word is not needed either, because the new process
// may start before the result is written, and is itself the proof. For the same
// reason a failure the helper reported is not believed over a process that
// already runs the target: whatever it complained of, the update took, and
// "still runs the old build" would be untrue of it.
func (c *Controller) controllerOutcome(a store.UpdateAttempt) (state, text string, ended bool) {
	arrived := runsAtLeast(version.Version, a.ToVersion)
	res, answered := c.resultFor(a)
	if a.ToVersion == updates.DevTag {
		// A moving channel is proved by the running build, not the channel name.
		arrived = version.IsMainBuild(version.Version) && version.Version != a.FromVersion
		if answered && res.OK {
			arrived = version.IsMainBuild(version.Version) && version.Version == res.To
		}
	}
	switch {
	case arrived:
		if answered && !res.OK {
			c.log.Warn("the update helper reported a failure, but this controller runs the release it was asked for, so the attempt is recorded as succeeded",
				"attempt", a.ID, "to", a.ToVersion, "running", version.Version, "helper", cutAt(res.Error, maxHelperSentence))
		}
		return store.UpdateSucceeded, "", true
	case !answered:
		return "", "", false
	case res.OK:
		return store.UpdateFailed, fmt.Sprintf("The update helper says %s is installed, but this controller still runs %s, so the new release is not the one running. "+
			"Restart zoomies on the controller's host, and look at journalctl -u zoomies-update there if it does not come back on %s.",
			a.ToVersion, version.Version, a.ToVersion), true
	}
	if msg := strings.TrimSpace(cutAt(res.Error, maxHelperSentence)); msg != "" {
		return store.UpdateFailed, msg, true
	}
	return store.UpdateFailed, "The update helper says the update failed, and gave no reason. Look at journalctl -u zoomies-update on the controller's host.", true
}

// runsAtLeast says whether running is the release tag names or a later one.
// Release binaries report 1.3.5 where the tag is v1.3.5, so only CompareBuilds
// can say whether the two are the same release.
func runsAtLeast(running, tag string) bool {
	if strings.TrimSpace(running) == "" || strings.TrimSpace(tag) == "" {
		return false
	}
	switch version.CompareBuilds(running, tag) {
	case version.SkewNone, version.SkewAhead:
		return true
	}
	return false
}

// recordLateHelperFacts records what the helper reported about the controller's
// latest attempt when its answer arrived after the attempt had already closed.
// A successful upgrade starts the new controller before the helper writes
// result.json, so the attempt is closed on the running version and would never
// see the copy the engine took. It is skipped when the attempt already carries
// what the answer says, so a pass that finds nothing new writes nothing.
func (c *Controller) recordLateHelperFacts(ctx context.Context) {
	latest, err := c.st.ListUpdateAttempts(ctx, store.UpdateScopeController, "", 1)
	if err != nil || len(latest) == 0 {
		return
	}
	a := latest[0]
	res, ok := c.resultFor(a)
	if !ok || (res.Backup == a.Backup && res.RolledBack == a.RolledBack) {
		return
	}
	if err := c.st.SetUpdateAttemptFacts(ctx, a.ID, res.Backup, res.RolledBack); err != nil {
		c.log.Warn("could not record what the update helper reported", "attempt", a.ID, "error", err)
	}
}

// resultFor is the helper's answer to attempt a, if the folder holds one.
//
// Anything else in result.json is ignored, quietly: a result left from before a
// restart, an answer to an attempt already closed, a file that is not a result.
// The service can write the folder, so nothing in it is evidence of anything but
// what the helper is showing; it only ever closes the attempt it answers.
//
// One answer carries no id. The helper refuses a request it cannot trust (one it
// cannot parse, or one owned by another account) without echoing an id it has
// no reason to believe. Only one attempt is open at a time and only this service
// writes requests, so a refusal without an id written after this attempt was
// asked for can only be the answer to it; ignored, it would leave the attempt to
// time out after 90 minutes with no reason given.
func (c *Controller) resultFor(a store.UpdateAttempt) (updates.Result, bool) {
	dir, ok := c.updateDir()
	if !ok {
		return updates.Result{}, false
	}
	res, found, err := channel.ReadResult(dir)
	if err != nil {
		c.log.Debug("ignoring a result in the update folder that cannot be read", "error", err)
		return updates.Result{}, false
	}
	switch {
	case !found:
		return updates.Result{}, false
	case res.ID == a.ID:
		return res, true
	case res.ID == "" && !res.OK && res.FinishedAt.After(a.RequestedAt):
		return res, true
	}
	return updates.Result{}, false
}

// maxHelperSentence bounds what of the helper's error an attempt keeps. The
// result file may carry far more, and the row is read on every status; a
// sentence an operator reads is a few hundred bytes, and the log tail is where
// the rest is.
const maxHelperSentence = 2048

// cutAt is s cut to at most limit bytes, at a character boundary.
func cutAt(s string, limit int) string {
	if len(s) <= limit {
		return s
	}
	end := limit
	for end > 0 && !utf8.RuneStart(s[end]) {
		end--
	}
	return s[:end]
}

// withdrawRequest takes back the controller's own request once its attempt has
// ended without the helper taking it, so that the next press is not refused by
// a request nobody will read. Anything there that is not provably this
// attempt's request is left for a person.
func (c *Controller) withdrawRequest(a store.UpdateAttempt) {
	dir, ok := c.updateDir()
	if !ok {
		return
	}
	switch got, err := channel.WithdrawRequest(dir, a.ID); {
	case err != nil:
		c.log.Warn("could not take back the request of an update attempt that has ended; remove request.json from the update folder by hand",
			"attempt", a.ID, "error", err)
	case got == channel.RequestWithdrawn:
		c.log.Info("took back the request of an update attempt that has ended, which the update helper never read", "attempt", a.ID)
	case got == channel.RequestNotOurs:
		c.log.Warn("the update folder holds a request.json that is not this attempt's, so it was left alone; the next update is refused until it is gone",
			"attempt", a.ID)
	}
}

// finishUpdateAttempt closes an open attempt and counts it, and says whether it
// was this call that closed it: the store keeps the first ending, so a pass and
// a button racing count one.
func (c *Controller) finishUpdateAttempt(ctx context.Context, a store.UpdateAttempt, state, text string) bool {
	closed, _ := c.recordUpdateEnding(ctx, a, state, text)
	return closed
}

// finishAttemptInStore is the store's FinishUpdateAttempt. It is a variable so
// that a test can make the write fail once.
var finishAttemptInStore = (*store.Store).FinishUpdateAttempt

// recordUpdateEnding is finishUpdateAttempt for a caller that must tell an
// attempt that was already closed from a write that failed: a host's report is
// sent again only when the store could not take it.
func (c *Controller) recordUpdateEnding(ctx context.Context, a store.UpdateAttempt, state, text string) (bool, error) {
	closed, err := finishAttemptInStore(c.st, ctx, a.ID, state, text)
	if err != nil {
		c.log.Warn("could not record how an update attempt ended; the next pass will try again", "attempt", a.ID, "error", err)
		return false, err
	}
	if !closed {
		return false, nil
	}
	// The planner moves on from an ended attempt, and should not wait ten
	// seconds to.
	c.KickUpdates()
	c.metrics.updateAttempts.WithLabelValues(a.Scope, state).Inc()
	if state == store.UpdateSucceeded {
		c.log.Info("an update attempt succeeded", "attempt", a.ID, "scope", a.Scope, "host", a.HostID, "to", a.ToVersion)
	} else {
		c.log.Warn("an update attempt did not succeed", "attempt", a.ID, "scope", a.Scope, "host", a.HostID,
			"to", a.ToVersion, "state", state, "reason", text)
	}
	return true, nil
}

// renderUpdates is UpdatesView. It is a variable so that a test can make the
// status fail to render after a request has been written.
var renderUpdates = (*Controller).UpdatesView

// publishUpdates sends the update status now, if it differs from what was last
// sent, and returns it. A request and a closed attempt write rows, and the page
// that asked should not wait for the next pass to hear of them.
//
// The status is worked out with derivedMu held, as publishDerived works out its
// own: two publishers that each rendered first and then waited for the lock
// could send an older status after a newer one, and the page keeps whichever
// frame came last.
func (c *Controller) publishUpdates(ctx context.Context) (*UpdatesView, error) {
	c.derivedMu.Lock()
	defer c.derivedMu.Unlock()
	view, err := renderUpdates(c, ctx)
	if err != nil {
		return nil, err
	}
	c.sendUpdates(view)
	return view, nil
}

// sendUpdates publishes a status that differs from the one last sent. Called
// with derivedMu held, and with a status rendered under it.
func (c *Controller) sendUpdates(view *UpdatesView) {
	if c.bus == nil {
		return
	}
	if raw, changed := c.derivedChanged(&c.lastUpdates, view); changed {
		c.bus.Publish(events.KindUpdates, "", json.RawMessage(raw))
	}
}

package controller

import (
	"context"
	"encoding/json"
	"fmt"
	"slices"
	"strings"
	"time"
	"unicode"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/naming"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/updates"
)

// CodeHostUpdateHelperStuck is the problem for an update that could not be handed
// to a host because the helper there had stopped reading requests. It is the same
// code on the host's card, where it labels the failed attempt, and in the list.
const CodeHostUpdateHelperStuck = "host.update_helper_stuck"

// The audit action written when an agent has asked for the helper on its host to
// be repaired, or root has repaired it. One action for both, because the person
// reading the audit wants to know that the helper was touched and what became of it.
const auditUpdateHelperRepair = "update.helper_repair"

var knownRepairActions = []string{
	updates.ActionResetFailed, updates.ActionRewroteUnits, updates.ActionStartedPath,
	updates.ActionRemovedRequest, updates.ActionRemovedLock, updates.ActionRefusedBusy, updates.ActionRefusedRateLimit,
}

// cleanStuck is what an agent said about a stalled helper, made fit to keep and
// to show every role: the kind, the note and the actions are checked against the
// fixed words, the unit states are cut to a name's length, and the numbers are
// bounded. An agent is trusted to be honest about its host and no further.
func cleanStuck(s *agent.UpdateStuck, attempts int) *agent.UpdateStuck {
	if s == nil {
		return nil
	}
	out := agent.UpdateStuck{
		Kind: s.Kind, Path: unitWord(s.Path), Service: unitWord(s.Service),
		LockPresent: s.LockPresent, Healed: s.Healed, Asked: s.Asked, Attempts: min(max(s.Attempts, 0), 99),
	}
	if !slices.Contains([]string{updates.StuckPathDown, updates.StuckStaleRequest, updates.StuckBusy}, out.Kind) {
		return nil
	}
	if slices.Contains([]string{"busy", "held_back", "no_answer", "refused"}, s.Note) {
		out.Note = s.Note
	}
	out.RequestAgeSeconds = min(max(s.RequestAgeSeconds, 0), int64(10*365*24*time.Hour/time.Second))
	for _, a := range s.Repaired {
		if slices.Contains(knownRepairActions, a) && len(out.Repaired) < len(knownRepairActions) {
			out.Repaired = append(out.Repaired, a)
		}
	}
	return &out
}

// unitWord is a unit's state as an agent reported it: systemd's own words, so it
// is short and plain. Anything a terminal or a page would act on is dropped and
// the rest is cut to a name's length.
func unitWord(s string) string {
	s = strings.Map(func(r rune) rune {
		if unicode.IsControl(r) || isBidiControl(r) {
			return -1
		}
		return r
	}, strings.ToValidUTF8(s, ""))
	return strings.TrimSpace(cutAt(strings.TrimSpace(s), 64))
}

// stuckOf reads the record on an attempt. Absent, or unreadable, is none.
func stuckOf(a store.UpdateAttempt) *agent.UpdateStuck {
	if a.Stuck == "" {
		return nil
	}
	var s agent.UpdateStuck
	if json.Unmarshal([]byte(a.Stuck), &s) != nil {
		return nil
	}
	return cleanStuck(&s, 0)
}

// stuckIsFault says the record is a helper that was stopped and stayed so, not
// one that was merely busy or that was repaired and then took the request: only
// a helper still stopped is a problem of its own.
func stuckIsFault(s *agent.UpdateStuck) bool {
	return s != nil && !s.Healed && s.Kind != updates.StuckBusy && s.Note != "busy"
}

// ageWords says how long a request had waited, roughly, because a person reading
// "3 days" knows what it means and "259214s" is for the log.
func ageWords(seconds int64) string {
	d := time.Duration(seconds) * time.Second
	switch {
	case d >= 48*time.Hour:
		return fmt.Sprintf("%d days", int(d.Hours()/24))
	case d >= 2*time.Hour:
		return fmt.Sprintf("%d hours", int(d.Hours()))
	case d >= 2*time.Minute:
		return fmt.Sprintf("%d minutes", int(d.Minutes()))
	}
	return "less than two minutes"
}

// repairWords is what root did, in a clause, in the order it did it.
func repairWords(actions []string) string {
	say := map[string]string{
		updates.ActionResetFailed:      "cleared the units' failed state",
		updates.ActionRewroteUnits:     "rewrote the helper's units",
		updates.ActionStartedPath:      "started the path unit",
		updates.ActionRemovedRequest:   "removed an abandoned request",
		updates.ActionRemovedLock:      "removed an abandoned upgrade lock",
		updates.ActionRefusedBusy:      "declined because an update was running",
		updates.ActionRefusedRateLimit: "declined because it had repaired this helper too recently",
	}
	var parts []string
	for _, a := range actions {
		if w, ok := say[a]; ok {
			parts = append(parts, w)
		}
	}
	return strings.Join(parts, ", ")
}

// stuckFacts is the sentence of what was found, with no path and nothing the
// host chose: fixed words, systemd's own words for the units, and numbers. It is
// safe to show to every role.
func stuckFacts(s *agent.UpdateStuck) string {
	var parts []string
	if s.Path != "" {
		parts = append(parts, "its path unit is "+s.Path)
	}
	if s.Service != "" && s.Service != "inactive, static" {
		parts = append(parts, "its service unit is "+s.Service)
	}
	if s.RequestAgeSeconds > 0 {
		parts = append(parts, "a request had been waiting for "+ageWords(s.RequestAgeSeconds))
	}
	if s.LockPresent {
		parts = append(parts, "upgrade.lock was present")
	}
	return strings.Join(parts, "; ")
}

// stuckSentence is what the controller says of an attempt the stalled helper
// stopped, on the host's card and in the failed row. The agent's own error text
// is not used: this is built from the checked record.
func stuckSentence(host string, s *agent.UpdateStuck) string {
	subject := "The update helper on " + host
	facts := stuckFacts(s)
	if facts != "" {
		facts = " (" + facts + ")"
	}
	repaired := repairWords(s.Repaired)
	if repaired != "" {
		repaired = " Root " + repaired + "."
	}
	const install = " Somebody with root on the host can run sudo zoomies updates helper install, which resets and restarts it, and then update again."
	switch {
	case s.Kind == updates.StuckBusy || s.Note == "busy":
		return subject + " is running another update, so this request was not written and nothing was changed. Update again once that one has finished."
	case s.Note == "held_back":
		return subject + " has stopped" + facts + ", and was repaired too recently or too often to try again yet." + repaired + install
	case s.Note == "no_answer":
		return subject + " has stopped" + facts + ", and the request to repair it was not answered, which happens when the repair units are not installed on that host." + install
	case s.Note == "refused":
		return subject + " has stopped" + facts + ", and the repair did not put it right." + repaired + install
	}
	return subject + " had stopped" + facts + "." + repaired
}

// stuckProblem is the problem for a host whose latest attempt the stalled helper
// stopped. It carries what an operator needs to act without opening the host: the
// attempt, how long the request had waited, and the state of the units. Like
// every host update problem it has no Remedy: the autopilot applies every remedy
// it finds, and nothing here is one it applies.
func stuckProblem(h *store.Host, a store.UpdateAttempt, s *agent.UpdateStuck) Problem {
	label := naming.ForSentence(h.Name)
	return Problem{
		Code:     "host.update_helper_stuck",
		Severity: config.SeverityError,
		Title:    fmt.Sprintf("the update helper on host %s has stopped, so its update to %s could not be handed over", label, a.ToVersion),
		Detail: fmt.Sprintf("attempt %s: %s. The host's agent still runs %s and places work as normal.%s",
			a.ID, stuckFacts(s), reportedVersion(h.Version), problemRepairClause(s)),
		Fix: fmt.Sprintf("have somebody with root on %s run `%s`, which clears the units' failed state, rewrites them and starts the path unit again, "+
			"then `sudo zoomies updates helper status` to see that it is waiting. Update it again from the Hosts page once it is.", label, helperInstallCommand),
		TargetKind: "host", TargetID: h.ID,
	}
}

func problemRepairClause(s *agent.UpdateStuck) string {
	switch {
	case s.Note == "no_answer":
		return " The request to repair it was not answered, so the repair units are probably not installed on that host."
	case s.Note == "held_back":
		return " It was repaired too recently or too often for the agent to ask again."
	case len(s.Repaired) > 0:
		return " Root tried: it " + repairWords(s.Repaired) + "."
	}
	return ""
}

// noteHelperStuck records what an update task found wrong with the helper and,
// when the agent asked for or saw a repair, says so where an operator reads: the
// log, the audit and the host's card. It reports whether the attempt's record was
// written.
func (c *Controller) noteHelperStuck(ctx context.Context, hostID, attemptID string, raw *agent.UpdateStuck) *agent.UpdateStuck {
	s := cleanStuck(raw, 0)
	if s == nil {
		return nil
	}
	if body, err := json.Marshal(s); err == nil {
		if err := c.st.SetUpdateAttemptStuck(ctx, attemptID, string(body)); err != nil {
			c.log.Warn("could not record what was found wrong with a host's update helper", "host", hostID, "attempt", attemptID, "error", err)
		}
	}
	if s.Asked || len(s.Repaired) > 0 {
		c.log.Warn("a host's update helper had stopped and a repair was asked for",
			"host", hostID, "attempt", attemptID, "kind", s.Kind, "request_age_seconds", s.RequestAgeSeconds,
			"path_unit", s.Path, "service_unit", s.Service, "repaired", s.Repaired, "healed", s.Healed, "note", s.Note)
		c.systemAudit(ctx, auditUpdateHelperRepair, "host", hostID, nil, map[string]any{
			"attempt_id": attemptID, "kind": s.Kind, "request_age_seconds": s.RequestAgeSeconds,
			"path_unit": s.Path, "service_unit": s.Service, "repaired": s.Repaired, "healed": s.Healed, "note": s.Note,
		})
	}
	return s
}

package controller

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/updates"
)

// stalledHelper is what an agent reports when the host's update helper was dead:
// the path unit disabled, a request three days old, and root unable to help.
func stalledHelper() *agent.UpdateStuck {
	return &agent.UpdateStuck{
		Kind: updates.StuckPathDown, RequestAgeSeconds: int64(72 * time.Hour / time.Second),
		Path: "inactive, disabled, failed", Service: "inactive", Asked: true, Attempts: 1,
		Note: "no_answer",
	}
}

// reportStuck is the agent answering the update task with a failure that carries
// what it found. The text is the agent's own, and names a path on the host.
func (h *harness) reportStuck(host *store.Host, stuck *agent.UpdateStuck, agentSaid string) store.UpdateAttempt {
	h.t.Helper()
	a := h.requestHost(host)
	task := h.poll(host)[0]
	if err := h.c.ReportResult(h.ctx, host.ID, agent.TaskResult{
		TaskID: task.ID, Kind: agent.TaskUpdateAgent, OK: false, Error: agentSaid, Stuck: stuck, CompletedAt: h.c.Now(),
	}); err != nil {
		h.t.Fatalf("ReportResult: %v", err)
	}
	return h.attempt(a.ID)
}

// The report: every attempt failed for days and the controller showed no reason.
// Now the attempt fails with a sentence that says the helper had stopped and how,
// and the host has a problem of its own to point at.
func TestAStalledHelperIsAProblemOfItsOwnThatNamesTheAttemptAgeAndUnits(t *testing.T) {
	h := newHarness(t)
	h.hostsCanUpdate()
	host := h.updatableHost("vm-1")
	agentSaid := "an earlier update request is still waiting in /var/lib/zoomies/update"

	a := h.reportStuck(host, stalledHelper(), agentSaid)

	if a.State != store.UpdateFailed {
		t.Fatalf("attempt = %s, want failed", a.State)
	}
	for _, want := range []string{"vm-1", "has stopped", "inactive, disabled, failed", "3 days", "repair units"} {
		if !strings.Contains(a.Error, want) {
			t.Errorf("the attempt's reason %q does not say %q", a.Error, want)
		}
	}
	if strings.Contains(a.Error, "/var/lib") {
		t.Errorf("the attempt's reason %q carries the agent's text, which names a path on the host", a.Error)
	}

	p, ok := h.problemsByCode()[CodeHostUpdateHelperStuck]
	if !ok {
		t.Fatalf("no %s problem; have %v", CodeHostUpdateHelperStuck, h.problemCodes())
	}
	if p.Severity != config.SeverityError || p.TargetKind != "host" || p.TargetID != host.ID || p.Remedy != nil {
		t.Errorf("problem = %+v, want an error about the host with no remedy", p)
	}
	for _, want := range []string{a.ID, "3 days", "inactive, disabled, failed"} {
		if !strings.Contains(p.Detail, want) {
			t.Errorf("the problem's detail %q does not carry %q", p.Detail, want)
		}
	}
	if !strings.Contains(p.Fix, "sudo zoomies updates helper install") {
		t.Errorf("the problem's fix %q does not say how to put the helper right", p.Fix)
	}
	if contains(h.problemCodes(), "host.update_failed") {
		t.Error("the same failure is also raised as a bare host.update_failed")
	}
}

// The card is where the reason is read. It is built from fixed words and numbers,
// so every role reads it, and it is labelled with the code so the UI can say what
// kind of failure it is.
func TestTheHostCardShowsTheHelperStoppedToEveryRole(t *testing.T) {
	h := newHarness(t)
	h.hostsCanUpdate()
	host := h.updatableHost("vm-1")
	h.reportStuck(host, stalledHelper(), "the agent's own text")

	view := h.view(host.ID)
	if view.Update.State != store.UpdateFailed || view.Update.Code != CodeHostUpdateHelperStuck {
		t.Fatalf("update = %+v, want a failure labelled %s", view.Update, CodeHostUpdateHelperStuck)
	}
	for _, platform := range []bool{true, false} {
		got := view.For(platform).Update
		if !strings.Contains(got.Reason, "has stopped") || !strings.Contains(got.Reason, "3 days") {
			t.Errorf("platform=%v: the card says %q, want the helper's stop and how long the request waited", platform, got.Reason)
		}
	}
	// Any other failure still reads the fixed sentence below the platform role.
	other := h.updatableHost("vm-2")
	b := h.requestHost(other)
	h.agentBeat(other, "1.3.4", &agent.UpdateReport{ID: b.ID, OK: false, Error: "failed at /var/lib/zoomies", FinishedAt: h.c.Now().UTC()})
	if got := h.view(other.ID).For(false).Update; got.Code != "" || strings.Contains(got.Reason, "/var/lib") {
		t.Errorf("a plain failure reads %+v below the platform role, want a fixed sentence and no code", got)
	}
}

// The record is on the attempt, so the problem is what the next controller
// process sees too, not something held in memory.
func TestAStalledHelperProblemSurvivesTheLoopBeingRebuilt(t *testing.T) {
	h := newHarness(t)
	h.hostsCanUpdate()
	host := h.updatableHost("vm-1")
	a := h.reportStuck(host, stalledHelper(), "")
	if a.Stuck == "" {
		t.Fatal("the attempt kept no record of what was found")
	}

	h.c.updates.hostMu.Lock()
	h.c.updates.hostLast = nil
	h.c.updates.hostMu.Unlock()
	h.c.lookAtHostUpdates(h.ctx)

	if _, ok := h.problemsByCode()[CodeHostUpdateHelperStuck]; !ok {
		t.Errorf("after a fresh look the problems are %v, want %s", h.problemCodes(), CodeHostUpdateHelperStuck)
	}
}

// A helper that is mid-upgrade is not a fault. The attempt says it was not
// written and why, and nothing is raised that would send somebody to repair a
// helper that is working.
func TestABusyHelperFailsTheAttemptButIsNotAStalledHelper(t *testing.T) {
	h := newHarness(t)
	h.hostsCanUpdate()
	host := h.updatableHost("vm-1")
	busy := &agent.UpdateStuck{Kind: updates.StuckBusy, Note: "busy", RequestAgeSeconds: 600, Path: "active, enabled", Service: "active"}

	a := h.reportStuck(host, busy, "")

	if !strings.Contains(a.Error, "running another update") || !strings.Contains(a.Error, "nothing was changed") {
		t.Errorf("the attempt's reason is %q, want it to say the helper was busy and nothing was touched", a.Error)
	}
	if codes := h.problemCodes(); contains(codes, CodeHostUpdateHelperStuck) {
		t.Errorf("a busy helper was raised as stalled: %v", codes)
	}
}

// A repair that worked leaves no problem, but it is on the record: in the log,
// and in the audit under its own action, naming the attempt and what was done.
func TestARepairThatWorkedIsAuditedAndLeavesTheAttemptOpen(t *testing.T) {
	h := newHarness(t)
	h.hostsCanUpdate()
	host := h.updatableHost("vm-1")
	a := h.requestHost(host)
	task := h.poll(host)[0]

	healed := &agent.UpdateStuck{
		Kind: updates.StuckPathDown, RequestAgeSeconds: 259200, Path: "inactive, disabled, failed", Asked: true, Healed: true, Attempts: 1,
		Repaired: []string{updates.ActionResetFailed, updates.ActionRewroteUnits, updates.ActionStartedPath, updates.ActionRemovedRequest},
	}
	if err := h.c.ReportResult(h.ctx, host.ID, agent.TaskResult{TaskID: task.ID, Kind: agent.TaskUpdateAgent, OK: true, Stuck: healed, CompletedAt: h.c.Now()}); err != nil {
		t.Fatal(err)
	}

	if got := h.attempt(a.ID); got.State != store.UpdateRequested {
		t.Fatalf("attempt = %s after a repaired helper took the request, want it still requested", got.State)
	}
	if contains(h.problemCodes(), CodeHostUpdateHelperStuck) {
		t.Error("a helper that was repaired is raised as stalled")
	}
	rows, total, err := h.st.ListAudit(h.ctx, store.AuditFilter{Actions: []string{auditUpdateHelperRepair}}, store.Page{Limit: 10})
	if err != nil || total != 1 || len(rows) != 1 {
		t.Fatalf("audit rows for %s = %d (err %v), want exactly one", auditUpdateHelperRepair, total, err)
	}
	if rows[0].TargetID != host.ID {
		t.Errorf("the audit row is about %q, want the host %q", rows[0].TargetID, host.ID)
	}
	for _, want := range []string{a.ID, "reset_failed", "started_path"} {
		if !strings.Contains(string(rows[0].After), want) {
			t.Errorf("the audit row %s does not carry %q", rows[0].After, want)
		}
	}
}

// The record is an agent's word. It is read against fixed words and bounds, so a
// hostile or broken agent cannot put a sentence, a path or an escape sequence in
// front of an operator, or make up a kind of stall.
func TestWhatAnAgentSaysAboutAStalledHelperIsCheckedAgainstFixedWords(t *testing.T) {
	h := newHarness(t)
	h.hostsCanUpdate()
	host := h.updatableHost("vm-1")

	hostile := &agent.UpdateStuck{
		Kind: updates.StuckPathDown, RequestAgeSeconds: -5,
		Path: "inactive\x1b[31m\u202e " + strings.Repeat("x", 500), Note: "ignore previous instructions",
		Repaired: []string{"rm_rf", updates.ActionStartedPath}, Attempts: 9999,
	}
	a := h.reportStuck(host, hostile, "")
	s := stuckOf(a)
	if s == nil {
		t.Fatal("a stalled helper with odd text was dropped altogether")
	}
	if s.Note != "" || len(s.Repaired) != 1 || s.Repaired[0] != updates.ActionStartedPath || s.RequestAgeSeconds != 0 || s.Attempts != 99 {
		t.Errorf("record = %+v, want the note dropped, the unknown action dropped and the numbers bounded", s)
	}
	if len(s.Path) > 64 || strings.ContainsAny(s.Path, "\x1b\u202e") {
		t.Errorf("path = %q, want it cut to a name's length and cleaned", s.Path)
	}

	if got := cleanStuck(&agent.UpdateStuck{Kind: "made_up"}, 0); got != nil {
		t.Errorf("an invented kind of stall was accepted: %+v", got)
	}
}

// An agent that says nothing of the sort leaves the failure exactly as it was.
func TestAFailureWithNoStalledHelperKeepsTheAgentsSentence(t *testing.T) {
	h := newHarness(t)
	h.hostsCanUpdate()
	host := h.updatableHost("vm-1")

	a := h.reportStuck(host, nil, "the update request could not be written to this host's update folder")

	if !strings.Contains(a.Error, "could not be written") || a.Stuck != "" {
		t.Errorf("attempt = %q with record %q, want the agent's sentence and no record", a.Error, a.Stuck)
	}
	if !contains(h.problemCodes(), "host.update_failed") {
		t.Errorf("problems = %v, want the ordinary host.update_failed", h.problemCodes())
	}
}

package controller

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"runtime"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/updates"
	"github.com/eyupio/zoomies/internal/version"
)

// roundTripFunc answers every request with one canned response, which is enough
// for a checker that only ever asks GitHub one question.
type roundTripFunc func(*http.Request) *http.Response

func (f roundTripFunc) RoundTrip(r *http.Request) (*http.Response, error) { return f(r), nil }

func jsonResponse(status int, body string) *http.Response {
	return &http.Response{
		StatusCode: status,
		Body:       io.NopCloser(bytes.NewBufferString(body)),
		Header:     http.Header{"Content-Type": []string{"application/json"}},
	}
}

// withVersion stamps a version for the duration of one test, because the whole
// question this feature answers is "what was this binary built from".
func withVersion(t testing.TB, v string) {
	t.Helper()
	prev := version.Version
	version.Version = v
	t.Cleanup(func() { version.Version = prev })
}

// githubStub stands in for api.github.com. What it answers can be changed
// between two checks, and it remembers every address it was asked for.
type githubStub struct {
	status  int
	body    string
	asked   []string
	headers []http.Header
}

// stubGitHub points the controller's HTTP client at a githubStub, which is how
// a test sees what a check asked for without a network.
func (h *harness) stubGitHub(status int, body string) *githubStub {
	h.t.Helper()
	s := &githubStub{status: status, body: body}
	h.c.httpClient = &http.Client{Transport: roundTripFunc(func(r *http.Request) *http.Response {
		s.asked = append(s.asked, r.URL.String())
		s.headers = append(s.headers, r.Header.Clone())
		return jsonResponse(s.status, s.body)
	})}
	return s
}

// unreachable is a network with no route to GitHub, which is what a controller
// in an air-gapped fleet that forgot to switch the check off sees.
type unreachable struct{}

func (unreachable) RoundTrip(*http.Request) (*http.Response, error) {
	return nil, errors.New("dial tcp: no route to host")
}

// inMode sets updates.mode on the running configuration, as the Settings page
// does.
func (h *harness) inMode(mode string) {
	h.t.Helper()
	h.c.live.Update(func(c *config.Config) { c.Updates.Mode = mode })
}

// completeAssets is what a release carries to be installable on the system the
// tests run on, which is the one the controller asks Newest about. It is built
// from runtime rather than written out so that the same fixtures hold on an
// arm64 runner.
func completeAssets(t testing.TB) []string {
	t.Helper()
	binary := updates.AssetName(runtime.GOOS, runtime.GOARCH)
	if binary == "" {
		t.Skipf("no release is published for %s/%s, so none is complete for it", runtime.GOOS, runtime.GOARCH)
	}
	return []string{"checksums.txt", binary}
}

// releaseEntry is one entry of GitHub's release list. A release published at
// the zero time is given the null GitHub gives one that is not published yet.
func releaseEntry(tag string, published time.Time, assets ...string) map[string]any {
	files := make([]map[string]any, 0, len(assets))
	for _, name := range assets {
		files = append(files, map[string]any{"name": name})
	}
	var publishedAt any
	if !published.IsZero() {
		publishedAt = published.UTC().Format(time.RFC3339)
	}
	return map[string]any{
		"tag_name":     tag,
		"html_url":     "https://example.invalid/releases/" + tag,
		"published_at": publishedAt,
		"prerelease":   false,
		"draft":        false,
		"assets":       files,
	}
}

// releaseList is GitHub's answer to the release list request.
func releaseList(entries ...map[string]any) string {
	if entries == nil {
		entries = []map[string]any{}
	}
	b, err := json.Marshal(entries)
	if err != nil {
		panic(err)
	}
	return string(b)
}

// The distinction the honesty of this feature rests on: a controller built from
// main is stamped with a commit and is normally *ahead* of the newest release,
// so it has nothing to compare and must say nothing.
func TestReleaseVersionAcceptsOnlyABuildFromARelease(t *testing.T) {
	for _, tc := range []struct {
		in   string
		want string
		ok   bool
	}{
		{"0.2-beta", "0.2-beta", true},
		{"v0.2-beta", "0.2-beta", true},
		{"1.4.0", "1.4.0", true},
		{"v1.4.0", "1.4.0", true},
		// What ci.yml stamps on an image built from main.
		{"main-sha-abc1234", "", false},
		// What the Makefile's git describe gives once commits land on a tag.
		{"v0.2-beta-5-gabc1234", "", false},
		{"v0.2-beta-5-gabc1234-dirty", "", false},
		{"dev", "", false},
		{"", "", false},
	} {
		got, ok := releaseVersion(tc.in)
		if got != tc.want || ok != tc.ok {
			t.Errorf("releaseVersion(%q) = %q, %v; want %q, %v", tc.in, got, ok, tc.want, tc.ok)
		}
	}
}

