// What the rule in internal/updates reads is decoded from GitHub's names for it
// -- tag_name, published_at, prerelease, draft and the name of each asset -- and
// all of it is kept, the entries that cannot be taken included: the status
// explains a release that was passed over, and a soak is counted afresh every
// time the clock moves on, neither of which is a reason to ask GitHub again.
func TestTheWholeListIsRecordedAndTheNewestReleaseThatCanBeTakenIsNamed(t *testing.T) {
	h := newHarness(t)
	withVersion(t, "1.3.3")
	h.inMode("manual")
	assets := completeAssets(t)
	published := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)

	candidate := releaseEntry("v1.3.7", published.Add(72*time.Hour), assets...)
	candidate["prerelease"] = true
	pulled := releaseEntry("v1.3.6", time.Time{}, assets...)
	pulled["draft"] = true
	h.stubGitHub(http.StatusOK, releaseList(
		candidate,
		pulled,
		releaseEntry("v1.3.4", published, assets...),
		releaseEntry("v1.3.2", published.Add(-240*time.Hour), assets[0]),
	))

	if err := h.c.checkForRelease(h.ctx); err != nil {
		t.Fatalf("checkForRelease: %v", err)
	}

	got := h.c.latestRelease()
	if got == nil {
		t.Fatal("nothing was recorded")
	}
	want := []updates.Release{
		{Tag: "v1.3.7", URL: "https://example.invalid/releases/v1.3.7", PublishedAt: published.Add(72 * time.Hour), Prerelease: true, Assets: assets},
		{Tag: "v1.3.6", URL: "https://example.invalid/releases/v1.3.6", Draft: true, Assets: assets},
		{Tag: "v1.3.4", URL: "https://example.invalid/releases/v1.3.4", PublishedAt: published, Assets: assets},
		{Tag: "v1.3.2", URL: "https://example.invalid/releases/v1.3.2", PublishedAt: published.Add(-240 * time.Hour), Assets: assets[:1]},
	}
	if len(got.Releases) != len(want) {
		t.Fatalf("recorded %d releases, want %d: %+v", len(got.Releases), len(want), got.Releases)
	}
	for i, w := range want {
		g := got.Releases[i]
		if g.Tag != w.Tag || g.URL != w.URL || !g.PublishedAt.Equal(w.PublishedAt) ||
			g.Prerelease != w.Prerelease || g.Draft != w.Draft || !slices.Equal(g.Assets, w.Assets) {
			t.Errorf("release %d = %+v, want %+v", i, g, w)
		}
	}
	// The prerelease is the newest and fully equipped, and the draft is newer
	// than what is named too; neither may be offered.
	if got.Tag != "v1.3.4" || got.URL != "https://example.invalid/releases/v1.3.4" {
		t.Errorf("named %s (%s), want v1.3.4, the newest that is neither a prerelease nor a draft nor incomplete", got.Tag, got.URL)
	}
	if got.At.IsZero() {
		t.Error("the answer carries no time, so a stale one could not be recognised")
	}
}

// GitHub gives a release that is not published no date, and encoding/json turns
// a null, a missing key and the zero date alike into the zero time without an
// error. Refusing the whole list over one such entry would leave a fleet deaf to
// every release for as long as it stayed among the first ten. It is
// internal/updates that declines to offer a release it cannot date, because the
// soak starts from that date, so the entry is kept and the rest is read.
func TestAReleaseWithNoDateIsKeptInTheListAndNeverNamed(t *testing.T) {
	h := newHarness(t)
	withVersion(t, "1.3.3")
	h.inMode("manual")
	files := fmt.Sprintf(`[{"name":"checksums.txt"},{"name":%q}]`, completeAssets(t)[1])
	// By hand, because the three ways of leaving a date out are the point.
	h.stubGitHub(http.StatusOK, fmt.Sprintf(`[
		{"tag_name":"v1.3.6","html_url":"u6","published_at":null,"assets":%[1]s},
		{"tag_name":"v1.3.5","html_url":"u5","assets":%[1]s},
		{"tag_name":"v1.3.4","html_url":"u4","published_at":"0001-01-01T00:00:00Z","assets":%[1]s},
		{"tag_name":"v1.3.3","html_url":"u3","published_at":"2026-10-01T09:00:00Z","assets":%[1]s}
	]`, files))

	if err := h.c.checkForRelease(h.ctx); err != nil {
		t.Fatalf("an undated entry failed the check: %v", err)
	}

	got := h.c.latestRelease()
	if got == nil || len(got.Releases) != 4 {
		t.Fatalf("release = %+v, want all four entries kept", got)
	}
	for _, r := range got.Releases[:3] {
		if !r.PublishedAt.IsZero() {
			t.Errorf("%s has the date %s, want none", r.Tag, r.PublishedAt)
		}
	}
	if got.Tag != "v1.3.3" {
		t.Errorf("named %q, want v1.3.3: the three newer entries have no date to soak from", got.Tag)
	}
}

// GitHub's "latest" is the newest by date, and a release is public before its
// files have all been uploaded, so for a while the newest tag is one nothing can
// install. The notice used to name it. It names what the status would offer, so
// an operator is never told of one version in the banner and offered another in
// the panel under it.
func TestTheNoticeAndTheStatusNameTheSameRelease(t *testing.T) {
	h := newHarness(t)
	withVersion(t, "1.3.3")
	h.inMode("manual")
	assets := completeAssets(t)
	published := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
	h.stubGitHub(http.StatusOK, releaseList(
		// Binaries first and checksums last: this one is mid-upload.
		releaseEntry("v1.3.5", published.Add(2*time.Hour), assets[1]),
		releaseEntry("v1.3.4", published, assets...),
	))

	if err := h.c.checkForRelease(h.ctx); err != nil {
		t.Fatalf("checkForRelease: %v", err)
	}

	got := h.c.latestRelease()
	if got == nil || got.Tag != "v1.3.4" {
		t.Fatalf("release = %+v, want v1.3.4", got)
	}
	problems := h.c.updateProblems()
	if len(problems) != 1 || !strings.Contains(problems[0].Title, "v1.3.4") || strings.Contains(problems[0].Title, "v1.3.5") {
		t.Fatalf("problems = %+v, want one that names v1.3.4 and not v1.3.5", problems)
	}
	// The status is the rule in internal/updates applied to what was recorded.
	target := updates.Choose(updates.ChooseInput{
		Mode: updates.ModeManual, Now: h.c.Now(), Running: version.Version,
		Releases: got.Releases, GOOS: runtime.GOOS, GOARCH: runtime.GOARCH,
	})
	if !target.Newer || target.Release.Tag != got.Tag {
		t.Errorf("the status would offer %q (newer: %v), but the notice names %q", target.Release.Tag, target.Newer, got.Tag)
	}
}

// A controller can be ahead of the newest release that can be taken: its own
// release is public before checksums.txt is uploaded, so the list's newest
// complete entry is the one before it. Telling that controller "the current
// release is v1.3.9" while the status and the gauge say it is ahead sent an
// operator to downgrade. Only a controller behind the release is told of one.
// With the mode off the one request made today is read as it always was, and
// that path stays a plain comparison of the two words.
func TestTheNoticeIsOnlyRaisedForABuildBehindTheRelease(t *testing.T) {
	assets := completeAssets(t)
	published := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
	for _, tc := range []struct {
		name, mode, running, body string
		want                      bool
	}{
		{"the build is ahead of the newest complete release", "manual", "1.4.0",
			releaseList(releaseEntry("v1.4.0", published.Add(time.Hour), assets[1]), releaseEntry("v1.3.9", published, assets...)), false},
		{"the build is the release", "manual", "1.3.9",
			releaseList(releaseEntry("v1.3.9", published, assets...)), false},
		{"the build is behind the release", "auto", "1.3.3",
			releaseList(releaseEntry("v1.3.9", published, assets...)), true},
		{"the mode is off and the words differ", "off", "1.4.0",
			`{"tag_name":"v1.3.9","html_url":"https://example.invalid/r"}`, true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			withVersion(t, tc.running)
			h.inMode(tc.mode)
			h.stubGitHub(http.StatusOK, tc.body)
			if err := h.c.checkForRelease(h.ctx); err != nil {
				t.Fatalf("checkForRelease: %v", err)
			}

			problems := h.c.updateProblems()
			if got := len(problems) == 1; got != tc.want {
				t.Errorf("problems = %+v, want a notice: %v", problems, tc.want)
			}
		})
	}
}

// A list in which nothing can be taken is an answer and not the absence of one:
// the release that used to be there is gone from it, and naming it would send an
// operator to something GitHub no longer offers. The list is kept all the same,
// empty or not, so that the status can say why there is nothing to take instead
// of saying that nothing was read.
func TestAListWithNothingToTakeReplacesTheLastAnswer(t *testing.T) {
	assets := completeAssets(t)
	published := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
	for _, tc := range []struct {
		name string
		body string
		kept int
	}{
		{"every release in it is incomplete", releaseList(releaseEntry("v1.3.5", published, assets[0])), 1},
		{"it is empty", releaseList(), 0},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			withVersion(t, "1.3.3")
			h.inMode("manual")
			gh := h.stubGitHub(http.StatusOK, releaseList(releaseEntry("v1.3.4", published, assets...)))
			if err := h.c.checkForRelease(h.ctx); err != nil {
				t.Fatalf("the first check: %v", err)
			}
			if got := h.c.latestRelease(); got == nil || got.Tag != "v1.3.4" {
				t.Fatalf("release = %+v, want v1.3.4 before the list changes", got)
			}

			gh.body = tc.body
			if err := h.c.checkForRelease(h.ctx); err != nil {
				t.Fatalf("the second check: %v", err)
			}

			got := h.c.latestRelease()
			if got == nil {
				t.Fatal("the answer was dropped, so nothing says a list was read")
			}
			if got.Tag != "" || got.URL != "" {
				t.Errorf("named %q (%q), want no release: the list holds none that can be taken", got.Tag, got.URL)
			}
			if got.Releases == nil || len(got.Releases) != tc.kept {
				t.Errorf("releases = %#v, want %d kept and not nil: a list that came back empty is not a list that was never read", got.Releases, tc.kept)
			}
			if problems := h.c.updateProblems(); len(problems) != 0 {
				t.Errorf("problems = %v, want none when there is no release to name", problems)
			}
		})
	}
}

// The privacy page promises that the update check says nothing about an
// installation beyond the version it runs, in a User-Agent every call to GitHub
// carries. Asking for the list instead of the latest release is not a way
// round that, so the two questions are announced alike.
func TestTheListIsAskedForAsTheLatestReleaseIs(t *testing.T) {
	for _, tc := range []struct{ mode, body string }{
		{"off", `{"tag_name":"v1.3.4","html_url":"https://example.invalid/r"}`},
		{"manual", releaseList()},
	} {
		t.Run(tc.mode, func(t *testing.T) {
			h := newHarness(t)
			withVersion(t, "1.3.3")
			h.inMode(tc.mode)
			gh := h.stubGitHub(http.StatusOK, tc.body)

			if err := h.c.checkForRelease(h.ctx); err != nil {
				t.Fatalf("checkForRelease: %v", err)
			}

			if len(gh.headers) != 1 {
				t.Fatalf("made %d requests, want 1", len(gh.headers))
			}
			if got := gh.headers[0].Get("User-Agent"); got != "zoomies/1.3.3" {
				t.Errorf("User-Agent = %q, want zoomies/1.3.3", got)
			}
			if got := gh.headers[0].Get("Accept"); got != "application/vnd.github+json" {
				t.Errorf("Accept = %q, want application/vnd.github+json", got)
			}
		})
	}
}

// A controller that cannot get an answer is not a controller with a problem, and
// the answer it already holds is still the best it has. The error is for whoever
// asked, and the button reports it too: a person who asked for a check is not
// told that it worked.
func TestAFailedListRequestKeepsTheLastAnswer(t *testing.T) {
	assets := completeAssets(t)
	published := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
	for _, tc := range []struct {
		name string
		fail func(h *harness, gh *githubStub)
	}{
		{"GitHub refuses on its rate limit", func(_ *harness, gh *githubStub) {
			gh.status, gh.body = http.StatusForbidden, `{"message":"API rate limit exceeded"}`
		}},
		{"GitHub is down", func(_ *harness, gh *githubStub) {
			gh.status, gh.body = http.StatusBadGateway, `<html>Bad Gateway</html>`
		}},
		{"there is no route to GitHub", func(h *harness, _ *githubStub) {
			h.c.httpClient = &http.Client{Transport: unreachable{}}
		}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			withVersion(t, "1.3.3")
			h.inMode("manual")
			gh := h.stubGitHub(http.StatusOK, releaseList(releaseEntry("v1.3.4", published, assets...)))
			if err := h.c.checkForRelease(h.ctx); err != nil {
				t.Fatalf("the first check: %v", err)
			}
			before := h.c.latestRelease()

			tc.fail(h, gh)

			if err := h.c.checkForRelease(h.ctx); err == nil {
				t.Error("a check that failed returned no error")
			}
			if got := h.c.latestRelease(); got != before {
				t.Errorf("release = %+v, want the last answer %+v left alone", got, before)
			}
			if err := h.c.CheckForReleases(h.ctx); err == nil {
				t.Error("the button reported a check that failed as having worked")
			}
			if got := h.c.latestRelease(); got != before {
				t.Errorf("release = %+v after the button, want the last answer %+v left alone", got, before)
			}
		})
	}
}

// GitHub answers in this shape or something is wrong with the answer: a proxy's
// error page, an object where the list should be, or a body too large to be ten
// releases. None of it is guessed at. The check fails, and the answer already
// held stays, which is the difference between a stale notice and a wrong one.
func TestAListOfAnUnexpectedShapeIsIgnored(t *testing.T) {
	for _, tc := range []struct{ name, body string }{
		{"an object where the list should be", `{}`},
		{"null", `null`},
		{"an error page from a proxy", `<html><body>Bad Gateway</body></html>`},
		{"entries that are not releases", `[1, 2]`},
		{"a list cut off part way", `[{"tag_name":"v1.3.4","assets":[{"name":"checksums.txt"}`},
		{"a list larger than the controller will read", `[{"tag_name":"v1.3.4","body":"` + strings.Repeat("x", 5<<20) + `"}]`},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			withVersion(t, "1.3.3")
			h.inMode("manual")
			before := &releaseState{Tag: "v1.3.4", URL: "https://example.invalid/releases/v1.3.4", At: time.Now()}
			h.c.mu.Lock()
			h.c.release = before
			h.c.mu.Unlock()
			h.stubGitHub(http.StatusOK, tc.body)

			if err := h.c.checkForRelease(h.ctx); err == nil {
				t.Error("an answer that is not a list of releases returned no error")
			}
			if got := h.c.latestRelease(); got != before {
				t.Errorf("release = %+v, want the last answer %+v left alone", got, before)
			}
		})
	}
}

// updates.check_interval 0 is the air-gap switch: it says this controller must
// never make the one request that is not about the fleet, and a button is not an
// exception to it. A refusal is not a check, either, so it does not use up the
// minute: once the switch is turned back on, the next press asks.
func TestCheckForReleasesRefusesWhenTheCheckIsOff(t *testing.T) {
	h := newHarness(t)
	withVersion(t, "1.3.3")
	h.inMode("manual")
	h.c.live.Update(func(c *config.Config) { c.Updates.CheckInterval = 0 })
	gh := h.stubGitHub(http.StatusOK, releaseList())

	if err := h.c.CheckForReleases(h.ctx); !errors.Is(err, ErrUpdateCheckDisabled) {
		t.Fatalf("CheckForReleases = %v, want ErrUpdateCheckDisabled", err)
	}
	if len(gh.asked) != 0 {
		t.Fatalf("asked for %v with the check switched off, want nothing", gh.asked)
	}

	h.c.live.Update(func(c *config.Config) { c.Updates.CheckInterval = 24 * time.Hour })
	if err := h.c.CheckForReleases(h.ctx); err != nil {
		t.Fatalf("CheckForReleases once switched on: %v", err)
	}
	if len(gh.asked) != 1 {
		t.Errorf("asked %d times after the refusal, want the next press to ask once", len(gh.asked))
	}
}

// The request is unauthenticated, so the limit it spends is shared with
// everything else on the controller's address, and a button pressed twice is one
// question. A press inside the minute is not an error: what it would have learnt
// is what the last one learnt a moment ago. The wait is counted from the press
// that asked, so a press that was held back does not start it again.
func TestCheckForReleasesIsLimitedToOneRequestAMinute(t *testing.T) {
	h := newHarness(t)
	withVersion(t, "1.3.3")
	h.inMode("manual")
	gh := h.stubGitHub(http.StatusOK, releaseList())

	if err := h.c.CheckForReleases(h.ctx); err != nil {
		t.Fatalf("the first press: %v", err)
	}
	if len(gh.asked) != 1 {
		t.Fatalf("asked %d times after the first press, want 1", len(gh.asked))
	}

	h.advance(59 * time.Second)
	if err := h.c.CheckForReleases(h.ctx); err != nil {
		t.Errorf("a press after 59 seconds returned %v, want nil", err)
	}
	if len(gh.asked) != 1 {
		t.Fatalf("asked %d times after 59 seconds, want no new request", len(gh.asked))
	}

	h.advance(2 * time.Second)
	if err := h.c.CheckForReleases(h.ctx); err != nil {
		t.Fatalf("a press after 61 seconds: %v", err)
	}
	if len(gh.asked) != 2 {
		t.Errorf("asked %d times after 61 seconds, want the press to ask again", len(gh.asked))
	}
}

// GitHub refusing the request is the case the limit is for: a rate-limited
// address that is asked again a second later is asked a second time while it is
// still refusing. So the minute is spent by asking and not by succeeding, and a
// press after a failure is held back like any other.
func TestAFailedRequestStillUsesUpTheMinuteAllowance(t *testing.T) {
	h := newHarness(t)
	withVersion(t, "1.3.3")
	h.inMode("manual")
	gh := h.stubGitHub(http.StatusForbidden, `{"message":"API rate limit exceeded"}`)

	if err := h.c.CheckForReleases(h.ctx); err == nil {
		t.Fatal("a press that GitHub refused returned no error")
	}
	if len(gh.asked) != 1 {
		t.Fatalf("asked %d times after the first press, want 1", len(gh.asked))
	}

	h.advance(10 * time.Second)
	if err := h.c.CheckForReleases(h.ctx); err != nil {
		t.Errorf("a press inside the minute returned %v, want it held back without an error", err)
	}
	if len(gh.asked) != 1 {
		t.Errorf("asked %d times after a failure and a second press, want the second held back", len(gh.asked))
	}
}

// The request is made with no lock held, or every reader of the controller waits
// on GitHub for as long as the request takes, and the minute is taken before it
// is made, or a second press while it is in flight asks again. A request that
// presses the button and reads the answer from inside itself cannot be written
// to pass unless both are true: with the lock held it never returns, and with
// the stamp taken afterwards the inner press makes a second request.
func TestNoLockIsHeldAcrossTheRequestAndASecondPressDuringItIsHeldBack(t *testing.T) {
	h := newHarness(t)
	withVersion(t, "1.3.3")
	h.inMode("manual")

	asked := 0
	var innerErr error
	var innerSaw *releaseState
	h.c.httpClient = &http.Client{Transport: roundTripFunc(func(*http.Request) *http.Response {
		asked++
		if asked == 1 {
			innerErr = h.c.CheckForReleases(h.ctx)
			innerSaw = h.c.latestRelease()
		}
		return jsonResponse(http.StatusOK, releaseList())
	})}

	done := make(chan error, 1)
	go func() { done <- h.c.CheckForReleases(h.ctx) }()
	select {
	case err := <-done:
		if err != nil {
			t.Fatalf("the press: %v", err)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("the press never returned: a lock is held across the request")
	}

	if asked != 1 {
		t.Errorf("made %d requests, want the press during the first to be held back", asked)
	}
	if innerErr != nil {
		t.Errorf("the press during the request returned %v, want nil", innerErr)
	}
	if innerSaw != nil {
		t.Errorf("a press during the request saw %+v, want nothing learnt yet", innerSaw)
	}
}

// A clock that is stepped back leaves the last request in the future. Counted
// literally that is a negative wait, shorter than the minute, so the button would
// stay dead until the clock caught up with a time that was never real.
func TestAClockSteppedBackwardsDoesNotLockTheButton(t *testing.T) {
	h := newHarness(t)
	withVersion(t, "1.3.3")
	h.inMode("manual")
	gh := h.stubGitHub(http.StatusOK, releaseList())

	if err := h.c.CheckForReleases(h.ctx); err != nil {
		t.Fatalf("the first press: %v", err)
	}
	h.advance(-time.Hour)
	if err := h.c.CheckForReleases(h.ctx); err != nil {
		t.Fatalf("a press after the clock moved back: %v", err)
	}
	if len(gh.asked) != 2 {
		t.Errorf("asked %d times, want a press after the clock moved back to ask again", len(gh.asked))
	}
}

// The scheduled pass is what asks in production, and it is not told which
// question to ask: it has to reach the list when updating is on. The harness
// answers for GitHub with an empty list, which a pass that went to the real
// network instead could not.
func TestTheBackgroundPassReadsTheListWhenUpdatingIsOn(t *testing.T) {
	h := newHarness(t)
	withVersion(t, "1.3.3")
	h.inMode("manual")

	h.c.housekeep(h.ctx, &housekeeping{})

	got := h.c.latestRelease()
	if got == nil || got.Releases == nil || len(got.Releases) != 0 {
		t.Fatalf("release = %+v, want the empty list the harness gave", got)
	}
}

package controller

import (
	"strings"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/updates"
)

// controllerUpgradeCommand is what updates this controller by hand on its host,
// for a person to copy where the helper cannot be installed. With no version it
// takes the newest release, which is what the button would have taken.
//
// There is none on Windows: it has no sudo, and zoomies upgrade replaces a
// service it finds under systemd or launchd and knows no Windows service, so a
// command offered there would be one that fails.
func controllerUpgradeCommand(goos string) string {
	if goos == "windows" {
		return ""
	}
	return "sudo zoomies upgrade"
}

// controllerByHand is what to do to update this controller by hand, as the end
// of a sentence for the status and of a refusal: the command when there is one,
// and the steps when there is not.
func controllerByHand(goos string) (status, refusal string) {
	if controllerUpgradeCommand(goos) == "" {
		return "Update this controller on its host by hand: stop it, put the release's zoomies.exe in place of the one it runs, and start it again.",
			"update this controller on its host by hand, putting the release's zoomies.exe in place of the one it runs"
	}
	return "Update this controller on its host with the command below.", "update this controller on its host with zoomies upgrade"
}

// helperHostFacts is what this controller can see of its machine that decides
// whether the helper could be installed beside it. A container has the shared
// folder only when its embedded agent is on, which is the rule the installer
// mounts it by, and the runtime it runs under is the one that agent found.
func (c *Controller) helperHostFacts() updates.HelperHost {
	look := c.helperHost
	if look == nil {
		look = agent.LocalHelperHost
	}
	host := look()
	host.RunsRunners = c.cfg().Agent.Embedded
	c.mu.Lock()
	embedded := c.embedded
	c.mu.Unlock()
	if embedded != nil && embedded.RootlessRuntime() {
		host.RootlessRuntime = true
	}
	return host
}

// helperUnsupportedWhy is why the helper cannot be installed, for who, as the
// middle of a sentence. It names no path and nothing an agent wrote, because
// every role reads it.
func helperUnsupportedWhy(cause updates.HelperUnsupported, who string) string {
	switch cause {
	case updates.HelperUnsupportedOS:
		return who + " runs on an operating system other than Linux, and the update helper is a pair of systemd units, which need Linux"
	case updates.HelperUnsupportedNoSystemd:
		return who + " runs on a host that systemd does not run, and the update helper is a pair of systemd units"
	case updates.HelperUnsupportedNoSharedFolder:
		return who + " runs in a container that runs no runners, so the container does not mount the shared folder the update helper would read a request from"
	case updates.HelperUnsupportedRootless:
		return who + " runs in a container under a rootless runtime, which makes what the container writes belong to another account than the one the update helper serves"
	}
	return ""
}

// hostHelperUnsupported is why the helper cannot be installed on a host: what
// its agent said on its last beat, or, from an agent too old to say, an
// operating system the helper never runs on, which the host told the
// controller when it joined.
func (c *Controller) hostHelperUnsupported(h *store.Host) updates.HelperUnsupported {
	if os := strings.TrimSpace(h.OS); os != "" && os != "linux" {
		return updates.HelperUnsupportedOS
	}
	c.updates.hostMu.RLock()
	defer c.updates.hostMu.RUnlock()
	return c.updates.hostUnsupported[h.ID]
}

// noteHelperUnsupported keeps what a host's agent said on this beat about its
// helper. It is memory only: after a restart the next beat says it again, and
// until then the card offers the command that installs the helper, as it
// would for an agent too old to say. A word nobody defined is nothing said.
func (c *Controller) noteHelperUnsupported(hostID, said string) {
	cause := updates.HelperUnsupported(said)
	c.updates.hostMu.Lock()
	defer c.updates.hostMu.Unlock()
	if !cause.Known() {
		delete(c.updates.hostUnsupported, hostID)
		return
	}
	if c.updates.hostUnsupported == nil {
		c.updates.hostUnsupported = make(map[string]updates.HelperUnsupported)
	}
	c.updates.hostUnsupported[hostID] = cause
}

package controller

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/updates"
	"github.com/eyupio/zoomies/internal/updates/channel"
)

// Every cause the status names, with the words its sentence has to carry for a
// person to know which one it is.
var unsupportedCauses = []struct {
	name string
	// facts is this controller's machine with the cause; embedded is whether its
	// agent is on, which is what decides whether a container has a shared folder.
	facts    updates.HelperHost
	embedded bool
	// says is what the controller's sentence and refusal name.
	says string
	// command is the upgrade by hand the status offers to copy, and byHand what
	// the refusal says to do instead. Windows has no sudo, and zoomies upgrade
	// drives systemd or launchd and no Windows service, so it is given no
	// command, only what to do.
	command, byHand string
}{
	{"macOS", updates.HelperHost{GOOS: "darwin", Systemd: true}, true, "Linux", "sudo zoomies upgrade", "zoomies upgrade"},
	{"Windows", updates.HelperHost{GOOS: "windows"}, true, "Linux", "", "zoomies.exe"},
	{"a Linux host without systemd", updates.HelperHost{GOOS: "linux"}, true, "systemd", "sudo zoomies upgrade", "zoomies upgrade"},
	{"a controller-only container", updates.HelperHost{GOOS: "linux", InContainer: true}, false, "shared folder", "sudo zoomies upgrade", "zoomies upgrade"},
	{"a container under a rootless runtime", updates.HelperHost{GOOS: "linux", InContainer: true, RootlessRuntime: true}, true, "rootless", "sudo zoomies upgrade", "zoomies upgrade"},
}

// A controller the helper can never be installed beside is shown so, with the
// reason, and is never told to run a command that would only refuse. It is
// given the upgrade by hand that works there instead, and a missing helper is
// not a problem it can do anything about.
func TestAControllerThatCannotHaveTheHelperSaysWhyAndOffersNoInstall(t *testing.T) {
	for _, tc := range unsupportedCauses {
		t.Run(tc.name, func(t *testing.T) {
			withHelperHost(t, tc.facts)
			h := newHarness(t)
			h.c.live.Update(func(c *config.Config) { c.Agent.Embedded = tc.embedded })
			h.readyToUpdate()
			if err := os.Remove(filepath.Join(h.updateDir, channel.MarkerFile)); err != nil {
				t.Fatal(err)
			}
			h.pass(h.c)

			helper := h.status().Helper
			if helper.State != HelperUnsupported {
				t.Fatalf("the status says %+v, want unsupported", helper)
			}
			if helper.InstallCommand != "" || strings.Contains(helper.Reason, helperInstallCommand) {
				t.Errorf("the status still suggests installing the helper: %+v", helper)
			}
			if !strings.Contains(helper.Reason, tc.says) || helper.UpgradeCommand != tc.command {
				t.Errorf("the status says %+v, want a reason naming %q and the upgrade command %q", helper, tc.says, tc.command)
			}
			if tc.command == "" && (strings.Contains(helper.Reason, "command below") || !strings.Contains(helper.Reason, tc.byHand)) {
				t.Errorf("with no command to copy the status says %q, want what to do by hand and no command below", helper.Reason)
			}
			if strings.Contains(helper.Reason, h.updateDir) || strings.Contains(helper.Reason, "/") {
				t.Errorf("every role reads the reason, and it names a path: %q", helper.Reason)
			}

			_, err := h.c.RequestControllerUpdate(h.ctx, alice, "")
			assertRefusedWithNothingWritten(t, h, err, ErrUpdateHelperMissing)
			if strings.Contains(err.Error(), helperInstallCommand) || !strings.Contains(err.Error(), tc.says) ||
				!strings.Contains(err.Error(), tc.byHand) || (tc.command == "" && strings.Contains(err.Error(), "zoomies upgrade")) {
				t.Errorf("the refusal = %v, want the reason and %s, and no install command", err, tc.byHand)
			}

			if codes := h.problemCodes(); contains(codes, "controller.update_helper_missing") {
				t.Errorf("problems = %v, want no missing-helper problem for a host that cannot have one", codes)
			}
			if fix := h.problem(t, "controller.update_available").Fix; strings.Contains(fix, "Settings → Updates") {
				t.Errorf("the new-release notice sends the operator to a button that is not there: %q", fix)
			}
		})
	}
}

// Only a cause the installer is certain to refuse is shown as one. A machine
// the controller cannot see well enough to say, or one the helper could be
// installed on, keeps the command that installs it.
func TestAControllerTheHelperCouldBeInstalledBesideIsStillOfferedTheCommand(t *testing.T) {
	for _, tc := range []struct {
		name     string
		facts    updates.HelperHost
		embedded bool
	}{
		{"a native systemd host", updates.HelperHost{GOOS: "linux", Systemd: true}, false},
		{"a container that runs runners", updates.HelperHost{GOOS: "linux", InContainer: true}, true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			withHelperHost(t, tc.facts)
			h := newHarness(t)
			h.c.live.Update(func(c *config.Config) { c.Agent.Embedded = tc.embedded })
			withVersion(t, "1.3.4")
			if helper := h.status().Helper; helper.State != HelperMissing || helper.InstallCommand != helperInstallCommand || helper.UpgradeCommand != "" {
				t.Errorf("the status says %+v, want missing with the install command", helper)
			}
		})
	}
}

// The marker is the installer's last step, so a helper that is there is ready
// whatever the controller worked out about its machine; only an operating
// system that cannot run it at all is certain enough to overrule it.
func TestAReadyHelperIsReadyWhateverTheControllerWorkedOut(t *testing.T) {
	withHelperHost(t, updates.HelperHost{GOOS: "linux", InContainer: true})
	h := newHarness(t)
	h.c.live.Update(func(c *config.Config) { c.Agent.Embedded = false })
	withVersion(t, "1.3.4")
	h.installHelper()
	if got := h.status().Helper.State; got != HelperReady {
		t.Errorf("a controller-only container with the helper's marker in its folder is %q, want ready", got)
	}
}

// beatSaying is one heartbeat from a host's agent that offers no self-update and
// says why its host cannot have the helper.
func (h *harness) beatSaying(host *store.Host, ver, unsupported string) {
	h.t.Helper()
	if _, err := h.c.Heartbeat(h.ctx, host.ID, agent.HeartbeatRequest{
		ProtocolVersion: agent.ProtocolVersion, Version: ver, UpdateUnsupported: unsupported,
	}); err != nil {
		h.t.Fatalf("Heartbeat: %v", err)
	}
}

// A host the helper can never be installed on is shown so, with the reason, on
// its card and in its note, and nothing tells anyone to install it there. The
// command beneath the card is the way, and the note says so.
func TestAHostThatCannotHaveTheHelperSaysWhyAndOffersNoInstall(t *testing.T) {
	for _, tc := range []struct {
		name, word, says string
	}{
		{"no systemd", string(updates.HelperUnsupportedNoSystemd), "systemd"},
		{"rootless", string(updates.HelperUnsupportedRootless), "rootless"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			h.hostsCanUpdate()
			host := h.agentHost("vm-plain", "1.3.4")
			h.beatSaying(host, "1.3.4", tc.word)

			u := h.c.HostView(host).Update
			if u.State != HostUpdateUnsupported || u.CanUpdate || !strings.Contains(u.Reason, tc.says) {
				t.Fatalf("the card says %+v, want unsupported, not updatable, naming %q", u, tc.says)
			}
			if strings.Contains(u.Reason, "helper install") {
				t.Errorf("the card still suggests installing the helper: %q", u.Reason)
			}
			_, err := h.c.RequestHostUpdate(h.ctx, alice, host.ID)
			assertNothingSent(t, h, host, err, ErrUpdateHostCannotUpdate)
			if err.Error() != u.Reason {
				t.Errorf("the refusal = %q, want the card's own sentence %q", err, u.Reason)
			}

			p := h.problem(t, "host.update_unavailable")
			if p.Severity != config.SeverityInfo || p.TargetID != host.ID || !strings.Contains(p.Detail, tc.says) {
				t.Errorf("the note is %+v, want an info note about the host naming %q", p, tc.says)
			}
			if strings.Contains(p.Fix, "helper install") || !strings.Contains(p.Fix, "command on its card") {
				t.Errorf("the note's fix = %q, want the command on the card and no install", p.Fix)
			}
		})
	}
}

// An agent too old to say why still told the controller its operating system
// when it joined, and the helper never runs on any but Linux. A word nobody
// defined is read as nothing said, and so is an agent that stops saying it,
// which is what installing the helper there looks like.
func TestWhatTheControllerKnowsOfAHostsHelperFollowsTheHost(t *testing.T) {
	h := newHarness(t)
	h.hostsCanUpdate()

	mac := &store.Host{Name: "mac-mini", Capacity: 2, Backends: store.StringSlice{"process"}, Labels: store.StringMap{},
		OS: "darwin", Arch: "arm64", Version: "1.3.4", LastHeartbeat: h.c.Now()}
	if err := h.st.CreateHost(h.ctx, mac); err != nil {
		t.Fatal(err)
	}
	if u := h.c.HostView(mac).Update; u.State != HostUpdateUnsupported || !strings.Contains(u.Reason, "Linux") {
		t.Errorf("a macOS host that said nothing shows %+v, want unsupported naming Linux", u)
	}

	host := h.agentHost("vm-said", "1.3.4")
	h.beatSaying(host, "1.3.4", "because I said so")
	if u := h.c.HostView(host).Update; u.State != HostUpdateNone || !strings.Contains(u.Reason, "helper install") {
		t.Errorf("a word nobody defined shows %+v, want the card as before, with the install command", u)
	}

	h.beatSaying(host, "1.3.4", string(updates.HelperUnsupportedNoSystemd))
	if u := h.c.HostView(host).Update; u.State != HostUpdateUnsupported {
		t.Fatalf("after the agent said why the card shows %+v", u)
	}
	h.agentBeat(host, "1.3.4", nil)
	offering, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	if u := h.c.HostView(offering).Update; u.State != HostUpdateNone || !u.CanUpdate {
		t.Errorf("once the agent offers to update itself the card shows %+v, want it updatable", u)
	}

	// A host on the controller's release has nothing to update, whatever its
	// helper: the card says so, not why it could not.
	current := h.agentHost("vm-current", "1.3.5")
	h.beatSaying(current, "1.3.5", string(updates.HelperUnsupportedNoSystemd))
	if u := h.c.HostView(current).Update; u.State != HostUpdateNone || !strings.Contains(u.Reason, "already runs") {
		t.Errorf("a host on the release shows %+v, want nothing to update", u)
	}
	if codes := h.problemCodes(); count(codes, "host.update_unavailable") != 1 {
		t.Errorf("problems = %v, want one note, for the macOS host", codes)
	}

	// A deleted host is forgotten with its row.
	h.beatSaying(host, "1.3.4", string(updates.HelperUnsupportedNoSystemd))
	h.c.forgetHostUpdates(host.ID)
	h.c.updates.hostMu.RLock()
	_, kept := h.c.updates.hostUnsupported[host.ID]
	h.c.updates.hostMu.RUnlock()
	if kept {
		t.Error("what an agent said of its helper outlived its host")
	}
}

func count(list []string, s string) int {
	n := 0
	for _, v := range list {
		if v == s {
			n++
		}
	}
	return n
}

package controller

import (
	"cmp"
	"context"
	"fmt"
	"net/url"
	"runtime"
	"slices"
	"strings"
	"time"
	"unicode"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/releasekey"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/updates"
	"github.com/eyupio/zoomies/internal/version"
)

// The views below are the JSON of the update status. GET /updates returns one,
// updates.updated carries the same, and the metrics read the same, all rendered
// by UpdatesView and by nothing else: a frame dropped straight into the page is
// what a fetch would have returned, and a gauge cannot say something the page
// does not.

// UpdatesView is what the update mode would do about the releases on offer, and
// why.
//
// It is worked out when asked and never stored. It changes when the clock passes
// the end of a soak as much as when a list is read, and no row is written for
// either.
//
// Latest, Target and CheckedAt are null while updating is off and until a list
// has been read. A list that was read and holds nothing that can be installed is
// not the same: it has a time, and a sentence of its own.
type UpdatesView struct {
	// Mode is updates.mode as the controller acts on it, so a word the registry
	// does not know reads here, as everywhere else, as off.
	Mode string `json:"mode"`
	// Soak is updates.soak as the Settings page writes it. manual ignores it.
	Soak    string         `json:"soak"`
	Running UpdatesRunning `json:"running"`
	// Development compares the stamped build with main. It does not claim
	// that main's image has finished publishing to the dev channel.
	Development *UpdatesDevelopment `json:"development,omitempty"`
	// Latest is the newest release that could be installed on this system,
	// whether or not the running build is behind it.
	Latest *UpdatesRelease `json:"latest"`
	// Target is what the mode would do about Latest.
	Target *UpdatesTarget `json:"target"`
	// Reason is the sentence the page shows: the planner's, wherever a list has
	// been read, which is the release rule's own unless something else (an open
	// attempt, a rollout, the helper) decides what happens next. It holds no
	// elapsed time that moves with a heartbeat, so the panel is not repainted
	// for nothing.
	Reason string `json:"reason"`
	// CheckedAt is when the list Latest was chosen from was read.
	CheckedAt *time.Time `json:"checked_at"`
	// Helper says whether this controller can update itself, and if not, how a
	// person with root on its host makes it able to, or why nobody can.
	Helper UpdatesHelper `json:"helper"`
	// Signing says whether this build holds a release's checksums to a signature,
	// and the ids of the keys it trusts. No keys means it takes the checksums on
	// trust, which is what a build from before a key was committed does.
	Signing UpdatesSigning `json:"signing"`
	// Rollback says a controller that does not come back is put back on the
	// release it ran, which is a native service running the binary. A container's
	// service is its image, which the upgrade does not keep the one before, so
	// this is false there.
	Rollback bool `json:"rollback"`
	// Controller is this controller's latest update attempt, open or ended, and
	// null when it has never had one.
	Controller *UpdatesAttempt `json:"controller"`
	// Rollout is the open rollout, or the last one that ended, and null when
	// there has been none.
	Rollout *UpdatesRollout `json:"rollout"`
}

// UpdatesRollout is a walk of the fleet to one release, as far as it has got.
type UpdatesRollout struct {
	ID     string `json:"id"`
	Target string `json:"target"`
	// State is running or halted while it is open, then done or cancelled.
	State string `json:"state"`
	// HaltedReason is the sentence it halted with, and empty unless it is
	// halted now: it names the host and the release and never the helper's
	// text, which can name a path on the host, so every role reads it.
	HaltedReason string `json:"halted_reason"`
	// Done is the hosts it has updated, and Total those and the hosts it would
	// still update. Neither moves with a heartbeat, only with a host's version.
	Done  int `json:"done"`
	Total int `json:"total"`
	// Current is the name of the host being updated now, and empty with none.
	Current string `json:"current"`
}

// UpdatesHelper is the update helper beside the controller, as far as the
// controller can see it: its marker, in the folder the installer recorded.
type UpdatesHelper struct {
	// State is ready, missing, or unsupported where it can never be installed.
	State string `json:"state"`
	// Reason is the sentence the page shows. It names no path, because every role
	// reads it.
	Reason string `json:"reason"`
	// InstallCommand is what installs the helper, for a person to copy, and empty
	// when it is ready or cannot be installed.
	InstallCommand string `json:"install_command"`
	// UpgradeCommand is what updates the controller by hand on its host, for a
	// person to copy, and empty unless the helper cannot be installed: anywhere
	// else the helper is the way, and the command would be a second answer.
	UpgradeCommand string `json:"upgrade_command"`
}

// UpdatesSigning is the release signing key state of the running build, so a
// page can say whether a download is held to a signature and by which keys.
type UpdatesSigning struct {
	// Keys is one id per trusted release key, empty when none is compiled in.
	// The keys themselves are not exposed here: an id names one, which is all a
	// page needs to say what this build trusts.
	Keys []string `json:"keys"`
}

// UpdatesAttempt is one request to update, and how it ended.
type UpdatesAttempt struct {
	ID string `json:"id"`
	// State is requested until it ends, then succeeded, failed, timed_out or
	// cancelled.
	State string `json:"state"`
	// From is the build that asked, as it reports itself, and To the release tag
	// it asked for.
	From string `json:"from"`
	To   string `json:"to"`
	// Trigger is manual for a person and auto for the update mode.
	Trigger     string     `json:"trigger"`
	RequestedAt time.Time  `json:"requested_at"`
	FinishedAt  *time.Time `json:"finished_at"`
	// Error is why it did not succeed, often the helper's own sentence, and empty
	// otherwise. Below the platform role it is a fixed sentence for the state (see
	// For), because the text can name a folder on the controller's host.
	Error string `json:"error"`
	// Backup is the copy the engine took before it changed anything, for a page
	// to offer a restore from after a failed update. It names a folder on the
	// controller's host, so below the platform role it is empty (see For).
	Backup string `json:"backup"`
	// RolledBack says the engine put the previous release back because the new one
	// did not answer, so the attempt is a failure that was undone rather than one
	// left in place.
	RolledBack bool `json:"rolled_back"`
}

// UpdatesRunning is the build being updated, as it reports itself: a release
// binary says "1.3.5", without the v its tag has.
type UpdatesRunning struct {
	Version string `json:"version"`
	// Release says the build came from a release. A build from main is usually
	// ahead of the newest release, so only one that did can be offered an update
	// without it being a downgrade.
	Release bool `json:"release"`
}

type UpdatesDevelopment struct {
	Current   string     `json:"current"`
	Latest    string     `json:"latest"`
	State     string     `json:"state"`
	CheckedAt *time.Time `json:"checked_at"`
}

func (c *Controller) developmentView(running string) *UpdatesDevelopment {
	commit, ok := developmentCommit(running)
	if !ok {
		return nil
	}
	v := &UpdatesDevelopment{Current: commit, State: "unknown"}
	if latest := c.latestDevelopment(); latest != nil {
		v.Latest, v.State = latest.SHA, "available"
		at := latest.At.UTC()
		v.CheckedAt = &at
		if strings.HasPrefix(latest.SHA, commit) {
			v.State = "current"
		}
	}
	return v
}

// UpdatesRelease is a release on offer.
type UpdatesRelease struct {
	Tag string `json:"tag"`
	// URL is the release's page, so its notes can be read before it is taken.
	URL string `json:"url"`
	// PublishedAt is when GitHub published it, which is where the soak starts.
	PublishedAt time.Time `json:"published_at"`
}

// UpdatesTarget is what the mode would do about the newest release.
type UpdatesTarget struct {
	Tag string `json:"tag"`
	// Newer says the release is a later one than the running build. Only then is
	// there anything to take, and only then does DueAt mean anything.
	Newer bool `json:"newer"`
	// DueAt is the earliest time the mode takes the release: the end of the soak
	// in auto. It is null in manual, where the person asking is the only wait.
	DueAt *time.Time `json:"due_at"`
}

// For is the status as one audience may read it. The platform reads it whole.
//
// An attempt's error is often the helper's own sentence, or the controller's
// about a folder it could not write, and either can name a path on the
// controller's host. That host is the platform's to know about, so every other
// role is given a sentence for the state in its place, and still learns that the
// attempt ended and how. The helper's own sentence stays: it is fixed, and names
// no path, because every role reads it.
//
// It narrows a copy. The view is rendered once and handed to every audience, and
// the attempt it points to is shared.
func (v UpdatesView) For(platform bool) UpdatesView {
	if platform || v.Controller == nil {
		return v
	}
	attempt := *v.Controller
	if attempt.Error != "" {
		attempt.Error = withheldAttemptError(attempt.State)
	}
	// The copy's directory is a path on the controller's host, so it is withheld
	// in every state and not only along with an error: a succeeded update records
	// one too, and an attempt with nothing to say about a failure was once passed
	// through with its path. RolledBack is a fact about what happened, not a path,
	// and stays.
	attempt.Backup = ""
	v.Controller = &attempt
	return v
}

// withheldAttemptError is what a role below the platform reads where the text of
// an attempt's error would be. It is keyed on the state alone, so that it can
// never carry anything the error did.
func withheldAttemptError(state string) string {
	switch state {
	case store.UpdateTimedOut:
		return "The update helper did not answer in time. Whoever holds the platform role can read the detail."
	case store.UpdateCancelled:
		return "The update was cancelled. Whoever holds the platform role can read the detail."
	}
	return "The update did not succeed. Whoever holds the platform role can read why."
}

// UpdatesView works out the status now.
func (c *Controller) UpdatesView(ctx context.Context) (*UpdatesView, error) {
	// Loaded once, so that a settings change between two loads cannot give one
	// frame the old soak beside the new mode.
	cfg := c.cfg().Updates
	mode := updateModeOf(cfg.Mode)
	_, fromRelease := version.Release(version.Version)
	probe := c.probeUpdateHelper()
	view := &UpdatesView{
		Mode:        string(mode),
		Soak:        config.TidyDuration(cfg.Soak),
		Running:     UpdatesRunning{Version: version.Version, Release: fromRelease},
		Development: c.developmentView(version.Version),
		Helper:      probe.view,
		Signing:     UpdatesSigning{Keys: releasekey.IDs(releasekey.Default)},
		// A native service runs the binary the upgrade keeps beside it, so the
		// previous release can be put back; a container's service is an image,
		// which the upgrade does not keep the one before.
		Rollback: !c.helperHostFacts().InContainer,
	}
	pic, err := c.updatesSnapshot(ctx, cfg, probe)
	if err != nil {
		return nil, err
	}
	view.Rollout = c.rolloutView(pic)
	// The last attempt is shown in every mode: one that was in flight when
	// updating was switched off still ends, and the page says how.
	attempts, err := c.st.ListUpdateAttempts(ctx, store.UpdateScopeController, "", 1)
	if err != nil {
		return nil, fmt.Errorf("reading the controller's update attempts: %w", err)
	}
	if len(attempts) > 0 {
		view.Controller = attemptView(attempts[0])
	}

	state := c.latestRelease()
	// Having a release is not the same as having read the list. The check that ran
	// while updating was off asked only for the latest release, and switching to a
	// mode that wants the list starts no check of its own, so for a while the
	// status has a mode and no list. Handed none, the rule would say that no
	// complete release exists, which nobody has been told: a list with nothing in
	// it is an answer, and not having asked is not.
	listRead := state != nil && state.Releases != nil
	if mode != updates.ModeOff && !listRead {
		view.Reason = unreadReason(cfg.CheckInterval)
		return view, nil
	}

	var releases []updates.Release
	if listRead {
		releases = state.Releases
	}
	// A list that was never read goes in as nil only where the rule does not
	// depend on it: it decides off first. A list left over from when updating was
	// on offers nothing once it is off, for the same reason.
	target := updates.Choose(updates.ChooseInput{
		Mode: mode, Soak: cfg.Soak, Now: c.Now(), Running: version.Version,
		Releases: releases, GOOS: runtime.GOOS, GOARCH: runtime.GOARCH,
	})
	// The planner's sentence, worked out from the same snapshot it acts on, so
	// the page says what the next pass will do. Where nothing else stands in the
	// way it is the rule's own.
	view.Reason = updates.Decide(pic.snap).Sentence
	if mode == updates.ModeOff {
		return view, nil
	}
	if listRead {
		at := state.At.UTC()
		view.CheckedAt = &at
	}
	if target.Release.Tag == "" {
		return view, nil
	}

	view.Latest = &UpdatesRelease{
		Tag: target.Release.Tag, URL: releasePageURL(target.Release.URL), PublishedAt: target.Release.PublishedAt.UTC(),
	}
	view.Target = &UpdatesTarget{Tag: target.Release.Tag, Newer: target.Newer}
	if target.Newer && !target.DueAt.IsZero() {
		due := target.DueAt.UTC()
		view.Target.DueAt = &due
	}
	return view, nil
}

// rolloutView is the open rollout, or the last that ended, as the status shows
// it.
func (c *Controller) rolloutView(pic *updatesPicture) *UpdatesRollout {
	r := pic.rollout
	if r == nil {
		r = pic.last
	}
	if r == nil {
		return nil
	}
	out := &UpdatesRollout{ID: r.ID, Target: r.Target, State: r.State}
	// The store keeps the sentence after a resume or a cancel, as history. Shown
	// beside a rollout that is no longer halted it would ask for a resume or a
	// cancel that can no longer be made.
	if r.State == store.RolloutHalted {
		out.HaltedReason = r.HaltedReason
	}
	names := make(map[string]string, len(pic.hosts))
	for _, h := range pic.hosts {
		names[h.ID] = h.Name
	}
	done := map[string]bool{}
	asked := map[string]bool{}
	for _, a := range pic.attempts {
		if a.RolloutID != r.ID {
			continue
		}
		asked[a.HostID] = true
		switch a.State {
		case store.UpdateSucceeded:
			done[a.HostID] = true
		case store.UpdateRequested:
			out.Current = cmp.Or(names[a.HostID], a.HostID)
		}
	}
	out.Done = len(done)
	if r.State != store.RolloutRunning && r.State != store.RolloutHalted {
		// Ended: what it was made of is what it asked for.
		out.Total = len(asked)
		return out
	}
	out.Total = out.Done
	for _, h := range pic.hosts {
		if done[h.ID] || (len(r.HostIDs) > 0 && !slices.Contains(r.HostIDs, h.ID)) {
			continue
		}
		if can, _, _ := hostCanSelfUpdate(h, r.Target, c.hostHelperUnsupported(h), pic.snap.Mode, c.rentedHost(h.ID)); can {
			out.Total++
		}
	}
	return out
}

// attemptView is an attempt as the status shows it.
func attemptView(a store.UpdateAttempt) *UpdatesAttempt {
	out := &UpdatesAttempt{
		ID: a.ID, State: a.State, From: a.FromVersion, To: a.ToVersion, Trigger: a.Trigger,
		RequestedAt: a.RequestedAt.UTC(), Error: withoutDirectionControls(a.Error),
		Backup: withoutDirectionControls(a.Backup), RolledBack: a.RolledBack,
	}
	if a.FinishedAt != nil {
		at := a.FinishedAt.UTC()
		out.FinishedAt = &at
	}
	return out
}

// withoutDirectionControls is s with the characters that change the direction
// text is shown in, or end a line the browser would not otherwise end, taken out.
// The update folder is writable by the service, so the helper's sentence in it is
// not trusted to be plain text, and the page shows it as written, which an
// override would reorder. Line breaks are kept: a real sentence has them.
func withoutDirectionControls(s string) string {
	return strings.Map(func(r rune) rune {
		if isBidiControl(r) {
			return -1
		}
		return r
	}, s)
}

// unreadReason says why there is nothing to offer yet, for a mode that wants a
// list nobody has read.
//
// It claims nothing about what the list holds, which is the one thing not known:
// the rule's sentence for a list with no complete release in it would tell the
// operator that none exists.
func unreadReason(interval time.Duration) string {
	if interval <= 0 {
		return "Zoomies has not read the release list, and updates.check_interval is 0, which switches the check off. " +
			"Set updates.check_interval to a duration such as 24h to be offered releases."
	}
	return fmt.Sprintf("Zoomies has not read the release list yet. It reads it every %s, so the next read is due within that time.",
		config.TidyDuration(interval))
}

// releasePageURL is a release's page when it is one a browser can safely be sent
// to, and blank when it is not.
//
// The address arrives as GitHub's html_url and the UI puts it in a link. GitHub
// is trusted to be GitHub, but a proxy in between, or a response that has been
// tampered with, is not, and a javascript: address in an href runs in the
// operator's session. Only an absolute https address with a host and no
// control characters passes; the page then simply has no link.
func releasePageURL(raw string) string {
	for _, r := range raw {
		if unicode.IsControl(r) {
			return ""
		}
	}
	u, err := url.Parse(raw)
	if err != nil || u.Scheme != "https" || u.Host == "" {
		return ""
	}
	return raw
}

