				t.Errorf("soak = %q, want %q", got.Soak, tc.want)
			}
		})
	}
}

// The status says whether this build holds a release's checksums to a
// signature, and by which key ids, so a page can show it without the key
// itself ever leaving the binary.
func TestTheStatusNamesTheReleaseKeysThisBuildTrusts(t *testing.T) {
	public, _, err := releasekey.Generate()
	if err != nil {
		t.Fatal(err)
	}
	old := releasekey.Default
	releasekey.Default = public
	t.Cleanup(func() { releasekey.Default = old })

	h := newHarness(t)
	withVersion(t, "1.3.0")
	keys := h.status().Signing.Keys
	parsed, err := releasekey.ParsePublic(public)
	if err != nil {
		t.Fatal(err)
	}
	if len(keys) != 1 || keys[0] != parsed.ID {
		t.Fatalf("keys = %v, want [%s]", keys, parsed.ID)
	}
}

func TestTheStatusSaysABuildWithNoReleaseKeyVerifiesNothing(t *testing.T) {
	old := releasekey.Default
	releasekey.Default = ""
	t.Cleanup(func() { releasekey.Default = old })

	h := newHarness(t)
	withVersion(t, "1.3.0")
	if keys := h.status().Signing.Keys; len(keys) != 0 {
		t.Fatalf("keys = %v, want none", keys)
	}
}

// Whether a controller that does not come back is put back is a fact about how
// it runs: a native service runs the binary the upgrade keeps beside it, a
// container's service is an image. The status says which, so the confirmation
// can promise the rollback only where it applies.
func TestTheStatusSaysWhetherAControllerThatFailsIsPutBack(t *testing.T) {
	withHelperHost(t, updates.HelperHost{GOOS: "linux", Systemd: true})
	h := newHarness(t)
	if !h.status().Rollback {
		t.Fatal("a native controller is put back and the status should say so")
	}
	withHelperHost(t, updates.HelperHost{GOOS: "linux", InContainer: true, RunsRunners: true})
	if h.status().Rollback {
		t.Fatal("a container controller is not put back and the status should not promise it")
	}
}

// The document says every field is always present, so a client reads a missing
// release as null and never has to ask whether the key is there.
func TestTheStatusAlwaysCarriesEveryFieldAndIsNullWhereThereIsNothing(t *testing.T) {
	h := newHarness(t)
	withVersion(t, "1.3.0")
	raw, err := json.Marshal(h.status())
	if err != nil {
		t.Fatalf("marshalling the status: %v", err)
	}

	var fields map[string]json.RawMessage
	if err := json.Unmarshal(raw, &fields); err != nil {
		t.Fatalf("the status is not a JSON object: %v", err)
	}
	for _, key := range []string{"mode", "soak", "running", "latest", "target", "reason", "checked_at", "helper", "signing", "rollback", "controller", "rollout"} {
		if _, ok := fields[key]; !ok {
			t.Errorf("the status has no %q: %s", key, raw)
		}
	}
	for _, key := range []string{"latest", "target", "checked_at", "controller", "rollout"} {
		if got := string(fields[key]); got != "null" {
			t.Errorf("%s = %s, want null while there is nothing to name", key, got)
		}
	}
	if len(fields) != 12 {
		t.Errorf("the status has %d fields, want the twelve the document lists: %s", len(fields), raw)
	}
}

// The mode names live in two places that cannot import each other: the choices
// the setting offers, in internal/config, and the modes the rule acts on, in
// internal/updates. A choice the second does not know would be offered on the
// Settings page, accepted, and then read as off by every pass, so the setting
// would say one thing while the controller did another. This is the test that
// notices when only one of the two has been told.
func TestEveryUpdateModeTheRegistryOffersIsOneThePlannerKnows(t *testing.T) {
	setting, ok := config.LookupSetting("updates.mode")
	if !ok {
		t.Fatal("updates.mode is not in the settings registry")
	}
	if !slices.Contains(setting.Choices, string(updates.ModeOff)) {
		t.Errorf("the registry offers %v, and off is not among them: off is the default and the way back", setting.Choices)
	}
	newer := []updates.Release{{
		Tag: "v1.3.2", PublishedAt: time.Now().Add(-48 * time.Hour),
		Assets: []string{"checksums.txt", updates.AssetName("linux", "amd64")},
	}}
	for _, choice := range setting.Choices {
		t.Run(choice, func(t *testing.T) {
			h := newHarness(t)
			h.inMode(choice)
			mode := updates.Mode(choice)

			if got := h.c.updateMode(); got != mode {
				t.Errorf("the controller reads %q as %q, want it taken as it is", choice, got)
			}
			target := updates.Choose(updates.ChooseInput{
				Mode: mode, Now: time.Now(), Running: "1.3.0", Releases: newer, GOOS: "linux", GOARCH: "amd64",
			})
			switch {
			case mode == updates.ModeOff && target.Release.Tag != "":
				t.Errorf("off offered %s", target.Release.Tag)
			case mode != updates.ModeOff && !target.Newer:
				t.Errorf("the planner does not act on %q: it offers nothing when a newer release is there, which is how it treats a mode it does not know", choice)
			}
		})
	}
}

// A check that finishes writes no row and publishes nothing of its own: the
// status is computed from what the check recorded, and the pass that follows
// sends the frame. So an open page hears about a finished check exactly once,
// from the pass, and a check does not need a publish call that could be forgotten
// or could say something the GET would not.
func TestAFinishedCheckReachesAnOpenStreamOnTheNextPassAndNotBefore(t *testing.T) {
	h := newHarness(t)
	h.fleet()
	withVersion(t, "1.3.0")
	h.inMode("manual")
	sub := h.listen(events.KindUpdates)

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	before := nextOfKind(t, sub, events.KindUpdates)
	if reason, _ := before["reason"].(string); !strings.Contains(reason, "has not read the release list") {
		t.Fatalf("frame before the check: reason = %q, want it to say the list is unread", reason)
	}

	h.readTheList(releaseEntry("v1.3.2", whenAgo(6*time.Hour), completeAssets(t)...))
	nothingFor(t, sub)

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile after the check: %v", err)
	}
	after := nextOfKind(t, sub, events.KindUpdates)
	if target, _ := after["target"].(map[string]any); target["tag"] != "v1.3.2" || after["checked_at"] == nil {
		t.Errorf("frame after the check: target %v, checked_at %v, want v1.3.2 and the time it was read", after["target"], after["checked_at"])
	}
}

// The address is put in a link on the page, and it arrives off the network. Only
// an absolute https one is passed on; anything else leaves the release without a
// link and is never an error, because the page works without one.
func TestTheReleasePageIsLinkedOnlyWhenItIsAnAbsoluteHTTPSAddress(t *testing.T) {
	for _, tc := range []struct {
		name, url, want string
	}{
		{"a release page", "https://github.com/eyupio/zoomies/releases/tag/v1.3.5", "https://github.com/eyupio/zoomies/releases/tag/v1.3.5"},
		{"a script address", "javascript:alert(1)", ""},
		{"plain http", "http://x/", ""},
		{"https with no host", "https://", ""},
		{"a newline in the address", "https://github.com/eyupio/zoomies/releases/tag/v1.3.5\nx", ""},
		{"a tab in the address", "https://github.com/\teyupio", ""},
		{"a delete character in the address", "https://github.com/\x7f", ""},
		{"a relative address", "/eyupio/zoomies/releases", ""},
		{"nothing", "", ""},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := releasePageURL(tc.url); got != tc.want {
				t.Errorf("releasePageURL(%q) = %q, want %q", tc.url, got, tc.want)
			}
		})
	}

	// And the status uses it, so a list GitHub's answer put a bad address in is
	// shown without the link and not with it.
	h := newHarness(t)
	withVersion(t, "1.3.0")
	h.inMode("manual")
	entry := releaseEntry("v1.3.2", whenAgo(6*time.Hour), completeAssets(t)...)
	entry["html_url"] = "javascript:alert(1)"
	h.readTheList(entry)
	got := h.status()
	if got.Latest == nil || got.Latest.Tag != "v1.3.2" || got.Latest.URL != "" {
		t.Errorf("latest = %+v, want v1.3.2 with no link", got.Latest)
	}
}

// An attempt's error is often the helper's own sentence, or the controller's
// about a folder it could not write, and either can name a path on the
// controller's host. The status is read by every role and sent to every open
// page, so only the platform, which owns that host, is given the text; the
// others are told the state's own sentence, which names nothing.
func TestTheStatusWithholdsAnAttemptsErrorBelowPlatform(t *testing.T) {
	const secret = "/var/lib/zoomies-update/request.json"
	attempt := func(state, text string) *UpdatesAttempt {
		return &UpdatesAttempt{ID: "upd_1", State: state, From: "1.3.4", To: "v1.3.5", Trigger: "manual", Error: text}
	}
	helper := UpdatesHelper{State: HelperReady, Reason: "The update helper is installed on this controller's host, so the controller can update itself."}

	for _, state := range []string{"failed", "timed_out", "cancelled"} {
		t.Run(state, func(t *testing.T) {
			view := UpdatesView{Mode: "manual", Helper: helper, Controller: attempt(state, "cannot write in "+secret)}

			if got := view.For(true); got.Controller.Error != "cannot write in "+secret {
				t.Errorf("the platform's error = %q, want the text as it was written", got.Controller.Error)
			}
			below := view.For(false)
			if below.Controller.Error == "" {
				t.Error("a role below platform was given no reason at all, so the page cannot say anything about why")
			}
			if strings.Contains(below.Controller.Error, secret) || strings.Contains(below.Controller.Error, "/") {
				t.Errorf("the error below platform = %q, want a sentence that names no path", below.Controller.Error)
			}
			if below.Controller.State != state || below.Controller.To != "v1.3.5" {
				t.Errorf("the attempt below platform = %+v, want its state and target kept", below.Controller)
			}
			if below.Helper != helper {
				t.Errorf("the helper below platform = %+v, want the status's own sentence kept: %+v", below.Helper, helper)
			}
			// The view is shared with the other audiences, which are each handed a
			// value of their own.
			if view.Controller.Error != "cannot write in "+secret {
				t.Errorf("narrowing the status changed the one it was made from: %q", view.Controller.Error)
			}
		})
	}

	t.Run("an attempt with nothing to withhold stays empty", func(t *testing.T) {
		view := UpdatesView{Controller: attempt("requested", "")}
		if got := view.For(false).Controller.Error; got != "" {
			t.Errorf("error = %q, want none: a sentence about a failure on an attempt that has not failed", got)
		}
	})
	t.Run("a controller that has never had an attempt", func(t *testing.T) {
		if got := (UpdatesView{}).For(false); got.Controller != nil {
			t.Errorf("controller = %+v, want null", got.Controller)
		}
	})
}

// The directory of the copy an update took first names a folder on the
// controller's host, as an error can, so a role below the platform is not given
// it whatever state the attempt is in. A succeeded update records one too, and
// an attempt with no error was passed through whole, path and all.
func TestTheStatusWithholdsAnAttemptsBackupDirectoryBelowPlatformInEveryState(t *testing.T) {
	const dir = "/var/lib/zoomies-update/backup-20261018"
	for _, tc := range []struct{ state, text string }{
		{"requested", ""},
		{"succeeded", ""},
		{"cancelled", ""},
		{"failed", "cannot write in /var/lib/zoomies-update"},
		{"timed_out", "no answer from the helper"},
	} {
		t.Run(tc.state, func(t *testing.T) {
			view := UpdatesView{Controller: &UpdatesAttempt{
				ID: "upd_1", State: tc.state, From: "1.3.4", To: "v1.3.5", Error: tc.text, Backup: dir, RolledBack: true,
			}}

			if got := view.For(true).Controller.Backup; got != dir {
				t.Errorf("the platform's backup = %q, want the directory as it was recorded", got)
			}
			below := view.For(false)
			if below.Controller.Backup != "" {
				t.Errorf("the backup below platform = %q, want it withheld: it names a folder on the controller's host", below.Controller.Backup)
			}
			if !below.Controller.RolledBack || below.Controller.State != tc.state {
				t.Errorf("the attempt below platform = %+v, want what happened kept: only the path is withheld", below.Controller)
			}
			if view.Controller.Backup != dir {
				t.Errorf("narrowing the status changed the one it was made from: %q", view.Controller.Backup)
			}
		})
	}
}

// The page shows the helper's sentence as it was written, line breaks and all.
// The folder is one the service can write, so a result in it is not trusted to
// be plain text: a direction override would reorder what an operator reads, and
// the platform is shown the sentence whole. The override is the only thing taken
// out; the lines of a real sentence stay.
func TestTheStatusStripsDirectionControlsFromAnAttemptsErrorEvenForThePlatform(t *testing.T) {
	h := newHarness(t)
	h.readyToUpdate()
	a := h.request()
	h.takeRequest()
	hostile := "cannot write \u202eelif.tseuqer\u202c in \u2066the folder\u2069\u200e\u200f\u061c.\nSecond line\u2028 here"
	h.helperAnswers(updates.Result{ID: a.ID, OK: false, Error: hostile, FinishedAt: time.Now()})
	h.pass(h.c)

	const want = "cannot write elif.tseuqer in the folder.\nSecond line here"
	if got := h.status().For(true).Controller.Error; got != want {
		t.Errorf("the platform reads %q, want %q", got, want)
	}
}

// A check that could not be completed is the controller's sentence, whole, and
// is still the sentinel that tells the API it was upstream's failure and not its
// own.
func TestAFailedReleaseListReadKeepsItsSentenceAndIsTheCheckFailedSentinel(t *testing.T) {
	h := newHarness(t)
	withVersion(t, "1.3.0")
	h.inMode("manual")

	t.Run("GitHub refuses", func(t *testing.T) {
		h.stubGitHub(http.StatusForbidden, `{"message":"rate limited"}`)
		err := h.c.checkForRelease(h.ctx)
		if !errors.Is(err, ErrUpdateCheckFailed) {
			t.Fatalf("error = %v, want ErrUpdateCheckFailed", err)
		}
		if !strings.HasPrefix(err.Error(), "GitHub answered 403 ") || strings.Contains(err.Error(), ErrUpdateCheckFailed.Error()) {
			t.Errorf("error = %q, want the controller's own sentence only", err)
		}
	})
	t.Run("the network is down", func(t *testing.T) {
		h.c.httpClient = &http.Client{Transport: unreachable{}}
		err := h.c.checkForRelease(h.ctx)
		if !errors.Is(err, ErrUpdateCheckFailed) || !strings.Contains(err.Error(), "api.github.com") {
			t.Errorf("error = %v, want ErrUpdateCheckFailed and the sentence about outbound HTTPS", err)
		}
	})
	t.Run("an answer that is not a list", func(t *testing.T) {
		h.stubGitHub(http.StatusOK, `{"not":"a list"}`)
		if err := h.c.checkForRelease(h.ctx); !errors.Is(err, ErrUpdateCheckFailed) {
			t.Errorf("error = %v, want ErrUpdateCheckFailed", err)
		}
	})
}

// The store keeps the sentence a rollout halted with after it is resumed or
// cancelled, as history. The status must not: a cancelled rollout shown with
// "resume the rollout or cancel it" asks for a press that can no longer be made.
func TestARolloutSaysWhyItHaltedOnlyWhileItIsHalted(t *testing.T) {
	h := newHarness(t)
	h.autoFleet("manual")
	h.updatableHost("vm-a")
	if _, _, err := h.c.StartHostRollout(h.ctx, alice, nil); err != nil {
		t.Fatalf("StartHostRollout: %v", err)
	}
	r := h.openRollout()
	const why = "The update of vm-a to v1.3.5 did not succeed, so the rollout is halted."
	if _, err := h.st.HaltUpdateRollout(h.ctx, r.ID, why); err != nil {
		t.Fatal(err)
	}
	if got := h.status().Rollout; got == nil || got.State != store.RolloutHalted || got.HaltedReason != why {
		t.Fatalf("the halted rollout shows as %+v, want it halted with its sentence", got)
	}
	if _, _, err := h.c.ResumeRollout(h.ctx, alice); err != nil {
		t.Fatalf("ResumeRollout: %v", err)
	}
	if got := h.status().Rollout; got == nil || got.State != store.RolloutRunning || got.HaltedReason != "" {
		t.Errorf("the resumed rollout shows as %+v, want it running with no halted sentence", got)
	}
	if _, err := h.st.HaltUpdateRollout(h.ctx, r.ID, why); err != nil {
		t.Fatal(err)
	}
	if _, _, err := h.c.CancelRollout(h.ctx, alice); err != nil {
		t.Fatalf("CancelRollout: %v", err)
	}
	if got := h.status().Rollout; got == nil || got.State != store.RolloutCancelled || got.HaltedReason != "" {
		t.Errorf("the cancelled rollout shows as %+v, want it cancelled with no halted sentence", got)
	}
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"slices"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// A workflow_job delivery used to ask the store which installation covers its
// repository twice: once to pick the secret the signature is checked with, and
// again to say which installation the job belongs to. It is one question about
// one repository asked a few hundred microseconds apart, and in a profile each
// asking was about 6% of a delivery.

// countInstallationQuestions makes the controller ask which installation covers
// a repository through a counter, and returns the count.
func (h *harness) countInstallationQuestions(failFirst bool) *int {
	h.t.Helper()
	asked := new(int)
	h.c.findInstallation = func(ctx context.Context, repo string) (*store.Installation, error) {
		*asked++
		if failFirst && *asked == 1 {
			return nil, errors.New("the database is busy")
		}
		return h.st.FindInstallationByTarget(ctx, repo)
	}
	return asked
}

func TestADeliveryAsksWhichInstallationCoversItsRepositoryOnce(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	asked := h.countInstallationQuestions(false)

	rec := h.deliverJob(jobEvent{Action: "queued", JobID: 1, RunID: 10, Labels: []string{"self-hosted", "linux"}})
	if rec.Code != http.StatusAccepted {
		t.Fatalf("the delivery was answered %d: %s", rec.Code, rec.Body)
	}
	if *asked != 1 {
		t.Errorf("the delivery asked which installation covers its repository %d times; want once", *asked)
	}
	job, err := h.st.GetJobByGitHubID(h.ctx, 1)
	if err != nil {
		t.Fatalf("reading the job back: %v", err)
	}
	if job.InstallationID != inst.ID {
		t.Errorf("the job belongs to installation %q; want %q, the one that covers its repository", job.InstallationID, inst.ID)
	}
}

// The answer that no installation covers a repository is as good as any other:
// it is kept for the rest of the delivery too, and the job is recorded with none,
// as it always was.
func TestADeliveryForARepositoryNoInstallationCoversAsksOnce(t *testing.T) {
	h := newHarness(t)
	h.installation() // covers acme and nothing else
	asked := h.countInstallationQuestions(false)

	rec := h.deliverJob(jobEvent{Action: "queued", JobID: 2, RunID: 11, Repo: "stranger/repo", Labels: []string{"self-hosted", "linux"}})
	if rec.Code != http.StatusAccepted {
		t.Fatalf("the delivery was answered %d: %s", rec.Code, rec.Body)
	}
	if *asked != 1 {
		t.Errorf("the delivery asked which installation covers its repository %d times; want once", *asked)
	}
	job, err := h.st.GetJobByGitHubID(h.ctx, 2)
	if err != nil {
		t.Fatalf("reading the job back: %v", err)
	}
	if job.InstallationID != "" {
		t.Errorf("the job belongs to installation %q; want none, nothing covers stranger/repo", job.InstallationID)
	}
}

// Only an answer is kept. A lookup that failed says nothing about the
// repository, so the job's own question is asked again, as it always was, and a
// busy database for a moment does not cost a job its installation.
func TestAFailedInstallationLookupIsAskedAgainWhenTheJobIsApplied(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	asked := h.countInstallationQuestions(true)

	rec := h.deliverJob(jobEvent{Action: "queued", JobID: 3, RunID: 12, Labels: []string{"self-hosted", "linux"}})
	if rec.Code != http.StatusAccepted {
		t.Fatalf("the delivery was answered %d: %s", rec.Code, rec.Body)
	}
	if *asked != 2 {
		t.Errorf("the delivery asked %d times after the first failed; want a second, and no more", *asked)
	}
	job, err := h.st.GetJobByGitHubID(h.ctx, 3)
	if err != nil {
		t.Fatalf("reading the job back: %v", err)
	}
	if job.InstallationID != inst.ID {
		t.Errorf("the job belongs to installation %q; want %q, which the second question found", job.InstallationID, inst.ID)
	}
}

// deliveryOwner on its own, with a store that says what it is told.

type ownerReply struct {
	inst *store.Installation
	err  error
}

// scriptedOwner is a deliveryOwner whose store gives each reply in turn, the last
// one for ever, and a count of the times it was asked.
func scriptedOwner(replies ...ownerReply) (*deliveryOwner, *int) {
	asked := new(int)
	return &deliveryOwner{ask: func(context.Context, string) (*store.Installation, error) {
		r := replies[min(*asked, len(replies)-1)]
		*asked++
		return r.inst, r.err
	}}, asked
}

func TestADeliveryOwnerAsksTheStoreOnceForAnInstallationItFound(t *testing.T) {
	inst := &store.Installation{ID: "ins_a"}
	owners, asked := scriptedOwner(ownerReply{inst: inst})
	for range 3 {
		got, err := owners.of(context.Background(), "acme/widgets")
		if err != nil || got != inst {
			t.Fatalf("of = %v, %v; want the installation", got, err)
		}
	}
	if *asked != 1 {
		t.Errorf("the store was asked %d times; want once", *asked)
	}
}

func TestADeliveryOwnerAsksTheStoreOnceWhenNoInstallationCoversTheRepository(t *testing.T) {
	owners, asked := scriptedOwner(ownerReply{err: fmt.Errorf("installation for acme/widgets: %w", store.ErrNotFound)})
	for range 3 {
		if got, err := owners.of(context.Background(), "acme/widgets"); got != nil || !errors.Is(err, store.ErrNotFound) {
			t.Fatalf("of = %v, %v; want no installation and ErrNotFound", got, err)
		}
	}
	if *asked != 1 {
		t.Errorf("the store was asked %d times; want once", *asked)
	}
}

func TestADeliveryOwnerDoesNotKeepAFailedLookup(t *testing.T) {
	inst := &store.Installation{ID: "ins_a"}
	busy := errors.New("the database is busy")
	owners, asked := scriptedOwner(ownerReply{err: busy}, ownerReply{inst: inst})

	if _, err := owners.of(context.Background(), "acme/widgets"); !errors.Is(err, busy) {
		t.Fatalf("the first of = %v; want the failure", err)
	}
	for range 2 {
		if got, err := owners.of(context.Background(), "acme/widgets"); err != nil || got != inst {
			t.Fatalf("of after the failure = %v, %v; want the installation the store then found", got, err)
		}
	}
	if *asked != 2 {
		t.Errorf("the store was asked %d times; want twice, the failure and then the answer", *asked)
	}
}

// A delivery names one repository, and the owner remembers one. A question about
// another goes to the store, and the first is forgotten for it.
func TestADeliveryOwnerRemembersTheRepositoryItWasAskedAbout(t *testing.T) {
	a, b := &store.Installation{ID: "ins_a"}, &store.Installation{ID: "ins_b"}
	owners := &deliveryOwner{}
	var asked []string
	owners.ask = func(_ context.Context, repo string) (*store.Installation, error) {
		asked = append(asked, repo)
		if repo == "acme/widgets" {
			return a, nil
		}
		return b, nil
	}
	for _, repo := range []string{"acme/widgets", "acme/widgets", "other/gadgets", "other/gadgets", "acme/widgets"} {
		want := a
		if repo == "other/gadgets" {
			want = b
		}
		if got, err := owners.of(context.Background(), repo); err != nil || got != want {
			t.Fatalf("of(%q) = %v, %v; want %s", repo, got, err, want.ID)
		}
	}
	if want := []string{"acme/widgets", "other/gadgets", "acme/widgets"}; !slices.Equal(asked, want) {
		t.Errorf("the store was asked about %v; want %v", asked, want)
	}
}

package controller

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"strings"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

// maxWebhookBody caps an inbound delivery. GitHub's own limit is 25 MB, but a
// workflow_job payload is tens of kilobytes; anything approaching this is
// either not from GitHub or not something Zoomies should be parsing. The body
// is read into memory before its signature can be checked -- the repository in
// it chooses the secret -- so this is what one request on a public endpoint
// costs the controller whoever sends it, and a megabyte is still some twenty
// times the largest delivery the fleet acts on.
const maxWebhookBody = 1 << 20

// What a delivery is allowed to say about itself before its signature has been
// checked.
//
// Everything below is read off an unauthenticated request: two headers, and
// three fields of a body that is parsed before verification because the
// repository is what chooses the secret. All of it is then written down --
// a database row that is kept, a line in the log, and a frame on the event
// stream every watching browser holds in memory -- because a rejected delivery
// is worth recording. Unbounded, that is an open invitation: a megabyte of
// "repository.full_name" per request, from anyone who can reach the endpoint,
// with no credential of any kind.
//
// The real values are far smaller. A GitHub repository's full name cannot
// exceed 100 characters either side of the slash, a delivery ID is a UUID, and
// an event name and an action are single words. These leave room and still
// bound the cost.
const (
	maxDeliveryRepo   = 256
	maxDeliveryAction = 64
	maxDeliveryID     = 64
	maxDeliveryEvent  = 64
)

// probeKey is who a rejected delivery is counted against: the address it came
// from, without its port, since a prober gets a new port every connection.
func probeKey(r *http.Request) string {
	host, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		return r.RemoteAddr
	}
	return host
}

// clampField bounds one such value. It reports what was cut rather than
// truncating silently, so an operator reading the row sees a probe for what it
// is instead of a repository name that looks merely unfamiliar.
func clampField(s string, max int) string {
	if len(s) <= max {
		return s
	}
	return s[:max] + fmt.Sprintf("... (%d bytes, truncated)", len(s))
}

// HandleWebhook is the endpoint GitHub delivers to, mounted by the API at
// config.GitHub.WebhookPath.
//
// It answers quickly on purpose. GitHub gives a webhook ten seconds before it
// records the delivery as failed, so this verifies, writes one row and returns;
// the scheduling it triggers happens on the reconcile loop, which nothing here
// waits for.
func (c *Controller) HandleWebhook(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()

	if r.Method != http.MethodPost {
		w.Header().Set("Allow", http.MethodPost)
		http.Error(w, "webhook deliveries are POSTed; this endpoint accepts nothing else", http.StatusMethodNotAllowed)
		return
	}

	event := clampField(github.ParseEventType(r.Header.Get(github.EventTypeHeader)), maxDeliveryEvent)
	d := &store.WebhookDelivery{
		DeliveryID: clampField(r.Header.Get(github.DeliveryIDHeader), maxDeliveryID),
		Event:      event,
	}

	// A delivery with no signature header cannot verify, so it is refused
	// before its body is read: reading, parsing and checking a body against
	// every installation's secret is the expensive part of this handler, and
	// it is the part a probe of the endpoint would otherwise get for free.
	// The refusal is recorded through the same bounded path as a delivery
	// whose signature was wrong, so a burst of them is still visible.
	signature := r.Header.Get(github.SignatureHeader)
	if strings.TrimSpace(signature) == "" {
		c.rejectDelivery(ctx, w, r, d, event, "",
			fmt.Errorf("the delivery carries no %s header, so it cannot have come from GitHub with the webhook secret Zoomies holds", github.SignatureHeader))
		return
	}

	body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxWebhookBody))
	if err != nil {
		c.recordDelivery(ctx, d, "error", fmt.Sprintf("could not read the delivery body (limit %d bytes): %v", maxWebhookBody, err))
		http.Error(w, fmt.Sprintf("the delivery body could not be read, or was larger than %d MiB", maxWebhookBody>>20), http.StatusRequestEntityTooLarge)
		return
	}

	// The envelope is read before the signature is checked, because the
	// repository is what selects the secret to check the signature with.
	// Nothing from it is acted on until the signature verifies.
	env := parseEnvelope(body)
	d.Repo, d.Action = env.Repo, env.Action

	owners := c.newDeliveryOwner()
	inst, note, err := c.verifyDelivery(ctx, body, signature, env.Repo, owners)
	if err != nil {
		c.rejectDelivery(ctx, w, r, d, event, env.Repo, err)
		return
	}

	// A delivery that verified proves webhooks reach this controller.
	c.pollingOnly.Store(false)
	d.InstallationID = installationID(inst)

	switch {
	case github.IsPing(event):
		c.recordDelivery(ctx, d, "accepted", note)
		c.log.Info("GitHub's webhook ping arrived; deliveries can reach this controller",
			"installation", installationID(inst), "repo", env.Repo)
		writeJSON(w, http.StatusOK, map[string]any{
			"ok":      true,
			"message": "Zoomies received the ping; webhook delivery to this controller works",
		})
	case event == "workflow_job":
		if err := c.handleWorkflowJob(ctx, body, owners); err != nil {
			if errors.Is(err, errMalformedDelivery) {
				// A body that verified but is not a workflow_job event is
				// GitHub's problem or a mistaken sender's, not a failure on
				// this side, and a 500 would have GitHub redeliver it for
				// ever. A 400 is recorded and ends there.
				c.recordDelivery(ctx, d, "rejected", err.Error())
				c.log.Warn("rejected a workflow_job delivery that could not be read", "delivery", d.DeliveryID, "error", err)
				http.Error(w, "the delivery body is not a workflow_job event this controller can read", http.StatusBadRequest)
				return
			}
			c.recordDelivery(ctx, d, "error", err.Error())
			c.log.Error("could not apply a workflow_job delivery", "delivery", d.DeliveryID, "error", err)
			// A 500 makes GitHub's redelivery button useful: this one failed
			// on our side and is worth sending again.
			http.Error(w, "the delivery could not be processed", http.StatusInternalServerError)
			return
		}
		if err := c.enqueueRepairWebhook(ctx, inst, event, body); err != nil {
			c.recordDelivery(ctx, d, "error", err.Error())
			http.Error(w, "the repair request could not be queued", http.StatusInternalServerError)
			return
		}
		c.recordDelivery(ctx, d, "accepted", note)
		w.WriteHeader(http.StatusAccepted)
	case event == "issue_comment":
		if err := c.enqueueRepairWebhook(ctx, inst, event, body); err != nil {
			c.recordDelivery(ctx, d, "error", err.Error())
			http.Error(w, "the repair request could not be queued", http.StatusInternalServerError)
			return
		}
		c.recordDelivery(ctx, d, "accepted", note)
		w.WriteHeader(http.StatusAccepted)
	default:
		// Zoomies subscribes to workflow_job only; anything else is recorded
		// so the delivery log explains what is arriving and ignored.
		c.recordDelivery(ctx, d, "accepted", note)
		writeJSON(w, http.StatusOK, map[string]any{
			"ok":      true,
			"message": fmt.Sprintf("Zoomies does not act on %q events; supported events are workflow_job and issue_comment", event),
		})
	}
}

// envelope is the part of any delivery that routes it, read before the
// signature has been checked.
type envelope struct {
	Repo           string
	Action         string
	InstallationID int64
}

func parseEnvelope(body []byte) envelope {
	var p struct {
		Action     string `json:"action"`
		Repository struct {
			FullName string `json:"full_name"`
		} `json:"repository"`
		Organization struct {
			Login string `json:"login"`
		} `json:"organization"`
		// The installation GitHub says sent this. It is read for the record
		// only: it is GitHub's numeric identifier rather than the store's, and
		// a delivery asserting which installation it belongs to would be the
		// delivery choosing its own scope. The repository decides instead.
		Installation struct {
			ID int64 `json:"id"`
		} `json:"installation"`
	}
	if err := json.Unmarshal(body, &p); err != nil {
		return envelope{}
	}
	repo := p.Repository.FullName
	if repo == "" {
		// A ping for an org-wide App carries no repository, but the org is
		// enough to find the installation that should have signed it.
		repo = p.Organization.Login
	}
	return envelope{
		Repo:           clampField(repo, maxDeliveryRepo),
		Action:         clampField(strings.ToLower(strings.TrimSpace(p.Action)), maxDeliveryAction),
		InstallationID: p.Installation.ID,
	}
}

// rejectDelivery answers a delivery that could not be verified, and records it
// within bounds.
//
// A burst of these means somebody is probing the endpoint, which is why they
// are written down rather than only counted -- but written down is what costs,
// so one address gets a bounded number of them.
//
// The limit is on the rejected path alone, deliberately. GitHub sends in bursts
// from a range of addresses and a real delivery has a valid signature, so
// nothing that verifies is ever slowed by this; only something that could not
// have come from GitHub is. Rate-limiting the endpoint itself would throttle
// the deliveries the fleet scales on.
//
// The refusal is unchanged either way: what is dropped is the record, not the
// rejection.
func (c *Controller) rejectDelivery(ctx context.Context, w http.ResponseWriter, r *http.Request, d *store.WebhookDelivery, event, repo string, err error) {
	if c.webhookProbes.Allow(probeKey(r)) {
		c.recordDelivery(ctx, d, "rejected", err.Error())
		c.log.Warn("rejected a webhook delivery",
			"delivery", d.DeliveryID, "event", event, "repo", repo, "reason", err)
	} else {
		c.metrics.webhookDeliveries.WithLabelValues("rejected").Inc()
	}
	http.Error(w, "the delivery signature could not be verified", http.StatusUnauthorized)
}

// verifyDelivery finds the secret this delivery should have been signed with
// and checks the signature in constant time (github.ValidateSignature uses
// hmac.Equal).
//
// The installation that owns the repository decides it. Only when no
// installation covers the repository at all -- which happens when a repository
// moved between organisations -- is every other configured secret tried, and
// the note that comes back says which one worked, because "your secrets are out
// of step with your installations" is a different problem from "this delivery
// was forged".
//
// The fallback is deliberately not reached when an owner exists and its secret
// fails. Every configured secret is held by somebody: on a controller serving
// two organisations, each one's GitHub admin pasted their own. Trying them all
// against a delivery that names somebody else's repository let the holder of
// one organisation's secret sign a workflow_job for another's, and be believed
// -- the job is then scheduled on the named repository's pools and a runner is
// registered in its organisation with its own App credentials. Nor did the
// wider net ever help the case it was written for: a stale secret for this
// installation cannot be recovered by matching a different installation's.
func (c *Controller) verifyDelivery(ctx context.Context, body []byte, signature, repo string, owners *deliveryOwner) (*store.Installation, string, error) {
	var firstErr error

	var owner *store.Installation
	if repo != "" {
		if inst, err := owners.of(ctx, repo); err == nil {
			owner = inst
			secret, serr := c.unsealString(inst.WebhookSecretEnc, "webhook secret for installation "+inst.ID)
			if serr != nil {
				firstErr = serr
			} else if err := github.ValidateSignature(body, signature, secret); err != nil {
				firstErr = err
			} else {
				return inst, "", nil
			}
		}
	}

	// An owner that did not verify is the end of it. Anything further would be
	// checking this delivery against a secret its own repository's installation
	// does not use.
	if owner != nil {
		if firstErr != nil {
			return nil, "", firstErr
		}
		return nil, "", fmt.Errorf("installation %s covers %q, and this delivery was not signed with its webhook secret",
			owner.ID, repo)
	}

	insts, err := c.st.ListInstallations(ctx)
	if err != nil {
		return nil, "", fmt.Errorf("could not read the configured installations to verify this delivery: %w", err)
	}
	tried := 0
	for _, inst := range insts {
		secret, serr := c.unsealString(inst.WebhookSecretEnc, "webhook secret for installation "+inst.ID)
		if serr != nil || secret == "" {
			continue
		}
		tried++
		if err := github.ValidateSignature(body, signature, secret); err == nil {
			return inst, fmt.Sprintf("no installation covers %q, so this delivery was verified with the webhook secret of installation %s (%s)",
				repo, inst.ID, inst.Target), nil
		}
	}

	if firstErr != nil {
		return nil, "", firstErr
	}
	if len(insts) == 0 {
		return nil, "", errors.New("this controller has no GitHub App installation configured, so it holds no webhook secret to verify deliveries with; add one on the Installations page")
	}
	return nil, "", fmt.Errorf("no installation covers %q and none of the %d configured webhook secrets verified this delivery; "+
		"check that the App's webhook secret matches the one Zoomies holds", repo, tried)
}

// installationCovering is the store's answer to which installation covers a
// repository, unless a test has put its own in the way.
func (c *Controller) installationCovering(ctx context.Context, repo string) (*store.Installation, error) {
	if c.findInstallation != nil {
		return c.findInstallation(ctx, repo)
	}
	return c.st.FindInstallationByTarget(ctx, repo)
}

// deliveryOwner remembers which installation covers a repository for the length
// of one delivery. Verifying a delivery asks, to find the secret its signature
// was made with, and applying the job asks, to say which installation it belongs
// to: the same question about the same repository a few hundred microseconds
// apart, and in a profile about 3% of a delivery for each asking.
//
// Only an answer is kept, as the poller's repoOwners keeps only an answer: an
// installation, or that none covers the repository. A lookup that failed for any
// other reason says nothing about the repository, so the next question goes to
// the store, as both always did. It is for one delivery on one goroutine, and it
// remembers one repository, because a delivery names one; a question about
// another goes to the store.
type deliveryOwner struct {
	ask     func(ctx context.Context, repo string) (*store.Installation, error)
	repo    string
	inst    *store.Installation // nil once settled means no installation covers repo
	settled bool
}

func (c *Controller) newDeliveryOwner() *deliveryOwner {
	return &deliveryOwner{ask: c.installationCovering}
}

// of is the installation covering repo, or an error wrapping store.ErrNotFound
// when none does.
func (o *deliveryOwner) of(ctx context.Context, repo string) (*store.Installation, error) {
	if o.settled && o.repo == repo {
		if o.inst == nil {
			return nil, store.ErrNotFound
		}
		return o.inst, nil
	}
	inst, err := o.ask(ctx, repo)
	switch {
	case err == nil:
		o.repo, o.inst, o.settled = repo, inst, true
	case errors.Is(err, store.ErrNotFound):
		o.repo, o.inst, o.settled = repo, nil, true
	}
	return inst, err
}

// handleWorkflowJob is the path that actually scales the fleet.
// errMalformedDelivery marks a verified delivery whose body is not a
// workflow_job event, which is answered with a 400 rather than a 500 so that
// GitHub does not redeliver it for ever.
var errMalformedDelivery = errors.New("malformed workflow_job delivery")

func (c *Controller) handleWorkflowJob(ctx context.Context, body []byte, owners *deliveryOwner) error {
	e, err := github.ParseWorkflowJob(body)
	if err != nil {
		return fmt.Errorf("%w: %v", errMalformedDelivery, err)
	}
	return c.applyWorkflowJob(ctx, e, sourceWebhook, owners)
}

// applyWorkflowJob gives polling and webhooks the same monotonic state updates.
// owners is what the delivery has already learned about which installation
// covers its repository, or nil for a caller that has learned nothing.
func (c *Controller) applyWorkflowJob(ctx context.Context, e *github.WorkflowJobEvent, source string, owners *deliveryOwner) error {
	job := e.ToJob()
	if owners == nil {
		owners = c.newDeliveryOwner()
	}

	// Which installation owns this work is the job's repository's question,
	// not the delivery's. Verification deliberately falls back to any secret
	// that answers, so the installation that signed a delivery may be one that
	// has nothing to do with the repository named in it; scoping the job by
	// that would mint runners in the wrong GitHub target. A repository no
	// installation covers is recorded with none, and the eligibility rule says
	// so rather than the delivery being rejected.
	if owner, err := owners.of(ctx, job.Repo); err == nil {
		job.InstallationID = owner.ID
	} else if !errors.Is(err, store.ErrNotFound) {
		return fmt.Errorf("resolving the installation covering %s: %w", job.Repo, err)
	}

	// Which pool claims this job is decided here rather than at reconcile time
	// so that "no pool wants this job" is visible on the Jobs page the moment
	// it arrives, instead of only in a scheduler decision nobody is watching.
	//
	// Only what a claim reads of each pool is read, and the pools are used for
	// nothing else here but naming a job's pool, in the frame published for it
	// and in the histogram's labels: see ListPoolsForClaim.
	claimable, err := c.st.ListPoolsForClaim(ctx)
	if err != nil {
		return fmt.Errorf("listing pools to match job %d: %w", e.JobID, err)
	}
	// The class comes first, because the claim below is made for it: a job sent
	// to the large pool has to be claimed by the large pool at the door, or its
	// row names one pool and the scheduler feeds another.
	classing := c.sizeOnArrival(ctx, job, claimable)
	if p := c.bestPool(claimable, job); p != nil {
		job.PoolID = p.ID
		job.Matched = true
	}

	var runner *store.Runner
	if e.RunnerName != "" {
		if r, err := c.st.GetRunnerByName(ctx, e.RunnerName); err == nil {
			job.RunnerID = r.ID
			runner = r
		}
	}

	saved, change, err := c.st.ApplyJob(ctx, job)
	if err != nil {
		return fmt.Errorf("recording job %d: %w", e.JobID, err)
	}
	saved = c.stampSize(ctx, saved, classing)
	if saved.RunNumber == 0 && saved.GitHubRunID > 0 {
		if n, err := c.st.RunNumberForRun(ctx, saved.GitHubRunID); err == nil {
			c.recordRunNumber(ctx, saved, n)
		}
	}
	// A recovery response may omit runner_name even though the earlier
	// in-progress event linked this job. Use the durable link as the fallback,
	// or a completed job can still miss its runner cleanup.
	if runner == nil && saved.RunnerID != "" {
		if r, err := c.st.GetRunner(ctx, saved.RunnerID); err == nil {
			runner = r
		}
	}
	if change.Created || change.StateChanged {
		c.placementVersion.Add(1)
		c.placement.Store(nil)
	}
	c.recordJobChange(ctx, saved, change, source, runner)
	if saved.StartedAt != nil && (change.Created || change.StateChanged) && change.PreviousState != store.JobInProgress {
		poolName, backendName := UnmatchedPool, "unknown"
		if p := poolIn(claimable, saved.PoolID); p != nil {
			poolName, backendName = p.Name, string(p.Backend)
		} else if saved.PoolID != "" {
			if p, e := c.st.GetPool(ctx, saved.PoolID); e == nil {
				poolName, backendName = p.Name, string(p.Backend)
			}
		}
		observeDuration(c.metrics.queuedToStarted, poolName, backendName, saved.QueuedAt, *saved.StartedAt)
	}

	if runner != nil {
		switch saved.State {
		case store.JobInProgress:
			// GitHub's start is authoritative, like its completion below: it
			// means the runner registered and took the job, whatever the row
			// still says. Linked and taken busy in one statement, because the
			// runner read at the top of this handler is already several writes
			// old by the time it gets here -- long enough for the agent's
			// create result to land in between and for a check made against
			// that copy to refuse provisioning -> busy on a row that had since
			// reached registering.
			started, changed, err := c.st.StartRunnerJob(ctx, runner.ID, saved.ID,
				fmt.Sprintf("running %s / %s", saved.Workflow, saved.JobName))
			if err != nil {
				c.log.Warn("could not start a runner on the job GitHub says is running on it",
					"runner", runner.ID, "job", saved.ID, "error", err)
			} else if changed {
				c.observeRunnerReady(ctx, started)
				c.publishRunner(ctx, events.KindRunnerUpdated, started)
			}
		case store.JobCompleted:
			// GitHub's completion is authoritative. An ephemeral runner normally
			// exits and is reported gone by its agent, but relying on that second
			// observation alone leaves the row busy forever when one report is
			// missed. Release it atomically and explicitly remove its workload.
			finished, changed, err := c.st.CompleteRunnerJob(ctx, runner.ID, saved.ID, "finished "+saved.JobName)
			if err != nil {
				c.log.Warn("could not release a runner from its completed job",
					"runner", runner.ID, "job", saved.ID, "error", err)
			} else if changed {
				c.publishRunner(ctx, events.KindRunnerUpdated, finished)
				if finished.Ephemeral {
					c.enqueueLifecycle(ctx, finished.HostID, agent.Task{
						Kind: agent.TaskRemoveRunner, RunnerID: finished.ID,
						Backend: c.backendKind(ctx, finished, nil),
					})
					c.Nudge()
				}
			}
			if change.Created || change.StateChanged {
				c.observeJobCompletion(saved)
			}
		}
	} else if saved.State == store.JobCompleted && (change.Created || change.StateChanged) {
		c.observeJobCompletion(saved)
	}

	// Run metadata and cancellation verification can wait; the job event cannot.
	if saved.GitHubRunID > 0 && saved.InstallationID != "" && (saved.RunNumber == 0 || saved.State == store.JobCompleted && saved.Conclusion == "cancelled") {
		if err := c.st.QueueEnrichment(ctx, "job", saved.ID); err != nil {
			return err
		}
	}

	if !saved.Matched && saved.State == store.JobQueued && !hostedJob(saved.Labels) {
		// Not a warning: next to another runner provider this is every one of
		// its jobs. The problems drawer says so once the job has waited long
		// enough to mean something.
		c.log.Info("no enabled pool here claims a queued job; if it is meant for this fleet, its labels match no pool",
			"job", saved.ID, "repo", saved.Repo, "labels", strings.Join(saved.Labels, ","))
	}

	c.publishJobIn(ctx, saved, claimable)
	// Wake the reconcile loop rather than scheduling inline: GitHub is holding
	// this connection open, and a reconcile can take as long as GitHub's API
	// does to answer.
	c.Nudge()
	return nil
}

// recordRunNumber writes a run's number to every job of the run that lacks
// one, the job in hand included.
func (c *Controller) recordRunNumber(ctx context.Context, saved *store.Job, n int64) {
	saved.RunNumber = n
	if err := c.st.SetRunNumberForRun(ctx, saved.Repo, saved.GitHubRunID, n); err != nil {
		c.log.Warn("could not record a workflow run's number on its jobs",
			"job", saved.ID, "run", saved.GitHubRunID, "error", err)
	}
}

// observeJobCompletion feeds the histograms the Overview's percentiles and the
// Prometheus endpoint are built from.
func (c *Controller) observeJobCompletion(j *store.Job) {
	pool := c.poolLabel(j.PoolID)
	conclusion := j.Conclusion
	if conclusion == "" {
		conclusion = "unknown"
	}
	c.metrics.jobsTotal.WithLabelValues(pool, conclusion).Inc()
	// The fleet's own half is counted when the fault is recorded, which
	// happens before GitHub closes the job and sometimes long before. Counting
	// it again here would double every runner that died mid-job.
	if j.WorkflowFailed() {
		c.metrics.jobFailures.WithLabelValues(pool, store.FaultDomainWorkflow, "").Inc()
	}
	if w := j.QueueWait(); w > 0 {
		c.metrics.queueWait.Observe(w.Seconds())
	}
	if d := j.Duration(); d > 0 {
		c.metrics.jobDuration.Observe(d.Seconds())
	}
	// Recorded once, when the job ends, because the counters only climb while
	// it runs; observing every sample would count the same job repeatedly.
	if share, ok := j.Throttled(); ok {
		c.metrics.jobCPUThrottled.WithLabelValues(pool).Observe(share)
	}
}

// recordDelivery writes one delivery down and tells the UI about it. Every
// delivery is recorded, accepted or not: a run of rejections is how an
// operator sees that something is probing the endpoint or that a secret has
// drifted.
//
// errMsg doubles as a note on an accepted delivery -- the store has one free
// text column and "this verified against a different installation's secret" is
// exactly the sort of thing the delivery log exists to say.
func (c *Controller) recordDelivery(ctx context.Context, d *store.WebhookDelivery, status, errMsg string) {
	d.Status = status
	d.Error = errMsg
	if d.ReceivedAt.IsZero() {
		d.ReceivedAt = c.Now()
	}
	// The request's context is cancelled the moment the response is written,
	// which must not take the row with it.
	if err := c.st.RecordDelivery(context.WithoutCancel(ctx), d); err != nil {
		c.log.Error("could not record a webhook delivery", "delivery", d.DeliveryID, "error", err)
	}
	c.metrics.webhookDeliveries.WithLabelValues(status).Inc()
	c.publish(events.KindWebhook, "webhook:"+d.ID, d)
}

func installationID(inst *store.Installation) string {
	if inst == nil {
		return ""
	}
	return inst.ID
}

// writeJSON is the one response helper this package needs; the API package has
// its own for everything else.
func writeJSON(w http.ResponseWriter, status int, body any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(body)
}

package controller

import (
	"bytes"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

// This is the product's core promise: a job is queued on GitHub, and a runner
// appears on a host to run it.
func TestQueuedJobWebhookProducesARunnerAndACreateTask(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()

	rec := h.deliverJob(jobEvent{
		Action: "queued", JobID: 1001, RunID: 5001,
		Name: "build", Workflow: "CI",
		Labels: []string{"self-hosted", "linux", "x64", "demo"},
	})
	if rec.Code != http.StatusAccepted {
		t.Fatalf("webhook status = %d, want %d (%s)", rec.Code, http.StatusAccepted, rec.Body.String())
	}

	job, err := h.st.GetJobByGitHubID(h.ctx, 1001)
	if err != nil {
		t.Fatalf("the delivery did not produce a job row: %v", err)
	}
	if job.State != store.JobQueued || !job.Matched || job.PoolID != pool.ID {
		t.Fatalf("job = %+v, want queued and matched to pool %s", job, pool.ID)
	}

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	h.c.lifecycleCalls.Wait()

	r := h.onlyRunner()
	if r.State != store.RunnerProvisioning {
		t.Fatalf("runner state = %q, want %q", r.State, store.RunnerProvisioning)
	}
	if r.HostID != host.ID || r.PoolID != pool.ID {
		t.Fatalf("runner placed on host %s in pool %s, want %s/%s", r.HostID, r.PoolID, host.ID, pool.ID)
	}
	if !store.IsRunnerName(r.Name) {
		t.Fatalf("runner name %q does not carry the %q prefix", r.Name, store.RunnerNamePrefix)
	}
	if r.GitHubRunnerID == 0 {
		t.Fatal("the runner has no GitHub runner ID, so no JIT config was minted for it")
	}

	task := h.taskOfKind(host.ID, agent.TaskCreateRunner)
	if task.RunnerID != r.ID {
		t.Fatalf("create task is for runner %s, want %s", task.RunnerID, r.ID)
	}
	if task.Spec == nil || task.Spec.Credentials.JITConfig == "" {
		t.Fatal("the create task carries no JIT configuration, so the agent could not register the runner")
	}
	if task.Spec.Name != r.Name || task.Backend != pool.Backend {
		t.Fatalf("spec = %+v, want name %s on the %s backend", task.Spec, r.Name, pool.Backend)
	}
	if task.Spec.PullPolicy != pool.PullPolicy {
		t.Fatalf("create task pull policy = %q, want pool policy %q", task.Spec.PullPolicy, pool.PullPolicy)
	}
}

