import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/installer"
)

// TestTheControllerOnlyAnswersTemplateIsAWholeUnattendedInstall holds the
// committed template to what it claims to be.
//
// A provisioner copies this file and changes the example values; it does not
// read the installer to find out which keys it forgot. So the template has to
// load with the installer's own strict reader, leave nothing the installer
// would stop to ask for, and keep the choices that make it controller-only --
// and it must never carry a password inline, because the file is exactly the
// thing that ends up in a repository.
func TestTheControllerOnlyAnswersTemplateIsAWholeUnattendedInstall(t *testing.T) {
	path := filepath.Join(marketplaceDir, "controller-answers.yaml")
	a, err := installer.Load(path)
	if err != nil {
		t.Fatalf("the installer cannot read the template: %v", err)
	}
	mode, err := installer.ParseMode(a.Mode)
	if err != nil {
		t.Fatalf("the template's mode: %v", err)
	}
	if mode != installer.ModeController {
		t.Errorf("the template is mode %q; a controller-only instance runs no embedded agent", a.Mode)
	}
	if err := a.Validate(mode); err != nil {
		t.Errorf("the template leaves questions unanswered:\n%v", err)
	}

	checks := []struct {
		ok   bool
		what string
	}{
		{a.GitHub.Skip, "github.skip, so an install needs no App credentials"},
		{a.Pool.Skip, "pool.skip, since a controller with no agent has no runners for a pool"},
		{a.TLS.Mode == "files" && a.TLS.CertFile != "" && a.TLS.KeyFile != "", "TLS from files"},
		{strings.HasPrefix(a.ExternalURL, "https://"), "an https external URL"},
		{a.Admin.Username != "" && a.Admin.PasswordFile != "", "a first account whose password comes from a file"},
		{a.Admin.Password == "", "no inline password"},
	}
	for _, c := range checks {
		if !c.ok {
			t.Errorf("the template does not set %s", c.what)
		}
	}

	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("reading the template: %v", err)
	}
	if !strings.Contains(string(raw), "ZOOMIES_BOOTSTRAP_") {
		t.Error("the template does not point a containerised install at the bootstrap variables")
	}
}

package docs

import (
	"os"
	"regexp"
	"sort"
	"strings"
	"testing"
)

// docs/dependencies.md promises that every dependency carries a one-line
// reason, and until this test that was kept by review alone. It slipped twice:
// a direct module that only a test imports had no row, and a row went on naming
// a version two releases after go.mod had moved on. The doc is the place an
// owner decides whether a module still earns its keep, so it has to list the
// modules that are there and none that are gone.
//
// Only the Go table is checked. The UI's rows group packages that ship together
// (`@xterm/xterm` with its addons), which a name-for-name comparison would
// misread, and a row for a package that was dropped is caught by review of the
// change that dropped it.
const dependenciesDoc = "../../docs/dependencies.md"

var (
	// One module path at the start of a table row's first cell.
	dependencyRow = regexp.MustCompile("(?m)^\\| `([^`]+)` \\|")
	// One requirement inside a require block, or a single-line require: the
	// module path, the version, and the marker that says the module is
	// indirect.
	requirement = regexp.MustCompile(`^\s*(?:require\s+)?(\S+)\s+(v\S+?)(\s+//\s*indirect)?\s*$`)
)

func TestEveryDirectGoModuleHasARowInTheDependenciesPage(t *testing.T) {
	direct, all := goModules(t)
	page, err := os.ReadFile(dependenciesDoc)
	if err != nil {
		t.Fatalf("reading %s: %v", dependenciesDoc, err)
	}
	goTable := section(string(page), "## Go", "## ")
	rows := map[string]bool{}
	for _, m := range dependencyRow.FindAllStringSubmatch(goTable, -1) {
		rows[m[1]] = true
	}
	if len(rows) == 0 {
		t.Fatal("no rows were found under the Go heading of docs/dependencies.md; the page changed shape")
	}

	var missing, gone []string
	for module := range direct {
		if !rows[module] {
			missing = append(missing, module)
		}
	}
	for row := range rows {
		if !all[row] {
			gone = append(gone, row)
		}
	}
	sort.Strings(missing)
	sort.Strings(gone)
	if len(missing) > 0 {
		t.Errorf("go.mod requires these directly and docs/dependencies.md gives no reason for them; add a row saying why each earns its place:\n  %s",
			strings.Join(missing, "\n  "))
	}
	if len(gone) > 0 {
		t.Errorf("docs/dependencies.md has rows for modules go.mod no longer requires; remove them with the code that stopped using them:\n  %s",
			strings.Join(gone, "\n  "))
	}
}

// goModules returns every module go.mod requires directly, and every one it
// requires at all.
func goModules(t *testing.T) (direct, all map[string]bool) {
	t.Helper()
	direct, all = map[string]bool{}, map[string]bool{}
	for _, m := range requirementLines(t) {
		all[m[1]] = true
		if m[3] == "" {
			direct[m[1]] = true
		}
	}
	if len(direct) == 0 {
		t.Fatal("no direct requirements were found in go.mod; the test is reading it wrongly")
	}
	return direct, all
}

// requirementLines returns every requirement go.mod states, in the order it
// states them. The block structure is read as well as the lines, so a comment
// that looks like a requirement is not taken for one.
func requirementLines(t *testing.T) [][]string {
	t.Helper()
	body, err := os.ReadFile("../../go.mod")
	if err != nil {
		t.Fatalf("reading go.mod: %v", err)
	}
	var found [][]string
	inBlock := false
	for _, line := range strings.Split(string(body), "\n") {
		trimmed := strings.TrimSpace(line)
		switch {
		case strings.HasPrefix(trimmed, "require ("):
			inBlock = true
			continue
		case inBlock && trimmed == ")":
			inBlock = false
			continue
		case !inBlock && !strings.HasPrefix(trimmed, "require "):
			continue
		}
		m := requirement.FindStringSubmatch(line)
		if m == nil {
			continue
		}
		found = append(found, m)
	}
	return found
}

// moduleVersion returns the version go.mod requires directly for a module.
func moduleVersion(t *testing.T, name string) string {
	t.Helper()
	for _, m := range requirementLines(t) {
		if m[1] == name && m[3] == "" {
			return m[2]
		}
	}
	t.Fatalf("go.mod requires no direct module named %s; the test is reading it wrongly", name)
	return ""
}

// rowFor returns the row a module has in the Go table of the dependencies
// page, or the empty string when it has none.
func rowFor(text, module string) string {
	for _, line := range strings.Split(section(text, "## Go", "## "), "\n") {
		if strings.HasPrefix(line, "| `"+module+"` |") {
			return line
		}
	}
	return ""
}

// The tailscale.com pin rides a pre-release channel, and a pin on that
// channel brings a module graph with it: the version names one module, and the
// hundred and thirty indirect ones arrive alongside it. Nothing in the
// pipeline sees that arrival, because govulncheck and osv-scanner read what
// is there, not what arrived, so the row in docs/dependencies.md is the one
// place an owner defends the pin. It has to name the channel and the rule, or
// a bump can change the graph without anybody being asked about it.
func TestTheTailscalePinNamesItsChannel(t *testing.T) {
	version := moduleVersion(t, "tailscale.com")
	if !strings.Contains(version, "-pre") {
		// A stable tag is an owner decision that leaves no channel policy to
		// defend, so there is nothing for the row to have to say.
		return
	}
	page, err := os.ReadFile(dependenciesDoc)
	if err != nil {
		t.Fatalf("reading %s: %v", dependenciesDoc, err)
	}
	row := rowFor(string(page), "tailscale.com")
	if row == "" {
		t.Fatalf("docs/dependencies.md has no row for tailscale.com; the page changed shape")
	}
	// The row may be reworded as long as it keeps naming the channel and the
	// graph rule, so the test reads the two markers and not the wording.
	for _, marker := range []string{"pre-release", "changes what it pulls in says so"} {
		if !strings.Contains(row, marker) {
			t.Errorf("the tailscale.com row in docs/dependencies.md does not say %q; the pin rides the pre-release channel and carries a module graph with it, and that row is where an owner defends it:\n  %s",
				marker, row)
		}
	}
}

// section returns the text from the first line starting with start up to the
// next line starting with next, or to the end.
func section(text, start, next string) string {
	i := strings.Index(text, "\n"+start+"\n")
	if i < 0 {
		return ""
	}
	rest := text[i+1+len(start):]
	if j := strings.Index(rest, "\n"+next); j >= 0 {
		return rest[:j]
	}
	return rest
}

package docs

import (
	"os"
	"regexp"
	"strconv"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// The hint under a provider's Disk field does the provider check's arithmetic
// in the browser, from copies of two Go constants. A change to one side alone
// would have the form tell an operator a disk is enough and the check warn
// that it is not, so the copies are held to the originals here.
func TestTheDiskHintsFiguresMatchTheSchedulersAndTheStores(t *testing.T) {
	src, err := os.ReadFile("../../web/src/lib/providers/recommend.ts")
	if err != nil {
		t.Fatal(err)
	}
	for _, tc := range []struct {
		name string
		want int64
		from string
	}{
		{"RUNNER_DISK_MB", scheduler.RunnerDiskMB, "scheduler.RunnerDiskMB"},
		{"HOST_RESERVE_DISK_FLOOR_MB", store.MinHostReserveDiskMB, "store.MinHostReserveDiskMB"},
	} {
		got, ok := tsConstantProduct(string(src), tc.name)
		if !ok {
			t.Errorf("web/src/lib/providers/recommend.ts has no `export const %s = <whole number, or a product of them>;`", tc.name)
			continue
		}
		if got != tc.want {
			t.Errorf("web/src/lib/providers/recommend.ts sets %s to %d MB and %s is %d MB; change both together", tc.name, got, tc.from, tc.want)
		}
	}
}

// tsConstantProduct reads `export const NAME = 10 * 1024;` and the like: whole
// numbers multiplied together, which is all these constants are written as.
func tsConstantProduct(src, name string) (int64, bool) {
	m := regexp.MustCompile(`(?m)^export const ` + regexp.QuoteMeta(name) + `\s*=\s*([0-9_*\s]+);`).FindStringSubmatch(src)
	if m == nil {
		return 0, false
	}
	product := int64(1)
	for _, factor := range strings.Split(m[1], "*") {
		n, err := strconv.ParseInt(strings.ReplaceAll(strings.TrimSpace(factor), "_", ""), 10, 64)
		if err != nil {
			return 0, false
		}
		product *= n
	}
	return product, true
}

package docs

import (
	"bufio"
	"bytes"
	"flag"
	"os"
	"path"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"testing"
	"unicode/utf8"
)

var updateDoubleHyphenBaseline = flag.Bool("update-double-hyphen-baseline", false,
	"rewrite testdata/double-hyphen-baseline.txt from the tree as it is now")

// AGENTS.md says a spaced double hyphen is not a dash either, and when this
// test was written about six thousand lines in the tree already used one as
// exactly that: four in five of them in code comments, written before the rule
// and copied by every contributor since, because the line above is the best
// evidence of what is allowed. Sweeping six thousand lines would bury the
// history of every file in one commit that nobody can review, so the rule is
// held the way a lint baseline is: a file may not gain more of them than it had.
// New prose and new comments follow the rule, the old ones go as the lines
// around them are rewritten, and `-update-double-hyphen-baseline` records the
// improvement so it cannot come back.
//
// A line counts when two hyphens stand between words with a space either side.
// What the pattern leaves alone is on purpose: a shell's end-of-options marker
// is followed by a flag, and a fenced block in Markdown is a command, not a
// sentence. The baseline also holds a few honest false positives (a shell
// script that resets its arguments with `set`), which is why it is a count for
// each file and not a list of lines.
var doubleHyphenDash = regexp.MustCompile(`\S -{2} [^-\s]`)

// doubleHyphenSkipped reports the files whose text nobody here chose. SQL
// writes its own comments with the two characters, and the validation records
// are appended by the drill and load jobs from whatever the fleet said.
func doubleHyphenSkipped(file string) bool {
	switch path.Base(file) {
	case "LICENSE", "package-lock.json", "go.sum":
		return true
	}
	return strings.HasSuffix(file, ".sql") || strings.HasPrefix(file, "roadmap/validation/")
}

const doubleHyphenBaseline = "testdata/double-hyphen-baseline.txt"

// countDoubleHyphens returns, for every tracked text file, how many of its
// lines use the pattern above, and for each file the first few line numbers so
// a failure can point at them.
func countDoubleHyphens(t *testing.T) (map[string]int, map[string][]int) {
	t.Helper()
	counts := map[string]int{}
	lines := map[string][]int{}
	for _, file := range trackedFiles(t) {
		if doubleHyphenSkipped(file) {
			continue
		}
		info, err := os.Stat("../../" + file)
		if err != nil || !info.Mode().IsRegular() || info.Size() > 4<<20 {
			continue // deleted but not yet committed, a symlink, or a bundle
		}
		body, err := os.ReadFile("../../" + file)
		if err != nil || bytes.IndexByte(body, 0) >= 0 || !utf8.Valid(body) {
			continue
		}
		markdown := strings.HasSuffix(file, ".md")
		fenced := false
		for i, line := range strings.Split(string(body), "\n") {
			if markdown && strings.HasPrefix(strings.TrimSpace(line), "```") {
				fenced = !fenced
				continue
			}
			if fenced || !doubleHyphenDash.MatchString(line) {
				continue
			}
			counts[file]++
			if len(lines[file]) < 3 {
				lines[file] = append(lines[file], i+1)
			}
		}
	}
	return counts, lines
}

func readDoubleHyphenBaseline(t *testing.T) map[string]int {
	t.Helper()
	f, err := os.Open(doubleHyphenBaseline)
	if err != nil {
		t.Fatalf("reading the baseline: %v; `go test ./internal/docs -run TestNoNewSpacedDoubleHyphenIsWrittenAsADash -update-double-hyphen-baseline` writes it", err)
	}
	defer f.Close()
	baseline := map[string]int{}
	sc := bufio.NewScanner(f)
	for n := 1; sc.Scan(); n++ {
		file, count, ok := strings.Cut(sc.Text(), "\t")
		c, err := strconv.Atoi(count)
		if !ok || err != nil {
			t.Fatalf("%s:%d is %q, want a path, a tab and a count", doubleHyphenBaseline, n, sc.Text())
		}
		baseline[file] = c
	}
	if err := sc.Err(); err != nil {
		t.Fatal(err)
	}
	return baseline
}

func TestNoNewSpacedDoubleHyphenIsWrittenAsADash(t *testing.T) {
	counts, lines := countDoubleHyphens(t)

	if *updateDoubleHyphenBaseline {
		files := make([]string, 0, len(counts))
		for file := range counts {
			files = append(files, file)
		}
		sort.Strings(files)
		var out strings.Builder
		for _, file := range files {
			out.WriteString(file + "\t" + strconv.Itoa(counts[file]) + "\n")
		}
		if err := os.WriteFile(doubleHyphenBaseline, []byte(out.String()), 0o644); err != nil {
			t.Fatal(err)
		}
		return
	}

	baseline := readDoubleHyphenBaseline(t)
	var files []string
	for file := range counts {
		files = append(files, file)
	}
	sort.Strings(files)
	for _, file := range files {
		if counts[file] <= baseline[file] {
			continue
		}
		nums := make([]string, len(lines[file]))
		for i, n := range lines[file] {
			nums[i] = strconv.Itoa(n)
		}
		t.Errorf("%s has %d lines that use a spaced `--` as a dash, up from %d; write the pause as a comma, a colon, a semicolon or parentheses, or split the sentence (the file has them at lines %s, among others). If the file was moved or renamed, `go test ./internal/docs -run TestNoNewSpacedDoubleHyphenIsWrittenAsADash -update-double-hyphen-baseline` carries its count over",
			file, counts[file], baseline[file], strings.Join(nums, ", "))
	}
}

// A row for a file that is no longer in the repository holds a count for
// nothing, and worse for the name: .jules/testsmith.md was recorded as
// .Jules/testsmith.md, and a row that names a path nobody will ever write again
// is one a new file of that name would inherit as an allowance. The ratchet
// itself still fails only on a gain, so a row that is merely higher than the
// file's count today is left alone (the next `-update-double-hyphen-baseline`
// lowers it); a row for a file that is gone is a mistake to be corrected.
func TestTheDoubleHyphenBaselineNamesNoFileThatIsGone(t *testing.T) {
	tracked := map[string]bool{}
	for _, file := range trackedFiles(t) {
		tracked[file] = true
	}
	var gone []string
	for file := range readDoubleHyphenBaseline(t) {
		if !tracked[file] {
			gone = append(gone, file)
		}
	}
	sort.Strings(gone)
	if len(gone) > 0 {
		t.Errorf("%s has rows for files that are not in the repository, perhaps because they were renamed or deleted:\n  %s\n"+
			"`go test ./internal/docs -run TestNoNewSpacedDoubleHyphenIsWrittenAsADash -update-double-hyphen-baseline` rewrites it from the tree as it is, or delete the rows by hand to leave every other count alone",
			doubleHyphenBaseline, strings.Join(gone, "\n  "))
	}
}

// The ratchet is only as good as the pattern under it, so the pattern is held
// to the cases that decided it.
func TestTheDoubleHyphenPatternSeparatesADashFromAnArgumentMarker(t *testing.T) {
	// The marker is spelt in pieces so that this file does not hold the
	// pattern it is testing.
	const dd = "--"
	for _, tc := range []struct {
		line string
		dash bool
	}{
		{"// the runner is gone " + dd + " the job is not", true},
		{"echo \"no such host " + dd + " try again\"", true},
		{"npm run build " + dd + " " + dd + "watch", false},
		{"git log " + dd + " path/to/file", true}, // indistinguishable from prose; the baseline absorbs it
		{dd + " a SQL comment at the start of a line", false},
		{"| " + dd + "- | " + dd + "- |", false},
		{"a range 1" + dd + "8 has no spaces", false},
		{"a trailing " + dd, false},
	} {
		if got := doubleHyphenDash.MatchString(tc.line); got != tc.dash {
			t.Errorf("%q: counted as a dash = %v, want %v", tc.line, got, tc.dash)
		}
	}
}

package docs_test

import (
	"os"
	"regexp"
	"strconv"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
)

// The validator judges scheduler.provision_timeout against how long a runner
// may take to start, and part of that is the wait the runner image does for its
// Docker daemon when runners.docker_wait leaves the choice to it. That default
// is written in the entrypoint, which is shell and cannot be imported, so
// config.ImageDockerWait restates it -- and a restated number drifts unless
// something reads both.
//
// Drift here is quiet in exactly the wrong way: the script would wait longer
// than the controller believed, so the controller would go on failing runners
// that were doing what the image told them to.
func TestTheImagesDockerWaitIsWhatTheValidatorBelieves(t *testing.T) {
	const script = "../../deploy/runner-entrypoint.sh"
	b, err := os.ReadFile(script)
	if err != nil {
		t.Fatalf("reading %s: %v", script, err)
	}
	m := regexp.MustCompile(`\$\{ZOOMIES_DOCKER_WAIT:-(\d+)\}`).FindSubmatch(b)
	if m == nil {
		t.Fatalf("%s no longer gives ZOOMIES_DOCKER_WAIT a default the way this test reads it; the two numbers cannot be held together by anything else", script)
	}
	secs, err := strconv.Atoi(string(m[1]))
	if err != nil {
		t.Fatalf("the default in %s is %q, which is not a number of seconds", script, m[1])
	}
	if got := time.Duration(secs) * time.Second; got != config.ImageDockerWait {
		t.Errorf("%s waits %s for the docker daemon but config.ImageDockerWait is %s; the provision timeout would be judged against a wait the image does not do",
			script, got, config.ImageDockerWait)
	}
}

package docs

import (
	"bufio"
	"os"
	"regexp"
	"sort"
	"strings"
	"testing"

	"gopkg.in/yaml.v3"

	"github.com/eyupio/zoomies/internal/config"
)

// envAssignment is a line of an env file that sets something: a name, an equals
// sign, and whatever follows. A commented-out line is not one, because nobody
// has set it.
var envAssignment = regexp.MustCompile(`^([A-Za-z_][A-Za-z0-9_]*)=(.*)$`)

// exampleEnv reads .env.example the way Compose reads the .env it becomes: each
// assignment is a variable the container is handed, an empty value included.
func exampleEnv(t *testing.T) map[string]string {
	t.Helper()
	f, err := os.Open("../../.env.example")
	if err != nil {
		t.Fatalf("reading the example env file: %v", err)
	}
	defer f.Close()

	env := map[string]string{}
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		m := envAssignment.FindStringSubmatch(strings.TrimSpace(sc.Text()))
		if m == nil {
			continue
		}
		value := strings.TrimSpace(m[2])
		if len(value) >= 2 && (value[0] == '"' || value[0] == '\'') && value[len(value)-1] == value[0] {
			value = value[1 : len(value)-1]
		} else if before, _, found := strings.Cut(value, " #"); found {
			value = strings.TrimSpace(before)
		}
		env[m[1]] = value
	}
	if err := sc.Err(); err != nil {
		t.Fatalf("reading the example env file: %v", err)
	}
	return env
}

// The first thing the Compose guide asks a new operator to do is copy this file
// to .env and fill in three values. Compose hands the container every line of
// it, empty ones as the empty string, so a line the controller refuses is a
// first run that exits before it has logged anything: ZOOMIES_AGENT_CAPACITY=
// was exactly that, promised to work and refused as `"" is not an integer`.
//
// The environment goes through config.Effective, which reads it the way the
// controller does at start, so the file can never ship a value the controller
// would not take.
func TestTheExampleEnvFileShipsNothingTheControllerRefuses(t *testing.T) {
	env := exampleEnv(t)
	for _, name := range []string{"ZOOMIES_EXTERNAL_URL", "ZOOMIES_AGENT_CAPACITY"} {
		if _, ok := env[name]; !ok {
			t.Fatalf("%s is not an assignment in .env.example; the test is reading the file wrongly", name)
		}
	}
	if _, _, err := config.Effective("", nil, nil, env); err != nil {
		t.Errorf(".env.example sets a value the controller refuses at start, so following the Compose guide fails on the first run:\n%v", err)
	}
}

// docs/upgrading.md tells an operator with this Compose file to run
// `zoomies config import-env < .env`, to move the settings in .env into the
// database. A refusal there is the same stopped first step as a refusal at
// start, and it stops every other setting moving with it.
func TestTheExampleEnvFileCanBeImportedIntoTheDatabase(t *testing.T) {
	if _, _, _, err := config.ImportEnvironment(exampleEnv(t), nil); err != nil {
		t.Errorf("`zoomies config import-env` refuses .env.example, so the documented way to move its settings into the database fails:\n%v", err)
	}
}

// bareInterpolation is a value that is nothing but a reference to a variable
// with no default and no demand that it be set. Compose renders it as the empty
// string when .env says NAME= and when .env does not mention NAME at all, so
// whatever the container reads from it has to accept being empty.
var bareInterpolation = regexp.MustCompile(`^\$\{[A-Za-z_][A-Za-z0-9_]*\}$`)

// The environment block of docker-compose.yml names some variables that come
// straight from .env. Each one that can arrive empty is a value the controller
// has to take empty, however .env.example happens to spell it today: an
// operator who deletes the line, or blanks it, gets the same container.
func TestTheComposeFilePassesNothingThroughThatTheControllerRefusesWhenItIsEmpty(t *testing.T) {
	raw, err := os.ReadFile("../../docker-compose.yml")
	if err != nil {
		t.Fatalf("reading the compose file: %v", err)
	}
	var file struct {
		Services map[string]struct {
			Environment map[string]string `yaml:"environment"`
		} `yaml:"services"`
	}
	if err := yaml.Unmarshal(raw, &file); err != nil {
		t.Fatalf("parsing the compose file: %v", err)
	}
	environment := file.Services["zoomies"].Environment
	if len(environment) == 0 {
		t.Fatal("docker-compose.yml has no environment mapping for the zoomies service; the test is reading the file wrongly")
	}

	var names []string
	for name, value := range environment {
		if bareInterpolation.MatchString(strings.TrimSpace(value)) {
			names = append(names, name)
		}
	}
	sort.Strings(names)
	for _, name := range names {
		if _, _, err := config.Effective("", nil, nil, map[string]string{name: ""}); err != nil {
			t.Errorf("docker-compose.yml passes %s through from .env, where it can be empty, and the controller refuses that:\n%v", name, err)
		}
	}
}

package docs

import (
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"runtime"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/releasekey"
)

// A pod's Build command runs deploy/instapods/fetch.sh, and so does the nightly
// update.sh that docs/instapods.md recommends, with ZOOMIES_VERSION unset. The
// release it takes then is whichever one GitHub calls the latest, and that is
// the newest by date: whoever can publish a release chooses its name and can
// attach a checksums.txt that matches a binary of their own. They cannot sign
// it. These tests run the real script, end to end, against a stand-in for
// GitHub, to hold it to refusing that.

// fetchRig is a pod's checkout, a home directory per run, and a curl that serves
// release files from a directory instead of GitHub. The script is the one that
// ships, except for its release key: the project's private half is not ours to
// sign with, so the key is swapped for one this test holds both halves of.
type fetchRig struct {
	root     string // the checkout, the fake curl and the releases
	releases string
	priv     string
	asset    string
}

// fakeCurl answers the two kinds of request fetch.sh makes: the redirect from
// .../releases/latest, which names the latest tag, and a download of a release
// file, which is served from $FAKE_RELEASES or is a 404. Every request is
// logged, so a test can say nothing was downloaded.
const fakeCurl = `#!/bin/sh
out=''
url=''
while [ $# -gt 0 ]; do
    case "$1" in
        -o) out=$2; shift 2 ;;
        -w | --retry | --retry-delay | --proto | --proto-redir) shift 2 ;;
        -*) shift ;;
        *) url=$1; shift ;;
    esac
done
printf '%s\n' "$url" >> "$FAKE_LOG"
case "$url" in
    */releases/latest)
        printf '%s' "https://github.com/eyupio/zoomies/releases/tag/$FAKE_LATEST"
        ;;
    */releases/download/*)
        rest=${url#*/releases/download/}
        src="$FAKE_RELEASES/${rest%%/*}/${rest#*/}"
        [ -f "$src" ] || exit 22
        cp "$src" "$out"
        ;;
    *) exit 22 ;;
esac
`

func newFetchRig(t *testing.T) *fetchRig {
	t.Helper()
	if runtime.GOOS != "linux" {
		t.Skip("fetch.sh is for a pod, which runs Linux, and refuses to run anywhere else")
	}
	if runtime.GOARCH != "amd64" && runtime.GOARCH != "arm64" {
		t.Skipf("fetch.sh downloads amd64 and arm64 builds, and this is %s", runtime.GOARCH)
	}
	needOpenSSLForEd25519(t)

	pub, priv, err := releasekey.Generate()
	if err != nil {
		t.Fatal(err)
	}
	script := scriptText(t, "deploy/instapods/fetch.sh")
	keyed := regexp.MustCompile(`(?m)^RELEASE_KEY="[^"]*"$`).ReplaceAllString(script, `RELEASE_KEY="`+pub+`"`)
	if keyed == script {
		t.Fatal("fetch.sh has no RELEASE_KEY line to swap, so the signatures made here would be checked against the project's key")
	}

	root := t.TempDir()
	r := &fetchRig{root: root, releases: filepath.Join(root, "releases"), priv: priv, asset: "zoomies_linux_" + runtime.GOARCH}
	for path, body := range map[string]string{
		"app/deploy/instapods/fetch.sh": keyed,
		"app/deploy/instapods/lib.sh":   scriptText(t, "deploy/instapods/lib.sh"),
		"bin/curl":                      fakeCurl,
	} {
		full := filepath.Join(root, path)
		if err := os.MkdirAll(filepath.Dir(full), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(full, []byte(body), 0o755); err != nil {
			t.Fatal(err)
		}
	}
	return r
}

// release publishes a tag: a binary that records having been run, the
// checksums.txt that matches it, and the signature when asked for one.
func (r *fetchRig) release(t *testing.T, tag string, signed bool) {
	t.Helper()
	dir := filepath.Join(r.releases, tag)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	payload := "#!/bin/sh\n: > \"$HOME/payload-ran\"\necho \"zoomies " + tag + "\"\n"
	sum := sha256.Sum256([]byte(payload))
	sums := []byte(hex.EncodeToString(sum[:]) + "  " + r.asset + "\n")
	files := map[string][]byte{r.asset: []byte(payload), "checksums.txt": sums}
	if signed {
		envelope, err := releasekey.Sign(r.priv, sums)
		if err != nil {
			t.Fatal(err)
		}
		files["checksums.txt.ed25519"] = envelope
	}
	for name, body := range files {
		if err := os.WriteFile(filepath.Join(dir, name), body, 0o755); err != nil {
			t.Fatal(err)
		}
	}
}

type fetchRun struct {
	output     string
	exit       int
	installed  bool   // the binary is in place, where the service will start it from
	ran        bool   // the downloaded file was executed at all
	downloaded string // every address the script asked the fake GitHub for
}

// run is a deploy of the controller pod. latest is the tag GitHub's
// /releases/latest redirects to, and env is the rest of the pod's environment,
// ZOOMIES_VERSION among it.
func (r *fetchRig) run(t *testing.T, latest string, env ...string) fetchRun {
	t.Helper()
	home, logPath := t.TempDir(), filepath.Join(t.TempDir(), "requests")
	cmd := exec.Command("sh", filepath.Join(r.root, "app/deploy/instapods/fetch.sh"), "controller")
	cmd.Env = append([]string{
		"PATH=" + filepath.Join(r.root, "bin") + string(os.PathListSeparator) + os.Getenv("PATH"),
		"HOME=" + home, "FAKE_RELEASES=" + r.releases, "FAKE_LATEST=" + latest, "FAKE_LOG=" + logPath,
	}, env...)
	out, err := cmd.CombinedOutput()
	res := fetchRun{output: string(out)}
	var ee *exec.ExitError
	if errors.As(err, &ee) {
		res.exit = ee.ExitCode()
	} else if err != nil {
		t.Fatalf("running sh: %v", err)
	}
	_, statErr := os.Stat(filepath.Join(home, "zoomies/bin/zoomies"))
	res.installed = statErr == nil
	_, statErr = os.Stat(filepath.Join(home, "payload-ran"))
	res.ran = statErr == nil
	if b, err := os.ReadFile(logPath); err == nil {
		res.downloaded = string(b)
	}
	return res
}

func TestTheInstaPodsBuildInstallsALatestReleaseThatIsSigned(t *testing.T) {
	r := newFetchRig(t)
	r.release(t, "v1.3.9", true)
	got := r.run(t, "v1.3.9")
	if got.exit != 0 || !got.installed || !strings.Contains(got.output, "matches the release key") {
		t.Errorf("a signed latest release: exit %d, installed %v, output:\n%s\nwant it installed after the signature was checked", got.exit, got.installed, got.output)
	}
}

// GitHub's latest is the newest release by date, and its name is the
// publisher's to choose. A name that needs no signature (an old version, a
// string the script cannot read as one) is therefore not what "latest" can
// honestly be, since every release from v1.3.6 up is signed: it is refused
// before the binary is fetched, and the message says what to do instead. The
// same script still runs an old release its operator names, below.
func TestTheInstaPodsBuildRefusesALatestReleaseThatNeedsNoSignatureBeforeDownloadingIt(t *testing.T) {
	r := newFetchRig(t)
	for _, tag := range []string{"v0.0.1", "v1.3.5", "dev", "v2x.0.0", "v99999999999999999999.0.0"} {
		r.release(t, tag, false)
	}
	for _, tag := range []string{"v0.0.1", "v1.3.5", "dev"} {
		t.Run(tag, func(t *testing.T) {
			got := r.run(t, tag)
			if got.exit == 0 || got.installed || got.ran {
				t.Errorf("latest = %s with no signature: exit %d, installed %v, run %v; it must stop", tag, got.exit, got.installed, got.ran)
			}
			if strings.Contains(got.downloaded, "/download/"+tag+"/"+r.asset) {
				t.Errorf("latest = %s: the binary was downloaded before the name was refused:\n%s", tag, got.downloaded)
			}
			if !strings.Contains(got.output, tag) || !strings.Contains(got.output, "ZOOMIES_VERSION") {
				t.Errorf("latest = %s: the refusal does not name the release and the variable that chooses another:\n%s", tag, got.output)
			}
		})
	}
	// A name the script cannot read as a version is also held to a signature, so
	// it is refused for the want of one wherever the name came from.
	for _, tag := range []string{"v2x.0.0", "v99999999999999999999.0.0"} {
		t.Run(tag, func(t *testing.T) {
			if got := r.run(t, tag); got.exit == 0 || got.installed || got.ran {
				t.Errorf("latest = %s with no signature: exit %d, installed %v, run %v; it must stop:\n%s", tag, got.exit, got.installed, got.ran, got.output)
			}
		})
	}
}

// Naming a release is the operator's own decision, and docs/upgrading.md says a
// release before signing began is taken on its checksum with a warning. A pod
// pinned to one keeps working.
func TestTheInstaPodsBuildStillTakesAnOldReleaseNamedOutrightOnItsChecksum(t *testing.T) {
	r := newFetchRig(t)
	r.release(t, "v1.3.5", false)
	got := r.run(t, "v1.3.9", "ZOOMIES_VERSION=v1.3.5")
	if got.exit != 0 || !got.installed || !strings.Contains(got.output, "warning") || !strings.Contains(got.output, "checksum alone") {
		t.Errorf("v1.3.5 named by the operator: exit %d, installed %v, output:\n%s\nwant it installed on its checksum with a warning", got.exit, got.installed, got.output)
	}
}

// A name that cannot be read as numbers is not an old release. An operator who
// pins one gets the same answer as for a new release with no signature, because
// the alternative is that the name itself switches the check off.
func TestTheInstaPodsBuildHoldsAReleaseWithAnUnreadableNameToASignature(t *testing.T) {
	r := newFetchRig(t)
	for _, tag := range []string{"v2x.0.0", "v99999999999999999999.0.0"} {
		r.release(t, tag, false)
		t.Run(tag, func(t *testing.T) {
			got := r.run(t, "v1.3.9", "ZOOMIES_VERSION="+tag)
			if got.exit == 0 || got.installed || got.ran || !strings.Contains(got.output, "must be signed") {
				t.Errorf("%s named by the operator, unsigned: exit %d, installed %v, run %v, output:\n%s\nwant it refused for the want of a signature", tag, got.exit, got.installed, got.ran, got.output)
			}
		})
	}
}

