// A skill is read whole by an agent that then types what it names, so a
// command in a skill has to be one the binary has: an agent that follows a
// skill into a verb that does not exist learns to distrust the whole thing.
// The list comes from the binary itself, never from a copy.
func commandNames(t *testing.T) (names, groups map[string]bool) {
	t.Helper()
	cmd := exec.Command("go", "run", "../../cmd/zoomies", "commands", "--output", "json")
	cmd.Env = append(os.Environ(), "ZOOMIES_URL=", "ZOOMIES_TOKEN=")
	out, err := cmd.Output()
	if err != nil {
		var ee *exec.ExitError
		if errors.As(err, &ee) {
			t.Fatalf("zoomies commands: %v\n%s", err, ee.Stderr)
		}
		t.Fatalf("zoomies commands: %v", err)
	}
	var cmds []struct {
		Name        string `json:"name"`
		Subcommands []struct {
			Name string `json:"name"`
		} `json:"subcommands"`
	}
	if err := json.Unmarshal(out, &cmds); err != nil {
		t.Fatal(err)
	}
	names, groups = map[string]bool{}, map[string]bool{}
	for _, c := range cmds {
		names["zoomies "+c.Name] = true
		if len(c.Subcommands) > 0 {
			groups["zoomies "+c.Name] = true
		}
		for _, s := range c.Subcommands {
			names["zoomies "+c.Name+" "+s.Name] = true
		}
	}
	return names, groups
}

// A command is named in backticks; "zoomies is not installed" in prose is a
// sentence, not a verb.
var skillCommand = regexp.MustCompile("`zoomies ([a-z][a-z-]*)(?: ([a-z][a-z-]*))?[^`]*`")

// unknownCommands is every backticked "zoomies ..." in text that the binary
// does not have. A second word after a group's name is a verb and must be one
// of the group's; after a command that takes arguments it is an argument
// ("zoomies why job_1") and only the command is checked.
func unknownCommands(text string, names, groups map[string]bool) []string {
	var out []string
	for _, m := range skillCommand.FindAllStringSubmatch(text, -1) {
		one := "zoomies " + m[1]
		if m[2] != "" && groups[one] {
			if !names[one+" "+m[2]] {
				out = append(out, strings.Trim(m[0], "` "))
			}
			continue
		}
		if !names[one] {
			out = append(out, strings.Trim(m[0], "` "))
		}
	}
	return out
}

func TestEveryCommandASkillNamesIsOneTheBinaryHas(t *testing.T) {
	names, groups := commandNames(t)
	for _, s := range readSkills(t) {
		for _, bad := range unknownCommands(s.text, names, groups) {
			t.Errorf("skills/%s: names %q, which the binary does not have", s.dir, bad)
		}
	}
}

// The matcher is the whole point of the test above, so it is held to the
// failure it exists to catch: a verb mistyped under a group, which the
// group's own existence must not excuse.
func TestAMistypedSubcommandIsCaughtAndAnArgumentIsNot(t *testing.T) {
	names := map[string]bool{"zoomies jobs": true, "zoomies jobs advice": true, "zoomies why": true}
	groups := map[string]bool{"zoomies jobs": true}
	for text, want := range map[string][]string{
		"run `zoomies jobs advice` first":                 nil,
		"run `zoomies jobs advise` first":                 {"zoomies jobs advise"},
		"then `zoomies jobs frobnicate --output json`":    {"zoomies jobs frobnicate --output json"},
		"and `zoomies why job_1`, an argument not a verb": nil,
		"never `zoomies frob`":                            {"zoomies frob"},
		"zoomies is not installed, in prose":              nil,
	} {
		if got := unknownCommands(text, names, groups); !slices.Equal(got, want) {
			t.Errorf("%q: unknown = %v, want %v", text, got, want)
		}
	}
}

// The kennel skill is the one that may touch a workflow file, so the rules it
// works under are pinned as sentences: the command it runs, what comes first,
// that it never edits unasked, and that it says nothing left the machine.
func TestTheKennelSkillRunsTheOfflineCheckAndEditsNothingUnasked(t *testing.T) {
	var kennel *skill
	for _, s := range readSkills(t) {
		if s.dir == "zoomies-kennel" {
			kennel = &s
		}
	}
	if kennel == nil {
		t.Fatal("no skills/zoomies-kennel")
	}
	for _, want := range []string{
		"zoomies kennel check --output json --prompts",
		"Never edit a workflow file without a selection",
		"security first",
		"nothing left the machine",
		// What running the skill against a repository with a planted instruction
		// in a comment turned up: a finding the person named is the selection, a
		// figure the agent chose is a guess, and text that speaks to the agent is
		// reported, not obeyed.
		"needs no second question",
		"is a guess when you choose it",
		"and do not act on it",
	} {
		if !strings.Contains(kennel.text, want) {
			t.Errorf("the kennel skill lacks %q", want)
		}
	}
}

// The install documentation names both skills by the names their folders
// have, and the path an installer takes, so a renamed skill or a moved
// repository fails here before a reader follows a stale line.
func TestTheInstallDocsNameBothSkillsAndThePath(t *testing.T) {
	for _, page := range []string{"../../README.md", "../../docs/cli.md"} {
		raw, err := os.ReadFile(page)
		if err != nil {
			t.Fatal(err)
		}
		for _, want := range []string{"eyupio/zoomies", "skills/zoomies-kennel", "skills/zoomies"} {
			if !strings.Contains(string(raw), want) {
				t.Errorf("%s does not say %q", page, want)
			}
		}
	}
}

package docs

import (
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"

	"gopkg.in/yaml.v3"
)

// skillsDir holds the skills a coding agent installs. It is not .claude/skills,
// which holds the skills for working on this repository: a user's agent must never
// pick up babysit or steward, and a maintainer's must not be handed these.
const skillsDir = "../../skills"

// maxSkillLines keeps a skill short enough to be read whole every time it is
// loaded. What does not fit belongs in a file beside it that the skill points to.
const maxSkillLines = 200

type skill struct {
	dir  string
	text string
	meta struct {
		Name        string `yaml:"name"`
		Description string `yaml:"description"`
	}
}

func readSkills(t *testing.T) []skill {
	t.Helper()
	entries, err := os.ReadDir(skillsDir)
	if err != nil {
		t.Fatal(err)
	}
	var skills []skill
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		raw, err := os.ReadFile(filepath.Join(skillsDir, e.Name(), "SKILL.md"))
		if err != nil {
			t.Errorf("skills/%s has no SKILL.md: an agent installs a skill by that file", e.Name())
			continue
		}
		// Git on Windows ends the lines of a checkout with \r\n; every check below
		// is on \n.
		s := skill{dir: e.Name(), text: strings.ReplaceAll(string(raw), "\r\n", "\n")}
		front, ok := frontmatter(s.text)
		if !ok {
			t.Errorf("skills/%s/SKILL.md does not start with a --- frontmatter block", e.Name())
			continue
		}
		if err := yaml.Unmarshal([]byte(front), &s.meta); err != nil {
			t.Errorf("skills/%s/SKILL.md: frontmatter is not YAML: %v", e.Name(), err)
			continue
		}
		skills = append(skills, s)
	}
	if len(skills) == 0 {
		t.Fatal("found no skills; the test is looking in the wrong place")
	}
	return skills
}

// frontmatter returns what lies between the opening and closing --- lines.
func frontmatter(text string) (string, bool) {
	rest, ok := strings.CutPrefix(text, "---\n")
	if !ok {
		return "", false
	}
	front, _, ok := strings.Cut(rest, "\n---\n")
	return front, ok
}

// The installers that read a skills folder choose a skill by its name and decide
// when to load it from its description alone, so both must be there and say
// something: a name that differs from its folder is a skill that installs under
// one name and is asked for under another, and a description that does not say
// when to use the skill is a skill nothing ever loads.
func TestEverySkillNamesItselfAndSaysWhenToUseIt(t *testing.T) {
	for _, s := range readSkills(t) {
		if s.meta.Name != s.dir {
			t.Errorf("skills/%s: name is %q, and it must be the folder's name", s.dir, s.meta.Name)
		}
		if !regexp.MustCompile(`^[a-z][a-z0-9-]*$`).MatchString(s.meta.Name) {
			t.Errorf("skills/%s: name %q is not lower-case words joined by hyphens", s.dir, s.meta.Name)
		}
		d := strings.TrimSpace(s.meta.Description)
		if d == "" {
			t.Errorf("skills/%s: no description", s.dir)
		}
		if len(d) > 1024 {
			t.Errorf("skills/%s: description is %d characters; installers cut it at 1024", s.dir, len(d))
		}
		if !strings.Contains(d, "Use when") {
			t.Errorf("skills/%s: the description does not say \"Use when\", which is what makes an agent load the skill", s.dir)
		}
		if strings.ContainsAny(d, "<>") {
			t.Errorf("skills/%s: the description has angle brackets, which some installers reject", s.dir)
		}
	}
}

func TestEverySkillFitsInTwoHundredLines(t *testing.T) {
	for _, s := range readSkills(t) {
		if n := strings.Count(s.text, "\n"); n > maxSkillLines {
			t.Errorf("skills/%s/SKILL.md is %d lines; the limit is %d. Put the detail in a file beside it and link to it", s.dir, n, maxSkillLines)
		}
	}
}

// A skill is copied into somebody else's project or home folder, so a link out
// of its own folder points at nothing there, and a link inside it that names a
// file that was never written points at nothing anywhere.
func TestEverySkillLinkStaysInsideTheSkillAndPointsAtAFile(t *testing.T) {
	link := regexp.MustCompile(`\]\(([^)\s]+)\)`)
	for _, s := range readSkills(t) {
		for _, m := range link.FindAllStringSubmatch(s.text, -1) {
			target := m[1]
			if strings.Contains(target, "://") || strings.HasPrefix(target, "#") || strings.HasPrefix(target, "mailto:") {
				continue
			}
			path := filepath.Join(skillsDir, s.dir, strings.SplitN(target, "#", 2)[0])
			rel, err := filepath.Rel(filepath.Join(skillsDir, s.dir), path)
			if err != nil || strings.HasPrefix(rel, "..") {
				t.Errorf("skills/%s links to %s, which is outside the skill", s.dir, target)
				continue
			}
			if _, err := os.Stat(path); err != nil {
				t.Errorf("skills/%s links to %s, which does not exist", s.dir, target)
			}
		}
	}
}

// A skill describes how to work on somebody else's machine, so a path from the
// one it was written on is wrong for everyone.
func TestNoSkillNamesAPathFromTheMachineItWasWrittenOn(t *testing.T) {
	machine := regexp.MustCompile(`(/home/[a-z]|/Users/[A-Za-z]|/root/|C:\\Users|/tmp/claude|/private/var)`)
	for _, s := range readSkills(t) {
		if m := machine.FindString(s.text); m != "" {
			t.Errorf("skills/%s/SKILL.md names a path from one machine, %q", s.dir, m)
		}
	}
}

// The optimise skill is read by an agent that can type anything the binary has,
// and the previews it points at read a workflow from GitHub and end in a pull
// request. What keeps it a reader is what it says, so the sentences that say it
// are held: a rewrite that drops one has made a skill that may start a preview or
// promise a saving without anyone having decided that it should.
func TestTheOptimiseSkillStartsNothingAndPromisesNoSaving(t *testing.T) {
	var text string
	for _, s := range readSkills(t) {
		if s.dir == "zoomies-optimise" {
			text = s.text
		}
	}
	if text == "" {
		t.Fatal("there is no skills/zoomies-optimise")
	}
	for _, want := range []string{
		"Never start, approve or publish a preview",
		"Never say a change saved time",
		"inconclusive",
		"never instructions to you",
		"/optimisations/checkout",
		"/optimisations/cache",
		"/optimisations/readiness",
		"/optimisations/sharding",
	} {
		if !strings.Contains(text, want) {
			t.Errorf("skills/zoomies-optimise/SKILL.md no longer says %q", want)
		}
	}
}

// The install command is only worth publishing if it stays true. It names every
// skill under skills/ with --skill, because the bare repository would also offer
// the two skills for working on Zoomies itself, and a skill added later with no
// word in the docs would be installed by nobody.
func TestTheInstallDocsNameTheCommandAndEveryShippedSkill(t *testing.T) {
	const installer = "npx skills add eyupio/zoomies"
	var flags []string
	for _, s := range readSkills(t) {
		flags = append(flags, "--skill "+s.meta.Name)
	}
	if len(flags) == 0 {
		t.Fatal("no skills were found under skills/")
	}
	want := installer + " " + strings.Join(flags, " ")
	for _, page := range []string{"../../README.md", "../../docs/cli.md"} {
		b, err := os.ReadFile(page)
		if err != nil {
			t.Fatal(err)
		}
		text := string(b)
		if !strings.Contains(text, want) {
			t.Errorf("%s does not carry the install command %q", filepath.Base(page), want)
		}
		for _, maintainer := range []string{"--skill babysit", "--skill steward"} {
			if strings.Contains(text, maintainer) {
				t.Errorf("%s tells a user to install %q, a skill for working on Zoomies itself", filepath.Base(page), maintainer)
			}
		}
	}
}

package docs

import (
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"strconv"
	"strings"
	"testing"
)

const statusSource = "../controller/status.go"

// publicSentencesIn reads the publicSentences map literal out of the
// controller's source, parsed rather than searched for the reason codesIn
// is: a sentence in a comment is not one the status page can show.
func publicSentencesIn(t *testing.T) map[string]string {
	t.Helper()
	file, err := parser.ParseFile(token.NewFileSet(), statusSource, nil, parser.SkipObjectResolution)
	if err != nil {
		t.Fatalf("parsing %s: %v", statusSource, err)
	}
	out := map[string]string{}
	ast.Inspect(file, func(n ast.Node) bool {
		spec, ok := n.(*ast.ValueSpec)
		if !ok || len(spec.Names) != 1 || spec.Names[0].Name != "publicSentences" || len(spec.Values) != 1 {
			return true
		}
		lit, ok := spec.Values[0].(*ast.CompositeLit)
		if !ok {
			return false
		}
		for _, elt := range lit.Elts {
			kv, ok := elt.(*ast.KeyValueExpr)
			if !ok {
				continue
			}
			k, kok := kv.Key.(*ast.BasicLit)
			v, vok := kv.Value.(*ast.BasicLit)
			if !kok || !vok {
				t.Errorf("a publicSentences entry is not a pair of string literals; a sentence built from anything else could carry a name")
				continue
			}
			code, _ := strconv.Unquote(k.Value)
			sentence, _ := strconv.Unquote(v.Value)
			out[code] = sentence
		}
		return false
	})
	if len(out) == 0 {
		t.Fatal("no public sentences were found; the map moved, not the docs")
	}
	return out
}

// statusTable is the "What the status page says" table on the problem-codes
// page, code to sentence.
func statusTable(t *testing.T) map[string]string {
	t.Helper()
	page, err := os.ReadFile(reference)
	if err != nil {
		t.Fatalf("reading %s: %v", reference, err)
	}
	_, section, ok := strings.Cut(string(page), "\n## What the status page says\n")
	if !ok {
		t.Fatal(`docs/problem-codes.md has no "What the status page says" section`)
	}
	if end := strings.Index(section, "\n## "); end >= 0 {
		section = section[:end]
	}
	out := map[string]string{}
	for _, line := range strings.Split(section, "\n") {
		if !strings.HasPrefix(line, "| `") {
			continue
		}
		cells := strings.Split(strings.Trim(line, "|"), " | ")
		if len(cells) != 2 {
			t.Errorf("a row in the status table is not two cells: %s", line)
			continue
		}
		out[strings.Trim(strings.TrimSpace(cells[0]), "`")] = strings.TrimSpace(cells[1])
	}
	return out
}

// The status page shows a reader with no account one sentence per problem
// code, and the problem-codes page publishes the same sentence beside the
// operator's -- in both directions and word for word, so that what an
// operator reads there is what their developers are being told.
func TestEveryPublicSentenceIsOnTheProblemCodesPage(t *testing.T) {
	code := publicSentencesIn(t)
	page := statusTable(t)
	for c, s := range code {
		got, ok := page[c]
		switch {
		case !ok:
			t.Errorf("%s has a public sentence and no row in the status table of docs/problem-codes.md", c)
		case got != s:
			t.Errorf("%s says %q in the code and %q on the page", c, s, got)
		}
	}
	for c := range page {
		if _, ok := code[c]; !ok {
			t.Errorf("docs/problem-codes.md gives %s a public sentence the status page does not have", c)
		}
	}
}

package docs

import (
	"os"
	"regexp"
	"strings"
	"testing"
)

// The pages of the UI, and the two places that count them.
const (
	sectionsSource = "../../web/src/lib/shell/sections.ts"
	uiTour         = "../../docs/ui.md"
)

// The front pages say how many pages the UI has, and the number has to be
// true.
//
// It is the first concrete claim a reader meets on both the README and the
// site's home page, and it is the kind of number nobody thinks to revisit:
// Usage and Providers were both added without it moving, so it sat at ten
// while the navigation grew to twelve. A count that is quietly wrong in the
// first sentence is a poor argument for trusting the rest.
func TestTheFrontPagesCountThePagesTheUIHas(t *testing.T) {
	body, err := os.ReadFile(sectionsSource)
	if err != nil {
		t.Fatalf("reading %s: %v", sectionsSource, err)
	}
	// The entries of SECTIONS, which is the one list the sidebar, the phone's
	// bar and its menu all read -- so counting it counts what an operator sees.
	// An entry too long for one line is wrapped by the formatter, so the
	// comma between the path and the label may be followed by a newline.
	entries := regexp.MustCompile(`\{\s*path: '[^']*',\s*label: '`).FindAllString(string(body), -1)
	if len(entries) < 2 {
		t.Fatalf("found %d sections in %s; the list moved rather than the count", len(entries), sectionsSource)
	}
	want := numberWord(len(entries))
	if want == "" {
		t.Fatalf("the UI has %d sections and this test cannot spell that; add the word", len(entries))
	}

	// Both front doors make the claim, in their own words, so the pattern is
	// the number followed by "pages" rather than a sentence to match.
	claim := regexp.MustCompile(`(?i)\b([a-z]+) pages, one job each\b`)
	for _, page := range []string{"../../README.md", "../../docs/index.md"} {
		text, err := os.ReadFile(page)
		if err != nil {
			t.Fatalf("reading %s: %v", page, err)
		}
		found := claim.FindStringSubmatch(string(text))
		if found == nil {
			t.Errorf("%s no longer says how many pages the UI has; if that claim moved, move this test with it", page)
			continue
		}
		if !strings.EqualFold(found[1], want) {
			t.Errorf("%s says %q pages; the navigation has %d, so it should say %q",
				page, found[1], len(entries), want)
		}
	}
}

// Every page in the navigation is described somewhere in the tour.
//
// docs/ui.md is linked from both front pages as "see every page", which is a
// promise rather than a title: a page that is in the product and not in the
// tour is one a reader concludes does not exist.
func TestTheTourDescribesEveryPageInTheNavigation(t *testing.T) {
	body, err := os.ReadFile(sectionsSource)
	if err != nil {
		t.Fatalf("reading %s: %v", sectionsSource, err)
	}
	labels := regexp.MustCompile(`label: '([^']+)'`).FindAllStringSubmatch(string(body), -1)
	if len(labels) < 2 {
		t.Fatalf("found %d labels in %s; the list moved", len(labels), sectionsSource)
	}

	tour, err := os.ReadFile(uiTour)
	if err != nil {
		t.Fatalf("reading %s: %v", uiTour, err)
	}
	headings := map[string]bool{}
	for _, line := range strings.Split(string(tour), "\n") {
		if after, ok := strings.CutPrefix(line, "## "); ok {
			headings[strings.ToLower(strings.TrimSpace(after))] = true
		}
	}

	var missing []string
	for _, label := range labels {
		if !headings[strings.ToLower(label[1])] {
			missing = append(missing, label[1])
		}
	}
	if len(missing) > 0 {
		t.Errorf("these pages are in the navigation but have no section in %s: %s",
			uiTour, strings.Join(missing, ", "))
	}
}

// numberWord spells the counts a navigation could plausibly have. The front
// pages write the number as a word because they are prose, so the test has to
// compare words.
func numberWord(n int) string {
	words := map[int]string{
		6: "Six", 7: "Seven", 8: "Eight", 9: "Nine", 10: "Ten", 11: "Eleven",
		12: "Twelve", 13: "Thirteen", 14: "Fourteen", 15: "Fifteen", 16: "Sixteen",
	}
	return words[n]
}

package docs

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/installer"
)

// The update helper is a grant of root that the installer offers, so every page
// that describes the offer says what it is for in the installer's own sentence:
// that the web UI can then update the host, and that its owner installs and
// removes it. A page that said less would ask for root without saying why, and
// one that said something else would drift from what the question at the
// terminal says. A release that changes what the helper is for changes the
// sentence, and this test finds every page that has to follow.
func TestEveryPageThatOffersTheUpdateHelperSaysWhatItIsFor(t *testing.T) {
	read := func(page string) string {
		t.Helper()
		body, err := os.ReadFile(filepath.Join("..", "..", "docs", page))
		if err != nil {
			t.Fatal(err)
		}
		return string(body)
	}
	for _, page := range []string{"upgrading.md", "quickstart.md"} {
		if !strings.Contains(read(page), installer.UpdateHelperExplained) {
			t.Errorf("docs/%s describes the update helper without saying %q", page, installer.UpdateHelperExplained)
		}
	}

	cli := strings.Split(read("cli.md"), "\n")
	row := func(prefix string) string {
		t.Helper()
		for _, l := range cli {
			if strings.HasPrefix(l, prefix) {
				return l
			}
		}
		t.Fatalf("docs/cli.md has no row starting %q", prefix)
		return ""
	}
	for _, prefix := range []string{"| `updates helper install`", "| `zoomies init", "| `zoomies upgrade", "| `zoomies agent join"} {
		if line := row(prefix); !strings.Contains(line, installer.UpdateHelperExplained) {
			t.Errorf("the docs/cli.md row %s describes the update helper without saying %q", prefix, installer.UpdateHelperExplained)
		}
	}
}

package docs

import (
	"errors"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
)

// deploy/instapods/update.sh brings a pod up to date: it downloads the release,
// and restarts the app onto it. On the worker a restart fails the job that is
// running, so the script looks for one first. A download takes minutes, and a
// job can start in them; these tests run the real script against stand-ins for
// the download, for systemctl and for the process table, and hold it to
// restarting only when no job is running at the moment of the restart.

// updateRig is a pod's checkout and home directory, with a fetch.sh that
// "downloads" without a network, a systemctl that records its restarts, and a
// directory standing in for /proc whose entries are the jobs running.
type updateRig struct {
	root string
	proc string // a stand-in for /proc: one directory with a cmdline file per job
}

func newUpdateRig(t *testing.T) *updateRig {
	t.Helper()
	if runtime.GOOS != "linux" {
		t.Skip("update.sh finds a running job in /proc, which only Linux has")
	}
	root := t.TempDir()
	r := &updateRig{root: root, proc: filepath.Join(root, "proc")}

	// The script as it ships, except that it reads the stand-in for /proc. A CI
	// job itself runs under a Runner.Worker, so the real /proc would always show
	// a job running and the idle cases could not be told from the busy ones.
	script := scriptText(t, "deploy/instapods/update.sh")
	const probe = "/proc/[0-9]*/cmdline"
	if strings.Count(script, probe) != 1 {
		t.Fatalf("update.sh no longer looks for a job in %s exactly once, so this test cannot point it at its own process table", probe)
	}
	script = strings.Replace(script, probe, `"$FAKE_PROC"/[0-9]*/cmdline`, 1)

	for path, body := range map[string]string{
		"app/deploy/instapods/update.sh": script,
		"app/deploy/instapods/lib.sh":    scriptText(t, "deploy/instapods/lib.sh"),
		// The download: a new binary on request, and a job that starts while it
		// is in flight on request.
		"app/deploy/instapods/fetch.sh": `#!/bin/sh
set -eu
if [ -n "${NEW_BINARY:-}" ]; then
    mkdir -p "$(dirname "$ZOOMIES_BIN")"
    n=$(cat "$STATE/n" 2>/dev/null || echo 0)
    n=$((n + 1))
    echo "$n" > "$STATE/n"
    printf '#!/bin/sh\necho "zoomies fake-%s"\n' "$n" > "$ZOOMIES_BIN"
    chmod 0755 "$ZOOMIES_BIN"
fi
if [ -n "${START_JOB_DURING_DOWNLOAD:-}" ]; then
    mkdir -p "$FAKE_PROC/4242"
    echo "/opt/runner/bin/Runner.Worker spawnclient" > "$FAKE_PROC/4242/cmdline"
fi
`,
		"shim/systemctl": `#!/bin/sh
case "$1" in
    cat) [ -z "${NO_SERVICE:-}" ] ;;
    restart) echo "restart $2" >> "$SYSTEMCTL_LOG" ;;
esac
`,
		"shim/sudo":  "#!/bin/sh\n[ \"$1\" != -n ] || shift\nexec \"$@\"\n",
		"shim/sleep": "#!/bin/sh\nexit 0\n",
	} {
		full := filepath.Join(root, path)
		if err := os.MkdirAll(filepath.Dir(full), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(full, []byte(body), 0o755); err != nil {
			t.Fatal(err)
		}
	}
	for _, dir := range []string{r.proc, filepath.Join(root, "state"), filepath.Join(root, "home")} {
		if err := os.MkdirAll(dir, 0o755); err != nil {
			t.Fatal(err)
		}
	}
	return r
}

type updateRun struct {
	output   string
	exit     int
	restarts int // how many times the app was restarted
}

// run is `sh deploy/instapods/update.sh args`, with the rest of the pod's
// environment in env.
func (r *updateRig) run(t *testing.T, args []string, env ...string) updateRun {
	t.Helper()
	logPath := filepath.Join(r.root, "systemctl.log")
	before := countLines(logPath, "restart")
	cmd := exec.Command("sh", append([]string{filepath.Join(r.root, "app/deploy/instapods/update.sh")}, args...)...)
	cmd.Env = append([]string{
		"PATH=" + filepath.Join(r.root, "shim") + string(os.PathListSeparator) + os.Getenv("PATH"),
		"HOME=" + filepath.Join(r.root, "home"),
		"ZOOMIES_BIN=" + filepath.Join(r.root, "home/zoomies/bin/zoomies"),
		"STATE=" + filepath.Join(r.root, "state"), "FAKE_PROC=" + r.proc, "SYSTEMCTL_LOG=" + logPath,
	}, env...)
	out, err := cmd.CombinedOutput()
	got := updateRun{output: string(out)}
	var ee *exec.ExitError
	if errors.As(err, &ee) {
		got.exit = ee.ExitCode()
	} else if err != nil {
		t.Fatalf("running sh: %v", err)
	}
	got.restarts = countLines(logPath, "restart") - before
	return got
}

func countLines(path, contains string) int {
	body, err := os.ReadFile(path)
	if err != nil {
		return 0
	}
	n := 0
	for _, line := range strings.Split(string(body), "\n") {
		if strings.Contains(line, contains) {
			n++
		}
	}
	return n
}

// endJob takes the Runner.Worker the download started out of the stand-in
// process table, as a job finishing does.
func (r *updateRig) endJob(t *testing.T) {
	t.Helper()
	if err := os.RemoveAll(filepath.Join(r.proc, "4242")); err != nil {
		t.Fatal(err)
	}
}

func TestTheInstaPodsUpdateRestartsAnIdleWorkerOntoTheNewVersion(t *testing.T) {
	r := newUpdateRig(t)
	got := r.run(t, []string{"agent"}, "NEW_BINARY=1")
	if got.exit != 0 || got.restarts != 1 || !strings.Contains(got.output, "now running: zoomies fake-1") {
		t.Errorf("an idle worker, new binary: exit %d, restarts %d, output:\n%s\nwant one restart and the new version said to be running", got.exit, got.restarts, got.output)
	}
}

// docs/instapods.md promises the worker is left alone while a job runs. The
// script checks before it downloads, but the download takes minutes, and a job
// that starts in them used to be killed by the restart that followed. The
// restart waits instead, and is not forgotten: the next run, with nothing new
// to download, makes it.
func TestTheInstaPodsUpdateDoesNotRestartAWorkerWhoseJobStartedDuringTheDownload(t *testing.T) {
	r := newUpdateRig(t)

	got := r.run(t, []string{"agent"}, "NEW_BINARY=1", "START_JOB_DURING_DOWNLOAD=1")
	if got.exit != 0 || got.restarts != 0 {
		t.Fatalf("a job started during the download: exit %d, restarts %d, output:\n%s\nwant the app left running so the job survives", got.exit, got.restarts, got.output)
	}
	if !strings.Contains(got.output, "job") || !strings.Contains(got.output, "not restarted") {
		t.Errorf("the output does not say a job held the restart back:\n%s", got.output)
	}

	r.endJob(t)
	got = r.run(t, []string{"agent"})
	if got.exit != 0 || got.restarts != 1 || !strings.Contains(got.output, "now running: zoomies fake-1") {
		t.Errorf("the next run, with the job finished and nothing new to download: exit %d, restarts %d, output:\n%s\nwant the restart that was held back", got.exit, got.restarts, got.output)
	}

	got = r.run(t, []string{"agent"})
	if got.restarts != 0 || !strings.Contains(got.output, "already up to date") {
		t.Errorf("the run after that: restarts %d, output:\n%s\nwant it left alone, the restart having been made", got.restarts, got.output)
	}
}

func TestTheInstaPodsUpdateRestartsAWorkerWithAJobWhenToldTo(t *testing.T) {
	r := newUpdateRig(t)
	got := r.run(t, []string{"--force", "agent"}, "NEW_BINARY=1", "START_JOB_DURING_DOWNLOAD=1")
	if got.exit != 0 || got.restarts != 1 {
		t.Errorf("--force with a job running: exit %d, restarts %d, output:\n%s\nwant the restart made", got.exit, got.restarts, got.output)
	}
}

// With no app service there is nothing to restart: the script says what to run,
// and what it printed after that was "now running", which nothing was.
func TestTheInstaPodsUpdateOnAPodWithNoServiceSaysInstalledNotRunning(t *testing.T) {
	r := newUpdateRig(t)
	got := r.run(t, []string{"agent"}, "NEW_BINARY=1", "NO_SERVICE=1")
	if got.exit != 0 || got.restarts != 0 || !strings.Contains(got.output, "systemctl restart app") {
		t.Fatalf("no app service: exit %d, restarts %d, output:\n%s\nwant the instruction to restart it by hand", got.exit, got.restarts, got.output)
	}
	if strings.Contains(got.output, "now running") || !strings.Contains(got.output, "installed: zoomies fake-1") {
		t.Errorf("no app service, output:\n%s\nwant the version said to be installed, and not to be running", got.output)
	}
}

package docs

import (
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"testing"

	"gopkg.in/yaml.v3"
)

// A run step's default shell is `bash -e {0}`, which has no pipefail. A pipeline
// then ends with the status of its last command, so `make runner-bases | tee
// file` reports tee's success when make fails, and the step goes green over a
// generator that produced nothing. runner-bases.yml did exactly that: a registry
// answering 429 left the weekly refresh green with no pull request, and nothing
// said so. A step that pipes into tee, or pipes out of make or go run, has to
// ask for pipefail first: `set -o pipefail` in the script, or `shell: bash`,
// which GitHub runs with -eo pipefail.

var (
	// A trailing backslash, or a pipe that ends a line, continues the command on
	// the next one.
	shellBackslash = regexp.MustCompile(`\\\n[ \t]*`)
	shellPipeEnd   = regexp.MustCompile(`\|[ \t]*\n[ \t]*`)
	shellQuoted    = regexp.MustCompile(`"[^"]*"|'[^']*'`)
	shellKeywords  = map[string]bool{"if": true, "while": true, "until": true, "!": true, "time": true, "sudo": true, "then": true, "do": true, "else": true}
	shellAssign    = regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*=`)
	shellBoundary  = strings.NewReplacer("&&", ";", "||", ";", "|&", "|", "$(", ";", "(", ";", "`", ";", "{", ";")
	// The patterns of a case arm are separated by pipes too: make|go) is not a
	// pipeline.
	shellCaseArm = regexp.MustCompile(`^\s*[^\s|()]+(?:\|[^\s|()]+)*\)`)
)

// commandWords is a pipeline stage's words with the keywords, variable
// assignments and sudo in front of the command dropped.
func commandWords(stage string) []string {
	words := strings.Fields(stage)
	for len(words) > 0 && (shellKeywords[words[0]] || shellAssign.MatchString(words[0])) {
		words = words[1:]
	}
	return words
}

// pipelinesThatCouldHideAFailure returns the lines of a shell script that pipe
// into tee, or out of make or go run, before anything has set pipefail.
//
// It reads a script the way a person skimming it would, not the way a shell
// does: quoted text is blanked, the separators between commands are told from
// the pipes inside one, and a comment line is ignored. That is enough for the
// two shapes it is looking for, and a line it misreads is named in the failure
// so that it can be rewritten, not argued with.
func pipelinesThatCouldHideAFailure(script string) []string {
	script = shellBackslash.ReplaceAllString(script, " ")
	script = shellPipeEnd.ReplaceAllString(script, "| ")
	var bad []string
	for _, line := range strings.Split(script, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if strings.Contains(line, "pipefail") {
			// Everything from here on is guarded.
			return bad
		}
		code := shellBoundary.Replace(shellQuoted.ReplaceAllString(line, `""`))
		for _, command := range strings.Split(code, ";") {
			stages := strings.Split(shellCaseArm.ReplaceAllString(command, ""), "|")
			if len(stages) < 2 {
				continue
			}
			first := commandWords(stages[0])
			fromABuild := len(first) > 0 && (first[0] == "make" || (len(first) > 1 && first[0] == "go" && first[1] == "run"))
			intoTee := false
			for _, stage := range stages[1:] {
				if words := commandWords(stage); len(words) > 0 && words[0] == "tee" {
					intoTee = true
				}
			}
			if fromABuild || intoTee {
				bad = append(bad, line)
				break
			}
		}
	}
	return bad
}

func TestThePipelineCheckSeesTheShapesThatHideAFailure(t *testing.T) {
	for _, tc := range []struct {
		name   string
		script string
		bad    bool
	}{
		{"make piped into tee, as runner-bases.yml had it", `make runner-bases | tee "$RUNNER_TEMP/moved.txt"`, true},
		{"go run piped anywhere", "go run ./tools/gen | sort > out.txt", true},
		{"anything piped into tee", `echo "$value" | tee out.txt`, true},
		{"a continuation line", "make runner-bases \\\n  | tee out.txt", true},
		{"a pipe that ends a line", "make runner-bases |\n  tee out.txt", true},
		{"inside a condition", `if make check | tee out.txt; then echo ok; fi`, true},
		{"inside a command substitution", `moved=$(make runner-bases | tee out.txt)`, true},
		{"after another command", "cd dir && make runner-bases | tee out.txt", true},
		{"after pipefail is set", "set -eu -o pipefail\nmake runner-bases | tee out.txt", false},
		{"pipefail set in the same line", "set -o pipefail; make runner-bases | tee out.txt", false},
		{"pipefail asked for only afterwards", "make runner-bases | tee out.txt\nset -o pipefail", true},
		{"pipefail named only in a comment", "# set -o pipefail\nmake runner-bases | tee out.txt", true},
		{"no pipe at all", "make runner-bases > out.txt\ncat out.txt", false},
		{"a case pattern is not a pipeline", "case \"$f\" in\n  make|go) echo build ;;\n  deploy/*|docker-compose.yml) echo deploy ;;\nesac", false},
		{"a logical or is not a pipe", "make runner-bases || echo failed", false},
		{"a pipe inside quotes", `echo "make x | tee y"`, false},
		{"a comment", "# make runner-bases | tee out.txt", false},
		{"a pipeline from something that is not a build", "go list ./... | grep -v internal/api", false},
		{"a pipeline that only reads", "git diff --name-only | grep -q workflows", false},
		{"bash's pipe that takes standard error too", `echo "$value" |& tee out.txt`, true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := pipelinesThatCouldHideAFailure(tc.script); (len(got) > 0) != tc.bad {
				t.Errorf("script:\n%s\nflagged %v, want flagged=%v", tc.script, got, tc.bad)
			}
		})
	}
}

// A step is checked in the shell it will run in: its own, else its job's, else
// the workflow's. `shell: bash` is the explicit form of bash with pipefail, and
// a Windows step is not a POSIX shell at all.
type shellSteps struct {
	Defaults struct {
		Run struct {
			Shell string `yaml:"shell"`
		} `yaml:"run"`
	} `yaml:"defaults"`
	Steps []struct {
		Name  string `yaml:"name"`
		Run   string `yaml:"run"`
		Shell string `yaml:"shell"`
	} `yaml:"steps"`
}

func TestEveryWorkflowPipelineThatCouldHideAFailureSetsPipefail(t *testing.T) {
	files := map[string]string{}
	for name, body := range workflowFiles(t) {
		files[".github/workflows/"+name] = body
	}
	actions, err := filepath.Glob("../../.github/actions/*/action.yml")
	if err != nil {
		t.Fatal(err)
	}
	for _, path := range actions {
		body, err := os.ReadFile(path)
		if err != nil {
			t.Fatal(err)
		}
		files[strings.TrimPrefix(filepath.ToSlash(path), "../../")] = string(body)
	}

	var offences []string
	checked := 0
	for name, body := range files {
		var doc struct {
			Defaults struct {
				Run struct {
					Shell string `yaml:"shell"`
				} `yaml:"run"`
			} `yaml:"defaults"`
			Jobs map[string]shellSteps `yaml:"jobs"`
			Runs shellSteps            `yaml:"runs"`
		}
		if err := yaml.Unmarshal([]byte(body), &doc); err != nil {
			t.Fatalf("parsing %s: %v", name, err)
		}
		jobs := doc.Jobs
		if jobs == nil {
			jobs = map[string]shellSteps{"(composite action)": doc.Runs}
		}
		for jobName, job := range jobs {
			for i, step := range job.Steps {
				if step.Run == "" {
					continue
				}
				checked++
				shell := step.Shell
				if shell == "" {
					shell = job.Defaults.Run.Shell
				}
				if shell == "" {
					shell = doc.Defaults.Run.Shell
				}
				switch {
				case shell == "bash" || strings.Contains(shell, "pipefail"):
					continue
				case shell == "pwsh" || shell == "powershell" || shell == "cmd" || strings.HasPrefix(shell, "python"):
					continue
				}
				for _, line := range pipelinesThatCouldHideAFailure(step.Run) {
					offences = append(offences, name+", job "+jobName+", step "+strconv.Itoa(i+1)+" ("+step.Name+"): "+line)
				}
			}
		}
	}
	if checked == 0 {
		t.Fatal("no run steps were found; this test is reading the workflows wrongly")
	}
	sort.Strings(offences)
	if len(offences) > 0 {
		t.Errorf("a pipeline into tee, or out of make or go run, reports the status of its last command, so it goes green when the first one fails.\n"+
			"Start the script with `set -o pipefail`, or set `shell: bash` on the step:\n  %s", strings.Join(offences, "\n  "))
	}
}

// Package events is the in-process publish/subscribe bus that makes the UI
// live.
//
// Every state change the operator would want to see -- a runner changing state,
// a scaling decision, a job starting -- is published here, and the API's
// Server-Sent Events endpoint fans it out to browsers. There is no polling
// anywhere in the UI.
package events

import (
	"context"
	"encoding/json"
	"log/slog"
	"slices"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"time"
)

// Kind names an event type. The UI switches on these to decide what to update,
// so they are part of the API's contract.
type Kind string

const (
	KindRunnerCreated Kind = "runner.created"
	KindRunnerUpdated Kind = "runner.updated"
	KindRunnerDeleted Kind = "runner.deleted"
	KindPoolCreated   Kind = "pool.created"
	KindPoolUpdated   Kind = "pool.updated"
	KindPoolDeleted   Kind = "pool.deleted"
	KindJobUpdated    Kind = "job.updated"
	KindHostUpdated   Kind = "host.updated"
	KindHostDeleted   Kind = "host.deleted"
	KindScaling       Kind = "scaling"
	KindInstallation  Kind = "installation.updated"
	// KindInstallationDeleted is sent when an installation is removed; the
	// pools that depended on it go with it, each with its own pool.deleted.
	KindInstallationDeleted Kind = "installation.deleted"
	// The provider and machine kinds carry the same JSON their GET routes
	// return, as every other resource frame does. A machine is deleted from
	// the page only when its row goes -- the row outlives the resource on
	// purpose -- so machine.deleted is the prune's frame rather than the
	// hypervisor's.
	KindProviderUpdated Kind = "provider.updated"
	KindProviderDeleted Kind = "provider.deleted"
	KindMachineUpdated  Kind = "machine.updated"
	KindMachineDeleted  Kind = "machine.deleted"
	// The Kennel Club kinds follow the same rule. kennel.updated is one
	// repository exactly as GET /kennel/repositories/{id} returns it, and
	// kennel.deleted is the id of one that is gone -- pruned, or taken away with
	// its installation. kennel.summary is the Overview's document, computed and
	// sent only when it changes, as stats and problems.updated are: nothing
	// writes a row when a repository's last evaluation ages, so nothing could
	// announce it.
	KindKennelUpdated Kind = "kennel.updated"
	KindKennelDeleted Kind = "kennel.deleted"
	KindKennelSummary Kind = "kennel.summary"
	KindProblems      Kind = "problems.updated"
	KindStats         Kind = "stats"
	KindAudit         Kind = "audit"
	KindWebhook       Kind = "webhook.delivery"
	// KindUpdates is the update status, in the shape GET /updates returns. Like
	// stats and kennel.summary it is computed and sent only when it changes: a
	// soak ends with no row written, so nothing but the pass that notices could
	// announce it.
	KindUpdates Kind = "updates.updated"
	// KindTransfer is an instance transfer's preparation, in the shape
	// GET /transfers/preparation returns. Computed and sent when it changes,
	// as updates.updated is: a runner confirmed gone or a job finishing moves
	// the counts without any row saying "the transfer moved", and the page
	// an operator watches while the fleet drains is the one that should not
	// need reloading.
	KindTransfer Kind = "transfer.updated"
	// KindHeartbeat is an empty keep-alive so that proxies do not close an
	// idle SSE connection.
	KindHeartbeat Kind = "heartbeat"
	// KindResync tells a client that what it holds may be stale and it should
	// fetch the resources afresh: the events between its last ID and now could
	// not all be replayed -- the ring had moved on, or the controller
	// restarted and the IDs began again -- or too much was deleted at once to
	// announce row by row. It is never in the ring, because it is true of the
	// connections it was sent to and of no connection made afterwards; the
	// SSE handler writes its own directly, and the controller sends one with
	// Bus.PublishTransient.
	KindResync Kind = "resync"
)

// Event is one published change.
type Event struct {
	// ID is a monotonic sequence number, sent as the SSE event id so a
	// reconnecting client can say where it left off.
	ID   uint64 `json:"id"`
	Kind Kind   `json:"kind"`
	// Topic narrows the event, e.g. "runner:run_abc" or "pool:pool_xyz".
	// Subscribers may filter on it.
	Topic string `json:"topic,omitempty"`
	// Data is the payload, already marshalled by the publisher.
	Data json.RawMessage `json:"data,omitempty"`
	At   time.Time       `json:"at"`
}

// Bus fans events out to subscribers.
//
// A slow subscriber is cut off rather than allowed to block the publisher: an
// operator whose browser tab is wedged must not stop the fleet from scaling.
// Cut off, not thinned: its feed ends, the SSE handler closes the response,
// and the browser reconnects with its last event ID and catches up from the
// ring. Dropping single events would leave that tab quietly showing a fleet
// that no longer exists, with no polling to ever put it right.
type Bus struct {
	mu     sync.RWMutex
	subs   map[int]*subscriber
	nextID int
	seq    atomic.Uint64

	// epoch names this process's run. Event IDs restart at one with every
	// controller start, so a client's Last-Event-ID from before a restart is
	// a number from a different sequence -- usually one this process has not
	// reached yet, which replayed nothing and said nothing. The epoch travels
	// with the ID on the wire so a client that comes back with the wrong one
	// is told to resynchronise instead.
	epoch string

	// buffer is the per-subscriber queue depth. It is deliberately larger
	// than ringCap: a subscriber is handed the whole replay before it has
	// read a byte, so a queue only as deep as the ring is full at the moment
	// it is created, and the next publish -- one already waiting on this same
	// lock, on a fleet busy enough to have filled the ring -- would drop it.
	// The tab reconnects, replays a full ring again and is dropped again.
	buffer int
	// ring keeps recent events so a client that reconnects within a few
	// seconds does not miss anything.
	ring    []Event
	ringCap int
}

type subscriber struct {
	id     int
	ch     chan Event
	filter func(Event) bool
	class  string
}

// New returns a bus with sensible queue depths.
func New() *Bus {
	return &Bus{
		subs:    map[int]*subscriber{},
		epoch:   strconv.FormatInt(time.Now().UnixNano(), 36),
		buffer:  512,
		ringCap: 256,
	}
}

// Epoch identifies this process's run of the sequence; see Bus.epoch.
func (b *Bus) Epoch() string { return b.epoch }

// WireID renders an event ID for the wire: the epoch, a dot, the sequence
// number. ParseWireID reads it back.
func (b *Bus) WireID(id uint64) string {
	return b.epoch + "." + strconv.FormatUint(id, 10)
}

// ParseWireID reads a Last-Event-ID the client sent back. It returns the
// sequence number to replay from and whether that number belongs to this
// process's sequence at all; a bare number, from a client that predates the
// epoch, is taken as this epoch's so an upgrade does not resync every tab for
// nothing.
func (b *Bus) ParseWireID(raw string) (id uint64, sameEpoch bool) {
	raw = strings.TrimSpace(raw)
	epoch, seq, dotted := strings.Cut(raw, ".")
	if !dotted {
		seq, epoch = raw, b.epoch
	}
	n, err := strconv.ParseUint(seq, 10, 64)
	if err != nil {
		return 0, false
	}
	return n, epoch == b.epoch
}

// Publish marshals v and delivers it to every matching subscriber. Marshalling
// failures are logged rather than returned, because a publisher in the middle
// of a reconcile has nothing useful to do with the error.
func (b *Bus) Publish(kind Kind, topic string, v any) {
	if e, ok := frame(kind, topic, v); ok {
		b.publish(e, true)
	}
}

// PublishTransient is Publish for a frame that must reach the subscribers who
// are here now and must never be replayed to one that arrives later.
//
// KindResync is the whole of it: it says "what you hold may be stale, fetch
// the resources again", which is true of the tab it was sent to and says
// nothing about a tab that connects afterwards -- that one is already fetching
// everything. Replaying it would send a client that has just loaded the fleet
// straight back to load it again.
func (b *Bus) PublishTransient(kind Kind, topic string, v any) {
	if e, ok := frame(kind, topic, v); ok {
		b.publish(e, false)
	}
}

// frame renders a payload into an unnumbered event, or reports that it could
// not be. The number is publish's to draw, under the lock.
func frame(kind Kind, topic string, v any) (Event, bool) {
	var raw json.RawMessage
	if v != nil {
		enc, err := json.Marshal(v)
		if err != nil {
			slog.Error("events: could not marshal payload", "kind", kind, "error", err)
			return Event{}, false
		}
		raw = enc
	}
	return Event{Kind: kind, Topic: topic, Data: raw, At: time.Now().UTC()}, true
}

// publish numbers the event, appends it to the ring and hands it to every
// subscriber.
//
// The number is drawn here, under the lock, rather than by the caller. Drawing
// it first and taking the lock afterwards let two publishers -- the reconcile
// loop and an API handler, say -- enter the ring in the opposite order to their
// numbers, and the wire with them. A browser handed 6 before 5 reconnects with
// 6 as its last id and never sees 5 again, while Subscribe still reports the
// replay complete because the ring's oldest id is no longer its lowest. There
// is no polling to put that right, so the tab quietly shows a fleet that has
// moved on.
//
// The sends happen under the lock on purpose. Close closes a subscriber's
// channel under that same lock, and a send on a closed channel panics even
// from a select with a default case -- so sending from a snapshot taken
// before releasing the lock let a browser tab closing at the wrong instant
// panic whichever loop was publishing, and the reconcile loop does not come
// back from that. Every send here is non-blocking, so holding the lock costs
// the other publishers microseconds.
// It still draws a number when it is not kept: the number is what a client
// comes back with, and a frame delivered without one would have the client
// resume from before it and be sent the events it has already seen.
func (b *Bus) publish(e Event, keep bool) {
	b.mu.Lock()
	defer b.mu.Unlock()
	e.ID = b.seq.Add(1)
	if keep && b.ringCap > 0 {
		b.ring = append(b.ring, e)
		if len(b.ring) > b.ringCap {
			b.ring = b.ring[len(b.ring)-b.ringCap:]
		}
	}

	for _, s := range b.subs {
		if s.filter != nil && !s.filter(e) {
			continue
		}
		select {
		case s.ch <- e:
		default:
			// The subscriber is not keeping up. Ending its feed here, under
			// the same lock Close takes and after removing it from the map,
			// is what stops Close from closing the channel a second time.
			// What it has already been handed stays in the channel for it to
			// drain; only then does it see the end and reconnect.
			slog.Warn("events: subscriber is behind; ending its feed so the client resynchronises",
				"subscriber", s.id, "buffer", b.buffer)
			delete(b.subs, s.id)
			close(s.ch)
		}
	}
}

// Subscription is a live event feed.
type Subscription struct {
	C   <-chan Event
	bus *Bus
	id  int
	// Complete reports whether the subscriber has everything it asked for: a
	// subscription that asked for no replay, or one whose Replay the ring
	// still reached back to. When it is false the client missed events it
	// will never be sent, and the SSE handler tells it so with a resync
	// frame before anything else.
	Complete bool
	// done is closed by Close, so the goroutine Subscribe starts to watch the
	// context ends with the subscription. Without it a subscription closed by
	// hand under a context that never ends -- the SSE handler closes its own
	// before the request's context is cancelled -- left one goroutine waiting
	// per connection for the life of the process.
	done chan struct{}
	// once makes Close idempotent AND race-free. Both matter: Subscribe spawns
	// a goroutine that closes the subscription when the context ends, so an
	// explicit Close from the handler and that goroutine routinely run at the
	// same time. An earlier version cleared s.bus at the end of Close, which
	// was an unsynchronised write to a field the other caller was reading.
	once sync.Once
}

// Close unsubscribes. It is safe to call more than once and from more than one
// goroutine at a time.
func (s *Subscription) Close() {
	if s == nil || s.bus == nil {
		return
	}
	s.once.Do(func() {
		s.bus.mu.Lock()
		if sub, ok := s.bus.subs[s.id]; ok {
			delete(s.bus.subs, s.id)
			close(sub.ch)
		}
		s.bus.mu.Unlock()
		if s.done != nil {
			close(s.done)
		}
	})
}

// SubscribeOptions narrows a subscription.
type SubscribeOptions struct {
	// Kinds, when non-empty, limits delivery to these event kinds.
	Kinds []Kind
	// TopicPrefix, when non-empty, limits delivery to matching topics.
	TopicPrefix string
	// Replay delivers buffered events with an ID greater than this before any
	// new ones, so a reconnecting client can catch up.
	Replay uint64
	// Incomplete says the caller already knows the client missed events --
	// its Last-Event-ID was from another run of the process -- so the
	// subscription is marked incomplete whatever the ring holds.
	Incomplete bool
	// Class sets a subscription apart under a ceiling of its own, ClassLimit,
	// instead of the one SubscribeWithin is given. A public view's visitors
	// are a class: a crowd of them must never fill the streams the people who
	// run the fleet need, so they neither count against that ceiling nor are
	// counted by it. Empty is the ordinary, unclassed subscription.
	Class string
	// ClassLimit caps the open subscriptions of Class. Zero is no ceiling.
	ClassLimit int
}

// Matches is the predicate a subscription, a replay and a read of the ring all
// share, so none of them can disagree about which events match. It is exported
// for the readers outside this package that select from a copy of the ring.
func (o SubscribeOptions) Matches(e Event) bool {
	if len(o.Kinds) > 0 && !slices.Contains(o.Kinds, e.Kind) {
		return false
	}
	if o.TopicPrefix != "" && !strings.HasPrefix(e.Topic, o.TopicPrefix) {
		return false
	}
	return true
}

// replayLocked returns the ringed events after since that pass filter, and
// whether the ring still covers the whole gap. The caller holds b.mu, so the
// answer is one instant's: a subscription takes it under the lock that also
// registers the feed, and Recent under the lock that publish numbers events
// with. Zero means "from the start of the ring" and is always complete; it is
// SubscribeWithin's job to ask for no replay at all.
func (b *Bus) replayLocked(since uint64, filter func(Event) bool) ([]Event, bool) {
	complete := true
	if since > 0 {
		// The ring covers the gap when the event after since is still in it,
		// or when nothing has been published since. A since beyond the
		// sequence is from another run of the process and covers nothing.
		last := b.seq.Load()
		switch {
		case since > last:
			complete = false
		case since == last:
		case len(b.ring) == 0 || b.ring[0].ID > since+1:
			complete = false
		}
	}
	var out []Event
	for _, e := range b.ring {
		if e.ID > since && filter(e) {
			out = append(out, e)
		}
	}
	return out, complete
}

// Recent answers "what happened since event id since" from the ring, with the
// events and the completeness a reconnecting stream would be given for the
// same id. Zero returns everything the ring holds. limit, when positive, keeps
// the oldest limit matches and reports truncated if more remained, so a caller
// paging forward resumes from the last id it was handed.
func (b *Bus) Recent(since uint64, opts SubscribeOptions, limit int) (items []Event, complete, truncated bool) {
	b.mu.RLock()
	items, complete = b.replayLocked(since, opts.Matches)
	b.mu.RUnlock()
	if limit > 0 && len(items) > limit {
		items, truncated = items[:limit], true
	}
	return items, complete, truncated
}

// Subscribe returns a feed. The caller must Close it.
func (b *Bus) Subscribe(ctx context.Context, opts SubscribeOptions) *Subscription {
	s, _ := b.SubscribeWithin(ctx, opts, 0)
	return s
}

// SubscribeWithin is Subscribe with a ceiling on how many feeds may be open,
// reporting false and subscribing nothing when limit are already open. Zero
// is no ceiling. A subscription with a Class is held to its ClassLimit
// instead, and the two ceilings count only their own: see Class.
//
// The count and the subscription are taken under the one lock, so a burst of
// streams opened together cannot all see room for one and all take it.
func (b *Bus) SubscribeWithin(ctx context.Context, opts SubscribeOptions, limit int) (*Subscription, bool) {
	filter := opts.Matches

	ceiling := limit
	if opts.Class != "" {
		ceiling = opts.ClassLimit
	}
	b.mu.Lock()
	if ceiling > 0 && b.countLocked(opts.Class) >= ceiling {
		b.mu.Unlock()
		return nil, false
	}
	ch := make(chan Event, b.buffer)
	b.nextID++
	sub := &subscriber{id: b.nextID, ch: ch, filter: filter, class: opts.Class}
	b.subs[sub.id] = sub
	// Replay under the same lock so an event cannot slip between the replay
	// and the subscription taking effect.
	complete := true
	if opts.Replay > 0 {
		var replay []Event
		replay, complete = b.replayLocked(opts.Replay, filter)
		for _, e := range replay {
			select {
			case ch <- e:
			default:
				// The queue is deeper than the ring, so this is not
				// reachable -- but a replay that silently dropped a frame
				// while still calling itself complete is the one outcome
				// this whole path exists to prevent, so say so instead.
				complete = false
			}
		}
	}
	if opts.Incomplete {
		complete = false
	}
	b.mu.Unlock()

	s := &Subscription{C: ch, bus: b, id: sub.id, Complete: complete, done: make(chan struct{})}
	if ctx != nil {
		go func() {
			select {
			case <-ctx.Done():
				s.Close()
			case <-s.done:
			}
		}()
	}
	return s, true
}

// Subscribers returns the current subscriber count, which the UI shows on the
// Settings page as a sanity check that live updates are wired up.
func (b *Bus) Subscribers() int {
	b.mu.RLock()
	defer b.mu.RUnlock()
	return len(b.subs)
}

// ClassSubscribers returns how many subscriptions of class are open; the
// empty class is the ordinary ones.
func (b *Bus) ClassSubscribers(class string) int {
	b.mu.RLock()
	defer b.mu.RUnlock()
	return b.countLocked(class)
}

// countLocked counts the open subscriptions of one class. A walk rather than
// a running count: the set is a few hundred at most, and a count kept beside
// it is one more thing every close has to remember to keep right.
func (b *Bus) countLocked(class string) int {
	n := 0
	for _, s := range b.subs {
		if s.class == class {
			n++
		}
	}
	return n
}

// LastID returns the most recently issued event ID.
func (b *Bus) LastID() uint64 { return b.seq.Load() }

package events

import (
	"context"
	"strconv"
	"testing"
	"time"
)

// Every state change in the fleet is published here, from the middle of a
// reconcile pass, and the bus holds its lock while it offers the frame to each
// subscriber in turn. That time is time the pass is not scaling anything, and
// it grows with the number of browser tabs open. These benchmarks size Publish
// against the number of subscribers, and Subscribe, whose queue is large enough
// to be worth knowing the price of every time a tab connects.

// benchFrame stands in for the payload of a resource frame, which the
// controller publishes as the same JSON its GET route returns. A runner's has
// over forty fields, most of them left out when empty, and carries the job it
// is holding while it holds one, so this smaller stand-in (a dozen scalar
// fields, two times and a list of labels: 394 bytes) gives a lower bound on
// what publishing a real frame costs. What it costs to deliver a frame to each
// subscriber does not depend on its size.
type benchFrame struct {
	ID         string     `json:"id"`
	Name       string     `json:"name"`
	PoolID     string     `json:"pool_id"`
	PoolName   string     `json:"pool_name"`
	HostID     string     `json:"host_id"`
	State      string     `json:"state"`
	Backend    string     `json:"backend"`
	Image      string     `json:"image"`
	Labels     []string   `json:"labels"`
	CPUs       float64    `json:"cpus"`
	MemoryMB   int64      `json:"memory_mb"`
	Ephemeral  bool       `json:"ephemeral"`
	CreatedAt  time.Time  `json:"created_at"`
	LastIdleAt *time.Time `json:"last_idle_at,omitempty"`
	JobID      string     `json:"current_job_id,omitempty"`
}

func newBenchFrame() benchFrame {
	created := time.Date(2025, 3, 4, 12, 0, 0, 0, time.UTC)
	idle := created.Add(2 * time.Minute)
	return benchFrame{
		ID: "run_8f3k2m1q9x", Name: "zoomies-linux-x64-8f3k2m1q9x", PoolID: "pool_a1b2c3d4e5",
		PoolName: "linux-x64", HostID: "host_p9o8i7u6y5", State: "idle", Backend: "docker",
		Image:  "ghcr.io/eyupio/zoomies-runner:ubuntu-24.04",
		Labels: []string{"self-hosted", "linux", "x64", "zoomies"}, CPUs: 2, MemoryMB: 4096,
		Ephemeral: true, CreatedAt: created, LastIdleAt: &idle,
	}
}

func BenchmarkPublish(b *testing.B) {
	frame := newBenchFrame()
	for _, tc := range []struct {
		name        string
		subscribers int
		opts        SubscribeOptions
		// delivered says the frame reaches every subscriber. A filter that
		// turns it away still costs a test per subscriber and delivers nothing.
		delivered bool
	}{
		{name: "subscribers=0", delivered: true},
		{name: "subscribers=1", subscribers: 1, delivered: true},
		{name: "subscribers=10", subscribers: 10, delivered: true},
		{name: "subscribers=100", subscribers: 100, delivered: true},
		{
			name:        "subscribers=100,filtered_out",
			subscribers: 100,
			opts:        SubscribeOptions{Kinds: []Kind{KindPoolUpdated}, TopicPrefix: "pool:"},
		},
	} {
		b.Run(tc.name, func(b *testing.B) {
			bus := New()
			subs := make([]*Subscription, tc.subscribers)
			for i := range subs {
				subs[i] = bus.Subscribe(context.Background(), tc.opts)
			}
			b.Cleanup(func() {
				for _, s := range subs {
					s.Close()
				}
			})

			// The subscribers are emptied from the benchmark's own goroutine,
			// every half queue, so that none is ever cut off for falling
			// behind (which would end its feed and log a warning, and make
			// the numbers about something else). That puts the receive in the
			// timing, so the figure is the whole cost of delivering a frame
			// and not only the publisher's share, and it spares the numbers
			// the scheduler noise of a goroutine for each subscriber.
			drain := func() {
				for _, s := range subs {
					for len(s.C) > 0 {
						<-s.C
					}
				}
			}
			every := bus.buffer / 2

			want := 0
			if tc.delivered {
				want = 1
			}
			bus.Publish(KindRunnerUpdated, "runner:run_bench", frame)
			for i, s := range subs {
				if got := len(s.C); got != want {
					b.Fatalf("subscriber %d holds %d frames after one publish, want %d", i, got, want)
				}
			}
			drain()

			b.ReportAllocs()
			sent := 0
			for b.Loop() {
				bus.Publish(KindRunnerUpdated, "runner:run_bench", frame)
				if sent++; sent == every {
					sent = 0
					drain()
				}
			}
		})
	}
}

// BenchmarkSubscribe is a browser tab connecting and leaving. Each feed is a
// queue of 512 events, about 45 KB allocated and cleared whether or not
// anything ever fills it, so a controller restart that brings every open tab
// back in the same second is that cost times the tabs.
func BenchmarkSubscribe(b *testing.B) {
	ctx := context.Background()

	b.Run("no_replay", func(b *testing.B) {
		bus := New()
		b.ReportAllocs()
		for b.Loop() {
			bus.Subscribe(ctx, SubscribeOptions{}).Close()
		}
	})

	// A tab that reconnects with the last event it saw is handed everything
	// the ring has kept since, under the lock every publisher is waiting on.
	// This is the full ring, which is what a tab that was away for a few
	// seconds on a busy fleet is given.
	b.Run("full_ring_replay", func(b *testing.B) {
		bus := New()
		frame := newBenchFrame()
		for range bus.ringCap + 50 {
			bus.Publish(KindRunnerUpdated, "runner:run_bench", frame)
		}
		since := bus.LastID() - uint64(bus.ringCap)
		sub := bus.Subscribe(ctx, SubscribeOptions{Replay: since})
		if !sub.Complete || len(sub.C) != bus.ringCap {
			b.Fatalf("replay holds %d of %d ringed events, complete = %v", len(sub.C), bus.ringCap, sub.Complete)
		}
		sub.Close()

		b.ReportAllocs()
		for b.Loop() {
			bus.Subscribe(ctx, SubscribeOptions{Replay: since}).Close()
		}
	})
}

// BenchmarkPublishParallel is Publish called from every core at once, which is
// what happens when the reconcile loop, an API handler and a webhook each
// announce a change in the same instant. The payload is encoded in parallel;
// the numbering, the ring and the walk over the subscribers take the one lock
// in turn, so the more subscribers there are to walk, the longer each publisher
// holds the others up. Run it with -cpu 1,2,4 to see whether ns/op falls as
// cores are added: if the lock were the whole cost it would not.
//
// The subscribers here turn every frame away. One that received frames would
// need a consumer keeping up with publishers on every core, and none can: the
// goroutine that drains it is starved of a core, its queue fills, and the bus
// does what it is built to do and cuts it off, which is a different thing to
// time. The benchmark fails if any were.
func BenchmarkPublishParallel(b *testing.B) {
	frame := newBenchFrame()
	for _, tc := range []struct {
		name        string
		subscribers int
	}{
		{"subscribers=0", 0},
		{"subscribers=100,filtered_out", 100},
	} {
		b.Run(tc.name, func(b *testing.B) {
			bus := New()
			opts := SubscribeOptions{Kinds: []Kind{KindPoolUpdated}, TopicPrefix: "pool:"}
			for range tc.subscribers {
				s := bus.Subscribe(context.Background(), opts)
				b.Cleanup(s.Close)
			}

			b.ReportAllocs()
			b.RunParallel(func(pb *testing.PB) {
				for pb.Next() {
					bus.Publish(KindRunnerUpdated, "runner:run_bench", frame)
				}
			})
			if open := bus.Subscribers(); open != tc.subscribers {
				b.Fatalf("%d of %d subscribers were cut off for falling behind", tc.subscribers-open, tc.subscribers)
			}
		})
	}
}

// BenchmarkRecent is a read of the ring, as the recent-events routes and the
// MCP wait make it: every event it holds put through a filter and copied out
// under the read lock that each publisher has to wait for.
func BenchmarkRecent(b *testing.B) {
	bus := New()
	frame := newBenchFrame()
	kinds := []Kind{KindRunnerUpdated, KindPoolUpdated, KindJobUpdated, KindHostUpdated}
	for i := range bus.ringCap {
		bus.Publish(kinds[i%len(kinds)], "x:"+strconv.Itoa(i), frame)
	}

	for _, tc := range []struct {
		name string
		opts SubscribeOptions
		want int
	}{
		{"everything", SubscribeOptions{}, bus.ringCap},
		{"one_kind_in_four", SubscribeOptions{Kinds: []Kind{KindJobUpdated}}, bus.ringCap / 4},
	} {
		b.Run(tc.name, func(b *testing.B) {
			if got, complete, _ := bus.Recent(0, tc.opts, 0); len(got) != tc.want || !complete {
				b.Fatalf("the ring gave %d events (complete = %v), want %d", len(got), complete, tc.want)
			}

			b.ReportAllocs()
			for b.Loop() {
				bus.Recent(0, tc.opts, 0)
			}
		})
	}
}

package events

import (
	"context"
	"encoding/json"
	"runtime"
	"strings"
	"sync"
	"testing"
	"time"
)

func TestPublishReachesSubscribers(t *testing.T) {
	b := New()
	sub := b.Subscribe(context.Background(), SubscribeOptions{})
	defer sub.Close()

	b.Publish(KindRunnerUpdated, "runner:run_1", map[string]string{"state": "idle"})

	select {
	case e := <-sub.C:
		if e.Kind != KindRunnerUpdated {
			t.Errorf("kind = %s, want %s", e.Kind, KindRunnerUpdated)
		}
		if e.Topic != "runner:run_1" {
			t.Errorf("topic = %q", e.Topic)
		}
		var got map[string]string
		if err := json.Unmarshal(e.Data, &got); err != nil {
			t.Fatalf("payload: %v", err)
		}
		if got["state"] != "idle" {
			t.Errorf("payload = %v", got)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("no event arrived")
	}
}

func TestSubscribeFiltersByKindAndTopic(t *testing.T) {
	b := New()
	sub := b.Subscribe(context.Background(), SubscribeOptions{
		Kinds:       []Kind{KindRunnerUpdated},
		TopicPrefix: "runner:",
	})
	defer sub.Close()

	b.Publish(KindPoolUpdated, "pool:p1", nil)     // wrong kind
	b.Publish(KindRunnerUpdated, "host:h1", nil)   // wrong topic
	b.Publish(KindRunnerUpdated, "runner:r1", nil) // both right

	select {
	case e := <-sub.C:
		if e.Topic != "runner:r1" {
			t.Fatalf("got %s/%s; the filter let the wrong event through", e.Kind, e.Topic)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("the matching event never arrived")
	}
}

func TestReplayDeliversMissedEvents(t *testing.T) {
	b := New()
	b.Publish(KindScaling, "", map[string]int{"n": 1})
	after := b.LastID()
	b.Publish(KindScaling, "", map[string]int{"n": 2})

	// A client reconnecting with Last-Event-ID should be given what it missed.
	sub := b.Subscribe(context.Background(), SubscribeOptions{Replay: after})
	defer sub.Close()

	select {
	case e := <-sub.C:
		if e.ID != after+1 {
			t.Errorf("replayed event ID = %d, want %d", e.ID, after+1)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("nothing was replayed")
	}
}

func TestSlowSubscriberIsCutOffNotBlocking(t *testing.T) {
	b := New()
	b.buffer = 2
	sub := b.Subscribe(context.Background(), SubscribeOptions{})
	defer sub.Close()

	// A wedged browser tab must not be able to stop the fleet from scaling, so
	// publishing past a full queue never blocks.
	done := make(chan struct{})
	go func() {
		for i := 0; i < 500; i++ {
			b.Publish(KindHeartbeat, "", nil)
		}
		close(done)
	}()
	select {
	case <-done:
	case <-time.After(5 * time.Second):
		t.Fatal("Publish blocked on a subscriber that was not reading")
	}

	// And the subscriber that fell behind is told so, by its feed ending. A
	// stream quietly thinned by dropped events would leave its dashboard wrong
	// until somebody reloaded it; an ended stream makes the browser reconnect
	// and replay. It keeps what it had already been handed.
	received := 0
	for range sub.C {
		received++
	}
	if received != b.buffer {
		t.Fatalf("received %d buffered events before the feed ended, want %d", received, b.buffer)
	}
	if n := b.Subscribers(); n != 0 {
		t.Fatalf("%d subscribers remain after the slow one was cut off, want 0", n)
	}
}

// Subscribe spawns a goroutine that closes the subscription when the context
// ends, so an explicit Close and that goroutine routinely race. Run this with
// -race: it is the regression test for an unsynchronised write in Close.
func TestCloseIsSafeConcurrentlyAndRepeatedly(t *testing.T) {
	b := New()
	for i := 0; i < 50; i++ {
		ctx, cancel := context.WithCancel(context.Background())
		sub := b.Subscribe(ctx, SubscribeOptions{})

		var wg sync.WaitGroup
		wg.Add(3)
		go func() { defer wg.Done(); cancel() }()
		go func() { defer wg.Done(); sub.Close() }()
		go func() { defer wg.Done(); sub.Close() }()
		wg.Wait()
		cancel()
	}
	// Give the context watchers a moment, then assert nothing leaked.
	deadline := time.Now().Add(2 * time.Second)
	for time.Now().Before(deadline) && b.Subscribers() != 0 {
		time.Sleep(10 * time.Millisecond)
	}
	if n := b.Subscribers(); n != 0 {
		t.Errorf("%d subscriptions leaked", n)
	}
}

func TestContextCancellationUnsubscribes(t *testing.T) {
	b := New()
	ctx, cancel := context.WithCancel(context.Background())
	b.Subscribe(ctx, SubscribeOptions{})
	if b.Subscribers() != 1 {
		t.Fatalf("subscribers = %d, want 1", b.Subscribers())
	}
	cancel()
	deadline := time.Now().Add(2 * time.Second)
	for time.Now().Before(deadline) && b.Subscribers() != 0 {
		time.Sleep(10 * time.Millisecond)
	}
	if n := b.Subscribers(); n != 0 {
		t.Errorf("subscribers = %d after cancellation, want 0", n)
	}
}

// A subscriber closing while a publish is in flight is the everyday case: a
// browser tab closes and its SSE handler's context ends while the reconcile
// loop is announcing a state change. Sending on the closed channel panics,
// and the loop that was publishing does not come back from a panic.
func TestPublishRacesClose(t *testing.T) {
	b := New()
	for i := 0; i < 2000; i++ {
		sub := b.Subscribe(context.Background(), SubscribeOptions{})
		var wg sync.WaitGroup
		wg.Add(2)
		go func() {
			defer wg.Done()
			b.Publish(KindRunnerUpdated, "runner:r1", map[string]string{"id": "r1"})
		}()
		go func() {
			defer wg.Done()
			sub.Close()
		}()
		wg.Wait()
	}
	if n := b.Subscribers(); n != 0 {
		t.Errorf("%d subscriptions leaked", n)
	}
}

// Replay used to be silent about what it could not do: a client whose last id
// predated the ring, or whose id came from before a restart, was handed
// nothing and told nothing. Subscribe now says whether the gap was covered.
func TestReplayReportsWhetherItCoveredTheGap(t *testing.T) {
	b := New()
	b.ringCap = 3
	for i := range 6 {
		b.Publish(KindScaling, "", map[string]int{"n": i})
	}
	last := b.LastID()

	cases := []struct {
		name     string
		replay   uint64
		complete bool
	}{
		{"a fresh subscription asks for nothing and misses nothing", 0, true},
		{"the id just before the ring's oldest is covered", last - 3, true},
		{"an id the ring no longer reaches back to is not", 1, false},
		{"the latest id, with nothing since, is covered", last, true},
		{"an id from another run of the process is not", last + 40, false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			sub := b.Subscribe(context.Background(), SubscribeOptions{Replay: tc.replay})
			defer sub.Close()
			if sub.Complete != tc.complete {
				t.Fatalf("Complete = %v, want %v", sub.Complete, tc.complete)
			}
		})
	}

	t.Run("a caller that knows better can mark it incomplete", func(t *testing.T) {
		sub := b.Subscribe(context.Background(), SubscribeOptions{Replay: last, Incomplete: true})
		defer sub.Close()
		if sub.Complete {
			t.Fatal("Incomplete was ignored")
		}
	})
}

// IDs restart at one with every process, so an id alone cannot say which
// sequence it came from. On the wire it carries the run's epoch.
func TestWireIDsCarryTheEpoch(t *testing.T) {
	b := New()
	wire := b.WireID(42)
	if !strings.HasPrefix(wire, b.Epoch()+".") || !strings.HasSuffix(wire, ".42") {
		t.Fatalf("WireID(42) = %q, want <epoch>.42", wire)
	}
	if id, same := b.ParseWireID(wire); id != 42 || !same {
		t.Fatalf("ParseWireID(%q) = %d, %v; want 42 in this epoch", wire, id, same)
	}
	if id, same := b.ParseWireID("otherrun.42"); id != 42 || same {
		t.Fatalf("an id from another epoch parsed as %d, %v; want 42 and not this epoch", id, same)
	}
	// A bare number is what a client that predates the epoch sends; it is
	// taken as this epoch's so an upgrade does not resync every tab.
	if id, same := b.ParseWireID("42"); id != 42 || !same {
		t.Fatalf("a bare id parsed as %d, %v", id, same)
	}
	if id, same := b.ParseWireID("not-an-id"); id != 0 || same {
		t.Fatalf("garbage parsed as %d, %v", id, same)
	}
	other := New()
	if other.Epoch() == b.Epoch() {
		t.Fatal("two buses share an epoch; a restart would look like the same run")
	}
}

// Subscribe starts a goroutine to close the subscription when its context
// ends. The SSE handler closes its subscription itself, before the request's
// context is cancelled, and a long-lived caller may pass a context that is
// never cancelled at all; either way that goroutine used to wait for ever, one
// per subscription for the life of the process.
func TestClosingASubscriptionEndsItsContextWatcher(t *testing.T) {
	b := New()
	before := runtime.NumGoroutine()
	for i := 0; i < 50; i++ {
		b.Subscribe(context.Background(), SubscribeOptions{}).Close()
	}
	deadline := time.Now().Add(2 * time.Second)
	for runtime.NumGoroutine() > before+5 && time.Now().Before(deadline) {
		time.Sleep(10 * time.Millisecond)
	}
	if n := runtime.NumGoroutine(); n > before+5 {
		t.Fatalf("%d goroutines after closing 50 subscriptions, %d before them", n, before)
	}
}

// The ring and the wire have to agree with the sequence.
//
// Every event carries the number a reconnecting client comes back with, and
// the SSE handler replays everything above it. So an event that reaches the
// ring after one numbered above it is an event that client will never be sent
// -- and Subscribe, which reads the ring's first entry as the oldest number it
// holds, would still call the replay complete and send no resync. The number
// used to be drawn before the lock, which is exactly the window two publishers
// need to swap places.
func TestConcurrentPublishesKeepTheRingInSequence(t *testing.T) {
	b := New()
	const writers, each = 8, 64

	var wg sync.WaitGroup
	for w := 0; w < writers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := 0; i < each; i++ {
				b.Publish(KindStats, "", map[string]int{"n": i})
			}
		}()
	}
	wg.Wait()

	b.mu.RLock()
	ring := append([]Event(nil), b.ring...)
	b.mu.RUnlock()

	if len(ring) == 0 {
		t.Fatal("nothing reached the ring")
	}
	for i := 1; i < len(ring); i++ {
		if ring[i].ID <= ring[i-1].ID {
			t.Fatalf("ring entry %d has id %d, after id %d: a client resuming from the higher one never sees the lower",
				i, ring[i].ID, ring[i-1].ID)
		}
	}
	if got, want := ring[len(ring)-1].ID, uint64(writers*each); got != want {
		t.Fatalf("the last event is %d, want %d", got, want)
	}
}

// A tab reconnecting to a busy fleet must not be cut off by its own replay.
//
// The replay is delivered before the subscriber has read anything, so a queue
// only as deep as the ring is full the instant the subscription exists. The
// next publish then finds no room and ends the feed -- and the tab reconnects
// to a ring that is still full and is ended again, on the fleet that most
// needs watching.
func TestAFullReplayLeavesRoomForTheNextEvent(t *testing.T) {
	b := New()
	// One more than the ring holds, so a replay from the first id reaches
	// back to the oldest entry still in it and carries every one of them.
	for i := 0; i <= b.ringCap; i++ {
		b.Publish(KindStats, "", map[string]int{"n": i})
	}

	sub := b.Subscribe(context.Background(), SubscribeOptions{Replay: 1})
	defer sub.Close()
	if !sub.Complete {
		t.Fatal("a replay reaching back to the oldest event in the ring reported itself incomplete")
	}

	b.Publish(KindStats, "", map[string]int{"n": -1})
	for i := 0; i < b.ringCap; i++ {
		if _, ok := <-sub.C; !ok {
			t.Fatalf("the feed ended after %d replayed events; the subscriber was dropped by its own replay", i)
		}
	}
	if _, ok := <-sub.C; !ok {
		t.Fatal("the feed ended before the event published after the replay")
	}
}

// A resync is about the connections it was sent to and about no other.
//
// It means "what you hold may be stale, fetch the resources again", which is
// never true of a client that connects afterwards -- that one is already
// fetching everything. Kept in the ring, the prune's resync would meet each
// new tab on its first reconnect and send it straight back to load a fleet it
// had only just loaded.
func TestATransientEventReachesSubscribersWithoutEnteringTheRing(t *testing.T) {
	b := New()
	sub := b.Subscribe(context.Background(), SubscribeOptions{})
	defer sub.Close()

	b.PublishTransient(KindResync, "", map[string]string{"reason": "everything went"})

	select {
	case ev := <-sub.C:
		if ev.Kind != KindResync {
			t.Fatalf("the subscriber got %q, want a resync", ev.Kind)
		}
		if ev.ID == 0 {
			t.Fatal("a transient event carried no id, so a client resuming from it would be sent what it has already seen")
		}
	case <-time.After(time.Second):
		t.Fatal("the subscriber never got the transient event")
	}

	b.mu.RLock()
	ring := append([]Event(nil), b.ring...)
	b.mu.RUnlock()
	for _, e := range ring {
		if e.Kind == KindResync {
			t.Fatal("the resync is in the ring; a client reconnecting later would be told to refetch for nothing")
		}
	}

	// The number it drew still belongs to the sequence, so an ordinary event
	// published after it follows on.
	b.Publish(KindStats, "", map[string]int{"n": 1})
	later := b.Subscribe(context.Background(), SubscribeOptions{Replay: 1})
	defer later.Close()
	if !later.Complete {
		t.Fatal("a replay across the transient event reported itself incomplete")
	}
}

// A reconnecting client and a tool asking "since id 3" must get the same
// answer, or the stream and the route disagree about what was lost.
func TestRecentAgreesWithTheStreamsReplay(t *testing.T) {
	b := New()
	for i := range 5 {
		b.Publish(KindScaling, "", map[string]int{"n": i})
	}

	items, complete, truncated := b.Recent(3, SubscribeOptions{}, 0)
	if !complete || truncated {
		t.Fatalf("complete = %v, truncated = %v, want true and false", complete, truncated)
	}
	if len(items) != 2 || items[0].ID != 4 || items[1].ID != 5 {
		t.Fatalf("Recent(3) = %v, want ids 4 and 5", ids(items))
	}

	sub := b.Subscribe(context.Background(), SubscribeOptions{Replay: 3})
	defer sub.Close()
	if sub.Complete != complete {
		t.Fatalf("the stream says complete = %v and Recent says %v", sub.Complete, complete)
	}
	for _, want := range items {
		select {
		case got := <-sub.C:
			if got.ID != want.ID {
				t.Fatalf("the stream replayed id %d where Recent returned %d", got.ID, want.ID)
			}
		case <-time.After(2 * time.Second):
			t.Fatalf("the stream never replayed id %d", want.ID)
		}
	}
	select {
	case got := <-sub.C:
		t.Fatalf("the stream replayed id %d, which Recent did not return", got.ID)
	default:
	}
}

func TestRecentSaysIncompleteWhenTheRingMovedOn(t *testing.T) {
	b := New()
	b.ringCap = 4
	for i := range 10 {
		b.Publish(KindScaling, "", map[string]int{"n": i})
	}

	items, complete, _ := b.Recent(2, SubscribeOptions{}, 0)
	if complete {
		t.Fatal("Recent claimed to be complete though the ring no longer reaches id 3")
	}
	if got := ids(items); len(got) != 4 || got[0] != 7 || got[3] != 10 {
		t.Fatalf("Recent(2) = %v, want what the ring holds, ids 7 to 10", got)
	}

	t.Run("an id from another run of the process is incomplete and empty", func(t *testing.T) {
		items, complete, truncated := b.Recent(b.LastID()+40, SubscribeOptions{}, 0)
		if complete || truncated || len(items) != 0 {
			t.Fatalf("got %v, complete %v, truncated %v", ids(items), complete, truncated)
		}
	})
	t.Run("the latest id has nothing since and misses nothing", func(t *testing.T) {
		items, complete, truncated := b.Recent(b.LastID(), SubscribeOptions{}, 0)
		if !complete || truncated || len(items) != 0 {
			t.Fatalf("got %v, complete %v, truncated %v", ids(items), complete, truncated)
		}
	})
	t.Run("an empty ring is complete from the start and incomplete from anywhere later", func(t *testing.T) {
		empty := New()
		if items, complete, _ := empty.Recent(0, SubscribeOptions{}, 0); !complete || len(items) != 0 {
			t.Fatalf("since 0: got %v, complete %v", ids(items), complete)
		}
		if _, complete, _ := empty.Recent(5, SubscribeOptions{}, 0); complete {
			t.Fatal("an id beyond an empty sequence was reported complete")
		}
	})
}

func TestRecentFiltersByKindAndTopicAndTruncatesOldestFirst(t *testing.T) {
	b := New()
	b.Publish(KindRunnerUpdated, "runner:a", nil)
	b.Publish(KindPoolUpdated, "pool:a", nil)
	b.Publish(KindRunnerUpdated, "runner:b", nil)
	b.Publish(KindRunnerUpdated, "pool:b", nil)
	b.Publish(KindRunnerUpdated, "runner:c", nil)

	items, complete, truncated := b.Recent(0, SubscribeOptions{Kinds: []Kind{KindRunnerUpdated}}, 0)
	if !complete || truncated || len(items) != 4 {
		t.Fatalf("kind filter: got %v, complete %v, truncated %v", ids(items), complete, truncated)
	}

	items, _, _ = b.Recent(0, SubscribeOptions{TopicPrefix: "runner:"}, 0)
	if got := ids(items); len(got) != 3 || got[0] != 1 || got[1] != 3 || got[2] != 5 {
		t.Fatalf("topic filter: got %v, want ids 1, 3 and 5", got)
	}

	items, _, truncated = b.Recent(0, SubscribeOptions{}, 2)
	if got := ids(items); len(got) != 2 || got[0] != 1 || got[1] != 2 || !truncated {
		t.Fatalf("limit 2 of 5: got %v, truncated %v, want the oldest two and true", got, truncated)
	}

	items, _, truncated = b.Recent(0, SubscribeOptions{}, 5)
	if len(items) != 5 || truncated {
		t.Fatalf("a limit equal to the matches: got %d, truncated %v, want 5 and false", len(items), truncated)
	}
}

func ids(events []Event) []uint64 {
	out := make([]uint64, 0, len(events))
	for _, e := range events {
		out = append(out, e.ID)
	}
	return out
}

func TestMatchesIsTheOneRuleForKindsAndTopics(t *testing.T) {
	ev := Event{Kind: KindJobUpdated, Topic: "job:job_1"}
	for _, tc := range []struct {
		name string
		opts SubscribeOptions
		want bool
	}{
		{"no filter takes everything", SubscribeOptions{}, true},
		{"a listed kind", SubscribeOptions{Kinds: []Kind{KindRunnerUpdated, KindJobUpdated}}, true},
		{"an unlisted kind", SubscribeOptions{Kinds: []Kind{KindRunnerUpdated}}, false},
		{"a topic prefix", SubscribeOptions{TopicPrefix: "job:"}, true},
		{"another topic prefix", SubscribeOptions{TopicPrefix: "runner:"}, false},
		{"both must hold", SubscribeOptions{Kinds: []Kind{KindJobUpdated}, TopicPrefix: "runner:"}, false},
	} {
		if got := tc.opts.Matches(ev); got != tc.want {
			t.Errorf("%s: Matches = %v, want %v", tc.name, got, tc.want)
		}
	}
}

package events

import (
	"context"
	"testing"
)

// limits.event_subscribers is enforced here rather than by counting first and
// subscribing after, so that the ceiling holds for streams opened together.
// Closing one has to give its place back, or a browser that reconnects would
// find the instance permanently full of its own dead streams.
func TestSubscribeWithinRefusesAtTheCeilingAndFreesAPlaceOnClose(t *testing.T) {
	b := New()
	ctx := context.Background()

	first, ok := b.SubscribeWithin(ctx, SubscribeOptions{}, 2)
	if !ok {
		t.Fatal("the first subscription was refused under a ceiling of 2")
	}
	if _, ok := b.SubscribeWithin(ctx, SubscribeOptions{}, 2); !ok {
		t.Fatal("the second subscription was refused under a ceiling of 2")
	}
	if s, ok := b.SubscribeWithin(ctx, SubscribeOptions{}, 2); ok || s != nil {
		t.Fatalf("a third subscription was admitted under a ceiling of 2 (%d open)", b.Subscribers())
	}
	if n := b.Subscribers(); n != 2 {
		t.Fatalf("a refused subscription was still counted: %d open", n)
	}

	first.Close()
	if _, ok := b.SubscribeWithin(ctx, SubscribeOptions{}, 2); !ok {
		t.Fatal("closing a subscription did not free its place")
	}
	if _, ok := b.SubscribeWithin(ctx, SubscribeOptions{}, 0); !ok {
		t.Fatal("a ceiling of 0 refused a subscription; 0 is unlimited")
	}
}

// A public view's visitors are a class with a ceiling of their own. However
// many of them there are, the people who run the fleet keep every stream the
// ordinary ceiling allows them, and a visitor is refused only at the visitors'
// ceiling, never because staff are busy.
func TestAClassHasItsOwnCeilingAndNeverTakesTheOrdinaryOne(t *testing.T) {
	b := New()
	ctx := context.Background()
	visitor := SubscribeOptions{Class: "visitor", ClassLimit: 2}

	var visitors []*Subscription
	for i := range 2 {
		s, ok := b.SubscribeWithin(ctx, visitor, 1)
		if !ok {
			t.Fatalf("visitor %d was refused under a visitors' ceiling of 2", i+1)
		}
		visitors = append(visitors, s)
	}
	if _, ok := b.SubscribeWithin(ctx, visitor, 1); ok {
		t.Fatal("a third visitor was admitted under a visitors' ceiling of 2")
	}

	// Two visitors are open and the ordinary ceiling is 1: staff still get it.
	staff, ok := b.SubscribeWithin(ctx, SubscribeOptions{}, 1)
	if !ok {
		t.Fatal("visitors took the place the ordinary ceiling keeps for staff")
	}
	if _, ok := b.SubscribeWithin(ctx, SubscribeOptions{}, 1); ok {
		t.Fatal("a second ordinary subscription was admitted under a ceiling of 1")
	}
	if got := b.ClassSubscribers("visitor"); got != 2 {
		t.Errorf("ClassSubscribers(visitor) = %d; want 2", got)
	}
	if got := b.ClassSubscribers(""); got != 1 {
		t.Errorf("ClassSubscribers(\"\") = %d; want 1", got)
	}
	if got := b.Subscribers(); got != 3 {
		t.Errorf("Subscribers() = %d; want every open stream, 3", got)
	}

	// Staff leaving frees nothing for visitors, and a visitor leaving does.
	staff.Close()
	if _, ok := b.SubscribeWithin(ctx, visitor, 1); ok {
		t.Fatal("a staff stream closing made room under the visitors' ceiling")
	}
	visitors[0].Close()
	if _, ok := b.SubscribeWithin(ctx, visitor, 1); !ok {
		t.Fatal("a visitor leaving did not free a visitor's place")
	}
}

// Package gateway publishes one private service -- a hypervisor's API on a
// home network, typically -- to a controller over Tailcat.
//
// It is the provider-side half of what internal/agent's private transport is
// for hosts, with the direction reversed. A host connects outbound to the
// controller, so the controller listens inside the tunnel. A provider is
// something the controller connects to, so the gateway listens instead: it
// runs beside the hypervisor, on any machine that can reach its API, and
// forwards every TCP connection that arrives through the tunnel to that one
// address. The controller keeps the gateway's address sealed beside the
// provider's credential and dials through it.
//
// The gateway exposes exactly the target and nothing else. There is no port
// on the operating system, no route to the LAN and no way to ask it for a
// second destination: a client that holds the address can open connections to
// the target, which is why the address is treated as a credential everywhere
// it is handled. TLS is not terminated here -- the controller still verifies
// the hypervisor's certificate end to end, so the gateway learns nothing about
// the API token that passes through it.
package gateway

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"net"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"github.com/tailscale/tailcat"
	"tailscale.com/tailcfg"
)

// StateFile is the identity, kept in the state directory. Losing it changes
// the address, and every provider row pointing at this gateway with it.
const StateFile = "gateway.json"

// dialTimeout bounds one forwarded connection's dial of the target. The
// controller has its own budget for the request; this is only so that a target
// that has gone away frees the tunnel's side promptly.
const dialTimeout = 10 * time.Second

// relayTimeout bounds relay discovery at startup, which the upstream library
// otherwise does with a background context.
const relayTimeout = 20 * time.Second

// Options is what a gateway needs.
type Options struct {
	// Target is the host:port every forwarded connection goes to, as the
	// machine running the gateway reaches it: "192.168.1.10:8006".
	Target string
	// StateDir is where the identity is kept. The address printed at startup
	// is derived from it, so a gateway restarted from the same directory
	// keeps its address.
	StateDir string
	// Region, when set, is the relay to use instead of discovering one. Tests
	// point it at a local relay; production leaves it nil.
	Region *tailcfg.DERPRegion
	Logger *slog.Logger
}

// Gateway is one running tunnel end.
type Gateway struct {
	node    *tailcat.Server
	address string
	target  string
	log     *slog.Logger
	closed  chan struct{}
	once    sync.Once
	active  sync.WaitGroup
}

// StatePath is where a gateway in the given directory keeps its identity.
func StatePath(dir string) string { return filepath.Join(dir, StateFile) }

// ParseTarget checks a target the way Start will use it, so a command can
// refuse a bad one before touching the network or the state directory.
func ParseTarget(raw string) (string, error) {
	target := strings.TrimSpace(raw)
	if target == "" {
		return "", errors.New("gateway: no target; give the address the hypervisor's API answers on, as this machine reaches it, e.g. --target 192.168.1.10:8006")
	}
	if strings.Contains(target, "://") {
		return "", fmt.Errorf("gateway: the target is a host and port, not a URL: write %q without the scheme and path", target)
	}
	host, port, err := net.SplitHostPort(target)
	if err != nil || host == "" || port == "" {
		return "", fmt.Errorf("gateway: %q is not host:port; a Proxmox API is usually on port 8006, e.g. 192.168.1.10:8006", target)
	}
	return net.JoinHostPort(host, port), nil
}

// Start loads or creates the identity, joins the relay and begins forwarding.
//
// The address it returns is a capability: whoever holds it can open
// connections to the target. It goes to the operator once, to paste into the
// provider's form, and nowhere else -- not into the log, which is why the
// upstream library's own logging is discarded.
func Start(ctx context.Context, opts Options) (*Gateway, error) {
	target, err := ParseTarget(opts.Target)
	if err != nil {
		return nil, err
	}
	log := opts.Logger
	if log == nil {
		log = slog.Default()
	}
	log = log.With("component", "gateway")
	if opts.StateDir == "" {
		return nil, errors.New("gateway: no state directory; the identity that keeps the address stable across restarts has to live somewhere")
	}

	identity, fresh, err := loadIdentity(StatePath(opts.StateDir))
	if err != nil {
		return nil, err
	}
	if opts.Region != nil {
		identity.Public.Region = []*tailcfg.DERPRegion{opts.Region}
	}
	if len(identity.Public.Region) == 0 {
		// Resolve the relay with a bounded context before Start, which
		// otherwise performs discovery with a background context inside the
		// upstream library. The region is saved with the identity so that
		// the address, which embeds it, is the same after a restart.
		identity.Public.RegionID = -1
		resolveCtx, cancel := context.WithTimeout(ctx, relayTimeout)
		defer cancel()
		if err := identity.Public.Expand(resolveCtx, tailcat.ExpandForServer); err != nil {
			return nil, errors.New("gateway: cannot reach a Tailcat relay; check this machine's outbound internet access and try again")
		}
		fresh = true
	}

	g := &Gateway{target: target, log: log, closed: make(chan struct{})}
	g.node = &tailcat.Server{
		Key:          identity.Private,
		PresharedKey: identity.Public.PresharedKey,
		Region:       identity.Public.Region[0],
		Logf:         func(string, ...any) {},
		// Every port forwards to the one target. Refusing all but one would
		// only add a way for the endpoint an operator typed on the controller
		// and the target they typed here to disagree, with a reset and no
		// message as the symptom; there is one destination either way.
		OnTCP: func(uint16) func(net.Conn) { return g.forward },
	}
	if err := g.node.Start(); err != nil {
		return nil, errors.New("gateway: cannot start the private connection; check network-interface permissions and outbound internet access, then try again")
	}
	if fresh {
		if err := saveIdentity(StatePath(opts.StateDir), identity); err != nil {
			_ = g.node.Close()
			return nil, err
		}
	}
	g.address = string(identity.Public.Addr())
	return g, nil
}

// Address is the capability a controller needs to reach the target.
func (g *Gateway) Address() string { return g.address }

// Target is what forwarded connections go to.
func (g *Gateway) Target() string { return g.target }

// Close stops accepting connections and cuts the ones in flight. A controller
// mid-request sees a closed connection and retries on its own schedule, as it
// does for any hypervisor that went away.
func (g *Gateway) Close() error {
	g.once.Do(func() {
		close(g.closed)
		_ = g.node.Close()
	})
	g.active.Wait()
	return nil
}

// forward carries one tunnelled connection to the target and back.
func (g *Gateway) forward(tunnel net.Conn) {
	g.active.Add(1)
	defer g.active.Done()
	defer tunnel.Close()
	select {
	case <-g.closed:
		return
	default:
	}
	ctx, cancel := context.WithTimeout(context.Background(), dialTimeout)
	defer cancel()
	local, err := (&net.Dialer{}).DialContext(ctx, "tcp", g.target)
	if err != nil {
		// The one failure worth a log line: the tunnel is up and the thing
		// behind it is not, which is what an operator staring at "provider
		// unreachable" on the controller needs to hear from this side.
		g.log.Warn("cannot reach the target behind the gateway; the controller will see the provider as unreachable",
			"target", g.target, "error", err.Error())
		return
	}
	defer local.Close()
	done := make(chan struct{}, 2)
	go func() { _, _ = io.Copy(local, tunnel); closeWrite(local); done <- struct{}{} }()
	go func() { _, _ = io.Copy(tunnel, local); closeWrite(tunnel); done <- struct{}{} }()
	select {
	case <-done:
	case <-g.closed:
		return
	}
	select {
	case <-done:
	case <-g.closed:
	}
}

func closeWrite(c net.Conn) {
	if cw, ok := c.(interface{ CloseWrite() error }); ok {
		_ = cw.CloseWrite()
		return
	}
	_ = c.Close()
}

// loadIdentity reads the saved identity, or makes a new one when there is
// none. fresh says the caller has to save it.
//
// A world-readable identity file is refused rather than used, as the agent's
// credentials file is: it is the address, and the address is the capability.
func loadIdentity(path string) (identity *tailcat.PrivateKey, fresh bool, err error) {
	info, err := os.Stat(path)
	if errors.Is(err, os.ErrNotExist) {
		return tailcat.NewPrivateKey(), true, nil
	}
	if err != nil {
		return nil, false, fmt.Errorf("gateway: reading the identity at %s: %w", path, err)
	}
	if info.Mode().Perm()&0o077 != 0 {
		return nil, false, fmt.Errorf("gateway: the identity at %s is readable by other users, and it is the address a controller uses to reach the target; run chmod 600 on it", path)
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, false, fmt.Errorf("gateway: reading the identity at %s: %w", path, err)
	}
	identity = &tailcat.PrivateKey{}
	if json.Unmarshal(raw, identity) != nil || identity.Private.IsZero() || identity.Public.PresharedKey.IsZero() {
		return nil, false, fmt.Errorf("gateway: the identity at %s is incomplete; move it aside to start with a new address, then update the provider on the controller with it", path)
	}
	return identity, false, nil
}

// saveIdentity writes the identity with mode 0600, atomically, so a crash
// between two writes cannot leave a half-written address behind.
func saveIdentity(path string, identity *tailcat.PrivateKey) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return fmt.Errorf("gateway: creating the state directory %s: %w", dir, err)
	}
	raw, err := json.MarshalIndent(identity, "", "  ")
	if err != nil {
		return fmt.Errorf("gateway: encoding the identity: %w", err)
	}
	tmp, err := os.CreateTemp(dir, ".gateway-*.json")
	if err != nil {
		return fmt.Errorf("gateway: creating a temporary file in %s: %w", dir, err)
	}
	tmpName := tmp.Name()
	defer os.Remove(tmpName) // no-op once the rename has succeeded
	if err := tmp.Chmod(0o600); err != nil {
		tmp.Close()
		return fmt.Errorf("gateway: setting permissions on %s: %w", tmpName, err)
	}
	if _, err := tmp.Write(append(raw, '\n')); err != nil {
		tmp.Close()
		return fmt.Errorf("gateway: writing %s: %w", tmpName, err)
	}
	if err := tmp.Close(); err != nil {
		return fmt.Errorf("gateway: closing %s: %w", tmpName, err)
	}
	if err := os.Rename(tmpName, path); err != nil {
		return fmt.Errorf("gateway: moving the identity into place at %s: %w", path, err)
	}
	return nil
}

