func TestTargetsAreHostAndPortAndNothingElse(t *testing.T) {
	for _, bad := range []string{"", "https://pve:8006", "pve", ":8006", "pve:"} {
		if _, err := ParseTarget(bad); err == nil {
			t.Errorf("%q was accepted", bad)
		}
	}
	got, err := ParseTarget(" 192.168.1.10:8006 ")
	if err != nil || got != "192.168.1.10:8006" {
		t.Fatalf("ParseTarget = %q, %v", got, err)
	}
}

// The identity is the address, and the address is a capability to open
// connections to the target, so it is kept the way the agent keeps its token.
func TestIdentityIsPrivateAndRefusedWhenItIsNot(t *testing.T) {
	dir := t.TempDir()
	path := StatePath(dir)
	identity := tailcat.NewPrivateKey()
	if err := saveIdentity(path, identity); err != nil {
		t.Fatal(err)
	}
	info, err := os.Stat(path)
	if err != nil {
		t.Fatal(err)
	}
	if info.Mode().Perm() != 0o600 {
		t.Fatalf("identity saved with mode %o", info.Mode().Perm())
	}
	loaded, fresh, err := loadIdentity(path)
	if err != nil || fresh {
		t.Fatalf("loadIdentity = fresh %v, %v", fresh, err)
	}
	if !loaded.Private.Equal(identity.Private) || !loaded.Public.PresharedKey.Equal(identity.Public.PresharedKey) {
		t.Fatal("the identity did not survive a round trip")
	}
	if err := os.Chmod(path, 0o644); err != nil {
		t.Fatal(err)
	}
	if _, _, err := loadIdentity(path); err == nil || !strings.Contains(err.Error(), "chmod 600") {
		t.Fatalf("a world-readable identity was used: %v", err)
	}
	if err := os.WriteFile(filepath.Join(dir, "broken.json"), []byte("{}"), 0o600); err != nil {
		t.Fatal(err)
	}
	if _, _, err := loadIdentity(filepath.Join(dir, "broken.json")); err == nil {
		t.Fatal("an empty identity was used")
	}
	if _, fresh, err := loadIdentity(filepath.Join(dir, "absent.json")); err != nil || !fresh {
		t.Fatalf("a missing identity is a fresh start: fresh %v, %v", fresh, err)
	}
}

// A local DERP relay exercises the real data path: a TLS server that only the
// gateway can reach, a client that holds nothing but the address, and the
// hypervisor's certificate verified end to end through the tunnel.
func TestGatewayForwardsTheTunnelToItsTargetAndKeepsItsAddressAcrossRestarts(t *testing.T) {
	t.Setenv("IN_TS_TEST", "true")
	dm := integration.RunDERPAndSTUN(t, func(string, ...any) {}, "127.0.0.1")
	target := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_, _ = io.WriteString(w, "hello from "+r.Host)
	}))
	defer target.Close()
	dir := t.TempDir()
	ctx, cancel := context.WithTimeout(context.Background(), time.Minute)
	defer cancel()

	g, err := Start(ctx, Options{Target: target.Listener.Addr().String(), StateDir: dir, Region: dm.Regions[1]})
	if err != nil {
		t.Fatal(err)
	}
	address := g.Address()
	if !strings.HasPrefix(address, "tc") {
		t.Fatalf("address %q is not a Tailcat address", address)
	}

	client := tailcat.NewClient(tailcat.Addr(address))
	client.Logf = func(string, ...any) {}
	defer client.Close()
	pool := target.Client().Transport.(*http.Transport).TLSClientConfig.RootCAs
	httpClient := &http.Client{Transport: &http.Transport{
		TLSClientConfig: &tls.Config{RootCAs: pool},
		DialContext: func(ctx context.Context, _, _ string) (net.Conn, error) {
			return client.DialTCPPort(ctx, 8006)
		},
	}}
	// example.com is the name httptest's certificate is issued for, and it
	// does not resolve to the target: only the tunnel gets there.
	res, err := httpClient.Get("https://example.com:8006/version")
	if err != nil {
		t.Fatalf("through the gateway: %v", err)
	}
	body, _ := io.ReadAll(res.Body)
	res.Body.Close()
	if string(body) != "hello from example.com:8006" {
		t.Fatalf("got %q", body)
	}

	// The same directory is the same address, which is what lets a provider
	// row outlive a reboot of the machine the gateway runs on.
	if err := g.Close(); err != nil {
		t.Fatal(err)
	}
	again, err := Start(ctx, Options{Target: target.Listener.Addr().String(), StateDir: dir})
	if err != nil {
		t.Fatal(err)
	}
	defer again.Close()
	if again.Address() != address {
		t.Fatal("restarting the gateway changed its address")
	}
}

package github

import (
	"context"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"net/url"
	"strings"
	"sync"
	"time"

	"github.com/coreos/go-oidc/v3/oidc"
)

// ActionsIssuer is the issuer of GitHub.com's Actions OIDC tokens. A token from
// any other issuer is not a statement GitHub made about a workflow run.
const ActionsIssuer = "https://token.actions.githubusercontent.com"

// ActionsIssuerFor is the issuer of Actions OIDC tokens for workflows on
// host. GitHub.com's come from one shared issuer; an Enterprise Server signs
// its own, under /_services/token on the instance itself, so a GHES token is
// only ever checked against the keys of the server that ran the workflow.
func ActionsIssuerFor(host string) string {
	if host == "github.com" {
		return ActionsIssuer
	}
	return "https://" + host + "/_services/token"
}

// UnverifiedActionsIssuer reads a token's iss claim without checking anything.
// It is for routing only -- choosing which issuer's keys to verify against --
// and a caller must accept the answer only if it names an issuer it already
// trusts, so a token cannot make the controller fetch keys from anywhere.
func UnverifiedActionsIssuer(raw string) (string, error) {
	parts := strings.Split(raw, ".")
	if len(parts) != 3 || len(raw) > 16<<10 {
		return "", fmt.Errorf("%w: it is not a JWT", ErrActionsToken)
	}
	payload, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return "", fmt.Errorf("%w: its payload is not base64url", ErrActionsToken)
	}
	var claims struct {
		Issuer string `json:"iss"`
	}
	if err := json.Unmarshal(payload, &claims); err != nil || claims.Issuer == "" {
		return "", fmt.Errorf("%w: it names no issuer", ErrActionsToken)
	}
	return strings.TrimRight(claims.Issuer, "/"), nil
}

// ActionsClaims are the parts of an Actions OIDC token Zoomies decides on. Each
// is something GitHub asserts about the run, not something the workflow chose:
// a step can ask for a token but cannot change what it says.
type ActionsClaims struct {
	ID                string
	Expiry            time.Time
	Repository        string `json:"repository"`
	RepositoryID      string `json:"repository_id"`
	RepositoryOwnerID string `json:"repository_owner_id"`
	Ref               string `json:"ref"`
	SHA               string `json:"sha"`
	EventName         string `json:"event_name"`
	JobWorkflowRef    string `json:"job_workflow_ref"`
	RunID             string `json:"run_id"`
	RunAttempt        string `json:"run_attempt"`
}

// ActionsTokenVerifier checks an Actions OIDC token's signature against the
// issuer's published keys, and its issuer, audience and expiry.
type ActionsTokenVerifier struct {
	issuer string
	once   sync.Once
	keys   oidc.KeySet
}

// NewActionsTokenVerifier verifies tokens from issuer; production passes
// ActionsIssuer, and tests a local one. The keys are fetched on first use and
// cached by go-oidc, which refetches when it sees a key it does not know --
// GitHub rotates them.
func NewActionsTokenVerifier(issuer string) *ActionsTokenVerifier {
	return &ActionsTokenVerifier{issuer: strings.TrimRight(issuer, "/")}
}

// ErrActionsKeysUnavailable is a token that could not be checked because
// GitHub's signing keys could not be fetched. It says nothing about the token,
// so it must not read as a refusal of it: the workflow's log should send the
// operator to the controller's network, not to the workflow.
var ErrActionsKeysUnavailable = errors.New("GitHub's Actions signing keys could not be fetched")

// ActionsKeysError is ErrActionsKeysUnavailable with the host the keys live
// on, which is the host an operator has to let the controller reach: GitHub's
// shared issuer for GitHub.com, the server itself for Enterprise Server.
type ActionsKeysError struct {
	Host string
	Err  error
}

func (e *ActionsKeysError) Error() string {
	return fmt.Sprintf("%v from %s: %v", ErrActionsKeysUnavailable, e.Host, e.Err)
}

func (e *ActionsKeysError) Is(target error) bool { return target == ErrActionsKeysUnavailable }

// fetchRecordingKeys notes whether the key set failed to fetch, which the
// verifier would otherwise flatten into a signature error: go-oidc formats the
// key set's error with %v, so its type does not survive. The prefix it checks is
// go-oidc's own, and TestAnUnreachableIssuerIsNotABadToken pins it.
type fetchRecordingKeys struct {
	inner   oidc.KeySet
	fetched error
}

func (k *fetchRecordingKeys) VerifySignature(ctx context.Context, jwt string) ([]byte, error) {
	payload, err := k.inner.VerifySignature(ctx, jwt)
	if err != nil && strings.HasPrefix(err.Error(), "fetching keys") {
		k.fetched = err
	}
	return payload, err
}

// ErrActionsToken is returned for any token that is not a valid, current
// Actions token for this audience. The cause is wrapped for the log only.
var ErrActionsToken = errors.New("the upload's GitHub Actions OIDC token is not valid for this controller")

// Verify returns the claims of a token minted for audience. The audience is
// the controller's own upload address, so a token minted for one Zoomies is
// useless against another.
func (v *ActionsTokenVerifier) Verify(ctx context.Context, raw, audience string) (*ActionsClaims, error) {
	v.once.Do(func() {
		// Its own context: the key set outlives the request that created it.
		v.keys = oidc.NewRemoteKeySet(context.WithoutCancel(ctx), v.issuer+"/.well-known/jwks")
	})
	keys := &fetchRecordingKeys{inner: v.keys}
	verifier := oidc.NewVerifier(v.issuer, keys, &oidc.Config{ClientID: audience, SupportedSigningAlgs: []string{oidc.RS256}})
	token, err := verifier.Verify(ctx, raw)
	if err != nil {
		if keys.fetched != nil {
			host := v.issuer
			if u, err := url.Parse(v.issuer); err == nil && u.Host != "" {
				host = u.Host
			}
			return nil, &ActionsKeysError{Host: host, Err: keys.fetched}
		}
		return nil, fmt.Errorf("%w: %v", ErrActionsToken, err)
	}
	var claims ActionsClaims
	if err := token.Claims(&claims); err != nil {
		return nil, fmt.Errorf("%w: %v", ErrActionsToken, err)
	}
	var id struct {
		JTI string `json:"jti"`
	}
	if err := token.Claims(&id); err != nil || id.JTI == "" || len(id.JTI) > 200 {
		return nil, fmt.Errorf("%w: it carries no token ID, so it could be replayed", ErrActionsToken)
	}
	claims.ID, claims.Expiry = id.JTI, token.Expiry
	return &claims, nil
}

package github

import (
	"errors"
	"strings"
	"testing"
	"time"
)

func TestActionsTokensAreBoundToTheirIssuerAudienceAndLifetime(t *testing.T) {
	issuer := NewFakeActionsIssuer(t)
	verifier := NewActionsTokenVerifier(issuer.URL)
	const audience = "https://zoomies.example.com/api/v1/ai-context/uploads"

	claims, err := verifier.Verify(t.Context(), issuer.Sign(t, map[string]any{"aud": audience, "repository_id": "42", "sha": "abc", "jti": "one"}), audience)
	if err != nil {
		t.Fatal(err)
	}
	if claims.RepositoryID != "42" || claims.SHA != "abc" || claims.ID != "one" {
		t.Fatalf("claims %+v", claims)
	}

	for name, token := range map[string]string{
		"another controller's audience": issuer.Sign(t, map[string]any{"aud": "https://elsewhere.example.com/api/v1/ai-context/uploads"}),
		"expired":                       issuer.Sign(t, map[string]any{"aud": audience, "exp": time.Now().Add(-time.Minute).Unix()}),
		"another issuer":                issuer.Sign(t, map[string]any{"aud": audience, "iss": "https://token.actions.example.com"}),
		"no token ID":                   issuer.Sign(t, map[string]any{"aud": audience, "jti": ""}),
	} {
		if _, err := verifier.Verify(t.Context(), token, audience); !errors.Is(err, ErrActionsToken) {
			t.Errorf("%s: accepted (%v)", name, err)
		}
	}

	forged := NewFakeActionsIssuer(t)
	token := forged.Sign(t, map[string]any{"aud": audience, "iss": issuer.URL})
	if _, err := verifier.Verify(t.Context(), token, audience); !errors.Is(err, ErrActionsToken) {
		t.Errorf("a token signed with someone else's key was accepted: %v", err)
	}
}

// A controller that cannot reach GitHub's key endpoint has not seen a bad
// token; it has not been able to look. Reporting it as one would send the
// operator to the workflow instead of the controller's network.
func TestAnUnreachableIssuerIsNotABadToken(t *testing.T) {
	issuer := NewFakeActionsIssuer(t)
	token := issuer.Sign(t, map[string]any{"aud": "https://zoomies.example.com/api/v1/ai-context/uploads", "iss": "http://127.0.0.1:1"})
	verifier := NewActionsTokenVerifier("http://127.0.0.1:1")
	_, err := verifier.Verify(t.Context(), token, "https://zoomies.example.com/api/v1/ai-context/uploads")
	if !errors.Is(err, ErrActionsKeysUnavailable) || errors.Is(err, ErrActionsToken) {
		t.Fatalf("Verify against an unreachable issuer = %v; want ErrActionsKeysUnavailable alone", err)
	}
	// The operator is told which host to let the controller reach.
	var keys *ActionsKeysError
	if !errors.As(err, &keys) || keys.Host != "127.0.0.1:1" {
		t.Fatalf("the error does not name the issuer's host: %v", err)
	}
}

func TestEachGitHubHostHasItsOwnActionsIssuer(t *testing.T) {
	// An Enterprise Server signs its own tokens; trusting GitHub.com's issuer
	// for it, or the reverse, would let one vouch for the other's runs.
	for host, want := range map[string]string{
		"github.com":       "https://token.actions.githubusercontent.com",
		"ghes.example.org": "https://ghes.example.org/_services/token",
	} {
		if got := ActionsIssuerFor(host); got != want {
			t.Errorf("ActionsIssuerFor(%q) = %q, want %q", host, got, want)
		}
	}
}

func TestATokensIssuerIsReadOnlyFromAWellFormedToken(t *testing.T) {
	issuer := NewFakeActionsIssuer(t)
	got, err := UnverifiedActionsIssuer(issuer.Sign(t, map[string]any{"iss": "https://ghes.example.org/_services/token/"}))
	if err != nil || got != "https://ghes.example.org/_services/token" {
		t.Fatalf("issuer = %q, %v", got, err)
	}
	for name, raw := range map[string]string{
		"not a JWT":   "token",
		"bad payload": "a.!!!.c",
		"no issuer":   "e30.e30.sig",
		"oversized":   strings.Repeat("a", 17<<10) + ".e30.sig",
	} {
		if _, err := UnverifiedActionsIssuer(raw); !errors.Is(err, ErrActionsToken) {
			t.Errorf("%s: %v", name, err)
		}
	}
}

package github

import (
	"bytes"
	"context"
	"crypto/sha1"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"path"
	"strings"

	"github.com/eyupio/zoomies/internal/aicontext"
	gh "github.com/google/go-github/v88/github"
)

// ContextIngestionClient is read-only and does not widen runner permissions.
type ContextIngestionClient interface {
	ReadContextPublication(context.Context, string, string) (*ContextPublication, error)
	ContextSetupMerged(context.Context, string, int, string) (bool, error)
	VerifyContextSnapshot(ctx context.Context, repo, branch, commit string, snapshot *aicontext.Snapshot) error
}

// ErrContextMismatch is a published snapshot that no longer describes the
// trusted branch: the branch moved on, or the snapshot was made for another
// commit. It is the ordinary state between a push and the workflow finishing,
// so a caller can tell it apart from a publication that is genuinely broken.
var ErrContextMismatch = errors.New("github: published context does not match the trusted branch")

// ContextWorkflowDispatcher starts the managed workflow by hand. It is a
// separate interface because it is the one AI Context call that writes to
// GitHub Actions, and so needs the Actions write permission the rest of this
// file never asks for.
type ContextWorkflowDispatcher interface {
	DispatchContextWorkflow(ctx context.Context, repo, branch string) error
}

type ContextPublication struct {
	Source       *ContextSetupSource
	OutputCommit string
	Snapshot     *aicontext.Snapshot
}

type ContextSetupStatusClient interface {
	ContextSetupStatus(context.Context, string, int, string) (string, error)
}

func (c *appClient) ContextSetupStatus(ctx context.Context, repo string, number int, branch string) (string, error) {
	owner, name, err := splitRepo(repo)
	if err != nil {
		return "", err
	}
	pr, resp, err := c.asInstallation.PullRequests.Get(ctx, owner, name, number)
	if err != nil {
		return "", c.fail("check context setup outcome", resp, err)
	}
	if pr.GetBase().GetRef() != branch {
		return "", ErrSetupConflict
	}
	if pr.GetMerged() && pr.GetMergeCommitSHA() != "" {
		return "merged", nil
	}
	return pr.GetState(), nil
}

// DispatchContextWorkflow runs the managed workflow on the trusted branch. The
// caller has already checked that the workflow on that branch is the reviewed
// one; dispatching an edited file would run whatever it says.
func (c *appClient) DispatchContextWorkflow(ctx context.Context, repo, branch string) error {
	owner, name, err := splitRepo(repo)
	if err != nil {
		return err
	}
	_, resp, err := c.asInstallation.Actions.CreateWorkflowDispatchEventByFileName(ctx, owner, name, path.Base(aicontext.WorkflowPath), gh.CreateWorkflowDispatchEventRequest{Ref: branch})
	// GitHub answers 204, and 200 once it returns run details; either is a start.
	if err == nil || (resp != nil && (resp.StatusCode == http.StatusNoContent || resp.StatusCode == http.StatusOK)) {
		return nil
	}
	e := classify(resp, err)
	if errors.Is(e, ErrForbidden) {
		return fmt.Errorf("github: run context workflow: %w; check the App installation on %s: it needs \"Actions\" (actions) read and write, and changed permissions must be accepted on the installation", e, c.target)
	}
	return errorf("run context workflow", e)
}

func (c *appClient) ContextSetupMerged(ctx context.Context, repo string, number int, branch string) (bool, error) {
	owner, name, err := splitRepo(repo)
	if err != nil {
		return false, err
	}
	pr, resp, err := c.asInstallation.PullRequests.Get(ctx, owner, name, number)
	if err != nil {
		return false, c.fail("verify context setup merge", resp, err)
	}
	return pr.GetMerged() && pr.GetBase().GetRef() == branch && pr.GetMergeCommitSHA() != "", nil
}

func (c *appClient) ReadContextPublication(ctx context.Context, repo, branch string) (*ContextPublication, error) {
	source, err := c.ReadContextSetup(ctx, repo, branch)
	if err != nil {
		return nil, err
	}
	owner, name, _ := splitRepo(repo)
	ref, resp, err := c.asInstallation.Git.GetRef(ctx, owner, name, "heads/"+aicontext.OutputBranch)
	if err != nil {
		return nil, c.fail("read context output branch", resp, err)
	}
	commit, resp, err := c.asInstallation.Git.GetCommit(ctx, owner, name, ref.GetObject().GetSHA())
	if err != nil {
		return nil, c.fail("read context output commit", resp, err)
	}
	tree, resp, err := c.asInstallation.Git.GetTree(ctx, owner, name, commit.GetTree().GetSHA(), true)
	if err != nil {
		return nil, c.fail("read context output tree", resp, err)
	}
	if tree.GetTruncated() || len(tree.Entries) > 8 {
		return nil, fmt.Errorf("context output tree exceeds its bounded managed layout")
	}
	blobs := map[string][]byte{}
	for _, entry := range tree.Entries {
		if entry.GetType() == "tree" && (entry.GetPath() == ".zoomies" || entry.GetPath() == aicontext.OutputDirectory) {
			continue
		}
		p := strings.TrimPrefix(entry.GetPath(), aicontext.OutputDirectory+"/")
		if entry.GetMode() != "100644" || entry.GetType() != "blob" || p == entry.GetPath() || (p != "snapshot.json" && p != "manifest.json" && p != "NOTICE.md") || blobs[p] != nil {
			return nil, fmt.Errorf("context output contains an unowned or non-regular file")
		}
		limit := aicontext.MaxSnapshotBytes
		if p != "snapshot.json" {
			limit = 16384
		}
		if entry.GetSize() < 0 || entry.GetSize() > limit {
			return nil, fmt.Errorf("context output exceeds its managed file limit")
		}
		b, err := c.contextBlob(ctx, owner, name, entry.GetSHA(), limit)
		if err != nil {
			return nil, err
		}
		blobs[p] = b
	}
	if len(blobs) != 3 || string(blobs["NOTICE.md"]) != "Managed by Zoomies AI Context. Generated by Repomix. Do not edit.\n" {
		return nil, fmt.Errorf("context output is incomplete or lacks its managed notice")
	}
	var publication struct {
		SnapshotSHA string `json:"snapshot_sha256"`
	}
	if json.Unmarshal(blobs["manifest.json"], &publication) != nil || publication.SnapshotSHA != aicontext.Hash(blobs["snapshot.json"]) {
		return nil, fmt.Errorf("context publication fails integrity validation")
	}
	snapshot, err := aicontext.Decode(bytes.NewReader(blobs["snapshot.json"]))
	if err != nil {
		return nil, fmt.Errorf("context snapshot fails validation")
	}
	if err := c.verifyContextSnapshot(ctx, owner, name, branch, source.Commit, snapshot); err != nil {
		return nil, err
	}
	return &ContextPublication{source, ref.GetObject().GetSHA(), snapshot}, nil
}

// VerifyContextSnapshot checks a snapshot that did not come from a branch --
// a Zoomies-only upload -- against the repository itself: every file must be
// the regular blob at that path in the commit, and the commit must still be
// the head of the trusted branch.
func (c *appClient) VerifyContextSnapshot(ctx context.Context, repo, branch, commit string, snapshot *aicontext.Snapshot) error {
	owner, name, err := splitRepo(repo)
	if err != nil {
		return err
	}
	return c.verifyContextSnapshot(ctx, owner, name, branch, commit, snapshot)
}

func (c *appClient) verifyContextSnapshot(ctx context.Context, owner, name, branch, commit string, snapshot *aicontext.Snapshot) error {
	// File digests alone do not prove source authenticity. Match original Git
	// blob identities against the pinned trusted source tree before admitting it.
	sourceCommit, resp, err := c.asInstallation.Git.GetCommit(ctx, owner, name, commit)
	if err != nil {
		return c.fail("read trusted context commit", resp, err)
	}
	sourceTree, resp, err := c.asInstallation.Git.GetTree(ctx, owner, name, sourceCommit.GetTree().GetSHA(), true)
	if err != nil {
		return c.fail("read trusted context tree", resp, err)
	}
	if sourceTree.GetTruncated() || len(sourceTree.Entries) > 100000 {
		return fmt.Errorf("trusted context tree exceeds its validation limit")
	}
	entries := map[string]*gh.TreeEntry{}
	for _, e := range sourceTree.Entries {
		entries[e.GetPath()] = e
	}
	for _, file := range snapshot.Files {
		e := entries[file.Path]
		if e == nil || e.GetType() != "blob" || (e.GetMode() != "100644" && e.GetMode() != "100755") || e.GetSHA() != contextGitBlobSHA(file.Content) {
			return fmt.Errorf("%w: context content does not match regular files in the trusted commit", ErrContextMismatch)
		}
	}
	// An omitted file carries no content to hash, so the claim that it exists
	// and how large it is gets the same scrutiny: the trusted tree must have a
	// regular blob of that size at that path. Otherwise a workflow could list
	// files that were never there, or hide one behind a made-up reason.
	for _, o := range snapshot.Omitted {
		e := entries[o.Path]
		if e == nil || e.GetType() != "blob" || (e.GetMode() != "100644" && e.GetMode() != "100755") || e.GetSize() != o.Bytes {
			return fmt.Errorf("%w: an omitted file does not match a regular file of that size in the trusted commit", ErrContextMismatch)
		}
	}
	latest, resp, err := c.asInstallation.Git.GetRef(ctx, owner, name, "heads/"+branch)
	if err != nil {
		return c.fail("recheck trusted context branch", resp, err)
	}
	if latest.GetObject().GetSHA() != commit {
		return fmt.Errorf("%w: context source changed during validation; retry its latest generation", ErrContextMismatch)
	}
	return nil
}

func contextGitBlobSHA(content string) string {
	h := sha1.New()
	fmt.Fprintf(h, "blob %d\x00", len(content))
	h.Write([]byte(content))
	return hex.EncodeToString(h.Sum(nil))
}
func (c *appClient) contextBlob(ctx context.Context, owner, name, sha string, limit int) ([]byte, error) {
	blob, resp, err := c.asInstallation.Git.GetBlob(ctx, owner, name, sha)
	if err != nil {
		return nil, c.fail("read bounded context blob", resp, err)
	}
	if blob.GetSize() > limit || blob.GetEncoding() != "base64" || len(blob.GetContent()) > (limit*4/3)+4096 {
		return nil, fmt.Errorf("context blob exceeds its size or encoding limit")
	}
	b, err := base64.StdEncoding.DecodeString(strings.ReplaceAll(blob.GetContent(), "\n", ""))
	if err != nil || len(b) > limit || len(b) != blob.GetSize() || contextGitBlobSHA(string(b)) != sha {
		return nil, fmt.Errorf("context blob fails decoding")
	}
	return b, nil
}

