func TestContextPublicationVerifiesOriginalGitBlobsRatherThanSelfReportedHashes(t *testing.T) {
	fake, client := migrationFake(t)
	fake.AddFile("acme/widgets", "src/main.go", "package widgets\n")
	source, err := client.(ContextSetupClient).ReadContextSetup(t.Context(), "acme/widgets", "main")
	if err != nil {
		t.Fatal(err)
	}
	cfg := aicontext.DefaultConfig("main")
	hash, _ := cfg.Hash()
	snapshot := aicontext.Snapshot{Manifest: aicontext.Manifest{SchemaVersion: 1, Repository: aicontext.RepositoryKey{GitHubHost: "github.com", InstallationID: "1", RepositoryID: source.Repository.ID}, SourceBranch: "main", SourceCommit: source.Commit, ConfigHash: hash, GeneratedAt: time.Now(), Manager: "zoomies", Generator: "repomix@1.18.1"}, Files: []aicontext.File{{Path: "src/main.go", Content: "package widgets\n", SHA256: aicontext.Hash([]byte("package widgets\n"))}}}
	publish := func(extra bool) {
		body, _ := json.Marshal(snapshot)
		manifest, _ := json.Marshal(map[string]string{"snapshot_sha256": aicontext.Hash(body)})
		files := map[string]string{aicontext.OutputDirectory + "/snapshot.json": string(body), aicontext.OutputDirectory + "/manifest.json": string(manifest), aicontext.OutputDirectory + "/NOTICE.md": "Managed by Zoomies AI Context. Generated by Repomix. Do not edit.\n"}
		if extra {
			files["unexpected.go"] = "package injected"
		}
		fake.SetContextBranch("acme/widgets", aicontext.OutputBranch, files)
	}
	ingestion := client.(ContextIngestionClient)
	publish(false)
	if _, err := ingestion.ReadContextPublication(t.Context(), "acme/widgets", "main"); err != nil {
		t.Fatal(err)
	}
	snapshot.Files[0].Content = "package forged\n"
	snapshot.Files[0].SHA256 = aicontext.Hash([]byte(snapshot.Files[0].Content))
	publish(false)
	if _, err := ingestion.ReadContextPublication(t.Context(), "acme/widgets", "main"); err == nil || !strings.Contains(err.Error(), "trusted commit") {
		t.Fatalf("forgery admitted: %v", err)
	}
	snapshot.Files[0].Content = "package widgets\n"
	snapshot.Files[0].SHA256 = aicontext.Hash([]byte(snapshot.Files[0].Content))
	publish(true)
	if _, err := ingestion.ReadContextPublication(t.Context(), "acme/widgets", "main"); err == nil {
		t.Fatal("unowned file admitted")
	}
	publish(false)
	fake.SetFileMode("acme/widgets", "src/main.go", "120000")
	fake.AddFile("acme/widgets", "src/main.go", "package widgets\n")
	if _, err := ingestion.ReadContextPublication(t.Context(), "acme/widgets", "main"); err == nil {
		t.Fatal("symlink admitted")
	}
}

func TestContextSetupMergeRequiresTheReviewedBaseBranch(t *testing.T) {
	fake, client := migrationFake(t)
	setup := client.(ContextSetupClient)
	source, err := setup.ReadContextSetup(t.Context(), "acme/widgets", "main")
	if err != nil {
		t.Fatal(err)
	}
	pr, err := setup.OpenContextSetup(t.Context(), ContextSetupRequest{Repo: "acme/widgets", Base: "main", BaseCommit: source.Commit, Head: "context-merge-check", PlanHash: strings.Repeat("a", 64), Files: []aicontext.SetupChange{{Path: "AGENTS.md", Mode: "100644", Content: "guidance"}}})
	if err != nil {
		t.Fatal(err)
	}
	ingestion := client.(ContextIngestionClient)
	if merged, err := ingestion.ContextSetupMerged(t.Context(), "acme/widgets", pr.Number, "main"); err != nil || merged {
		t.Fatalf("open PR: %v %v", merged, err)
	}
	if !fake.MergeContextPull("acme/widgets", pr.Number) {
		t.Fatal("merge failed")
	}
	if merged, err := ingestion.ContextSetupMerged(t.Context(), "acme/widgets", pr.Number, "main"); err != nil || !merged {
		t.Fatalf("merged PR: %v %v", merged, err)
	}
	if merged, err := ingestion.ContextSetupMerged(t.Context(), "acme/widgets", pr.Number, "other"); err != nil || merged {
		t.Fatalf("wrong base: %v %v", merged, err)
	}
}

package github

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"path"
	"sort"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/aicontext"
	"github.com/eyupio/zoomies/internal/config"
	gh "github.com/google/go-github/v88/github"
)

// ContextRunReader reads what the managed workflow did, so that a context that
// has not been published can be explained instead of only noticed. It is
// read-only and needs the Actions read permission the App already has for the
// fleet; starting a run is ContextWorkflowDispatcher's, and separate.
type ContextRunReader interface {
	// LatestContextRun is the most informative run of the managed workflow for a
	// commit, or nil when it has none.
	LatestContextRun(ctx context.Context, repo, commit string) (*ContextRun, error)
	// ContextJobErrors is the error lines of one job's log, bounded. It is nil,
	// with no error, when the job has no log: it never started, or the log has
	// expired.
	ContextJobErrors(ctx context.Context, repo string, jobID int64) ([]string, error)
	// ContextArtifactUsage is what the repository's unexpired artifacts hold.
	ContextArtifactUsage(ctx context.Context, repo string) (*aicontext.ArtifactUsage, error)
}

// ContextRun is one run, in the terms aicontext.Diagnose reads.
type ContextRun struct {
	ID        int64
	URL       string
	CreatedAt time.Time
	UpdatedAt time.Time
	Facts     aicontext.RunFacts
	// JobIDs are GitHub's ids for Facts.Jobs, in the same order.
	JobIDs []int64
}

const (
	// maxContextLog bounds how much of one job's log is read. The managed
	// workflow's logs are small -- the generator prints paths and sizes, never
	// source -- so this is a ceiling against a log that is not that, not a
	// working size.
	maxContextLog = 8 << 20
	// maxContextErrorLines and maxContextErrorLine bound what is kept of it.
	maxContextErrorLines = 12
	maxContextErrorLine  = 300
	// maxArtifactPages bounds the artifact listing: a thousand artifacts is
	// enough to say what is using the storage, and past it the totals are
	// reported as at least.
	maxArtifactPages = 10
	artifactPageSize = 100
)

// LatestContextRun lists the runs for a commit, newest first, and returns the
// first that says something. A run cancelled by a newer one is not an answer --
// the managed workflow's concurrency group cancels the previous run on purpose
// -- so it is skipped for an older one, and returned only when every run was
// cancelled, so that the caller can still tell nothing has happened since.
func (c *appClient) LatestContextRun(ctx context.Context, repo, commit string) (*ContextRun, error) {
	owner, name, err := splitRepo(repo)
	if err != nil {
		return nil, err
	}
	runs, resp, err := c.asInstallation.Actions.ListWorkflowRunsByFileName(ctx, owner, name, path.Base(aicontext.WorkflowPath),
		&gh.ListWorkflowRunsOptions{HeadSHA: commit, ListOptions: gh.ListOptions{PerPage: 10}})
	if err != nil {
		return nil, c.fail("list context workflow runs", resp, err)
	}
	var pick, cancelled *gh.WorkflowRun
	for _, r := range runs.WorkflowRuns {
		if r.GetStatus() == "completed" && r.GetConclusion() == "cancelled" {
			if cancelled == nil {
				cancelled = r
			}
			continue
		}
		pick = r
		break
	}
	if pick == nil {
		pick = cancelled
	}
	if pick == nil {
		return nil, nil
	}
	run := &ContextRun{
		ID: pick.GetID(), URL: pick.GetHTMLURL(),
		CreatedAt: pick.GetCreatedAt().Time, UpdatedAt: pick.GetUpdatedAt().Time,
		Facts: aicontext.RunFacts{Status: pick.GetStatus(), Conclusion: pick.GetConclusion()},
	}
	// A run that has not finished is reported as it is; its jobs are not needed
	// to know that it must be left alone, and a run that was cancelled or never
	// started has none worth reading.
	if pick.GetStatus() != "completed" || pick.GetConclusion() == "cancelled" || pick.GetConclusion() == "startup_failure" {
		return run, nil
	}
	jobs, resp, err := c.asInstallation.Actions.ListWorkflowJobs(ctx, owner, name, pick.GetID(),
		&gh.ListWorkflowJobsOptions{Filter: "latest", ListOptions: gh.ListOptions{PerPage: 20}})
	if err != nil {
		return nil, c.fail("list context workflow jobs", resp, err)
	}
	for _, j := range jobs.Jobs {
		job := aicontext.JobFacts{Name: j.GetName(), Conclusion: j.GetConclusion()}
		for _, s := range j.Steps {
			job.Steps = append(job.Steps, aicontext.StepFacts{Name: s.GetName(), Conclusion: s.GetConclusion()})
		}
		run.Facts.Jobs = append(run.Facts.Jobs, job)
		run.JobIDs = append(run.JobIDs, j.GetID())
	}
	return run, nil
}

// ContextJobErrors downloads one job's log and keeps only the lines that explain
// a failure: every ##[error] annotation, and the line before it. The generator and
// the upload and publication scripts end by raising SystemExit with their reason,
// which Actions prints as an ordinary line immediately before its own "Process
// completed with exit code 1" annotation, so the reason is the line before.
//
// The log lives at a pre-signed address on another host. The request for it is
// made without the installation's token for exactly that reason, and only to an
// address on the scheme of the API itself.
func (c *appClient) ContextJobErrors(ctx context.Context, repo string, jobID int64) ([]string, error) {
	owner, name, err := splitRepo(repo)
	if err != nil {
		return nil, err
	}
	u, resp, err := c.asInstallation.Actions.GetWorkflowJobLogs(ctx, owner, name, jobID, 0)
	if err != nil {
		// A log that is gone -- expired, or never written for a job that did not
		// start -- is an answer ("no log"), not a failure to ask.
		if resp != nil && (resp.StatusCode == http.StatusNotFound || resp.StatusCode == http.StatusGone) {
			return nil, nil
		}
		return nil, c.fail("read context job log", resp, err)
	}
	if !fetchableLogAddress(c.asInstallation.BaseURL(), u) {
		return nil, fmt.Errorf("github: the job log address is not one to fetch")
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("Range", "bytes=-8388608")
	httpClient := &http.Client{Timeout: 30 * time.Second, CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }}
	res, err := httpClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("github: read context job log: %w", err)
	}
	defer res.Body.Close()
	if res.StatusCode == http.StatusNotFound || res.StatusCode == http.StatusGone {
		return nil, nil
	}
	if res.StatusCode != http.StatusOK && res.StatusCode != http.StatusPartialContent {
		return nil, fmt.Errorf("github: read context job log: unexpected status %d", res.StatusCode)
	}
	body, err := readContextLogTail(res.Body)
	if err != nil {
		return nil, fmt.Errorf("github: read context job log: %w", err)
	}
	return errorLines(string(body)), nil
}

// fetchableLogAddress is whether this process may fetch a log from where GitHub
// said it is. The address is GitHub's to name, but it arrives in a response
// header and is about to be requested from the controller's own network, so it
// is held to what an operator-supplied URL is: it is on the API's scheme, names a
// host and no credentials, and does not point at this machine or a private
// network -- unless the API itself does, as an Enterprise Server on a LAN, or a
// test, legitimately does.
func fetchableLogAddress(apiBase string, log *url.URL) bool {
	api, err := url.Parse(apiBase)
	if err != nil || log == nil || log.Host == "" || log.User != nil || log.Scheme != api.Scheme {
		return false
	}
	apiIsPrivate := config.CheckOutboundURL("", apiBase, false) != nil
	return config.CheckOutboundURL("the job log address", log.String(), apiIsPrivate) == nil
}

// errorLines picks the lines of a log that explain why a job failed.
func errorLines(log string) []string {
	lines := strings.Split(log, "\n")
	var out []string
	for i, line := range lines {
		line = strings.TrimRight(stripLogTimestamp(line), "\r")
		if !strings.HasPrefix(line, "##[error]") {
			continue
		}
		if i > 0 {
			if prev := strings.TrimRight(stripLogTimestamp(lines[i-1]), "\r"); prev != "" && !strings.HasPrefix(prev, "##[") {
				out = append(out, clip(prev))
			}
		}
		out = append(out, clip(strings.TrimPrefix(line, "##[error]")))
	}
	if len(out) == 0 {
		for i, line := range lines {
			lower := strings.ToLower(line)
			if strings.Contains(lower, "error:") || strings.Contains(lower, "assertionerror") || strings.Contains(lower, "--- fail:") || strings.Contains(lower, "panic:") || strings.Contains(lower, "traceback") || strings.Contains(lower, "failed:") {
				for _, v := range lines[max(0, i-2):min(len(lines), i+6)] {
					if strings.TrimSpace(v) != "" {
						out = append(out, clip(stripLogTimestamp(v)))
					}
				}
			}
		}
	}
	// The last of them are the ones that ended the job.
	if len(out) > maxContextErrorLines {
		out = out[len(out)-maxContextErrorLines:]
	}
	return out
}

// stripLogTimestamp removes the "2026-10-06T06:47:48.2010869Z " Actions puts in
// front of every line.
func stripLogTimestamp(line string) string {
	if head, rest, ok := strings.Cut(line, " "); ok && strings.HasSuffix(head, "Z") && strings.Contains(head, "T") {
		return rest
	}
	return line
}

func clip(s string) string {
	if len(s) > maxContextErrorLine {
		return s[:maxContextErrorLine]
	}
	return s
}

// ContextArtifactUsage totals the repository's unexpired artifacts and names the
// biggest groups by name. It reads at most maxArtifactPages pages.
func (c *appClient) ContextArtifactUsage(ctx context.Context, repo string) (*aicontext.ArtifactUsage, error) {
	owner, name, err := splitRepo(repo)
	if err != nil {
		return nil, err
	}
	usage := &aicontext.ArtifactUsage{}
	groups := map[string]*aicontext.ArtifactGroup{}
	for page := 1; ; page++ {
		list, resp, err := c.asInstallation.Actions.ListArtifacts(ctx, owner, name, &gh.ListArtifactsOptions{ListOptions: gh.ListOptions{PerPage: artifactPageSize, Page: page}})
		if err != nil {
			return nil, c.fail("list artifacts", resp, err)
		}
		for _, a := range list.Artifacts {
			if a.GetExpired() {
				continue
			}
			usage.Count++
			usage.Bytes += a.GetSizeInBytes()
			g := groups[a.GetName()]
			if g == nil {
				g = &aicontext.ArtifactGroup{Name: a.GetName()}
				groups[a.GetName()] = g
			}
			g.Count++
			g.Bytes += a.GetSizeInBytes()
		}
		if len(list.Artifacts) < artifactPageSize {
			break
		}
		if page == maxArtifactPages {
			usage.Partial = true
			break
		}
	}
	for _, g := range groups {
		usage.Largest = append(usage.Largest, *g)
	}
	sort.Slice(usage.Largest, func(i, j int) bool {
		if usage.Largest[i].Bytes != usage.Largest[j].Bytes {
			return usage.Largest[i].Bytes > usage.Largest[j].Bytes
		}
		return usage.Largest[i].Name < usage.Largest[j].Name
	})
	if len(usage.Largest) > 3 {
		usage.Largest = usage.Largest[:3]
	}
	return usage, nil
}

var _ ContextRunReader = (*appClient)(nil)

// Servers that honour Range return just the tail. A bounded streaming fallback
// keeps late evidence without retaining the entire log in memory.
func readContextLogTail(r io.Reader) ([]byte, error) {
	tail := make([]byte, 0, maxContextLog)
	buf := make([]byte, 64<<10)
	total := 0
	for {
		n, err := r.Read(buf)
		total += n
		if total > 64<<20 {
			return nil, fmt.Errorf("job log exceeds the bounded download limit; inspect its failed step on GitHub")
		}
		if n > 0 {
			if len(tail)+n > maxContextLog {
				drop := len(tail) + n - maxContextLog
				copy(tail, tail[drop:])
				tail = tail[:len(tail)-drop]
			}
			tail = append(tail, buf[:n]...)
		}
		if err == io.EOF {
			return tail, nil
		}
		if err != nil {
			return nil, err
		}
	}
}

package github

import (
	"context"
	"encoding/base64"
	"errors"
	"fmt"
	"net/http"
	"path"
	"strings"

	"github.com/eyupio/zoomies/internal/agentguidance"
	"github.com/eyupio/zoomies/internal/aicontext"
	gh "github.com/google/go-github/v88/github"
)

var ErrSetupConflict = errors.New("github: repository setup changed; review it again")

// ContextSetupClient keeps source setup apart from the runner-only interface.
type ContextSetupClient interface {
	ReadContextSetup(context.Context, string, string) (*ContextSetupSource, error)
	OpenContextSetup(context.Context, ContextSetupRequest) (*PullRequest, error)
}

type ContextSetupSource struct {
	Repository Repository
	Commit     string
	Inventory  []string
	Files      []aicontext.SetupFile
}

type ContextSetupRequest struct {
	Action     string
	Repo       string
	Base       string
	BaseCommit string
	Head       string
	PlanHash   string
	Files      []aicontext.SetupChange
}

// AgentGuidanceClient reads evidence for a guidance proposal independently of
// AI Context registration and never needs Workflows write permission.
type AgentGuidanceClient interface {
	ReadAgentGuidance(context.Context, string, string) (*ContextSetupSource, error)
	OpenContextSetup(context.Context, ContextSetupRequest) (*PullRequest, error)
}

func (c *appClient) ReadContextSetup(ctx context.Context, repo, branch string) (*ContextSetupSource, error) {
	return c.readSetupSource(ctx, repo, branch, false)
}

func (c *appClient) ReadAgentGuidance(ctx context.Context, repo, branch string) (*ContextSetupSource, error) {
	return c.readSetupSource(ctx, repo, branch, true)
}

func (c *appClient) readSetupSource(ctx context.Context, repo, branch string, guidance bool) (*ContextSetupSource, error) {
	owner, name, err := splitRepo(repo)
	if err != nil {
		return nil, err
	}
	r, resp, err := c.asInstallation.Repositories.Get(ctx, owner, name)
	if err != nil {
		return nil, c.fail("verify context repository", resp, err)
	}
	if guidance && branch == "" {
		branch = r.GetDefaultBranch()
	}
	if branch == "" {
		return nil, fmt.Errorf("%w: repository has no default branch", ErrSetupConflict)
	}
	ref, resp, err := c.asInstallation.Git.GetRef(ctx, owner, name, "heads/"+branch)
	if err != nil {
		return nil, c.fail("pin context source branch", resp, err)
	}
	commit := ref.GetObject().GetSHA()
	out := &ContextSetupSource{Repository: repositoryOf(r), Commit: commit, Files: []aicontext.SetupFile{}}
	gitCommit, resp, err := c.asInstallation.Git.GetCommit(ctx, owner, name, commit)
	if err != nil {
		return nil, c.fail("read context source commit", resp, err)
	}
	trees := map[string]*gh.Tree{}
	fileAt := func(p string) (*gh.TreeEntry, error) {
		treeSHA := gitCommit.GetTree().GetSHA()
		parts := strings.Split(p, "/")
		for i, part := range parts {
			tree := trees[treeSHA]
			if tree == nil {
				var resp *gh.Response
				var err error
				tree, resp, err = c.asInstallation.Git.GetTree(ctx, owner, name, treeSHA, false)
				if err != nil {
					return nil, c.fail("verify setup file modes", resp, err)
				}
				if tree.GetTruncated() || len(tree.Entries) > 10000 {
					return nil, fmt.Errorf("%w: repository tree exceeds setup preview limits", ErrSetupConflict)
				}
				trees[treeSHA] = tree
			}
			var entry *gh.TreeEntry
			for _, e := range tree.Entries {
				if e.GetPath() == part {
					entry = e
					break
				}
			}
			if entry == nil {
				return nil, nil
			}
			if i == len(parts)-1 {
				if entry.GetType() != "blob" || entry.GetMode() != "100644" && entry.GetMode() != "100755" {
					return nil, fmt.Errorf("%w: %s must be a regular file", ErrSetupConflict, p)
				}
				return entry, nil
			}
			if entry.GetType() != "tree" || entry.GetMode() != "040000" {
				return nil, fmt.Errorf("%w: %s crosses a symlink or non-directory", ErrSetupConflict, p)
			}
			treeSHA = entry.GetSHA()
		}
		return nil, nil
	}
	read := func(p string) error {
		entry, err := fileAt(p)
		if err != nil {
			return err
		}
		if entry == nil {
			return nil
		}
		if entry.GetSize() > 512<<10 {
			return fmt.Errorf("%w: %s exceeds setup preview limits", ErrSetupConflict, p)
		}
		blob, resp, err := c.asInstallation.Git.GetBlob(ctx, owner, name, entry.GetSHA())
		if err != nil {
			return c.fail("read pinned setup file", resp, err)
		}
		if blob.GetEncoding() != "base64" || blob.GetSize() > 512<<10 || len(blob.GetContent()) > 1<<20 {
			return fmt.Errorf("%w: %s has unsupported content", ErrSetupConflict, p)
		}
		content, err := base64.StdEncoding.DecodeString(strings.ReplaceAll(blob.GetContent(), "\n", ""))
		if err != nil || len(content) != entry.GetSize() || contextGitBlobSHA(string(content)) != entry.GetSHA() {
			return fmt.Errorf("%w: setup file failed integrity validation", ErrSetupConflict)
		}
		out.Files = append(out.Files, aicontext.SetupFile{Mode: entry.GetMode(), Path: p, SHA: entry.GetSHA(), Content: string(content)})
		return nil
	}
	paths := []string{aicontext.ConfigPath, aicontext.ContextGuidePath, "CLAUDE.md", ".claude/CLAUDE.md", "AGENTS.md", aicontext.WorkflowPath, aicontext.GeneratorPackagePath, aicontext.GeneratorLockPath}
	if guidance {
		inventory, err := c.KennelGuidanceInventory(ctx, repo, gitCommit.GetTree().GetSHA())
		if err != nil {
			return nil, err
		}
		if inventory.Partial {
			return nil, fmt.Errorf("%w: guidance inventory is incomplete; bring the files within the inspection limits before proposing changes", ErrSetupConflict)
		}
		out.Inventory = inventory.Paths
		paths = []string{"Makefile", "package.json"}
		for _, f := range inventory.Files {
			paths = append(paths, f.Path)
		}
	}
	for _, p := range paths {
		if err := read(p); err != nil {
			return nil, err
		}
	}
	if guidance {
		return out, nil
	}
	readme, resp, err := c.asInstallation.Repositories.GetReadme(ctx, owner, name, &gh.RepositoryContentGetOptions{Ref: commit})
	if err != nil && !errors.Is(classify(resp, err), ErrNotFound) {
		return nil, c.fail("locate pinned README", resp, err)
	}
	if err == nil && (strings.EqualFold(path.Base(readme.GetPath()), "README.md") || strings.EqualFold(path.Base(readme.GetPath()), "README.markdown")) && !strings.Contains(readme.GetPath(), "/") {
		if err := read(readme.GetPath()); err != nil {
			return nil, err
		}
	}
	return out, nil
}

func (c *appClient) OpenContextSetup(ctx context.Context, req ContextSetupRequest) (*PullRequest, error) {
	owner, name, err := splitRepo(req.Repo)
	if err != nil {
		return nil, err
	}
	if len(req.Files) == 0 || !aicontext.ValidBranch(req.Head) || !aicontext.ValidBranch(req.Base) || len(req.PlanHash) != 64 {
		return nil, fmt.Errorf("%w: setup has no valid reviewed changes", ErrSetupConflict)
	}
	// The exact base is checked before creating Git objects and again before
	// publishing a ref. User edits never get rebased or overwritten silently.
	ref, resp, err := c.asInstallation.Git.GetRef(ctx, owner, name, "heads/"+req.Base)
	if err != nil {
		return nil, c.fail("verify setup base", resp, err)
	}
	existing, existingResp, existingErr := c.asInstallation.Git.GetRef(ctx, owner, name, "heads/"+req.Head)
	if existingErr != nil && !errors.Is(classify(existingResp, existingErr), ErrNotFound) {
		return nil, c.fail("reconcile setup branch", existingResp, existingErr)
	}
	if existingErr != nil && ref.GetObject().GetSHA() != req.BaseCommit {
		return nil, ErrSetupConflict
	}
	base, resp, err := c.asInstallation.Git.GetCommit(ctx, owner, name, req.BaseCommit)
	if err != nil {
		return nil, c.fail("read setup base", resp, err)
	}
	if req.Action == "agent-guidance" {
		if len(req.Files) > agentguidance.MaxFiles+2 {
			return nil, ErrSetupConflict
		}
		for _, f := range req.Files {
			if !agentguidance.SafePath(f.Path) || !agentguidance.EntryPoint(f.Path) || f.Delete || len(f.Content) > agentguidance.MaxBytes {
				return nil, ErrSetupConflict
			}
		}
	}
	entries := make([]*gh.TreeEntry, 0, len(req.Files))
	for _, f := range req.Files {
		if f.Delete {
			if f.PreviousSHA == "" || f.Content != "" {
				return nil, ErrSetupConflict
			}
			entries = append(entries, &gh.TreeEntry{Path: gh.Ptr(f.Path), Mode: gh.Ptr(contextSetupFileMode(f.Mode)), Type: gh.Ptr("blob")})
		} else {
			entries = append(entries, &gh.TreeEntry{Path: gh.Ptr(f.Path), Mode: gh.Ptr(contextSetupFileMode(f.Mode)), Type: gh.Ptr("blob"), Content: gh.Ptr(f.Content)})
		}
	}
	tree, resp, err := c.asInstallation.Git.CreateTree(ctx, owner, name, base.GetTree().GetSHA(), entries)
	if err != nil {
		return nil, c.migrationError("prepare complete setup tree", classify(resp, err))
	}
	title := "Enable Zoomies AI Context"
	switch req.Action {
	case "agent-guidance":
		title = "Improve agent guidance with Zoomies"
	case "reinstall":
		title = "Reinstall Zoomies AI Context"
	case "amend":
		title = "Amend Zoomies AI Context"
	case "remove":
		title = "Remove Zoomies AI Context"
	case "":
	default:
		return nil, ErrSetupConflict
	}
	message := title + "\n\nZoomies setup: " + req.PlanHash

	if existingErr == nil {
		previous, resp, err := c.asInstallation.Git.GetCommit(ctx, owner, name, existing.GetObject().GetSHA())
		if err != nil {
			return nil, c.fail("verify existing setup branch", resp, err)
		}
		if previous.GetTree().GetSHA() != tree.GetSHA() || previous.GetMessage() != message || len(previous.Parents) != 1 || previous.Parents[0].GetSHA() != req.BaseCommit {
			return nil, fmt.Errorf("%w: existing proposal differs from this preview or its base; its branch has been preserved", ErrSetupConflict)
		}
	} else {
		commit, resp, err := c.asInstallation.Git.CreateCommit(ctx, owner, name, gh.Commit{Message: gh.Ptr(message), Tree: tree, Parents: []*gh.Commit{{SHA: gh.Ptr(req.BaseCommit)}}}, nil)
		if err != nil {
			return nil, c.migrationError("prepare atomic setup commit", classify(resp, err))
		}
		ref, resp, err = c.asInstallation.Git.GetRef(ctx, owner, name, "heads/"+req.Base)
		if err != nil {
			return nil, c.fail("recheck setup base", resp, err)
		}
		if ref.GetObject().GetSHA() != req.BaseCommit {
			return nil, ErrSetupConflict
		}
		_, resp, err = c.asInstallation.Git.CreateRef(ctx, owner, name, gh.CreateRef{Ref: "refs/heads/" + req.Head, SHA: commit.GetSHA()})
		if err != nil {
			return nil, c.migrationError("publish complete setup branch", classify(resp, err))
		}
	}
	body := "Prepare this repository for AI coding assistants with Zoomies-managed Repomix context.\n\nReview every changed file below, including the workflow and the instruction and badge sections. Wait for this pull request's checks to pass before merging it; merging runs generation. It does not grant assistant connections source access. The workflow uses a read-only generation job and a separate write-only publication job. Action pins already in the repository are kept, so a reinstall does not move them.\n\nChanged files:\n" + changedFiles(req.Files)
	if req.Action == "agent-guidance" {
		body = "Review the proposed agent instruction files and commands declared in repository files. Existing guidance is preserved except for exact duplicate Claude adapters or unambiguous broken imports. This proposal does not install AI Context, change workflows or grant assistant access. Merge it, then press Recheck in Kennel Club.\n\nChanged files:\n" + changedFiles(req.Files)
	}
	if req.Action == "remove" {
		body = "Remove the Zoomies AI Context workflow and managed files/sections. Other repository text and the historical generated context branch are preserved. Zoomies access, cached snapshots, readers and connection consent have been revoked; reinstall requires explicit access selection again.\n\nChanged files:\n" + changedFiles(req.Files)
	}
	marker := "<!-- zoomies-ai-context:setup " + req.PlanHash + " -->"
	if req.Action == "agent-guidance" {
		marker = "<!-- zoomies-agent-guidance:proposal " + req.PlanHash + " -->"
	}
	body += "\n" + marker
	// Closed PRs are included: a retry must not reopen a deliberately declined
	// proposal or produce a duplicate after an uncertain successful response.
	pulls, resp, err := c.asInstallation.PullRequests.List(ctx, owner, name, &gh.PullRequestListOptions{State: "all", Head: owner + ":" + req.Head, Base: req.Base, ListOptions: gh.ListOptions{PerPage: 100}})
	if err != nil {
		return nil, c.fail("reconcile setup pull request", resp, err)
	}
	if resp != nil && resp.NextPage != 0 {
		return nil, fmt.Errorf("%w: too many setup pull requests to reconcile safely", ErrSetupConflict)
	}
	if len(pulls) > 0 {
		if len(pulls) != 1 || pulls[0].GetBody() != body || pulls[0].GetTitle() != title {
			return nil, fmt.Errorf("%w: existing pull request differs from the reviewed setup", ErrSetupConflict)
		}
		pr := pulls[0]
		if pr.GetState() != "open" {
			return nil, fmt.Errorf("%w: the previous setup PR is closed; check its outcome before another setup", ErrSetupConflict)
		}
		return &PullRequest{Number: pr.GetNumber(), HTMLURL: pr.GetHTMLURL(), Branch: req.Head}, nil
	}
	pr, resp, err := c.asInstallation.PullRequests.Create(ctx, owner, name, &gh.NewPullRequest{Title: gh.Ptr(title), Body: gh.Ptr(body), Head: gh.Ptr(req.Head), Base: gh.Ptr(req.Base), Draft: gh.Ptr(req.Action == "agent-guidance")})
	if err != nil {
		// Keep the complete branch even on a timeout: the request may have opened
		// a PR. The same durable head is reconciled on the next explicit retry.
		if resp == nil || resp.StatusCode >= 500 || resp.StatusCode == http.StatusRequestTimeout {
			return nil, fmt.Errorf("%w; setup branch retained for safe retry", err)
		}
		return nil, c.migrationError("open setup pull request", classify(resp, err))
	}
	return &PullRequest{Number: pr.GetNumber(), HTMLURL: pr.GetHTMLURL(), Branch: req.Head}, nil
}

func changedFiles(files []aicontext.SetupChange) string {
	var b strings.Builder
	for _, f := range files {
		state := "modified"
		switch {
		case f.Delete:
			state = "deleted"
		case f.PreviousSHA == "":
			state = "new"
		}
		b.WriteString("- `" + f.Path + "` (" + state + ")\n")
	}
	return b.String()
}

func contextSetupFileMode(mode string) string {
	if mode == "100755" {
		return mode
	}
	return "100644"
}

