func TestListAndDeleteRunners(t *testing.T) {
	eachTarget(t, func(t *testing.T, f *FakeGitHub, c Client, _ string, _ store.TargetType) {
		ctx := context.Background()
		orphan := f.AddRunner("registered-by-hand", []string{"linux"})

