func installationFor(f *FakeGitHub, apiBase string, kind store.TargetType, target string) *store.Installation {
	return &store.Installation{
		ID:             "ins_test",
		AppID:          f.AppID(),
		InstallationID: f.InstallationID(),
		Target:         target,
		TargetType:     kind,
