func checkoutTestSource() string {
	return "on: push\njobs:\n  build:\n    name: Build\n    runs-on: ubuntu-latest\n    steps:\n      - name: Checkout\n        uses: actions/checkout@" + strings.Repeat("b", 40) + "\n        with:\n          fetch-depth: 0\n      - name: Test\n        run: npm test\n"
}
func checkoutReaderFixture(t *testing.T, mode string) (*appClient, *int) {
	t.Helper()
	calls, runs, jobs := 0, 0, 0
	sha, treeSHA := strings.Repeat("a", 40), strings.Repeat("c", 40)
	source := checkoutTestSource()
	if mode == "matrix" {
		source = strings.Replace(source, "    name: Build", "    strategy: {matrix: {os: [linux]}}\n    name: Build", 1)
	}
	if mode == "unnamed" {
		source = strings.Replace(source, "      - name: Checkout\n        uses:", "      - uses:", 1)
	}
	blob := contextGitBlobSHA(source)
	c := delayTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		calls++
		if mode == "redirect" {
			w.Header().Set("Location", "/unscoped")
			w.WriteHeader(http.StatusFound)
			return
		}
		if r.Method != "GET" || r.Header.Get("If-None-Match") != "" {
			t.Error("mutable or conditional read")
		}
		var body any
		switch r.URL.Path {
		case "/repos/acme/repo/actions/runs/10/attempts/2":
			runs++
			body = map[string]any{"id": 10, "run_attempt": 2, "head_sha": sha, "workflow_id": 20, "event": "push", "path": ".github/workflows/private.yml", "status": "completed", "conclusion": "success", "repository": map[string]any{"full_name": "acme/repo"}, "run_started_at": "2026-10-14T01:00:00Z", "updated_at": "2026-10-14T01:00:10Z", "jobs_url": "https://attacker.invalid/jobs"}
			v := body.(map[string]any)
			switch mode {
			case "foreign_repo":
				v["repository"] = map[string]any{"full_name": "other/repo"}
			case "non_push":
				v["event"] = "pull_request"
			case "mutable_path":
				v["path"] = ".github/workflows/private.yml@main"
			case "missing_run_time":
				delete(v, "updated_at")
			case "moved_run":
				if runs == 2 {
					v["head_sha"] = strings.Repeat("d", 40)
				}
			}
		case "/repos/acme/repo/actions/jobs/100":
			jobs++
			step := map[string]any{"name": "Checkout", "number": 42, "status": "completed", "conclusion": "success", "started_at": "2026-10-14T01:00:02Z", "completed_at": "2026-10-14T01:00:06.200Z"}
			switch mode {
			case "step_failed":
				step["conclusion"] = "failure"
			case "missing_step_time":
				delete(step, "started_at")
			case "negative_time":
				step["completed_at"] = "2026-10-14T01:00:01Z"
			case "outside_job":
				step["completed_at"] = "2026-10-14T01:00:09Z"
			case "moved_step":
				if jobs == 2 {
					step["completed_at"] = "2026-10-14T01:00:07Z"
				}
			}
			steps := []any{map[string]any{"name": "Set up job", "number": 1}, step}
			if mode == "duplicate_name" {
				steps = append(steps, map[string]any{"name": "Checkout", "number": 99})
			}
			if mode == "duplicate_number" {
				steps = append(steps, map[string]any{"name": "other", "number": 42})
			}
			body = map[string]any{"id": 100, "run_id": 10, "run_attempt": 2, "head_sha": sha, "name": "Build", "status": "completed", "conclusion": "success", "started_at": "2026-10-14T01:00:01Z", "completed_at": "2026-10-14T01:00:08Z", "steps": steps, "runner_name": "private-runner", "labels": []string{"private-label"}}
			v := body.(map[string]any)
			switch mode {
			case "foreign_attempt":
				v["run_attempt"] = 1
			case "foreign_head":
				v["head_sha"] = strings.Repeat("d", 40)
			case "wrong_job_name":
				v["name"] = "Build (linux)"
			}
		case "/repos/acme/repo/contents/.github/workflows/private.yml":
			if r.URL.Query().Get("ref") != sha {
				t.Error("mutable contents ref")
			}
			body = map[string]any{"type": "file", "path": ".github/workflows/private.yml", "encoding": "base64", "size": len(source), "sha": blob, "content": base64.StdEncoding.EncodeToString([]byte(source)), "download_url": "https://attacker.invalid/source"}
			v := body.(map[string]any)
			if mode == "corrupt_source" {
				v["sha"] = strings.Repeat("d", 40)
			}
			if mode == "large_source" {
				v["size"] = 32769
			}
		case "/repos/acme/repo/git/commits/" + sha:
			body = map[string]any{"sha": sha, "tree": map[string]any{"sha": treeSHA}}
			if mode == "foreign_commit" {
				body.(map[string]any)["sha"] = strings.Repeat("d", 40)
			}
		case "/repos/acme/repo/git/trees/" + treeSHA:
			if r.URL.Query().Get("recursive") != "1" {
				t.Error("missing bounded tree enumeration")
			}
			entry := map[string]any{"path": ".github/workflows/private.yml", "mode": "100755", "type": "blob", "sha": blob}
			body = map[string]any{"sha": treeSHA, "truncated": false, "tree": []any{entry}}
			switch mode {
			case "truncated_tree":
				body.(map[string]any)["truncated"] = true
			case "unknown_tree":
				delete(body.(map[string]any), "truncated")
			case "symlink":
				entry["mode"] = "120000"
			case "foreign_blob":
				entry["sha"] = strings.Repeat("d", 40)
			case "foreign_tree":
				body.(map[string]any)["sha"] = strings.Repeat("d", 40)
			}
		default:
			t.Errorf("unexpected endpoint %s", r.URL)
			http.NotFound(w, r)
			return
		}
		if err := json.NewEncoder(w).Encode(body); err != nil {
			t.Error(err)
		}
	})
	return c, &calls
}
func TestCheckoutEvidenceAssociatesUniqueNamesWithoutGuessingStepNumberOrFileMode(t *testing.T) {
	c, calls := checkoutReaderFixture(t, "valid")
	s := CheckoutSelection{RunID: 10, Attempt: 2, GitHubJobID: 100, JobIndex: 0, StepIndex: 0}
	e, err := c.ReadCheckoutEvidence(context.Background(), "acme/repo", s)
	if err != nil {
		t.Fatal(err)
	}
	if *calls != CheckoutEvidenceMaximumRequests || !ValidCheckoutEvidence(e, "acme/repo", s) || e.StepNumber != 42 || e.Source.File.Mode != "100755" || *e.Timing.CheckoutMS != 4200 || e.Timing.EvidenceID != "checkout:10:2:100:42" {
		t.Fatalf("invalid bounded evidence %+v calls=%d", e, *calls)
	}
	body, _ := json.Marshal(e)
	if strings.Contains(string(body), "private-runner") || strings.Contains(string(body), "attacker.invalid") {
		t.Fatal("unrelated metadata retained")
	}
}
func TestCheckoutEvidenceRefusesAmbiguousUnsupportedForeignAndMovingFacts(t *testing.T) {
	for _, mode := range []string{"redirect", "foreign_repo", "non_push", "mutable_path", "missing_run_time", "moved_run", "foreign_attempt", "foreign_head", "wrong_job_name", "step_failed", "missing_step_time", "negative_time", "outside_job", "moved_step", "duplicate_name", "duplicate_number", "corrupt_source", "large_source", "matrix", "unnamed", "foreign_commit", "truncated_tree", "unknown_tree", "symlink", "foreign_blob", "foreign_tree"} {
		t.Run(mode, func(t *testing.T) {
			c, calls := checkoutReaderFixture(t, mode)
			if e, err := c.ReadCheckoutEvidence(context.Background(), "acme/repo", CheckoutSelection{RunID: 10, Attempt: 2, GitHubJobID: 100}); err == nil || e != nil || *calls > CheckoutEvidenceMaximumRequests {
				t.Fatal("unsupported source/timing accepted", err, fmt.Sprint(*calls))
			}
		})
	}
}

func TestCheckoutEvidenceLocatesTheStepWithinTheSameRequestBudget(t *testing.T) {
	c, calls := checkoutReaderFixture(t, "valid")
	located := CheckoutSelection{RunID: 10, Attempt: 2, GitHubJobID: 100, Locate: true}
	e, err := c.ReadCheckoutEvidence(context.Background(), "acme/repo", located)
	if err != nil {
		t.Fatal(err)
	}
	want := CheckoutSelection{RunID: 10, Attempt: 2, GitHubJobID: 100}
	if *calls != CheckoutEvidenceMaximumRequests || e.Selection != want || e.Selection.Locate || !ValidCheckoutEvidence(e, "acme/repo", want) || e.StepNumber != 42 {
		t.Fatalf("a located read must cost the same and name the positions it found: %+v calls=%d", e.Selection, *calls)
	}
	if ValidCheckoutSelection(CheckoutSelection{RunID: 10, Attempt: 2, GitHubJobID: 100, StepIndex: 1, Locate: true}) {
		t.Fatal("a located selection must not also name a position")
	}
}

package github

import (
	"errors"
	"net/http"
	"net/url"
	"strings"
	"testing"

	gh "github.com/google/go-github/v88/github"
)

// GitHub's 401, 403, 404 and 429 all became sentences an operator can act on;
// a 422 -- a runner name already taken, a label GitHub will not accept -- fell
// through as go-github's raw "422 Validation Failed", which is what a runner
// row then showed as the reason it never started.
func TestAValidationFailureSaysWhatGitHubObjectedTo(t *testing.T) {
	cases := []struct {
		name string
		errs []gh.Error
		msg  string
		want string
	}{
		{
			name: "a message per field",
			errs: []gh.Error{{Resource: "Runner", Field: "name", Code: "already_exists", Message: "A runner with this name already exists"}},
			msg:  "Validation Failed",
			want: "A runner with this name already exists",
		},
		{
			name: "a code where there is no message",
			errs: []gh.Error{{Resource: "Runner", Field: "labels", Code: "invalid"}},
			msg:  "Validation Failed",
			want: "Runner labels invalid",
		},
		{
			name: "nothing but the message",
			msg:  "Validation Failed",
			want: "Validation Failed",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			err := classify(nil, validationError(tc.msg, tc.errs))
			if !errors.Is(err, ErrInvalid) {
				t.Fatalf("classify = %v, want it to match ErrInvalid", err)
			}
			if !strings.Contains(err.Error(), tc.want) {
				t.Fatalf("classify = %q, want it to carry %q", err, tc.want)
			}
		})
	}
}

// The statuses that already had answers keep them: a 422 must not swallow the
// ones a caller branches on.
func TestClassifyKeepsTheOtherStatusesApart(t *testing.T) {
	for status, want := range map[int]error{
		http.StatusNotFound:            ErrNotFound,
		http.StatusForbidden:           ErrForbidden,
		http.StatusTooManyRequests:     ErrRateLimited,
		http.StatusUnprocessableEntity: ErrInvalid,
	} {
		err := classify(nil, &gh.ErrorResponse{Response: response(status), Message: "nope"})
		if !errors.Is(err, want) {
			t.Errorf("classify(%d) = %v, want %v", status, err, want)
		}
	}
}

func validationError(message string, errs []gh.Error) *gh.ErrorResponse {
	return &gh.ErrorResponse{
		Response: response(http.StatusUnprocessableEntity),
		Message:  message,
		Errors:   errs,
	}
}

func response(status int) *http.Response {
	return &http.Response{
		StatusCode: status,
		Request:    &http.Request{Method: http.MethodPost, URL: &url.URL{Scheme: "https", Host: "api.github.com", Path: "/repos/acme/widgets/actions/runners"}},
	}
}

// A 5xx is GitHub failing, which no permission fixes and no retry in a minute
// helps; it is told apart so callers that can wait do, and the message stays
// GitHub's own so a runner row still says what came back.
func TestAServerErrorIsToldApartAndKeepsItsMessage(t *testing.T) {
	raw := &gh.ErrorResponse{Response: &http.Response{StatusCode: http.StatusInternalServerError, Request: &http.Request{Method: "POST", URL: &url.URL{Path: "/x"}}}}
	err := classify(nil, raw)
	if !errors.Is(err, ErrServerError) {
		t.Fatalf("classify(500) = %v, want a server error", err)
	}
	if err.Error() != raw.Error() {
		t.Errorf("message = %q, want GitHub's own %q", err.Error(), raw.Error())
	}
	if errors.Is(classify(nil, &gh.ErrorResponse{Response: &http.Response{StatusCode: http.StatusBadRequest, Request: raw.Response.Request}}), ErrServerError) {
		t.Error("a 400 was called a server error")
	}
}

// Package github wraps everything Zoomies needs from the GitHub API: App
// authentication, minting runner credentials, listing runners and queued jobs,
// and validating inbound webhooks.
//
// Zoomies never asks an operator for a personal access token. It authenticates
// as a GitHub App and mints short-lived registration credentials itself, so
// there is no long-lived token sitting in a dotfile next to a runner.
package github

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// ErrNotFound is returned when GitHub reports a 404 for something Zoomies
// expected to exist.
var ErrNotFound = errors.New("github: not found")

// ErrRateLimited is returned when the installation has exhausted its quota.
// The caller backs off rather than hammering.
var ErrRateLimited = errors.New("github: rate limited")

// RateLimitedError is a refusal that says when to come back.
//
// GitHub sends the answer on every rate-limited response -- a reset instant on
// the primary limit, a retry-after duration on the secondary one -- and it used
// to be formatted straight into the message and lost, leaving every caller to
// guess a fixed wait. Guessing long wastes quota that came back minutes ago;
// guessing short spends the next window on refusals. So the number is carried.
//
// It wraps ErrRateLimited, so the callers that only ask "was this a rate limit"
// keep working through errors.Is and only the ones that want the time reach for
// errors.As.
type RateLimitedError struct {
	// ResetAt is when the quota refills, zero when GitHub did not say.
	ResetAt time.Time
	// RetryAfter is the secondary limit's answer, which is a duration rather
	// than an instant. Zero when unset.
	RetryAfter time.Duration
	Detail     string
}

func (e *RateLimitedError) Error() string {
	switch {
	case !e.ResetAt.IsZero():
		return fmt.Sprintf("%s: quota exhausted until %s%s",
			ErrRateLimited, e.ResetAt.UTC().Format(time.RFC3339), e.Detail)
	case e.RetryAfter > 0:
		return fmt.Sprintf("%s: secondary rate limit, retry after %s%s",
			ErrRateLimited, e.RetryAfter, e.Detail)
	}
	return ErrRateLimited.Error() + e.Detail
}

func (e *RateLimitedError) Unwrap() error { return ErrRateLimited }

// RetryAt is when a caller may try this installation again, given the time it
// is asking at, and whether GitHub said anything at all.
//
// A reset already in the past is no answer -- clocks drift, and a response can
// sit in a queue -- so it is reported as unknown and the caller keeps its own
// default rather than resuming into the same refusal.
func (e *RateLimitedError) RetryAt(now time.Time) (time.Time, bool) {
	if e == nil {
		return time.Time{}, false
	}
	if e.RetryAfter > 0 {
		return now.Add(e.RetryAfter), true
	}
	if !e.ResetAt.IsZero() && e.ResetAt.After(now) {
		return e.ResetAt, true
	}
	return time.Time{}, false
}

// RetryAfterRateLimit reports when err says an installation may be used again.
//
// It answers false for anything that is not a rate limit and for a rate limit
// GitHub said nothing useful about, which is the same thing to a caller: fall
// back to your own wait.
func RetryAfterRateLimit(err error, now time.Time) (time.Time, bool) {
	var rl *RateLimitedError
	if !errors.As(err, &rl) {
		return time.Time{}, false
	}
	return rl.RetryAt(now)
}

// ErrForbidden is returned for a 403 that is not a rate limit, usually meaning
// the App installation is missing a permission.
var ErrForbidden = errors.New("github: forbidden")

// ErrServerError is GitHub itself failing -- any 5xx. It is nothing the caller
// did and nothing a permission fixes, so it is told apart from ErrForbidden: the
// callers that can wait (Kennel Club) back off on it instead of asking again.
var ErrServerError = errors.New("github: server error")

// NewServerError marks err as GitHub failing, for the code that classifies a
// response and for tests that need the failure without the response.
func NewServerError(err error) error { return &serverError{err: err} }

// serverError keeps GitHub's own wording as the message and only adds the kind,
// so a runner row still shows "500 []" and not a paraphrase of it.
type serverError struct{ err error }

func (e *serverError) Error() string        { return e.err.Error() }
func (e *serverError) Unwrap() error        { return e.err }
func (e *serverError) Is(target error) bool { return target == ErrServerError }

// ErrInvalid is GitHub refusing a request as invalid rather than unauthorised:
// a runner name already taken, a label it will not accept. The detail carries
// the field-by-field reason, which is the part worth reading -- the message on
// a 422 is always "Validation Failed".
var ErrInvalid = errors.New("github: refused as invalid")

// ErrRunnerBusy is DeleteRunner refused because GitHub still considers the
// runner to be running a job. It wraps ErrInvalid -- the same 422 GitHub uses
// for every other "refused as invalid" case -- so a caller that only checks
// for ErrInvalid still catches it, and one that wants to tell this apart from
// a genuinely bad request (a stale ID, a name GitHub never had) can.
//
// This is usually not the operator's problem: GitHub's own bookkeeping can lag
// a few seconds behind the workflow_job "completed" webhook that told Zoomies
// the runner was free, and the delete loses that race. Deleting again once
// GitHub reports the runner idle succeeds without anyone doing anything.
var ErrRunnerBusy = errors.New("github: runner is still running a job")

// JITRequest asks GitHub for a just-in-time runner configuration.
type JITRequest struct {
	// Name must be unique within the target. GitHub rejects reuse.
	Name string
	// Labels are the custom labels this runner advertises, without the
	// implicit self-hosted/os/arch set.
	Labels []string
	// RunnerGroupID is 1 (Default) unless the pool names a group.
	RunnerGroupID int64
	// WorkFolder defaults to "_work".
	WorkFolder string
}

// JITConfig is the base64 blob handed to `actions-runner --jitconfig`. It
// registers an ephemeral runner exactly once and expires quickly, which is what
// makes it safe to pass through an environment variable.
type JITConfig struct {
	// Encoded is the base64 configuration.
	Encoded string
	// RunnerID is the ID GitHub assigned, so Zoomies can delete the
	// registration later if the runner never comes up.
	RunnerID int64
	// Name echoes the requested name.
	Name string
}

// RegistrationToken is the older credential, used by non-ephemeral pools that
// must run config.sh. It is valid for one hour.
type RegistrationToken struct {
	Token     string
	ExpiresAt time.Time
}

// Runner is a runner as GitHub sees it, used to reconcile Zoomies' view with
// reality and to clean up registrations Zoomies has lost track of.
type Runner struct {
	ID     int64
	Name   string
	OS     string
	Status string // online | offline
	Busy   bool
	Labels []string
	// Ephemeral is reported by GitHub for JIT-configured runners.
	Ephemeral bool
}

// QueuedJob is a job the fallback poller found unfinished: waiting for a
// runner, or already running on one. It carries only what the scheduler needs
// to match it to a pool and, once it has started, to its runner.
type QueuedJob struct {
	ID    int64
	RunID int64
	// RunNumber is GitHub's own sequential number for the workflow run --
	// free from the same run listing this job was found in, unlike the
	// webhook path, which has to ask for it separately.
	RunNumber    int64
	Repo         string
	WorkflowName string
	JobName      string
	Labels       []string
	QueuedAt     time.Time
	HTMLURL      string
	// RunnerName is set once GitHub has assigned the job.
	RunnerName  string
	Status      string
	Conclusion  string
	StartedAt   *time.Time
	CompletedAt *time.Time
}

// WorkflowRunState is GitHub's authoritative lifecycle for one workflow run.
// Status becomes "completed" before Conclusion is meaningful.
type WorkflowRunState struct {
	Status     string
	Conclusion string
	// RunNumber is the "#1009" GitHub's Actions UI shows next to the workflow
	// name. workflow_job deliveries never carry it, which is what this lookup
	// is for.
	RunNumber int64
	// Event is what started the run: push, pull_request, schedule and so on.
	Event string
}

// Cancelled reports whether GitHub has finished the whole run as cancelled.
// A cancelled workflow job by itself is deliberately not enough evidence.
func (s WorkflowRunState) Cancelled() bool {
	return s.Status == string(store.JobCompleted) && s.Conclusion == "cancelled"
}

// RunnerGroup is a runner group in the target org.
type RunnerGroup struct {
	ID         int64
	Name       string
	Default    bool
	Visibility string
	// PublicRepositoryAccessKnown distinguishes an older GitHub Enterprise
	// response that omitted the setting from a group that explicitly disables
	// it. Treating both as false would raise a warning nobody could act on.
	PublicRepositoryAccessKnown bool
	AllowsPublicRepositories    bool
	RestrictedToWorkflows       bool
}

// RunnerGroupCreate is the policy for a new organisation runner group.
type RunnerGroupCreate struct {
	Name                     string
	Visibility               string
	AllowsPublicRepositories bool
}

// AppInfo describes the authenticated GitHub App.
type AppInfo struct {
	ID    int64
	Slug  string
	Name  string
	Owner string
	// Permissions is what the App was granted, so setup can tell the operator
	// exactly which permission is missing rather than "403".
	Permissions map[string]string
	Events      []string
	// RepositorySelection is GitHub's own word for how much of the target this
	// installation covers: "all" or "selected". It is the difference between a
	// pool that will see every repository somebody pushes to and one that
	// silently sees none of them -- the second commonest setup mistake after a
	// missing permission, and the one nothing in Zoomies could previously say
	// anything about.
	RepositorySelection string
}

// RateLimit reports the installation's remaining API quota, which the UI shows
// on the Installations page.
type RateLimit struct {
	Limit     int
	Remaining int
	ResetAt   time.Time
}

// Client is the GitHub surface Zoomies uses, scoped to one installation.
//
// It is an interface so that tests can run the whole controller against a fake
// GitHub without a network, and so that GHES differences stay behind one seam.
type Client interface {
	// Target returns the org or repo this client acts on.
	Target() (name string, kind store.TargetType)
	// Probe verifies the credentials and permissions, returning an error whose
	// message names the missing permission where GitHub tells us.
	Probe(ctx context.Context) (*AppInfo, error)
	// CreateJITConfig mints an ephemeral runner registration.
	CreateJITConfig(ctx context.Context, req JITRequest) (*JITConfig, error)
	// CreateRegistrationToken mints a one-hour token for config.sh.
	CreateRegistrationToken(ctx context.Context) (*RegistrationToken, error)
	// CreateRemoveToken mints a token for deregistering a runner from the host.
	CreateRemoveToken(ctx context.Context) (*RegistrationToken, error)
	// ListRunners returns every self-hosted runner registered on the target.
	ListRunners(ctx context.Context) ([]Runner, error)
	// DeleteRunner removes a registration. Deleting one that is already gone
	// returns nil, because the desired end state has been reached.
	DeleteRunner(ctx context.Context, id int64) error
	// ListRunnerGroups returns the target's runner groups.
	ListRunnerGroups(ctx context.Context) ([]RunnerGroup, error)
	// CreateRunnerGroup creates an organisation runner group. Repository
	// targets reject it because GitHub only supports groups at organisation
	// scope.
	CreateRunnerGroup(ctx context.Context, req RunnerGroupCreate) (*RunnerGroup, error)
	// ListQueuedJobs is the webhook fallback: it walks recent workflow runs and
	// returns the jobs still waiting for a runner and the ones running on one.
	// Status tells the two apart.
	ListQueuedJobs(ctx context.Context) ([]QueuedJob, error)
	// GetWorkflowJob reconciles a known job even after its run has completed.
	GetWorkflowJob(ctx context.Context, repo string, id int64) (*WorkflowJobEvent, error)
	// GetWorkflowRun reads the run-level status used to distinguish one
	// cancelled job from cancellation of the entire workflow run.
	GetWorkflowRun(ctx context.Context, repo string, runID int64) (*WorkflowRunState, error)
	// CancelWorkflowRun asks GitHub to cancel the entire run containing a job.
	// Force bypasses conditions that may otherwise keep a run cancelling.
	CancelWorkflowRun(ctx context.Context, repo string, runID int64, force bool) error
	// RerunWorkflowJob asks GitHub to run one job again, together with any
	// job that declares it in `needs`. It is the narrower of the two and the
	// one to reach for: a job re-run on its own account should not drag the
	// rest of the run's failures with it.
	RerunWorkflowJob(ctx context.Context, repo string, jobID int64) error
	// RerunFailedWorkflowJobs asks GitHub to run a run's failed jobs again.
	// Like cancellation it is run-level: GitHub reruns the failed jobs of a
	// run together, so a caller must be clear about what else goes with it.
	// It is the fallback for a job whose GitHub job ID this fleet never saw.
	RerunFailedWorkflowJobs(ctx context.Context, repo string, runID int64) error
	// RateLimit reports remaining quota.
	RateLimit(ctx context.Context) (*RateLimit, error)
	// WebURL returns the browser URL for the target.
	WebURL() string

	// The migration surface. These are the only calls Zoomies makes that
	// write anything to a repository, and they are used by one feature: the
	// wizard that moves a repository's workflows onto this fleet. They need
	// permissions the rest of Zoomies does not have and does not ask for, so
	// every one of them can fail with ErrForbidden on a perfectly healthy
	// installation; callers must say so rather than reporting a broken App.

	// ListRepositories returns the repositories this installation can see.
	ListRepositories(ctx context.Context, limit int) ([]Repository, error)
	// ListWorkflows returns the workflow files at the top of a repository's
	// .github/workflows, with their contents.
	ListWorkflows(ctx context.Context, repo string) ([]WorkflowFile, error)
	// ReadReadme returns the README GitHub renders on the repository's front
	// page, or ErrNoReadme when there is none. It is where the badge goes.
	ReadReadme(ctx context.Context, repo string) (*Readme, error)
	// OpenPullRequest commits a set of files to a new branch and opens a pull
	// request for it.
	OpenPullRequest(ctx context.Context, req PullRequestRequest) (*PullRequest, error)
}

// Repository is one repository an installation can see.
type Repository struct {
	ID            int64  `json:"id"`
	FullName      string `json:"full_name"`
	DefaultBranch string `json:"default_branch"`
	Private       bool   `json:"private"`
	Archived      bool   `json:"archived"`
	HTMLURL       string `json:"html_url"`
	// Visibility is "public", "private" or "internal". GitHub sends it with every
	// repository; an older GitHub Enterprise Server that does not is read from
	// Private instead, so it is never empty.
	Visibility string `json:"visibility"`
}

// WorkflowFile is one file under .github/workflows as it exists on the
// repository's default branch.
type WorkflowFile struct {
	// Path is repository-relative.
	Path string
	// SHA is the blob SHA. GitHub requires it to update the file, and it is
	// what makes an update fail rather than clobber somebody's change.
	SHA string
	// Content is the decoded file.
	Content string
}

// FileChange is one file a pull request writes.
type FileChange struct {
	Path    string
	Content string
	// SHA is the blob SHA the change was computed against.
	SHA string
}

// PullRequestRequest describes the pull request to open.
type PullRequestRequest struct {
	// Repo is "owner/name".
	Repo string
	// Base is the branch to open against. Empty means the default branch.
	Base string
	// Head is the branch to create. It must not already exist.
	Head          string
	Title         string
	Body          string
	CommitMessage string
	Files         []FileChange
}

// PullRequest is what opening one produced.
type PullRequest struct {
	Number  int    `json:"number"`
	HTMLURL string `json:"html_url"`
	Branch  string `json:"branch"`
}

// Factory builds a Client for an installation. The controller holds one
// factory and caches clients per installation.
type Factory interface {
	For(ctx context.Context, inst *store.Installation, privateKeyPEM []byte) (Client, error)
}

// RunnerName mints the name one runner of this pool registers under:
// "zoomies-4vcpu-ubuntu-2404-biscuit-a3f9qz2m".
//
// This is the one name Zoomies puts in somebody else's account, so GitHub's
// constraints on it are worth stating where the registration is made. The name
// must be unique within the target -- two runners answering to one name is one
// registration being taken over, not two runners -- which is what the random
// token at the end is for, and why nothing may truncate it away. GitHub also
// shows it in three places a reader arrives at knowing nothing: the runner list,
// the job header, and the "Set up job" step of every log. That is what the shape
// in the middle answers, and store.NewRunnerName explains why it is worth the
// characters.
//
// The 64-character limit GitHub enforces is internal/naming's MaxNameLength, so
// a name is trimmed to fit here rather than refused by the API at registration.
func RunnerName(pool *store.Pool) string { return store.NewRunnerName(pool) }

// RunnerNameOn names a runner that is going to a known host, so the name GitHub
// shows says which machine a job ran on.
func RunnerNameOn(pool *store.Pool, host *store.Host) string {
	return store.NewRunnerNameOn(pool, host)
}

// SplitTarget parses "owner" or "owner/repo" into its parts.
func SplitTarget(target string) (owner, repo string, kind store.TargetType) {
	if o, r, ok := strings.Cut(target, "/"); ok && r != "" {
		return o, r, store.TargetRepo
	}
	return target, "", store.TargetOrg
}

// NormalizeAPIBaseURL turns the forms operators actually type into the form
// go-github expects: an absolute URL ending in a slash, with /api/v3 appended
// for a bare GHES hostname.
func NormalizeAPIBaseURL(raw string) (string, error) {
	// The rule lives in config so that zoomies.yaml is normalised by the same
	// code as an installation row: the docs promise a bare GHES hostname works
	// in both places, and two copies of the rule had already let the config
	// side refuse what this side accepted.
	return config.NormalizeGitHubAPIBaseURL(raw)
}

// IsEnterprise reports whether an API base URL points at GitHub Enterprise
// Server rather than github.com.
func IsEnterprise(apiBaseURL string) bool {
	return apiBaseURL != "" && !strings.Contains(apiBaseURL, "api.github.com")
}

// WebURLForAPI derives the browser-facing base URL from an API base URL, which
// is what the UI links to.
//
// It is also the URL a runner registers against, so a GHE.com tenant has to
// lose its api. prefix here: config.sh pointed at api.<tenant>.ghe.com/<org>
// fails to register, and the App-creation page there does not exist.
func WebURLForAPI(apiBaseURL string) string {
	if !IsEnterprise(apiBaseURL) {
		return "https://github.com"
	}
	s := strings.TrimSuffix(strings.TrimRight(apiBaseURL, "/"), "/api/v3")
	if config.IsGHECom(s) {
		s = strings.Replace(s, "://api.", "://", 1)
	}
	return s
}

// errorf wraps a GitHub failure with the operation that produced it.
func errorf(op string, err error) error {
	if err == nil {
		return nil
	}
	return fmt.Errorf("github: %s: %w", op, err)
}

package github

import (
	"context"
	"errors"
	"net/http"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// The reset GitHub sends is the difference between waiting exactly as long as
// the quota needs and guessing a flat fifteen minutes -- which is either most
// of a window wasted or most of a window spent on refusals. It used to be
// formatted into the message and lost, so this checks it survives as a number.
func TestARateLimitCarriesWhenToComeBack(t *testing.T) {
	now := time.Date(2025, 3, 4, 12, 0, 0, 0, time.UTC)
	reset := now.Add(9 * time.Minute)

	err := error(&RateLimitedError{ResetAt: reset})
	if !errors.Is(err, ErrRateLimited) {
		t.Fatal("callers that only ask whether it was a rate limit must still get yes")
	}
	at, ok := RetryAfterRateLimit(err, now)
	if !ok || !at.Equal(reset) {
		t.Fatalf("RetryAfterRateLimit = %v, %v; want %v, true", at, ok, reset)
	}
	if !strings.Contains(err.Error(), reset.Format(time.RFC3339)) {
		t.Fatalf("the message still has to name the time for an operator: %q", err)
	}
}

// GitHub's secondary limit answers with a duration rather than an instant.
func TestASecondaryRateLimitCarriesItsRetryAfter(t *testing.T) {
	now := time.Date(2025, 3, 4, 12, 0, 0, 0, time.UTC)
	err := error(&RateLimitedError{RetryAfter: 90 * time.Second})

	at, ok := RetryAfterRateLimit(err, now)
	if !ok || !at.Equal(now.Add(90*time.Second)) {
		t.Fatalf("RetryAfterRateLimit = %v, %v", at, ok)
	}
}

// A reset already behind us is no answer at all: clocks drift and a response
// can sit in a queue, and resuming on it would buy another refusal. The caller
// is told nothing rather than told to go now.
func TestARateLimitResetInThePastIsNotAnAnswer(t *testing.T) {
	now := time.Date(2025, 3, 4, 12, 0, 0, 0, time.UTC)
	err := error(&RateLimitedError{ResetAt: now.Add(-time.Minute)})

	if at, ok := RetryAfterRateLimit(err, now); ok {
		t.Fatalf("a reset in the past was offered as a resume time: %v", at)
	}
}

// Anything that is not a rate limit must not be mistaken for one.
func TestOtherFailuresCarryNoResumeTime(t *testing.T) {
	now := time.Date(2025, 3, 4, 12, 0, 0, 0, time.UTC)
	for _, err := range []error{ErrForbidden, ErrNotFound, errors.New("boom"), nil} {
		if _, ok := RetryAfterRateLimit(err, now); ok {
			t.Fatalf("%v was read as a rate limit", err)
		}
	}
}

// The end of the same story, through a real client against a real response:
// what GitHub sends has to arrive as a number a caller can wait on. The tests
// above build the error by hand and would go on passing if classify stopped
// producing it.
func TestAGitHubRefusalForQuotaArrivesWithItsResetTime(t *testing.T) {
	f := newFake(t)
	reset := time.Now().Add(11 * time.Minute).Truncate(time.Second)
	f.SetRateLimit(5000, 0, reset)
	f.SetError("/actions/runners", http.StatusForbidden, "API rate limit exceeded")

	_, err := f.Client("acme", store.TargetOrg).ListRunners(context.Background())
	if !errors.Is(err, ErrRateLimited) {
		t.Fatalf("got %v, want a rate limit", err)
	}
	at, ok := RetryAfterRateLimit(err, time.Now())
	if !ok {
		t.Fatalf("the refusal carried no time to come back at: %v", err)
	}
	if !at.Equal(reset.UTC()) {
		t.Fatalf("resume at %v, want the reset GitHub sent, %v", at, reset.UTC())
	}
}

package github

import (
	"context"
	"encoding/base64"
	"errors"
	"fmt"
	"net/http"
	"net/url"
	"strconv"
	"strings"
	"unicode/utf8"

	"github.com/eyupio/zoomies/internal/prrepair"
	gh "github.com/google/go-github/v88/github"
)

// ErrRepairUnsupported identifies a run that cannot be admitted as a PR repair.
var ErrRepairUnsupported = errors.New("unsupported PR repair target")

// RepairTargetChanged describes an authoritative change since a failed run.
// Transport and permission errors never use this type: neither proves a fix.
type RepairTargetChanged struct {
	Code    string
	Message string
}

func (e *RepairTargetChanged) Error() string { return e.Message }
func (e *RepairTargetChanged) Unwrap() error { return ErrRepairUnsupported }

type RepairActor struct {
	ID       int64
	Login    string
	CanWrite bool
}
type RepairPull struct {
	Number   int
	AuthorID int64
	Author   string
	Branch   string
	// Base is the branch the pull request merges into, which is not always the
	// repository's default branch: it can target a release branch.
	Base          string
	HeadSHA       string
	Title         string
	Body          string
	URL           string
	DefaultBranch string
	Fork          bool
	Open          bool
}
type RepairClient interface {
	RepairActor(context.Context, string, string) (RepairActor, error)
	RepairPull(context.Context, string, int) (RepairPull, error)
	RepairPullForRun(context.Context, string, int64) (RepairPull, error)
	RepairSource(context.Context, string, RepairPull, bool) (*RepairSource, error)
	RepairFailures(context.Context, string, RepairPull, int64) ([]string, error)
	CommitRepair(context.Context, string, RepairPull, prrepair.Plan) (string, error)
	RepairComment(context.Context, string, int, int64, string) (int64, error)
	RepairReact(context.Context, string, int64, string) error
	RepairChecks(context.Context, string, string) (string, error)
}
type RepairSource struct {
	Snapshot prrepair.Snapshot
	files    map[string]repairTreeEntry
	client   *appClient
	repo     string
	commit   string
}
type repairTreeEntry struct {
	Path string `json:"path"`
	Mode string `json:"mode"`
	Type string `json:"type"`
	SHA  string `json:"sha"`
}

func (c *appClient) repairRequest(ctx context.Context, method, p string, body, out any) error {
	req, err := c.asInstallation.NewRequest(ctx, method, p, body)
	if err != nil {
		return err
	}
	resp, err := c.asInstallation.Do(req, out)
	if err != nil {
		return c.fail("Eli GitHub operation", resp, err)
	}
	return nil
}
func repairRepo(repo string) (string, error) {
	owner, name, err := splitRepo(repo)
	if err != nil {
		return "", err
	}
	return "repos/" + url.PathEscape(owner) + "/" + url.PathEscape(name), nil
}
func (c *appClient) RepairActor(ctx context.Context, repo, login string) (RepairActor, error) {
	base, err := repairRepo(repo)
	if err != nil {
		return RepairActor{}, err
	}
	var v struct {
		Permission string `json:"permission"`
		User       struct {
			ID    int64  `json:"id"`
			Login string `json:"login"`
		} `json:"user"`
	}
	err = c.repairRequest(ctx, http.MethodGet, base+"/collaborators/"+url.PathEscape(login)+"/permission", nil, &v)
	return RepairActor{ID: v.User.ID, Login: v.User.Login, CanWrite: v.Permission == "write" || v.Permission == "maintain" || v.Permission == "admin"}, err
}
func (c *appClient) RepairPull(ctx context.Context, repo string, number int) (RepairPull, error) {
	base, err := repairRepo(repo)
	if err != nil {
		return RepairPull{}, err
	}
	var p struct {
		Number  int    `json:"number"`
		State   string `json:"state"`
		Title   string `json:"title"`
		Body    string `json:"body"`
		HTMLURL string `json:"html_url"`
		User    struct {
			ID    int64  `json:"id"`
			Login string `json:"login"`
		} `json:"user"`
		Head struct {
			Ref  string `json:"ref"`
			SHA  string `json:"sha"`
			Repo struct {
				FullName      string `json:"full_name"`
				DefaultBranch string `json:"default_branch"`
			} `json:"repo"`
		} `json:"head"`
		Base struct {
			Ref string `json:"ref"`
		} `json:"base"`
	}
	if err := c.repairRequest(ctx, http.MethodGet, base+"/pulls/"+strconv.Itoa(number), nil, &p); err != nil {
		return RepairPull{}, err
	}
	out := RepairPull{Number: p.Number, AuthorID: p.User.ID, Author: p.User.Login, Branch: p.Head.Ref, Base: p.Base.Ref, HeadSHA: p.Head.SHA, Title: p.Title, Body: p.Body, URL: p.HTMLURL, DefaultBranch: p.Head.Repo.DefaultBranch, Fork: p.Head.Repo.FullName != repo, Open: p.State == "open"}
	if out.Number > 0 && p.State == "closed" {
		return out, &RepairTargetChanged{Code: "closed", Message: fmt.Sprintf("PR #%d is closed or merged. This failure no longer needs a PR repair. You can still inspect the original run on GitHub.", out.Number)}
	}
	if out.Number <= 0 || !out.Open || out.Fork || out.HeadSHA == "" || out.Branch == "" || out.Branch == out.DefaultBranch {
		return out, fmt.Errorf("%w: an Eli repair needs an open PR on a non-default branch in this repository; forks are not writable", ErrRepairUnsupported)
	}
	return out, nil
}
func (c *appClient) RepairPullForRun(ctx context.Context, repo string, run int64) (RepairPull, error) {
	base, err := repairRepo(repo)
	if err != nil {
		return RepairPull{}, err
	}
	var r struct {
		HeadSHA        string `json:"head_sha"`
		Event          string `json:"event"`
		HeadRepository struct {
			FullName string `json:"full_name"`
		} `json:"head_repository"`
		Pulls []struct {
			Number int `json:"number"`
		} `json:"pull_requests"`
	}
	if err := c.repairRequest(ctx, http.MethodGet, fmt.Sprintf("%s/actions/runs/%d", base, run), nil, &r); err != nil {
		return RepairPull{}, err
	}
	if r.HeadRepository.FullName != repo {
		return RepairPull{}, fmt.Errorf("%w: fork workflow runs are not writable", ErrRepairUnsupported)
	}
	// GitHub can omit the run's PR links, including after a PR is merged.
	// Resolve by commit, never by a branch name that may have been reused, and
	// only for a run a PR started: the commit of a push, schedule or manual run
	// on the default branch resolves to the PR whose merge made it, and that
	// PR being closed would settle a failure that never belonged to it.
	if len(r.Pulls) == 0 && r.HeadSHA != "" {
		if r.Event != "pull_request" && r.Event != "pull_request_target" {
			return RepairPull{}, fmt.Errorf("%w: the failed run was not started by a PR (its event is %q), so there is no PR to repair", ErrRepairUnsupported, r.Event)
		}
		if err := c.repairRequest(ctx, http.MethodGet, base+"/commits/"+url.PathEscape(r.HeadSHA)+"/pulls?per_page=2", nil, &r.Pulls); err != nil {
			return RepairPull{}, err
		}
	}
	if len(r.Pulls) != 1 {
		return RepairPull{}, fmt.Errorf("%w: the failed run does not identify a single PR. Choose an open PR or paste its GitHub URL", ErrRepairUnsupported)
	}
	p, err := c.RepairPull(ctx, repo, r.Pulls[0].Number)
	if err != nil {
		return p, err
	}
	if p.HeadSHA != r.HeadSHA {
		return p, &RepairTargetChanged{Code: "superseded", Message: fmt.Sprintf("PR #%d has newer commits than this failed run. This failure is out of date. Check the current PR to see whether its latest checks need a repair.", p.Number)}
	}
	return p, nil
}
func (c *appClient) RepairSource(ctx context.Context, repo string, p RepairPull, workflows bool) (*RepairSource, error) {
	base, err := repairRepo(repo)
	if err != nil {
		return nil, err
	}
	var commit struct {
		Tree struct {
			SHA string `json:"sha"`
		} `json:"tree"`
	}
	if err := c.repairRequest(ctx, http.MethodGet, base+"/git/commits/"+p.HeadSHA, nil, &commit); err != nil {
		return nil, err
	}
	var tree struct {
		Truncated bool              `json:"truncated"`
		Tree      []repairTreeEntry `json:"tree"`
	}
	if err := c.repairRequest(ctx, http.MethodGet, base+"/git/trees/"+commit.Tree.SHA+"?recursive=1", nil, &tree); err != nil {
		return nil, err
	}
	if tree.Truncated || len(tree.Tree) > 10000 {
		return nil, fmt.Errorf("repository inventory exceeds Eli's repair limit")
	}
	source := &RepairSource{client: c, repo: repo, commit: p.HeadSHA, files: map[string]repairTreeEntry{}, Snapshot: prrepair.Snapshot{Title: p.Title, Body: prrepair.Redact(p.Body[:min(len(p.Body), 8000)]), Branch: p.Branch, HeadSHA: p.HeadSHA}}
	for _, f := range tree.Tree {
		source.files[f.Path] = f
		if f.Type == "blob" && (f.Mode == "100644" || f.Mode == "100755") && prrepair.AllowedPath(f.Path, workflows) {
			source.Snapshot.Inventory = append(source.Snapshot.Inventory, f.Path)
		}
	}
	var changed []struct {
		Filename string `json:"filename"`
		Status   string `json:"status"`
		Patch    string `json:"patch"`
	}
	if err := c.repairRequest(ctx, http.MethodGet, fmt.Sprintf("%s/pulls/%d/files?per_page=100", base, p.Number), nil, &changed); err != nil {
		return nil, err
	}
	if len(changed) >= 100 {
		return nil, fmt.Errorf("the PR exceeds Eli's changed-file limit")
	}
	total := 0
	for _, f := range changed {
		if len(source.Snapshot.Diff) < 32<<10 {
			patch := f.Filename + "\n" + f.Patch + "\n"
			source.Snapshot.Diff += prrepair.Redact(patch[:min(len(patch), (32<<10)-len(source.Snapshot.Diff))])
		}
		if f.Status == "removed" || !prrepair.AllowedPath(f.Filename, workflows) {
			continue
		}
		file, err := source.ReadFile(ctx, f.Filename)
		// A file Eli may not have (too large, or not text) is left out and
		// named, not the end of the repair: a PR that regenerates a reference
		// of a few thousand lines is still a PR whose other files can be
		// fixed. GitHub refusing a read is a failure, because the next read
		// will be refused too.
		var unusable *prrepair.ReadError
		if errors.As(err, &unusable) && unusable.Err == nil {
			source.Snapshot.Skipped = append(source.Snapshot.Skipped, fmt.Sprintf("%s: larger than %d KiB or not plain text", f.Filename, prrepair.MaxBlobBytes/1024))
			continue
		}
		if err != nil {
			return nil, err
		}
		if total+len(file.Content) > 4<<20 {
			source.Snapshot.Skipped = append(source.Snapshot.Skipped, fmt.Sprintf("%s: left out, the PR's source is over the %d KiB budget", f.Filename, 4096))
			continue
		}
		total += len(file.Content)
		source.Snapshot.Files = append(source.Snapshot.Files, file)
	}
	return source, nil
}
func (s *RepairSource) ReadFile(ctx context.Context, name string) (prrepair.File, error) {
	// Git blobs never resolve symlinks; every parent must still be a tree.
	parts := strings.Split(name, "/")
	for i := 1; i < len(parts); i++ {
		if e, ok := s.files[strings.Join(parts[:i], "/")]; ok && e.Type != "tree" {
			return prrepair.File{}, fmt.Errorf("source path crosses a non-directory")
		}
	}
	e, ok := s.files[name]
	if !ok {
		return prrepair.File{Path: name, Mode: "100644"}, nil
	}
	if e.Type != "blob" || e.Mode != "100644" && e.Mode != "100755" {
		return prrepair.File{}, fmt.Errorf("source path is not a regular file")
	}
	base, _ := repairRepo(s.repo)
	var blob struct {
		Content  string `json:"content"`
		Encoding string `json:"encoding"`
		Size     int    `json:"size"`
	}
	if err := s.client.repairRequest(ctx, http.MethodGet, base+"/git/blobs/"+e.SHA, nil, &blob); err != nil {
		return prrepair.File{}, err
	}
	if blob.Size > prrepair.MaxBlobBytes {
		return prrepair.File{}, &prrepair.ReadError{Path: name, Reason: "file_size", Bytes: blob.Size}
	}
	if blob.Encoding != "base64" {
		return prrepair.File{}, &prrepair.ReadError{Path: name, Reason: "unsupported_encoding"}
	}
	raw, err := base64.StdEncoding.DecodeString(strings.ReplaceAll(blob.Content, "\n", ""))
	if err != nil {
		return prrepair.File{}, fmt.Errorf("source file could not be decoded")
	}
	if len(raw) > prrepair.MaxBlobBytes {
		return prrepair.File{}, &prrepair.ReadError{Path: name, Reason: "file_size", Bytes: len(raw)}
	}
	if !utf8.ValidString(string(raw)) || strings.ContainsRune(string(raw), 0) {
		return prrepair.File{}, &prrepair.ReadError{Path: name, Reason: "unsupported_text"}
	}
	return prrepair.File{Path: name, Content: string(raw), Mode: e.Mode}, nil
}
func (c *appClient) RepairFailures(ctx context.Context, repo string, p RepairPull, jobID int64) ([]string, error) {
	if jobID > 0 {
		return c.ContextJobErrors(ctx, repo, jobID)
	}
	base, err := repairRepo(repo)
	if err != nil {
		return nil, err
	}
	var runs struct {
		Runs []struct {
			ID      int64  `json:"id"`
			HeadSHA string `json:"head_sha"`
			Status  string `json:"status"`
		} `json:"workflow_runs"`
	}
	if err := c.repairRequest(ctx, http.MethodGet, base+"/actions/runs?head_sha="+p.HeadSHA+"&per_page=10", nil, &runs); err != nil {
		return nil, err
	}
	out := []string{}
	for _, r := range runs.Runs {
		if r.HeadSHA != p.HeadSHA {
			continue
		}
		var jobs struct {
			Jobs []struct {
				ID         int64  `json:"id"`
				Name       string `json:"name"`
				Conclusion string `json:"conclusion"`
			} `json:"jobs"`
		}
		if err := c.repairRequest(ctx, http.MethodGet, fmt.Sprintf("%s/actions/runs/%d/jobs?per_page=100", base, r.ID), nil, &jobs); err != nil {
			return nil, err
		}
		for _, j := range jobs.Jobs {
			if j.Conclusion != "failure" && j.Conclusion != "timed_out" {
				continue
			}
			lines, err := c.ContextJobErrors(ctx, repo, j.ID)
			if err != nil {
				return nil, err
			}
			out = append(out, prrepair.Redact(j.Name+": "+strings.Join(lines, "\n")))
			if len(out) >= 5 {
				return out, nil
			}
		}
	}
	return out, nil
}
func (c *appClient) CommitRepair(ctx context.Context, repo string, p RepairPull, plan prrepair.Plan) (string, error) {
	fresh, err := c.RepairPull(ctx, repo, p.Number)
	if err != nil {
		return "", err
	}
	if fresh.HeadSHA != p.HeadSHA || fresh.Branch != p.Branch {
		return "", ErrSetupConflict
	}
	owner, name, _ := splitRepo(repo)
	parent, resp, err := c.asInstallation.Git.GetCommit(ctx, owner, name, p.HeadSHA)
	if err != nil {
		return "", c.fail("read repair parent", resp, err)
	}
	entries := []*gh.TreeEntry{}
	for _, f := range plan.Files {
		mode := f.Mode
		if mode == "" {
			mode = "100644"
		}
		entries = append(entries, &gh.TreeEntry{Path: gh.Ptr(f.Path), Mode: gh.Ptr(mode), Type: gh.Ptr("blob"), Content: gh.Ptr(f.Content)})
	}
	tree, resp, err := c.asInstallation.Git.CreateTree(ctx, owner, name, parent.GetTree().GetSHA(), entries)
	if err != nil {
		return "", c.fail("write repair tree", resp, err)
	}
	commit, resp, err := c.asInstallation.Git.CreateCommit(ctx, owner, name, gh.Commit{Message: gh.Ptr("Fix PR checks with Eli"), Tree: tree, Parents: []*gh.Commit{{SHA: gh.Ptr(p.HeadSHA)}}}, nil)
	if err != nil {
		return "", c.fail("write repair commit", resp, err)
	}
	// A concurrent push makes this divergent, so GitHub refuses it. Force is always false.
	_, resp, err = c.asInstallation.Git.UpdateRef(ctx, owner, name, "heads/"+p.Branch, gh.UpdateRef{SHA: commit.GetSHA(), Force: gh.Ptr(false)})
	if err != nil {
		return "", c.fail("advance repair branch without forcing", resp, err)
	}
	return commit.GetSHA(), nil
}
func (c *appClient) RepairComment(ctx context.Context, repo string, pull int, id int64, text string) (int64, error) {
	base, err := repairRepo(repo)
	if err != nil {
		return 0, err
	}
	method := http.MethodPost
	endpoint := fmt.Sprintf("%s/issues/%d/comments", base, pull)
	if id > 0 {
		method = http.MethodPatch
		endpoint = fmt.Sprintf("%s/issues/comments/%d", base, id)
	}
	var out struct {
		ID int64 `json:"id"`
	}
	err = c.repairRequest(ctx, method, endpoint, map[string]string{"body": text}, &out)
	return out.ID, err
}

// RepairReact puts a reaction on a comment. GitHub offers a fixed set (there is
// no paw), and posting the same one twice is not an error, so a redelivered
// webhook cannot stack them.
func (c *appClient) RepairReact(ctx context.Context, repo string, commentID int64, content string) error {
	base, err := repairRepo(repo)
	if err != nil {
		return err
	}
	return c.repairRequest(ctx, http.MethodPost, fmt.Sprintf("%s/issues/comments/%d/reactions", base, commentID), map[string]string{"content": content}, nil)
}
func (c *appClient) RepairChecks(ctx context.Context, repo, sha string) (string, error) {
	base, err := repairRepo(repo)
	if err != nil {
		return "", err
	}
	var checks struct {
		Total int `json:"total_count"`
		Runs  []struct {
			Status     string `json:"status"`
			Conclusion string `json:"conclusion"`
		} `json:"check_runs"`
	}
	if err := c.repairRequest(ctx, http.MethodGet, base+"/commits/"+sha+"/check-runs?per_page=100", nil, &checks); err != nil {
		return "", err
	}
	var statuses struct {
		Total int    `json:"total_count"`
		State string `json:"state"`
	}
	if err := c.repairRequest(ctx, http.MethodGet, base+"/commits/"+url.PathEscape(sha)+"/status", nil, &statuses); err != nil {
		return "", err
	}
	if statuses.Total > 0 && (statuses.State == "failure" || statuses.State == "error") {
		return "failed", nil
	}
	pending := checks.Total > len(checks.Runs) || statuses.Total > 0 && statuses.State != "success"
	passed := statuses.Total > 0 && statuses.State == "success"
	for _, r := range checks.Runs {
		if r.Status != "completed" {
			pending = true
			continue
		}
		switch r.Conclusion {
		case "failure", "timed_out", "action_required", "startup_failure":
			return "failed", nil
		case "success":
			passed = true
		case "neutral", "skipped":
		default:
			// A cancellation or missing outcome is not evidence of a fix.
			pending = true
		}
	}
	if pending || !passed {
		return "waiting", nil
	}
	return "passed", nil
}

var _ RepairClient = (*appClient)(nil)

