package github

import (
	"bytes"
	"container/list"
	"io"
	"net/http"
	"strings"
	"sync"
)

// The conditional-request transport makes a repeated read cost nothing against
// GitHub's primary rate limit: a GET that carries If-None-Match and comes back
// 304 is not counted. Kennel Club re-reads the same repositories every day and
// almost nothing changes between reads, so without this its daily sweep would
// spend the quota the poller and the JIT configurations live on.
//
// It is layered under Kennel Club's reads only. The poller and the runner calls
// keep the transport they have, because a transport that quietly answered from
// memory is the wrong default for code whose whole job is to see the queue as it
// is now. A 304 means "unchanged", so what a caller gets is what it would have
// got, and the only observable difference is the request count.

const (
	// conditionalCacheBytes bounds everything the cache holds, across every
	// installation. A restart empties it, which costs one full-price read per
	// repository that is then due, spread by the schedule's jitter.
	conditionalCacheBytes = 20 << 20
	// conditionalEntryBytes is the largest single response worth remembering.
	// Bigger ones are delivered intact and not kept: a listing that large changes
	// too often to repay holding it.
	conditionalEntryBytes = 512 << 10
)

// conditionalCache is a size-bounded, least-recently-used store of responses by
// request. It is shared by every installation's transport, which is safe because
// the scope an installation's transport adds to each key is what separates one
// tenant's responses from another's.
type conditionalCache struct {
	mu      sync.Mutex
	max     int64
	used    int64
	order   *list.List // front is the most recently used
	entries map[string]*list.Element
}

type conditionalEntry struct {
	key    string
	etag   string
	status int
	header http.Header
	body   []byte
}

func (e *conditionalEntry) size() int64 { return int64(len(e.body) + len(e.key) + len(e.etag) + 256) }

func newConditionalCache(max int64) *conditionalCache {
	return &conditionalCache{max: max, order: list.New(), entries: map[string]*list.Element{}}
}

func (c *conditionalCache) get(key string) (*conditionalEntry, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()
	el, ok := c.entries[key]
	if !ok {
		return nil, false
	}
	c.order.MoveToFront(el)
	return el.Value.(*conditionalEntry), true
}

func (c *conditionalCache) put(e *conditionalEntry) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if old, ok := c.entries[e.key]; ok {
		c.used -= old.Value.(*conditionalEntry).size()
		c.order.Remove(old)
		delete(c.entries, e.key)
	}
	if e.size() > c.max {
		return
	}
	c.entries[e.key] = c.order.PushFront(e)
	c.used += e.size()
	for c.used > c.max {
		last := c.order.Back()
		if last == nil {
			break
		}
		old := last.Value.(*conditionalEntry)
		c.used -= old.size()
		c.order.Remove(last)
		delete(c.entries, old.key)
	}
}

func (c *conditionalCache) drop(key string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if el, ok := c.entries[key]; ok {
		c.used -= el.Value.(*conditionalEntry).size()
		c.order.Remove(el)
		delete(c.entries, key)
	}
}

// conditionalTransport revalidates GET responses against what it last saw.
type conditionalTransport struct {
	base  http.RoundTripper
	cache *conditionalCache
	// scope separates one installation's responses from another's. Two
	// installations asking for the same URL are different questions: each is
	// answered for what that installation may see.
	scope string
}

// rateLimitHeaders are what a 304 refreshes on the response the caller gets,
// because the quota left is as true on a not-modified answer as on any other
// and go-github reads it from there.
var rateLimitHeaders = []string{"X-Ratelimit-Limit", "X-Ratelimit-Remaining", "X-Ratelimit-Reset", "X-Ratelimit-Used", "X-Ratelimit-Resource", "Date"}

// RoundTrip implements http.RoundTripper. It never changes the request it is
// given, as the interface requires.
func (t *conditionalTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	if req.Method != http.MethodGet {
		return t.base.RoundTrip(req)
	}
	key := t.scope + "\x00" + req.Header.Get("Accept") + "\x00" + req.URL.String()
	entry, cached := t.cache.get(key)
	out := req
	if cached {
		out = req.Clone(req.Context())
		out.Header.Set("If-None-Match", entry.etag)
	}
	resp, err := t.base.RoundTrip(out)
	if err != nil {
		return nil, err
	}

	if resp.StatusCode == http.StatusNotModified && cached {
		_ = resp.Body.Close()
		return replay(req, entry, resp.Header), nil
	}
	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		// A refusal or a missing resource is not worth keeping, and what was kept
		// for the same request may no longer be true: a permission withdrawn, a
		// repository deleted.
		if cached {
			t.cache.drop(key)
		}
		return resp, nil
	}

	etag := resp.Header.Get("ETag")
	if etag == "" || resp.StatusCode != http.StatusOK {
		return resp, nil
	}
	body, err := io.ReadAll(io.LimitReader(resp.Body, conditionalEntryBytes+1))
	if err != nil {
		_ = resp.Body.Close()
		return nil, err
	}
	if len(body) > conditionalEntryBytes {
		// Too big to keep. Hand the caller everything, the part already read and
		// what is still to come.
		resp.Body = struct {
			io.Reader
			io.Closer
		}{io.MultiReader(bytes.NewReader(body), resp.Body), resp.Body}
		return resp, nil
	}
	_ = resp.Body.Close()
	h := resp.Header.Clone()
	// A cookie is a session, not a property of the resource.
	h.Del("Set-Cookie")
	t.cache.put(&conditionalEntry{key: key, etag: etag, status: resp.StatusCode, header: h, body: body})
	resp.Body = io.NopCloser(bytes.NewReader(body))
	return resp, nil
}

// replay builds the response a caller would have got had the resource been sent
// again: the remembered body and headers, with the quota headers of the 304 that
// has just been answered.
func replay(req *http.Request, e *conditionalEntry, fresh http.Header) *http.Response {
	h := e.header.Clone()
	for _, name := range rateLimitHeaders {
		if v := fresh.Values(name); len(v) > 0 {
			h[name] = append([]string(nil), v...)
		}
	}
	return &http.Response{
		Status:        "200 OK",
		StatusCode:    e.status,
		Proto:         "HTTP/1.1",
		ProtoMajor:    1,
		ProtoMinor:    1,
		Header:        h,
		Body:          io.NopCloser(bytes.NewReader(e.body)),
		ContentLength: int64(len(e.body)),
		Request:       req,
	}
}

// newConditionalClient returns an http.Client like hc whose GETs are revalidated.
func newConditionalClient(hc *http.Client, cache *conditionalCache, scope string) *http.Client {
	base := hc.Transport
	if base == nil {
		base = http.DefaultTransport
	}
	return &http.Client{
		Transport:     &conditionalTransport{base: base, cache: cache, scope: strings.TrimSpace(scope)},
		CheckRedirect: hc.CheckRedirect,
		Jar:           hc.Jar,
		Timeout:       hc.Timeout,
	}
}

package github

import (
	"crypto/sha256"
	"encoding/hex"
	"io"
	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
)

// etagServer answers GET /thing with a body and an ETag derived from it, and
// answers 304 to a matching If-None-Match, as GitHub does. It records what it
// was sent.
type etagServer struct {
	*httptest.Server
	mu       sync.Mutex
	body     string
	status   int
	requests int
	sent     []string // the If-None-Match of each request
	accept   []string
}

func newETagServer(t *testing.T, body string) *etagServer {
	t.Helper()
	s := &etagServer{body: body, status: http.StatusOK}
	s.Server = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		s.mu.Lock()
		defer s.mu.Unlock()
		s.requests++
		inm := r.Header.Get("If-None-Match")
		s.sent = append(s.sent, inm)
		s.accept = append(s.accept, r.Header.Get("Accept"))
		w.Header().Set("X-RateLimit-Remaining", strconv.Itoa(5000-s.requests))
		if s.status != http.StatusOK {
			w.WriteHeader(s.status)
			_, _ = io.WriteString(w, `{"message":"no"}`)
			return
		}
		// A short hash, as GitHub's are: an ETag the length of the body would make
		// every entry twice the size the bound tests reason about.
		sum := sha256.Sum256([]byte(s.body))
		etag := `"` + hex.EncodeToString(sum[:8]) + `"`
		w.Header().Set("ETag", etag)
		w.Header().Set("Set-Cookie", "session=secret")
		if r.Method == http.MethodGet && inm == etag {
			w.WriteHeader(http.StatusNotModified)
			return
		}
		_, _ = io.WriteString(w, s.body)
	}))
	t.Cleanup(s.Close)
	return s
}

func (s *etagServer) set(body string, status int) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.body, s.status = body, status
}

func get(t *testing.T, c *http.Client, url string, hdr ...string) (int, string, http.Header) {
	t.Helper()
	req, _ := http.NewRequest(http.MethodGet, url, nil)
	for i := 0; i+1 < len(hdr); i += 2 {
		req.Header.Set(hdr[i], hdr[i+1])
	}
	resp, err := c.Do(req)
	if err != nil {
		t.Fatalf("GET %s: %v", url, err)
	}
	defer resp.Body.Close()
	b, _ := io.ReadAll(resp.Body)
	return resp.StatusCode, string(b), resp.Header
}

func client(cache *conditionalCache, scope string) *http.Client {
	return newConditionalClient(&http.Client{}, cache, scope)
}

// What the caller sees must not change: the point is the request count. A 304
// that surfaced as a 304 would be an error to every caller that never asked for
// a conditional read.
func TestARepeatedReadIsAnsweredFromMemoryAndLooksIdentical(t *testing.T) {
	srv := newETagServer(t, "hello")
	c := client(newConditionalCache(1<<20), "inst-1")
	code, body, _ := get(t, c, srv.URL+"/thing")
	if code != 200 || body != "hello" {
		t.Fatalf("first read = %d %q", code, body)
	}
	code, body, _ = get(t, c, srv.URL+"/thing")
	if code != 200 || body != "hello" {
		t.Fatalf("second read = %d %q, want the same as the first, not a 304", code, body)
	}
	if srv.sent[0] != "" || srv.sent[1] == "" {
		t.Errorf("If-None-Match sent = %q, want none on the first read and the ETag on the second", srv.sent)
	}
}

func TestAChangedResourceIsReadInFullAndRemembered(t *testing.T) {
	srv := newETagServer(t, "one")
	c := client(newConditionalCache(1<<20), "inst-1")
	get(t, c, srv.URL+"/thing")
	srv.set("two!", http.StatusOK)
	if _, body, _ := get(t, c, srv.URL+"/thing"); body != "two!" {
		t.Fatalf("body = %q, want the new one", body)
	}
	if _, body, _ := get(t, c, srv.URL+"/thing"); body != "two!" {
		t.Fatalf("body = %q after revalidating the new one", body)
	}
	if srv.sent[2] == "" || srv.sent[2] == srv.sent[1] {
		t.Errorf("third read sent %q, want the new ETag", srv.sent[2])
	}
}

// The 304 carries the quota as it is now. go-github reads the rate limit from
// the response, and a replayed header would show a quota that was true a minute
// ago.
func TestAReplayedResponseCarriesTheCurrentQuotaNotTheOldOne(t *testing.T) {
	srv := newETagServer(t, "x")
	c := client(newConditionalCache(1<<20), "inst-1")
	_, _, first := get(t, c, srv.URL+"/thing")
	_, _, second := get(t, c, srv.URL+"/thing")
	if first.Get("X-RateLimit-Remaining") != "4999" || second.Get("X-RateLimit-Remaining") != "4998" {
		t.Errorf("remaining = %q then %q, want 4999 then 4998", first.Get("X-RateLimit-Remaining"), second.Get("X-RateLimit-Remaining"))
	}
}

// Two installations asking for one URL are two questions. A response one was
// allowed to see must never be handed to the other, and the second must pay for
// its own first read.
func TestOneInstallationNeverGetsAnotherOnesResponse(t *testing.T) {
	srv := newETagServer(t, "private to one")
	shared := newConditionalCache(1 << 20)
	a, b := client(shared, "inst-A"), client(shared, "inst-B")
	get(t, a, srv.URL+"/thing")
	get(t, b, srv.URL+"/thing")
	if srv.sent[1] != "" {
		t.Errorf("installation B revalidated with %q: it was sent A's ETag, so it could have been handed A's body", srv.sent[1])
	}
	get(t, b, srv.URL+"/thing")
	if srv.sent[2] == "" {
		t.Error("installation B's own repeat read was not conditional")
	}
}

// GitHub varies a response on its media type, so the same URL asked for two
// ways is two answers.
func TestADifferentMediaTypeIsADifferentQuestion(t *testing.T) {
	srv := newETagServer(t, "x")
	c := client(newConditionalCache(1<<20), "i")
	get(t, c, srv.URL+"/thing", "Accept", "application/vnd.github+json")
	get(t, c, srv.URL+"/thing", "Accept", "application/vnd.github.raw+json")
	if srv.sent[1] != "" {
		t.Errorf("a read with another Accept was conditional on the first's ETag: %q", srv.sent)
	}
}

func TestAQueryStringIsPartOfWhatIsRemembered(t *testing.T) {
	srv := newETagServer(t, "x")
	c := client(newConditionalCache(1<<20), "i")
	get(t, c, srv.URL+"/thing?page=1")
	get(t, c, srv.URL+"/thing?page=2")
	if srv.sent[1] != "" {
		t.Errorf("page 2 was conditional on page 1's ETag: %q", srv.sent)
	}
}

// A refusal is not worth keeping, and what was kept for the same request may
// no longer be true: a permission taken away, a repository deleted.
func TestARefusalIsNotKeptAndForgetsWhatWasKeptBefore(t *testing.T) {
	srv := newETagServer(t, "fine")
	c := client(newConditionalCache(1<<20), "i")
	get(t, c, srv.URL+"/thing")
	srv.set("", http.StatusForbidden)
	if code, _, _ := get(t, c, srv.URL+"/thing"); code != http.StatusForbidden {
		t.Fatalf("code = %d, want the refusal passed through", code)
	}
	srv.set("fine", http.StatusOK)
	get(t, c, srv.URL+"/thing")
	if last := srv.sent[len(srv.sent)-1]; last != "" {
		t.Errorf("after a refusal the next read was still conditional (%q): the old entry should be gone", last)
	}
}

func TestAnErrorResponseIsNeverCached(t *testing.T) {
	srv := newETagServer(t, "x")
	srv.set("", http.StatusNotFound)
	c := client(newConditionalCache(1<<20), "i")
	get(t, c, srv.URL+"/thing")
	get(t, c, srv.URL+"/thing")
	for _, s := range srv.sent {
		if s != "" {
			t.Errorf("a conditional read followed a 404: %q", srv.sent)
		}
	}
}

func TestOnlyAGetIsEverConditional(t *testing.T) {
	var sawIfNoneMatch atomic.Bool
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Header.Get("If-None-Match") != "" {
			sawIfNoneMatch.Store(true)
		}
		w.Header().Set("ETag", `"e"`)
		_, _ = io.WriteString(w, "ok")
	}))
	defer srv.Close()
	c := client(newConditionalCache(1<<20), "i")
	for i := 0; i < 2; i++ {
		resp, err := c.Post(srv.URL+"/thing", "text/plain", strings.NewReader("x"))
		if err != nil {
			t.Fatal(err)
		}
		resp.Body.Close()
	}
	if sawIfNoneMatch.Load() {
		t.Error("a POST was made conditional")
	}
}

// A transport must not change the request it is given: the caller may retry it.
func TestTheCallersRequestIsLeftAlone(t *testing.T) {
	srv := newETagServer(t, "x")
	c := client(newConditionalCache(1<<20), "i")
	get(t, c, srv.URL+"/thing")
	req, _ := http.NewRequest(http.MethodGet, srv.URL+"/thing", nil)
	resp, err := c.Do(req)
	if err != nil {
		t.Fatal(err)
	}
	resp.Body.Close()
	if req.Header.Get("If-None-Match") != "" {
		t.Error("the caller's request was given an If-None-Match")
	}
}

// A session cookie is not a property of the resource, and replaying one to a
// later caller would be a leak.
func TestACookieIsNeverReplayed(t *testing.T) {
	srv := newETagServer(t, "x")
	c := client(newConditionalCache(1<<20), "i")
	get(t, c, srv.URL+"/thing")
	_, _, h := get(t, c, srv.URL+"/thing")
	if h.Get("Set-Cookie") != "" {
		t.Errorf("a replayed response carried Set-Cookie: %q", h.Get("Set-Cookie"))
	}
}

// A response too big to keep is still delivered whole.
func TestAResponseTooBigToKeepIsStillDeliveredIntact(t *testing.T) {
	big := strings.Repeat("a", conditionalEntryBytes+10)
	srv := newETagServer(t, big)
	c := client(newConditionalCache(64<<20), "i")
	for i := 0; i < 2; i++ {
		if _, body, _ := get(t, c, srv.URL+"/thing"); body != big {
			t.Fatalf("read %d delivered %d bytes, want %d", i, len(body), len(big))
		}
	}
	if srv.sent[1] != "" {
		t.Error("an oversize response was kept")
	}
}

// Memory is bounded across every installation, least recently used first.
func TestTheCacheNeverHoldsMoreThanItsBoundAndForgetsTheLeastRecentlyUsed(t *testing.T) {
	srv := newETagServer(t, strings.Repeat("a", 2000))
	cache := newConditionalCache(6000) // room for two entries, not three
	c := client(cache, "i")
	get(t, c, srv.URL+"/a")
	get(t, c, srv.URL+"/b")
	get(t, c, srv.URL+"/a") // a is now the more recently used
	get(t, c, srv.URL+"/c") // evicts b
	if cache.used > cache.max {
		t.Fatalf("used %d over the bound %d", cache.used, cache.max)
	}
	before := len(srv.sent)
	get(t, c, srv.URL+"/a")
	get(t, c, srv.URL+"/b")
	if srv.sent[before] == "" {
		t.Error("a, recently used, was forgotten")
	}
	if srv.sent[before+1] != "" {
		t.Error("b, least recently used, was kept")
	}
}

func TestAResponseWithNoETagIsNotKept(t *testing.T) {
	var n atomic.Int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		n.Add(1)
		// Presence, not value: an empty If-None-Match is still a conditional read of
		// something that never offered a version to compare with.
		if _, present := r.Header["If-None-Match"]; present {
			t.Error("a conditional read of a resource that sent no ETag")
		}
		_, _ = io.WriteString(w, "x")
	}))
	defer srv.Close()
	c := client(newConditionalCache(1<<20), "i")
	get(t, c, srv.URL+"/thing")
	get(t, c, srv.URL+"/thing")
	if n.Load() != 2 {
		t.Errorf("requests = %d", n.Load())
	}
}

func TestTheCacheIsSafeUnderConcurrentUse(t *testing.T) {
	srv := newETagServer(t, "x")
	c := client(newConditionalCache(1<<20), "i")
	var wg sync.WaitGroup
	for i := 0; i < 20; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			get(t, c, srv.URL+"/thing?n="+strconv.Itoa(i%4))
		}(i)
	}
	wg.Wait()
}

package github

import (
	"context"
	"errors"
	"fmt"
	"time"
	"unicode"
	"unicode/utf8"

	gh "github.com/google/go-github/v88/github"
)

// ExperimentAttemptReader is optional and on demand. Controller admission and
// the caller's repository permission must be checked before spending its reads.
type ExperimentAttemptReader interface {
	ReadExperimentAttempt(context.Context, string, int64, int) (*ExperimentAttemptEvidence, error)
}

var _ ExperimentAttemptReader = (*appClient)(nil)

const ExperimentAttemptMaximumRequests = 8

var ErrExperimentAttemptChanged = errors.New("github: comparison attempt changed during collection; refresh its evidence")

type ExperimentAttemptEvidence struct {
	WorkflowSource *ExperimentWorkflowSource `json:"workflow_source,omitempty"`
	// These are descriptive attempt metadata, not workflow contents or inputs.
	Event        string                 `json:"event,omitempty"`
	WorkflowPath string                 `json:"workflow_path,omitempty"`
	Repository   string                 `json:"repository"`
	RunID        int64                  `json:"run_id"`
	Attempt      int                    `json:"attempt"`
	HeadSHA      string                 `json:"head_sha"`
	WorkflowID   int64                  `json:"workflow_id"`
	Status       string                 `json:"status"`
	Conclusion   string                 `json:"conclusion"`
	RunStartedAt *time.Time             `json:"run_started_at"`
	UpdatedAt    *time.Time             `json:"updated_at"`
	JobsCoverage string                 `json:"jobs_coverage"`
	Jobs         []ExperimentAttemptJob `json:"jobs"`
}

type ExperimentAttemptJob struct {
	ID          int64      `json:"id"`
	Status      string     `json:"status"`
	Conclusion  string     `json:"conclusion"`
	StartedAt   *time.Time `json:"started_at"`
	CompletedAt *time.Time `json:"completed_at"`
}

// ReadExperimentAttempt pins the attempt endpoint rather than the latest run.
// It reads neither logs nor source and never follows a response's jobs URL.
func (c *appClient) ReadExperimentAttempt(ctx context.Context, repo string, runID int64, attempt int) (*ExperimentAttemptEvidence, error) {
	owner, name, err := splitRepo(repo)
	if err != nil {
		return nil, err
	}
	if runID <= 0 || attempt <= 0 {
		return nil, fmt.Errorf("github: select a positive workflow run and attempt")
	}
	ctx, cancel := context.WithTimeout(ctx, 20*time.Second)
	defer cancel()
	// Reuse the isolated 4 MiB diagnostic body bound, with no conditional cache
	// or mutation of the shared installation client.
	bounded, err := c.prDelayClient()
	if err != nil {
		return nil, err
	}
	read := func() (*gh.WorkflowRun, error) {
		r, resp, err := bounded.asInstallation.Actions.GetWorkflowRunAttempt(ctx, owner, name, runID, attempt, nil)
		if err != nil {
			return nil, bounded.fail("read comparison workflow attempt", resp, err)
		}
		if r == nil || r.GetID() != runID || r.GetRunAttempt() != attempt || r.GetRepository().GetFullName() != repo || !validDelaySHA(r.GetHeadSHA()) || r.GetWorkflowID() <= 0 || !ValidExperimentAttemptContext(r.GetEvent(), r.GetPath()) {
			return nil, fmt.Errorf("github: comparison attempt has incomplete or inconsistent identity")
		}
		return r, nil
	}
	initial, err := read()
	if err != nil {
		return nil, err
	}
	stamp := func(t *gh.Timestamp) *time.Time {
		if t == nil || t.IsZero() {
			return nil
		}
		v := t.Time
		return &v
	}
	out := &ExperimentAttemptEvidence{Event: initial.GetEvent(), WorkflowPath: initial.GetPath(), Repository: repo, RunID: runID, Attempt: attempt, HeadSHA: initial.GetHeadSHA(), WorkflowID: initial.GetWorkflowID(), Status: initial.GetStatus(), Conclusion: initial.GetConclusion(), RunStartedAt: stamp(initial.RunStartedAt), UpdatedAt: stamp(initial.UpdatedAt), JobsCoverage: "partial", Jobs: []ExperimentAttemptJob{}}
	complete := initial.GetStatus() == "completed" && initial.GetConclusion() != "" && out.UpdatedAt != nil
	total := -1
	seen := map[int64]bool{}
	ended := false
	for page := 1; page <= 5; page++ {
		rows, resp, err := bounded.asInstallation.Actions.ListWorkflowJobsAttempt(ctx, owner, name, runID, int64(attempt), &gh.ListOptions{Page: page, PerPage: 100})
		if err != nil {
			return nil, bounded.fail("read comparison attempt jobs", resp, err)
		}
		if rows == nil || len(rows.Jobs) > 100 {
			return nil, fmt.Errorf("github: comparison job page is invalid")
		}
		if rows.TotalCount == nil || rows.GetTotalCount() < 0 {
			complete = false
		} else if total < 0 {
			total = rows.GetTotalCount()
		} else if total != rows.GetTotalCount() {
			complete = false
		}
		for _, j := range rows.Jobs {
			if j == nil || j.GetID() <= 0 || j.GetRunID() != runID || j.GetRunAttempt() != int64(attempt) || j.GetHeadSHA() != out.HeadSHA {
				return nil, fmt.Errorf("github: comparison job does not belong to the pinned run attempt")
			}
			if seen[j.GetID()] {
				complete = false
				continue
			}
			seen[j.GetID()] = true
			if j.GetStatus() != "completed" || j.GetConclusion() == "" {
				complete = false
			}
			out.Jobs = append(out.Jobs, ExperimentAttemptJob{ID: j.GetID(), Status: j.GetStatus(), Conclusion: j.GetConclusion(), StartedAt: stamp(j.StartedAt), CompletedAt: stamp(j.CompletedAt)})
		}
		if resp == nil {
			complete = false
			break
		}
		if resp.NextPage == 0 {
			ended = true
			break
		}
		// Sequential pages stay on the pinned endpoint, even if Link names a
		// different host. A jumping/backwards cursor does not establish coverage.
		if resp.NextPage != page+1 {
			complete = false
			break
		}
	}
	out.WorkflowSource, err = bounded.readExperimentSource(ctx, owner, name, out)
	if err != nil {
		return nil, err
	}
	final, err := read()
	if err != nil {
		return nil, err
	}
	sameStamp := func(a, b *gh.Timestamp) bool {
		if a == nil || b == nil {
			return a == nil && b == nil
		}
		return a.Time.Equal(b.Time)
	}
	if final.GetEvent() != out.Event || final.GetPath() != out.WorkflowPath || final.GetHeadSHA() != out.HeadSHA || final.GetWorkflowID() != out.WorkflowID || final.GetStatus() != out.Status || final.GetConclusion() != out.Conclusion || !sameStamp(initial.UpdatedAt, final.UpdatedAt) || !sameStamp(initial.RunStartedAt, final.RunStartedAt) {
		return nil, ErrExperimentAttemptChanged
	}
	if complete && ended && total == len(out.Jobs) {
		out.JobsCoverage = "complete"
	}
	return out, nil
}

// ValidExperimentAttemptContext bounds optional, untrusted metadata before it is
// retained. A path is opaque: it is never resolved as a file, URL or source ref.
// Empty fields remain unknown, including in evidence captured before this slice.
func ValidExperimentAttemptContext(event, workflowPath string) bool {
	if len(event) > 64 || len(workflowPath) > 1024 || !utf8.ValidString(workflowPath) {
		return false
	}
	for _, c := range event {
		if !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '_') {
			return false
		}
	}
	for _, c := range workflowPath {
		if unicode.IsControl(c) {
			return false
		}
	}
	return true
}

package github

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"strconv"
	"strings"
	"testing"
)

func experimentRunJSON(sha string) string {
	return fmt.Sprintf(`{"id":10,"run_attempt":2,"head_sha":%q,"workflow_id":20,"status":"completed","conclusion":"success","repository":{"full_name":"acme/repo"},"updated_at":"2026-10-13T01:00:00Z"}`, sha)
}
func experimentJobJSON(id int) string {
	return fmt.Sprintf(`{"id":%d,"run_id":10,"run_attempt":2,"head_sha":%q,"status":"completed","conclusion":"failure","name":"private workflow text","steps":[{"name":"private step"}]}`, id, delayTestSHA)
}

func TestAnExactAttemptReadPreservesFailuresWithoutWorkflowText(t *testing.T) {
	calls := 0
	c := delayTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		calls++
		if r.Method != "GET" {
			t.Error(r.Method)
		}
		switch r.URL.Path {
		case "/repos/acme/repo/actions/runs/10/attempts/2":
			fmt.Fprint(w, experimentRunJSON(delayTestSHA))
		case "/repos/acme/repo/actions/runs/10/attempts/2/jobs":
			if r.URL.Query().Get("per_page") != "100" {
				t.Error("page size")
			}
			fmt.Fprintf(w, `{"total_count":1,"jobs":[%s]}`, experimentJobJSON(1))
		default:
			t.Errorf("unexpected path %s", r.URL.Path)
			w.WriteHeader(404)
		}
	})
	e, err := c.ReadExperimentAttempt(context.Background(), "acme/repo", 10, 2)
	if err != nil {
		t.Fatal(err)
	}
	b, _ := json.Marshal(e)
	if e.JobsCoverage != "complete" || calls != 3 || len(e.Jobs) != 1 || e.Jobs[0].Conclusion != "failure" || strings.Contains(string(b), "private") {
		t.Fatalf("got %s calls=%d", b, calls)
	}
}
