func TestAttemptTriggerAndWorkflowPathArePinnedWithoutAdditionalReads(t *testing.T) {
	for _, mode := range []string{"present", "absent", "event_changes", "path_changes", "event_disappears", "path_disappears", "event_appears", "path_appears", "invalid_event", "oversized_path", "control_path"} {
		t.Run(mode, func(t *testing.T) {
			calls, runs := 0, 0
			c := delayTestClient(t, func(w http.ResponseWriter, r *http.Request) {
				calls++
				if strings.HasSuffix(r.URL.Path, "/jobs") {
					fmt.Fprintf(w, `{"total_count":1,"jobs":[%s]}`, experimentJobJSON(1))
					return
				}
				runs++
				event, path := "workflow_dispatch", ".github/workflows/build.yml@refs/heads/main"
				if mode == "absent" {
					event, path = "", ""
				}
				if runs == 1 && mode == "event_appears" {
					event = ""
				}
				if runs == 1 && mode == "path_appears" {
					path = ""
				}
				if runs > 1 {
					switch mode {
					case "event_changes":
						event = "push"
					case "path_changes":
						path = ".github/workflows/other.yml"
					case "event_disappears":
						event = ""
					case "path_disappears":
						path = ""
					}
				}
				switch mode {
				case "invalid_event":
					event = "push\nprivate"
				case "oversized_path":
					path = strings.Repeat("x", 1025)
				case "control_path":
					path = "file\x1b[31m"
				}
				payload := strings.TrimSuffix(experimentRunJSON(delayTestSHA), "}") + fmt.Sprintf(`,"event":%q,"path":%q,"display_title":"private title","inputs":{"token":"private secret"}}`, event, path)
				fmt.Fprint(w, payload)
			})
			e, err := c.ReadExperimentAttempt(context.Background(), "acme/repo", 10, 2)
			if mode != "present" && mode != "absent" {
				if err == nil {
					t.Fatal("changed or invalid context accepted")
				}
				if strings.HasPrefix(mode, "invalid") || mode == "oversized_path" || mode == "control_path" {
					if calls != 1 {
						t.Fatalf("invalid context spent %d reads", calls)
					}
				} else if calls != 3 {
					t.Fatalf("identity recheck spent %d reads", calls)
				}
				return
			}
			if err != nil {
				t.Fatal(err)
			}
			if calls != 3 {
				t.Fatalf("spent %d reads", calls)
			}
			if mode == "present" && (e.Event != "workflow_dispatch" || e.WorkflowPath != ".github/workflows/build.yml@refs/heads/main") {
				t.Fatalf("lost context: %+v", e)
			}
			b, _ := json.Marshal(e)
			if strings.Contains(string(b), "private") || mode == "absent" && (strings.Contains(string(b), `"event"`) || strings.Contains(string(b), `"workflow_path"`)) {
				t.Fatalf("unexpected projection %s", b)
			}
		})
	}
}

package github

import (
	"context"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"fmt"
	"path"
	"strings"
	"unicode/utf8"

	"github.com/eyupio/zoomies/internal/kennel/workflow"
	gh "github.com/google/go-github/v88/github"
)

const ExperimentWorkflowSourceBytes = 128 * 1024

// ExperimentWorkflowSource describes only the root file read at a push commit.
// Its digest does not cover reusable workflows, actions, inputs or test scope.
type ExperimentWorkflowSource struct {
	Dependencies  *workflow.DependencyInventory `json:"dependencies,omitempty"`
	Version       string                        `json:"version"`
	Basis         string                        `json:"basis"`
	CommitSHA     string                        `json:"commit_sha"`
	Path          string                        `json:"path"`
	BlobSHA       string                        `json:"blob_sha"`
	ContentSHA256 string                        `json:"content_sha256"`
	Bytes         int                           `json:"bytes"`
}

func experimentSourcePath(e *ExperimentAttemptEvidence) string {
	if e == nil || e.Event != "push" || !validDelaySHA(e.HeadSHA) {
		return ""
	}
	p := e.WorkflowPath
	// Mutable @refs and ambiguous paths must not be guessed from HeadSHA.
	if strings.Contains(p, "@") || strings.ContainsAny(p, "\\\\?#%") || path.Clean(p) != p || path.Dir(p) != ".github/workflows" || !(strings.HasSuffix(p, ".yml") || strings.HasSuffix(p, ".yaml")) || !ValidExperimentAttemptContext(e.Event, p) {
		return ""
	}
	return p
}

func (c *appClient) readExperimentSource(ctx context.Context, owner, repo string, e *ExperimentAttemptEvidence) (*ExperimentWorkflowSource, error) {
	p := experimentSourcePath(e)
	if p == "" {
		return nil, nil
	}
	// GetContents renders JSON inline; no download_url or branch lookup is followed.
	f, directory, resp, err := c.asInstallation.Repositories.GetContents(ctx, owner, repo, p, &gh.RepositoryContentGetOptions{Ref: e.HeadSHA})
	if err != nil {
		return nil, c.fail("read comparison workflow source at its push commit", resp, err)
	}
	raw := ""
	if f != nil && f.Content != nil {
		raw = *f.Content
	}
	if f == nil || directory != nil || f.GetType() != "file" || f.GetPath() != p || f.GetEncoding() != "base64" || f.GetSize() <= 0 || f.GetSize() > ExperimentWorkflowSourceBytes || len(raw) > ExperimentWorkflowSourceBytes*4/3+4096 || f.GetSubmoduleGitURL() != "" || f.GetTarget() != "" {
		return nil, fmt.Errorf("github: comparison workflow source has invalid identity, type, size or encoding")
	}
	content, err := base64.StdEncoding.DecodeString(strings.ReplaceAll(raw, "\n", ""))
	if err != nil || len(content) != f.GetSize() || !utf8.Valid(content) || contextGitBlobSHA(string(content)) != f.GetSHA() {
		return nil, fmt.Errorf("github: comparison workflow source failed content integrity validation")
	}
	digest := sha256.Sum256(content)
	return &ExperimentWorkflowSource{Dependencies: workflow.InspectDependencies(content), Version: "workflow-source-v1", Basis: "push_head_sha_root_file", CommitSHA: e.HeadSHA, Path: p, BlobSHA: f.GetSHA(), ContentSHA256: hex.EncodeToString(digest[:]), Bytes: len(content)}, nil
}

// ValidExperimentWorkflowSource checks the retained association and digest forms.
// Collection checks bytes; replay has only the retained digests, not source text.
func ValidExperimentWorkflowSource(e *ExperimentAttemptEvidence) bool {
	if e == nil {
		return false
	}
	s := e.WorkflowSource
	if s == nil {
		return true
	}
	validHash := func(v string, n int) bool {
		_, err := hex.DecodeString(v)
		return len(v) == n && err == nil && v == strings.ToLower(v)
	}
	return workflow.ValidDependencyInventory(s.Dependencies, s.ContentSHA256) && s.Version == "workflow-source-v1" && s.Basis == "push_head_sha_root_file" && experimentSourcePath(e) != "" && s.Path == e.WorkflowPath && s.CommitSHA == e.HeadSHA && s.Bytes > 0 && s.Bytes <= ExperimentWorkflowSourceBytes && validHash(s.BlobSHA, 40) && validHash(s.ContentSHA256, 64)
}

package github

import (
	"context"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"net/http"
	"strings"
	"testing"
)

func TestPushWorkflowSourceUsesTheImmutableCommitAndRetainsOnlyDigests(t *testing.T) {
	for _, mode := range []string{"observed", "dispatch", "missing_path", "mutable_ref", "traversal", "url", "wrong_path", "bad_blob", "wrong_size", "directory", "symlink", "encoding", "oversized", "invalid_utf8", "permission", "missing", "submodule", "bad_base64", "empty", "movement"} {
		t.Run(mode, func(t *testing.T) {
			calls, runs, sources := 0, 0, 0
			content := "name: private workflow\non: push\njobs:\n  private_job:\n    runs-on: linux\n    steps:\n      - uses: private_owner/private_repo@" + strings.Repeat("a", 40) + "\n      - uses: ./private-action\n# private token text\n"
			workflowPath := ".github/workflows/build.yml"
			event := "push"
			switch mode {
			case "dispatch":
				event = "workflow_dispatch"
			case "missing_path":
				workflowPath = ""
			case "mutable_ref":
				workflowPath += "@refs/heads/main"
			case "traversal":
				workflowPath = ".github/workflows/../workflows/build.yml"
			case "url":
				workflowPath = "https://other.example/workflow.yml"
			}
			c := delayTestClient(t, func(w http.ResponseWriter, r *http.Request) {
				calls++
				if r.Method != "GET" {
					t.Error("not a read")
				}
				switch r.URL.Path {
				case "/repos/acme/repo/actions/runs/10/attempts/2":
					runs++
					currentEvent := event
					if mode == "movement" && runs == 2 {
						currentEvent = "workflow_dispatch"
					}
					fmt.Fprint(w, strings.TrimSuffix(experimentRunJSON(delayTestSHA), "}")+fmt.Sprintf(`,"event":%q,"path":%q}`, currentEvent, workflowPath))
				case "/repos/acme/repo/actions/runs/10/attempts/2/jobs":
					fmt.Fprintf(w, `{"total_count":1,"jobs":[%s]}`, experimentJobJSON(1))
				case "/repos/acme/repo/contents/.github/workflows/build.yml":
					sources++
					if r.URL.Query().Get("ref") != delayTestSHA {
						t.Error("mutable or unpinned source ref")
					}
					if mode == "permission" || mode == "missing" {
						if mode == "missing" {
							w.WriteHeader(http.StatusNotFound)
						} else {
							w.WriteHeader(http.StatusForbidden)
						}
						fmt.Fprint(w, `{"message":"forbidden"}`)
						return
					}
					body := content
					if mode == "invalid_utf8" {
						body = string([]byte{0xff})
					}
					f := map[string]any{"type": "file", "path": workflowPath, "size": len(body), "sha": contextGitBlobSHA(body), "encoding": "base64", "content": base64.StdEncoding.EncodeToString([]byte(body)), "download_url": "https://other.example/private"}
					switch mode {
					case "wrong_path":
						f["path"] = ".github/workflows/other.yml"
					case "bad_blob":
						f["sha"] = strings.Repeat("b", 40)
					case "wrong_size":
						f["size"] = len(body) + 1
					case "directory":
						json.NewEncoder(w).Encode([]any{f})
						return
					case "symlink":
						f["type"] = "symlink"
						f["target"] = "private"
					case "encoding":
						f["encoding"] = "none"
					case "submodule":
						f["submodule_git_url"] = "https://other.example/repo"
					case "bad_base64":
						f["content"] = "%%%"
					case "empty":
						f["size"] = 0
					case "oversized":
						f["size"] = ExperimentWorkflowSourceBytes + 1
					}
					json.NewEncoder(w).Encode(f)
				default:
					t.Errorf("unexpected endpoint %s", r.URL.Path)
					w.WriteHeader(404)
				}
			})
			e, err := c.ReadExperimentAttempt(context.Background(), "acme/repo", 10, 2)
			skipped := mode == "dispatch" || mode == "missing_path" || mode == "mutable_ref" || mode == "traversal" || mode == "url"
			if skipped {
				if err != nil || e.WorkflowSource != nil || calls != 3 || sources != 0 {
					t.Fatalf("unsupported context fetched source: %+v %v %d", e, err, calls)
				}
				return
			}
			if mode != "observed" {
				if err == nil || calls > 4 || sources != 1 {
					t.Fatalf("invalid evidence accepted %v %d", err, calls)
				}
				return
			}
			if err != nil {
				t.Fatal(err)
			}
			digest := sha256.Sum256([]byte(content))
			s := e.WorkflowSource
			if calls != 4 || sources != 1 || s == nil || !ValidExperimentWorkflowSource(e) || s.ContentSHA256 != hex.EncodeToString(digest[:]) || s.BlobSHA != contextGitBlobSHA(content) || s.CommitSHA != delayTestSHA || s.Bytes != len(content) {
				t.Fatalf("lost or unpinned source: %+v calls=%d", e, calls)
			}
			if s.Dependencies == nil || s.Dependencies.Coverage != "enumerated" || s.Dependencies.Counts.Declarations != 2 || s.Dependencies.Counts.CommitPins != 1 || s.Dependencies.Counts.Local != 1 || s.Dependencies.SourceSHA256 != s.ContentSHA256 {
				t.Fatal("source inventory not bound or collected")
			}
			raw, _ := json.Marshal(e)
			if strings.Contains(string(raw), "private") || strings.Contains(string(raw), "download_url") {
				t.Fatal("source text or URL retained")
			}
		})
	}
}

package github

import (
	"encoding/base64"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"slices"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// FakeGitHub is an in-memory stand-in for the GitHub REST API.
//
// It lives in the production package rather than a _test.go file on purpose:
// the controller, scheduler and API tests all need a GitHub to run the whole
// system against, and a second, subtly different fake in each of them would be
// worse than one honest fake here. "Honest" means it enforces the rules that
// actually bite -- runner names must be unique, a deleted runner is gone, a
// job only appears in a run's job list -- so a test that passes against it has
// some claim to passing against GitHub.
//
// It serves both the github.com layout (/app) and the GitHub Enterprise Server
// layout (/api/v3/app), so the same fake exercises both code paths.
//
// Pagination is not implemented: every list returns one page. Tests that need
// to exercise paging should drive appClient against their own handler.
type FakeGitHub struct {
	srv *httptest.Server

	mu             sync.Mutex
	appID          int64
	installationID int64
	appSlug        string
	appName        string
	appOwner       string
	permissions    map[string]string
	// repositorySelection is GitHub's "all" or "selected".
	repositorySelection string
	events              []string

	nextRunnerID int64
	runners      []*Runner

	// repairActors is what the repair flow's collaborators-permission read
	// finds per login. GitHub serves that read for any collaborator, and
	// answers 404 for a name it does not know; a login nobody registered here
	// gets the same. A test that wants an actor whose identity is known says
	// so with SetRepairActor.
	repairActors map[string]repairActor

	// jobReruns counts job-level re-run requests, kept apart from reruns so a
	// test can say which endpoint the controller chose.
	jobReruns int
	// reruns counts re-run requests, which nothing else records: the fake
	// answers and forgets, and a test asserting that Zoomies asked GitHub
	// exactly once needs somewhere to look.
	reruns int
	// contextDispatches counts manual runs of a repository's managed AI
	// Context workflow, keyed by repository and workflow file.
	contextDispatches map[string]int
	// contextRuns is what the fake says the managed AI Context workflow did, and
	// the artifacts a repository holds: see fake_ai_context_runs.go.
	contextRuns fakeContextRuns

	nextJobID     int64
	nextRunID     int64
	nextRunNumber int64
	jobs          []*fakeJob
	repos         []string
	// contents holds what the migration surface reads and writes: files,
	// branches and pull requests, per repository. It fills in lazily, so a
	// test that never migrates anything pays nothing for it.
	contents map[string]*fakeRepo

	groups []RunnerGroup

	rateLimit RateLimit

	// runTriggers says how a run began, for the runs a test has described: see
	// fake_kennel.go.
	runTriggers map[string]fakeRunTrigger
	// notModified counts the 304s the fake has answered.
	notModified int

	failures []fakeFailure
	delays   []fakeDelay
	requests []string
}

// fakeJob is one queued/running/finished job. Every job gets its own workflow
// run, which is the common shape and keeps the run listing meaningful.
type fakeJob struct {
	QueuedJob
	runStatus string
}

// fakeFailure makes matching requests fail, so tests can exercise the error
// paths without a network.
type fakeFailure struct {
	// method narrows the failure to one HTTP verb. Empty matches any.
	method  string
	pattern string
	status  int
	message string
}

// fakeDelay holds a matching request open before it is served, so a test can
// exercise a GitHub call that takes real wall-clock time -- a controller
// detaching that call from a lock it must not hold is not proven by one that
// answers before anybody could tell the difference.
type fakeDelay struct {
	method  string
	pattern string
	d       time.Duration
}

// NewFake starts a fake GitHub and returns it. The caller must Close it.
func NewFake() *FakeGitHub {
	f := &FakeGitHub{
		appID:               12345,
		installationID:      42,
		appSlug:             "zoomies-fake",
		appName:             "Zoomies Fake",
		appOwner:            "acme",
		repositorySelection: "all",
		// What an App created with the migration option is granted, which is what
		// the manifest in manifest.go asks for when it is asked to. The three
		// migration permissions belong here because this fake serves repository
		// contents: an App described as
		// unable to read them, while the fake hands them over anyway, is a
		// fixture no real installation can be in, and it hid the wizard
		// reporting an App's missing Contents permission as "these
		// repositories have no workflows". A test that wants a narrower App
		// says so with SetPermissions.
		permissions: map[string]string{
			"actions":                          "write",
			"metadata":                         "read",
			"administration":                   "write",
			"organization_self_hosted_runners": "write",
			"contents":                         "write",
			"pull_requests":                    "write",
			"workflows":                        "write",
		},
		events:        []string{"workflow_job"},
		repairActors:  map[string]repairActor{},
		nextRunnerID:  1,
		nextJobID:     1000,
		nextRunID:     5000,
		nextRunNumber: 1,
		groups: []RunnerGroup{{
			ID: 1, Name: "Default", Default: true,
			PublicRepositoryAccessKnown: true, AllowsPublicRepositories: true,
		}},
		rateLimit: RateLimit{Limit: 5000, Remaining: 4999, ResetAt: time.Now().Add(time.Hour).UTC()},
	}
	f.srv = httptest.NewServer(f.handler())
	return f
}

// Server exposes the underlying test server, for tests that need its URL or
// its TLS-aware http.Client.
func (f *FakeGitHub) Server() *httptest.Server { return f.srv }

// URL is the API base URL to hand to an installation.
func (f *FakeGitHub) URL() string { return f.srv.URL }

// Close shuts the server down.
func (f *FakeGitHub) Close() { f.srv.Close() }

// AppID is the App ID the fake claims to be.
func (f *FakeGitHub) AppID() int64 { return f.appID }

// InstallationID is the installation ID the fake serves.
func (f *FakeGitHub) InstallationID() int64 { return f.installationID }

// Client returns a Client wired to this fake for the given target. It is the
// quickest way for a test to get a working github.Client.
func (f *FakeGitHub) Client(target string, kind store.TargetType) Client {
	base := f.srv.URL + "/"
	c, err := newGitHubClient(f.srv.Client(), base, base)
	if err != nil {
		// The URL comes from httptest, so this cannot happen; failing loudly
		// beats handing back a client that talks to the real GitHub.
		panic("github: fake: " + err.Error())
	}
	ac := newAppClient(c, c, target, kind, f.installationID, "https://github.com")
	// Kennel Club's reads go through the conditional client in production, so a
	// test of them must too, or it would pass while the real path was broken.
	ac.enableConditionalReads(newConditionalCache(conditionalCacheBytes), "fake|"+strconv.FormatInt(f.installationID, 10))
	return ac
}

// SetRepositorySelection sets GitHub's "all" or "selected", so a test can
// describe an App installed on a handful of repositories rather than on
// everything.
func (f *FakeGitHub) SetRepositorySelection(selection string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.repositorySelection = selection
}

// SetPermissions replaces what the App reports being granted, so tests can
// exercise the "missing permission" reporting.
func (f *FakeGitHub) SetPermissions(p map[string]string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.permissions = p
}

// SetEvents replaces the App's event subscriptions.
func (f *FakeGitHub) SetEvents(events ...string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.events = events
}

// AddRepo makes "owner/name" visible to the installation. AddQueuedJob does
// this for you; call it directly for a repository with no jobs.
func (f *FakeGitHub) AddRepo(fullName string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.addRepoLocked(fullName)
}

func (f *FakeGitHub) addRepoLocked(fullName string) {
	if fullName == "" || slices.Contains(f.repos, fullName) {
		return
	}
	f.repos = append(f.repos, fullName)
	f.repoLocked(fullName).id = int64(len(f.repos))
}

// AddRunnerGroup registers a runner group and returns it.
func (f *FakeGitHub) AddRunnerGroup(name string) RunnerGroup {
	f.mu.Lock()
	defer f.mu.Unlock()
	g := RunnerGroup{ID: int64(len(f.groups) + 1), Name: name,
		Visibility:                  "all",
		PublicRepositoryAccessKnown: true, AllowsPublicRepositories: true}
	f.groups = append(f.groups, g)
	return g
}

// SetRunnerGroupPublicAccess changes the public-repository policy GitHub
// reports for a group. It exists for controller tests of the otherwise easy
// to miss state where a runner is online but no public-repository job is
// eligible to use it.
func (f *FakeGitHub) SetRunnerGroupPublicAccess(name string, allowed bool) {
	f.mu.Lock()
	defer f.mu.Unlock()
	for i := range f.groups {
		if strings.EqualFold(f.groups[i].Name, name) {
			f.groups[i].PublicRepositoryAccessKnown = true
			f.groups[i].AllowsPublicRepositories = allowed
			return
		}
	}
}

// AddRunner registers a runner that Zoomies did not create, which is how a
// test simulates a registration the controller has lost track of.
func (f *FakeGitHub) AddRunner(name string, labels []string) Runner {
	f.mu.Lock()
	defer f.mu.Unlock()
	r := f.addRunnerLocked(name, labels, false)
	return *r
}

func (f *FakeGitHub) addRunnerLocked(name string, labels []string, ephemeral bool) *Runner {
	r := &Runner{
		ID:        f.nextRunnerID,
		Name:      name,
		OS:        "linux",
		Status:    "online",
		Labels:    append([]string{"self-hosted"}, labels...),
		Ephemeral: ephemeral,
	}
	f.nextRunnerID++
	f.runners = append(f.runners, r)
	return r
}

// SetRunnerBusy marks a registered runner busy or idle, the same field
// GitHub's own runner list carries. Tests use it to reproduce the race where
// GitHub still considers a runner busy after its completion webhook already
// fired: deleting it is refused the way GitHub refuses it for real.
func (f *FakeGitHub) SetRunnerBusy(name string, busy bool) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if i := slices.IndexFunc(f.runners, func(r *Runner) bool { return r.Name == name }); i >= 0 {
		f.runners[i].Busy = busy
	}
}

// Runners returns a snapshot of the registered runners.
func (f *FakeGitHub) Runners() []Runner {
	f.mu.Lock()
	defer f.mu.Unlock()
	out := make([]Runner, 0, len(f.runners))
	for _, r := range f.runners {
		out = append(out, *r)
	}
	return out
}

// AddQueuedJob queues a job on repo ("owner/name") and returns it as the API
// will report it. The repository becomes visible to the installation.
func (f *FakeGitHub) AddQueuedJob(repo, workflow, jobName string, labels []string) QueuedJob {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.addRepoLocked(repo)
	// A queued job usually follows a push; the poller sorts on it.
	f.repoLocked(repo).pushedAt = time.Now().UTC()
	j := &fakeJob{
		QueuedJob: QueuedJob{
			ID:           f.nextJobID,
			RunID:        f.nextRunID,
			RunNumber:    f.nextRunNumber,
			Repo:         repo,
			WorkflowName: workflow,
			JobName:      jobName,
			Labels:       slices.Clone(labels),
			QueuedAt:     time.Now().UTC(),
			HTMLURL:      fmt.Sprintf("https://github.com/%s/actions/runs/%d/job/%d", repo, f.nextRunID, f.nextJobID),
			Status:       string(store.JobQueued),
		},
		runStatus: string(store.JobQueued),
	}
	f.nextJobID++
	f.nextRunID++
	f.nextRunNumber++
	f.jobs = append(f.jobs, j)
	return j.QueuedJob
}

// StartJob marks a queued job as picked up by runnerName.
func (f *FakeGitHub) StartJob(jobID int64, runnerName string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if j := f.findJobLocked(jobID); j != nil {
		now := time.Now().UTC()
		j.Status = string(store.JobInProgress)
		j.runStatus = string(store.JobInProgress)
		j.RunnerName = runnerName
		j.StartedAt = &now
	}
}

// CompleteJob finishes a job with the given conclusion ("success",
// "failure", "cancelled", ...).
func (f *FakeGitHub) CompleteJob(jobID int64, conclusion string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if j := f.findJobLocked(jobID); j != nil {
		now := time.Now().UTC()
		if j.StartedAt == nil {
			j.StartedAt = &now
		}
		j.Status = string(store.JobCompleted)
		j.runStatus = string(store.JobCompleted)
		j.Conclusion = conclusion
		j.CompletedAt = &now
	}
}

// SetWorkflowRunState changes the run record independently of its jobs. That
// distinction lets controller tests prove that one cancelled stage does not
// fan cancellation out to the rest of the workflow.
func (f *FakeGitHub) SetWorkflowRunState(runID int64, status, conclusion string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	for _, j := range f.jobs {
		if j.RunID == runID {
			j.runStatus = status
			if conclusion != "" {
				j.Conclusion = conclusion
			}
		}
	}
}

func (f *FakeGitHub) findJobLocked(id int64) *fakeJob {
	for _, j := range f.jobs {
		if j.ID == id {
			return j
		}
	}
	return nil
}

// SetError makes every request whose path contains pattern fail with status
// and message. An empty pattern matches every request. Calls accumulate; use
// ClearErrors to reset.
//
// A 403 carrying the rate-limit headers (see SetRateLimit) is how a test
// produces ErrRateLimited, because that is how GitHub signals it.
func (f *FakeGitHub) SetError(pattern string, status int, message string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.failures = append(f.failures, fakeFailure{pattern: pattern, status: status, message: message})
}

// SetMethodError is SetError narrowed to one HTTP method.
//
// Several verbs share a path: an orphan sweep lists an installation's runners
// and then deletes them at the same one, so a test about a refused delete
// cannot afford to refuse the listing that finds them too.
func (f *FakeGitHub) SetMethodError(method, pattern string, status int, message string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.failures = append(f.failures, fakeFailure{
		method: method, pattern: pattern, status: status, message: message,
	})
}

// SetDelay holds every request matching method (empty for any) and pattern
// open for d before it is served, so a test can drive a GitHub call that
// takes real wall-clock time.
func (f *FakeGitHub) SetDelay(method, pattern string, d time.Duration) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.delays = append(f.delays, fakeDelay{method: method, pattern: pattern, d: d})
}

// ClearErrors removes every failure injected with SetError.
func (f *FakeGitHub) ClearErrors() {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.failures = nil
}

// SetRateLimit sets the quota reported by /rate_limit and by the rate-limit
// headers on every response.
func (f *FakeGitHub) SetRateLimit(limit, remaining int, reset time.Time) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.rateLimit = RateLimit{Limit: limit, Remaining: remaining, ResetAt: reset.UTC()}
}

// Requests returns every request the fake has served, as "GET /path". Tests
// use it to assert that a poll stayed within its call budget.
func (f *FakeGitHub) Requests() []string {
	f.mu.Lock()
	defer f.mu.Unlock()
	return slices.Clone(f.requests)
}

// ---------------------------------------------------------------------------
// HTTP surface
// ---------------------------------------------------------------------------

func (f *FakeGitHub) handler() http.Handler {
	mux := http.NewServeMux()

	mux.HandleFunc("GET /app", f.getApp)
	mux.HandleFunc("GET /app/installations/{id}", f.getInstallation)
	mux.HandleFunc("POST /app/installations/{id}/access_tokens", f.createInstallationToken)
	mux.HandleFunc("GET /installation/repositories", f.listInstallationRepos)
	mux.HandleFunc("GET /rate_limit", f.getRateLimit)
	// The repair flow's identity read. Served like the rest of the fake: a
	// login nobody registered is not a collaborator GitHub would tell us
	// about either.
	mux.HandleFunc("GET /repos/{owner}/{repo}/collaborators/{user}/permission", f.collaboratorPermission)

	mux.HandleFunc("POST /orgs/{org}/actions/runners/generate-jitconfig", f.generateJITConfig)
	mux.HandleFunc("POST /repos/{owner}/{repo}/actions/runners/generate-jitconfig", f.generateJITConfig)
	mux.HandleFunc("POST /orgs/{org}/actions/runners/registration-token", f.createToken)
	mux.HandleFunc("POST /repos/{owner}/{repo}/actions/runners/registration-token", f.createToken)
	mux.HandleFunc("POST /orgs/{org}/actions/runners/remove-token", f.createToken)
	mux.HandleFunc("POST /repos/{owner}/{repo}/actions/runners/remove-token", f.createToken)
	mux.HandleFunc("GET /orgs/{org}/actions/runners", f.listRunners)
	mux.HandleFunc("GET /repos/{owner}/{repo}/actions/runners", f.listRunners)
	mux.HandleFunc("DELETE /orgs/{org}/actions/runners/{id}", f.deleteRunner)
	mux.HandleFunc("DELETE /repos/{owner}/{repo}/actions/runners/{id}", f.deleteRunner)
	mux.HandleFunc("GET /orgs/{org}/actions/runner-groups", f.listRunnerGroups)
	mux.HandleFunc("POST /orgs/{org}/actions/runner-groups", f.createRunnerGroup)

	mux.HandleFunc("GET /repos/{owner}/{repo}/actions/jobs/{job}", f.getWorkflowJob)
	mux.HandleFunc("GET /repos/{owner}/{repo}/actions/runs", f.listWorkflowRuns)
	mux.HandleFunc("GET /repos/{owner}/{repo}/actions/runs/{run}", f.getWorkflowRun)
	mux.HandleFunc("GET /repos/{owner}/{repo}/actions/runs/{run}/jobs", f.listWorkflowJobs)
	mux.HandleFunc("POST /repos/{owner}/{repo}/actions/runs/{run}/cancel", f.cancelWorkflowRun)
	mux.HandleFunc("POST /repos/{owner}/{repo}/actions/runs/{run}/force-cancel", f.cancelWorkflowRun)
	mux.HandleFunc("POST /repos/{owner}/{repo}/actions/runs/{run}/rerun-failed-jobs", f.rerunFailedJobs)
	mux.HandleFunc("POST /repos/{owner}/{repo}/actions/jobs/{job}/rerun", f.rerunJob)

	f.registerMigrationRoutes(mux)
	f.registerKennelSettingsRoutes(mux)

	return f.middleware(mux)
}

func (f *FakeGitHub) cancelWorkflowRun(w http.ResponseWriter, _ *http.Request) {
	f.mu.Lock()
	level := f.permissions["actions"]
	f.mu.Unlock()
	if level != "write" {
		writeError(w, http.StatusForbidden, "Resource not accessible by integration")
		return
	}
	w.WriteHeader(http.StatusAccepted)
}

// rerunFailedJobs answers a re-run request. It needs the same Actions write
// permission a cancel does, and it answers 201 as GitHub does, so a test can
// tell the two status paths apart.
func (f *FakeGitHub) rerunFailedJobs(w http.ResponseWriter, _ *http.Request) {
	f.mu.Lock()
	level := f.permissions["actions"]
	f.reruns++
	f.mu.Unlock()
	if level != "write" {
		writeError(w, http.StatusForbidden, "Resource not accessible by integration")
		return
	}
	w.WriteHeader(http.StatusCreated)
}

// rerunJob answers a job-level re-run. It is a separate counter from the
// run-level one, because which of the two a caller reached for is the whole
// difference between re-running one job and re-running every failure in its
// run, and a test that could not tell them apart could not hold that.
func (f *FakeGitHub) rerunJob(w http.ResponseWriter, _ *http.Request) {
	f.mu.Lock()
	level := f.permissions["actions"]
	f.jobReruns++
	f.mu.Unlock()
	if level != "write" {
		writeError(w, http.StatusForbidden, "Resource not accessible by integration")
		return
	}
	w.WriteHeader(http.StatusCreated)
}

// JobReruns is how many job-level re-run requests the fake has been sent.
func (f *FakeGitHub) JobReruns() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.jobReruns
}

// Reruns is how many re-run requests the fake has been sent, so a test can
// assert that asking twice asked GitHub twice -- or, where the controller
// refuses, that it asked nothing at all.
func (f *FakeGitHub) Reruns() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.reruns
}

// middleware records the request, strips the GitHub Enterprise Server /api/v3
// prefix so one set of routes serves both layouts, stamps the rate-limit
// headers GitHub always sends, and applies any injected failure.
func (f *FakeGitHub) middleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// The raw path is what gets recorded, so a test can tell a GHES-shaped
		// call from a github.com-shaped one.
		raw := r.URL.Path
		path := raw
		if rest, ok := strings.CutPrefix(path, "/api/v3"); ok && strings.HasPrefix(rest, "/") {
			r = r.Clone(r.Context())
			r.URL.Path = rest
			path = rest
		}

		f.mu.Lock()
		f.requests = append(f.requests, r.Method+" "+raw)
		rate := f.rateLimit
		var hit *fakeFailure
		for i := range f.failures {
			if f.failures[i].method != "" && f.failures[i].method != r.Method {
				continue
			}
			if f.failures[i].pattern == "" || strings.Contains(path, f.failures[i].pattern) {
				hit = &f.failures[i]
				break
			}
		}
		var wait time.Duration
		for i := range f.delays {
			if f.delays[i].method != "" && f.delays[i].method != r.Method {
				continue
			}
			if f.delays[i].pattern == "" || strings.Contains(path, f.delays[i].pattern) {
				wait = f.delays[i].d
				break
			}
		}
		f.mu.Unlock()

		if wait > 0 {
			select {
			case <-time.After(wait):
			case <-r.Context().Done():
				return
			}
		}

		h := w.Header()
		h.Set("Content-Type", "application/json; charset=utf-8")
		h.Set("X-Ratelimit-Limit", strconv.Itoa(rate.Limit))
		h.Set("X-Ratelimit-Remaining", strconv.Itoa(rate.Remaining))
		h.Set("X-Ratelimit-Reset", strconv.FormatInt(rate.ResetAt.Unix(), 10))

		if hit != nil {
			writeError(w, hit.status, hit.message)
			return
		}
		next.ServeHTTP(w, r)
	})
}

// repairActor is the identity a collaborator's permission read resolves to:
// the numeric id the link stores, and whether they may write.
type repairActor struct {
	id       int64
	canWrite bool
}

// SetRepairActor registers the collaborators-permission answer for a login,
// so a repair-flow test decides who GitHub says the account is, and what
// they may do.
func (f *FakeGitHub) SetRepairActor(login string, id int64, canWrite bool) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.repairActors[login] = repairActor{id: id, canWrite: canWrite}
}

func writeJSON(w http.ResponseWriter, status int, body any) {
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(body)
}

func writeError(w http.ResponseWriter, status int, message string) {
	if message == "" {
		message = http.StatusText(status)
	}
	writeJSON(w, status, map[string]any{
		"message":           message,
		"documentation_url": "https://docs.github.com/rest",
	})
}

// target reconstructs the target a request addresses, so one handler can serve
// both halves of each org/repo endpoint pair.
func target(r *http.Request) (full string, kind store.TargetType) {
	if org := r.PathValue("org"); org != "" {
		return org, store.TargetOrg
	}
	return r.PathValue("owner") + "/" + r.PathValue("repo"), store.TargetRepo
}

// collaboratorPermission answers the read the repair flow makes after a
// comment or a link form names a GitHub login: the numeric identity behind it
// and what they may do to the repository. Serving it here keeps RepairActor's
// tests on the real code path.
func (f *FakeGitHub) collaboratorPermission(w http.ResponseWriter, r *http.Request) {
	f.mu.Lock()
	defer f.mu.Unlock()
	actor, ok := f.repairActors[r.PathValue("user")]
	if !ok {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	login := r.PathValue("user")
	writeJSON(w, http.StatusOK, map[string]any{
		"permission": map[bool]string{true: "write", false: "read"}[actor.canWrite],
		"user":       map[string]any{"id": actor.id, "login": login},
	})
}

func (f *FakeGitHub) getApp(w http.ResponseWriter, _ *http.Request) {
	f.mu.Lock()
	defer f.mu.Unlock()
	writeJSON(w, http.StatusOK, map[string]any{
		"id":          f.appID,
		"slug":        f.appSlug,
		"name":        f.appName,
		"owner":       map[string]any{"login": f.appOwner},
		"permissions": f.permissions,
		"events":      f.events,
	})
}

func (f *FakeGitHub) getInstallation(w http.ResponseWriter, r *http.Request) {
	id, _ := strconv.ParseInt(r.PathValue("id"), 10, 64)
	f.mu.Lock()
	defer f.mu.Unlock()
	if id != f.installationID {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"id":          f.installationID,
		"app_id":      f.appID,
		"app_slug":    f.appSlug,
		"account":     map[string]any{"login": f.appOwner},
		"target_type": "Organization",
		"permissions": f.permissions,
		"events":      f.events,
		// How much of the target the installation covers. GitHub sends it on
		// every installation, and it is what tells "the App can see everything
		// you push to" from "the App was installed on three repositories and
		// yours is not one of them".
		"repository_selection": f.repositorySelection,
	})
}

func (f *FakeGitHub) createInstallationToken(w http.ResponseWriter, r *http.Request) {
	id, _ := strconv.ParseInt(r.PathValue("id"), 10, 64)
	f.mu.Lock()
	defer f.mu.Unlock()
	if id != f.installationID {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	writeJSON(w, http.StatusCreated, map[string]any{
		"token":       "ghs_fake_installation_token",
		"expires_at":  time.Now().Add(time.Hour).UTC().Format(time.RFC3339),
		"permissions": f.permissions,
	})
}

func (f *FakeGitHub) listInstallationRepos(w http.ResponseWriter, r *http.Request) {
	f.mu.Lock()
	defer f.mu.Unlock()
	repos := make([]map[string]any, 0, len(f.repos))
	for _, full := range f.repos {
		owner, name, _ := SplitTarget(full)
		repos = append(repos, map[string]any{
			"id":        f.repoLocked(full).id,
			"full_name": full,
			"name":      name,
			"owner":     map[string]any{"login": owner},
			// The migration scan reads the default branch from here: a pull
			// request has to be opened against one, and guessing "main" is how
			// a migration fails silently on a repository still using "master".
			"default_branch": f.repoLocked(full).defaultBranch,
			"private":        f.visibilityLocked(full) != "public",
			"visibility":     f.visibilityLocked(full),
			"archived":       f.repoLocked(full).archived,
			"html_url":       "https://github.com/" + full,
			"pushed_at":      f.repoLocked(full).pushedAt.UTC().Format(time.RFC3339),
		})
	}
	f.writeETagged(w, r, map[string]any{"total_count": len(repos), "repositories": repos})
}

func (f *FakeGitHub) getRateLimit(w http.ResponseWriter, _ *http.Request) {
	f.mu.Lock()
	defer f.mu.Unlock()
	core := map[string]any{
		"limit":     f.rateLimit.Limit,
		"remaining": f.rateLimit.Remaining,
		"used":      f.rateLimit.Limit - f.rateLimit.Remaining,
		"reset":     f.rateLimit.ResetAt.Unix(),
	}
	writeJSON(w, http.StatusOK, map[string]any{"resources": map[string]any{"core": core}})
}

func (f *FakeGitHub) generateJITConfig(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Name          string   `json:"name"`
		RunnerGroupID int64    `json:"runner_group_id"`
		WorkFolder    string   `json:"work_folder"`
		Labels        []string `json:"labels"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "Problems parsing JSON")
		return
	}
	if req.Name == "" || len(req.Labels) == 0 {
		writeError(w, http.StatusUnprocessableEntity, "Validation Failed: name and labels are required")
		return
	}

	f.mu.Lock()
	defer f.mu.Unlock()
	// GitHub refuses to reuse a runner name within a target; a fake that
	// allowed it would hide the bug where a pool mints colliding names.
	for _, existing := range f.runners {
		if existing.Name == req.Name {
			writeError(w, http.StatusConflict,
				fmt.Sprintf("A runner with the name %q already exists.", req.Name))
			return
		}
	}
	if !slices.ContainsFunc(f.groups, func(g RunnerGroup) bool { return g.ID == req.RunnerGroupID }) {
		writeError(w, http.StatusNotFound, "Runner group not found")
		return
	}

	runner := f.addRunnerLocked(req.Name, req.Labels, true)
	blob, _ := json.Marshal(map[string]any{
		"name":        req.Name,
		"labels":      req.Labels,
		"work_folder": req.WorkFolder,
		"runner_id":   runner.ID,
	})
	writeJSON(w, http.StatusCreated, map[string]any{
		"runner":             runnerJSON(runner),
		"encoded_jit_config": base64.StdEncoding.EncodeToString(blob),
	})
}

func (f *FakeGitHub) createToken(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusCreated, map[string]any{
		"token":      "AABF3JGZDX3P5PMEXLND6TS6FCWO6",
		"expires_at": time.Now().Add(time.Hour).UTC().Format(time.RFC3339),
	})
}

func (f *FakeGitHub) listRunners(w http.ResponseWriter, _ *http.Request) {
	f.mu.Lock()
	defer f.mu.Unlock()
	out := make([]map[string]any, 0, len(f.runners))
	for _, r := range f.runners {
		out = append(out, runnerJSON(r))
	}
	writeJSON(w, http.StatusOK, map[string]any{"total_count": len(out), "runners": out})
}

func runnerJSON(r *Runner) map[string]any {
	labels := make([]map[string]any, 0, len(r.Labels))
	for i, l := range r.Labels {
		labels = append(labels, map[string]any{"id": i + 1, "name": l, "type": "custom"})
	}
	return map[string]any{
		"id":        r.ID,
		"name":      r.Name,
		"os":        r.OS,
		"status":    r.Status,
		"busy":      r.Busy,
		"ephemeral": r.Ephemeral,
		"labels":    labels,
	}
}

func (f *FakeGitHub) deleteRunner(w http.ResponseWriter, r *http.Request) {
	id, _ := strconv.ParseInt(r.PathValue("id"), 10, 64)
	f.mu.Lock()
	defer f.mu.Unlock()
	i := slices.IndexFunc(f.runners, func(x *Runner) bool { return x.ID == id })
	if i < 0 {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	if f.runners[i].Busy {
		// The refusal real GitHub sends for this, reproduced verbatim: it is
		// the plain message field, with no per-field errors array, which is
		// why classify() reads it straight off er.Message.
		writeError(w, http.StatusUnprocessableEntity, fmt.Sprintf(
			"Bad request - Runner %s is currently running a job and cannot be deleted.", f.runners[i].Name))
		return
	}
	f.runners = slices.Delete(f.runners, i, i+1)
	w.WriteHeader(http.StatusNoContent)
}

func (f *FakeGitHub) listRunnerGroups(w http.ResponseWriter, _ *http.Request) {
	f.mu.Lock()
	defer f.mu.Unlock()
	out := make([]map[string]any, 0, len(f.groups))
	for _, g := range f.groups {
		out = append(out, map[string]any{
			"id": g.ID, "name": g.Name, "default": g.Default,
			"visibility":                 g.Visibility,
			"allows_public_repositories": g.AllowsPublicRepositories,
			"restricted_to_workflows":    g.RestrictedToWorkflows,
		})
	}
	writeJSON(w, http.StatusOK, map[string]any{"total_count": len(out), "runner_groups": out})
}

func (f *FakeGitHub) createRunnerGroup(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Name                     string `json:"name"`
		Visibility               string `json:"visibility"`
		AllowsPublicRepositories bool   `json:"allows_public_repositories"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil || strings.TrimSpace(req.Name) == "" {
		writeError(w, http.StatusUnprocessableEntity, "Validation Failed")
		return
	}
	f.mu.Lock()
	defer f.mu.Unlock()
	if slices.ContainsFunc(f.groups, func(g RunnerGroup) bool { return strings.EqualFold(g.Name, req.Name) }) {
		writeError(w, http.StatusUnprocessableEntity, "Validation Failed")
		return
	}
	g := RunnerGroup{
		ID: int64(len(f.groups) + 1), Name: strings.TrimSpace(req.Name), Visibility: req.Visibility,
		PublicRepositoryAccessKnown: true, AllowsPublicRepositories: req.AllowsPublicRepositories,
	}
	f.groups = append(f.groups, g)
	writeJSON(w, http.StatusCreated, map[string]any{
		"id": g.ID, "name": g.Name, "default": false, "visibility": g.Visibility,
		"allows_public_repositories": g.AllowsPublicRepositories,
		"restricted_to_workflows":    false,
	})
}

func (f *FakeGitHub) listWorkflowRuns(w http.ResponseWriter, r *http.Request) {
	full, _ := target(r)
	want := r.URL.Query().Get("status")

	f.mu.Lock()
	defer f.mu.Unlock()
	runs := make([]map[string]any, 0)
	for _, j := range f.jobs {
		if j.Repo != full {
			continue
		}
		if want != "" && j.runStatus != want {
			continue
		}
		runs = append(runs, map[string]any{
			"id":         j.RunID,
			"run_number": j.RunNumber,
			"name":       j.WorkflowName,
			"status":     j.runStatus,
			"created_at": j.QueuedAt.Format(time.RFC3339),
			"html_url":   j.HTMLURL,
		})
	}
	writeJSON(w, http.StatusOK, map[string]any{"total_count": len(runs), "workflow_runs": runs})
}

func (f *FakeGitHub) getWorkflowRun(w http.ResponseWriter, r *http.Request) {
	full, _ := target(r)
	runID, _ := strconv.ParseInt(r.PathValue("run"), 10, 64)

	f.mu.Lock()
	defer f.mu.Unlock()
	// Reading a run needs Actions read, as it does on GitHub. Without it the
	// answer is a 403, not a 404: the repository is there, the App just may not
	// look at its runs.
	if !f.canReadActionsLocked() {
		writeError(w, http.StatusForbidden, "Resource not accessible by integration")
		return
	}
	body := map[string]any{"id": runID}
	found := false
	for _, j := range f.jobs {
		if j.Repo == full && j.RunID == runID {
			body["status"], body["conclusion"] = j.runStatus, j.Conclusion
			body["name"], body["html_url"], body["run_number"] = j.WorkflowName, j.HTMLURL, j.RunNumber
			found = true
			break
		}
	}
	trig, described := f.runTriggers[triggerKey(full, runID)]
	if !found && !described {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	// A run says where it ran and where its head commit is. A push or a
	// scheduled run is its own repository's; a pull request from a fork is not.
	repoID := f.repoLocked(full).id
	body["event"] = "push"
	body["repository"] = map[string]any{"id": repoID}
	body["head_repository"] = map[string]any{"id": repoID}
	if described {
		body["event"] = trig.event
		if trig.headRepositoryID == 0 {
			body["head_repository"] = nil
		} else {
			body["head_repository"] = map[string]any{"id": trig.headRepositoryID}
		}
	}
	writeJSON(w, http.StatusOK, body)
}

func (f *FakeGitHub) listWorkflowJobs(w http.ResponseWriter, r *http.Request) {
	full, _ := target(r)
	runID, _ := strconv.ParseInt(r.PathValue("run"), 10, 64)

	f.mu.Lock()
	defer f.mu.Unlock()
	if f.writeContextRunJobsLocked(w, full, runID) {
		return
	}
	jobs := make([]map[string]any, 0)
	for _, j := range f.jobs {
		if j.Repo != full || j.RunID != runID {
			continue
		}
		job := map[string]any{
			"id":            j.ID,
			"run_id":        j.RunID,
			"name":          j.JobName,
			"workflow_name": j.WorkflowName,
			"status":        j.Status,
			"labels":        j.Labels,
			"created_at":    j.QueuedAt.Format(time.RFC3339),
			"html_url":      j.HTMLURL,
			"runner_name":   j.RunnerName,
		}
		if j.Conclusion != "" {
			job["conclusion"] = j.Conclusion
		}
		if j.StartedAt != nil {
			job["started_at"] = j.StartedAt.Format(time.RFC3339)
		}
		if j.CompletedAt != nil {
			job["completed_at"] = j.CompletedAt.Format(time.RFC3339)
		}
		jobs = append(jobs, job)
	}
	if len(jobs) == 0 {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"total_count": len(jobs), "jobs": jobs})
}

func (f *FakeGitHub) getWorkflowJob(w http.ResponseWriter, r *http.Request) {
	full, _ := target(r)
	id, _ := strconv.ParseInt(r.PathValue("job"), 10, 64)
	f.mu.Lock()
	defer f.mu.Unlock()
	j := f.findJobLocked(id)
	if j == nil || j.Repo != full {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"id": j.ID, "run_id": j.RunID, "name": j.JobName, "workflow_name": j.WorkflowName,
		"status": j.Status, "conclusion": j.Conclusion, "labels": j.Labels, "runner_name": j.RunnerName,
		"created_at": j.QueuedAt, "started_at": j.StartedAt, "completed_at": j.CompletedAt, "html_url": j.HTMLURL,
	})
}

package github

import (
	"crypto"
	"crypto/rand"
	"crypto/rsa"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"math/big"
	"net/http"
	"net/http/httptest"
	"time"
)

// fakeT is the part of *testing.T the fake issuer uses, so this production
// package does not import testing.
type fakeT interface {
	Helper()
	Fatal(args ...any)
	Cleanup(func())
}

// FakeActionsIssuer stands in for token.actions.githubusercontent.com: it
// publishes a key set and signs tokens with the matching private key, so the
// verifier is exercised end to end without the network.
type FakeActionsIssuer struct {
	URL string
	key *rsa.PrivateKey
}

func NewFakeActionsIssuer(t fakeT) *FakeActionsIssuer {
	t.Helper()
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		t.Fatal(err)
	}
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/.well-known/jwks" {
			http.NotFound(w, r)
			return
		}
		_ = json.NewEncoder(w).Encode(map[string]any{"keys": []map[string]string{{
			"kty": "RSA", "alg": "RS256", "use": "sig", "kid": "test",
			"n": base64.RawURLEncoding.EncodeToString(key.N.Bytes()),
			"e": base64.RawURLEncoding.EncodeToString(big.NewInt(int64(key.E)).Bytes()),
		}}})
	}))
	t.Cleanup(srv.Close)
	return &FakeActionsIssuer{URL: srv.URL, key: key}
}

// Sign mints a token with the given claims, defaulting the registered ones.
func (f *FakeActionsIssuer) Sign(t fakeT, claims map[string]any) string {
	t.Helper()
	now := time.Now()
	all := map[string]any{"iss": f.URL, "iat": now.Unix(), "nbf": now.Unix(), "exp": now.Add(5 * time.Minute).Unix(), "jti": "jti-" + now.Format(time.RFC3339Nano)}
	for k, v := range claims {
		all[k] = v
	}
	header, _ := json.Marshal(map[string]string{"alg": "RS256", "typ": "JWT", "kid": "test"})
	body, _ := json.Marshal(all)
	signing := base64.RawURLEncoding.EncodeToString(header) + "." + base64.RawURLEncoding.EncodeToString(body)
	digest := sha256.Sum256([]byte(signing))
	sig, err := rsa.SignPKCS1v15(rand.Reader, f.key, crypto.SHA256, digest[:])
	if err != nil {
		t.Fatal(err)
	}
	return signing + "." + base64.RawURLEncoding.EncodeToString(sig)
}

package github

import (
	"encoding/base64"
	"encoding/json"
	"net/http"
	"sort"
	"strconv"
	"strings"

	gh "github.com/google/go-github/v88/github"
)

// Git objects are immutable in the fake, too. Reads pinned to yesterday's
// commit must not see files somebody added to the default branch today.
type fakeContextGit struct {
	Trees                map[string]*gh.Tree
	Commits              map[string]*gh.Commit
	Blobs                map[string]string
	Modes                map[string]string
	Pulls                []*gh.PullRequest
	LoseNextPullResponse bool
}

func (r *fakeRepo) contextGit() *fakeContextGit {
	if r.git == nil {
		r.git = &fakeContextGit{Trees: map[string]*gh.Tree{}, Commits: map[string]*gh.Commit{}, Blobs: map[string]string{}, Modes: map[string]string{}}
	}
	return r.git
}

func (g *fakeContextGit) treeOf(files map[string]*gh.TreeEntry) *gh.Tree {
	groups := map[string]map[string]*gh.TreeEntry{}
	entries := []*gh.TreeEntry{}
	for p, e := range files {
		first, rest, nested := strings.Cut(p, "/")
		if !nested {
			copy := *e
			copy.Path = gh.Ptr(p)
			entries = append(entries, &copy)
			continue
		}
		if groups[first] == nil {
			groups[first] = map[string]*gh.TreeEntry{}
		}
		groups[first][rest] = e
	}
	for p, children := range groups {
		tree := g.treeOf(children)
		entries = append(entries, &gh.TreeEntry{Path: gh.Ptr(p), Type: gh.Ptr("tree"), Mode: gh.Ptr("040000"), SHA: tree.SHA})
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].GetPath() < entries[j].GetPath() })
	encoded, _ := json.Marshal(entries)
	sha := blobSHA(string(encoded))
	tree := &gh.Tree{SHA: gh.Ptr(sha), Entries: entries}
	g.Trees[sha] = tree
	return tree
}

func (g *fakeContextGit) flatten(sha string, prefix string, out map[string]*gh.TreeEntry) {
	tree := g.Trees[sha]
	if tree == nil {
		return
	}
	for _, e := range tree.Entries {
		p := prefix + e.GetPath()
		if e.GetType() == "tree" {
			g.flatten(e.GetSHA(), p+"/", out)
		} else {
			copy := *e
			copy.Path = gh.Ptr(p)
			out[p] = &copy
		}
	}
}

func (r *fakeRepo) pinContextSource() {
	g := r.contextGit()
	files := map[string]*gh.TreeEntry{}
	for p, c := range r.files {
		sha := blobSHA(c)
		g.Blobs[sha] = c
		mode := g.Modes[p]
		if mode == "" {
			mode = "100644"
		}
		files[p] = &gh.TreeEntry{Path: gh.Ptr(p), Mode: gh.Ptr(mode), Type: gh.Ptr("blob"), SHA: gh.Ptr(sha), Size: gh.Ptr(len(c))}
	}
	tree := g.treeOf(files)
	sha := blobSHA("source:" + tree.GetSHA())
	g.Commits[sha] = &gh.Commit{SHA: gh.Ptr(sha), Tree: tree, Message: gh.Ptr("Source commit")}
	r.branches[r.defaultBranch] = sha
}

func (f *FakeGitHub) SetFileMode(repo, path, mode string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.repoLocked(repo).contextGit().Modes[path] = mode
}

func (f *FakeGitHub) registerContextGitRoutes(mux *http.ServeMux) {
	mux.HandleFunc("GET /repos/{owner}/{repo}/git/commits/{sha}", f.contextGitRead)
	mux.HandleFunc("GET /repos/{owner}/{repo}/git/trees/{sha}", f.contextGitRead)
	mux.HandleFunc("GET /repos/{owner}/{repo}/git/blobs/{sha}", f.contextGitRead)
	mux.HandleFunc("POST /repos/{owner}/{repo}/git/trees", f.contextCreateTree)
	mux.HandleFunc("POST /repos/{owner}/{repo}/git/commits", f.contextCreateCommit)
	mux.HandleFunc("GET /repos/{owner}/{repo}/pulls", f.contextListPulls)
	mux.HandleFunc("GET /repos/{owner}/{repo}/pulls/{number}", f.contextGetPull)
	mux.HandleFunc("POST /repos/{owner}/{repo}/actions/workflows/{file}/dispatches", f.contextDispatch)
	f.registerContextRunRoutes(mux)
}

// contextDispatch answers a manual workflow run. Like the other Actions writes
// it needs the Actions write permission, and it answers 204 as GitHub does.
func (f *FakeGitHub) contextDispatch(w http.ResponseWriter, r *http.Request) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.permissions["actions"] != "write" {
		writeError(w, http.StatusForbidden, "Resource not accessible by integration")
		return
	}
	if f.contextDispatches == nil {
		f.contextDispatches = map[string]int{}
	}
	f.contextDispatches[fullName(r)+"/"+r.PathValue("file")]++
	w.WriteHeader(http.StatusNoContent)
}

// ContextDispatches is how many times the fake has been asked to run a
// repository's managed workflow by hand.
func (f *FakeGitHub) ContextDispatches(repo string) int {
	f.mu.Lock()
	defer f.mu.Unlock()
	n := 0
	for k, v := range f.contextDispatches {
		if strings.HasPrefix(k, repo+"/") {
			n += v
		}
	}
	return n
}

func (f *FakeGitHub) contextGitRead(w http.ResponseWriter, r *http.Request) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if !f.canReadContentsLocked() {
		writeError(w, 404, "Not Found")
		return
	}
	repo := f.repoLocked(fullName(r))
	g := repo.contextGit()
	sha := r.PathValue("sha")
	switch {
	case strings.Contains(r.URL.Path, "/git/commits/"):
		if obj := g.Commits[sha]; obj != nil {
			writeJSON(w, 200, obj)
			return
		}
	case strings.Contains(r.URL.Path, "/git/trees/"):
		// A tree can be addressed by a branch name as well as an object SHA.
		if sha == repo.defaultBranch {
			repo.pinContextSource()
		}
		if commit := g.Commits[repo.branches[sha]]; commit != nil {
			sha = commit.GetTree().GetSHA()
		}
		if obj := g.Trees[sha]; obj != nil {
			if r.URL.Query().Get("recursive") != "" {
				files := map[string]*gh.TreeEntry{}
				g.flatten(sha, "", files)
				flat := &gh.Tree{SHA: obj.SHA}
				for _, e := range files {
					flat.Entries = append(flat.Entries, e)
				}
				sort.Slice(flat.Entries, func(i, j int) bool { return flat.Entries[i].GetPath() < flat.Entries[j].GetPath() })
				writeJSON(w, 200, flat)
				return
			}
			writeJSON(w, 200, obj)
			return
		}
	case strings.Contains(r.URL.Path, "/git/blobs/"):
		if content, ok := g.Blobs[sha]; ok {
			writeJSON(w, 200, map[string]any{"sha": sha, "encoding": "base64", "size": len(content), "content": base64.StdEncoding.EncodeToString([]byte(content))})
			return
		}
	}
	writeError(w, 404, "Not Found")
}

func (f *FakeGitHub) contextCreateTree(w http.ResponseWriter, r *http.Request) {
	var in struct {
		Base    string          `json:"base_tree"`
		Entries []*gh.TreeEntry `json:"tree"`
	}
	if json.NewDecoder(r.Body).Decode(&in) != nil {
		writeError(w, 400, "invalid body")
		return
	}
	f.mu.Lock()
	defer f.mu.Unlock()
	repo := f.repoLocked(fullName(r))
	g := repo.contextGit()
	if repo.archived || f.permissions["contents"] != "write" {
		writeError(w, 403, "Missing Contents write")
		return
	}
	files := map[string]*gh.TreeEntry{}
	g.flatten(in.Base, "", files)
	for _, e := range in.Entries {
		if strings.HasPrefix(e.GetPath(), ".github/workflows/") && f.permissions["workflows"] != "write" {
			writeError(w, 403, "Missing Workflows write")
			return
		}
		if e.Content == nil && e.SHA == nil {
			delete(files, e.GetPath())
			continue
		}
		if e.Content != nil {
			sha := blobSHA(e.GetContent())
			g.Blobs[sha] = e.GetContent()
			e.SHA = gh.Ptr(sha)
			e.Size = gh.Ptr(len(e.GetContent()))
			e.Content = nil
		}
		files[e.GetPath()] = e
	}
	writeJSON(w, 201, g.treeOf(files))
}

func (f *FakeGitHub) contextCreateCommit(w http.ResponseWriter, r *http.Request) {
	var in struct {
		Message string   `json:"message"`
		Tree    string   `json:"tree"`
		Parents []string `json:"parents"`
	}
	if json.NewDecoder(r.Body).Decode(&in) != nil {
		writeError(w, 400, "invalid body")
		return
	}
	f.mu.Lock()
	defer f.mu.Unlock()
	repo := f.repoLocked(fullName(r))
	g := repo.contextGit()
	if repo.archived || f.permissions["contents"] != "write" {
		writeError(w, 403, "Missing Contents write")
		return
	}
	if g.Trees[in.Tree] == nil {
		writeError(w, 422, "unknown tree")
		return
	}
	encoded, _ := json.Marshal(in)
	sha := blobSHA(string(encoded))
	obj := &gh.Commit{SHA: gh.Ptr(sha), Message: gh.Ptr(in.Message), Tree: g.Trees[in.Tree]}
	for _, p := range in.Parents {
		obj.Parents = append(obj.Parents, &gh.Commit{SHA: gh.Ptr(p)})
	}
	g.Commits[sha] = obj
	writeJSON(w, 201, obj)
}

func (f *FakeGitHub) contextListPulls(w http.ResponseWriter, r *http.Request) {
	f.mu.Lock()
	defer f.mu.Unlock()
	var out []*gh.PullRequest
	for _, pr := range f.repoLocked(fullName(r)).contextGit().Pulls {
		_, head, _ := strings.Cut(r.URL.Query().Get("head"), ":")
		if pr.GetHead().GetRef() == head && pr.GetBase().GetRef() == r.URL.Query().Get("base") {
			out = append(out, pr)
		}
	}
	if out == nil {
		out = []*gh.PullRequest{}
	}
	writeJSON(w, 200, out)
}

func (f *FakeGitHub) LoseNextContextPullResponse(repo string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.repoLocked(repo).contextGit().LoseNextPullResponse = true
}

func (f *FakeGitHub) contextGetPull(w http.ResponseWriter, r *http.Request) {
	f.mu.Lock()
	defer f.mu.Unlock()
	number, _ := strconv.Atoi(r.PathValue("number"))
	for _, pr := range f.repoLocked(fullName(r)).contextGit().Pulls {
		if pr.GetNumber() == number {
			writeJSON(w, 200, pr)
			return
		}
	}
	writeError(w, 404, "Not Found")
}

// MergeContextPull models the reviewed setup becoming trusted branch content.
func (f *FakeGitHub) MergeContextPull(repo string, number int) bool {
	f.mu.Lock()
	defer f.mu.Unlock()
	r := f.repoLocked(repo)
	g := r.contextGit()
	for _, pr := range g.Pulls {
		if pr.GetNumber() != number {
			continue
		}
		commit := g.Commits[r.branches[pr.GetHead().GetRef()]]
		if commit == nil {
			return false
		}
		files := map[string]*gh.TreeEntry{}
		g.flatten(commit.GetTree().GetSHA(), "", files)
		r.files = map[string]string{}
		for p, e := range files {
			r.files[p] = g.Blobs[e.GetSHA()]
			g.Modes[p] = e.GetMode()
		}
		r.pinContextSource()
		pr.Merged = gh.Ptr(true)
		pr.State = gh.Ptr("closed")
		pr.MergeCommitSHA = gh.Ptr(r.branches[r.defaultBranch])
		return true
	}
	return false
}

// SetContextBranch publishes complete immutable objects without touching source.
func (f *FakeGitHub) SetContextBranch(repo, branch string, contents map[string]string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	r := f.repoLocked(repo)
	g := r.contextGit()
	files := map[string]*gh.TreeEntry{}
	for p, c := range contents {
		sha := blobSHA(c)
		g.Blobs[sha] = c
		files[p] = &gh.TreeEntry{Path: gh.Ptr(p), Type: gh.Ptr("blob"), Mode: gh.Ptr("100644"), SHA: gh.Ptr(sha), Size: gh.Ptr(len(c))}
	}
	tree := g.treeOf(files)
	sha := blobSHA("publication:" + tree.GetSHA())
	g.Commits[sha] = &gh.Commit{SHA: gh.Ptr(sha), Tree: tree}
	r.branches[branch] = sha
}

package github

import (
	"net/http"
	"sort"
	"strconv"
	"time"
)

// What the fake knows about the managed AI Context workflow's runs. Unlike the
// fleet's jobs, which a test queues and the controller picks up, these are
// history: a test says what a run did, and the controller reads it back to
// explain why a repository's context is stale.

// FakeContextRun is one run of a repository's managed workflow.
type FakeContextRun struct {
	// Commit is the head commit the run was for.
	Commit string
	// Status is queued, in_progress or completed; empty means completed.
	Status     string
	Conclusion string
	// Finished is when the run ended; empty means now. A test that needs a
	// failure from hours ago says so here rather than waiting for it.
	Finished time.Time
	Jobs     []FakeContextJob
}

// FakeContextJob is one job of a run.
type FakeContextJob struct {
	Name       string
	Conclusion string
	Steps      []FakeContextStep
	// Log is the job's log. Empty means it has none, which GitHub answers with a
	// 404 for a job that never started.
	Log string
}

// FakeContextStep is one step of a job.
type FakeContextStep struct{ Name, Conclusion string }

// FakeArtifact is one artifact in a repository.
type FakeArtifact struct {
	Name    string
	Bytes   int64
	Expired bool
}

type fakeContextRun struct {
	id      int64
	repo    string
	created time.Time
	FakeContextRun
	jobIDs []int64
}

type fakeContextRuns struct {
	runs      []*fakeContextRun
	logs      map[int64]string
	artifacts map[string][]FakeArtifact
	// logAuth records the Authorization header of every log download, so a test
	// can show the installation's token is never sent to the log's address.
	logAuth []string
}

// AddContextRun records a run of repo's managed workflow and returns its id.
// Runs are listed newest first by id, so the order they were added is their age.
func (f *FakeGitHub) AddContextRun(repo string, run FakeContextRun) int64 {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.nextRunID++
	if run.Status == "" {
		run.Status = "completed"
	}
	if run.Finished.IsZero() {
		run.Finished = time.Now()
	}
	r := &fakeContextRun{id: f.nextRunID, repo: repo, created: run.Finished, FakeContextRun: run}
	if f.contextRuns.logs == nil {
		f.contextRuns.logs = map[int64]string{}
	}
	for _, j := range run.Jobs {
		f.nextJobID++
		r.jobIDs = append(r.jobIDs, f.nextJobID)
		if j.Log != "" {
			f.contextRuns.logs[f.nextJobID] = j.Log
		}
	}
	f.contextRuns.runs = append(f.contextRuns.runs, r)
	return r.id
}

// ContextRunJobID is the id of the i'th job of a run added with AddContextRun.
func (f *FakeGitHub) ContextRunJobID(runID int64, i int) int64 {
	f.mu.Lock()
	defer f.mu.Unlock()
	for _, r := range f.contextRuns.runs {
		if r.id == runID && i < len(r.jobIDs) {
			return r.jobIDs[i]
		}
	}
	return 0
}

// AddArtifacts adds artifacts to a repository.
func (f *FakeGitHub) AddArtifacts(repo string, artifacts ...FakeArtifact) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.contextRuns.artifacts == nil {
		f.contextRuns.artifacts = map[string][]FakeArtifact{}
	}
	f.contextRuns.artifacts[repo] = append(f.contextRuns.artifacts[repo], artifacts...)
}

// ContextLogAuthorizations is the Authorization header of each log download.
func (f *FakeGitHub) ContextLogAuthorizations() []string {
	f.mu.Lock()
	defer f.mu.Unlock()
	return append([]string(nil), f.contextRuns.logAuth...)
}

func (f *FakeGitHub) registerContextRunRoutes(mux *http.ServeMux) {
	mux.HandleFunc("GET /repos/{owner}/{repo}/actions/workflows/{file}/runs", f.contextListRuns)
	mux.HandleFunc("GET /repos/{owner}/{repo}/actions/jobs/{job}/logs", f.contextJobLogRedirect)
	mux.HandleFunc("GET /_logs/{job}", f.contextJobLog)
	mux.HandleFunc("GET /repos/{owner}/{repo}/actions/artifacts", f.contextListArtifacts)
}

// canReadActionsLocked is the Actions read permission, which write includes.
func (f *FakeGitHub) canReadActionsLocked() bool {
	level := f.permissions["actions"]
	return level == "read" || level == "write"
}

func (f *FakeGitHub) contextListRuns(w http.ResponseWriter, r *http.Request) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if !f.canReadActionsLocked() {
		writeError(w, http.StatusForbidden, "Resource not accessible by integration")
		return
	}
	full, head := fullName(r), r.URL.Query().Get("head_sha")
	var runs []*fakeContextRun
	for _, run := range f.contextRuns.runs {
		if run.repo == full && (head == "" || run.Commit == head) {
			runs = append(runs, run)
		}
	}
	sort.Slice(runs, func(i, j int) bool { return runs[i].id > runs[j].id })
	out := make([]map[string]any, 0, len(runs))
	for _, run := range runs {
		entry := map[string]any{
			"id": run.id, "status": run.Status, "head_sha": run.Commit, "event": "push",
			"html_url":   "https://github.example/" + full + "/actions/runs/" + strconv.FormatInt(run.id, 10),
			"created_at": run.created.UTC().Format(time.RFC3339), "updated_at": run.created.UTC().Format(time.RFC3339),
		}
		if run.Conclusion != "" {
			entry["conclusion"] = run.Conclusion
		}
		out = append(out, entry)
	}
	writeJSON(w, http.StatusOK, map[string]any{"total_count": len(out), "workflow_runs": out})
}

// writeContextRunJobsLocked answers the jobs of a managed-workflow run, and
// reports whether the run was one.
func (f *FakeGitHub) writeContextRunJobsLocked(w http.ResponseWriter, full string, runID int64) bool {
	for _, run := range f.contextRuns.runs {
		if run.id != runID || run.repo != full {
			continue
		}
		if !f.canReadActionsLocked() {
			writeError(w, http.StatusForbidden, "Resource not accessible by integration")
			return true
		}
		jobs := make([]map[string]any, 0, len(run.Jobs))
		for i, j := range run.Jobs {
			steps := make([]map[string]any, 0, len(j.Steps))
			for n, s := range j.Steps {
				step := map[string]any{"name": s.Name, "number": n + 1, "status": "completed"}
				if s.Conclusion != "" {
					step["conclusion"] = s.Conclusion
				}
				steps = append(steps, step)
			}
			job := map[string]any{"id": run.jobIDs[i], "run_id": run.id, "name": j.Name, "status": "completed", "steps": steps}
			if j.Conclusion != "" {
				job["conclusion"] = j.Conclusion
			}
			jobs = append(jobs, job)
		}
		writeJSON(w, http.StatusOK, map[string]any{"total_count": len(jobs), "jobs": jobs})
		return true
	}
	return false
}

// contextJobLogRedirect answers as GitHub does: a 302 to a pre-signed address
// on another host, not the log.
func (f *FakeGitHub) contextJobLogRedirect(w http.ResponseWriter, r *http.Request) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if !f.canReadActionsLocked() {
		writeError(w, http.StatusForbidden, "Resource not accessible by integration")
		return
	}
	job, _ := strconv.ParseInt(r.PathValue("job"), 10, 64)
	if _, ok := f.contextRuns.logs[job]; !ok {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	http.Redirect(w, r, f.srv.URL+"/_logs/"+r.PathValue("job"), http.StatusFound)
}

func (f *FakeGitHub) contextJobLog(w http.ResponseWriter, r *http.Request) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.contextRuns.logAuth = append(f.contextRuns.logAuth, r.Header.Get("Authorization"))
	job, _ := strconv.ParseInt(r.PathValue("job"), 10, 64)
	log, ok := f.contextRuns.logs[job]
	if !ok {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	w.Header().Set("Content-Type", "text/plain")
	_, _ = w.Write([]byte(log))
}

func (f *FakeGitHub) contextListArtifacts(w http.ResponseWriter, r *http.Request) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if !f.canReadActionsLocked() {
		writeError(w, http.StatusForbidden, "Resource not accessible by integration")
		return
	}
	all := f.contextRuns.artifacts[fullName(r)]
	page, _ := strconv.Atoi(r.URL.Query().Get("page"))
	size, _ := strconv.Atoi(r.URL.Query().Get("per_page"))
	if page < 1 {
		page = 1
	}
	if size < 1 {
		size = 30
	}
	lo, hi := min((page-1)*size, len(all)), min(page*size, len(all))
	out := make([]map[string]any, 0, hi-lo)
	for i, a := range all[lo:hi] {
		out = append(out, map[string]any{"id": lo + i + 1, "name": a.Name, "size_in_bytes": a.Bytes, "expired": a.Expired})
	}
	writeJSON(w, http.StatusOK, map[string]any{"total_count": len(all), "artifacts": out})
}

package github

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"net/http"
	"strconv"
)

// What the fake needs to be able to say for Kennel Club: whether a repository is
// public, and what started a run and where its head commit lives.

// fakeRunTrigger is what a run says about how it began.
type fakeRunTrigger struct {
	event string
	// headRepositoryID is zero for a run whose head repository has been deleted,
	// which GitHub reports as null.
	headRepositoryID int64
}

func triggerKey(repo string, runID int64) string { return repo + "#" + strconv.FormatInt(runID, 10) }

// SetVisibility says whether a repository is "public", "private" or "internal".
// A repository the fake has not been told about is private, which is what it
// has always answered.
func (f *FakeGitHub) SetVisibility(fullName, visibility string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.addRepoLocked(fullName)
	f.repoLocked(fullName).visibility = visibility
}

// RepositoryID is the numeric ID the fake gave a repository, so a test can say a
// run's head is in the same repository (the same ID) or in another (a different
// one).
func (f *FakeGitHub) RepositoryID(fullName string) int64 {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.addRepoLocked(fullName)
	return f.repoLocked(fullName).id
}

// SetRunTrigger gives a run the event that started it and the ID of the
// repository its head commit is in; zero means that repository was deleted. It
// makes the run readable even if no job of it was ever queued.
func (f *FakeGitHub) SetRunTrigger(repo string, runID int64, event string, headRepositoryID int64) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.addRepoLocked(repo)
	if f.runTriggers == nil {
		f.runTriggers = map[string]fakeRunTrigger{}
	}
	f.runTriggers[triggerKey(repo, runID)] = fakeRunTrigger{event: event, headRepositoryID: headRepositoryID}
}

// visibilityLocked is a repository's visibility, private unless told otherwise.
func (f *FakeGitHub) visibilityLocked(fullName string) string {
	if v := f.repoLocked(fullName).visibility; v != "" {
		return v
	}
	return "private"
}

// writeETagged answers like GitHub does for a resource it can revalidate: with
// an ETag, and with a 304 and no body when the caller already has this version.
// It must be called with f.mu held, as every handler is.
func (f *FakeGitHub) writeETagged(w http.ResponseWriter, r *http.Request, v any) {
	b, err := json.Marshal(v)
	if err != nil {
		writeError(w, http.StatusInternalServerError, err.Error())
		return
	}
	sum := sha256.Sum256(b)
	etag := `"` + hex.EncodeToString(sum[:8]) + `"`
	w.Header().Set("ETag", etag)
	if r.Header.Get("If-None-Match") == etag {
		f.notModified++
		w.WriteHeader(http.StatusNotModified)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	_, _ = w.Write(b)
}

// NotModified is how many requests the fake has answered with a 304, which is
// how a test shows a repeated read really did not cost a full response.
func (f *FakeGitHub) NotModified() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.notModified
}

package github

import (
	"fmt"
	"net/http"
	"strconv"
)

// What the fake needs to be able to say for the Kennel Club settings checks: a
// repository's Actions settings, the status checks a branch requires under
// classic protection, and the ones its rules require.
//
// Reading any of the Actions settings, or classic protection, needs the
// Administration read permission, and without it the fake answers 403 as GitHub
// does. The rules need only Metadata, which every App holds.

// FakeActionsSettings is what the fake answers for a repository's Actions
// settings. A repository it has not been told about has the read-only default
// token and the policy GitHub applies when nobody has changed it.
type FakeActionsSettings struct {
	// DefaultTokenWrite makes the default workflow token read and write.
	DefaultTokenWrite bool
	// ForkApproval is the approval policy word for a public repository; empty
	// is "first_time_contributors".
	ForkApproval string
	// The three answers for a private repository's fork pull requests.
	PrivateForkRuns, PrivateForkSecrets, PrivateForkWriteToken bool
}

// FakeRequiredCheck is a status check a branch requires. AppID is the app that
// must post it, and zero means any app.
type FakeRequiredCheck struct {
	Context string
	AppID   int64
}

type fakeKennelSettings struct {
	actions *FakeActionsSettings
	// classic maps a branch to its classic protection; absent is "Branch not
	// protected".
	classic map[string]*fakeClassicProtection
	// rules maps a branch to the required-check rules that apply to it, one entry
	// per rule.
	rules map[string][][]FakeRequiredCheck
}

type fakeClassicProtection struct {
	checks []FakeRequiredCheck
	// legacy answers only the deprecated list of contexts, which names no app.
	legacy bool
}

func (f *FakeGitHub) kennelSettingsLocked(repo string) *fakeKennelSettings {
	r := f.repoLocked(repo)
	if r.kennelSettings == nil {
		r.kennelSettings = &fakeKennelSettings{
			classic: map[string]*fakeClassicProtection{},
			rules:   map[string][][]FakeRequiredCheck{},
		}
	}
	return r.kennelSettings
}

// SetActionsSettings replaces what the fake answers for a repository's Actions
// settings.
func (f *FakeGitHub) SetActionsSettings(repo string, s FakeActionsSettings) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.addRepoLocked(repo)
	f.kennelSettingsLocked(repo).actions = &s
}

// SetBranchProtection gives a branch classic protection requiring these checks.
// With none, the branch is protected and requires nothing.
func (f *FakeGitHub) SetBranchProtection(repo, branch string, checks ...FakeRequiredCheck) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.addRepoLocked(repo)
	f.kennelSettingsLocked(repo).classic[branch] = &fakeClassicProtection{checks: checks}
}

// SetLegacyBranchProtection is SetBranchProtection answering only the deprecated
// list of contexts, which names no app, as an older protection rule does.
func (f *FakeGitHub) SetLegacyBranchProtection(repo, branch string, contexts ...string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.addRepoLocked(repo)
	var checks []FakeRequiredCheck
	for _, c := range contexts {
		checks = append(checks, FakeRequiredCheck{Context: c})
	}
	f.kennelSettingsLocked(repo).classic[branch] = &fakeClassicProtection{checks: checks, legacy: true}
}

// AddBranchRule adds one rule, requiring these checks, to the rules that apply
// to a branch. Call it again for another rule.
func (f *FakeGitHub) AddBranchRule(repo, branch string, checks ...FakeRequiredCheck) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.addRepoLocked(repo)
	ks := f.kennelSettingsLocked(repo)
	ks.rules[branch] = append(ks.rules[branch], checks)
}

// canReadAdministrationLocked is the Administration read permission, which write
// includes.
func (f *FakeGitHub) canReadAdministrationLocked() bool {
	level := f.permissions["administration"]
	return level == "read" || level == "write"
}

func (f *FakeGitHub) registerKennelSettingsRoutes(mux *http.ServeMux) {
	mux.HandleFunc("GET /repos/{owner}/{repo}/actions/permissions/workflow", f.getActionsWorkflowPermissions)
	mux.HandleFunc("GET /repos/{owner}/{repo}/actions/permissions/fork-pr-contributor-approval", f.getForkApprovalPolicy)
	mux.HandleFunc("GET /repos/{owner}/{repo}/actions/permissions/fork-pr-workflows-private-repos", f.getPrivateForkSettings)
	mux.HandleFunc("GET /repos/{owner}/{repo}/branches/{branch}/protection", f.getBranchProtection)
	mux.HandleFunc("GET /repos/{owner}/{repo}/rules/branches/{branch}", f.getBranchRules)
}

// actionsSettingsLocked is what the fake holds for a repository's Actions
// settings, or the defaults. It answers false, and has written the 403, when the
// App may not read Administration.
func (f *FakeGitHub) actionsSettingsLocked(w http.ResponseWriter, repo string) (FakeActionsSettings, bool) {
	if !f.canReadAdministrationLocked() {
		writeError(w, http.StatusForbidden, "Resource not accessible by integration")
		return FakeActionsSettings{}, false
	}
	if s := f.kennelSettingsLocked(repo).actions; s != nil {
		return *s, true
	}
	return FakeActionsSettings{}, true
}

func (f *FakeGitHub) getActionsWorkflowPermissions(w http.ResponseWriter, r *http.Request) {
	full, _ := target(r)
	f.mu.Lock()
	defer f.mu.Unlock()
	s, ok := f.actionsSettingsLocked(w, full)
	if !ok {
		return
	}
	level := "read"
	if s.DefaultTokenWrite {
		level = "write"
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"default_workflow_permissions":     level,
		"can_approve_pull_request_reviews": false,
	})
}

func (f *FakeGitHub) getForkApprovalPolicy(w http.ResponseWriter, r *http.Request) {
	full, _ := target(r)
	f.mu.Lock()
	defer f.mu.Unlock()
	s, ok := f.actionsSettingsLocked(w, full)
	if !ok {
		return
	}
	policy := s.ForkApproval
	if policy == "" {
		policy = "first_time_contributors"
	}
	writeJSON(w, http.StatusOK, map[string]any{"approval_policy": policy})
}

func (f *FakeGitHub) getPrivateForkSettings(w http.ResponseWriter, r *http.Request) {
	full, _ := target(r)
	f.mu.Lock()
	defer f.mu.Unlock()
	s, ok := f.actionsSettingsLocked(w, full)
	if !ok {
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"run_workflows_from_fork_pull_requests":  s.PrivateForkRuns,
		"send_write_tokens_to_workflows":         s.PrivateForkWriteToken,
		"send_secrets_and_variables":             s.PrivateForkSecrets,
		"require_approval_for_fork_pr_workflows": true,
	})
}

func (f *FakeGitHub) getBranchProtection(w http.ResponseWriter, r *http.Request) {
	full, _ := target(r)
	branch := r.PathValue("branch")
	f.mu.Lock()
	defer f.mu.Unlock()
	if !f.canReadAdministrationLocked() {
		writeError(w, http.StatusForbidden, "Resource not accessible by integration")
		return
	}
	p, ok := f.kennelSettingsLocked(full).classic[branch]
	if !ok {
		// Not a failure: this is how GitHub says a branch has no classic
		// protection, and the exact message is what go-github looks for.
		writeError(w, http.StatusNotFound, "Branch not protected")
		return
	}
	rsc := map[string]any{"strict": false}
	var contexts []string
	var checks []map[string]any
	for _, c := range p.checks {
		contexts = append(contexts, c.Context)
		var app any
		if c.AppID != 0 {
			app = c.AppID
		}
		checks = append(checks, map[string]any{"context": c.Context, "app_id": app})
	}
	if len(p.checks) > 0 {
		rsc["contexts"] = contexts
		if !p.legacy {
			rsc["checks"] = checks
		}
	}
	body := map[string]any{"url": "https://example.invalid/protection"}
	if len(p.checks) > 0 {
		body["required_status_checks"] = rsc
	}
	writeJSON(w, http.StatusOK, body)
}

func (f *FakeGitHub) getBranchRules(w http.ResponseWriter, r *http.Request) {
	full, _ := target(r)
	branch := r.PathValue("branch")
	f.mu.Lock()
	defer f.mu.Unlock()
	rules := f.kennelSettingsLocked(full).rules[branch]

	// GitHub pages this list, a hundred at most to a page.
	per, page := 30, 1
	if n, err := strconv.Atoi(r.URL.Query().Get("per_page")); err == nil && n > 0 && n <= 100 {
		per = n
	}
	if n, err := strconv.Atoi(r.URL.Query().Get("page")); err == nil && n > 0 {
		page = n
	}
	start := (page - 1) * per
	if start > len(rules) {
		start = len(rules)
	}
	end := start + per
	if end > len(rules) {
		end = len(rules)
	}
	out := make([]map[string]any, 0, end-start)
	for i, checks := range rules[start:end] {
		var rsc []map[string]any
		for _, c := range checks {
			var app any
			if c.AppID != 0 {
				app = c.AppID
			}
			rsc = append(rsc, map[string]any{"context": c.Context, "integration_id": app})
		}
		out = append(out, map[string]any{
			"type":                "required_status_checks",
			"ruleset_source_type": "Repository",
			"ruleset_source":      full,
			"ruleset_id":          start + i + 1,
			"parameters": map[string]any{
				"required_status_checks":               rsc,
				"strict_required_status_checks_policy": false,
			},
		})
	}
	if end < len(rules) {
		w.Header().Set("Link", fmt.Sprintf(`<http://%s%s?page=%d&per_page=%d>; rel="next"`, r.Host, r.URL.Path, page+1, per))
	}
	writeJSON(w, http.StatusOK, out)
}

package github

import (
	"crypto/sha1"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"maps"
	"net/http"
	"slices"
	"sort"
	"strings"
	"time"

	gh "github.com/google/go-github/v88/github"
)

// The fake's half of the migration surface: repository contents, refs and pull
// requests.
//
// It enforces the rules that actually bite when a migration goes wrong. A
// branch that already exists is a 422, not a silent overwrite. A file committed
// with a stale blob SHA is a 409, which is what stops the wizard from
// clobbering a change somebody pushed while the review screen was open. A
// repository with no .github/workflows is a 404 on the directory, which is the
// common case in a large organisation and must not read as a broken App.

// fakeRepo is one repository's contents, as far as the migration cares.
type fakeRepo struct {
	git *fakeContextGit
	// pushedAt is what the poller sorts repositories by; a queued job bumps it.
	pushedAt      time.Time
	defaultBranch string
	id            int64
	// archived makes the repository read-only, as GitHub does: every write
	// answers 403. It is here so a test can prove the migration never gets
	// that far rather than only that it survives the refusal.
	archived bool
	// visibility is "public", "private" or "internal"; empty is private.
	visibility string
	// files maps a repository-relative path to its contents.
	files map[string]string
	// branches maps a branch name to the commit it points at.
	branches map[string]string
	// pulls counts the pull requests opened, which is where the next number
	// comes from.
	pulls int
	// pullBodies keeps each pull request's body by number, so a test can read
	// what a reviewer would read.
	pullBodies map[int]string
	// kennelSettings is what the fake says about the repository's Actions
	// settings and branch protection; see fake_kennel_settings.go.
	kennelSettings *fakeKennelSettings
}

// AddWorkflow puts a workflow file in a repository, creating the repository if
// this is the first thing in it.
func (f *FakeGitHub) AddWorkflow(repo, path, content string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.addRepoLocked(repo)
	r := f.repoLocked(repo)
	r.files[path] = content
}

// AddFile puts any file in a repository, creating the repository if this is
// the first thing in it. It is AddWorkflow under a name that does not lie
// about a README.
func (f *FakeGitHub) AddFile(repo, path, content string) {
	f.AddWorkflow(repo, path, content)
}

// SetDefaultBranch names a repository's default branch. It is "main" until
// something says otherwise.
func (f *FakeGitHub) SetDefaultBranch(repo, branch string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.addRepoLocked(repo)
	r := f.repoLocked(repo)
	head := r.branches[r.defaultBranch]
	r.defaultBranch = branch
	r.branches = map[string]string{branch: head}
}

// SetArchived archives or unarchives a repository, creating it if this is the
// first thing said about it.
func (f *FakeGitHub) SetArchived(repo string, archived bool) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.addRepoLocked(repo)
	f.repoLocked(repo).archived = archived
}

// FileContent returns what a repository's file holds now, which is how a test
// checks what a migration actually committed.
func (f *FakeGitHub) FileContent(repo, path string) (string, bool) {
	f.mu.Lock()
	defer f.mu.Unlock()
	r, ok := f.contents[repo]
	if !ok {
		return "", false
	}
	content, ok := r.files[path]
	return content, ok
}

// PullRequestBody returns the body a pull request was opened with, or "" for
// one that was never opened.
func (f *FakeGitHub) PullRequestBody(repo string, number int) string {
	f.mu.Lock()
	defer f.mu.Unlock()
	r, ok := f.contents[repo]
	if !ok {
		return ""
	}
	return r.pullBodies[number]
}

// Branches returns a repository's branch names, sorted.
func (f *FakeGitHub) Branches(repo string) []string {
	f.mu.Lock()
	defer f.mu.Unlock()
	r, ok := f.contents[repo]
	if !ok {
		return nil
	}
	out := slices.Collect(maps.Keys(r.branches))
	sort.Strings(out)
	return out
}

// repoLocked returns the repository's contents, creating them on first use.
// The caller holds f.mu.
func (f *FakeGitHub) repoLocked(repo string) *fakeRepo {
	if f.contents == nil {
		f.contents = map[string]*fakeRepo{}
	}
	r, ok := f.contents[repo]
	if !ok {
		r = &fakeRepo{
			defaultBranch: "main",
			files:         map[string]string{},
			branches:      map[string]string{"main": blobSHA("commit:" + repo)},
		}
		f.contents[repo] = r
	}
	return r
}

// blobSHA uses Git's object identity so source verification exercises real hashes.
func blobSHA(content string) string {
	sum := sha1.Sum([]byte(fmt.Sprintf("blob %d\x00%s", len(content), content)))
	return hex.EncodeToString(sum[:])
}

func (f *FakeGitHub) registerMigrationRoutes(mux *http.ServeMux) {
	f.registerContextGitRoutes(mux)
	mux.HandleFunc("GET /repos/{owner}/{repo}", f.getRepo)
	mux.HandleFunc("GET /repos/{owner}/{repo}/contents/{path...}", f.getContents)
	mux.HandleFunc("PUT /repos/{owner}/{repo}/contents/{path...}", f.putContents)
	mux.HandleFunc("GET /repos/{owner}/{repo}/readme", f.getReadme)
	mux.HandleFunc("GET /repos/{owner}/{repo}/git/ref/{ref...}", f.getRef)
	mux.HandleFunc("POST /repos/{owner}/{repo}/git/refs", f.createRef)
	mux.HandleFunc("DELETE /repos/{owner}/{repo}/git/refs/{ref...}", f.deleteRef)
	mux.HandleFunc("POST /repos/{owner}/{repo}/pulls", f.createPull)
}

func fullName(r *http.Request) string {
	return r.PathValue("owner") + "/" + r.PathValue("repo")
}

func (f *FakeGitHub) getRepo(w http.ResponseWriter, r *http.Request) {
	full := fullName(r)
	f.mu.Lock()
	defer f.mu.Unlock()
	if !slices.Contains(f.repos, full) {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	repo := f.repoLocked(full)
	owner, name, _ := SplitTarget(full)
	f.writeETagged(w, r, map[string]any{
		"id":             repo.id,
		"full_name":      full,
		"name":           name,
		"owner":          map[string]any{"login": owner},
		"default_branch": repo.defaultBranch,
		"private":        f.visibilityLocked(full) != "public",
		"visibility":     f.visibilityLocked(full),
		"archived":       repo.archived,
		"html_url":       "https://github.com/" + full,
	})
}

func (f *FakeGitHub) getContents(w http.ResponseWriter, r *http.Request) {
	full := fullName(r)
	path := strings.Trim(r.PathValue("path"), "/")

	f.mu.Lock()
	defer f.mu.Unlock()
	// GitHub does not distinguish "you may not see this" from "it is not
	// there": an App without the Contents permission gets a 404, the same
	// answer as a repository with no .github/workflows. Answering 403 here
	// would make the fake kinder than GitHub is, and hide the confusion that
	// causes.
	if !slices.Contains(f.repos, full) || !f.canReadContentsLocked() {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	repo := f.repoLocked(full)

	if content, ok := repo.files[path]; ok {
		writeJSON(w, http.StatusOK, contentEntry(path, content))
		return
	}

	// A directory: everything one level below the prefix.
	prefix := path + "/"
	var entries []map[string]any
	for p, content := range repo.files {
		rest, ok := strings.CutPrefix(p, prefix)
		if !ok || strings.Contains(rest, "/") {
			continue
		}
		entries = append(entries, contentEntry(p, content))
	}
	if len(entries) == 0 {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	sort.Slice(entries, func(i, j int) bool {
		return entries[i]["path"].(string) < entries[j]["path"].(string)
	})
	writeJSON(w, http.StatusOK, entries)
}

// getReadme answers as GitHub does: the file at the repository root whose
// name is README in any case and with any extension, and a 404 when there is
// none. Which of several wins is GitHub's own preference order, so a test can
// prove the badge goes in the file people actually see.
func (f *FakeGitHub) getReadme(w http.ResponseWriter, r *http.Request) {
	full := fullName(r)

	f.mu.Lock()
	defer f.mu.Unlock()
	if !slices.Contains(f.repos, full) || !f.canReadContentsLocked() {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	repo := f.repoLocked(full)
	var names []string
	for p := range repo.files {
		if strings.Contains(p, "/") {
			continue
		}
		if base := strings.ToLower(p); base == "readme" || strings.HasPrefix(base, "readme.") {
			names = append(names, p)
		}
	}
	if len(names) == 0 {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	sort.Slice(names, func(i, j int) bool {
		return readmeRank(names[i]) < readmeRank(names[j]) || (readmeRank(names[i]) == readmeRank(names[j]) && names[i] < names[j])
	})
	writeJSON(w, http.StatusOK, contentEntry(names[0], repo.files[names[0]]))
}

// readmeRank orders README candidates the way GitHub prefers them: a Markdown
// one before any other markup, and markup before plain text.
func readmeRank(name string) int {
	switch strings.ToLower(name[strings.LastIndex(name, ".")+1:]) {
	case "md", "markdown":
		return 0
	case "rst", "adoc", "org", "textile":
		return 1
	}
	return 2
}

func contentEntry(path, content string) map[string]any {
	return map[string]any{
		"type":     "file",
		"name":     path[strings.LastIndex(path, "/")+1:],
		"path":     path,
		"sha":      blobSHA(content),
		"size":     len(content),
		"encoding": "base64",
		"content":  base64.StdEncoding.EncodeToString([]byte(content)),
	}
}

func (f *FakeGitHub) putContents(w http.ResponseWriter, r *http.Request) {
	full := fullName(r)
	path := strings.Trim(r.PathValue("path"), "/")

	var body struct {
		Message string `json:"message"`
		Content string `json:"content"`
		SHA     string `json:"sha"`
		Branch  string `json:"branch"`
	}
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		writeError(w, http.StatusBadRequest, "invalid body")
		return
	}
	decoded, err := base64.StdEncoding.DecodeString(body.Content)
	if err != nil {
		writeError(w, http.StatusBadRequest, "content is not base64")
		return
	}

	f.mu.Lock()
	defer f.mu.Unlock()
	if !slices.Contains(f.repos, full) {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	repo := f.repoLocked(full)
	if repo.archived {
		writeError(w, http.StatusForbidden, "Repository was archived so is read-only.")
		return
	}
	if body.Branch != "" {
		if _, ok := repo.branches[body.Branch]; !ok {
			writeError(w, http.StatusNotFound, "Branch "+body.Branch+" not found")
			return
		}
	}
	if body.Message == "" {
		writeError(w, http.StatusUnprocessableEntity, "message is required")
		return
	}
	existing, exists := repo.files[path]
	switch {
	case exists && body.SHA == "":
		writeError(w, http.StatusUnprocessableEntity, path+" exists; a sha is required to update it")
		return
	case exists && body.SHA != blobSHA(existing):
		// The real failure this guards: somebody pushed to the file between the
		// wizard reading it and the operator approving the migration.
		writeError(w, http.StatusConflict, path+" has changed since it was read")
		return
	}
	repo.files[path] = string(decoded)
	writeJSON(w, http.StatusOK, map[string]any{
		"content": contentEntry(path, string(decoded)),
		"commit":  map[string]any{"sha": blobSHA(body.Message + string(decoded))},
	})
}

func (f *FakeGitHub) getRef(w http.ResponseWriter, r *http.Request) {
	full := fullName(r)
	ref := strings.Trim(r.PathValue("ref"), "/")
	branch := strings.TrimPrefix(ref, "heads/")

	f.mu.Lock()
	defer f.mu.Unlock()
	if !slices.Contains(f.repos, full) {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	repo := f.repoLocked(full)
	if branch == repo.defaultBranch {
		repo.pinContextSource()
	}
	sha, ok := repo.branches[branch]
	if !ok {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"ref":    "refs/heads/" + branch,
		"object": map[string]any{"sha": sha, "type": "commit"},
	})
}

func (f *FakeGitHub) createRef(w http.ResponseWriter, r *http.Request) {
	full := fullName(r)
	var body struct {
		Ref string `json:"ref"`
		SHA string `json:"sha"`
	}
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		writeError(w, http.StatusBadRequest, "invalid body")
		return
	}
	branch := strings.TrimPrefix(strings.TrimPrefix(body.Ref, "refs/"), "heads/")

	f.mu.Lock()
	defer f.mu.Unlock()
	if !slices.Contains(f.repos, full) {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	repo := f.repoLocked(full)
	if repo.archived {
		writeError(w, http.StatusForbidden, "Repository was archived so is read-only.")
		return
	}
	if branch == "" || body.SHA == "" {
		writeError(w, http.StatusUnprocessableEntity, "ref and sha are required")
		return
	}
	if _, exists := repo.branches[branch]; exists {
		writeError(w, http.StatusUnprocessableEntity, "Reference already exists")
		return
	}
	repo.branches[branch] = body.SHA
	writeJSON(w, http.StatusCreated, map[string]any{
		"ref":    "refs/heads/" + branch,
		"object": map[string]any{"sha": body.SHA, "type": "commit"},
	})
}

// deleteRef removes a branch. Like GitHub it refuses the default branch, and it
// does not close or forget pull requests: the real API closes a pull request
// whose head branch is deleted, which is why the migration only cleans up a
// branch it knows has none.
func (f *FakeGitHub) deleteRef(w http.ResponseWriter, r *http.Request) {
	full := fullName(r)
	branch := strings.TrimPrefix(strings.Trim(r.PathValue("ref"), "/"), "heads/")

	f.mu.Lock()
	defer f.mu.Unlock()
	if !slices.Contains(f.repos, full) {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	repo := f.repoLocked(full)
	if repo.archived {
		writeError(w, http.StatusForbidden, "Repository was archived so is read-only.")
		return
	}
	if _, ok := repo.branches[branch]; !ok {
		writeError(w, http.StatusUnprocessableEntity, "Reference does not exist")
		return
	}
	if branch == repo.defaultBranch {
		writeError(w, http.StatusUnprocessableEntity, "Cannot delete the default branch")
		return
	}
	delete(repo.branches, branch)
	w.WriteHeader(http.StatusNoContent)
}

func (f *FakeGitHub) createPull(w http.ResponseWriter, r *http.Request) {
	full := fullName(r)
	var body struct {
		Title string `json:"title"`
		Draft bool   `json:"draft"`
		Body  string `json:"body"`
		Head  string `json:"head"`
		Base  string `json:"base"`
	}
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		writeError(w, http.StatusBadRequest, "invalid body")
		return
	}

	f.mu.Lock()
	defer f.mu.Unlock()
	if !slices.Contains(f.repos, full) {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	repo := f.repoLocked(full)
	if repo.archived {
		writeError(w, http.StatusForbidden, "Repository was archived so is read-only.")
		return
	}
	for _, branch := range []string{body.Head, body.Base} {
		if _, ok := repo.branches[branch]; !ok {
			writeError(w, http.StatusUnprocessableEntity, "Branch "+branch+" not found")
			return
		}
	}
	if strings.TrimSpace(body.Title) == "" {
		writeError(w, http.StatusUnprocessableEntity, "title is required")
		return
	}
	repo.pulls++
	number := repo.pulls
	if repo.pullBodies == nil {
		repo.pullBodies = map[int]string{}
	}
	repo.pullBodies[number] = body.Body
	repo.contextGit().Pulls = append(repo.contextGit().Pulls, &gh.PullRequest{Draft: gh.Ptr(body.Draft), Number: gh.Ptr(number), Title: gh.Ptr(body.Title), Body: gh.Ptr(body.Body), State: gh.Ptr("open"), Head: &gh.PullRequestBranch{Ref: gh.Ptr(body.Head)}, Base: &gh.PullRequestBranch{Ref: gh.Ptr(body.Base)}, HTMLURL: gh.Ptr(fmt.Sprintf("https://github.com/%s/pull/%d", full, number))})
	if repo.contextGit().LoseNextPullResponse {
		repo.contextGit().LoseNextPullResponse = false
		writeError(w, http.StatusBadGateway, "Response lost after opening pull request")
		return
	}
	writeJSON(w, http.StatusCreated, map[string]any{
		"number":   number,
		"title":    body.Title,
		"body":     body.Body,
		"head":     map[string]any{"ref": body.Head},
		"base":     map[string]any{"ref": body.Base},
		"html_url": fmt.Sprintf("https://github.com/%s/pull/%d", full, number),
	})
}

// canReadContentsLocked reports whether the App this fake describes was granted
// the Contents permission. The caller holds f.mu.
func (f *FakeGitHub) canReadContentsLocked() bool {
	switch f.permissions["contents"] {
	case "read", "write":
		return true
	}
	return false
}

package github

import (
	"context"
	"fmt"
	"slices"
	"sort"
	"strings"

	"github.com/eyupio/zoomies/internal/agentguidance"
)

type KennelGuidanceReader interface {
	KennelGuidanceInventory(context.Context, string, string) (*KennelGuidanceInventory, error)
	KennelWorkflowBlob(context.Context, string, WorkflowFileRef) ([]byte, error)
}

type KennelGuidanceInventory struct {
	Paths       []string
	Files       []WorkflowFileRef
	Skipped     []WorkflowFileRef
	Partial     bool
	TreePartial bool
}

func (c *appClient) KennelGuidanceInventory(ctx context.Context, repo, branch string) (*KennelGuidanceInventory, error) {
	owner, name, err := splitRepo(repo)
	if err != nil {
		return nil, err
	}
	if branch == "" {
		return nil, fmt.Errorf("github: repository has no default branch")
	}
	tree, resp, err := c.readClient().Git.GetTree(ctx, owner, name, branch, true)
	if err != nil {
		return nil, c.fail("read agent guidance inventory", resp, err)
	}
	if tree == nil || !workflowSHA.MatchString(tree.GetSHA()) {
		return nil, fmt.Errorf("github: guidance tree has no identity")
	}
	out := &KennelGuidanceInventory{Partial: tree.GetTruncated(), TreePartial: tree.GetTruncated()}
	entries := slices.Clone(tree.Entries)
	sort.Slice(entries, func(i, j int) bool { return entries[i].GetPath() < entries[j].GetPath() })
	if len(entries) > 10000 {
		entries = entries[:10000]
		out.Partial = true
		out.TreePartial = true
	}
	for _, e := range entries {
		p := e.GetPath()

		regular := e.GetType() == "blob" && (e.GetMode() == "100644" || e.GetMode() == "100755")
		if regular || e.GetType() == "tree" && e.GetMode() == "040000" {
			out.Paths = append(out.Paths, p)
		}
		if !agentguidance.Recognised(p) {
			continue
		}
		ref := WorkflowFileRef{Path: p, SHA: strings.ToLower(e.GetSHA()), Size: e.GetSize()}
		if !agentguidance.SafePath(p) || !regular || !workflowSHA.MatchString(ref.SHA) || ref.Size <= 0 || ref.Size > agentguidance.MaxBytes || len(out.Files) >= agentguidance.MaxFiles {
			out.Skipped = append(out.Skipped, ref)
			out.Partial = true
			continue
		}
		out.Files = append(out.Files, ref)
	}
	return out, nil
}

package github

import (
	"errors"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/agentguidance"
	"github.com/eyupio/zoomies/internal/aicontext"
	"github.com/eyupio/zoomies/internal/store"
)

func TestGuidanceInventoryReadsOnlyBoundedImmutableInstructionBlobs(t *testing.T) {
	f := newFake(t)
	f.AddFile("acme/api", "AGENTS.md", "# Rules\n")
	f.AddFile("acme/api", ".claude/CLAUDE.md", "@../AGENTS.md\n")
	f.AddFile("acme/api", "src/AGENTS.md", strings.Repeat("x", agentguidance.MaxBytes+1))
	f.AddFile("acme/api", "empty/CLAUDE.md", "")
	f.AddFile("acme/api", "link/AGENTS.md", "elsewhere")
	f.SetFileMode("acme/api", "link/AGENTS.md", "120000")
	reader := f.Client("acme", store.TargetOrg).(KennelGuidanceReader)
	inv, err := reader.KennelGuidanceInventory(t.Context(), "acme/api", "main")
	if err != nil {
		t.Fatal(err)
	}
	if !inv.Partial || len(inv.Files) != 2 || len(inv.Skipped) != 3 {
		t.Fatalf("inventory=%+v", inv)
	}
	if _, err := reader.KennelWorkflowBlob(t.Context(), "acme/api", inv.Files[0]); err != nil {
		t.Fatal(err)
	}
	if _, err := f.Client("acme", store.TargetOrg).(AgentGuidanceClient).ReadAgentGuidance(t.Context(), "acme/api", ""); !errors.Is(err, ErrSetupConflict) {
		t.Fatalf("incomplete proposal accepted: %v", err)
	}
}

func TestGuidanceProposalsAreDraftAndNeedNoWorkflowWritePermission(t *testing.T) {
	f := newFake(t)
	f.AddFile("acme/api", "AGENTS.md", "# Rules\n")
	f.AddFile("acme/api", "CLAUDE.md", "# Rules\n")
	f.SetPermissions(map[string]string{"contents": "write", "pull_requests": "write"})
	client := f.Client("acme", store.TargetOrg).(AgentGuidanceClient)
	source, err := client.ReadAgentGuidance(t.Context(), "acme/api", "")
	if err != nil {
		t.Fatal(err)
	}
	req := ContextSetupRequest{Action: "agent-guidance", Repo: "acme/api", Base: "main", BaseCommit: source.Commit, Head: "zoomies-agent-guidance-test", PlanHash: strings.Repeat("a", 64), Files: []aicontext.SetupChange{{Path: "CLAUDE.md", Mode: "100644", Content: "@AGENTS.md\n"}}}
	pr, err := client.OpenContextSetup(t.Context(), req)
	if err != nil {
		t.Fatal(err)
	}
	f.mu.Lock()
	pull := f.repoLocked("acme/api").contextGit().Pulls[0]
	isDraft := pull.GetDraft()
	f.mu.Unlock()
	if !isDraft {
		t.Fatal("guidance proposal was not a draft")
	}
	again, err := client.OpenContextSetup(t.Context(), req)
	if err != nil || pr.Number != again.Number {
		t.Fatalf("retry=%+v %v", again, err)
	}
}

package github

import (
	"context"
	"fmt"

	"github.com/eyupio/zoomies/internal/store"
)

// RepoReader is everything Kennel Club asks GitHub, and it is read-only by
// construction: there is no method on it that writes, so no change to the
// controller can make Kennel Club write through it. It is not part of Client,
// for the reason ContextRunReader is not: a capability one feature uses does not
// belong on the interface every fake and every demo client has to satisfy, so
// the controller asks for it by type assertion and a client without it simply
// has no Kennel Club coverage to report.
type RepoReader interface {
	// KennelRepositories lists the repositories the installation can see, through
	// the conditional client: Kennel Club asks again every refresh, and a listing
	// GitHub says is unchanged costs nothing against the rate limit.
	KennelRepositories(ctx context.Context, limit int) ([]Repository, error)
	// KennelRun reads four fields of one workflow run, and no others.
	KennelRun(ctx context.Context, repo string, runID int64) (*KennelRun, error)
}

var _ RepoReader = (*appClient)(nil)

// KennelEndpoints are the GitHub endpoints Kennel Club may call, in
// the form its documentation lists them. A test runs the reader against the fake
// and fails on any request that is not one of these, so a new call is a visible
// change to this list in review rather than something found in a log.
var KennelEndpoints = []string{
	"GET /installation/repositories",
	"GET /repos/{owner}/{repo}",
	"GET /repos/{owner}/{repo}/actions/runs/{run}",
	"GET /orgs/{org}/actions/runner-groups",
	// The budget is a share of the limit the installation reports, and this is
	// how it reports it. GitHub does not count the request against the limit.
	"GET /rate_limit",
	// Optional repository setup reads only the default-branch file inventory.
	"GET /repos/{owner}/{repo}/git/trees/{tree}",
	"GET /repos/{owner}/{repo}/git/blobs/{blob}",
	// The optional settings reads. A public repository has an approval policy for
	// fork pull requests and a private one has the rules for them, so each
	// repository makes one of the two. Rules need only Metadata; everything else
	// here needs the App's Administration read permission.
	"GET /repos/{owner}/{repo}/actions/permissions/workflow",
	"GET /repos/{owner}/{repo}/actions/permissions/fork-pr-contributor-approval",
	"GET /repos/{owner}/{repo}/actions/permissions/fork-pr-workflows-private-repos",
	"GET /repos/{owner}/{repo}/branches/{branch}/protection",
	"GET /repos/{owner}/{repo}/rules/branches/{branch}",
}

// KennelRun is the four fields of a workflow run that the exposure checks read.
// Everything else on a run -- who triggered it, its branch, its title, the path
// of its workflow -- is written by whoever opened the pull request, and is never
// read, so there is nothing of theirs to leak.
type KennelRun struct {
	ID int64
	// Event is GitHub's name for what triggered the run, bounded to 64 bytes. The
	// controller passes it through an allow-list before anything sees it.
	Event string
	// RepositoryID is the repository the run ran in; HeadRepositoryID is the one
	// its head commit is in. They differ for a pull request from a fork, and a
	// fork that has since been deleted has no head repository at all, which reads
	// as zero.
	RepositoryID     int64
	HeadRepositoryID int64
}

// FromFork says whether the run's head is somewhere other than where it ran. A
// deleted fork is still a fork: the code in it was written by somebody else.
func (r KennelRun) FromFork() bool { return r.HeadRepositoryID != r.RepositoryID }

// maxKennelEvent bounds the event name a run may carry into the controller.
const maxKennelEvent = 64

func (c *appClient) KennelRepositories(ctx context.Context, limit int) ([]Repository, error) {
	return c.listRepositories(ctx, c.readClient(), limit)
}

func (c *appClient) KennelRun(ctx context.Context, repo string, runID int64) (*KennelRun, error) {
	owner, name, kind := SplitTarget(repo)
	if kind != store.TargetRepo || runID <= 0 {
		return nil, fmt.Errorf("github: invalid workflow run %q/%d", repo, runID)
	}
	run, resp, err := c.readClient().Actions.GetWorkflowRunByID(ctx, owner, name, runID)
	if err != nil {
		return nil, c.fail("read workflow run", resp, err)
	}
	base := run.GetRepository().GetID()
	if base == 0 {
		// A run whose repository GitHub did not name cannot be compared with
		// its head, and guessing would be reporting a fork from nothing.
		return nil, fmt.Errorf("github: read workflow run %s/%d: GitHub did not say which repository it ran in", repo, runID)
	}
	event := run.GetEvent()
	if len(event) > maxKennelEvent {
		event = event[:maxKennelEvent]
	}
	return &KennelRun{
		ID:               runID,
		Event:            event,
		RepositoryID:     base,
		HeadRepositoryID: run.GetHeadRepository().GetID(),
	}, nil
}

package github

