		t.Errorf("before %+v, after %+v, %v", before, after, err)
	}
}

var idSegment = regexp.MustCompile(`/\d+`)

// normaliseKennelRequest turns a request the fake recorded into the form
// KennelEndpoints lists it in. It works by what a path is, not by where a
// segment falls, because the recorded path is the decoded one: a branch named
// release/1.0 is two segments there, and a fixed index would mistake the
// settings endpoints for runs.
func normaliseKennelRequest(req string) string {
	method, path, _ := strings.Cut(req, " ")
	path, _, _ = strings.Cut(path, "?")
	path = strings.TrimPrefix(path, "/api/v3")
	parts := strings.Split(strings.Trim(path, "/"), "/")
	switch {
	case len(parts) >= 3 && parts[0] == "repos":
		rest := parts[3:]
		switch {
		case len(rest) >= 3 && rest[0] == "actions" && rest[1] == "runs":
			rest = []string{"actions", "runs", "{run}"}
		case len(rest) >= 3 && rest[0] == "git" && (rest[1] == "trees" || rest[1] == "blobs"):
			rest = []string{"git", rest[1], "{" + strings.TrimSuffix(rest[1], "s") + "}"}
		case len(rest) >= 3 && rest[0] == "branches" && rest[len(rest)-1] == "protection":
			rest = []string{"branches", "{branch}", "protection"}
		case len(rest) >= 3 && rest[0] == "rules" && rest[1] == "branches":
			rest = []string{"rules", "branches", "{branch}"}
		}
		parts = append([]string{"repos", "{owner}", "{repo}"}, rest...)
	case len(parts) >= 2 && parts[0] == "orgs":
		parts[1] = "{org}"
	}
	norm := method + " /" + strings.Join(parts, "/")
	return idSegment.ReplaceAllString(norm, "/{n}")
}

// Kennel Club calls the endpoints it documents and no others, and none of them
// is a write. A call added later has to change KennelEndpoints in the same
// change, which is where a reviewer, and the operator who reads the permissions
// page, will see it.
func TestKennelClubCallsOnlyTheEndpointsItDocuments(t *testing.T) {
	f := newFake(t)
	f.SetVisibility("acme/api", "public")
	f.SetVisibility("acme/internal", "private")
	f.SetRunTrigger("acme/api", 5, "pull_request", f.RepositoryID("acme/api")+1)
	f.AddRunnerGroup("fleet")
	// A branch with a slash, protected and ruled, so the normaliser is held to
	// the shape that breaks a fixed index.
	f.SetBranchProtection("acme/api", "release/1.0", actions("test")...)
	f.AddBranchRule("acme/api", "release/1.0", actions("lint")...)
	ctx := context.Background()
	for _, tc := range []struct {
		target string
		kind   store.TargetType
	}{{"acme", store.TargetOrg}, {"acme/api", store.TargetRepo}} {
		c := f.Client(tc.target, tc.kind)
		r := c.(RepoReader)
		if _, err := r.KennelRepositories(ctx, 0); err != nil {
			t.Fatal(err)
		}
		if _, err := r.KennelRun(ctx, "acme/api", 5); err != nil {
			t.Fatal(err)
		}
		// Each repository makes the fork-policy read that is its own.
		sr := c.(KennelSettingsReader)
		if _, err := sr.KennelSettings(ctx, "acme/api", true); err != nil {
			t.Fatal(err)
		}
		if _, err := sr.KennelSettings(ctx, "acme/internal", false); err != nil {
			t.Fatal(err)
		}
		if _, err := sr.KennelProtection(ctx, "acme/api", "release/1.0"); err != nil {
			t.Fatal(err)
		}
		if tc.kind == store.TargetOrg {
			if _, err := c.ListRunnerGroups(ctx); err != nil {
				t.Fatal(err)
			}
		}
		// The budget is a share of what the installation reports, and this is how
		// it reports it.
		if _, err := c.RateLimit(ctx); err != nil {
			t.Fatal(err)
		}
	}
	allowed := map[string]bool{}
	for _, e := range KennelEndpoints {
		allowed[e] = true
	}
	seen := map[string]bool{}
	for _, req := range f.Requests() {
		norm := normaliseKennelRequest(req)
		if !allowed[norm] {
			t.Errorf("Kennel Club made a request it does not document: %s (normalised %s)", req, norm)
		}
		if !strings.HasPrefix(req, "GET ") {
			t.Errorf("Kennel Club made a request that is not a GET: %s", req)
		}
		seen[norm] = true
	}
	if len(seen) == 0 {
		t.Fatal("no requests were recorded; the test proves nothing")
	}
	// An endpoint listed and never reached is a list that has drifted from the
	// code, and it would widen what the operator is told without anything using
	// it. The tree and blob reads are reached by the workflow and setup tests.
	for _, e := range KennelEndpoints {
		if strings.Contains(e, "/git/") {
			continue
		}
		if !seen[e] {
			t.Errorf("%s is documented and this test never reached it", e)
		}
	}
}

package github

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"net/url"
	"sort"
	"strings"

	gh "github.com/google/go-github/v88/github"
)

// GitHubActionsAppID is the ID GitHub gives the app that posts a workflow job's
// check. A required status check is pinned to Actions when it names this app,
// and only then can the jobs the fleet saw say whether the check ever reports:
// a check that any app may post could come from somewhere the fleet cannot see.
const GitHubActionsAppID int64 = 15368

// kennelRulePages bounds the rules read for one branch: a hundred a page, five
// pages. A branch with more is read as far as that and marked partial, so a
// repository cannot make one refresh unbounded.
const kennelRulePages = 5

// kennelRequiredCap bounds how many required checks are kept for a branch. It
// is far above what a repository requires, and a repository over it is marked
// partial rather than stored whole.
const kennelRequiredCap = 100

// KennelSettingsReader is optional, like the other Kennel Club readers: a
// client without it gives no settings coverage and needs no new capability.
// Everything on it is a GET, and nothing on it can write a setting.
//
// Both methods need the App's Administration read permission, which GitHub
// offers no narrower form of, so it is asked for separately and only when the
// operator has switched the settings checks on.
type KennelSettingsReader interface {
	// KennelSettings reads the Actions settings that govern a workflow's token
	// and a fork's approval. public says which fork policy applies: a public
	// repository has an approval policy, and a private one has the rules for
	// fork pull requests. An internal repository is read as private.
	KennelSettings(ctx context.Context, repo string, public bool) (*KennelSettings, error)
	// KennelProtection reads the status checks a branch requires, from classic
	// branch protection and from the rules that apply to the branch. Both are
	// read, because a repository protected one way looks unprotected to a reader
	// of the other.
	KennelProtection(ctx context.Context, repo, branch string) (*KennelProtection, error)
}

var _ KennelSettingsReader = (*appClient)(nil)

// KennelSettings is the part of a repository's Actions settings that Kennel Club
// judges, as booleans and one policy word. Nothing a repository wrote is in it.
type KennelSettings struct {
	// DefaultTokenWrite is true when the default workflow token can write.
	DefaultTokenWrite bool
	// ForkApproval is GitHub's approval policy for a fork pull request from an
	// outside contributor, for a public repository. It is empty when the policy
	// was not read: a private repository, or a GitHub that lacks the endpoint.
	ForkApproval string
	// PrivateFork says what a private repository does with fork pull requests.
	// It is nil for a public repository and when GitHub lacks the endpoint.
	PrivateFork *KennelPrivateFork
	// Partial is set when an endpoint this GitHub does not offer was left out, so
	// a finding that needed it cannot be judged.
	Partial bool
}

// KennelPrivateFork is a private repository's policy for fork pull requests.
type KennelPrivateFork struct {
	// Runs is true when fork pull requests run workflows at all.
	Runs bool
	// Secrets is true when they are given the repository's secrets and variables.
	Secrets bool
	// WriteToken is true when they are given a token that can write.
	WriteToken bool
}

// KennelProtection is the required status checks of one branch.
type KennelProtection struct {
	// Required are the checks pinned to the GitHub Actions app, from every source
	// that requires them, sorted and without repeats. They are names a
	// repository chose, so the controller compares them with job names and keeps
	// them out of every sentence.
	Required []string
	// Unpinned counts the required checks that name no app or another one, or
	// that one source leaves open to any app. They are counted and never judged.
	Unpinned int
	// Partial is set when one half could not be read or a limit was reached, so
	// the list may be short.
	Partial bool
}

func (c *appClient) KennelSettings(ctx context.Context, repo string, public bool) (*KennelSettings, error) {
	owner, name, err := splitRepo(repo)
	if err != nil {
		return nil, err
	}
	rc := c.readClient()
	wf, resp, err := rc.Repositories.GetDefaultWorkflowPermissions(ctx, owner, name)
	if err != nil {
		return nil, c.failAdministration("read the default workflow permissions", resp, err)
	}
	out := &KennelSettings{DefaultTokenWrite: wf.GetDefaultWorkflowPermissions() == "write"}
	if public {
		ap, resp, err := rc.Actions.GetForkPRContributorApprovalPermissions(ctx, owner, name)
		switch {
		case err == nil:
			out.ForkApproval = ap.ApprovalPolicy
		case kennelEndpointMissing(resp, err):
			out.Partial = true
		default:
			return nil, c.failAdministration("read the fork pull request approval policy", resp, err)
		}
		return out, nil
	}
	pf, resp, err := rc.Repositories.GetPrivateRepoForkPRWorkflowSettings(ctx, owner, name)
	switch {
	case err == nil:
		out.PrivateFork = &KennelPrivateFork{
			Runs:       pf.GetRunWorkflowsFromForkPullRequests(),
			Secrets:    pf.GetSendSecretsAndVariables(),
			WriteToken: pf.GetSendWriteTokensToWorkflows(),
		}
	case kennelEndpointMissing(resp, err):
		out.Partial = true
	default:
		return nil, c.failAdministration("read the fork pull request settings", resp, err)
	}
	return out, nil
}

func (c *appClient) KennelProtection(ctx context.Context, repo, branch string) (*KennelProtection, error) {
	owner, name, err := splitRepo(repo)
	if err != nil {
		return nil, err
	}
	if branch == "" {
		return nil, fmt.Errorf("github: repository has no default branch")
	}
	rc := c.readClient()
	// A context is pinned only if every source that requires it pins it to
	// Actions: one source that lets any app post it is enough for the check to
	// come from somewhere the fleet cannot see.
	pinned := map[string]bool{}
	note := func(check string, appID *int64) {
		check = strings.TrimSpace(check)
		if check == "" {
			return
		}
		ok := appID != nil && *appID == GitHubActionsAppID
		if prev, seen := pinned[check]; seen {
			pinned[check] = prev && ok
			return
		}
		pinned[check] = ok
	}
	out := &KennelProtection{}

	classicDenied, rulesDenied := false, false
	var classicErr error

	prot, resp, err := rc.Repositories.GetBranchProtection(ctx, owner, name, branch)
	switch {
	case err == nil:
		if rsc := prot.GetRequiredStatusChecks(); rsc != nil {
			if rsc.Checks != nil {
				for _, ck := range *rsc.Checks {
					if ck != nil {
						note(ck.Context, ck.AppID)
					}
				}
			} else if rsc.Contexts != nil {
				// The deprecated form names no app at all.
				for _, name := range *rsc.Contexts {
					note(name, nil)
				}
			}
		}
	case errors.Is(err, gh.ErrBranchNotProtected):
		// Normal, and not a failure: classic protection answers 404 "Branch not
		// protected" for a branch that has none, and the rules may still require
		// checks of it.
	case kennelStatus(resp, err) == http.StatusForbidden:
		classicDenied = true
		classicErr = c.failAdministration("read the branch protection", resp, err)
	default:
		return nil, c.failAdministration("read the branch protection", resp, err)
	}

	// go-github escapes the branch name for classic protection and does not for
	// the rules, and a slash in a branch name is one segment to GitHub, not two,
	// so the rules read is given the name already escaped.
	escaped := url.PathEscape(branch)
	opts := &gh.ListOptions{PerPage: 100}
	for page := 0; page < kennelRulePages; page++ {
		rules, resp, err := rc.Repositories.ListRulesForBranch(ctx, owner, name, escaped, opts)
		if err != nil {
			switch {
			case kennelEndpointMissing(resp, err):
				// A GitHub without rules has none that require anything.
			case kennelStatus(resp, err) == http.StatusForbidden:
				rulesDenied = true
			default:
				return nil, c.fail("read the rules for the branch", resp, err)
			}
			break
		}
		for _, rule := range rules.RequiredStatusChecks {
			if rule == nil {
				continue
			}
			for _, ck := range rule.Parameters.RequiredStatusChecks {
				if ck != nil {
					note(ck.Context, ck.IntegrationID)
				}
			}
		}
		if resp.NextPage == 0 {
			break
		}
		if page == kennelRulePages-1 {
			out.Partial = true
		}
		opts.Page = resp.NextPage
	}

	switch {
	case classicDenied && rulesDenied:
		return nil, classicErr
	case classicDenied:
		out.Partial = true
	case rulesDenied:
		out.Partial = true
	}

	for check, ok := range pinned {
		if !ok {
			out.Unpinned++
			continue
		}
		out.Required = append(out.Required, check)
	}
	sort.Strings(out.Required)
	if len(out.Required) > kennelRequiredCap {
		out.Required = out.Required[:kennelRequiredCap]
		out.Partial = true
	}
	return out, nil
}

// failAdministration is fail for a read that needs the Administration read
// permission. The shared hint on a 403 talks about runner permissions, which
// would send an operator to the wrong checkbox.
func (c *appClient) failAdministration(op string, resp *gh.Response, err error) error {
	e := classify(resp, err)
	if errors.Is(e, ErrForbidden) {
		return fmt.Errorf("github: %s: %w; the App installation on %s needs the \"Administration\" (administration) "+
			"read permission, which is optional, and changing permissions needs the installation to accept them",
			op, e, c.target)
	}
	return errorf(op, e)
}

// kennelStatus is the HTTP status of a failed go-github call, or zero.
func kennelStatus(resp *gh.Response, err error) int {
	var er *gh.ErrorResponse
	if errors.As(err, &er) && er.Response != nil {
		return er.Response.StatusCode
	}
	if resp != nil && resp.Response != nil {
		return resp.StatusCode
	}
	return 0
}

// kennelEndpointMissing is a 404 or a 405: a GitHub that does not offer the
// endpoint, which on an older server is a fact about the server and not a
// failure. The shared classify maps 404 and leaves 405 to fall through, and this
// is the one place that treats the two alike.
func kennelEndpointMissing(resp *gh.Response, err error) bool {
	switch kennelStatus(resp, err) {
	case http.StatusNotFound, http.StatusMethodNotAllowed:
		return true
	}
	return false
}

package github

import (
	"context"
	"errors"
	"fmt"
	"slices"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

func settingsReader(t *testing.T, f *FakeGitHub) KennelSettingsReader {
	t.Helper()
	r, ok := f.Client("acme", store.TargetOrg).(KennelSettingsReader)
	if !ok {
		t.Fatal("the client does not implement KennelSettingsReader")
	}
	return r
}

// withoutAdministration is an App that holds what the default App holds and
// nothing more: no Administration read.
func withoutAdministration(f *FakeGitHub) {
	f.SetPermissions(map[string]string{"actions": "read", "metadata": "read", "organization_self_hosted_runners": "write"})
}

// requestsTo is the requests the fake recorded whose path contains any of the
// words, so a test can say which of two endpoints a read reached for.
func requestsTo(f *FakeGitHub, words ...string) []string {
	var out []string
	for _, req := range f.Requests() {
		for _, w := range words {
			if strings.Contains(req, w) {
				out = append(out, req)
				break
			}
		}
	}
	return out
}

func noWrites(t *testing.T, f *FakeGitHub) {
	t.Helper()
	for _, req := range f.Requests() {
		if !strings.HasPrefix(req, "GET ") {
			t.Errorf("a settings read made a request that is not a GET: %s", req)
		}
	}
}

// A public repository has an approval policy for fork pull requests and a
// private one has the rules for them. Each makes the request that is its own and
// not the other, because the other is a request to an endpoint that does not
// describe it.
func TestAPublicRepositoryAsksForItsApprovalPolicyAndAPrivateOneForItsForkRules(t *testing.T) {
	f := newFake(t)
	f.SetActionsSettings("acme/pub", FakeActionsSettings{DefaultTokenWrite: true, ForkApproval: "first_time_contributors_new_to_github"})
	f.SetActionsSettings("acme/priv", FakeActionsSettings{PrivateForkRuns: true, PrivateForkSecrets: true})
	r := settingsReader(t, f)

	pub, err := r.KennelSettings(context.Background(), "acme/pub", true)
	if err != nil {
		t.Fatal(err)
	}
	if !pub.DefaultTokenWrite || pub.ForkApproval != "first_time_contributors_new_to_github" || pub.PrivateFork != nil || pub.Partial {
		t.Errorf("public settings = %+v", pub)
	}
	if got := requestsTo(f, "fork-pr-workflows-private-repos"); len(got) != 0 {
		t.Errorf("a public repository asked the private fork endpoint: %v", got)
	}

	priv, err := r.KennelSettings(context.Background(), "acme/priv", false)
	if err != nil {
		t.Fatal(err)
	}
	want := &KennelPrivateFork{Runs: true, Secrets: true, WriteToken: false}
	if priv.DefaultTokenWrite || priv.ForkApproval != "" || priv.PrivateFork == nil || *priv.PrivateFork != *want || priv.Partial {
		t.Errorf("private settings = %+v, fork %+v", priv, priv.PrivateFork)
	}
	if got := requestsTo(f, "acme/priv/actions/permissions/fork-pr-contributor-approval"); len(got) != 0 {
		t.Errorf("a private repository asked the approval policy: %v", got)
	}
	noWrites(t, f)
}

// A repository nobody has configured has the read-only token GitHub gives it.
func TestAnUnconfiguredRepositoryHasTheReadOnlyDefault(t *testing.T) {
	f := newFake(t)
	s, err := settingsReader(t, f).KennelSettings(context.Background(), "acme/api", true)
	if err != nil || s.DefaultTokenWrite {
		t.Errorf("settings = %+v, %v", s, err)
	}
}

// A 403 is the App not holding Administration read, and the error has to say
// that. The shared hint for a 403 sends an operator to the runner permissions,
// which are the wrong checkbox for this read.
func TestRefusedSettingsNameTheAdministrationPermissionAndNotTheRunnerOnes(t *testing.T) {
	f := newFake(t)
	withoutAdministration(f)
	r := settingsReader(t, f)
	for name, read := range map[string]func() error{
		"settings": func() error { _, err := r.KennelSettings(context.Background(), "acme/api", true); return err },
		"protection": func() error {
			f.SetError("rules/branches", 403, "Resource not accessible by integration")
			_, err := r.KennelProtection(context.Background(), "acme/api", "main")
			return err
		},
	} {
		err := read()
		if !errors.Is(err, ErrForbidden) {
			t.Errorf("%s: %v is not ErrForbidden", name, err)
			continue
		}
		if !strings.Contains(err.Error(), "Administration") {
			t.Errorf("%s: the error does not name the permission: %v", name, err)
		}
		if strings.Contains(err.Error(), "self_hosted_runners") || strings.Contains(err.Error(), "workflow_job") {
			t.Errorf("%s: the error sends the operator to the runner permissions: %v", name, err)
		}
	}
}

// The two fork-policy endpoints are newer than the rest, and a GitHub that lacks
// one is a fact about that server. The default token is still read and the
// repository is marked partial, so a finding that needed the missing answer is
// not judged and the one that did not is. A 405 is the same fact, and the shared
// classify would leave it as a failure retried every half hour.
func TestAMissingForkEndpointLeavesTheSettingsPartialAndNotFailed(t *testing.T) {
	for _, status := range []int{404, 405} {
		for _, public := range []bool{true, false} {
			t.Run(fmt.Sprintf("%d public=%v", status, public), func(t *testing.T) {
				f := newFake(t)
				f.SetActionsSettings("acme/api", FakeActionsSettings{DefaultTokenWrite: true})
				f.SetError("fork-pr-", status, "Not Found")
				s, err := settingsReader(t, f).KennelSettings(context.Background(), "acme/api", public)
				if err != nil {
					t.Fatalf("a missing fork endpoint failed the read: %v", err)
				}
				if !s.Partial || !s.DefaultTokenWrite || s.ForkApproval != "" || s.PrivateFork != nil {
					t.Errorf("settings = %+v, fork %+v", s, s.PrivateFork)
				}
			})
		}
	}
}

// The default token is the one answer every finding here rests on, so GitHub
// lacking it is a failure the controller reads as "not offered", not a quiet
// partial.
func TestAMissingWorkflowPermissionsEndpointFailsTheRead(t *testing.T) {
	f := newFake(t)
	f.SetError("permissions/workflow", 404, "Not Found")
	_, err := settingsReader(t, f).KennelSettings(context.Background(), "acme/api", true)
	if !errors.Is(err, ErrNotFound) {
		t.Errorf("err = %v, want ErrNotFound", err)
	}
	f = newFake(t)
	f.SetError("permissions/workflow", 500, "boom")
	if _, err := settingsReader(t, f).KennelSettings(context.Background(), "acme/api", true); err == nil {
		t.Error("a server error was read as settings")
	}
}

func actions(contexts ...string) []FakeRequiredCheck {
	var out []FakeRequiredCheck
	for _, c := range contexts {
		out = append(out, FakeRequiredCheck{Context: c, AppID: GitHubActionsAppID})
	}
	return out
}

func readProtection(t *testing.T, f *FakeGitHub, branch string) *KennelProtection {
	t.Helper()
	p, err := settingsReader(t, f).KennelProtection(context.Background(), "acme/api", branch)
	if err != nil {
		t.Fatalf("KennelProtection(%q): %v", branch, err)
	}
	return p
}

// Classic protection answers 404 "Branch not protected" when a branch has none.
// That is a normal answer and not a failure, and it is not the repository being
// missing: reading it as unavailable would hide every repository that is
// protected only by its rules.
func TestABranchWithNoClassicProtectionIsNotAFailure(t *testing.T) {
	f := newFake(t)
	p := readProtection(t, f, "main")
	if len(p.Required) != 0 || p.Unpinned != 0 || p.Partial {
		t.Errorf("an unprotected branch read as %+v", p)
	}
	if got := requestsTo(f, "/protection"); len(got) != 1 {
		t.Errorf("classic protection was read %d times: %v", len(got), got)
	}
}

// A repository protected only by rulesets looks unprotected to a reader of
// classic protection alone, and the reverse is true of the rules, so both are
// read and either alone is enough.
func TestRequiredChecksComeFromClassicProtectionAndFromRulesAlike(t *testing.T) {
	t.Run("classic only", func(t *testing.T) {
		f := newFake(t)
		f.SetBranchProtection("acme/api", "main", actions("test", "build")...)
		p := readProtection(t, f, "main")
		if !slices.Equal(p.Required, []string{"build", "test"}) || p.Unpinned != 0 || p.Partial {
			t.Errorf("read %+v", p)
		}
	})
	t.Run("rules only", func(t *testing.T) {
		f := newFake(t)
		f.AddBranchRule("acme/api", "main", actions("lint")...)
		p := readProtection(t, f, "main")
		if !slices.Equal(p.Required, []string{"lint"}) || p.Partial {
			t.Errorf("read %+v", p)
		}
	})
	t.Run("both, with a repeat", func(t *testing.T) {
		f := newFake(t)
		f.SetBranchProtection("acme/api", "main", actions("test")...)
		f.AddBranchRule("acme/api", "main", actions("test", "lint")...)
		f.AddBranchRule("acme/api", "main", actions("lint")...)
		p := readProtection(t, f, "main")
		if !slices.Equal(p.Required, []string{"lint", "test"}) {
			t.Errorf("read %+v, want each check once, sorted", p)
		}
	})
}

// A check any app may post could come from somewhere the fleet cannot see, so it
// is counted and never judged: a pinned one is the only kind the jobs the fleet
// saw can speak for. One source leaving a check open to any app is enough to
// leave it open.
func TestOnlyACheckPinnedToTheActionsAppIsKeptForJudging(t *testing.T) {
	f := newFake(t)
	f.SetBranchProtection("acme/api", "main",
		FakeRequiredCheck{Context: "pinned", AppID: GitHubActionsAppID},
		FakeRequiredCheck{Context: "any app"},
		FakeRequiredCheck{Context: "other app", AppID: 99},
		FakeRequiredCheck{Context: "open in a rule", AppID: GitHubActionsAppID},
	)
	f.AddBranchRule("acme/api", "main", FakeRequiredCheck{Context: "open in a rule"})
	p := readProtection(t, f, "main")
	if !slices.Equal(p.Required, []string{"pinned"}) || p.Unpinned != 3 {
		t.Errorf("read %+v, want one pinned and three left open", p)
	}
}

// The deprecated list of contexts names no app, so it can only be unpinned.
func TestAProtectionRuleThatOnlyListsContextsPinsNothing(t *testing.T) {
	f := newFake(t)
	f.SetLegacyBranchProtection("acme/api", "main", "build", "test")
	p := readProtection(t, f, "main")
	if len(p.Required) != 0 || p.Unpinned != 2 {
		t.Errorf("read %+v, want two unpinned", p)
	}
}

// GitHub accepts a slash in a branch name, and go-github escapes it for one
// endpoint and not the other. Both reads have to find the branch.
func TestABranchNameWithASlashIsFoundByBothReads(t *testing.T) {
	f := newFake(t)
	f.SetBranchProtection("acme/api", "release/1.0", actions("classic")...)
	f.AddBranchRule("acme/api", "release/1.0", actions("ruled")...)
	p := readProtection(t, f, "release/1.0")
	if !slices.Equal(p.Required, []string{"classic", "ruled"}) {
		t.Errorf("read %+v", p)
	}
}

// Without Administration read the classic half is refused and the rules, which
// need only Metadata, are not. The checks the rules require are kept and the
// repository is partial, so nothing is judged as if the other half were empty.
func TestARefusedClassicHalfLeavesTheRulesAndMarksTheReadPartial(t *testing.T) {
	f := newFake(t)
	withoutAdministration(f)
	f.AddBranchRule("acme/api", "main", actions("lint")...)
	p := readProtection(t, f, "main")
	if !slices.Equal(p.Required, []string{"lint"}) || !p.Partial {
		t.Errorf("read %+v", p)
	}
}

func TestProtectionRefusedInBothHalvesFailsAsForbidden(t *testing.T) {
	f := newFake(t)
	withoutAdministration(f)
	f.SetError("rules/branches", 403, "Resource not accessible by integration")
	_, err := settingsReader(t, f).KennelProtection(context.Background(), "acme/api", "main")
	if !errors.Is(err, ErrForbidden) {
		t.Errorf("err = %v", err)
	}
}

// A GitHub that lacks rules has none that require anything, which is complete
// knowledge and not a gap.
func TestAGitHubWithoutRulesIsNotPartial(t *testing.T) {
	for _, status := range []int{404, 405} {
		f := newFake(t)
		f.SetBranchProtection("acme/api", "main", actions("test")...)
		f.SetError("rules/branches", status, "Not Found")
		p := readProtection(t, f, "main")
		if !slices.Equal(p.Required, []string{"test"}) || p.Partial {
			t.Errorf("status %d: read %+v", status, p)
		}
	}
}

// Rules are paged a hundred at a time, and one branch cannot make a refresh
// unbounded: the pages are read up to a limit and the read is marked partial
// where the limit cut it.
func TestRulesArePagedAndTheReadIsBounded(t *testing.T) {
	t.Run("every page of a long list", func(t *testing.T) {
		f := newFake(t)
		for i := 0; i < 150; i++ {
			f.AddBranchRule("acme/api", "main", actions(fmt.Sprintf("check-%d", i%10))...)
		}
		p := readProtection(t, f, "main")
		if len(p.Required) != 10 || p.Partial {
			t.Errorf("read %d checks, partial %v", len(p.Required), p.Partial)
		}
		if got := requestsTo(f, "/rules/branches/"); len(got) != 2 {
			t.Errorf("a list of 150 rules took %d requests: %v", len(got), got)
		}
	})
	t.Run("stops at the limit", func(t *testing.T) {
		// The limit is a budget: one branch's rules may cost a refresh no more
		// than this. Read from the constant alone, a test would follow the
		// constant wherever it was moved.
		const mostRuleRequests = 10
		if kennelRulePages > mostRuleRequests {
			t.Fatalf("kennelRulePages is %d; one branch's rules may cost at most %d requests a refresh", kennelRulePages, mostRuleRequests)
		}
		f := newFake(t)
		for i := 0; i < 100*kennelRulePages+50; i++ {
			f.AddBranchRule("acme/api", "main", actions(fmt.Sprintf("check-%d", i%10))...)
		}
		p := readProtection(t, f, "main")
		if !p.Partial {
			t.Error("a list cut at the limit was not marked partial")
		}
		if got := requestsTo(f, "/rules/branches/"); len(got) != kennelRulePages {
			t.Errorf("%d requests, want %d", len(got), kennelRulePages)
		}
	})
}

// A repository cannot make the kept list unbounded either.
func TestTheRequiredChecksKeptAreBounded(t *testing.T) {
	f := newFake(t)
	var names []string
	for i := 0; i < kennelRequiredCap+20; i++ {
		names = append(names, fmt.Sprintf("check-%03d", i))
	}
	f.SetBranchProtection("acme/api", "main", actions(names...)...)
	p := readProtection(t, f, "main")
	if len(p.Required) != kennelRequiredCap || !p.Partial {
		t.Errorf("kept %d, partial %v", len(p.Required), p.Partial)
	}
}

func TestAProtectionReadNeedsABranch(t *testing.T) {
	f := newFake(t)
	if _, err := settingsReader(t, f).KennelProtection(context.Background(), "acme/api", ""); err == nil {
		t.Error("a read with no branch was made")
	}
	if got := f.Requests(); len(got) != 0 {
		t.Errorf("requests made for no branch: %v", got)
	}
}

func TestEverySettingsReadIsAGet(t *testing.T) {
	f := newFake(t)
	f.SetBranchProtection("acme/api", "main", actions("test")...)
	f.AddBranchRule("acme/api", "main", actions("lint")...)
	r := settingsReader(t, f)
	for _, public := range []bool{true, false} {
		if _, err := r.KennelSettings(context.Background(), "acme/api", public); err != nil {
			t.Fatal(err)
		}
	}
	readProtection(t, f, "main")
	if len(f.Requests()) == 0 {
		t.Fatal("no requests were recorded; the test proves nothing")
	}
	noWrites(t, f)
}

package github

import (
	"context"
	"fmt"
	"path"
	"strings"
)

// KennelSetupReader is optional: clients without Contents access still provide
// exposure and capacity facts, and never need a new write capability.
type KennelSetupReader interface {
	KennelSetup(context.Context, string, string) (*KennelSetup, error)
}

// KennelSetup is a file inventory, not a judgement about the files' contents.
// No raw path or content survives the reduction at this boundary.
type KennelSetup struct {
	Present         map[string]bool
	HasDependencies bool
	Partial         bool
}

func (c *appClient) KennelSetup(ctx context.Context, repo, branch string) (*KennelSetup, error) {
	owner, name, err := splitRepo(repo)
	if err != nil {
		return nil, err
	}
	if branch == "" {
		return nil, fmt.Errorf("github: repository has no default branch")
	}
	tree, resp, err := c.readClient().Git.GetTree(ctx, owner, name, branch, true)
	if err != nil {
		return nil, c.fail("read repository setup tree", resp, err)
	}
	if tree == nil || tree.GetSHA() == "" {
		return nil, fmt.Errorf("github: setup tree has no identity")
	}
	out := &KennelSetup{Present: map[string]bool{}, Partial: tree.GetTruncated()}
	// GitHub caps recursive trees at 100,000 entries. A smaller local cap bounds
	// inspection too; any omitted path leaves the inventory incomplete.
	entries := tree.Entries
	if len(entries) > 10000 {
		entries = entries[:10000]
		out.Partial = true
	}
	for _, e := range entries {
		if e.GetType() != "blob" || (e.GetMode() != "100644" && e.GetMode() != "100755") || e.GetSize() <= 0 {
			continue
		}
		p := e.GetPath()
		base := strings.ToLower(path.Base(p))
		dir := path.Dir(p)
		community := dir == "." || dir == ".github" || dir == "docs"
		if community {
			stem := strings.TrimSuffix(base, path.Ext(base))
			switch stem {
			case "readme":
				out.Present["readme"] = true
			case "license", "licence", "copying":
				if dir == "." {
					out.Present["licence"] = true
				}
			case "security":
				out.Present["security"] = true
			case "contributing":
				out.Present["contributing"] = true
			case "code_of_conduct":
				out.Present["code_of_conduct"] = true
			case "pull_request_template":
				out.Present["pull_request_template"] = true
			case "issue_template":
				out.Present["issue_template"] = true
			}
		}
		// CODEOWNERS and Actions paths are case-sensitive on GitHub.
		if p == ".github/CODEOWNERS" || p == "CODEOWNERS" || p == "docs/CODEOWNERS" {
			out.Present["codeowners"] = true
		}
		if dir == ".github/ISSUE_TEMPLATE" && (strings.HasSuffix(base, ".md") || strings.HasSuffix(base, ".yml") || strings.HasSuffix(base, ".yaml")) && base != "config.yml" && base != "config.yaml" {
			out.Present["issue_template"] = true
		}
		if (dir == ".github/PULL_REQUEST_TEMPLATE" || dir == "docs/PULL_REQUEST_TEMPLATE" || dir == "PULL_REQUEST_TEMPLATE") && strings.HasSuffix(base, ".md") {
			out.Present["pull_request_template"] = true
		}
		if dir == ".github/workflows" && (strings.HasSuffix(p, ".yml") || strings.HasSuffix(p, ".yaml")) {
			out.Present["workflows"] = true
			out.HasDependencies = true
		}
		switch p {
		case ".github/dependabot.yml", ".github/dependabot.yaml", "renovate.json", "renovate.json5", ".renovaterc", ".renovaterc.json", ".github/renovate.json", ".github/renovate.json5":
			out.Present["dependency_updates"] = true
		}
		// Root manifests avoid treating vendored packages and example projects as
		// an obligation to run an update bot for this repository.
		if dir == "." {
			switch base {
			case "go.mod", "package.json", "cargo.toml", "pyproject.toml", "requirements.txt", "pipfile", "gemfile", "composer.json", "pom.xml", "build.gradle", "build.gradle.kts", "mix.exs", "pubspec.yaml", "packages.config":
				out.HasDependencies = true
			}
		}
	}
	return out, nil
}

