func TestParseWorkflowJobCompleted(t *testing.T) {
	e, err := ParseWorkflowJob(jobPayload("completed", "completed", "success", true, true))
	if err != nil {
		t.Fatalf("ParseWorkflowJob: %v", err)
	}
	j := e.ToJob()
	if j.State != store.JobCompleted {
		t.Fatalf("state = %q", j.State)
	}
	if j.Conclusion != "success" {
		t.Fatalf("conclusion = %q", j.Conclusion)
	}
	if j.CompletedAt == nil || !j.CompletedAt.Equal(time.Date(2024, 5, 1, 10, 5, 0, 0, time.UTC)) {
		t.Fatalf("completed_at = %v", j.CompletedAt)
	}
	if got := j.Duration(); got != 4*time.Minute+30*time.Second {
		t.Fatalf("duration = %v", got)
	}
}

// The steps are what let a failed job say where it failed without the operator
// leaving for GitHub, and the branch and attempt are what make "CI failed" mean
// something.
func TestParseWorkflowJobCarriesTheStepsAndTheRunContext(t *testing.T) {
	e, err := ParseWorkflowJob(jobPayload("completed", "completed", "failure", true, true))
	if err != nil {
		t.Fatalf("ParseWorkflowJob: %v", err)
	}
	if e.HeadBranch != "main" || e.HeadSHA != "0123456789abcdef0123456789abcdef01234567" || e.RunAttempt != 2 {
		t.Fatalf("run context = %q %q %d", e.HeadBranch, e.HeadSHA, e.RunAttempt)
	}
	if len(e.Steps) != 3 {
		t.Fatalf("steps = %+v, want 3", e.Steps)
	}
	j := e.ToJob()
	if j.HeadBranch != "main" || j.RunAttempt != 2 || len(j.Steps) != 3 {
		t.Fatalf("ToJob dropped the run context or the steps: %+v", j)
	}
	step := j.FailedStep()
	if step == nil || step.Number != 2 || step.Name != "Run tests" || step.Conclusion != "failure" {
		t.Fatalf("FailedStep = %+v, want step 2 'Run tests' failed", step)
	}
	if step.StartedAt == nil || step.CompletedAt == nil || step.CompletedAt.Sub(*step.StartedAt) != 4*time.Minute+15*time.Second {
		t.Fatalf("failed step timestamps = %v .. %v", step.StartedAt, step.CompletedAt)
	}
	// The step after the failure was skipped as a consequence, and must not be
	// the one reported.
	if j.Steps[2].Conclusion != "skipped" {
		t.Fatalf("step 3 conclusion = %q, want skipped", j.Steps[2].Conclusion)
	}

	// A job still running has steps too, but none of them has failed yet.
	running, err := ParseWorkflowJob(jobPayload("in_progress", "in_progress", "", true, false))
	if err != nil {
		t.Fatalf("ParseWorkflowJob in_progress: %v", err)
	}
	if rj := running.ToJob(); rj.FailedStep() != nil || len(rj.Steps) != 3 || rj.Steps[1].Status != "in_progress" {
		t.Fatalf("running job steps = %+v", rj.Steps)
	}
	// And a success has no failed step to name.
	ok, _ := ParseWorkflowJob(jobPayload("completed", "completed", "success", true, true))
	if ok.ToJob().FailedStep() != nil {
		t.Fatal("a successful job named a failed step")
	}
}

func TestParseWorkflowJobWaitingIsItsOwnState(t *testing.T) {
	// A job held for a deployment review is not demand: recorded as queued it
	// had the scheduler starting a runner nobody could use for as long as the
	// review took. It is "waiting", which sits before queued in the lifecycle
	// so that the approval's queued delivery still moves it forward.
	e, err := ParseWorkflowJob(jobPayload("waiting", "waiting", "", false, false))
	if err != nil {
		t.Fatalf("ParseWorkflowJob: %v", err)
	}
	if got := e.ToJob().State; got != store.JobWaiting {
		t.Fatalf("state = %q, want %q", got, store.JobWaiting)
	}
}

// GitHub stamps started_at on any job that has not started, and the store keeps
// StartedAt write-once. Trusting it on a held job would pin the start to the
// moment the job was created: the hours of review would then count as run time,
// the queue wait after approval would come out negative and be dropped, and the
// real started_at on the in_progress delivery could never replace it.
func TestAWaitingJobKeepsNoStartedAtFromItsDelivery(t *testing.T) {
	e, err := ParseWorkflowJob(jobPayload("waiting", "waiting", "", true, false))
	if err != nil {
		t.Fatalf("ParseWorkflowJob: %v", err)
	}
	if e.StartedAt.IsZero() {
		t.Fatal("the payload carries no started_at, so this test proves nothing")
	}
	if j := e.ToJob(); j.StartedAt != nil {
		t.Fatalf("a waiting job has StartedAt = %v", *j.StartedAt)
	}
}

func TestParseWorkflowJobCompletedWithoutTimestamp(t *testing.T) {
	before := time.Now().UTC()
	e, err := ParseWorkflowJob(jobPayload("completed", "completed", "cancelled", false, false))
	if err != nil {
		t.Fatalf("ParseWorkflowJob: %v", err)
	}
	j := e.ToJob()
	if j.CompletedAt == nil || j.CompletedAt.Before(before) {
		t.Fatalf("completed_at should be stamped now, got %v", j.CompletedAt)
	}
}

func TestParseWorkflowJobRejectsOtherEvents(t *testing.T) {
	_, err := ParseWorkflowJob([]byte(`{"action":"completed","workflow_run":{"id":1}}`))
	if !errors.Is(err, ErrNotWorkflowJob) {
		t.Fatalf("got %v, want ErrNotWorkflowJob", err)
	}
	if _, err := ParseWorkflowJob([]byte(`not json`)); err == nil {
		t.Fatal("malformed JSON accepted")
	}
}

func TestToJobStampsQueuedAtWhenMissing(t *testing.T) {
	e := &WorkflowJobEvent{Action: "queued", JobID: 1}
	j := e.ToJob()
	if j.QueuedAt.IsZero() {
		t.Fatal("QueuedAt left zero; the queue-wait histogram cannot sort it")
	}
}

package hosttune

import (
	"fmt"
	"sync"
	"time"
)

// Acceptance is an operator's decision that a warning is deliberate. The
// controller stamps it on a COPY of the report when it reads one; anything an
// agent sent in its place is discarded, so a host can never silence its own
// alarm.
type Acceptance struct {
	Reason    string    `json:"reason"`
	By        string    `json:"by"`
	At        time.Time `json:"at"`
	ExpiresAt time.Time `json:"expires_at"`
}

// Ended says why a held acceptance no longer covers a result, so the row that
// came back to the list does not look like a bug. At is the acceptance's own
// time -- when it was made for "changed" and "worse", when it lapsed for
// "expired" -- and never the moment of reading: a stamp that moved on every
// pass would make every frame differ from the last.
type Ended struct {
	By  string    `json:"by"`
	At  time.Time `json:"at"`
	Was string    `json:"was"`
	Why string    `json:"why"` // "changed" | "expired" | "worse"
}

// Why an acceptance ended.
const (
	EndedChanged = "changed"
	EndedExpired = "expired"
	EndedWorse   = "worse"
)

// Held is one stored acceptance as the controller loads it.
type Held struct {
	CheckID, Current, Reason, By string
	At, ExpiresAt                time.Time
}

// MaxAcceptance is the longest an acceptance may last. Every one must end: an
// acceptance with no end is how a kernel pinned below the baseline is still
// "deliberate" three years after the person who chose it left.
const MaxAcceptance = 365 * 24 * time.Hour

// catalogue is every check this build can emit, by id, built from the same
// constructors the engine runs (closures with no I/O, as titles does).
var catalogue = sync.OnceValue(func() map[string]Check {
	m := map[string]Check{"environment": {ID: "environment", Tier: Safe}}
	for _, list := range [][]Check{baseChecks(), kernelChecks(), dedicatedChecks()} {
		for _, c := range list {
			m[c.ID] = c
		}
	}
	return m
})

// Acceptable reports whether a check may ever be accepted and, if not, the
// sentence to tell the person. Only a counted catalogue check: never the
// reboot, which ends when the host reboots, and never the two disk checks,
// because free space moves and an acceptance could not tell 12% from 2%.
func Acceptable(id string) (ok bool, why string) {
	c, known := catalogue()[id]
	switch {
	case !known:
		return false, fmt.Sprintf("This build does not know a check called %q.", id)
	case id == KernelPending:
		return false, "A pending reboot cannot be accepted: it ends when the host reboots. Cordon the host and reboot it when it is idle."
	case id == "disk.space" || id == "disk.inodes":
		return false, "Free space moves, so an acceptance could not tell 12% free from 2%. Make room on the work directory's filesystem, or give the host a larger disk."
	case c.Tier != Safe || c.Optional:
		return false, "That check is a suggestion and does not count, so there is nothing to accept."
	}
	return true, ""
}

// AcceptRefusal is why a result as it stands cannot be accepted, or "" when it
// can. It judges the id first and then the outcome, so the sentence names the
// thing the person can change.
func AcceptRefusal(x Result) string {
	if ok, why := Acceptable(x.ID); !ok {
		return why
	}
	switch x.Status {
	case Warn:
		return ""
	case Error:
		return "This check could not run, so there is nothing to accept. Fix what stops it running; the Why column says what."
	}
	return "That check is not a warning on this host right now."
}

// Judged returns a copy of r with Accepted, Ended and Acceptable stamped, and
// never touches r.Results: the stored report is shared with the heartbeat write
// path. It clears whatever an agent put in those fields first.
//
// An acceptance covers a result only while the check is a counted Warn that
// still reads what it read when the operator decided, inside its term. If the
// value returns to the accepted text within the term it holds again, on purpose:
// the decision was about that value.
func (r Report) Judged(held []Held, now time.Time) Report {
	out := r
	out.Results = make([]Result, len(r.Results))
	byCheck := make(map[string]Held, len(held))
	for _, h := range held {
		if _, dup := byCheck[h.CheckID]; !dup {
			byCheck[h.CheckID] = h
		}
	}
	for i, x := range r.Results {
		x.Accepted, x.Ended, x.Acceptable = nil, nil, false
		out.Results[i] = x
		// A container sees only its own corner of the host, and the reboot row
		// is the reboot: neither is ever judged.
		if r.Container || r.rebootRow(x) || !x.Counted() {
			continue
		}
		if ok, _ := Acceptable(x.ID); !ok || (x.Status != Warn && x.Status != Error) {
			continue
		}
		h, has := byCheck[x.ID]
		switch {
		case !has:
		case x.Status == Error:
			x.Ended = &Ended{By: h.By, At: h.At, Was: h.Current, Why: EndedWorse}
		case !now.Before(h.ExpiresAt):
			x.Ended = &Ended{By: h.By, At: h.ExpiresAt, Was: h.Current, Why: EndedExpired}
		case x.Current != h.Current:
			x.Ended = &Ended{By: h.By, At: h.At, Was: h.Current, Why: EndedChanged}
		default:
			x.Accepted = &Acceptance{Reason: h.Reason, By: h.By, At: h.At, ExpiresAt: h.ExpiresAt}
		}
		x.Acceptable = x.Status == Warn && x.Accepted == nil
		out.Results[i] = x
	}
	return out
}

// Accepting reports whether an operator's acceptance covers this result.
func (x Result) Accepting() bool { return x.Accepted != nil }

package hosttune

import (
	"encoding/json"
	"slices"
	"strings"
	"testing"
	"time"
)

var acceptNow = time.Date(2026, 10, 7, 12, 0, 0, 0, time.UTC)

func warnWith(id, current string) Result {
	return Result{ID: id, Title: id, Tier: Safe, Status: Warn, Current: current}
}

func heldFor(id, current string, expires time.Time) Held {
	return Held{CheckID: id, Current: current, Reason: "pinned on purpose", By: "Sam", At: acceptNow.Add(-24 * time.Hour), ExpiresAt: expires}
}

// Which checks may be accepted is decided here and nowhere else, so a refused
// one cannot be got round by a client that skips the dialog.
func TestOnlyACountedCatalogueCheckThatIsNotAMovingMeasurementIsAcceptable(t *testing.T) {
	for id, want := range map[string]bool{
		"docker.logs":     true,
		"work.filesystem": true,
		"environment":     true,
		KernelPending:     false,
		"disk.space":      false,
		"disk.inodes":     false,
		"cpu.governor":    false, // aggressive: a suggestion, nothing to accept
		"tmp.tmpfs":       false,
		"service.snapd":   false,
		"no.such.check":   false,
		"cpu.x$(reboot)":  false,
		"":                false,
	} {
		ok, why := Acceptable(id)
		if ok != want {
			t.Errorf("Acceptable(%q) = %v, want %v", id, ok, want)
		}
		if !ok && why == "" {
			t.Errorf("Acceptable(%q) refused without telling the person why", id)
		}
		if ok && why != "" {
			t.Errorf("Acceptable(%q) allowed but also said %q", id, why)
		}
	}
}

func TestEveryRefusalSentenceNamesWhatThePersonCanDo(t *testing.T) {
	_, unknown := Acceptable("nope")
	_, reboot := Acceptable(KernelPending)
	_, disk := Acceptable("disk.space")
	for _, s := range []string{unknown, reboot, disk, AcceptRefusal(Result{ID: "docker.logs", Tier: Safe, Status: Error}), AcceptRefusal(Result{ID: "docker.logs", Tier: Safe, Status: OK})} {
		if s == "" || !strings.HasSuffix(s, ".") {
			t.Errorf("refusal %q is not a sentence", s)
		}
	}
	if AcceptRefusal(warnWith("docker.logs", "x")) != "" {
		t.Error("a counted warning on a catalogue check was refused")
	}
}

// The stored report is shared with the heartbeat write path: judging must never
// leave a mark on it, or the next read would see an acceptance that was revoked.
func TestJudgingNeverMutatesTheStoredReport(t *testing.T) {
	r := Report{Results: []Result{warnWith("docker.logs", "none")}}
	got := r.Judged([]Held{heldFor("docker.logs", "none", acceptNow.Add(time.Hour))}, acceptNow)
	if got.Results[0].Accepted == nil {
		t.Fatal("the acceptance did not cover its result")
	}
	if r.Results[0].Accepted != nil || r.Results[0].Acceptable {
		t.Error("Judged wrote through to the report it was given")
	}
}

// A host must not be able to silence its own alarm by claiming an acceptance.
func TestAnAgentsOwnAcceptanceMarksAreCleared(t *testing.T) {
	x := warnWith("docker.logs", "none")
	x.Accepted = &Acceptance{Reason: "trust me"}
	x.Ended = &Ended{Why: "changed"}
	x.Acceptable = false
	for _, container := range []bool{false, true} {
		got := Report{Container: container, Results: []Result{x}}.Judged(nil, acceptNow)
		if got.Results[0].Accepted != nil || got.Results[0].Ended != nil {
			t.Errorf("container=%v: a mark the agent sent survived", container)
		}
		if got.Summary().Accepted != 0 {
			t.Errorf("container=%v: an agent's claim was counted as accepted", container)
		}
	}
}

func TestAnAcceptanceHoldsOnlyForTheValueAndTermItWasMadeFor(t *testing.T) {
	soon := acceptNow.Add(48 * time.Hour)
	cases := []struct {
		name    string
		result  Result
		held    Held
		now     time.Time
		covered bool
		ended   string
		offer   bool
	}{
		{"the same value inside the term is covered", warnWith("docker.logs", "none"), heldFor("docker.logs", "none", soon), acceptNow, true, "", false},
		{"a warning nobody accepted can be accepted", warnWith("docker.logs", "none"), Held{}, acceptNow, false, "", true},
		{"a changed value counts again and says so", warnWith("docker.logs", "10m"), heldFor("docker.logs", "none", soon), acceptNow, false, EndedChanged, true},
		{"the day it ends it counts again", warnWith("docker.logs", "none"), heldFor("docker.logs", "none", acceptNow), acceptNow, false, EndedExpired, true},
		{"an error is never covered and is not offered", Result{ID: "docker.logs", Tier: Safe, Status: Error, Current: "none"}, heldFor("docker.logs", "none", soon), acceptNow, false, EndedWorse, false},
		{"an acceptance on a passing check is inert", Result{ID: "docker.logs", Tier: Safe, Status: OK, Current: "none"}, heldFor("docker.logs", "none", soon), acceptNow, false, "", false},
		{"an acceptance on a skipped check is inert", Result{ID: "docker.logs", Tier: Safe, Status: Skip}, heldFor("docker.logs", "none", soon), acceptNow, false, "", false},
		{"a suggestion tier is never judged", Result{ID: "cpu.governor", Tier: Aggressive, Status: Warn, Current: "none"}, heldFor("cpu.governor", "none", soon), acceptNow, false, "", false},
		{"disk space is never accepted even if a row exists", warnWith("disk.space", "3% free"), heldFor("disk.space", "3% free", soon), acceptNow, false, "", false},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			held := []Held{c.held}
			if c.held.CheckID == "" {
				held = nil
			}
			got := Report{Results: []Result{c.result}}.Judged(held, c.now).Results[0]
			if (got.Accepted != nil) != c.covered {
				t.Errorf("covered = %v, want %v", got.Accepted != nil, c.covered)
			}
			why := ""
			if got.Ended != nil {
				why = got.Ended.Why
			}
			if why != c.ended {
				t.Errorf("ended = %q, want %q", why, c.ended)
			}
			if got.Acceptable != c.offer {
				t.Errorf("acceptable = %v, want %v", got.Acceptable, c.offer)
			}
		})
	}
}

// If the value drifts back inside the term the decision applies again: it was a
// decision about that value, and the docs say so.
func TestAValueThatReturnsToTheAcceptedTextHoldsAgainInsideTheTerm(t *testing.T) {
	held := []Held{heldFor("docker.logs", "none", acceptNow.Add(time.Hour))}
	changed := Report{Results: []Result{warnWith("docker.logs", "10m")}}.Judged(held, acceptNow)
	back := Report{Results: []Result{warnWith("docker.logs", "none")}}.Judged(held, acceptNow)
	if changed.Results[0].Accepted != nil || back.Results[0].Accepted == nil {
		t.Error("the acceptance did not follow the value")
	}
}

// The ended stamp must not move between reads, or every pass would publish a
// frame that differs from the last.
func TestAnEndedNoteIsTheSameOnEveryRead(t *testing.T) {
	r := Report{Results: []Result{warnWith("docker.logs", "10m")}}
	held := []Held{heldFor("docker.logs", "none", acceptNow.Add(time.Hour))}
	a, _ := json.Marshal(r.Judged(held, acceptNow))
	b, _ := json.Marshal(r.Judged(held, acceptNow.Add(10*time.Minute)))
	if string(a) != string(b) {
		t.Errorf("the judged report moved with the clock:\n%s\n%s", a, b)
	}
}

func TestAnAcceptedWarningLeavesTheCountsAndStaysInTheTotal(t *testing.T) {
	r := Report{Results: []Result{
		warnWith("docker.logs", "none"),
		warnWith("cgroup.version", "v1"),
		{ID: "docker.storage", Tier: Safe, Status: OK},
	}}.Judged([]Held{heldFor("docker.logs", "none", acceptNow.Add(time.Hour))}, acceptNow)
	s := r.Summary()
	if want := (Summary{Counted: 3, Warnings: 1, Accepted: 1}); s != want {
		t.Errorf("summary = %+v, want %+v", s, want)
	}
	if got := ids(r.Findings()); !slices.Equal(got, []string{"cgroup.version"}) {
		t.Errorf("findings = %v, want only the unaccepted warning", got)
	}
	if n := len(r.Findings()); n != s.Warnings+s.Errors {
		t.Errorf("findings %d != warnings+errors %d", n, s.Warnings+s.Errors)
	}
	if w, e, _ := r.Counts(); w != 1 || e != 0 {
		t.Errorf("Counts = %d warnings, %d errors; doctor must agree with the page", w, e)
	}
}

// A host whose only warning was accepted exits 0, as the page says it is well.
func TestAHostWhoseOnlyWarningWasAcceptedExitsZero(t *testing.T) {
	r := Report{Results: []Result{warnWith("docker.logs", "none")}}
	if r.ExitCode() != 1 {
		t.Fatal("setup: an unaccepted warning must exit 1")
	}
	j := r.Judged([]Held{heldFor("docker.logs", "none", acceptNow.Add(time.Hour))}, acceptNow)
	if j.ExitCode() != 0 {
		t.Errorf("exit code = %d, want 0", j.ExitCode())
	}
}

// The reboot is counted once, as the reboot; it can never be accepted, even by
// a stored row for it.
func TestThePendingRebootIsNeverAcceptedAway(t *testing.T) {
	r := Report{RebootPending: true, Results: []Result{warnWith(KernelPending, "5.15")}}.
		Judged([]Held{heldFor(KernelPending, "5.15", acceptNow.Add(time.Hour))}, acceptNow)
	if r.Results[0].Accepted != nil || r.Results[0].Acceptable {
		t.Error("the reboot row was judged")
	}
	if r.Summary().Accepted != 0 {
		t.Error("the reboot was counted as accepted")
	}
}

func TestTheResultMarksAreOmittedWhenThereIsNothingToSay(t *testing.T) {
	b, _ := json.Marshal(warnWith("docker.logs", "x"))
	for _, k := range []string{"accepted", "ended", "acceptable"} {
		if strings.Contains(string(b), `"`+k+`"`) {
			t.Errorf("%s present on a plain result: %s", k, b)
		}
	}
}

package hosttune

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"path/filepath"
	"strings"
	"time"
)

type Snapshot struct {
	Exists bool        `json:"exists"`
	Data   []byte      `json:"data,omitempty"`
	Mode   fs.FileMode `json:"mode"`
	UID    int         `json:"uid"`
	GID    int         `json:"gid"`
}
type FileChange struct {
	Path   string      `json:"path"`
	Before Snapshot    `json:"before"`
	After  []byte      `json:"after"`
	Mode   fs.FileMode `json:"mode"`
}
type Operation struct {
	Do       []string `json:"do,omitempty"`
	Undo     []string `json:"undo,omitempty"`
	Path     string   `json:"path,omitempty"`
	Value    string   `json:"value,omitempty"`
	Previous string   `json:"previous,omitempty"`
}
type UnitChange struct {
	Name          string `json:"name"`
	BeforeEnabled string `json:"before_enabled"`
	BeforeActive  string `json:"before_active"`
	AfterEnabled  string `json:"after_enabled"`
	AfterActive   string `json:"after_active"`
}
type Change struct {
	Units         []UnitChange `json:"units,omitempty"`
	ID            string       `json:"id"`
	Previous      string       `json:"previous"`
	New           string       `json:"new"`
	Files         []FileChange `json:"files,omitempty"`
	Operations    []Operation  `json:"operations,omitempty"`
	DockerRestart bool         `json:"docker_restart,omitempty"`
	Notice        string       `json:"notice,omitempty"`
	At            time.Time    `json:"at"`
	Actor         string       `json:"actor"`
	Phase         string       `json:"phase"`
}
type State struct {
	DockerRestartPending bool `json:"docker_restart_pending"`
	// MaintenanceStopped is the units a maintenance restart has stopped and not yet
	// started again. It is written before the first stop and cleared after the last
	// start, so a restart that was killed in between -- SIGKILL, a crash, the machine
	// going down -- left a record of what it owed. Without it a rerun saw both units
	// inactive, decided there was nothing to restore, and reported the host back in
	// service with the agent and the controller still stopped.
	MaintenanceStopped []string `json:"maintenance_stopped,omitempty"`
	Version            int      `json:"version"`
	Changes            []Change `json:"changes"`
}

func snapshot(e *Engine, p string) (Snapshot, error) {
	i, err := e.System.Stat(p)
	if errors.Is(err, fs.ErrNotExist) {
		return Snapshot{}, nil
	}
	if err != nil {
		return Snapshot{}, err
	}
	if !i.Mode().IsRegular() {
		return Snapshot{}, fmt.Errorf("refusing non-regular file %s", p)
	}
	b, err := e.System.ReadFile(p)
	uid, gid := fileOwner(i)
	return Snapshot{Exists: true, Data: b, Mode: i.Mode().Perm(), UID: uid, GID: gid}, err
}
func snapshotMode(s Snapshot) fs.FileMode {
	if s.Exists {
		return s.Mode
	}
	return 0644
}
func fileChange(e *Engine, p, s string) (FileChange, error) {
	b, err := snapshot(e, p)
	if managed(string(b.Data)) {
		return FileChange{}, fmt.Errorf("%s is managed elsewhere", p)
	}
	mode := fs.FileMode(0644)
	if b.Exists {
		mode = b.Mode
	}
	return FileChange{Path: p, Before: b, After: []byte(s), Mode: mode}, err
}
func (e *Engine) LoadState() (State, error) {
	s := State{Version: 1, Changes: []Change{}}
	b, err := e.System.ReadFile(StatePath)
	if errors.Is(err, fs.ErrNotExist) {
		return s, nil
	}
	if err != nil {
		return s, err
	}
	if err = json.Unmarshal(b, &s); err != nil {
		return s, err
	}
	if s.Version != 1 {
		return s, fmt.Errorf("unsupported tuning state version %d", s.Version)
	}
	return s, nil
}
func (e *Engine) saveState(s State) error {
	b, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		return err
	}
	return e.System.WriteFile(StatePath, append(b, '\n'), 0600)
}
func (e *Engine) Plan(ctx context.Context, r Result) (Change, error) {
	c, ok := e.Check(r.ID)
	if !ok || c.Plan == nil {
		return Change{}, fmt.Errorf("%s is report-only", r.ID)
	}
	if !e.Supported() || e.Container || e.UID != 0 {
		return Change{}, fmt.Errorf("tuning requires root on a supported Linux host outside a container")
	}
	fresh := c.Detect(ctx, e)
	if c.ID == "kernel.hwe-install" && strings.HasPrefix(fresh.Reason, "optional install") {
		fresh.Reason = ""
	}
	if fresh.Status != Warn || fresh.Reason != "" {
		return Change{}, fmt.Errorf("%s cannot be changed: %s (%s)", r.ID, fresh.Status, fresh.Reason)
	}
	fresh.ID = c.ID
	fresh.Recommended = r.Recommended
	return c.Plan(ctx, e, fresh)
}

// Preview is deliberately literal: all bytes removed/added and every command
// are visible, rather than an abbreviated description hiding configuration.
func (c Change) Preview() string {
	var b bytes.Buffer
	for _, f := range c.Files {
		fmt.Fprintf(&b, "--- %s (before)\n+++ %s (after)\n", f.Path, f.Path)
		for _, l := range bytes.Split(bytes.TrimSuffix(f.Before.Data, []byte("\n")), []byte("\n")) {
			fmt.Fprintf(&b, "-%s\n", l)
		}
		for _, l := range bytes.Split(bytes.TrimSuffix(f.After, []byte("\n")), []byte("\n")) {
			fmt.Fprintf(&b, "+%s\n", l)
		}
	}
	for _, o := range c.Operations {
		if o.Path != "" {
			fmt.Fprintf(&b, "write %s: %q -> %q\n", o.Path, o.Previous, o.Value)
		} else {
			fmt.Fprintf(&b, "command: %q\nrevert: %q\n", o.Do, o.Undo)
		}
	}
	if c.Notice != "" {
		fmt.Fprintln(&b, c.Notice)
	}
	return b.String()
}
func (e *Engine) verifyRevert(ctx context.Context, c Change) error {
	for _, u := range c.Units {
		en, ac, err := unitState(ctx, e, u.Name)
		if err != nil {
			return err
		}
		allowedEnabled := en == u.AfterEnabled || (c.Phase == "pending" && (en == u.BeforeEnabled || en == "disabled"))
		allowedActive := ac == u.AfterActive || (c.Phase == "pending" && ac == u.BeforeActive)
		if !allowedEnabled || !allowedActive {
			return fmt.Errorf("%s was changed outside Zoomies; refusing to overwrite it", u.Name)
		}
	}

	for _, op := range c.Operations {
		p, after, before := op.Path, op.Value, op.Previous
		if len(op.Do) >= 3 && op.Do[0] == "sysctl" {
			key, val, _ := strings.Cut(op.Do[2], "=")
			p = "/proc/sys/" + strings.ReplaceAll(key, ".", "/")
			after = val
			_, before, _ = strings.Cut(op.Undo[2], "=")
		}
		if p != "" {
			v, err := read(e, p)
			if err != nil {
				return err
			}
			if v != after && !(c.Phase == "pending" && v == before) {
				return fmt.Errorf("%s was changed outside Zoomies; refusing to overwrite it", p)
			}
		}
		if len(op.Undo) > 2 && op.Undo[0] == "apt-get" {
			running, err := command(ctx, e, "uname", "-r")
			if err != nil {
				return err
			}
			for _, pkg := range op.Undo[4:] {
				if strings.Contains(pkg, running) {
					return fmt.Errorf("the installed HWE kernel is running; boot the previous kernel before reverting")
				}
			}
			plan, err := command(ctx, e, "apt-get", append([]string{"--simulate", "remove", "--"}, op.Undo[4:]...)...)
			if err != nil {
				return fmt.Errorf("cannot verify package reversal")
			}
			allowed := map[string]bool{}
			for _, pkg := range op.Undo[4:] {
				allowed[pkg] = true
			}
			for _, l := range strings.Split(plan, "\n") {
				f := strings.Fields(l)
				if len(f) > 1 && ((f[0] == "Remv" && !allowed[f[1]]) || f[0] == "Inst") {
					return fmt.Errorf("package reversal would change an unrelated package: %s", f[1])
				}
			}
		}
	}
	return nil
}
func (e *Engine) execute(ctx context.Context, o Operation, undo bool) error {
	if o.Path != "" {
		v := o.Value
		if undo {
			v = o.Previous
		}
		return e.System.WriteValue(o.Path, v)
	}
	a := o.Do
	if undo {
		a = o.Undo
	}
	if len(a) == 0 {
		return nil
	}
	out, err := e.System.Run(ctx, a[0], a[1:]...)
	if err != nil {
		return fmt.Errorf("%s: %s: %w", a[0], out, err)
	}
	return nil
}

// Apply writes the complete reversal plan before any host mutation. A pending
// record is retained after any failure so a later revert can recover it.
func (e *Engine) Apply(ctx context.Context, c Change, actor string) error {
	if !e.Supported() || e.Container || e.UID != 0 {
		return fmt.Errorf("tuning requires root on a supported Linux host outside a container")
	}
	unlock, err := e.System.Lock(StateDir + "/lock")
	if err != nil {
		return err
	}
	defer unlock()
	s, err := e.LoadState()
	if err != nil {
		return err
	}
	for _, old := range s.Changes {
		if old.Phase == "pending" {
			return fmt.Errorf("an interrupted change needs --revert first: %s", old.ID)
		}
		if old.ID == c.ID && old.Phase == "applied" {
			return nil
		}
	}
	for _, f := range c.Files {
		now, err := snapshot(e, f.Path)
		if err != nil {
			return err
		}
		if now.Exists != f.Before.Exists || !bytes.Equal(now.Data, f.Before.Data) || (now.Exists && (now.Mode != f.Before.Mode || now.UID != f.Before.UID || now.GID != f.Before.GID)) {
			return fmt.Errorf("%s changed after preview; run tune again", f.Path)
		}
	}
	c.At = e.Now().UTC()
	c.Actor = actor
	c.Phase = "pending"
	if c.DockerRestart {
		s.DockerRestartPending = true
	}
	s.Changes = append(s.Changes, c)
	if err = e.saveState(s); err != nil {
		return err
	}
	for i, f := range c.Files {
		if f.Before.Exists {
			backup := filepath.Join(StateDir, "backups", fmt.Sprintf("%d-%s-%d", c.At.UnixNano(), c.ID, i))
			if err = e.System.WriteFile(backup, f.Before.Data, 0600); err != nil {
				return err
			}
		}
		if err = e.System.WriteFile(f.Path, f.After, f.Mode); err != nil {
			return err
		}
	}
	for _, o := range c.Operations {
		if err = e.execute(ctx, o, false); err != nil {
			return err
		}
	}
	s.Changes[len(s.Changes)-1].Phase = "applied"
	return e.saveState(s)
}
func (e *Engine) Revert(ctx context.Context, only, skip map[string]bool, dry bool) ([]Change, error) {
	if !e.Supported() || e.Container || e.UID != 0 {
		return nil, fmt.Errorf("revert requires root on a supported Linux host")
	}
	var unlock func()
	var err error
	if !dry {
		unlock, err = e.System.Lock(StateDir + "/lock")
		if err != nil {
			return nil, err
		}
		defer unlock()
	}
	s, err := e.LoadState()
	if err != nil {
		return nil, err
	}
	var out []Change
	virtual := map[string]Snapshot{}
	// Shared drop-ins must unwind in reverse order; a selective revert of an
	// earlier edit is refused if a later live edit touched the same file.
	for i := len(s.Changes) - 1; i >= 0; i-- {
		c := s.Changes[i]
		if c.Phase == "reverted" || skip[c.ID] || (len(only) > 0 && !only[c.ID]) {
			continue
		}
		for _, f := range c.Files {
			for j := i + 1; j < len(s.Changes); j++ {
				if s.Changes[j].Phase == "reverted" {
					continue
				}
				for _, later := range s.Changes[j].Files {
					if later.Path == f.Path {
						return out, fmt.Errorf("revert %s first because it also edits %s", s.Changes[j].ID, f.Path)
					}
				}
			}
			now, err := snapshot(e, f.Path)
			if dry {
				if v, ok := virtual[f.Path]; ok {
					now = v
					err = nil
				}
			}
			if err != nil {
				return out, err
			}
			if (!bytes.Equal(now.Data, f.After) && !(now.Exists == f.Before.Exists && bytes.Equal(now.Data, f.Before.Data))) || (now.Exists && f.Before.Exists && (now.UID != f.Before.UID || now.GID != f.Before.GID || now.Mode != f.Mode)) {
				return out, fmt.Errorf("%s was changed outside Zoomies; refusing to overwrite it", f.Path)
			}
		}
		if err = e.verifyRevert(ctx, c); err != nil {
			return out, err
		}
		out = append(out, c)
		if dry {
			for _, f := range c.Files {
				virtual[f.Path] = f.Before
			}
			s.Changes[i].Phase = "reverted"
			continue
		}
		for _, f := range c.Files {
			if f.Before.Exists {
				err = e.System.WriteFile(f.Path, f.Before.Data, f.Before.Mode)
			} else {
				err = e.System.Remove(f.Path)
				if errors.Is(err, fs.ErrNotExist) {
					err = nil
				}
			}
			if err != nil {
				return out, err
			}
		}
		for j := len(c.Operations) - 1; j >= 0; j-- {
			if err = e.execute(ctx, c.Operations[j], true); err != nil {
				return out, err
			}
		}
		s.Changes[i].Phase = "reverted"
		if c.DockerRestart {
			s.DockerRestartPending = true
		}
		if err = e.saveState(s); err != nil {
			return out, err
		}
	}
	return out, nil
}

package hosttune

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

const sysctlFile = "/etc/sysctl.d/90-zoomies.conf"

func baseChecks() []Check {
	checks := []Check{
		sysctl("inotify.watches", "File watches", "fs.inotify.max_user_watches", 524288, Safe, "Large checkouts and build tools need enough file watches."),
		sysctl("inotify.instances", "File watch instances", "fs.inotify.max_user_instances", 1024, Safe, "Concurrent runners each need their own watch instances."),
		sysctl("files.maximum", "System file descriptors", "fs.file-max", 2097152, Safe, "Concurrent builds need enough system-wide file descriptors."),
		{ID: "files.service", Title: "Runner service file descriptors", Tier: Safe, Rationale: "The runner service needs enough open files for concurrent builds.", Detect: detectServiceLimit, Plan: planServiceLimit},
		{ID: "docker.logs", Title: "Docker log rotation", Tier: Safe, Rationale: "Rotating JSON logs prevents them from filling the host disk.", Detect: detectLogs, Plan: planLogs},
		{ID: "docker.storage", Title: "Docker storage driver", Tier: Safe, Rationale: "overlay2 is the supported baseline for this host configuration.", Detect: func(ctx context.Context, e *Engine) Result {
			v, err := dockerInfo(ctx, e, "{{.Driver}}")
			if err != nil {
				return Result{Status: Skip, Reason: "Docker information is unavailable: " + v}
			}
			s := OK
			if v != "overlay2" {
				s = Warn
			}
			return Result{Status: s, Current: v, Recommended: "overlay2"}
		}},
		{ID: "cgroup.version", Title: "Control groups", Tier: Safe, Rationale: "Control groups version 2 gives consistent resource accounting.", Detect: func(ctx context.Context, e *Engine) Result {
			_, err := e.System.Stat("/sys/fs/cgroup/cgroup.controllers")
			v, s := "v2", OK
			if err != nil {
				v, s = "v1 or unavailable", Warn
			}
			return Result{Status: s, Current: v, Recommended: "v2"}
		}},
		{ID: "work.filesystem", Title: "Work directory filesystem", Tier: Safe, Rationale: "Local ext4 or XFS with noatime avoids extra metadata writes.", Detect: mountCheck(false)},
		{ID: "docker.filesystem", Title: "Docker root filesystem", Tier: Safe, Rationale: "Docker layers benefit from local ext4 or XFS with noatime.", Detect: mountCheck(true)},
		{ID: "disk.space", Title: "Work directory free space", Tier: Safe, Rationale: "Keep at least 10% and 10 GiB free for new builds.", Detect: diskCheck(false)},
		{ID: "disk.inodes", Title: "Work directory free inodes", Tier: Safe, Rationale: "Many small build files can exhaust inodes before disk space.", Detect: diskCheck(true)},
		{ID: "cpu.governor", Title: "CPU frequency governor", Tier: Aggressive, Rationale: "Performance mode reduces frequency scaling delays at the cost of power.", Detect: detectGovernor, Plan: planGovernor},
		sysctl("memory.swappiness", "Swappiness", "vm.swappiness", 10, Aggressive, "Less swapping can improve build latency when RAM is sufficient."),
		{ID: "tmp.tmpfs", Title: "Temporary directory in memory", Tier: Aggressive, Optional: true, Rationale: "A memory-backed /tmp can speed temporary work but consumes RAM.", Detect: func(ctx context.Context, e *Engine) Result {
			v, err := command(ctx, e, "findmnt", "-n", "-o", "FSTYPE", "--target", "/tmp")
			if err != nil {
				return unavailable(err)
			}
			s := Warn
			if v == "tmpfs" {
				s = OK
			}
			r := Result{Status: s, Current: v, Recommended: "tmpfs with a 25% RAM cap, at the next planned boot"}
			if s == Warn {
				unit, err := command(ctx, e, "systemctl", "show", "tmp.mount", "--property=LoadState", "--value")
				if err != nil || unit != "loaded" {
					r.Reason = "advice only: no existing tmp.mount unit; configure a memory-backed /tmp manually after reviewing RAM"
				} else if managedUnitPolicy(ctx, e, "tmp.mount", "What", "Type", "Options") {
					r.Reason = "temporary directory mount policy is managed elsewhere"
				}
				b, _ := read(e, "/etc/fstab")
				for _, line := range strings.Split(b, "\n") {
					f := strings.Fields(line)
					if len(f) > 1 && !strings.HasPrefix(f[0], "#") && f[1] == "/tmp" {
						r.Reason = "temporary directory mount policy is already managed in /etc/fstab"
					}
				}

			}
			return r
		}, Plan: planTmpfs},
	}
	return checks
}
func sysctl(id, title, key string, want int64, t Tier, why string) Check {
	return Check{ID: id, Title: title, Tier: t, Rationale: why, Detect: func(ctx context.Context, e *Engine) Result {
		p := "/proc/sys/" + strings.ReplaceAll(key, ".", "/")
		v, err := read(e, p)
		if err != nil {
			return unavailable(err)
		}
		r := Result{Status: Warn, Current: v, Recommended: strconv.FormatInt(want, 10)}
		if (key != "vm.swappiness" && number(v) >= want) || (key == "vm.swappiness" && number(v) <= want) {
			r.Status = OK
			return r
		}
		if e.Container {
			r.Status = Skip
			r.Reason = "container or LXC; the outer host owns this setting"
			return r
		}
		if i, err := e.System.Stat(p); err == nil && i.Mode().Perm()&0200 == 0 {
			r.Status = Skip
			r.Reason = "read-only kernel setting"
			return r
		}
		r.Reason = managedSysctl(e, key)
		return r
	}, Plan: func(ctx context.Context, e *Engine, r Result) (Change, error) {
		before, err := snapshot(e, sysctlFile)
		if err != nil {
			return Change{}, err
		}
		after := setAssignment(string(before.Data), key, r.Recommended)
		return Change{ID: id, Files: []FileChange{{Path: sysctlFile, Before: before, After: []byte(after), Mode: snapshotMode(before)}}, Operations: []Operation{{Do: []string{"sysctl", "-w", key + "=" + r.Recommended}, Undo: []string{"sysctl", "-w", key + "=" + r.Current}}}, Previous: r.Current, New: r.Recommended}, nil
	}}
}
func managedSysctl(e *Engine, key string) string {
	for _, dir := range []string{"/etc/sysctl.d", "/run/sysctl.d", "/usr/local/lib/sysctl.d", "/usr/lib/sysctl.d", "/lib/sysctl.d"} {
		entries, err := e.System.ReadDir(dir)
		if err != nil {
			if !errors.Is(err, fs.ErrNotExist) {
				return "cannot inspect " + dir + " for managed settings"
			}
			continue
		}
		for _, entry := range entries {
			p := filepath.Join(dir, entry.Name())
			if p == sysctlFile || !strings.HasSuffix(p, ".conf") {
				continue
			}
			b, err := read(e, p)
			if err != nil {
				return "cannot inspect " + p
			}
			if assigns(b, key) {
				return "already managed in " + p
			}
		}
	}
	b, err := read(e, "/etc/sysctl.conf")
	if err == nil && assigns(b, key) {
		return "already managed in /etc/sysctl.conf"
	}
	b, _ = read(e, sysctlFile)
	if managed(b) {
		return "configuration management marker in " + sysctlFile
	}
	return ""
}
func managed(s string) bool {
	s = strings.ToLower(s)
	for _, v := range []string{"ansible", "puppet", "chef", "saltstack", "do not edit", "managed by"} {
		if strings.Contains(s, v) {
			return true
		}
	}
	return false
}
func assigns(s, key string) bool {
	for _, l := range strings.Split(s, "\n") {
		l = strings.TrimSpace(strings.SplitN(l, "#", 2)[0])
		k, _, ok := strings.Cut(l, "=")
		if ok && strings.ReplaceAll(strings.TrimSpace(k), "/", ".") == key {
			return true
		}
	}
	return false
}
func setAssignment(s, key, value string) string {
	var out []string
	found := false
	for _, l := range strings.Split(strings.TrimSuffix(s, "\n"), "\n") {
		k, _, ok := strings.Cut(l, "=")
		if ok && strings.TrimSpace(k) == key {
			l = key + " = " + value
			found = true
		}
		if l != "" {
			out = append(out, l)
		}
	}
	if !found {
		out = append(out, key+" = "+value)
	}
	return strings.Join(out, "\n") + "\n"
}
func service(ctx context.Context, e *Engine) (string, string, error) {
	for _, u := range []string{"zoomies-agent.service", "zoomies.service"} {
		v, err := command(ctx, e, "systemctl", "show", u, "--property=LoadState", "--value")
		if err == nil && v == "loaded" {
			limit, err := command(ctx, e, "systemctl", "show", u, "--property=LimitNOFILE", "--value")
			return u, limit, err
		}
	}
	return "", "", fs.ErrNotExist
}
func detectServiceLimit(ctx context.Context, e *Engine) Result {
	u, v, err := service(ctx, e)
	if err != nil {
		return Result{Status: Skip, Reason: "no native Zoomies systemd service; container limits belong to the deployment"}
	}
	r := Result{Status: Warn, Current: v, Recommended: "65536"}
	if v == "infinity" || number(v) >= 65536 {
		r.Status = OK
	}
	if managedDropins(ctx, e, u) {
		r.Reason = "service limits are managed in another drop-in"
	}
	return r
}
func managedDropins(ctx context.Context, e *Engine, u string) bool {
	v, err := command(ctx, e, "systemctl", "show", u, "--property=DropInPaths", "--value")
	if err != nil {
		return true
	}
	for _, p := range strings.Fields(v) {
		b, err := read(e, p)
		if err != nil || managed(b) || (strings.Contains(b, "LimitNOFILE") && !strings.HasSuffix(p, "/90-zoomies.conf")) {
			return true
		}
	}
	return false
}

// Existing drop-ins and management markers belong to their administrator.
func managedUnitPolicy(ctx context.Context, e *Engine, u string, keys ...string) bool {
	paths, err := command(ctx, e, "systemctl", "show", u, "--property=DropInPaths", "--value")
	if err != nil {
		return true
	}
	fragment, err := command(ctx, e, "systemctl", "show", u, "--property=FragmentPath", "--value")
	if err != nil {
		return true
	}
	if b, err := read(e, fragment); err == nil && managed(b) {
		return true
	}
	for _, p := range strings.Fields(paths) {
		b, err := read(e, p)
		if err != nil || managed(b) {
			return true
		}
		if strings.HasSuffix(p, "/90-zoomies.conf") {
			continue
		}
		for _, k := range keys {
			if assigns(b, k) {
				return true
			}
		}
	}
	return false
}
func planServiceLimit(ctx context.Context, e *Engine, r Result) (Change, error) {
	u, _, err := service(ctx, e)
	if err != nil {
		return Change{}, err
	}
	p := "/etc/systemd/system/" + u + ".d/90-zoomies.conf"
	f, err := fileChange(e, p, "[Service]\nLimitNOFILE=65536\n")
	return Change{ID: r.ID, Previous: r.Current, New: r.Recommended, Files: []FileChange{f}, Operations: []Operation{{Do: []string{"systemctl", "daemon-reload"}, Undo: []string{"systemctl", "daemon-reload"}}}, Notice: "The service limit takes effect next time the Zoomies service starts. Drain jobs before restarting it."}, err
}
func dockerInfo(ctx context.Context, e *Engine, format string) (string, error) {
	a := []string{}
	if e.DockerHost != "" {
		a = append(a, "--host", e.DockerHost)
	}
	a = append(a, "info", "--format", format)
	return command(ctx, e, "docker", a...)
}
func detectLogs(ctx context.Context, e *Engine) Result {
	r := Result{Status: Warn, Recommended: "json-file: max-size 10m, max-file 3"}
	v, err := dockerInfo(ctx, e, "{{.LoggingDriver}}")
	if err != nil {
		return Result{Status: Skip, Reason: "Docker information is unavailable: " + v}
	}
	if security, err := dockerInfo(ctx, e, "{{json .SecurityOptions}}"); err != nil {
		return Result{Status: Skip, Reason: "cannot establish whether the Docker daemon is rootless"}
	} else if strings.Contains(security, "rootless") {
		return Result{Status: Skip, Reason: "rootless Docker uses the owning user's daemon configuration"}
	}
	if e.DockerHost != "" && e.DockerHost != "unix:///var/run/docker.sock" {
		return Result{Status: Skip, Reason: "custom Docker socket; local /etc/docker/daemon.json may not control it"}
	}
	if v != "json-file" {
		return Result{Status: Skip, Current: v, Recommended: r.Recommended, Reason: "another logging driver is configured; leave its policy unchanged"}
	}
	b, err := e.System.ReadFile("/etc/docker/daemon.json")
	if err != nil && !errors.Is(err, fs.ErrNotExist) {
		return unavailable(err)
	}
	var doc map[string]any
	if len(b) > 0 {
		if err = json.Unmarshal(b, &doc); err != nil {
			return Result{Status: Error, Reason: "daemon.json is invalid JSON"}
		}
	}
	r.Current = "json-file without explicit rotation"
	opts, _ := doc["log-opts"].(map[string]any)
	if opts != nil {
		r.Current = fmt.Sprint(opts)
		size, _ := opts["max-size"].(string)
		files, _ := opts["max-file"].(string)
		if size != "" && size != "-1" && number(files) > 0 {
			r.Status = OK
		}
	}
	if managed(string(b)) {
		r.Reason = "daemon.json is managed elsewhere"
	}
	if e.DockerHost != "" && !strings.HasPrefix(e.DockerHost, "unix:///") {
		r.Status = Skip
		r.Reason = "Docker endpoint is remote; local daemon.json does not control it"
	}
	return r
}

// MergeDockerLogs preserves unrelated settings and logging options.
func MergeDockerLogs(b []byte) ([]byte, error) {
	doc := map[string]any{}
	if len(b) > 0 {
		if err := json.Unmarshal(b, &doc); err != nil {
			return nil, err
		}
		if doc == nil {
			return nil, fmt.Errorf("daemon.json must be an object")
		}
	}
	if d, ok := doc["log-driver"]; ok && d != "json-file" {
		return nil, fmt.Errorf("refusing to replace logging driver %v", d)
	}
	doc["log-driver"] = "json-file"
	opts := map[string]any{}
	if v, ok := doc["log-opts"]; ok {
		var valid bool
		opts, valid = v.(map[string]any)
		if !valid {
			return nil, fmt.Errorf("log-opts must be an object")
		}
	}
	opts["max-size"] = "10m"
	opts["max-file"] = "3"
	doc["log-opts"] = opts
	b, err := json.MarshalIndent(doc, "", "  ")
	return append(b, '\n'), err
}
func planLogs(ctx context.Context, e *Engine, r Result) (Change, error) {
	p := "/etc/docker/daemon.json"
	s, err := snapshot(e, p)
	if err != nil {
		return Change{}, err
	}
	b, err := MergeDockerLogs(s.Data)
	if err != nil {
		return Change{}, err
	}
	return Change{ID: r.ID, Previous: r.Current, New: r.Recommended, Files: []FileChange{{Path: p, Before: s, After: b, Mode: snapshotMode(s)}}, DockerRestart: true, Notice: "Docker must restart to load this policy; it applies to newly created containers."}, nil
}
func mountCheck(docker bool) func(context.Context, *Engine) Result {
	return func(ctx context.Context, e *Engine) Result {
		p := e.WorkDir
		if docker {
			p = e.DockerRoot
			if p == "" {
				v, err := dockerInfo(ctx, e, "{{.DockerRootDir}}")
				if err != nil {
					return Result{Status: Skip, Reason: "Docker root is unavailable"}
				}
				p = v
			}
		}
		if e.Container {
			return Result{Status: Skip, Reason: "container mount view does not describe the outer host"}
		}
		v, err := command(ctx, e, "findmnt", "-n", "-o", "FSTYPE,OPTIONS", "--target", p)
		if err != nil {
			return Result{Status: Skip, Reason: "filesystem is unavailable: " + p}
		}
		s := Warn
		if (strings.HasPrefix(v, "ext4 ") || strings.HasPrefix(v, "xfs ")) && strings.Contains(","+strings.ReplaceAll(v, " ", ",")+",", ",noatime,") {
			s = OK
		}
		return Result{Status: s, Current: p + ": " + v, Recommended: "ext4 or XFS with noatime", Reason: "advice only; review mount settings, with the host cordoned, before changing them"}
	}
}
func diskCheck(inodes bool) func(context.Context, *Engine) Result {
	return func(ctx context.Context, e *Engine) Result {
		a := "-Pk"
		rec := "at least 10% and 10 GiB free"
		if inodes {
			a = "-Pi"
			rec = "at least 10% free inodes"
		}
		v, err := command(ctx, e, "df", a, "--", e.WorkDir)
		if err != nil {
			return Result{Status: Skip, Reason: "work directory is unavailable"}
		}
		ls := strings.Split(v, "\n")
		if len(ls) < 2 {
			return Result{Status: Error, Reason: "cannot read df output"}
		}
		f := strings.Fields(ls[len(ls)-1])
		if len(f) < 6 {
			return Result{Status: Error, Reason: "cannot read df columns"}
		}
		total, free := number(f[1]), number(f[3])
		if total <= 0 {
			return Result{Status: Skip, Reason: "filesystem does not report a usable capacity"}
		}
		s := OK
		if free*100/total < 10 || (!inodes && free < 10*1024*1024) {
			s = Warn
		}
		// df -P reports 1 KiB blocks, which nobody reads at a glance; the status
		// rule above is untouched, only the words an operator sees changed.
		amount := fmt.Sprintf("%d inodes", free)
		if !inodes {
			amount = formatKiB(free)
		}
		return Result{Status: s, Current: fmt.Sprintf("%d%% free (%s)", free*100/total, amount), Recommended: rec}
	}
}

// formatKiB renders a df block count in the largest unit that keeps it short:
// GiB to one decimal, whole MiB under a GiB, KiB under a MiB.
func formatKiB(k int64) string {
	switch {
	case k >= 1024*1024:
		return fmt.Sprintf("%.1f GiB", float64(k)/(1024*1024))
	case k >= 1024:
		return fmt.Sprintf("%d MiB", k/1024)
	}
	return fmt.Sprintf("%d KiB", k)
}
func governorPaths(e *Engine) []string {
	es, _ := e.System.ReadDir("/sys/devices/system/cpu/cpufreq")
	var out []string
	for _, x := range es {
		if strings.HasPrefix(x.Name(), "policy") {
			out = append(out, "/sys/devices/system/cpu/cpufreq/"+x.Name()+"/scaling_governor")
		}
	}
	sort.Strings(out)
	return out
}
func detectGovernor(ctx context.Context, e *Engine) Result {
	ps := governorPaths(e)
	if len(ps) == 0 {
		return Result{Status: Skip, Reason: "CPU governor is not exposed (common in VMs)"}
	}
	r := Result{Status: OK, Recommended: "performance"}
	var vs []string
	for _, p := range ps {
		v, err := read(e, p)
		if err != nil {
			return unavailable(err)
		}
		vs = append(vs, filepath.Base(filepath.Dir(p))+"="+v)
		if v != "performance" {
			r.Status = Warn
		}
		a, err := read(e, filepath.Join(filepath.Dir(p), "scaling_available_governors"))
		if err != nil || !strings.Contains(" "+a+" ", " performance ") {
			r.Status = Skip
			r.Reason = "performance governor is not available"
		}
	}
	r.Current = strings.Join(vs, ", ")
	if r.Status == Warn {
		v, err := command(ctx, e, "systemctl", "show", "cpupower.service", "--property=LoadState", "--value")
		if err != nil || v != "loaded" {
			r.Reason = "persistent tuning needs the distribution's cpupower.service; install its CPU frequency tools first"
		} else if managedUnitPolicy(ctx, e, "cpupower.service", "ExecStart", "Environment") {
			r.Reason = "CPU governor service policy is managed elsewhere"
		}

	}
	return r
}
func planGovernor(ctx context.Context, e *Engine, r Result) (Change, error) {
	// A systemd service drop-in persists the choice; runtime writes and their
	// individual previous values are journalled separately.
	c := Change{ID: r.ID, Previous: r.Current, New: "performance"}
	for _, p := range governorPaths(e) {
		v, err := read(e, p)
		if err != nil {
			return c, err
		}
		c.Operations = append(c.Operations, Operation{Path: p, Value: "performance", Previous: v})
	}
	// cpupower is distribution supplied; do not invent a shell script or assume
	// it is installed. Its existing service provides the persistence point.
	v, err := command(ctx, e, "systemctl", "show", "cpupower.service", "--property=LoadState", "--value")
	if err != nil || v != "loaded" {
		return c, fmt.Errorf("persistent CPU governor tuning needs an installed cpupower.service; install the distribution's CPU frequency tools first")
	}
	f, err := fileChange(e, "/etc/systemd/system/cpupower.service.d/90-zoomies.conf", "[Service]\nExecStart=\nExecStart=/usr/bin/cpupower frequency-set -g performance\n")
	if err != nil {
		return c, err
	}
	c.Files = []FileChange{f}
	c.Operations = append(c.Operations, Operation{Do: []string{"systemctl", "daemon-reload"}, Undo: []string{"systemctl", "daemon-reload"}})
	enabled, err := command(ctx, e, "systemctl", "show", "cpupower.service", "--property=UnitFileState", "--value")
	if err != nil {
		return c, err
	}
	if enabled == "disabled" {
		c.Operations = append(c.Operations, Operation{Do: []string{"systemctl", "enable", "cpupower.service"}, Undo: []string{"systemctl", "disable", "cpupower.service"}})
	} else if enabled != "enabled" {
		return c, fmt.Errorf("cpupower service state cannot be restored safely: %s", enabled)
	}
	c.Notice = "The existing cpupower service restores the governor at boot; previous service enablement and each CPU policy are recorded."
	return c, nil
}

func planTmpfs(ctx context.Context, e *Engine, r Result) (Change, error) {
	unit, err := command(ctx, e, "systemctl", "show", "tmp.mount", "--property=UnitFileState", "--value")
	if err != nil {
		return Change{}, err
	}
	if unit != "enabled" && unit != "disabled" {
		return Change{}, fmt.Errorf("tmp.mount enablement cannot be restored safely: %s", unit)
	}
	f, err := fileChange(e, "/etc/systemd/system/tmp.mount.d/90-zoomies.conf", "[Mount]\nWhat=tmpfs\nType=tmpfs\nOptions=mode=1777,size=25%\n")
	if err != nil {
		return Change{}, err
	}
	c := Change{ID: r.ID, Previous: r.Current, New: r.Recommended, Files: []FileChange{f}, Operations: []Operation{{Do: []string{"systemctl", "daemon-reload"}, Undo: []string{"systemctl", "daemon-reload"}}}, Notice: "No active /tmp files are hidden or moved. The mount is enabled only for the next planned boot; drain before rebooting. Revert restores the drop-in and enablement; if it has since booted, drain and reboot again to change the live mount."}
	if unit == "disabled" {
		c.Operations = append(c.Operations, Operation{Do: []string{"systemctl", "enable", "tmp.mount"}, Undo: []string{"systemctl", "disable", "tmp.mount"}})
	}
	return c, nil
}

package hosttune

import (
	"context"
	"encoding/json"
	"fmt"
	"path/filepath"
	"strings"
)

var dedicatedUnits = []string{"snapd.service", "ModemManager.service", "multipathd.service", "apport.service", "motd-news.service", "udisks2.service", "fwupd.service", "cloud-init.service"}

func dedicatedChecks() []Check {
	var out []Check
	for _, unit := range dedicatedUnits {
		out = append(out, unitCheck(unit))
	}
	for _, u := range []string{"apt-daily.timer", "apt-daily-upgrade.timer"} {
		out = append(out, unitCheck(u))
	}
	out = append(out, Check{ID: "journal.size", Title: "Journal disk usage cap", Tier: Dedicated, Rationale: "A journal size cap leaves more disk space available for builds.", Detect: detectJournal, Plan: planJournal},
		Check{ID: "memory.swap-off", Title: "Disable swap", Tier: Dedicated, Optional: true, Rationale: "On a host with at least 32 GiB RAM, disabling swap can reduce latency but increases out-of-memory risk.", Detect: detectSwap, Plan: planSwap})
	return out
}
func unitID(u string) string {
	return "service." + strings.TrimSuffix(strings.TrimSuffix(u, ".service"), ".timer")
}
func unitFamily(u string) []string {
	switch u {
	case "snapd.service":
		return []string{u, "snapd.socket", "snapd.seeded.service", "snapd.apparmor.service", "snapd.autoimport.service"}
	case "multipathd.service":
		return []string{u, "multipathd.socket"}
	case "motd-news.service":
		return []string{u, "motd-news.timer"}
	case "cloud-init.service":
		return []string{u, "cloud-init-local.service", "cloud-config.service", "cloud-final.service"}
	}
	return []string{u}
}
func familyGuard(ctx context.Context, e *Engine, u string) string {
	for _, member := range unitFamily(u) {
		enabled, active, err := unitState(ctx, e, member)
		if err != nil {
			if member == u {
				return err.Error()
			}
			continue
		}
		if enabled != "enabled" && enabled != "disabled" && enabled != "static" && enabled != "masked" {
			return "unit state cannot be restored safely: " + member + " " + enabled
		}
		if active != "active" && active != "inactive" {
			return "unit is not settled: " + member + " " + active
		}
		if reason := unitGuard(ctx, e, member); reason != "" {
			return reason
		}
	}
	return ""
}
func allowedUnit(u string) bool {
	for _, a := range dedicatedUnits {
		if u == a {
			return true
		}
	}
	switch u {
	case "apt-daily.timer", "apt-daily-upgrade.timer", "snapd.socket", "snapd.seeded.service", "snapd.apparmor.service", "snapd.autoimport.service", "multipathd.socket", "motd-news.timer", "cloud-init-local.service", "cloud-config.service", "cloud-final.service":
		return true
	}
	return false
}
func unitState(ctx context.Context, e *Engine, u string) (enabled, active string, err error) {
	v, err := command(ctx, e, "systemctl", "show", u, "--property=LoadState", "--property=UnitFileState", "--property=ActiveState")
	if err != nil {
		return "", "", err
	}
	load := ""
	for _, l := range strings.Split(v, "\n") {
		k, x, _ := strings.Cut(l, "=")
		switch k {
		case "LoadState":
			load = x
		case "UnitFileState":
			enabled = x
		case "ActiveState":
			active = x
		}
	}
	if load == "not-found" || load == "" {
		return "", "", fmt.Errorf("unit is not installed")
	}
	return
}
func unitGuard(ctx context.Context, e *Engine, u string) string {
	if strings.HasPrefix(u, "apt-daily") && !e.SecurityMaintenanceReady {
		return "security-update maintenance window is not configured; leave automatic updates enabled"
	}
	if strings.HasPrefix(u, "snapd") {
		v, err := command(ctx, e, "snap", "list")
		if err != nil {
			return "cannot verify installed snaps"
		}
		for i, l := range strings.Split(v, "\n") {
			f := strings.Fields(l)
			if i == 0 || len(f) == 0 {
				continue
			}
			n := f[0]
			if n != "core" && n != "core18" && n != "core20" && n != "core22" && n != "core24" {
				return "a non-core snap is installed: " + n
			}
		}
	}
	if u == "fwupd.service" {
		v, err := command(ctx, e, "systemd-detect-virt", "--vm")
		if err != nil || v == "none" || v == "" {
			return "fwupd may only be disabled on a confirmed virtual machine"
		}
	}
	if u == "cloud-init.service" {
		v, err := command(ctx, e, "cloud-init", "status", "--format", "json")
		var status struct {
			Status string `json:"status"`
		}
		if err != nil || json.Unmarshal([]byte(v), &status) != nil || status.Status != "done" {
			return "cloud-init has not been confirmed complete"
		}
	}
	v, err := command(ctx, e, "systemctl", "list-dependencies", "--reverse", "--all", "--plain", "--no-pager", u)
	if err != nil {
		return "cannot verify reverse dependencies"
	}
	for _, l := range strings.Split(v, "\n") {
		f := strings.Fields(strings.TrimSpace(l))
		if len(f) == 0 {
			continue
		}
		name := f[len(f)-1]
		if name == u {
			continue
		}
		if strings.Contains(name, ".") && !allowedUnit(name) {
			return "another unit depends on it: " + name
		}
	}
	return ""
}
func unitCheck(u string) Check {
	return Check{ID: unitID(u), Title: "Disable " + u + " (dedicated hosts only)", Tier: Dedicated, Rationale: "Disable and mask an unused service only on a host dedicated to Zoomies.", Detect: func(ctx context.Context, e *Engine) Result {
		enabled, active, err := unitState(ctx, e, u)
		if err != nil {
			return Result{Status: Skip, Reason: err.Error()}
		}
		r := Result{Status: Warn, Current: enabled + ", " + active, Recommended: "disabled and masked"}
		allMasked := true
		for _, member := range unitFamily(u) {
			en, ac, er := unitState(ctx, e, member)
			if er == nil && (en != "masked" || ac != "inactive") {
				allMasked = false
			}
		}
		if allMasked && strings.HasPrefix(enabled, "masked") && active != "active" {
			r.Status = OK
			return r
		}
		if enabled != "enabled" && enabled != "disabled" && enabled != "static" && enabled != "masked" {
			r.Status = Skip
			r.Reason = "unit state cannot be restored safely: " + enabled
			return r
		}
		if reason := familyGuard(ctx, e, u); reason != "" {
			r.Status = Skip
			if strings.HasPrefix(u, "apt-daily") {
				r.Status = Warn
			}
			r.Reason = reason
		}
		return r
	}, Plan: func(ctx context.Context, e *Engine, r Result) (Change, error) {
		if reason := familyGuard(ctx, e, u); reason != "" {
			return Change{}, fmt.Errorf("%s", reason)
		}

		c := Change{ID: r.ID, Previous: r.Current, New: "disabled and masked"}
		for _, member := range unitFamily(u) {
			enabled, active, err := unitState(ctx, e, member)
			if err != nil {
				if member == u {
					return Change{}, err
				}
				continue
			}
			if enabled == "masked" && active == "inactive" {
				continue
			}
			c.Units = append(c.Units, UnitChange{Name: member, BeforeEnabled: enabled, BeforeActive: active, AfterEnabled: "masked", AfterActive: "inactive"})
			if active == "active" {
				c.Operations = append(c.Operations, Operation{Do: []string{"systemctl", "stop", member}, Undo: []string{"systemctl", "start", member}})
			}
			if enabled == "enabled" {
				c.Operations = append(c.Operations, Operation{Do: []string{"systemctl", "disable", member}, Undo: []string{"systemctl", "enable", member}})
			}
			if enabled != "masked" {
				c.Operations = append(c.Operations, Operation{Do: []string{"systemctl", "mask", member}, Undo: []string{"systemctl", "unmask", member}})
			}
		}

		return c, nil
	}}
}
func detectJournal(ctx context.Context, e *Engine) Result {
	path := "/etc/systemd/journald.conf.d/90-zoomies.conf"
	current := "distribution default"
	s := Warn
	for _, dir := range []string{"/etc/systemd/journald.conf.d", "/run/systemd/journald.conf.d", "/usr/lib/systemd/journald.conf.d"} {
		entries, _ := e.System.ReadDir(dir)
		for _, x := range entries {
			p := filepath.Join(dir, x.Name())
			b, err := read(e, p)
			if err != nil {
				continue
			}
			if strings.Contains(b, "SystemMaxUse=") {
				if p != path || managed(b) {
					return Result{Status: Warn, Current: p, Recommended: "1G", Reason: "journal size already managed elsewhere"}
				}
				current = b
				if strings.Contains(b, "SystemMaxUse=1G") {
					s = OK
				}
			}
		}
	}
	b, _ := read(e, "/etc/systemd/journald.conf")
	if assigns(b, "SystemMaxUse") {
		return Result{Status: Warn, Current: "/etc/systemd/journald.conf", Recommended: "1G", Reason: "journal size already managed elsewhere"}
	}
	return Result{Status: s, Current: current, Recommended: "1G"}
}
func planJournal(ctx context.Context, e *Engine, r Result) (Change, error) {
	f, err := fileChange(e, "/etc/systemd/journald.conf.d/90-zoomies.conf", "[Journal]\nSystemMaxUse=1G\n")
	return Change{ID: r.ID, Previous: r.Current, New: r.Recommended, Files: []FileChange{f}, Notice: "The cap takes effect when journald next starts. Zoomies does not stop or restart journald."}, err
}
func detectSwap(ctx context.Context, e *Engine) Result {
	b, err := read(e, "/proc/meminfo")
	if err != nil {
		return unavailable(err)
	}
	ram := int64(0)
	for _, l := range strings.Split(b, "\n") {
		f := strings.Fields(l)
		if len(f) > 1 && f[0] == "MemTotal:" {
			ram = number(f[1]) * 1024
		}
	}
	if ram < 32*1024*1024*1024 {
		return Result{Status: Skip, Reason: "less than 32 GiB RAM; keep swap enabled"}
	}
	v, err := command(ctx, e, "swapon", "--show", "--noheadings", "--raw", "--output", "NAME")
	if err != nil {
		return unavailable(err)
	}
	if v == "" {
		return Result{Status: OK, Current: "no active swap", Recommended: "swap off"}
	}
	// Only native systemd swap units backed by fstab can be restored and masked
	// with drop-ins; zram generators and custom swap policies remain untouched.
	for _, p := range strings.Fields(v) {
		u, err := command(ctx, e, "systemd-escape", "--path", "--suffix=swap", p)
		if err != nil {
			return unavailable(err)
		}
		fragment, err := command(ctx, e, "systemctl", "show", u, "--property=FragmentPath", "--value")
		if err != nil || !strings.HasPrefix(fragment, "/run/systemd/generator/") {
			return Result{Status: Skip, Current: v, Reason: "swap is generated or managed outside fstab; leave its policy unchanged"}
		}
	}
	return Result{Status: Warn, Current: v, Recommended: "swap off"}
}
func planSwap(ctx context.Context, e *Engine, r Result) (Change, error) {
	c := Change{ID: r.ID, Previous: r.Current, New: "swap off"}
	for _, p := range strings.Fields(r.Current) {
		u, err := command(ctx, e, "systemd-escape", "--path", "--suffix=swap", p)
		if err != nil {
			return c, err
		}
		f, err := fileChange(e, "/etc/systemd/system/"+u+".d/90-zoomies.conf", "[Unit]\nConditionPathExists=/run/zoomies-swap-enabled\n")
		if err != nil {
			return c, err
		}
		if _, err = e.System.Stat("/run/zoomies-swap-enabled"); err == nil {
			return c, fmt.Errorf("swap condition marker already exists")
		}
		c.Files = append(c.Files, f)
		c.Operations = append(c.Operations, Operation{Do: []string{"swapoff", "--", p}, Undo: []string{"swapon", "--", p}})
	}
	c.Operations = append(c.Operations, Operation{Do: []string{"systemctl", "daemon-reload"}, Undo: []string{"systemctl", "daemon-reload"}})
	return c, nil
}

// Package hosttune inspects host settings and plans explicitly approved changes.
// Detection never writes files or invokes a mutating command.
package hosttune

import (
	"context"
	"crypto/rand"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"reflect"
	"runtime"
	"slices"
	"strconv"
	"strings"
	"time"
)

type Tier string

const (
	Safe       Tier = "safe"
	Aggressive Tier = "aggressive"
	Dedicated  Tier = "dedicated"
)

type Status string

const (
	OK    Status = "ok"
	Warn  Status = "warn"
	Skip  Status = "skip"
	Error Status = "error"
)
const StateDir = "/var/lib/zoomies-host-tune"
const StatePath = StateDir + "/state.json"

// System is the complete host boundary. Tests supply an in-memory filesystem
// and command runner; none of the checks reach the real machine themselves.
type System interface {
	ReadFile(string) ([]byte, error)
	ReadDir(string) ([]fs.DirEntry, error)
	Stat(string) (fs.FileInfo, error)
	WriteFile(string, []byte, fs.FileMode) error
	WriteValue(string, string) error
	Remove(string) error
	Run(context.Context, string, ...string) (string, error)
	Lock(string) (func(), error)
}
type LocalSystem struct{}

func (LocalSystem) ReadFile(p string) ([]byte, error)       { return os.ReadFile(p) }
func (LocalSystem) ReadDir(p string) ([]fs.DirEntry, error) { return os.ReadDir(p) }
func (LocalSystem) Stat(p string) (fs.FileInfo, error)      { return os.Lstat(p) }
func (LocalSystem) Remove(p string) error                   { return os.Remove(p) }

// Time allowed for one host command. Most return at once; the longer budgets
// are for commands that legitimately wait on other work.
const (
	defaultCommandBudget = 30 * time.Second
	aptCommandBudget     = 20 * time.Minute
	// A Zoomies unit stops by waiting for the tasks it admitted (a cold image
	// pull included) and its unit allows 20 minutes for it, so a client that
	// gave up at three left systemd finishing a stop nothing would then start again.
	maintainedUnitBudget = 21 * time.Minute
	// A service or a daemon stopping waits on what it is running: Docker
	// gives each container ten seconds before it kills it.
	stopStartBudget = 3 * time.Minute
)

// commandBudget picks the longest wait a command can reasonably need. The
// maintained-unit case must stay ahead of the general systemctl one, or it
// would be cut short at the smaller budget.
func commandBudget(n string, a []string) time.Duration {
	switch {
	case n == "apt-get":
		return aptCommandBudget
	case n == "systemctl" && len(a) > 1 && (a[0] == "stop" || a[0] == "start") && slices.Contains(maintainedServices, a[len(a)-1]):
		return maintainedUnitBudget
	case n == "systemctl" && len(a) > 0 && (a[0] == "stop" || a[0] == "start" || a[0] == "restart"),
		n == "docker" && len(a) > 0 && a[0] == "stop":
		return stopStartBudget
	}
	return defaultCommandBudget
}

func (LocalSystem) Run(ctx context.Context, n string, a ...string) (string, error) {
	cctx, cancel := context.WithTimeout(ctx, commandBudget(n, a))
	defer cancel()
	c := exec.CommandContext(cctx, n, a...)
	c.Env = append(os.Environ(), "LC_ALL=C", "DEBIAN_FRONTEND=noninteractive")
	b, e := c.CombinedOutput()
	return strings.TrimSpace(string(b)), e
}

// WriteValue writes a kernel virtual file directly; atomic renames cannot be
// used on procfs or sysfs. It is never used for persistent configuration.
func (LocalSystem) WriteValue(p, v string) error { return os.WriteFile(p, []byte(v+"\n"), 0644) }
func fileOwner(info fs.FileInfo) (int, int) {
	if info == nil {
		return -1, -1
	}
	v := reflect.ValueOf(info.Sys())
	if v.Kind() == reflect.Pointer {
		v = v.Elem()
	}
	if v.Kind() != reflect.Struct {
		return -1, -1
	}
	u, g := v.FieldByName("Uid"), v.FieldByName("Gid")
	if u.IsValid() && g.IsValid() {
		return int(u.Uint()), int(g.Uint())
	}
	return -1, -1
}

// preserveOwner hands a temporary file to the owner of the file it replaces.
// A file the process just created already belongs to it, so a matching owner
// is left alone: the controller's unit filters fchown out (SystemCallFilter
// excludes @privileged) and the kernel kills a process that makes the call
// with SIGSYS, even when the call would have changed nothing.
func preserveOwner(f *os.File, info fs.FileInfo) error {
	uid, gid := fileOwner(info)
	if uid < 0 || gid < 0 || (uid == os.Geteuid() && gid == os.Getegid()) {
		return nil
	}
	return f.Chown(uid, gid)
}
func (LocalSystem) Lock(p string) (func(), error) {
	if err := os.MkdirAll(filepath.Dir(p), 0700); err != nil {
		return nil, err
	}
	info, err := os.Lstat(filepath.Dir(p))
	if err != nil {
		return nil, err
	}
	if !info.IsDir() || info.Mode().Perm() != 0700 {
		return nil, fmt.Errorf("tuning state directory must be a real directory with mode 0700")
	}
	if uid, _ := fileOwner(info); uid != 0 {
		return nil, fmt.Errorf("tuning state directory must be owned by root")
	}
	f, err := os.OpenFile(p, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600)
	if err != nil {
		return nil, fmt.Errorf("tuning is locked at %s; check for another tune process before removing a stale lock: %w", p, err)
	}
	_ = f.Close()
	return func() { _ = os.Remove(p) }, nil
}
func (LocalSystem) WriteFile(p string, b []byte, m fs.FileMode) error {
	if p == "/var/lib/zoomies/shared/host-health/report.json" {
		return writeHostReport(b)
	}
	if i, e := os.Lstat(p); e == nil && !i.Mode().IsRegular() {
		return fmt.Errorf("refusing non-regular file %s", p)
	}
	if e := os.MkdirAll(filepath.Dir(p), 0755); e != nil {
		return e
	}
	f, e := os.CreateTemp(filepath.Dir(p), ".zoomies-tune-*")
	if e != nil {
		return e
	}
	defer os.Remove(f.Name())
	owner, _ := os.Lstat(p)
	if e = preserveOwner(f, owner); e != nil {
		_ = f.Close()
		return e
	}
	if e = f.Chmod(m); e == nil {
		_, e = f.Write(b)
	}
	if e == nil {
		e = f.Sync()
	}
	closeErr := f.Close()
	if e == nil {
		e = closeErr
	}
	if e != nil {
		return e
	}
	if e = os.Rename(f.Name(), p); e != nil {
		return e
	}
	d, e := os.Open(filepath.Dir(p))
	if e != nil {
		return e
	}
	defer d.Close()
	return d.Sync()
}

type Options struct {
	System         System
	OS             string
	UID            int
	Now            func() time.Time
	WorkDir        string
	DockerRoot     string
	DockerHost     string
	HostReportPath string
	// SecurityMaintenanceReady is deliberately false until the maintenance
	// scheduler can prove security updates are run only on a drained host.
	// TODO: wire to the effective maintenance window configuration when built.
	SecurityMaintenanceReady bool
}

func LocalOptions(workDir string) Options {
	return Options{System: LocalSystem{}, OS: runtime.GOOS, UID: os.Geteuid(), Now: time.Now, WorkDir: workDir}
}

type Result struct {
	ID          string `json:"id"`
	Title       string `json:"title"`
	Tier        Tier   `json:"tier"`
	Status      Status `json:"status"`
	Current     string `json:"current"`
	Recommended string `json:"recommended"`
	Rationale   string `json:"rationale"`
	Reason      string `json:"reason,omitempty"`
	// Command is what an operator can paste into a shell on the host to put the
	// finding right by hand, for a package or setting Zoomies would never change
	// on its own (a kernel, say) or cannot from where it is running. Empty when
	// there is nothing sensible to type. It is a suggestion, never run by us.
	Command    string `json:"command,omitempty"`
	Actionable bool   `json:"actionable"`
	Optional   bool   `json:"optional,omitempty"`
	// Accepted, Ended and Acceptable are the controller's reading of the
	// operator's decisions (see Report.Judged). An agent never sets them: they are
	// scrubbed on the way in and stamped on a copy on the way out.
	Accepted   *Acceptance `json:"accepted,omitempty"`
	Ended      *Ended      `json:"ended,omitempty"`
	Acceptable bool        `json:"acceptable,omitempty"`
}
type Report struct {
	CheckedAt     time.Time `json:"checked_at"`
	OS            string    `json:"os"`
	Distro        string    `json:"distro"`
	WorkDir       string    `json:"work_dir,omitempty"`
	Container     bool      `json:"container"`
	Results       []Result  `json:"results"`
	RebootPending bool      `json:"reboot_pending"`
}

func (r Report) Counts() (warnings, errors, skipped int) {
	for _, x := range r.Results {
		// An accepted warning is the operator's decision, so doctor on the page
		// and doctor in a terminal agree on what is left. A local run never has
		// one: only the controller stamps it.
		if x.Accepting() {
			continue
		}
		switch x.Status {
		case Warn:
			warnings++
		case Error:
			errors++
		case Skip:
			skipped++
		}
	}
	return
}
func (r Report) ExitCode() int {
	w, e, _ := r.Counts()
	if e > 0 {
		return 2
	}
	if w > 0 {
		return 1
	}
	return 0
}

// Check keeps detection separate from the plan that Apply and Revert execute.
// A nil Plan is a report-only check, which cannot be applied accidentally.
type Check struct {
	ID, Title string
	Tier      Tier
	Rationale string
	Optional  bool
	Detect    func(context.Context, *Engine) Result
	Plan      func(context.Context, *Engine, Result) (Change, error)
}
type Engine struct {
	Options
	Distro, Version string
	Container       bool
	Checks          []Check
}

func New(o Options) *Engine {
	if o.System == nil {
		o.System = LocalSystem{}
	}
	if o.Now == nil {
		o.Now = time.Now
	}
	if o.WorkDir == "" {
		o.WorkDir = "/var/lib/zoomies/work"
	}
	e := &Engine{Options: o}
	b, _ := o.System.ReadFile("/etc/os-release")
	for _, l := range strings.Split(string(b), "\n") {
		k, v, ok := strings.Cut(l, "=")
		if ok {
			v = strings.Trim(v, "\"'")
			if k == "ID" {
				e.Distro = v
			}
			if k == "VERSION_ID" {
				e.Version = v
			}
		}
	}
	for _, p := range []string{"/.dockerenv", "/run/.containerenv"} {
		if _, err := o.System.Stat(p); err == nil {
			e.Container = true
		}
	}
	// systemd records the kind of container it runs in here, and WSL2 writes
	// "wsl" into it although a WSL2 distro is a virtual machine with its own
	// kernel, whose sysctls and Docker daemon are the distro's to tune.
	if b, err := o.System.ReadFile("/run/systemd/container"); err == nil && strings.TrimSpace(string(b)) != "wsl" {
		e.Container = true
	}
	if b, err := o.System.ReadFile("/proc/1/cgroup"); err == nil && (strings.Contains(string(b), "docker") || strings.Contains(string(b), "lxc") || strings.Contains(string(b), "kubepods")) {
		e.Container = true
	}
	e.Checks = baseChecks()
	e.Checks = append(e.Checks, kernelChecks()...)
	e.Checks = append(e.Checks, dedicatedChecks()...)
	return e
}

// supportedPlatforms is where tuning is expected to do what it says: the
// distributions whose sysctl layout, Docker daemon file and journal settings the
// changes were written against. Anywhere else the checks still report, and
// nothing is changed, because a fix that is right for one distribution is a guess
// on another. Adding a release is one row here, plus a line in
// docs/host-health.md; the kernel's HWE check has its own, narrower rule.
var supportedPlatforms = []struct {
	distro string
	// version is matched against VERSION_ID exactly, or against its major part
	// when major is set (Debian numbers its releases, and 13.1 is still 13).
	version string
	major   bool
}{
	{distro: "ubuntu", version: "24.04"},
	{distro: "ubuntu", version: "26.04"},
	{distro: "debian", version: "13", major: true},
}

// SupportedPlatforms names them in the order an operator would read them.
func SupportedPlatforms() string {
	names := make([]string, 0, len(supportedPlatforms))
	for _, p := range supportedPlatforms {
		names = append(names, strings.ToUpper(p.distro[:1])+p.distro[1:]+" "+p.version)
	}
	return strings.Join(names[:len(names)-1], ", ") + " or " + names[len(names)-1]
}

// Platform is this host as it names itself, which is what a refusal should say:
// "linux ubuntu" does not tell an operator whether it is the release that is
// unsupported or the whole distribution.
func (e *Engine) Platform() string { return strings.TrimSpace(e.Distro + " " + e.Version) }

func (e *Engine) Supported() bool {
	if e.OS != "linux" {
		return false
	}
	for _, p := range supportedPlatforms {
		if e.Distro != p.distro {
			continue
		}
		if p.major && strings.Split(e.Version, ".")[0] == p.version || !p.major && e.Version == p.version {
			return true
		}
	}
	return false
}
func (e *Engine) Run(ctx context.Context, t Tier) Report {
	r := Report{CheckedAt: e.Now().UTC(), OS: e.OS, Distro: e.Distro + " " + e.Version, WorkDir: e.WorkDir, Container: e.Container, Results: []Result{}}
	if e.OS != "linux" {
		r.Results = append(r.Results, Result{ID: "environment", Title: "Operating system", Tier: Safe, Status: Skip, Current: e.OS, Recommended: "Linux", Rationale: "Host tuning requires Linux.", Reason: "unsupported operating system"})
		return r
	}
	if !e.Supported() {
		r.Results = append(r.Results, Result{ID: "environment", Title: "Distribution", Tier: Safe, Status: Warn, Current: r.Distro, Recommended: SupportedPlatforms(), Rationale: "Other distributions are report-only in this release."})
	}
	for _, c := range e.Checks {
		if c.Tier == Dedicated && t != Dedicated {
			continue
		}
		if c.Tier == Aggressive && t == Safe {
			continue
		}
		x := c.Detect(ctx, e)
		x.ID = c.ID
		x.Title = c.Title
		x.Tier = c.Tier
		x.Rationale = c.Rationale
		x.Optional = c.Optional
		if c.ID == "kernel.hwe-install" && strings.HasPrefix(x.Reason, "optional install") {
			x.Reason = ""
		}
		x.Actionable = c.Plan != nil && x.Status == Warn && x.Reason == "" && e.Supported() && !e.Container && e.UID == 0
		if c.ID == KernelPending && x.Status == Warn {
			r.RebootPending = true
		}
		r.Results = append(r.Results, x)
	}
	return r
}
func (e *Engine) Check(id string) (Check, bool) {
	for _, c := range e.Checks {
		if c.ID == id {
			return c, true
		}
	}
	return Check{}, false
}
func read(e *Engine, p string) (string, error) {
	b, err := e.System.ReadFile(p)
	return strings.TrimSpace(string(b)), err
}
func unavailable(err error) Result {
	if errors.Is(err, fs.ErrPermission) {
		return Result{Status: Skip, Reason: "root access is needed to read this setting"}
	}
	if errors.Is(err, fs.ErrNotExist) {
		return Result{Status: Skip, Reason: "not available on this host"}
	}
	return Result{Status: Error, Reason: err.Error()}
}
func number(s string) int64 { n, _ := strconv.ParseInt(strings.TrimSpace(s), 10, 64); return n }
func command(ctx context.Context, e *Engine, n string, a ...string) (string, error) {
	return e.System.Run(ctx, n, a...)
}

// The shared parent belongs to the container account. Hold a directory handle
// and refuse an untrusted subdirectory so it cannot redirect a root reporter
// into an OS configuration file by replacing a path with a symlink.
func writeHostReport(b []byte) error {
	base, err := os.OpenRoot("/var/lib/zoomies/shared")
	if err != nil {
		return err
	}
	defer base.Close()
	expected, err := base.Lstat("host-health")
	if err != nil {
		return err
	}
	if !expected.IsDir() {
		return fmt.Errorf("host-health must be a real directory")
	}
	root, err := base.OpenRoot("host-health")
	if err != nil {
		return err
	}
	defer root.Close()
	info, err := root.Stat(".")
	if err != nil {
		return err
	}
	if !os.SameFile(expected, info) {
		return fmt.Errorf("host-health directory changed while opening it")
	}
	uid, _ := fileOwner(info)
	if uid != 0 || info.Mode().Perm()&0022 != 0 {
		return fmt.Errorf("host-health directory must be root-owned and not group/world-writable")
	}
	name := ".report-" + rand.Text()
	f, err := root.OpenFile(name, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0644)
	if err != nil {
		return err
	}
	defer root.Remove(name)
	_, err = f.Write(b)
	if err == nil {
		err = f.Sync()
	}
	ce := f.Close()
	if err == nil {
		err = ce
	}
	if err != nil {
		return err
	}
	return root.Rename(name, "report.json")
}

