// The web UI prints each row's reason on the host page, under a Next step panel
// that says cordon and never drain: a drain stops a runner that is still busy
// after five minutes, which is the wrong advice for waiting on a job. Two
// reasons said "drain" until this was pinned, so the page contradicted itself
// on the one host that had a reboot pending. This walks every tier on a host
// that reaches both of them, and fails if any text a check reports uses the word.
func TestNoCheckTellsAnOperatorToDrainTheHost(t *testing.T) {
	e := rebootHost()
	f := e.System.(*fakeSystem)
	// Neither filesystem is ext4 or XFS with noatime, so both mount rows warn
	// and carry their advice.
	f.commands["findmnt -n -o FSTYPE,OPTIONS --target /work"] = "nfs4 rw"
	f.commands["docker info --format {{.DockerRootDir}}"] = "/var/lib/docker"
	f.commands["findmnt -n -o FSTYPE,OPTIONS --target /var/lib/docker"] = "nfs4 rw"

	reached := map[string]bool{}
	for _, tier := range []Tier{Safe, Aggressive, Dedicated} {
		for _, r := range e.Run(context.Background(), tier).Results {
			if r.Status == Warn && r.Reason != "" {
				reached[r.ID] = true
			}
			for field, text := range map[string]string{
				"title": r.Title, "current": r.Current, "recommended": r.Recommended,
				"rationale": r.Rationale, "reason": r.Reason,
			} {
				if strings.Contains(strings.ToLower(text), "drain") {
					t.Errorf("%s (%s tier) %s says drain, but the host page advises cordon: %q", r.ID, tier, field, text)
				}
			}
		}
	}
	for _, id := range []string{KernelPending, "work.filesystem", "docker.filesystem"} {
		if !reached[id] {
			t.Errorf("%s did not warn with a reason, so this test proves nothing about its text", id)
		}
	}
}

// An operator reads these words. A reason that ends in a developer's note, or a
// title that is a tier name and a unit, tells them nothing about what to do.
func TestDedicatedCheckTextIsWrittenForAnOperator(t *testing.T) {
	e := rebootHost()
	if got := unitGuard(context.Background(), e, "apt-daily.timer"); got == "" || strings.Contains(strings.ToLower(got), "todo") {
		t.Errorf("the maintenance guard must give a reason an operator can act on, got %q", got)
	}
	for _, r := range e.Run(context.Background(), Dedicated).Results {
		for field, text := range map[string]string{"title": r.Title, "reason": r.Reason, "rationale": r.Rationale} {
			if strings.Contains(strings.ToLower(text), "todo") {
				t.Errorf("%s %s carries a developer note: %q", r.ID, field, text)
			}
		}
		if strings.HasPrefix(r.Title, "Dedicated host:") {
			t.Errorf("%s is titled %q, which names the tier and not the change", r.ID, r.Title)
		}
	}
}

// The Current text is shown to an operator as evidence, so it must be in units
// they can read, while the Warn rule underneath stays exactly as it was.
func TestDiskChecksSayWhatTheyFoundInReadableUnits(t *testing.T) {
	const df = "Filesystem 1024-blocks Used Available Capacity Mounted on\n/dev/sda1 %d 1 %d 1%% /work"
	const dfi = "Filesystem Inodes IUsed IFree IUse%% Mounted on\n/dev/sda1 %d 1 %d 1%% /work"
	const gib = 1024 * 1024
	cases := []struct {
		name    string
		inodes  bool
		total   int64
		free    int64
		status  Status
		current string
	}{
		{"space under ten percent", false, 100 * gib, 3 * gib, Warn, "3% free (3.0 GiB)"},
		{"space under a GiB is whole MiB", false, 100 * gib, 512 * 1024, Warn, "0% free (512 MiB)"},
		{"exactly ten percent is not low", false, 200 * gib, 20 * gib, OK, "10% free (20.0 GiB)"},
		{"exactly ten GiB is not low", false, 50 * gib, 10 * gib, OK, "20% free (10.0 GiB)"},
		{"one KiB under ten GiB is low", false, 50 * gib, 10*gib - 1, Warn, "19% free (10.0 GiB)"},
		{"inodes name the count", true, 400000, 12000, Warn, "3% free (12000 inodes)"},
		{"exactly ten percent of inodes is not low", true, 400000, 40000, OK, "10% free (40000 inodes)"},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			e, f := fixture()
			if c.inodes {
				f.commands["df -Pi -- /work"] = fmt.Sprintf(dfi, c.total, c.free)
			} else {
				f.commands["df -Pk -- /work"] = fmt.Sprintf(df, c.total, c.free)
			}
			id := "disk.space"
			if c.inodes {
				id = "disk.inodes"
			}
			for _, r := range e.Run(context.Background(), Safe).Results {
				if r.ID != id {
					continue
				}
				if r.Status != c.status || r.Current != c.current {
					t.Fatalf("%s = %s %q, want %s %q", id, r.Status, r.Current, c.status, c.current)
				}
				return
			}
			t.Fatalf("no %s result", id)
		})
	}
}

package hosttune

import (
	"context"
	"fmt"
	"strconv"
	"strings"
)

const hwePackage = "linux-generic-hwe-24.04"

// hweCommand is the by-hand route to the same install planHWE performs, for a
// host Zoomies cannot tune: a container install, a non-root run, or an operator
// who would rather type it. It installs no recommends, as the plan does.
const hweCommand = "sudo apt-get install --no-install-recommends " + hwePackage

func kernelChecks() []Check {
	return []Check{
		{ID: "kernel.running", Title: "Running kernel", Tier: Safe, Rationale: "Linux 6.8 or later is the baseline for these runner hosts.", Detect: func(ctx context.Context, e *Engine) Result {
			v, err := command(ctx, e, "uname", "-r")
			if err != nil {
				return unavailable(err)
			}
			s := OK
			if versionCompare(v, "6.8") < 0 {
				s = Warn
			}
			return Result{Status: s, Current: v, Recommended: "6.8 or later (distribution supplied)"}
		}},
		{ID: "kernel.pending", Title: "Installed kernel awaiting reboot", Tier: Safe, Rationale: "A newer installed kernel is only used after a planned reboot.", Detect: func(ctx context.Context, e *Engine) Result {
			running, err := command(ctx, e, "uname", "-r")
			if err != nil {
				return unavailable(err)
			}
			entries, err := e.System.ReadDir("/lib/modules")
			if err != nil {
				return Result{Status: Skip, Current: running, Reason: "installed host kernels are not visible"}
			}
			latest := running
			for _, x := range entries {
				if versionCompare(x.Name(), latest) > 0 {
					latest = x.Name()
				}
			}
			s := OK
			pending := latest != running
			if _, err := e.System.Stat("/var/run/reboot-required"); err == nil {
				pending = true
			}
			if pending {
				s = Warn
			}
			r := Result{Status: s, Current: running, Recommended: latest}
			if pending {
				// Cordon, not drain: a drain stops a runner that is still busy after
				// five minutes, and this text reaches the host page in the web UI,
				// which gives the same advice the controller does.
				r.Reason = "reboot pending; cordon the host and wait until none of its runners is running a job, then reboot it manually"
			}
			return r
		}},
		{ID: "kernel.hwe", Title: "Ubuntu hardware enablement kernel", Tier: Safe, Rationale: "Ubuntu's HWE package supplies an official newer kernel.", Detect: detectHWE},
		{ID: "kernel.hwe-install", Title: "Install Ubuntu HWE kernel", Tier: Dedicated, Optional: true, Rationale: "An official Ubuntu HWE kernel can improve newer hardware support; a reboot is planned separately.", Detect: detectHWE, Plan: planHWE},
	}
}
func versionCompare(a, b string) int {
	numbers := func(s string) []int {
		f := strings.FieldsFunc(s, func(r rune) bool { return r < '0' || r > '9' })
		out := []int{}
		for _, x := range f {
			n, _ := strconv.Atoi(x)
			out = append(out, n)
		}
		return out
	}
	aa, bb := numbers(a), numbers(b)
	for i := 0; i < len(aa) || i < len(bb); i++ {
		x, y := 0, 0
		if i < len(aa) {
			x = aa[i]
		}
		if i < len(bb) {
			y = bb[i]
		}
		if x < y {
			return -1
		}
		if x > y {
			return 1
		}
	}
	return 0
}
func detectHWE(ctx context.Context, e *Engine) Result {
	if e.Distro != "ubuntu" || e.Version != "24.04" {
		return Result{Status: Skip, Reason: "HWE check applies to Ubuntu 24.04 only"}
	}
	pkg := hwePackage
	v, err := command(ctx, e, "dpkg-query", "-W", "-f=${Status}", pkg)
	if err == nil && strings.Contains(v, "install ok installed") {
		return Result{Status: OK, Current: pkg + " installed", Recommended: pkg}
	}
	v, err = command(ctx, e, "apt-cache", "policy", pkg)
	if err != nil {
		return Result{Status: Skip, Reason: "Ubuntu package metadata is unavailable; update it during maintenance"}
	}
	candidate := ""
	for _, l := range strings.Split(v, "\n") {
		if strings.HasPrefix(strings.TrimSpace(l), "Candidate:") {
			candidate = strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(l), "Candidate:"))
		}
	}
	if candidate == "" || candidate == "(none)" {
		return Result{Status: Skip, Current: "not installed", Reason: "no HWE candidate in configured package metadata"}
	}
	return Result{Status: Warn, Current: "available, not installed", Recommended: pkg, Command: hweCommand, Reason: "optional install with --dedicated --only kernel.hwe-install"}
}
func planHWE(ctx context.Context, e *Engine, r Result) (Change, error) {
	pkg := hwePackage
	out, err := command(ctx, e, "apt-get", "--simulate", "--no-install-recommends", "install", pkg)
	if err != nil {
		return Change{}, fmt.Errorf("cannot plan HWE installation: %s", out)
	}
	var packages, versions []string
	for _, l := range strings.Split(out, "\n") {
		if strings.HasPrefix(l, "Remv ") {
			return Change{}, fmt.Errorf("HWE would remove existing packages; install manually")
		}
		if !strings.HasPrefix(l, "Inst ") {
			continue
		}
		f := strings.Fields(l)
		if len(f) < 3 || strings.HasPrefix(f[2], "[") {
			return Change{}, fmt.Errorf("HWE would upgrade existing packages; install manually")
		}
		name := f[1]
		version := strings.TrimPrefix(f[2], "(")
		if !strings.Contains(l, "Ubuntu:") {
			return Change{}, fmt.Errorf("%s is not an official Ubuntu package candidate", name)
		}
		packages = append(packages, name)
		versions = append(versions, name+"="+version)
	}
	if len(packages) == 0 {
		return Change{}, fmt.Errorf("HWE package plan is empty")
	}
	do := append([]string{"apt-get", "--yes", "--no-install-recommends", "install"}, versions...)
	undo := append([]string{"apt-get", "--yes", "remove", "--"}, packages...)
	return Change{ID: r.ID, Previous: "not installed", New: strings.Join(versions, ", "), Operations: []Operation{{Do: do, Undo: undo}}, Notice: "No reboot is performed. After installation, drain this host and reboot manually. Revert removes only the newly installed packages; no pre-existing package is upgraded or purged."}, nil
}

package hosttune

import (
	"context"
	"errors"
	"fmt"
	"io"
	"slices"
	"strings"
	"time"
)

// ErrHostBusy is a restart that did not happen because containers were still
// running. It is the one failure that is only a matter of time, which is what
// lets RestartWhenSafe retry it and nothing else.
var ErrHostBusy = errors.New("host busy")

// A change to the Docker daemon's configuration takes effect when the daemon
// restarts, and restarting it ends every container it is running: a runner's job
// is one of them. So tuning never restarted Docker on a host that was doing
// anything, and left the restart pending for an operator to find a quiet moment
// for -- which, on a host that is never quiet, is never.
//
// MaintainDocker is that quiet moment, made on purpose. It takes the host out of
// service so nothing new starts, waits for what is running to finish, restarts
// Docker, and puts the host back as it found it. It is the operator's explicit
// request (--force), never a side effect of tuning or of an upgrade, and it
// never ends a job unless asked to by name (--kill-running).

// MaintenanceOptions says how patient to be and what to do about work that does
// not finish.
type MaintenanceOptions struct {
	// Wait is how long running containers are given to finish once the host is
	// out of service. Zero is DefaultMaintenanceWait.
	Wait time.Duration
	// KillRunning stops what is still running when Wait is over, and restarts
	// Docker anyway. Without it a host that is still busy is put back and the
	// restart is left pending.
	KillRunning bool
	// Poll is how often the wait looks, and Sleep how it waits; both are for tests.
	Poll  time.Duration
	Sleep func(context.Context, time.Duration)
	Out   io.Writer
}

// DefaultMaintenanceWait is long enough for most CI jobs and short enough that an
// operator at a terminal does not walk away from a hung command.
const DefaultMaintenanceWait = 10 * time.Minute

// How long a restarted Docker is given to answer: twelve looks, five seconds
// apart, so a slow daemon gets about a minute before the restart is reported as
// failed.
const (
	dockerAnswerTries    = 12
	dockerAnswerInterval = 5 * time.Second
)

// maintainedServices are the units that admit jobs on this host, in the order
// they are stopped. They are started again in the reverse order.
var maintainedServices = []string{"zoomies-agent.service", "zoomies.service"}

func sleepCtx(ctx context.Context, d time.Duration) {
	t := time.NewTimer(d)
	defer t.Stop()
	select {
	case <-ctx.Done():
	case <-t.C:
	}
}

// MaintainDocker restarts Docker on a host taken out of service for the purpose.
//
// Whatever happens after the services are stopped, they are started again if they
// were running: a host left out of service by a failed restart is a worse outcome
// than the restart not happening. It returns an error describing what did not
// work, and says in Out what state the host is in.
func (e *Engine) MaintainDocker(ctx context.Context, o MaintenanceOptions) (err error) {
	if o.Out == nil {
		o.Out = io.Discard
	}
	if o.Wait <= 0 {
		o.Wait = DefaultMaintenanceWait
	}
	if o.Poll <= 0 {
		o.Poll = 15 * time.Second
	}
	if o.Sleep == nil {
		o.Sleep = sleepCtx
	}
	if e.DockerHost != "" && e.DockerHost != "unix:///var/run/docker.sock" {
		return fmt.Errorf("custom or rootless Docker endpoint; restart it manually after draining")
	}
	if e.UID != 0 {
		return fmt.Errorf("root is required")
	}

	// What is running now has to be known before anything is stopped: a service
	// whose state cannot be read is one that might be admitting jobs, and the
	// host is not taken out of service on a guess.
	var was []string
	for _, u := range maintainedServices {
		v, qerr := command(ctx, e, "systemctl", "show", u, "--property=ActiveState", "--value")
		if qerr != nil {
			return fmt.Errorf("cannot establish whether %s is running, so the host is left as it is", u)
		}
		if strings.TrimSpace(v) == "active" || strings.TrimSpace(v) == "activating" {
			was = append(was, u)
		}
	}

	// A restart that was killed after it stopped the units left them stopped, and left a
	// record of them. They are owed a start as much as the ones running now, so they
	// join the list before anything is decided from what is running.
	owed, serr := e.maintenanceOwed()
	if serr != nil {
		return serr
	}
	for _, u := range owed {
		if !slices.Contains(was, u) {
			fmt.Fprintf(o.Out, "A maintenance restart was interrupted and left %s stopped; it is started again at the end of this one.\n", u)
			was = append(was, u)
		}
	}
	if len(was) > 0 {
		// Written before the first stop. If it cannot be, nothing is stopped: a host taken
		// out of service with no record of how to put it back is the thing this prevents.
		if err := e.setMaintenanceOwed(was); err != nil {
			return fmt.Errorf("cannot record what this restart is about to stop, so the host is left as it is: %w", err)
		}
	}

	stopped := []string{}
	// Restoring is the one thing that must happen on every path out, including a
	// cancelled context, so it does not use the caller's.
	defer func() {
		rctx := context.WithoutCancel(ctx)
		failed := false
		for i := len(stopped) - 1; i >= 0; i-- {
			u := stopped[i]
			if _, serr := command(rctx, e, "systemctl", "start", u); serr != nil {
				fmt.Fprintf(o.Out, "Could not start %s again: %v. Start it with: systemctl start %s\n", u, serr, u)
				if err == nil {
					err = fmt.Errorf("%s was stopped for maintenance and did not start again", u)
				}
				failed = true
				continue
			}
			fmt.Fprintf(o.Out, "Started %s again.\n", u)
		}
		// Cleared only when everything owed has been started: a unit that would not start
		// stays on the record, so the next restart, or an operator reading the state,
		// still knows.
		if len(was) > 0 && !failed {
			if cerr := e.setMaintenanceOwed(nil); cerr != nil {
				fmt.Fprintf(o.Out, "Could not clear the record of this restart: %v\n", cerr)
			}
		}
	}()

	for _, u := range was {
		fmt.Fprintf(o.Out, "Stopping %s so nothing new starts.\n", u)
		// Recorded before the stop, not after it: a stop that times out or is
		// interrupted can leave systemd finishing it, and a unit that is not on this
		// list is never started again. Starting one that never stopped is a no-op.
		stopped = append(stopped, u)
		if _, serr := command(ctx, e, "systemctl", "stop", u); serr != nil {
			return fmt.Errorf("could not stop %s: %w (it may still be stopping; it is started again on the way out)", u, serr)
		}
	}

	running, idle, rerr := e.workContainers(ctx)
	if rerr != nil {
		return rerr
	}
	for polls := int(o.Wait / o.Poll); len(running) > 0 && polls > 0; polls-- {
		fmt.Fprintf(o.Out, "Waiting for %d running container(s) to finish; %s left.\n", len(running), (time.Duration(polls) * o.Poll).Round(time.Second))
		o.Sleep(ctx, o.Poll)
		if ctx.Err() != nil {
			return ctx.Err()
		}
		if running, idle, rerr = e.workContainers(ctx); rerr != nil {
			return rerr
		}
	}
	if len(running) > 0 {
		if !o.KillRunning {
			return fmt.Errorf("%w: %d container(s) were still running after %s, so Docker was not restarted and its change stays pending; "+
				"run again when the host is quieter, or add --kill-running to stop them", ErrHostBusy, len(running), o.Wait)
		}
		fmt.Fprintf(o.Out, "Stopping %d container(s) still running, as asked: %s\n", len(running), strings.Join(running, " "))
		if _, serr := command(ctx, e, "docker", append([]string{"stop"}, running...)...); serr != nil {
			return fmt.Errorf("could not stop the running containers: %w", serr)
		}
	}

	// Warm runners are not work, so they were not waited for; they do not survive the
	// restart either, and are stopped here rather than left for Docker to kill. The
	// controller starts them again when it is back. The look that found them idle was
	// the last one made, so a job that began in the instant since is the same race
	// every restart has with a runner that was not there a moment ago.
	if len(idle) > 0 {
		fmt.Fprintf(o.Out, "Stopping %d idle runner container(s) that hold no job.\n", len(idle))
		if _, serr := command(ctx, e, "docker", append([]string{"stop"}, idle...)...); serr != nil {
			return fmt.Errorf("could not stop the idle runner containers: %w", serr)
		}
	}

	fmt.Fprintln(o.Out, "Restarting Docker.")
	if _, serr := command(ctx, e, "systemctl", "restart", "docker.service"); serr != nil {
		return fmt.Errorf("docker did not restart: %w", serr)
	}
	// Up means answering, which is what a runner needs, not merely a unit that
	// says it started.
	answered := false
	for tries := 0; tries < dockerAnswerTries && !answered; tries++ {
		if _, derr := command(ctx, e, "docker", "info", "--format", "{{.ServerVersion}}"); derr == nil {
			answered = true
			break
		}
		o.Sleep(ctx, dockerAnswerInterval)
	}
	if !answered {
		return fmt.Errorf("docker restarted but is not answering; check it with: systemctl status docker.service")
	}
	fmt.Fprintln(o.Out, "Docker is answering.")

	unlock, lerr := e.System.Lock(StateDir + "/lock")
	if lerr != nil {
		return lerr
	}
	defer unlock()
	s, lerr := e.LoadState()
	if lerr != nil {
		return lerr
	}
	s.DockerRestartPending = false
	return e.saveState(s)
}

// maintenanceOwed is the units an interrupted maintenance restart left stopped.
func (e *Engine) maintenanceOwed() ([]string, error) {
	s, err := e.LoadState()
	if err != nil {
		return nil, err
	}
	return s.MaintenanceStopped, nil
}

// setMaintenanceOwed records the units a restart owes a start, under the state lock, which
// is taken for the write and not held: the restart itself can take the best part of an
// hour waiting for jobs, and tuning must be able to read its state meanwhile.
func (e *Engine) setMaintenanceOwed(units []string) error {
	unlock, err := e.System.Lock(StateDir + "/lock")
	if err != nil {
		return err
	}
	defer unlock()
	s, err := e.LoadState()
	if err != nil {
		return err
	}
	s.MaintenanceStopped = slices.Clone(units)
	return e.saveState(s)
}

// workContainers splits what is running into the containers that hold work and the
// idle Zoomies runners that do not.
//
// A restart ends every container, the host's own and other people's alike, so all of
// those are waited for. A runner of this fleet that is not running a job is the
// exception: a pool with a minimum keeps them up between jobs and never reaps below it,
// so counting them made the quiet moment unreachable -- a foreground restart stopped
// the controller for the whole wait to refuse at the end of it, and the background one
// never found its gap. A runner is idle when its container has no Runner.Worker, which
// the listener starts per job; its docker-in-docker sidecar goes with it. Anything the
// look cannot establish counts as work: a wrong "idle" ends a job, a wrong "busy" costs
// a poll.
func (e *Engine) workContainers(ctx context.Context) (busy, idle []string, err error) {
	v, err := command(ctx, e, "docker", "ps", "-q")
	if err != nil {
		return nil, nil, fmt.Errorf("%w, so Docker is not restarted: %v", errDockerUnreadable, err)
	}
	all := strings.Fields(v)
	if len(all) == 0 {
		return nil, nil, nil
	}
	list, lerr := command(ctx, e, "docker", "ps", "--filter", "label=io.zoomies.managed=true", "--format",
		`{{.ID}}|{{.Names}}|{{.Label "io.zoomies.role"}}|{{.Label "io.zoomies.dind-for"}}`)
	if lerr != nil {
		return all, nil, nil
	}
	idleRunners := map[string]bool{}
	type sidecar struct{ id, runner string }
	var sidecars []sidecar
	ids := map[string]string{}
	for _, line := range strings.Split(list, "\n") {
		f := strings.Split(strings.TrimSpace(line), "|")
		if len(f) != 4 {
			continue
		}
		id, name, role, owner := f[0], f[1], f[2], f[3]
		switch role {
		case "runner":
			top, terr := command(ctx, e, "docker", "top", id, "-eo", "args")
			if terr == nil && !strings.Contains(top, "Runner.Worker") {
				idleRunners[name] = true
				ids[id] = name
			}
		case "dind":
			sidecars = append(sidecars, sidecar{id, owner})
		}
	}
	idleIDs := map[string]bool{}
	for id := range ids {
		idleIDs[id] = true
	}
	for _, sc := range sidecars {
		if idleRunners[sc.runner] {
			idleIDs[sc.id] = true
		}
	}
	for _, id := range all {
		if idleIDs[id] || containsPrefixID(idleIDs, id) {
			idle = append(idle, id)
		} else {
			busy = append(busy, id)
		}
	}
	return busy, idle, nil
}

// containsPrefixID matches a short ID from one listing against the same container in
// another: both come from the same daemon, but the format of an ID is its business.
func containsPrefixID(set map[string]bool, id string) bool {
	for k := range set {
		if strings.HasPrefix(k, id) || strings.HasPrefix(id, k) {
			return true
		}
	}
	return false
}

// errDockerUnreadable is a failed look at what is running. It is not a verdict on the
// host: a daemon that is briefly slow, or a probe that ran over its budget on a loaded
// machine, fails once and answers the next time.
var errDockerUnreadable = errors.New("cannot check running containers")

// maxUnreadable is how many looks in a row may fail before the background task gives
// up on a Docker that is really down.
const maxUnreadable = 10

// WhenSafeOptions is how RestartWhenSafe goes about waiting for a quiet host.
type WhenSafeOptions struct {
	// GiveUp is how long to keep trying. Zero is DefaultGiveUp.
	GiveUp time.Duration
	// Poll is how often to look for a quiet host; Settle is how long the brief
	// out-of-service window is given to confirm it. Both are for tests as much
	// as for operators.
	Poll, Settle time.Duration
	Sleep        func(context.Context, time.Duration)
	Out          io.Writer
}

// DefaultGiveUp is a day: long enough for a host with a quiet night, short enough
// that a background task nobody remembers does not run for ever.
const DefaultGiveUp = 24 * time.Hour

// RestartWhenSafe keeps trying to restart Docker until the host is quiet, and
// leaves the host in service while it waits.
//
// That is the difference from MaintainDocker, which takes the host out of service
// and waits for the work to drain. On a host that is busy for hours, draining is
// hours of queued jobs; waiting for the gaps that ephemeral runners leave between
// jobs costs nothing until one appears. When it does, the host is taken out of
// service for as long as the restart needs, a job that arrived in that moment puts
// everything back and the loop carries on, and nothing is ever stopped to make
// room. It restarts only what a previous tune left pending, and does nothing when
// nothing is.
func (e *Engine) RestartWhenSafe(ctx context.Context, o WhenSafeOptions) error {
	if o.Out == nil {
		o.Out = io.Discard
	}
	if o.GiveUp <= 0 {
		o.GiveUp = DefaultGiveUp
	}
	if o.Poll <= 0 {
		o.Poll = 30 * time.Second
	}
	if o.Settle <= 0 {
		o.Settle = 30 * time.Second
	}
	if o.Sleep == nil {
		o.Sleep = sleepCtx
	}
	attempts := max(int(o.GiveUp/o.Poll), 1)
	unreadable := 0
	for i := 0; i < attempts; i++ {
		s, err := e.LoadState()
		if err != nil {
			return err
		}
		if !s.DockerRestartPending {
			fmt.Fprintln(o.Out, "No Docker restart is pending.")
			return nil
		}
		running, _, err := e.workContainers(ctx)
		if err != nil {
			// One failed look at what is running is not a reason to end a day-long wait
			// that would otherwise vanish without a word: it is not a quiet moment, and
			// the next look is soon.
			if unreadable++; unreadable >= maxUnreadable || !errors.Is(err, errDockerUnreadable) {
				return err
			}
			fmt.Fprintf(o.Out, "%v; looking again.\n", err)
			o.Sleep(ctx, o.Poll)
			if ctx.Err() != nil {
				return ctx.Err()
			}
			continue
		}
		unreadable = 0
		if len(running) == 0 {
			fmt.Fprintln(o.Out, "The host is quiet; restarting Docker.")
			err := e.MaintainDocker(ctx, MaintenanceOptions{Wait: o.Settle, Poll: min(o.Poll, o.Settle), Out: o.Out, Sleep: o.Sleep})
			if err == nil {
				return nil
			}
			if errors.Is(err, errDockerUnreadable) && unreadable+1 < maxUnreadable {
				unreadable++
				fmt.Fprintf(o.Out, "%v; the host is back in service and the restart will be tried again.\n", err)
			} else if !errors.Is(err, ErrHostBusy) {
				return err
			} else {
				fmt.Fprintln(o.Out, "A job started in that moment; the host is back in service and the restart will be tried again.")
			}
		} else if i%20 == 0 {
			// Said now and then, not at every poll: a day of "still busy" is a log
			// nobody reads.
			fmt.Fprintf(o.Out, "Waiting for a quiet moment: %d container(s) running.\n", len(running))
		}
		o.Sleep(ctx, o.Poll)
		if ctx.Err() != nil {
			return ctx.Err()
		}
	}
	return fmt.Errorf("%w: no quiet moment in %s, so Docker was not restarted; its change stays pending and the next tune can try again", ErrHostBusy, o.GiveUp)
}

// BackgroundUnit is the transient unit a background restart runs as. One name, so
// a second request while one is waiting is refused instead of started beside it.
const BackgroundUnit = "zoomies-docker-restart.service"

// StartBackground runs a command as a transient systemd unit of its own, which is
// the only way it can outlive both the terminal and the services it will stop: a
// child of zoomies-agent.service would be stopped with it.
func (e *Engine) StartBackground(ctx context.Context, args []string) error {
	if _, err := e.System.Stat("/run/systemd/system"); err != nil {
		return fmt.Errorf("this host does not run systemd, so there is nowhere to keep a background task; run `zoomies tune --restart-pending` in a terminal multiplexer instead")
	}
	if v, err := command(ctx, e, "systemctl", "is-active", BackgroundUnit); err == nil && strings.TrimSpace(v) == "active" {
		return fmt.Errorf("a background restart is already waiting (%s); follow it with: journalctl -u %s -f", BackgroundUnit, BackgroundUnit)
	}
	run := append([]string{"--quiet", "--collect", "--unit", strings.TrimSuffix(BackgroundUnit, ".service"),
		"--description", "Restart Docker for a Zoomies host tuning change, when the host is quiet"}, args...)
	if _, err := command(ctx, e, "systemd-run", run...); err != nil {
		return fmt.Errorf("could not start the background task: %w", err)
	}
	return nil
}

package hosttune

import (
	"bytes"
	"context"
	"errors"
	"io/fs"
	"strings"
	"testing"
	"time"
)

// scriptedHost is a host whose services and containers behave: stopping a unit
// makes it inactive, starting it makes it active, and `docker ps` answers from a
// script so a test can have a job finish after a few looks.
type scriptedHost struct {
	*fakeSystem
	active      map[string]string
	ps          [][]string
	psCalls     int
	failRestart bool
	unitActive  bool
	killed      bool
	// failStop is the units whose stop returns an error although systemd goes on to
	// finish stopping them: a client that gave up waiting.
	failStop map[string]bool
	// psFail is how many of the first `docker ps` calls fail, as a daemon too slow to
	// answer within the probe's budget does.
	psFail int
	// failWrites makes the state file unwritable, as a full or read-only disk does.
	failWrites bool
	// managed is what `docker ps` says of the containers this fleet owns, one line each as
	// the format asks for them, and withWorker is the containers a job is running in.
	managed    []string
	withWorker map[string]bool
	log        []string
}

func (s *scriptedHost) Run(_ context.Context, n string, a ...string) (string, error) {
	k := n + " " + strings.Join(a, " ")
	s.log = append(s.log, k)
	switch {
	case n == "systemctl" && len(a) >= 2 && a[0] == "show":
		v, ok := s.active[a[1]]
		if !ok {
			return "", errors.New("unit state unknown")
		}
		return v, nil
	case n == "systemctl" && len(a) == 2 && a[0] == "stop":
		s.active[a[1]] = "inactive"
		if s.failStop[a[1]] {
			return "", errors.New("signal: killed")
		}
	case n == "systemctl" && len(a) == 2 && a[0] == "start":
		s.active[a[1]] = "active"
	case n == "systemctl" && len(a) == 2 && a[0] == "restart" && a[1] == "docker.service":
		if s.failRestart {
			return "", errors.New("docker failed to start")
		}
	case k == "systemctl is-active "+BackgroundUnit:
		if s.unitActive {
			return "active", nil
		}
		return "inactive", errors.New("inactive")
	case k == "docker ps -q":
		if s.psCalls < s.psFail {
			s.psCalls++
			return "", errors.New("context deadline exceeded")
		}
		if s.killed {
			return "", nil
		}
		i := min(s.psCalls, len(s.ps)-1)
		s.psCalls++
		return strings.Join(s.ps[i], "\n"), nil
	case n == "docker" && len(a) > 1 && a[0] == "ps" && a[1] == "--filter":
		return strings.Join(s.managed, "\n"), nil
	case n == "docker" && len(a) > 1 && a[0] == "top":
		if s.withWorker[a[1]] {
			return "ARGS\n/runner/bin/Runner.Listener\n/runner/bin/Runner.Worker spawnclient", nil
		}
		return "ARGS\n/runner/bin/Runner.Listener run", nil
	case n == "docker" && len(a) > 0 && a[0] == "stop":
		s.killed = true
	case n == "docker" && len(a) > 0 && a[0] == "info":
		return "27.1.1", nil
	}
	return "", nil
}

func (s *scriptedHost) did(prefix string) int {
	n := 0
	for _, c := range s.log {
		if strings.HasPrefix(c, prefix) {
			n++
		}
	}
	return n
}

func (s *scriptedHost) index(call string) int {
	for i, c := range s.log {
		if c == call {
			return i
		}
	}
	return -1
}

func maintenanceHost(ps ...[]string) (*Engine, *scriptedHost) {
	f := fake()
	f.put("/etc/os-release", "ID=ubuntu\nVERSION_ID=24.04\n")
	s := &scriptedHost{fakeSystem: f, ps: ps, active: map[string]string{"zoomies.service": "active", "zoomies-agent.service": "active"}}
	e := New(Options{System: s, OS: "linux", UID: 0, Now: func() time.Time { return time.Unix(1234, 0) }, WorkDir: "/work"})
	_ = e.saveState(State{Version: 1, DockerRestartPending: true, Changes: []Change{}})
	return e, s
}

func opts(kill bool) (MaintenanceOptions, *bytes.Buffer) {
	var out bytes.Buffer
	return MaintenanceOptions{Wait: 3 * time.Minute, Poll: time.Minute, KillRunning: kill, Sleep: func(context.Context, time.Duration) {}, Out: &out}, &out
}

func pending(t *testing.T, e *Engine) bool {
	t.Helper()
	s, err := e.LoadState()
	if err != nil {
		t.Fatal(err)
	}
	return s.DockerRestartPending
}

// The whole sequence, in order: nothing new is admitted before the wait, Docker is
// restarted only once the host is quiet, and the host comes back the way it was --
// the services started in the reverse of the order they were stopped.
func TestMaintenanceTakesTheHostOutRestartsDockerAndPutsItBack(t *testing.T) {
	e, s := maintenanceHost([]string{"job-1"}, []string{"job-1"}, nil)
	o, out := opts(false)
	if err := e.MaintainDocker(context.Background(), o); err != nil {
		t.Fatalf("MaintainDocker: %v\n%s", err, out)
	}
	order := []string{
		"systemctl stop zoomies-agent.service", "systemctl stop zoomies.service",
		"systemctl restart docker.service",
		"systemctl start zoomies.service", "systemctl start zoomies-agent.service",
	}
	last := -1
	for _, c := range order {
		i := s.index(c)
		if i <= last {
			t.Fatalf("%q ran at %d, want after %d; calls: %v", c, i, last, s.log)
		}
		last = i
	}
	if s.active["zoomies.service"] != "active" || s.active["zoomies-agent.service"] != "active" {
		t.Errorf("the host was not put back: %v", s.active)
	}
	if pending(t, e) {
		t.Error("a restart that happened is still recorded as pending")
	}
}

// A job is never ended unless the operator said so by name. A host still busy when
// the wait is over is put back, and the restart stays pending for another try.
func TestMaintenanceNeverEndsJobsUnlessAsked(t *testing.T) {
	e, s := maintenanceHost([]string{"job-1"})
	o, _ := opts(false)
	err := e.MaintainDocker(context.Background(), o)
	if err == nil || !strings.Contains(err.Error(), "--kill-running") {
		t.Fatalf("a busy host must be refused with the way forward, got %v", err)
	}
	if s.did("systemctl restart docker") != 0 || s.did("docker stop") != 0 {
		t.Errorf("Docker was touched on a busy host: %v", s.log)
	}
	if s.active["zoomies.service"] != "active" || s.active["zoomies-agent.service"] != "active" {
		t.Errorf("a refused maintenance left the host out of service: %v", s.active)
	}
	if !pending(t, e) {
		t.Error("a restart that did not happen must stay pending")
	}
}

func TestKillRunningStopsWhatIsLeftAndStillPutsTheHostBack(t *testing.T) {
	e, s := maintenanceHost([]string{"job-1", "job-2"})
	o, out := opts(true)
	if err := e.MaintainDocker(context.Background(), o); err != nil {
		t.Fatalf("MaintainDocker: %v", err)
	}
	if s.did("docker stop job-1 job-2") != 1 || s.did("systemctl restart docker") != 1 {
		t.Errorf("the running containers must be stopped and Docker restarted: %v", s.log)
	}
	if !strings.Contains(out.String(), "job-1 job-2") {
		t.Errorf("the containers it stops must be named:\n%s", out)
	}
	if s.active["zoomies.service"] != "active" || s.active["zoomies-agent.service"] != "active" {
		t.Errorf("the host was not put back: %v", s.active)
	}
}

// A host left out of service by a failed restart is worse than a restart that did
// not happen, so the services come back whatever went wrong.
func TestAFailedRestartStillBringsTheServicesBack(t *testing.T) {
	e, s := maintenanceHost(nil)
	s.failRestart = true
	o, _ := opts(false)
	if err := e.MaintainDocker(context.Background(), o); err == nil {
