func (s *scriptedHost) WriteFile(p string, b []byte, m fs.FileMode) error {
	if s.failWrites {
		return errors.New("read-only file system")
	}
	return s.fakeSystem.WriteFile(p, b, m)
}

// A pool with a minimum keeps idle runners up between jobs and never reaps below it, so
// counting them as work made the quiet moment unreachable: the restart waited out its
// whole budget, with the host out of service, to refuse at the end. An idle runner and
// its sidecar are stopped for the restart instead; one with a job in it is still waited
// for.
func TestWarmRunnersAreNotWorkButARunnerWithAJobIs(t *testing.T) {
	warm := []string{"r1|runner-1|runner|", "d1|dind-1|dind|runner-1"}
	e, s := maintenanceHost([]string{"r1", "d1"})
	s.managed = warm
	o, _ := opts(false)
	if err := e.MaintainDocker(context.Background(), o); err != nil {
		t.Fatalf("a host holding only warm runners was refused: %v", err)
	}
	if s.did("docker stop r1 d1") != 1 || s.did("systemctl restart docker") != 1 {
		t.Errorf("the idle runner and its sidecar were not stopped before the restart: %v", s.log)
	}

	e, s = maintenanceHost([]string{"r1", "d1"})
	s.managed = warm
	s.withWorker = map[string]bool{"r1": true}
	o, _ = opts(false)
	if err := e.MaintainDocker(context.Background(), o); !errors.Is(err, ErrHostBusy) {
		t.Fatalf("err = %v; a runner with a job in it is work and must be waited for", err)
	}
	if s.did("systemctl restart docker") != 0 {
		t.Errorf("Docker was restarted under a running job: %v", s.log)
	}
}

// The background task's quiet moment is the same test: a host kept warm by a pool
// minimum is quiet, where before it never was.
func TestWhenSafeFindsAQuietMomentOnAHostThatKeepsWarmRunners(t *testing.T) {
	e, s := maintenanceHost([]string{"r1"})
	s.managed = []string{"r1|runner-1|runner|"}
	o, _ := whenSafe(time.Hour)
	if err := e.RestartWhenSafe(context.Background(), o); err != nil {
		t.Fatal(err)
	}
	if s.did("systemctl restart docker") != 1 {
		t.Errorf("Docker was not restarted: %v", s.log)
	}
}

// What cannot be established counts as work: a wrong "idle" ends someone's job.
func TestARunnerWhoseProcessesCannotBeReadIsTreatedAsWork(t *testing.T) {
	e, s := maintenanceHost([]string{"r1"})
	s.managed = []string{"r1|runner-1|runner|"}
	s.withWorker = nil
	e.System = &topFails{s}
	busy, idle, err := e.workContainers(context.Background())
	if err != nil || len(busy) != 1 || len(idle) != 0 {
		t.Fatalf("busy = %v, idle = %v, err = %v; want the container counted as work", busy, idle, err)
	}
}

type topFails struct{ *scriptedHost }

func (t *topFails) Run(ctx context.Context, n string, a ...string) (string, error) {
	if n == "docker" && len(a) > 0 && a[0] == "top" {
		return "", errors.New("no such container")
	}
	return t.scriptedHost.Run(ctx, n, a...)
}

package hosttune

import (
	"context"
	"encoding/json"
	"errors"
	"path/filepath"
	"sync"
	"time"
)

const ReportFile = "host-doctor.json"

// MonitorRunTimeout bounds one run of the checks. Exported so that whatever
// waits on a run (the controller's lease on a check request) can be pinned
// above it by a test instead of by a comment.
const MonitorRunTimeout = 45 * time.Second

// ErrCheckNowUnsupported is what CheckNow answers where the monitor cannot run
// the checks itself: inside a container it only re-reads a file another unit
// writes, and off Linux the engine has nothing to look at.
var ErrCheckNowUnsupported = errors.New("the host checks cannot be run on request here: this agent runs in a container or on an operating system other than Linux")

// Monitor publishes bounded, read-only observations independently of the
// heartbeat deadline. It writes only its observation cache, never OS settings.
type Monitor struct {
	mu       sync.Mutex
	Engine   *Engine
	latest   *Report
	checking bool
	due      time.Time
	interval time.Duration

	// runMu is the single flight: the periodic run and an on-request run never
	// overlap, so a press cannot double the load a busy host is already under.
	runMu sync.Mutex
	// waiting is the one on-request run that has not started yet. A press that
	// arrives while it is still queued joins it -- its report is taken after
	// that press too -- so any number of presses cost at most one extra run.
	waiting *checkCall
}

// checkCall is one queued on-request run and everyone waiting on its answer.
type checkCall struct {
	done    chan struct{}
	report  *Report
	err     error
	waiters int
}

func NewMonitor(e *Engine) *Monitor { return &Monitor{Engine: e, interval: time.Minute} }

// CanCheckNow reports whether CheckNow can run the checks here. It is safe on a
// nil monitor because the agent holds one behind an interface, where a typed nil
// is not a nil interface.
func (m *Monitor) CanCheckNow() bool {
	return m != nil && m.Engine != nil && m.Engine.OS == "linux" && !m.Engine.Container
}

// CheckNow runs the checks once, now, and returns the report. If a run is
// already in flight it waits for it and then runs again, because that report
// may have been taken before the caller asked. The report is returned even when
// it is no newer than the last one: whether that matters is the receiver's
// call.
func (m *Monitor) CheckNow(ctx context.Context) (*Report, error) {
	if !m.CanCheckNow() {
		return nil, ErrCheckNowUnsupported
	}
	m.mu.Lock()
	call := m.waiting
	if call == nil {
		call = &checkCall{done: make(chan struct{})}
		m.waiting = call
		go m.runWaiting(ctx, call)
	}
	call.waiters++
	m.mu.Unlock()
	select {
	case <-call.done:
		return call.report, call.err
	case <-ctx.Done():
		return nil, ctx.Err()
	}
}

// runWaiting takes its turn on the single flight and runs for everyone who
// joined. It runs on its own goroutine so that a caller that stops waiting
// does not strand the others on a lock it still holds.
func (m *Monitor) runWaiting(ctx context.Context, call *checkCall) {
	m.runMu.Lock()
	defer m.runMu.Unlock()
	m.mu.Lock()
	m.waiting = nil
	m.mu.Unlock()
	call.report, call.err = m.run(ctx)
	close(call.done)
}

// run is the one place the checks execute, and is called with runMu held. A run cut off by its timeout is
// discarded rather than stored: the checks that did not get to run come back as
// errors, and publishing them would raise a host-health finding about the
// deadline instead of the host.
func (m *Monitor) run(ctx context.Context) (*Report, error) {
	c, cancel := context.WithTimeout(ctx, MonitorRunTimeout)
	defer cancel()
	r := m.Engine.Run(c, Dedicated)
	if err := c.Err(); err != nil {
		return nil, err
	}
	if b, err := json.Marshal(r); err == nil {
		_ = m.Engine.System.WriteFile(filepath.Join(m.Engine.WorkDir, ReportFile), b, 0640)
	}
	m.mu.Lock()
	m.latest = &r
	m.due = m.Engine.Now().Add(m.interval)
	m.mu.Unlock()
	return &r, nil
}

func (m *Monitor) Latest(ctx context.Context) *Report {
	if m == nil {
		return nil
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	if !m.Engine.Container {
		if r, err := ReadReport(m.Engine.System, m.Engine.WorkDir); err == nil && !r.Container && r.CheckedAt.Before(m.Engine.Now().Add(time.Minute)) && (m.latest == nil || r.CheckedAt.After(m.latest.CheckedAt)) {
			m.latest = r
		}
	}
	if m.Engine.Container && m.Engine.HostReportPath != "" {
		if b, err := m.Engine.System.ReadFile(m.Engine.HostReportPath); err == nil {
			var r Report
			if json.Unmarshal(b, &r) == nil && !r.Container && !r.CheckedAt.IsZero() && m.Engine.Now().Sub(r.CheckedAt) < 3*time.Minute && r.CheckedAt.Before(m.Engine.Now().Add(time.Minute)) && len(r.Results) <= 64 {
				m.latest = &r
				return m.latest
			}
		}
	}
	if !m.checking && !m.Engine.Now().Before(m.due) {
		m.checking = true
		go func() {
			// The error is dropped on purpose: a cut-off run stores nothing and the
			// next one is due after the interval either way, so a failing host is
			// not hammered.
			m.runMu.Lock()
			_, _ = m.run(ctx)
			m.runMu.Unlock()
			m.mu.Lock()
			m.checking = false
			m.due = m.Engine.Now().Add(m.interval)
			m.mu.Unlock()
		}()
	}
	return m.latest
}
func ReadReport(sys System, work string) (*Report, error) {
	b, err := sys.ReadFile(filepath.Join(work, ReportFile))
	if err != nil {
		return nil, err
	}
	var r Report
	if err = json.Unmarshal(b, &r); err != nil {
		return nil, err
	}
	return &r, nil
}
func NewWarnings(before *Report, after Report) int {
	old := map[string]bool{}
	if before != nil {
		for _, r := range before.Results {
			if r.Status == Warn {
				old[r.ID] = true
			}
		}
	}
	n := 0
	for _, r := range after.Results {
		if r.Status == Warn && !old[r.ID] {
			n++
		}
	}
	return n
}

package hosttune

import (
	"context"
	"encoding/json"
	"errors"
	"io/fs"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

// gatedSystem holds every run of the checks at its first read until the test
// opens the gate, and counts the cache writes, which is one per stored run. It
// is how a test makes "a run is in flight" a fact rather than a race.
type gatedSystem struct {
	*fakeSystem
	gate    chan struct{}
	entered chan struct{}
	once    sync.Once
	stored  atomic.Int32
}

func newGated() (*Engine, *gatedSystem) {
	e, f := fixture()
	g := &gatedSystem{fakeSystem: f, gate: make(chan struct{}), entered: make(chan struct{})}
	e.System = g
	return e, g
}

func (g *gatedSystem) ReadFile(p string) ([]byte, error) {
	// Latest reads the cache under the monitor's lock before it starts a run;
	// gating that read would hold the lock the test needs to observe the run.
	if strings.HasPrefix(p, "/work") {
		return g.fakeSystem.ReadFile(p)
	}
	g.once.Do(func() { close(g.entered) })
	<-g.gate
	return g.fakeSystem.ReadFile(p)
}

func (g *gatedSystem) WriteFile(p string, b []byte, m fs.FileMode) error {
	g.stored.Add(1)
	return g.fakeSystem.WriteFile(p, b, m)
}

func waitFor(t *testing.T, what string, ok func() bool) {
	t.Helper()
	deadline := time.Now().Add(10 * time.Second)
	for !ok() {
		if time.Now().After(deadline) {
			t.Fatalf("timed out waiting for %s", what)
		}
		time.Sleep(time.Millisecond)
	}
}

func queuedWaiters(m *Monitor) int {
	m.mu.Lock()
	defer m.mu.Unlock()
	if m.waiting == nil {
		return 0
	}
	return m.waiting.waiters
}

// A container install only re-reads a file another unit writes, so a press
// there must say so and run nothing -- never quietly run the engine against a
// host it is not allowed to inspect.
func TestCheckNowRefusesWhereTheMonitorCannotRunTheChecks(t *testing.T) {
	for name, tc := range map[string]func(*Engine){
		"in a container":      func(e *Engine) { e.Container = true },
		"off Linux":           func(e *Engine) { e.OS = "darwin" },
		"container with file": func(e *Engine) { e.Container = true; e.HostReportPath = "/shared/report.json" },
	} {
		t.Run(name, func(t *testing.T) {
			e, f := fixture()
			tc(e)
			m := NewMonitor(e)
			if m.CanCheckNow() {
				t.Fatal("CanCheckNow is true")
			}
			rep, err := m.CheckNow(context.Background())
			if !errors.Is(err, ErrCheckNowUnsupported) || rep != nil {
				t.Fatalf("got %v, %v", rep, err)
			}
			if len(f.calls) > 0 || f.writes > 0 {
				t.Fatal("an unsupported check still touched the host")
			}
		})
	}
	var nilMonitor *Monitor
	if nilMonitor.CanCheckNow() {
		t.Fatal("a nil monitor claims it can check")
	}
	if _, err := nilMonitor.CheckNow(context.Background()); !errors.Is(err, ErrCheckNowUnsupported) {
		t.Fatalf("nil monitor: %v", err)
	}
}

// The report an operator waits for must be the one taken after the press, and
// the periodic path must then serve it rather than run again at once.
func TestCheckNowRunsTheChecksAndKeepsTheReport(t *testing.T) {
	e, f := fixture()
	m := NewMonitor(e)
	if !m.CanCheckNow() {
		t.Fatal("a native Linux monitor cannot check on request")
	}
	rep, err := m.CheckNow(context.Background())
	if err != nil || rep == nil || len(rep.Results) == 0 {
		t.Fatalf("got %+v, %v", rep, err)
	}
	if f.writes != 1 {
		t.Fatalf("cache writes = %d, want 1", f.writes)
	}
	if got := m.Latest(context.Background()); got == nil || !got.CheckedAt.Equal(rep.CheckedAt) {
		t.Fatalf("Latest did not serve the report just taken: %+v", got)
	}
	m.mu.Lock()
	due := m.due
	m.mu.Unlock()
	if !due.After(e.Now()) {
		t.Fatal("an on-request run left the periodic run due straight away")
	}
}

// A run that overran turns every check it did not reach into an error row, and
// storing it would raise a host-health finding about the deadline instead of
// the host. Both paths drop it.
func TestARunCutOffByItsTimeoutIsNotStored(t *testing.T) {
	t.Run("on request", func(t *testing.T) {
		e, g := newGated()
		m := NewMonitor(e)
		ctx, cancel := context.WithCancel(context.Background())
		errc := make(chan error, 1)
		go func() { _, err := m.CheckNow(ctx); errc <- err }()
		<-g.entered
		cancel()
		close(g.gate)
		if err := <-errc; err == nil {
			t.Fatal("a cut-off run reported success")
		}
		waitFor(t, "the run to finish", func() bool { return m.runMu.TryLock() })
		m.runMu.Unlock()
		if g.stored.Load() != 0 || m.latest != nil {
			t.Fatal("a cut-off run was stored")
		}
	})
	t.Run("periodic", func(t *testing.T) {
		e, g := newGated()
		m := NewMonitor(e)
		ctx, cancel := context.WithCancel(context.Background())
		m.Latest(ctx)
		<-g.entered
		cancel()
		close(g.gate)
		waitFor(t, "the periodic run to end", func() bool {
			m.mu.Lock()
			defer m.mu.Unlock()
			return !m.checking
		})
		if g.stored.Load() != 0 || m.latest != nil {
			t.Fatal("a cut-off run was stored")
		}
	})
}

// A press during a periodic run cannot reuse that run's report, which may
// predate it, and presses piled up behind it must not each cost a run: the
// host being checked is the one under load.
func TestCheckNowWaitsForARunInFlightThenRunsOnceForEveryoneQueued(t *testing.T) {
	e, g := newGated()
	m := NewMonitor(e)
	m.Latest(context.Background())
	<-g.entered

	const callers = 3
	reports := make(chan *Report, callers)
	for i := 0; i < callers; i++ {
		go func() {
			r, err := m.CheckNow(context.Background())
			if err != nil {
				t.Error(err)
			}
			reports <- r
		}()
	}
	waitFor(t, "every press to queue", func() bool { return queuedWaiters(m) == callers })
	select {
	case <-reports:
		t.Fatal("a press was answered while the earlier run was still in flight")
	default:
	}
	close(g.gate)
	for i := 0; i < callers; i++ {
		select {
		case r := <-reports:
			if r == nil {
				t.Fatal("no report")
			}
		case <-time.After(10 * time.Second):
			t.Fatal("timed out waiting for the shared run")
		}
	}
	if got := g.stored.Load(); got != 2 {
		t.Fatalf("runs = %d, want the in-flight one plus exactly one for the presses", got)
	}
}

func TestContainerConsumesNativeHostReportWithoutRunningHostCommands(t *testing.T) {
	e, f := fixture()
	e.Container = true
	e.HostReportPath = "/shared/host-health/report.json"
	r := Report{CheckedAt: e.Now(), OS: "linux", Distro: "ubuntu 24.04", Results: []Result{{ID: "disk.space", Status: OK, Tier: Safe}}}
	b, _ := json.Marshal(r)
	f.put(e.HostReportPath, string(b))
	m := NewMonitor(e)
	got := m.Latest(context.Background())
	if got == nil || got.Container {
		t.Fatal("did not use native report")
	}
	if len(f.calls) > 0 || f.writes > 0 {
		t.Fatal("container unnecessarily inspected the OS")
	}
}
func TestNewWarningComparisonUsesCheckIDs(t *testing.T) {
	old := &Report{Results: []Result{{ID: "same", Status: Warn}, {ID: "fixed", Status: Warn}}}
	next := Report{Results: []Result{{ID: "same", Status: Warn}, {ID: "fixed", Status: OK}, {ID: "new", Status: Warn}}}
	if NewWarnings(old, next) != 1 {
		t.Fatal("warning comparison")
	}
	if NewWarnings(nil, next) != 2 {
		t.Fatal("missing baseline")
	}
}
func TestNativeMonitorCanImportAnImmediatePostTuneReport(t *testing.T) {
	e, f := fixture()
	r := Report{CheckedAt: e.Now(), Results: []Result{{ID: "disk.space", Tier: Safe, Status: OK}}}
	b, _ := json.Marshal(r)
	f.put(e.WorkDir+"/"+ReportFile, string(b))
	m := NewMonitor(e)
	m.due = e.Now().Add(time.Hour)
	got := m.Latest(context.Background())
	if got == nil || len(got.Results) != 1 {
		t.Fatal("post-tune cache not imported")
	}
}

package hosttune

import (
	"os"
	"path/filepath"
	"testing"
)

// The controller's systemd unit filters fchown out and the kernel kills a
// process that calls it, so replacing a file the process already owns must not
// reach the syscall at all. A closed file makes any attempt return an error.
func TestPreserveOwnerSkipsFchownWhenTheOwnerAlreadyMatches(t *testing.T) {
	p := filepath.Join(t.TempDir(), "report.json")
	if err := os.WriteFile(p, []byte("{}"), 0o640); err != nil {
		t.Fatal(err)
	}
	info, err := os.Lstat(p)
	if err != nil {
		t.Fatal(err)
	}
	f, err := os.Open(p)
	if err != nil {
		t.Fatal(err)
	}
	_ = f.Close()
	if uid, _ := fileOwner(info); uid < 0 {
		t.Skip("no file owner on this platform")
	}
	if err := preserveOwner(f, info); err != nil {
		t.Fatalf("preserveOwner called fchown for a file we already own: %v", err)
	}
}

func TestPreserveOwnerIgnoresAMissingFile(t *testing.T) {
	if err := preserveOwner(nil, nil); err != nil {
		t.Fatal(err)
	}
}

package hosttune

// driftingCurrent names the checks whose Current text moves on every report
// ("61% free (210.0 GiB)"). Acceptable bars the same two for the same reason,
// and a test holds the two lists together.
var driftingCurrent = map[string]bool{"disk.space": true, "disk.inodes": true}

// SameFindings reports whether o says the same thing as r, ignoring when it was
// taken. disk.space and disk.inodes may differ in Current when their Status is
// equal: those figures move every report, so treating them as news would
// rewrite the stored body on every report of a busy host.
//
// The operator's marks (Accepted, Ended, Acceptable) are not compared. They are
// scrubbed on the way in and stamped at read time, so a decision never makes
// two reports differ.
func (r Report) SameFindings(o Report) bool {
	if r.OS != o.OS || r.Distro != o.Distro || r.WorkDir != o.WorkDir ||
		r.Container != o.Container || r.RebootPending != o.RebootPending ||
		len(r.Results) != len(o.Results) {
		return false
	}
	for i, a := range r.Results {
		b := o.Results[i]
		if a.ID != b.ID || a.Title != b.Title || a.Tier != b.Tier || a.Status != b.Status ||
			a.Recommended != b.Recommended || a.Rationale != b.Rationale || a.Reason != b.Reason ||
			a.Actionable != b.Actionable || a.Optional != b.Optional {
			return false
		}
		if a.Current != b.Current && !driftingCurrent[a.ID] {
			return false
		}
	}
	return true
}

package hosttune

import (
	"strings"
	"testing"
	"time"
)

func sampleReport() Report {
	return Report{
		CheckedAt: time.Unix(1000, 0).UTC(),
		OS:        "linux", Distro: "ubuntu", WorkDir: "/var/lib/zoomies",
		Results: []Result{
			{ID: "disk.space", Title: "Free space", Tier: Safe, Status: OK, Current: "61% free (210.0 GiB)"},
			{ID: "sysctl.somaxconn", Title: "Backlog", Tier: Safe, Status: Warn, Current: "128", Recommended: "4096", Rationale: "why", Actionable: true},
		},
	}
}

func TestSameFindingsIgnoresWhenAReportWasTaken(t *testing.T) {
	a, b := sampleReport(), sampleReport()
	b.CheckedAt = a.CheckedAt.Add(time.Hour)
	if !a.SameFindings(b) {
		t.Fatal("two reports that differ only in time should say the same thing")
	}
}

func TestSameFindingsIgnoresDriftingDiskFiguresWhileTheStatusHolds(t *testing.T) {
	a, b := sampleReport(), sampleReport()
	b.Results[0].Current = "60% free (209.0 GiB)"
	if !a.SameFindings(b) {
		t.Fatal("free space moving by a point is not news; a busy host would rewrite on every report")
	}
	b.Results[0].Status = Warn
	if a.SameFindings(b) {
		t.Fatal("a disk check changing status is news")
	}
}

func TestSameFindingsNoticesEveryOtherChange(t *testing.T) {
	edits := map[string]func(*Report){
		"os":          func(r *Report) { r.OS = "darwin" },
		"distro":      func(r *Report) { r.Distro = "debian" },
		"work dir":    func(r *Report) { r.WorkDir = "/srv" },
		"container":   func(r *Report) { r.Container = true },
		"reboot":      func(r *Report) { r.RebootPending = true },
		"added":       func(r *Report) { r.Results = append(r.Results, Result{ID: "x", Title: "x", Tier: Safe, Status: OK}) },
		"removed":     func(r *Report) { r.Results = r.Results[:1] },
		"reordered":   func(r *Report) { r.Results[0], r.Results[1] = r.Results[1], r.Results[0] },
		"id":          func(r *Report) { r.Results[1].ID = "other" },
		"title":       func(r *Report) { r.Results[1].Title = "other" },
		"tier":        func(r *Report) { r.Results[1].Tier = Aggressive },
		"status":      func(r *Report) { r.Results[1].Status = OK },
		"current":     func(r *Report) { r.Results[1].Current = "129" },
		"recommended": func(r *Report) { r.Results[1].Recommended = "1" },
		"rationale":   func(r *Report) { r.Results[1].Rationale = "other" },
		"reason":      func(r *Report) { r.Results[1].Reason = "other" },
		"actionable":  func(r *Report) { r.Results[1].Actionable = false },
		"optional":    func(r *Report) { r.Results[1].Optional = true },
	}
	for name, edit := range edits {
		t.Run(name, func(t *testing.T) {
			a, b := sampleReport(), sampleReport()
			edit(&b)
			if a.SameFindings(b) {
				t.Fatalf("a change to %s should count as news", name)
			}
		})
	}
}

func TestSameFindingsDoesNotCompareTheOperatorsMarks(t *testing.T) {
	a, b := sampleReport(), sampleReport()
	b.Results[1].Acceptable = true
	b.Results[1].Accepted = &Acceptance{}
	if !a.SameFindings(b) {
		t.Fatal("marks are stamped at read time and must not make reports differ")
	}
}

// The two lists exist for the same reason, so they must not drift apart: a
// check whose figure moves should neither be acceptable nor count as news.
func TestEveryDriftingCheckIsOneThatCannotBeAccepted(t *testing.T) {
	for id := range driftingCurrent {
		ok, why := Acceptable(id)
		if ok || !strings.Contains(why, "Free space moves") {
			t.Errorf("%s drifts but Acceptable says (%v, %q)", id, ok, why)
		}
	}
}

package hosttune

import (
	"sync"
	"time"
)

// ReportStaleAfter is how long a connected host may go without a newer OS
// report before Zoomies says its collector has stopped. It is later than the
// three minutes the host page greys a badge after -- that is a display, this
// raises a problem -- and later than the monitor's one-minute interval plus its
// 45s timeout. CheckedAt is the host's clock and the comparison is the
// controller's, so the slack also absorbs a clock that is a little off.
const ReportStaleAfter = 10 * time.Minute

// KernelPending is the check whose warning is the reboot flag: Run sets
// Report.RebootPending from it, so the one fact is already carried twice in a
// report. Summary and Findings count it once, as the reboot, and leave the row
// out of the checks that need attention.
const KernelPending = "kernel.pending"

// Counted is whether a result counts towards a host's health: the safe tier,
// and not an optional suggestion. That is what zoomies doctor counts by
// default. The other tiers are choices an operator opts into, so a host that
// has not made them is not unwell. A result with no tier is not counted.
func (x Result) Counted() bool { return x.Tier == Safe && !x.Optional }

// Summary is the one count every surface agrees on -- the host payload, the
// problems, the metrics, the feed, hosts list and MCP. It is worked out from
// the results on every read and is never stored or sent by an agent, so it
// cannot outlive the report it counts or be claimed by a host.
//
// Counts, which the CLI uses for the tier it ran and for exit codes, still
// counts every result on purpose: `doctor --tier aggressive` must exit 1 on an
// aggressive warning, and TestReportExitCodes builds results with no tier. It
// makes one exception, for a warning an operator has accepted: that is a
// decision about this host, so a report the controller judged exits 0 here as
// the page says it is well.
//
// A pending reboot is counted once. When the report says RebootPending, the
// kernel.pending warning is the same fact and is left out of every number here,
// so a host whose only finding is a reboot raises the reboot and not a failing
// check. Counts does not make that exception, which makes zoomies doctor's own
// warning count one higher than Warnings for exactly that check; a person
// reading the doctor's rows sees the row, and the reboot hint beside it, rather
// than a total that silently omits one.
type Summary struct {
	// Counted is how many counted checks there are, whatever they found, so a
	// reader can tell "every check passed" from "every check was skipped".
	Counted  int `json:"counted"`
	Warnings int `json:"warnings"`
	Errors   int `json:"errors"`
	Skipped  int `json:"skipped"`
	// Suggestions are the warnings that do not count: other tiers, and
	// anything optional. An uncounted error or skip is in no number; it is
	// still in the results.
	Suggestions int `json:"suggestions"`
	// Accepted are counted warnings an operator has accepted as deliberate. They
	// are in Counted, so "every check was accepted" can be told from "every check
	// was skipped", and in neither Warnings nor Suggestions: they leave the
	// list and the problems, and stay visible here.
	Accepted int `json:"accepted"`
}

// rebootRow is the kernel.pending warning of a report that already says a
// reboot is pending. Only a warning: a check that could not run, or one that
// passed, is not the reboot, and a report that contradicts itself is judged by
// its rows.
func (r Report) rebootRow(x Result) bool {
	return r.RebootPending && x.ID == KernelPending && x.Status == Warn
}

// Summary counts the report once, for every surface to read.
func (r Report) Summary() Summary {
	var s Summary
	for _, x := range r.Results {
		if r.rebootRow(x) {
			continue
		}
		if !x.Counted() {
			if x.Status == Warn {
				s.Suggestions++
			}
			continue
		}
		s.Counted++
		if x.Accepting() && x.Status == Warn {
			s.Accepted++
			continue
		}
		switch x.Status {
		case Warn:
			s.Warnings++
		case Error:
			s.Errors++
		case Skip:
			s.Skipped++
		}
	}
	return s
}

// Findings is what Summary counts as warnings and errors, errors first and the
// engine's own order within each, so a problem and a page name the same
// checks. len(Findings()) == Warnings + Errors, by construction and by test.
func (r Report) Findings() []Result {
	var errs, warns []Result
	for _, x := range r.Results {
		if !x.Counted() || r.rebootRow(x) || x.Accepting() {
			continue
		}
		switch x.Status {
		case Error:
			errs = append(errs, x)
		case Warn:
			warns = append(warns, x)
		}
	}
	return append(errs, warns...)
}

// titles is the catalogue of check names this build knows, built from the same
// constructors the engine runs. They are closures with no I/O, so building the
// list reads nothing from the machine the controller is on.
var titles = sync.OnceValue(func() map[string]string {
	// environment is not a Check: Run adds it by hand, so it is named here. The
	// engine gives it a second title when the operating system is not Linux,
	// but that result is a skip and is never a finding.
	m := map[string]string{"environment": "Distribution"}
	for _, list := range [][]Check{baseChecks(), kernelChecks(), dedicatedChecks()} {
		for _, c := range list {
			m[c.ID] = c.Title
		}
	}
	return m
})

// Title is this build's own name for a check, or false for one it has not heard
// of. A problem names checks with it and never with the report's own text,
// which an agent wrote.
func Title(id string) (string, bool) {
	t, ok := titles()[id]
	return t, ok
}

package hosttune

import (
	"context"
	"encoding/json"
	"slices"
	"testing"
	"time"
)

// res builds a result the way the engine would stamp it: a tier, an outcome and
// whether the check is only a suggestion. The id is what the Findings tests
// read back, so each case can say which rows it expects.
func res(id string, tier Tier, status Status, optional bool) Result {
	return Result{ID: id, Title: id, Tier: tier, Status: status, Optional: optional}
}

func ids(rs []Result) []string {
	out := []string{}
	for _, x := range rs {
		out = append(out, x.ID)
	}
	return out
}

// summaryCases is shared by the Summary and Findings tests so the two are
// judged on the same reports: a problem that names the checks and a count that
// says how many must never be able to disagree.
var summaryCases = []struct {
	name   string
	report Report
	want   Summary
	// findings are the ids Findings must return, in order.
	findings []string
}{
	{
		name:   "a report with no results counts nothing",
		report: Report{Results: []Result{}},
		want:   Summary{},
	},
	{
		// The three tiers and the optional checks in one report. Only the safe,
		// non-optional rows are the host's health; everything else is a choice the
		// operator has not made, and a stock host carries those for ever.
		name: "only safe checks that are not optional count, and the rest are suggestions",
		report: Report{Results: []Result{
			res("inotify.watches", Safe, Warn, false),
			res("inotify.instances", Safe, OK, false),
			res("files.service", Safe, Skip, false),
			res("docker.logs", Safe, Error, false),
			res("disk.space", Safe, Warn, false),
			res("cpu.governor", Aggressive, Warn, false),
			res("memory.swappiness", Aggressive, OK, false),
			res("tmp.tmpfs", Aggressive, Warn, true),
			res("service.snapd", Dedicated, Warn, false),
			res("memory.swap-off", Dedicated, Warn, true),
			res("kernel.hwe-install", Dedicated, Skip, true),
			res("service.fwupd", Dedicated, Error, false),
			// Nothing in the engine is both safe and optional today; the rule is
			// still that optional wins, so a check added tomorrow is a suggestion.
			res("future.safe-optional", Safe, Warn, true),
		}},
		want:     Summary{Counted: 5, Warnings: 2, Errors: 1, Skipped: 1, Suggestions: 5},
		findings: []string{"docker.logs", "inotify.watches", "disk.space"},
	},
	{
		// An uncounted error or skip is in no number: it is still in the results
		// for anyone who opens the host, but it is not the host being unwell.
		name: "an error or skip outside the counted checks is in no number",
		report: Report{Results: []Result{
			res("service.fwupd", Dedicated, Error, false),
			res("kernel.hwe-install", Dedicated, Skip, true),
			res("cpu.governor", Aggressive, Skip, false),
			res("cgroup.version", Safe, OK, false),
		}},
		want: Summary{Counted: 1},
	},
	{
		// TestReportExitCodes builds results with no tier because Counts has no
		// use for one. The summary does, and a row that does not say which tier it
		// belongs to is not evidence that the host is unwell.
		name: "a result with no tier is not counted",
		report: Report{Results: []Result{
			{ID: "inotify.watches", Status: Warn},
			{ID: "docker.logs", Status: Error},
			{ID: "files.service", Status: Skip},
			{ID: "cgroup.version", Status: OK},
		}},
		want: Summary{Suggestions: 1},
	},
	{
		name: "every counted check passing counts them all and finds nothing",
		report: Report{Results: []Result{
			res("inotify.watches", Safe, OK, false),
			res("docker.logs", Safe, OK, false),
		}},
		want: Summary{Counted: 2},
	},
	{
		// Counted is what separates "everything passed" from "nothing could be
		// checked", which the host page words differently.
		name: "every counted check skipped is told apart from every counted check passing",
		report: Report{Results: []Result{
			res("inotify.watches", Safe, Skip, false),
			res("docker.logs", Safe, Skip, false),
		}},
		want: Summary{Counted: 2, Skipped: 2},
	},
	{
		// A reboot is one fact the engine records twice: as the kernel.pending
		// warning and as Report.RebootPending. It is counted once, as the reboot.
		name: "a host whose only finding is a pending reboot has no finding",
		report: Report{RebootPending: true, Results: []Result{
			res("kernel.running", Safe, OK, false),
			res(KernelPending, Safe, Warn, false),
			res("cgroup.version", Safe, OK, false),
		}},
		want: Summary{Counted: 2},
	},
	{
		name: "a pending reboot is left out and the other warnings still count",
		report: Report{RebootPending: true, Results: []Result{
			res("docker.storage", Safe, Warn, false),
			res(KernelPending, Safe, Warn, false),
			res("docker.logs", Safe, Error, false),
		}},
		want:     Summary{Counted: 2, Warnings: 1, Errors: 1},
		findings: []string{"docker.logs", "docker.storage"},
	},
	{
		// The exclusion belongs to the report's own claim. A row that warns with no
		// pending reboot reported beside it is judged as any other row.
		name: "the kernel.pending warning counts when the report does not say a reboot is pending",
		report: Report{RebootPending: false, Results: []Result{
			res(KernelPending, Safe, Warn, false),
			res("cgroup.version", Safe, OK, false),
		}},
		want:     Summary{Counted: 2, Warnings: 1},
		findings: []string{KernelPending},
	},
	{
		// Only the warning is the reboot. A kernel.pending row that passed or that
		// could not run is an ordinary row in a report that happens to contradict
		// itself, and is counted as one.
		name: "only a warning is taken for the reboot",
		report: Report{RebootPending: true, Results: []Result{
			res(KernelPending, Safe, Error, false),
			res("docker.logs", Safe, OK, false),
		}},
		want:     Summary{Counted: 2, Errors: 1},
		findings: []string{KernelPending},
	},
	{
		name: "a reboot says nothing about a result in another tier",
		report: Report{RebootPending: true, Results: []Result{
			res(KernelPending, Safe, Warn, false),
			res("cpu.governor", Aggressive, Warn, false),
		}},
		want: Summary{Suggestions: 1},
	},
}

func TestSummaryCountsOnlyWhatAHostIsJudgedOn(t *testing.T) {
	for _, tc := range summaryCases {
		t.Run(tc.name, func(t *testing.T) {
			if got := tc.report.Summary(); got != tc.want {
				t.Errorf("Summary() = %+v, want %+v", got, tc.want)
			}
		})
	}
}

// A problem names the checks Findings returns and says how many with Summary. If
// the two were counted by separate rules, a host would raise "3 checks need
// attention" and then name two.
func TestFindingsAreExactlyWhatSummaryCountsAsWarningsAndErrors(t *testing.T) {
	for _, tc := range summaryCases {
		t.Run(tc.name, func(t *testing.T) {
			got := tc.report.Findings()
			s := tc.report.Summary()
			if len(got) != s.Warnings+s.Errors {
				t.Errorf("len(Findings()) = %d, but Summary() counts %d warnings and %d errors", len(got), s.Warnings, s.Errors)
			}
			if !slices.Equal(ids(got), append([]string{}, tc.findings...)) {
				t.Errorf("Findings() = %v, want %v", ids(got), tc.findings)
			}
		})
	}
}

// Errors come first because a check that could not run is what an operator
// should look at before a setting that is merely below the recommendation, and
// the engine's own order inside each rank keeps the text of a problem stable
// from one report to the next, which is what keeps problems.updated quiet.
func TestFindingsPutErrorsFirstAndKeepTheEnginesOrderWithinARank(t *testing.T) {
	r := Report{Results: []Result{
		res("w1", Safe, Warn, false),
		res("e1", Safe, Error, false),
		res("ok", Safe, OK, false),
		res("w2", Safe, Warn, false),
		res("skipped", Safe, Skip, false),
		res("e2", Safe, Error, false),
		res("suggestion", Aggressive, Warn, false),
		res("optional", Safe, Warn, true),
		res("w3", Safe, Warn, false),
	}}
	want := []string{"e1", "e2", "w1", "w2", "w3"}
	if got := ids(r.Findings()); !slices.Equal(got, want) {
		t.Errorf("Findings() = %v, want %v", got, want)
	}
	// The slice is the caller's own: a problem builder that appends to it must
	// not be writing into the report a host's view is rendered from.
	first := r.Findings()
	_ = append(first[:1], res("intruder", Safe, Warn, false))
	if got := ids(r.Findings()); !slices.Equal(got, want) {
		t.Errorf("Findings() after a caller appended = %v, want %v", got, want)
	}
	if r.Results[1].ID != "e1" {
		t.Errorf("Findings() wrote into the report's results: %v", ids(r.Results))
	}
}

func TestOnlyASafeCheckThatIsNotOptionalIsCounted(t *testing.T) {
	for _, tc := range []struct {
		tier     Tier
		optional bool
		want     bool
	}{
		{Safe, false, true},
		{Safe, true, false},
		{Aggressive, false, false},
		{Aggressive, true, false},
		{Dedicated, false, false},
		{Dedicated, true, false},
		{"", false, false},
		{"", true, false},
	} {
		if got := res("x", tc.tier, Warn, tc.optional).Counted(); got != tc.want {
			t.Errorf("Counted() for tier %q, optional %v = %v, want %v", tc.tier, tc.optional, got, tc.want)
		}
	}
}

// The summary is a contract with the UI, the CLI and the metrics, and a missing
// key reads as "unknown" where a zero reads as "none". A host with nothing wrong
// must still send all six numbers.
func TestSummaryAlwaysCarriesAllSixNumbers(t *testing.T) {
	b, err := json.Marshal(Report{}.Summary())
	if err != nil {
		t.Fatal(err)
	}
	if want := `{"counted":0,"warnings":0,"errors":0,"skipped":0,"suggestions":0,"accepted":0}`; string(b) != want {
		t.Errorf("an empty summary marshals as %s, want %s", b, want)
	}
}

// The docs and the problem text say ten minutes in words. Moving the threshold
// is a decision about those, not a tidy-up of a constant.
func TestAReportIsStaleAfterTenMinutes(t *testing.T) {
	if ReportStaleAfter != 10*time.Minute {
		t.Errorf("ReportStaleAfter = %s; docs/host-health.md and docs/problem-codes.md say ten minutes, so change them with it", ReportStaleAfter)
	}
}

// mixedHost is a supported host with one of each outcome in its safe checks: two
// warnings, an error from a daemon.json that is not JSON, and the rest skipped
// because the fake host has nothing to read.
func mixedHost(osRelease string) *Engine {
	f := fake()
	f.put("/etc/os-release", osRelease)
	f.put("/sys/fs/cgroup/cgroup.controllers", "")
	f.put("/proc/sys/fs/inotify/max_user_watches", "1024")
	f.put("/proc/sys/vm/swappiness", "60")
	f.commands["docker info --format {{.Driver}}"] = "vfs"
	f.commands["docker info --format {{.LoggingDriver}}"] = "json-file"
	f.commands["docker info --format {{json .SecurityOptions}}"] = `["name=seccomp"]`
	f.put("/etc/docker/daemon.json", "{")
	return New(Options{System: f, OS: "linux", UID: 0, Now: func() time.Time { return time.Unix(1234, 0) }, WorkDir: "/work"})
}

// Counts is what zoomies doctor prints and exits on, and Summary is what every
// other surface shows. They are two functions only because doctor must count the
// tier it was asked to run. On the default run they have to agree, and they do
// today for one reason: no safe check is optional. This pins that reason. If a
// safe check is ever made optional the two numbers will part, and that wants a
// decision about what doctor prints -- not a surprise on a dashboard.
func TestDoctorsOwnCountsAgreeWithTheSummaryOnTheDefaultRun(t *testing.T) {
	for _, c := range append(append(baseChecks(), kernelChecks()...), dedicatedChecks()...) {
		if c.Tier == Safe && c.Optional {
			t.Errorf("%s is a safe check marked optional: Counts() and Summary() now disagree on the default doctor run, so decide which is right before adding it", c.ID)
		}
	}
	for _, tc := range []struct {
		name      string
		osRelease string
	}{
		{"a supported distribution", "ID=ubuntu\nVERSION_ID=24.04\n"},
		// The distribution warning is a safe, non-optional row the engine adds by
		// hand, so it has to be counted by both.
		{"an unsupported distribution", "ID=fedora\nVERSION_ID=42\n"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			r := mixedHost(tc.osRelease).Run(context.Background(), Safe)
			w, e, s := r.Counts()
			if w == 0 || e == 0 || s == 0 {
				t.Fatalf("the fixture must produce a warning, an error and a skip or this guard proves nothing: %d, %d, %d", w, e, s)
			}
			got := r.Summary()
			if got.Warnings != w || got.Errors != e || got.Skipped != s {
				t.Errorf("Counts() = %d warnings, %d errors, %d skipped; Summary() = %+v", w, e, s, got)
			}
			if got.Suggestions != 0 {
				t.Errorf("a safe run has no suggestions, got %d", got.Suggestions)
			}
		})
	}
}

// doctor --tier aggressive and --dedicated count what they ran, exit code
// included, so Counts must keep counting every tier. The summary, by contrast,
// must not let a stock host's aggressive warnings read as an unwell host.
func TestACountedTierIsDoctorsToCountAndASuggestionToTheSummary(t *testing.T) {
	r := mixedHost("ID=ubuntu\nVERSION_ID=24.04\n").Run(context.Background(), Aggressive)
	w, _, _ := r.Counts()
	got := r.Summary()
	if w <= got.Warnings {
		t.Fatalf("Counts() = %d warnings, Summary() = %d: the aggressive swappiness warning should be counted by one and not the other", w, got.Warnings)
	}
	if got.Suggestions == 0 {
		t.Errorf("the aggressive warning should be a suggestion: %+v", got)
	}
	if r.ExitCode() == 0 {
		t.Error("doctor must still exit non-zero on what it was asked to check")
	}
}

// rebootHost is a host that has a newer kernel installed than the one running
// and nothing else wrong, which is the common state of a patched but unrebooted
// machine.
func rebootHost() *Engine {
	e := mixedHost("ID=ubuntu\nVERSION_ID=24.04\n")
	f := e.System.(*fakeSystem)
	f.commands["uname -r"] = "6.9.0-1-generic"
	f.put("/lib/modules/6.10.0-2-generic/modules.dep", "")
	// Put right everything mixedHost got wrong, leaving only the reboot.
	f.put("/proc/sys/fs/inotify/max_user_watches", "524288")
	f.commands["docker info --format {{.Driver}}"] = "overlay2"
	f.put("/etc/docker/daemon.json", `{"log-opts":{"max-size":"10m","max-file":"3"}}`)
	return e
}

// This is the one place doctor and the summary are meant to differ on the
// default run. A reboot is a fact about the host rather than a setting to fix,
// so the summary counts it once, as the reboot, and a host that is only waiting
// for one is not flagged as unwell as well. doctor still lists the row.
func TestAPendingRebootIsCountedOnceByTheSummaryAndTwiceByDoctor(t *testing.T) {
	ctx := context.Background()

	r := rebootHost().Run(ctx, Safe)
	if !r.RebootPending {
		t.Fatalf("the fixture must have a reboot pending: %+v", r.Results)
	}
	if w, e, _ := r.Counts(); w != 1 || e != 0 {
		t.Fatalf("doctor counts %d warnings and %d errors, want just the kernel.pending warning", w, e)
	}
	got := r.Summary()
	if got.Warnings != 0 || got.Errors != 0 || len(r.Findings()) != 0 {
		t.Errorf("a host whose only finding is a reboot should have none: %+v %v", got, ids(r.Findings()))
	}
	if safe := len(r.Results); got.Counted != safe-1 {
		t.Errorf("Counted = %d, want every safe row but the reboot, %d", got.Counted, safe-1)
	}

	// Another warning beside it is still a finding, and the reboot is still not.
	e := rebootHost()
	e.System.(*fakeSystem).commands["docker info --format {{.Driver}}"] = "vfs"
	r = e.Run(ctx, Safe)
	got = r.Summary()
	if got.Warnings != 1 || !slices.Equal(ids(r.Findings()), []string{"docker.storage"}) {
		t.Errorf("want only the storage driver flagged, got %+v %v", got, ids(r.Findings()))
	}
	if w, _, _ := r.Counts(); w != got.Warnings+1 {
		t.Errorf("doctor counts %d warnings, want one more than the summary's %d", w, got.Warnings)
	}
}

// Run sets RebootPending from the constant, and the exclusion above is only
// right while the constant names the check that sets it.
func TestTheRebootFlagIsSetByTheCheckTheConstantNames(t *testing.T) {
	found := false
	for _, c := range kernelChecks() {
		if c.ID == KernelPending {
			found = true
		}
	}
	if !found {
		t.Fatalf("no kernel check has the id %q that Run reads the reboot flag from", KernelPending)
	}
}

// A problem names checks from this catalogue and never from the report, whose
// every field an agent wrote and which any signed-in viewer can read back. So
// every check the engine can emit must be named here, or a real finding would
// be reported as one the controller has never heard of.
func TestEveryCheckTheEngineCanEmitHasATitle(t *testing.T) {
	ctx := context.Background()
	for _, tc := range []struct {
		name string
		e    *Engine
	}{
		{"a supported host", mixedHost("ID=ubuntu\nVERSION_ID=24.04\n")},
		{"an unsupported distribution", mixedHost("ID=fedora\nVERSION_ID=42\n")},
		{"another operating system", New(Options{System: fake(), OS: "darwin", UID: 0, Now: time.Now})},
	} {
		t.Run(tc.name, func(t *testing.T) {
			for _, c := range tc.e.Checks {
				got, ok := Title(c.ID)
				if !ok || got != c.Title {
					t.Errorf("Title(%q) = %q, %v; the engine calls it %q", c.ID, got, ok, c.Title)
				}
			}
			for _, x := range tc.e.Run(ctx, Dedicated).Results {
				if _, ok := Title(x.ID); !ok {
					t.Errorf("the engine emitted %q, which has no title", x.ID)
				}
			}
		})
	}
	if got, ok := Title("environment"); !ok || got != "Distribution" {
		t.Errorf(`Title("environment") = %q, %v`, got, ok)
	}
}

func TestACheckTheControllerHasNotHeardOfHasNoTitle(t *testing.T) {
	for _, id := range []string{"", "made.up", "Kernel.Pending", " kernel.pending", "service."} {
		if got, ok := Title(id); ok || got != "" {
			t.Errorf("Title(%q) = %q, %v, want nothing", id, got, ok)
		}
	}
}

