		e, f := fixture()
		f.put("/proc/sys/fs/inotify/max_user_watches", "1024")
		var out strings.Builder
		if err := e.Tune(context.Background(), TuneOptions{DryRun: dry, Only: IDs("inotify.watches"), In: strings.NewReader("n\n"), Out: &out}); err != nil {
