// An answer file is an unattended install, and the account it makes is the
// platform one: the audit log has to say the system made it and that an
// answer file said to, or the first row of every such instance's history is
// an account nobody can account for.
func TestTheAnswerFileAdministratorIsAudited(t *testing.T) {
	ctx := context.Background()
	st, err := store.Open(ctx, store.Options{Path: ":memory:"})
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })

	i := &Installer{out: &bytes.Buffer{}, ui: newUI(&bytes.Buffer{}), log: slog.New(slog.DiscardHandler)}
	p := Plan{AdminUser: "ada", adminPassword: "correct-horse-battery"}
	if err := i.stepAdmin(ctx, st, config.Default(), p); err != nil {
		t.Fatalf("stepAdmin: %v", err)
	}

	rows, _, err := st.ListAudit(ctx, store.AuditFilter{Actions: []string{"auth.bootstrap"}}, store.Page{Limit: 10})
	if err != nil {
		t.Fatalf("ListAudit: %v", err)
	}
	if len(rows) != 1 {
		t.Fatalf("got %d auth.bootstrap rows; want exactly one", len(rows))
	}
	if rows[0].ActorKind != auth.KindSystem || !strings.Contains(rows[0].After, auth.BootstrapAnswerFile) {
		t.Fatalf("the row is by %s and says %s; want the system and the answer file", rows[0].ActorKind, rows[0].After)
	}
}

package installer

import (
	"fmt"
	"io"
	"os"
	"strings"

	"gopkg.in/yaml.v3"
)

// Answers is the answer file: one YAML key for every question `zoomies init`
// would otherwise ask.
//
// It exists so that a fleet can be rebuilt by configuration management without
// anyone sitting in front of it. Every field maps to exactly one prompt, and
// the non-interactive path uses the same decision code as the interactive one,
// so an answer file cannot drift away from what the prompts do.
type Answers struct {
	// Mode is single, controller or agent.
	Mode string `yaml:"mode"`
	// Deployment is native, compose or docker: how this host runs Zoomies,
	// which is a separate question from what it runs.
	Deployment string `yaml:"deployment"`
	// DeploymentDir is where a compose or docker deployment writes its
	// docker-compose.yml and its environment file.
	DeploymentDir string `yaml:"deployment_dir"`
	// Image is the container image those deployments run.
	Image string `yaml:"image"`
	// ServiceUser is the unprivileged account the service runs as.
	ServiceUser string `yaml:"service_user"`
	ConfigDir   string `yaml:"config_dir"`
	StateDir    string `yaml:"state_dir"`

	// Backend is docker, podman or process.
	Backend string `yaml:"backend"`
	// DockerHost overrides socket autodetection.
	DockerHost string `yaml:"docker_host"`
	// Capacity is the most runners this host may hold at once.
	Capacity int `yaml:"capacity"`

	Bind           string      `yaml:"bind"`
	TLS            AnswersTLS  `yaml:"tls"`
	TrustedProxies []string    `yaml:"trusted_proxies"`
	ExternalURL    string      `yaml:"external_url"`
	GitHub         AnswersApp  `yaml:"github"`
	Admin          AnswersUser `yaml:"admin"`
	Pool           AnswersPool `yaml:"pool"`
	Service        AnswersSvc  `yaml:"service"`
	Agent          AnswersJoin `yaml:"agent"`

	// UpdateHelper adds the update helper, which the web UI uses to update this
	// host. It is a pointer, like service.enable, so that "false" can be told
	// apart from "not mentioned". Only true does anything: the helper is a
	// grant of root, so no other answer, and no --yes, installs it.
	UpdateHelper *bool `yaml:"update_helper"`

	// path records where this file came from, so errors can name it.
	path string `yaml:"-"`
}

// AnswersTLS mirrors the bind-and-TLS question.
type AnswersTLS struct {
	// Mode is "off", "files" or "self-signed". Quote it: an unquoted off is a
	// boolean in YAML, not a word.
	Mode     string   `yaml:"mode"`
	CertFile string   `yaml:"cert_file"`
	KeyFile  string   `yaml:"key_file"`
	Hosts    []string `yaml:"hosts"`
}

// AnswersApp mirrors the GitHub App questions. A non-interactive run cannot
// drive a browser, so it takes credentials that already exist instead.
type AnswersApp struct {
	APIBaseURL string `yaml:"api_base_url"`
	// Target is an organisation login, or "owner/repo" for a single repository.
	Target string `yaml:"target"`
	// TargetType is org or repo. It is derived from Target when empty.
	TargetType     string `yaml:"target_type"`
	AppID          int64  `yaml:"app_id"`
	InstallationID int64  `yaml:"installation_id"`
	// PrivateKeyFile is the .pem GitHub gave you when the App was created.
	PrivateKeyFile string `yaml:"private_key_file"`
	// WebhookSecret is the secret configured on the App's webhook. Without it
	// Zoomies cannot verify deliveries and will reject every one.
	WebhookSecret string `yaml:"webhook_secret"`
	// WebhookSecretFile keeps the secret out of the answer file, which is the
	// better habit when that file lives in a repository.
	WebhookSecretFile string `yaml:"webhook_secret_file"`
	// Skip records a deliberate decision to connect GitHub later in the UI.
	Skip bool `yaml:"skip"`
}

// AnswersUser is the first administrator.
type AnswersUser struct {
	Username string `yaml:"username"`
	// Password is here for completeness; PasswordFile is the one to use when
	// the answer file is stored anywhere shared.
	Password     string `yaml:"password"`
	PasswordFile string `yaml:"password_file"`
}

// AnswersPool mirrors the first-pool question a single-host install asks.
//
// Every field is optional: an answer file that says nothing about pools gets
// the same pool the prompt would have offered, which is the one this host can
// actually run.
type AnswersPool struct {
	// Skip finishes setup with no pool. The Pools page is then empty and
	// nothing runs until one is created.
	Skip bool `yaml:"skip"`
	// Name overrides the suggested pool name, which is derived from this
	// host's OS, architecture and backend. It is branded on the way in, so a
	// name written here without the "zoomies-" prefix is given one.
	Name string `yaml:"name"`
	// Labels are what a workflow's runs-on has to ask for. Empty means the
	// pool answers to its own name.
	Labels []string `yaml:"labels"`
	// MaxRunners caps how many runners the pool may start at once. It cannot
	// usefully exceed the host's capacity, which is where the default comes
	// from.
	MaxRunners int `yaml:"max_runners"`
}

// AnswersSvc mirrors the service question.
type AnswersSvc struct {
	// Manager is systemd, launchd, compose or none.
	Manager string `yaml:"manager"`
	// Enable and Start are pointers so that "false" can be told apart from
	// "not mentioned", which is what lets a partial answer file work.
	Enable *bool `yaml:"enable"`
	Start  *bool `yaml:"start"`
}

// AnswersJoin mirrors `zoomies agent join`.
type AnswersJoin struct {
	ControllerURL string            `yaml:"controller_url"`
	JoinToken     string            `yaml:"join_token"`
	JoinTokenFile string            `yaml:"join_token_file"`
	Name          string            `yaml:"name"`
	Labels        map[string]string `yaml:"labels"`
	CAFile        string            `yaml:"ca_file"`
}

// Load reads an answer file. Unknown keys are an error, not a shrug: a typo in
// an unattended install would otherwise leave a setting silently at its
// default and be found weeks later.
func Load(path string) (*Answers, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("installer: reading the answer file %s: %w (write one with `zoomies init --print-answers > %s`)", path, err, path)
	}
	var a Answers
	dec := yaml.NewDecoder(strings.NewReader(string(b)))
	dec.KnownFields(true)
	if err := dec.Decode(&a); err != nil && err != io.EOF {
		return nil, fmt.Errorf("installer: %s is not a valid answer file: %w", path, err)
	}
	a.path = path
	a.normalize()
	return &a, nil
}

// Path returns the file these answers were read from, for error messages.
func (a *Answers) Path() string {
	if a == nil {
		return ""
	}
	return a.path
}

func (a *Answers) normalize() {
	a.Mode = strings.ToLower(strings.TrimSpace(a.Mode))
	a.Deployment = strings.ToLower(strings.TrimSpace(a.Deployment))
	a.Backend = strings.ToLower(strings.TrimSpace(a.Backend))
	a.TLS.Mode = strings.ToLower(strings.TrimSpace(a.TLS.Mode))
	a.Service.Manager = strings.ToLower(strings.TrimSpace(a.Service.Manager))
	a.GitHub.TargetType = strings.ToLower(strings.TrimSpace(a.GitHub.TargetType))
	a.GitHub.Target = strings.TrimSpace(a.GitHub.Target)
	a.ExternalURL = strings.TrimRight(strings.TrimSpace(a.ExternalURL), "/")
	a.Agent.ControllerURL = strings.TrimRight(strings.TrimSpace(a.Agent.ControllerURL), "/")
	a.Admin.Username = strings.TrimSpace(a.Admin.Username)
	// "false" is what a YAML 1.1 parser makes of an unquoted "off", and an
	// operator who wrote that meant the TLS mode.
	if a.TLS.Mode == "false" {
		a.TLS.Mode = "off"
	}
}

// MissingAnswer names one answer a non-interactive run cannot invent, and says
// what it is for. Silently defaulting any of these would produce a controller
// that starts and then does not work.
type MissingAnswer struct {
	Key string
	Why string
}

func (m MissingAnswer) String() string { return m.Key + " -- " + m.Why }

// Missing lists the answers this file still needs for a given mode. A nil
// Answers is treated as an empty one, which is what a run with no answer file
// at all should report.
func (a *Answers) Missing(mode Mode) []MissingAnswer {
	if a == nil {
		a = &Answers{}
	}
	var out []MissingAnswer
	need := func(ok bool, key, why string) {
		if !ok {
			out = append(out, MissingAnswer{Key: key, Why: why})
		}
	}

	if mode == ModeAgent {
		need(a.Agent.ControllerURL != "", "agent.controller_url",
			"the controller this host joins, e.g. https://zoomies.example.com")
		need(a.Agent.JoinToken != "" || a.Agent.JoinTokenFile != "", "agent.join_token",
			"a join token from the UI under Hosts, or `zoomies hosts join-token create`")
		return out
	}

	need(a.ExternalURL != "", "external_url",
		"the URL GitHub and your browser reach this controller on; it forms the webhook URL")
	// A container's database lives in a volume the installer never opens, so
	// its first administrator is created in the browser rather than here.
	if !Deployment(a.Deployment).Containerised() {
		need(a.Admin.Username != "", "admin.username",
			"the first administrator's login name")
		need(a.Admin.Password != "" || a.Admin.PasswordFile != "", "admin.password",
			"the first administrator's password, or admin.password_file to keep it out of this file")
	}

	if !a.GitHub.Skip {
		need(a.GitHub.Target != "", "github.target",
			"the organisation, or owner/repo, whose runners this fleet manages")
		need(a.GitHub.AppID != 0, "github.app_id",
			"the GitHub App's ID; unattended setup cannot drive the browser handshake, so create the App first and paste its numbers here")
		need(a.GitHub.InstallationID != 0, "github.installation_id",
			"the installation ID from the App's installation page URL")
		need(a.GitHub.PrivateKeyFile != "", "github.private_key_file",
			"the path to the App's .pem private key, which Zoomies seals with the instance encryption key")
		need(a.GitHub.WebhookSecret != "" || a.GitHub.WebhookSecretFile != "", "github.webhook_secret",
			"the App's webhook secret; without it every delivery fails signature validation")
	}
	if a.TLS.Mode == "files" {
		need(a.TLS.CertFile != "", "tls.cert_file", "the certificate to serve")
		need(a.TLS.KeyFile != "", "tls.key_file", "the certificate's private key")
	}
	return out
}

// Validate returns an error naming every missing key, or nil.
func (a *Answers) Validate(mode Mode) error {
	missing := a.Missing(mode)
	if len(missing) == 0 {
		return nil
	}
	var b strings.Builder
	where := a.Path()
	if where == "" {
		where = "this run"
	}
	fmt.Fprintf(&b, "installer: %s cannot continue without these answers (%s):\n", where, mode)
	for _, m := range missing {
		fmt.Fprintf(&b, "  - %s: %s\n", m.Key, m.Why)
	}
	b.WriteString("write them with `zoomies init --print-answers > answers.yaml`, fill it in, and pass --answers answers.yaml")
	return fmt.Errorf("%s", b.String())
}

// AdminPassword resolves the administrator's password, preferring the file so
// that the secret need never be written into the answer file itself.
func (a *Answers) AdminPassword() (string, error) {
	if a == nil {
		return "", nil
	}
	if a.Admin.PasswordFile != "" {
		b, err := os.ReadFile(a.Admin.PasswordFile)
		if err != nil {
			return "", fmt.Errorf("installer: reading admin.password_file %s: %w", a.Admin.PasswordFile, err)
		}
		return strings.TrimRight(string(b), "\r\n"), nil
	}
	return a.Admin.Password, nil
}

// WebhookSecret resolves the App's webhook secret from the file or the inline
// value.
func (a *Answers) WebhookSecret() (string, error) {
	if a == nil {
		return "", nil
	}
	if a.GitHub.WebhookSecretFile != "" {
		b, err := os.ReadFile(a.GitHub.WebhookSecretFile)
		if err != nil {
			return "", fmt.Errorf("installer: reading github.webhook_secret_file %s: %w", a.GitHub.WebhookSecretFile, err)
		}
		return strings.TrimSpace(string(b)), nil
	}
	return a.GitHub.WebhookSecret, nil
}

// PrivateKey reads the GitHub App's private key. The PEM is returned rather
// than kept, so the caller can seal it and let it go out of scope.
func (a *Answers) PrivateKey() (string, error) {
	if a == nil || a.GitHub.PrivateKeyFile == "" {
		return "", nil
	}
	b, err := os.ReadFile(a.GitHub.PrivateKeyFile)
	if err != nil {
		return "", fmt.Errorf("installer: reading github.private_key_file %s: %w (it is the .pem GitHub offered once, when the App was created)", a.GitHub.PrivateKeyFile, err)
	}
	if !strings.Contains(string(b), "PRIVATE KEY") {
		return "", fmt.Errorf("installer: %s does not look like a PEM private key; download a new one from the App's settings page", a.GitHub.PrivateKeyFile)
	}
	return string(b), nil
}

// JoinToken resolves the join token for `zoomies agent join`.
func (a *Answers) JoinToken() (string, error) {
	if a == nil {
		return "", nil
	}
	if a.Agent.JoinTokenFile != "" {
		b, err := os.ReadFile(a.Agent.JoinTokenFile)
		if err != nil {
			return "", fmt.Errorf("installer: reading agent.join_token_file %s: %w", a.Agent.JoinTokenFile, err)
		}
		return strings.TrimSpace(string(b)), nil
	}
	return strings.TrimSpace(a.Agent.JoinToken), nil
}

// exampleAnswers is what `zoomies init --print-answers` emits. It is a
// commented template rather than a dump of defaults, because the person
// filling it in is deciding, not reviewing.
const exampleAnswers = `# zoomies answer file
#
#   zoomies init --non-interactive --answers answers.yaml
#
# Every key here is one question the interactive installer would ask. Anything
# left out keeps the detected or default value, except the keys marked
# REQUIRED: an unattended run refuses to guess those rather than build a
# controller that starts and then does not work.

# single     -- controller with an embedded agent, one process on one VM
# controller -- controller only; runner hosts join it separately
# agent      -- this host only runs runners
mode: single

# How this host runs Zoomies. Orthogonal to mode: any of them can be
# containerised.
#
# native   -- the binary under systemd or launchd. Leanest, starts fastest,
#             and needs no container runtime for the controller itself.
# compose  -- a docker-compose.yml and a fully populated .env, brought up with
#             "docker compose up -d". Easiest to upgrade and to move.
# docker   -- a single container from an env file. Fewest files, but you own
#             the run command.
#
# Omitted, it takes compose when this host has a compose command and native
# otherwise. A compose or docker deployment creates its first administrator in
# the browser, so admin.username and admin.password below are then unused.
deployment: compose
# Where docker-compose.yml and the .env are written. Defaults to config_dir.
# deployment_dir: /etc/zoomies
# The image those deployments run. Pin a release tag to choose when to upgrade.
# image: ghcr.io/eyupio/zoomies:latest

# The unprivileged account the service runs as. Created when init runs as root.
service_user: zoomies
# config_dir: /etc/zoomies
# state_dir: /var/lib/zoomies

# docker | podman | process
# Rootless docker or podman is strongly preferred: a container escape from a
# job then lands on an unprivileged account rather than on root. The process
# backend gives jobs no isolation at all -- they run directly on this host.
backend: docker
# docker_host: unix:///run/user/1000/docker.sock
# The most runners this host may hold at once.
capacity: 4

# Where the controller listens. Loopback is the safe default; reach it through
# a reverse proxy or an SSH tunnel. Use 0.0.0.0:8080 only with a proxy in front
# or with TLS configured below.
bind: 127.0.0.1:8080

tls:
  # "off" (quote it -- an unquoted off is a boolean in YAML), "files" or
  # "self-signed". GitHub will not deliver webhooks to a self-signed
  # certificate, so use "files" or terminate TLS in a proxy.
  mode: "off"
  # cert_file: /etc/zoomies/tls/fullchain.pem
  # key_file: /etc/zoomies/tls/privkey.pem
  # hosts: [zoomies.example.com]

# CIDRs whose X-Forwarded-For header is believed. Set this when a proxy
# terminates TLS, or every audit entry records the proxy's address. The word
# cloudflare stands for Cloudflare's published ranges.
# trusted_proxies: [10.0.0.0/8]

# REQUIRED. How GitHub and your browser reach this controller. Webhook
# deliveries go to $external_url/webhooks/github.
external_url: https://zoomies.example.com

github:
  # https://api.github.com, or https://ghes.example.com/api/v3 for Enterprise.
  api_base_url: https://api.github.com
  # REQUIRED unless skip is true. An organisation login, or "owner/repo".
  target: acme
  # org | repo. Derived from target when omitted.
  target_type: org
  # REQUIRED unless skip is true. An unattended run cannot drive the browser
  # handshake that creates the App, so create it first -- interactively, once --
  # and paste its numbers here.
  app_id: 0
  installation_id: 0
  private_key_file: /etc/zoomies/github-app.private-key.pem
  # Prefer the file: an answer file often ends up in a repository.
  # webhook_secret_file: /etc/zoomies/webhook.secret
  webhook_secret: ""
  # Set skip to true to finish setup now and connect GitHub later in the UI.
  skip: false

admin:
  # REQUIRED. The first administrator.
  username: admin
  # REQUIRED (or password_file). At least 12 characters.
  password: ""
  # password_file: /run/secrets/zoomies-admin-password

# The first pool, created on a single-host install once GitHub is connected.
# Without one the fleet has a host and nothing to place on it, so every key
# here is optional and the defaults come from what this host actually is.
pool:
  # Set skip to true to finish setup with no pool and create one yourself.
  skip: false
  # Defaults to this host's OS and architecture, e.g. zoomies-linux-x64 (and
  # zoomies-linux-x64-host for the process backend, which gives jobs no
  # container). A name given without the zoomies- prefix is stored with one.
  # name: zoomies-linux-x64
  # What a workflow's runs-on has to ask for. Defaults to the pool's name.
  # labels: [linux-x64]
  # Defaults to capacity above. Always set a maximum somewhere: it is the only
  # backstop against a runaway workflow.
  # max_runners: 4

# Adds the update helper, so this host can be updated from the web UI.
# ` + UpdateHelperExplained + `
# It is a pair of systemd units, and a request names a release and nothing
# else; the account Zoomies runs as can trigger an upgrade by writing one. That
# is a grant of root, so it is never on by default: left out, or false, nothing
# is added and the run prints how to add it later ("sudo zoomies updates helper
# install"). Only true adds it, on a systemd host.
# update_helper: true

# Only for deployment: native.
service:
  # systemd | launchd | compose | none. Detected when omitted.
  manager: systemd
  enable: true
  start: true

# Only for mode: agent.
agent:
  # REQUIRED for mode: agent.
  controller_url: https://zoomies.example.com
  # REQUIRED for mode: agent. Mint one with:
  #   zoomies hosts join-token create --ttl 15m
  join_token: ""
  # join_token_file: /run/secrets/zoomies-join-token
  # name: build-box-3
  # labels: {zone: eu-west-1a}
  # ca_file: /etc/zoomies/controller-ca.pem
`

// WriteExample emits a commented answer-file template, which is what
// `zoomies init --print-answers` prints.
func WriteExample(w io.Writer) error {
	if _, err := io.WriteString(w, exampleAnswers); err != nil {
		return fmt.Errorf("installer: writing the answer template: %w", err)
	}
	return nil
}

package installer

import (
	"bytes"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func writeFile(t *testing.T, dir, name, body string) string {
	t.Helper()
	path := filepath.Join(dir, name)
	if err := os.WriteFile(path, []byte(body), 0o600); err != nil {
		t.Fatalf("writing %s: %v", path, err)
	}
	return path
}

func TestLoadAnswers(t *testing.T) {
	dir := t.TempDir()
	path := writeFile(t, dir, "answers.yaml", `
mode: controller
backend: podman
capacity: 6
bind: 0.0.0.0:8443
tls:
  mode: files
  cert_file: /etc/zoomies/tls/cert.pem
  key_file: /etc/zoomies/tls/key.pem
trusted_proxies: [10.0.0.0/8]
external_url: https://zoomies.example.com/
github:
  target: acme
  app_id: 42
  installation_id: 99
  private_key_file: /etc/zoomies/app.pem
  webhook_secret: shhh
admin:
  username: ada
  password: correct-horse-battery
service:
  manager: systemd
  start: false
`)

	a, err := Load(path)
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if a.Mode != "controller" || a.Backend != "podman" || a.Capacity != 6 {
		t.Fatalf("basic fields not decoded: %+v", a)
	}
	if a.ExternalURL != "https://zoomies.example.com" {
		t.Fatalf("external URL not normalised: %q", a.ExternalURL)
	}
	if a.TLS.Mode != "files" || a.TLS.CertFile == "" {
		t.Fatalf("tls block not decoded: %+v", a.TLS)
	}
	if a.Service.Start == nil || *a.Service.Start {
		t.Fatalf("service.start should decode as an explicit false, got %v", a.Service.Start)
	}
	if a.Service.Enable != nil {
		t.Fatalf("service.enable was not in the file, so it must stay nil rather than default to false")
	}
	if got := a.Path(); got != path {
		t.Fatalf("Path() = %q, want %q", got, path)
	}
}

func TestLoadAnswersRejectsUnknownKeys(t *testing.T) {
	dir := t.TempDir()
	path := writeFile(t, dir, "answers.yaml", "extenal_url: https://example.com\n")
	if _, err := Load(path); err == nil {
		t.Fatal("a typo'd key must be an error, or an unattended install silently keeps the default")
	}
}

func TestLoadAnswersMissingFile(t *testing.T) {
	_, err := Load(filepath.Join(t.TempDir(), "nope.yaml"))
	if err == nil {
		t.Fatal("want an error for a missing answer file")
	}
	if !strings.Contains(err.Error(), "--print-answers") {
		t.Fatalf("the error should say how to make one, got: %v", err)
	}
}

func TestAnswersMissingNamesEveryRequiredKey(t *testing.T) {
	var a *Answers // no answer file at all
	missing := keysOf(a.Missing(ModeSingle))

	for _, want := range []string{"external_url", "admin.username", "admin.password",
		"github.target", "github.app_id", "github.installation_id", "github.private_key_file", "github.webhook_secret"} {
		if !contains(missing, want) {
			t.Errorf("Missing() should name %q; got %v", want, missing)
		}
	}

	err := a.Validate(ModeSingle)
	if err == nil {
		t.Fatal("Validate must fail when everything is missing")
	}
	if !strings.Contains(err.Error(), "external_url") {
		t.Fatalf("the error must name the keys, got: %v", err)
	}
}

func TestAnswersMissingSkipsGitHubWhenSkipped(t *testing.T) {
	a := &Answers{ExternalURL: "https://x.example.com"}
	a.GitHub.Skip = true
	a.Admin.Username = "ada"
	a.Admin.Password = "correct-horse-battery"

	if got := a.Missing(ModeSingle); len(got) != 0 {
		t.Fatalf("nothing should be missing, got %v", keysOf(got))
	}
	if err := a.Validate(ModeSingle); err != nil {
		t.Fatalf("Validate: %v", err)
	}
}

func TestAnswersMissingForAgentMode(t *testing.T) {
	a := &Answers{}
	missing := keysOf(a.Missing(ModeAgent))
	if !contains(missing, "agent.controller_url") || !contains(missing, "agent.join_token") {
		t.Fatalf("agent mode needs a controller and a token, got %v", missing)
	}
	if contains(missing, "external_url") {
		t.Fatalf("an agent has no external URL to be missing: %v", missing)
	}
}

func TestAnswersTLSModeOffSurvivesYAMLBooleans(t *testing.T) {
	dir := t.TempDir()
	// An unquoted "off" is a boolean in YAML 1.1, and operators write it.
	path := writeFile(t, dir, "answers.yaml", "tls:\n  mode: false\n")
	a, err := Load(path)
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if a.TLS.Mode != "off" {
		t.Fatalf("tls.mode = %q, want off", a.TLS.Mode)
	}
}

func TestAnswersSecretsComeFromFiles(t *testing.T) {
	dir := t.TempDir()
	pwPath := writeFile(t, dir, "pw", "correct-horse-battery\n")
	secretPath := writeFile(t, dir, "hook", "  hunter2hunter2  \n")
	keyPath := writeFile(t, dir, "app.pem", "-----BEGIN RSA PRIVATE KEY-----\nabc\n-----END RSA PRIVATE KEY-----\n")
	tokenPath := writeFile(t, dir, "join", "zoojoin_abc\n")

	a := &Answers{}
	a.Admin.PasswordFile = pwPath
	a.GitHub.WebhookSecretFile = secretPath
	a.GitHub.PrivateKeyFile = keyPath
	a.Agent.JoinTokenFile = tokenPath

	if pw, err := a.AdminPassword(); err != nil || pw != "correct-horse-battery" {
		t.Fatalf("AdminPassword = %q, %v", pw, err)
	}
	if s, err := a.WebhookSecret(); err != nil || s != "hunter2hunter2" {
		t.Fatalf("WebhookSecret = %q, %v", s, err)
	}
	if pem, err := a.PrivateKey(); err != nil || !strings.Contains(pem, "PRIVATE KEY") {
		t.Fatalf("PrivateKey = %q, %v", pem, err)
	}
	if tok, err := a.JoinToken(); err != nil || tok != "zoojoin_abc" {
		t.Fatalf("JoinToken = %q, %v", tok, err)
	}
}

func TestPrivateKeyRejectsSomethingThatIsNotAKey(t *testing.T) {
	dir := t.TempDir()
	a := &Answers{}
	a.GitHub.PrivateKeyFile = writeFile(t, dir, "app.pem", "this is not a key\n")
	if _, err := a.PrivateKey(); err == nil {
		t.Fatal("want an error for a file that is not a PEM key")
	}
}

func TestWriteExampleRoundTrips(t *testing.T) {
	var buf bytes.Buffer
	if err := WriteExample(&buf); err != nil {
		t.Fatalf("WriteExample: %v", err)
	}
	dir := t.TempDir()
	path := writeFile(t, dir, "answers.yaml", buf.String())

	a, err := Load(path)
	if err != nil {
		t.Fatalf("the printed template must load back: %v", err)
	}
	if a.Mode != "single" {
		t.Fatalf("mode = %q, want single", a.Mode)
	}
	if a.TLS.Mode != "off" {
		t.Fatalf("tls.mode = %q, want off (it must be quoted in the template)", a.TLS.Mode)
	}
	if !strings.Contains(buf.String(), "REQUIRED") {
		t.Fatal("the template should mark the keys an unattended run cannot invent")
	}
	// The key is documented, and the template never turns it on: a file copied
	// as it stands must not grant root to the web UI.
	if !strings.Contains(buf.String(), "# update_helper: true") || a.UpdateHelper != nil {
		t.Fatalf("the template should document update_helper without setting it (read as %v)", a.UpdateHelper)
	}
}

// The key is documented, accepted, and read as a yes only when it is true; a
// misspelling is still refused by name, because a typo in an unattended
// install would otherwise leave the helper out and be found when an update
// button does nothing.
func TestTheAnswersFileAcceptsTheUpdateHelperKey(t *testing.T) {
	dir := t.TempDir()
	a, err := Load(writeFile(t, dir, "yes.yaml", "update_helper: true\n"))
	if err != nil || a.UpdateHelper == nil || !*a.UpdateHelper {
		t.Fatalf("update_helper: true loaded as %+v, %v", a, err)
	}
	a, err = Load(writeFile(t, dir, "no.yaml", "update_helper: false\n"))
	if err != nil || a.UpdateHelper == nil || *a.UpdateHelper {
		t.Fatalf("update_helper: false loaded as %+v, %v", a, err)
	}
	a, err = Load(writeFile(t, dir, "none.yaml", "mode: single\n"))
	if err != nil || a.UpdateHelper != nil {
		t.Fatalf("an answer file that does not mention it loaded as %+v, %v", a, err)
	}
	for _, typo := range []string{"update_helpr", "updates_helper", "update-helper", "helper"} {
		_, err := Load(writeFile(t, dir, typo+".yaml", typo+": true\n"))
		if err == nil || !strings.Contains(err.Error(), typo) {
			t.Errorf("%s: want a refusal naming the key, got %v", typo, err)
		}
	}
	if !strings.Contains(exampleAnswers, UpdateHelperExplained) {
		t.Error("the printed template documents update_helper without saying what the helper is for")
	}
	if !strings.Contains(exampleAnswers, "update_helper:") {
		t.Error("the printed template does not document update_helper")
	}
}

func keysOf(ms []MissingAnswer) []string {
	out := make([]string, 0, len(ms))
	for _, m := range ms {
		out = append(out, m.Key)
	}
	return out
}

func contains(list []string, want string) bool {
	for _, s := range list {
		if s == want {
			return true
		}
	}
	return false
}

package installer

import (
	"context"
	"fmt"
	"os"
	"regexp"
	"strconv"

	"github.com/eyupio/zoomies/internal/store"
)

// cgroupControllersPath exists only under a cgroup v2 unified hierarchy: a
// host still on cgroup v1, or split into the legacy hybrid layout, has no
// file by this name at the root. It is the same test util-linux's own
// `mount` output and systemd rely on, done directly rather than by shelling
// out to either.
const cgroupControllersPath = "/sys/fs/cgroup/cgroup.controllers"

// cgroupV2Unified reports whether this host mounts a cgroup v2 unified
// hierarchy, which is what a systemd user slice needs before it has
// anything to delegate. A var rather than a func, so a test can stand in
// for a cgroup v1 host without needing one.
var cgroupV2Unified = func() bool {
	_, err := os.Stat(cgroupControllersPath)
	return err == nil
}

// rootlessSocketUID pulls the uid out of a rootless socket endpoint, e.g.
// unix:///run/user/1000/podman/podman.sock. Delegating the cgroup
// controllers means editing that user's own systemd slice, and by the time
// setup gets here it is usually running as root itself -- install.sh
// re-execs it under sudo because it writes a unit and /etc/zoomies -- so the
// uid has to come from the socket the daemon actually answered on rather
// than from the installer's own.
var rootlessSocketUID = regexp.MustCompile(`/run/user/(\d+)/`)

func rootlessUID(endpoint string) (int, bool) {
	m := rootlessSocketUID.FindStringSubmatch(endpoint)
	if m == nil {
		return 0, false
	}
	uid, err := strconv.Atoi(m[1])
	if err != nil {
		return 0, false
	}
	return uid, true
}

// cgroupDelegateDropIn hands the user slice every controller a pool's
// resource limits can ask for, not just cpu: a pool that sets pids_limit or
// a memory limit is refused in exactly the same way otherwise.
const cgroupDelegateDropIn = "[Service]\nDelegate=cpu cpuset io memory pids\n"

// cgroupDelegateUnit is the drop-in's own file name, distinct from the
// override.conf `systemctl edit` would write, so an operator's own manual
// edit and this one do not clobber each other.
const cgroupDelegateUnit = "zoomies-delegate.conf"

// cgroupDropInPath is where the drop-in for one uid's user slice lives.
func cgroupDropInPath(uid int) string {
	return fmt.Sprintf("/etc/systemd/system/user@%d.service.d/%s", uid, cgroupDelegateUnit)
}

// writeCgroupDropIn is writeFileAtomic by default. It is a var so a test can
// check delegateCgroupControllers's command sequencing without root or a
// write into the real /etc/systemd/system this runs against outside a test.
var writeCgroupDropIn = writeFileAtomic

// delegateCgroupControllers gives a rootless daemon's user slice the
// controllers it needs to enforce a CPU quota, a memory limit and a pids
// limit: this is host.limits_unenforceable's fix, done once at setup rather
// than left for an operator to run by hand after the finding shows up.
//
// It needs root to write the drop-in -- user@<uid>.service is a system unit
// regardless of how unprivileged the daemon under it is -- and it restarts
// the daemon inside the target user's own session, because `systemctl
// --user` against anyone else's slice does nothing. run is taken as an
// argument, the same seam prepareDirs uses, so a test can watch what would
// have been run without a real systemd to run it against.
func delegateCgroupControllers(ctx context.Context, run commandRunner, uid int, userName string, kind store.BackendKind) error {
	dropInPath := cgroupDropInPath(uid)
	if err := writeCgroupDropIn(dropInPath, []byte(cgroupDelegateDropIn), 0o644); err != nil {
		return fmt.Errorf("installer: writing %s: %w", dropInPath, err)
	}
	if _, err := run(ctx, "systemctl", "daemon-reload"); err != nil {
		return err
	}
	runtimeDir := "XDG_RUNTIME_DIR=/run/user/" + strconv.Itoa(uid)
	if _, err := run(ctx, "runuser", "-u", userName, "--", "env", runtimeDir, "systemctl", "--user", "restart", string(kind)); err != nil {
		return fmt.Errorf("installer: wrote %s, but restarting %s in %s's session failed; log %s out and back in "+
			"(or reboot) to pick up the delegation: %w", dropInPath, kind, userName, userName, err)
	}
	return nil
}

// cgroupDelegator is delegateCgroupControllers by default. It is a var, the
// same seam PrepareOptions.newManager uses, so a test can check
// ensureCgroupDelegation's branching without a real systemd or write access
// to /etc.
var cgroupDelegator = delegateCgroupControllers

// ensureCgroupDelegation is the setup-time half of host.limits_unenforceable:
// where the controller can only report that a rootless daemon refuses a
// runner's CPU quota, setup can fix the common case itself, on the same
// host, before a pool ever asks for one.
//
// A daemon that has not said whether it can apply a limit (Known is false),
// or that already can, needs nothing done -- writing the drop-in a second
// time would be a needless restart of a daemon that already works.
func ensureCgroupDelegation(ctx context.Context, u *ui, det Detection, kind store.BackendKind, rootless bool, endpoint string, limits store.LimitSupport, run commandRunner) {
	if kind == store.BackendProcess || !rootless {
		return
	}
	if !limits.Known || (limits.CPU && limits.Memory && limits.Pids) {
		return
	}
	if det.OS != "linux" || !det.HasSystemd {
		return // the fix is a systemd drop-in; there is nothing to automate elsewhere
	}
	uid, ok := rootlessUID(endpoint)
	if !ok {
		return
	}
	if !det.Root {
		u.note(fmt.Sprintf("%s here cannot apply a CPU quota, a memory limit or a pids limit; delegating the cgroup "+
			"controllers needs root, so re-run setup with sudo to have it fixed automatically", kind))
		return
	}
	if !cgroupV2Unified() {
		u.warn(fmt.Sprintf("%s here cannot apply a CPU quota, a memory limit or a pids limit, and this host is still on cgroup v1", kind))
		u.note("cgroup v2 needs `systemd.unified_cgroup_hierarchy=1` on the kernel command line and a reboot; nothing here can do that for you")
		return
	}
	userName := currentUserName(uid)
	if err := cgroupDelegator(ctx, run, uid, userName, kind); err != nil {
		u.warn("could not delegate the cgroup controllers to " + userName + "'s user slice: " + err.Error())
		return
	}
	u.ok(fmt.Sprintf("delegated cpu, cpuset, io, memory and pids to %s's user slice, and restarted %s", userName, kind))
}

package installer

import (
	"bytes"
	"context"
	"os"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// A pool's CPU quota or memory limit is refused by exactly this daemon, so
// the uid it runs the socket under is what a fix has to target -- and it has
// to survive the usual shapes a rootless endpoint takes.
func TestRootlessUIDReadsTheUserRunDirectory(t *testing.T) {
	cases := []struct {
		endpoint string
		want     int
		ok       bool
	}{
		{"unix:///run/user/1000/podman/podman.sock", 1000, true},
		{"unix:///run/user/0/docker.sock", 0, true},
		{"unix:///var/run/docker.sock", 0, false},
		{"tcp://127.0.0.1:2375", 0, false},
		{"", 0, false},
	}
	for _, c := range cases {
		got, ok := rootlessUID(c.endpoint)
		if ok != c.ok || (ok && got != c.want) {
			t.Errorf("rootlessUID(%q) = (%d, %v), want (%d, %v)", c.endpoint, got, ok, c.want, c.ok)
		}
	}
}

// fullSupport and noSupport are the two ends of store.LimitSupport that mean
// "nothing to fix here": either the daemon already applies every limit, or it
// has never been asked and Known is false.
var (
	fullSupport = store.LimitSupport{Known: true, CPU: true, Memory: true, Pids: true}
	noSupport   = store.LimitSupport{}
)

func cgroupTestUI() (*ui, *bytes.Buffer) {
	var b bytes.Buffer
	return newUI(&b), &b
}

func rootlessSystemdDetection(root bool) Detection {
	return Detection{OS: "linux", HasSystemd: true, Root: root}
}

// Nothing here is worth writing a drop-in for: the process backend has no
// daemon, a root daemon's limits are a kernel fact rather than a delegation
// one, and a daemon that already enforces every limit -- or has never said
// whether it can -- needs setup to do nothing at all.
func TestEnsureCgroupDelegationSkipsWhenThereIsNothingToFix(t *testing.T) {
	cases := []struct {
		name     string
		kind     store.BackendKind
		rootless bool
		limits   store.LimitSupport
		det      Detection
	}{
		{"process backend", store.BackendProcess, true, store.LimitSupport{Known: true}, rootlessSystemdDetection(true)},
		{"root daemon", store.BackendPodman, false, store.LimitSupport{Known: true}, rootlessSystemdDetection(true)},
		{"limits not yet known", store.BackendPodman, true, noSupport, rootlessSystemdDetection(true)},
		{"limits already fully enforced", store.BackendPodman, true, fullSupport, rootlessSystemdDetection(true)},
		{"not linux", store.BackendPodman, true, store.LimitSupport{Known: true}, Detection{OS: "darwin", HasSystemd: false, Root: true}},
		{"no systemd", store.BackendPodman, true, store.LimitSupport{Known: true}, Detection{OS: "linux", HasSystemd: false, Root: true}},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			u, out := cgroupTestUI()
			r := &recordingRunner{}
			var called bool
			orig := cgroupDelegator
			cgroupDelegator = func(context.Context, commandRunner, int, string, store.BackendKind) error {
				called = true
				return nil
			}
			defer func() { cgroupDelegator = orig }()

			ensureCgroupDelegation(t.Context(), u, c.det, c.kind, c.rootless, "unix:///run/user/1000/podman/podman.sock", c.limits, r.run)

			if called {
				t.Error("the delegation step ran when there was nothing for it to fix")
			}
			if out.Len() != 0 {
				t.Errorf("nothing should be printed when there is nothing to fix, got %q", out.String())
			}
		})
	}
}

// An endpoint that does not name a uid -- a root socket, a TCP one -- gives
// setup nothing to delegate to, so it says nothing rather than guessing.
func TestEnsureCgroupDelegationSkipsAnEndpointWithNoUID(t *testing.T) {
	u, out := cgroupTestUI()
	ensureCgroupDelegation(t.Context(), u, rootlessSystemdDetection(true), store.BackendPodman, true,
		"unix:///var/run/podman.sock", store.LimitSupport{Known: true}, (&recordingRunner{}).run)
	if out.Len() != 0 {
		t.Errorf("an endpoint with no uid should print nothing, got %q", out.String())
	}
}

// A non-root installer cannot write a system unit's drop-in, and the
// operator is told exactly what would fix it -- re-run under sudo -- rather
// than being left to work out why nothing happened.
func TestEnsureCgroupDelegationWithoutRootAsksForSudo(t *testing.T) {
	u, out := cgroupTestUI()
	var called bool
	orig := cgroupDelegator
	cgroupDelegator = func(context.Context, commandRunner, int, string, store.BackendKind) error {
		called = true
		return nil
	}
	defer func() { cgroupDelegator = orig }()

	ensureCgroupDelegation(t.Context(), u, rootlessSystemdDetection(false), store.BackendPodman, true,
		"unix:///run/user/1000/podman/podman.sock", store.LimitSupport{Known: true}, (&recordingRunner{}).run)

	if called {
		t.Fatal("delegation ran without root")
	}
	if !strings.Contains(out.String(), "sudo") {
		t.Errorf("output = %q, want it to say to re-run with sudo", out.String())
	}
}

// A host still on cgroup v1 has nothing to delegate: the fix is a kernel
// command line and a reboot, and setup says so instead of writing a drop-in
// that would do nothing until then.
func TestEnsureCgroupDelegationOnCgroupV1WarnsInsteadOfWriting(t *testing.T) {
	origCgroup := cgroupV2Unified
	cgroupV2Unified = func() bool { return false }
	defer func() { cgroupV2Unified = origCgroup }()

	u, out := cgroupTestUI()
	var called bool
	orig := cgroupDelegator
	cgroupDelegator = func(context.Context, commandRunner, int, string, store.BackendKind) error {
		called = true
		return nil
	}
	defer func() { cgroupDelegator = orig }()

	ensureCgroupDelegation(t.Context(), u, rootlessSystemdDetection(true), store.BackendPodman, true,
		"unix:///run/user/1000/podman/podman.sock", store.LimitSupport{Known: true}, (&recordingRunner{}).run)

	if called {
		t.Fatal("delegation ran on a cgroup v1 host")
	}
	if !strings.Contains(out.String(), "cgroup v1") {
		t.Errorf("output = %q, want it to name cgroup v1 as the reason", out.String())
	}
	if !strings.Contains(out.String(), "unified_cgroup_hierarchy") {
		t.Errorf("output = %q, want the kernel command line fix", out.String())
	}
}

// The one case setup can actually fix on its own: root, systemd, cgroup v2,
// and a daemon that has said it cannot apply a limit. This is the path that
// writes the drop-in and restarts the daemon -- stood in for here so the
// test needs neither.
func TestEnsureCgroupDelegationFixesTheDaemonOnACgroupV2Host(t *testing.T) {
	origCgroup := cgroupV2Unified
	cgroupV2Unified = func() bool { return true }
	defer func() { cgroupV2Unified = origCgroup }()

	u, out := cgroupTestUI()
	var gotUID int
	var gotKind store.BackendKind
	orig := cgroupDelegator
	cgroupDelegator = func(_ context.Context, _ commandRunner, uid int, _ string, kind store.BackendKind) error {
		gotUID, gotKind = uid, kind
		return nil
	}
	defer func() { cgroupDelegator = orig }()

	ensureCgroupDelegation(t.Context(), u, rootlessSystemdDetection(true), store.BackendPodman, true,
		"unix:///run/user/1000/podman/podman.sock", store.LimitSupport{Known: true, CPU: false, Memory: true, Pids: true}, (&recordingRunner{}).run)

	if gotUID != 1000 {
		t.Errorf("delegated to uid %d, want 1000 (from the socket path)", gotUID)
	}
	if gotKind != store.BackendPodman {
		t.Errorf("delegated for backend %q, want podman", gotKind)
	}
	if !strings.Contains(out.String(), "delegated") {
		t.Errorf("output = %q, want it to say the controllers were delegated", out.String())
	}
}

// A restart that fails leaves the operator with the drop-in on disk but no
// confirmation it took effect, so the failure is a warning naming what broke
// rather than a silent success.
func TestEnsureCgroupDelegationReportsAFailedRestart(t *testing.T) {
	origCgroup := cgroupV2Unified
	cgroupV2Unified = func() bool { return true }
	defer func() { cgroupV2Unified = origCgroup }()

	u, out := cgroupTestUI()
	orig := cgroupDelegator
	cgroupDelegator = func(context.Context, commandRunner, int, string, store.BackendKind) error {
		return context.DeadlineExceeded
	}
	defer func() { cgroupDelegator = orig }()

	ensureCgroupDelegation(t.Context(), u, rootlessSystemdDetection(true), store.BackendPodman, true,
		"unix:///run/user/1000/podman/podman.sock", store.LimitSupport{Known: true}, (&recordingRunner{}).run)

	if !strings.Contains(out.String(), "could not delegate") {
		t.Errorf("output = %q, want it to say the delegation failed", out.String())
	}
}

// stubCgroupDropInWrite makes writeCgroupDropIn a no-op, so a test of
// delegateCgroupControllers needs neither root nor a real
// /etc/systemd/system to run against.
func stubCgroupDropInWrite(t *testing.T) {
	t.Helper()
	orig := writeCgroupDropIn
	writeCgroupDropIn = func(string, []byte, os.FileMode) error { return nil }
	t.Cleanup(func() { writeCgroupDropIn = orig })
}

// delegateCgroupControllers itself: the drop-in's path and content, and the
// commands it runs, in the order that matters -- the restart only means
// anything once the reload has picked up the new drop-in.
func TestDelegateCgroupControllersRunsDaemonReloadThenRestartsInTheUsersSession(t *testing.T) {
	stubCgroupDropInWrite(t)
	r := &recordingRunner{}
	if err := delegateCgroupControllers(t.Context(), r.run, 1000, "runner", store.BackendPodman); err != nil {
		t.Fatalf("delegateCgroupControllers: %v", err)
	}
	if !r.ran("systemctl", "daemon-reload") {
		t.Errorf("commands run = %v, want systemctl daemon-reload among them", r.lines())
	}
	if !r.ran("runuser", "-u", "runner", "--", "env", "XDG_RUNTIME_DIR=/run/user/1000", "systemctl", "--user", "restart", "podman") {
		t.Errorf("commands run = %v, want the restart run inside runner's own session", r.lines())
	}
}

// The drop-in itself: every controller a pool's limits can ask for, at the
// path user@<uid>.service.d looks for one.
func TestDelegateCgroupControllersWritesEveryController(t *testing.T) {
	var gotPath string
	var gotContent []byte
	orig := writeCgroupDropIn
	writeCgroupDropIn = func(p string, data []byte, _ os.FileMode) error {
		gotPath, gotContent = p, data
		return nil
	}
	t.Cleanup(func() { writeCgroupDropIn = orig })

	r := &recordingRunner{}
	if err := delegateCgroupControllers(t.Context(), r.run, 1000, "runner", store.BackendPodman); err != nil {
		t.Fatalf("delegateCgroupControllers: %v", err)
	}
	if want := "/etc/systemd/system/user@1000.service.d/zoomies-delegate.conf"; gotPath != want {
		t.Errorf("drop-in path = %q, want %q", gotPath, want)
	}
	for _, controller := range []string{"cpu", "cpuset", "io", "memory", "pids"} {
		if !strings.Contains(string(gotContent), controller) {
			t.Errorf("drop-in content = %q, missing controller %q", gotContent, controller)
		}
	}
}

// A daemon-reload that fails means the drop-in was never picked up, so the
// restart must not run against a slice that still has the old unit.
func TestDelegateCgroupControllersStopsIfDaemonReloadFails(t *testing.T) {
	stubCgroupDropInWrite(t)
	r := &recordingRunner{answer: func(args []string) (string, error) {
		if len(args) > 0 && args[0] == "daemon-reload" {
			return "", context.DeadlineExceeded
		}
		return "", nil
	}}
	if err := delegateCgroupControllers(t.Context(), r.run, 1000, "runner", store.BackendPodman); err == nil {
		t.Fatal("delegateCgroupControllers succeeded despite a failed daemon-reload")
	}
	if r.ran("runuser", "-u", "runner", "--", "env", "XDG_RUNTIME_DIR=/run/user/1000", "systemctl", "--user", "restart", "podman") {
		t.Error("the restart ran even though daemon-reload failed")
	}
}

package installer

import (
	"context"
	"strings"

	"github.com/eyupio/zoomies/internal/cliconfig"
	"github.com/eyupio/zoomies/internal/config"
)

// The `zoomies` command on the host that runs the controller has to be told
// where the controller is. Installed by hand it never was: `zoomies pools edit`
// answered "no controller URL" on the one machine where the answer is known to
// the installer, and an operator had to write a file nobody had told them
// existed -- in a directory that did not exist either.
//
// So an install writes it, and an upgrade offers to. What is written is the
// address and nothing else. A token is authority; the installer does not mint
// one on an operator's behalf, and says where to make one.

// connectionURL is where this host's own CLI should reach the controller; the
// rule is shared with the CLI's own fallback, in internal/cliconfig.
func connectionURL(external, bind string, tls config.TLSMode) string {
	return cliconfig.ConnectionURL(external, bind, tls)
}

// cliConfigChanges is the CLI's connection file, offered where this host runs
// the controller and has none naming one.
func (p *upgradePlan) cliConfigChanges(s deploymentSettings) []layoutChange {
	if p.record.Mode == ModeAgent {
		return nil
	}
	url := connectionURL(s.cfg.Server.ExternalURL, s.cfg.Server.Bind, s.cfg.Server.TLS.Mode)
	if url == "" {
		return nil
	}
	path := cliconfig.Path()
	if existing, err := cliconfig.Load(path); err != nil || strings.TrimSpace(existing.URL) != "" {
		// A file naming a controller is the operator's; one that does not parse
		// is not ours to rewrite.
		return nil
	}
	return []layoutChange{{
		what: "the CLI's connection file " + path + ", naming this controller at " + url + " (no token), so `zoomies` on this host knows where the controller is; every command still needs a token added to it",
		apply: func(context.Context) error {
			_, err := cliconfig.EnsureURL(path, url)
			return err
		},
	}}
}

// stepCLIConfig writes the same file at install, and says so. It is create-only
// and never fatal: a controller that is installed and running is not made a
// failure by a home directory it could not write to.
func (i *Installer) stepCLIConfig(external, bind string, tls config.TLSMode) {
	url := connectionURL(external, bind, tls)
	if url == "" {
		return
	}
	path := cliconfig.Path()
	outcome, err := cliconfig.EnsureURL(path, url)
	switch {
	case err != nil:
		i.ui.warn("could not write the CLI's connection file " + path + ": " + err.Error())
		i.ui.note("create it with: url: " + url)
	case outcome == cliconfig.Kept:
		// Already names a controller; saying nothing is the right amount.
	default:
		i.ui.ok("wrote " + path + " so `zoomies` on this host finds the controller at " + url)
		i.ui.note("it holds no token: create one in the UI under your account's API tokens and add it as `token:` to change anything from the CLI.")
	}
}

package installer

import (
	"net"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// newSocketAt makes a real unix socket a test can stat, since these checks read
// the filesystem rather than take a caller's word for the mode.
func newSocketAt(t *testing.T, mode os.FileMode) (path string, facts socketFacts) {
	t.Helper()
	path = filepath.Join(t.TempDir(), "docker.sock")
	l, err := net.Listen("unix", path)
	if err != nil {
		t.Skipf("unix sockets unavailable here: %v", err)
	}
	t.Cleanup(func() { _ = l.Close() })
	if err := os.Chmod(path, mode); err != nil {
		t.Fatal(err)
	}
	facts, ok := statSocket(path)
	if !ok {
		// Off unix a socket has no owning group, so none of the group handling
		// these checks are about applies here.
		t.Skip("this platform reports no owner for a socket")
	}
	return path, facts
}

// A plain container carries its group in its own run command, so the advice
// cannot be about the env file that only compose reads. Sending an operator to
// edit a file that nothing consults is worse than saying nothing.
func TestSocketAdviceForAPlainContainerNamesTheRunFlag(t *testing.T) {
	path, facts := newSocketAt(t, 0o660)
	if facts.gid == 0 {
		t.Skip("this socket belongs to group root, which is a different refusal")
	}

	i, out := newUnattendedInstaller(t, nil)
	i.checkContainerSocketAccess(Plan{
		Deployment: DeploymentDocker, Mode: ModeSingle, Backend: store.BackendDocker,
		DockerHost: "unix://" + path, DockerGID: facts.gid + 1, Embedded: true,
	})

	body := out.String()
	if !strings.Contains(body, "--group-add") {
		t.Errorf("a plain container must be told about --group-add:\n%s", body)
	}
	if strings.Contains(body, "DOCKER_GID=") {
		t.Errorf("a plain container was sent to the compose env file:\n%s", body)
	}
	// The wrong gid means no runner can be created at all, which is the fact
	// the operator needs -- a container that comes up healthy and queues
	// forever is the failure this exists to prevent.
	if !strings.Contains(body, "no runner could be created") {
		t.Errorf("the cost must be stated:\n%s", body)
	}
}

// A socket the container could not open is refused with advice that matches
// what is actually wrong with it: a group of root is never joined, and a mode
// with no group bits cannot be fixed by joining anything.
func TestSocketAdviceMatchesWhyItCannotBeOpened(t *testing.T) {
	path, facts := newSocketAt(t, 0o600)
	if facts.uid == ImageUID {
		t.Skip("this socket is already owned by the image's own account")
	}

	i, out := newUnattendedInstaller(t, nil)
	i.checkContainerSocketAccess(Plan{
		Deployment: DeploymentCompose, Mode: ModeAgent, Backend: store.BackendDocker,
		DockerHost: "unix://" + path, DockerGID: facts.gid,
	})

	body := out.String()
	switch judgeContainerSocket(facts, facts.gid) {
	case socketRootGroup:
		// Zoomies will not put a container in the root group, so the way out
		// is a group of the socket's own or a rootless daemon.
		if !strings.Contains(body, "group root") {
			t.Errorf("a root-owned socket must be named as one:\n%s", body)
		}
		if !strings.Contains(body, "groupadd docker") && !strings.Contains(body, "rootless") {
			t.Errorf("the way out must be offered:\n%s", body)
		}
	case socketNoGroupBits:
		if !strings.Contains(body, "grants nothing to its group") {
			t.Errorf("the mode must be explained:\n%s", body)
		}
		if !strings.Contains(body, "rootless") {
			t.Errorf("the way out must be offered:\n%s", body)
		}
	default:
		t.Skipf("a mode-0600 socket is usable by the image's account here: %s", body)
	}
}

// A host that runs no runners has no socket to reach, so checking one would be
// advice about a problem the operator does not have.
func TestSocketIsNotCheckedOnAHostThatRunsNoRunners(t *testing.T) {
	path, facts := newSocketAt(t, 0o600)

	i, out := newUnattendedInstaller(t, nil)
	for _, p := range []Plan{
		{Deployment: DeploymentCompose, Mode: ModeController, Backend: store.BackendDocker,
			DockerHost: "unix://" + path, DockerGID: facts.gid},
		// The bare-process backend needs no daemon at all.
		{Deployment: DeploymentCompose, Mode: ModeSingle, Embedded: true,
			Backend: store.BackendProcess, DockerHost: "unix://" + path},
		// A TCP endpoint has no path to stat.
		{Deployment: DeploymentCompose, Mode: ModeSingle, Embedded: true,
			Backend: store.BackendDocker, DockerHost: "tcp://docker.example.com:2376"},
	} {
		i.checkContainerSocketAccess(p)
	}
	if out.String() != "" {
		t.Fatalf("a host with no socket to reach was given socket advice:\n%s", out)
	}
}

// A rootless socket belongs to the operator's own user and the image runs as
// uid 65532, so the two do not meet. It is a warning rather than a refusal
// because it often works anyway, and the way out differs per deployment.
func TestRootlessSocketWarningNamesTheRightFix(t *testing.T) {
	compose := Plan{Rootless: true, Embedded: true, Mode: ModeSingle,
		Backend: store.BackendDocker, DockerHost: "unix:///run/user/1000/docker.sock",
		Deployment: DeploymentCompose, DeployDir: "/opt/zoomies"}

	i, out := newUnattendedInstaller(t, nil)
	i.warnAboutRootlessSocket(compose)
	body := out.String()
	if !strings.Contains(body, "uid 65532") {
		t.Errorf("the mismatch must be named:\n%s", body)
	}
	if !strings.Contains(body, `user: "$(id -u):$(id -g)"`) {
		t.Errorf("compose must be told the compose fix:\n%s", body)
	}
	if !strings.Contains(body, filepath.Join("/opt/zoomies", ComposeFileName)) {
		t.Errorf("the file to edit must be named:\n%s", body)
	}

	plain := compose
	plain.Deployment = DeploymentDocker
	i, out = newUnattendedInstaller(t, nil)
	i.warnAboutRootlessSocket(plain)
	if !strings.Contains(out.String(), "--user $(id -u):$(id -g)") {
		t.Errorf("a plain container must be told the run-command fix:\n%s", out)
	}

	// A root socket, or a host that runs no runners, has nothing to warn about.
	i, out = newUnattendedInstaller(t, nil)
	i.warnAboutRootlessSocket(Plan{Embedded: true, Backend: store.BackendDocker})
	i.warnAboutRootlessSocket(Plan{Rootless: true, Mode: ModeController, Backend: store.BackendDocker})
	i.warnAboutRootlessSocket(Plan{Rootless: true, Embedded: true, Backend: store.BackendProcess})
	if out.String() != "" {
		t.Fatalf("a deployment with no rootless socket was warned about one:\n%s", out)
	}
}

// A crash halfway through a write must never leave a half-written unit that
// systemd would then refuse to parse, so the write goes through a temporary
// file and a rename.
func TestWriteFileAtomicLeavesNoHalfWrittenFile(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "nested", "zoomies.service")

	if err := writeFileAtomic(path, []byte("[Unit]\n"), 0o644); err != nil {
		t.Fatalf("writeFileAtomic: %v", err)
	}
	body, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if string(body) != "[Unit]\n" {
		t.Fatalf("file = %q", body)
	}
	// Windows models only a read-only bit, so the mode is a POSIX fact.
	if runtime.GOOS != "windows" {
		info, err := os.Stat(path)
		if err != nil {
			t.Fatal(err)
		}
		if info.Mode().Perm() != 0o644 {
			t.Fatalf("mode = %v, want 0644", info.Mode().Perm())
		}
	}

	// Rewriting replaces it rather than appending, and leaves no temporary
	// file behind for the next run to trip over.
	if err := writeFileAtomic(path, []byte("[Unit]\nDescription=Zoomies\n"), 0o600); err != nil {
		t.Fatalf("writeFileAtomic again: %v", err)
	}
	body, err = os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if string(body) != "[Unit]\nDescription=Zoomies\n" {
		t.Fatalf("file = %q, want it replaced", body)
	}
	entries, err := os.ReadDir(filepath.Dir(path))
	if err != nil {
		t.Fatal(err)
	}
	for _, e := range entries {
		if strings.HasPrefix(e.Name(), ".") {
			t.Errorf("a temporary file was left behind: %s", e.Name())
		}
	}
}

