// controllerUpgrade is a Compose controller installed before this release,
// and fakes for the commands an upgrade of it runs.
type controllerUpgrade struct {
	opts    UpgradeOptions
	rec     DeploymentRecord
	out     bytes.Buffer
	calls   []string
	inputs  []string
	failOn  string
	failRun error
}

func newControllerUpgrade(t *testing.T) *controllerUpgrade {
	t.Helper()
	u := &controllerUpgrade{}
	opts, _ := upgradeFixture(t, DeploymentCompose)
	dir := opts.ConfigDir
	rec := DeploymentRecord{Deployment: DeploymentCompose, Directory: dir, EnvFile: filepath.Join(dir, ".env"),
		Image: "ghcr.io/eyupio/zoomies:v0.1", Mode: ModeSingle, Container: "zoomies", ComposeCommand: []string{"docker", "compose"}}
	if err := os.WriteFile(rec.EnvFile, []byte(oldControllerEnv), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(rec.ComposeFile(), []byte(oldControllerCompose), 0o640); err != nil {
		t.Fatal(err)
	}
	if _, err := WriteDeploymentRecord(dir, rec); err != nil {
		t.Fatal(err)
	}
	opts.Mode = ModeSingle
	opts.Image = "ghcr.io/eyupio/zoomies:v9.0"
	opts.AssumeYes = true
	opts.Out = &u.out
	envJSON, _ := json.Marshal(oldControllerContainerEnv)
	opts.run = func(_ context.Context, name string, args ...string) (string, error) {
		line := name + " " + strings.Join(args, " ")
		u.calls = append(u.calls, line)
		switch {
		case u.failOn != "" && strings.Contains(line, u.failOn):
			return "", errors.New("test refusal")
		case strings.Contains(line, "config --images"):
			return opts.Image, nil
		case strings.Contains(line, "{{json .Config.Env}}"):
			return string(envJSON), nil
		case name == "docker" && len(args) > 0 && args[0] == "inspect":
			return "true", nil
		}
		return "", nil
	}
	opts.runInput = func(_ context.Context, input, name string, args ...string) (string, error) {
		u.calls = append(u.calls, name+" "+strings.Join(args, " "))
		u.inputs = append(u.inputs, input)
		if u.failRun != nil {
			return "", u.failRun
		}
		return "server.bind is now 0.0.0.0:8080 (from ZOOMIES_BIND)", nil
	}
	u.opts, u.rec = opts, rec
	return u
}

func (u *controllerUpgrade) callIndex(part string) int {
	for i, c := range u.calls {
		if strings.Contains(c, part) {
			return i
		}
	}
	return -1
}

// The report behind this: the upgrade took a deployment's settings from its
// .env, when every setting lives in the database. A controller installed
// before that has them in its .env, where each one pins the settings page, so
// the upgrade stores them in the database -- with the controller stopped,
// through the new image -- and only then comments them out, so the
// controller comes back up on the same values from where they belong.
func TestAnUpgradeMovesAControllersSettingsIntoItsDatabase(t *testing.T) {
	u := newControllerUpgrade(t)
	if err := Upgrade(context.Background(), u.opts); err != nil {
		t.Fatalf("Upgrade: %v\n%s", err, u.out.String())
	}

	stop, run, up := u.callIndex(" stop "), u.callIndex("run --rm --no-deps -T zoomies config import-env"), u.callIndex(" up -d ")
	if stop < 0 || run < stop || up < run {
		t.Fatalf("want stop, then the import, then up; calls:\n%s", strings.Join(u.calls, "\n"))
	}
	if !strings.Contains(u.calls[run], "ZOOMIES_IMAGE="+u.opts.Image) {
		t.Errorf("the import did not run the new image: %s", u.calls[run])
	}
	if len(u.inputs) != 1 {
		t.Fatalf("inputs = %q", u.inputs)
	}
	in := u.inputs[0]
	for _, want := range []string{"ZOOMIES_EXTERNAL_URL=https://zoomies.example.com", "ZOOMIES_BIND=0.0.0.0:8080",
		"ZOOMIES_TLS_MODE=files", "ZOOMIES_TLS_CERT_FILE=/etc/zoomies/cert.pem"} {
		if !strings.Contains(in, want+"\n") {
			t.Errorf("the import was not given %s:\n%s", want, in)
		}
	}
	// The key opens the database; an empty value that is the default has
	// nothing to keep.
	for _, not := range []string{"ZOOMIES_ENCRYPTION_KEY", "ZOOMIES_DB_PATH", "ZOOMIES_TRUSTED_PROXIES", "PATH="} {
		if strings.Contains(in, not) {
			t.Errorf("the import was given %s:\n%s", not, in)
		}
	}

	env, _ := os.ReadFile(u.rec.EnvFile)
	vars, _ := ParseEnvFile(u.rec.EnvFile)
	for _, gone := range []string{"ZOOMIES_EXTERNAL_URL", "ZOOMIES_BIND", "ZOOMIES_TLS_MODE", "ZOOMIES_TLS_CERT_FILE", "ZOOMIES_TRUSTED_PROXIES"} {
		if _, ok := vars[gone]; ok {
			t.Errorf("%s is still set in .env:\n%s", gone, env)
		}
	}
	for _, kept := range []string{"ZOOMIES_ENCRYPTION_KEY", "ZOOMIES_DB_PATH", "DOCKER_GID"} {
		if _, ok := vars[kept]; !ok {
			t.Errorf("%s was taken out of .env, which the controller needs before its database opens", kept)
		}
	}
	if vars["ZOOMIES_IMAGE"] != u.opts.Image {
		t.Errorf("image = %q", vars["ZOOMIES_IMAGE"])
	}
	if !strings.Contains(string(env), "# ZOOMIES_BIND=0.0.0.0:8080") || !strings.Contains(string(env), "server.bind lives in the database now") ||
		!strings.Contains(string(env), "# keep this comment") {
		t.Errorf(".env does not say where the settings went, or lost its own comments:\n%s", env)
	}

	compose, _ := os.ReadFile(u.rec.ComposeFile())
	if strings.Contains(string(compose), "ZOOMIES_BIND") || strings.Contains(string(compose), "${ZOOMIES_TLS_CERT_FILE}") {
		t.Errorf("the Compose file still hands the container a moved setting:\n%s", compose)
	}
	for _, want := range []string{"ZOOMIES_ENCRYPTION_KEY", "/etc/zoomies/cert.pem:/etc/zoomies/cert.pem:ro", "${ZOOMIES_IMAGE}"} {
		if !strings.Contains(string(compose), want) {
			t.Errorf("the Compose file lost %s:\n%s", want, compose)
		}
	}
	if matches, _ := filepath.Glob(u.rec.ComposeFile() + ".bak.*"); len(matches) == 0 {
		t.Error("the Compose file as it was is not kept")
	}
	if !strings.Contains(u.out.String(), "ZOOMIES_BIND (server.bind) = 0.0.0.0:8080") || !strings.Contains(u.out.String(), "Moved 6 settings") {
		t.Errorf("the operator was not told what moved:\n%s", u.out.String())
	}
}

// A new image that cannot store them -- an older one pinned, a database it
// cannot open -- moves nothing: the files stay as they were, and the upgrade
// goes on, because the controller runs as it did.
func TestAnUpgradeThatCannotStoreTheSettingsLeavesThemWhereTheyAre(t *testing.T) {
	u := newControllerUpgrade(t)
	u.failRun = errors.New("unknown command \"import-env\"")
	composeBefore, _ := os.ReadFile(u.rec.ComposeFile())
	if err := Upgrade(context.Background(), u.opts); err != nil {
		t.Fatalf("Upgrade: %v", err)
	}
	vars, _ := ParseEnvFile(u.rec.EnvFile)
	if vars["ZOOMIES_BIND"] != "0.0.0.0:8080" {
		t.Errorf("ZOOMIES_BIND was taken out although nothing was stored")
	}
	if compose, _ := os.ReadFile(u.rec.ComposeFile()); !bytes.Equal(compose, composeBefore) {
		t.Errorf("the Compose file was edited although nothing was stored")
	}
	if u.callIndex(" up -d ") < 0 || !strings.Contains(u.out.String(), "Could not move the settings") {
		t.Errorf("the upgrade did not go on, or did not say why nothing moved:\n%s", u.out.String())
	}
}

// A recreate that fails rolls back to the old image, which may predate the
// settings it would now find only in the database: the files go back as they
// were before the move, not just before the image line.
func TestAFailedUpgradePutsTheSettingsBackInTheEnvironment(t *testing.T) {
	u := newControllerUpgrade(t)
	u.failOn = "--force-recreate --timeout 1200 zoomies"
	if err := Upgrade(context.Background(), u.opts); err == nil {
		t.Fatal("the upgrade reported success")
	}
	env, _ := os.ReadFile(u.rec.EnvFile)
	if string(env) != oldControllerEnv {
		t.Errorf(".env was not put back:\n%s", env)
	}
	if compose, _ := os.ReadFile(u.rec.ComposeFile()); string(compose) != oldControllerCompose {
		t.Errorf("the Compose file was not put back:\n%s", compose)
	}
}

// Nothing changes without the operator's say: unattended, the upgrade lists
// what it would move and the command that moves it.
func TestAnUnattendedUpgradeOnlySaysWhichSettingsItWouldMove(t *testing.T) {
	u := newControllerUpgrade(t)
	u.opts.AssumeYes = false
	if err := Upgrade(context.Background(), u.opts); err != nil {
		t.Fatalf("Upgrade: %v", err)
	}
	if len(u.inputs) != 0 || u.callIndex(" stop ") >= 0 {
		t.Errorf("settings were moved without approval: %v", u.calls)
	}
	if vars, _ := ParseEnvFile(u.rec.EnvFile); vars["ZOOMIES_BIND"] == "" {
		t.Error("ZOOMIES_BIND was commented out without approval")
	}
	if !strings.Contains(u.out.String(), "ZOOMIES_BIND (server.bind)") || !strings.Contains(u.out.String(), "zoomies upgrade --yes") {
		t.Errorf("the operator was not told what would move and how:\n%s", u.out.String())
	}
}

// An agent has no database to move anything to, so its environment is its
// configuration and the upgrade leaves it alone.
func TestAnAgentsEnvironmentIsNotOffered(t *testing.T) {
	opts, _ := upgradeFixture(t, DeploymentCompose)
	var out bytes.Buffer
	opts.Out = &out
	opts.AssumeYes = true
	opts.run = func(_ context.Context, name string, args ...string) (string, error) {
		line := name + " " + strings.Join(args, " ")
		if strings.Contains(line, "{{json .Config.Env}}") {
			return `["ZOOMIES_AGENT_CAPACITY=4","ZOOMIES_DOCKER_HOST=unix:///var/run/docker.sock"]`, nil
		}
		if strings.Contains(line, "config --images") {
			return opts.Image, nil
		}
		if name == "docker" && len(args) > 0 && args[0] == "inspect" {
			return "true", nil
		}
		return "", nil
	}
	opts.runInput = func(context.Context, string, string, ...string) (string, error) {
		t.Error("an agent's settings were imported into a database it does not have")
		return "", nil
	}
	if err := Upgrade(context.Background(), opts); err != nil {
		t.Fatal(err)
	}
	if strings.Contains(out.String(), "override its database") {
		t.Errorf("an agent was offered a move:\n%s", out.String())
	}
}

// A docker deployment's container carries its environment in its own
// configuration, which the replacement copies: commenting the file out would
// change nothing. So the import runs on the stopped controller's volumes, and
// the replacement is created without the variables.
func TestADockerUpgradeCreatesTheReplacementWithoutTheMovedVariables(t *testing.T) {
	var created map[string]json.RawMessage
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		path := r.URL.Path
		switch {
		case strings.HasSuffix(path, "/zoomies/json"):
			_ = json.NewEncoder(w).Encode(map[string]any{"Id": "old", "Name": "/zoomies",
				"Config":     map[string]any{"Image": "ghcr.io/eyupio/zoomies:v0.1", "Env": oldControllerContainerEnv},
				"HostConfig": map[string]any{"AutoRemove": false}, "State": map[string]any{"Running": true}})
		case strings.HasSuffix(path, "/zoomies-before-upgrade/json"):
			w.WriteHeader(404)
		case strings.HasSuffix(path, "/containers/create"):
			body, _ := io.ReadAll(r.Body)
			_ = json.Unmarshal(body, &created)
			w.WriteHeader(201)
			_, _ = w.Write([]byte(`{"Id":"new"}`))
		case strings.HasSuffix(path, "/new/json"):
			_, _ = w.Write([]byte(`{"Id":"new","State":{"Running":true}}`))
		default:
			w.WriteHeader(204)
		}
	}))
	defer server.Close()

	opts, _ := upgradeFixture(t, DeploymentDocker)
	dir := opts.ConfigDir
	rec := DeploymentRecord{Deployment: DeploymentDocker, Directory: dir, EnvFile: filepath.Join(dir, DockerEnvFileName),
		Image: "ghcr.io/eyupio/zoomies:v0.1", Mode: ModeSingle, Container: "zoomies"}
	if err := os.WriteFile(rec.EnvFile, []byte(oldControllerEnv), 0o600); err != nil {
		t.Fatal(err)
	}
	if _, err := WriteDeploymentRecord(dir, rec); err != nil {
		t.Fatal(err)
	}
	var out bytes.Buffer
	opts.Out, opts.Mode, opts.Image, opts.AssumeYes = &out, ModeSingle, "ghcr.io/eyupio/zoomies:v9.0", true
	opts.DockerHost = server.URL
	opts.run = func(context.Context, string, ...string) (string, error) { return "", nil }
	var importArgs string
	opts.runInput = func(_ context.Context, input, name string, args ...string) (string, error) {
		importArgs = name + " " + strings.Join(args, " ")
		if !strings.Contains(input, "ZOOMIES_BIND=0.0.0.0:8080") {
			t.Errorf("input = %q", input)
		}
		return "", nil
	}
	if err := Upgrade(context.Background(), opts); err != nil {
		t.Fatalf("Upgrade: %v\n%s", err, out.String())
	}
	for _, want := range []string{"--volumes-from old", "--network none", "--env-file " + rec.EnvFile, opts.Image + " config import-env"} {
		if !strings.Contains(importArgs, want) {
			t.Errorf("the import ran as %q, want %s", importArgs, want)
		}
	}
	var env []string
	_ = json.Unmarshal(created["Env"], &env)
	joined := strings.Join(env, "\n")
	if strings.Contains(joined, "ZOOMIES_BIND") || strings.Contains(joined, "ZOOMIES_TLS_MODE") ||
		!strings.Contains(joined, "ZOOMIES_ENCRYPTION_KEY=") || !strings.Contains(joined, "PATH=") {
		t.Errorf("the replacement's environment is wrong:\n%s", joined)
	}
	if vars, _ := ParseEnvFile(rec.EnvFile); vars["ZOOMIES_BIND"] != "" || vars["ZOOMIES_ENCRYPTION_KEY"] == "" {
		t.Errorf("%s was not commented out as the container was: %v", rec.EnvFile, vars)
	}
}

func TestCommentOutEnvKeepsNoCredentialInTheComment(t *testing.T) {
	secret, _ := config.SettingForEnv("ZOOMIES_OIDC_CLIENT_SECRET")
	bind, _ := config.SettingForEnv("ZOOMIES_BIND")
	body := "# already a comment: ZOOMIES_BIND=1.2.3.4:1\nexport ZOOMIES_BIND=0.0.0.0:8080\nZOOMIES_OIDC_CLIENT_SECRET=hunter2\nOTHER=x"
	got := string(commentOutEnv([]byte(body), []movedSetting{{env: "ZOOMIES_BIND", setting: bind}, {env: "ZOOMIES_OIDC_CLIENT_SECRET", setting: secret}},
		time.Date(2026, 9, 24, 0, 0, 0, 0, time.UTC)))
	if strings.Contains(got, "hunter2") {
		t.Errorf("the credential is still in the file:\n%s", got)
	}
	for _, want := range []string{"# already a comment: ZOOMIES_BIND=1.2.3.4:1\n", "# export ZOOMIES_BIND=0.0.0.0:8080\n",
		"on 2026-09-24: server.bind lives in the database now", "\nOTHER=x"} {
		if !strings.Contains(got, want) {
			t.Errorf("want %q in:\n%s", want, got)
		}
	}
	vars, _ := ParseEnv(strings.NewReader(got))
	if len(vars) != 1 || vars["OTHER"] != "x" {
		t.Errorf("vars after = %v", vars)
	}
}

// A Compose file can name a variable as a list item as well as a mapping,
// and anywhere else in the service; a literal $ in a value is Compose's to
// interpolate unless it is doubled.
func TestRemoveComposeEnvHandlesAListAndEscapesADollar(t *testing.T) {
	proxies, _ := config.SettingForEnv("ZOOMIES_TRUSTED_PROXIES")
	cert, _ := config.SettingForEnv("ZOOMIES_TLS_CERT_FILE")
	body := `services:
  zoomies:
    image: ${ZOOMIES_IMAGE}
    environment:
      - ZOOMIES_TRUSTED_PROXIES=10.0.0.0/8
      - ZOOMIES_ENCRYPTION_KEY=${ZOOMIES_ENCRYPTION_KEY}
    volumes:
      - "${ZOOMIES_TLS_CERT_FILE:?set it}:/cert.pem:ro"
`
	got, err := removeComposeEnv([]byte(body), []movedSetting{
		{env: "ZOOMIES_TRUSTED_PROXIES", setting: proxies, value: "10.0.0.0/8"},
		{env: "ZOOMIES_TLS_CERT_FILE", setting: cert, value: "/etc/$weird/cert.pem"},
	})
	if err != nil {
		t.Fatal(err)
	}
	s := string(got)
	if strings.Contains(s, "ZOOMIES_TRUSTED_PROXIES") || !strings.Contains(s, "ZOOMIES_ENCRYPTION_KEY=${ZOOMIES_ENCRYPTION_KEY}") {
		t.Errorf("environment list:\n%s", s)
	}
	if !strings.Contains(s, "/etc/$$weird/cert.pem:/cert.pem:ro") || !strings.Contains(s, "${ZOOMIES_IMAGE}") {
		t.Errorf("substitution:\n%s", s)
	}
	if _, err := removeComposeEnv([]byte("services:\n  other: {}\n"), nil); err == nil {
		t.Error("a Compose file with no zoomies service was edited")
	}
}

// A controller's Compose file hands its container no setting: each would pin
// the database, and the settings page would show it locked. An agent's does,
// because an agent has no database and its environment is its configuration.
func TestAControllersComposeFileHandsItNoSetting(t *testing.T) {
	controller, err := RenderComposeFile(ComposeFileSpec{Mode: ModeSingle, Publish: true, MountSocket: true, MountShared: true,
		TLSCertFile: "/etc/zoomies/cert.pem", TLSKeyFile: "/etc/zoomies/key.pem"})
	if err != nil {
		t.Fatal(err)
	}
	for _, m := range interpolation.FindAllStringSubmatch(controller, -1) {
		name := m[1] + m[2]
		if _, stored := config.SettingForEnv(name); stored {
			t.Errorf("the controller's Compose file reads %s, which would pin a setting over the database", name)
		}
	}
	if !strings.Contains(controller, "- /etc/zoomies/cert.pem:/etc/zoomies/cert.pem:ro") {
		t.Errorf("the certificate is not mounted by its own path:\n%s", controller)
	}

	agent, err := RenderComposeFile(ComposeFileSpec{Mode: ModeAgent, MountSocket: true, MountShared: true})
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{"ZOOMIES_AGENT_CAPACITY: ${ZOOMIES_AGENT_CAPACITY}", "ZOOMIES_DOCKER_HOST: ${ZOOMIES_DOCKER_HOST}", "ZOOMIES_LOG_LEVEL"} {
		if !strings.Contains(agent, want) {
			t.Errorf("an agent's Compose file lost %s:\n%s", want, agent)
		}
	}
}

package installer

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// stopWatcher lets a test look at the host at the moment the service is asked
// to stop, which is the only way to prove what happened before or after it.
type stopWatcher struct {
	fakeManager
	onStop func()
}

func (m *stopWatcher) Stop(ctx context.Context) error {
	if m.onStop != nil {
		m.onStop()
	}
	return m.fakeManager.Stop(ctx)
}

func existingInstall(t *testing.T) (Plan, string) {
	t.Helper()
	dir := t.TempDir()
	p := Plan{
		KeyFile:    filepath.Join(dir, "encryption.key"),
		DBPath:     filepath.Join(dir, "zoomies.db"),
		ConfigFile: filepath.Join(dir, "zoomies.yaml"),
		Service:    ServiceSystemd,
	}
	for _, path := range []string{p.KeyFile, p.DBPath, p.ConfigFile} {
		if err := os.WriteFile(path, []byte(filepath.Base(path)), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	return p, dir
}

func installerWith(mgr ServiceManager, existing ExistingInstall) *Installer {
	i := &Installer{ui: newUI(&strings.Builder{})}
	i.det.Existing = existing
	i.newManager = func(ServiceKind, string) (ServiceManager, error) { return mgr, nil }
	return i
}

// A controller that crashed, or was killed, leaves its write-ahead log next to
// the database. Left in place while a fresh database is created at the same
// path, SQLite would try to replay the old database's log into the new one.
func TestArchivingAnInstallMovesTheDatabaseSidecarsWithIt(t *testing.T) {
	p, dir := existingInstall(t)
	for _, suffix := range []string{"-wal", "-shm"} {
		if err := os.WriteFile(p.DBPath+suffix, []byte("stale"), 0o600); err != nil {
			t.Fatal(err)
		}
	}

	i := installerWith(&fakeManager{}, ExistingInstall{})
	if err := i.archiveExisting(p); err != nil {
		t.Fatalf("archiveExisting: %v", err)
	}

	for _, path := range []string{p.KeyFile, p.DBPath, p.ConfigFile, p.DBPath + "-wal", p.DBPath + "-shm"} {
		if exists(path) {
			t.Errorf("%s is still where the new install will write", path)
		}
	}
	// Each sidecar keeps the name of the database it belongs to, so opening the
	// archived database directly still finds its own log.
	moved, err := filepath.Glob(filepath.Join(dir, "zoomies.db.*.bak-wal"))
	if err != nil || len(moved) != 1 {
		t.Errorf("the write-ahead log should be archived beside its database, found %v (%v)", moved, err)
	}
	moved, _ = filepath.Glob(filepath.Join(dir, "zoomies.db.*.bak-shm"))
	if len(moved) != 1 {
		t.Errorf("the shared-memory file should be archived beside its database, found %v", moved)
	}
}

// Renaming a database a live controller has open leaves that controller
// writing into the archive while the installer builds a new one nobody serves.
// The service has to be stopped -- which also checkpoints its log -- while the
// files are still where it expects them, and nothing may move if it will not
// stop.
func TestStartingAgainStopsTheControllerBeforeMovingItsFiles(t *testing.T) {
	p, _ := existingInstall(t)
	p.StartOver = true

	var presentAtStop bool
	mgr := &stopWatcher{}
	mgr.onStop = func() { presentAtStop = exists(p.DBPath) && exists(p.KeyFile) && exists(p.ConfigFile) }
	i := installerWith(mgr, ExistingInstall{Unit: "/etc/systemd/system/zoomies.service", Database: p.DBPath})

	if err := i.startOver(context.Background(), p); err != nil {
		t.Fatalf("startOver: %v", err)
	}
	if !contains(mgr.calls, "stop") {
		t.Fatalf("the running controller was never stopped: %v", mgr.calls)
	}
	if !presentAtStop {
		t.Error("the files were moved before the controller stopped, while it still had the database open")
	}
	if exists(p.DBPath) || exists(p.KeyFile) || exists(p.ConfigFile) {
		t.Error("the old key, database and configuration should have been moved aside")
	}
}

func TestStartingAgainMovesNothingWhenTheControllerWillNotStop(t *testing.T) {
	p, _ := existingInstall(t)
	p.StartOver = true

	mgr := &failingStop{}
	i := installerWith(mgr, ExistingInstall{Unit: "/etc/systemd/system/zoomies.service"})

	err := i.startOver(context.Background(), p)
	if err == nil {
		t.Fatal("a controller that will not stop must stop the run")
	}
	if !strings.Contains(err.Error(), "systemctl stop") {
		t.Errorf("the error should say how to stop it by hand: %v", err)
	}
	if !exists(p.DBPath) || !exists(p.KeyFile) || !exists(p.ConfigFile) {
		t.Error("nothing may be renamed under a controller that is still running")
	}
}

type failingStop struct{ fakeManager }

func (m *failingStop) Stop(context.Context) error { return os.ErrPermission }

// `systemctl start` on a unit that is already active does nothing, so a
// reconfigure that only started the service left the old process serving the
// old bind, TLS and key while the summary said it was running.
func TestReconfiguringStopsTheRunningControllerSoTheStartIsAFreshOne(t *testing.T) {
	cases := []struct {
		name     string
		existing ExistingInstall
		service  ServiceKind
		stopped  bool
	}{
		{"a native install with a unit", ExistingInstall{Unit: "/etc/systemd/system/zoomies.service"}, ServiceSystemd, true},
		{"a first install has nothing to stop", ExistingInstall{}, ServiceSystemd, false},
		{"an install run by hand has no service to stop", ExistingInstall{ConfigFile: "/etc/zoomies/zoomies.yaml"}, ServiceNone, false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			mgr := &fakeManager{}
			i := installerWith(mgr, tc.existing)
			if err := i.stopRunningController(context.Background(), Plan{Service: tc.service}); err != nil {
				t.Fatalf("stopRunningController: %v", err)
			}
			if got := contains(mgr.calls, "stop"); got != tc.stopped {
				t.Errorf("stopped = %v, want %v (calls %v)", got, tc.stopped, mgr.calls)
			}
		})
	}
}

// The wiring is what the audit finding is about: a helper that stops the
// controller is no fix if the install never calls it, or calls it after the
// start.
func TestReconfiguringAnInstallReplacesTheRunningControllerBeforeStartingTheUnit(t *testing.T) {
	cases := []struct {
		name  string
		plan  Plan
		calls []string
	}{
		{"a reconfigure stops the old process, then starts a fresh one",
			Plan{Service: ServiceSystemd, StartService: true, EnableService: true},
			[]string{"stop", "install", "enable", "start"}},
		{"a service that is not to be started is not stopped either",
			Plan{Service: ServiceSystemd, StartService: false, EnableService: true},
			[]string{"install", "enable"}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			mgr := &fakeManager{}
			i := installerWith(mgr, ExistingInstall{Unit: "/etc/systemd/system/zoomies.service"})
			if _, err := i.restartService(context.Background(), tc.plan); err != nil {
				t.Fatalf("restartService: %v", err)
			}
			if got, want := strings.Join(mgr.calls, ","), strings.Join(tc.calls, ","); got != want {
				t.Errorf("service calls = %s, want %s", got, want)
			}
		})
	}
}

// A stop that fails must not abandon the install: the start may still work.
// It has to say what the old process may still be serving, though, or the
// summary's "running" is a lie about which settings are live.
func TestAControllerThatWillNotStopIsAWarningAndTheStartStillHappens(t *testing.T) {
	mgr := &failingStop{}
	i := installerWith(mgr, ExistingInstall{Unit: "/etc/systemd/system/zoomies.service"})
	var out strings.Builder
	i.ui = newUI(&out)

	if _, err := i.restartService(context.Background(), Plan{Service: ServiceSystemd, StartService: true}); err != nil {
		t.Fatalf("restartService: %v", err)
	}
	if !contains(mgr.calls, "start") {
		t.Errorf("the unit was never started after the failed stop: %v", mgr.calls)
	}
	if !strings.Contains(out.String(), "old process keeps serving the old settings") {
		t.Errorf("the operator was not warned that the old process may still be running:\n%s", out.String())
	}
}

func filesInPlace(p Plan) bool { return exists(p.DBPath) && exists(p.KeyFile) && exists(p.ConfigFile) }

// The review's text promises that stopping there leaves the host as it was.
// Choosing Start again records the intention on the plan, and nothing may act
// on it until the review has been confirmed.
func TestStoppingAtTheReviewAfterChoosingStartAgainLeavesTheHostAsItWas(t *testing.T) {
	p, _ := existingInstall(t)
	p.StartOver = true
	mgr := &fakeManager{}
	i := installerWith(mgr, ExistingInstall{Unit: "/etc/systemd/system/zoomies.service"})

	installed := false
	err := i.reviewAndCarryOut(context.Background(), p,
		func(context.Context, Plan) (bool, error) { return false, nil },
		func(context.Context, Plan) error { installed = true; return nil })
	if err != nil {
		t.Fatalf("reviewAndCarryOut: %v", err)
	}
	if installed {
		t.Error("the install ran although the operator stopped at the review")
	}
	if len(mgr.calls) != 0 {
		t.Errorf("the service was touched although the operator stopped at the review: %v", mgr.calls)
	}
	if !filesInPlace(p) {
		t.Error("the key, database or configuration was moved although the operator stopped at the review")
	}
}

// The order is the fix: review, then stop the controller while its files are
// still where it expects them, then archive, then install. Archiving after the
// install has begun would take the new database with it.
func TestStartingAgainStopsArchivesAndThenInstallsOnceTheReviewIsConfirmed(t *testing.T) {
	p, _ := existingInstall(t)
	p.StartOver = true
	p.StartService = true

	var events []string
	mgr := &stopWatcher{}
	mgr.onStop = func() { events = append(events, "stop (files in place: "+yesNo(filesInPlace(p))+")") }
	i := installerWith(mgr, ExistingInstall{Unit: "/etc/systemd/system/zoomies.service"})

	err := i.reviewAndCarryOut(context.Background(), p,
		func(context.Context, Plan) (bool, error) {
			events = append(events, "review (files in place: "+yesNo(filesInPlace(p))+")")
			return true, nil
		},
		func(ctx context.Context, p Plan) error {
			events = append(events, "install (files in place: "+yesNo(filesInPlace(p))+")")
			// The tail of a real install. It must not stop the controller a
			// second time: startOver already did.
			_, err := i.restartService(ctx, p)
			return err
		})
	if err != nil {
		t.Fatalf("reviewAndCarryOut: %v", err)
	}
	want := "review (files in place: yes),stop (files in place: yes),install (files in place: no)"
	if got := strings.Join(events, ","); got != want {
		t.Errorf("sequence = %s, want %s", got, want)
	}
	if got, want := strings.Join(mgr.calls, ","), "stop,install,start"; got != want {
		t.Errorf("service calls = %s, want %s (exactly one stop)", got, want)
	}
}

func TestAControllerThatWillNotStopEndsAStartAgainBeforeTheInstall(t *testing.T) {
	p, _ := existingInstall(t)
	p.StartOver = true
	i := installerWith(&failingStop{}, ExistingInstall{Unit: "/etc/systemd/system/zoomies.service"})

	installed := false
	err := i.reviewAndCarryOut(context.Background(), p,
		func(context.Context, Plan) (bool, error) { return true, nil },
		func(context.Context, Plan) error { installed = true; return nil })
	if err == nil {
		t.Fatal("a controller that will not stop must end the run")
	}
	if installed {
		t.Error("the install ran under a controller that is still serving the old database")
	}
	if !filesInPlace(p) {
		t.Error("nothing may be renamed under a controller that is still running")
	}
}

func TestAConfirmedRunThatIsNotAStartAgainArchivesNothing(t *testing.T) {
	p, _ := existingInstall(t)
	mgr := &fakeManager{}
	i := installerWith(mgr, ExistingInstall{Unit: "/etc/systemd/system/zoomies.service"})

	installed := false
	err := i.reviewAndCarryOut(context.Background(), p,
		func(context.Context, Plan) (bool, error) { return true, nil },
		func(context.Context, Plan) error { installed = true; return nil })
	if err != nil {
		t.Fatalf("reviewAndCarryOut: %v", err)
	}
	if !installed {
		t.Error("a confirmed review must go on to install")
	}
	if !filesInPlace(p) || len(mgr.calls) != 0 {
		t.Errorf("a reconfigure keeps the key and database and leaves the stop to the install (calls %v)", mgr.calls)
	}
}

func yesNo(b bool) string {
	if b {
		return "yes"
	}
	return "no"
}

package installer

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

const HostHealthUnit = "zoomies-host-health.service"
const HostHealthUnitPath = "/etc/systemd/system/" + HostHealthUnit
const HostHealthReport = SharedHostDir + "/host-health/report.json"

// RenderHostHealthService uses the native installed binary, so a container
// controller receives a real OS report without privileged container mounts.
func RenderHostHealthService(binary, work, dockerHost string) string {
	quote := func(s string) string { return strconv.Quote(strings.ReplaceAll(s, "%", "%%")) }
	args := quote(binary) + " doctor --watch --tier dedicated --report-file " + quote(HostHealthReport) + " --work-dir " + quote(work)
	if dockerHost != "" {
		args += " --docker-host " + quote(dockerHost)
	}
	return "[Unit]\nDescription=Zoomies read-only host health reports\nAfter=docker.service\n\n[Service]\nType=simple\nExecStart=" + args + "\nRestart=on-failure\nRestartSec=10s\nUser=root\nNoNewPrivileges=yes\nProtectSystem=strict\nProtectHome=read-only\nProtectKernelTunables=yes\nProtectKernelModules=yes\nProtectControlGroups=yes\nReadWritePaths=" + SharedHostDir + "/host-health\nUMask=0022\n\n[Install]\nWantedBy=multi-user.target\n"
}
func installHostHealth(ctx context.Context, binary, work, dockerHost string, run commandRunner) error {
	base, err := os.OpenRoot(SharedHostDir)
	if err != nil {
		return err
	}
	defer base.Close()
	if err = base.Mkdir("host-health", 0755); err != nil && !os.IsExist(err) {
		return err
	}
	info, err := base.Lstat("host-health")
	if err != nil {
		return err
	}
	if !info.IsDir() {
		return fmt.Errorf("host-health must be a real directory")
	}
	expected := info
	dir, err := base.OpenRoot("host-health")
	if err != nil {
		return err
	}
	defer dir.Close()
	info, err = dir.Stat(".")
	if err != nil {
		return err
	}
	if !os.SameFile(expected, info) {
		return fmt.Errorf("host-health directory changed while opening it")
	}
	uid, _, ok := fileOwner(info)
	if !ok || uid != 0 {
		return fmt.Errorf("host-health must be root-owned")
	}
	if err = dir.Chmod(".", 0755); err != nil {
		return err
	}
	body := RenderHostHealthService(binary, work, dockerHost)
	if old, err := os.ReadFile(HostHealthUnitPath); err == nil && string(old) != body {
		return fmt.Errorf("%s already exists with different contents; inspect it before replacing", HostHealthUnitPath)
	}
	if err := writeFileAtomic(HostHealthUnitPath, []byte(body), 0644); err != nil {
		return err
	}
	if _, err := run(ctx, "systemctl", "daemon-reload"); err != nil {
		return err
	}
	_, err = run(ctx, "systemctl", "enable", "--now", HostHealthUnit)
	return err
}
func (p *upgradePlan) hostHealthChanges(ctx context.Context, s deploymentSettings) []layoutChange {
	if p.opts.Doctor == nil || !p.record.Deployment.Containerised() || !s.runsRunners(p.record.Mode) {
		return nil
	}
	if _, err := os.Stat("/run/systemd/system"); err != nil {
		return nil
	}
	if _, err := os.Stat(HostHealthUnitPath); err == nil {
		return nil
	}
	work := s.cfg.Agent.WorkDir
	if mount, err := p.opts.run(ctx, "docker", "volume", "inspect", "--format", "{{.Mountpoint}}", p.record.Volume); err == nil && filepath.IsAbs(strings.TrimSpace(mount)) {
		work = filepath.Join(strings.TrimSpace(mount), "work")
	}
	return []layoutChange{{what: "install " + HostHealthUnitPath + " using the native binary for read-only OS checks; publish to " + HostHealthReport + " through the existing shared mount (no tuning)", apply: func(ctx context.Context) error {
		return installHostHealth(ctx, p.opts.BinaryPath, work, s.cfg.Agent.DockerHost, p.opts.run)
	}}}

}

