// A controller host that has no CLI file is offered one, named in the list of
// additions an upgrade asks approval for; one that already names a controller
// is not, and an agent-only host has no controller to name.
func TestAnUpgradeOffersTheCLIConnectionFileOnlyWhereItIsMissing(t *testing.T) {
	path := filepath.Join(t.TempDir(), "cli.yaml")
	t.Setenv("ZOOMIES_CLI_CONFIG", path)
	cfg := config.Default()
	cfg.Server.ExternalURL = "https://zoomies.example.com"
	s := deploymentSettings{cfg: cfg, read: true}
	p := &upgradePlan{record: DeploymentRecord{Mode: ModeController}}

	changes := p.cliConfigChanges(s)
	if len(changes) != 1 || !strings.Contains(changes[0].what, path) || !strings.Contains(changes[0].what, "https://zoomies.example.com") || changes[0].required {
		t.Fatalf("changes = %+v, want one optional addition naming the file and the controller", changes)
	}
	if _, err := os.Stat(path); !os.IsNotExist(err) {
		t.Fatal("offering the file wrote it")
	}
	if err := changes[0].apply(context.Background()); err != nil {
		t.Fatal(err)
	}
	if raw, _ := os.ReadFile(path); !strings.Contains(string(raw), "url: https://zoomies.example.com") {
		t.Errorf("approval must write the url: %s", raw)
	}
	if again := p.cliConfigChanges(s); len(again) != 0 {
		t.Errorf("a file that names a controller is not offered again: %+v", again)
	}

	p.record.Mode = ModeAgent
	_ = os.Remove(path)
	if got := p.cliConfigChanges(s); len(got) != 0 {
		t.Errorf("an agent host has no controller to name: %+v", got)
	}
}

package installer

import (
	"context"
	"fmt"
	"io"
	"strings"

	"github.com/eyupio/zoomies/internal/config"
)

// DeploymentAction is an operator lifecycle operation on the containerised
// deployment recorded by zoomies init.
type DeploymentAction string

const (
	DeploymentStart   DeploymentAction = "start"
	DeploymentStop    DeploymentAction = "stop"
	DeploymentRestart DeploymentAction = "restart"
	DeploymentDown    DeploymentAction = "down"
	DeploymentStatus  DeploymentAction = "status"
	DeploymentLogs    DeploymentAction = "logs"
	DeploymentUpdate  DeploymentAction = "update"
)

// DeploymentControlOptions targets the deployment record rather than guessing
// container names, Compose variants, or environment-file locations.
type DeploymentControlOptions struct {
	ConfigDir    string
	Action       DeploymentAction
	RemoveVolume bool
	Image        string
	DockerHost   string
	Runtime      string
	BinaryPath   string
	Out          io.Writer
	run          commandRunner
}

// ControlDeployment starts, stops, restarts, updates, inspects, or takes down
// the container deployment created by zoomies init.
func ControlDeployment(ctx context.Context, opts DeploymentControlOptions) error {
	if opts.Out == nil {
		opts.Out = io.Discard
	}
	if opts.run == nil {
		opts.run = runCommand
	}
	if opts.ConfigDir == "" {
		opts.ConfigDir = config.ConfigDir()
	}
	rec, ok := ReadDeploymentRecord(opts.ConfigDir)
	if !ok || !rec.Deployment.Containerised() {
		return fmt.Errorf("installer: no containerised Zoomies deployment was found in %s", DeploymentRecordPath(opts.ConfigDir))
	}
	if opts.Action == DeploymentUpdate {
		return Upgrade(ctx, UpgradeOptions{
			ConfigDir: opts.ConfigDir, BinaryPath: opts.BinaryPath, DockerHost: opts.DockerHost,
			Runtime: deploymentRuntime(rec, opts.Runtime), Image: opts.Image, Out: opts.Out, run: opts.run,
		})
	}

	name, args, err := deploymentActionCommand(rec, opts.Action, opts.RemoveVolume)
	if err != nil {
		return err
	}
	out, err := opts.run(ctx, name, args...)
	if err != nil {
		return fmt.Errorf("installer: %s deployment: %w", opts.Action, err)
	}
	if strings.TrimSpace(out) != "" {
		fmt.Fprintln(opts.Out, strings.TrimSpace(out))
	}
	fmt.Fprintf(opts.Out, "Zoomies deployment %s complete.\n", opts.Action)
	return nil
}

func deploymentRuntime(rec DeploymentRecord, override string) string {
	if override != "" {
		return override
	}
	if len(rec.ComposeCommand) > 0 && rec.ComposeCommand[0] == "podman" {
		return "podman"
	}
	return "docker"
}

func deploymentActionCommand(rec DeploymentRecord, action DeploymentAction, removeVolume bool) (string, []string, error) {
	if rec.Deployment == DeploymentCompose {
		var args []string
		switch action {
		case DeploymentStart:
			args = []string{"up", "-d"}
		case DeploymentStop:
			args = []string{"stop"}
		case DeploymentRestart:
			args = []string{"restart"}
		case DeploymentStatus:
			args = []string{"ps"}
		case DeploymentLogs:
			args = []string{"logs", "--tail", "100"}
		case DeploymentDown:
			args = []string{"down"}
			if removeVolume {
				args = append(args, "-v")
			}
		default:
			return "", nil, fmt.Errorf("installer: unknown deployment action %q", action)
		}
		name, command := ComposeArgs(rec.ComposeCommand, rec.ComposeFile(), args...)
		return name, command, nil
	}

	runtime := deploymentRuntime(rec, "")
	container := containerOr(rec)
	switch action {
	case DeploymentStart:
		return runtime, []string{"start", container}, nil
	case DeploymentStop:
		return runtime, []string{"stop", container}, nil
	case DeploymentRestart:
		return runtime, []string{"restart", container}, nil
	case DeploymentStatus:
		return runtime, []string{"inspect", "--format", "{{.Name}}  {{.State.Status}}  {{.Config.Image}}", container}, nil
	case DeploymentLogs:
		return runtime, []string{"logs", "--tail", "100", container}, nil
	case DeploymentDown:
		args := []string{"rm", "-f", container}
		if removeVolume {
			// Docker cannot remove a container and a named volume in one command;
			// the CLI executes the second safe, explicit operation below.
			return "", nil, fmt.Errorf("installer: --volumes with a docker deployment belongs to `zoomies uninstall --volumes`; down keeps the database")
		}
		return runtime, args, nil
	default:
		return "", nil, fmt.Errorf("installer: unknown deployment action %q", action)
	}
}

package installer

import (
	"bytes"
	"context"
	"reflect"
	"strings"
	"testing"
)

func TestDeploymentActionCommandsUseTheRecordedDeployment(t *testing.T) {
	compose := DeploymentRecord{
		Deployment: DeploymentCompose, Directory: "/srv/zoomies",
		ComposeCommand: []string{"docker", "compose"},
	}
	name, args, err := deploymentActionCommand(compose, DeploymentStart, false)
	if err != nil {
		t.Fatal(err)
	}
	if name != "docker" || !reflect.DeepEqual(args[len(args)-2:], []string{"up", "-d"}) {
		t.Fatalf("compose start = %s %v", name, args)
	}
	_, args, err = deploymentActionCommand(compose, DeploymentDown, true)
	if err != nil || !reflect.DeepEqual(args[len(args)-2:], []string{"down", "-v"}) {
		t.Fatalf("compose down --volumes = %v, %v", args, err)
	}

	docker := DeploymentRecord{Deployment: DeploymentDocker, Container: "my-zoomies"}
	name, args, err = deploymentActionCommand(docker, DeploymentRestart, false)
	if err != nil || name != "docker" || !reflect.DeepEqual(args, []string{"restart", "my-zoomies"}) {
		t.Fatalf("docker restart = %s %v, %v", name, args, err)
	}
	name, args, err = deploymentActionCommand(docker, DeploymentDown, false)
	if err != nil || name != "docker" || !reflect.DeepEqual(args, []string{"rm", "-f", "my-zoomies"}) {
		t.Fatalf("docker down = %s %v, %v", name, args, err)
	}
}

func TestControlDeploymentRunsAndReportsTheRequestedAction(t *testing.T) {
	dir := t.TempDir()
	if _, err := WriteDeploymentRecord(dir, DeploymentRecord{
		Deployment: DeploymentCompose, Directory: dir,
		ComposeCommand: []string{"docker", "compose"},
	}); err != nil {
		t.Fatal(err)
	}
	var called string
	var out bytes.Buffer
	err := ControlDeployment(context.Background(), DeploymentControlOptions{
		ConfigDir: dir, Action: DeploymentStatus, Out: &out,
		run: func(_ context.Context, name string, args ...string) (string, error) {
			called = name + " " + strings.Join(args, " ")
			return "zoomies running", nil
		},
	})
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(called, "ps") || !strings.Contains(out.String(), "zoomies running") || !strings.Contains(out.String(), "status complete") {
		t.Fatalf("called %q, output %q", called, out.String())
	}
}

func TestControlDeploymentRefusesAnUnrecordedHost(t *testing.T) {
	err := ControlDeployment(context.Background(), DeploymentControlOptions{
		ConfigDir: t.TempDir(), Action: DeploymentStop,
	})
	if err == nil || !strings.Contains(err.Error(), "no containerised") {
		t.Fatalf("error = %v", err)
	}
}

