	opts, bin := updateFixture(t, srv, "v1.3.0")
	opts.ReleaseKey = public
	res, err := SelfUpdate(context.Background(), opts)
	if err != nil || !res.Updated || res.Tag != "v1.4.0" {
		t.Fatalf("res=%+v err=%v", res, err)
