	defer cand.Discard()
	if b, _ := os.ReadFile(bin); string(b) != "old" {
		t.Fatalf("installed binary = %q", b)
	}
	if b, _ := os.ReadFile(cand.Path); string(b) != "new build" {
		t.Fatalf("candidate = %q", b)
	}
	if _, err := os.Stat(bin + PreviousSuffix); !os.IsNotExist(err) {
