package installer

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/updates"
	"github.com/eyupio/zoomies/internal/updates/channel"
)

// The repair is the root side of a stuck update helper. The service cannot
// reset a failed unit or rewrite one, and should not be able to, so when its
// agent finds the helper stopped it writes repair.json and the repair units
// start this. The request carries only the attempt it is for: the helper's state
// is looked at again here, as root, and what is done follows from what root
// finds. That is also why the order is fixed.
//
//  1. Units first: reset-failed, rewrite, start the path unit. A helper that
//     comes back reads a waiting request itself, so a request is never removed
//     from under one that is about to read it.
//  2. Only then a request or a lock that is provably abandoned: nothing running,
//     older than updates.OrphanAfter, no engine process.
//
// Nothing is touched while the helper's service or an engine is running.

const (
	repairLedgerFile = "repair-state.json"
	// repairSettle is how long the repair waits after starting the path unit for
	// the helper to take a waiting request, and repairPoll how often it looks.
	repairSettle = 6 * time.Second
	repairPoll   = 500 * time.Millisecond
)

// RepairOptions is what a repair needs. The helper's own options carry the
// folder, the lock and the binary, all read from root's pointer.
type RepairOptions struct {
	HelperOptions
	unitDir string
	run     commandRunner
	procs   func() [][]string
	settle  time.Duration
	sleep   func(time.Duration)
}

func (o RepairOptions) withDefaults() RepairOptions {
	if o.Now == nil {
		o.Now = time.Now
	}
	if o.Out == nil {
		o.Out = io.Discard
	}
	if o.ownerOf == nil {
		o.ownerOf = fileUID
	}
	if o.unitDir == "" {
		o.unitDir = systemdUnitDir
	}
	if o.run == nil {
		o.run = runCommand
	}
	if o.procs == nil {
		o.procs = channel.Processes
	}
	if o.settle == 0 {
		o.settle = repairSettle
	}
	if o.sleep == nil {
		o.sleep = time.Sleep
	}
	return o
}

func (o RepairOptions) logf(format string, args ...any) {
	fmt.Fprintf(o.Out, format+"\n", args...)
}

// RunUpdateRepair answers the repair request in the update folder. An error
// means it could not answer at all; every other outcome, a refusal included, is
// in repair-result.json.
func RunUpdateRepair(ctx context.Context, opts RepairOptions) error {
	o := opts.withDefaults()
	dir, err := openUpdateFolder(o.Dir, o.ServiceUID, o.ownerOf)
	if err != nil {
		return err
	}
	defer dir.Close()

	req, err := takeRepairRequest(dir, o.ServiceUID, o.ownerOf)
	if errors.Is(err, fs.ErrNotExist) {
		o.logf("there is no repair request in %s, so there is nothing to answer", o.Dir)
		return nil
	}
	started := o.Now()
	if err != nil {
		// No id to echo; the answer still says why, for whoever looks.
		o.logf("the repair request cannot be used: %v", err)
		return writeRepairResult(dir, updates.RepairResult{ID: "refused", Error: "the repair request cannot be used, and was removed; see the helper's log (journalctl -u " + UpdateRepairServiceUnit + ")", FinishedAt: started})
	}
	o.logf("repair %s asked for at %s", req.ID, req.RequestedAt.UTC().Format(time.RFC3339))

	res := updates.RepairResult{ID: req.ID}
	finish := func(r updates.RepairResult) error {
		r.ID, r.FinishedAt = req.ID, o.Now()
		o.logf("repair %s: healed=%v verdict=%s actions=%s %s", req.ID, r.Healed, r.Verdict, strings.Join(r.Actions, ","), r.Error)
		return writeRepairResult(dir, r)
	}

	ledger, err := loadRepairLedger(o.StateDir)
	if err != nil {
		o.logf("%v", err)
		res.Error = "the helper's repair record cannot be used, so no repair was made; the reason is in the log (journalctl -u " + UpdateRepairServiceUnit + ")"
		return finish(res)
	}
	diag, err := o.diagnose(ctx, dir)
	if err != nil {
		res.Error = "root could not look at the helper: " + err.Error()
		return finish(res)
	}
	verdict := updates.Classify(diag, updates.OrphanAfter)
	res.Verdict = verdict.Kind
	switch {
	case verdict.Kind == updates.StuckBusy:
		// A live helper may still be reading its request and a live engine owns
		// the lock. Nothing is touched, and nothing counts against the budget.
		res.Actions = []string{updates.ActionRefusedBusy}
		res.Error = "the helper is running an update now, so nothing was changed"
		return finish(res)
	case !verdict.Repair:
		res.Healed = true
		return finish(res)
	}
	if ok, next := ledger.Admit(o.Now()); !ok {
		res.Actions = []string{updates.ActionRefusedRateLimit}
		res.Error = "root has repaired this helper too recently or too often, so it did not try again; the next repair may start at " + next.UTC().Format(time.RFC3339)
		return finish(res)
	}
	// Saved before anything is changed, so a repair is counted however it ends.
	if err := ledger.save(o.StateDir); err != nil {
		o.logf("%v", err)
		res.Error = "the helper's repair record cannot be written, so no repair was made; the reason is in the log (journalctl -u " + UpdateRepairServiceUnit + ")"
		return finish(res)
	}

	actions, err := o.putUnitsRight(ctx)
	res.Actions = actions
	if err != nil {
		o.logf("%v", err)
		res.Error = "the helper's units could not be put right: " + err.Error()
		return finish(res)
	}

	// Give a helper that is back a moment to take what is waiting.
	for waited := time.Duration(0); waited < o.settle; waited += repairPoll {
		d, err := o.diagnose(ctx, dir)
		if err != nil || d.ServiceBusy() || !d.RequestPresent {
			break
		}
		o.sleep(repairPoll)
	}
	after, err := o.diagnose(ctx, dir)
	if err != nil {
		res.Error = "root could not look at the helper after repairing its units: " + err.Error()
		return finish(res)
	}
	if after.ServiceBusy() {
		// The helper started on the request it found. It is not ours to touch.
		res.Healed = true
		return finish(res)
	}
	removeRequest, removeLock := after.Orphaned()
	if removeRequest && o.stillIdle(ctx) {
		if err := dir.Remove(channel.RequestFile); err == nil {
			res.Actions = append(res.Actions, updates.ActionRemovedRequest)
		} else if !errors.Is(err, fs.ErrNotExist) {
			o.logf("cannot remove the abandoned request: %v", err)
		}
	}
	if removeLock && o.stillIdle(ctx) {
		if info, err := os.Lstat(o.LockPath); err == nil && info.Mode().IsRegular() {
			if err := os.Remove(o.LockPath); err == nil {
				res.Actions = append(res.Actions, updates.ActionRemovedLock)
			} else {
				o.logf("cannot remove the abandoned lock %s: %v", o.LockPath, err)
			}
		}
	}
	final, err := o.diagnose(ctx, dir)
	res.Healed = err == nil && final.PathWaiting() && (!final.RequestPresent || final.ServiceBusy())
	if !res.Healed && res.Error == "" {
		res.Error = "the helper's units were put right, but something is still in the way; run \"sudo zoomies updates helper status\" on this host"
	}
	return finish(res)
}

// diagnose is the same look the agent takes, taken again by root.
func (o RepairOptions) diagnose(ctx context.Context, dir *os.Root) (updates.Diagnosis, error) {
	_ = dir
	lockDir := ""
	if o.LockPath != "" {
		lockDir = filepath.Dir(o.LockPath)
	}
	return channel.Diagnose(ctx, channel.RunFunc(o.run), o.Dir, lockDir, o.Now(), o.procs)
}

// stillIdle is the last look before a file is removed: a helper that started
// since the last diagnosis is reading it.
func (o RepairOptions) stillIdle(ctx context.Context) bool {
	service := channel.QueryUnit(ctx, channel.RunFunc(o.run), UpdateServiceUnit)
	return !updates.Diagnosis{Service: service, EngineRunning: updates.EngineRunning(o.procs())}.ServiceBusy()
}

// putUnitsRight is the units half of "zoomies updates helper install": clear a
// failed state, write the units root rendered from its own pointer, and start
// the path unit. It reports what it did in fixed words.
func (o RepairOptions) putUnitsRight(ctx context.Context) ([]string, error) {
	var actions []string
	if _, err := o.run(ctx, "systemctl", "reset-failed", UpdateServiceUnit, UpdatePathUnit); err == nil {
		actions = append(actions, updates.ActionResetFailed)
	}
	pathUnit, serviceUnit := RenderUpdateUnits(o.BinaryPath, o.Dir)
	repairPath, repairService := RenderRepairUnits(o.BinaryPath, o.Dir)
	rewrote := false
	for _, u := range [][2]string{{UpdatePathUnit, pathUnit}, {UpdateServiceUnit, serviceUnit},
		{UpdateRepairPathUnit, repairPath}, {UpdateRepairServiceUnit, repairService}} {
		path := filepath.Join(o.unitDir, u[0])
		if old, err := os.ReadFile(path); err == nil && string(old) == u[1] {
			continue
		}
		if err := writeFileAtomic(path, []byte(u[1]), 0o644); err != nil {
			return actions, fmt.Errorf("cannot write %s: %w", path, err)
		}
		rewrote = true
	}
	if rewrote {
		actions = append(actions, updates.ActionRewroteUnits)
		if _, err := o.run(ctx, "systemctl", "daemon-reload"); err != nil {
			return actions, err
		}
		_, _ = o.run(ctx, "systemctl", "reset-failed", UpdateServiceUnit, UpdatePathUnit)
	}
	if _, err := o.run(ctx, "systemctl", "enable", "--now", UpdatePathUnit); err != nil {
		return actions, err
	}
	return append(actions, updates.ActionStartedPath), nil
}

// takeRepairRequest reads repair.json through the folder's handle and removes
// it before anything is done about it, so that a repair that goes wrong is not
// started again by the file it was started by.
func takeRepairRequest(dir *os.Root, wantUID int, ownerOf func(os.FileInfo) (int, bool)) (updates.RepairRequest, error) {
	f, info, err := openPlainFile(dir, updates.RepairFile)
	if err != nil {
		return updates.RepairRequest{}, err
	}
	defer f.Close()
	defer dir.Remove(updates.RepairFile)
	if uid, ok := ownerOf(info); !ok || uid != wantUID {
		return updates.RepairRequest{}, fmt.Errorf("it is not owned by the account the helper was installed for (uid %d)", wantUID)
	}
	body, err := io.ReadAll(io.LimitReader(f, updates.MaxRepairBytes+1))
	if err != nil {
		return updates.RepairRequest{}, err
	}
	if len(body) > updates.MaxRepairBytes {
		return updates.RepairRequest{}, fmt.Errorf("it is over the limit of %d bytes", updates.MaxRepairBytes)
	}
	return updates.ParseRepairRequest(body)
}

func writeRepairResult(dir *os.Root, r updates.RepairResult) error {
	r.V = updates.WireVersion
	r.ID = headOf(printable(r.ID, false), maxResultFieldBytes)
	r.Error = headOf(printable(r.Error, false), maxResultErrorBytes)
	r.Verdict = headOf(printable(r.Verdict, false), maxResultFieldBytes)
	body, err := json.Marshal(r)
	if err != nil {
		return fmt.Errorf("cannot encode the repair result: %w", err)
	}
	return replaceFile(dir, updates.RepairResultFile, body, 0o644)
}

type repairLedger struct{ updates.RepairLedger }

// loadRepairLedger reads root's record of past repairs. Absent is a fresh
// start; a record that cannot be trusted is an error and not a fresh start,
// because treating it as one would reset the limit.
func loadRepairLedger(stateDir string) (*repairLedger, error) {
	root, err := openStateDir(stateDir)
	if err != nil {
		return nil, err
	}
	defer root.Close()
	l := &repairLedger{}
	if _, err := root.Lstat(repairLedgerFile); errors.Is(err, fs.ErrNotExist) {
		return l, nil
	}
	path := filepath.Join(stateDir, repairLedgerFile)
	f, info, err := openPlainFile(root, repairLedgerFile)
	if err != nil {
		return nil, fmt.Errorf("the update helper's repair record %s cannot be used: %w", path, err)
	}
	defer f.Close()
	if err := checkStateOwner(path, info); err != nil {
		return nil, err
	}
	body, err := io.ReadAll(io.LimitReader(f, maxHelperStateBytes+1))
	if err == nil && len(body) > maxHelperStateBytes {
		err = errors.New("it is over the size limit")
	}
	if err == nil {
		dec := json.NewDecoder(bytes.NewReader(body))
		dec.DisallowUnknownFields()
		err = dec.Decode(&l.RepairLedger)
	}
	if err != nil {
		return nil, fmt.Errorf("the update helper's repair record %s cannot be read: %v; inspect it, and remove it only if you mean to reset the limit", path, err)
	}
	return l, nil
}

func (l *repairLedger) save(stateDir string) error {
	root, err := openStateDir(stateDir)
	if err != nil {
		return err
	}
	defer root.Close()
	body, err := json.Marshal(l.RepairLedger)
	if err != nil {
		return err
	}
	return replaceFile(root, repairLedgerFile, body, 0o600)
}

//go:build unix

package installer

import (
	"context"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/updates"
	"github.com/eyupio/zoomies/internal/updates/channel"
)

// fakeSystemd stands in for systemctl: it answers the three questions the
// repair asks from fields a test sets, and does what reset-failed and enable
// --now would do to them. Every call is recorded, with whether request.json was
// still in the folder when it was made, which is how the tests hold the order.
type fakeSystemd struct {
	pathActive, pathEnabled   string
	pathFailed, serviceFailed bool
	serviceActive             string
	// onEnable runs when the path unit is started, for a helper that comes back
	// and takes the request it finds.
	onEnable func()
	calls    []string
	// requestAt is the folder's request, so a call can say whether it was there.
	requestAt     string
	requestAtCall map[string]bool
}

func (f *fakeSystemd) run(_ context.Context, name string, args ...string) (string, error) {
	line := name + " " + strings.Join(args, " ")
	f.calls = append(f.calls, line)
	if f.requestAtCall == nil {
		f.requestAtCall = map[string]bool{}
	}
	_, err := os.Lstat(f.requestAt)
	f.requestAtCall[line] = err == nil
	unit := ""
	if len(args) > 0 {
		unit = args[len(args)-1]
	}
	switch args[0] {
	case "is-active":
		if unit == UpdatePathUnit {
			return f.pathActive, nil
		}
		if unit == UpdateServiceUnit {
			return f.serviceActive, nil
		}
		return "inactive", nil
	case "is-enabled":
		if unit == UpdatePathUnit {
			return f.pathEnabled, nil
		}
		return "static", nil
	case "is-failed":
		if (unit == UpdatePathUnit && f.pathFailed) || (unit == UpdateServiceUnit && f.serviceFailed) {
			return "failed", nil
		}
		return "active", nil
	case "reset-failed":
		f.pathFailed, f.serviceFailed = false, false
	case "enable":
		f.pathActive, f.pathEnabled, f.pathFailed = "active", "enabled", false
		if f.onEnable != nil {
			f.onEnable()
		}
	}
	return "", nil
}

func (f *fakeSystemd) changed() bool {
	return slices.ContainsFunc(f.calls, func(c string) bool {
		return strings.Contains(c, "reset-failed") || strings.Contains(c, " enable ") || strings.Contains(c, "daemon-reload")
	})
}

type repairHost struct {
	*helperHost
	sysd     *fakeSystemd
	unitDir  string
	lockPath string
	engines  [][]string
	now      time.Time
}

// newRepairHost is the host from the report: the path unit disabled and dead, a
// request three days old in the folder, and a lock beside the configuration.
func newRepairHost(t *testing.T) *repairHost {
	t.Helper()
	h := newHelperHost(t, "1.3.4")
	r := &repairHost{helperHost: h, unitDir: filepath.Join(filepath.Dir(h.dir), "units"), lockPath: h.opts.LockPath, now: t0}
	if err := os.Mkdir(r.unitDir, 0o755); err != nil {
		t.Fatal(err)
	}
	r.sysd = &fakeSystemd{
		pathActive: "inactive", pathEnabled: "disabled", pathFailed: true,
		serviceActive: "inactive", requestAt: filepath.Join(h.dir, channel.RequestFile),
	}
	return r
}

func (r *repairHost) age(t *testing.T, path string, age time.Duration) {
	t.Helper()
	at := r.now.Add(-age)
	if err := os.Chtimes(path, at, at); err != nil {
		t.Fatal(err)
	}
}

// staleRequest plants request.json and the lock, both aged.
func (r *repairHost) staleRequest(t *testing.T, requestAge, lockAge time.Duration) {
	t.Helper()
	r.ask(t, `{"v":1,"id":"upd_old","tag":"v1.3.5","requested_by":"someone","requested_at":"2026-10-05T09:00:00Z"}`)
	r.age(t, r.sysd.requestAt, requestAge)
	if lockAge > 0 {
		plant(t, r.lockPath, "locked")
		r.age(t, r.lockPath, lockAge)
	}
}

func (r *repairHost) askForRepair(t *testing.T, id string) {
	t.Helper()
	plant(t, filepath.Join(r.dir, updates.RepairFile), `{"v":1,"id":"`+id+`","requested_at":"2026-10-08T09:00:00Z"}`)
}

// repair runs the repair once and returns its answer.
func (r *repairHost) repair(t *testing.T, id string) updates.RepairResult {
	t.Helper()
	r.askForRepair(t, id)
	opts := RepairOptions{HelperOptions: r.opts, unitDir: r.unitDir, run: r.sysd.run,
		procs: func() [][]string { return r.engines }, settle: time.Millisecond, sleep: func(time.Duration) {}}
	opts.Now = func() time.Time { return r.now }
	if err := RunUpdateRepair(context.Background(), opts); err != nil {
		t.Fatalf("RunUpdateRepair: %v\nlog:\n%s", err, r.log)
	}
	if _, err := os.Lstat(filepath.Join(r.dir, updates.RepairFile)); err == nil {
		t.Error("the repair request was left in the folder, and would start the repair again")
	}
	res, found, err := channel.ReadRepairResult(r.dir)
	if err != nil || !found {
		t.Fatalf("no repair result the service can read: found %v, err %v\nlog:\n%s", found, err, r.log)
	}
	return res
}

func exists_(path string) bool { _, err := os.Lstat(path); return err == nil }

// The report: path unit disabled and dead, a request three days old. The units
// are put right first, and only then is what is provably abandoned removed.
func TestARepairRestartsADisabledPathUnitBeforeItClearsAnAbandonedRequest(t *testing.T) {
	r := newRepairHost(t)
	r.staleRequest(t, 72*time.Hour, 70*time.Hour)

	res := r.repair(t, "upd_new")

	want := []string{updates.ActionResetFailed, updates.ActionRewroteUnits, updates.ActionStartedPath,
		updates.ActionRemovedRequest, updates.ActionRemovedLock}
	if !slices.Equal(res.Actions, want) || !res.Healed || res.ID != "upd_new" || res.Verdict != updates.StuckPathDown {
		t.Errorf("result = %+v, want healed with actions %v", res, want)
	}
	if exists_(r.sysd.requestAt) || exists_(r.lockPath) {
		t.Error("the abandoned request and lock were left behind")
	}
	if !r.sysd.ran("systemctl enable --now " + UpdatePathUnit) {
		t.Errorf("the path unit was not started; calls: %v", r.sysd.calls)
	}
	// The order is the point: a request is never removed from under a helper that
	// has not been given the chance to read it.
	if !r.sysd.requestAtCall["systemctl enable --now "+UpdatePathUnit] {
		t.Error("the request was already gone when the path unit was started, so the helper had no chance to read it")
	}
	for _, unit := range []string{UpdatePathUnit, UpdateServiceUnit, UpdateRepairPathUnit, UpdateRepairServiceUnit} {
		if !exists_(filepath.Join(r.unitDir, unit)) {
			t.Errorf("%s was not rewritten", unit)
		}
	}
}

func (f *fakeSystemd) ran(line string) bool { return slices.Contains(f.calls, line) }

// A helper that is running an update may be reading the request, and the engine
// owns the lock. Whatever else is wrong, none of it is touched, and nothing is
// even asked of systemd that would change a unit.
func TestARepairNeverTouchesAHelperThatIsMidUpgrade(t *testing.T) {
	for name, mid := range map[string]func(*repairHost){
		"the service is running":  func(r *repairHost) { r.sysd.serviceActive = "active" },
		"the service is starting": func(r *repairHost) { r.sysd.serviceActive = "activating" },
		"an engine process is live": func(r *repairHost) {
			r.engines = [][]string{{"/usr/local/bin/zoomies", "upgrade", "--version", "v1.3.5", "--non-interactive"}}
		},
	} {
		t.Run(name, func(t *testing.T) {
			r := newRepairHost(t)
			r.staleRequest(t, 72*time.Hour, 70*time.Hour)
			mid(r)

			res := r.repair(t, "upd_new")

			if res.Healed || res.Verdict != updates.StuckBusy || !slices.Equal(res.Actions, []string{updates.ActionRefusedBusy}) {
				t.Errorf("result = %+v, want a refusal because the helper is busy", res)
			}
			if !exists_(r.sysd.requestAt) || !exists_(r.lockPath) {
				t.Error("the request or the lock was removed from under a live helper")
			}
			if r.sysd.changed() {
				t.Errorf("systemd was changed under a live helper: %v", r.sysd.calls)
			}
		})
	}
}

// Once the units are right the helper reads what is waiting itself. A repair
// that then removed "the stale request" would be removing a live one.
func TestARepairLeavesTheRequestToAHelperThatCameBackAndTookIt(t *testing.T) {
	r := newRepairHost(t)
	r.staleRequest(t, 72*time.Hour, 0)
	r.sysd.onEnable = func() {
		_ = os.Remove(r.sysd.requestAt)
		r.sysd.serviceActive = "active"
	}

	res := r.repair(t, "upd_new")

	if !res.Healed || slices.Contains(res.Actions, updates.ActionRemovedRequest) {
		t.Errorf("result = %+v, want healed without removing a request the helper took", res)
	}
}

func TestARepairKeepsARequestThatIsTooYoungToBeCalledAbandoned(t *testing.T) {
	r := newRepairHost(t)
	r.staleRequest(t, 2*time.Minute, 2*time.Minute)

	res := r.repair(t, "upd_new")

	if slices.Contains(res.Actions, updates.ActionRemovedRequest) || slices.Contains(res.Actions, updates.ActionRemovedLock) {
		t.Errorf("actions = %v; files two minutes old are not abandoned", res.Actions)
	}
	if !exists_(r.sysd.requestAt) || !exists_(r.lockPath) {
		t.Error("a young request or lock was removed")
	}
	if !r.sysd.ran("systemctl enable --now " + UpdatePathUnit) {
		t.Error("the units still need putting right whatever the age of the request")
	}
}

// A healthy helper with nothing wrong is left exactly as it is, and the repair
// does not count against the budget for it.
func TestARepairOfAHealthyHelperChangesNothing(t *testing.T) {
	r := newRepairHost(t)
	r.sysd.pathActive, r.sysd.pathEnabled, r.sysd.pathFailed = "active", "enabled", false

	res := r.repair(t, "upd_new")

	if !res.Healed || len(res.Actions) != 0 || r.sysd.changed() {
		t.Errorf("result = %+v, calls %v; a healthy helper needs nothing", res, r.sysd.calls)
	}
}

// Never self-heal in a loop: a second repair a minute after the first is refused
// by root against its own record, whatever the service asks.
func TestRootRefusesToRepairAgainSoSoon(t *testing.T) {
	r := newRepairHost(t)
	r.staleRequest(t, 72*time.Hour, 0)
	first := r.repair(t, "upd_one")
	if !first.Healed {
		t.Fatalf("the first repair failed: %+v", first)
	}

	r.sysd.pathActive, r.sysd.pathEnabled, r.sysd.pathFailed = "inactive", "disabled", true
	r.sysd.calls = nil
	r.now = r.now.Add(time.Minute)
	second := r.repair(t, "upd_two")

	if second.Healed || !slices.Equal(second.Actions, []string{updates.ActionRefusedRateLimit}) || !strings.Contains(second.Error, "too recently") {
		t.Errorf("second result = %+v, want a refusal for repairing too soon", second)
	}
	if r.sysd.changed() {
		t.Errorf("the second repair changed systemd: %v", r.sysd.calls)
	}

	// After the interval it is allowed again, up to the day's limit.
	r.now = r.now.Add(updates.RepairMinInterval)
	if third := r.repair(t, "upd_three"); !third.Healed {
		t.Errorf("a repair after the interval was refused: %+v", third)
	}
}

func TestAGarbledRepairRequestIsRemovedAndNothingIsDoneForIt(t *testing.T) {
	r := newRepairHost(t)
	plant(t, filepath.Join(r.dir, updates.RepairFile), `{"v":1,"id":"upd_x","requested_at":"2026-10-08T09:00:00Z","run":"rm -rf /"}`)
	opts := RepairOptions{HelperOptions: r.opts, unitDir: r.unitDir, run: r.sysd.run, settle: time.Millisecond, sleep: func(time.Duration) {}}
	opts.Now = func() time.Time { return r.now }
	if err := RunUpdateRepair(context.Background(), opts); err != nil {
		t.Fatal(err)
	}
	if exists_(filepath.Join(r.dir, updates.RepairFile)) {
		t.Error("a request root refused was left to be refused again")
	}
	if len(r.sysd.calls) != 0 {
		t.Errorf("systemd was asked for something on a request that could not be read: %v", r.sysd.calls)
	}
	if res, found, err := channel.ReadRepairResult(r.dir); err != nil || !found || res.Healed || res.Error == "" {
		t.Errorf("result = %+v, found %v, err %v; want a refusal that says why", res, found, err)
	}
}

//go:build unix

package installer

import (
	"bytes"
	"crypto/rand"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"syscall"
	"time"
	"unicode/utf8"

	"github.com/eyupio/zoomies/internal/updates"
	"github.com/eyupio/zoomies/internal/updates/channel"
)

// The root side of the update folder. The service account writes the folder
// and may be compromised, and the helper runs as root, so everything in the
// folder is hostile input: read once through one descriptor, never followed
// through a link, and checked on what was read rather than on a path that can
// change between the check and the use. What limits the helper lives outside
// the folder, where the service cannot reset it.
const (
	// helperMaxAttemptsPerTag is where the helper stops and a person looks: two
	// failures of one release are not going to be fixed by a third. It counts
	// the tries at one release, so the dev channel, which is not one, is left out
	// of it (see admit).
	helperMaxAttemptsPerTag = 2
	// helperMinInterval spaces attempts on one host across every tag, so a loop
	// that names a new tag each time is still one attempt in ten minutes.
	helperMinInterval = 10 * time.Minute
	// helperSeenIDs is how many request ids, and how many tags' attempts, the
	// state remembers. A tag forgotten has had sixty-four others tried since,
	// which at one attempt in ten minutes is most of a day, and the state stays
	// small however long a looping service keeps asking.
	helperSeenIDs = 64

	// helperStateFile is the one file in the state directory.
	helperStateFile = "state.json"
	// maxHelperStateBytes bounds what loading the state reads. The real file is a
	// few kilobytes at its largest.
	maxHelperStateBytes = 64 << 10
	// maxResultErrorBytes and maxResultFieldBytes bound the rest of a result, so
	// that even text that JSON escapes to six bytes a character stays inside the
	// limit the service reads results through.
	maxResultErrorBytes = 2048
	maxResultFieldBytes = 128
)

// helperEUID is the uid the helper's state must belong to. It is a variable so
// that a test, whose files all belong to whoever runs it, can stand for a
// helper whose state somebody else owns without chown.
var helperEUID = os.Geteuid

// fileUID is the ownerOf a real helper passes: the file's owning uid.
func fileUID(fi os.FileInfo) (int, bool) {
	uid, _, ok := fileOwner(fi)
	return uid, ok
}

// readRequest reads the one request in the update folder and refuses anything
// but a plain file, owned by the account the folder belongs to, no larger than
// a request can be, holding exactly the documented shape.
//
// It consumes the request: the name is removed once it has been looked at,
// whatever the verdict, so the path unit fires once per request and a refused
// request is not read again. A refusal comes back with the zero Request and an
// error worth answering with. An empty folder is an error satisfying
// errors.Is(err, fs.ErrNotExist), and there is nobody to answer.
func readRequest(dir *os.Root, wantUID int, ownerOf func(os.FileInfo) (int, bool)) (updates.Request, error) {
	if _, err := dir.Lstat(channel.RequestFile); errors.Is(err, fs.ErrNotExist) {
		return updates.Request{}, fmt.Errorf("there is no %s in the update folder: %w", channel.RequestFile, err)
	}
	r, err := inspectRequest(dir, wantUID, ownerOf)
	// RemoveAll, because a directory planted under the name would otherwise
	// survive and fire the path unit again. It removes a link and never what the
	// link points at, and the root keeps it inside the folder.
	if rmErr := dir.RemoveAll(channel.RequestFile); rmErr != nil && err == nil {
		// A request that cannot be consumed would be read again, so it is not run
		// once either.
		return updates.Request{}, fmt.Errorf("cannot remove %s from the update folder after reading it: %w; the helper does not act on a request it cannot consume", channel.RequestFile, rmErr)
	}
	if err != nil {
		return updates.Request{}, err
	}
	return r, nil
}

// inspectRequest is readRequest without the removal.
//
// The checks run in the order that gives away least. The owner is checked
// before the size and long before the content, so that nothing about a file
// the service does not own (a hard link to one only root can read, say) ends up
// in an answer the service reads.
func inspectRequest(dir *os.Root, wantUID int, ownerOf func(os.FileInfo) (int, bool)) (updates.Request, error) {
	// The owner check is what keeps a hard link to a root-only file out, and it
	// keeps nothing out if the service is root. A service that runs as root can
	// upgrade itself and needs no helper.
	if wantUID == 0 {
		return updates.Request{}, fmt.Errorf("the update folder is recorded as belonging to uid 0, and the helper does not serve root, because every file root can read would then pass as a request; a service that runs as root needs no helper, and otherwise run \"sudo zoomies updates helper install\" again so it records the account zoomies runs as")
	}
	f, info, err := openPlainFile(dir, channel.RequestFile)
	if err != nil {
		return updates.Request{}, err
	}
	defer f.Close()
	uid, ok := ownerOf(info)
	if !ok {
		return updates.Request{}, fmt.Errorf("cannot tell who owns %s, so the helper does not trust it", channel.RequestFile)
	}
	if uid != wantUID {
		return updates.Request{}, fmt.Errorf("%s is owned by uid %d and not by uid %d, the account the update folder belongs to; a rootless or remapped container host owns files under another uid, and the helper does not serve one", channel.RequestFile, uid, wantUID)
	}
	if info.Size() > updates.MaxRequestBytes {
		return updates.Request{}, fmt.Errorf("%s is %d bytes, larger than a request can be (%d)", channel.RequestFile, info.Size(), updates.MaxRequestBytes)
	}
	// One byte more than the limit, so a file that grew since the stat is still
	// refused by the parser and never read whole.
	body, err := io.ReadAll(io.LimitReader(f, updates.MaxRequestBytes+1))
	if err != nil {
		return updates.Request{}, fmt.Errorf("cannot read %s: %w", channel.RequestFile, err)
	}
	return updates.ParseRequest(body)
}

// openPlainFile opens name for reading and hands it back only if the name is a
// plain file, and the file opened is the one the name was.
//
// The name is looked at first, without following it, so that root never opens
// anything but a plain file on the service's say: opening a device can do
// something, and opening a pipe waits for a writer. os.Root follows a link that
// stays inside the root even when the open asks for O_NOFOLLOW, so the flag
// alone refuses only a link out of the folder, and it is the look that refuses
// the rest. The open does not block and the file opened must be the one looked
// at, so a name swapped in between costs an error and not a hang, a terminal or
// a read of something else.
func openPlainFile(dir *os.Root, name string) (*os.File, os.FileInfo, error) {
	named, err := dir.Lstat(name)
	if err != nil {
		return nil, nil, fmt.Errorf("cannot look at %s: %w", name, err)
	}
	if !named.Mode().IsRegular() {
		return nil, nil, fmt.Errorf("%s is a %s and not a plain file", name, fileKind(named.Mode()))
	}
	betweenLookAndOpen(name)
	// O_NOCTTY because the helper is a session leader with no terminal, which a
	// terminal opened without it would become the controlling terminal of.
	f, err := dir.OpenFile(name, os.O_RDONLY|syscall.O_NOFOLLOW|syscall.O_NONBLOCK|syscall.O_NOCTTY, 0)
	if err != nil {
		return nil, nil, fmt.Errorf("cannot open %s: %v", name, err)
	}
	opened, err := f.Stat()
	if err != nil {
		f.Close()
		return nil, nil, fmt.Errorf("cannot look at %s once open: %v", name, err)
	}
	if !opened.Mode().IsRegular() || !os.SameFile(named, opened) {
		f.Close()
		return nil, nil, fmt.Errorf("%s changed while it was being opened", name)
	}
	return f, opened, nil
}

// betweenLookAndOpen runs after the helper has looked at a name (a file in
// openPlainFile, the update folder in openUpdateFolder) and before it opens
// it. It does nothing; it is a variable so that a test can swap the name in
// the one moment a hostile service would.
var betweenLookAndOpen = func(name string) {}

// fileKind says what something that is not a plain file is, for the sentence
// that refuses it.
func fileKind(m fs.FileMode) string {
	switch {
	case m&fs.ModeSymlink != 0:
		return "link"
	case m.IsDir():
		return "folder"
	case m&fs.ModeNamedPipe != 0:
		return "pipe"
	case m&fs.ModeSocket != 0:
		return "socket"
	case m&fs.ModeDevice != 0:
		return "device"
	}
	return "special file"
}

// helperState is what the helper remembers between runs: the request ids it
// has seen, newest last, and when each tag was attempted. It is root's, in a
// directory outside the update folder, because state the service could write
// is state the service could reset.
type helperState struct {
	Seen     []string               `json:"seen"`
	Attempts map[string][]time.Time `json:"attempts"`

	dir string
}

// stateRefusal is the end of every sentence that refuses the state: the helper
// fails closed, and the operator decides whether the limits are reset.
const stateRefusal = "the helper refuses every request until it is fixed, because these are the limits on how often root updates this host"

// loadHelperState reads the state in dir, creating the directory, private, if
// there is none yet. No file is a fresh start. A file that is there and cannot
// be trusted or read is an error and never a fresh start: treating it as one
// would reset the limits, which is what corrupting it would be for.
func loadHelperState(dir string) (*helperState, error) {
	root, err := openStateDir(dir)
	if err != nil {
		return nil, err
	}
	defer root.Close()
	path := filepath.Join(dir, helperStateFile)
	s := &helperState{Attempts: map[string][]time.Time{}, dir: dir}
	if _, err := root.Lstat(helperStateFile); errors.Is(err, fs.ErrNotExist) {
		return s, nil
	}
	f, info, err := openPlainFile(root, helperStateFile)
	if err != nil {
		return nil, fmt.Errorf("the update helper's state %s cannot be used: %w; %s", path, err, stateRefusal)
	}
	defer f.Close()
	if err := checkStateOwner(path, info); err != nil {
		return nil, err
	}
	if info.Size() > maxHelperStateBytes {
		return nil, fmt.Errorf("the update helper's state %s is %d bytes, over the limit of %d; %s", path, info.Size(), maxHelperStateBytes, stateRefusal)
	}
	body, err := io.ReadAll(io.LimitReader(f, maxHelperStateBytes+1))
	if err == nil && len(body) > maxHelperStateBytes {
		err = fmt.Errorf("it is over the limit of %d bytes", maxHelperStateBytes)
	}
	if err == nil {
		dec := json.NewDecoder(bytes.NewReader(body))
		dec.DisallowUnknownFields()
		if err = dec.Decode(s); err == nil {
			if _, tok := dec.Token(); !errors.Is(tok, io.EOF) {
				err = errors.New("it has more in it than one document")
			}
		}
	}
	if err != nil {
		return nil, fmt.Errorf("the update helper's state %s cannot be read: %v; inspect it, and remove it only if you mean to reset the limits; %s", path, err, stateRefusal)
	}
	if s.Attempts == nil {
		s.Attempts = map[string][]time.Time{}
	}
	return s, nil
}

// openStateDir opens the state directory, making it if it is not there, and
// refuses one the helper does not control. The directory is looked at without
// following a link and must be the one that was opened.
func openStateDir(dir string) (*os.Root, error) {
	if err := os.Mkdir(dir, 0o700); err != nil && !errors.Is(err, fs.ErrExist) {
		return nil, fmt.Errorf("cannot create the update helper's state directory %s: %w", dir, err)
	}
	named, err := os.Lstat(dir)
	if err != nil {
		return nil, fmt.Errorf("cannot look at the update helper's state directory %s: %w", dir, err)
	}
	if !named.IsDir() {
		return nil, fmt.Errorf("the update helper's state directory %s is not a folder (it is a %s); remove it so the helper can make its own; %s", dir, fileKind(named.Mode()), stateRefusal)
	}
	root, err := os.OpenRoot(dir)
	if err != nil {
		return nil, fmt.Errorf("cannot open the update helper's state directory %s: %w", dir, err)
	}
	opened, err := root.Stat(".")
	if err != nil {
		err = fmt.Errorf("cannot look at the update helper's state directory %s once open: %w", dir, err)
	} else if !os.SameFile(named, opened) {
		err = fmt.Errorf("the update helper's state directory %s changed while it was being opened; %s", dir, stateRefusal)
	}
	if err == nil {
		err = checkStateOwner(dir, opened)
	}
	if err != nil {
		root.Close()
		return nil, err
	}
	return root, nil
}

// checkStateOwner refuses state the helper's own account does not own, or that
// a group or the world can write, since either could let someone else rewrite
// the limits.
func checkStateOwner(path string, info os.FileInfo) error {
	uid, ok := fileUID(info)
	if !ok {
		return fmt.Errorf("cannot tell who owns the update helper's state %s; %s", path, stateRefusal)
	}
	if want := helperEUID(); uid != want {
		return fmt.Errorf("the update helper's state %s is owned by uid %d and not by uid %d, which the helper runs as; %s", path, uid, want, stateRefusal)
	}
	if info.Mode().Perm()&0o022 != 0 {
		return fmt.Errorf("the update helper's state %s is writable by its group or the world (mode %o); make it writable by its owner alone; %s", path, info.Mode().Perm(), stateRefusal)
	}
	return nil
}

// admit decides whether the helper may act on r at now. It records what it saw
// whatever it decides, so the caller saves the state either way: a refused id
// is still one that has been seen. Only an admitted request counts as an
// attempt.
//
// The dev channel is the one tag that is not counted. It names whatever main
// built last, so asking for it again asks for something else, and what was
// asked of it before says nothing about this time. Counted like a release, two
// updates through it shut a host out of the channel for good, with a sentence
// that blamed a failure no one had had. It is held to the interval alone, as a
// tag that is new every time is, and keeps its newest attempt and no more,
// which is all the interval reads, so a service that keeps asking cannot make
// the state grow.
func (s *helperState) admit(r updates.Request, now time.Time) error {
	if slices.Contains(s.Seen, r.ID) {
		return fmt.Errorf("the request %s has been seen before, and the helper acts on a request once; the controller makes a new request for every attempt", r.ID)
	}
	s.Seen = append(s.Seen, r.ID)
	if over := len(s.Seen) - helperSeenIDs; over > 0 {
		s.Seen = slices.Delete(s.Seen, 0, over)
	}
	tried := s.Attempts[r.Tag]
	dev := r.Tag == updates.DevTag
	// The helper cannot tell a second try that failed from one asked of a host
	// that already has the release, so the sentence does not say which it was.
	if !dev && len(tried) >= helperMaxAttemptsPerTag {
		return fmt.Errorf("%s has been tried %d times on this host already, which is as many as the helper allows; if the host is not on it, find out why, then run \"sudo zoomies upgrade --version %s\" on the host", r.Tag, len(tried), r.Tag)
	}
	if last, ok := s.lastAttempt(now); ok && now.Sub(last) < helperMinInterval {
		return fmt.Errorf("the last update attempt on this host was at %s, and the helper starts at most one every %d minutes; ask again after %s", last.UTC().Format(time.RFC3339), int(helperMinInterval/time.Minute), last.Add(helperMinInterval).UTC().Format(time.RFC3339))
	}
	if dev {
		tried = nil
	}
	s.Attempts[r.Tag] = append(tried, now)
	for len(s.Attempts) > helperSeenIDs {
		delete(s.Attempts, s.tagToForget())
	}
	return nil
}

// lastAttempt is the newest attempt at any tag, leaving out any more than the
// interval ahead of now. One that far ahead was recorded before the clock was
// set back, and waiting for the clock to catch up could lock the helper for as
// long as the clock was wrong; it still counts against its own tag.
func (s *helperState) lastAttempt(now time.Time) (time.Time, bool) {
	var last time.Time
	for _, times := range s.Attempts {
		for _, at := range times {
			if at.After(last) && !at.After(now.Add(helperMinInterval)) {
				last = at
			}
		}
	}
	return last, !last.IsZero()
}

// tagToForget is the tag the state can most afford to lose: of the tags that
// can still be tried, the one tried longest ago, and only when every tag has
// reached its limit, the one that reached it longest ago.
//
// Forgetting a tag at its limit hands it two fresh attempts, so that happens
// only once every remembered tag is at its limit too: a service that wants a
// capped tag back has to spend two attempts on each of sixty-four others first,
// which at one attempt in ten minutes is most of a day. That is the residue the
// bound on the state leaves.
func (s *helperState) tagToForget() string {
	if tag, ok := s.stalestTag(func(times []time.Time) bool { return len(times) < helperMaxAttemptsPerTag }); ok {
		return tag
	}
	tag, _ := s.stalestTag(func([]time.Time) bool { return true })
	return tag
}

// stalestTag is the tag, among those include accepts, whose newest attempt is
// the oldest.
func (s *helperState) stalestTag(include func([]time.Time) bool) (string, bool) {
	var stalest string
	var stalestAt time.Time
	found := false
	for tag, times := range s.Attempts {
		if !include(times) {
			continue
		}
		// A tag with no times, which only a hand-edited file holds, counts as the
		// oldest rather than as a reason to stop.
		var newest time.Time
		for _, at := range times {
			if at.After(newest) {
				newest = at
			}
		}
		if !found || newest.Before(stalestAt) {
			stalest, stalestAt, found = tag, newest, true
		}
	}
	return stalest, found
}

// save writes the state atomically, private to root. A helper that cannot save
// must not act on what it admitted, or a restart would forget the attempt.
func (s *helperState) save() error {
	root, err := openStateDir(s.dir)
	if err != nil {
		return err
	}
	defer root.Close()
	body, err := json.Marshal(s)
	if err != nil {
		return fmt.Errorf("cannot encode the update helper's state: %w", err)
	}
	return replaceFile(root, helperStateFile, body, 0o600)
}

// refusedResult is the answer to a request the helper would not act on. A
// request that could not be read has no id to echo, and is answered all the
// same, so that whoever looks at the folder can see why.
func refusedResult(r updates.Request, err error, at time.Time) updates.Result {
	return updates.Result{V: updates.WireVersion, ID: r.ID, Tag: r.Tag, Error: err.Error(), StartedAt: at, FinishedAt: at}
}

// writeResult answers in the update folder. It never opens result.json: it
// makes a new file under a random name, which cannot already be a link, and
// renames it over the old name, which replaces a planted link rather than
// writing through it. The file is world-readable, since the service has to
// read it and it holds nothing secret.
//
// The text is made printable and bounded first, so the answer stays within
// the limit the service reads results through whatever the engine printed,
// and a person shown it later is shown text and not terminal control.
func writeResult(dir *os.Root, r updates.Result) error {
	r.V = updates.WireVersion
	r.ID = headOf(printable(r.ID, false), maxResultFieldBytes)
	r.Tag = headOf(printable(r.Tag, false), maxResultFieldBytes)
	r.From = headOf(printable(r.From, false), maxResultFieldBytes)
	r.To = headOf(printable(r.To, false), maxResultFieldBytes)
	r.Error = headOf(printable(r.Error, false), maxResultErrorBytes)
	// The reason a run failed is at the end of its output.
	r.LogTail = tailOf(printable(r.LogTail, true), updates.MaxLogTailBytes)
	body, err := json.Marshal(r)
	if err != nil {
		return fmt.Errorf("cannot encode the update result: %w", err)
	}
	return replaceFile(dir, channel.ResultFile, body, 0o644)
}

// replaceFile puts body at name inside root without ever opening name: a new
// file under a random name is written, flushed and renamed over it. The
// temporary name is removed on every path that does not end in the rename.
func replaceFile(root *os.Root, name string, body []byte, mode fs.FileMode) error {
	tmp := "." + strings.TrimSuffix(name, filepath.Ext(name)) + "-" + rand.Text() + ".tmp"
	f, err := root.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL|syscall.O_NOFOLLOW, mode)
	if err != nil {
		return fmt.Errorf("cannot create a file beside %s: %w", name, err)
	}
	renamed := false
	defer func() {
		if !renamed {
			_ = root.Remove(tmp)
		}
	}()
	// Explicit rather than left to the umask, which could make a result the
	// service cannot read.
	err = f.Chmod(mode)
	if err == nil {
		_, err = f.Write(body)
	}
	if err == nil {
		err = f.Sync()
	}
	if cerr := f.Close(); err == nil {
		err = cerr
	}
	if err != nil {
		return fmt.Errorf("cannot write %s: %w", name, err)
	}
	if err := root.Rename(tmp, name); err != nil {
		return fmt.Errorf("cannot put %s in place: %w", name, err)
	}
	renamed = true
	// The rename is durable only once the directory is; until then a power cut
	// could bring back the old state, and with it limits already used up.
	if d, err := root.Open("."); err == nil {
		_ = d.Sync()
		_ = d.Close()
	}
	return nil
}

// headOf is s as valid UTF-8, cut to at most n bytes on a character boundary.
// Invalid bytes are replaced before the cut and not left to encoding/json,
// which would turn each one into a three-byte replacement after it and take the
// text past n.
func headOf(s string, n int) string {
	s = strings.ToValidUTF8(s, "\uFFFD")
	if len(s) <= n {
		return s
	}
	for n > 0 && !utf8.RuneStart(s[n]) {
		n--
	}
	return s[:n]
}

// tailOf is headOf for the end of s.
func tailOf(s string, n int) string {
	s = strings.ToValidUTF8(s, "\uFFFD")
	if len(s) <= n {
		return s
	}
	start := len(s) - n
	for start < len(s) && !utf8.RuneStart(s[start]) {
		start++
	}
	return s[start:]
}

package installer

import (
	"errors"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"syscall"
	"testing"
	"unsafe"

	"github.com/eyupio/zoomies/internal/updates/channel"
)

// A session leader with no terminal that opens a terminal without O_NOCTTY
// takes it as its controlling terminal, and the helper, started by systemd, is
// exactly such a leader. A terminal handed to it as a request would then be
// able to signal root's helper and read from it. The service cannot make a
// device node, so the case is a terminal swapped in between the look and the
// open. The test needs a session of its own, to tell whether it acquired a
// terminal, and a mount namespace of its own, because a pseudo-terminal opens
// only through its own devpts and so is bind-mounted over the request; it runs
// itself again as a child with both, which takes root.
func TestTheHelperNeverTakesATerminalItIsHandedAsARequest(t *testing.T) {
	if os.Getenv("ZOOMIES_TEST_TERMINAL_CHILD") == "1" {
		terminalChild(t)
		return
	}
	cmd := exec.Command(os.Args[0], "-test.run=^TestTheHelperNeverTakesATerminalItIsHandedAsARequest$", "-test.v")
	cmd.Env = append(os.Environ(), "ZOOMIES_TEST_TERMINAL_CHILD=1")
	cmd.SysProcAttr = &syscall.SysProcAttr{Setsid: true, Cloneflags: syscall.CLONE_NEWNS}
	out, err := cmd.CombinedOutput()
	var exitErr *exec.ExitError
	if err != nil && !errors.As(err, &exitErr) {
		t.Skipf("cannot start a child in a mount namespace of its own (it takes root): %v", err)
	}
	if strings.Contains(string(out), "--- SKIP") {
		t.Skipf("the child could not set the case up: %s", lastLine(string(out)))
	}
	if err != nil {
		t.Fatalf("the child failed: %v\n%s", err, out)
	}
}

// terminalChild runs in a fresh session with no controlling terminal, in a
// mount namespace of its own.
func terminalChild(t *testing.T) {
	// Private, so the bind mount below never reaches the host's namespace.
	if err := syscall.Mount("", "/", "", syscall.MS_REC|syscall.MS_PRIVATE, ""); err != nil {
		t.Skipf("cannot make the child's mounts private: %v", err)
	}
	master, err := os.OpenFile("/dev/ptmx", os.O_RDWR|syscall.O_NOCTTY, 0)
	if err != nil {
		t.Skipf("no pseudo-terminals here: %v", err)
	}
	defer master.Close()
	var unlock int32
	if _, _, errno := syscall.Syscall(syscall.SYS_IOCTL, master.Fd(), syscall.TIOCSPTLCK, uintptr(unsafe.Pointer(&unlock))); errno != 0 {
		t.Skipf("cannot unlock the pseudo-terminal: %v", errno)
	}
	var n uint32
	if _, _, errno := syscall.Syscall(syscall.SYS_IOCTL, master.Fd(), syscall.TIOCGPTN, uintptr(unsafe.Pointer(&n))); errno != 0 {
		t.Skipf("cannot name the pseudo-terminal: %v", errno)
	}
	pts := "/dev/pts/" + strconv.Itoa(int(n))

	dir, root := updateRoot(t)
	path := filepath.Join(dir, channel.RequestFile)
	plant(t, path, wellFormedRequest)
	was := betweenLookAndOpen
	betweenLookAndOpen = func(string) {
		if err := os.Remove(path); err != nil {
			t.Fatal(err)
		}
		plant(t, path, "")
		if err := syscall.Mount(pts, path, "", syscall.MS_BIND, ""); err != nil {
			t.Skipf("cannot bind-mount the pseudo-terminal over the request: %v", err)
		}
		t.Cleanup(func() { _ = syscall.Unmount(path, syscall.MNT_DETACH) })
	}
	defer func() { betweenLookAndOpen = was }()

	// The refusal has to come after the open, or the terminal was never opened
	// and the test proves nothing.
	if _, err := readRequest(root, testServiceUID, ownedByService); err == nil || !strings.Contains(err.Error(), "changed while it was being opened") {
		t.Fatalf("a terminal swapped in for the request should be opened and then refused, got: %v", err)
	}
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err == nil {
		tty.Close()
		t.Fatal("reading the request made the terminal handed to it this session's controlling terminal")
	}
	if !errors.Is(err, syscall.ENXIO) {
		t.Fatalf("cannot tell whether a controlling terminal was taken: %v", err)
	}
}

func lastLine(s string) string {
	lines := strings.Split(strings.TrimSpace(s), "\n")
	return lines[len(lines)-1]
}

//go:build unix

package installer

import (
	"encoding/json"
	"errors"
	"io/fs"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"syscall"
	"testing"
	"time"
	"unicode/utf8"

	"github.com/eyupio/zoomies/internal/updates"
	"github.com/eyupio/zoomies/internal/updates/channel"
)

// testServiceUID is the account the update folder belongs to in these tests.
// Every file a test makes belongs to whoever runs the tests, root or not; the
// ownerOf seam is what says a file is the service's, and a test that wants a
// stranger's file says so through it rather than with chown.
const testServiceUID = 65532

func ownedByService(os.FileInfo) (int, bool) { return testServiceUID, true }

func requestBody(id, tag string) string {
	return `{"v":1,"id":"` + id + `","tag":"` + tag + `","requested_by":"user:alice","requested_at":"2026-10-08T09:00:00Z"}`
}

const wellFormedRequest = `{"v":1,"id":"upd_k3fqz2mx7abcd","tag":"v1.3.5","requested_by":"user:alice","requested_at":"2026-10-08T09:00:00Z"}`

// updateRoot is the update folder as the helper holds it: a directory and the
// root handle every read and write goes through.
func updateRoot(t *testing.T) (string, *os.Root) {
	t.Helper()
	dir := filepath.Join(t.TempDir(), "update")
	if err := os.Mkdir(dir, 0o750); err != nil {
		t.Fatal(err)
	}
	root, err := os.OpenRoot(dir)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { root.Close() })
	return dir, root
}

func plant(t *testing.T, path, body string) {
	t.Helper()
	if err := os.WriteFile(path, []byte(body), 0o640); err != nil {
		t.Fatal(err)
	}
}

func contents(t *testing.T, path string) string {
	t.Helper()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return string(b)
}

// assertRefused reads the folder's request and wants a refusal that says
// what it is about, and the request gone.
func assertRefused(t *testing.T, dir string, root *os.Root, ownerOf func(os.FileInfo) (int, bool), want string) {
	t.Helper()
	r, err := readRequest(root, testServiceUID, ownerOf)
	if err == nil {
		t.Fatalf("the request was accepted: %+v", r)
	}
	if !strings.Contains(err.Error(), want) {
		t.Errorf("the refusal should say %q, got: %v", want, err)
	}
	if r != (updates.Request{}) {
		t.Errorf("a refusal came back with a request to act on: %+v", r)
	}
	if _, err := os.Lstat(filepath.Join(dir, channel.RequestFile)); !errors.Is(err, fs.ErrNotExist) {
		t.Errorf("the refused request is still in the folder (%v), so the path unit would fire on it again", err)
	}
}

// The refusals below are only worth anything if a request that breaks none of
// the rules gets through, so this is the one they are all measured against.
func TestTheHelperReadsAWellFormedRequest(t *testing.T) {
	dir, root := updateRoot(t)
	plant(t, filepath.Join(dir, channel.RequestFile), wellFormedRequest)
	r, err := readRequest(root, testServiceUID, ownedByService)
	if err != nil {
		t.Fatalf("readRequest: %v", err)
	}
	if r.ID != "upd_k3fqz2mx7abcd" || r.Tag != "v1.3.5" || r.RequestedBy != "user:alice" {
		t.Fatalf("readRequest = %+v", r)
	}
}

// os.Root follows a link that stays inside the root even when the open asks
// for O_NOFOLLOW, so the link inside the folder is the case that proves the
// name itself is checked. A link out of the folder would let the service point
// root at any file on the host.
func TestTheHelperRefusesARequestThatIsASymlink(t *testing.T) {
	outside := filepath.Join(t.TempDir(), "elsewhere.json")
	plant(t, outside, wellFormedRequest)
	for name, target := range map[string]string{"outside": outside, "inside": "real.json", "dangling": "missing.json"} {
		t.Run(name, func(t *testing.T) {
			dir, root := updateRoot(t)
			plant(t, filepath.Join(dir, "real.json"), wellFormedRequest)
			if err := os.Symlink(target, filepath.Join(dir, channel.RequestFile)); err != nil {
				t.Fatal(err)
			}
			assertRefused(t, dir, root, ownedByService, "link")
			// Consuming a link removes the link and never what it pointed at.
			if got := contents(t, outside); got != wellFormedRequest {
				t.Errorf("the link's target outside the folder changed to %q", got)
			}
			if got := contents(t, filepath.Join(dir, "real.json")); got != wellFormedRequest {
				t.Errorf("the link's target inside the folder changed to %q", got)
			}
		})
	}
}

func TestTheHelperRefusesARequestThatIsADirectory(t *testing.T) {
	dir, root := updateRoot(t)
	if err := os.Mkdir(filepath.Join(dir, channel.RequestFile), 0o750); err != nil {
		t.Fatal(err)
	}
	plant(t, filepath.Join(dir, channel.RequestFile, "inner.json"), wellFormedRequest)
	assertRefused(t, dir, root, ownedByService, "not a plain file")
}

// A pipe opened for reading waits for a writer, and the service would never
// be one: the helper would hang until systemd killed it.
func TestTheHelperRefusesAFIFOWithoutBlocking(t *testing.T) {
	dir, root := updateRoot(t)
	path := filepath.Join(dir, channel.RequestFile)
	if err := syscall.Mkfifo(path, 0o640); err != nil {
		t.Skipf("cannot make a FIFO here: %v", err)
	}
	done := make(chan error, 1)
	go func() {
		_, err := readRequest(root, testServiceUID, ownedByService)
		done <- err
	}()
	select {
	case err := <-done:
		if err == nil || !strings.Contains(err.Error(), "not a plain file") {
			t.Errorf("the refusal should say the request is not a plain file, got: %v", err)
		}
	case <-time.After(5 * time.Second):
		// Opening the pipe for writing releases the blocked reader, so the test
		// ends instead of leaking a goroutine stuck in open.
		if w, err := os.OpenFile(path, os.O_WRONLY, 0); err == nil {
			w.Close()
		}
		t.Fatal("reading a FIFO blocked")
	}
}

// The look and the open are two steps, and a hostile service gets the moment
// between them. Whatever it swaps in, the helper neither hangs nor reads a file
// other than the one it looked at.
func TestTheHelperRefusesARequestSwappedAfterItWasLookedAt(t *testing.T) {
	for name, swap := range map[string]func(t *testing.T, dir, path string){
		"for a FIFO": func(t *testing.T, dir, path string) {
			if err := syscall.Mkfifo(path, 0o640); err != nil {
				t.Skipf("cannot make a FIFO here: %v", err)
			}
		},
		"for a link inside the folder": func(t *testing.T, dir, path string) {
			if err := os.Symlink("real.json", path); err != nil {
				t.Fatal(err)
			}
		},
		"for another file": func(t *testing.T, dir, path string) {
			if err := os.Rename(filepath.Join(dir, "real.json"), path); err != nil {
				t.Fatal(err)
			}
		},
	} {
		t.Run(name, func(t *testing.T) {
			dir, root := updateRoot(t)
			path := filepath.Join(dir, channel.RequestFile)
			plant(t, path, wellFormedRequest)
			plant(t, filepath.Join(dir, "real.json"), requestBody("upd_bbbb", "v1.3.6"))
			was := betweenLookAndOpen
			betweenLookAndOpen = func(string) {
				if err := os.Remove(path); err != nil {
					t.Fatal(err)
				}
				swap(t, dir, path)
			}
			t.Cleanup(func() { betweenLookAndOpen = was })
			done := make(chan error, 1)
			go func() {
				_, err := readRequest(root, testServiceUID, ownedByService)
				done <- err
			}()
			select {
			case err := <-done:
				if err == nil || !strings.Contains(err.Error(), "changed while it was being opened") {
					t.Errorf("the refusal should say the request changed, got: %v", err)
				}
			case <-time.After(5 * time.Second):
				if w, err := os.OpenFile(path, os.O_WRONLY, 0); err == nil {
					w.Close()
				}
				t.Fatal("reading a request swapped for a FIFO blocked")
			}
		})
	}
}

// A service that runs as root needs no helper, and serving one would make the
// owner check meaningless: every file root can read, including one hard-linked
// into the folder, is root's, so it would pass as a request.
func TestTheHelperRefusesToServeAFolderThatBelongsToRoot(t *testing.T) {
	dir, root := updateRoot(t)
	plant(t, filepath.Join(dir, channel.RequestFile), wellFormedRequest)
	ownedByRoot := func(os.FileInfo) (int, bool) { return 0, true }
	r, err := readRequest(root, 0, ownedByRoot)
	if err == nil {
		t.Fatalf("a request for a root-owned folder was accepted: %+v", r)
	}
	if !strings.Contains(err.Error(), "uid 0") || !strings.Contains(err.Error(), "helper install") {
		t.Errorf("the refusal should say the folder is root's and how to fix it, got: %v", err)
	}
	if _, err := os.Lstat(filepath.Join(dir, channel.RequestFile)); !errors.Is(err, fs.ErrNotExist) {
		t.Errorf("the refused request is still in the folder: %v", err)
	}
}

// A request that cannot be consumed would be read again on the next firing, so
// it is not acted on once either. Root can remove from any folder, so this is
// only seen as another account.
func TestTheHelperRefusesARequestItCannotRemove(t *testing.T) {
	if os.Geteuid() == 0 {
		t.Skip("root can remove a file from a read-only folder; run the tests as another account to see this")
	}
	dir, root := updateRoot(t)
	plant(t, filepath.Join(dir, channel.RequestFile), wellFormedRequest)
	if err := os.Chmod(dir, 0o500); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { os.Chmod(dir, 0o750) })
	r, err := readRequest(root, testServiceUID, ownedByService)
	if err == nil || !strings.Contains(err.Error(), "cannot remove") {
		t.Fatalf("a request that could not be removed was not refused for it: %+v, %v", r, err)
	}
	if r != (updates.Request{}) {
		t.Errorf("the refusal came back with a request to act on: %+v", r)
	}
}

func TestTheHelperRefusesAnOversizedRequest(t *testing.T) {
	dir, root := updateRoot(t)
	// Leading spaces keep it a valid request, so its size is all that is wrong.
	body := strings.Repeat(" ", updates.MaxRequestBytes+1-len(wellFormedRequest)) + wellFormedRequest
	plant(t, filepath.Join(dir, channel.RequestFile), body)
	assertRefused(t, dir, root, ownedByService, "larger than a request can be")
}

// The folder is the service's, so a file in it owned by anyone else is not
// one the service wrote. Above all it may be root's: a hard link to a file
// only root can read, which the helper must not read for it, not even far
// enough to quote a field name back in its answer.
func TestTheHelperRefusesARequestOwnedBySomeoneElse(t *testing.T) {
	for name, ownerOf := range map[string]func(os.FileInfo) (int, bool){
		"root":       func(os.FileInfo) (int, bool) { return 0, true },
		"a stranger": func(os.FileInfo) (int, bool) { return 1000, true },
		// The uid it would have answered is the right one, so only the
		// unanswered question refuses it.
		"nobody can tell": func(os.FileInfo) (int, bool) {
			return testServiceUID, false
		},
	} {
		t.Run(name, func(t *testing.T) {
			dir, root := updateRoot(t)
			plant(t, filepath.Join(dir, channel.RequestFile), `{"root_secret":"hunter2"}`)
			r, err := readRequest(root, testServiceUID, ownerOf)
			if err == nil {
				t.Fatalf("the request was accepted: %+v", r)
			}
			if !strings.Contains(err.Error(), "owned by") && !strings.Contains(err.Error(), "who owns") {
				t.Errorf("the refusal should be about the owner, got: %v", err)
			}
			if strings.Contains(err.Error(), "root_secret") || strings.Contains(err.Error(), "hunter2") {
				t.Errorf("the refusal quotes the content of a file the service does not own: %v", err)
			}
			if _, err := os.Lstat(filepath.Join(dir, channel.RequestFile)); !errors.Is(err, fs.ErrNotExist) {
				t.Errorf("the refused request is still in the folder: %v", err)
			}
		})
	}
}

func TestTheHelperRefusesAnUnknownField(t *testing.T) {
	dir, root := updateRoot(t)
	body := strings.TrimSuffix(wellFormedRequest, "}") + `,"url":"https://example.com/zoomies"}`
	plant(t, filepath.Join(dir, channel.RequestFile), body)
	assertRefused(t, dir, root, ownedByService, "url")
}

func TestTheHelperRefusesABadTag(t *testing.T) {
	for _, tag := range []string{`v1.3`, `1.3.5`, `v1.3.5-rc1`, `v1.3.5\n`, `../v1.3.5`} {
		t.Run(tag, func(t *testing.T) {
			dir, root := updateRoot(t)
			plant(t, filepath.Join(dir, channel.RequestFile), requestBody("upd_k3fqz2mx7abcd", tag))
			assertRefused(t, dir, root, ownedByService, "release tag")
		})
	}
}

// The path unit fires while request.json exists, so a request left behind
// would run the helper again and again; and a refused one is no different.
func TestTheHelperConsumesTheRequestItReads(t *testing.T) {
	for name, body := range map[string]string{"accepted": wellFormedRequest, "refused": `{"v":2}`} {
		t.Run(name, func(t *testing.T) {
			dir, root := updateRoot(t)
			plant(t, filepath.Join(dir, channel.RequestFile), body)
			_, _ = readRequest(root, testServiceUID, ownedByService)
			if _, err := os.Lstat(filepath.Join(dir, channel.RequestFile)); !errors.Is(err, fs.ErrNotExist) {
				t.Errorf("the request is still in the folder after it was read: %v", err)
			}
		})
	}
	// No request is not a refusal: the path unit can fire on a file that has gone
	// by the time the helper looks, and there is nobody to answer.
	_, root := updateRoot(t)
	if _, err := readRequest(root, testServiceUID, ownedByService); !errors.Is(err, fs.ErrNotExist) {
		t.Errorf("an empty folder should read as no request, got: %v", err)
	}
}

func testRequest(id, tag string) updates.Request {
	return updates.Request{V: updates.WireVersion, ID: id, Tag: tag, RequestedBy: "user:alice", RequestedAt: time.Date(2026, 10, 8, 9, 0, 0, 0, time.UTC)}
}

// stateDir is where the helper keeps its limits, made fresh for each test so
// the first load starts from nothing.
func stateDir(t *testing.T) string {
	t.Helper()
	return filepath.Join(t.TempDir(), "zoomies-update")
}

func loadState(t *testing.T, dir string) *helperState {
	t.Helper()
	s, err := loadHelperState(dir)
	if err != nil {
		t.Fatalf("loadHelperState: %v", err)
	}
	return s
}

var t0 = time.Date(2026, 10, 8, 9, 0, 0, 0, time.UTC)

// A request is acted on once. A replayed one (the service writing back a
// request it saw before) would otherwise start the same attempt again.
func TestTheHelperRefusesARepeatedRequestID(t *testing.T) {
	s := loadState(t, stateDir(t))
	if err := s.admit(testRequest("upd_aaaa", "v1.3.5"), t0); err != nil {
		t.Fatalf("the first request was refused: %v", err)
	}
	// Late enough and for a tag tried once, so the id is the only thing wrong.
	err := s.admit(testRequest("upd_aaaa", "v1.3.5"), t0.Add(time.Hour))
	if err == nil || !strings.Contains(err.Error(), "seen before") {
		t.Fatalf("a repeated id should be refused as seen before, got: %v", err)
	}
}

// Two failures of one tag is where the helper stops and a person looks. The
// third attempt is refused however long ago the others were, and another tag
// is not held up by it.
func TestTheHelperRefusesATagTriedTwiceAlready(t *testing.T) {
	s := loadState(t, stateDir(t))
	for i, id := range []string{"upd_aaaa", "upd_bbbb"} {
		if err := s.admit(testRequest(id, "v1.3.5"), t0.Add(time.Duration(i)*time.Hour)); err != nil {
			t.Fatalf("attempt %d was refused: %v", i+1, err)
		}
	}
	err := s.admit(testRequest("upd_cccc", "v1.3.5"), t0.Add(30*24*time.Hour))
	if err == nil || !strings.Contains(err.Error(), "tried 2 times") {
		t.Fatalf("a third attempt at one tag should be refused, got: %v", err)
	}
	if err := s.admit(testRequest("upd_dddd", "v1.3.6"), t0.Add(31*24*time.Hour)); err != nil {
		t.Fatalf("another tag was refused: %v", err)
	}
}

// A release asked for twice may have been installed by the first, and asked for
// again of a host that already has it, and the helper does not know which. The
// sentence that refuses a third says what to check, and does not say that
// anything failed.
func TestTheSentenceAtTheLimitOnAReleaseDoesNotSayItFailed(t *testing.T) {
	s := loadState(t, stateDir(t))
	for i, id := range []string{"upd_aaaa", "upd_bbbb"} {
		if err := s.admit(testRequest(id, "v1.3.5"), t0.Add(time.Duration(i)*time.Hour)); err != nil {
			t.Fatal(err)
		}
	}
	err := s.admit(testRequest("upd_cccc", "v1.3.5"), t0.Add(3*time.Hour))
	if err == nil {
		t.Fatal("a third attempt at one release was admitted")
	}
	if strings.Contains(err.Error(), "it failed") || !strings.Contains(err.Error(), `sudo zoomies upgrade --version v1.3.5`) {
		t.Errorf("the sentence should say what to run and claim no failure, got: %v", err)
	}
}

// The dev channel is not one release: it names whatever main built last. A host
// the helper had taken through it twice was shut out of it for good, with a
// sentence that said something had failed when both updates had worked. Only
// the interval holds it back, as it holds back a tag that is new every time.
func TestTheHelperTakesAHostThroughTheDevChannelAgainAndAgain(t *testing.T) {
	s := loadState(t, stateDir(t))
	for i := range 10 {
		id := "upd_" + strings.Repeat("d", i+1)
		if err := s.admit(testRequest(id, updates.DevTag), t0.Add(time.Duration(i)*helperMinInterval)); err != nil {
			t.Fatalf("dev request %d was refused: %v", i+1, err)
		}
	}
	// The newest attempt is all the interval reads, so a service that keeps asking
	// does not make the state grow until the helper refuses to load it.
	newest := t0.Add(9 * helperMinInterval)
	if got := s.Attempts[updates.DevTag]; len(got) != 1 || !got[0].Equal(newest) {
		t.Errorf("the attempts kept for dev are %v, want only the newest, %v", got, newest)
	}
	err := s.admit(testRequest("upd_toosoon", updates.DevTag), newest.Add(time.Minute))
	if err == nil || !strings.Contains(err.Error(), "at most one every") {
		t.Errorf("a dev request a minute after the last was not held to the interval: %v", err)
	}
}

// The state of a host the old count had shut out: two dev attempts, both of
// which had worked. The helper that replaces the old one reads that state, and
// admits the next request, so the host does not need its limits reset by hand
// to be updated again.
func TestAHostTheOldCountShutOutOfTheDevChannelIsLetBackIn(t *testing.T) {
	dir := stateDir(t)
	old := loadState(t, dir)
	old.Attempts[updates.DevTag] = []time.Time{t0.Add(-40 * time.Hour), t0.Add(-36 * time.Hour)}
	if err := old.save(); err != nil {
		t.Fatal(err)
	}
	s := loadState(t, dir)
	if err := s.admit(testRequest("upd_aaaa", updates.DevTag), t0); err != nil {
		t.Fatalf("a host with two old dev attempts was still refused: %v", err)
	}
	if got := s.Attempts[updates.DevTag]; len(got) != 1 || !got[0].Equal(t0) {
		t.Errorf("the attempts kept for dev are %v, want only the one just admitted", got)
	}
}

// The count is of tries at a release. The dev channel does not use up a
// release's attempts, and a release at its limit does not hold up the channel.
func TestTheDevChannelAndAReleaseDoNotCountAgainstEachOther(t *testing.T) {
	s := loadState(t, stateDir(t))
	at := t0
	admit := func(id, tag string) error {
		at = at.Add(helperMinInterval)
		return s.admit(testRequest(id, tag), at)
	}
	for _, id := range []string{"upd_deva", "upd_devb", "upd_devc"} {
		if err := admit(id, updates.DevTag); err != nil {
			t.Fatalf("dev request %s: %v", id, err)
		}
	}
	for _, id := range []string{"upd_rela", "upd_relb"} {
		if err := admit(id, "v1.3.5"); err != nil {
			t.Fatalf("the channel used up an attempt at the release: %v", err)
		}
	}
	if err := admit("upd_relc", "v1.3.5"); err == nil || !strings.Contains(err.Error(), "tried 2 times") {
		t.Fatalf("the release was not held at its limit: %v", err)
	}
	if err := admit("upd_devd", updates.DevTag); err != nil {
		t.Errorf("a release at its limit held up the dev channel: %v", err)
	}
}

// The interval is across tags: a loop that names a new tag every time is still
// one attempt per ten minutes.
func TestTheHelperRefusesAnAttemptWithinTenMinutesOfTheLast(t *testing.T) {
	s := loadState(t, stateDir(t))
	if err := s.admit(testRequest("upd_aaaa", "v1.3.5"), t0); err != nil {
		t.Fatal(err)
	}
	err := s.admit(testRequest("upd_bbbb", "v1.3.6"), t0.Add(helperMinInterval-time.Second))
	if err == nil || !strings.Contains(err.Error(), "at most one every") {
		t.Fatalf("an attempt within ten minutes of the last should be refused, got: %v", err)
	}
	if err := s.admit(testRequest("upd_cccc", "v1.3.6"), t0.Add(helperMinInterval)); err != nil {
		t.Fatalf("an attempt ten minutes after the last was refused: %v", err)
	}
}

// The limits are only limits if a restart of the helper does not forget them,
// and every request is a restart, since each run is a oneshot.
func TestTheHelperStateSurvivesARestart(t *testing.T) {
	dir := stateDir(t)
	s := loadState(t, dir)
	if err := s.admit(testRequest("upd_aaaa", "v1.3.5"), t0); err != nil {
		t.Fatal(err)
	}
	if err := s.save(); err != nil {
		t.Fatalf("save: %v", err)
	}
	again := loadState(t, dir)
	if err := again.admit(testRequest("upd_aaaa", "v1.3.5"), t0.Add(time.Hour)); err == nil {
		t.Error("a restart forgot the ids already seen")
	}
	if err := again.admit(testRequest("upd_bbbb", "v1.3.6"), t0.Add(time.Minute)); err == nil {
		t.Error("a restart forgot when the last attempt was")
	}
	if got := again.Attempts["v1.3.5"]; len(got) != 1 || !got[0].Equal(t0) {
		t.Errorf("the attempts at v1.3.5 after a restart are %v, want [%v]", got, t0)
	}
}

// root owns the state, and nobody else may read or write it: the directory is
// made 0700 and the file 0600 whatever the umask.
func TestTheHelperKeepsItsStatePrivate(t *testing.T) {
	dir := stateDir(t)
	s := loadState(t, dir)
	if err := s.admit(testRequest("upd_aaaa", "v1.3.5"), t0); err != nil {
		t.Fatal(err)
	}
	if err := s.save(); err != nil {
		t.Fatal(err)
	}
	for path, want := range map[string]fs.FileMode{dir: 0o700, filepath.Join(dir, helperStateFile): 0o600} {
		info, err := os.Lstat(path)
		if err != nil {
			t.Fatal(err)
		}
		if got := info.Mode().Perm(); got != want {
			t.Errorf("%s is mode %o, want %o", path, got, want)
		}
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	if len(entries) != 1 {
		t.Errorf("the state directory holds %d entries, want only %s", len(entries), helperStateFile)
	}
}

// The state is bounded however long a host runs, or however many tags a
// looping service names.
func TestTheHelperRemembersABoundedNumberOfRequests(t *testing.T) {
	s := loadState(t, stateDir(t))
	for i := range helperSeenIDs + 5 {
		id := "upd_" + strings.Repeat("a", i+1)
		tag := "v1.0." + strings.Repeat("1", i+1)
		if err := s.admit(testRequest(id, tag), t0.Add(time.Duration(i)*helperMinInterval)); err != nil {
			t.Fatalf("attempt %d: %v", i, err)
		}
	}
	if len(s.Seen) != helperSeenIDs {
		t.Errorf("%d ids are remembered, want %d", len(s.Seen), helperSeenIDs)
	}
	if len(s.Attempts) != helperSeenIDs {
		t.Errorf("%d tags are remembered, want %d", len(s.Attempts), helperSeenIDs)
	}
	newest := "upd_" + strings.Repeat("a", helperSeenIDs+5)
	if !slices.Contains(s.Seen, newest) || slices.Contains(s.Seen, "upd_a") {
		t.Error("the oldest id should be the one forgotten, and the newest kept")
	}
}

// Forgetting a tag to keep the state small must not hand a tag that has reached
// its limit a fresh pair of attempts: the tags forgotten first are the ones
// that can still be tried anyway.
func TestTheHelperKeepsATagAtItsLimitWhenItForgetsOthers(t *testing.T) {
	s := loadState(t, stateDir(t))
	at := t0
	for _, id := range []string{"upd_capa", "upd_capb"} {
		if err := s.admit(testRequest(id, "v1.3.5"), at); err != nil {
			t.Fatal(err)
		}
		at = at.Add(helperMinInterval)
	}
	for i := range helperSeenIDs {
		id := "upd_" + strings.Repeat("b", i+1)
		tag := "v2.0." + strings.Repeat("1", i+1)
		if err := s.admit(testRequest(id, tag), at); err != nil {
			t.Fatalf("attempt %d: %v", i, err)
		}
		at = at.Add(helperMinInterval)
	}
	if len(s.Attempts) != helperSeenIDs {
		t.Fatalf("%d tags are remembered, want %d", len(s.Attempts), helperSeenIDs)
	}
	if _, ok := s.Attempts["v2.0.1"]; ok {
		t.Error("the oldest tag with an attempt left was kept, so the tag at its limit must have been forgotten")
	}
	if err := s.admit(testRequest("upd_capc", "v1.3.5"), at); err == nil || !strings.Contains(err.Error(), "tried 2 times") {
		t.Fatalf("the tag at its limit was let in again after 64 other tags: %v", err)
	}
}

// A clock set back after an attempt leaves that attempt in the future. Waiting
// for the clock to catch up could lock the helper for years, so an attempt
// more than the interval ahead is taken as a clock fault: it no longer holds
// up other attempts, and still counts against its own tag.
func TestTheHelperIsNotLockedByAnAttemptFromTheFuture(t *testing.T) {
	s := loadState(t, stateDir(t))
	if err := s.admit(testRequest("upd_aaaa", "v1.3.5"), t0.Add(24*time.Hour)); err != nil {
		t.Fatal(err)
	}
	if err := s.admit(testRequest("upd_bbbb", "v1.3.5"), t0); err != nil {
		t.Fatalf("an attempt from a day ahead held up the helper: %v", err)
	}
	if err := s.admit(testRequest("upd_cccc", "v1.3.5"), t0.Add(time.Hour)); err == nil || !strings.Contains(err.Error(), "tried 2 times") {
		t.Errorf("the attempt from the future did not count against its tag: %v", err)
	}
	// A little ahead is ordinary skew, and still holds the next attempt back.
	near := loadState(t, stateDir(t))
	if err := near.admit(testRequest("upd_dddd", "v1.3.5"), t0.Add(5*time.Minute)); err != nil {
		t.Fatal(err)
	}
	if err := near.admit(testRequest("upd_eeee", "v1.3.6"), t0); err == nil || !strings.Contains(err.Error(), "at most one every") {
		t.Errorf("an attempt five minutes ahead did not hold up the next: %v", err)
	}
}

// The state is what stops a compromised service from asking root for update
// after update, so anything that might let the service have written it is
// refused and not used: an owner other than the helper's, a mode that lets a
// group or the world write, or a link.
func TestTheHelperRefusesStateItDoesNotControl(t *testing.T) {
	saved := func(t *testing.T) string {
		dir := stateDir(t)
		s := loadState(t, dir)
		if err := s.admit(testRequest("upd_aaaa", "v1.3.5"), t0); err != nil {
			t.Fatal(err)
		}
		if err := s.save(); err != nil {
			t.Fatal(err)
		}
		return dir
	}
	t.Run("owned by another uid", func(t *testing.T) {
		dir := saved(t)
		// The files are whoever runs the tests'; pretending the helper runs as
		// someone else makes them another account's without chown.
		was := helperEUID
		helperEUID = func() int { return 4242 }
		t.Cleanup(func() { helperEUID = was })
		if _, err := loadHelperState(dir); err == nil || !strings.Contains(err.Error(), "owned by") {
			t.Errorf("state owned by another account was used: %v", err)
		}
	})
	t.Run("a group-writable directory", func(t *testing.T) {
		dir := saved(t)
		if err := os.Chmod(dir, 0o770); err != nil {
			t.Fatal(err)
		}
		if _, err := loadHelperState(dir); err == nil || !strings.Contains(err.Error(), "writable") {
			t.Errorf("a group-writable state directory was used: %v", err)
		}
	})
	t.Run("a world-writable file", func(t *testing.T) {
		dir := saved(t)
		if err := os.Chmod(filepath.Join(dir, helperStateFile), 0o602); err != nil {
			t.Fatal(err)
		}
		if _, err := loadHelperState(dir); err == nil || !strings.Contains(err.Error(), "writable") {
			t.Errorf("a world-writable state file was used: %v", err)
		}
	})
	t.Run("a linked directory", func(t *testing.T) {
		real := saved(t)
		link := filepath.Join(t.TempDir(), "zoomies-update")
		if err := os.Symlink(real, link); err != nil {
			t.Fatal(err)
		}
		if _, err := loadHelperState(link); err == nil || !strings.Contains(err.Error(), "not a folder") {
			t.Errorf("a linked state directory was used: %v", err)
		}
	})
	t.Run("a linked file", func(t *testing.T) {
		dir := stateDir(t)
		loadState(t, dir)
		elsewhere := filepath.Join(dir, "elsewhere.json")
		plant(t, elsewhere, `{"seen":[],"attempts":{}}`)
		if err := os.Chmod(elsewhere, 0o600); err != nil {
			t.Fatal(err)
		}
		if err := os.Symlink("elsewhere.json", filepath.Join(dir, helperStateFile)); err != nil {
			t.Fatal(err)
		}
		if _, err := loadHelperState(dir); err == nil || !strings.Contains(err.Error(), "link") {
			t.Errorf("a linked state file was used: %v", err)
		}
	})
}

// A state file that cannot be read is not a fresh start: treating it as one
// would reset the limits, which is exactly what corrupting it would be for.
func TestTheHelperRefusesCorruptStateRatherThanResettingIt(t *testing.T) {
	for name, body := range map[string]string{
		"empty":         "",
		"truncated":     `{"seen":["upd_aaaa"],"attem`,
		"not JSON":      "not json",
		"unknown field": `{"seen":[],"attempts":{},"reset":true}`,
		"two documents": `{"seen":[],"attempts":{}}{"seen":[]}`,
	} {
		t.Run(name, func(t *testing.T) {
			dir := stateDir(t)
			loadState(t, dir)
			path := filepath.Join(dir, helperStateFile)
			plant(t, path, body)
			if err := os.Chmod(path, 0o600); err != nil {
				t.Fatal(err)
			}
			_, err := loadHelperState(dir)
			if err == nil {
				t.Fatal("corrupt state was used")
			}
			if !strings.Contains(err.Error(), path) {
				t.Errorf("the refusal should name the state file, got: %v", err)
			}
		})
	}
	t.Run("oversized", func(t *testing.T) {
		dir := stateDir(t)
		loadState(t, dir)
		path := filepath.Join(dir, helperStateFile)
		plant(t, path, strings.Repeat(" ", maxHelperStateBytes)+`{"seen":[],"attempts":{}}`)
		if err := os.Chmod(path, 0o600); err != nil {
			t.Fatal(err)
		}
		// Refused on its size, before any of it is read.
		if _, err := loadHelperState(dir); err == nil || !strings.Contains(err.Error(), "bytes, over the limit") {
			t.Fatalf("an oversized state file should be refused on its size, got: %v", err)
		}
	})
}

// The service can plant anything in the folder, including a link named
// result.json pointing at a file root would then overwrite for it. The answer
// replaces the link with a file of its own and leaves the target alone.
func TestTheResultIsWrittenWithoutFollowingAPlantedLink(t *testing.T) {
	// A hardened unit may set UMask=0077, which must not leave the service with
	// an answer it cannot read.
	was := syscall.Umask(0o077)
	t.Cleanup(func() { syscall.Umask(was) })
	victim := filepath.Join(t.TempDir(), "shadow")
	for name, target := range map[string]string{"outside": victim, "inside": "victim.json"} {
		t.Run(name, func(t *testing.T) {
			plant(t, victim, "untouched")
			dir, root := updateRoot(t)
			inside := filepath.Join(dir, "victim.json")
			plant(t, inside, "untouched")
			resultPath := filepath.Join(dir, channel.ResultFile)
			if err := os.Symlink(target, resultPath); err != nil {
				t.Fatal(err)
			}
			if err := writeResult(root, updates.Result{ID: "upd_aaaa", OK: true, Tag: "v1.3.5"}); err != nil {
				t.Fatalf("writeResult: %v", err)
			}
			info, err := os.Lstat(resultPath)
			if err != nil {
				t.Fatal(err)
			}
			if !info.Mode().IsRegular() {
				t.Fatalf("result.json is %v, want a plain file", info.Mode())
			}
			// The service reads the answer, so it has to be able to.
			if got := info.Mode().Perm(); got != 0o644 {
				t.Errorf("result.json is mode %o, want 644", got)
			}
			for _, path := range []string{victim, inside} {
				if got := contents(t, path); got != "untouched" {
					t.Errorf("%s was written through the link: %q", path, got)
				}
			}
			got, found, err := channel.ReadResult(dir)
			if err != nil || !found || got.ID != "upd_aaaa" || !got.OK {
				t.Fatalf("the service read back %+v, found %v, err %v", got, found, err)
			}
			entries, _ := os.ReadDir(dir)
			if len(entries) != 2 {
				t.Errorf("the folder holds %d entries, want the result and the planted file only", len(entries))
			}
		})
	}
}

// A result is a message for the UI and not a log store, and the service reads
// it through a limit. Whatever the engine printed, the answer stays within the
// bound, is valid UTF-8, and keeps the end of the output, where the reason is.
func TestTheResultIsBoundedAndValidUTF8(t *testing.T) {
	dir, root := updateRoot(t)
	// Each invalid byte becomes a three-byte replacement once encoded, so they
	// have to be counted after the replacement and not before; and the output is
	// longer than the bound, so the cut has to keep the end.
	// The control character is the worst case for size, six bytes each once
	// escaped, so the bound is tested where the encoded document is largest.
	tail := strings.Repeat("\x01\xffa", 7<<10) + "the last line says why"
	worst := strings.Repeat("\x01", 20<<10) // six bytes each once escaped
	// The error's bound falls inside a three-byte character, which has to be
	// dropped whole rather than cut.
	errorText := strings.Repeat("\x01", maxResultErrorBytes-1) + "€€\xffend"
	r := updates.Result{ID: "upd_aaaa", Tag: "v1.3.5", From: worst, To: worst, Error: errorText, LogTail: tail}
	if err := writeResult(root, r); err != nil {
		t.Fatalf("writeResult: %v", err)
	}
	raw := contents(t, filepath.Join(dir, channel.ResultFile))
	if !utf8.ValidString(raw) {
		t.Error("result.json is not valid UTF-8")
	}
	var got updates.Result
	if err := json.Unmarshal([]byte(raw), &got); err != nil {
		t.Fatal(err)
	}
	if len(got.LogTail) > updates.MaxLogTailBytes {
		t.Errorf("the log tail is %d bytes, over %d", len(got.LogTail), updates.MaxLogTailBytes)
	}
	if !strings.HasSuffix(got.LogTail, "the last line says why") {
		t.Error("the log tail lost the end of the output")
	}
	for name, s := range map[string]string{"error": got.Error, "log tail": got.LogTail, "from": got.From} {
		if !utf8.ValidString(s) {
			t.Errorf("the %s is not valid UTF-8", name)
		}
	}
	if len(got.Error) > maxResultErrorBytes || len(got.From) > maxResultFieldBytes {
		t.Errorf("the error is %d bytes and from %d, over their bounds", len(got.Error), len(got.From))
	}
	if got.V != updates.WireVersion {
		t.Errorf("the result is version %d, want %d", got.V, updates.WireVersion)
	}
	// The service's reader is the one that has to accept it.
	if _, found, err := channel.ReadResult(dir); err != nil || !found {
		t.Errorf("the service could not read the bounded result: found %v, err %v", found, err)
	}
}

// A refusal that went unanswered would leave the controller waiting out the
// attempt's whole timeout for a run that never started.
func TestARefusedRequestIsAnsweredWithItsReason(t *testing.T) {
	dir, root := updateRoot(t)
	s := loadState(t, stateDir(t))
	if err := s.admit(testRequest("upd_aaaa", "v1.3.5"), t0); err != nil {
		t.Fatal(err)
	}
	plant(t, filepath.Join(dir, channel.RequestFile), requestBody("upd_bbbb", "v1.3.6"))
	r, err := readRequest(root, testServiceUID, ownedByService)
	if err != nil {
		t.Fatalf("readRequest: %v", err)
	}
	refusal := s.admit(r, t0.Add(time.Minute))
	if refusal == nil {
		t.Fatal("an attempt a minute after the last was admitted")
	}
	at := t0.Add(time.Minute)
	if err := writeResult(root, refusedResult(r, refusal, at)); err != nil {
		t.Fatalf("writeResult: %v", err)
	}
	got, found, err := channel.ReadResult(dir)
	if err != nil || !found {
		t.Fatalf("the service found no answer: %v", err)
	}
	if got.ID != "upd_bbbb" || got.Tag != "v1.3.6" || got.OK || got.Error != refusal.Error() || !got.FinishedAt.Equal(at) {
		t.Errorf("the answer is %+v, want a failure for upd_bbbb saying %q", got, refusal)
	}

	// A request that could not be read has no id to echo, and is still answered.
	plant(t, filepath.Join(dir, channel.RequestFile), `{"v":2}`)
	r, err = readRequest(root, testServiceUID, ownedByService)
	if err == nil {
		t.Fatal("a version 2 request was accepted")
	}
	if err := writeResult(root, refusedResult(r, err, at)); err != nil {
		t.Fatalf("writeResult: %v", err)
	}
	got, _, _ = channel.ReadResult(dir)
	if got.OK || got.ID != "" || !strings.Contains(got.Error, "version 2") {
		t.Errorf("the answer to an unreadable request is %+v", got)
	}
}

//go:build unix

package installer

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"io/fs"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"testing"
	"time"
	"unicode"
	"unicode/utf8"

	"github.com/eyupio/zoomies/internal/updates"
	"github.com/eyupio/zoomies/internal/updates/channel"
)

// helperHost is one host as the helper sees it: an update folder the service
// owns, a state directory of root's, an installed version, and an engine that
// records what it was asked instead of upgrading anything.
type helperHost struct {
	opts      HelperOptions
	dir       string
	log       *bytes.Buffer
	installed string
	upgrades  []string
	// engine is what the fake engine prints and returns; by default it moves
	// the installed version to the tag and succeeds.
	engine func(tag string) (string, error)
}

func newHelperHost(t *testing.T, installed string) *helperHost {
	t.Helper()
	base := privateTempDir(t)
	dir := filepath.Join(base, "update")
	if err := os.Mkdir(dir, 0o750); err != nil {
		t.Fatal(err)
	}
	h := &helperHost{dir: dir, log: &bytes.Buffer{}, installed: installed}
	h.engine = func(tag string) (string, error) {
		h.installed = strings.TrimPrefix(tag, "v")
		return "Upgraded to " + tag + "\n", nil
	}
	h.opts = HelperOptions{
		Dir:        dir,
		StateDir:   filepath.Join(base, "zoomies-update"),
		BinaryPath: filepath.Join(base, "zoomies"),
		LockPath:   filepath.Join(base, "upgrade.lock"),
		ServiceUID: testServiceUID,
		Now:        func() time.Time { return t0 },
		Out:        h.log,
		ownerOf:    ownedByService,
		installedVersion: func(context.Context) (string, error) {
			return h.installed, nil
		},
		upgrade: func(_ context.Context, tag string) (string, error) {
			h.upgrades = append(h.upgrades, tag)
			return h.engine(tag)
		},
	}
	return h
}

func (h *helperHost) ask(t *testing.T, body string) {
	t.Helper()
	plant(t, filepath.Join(h.dir, channel.RequestFile), body)
}

// answer runs the helper once and returns the result it wrote.
func (h *helperHost) answer(t *testing.T) updates.Result {
	t.Helper()
	if err := RunUpdateHelper(context.Background(), h.opts); err != nil {
		t.Fatalf("RunUpdateHelper: %v\nlog:\n%s", err, h.log)
	}
	r, found, err := channel.ReadResult(h.dir)
	if err != nil || !found {
		t.Fatalf("no result the service can read: found %v, err %v\nlog:\n%s", found, err, h.log)
	}
	return r
}

func (h *helperHost) ranNothing(t *testing.T) {
	t.Helper()
	if len(h.upgrades) != 0 {
		t.Errorf("the engine was run for %v", h.upgrades)
	}
}

// fakeZoomies writes a shell script that answers `version --short` and
// `upgrade` the way the real binary does, recording the upgrade's argv and
// printing upgradeOutput.
func fakeZoomies(t *testing.T, path, upgradeOutput string) {
	t.Helper()
	fakeZoomiesScript(t, path, fakeVersion, `printf '`+upgradeOutput+`'`)
}

// fakeVersion is what the fake binary answers to `version --short`: the
// release before the tag until an upgrade has run, the tag after.
const fakeVersion = `if [ -f "$here/upgraded" ]; then echo "1.3.5 (abc1234)"; else echo "1.3.4 (abc1234)"; fi`

// fakeZoomiesScript is fakeZoomies with the shell each command runs, for an
// engine that has to behave in a particular way.
func fakeZoomiesScript(t *testing.T, path, versionCmd, upgrade string) {
	t.Helper()
	script := `#!/bin/sh
here=$(dirname "$0")
case "$1" in
version)
	` + versionCmd + ` ;;
upgrade)
	printf '%s\n' "$@" > "$here/argv"
	touch "$here/upgraded"
	` + upgrade + ` ;;
*)
	exit 2 ;;
esac
`
	if err := os.WriteFile(path, []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}
}

// shorten sets a duration variable for one test.
func shorten(t *testing.T, v *time.Duration, to time.Duration) {
	t.Helper()
	was := *v
	*v = to
	t.Cleanup(func() { *v = was })
}

// The engine re-executes itself into the new binary, so it cannot run inside
// the helper; and --yes would approve, unattended, the deployment additions
// only an operator may agree to. The argv is the whole of what root is asked
// to do, so it is pinned exactly.
func TestTheHelperRunsTheUpgradeForTheRequestedTagAsAChildProcess(t *testing.T) {
	t.Run("the engine is asked for the tag", func(t *testing.T) {
		h := newHelperHost(t, "1.3.4")
		h.ask(t, wellFormedRequest)
		r := h.answer(t)
		if !slices.Equal(h.upgrades, []string{"v1.3.5"}) {
			t.Errorf("the engine was asked for %v, want [v1.3.5]", h.upgrades)
		}
		if !r.OK || r.ID != "upd_k3fqz2mx7abcd" || r.Tag != "v1.3.5" || r.From != "1.3.4" || r.To != "1.3.5" || r.Error != "" {
			t.Errorf("result = %+v", r)
		}
	})
	t.Run("as a child process", func(t *testing.T) {
		h := newHelperHost(t, "")
		h.opts.installedVersion, h.opts.upgrade = nil, nil
		fakeZoomies(t, h.opts.BinaryPath, `Upgraded to v1.3.5\n`)
		h.ask(t, wellFormedRequest)
		r := h.answer(t)
		argv, err := os.ReadFile(filepath.Join(filepath.Dir(h.opts.BinaryPath), "argv"))
		if err != nil {
			t.Fatalf("the engine never ran: %v\nlog:\n%s", err, h.log)
		}
		got := strings.Split(strings.TrimSuffix(string(argv), "\n"), "\n")
		want := []string{"upgrade", "--version", "v1.3.5", "--non-interactive", "--config-dir", filepath.Dir(h.opts.LockPath)}
		if !slices.Equal(got, want) {
			t.Errorf("argv = %q, want %q", got, want)
		}
		if slices.Contains(got, "--yes") {
			t.Error("the helper approved deployment additions with --yes")
		}
		if !r.OK || r.From != "1.3.4" || r.To != "1.3.5" {
			t.Errorf("result = %+v", r)
		}
		if !strings.Contains(r.LogTail, "Upgraded to v1.3.5") || !strings.Contains(h.log.String(), "Upgraded to v1.3.5") {
			t.Errorf("the engine's output is in neither the log tail (%q) nor the helper's log:\n%s", r.LogTail, h.log)
		}
	})
}

// A downgrade is a no-op, and a tag already installed is done: running the
// engine anyway would restart the service and pull images for nothing.
// Release binaries say 1.3.5 without the v, so this is a comparison of
// releases, never of strings.
func TestTheHelperAnswersAnInstalledTagAsDoneWithoutRunningAnything(t *testing.T) {
	for _, installed := range []string{"1.3.5", "1.4.0"} {
		t.Run(installed, func(t *testing.T) {
			h := newHelperHost(t, installed)
			h.ask(t, wellFormedRequest)
			r := h.answer(t)
			h.ranNothing(t)
			if !r.OK || r.From != installed || r.To != "" || r.ID != "upd_k3fqz2mx7abcd" {
				t.Errorf("result = %+v", r)
			}
		})
	}
}

// A build from main cannot be ordered against a tag, and the helper does not
// guess: a wrong guess is a downgrade.
func TestTheHelperRefusesABuildThatIsNotFromARelease(t *testing.T) {
