// The engine's output reaches root's journal through the helper, and none of
// it may reach a terminal that later shows that journal as anything but text.
func TestTheHelperLogsTheEnginesOutputWithoutControlCharacters(t *testing.T) {
	h := newHelperHost(t, "")
	h.opts.installedVersion, h.opts.upgrade = nil, nil
	fakeZoomies(t, h.opts.BinaryPath, `step one\033[2K\rstep two\n`)
	h.ask(t, wellFormedRequest)
	h.answer(t)
	log := h.log.String()
	// Prefixed, so a line the engine printed cannot pass for one of the
	// helper's, or begin with the <N> a journal reads as a priority.
	if !strings.Contains(log, "\nengine: step one") || !strings.Contains(log, "step two") {
		t.Fatalf("the engine's output is not in the log as the engine's:\n%s", log)
	}
	for _, c := range log {
		if c != '\n' && c != '\t' && unicode.IsControl(c) {
			t.Fatalf("the log carries %U:\n%q", c, log)
		}
	}
}

// The ids it has seen and the attempts per tag are what limit root; an
// attempt the helper had not written down before the engine ran would be
// forgotten by a helper killed during the run, and tried again.
func TestTheHelperRecordsTheAttemptBeforeTheEngineRuns(t *testing.T) {
	h := newHelperHost(t, "1.3.4")
	h.engine = func(tag string) (string, error) {
		s, err := loadHelperState(h.opts.StateDir)
		if err != nil {
			t.Fatalf("loadHelperState during the run: %v", err)
		}
		if !slices.Contains(s.Seen, "upd_k3fqz2mx7abcd") || len(s.Attempts["v1.3.5"]) != 1 {
			t.Errorf("the state during the run does not hold this attempt: %+v", s)
		}
		return "", nil
	}
	h.ask(t, wellFormedRequest)
	h.answer(t)
	if len(h.upgrades) != 1 {
		t.Fatalf("the engine ran %d times", len(h.upgrades))
	}
}

// The limits are only limits if the helper asks them: a second request within
// ten minutes is answered with the reason and nothing runs.
func TestTheHelperAnswersARequestItsLimitsRefuse(t *testing.T) {
	h := newHelperHost(t, "1.3.4")
	h.ask(t, requestBody("upd_aaaa", "v1.3.5"))
	h.engine = func(string) (string, error) { return "", errors.New("exit status 1") }
	h.answer(t)
	h.ask(t, requestBody("upd_bbbb", "v1.3.5"))
	r := h.answer(t)
	if len(h.upgrades) != 1 {
		t.Errorf("the engine ran %d times, want once", len(h.upgrades))
	}
	if r.OK || r.ID != "upd_bbbb" || !strings.Contains(r.Error, "at most one every 10 minutes") {
		t.Errorf("result = %+v", r)
	}
}

// The report this was written for: a host the helper had taken through the dev
// channel twice answered every request after that with "tried 2 times", though
// both had worked, and the controller showed its update as failed for good.
// Each request an hour apart runs, a build further on every time.
func TestTheHelperKeepsTakingAHostThroughTheDevChannel(t *testing.T) {
	h := newHelperHost(t, "main-sha-aaaaaaa")
	now := t0
	h.opts.Now = func() time.Time { return now }
	from := h.installed
	for i, build := range []string{"main-sha-bbbbbbb", "main-sha-ccccccc", "main-sha-ddddddd", "main-sha-eeeeeee"} {
		h.engine = func(string) (string, error) {
			h.installed = build
			return "Upgraded to the dev build\n", nil
		}
		h.ask(t, requestBody("upd_dev"+string(rune('a'+i)), updates.DevTag))
		r := h.answer(t)
		if !r.OK || r.From != from || r.To != build {
			t.Fatalf("request %d: result = %+v, want an update from %s to %s", i+1, r, from, build)
		}
		from = build
		now = now.Add(time.Hour)
	}
	if len(h.upgrades) != 4 {
		t.Errorf("the engine ran %d times, want 4", len(h.upgrades))
	}
}

// A request the helper will not even read is answered too, so that whoever
// looks at the folder sees why, and the request is consumed so the path unit
// does not fire on it again.
func TestTheHelperAnswersARequestItWillNotRead(t *testing.T) {
	h := newHelperHost(t, "1.3.4")
	h.opts.ownerOf = func(fi os.FileInfo) (int, bool) {
		if fi.Name() == channel.RequestFile {
			return 4242, true
		}
		return testServiceUID, true
	}
	h.ask(t, wellFormedRequest)
	r := h.answer(t)
	h.ranNothing(t)
	if r.OK || r.ID != "" || !strings.Contains(r.Error, "owned by uid 4242") {
		t.Errorf("result = %+v", r)
	}
	if _, err := os.Lstat(filepath.Join(h.dir, channel.RequestFile)); !errors.Is(err, fs.ErrNotExist) {
		t.Errorf("the refused request is still there: %v", err)
	}
}

// The path unit fires on a request; finding none (it was consumed by a run
// that started first) is nothing to answer.
func TestTheHelperDoesNothingWithoutARequest(t *testing.T) {
	h := newHelperHost(t, "1.3.4")
	if err := RunUpdateHelper(context.Background(), h.opts); err != nil {
		t.Fatalf("RunUpdateHelper: %v", err)
	}
	h.ranNothing(t)
	if _, err := os.Lstat(filepath.Join(h.dir, channel.ResultFile)); !errors.Is(err, fs.ErrNotExist) {
		t.Errorf("a result was written with nothing asked: %v", err)
	}
}

// State that cannot be trusted fails closed, and the request is still
// answered, or the controller would wait out its whole timeout. The answer is
// read by the service, so it says where to look and quotes nothing of the
// state, whose text is root's.
func TestTheHelperAnswersWhenItsStateCannotBeUsedWithoutQuotingIt(t *testing.T) {
	t.Run("corrupt", func(t *testing.T) {
		h := newHelperHost(t, "1.3.4")
		loadState(t, h.opts.StateDir)
		path := filepath.Join(h.opts.StateDir, helperStateFile)
		plant(t, path, `{"seen":["root-only-secret"],"attempts":{"v1.3.5":"root-only-secret"}}`)
		if err := os.Chmod(path, 0o600); err != nil {
			t.Fatal(err)
		}
		h.ask(t, wellFormedRequest)
		r := h.answer(t)
		h.ranNothing(t)
		if r.OK || r.ID != "upd_k3fqz2mx7abcd" || !strings.Contains(r.Error, h.opts.StateDir) {
			t.Errorf("result = %+v", r)
		}
		if strings.Contains(r.Error, "secret") || strings.Contains(r.Error, "string") {
			t.Errorf("the answer quotes the state: %q", r.Error)
		}
	})
	t.Run("owned by another account", func(t *testing.T) {
		h := newHelperHost(t, "1.3.4")
		loadState(t, h.opts.StateDir)
		was := helperEUID
		helperEUID = func() int { return 4242 }
		t.Cleanup(func() { helperEUID = was })
		h.ask(t, wellFormedRequest)
		r := h.answer(t)
		h.ranNothing(t)
		if r.OK || !strings.Contains(r.Error, h.opts.StateDir) {
			t.Errorf("result = %+v", r)
		}
	})
}

// The folder is the service's, and ServiceUID comes from root's own record of
// it. A folder that is not the one the installer gave the service is not
// answered at all: writing into it would be writing where the service pointed.
func TestTheHelperRefusesAnUpdateFolderThatIsNotTheServices(t *testing.T) {
	refused := func(t *testing.T, h *helperHost, want string) {
		t.Helper()
		err := RunUpdateHelper(context.Background(), h.opts)
		if err == nil || !strings.Contains(err.Error(), want) {
			t.Fatalf("the folder was used, or refused for another reason (want %q): %v", want, err)
		}
		h.ranNothing(t)
		// The error is the caller's to print, and it goes to the same journal.
		if strings.Contains(h.log.String(), want) {
			t.Errorf("the refusal was logged as well as returned, so the journal has it twice:\n%s", h.log)
		}
	}
	t.Run("a link to a folder of the service's", func(t *testing.T) {
		h := newHelperHost(t, "1.3.4")
		elsewhere := filepath.Join(t.TempDir(), "elsewhere")
		if err := os.Mkdir(elsewhere, 0o750); err != nil {
			t.Fatal(err)
		}
		plant(t, filepath.Join(elsewhere, channel.RequestFile), wellFormedRequest)
		if err := os.Remove(h.dir); err != nil {
			t.Fatal(err)
		}
		if err := os.Symlink(elsewhere, h.dir); err != nil {
			t.Fatal(err)
		}
		refused(t, h, "link")
		if _, err := os.Lstat(filepath.Join(elsewhere, channel.RequestFile)); err != nil {
			t.Errorf("the request behind the link was consumed: %v", err)
		}
		if _, err := os.Lstat(filepath.Join(elsewhere, channel.ResultFile)); !errors.Is(err, fs.ErrNotExist) {
			t.Errorf("a result was written behind the link: %v", err)
		}
	})
	t.Run("a link to a folder of root's", func(t *testing.T) {
		h := newHelperHost(t, "1.3.4")
		roots := t.TempDir()
		rootsInfo, err := os.Stat(roots)
		if err != nil {
			t.Fatal(err)
		}
		h.opts.ownerOf = func(fi os.FileInfo) (int, bool) {
			if os.SameFile(fi, rootsInfo) {
				return 0, true
			}
			return testServiceUID, true
		}
		if err := os.Remove(h.dir); err != nil {
			t.Fatal(err)
		}
		if err := os.Symlink(roots, h.dir); err != nil {
			t.Fatal(err)
		}
		refused(t, h, "link")
	})
	t.Run("owned by another account", func(t *testing.T) {
		h := newHelperHost(t, "1.3.4")
		info, err := os.Stat(h.dir)
		if err != nil {
			t.Fatal(err)
		}
		h.opts.ownerOf = func(fi os.FileInfo) (int, bool) {
			if os.SameFile(fi, info) {
				return 4242, true
			}
			return testServiceUID, true
		}
		h.ask(t, wellFormedRequest)
		refused(t, h, "owned by uid 4242")
		if _, err := os.Lstat(filepath.Join(h.dir, channel.RequestFile)); err != nil {
			t.Errorf("the request in a folder the helper refused was consumed: %v", err)
		}
	})
	t.Run("swapped for a link after it was looked at", func(t *testing.T) {
		h := newHelperHost(t, "1.3.4")
		elsewhere := filepath.Join(t.TempDir(), "elsewhere")
		if err := os.Mkdir(elsewhere, 0o750); err != nil {
			t.Fatal(err)
		}
		was := betweenLookAndOpen
		betweenLookAndOpen = func(string) {
			if err := os.Rename(h.dir, h.dir+".old"); err != nil {
				t.Fatal(err)
			}
			if err := os.Symlink(elsewhere, h.dir); err != nil {
				t.Fatal(err)
			}
		}
		t.Cleanup(func() { betweenLookAndOpen = was })
		refused(t, h, "changed while it was being opened")
	})
	t.Run("writable by its group", func(t *testing.T) {
		h := newHelperHost(t, "1.3.4")
		if err := os.Chmod(h.dir, 0o770); err != nil {
			t.Fatal(err)
		}
		refused(t, h, "writable by its group or the world")
	})
	t.Run("missing", func(t *testing.T) {
		h := newHelperHost(t, "1.3.4")
		if err := os.Remove(h.dir); err != nil {
			t.Fatal(err)
		}
		refused(t, h, "does not exist")
	})
}

// Whoever can write the folder's parent can put another folder in its place,
// so the parent has to be root's or the service's and nobody else's.
func TestTheHelperRefusesAnUpdateFolderInAFolderOthersCanWrite(t *testing.T) {
	t.Run("world-writable", func(t *testing.T) {
		h := newHelperHost(t, "1.3.4")
		parent := filepath.Dir(h.dir)
		if err := os.Chmod(parent, 0o777); err != nil {
			t.Fatal(err)
		}
		t.Cleanup(func() { os.Chmod(parent, 0o700) })
		if err := RunUpdateHelper(context.Background(), h.opts); err == nil || !strings.Contains(err.Error(), "writable by its group or the world") {
			t.Errorf("a folder in a world-writable folder was used: %v", err)
		}
	})
	t.Run("owned by another account", func(t *testing.T) {
		h := newHelperHost(t, "1.3.4")
		info, err := os.Stat(filepath.Dir(h.dir))
		if err != nil {
			t.Fatal(err)
		}
		h.opts.ownerOf = func(fi os.FileInfo) (int, bool) {
			if os.SameFile(fi, info) {
				return 4242, true
			}
			return testServiceUID, true
		}
		if err := RunUpdateHelper(context.Background(), h.opts); err == nil || !strings.Contains(err.Error(), "uid 4242") {
			t.Errorf("a folder in a stranger's folder was used: %v", err)
		}
	})
}

// A grandchild of the engine can hold its output open after the engine has
// exited 0. Go reports that as ErrWaitDelay, which is not a failed upgrade;
// what the binary reports afterwards is what decides.
func TestAnEngineWhoseChildKeepsItsOutputOpenIsJudgedByTheReleaseItLeft(t *testing.T) {
	shorten(t, &helperStopGrace, 200*time.Millisecond)
	h := newHelperHost(t, "")
	h.opts.installedVersion, h.opts.upgrade = nil, nil
	fakeZoomiesScript(t, h.opts.BinaryPath, fakeVersion, `echo upgraded; sleep 5 &`)
	h.ask(t, wellFormedRequest)
	r := h.answer(t)
	if !r.OK || r.To != "1.3.5" {
		t.Errorf("result = %+v", r)
	}
}

// Stopped by systemd, the engine is asked to stop first, so that it can remove
// upgrade.lock; killed outright, it would leave the lock and every later
// request refused over it. One that will not stop is killed after the grace.
func TestTheEngineIsAskedToStopBeforeItIsKilled(t *testing.T) {
	stopWhenStarted := func(t *testing.T, h *helperHost) context.Context {
		t.Helper()
		ctx, cancel := context.WithCancel(context.Background())
		t.Cleanup(cancel)
		started := filepath.Join(filepath.Dir(h.opts.BinaryPath), "started")
		go func() {
			for range 1000 {
				if _, err := os.Stat(started); err == nil {
					break
				}
				time.Sleep(10 * time.Millisecond)
			}
			cancel()
		}()
		return ctx
	}
	t.Run("it is sent SIGTERM", func(t *testing.T) {
		shorten(t, &helperStopGrace, 10*time.Second)
		h := newHelperHost(t, "")
		h.opts.installedVersion, h.opts.upgrade = nil, nil
		lock := filepath.Join(filepath.Dir(h.opts.BinaryPath), "engine.lock")
		fakeZoomiesScript(t, h.opts.BinaryPath, fakeVersion,
			`trap 'rm -f "$here/engine.lock"; exit 1' TERM; touch "$here/engine.lock" "$here/started"; sleep 30 >/dev/null 2>&1 & wait`)
		h.ask(t, wellFormedRequest)
		if err := RunUpdateHelper(stopWhenStarted(t, h), h.opts); err != nil {
			t.Fatalf("RunUpdateHelper: %v", err)
		}
		if _, err := os.Stat(lock); !errors.Is(err, fs.ErrNotExist) {
			t.Errorf("the engine never ran its handler for SIGTERM, so it was killed outright: %v", err)
		}
		r, _, _ := channel.ReadResult(h.dir)
		if r.OK || !strings.Contains(r.Error, "stopped") {
			t.Errorf("result = %+v", r)
		}
	})
	t.Run("one that ignores it is killed after the grace", func(t *testing.T) {
		shorten(t, &helperStopGrace, 300*time.Millisecond)
		h := newHelperHost(t, "")
		h.opts.installedVersion, h.opts.upgrade = nil, nil
		fakeZoomiesScript(t, h.opts.BinaryPath, fakeVersion,
			`trap '' TERM; touch "$here/started"; sleep 20 >/dev/null 2>&1`)
		h.ask(t, wellFormedRequest)
		began := time.Now()
		if err := RunUpdateHelper(stopWhenStarted(t, h), h.opts); err != nil {
			t.Fatalf("RunUpdateHelper: %v", err)
		}
		if took := time.Since(began); took > 10*time.Second {
			t.Errorf("an engine that ignored SIGTERM held the helper for %s", took)
		}
	})
}

// The version is asked of the installed binary, which answers at once or is
// broken; a broken one must not hold the helper, and an answer no release
// could give is not compared with anything.
func TestTheHelperBoundsWhatItAsksTheInstalledBinary(t *testing.T) {
	t.Run("a binary that does not answer", func(t *testing.T) {
		shorten(t, &helperVersionTimeout, 200*time.Millisecond)
		h := newHelperHost(t, "")
		h.opts.installedVersion, h.opts.upgrade = nil, nil
		fakeZoomiesScript(t, h.opts.BinaryPath, `exec sleep 30`, `true`)
		h.ask(t, wellFormedRequest)
		began := time.Now()
		r := h.answer(t)
		if took := time.Since(began); took > 10*time.Second {
			t.Errorf("a binary that never answered held the helper for %s", took)
		}
		if r.OK || !strings.Contains(r.Error, "cannot tell which release") {
			t.Errorf("result = %+v", r)
		}
	})
	t.Run("a version longer than any release's", func(t *testing.T) {
		h := newHelperHost(t, "1."+strings.Repeat("9", 130))
		h.ask(t, wellFormedRequest)
		r := h.answer(t)
		h.ranNothing(t)
		if r.OK || !strings.Contains(r.Error, "longer than any release") {
			t.Errorf("result = %+v", r)
		}
	})
}

// The lock the helper looks for and the deployment the engine upgrades have
// to be the same one, and both come from root's pointer: an engine left to
// find its own configuration directory could upgrade a deployment whose lock
// the helper never looked at.
func TestTheEngineUpgradesTheDeploymentThePointerNames(t *testing.T) {
	p := newPointerHost(t)
	p.pointer.ConfigDir = filepath.Join(p.base, "srv", "zoomies-config")
	p.pointer.UID = testServiceUID
	for _, d := range []string{filepath.Join(p.base, "srv"), p.pointer.ConfigDir, filepath.Join(p.base, "var")} {
		mustDo(t, os.Mkdir(d, 0o700))
	}
	mustDo(t, os.Mkdir(p.pointer.Dir, 0o750))
	fakeZoomies(t, p.pointer.Binary, `Upgraded to v1.3.5\n`)
	p.write(t)
	opts, err := helperOptionsFromPointer(p.stateDir, fileOwner, p.base)
	if err != nil {
		t.Fatalf("helperOptionsFromPointer: %v", err)
	}
	opts.ownerOf, opts.Now = ownedByService, func() time.Time { return t0 }
	plant(t, filepath.Join(p.pointer.Dir, channel.RequestFile), wellFormedRequest)
	if err := RunUpdateHelper(context.Background(), opts); err != nil {
		t.Fatalf("RunUpdateHelper: %v", err)
	}
	argv, err := os.ReadFile(filepath.Join(filepath.Dir(p.pointer.Binary), "argv"))
	if err != nil {
		t.Fatalf("the engine never ran: %v", err)
	}
	got := strings.Split(strings.TrimSuffix(string(argv), "\n"), "\n")
	if i := slices.Index(got, "--config-dir"); i < 0 || i+1 >= len(got) || got[i+1] != p.pointer.ConfigDir {
		t.Errorf("the engine was not pointed at %s: argv %q", p.pointer.ConfigDir, got)
	}
	if opts.LockPath != filepath.Join(p.pointer.ConfigDir, "upgrade.lock") {
		t.Errorf("the lock is looked for at %s", opts.LockPath)
	}
}

func mustDo(t *testing.T, err error) {
	t.Helper()
	if err != nil {
		t.Fatal(err)
	}
}

// pointerHost is root's state directory holding a copy of the pointer, and the
// binary and configuration directory it names. The binary is two folders down,
// in opt/bin, so that a grandparent can be made to fail on its own; the walk
// up from it stops at base, which stands for / in these tests.
type pointerHost struct {
	base     string
	stateDir string
	pointer  channel.Pointer
}

func newPointerHost(t *testing.T) *pointerHost {
	t.Helper()
	base := privateTempDir(t)
	p := &pointerHost{base: base, stateDir: filepath.Join(base, "zoomies-update")}
	for _, d := range []string{p.stateDir, filepath.Join(base, "opt"), filepath.Join(base, "opt", "bin"), filepath.Join(base, "etc")} {
		mustDo(t, os.Mkdir(d, 0o700))
	}
	binary := filepath.Join(base, "opt", "bin", "zoomies")
	mustDo(t, os.WriteFile(binary, []byte("#!/bin/sh\n"), 0o755))
	p.pointer = channel.Pointer{V: 1, Dir: filepath.Join(base, "var", "update"), Binary: binary, Account: "zoomies", UID: 999, ConfigDir: filepath.Join(base, "etc")}
	return p
}

func (p *pointerHost) write(t *testing.T) string {
	t.Helper()
	body, err := json.Marshal(p.pointer)
	if err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(p.stateDir, channel.PointerFile)
	mustDo(t, os.WriteFile(path, body, 0o600))
	return path
}

// The helper takes nothing from the folder about itself: where the folder is,
// whose it is, which binary to run and where the lock lives all come from
// root's copy of the pointer.
func TestTheHelperTakesItsSettingsFromRootsCopyOfThePointer(t *testing.T) {
	p := newPointerHost(t)
	p.write(t)
	opts, err := helperOptionsFromPointer(p.stateDir, fileOwner, p.base)
	if err != nil {
		t.Fatalf("helperOptionsFromPointer: %v", err)
	}
	if opts.Dir != p.pointer.Dir || opts.StateDir != p.stateDir || opts.BinaryPath != p.pointer.Binary ||
		opts.LockPath != filepath.Join(p.pointer.ConfigDir, "upgrade.lock") || opts.ServiceUID != 999 {
		t.Errorf("options = %+v", opts)
	}
}

// ownedBy says the file or folder called name belongs to uid and gid, and
// leaves everything else to its real owner.
func ownedBy(name string, uid, gid int) func(os.FileInfo) (int, int, bool) {
	return func(fi os.FileInfo) (int, int, bool) {
		if fi.Name() == name {
			return uid, gid, true
		}
		return fileOwner(fi)
	}
}

// Everything in the pointer decides what root does, so each field the helper
// uses is checked by the helper, and a pointer anyone but root could have
// written is not read at all.
func TestTheHelperRefusesAPointerItCannotTrust(t *testing.T) {
	for _, c := range []struct {
		name   string
		change func(t *testing.T, p *pointerHost, path string)
		owner  func(os.FileInfo) (int, int, bool)
		want   string
	}{
		{name: "missing", change: func(t *testing.T, p *pointerHost, path string) { mustDo(t, os.Remove(path)) }, want: "updates helper install"},
		{name: "owned by another account", owner: ownedBy(channel.PointerFile, 4242, 0), want: "owned by uid 4242"},
		{name: "writable by its group", change: func(t *testing.T, p *pointerHost, path string) { mustDo(t, os.Chmod(path, 0o620)) }, want: "writable by its group or the world"},
		{name: "a link", change: func(t *testing.T, p *pointerHost, path string) {
			mustDo(t, os.Rename(path, path+".real"))
			mustDo(t, os.Symlink(path+".real", path))
		}, want: "link"},
		{name: "uid 0", change: func(t *testing.T, p *pointerHost, path string) { p.pointer.UID = 0; p.write(t) }, want: "uid 0"},
		{name: "an account that is not a name", change: func(t *testing.T, p *pointerHost, path string) { p.pointer.Account = "zoomies\nroot"; p.write(t) }, want: "account"},
		{name: "a relative binary", change: func(t *testing.T, p *pointerHost, path string) { p.pointer.Binary = "zoomies"; p.write(t) }, want: "absolute"},
		{name: "a binary that is a link", change: func(t *testing.T, p *pointerHost, path string) {
			mustDo(t, os.Rename(p.pointer.Binary, p.pointer.Binary+"-real"))
			mustDo(t, os.Symlink(p.pointer.Binary+"-real", p.pointer.Binary))
		}, want: "link"},
		{name: "a binary root does not own", owner: ownedBy("zoomies", 4242, 0), want: "owned by uid 4242"},
		{name: "a binary its group can write", change: func(t *testing.T, p *pointerHost, path string) { mustDo(t, os.Chmod(p.pointer.Binary, 0o775)) }, want: "writable by its group or the world"},
		{name: "a binary in a folder root does not own", owner: ownedBy("bin", 4242, 0), want: "owned by uid 4242"},
		{name: "a binary under a folder the service owns", owner: ownedBy("opt", 999, 999), want: "opt is owned by uid 999"},
		{name: "a binary under a folder staff can write", change: func(t *testing.T, p *pointerHost, path string) {
			mustDo(t, os.Chmod(filepath.Join(p.base, "opt"), 0o775))
		}, owner: ownedBy("opt", os.Geteuid(), 50), want: "opt is writable by its group (gid 50)"},
		{name: "a binary under a link", change: func(t *testing.T, p *pointerHost, path string) {
			opt := filepath.Join(p.base, "opt")
			mustDo(t, os.Rename(opt, opt+"-real"))
			mustDo(t, os.Symlink(opt+"-real", opt))
		}, want: "opt is a link"},
		{name: "a binary under a folder anyone can write", change: func(t *testing.T, p *pointerHost, path string) {
			mustDo(t, os.Chmod(filepath.Join(p.base, "opt"), 0o777|os.ModeSticky))
		}, want: "opt is writable by the world"},
		{name: "a binary that cannot run", change: func(t *testing.T, p *pointerHost, path string) { mustDo(t, os.Chmod(p.pointer.Binary, 0o644)) }, want: "not executable"},
		{name: "a relative configuration directory", change: func(t *testing.T, p *pointerHost, path string) { p.pointer.ConfigDir = "etc"; p.write(t) }, want: "absolute"},
		{name: "a configuration directory that is not there", change: func(t *testing.T, p *pointerHost, path string) {
			p.pointer.ConfigDir = filepath.Join(p.pointer.ConfigDir, "missing")
			p.write(t)
		}, want: "configuration directory"},
		{name: "a configuration directory that is a file", change: func(t *testing.T, p *pointerHost, path string) {
			p.pointer.ConfigDir = p.pointer.Binary
			p.write(t)
		}, want: "is a file and not a folder"},
		{name: "a relative update folder", change: func(t *testing.T, p *pointerHost, path string) { p.pointer.Dir = "update"; p.write(t) }, want: "absolute"},
	} {
		t.Run(c.name, func(t *testing.T) {
			p := newPointerHost(t)
			path := p.write(t)
			if c.change != nil {
				c.change(t, p, path)
			}
			owner := c.owner
			if owner == nil {
				owner = fileOwner
			}
			_, err := helperOptionsFromPointer(p.stateDir, owner, p.base)
			if err == nil || !strings.Contains(err.Error(), c.want) {
				t.Errorf("want a refusal saying %q, got: %v", c.want, err)
			}
			if err != nil && strings.Contains(err.Error(), "<nil>") {
				t.Errorf("the refusal prints a nil error: %v", err)
			}
		})
	}
}

// A group-write bit on a folder above the binary is tolerated only for the
// root group, which on a host is root's anyway; staff on an older Debian is
// not, and the refusal says so at install rather than as a timeout later.
func TestTheHelperAcceptsAFolderAboveTheBinaryThatOnlyTheRootGroupCanWrite(t *testing.T) {
	p := newPointerHost(t)
	p.write(t)
	mustDo(t, os.Chmod(filepath.Join(p.base, "opt"), 0o775))
	if _, err := helperOptionsFromPointer(p.stateDir, ownedBy("opt", os.Geteuid(), 0), p.base); err != nil {
		t.Errorf("a folder only the root group can write was refused: %v", err)
	}
}

// A host that never had the helper has no state directory, and the unit that
// runs this is only there if somebody installed it. Running it anyway (by hand,
// or from a unit left behind) must say the helper is not installed and leave the
// filesystem as it was, not make root's folder for a helper that is not there.
func TestReadingRootsPointerNeverMakesTheStateDirectory(t *testing.T) {
	missing := filepath.Join(t.TempDir(), "zoomies-update")
	_, err := helperOptionsFromPointer(missing, fileOwner, "/")
	if err == nil || !strings.Contains(err.Error(), "not installed") || !strings.Contains(err.Error(), "helper install") {
		t.Fatalf("want a refusal saying the helper is not installed, got: %v", err)
	}
	if _, err := os.Lstat(missing); !errors.Is(err, fs.ErrNotExist) {
		t.Errorf("reading the pointer made the state directory (%v)", err)
	}
}

// The engine writes a line or two for the helper alone, under a marker: the
// copy it took and whether it rolled back. The helper reads them out of the log
// an operator reads, so the words a person sees stay prose.
func TestTheHelperTakesTheBackupAndRollbackOutOfTheEngineOutput(t *testing.T) {
	// A copy's directory can hold a space: the value is the whole rest of the
	// line, not the next word.
	input := "Backed up the database as zoomies-20260101-000000 and verified it\n" +
		engineResultMarker + "backup=/var/lib/zoomies/my backups/zoomies-20260101-000000\n" +
		"still starting\n" +
		engineResultMarker + "rolled_back=true\n"
	logTail, backup, rolledBack := parseEngineResult(input)
	if backup != "/var/lib/zoomies/my backups/zoomies-20260101-000000" {
		t.Fatalf("backup = %q", backup)
	}
	if !rolledBack {
		t.Fatal("a rolled-back run was not read as one")
	}
	if strings.Contains(logTail, engineResultMarker) {
		t.Fatalf("the marker is still in the log an operator reads: %q", logTail)
	}
	if !strings.Contains(logTail, "still starting") {
		t.Fatalf("the prose was dropped: %q", logTail)
	}
}

//go:build unix

package installer

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"os/user"
	"path/filepath"
	"slices"
	"strconv"
	"strings"
	"time"
	"unicode"

	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/updates"
	"github.com/eyupio/zoomies/internal/updates/channel"
	"github.com/eyupio/zoomies/internal/version"
)

// The helper's two units. The path unit waits for a request; the service it
// starts is the helper, as root, once per request. Nothing else starts either.
const (
	UpdatePathUnit    = "zoomies-update.path"
	UpdateServiceUnit = "zoomies-update.service"
	// The repair pair is a second, separate way to reach root. The helper's own
	// path unit is the thing that dies when systemd stops it for starting the
	// service too often, and a helper that is dead cannot be asked to repair
	// itself, so the service writes a repair request that these units, which
	// have a start limit of their own, answer.
	UpdateRepairPathUnit    = "zoomies-update-repair.path"
	UpdateRepairServiceUnit = "zoomies-update-repair.service"
)

const (
	// systemdUnitDir is where the helper's units are written.
	systemdUnitDir = "/etc/systemd/system"
	// updateFolderName is the update folder's name, under the state directory on
	// a native install and under the shared folder in a container.
	updateFolderName = "update"
	// imageAccount is what the published image calls ImageUID (distroless'
	// "nonroot"). The host has no such account; the helper only repeats the name
	// in its sentences.
	imageAccount = "nonroot"
)

// RenderUpdateUnits renders the helper's path and service units for the update
// folder dir and the installed binary. Both paths are the host's real ones, and
// a % in either is doubled, since systemd reads one as a specifier.
func RenderUpdateUnits(binary, dir string) (pathUnit, serviceUnit string) {
	esc := func(s string) string { return strings.ReplaceAll(s, "%", "%%") }
	pathUnit = `# Written by "zoomies updates helper install"; "zoomies updates helper remove"
# takes it away. It starts the update helper when the service asks for an update.
[Unit]
Description=Zoomies update helper: waits for the service to ask for an update
Documentation=https://zoomies.sh/security/#what-the-agent-owns-on-a-host

[Path]
PathExists=` + esc(filepath.Join(dir, channel.RequestFile)) + `
Unit=` + UpdateServiceUnit + `

[Install]
WantedBy=paths.target
`
	serviceUnit = `# Written by "zoomies updates helper install"; "zoomies updates helper remove"
# takes it away. ` + UpdatePathUnit + ` starts it, once per request; it is never
# enabled on its own.
[Unit]
Description=Zoomies update helper: applies an update the service asked for
Documentation=https://zoomies.sh/security/#what-the-agent-owns-on-a-host
# A request the helper cannot consume, in a folder it refuses and so leaves
# alone, starts it again the moment it exits. Requests answered one at a time
# never need five starts in ten minutes, so systemd stops that loop here, and
# "sudo zoomies updates helper install" starts it again once the folder is fixed.
StartLimitIntervalSec=10min
StartLimitBurst=5

[Service]
Type=oneshot
User=root
# No EnvironmentFile: the engine runs with this unit's environment, and a file
# the service could write would choose the release root installs.
ExecStart=` + esc(binary) + ` updates helper run
# A backstop. The engine's worst case is fifty minutes (twenty to stop the old
# service, thirty for the new one to answer), and a limit shorter than the run
# would kill it midway and leave upgrade.lock behind.
TimeoutStartSec=2h
# Longer than the thirty seconds the helper gives the engine to remove
# upgrade.lock once told to stop, and to write down that it was stopped.
TimeoutStopSec=2min
# Only the helper is told to stop. It stops the engine itself, asking first and
# killing it thirty seconds later, so that the engine can remove upgrade.lock;
# the default would signal the engine at the same moment, past that order.
KillMode=mixed
# No ProtectSystem: the upgrade writes the binary, the unit files and the
# deployment's Compose and environment files, and pulls images with the
# credentials root holds. Home directories stay read-only, which is why the
# installer refuses the binary, the configuration directory, the update folder
# and a container deployment's directory and environment file in one.
NoNewPrivileges=yes
PrivateTmp=yes
ProtectHome=read-only
ProtectKernelTunables=yes
ProtectKernelModules=yes
ProtectControlGroups=yes
UMask=0022
`
	return pathUnit, serviceUnit
}

// RenderRepairUnits renders the units that repair the helper. The service unit
// runs "zoomies updates helper repair", which takes no flags: like the helper
// itself it learns where everything is from root's copy of the pointer.
func RenderRepairUnits(binary, dir string) (pathUnit, serviceUnit string) {
	esc := func(s string) string { return strings.ReplaceAll(s, "%", "%%") }
	pathUnit = `# Written by "zoomies updates helper install"; "zoomies updates helper remove"
# takes it away. It starts the repair when the service finds the update helper
# stopped and asks for it to be looked at.
[Unit]
Description=Zoomies update helper repair: waits for the service to report a stuck helper
Documentation=https://zoomies.sh/security/#what-the-agent-owns-on-a-host

[Path]
PathExists=` + esc(filepath.Join(dir, updates.RepairFile)) + `
Unit=` + UpdateRepairServiceUnit + `

[Install]
WantedBy=paths.target
`
	serviceUnit = `# Written by "zoomies updates helper install"; "zoomies updates helper remove"
# takes it away. ` + UpdateRepairPathUnit + ` starts it, once per repair request.
[Unit]
Description=Zoomies update helper repair: puts a stopped update helper right
Documentation=https://zoomies.sh/security/#what-the-agent-owns-on-a-host
# The repair removes its own request before it acts, so it cannot start itself
# again; this is a second stop for anything that would, and root keeps a limit
# of its own on how often it repairs.
StartLimitIntervalSec=1h
StartLimitBurst=6

[Service]
Type=oneshot
User=root
ExecStart=` + esc(binary) + ` updates helper repair
TimeoutStartSec=5min
NoNewPrivileges=yes
PrivateTmp=yes
ProtectHome=read-only
ProtectKernelTunables=yes
ProtectKernelModules=yes
ProtectControlGroups=yes
UMask=0022
`
	return pathUnit, serviceUnit
}

// InstallHelperOptions is what installing or removing the update helper needs.
// Every field is root's own record of the deployment, which
// ResolveHelperInstall reads from the installed unit or the deployment record
// and never from the update folder or anything else the service could write.
type InstallHelperOptions struct {
	Deployment Deployment
	// StateDir is the folder the update folder is made in: the state directory
	// the installed unit names on a native install, the shared folder in a
	// container.
	StateDir string
	// ConfigDir is the deployment's configuration directory: where upgrade.lock
	// and the deployment record are, and on a native install where the service
	// looks for its pointer to the update folder.
	ConfigDir string
	// BinaryPath is the installed zoomies the helper runs. It is recorded by its
	// real path, because the helper refuses a link anywhere above the binary.
	BinaryPath string
	// ServiceUID and Account are the account zoomies runs as, which owns the
	// update folder and every request in it.
	ServiceUID int
	Account    string
	// Out is where what was done is said; nil says nothing.
	Out io.Writer

	unitDir        string
	helperStateDir string
	// binaryTop is where the walk up from the binary stops: / on a host.
	binaryTop string
	run       commandRunner
	now       func() time.Time
}

func (o InstallHelperOptions) withDefaults() InstallHelperOptions {
	if o.unitDir == "" {
		o.unitDir = systemdUnitDir
	}
	if o.helperStateDir == "" {
		o.helperStateDir = UpdateHelperStateDir
	}
	if o.binaryTop == "" {
		o.binaryTop = "/"
	}
	if o.run == nil {
		o.run = runCommand
	}
	if o.now == nil {
		o.now = time.Now
	}
	if o.Out == nil {
		o.Out = io.Discard
	}
	return o
}

// ResolveHelperInstall works out the helper's options for the deployment whose
// configuration is in configDir, from what root installed: the deployment
// record for a container, and otherwise the zoomies unit, whose User= is the
// account, whose WorkingDirectory= is the state directory and whose ExecStart=
// is the binary.
func ResolveHelperInstall(configDir string) (InstallHelperOptions, error) {
	// The same look the controller and the agent take before they show a host as
	// one the helper can never be installed on (agent.LocalHelperHost), so that
	// the status and this refusal cannot disagree about which hosts those are.
	if !backend.HasSystemd() {
		return InstallHelperOptions{}, errors.New(noSystemdForHelper)
	}
	executable, err := os.Executable()
	if err != nil {
		return InstallHelperOptions{}, fmt.Errorf("cannot tell where this zoomies binary is: %w", err)
	}
	return resolveHelperInstall(configDir, systemdUnitDir, user.Lookup, executable)
}

// rootNeedsNoHelper is the refusal of a service that runs as root: it can
// upgrade itself, and the helper's owner checks keep nothing out for it.
const rootNeedsNoHelper = `a service that runs as root can upgrade itself and needs no helper; update this host with "sudo zoomies upgrade"`

func resolveHelperInstall(configDir, unitDir string, lookup func(string) (*user.User, error), executable string) (InstallHelperOptions, error) {
	if rec, ok := ReadDeploymentRecord(configDir); ok && rec.Deployment.Containerised() {
		return InstallHelperOptions{
			Deployment: rec.Deployment, StateDir: SharedHostDir, ConfigDir: configDir,
			BinaryPath: executable, ServiceUID: ImageUID, Account: imageAccount,
		}, nil
	}
	for _, unit := range []string{UnitController, UnitAgent} {
		path := filepath.Join(unitDir, unit+".service")
		body, err := os.ReadFile(path)
		if errors.Is(err, fs.ErrNotExist) {
			continue
		}
		if err != nil {
			return InstallHelperOptions{}, fmt.Errorf("cannot read %s, the unit the helper would update: %w", path, err)
		}
		return nativeHelperInstall(path, string(body), configDir, lookup)
	}
	return InstallHelperOptions{}, helperNotApplicable{fmt.Errorf("there is no %s.service or %s.service in %s and no container deployment recorded in %s, so there is no Zoomies service here for the helper to update; install Zoomies first, or pass --config-dir with the deployment's configuration directory", UnitController, UnitAgent, unitDir, configDir)}
}

// nativeHelperInstall reads the options from the unit a native install wrote.
func nativeHelperInstall(path, body, configDir string, lookup func(string) (*user.User, error)) (InstallHelperOptions, error) {
	name, _, _ := ReadUnitIdentity(path)
	if name == "" || name == "root" {
		return InstallHelperOptions{}, helperNotApplicable{fmt.Errorf("%s runs zoomies as root, and %s", path, rootNeedsNoHelper)}
	}
	account, err := lookup(name)
	if err != nil {
		return InstallHelperOptions{}, fmt.Errorf("%s runs zoomies as %s, and that account cannot be found on this host (%v); run \"sudo zoomies init\" again to put the service right", path, name, err)
	}
	uid, err := strconv.Atoi(account.Uid)
	if err != nil {
		return InstallHelperOptions{}, fmt.Errorf("%s runs zoomies as %s, whose uid %q is not a number", path, name, account.Uid)
	}
	if uid == 0 {
		return InstallHelperOptions{}, helperNotApplicable{fmt.Errorf("%s runs zoomies as %s, which is uid 0, and %s", path, name, rootNeedsNoHelper)}
	}
	workDir := unitValue(body, "WorkingDirectory")
	if workDir == "" {
		return InstallHelperOptions{}, fmt.Errorf("%s names no WorkingDirectory, which is the state directory the update folder is made in; run \"sudo zoomies init\" again to write the unit afresh", path)
	}
	args := strings.Fields(unitValue(body, "ExecStart"))
	if len(args) == 0 {
		return InstallHelperOptions{}, fmt.Errorf("%s has no ExecStart, so there is no binary for the helper to run; run \"sudo zoomies init\" again to write the unit afresh", path)
	}
	for i, arg := range args {
		file, ok := strings.CutPrefix(arg, "--config=")
		if !ok && arg == "--config" && i+1 < len(args) {
			file, ok = args[i+1], true
		}
		// The service finds its pointer beside its --config file, so a pointer
		// written anywhere else would be one it never reads.
		if ok && filepath.Dir(strings.Trim(file, `"`)) != filepath.Clean(configDir) {
			return InstallHelperOptions{}, fmt.Errorf("%s starts zoomies with --config %s, and the service looks for its pointer to the update folder beside that file; pass --config-dir %s", path, file, filepath.Dir(strings.Trim(file, `"`)))
		}
	}
	return InstallHelperOptions{
		Deployment: DeploymentNative, StateDir: strings.Trim(workDir, `"`), ConfigDir: configDir,
		BinaryPath: strings.Trim(args[0], `"`), ServiceUID: uid, Account: name,
	}, nil
}

// unitValue is the last value a unit gives key, as systemd takes the last.
func unitValue(body, key string) string {
	value := ""
	for _, line := range strings.Split(body, "\n") {
		if v, ok := strings.CutPrefix(strings.TrimSpace(line), key+"="); ok {
			value = strings.TrimSpace(v)
		}
	}
	return value
}

// InstallUpdateHelper installs the helper: it makes the update folder, owned by
// the service's account, writes root's pointer to it (and on a native install
// the copy the service reads), writes and starts the units, and writes the
// marker last, which is what tells the controller the helper is there.
//
// Everything the helper would refuse is refused here first, before anything is
// written, in the helper's own words: a refusal discovered by the helper is a
// request nobody answers and a timeout ninety minutes later.
func InstallUpdateHelper(ctx context.Context, opts InstallHelperOptions) error {
	o := opts.withDefaults()
	plan, err := o.planInstall(ctx)
	if err != nil {
		return err
	}
	return o.applyInstall(ctx, plan)
}

// helperInstall is what an install writes, worked out and checked.
type helperInstall struct {
	dir     string
	pointer []byte
	binary  string
	units   [][2]string
}

func (o InstallHelperOptions) planInstall(ctx context.Context) (helperInstall, error) {
	if o.ServiceUID <= 0 {
		return helperInstall{}, fmt.Errorf("zoomies runs as uid %d here, and %s", o.ServiceUID, rootNeedsNoHelper)
	}
	if !cleanAbs(o.StateDir) {
		return helperInstall{}, fmt.Errorf("the folder to make the update folder in, %q, is not a clean absolute path", o.StateDir)
	}
	binary, err := filepath.EvalSymlinks(o.BinaryPath)
	if err != nil {
		return helperInstall{}, fmt.Errorf("cannot find the zoomies binary %s: %w", o.BinaryPath, err)
	}
	dir := filepath.Join(o.StateDir, updateFolderName)
	p := channel.Pointer{V: updates.WireVersion, Dir: dir, Binary: binary, Account: o.Account, UID: o.ServiceUID, ConfigDir: o.ConfigDir}
	if err := checkPointer(filepath.Join(o.helperStateDir, channel.PointerFile), p, fileOwner, o.binaryTop); err != nil {
		return helperInstall{}, err
	}
	for _, path := range []string{dir, binary, o.ConfigDir} {
		if err := checkUnitPath(path); err != nil {
			return helperInstall{}, err
		}
	}
	if o.Deployment.Containerised() {
		if err := o.checkSharedMount(ctx); err != nil {
			return helperInstall{}, err
		}
	}
	pathUnit, serviceUnit := RenderUpdateUnits(binary, dir)
	repairPath, repairService := RenderRepairUnits(binary, dir)
	units := [][2]string{{UpdatePathUnit, pathUnit}, {UpdateServiceUnit, serviceUnit},
		{UpdateRepairPathUnit, repairPath}, {UpdateRepairServiceUnit, repairService}}
	for _, u := range units {
		path := filepath.Join(o.unitDir, u[0])
		if old, err := os.ReadFile(path); err == nil && string(old) != u[1] {
			return helperInstall{}, fmt.Errorf("%s already exists with different contents; inspect it, and if it should go, run \"sudo zoomies updates helper remove\" and install again", path)
		}
	}
	if err := checkUpdateFolderParent(o.StateDir, o.ServiceUID, fileUID); err != nil {
		return helperInstall{}, err
	}
	// Root's folder for the helper is made at the first write, if it is not
	// there yet; one that is there and that the helper would refuse is refused
	// now, with everything else.
	if info, err := os.Lstat(o.helperStateDir); err == nil {
		if !info.IsDir() {
			return helperInstall{}, fmt.Errorf("the update helper's state directory %s is not a folder (it is a %s); remove it so the helper can make its own; %s", o.helperStateDir, fileKind(info.Mode()), stateRefusal)
		}
		if err := checkStateOwner(o.helperStateDir, info); err != nil {
			return helperInstall{}, err
		}
	} else if !errors.Is(err, fs.ErrNotExist) {
		return helperInstall{}, fmt.Errorf("cannot look at the update helper's state directory %s: %w", o.helperStateDir, err)
	}
	body, err := json.MarshalIndent(p, "", "  ")
	if err != nil {
		return helperInstall{}, fmt.Errorf("cannot encode the update helper's pointer: %w", err)
	}
	return helperInstall{dir: dir, pointer: append(body, '\n'), binary: binary, units: units}, nil
}

func (o InstallHelperOptions) applyInstall(ctx context.Context, plan helperInstall) error {
	folder, err := makeUpdateFolder(o.StateDir, plan.dir, o.ServiceUID)
	if err != nil {
		return err
	}
	defer folder.Close()
	fmt.Fprintf(o.Out, "The update folder is %s, owned by %s (uid %d).\n", plan.dir, o.Account, o.ServiceUID)

	// Root's copy, which is the one the helper reads, in a folder only root can
	// write.
	state, err := openStateDir(o.helperStateDir)
	if err != nil {
		return err
	}
	state.Close()
	written := []string{filepath.Join(o.helperStateDir, channel.PointerFile)}
	if err := writeFileAtomic(written[0], plan.pointer, 0o600); err != nil {
		return fmt.Errorf("cannot write the update helper's pointer %s: %w", written[0], err)
	}
	// A container finds its folder under the shared folder and has no
	// configuration directory of the installer's to read a pointer from.
	if !o.Deployment.Containerised() {
		path := filepath.Join(o.ConfigDir, channel.PointerFile)
		if err := writeFileAtomic(path, plan.pointer, 0o644); err != nil {
			return fmt.Errorf("cannot write %s, where the service looks for the update folder: %w", path, err)
		}
		written = append(written, path)
	}
	fmt.Fprintf(o.Out, "Wrote %s.\n", strings.Join(written, " and "))

	for _, u := range plan.units {
		path := filepath.Join(o.unitDir, u[0])
		if err := writeFileAtomic(path, []byte(u[1]), 0o644); err != nil {
			return fmt.Errorf("cannot write %s: %w", path, err)
		}
	}
	if _, err := o.run(ctx, "systemctl", "daemon-reload"); err != nil {
		return err
	}
	// A helper systemd stopped for starting too often stays stopped until this.
	_, _ = o.run(ctx, "systemctl", "reset-failed", UpdateServiceUnit, UpdatePathUnit, UpdateRepairServiceUnit, UpdateRepairPathUnit)
	if _, err := o.run(ctx, "systemctl", "enable", "--now", UpdatePathUnit); err != nil {
		return err
	}
	if _, err := o.run(ctx, "systemctl", "enable", "--now", UpdateRepairPathUnit); err != nil {
		return err
	}
	if err := o.writeMarker(folder, plan); err != nil {
		return err
	}
	fmt.Fprintf(o.Out, "Installed and started %s, which runs %s as root when the service asks for an update; remove it with \"sudo zoomies updates helper remove\".\n", UpdatePathUnit, UpdateServiceUnit)
	return nil
}

// writeMarker writes helper.json, unless the one there already says the same
// thing, so that installing again changes nothing.
func (o InstallHelperOptions) writeMarker(folder *os.Root, plan helperInstall) error {
	m := channel.Marker{V: updates.WireVersion, Version: version.Version, Binary: plan.binary, InstalledAt: o.now().UTC()}
	// Read through the folder's handle, never by path: the folder is the
	// service's, and a pipe put in the marker's place must not hang root.
	if f, _, err := openPlainFile(folder, channel.MarkerFile); err == nil {
		var old channel.Marker
		decodeErr := json.NewDecoder(io.LimitReader(f, maxPointerBytes)).Decode(&old)
		f.Close()
		if decodeErr == nil && old.V == m.V && old.Version == m.Version && old.Binary == m.Binary {
			return nil
		}
	}
	body, err := json.Marshal(m)
	if err != nil {
		return fmt.Errorf("cannot encode the update helper's marker: %w", err)
	}
	if err := replaceFile(folder, channel.MarkerFile, body, 0o644); err != nil {
		return fmt.Errorf("cannot write the update helper's marker in %s: %w", plan.dir, err)
	}
	return nil
}

// makeUpdateFolder makes the update folder, gives it to the service's account,
// and opens it as the helper will, through the helper's own check. This is the
// only place the folder is made.
func makeUpdateFolder(parent, dir string, uid int) (*os.Root, error) {
	base, err := os.OpenRoot(parent)
	if err != nil {
		return nil, fmt.Errorf("cannot open %s to make the update folder in: %w", parent, err)
	}
	defer base.Close()
	if err := base.Mkdir(updateFolderName, 0o750); err != nil && !errors.Is(err, fs.ErrExist) {
		return nil, fmt.Errorf("cannot make the update folder %s: %w", dir, err)
	}
	named, err := base.Lstat(updateFolderName)
	if err != nil {
		return nil, fmt.Errorf("cannot look at the update folder %s: %w", dir, err)
	}
	if !named.IsDir() {
		return nil, fmt.Errorf("%s is a %s and not a folder; remove it, and run \"sudo zoomies updates helper install\" again to make the update folder", dir, fileKind(named.Mode()))
	}
	folder, err := base.OpenRoot(updateFolderName)
	if err != nil {
		return nil, fmt.Errorf("cannot open the update folder %s: %w", dir, err)
	}
	opened, err := folder.Stat(".")
	switch {
	case err != nil:
		err = fmt.Errorf("cannot look at the update folder %s once open: %w", dir, err)
	case !os.SameFile(named, opened):
		err = fmt.Errorf("the update folder %s changed while it was being made; run this again", dir)
	default:
		// Through the open folder, so what is given away is the folder that was
		// looked at. The group is left alone: only the owner may write.
		if err = folder.Chown(".", uid, -1); err == nil {
			err = folder.Chmod(".", 0o750)
		}
		if err != nil {
			err = fmt.Errorf("cannot give the update folder %s to uid %d: %w", dir, uid, err)
		}
	}
	folder.Close()
	if err != nil {
		return nil, err
	}
	return openUpdateFolder(dir, uid, fileUID)
}

// checkSharedMount refuses a container that does not mount the shared folder.
// Only a container that runs runners does, and the update folder has to be
// where the controller inside can write a request the host can see.
func (o InstallHelperOptions) checkSharedMount(ctx context.Context) error {
	rec, ok := ReadDeploymentRecord(o.ConfigDir)
	if !ok {
		return fmt.Errorf("there is no deployment record in %s, so the helper cannot tell which container it would update; pass --config-dir with the deployment's configuration directory", o.ConfigDir)
	}
	// The upgrade rewrites these two, and the unit keeps home directories read-only.
	for _, path := range []string{rec.Directory, rec.EnvFile} {
		if path == "" {
			continue
		}
		if err := checkUnitPath(path); err != nil {
			return err
		}
	}
	container := containerOr(rec)
	format := `{{range .Mounts}}{{if eq .Destination "` + SharedHostDir + `"}}{{.Source}}{{end}}{{end}}`
	out, err := o.run(ctx, deploymentRuntime(rec, ""), "inspect", "--type", "container", "--format", format, container)
	if err != nil {
		return fmt.Errorf("cannot ask the %s container whether it mounts the shared folder %s: %w; start the deployment and run this again", container, SharedHostDir, err)
	}
	source := strings.TrimSpace(out)
	switch {
	case source == "":
		return fmt.Errorf("the %s container does not mount the shared folder %s, which a container mounts only when it runs runners, so the controller in it could not write a request the helper would see; a controller-only container is not offered the helper, so update it by hand with \"sudo zoomies upgrade\"", container, SharedHostDir)
	case filepath.Clean(source) != o.StateDir:
		return fmt.Errorf("the %s container mounts %s at the shared folder and not %s, so a request it wrote would not be in the folder the helper watches; mount %s at the same path, as \"sudo zoomies upgrade --yes\" does", container, source, o.StateDir, o.StateDir)
	}
	// A daemon that remaps user namespaces, or runs rootless, owns what the
	// container writes under another uid than the image's, and the helper
	// refuses every request that is not the image's. Docker says so in its
	// security options; Podman is left to the helper's own check.
	if deploymentRuntime(rec, "") == "docker" {
		info, err := o.run(ctx, "docker", "info", "--format", "{{.SecurityOptions}}")
		if err != nil {
			return fmt.Errorf("cannot ask Docker how it runs containers: %w; start it and run this again", err)
		}
		for _, option := range []string{"name=userns", "name=rootless"} {
			if strings.Contains(info, option) {
				return fmt.Errorf("the Docker daemon on this host runs with %s, which maps the container's account to another uid on the host, so every request would be owned by an account the helper does not serve; update this host by hand with \"sudo zoomies upgrade\"", option)
			}
		}
	}
	return nil
}

// protectedHomes are the folders the helper's unit keeps read-only
// (ProtectHome=read-only).
var protectedHomes = []string{"/home", "/root", "/run/user"}

// checkUnitPath refuses a path the helper's unit could not use: one in a home
// directory, which the upgrade could not write under ProtectHome, and one
// systemd would read as something other than a path.
func checkUnitPath(path string) error {
	resolved := resolvedPath(path)
	for _, home := range protectedHomes {
		if resolved == home || strings.HasPrefix(resolved, home+"/") {
			where := path
			if resolved != path {
				where = path + " (" + resolved + ", once its links are followed)"
			}
			return fmt.Errorf("%s is in %s, which the helper's unit keeps read-only so that an upgrade it runs cannot change a home directory, and the upgrade would need to write there; install Zoomies outside a home directory to use the helper", where, home)
		}
	}
	if i := strings.IndexFunc(path, func(r rune) bool {
		return unicode.IsSpace(r) || !unicode.IsGraphic(r) || strings.ContainsRune(`"'\$`, r)
	}); i >= 0 {
		return fmt.Errorf("%s has %q in it, which systemd reads as something other than part of a path; move it to a path without one to use the helper", path, []rune(path[i:])[0])
	}
	return nil
}

// resolvedPath is path with every link in it resolved: a link out of a home
// directory leads into one all the same. Where the end of the path does not
// exist yet, the part that does is resolved and the rest kept. A link whose
// target is missing is followed to where it points, because the install would
// create the folder there.
func resolvedPath(path string) string { return resolvePath(path, 0) }

// maxLinkHops stops a loop of dangling links from being followed for ever.
const maxLinkHops = 40

func resolvePath(path string, hops int) string {
	rest := ""
	for dir := path; ; dir = filepath.Dir(dir) {
		if resolved, err := filepath.EvalSymlinks(dir); err == nil {
			return filepath.Join(resolved, rest)
		}
		if target, err := os.Readlink(dir); err == nil && hops < maxLinkHops {
			if !filepath.IsAbs(target) {
				target = filepath.Join(filepath.Dir(dir), target)
			}
			return filepath.Join(resolvePath(target, hops+1), rest)
		}
		if dir == filepath.Dir(dir) {
			return path
		}
		rest = filepath.Join(filepath.Base(dir), rest)
	}
}

// RemoveUpdateHelper stops the helper and removes it: its units, root's state
// and pointer, the pointer beside the configuration, and what it and the
// installer wrote in the update folder. The folder itself goes only when that
// leaves it empty, since anything else in it is not the helper's.
//
// Which folder that is, and whose, comes from root's copy of the pointer, or
// failing that from StateDir and ServiceUID, which the caller takes from what
// root installed. Never from the copy beside the configuration: the service can
// replace that one, and would then choose a folder for root to empty.
func RemoveUpdateHelper(ctx context.Context, opts InstallHelperOptions) error {
	o := opts.withDefaults()
	removed, left, err := o.remove(ctx)
	for _, line := range removed {
		fmt.Fprintf(o.Out, "Removed %s.\n", line)
	}
	for _, line := range left {
		fmt.Fprintf(o.Out, "Left %s.\n", line)
	}
	if err == nil && len(removed) == 0 && len(left) == 0 {
		fmt.Fprintln(o.Out, "The update helper is not installed on this host; there was nothing to remove.")
	}
	return err
}

// removeUpdateHelper is RemoveUpdateHelper for a caller that reports what was
// removed and left in its own words, which is uninstall.
func removeUpdateHelper(ctx context.Context, opts InstallHelperOptions) (removed, left []string, err error) {
	return opts.withDefaults().remove(ctx)
}

// stopUpdateTrigger turns the path unit off, so that no update starts from now
// on, and then refuses if one is running. In that order, an update that
// started a moment before is seen; and the running one is never stopped, which
// would kill the upgrade midway and leave upgrade.lock behind.
func stopUpdateTrigger(ctx context.Context, opts InstallHelperOptions) error {
	o := opts.withDefaults()
	for _, unit := range []string{UpdatePathUnit, UpdateRepairPathUnit} {
		if exists(filepath.Join(o.unitDir, unit)) {
			if _, err := o.run(ctx, "systemctl", "disable", "--now", unit); err != nil {
				return err
			}
		}
	}
	state, _ := o.run(ctx, "systemctl", "is-active", UpdateServiceUnit)
	if state = strings.TrimSpace(state); slices.Contains([]string{"active", "activating", "deactivating", "reloading"}, state) {
		return fmt.Errorf("the update helper is running an update now (%s is %s); its trigger is off, so no other will start, and removing it now would stop this one midway: wait for it to finish (journalctl -u zoomies-update -f) and run this again; if you meant to keep the helper, turn its trigger back on with \"sudo zoomies updates helper install\"", UpdateServiceUnit, state)
	}
	return nil
}

func (o InstallHelperOptions) remove(ctx context.Context) (removed, left []string, err error) {
	if err := stopUpdateTrigger(ctx, o); err != nil {
		return nil, nil, err
	}
	// Read before root's copy goes: it says where the folder is and whose.
	p, havePointer := o.rootPointer()
	configPointer := ""
	if o.ConfigDir != "" {
		configPointer = filepath.Join(o.ConfigDir, channel.PointerFile)
	}
	installed := havePointer || exists(o.helperStateDir) || (configPointer != "" && exists(configPointer))

	var unitFiles []string
	for _, unit := range []string{UpdatePathUnit, UpdateServiceUnit, UpdateRepairPathUnit, UpdateRepairServiceUnit} {
		unitFiles = append(unitFiles, filepath.Join(o.unitDir, unit))
	}
	for _, path := range unitFiles {
		if err := os.Remove(path); err == nil {
			removed = append(removed, path)
			installed = true
		} else if !errors.Is(err, fs.ErrNotExist) {
			return removed, left, fmt.Errorf("cannot remove %s: %w", path, err)
		}
	}
	if len(removed) > 0 {
		_, _ = o.run(ctx, "systemctl", "daemon-reload")
		_, _ = o.run(ctx, "systemctl", "reset-failed", UpdateServiceUnit, UpdatePathUnit, UpdateRepairServiceUnit, UpdateRepairPathUnit)
	}

	switch {
	case havePointer:
		r, l := emptyUpdateFolder(p.Dir, p.UID)
		removed, left = append(removed, r...), append(left, l...)
	case o.StateDir != "" && o.ServiceUID > 0:
		r, l := emptyUpdateFolder(filepath.Join(o.StateDir, updateFolderName), o.ServiceUID)
		removed, left = append(removed, r...), append(left, l...)
	case installed:
		left = append(left, fmt.Sprintf("the update folder as it is: root's pointer in %s is gone, and nothing else root wrote says which folder was the helper's; look in the state directory, or the shared folder for a container, and remove update/ by hand if it is there", o.helperStateDir))
	}

	// By name only: what it says is never read.
	if configPointer != "" {
		if err := os.Remove(configPointer); err == nil {
			removed = append(removed, configPointer)
		} else if !errors.Is(err, fs.ErrNotExist) {
			left = append(left, fmt.Sprintf("%s, which could not be removed: %v", configPointer, err))
		}
	}

	// Root's state goes only when it is the folder the helper made: root's, and
	// a folder rather than a link to one.
	if info, err := os.Lstat(o.helperStateDir); err == nil {
		owner, _, ok := fileOwner(info)
		switch {
		case !info.IsDir():
			left = append(left, fmt.Sprintf("%s, which is a %s and not the helper's folder", o.helperStateDir, fileKind(info.Mode())))
		case !ok || owner != helperEUID():
			left = append(left, fmt.Sprintf("%s, which is owned by uid %d and not the helper's folder", o.helperStateDir, owner))
		default:
			if err := os.RemoveAll(o.helperStateDir); err != nil {
				left = append(left, fmt.Sprintf("%s, which could not be removed: %v", o.helperStateDir, err))
			} else {
				removed = append(removed, o.helperStateDir+", with the helper's limits and its pointer")
			}
		}
	}
	return removed, left, nil
}

// rootPointer is root's copy of the pointer, read only from a state directory
// that is root's and only if root owns the file, as the helper reads it. It
// creates nothing: an absent directory is no pointer.
func (o InstallHelperOptions) rootPointer() (channel.Pointer, bool) {
	if _, err := os.Lstat(o.helperStateDir); err != nil {
		return channel.Pointer{}, false
	}
	root, err := openStateDir(o.helperStateDir)
	if err != nil {
		return channel.Pointer{}, false
	}
	defer root.Close()
	f, info, err := openPlainFile(root, channel.PointerFile)
	if err != nil {
		return channel.Pointer{}, false
	}
	defer f.Close()
	if checkRootOwns("the update helper's pointer", filepath.Join(o.helperStateDir, channel.PointerFile), info, fileUID) != nil {
		return channel.Pointer{}, false
	}
	body, err := io.ReadAll(io.LimitReader(f, maxPointerBytes+1))
	if err != nil {
		return channel.Pointer{}, false
	}
	p, err := channel.DecodePointer(channel.PointerFile, body)
	if err != nil || p.UID <= 0 || !cleanAbs(p.Dir) {
		return channel.Pointer{}, false
	}
	return p, true
}

// emptyUpdateFolder removes from the update folder what the helper, the
// installer and the service put there for the helper, and the folder too once
// nothing else is in it. A folder the helper would not open is left untouched.
func emptyUpdateFolder(dir string, uid int) (removed, left []string) {
	if _, err := os.Lstat(dir); errors.Is(err, fs.ErrNotExist) {
		return nil, nil
	}
	folder, err := openUpdateFolder(dir, uid, fileUID)
	if err != nil {
		return nil, []string{fmt.Sprintf("%s untouched, because %v", dir, err)}
	}
	defer folder.Close()
	for _, name := range []string{channel.MarkerFile, channel.ResultFile, channel.RequestFile, updates.RepairFile, updates.RepairResultFile} {
		if err := folder.Remove(name); err == nil {
			removed = append(removed, filepath.Join(dir, name))
		} else if !errors.Is(err, fs.ErrNotExist) {
			left = append(left, fmt.Sprintf("%s, which could not be removed: %v", filepath.Join(dir, name), err))
		}
	}
	d, err := folder.Open(".")
	if err != nil {
		return removed, append(left, fmt.Sprintf("%s, which could not be read: %v", dir, err))
	}
	names, err := d.Readdirnames(-1)
	d.Close()
	if err != nil {
		return removed, append(left, fmt.Sprintf("%s, which could not be read: %v", dir, err))
	}
	if len(names) > 0 {
		slices.Sort(names)
		return removed, append(left, fmt.Sprintf("%s, which still holds %s", dir, strings.Join(names, ", ")))
	}
	if err := os.Remove(dir); err != nil {
		return removed, append(left, fmt.Sprintf("%s, which could not be removed: %v", dir, err))
	}
	return append(removed, dir), left
}

