// neverStoppedTheService fails the test if zoomies-update.service was ever
// stopped: that kills the upgrade it is running and leaves upgrade.lock behind.
func (h *installHost) neverStoppedTheService(t *testing.T) {
	t.Helper()
	if slices.ContainsFunc(h.runner.calls, func(c []string) bool {
		return len(c) > 1 && c[0] == "systemctl" && c[1] == "stop" && slices.Contains(c, UpdateServiceUnit)
	}) {
		t.Errorf("remove stopped %s: %v", UpdateServiceUnit, h.runner.lines())
	}
}

// updateRunning makes systemctl say the helper is running an update.
func (h *installHost) updateRunning() {
	h.runner.answer = func(args []string) (string, error) {
		if slices.Equal(args, []string{"is-active", UpdateServiceUnit}) {
			return "activating", errors.New("exit status 3")
		}
		return "", nil
	}
}

// Stopping the helper mid-run would kill the upgrade it is running and leave
// upgrade.lock behind, so an update in flight is let finish. The trigger goes
// first, so that one starting between the look and the refusal is seen, and no
// other starts while the operator waits.
func TestRemovingTheHelperWaitsForAnUpdateItIsRunning(t *testing.T) {
	h := newInstallHost(t, DeploymentNative)
	h.install(t)
	h.runner.calls = nil
	h.updateRunning()
	err := RemoveUpdateHelper(context.Background(), h.opts)
	if err == nil || !strings.Contains(err.Error(), "running an update now") || !strings.Contains(err.Error(), "trigger is off") {
		t.Fatalf("want a refusal while an update runs, saying the trigger is off, got: %v", err)
	}
	if !strings.Contains(err.Error(), "sudo zoomies updates helper install") {
		t.Errorf("the refusal leaves the trigger off and should say how to turn it back on, got: %v", err)
	}
	lines := h.runner.lines()
	disable, look := slices.Index(lines, "systemctl disable --now "+UpdatePathUnit), slices.Index(lines, "systemctl is-active "+UpdateServiceUnit)
	if disable < 0 || look < 0 || disable > look {
		t.Errorf("the trigger should be turned off before the service is looked at: %v", lines)
	}
	h.neverStoppedTheService(t)
	if !exists(filepath.Join(h.opts.unitDir, UpdatePathUnit)) || !exists(filepath.Join(h.folder(), channel.MarkerFile)) {
		t.Error("a refused remove removed something")
	}
}

// foreignFolder is a folder that is not the helper's, holding files named as
// the helper's are, and named by a pointer planted beside the configuration,
// which the service can write. Its uid is the folder's real owner (root, when
// the tests run as root), which is what would let the helper's own folder
// check pass if root believed the planted pointer.
func foreignFolder(t *testing.T, configDir string) string {
	t.Helper()
	dir := filepath.Join(t.TempDir(), "root-only")
	mustDo(t, os.Mkdir(dir, 0o750))
	plant(t, filepath.Join(dir, channel.MarkerFile), "root's")
	plant(t, filepath.Join(dir, channel.ResultFile), "root's")
	writeJSONFile(t, filepath.Join(configDir, channel.PointerFile), channel.Pointer{V: 1, Dir: dir, Binary: "/usr/local/bin/zoomies", Account: "root", UID: os.Geteuid(), ConfigDir: configDir})
	return dir
}

func writeJSONFile(t *testing.T, path string, v any) {
	t.Helper()
	body, err := json.Marshal(v)
	mustDo(t, err)
	mustDo(t, os.WriteFile(path, body, 0o644))
}

func untouched(t *testing.T, dir string) {
	t.Helper()
	for _, name := range []string{channel.MarkerFile, channel.ResultFile} {
		if !exists(filepath.Join(dir, name)) {
			t.Errorf("root acted on the pointer the service can write and removed %s", filepath.Join(dir, name))
		}
	}
}

// The pointer beside the configuration is the service's to read, and the
// service can replace it; root deciding what to delete from it would be the
// service choosing a folder of root's to empty. Only root's own copy says
// where the folder is, and without it the folder is left, and said to be.
func TestRemovingTheHelperNeverActsOnThePointerTheServiceCanWrite(t *testing.T) {
	h := newInstallHost(t, DeploymentNative)
	h.install(t)
	mustDo(t, os.RemoveAll(h.opts.helperStateDir))
	dir := foreignFolder(t, h.configDir)
	h.opts.StateDir, h.opts.ServiceUID = "", 0
	if err := RemoveUpdateHelper(context.Background(), h.opts); err != nil {
		t.Fatalf("RemoveUpdateHelper: %v", err)
	}
	untouched(t, dir)
	if exists(filepath.Join(h.configDir, channel.PointerFile)) {
		t.Error("the pointer beside the configuration should be removed by name")
	}
	if out := h.out.String(); strings.Contains(out, "nothing to remove") || !strings.Contains(out, "Left the update folder") {
		t.Errorf("remove should say it left the update folder, and not that there was nothing to remove:\n%s", out)
	}
}

// Without root's copy, the folder is the one the installed unit says, which is
// what the command line passes.
func TestRemovingTheHelperWithoutRootsPointerUsesWhatRootInstalled(t *testing.T) {
	h := newInstallHost(t, DeploymentNative)
	h.install(t)
	mustDo(t, os.RemoveAll(h.opts.helperStateDir))
	if err := RemoveUpdateHelper(context.Background(), h.opts); err != nil {
		t.Fatalf("RemoveUpdateHelper: %v", err)
	}
	if exists(h.folder()) {
		t.Errorf("the update folder the installed unit names was left:\n%s", h.out)
	}
}

func fakeLookup(name string) (*user.User, error) {
	switch name {
	case "zoomies":
		return &user.User{Username: name, Uid: "999"}, nil
	case "toor":
		return &user.User{Username: name, Uid: "0"}, nil
	}
	return nil, user.UnknownUserError(name)
}

// The account, the state directory and the binary are the installed unit's,
// which is what the service really runs as and from; a container's are the
// image's. Root, and a unit pointing its --config elsewhere, are refused.
func TestTheHelperIsInstalledForWhatTheInstalledUnitRuns(t *testing.T) {
	const unit = "[Service]\nUser=%s\nWorkingDirectory=/var/lib/zoomies\nExecStart=/usr/local/bin/zoomies %s --config %s\n"
	write := func(t *testing.T, dir, name, user, command, config string) {
		t.Helper()
		body := unit
		for _, v := range []string{user, command, config} {
			body = strings.Replace(body, "%s", v, 1)
		}
		mustDo(t, os.WriteFile(filepath.Join(dir, name), []byte(body), 0o644))
	}

	t.Run("a native controller", func(t *testing.T) {
		units := t.TempDir()
		write(t, units, "zoomies.service", "zoomies", "controller", "/etc/zoomies/zoomies.yaml")
		got, err := resolveHelperInstall("/etc/zoomies", units, fakeLookup, "/tmp/elsewhere/zoomies")
		want := InstallHelperOptions{Deployment: DeploymentNative, StateDir: "/var/lib/zoomies", ConfigDir: "/etc/zoomies", BinaryPath: "/usr/local/bin/zoomies", ServiceUID: 999, Account: "zoomies"}
		if err != nil || got.Deployment != want.Deployment || got.StateDir != want.StateDir || got.ConfigDir != want.ConfigDir ||
			got.BinaryPath != want.BinaryPath || got.ServiceUID != want.ServiceUID || got.Account != want.Account {
			t.Errorf("got %+v (%v), want %+v", got, err, want)
		}
	})
	t.Run("a native agent", func(t *testing.T) {
		units := t.TempDir()
		write(t, units, "zoomies-agent.service", "zoomies", "agent", "/etc/zoomies/agent.yaml")
		got, err := resolveHelperInstall("/etc/zoomies", units, fakeLookup, "/tmp/elsewhere/zoomies")
		if err != nil || got.ServiceUID != 999 || got.BinaryPath != "/usr/local/bin/zoomies" {
			t.Errorf("got %+v (%v)", got, err)
		}
	})
	t.Run("a container", func(t *testing.T) {
		config := t.TempDir()
		_, err := WriteDeploymentRecord(config, DeploymentRecord{Deployment: DeploymentDocker})
		mustDo(t, err)
		got, err := resolveHelperInstall(config, t.TempDir(), fakeLookup, "/usr/local/bin/zoomies")
		if err != nil || got.StateDir != SharedHostDir || got.ServiceUID != ImageUID || got.BinaryPath != "/usr/local/bin/zoomies" || got.Deployment != DeploymentDocker {
			t.Errorf("got %+v (%v)", got, err)
		}
	})
	for _, c := range []struct{ name, user, config, want string }{
		{"a service that runs as root", "root", "/etc/zoomies/zoomies.yaml", "needs no helper"},
		{"an account that is uid 0", "toor", "/etc/zoomies/zoomies.yaml", "needs no helper"},
		{"an account that is not there", "ada", "/etc/zoomies/zoomies.yaml", "cannot be found"},
		{"a configuration elsewhere", "zoomies", "/srv/zoomies/zoomies.yaml", "pass --config-dir /srv/zoomies"},
	} {
		t.Run(c.name, func(t *testing.T) {
			units := t.TempDir()
			write(t, units, "zoomies.service", c.user, "controller", c.config)
			_, err := resolveHelperInstall("/etc/zoomies", units, fakeLookup, "/usr/local/bin/zoomies")
			if err == nil || !strings.Contains(err.Error(), c.want) {
				t.Errorf("want a refusal saying %q, got: %v", c.want, err)
			}
		})
	}
	t.Run("no service at all", func(t *testing.T) {
		_, err := resolveHelperInstall(t.TempDir(), t.TempDir(), fakeLookup, "/usr/local/bin/zoomies")
		if err == nil || !strings.Contains(err.Error(), "no Zoomies service") {
			t.Errorf("want a refusal, got: %v", err)
		}
	})
}

// The pointer beside the configuration is the service's to replace, so it
// does not make the helper look installed, and the folder it names is not
// root's to empty.
func TestUninstallNeverActsOnTheHelperPointerTheServiceCanWrite(t *testing.T) {
	opts := uninstallOpts(t)
	opts.Yes, opts.NonInteractive = true, true
	writeFile(t, opts.ConfigDir, "zoomies.yaml", "")
	dir := foreignFolder(t, opts.ConfigDir)
	for _, it := range UninstallItems(opts) {
		if it.What == "update helper" && it.Present {
			t.Errorf("a pointer the service can write made the helper look installed: %+v", it)
		}
	}
	if err := Uninstall(context.Background(), opts); err != nil {
		t.Fatalf("Uninstall: %v", err)
	}
	untouched(t, dir)
}

// Uninstalling under a running upgrade would take the binary and the units
// away from it midway, so the whole uninstall waits, with the trigger off so
// that no other update starts meanwhile.
func TestUninstallRefusesWhileTheHelperIsRunningAnUpdate(t *testing.T) {
	opts := uninstallOpts(t)
	runner := &recordingRunner{answer: func(args []string) (string, error) {
		if slices.Equal(args, []string{"is-active", UpdateServiceUnit}) {
			return "activating", errors.New("exit status 3")
		}
		return "", nil
	}}
	opts.run = runner.run
	opts.Yes, opts.NonInteractive = true, true
	config := writeFile(t, opts.ConfigDir, "zoomies.yaml", "")
	writeFile(t, opts.helperUnitDir, UpdatePathUnit, "[Path]\n")
	writeFile(t, opts.helperUnitDir, UpdateServiceUnit, "[Service]\n")
	err := Uninstall(context.Background(), opts)
	if err == nil || !strings.Contains(err.Error(), "running an update now") {
		t.Fatalf("want the uninstall refused while an update runs, got: %v", err)
	}
	if !exists(config) || !exists(filepath.Join(opts.helperUnitDir, UpdatePathUnit)) {
		t.Error("a refused uninstall removed something")
	}
	if !runner.ran("systemctl", "disable", "--now", UpdatePathUnit) {
		t.Errorf("the trigger should be off while the operator waits: %v", runner.lines())
	}
	if runner.ran("systemctl", "stop", UpdateServiceUnit) {
		t.Errorf("the running update was stopped: %v", runner.lines())
	}
}

package installer

import (
	"bytes"
	"context"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/backup"
	"github.com/eyupio/zoomies/internal/config"
)

// An upgrade changes a database that may have taken migrations, so a step of
// its own takes a copy through the same package the schedule uses, before the
// binary is replaced, and holds that copy to the checks a restore would: a
// backup nobody opened is a backup nobody knows.
func TestABackupIsTakenAndVerifiedBeforeTheUpgrade(t *testing.T) {
	opts, _, volume := controllerFixture(t, map[string]string{"agent.embedded": "true"})
	fakeVolume(&opts, volume, nil)
	opts.socketGroup = func(string) int { return 998 }
	var out bytes.Buffer
	opts.Out = &out

	dir, err := BackupBeforeUpgrade(context.Background(), opts)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(out.String(), "Backed up the database as") {
		t.Fatalf("the step did not say it backed up:\n%s", out.String())
	}
	// The helper reads the copy's directory from a marked line of its own.
	if !strings.Contains(out.String(), engineResultMarker+"backup="+dir) {
		t.Fatalf("the copy was not reported to the helper:\n%s", out.String())
	}
	root := filepath.Join(volume, backup.DefaultDirName)
	entries, err := backup.List(root)
	if err != nil || len(entries) != 1 {
		t.Fatalf("backups = %+v, err = %v", entries, err)
	}
	if entries[0].Source != backup.SourceUpgrade {
		t.Fatalf("source = %q, want %q", entries[0].Source, backup.SourceUpgrade)
	}
	if dir != entries[0].Dir {
		t.Fatalf("returned %q, want %q", dir, entries[0].Dir)
	}
	verified, err := backup.Verify(context.Background(), root, entries[0].ID)
	if err != nil || !verified.OK {
		t.Fatalf("verify = %+v, err = %v", verified, err)
	}
}

// A copy that cannot be taken fails the step: the caller runs it before the
// binary is replaced, so failing here is what leaves the host as it was.
func TestACopyThatCannotBeTakenFailsTheStep(t *testing.T) {
	opts, _, volume := controllerFixture(t, nil)
	fakeVolume(&opts, volume, nil)
	opts.socketGroup = func(string) int { return 998 }
	var out bytes.Buffer
	opts.Out = &out
	// A file where the backups directory must be created makes the copy fail
	// for the same reason a full disk or a bad path would.
	if err := os.WriteFile(filepath.Join(volume, backup.DefaultDirName), []byte("not a directory"), 0o600); err != nil {
		t.Fatal(err)
	}
	if _, err := BackupBeforeUpgrade(context.Background(), opts); err == nil {
		t.Fatal("a copy that could not be taken reported success")
	}
}

// A database path that cannot be resolved is not the same as a database that
// is not there: the first has something to lose and no way to copy it, so the
// step refuses rather than restarting into a migration nothing protected.
func TestTheCopyStopsWhenTheDatabaseCannotBeFound(t *testing.T) {
	opts, _, _ := controllerFixture(t, nil)
	fakeVolume(&opts, "", errors.New("the volume could not be inspected"))
	opts.socketGroup = func(string) int { return 998 }
	var out bytes.Buffer
	opts.Out = &out

	_, err := BackupBeforeUpgrade(context.Background(), opts)
	if err == nil || !strings.Contains(err.Error(), "could not read this deployment's settings") {
		t.Fatalf("error = %v", err)
	}
}

// A container's configuration speaks in the container's paths. An absolute
// backup directory under its state directory is the mounted volume, which on
// this host is the directory holding the database; anywhere else has no host
// path and is refused rather than written to the host's own /var/lib.
func TestPreUpgradeBackupDirTranslatesAContainerPath(t *testing.T) {
	cfg := config.Default()
	cfg.Backup.Directory = ContainerStateDir + "/upgrades"
	got, err := preUpgradeBackupDir(cfg, "/host/volume/zoomies.db", true)
	if err != nil || got != filepath.Join("/host/volume", "upgrades") {
		t.Fatalf("got %q, err = %v", got, err)
	}

	cfg.Backup.Directory = "/etc/zoomies/backups"
	if _, err := preUpgradeBackupDir(cfg, "/host/volume/zoomies.db", true); err == nil {
		t.Fatal("an absolute container path outside the state directory was accepted")
	}
	// A native path is the host's own, so an absolute one is absolute on
	// whichever host this is, and comes back unchanged.
	native := filepath.Join(t.TempDir(), "backups")
	cfg.Backup.Directory = native
	if got, err := preUpgradeBackupDir(cfg, filepath.Join(ContainerStateDir, "zoomies.db"), false); err != nil || got != native {
		t.Fatalf("a native absolute path = %q, err = %v", got, err)
	}
}

package installer

import (
	"bytes"
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"runtime"
	"strings"
	"testing"
)

func TestAnUnchangedImageKeepsTheControllerContainer(t *testing.T) {
	for _, deployment := range []Deployment{DeploymentCompose, DeploymentDocker} {
		t.Run(string(deployment), func(t *testing.T) {
			opts, rec := upgradeFixture(t, deployment)
			rec.Mode = ModeController
			var out bytes.Buffer
			opts.Out = &out
			var calls []string
			opts.run = func(_ context.Context, name string, args ...string) (string, error) {
				line := name + " " + strings.Join(args, " ")
				calls = append(calls, line)
				switch {
				case strings.Contains(line, "image inspect"), strings.Contains(line, "{{.Image}}"):
					return "sha256:current", nil
				case strings.Contains(line, "{{.State.Running}}"):
					return "true", nil
				}
				return "", nil
			}
			p := &upgradePlan{opts: opts, record: rec, image: opts.Image}
			var err error
			if deployment == DeploymentCompose {
				err = p.upgradeCompose(context.Background())
			} else {
				// No Docker API client is needed on this path: stopping or
				// replacing the existing container would fail this test.
				err = p.upgradeDocker(context.Background())
			}
			if err != nil {
				t.Fatal(err)
			}
			joined := strings.Join(calls, "\n")
			if !strings.Contains(joined, " pull ") || strings.Contains(joined, " up ") {
				t.Fatalf("upgrade must pull without recreating the container: %s", joined)
			}
			if !strings.Contains(out.String(), "keeping the running container") {
				t.Fatalf("output = %q, want the skipped restart explained", out.String())
			}
			stored, ok := ReadDeploymentRecord(opts.ConfigDir)
			if !ok || stored.Image != opts.Image {
				t.Fatalf("new image reference was not remembered: %+v", stored)
			}
			env, err := ParseEnvFile(rec.EnvFile)
			if err != nil || env["ZOOMIES_IMAGE"] != opts.Image || env["CUSTOM_SETTING"] != "leave me alone" {
				t.Fatalf("environment = %v, %v", env, err)
			}
			// Windows reports every file as 0666, so there is no mode to keep.
			if info, err := os.Stat(rec.EnvFile); err != nil || (runtime.GOOS != "windows" && info.Mode().Perm() != 0600) {
				t.Fatalf("environment permissions changed: %v, %v", info, err)
			}
		})
	}
}

func TestDockerUpgradeRestoresTheOldContainerWhenTheReplacementCannotStart(t *testing.T) {
	for _, fail := range []bool{false, true} {
		t.Run(map[bool]string{false: "success", true: "failed start"}[fail], func(t *testing.T) {
			var calls []string
			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				path := r.URL.Path
				calls = append(calls, r.Method+" "+path+"?"+r.URL.RawQuery)
				switch {
				case strings.HasSuffix(path, "/zoomies/json"):
					_ = json.NewEncoder(w).Encode(map[string]any{"Id": "old", "Name": "/zoomies", "Config": map[string]any{"Image": stockAgentRepository + ":old"}, "HostConfig": map[string]any{"AutoRemove": false}, "State": map[string]any{"Running": true}})
				case strings.HasSuffix(path, "/zoomies-before-upgrade/json"):
					w.WriteHeader(404)
				case strings.HasSuffix(path, "/containers/create"):
					w.WriteHeader(201)
					_, _ = w.Write([]byte(`{"Id":"new"}`))
				case strings.HasSuffix(path, "/new/start") && fail:
					w.WriteHeader(500)
					_, _ = w.Write([]byte(`{"message":"cannot start"}`))
				case strings.HasSuffix(path, "/new/json"):
					_, _ = w.Write([]byte(`{"Id":"new","State":{"Running":true}}`))
				default:
					w.WriteHeader(204)
				}
			}))
			defer server.Close()
			opts, rec := upgradeFixture(t, DeploymentDocker)
			opts.DockerHost = server.URL
			opts.run = func(context.Context, string, ...string) (string, error) { return "", nil }
			err := Upgrade(context.Background(), opts)
			if (err != nil) != fail {
				t.Fatalf("fail=%v: %v", fail, err)
			}
			all := strings.Join(calls, "\n")
			if !strings.Contains(all, "/old/stop?t=1200") || !strings.Contains(all, "name=zoomies-before-upgrade") {
				t.Fatalf("missing graceful replacement: %s", all)
			}
			if fail {
				if !strings.Contains(all, "/old/rename?name=zoomies") || !strings.Contains(all, "/old/start?") || !strings.Contains(all, "/new?force=1&v=0") {
					t.Fatalf("rollback missing: %s", all)
				}
				for _, call := range calls {
					if strings.HasPrefix(call, "DELETE ") && strings.Contains(call, "/containers/old?") {
						t.Fatal("removed rollback container")
					}
				}
			} else if !strings.Contains(all, "/old?v=0") {
				t.Fatalf("old container not cleaned up safely: %s", all)
			}
			stored, _ := ReadDeploymentRecord(opts.ConfigDir)
			if fail && stored.Image != rec.Image {
				t.Fatal("failed upgrade recorded as successful")
			}
		})
	}
}

package installer

import (
	"context"
	"errors"
	"fmt"
	"io"
	"path/filepath"
	"slices"
	"strconv"
	"strings"

	"github.com/eyupio/zoomies/internal/config"
)

// noSystemdForHelper is the refusal on a host that systemd does not run: the
// helper is a pair of systemd units, and nothing else could start it.
const noSystemdForHelper = `the update helper is a pair of systemd units, and this host does not run systemd; update it by hand with "sudo zoomies upgrade"`

// UpdateHelperExplained says what the update helper is for, wherever it is
// offered or described: the upgrade's, init's and the join's question, the hint
// after a no, the answer file, the help of "zoomies updates helper install" and
// the pages that describe the offer. It is one sentence for the controller's host
// and an agent's alike, because the web UI updates both, and a test finds every
// place by it, so a release that changes what the helper is for changes them all.
const UpdateHelperExplained = "The update helper runs `zoomies upgrade` as root for a validated request, so that the web UI can update this host (and on the controller's host, `zoomies updates apply` can too). Only the host's owner installs it, and `sudo zoomies updates helper remove` takes it away."

// upgradeHelperHost is what the update helper question reads from the host.
type upgradeHelperHost struct {
	// systemdDir exists only while systemd is the init system.
	systemdDir string
	// unitDir and stateDir are where the helper's units and root's folder for
	// it are, which is what decides that the helper is installed.
	unitDir, stateDir string
	resolve           func(configDir string) (InstallHelperOptions, error)
}

// helperHostOr is the host the question reads from: the real one, or the
// stand-in a test gave.
func helperHostOr(stand *upgradeHelperHost) upgradeHelperHost {
	if stand != nil {
		return *stand
	}
	return upgradeHelperHost{systemdDir: "/run/systemd/system", unitDir: systemdUnitDir, stateDir: UpdateHelperStateDir, resolve: ResolveHelperInstall}
}

// helperPresent is whether the update helper is on this host, judged on what
// only root can write: its units and root's folder for it. The pointer beside
// the configuration is the service's to replace, so it decides nothing, and
// root must never conclude from a file the service could have written that the
// helper is there, or that it is not.
func helperPresent(unitDir, stateDir string) bool {
	return exists(filepath.Join(unitDir, UpdatePathUnit)) || exists(filepath.Join(unitDir, UpdateServiceUnit)) || exists(stateDir)
}

// helperOffer is one asking of the update helper question. The upgrade, the
// install and the join all put it, in the same words and with the same
// refusals, so what each of them does with an answer is decided here once.
//
// It is not part of what --yes approves. --yes accepts the deployment's
// additions in advance, and this is a grant of root to a request the service
// writes; only the person at the host, or --update-helper typed by them (or the
// answer file's update_helper, which they wrote), says yes to it. The upgrade
// the helper itself runs is never interactive and never passes either, so with
// the helper installed it asks nothing and says nothing.
type helperOffer struct {
	Out io.Writer
	In  io.Reader
	// ConfigDir is the deployment's configuration directory, which the retry
	// command names when it is not the default.
	ConfigDir string
	// Interactive is whether somebody is at a terminal to read a hint and answer
	// the question.
	Interactive bool
	// Requested is the helper asked for by name, without a question.
	Requested bool
	host      upgradeHelperHost
	run       commandRunner
	// noSharedFolder, when set, says whether this is a container that runs no
	// runners. Such a container does not mount the shared folder, so the helper
	// could only refuse it: asked for by name it gets that refusal in the
	// helper's words, and offered unasked it would be a question with no answer.
	// It is a function because the upgrade reads the deployment's settings to
	// know, and only a container has anything to read.
	noSharedFolder func(context.Context) bool
	// hold, when set, is asked once the helper could be installed here, and a
	// true stops the offer there. It has said why itself.
	hold func() bool
}

// offer asks, as a question of its own, whether this host may be made ready to
// be updated from the web UI, and installs the helper if the answer is yes.
//
// The question is asked only where it could be answered: on a systemd host,
// where the helper is not already installed, and for a service that can be
// resolved to an account other than root's. A refusal after a yes is reported
// and the caller goes on, since the host is no worse for not having the helper
// and the refusal is something to put right and retry.
func (o helperOffer) offer(ctx context.Context) {
	out, ui := o.Out, PaletteFor(o.Out)
	host := o.host
	if !exists(host.systemdDir) {
		if o.Requested {
			o.notAdded(noSystemdForHelper)
		}
		return
	}
	if helperPresent(host.unitDir, host.stateDir) {
		return
	}
	if !o.Requested && o.noSharedFolder != nil && o.noSharedFolder(ctx) {
		return
	}
	helper, err := host.resolve(o.ConfigDir)
	if err != nil {
		var nothingToServe helperNotApplicable
		switch {
		case o.Requested:
			o.notAdded(err)
		case o.Interactive && !errors.As(err, &nothingToServe):
			// Something the operator can put right, and somebody is there to read it.
			ui.Hint(out, "The update helper cannot be offered on this host: %v", err)
		}
		return
	}
	if o.hold != nil && o.hold() {
		return
	}
	switch {
	case o.Requested:
	case o.Interactive && o.In != nil:
		fmt.Fprintln(out, "Make this host ready to be updated from the web UI?")
		fmt.Fprintln(out, "  "+UpdateHelperExplained)
		fmt.Fprintln(out, "  It is a pair of systemd units ("+UpdatePathUnit+" and "+UpdateServiceUnit+"),")
		fmt.Fprintln(out, "  and a request names a release and nothing else. The account Zoomies runs as")
		fmt.Fprintln(out, "  ("+helper.Account+") can trigger an upgrade by writing a request.")
		if !askDefaultNo(o.In, out, "Add the update helper? [y/N] ") {
			o.skipped()
			return
		}
	default:
		o.skipped()
		return
	}
	helper.Out, helper.run = out, o.run
	ui.Doing(out, "Adding the update helper")
	if err := InstallUpdateHelper(ctx, helper); err != nil {
		o.notAdded(err)
	}
}

// offerUpdateHelper is the upgrade's asking. It comes after the layout review
// and before anything is pulled or restarted, and not in the run that is about
// to give the container its shared mount.
func (p *upgradePlan) offerUpdateHelper(ctx context.Context) {
	if !p.managesZoomiesUnits() {
		return
	}
	helperOffer{
		Out: p.opts.Out, In: p.opts.In, ConfigDir: p.opts.ConfigDir,
		Interactive: p.opts.Interactive, Requested: p.opts.UpdateHelper,
		host: helperHostOr(p.opts.helperHost), run: p.opts.run, hold: p.holdForSharedMount,
		noSharedFolder: func(ctx context.Context) bool {
			return p.record.Deployment.Containerised() && !p.settings(ctx).runsRunners(p.record.Mode)
		},
	}.offer(ctx)
}

// holdForSharedMount is whether the offer must wait for the restart that gives
// the running container its shared folder. The install would refuse it now with
// a sentence about runner-less containers; it gets the mount when it is
// recreated below, and then the install works.
func (p *upgradePlan) holdForSharedMount() bool {
	if !p.sharedMountComing {
		return false
	}
	ui, command := PaletteFor(p.opts.Out), helperInstallCommand(p.opts.ConfigDir)
	if p.sharedMountApplied {
		ui.Hint(p.opts.Out, "The update helper needs the shared folder mounted, which the restart below adds; run %s afterwards.", command)
	} else {
		ui.Hint(p.opts.Out, "The update helper needs the shared folder mounted, which the deployment additions above would give it; once they are added (sudo zoomies upgrade --yes), run %s.", command)
	}
	return true
}

// stepUpdateHelper is init's asking. It comes last, once the service is
// installed (a container: once it is up, and so has its shared mount) and the
// account it runs as can be read back from what was installed, and before the
// summary, which stays the last thing the operator reads.
func (i *Installer) stepUpdateHelper(ctx context.Context, p Plan) {
	helperOffer{
		Out: i.out, In: i.in, ConfigDir: p.ConfigDir,
		Interactive: i.interactive, Requested: i.updateHelperRequested(),
		host: helperHostOr(i.opts.helperHost), run: i.opts.run,
		noSharedFolder: func(context.Context) bool { return p.Deployment.Containerised() && !p.runsRunners() },
	}.offer(ctx)
}

// updateHelperRequested is the helper asked for by name: --update-helper, or an
// answer file that says update_helper: true. Nothing else is, --yes included.
func (i *Installer) updateHelperRequested() bool {
	return i.opts.UpdateHelper || (i.answers != nil && i.answers.UpdateHelper != nil && *i.answers.UpdateHelper)
}

// offerUpdateHelper is the join's asking, once the agent's service is
// installed. A join is a single-use token already spent and a host already
// enrolled, so nothing here may fail it.
func (o JoinOptions) offerUpdateHelper(ctx context.Context) {
	helperOffer{
		Out: o.Out, In: o.In, ConfigDir: o.configDir(),
		Interactive: o.Interactive && !o.NonInteractive, Requested: o.UpdateHelper,
		host: helperHostOr(o.helperHost), run: o.run,
	}.offer(ctx)
}

// managesZoomiesUnits is whether the upgrade is of a deployment the helper can
// update: a container, or the zoomies controller or agent unit. A private
// provider's executable upgrades through its own unit, which the helper does
// not serve.
func (p *upgradePlan) managesZoomiesUnits() bool {
	if p.record.Deployment.Containerised() {
		return true
	}
	return !p.launchd && (slices.Contains(p.nativeUnits, UnitController) || slices.Contains(p.nativeUnits, UnitAgent))
}

// helperInstallCommand is the command that adds the helper later. It names the
// configuration directory when the run was against another than the default,
// because the bare command would look at the wrong deployment.
func helperInstallCommand(configDir string) string {
	command := "sudo zoomies updates helper install"
	if configDir != "" && configDir != config.ConfigDir() {
		if strings.ContainsAny(configDir, " \t") {
			configDir = strconv.Quote(configDir)
		}
		command += " --config-dir " + configDir
	}
	return command
}

func (o helperOffer) skipped() {
	PaletteFor(o.Out).Hint(o.Out, "The update helper was not added. %s", UpdateHelperExplained)
	fmt.Fprintln(o.Out, "Add later: "+helperInstallCommand(o.ConfigDir))
}

// notAdded reports a refusal in the helper's own words. It is a warning and not
// an error: the host is no worse for it, and what was being done goes on.
func (o helperOffer) notAdded(reason any) {
	ui := PaletteFor(o.Out)
	ui.Warn(o.Out, "The update helper was not added: %v", reason)
	ui.Hint(o.Out, "Everything else goes on without it. Once that is put right, add it with: %s", helperInstallCommand(o.ConfigDir))
}

// helperNotApplicable marks a host the helper has nothing to serve: a service
// that runs as root, or no zoomies service at all. The upgrade says nothing
// about the helper there, where any other reason it cannot be resolved is
// something to tell the person at the terminal.
type helperNotApplicable struct{ error }

// askDefaultNo reads one answer to a [y/N] question: only y or yes is a yes,
// and an empty line or an input that ends first is a no.
func askDefaultNo(in io.Reader, out io.Writer, question string) bool {
	answer, ok := readAnswer(in, out, question)
	if !ok {
		return false
	}
	return slices.Contains([]string{"y", "yes"}, strings.ToLower(answer))
}

package installer

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"runtime"
	"strings"
)

var proxmoxKey = regexp.MustCompile(`^[0-9a-f]{12}$`)

// Gateways have private executables so replacing the runner binary alone would
// leave them behind. Upgrade only installations whose systemd executable agrees
// with their dedicated state directory. Never touch credentials or identities.
func (p *upgradePlan) upgradeProxmoxGateways(ctx context.Context) error {
	if runtime.GOOS != "linux" {
		return nil
	}
	root := p.opts.proxmoxRoot
	if root == "" {
		root = "/var/lib/zoomies-proxmox"
	}
	entries, err := os.ReadDir(root)
	if os.IsNotExist(err) {
		return nil
	}
	if err != nil {
		return err
	}
	for _, entry := range entries {
		if !entry.IsDir() || !proxmoxKey.MatchString(entry.Name()) {
			continue
		}
		target := filepath.Join(root, entry.Name(), "zoomies")
		unit := "zoomies-proxmox-" + entry.Name() + ".service"
		start, err := p.opts.run(ctx, "systemctl", "show", unit, "--property=ExecStart", "--value")
		if err != nil {
			return fmt.Errorf("installer: inspect %s: %w", unit, err)
		}
		if !strings.Contains(start, "path="+target+" ;") && !strings.Contains(start, "path="+target+";") {
			continue
		}
		if p.opts.Check {
			PaletteFor(p.opts.Out).Hint(p.opts.Out, "Will update %s", unit)
			continue
		}
		lock, err := os.OpenFile(filepath.Join(root, entry.Name(), "setup.lock"), os.O_CREATE|os.O_RDWR, 0600)
		if err != nil {
			return err
		}
		defer lock.Close()
		unlock, err := tryLockSetup(lock)
		if err != nil {
			return fmt.Errorf("installer: %s is being configured; retry the upgrade when setup finishes", unit)
		}
		defer unlock()
		binary, err := os.ReadFile(p.opts.BinaryPath)
		if err != nil {
			return err
		}
		if err := os.WriteFile(target+".new", binary, 0700); err != nil {
			return err
		}
		if err := os.Rename(target+".new", target); err != nil {
			return err
		}
		PaletteFor(p.opts.Out).Doing(p.opts.Out, "Updating %s", unit)
		for _, args := range [][]string{{"restart", unit}, {"is-active", "--quiet", unit}} {
			if _, err := p.opts.run(ctx, "systemctl", args...); err != nil {
				return fmt.Errorf("installer: %s could not restart; rerun the upgrade: %w", unit, err)
			}
		}
	}
	return nil
}

package installer

import (
	"context"
	"errors"
	"io"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
)

func TestProxmoxGatewayUpgradePreservesIdentityAndPreviews(t *testing.T) {
	// Gateways are systemd units, so the upgrade deliberately does nothing off
	// Linux; there is nothing for this test to observe on Windows or macOS.
	if runtime.GOOS != "linux" {
		t.Skip("Proxmox gateways exist only on Linux hosts")
	}
	root := t.TempDir()
	dir := filepath.Join(root, "0123456789ab")
	if err := os.Mkdir(dir, 0700); err != nil {
		t.Fatal(err)
	}
	target := filepath.Join(dir, "zoomies")
	for name, value := range map[string]string{"zoomies": "old", "credential": "saved-secret", "gateway.json": "saved-identity", "completed-receipt": "connected"} {
		if err := os.WriteFile(filepath.Join(dir, name), []byte(value), 0600); err != nil {
			t.Fatal(err)
		}
	}
	source := filepath.Join(t.TempDir(), "zoomies")
	if err := os.WriteFile(source, []byte("new"), 0700); err != nil {
		t.Fatal(err)
	}
	var calls []string
	fail := false
	p := &upgradePlan{opts: UpgradeOptions{BinaryPath: source, proxmoxRoot: root, Out: io.Discard, run: func(_ context.Context, name string, args ...string) (string, error) {
		line := name + " " + strings.Join(args, " ")
		calls = append(calls, line)
		if len(args) > 0 && args[0] == "show" {
			return "path=" + target + " ;", nil
		}
		if fail {
			return "", errors.New("restart failed")
		}
		return "", nil
	}}}
	if runtime.GOOS != "linux" {
		// A gateway is a systemd unit, so off Linux the upgrade promises to leave
		// everything alone rather than to replace a binary it cannot restart.
		if err := p.upgradeProxmoxGateways(context.Background()); err != nil {
			t.Fatal(err)
		}
		if b, _ := os.ReadFile(target); string(b) != "old" || len(calls) != 0 {
			t.Fatalf("an upgrade off Linux touched a gateway: binary %q, commands %v", b, calls)
		}
		return
	}
	p.opts.Check = true
	if err := p.upgradeProxmoxGateways(context.Background()); err != nil {
		t.Fatal(err)
	}
	b, _ := os.ReadFile(target)
	if string(b) != "old" || strings.Contains(strings.Join(calls, "\n"), "restart") {
		t.Fatal("preview changed gateway")
	}
	p.opts.Check = false
	if err := p.upgradeProxmoxGateways(context.Background()); err != nil {
		t.Fatal(err)
	}
	b, _ = os.ReadFile(target)
	if string(b) != "new" {
		t.Fatal("gateway binary not replaced")
	}
	for name, value := range map[string]string{"credential": "saved-secret", "gateway.json": "saved-identity", "completed-receipt": "connected"} {
		b, err := os.ReadFile(filepath.Join(dir, name))
		if err != nil || string(b) != value {
			t.Fatalf("changed %s", name)
		}
	}
	if !strings.Contains(strings.Join(calls, "\n"), "is-active --quiet zoomies-proxmox-0123456789ab.service") {
		t.Fatal("restart not verified")
	}
	fail = true
	if err := p.upgradeProxmoxGateways(context.Background()); err == nil {
		t.Fatal("restart failure hidden")
	}
}

package installer

import (
	"bytes"
	"context"
	"errors"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// rollbackFixture is a native controller that does not answer until its
// service is restarted, with the previous release kept beside the installed
// one. It returns the plan, the binary path and a pointer to whether the
// restart has happened.
func rollbackFixture(t *testing.T) (*upgradePlan, string, *bool, *bytes.Buffer) {
	t.Helper()
	dir := t.TempDir()
	bin := filepath.Join(dir, "zoomies")
	if err := os.WriteFile(bin, []byte("new build"), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(bin+PreviousSuffix, []byte("old build"), 0o755); err != nil {
		t.Fatal(err)
	}
	answering := false
	var out bytes.Buffer
	p := &upgradePlan{
		opts: UpgradeOptions{
			Out: &out, BinaryPath: bin,
			serveTimeout: 20 * time.Millisecond, servePoll: time.Millisecond, progressEvery: time.Nanosecond,
			run: func(_ context.Context, name string, args ...string) (string, error) {
				if name == "systemctl" && slices.Contains(args, "restart") {
					answering = true
				}
				return "", nil
			},
		},
		record:      DeploymentRecord{Deployment: DeploymentNative, Mode: ModeController},
		nativeUnits: []string{"zoomies.service"}, unit: "zoomies.service",
	}
	return p, bin, &answering, &out
}

func failingCheck(answering *bool) *serveCheck {
	return &serveCheck{
		what: "the controller",
		probe: func(context.Context) error {
			if *answering {
				return nil
			}
			return errors.New("connection refused")
		},
		stopped: func(context.Context) string { return "" },
		latest:  func(context.Context) string { return "" },
	}
}

// The whole point of a rollback is that the host ends on what it ran: a
// controller that never answers, having migrated nothing, is put back.
func TestAControllerThatDoesNotAnswerIsPutBackWhenNothingMigrated(t *testing.T) {
	p, bin, answering, out := rollbackFixture(t)
	err := p.waitServing(context.Background(), failingCheck(answering))
	if err == nil || !strings.Contains(err.Error(), "previous release is running again") {
		t.Fatalf("error = %v", err)
	}
	if b, _ := os.ReadFile(bin); string(b) != "old build" {
		t.Fatalf("binary = %q, want the previous release back", b)
	}
	if !strings.Contains(out.String(), "putting the previous release back") {
		t.Fatalf("the rollback was not said:\n%s", out.String())
	}
	// The helper reads that this failure was undone from a marked line of its own.
	if !strings.Contains(out.String(), engineResultMarker+"rolled_back=true") {
		t.Fatalf("the rollback was not reported to the helper:\n%s", out.String())
	}
}

// Migrations run one way: an older release cannot open a database a newer one
// has moved on, so the binary must not be put back over it. The copy taken
// before the migration is named instead.
func TestAMigratedDatabaseIsNotRolledBackOnto(t *testing.T) {
	p, bin, answering, _ := rollbackFixture(t)
	dbDir := filepath.Join(t.TempDir(), "data")
	copyDir := filepath.Join(dbDir, store.PreMigrationDir, "zoomies-20300101-000000")
	if err := os.MkdirAll(copyDir, 0o700); err != nil {
		t.Fatal(err)
	}
	p.dbPath = filepath.Join(dbDir, "zoomies.db")
	p.beforeMigrate = ""

	err := p.waitServing(context.Background(), failingCheck(answering))
	if err == nil || !strings.Contains(err.Error(), copyDir) || !strings.Contains(err.Error(), "not put back") {
		t.Fatalf("error = %v", err)
	}
	if *answering {
		t.Fatal("the service was restarted although the database had migrated")
	}
	if b, _ := os.ReadFile(bin); string(b) != "new build" {
		t.Fatalf("binary = %q, want it left as the new release", b)
	}
}

// A native controller with no kept previous binary, and a container whose
