package installer

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// An upgrade used to call itself complete the moment the new container was
// running. But a controller does not serve until its migrations have run, and
// one that grows with the jobs table can take minutes -- so an operator was
// told the upgrade had finished while their site answered nothing, with no
// sign of why. The upgrade now waits for the controller to answer, and says
// what it is doing while it waits.

const (
	// upgradeServeTimeout is how long a controller may take to answer after
	// it restarts. It is long on purpose: a migration on a large database is
	// slow, not broken, and stopping it half way is the one thing that would
	// make it worse.
	upgradeServeTimeout = 30 * time.Minute
	upgradeServePoll    = 2 * time.Second
	// upgradeProgressEvery is how often the latest log line is echoed while
	// the controller is still starting, so a long wait is visibly progress.
	upgradeProgressEvery = 30 * time.Second
)

// serveCheck is how the upgrade learns whether the controller is serving. A
// nil check means there is nothing to wait for: an agent serves nothing, and
// a container with its health check turned off offers no way to ask.
type serveCheck struct {
	what string
	// probe answers nil once the controller is serving.
	probe func(ctx context.Context) error
	// stopped says why the service is no longer running, or "" while it is.
	stopped func(ctx context.Context) string
	// latest is the controller's most recent log line, echoed while waiting.
	latest func(ctx context.Context) string
}

// serveCheck is worked out before the service restarts: a native controller's
// listener comes from its settings, and those are read from its database,
// which the new process may be migrating a moment later.
func (p *upgradePlan) serveCheck(ctx context.Context) *serveCheck {
	if p.record.Deployment.Containerised() && p.record.Mode == ModeAgent {
		return nil
	}
	if p.record.Deployment.Containerised() {
		return p.containerServeCheck()
	}
	// A native host may have no deployment record; the unit found is then
	// what says which half it runs.
	if p.launchd || p.unit == UnitAgent {
		return nil
	}
	// The listener is a stored setting. Without the database to read it
	// from, the address in the file or the default is a guess, and waiting
	// on a guess is a wait that can only time out.
	s := p.settings(ctx)
	if !s.read {
		return nil
	}
	target, client := nativeHealthTarget(s.cfg)
	if target == "" {
		return nil
	}
	return &serveCheck{
		what: target,
		probe: func(ctx context.Context) error {
			return probeHealth(ctx, client, target)
		},
		stopped: func(ctx context.Context) string {
			if _, err := p.opts.run(ctx, "systemctl", "is-active", "--quiet", p.unit); err != nil {
				return p.unit + " is not active"
			}
			return ""
		},
		latest: func(ctx context.Context) string {
			out, _ := p.opts.run(ctx, "journalctl", "--unit", p.unit, "--lines", "1", "--output", "cat", "--no-pager")
			return out
		},
	}
}

// containerServeCheck runs the container's own health check -- the command the
// Compose file or the image declares -- in the container, now, rather than
// waiting up to its interval for the runtime's next scheduled run of it.
func (p *upgradePlan) containerServeCheck() *serveCheck {
	name := containerOr(p.record)
	return &serveCheck{
		what: "the " + name + " container's health check",
		probe: func(ctx context.Context) error {
			out, err := p.docker(ctx, "inspect", "--format", "{{json .Config.Healthcheck}}", name)
			if err != nil {
				return err
			}
			cmd, ok := healthCommand(out)
			if !ok {
				return errNoHealthCheck
			}
			_, err = p.docker(ctx, append([]string{"exec", name}, cmd...)...)
			return err
		},
		stopped: func(ctx context.Context) string {
			out, err := p.docker(ctx, "inspect", "--format", "{{.State.Status}}", name)
			if err != nil {
				return "the " + name + " container could not be inspected: " + err.Error()
			}
			switch status := strings.TrimSpace(out); status {
			case "running", "":
				return ""
			default:
				return "the " + name + " container is " + status
			}
		},
		latest: func(ctx context.Context) string {
			out, _ := p.docker(ctx, "logs", "--tail", "1", name)
			return out
		},
	}
}

var errNoHealthCheck = errors.New("the container declares no health check")

// healthCommand turns a container's declared health check into the command to
// exec in it. It is false when there is none: no health check, or NONE.
func healthCommand(inspect string) ([]string, bool) {
	var hc struct{ Test []string }
	if err := json.Unmarshal([]byte(strings.TrimSpace(inspect)), &hc); err != nil || len(hc.Test) < 2 {
		return nil, false
	}
	switch hc.Test[0] {
	case "CMD":
		return hc.Test[1:], true
	case "CMD-SHELL":
		return []string{"/bin/sh", "-c", strings.Join(hc.Test[1:], " ")}, true
	}
	return nil, false
}

// nativeHealthTarget is the controller's own listener over loopback, and a
// client for it. Verification is off for the same reason it is at install: the
// certificate may be self-signed and the connection never leaves the host.
func nativeHealthTarget(cfg *config.Config) (string, *http.Client) {
	if cfg == nil {
		return "", nil
	}
	host, port, err := net.SplitHostPort(cfg.Server.Bind)
	if err != nil || port == "" {
		return "", nil
	}
	if host == "" || host == "0.0.0.0" || host == "::" {
		host = "127.0.0.1"
	}
	scheme := "http"
	client := &http.Client{Timeout: 5 * time.Second}
	if cfg.Server.TLS.Mode != config.TLSOff {
		scheme = "https"
		client.Transport = insecureLoopbackTransport()
	}
	return fmt.Sprintf("%s://%s/healthz", scheme, net.JoinHostPort(host, port)), client
}

func probeHealth(ctx context.Context, client *http.Client, target string) error {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, target, nil)
	if err != nil {
		return err
	}
	resp, err := client.Do(req)
	if err != nil {
		return err
	}
	resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return fmt.Errorf("%s answered HTTP %d", target, resp.StatusCode)
	}
	return nil
}

// upgradeRollbackTimeout is how long the previous release is given to answer
// after it is put back. It has run here before, so it does not need the
// migration wait the new release is given.
const upgradeRollbackTimeout = 5 * time.Minute

// waitServing waits until the controller answers. When it does not, it decides
// what can be done: putting the previous release back is only safe when this
// upgrade did not migrate the database, because migrations run one way and an
// older binary cannot open a schema that has moved on.
func (p *upgradePlan) waitServing(ctx context.Context, check *serveCheck) error {
	if check == nil {
		return nil
	}
	timeout, poll, every := p.serveTimings()
	stop := p.answerWait(ctx, check, timeout, poll, every)
	if stop == nil {
		return nil
	}
	logs := p.logsHint()
	// The two ways the wait ends, without advice: what to do about it is the
	// decision below, and a message that named one path here would contradict
	// the path actually taken.
	var base string
	if stop.stoppedWhy != "" {
		base = fmt.Sprintf("the controller stopped after the upgrade: %s. See why with: %s", stop.stoppedWhy, logs)
	} else {
		base = fmt.Sprintf("the controller has not answered in %s (%v)", timeout, stop.lastErr)
	}
	if !p.canRollback() {
		if stop.stoppedWhy != "" {
			return errors.New(base + ". The upgrade was not rolled back: the new release may already have migrated the database, which an older one cannot open")
		}
		return fmt.Errorf("%s. It is still running, so it may still be migrating its database: follow it with %s, and do not stop it part way", base, logs)
	}
	if copy := p.migratedCopy(); copy != "" {
		return fmt.Errorf("%s. The previous release was not put back: this upgrade migrated the database, which an older release cannot open. The copy taken before the migration is %s; stop the service and restore it with: zoomies restore %s --replace", base, copy, copy)
	}
	return p.rollbackBinary(ctx, check, base)
}

// serveTimings is how long to wait for the controller, and how often to ask
// and to echo progress, with the defaults an unattended run leaves.
func (p *upgradePlan) serveTimings() (timeout, poll, every time.Duration) {
	timeout, poll, every = p.opts.serveTimeout, p.opts.servePoll, p.opts.progressEvery
	if timeout == 0 {
		timeout = upgradeServeTimeout
	}
	if poll == 0 {
		poll = upgradeServePoll
	}
	if every == 0 {
		every = upgradeProgressEvery
	}
	return timeout, poll, every
}

// waitStop is why a wait ended: the service was found stopped, or the deadline
// passed with the controller still not answering.
type waitStop struct {
	// stoppedWhy is why the service is not running, and "" while it is.
	stoppedWhy string
	// lastErr is the last probe's error, for the message a timeout writes.
	lastErr error
}

// answerWait polls until the controller answers, and returns nil when it does.
// A container with no health check is not waited on: nil is returned with a
// warning, because there is nothing to ask.
func (p *upgradePlan) answerWait(ctx context.Context, check *serveCheck, timeout, poll, every time.Duration) *waitStop {
	out := p.opts.Out
	logs := p.logsHint()
	start := time.Now()
	lastSaid := start
	announced := false
	for {
		err := check.probe(ctx)
		if err == nil {
			if announced {
				PaletteFor(out).Done(out, "The controller is answering (%s)", time.Since(start).Round(time.Second))
			}
			return nil
		}
		if errors.Is(err, errNoHealthCheck) {
			PaletteFor(out).Warn(out, "Container declares no health check; readiness is unverified")
			PaletteFor(out).Hint(out, "Follow startup: %s", logs)
			return nil
		}
		if why := check.stopped(ctx); why != "" {
			return &waitStop{stoppedWhy: why}
		}
		if !announced {
			PaletteFor(out).Doing(out, "Waiting for the controller to answer")
			PaletteFor(out).Hint(out, "Database migrations may take several minutes. Logs: %s", logs)
			announced = true
		}
		if time.Since(start) >= timeout {
			return &waitStop{lastErr: err}
		}
		if time.Since(lastSaid) >= every {
			lastSaid = time.Now()
			if line := logLineMessage(check.latest(ctx)); line != "" {
				fmt.Fprintf(out, "  still starting after %s; latest: %s\n", time.Since(start).Round(time.Second), line)
			} else {
				fmt.Fprintf(out, "  still starting after %s\n", time.Since(start).Round(time.Second))
			}
		}
		select {
		case <-ctx.Done():
			return &waitStop{lastErr: ctx.Err()}
		case <-time.After(poll):
		}
	}
}

// canRollback says whether the previous release can be put back: a native
// service that runs the binary selfUpdate replaced, and only when that binary
// was actually kept beside it. A container's service is its image, which this
// upgrade does not keep the one before.
func (p *upgradePlan) canRollback() bool {
	if p.record.Deployment.Containerised() || p.opts.BinaryPath == "" {
		return false
	}
	_, err := os.Stat(p.opts.BinaryPath + PreviousSuffix)
	return err == nil
}

// migratedCopy is the pre-migration copy this upgrade made, or "" when it
// migrated nothing: the newest copy beside the database, when it is newer than
// the one that was there before the restart.
func (p *upgradePlan) migratedCopy() string {
	if p.dbPath == "" {
		return ""
	}
	newest := store.NewestPreMigrationName(p.dbPath)
	if newest == "" || newest <= p.beforeMigrate {
		return ""
	}
	return filepath.Join(filepath.Dir(p.dbPath), store.PreMigrationDir, newest)
}

// rollbackBinary puts the previous release back, restarts the service and waits
// for it to answer. It returns an error either way: the upgrade failed, and
// this says whether the host was put back to what it ran.
func (p *upgradePlan) rollbackBinary(ctx context.Context, check *serveCheck, base string) error {
	PaletteFor(p.opts.Out).Warn(p.opts.Out, "The controller did not answer; putting the previous release back")
	if err := restorePreviousBinary(p.opts.BinaryPath); err != nil {
		return fmt.Errorf("%s; and the previous release could not be put back: %v", base, err)
	}
	if err := p.restartNative(ctx); err != nil {
		return fmt.Errorf("%s; the previous release was put back but the service would not restart: %v", base, err)
	}
	tctx, cancel := context.WithTimeout(context.WithoutCancel(ctx), upgradeRollbackTimeout)
	defer cancel()
	_, poll, every := p.serveTimings()
	if stop := p.answerWait(tctx, check, upgradeRollbackTimeout, poll, every); stop != nil {
		why := stop.stoppedWhy
		if why == "" {
			why = stop.lastErr.Error()
		}
		return fmt.Errorf("%s; the previous release was put back and did not answer either (%s). Restore the copy taken before the upgrade, if there is one, with: zoomies restore", base, why)
	}
	// For the helper alone: the previous release is running again, so the
	// failure was undone and the version it reported is not the one asked for
	// because of that, not because the engine did nothing.
	fmt.Fprintf(p.opts.Out, "%srolled_back=true\n", engineResultMarker)
	return fmt.Errorf("%s. The upgrade failed and the previous release is running again", base)
}

// logsHint is the command that shows this deployment's logs.
func (p *upgradePlan) logsHint() string {
	if p.record.Deployment.Containerised() {
		return "zoomies logs"
	}
	return "journalctl --unit " + p.unit + " --follow"
}

// logLineMessage makes one log line fit to echo: the message of a structured
// line, the line itself otherwise, and never a wall of text.
func logLineMessage(line string) string {
	line = strings.TrimSpace(line)
	if i := strings.LastIndexByte(line, '\n'); i >= 0 {
		line = strings.TrimSpace(line[i+1:])
	}
	// A Compose log line carries the service's name in front of it.
	if _, rest, ok := strings.Cut(line, "| "); ok && strings.HasPrefix(strings.TrimSpace(rest), "{") {
		line = strings.TrimSpace(rest)
	}
	var structured struct {
		Msg string `json:"msg"`
	}
	if strings.HasPrefix(line, "{") && json.Unmarshal([]byte(line), &structured) == nil && structured.Msg != "" {
		line = structured.Msg
	}
	if len(line) > 160 {
		line = line[:157] + "..."
	}
	return line
}

package installer

import (
	"bytes"
	"context"
	"errors"
	"net"
	"net/http"
	"net/http/httptest"
	"slices"
	"strings"
	"sync/atomic"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
)

const composeHealthCheck = `{"Test":["CMD","/usr/local/bin/zoomies","healthcheck","--url","http://127.0.0.1:8080"],"Interval":30000000000}`

// waitFixture is a Compose upgrade whose controller fails its health check
// `failures` times before it answers, and reports `status` while it does.
func waitFixture(t *testing.T, failures int, status, healthcheck string) (UpgradeOptions, *bytes.Buffer, *[]string) {
	t.Helper()
	opts, rec := upgradeFixture(t, DeploymentCompose)
	// A controller: an agent serves nothing, so it has nothing to wait for.
	rec.Mode, rec.Image = ModeSingle, stockControllerRepository+":v0.1"
	if _, err := WriteDeploymentRecord(opts.ConfigDir, rec); err != nil {
		t.Fatal(err)
	}
	opts.Mode, opts.Image = ModeSingle, stockControllerRepository+":v9.0"
	var out bytes.Buffer
	opts.Out = &out
	opts.servePoll = time.Millisecond
	opts.progressEvery = time.Nanosecond
	opts.serveTimeout = time.Minute
	var calls []string
	probes := 0
	opts.run = func(_ context.Context, name string, args ...string) (string, error) {
		line := name + " " + strings.Join(args, " ")
		calls = append(calls, line)
		switch {
		case strings.Contains(line, "config --images"):
			return opts.Image, nil
		case strings.Contains(line, "{{json .Config.Healthcheck}}"):
			return healthcheck, nil
		case name == "docker" && len(args) > 1 && args[0] == "exec":
			probes++
			if probes <= failures {
				return "", errors.New("connection refused")
			}
			return "", nil
		case strings.Contains(line, "{{.State.Status}}"):
			return status, nil
		case strings.Contains(line, "logs --tail 1"):
			return `zoomies  | {"time":"2026-09-24T18:47:19Z","level":"INFO","msg":"copied the database before migrating it","migrations":1}`, nil
		case name == "docker" && len(args) > 0 && args[0] == "inspect":
			return "true", nil
		}
		return "", nil
	}
	return opts, &out, &calls
}

// The upgrade used to report itself complete while the controller was still
// migrating its database and answering nothing, which reads as an outage with
// no explanation. It waits for the controller now, and says why it is waiting.
func TestAnUpgradeWaitsForTheControllerToAnswer(t *testing.T) {
	opts, out, calls := waitFixture(t, 3, "running", composeHealthCheck)
	if err := Upgrade(context.Background(), opts); err != nil {
		t.Fatal(err)
	}
	text := out.String()
	waiting := strings.Index(text, "Waiting for the controller to answer")
	answering := strings.Index(text, "The controller is answering")
	complete := strings.Index(text, "Upgrade complete")
	if waiting < 0 || answering < waiting || complete < answering {
		t.Fatalf("output does not wait, then answer, then complete:\n%s", text)
	}
	// The latest log line is what shows a slow start is a migration.
	if !strings.Contains(text, "latest: copied the database before migrating it") {
		t.Fatalf("output never said what the controller was doing:\n%s", text)
	}
	// The container's own check, run in it, rather than a guess at a URL.
	want := "docker exec zoomies /usr/local/bin/zoomies healthcheck --url http://127.0.0.1:8080"
	if !slices.Contains(*calls, want) {
		t.Fatalf("calls = %q, want %q", *calls, want)
	}
}

func TestAnAgentUpgradeDoesNotWait(t *testing.T) {
	opts, _ := upgradeFixture(t, DeploymentCompose)
	var out bytes.Buffer
	opts.Out = &out
	opts.run = func(_ context.Context, name string, args ...string) (string, error) {
		line := name + " " + strings.Join(args, " ")
		switch {
		case strings.Contains(line, "config --images"):
			return opts.Image, nil
		case name == "docker" && len(args) > 0 && args[0] == "exec":
			t.Errorf("an agent was health-checked: %s", line)
		case name == "docker" && len(args) > 0 && args[0] == "inspect":
			return "true", nil
		}
		return "", nil
	}
	if err := Upgrade(context.Background(), opts); err != nil {
		t.Fatal(err)
	}
}

func TestAControllerThatAnswersAtOnceIsNotWaitedOnAloud(t *testing.T) {
	opts, out, _ := waitFixture(t, 0, "running", composeHealthCheck)
	if err := Upgrade(context.Background(), opts); err != nil {
		t.Fatal(err)
	}
	if strings.Contains(out.String(), "Waiting for the controller") {
		t.Fatalf("output = %q, announced a wait there was no need for", out.String())
	}
}

// A controller that stops after the upgrade is an error, and one that must
// not be rolled back: it may already have migrated the database, which the
// older image cannot open.
func TestAControllerThatStopsAfterTheUpgradeFailsIt(t *testing.T) {
	opts, out, calls := waitFixture(t, 1000, "exited", composeHealthCheck)
	err := Upgrade(context.Background(), opts)
	if err == nil {
		t.Fatal("an upgrade whose controller stopped reported success")
	}
	for _, want := range []string{"container is exited", "zoomies logs", "not rolled back"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("error %q does not say %q", err, want)
		}
	}
	if strings.Contains(out.String(), "Upgrade complete") {
		t.Fatalf("output = %q, called the upgrade complete", out.String())
	}
	ups := 0
	for _, c := range *calls {
		if strings.Contains(c, " up -d ") {
			ups++
		}
	}
	if ups != 1 {
		t.Fatalf("the service was brought up %d times, want once and no rollback: %q", ups, *calls)
	}
}

func TestAControllerStillStartingAtTheDeadlineSaysNotToStopIt(t *testing.T) {
	opts, _, _ := waitFixture(t, 1000, "running", composeHealthCheck)
	opts.serveTimeout = 20 * time.Millisecond
	err := Upgrade(context.Background(), opts)
	if err == nil {
		t.Fatal("an upgrade whose controller never answered reported success")
	}
	for _, want := range []string{"has not answered", "still running", "do not stop it"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("error %q does not say %q", err, want)
		}
	}
}

func TestAContainerWithNoHealthCheckIsNotWaitedOn(t *testing.T) {
	opts, out, _ := waitFixture(t, 1000, "running", `{"Test":["NONE"]}`)
	if err := Upgrade(context.Background(), opts); err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(out.String(), "declares no health check") || !strings.Contains(out.String(), "Upgrade complete") {
		t.Fatalf("output = %q", out.String())
	}
}

func TestHealthCommandRunsWhatTheContainerDeclares(t *testing.T) {
	for _, tc := range []struct {
		inspect string
		want    []string
	}{
		{composeHealthCheck, []string{"/usr/local/bin/zoomies", "healthcheck", "--url", "http://127.0.0.1:8080"}},
		{`{"Test":["CMD-SHELL","curl -f http://localhost/"]}`, []string{"/bin/sh", "-c", "curl -f http://localhost/"}},
		{`{"Test":["NONE"]}`, nil},
		{`null`, nil},
		{``, nil},
	} {
		got, ok := healthCommand(tc.inspect)
		if ok != (tc.want != nil) || !slices.Equal(got, tc.want) {
			t.Errorf("healthCommand(%q) = %q, %v; want %q", tc.inspect, got, ok, tc.want)
		}
	}
}

func TestLogLineMessageEchoesTheMessage(t *testing.T) {
	for in, want := range map[string]string{
		`zoomies  | {"level":"INFO","msg":"applied database migration","migration":"0054"}`: "applied database migration",
		`{"msg":"copied the database"}`:             "copied the database",
		"first\nlistening on http://0.0.0.0:8080\n": "listening on http://0.0.0.0:8080",
		"":                       "",
		strings.Repeat("x", 400): strings.Repeat("x", 157) + "...",
	} {
		if got := logLineMessage(in); got != want {
			t.Errorf("logLineMessage(%q) = %q, want %q", in, got, want)
		}
	}
}

// A native controller is asked on its own listener, which is a stored setting:
// every interface is reached over loopback, and TLS means https.
func TestANativeControllerIsAskedOnItsListener(t *testing.T) {
	cfg := config.Default()
	cfg.Server.Bind = "0.0.0.0:9443"
	cfg.Server.TLS.Mode = config.TLSSelfSigned
	if target, _ := nativeHealthTarget(cfg); target != "https://127.0.0.1:9443/healthz" {
		t.Fatalf("target = %q", target)
	}

	var answering atomic.Bool
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/healthz" || !answering.Load() {
			w.WriteHeader(http.StatusServiceUnavailable)
			return
		}
		w.WriteHeader(http.StatusOK)
	}))
	t.Cleanup(srv.Close)
	cfg.Server.Bind = strings.TrimPrefix(srv.URL, "http://")
	cfg.Server.TLS.Mode = config.TLSOff
	target, client := nativeHealthTarget(cfg)
	if host, _, _ := net.SplitHostPort(cfg.Server.Bind); !strings.Contains(target, host) {
		t.Fatalf("target = %q, not the listener %s", target, cfg.Server.Bind)
	}
	if err := probeHealth(t.Context(), client, target); err == nil || !strings.Contains(err.Error(), "503") {
		t.Fatalf("probe of a controller not yet answering = %v", err)
	}
	answering.Store(true)
	if err := probeHealth(t.Context(), client, target); err != nil {
		t.Fatalf("probe of an answering controller = %v", err)
	}
}

package installer

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"runtime"
	"strings"

	"github.com/eyupio/zoomies/internal/backend"
)

const wslConfPath = "/etc/wsl.conf"

// runningUnderWSL is whether this Linux is a WSL distro. Its init is rarely
// systemd unless the operator turned that on, so a join or an upgrade that finds
// no service manager there has a specific, fixable reason to give instead of the
// generic one.
func runningUnderWSL() bool {
	if runtime.GOOS != "linux" {
		return false
	}
	b, err := os.ReadFile("/proc/sys/kernel/osrelease")
	return err == nil && osReleaseIsWSL(string(b))
}

// osReleaseIsWSL reads the kernel release string, which WSL2 builds name
// "...microsoft-standard-WSL2" and WSL1 names "...-Microsoft".
func osReleaseIsWSL(release string) bool {
	r := strings.ToLower(release)
	return strings.Contains(r, "microsoft") || strings.Contains(r, "wsl")
}

// wslServiceNotes says why an agent started by hand in a WSL distro stops with
// its terminal, and the two changes that keep it running. Turning systemd on is
// optional: without it the agent still works, it just lives and dies with the
// shell that started it.
func wslServiceNotes() []string {
	return []string{
		"this is a WSL distro without systemd, so the agent stops when its terminal closes.",
		"to keep it running, optionally turn systemd on: add this to /etc/wsl.conf",
		"  [boot]",
		"  systemd=true",
		"then run `wsl --shutdown` from Windows, reopen the distro and run the join again with a new token.",
		"WSL can still stop an idle distro; docs/hosts-and-pools.md (A host in WSL2) says how to keep it up.",
	}
}

// wslSystemdSetting reports whether conf already asks for systemd, so that an
// upgrade does not offer to write a line that is there and say, correctly, that
// what is missing is a restart of the distro.
func wslSystemdSetting(conf string) bool {
	section := ""
	for _, line := range strings.Split(conf, "\n") {
		line = strings.TrimSpace(line)
		switch {
		case strings.HasPrefix(line, "["):
			section = strings.ToLower(strings.Trim(line, "[] "))
		case section == "boot":
			k, v, ok := strings.Cut(line, "=")
			if ok && strings.EqualFold(strings.TrimSpace(k), "systemd") {
				return strings.EqualFold(strings.TrimSpace(v), "true")
			}
		}
	}
	return false
}

// withWSLSystemd returns conf with systemd=true under [boot], changing nothing
// else in it. A wsl.conf is often hand-written (automount, network, interop), so
// the line goes into the section that is there rather than a second [boot].
func withWSLSystemd(conf string) string {
	lines := strings.Split(conf, "\n")
	boot, end := -1, len(lines)
	for i, line := range lines {
		t := strings.TrimSpace(line)
		if !strings.HasPrefix(t, "[") {
			continue
		}
		if boot >= 0 {
			end = i
			break
		}
		if strings.EqualFold(strings.Trim(t, "[] "), "boot") {
			boot = i
		}
	}
	if boot < 0 {
		out := strings.TrimRight(conf, "\n")
		if out != "" {
			out += "\n\n"
		}
		return out + "[boot]\nsystemd=true\n"
	}
	for i := boot + 1; i < end; i++ {
		k, _, ok := strings.Cut(strings.TrimSpace(lines[i]), "=")
		if ok && strings.EqualFold(strings.TrimSpace(k), "systemd") {
			lines[i] = "systemd=true"
			return strings.Join(lines, "\n")
		}
	}
	lines = append(lines[:boot+1], append([]string{"systemd=true"}, lines[boot+1:]...)...)
	return strings.Join(lines, "\n")
}

// enableWSLSystemd writes systemd=true into the wsl.conf at path, keeping the
// file it replaces beside it the first time. It returns false when the file
// already asked for systemd.
func enableWSLSystemd(path string) (bool, error) {
	data, err := os.ReadFile(path)
	if err != nil && !errors.Is(err, fs.ErrNotExist) {
		return false, err
	}
	if wslSystemdSetting(string(data)) {
		return false, nil
	}
	if err == nil {
		if _, statErr := os.Stat(path + ".zoomies-bak"); errors.Is(statErr, fs.ErrNotExist) {
			if err := os.WriteFile(path+".zoomies-bak", data, 0o644); err != nil {
				return false, err
			}
		}
	}
	return true, os.WriteFile(path, []byte(withWSLSystemd(string(data))), 0o644)
}

// offerWSLSystemd explains an upgrade that found no service on a WSL distro and
// offers the fix: the agent there is most likely running by hand, so there is no
// unit to restart. It changes nothing under --check. The distro has to be
// restarted from Windows for the setting to take effect, which no process inside
// it can do, so the returned error always ends with that instruction.
func (p *upgradePlan) offerWSLSystemd() error {
	out := p.opts.Out
	conf := p.opts.wslConf
	if conf == "" {
		conf = wslConfPath
	}
	data, _ := os.ReadFile(conf)
	fmt.Fprintln(out, "This is a WSL distro and systemd is not running in it, so Zoomies has no service here to restart.")
	fmt.Fprintln(out, "An agent started by hand keeps running the old build until you stop it and start it again.")
	if wslSystemdSetting(string(data)) {
		return fmt.Errorf("installer: %s already turns systemd on, but this distro has not been restarted since; run `wsl --shutdown` from Windows, reopen the distro and run the upgrade again", conf)
	}
	if p.opts.Check {
		return fmt.Errorf("installer: no service was found; turn systemd on in %s ([boot] systemd=true), run `wsl --shutdown` from Windows and upgrade again", conf)
	}
	approved := p.opts.AssumeYes
	if !approved && p.opts.Interactive {
		approved = askApproval(p.opts.In, out, "Turn systemd on in "+conf+" now? [Y/n] ")
	}
	if !approved {
		return fmt.Errorf("installer: no service was found; to fix it, add `[boot]` and `systemd=true` to %s, run `wsl --shutdown` from Windows and upgrade again (or re-run this with --yes to have it written for you)", conf)
	}
	if _, err := enableWSLSystemd(conf); err != nil {
		if errors.Is(err, fs.ErrPermission) {
			return fmt.Errorf("installer: cannot write %s: %w; run the upgrade with sudo, or add `[boot]` and `systemd=true` to it yourself", conf, err)
		}
		return fmt.Errorf("installer: writing %s: %w", conf, err)
	}
	fmt.Fprintf(out, "Turned systemd on in %s (the previous file is kept as %s.zoomies-bak).\n", conf, conf)
	return fmt.Errorf("installer: systemd takes effect when the distro restarts: run `wsl --shutdown` from Windows, reopen the distro, then join this host with a new token (`zoomies agent join`) so the agent becomes a service, or upgrade again if it already is one")
}

// wslWithoutSystemd is whether an upgrade that found no service is on a WSL
// distro that cannot have one.
func (p *upgradePlan) wslWithoutSystemd() bool {
	isWSL, hasSystemd := p.opts.isWSL, p.opts.hasSystemd
	if isWSL == nil {
		isWSL = runningUnderWSL
	}
	if hasSystemd == nil {
		hasSystemd = backend.HasSystemd
	}
	return isWSL() && !hasSystemd()
}

package installer

import (
	"context"
	"fmt"
	"io"

	"github.com/eyupio/zoomies/internal/wsl"
)

// wslOffer is what an install, a join or an upgrade knows when it asks whether
// to set up WSL2 self-management.
type wslOffer struct {
	Out io.Writer
	In  io.Reader
	// Interactive is whether a person is at the terminal to answer. AssumeYes
	// is --yes, the operator's answer given in advance.
	Interactive bool
	AssumeYes   bool
	// Check changes nothing: it says what would be offered.
	Check bool
	// Binary is the zoomies binary the distro's boot command will run.
	Binary string
	// User is the account the agent runs as; empty reads it from the unit.
	User string

	// isWSL and sys stand in for the host, so a test never reads the real one.
	isWSL func() bool
	sys   wsl.System
}

// offerWSLSelfManagement says what a WSL2 distro needs to stay up and offers to
// do it. It does nothing anywhere else, and says nothing when everything is
// already in place. It is a best effort, never an error: the install or upgrade
// it follows has already succeeded, and a refusal here changes nothing about
// that. Nothing it does restarts a service or ends a process, so it is safe to
// offer while jobs are running.
func offerWSLSelfManagement(ctx context.Context, o wslOffer) {
	isWSL := o.isWSL
	if isWSL == nil {
		isWSL = runningUnderWSL
	}
	if !isWSL() {
		return
	}
	sys := o.sys
	if sys == nil {
		sys = wsl.OS{}
	}
	ui := PaletteFor(o.Out)
	opts := wsl.Options{Binary: o.Binary, User: o.User, DryRun: true}
	plan := wsl.Ensure(ctx, sys, opts)
	pending := plan.Pending()
	if len(plan.Steps) > 0 && plan.Steps[0].Status == wsl.StatusSkipped {
		return // the kernel says WSL but the process does not see WSL2: leave it be
	}
	if len(pending) == 0 {
		for _, w := range plan.Warnings() {
			ui.Warn(o.Out, "WSL2: %s: %s", w.Name, w.Detail)
		}
		if len(plan.Warnings()) == 0 {
			ui.Hint(o.Out, "WSL2: this distro already starts at boot and stays up")
		}
		return
	}

	fmt.Fprintln(o.Out)
	ui.Rule(o.Out, "WSL2")
	fmt.Fprintln(o.Out, "This is a WSL2 distro. WSL stops it when the last Windows session closes, which")
	fmt.Fprintln(o.Out, "stops the runners on it, and nothing starts it again after a reboot. Zoomies can:")
	for _, s := range pending {
		fmt.Fprintf(o.Out, "  - %s\n", s.Detail)
	}
	fmt.Fprintln(o.Out, "Nothing is restarted, so a job that is running is not touched. No password is asked for.")

	command := "sudo zoomies agent --wsl-ensure"
	switch {
	case o.Check:
		ui.Hint(o.Out, "No changes made. An install or upgrade offers this; or run: %s", command)
		return
	case o.AssumeYes:
	case o.Interactive:
		if !askApproval(o.In, o.Out, "Set this up now? [Y/n] ") {
			ui.Hint(o.Out, "Skipped. Run %s whenever you want it.", command)
			return
		}
	default:
		ui.Hint(o.Out, "Not set up, because nobody is here to ask. Run %s, or repeat this with --yes.", command)
		return
	}

	rep := wsl.Ensure(ctx, sys, wsl.Options{Binary: o.Binary, User: o.User})
	for _, s := range rep.Steps {
		switch s.Status {
		case wsl.StatusChanged:
			ui.Done(o.Out, "%s: %s", s.Name, s.Detail)
		case wsl.StatusWarn:
			ui.Warn(o.Out, "%s: %s", s.Name, s.Detail)
		}
	}
	if rep.Changed() {
		ui.Hint(o.Out, "A change to /etc/wsl.conf applies the next time the distro starts; nothing here restarts it.")
	}
}

package installer

import (
	"bytes"
	"context"
	"errors"
	"io/fs"
	"os"
	"strings"
	"testing"
)

// wslFake is a WSL2 distro with systemd and an installed agent unit, and no
// Windows interop, so only the in-distro steps are in play.
type wslFake struct {
	files map[string]string
	ran   []string
}

func newWSLFake() *wslFake {
	return &wslFake{files: map[string]string{
		"/etc/systemd/system/zoomies-agent.service": "[Service]\nUser=zoomies\n",
	}}
}

func (f *wslFake) GOOS() string { return "linux" }
func (f *wslFake) Getenv(k string) string {
	if k == "WSL_DISTRO_NAME" {
		return "Ubuntu"
	}
	return ""
}
func (f *wslFake) Geteuid() int                       { return 0 }
func (f *wslFake) MkdirAll(string, os.FileMode) error { return nil }
func (f *wslFake) Exists(p string) bool               { _, ok := f.files[p]; return ok }
func (f *wslFake) ReadFile(p string) ([]byte, error) {
	if s, ok := f.files[p]; ok {
		return []byte(s), nil
	}
	return nil, fs.ErrNotExist
}
func (f *wslFake) WriteFile(p string, d []byte, _ os.FileMode) error {
	f.files[p] = string(d)
	return nil
}
func (f *wslFake) Run(_ context.Context, name string, args ...string) ([]byte, error) {
	f.ran = append(f.ran, name+" "+strings.Join(args, " "))
	if name == "loginctl" {
		f.files["/var/lib/systemd/linger/"+args[1]] = ""
		return nil, nil
	}
	return nil, errors.New("not available")
}

func runOffer(t *testing.T, f *wslFake, o wslOffer, input string) string {
	t.Helper()
	var out bytes.Buffer
	o.Out, o.In = &out, strings.NewReader(input)
	o.Binary = "/usr/local/bin/zoomies"
	o.isWSL = func() bool { return true }
	o.sys = f
	offerWSLSelfManagement(context.Background(), o)
	return out.String()
}

func TestAnInteractiveInstallOffersWSLSelfManagementAndAppliesIt(t *testing.T) {
	f := newWSLFake()
	out := runOffer(t, f, wslOffer{Interactive: true}, "y\n")
	for _, want := range []string{"WSL2 distro", "boot.command", "linger", "Set this up now?", "Nothing is restarted"} {
		if !strings.Contains(out, want) {
			t.Errorf("output lacks %q:\n%s", want, out)
		}
	}
	if !strings.Contains(f.files["/etc/wsl.conf"], "agent --wsl-ensure") {
		t.Fatalf("wsl.conf was not written: %q", f.files["/etc/wsl.conf"])
	}
}

func TestDecliningTheWSLOfferChangesNothing(t *testing.T) {
	f := newWSLFake()
	out := runOffer(t, f, wslOffer{Interactive: true}, "n\n")
	if _, wrote := f.files["/etc/wsl.conf"]; wrote || len(f.ran) != 0 {
		t.Fatalf("declined, but the host was changed: %v", f.ran)
	}
	if !strings.Contains(out, "sudo zoomies agent --wsl-ensure") {
		t.Errorf("a decline should say how to do it later:\n%s", out)
	}
}

func TestWSLOfferWithNobodyToAskIsNotAppliedWithoutYes(t *testing.T) {
	f := newWSLFake()
	out := runOffer(t, f, wslOffer{}, "")
	if _, wrote := f.files["/etc/wsl.conf"]; wrote {
		t.Fatal("an unattended run wrote wsl.conf without --yes")
	}
	if !strings.Contains(out, "--yes") {
		t.Errorf("should say --yes does it:\n%s", out)
	}
	runOffer(t, f, wslOffer{AssumeYes: true}, "")
	if _, wrote := f.files["/etc/wsl.conf"]; !wrote {
		t.Fatal("--yes did not apply it")
	}
}

func TestWSLOfferUnderCheckOnlyDescribes(t *testing.T) {
	f := newWSLFake()
	out := runOffer(t, f, wslOffer{Check: true, Interactive: true, AssumeYes: true}, "y\n")
	if _, wrote := f.files["/etc/wsl.conf"]; wrote || len(f.ran) != 0 {
		t.Fatal("--check changed the host")
	}
	if !strings.Contains(out, "No changes made") {
		t.Errorf("output: %s", out)
	}
}

func TestWSLOfferIsSilentOffWSLAndQuietOnceDone(t *testing.T) {
	var out bytes.Buffer
	offerWSLSelfManagement(context.Background(), wslOffer{Out: &out, isWSL: func() bool { return false }})
	if out.Len() != 0 {
		t.Fatalf("spoke on a plain Linux host: %q", out.String())
	}
	f := newWSLFake()
	runOffer(t, f, wslOffer{AssumeYes: true}, "")
	again := runOffer(t, f, wslOffer{Interactive: true}, "y\n")
	if strings.Contains(again, "Set this up now?") {
		t.Fatalf("asked again once everything was in place:\n%s", again)
	}
}

package kennel

import (
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"slices"
	"strconv"
	"strings"
	"testing"
)

// The package is pure for the reason internal/scheduler is: a check that reads
// a clock, a database or the network cannot be tested by describing a world.
// So it may import the standard library's pure parts and nothing else, and it
// may not ask the time.
//
// If a change here is deliberate, this list is what has to change with it, and
// a reviewer is meant to see it do so.
var allowedImports = []string{
	"regexp", "slices", "sort", "strconv", "strings", "time",
}

func nonTestFiles(t *testing.T) []string {
	t.Helper()
	all, err := filepath.Glob("*.go")
	if err != nil {
		t.Fatal(err)
	}
	var out []string
	for _, f := range all {
		if !strings.HasSuffix(f, "_test.go") {
			out = append(out, f)
		}
	}
	if len(out) < 5 {
		t.Fatalf("found only %d source files; the test is looking in the wrong place", len(out))
	}
	return out
}

func TestTheEvaluatorImportsNothingImpure(t *testing.T) {
	fset := token.NewFileSet()
	for _, name := range nonTestFiles(t) {
		file, err := parser.ParseFile(fset, name, nil, parser.ImportsOnly)
		if err != nil {
			t.Fatal(err)
		}
		for _, imp := range file.Imports {
			path, _ := strconv.Unquote(imp.Path.Value)
			if !slices.Contains(allowedImports, path) {
				t.Errorf("%s imports %s; internal/kennel is pure and may import only %v", name, path, allowedImports)
			}
		}
	}
}

// "time" is allowed for its types. Asking it what time it is, or for a timer,
// is what makes a check depend on when it ran.
func TestTheEvaluatorNeverReadsAClock(t *testing.T) {
	forbidden := []string{"Now", "Since", "Until", "After", "AfterFunc", "Sleep", "Tick", "NewTicker", "NewTimer"}
	fset := token.NewFileSet()
	for _, name := range nonTestFiles(t) {
		file, err := parser.ParseFile(fset, name, nil, 0)
		if err != nil {
			t.Fatal(err)
		}
		ast.Inspect(file, func(n ast.Node) bool {
			sel, ok := n.(*ast.SelectorExpr)
			if !ok {
				return true
			}
			if id, ok := sel.X.(*ast.Ident); ok && id.Name == "time" && slices.Contains(forbidden, sel.Sel.Name) {
				t.Errorf("%s: time.%s -- the evaluator is handed the time in Snapshot.At", fset.Position(sel.Pos()), sel.Sel.Name)
			}
			return true
		})
	}
}

func TestTheEvaluatorTouchesNoFilesystemOrEnvironment(t *testing.T) {
	// os is not importable (see allowedImports), so this is belt and braces: the
	// directory has no other kind of source file either.
	entries, err := os.ReadDir(".")
	if err != nil {
		t.Fatal(err)
	}
	for _, e := range entries {
		if strings.HasSuffix(e.Name(), ".go") || e.IsDir() {
			continue
		}
		t.Errorf("unexpected file %s; the package holds Go source and nothing it could read at run time", e.Name())
	}
}

package kennel

import "time"

const (
	// UnservedWait is how long a job must have waited for a label no pool
	// serves before it counts. A job that is simply waiting for its pool to
	// scale up is not an unserved one, and the existing jobs.unmatched problem
	// already gives that case its own short grace.
	UnservedWait = 10 * time.Minute

	// DefaultJobLimit is how long GitHub lets a job run when it sets no
	// timeout-minutes.
	DefaultJobLimit = 360 * time.Minute

	// A job that GitHub stops at its limit is cancelled a moment after the
	// limit is reached, counted from when the job started. These bound "a
	// moment": a minute early for clock skew, two late for the cancellation.
	limitEarly = 1 * time.Minute
	limitLate  = 2 * time.Minute

	// LongJobFloor is the shortest job the collector hands over in
	// JobFacts.Long. It is well below the limit, so the evaluator, not the
	// collector, decides which jobs hit it.
	LongJobFloor = 5 * time.Hour

	// MatrixWait is how long a job of a matrix must have waited for a runner
	// before the matrix counts as held up by its pool. A pool that is merely
	// busy for a moment is not a pool that is too small.
	MatrixWait = 2 * time.Minute
)

func evalUnservedLabel(s *Snapshot) result {
	var n int
	var longest time.Duration
	for _, u := range s.Fleet.Jobs.Unserved {
		if u.Waited >= UnservedWait {
			n++
			longest = max(longest, u.Waited)
		}
	}
	if n == 0 {
		return result{applies: true}
	}
	return result{applies: true, findings: []Finding{{
		Code:     CodeUnservedLabel,
		Severity: SeverityWarning,
		Title:    "Jobs waited for a label no pool serves",
		Detail: count(n, "job", "jobs") + " waited more than " + span(UnservedWait) + " in the last 7 days for runners no pool here provides, " +
			"the longest for " + span(longest) + ". Such a job stays queued until a pool matches it or somebody cancels it.",
		Fix: "Add a pool that offers the label, or change the workflow's runs-on to a label a pool serves. " +
			"The Jobs page, filtered to unmatched jobs, lists each one.",
	}}}
}

func evalJobHitDefaultLimit(s *Snapshot) result {
	var n int
	for _, j := range s.Fleet.Jobs.Long {
		if j.Conclusion == "cancelled" &&
			j.Duration >= DefaultJobLimit-limitEarly && j.Duration <= DefaultJobLimit+limitLate {
			n++
		}
	}
	if n == 0 {
		return result{applies: true}
	}
	return result{applies: true, findings: []Finding{{
		Code:     CodeJobHitDefaultLimit,
		Severity: SeverityWarning,
		Title:    "A job ran until GitHub stopped it at six hours",
		Detail: "GitHub cancels a job that sets no timeout-minutes after 360 minutes, and the job holds its runner for all of that time. " +
			count(n, "job", "jobs") + " did this in the last " + forDays(s.Fleet.Window) + ".",
		Fix: "Set timeout-minutes on the job, a little above its longest healthy run, so a hung job frees its runner sooner.",
	}}}
}

func evalMatrixExceedsPool(s *Snapshot) result {
	type held struct {
		matrices, widest int
		waited           time.Duration
	}
	byPool := map[string]*held{}
	for _, m := range s.Fleet.Jobs.Matrices {
		if m.Waited < MatrixWait {
			continue
		}
		for _, p := range s.Fleet.Pools {
			if p.ID != m.PoolID || p.MaxRunners <= 0 || p.MaxRunners >= m.Jobs {
				continue
			}
			h := byPool[p.ID]
			if h == nil {
				h = &held{}
				byPool[p.ID] = h
			}
			h.matrices++
			h.widest = max(h.widest, m.Jobs)
			h.waited = max(h.waited, m.Waited)
		}
	}
	var findings []Finding
	for _, p := range s.Fleet.Pools {
		h := byPool[p.ID]
		if h == nil {
			continue
		}
		findings = append(findings, Finding{
			Code:     CodeMatrixExceedsPool,
			Severity: SeverityInfo,
			Subject:  p.ID,
			Title:    "A matrix is wider than the pool that runs it",
			Detail: count(h.matrices, "matrix", "matrices") + " of up to " + count(h.widest, "job", "jobs") + " ran on a pool of " + count(p.MaxRunners, "runner", "runners") +
				" in the last " + forDays(s.Fleet.Window) + ", and jobs of it waited up to " + span(h.waited) + " for a runner. A matrix wider than its pool runs in waves.",
			Fix: "Raise the pool's max_runners to the matrix's width, spread the matrix over more than one pool with runs-on, " +
				"or cap it with max-parallel so the wait is chosen and not suffered.",
			Evidence: []Evidence{poolEvidence(p.ID, p.Name)},
		})
	}
	return result{applies: true, findings: findings}
}

package kennel

import (
	"strings"
	"testing"
	"time"
)

func withMatrix(s Snapshot, pool string, jobs int, waited time.Duration) Snapshot {
	s.Fleet.Jobs.Matrices = append(s.Fleet.Jobs.Matrices, Matrix{PoolID: pool, Jobs: jobs, Waited: waited})
	return s
}

func matrixRepo(maxRunners int) Snapshot {
	s := privateRepo()
	s.Fleet.Pools = []PoolFact{{ID: "pool_a1", Name: "zoomies-ubuntu-2404", JobsRun: 6, MaxRunners: maxRunners}}
	return s
}

// A matrix wider than its pool runs in waves, and the wait is the symptom an
// operator sees: the finding says the width, the ceiling and the wait, and
// points at the pool, which is where the change is made.
func TestAMatrixWiderThanItsPoolThatWaitedIsAnInfoFindingOnThePool(t *testing.T) {
	ev := Evaluate(withMatrix(matrixRepo(2), "pool_a1", 6, 3*time.Minute), Policy{})
	f := findingIn(t, ev, CodeMatrixExceedsPool)
	if f.Severity != SeverityInfo || f.Subject != "pool_a1" {
		t.Errorf("finding = %+v", f)
	}
	if !strings.Contains(f.Detail, "6 jobs") || !strings.Contains(f.Detail, "2 runners") || !strings.Contains(f.Detail, "3 minutes") {
		t.Errorf("detail = %q", f.Detail)
	}
	if len(f.Evidence) != 1 || f.Evidence[0].Kind != EvidencePool || f.Evidence[0].Ref != "pool_a1" {
		t.Errorf("evidence = %+v, want the pool", f.Evidence)
	}
}

// A pool with no ceiling cannot be too small, and a matrix whose jobs all
// started at once was not held up by the pool, whatever its width.
func TestAMatrixOnAPoolWithNoCeilingOrThatDidNotWaitRaisesNothing(t *testing.T) {
	for name, s := range map[string]Snapshot{
		"no ceiling":   withMatrix(matrixRepo(0), "pool_a1", 6, 10*time.Minute),
		"did not wait": withMatrix(matrixRepo(2), "pool_a1", 6, 59*time.Second),
		"fits":         withMatrix(matrixRepo(6), "pool_a1", 6, 10*time.Minute),
		"unknown pool": withMatrix(matrixRepo(2), "pool_gone", 6, 10*time.Minute),
	} {
		if ev := Evaluate(s, Policy{}); hasFinding(ev, CodeMatrixExceedsPool) {
			t.Errorf("%s: a finding was raised", name)
		}
	}
}

func TestOneFindingPerPoolHoweverManyMatricesRanOnIt(t *testing.T) {
	s := matrixRepo(2)
	s.Fleet.Pools = append(s.Fleet.Pools, PoolFact{ID: "pool_b2", Name: "zoomies-ubuntu-2404-b", JobsRun: 3, MaxRunners: 1})
	s = withMatrix(s, "pool_a1", 6, 3*time.Minute)
	s = withMatrix(s, "pool_a1", 4, 9*time.Minute)
	s = withMatrix(s, "pool_b2", 3, 2*time.Minute)
	ev := Evaluate(s, Policy{})
	var n int
	for _, f := range ev.Findings {
		if f.Code == CodeMatrixExceedsPool {
			n++
			if f.Subject == "pool_a1" && (!strings.Contains(f.Detail, "2 matrices") || !strings.Contains(f.Detail, "9 minutes")) {
				t.Errorf("pool_a1 detail = %q, want both matrices and the longest wait", f.Detail)
			}
		}
	}
	if n != 2 {
		t.Errorf("%d findings, want one per pool", n)
	}
}

func findingIn(t *testing.T, ev Evaluation, code Code) Finding {
	t.Helper()
	for _, f := range ev.Findings {
		if f.Code == code {
			return f
		}
	}
	t.Fatalf("no %s among %+v", code, ev.Findings)
	return Finding{}
}

func hasFinding(ev Evaluation, code Code) bool {
	for _, f := range ev.Findings {
		if f.Code == code {
			return true
		}
	}
	return false
}

// Package kennel decides what is wrong with a repository, from the facts it is
// handed and from nothing else.
//
// It is pure on purpose, for the reason internal/scheduler is: no clock, no
// database, no network. A check that reads the world cannot be tested by
// describing a world, and a finding whose sentence came from somewhere other
// than this package cannot be trusted not to repeat what a stranger wrote into
// a repository. Both properties are tested: boundary_test.go fails if this
// package imports anything but the standard library or reads a clock, and the
// hostile-input test fails if repository text reaches a sentence.
//
// The question every check answers is "does this affect running CI, or the
// fleet that runs it?". The optional setup area also reports repository-local
// guidance that makes contributions, maintenance and CI easier to sustain.
package kennel

import (
	"slices"
	"strings"
)

// Version is the evaluator's version. A stored evaluation made by an older one
// is re-run, so bump it whenever a check's meaning or wording changes.
const Version = 7

