import "testing"

func completeSetup() *SetupFacts {
	s := &SetupFacts{Present: map[Code]bool{}, HasDependencies: true}
	for _, c := range Checks() {
		if c.Area == AreaSetup {
			s.Present[c.Code] = true
		}
	}
	return s
}

func init() {
	for _, c := range Checks() {
		if c.Area != AreaSetup {
			continue
		}
		code := c.Code
		positives[code] = func() Snapshot {
			s := publicRepo()
			delete(s.Setup.Present, code)
			return s
		}
	}
}

