package kennel

import (
	"slices"
	"time"
)

// Visibility is a repository's visibility as GitHub reports it. An internal
// repository, GitHub Enterprise's, is not public: only members of the
// enterprise can open a pull request against it.
type Visibility string

const (
	VisibilityPublic   Visibility = "public"
	VisibilityPrivate  Visibility = "private"
	VisibilityInternal Visibility = "internal"
)

// Snapshot is everything Evaluate is told about one repository. It is plain
// data, assembled by the controller from the store and from GitHub, and it
// carries no raw repository content: a field is a number, a flag, an
// enumerated word, or an identifier the controller made.
type Snapshot struct {
	// At is when the facts were taken. It is data, because this package reads no
	// clock; waivers are judged against it.
	At        time.Time
	Repo      Repo
	Fleet     Fleet
	Workflows *WorkflowFacts
	Guidance  *GuidanceFacts
	Setup     *SetupFacts
	Runs      *RunFacts
	Settings  *SettingsFacts
	// Protection is nil until the default branch's required checks have been
	// read and compared with the jobs the fleet saw.
	Protection *ProtectionFacts
	Coverage   Coverage
}

// Repo is what GitHub says about the repository itself.
type Repo struct {
	// Visibility is empty until the metadata has been read.
	Visibility Visibility
}

// Fleet is what this controller observed about the repository's jobs.
type Fleet struct {
	// Window is how far back these facts reach: the shorter of thirty days and
	// the fleet's job retention. A sentence that says "in the last N days"
	// says this one, never a number somebody remembered.
	Window time.Duration
	Jobs   JobFacts
	// Pools are the pools that ran this repository's jobs inside the window.
	Pools []PoolFact
	// RunnerGroupAllowsPublic is what the organisation runner group the fleet
	// registers into says about public repositories.
	RunnerGroupAllowsPublic Tri
}

// Tri is a yes, a no, or "GitHub did not say". Treating a missing answer as no
// would raise a warning nobody could act on.
type Tri string

const (
	TriUnknown Tri = ""
	TriYes     Tri = "yes"
	TriNo      Tri = "no"
)

// JobFacts counts and measures what the fleet did for the repository.
type JobFacts struct {
	// Ran is the jobs a runner of this fleet executed inside the window.
	Ran int
	// Queued is the jobs waiting for this fleet right now.
	Queued int
	// Unserved lists jobs that waited for a label no pool serves, inside the
	// last seven days, longest first and capped at 200 by the collector.
	Unserved []Unserved
	// Long lists finished jobs that held a runner for LongJobFloor or more,
	// inside the window, capped at 500 by the collector. Handing over only the
	// long ones keeps the snapshot small; deciding which of them hit GitHub's
	// limit stays here, where it can be tested.
	Long []FinishedJob
	// Matrices are the matrices of two or more jobs the fleet ran inside the
	// window, widest first, capped at 200 by the collector.
	Matrices []Matrix
}

// Matrix is one matrix the fleet ran: how wide it was, which pool ran it, and
// the longest any of its jobs waited for a runner.
type Matrix struct {
	PoolID string
	Jobs   int
	Waited time.Duration
}

// Unserved is one job that waited for a label no pool serves.
type Unserved struct {
	Waited time.Duration
}

// FinishedJob is one job that held a runner for a long time.
type FinishedJob struct {
	Duration   time.Duration
	Conclusion string
}

// PoolDanger is one way a pool weakens the isolation between a job and its host.
// The controller reduces a pool to these words; the evaluator never sees a pool.
type PoolDanger string

const (
	DangerPersistent  PoolDanger = "persistent"
	DangerHostSocket  PoolDanger = "host_socket"
	DangerPrivileged  PoolDanger = "privileged_docker"
	DangerRoot        PoolDanger = "root"
	DangerNoContainer PoolDanger = "no_container"
)

// PoolFact is one pool that ran jobs for the repository.
type PoolFact struct {
	// ID and Name are the pool's. The name is the operator's own text, so it
	// reaches a finding only as evidence, through the gate in refs.go.
	ID      string
	Name    string
	JobsRun int
	// MaxRunners is the pool's ceiling; 0 is no ceiling, as for an automatic
	// pool, and such a pool is never too small.
	MaxRunners int
	Dangers    []PoolDanger
}

// RunFacts are five fields of each run the fleet ran in a public repository:
// nothing else about a run is read, so nothing else can leak into a finding.
type RunFacts struct {
	// Window is how far back the runs reach.
	Window time.Duration
	Runs   []Run
}

// Run is one workflow run.
type Run struct {
	ID int64
	// Event is GitHub's trigger name. The controller passes it through an
	// allow-list, so an event this package does not know arrives as "other".
	Event string
	// FromFork is whether the run's head repository is not the repository it
	// ran in.
	FromFork bool
}

// NormalizeEvent is what a run's trigger is called once it has been through the
// allow-list. The only events any check looks at are a pull request, which is
// fork code when the run is from a fork, and the four a stranger can trigger on
// the default branch; every other name -- including anything a snapshot should
// not carry -- is "other", which no check treats specially.
func NormalizeEvent(event string) string {
	if event == "pull_request" || slices.Contains(strangerEvents, event) {
		return event
	}
	return "other"
}

package kennel

import "time"

// Waiver is a decision, recorded by a person with a reason, that a finding is
// acceptable here. It is not a dismissal: a dismissal hides a notification for
// one person, and a waiver changes what the fleet's record says about a
// repository, so it carries a reason, an owner and an end.
type Waiver struct {
	ID      string `json:"id"`
	Code    Code   `json:"code"`
	Subject string `json:"subject"`
	// Severity is the finding's severity when the waiver was made. A finding
	// that has since got worse is not covered by a decision about a milder one.
	Severity Severity  `json:"severity"`
	Reason   string    `json:"reason"`
	By       string    `json:"by"`
	At       time.Time `json:"at"`
	// ExpiresAt is mandatory. A waiver that never ends is a decision nobody is
	// asked to make again.
	ExpiresAt time.Time `json:"expires_at"`
}

// covers says whether the waiver still speaks for this finding at this moment.
func (w Waiver) covers(f Finding, now time.Time) bool {
	return w.Code == f.Code &&
		w.Subject == f.Subject &&
		now.Before(w.ExpiresAt) &&
		w.Severity.rank() >= f.Severity.rank()
}

// matches is whether the waiver is about this finding at all, whether or not it
// is still in force.
func (w Waiver) matches(f Finding) bool { return w.Code == f.Code && w.Subject == f.Subject }

// WaivedFinding is a finding a waiver covers.
type WaivedFinding struct {
	Finding Finding `json:"finding"`
	Waiver  Waiver  `json:"waiver"`
}

package kennel

import (
	"testing"
	"time"
)

func waiverFor(c Code, sev Severity, expires time.Time) Waiver {
	return Waiver{ID: "kcw_1", Code: c, Severity: sev, Reason: "isolated hosts, reviewed", By: "usr_1", At: now.Add(-time.Hour), ExpiresAt: expires}
}

func forkRun() Snapshot {
	return withRuns(publicRepo(), Run{ID: 1, Event: "pull_request", FromFork: true})
}

// A waiver is how a person says "I have looked, and this is acceptable here".
// It must take the finding off the open list without making it disappear.
func TestAWaiverMovesAFindingToWaivedAndKeepsItVisible(t *testing.T) {
	w := waiverFor(CodeForkCodeRan, SeverityError, now.Add(24*time.Hour))
	ev := Evaluate(forkRun(), Policy{Waivers: []Waiver{w}})
	if _, open := finding(ev, CodeForkCodeRan); open {
		t.Error("a waived finding is still open")
	}
	if len(ev.Waived) != 1 || ev.Waived[0].Finding.Code != CodeForkCodeRan || ev.Waived[0].Waiver.Reason != w.Reason {
		t.Errorf("waived = %+v, want the finding with its waiver beside it", ev.Waived)
	}
	if ev.Counts().Waived != 1 {
		t.Errorf("counts = %+v: the badge has to be able to say how many are waived", ev.Counts())
	}
}

// A decision nobody is asked to make again is a decision that has been
// forgotten. At its end the finding is open again, and the evaluation says a
// waiver lapsed so the page can say so.
func TestAWaiverEndsWhenItExpires(t *testing.T) {
	w := waiverFor(CodeForkCodeRan, SeverityError, now) // expires exactly now
	ev := Evaluate(forkRun(), Policy{Waivers: []Waiver{w}})
	if _, open := finding(ev, CodeForkCodeRan); !open {
		t.Error("an expired waiver still covers the finding")
	}
	if len(ev.Lapsed) != 1 {
		t.Errorf("lapsed = %+v, want the expired waiver", ev.Lapsed)
	}
}

// A decision about a warning is not a decision about the error it became.
func TestAWaiverDoesNotCoverAFindingThatGotWorse(t *testing.T) {
	// The public-repository finding was a warning when it was waived, and a fork's
	// code running since has made it an error.
	w := waiverFor(CodePublicRepoOnFleet, SeverityWarning, now.Add(time.Hour))
	ev := Evaluate(forkRun(), Policy{Waivers: []Waiver{w}})
	f, open := finding(ev, CodePublicRepoOnFleet)
	if !open || f.Severity != SeverityError {
		t.Fatalf("finding open=%v severity=%s, want an open error", open, f.Severity)
	}
	if len(ev.Lapsed) != 1 {
		t.Errorf("lapsed = %+v, want the outranked waiver", ev.Lapsed)
	}
}

func TestAWaiverMadeForAnErrorCoversTheSameFindingWhenItIsMilder(t *testing.T) {
	w := waiverFor(CodePublicRepoOnFleet, SeverityError, now.Add(time.Hour))
	ev := Evaluate(publicRepo(), Policy{Waivers: []Waiver{w}}) // a warning on its own
	if _, open := finding(ev, CodePublicRepoOnFleet); open {
		t.Error("a waiver for an error did not cover the same finding at warning")
	}
}

func TestAWaiverIsAboutOneFindingAndOneSubject(t *testing.T) {
	other := waiverFor(CodeTargetEventRan, SeverityError, now.Add(time.Hour))
	subject := waiverFor(CodeForkCodeRan, SeverityError, now.Add(time.Hour))
	subject.Subject = "workflow:1234"
	ev := Evaluate(forkRun(), Policy{Waivers: []Waiver{other, subject}})
	if _, open := finding(ev, CodeForkCodeRan); !open {
		t.Error("a waiver for another check or another subject covered the finding")
	}
}

// A finding that stopped being reported has no use for its waiver, and the
// controller retires it: an old decision must not quietly cover the same
// problem if it comes back months later.
func TestAWaiverForAFindingThatIsGoneIsStale(t *testing.T) {
	w := waiverFor(CodeForkCodeRan, SeverityError, now.Add(time.Hour))
	ev := Evaluate(publicRepo(), Policy{Waivers: []Waiver{w}})
	if len(ev.Stale) != 1 || ev.Stale[0].ID != w.ID {
		t.Errorf("stale = %+v, want the waiver", ev.Stale)
	}
	if len(ev.Waived) != 0 {
		t.Errorf("waived = %+v", ev.Waived)
	}
}

// Where two waivers could cover a finding, the answer must not depend on the
// order they were read from the database in.
func TestTheLongestWaiverCoversAndTheOrderTheyWereStoredInDoesNotMatter(t *testing.T) {
	short := waiverFor(CodeForkCodeRan, SeverityError, now.Add(time.Hour))
	short.ID = "kcw_a" // sorts first, so an ID tie-break cannot stand in for the expiry order
	long := waiverFor(CodeForkCodeRan, SeverityError, now.Add(48*time.Hour))
	long.ID = "kcw_z"
	for _, order := range [][]Waiver{{short, long}, {long, short}} {
		ev := Evaluate(forkRun(), Policy{Waivers: order})
		if len(ev.Waived) != 1 || ev.Waived[0].Waiver.ID != "kcw_z" {
			t.Errorf("waived by %v, want the longer waiver", ev.Waived)
		}
	}
}

// Waiving the milder finding must not silently cover the worse one it escalates
// to: escalation happens before waivers are applied.
func TestEscalationHappensBeforeWaiversAreApplied(t *testing.T) {
	warn := waiverFor(CodePublicRepoOnFleet, SeverityWarning, now.Add(time.Hour))
	ev := Evaluate(withWeakPool(publicRepo(), DangerRoot), Policy{Waivers: []Waiver{warn}})
	if _, open := finding(ev, CodePublicRepoOnFleet); !open {
		t.Error("a waiver for the warning covered the finding after it became an error")
	}
}

package kennel

import (
	"strconv"
	"time"
)

// The helpers here build the numbers and phrases a sentence is allowed to
// contain. Nothing in this file takes a string from a snapshot.

// count says "1 run" or "4 runs".
func count(n int, one, many string) string {
	if n == 1 {
		return "1 " + one
	}
	return strconv.Itoa(n) + " " + many
}

// days rounds a window up to whole days, and never says less than one.
func days(d time.Duration) int {
	n := int((d + 24*time.Hour - 1) / (24 * time.Hour))
	if n < 1 {
		return 1
	}
	return n
}

// forDays says "1 day" or "30 days".
func forDays(d time.Duration) string { return count(days(d), "day", "days") }

// span says how long, in the largest whole unit and no finer: "42 minutes",
// "3 hours".
func span(d time.Duration) string {
	switch {
	case d >= 2*time.Hour:
		return count(int(d/time.Hour), "hour", "hours")
	case d >= time.Hour:
		return "1 hour"
	default:
		m := int(d / time.Minute)
		if m < 1 {
			m = 1
		}
		return count(m, "minute", "minutes")
	}
}

package kennel

import (
	"testing"
	"time"
)

// A window the sentence reports must never be shorter than the one that was
// read: "in the last 1 day" over a thirty-hour window would understate what the
// finding is built on.
func TestAWindowIsReportedInWholeDaysRoundedUpAndNeverBelowOne(t *testing.T) {
	tests := []struct {
		window time.Duration
		want   string
	}{
		{0, "1 day"},
		{time.Hour, "1 day"},
		{24 * time.Hour, "1 day"},
		{25 * time.Hour, "2 days"},
		{36 * time.Hour, "2 days"},
		{30 * 24 * time.Hour, "30 days"},
	}
	for _, tt := range tests {
		if got := forDays(tt.window); got != tt.want {
			t.Errorf("forDays(%s) = %q, want %q", tt.window, got, tt.want)
		}
	}
}

func TestADurationIsSaidInItsLargestWholeUnit(t *testing.T) {
	tests := []struct {
		d    time.Duration
		want string
	}{
		{0, "1 minute"},
		{30 * time.Second, "1 minute"},
		{10 * time.Minute, "10 minutes"},
		{59*time.Minute + 59*time.Second, "59 minutes"},
		{time.Hour, "1 hour"},
		{119 * time.Minute, "1 hour"},
		{2 * time.Hour, "2 hours"},
		{25 * time.Hour, "25 hours"},
	}
	for _, tt := range tests {
		if got := span(tt.d); got != tt.want {
			t.Errorf("span(%s) = %q, want %q", tt.d, got, tt.want)
		}
	}
}

func TestACountAgreesWithItsNoun(t *testing.T) {
	if got := count(1, "job", "jobs"); got != "1 job" {
		t.Errorf("got %q", got)
	}
	for _, n := range []int{0, 2, 11} {
		if got := count(n, "job", "jobs"); got[len(got)-4:] != "jobs" {
			t.Errorf("count(%d) = %q", n, got)
		}
	}
}

package workflow

import (
	"errors"
	"strings"

	"gopkg.in/yaml.v3"
)

var errCacheUnsupported = errors.New("setup cache change needs one pinned setup-node step with a block with mapping")

// SetupCacheChange returns the exact bytes to add a package-manager cache to
// one actions/setup-node step. The step must be pinned to a commit and must not
// already name a cache. The caller supplies the package manager because the
// lockfile it was read from decides it; this function does not guess.
//
// The edit inserts the new key immediately after the step's with: line, at the
// indentation of the first key already there. The bytes before and after are
// contiguous slices, so the existing comments and line endings are preserved.
func SetupCacheChange(data []byte, jobIndex, stepIndex int, manager string) (before, after string, line int, err error) {
	if manager != "npm" && manager != "yarn" && manager != "pnpm" {
		return "", "", 0, errCacheUnsupported
	}
	if _, err = Inspect(data); err != nil {
		return "", "", 0, err
	}
	root, parseErr := parseRoot(data)
	if parseErr != nil {
		err = parseErr
		return
	}
	jobs := field(root, "jobs")
	if jobIndex < 0 || jobIndex >= len(jobs.Content)/2 {
		err = errUnsupported
		return
	}
	job := jobs.Content[jobIndex*2+1]
	steps := field(job, "steps")
	if field(job, "uses") != nil || steps == nil || steps.Kind != yaml.SequenceNode || stepIndex < 0 || stepIndex >= len(steps.Content) {
		err = errUnsupported
		return
	}
	step := steps.Content[stepIndex]
	uses := field(step, "uses")
	if field(step, "run") != nil || uses == nil || uses.Kind != yaml.ScalarNode || !strings.HasPrefix(uses.Value, "actions/setup-node@") || !commitSHA.MatchString(strings.TrimPrefix(uses.Value, "actions/setup-node@")) {
		err = errUnsupported
		return
	}
	withKey, with := keyAndValue(step, "with")
	if with == nil || with.Kind != yaml.MappingNode || with.Style&yaml.FlowStyle != 0 || field(with, "cache") != nil || len(with.Content) < 2 {
		err = errUnsupported
		return
	}
	lines := strings.SplitAfter(string(data), "\n")
	if withKey.Line < 1 || withKey.Line > len(lines) {
		err = errUnsupported
		return
	}
	firstKey := with.Content[0]
	if firstKey.Line <= withKey.Line || firstKey.Line > len(lines) {
		err = errUnsupported
		return
	}
	indent := strings.Repeat(" ", max(firstKey.Column-1, 0))
	withLine := lines[withKey.Line-1]
	throughFirst := strings.Join(lines[withKey.Line-1:firstKey.Line], "")
	before = throughFirst
	ending := "\n"
	if strings.HasSuffix(withLine, "\r\n") {
		ending = "\r\n"
	}
	insert := indent + "cache: " + manager + ending
	if !strings.HasSuffix(withLine, "\n") {
		withLine += ending
	}
	after = withLine + insert + strings.Join(lines[withKey.Line:firstKey.Line], "")
	if strings.Count(string(data), before) != 1 {
		return "", "", 0, errCacheUnsupported
	}
	return before, after, withKey.Line + 1, nil
}

var (
	ErrSetupNodeNotFound  = errors.New("no pinned actions/setup-node step")
	ErrSetupNodeAmbiguous = errors.New("more than one pinned actions/setup-node step")
)

// FindSetupNode returns the one pinned actions/setup-node step in a workflow.
// Two candidates are an explained refusal rather than a guess: a cache added to
// the wrong one would change the wrong package manager's behaviour.
func FindSetupNode(data []byte) (jobIndex, stepIndex int, err error) {
	if _, err = Inspect(data); err != nil {
		return 0, 0, err
	}
	root, parseErr := parseRoot(data)
	if parseErr != nil {
		return 0, 0, parseErr
	}
	jobs := field(root, "jobs")
	if jobs == nil || jobs.Kind != yaml.MappingNode {
		return 0, 0, errUnsupported
	}
	found := false
	for i := 0; i < len(jobs.Content); i += 2 {
		index := i / 2
		job := jobs.Content[i+1]
		if job.Kind != yaml.MappingNode || field(job, "uses") != nil {
			continue
		}
		steps := field(job, "steps")
		if steps == nil || steps.Kind != yaml.SequenceNode {
			continue
		}
		for j, step := range steps.Content {
			uses := field(step, "uses")
			if step.Kind != yaml.MappingNode || uses == nil || uses.Kind != yaml.ScalarNode {
				continue
			}
			if !strings.HasPrefix(uses.Value, "actions/setup-node@") || !commitSHA.MatchString(strings.TrimPrefix(uses.Value, "actions/setup-node@")) {
				continue
			}
			if found {
				return 0, 0, ErrSetupNodeAmbiguous
			}
			jobIndex, stepIndex, found = index, j, true
		}
	}
	if !found {
		return 0, 0, ErrSetupNodeNotFound
	}
	return jobIndex, stepIndex, nil
}

// SetupNames returns the literal job and step names for the one pinned
// setup-node step. The cache preview matches them against the fleet job's
// GitHub-reported names; an unnamed step cannot be matched safely.
func SetupNames(data []byte, jobIndex, stepIndex int) (jobName, stepName string, err error) {
	foundJob, foundStep, err := FindSetupNode(data)
	if err != nil || foundJob != jobIndex || foundStep != stepIndex {
		return "", "", errUnsupported
	}
	return namesAt(data, jobIndex, stepIndex)
}

package workflow

import (
	"strings"
	"testing"
)

const cacheWorkflow = `on: push
jobs:
  build:
    name: Build
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@` + "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa" + `
      - name: Node
        uses: actions/setup-node@` + "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb" + `
        with:
          node-version: 20
          # keep this note
          registry-url: https://registry.npmjs.org
      - run: npm test
`

func TestSetupCacheChangeInsertsTheKeyAndPreservesTheRest(t *testing.T) {
	if _, err := Inspect([]byte(cacheWorkflow)); err != nil {
		t.Fatalf("inspect fixture: %v", err)
	}
	before, after, line, err := SetupCacheChange([]byte(cacheWorkflow), 0, 1, "npm")
	if err != nil {
		t.Fatal(err)
	}
	if line != 11 || !strings.Contains(after, "          cache: npm\n") || !strings.Contains(after, "          node-version: 20\n") || strings.Count(after, "cache: npm") != 1 {
		t.Fatalf("line=%d after=%q", line, after)
	}
	if strings.Count(cacheWorkflow, before) != 1 {
		t.Fatalf("preimage is not a unique contiguous slice: %q", before)
	}
	out := strings.Replace(cacheWorkflow, before, after, 1)
	if !strings.Contains(out, "          cache: npm\n          node-version: 20") {
		t.Fatalf("inserted in the wrong place: %s", out)
	}
}

func TestSetupCacheChangePreservesCRLF(t *testing.T) {
	crlf := strings.ReplaceAll(cacheWorkflow, "\n", "\r\n")
	before, after, _, err := SetupCacheChange([]byte(crlf), 0, 1, "pnpm")
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(after, "          cache: pnpm\r\n") || strings.Contains(after, "\n") && !strings.Contains(after, "\r\n") {
		t.Fatalf("line endings changed: %q", after)
	}
	if strings.Count(crlf, before) != 1 {
		t.Fatal("CRLF preimage is not unique")
	}
}

func TestSetupCacheChangeRefusesUnsupportedSteps(t *testing.T) {
	for _, tc := range []struct {
		name string
		doc  string
		job  int
		step int
		mgmt string
	}{
		{"unpinned action", strings.ReplaceAll(cacheWorkflow, "actions/setup-node@bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb", "actions/setup-node@v4"), 0, 1, "npm"},
		{"checkout step", cacheWorkflow, 0, 0, "npm"},
		{"cache already set", strings.ReplaceAll(cacheWorkflow, "          node-version: 20\n", "          node-version: 20\n          cache: npm\n"), 0, 1, "npm"},
		{"flow with", strings.ReplaceAll(cacheWorkflow, "        with:\n          node-version: 20\n          # keep this note\n          registry-url: https://registry.npmjs.org", "        with: { node-version: 20 }"), 0, 1, "npm"},
		{"empty with", strings.ReplaceAll(cacheWorkflow, "        with:\n          node-version: 20\n          # keep this note\n          registry-url: https://registry.npmjs.org", "        with:"), 0, 1, "npm"},
		{"unknown manager", cacheWorkflow, 0, 1, "bun"},
		{"wrong job", cacheWorkflow, 1, 1, "npm"},
		{"wrong step", cacheWorkflow, 0, 9, "npm"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if _, _, _, err := SetupCacheChange([]byte(tc.doc), tc.job, tc.step, tc.mgmt); err == nil {
				t.Fatal("accepted")
			}
		})
	}
}

func TestSetupCacheChangeRefusesAPreimageThatIsNotUnique(t *testing.T) {
	doc := strings.Replace(cacheWorkflow, "      - run: npm test", "      - uses: actions/setup-node@"+strings.Repeat("b", 40)+"\n        with:\n          node-version: 20\n      - run: npm test", 1)
	if _, _, _, err := SetupCacheChange([]byte(doc), 0, 1, "npm"); err == nil || !strings.Contains(err.Error(), "setup cache") {
		t.Fatalf("accepted an ambiguous preimage: %v", err)
	}
}

func TestFindSetupNodeFindsOneAndRefusesNoneOrTwo(t *testing.T) {
	if job, step, err := FindSetupNode([]byte(cacheWorkflow)); err != nil || job != 0 || step != 1 {
		t.Fatalf("job=%d step=%d err=%v", job, step, err)
	}
	none := strings.ReplaceAll(cacheWorkflow, "actions/setup-node@"+strings.Repeat("b", 40), "actions/setup-node@v4")
	if _, _, err := FindSetupNode([]byte(none)); err != ErrSetupNodeNotFound {
		t.Fatalf("none: %v", err)
	}
	two := strings.Replace(cacheWorkflow, "      - run: npm test", "      - uses: actions/setup-node@"+strings.Repeat("c", 40)+"\n        with:\n          node-version: 20\n      - run: npm test", 1)
	if _, _, err := FindSetupNode([]byte(two)); err != ErrSetupNodeAmbiguous {
		t.Fatalf("two: %v", err)
	}
}

package workflow

import (
	"errors"
	"strings"

	"gopkg.in/yaml.v3"
)

// CheckoutDepthChange preserves the original line, including comments and line
// endings. Unsupported syntax is refused rather than reserialised as new YAML.
func CheckoutDepthChange(data []byte, jobIndex, stepIndex int) (before, after string, line int, err error) {
	if _, err = Inspect(data); err != nil {
		return
	}
	root, parseErr := parseRoot(data)
	if parseErr != nil {
		err = parseErr
		return
	}
	jobs := field(root, "jobs")
	if jobIndex < 0 || jobIndex >= len(jobs.Content)/2 {
		err = errUnsupported
		return
	}
	job := jobs.Content[jobIndex*2+1]
	steps := field(job, "steps")
	if field(job, "uses") != nil || steps == nil || steps.Kind != yaml.SequenceNode || stepIndex < 0 || stepIndex >= len(steps.Content) {
		err = errUnsupported
		return
	}
	step := steps.Content[stepIndex]
	uses := field(step, "uses")
	if field(step, "run") != nil || uses == nil || uses.Kind != yaml.ScalarNode || !strings.HasPrefix(uses.Value, "actions/checkout@") || !commitSHA.MatchString(strings.TrimPrefix(uses.Value, "actions/checkout@")) {
		err = errUnsupported
		return
	}
	with := field(step, "with")
	if with == nil || with.Kind != yaml.MappingNode || with.Style&yaml.FlowStyle != 0 {
		err = errUnsupported
		return
	}
	depth := field(with, "fetch-depth")
	if depth == nil || depth.Kind != yaml.ScalarNode || depth.Value != "0" || depth.Style != 0 || depth.Tag != "!!int" || field(with, "fetch-tags") != nil || field(with, "ref") != nil || field(with, "repository") != nil {
		err = errUnsupported
		return
	}
	lines := strings.SplitAfter(string(data), "\n")
	line = depth.Line
	if line < 1 || line > len(lines) {
		err = errUnsupported
		return
	}
	before = lines[line-1]
	offset := depth.Column - 1
	if offset < 0 || offset >= len(before) || before[offset] != '0' || strings.Count(string(data), before) != 1 {
		err = errUnsupported
		return
	}
	after = before[:offset] + "1" + before[offset+1:]
	return
}

// CheckoutNames supplies a conservative association with API names. It does not
// attest executed bytes. Dynamic/matrix/reusable job names cannot prove a position.
func CheckoutNames(data []byte, jobIndex, stepIndex int) (jobName, stepName string, err error) {
	if _, _, _, err = CheckoutDepthChange(data, jobIndex, stepIndex); err != nil {
		return
	}
	return namesAt(data, jobIndex, stepIndex)
}

// namesAt reads the literal job and step names at one position. Explicit names
// avoid depending on GitHub's generated naming rules; duplicate names in the
// file or the job make the association ambiguous.
func namesAt(data []byte, jobIndex, stepIndex int) (jobName, stepName string, err error) {
	root, err := parseRoot(data)
	if err != nil {
		return "", "", err
	}
	jobs := field(root, "jobs")
	if jobs == nil || jobs.Kind != yaml.MappingNode || jobIndex < 0 || jobIndex >= len(jobs.Content)/2 {
		return "", "", errUnsupported
	}
	literal := func(n *yaml.Node) (string, bool) {
		if n == nil || n.Kind != yaml.ScalarNode || n.Tag != "!!str" || n.Value == "" || len(n.Value) > 128 || strings.TrimSpace(n.Value) != n.Value || strings.Contains(n.Value, "${{") || strings.ContainsAny(n.Value, "\r\n\x00") {
			return "", false
		}
		return n.Value, true
	}
	seen := map[string]bool{}
	for i := 0; i < len(jobs.Content); i += 2 {
		job := jobs.Content[i+1]
		if field(job, "strategy") != nil || field(job, "uses") != nil {
			return "", "", errUnsupported
		}
		name := field(job, "name")
		if name == nil {
			name = jobs.Content[i]
		}
		text, ok := literal(name)
		if !ok || seen[text] {
			return "", "", errUnsupported
		}
		seen[text] = true
		if i/2 == jobIndex {
			if field(job, "name") == nil {
				return "", "", errUnsupported
			}
			jobName = text
		}
	}
	steps := field(jobs.Content[jobIndex*2+1], "steps")
	if steps == nil || steps.Kind != yaml.SequenceNode || stepIndex < 0 || stepIndex >= len(steps.Content) {
		return "", "", errUnsupported
	}
	seen = map[string]bool{}
	for i, step := range steps.Content {
		name, ok := literal(field(step, "name"))
		if !ok || seen[name] {
			return "", "", errUnsupported
		}
		seen[name] = true
		if i == stepIndex {
			stepName = name
		}
	}
	return jobName, stepName, nil
}

// ErrCheckoutNotFound and ErrCheckoutAmbiguous say why FindCheckout could not
// choose, so a caller can tell somebody whether to look at another job or to name
// the step themselves.
var (
	ErrCheckoutNotFound  = errors.New("workflow: no checkout step in that job can be previewed")
	ErrCheckoutAmbiguous = errors.New("workflow: more than one checkout step in that job can be previewed")
)

// FindCheckout locates the one previewable checkout step in the job GitHub
// reports under jobName, so nobody has to count positions in a file. Every
// condition CheckoutNames and CheckoutDepthChange impose still applies to the
// step it returns; this only does the counting. Two candidates is an error, not a
// guess.
func FindCheckout(data []byte, jobName string) (jobIndex, stepIndex int, err error) {
	root, parseErr := parseRoot(data)
	if parseErr != nil {
		return 0, 0, parseErr
	}
	jobs := field(root, "jobs")
	if jobs == nil {
		return 0, 0, ErrCheckoutNotFound
	}
	found := 0
	for j := 0; j < len(jobs.Content)/2; j++ {
		steps := field(jobs.Content[j*2+1], "steps")
		if steps == nil {
			continue
		}
		for s := range steps.Content {
			name, _, namesErr := CheckoutNames(data, j, s)
			if namesErr != nil || name != jobName {
				continue
			}
			jobIndex, stepIndex = j, s
			found++
		}
	}
	switch found {
	case 0:
		return 0, 0, ErrCheckoutNotFound
	case 1:
		return jobIndex, stepIndex, nil
	}
	return 0, 0, ErrCheckoutAmbiguous
}

package workflow

import (
	"strings"
	"testing"
)

func TestCheckoutLineEditRefusesAmbiguousYAMLAndUnsupportedInputForms(t *testing.T) {
	base := "on: push\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@" + strings.Repeat("a", 40) + "\n        with:\n          fetch-depth: 0\n"
	for _, data := range []string{
		strings.Replace(base, "fetch-depth: 0", "fetch-depth: '0'", 1),
		strings.Replace(base, "fetch-depth: 0", "fetch-depth: ${{ inputs.depth }}", 1),
		strings.Replace(base, "with:\n          fetch-depth: 0", "with: {fetch-depth: 0}", 1),
		base + "          fetch-depth: 0\n",
		base + "---\non: push\n",
		strings.Replace(base, "with:", "with: &inputs", 1),
		base + "          repository: other/repo\n",
		base + "          ref: main\n",
	} {
		if _, _, _, err := CheckoutDepthChange([]byte(data), 0, 0); err == nil {
			t.Fatalf("accepted unsupported source: %s", data)
		}
	}
}

func FuzzCheckoutDepthEditPreservesTheDocument(f *testing.F) {
	f.Add([]byte("on: push\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@" + strings.Repeat("a", 40) + "\n        with:\n          fetch-depth: 0 # comment\n"))
	f.Fuzz(func(t *testing.T, data []byte) {
		before, after, _, err := CheckoutDepthChange(data, 0, 0)
		if err != nil {
			return
		}
		if len(before) != len(after) || strings.Count(string(data), before) != 1 {
			t.Fatal("ambiguous edit emitted")
		}
		changed := strings.Replace(string(data), before, after, 1)
		if _, err := Inspect([]byte(changed)); err != nil {
			t.Fatal("edit invalidated supported YAML", err)
		}
		if _, _, _, err := CheckoutDepthChange([]byte(changed), 0, 0); err == nil {
			t.Fatal("preview reapplied to shallow checkout")
		}
	})
}

func TestCheckoutNamesRefuseGeneratedMatrixDynamicAndDuplicateSourceNames(t *testing.T) {
	base := "on: push\njobs:\n  test:\n    name: Build\n    runs-on: ubuntu-latest\n    steps:\n      - name: Checkout\n        uses: actions/checkout@" + strings.Repeat("a", 40) + "\n        with:\n          fetch-depth: 0\n      - name: Test\n        run: echo test\n"
	if j, s, err := CheckoutNames([]byte(base), 0, 0); err != nil || j != "Build" || s != "Checkout" {
		t.Fatal(j, s, err)
	}
	for _, data := range []string{
		strings.Replace(base, "    name: Build\n", "", 1),
		strings.Replace(base, "      - name: Checkout\n        uses:", "      - uses:", 1),
		strings.Replace(base, "    name: Build", "    name: ${{ inputs.name }}", 1),
		strings.Replace(base, "    name: Build", "    strategy: {matrix: {os: [linux]}}\n    name: Build", 1),
		strings.Replace(base, "name: Test", "name: Checkout", 1),
		base + "  other:\n    name: Build\n    runs-on: ubuntu-latest\n    steps:\n      - run: echo other\n",
	} {
		if _, _, err := CheckoutNames([]byte(data), 0, 0); err == nil {
			t.Fatal("ambiguous name association accepted")
		}
	}
}

func TestFindCheckoutChoosesTheOnePreviewableStepAndNeverGuesses(t *testing.T) {
	sha := strings.Repeat("a", 40)
	job := func(key, name string) string {
		return "  " + key + ":\n    name: " + name + "\n    runs-on: ubuntu-latest\n    steps:\n      - name: Checkout\n        uses: actions/checkout@" + sha + "\n        with:\n          fetch-depth: 0\n      - name: Test\n        run: echo test\n"
	}
	lint := "  lint:\n    name: Lint\n    runs-on: ubuntu-latest\n    steps:\n      - name: Vet\n        run: echo vet\n"
	two := "on: push\njobs:\n" + lint + job("test", "Build")
	j, s, err := FindCheckout([]byte(two), "Build")
	if err != nil || j != 1 || s != 0 {
		t.Fatalf("want job 1 step 0, got %d %d %v", j, s, err)
	}
	if _, _, err := FindCheckout([]byte(two), "Deploy"); err != ErrCheckoutNotFound {
		t.Fatalf("a job with no such name: %v", err)
	}
	shallow := strings.Replace(job("test", "Build"), "fetch-depth: 0", "fetch-depth: 1", 1)
	if _, _, err := FindCheckout([]byte("on: push\njobs:\n"+shallow), "Build"); err != ErrCheckoutNotFound {
		t.Fatalf("an already shallow checkout is not a candidate: %v", err)
	}
	twice := strings.Replace(job("test", "Build"), "      - name: Test\n        run: echo test\n", "      - name: Checkout again\n        uses: actions/checkout@"+sha+"\n        with:\n          fetch-depth: 0 # again\n", 1)
	if _, _, err := FindCheckout([]byte("on: push\njobs:\n"+twice), "Build"); err != ErrCheckoutAmbiguous {
		t.Fatalf("two candidates must be refused, not picked: %v", err)
	}
}

package workflow

import (
	"crypto/sha256"
	"encoding/hex"
	"regexp"
	"strconv"
	"strings"
	"unicode"

	"gopkg.in/yaml.v3"
)

const DependencyRows = 100
const maxDependencyDeclarations = maxNodes / 2

// These are root-file declaration facts, never resolved dependencies. Raw names,
// paths, inputs and source text must not outlive the parser.
type DependencyInventory struct {
	Version      string                `json:"version"`
	Basis        string                `json:"basis"`
	SourceSHA256 string                `json:"source_sha256"`
	Coverage     string                `json:"coverage"`
	Counts       *DependencyCounts     `json:"counts"`
	RowsOmitted  bool                  `json:"rows_omitted"`
	References   []DependencyReference `json:"references"`
}
type DependencyCounts struct {
	Declarations int `json:"declarations"`
	CommitPins   int `json:"commit_pins"`
	DigestPins   int `json:"digest_pins"`
	Floating     int `json:"floating"`
	Local        int `json:"local"`
	Expressions  int `json:"expressions"`
	Unknown      int `json:"unknown"`
}
type DependencyReference struct {
	JobIndex        int     `json:"job_index"`
	StepIndex       int     `json:"step_index"`
	Line            int     `json:"line"`
	Declaration     string  `json:"declaration"`
	Kind            string  `json:"kind"`
	Pin             string  `json:"pin"`
	ReferenceSHA256 string  `json:"reference_sha256"`
	Revision        *string `json:"revision"`
}

var dependencyName = regexp.MustCompile(`^[A-Za-z0-9_.-]+$`)
var dependencyImage = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._/:-]*$`)

// InspectDependencies enumerates literal root uses positions only. Unsupported
// shapes discard partial facts; expressions and local paths stay unresolved.
func InspectDependencies(data []byte) *DependencyInventory {
	if len(data) > MaxBytes {
		return nil
	}
	digest := sha256.Sum256(data)
	unknown := &DependencyInventory{Version: "workflow-dependencies-v1", Basis: "root_uses_declarations", SourceSHA256: hex.EncodeToString(digest[:]), Coverage: "unsupported", References: []DependencyReference{}}
	root, err := parseRoot(data)
	if err != nil {
		return unknown
	}
	jobs := field(root, "jobs")
	if jobs == nil || jobs.Kind != yaml.MappingNode || len(jobs.Content) == 0 {
		return unknown
	}
	out := *unknown
	out.Coverage = "enumerated"
	out.Counts = &DependencyCounts{}
	add := func(node *yaml.Node, job, step int, declaration string) bool {
		if node.Kind != yaml.ScalarNode || node.Tag != "!!str" {
			return false
		}
		row := classifyDependency(node.Value)
		if declaration == "job_workflow" {
			invalid := row.Kind == "docker"
			if row.Kind == "remote" {
				name, _, _ := strings.Cut(node.Value, "@")
				parts := strings.Split(name, "/")
				invalid = len(parts) != 5 || parts[2] != ".github" || parts[3] != "workflows" || !(strings.HasSuffix(parts[4], ".yml") || strings.HasSuffix(parts[4], ".yaml"))
			}
			if invalid {
				row.Kind = "unknown"
				row.Pin = "unresolved"
				row.Revision = nil
			}
		}
		row.JobIndex = job
		row.StepIndex = step
		row.Line = node.Line
		row.Declaration = declaration
		out.Counts.Declarations++
		switch dependencyClass(row) {
		case "commit":
			out.Counts.CommitPins++
		case "digest":
			out.Counts.DigestPins++
		case "floating":
			out.Counts.Floating++
		case "local":
			out.Counts.Local++
		case "expression":
			out.Counts.Expressions++
		default:
			out.Counts.Unknown++
		}
		if len(out.References) < DependencyRows {
			out.References = append(out.References, row)
		} else {
			out.RowsOmitted = true
		}
		return true
	}
	for i := 0; i < len(jobs.Content); i += 2 {
		job := jobs.Content[i+1]
		if job.Kind != yaml.MappingNode {
			return unknown
		}
		uses, steps := field(job, "uses"), field(job, "steps")
		if uses != nil {
			if steps != nil || !add(uses, i/2, -1, "job_workflow") {
				return unknown
			}
			continue
		}
		if steps == nil || steps.Kind != yaml.SequenceNode {
			return unknown
		}
		for j, step := range steps.Content {
			if step.Kind != yaml.MappingNode {
				return unknown
			}
			if uses := field(step, "uses"); uses != nil {
				if field(step, "run") != nil || !add(uses, i/2, j, "step_action") {
					return unknown
				}
			}
		}
	}
	return &out
}
func classifyDependency(value string) DependencyReference {
	digest := sha256.Sum256([]byte(value))
	row := DependencyReference{Kind: "unknown", Pin: "unresolved", ReferenceSHA256: hex.EncodeToString(digest[:])}
	if strings.Contains(value, "${{") {
		row.Kind = "expression"
		return row
	}
	if value == "" || len(value) > 2048 {
		return row
	}
	for _, c := range value {
		if unicode.IsSpace(c) || unicode.IsControl(c) {
			return row
		}
	}
	if strings.HasPrefix(value, "./") {
		row.Kind = "local"
		return row
	}
	if strings.HasPrefix(value, "docker://") {
		image := strings.TrimPrefix(value, "docker://")
		name, ref, has := strings.Cut(image, "@")
		if strings.Contains(name, "://") || !dependencyImage.MatchString(name) {
			return row
		}
		if !has {
			row.Kind = "docker"
			row.Pin = "floating"
			return row
		}
		if strings.HasPrefix(ref, "sha256:") && dependencyHash(strings.TrimPrefix(ref, "sha256:"), 64) {
			row.Kind = "docker"
			row.Pin = "digest"
			v := strings.ToLower(ref)
			row.Revision = &v
		}
		return row
	}
	name, ref, has := strings.Cut(value, "@")
	if !has || ref == "" || strings.Contains(ref, "@") {
		return row
	}
	parts := strings.Split(name, "/")
	if len(parts) < 2 {
		return row
	}
	for _, p := range parts {
		if p == "." || p == ".." || !dependencyName.MatchString(p) {
			return row
		}
	}
	row.Kind = "remote"
	row.Pin = "floating"
	if commitSHA.MatchString(ref) {
		row.Pin = "commit"
		v := strings.ToLower(ref)
		row.Revision = &v
	}
	return row
}
func dependencyClass(r DependencyReference) string {
	if r.Kind == "local" || r.Kind == "expression" {
		return r.Kind
	}
	if r.Pin == "commit" || r.Pin == "digest" || r.Pin == "floating" {
		return r.Pin
	}
	return "unknown"
}
func dependencyHash(s string, n int) bool {
	_, err := hex.DecodeString(s)
	return len(s) == n && err == nil
}

// ValidDependencyInventory checks retained metadata, not discarded source bytes.
func ValidDependencyInventory(e *DependencyInventory, digest string) bool {
	if e == nil {
		return true
	}
	if e.Version != "workflow-dependencies-v1" || e.Basis != "root_uses_declarations" || e.SourceSHA256 != digest || !dependencyHash(digest, 64) || e.References == nil || len(e.References) > DependencyRows {
		return false
	}
	if e.Coverage == "unsupported" {
		return e.Counts == nil && !e.RowsOmitted && len(e.References) == 0
	}
	c := e.Counts
	if e.Coverage != "enumerated" || c == nil || c.Declarations < 0 || c.Declarations > maxDependencyDeclarations || c.Declarations < len(e.References) || e.RowsOmitted != (c.Declarations > len(e.References)) {
		return false
	}
	total := 0
	counts := map[string]int{"commit": c.CommitPins, "digest": c.DigestPins, "floating": c.Floating, "local": c.Local, "expression": c.Expressions, "unknown": c.Unknown}
	for _, n := range counts {
		if n < 0 || n > c.Declarations {
			return false
		}
		total += n
	}
	if total != c.Declarations {
		return false
	}
	seen := map[string]bool{}
	shown := map[string]int{}
	for _, r := range e.References {
		key := strconv.Itoa(r.JobIndex) + ":" + strconv.Itoa(r.StepIndex)
		if r.JobIndex < 0 || r.JobIndex > maxDependencyDeclarations || r.StepIndex < -1 || r.StepIndex > maxNodes || r.Line < 1 || r.Line > MaxBytes || seen[key] || !dependencyHash(r.ReferenceSHA256, 64) || r.ReferenceSHA256 != strings.ToLower(r.ReferenceSHA256) {
			return false
		}
		seen[key] = true
		if r.Declaration == "job_workflow" {
			if r.StepIndex != -1 {
				return false
			}
		} else if r.Declaration != "step_action" || r.StepIndex < 0 {
			return false
		}
		switch r.Kind {
		case "remote":
			if r.Pin != "commit" && r.Pin != "floating" {
				return false
			}
		case "docker":
			if r.Declaration != "step_action" || r.Pin != "digest" && r.Pin != "floating" {
				return false
			}
		case "local", "expression", "unknown":
			if r.Pin != "unresolved" {
				return false
			}
		default:
			return false
		}
		if r.Pin == "commit" {
			if r.Revision == nil || !dependencyHash(*r.Revision, 40) {
				return false
			}
		} else if r.Pin == "digest" {
			if r.Revision == nil || !strings.HasPrefix(*r.Revision, "sha256:") || !dependencyHash(strings.TrimPrefix(*r.Revision, "sha256:"), 64) {
				return false
			}
		} else if r.Revision != nil {
			return false
		}
		shown[dependencyClass(r)]++
	}
	for kind, n := range counts {
		if n < shown[kind] || n-shown[kind] > c.Declarations-len(e.References) {
			return false
		}
	}
	return true
}

