func dependencyFixture() []byte {
	return []byte("on: push\njobs:\n  private_job:\n    runs-on: linux\n    steps:\n      - uses: private_owner/private_repo@" + strings.Repeat("a", 40) + "\n      - uses: docker://private_image@sha256:" + strings.Repeat("b", 64) + "\n      - uses: private_owner/private_repo@main\n      - uses: ./private-action\n      - uses: ${{ inputs.private_action }}\n      - uses: unrecognised-private-value\n  private_reusable:\n    uses: private_owner/private_repo/.github/workflows/private.yml@" + strings.Repeat("c", 40) + "\n")
}
func TestRootDependencyInventoryDistinguishesLiteralPinsFromUnresolvedReferencesWithoutNames(t *testing.T) {
	e := InspectDependencies(dependencyFixture())
	if !ValidDependencyInventory(e, e.SourceSHA256) || e.Coverage != "enumerated" || e.Counts == nil || *e.Counts != (DependencyCounts{Declarations: 7, CommitPins: 2, DigestPins: 1, Floating: 1, Local: 1, Expressions: 1, Unknown: 1}) {
		t.Fatalf("wrong root inventory: %+v", e)
	}
	if e.References[6].Declaration != "job_workflow" || e.References[6].StepIndex != -1 || e.References[0].Revision == nil || e.References[3].Revision != nil {
		t.Fatal("invented resolution or lost positions")
	}
	b, _ := json.Marshal(e)
	for _, text := range []string{"private_", "private-", "private.yml", "inputs.", "runs-on", "uses:"} {
		if strings.Contains(string(b), text) {
			t.Fatalf("retained raw repository text %s", text)
		}
	}
}
func TestRootDependencyInventoryDiscardsPartialFactsForUnsupportedYAML(t *testing.T) {
	for _, data := range []string{
		"jobs: {a: {steps: [{uses: actions/checkout@main}, {uses: [bad]}]}}",
		"jobs: {a: {steps: [{uses: actions/checkout@main, run: echo private}]}}",
		"jobs: {a: &private {steps: []}, b: *private}",
		"jobs: {a: {steps: [], steps: []}}", "jobs: {}", "jobs: []",
		"jobs: {a: {steps: []}}\n---\njobs: {}", strings.Repeat("x", MaxBytes+1),
	} {
		e := InspectDependencies([]byte(data))
		if len(data) > MaxBytes {
			if e != nil {
				t.Fatal("oversized data retained")
			}
			continue
		}
		if e.Coverage != "unsupported" || e.Counts != nil || len(e.References) != 0 || e.RowsOmitted || !ValidDependencyInventory(e, e.SourceSHA256) {
			t.Fatalf("partial/zero facts invented: %+v", e)
		}
	}
}
func TestRootDependencyInventoryBoundsRowsWithoutClippingFullCounts(t *testing.T) {
	data := "jobs:\n  private:\n    steps:\n" + strings.Repeat("      - uses: private_owner/private_repo@main\n", 101)
	e := InspectDependencies([]byte(data))
	if !ValidDependencyInventory(e, e.SourceSHA256) || !e.RowsOmitted || len(e.References) != 100 || e.Counts.Declarations != 101 || e.Counts.Floating != 101 {
		t.Fatal("full inventory lost under row bounds")
	}
}
func TestRootDependencyInventoryNeverTreatsMalformedWorkflowOrImageReferencesAsPins(t *testing.T) {
	for _, uses := range []string{"docker://image@sha256:not-a-digest", "docker://https://private@sha256:" + strings.Repeat("a", 64), "owner/repo@" + strings.Repeat("a", 39), "private @" + strings.Repeat("a", 40)} {
		e := InspectDependencies([]byte("jobs: {a: {steps: [{uses: '" + uses + "'}]}}"))
		if !ValidDependencyInventory(e, e.SourceSHA256) || e.Counts.CommitPins != 0 || e.Counts.DigestPins != 0 {
			t.Fatalf("malformed literal promoted: %+v", e)
		}
	}
	for _, uses := range []string{"owner/repo@" + strings.Repeat("a", 40), "docker://image@sha256:" + strings.Repeat("a", 64)} {
		e := InspectDependencies([]byte("jobs: {a: {uses: '" + uses + "'}}"))
		if !ValidDependencyInventory(e, e.SourceSHA256) || e.Counts.Unknown != 1 {
			t.Fatal("non-workflow job reference promoted")
		}
	}
}
func TestRetainedDependencyInventoryRefusesContradictoryCountsBindingsAndPositions(t *testing.T) {
	for _, mode := range []string{"version", "digest", "count", "omitted", "position", "fingerprint", "pin", "revision", "unknown_coverage"} {
		e := InspectDependencies(dependencyFixture())
		original := e.SourceSHA256
		switch mode {
		case "version":
			e.Version = "future"
		case "digest":
			e.SourceSHA256 = strings.Repeat("e", 64)
		case "count":
			e.Counts.CommitPins++
		case "omitted":
			e.RowsOmitted = true
		case "position":
			e.References[1].StepIndex = e.References[0].StepIndex
		case "fingerprint":
			e.References[0].ReferenceSHA256 = "private"
		case "pin":
			e.References[0].Pin = "digest"
		case "revision":
			e.References[0].Revision = nil
		case "unknown_coverage":
			e.Coverage = "complete_transitive_graph"
		}
		if ValidDependencyInventory(e, original) {
			t.Fatalf("%s accepted", mode)
		}
	}
}

func FuzzDependencyInventoriesPreserveTheirRetainedInvariants(f *testing.F) {
	f.Add(dependencyFixture())
	f.Add([]byte("jobs: {a: &x {steps: []}, b: *x}"))
	f.Add([]byte("jobs: {a: {uses: owner/repo/.github/workflows/a.yml@main}}"))
	f.Fuzz(func(t *testing.T, data []byte) {
		e := InspectDependencies(data)
		if len(data) > MaxBytes {
			if e != nil {
				t.Fatal("oversized data retained")
			}
			return
		}
		if e == nil || !ValidDependencyInventory(e, e.SourceSHA256) {
			t.Fatal("parser produced inconsistent private metadata")
		}
	})
}

func TestRootUsesEnumerationDistinguishesKnownZeroFromUnsupportedUnknown(t *testing.T) {
	e := InspectDependencies([]byte("jobs: {private_job: {steps: [{run: 'private script imports dependencies'}]}}"))
	if e.Coverage != "enumerated" || e.Counts == nil || e.Counts.Declarations != 0 || !ValidDependencyInventory(e, e.SourceSHA256) {
		t.Fatal("known absence of root uses became unknown")
	}
	raw, _ := json.Marshal(e)
	if strings.Contains(string(raw), "private") {
		t.Fatal("script text retained")
	}
	unknown := InspectDependencies([]byte("jobs: unsupported"))
	if unknown.Counts != nil || unknown.Coverage != "unsupported" {
		t.Fatal("unsupported inventory became zero")
	}
}

package workflow

import (
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
)

var pinnedRef = regexp.MustCompile(`@[a-f0-9]{40}`)

// This repository holds its own workflows to several of these rules, in
// internal/docs: every action is pinned to a commit, no workflow grants write
// to every job. The parser is held to the same files: every one readable, no
// unpinned reference, no secret on a command line, no checkout of a pull
// request's head under pull_request_target; and with one pin stripped from a
// file, exactly one unpinned reference, placed at the step it belongs to. If
// the parser and the repository's own tests ever disagree, one of them is
// wrong.
func TestKennelAgreesWithTheRepositorysOwnWorkflows(t *testing.T) {
	files, err := filepath.Glob(filepath.Join("..", "..", "..", ".github", "workflows", "*.yml"))
	if err != nil || len(files) == 0 {
		t.Fatalf("no workflows found: %v", err)
	}
	for _, path := range files {
		data, err := os.ReadFile(path)
		if err != nil {
			t.Fatal(err)
		}
		facts, err := Inspect(data)
		if err != nil {
			t.Errorf("%s: the parser refused this repository's own workflow: %v", filepath.Base(path), err)
			continue
		}
		if n := len(facts.FirstPartyUnpinned) + len(facts.OtherUnpinned); n != 0 {
			t.Errorf("%s: %d unpinned references, and this repository pins every action", filepath.Base(path), n)
		}
		if len(facts.SecretOnCommandLine) != 0 || len(facts.TargetCheckoutPRHead) != 0 {
			t.Errorf("%s: a secret on a command line or a checkout of a pull request's head: %+v", filepath.Base(path), facts)
		}
		loc := pinnedRef.FindIndex(data)
		if loc == nil {
			continue
		}
		stripped := string(data[:loc[0]]) + "@v1" + string(data[loc[1]:])
		line := stepLine(string(data), strings.Count(string(data[:loc[0]]), "\n"))
		after, err := Inspect([]byte(stripped))
		if err != nil {
			t.Errorf("%s: stripping a pin made the file unreadable: %v", filepath.Base(path), err)
			continue
		}
		unpinned := append(after.FirstPartyUnpinned, after.OtherUnpinned...)
		if len(unpinned) != 1 || unpinned[0].Line != line {
			t.Errorf("%s: with the pin on line %d stripped, unpinned = %v, want that one line", filepath.Base(path), line, unpinned)
		}
	}
}

var stepStart = regexp.MustCompile(`^\s*- `)

// stepLine is the 1-based line of the step that holds line index i: a
// finding points at a step's first key, which is where a person looks for it,
// and the pin may sit on a later key of the same step.
func stepLine(data string, i int) int {
	lines := strings.Split(data, "\n")
	for ; i > 0; i-- {
		if stepStart.MatchString(lines[i]) {
			break
		}
	}
	return i + 1
}

package workflow

import (
	"encoding/json"
	"regexp"
	"strings"
	"testing"
)

// keysAndNull is what a marshalled Facts is allowed to say in letters: its
// field names and the null of an absent location. Everything else in it is
// digits and punctuation, and must stay so.
var keysAndNull = regexp.MustCompile(`"[a-z_]+":|null`)

// A workflow file is written by whoever can open a pull request against a
// served repository, so the parser is fuzzed: it must return, within its
// limits, for any bytes, and what it returns must marshal without carrying
// any of the input's text. The type makes that true today; the fuzz target is
// what catches a field added later that carries a name or an expression.
func FuzzInspect(f *testing.F) {
	for _, seed := range []string{
		"on: push\njobs:\n  a:\n    runs-on: x\n    steps:\n      - uses: actions/checkout@v4\n      - run: echo ${{ secrets.T }}\n",
		"on: pull_request_target\njobs:\n  a:\n    runs-on: x\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          ref: ${{ github.head_ref }}\n",
		"jobs: {a: {runs-on: [self-hosted, linux], steps: []}}",
		"jobs: &j {a: {runs-on: x, steps: []}}",
		"",
	} {
		f.Add([]byte(seed))
	}
	f.Fuzz(func(t *testing.T, data []byte) {
		facts, err := Inspect(data)
		if err != nil {
			return
		}
		if facts.Jobs == 0 {
			t.Fatal("a workflow without jobs was accepted")
		}
		out, err := json.Marshal(facts)
		if err != nil {
			t.Fatal(err)
		}
		if leaked := inputTextIn(string(data), keysAndNull.ReplaceAllString(string(out), "")); leaked != "" {
			t.Fatalf("the facts carry %q from the input: %s", leaked, out)
		}
	})
}

// inputTextIn returns the first run of four or more printable bytes of the
// input, holding at least one letter, that appears in the marshalled facts.
func inputTextIn(input, marshalled string) string {
	for _, run := range strings.FieldsFunc(input, func(r rune) bool { return r < 0x21 || r > 0x7e }) {
		if len(run) >= 4 && strings.ContainsFunc(run, func(r rune) bool { return r >= 'A' && r <= 'z' }) && strings.Contains(marshalled, run) {
			return run
		}
	}
	return ""
}

// The guard above is only worth having if it fires: a marshalled document
// that did carry a line of the input must be caught.
func TestTheFuzzGuardCatchesInputTextInTheFacts(t *testing.T) {
	input := "jobs:\n  build:\n    runs-on: secret-pool\n"
	if got := inputTextIn(input, `{"jobs":1,"runs_on":"secret-pool"}`); got != "secret-pool" {
		t.Fatalf("leak = %q, want secret-pool", got)
	}
	if got := inputTextIn(input, `{"jobs":1,"line":12}`); got != "" {
		t.Fatalf("a document of numbers was taken for a leak: %q", got)
	}
}

// Package workflow reads a GitHub Actions workflow file and says, by position,
// what Kennel Club's checks want to know about it: which job has no timeout,
// which reference is not pinned, which step puts a secret on a command line.
//
// It is the one place repository text is parsed, and it keeps none of it: a
// fact is a job index and a line, so a finding can say where without saying
// what, and the raw file is discarded when Inspect returns. The parse is
// bounded and conservative, because the file is written by whoever can open a
// pull request against a served repository: a shape it does not understand is
// refused as a whole, never judged in part, and an expression it cannot read
// is unknown rather than wrong.
package workflow

import (
	"bytes"
	"errors"
	"io"
	"regexp"
	"strings"
	"unicode/utf8"

	"gopkg.in/yaml.v3"
)

// MaxBytes is the largest file Inspect reads. The inventory skips a larger
// one, and the collector reports it as unreadable.
const MaxBytes = 256 * 1024

const (
	maxNodes = 20000
	maxDepth = 50
)

// Location says where a fact is: the job it belongs to, by its position in
// the file's `jobs` mapping, and the line of the thing itself. JobIndex is -1
// for a fact about the workflow as a whole. A job's line is the line of its
// key; a step's is the line of its first key; the workflow's is its `on` key.
type Location struct {
	JobIndex int `json:"job_index"`
	Line     int `json:"line"`
}

// RunsOn is one job's literal runs-on labels. They are a workflow author's
// text, so they are kept in memory for the controller's membership test and
// never marshalled; a job whose runs-on holds an expression or a runner
// group is left out, because it cannot be judged.
type RunsOn struct {
	Location
	Labels []string `json:"-"`
}

// Facts is what one workflow file says, as positions and counts.
type Facts struct {
	// Jobs is how many job declarations the file holds, executable and
	// reusable alike.
	Jobs int `json:"jobs"`
	// Pinned is how many external references are pinned to a commit or an
	// image digest, for the check that asks whether anything moves the pins.
	Pinned int `json:"pinned"`
	// NoTimeout is each executable job without a timeout-minutes.
	NoTimeout []Location `json:"no_timeout,omitempty"`
	// NoConcurrency is the `on` key of a pull-request-only workflow that
	// cancels nothing, at workflow level or on every job; nil otherwise.
	NoConcurrency *Location `json:"no_concurrency,omitempty"`
	// FirstPartyUnpinned and OtherUnpinned are each `uses` of an external
	// action, reusable workflow or Docker image that is not a commit or a
	// digest, by who publishes it.
	FirstPartyUnpinned []Location `json:"first_party_unpinned,omitempty"`
	OtherUnpinned      []Location `json:"other_unpinned,omitempty"`
	// PermissionsUnset is each job with no permissions block of its own or
	// its workflow's.
	PermissionsUnset []Location `json:"permissions_unset,omitempty"`
	// TargetCheckoutPRHead is each checkout step under pull_request_target
	// that takes the pull request's head.
	TargetCheckoutPRHead []Location `json:"target_checkout_pr_head,omitempty"`
	// SecretOnCommandLine is each step whose run line or args interpolates a
	// secret.
	SecretOnCommandLine []Location `json:"secret_on_command_line,omitempty"`
	// RunsOn is each job's literal labels, in memory only.
	RunsOn []RunsOn `json:"-"`
}

var (
	errUnsupported = errors.New("workflow is malformed or exceeds the supported YAML shape")
	commitSHA      = regexp.MustCompile(`^[a-fA-F0-9]{40}$`)
	imageDigest    = regexp.MustCompile(`@sha256:[a-fA-F0-9]{64}$`)
)

// Inspect reads one workflow file. It refuses aliases, anchors and merge keys
// on purpose: resolving an arbitrary graph is unbounded work, and it obscures
// which declaration supplied a value. The caller records an unreadable file.
func Inspect(data []byte) (Facts, error) {
	var out Facts
	root, err := parseRoot(data)
	if err != nil {
		return Facts{}, err
	}
	jobs := field(root, "jobs")
	if jobs == nil || jobs.Kind != yaml.MappingNode || len(jobs.Content) == 0 {
		return Facts{}, errUnsupported
	}
	if !validPermissions(field(root, "permissions")) {
		return Facts{}, errUnsupported
	}
	onKey, onValue := keyAndValue(root, "on")
	events, ok := eventsOf(onValue)
	if !ok {
		return Facts{}, errUnsupported
	}
	onlyPR := len(events) > 0 && every(events, func(e string) bool { return e == "pull_request" || e == "pull_request_target" })
	target := contains(events, "pull_request_target")
	allJobsCancel := true
	for i := 0; i < len(jobs.Content); i += 2 {
		index := i / 2
		job := jobs.Content[i+1]
		at := Location{JobIndex: index, Line: jobs.Content[i].Line}
		if job.Kind != yaml.MappingNode {
			return Facts{}, errUnsupported
		}
		out.Jobs++
		if !validPermissions(field(job, "permissions")) {
			return Facts{}, errUnsupported
		}
		if !declared(field(root, "permissions")) && !declared(field(job, "permissions")) {
			out.PermissionsUnset = append(out.PermissionsUnset, at)
		}
		if !cancels(field(job, "concurrency")) {
			allJobsCancel = false
		}
		if usesKey, uses := keyAndValue(job, "uses"); uses != nil {
			// A reusable job's reference is its own line, as a step's is.
			if uses.Kind != yaml.ScalarNode || !out.reference(uses.Value, Location{JobIndex: index, Line: usesKey.Line}) {
				return Facts{}, errUnsupported
			}
			continue
		}
		steps := field(job, "steps")
		runsOn := field(job, "runs-on")
		if steps == nil || steps.Kind != yaml.SequenceNode || !declared(runsOn) {
			return Facts{}, errUnsupported
		}
		if !declared(field(job, "timeout-minutes")) {
			out.NoTimeout = append(out.NoTimeout, at)
		}
		if labels, ok := literalLabels(runsOn); ok {
			out.RunsOn = append(out.RunsOn, RunsOn{Location: Location{JobIndex: index, Line: runsOnLine(job)}, Labels: labels})
		}
		for _, step := range steps.Content {
			if step.Kind != yaml.MappingNode || len(step.Content) == 0 {
				return Facts{}, errUnsupported
			}
			stepAt := Location{JobIndex: index, Line: step.Content[0].Line}
			uses := field(step, "uses")
			if uses != nil {
				if uses.Kind != yaml.ScalarNode || !out.reference(uses.Value, stepAt) {
					return Facts{}, errUnsupported
				}
				if target && isCheckout(uses.Value) && takesPullRequestHead(field(step, "with")) {
					out.TargetCheckoutPRHead = append(out.TargetCheckoutPRHead, stepAt)
				}
			}
			if secretOnCommandLine(field(step, "run")) || secretOnCommandLine(field(field(step, "with"), "args")) {
				out.SecretOnCommandLine = append(out.SecretOnCommandLine, stepAt)
			}
		}
	}
	if onlyPR && !cancels(field(root, "concurrency")) && !allJobsCancel {
		out.NoConcurrency = &Location{JobIndex: -1, Line: onKey.Line}
	}
	return out, nil
}

// bounded walks the document once, refusing what the walker will not read:
// too many nodes, too deep, an alias, an anchor, a merge key, a duplicate key.
func bounded(doc *yaml.Node) bool {
	count := 0
	var walk func(*yaml.Node, int) bool
	walk = func(n *yaml.Node, depth int) bool {
		count++
		if count > maxNodes || depth > maxDepth || n.Kind == yaml.AliasNode || n.Anchor != "" || n.Tag == "!!merge" {
			return false
		}
		if n.Kind == yaml.MappingNode {
			if len(n.Content)%2 != 0 {
				return false
			}
			keys := map[string]bool{}
			for i := 0; i < len(n.Content); i += 2 {
				k := n.Content[i]
				if k.Kind != yaml.ScalarNode || keys[k.Value] {
					return false
				}
				keys[k.Value] = true
			}
		}
		for _, ch := range n.Content {
			if !walk(ch, depth+1) {
				return false
			}
		}
		return true
	}
	return walk(doc, 0)
}

// reference classes one `uses`: pinned, unpinned by publisher, or local. An
// expression in it is a shape the walker refuses, because the reference could
// be anything.
func (f *Facts) reference(uses string, at Location) bool {
	if strings.Contains(uses, "${{") {
		return false
	}
	if strings.HasPrefix(uses, "./") {
		return true
	}
	if strings.HasPrefix(uses, "docker://") {
		if imageDigest.MatchString(uses) {
			f.Pinned++
		} else {
			f.OtherUnpinned = append(f.OtherUnpinned, at)
		}
		return true
	}
	if _, ref, ok := strings.Cut(uses, "@"); ok && commitSHA.MatchString(ref) {
		f.Pinned++
		return true
	}
	lower := strings.ToLower(uses)
	if strings.HasPrefix(lower, "actions/") || strings.HasPrefix(lower, "github/") {
		f.FirstPartyUnpinned = append(f.FirstPartyUnpinned, at)
	} else {
		f.OtherUnpinned = append(f.OtherUnpinned, at)
	}
	return true
}

func field(n *yaml.Node, key string) *yaml.Node {
	_, v := keyAndValue(n, key)
	return v
}

func keyAndValue(n *yaml.Node, key string) (*yaml.Node, *yaml.Node) {
	if n == nil || n.Kind != yaml.MappingNode {
		return nil, nil
	}
	for i := 0; i < len(n.Content); i += 2 {
		if n.Content[i].Value == key {
			return n.Content[i], n.Content[i+1]
		}
	}
	return nil, nil
}

func runsOnLine(job *yaml.Node) int {
	k, _ := keyAndValue(job, "runs-on")
	if k == nil {
		return 0
	}
	return k.Line
}

func declared(n *yaml.Node) bool {
	return n != nil && n.Tag != "!!null" && (n.Kind != yaml.ScalarNode || strings.TrimSpace(n.Value) != "")
}

// validPermissions is whether a permissions block has a shape the walker
// understands: absent, a mapping of read/write/none, or read-all/write-all.
func validPermissions(n *yaml.Node) bool {
	if !declared(n) {
		return true
	}
	if n.Kind == yaml.MappingNode {
		for i := 1; i < len(n.Content); i += 2 {
			v := n.Content[i]
			if v.Kind != yaml.ScalarNode || (v.Value != "read" && v.Value != "write" && v.Value != "none") {
				return false
			}
		}
		return true
	}
	return n.Kind == yaml.ScalarNode && (n.Value == "read-all" || n.Value == "write-all")
}

// eventsOf lists the events an `on` names; ok is false for a shape it does
// not understand, and an absent `on` is no events.
func eventsOf(n *yaml.Node) ([]string, bool) {
	if n == nil {
		return nil, true
	}
	var events []string
	switch n.Kind {
	case yaml.ScalarNode:
		events = append(events, n.Value)
	case yaml.SequenceNode:
		for _, e := range n.Content {
			if e.Kind != yaml.ScalarNode {
				return nil, false
			}
			events = append(events, e.Value)
		}
	case yaml.MappingNode:
		for i := 0; i < len(n.Content); i += 2 {
			events = append(events, n.Content[i].Value)
		}
	default:
		return nil, false
	}
	return events, true
}

func cancels(n *yaml.Node) bool {
	if n == nil || n.Kind != yaml.MappingNode || !declared(field(n, "group")) {
		return false
	}
	cancel := field(n, "cancel-in-progress")
	// An expression cannot be evaluated statically; a declared one is left to
	// its author rather than guessed to be false.
	return declared(cancel) && (cancel.Value == "true" || strings.Contains(cancel.Value, "${{"))
}

// literalLabels is a job's runs-on as labels, when every one is literal.
func literalLabels(n *yaml.Node) ([]string, bool) {
	switch n.Kind {
	case yaml.ScalarNode:
		if strings.Contains(n.Value, "${{") {
			return nil, false
		}
		return []string{n.Value}, true
	case yaml.SequenceNode:
		var labels []string
		for _, e := range n.Content {
			if e.Kind != yaml.ScalarNode || strings.Contains(e.Value, "${{") {
				return nil, false
			}
			labels = append(labels, e.Value)
		}
		return labels, len(labels) > 0
	}
	return nil, false
}

func isCheckout(uses string) bool {
	return strings.HasPrefix(strings.ToLower(uses), "actions/checkout@")
}

// takesPullRequestHead is whether a checkout's `ref` names the pull request's
// head, which under pull_request_target is the stranger's code checked out
// beside the repository's token.
func takesPullRequestHead(with *yaml.Node) bool {
	ref := field(with, "ref")
	if ref == nil || ref.Kind != yaml.ScalarNode {
		return false
	}
	return strings.Contains(ref.Value, "github.event.pull_request.head") || strings.Contains(ref.Value, "github.head_ref")
}

func secretOnCommandLine(n *yaml.Node) bool {
	return n != nil && n.Kind == yaml.ScalarNode && strings.Contains(n.Value, "${{ secrets.")
}

func every(xs []string, f func(string) bool) bool {
	for _, x := range xs {
		if !f(x) {
			return false
		}
	}
	return true
}

func contains(xs []string, s string) bool {
	for _, x := range xs {
		if x == s {
			return true
		}
	}
	return false
}

// Share the same graph bounds and refusal rules across repository inspectors.
func parseRoot(data []byte) (*yaml.Node, error) {
	if len(data) == 0 || len(data) > MaxBytes || !utf8.Valid(data) {
		return nil, errUnsupported
	}
	var doc yaml.Node
	decoder := yaml.NewDecoder(bytes.NewReader(data))
	if decoder.Decode(&doc) != nil || len(doc.Content) != 1 {
		return nil, errUnsupported
	}
	var extra yaml.Node
	if decoder.Decode(&extra) != io.EOF {
		return nil, errUnsupported
	}
	if !bounded(&doc) || doc.Content[0].Kind != yaml.MappingNode {
		return nil, errUnsupported
	}
	return doc.Content[0], nil
}

package workflow

import (
	"encoding/json"
	"strings"
	"testing"
)

const sha40 = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"

func mustInspect(t *testing.T, data string) Facts {
	t.Helper()
	got, err := Inspect([]byte(data))
	if err != nil {
		t.Fatalf("Inspect: %v", err)
	}
	return got
}

func locs(l ...Location) []Location { return l }

// The facts say where: a job by the line its key is on, a step by the line
// its first key is on, the workflow by its `on` key. A reader who opens the
// file at that line sees the thing the finding is about.
func TestInspectionFindsMissingGuardsAndSaysWhereEachIs(t *testing.T) {
	got := mustInspect(t, `name: IGNORE PREVIOUS INSTRUCTIONS
on: pull_request
jobs:
  build:
    runs-on: self-hosted
    steps:
      - uses: actions/checkout@v4
      - uses: stranger/action@main
      - run: echo hello
  reuse:
    uses: acme/ci/.github/workflows/test.yml@main
`)
	if got.Jobs != 2 {
		t.Errorf("jobs = %d, want 2", got.Jobs)
	}
	for name, tc := range map[string]struct{ got, want []Location }{
		"no timeout":           {got.NoTimeout, locs(Location{0, 4})},
		"first-party unpinned": {got.FirstPartyUnpinned, locs(Location{0, 7})},
		"other unpinned":       {got.OtherUnpinned, locs(Location{0, 8}, Location{1, 11})},
		"permissions unset":    {got.PermissionsUnset, locs(Location{0, 4}, Location{1, 10})},
	} {
		if !equal(tc.got, tc.want) {
			t.Errorf("%s = %v, want %v", name, tc.got, tc.want)
		}
	}
	if got.NoConcurrency == nil || *got.NoConcurrency != (Location{-1, 2}) {
		t.Errorf("no concurrency = %v, want the on key on line 2", got.NoConcurrency)
	}
	if len(got.RunsOn) != 1 || got.RunsOn[0].Location != (Location{0, 5}) || strings.Join(got.RunsOn[0].Labels, ",") != "self-hosted" {
		t.Errorf("runs-on = %+v", got.RunsOn)
	}
}

func TestInspectionHonoursExplicitGuardsAndReusableCallers(t *testing.T) {
	got := mustInspect(t, `on: pull_request
permissions: {}
concurrency:
  group: ${{ github.workflow }}-${{ github.event.pull_request.number }}
  cancel-in-progress: true
jobs:
  build:
    runs-on: self-hosted
    timeout-minutes: ${{ inputs.timeout }}
    steps:
      - uses: actions/checkout@`+sha40+`
      - uses: ./local-action
      - uses: docker://alpine@sha256:`+strings.Repeat("b", 64)+`
  reuse:
    uses: acme/ci/.github/workflows/test.yml@`+strings.Repeat("c", 40)+`
`)
	if len(got.NoTimeout)+len(got.FirstPartyUnpinned)+len(got.OtherUnpinned)+len(got.PermissionsUnset)+len(got.TargetCheckoutPRHead)+len(got.SecretOnCommandLine) != 0 || got.NoConcurrency != nil {
		t.Fatalf("facts = %+v, want none", got)
	}
	// The checkout, the Docker image and the reusable workflow are each a
	// pinned external reference; the local action is not external.
	if got.Jobs != 2 || got.Pinned != 3 {
		t.Errorf("jobs %d pinned %d, want 2 and 3", got.Jobs, got.Pinned)
	}
}

// An expression cannot be read statically. A timeout that is one is unknown,
// not missing, because precision comes before recall: a finding an author
// learns to ignore is worse than none.
func TestAnExpressionTimeoutIsUnknownNotMissing(t *testing.T) {
	got := mustInspect(t, "on: push\njobs:\n  a:\n    runs-on: x\n    timeout-minutes: ${{ inputs.t }}\n    permissions: {}\n    steps: []\n")
	if len(got.NoTimeout) != 0 {
		t.Fatalf("no timeout = %v for an expression", got.NoTimeout)
	}
}

func TestConcurrencyAdviceIsLimitedToPullRequestOnlyWorkflows(t *testing.T) {
	for _, tt := range []struct {
		on   string
		want bool
	}{
		{"pull_request", true}, {"[pull_request, pull_request_target]", true}, {"{pull_request: {branches: [main]}}", true},
		{"[push, pull_request]", false}, {"workflow_dispatch", false}, {"{release: {types: [published]}}", false},
	} {
		got := mustInspect(t, "on: "+tt.on+"\njobs:\n  build:\n    runs-on: self-hosted\n    steps: []\n")
		if (got.NoConcurrency != nil) != tt.want {
			t.Errorf("%s: no concurrency = %v, want %v", tt.on, got.NoConcurrency, tt.want)
		}
	}
	got := mustInspect(t, `on: pull_request
jobs:
  build:
    runs-on: self-hosted
    concurrency: {group: '${{ github.job }}-${{ github.ref }}', cancel-in-progress: true}
    permissions: {contents: read}
    steps: []
`)
	if got.NoConcurrency != nil || len(got.PermissionsUnset) != 0 {
		t.Fatalf("job guards = %+v", got)
	}
}

// A pull_request_target workflow runs on the default branch with the
// repository's token, and a checkout of the pull request's head hands that
// token to the stranger's code. The same checkout under pull_request runs
// with the fork's lesser token and is nothing to say.
func TestACheckoutOfThePullRequestHeadUnderPullRequestTargetIsLocated(t *testing.T) {
	body := `
jobs:
  build:
    runs-on: ubuntu-latest
    timeout-minutes: 5
    permissions: {}
    steps:
      - uses: actions/checkout@` + sha40 + `
        with:
          ref: ${{ github.event.pull_request.head.sha }}
`
	if got := mustInspect(t, "on: pull_request_target"+body); !equal(got.TargetCheckoutPRHead, locs(Location{0, 8})) {
		t.Errorf("under pull_request_target = %v, want the step on line 8", got.TargetCheckoutPRHead)
	}
	if got := mustInspect(t, "on: pull_request"+body); len(got.TargetCheckoutPRHead) != 0 {
		t.Errorf("under pull_request = %v, want none", got.TargetCheckoutPRHead)
	}
	headRef := strings.Replace(body, "${{ github.event.pull_request.head.sha }}", "${{ github.head_ref }}", 1)
	if got := mustInspect(t, "on: [push, pull_request_target]"+headRef); len(got.TargetCheckoutPRHead) != 1 {
		t.Errorf("head_ref under a mixed on = %v, want one", got.TargetCheckoutPRHead)
	}
}

// A secret on a command line reaches the process list and the log; the env
// block is the safe form, and nothing else is scanned.
func TestASecretInterpolatedIntoARunLineOrArgsIsLocatedAndOneInEnvIsNot(t *testing.T) {
	got := mustInspect(t, `on: push
jobs:
  a:
    runs-on: x
    timeout-minutes: 5
    permissions: {}
    steps:
      - run: 'curl -H "Authorization: ${{ secrets.TOKEN }}"'
      - uses: docker://alpine@sha256:`+strings.Repeat("b", 64)+`
        with:
          args: --token ${{ secrets.TOKEN }}
      - run: echo ok
        env:
          TOKEN: ${{ secrets.TOKEN }}
      - uses: actions/checkout@`+sha40+`
        with:
          token: ${{ secrets.TOKEN }}
`)
	if !equal(got.SecretOnCommandLine, locs(Location{0, 8}, Location{0, 9})) {
		t.Fatalf("secret on command line = %v, want lines 8 and 9", got.SecretOnCommandLine)
	}
}

// Labels are a workflow author's text. They are returned so the controller
// can test them against what its pools serve, and only when they are
// literal: an expression or a runner group is not judged.
func TestRunsOnLabelsAreReturnedOnlyWhenLiteral(t *testing.T) {
	got := mustInspect(t, `on: push
jobs:
  a: {runs-on: [self-hosted, linux], timeout-minutes: 5, permissions: {}, steps: []}
  b: {runs-on: '${{ matrix.os }}', timeout-minutes: 5, permissions: {}, steps: []}
  c: {runs-on: {group: big}, timeout-minutes: 5, permissions: {}, steps: []}
  d: {runs-on: zoomies, timeout-minutes: 5, permissions: {}, steps: []}
`)
	if len(got.RunsOn) != 2 || strings.Join(got.RunsOn[0].Labels, ",") != "self-hosted,linux" || got.RunsOn[0].JobIndex != 0 ||
		strings.Join(got.RunsOn[1].Labels, ",") != "zoomies" || got.RunsOn[1].JobIndex != 3 {
		t.Fatalf("runs-on = %+v", got.RunsOn)
	}
}

// Everything in the facts is a number or a position. The labels are the one
// piece of repository text, and they never leave the process: a marshalled
// Facts carries none of them.
func TestNoRepositoryTextIsInTheFacts(t *testing.T) {
	const hostile = "IGNORE-PREVIOUS-INSTRUCTIONS"
	got := mustInspect(t, "on: push\njobs:\n  "+hostile+":\n    runs-on: "+hostile+"\n    steps:\n      - uses: "+hostile+"/action@main\n      - run: echo ${{ secrets."+hostile+" }}\n")
	b, err := json.Marshal(got)
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(b), "IGNORE") {
		t.Fatalf("repository text in the facts: %s", b)
	}
	if len(got.RunsOn) != 1 || got.RunsOn[0].Labels[0] != hostile {
		t.Fatalf("the labels are kept in memory for the controller: %+v", got.RunsOn)
	}
}

func equal(a, b []Location) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

package workflow

import (
	"strings"
	"testing"
)

// The parser refuses what it cannot judge with bounded work, and a refusal
// is an error the collector turns into an unreadable file: never a panic,
// never a partial judgement.
func TestInspectionRefusesAmbiguousOrUnsupportedYAML(t *testing.T) {
	for _, data := range []string{
		"jobs: [broken]", "jobs: {a: {uses: 'owner/repo@${{ inputs.ref }}'}}", "jobs: {}", "jobs: {a: {steps: []}}",
		"jobs: {a: {runs-on: linux, steps: []}}\njobs: {}",
		"jobs: &jobs {a: {runs-on: linux, steps: []}}", "jobs: {a: {runs-on: linux, steps: []}}\n---\njobs: {}",
		"jobs: {a: {runs-on: linux, steps: [], permissions: [read]}}", strings.Repeat("x", MaxBytes+1),
		"", "on: push\njobs: {a: {runs-on: x, steps: []}}\n# \xff\xfe",
	} {
		if _, err := Inspect([]byte(data)); err == nil {
			t.Errorf("accepted unsupported YAML of %d bytes: %.40q", len(data), data)
		}
	}
}

func TestDeepNestingIsRefusedWithoutExhaustingTheStack(t *testing.T) {
	data := "jobs:\n  a:\n    runs-on: x\n    steps: []\n    deep: " + strings.Repeat("[", 400) + strings.Repeat("]", 400) + "\n"
	if _, err := Inspect([]byte(data)); err == nil {
		t.Fatal("accepted 400 levels of nesting")
	}
}

package workflow

import (
	"go/ast"
	"go/parser"
	"go/token"
	"path/filepath"
	"slices"
	"strconv"
	"strings"
	"testing"
)

// The parser is shared by the controller's collector and by the offline
// zoomies kennel check, and the second of those must run on a laptop with no
// controller and no GitHub client. So it may import the standard library's
// pure parts and the YAML library, and nothing from this module: the moment it
// reaches for the store, the GitHub package or the controller, the offline
// command would drag them along. A deliberate change here changes this list,
// where a reviewer sees it.
var allowedImports = []string{
	"bytes", "crypto/sha256", "encoding/hex", "errors", "io", "regexp", "strconv", "strings", "unicode", "unicode/utf8", "gopkg.in/yaml.v3",
}

func sources(t *testing.T) []string {
	t.Helper()
	all, err := filepath.Glob("*.go")
	if err != nil {
		t.Fatal(err)
	}
	var out []string
	for _, f := range all {
		if !strings.HasSuffix(f, "_test.go") {
			out = append(out, f)
		}
	}
	if len(out) == 0 {
		t.Fatal("found no source files; the test is looking in the wrong place")
	}
	return out
}

func TestTheParserImportsNothingFromThisModuleOrTheOutsideWorld(t *testing.T) {
	fset := token.NewFileSet()
	for _, name := range sources(t) {
		file, err := parser.ParseFile(fset, name, nil, parser.ImportsOnly)
		if err != nil {
			t.Fatal(err)
		}
		for _, imp := range file.Imports {
			path, _ := strconv.Unquote(imp.Path.Value)
			if !slices.Contains(allowedImports, path) {
				t.Errorf("%s imports %s; the workflow parser may import only %v", name, path, allowedImports)
			}
		}
	}
}

// The parser is handed bytes and answers with facts. A file read, an
// environment lookup or a clock would make its answer depend on where and
// when it ran, which is what a fixture-driven test cannot describe.
func TestTheParserNeverReadsAClockTheFilesystemOrTheEnvironment(t *testing.T) {
	forbidden := map[string][]string{
		"time": {"Now", "Since", "Until", "After", "AfterFunc", "Sleep", "Tick", "NewTicker", "NewTimer"},
		"os":   {"ReadFile", "Open", "Getenv", "LookupEnv", "Environ"},
	}
	fset := token.NewFileSet()
	for _, name := range sources(t) {
		file, err := parser.ParseFile(fset, name, nil, 0)
		if err != nil {
			t.Fatal(err)
		}
		ast.Inspect(file, func(n ast.Node) bool {
			sel, ok := n.(*ast.SelectorExpr)
			if !ok {
				return true
			}
			if id, ok := sel.X.(*ast.Ident); ok && slices.Contains(forbidden[id.Name], sel.Sel.Name) {
				t.Errorf("%s: %s.%s: the parser is given bytes and gives facts", fset.Position(sel.Pos()), id.Name, sel.Sel.Name)
			}
			return true
		})
	}
}

package workflow

import (
	"errors"
	"regexp"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

// ErrFixedSleepNotFound and ErrFixedSleepAmbiguous say why a readiness preview
// could not choose a wait. A workflow with two fixed sleeps needs the operator
// to pick one; this function does not guess.
var (
	ErrFixedSleepNotFound  = errors.New("workflow: no fixed sleep step on an Ubuntu runner can be previewed")
	ErrFixedSleepAmbiguous = errors.New("workflow: more than one fixed sleep step on Ubuntu runners can be previewed")
)

var fixedSleep = regexp.MustCompile(`^sleep[ \t]+([0-9]{1,5})$`)

// FindFixedSleep returns the one step whose run script is exactly a whole
// number of seconds of sleep, on a job with a literal Ubuntu runs-on label.
// A block scalar must contain that one command and nothing else. Comments,
// other commands, other shells and expressions are refused rather than
// interpreted: the preview must not turn a script someone else wrote into a
// different one.
func FindFixedSleep(data []byte) (jobIndex, stepIndex, seconds int, err error) {
	if _, err = Inspect(data); err != nil {
		return 0, 0, 0, err
	}
	root, parseErr := parseRoot(data)
	if parseErr != nil {
		err = parseErr
		return
	}
	jobs := field(root, "jobs")
	if jobs == nil || jobs.Kind != yaml.MappingNode {
		err = errUnsupported
		return
	}
	found := false
	for i := 0; i < len(jobs.Content); i += 2 {
		job := jobs.Content[i+1]
		if job.Kind != yaml.MappingNode || field(job, "uses") != nil {
			continue
		}
		runs := field(job, "runs-on")
		if runs == nil || runs.Kind != yaml.ScalarNode || runs.Tag != "!!str" || runs.Style != 0 || !strings.HasPrefix(runs.Value, "ubuntu-") || strings.Contains(runs.Value, "${{") || strings.ContainsAny(runs.Value, "\r\n\x00") {
			continue
		}
		steps := field(job, "steps")
		if steps == nil || steps.Kind != yaml.SequenceNode {
			continue
		}
		for j, step := range steps.Content {
			if step.Kind != yaml.MappingNode || field(step, "uses") != nil {
				continue
			}
			run := field(step, "run")
			n, ok := fixedSleepNode(run)
			if !ok {
				continue
			}
			if found {
				return 0, 0, 0, ErrFixedSleepAmbiguous
			}
			jobIndex, stepIndex, seconds, found = i/2, j, n, true
		}
	}
	if !found {
		return 0, 0, 0, ErrFixedSleepNotFound
	}
	return jobIndex, stepIndex, seconds, nil
}

func fixedSleepNode(n *yaml.Node) (int, bool) {
	if n == nil || n.Kind != yaml.ScalarNode || n.Tag != "!!str" || n.Style != 0 && n.Style&yaml.LiteralStyle == 0 {
		return 0, false
	}
	value := strings.TrimSuffix(n.Value, "\n")
	if strings.ContainsAny(value, "\r\n\x00") || strings.Contains(value, "#") {
		return 0, false
	}
	m := fixedSleep.FindStringSubmatch(strings.TrimSpace(value))
	if m == nil {
		return 0, false
	}
	seconds, err := strconv.Atoi(m[1])
	if err != nil || seconds < 2 || seconds > 3600 {
		return 0, false
	}
	return seconds, true
}

// ReadinessNames returns the literal job and step names for the one fixed sleep
// step, so the preview can be matched to the fleet job GitHub reported.
func ReadinessNames(data []byte, jobIndex, stepIndex int) (jobName, stepName string, err error) {
	foundJob, foundStep, _, err := FindFixedSleep(data)
	if err != nil || foundJob != jobIndex || foundStep != stepIndex {
		return "", "", errUnsupported
	}
	return namesAt(data, jobIndex, stepIndex)
}

// ReadinessChange replaces the fixed sleep's run scalar with one bounded shell
// loop. The script is supplied by the caller and must be one line: this
// function does not infer a condition. Bytes outside the run block are
// contiguous slices, so comments and line endings elsewhere are preserved.
func ReadinessChange(data []byte, jobIndex, stepIndex int, script string) (before, after string, line int, err error) {
	if script == "" || len(script) > 4096 || strings.ContainsAny(script, "\r\n\x00") {
		return "", "", 0, errUnsupported
	}
	foundJob, foundStep, _, err := FindFixedSleep(data)
	if err != nil || foundJob != jobIndex || foundStep != stepIndex {
		return "", "", 0, errUnsupported
	}
	root, parseErr := parseRoot(data)
	if parseErr != nil {
		err = parseErr
		return
	}
	jobs := field(root, "jobs")
	job := jobs.Content[jobIndex*2+1]
	step := field(job, "steps").Content[stepIndex]
	runKey, run := keyAndValue(step, "run")
	if runKey == nil || run == nil || run.Style != 0 && run.Style&yaml.LiteralStyle == 0 {
		return "", "", 0, errUnsupported
	}
	lines := strings.SplitAfter(string(data), "\n")
	if runKey.Line < 1 || runKey.Line > len(lines) {
		return "", "", 0, errUnsupported
	}
	keyLine := lines[runKey.Line-1]
	indent := strings.Repeat(" ", max(runKey.Column-1, 0))
	ending := "\n"
	if strings.HasSuffix(keyLine, "\r\n") {
		ending = "\r\n"
	}
	end := runKey.Line
	trailing := ""
	if run.Style&yaml.LiteralStyle != 0 {
		// Consume the indented block. A line that is not blank and is indented
		// no further than the key belongs to the next field.
		contentEnd := end
		for end < len(lines) {
			next := lines[end]
			trimmed := strings.TrimRight(next, "\r\n")
			if strings.TrimSpace(trimmed) != "" && leadingSpaces(trimmed) <= runKey.Column-1 {
				break
			}
			end++
		}
		contentEnd = end
		for end < len(lines) && strings.TrimSpace(lines[end]) == "" {
			end++
		}
		trailing = strings.Join(lines[contentEnd:end], "")
	} else {
		if strings.Contains(strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(keyLine), "run:")), "#") {
			return "", "", 0, errUnsupported
		}
	}
	before = strings.Join(lines[runKey.Line-1:end], "")
	after = indent + "run: |" + ending + indent + "  " + script + ending + trailing
	if strings.Count(string(data), before) != 1 {
		return "", "", 0, errUnsupported
	}
	return before, after, runKey.Line, nil
}

func leadingSpaces(s string) int {
	return len(s) - len(strings.TrimLeft(s, " "))
}

package workflow

import (
	"errors"
	"regexp"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

// ErrShardNotFound and ErrShardAmbiguous say why a sharding preview could not
// choose a test step. A workflow with two Playwright runs needs the operator to
// pick one; this function does not guess.
var (
	ErrShardNotFound  = errors.New("workflow: no single Playwright test step on an Ubuntu runner can be previewed")
	ErrShardAmbiguous = errors.New("workflow: more than one Playwright test step can be previewed")
)

// ShardRefusal is a refusal with a reason an operator can act on. Sharding can
// drop tests, rename a job a required check depends on and hide a failure, so
// every shape it does not understand is refused by name rather than repaired.
type ShardRefusal struct{ Reason string }

func (e *ShardRefusal) Error() string { return "workflow: sharding refused: " + e.Reason }

func refuse(reason string) error { return &ShardRefusal{Reason: reason} }

// shardMaxBlockLines and shardMaxBlockBytes keep the reviewed change small
// enough to read as one block: a job too large to review is not previewed.
const (
	shardMaxBlockLines = 60
	shardMaxBlockBytes = 3000
)

var (
	playwrightPrefix = []string{"npx playwright test", "pnpm exec playwright test", "yarn playwright test"}
	// Only arguments that neither select tests nor change which files run.
	playwrightSafeArg = regexp.MustCompile(`^(--reporter=[a-z]{2,16}|--workers=[0-9]{1,2}|--retries=[0-9]|--timeout=[0-9]{1,7}|--project=[A-Za-z0-9._-]{1,64})$`)
	narrowingArg      = regexp.MustCompile(`^(--shard|--grep|--grep-invert|-g|--only-changed|--last-failed|--list|--ui|--debug|-x|--max-failures)(=|$)`)
	shardJobID        = regexp.MustCompile(`^[A-Za-z0-9_-]{1,64}$`)
	shardSafeName     = regexp.MustCompile(`^[A-Za-z0-9 ._()/-]{1,100}$`)
)

// FindPlaywrightTest returns the one step whose run script is exactly one
// Playwright test invocation, on a job with a literal Ubuntu runs-on label and
// nothing that sharding would break. A command that already shards, filters or
// narrows, a job that already has a strategy, outputs, services or a condition,
// and a job that uploads artifacts or coverage are refused with a reason.
func FindPlaywrightTest(data []byte) (jobIndex, stepIndex int, err error) {
	if _, err = Inspect(data); err != nil {
		return 0, 0, err
	}
	root, parseErr := parseRoot(data)
	if parseErr != nil {
		return 0, 0, parseErr
	}
	jobs := field(root, "jobs")
	if jobs == nil || jobs.Kind != yaml.MappingNode {
		return 0, 0, errUnsupported
	}
	found := false
	for i := 0; i < len(jobs.Content); i += 2 {
		job := jobs.Content[i+1]
		if job.Kind != yaml.MappingNode || field(job, "uses") != nil {
			continue
		}
		steps := field(job, "steps")
		if steps == nil || steps.Kind != yaml.SequenceNode {
			continue
		}
		for j, step := range steps.Content {
			if step.Kind != yaml.MappingNode || field(step, "uses") != nil {
				continue
			}
			if _, _, ok := playwrightCommand(field(step, "run")); !ok {
				continue
			}
			if found {
				return 0, 0, ErrShardAmbiguous
			}
			jobIndex, stepIndex, found = i/2, j, true
		}
	}
	if !found {
		return 0, 0, ErrShardNotFound
	}
	if err := shardEligible(jobs, jobIndex, stepIndex); err != nil {
		return 0, 0, err
	}
	return jobIndex, stepIndex, nil
}

// playwrightCommand reports whether a run scalar is exactly one Playwright test
// invocation. The second result says why a recognised command is refused.
func playwrightCommand(run *yaml.Node) (command string, reason string, ok bool) {
	if run == nil || run.Kind != yaml.ScalarNode || run.Tag != "!!str" || run.Style != 0 && run.Style&yaml.LiteralStyle == 0 {
		return "", "", false
	}
	value := strings.TrimSpace(strings.TrimSuffix(run.Value, "\n"))
	if value == "" || strings.ContainsAny(value, "\r\n\x00") {
		return "", "", false
	}
	prefix := ""
	for _, p := range playwrightPrefix {
		if value == p || strings.HasPrefix(value, p+" ") {
			prefix = p
			break
		}
	}
	if prefix == "" {
		return "", "", false
	}
	for _, arg := range strings.Fields(strings.TrimPrefix(value, prefix)) {
		switch {
		case narrowingArg.MatchString(arg):
			return value, "the command already shards, filters or narrows the run (" + arg + ")", true
		case !playwrightSafeArg.MatchString(arg):
			return value, "the command passes an argument Zoomies does not recognise (" + arg + "), so it cannot show that every test still runs", true
		}
	}
	return value, "", true
}

// shardEligible holds every refusal for the job and step the finder chose.
func shardEligible(jobs *yaml.Node, jobIndex, stepIndex int) error {
	if jobIndex < 0 || jobIndex*2+1 >= len(jobs.Content) {
		return errUnsupported
	}
	id := jobs.Content[jobIndex*2].Value
	job := jobs.Content[jobIndex*2+1]
	steps := field(job, "steps")
	if steps == nil || stepIndex < 0 || stepIndex >= len(steps.Content) {
		return errUnsupported
	}
	step := steps.Content[stepIndex]
	if _, reason, _ := playwrightCommand(field(step, "run")); reason != "" {
		return refuse(reason)
	}
	runs := field(job, "runs-on")
	if runs == nil || runs.Kind != yaml.ScalarNode || runs.Tag != "!!str" || runs.Style != 0 || !strings.HasPrefix(runs.Value, "ubuntu-") || strings.Contains(runs.Value, "${{") || strings.ContainsAny(runs.Value, "\r\n\x00") {
		return refuse("the job needs a literal Ubuntu runs-on label")
	}
	if !shardJobID.MatchString(id) {
		return refuse("the job ID is not a plain identifier")
	}
	for i := 0; i < len(jobs.Content); i += 2 {
		if jobs.Content[i].Value == id+"-shards" {
			return refuse("a job named " + id + "-shards already exists")
		}
	}
	for _, c := range []struct{ key, why string }{
		{"strategy", "the job already has a strategy or matrix"},
		{"services", "the job starts services that Zoomies cannot show are safe to run once per shard"},
		{"outputs", "the job declares outputs that a later job may read"},
		{"if", "the job has a condition"},
		{"continue-on-error", "the job can pass while failing"},
		{"container", "the job runs in a container Zoomies cannot show is safe to repeat per shard"},
		{"concurrency", "the job sets its own concurrency group"},
	} {
		if field(job, c.key) != nil {
			return refuse(c.why)
		}
	}
	if name := field(job, "name"); name != nil && (name.Kind != yaml.ScalarNode || name.Tag != "!!str" || name.Style != 0 || !shardSafeName.MatchString(name.Value) || strings.TrimSpace(name.Value) != name.Value) {
		return refuse("the job name is not a plain literal")
	}
	if field(step, "if") != nil || field(step, "continue-on-error") != nil {
		return refuse("the test step is conditional or can pass while failing")
	}
	stepName := field(step, "name")
	if stepName == nil || stepName.Kind != yaml.ScalarNode || stepName.Tag != "!!str" || stepName.Value == "" || len(stepName.Value) > 128 || strings.Contains(stepName.Value, "${{") || strings.ContainsAny(stepName.Value, "\r\n\x00") {
		return refuse("the test step needs a literal name so the fleet's history can be matched to it")
	}
	for _, s := range steps.Content {
		uses := field(s, "uses")
		if uses != nil && (strings.Contains(strings.ToLower(uses.Value), "upload-artifact") || strings.Contains(strings.ToLower(uses.Value), "codecov") || strings.Contains(strings.ToLower(uses.Value), "coveralls")) {
			return refuse("the job uploads artifacts or coverage under one name, which every shard would overwrite")
		}
		for _, k := range []string{"name", "run"} {
			if v := field(s, k); v != nil && strings.Contains(strings.ToLower(v.Value), "coverage") {
				return refuse("the job reads or writes coverage that a single shard would only partly cover")
			}
		}
	}
	return nil
}

// ShardNames returns the literal job and step names for the one test step, so
// the preview can be matched to the fleet job GitHub reported. A job without a
// name is reported under its ID, which is what GitHub shows.
func ShardNames(data []byte, jobIndex, stepIndex int) (jobName, stepName string, err error) {
	foundJob, foundStep, err := FindPlaywrightTest(data)
	if err != nil || foundJob != jobIndex || foundStep != stepIndex {
		return "", "", errUnsupported
	}
	root, err := parseRoot(data)
	if err != nil {
		return "", "", err
	}
	jobs := field(root, "jobs")
	job := jobs.Content[jobIndex*2+1]
	jobName = jobs.Content[jobIndex*2].Value
	if n := field(job, "name"); n != nil {
		jobName = n.Value
	}
	return jobName, field(field(job, "steps").Content[stepIndex], "name").Value, nil
}

// ShardChange rewrites the one job into a shard job plus an aggregator that
// keeps the original job ID and name, so a required check that names the job
// still resolves. The Playwright command gains --shard and nothing else. Bytes
// outside the job's block are untouched, and the job block is returned whole
// because the change is one reviewable replacement of it.
func ShardChange(data []byte, jobIndex, stepIndex, count int) (before, after string, line int, err error) {
	if count < 2 || count > 8 {
		return "", "", 0, errUnsupported
	}
	foundJob, foundStep, err := FindPlaywrightTest(data)
	if err != nil || foundJob != jobIndex || foundStep != stepIndex {
		return "", "", 0, errUnsupported
	}
	root, err := parseRoot(data)
	if err != nil {
		return "", "", 0, err
	}
	jobs := field(root, "jobs")
	keyNode := jobs.Content[jobIndex*2]
	job := jobs.Content[jobIndex*2+1]
	id := keyNode.Value
	lines := strings.SplitAfter(string(data), "\n")
	if keyNode.Line < 1 || keyNode.Line > len(lines) {
		return "", "", 0, errUnsupported
	}
	start := keyNode.Line - 1
	keyIndent := keyNode.Column - 1
	if strings.TrimRight(lines[start], " \r\n") != strings.Repeat(" ", keyIndent)+id+":" {
		return "", "", 0, refuse("the job header carries a comment or an unusual layout")
	}
	end := start + 1
	for end < len(lines) {
		trimmed := strings.TrimSpace(lines[end])
		if trimmed != "" && !strings.HasPrefix(trimmed, "#") && leadingSpaces(strings.TrimRight(lines[end], "\r\n")) <= keyIndent {
			break
		}
		end++
	}
	// Blank lines and comments just before the next job belong to it.
	for end > start+1 {
		prev := strings.TrimRight(lines[end-1], "\r\n")
		if strings.TrimSpace(prev) == "" || strings.HasPrefix(strings.TrimSpace(prev), "#") && leadingSpaces(prev) <= keyIndent {
			end--
			continue
		}
		break
	}
	block := lines[start:end]
	if len(block) > shardMaxBlockLines || len(strings.Join(block, "")) > shardMaxBlockBytes {
		return "", "", 0, refuse("the job is too large to review as one block")
	}
	ending := "\n"
	if strings.HasSuffix(lines[start], "\r\n") {
		ending = "\r\n"
	}
	childIndent := keyIndent + 2
	if len(job.Content) > 0 && job.Content[0].Column-1 > keyIndent {
		childIndent = job.Content[0].Column - 1
	}
	pad := strings.Repeat(" ", childIndent)
	jobName := id
	if n := field(job, "name"); n != nil {
		jobName = n.Value
	}
	runsOn := field(job, "runs-on").Value

	rel := func(l int) (int, bool) {
		i := l - 1 - start
		return i, i > 0 && i < len(block)
	}
	// The test command line.
	steps := field(job, "steps")
	run := field(steps.Content[stepIndex], "run")
	runKey, _ := keyAndValue(steps.Content[stepIndex], "run")
	cmdLine := runKey.Line
	if run.Style&yaml.LiteralStyle != 0 {
		cmdLine = runKey.Line + 1
	}
	cmdRel, ok := rel(cmdLine)
	if !ok {
		return "", "", 0, errUnsupported
	}
	cmd := strings.TrimRight(block[cmdRel], "\r\n")
	if strings.Contains(cmd, "#") || !strings.HasSuffix(strings.TrimSpace(cmd), strings.TrimSpace(run.Value)) {
		return "", "", 0, refuse("the test command line carries a comment or an unusual layout")
	}
	out := make([]string, len(block))
	copy(out, block)
	out[cmdRel] = cmd + " --shard=${{ matrix.shard }}/" + strconv.Itoa(count) + ending
	out[0] = strings.Repeat(" ", keyIndent) + id + "-shards:" + ending

	// The shard job's name and strategy, placed after the header, or replacing
	// the name line when the job already has one.
	shardName := pad + "name: " + strconv.Quote(jobName+" (shard ${{ matrix.shard }}/"+strconv.Itoa(count)+")") + ending
	strategy := pad + "strategy:" + ending +
		pad + "  fail-fast: false" + ending +
		pad + "  matrix:" + ending +
		pad + "    shard: [" + shardList(count) + "]" + ending
	var head []string
	if nameKey, _ := keyAndValue(job, "name"); nameKey != nil {
		nameRel, ok := rel(nameKey.Line)
		if !ok || strings.Contains(block[nameRel], "#") {
			return "", "", 0, refuse("the job name line carries a comment or an unusual layout")
		}
		out[nameRel] = shardName + strategy
	} else {
		head = []string{shardName + strategy}
	}
	rebuilt := out[0] + strings.Join(head, "") + strings.Join(out[1:], "")
	if !strings.HasSuffix(rebuilt, ending) {
		rebuilt += ending
	}
	aggregator := ending +
		strings.Repeat(" ", keyIndent) + id + ":" + ending +
		pad + "name: " + shardScalar(jobName) + ending +
		pad + "needs: " + id + "-shards" + ending +
		pad + "if: ${{ always() }}" + ending +
		pad + "runs-on: " + runsOn + ending +
		pad + "steps:" + ending +
		pad + "  - name: Require every shard to pass" + ending +
		pad + "    run: test \"${{ needs." + id + "-shards.result }}\" = \"success\"" + ending

	before = strings.Join(block, "")
	if !strings.HasSuffix(before, ending) {
		return "", "", 0, errUnsupported
	}
	after = rebuilt + aggregator
	if strings.Count(string(data), before) != 1 {
		return "", "", 0, errUnsupported
	}
	return before, after, keyNode.Line, nil
}

func shardList(count int) string {
	parts := make([]string, count)
	for i := range parts {
		parts[i] = strconv.Itoa(i + 1)
	}
	return strings.Join(parts, ", ")
}

// shardScalar writes a name back the way it was safe to read: plain when it
// only holds characters that need no quoting, double-quoted otherwise.
func shardScalar(s string) string {
	if shardSafeName.MatchString(s) && !strings.HasPrefix(s, "-") && !strings.HasPrefix(s, ".") {
		return s
	}
	return strconv.Quote(s)
}

package workflow

import (
	"errors"
	"strings"
	"testing"
)

const shardWorkflow = `on: push
jobs:
  test:
    name: End to end
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa
      - name: Browser tests
        run: npx playwright test --project=chromium
  lint:
    runs-on: ubuntu-latest
    steps:
      - run: echo lint
`

func TestFindPlaywrightTestFindsTheOneShardableStep(t *testing.T) {
	job, step, err := FindPlaywrightTest([]byte(shardWorkflow))
	if err != nil || job != 0 || step != 1 {
		t.Fatalf("job=%d step=%d err=%v", job, step, err)
	}
	jobName, stepName, err := ShardNames([]byte(shardWorkflow), job, step)
	if err != nil || jobName != "End to end" || stepName != "Browser tests" {
		t.Fatalf("names %q %q %v", jobName, stepName, err)
	}
}

func TestShardChangeKeepsTheJobNameAndAddsOnlyTheShardFlag(t *testing.T) {
	before, after, line, err := ShardChange([]byte(shardWorkflow), 0, 1, 3)
	if err != nil || line != 3 {
		t.Fatalf("line=%d err=%v", line, err)
	}
	if strings.Count(shardWorkflow, before) != 1 || !strings.Contains(shardWorkflow, before+"  lint:") {
		t.Fatal("the edit was not one contiguous block that stops before the next job")
	}
	for _, want := range []string{
		"  test-shards:\n",
		"    name: \"End to end (shard ${{ matrix.shard }}/3)\"\n",
		"      fail-fast: false\n",
		"        shard: [1, 2, 3]\n",
		"        run: npx playwright test --project=chromium --shard=${{ matrix.shard }}/3\n",
		"  test:\n    name: End to end\n    needs: test-shards\n    if: ${{ always() }}\n    runs-on: ubuntu-latest\n",
		`run: test "${{ needs.test-shards.result }}" = "success"`,
	} {
		if !strings.Contains(after, want) {
			t.Errorf("after does not contain %q:\n%s", want, after)
		}
	}
	if strings.Count(after, "--shard=") != 1 {
		t.Error("the shard flag was added more than once")
	}
	// The rewrite must itself be a workflow Zoomies reads, and a second preview
	// of it must be refused, because it now shards.
	rewritten := strings.Replace(shardWorkflow, before, after, 1)
	if _, err := Inspect([]byte(rewritten)); err != nil {
		t.Fatalf("the rewritten workflow does not parse: %v", err)
	}
	var refusal *ShardRefusal
	if _, _, err := FindPlaywrightTest([]byte(rewritten)); !errors.As(err, &refusal) {
		t.Fatalf("a rewritten workflow can be sharded again: %v", err)
	}
}

func TestShardChangeCoversAJobWithNoNameAndAPreservesCRLF(t *testing.T) {
	workflow := "on: push\r\njobs:\r\n  e2e:\r\n    runs-on: ubuntu-24.04\r\n    steps:\r\n      - name: Run\r\n        run: |\r\n          npx playwright test\r\n"
	job, step, err := FindPlaywrightTest([]byte(workflow))
	if err != nil {
		t.Fatal(err)
	}
	_, after, _, err := ShardChange([]byte(workflow), job, step, 2)
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(strings.ReplaceAll(after, "\r\n", ""), "\n") {
		t.Fatalf("mixed line endings: %q", after)
	}
	for _, want := range []string{"  e2e-shards:\r\n", "    name: \"e2e (shard ${{ matrix.shard }}/2)\"\r\n", "          npx playwright test --shard=${{ matrix.shard }}/2\r\n", "  e2e:\r\n    name: e2e\r\n"} {
		if !strings.Contains(after, want) {
			t.Errorf("after does not contain %q:\n%q", want, after)
		}
	}
}

func TestFindPlaywrightTestRefusesWhatShardingCouldBreak(t *testing.T) {
	job := func(extra, run string) string {
		return "on: push\njobs:\n  test:\n    name: Test\n    runs-on: ubuntu-latest\n" + extra + "    steps:\n      - name: Browser tests\n        run: " + run + "\n"
	}
	for name, tc := range map[string]struct{ workflow, reason string }{
		"already sharded":      {job("", "npx playwright test --shard=1/2"), "already shards"},
		"filtered":             {job("", "npx playwright test --grep @smoke"), "already shards, filters"},
		"a path":               {job("", "npx playwright test tests/a.spec.ts"), "does not recognise"},
		"piped":                {job("", "npx playwright test || true"), "does not recognise"},
		"existing matrix":      {job("    strategy:\n      matrix:\n        os: [a]\n", "npx playwright test"), "strategy"},
		"outputs":              {job("    outputs:\n      x: ${{ steps.a.outputs.x }}\n", "npx playwright test"), "outputs"},
		"services":             {job("    services:\n      db:\n        image: postgres\n", "npx playwright test"), "services"},
		"condition":            {job("    if: github.ref == 'refs/heads/main'\n", "npx playwright test"), "condition"},
		"continue on error":    {job("    continue-on-error: true\n", "npx playwright test"), "pass while failing"},
		"not ubuntu":           {strings.Replace(job("", "npx playwright test"), "ubuntu-latest", "macos-latest", 1), "Ubuntu"},
		"expression runner":    {strings.Replace(job("", "npx playwright test"), "ubuntu-latest", "ubuntu-${{ matrix.v }}", 1), "Ubuntu"},
		"colliding shard name": {job("", "npx playwright test") + "  test-shards:\n    runs-on: ubuntu-latest\n    steps:\n      - run: echo hi\n", "already exists"},
	} {
		t.Run(name, func(t *testing.T) {
			_, _, err := FindPlaywrightTest([]byte(tc.workflow))
			var refusal *ShardRefusal
			if !errors.As(err, &refusal) || !strings.Contains(refusal.Reason, tc.reason) {
				t.Fatalf("err=%v, want a refusal containing %q", err, tc.reason)
			}
		})
	}
}

func TestFindPlaywrightTestRefusesArtifactsCoverageAndUnnamedSteps(t *testing.T) {
	base := "on: push\njobs:\n  test:\n    name: Test\n    runs-on: ubuntu-latest\n    steps:\n      - name: Browser tests\n        run: npx playwright test\n"
	for name, workflow := range map[string]string{
		"artifact":  base + "      - uses: actions/upload-artifact@bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb\n        with:\n          name: report\n",
		"coverage":  base + "      - name: Upload coverage\n        run: echo hi\n",
		"unnamed":   strings.Replace(base, "      - name: Browser tests\n", "      - id: tests\n", 1),
		"test cond": strings.Replace(base, "        run: npx playwright test\n", "        if: always()\n        run: npx playwright test\n", 1),
	} {
		t.Run(name, func(t *testing.T) {
			_, _, err := FindPlaywrightTest([]byte(workflow))
			var refusal *ShardRefusal
			if !errors.As(err, &refusal) {
				t.Fatalf("err=%v, want a refusal", err)
			}
		})
	}
}

func TestFindPlaywrightTestSaysWhenThereIsNothingOrTwoThings(t *testing.T) {
	if _, _, err := FindPlaywrightTest([]byte("on: push\njobs:\n  a:\n    runs-on: ubuntu-latest\n    steps:\n      - run: go test ./...\n")); !errors.Is(err, ErrShardNotFound) {
		t.Fatalf("no playwright step: %v", err)
	}
	two := shardWorkflow + "  more:\n    runs-on: ubuntu-latest\n    steps:\n      - name: Again\n        run: npx playwright test\n"
	if _, _, err := FindPlaywrightTest([]byte(two)); !errors.Is(err, ErrShardAmbiguous) {
		t.Fatalf("two playwright steps: %v", err)
	}
}

func TestShardChangeRefusesAnOutOfRangeCountAndAJobTooLargeToReview(t *testing.T) {
	for _, n := range []int{0, 1, 9} {
		if _, _, _, err := ShardChange([]byte(shardWorkflow), 0, 1, n); err == nil {
			t.Fatalf("count %d accepted", n)
		}
	}
	var b strings.Builder
	b.WriteString("on: push\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n")
	for i := 0; i < 40; i++ {
		b.WriteString("      - name: Step\n        run: echo hello\n")
	}
	b.WriteString("      - name: Browser tests\n        run: npx playwright test\n")
	_, _, _, err := ShardChange([]byte(b.String()), 0, 40, 2)
	var refusal *ShardRefusal
	if !errors.As(err, &refusal) || !strings.Contains(refusal.Reason, "too large") {
		t.Fatalf("a large job: %v", err)
	}
}

package kennel

import (
	"sort"
)

// WorkflowFile is what the parser said about one default-branch workflow,
// keyed by its blob SHA: positions and counts, never a path, a job name or a
// line of YAML. See internal/kennel/workflow for how each is decided.
type WorkflowFile struct {
	SHA                  string     `json:"sha"`
	NoTimeout            []Location `json:"no_timeout,omitempty"`
	NoConcurrency        *Location  `json:"no_concurrency,omitempty"`
	FirstPartyUnpinned   []Location `json:"first_party_unpinned,omitempty"`
	OtherUnpinned        []Location `json:"other_unpinned,omitempty"`
	PermissionsUnset     []Location `json:"permissions_unset,omitempty"`
	TargetCheckoutPRHead []Location `json:"target_checkout_pr_head,omitempty"`
	SecretOnCommandLine  []Location `json:"secret_on_command_line,omitempty"`
	// LabelUnserved is each job whose literal runs-on no pool serves, decided
	// by the controller, which knows the pools; the labels never come here.
	LabelUnserved []Location `json:"label_unserved,omitempty"`
	// Pinned is how many external references in the file are pinned to a
	// commit or an image digest.
	Pinned int `json:"pinned,omitempty"`
}

// WorkflowFacts are the default-branch workflow files as read, and the ones
// that could not be: a file the inventory skipped for its size or the parser
// refused, by SHA.
type WorkflowFacts struct {
	Files      []WorkflowFile `json:"files"`
	Unreadable []string       `json:"unreadable"`
}

func workflowCheck(code Code, area Area, severity Severity, detects, fix, verify string, eval func(*Snapshot) result) Check {
	return Check{Code: code, Area: area, Severity: severity, Detects: detects, Fix: fix, Verify: verify, Docs: docsAnchor(code), Needs: []Source{SourceMetadata, SourceWorkflows}, eval: func(s *Snapshot) result {
		r := eval(s)
		r.incomplete = s.Coverage.state(SourceWorkflows) == CoveragePartial
		return r
	}}
}

// perFile raises one finding per file with any of the locations pick returns:
// the file is the subject, the locations are the evidence, lowest line first
// and at most maxEvidence of them, and the detail carries their count.
func perFile(s *Snapshot, code Code, severity func(*Snapshot, *WorkflowFile) Severity, pick func(*WorkflowFile) []Location, title string, detail func(n int) string, fix string) result {
	r := result{applies: true}
	if s.Workflows == nil {
		return r
	}
	for i := range s.Workflows.Files {
		f := &s.Workflows.Files[i]
		locs := pick(f)
		if len(locs) == 0 {
			continue
		}
		sorted := append([]Location(nil), locs...)
		sort.Slice(sorted, func(a, b int) bool { return sorted[a].Line < sorted[b].Line })
		var ev []Evidence
		for _, loc := range sorted[:min(len(sorted), maxEvidence)] {
			ev = append(ev, fileEvidence(f.SHA, loc))
		}
		r.findings = append(r.findings, Finding{
			Code: code, Severity: severity(s, f), Subject: subjectOf(f.SHA),
			Title: title, Detail: detail(len(locs)), Fix: fix, Evidence: ev,
		})
	}
	return r
}

func fixed(sev Severity) func(*Snapshot, *WorkflowFile) Severity {
	return func(*Snapshot, *WorkflowFile) Severity { return sev }
}

func evalNoTimeout(s *Snapshot) result {
	return perFile(s, CodeNoTimeout, fixed(SeverityWarning),
		func(f *WorkflowFile) []Location { return f.NoTimeout },
		"Jobs have no explicit timeout",
		func(n int) string {
			return count(n, "executable job", "executable jobs") + " in this workflow " + has(n) + " no timeout-minutes; a hung job can hold a runner until the platform limit."
		},
		"Set timeout-minutes on the executable jobs in the default-branch workflows, using their observed duration and a margin for slower runs.")
}

func evalNoConcurrency(s *Snapshot) result {
	return perFile(s, CodeNoConcurrency, fixed(SeverityInfo),
		func(f *WorkflowFile) []Location {
			if f.NoConcurrency == nil {
				return nil
			}
			return []Location{*f.NoConcurrency}
		},
		"Pull request workflows do not cancel superseded runs",
		func(int) string {
			return "This pull-request-only workflow has no cancelling concurrency group at workflow level or on every job; superseded work can keep consuming runners."
		},
		"Review whether superseded pull request runs may be cancelled, then add a concurrency group scoped to the workflow and pull request with cancel-in-progress enabled.")
}

func evalActionNotPinned(s *Snapshot) result {
	return perFile(s, CodeActionNotPinned,
		func(_ *Snapshot, f *WorkflowFile) Severity {
			if len(f.OtherUnpinned) > 0 {
				return SeverityWarning
			}
			return SeverityInfo
		},
		func(f *WorkflowFile) []Location {
			return append(append([]Location(nil), f.FirstPartyUnpinned...), f.OtherUnpinned...)
		},
		"External actions use mutable references",
		func(n int) string {
			return count(n, "external reference", "external references") + " in this workflow " + is(n) + " not a full commit pin, or a Docker action without an image digest; the code it runs may change without a repository change."
		},
		"Pin external actions and reusable workflows to reviewed full commit SHAs and Docker actions to image digests; use an updater to maintain the pins.")
}

func evalPermissionsUnset(s *Snapshot) result {
	// A workflow that sets no permissions is only as strong as the repository's
	// default token. With that read from GitHub the check can say so: silent when
	// the default is read-only, and naming it when it can write. The settings are
	// looked at here and are not declared as a source this check needs, because a
	// declared source that is off, denied or unread would skip the check, and
	// what that case needs is the old answer, not silence.
	known := s.Settings != nil && s.Coverage.state(SourceSettings).readable()
	if known && !s.Settings.DefaultTokenWrite {
		return result{applies: true}
	}
	return perFile(s, CodePermissionsUnset,
		func(s *Snapshot, _ *WorkflowFile) Severity {
			if s.Repo.Visibility == VisibilityPublic {
				return SeverityWarning
			}
			return SeverityInfo
		},
		func(f *WorkflowFile) []Location { return f.PermissionsUnset },
		"Jobs inherit undeclared token permissions",
		func(n int) string {
			if known {
				return count(n, "job", "jobs") + " in this workflow " + has(n) + " no permissions block at job or workflow level and " + inherits(n) + " the repository's default token, which can write."
			}
			return count(n, "job", "jobs") + " in this workflow " + has(n) + " no permissions block at job or workflow level and " + inherits(n) + " the repository or organisation default; that default has not been checked."
		},
		"Declare the least token permissions each workflow or job needs, reviewing its actions and publishing steps before reducing access.")
}

// has, is and inherits agree a verb with a count, so a sentence about one
// job reads as well as one about three.
func has(n int) string {
	if n == 1 {
		return "has"
	}
	return "have"
}

func is(n int) string {
	if n == 1 {
		return "is"
	}
	return "are"
}

func inherits(n int) string {
	if n == 1 {
		return "inherits"
	}
	return "inherit"
}

func evalTargetCheckoutPRHead(s *Snapshot) result {
	r := perFile(s, CodeTargetCheckoutPRHead,
		func(s *Snapshot, _ *WorkflowFile) Severity {
			// Only a stranger opens a pull request against a public repository;
			// on a private one the author is a member, and the checkout is a
			// weakness rather than an open door.
			if isPublic(s) {
				return SeverityError
			}
			return SeverityWarning
		},
		func(f *WorkflowFile) []Location { return f.TargetCheckoutPRHead },
		"A workflow strangers can trigger checks out their code",
		func(n int) string {
			return count(n, "step", "steps") + " in this pull_request_target workflow " + checksOut(n) + " the pull request's head. The workflow runs on the default branch with the repository's token and its secrets, and the checked-out code runs with them."
		},
		"Do not check out the pull request's head under pull_request_target: read what the event carries, or run the pull request's code under pull_request, where it gets the fork's lesser token and no secrets.")
	// The row's severity is the usual one; the finding's is the file's.
	return r
}

func evalWorkflowUnreadable(s *Snapshot) result {
	r := result{applies: true}
	if s.Workflows == nil {
		return r
	}
	for _, sha := range s.Workflows.Unreadable {
		r.findings = append(r.findings, Finding{
			Code: CodeWorkflowUnreadable, Severity: SeverityWarning, Subject: subjectOf(sha),
			Title:    "A workflow file could not be read",
			Detail:   "This workflow is over Kennel Club's limits or has a shape its parser will not judge in part, so nothing in it was checked: a finding it may hold is not reported, and a clean reading of the other files is not an all-clear.",
			Fix:      "Bring the file within the limits: under 256 KiB, no YAML anchors, aliases or merge keys, no duplicate keys, one document, valid UTF-8 and a jobs mapping; or split it into smaller workflows.",
			Evidence: []Evidence{fileEvidence(sha, Location{JobIndex: -1})},
		})
	}
	return r
}

// evalPinsWithoutUpdater needs the setup source, which says whether an updater
// is configured, so it is read only once the check applies, as the setup
// checks read it, and is skipped and says so when it was not read.
func evalPinsWithoutUpdater(s *Snapshot) result {
	r := result{applies: true, extra: []Source{SourceSetup}}
	if s.Workflows == nil || s.Setup == nil || s.Coverage.state(SourceSetup) != CoverageOK {
		return r
	}
	pinned := 0
	for _, f := range s.Workflows.Files {
		pinned += f.Pinned
	}
	if pinned == 0 || s.Setup.Present[CodeSetupDependencyUpdates] {
		return r
	}
	r.findings = []Finding{{
		Code: CodePinsWithoutUpdater, Severity: SeverityInfo,
		Title:  "Pinned actions have nothing to move the pins",
		Detail: count(pinned, "external reference is", "external references are") + " pinned to a commit or an image digest, and no Dependabot or Renovate configuration was found on the default branch, so the pins stay where they were put until somebody remembers them.",
		Fix:    "Configure Dependabot or Renovate for GitHub Actions so the pinned commits are moved by pull request, or confirm that an external service moves them.",
	}}
	return r
}

func evalLabelUnserved(s *Snapshot) result {
	return perFile(s, CodeLabelUnserved, fixed(SeverityInfo),
		func(f *WorkflowFile) []Location { return f.LabelUnserved },
		"Jobs ask for labels no pool serves",
		func(n int) string {
			return count(n, "job", "jobs") + " in this workflow " + names(n) + " a runs-on label no pool of this fleet serves; such a job waits until a pool matches it or somebody cancels it."
		},
		"Change the job's runs-on to labels a pool serves, or add the label to a pool that can run the job.")
}

func evalSecretOnCommandLine(s *Snapshot) result {
	return perFile(s, CodeSecretOnCommandLine, fixed(SeverityWarning),
		func(f *WorkflowFile) []Location { return f.SecretOnCommandLine },
		"A secret is put on a command line",
		func(n int) string {
			return count(n, "step", "steps") + " in this workflow " + interpolates(n) + " a secret into a run line or a command-line argument, where it can reach the process list and the log."
		},
		"Pass the secret through the step's env block and read it from the environment in the command; never interpolate it into run or args.")
}

func checksOut(n int) string {
	if n == 1 {
		return "checks out"
	}
	return "check out"
}

func names(n int) string {
	if n == 1 {
		return "names"
	}
	return "name"
}

func interpolates(n int) string {
	if n == 1 {
		return "interpolates"
	}
	return "interpolate"
}

package kennel

import (
	"strings"
	"testing"
	"time"
)

const (
	shaA = "a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1"
	shaB = "b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2"
)

// withWorkflowFile is a snapshot whose workflow source holds these files.
func withWorkflowFile(s Snapshot, files ...WorkflowFile) Snapshot {
	s.Workflows = &WorkflowFacts{Files: files}
	return s
}

func init() {
	positives[CodeNoTimeout] = func() Snapshot {
		return withWorkflowFile(privateRepo(), WorkflowFile{SHA: shaA, NoTimeout: []Location{{0, 4}}})
	}
	positives[CodeNoConcurrency] = func() Snapshot {
		return withWorkflowFile(privateRepo(), WorkflowFile{SHA: shaA, NoConcurrency: &Location{-1, 2}})
	}
	positives[CodeActionNotPinned] = func() Snapshot {
		return withWorkflowFile(privateRepo(), WorkflowFile{SHA: shaA, OtherUnpinned: []Location{{0, 8}}})
	}
	positives[CodePermissionsUnset] = func() Snapshot {
		// Unset permissions are only a finding when the default token can write or
		// is not known; see TestUnsetPermissionsAreJudgedAgainstTheDefaultTokenWhenItIsKnown.
		s := withWorkflowFile(publicRepo(), WorkflowFile{SHA: shaA, PermissionsUnset: []Location{{0, 4}}})
		s.Settings = &SettingsFacts{DefaultTokenWrite: true, ForkApproval: ApprovalAll}
		return s
	}
	positives[CodeTargetCheckoutPRHead] = func() Snapshot {
		return withWorkflowFile(publicRepo(), WorkflowFile{SHA: shaA, TargetCheckoutPRHead: []Location{{0, 8}}})
	}
	positives[CodePinsWithoutUpdater] = func() Snapshot {
		s := withWorkflowFile(privateRepo(), WorkflowFile{SHA: shaA, Pinned: 3})
		s.Setup.Present[CodeSetupDependencyUpdates] = false
		return s
	}
	positives[CodeWorkflowUnreadable] = func() Snapshot {
		s := privateRepo()
		s.Workflows = &WorkflowFacts{Unreadable: []string{shaA}}
		return s
	}
	positives[CodeLabelUnserved] = func() Snapshot {
		return withWorkflowFile(privateRepo(), WorkflowFile{SHA: shaA, LabelUnserved: []Location{{1, 9}}})
	}
	positives[CodeSecretOnCommandLine] = func() Snapshot {
		return withWorkflowFile(privateRepo(), WorkflowFile{SHA: shaA, SecretOnCommandLine: []Location{{0, 8}}})
	}
}

// Each owed check fires on its positive and not on the same repository with
// the fact removed, at the severity its registry row promises.
func TestTheOwedChecksFireOnTheirPositivesAndNotOnTheirNegatives(t *testing.T) {
	for _, tc := range []struct {
		code     Code
		severity Severity
		negative func() Snapshot
	}{
		{CodeTargetCheckoutPRHead, SeverityError, func() Snapshot { return withWorkflowFile(publicRepo(), WorkflowFile{SHA: shaA}) }},
		{CodePinsWithoutUpdater, SeverityInfo, func() Snapshot {
			s := withWorkflowFile(privateRepo(), WorkflowFile{SHA: shaA, Pinned: 3})
			s.Setup.Present[CodeSetupDependencyUpdates] = true
			return s
		}},
		{CodeWorkflowUnreadable, SeverityWarning, func() Snapshot { return withWorkflowFile(privateRepo(), WorkflowFile{SHA: shaA}) }},
		{CodeLabelUnserved, SeverityInfo, func() Snapshot { return withWorkflowFile(privateRepo(), WorkflowFile{SHA: shaA}) }},
		{CodeSecretOnCommandLine, SeverityWarning, func() Snapshot { return withWorkflowFile(privateRepo(), WorkflowFile{SHA: shaA}) }},
	} {
		f, ok := finding(Evaluate(positives[tc.code](), Policy{}), tc.code)
		if !ok || f.Severity != tc.severity {
			t.Errorf("%s on its positive: found %v, severity %s, want %s", tc.code, ok, f.Severity, tc.severity)
		}
		// The updater finding is about the repository, whose configuration is
		// one thing; every other is about one file.
		if want := shaA[:12]; tc.code == CodePinsWithoutUpdater {
			want = ""
		} else if f.Subject != want {
			t.Errorf("%s: subject = %q, want the file", tc.code, f.Subject)
		}
		if _, ok := finding(Evaluate(tc.negative(), Policy{}), tc.code); ok {
			t.Errorf("%s fired on its negative", tc.code)
		}
	}
	// A repository with nothing pinned has no pins for an updater to move.
	s := withWorkflowFile(privateRepo(), WorkflowFile{SHA: shaA})
	s.Setup.Present[CodeSetupDependencyUpdates] = false
	if _, ok := finding(Evaluate(s, Policy{}), CodePinsWithoutUpdater); ok {
		t.Error("pins_without_updater fired with nothing pinned")
	}
}

// Checking out the pull request's head under pull_request_target hands the
// repository's token and secrets to a stranger's code, on a public repository.
// On a private one only members open pull requests, so it is a warning.
func TestTargetCheckoutIsAnErrorOnlyOnAPublicRepository(t *testing.T) {
	private := withWorkflowFile(privateRepo(), WorkflowFile{SHA: shaA, TargetCheckoutPRHead: []Location{{0, 8}}})
	f, ok := finding(Evaluate(private, Policy{}), CodeTargetCheckoutPRHead)
	if !ok || f.Severity != SeverityWarning {
		t.Fatalf("private: found %v, severity %s", ok, f.Severity)
	}
}

// The updater check needs the setup source, which is read only when
// kennel.repository_setup is on: without it the check is skipped and says
// which source it wanted, as the setup checks are.
func TestPinsWithoutUpdaterIsSkippedWhenSetupWasNotRead(t *testing.T) {
	s := withWorkflowFile(privateRepo(), WorkflowFile{SHA: shaA, Pinned: 3})
	s.Setup = nil
	s.Coverage[SourceSetup] = SourceState{State: CoverageNotRead}
	ev := Evaluate(s, Policy{})
	if _, ok := finding(ev, CodePinsWithoutUpdater); ok {
		t.Fatal("fired without the setup source")
	}
	skipped := false
	for _, sk := range ev.Skipped {
		if sk.Code == CodePinsWithoutUpdater && sk.Source == SourceSetup {
			skipped = true
		}
	}
	if !skipped {
		t.Fatalf("not skipped for want of the setup source: %+v", ev.Skipped)
	}
}

// An unreadable file is a finding about that file, with the file as its
// only evidence, and the source it came from is still partial: nothing in
// the file was judged, so finding nothing elsewhere is no all-clear.
func TestAnUnreadableFileIsAFindingAndKeepsTheSourcePartial(t *testing.T) {
	s := positives[CodeWorkflowUnreadable]()
	s.Coverage[SourceWorkflows] = SourceState{State: CoveragePartial}
	ev := Evaluate(s, Policy{})
	f, ok := finding(ev, CodeWorkflowUnreadable)
	if !ok || len(f.Evidence) != 1 || f.Evidence[0].Ref != shaA || f.Evidence[0].JobIndex == nil || *f.Evidence[0].JobIndex != -1 {
		t.Fatalf("finding = %+v (found %v)", f, ok)
	}
	if ev.Complete || ev.State() == StateBestInShow {
		t.Fatalf("an unreadable file earned an all-clear: complete %v, state %s", ev.Complete, ev.State())
	}
}

// A finding is about one file: its subject is the file's identity, so a
// waiver covers that file and Recheck after a fix closes exactly it, and its
// evidence is where in the file, lowest line first.
func TestAWorkflowFindingNamesItsFileJobAndLine(t *testing.T) {
	s := withWorkflowFile(privateRepo(), WorkflowFile{SHA: shaA, NoTimeout: []Location{{1, 12}, {0, 4}}})
	f, ok := finding(Evaluate(s, Policy{}), CodeNoTimeout)
	if !ok {
		t.Fatal("no finding")
	}
	if f.Subject != shaA[:12] {
		t.Errorf("subject = %q, want the first twelve characters of the SHA", f.Subject)
	}
	if len(f.Evidence) != 2 || f.Evidence[0].Kind != EvidenceFile || f.Evidence[0].Ref != shaA ||
		f.Evidence[0].Line != 4 || f.Evidence[0].JobIndex == nil || *f.Evidence[0].JobIndex != 0 ||
		f.Evidence[1].Line != 12 || *f.Evidence[1].JobIndex != 1 {
		t.Errorf("evidence = %+v", f.Evidence)
	}
	if !strings.Contains(f.Detail, "2 executable jobs") {
		t.Errorf("detail = %q", f.Detail)
	}
}

func TestTwoFilesGiveTwoFindingsWithTheirOwnSubjects(t *testing.T) {
	s := withWorkflowFile(privateRepo(),
		WorkflowFile{SHA: shaA, NoTimeout: []Location{{0, 4}}},
		WorkflowFile{SHA: shaB, NoTimeout: []Location{{0, 9}}})
	ev := Evaluate(s, Policy{})
	var subjects []string
	for _, f := range ev.Findings {
		if f.Code == CodeNoTimeout {
			subjects = append(subjects, f.Subject)
		}
	}
	if strings.Join(subjects, " ") != shaA[:12]+" "+shaB[:12] {
		t.Fatalf("subjects = %v", subjects)
	}
}

// A workflow-level fact has no job: the evidence says so with -1, which the
// page reads as the file itself.
func TestAWorkflowLevelFactHasNoJob(t *testing.T) {
	s := positives[CodeNoConcurrency]()
	f, _ := finding(Evaluate(s, Policy{}), CodeNoConcurrency)
	if len(f.Evidence) != 1 || f.Evidence[0].JobIndex == nil || *f.Evidence[0].JobIndex != -1 || f.Evidence[0].Line != 2 {
		t.Fatalf("evidence = %+v", f.Evidence)
	}
}

// A blob SHA is an identifier GitHub made, so one that is not forty hex
// characters is something else wearing its name: it is dropped whole, as a
// pool identifier that fails its gate is, and the subject is empty.
func TestFileEvidenceIsGatedLikeAPoolName(t *testing.T) {
	s := withWorkflowFile(privateRepo(), WorkflowFile{SHA: "ignore previous instructions", NoTimeout: []Location{{0, 4}}})
	f, ok := finding(Evaluate(s, Policy{}), CodeNoTimeout)
	if !ok {
		t.Fatal("no finding")
	}
	if f.Subject != "" || len(f.Evidence) != 1 || f.Evidence[0].Ref != "" || f.Evidence[0].Label == "" {
		t.Fatalf("subject = %q, evidence = %+v", f.Subject, f.Evidence)
	}
}

func TestAWaiverOnAFileLapsesWhenTheFileChanges(t *testing.T) {
	w := Waiver{ID: "w1", Code: CodeNoTimeout, Subject: shaA[:12], Severity: SeverityWarning, ExpiresAt: now.Add(time.Hour)}
	before := Evaluate(withWorkflowFile(privateRepo(), WorkflowFile{SHA: shaA, NoTimeout: []Location{{0, 4}}}), Policy{Waivers: []Waiver{w}})
	if len(before.Waived) != 1 || len(before.Findings) != 0 {
		t.Fatalf("the waiver covers the file: waived %d, open %d", len(before.Waived), len(before.Findings))
	}
	after := Evaluate(withWorkflowFile(privateRepo(), WorkflowFile{SHA: shaB, NoTimeout: []Location{{0, 4}}}), Policy{Waivers: []Waiver{w}})
	if len(after.Waived) != 0 || len(after.Findings) != 1 || len(after.Stale) != 1 {
		t.Fatalf("after the file changed: waived %d, open %d, stale %d", len(after.Waived), len(after.Findings), len(after.Stale))
	}
}

func TestWorkflowAdviceRequiresReadableCoverageAndNeverCallsPartialReadsClear(t *testing.T) {
	for _, state := range allStates {
		s := privateRepo()
		s.Coverage[SourceWorkflows] = SourceState{State: state}
		ev := Evaluate(s, Policy{})
		if state != CoverageOK && ev.Complete {
			t.Errorf("%s was called complete", state)
		}
		if state != CoverageOK && state != CoveragePartial && !hasCode(ev.Disabled, CodeNoTimeout) && hasCode(ev.Ran, CodeNoTimeout) {
			t.Errorf("%s ran without facts", state)
		}
	}
	s := positives[CodeNoTimeout]()
	s.Coverage[SourceWorkflows] = SourceState{State: CoveragePartial}
	if ev := Evaluate(s, Policy{}); ev.Complete {
		t.Fatal("partial positive evidence was called complete")
	}
	if _, ok := finding(Evaluate(s, Policy{}), CodeNoTimeout); !ok {
		t.Fatal("positive evidence from a partial read was lost")
	}
}
func TestFirstPartyPinsAndPrivateTokenDeclarationsAreAdvice(t *testing.T) {
