	"github.com/eyupio/zoomies/internal/naming"
)

// fakeRoot builds a filesystem root carrying the files detect reads.
func fakeRoot(t *testing.T, files map[string]string) string {
	t.Helper()
	root := t.TempDir()
	for name, body := range files {
		path := filepath.Join(root, name)
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			t.Fatalf("MkdirAll: %v", err)
		}
		if err := os.WriteFile(path, []byte(body), 0o644); err != nil {
			t.Fatalf("WriteFile: %v", err)
		}
	}
	return root
}

const ubuntuOSRelease = `PRETTY_NAME="Ubuntu 24.04.1 LTS"
NAME="Ubuntu"
VERSION_ID="24.04"
VERSION="24.04.1 LTS (Noble Numbat)"
ID=ubuntu
ID_LIKE=debian
`

func TestDetectReadsTheDistribution(t *testing.T) {
	if runtime.GOOS != "linux" {
		t.Skip("the os-release probe is the Linux path")
	}
	root := fakeRoot(t, map[string]string{
		"etc/os-release": ubuntuOSRelease,
		"proc/meminfo":   "MemTotal:       32906892 kB\nMemFree:         1234 kB\n",
	})
	m := detect(root)
	if m.Distro != "ubuntu" || m.OSVersion != "24.04" {
		t.Errorf("distro/version = %q/%q, want ubuntu/24.04", m.Distro, m.OSVersion)
	}
	if m.MemoryMB != 32135 {
		t.Errorf("MemoryMB = %d, want 32135 (32906892 kB)", m.MemoryMB)
	}
	if m.CPUs != runtime.NumCPU() {
		t.Errorf("CPUs = %d, want this machine's %d", m.CPUs, runtime.NumCPU())
	}
}

func TestDetectPrefersACgroupLimit(t *testing.T) {
	if runtime.GOOS != "linux" {
		t.Skip("cgroups are the Linux path")
	}
	// An agent inside a two-core container must not tell the controller it has
	// the host's cores: every pool sized from that number would be wrong.
	root := fakeRoot(t, map[string]string{
		"etc/os-release":           ubuntuOSRelease,
		"proc/meminfo":             "MemTotal:       32906892 kB\n",
		"sys/fs/cgroup/cpu.max":    "150000 100000\n",
		"sys/fs/cgroup/memory.max": "2147483648\n",
	})
	m := detect(root)
	// 1.5 cores rounds up: the container can still burst onto the second.
	if m.CPUs != 2 {
		t.Errorf("CPUs = %d, want 2 from a 1.5-core quota", m.CPUs)
	}
	if m.MemoryMB != 2048 {
		t.Errorf("MemoryMB = %d, want 2048 from the cgroup limit", m.MemoryMB)
	}
}

func TestDetectIgnoresAnUnlimitedCgroup(t *testing.T) {
	if runtime.GOOS != "linux" {
		t.Skip("cgroups are the Linux path")
	}
	root := fakeRoot(t, map[string]string{
		"etc/os-release":           ubuntuOSRelease,
		"proc/meminfo":             "MemTotal:       32906892 kB\n",
		"sys/fs/cgroup/cpu.max":    "max 100000\n",
		"sys/fs/cgroup/memory.max": "max\n",
	})
	m := detect(root)
	if m.CPUs != runtime.NumCPU() {
		t.Errorf("CPUs = %d, want this machine's %d", m.CPUs, runtime.NumCPU())
	}
	if m.MemoryMB != 32135 {
		t.Errorf("MemoryMB = %d, want the host's total", m.MemoryMB)
	}
}

func TestDetectSaysNothingRatherThanGuessing(t *testing.T) {
	if runtime.GOOS != "linux" {
		t.Skip("the os-release probe is the Linux path")
	}
	// A distribution the catalogue does not know must not end up in the
	// column: it would never match a pool, and it would look like a promise.
	root := fakeRoot(t, map[string]string{
		"etc/os-release": "ID=voidlinux\nVERSION_ID=rolling\n",
	})
	m := detect(root)
	if m.Distro != "" {
		t.Errorf("Distro = %q, want empty for a distribution Zoomies does not know", m.Distro)
	}
	// An empty root: no os-release, no meminfo, no cgroup. Detection must
	// still return something usable rather than fail.
	bare := detect(t.TempDir())
	if bare.OS != runtime.GOOS || bare.Arch != runtime.GOARCH || bare.CPUs < 1 {
		t.Errorf("detect on a bare root = %+v", bare)
	}
}

func TestSpecNamesTheMachine(t *testing.T) {
	m := Facts{OS: "linux", Distro: "ubuntu", OSVersion: "24.04", Arch: "arm64", CPUs: 16, MemoryMB: 32768}
	if got, want := m.Spec("build01").String(), "zoomies-16vcpu-32gb-ubuntu-2404-arm64-build01"; got != want {
		t.Errorf("Spec = %q, want %q", got, want)
	}
	// A host that cannot say what distribution it is falls back to the kernel,
	// which at least tells macOS and Windows apart from Linux.
	mac := Facts{OS: "darwin", OSVersion: "15", Arch: "arm64", CPUs: 8}
	if got, want := mac.Spec("laptop").String(), "zoomies-8vcpu-macos-15-arm64-laptop"; got != want {
		t.Errorf("Spec = %q, want %q", got, want)
	}
}

func TestDefaultHostNameIsBranded(t *testing.T) {
	name := DefaultHostName()
	if name == "" {
		t.Fatal("DefaultHostName returned nothing")
	}
	// It is either a canonical name or, on a machine that says nothing about
	// itself, the slugged hostname. Neither may be empty or unusable.
	if err := naming.Validate(name); err != nil {
		t.Errorf("DefaultHostName returned %q, which is not a usable name: %v", name, err)
	}
}

func TestDetectReadsTheClockSpeed(t *testing.T) {
	if runtime.GOOS != "linux" {
		t.Skip("the cpufreq probe is the Linux path")
	}
	// cpufreq's figure is the rated ceiling, and wins over the moment's
	// frequency /proc/cpuinfo reports, because a priority scored from the
	// moment's frequency moves as the machine idles.
	root := fakeRoot(t, map[string]string{
		"proc/cpuinfo": "processor\t: 0\narchitecture: x86_64\ncpu MHz\t\t: 1200.000\n\nprocessor\t: 1\ncpu MHz\t\t: 3600.000\n",
		"sys/devices/system/cpu/cpu0/cpufreq/cpuinfo_max_freq": "4800000\n",
	})
	m := detect(root)
	if m.CPUMHz != 4800 {
		t.Errorf("CPUMHz = %d, want 4800 from cpufreq", m.CPUMHz)
	}
	without := fakeRoot(t, map[string]string{
		"proc/cpuinfo": "processor\t: 0\ncpu MHz\t\t: 3200.000\nprocessor\t: 1\ncpu MHz\t\t: 3100.000\n",
	})
	if m := detect(without); m.CPUMHz != 3200 {
		t.Errorf("CPUMHz from cpuinfo = %d, want 3200", m.CPUMHz)
	}
	// A machine that answers neither is unmeasured, which is what constrains
	// nothing: it still reports its cores.
	dumb := detect(t.TempDir())
	if dumb.CPUMHz != 0 {
		t.Errorf("CPUMHz = %d, want unmeasured on a bare root", dumb.CPUMHz)
	}
}

func TestParseMemorySpeedReadsTheRatedFigure(t *testing.T) {
	if got := parseMemorySpeed(`Handle 0x0001, DMI type 17, 22 bytes
	Size: 8192 MB
	Type: DDR4
	Configured Memory Speed: 4800 MT/s
	Speed: 3200 MT/s
	Serial Number: 3B13F2B2
`); got != 4800 {
		t.Errorf("configured speed = %d, want 4800 MT/s", got)
	}
	// Older modules say MHz, which mongrel spelling names half the rate the
	// newer one does.
	if got := parseMemorySpeed("Speed: 1600 MHz\n"); got != 800 {
		t.Errorf("MHz speed = %d, want 800 MT/s from 1600 MHz", got)
	}
	if got := parseMemorySpeed("Configured Memory Speed: Unknown\n"); got != 0 {
		t.Errorf("unknown speed = %d, want unmeasured", got)
	}
}

func TestRootDiskKindAsksTheBackingDevice(t *testing.T) {
	if runtime.GOOS != "linux" {
		t.Skip("the rotational probe is the Linux path")
	}
	t.Run("the device under the work root is what is asked", func(t *testing.T) {
		// The root directory detect() reads from is also the mount point the
		// agent's work is considered to live under, so the fixture says both.
		root := fakeRoot(t, map[string]string{
			"proc/mounts":                        "/dev/nvme0n1p3 /root ext4 rw,relatime 0 0\n/dev/sda1 /media/scratch ext4 rw 0 0\n",
			"sys/block/nvme0n1/queue/rotational": "0\n",
		})
		mounts := filepath.Join(root, "proc", "mounts")
		if err := os.WriteFile(mounts, []byte(fmt.Sprintf("/dev/nvme0n1p3 %s ext4 rw,relatime 0 0\n/dev/sda1 /media/scratch ext4 rw 0 0\n", root)), 0o644); err != nil {
			t.Fatalf("WriteFile: %v", err)
		}
		if got := rootDiskKind(mounts, root); got != "ssd" {
			t.Errorf("DiskKind = %q, want ssd", got)
		}
		root = fakeRoot(t, map[string]string{
			"sys/block/sdb/queue/rotational": "1\n",
		})
		if err := os.MkdirAll(filepath.Dir(filepath.Join(root, "proc", "mounts")), 0o755); err != nil {
			t.Fatalf("MkdirAll: %v", err)
		}
		if err := os.WriteFile(filepath.Join(root, "proc", "mounts"), []byte(fmt.Sprintf("/dev/sdb1 %s ext4 rw 0 0\n", root)), 0o644); err != nil {
			t.Fatalf("WriteFile: %v", err)
		}
		if got := rootDiskKind(filepath.Join(root, "proc", "mounts"), root); got != "hdd" {
			t.Errorf("DiskKind = %q, want hdd", got)
		}
	})
	t.Run("a device the kernel will not describe stays unmeasured", func(t *testing.T) {
		// Overlay filesystems name no block device, which is what an agent in
		// a container is on: the probe must give up rather than read another
		// disk in the tree.
		root := fakeRoot(t, map[string]string{
			"proc/mounts":                    "overlay / overlay rw 0 0\n",
			"sys/block/sda/queue/rotational": "0\n",
		})
		if got := rootDiskKind(filepath.Join(root, "proc", "mounts"), root); got != "" {
			t.Errorf("DiskKind = %q, want unmeasured behind a non-device mount", got)
		}
	})
	t.Run("other filesystems on the same tree do not answer", func(t *testing.T) {
		root := fakeRoot(t, map[string]string{
			"proc/mounts":                    "proc /proc proc rw 0 0\n/dev/sda1 /home ext4 rw 0 0\n",
			"sys/block/sda/queue/rotational": "1\n",
		})
		if got := rootDiskKind(filepath.Join(root, "proc", "mounts"), root); got != "" {
			t.Errorf("DiskKind = %q, want unmeasured when nothing backs /", got)
		}
	})
}

//go:build windows

package machine

import (
	"strconv"
	"unsafe"

	"golang.org/x/sys/windows"
)

// windowsFacts reports the Windows release and the physical memory.
//
// The release is the marketing number a pool would ask for -- "10" or "11" --
// rather than the kernel's 10.0.x, because a pool that says os=windows
// version=11 is written by a person, and Windows 11 reports itself as
// kernel 10.0 build 22000 and up. Server editions report the same kernel and
// are called "10" here, which is the honest limit of the version API.
func windowsFacts() (version string, memoryMB int64) {
	v := windows.RtlGetVersion()
	switch {
	case v == nil:
	case v.MajorVersion == 10 && v.BuildNumber >= 22000:
		version = "11"
	default:
		version = strconv.Itoa(int(v.MajorVersion))
	}
	return version, physicalMemoryMB()
}

// memoryStatusEx is MEMORYSTATUSEX from sysinfoapi.h.
type memoryStatusEx struct {
	length               uint32
	memoryLoad           uint32
	totalPhys            uint64
	availPhys            uint64
	totalPageFile        uint64
	availPageFile        uint64
	totalVirtual         uint64
	availVirtual         uint64
	availExtendedVirtual uint64
}

var procGlobalMemoryStatusEx = windows.NewLazySystemDLL("kernel32.dll").NewProc("GlobalMemoryStatusEx")

// physicalMemoryMB asks kernel32 directly: x/sys/windows wraps the version
// and disk calls but not this one, and one procedure lookup is smaller than
// a dependency that does.
func physicalMemoryMB() int64 {
	var st memoryStatusEx
	st.length = uint32(unsafe.Sizeof(st))
	r, _, _ := procGlobalMemoryStatusEx.Call(uintptr(unsafe.Pointer(&st)))
	if r == 0 {
		return 0
	}
	return int64(st.totalPhys / (1024 * 1024))
}

package machine

import (
	"math"
	"os"
	"path/filepath"
	"runtime"
	"strconv"
	"strings"
	"sync"
)

// Usage describes the whole machine, including work not owned by Zoomies.
// A missing value means unmeasured, never idle. Linux procfs is the only
// source for now; other platforms retain reservation-based placement.
type Usage struct {
	CPUPercent        *float64
	MemoryAvailableMB *int64
	// LoadAverage1 is the kernel's one-minute load average: the mean number
	// of runnable or uninterruptible tasks. It is the figure that keeps
	// climbing after CPU occupancy has pinned at 100%, so it is what says how
	// far past its cores a host has been pushed rather than merely that it is
	// busy. Whole-machine, like the other two, so it is only reported where
	// the CPU count is the machine's.
	LoadAverage1 *float64
	// IOWaitPercent is the share of CPU time the machine spent idle with
	// something waiting on disk, between two samples. CPUPercent counts that
	// time as busy, which is right for deciding whether a host has room and
	// wrong for asking why a job is slow: a build waiting on a saturated disk
	// reads as a machine hard at work. This is the figure that tells the two
	// apart, and the reason a pool is told its scratch folders could live in
	// memory.
	IOWaitPercent *float64
}

// UsageSampler takes CPU deltas between heartbeats without sleeping or asking
// Docker to do more work while it may already be overloaded.
type UsageSampler struct {
	mu          sync.Mutex
	root        string
	total, idle uint64
	iowait      uint64
	cpus        int
}

func (s *UsageSampler) Sample(cpus int, memoryMB int64) Usage {
	s.mu.Lock()
	defer s.mu.Unlock()
	var out Usage
	stat, err := os.ReadFile(filepath.Join(s.root, "/proc/stat"))
	if err == nil {
		total, idle, count, ok := cpuTicks(string(stat))
		iowait, ioOK := ioWaitTicks(string(stat))
		if ok && count == cpus && count == s.cpus && total > s.total && idle >= s.idle && idle-s.idle <= total-s.total {
			percent := 100 * (1 - float64(idle-s.idle)/float64(total-s.total))
			out.CPUPercent = &percent
			// Only beside a CPU figure: both are shares of the same interval,
			// and a counter that went backwards is not the machine sampled
			// last time.
			if ioOK && iowait >= s.iowait && iowait-s.iowait <= total-s.total {
				wait := 100 * float64(iowait-s.iowait) / float64(total-s.total)
				out.IOWaitPercent = &wait
			}
		}
		if ok && count == cpus {
			s.total, s.idle, s.iowait, s.cpus = total, idle, iowait, count
		} else {
			s.total, s.idle, s.iowait, s.cpus = 0, 0, 0, 0
		}
	} else {
		s.total, s.idle, s.iowait, s.cpus = 0, 0, 0, 0
	}
	mem, err := os.ReadFile(filepath.Join(s.root, "/proc/meminfo"))
	if err == nil {
		total, available, ok := availableMemory(string(mem))
		// Never label an agent cgroup's figures as its sibling runners' host,
		// or a remote daemon's machine as the one this process can see.
		if ok && total == memoryMB {
			out.MemoryAvailableMB = &available
		}
	}
	// The load average is only meaningful against the CPU count it is read
	// beside, so it is subject to the same test the CPU sample is: procfs has
	// to be describing the machine the caller believes it is on.
	if la, err := os.ReadFile(filepath.Join(s.root, "/proc/loadavg")); err == nil && s.cpus == cpus && cpus > 0 {
		if v, ok := loadAverage(string(la)); ok {
			out.LoadAverage1 = &v
		}
	}
	return out
}

// MemoryReadable reports whether this platform has a way to read the host's
// memory that the memory valve can check a loan against: Linux's procfs, and
// nothing else for now.
func MemoryReadable() bool { return runtime.GOOS == "linux" }

// Memory is the host's memory as the kernel reports it at one moment.
type Memory struct {
	TotalMB, AvailableMB int64
	// SwapTotalMB and SwapFreeMB are the machine's swap, both zero on a host
	// with none -- which is a measurement and not a failure to measure.
	SwapTotalMB, SwapFreeMB int64
}

// Memory reads the host's memory now. It is the look the memory valve takes
// before it lends any: unlike the CPU sample it needs no interval, so it can be
// taken every second without costing anything.
//
// It answers only for the machine the caller believes it is on, as Sample does:
// a total that is not memoryMB is an agent's cgroup or a remote daemon's
// machine, and its free memory says nothing about the host the runners share.
func (s *UsageSampler) Memory(memoryMB int64) (Memory, bool) {
	s.mu.Lock()
	root := s.root
	s.mu.Unlock()
	raw, err := os.ReadFile(filepath.Join(root, "/proc/meminfo"))
	if err != nil {
		return Memory{}, false
	}
	return parseMemory(string(raw), memoryMB)
}

func parseMemory(raw string, memoryMB int64) (Memory, bool) {
	total, available, ok := availableMemory(raw)
	if !ok || total != memoryMB {
		return Memory{}, false
	}
	out := Memory{TotalMB: total, AvailableMB: available}
	for _, line := range strings.Split(raw, "\n") {
		fields := strings.Fields(line)
		if len(fields) != 3 || fields[2] != "kB" {
			continue
		}
		v, err := strconv.ParseInt(fields[1], 10, 64)
		if err != nil || v < 0 {
			continue
		}
		switch fields[0] {
		case "SwapTotal:":
			out.SwapTotalMB = v / 1024
		case "SwapFree:":
			out.SwapFreeMB = v / 1024
		}
	}
	return out, true
}

// loadAverage reads the one-minute figure from /proc/loadavg, whose first
// three fields are the 1, 5 and 15 minute averages.
func loadAverage(raw string) (float64, bool) {
	fields := strings.Fields(raw)
	if len(fields) < 3 {
		return 0, false
	}
	v, err := strconv.ParseFloat(fields[0], 64)
	if err != nil || v < 0 || math.IsNaN(v) || math.IsInf(v, 0) {
		return 0, false
	}
	return v, true
}

// ioWaitTicks reads the iowait counter from the aggregate cpu line of
// /proc/stat: the fifth number after the name, after user, nice, system and
// idle. A kernel too old to report it has a shorter line, which is not
// measured rather than zero.
func ioWaitTicks(raw string) (uint64, bool) {
	for _, line := range strings.Split(raw, "\n") {
		fields := strings.Fields(line)
		if len(fields) < 6 || fields[0] != "cpu" {
			continue
		}
		v, err := strconv.ParseUint(fields[5], 10, 64)
		return v, err == nil
	}
	return 0, false
}

func cpuTicks(raw string) (total, idle uint64, cpus int, ok bool) {
	for _, line := range strings.Split(raw, "\n") {
		fields := strings.Fields(line)
		if len(fields) == 0 {
			continue
		}
		if fields[0] == "cpu" {
			if len(fields) < 5 {
				return 0, 0, 0, false
			}
			// Guest time is already included in user/nice. Count only the first
			// eight counters. I/O wait counts as unavailable CPU headroom here.
			for i := 1; i < len(fields) && i <= 8; i++ {
				v, err := strconv.ParseUint(fields[i], 10, 64)
				if err != nil || total+v < total {
					return 0, 0, 0, false
				}
				total += v
				if i == 4 {
					idle = v
				}
			}
			ok = true
		} else if strings.HasPrefix(fields[0], "cpu") {
			if _, err := strconv.Atoi(strings.TrimPrefix(fields[0], "cpu")); err == nil {
				cpus++
			}
		}
	}
	return total, idle, cpus, ok && cpus > 0
}

func availableMemory(raw string) (total, available int64, ok bool) {
	total, available = -1, -1
	for _, line := range strings.Split(raw, "\n") {
		fields := strings.Fields(line)
		if len(fields) != 3 || fields[2] != "kB" {
			continue
		}
		if fields[0] != "MemTotal:" && fields[0] != "MemAvailable:" {
			continue
		}
		v, err := strconv.ParseInt(fields[1], 10, 64)
		if err != nil || v < 0 {
			return 0, 0, false
		}
		if fields[0] == "MemTotal:" {
			total = v
		} else {
			available = v
		}
	}
	// MemAvailable includes reclaimable caches; MemFree alone would call a
	// healthy build host full just because Linux put idle memory to use.
	return total / 1024, available / 1024, total >= 1024 && available >= 0 && available <= total
}

package machine

import (
	"os"
	"path/filepath"
	"testing"
)

func TestUsageMeasuresDeltasAndAvailableMemoryWithoutSleeping(t *testing.T) {
	root := t.TempDir()
	if err := os.Mkdir(filepath.Join(root, "proc"), 0o700); err != nil {
		t.Fatal(err)
	}
	write := func(name, body string) {
		t.Helper()
		if err := os.WriteFile(filepath.Join(root, "proc", name), []byte(body), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	write("meminfo", "MemTotal: 8388608 kB\nMemFree: 1024 kB\nMemAvailable: 4194304 kB\n")
	write("stat", "cpu 100 0 0 100 0 0 0 0 99 0\ncpu0 0\ncpu1 0\n")
	write("loadavg", "5.25 3.10 1.00 3/512 4242\n")
	s := UsageSampler{root: root}
	first := s.Sample(2, 8192)
	if first.CPUPercent != nil || first.MemoryAvailableMB == nil || *first.MemoryAvailableMB != 4096 {
		t.Fatalf("first sample must report available memory but no CPU delta: %+v", first)
	}
	// The load average needs no delta, but it does need the CPU count to be
	// the machine's: a figure of 5 means something different beside 2 cores
	// than beside 64, so it is reported only once procfs has been checked
	// against the caller's view, which the first sample establishes.
	if first.LoadAverage1 == nil || *first.LoadAverage1 != 5.25 {
		t.Fatalf("load average = %v, want 5.25 from the first field of /proc/loadavg", first.LoadAverage1)
	}
	write("stat", "cpu 125 0 0 175 0 0 0 0 124 0\ncpu0 0\ncpu1 0\n")
	u := s.Sample(2, 8192)
	if u.CPUPercent == nil || *u.CPUPercent != 25 {
		t.Fatalf("CPU = %v, want 25%% (guest already counted)", u.CPUPercent)
	}
	if u.LoadAverage1 == nil || *u.LoadAverage1 != 5.25 {
		t.Fatalf("load average = %v on the second sample, want 5.25", u.LoadAverage1)
	}
	// A reboot or CPU topology change starts a new baseline, not an enormous
	// negative utilisation that attracts every queued job.
	write("stat", "cpu 1 0 0 1 0 0 0 0\ncpu0 0\ncpu1 0\n")
	if s.Sample(2, 8192).CPUPercent != nil {
		t.Fatal("counter reset became a valid CPU sample")
	}
	if got := s.Sample(1, 2048); got.CPUPercent != nil || got.MemoryAvailableMB != nil || got.LoadAverage1 != nil {
		t.Fatalf("physical host figures were attributed to a smaller cgroup: %+v", got)
	}
}

// A load average is read from the same file every Linux kernel writes, and the
// two ways it can be wrong are the two ways any procfs figure can be: absent,
// or not a number. Neither may become a reading of zero, because zero load is
// the one value that would let an overwhelmed host look idle.
func TestLoadAverageRejectsWhatItCannotRead(t *testing.T) {
	for _, raw := range []string{"", "x y z", "-1 0 0 1/2 3", "NaN 0 0 1/2 3", "1.5"} {
		if _, ok := loadAverage(raw); ok {
			t.Errorf("accepted %q", raw)
		}
	}
	if v, ok := loadAverage("0.00 0.01 0.05 1/100 200"); !ok || v != 0 {
		t.Fatalf("a measured idle host was rejected: %v %v", v, ok)
	}
}

func TestMissingAndInvalidUsageNeverBecomeIdleReadings(t *testing.T) {
	s := UsageSampler{root: t.TempDir()}
	if u := s.Sample(2, 8192); u.CPUPercent != nil || u.MemoryAvailableMB != nil {
		t.Fatal("missing procfs became measured usage")
	}
	for _, raw := range []string{"", "cpu broken 1 2 3\ncpu0 0", "cpu 1 2 3 4"} {
		if _, _, _, ok := cpuTicks(raw); ok {
			t.Fatalf("accepted %q", raw)
		}
	}
	for _, raw := range []string{"MemTotal: 8192 kB\nMemFree: 4096 kB", "MemTotal: 8192 kB\nMemAvailable: 9000 kB", "MemTotal: 8192 kB\nMemAvailable: -1 kB"} {
		if _, _, ok := availableMemory(raw); ok {
			t.Fatalf("accepted %q", raw)
		}
	}
	if _, available, ok := availableMemory("MemTotal: 8192 kB\nMemAvailable: 0 kB"); !ok || available != 0 {
		t.Fatal("a measured full host was treated as unmeasured")
	}
}

// I/O wait is read from the same counters as CPU, and is only a figure beside a
// CPU delta: the two are shares of the same interval.
func TestUsageMeasuresIOWaitFromTheSameDeltasAsCPU(t *testing.T) {
	root := t.TempDir()
	if err := os.Mkdir(filepath.Join(root, "proc"), 0o700); err != nil {
		t.Fatal(err)
	}
	write := func(name, body string) {
		t.Helper()
		if err := os.WriteFile(filepath.Join(root, "proc", name), []byte(body), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	write("meminfo", "MemTotal: 8388608 kB\nMemFree: 1024 kB\nMemAvailable: 4194304 kB\n")
	// user nice system idle iowait: 100 ticks in all, none of them waiting.
	write("stat", "cpu 50 0 0 50 0 0 0 0 0 0\ncpu0 0\ncpu1 0\n")
	s := UsageSampler{root: root}
	if first := s.Sample(2, 8192); first.IOWaitPercent != nil {
		t.Fatalf("the first sample has no delta to take a share of: %v", *first.IOWaitPercent)
	}
	// 100 more ticks, 40 of them waiting on disk.
	write("stat", "cpu 80 0 0 80 40 0 0 0 0 0\ncpu0 0\ncpu1 0\n")
	u := s.Sample(2, 8192)
	if u.IOWaitPercent == nil || *u.IOWaitPercent != 40 {
		t.Fatalf("io wait = %v, want 40%% of the interval", u.IOWaitPercent)
	}
	// iowait is part of what CPUPercent calls busy: 100 - idle share (30/140).
	if u.CPUPercent == nil {
		t.Fatal("no CPU figure beside the I/O wait")
	}

	// A kernel whose cpu line stops before iowait reports nothing, not zero.
	write("stat", "cpu 90 0 0 90\ncpu0 0\ncpu1 0\n")
	if u := s.Sample(2, 8192); u.IOWaitPercent != nil {
		t.Fatalf("a line with no iowait counter reported %v", *u.IOWaitPercent)
	}

	// A counter that goes backwards is a different machine than last time.
	write("stat", "cpu 200 0 0 200 80 0 0 0 0 0\ncpu0 0\ncpu1 0\n")
	_ = s.Sample(2, 8192)
	write("stat", "cpu 300 0 0 300 10 0 0 0 0 0\ncpu0 0\ncpu1 0\n")
	if u := s.Sample(2, 8192); u.IOWaitPercent != nil {
		t.Fatalf("a counter that went backwards reported %v", *u.IOWaitPercent)
	}
}

// The memory valve looks at the host before it lends anything, and what it
// needs from the look is free memory and free swap: the first decides whether a
// loan can be made, the second whether swap can be offered instead.
func TestAHostsMemoryNowIsReadWithItsSwap(t *testing.T) {
	root := t.TempDir()
	if err := os.Mkdir(filepath.Join(root, "proc"), 0o700); err != nil {
		t.Fatal(err)
	}
	meminfo := "MemTotal: 8388608 kB\nMemFree: 1024 kB\nMemAvailable: 3145728 kB\nSwapTotal: 4194304 kB\nSwapFree: 2097152 kB\n"
	if err := os.WriteFile(filepath.Join(root, "proc", "meminfo"), []byte(meminfo), 0o600); err != nil {
		t.Fatal(err)
	}
	s := UsageSampler{root: root}
	got, ok := s.Memory(8192)
	if !ok || got != (Memory{TotalMB: 8192, AvailableMB: 3072, SwapTotalMB: 4096, SwapFreeMB: 2048}) {
		t.Fatalf("memory = %+v, %v; want 3072 MB available and 2048 of 4096 MB of swap free", got, ok)
	}

	// A host with no swap says so with zeroes, which is a measurement.
	if err := os.WriteFile(filepath.Join(root, "proc", "meminfo"), []byte("MemTotal: 8388608 kB\nMemAvailable: 3145728 kB\nSwapTotal: 0 kB\nSwapFree: 0 kB\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	if got, ok := s.Memory(8192); !ok || got.SwapTotalMB != 0 || got.SwapFreeMB != 0 || got.AvailableMB != 3072 {
		t.Fatalf("memory = %+v, %v; want free memory read and no swap", got, ok)
	}
}

// The figures are a physical machine's. An agent in a smaller cgroup, or one
// talking to a remote daemon, must not have them attributed to the machine its
// runners share, or a loan would be made out of memory that is not theirs.
func TestAnotherMachinesMemoryIsNotTakenForTheHosts(t *testing.T) {
	root := t.TempDir()
	if err := os.Mkdir(filepath.Join(root, "proc"), 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(root, "proc", "meminfo"), []byte("MemTotal: 8388608 kB\nMemAvailable: 3145728 kB\nSwapTotal: 0 kB\nSwapFree: 0 kB\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	s := UsageSampler{root: root}
	if got, ok := s.Memory(2048); ok {
		t.Fatalf("memory = %+v for a smaller machine, want nothing", got)
	}
	// And a host with no procfs at all is not guessed at.
	if _, ok := (&UsageSampler{root: t.TempDir()}).Memory(8192); ok {
		t.Fatal("a host with no /proc/meminfo reported memory")
	}
}

package mcp

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/url"
	"sort"
	"strings"
)

// The administrator tools: the part of a host and of the settings page an
// agent can reach once an administrator has switched `security.mcp_admin_tools`
// on. They sit apart from update_pool and update_host because the people who
// may use them are not the same: the sizing tools need an operator, these need
// an administrator, and an administrator's token is the one an agent steered by
// workflow-written text can least afford to hold by default.
//
// The transport offers them only when the controller's switch is on and the
// credential's role is administrator; the controller still decides each call on
// its own route. What this file adds on top is the settings allowlist below,
// because "may change settings" must not mean "may change how people sign in".

// adminTools is every tool the controller's switch governs.
var adminTools = map[string]bool{
	"edit_host":           true,
	"clear_host_throttle": true,
	"get_settings":        true,
	"update_settings":     true,
}

// IsAdminTool reports whether a tool is one the administrator switch governs.
func IsAdminTool(name string) bool { return adminTools[name] }

// tunableSettings are what update_settings may write: a name ending in a dot is
// every key under it, and any other name is that one key. They are the knobs
// that shape scheduling, retention and limits. Everything that decides who gets in,
// what the controller trusts or where it keeps its state -- security, oidc,
// github, provider, server, database, agent, backup -- is not here, so an
// agent that has been talked into a bad change can at worst make the fleet
// slower or tidier, and not locked open.
//
// updates is here by one key only. How often github.com is asked which release
// is current is as harmless as the rest, but updates.mode decides whether this
// controller replaces its own binary with nobody pressing anything, and
// updates.soak is the wait that stands between a bad release and every host. An
// agent steered by text a workflow wrote must not be able to switch either on
// or shorten it, so a person makes those at the Settings page, and a new key in
// the section is not tunable until it is named here.
var tunableSettings = []string{
	"scheduler.", "capacity_demand.", "retention.", "runners.", "limits.",
	"log.", "metrics.", "images.", "status.", "ui.", "updates.check_interval",
}

func tunable(key string) bool {
	for _, p := range tunableSettings {
		if strings.HasSuffix(p, ".") {
			if strings.HasPrefix(key, p) {
				return true
			}
		} else if key == p {
			return true
		}
	}
	return false
}

// tunableList is the allowlist as a person reads it, with the one rule that
// tells a section from a single key.
func tunableList() string {
	return strings.Join(tunableSettings, " ") + " (a name ending in a dot stands for every key under it)"
}

func adminConfigTools() []*tool {
	return []*tool{
		{
			Name:  "edit_host",
			Title: "Rename, relabel, reserve disk on or cordon a host",
			Description: "Change a host's name, its labels, the disk it keeps back, or whether it is cordoned, leaving every other setting as it " +
				"is. Labels are replaced whole: read the host (list_hosts) and send the full set you want. A cordoned host keeps its running " +
				"runners and takes no new ones. Needs an administrator token and `security.mcp_admin_tools` on. The controller refuses a " +
				"change that would leave a pool with no host that could run it, and this tool never passes confirm=true.",
			InputSchema: object([]string{"host_id"}, map[string]any{
				"host_id":         str("the host's ID, starting host_"),
				"name":            str("what the host is called; non-empty, no control characters, not used by another host"),
				"labels":          map[string]any{"type": "object", "additionalProperties": map[string]any{"type": "string"}, "description": "the host's whole label set, which replaces the one it has"},
				"reserve_disk_mb": map[string]any{"type": "integer", "minimum": 0, "description": "disk held back from placement, in MiB"},
				"cordoned":        boolean("true stops the host taking new runners, false lets it take them again"),
			}),
			Annotations: annotations{Idempotent: true},
			action:      true,
			call:        editHost,
		},
		{
			Name:  "clear_host_throttle",
			Title: "Lift a host's throttle",
			Description: "Lift the throttle the controller has a host on, so it takes its configured capacity again on the next pass. The next " +
				"heartbeat steps it back up if the pressure is still there, so use it for a host whose cause is known and fixed, not to switch " +
				"throttling off. Needs an administrator token and `security.mcp_admin_tools` on.",
			InputSchema: object([]string{"host_id"}, map[string]any{
				"host_id": str("the host's ID, starting host_"),
			}),
			Annotations: annotations{Idempotent: true},
			action:      true,
			call: func(ctx context.Context, c API, raw json.RawMessage) ([]Content, error) {
				var a struct {
					HostID string `json:"host_id"`
				}
				if err := decodeArgs(raw, &a); err != nil {
					return nil, err
				}
				if err := requireID("host_id", a.HostID); err != nil {
					return nil, err
				}
				bc, ok := c.(BodyCaller)
				if !ok {
					return nil, fmt.Errorf("this transport cannot change a host")
				}
				body, err := bc.CallBody(ctx, http.MethodPost, "/hosts/"+url.PathEscape(a.HostID)+"/throttle/clear", nil, []byte(`{}`))
				if err != nil {
					return nil, err
				}
				return jsonContent(body), nil
			},
		},
		{
			Name:  "get_settings",
			Title: "Read settings",
			Description: "Every configuration key with its value, kind and where it came from, optionally only those under a prefix such as " +
				"scheduler. A secret's value is never sent. Needs an administrator token and `security.mcp_admin_tools` on.",
			InputSchema: object(nil, map[string]any{
				"prefix": str("only keys starting with this, such as scheduler or retention.jobs"),
			}),
			Annotations: readOnly,
			action:      true,
			call:        getSettings,
		},
		{
			Name:  "update_settings",
			Title: "Change tuning settings",
			Description: "Change these settings: " + tunableList() + " -- scheduling, retention, limits and the like. " +
				"A null value clears the stored setting, so the key goes back to the file or the default. Every key is checked before any is " +
				"written and the whole call is refused if one fails. Security, sign-in, GitHub, provider, server, database, agent and backup " +
				"settings are not changeable here: a person makes those at the Settings page. A change the running process cannot apply is " +
				"stored and named in pending_restart. Needs an administrator token and `security.mcp_admin_tools` on.",
			InputSchema: object([]string{"changes"}, map[string]any{
				"changes": map[string]any{"type": "object", "minProperties": 1, "description": "dotted setting key to new value, such as {\"retention.jobs\":\"720h\"}"},
			}),
			Annotations: annotations{Idempotent: true},
			action:      true,
			call:        updateSettings,
		},
	}
}

func editHost(ctx context.Context, c API, raw json.RawMessage) ([]Content, error) {
	var a struct {
		HostID        string             `json:"host_id"`
		Name          *string            `json:"name"`
		Labels        *map[string]string `json:"labels"`
		ReserveDiskMB *int64             `json:"reserve_disk_mb"`
		Cordoned      *bool              `json:"cordoned"`
	}
	if err := decodeArgs(raw, &a); err != nil {
		return nil, err
	}
	if err := requireID("host_id", a.HostID); err != nil {
		return nil, err
	}
	if a.Name == nil && a.Labels == nil && a.ReserveDiskMB == nil && a.Cordoned == nil {
		return nil, fmt.Errorf("name at least one setting to change")
	}
	if a.Name != nil && strings.TrimSpace(*a.Name) == "" {
		return nil, fmt.Errorf("name cannot be empty")
	}
	bc, ok := c.(BodyCaller)
	if !ok {
		return nil, fmt.Errorf("this transport cannot change a host")
	}
	path := "/hosts/" + url.PathEscape(a.HostID)
	current, err := readObject(ctx, c, path, "host", a.HostID, "list_hosts")
	if err != nil {
		return nil, err
	}
	changes := map[string]change{}
	body := map[string]any{}
	if a.Name != nil {
		changes["name"] = change{Before: current["name"], After: *a.Name}
		body["name"] = *a.Name
	}
	if a.Labels != nil {
		changes["labels"] = change{Before: current["labels"], After: *a.Labels}
		body["labels"] = *a.Labels
	}
	if a.ReserveDiskMB != nil {
		changes["reserve_disk_mb"] = change{Before: current["reserve_disk_mb"], After: *a.ReserveDiskMB}
		body["reserve_disk_mb"] = *a.ReserveDiskMB
	}
	reply := sizingReply{
		ID:      a.HostID,
		Name:    stringOf(current["name"]),
		Changes: changes,
		Note:    "Read the host again (list_hosts) to see it as it is now.",
	}
	if len(body) > 0 {
		// Never confirm=true: see send.
		if _, err := send(ctx, bc, path, body, reply); err != nil {
			return nil, err
		}
	}
	if a.Cordoned != nil {
		payload, err := json.Marshal(map[string]bool{"cordoned": *a.Cordoned})
		if err != nil {
			return nil, err
		}
		if _, err := bc.CallBody(ctx, http.MethodPost, path+"/cordon", nil, payload); err != nil {
			if len(body) > 0 {
				return nil, fmt.Errorf("the other changes were saved, but cordoning failed: %w", err)
			}
			return nil, err
		}
		changes["cordoned"] = change{Before: current["cordoned"], After: *a.Cordoned}
	}
	out, err := json.Marshal(reply)
	if err != nil {
		return nil, err
	}
	return jsonContent(out), nil
}

func getSettings(ctx context.Context, c API, raw json.RawMessage) ([]Content, error) {
	var a struct {
		Prefix string `json:"prefix"`
	}
	if err := decodeArgs(raw, &a); err != nil {
		return nil, err
	}
	body, err := c.Call(ctx, http.MethodGet, "/settings", nil)
	if err != nil {
		return nil, err
	}
	var page struct {
		Settings       []json.RawMessage `json:"settings"`
		PendingRestart []string          `json:"pending_restart"`
		Pinned         []string          `json:"pinned_by_environment"`
	}
	if err := json.Unmarshal(body, &page); err != nil {
		return nil, fmt.Errorf("the settings came back unreadable: %w", err)
	}
	var keep []json.RawMessage
	for _, s := range page.Settings {
		var k struct {
			Key string `json:"key"`
		}
		if json.Unmarshal(s, &k) == nil && strings.HasPrefix(k.Key, a.Prefix) {
			keep = append(keep, s)
		}
	}
	out, err := json.Marshal(map[string]any{
		"settings":              keep,
		"pending_restart":       page.PendingRestart,
		"pinned_by_environment": page.Pinned,
	})
	if err != nil {
		return nil, err
	}
	return jsonContent(out), nil
}

func updateSettings(ctx context.Context, c API, raw json.RawMessage) ([]Content, error) {
	var a struct {
		Changes map[string]any `json:"changes"`
	}
	if err := decodeArgs(raw, &a); err != nil {
		return nil, err
	}
	if len(a.Changes) == 0 {
		return nil, fmt.Errorf("name at least one setting to change")
	}
	var refused []string
	for k := range a.Changes {
		if !tunable(k) {
			refused = append(refused, k)
		}
	}
	if len(refused) > 0 {
		sort.Strings(refused)
		return nil, fmt.Errorf("%s cannot be changed over MCP: only these can: %s. Make the others at the Settings page",
			strings.Join(refused, ", "), tunableList())
	}
	bc, ok := c.(BodyCaller)
	if !ok {
		return nil, fmt.Errorf("this transport cannot change settings")
	}
	payload, err := json.Marshal(a.Changes)
	if err != nil {
		return nil, err
	}
	answer, err := bc.CallBody(ctx, http.MethodPatch, "/settings", nil, payload)
	if err != nil {
		return nil, err
	}
	var sent struct {
		PendingRestart []string `json:"pending_restart"`
	}
	_ = json.Unmarshal(answer, &sent)
	keys := make([]string, 0, len(a.Changes))
	for k := range a.Changes {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	out, err := json.Marshal(map[string]any{
		"changed":         keys,
		"pending_restart": sent.PendingRestart,
		"note":            "Read the keys again with get_settings to see what is in force; anything in pending_restart waits for a controller restart.",
	})
	if err != nil {
		return nil, err
	}
	return jsonContent(out), nil
}

