	r := &recorder{object: `{}`}
	for _, key := range []string{"security.auto_apply_remedies", "security.mcp_admin_tools"} {
		_, err := call(t, "update_settings", r, `{"changes":{"`+key+`":true}}`)
		if err == nil || !strings.Contains(err.Error(), key) {
			t.Errorf("%s: error = %v, want a refusal naming it", key, err)
		}
	}
	if len(r.sent) != 0 {
		t.Errorf("a refused call sent %v", r.sent)
	}
}

// An assistant is steered by text a workflow wrote, so it must not be able to
// switch on a controller that replaces its own binary, or shorten the wait that
// stands between a bad release and every host. The check interval stays
// tunable: it only changes how often a question is put to github.com.
func TestUpdateSettingsCannotWriteTheUpdatesMode(t *testing.T) {
	if tunable("updates.mode") || tunable("updates.soak") {
		t.Error("the update mode or its soak is on the tuning allowlist")
	}
	if !tunable("updates.check_interval") {
		t.Error("updates.check_interval was taken off the tuning allowlist with the rest of the section")
	}

	r := &recorder{object: `{}`}
	for key, value := range map[string]string{"updates.mode": `"auto"`, "updates.soak": `"0"`} {
		_, err := call(t, "update_settings", r, `{"changes":{"`+key+`":`+value+`}}`)
		if err == nil || !strings.Contains(err.Error(), key) {
			t.Errorf("%s: error = %v, want a refusal naming it", key, err)
		}
	}
	if len(r.sent) != 0 {
		t.Errorf("a refused call sent %v", r.sent)
	}
	if _, err := call(t, "update_settings", r, `{"changes":{"updates.check_interval":"12h"}}`); err != nil {
		t.Errorf("the check interval was refused: %v", err)
	}
}

// An entry that does not end in a dot names one key. Read as a prefix it would
// also admit updates.check_interval_x the day the section grows one, and the
// allowlist exists so that a new key is not tunable until somebody names it.
func TestAnAllowlistEntryWithoutATrailingDotNamesOneKey(t *testing.T) {
	for key, want := range map[string]bool{
		"updates.check_interval":   true,
		"updates.check_interval_x": false,
		"updates.check_interval.x": false,
		"scheduler.anything":       true,
	} {
		if got := tunable(key); got != want {
			t.Errorf("tunable(%q) = %v, want %v", key, got, want)
		}
	}

	_, err := call(t, "update_settings", &recorder{object: `{}`}, `{"changes":{"updates.check_interval_x":"1h"}}`)
	if err == nil || !strings.Contains(err.Error(), "updates.check_interval_x cannot be changed over MCP") {
		t.Fatalf("error = %v, want a refusal naming the key", err)
	}
	if !strings.Contains(err.Error(), "only these can") || strings.Contains(err.Error(), "only keys under") {
		t.Errorf("the refusal reads as though every entry were a prefix: %v", err)
	}
}

package mcp

import (
	"go/build"
	"slices"
	"strings"
	"testing"
)

// AGENTS.md says a tool calls the REST API through the mcp.API interface and
// nothing else (no store, no controller), "so it can never do what the caller's
// token could not". That holds only while nothing in this package can reach the
// fleet except through that interface, so this lists what the package may import
// and fails on anything else, instead of trusting review to notice a convenient
// import of the store in a tool that "only needs to read one row".
//
// Each entry says why it is safe. A new helper that only computes belongs here
// with a reason; one that reaches the fleet does not.
var mayImport = map[string]string{
	"github.com/eyupio/zoomies/internal/analysis": "evidence-backed findings computed from snapshots handed to it; it reads no fleet state itself",
	"github.com/eyupio/zoomies/internal/version":  "build metadata stamped in at link time",
}

func TestMCPReachesTheFleetOnlyThroughTheAPIInterface(t *testing.T) {
	pkg, err := build.ImportDir(".", 0)
	if err != nil {
		t.Fatalf("reading this package: %v", err)
	}
	if len(pkg.Imports) == 0 {
		t.Fatal("no imports were found at all; the walk is wrong, not the package")
	}
	allowed := make([]string, 0, len(mayImport))
	for path := range mayImport {
		allowed = append(allowed, path)
	}
	slices.Sort(allowed)
	for _, path := range pkg.Imports {
		first, _, _ := strings.Cut(path, "/")
		if strings.Contains(first, ".") && strings.HasPrefix(path, "github.com/eyupio/zoomies/") {
			if _, ok := mayImport[path]; !ok {
				t.Errorf("internal/mcp imports %s; it may import only %s, because everything else it does goes through the mcp.API interface and so cannot exceed the caller's token. A package that only computes is added to mayImport with its reason; one that reads or acts on the fleet is not",
					path, strings.Join(allowed, ", "))
			}
		}
		for _, banned := range []string{"database/sql", "net/http/httptest"} {
			if path == banned {
				t.Errorf("internal/mcp imports %s, which is a way around the API interface", path)
			}
		}
	}
}

package mcp

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"strings"
)

// The catalog is the one place every problem code and every Kennel Club check
// is explained, and docs/ai-context.md tells an agent to read it before it
// explains a problem. An agent that reaches the fleet only over MCP had no way
// to: an OAuth token is good on /mcp alone. It is a few hundred kilobytes, far
// more than a tool answer should put in front of a model, so without arguments
// the tool is an index, and an entry comes by its code. The same two readings
// are the catalog's resources (resources.go).

// catalogCategories are the catalog's own, in the order an agent should look.
var catalogCategories = []string{"capacity", "reliability", "security", "configuration", "cost"}

// catalogEntry is the part of an entry the index and a category list keep.
type catalogEntry struct {
	ID       string `json:"id"`
	Kind     string `json:"kind"`
	Title    string `json:"title"`
	Category string `json:"category"`
	Severity string `json:"severity"`
}

// catalog is GET /catalog taken apart: the entries as the controller wrote
// them, and the slice of each the index keeps.
type catalog struct {
	version int
	raw     []json.RawMessage
	entries []catalogEntry
}

// readCatalog fetches the catalog with the caller's token and takes it apart,
// refusing a shape it cannot read rather than passing it on.
func readCatalog(ctx context.Context, c API) (*catalog, error) {
	body, err := c.Call(ctx, "GET", "/catalog", nil)
	if err != nil {
		return nil, err
	}
	var doc struct {
		Version int               `json:"version"`
		Entries []json.RawMessage `json:"entries"`
	}
	if err := json.Unmarshal(body, &doc); err != nil {
		return nil, errCatalogShape
	}
	var entries []catalogEntry
	if err := json.Unmarshal(body, &struct {
		Entries *[]catalogEntry `json:"entries"`
	}{&entries}); err != nil || len(entries) != len(doc.Entries) {
		return nil, errCatalogShape
	}
	return &catalog{version: doc.Version, raw: doc.Entries, entries: entries}, nil
}

// index is every code under its category, which is small enough to hand a
// model whole and enough to choose an entry from.
func (c *catalog) index() ([]byte, error) {
	categories := map[string][]string{}
	for _, e := range c.entries {
		categories[e.Category] = append(categories[e.Category], e.ID)
	}
	for _, ids := range categories {
		sort.Strings(ids)
	}
	return json.Marshal(map[string]any{"version": c.version, "categories": categories})
}

// category is one category's codes with their titles and severity.
func (c *catalog) category(name string) ([]byte, error) {
	out := make([]catalogEntry, 0, len(c.entries))
	for _, e := range c.entries {
		if e.Category == name {
			out = append(out, e)
		}
	}
	return json.Marshal(map[string]any{"version": c.version, "category": name, "entries": out})
}

// entry is one entry in full, as the controller wrote it, or false.
func (c *catalog) entry(code string) (json.RawMessage, bool) {
	for i, e := range c.entries {
		if e.ID == code {
			return c.raw[i], true
		}
	}
	return nil, false
}

// family is every code that shares a code's prefix before its first dot, in
// order: what to offer in place of a code that is not there.
func (c *catalog) family(code string) []string {
	prefix, _, ok := strings.Cut(code, ".")
	if !ok || prefix == "" {
		return nil
	}
	var out []string
	for _, e := range c.entries {
		if strings.HasPrefix(e.ID, prefix+".") {
			out = append(out, e.ID)
		}
	}
	sort.Strings(out)
	return out
}

func catalogTools() []*tool {
	return []*tool{
		{
			Name:  "get_catalog",
			Title: "Catalog of problem codes and checks",
			Description: "Every problem code the controller raises and every check Kennel Club makes, with what each means, what to change and how to see that it worked: " +
				"the catalog at GET /catalog, which is Zoomies' own fixed text and names no fleet, repository or person. " +
				"Without arguments it is an index, each code under its category (capacity, reliability, security, configuration, cost). " +
				"With code it is that one entry in full, which is what to read before explaining a problem's code, a finding's check or a job explanation's problem_code. " +
				"With category it is that category's codes with their titles and severity. " +
				"A code that is not in the catalog is said to be unknown; it is not an empty entry.",
			InputSchema: object(nil, map[string]any{
				"code":     str("a problem code or check id, as list_problems, get_job or kennel_findings show it, such as pool.no_host or ci.no_timeout"),
				"category": enum("list the codes of one category, with titles", catalogCategories...),
			}),
			Annotations: readOnly,
			call:        getCatalog,
		},
	}
}

func getCatalog(ctx context.Context, c API, raw json.RawMessage) ([]Content, error) {
	var a struct {
		Code     string `json:"code"`
		Category string `json:"category"`
	}
	if err := decodeArgs(raw, &a); err != nil {
		return nil, err
	}
	cat, err := readCatalog(ctx, c)
	if err != nil {
		return nil, err
	}
	switch {
	case a.Code != "":
		entry, ok := cat.entry(a.Code)
		if !ok {
			// A code one letter off is answered with its family's codes, so the
			// next call is the right one; a model shown "no such code" alone
			// guessed again, and again.
			if family := cat.family(a.Code); len(family) > 0 {
				return nil, fmt.Errorf("there is no %s in the catalog; the codes that start the same way are %s", a.Code, strings.Join(family, ", "))
			}
			return nil, fmt.Errorf("there is no %s in the catalog; get_catalog without arguments lists every code", a.Code)
		}
		return jsonContent(entry), nil
	case a.Category != "":
		body, err := cat.category(a.Category)
		if err != nil {
			return nil, err
		}
		return jsonContent(body), nil
	}
	body, err := cat.index()
	if err != nil {
		return nil, err
	}
	return jsonContent(body), nil
}

// errCatalogShape is a catalog the tool cannot take apart, refused rather than
// passed on, as the Kennel tools refuse an answer they cannot read.
var errCatalogShape = errors.New("the controller's catalog is not in the shape this tool expects; upgrade the controller and the CLI together")

package mcp

import (
	"encoding/json"
	"strings"
	"testing"
)

// catalogDoc is a catalog small enough to read whole: three entries in two
// categories, one of them a check.
func catalogDoc() string {
	return `{"version":1,"generated_from":"x","entries":[
	  {"id":"pool.no_host","kind":"problem","title":"A pool has no host","category":"capacity","severity":"error","detection":"runtime","detects":"d1","fix":"f1","verify":null,"docs_html":"h","docs_md":"m"},
	  {"id":"ci.no_timeout","kind":"check","title":"A job has no timeout","category":"reliability","severity":"warning","detection":"static","detects":"d2","fix":"f2","verify":"v2","area":"ci","docs_html":"h","docs_md":"m"},
	  {"id":"pool.minimum_overcharges","kind":"problem","title":"A minimum costs more than it saves","category":"capacity","severity":"info","detection":"runtime","detects":"d3","fix":"f3","verify":null,"docs_html":"h","docs_md":"m"}
	]}`
}

// The catalog is the one place every code and check is explained, and the docs
// tell an agent to read it before explaining a problem; an agent that reaches the
// fleet only over MCP had no way to. It is far too big to send whole, so without
// arguments it is an index, and one entry comes by its code.
func TestTheCatalogIsAnIndexWithoutArgumentsAndOneEntryByCode(t *testing.T) {
	api := &kennelAPI{body: catalogDoc()}
	out, err := kennelCall(t, kennelTool(t, "get_catalog"), api, `{}`)
	if err != nil {
		t.Fatal(err)
	}
	if api.got != "GET /catalog" {
		t.Errorf("asked %q", api.got)
	}
	var index struct {
		Version    int                 `json:"version"`
		Categories map[string][]string `json:"categories"`
	}
	if len(out) != 1 || json.Unmarshal([]byte(out[0].Text), &index) != nil {
		t.Fatalf("the index is not one block of the shape expected: %+v", out)
	}
	if index.Version != 1 || len(index.Categories["capacity"]) != 2 || index.Categories["reliability"][0] != "ci.no_timeout" {
		t.Errorf("index = %+v", index)
	}
	if strings.Contains(out[0].Text, "f1") {
		t.Error("the index carries an entry's text, so it is not an index")
	}

	out, err = kennelCall(t, kennelTool(t, "get_catalog"), api, `{"code":"ci.no_timeout"}`)
	if err != nil {
		t.Fatal(err)
	}
	if len(out) != 1 || !strings.Contains(out[0].Text, `"fix":"f2"`) || strings.Contains(out[0].Text, "pool.no_host") {
		t.Errorf("one entry = %+v", out)
	}
}

// A category narrows the index to its codes with their titles and severity, which
// is what an agent reads to choose which entry to open.
func TestTheCatalogListsACategoryWithTitles(t *testing.T) {
	api := &kennelAPI{body: catalogDoc()}
	out, err := kennelCall(t, kennelTool(t, "get_catalog"), api, `{"category":"capacity"}`)
	if err != nil {
		t.Fatal(err)
	}
	text := out[0].Text
	if !strings.Contains(text, "A minimum costs more than it saves") || !strings.Contains(text, `"severity":"error"`) || strings.Contains(text, "ci.no_timeout") || strings.Contains(text, "f1") {
		t.Errorf("category = %s", text)
	}
}

// A code nobody documented is answered with the code and where the index is,
// not with an empty document the model would read as "nothing is known".
func TestAnUnknownCatalogCodeIsSaidToBeUnknown(t *testing.T) {
	api := &kennelAPI{body: catalogDoc()}
	out, err := kennelCall(t, kennelTool(t, "get_catalog"), api, `{"code":"pool.made_up"}`)
	if err == nil || !strings.Contains(err.Error(), "pool.made_up") || out != nil {
		t.Errorf("out %+v err %v", out, err)
	}
	// A code that is nearly right (a letter short, a family it knows) is told the
	// codes of that family, so the next call is the right one and not a guess.
	if !strings.Contains(err.Error(), "pool.no_host") || !strings.Contains(err.Error(), "pool.minimum_overcharges") || strings.Contains(err.Error(), "ci.no_timeout") {
		t.Errorf("the family's codes are not offered: %v", err)
	}
	_, err = kennelCall(t, kennelTool(t, "get_catalog"), api, `{"code":"nothing.like_it"}`)
	if err == nil || !strings.Contains(err.Error(), "without arguments") {
		t.Errorf("a code of no known family is not sent to the index: %v", err)
	}
}

