type comparisonRunnerArm struct {
	SelectedJobs       *int                  `json:"selected_jobs"`
	MatchedJobs        *int                  `json:"matched_jobs"`
	RecordedGrants     *int                  `json:"recorded_grants"`
	RunnerObservations *int                  `json:"runner_observations"`
