	if strings.Contains(p, "@") || strings.ContainsAny(p, "\\?#%") || path.Clean(p) != p || path.Dir(p) != ".github/workflows" || !(strings.HasSuffix(p, ".yml") || strings.HasSuffix(p, ".yaml")) {
