func TestHostedLabelsInFindsVendorLabels(t *testing.T) {
	in := "jobs:\n  a:\n    runs-on: blacksmith-4vcpu-ubuntu-2404\n  b:\n    runs-on: ubuntu-latest\n  c:\n    runs-on: acme-bigbox\n"
