func checkoutFixture() (Source, Timing, HistoryReview, Policy) {
	s := Source{HeadSHA: strings.Repeat("a", 40), File: prrepair.File{Path: ".github/workflows/ci.yml", Mode: "100644", Content: "name: Test\non: push\njobs:\n  build:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@" + strings.Repeat("b", 40) + "\n        with:\n          fetch-depth: 0 # reviewed history scope\n      - run: npm test\n"}}
	duration := int64(4200)
	needs := false
	return s, Timing{EvidenceID: "checkout_fixture", HeadSHA: s.HeadSHA, SourceSHA256: hash(s.File.Content), RunID: "9223372036854775807", Attempt: 2, JobIndex: 0, StepIndex: 0, Outcome: "success", CheckoutMS: &duration}, HistoryReview{HeadSHA: s.HeadSHA, SourceSHA256: hash(s.File.Content), Scope: "repository_and_downstream_consumers", NeedsHistory: &needs}, Policy{SourceAllowed: true, WorkflowEditsAllowed: true}
}
func TestCheckoutPreviewPreservesUnrelatedBytesAndNeverClaimsVerifiedSavings(t *testing.T) {
	for _, ending := range []string{"\n", "\r\n"} {
		s, timing, history, policy := checkoutFixture()
		s.File.Content = strings.ReplaceAll(s.File.Content, "\n", ending)
		timing.SourceSHA256 = hash(s.File.Content)
		history.SourceSHA256 = timing.SourceSHA256
		p, err := PreviewCheckout(s, timing, history, policy)
		if err != nil {
			t.Fatal(err)
		}
		want := strings.Replace(s.File.Content, "fetch-depth: 0", "fetch-depth: 1", 1)
		if p.File.Content != want || p.File.Mode != "100644" || p.Line != 9 || p.Verification != "inconclusive" || p.RunID != timing.RunID || p.CheckoutMS != 4200 || p.AfterSHA256 != hash(want) || CheckCurrent(p, s, policy) != nil {
			t.Fatalf("incorrect preview: %+v", p)
		}
		p.File.Content += "# unrelated change\n"
		if CheckCurrent(p, s, policy) == nil {
			t.Fatal("tampered preview accepted")
		}
	}
}
func TestCheckoutPreviewRefusesUnknownOrStaleEvidenceAndPolicy(t *testing.T) {
	for _, mode := range []string{"source_policy", "edit_policy", "head", "source_digest", "unknown_timing", "failed_timing", "zero_timing", "unknown_history", "required_history", "history_head", "history_digest", "history_scope", "run_id", "attempt", "step", "path", "partial", "mode", "oversize", "already_shallow", "floating_action", "ref_override", "tags", "duplicate_preimage", "credentials"} {
		t.Run(mode, func(t *testing.T) {
			s, timing, history, policy := checkoutFixture()
			switch mode {
			case "source_policy":
				policy.SourceAllowed = false
			case "edit_policy":
				policy.WorkflowEditsAllowed = false
			case "head":
				timing.HeadSHA = strings.Repeat("c", 40)
			case "source_digest":
				timing.SourceSHA256 = strings.Repeat("c", 64)
			case "unknown_timing":
				timing.CheckoutMS = nil
			case "failed_timing":
				timing.Outcome = "failure"
			case "zero_timing":
				*timing.CheckoutMS = 0
			case "unknown_history":
				history.NeedsHistory = nil
			case "required_history":
				*history.NeedsHistory = true
			case "history_head":
				history.HeadSHA = strings.Repeat("c", 40)
			case "history_digest":
				history.SourceSHA256 = strings.Repeat("c", 64)
			case "history_scope":
				history.Scope = "root_file_only"
			case "run_id":
				timing.RunID = "01"
			case "attempt":
				timing.Attempt = 0
			case "step":
				timing.StepIndex = 1
			case "path":
				s.File.Path = ".github/workflows/../ci.yml"
			case "partial":
				s.File.Partial = true
			case "mode":
				s.File.Mode = "120000"
			case "oversize":
				s.File.Content += strings.Repeat("#", MaxCheckoutSourceBytes)
			case "already_shallow":
				s.File.Content = strings.Replace(s.File.Content, "fetch-depth: 0", "fetch-depth: 1", 1)
			case "floating_action":
				s.File.Content = strings.Replace(s.File.Content, strings.Repeat("b", 40), "main", 1)
			case "ref_override":
				s.File.Content = strings.Replace(s.File.Content, "          fetch-depth:", "          ref: main\n          fetch-depth:", 1)
			case "tags":
				s.File.Content = strings.Replace(s.File.Content, "          fetch-depth:", "          fetch-tags: true\n          fetch-depth:", 1)
			case "duplicate_preimage":
				job := s.File.Content[strings.Index(s.File.Content, "  build:"):]
				s.File.Content += strings.Replace(job, "  build:", "  other:", 1)
			case "credentials":
				s.File.Content += "# ghp_" + strings.Repeat("x", 30) + "\n"
			}
			if mode == "oversize" || mode == "already_shallow" || mode == "floating_action" || mode == "ref_override" || mode == "tags" || mode == "duplicate_preimage" || mode == "credentials" {
				timing.SourceSHA256 = hash(s.File.Content)
				history.SourceSHA256 = timing.SourceSHA256
			}
			if p, err := PreviewCheckout(s, timing, history, policy); err == nil || p.File.Content != "" {
				t.Fatal("unsupported preview emitted source")
			}
		})
	}
}
func TestCheckoutCurrentnessStopsWhenHeadSourceOrPolicyChanges(t *testing.T) {
	for _, mode := range []string{"head", "source", "policy", "path", "edit", "version"} {
		s, timing, history, policy := checkoutFixture()
		p, err := PreviewCheckout(s, timing, history, policy)
		if err != nil {
			t.Fatal(err)
		}
		switch mode {
		case "head":
			s.HeadSHA = strings.Repeat("c", 40)
		case "source":
			s.File.Content += "# advanced source\n"
		case "policy":
			policy.WorkflowEditsAllowed = false
		case "path":
			s.File.Path = ".github/workflows/other.yml"
		case "edit":
			p.Edit.After = "          fetch-depth: 2\n"
		case "version":
			p.Version = "future"
		}
		if CheckCurrent(p, s, policy) == nil {
			t.Fatalf("%s remained current", mode)
		}
	}
}

package optimisation

import (
	"go/ast"
	"go/parser"
	"go/token"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
)

func TestOptimisationComputesOnlyFromSuppliedSourceAndEvidence(t *testing.T) {
	allowed := map[string]bool{"crypto/sha256": true, "encoding/hex": true, "errors": true, "path": true, "sort": true, "strconv": true, "strings": true, "unicode/utf8": true, "github.com/eyupio/zoomies/internal/kennel/workflow": true, "github.com/eyupio/zoomies/internal/prrepair": true}
	sharding := map[string]bool{"FindPlaywrightTest": true, "ShardNames": true, "ShardChange": true, "ShardRefusal": true, "ErrShardNotFound": true, "ErrShardAmbiguous": true}
	files, err := filepath.Glob("*.go")
	if err != nil {
		t.Fatal(err)
	}
	for _, name := range files {
		if strings.HasSuffix(name, "_test.go") {
			continue
		}
		f, err := parser.ParseFile(token.NewFileSet(), name, nil, 0)
		if err != nil {
			t.Fatal(err)
		}
		for _, imp := range f.Imports {
			p, _ := strconv.Unquote(imp.Path.Value)
			if !allowed[p] || imp.Name != nil {
				t.Errorf("%s imports unsupported dependency %s", name, p)
			}
		}
		ast.Inspect(f, func(n ast.Node) bool {
			s, ok := n.(*ast.SelectorExpr)
			if !ok {
				return true
			}
			id, ok := s.X.(*ast.Ident)
			if !ok {
				return true
			}
			if id.Name != "workflow" && id.Name != "prrepair" {
				return true
			}
			// The sharding preview finds its step, names it and builds the exact
			// rewrite in the workflow package too, and reads the refusal it gives
			// so the operator is told what to change.
			// The workflow package supplies the exact line or insertion; the
			// optimisation package never reads source itself.
			workflowChange := id.Name == "workflow" && (s.Sel.Name == "CheckoutDepthChange" || s.Sel.Name == "FindSetupNode" || s.Sel.Name == "SetupNames" || s.Sel.Name == "SetupCacheChange" || s.Sel.Name == "FindFixedSleep" || s.Sel.Name == "ReadinessNames" || s.Sel.Name == "ReadinessChange" || sharding[s.Sel.Name])
			repairEdit := id.Name == "prrepair" && (s.Sel.Name == "File" || s.Sel.Name == "Edit" || s.Sel.Name == "ApplySuppliedEdits")
			if !workflowChange && !repairEdit {
				t.Errorf("%s crosses the supplied preview boundary through %s.%s", name, id.Name, s.Sel.Name)
			}
			return true
		})
	}
}

package optimisation

import (
	"errors"
	"sort"
	"strconv"
	"strings"

	"github.com/eyupio/zoomies/internal/kennel/workflow"
	"github.com/eyupio/zoomies/internal/prrepair"
)

// ErrReadinessUnsupported is the one refusal for a bounded readiness preview.
// It names the shape the change needs without guessing a condition or a shell.
var ErrReadinessUnsupported = errors.New("bounded readiness preview needs one fixed sleep step on an Ubuntu runner, an operator-supplied readiness command, repeated wait evidence and source/edit policy")

// ReadinessSource is the workflow file at a pinned head. The readiness command
// is supplied separately because it is a decision about the repository's
// service, not something this package may infer from a sleep.
type ReadinessSource struct {
	HeadSHA  string
	Workflow prrepair.File
}

// ReadinessEvidence is caller-supplied, not independently attested. The
// condition is the operator's command; the wait samples describe what the
// fixed sleep cost in the selected job's history.
type ReadinessEvidence struct {
	EvidenceID   string
	HeadSHA      string
	SourceSHA256 string
	Runs         int
	WaitMS       *int64
	Condition    string
}

// ReadinessPreview is a proposed replacement of one fixed sleep with a bounded
// poll of an operator-supplied condition. Verification is always inconclusive.
type ReadinessPreview struct {
	Version      string
	Kind         string
	State        string
	HeadSHA      string
	SourceSHA256 string
	AfterSHA256  string
	EvidenceID   string
	JobIndex     int
	StepIndex    int
	JobName      string
	StepName     string
	Line         int
	WaitSeconds  int
	Runs         int
	WaitMS       int64
	Condition    string
	Edit         prrepair.Edit
	File         prrepair.File
	Verification string
	Explanation  string
}

// PreviewReadiness computes the exact replacement. It never guesses a health
// command: the operator supplies the condition, and the original sleep becomes
// the bound. A condition that is not one line, or a source outside the root
// workflow, is refused rather than repaired.
func PreviewReadiness(source ReadinessSource, evidence ReadinessEvidence, policy Policy) (ReadinessPreview, error) {
	if !policy.SourceAllowed || !policy.WorkflowEditsAllowed || !commit(source.HeadSHA) || !cacheWorkflow(source.Workflow) {
		return ReadinessPreview{}, ErrReadinessUnsupported
	}
	sourceDigest := hash(source.Workflow.Content)
	condition := strings.TrimSpace(evidence.Condition)
	if condition == "" || len(condition) > 1024 || strings.ContainsAny(condition, "\r\n\x00") || evidence.HeadSHA != source.HeadSHA || evidence.SourceSHA256 != sourceDigest || evidence.EvidenceID == "" || len(evidence.EvidenceID) > 128 || strings.ContainsAny(evidence.EvidenceID, " \t\r\n\x00") || evidence.Runs < 2 || evidence.Runs > 100 || evidence.WaitMS == nil || *evidence.WaitMS <= 0 || *evidence.WaitMS > 7*24*60*60*1000 {
		return ReadinessPreview{}, ErrReadinessUnsupported
	}
	job, step, seconds, err := workflow.FindFixedSleep([]byte(source.Workflow.Content))
	if err != nil {
		return ReadinessPreview{}, ErrReadinessUnsupported
	}
	jobName, stepName, err := workflow.ReadinessNames([]byte(source.Workflow.Content), job, step)
	if err != nil {
		return ReadinessPreview{}, ErrReadinessUnsupported
	}
	loop := "until " + condition + "; do sleep 1; done"
	script := "timeout " + strconv.Itoa(seconds) + " sh -c " + shellQuote(loop)
	before, after, line, err := workflow.ReadinessChange([]byte(source.Workflow.Content), job, step, script)
	if err != nil {
		return ReadinessPreview{}, ErrReadinessUnsupported
	}
	edit := prrepair.Edit{Path: source.Workflow.Path, Before: before, After: after}
	files, err := prrepair.ApplySuppliedEdits([]prrepair.File{source.Workflow}, []prrepair.Edit{edit}, true)
	if err != nil {
		return ReadinessPreview{}, ErrReadinessUnsupported
	}
	return ReadinessPreview{
		Version: "readiness-preview-v1", Kind: "bounded_readiness_poll", State: "preview_ready",
		HeadSHA: source.HeadSHA, SourceSHA256: sourceDigest, AfterSHA256: hash(files[0].Content),
		EvidenceID: evidence.EvidenceID, JobIndex: job, StepIndex: step, JobName: jobName, StepName: stepName, Line: line,
		WaitSeconds: seconds, Runs: evidence.Runs, WaitMS: *evidence.WaitMS, Condition: condition, Edit: edit, File: files[0],
		Verification: "inconclusive",
		Explanation:  "Replace a fixed " + strconv.Itoa(seconds) + "s sleep in " + stepName + " with a poll of the command the operator supplied, bounded to the same " + strconv.Itoa(seconds) + "s. The wait step averaged " + setupSeconds(*evidence.WaitMS) + " over " + runCount(evidence.Runs) + ". The condition is not inferred, and the saving is unverified: the service may become ready later or fail the bound.",
	}, nil
}

// CheckReadinessCurrent is a local precondition, not publication authorisation.
func CheckReadinessCurrent(p ReadinessPreview, source ReadinessSource, evidence ReadinessEvidence, policy Policy) error {
	if p.Version != "readiness-preview-v1" || p.Kind != "bounded_readiness_poll" || p.State != "preview_ready" {
		return ErrReadinessUnsupported
	}
	current, err := PreviewReadiness(source, evidence, policy)
	if err != nil {
		return err
	}
	if current.HeadSHA != p.HeadSHA || current.SourceSHA256 != p.SourceSHA256 || current.AfterSHA256 != p.AfterSHA256 || current.EvidenceID != p.EvidenceID || current.JobIndex != p.JobIndex || current.StepIndex != p.StepIndex || current.JobName != p.JobName || current.StepName != p.StepName || current.Line != p.Line || current.WaitSeconds != p.WaitSeconds || current.Runs != p.Runs || current.WaitMS != p.WaitMS || current.Condition != p.Condition || current.Edit != p.Edit || current.File != p.File {
		return ErrReadinessUnsupported
	}
	return nil
}

// shellQuote wraps one string in single quotes for sh, escaping an embedded
// quote in the only way a single-quoted shell word allows.
func shellQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}

// ReadinessEvidenceFromSamples turns exact local wait samples into the evidence
// a readiness preview needs. The samples are sorted by job ID before the
// evidence ID is computed, so the same set gives the same ID whatever order the
// store returned it in. Two to one hundred samples are required.
func ReadinessEvidenceFromSamples(head, sourceSHA256 string, samples []SetupSample) (ReadinessEvidence, error) {
	if !commit(head) || len(sourceSHA256) != 64 || sourceSHA256 != strings.ToLower(sourceSHA256) || len(samples) < 2 || len(samples) > 100 {
		return ReadinessEvidence{}, ErrReadinessUnsupported
	}
	ordered := append([]SetupSample(nil), samples...)
	sort.Slice(ordered, func(i, j int) bool { return ordered[i].JobID < ordered[j].JobID })
	parts := make([]string, 0, len(ordered))
	var total int64
	for i, s := range ordered {
		if s.JobID == "" || len(s.JobID) > 128 || strings.ContainsAny(s.JobID, " \t\r\n\x00") || s.RunID == "" || s.RunID != strconv.FormatInt(mustDecimal(s.RunID), 10) || s.Attempt < 1 || s.StepNumber <= 0 || s.SetupMS <= 0 || i > 0 && ordered[i-1].JobID == s.JobID {
			return ReadinessEvidence{}, ErrReadinessUnsupported
		}
		total += s.SetupMS
		parts = append(parts, s.JobID+"/"+s.RunID+"/"+strconv.Itoa(s.Attempt)+"/"+strconv.Itoa(s.StepNumber)+"/"+strconv.FormatInt(s.SetupMS, 10))
	}
	mean := total / int64(len(ordered))
	if mean <= 0 || mean > 7*24*60*60*1000 {
		return ReadinessEvidence{}, ErrReadinessUnsupported
	}
	return ReadinessEvidence{
		EvidenceID: hash("readiness-v1:" + head + ":" + sourceSHA256 + ":" + strings.Join(parts, ",")),
		HeadSHA:    head, SourceSHA256: sourceSHA256, Runs: len(ordered), WaitMS: &mean,
	}, nil
}

