func TestPreviewReadinessReplacesOneFixedSleepWithABoundedPoll(t *testing.T) {
	source, evidence := readinessFixture()
	p, err := PreviewReadiness(source, evidence, Policy{SourceAllowed: true, WorkflowEditsAllowed: true})
	if err != nil {
