	if p.Version != "readiness-preview-v1" || p.Kind != "bounded_readiness_poll" || p.State != "preview_ready" || p.WaitSeconds != 30 || p.Runs != 4 || p.WaitMS != 31000 || p.Condition != evidence.Condition || p.Verification != "inconclusive" {
