	}
	if !strings.Contains(p.Edit.Before, "run: sleep 30") || !strings.Contains(p.Edit.After, "run: |") || !strings.Contains(p.Edit.After, "timeout 30 sh -c 'until curl -fsS http://127.0.0.1:8080/health; do sleep 1; done'") {
