// Every call has to send what the API actually expects; a parameter with the
// wrong name is a machine that is built with the wrong shape or not at all.
func TestEveryCallSendsTheParametersProxmoxExpects(t *testing.T) {
	f := newFakePVE(t, nil)
	c := f.client(t)
	ctx := context.Background()

	if _, err := c.CloneVM(ctx, "pve-1", 9000, CloneRequest{
		NewID: 143, Name: "zoomies-mach-abc", Full: true, Storage: "local-lvm", Target: "pve-1",
		Pool: "zoomies", Description: "Managed by Zoomies",
	}); err != nil {
		t.Fatalf("CloneVM: %v", err)
	}
	clone := f.request(http.MethodPost, v+"/nodes/pve-1/qemu/9000/clone")
	for key, want := range map[string]string{
		"newid": "143", "name": "zoomies-mach-abc", "full": "1", "storage": "local-lvm",
		"target": "pve-1", "pool": "zoomies", "description": "Managed by Zoomies",
	} {
		if got := formValue(clone, key); got != want {
			t.Errorf("clone %s = %q, want %q", key, got, want)
		}
	}

	if _, err := c.ConfigureVM(ctx, "pve-1", 143, map[string][]string{
		"cores": {"4"}, "memory": {"8192"}, "net0": {"virtio,bridge=vmbr0"}, "tags": {"zoomies;zoomies-abc"},
	}); err != nil {
		t.Fatalf("ConfigureVM: %v", err)
	}
	config := f.request(http.MethodPost, v+"/nodes/pve-1/qemu/143/config")
	if got := formValue(config, "net0"); got != "virtio,bridge=vmbr0" {
		t.Errorf("net0 = %q", got)
	}
	if got := formValue(config, "tags"); got != "zoomies;zoomies-abc" {
		t.Errorf("tags = %q", got)
	}

	if err := c.ResizeDisk(ctx, "pve-1", 143, "scsi0", "+40G"); err != nil {
		t.Fatalf("ResizeDisk: %v", err)
	}
	resize := f.request(http.MethodPut, v+"/nodes/pve-1/qemu/143/resize")
	if formValue(resize, "disk") != "scsi0" || formValue(resize, "size") != "+40G" {
		t.Errorf("resize sent disk=%q size=%q", formValue(resize, "disk"), formValue(resize, "size"))
	}

	if _, err := c.ShutdownVM(ctx, "pve-1", 143, 90*time.Second, true); err != nil {
		t.Fatalf("ShutdownVM: %v", err)
	}
	shutdown := f.request(http.MethodPost, v+"/nodes/pve-1/qemu/143/status/shutdown")
	if formValue(shutdown, "timeout") != "90" || formValue(shutdown, "forceStop") != "1" {
		t.Errorf("shutdown sent timeout=%q forceStop=%q", formValue(shutdown, "timeout"), formValue(shutdown, "forceStop"))
	}

	if _, err := c.DeleteVM(ctx, "pve-1", 143); err != nil {
		t.Fatalf("DeleteVM: %v", err)
	}
	del := f.request(http.MethodDelete, v+"/nodes/pve-1/qemu/143")
	// Without both of these a destroyed guest leaves backups, replication jobs
	// and unreferenced disks behind, still costing somebody money.
	if queryValue(del, "purge") != "1" || queryValue(del, "destroy-unreferenced-disks") != "1" {
		t.Errorf("delete sent %q", del.URL.RawQuery)
	}
}

// The bootstrap payload is argv, never a shell line: a payload that is never
// pasted into a shell has no quoting to get wrong.
func TestACommandForTheGuestIsSentAsArgvRatherThanAShellLine(t *testing.T) {
	f := newFakePVE(t, nil)
	c := f.client(t)
	ctx := context.Background()

	if err := c.AgentPing(ctx, "pve-1", 100); err != nil {
		t.Fatalf("AgentPing: %v", err)
	}
	if err := c.AgentFileWrite(ctx, "pve-1", 100, "/etc/zoomies/agent.env", []byte("ZOOMIES_JOIN_TOKEN=join_abc\n")); err != nil {
		t.Fatalf("AgentFileWrite: %v", err)
	}
	if got := f.vm(100).files["/etc/zoomies/agent.env"]; !strings.Contains(got, "join_abc") {
		t.Errorf("the guest did not receive the file: %q", got)
	}

	pid, err := c.AgentExec(ctx, "pve-1", 100, []string{"systemctl", "enable", "--now", "zoomies-agent"}, "")
	if err != nil {
		t.Fatalf("AgentExec: %v", err)
	}
	if pid != 4242 {
		t.Errorf("pid = %d, want 4242", pid)
	}
	exec := f.request(http.MethodPost, v+"/nodes/pve-1/qemu/100/agent/exec")
	if got := exec.PostForm["command"]; len(got) != 4 || got[0] != "systemctl" || got[3] != "zoomies-agent" {
		t.Errorf("command = %q, want one value per argument", got)
	}

	status, err := c.AgentExecStatus(ctx, "pve-1", 100, pid)
	if err != nil {
		t.Fatalf("AgentExecStatus: %v", err)
	}
	if !bool(status.Exited) || status.ExitCode != 0 {
		t.Errorf("exited=%v exitcode=%d, want a finished, successful command", status.Exited, status.ExitCode)
	}
}

// A guest agent that never answers is what a machine that booted but never came
// up looks like, and it has to read as a refusal rather than as success.
func TestAGuestAgentThatNeverAnswersIsAFailureAndNotASuccess(t *testing.T) {
	f := newFakePVE(t, nil)
	f.SetGuestAgentSilent()

	err := f.client(t).AgentPing(context.Background(), "pve-1", 100)
	if err == nil {
		t.Fatal("a silent guest agent was reported as answering")
	}
	if !strings.Contains(err.Error(), "guest agent is not running") {
		t.Errorf("the reason does not say what is wrong: %v", err)
	}
}

// Proxmox writes its complaint in the HTTP status line as often as in the body.
// A client that only read the body would throw away the only sentence it sent.
func TestProxmoxsMessageInTheStatusLineIsNotLost(t *testing.T) {
	const sentence = "storage 'local-lvm' does not exist"
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("listen: %v", err)
	}
	t.Cleanup(func() { _ = ln.Close() })
	go func() {
		conn, err := ln.Accept()
		if err != nil {
			return
		}
		defer conn.Close()
		buf := make([]byte, 4096)
		_, _ = conn.Read(buf)
		const body = `{"data":null}`
		fmt.Fprintf(conn, "HTTP/1.1 500 %s\r\nContent-Type: application/json\r\nContent-Length: %d\r\nConnection: close\r\n\r\n%s",
			sentence, len(body), body)
	}()

	// Loopback plain HTTP is the one case this client accepts, which is what
	// makes this test possible without a certificate.
	c, err := New(Options{Endpoint: "http://" + ln.Addr().String(), TokenID: tokenID, Secret: tokenSecret})
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	_, err = c.Version(context.Background())
	if err == nil {
		t.Fatal("a 500 was accepted as an answer")
	}
	if !strings.Contains(err.Error(), sentence) {
		t.Errorf("the message in the status line was lost: %v", err)
	}
}

// deadAddress is an address nothing is listening on, for the cases about a
// request that never left this machine.
func deadAddress(t *testing.T) string {
	t.Helper()
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("listen: %v", err)
	}
	addr := ln.Addr().String()
	if err := ln.Close(); err != nil {
		t.Fatalf("close: %v", err)
	}
	return addr
}

// The worst case this package has to survive: the virtual machine was made and
// the answer saying so was lost. It has to arrive as an unknown outcome, and
// the machine has to be findable afterwards -- because the only safe next move
// is to look for it, and a retry would leave one nobody is tracking running and
// billing.
func TestACloneWhoseAnswerWasLostIsUnknownRatherThanFailed(t *testing.T) {
	f := newFakePVE(t, nil)
	f.SetAmbiguousClone()
	c := f.client(t)

	_, err := c.CloneVM(context.Background(), "pve-1", 9000, CloneRequest{NewID: 143, Name: "zoomies-mach-abc"})
	if got := provider.KindOf(err); got != provider.FailureAmbiguous {
		t.Fatalf("kind = %q, want %q (%v)", got, provider.FailureAmbiguous, err)
	}
	if provider.Retryable(err) {
		t.Error("an unknown outcome was reported as retryable")
	}

	guests, err := c.ClusterVMs(context.Background())
	if err != nil {
		t.Fatalf("ClusterVMs: %v", err)
	}
	var found bool
	for _, g := range guests {
		if g.Name == "zoomies-mach-abc" {
			found = true
		}
	}
	if !found {
		t.Fatal("the machine the clone made is not findable by name, so an ambiguous create could never be reconciled")
	}
}

// A cluster with no room refuses in its own words. It is worth waiting for and
// is never fixed by asking again immediately, which is a different answer from
// "the call was refused".
func TestAStorageWithNoRoomIsAQuotaRefusal(t *testing.T) {
	f := newFakePVE(t, nil)
	f.SetQuotaExhausted()

	_, err := f.client(t).CloneVM(context.Background(), "pve-1", 9000, CloneRequest{NewID: 143})
	if got := provider.KindOf(err); got != provider.FailureQuota {
		t.Fatalf("kind = %q, want %q (%v)", got, provider.FailureQuota, err)
	}
	if !strings.Contains(err.Error(), "local-lvm") {
		t.Errorf("the refusal does not say which storage is full: %v", err)
	}
	if !provider.Retryable(err) {
		t.Error("a full storage is worth trying again once there is room")
	}
}

// A cluster on a home network has no address the controller can route to. The
// controller hands the client a dialer for the private connection instead, and
// the client has to use it for every socket -- and consult no proxy, which
// would take the connection straight back out of the tunnel -- while the
// endpoint's host stays the name the certificate is verified against.
func TestClientDialsThroughTheProvidedDialerAndUsesNoProxy(t *testing.T) {
	f := newFakePVE(t, nil)
	t.Setenv("HTTPS_PROXY", "http://127.0.0.1:1")
	var dialled []string
	c, err := New(Options{
		// example.com is what httptest's certificate is issued for, and it is
		// not where the fake listens: only the dialer can get there.
		Endpoint: "https://example.com:8006",
		TokenID:  tokenID, Secret: tokenSecret, CAPEM: f.caPEM(t),
		DialContext: func(ctx context.Context, network, address string) (net.Conn, error) {
			dialled = append(dialled, address)
			return (&net.Dialer{}).DialContext(ctx, network, f.Listener.Addr().String())
		},
	})
	if err != nil {
		t.Fatal(err)
	}
	if tr := c.http.Transport.(*http.Transport); tr.Proxy != nil {
		t.Fatal("a proxy could take the connection out of the private tunnel")
	}
	if _, err := c.Version(context.Background()); err != nil {
		t.Fatalf("Version through the dialer: %v", err)
	}
	if len(dialled) == 0 || dialled[0] != "example.com:8006" {
		t.Fatalf("the dialer was asked for %v, want the endpoint's host and port", dialled)
	}
}

// A controller on the Proxmox host itself is usually pointed at localhost, and
// Proxmox never issues a certificate for that name, so pasting the CA cannot
// fix it. The message has to say so, and has to name the escape hatch and what
// it costs, or the operator is left to guess at both.
func TestALoopbackEndpointExplainsWhyItCannotBeVerified(t *testing.T) {
	for _, endpoint := range []string{"https://localhost:8006", "https://127.0.0.1:8006", "https://[::1]:8006"} {
		t.Run(endpoint, func(t *testing.T) {
			for _, err := range []error{x509.UnknownAuthorityError{}, x509.HostnameError{Host: "localhost"}} {
				msg, remedy := unreachable(endpoint, err), unreachableRemedy(endpoint, err)
				if !strings.Contains(msg, "not for localhost") {
					t.Errorf("message does not explain the name: %q", msg)
				}
				for _, want := range []string{"real name or IP", "ca_pem", "insecure_skip_verify", "risk"} {
					if !strings.Contains(remedy, want) {
						t.Errorf("remedy does not mention %q: %q", want, remedy)
					}
				}
			}
		})
	}

	// A named node keeps the plain advice, and still offers the way out.
	remedy := unreachableRemedy("https://pve-1:8006", x509.UnknownAuthorityError{})
	if strings.Contains(remedy, "real name or IP") || !strings.Contains(remedy, "insecure_skip_verify") {
		t.Errorf("remedy for a named node is wrong: %q", remedy)
	}
}

// A failure of the private connection is not a fact about the endpoint: the
// cluster was never asked anything. The message must say what did fail, and
// the remedy must send the operator to the machine the gateway runs beside,
// not to an address no route reaches and not to a switch that hands the API
// token to whatever is on the path.
func TestAPrivateConnectionFailureReadsAsATunnelAndNotAnAddress(t *testing.T) {
	endpoint := "https://elitedesk-node1:8006"
	private := fmt.Errorf("opening the tunnel failed: %w", provider.ErrPrivateConnection)

	msg := unreachable(endpoint, private)
	if strings.Contains(msg, "could not be reached") {
		t.Errorf("the message reads as a dead address: %q", msg)
	}
	if !strings.Contains(msg, "private connection") || !strings.Contains(msg, "gateway") {
		t.Errorf("the message does not name the connection that failed: %q", msg)
	}

	remedy := unreachableRemedy(endpoint, private)
	for _, want := range []string{
		"clears on its own", "systemctl status 'zoomies-proxmox-*'", "journalctl -u 'zoomies-proxmox-*'",
		"outbound HTTPS", "127.0.0.1:8006", "reinstalled",
	} {
		if !strings.Contains(remedy, want) {
			t.Errorf("remedy does not mention %q: %q", want, remedy)
		}
	}
	for _, banned := range []string{"insecure_skip_verify", "check the endpoint"} {
		if strings.Contains(remedy, banned) {
			t.Errorf("remedy sends the operator to the wrong layer with %q: %q", banned, remedy)
		}
	}

	// Whatever the prose, the classification that decides what happens next
	// must stay the unreachable kind nothing is created or deleted upon.
	if provider.KindOf(private) != provider.FailureUnreachable {
		t.Errorf("KindOf = %q, want unreachable", provider.KindOf(private))
	}
	if !provider.Retryable(private) {
		t.Error("a private-connection failure stopped being retryable")
	}
}

package proxmox

import (
	"context"
	"fmt"

	"github.com/eyupio/zoomies/internal/config"
)

// SetupAnswers is what an installer knows about a provider before anybody has
// been asked anything: the node it is running on, the bridge and template it
// has just found or built.
type SetupAnswers struct {
	Node         string
	Bridge       string
	TemplateID   int
	TemplateNode string
}

// SetupCheck runs the check the Check button runs, as the token setup has just
// created, and returns only what stops the provider working.
//
// The point is to learn on the Proxmox host, with the exact reason and before
// anything is saved, that a token cannot do what the controller will ask of
// it. A provider that is saved first and fails its first check on the other
// side of a private connection sends an operator hunting for a cause that was
// plain on the host.
//
// The storage is the one answer an installer does not have, so it is chosen the
// way the template step chooses one: an active storage that takes disk images,
// the one with most room. Whether the operator later picks another is not this
// check's business; whether the token can see any is.
func SetupCheck(ctx context.Context, c *Client, a SetupAnswers) []config.Finding {
	storage := ""
	if storages, err := c.Storages(ctx, a.Node); err == nil {
		var best int64
		for _, s := range storages {
			if !s.Accepts("images") || !bool(s.Enabled) || !bool(s.Active) {
				continue
			}
			if storage == "" || int64(s.Avail) > best {
				storage, best = s.Storage, int64(s.Avail)
			}
		}
	}

	report := Preflight(ctx, c, Prereqs{
		Nodes: []string{a.Node}, Storage: storage, Bridge: a.Bridge,
		TemplateNode: a.TemplateNode, TemplateID: a.TemplateID,
		// The default runner block, which the form offers and the template
		// deliberately sits outside.
		VMIDMin: 9000, VMIDMax: 9099, GuestAgent: true,
	})

	var out []config.Finding
	for _, f := range config.Findings(report.Findings).Errors() {
		if storage == "" && f.Setting == SettingStorage {
			continue // Replaced below by the one finding that says what is true.
		}
		out = append(out, f)
	}
	if storage == "" && report.Reachable {
		out = append(out, config.Finding{
			Code: "proxmox.storage_missing", Severity: config.SeverityError, Setting: SettingStorage,
			Title:  fmt.Sprintf("the API token sees no storage on %s that can hold disk images", a.Node),
			Detail: "a clone has nowhere to put the machine's disk.",
			Fix: fmt.Sprintf("grant the token Datastore.Audit on /storage (pveum acl modify /storage --tokens '%s' --roles <role with Datastore.Audit>), "+
				"and make sure a storage on this node is enabled for disk images.", c.TokenID()),
		})
	}
	return out
}

package proxmox

import (
	"fmt"
	"strconv"
	"strings"
	"time"
)

// UPID is Proxmox's identifier for one asynchronous task.
//
// It is the durable operation handle this provider returns from every call that
// starts work: a clone, a start, a shutdown, a delete. Everything needed to ask
// about the task later is inside the string, the node included, so a controller
// that restarts holding nothing but the stored handle can still find out what
// happened rather than doing the work again.
//
// The wire form is eight colon-separated fields and a trailing colon:
//
//	UPID:pve-1:00051234:0089ABCD:65F0A1B2:qmclone:143:zoomies@pve!fleet:
//	     node  pid      pstart   start    type    id  user
//
// pstart is eight or nine hex digits -- nine on a node that has been up long
// enough for the kernel's boot-relative counter to overflow eight -- which is
// the detail a parser written from one example gets wrong, and gets wrong only
// on the machines that have been running longest.
type UPID struct {
	// Raw is the string exactly as Proxmox wrote it. It is what is stored and
	// what is sent back, because a handle rewritten from its parts is a handle
	// that can differ from the one the task actually has.
	Raw       string
	Node      string
	PID       uint64
	PStart    uint64
	StartTime time.Time
	// Type is the worker kind: "qmclone", "qmstart", "qmshutdown", "qmdestroy".
	Type string
	// ID is what the task is about -- a VMID for a guest task -- and is empty
	// for tasks that are about nothing in particular.
	ID   string
	User string
}

// String returns the handle as Proxmox wrote it.
func (u UPID) String() string { return u.Raw }

// Zero reports whether this is the absent handle.
func (u UPID) Zero() bool { return u.Raw == "" }

// ParseUPID reads a task handle.
//
// It validates the shape -- the prefix, the field count, the trailing colon,
// and that the three numeric fields are hexadecimal -- and deliberately does
// not validate the rest. The worker types are Proxmox's to add to, and a
// release that invents one must not make a task we are already waiting on
// unreadable.
//
// A caller that only wants the node should not depend on this succeeding: the
// node a machine's resource lives on is recorded on its own row, and that is
// the answer to fall back on. Refusing to poll a task because its handle looked
// unfamiliar would strand a real virtual machine, which is the one outcome
// nothing here may cause.
func ParseUPID(s string) (UPID, error) {
	const prefix = "UPID:"
	if !strings.HasPrefix(s, prefix) {
		return UPID{}, fmt.Errorf("proxmox: %q is not a task handle; one starts with %q", elide(s), prefix)
	}
	if !strings.HasSuffix(s, ":") {
		return UPID{}, fmt.Errorf("proxmox: task handle %q is cut short; one ends with a colon", elide(s))
	}
	// The trailing colon closes the last field rather than opening another, so
	// it is dropped before splitting; eight fields remain, the first of which
	// is the "UPID" marker itself.
	parts := strings.Split(strings.TrimSuffix(s, ":"), ":")
	if len(parts) != 8 {
		return UPID{}, fmt.Errorf("proxmox: task handle %q has %d fields, want 8", elide(s), len(parts))
	}

	u := UPID{Raw: s, Node: parts[1], Type: parts[5], ID: parts[6], User: parts[7]}
	if u.Node == "" {
		return UPID{}, fmt.Errorf("proxmox: task handle %q names no node, so there is nowhere to ask about it", elide(s))
	}
	var err error
	if u.PID, err = hexField(s, "process id", parts[2]); err != nil {
		return UPID{}, err
	}
	if u.PStart, err = hexField(s, "process start", parts[3]); err != nil {
		return UPID{}, err
	}
	started, err := hexField(s, "start time", parts[4])
	if err != nil {
		return UPID{}, err
	}
	u.StartTime = time.Unix(int64(started), 0).UTC()
	return u, nil
}

func hexField(upid, name, text string) (uint64, error) {
	n, err := strconv.ParseUint(text, 16, 64)
	if err != nil {
		return 0, fmt.Errorf("proxmox: task handle %q has %s %q, which is not hexadecimal", elide(upid), name, text)
	}
	return n, nil
}

// elide keeps a malformed handle out of a log line at full length. Whatever
// produced it is not necessarily Proxmox, and an error message is not the place
// to reprint an arbitrary string somebody else chose.
func elide(s string) string {
	const max = 80
	if len(s) <= max {
		return s
	}
	return s[:max] + "..."
}

package proxmox

import (
	"strings"
	"testing"
	"time"
)

// The handle is how a controller that restarted finds out what happened to work
// it started, so the cases that matter are the ones that would make a real task
// unreadable rather than the ones that look untidy.
func TestATaskHandleIsReadWithoutLosingTheTaskItNames(t *testing.T) {
	for _, tc := range []struct {
		name string
		raw  string
		want UPID
	}{
		{
			name: "a clone",
			raw:  "UPID:pve-1:00051234:0089ABCD:65F0A1B2:qmclone:143:zoomies@pve!fleet:",
			want: UPID{
				Node: "pve-1", PID: 0x51234, PStart: 0x89ABCD,
				StartTime: time.Unix(0x65F0A1B2, 0).UTC(),
				Type:      "qmclone", ID: "143", User: "zoomies@pve!fleet",
			},
		},
		{
			// Proxmox writes eight or nine hex digits here: nine once the node
			// has been up long enough for the counter to need them. A parser
			// written against one example fails on exactly the machines that
			// have been running longest, which is the worst possible set.
			name: "a node that has been up a long time",
			raw:  "UPID:pve-1:00051234:1089ABCDE:65F0A1B2:qmstart:143:root@pam:",
			want: UPID{
				Node: "pve-1", PID: 0x51234, PStart: 0x1089ABCDE,
				StartTime: time.Unix(0x65F0A1B2, 0).UTC(),
				Type:      "qmstart", ID: "143", User: "root@pam",
			},
		},
		{
			// A task about nothing in particular leaves the field empty rather
			// than omitting it, so the field count is still eight.
			name: "a task about nothing in particular",
			raw:  "UPID:pve-1:00051234:0089ABCD:65F0A1B2:srvreload::root@pam:",
			want: UPID{
				Node: "pve-1", PID: 0x51234, PStart: 0x89ABCD,
				StartTime: time.Unix(0x65F0A1B2, 0).UTC(),
				Type:      "srvreload", ID: "", User: "root@pam",
			},
		},
		{
			name: "a hyphenated node name",
			raw:  "UPID:pve-node-02:0000ffff:00000001:65F0A1B2:qmdestroy:9001:zoomies@pve:",
			want: UPID{
				Node: "pve-node-02", PID: 0xffff, PStart: 1,
				StartTime: time.Unix(0x65F0A1B2, 0).UTC(),
				Type:      "qmdestroy", ID: "9001", User: "zoomies@pve",
			},
		},
		{
			// Nothing here knows the full list of worker types, and a Proxmox
			// release that adds one must not make a task we are waiting on
			// unreadable.
			name: "a worker type this build has never heard of",
			raw:  "UPID:pve-1:00051234:0089ABCD:65F0A1B2:somethingnew:143:root@pam:",
			want: UPID{
				Node: "pve-1", PID: 0x51234, PStart: 0x89ABCD,
				StartTime: time.Unix(0x65F0A1B2, 0).UTC(),
				Type:      "somethingnew", ID: "143", User: "root@pam",
			},
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			got, err := ParseUPID(tc.raw)
			if err != nil {
				t.Fatalf("ParseUPID(%q): %v", tc.raw, err)
			}
			tc.want.Raw = tc.raw
			if got != tc.want {
				t.Errorf("ParseUPID(%q)\n got %+v\nwant %+v", tc.raw, got, tc.want)
			}
			// The handle is sent back to Proxmox exactly as it arrived: one
			// rebuilt from its parts can differ from the one the task has.
			if got.String() != tc.raw {
				t.Errorf("String() = %q, want the handle unchanged", got.String())
			}
		})
	}
}

// A malformed handle is refused with a message that says which part of it is
// wrong, because the thing that produced it is not necessarily Proxmox.
func TestAHandleThatIsNotATaskIsRefusedAndSaysWhy(t *testing.T) {
	for _, tc := range []struct {
		name  string
		raw   string
		wants string
	}{
		{"empty", "", "starts with"},
		{"another identifier entirely", "mach_k3f9qz2mx7ab", "starts with"},
		{"cut short", "UPID:pve-1:00051234:0089ABCD:65F0A1B2:qmclone:143:root@pam", "cut short"},
		{"too few fields", "UPID:pve-1:00051234:qmclone:", "fields"},
		{"too many fields", "UPID:pve-1:00051234:0089ABCD:65F0A1B2:qmclone:143:root@pam:extra:", "fields"},
		{"no node", "UPID::00051234:0089ABCD:65F0A1B2:qmclone:143:root@pam:", "names no node"},
		{"a process id that is not a number", "UPID:pve-1:notahexnum:0089ABCD:65F0A1B2:qmclone:143:root@pam:", "hexadecimal"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			_, err := ParseUPID(tc.raw)
			if err == nil {
				t.Fatalf("ParseUPID(%q) was accepted", tc.raw)
			}
			if !strings.Contains(err.Error(), tc.wants) {
				t.Errorf("error was %q, want it to mention %q", err, tc.wants)
			}
		})
	}
}

// An arbitrary string is not reprinted at full length into a log line or an
// error an operator reads.
func TestARefusalDoesNotReprintAWholeUnreasonableString(t *testing.T) {
	_, err := ParseUPID(strings.Repeat("x", 4096))
	if err == nil {
		t.Fatal("4 KiB of nonsense was accepted as a task handle")
	}
	if len(err.Error()) > 200 {
		t.Errorf("the refusal was %d bytes long; it quotes its input without limit", len(err.Error()))
	}
}

// The absent handle. A machine that has no operation in flight carries an empty
// one, and every caller asks this rather than comparing to "" -- so that a
// synchronous provider returning no handle and a machine between operations
// answer the same way.
func TestTheAbsentHandleIsTellableFromARealOne(t *testing.T) {
	var none UPID
	if !none.Zero() {
		t.Error("the zero handle does not report itself as absent")
	}
	got, err := ParseUPID("UPID:pve-1:00051234:0089ABCD:65F0A1B2:qmclone:143:root@pam:")
	if err != nil {
		t.Fatalf("ParseUPID: %v", err)
	}
	if got.Zero() {
		t.Error("a real task handle reports itself as absent")
	}
}

package provider

import (
	"context"
	"fmt"
	"slices"

	"github.com/eyupio/zoomies/internal/store"
)

// Registry holds the provider factories a build supports, keyed by kind, the
// way backend.Registry holds the backends an agent has. One registry is built
// at startup and a provider is built from it per configuration row.
type Registry struct {
	factories map[store.ProviderKind]Factory
}

// NewRegistry builds a registry, refusing a factory this build cannot work
// with rather than discovering it during the first create.
//
// It refuses two things. A kind that is not one the store knows, because a row
// with that kind could never be written and a factory for it is dead code with
// a typo in it. And a contract range that does not contain ContractVersion: the
// message names both numbers and says which side to upgrade, because "version
// mismatch" without the numbers sends an operator to the release notes of the
// wrong half.
//
// It cannot check here that a factory's declared capabilities match the
// provider it builds -- that needs an instance, and building one needs a
// credential and a context. Registry.New makes that check at the moment the
// instance exists, which is the earliest it can be made and still before the
// reconciler has called anything.
func NewRegistry(fs ...Factory) (*Registry, error) {
	r := &Registry{factories: make(map[store.ProviderKind]Factory, len(fs))}
	for _, f := range fs {
		if f == nil {
			continue
		}
		kind := f.Kind()
		if !kind.Valid() {
			return nil, fmt.Errorf("provider: %q is not a provider kind this build knows", kind)
		}
		if err := checkContract(kind, f.Describe()); err != nil {
			return nil, err
		}
		if _, dup := r.factories[kind]; dup {
			return nil, fmt.Errorf("provider: two factories are registered for %q; one of them is the wrong kind", kind)
		}
		r.factories[kind] = f
	}
	return r, nil
}

// Get returns the factory for a kind, or ErrUnsupported when this build has
// none. The message names the kind, because the row that asked for it is the
// thing an operator has to go and change.
func (r *Registry) Get(k store.ProviderKind) (Factory, error) {
	f, ok := r.factories[k]
	if !ok {
		return nil, fmt.Errorf("%w: this build has no %q provider", ErrUnsupported, k)
	}
	return f, nil
}

// Kinds returns the registered kinds, sorted, so that a list rendered to an
// operator does not reshuffle itself between requests.
func (r *Registry) Kinds() []store.ProviderKind {
	out := make([]store.ProviderKind, 0, len(r.factories))
	for k := range r.factories {
		out = append(out, k)
	}
	slices.Sort(out)
	return out
}

// New builds the provider for one configuration row and checks that what it
// says about itself is true before handing it to anyone.
//
// The checks are here rather than in the reconciler because a capability that
// lies is a programming error in a provider, and the honest moment to catch one
// is when the provider is built: a reconciler that discovered it would discover
// it mid-create, on a machine somebody is paying for.
func (r *Registry) New(ctx context.Context, kind store.ProviderKind, cfg Config) (Provider, error) {
	f, err := r.Get(kind)
	if err != nil {
		return nil, err
	}
	p, err := f.New(ctx, cfg)
	if err != nil {
		return nil, err
	}
	if p == nil {
		return nil, fmt.Errorf("provider: the %q factory returned no provider and no error", kind)
	}
	if p.Kind() != kind {
		return nil, fmt.Errorf("provider: the %q factory built a %q provider", kind, p.Kind())
	}
	if err := checkContract(kind, p.Capabilities()); err != nil {
		return nil, err
	}
	if err := CheckCapabilities(p); err != nil {
		return nil, err
	}
	if err := checkDescription(f, p); err != nil {
		return nil, err
	}
	return p, nil
}

// CheckCapabilities reports whether a provider's declared capabilities agree
// with its type.
//
// Each optional capability is a separate interface found by type assertion, so
// the flag and the method set can disagree, and both directions are bugs worth
// naming. A flag that says yes where the type says no has the reconciler call a
// method that is not there; a flag that says no where the type says yes loses a
// capability silently, and the machine an operator expected to be stopped is
// deleted and bought again instead.
//
// It is exported because the conformance suite runs it against every provider
// and a provider's own tests may want it directly.
func CheckCapabilities(p Provider) error {
	caps := p.Capabilities()
	_, power := p.(PowerController)
	if caps.CanStartStop != power {
		return fmt.Errorf("provider: %s says CanStartStop=%t but %s PowerController; make the two agree",
			p.Kind(), caps.CanStartStop, implements(power))
	}
	_, discover := p.(Discoverer)
	if caps.CanDiscover != discover {
		return fmt.Errorf("provider: %s says CanDiscover=%t but %s Discoverer; make the two agree",
			p.Kind(), caps.CanDiscover, implements(discover))
	}
	_, boot := p.(Bootstrapper)
	if wantBoot := caps.Bootstrap == BootstrapGuestAgent; wantBoot != boot {
		return fmt.Errorf("provider: %s declares bootstrap mode %q but %s Bootstrapper; a provider that pushes the payload itself implements it, and one that does not says so",
			p.Kind(), caps.Bootstrap, implements(boot))
	}
	return nil
}

func implements(ok bool) string {
	if ok {
		return "implements"
	}
	return "does not implement"
}

// checkDescription holds a factory's description and its instances together. A
// page that lists what a kind can do is rendered from Describe() without
// building anything, so a description that disagrees with the provider is a
// promise made to an operator that the fleet then breaks.
func checkDescription(f Factory, p Provider) error {
	d, c := f.Describe(), p.Capabilities()
	switch {
	case d.CanStartStop != c.CanStartStop:
		return fmt.Errorf("provider: the %s factory describes CanStartStop=%t and builds %t", p.Kind(), d.CanStartStop, c.CanStartStop)
	case d.CanDiscover != c.CanDiscover:
		return fmt.Errorf("provider: the %s factory describes CanDiscover=%t and builds %t", p.Kind(), d.CanDiscover, c.CanDiscover)
	case d.Bootstrap != c.Bootstrap:
		return fmt.Errorf("provider: the %s factory describes bootstrap mode %q and builds %q", p.Kind(), d.Bootstrap, c.Bootstrap)
	}
	return nil
}

// checkContract is the version handshake, in one place so that the factory and
// the instance are held to the same range.
func checkContract(kind store.ProviderKind, caps Capabilities) error {
	if caps.MinContract > caps.MaxContract {
		return fmt.Errorf("%w: the %s provider declares contract range %d..%d, which contains nothing",
			ErrUnsupported, kind, caps.MinContract, caps.MaxContract)
	}
	if ContractVersion < caps.MinContract {
		return fmt.Errorf("%w: the %s provider speaks contract %d..%d and this build speaks %d; upgrade Zoomies",
			ErrUnsupported, kind, caps.MinContract, caps.MaxContract, ContractVersion)
	}
	if ContractVersion > caps.MaxContract {
		return fmt.Errorf("%w: the %s provider speaks contract %d..%d and this build speaks %d; upgrade the provider",
			ErrUnsupported, kind, caps.MinContract, caps.MaxContract, ContractVersion)
	}
	return nil
}

// Package proxmoxsetup prepares a connection on the Proxmox host itself. It
// owns a separate API principal, binary, service and state from any runner agent.
package proxmoxsetup

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"crypto/x509"
	"encoding/hex"
	"encoding/json"
	"encoding/pem"
	"errors"
	"fmt"
	"net"
	"net/url"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"

	"github.com/tailscale/tailcat"
)

// LocalNetworkPath is where Proxmox keeps permissions for the node's own
// bridges. A token needs SDN.Use there to see a bridge and to attach a machine
// to it, which is a different thing from being able to read the node: root sees
// vmbr0 where a token without it is shown no bridges at all.
const LocalNetworkPath = "/sdn/zones/localnetwork"

const ProviderPrivileges = "Sys.Audit SDN.Use VM.Clone VM.Allocate VM.Audit VM.Config.Disk VM.Config.CPU VM.Config.Memory VM.Config.Network VM.Config.Options VM.PowerMgmt VM.GuestAgent.Unrestricted Datastore.Audit Datastore.AllocateSpace"

var bridgeName = regexp.MustCompile(`^[A-Za-z0-9._-]{1,32}$`)

type Template struct {
	VMID int    `json:"vmid"`
	Name string `json:"name"`
	Node string `json:"node"`
	// Agent is the release this setup found the template prepared from, or the
	// one it has just prepared it from. Empty on a template this setup did not
	// make, and on one prepared by a release that did not record what it was
	// carrying.
	//
	// It is read on the Proxmox host and printed there, and never sent to the
	// controller: the controller is told what a machine runs by the machine,
	// and a fact about an image is not one to keep a second copy of.
	Agent string `json:"-"`
}

type Connection struct {
	Templates      []Template `json:"templates,omitempty"`
	Name           string     `json:"name"`
	Endpoint       string     `json:"endpoint"`
	Credential     string     `json:"credential"`
	CAPEM          string     `json:"ca_pem"`
	TailcatAddress string     `json:"tailcat_address"`
	// Bridge is the node's own active bridge, so a provider made by this setup
	// is saved with one that exists rather than the vmbr0 a form assumes.
	Bridge string `json:"bridge,omitempty"`
}

func (c Connection) Validate() error {
	u, err := url.Parse(c.Endpoint)
	if err != nil || u.Scheme != "https" || u.Hostname() == "" || u.User != nil || u.RawQuery != "" || u.Fragment != "" || u.Path != "" {
		return errors.New("proxmox setup: the Proxmox connection needs an HTTPS API address")
	}
	if c.Name == "" || len(c.Name) > 128 || c.Credential == "" {
		return errors.New("proxmox setup: the Proxmox host did not supply its name and API credential")
	}
	for _, template := range c.Templates {
		if template.VMID < 100 || template.VMID > 999999999 || template.Node == "" || len(template.Node) > 256 || len(template.Name) > 256 {
			return errors.New("proxmox setup: invalid template inventory")
		}
	}
	if c.Bridge != "" && !bridgeName.MatchString(c.Bridge) {
		return errors.New("proxmox setup: the Proxmox host supplied an invalid network bridge name")
	}
	roots := x509.NewCertPool()
	if !roots.AppendCertsFromPEM([]byte(c.CAPEM)) {
		return errors.New("proxmox setup: the Proxmox host did not supply its trusted certificate")
	}
	if _, err := tailcat.ParseAddr(tailcat.Addr(c.TailcatAddress)); err != nil {
		return errors.New("proxmox setup: the Proxmox host did not supply a complete Tailcat address")
	}
	return nil
}

// InstanceKey keeps repeated onboarding for one controller on the same service
// and credential, without sharing the runner agent's state or executable.
func InstanceKey(controller string) string {
	identity := strings.TrimRight(controller, "/")
	if address, ok := strings.CutPrefix(identity, "tailcat://"); ok {
		if info, err := tailcat.ParseAddr(tailcat.Addr(address)); err == nil {
			// Relay changes must not install a second service for the same controller.
			identity = "tailcat:" + info.ServerPublic.String()
		}
	}
	sum := sha256.Sum256([]byte(identity))
	return hex.EncodeToString(sum[:6])
}

type Host struct {
	ReadFile  func(string) ([]byte, error)
	WriteFile func(string, []byte, os.FileMode) error
	Run       func(context.Context, string, ...string) ([]byte, error)
}

// Prepare deliberately receives all host I/O so tests never tune the test host
// or invoke its Proxmox commands. The caller creates a private state directory.
func Prepare(ctx context.Context, h Host, dir, key string) (*Connection, error) {
	ca, err := h.ReadFile("/etc/pve/pve-root-ca.pem")
	if err != nil {
		return nil, errors.New("proxmox setup: run this command as root on the Proxmox host; its cluster CA could not be read")
	}
	leaf, err := h.ReadFile("/etc/pve/local/pveproxy-ssl.pem")
	if errors.Is(err, os.ErrNotExist) {
		leaf, err = h.ReadFile("/etc/pve/local/pve-ssl.pem")
	}
	if err != nil {
		return nil, errors.New("proxmox setup: the Proxmox API certificate could not be read")
	}
	block, _ := pem.Decode(leaf)
	if block == nil {
		return nil, errors.New("proxmox setup: the Proxmox API certificate is not PEM")
	}
	cert, err := x509.ParseCertificate(block.Bytes)
	if err != nil {
		return nil, errors.New("proxmox setup: the Proxmox API certificate could not be parsed")
	}
	nameBytes, err := h.ReadFile("/etc/hostname")
	if err != nil {
		return nil, err
	}
	name := strings.Split(strings.TrimSpace(string(nameBytes)), ".")[0]
	if name == "" {
		return nil, errors.New("proxmox setup: the Proxmox host name is empty")
	}
	host := endpointHost(cert, name)
	if host == "" {
		return nil, errors.New("proxmox setup: the Proxmox API certificate needs a DNS name or IP subject alternative name that is not localhost; " +
			"give the node a certificate for its real name or address, then rerun setup")
	}
	c := &Connection{Name: "proxmox-" + name, Endpoint: "https://" + net.JoinHostPort(host, "8006"), CAPEM: string(ca)}
	// Prefer the cluster CA across certificate renewal. A custom certificate is
	// trusted from the root-owned local file when that CA does not sign it.
	roots := x509.NewCertPool()
	roots.AppendCertsFromPEM(ca)
	if _, err := cert.Verify(x509.VerifyOptions{Roots: roots, DNSName: host}); err != nil {
		c.CAPEM += "\n" + string(leaf)
	}
	tokenPath := filepath.Join(dir, "credential")
	if raw, err := h.ReadFile(tokenPath); err == nil {
		c.Credential = strings.TrimSpace(string(raw))
		if c.Credential == "" {
			return nil, errors.New("proxmox setup: the saved Proxmox credential is empty; restore it before retrying setup")
		}
		return c, nil
	} else if !errors.Is(err, os.ErrNotExist) {
		return nil, err
	}
	user, role := "zoomies-"+key+"@pve", "Zoomies-"+key
	// Recover partial setup with existing dedicated objects. Failures are only
	// ignored when the corresponding object is confirmed to exist.
	ensure := func(kind, id string, args ...string) error {
		if _, err := h.Run(ctx, "pveum", append([]string{kind, "add", id}, args...)...); err == nil {
			return nil
		}
		raw, err := h.Run(ctx, "pveum", kind, "list", "--output-format", "json")
		if err != nil {
			return fmt.Errorf("proxmox setup: cannot create the dedicated Proxmox %s", kind)
		}
		var rows []map[string]any
		if json.Unmarshal(raw, &rows) != nil {
			return fmt.Errorf("proxmox setup: cannot inspect the dedicated Proxmox %s", kind)
		}
		idField := "userid"
		if kind == "role" {
			idField = "roleid"
		}
		for _, row := range rows {
			if row[idField] == id {
				return nil
			}
		}
		return fmt.Errorf("proxmox setup: cannot create the dedicated Proxmox %s", kind)
	}
	if err := ensure("user", user); err != nil {
		return nil, err
	}
	privs := ProviderPrivileges
	if err := ensure("role", role, "--privs", privs); err != nil {
		return nil, err
	}
	// Proxmox users are cluster-wide, while gateway state lives on one node.
	// A second node must get its own token rather than rotate the first node's.
	tokenName := "provider-" + InstanceKey(name)
	tokenID := user + "!" + tokenName
	for _, path := range []string{"/vms", "/storage", "/nodes"} {
		if _, err := h.Run(ctx, "pveum", "acl", "modify", path, "--users", user, "--roles", role); err != nil {
			return nil, errors.New("proxmox setup: cannot grant the dedicated Proxmox user its provider permissions")
		}
	}
	raw, err := h.Run(ctx, "pveum", "user", "token", "add", user, tokenName, "--privsep", "1", "--output-format", "json")
	if err != nil {
		// A crashed first attempt may have created a token whose secret was
		// never saved. Create another token; never revoke a possibly live one.
		suffix := make([]byte, 8)
		if _, err := rand.Read(suffix); err != nil {
			return nil, err
		}
		tokenName += "-" + hex.EncodeToString(suffix)
		tokenID = user + "!" + tokenName
		raw, err = h.Run(ctx, "pveum", "user", "token", "add", user, tokenName, "--privsep", "1", "--output-format", "json")
		if err != nil {
			return nil, errors.New("proxmox setup: cannot create the dedicated Proxmox token; check Proxmox permissions and retry")
		}
	}
	var token struct {
		Value string `json:"value"`
	}
	if json.Unmarshal(raw, &token) != nil || token.Value == "" {
		return nil, errors.New("proxmox setup: proxmox did not return the new API token")
	}
	c.Credential = tokenID + "=" + token.Value
	if err := h.WriteFile(tokenPath, []byte(c.Credential), 0600); err != nil {
		return nil, err
	}
	if err := GrantToken(ctx, h, tokenID, role); err != nil {
		return nil, err
	}
	return c, nil
}

// GrantToken gives the token, and the user it belongs to, the role on every
// path the provider works under. Both halves matter: the token is created with
// privilege separation on, so what it may do is the intersection of its own
// grants and its user's, and a path granted to one of them alone is granted to
// neither. It runs on every setup, so a role or path a newer release needs
// reaches a connection made by an older one.
func GrantToken(ctx context.Context, h Host, tokenID, role string) error {
	user, _, _ := strings.Cut(tokenID, "!")
	for _, path := range []string{"/vms", "/storage", "/nodes"} {
		if _, err := h.Run(ctx, "pveum", "acl", "modify", path, "--users", user, "--roles", role); err != nil {
			return errors.New("proxmox setup: cannot grant the dedicated Proxmox user its provider permissions")
		}
		if _, err := h.Run(ctx, "pveum", "acl", "modify", path, "--tokens", tokenID, "--roles", role); err != nil {
			return errors.New("proxmox setup: cannot grant the dedicated Proxmox token its provider permissions")
		}
	}
	// Best effort: a Proxmox without the local network zone has no such path and
	// needs no grant on it. Whether it was needed is what the check after says.
	_, _ = h.Run(ctx, "pveum", "acl", "modify", LocalNetworkPath, "--users", user, "--roles", role)
	_, _ = h.Run(ctx, "pveum", "acl", "modify", LocalNetworkPath, "--tokens", tokenID, "--roles", role)
	return nil
}

// Command installs only a private copy of the matching binary; the general
// installer may replace an agent executable or re-enrol a running host. The
// binary is held to the release's checksums, and those to the release signing
// key, before anything runs as root.
func Command(controller, id, token, tag string) string {
	quote := func(s string) string { return "'" + strings.ReplaceAll(s, "'", "'\\''") + "'" }
	dir := "/var/lib/zoomies-proxmox/" + InstanceKey(controller)
	return "if [ \"$(id -u)\" -eq 0 ]; then zoomies_proxmox_sudo=''; else zoomies_proxmox_sudo='sudo'; fi\n" +
		"$zoomies_proxmox_sudo bash <<'ZOOMIES_PROXMOX_SETUP'\nset -eu\numask 077\n" +
		"die() { printf 'zoomies: %s\\n' \"$*\" >&2; exit 1; }\nsay() { printf 'zoomies: %s\\n' \"$*\" >&2; }\nwarn() { printf 'zoomies: warning: %s\\n' \"$*\" >&2; }\n" +
		releaseSignatureCode +
		"dir=" + quote(dir) + "\nmkdir -p \"$dir\"\n" +
		"if [ -f \"$dir/completed-" + InstanceKey(id+token) + "\" ] && [ -x \"$dir/zoomies\" ]; then\n  \"$dir/zoomies\" providers connect-proxmox --controller " + quote(controller) + " --setup-id " + quote(id) + " --token " + quote(token) + "\n  exit 0\nfi\n" +
		"case $(uname -m) in x86_64) arch=amd64;; aarch64|arm64) arch=arm64;; *) echo 'Unsupported host architecture'; exit 1;; esac\n" +
		"asset=zoomies_linux_$arch\ntag=" + quote(tag) + "\nbase=" + quote("https://github.com/eyupio/zoomies/releases/download/"+tag) + "\n" +
		"tmp=$(mktemp -d \"$dir/download.XXXXXX\")\ntrap 'rm -rf \"$tmp\"' EXIT\n" +
		"curl --proto '=https' --proto-redir '=https' -fsSL \"$base/$asset\" -o \"$tmp/$asset\"\n" +
		"curl --proto '=https' --proto-redir '=https' -fsSL \"$base/checksums.txt\" -o \"$tmp/checksums.txt\"\n" +
		"curl --proto '=https' --proto-redir '=https' -fsSL \"$base/checksums.txt.ed25519\" -o \"$tmp/checksums.txt.ed25519\" 2>/dev/null || rm -f \"$tmp/checksums.txt.ed25519\"\n" +
		"verify_signature \"$tag\" \"$tmp/checksums.txt\" \"$tmp/checksums.txt.ed25519\" \"$tmp\"\n" +
		"(cd \"$tmp\"; awk -v asset=\"$asset\" '$2 == asset || $2 == \"*\" asset { print; found=1 } END { if (!found) exit 1 }' checksums.txt > selected; sha256sum -c selected)\n" +
		"chmod 700 \"$tmp/$asset\"\n" +
		"\"$tmp/$asset\" providers connect-proxmox --controller " + quote(controller) + " --setup-id " + quote(id) + " --token " + quote(token) + "\n" +
		"ZOOMIES_PROXMOX_SETUP"
}

// ConnectScriptURL is where connect-proxmox.sh is served; the site workflow
// copies the file from the repository root, as it does install.sh.
const ConnectScriptURL = "https://zoomies.sh/connect-proxmox.sh"

// ShortCommand is Command's two-line form: the same private, checksum-verified
// download, done by the hosted connect-proxmox.sh so the operator pastes a line
// they can read instead of a script. Command stays as the full text for a host
// that cannot reach zoomies.sh, and for anyone who wants to read every step
// before running it.
func ShortCommand(controller, id, token, tag string) string {
	quote := func(s string) string { return "'" + strings.ReplaceAll(s, "'", "'\\''") + "'" }
	return "if [ \"$(id -u)\" -eq 0 ]; then zoomies_sudo=''; else zoomies_sudo='sudo'; fi\n" +
		"curl --proto '=https' --proto-redir '=https' -fsSL " + ConnectScriptURL + " | $zoomies_sudo sh -s -- " +
		"--version " + quote(tag) + " --key " + quote(InstanceKey(controller)) +
		" --controller " + quote(controller) + " --setup-id " + quote(id) + " --token " + quote(token)
}

// DiscoverTemplates reads cluster inventory without changing any guests.
func DiscoverTemplates(ctx context.Context, h Host) ([]Template, error) {
	raw, err := h.Run(ctx, "pvesh", "get", "/cluster/resources", "--type", "vm", "--output-format", "json")
	if err != nil {
		return nil, errors.New("proxmox setup: cannot list VM templates")
	}
	var rows []guest
	if err := json.Unmarshal(raw, &rows); err != nil {
		return nil, errors.New("proxmox setup: invalid VM inventory")
	}
	var templates []Template
	for _, row := range rows {
		if row.Type == "qemu" && row.Template == 1 && row.VMID >= 100 && row.Node != "" {
			templates = append(templates, Template{VMID: row.VMID, Name: row.Name, Node: row.Node})
		}
	}
	sort.Slice(templates, func(i, j int) bool { return templates[i].VMID < templates[j].VMID })
	return templates, nil
}

// endpointHost picks the name the controller will dial the node by. A Proxmox
// certificate lists localhost among its names, and the first one in the list
// is as likely to be that as the node's own, but no name that only means "this
// machine" can be verified from anywhere else, and it is the wrong thing to
// save: the provider fails its first check and the CA that was sent along
// cannot help. So loopback names are never chosen, whatever order they come in.
func endpointHost(cert *x509.Certificate, node string) string {
	for _, name := range cert.DNSNames {
		if !strings.Contains(name, "*") && !loopbackName(name) {
			return name
		}
	}
	for _, name := range cert.DNSNames {
		if strings.HasPrefix(name, "*.") && !loopbackName(node+strings.TrimPrefix(name, "*")) {
			return node + strings.TrimPrefix(name, "*")
		}
	}
	for _, ip := range cert.IPAddresses {
		if !ip.IsLoopback() && !ip.IsUnspecified() {
			return ip.String()
		}
	}
	return ""
}

func loopbackName(name string) bool {
	name = strings.ToLower(strings.TrimSuffix(name, "."))
	if name == "localhost" || name == "localhost.localdomain" || strings.HasSuffix(name, ".localhost") {
		return true
	}
	ip := net.ParseIP(name)
	return ip != nil && ip.IsLoopback()
}

package proxmoxsetup

import (
	"context"
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/pem"
	"errors"
	"github.com/tailscale/tailcat"
	"math/big"
	"net"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

func hostCertificate(t *testing.T) []byte {
	t.Helper()
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	cert := &x509.Certificate{SerialNumber: big.NewInt(1), Subject: pkix.Name{CommonName: "pve.example"}, DNSNames: []string{"pve.example"}, NotBefore: time.Now().Add(-time.Hour), NotAfter: time.Now().Add(time.Hour), IsCA: true, BasicConstraintsValid: true, KeyUsage: x509.KeyUsageCertSign | x509.KeyUsageDigitalSignature}
	der, err := x509.CreateCertificate(rand.Reader, cert, cert, key.Public(), key)
	if err != nil {
		t.Fatal(err)
	}
	return pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der})
}

func TestPrepareDetectsConnectionAndReusesCredential(t *testing.T) {
	cert := hostCertificate(t)
	files := map[string][]byte{"/etc/pve/pve-root-ca.pem": cert, "/etc/pve/local/pve-ssl.pem": cert, "/etc/hostname": []byte("pve-1\n"), "/var/lib/zoomies/agent.json": []byte("existing runner credentials")}
	var commands []string
	h := Host{
		ReadFile: func(path string) ([]byte, error) {
			if b, ok := files[path]; ok {
				return b, nil
			}
			return nil, os.ErrNotExist
		},
		WriteFile: func(path string, b []byte, mode os.FileMode) error {
			if mode != 0600 {
				t.Fatalf("credential mode: %v", mode)
			}
			files[path] = b
			return nil
		},
		Run: func(_ context.Context, name string, argv ...string) ([]byte, error) {
			line := name + " " + strings.Join(argv, " ")
			commands = append(commands, line)
			if strings.Contains(line, "token add") {
				return []byte(`{"value":"token-secret"}`), nil
			}
			return nil, nil
		},
	}
	dir := "/var/lib/zoomies-proxmox/abc"
	c, err := Prepare(context.Background(), h, dir, "abc")
	if err != nil {
		t.Fatal(err)
	}
	if c.Name != "proxmox-pve-1" || c.Endpoint != "https://pve.example:8006" || c.Credential != "zoomies-abc@pve!provider-"+InstanceKey("pve-1")+"=token-secret" || c.CAPEM != string(cert) {
		t.Fatalf("unexpected connection: %+v", c)
	}
	if string(files["/var/lib/zoomies/agent.json"]) != "existing runner credentials" {
		t.Fatal("runner state changed")
	}
	if !strings.Contains(strings.Join(commands, "\n"), "--privsep 1") || !strings.Contains(strings.Join(commands, "\n"), "--tokens zoomies-abc@pve!provider-"+InstanceKey("pve-1")) {
		t.Fatalf("missing separated token ACLs: %v", commands)
	}
	commands = nil
	again, err := Prepare(context.Background(), h, dir, "abc")
	if err != nil {
		t.Fatal(err)
	}
	if c.Credential != again.Credential || len(commands) != 0 {
		t.Fatal("retry rotated token or modified Proxmox")
	}
	files["/etc/hostname"] = []byte("pve-2\n")
	second, err := Prepare(context.Background(), h, "/another-node/abc", "abc")
	if err != nil {
		t.Fatal(err)
	}
	if second.Credential == c.Credential || string(files[dir+"/credential"]) != c.Credential {
		t.Fatal("adding another cluster node reused or rotated the first node's token")
	}

	// A first run can stop after pveum creates a token but before saving it.
	previousRun := h.Run
	attempts := 0
	h.Run = func(ctx context.Context, command string, args ...string) ([]byte, error) {
		if strings.Contains(strings.Join(args, " "), "token add") {
			attempts++
			if attempts == 1 {
				return nil, errors.New("token already exists")
			}
		}
		return previousRun(ctx, command, args...)
	}
	recovered, err := Prepare(context.Background(), h, "/interrupted-node/abc", "abc")
	if err != nil || attempts != 2 || recovered.Credential == second.Credential {
		t.Fatalf("partial setup not recovered: %v", err)
	}
	if strings.Contains(strings.Join(commands, "\n"), "token remove") {
		t.Fatal("recovery revoked another connection")
	}
}

func TestPrepareRefusesUnreadableCredentialInsteadOfRotatingIt(t *testing.T) {
	cert := hostCertificate(t)
	h := Host{ReadFile: func(path string) ([]byte, error) {
		switch path {
		case "/etc/pve/pve-root-ca.pem", "/etc/pve/local/pveproxy-ssl.pem":
			return cert, nil
		case "/etc/hostname":
			return []byte("pve"), nil
		default:
			return nil, os.ErrPermission
		}
	}, Run: func(context.Context, string, ...string) ([]byte, error) {
		t.Fatal("attempted to rotate token")
		return nil, nil
	}}
	if _, err := Prepare(context.Background(), h, "/provider", "abc"); !os.IsPermission(err) {
		t.Fatalf("unreadable token: %v", err)
	}
}

func TestSetupCommandIsStandaloneAndShellQuoted(t *testing.T) {
