		"a path in a version": {"--version", "../x", "--key", "k", "--controller", "https://c", "--setup-id", "pvs_1", "--token", "t"},
		"a path in a key":     {"--version", "v1", "--key", "a/b", "--controller", "https://c", "--setup-id", "pvs_1", "--token", "t"},
		"an unknown option":   {"--bogus", "x"},
