package prrepair

import (
	"fmt"
	"strings"
)

// ApplySuppliedEdits reuses the repair preimage and overlap checks without a
// reader or model. Callers supply complete regular files; policy and currentness
// remain their responsibility.
func ApplySuppliedEdits(files []File, edits []Edit, workflows bool) ([]File, error) {
	if len(files) == 0 || len(files) > MaxEdits || len(edits) == 0 || len(edits) > MaxEdits {
		return nil, fmt.Errorf("supplied edits exceed the file or edit allowance")
	}
	s := newSourceContext(nil, workflows)
	total := 0
	for _, f := range files {
		total += len(f.Content)
		if _, exists := s.originals[f.Path]; exists || f.Partial || f.StartLine != 0 || f.Mode != "100644" && f.Mode != "100755" || !AllowedPath(f.Path, workflows) || len(f.Content) > MaxBlobBytes || total > MaxSourceBytes || !validText(f.Content) || strings.Contains(f.Content, "[redacted credential]") || credential.MatchString(f.Content) {
			return nil, fmt.Errorf("supplied source is incomplete, protected or outside the text allowance")
		}
		s.originals[f.Path] = f
		s.shown[f.Path] = []sourceSpan{{0, len(f.Content)}}
	}
	out, err := s.apply(edits)
	if err != nil {
		return nil, err
	}
	for _, f := range out {
		if len(f.Content) > MaxBlobBytes || !validText(f.Content) || strings.Contains(f.Content, "[redacted credential]") || credential.MatchString(f.Content) {
			return nil, fmt.Errorf("edited source exceeds the text allowance or contains a credential")
		}
	}
	return out, nil
}

package prrepair

import "testing"

func TestSuppliedEditsKeepModeAndRefuseUnreadProtectedOverlappingOrCredentialChanges(t *testing.T) {
	f := File{Path: ".github/workflows/ci.yml", Content: "first\nsecond\n", Mode: "100644"}
	e := Edit{Path: f.Path, Before: "first", After: "changed"}
	out, err := ApplySuppliedEdits([]File{f}, []Edit{e}, true)
	if err != nil || len(out) != 1 || out[0].Mode != f.Mode || out[0].Content != "changed\nsecond\n" {
		t.Fatal("bounded edit changed source or mode", err)
	}
	for _, mode := range []string{"protected", "unread", "overlap", "partial", "binary", "duplicate", "credential", "redacted"} {
		file, edit, edits, allow := f, e, []Edit{e}, true
		switch mode {
		case "protected":
			allow = false
		case "unread":
			edit.Path = "missing.go"
			edits = []Edit{edit}
		case "overlap":
			edits = []Edit{e, e}
		case "partial":
			file.Partial = true
		case "binary":
			file.Content += "\x00"
		case "duplicate":
			file.Content += "first"
		case "redacted":
			file.Content += "[redacted credential]"
		case "credential":
			edit.After = "ghp_012345678901234567890123456789"
			edits = []Edit{edit}
		}
		if _, err := ApplySuppliedEdits([]File{file}, edits, allow); err == nil {
			t.Fatalf("%s accepted", mode)
		}
	}
}

package prrepair

import (
	"bytes"
	"encoding/json"
	"strings"
)

// Call is a tool call a model made, as far as the repair needs to know it.
type Call struct {
	Name      string
	Arguments json.RawMessage
}

// ReplyFromCalls reads a model's tool calls as the reply it was asked for, and
// says whether it could.
//
// A repair offers no tools. Its replies are JSON objects the system prompt
// describes: {"read":["path"]} to see a file, {"windows":[...]} to see part of
// one, {"summary":...,"edits":[...]} to fix it, {"cannot_fix":"..."} to stop. A
// model trained to call functions takes those words for functions and calls
// `read` or `windows`, and on a repair that was one step from finished the
// answer was to give up. The call says exactly what the reply would have, so it
// is read as the reply. The result is only returned when the repair would have
// accepted it typed out, which is checked by decoding it as the repair does; the
// path allow-list, the bounds and the pinned head still apply to it afterwards,
// so this grants the model nothing it could not already ask for.
//
// What it cannot read is left for the caller to refuse as a tool the model was
// not offered: a call it only half understands is a guess at what was meant.
func ReplyFromCalls(calls []Call) (string, bool) {
	if len(calls) == 0 {
		return "", false
	}
	var reads []string
	var windows []ReadWindow
	seen := map[string]bool{}
	for _, c := range calls {
		var args any
		if err := json.Unmarshal(c.Arguments, &args); err != nil {
			return "", false
		}
		switch k := callKind(c.Name); k {
		case kindRead:
			paths, ok := pathsFrom(args)
			if !ok {
				return "", false
			}
			for _, p := range paths {
				if !seen[p] {
					seen[p] = true
					reads = append(reads, p)
				}
			}
		case kindWindows:
			found, ok := windowsFrom(args)
			if !ok {
				return "", false
			}
			windows = append(windows, found...)
		case kindFix, kindGiveUp:
			// A fix or a giving up ends the repair, so it stands alone: beside a
			// read it would be two replies, and the repair accepts one.
			if len(calls) != 1 {
				return "", false
			}
			if k == kindGiveUp {
				return giveUpReply(args)
			}
			return planReply(c.Arguments, args)
		default:
			return "", false
		}
	}
	out, err := json.Marshal(struct {
		Read    []string     `json:"read,omitempty"`
		Windows []ReadWindow `json:"windows,omitempty"`
	}{reads, windows})
	if err != nil {
		return "", false
	}
	return accepted(string(out))
}

type kind int

const (
	kindUnknown kind = iota
	kindRead
	kindWindows
	kindFix
	kindGiveUp
)

// callKind is what a tool name stands for. Some providers prefix a name with a
// namespace, and some models say read_file for read; both mean the reply.
func callKind(name string) kind {
	name = strings.TrimPrefix(strings.ToLower(strings.TrimSpace(name)), "functions.")
	switch name {
	case "read", "read_file", "read_files":
		return kindRead
	case "windows", "read_window", "read_windows":
		return kindWindows
	case "edits", "files", "summary":
		return kindFix
	case "cannot_fix":
		return kindGiveUp
	}
	return kindUnknown
}

// pathsFrom finds the paths a read asks for in whichever shape the model wrote
// them: the reply's own {"read":[...]}, a single {"path":"..."}, a list of
// strings, or a list of objects with a path.
func pathsFrom(v any) ([]string, bool) {
	switch v := v.(type) {
	case string:
		return []string{v}, v != ""
	case []any:
		var out []string
		for _, item := range v {
			switch item := item.(type) {
			case string:
				if item == "" {
					return nil, false
				}
				out = append(out, item)
			case map[string]any:
				p, ok := item["path"].(string)
				if !ok || p == "" {
					return nil, false
				}
				out = append(out, p)
			default:
				return nil, false
			}
		}
		return out, len(out) > 0
	case map[string]any:
		for _, key := range []string{"read", "paths", "files", "path", "file"} {
			if inner, present := v[key]; present {
				return pathsFrom(inner)
			}
		}
	}
	return nil, false
}

// windowsFrom finds the windows a read asks for: the reply's own
// {"windows":[...]}, a list of windows, or one window written as the object.
// A window is decoded as the repair decodes it, so a line given as text, or a
// field the repair has no word for, is not read.
func windowsFrom(v any) ([]ReadWindow, bool) {
	var items []any
	switch v := v.(type) {
	case []any:
		items = v
	case map[string]any:
		if inner, ok := v["windows"]; ok {
			return windowsFrom(inner)
		}
		items = []any{v}
	default:
		return nil, false
	}
	out := make([]ReadWindow, 0, len(items))
	for _, item := range items {
		raw, err := json.Marshal(item)
		if err != nil {
			return nil, false
		}
		dec := json.NewDecoder(bytes.NewReader(raw))
		dec.DisallowUnknownFields()
		var w ReadWindow
		if err := dec.Decode(&w); err != nil || w.Path == "" {
			return nil, false
		}
		out = append(out, w)
	}
	return out, len(out) > 0
}

// giveUpReply reads a call that stops the repair: the reason, in the reply's own
// shape, or as a bare string, or under the name a model is likelier to give it.
func giveUpReply(args any) (string, bool) {
	var reason string
	switch v := args.(type) {
	case string:
		reason = v
	case map[string]any:
		for _, key := range []string{"cannot_fix", "reason", "message"} {
			if s, ok := v[key].(string); ok && s != "" {
				reason = s
				break
			}
		}
	}
	if reason == "" {
		return "", false
	}
	out, err := json.Marshal(struct {
		CannotFix string `json:"cannot_fix"`
	}{reason})
	if err != nil {
		return "", false
	}
	return accepted(string(out))
}

// planReply reads a call that proposes the fix. Its arguments have to be the
// reply itself, a summary with edits or files: a bare list of edits has no
// summary to publish, and one that is invented is not what the model said.
func planReply(raw json.RawMessage, args any) (string, bool) {
	if _, isObject := args.(map[string]any); !isObject {
		return "", false
	}
	var compact bytes.Buffer
	if err := json.Compact(&compact, raw); err != nil {
		return "", false
	}
	p, err := decode(compact.String())
	if err != nil || strings.TrimSpace(p.Summary) == "" || len(p.Edits)+len(p.Files) == 0 || len(p.Read)+len(p.Windows) > 0 || p.CannotFix != "" {
		return "", false
	}
	return accepted(compact.String())
}

// accepted returns a reply only if the repair would decode it.
func accepted(reply string) (string, bool) {
	if _, err := decode(reply); err != nil {
		return "", false
	}
	return reply, true
}

package prrepair

import (
	"encoding/json"
	"reflect"
	"testing"
)

func call(name, args string) Call { return Call{Name: name, Arguments: json.RawMessage(args)} }

// A model that is offered no tools can still answer with a tool call, because the
// repair prompt describes its replies as {"read":[...]} and {"windows":[...]} and
// a model trained to call functions takes those for functions. The call says
// exactly what the reply would have, so it is read as the reply. Whatever comes
// out must be something the repair would have accepted had the model typed it.
func TestAToolCallNamedAfterAReplyIsReadAsThatReply(t *testing.T) {
	for _, tc := range []struct {
		name  string
		calls []Call
		want  Plan
	}{
		{"read with the reply's own shape", []Call{call("read", `{"read":["a.go","b.go"]}`)}, Plan{Read: []string{"a.go", "b.go"}}},
		{"read with one path", []Call{call("read", `{"path":"main.go"}`)}, Plan{Read: []string{"main.go"}}},
		{"read_file is the same ask", []Call{call("read_file", `{"path":"main.go"}`)}, Plan{Read: []string{"main.go"}}},
		{"read with several paths", []Call{call("read", `{"paths":["a.go","b.go"]}`)}, Plan{Read: []string{"a.go", "b.go"}}},
		{"read with files named by objects", []Call{call("read", `{"files":[{"path":"a.go"},{"path":"b.go"}]}`)}, Plan{Read: []string{"a.go", "b.go"}}},
		{"read with a bare list", []Call{call("read", `["a.go"]`)}, Plan{Read: []string{"a.go"}}},
		{"a name in capitals", []Call{call("READ", `{"path":"a.go"}`)}, Plan{Read: []string{"a.go"}}},
		{"parallel reads are one reply", []Call{call("read", `{"path":"a.go"}`), call("read", `{"path":"b.go"}`), call("read", `{"path":"a.go"}`)}, Plan{Read: []string{"a.go", "b.go"}}},
		{"windows with the reply's own shape", []Call{call("windows", `{"windows":[{"path":"a.go","start_line":10,"end_line":40}]}`)}, Plan{Windows: []ReadWindow{{Path: "a.go", StartLine: 10, EndLine: 40}}}},
		{"windows with one window", []Call{call("windows", `{"path":"a.go","start_line":1,"end_line":50}`)}, Plan{Windows: []ReadWindow{{Path: "a.go", StartLine: 1, EndLine: 50}}}},
		{"windows with a bare list", []Call{call("windows", `[{"path":"a.go","start_line":1,"end_line":5}]`)}, Plan{Windows: []ReadWindow{{Path: "a.go", StartLine: 1, EndLine: 5}}}},
		{"a read and a window together", []Call{call("read", `{"path":"a.go"}`), call("windows", `{"path":"b.go","start_line":1,"end_line":9}`)}, Plan{Read: []string{"a.go"}, Windows: []ReadWindow{{Path: "b.go", StartLine: 1, EndLine: 9}}}},
		{"a fix by edits", []Call{call("edits", `{"summary":"why","edits":[{"path":"a.go","before":"x","after":"y"}]}`)}, Plan{Summary: "why", Edits: []Edit{{Path: "a.go", Before: "x", After: "y"}}}},
		{"a fix by whole files", []Call{call("files", `{"summary":"why","files":[{"path":"a.go","content":"y"}]}`)}, Plan{Summary: "why", Files: []File{{Path: "a.go", Content: "y"}}}},
		{"giving up, in the reply's own shape", []Call{call("cannot_fix", `{"cannot_fix":"needs a secret"}`)}, Plan{CannotFix: "needs a secret"}},
		{"giving up, with a reason", []Call{call("cannot_fix", `{"reason":"needs a secret"}`)}, Plan{CannotFix: "needs a secret"}},
		{"giving up, with a bare string", []Call{call("cannot_fix", `"needs a secret"`)}, Plan{CannotFix: "needs a secret"}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			reply, ok := ReplyFromCalls(tc.calls)
			if !ok {
				t.Fatalf("the call was not read as a reply")
			}
			got, err := decode(reply)
			if err != nil {
				t.Fatalf("the reply %q is not one the repair accepts: %v", reply, err)
			}
			if !reflect.DeepEqual(got, tc.want) {
				t.Errorf("reply %q decoded to %+v, want %+v", reply, got, tc.want)
			}
		})
	}
}

// What cannot be read as a reply is left for the caller to answer as a tool call
// it was not offered. Guessing at a call that means something else would send
// the model's work somewhere it did not ask for.
func TestAToolCallThatIsNotAReplyIsLeftAlone(t *testing.T) {
	for _, tc := range []struct {
		name  string
		calls []Call
	}{
		{"no calls", nil},
		{"a tool the repair has no word for", []Call{call("run_tests", `{"command":"go test ./..."}`)}},
		{"a read of nothing", []Call{call("read", `{}`)}},
		{"a read of a number", []Call{call("read", `{"path":7}`)}},
		{"a read of an empty path", []Call{call("read", `{"path":""}`)}},
		{"a window with a path and lines as text", []Call{call("windows", `{"path":"a.go","start_line":"1","end_line":"5"}`)}},
		{"a window with no path", []Call{call("windows", `{"start_line":1,"end_line":5}`)}},
		{"arguments that are not JSON", []Call{call("read", `not json`)}},
		{"a fix with no summary", []Call{call("edits", `{"edits":[{"path":"a.go","before":"x","after":"y"}]}`)}},
		{"a fix with neither edits nor files", []Call{call("edits", `{"summary":"why"}`)}},
		{"a fix that is not an object", []Call{call("files", `[{"path":"a.go","content":"y"}]`)}},
		{"giving up with no reason", []Call{call("cannot_fix", `{}`)}},
		{"a read mixed with a tool it does not know", []Call{call("read", `{"path":"a.go"}`), call("run_tests", `{}`)}},
		{"a fix beside a read", []Call{call("read", `{"path":"a.go"}`), call("edits", `{"summary":"s","edits":[{"path":"a.go","before":"x","after":"y"}]}`)}},
		{"two fixes", []Call{call("edits", `{"summary":"s","edits":[{"path":"a.go","before":"x","after":"y"}]}`), call("edits", `{"summary":"s","edits":[{"path":"b.go","before":"x","after":"y"}]}`)}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if reply, ok := ReplyFromCalls(tc.calls); ok {
				t.Errorf("was read as the reply %q", reply)
			}
		})
	}
}

// Package qr encodes a short string as a QR code and renders it as SVG.
//
// It exists for one picture: the otpauth:// address an authenticator app
// scans when somebody turns two-step verification on. That is a few hundred
// bytes at most, so this is the smallest encoder that serves it -- byte mode
// only, error correction level M only, versions 1 to 10 -- rather than a
// dependency that would also do kanji, micro codes and PNG. Rendering on the
// server keeps the secret out of any third-party script, and SVG keeps it
// sharp at any size with no image library.
//
// The numbers are ISO/IEC 18004's. Where a table is written out below it is
// copied from the standard rather than derived, because a derived table that
// is subtly wrong still produces a picture, just not one a phone can read.
package qr

import (
	"errors"
	"fmt"
	"strings"
)

// ErrTooLong is returned for data that does not fit in the largest version
// this encoder supports.
var ErrTooLong = errors.New("qr: data is too long for a version 10 code at error correction level M")

// ecBlocks is one version's error correction layout at level M: the error
// correction codewords per block, then the blocks in each of the two groups
// and the data codewords each of their blocks holds.
type ecBlocks struct {
	ecPerBlock       int
	g1Blocks, g1Data int
	g2Blocks, g2Data int
}

// levelM is ISO/IEC 18004 table 9, level M, versions 1 to 10.
var levelM = [...]ecBlocks{
	1:  {10, 1, 16, 0, 0},
	2:  {16, 1, 28, 0, 0},
	3:  {26, 1, 44, 0, 0},
	4:  {18, 2, 32, 0, 0},
	5:  {24, 2, 43, 0, 0},
	6:  {16, 4, 27, 0, 0},
	7:  {18, 4, 31, 0, 0},
	8:  {22, 2, 38, 2, 39},
	9:  {22, 3, 36, 2, 37},
	10: {26, 4, 43, 1, 44},
}

// alignment is the row and column centres of the alignment patterns, from
// annex E.
var alignment = [...][]int{
	1: nil, 2: {6, 18}, 3: {6, 22}, 4: {6, 26}, 5: {6, 30},
	6: {6, 34}, 7: {6, 22, 38}, 8: {6, 24, 42}, 9: {6, 26, 46}, 10: {6, 28, 50},
}

const maxVersion = 10

func (b ecBlocks) dataCodewords() int { return b.g1Blocks*b.g1Data + b.g2Blocks*b.g2Data }

// Code is an encoded symbol: a square of modules, true for dark.
type Code struct {
	Version int
	Mask    int
	Size    int
	modules [][]bool
	// reservedMap marks function modules, which data and masks skip.
	reservedMap [][]bool
}

// Dark reports whether the module at row y, column x is dark.
func (c *Code) Dark(x, y int) bool { return c.modules[y][x] }

// Encode builds the smallest symbol that holds data, with the mask that
// scores lowest on the standard's penalty rules.
func Encode(data []byte) (*Code, error) {
	version := 0
	for v := 1; v <= maxVersion; v++ {
		// Mode indicator (4 bits), a character count (8 bits below version
		// 10, 16 from it), then the bytes.
		countBits := 8
		if v >= 10 {
			countBits = 16
		}
		if 4+countBits+8*len(data) <= 8*levelM[v].dataCodewords() {
			version = v
			break
		}
	}
	if version == 0 {
		return nil, ErrTooLong
	}
	codewords := interleave(version, dataCodewords(version, data))

	best := (*Code)(nil)
	bestScore := 0
	for mask := 0; mask < 8; mask++ {
		c := withMask(version, codewords, mask)
		if score := c.penalty(); best == nil || score < bestScore {
			best, bestScore = c, score
		}
	}
	return best, nil
}

// withMask lays the codewords out under one mask.
func withMask(version int, codewords []byte, mask int) *Code {
	c := newCode(version)
	c.Mask = mask
	c.placeData(codewords, mask)
	c.placeFormat(mask)
	return c
}

// dataCodewords renders data as a byte-mode segment padded out to the
// version's capacity.
func dataCodewords(version int, data []byte) []byte {
	var bits bitBuffer
	bits.put(0b0100, 4)
	if version >= 10 {
		bits.put(len(data), 16)
	} else {
		bits.put(len(data), 8)
	}
	for _, b := range data {
		bits.put(int(b), 8)
	}
	capacity := 8 * levelM[version].dataCodewords()
	// Up to four zero bits of terminator, then zeros to the byte boundary.
	for i := 0; i < 4 && len(bits) < capacity; i++ {
		bits = append(bits, false)
	}
	for len(bits)%8 != 0 {
		bits = append(bits, false)
	}
	out := bits.bytes()
	for pad := 0; len(out) < capacity/8; pad++ {
		if pad%2 == 0 {
			out = append(out, 0xEC)
		} else {
			out = append(out, 0x11)
		}
	}
	return out
}

// interleave splits the data into the version's blocks, appends each
// block's error correction, and interleaves them as the symbol stores them.
func interleave(version int, data []byte) []byte {
	b := levelM[version]
	var blocks [][]byte
	pos := 0
	for i := 0; i < b.g1Blocks; i++ {
		blocks = append(blocks, data[pos:pos+b.g1Data])
		pos += b.g1Data
	}
	for i := 0; i < b.g2Blocks; i++ {
		blocks = append(blocks, data[pos:pos+b.g2Data])
		pos += b.g2Data
	}
	ecc := make([][]byte, len(blocks))
	for i, blk := range blocks {
		ecc[i] = reedSolomon(blk, b.ecPerBlock)
	}
	var out []byte
	longest := b.g1Data
	if b.g2Data > longest {
		longest = b.g2Data
	}
	for i := 0; i < longest; i++ {
		for _, blk := range blocks {
			if i < len(blk) {
				out = append(out, blk[i])
			}
		}
	}
	for i := 0; i < b.ecPerBlock; i++ {
		for _, e := range ecc {
			out = append(out, e[i])
		}
	}
	return out
}

// ---------------------------------------------------------------------------
// Reed-Solomon over GF(256) with the QR polynomial x^8+x^4+x^3+x^2+1.
// ---------------------------------------------------------------------------

var gfExp, gfLog = func() (exp [512]byte, log [256]byte) {
	x := 1
	for i := 0; i < 255; i++ {
		exp[i] = byte(x)
		log[x] = byte(i)
		x <<= 1
		if x&0x100 != 0 {
			x ^= 0x11D
		}
	}
	for i := 255; i < 512; i++ {
		exp[i] = exp[i-255]
	}
	return exp, log
}()

func gfMul(a, b byte) byte {
	if a == 0 || b == 0 {
		return 0
	}
	return gfExp[int(gfLog[a])+int(gfLog[b])]
}

// generator returns the degree-n generator polynomial, highest term first.
func generator(n int) []byte {
	g := []byte{1}
	for i := 0; i < n; i++ {
		next := make([]byte, len(g)+1)
		for j, c := range g {
			next[j] ^= c
			next[j+1] ^= gfMul(c, gfExp[i])
		}
		g = next
	}
	return g
}

// reedSolomon returns the n error correction codewords for data.
func reedSolomon(data []byte, n int) []byte {
	g := generator(n)
	rem := make([]byte, n)
	for _, d := range data {
		factor := d ^ rem[0]
		copy(rem, rem[1:])
		rem[n-1] = 0
		for j := 0; j < n; j++ {
			rem[j] ^= gfMul(g[j+1], factor)
		}
	}
	return rem
}

// ---------------------------------------------------------------------------
// Module placement
// ---------------------------------------------------------------------------

func newCode(version int) *Code {
	size := 17 + 4*version
	c := &Code{Version: version, Size: size, modules: make([][]bool, size)}
	reserved := make([][]bool, size)
	for i := range c.modules {
		c.modules[i] = make([]bool, size)
		reserved[i] = make([]bool, size)
	}
	c.reservedMap = reserved
	c.placeFunctionPatterns()
	return c
}

// set places a function module, which data placement and masking skip.
func (c *Code) set(x, y int, dark bool) {
	c.modules[y][x] = dark
	c.reservedMap[y][x] = true
}

func (c *Code) placeFunctionPatterns() {
	n := c.Size
	// Finder patterns, with their separators, in three corners.
	for _, at := range [][2]int{{0, 0}, {n - 7, 0}, {0, n - 7}} {
		for dy := -1; dy <= 7; dy++ {
			for dx := -1; dx <= 7; dx++ {
				x, y := at[0]+dx, at[1]+dy
				if x < 0 || y < 0 || x >= n || y >= n {
					continue
				}
				ring := max(abs(dx-3), abs(dy-3))
				c.set(x, y, ring != 2 && ring != 4)
			}
		}
	}
	// Timing patterns.
	for i := 8; i < n-8; i++ {
		c.set(i, 6, i%2 == 0)
		c.set(6, i, i%2 == 0)
	}
	// Alignment patterns, everywhere they do not collide with a finder.
	// Three of the grid's corners are finder patterns; every other centre,
	// including the ones on the timing lines, gets a pattern.
	centres := alignment[c.Version]
	last := len(centres) - 1
	for i, cy := range centres {
		for j, cx := range centres {
			if (i == 0 && j == 0) || (i == 0 && j == last) || (i == last && j == 0) {
				continue
			}
			for dy := -2; dy <= 2; dy++ {
				for dx := -2; dx <= 2; dx++ {
					c.set(cx+dx, cy+dy, max(abs(dx), abs(dy)) != 1)
				}
			}
		}
	}
	// Reserve the format areas (written once the mask is chosen) and the
	// dark module.
	for i := 0; i < 9; i++ {
		c.reservedMap[8][i] = true
		c.reservedMap[i][8] = true
	}
	for i := 0; i < 8; i++ {
		c.reservedMap[8][n-1-i] = true
		c.reservedMap[n-1-i][8] = true
	}
	c.set(8, n-8, true)
	// Version information, from version 7.
	if c.Version >= 7 {
		bits := versionBits(c.Version)
		for i := 0; i < 18; i++ {
			dark := bits>>uint(i)&1 == 1
			a, b := i/3, n-11+i%3
			c.set(a, b, dark)
			c.set(b, a, dark)
		}
	}
}

// placeData writes the codewords in the standard's two-column zigzag, from
// the bottom-right corner, applying the mask as it goes.
func (c *Code) placeData(codewords []byte, mask int) {
	n := c.Size
	bit := 0
	total := len(codewords) * 8
	upward := true
	for right := n - 1; right >= 1; right -= 2 {
		if right == 6 {
			// The vertical timing pattern takes a whole column.
			right = 5
		}
		for i := 0; i < n; i++ {
			y := i
			if upward {
				y = n - 1 - i
			}
			for dx := 0; dx < 2; dx++ {
				x := right - dx
				if c.reservedMap[y][x] {
					continue
				}
				dark := false
				if bit < total {
					dark = codewords[bit/8]>>uint(7-bit%8)&1 == 1
					bit++
				}
				if maskAt(mask, x, y) {
					dark = !dark
				}
				c.modules[y][x] = dark
			}
		}
		upward = !upward
	}
}

// maskAt is the eight data masks of table 10.
func maskAt(mask, x, y int) bool {
	switch mask {
	case 0:
		return (x+y)%2 == 0
	case 1:
		return y%2 == 0
	case 2:
		return x%3 == 0
	case 3:
		return (x+y)%3 == 0
	case 4:
		return (y/2+x/3)%2 == 0
	case 5:
		return (x*y)%2+(x*y)%3 == 0
	case 6:
		return ((x*y)%2+(x*y)%3)%2 == 0
	default:
		return ((x+y)%2+(x*y)%3)%2 == 0
	}
}

// formatBits is the 15-bit format word for level M and a mask: a BCH(15,5)
// code, XORed with the standard's fixed pattern so it is never all light.
func formatBits(mask int) int {
	const levelMBits = 0b00
	data := levelMBits<<3 | mask
	rem := data << 10
	for i := 14; i >= 10; i-- {
		if rem>>uint(i)&1 == 1 {
			rem ^= 0x537 << uint(i-10)
		}
	}
	return (data<<10 | rem) ^ 0x5412
}

// versionBits is the 18-bit version word: a BCH(18,6) code.
func versionBits(version int) int {
	rem := version << 12
	for i := 17; i >= 12; i-- {
		if rem>>uint(i)&1 == 1 {
			rem ^= 0x1F25 << uint(i-12)
		}
	}
	return version<<12 | rem
}

func (c *Code) placeFormat(mask int) {
	n := c.Size
	bits := formatBits(mask)
	bitAt := func(i int) bool { return bits>>uint(i)&1 == 1 }
	// Around the top-left finder: bits 0-5 down column 8, then 6-7 skipping
	// the timing row, 8 on the corner, 9-14 along row 8.
	for i := 0; i <= 5; i++ {
		c.modules[i][8] = bitAt(i)
	}
	c.modules[7][8] = bitAt(6)
	c.modules[8][8] = bitAt(7)
	c.modules[8][7] = bitAt(8)
	for i := 9; i < 15; i++ {
		c.modules[8][14-i] = bitAt(i)
	}
	// The second copy, split between the other two finders.
	for i := 0; i < 8; i++ {
		c.modules[8][n-1-i] = bitAt(i)
	}
	for i := 8; i < 15; i++ {
		c.modules[n-15+i][8] = bitAt(i)
	}
	c.modules[n-8][8] = true
}

// penalty scores a finished symbol by the four rules of section 7.8.3; the
// lowest-scoring mask is the one a scanner finds easiest.
func (c *Code) penalty() int {
	n := c.Size
	score := 0
	// Rule 1: runs of five or more in a row or column.
	for y := 0; y < n; y++ {
		for _, line := range [2]func(i int) bool{
			func(i int) bool { return c.modules[y][i] },
			func(i int) bool { return c.modules[i][y] },
		} {
			run := 1
			for i := 1; i < n; i++ {
				if line(i) == line(i-1) {
					run++
					continue
				}
				if run >= 5 {
					score += run - 2
				}
				run = 1
			}
			if run >= 5 {
				score += run - 2
			}
		}
	}
	// Rule 2: two-by-two blocks of one colour.
	for y := 0; y < n-1; y++ {
		for x := 0; x < n-1; x++ {
			d := c.modules[y][x]
			if c.modules[y][x+1] == d && c.modules[y+1][x] == d && c.modules[y+1][x+1] == d {
				score += 3
			}
		}
	}
	// Rule 3: anything that looks like a finder pattern.
	pattern := []bool{true, false, true, true, true, false, true, false, false, false, false}
	for y := 0; y < n; y++ {
		for x := 0; x+len(pattern) <= n; x++ {
			fwdRow, revRow, fwdCol, revCol := true, true, true, true
			for k, p := range pattern {
				if c.modules[y][x+k] != p {
					fwdRow = false
				}
				if c.modules[y][x+len(pattern)-1-k] != p {
					revRow = false
				}
				if c.modules[x+k][y] != p {
					fwdCol = false
				}
				if c.modules[x+len(pattern)-1-k][y] != p {
					revCol = false
				}
			}
			for _, hit := range []bool{fwdRow, revRow, fwdCol, revCol} {
				if hit {
					score += 40
				}
			}
		}
	}
	// Rule 4: how far the dark proportion is from half.
	dark := 0
	for y := 0; y < n; y++ {
		for x := 0; x < n; x++ {
			if c.modules[y][x] {
				dark++
			}
		}
	}
	percent := dark * 100 / (n * n)
	score += abs(percent-50) / 5 * 10
	return score
}

// SVG renders the symbol with the four-module quiet zone the standard asks
// for, as one path. The colours are the caller's: the page draws it dark on
// light in both themes, because a scanner wants contrast, not a theme.
func (c *Code) SVG(dark, light string) string {
	const quiet = 4
	size := c.Size + 2*quiet
	var path strings.Builder
	for y := 0; y < c.Size; y++ {
		for x := 0; x < c.Size; x++ {
			if !c.modules[y][x] {
				continue
			}
			// Runs along a row become one rectangle, which keeps a version
			// 10 symbol to a few kilobytes.
			start := x
			for x+1 < c.Size && c.modules[y][x+1] {
				x++
			}
			fmt.Fprintf(&path, "M%d %dh%dv1h-%dz", start+quiet, y+quiet, x-start+1, x-start+1)
		}
	}
	return fmt.Sprintf(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 %d %d" shape-rendering="crispEdges">`+
		`<rect width="%d" height="%d" fill="%s"/><path d="%s" fill="%s"/></svg>`,
		size, size, size, size, light, path.String(), dark)
}

// bitBuffer is a big-endian bit stream.
type bitBuffer []bool

func (b *bitBuffer) put(v, n int) {
	for i := n - 1; i >= 0; i-- {
		*b = append(*b, v>>uint(i)&1 == 1)
	}
}

func (b bitBuffer) bytes() []byte {
	out := make([]byte, len(b)/8)
	for i, bit := range b {
		if bit {
			out[i/8] |= 1 << uint(7-i%8)
		}
	}
	return out
}

func abs(v int) int {
	if v < 0 {
		return -v
	}
	return v
}

package qr

import (
	"bytes"
	"errors"
	"fmt"
	"strings"
	"testing"
)

// The error correction is the part a mistake hides in best: a symbol with
// wrong ECC still draws, and still scans on a good camera, until one module
// is smudged. The vector is the standard worked example, "HELLO WORLD" as a
// version 1-M symbol.
func TestReedSolomonMatchesTheWorkedExample(t *testing.T) {
	data := []byte{32, 91, 11, 120, 209, 114, 220, 77, 67, 64, 236, 17, 236, 17, 236, 17}
	want := []byte{196, 35, 39, 119, 235, 215, 231, 226, 93, 23}
	if got := reedSolomon(data, 10); !bytes.Equal(got, want) {
		t.Fatalf("reedSolomon = %v, want %v", got, want)
	}
}

func TestFormatAndVersionWordsMatchTheStandardsTables(t *testing.T) {
	for _, tc := range []struct {
		mask int
		want string
	}{
		{0, "101010000010010"},
		{1, "101000100100101"},
		{2, "101111001111100"},
		{3, "101101101001011"},
		{4, "100010111111001"},
		{5, "100000011001110"},
		{6, "100111110010111"},
		{7, "100101010100000"},
	} {
		if got := fmt.Sprintf("%015b", formatBits(tc.mask)); got != tc.want {
			t.Errorf("formatBits(M, %d) = %s, want %s", tc.mask, got, tc.want)
		}
	}
	for _, tc := range []struct {
		version int
		want    string
	}{
		{7, "000111110010010100"},
		{8, "001000010110111100"},
		{10, "001010010011010011"},
	} {
		if got := fmt.Sprintf("%018b", versionBits(tc.version)); got != tc.want {
			t.Errorf("versionBits(%d) = %s, want %s", tc.version, got, tc.want)
		}
	}
}

// readCodewords walks a finished symbol the way a scanner does -- the same
// zigzag, skipping function modules, removing the mask -- and returns the
// bytes it finds. Placement and reading written separately would agree on a
// shared mistake; this one leans on newCode only for which modules are
// function modules, which the finder, timing and alignment checks pin down.
func readCodewords(c *Code, n int) []byte {
	ref := newCode(c.Version)
	var bits bitBuffer
	upward := true
	for right := c.Size - 1; right >= 1; right -= 2 {
		if right == 6 {
			right = 5
		}
		for i := 0; i < c.Size; i++ {
			y := i
			if upward {
				y = c.Size - 1 - i
			}
			for dx := 0; dx < 2; dx++ {
				x := right - dx
				if ref.reservedMap[y][x] {
					continue
				}
				bits = append(bits, c.Dark(x, y) != maskAt(c.Mask, x, y))
			}
		}
		upward = !upward
	}
	return bits.bytes()[:n]
}

func TestEverySupportedVersionRoundTripsItsCodewords(t *testing.T) {
	for v := 1; v <= maxVersion; v++ {
		b := levelM[v]
		// The longest payload the version holds, so the version chosen is v.
		countBits := 8
		if v >= 10 {
			countBits = 16
		}
		n := (8*b.dataCodewords() - 4 - countBits) / 8
		data := bytes.Repeat([]byte("otpauth://totp/"), 20)[:n]
		c, err := Encode(data)
		if err != nil {
			t.Fatalf("version %d: %v", v, err)
		}
		if c.Version != v || c.Size != 17+4*v {
			t.Fatalf("%d bytes chose version %d (size %d), want %d", n, c.Version, c.Size, v)
		}
		want := interleave(v, dataCodewords(v, data))
		if got := readCodewords(c, len(want)); !bytes.Equal(got, want) {
			t.Errorf("version %d: the codewords read back differ from the ones placed", v)
		}
	}
}

func TestTheFunctionPatternsAreWhereAScannerLooks(t *testing.T) {
	c, err := Encode([]byte("otpauth://totp/Zoomies:ada?secret=JBSWY3DPEHPK3PXP&issuer=Zoomies"))
	if err != nil {
		t.Fatal(err)
	}
	finder := []string{"1111111", "1000001", "1011101", "1011101", "1011101", "1000001", "1111111"}
	for _, at := range [][2]int{{0, 0}, {c.Size - 7, 0}, {0, c.Size - 7}} {
		for dy, row := range finder {
			for dx, ch := range row {
				if c.Dark(at[0]+dx, at[1]+dy) != (ch == '1') {
					t.Fatalf("the finder at %v is wrong at (%d,%d)", at, dx, dy)
				}
			}
		}
	}
	for i := 8; i < c.Size-8; i++ {
		if c.Dark(i, 6) != (i%2 == 0) || c.Dark(6, i) != (i%2 == 0) {
			t.Fatalf("the timing pattern is broken at %d", i)
		}
	}
	if !c.Dark(8, c.Size-8) {
		t.Fatal("the dark module is light")
	}
	// Both copies of the format word say level M and the chosen mask.
	var first, second int
	for i := 0; i <= 5; i++ {
		first |= b2i(c.Dark(8, i)) << i
	}
	first |= b2i(c.Dark(8, 7))<<6 | b2i(c.Dark(8, 8))<<7 | b2i(c.Dark(7, 8))<<8
	for i := 9; i < 15; i++ {
		first |= b2i(c.Dark(14-i, 8)) << i
	}
	for i := 0; i < 8; i++ {
		second |= b2i(c.Dark(c.Size-1-i, 8)) << i
	}
	for i := 8; i < 15; i++ {
		second |= b2i(c.Dark(8, c.Size-15+i)) << i
	}
	if first != formatBits(c.Mask) || second != first {
		t.Fatalf("format words %015b and %015b, want %015b", first, second, formatBits(c.Mask))
	}
}

func b2i(b bool) int {
	if b {
		return 1
	}
	return 0
}

func TestTooMuchDataIsRefusedRatherThanTruncated(t *testing.T) {
	if _, err := Encode(bytes.Repeat([]byte("a"), 300)); !errors.Is(err, ErrTooLong) {
		t.Fatalf("300 bytes = %v, want ErrTooLong", err)
	}
}

func TestTheSVGIsSelfContainedAndCarriesTheQuietZone(t *testing.T) {
	c, err := Encode([]byte("hello"))
	if err != nil {
		t.Fatal(err)
	}
	svg := c.SVG("#000", "#fff")
	for _, want := range []string{`viewBox="0 0 29 29"`, `fill="#fff"`, `fill="#000"`, `M4 4h7v1h-7z`} {
		if !strings.Contains(svg, want) {
			t.Errorf("the SVG does not contain %q", want)
		}
	}
	for _, banned := range []string{"<script", "href", "http://example"} {
		if strings.Contains(svg, banned) {
			t.Errorf("the SVG contains %q", banned)
		}
	}
}

// Package redact removes what should not leave this machine from text that is about
// to be sent to a model: credentials, and the email addresses of the people who
// wrote commits.
//
// It is pure and imports only the standard library, so it can be held to what it
// promises by tests that need no controller. It recognises the shapes credentials
// are known to take. It cannot recognise a secret that has no shape, such as a
// password in a sentence, and the documentation says so wherever it is described.
package redact

import (
	"regexp"
	"strings"
)

// Credential and Email are what a redacted span is replaced with. They are words
// a person and a model can both read, so the answer can say something was hidden.
const (
	Credential = "[redacted credential]"
	Email      = "[redacted email]"
)

// rule is one thing to find.
type rule struct {
	re *regexp.Regexp
	// replace is an expansion template over the match's groups, so that the name of
	// a setting can stay readable while its value goes.
	replace string
	// email marks the rule that counts as an email and not a credential.
	email bool
	// keep, when set, is asked about each match and its groups, and a match it says
	// true to is left as it was: a value that is not a secret at all.
	keep func(groups []string) bool
}

// rules run in order. The ones that take a larger span (a private key, an address
// with a password in it, a setting and its value) come before the ones that would
// take a part of it, so that nothing is replaced twice.
var rules = []rule{
	{re: regexp.MustCompile(`(?i)-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?(?:-----END [A-Z ]*PRIVATE KEY-----|$)`), replace: Credential},
	// A password in the address of a repository or a registry.
	{re: regexp.MustCompile(`(?i)\b([a-z][a-z0-9+.-]*://)[^\s/@:]+:[^\s/@]+@`), replace: "${1}" + Credential + "@"},
	// A setting whose name says it is a secret: the name stays and the value goes.
	// The value is a quoted string or a run with no space, at least four characters.
	{
		re:      regexp.MustCompile(`(?i)\b([a-z0-9_.-]*(?:password|passwd|secret|token|api[_-]?key|private[_-]?key|credential)[a-z0-9_.-]*)("?\s*[:=]\s*)("[^"\n]{4,}"|'[^'\n]{4,}'|[^\s"',;&}\])]{4,})`),
		replace: "${1}${2}" + Credential,
		keep:    func(g []string) bool { return notASecret(g[3]) },
	},
	// An Authorization header's value, whatever scheme it carries.
	{re: regexp.MustCompile(`(?i)\b(authorization\s*[:=]\s*)(?:(?:bearer|basic|token)\s+)?[a-z0-9._~+/=-]{16,}`), replace: "${1}" + Credential},
	{re: regexp.MustCompile(`(?i)\b(bearer)\s+[a-z0-9._~+/=-]{20,}`), replace: "${1} " + Credential},
	// GitHub's own prefixes are distinctive enough to need no word boundary, so a token
	// run up against other text is found as well.
	{re: regexp.MustCompile(`(?i)(?:gh[pousr]_[a-z0-9_]{10,}|github_pat_[a-z0-9_]{10,})`), replace: Credential},
	{re: regexp.MustCompile(`(?i)\bsk-(?:proj-|ant-)?[a-z0-9_-]{12,}`), replace: Credential},
	{re: regexp.MustCompile(`\b(?:AKIA|ASIA)[A-Z0-9]{16}\b`), replace: Credential},
	{re: regexp.MustCompile(`\bAIza[0-9A-Za-z_-]{35}\b`), replace: Credential},
	{re: regexp.MustCompile(`\bxox[abprs]-[A-Za-z0-9-]{10,}`), replace: Credential},
	{re: regexp.MustCompile(`\bnpm_[A-Za-z0-9]{36}\b`), replace: Credential},
	{re: regexp.MustCompile(`\beyJ[A-Za-z0-9_-]{8,}\.eyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}`), replace: Credential},
	{re: regexp.MustCompile(`[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}`), replace: Email, email: true},
}

// notASecret is whether the value of a setting called something like "token" is
// plainly not one: a number (a count of tokens is not a token), a flag, a value the
// system has masked or already redacted, or a reference to a secret and not the
// secret itself.
func notASecret(v string) bool {
	v = strings.Trim(v, `"'`)
	lower := strings.ToLower(v)
	switch lower {
	case "true", "false", "null", "none", "nil", "inherit", "required", "optional":
		return true
	}
	if strings.HasPrefix(v, "[redacted") || strings.HasPrefix(v, "***") || strings.HasPrefix(v, "${") ||
		strings.HasPrefix(v, "{{") || strings.HasPrefix(v, "$(") {
		return true
	}
	for _, r := range v {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}

// Result is what was found.
type Result struct {
	// Credentials and Emails are how many of each were replaced.
	Credentials, Emails int
}

// Total is every span that was replaced.
func (r Result) Total() int { return r.Credentials + r.Emails }

// Add is the sum of two results, for a conversation of many texts.
func (r Result) Add(o Result) Result {
	return Result{r.Credentials + o.Credentials, r.Emails + o.Emails}
}

// Text returns s with every span the rules recognise replaced, and how many there
// were of each kind.
func Text(s string) (string, Result) {
	var res Result
	for _, r := range rules {
		n := 0
		s = r.re.ReplaceAllStringFunc(s, func(m string) string {
			groups := r.re.FindStringSubmatch(m)
			if r.keep != nil && r.keep(groups) {
				return m
			}
			n++
			return string(r.re.ExpandString(nil, r.replace, m, r.re.FindStringSubmatchIndex(m)))
		})
		if r.email {
			res.Emails += n
		} else {
			res.Credentials += n
		}
	}
	return s, res
}

// Package registry asks a container registry what a tag points at, without
// pulling a layer. It exists for the generators that pin images by digest: the
// marketplace lock and the runner images' base-image refresh both need the one
// value `docker pull` would pin, and neither should carry its own copy of how
// Docker Hub and GHCR hand it out.
package registry

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"
)

// ManifestTypes is every media type a registry may answer a manifest request
// with. A multi-architecture image is an index and a single-architecture one is
// a manifest, and both spellings of each are still in the wild; asking for only
// one of them gets a 404 that looks like a missing tag.
const ManifestTypes = "application/vnd.oci.image.index.v1+json, " +
	"application/vnd.docker.distribution.manifest.list.v2+json, " +
	"application/vnd.oci.image.manifest.v1+json, " +
	"application/vnd.docker.distribution.manifest.v2+json"

// Resolver resolves image references. The zero value talks to the real
// registries with a client that gives up after thirty seconds.
type Resolver struct {
	// Client is used for every request; nil means a thirty-second default.
	Client *http.Client
	// BaseURL, when set, stands in for the registry and its token service, so a
	// test can answer on a local server. The reference's own host is still read,
	// to choose how the repository path is spelled.
	BaseURL string
}

func (r Resolver) client() *http.Client {
	if r.Client != nil {
		return r.Client
	}
	return &http.Client{Timeout: 30 * time.Second}
}

// Resolve asks the registry what a tag points at, and returns it as
// "sha256:...". GHCR wants a token even for a public repository, and Docker Hub
// does too; both hand one out for the asking. The digest is the header the
// registry answers a manifest request with, which is exactly the value
// `docker pull` would pin.
func (r Resolver) Resolve(ref string) (string, error) {
	host, repo, tag, err := Split(ref)
	if err != nil {
		return "", err
	}
	token, err := r.pullToken(host, repo)
	if err != nil {
		return "", err
	}
	base := "https://" + apiHost(host)
	if r.BaseURL != "" {
		base = strings.TrimRight(r.BaseURL, "/")
	}
	req, err := http.NewRequest(http.MethodHead, base+"/v2/"+repo+"/manifests/"+tag, nil)
	if err != nil {
		return "", err
	}
	req.Header.Set("Authorization", "Bearer "+token)
	req.Header.Set("Accept", ManifestTypes)
	resp, err := r.client().Do(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("the registry answered %s", resp.Status)
	}
	d := resp.Header.Get("Docker-Content-Digest")
	if !strings.HasPrefix(d, "sha256:") {
		return "", fmt.Errorf("the registry returned no digest")
	}
	return d, nil
}

// Split breaks a reference into the registry it lives on, the repository path
// that registry knows it by, and the tag. A digest on the reference is ignored:
// the question is what the tag points at today. Docker Hub is the awkward one:
// its references carry no host at all, official images live under an implied
// library/ prefix, and its API is on a different name from its references.
func Split(ref string) (host, repo, tag string, err error) {
	if i := strings.Index(ref, "@"); i >= 0 {
		ref = ref[:i]
	}
	rest := ref
	host = "docker.io"
	if i := strings.Index(ref, "/"); i >= 0 && strings.Contains(ref[:i], ".") {
		host, rest = ref[:i], ref[i+1:]
	}
	repo, tag, ok := strings.Cut(rest, ":")
	if !ok {
		return "", "", "", fmt.Errorf("%q names no tag", ref)
	}
	if host == "docker.io" && !strings.Contains(repo, "/") {
		repo = "library/" + repo
	}
	return host, repo, tag, nil
}

// apiHost is where the API lives, which is not always where references say the
// image does.
func apiHost(host string) string {
	if host == "docker.io" {
		return "registry-1.docker.io"
	}
	return host
}

// pullToken asks for anonymous pull access. Both registries hand one out for
// the asking on a public repository; neither serves a manifest without it.
func (r Resolver) pullToken(host, repo string) (string, error) {
	authURL := "https://" + host + "/token?scope=repository:" + repo + ":pull&service=" + host
	if host == "docker.io" {
		authURL = "https://auth.docker.io/token?scope=repository:" + repo + ":pull&service=registry.docker.io"
	}
	if r.BaseURL != "" {
		authURL = strings.TrimRight(r.BaseURL, "/") + "/token?scope=repository:" + repo + ":pull&service=" + host
	}
	resp, err := r.client().Get(authURL)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return "", err
	}
	var out struct {
		Token string `json:"token"`
	}
	if err := json.Unmarshal(body, &out); err != nil {
		return "", fmt.Errorf("reading the registry's token: %w", err)
	}
	if out.Token == "" {
		return "", fmt.Errorf("the registry issued no token for %s", repo)
	}
	return out.Token, nil
}

package registry

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func TestSplitReadsEachShapeOfReference(t *testing.T) {
	for _, tc := range []struct{ ref, host, repo, tag string }{
		// Docker Hub's official images have no host and an implied library/.
		{"ubuntu:24.04", "docker.io", "library/ubuntu", "24.04"},
		{"debian:13-slim", "docker.io", "library/debian", "13-slim"},
		// A user or organisation repository on Docker Hub keeps its own path.
		{"rockylinux/rockylinux:9", "docker.io", "rockylinux/rockylinux", "9"},
		{"ghcr.io/eyupio/zoomies:v1.3.0", "ghcr.io", "eyupio/zoomies", "v1.3.0"},
		// A digest already on the reference is not part of the question.
		{"ubuntu:24.04@sha256:" + strings.Repeat("a", 64), "docker.io", "library/ubuntu", "24.04"},
	} {
		host, repo, tag, err := Split(tc.ref)
		if err != nil || host != tc.host || repo != tc.repo || tag != tc.tag {
			t.Errorf("Split(%q) = %q, %q, %q, %v; want %q, %q, %q", tc.ref, host, repo, tag, err, tc.host, tc.repo, tc.tag)
		}
	}
	if _, _, _, err := Split("ubuntu"); err == nil {
		t.Error("a reference with no tag was accepted, and a registry would answer it with a 404 that looks like a missing image")
	}
}

// fakeRegistry answers the two requests Resolve makes: a token, then a manifest
// HEAD that must carry that token and every manifest type.
func fakeRegistry(t *testing.T, digest string, manifestStatus int) *httptest.Server {
	t.Helper()
	mux := http.NewServeMux()
	mux.HandleFunc("/token", func(w http.ResponseWriter, r *http.Request) {
		if got := r.URL.Query().Get("scope"); got != "repository:library/ubuntu:pull" {
			t.Errorf("the token was asked for scope %q", got)
		}
		_, _ = w.Write([]byte(`{"token":"t0k3n"}`))
	})
	mux.HandleFunc("/v2/library/ubuntu/manifests/24.04", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodHead {
			t.Errorf("the manifest was fetched with %s; a HEAD is all that is needed and pulls nothing", r.Method)
		}
		if got := r.Header.Get("Authorization"); got != "Bearer t0k3n" {
			t.Errorf("the manifest request carried %q, not the token", got)
		}
		accept := r.Header.Get("Accept")
		for _, want := range []string{"application/vnd.oci.image.index.v1+json", "application/vnd.docker.distribution.manifest.list.v2+json"} {
			if !strings.Contains(accept, want) {
				t.Errorf("Accept lacks %s, so a multi-architecture image would 404", want)
			}
		}
		if digest != "" {
			w.Header().Set("Docker-Content-Digest", digest)
		}
		w.WriteHeader(manifestStatus)
	})
	srv := httptest.NewServer(mux)
	t.Cleanup(srv.Close)
	return srv
}

func TestResolveReturnsTheDigestTheRegistryNames(t *testing.T) {
	want := "sha256:" + strings.Repeat("c", 64)
	srv := fakeRegistry(t, want, http.StatusOK)
	got, err := Resolver{BaseURL: srv.URL}.Resolve("ubuntu:24.04@sha256:" + strings.Repeat("0", 64))
	if err != nil || got != want {
		t.Errorf("Resolve = %q, %v; want %q", got, err, want)
	}
}

func TestResolveRefusesAnAnswerItCannotPin(t *testing.T) {
	for name, tc := range map[string]struct {
		digest string
		status int
	}{
		"an unknown tag":           {"", http.StatusNotFound},
		"no digest header":         {"", http.StatusOK},
		"a digest of another kind": {"md5:abc", http.StatusOK},
	} {
		srv := fakeRegistry(t, tc.digest, tc.status)
		if got, err := (Resolver{BaseURL: srv.URL}).Resolve("ubuntu:24.04"); err == nil {
			t.Errorf("%s: Resolve returned %q and no error, so a bad answer would be written into a pin", name, got)
		}
	}
}

func TestResolveSaysWhenTheRegistryIssuesNoToken(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_, _ = w.Write([]byte(`{}`))
	}))
	defer srv.Close()
	if _, err := (Resolver{BaseURL: srv.URL}).Resolve("ubuntu:24.04"); err == nil || !strings.Contains(err.Error(), "token") {
		t.Errorf("Resolve with no token gave %v; it should name the token", err)
	}
}

package releasekey

// Default is the release key set compiled into the binary: one base64 public
// key per line, so more than one is carried while a key is rotated. It is what
// `zoomies upgrade` and `zoomies release verify` hold a release's signature to.
//
// It is empty until the owner mints a key and commits the public half (docs/
// upgrading.md, "Signing releases"). An empty set means a download is not held
// to a signature, which the download says once. Set it to the line
// `zoomies release keygen --out DIR` wrote to release.pub; keep more than one
// line only for the releases of a rotation.
// It is a variable rather than a constant so a test can set it and put it
// back; nothing else writes it.
var Default = "6dK2/jDPHR8wAjsIayrxGxL8ednKVKdEMHdRcmNU67U="

// Package releasekey is the release signing key: Ed25519, from the standard
// library, so a release can be held to a signature with no external tool and
// no network beyond the release itself.
//
// It is what lets `zoomies upgrade` and an installer refuse a download that is
// not the project's. The checksums file says a download was not corrupted on
// the way; it travels with the binary, so on its own it says nothing about who
// made either. A detached signature over the checksums, checked against a key
// compiled into the running binary, says the release is the project's.
package releasekey

import (
	"crypto/ed25519"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"
	"sort"
	"strings"
)

// SigSuffix is the asset that carries the detached signature over a release's
// checksums.txt, as the release workflow names it.
const SigSuffix = ".ed25519"

// PublicKey is an Ed25519 public key with the id a signature names it by.
type PublicKey struct {
	ID  string
	key ed25519.PublicKey
}

// String is the key in the base64 form the key file holds.
func (k PublicKey) String() string { return base64.StdEncoding.EncodeToString(k.key) }

// ParsePublic reads a base64 Ed25519 public key and derives its id.
func ParsePublic(s string) (PublicKey, error) {
	raw, err := base64.StdEncoding.DecodeString(strings.TrimSpace(s))
	if err != nil {
		return PublicKey{}, fmt.Errorf("the release key is not base64: %w", err)
	}
	if len(raw) != ed25519.PublicKeySize {
		return PublicKey{}, fmt.Errorf("the release key is %d bytes, want %d", len(raw), ed25519.PublicKeySize)
	}
	key := ed25519.PublicKey(raw)
	return PublicKey{ID: keyID(key), key: key}, nil
}

// ParsePrivate reads a base64 Ed25519 private key: the 32-byte seed or the
// 64-byte key, so a key written by any of the usual tools is accepted.
func ParsePrivate(s string) (ed25519.PrivateKey, error) {
	raw, err := base64.StdEncoding.DecodeString(strings.TrimSpace(s))
	if err != nil {
		return nil, fmt.Errorf("the private key is not base64: %w", err)
	}
	switch len(raw) {
	case ed25519.SeedSize:
		return ed25519.NewKeyFromSeed(raw), nil
	case ed25519.PrivateKeySize:
		return ed25519.PrivateKey(raw), nil
	}
	return nil, fmt.Errorf("the private key is %d bytes, want %d or %d", len(raw), ed25519.SeedSize, ed25519.PrivateKeySize)
}

// Generate mints a key pair, each in the base64 form the key files hold. The
// private half is a credential: it is stored as a release secret and never
// committed.
func Generate() (public, private string, err error) {
	pub, priv, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		return "", "", err
	}
	return base64.StdEncoding.EncodeToString(pub), base64.StdEncoding.EncodeToString(priv), nil
}

// Sign returns the envelope written beside a release's checksums.txt: the
// signing key's id and the detached signature over msg, so a verifier holding
// several keys knows which one to trust.
func Sign(private string, msg []byte) ([]byte, error) {
	priv, err := ParsePrivate(private)
	if err != nil {
		return nil, err
	}
	pub, ok := priv.Public().(ed25519.PublicKey)
	if !ok {
		return nil, errors.New("the private key has no public half")
	}
	return Encode(keyID(pub), ed25519.Sign(priv, msg)), nil
}

// Encode is the envelope's text: the key id, then the base64 signature.
func Encode(id string, sig []byte) []byte {
	return []byte("key:" + id + "\n" + base64.StdEncoding.EncodeToString(sig) + "\n")
}

func decodeEnvelope(body []byte) (id string, sig []byte, err error) {
	lines := strings.Split(strings.TrimSpace(string(body)), "\n")
	if len(lines) != 2 || !strings.HasPrefix(lines[0], "key:") {
		return "", nil, errors.New("the signature is not a release signature")
	}
	id = strings.TrimSpace(strings.TrimPrefix(lines[0], "key:"))
	if id == "" {
		return "", nil, errors.New("the signature names no key")
	}
	sig, err = base64.StdEncoding.DecodeString(strings.TrimSpace(lines[1]))
	if err != nil {
		return "", nil, fmt.Errorf("the signature is not base64: %w", err)
	}
	return id, sig, nil
}

// Verify holds a detached signature over msg to the keys in set, one base64
// public key per line. It refuses a key id the set does not hold, which is a
// release signed by a key this build does not trust, and a signature that does
// not verify.
func Verify(set string, msg, envelope []byte) error {
	id, sig, err := decodeEnvelope(envelope)
	if err != nil {
		return err
	}
	keys, err := parseSet(set)
	if err != nil {
		return err
	}
	key, ok := keys[id]
	if !ok {
		return fmt.Errorf("the release is signed with key %s, which this build does not trust; it may be signed by a newer key, so upgrade over a release this build accepts", id)
	}
	if !ed25519.Verify(key, msg, sig) {
		return fmt.Errorf("the signature does not match the checksums under key %s", id)
	}
	return nil
}

// IDs returns the ids of the keys in a set, one base64 public key per line, in
// a stable order. An empty set is no keys, which means downloads are not held
// to a signature. It is what a page shows to say which keys this build trusts,
// and it never returns the keys themselves.
func IDs(set string) []string {
	keys, err := parseSet(set)
	if err != nil {
		return nil
	}
	ids := make([]string, 0, len(keys))
	for id := range keys {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	return ids
}

// keyID names a public key by the first eight bytes of its SHA-256, short
// enough for a signature file and long enough not to be guessed.
func keyID(key ed25519.PublicKey) string {
	sum := sha256.Sum256(key)
	return hex.EncodeToString(sum[:8])
}

func parseSet(set string) (map[string]ed25519.PublicKey, error) {
	out := map[string]ed25519.PublicKey{}
	for _, line := range strings.Split(set, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		pub, err := ParsePublic(line)
		if err != nil {
			return nil, err
		}
		out[pub.ID] = pub.key
	}
	return out, nil
}

package releasekey

import (
	"encoding/base64"
	"slices"
	"strings"
	"testing"
)

func TestASignatureVerifiesUnderTheKeyThatSignedIt(t *testing.T) {
	pub, priv, err := Generate()
	if err != nil {
		t.Fatal(err)
	}
	msg := []byte("deadbeef00  zoomies_linux_amd64\n")
	envelope, err := Sign(priv, msg)
	if err != nil {
		t.Fatal(err)
	}
	if err := Verify(pub, msg, envelope); err != nil {
		t.Fatalf("a signature made with the key did not verify: %v", err)
	}
}

// The checksums are what the binary is held to, so a changed checksums file
// must not verify even with a real signature over the original.
func TestATamperedChecksumsFileDoesNotVerify(t *testing.T) {
	pub, priv, _ := Generate()
	envelope, _ := Sign(priv, []byte("good"))
	if err := Verify(pub, []byte("tampered"), envelope); err == nil {
		t.Fatal("a changed checksums file verified")
	}
}

func TestAKeyTheSetDoesNotHoldIsRefused(t *testing.T) {
	other, _, _ := Generate()
	_, priv, _ := Generate()
	envelope, _ := Sign(priv, []byte("msg"))
	err := Verify(other, []byte("msg"), envelope)
	if err == nil || !strings.Contains(err.Error(), "does not trust") {
		t.Fatalf("err = %v", err)
	}
}

// A key is rotated by carrying both for a release: a build with both accepts
// either, and a build with only the old one refuses the new, which is the
// order the rotation relies on.
func TestARotatedKeyVerifiesWhileBothAreCarried(t *testing.T) {
	oldPub, oldPriv, _ := Generate()
	newPub, newPriv, _ := Generate()
	set := oldPub + "\n# the new key\n" + newPub
	oldEnvelope, _ := Sign(oldPriv, []byte("m"))
	if err := Verify(set, []byte("m"), oldEnvelope); err != nil {
		t.Fatalf("the old key under a set with both: %v", err)
	}
	newEnvelope, _ := Sign(newPriv, []byte("m"))
	if err := Verify(set, []byte("m"), newEnvelope); err != nil {
		t.Fatalf("the new key under a set with both: %v", err)
	}
	if err := Verify(oldPub, []byte("m"), newEnvelope); err == nil {
		t.Fatal("a build carrying only the old key accepted the new key")
	}
}

func TestMalformedKeysAndSignaturesAreRefused(t *testing.T) {
	if _, err := ParsePublic("not base64!"); err == nil {
		t.Fatal("a non-base64 public key was accepted")
	}
	if _, err := ParsePublic(base64.StdEncoding.EncodeToString([]byte("short"))); err == nil {
		t.Fatal("a public key of the wrong length was accepted")
	}
	if _, err := ParsePrivate("not base64!"); err == nil {
		t.Fatal("a non-base64 private key was accepted")
	}
	if _, err := Sign(base64.StdEncoding.EncodeToString([]byte("short")), []byte("m")); err == nil {
		t.Fatal("a private key of the wrong length was accepted")
	}
	if err := Verify("also not base64!", []byte("m"), Encode("id", []byte("sig"))); err == nil {
		t.Fatal("a malformed key set was accepted")
	}
	if err := Verify("", []byte("m"), []byte("not a signature")); err == nil {
		t.Fatal("a malformed envelope was accepted")
	}
	if err := Verify("", []byte("m"), Encode("", []byte("sig"))); err == nil {
		t.Fatal("an envelope naming no key was accepted")
	}
}

func TestIDsNamesTheKeysInASet(t *testing.T) {
	if got := IDs(""); len(got) != 0 {
		t.Fatalf("an empty set gave %v, want none", got)
	}
	a, _, _ := Generate()
	b, _, _ := Generate()
	ids := IDs(a + "\n# a comment\n" + b)
	if len(ids) != 2 {
		t.Fatalf("ids = %v, want two", ids)
	}
	pa, _ := ParsePublic(a)
	pb, _ := ParsePublic(b)
	if !slices.Contains(ids, pa.ID) || !slices.Contains(ids, pb.ID) {
		t.Fatalf("ids = %v, want %s and %s", ids, pa.ID, pb.ID)
	}
}

func TestTheKeyIDIsStable(t *testing.T) {
	pub, _, _ := Generate()
	parsed, err := ParsePublic(pub)
	if err != nil {
		t.Fatal(err)
	}
	if parsed.ID == "" || len(parsed.ID) != 16 {
		t.Fatalf("id = %q, want 16 hex characters", parsed.ID)
	}
	again, _ := ParsePublic(pub)
	if again.ID != parsed.ID {
		t.Fatalf("id changed between parses: %q then %q", parsed.ID, again.ID)
	}
}

package scheduler

import (
	"fmt"
	"sort"
	"strings"
	"unicode"
	"unicode/utf8"

	"github.com/eyupio/zoomies/internal/store"
)

// The three things label advice says about a job's runs-on. They are ordered by
// how much it costs to leave them: a job asking for too little is killed, a job
// that is only routed best effort may land on a host too small for it, and a job
// asking for too much only occupies a bigger machine than it needs.
const (
	// AdviceTooSmall: the job asks for a class by name and its runs call for a
	// larger one. The label is a guarantee, so the job can only ever run on hosts
	// that are too small for it, and is killed when it needs more than they have.
	AdviceTooSmall = "too_small"
	// AdviceUnguaranteed: the job asks only for the base label and its runs call
	// for a class above the default one. It is routed there while there is room,
	// which is best effort -- GitHub decides which waiting job a runner takes --
	// so it can land on a smaller host; naming the class makes it a guarantee.
	AdviceUnguaranteed = "unguaranteed"
	// AdviceTooLarge: the job asks for a class by name and its runs would fit a
	// smaller one, so it occupies a host another job needs.
	AdviceTooLarge = "too_large"
)

// AdviceMinRuns is how many measured runs a job needs before anything is said
// about its labels. A class worked out from one run is a guess, and advice to
// rewrite a workflow is not something to put on the strength of one.
const AdviceMinRuns = 5

// The states an advice row can be in. A job with too few runs used to be left
// out of the list, and an agent asking why a job had no advice could not tell
// "nothing to say" from "not enough known yet"; now it is a row that says so.
const (
	AdviceStateOK            = "ok"
	AdviceStateNotEnoughData = "not_enough_data"
)

// Advice is one thing to change in one job's runs-on, and why, with the figures
// it rests on beside it.
type Advice struct {
	Repo     string `json:"repo"`
	Workflow string `json:"workflow"`
	JobName  string `json:"job_name"`
	// Kind is what is wrong, empty for a row with too few runs to say.
	Kind string `json:"kind"`
	// State is ok, or not_enough_data for a job the fleet has measured fewer
	// than MinRuns runs of. MinRuns travels with the row so a client prints
	// "N of 5" from the payload and never from a literal of its own.
	State   string `json:"state"`
	MinRuns int    `json:"min_runs"`
	// Asked is the class the job names in its runs-on, empty when it names none,
	// and Class the class its runs call for.
	Asked store.SizeClass `json:"asked,omitempty"`
	Class store.SizeClass `json:"class"`
	// RecommendedClass is Class under the name the spec gives it, and Reason
	// is the class rule's own sentence for it, so a row says what it would have
	// a workflow write and why without a second request.
	RecommendedClass store.SizeClass `json:"recommended_class"`
	Reason           string          `json:"reason"`
	// Runs is how many measured runs the class was worked out from.
	Runs int `json:"runs"`
	// Labels is the runs-on the job had on its latest measured run.
	Labels []string `json:"labels"`
	// Message says what is wrong, and Fix what to write instead.
	Message string `json:"message"`
	Fix     string `json:"fix"`
	// Observed and Fits are filled by whoever has the runs and the hosts:
	// the figures behind the row, and whether any host carries the class.
	Observed *Observed `json:"observed,omitempty"`
	Fits     *Fit      `json:"fits,omitempty"`
}

// Fit says whether the fleet has a host of the recommended class at all, and
// names the class when none does. Whether such a host is free, cordoned or
// quiet is the fleet's state of the moment, not the fit.
type Fit struct {
	OK      bool            `json:"ok"`
	Missing store.SizeClass `json:"missing,omitempty"`
}

// LabelAdvice says what, if anything, a job's workflow should change in its
// runs-on, given the class kept from the job's runs and what its latest measured
// run asked for.
//
// It says nothing about a job an operator has pinned, because the pin is a
// decision that takes the place of the measurements; about a job that asks for
// something this fleet's automatic pools do not answer, because advice to add a
// class label to it would send it away from the pool that carries its own; or
// A job with too few runs to be worked out from is a row of its own that
// says how many it has, so "no advice" is never mistaken for "nothing to say".
func (c SizeConfig) LabelAdvice(k *store.JobClassAsked, pins []*store.SizePin) *Advice {
	if k == nil || !k.Class.Valid() || k.Basis != store.SizeBasisHistory || len(k.Labels) == 0 {
		return nil
	}
	for _, p := range pins {
		if p.Repo == lowerRepo(k.Repo) && (p.ForRepository() || (p.Workflow == k.Workflow && p.JobName == k.JobName)) {
			return nil
		}
	}
	out := &Advice{Repo: k.Repo, Workflow: k.Workflow, JobName: k.JobName, State: AdviceStateOK, MinRuns: AdviceMinRuns,
		Class: k.Class, RecommendedClass: k.Class, Reason: k.Reason, Runs: k.Runs, Labels: append([]string(nil), k.Labels...)}
	if k.Runs < AdviceMinRuns {
		out.State = AdviceStateNotEnoughData
		out.Message = fmt.Sprintf("%d of %d measured runs so far; advice needs %d.", k.Runs, AdviceMinRuns, AdviceMinRuns)
		return out
	}
	asked, named := RequestedClass(k.Labels)
	switch {
	case named && k.Class.Rank() > asked.Rank():
		out.Kind, out.Asked = AdviceTooSmall, asked
		out.Message = fmt.Sprintf("its runs-on asks for %s, which only a %s host answers, and its runs call for %s: %s.",
			asked.Label(), asked, k.Class, k.Reason)
		out.Fix = fmt.Sprintf("write %s in runs-on in place of %s. Left as it is, the job can only run on hosts smaller than it needs, and is killed when it uses more than they have.",
			k.Class.Label(), asked.Label())
	case named && k.Class.Rank() < asked.Rank():
		out.Kind, out.Asked = AdviceTooLarge, asked
		out.Message = fmt.Sprintf("its runs-on asks for %s, and its runs would fit a %s runner: %s.",
			asked.Label(), k.Class, k.Reason)
		out.Fix = fmt.Sprintf("write %s in runs-on in place of %s to leave the larger hosts to jobs that need them, unless the job needs the host for something that is not measured, such as its disk or its network.",
			k.Class.Label(), asked.Label())
	case !named && baseLabelsOnly(k.Labels) && k.Class.Rank() > c.defaultClass().Rank():
		out.Kind = AdviceUnguaranteed
		out.Message = fmt.Sprintf("its runs-on asks only for %s, so it is sent to %s while there is room, which is best effort and not a promise: GitHub decides which waiting job a runner takes, so it can land on a smaller host. %s.",
			store.BrandLabel, k.Class, capitalise(k.Reason))
		out.Fix = fmt.Sprintf("add %s to runs-on, beside %s, to make it a guarantee.", k.Class.Label(), store.BrandLabel)
	default:
		return nil
	}
	return out
}

// baseLabelsOnly reports whether a job asks for nothing but what every runner
// carries and the brand label. A job that names another label asks for a pool of
// somebody's own, which the automatic pools do not answer.
func baseLabelsOnly(labels []string) bool {
	for _, l := range store.NormalizeLabels(labels) {
		if !store.ImplicitLabels[l] && l != store.BrandLabel {
			return false
		}
	}
	return true
}

// lowerRepo is a repository as a pin stores it, which is how GitHub compares one.
func lowerRepo(r string) string { return strings.ToLower(strings.TrimSpace(r)) }

// capitalise starts a clause that was written to follow "because" as a sentence.
func capitalise(s string) string {
	r, n := utf8.DecodeRuneInString(s)
	if n == 0 {
		return s
	}
	return string(unicode.ToUpper(r)) + s[n:]
}

// SortAdvice puts the advice that costs most to leave first, the rows with too
// few runs to say anything last, and orders each by repository, workflow and
// job, so a page of it is stable between reads.
func SortAdvice(in []*Advice) {
	rank := map[string]int{AdviceTooSmall: 0, AdviceUnguaranteed: 1, AdviceTooLarge: 2, "": 3}
	sort.SliceStable(in, func(i, j int) bool {
		a, b := in[i], in[j]
		if rank[a.Kind] != rank[b.Kind] {
			return rank[a.Kind] < rank[b.Kind]
		}
		if a.Repo != b.Repo {
			return a.Repo < b.Repo
		}
		if a.Workflow != b.Workflow {
			return a.Workflow < b.Workflow
		}
		return a.JobName < b.JobName
	})
}

package scheduler

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

func kept(class store.SizeClass, runs int, labels ...string) *store.JobClassAsked {
	return &store.JobClassAsked{
		JobClass: store.JobClass{Repo: "Acme/Widgets", Workflow: "CI", JobName: "build", Class: class,
			Basis: store.SizeBasisHistory, Runs: runs,
			Reason: "its memory needs about 6.2 GB (the 90th percentile of 12 runs, with a fifth added), which a " + string(class) + " runner holds"},
		Labels: labels,
	}
}

func TestLabelAdviceSaysWhatAWorkflowShouldWriteInstead(t *testing.T) {
	cfg := DefaultSizeConfig()
	cases := []struct {
		name     string
		in       *store.JobClassAsked
		pins     []*store.SizePin
		wantKind string
		// wantInFix is what the fix has to tell the author to write.
		wantInFix string
	}{
		{"asks for less than its runs need", kept(store.SizeLarge, 12, "self-hosted", "zoomies-medium"), nil,
			AdviceTooSmall, "write zoomies-large in runs-on in place of zoomies-medium"},
		{"asks for more than its runs need", kept(store.SizeSmall, 12, "self-hosted", "zoomies-large"), nil,
			AdviceTooLarge, "write zoomies-small in runs-on in place of zoomies-large"},
		{"asks for nothing and needs more than the default", kept(store.SizeLarge, 12, "self-hosted", "linux", "x64", "zoomies"), nil,
			AdviceUnguaranteed, "add zoomies-large to runs-on"},
		{"asks for the class its runs call for", kept(store.SizeLarge, 12, "self-hosted", "zoomies-large"), nil, "", ""},
		{"asks for nothing and the default is right", kept(store.SizeMedium, 12, "self-hosted", "zoomies"), nil, "", ""},
		// Landing on a larger host than the default is the harmless direction: the
		// job is not killed and the labels need not be touched.
		{"asks for nothing and needs less than the default", kept(store.SizeSmall, 12, "self-hosted", "zoomies"), nil, "", ""},
		{"nothing was recorded about what it asks for", kept(store.SizeLarge, 12), nil, "", ""},
		// A job that asks for a pool of somebody's own is not asking for the
		// automatic ones, and adding a class label to it would send it away from
		// the pool that carries the label it needs.
		{"asks for a pool of its own", kept(store.SizeLarge, 12, "self-hosted", "zoomies", "gpu"), nil, "", ""},
		{"asks for a pool of its own by a class label too", kept(store.SizeLarge, 12, "self-hosted", "gpu", "zoomies-medium"), nil,
			AdviceTooSmall, "write zoomies-large in runs-on in place of zoomies-medium"},
		{"pinned in its repository", kept(store.SizeLarge, 12, "self-hosted", "zoomies-medium"),
			[]*store.SizePin{{Repo: "acme/widgets", Class: store.SizeMedium}}, "", ""},
		{"pinned itself", kept(store.SizeLarge, 12, "self-hosted", "zoomies-medium"),
			[]*store.SizePin{{Repo: "acme/widgets", Workflow: "CI", JobName: "build", Class: store.SizeMedium}}, "", ""},
		{"another job pinned", kept(store.SizeLarge, 12, "self-hosted", "zoomies-medium"),
			[]*store.SizePin{{Repo: "acme/widgets", Workflow: "CI", JobName: "test", Class: store.SizeMedium}},
			AdviceTooSmall, "zoomies-large"},
		{"another repository pinned", kept(store.SizeLarge, 12, "self-hosted", "zoomies-medium"),
			[]*store.SizePin{{Repo: "acme/other", Class: store.SizeMedium}}, AdviceTooSmall, "zoomies-large"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := cfg.LabelAdvice(tc.in, tc.pins)
			if tc.wantKind == "" {
				if got != nil {
					t.Fatalf("advice was given where none was due: %+v", got)
				}
				return
			}
			if got == nil || got.Kind != tc.wantKind {
				t.Fatalf("advice = %+v, want kind %s", got, tc.wantKind)
			}
			if !strings.Contains(got.Fix, tc.wantInFix) {
				t.Fatalf("the fix is %q, want it to say %q", got.Fix, tc.wantInFix)
			}
			if got.Class != tc.in.Class || got.Runs != tc.in.Runs || got.Repo != tc.in.Repo || len(got.Labels) != len(tc.in.Labels) {
				t.Fatalf("the advice does not carry the job: %+v", got)
			}
			if got.State != AdviceStateOK || got.MinRuns != AdviceMinRuns || got.RecommendedClass != tc.in.Class || got.Reason != tc.in.Reason {
				t.Fatalf("the advice does not say what it rests on: %+v", got)
			}
			if !strings.HasSuffix(got.Message, ".") || !strings.HasSuffix(got.Fix, ".") {
				t.Fatalf("the sentences should end: %q / %q", got.Message, got.Fix)
			}
		})
	}
}

// The advice for a job that only asks for the brand label has to say why it is
// advice at all: the routing it gets is not a promise.
func TestTheUnguaranteedAdviceSaysWhyBestEffortIsNotEnough(t *testing.T) {
	got := DefaultSizeConfig().LabelAdvice(kept(store.SizeLarge, 12, "self-hosted", "zoomies"), nil)
	if got == nil || got.Asked != "" {
		t.Fatalf("advice = %+v", got)
	}
	for _, want := range []string{"asks only for zoomies", "best effort", "GitHub decides which waiting job a runner takes", "Its memory needs about 6.2 GB"} {
		if !strings.Contains(got.Message, want) {
			t.Errorf("the message %q does not say %q", got.Message, want)
		}
	}
}

func TestAdviceOnlyFollowsMeasuredHistory(t *testing.T) {
	cfg := DefaultSizeConfig()
	in := kept(store.SizeLarge, 12, "self-hosted", "zoomies-medium")
	in.Basis = store.SizeBasisDefault
	if got := cfg.LabelAdvice(in, nil); got != nil {
		t.Fatalf("advice from a class that was not worked out from runs: %+v", got)
	}
	if got := cfg.LabelAdvice(nil, nil); got != nil {
		t.Fatalf("advice from nothing: %+v", got)
	}
	in.Basis, in.Class = store.SizeBasisHistory, "huge"
	if got := cfg.LabelAdvice(in, nil); got != nil {
		t.Fatalf("advice from a class that is not one: %+v", got)
	}
}

func TestAdviceIsOrderedByWhatItCostsToLeaveIt(t *testing.T) {
	in := []*Advice{
		{Repo: "b/b", Workflow: "CI", JobName: "x", Kind: AdviceTooLarge},
		{Repo: "b/b", Workflow: "CI", JobName: "a", Kind: AdviceTooSmall},
		{Repo: "a/a", Workflow: "CI", JobName: "z", Kind: AdviceUnguaranteed},
		{Repo: "a/a", Workflow: "CI", JobName: "b", Kind: AdviceTooSmall},
		{Repo: "a/a", Workflow: "CI", JobName: "a", Kind: AdviceTooSmall},
	}
	SortAdvice(in)
	var got []string
	for _, a := range in {
		got = append(got, a.Kind+":"+a.Repo+":"+a.JobName)
	}
	want := []string{
		"too_small:a/a:a", "too_small:a/a:b", "too_small:b/b:a", "unguaranteed:a/a:z", "too_large:b/b:x",
	}
	if strings.Join(got, " ") != strings.Join(want, " ") {
		t.Fatalf("order = %v, want %v", got, want)
	}
}

// Too few runs is a row, not an absence: an agent asking why a job has no
// advice is told how far it is from having some, and the boundary is the
// named constant on both sides.
func TestTooFewRunsIsARowThatSaysSo(t *testing.T) {
	cfg := DefaultSizeConfig()
	got := cfg.LabelAdvice(kept(store.SizeLarge, AdviceMinRuns-1, "self-hosted", "zoomies-medium"), nil)
	if got == nil || got.State != AdviceStateNotEnoughData || got.Kind != "" {
		t.Fatalf("advice = %+v, want a not_enough_data row with no kind", got)
	}
	if got.Runs != AdviceMinRuns-1 || got.MinRuns != AdviceMinRuns || got.RecommendedClass != store.SizeLarge || got.Reason == "" {
		t.Fatalf("the row does not carry the count and the class: %+v", got)
	}
	if !strings.Contains(got.Message, "4 of 5 measured runs") || got.Fix != "" {
		t.Fatalf("message = %q, fix = %q", got.Message, got.Fix)
	}
	if at := cfg.LabelAdvice(kept(store.SizeLarge, AdviceMinRuns, "self-hosted", "zoomies-medium"), nil); at == nil || at.State != AdviceStateOK {
		t.Fatalf("at the minimum the advice is given: %+v", at)
	}
	// A job that asks for exactly what it is heading for has nothing to be
	// told, even once; it is the sparse row's kind that is empty, not its advice.
	if right := cfg.LabelAdvice(kept(store.SizeLarge, AdviceMinRuns-1, "self-hosted", "zoomies-large"), nil); right == nil || right.State != AdviceStateNotEnoughData {
		t.Fatalf("a sparse job is a sparse row whatever it asks for: %+v", right)
	}
}

func TestSparseRowsSortLast(t *testing.T) {
	in := []*Advice{
		{Repo: "a/a", JobName: "sparse", State: AdviceStateNotEnoughData},
		{Repo: "b/b", JobName: "x", Kind: AdviceTooLarge, State: AdviceStateOK},
	}
	SortAdvice(in)
	if in[0].JobName != "x" || in[1].JobName != "sparse" {
		t.Fatalf("order = %s, %s", in[0].JobName, in[1].JobName)
	}
}

package scheduler

import (
	"math"

	"github.com/eyupio/zoomies/internal/store"
)

// Allocation is what one runner of p is limited to when it is created on h,
// and where those limits came from.
//
// It is the enforcement half of the resource model, and it closes the gap the
// charge left open. Reserve charges a pool that sets no limit one slot's share
// of the host, so the books balance -- and until now the runner itself was
// given no limit at all, so the books balanced while eight runners each took
// every core on the machine. A pool's own limits win where it set them; where
// it did not, the runner is given exactly what it was charged, as a cgroup
// limit the container backends apply.
//
// It is per field, as Reserve is, and for the same reason: a pool that sets
// memory and leaves CPU alone has said something about memory and nothing
// about CPU. Disk and the pids limit pass through untouched -- disk has no
// share to give (it is a measurement, not a budget) and a pids limit is not a
// thing the machine's size says anything about.
//
// A docker-in-docker runner's sidecar is given what this function hands back
// as spec.Resources, and what that is depends on where the figure came from.
// A limit an operator typed is given to both containers in full -- the build
// runs in the daemon, so it needs the same figure the runner was promised --
// and Reserve charges the host for both. A defaulted figure is one slot's
// share, and store.Resources.SplitWithDaemon divides it between the pair
// before either container is created, because a slot is one runner however
// many containers it takes to run it; Reserve charges one share to match.
//
// A slot too small to give both halves what a runner needs is refused rather
// than divided -- see ShareFloor -- because handing the daemon whatever is
// left over is no limit at all, which is how one build takes the machine.
//
// A default is only given where it would bind. The process backend applies no
// limit at all, so a defaulted figure on one of its runners would be a number
// on the Runners page saying the opposite of the truth. And a daemon that
// cannot apply a CPU quota -- rootless Docker on a host that delegates only
// memory and pids to the user -- refuses the container rather than ignoring
// the request, so a default sent there would fail every create on the host.
// The host's own probe says what its daemon can do, and a probe from an agent
// too old to say is read as "nothing", which is what every host did before.
//
// An automatic pool with a minimum above the slot share is given the minimum
// instead -- see MinimumSlot -- because a share smaller than the least the
// operator said a runner may have is a runner set up to be killed.
//
// A pool that takes its size from the host is given that host's standard size
// where an automatic pool is given the share -- the profile's, or the fleet's
// default where the host's names none -- and its source is "profile", so the
// runner's row says where the size came from. The host's minimum applies first
// (sizedOn), the same as to every other sum here.
//
// With defaults off the pool's limits are the whole answer, which is what
// every fleet had before this existed.
func Allocation(p *store.Pool, h *store.Host, defaults bool) (store.Resources, string) {
	res := p.Resources
	source := ""
	if res.CPUs > 0 || res.MemoryMB > 0 {
		source = store.AllocationFromPool
	}
	if !defaults || h == nil || p.Backend == store.BackendProcess {
		return res, source
	}
	p = sizedOn(p, h)
	info, _ := h.BackendInfo.Find(p.Backend)
	limits := hostLimits(h, p.Backend)
	alloc := h.Allocatable()
	def := slotSize(p, h)
	standardCPUs, standardMemoryMB := StandardSize(p, h)
	// A share under the pool's minimum is raised to it, which is what Reserve
	// charges: the minimum is the least a runner is given, never the most.
	floor := MinimumSlot(p)
	def.CPUs = max(def.CPUs, floor.CPUs)
	def.MemoryMB = max(def.MemoryMB, floor.MemoryMB)
	if res.CPUs <= 0 && alloc.CPUsKnown && limits.CPU && def.CPUs > 0 {
		// The share is a request to the daemon, and a daemon refuses a quota
		// above its own core count whatever the agent's machine has: a
		// Docker Desktop VM on a ten-core laptop has four. The host is sized
		// by its daemon, so this is a belt on braces, for a row whose size
		// and probe disagree.
		if info.CPUs > 0 && def.CPUs > float64(info.CPUs) {
			def.CPUs = float64(info.CPUs)
		}
		res.CPUs = def.CPUs
		source = hostSource(standardCPUs > 0, source)
	}
	if res.MemoryMB <= 0 && alloc.MemoryKnown && limits.Memory && def.MemoryMB > 0 {
		res.MemoryMB = def.MemoryMB
		source = hostSource(standardMemoryMB > 0, source)
	}
	return res, source
}

// hostSource is the source of a field the host decided: "profile" where its
// runner profile (or the fleet's default standing in for it) named the figure,
// and "host" where it is a slot's share. A runner that has any field from the
// profile is a profile runner, whatever the other field was.
func hostSource(fromProfile bool, current string) string {
	if fromProfile || current == store.AllocationFromProfile {
		return store.AllocationFromProfile
	}
	return store.AllocationFromHost
}

// HostShare is one slot's share of a host: the CPU and memory a runner of a
// pool that sets neither is given by Allocation, before the host's daemon is
// asked whether it can apply them. Zero on a field the host has not measured.
//
// It is exported so that the problem which warns about an over-provisioned
// host can say what each runner's default share would be in the same figures
// Allocation hands out, rather than in a second sum that could drift from it.
func HostShare(h *store.Host) store.Resources {
	if h == nil {
		return store.Resources{}
	}
	alloc := h.Allocatable()
	var out store.Resources
	if alloc.CPUsKnown {
		out.CPUs = shareCPUs(alloc.CPUs, h.Slots())
	}
	if alloc.MemoryKnown {
		out.MemoryMB = int64(share(float64(alloc.MemoryMB), h.Slots()))
	}
	return out
}

// DefaultsBind reports which default limits would bind on this host at all:
// whether any available container backend on it has said it can apply a CPU
// quota, and a memory limit. It is what a problem about the host asks before
// it names "each runner's default share", because on a host offering only
// the process backend, or one whose daemon cannot apply the limit, or one
// whose agent has not said, the share is never given and a sentence naming
// it would say the opposite of the truth.
func DefaultsBind(h *store.Host) (cpu, memory bool) {
	for _, info := range h.BackendInfo {
		if !info.Available || info.Kind == store.BackendProcess || !info.Limits.Known {
			continue
		}
		cpu = cpu || info.Limits.CPU
		memory = memory || info.Limits.Memory
	}
	return cpu, memory
}

// hostLimits is what the host's daemon for this backend said it can enforce.
// Unknown is every field false, which defaults nothing.
func hostLimits(h *store.Host, kind store.BackendKind) store.LimitSupport {
	info, ok := h.BackendInfo.Find(kind)
	if !ok || !info.Limits.Known {
		return store.LimitSupport{}
	}
	return info.Limits
}

// shareCPUs is one slot's worth of CPU, floored to the hundredth the pool
// form takes limits in. Floored rather than rounded: three runners rounded
// up from 0.667 to 0.67 would together be promised a hundredth of a core the
// host does not have, and the daemon refuses a quota above the machine.
func shareCPUs(total float64, capacity int) float64 {
	return math.Floor(share(total, capacity)*100) / 100
}

package scheduler

import (
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// A pool that sets no limit used to get a runner with no limit, charged one
// slot's share of the host it never had to honour. Eight such runners on an
// eight-slot host each took every core, and that is the overload this exists
// to end: the runner is given exactly what it was charged.
func TestAnUnlimitedPoolIsGivenOneSlotsShareOfItsHost(t *testing.T) {
	// 16 CPUs less the floor's 0.8 is 15.2, and 32 GB less the memory floor's
	// twentieth (1638 MB) is 31130 MB; four slots share both.
	h := sized("host_a", 4, 16, 32*1024, 500*1024)
	p := limited("builders", 0, 0)

	got, source := Allocation(p, h, true)
	if got.CPUs != 3.8 || got.MemoryMB != 7782 {
		t.Fatalf("allocation = %+v, want 3.8 CPUs and 7782 MB, one slot's share of the host", got)
	}
	if source != store.AllocationFromHost {
		t.Errorf("source = %q, want %q", source, store.AllocationFromHost)
	}
	// The charge and the allocation are the same figure, which is what makes
	// the books honest: what a host promises away is what its runners can
	// actually take.
	if charge := Reserve(p, h); charge.CPUs < got.CPUs || charge.MemoryMB != got.MemoryMB {
		t.Errorf("Reserve = %+v differs from the allocation %+v", charge, got)
	}
}

// Per field, as the charge is. A pool that set memory has said something about
// memory and nothing about CPU, so the pool answers for one and the host for
// the other -- and the source says the host had a hand in it, because that is
// what decides which setting an operator is sent to when a job runs out.
func TestAPartlyLimitedPoolKeepsItsOwnLimitsAndFillsTheRest(t *testing.T) {
	h := sized("host_a", 4, 16, 32*1024, 500*1024)
	p := limited("builders", 0, 2048)
	p.Resources.PidsLimit = 512
	p.Resources.DiskGB = 10

	got, source := Allocation(p, h, true)
	if got.MemoryMB != 2048 || got.CPUs != 3.8 || got.PidsLimit != 512 || got.DiskGB != 10 {
		t.Fatalf("allocation = %+v, want the pool's memory, pids and disk with the host's CPU share", got)
	}
	if source != store.AllocationFromHost {
		t.Errorf("source = %q, want %q because the CPU came from the host", source, store.AllocationFromHost)
	}

	p = limited("builders", 2, 2048)
	if got, source := Allocation(p, h, true); got != p.Resources || source != store.AllocationFromPool {
		t.Errorf("a fully limited pool was changed: %+v from %q", got, source)
	}
}

// Defaults off is the fleet as it was: the pool's limits are the whole answer,
// and a pool with none gets none. An operator who turns them off is warned at
// startup, and the allocation has to honour the choice rather than the warning.
func TestDefaultsOffLeavesAnUnlimitedPoolUnlimited(t *testing.T) {
	h := sized("host_a", 4, 16, 32*1024, 500*1024)
	p := limited("builders", 0, 0)
	if got, source := Allocation(p, h, false); got != (store.Resources{}) || source != "" {
		t.Fatalf("allocation = %+v from %q with defaults off, want nothing", got, source)
	}
}

// A host that never measured itself has no share to give, so its runners are
// created as they always were. It is the same rule that places such a host by
// slots alone: a figure nobody reported constrains nothing, and inventing one
// would be worse than the overload it was meant to prevent.
func TestAnUnmeasuredHostGivesNoDefault(t *testing.T) {
	h := testHost("host_a", 4, 0)
	h.BackendInfo = store.HostBackends{{Kind: store.BackendDocker, Available: true,
		Limits: store.LimitSupport{Known: true, CPU: true, Memory: true}}}
	p := limited("builders", 0, 0)
	if got, source := Allocation(p, h, true); got != (store.Resources{}) || source != "" {
		t.Fatalf("allocation = %+v from %q on an unmeasured host, want nothing", got, source)
	}
	// Half measured: the CPU share is given, the memory is not.
	h.CPUs = 8
	got, source := Allocation(p, h, true)
	if got.CPUs != 1.87 || got.MemoryMB != 0 || source != store.AllocationFromHost {
		t.Fatalf("allocation = %+v from %q on a host that measured only its CPUs", got, source)
	}
}

// A daemon that cannot apply a quota refuses the container rather than
// ignoring the request: rootless Docker on a host that delegates only memory
// and pids to the user says so in its own probe, and a default CPU limit sent
// there would fail every create on the host. So each field is defaulted only
// where the daemon said it can bind it, and a probe from an agent too old to
// say defaults nothing -- which is what every host did before.
func TestADefaultIsOnlyGivenWhereTheDaemonCanEnforceIt(t *testing.T) {
	h := sized("host_a", 4, 16, 32*1024, 500*1024)
	p := limited("builders", 0, 0)

	h.BackendInfo[0].Limits = store.LimitSupport{Known: true, CPU: false, Memory: true}
	got, source := Allocation(p, h, true)
	if got.CPUs != 0 || got.MemoryMB != 7782 || source != store.AllocationFromHost {
		t.Fatalf("allocation = %+v from %q on a daemon without CFS quotas, want memory alone", got, source)
	}
	h.BackendInfo[0].Limits = store.LimitSupport{}
	if got, source := Allocation(p, h, true); got != (store.Resources{}) || source != "" {
		t.Fatalf("allocation = %+v from %q from an agent that never said what its daemon can do", got, source)
	}
	h.BackendInfo = nil
	if got, source := Allocation(p, h, true); got != (store.Resources{}) || source != "" {
		t.Fatalf("allocation = %+v from %q on a host with no probe at all", got, source)
	}
}

// The process backend applies no limit, so a defaulted figure on one of its
// runners would be a number on the Runners page saying the opposite of the
// truth. Such a runner is recorded as what it is: unlimited.
func TestAProcessPoolGetsNoDefault(t *testing.T) {
	h := sized("host_a", 4, 16, 32*1024, 500*1024)
	h.Backends = store.StringSlice{"process"}
	h.BackendInfo = store.HostBackends{{Kind: store.BackendProcess, Available: true,
		Limits: store.LimitSupport{Known: true, CPU: true, Memory: true}}}
	p := limited("builders", 0, 0)
	p.Backend = store.BackendProcess
	if got, source := Allocation(p, h, true); got != (store.Resources{}) || source != "" {
		t.Fatalf("allocation = %+v from %q on a process pool, want nothing", got, source)
	}
	// The pool's own limits still travel, because the warning about them is
	// the pool's to earn.
	p = limited("builders", 2, 2048)
	p.Backend = store.BackendProcess
	if got, source := Allocation(p, h, true); got != p.Resources || source != store.AllocationFromPool {
		t.Fatalf("allocation = %+v from %q, want the pool's own limits", got, source)
	}
}

// The charge does not move with the throttle. Reserve and Allocation both
// divide by the operator's capacity, never the effective one: if they did not,
// stepping a host from four slots to two would double the charge on every
// runner already there, and the host card's committed figure would jump for
// runners that had not changed.
func TestTheShareIsAShareOfTheConfiguredCapacityWhateverTheThrottle(t *testing.T) {
	h := sized("host_a", 4, 16, 32*1024, 500*1024)
	p := limited("builders", 0, 0)
	before, _ := Allocation(p, h, true)
	charge := Reserve(p, h)
	h.Throttle = store.HostThrottle{Level: 2}
	after, _ := Allocation(p, h, true)
	if after != before || Reserve(p, h) != charge {
		t.Fatalf("the throttle moved the share: %+v -> %+v, charge %+v -> %+v", before, after, charge, Reserve(p, h))
	}
}

// The share is floored to the hundredth, never rounded up: three runners
// rounded up from 0.667 to 0.67 would together be promised a hundredth of a
// core the host does not have, and the daemon refuses a quota above the
// machine.
func TestTheCPUShareIsFlooredToTheHundredth(t *testing.T) {
	if got := shareCPUs(2, 3); got != 0.66 {
		t.Errorf("shareCPUs(2, 3) = %v, want 0.66", got)
	}
	if got := shareCPUs(7.5, 3); got != 2.5 {
		t.Errorf("shareCPUs(7.5, 3) = %v, want 2.5 exactly", got)
	}
	if got := shareCPUs(4, 0); got != 0 {
		t.Errorf("shareCPUs(4, 0) = %v, want 0 for a host with no slots", got)
	}
}

// A share is a request to the daemon, and a daemon refuses a quota above its
// own core count however many cores the agent's machine has -- a Docker
// Desktop VM on a ten-core laptop has four. The host is sized by its daemon,
// so this only matters for a row whose size and probe disagree, and then the
// share is capped rather than the create refused.
func TestTheDefaultShareNeverExceedsTheDaemonsOwnCores(t *testing.T) {
	h := sized("host_a", 1, 10, 32*1024, 500*1024)
	h.BackendInfo[0].CPUs = 4
	p := limited("builders", 0, 0)
	got, _ := Allocation(p, h, true)
	if got.CPUs != 4 {
		t.Fatalf("allocation = %v CPUs, want the daemon's 4 rather than the agent's share of 10", got.CPUs)
	}
}

// A problem that names "each runner's default share" has to ask first whether
// a share is ever given: a host offering only the process backend, or a
// daemon that cannot apply the limit, gives none.
func TestDefaultsBindSaysWhichFieldsAHostCanBeGivenADefaultOn(t *testing.T) {
	h := sized("host_a", 4, 16, 32*1024, 500*1024)
	if cpu, memory := DefaultsBind(h); !cpu || !memory {
		t.Fatalf("a daemon that enforces both reported %v/%v", cpu, memory)
	}
	h.BackendInfo[0].Limits = store.LimitSupport{Known: true, CPU: false, Memory: true}
	if cpu, memory := DefaultsBind(h); cpu || !memory {
		t.Fatalf("a daemon without CFS quotas reported %v/%v", cpu, memory)
	}
	h.BackendInfo = store.HostBackends{{Kind: store.BackendProcess, Available: true, Limits: store.LimitSupport{Known: true, CPU: true, Memory: true}}}
	if cpu, memory := DefaultsBind(h); cpu || memory {
		t.Fatalf("a process-only host reported %v/%v", cpu, memory)
	}
	h.BackendInfo = store.HostBackends{{Kind: store.BackendDocker, Available: true}}
	if cpu, memory := DefaultsBind(h); cpu || memory {
		t.Fatalf("an agent that has not said reported %v/%v", cpu, memory)
	}
}

package scheduler

import (
	"fmt"
	"math/rand"
	"reflect"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// assign used to set every queued job against every pool. It now sets a job
// against them only if no job before it asked the same thing, and gives the rest
// that job's answer. The function below is the one it replaced, kept as it was,
// and the tests hold the new one to its answer over a great many random fleets in
// which many jobs do ask the same thing.

// assign maps every queued job onto the pool that will run it, and collects the
// ones nothing claims, each with the reason it went unclaimed.
func referenceAssign(pools []*store.Pool, jobs []*store.Job, targets map[string]string) (map[string][]*store.Job, []UnmatchedJob) {
	demand := make(map[string][]*store.Job, len(pools))
	var unmatched []UnmatchedJob
	var prepared [][]string
	for _, j := range sortedJobs(jobs) {
		if j.State != store.JobQueued || j.Provisioning != "" {
			continue
		}
		if prepared == nil {
			// Prepared for the first job that needs it. Most passes find nothing
			// waiting, and they should not pay to get the pools ready for a
			// comparison that never happens.
			prepared = preparedLabels(pools)
		}
		p, reason := bestOf(pools, prepared, j, labelsOf(store.NormalizeLabels(j.Labels)), targets)
		if p == nil {
			unmatched = append(unmatched, UnmatchedJob{Job: j, Reason: reason})
			continue
		}
		demand[p.ID] = append(demand[p.ID], j)
	}
	return demand, unmatched
}

// randomAssignFleet is pools and jobs drawn from a small vocabulary, so that a
// great many of the jobs ask the same thing as another and a great many ask what
// only some pools offer: labels in several cases and orders (which normalise to
// the same), two installations and none, three size classes and none, a few
// repositories, jobs in every state and some held back from provisioning, pools
// that are disabled, that decline the implicit labels and that are kept for a
// class of runner.
func randomAssignFleet(rng *rand.Rand) ([]*store.Pool, []*store.Job, map[string]string) {
	vocabulary := []string{"self-hosted", "linux", "x64", "arm64", "gpu", "Large", "docker", "windows"}
	installations := []string{"", "ins_a", "ins_b"}
	var pools []*store.Pool
	for i := range 1 + rng.Intn(12) {
		var labels []string
		for _, l := range vocabulary {
			if rng.Intn(3) == 0 {
				labels = append(labels, l)
			}
		}
		p := testPool(fmt.Sprintf("pool%02d", i), labels...)
		p.ID = fmt.Sprintf("pool_%02d", i)
		p.InstallationID = installations[1+rng.Intn(2)]
		p.Enabled = rng.Intn(8) != 0
		p.NoDefaultLabels = rng.Intn(6) == 0
		if rng.Intn(3) == 0 {
			p.AutoKey = store.AutoKeyFor([]string{"amd64", "arm64"}[rng.Intn(2)], store.SizeClasses()[rng.Intn(3)])
		}
		pools = append(pools, p)
	}
	if rng.Intn(5) == 0 {
		pools = append(pools, nil)
	}

	states := []store.JobState{store.JobQueued, store.JobQueued, store.JobQueued, store.JobInProgress, store.JobWaiting}
	var jobs []*store.Job
	for i := range rng.Intn(60) {
		var labels []string
		for _, l := range vocabulary {
			if rng.Intn(3) == 0 {
				labels = append(labels, []string{l, "  " + l + " "}[rng.Intn(2)])
			}
		}
		rng.Shuffle(len(labels), func(a, b int) { labels[a], labels[b] = labels[b], labels[a] })
		j := queued(fmt.Sprintf("job_%03d", i), time.Duration(rng.Intn(600))*time.Second, labels...)
		j.State = states[rng.Intn(len(states))]
		j.InstallationID = installations[rng.Intn(3)]
		j.Repo = []string{"acme/widgets", "acme/gadgets", "other/things"}[rng.Intn(3)]
		if rng.Intn(3) == 0 {
			j.RoutedClass = store.SizeClasses()[rng.Intn(3)]
		}
		if rng.Intn(10) == 0 {
			j.Provisioning = "paused"
		}
		jobs = append(jobs, j)
	}
	return pools, jobs, map[string]string{"ins_a": "acme", "ins_b": "other"}
}

func TestChoosingAPoolOnceForEachKindOfJobChoosesAsChoosingForEveryJobDid(t *testing.T) {
	var matched, unmatched, shared int
	for seed := range int64(1500) {
		rng := rand.New(rand.NewSource(seed))
		pools, jobs, targets := randomAssignFleet(rng)

		gotDemand, gotUnmatched := assign(pools, jobs, targets)
		wantDemand, wantUnmatched := referenceAssign(pools, jobs, targets)
		if !reflect.DeepEqual(gotDemand, wantDemand) || !reflect.DeepEqual(gotUnmatched, wantUnmatched) {
			t.Fatalf("seed %d: the jobs were assigned differently\n got: %v / %v\nwant: %v / %v", seed, gotDemand, gotUnmatched, wantDemand, wantUnmatched)
		}
		for _, js := range wantDemand {
			matched += len(js)
			if len(js) > 1 {
				shared++
			}
		}
		unmatched += len(wantUnmatched)
	}
	// The comparison says something only if the fleets gave the jobs somewhere to go,
	// somewhere not to, and more than one job to a pool.
	if matched == 0 || unmatched == 0 || shared == 0 {
		t.Fatalf("the random fleets exercised too little: %d jobs matched, %d unmatched, %d pools given more than one", matched, unmatched, shared)
	}
}

// Two jobs that differ only in what bestOf never reads are given one answer, and
// two that differ in what it does read are not: the repository only where it is
// named in the reason.
func TestJobsAreGivenTheSameAnswerOnlyWhenTheyAskTheSameThing(t *testing.T) {
	a := testPool("a", "self-hosted", "gpu")
	a.ID, a.InstallationID = "pool_a", "ins_a"
	pools := []*store.Pool{a}
	targets := map[string]string{"ins_a": "acme", "ins_b": "other"}

	job := func(id, installation, repo string, labels ...string) *store.Job {
		j := queued(id, time.Minute, labels...)
		j.InstallationID, j.Repo = installation, repo
		return j
	}
	jobs := []*store.Job{
		job("job_1", "ins_a", "acme/widgets", "self-hosted", "gpu"), // goes to pool a
		job("job_2", "ins_a", "acme/gadgets", "gpu", "self-hosted"), // the same ask, in another order and repository: pool a
		job("job_3", "ins_b", "other/things", "self-hosted", "gpu"), // another installation: the near miss, not pool a
		job("job_4", "", "acme/widgets", "self-hosted", "gpu"),      // no installation, naming acme/widgets
		job("job_5", "", "acme/gadgets", "self-hosted", "gpu"),      // the same, naming acme/gadgets
	}
	for i := range jobs {
		jobs[i].QueuedAt = ago(time.Duration(len(jobs)-i) * time.Minute) // in the order written
	}
	demand, unmatched := assign(pools, jobs, targets)
	if len(demand["pool_a"]) != 2 {
		t.Errorf("pool a was given %d jobs; want the first two", len(demand["pool_a"]))
	}
	reasons := map[string]string{}
	for _, u := range unmatched {
		reasons[u.Job.ID] = u.Reason
	}
	if len(reasons) != 3 {
		t.Fatalf("%d jobs went unmatched; want three: %v", len(reasons), reasons)
	}
	if reasons["job_4"] == reasons["job_5"] {
		t.Errorf("two jobs in different repositories with no installation were told the same reason, %q; each reason names its repository", reasons["job_4"])
	}
	if reasons["job_3"] == reasons["job_4"] {
		t.Errorf("a job of another installation and one of none were told the same reason, %q", reasons["job_3"])
	}
}

// The answer is kept under the bytes of the question, so the bytes have to say where
// one label ends and the next begins: ab and c run together as a and bc do, and they
// are not the same ask.
func TestLabelsThatRunTogetherAreNotTheSameQuestion(t *testing.T) {
	x := testPool("x", "ab", "c")
	x.ID, x.InstallationID = "pool_x", "ins_a"
	y := testPool("y", "a", "bc")
	y.ID, y.InstallationID = "pool_y", "ins_a"

	job := func(id string, age time.Duration, labels ...string) *store.Job {
		j := queued(id, age, labels...)
		j.InstallationID, j.Repo = "ins_a", "acme/widgets"
		return j
	}
	jobs := []*store.Job{job("job_1", 2*time.Minute, "ab", "c"), job("job_2", time.Minute, "a", "bc")}

	demand, unmatched := assign([]*store.Pool{x, y}, jobs, nil)
	if len(unmatched) != 0 || len(demand["pool_x"]) != 1 || demand["pool_x"][0].ID != "job_1" ||
		len(demand["pool_y"]) != 1 || demand["pool_y"][0].ID != "job_2" {
		t.Errorf("the jobs asking for ab and c, and for a and bc, were given pool_x %v and pool_y %v, with %d unmatched; want one each",
			jobIDsOf(demand["pool_x"]), jobIDsOf(demand["pool_y"]), len(unmatched))
	}
}

func jobIDsOf(jobs []*store.Job) []string {
	out := make([]string, len(jobs))
	for i, j := range jobs {
		out[i] = j.ID
	}
	return out
}

// What a pass saves by it is the comparison, and a refusal is the part of the
// comparison that leaves something to count: the sentence saying which pool a job
// nearly went to is built each time bestOf has to word it. A thousand jobs refused
// for one reason cost the allocations of one sentence, not a thousand.
func TestAKindOfJobIsRefusedAndExplainedOnceHoweverManyAskIt(t *testing.T) {
	p := testPool("a", "self-hosted", "gpu")
	p.ID, p.InstallationID = "pool_a", "ins_a"
	pools := []*store.Pool{p}
	targets := map[string]string{"ins_a": "acme", "ins_b": "other"}

	refused := func(n int) []*store.Job {
		jobs := make([]*store.Job, n)
		for i := range jobs {
			// As the store hands them over, already normalised: labels out of order
			// are copied into order for every job, kind or no kind.
			j := queued(fmt.Sprintf("job_%04d", i), time.Duration(n-i)*time.Second, "gpu", "self-hosted")
			j.InstallationID, j.Repo = "ins_b", "other/things" // the near miss: the pool belongs to another installation
			jobs[i] = j
		}
		return jobs
	}
	few, many := refused(10), refused(1000)
	if _, unmatched := assign(pools, many, targets); len(unmatched) != len(many) || unmatched[0].Reason == "" {
		t.Fatalf("%d of %d jobs were refused, the first with %q; want all of them, with a reason", len(unmatched), len(many), unmatched[0].Reason)
	}

	allocsFew := testing.AllocsPerRun(10, func() { assign(pools, few, targets) })
	allocsMany := testing.AllocsPerRun(10, func() { assign(pools, many, targets) })
	// The list of refusals grows with the jobs, a few allocations for a hundredfold
	// more of them. Wording the reason for each would be several for every job.
	if allocsMany-allocsFew > 50 {
		t.Errorf("a thousand jobs asking the same thing took %.0f allocations and ten took %.0f; the reason for refusing them should be worded once", allocsMany, allocsFew)
	}
}

package scheduler

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// partlyUsed is the host the automatic-pool tests share: 8 cores and 16 GB
// allocatable over two slots, so a slot's share is 3.75 cores (after the
// host's CPU reserve) and 8 GB. One slot is taken by a fixed-size runner of
// another pool holding 5 cores and 10 GB, which leaves one free slot and 2.5
// cores and 6 GB to go with it -- less than a whole share, more than a runner
// needs.
func partlyUsed(t *testing.T, auto *store.Pool) *hostSet {
	t.Helper()
	h := sized("h", 2, 8, hostFor(16*1024), 100000)
	h.ActiveRunners = 1
	big := limited("big", 5, 10*1024)
	r := &store.Runner{ID: "r1", PoolID: big.ID, HostID: h.ID, State: store.RunnerBusy}
	return newHostSet([]*store.Host{h}, []*store.Pool{big, auto}, map[string][]*store.Runner{big.ID: {r}}, now)
}

func automatic(name string, minCPUs float64, minMemoryMB int64) *store.Pool {
	p := testPool(name, name)
	p.Resources.MinCPUs, p.Resources.MinMemoryMB = minCPUs, minMemoryMB
	return p
}

// The report that found this: an automatic pool on a host with a free slot and
// room for a runner several times over, refused because it only ever asked for
// a whole slot's share. With a minimum it runs, on what the host has left.
func TestAnAutomaticPoolWithAMinimumRunsOnWhatIsLeftOfASlot(t *testing.T) {
	p := automatic("auto", 1, 2048)
	hs := partlyUsed(t, p)

	placed := hs.placeAvoiding(p, 1, nil)
	if len(placed) != 1 || placed[0].hostID != "h" {
		t.Fatalf("placed %+v, want one runner on the partly used host", placed)
	}
	size := placed[0].size
	if size == nil {
		t.Fatal("the runner was placed at a whole share on a host without one left")
	}
	// All of what is left, not the minimum: the minimum is a floor.
	if size.CPUs != 2.5 || size.MemoryMB != 6*1024 {
		t.Errorf("size = %g CPU and %d MB, want what the host has left: 2.5 and 6144", size.CPUs, size.MemoryMB)
	}
	// The charge is what the runner is created with, and the host's slot and
	// room are both gone.
	if hs.free["h"] != 0 {
		t.Errorf("free slots = %d, want 0", hs.free["h"])
	}
}

// Without a minimum nothing changes: an automatic pool is still a whole slot
// or nothing, and the refusal now says what to do about it instead of telling
// the operator to lower limits the pool does not have.
func TestAnAutomaticPoolWithoutAMinimumStillWantsAWholeShare(t *testing.T) {
	p := automatic("auto", 0, 0)
	hs := partlyUsed(t, p)

	if got := hs.placeAvoiding(p, 1, nil); len(got) != 0 {
		t.Fatalf("placed %+v on a host without a whole share left, with no minimum", got)
	}
	b := hs.why(p)
	if !strings.Contains(b.fix, "minimum") || strings.Contains(b.fix, "limits") {
		t.Errorf("fix = %q, want it to point at a minimum, not at limits the pool does not set", b.fix)
	}
}

// A minimum is a way down, never the first choice: a host with a whole share
// left gets a runner at the whole share.
func TestAnAutomaticMinimumNeverShrinksARunnerThatHasAWholeShare(t *testing.T) {
	h := sized("idle", 2, 8, hostFor(16*1024), 100000)
	p := automatic("auto", 1, 2048)
	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)

	placed := hs.placeAvoiding(p, 1, nil)
	if len(placed) != 1 || placed[0].size != nil {
		t.Fatalf("placed %+v, want one runner at the standard share", placed)
	}
}

// Below the minimum is still no.
func TestAnAutomaticPoolDoesNotGoBelowItsMinimum(t *testing.T) {
	p := automatic("auto", 1, 8*1024)
	hs := partlyUsed(t, p)
	if got := hs.placeAvoiding(p, 1, nil); len(got) != 0 {
		t.Fatalf("placed %+v with 6 GB left under an 8 GB minimum", got)
	}
}

// A docker-in-docker slot is split between the runner and its daemon, and the
// pool's minimum is per container, so the slot is never cut below twice the
// minimum -- and no further than that: the operator's minimum, not the
// comfortable figure a pool nobody sized is held to, is what the pair needs.
func TestAnAutomaticDinDSlotIsNotCutBelowTwiceItsMinimum(t *testing.T) {
	p := automatic("auto", 0.5, 1024)
	p.DockerMode = store.DockerDinD
	floor := ShareFloor(p)
	if floor.CPUs != 1 || floor.MemoryMB != 2048 {
		t.Fatalf("ShareFloor = %+v, want twice the minimum: 1 core and 2 GB", floor)
	}

	for _, tc := range []struct {
		name   string
		used   float64
		placed bool
	}{
		{"exactly twice the minimum left", 6.5, true},
		{"less than twice the minimum left", 6.6, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := sized("h", 2, 8, hostFor(16*1024), 100000)
			h.ActiveRunners = 1
			big := limited("big", tc.used, 13*1024)
			r := &store.Runner{ID: "r1", PoolID: big.ID, HostID: h.ID, State: store.RunnerBusy}
			hs := newHostSet([]*store.Host{h}, []*store.Pool{big, p}, map[string][]*store.Runner{big.ID: {r}}, now)
			left := hs.leftFor(h, p)
			got := hs.placeAvoiding(p, 1, nil)
			if (len(got) == 1) != tc.placed {
				t.Fatalf("with %g cores left, placed %+v; want placed=%v against the pair's %g", left.CPUs, got, tc.placed, floor.CPUs)
			}
		})
	}
}

// A reduced automatic runner is charged what its row says it was given, once:
// its allocation is the whole of a (smaller) slot, shared with its daemon, not
// a per-container figure to double.
func TestAReducedAutomaticRunnerIsChargedWhatItWasGiven(t *testing.T) {
	p := automatic("auto", 1, 2048)
	p.DockerMode = store.DockerDinD
	h := sized("h", 2, 8, hostFor(16*1024), 100000)
	r := &store.Runner{ID: "r", PoolID: p.ID, HostID: h.ID, State: store.RunnerBusy,
		AllocationSource: store.AllocationReduced, AllocatedCPUs: 2.5, AllocatedMemoryMB: 6144}
	got := RunnerCharge(p, h, r)
	if got.CPUs != 2.5 || got.MemoryMB != 6144 {
		t.Errorf("charge = %+v, want 2.5 cores and 6144 MB", got)
	}
}

// A minimum above a small host's share is not a way up: it leaves the share as
// the least the pool asks for there.
func TestAnAutomaticMinimumAboveTheShareChangesNothing(t *testing.T) {
	h := sized("h", 4, 8, hostFor(8*1024), 100000)
	p := automatic("auto", 4, 8*1024)
	if got, want := MinimumReserve(p, h), Reserve(p, h); got != want {
		t.Errorf("MinimumReserve = %+v, want the share %+v", got, want)
	}
}

// End to end through Decide: a queued job for the automatic pool becomes a
// create on the partly used host, carrying the reduced size, with a reason
// that does not name a standard size the pool never set.
func TestAQueuedJobOnAnAutomaticPoolIsCreatedReduced(t *testing.T) {
	h := sized("h", 2, 8, hostFor(16*1024), 100000)
	h.ActiveRunners = 1
	big := limited("big", 5, 10*1024)
	auto := automatic("auto", 1, 2048)
	busy := &store.Runner{ID: "r1", PoolID: big.ID, HostID: h.ID, State: store.RunnerBusy, CreatedAt: now}
	s := snap([]*store.Pool{big, auto}, []*store.Runner{busy}, []*store.Job{queued("j1", time.Minute, "auto")}, []*store.Host{h})

	var creates []Action
	for _, a := range actionsOf(Decide(s).Actions, ActionCreate) {
		if a.PoolID == auto.ID {
			creates = append(creates, a)
		}
	}
	if len(creates) != 1 {
		t.Fatalf("creates for the automatic pool = %+v, want one", creates)
	}
	if creates[0].Size == nil || creates[0].Size.MemoryMB != 6*1024 {
		t.Errorf("size = %+v, want the 6 GB left carried on the action", creates[0].Size)
	}
	if !strings.Contains(creates[0].Reason, "reduced to 2.5 CPU and 6 GB") || strings.Contains(creates[0].Reason, "standard") {
		t.Errorf("reason = %q, want the reduced size and no standard the pool never set", creates[0].Reason)
	}
}

// The report behind this: an automatic docker-in-docker pool with a minimum,
// and a 4-core, 3 GB machine set to one slot. Its share is 2.8 GB, under the
// 4 GB a pair nobody sized is held to and over twice the minimum the operator
// typed, so it runs the pool -- at that share -- and saying so is information,
// not a reason it cannot. Without a minimum it still cannot, and with one the
// whole machine cannot cover the refusal names the minimum as the operator's to
// lower.
func TestAnAutomaticDinDPoolRunsAtItsMinimumOnASmallHostAndSaysSoAsInformation(t *testing.T) {
	h := sized("small", 1, 4, hostFor(2867), 100000)
	withMin := automatic("auto", 0, 1024)
	withMin.DockerMode = store.DockerDinD

	if !HostFits(h, withMin) {
		t.Fatalf("a 2.8 GB share was refused for a pool whose pair needs 2 GB: %s", HostShortfall(h, withMin))
	}
	if s := HostShortfall(h, withMin); s != "" {
		t.Errorf("shortfall = %q, want none", s)
	}
	note := HostReduction(h, withMin)
	if !strings.Contains(note, "2.8 GB") || !strings.Contains(note, "4 GB") || !strings.Contains(note, "minimum") {
		t.Errorf("reduction = %q, want the share, the comfortable size and the minimum", note)
	}

	noMin := automatic("plain", 0, 0)
	noMin.DockerMode = store.DockerDinD
	if HostFits(h, noMin) || !strings.Contains(HostShortfall(h, noMin), "a runner is killed before it takes a job below 4 GB") {
		t.Errorf("a pool nobody sized was placed on a thin slot: %q", HostShortfall(h, noMin))
	}

	high := automatic("high", 0, 2048)
	high.DockerMode = store.DockerDinD
	if got := HostShortfall(h, high); !strings.Contains(got, "this pool's minimum of 2 GB a container") {
		t.Errorf("shortfall = %q, want it to name the pool's own minimum", got)
	}
}

package scheduler

import (
	"fmt"
	"slices"
	"sort"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/naming"
	"github.com/eyupio/zoomies/internal/store"
)

// Why a host is not counted towards an automatic pool. The first four are
// states a healthy fleet passes through -- a machine cordoned for maintenance, a
// network that dropped for an hour -- and are said on the Hosts page and in a
// pool's own cause; the rest are things an operator has to do something about,
// and become findings.
const (
	SkipCordoned     = "cordoned"
	SkipIncompatible = "incompatible"
	SkipSilent       = "silent"
	SkipNoClass      = "unclassified"
	SkipBadSize      = "bad_size_label"
	SkipArch         = "unknown_architecture"
	SkipBackend      = "no_backend"
)

// AutoPoolChangeKind is what the controller has to do to a pool it keeps.
type AutoPoolChangeKind string

const (
	// AutoPoolCreate makes the pool for a class that has its first host.
	AutoPoolCreate AutoPoolChangeKind = "create"
	// AutoPoolResize moves a pool's maximum, or its warm minimum, because the
	// hosts in its class changed.
	AutoPoolResize AutoPoolChangeKind = "resize"
	// AutoPoolEnable puts a pool back in use because a host of its class is back.
	AutoPoolEnable AutoPoolChangeKind = "enable"
	// AutoPoolDisable takes a pool out of use because its last host is gone. The
	// pool and its history stay.
	AutoPoolDisable AutoPoolChangeKind = "disable"
	// AutoPoolReshape brings a pool's fixed fields -- its labels, its selector,
	// its docker mode -- back in line with what a pool of its class is made
	// with, which only differs after a setting changed.
	AutoPoolReshape AutoPoolChangeKind = "reshape"
)

// AutoPoolInput is what PlanAutoPools decides from.
type AutoPoolInput struct {
	Now   time.Time
	Hosts []*store.Host
	// Pools is every pool, the operator's and the controller's, so that a name
	// or a label an operator already uses is never taken over.
	Pools []*store.Pool
	// InstallationID is the installation the pools belong to. Pools the
	// controller keeps for any other are put out of use.
	InstallationID string
	// RunnerGroup is the organisation runner group a pool is made in: the one
	// Zoomies provisions for an organisation installation, and none for a
	// repository's, which has no groups. It is what a pool created by hand on the
	// same installation is given where it names none, and an automatic pool left
	// in GitHub's Default group would be offered to every repository of the
	// organisation while the pools beside it were not.
	RunnerGroup string
	// Since is when the controller began listening, zero where that is not known.
	// A host's silence is counted from the later of its last heartbeat and this: a
	// controller that was down for an hour has heard from no host for an hour,
	// which says nothing about the hosts, and every one would otherwise be
	// dropped from its pool -- and each pool disabled -- on the first pass, until
	// the agents had had time to report again.
	Since time.Time
	// Grace is how long a host may be silent and still count. It is longer than
	// the time after which the fleet gives a silent host's runners up, so that a
	// brief network drop reshuffles nothing.
	Grace time.Duration
	// DockerMode is the docker mode a pool is made with, from the settings.
	DockerMode store.DockerMode
	// Size returns a pool as the scheduler sizes it -- with the figures the
	// fleet's settings give it, which the scheduler cannot read -- or the pool
	// itself. A nil Size is the identity.
	Size func(*store.Pool) *store.Pool
	// Previous is the hosts that counted towards each pool the last time the
	// controller looked, by pool key. It is only there to say what changed in a
	// pool's cause; nothing is decided from it, so a controller that has just
	// started and has none is simply less specific.
	Previous map[string][]string
}

// AutoPoolChange is one thing to do to the pools the controller keeps, with
// the sentence that says why.
type AutoPoolChange struct {
	Kind AutoPoolChangeKind
	// Key is the pool's key: an architecture and a class.
	Key string
	// Before is the pool as it is, nil for a pool being created.
	Before *store.Pool
	// After is the pool as it should be. For a create it is the pool to insert;
	// otherwise it is Before with the changes made.
	After *store.Pool
	// Hosts are the hosts that count towards the pool, and Slots what they add
	// up to before any operator cap.
	Hosts []string
	Slots int
	// Reshaped says the pool's fixed fields differ from what a pool of its class
	// is made with, as well as whatever Kind says changed. They are written with
	// the limits in one statement, so a pool that needed both is not left
	// half-corrected for another pass.
	Reshaped bool
	// Cause is the sentence for the audit log and the Overview feed.
	Cause string
}

// AutoPoolFinding is something the controller could not do, and what to do
// about it.
type AutoPoolFinding struct {
	Code string `json:"code"`
	// Subject is the pool, host or class the finding is about.
	Subject string `json:"subject"`
	Message string `json:"message"`
	Fix     string `json:"fix"`
}

// The findings PlanAutoPools reports.
const (
	FindingNameTaken   = "auto_pool.name_taken"
	FindingLabelTaken  = "auto_pool.label_taken"
	FindingHostSkipped = "auto_pool.host_skipped"
)

// HostSkip is a host that does not count towards any automatic pool, and why.
type HostSkip struct {
	Host   *store.Host
	Reason string
}

// AutoPoolPlan is the outcome of one pass.
type AutoPoolPlan struct {
	Changes  []AutoPoolChange
	Findings []AutoPoolFinding
	// Skipped is every host that counted towards no pool.
	Skipped []HostSkip
	// Members is the hosts counted towards each pool, by pool key, which the
	// controller keeps to say what changed on the next pass.
	Members map[string][]string
	// Slots is the runners the hosts counted towards each pool hold between
	// them, by pool key, before any cap: what the pool's page says its maximum
	// is made of.
	Slots map[string]int
}

// AutoPoolKey is the key of the pool for an architecture and class.
func AutoPoolKey(arch string, class store.SizeClass) string { return store.AutoKeyFor(arch, class) }

// AutoPoolName is the name of the pool for an architecture and class, in the
// grammar every other name follows: the brand, the architecture where it is not
// the usual one, and the class -- zoomies-large, zoomies-arm64-large.
func AutoPoolName(arch string, class store.SizeClass) string {
	return naming.Spec{Arch: arch, Suffix: string(class)}.String()
}

// AutoPoolLabels are the labels the pool for an architecture and class answers
// to: the one every pool carries, the class, and the two kernel and architecture
// labels that stop a job for another machine being claimed by it. The class
// label is the guaranteed path: only a runner that carries it can take a job
// that asks for it.
func AutoPoolLabels(arch string, class store.SizeClass) []string {
	return store.BrandLabels([]string{class.Label(), "linux", naming.ArchLabel(arch)})
}

// NewAutoPool is the pool made for an architecture and class. It leaves its
// runners' size to the host they land on, which is why it is a profile pool, and
// selects the hosts in its class, which is why a host is only ever in one.
//
// It is the pool an operator would get from the API with nothing but these set,
// and a test in the api package holds the two together.
func NewAutoPool(in AutoPoolInput, arch string, class store.SizeClass, backend store.BackendKind) *store.Pool {
	p := &store.Pool{
		Name:            AutoPoolName(arch, class),
		InstallationID:  in.InstallationID,
		RunnerGroup:     in.RunnerGroup,
		Labels:          store.StringSlice(AutoPoolLabels(arch, class)),
		Backend:         backend,
		Platform:        store.Platform{Arch: arch},
		PullPolicy:      store.PullIfNotPresent,
		IdleTimeout:     store.Duration(5 * time.Minute),
		Ephemeral:       true,
		DockerMode:      in.DockerMode,
		Cache:           store.CacheConfig{Scope: store.CacheScopePool},
		SizeFromProfile: true,
		HostSelector:    store.StringMap{store.LabelSize: string(class)},
		AutoKey:         AutoPoolKey(arch, class),
		Enabled:         true,
	}
	if p.DockerMode == "" {
		p.DockerMode = store.DockerNone
	}
	if backend == store.BackendDocker || backend == store.BackendPodman {
		p.CPUBurst = store.CPUBurstPolicy{Mode: store.CPUBurstObserve}
		p.MemoryBurst = store.MemoryBurstPolicy{Mode: store.MemoryBurstObserve}
	}
	return p
}

// autoGroup is the hosts that fall in one architecture and class.
type autoGroup struct {
	arch  string
	class store.SizeClass
	hosts []*store.Host
}

// PlanAutoPools works out what the pools the controller keeps should look like
// for the hosts that exist, and what has to change to make them so.
//
// It is the whole of the policy and holds no state. It is run on every host
// event and on a timer, and because every figure is recomputed from the hosts as
// they are, running it twice in a row changes nothing the second time, and
// running it after a missed event repairs what the event would have done. That
// is what lets the controller treat an event as a hint to look sooner rather
// than as the only way anything is noticed.
func PlanAutoPools(in AutoPoolInput) AutoPoolPlan {
	plan := AutoPoolPlan{Members: map[string][]string{}, Slots: map[string]int{}}
	size := in.Size
	if size == nil {
		size = func(p *store.Pool) *store.Pool { return p }
	}

	// Which hosts count, and in which group.
	groups := map[string]*autoGroup{}
	reasons := map[string]string{} // by host ID, for wording what changed
	for _, h := range sortedHosts(in.Hosts) {
		arch, class, reason := autoClassOf(h, in)
		if reason != "" {
			reasons[h.ID] = reason
			plan.Skipped = append(plan.Skipped, HostSkip{Host: h, Reason: reason})
			continue
		}
		key := AutoPoolKey(arch, class)
		g := groups[key]
		if g == nil {
			g = &autoGroup{arch: arch, class: class}
			groups[key] = g
		}
		g.hosts = append(g.hosts, h)
	}

	// The pools the controller already keeps, by key, in this installation.
	ours := map[string]*store.Pool{}
	var elsewhere []*store.Pool
	for _, p := range sortedPools(in.Pools) {
		switch {
		case !p.FromHosts():
		case p.InstallationID == in.InstallationID:
			ours[p.AutoKey] = p
		default:
			elsewhere = append(elsewhere, p)
		}
	}

	keys := map[string]bool{}
	for k := range groups {
		keys[k] = true
	}
	for k := range ours {
		keys[k] = true
	}
	ordered := make([]string, 0, len(keys))
	for k := range keys {
		ordered = append(ordered, k)
	}
	sort.Slice(ordered, func(i, j int) bool {
		ai, ci, _ := store.ParseAutoKey(ordered[i])
		aj, cj, _ := store.ParseAutoKey(ordered[j])
		if ci.Rank() != cj.Rank() {
			return ci.Rank() < cj.Rank()
		}
		return ai < aj
	})

	for _, key := range ordered {
		arch, class, ok := store.ParseAutoKey(key)
		if !ok {
			continue
		}
		existing := ours[key]
		g := groups[key]

		var members []*store.Host
		backend := store.BackendKind("")
		if existing != nil {
			backend = existing.Backend
		}
		if g != nil {
			if backend == "" {
				backend = autoBackend(g.hosts)
			}
			for _, h := range g.hosts {
				if backend != "" && slices.Contains(h.Backends, string(backend)) {
					members = append(members, h)
				} else {
					reasons[h.ID] = SkipBackend
					plan.Skipped = append(plan.Skipped, HostSkip{Host: h, Reason: SkipBackend})
				}
			}
		}

		if existing == nil {
			if len(members) == 0 {
				continue
			}
			if clash := autoCollision(in, arch, class); clash != nil {
				plan.Findings = append(plan.Findings, *clash)
				continue
			}
			desired := NewAutoPool(in, arch, class, backend)
			slots := autoSlots(desired, members, size)
			plan.Slots[key] = slots
			desired.MaxRunners = capped(slots, desired.AutoCap)
			desired.MinRunners = min(desired.AutoMin, desired.MaxRunners)
			plan.Members[key] = hostNames(members)
			plan.Changes = append(plan.Changes, AutoPoolChange{
				Kind: AutoPoolCreate, Key: key, After: desired, Hosts: hostNames(members), Slots: slots,
				Cause: fmt.Sprintf("no pool existed for %s %s hosts, and %s has joined: %s",
					class, archPhrase(arch), hostPhrase(members), joinedWithHosts(members, slots)),
			})
			continue
		}

		desired := *existing
		reshaped := reshape(in, &desired, arch, class)
		slots := autoSlots(&desired, members, size)
		plan.Slots[key] = slots
		desired.MaxRunners = capped(slots, desired.AutoCap)
		desired.MinRunners = min(desired.AutoMin, desired.MaxRunners)
		desired.Enabled = len(members) > 0 && !desired.AutoPaused
		if len(members) == 0 {
			desired.MinRunners, desired.MaxRunners = 0, 0
		}
		plan.Members[key] = hostNames(members)

		change := AutoPoolChange{Key: key, Before: existing, After: &desired, Hosts: hostNames(members), Slots: slots, Reshaped: reshaped}
		derived := existing.MinRunners != desired.MinRunners || existing.MaxRunners != desired.MaxRunners ||
			existing.Enabled != desired.Enabled
		switch {
		case !derived && !reshaped:
			if clash := labelClash(in, existing, class); clash != nil {
				plan.Findings = append(plan.Findings, *clash)
			}
			continue
		case desired.AutoPaused && existing.Enabled:
			change.Kind = AutoPoolDisable
			change.Cause = "an operator paused the pool, so it takes no new work whatever its hosts do"
		case len(members) == 0 && existing.Enabled:
			change.Kind = AutoPoolDisable
			change.Cause = fmt.Sprintf("no %s %s host is left to take work", class, archPhrase(arch))
			if left := leftParts(in.Previous[key], nil, in.Hosts, reasons); len(left) > 0 {
				change.Cause += ": " + strings.Join(left, "; ")
			}
		case len(members) > 0 && !existing.Enabled && !existing.AutoPaused:
			change.Kind = AutoPoolEnable
			change.Cause = fmt.Sprintf("%s is back, so the pool is in use again with room for %s",
				hostPhrase(members), plural(desired.MaxRunners, "runner"))
			// A pool whose hosts were all there the last time we looked was not
			// out of use for want of one: someone paused it, and has stopped.
			if len(in.Previous[key]) > 0 {
				change.Cause = fmt.Sprintf("an operator resumed the pool, so it is in use again with room for %s", plural(desired.MaxRunners, "runner"))
			}
		case derived:
			change.Kind = AutoPoolResize
			change.Cause = resizeCause(existing, &desired, in.Previous[key], members, in.Hosts, reasons, slots)
		default:
			change.Kind = AutoPoolReshape
			change.Cause = "its fixed settings were brought back in line with the automatic pool settings"
		}
		if reshaped && change.Kind != AutoPoolReshape {
			change.Cause += "; its fixed settings were also brought back in line with the automatic pool settings"
		}
		plan.Changes = append(plan.Changes, change)
		if clash := labelClash(in, existing, class); clash != nil {
			plan.Findings = append(plan.Findings, *clash)
		}
	}

	// A pool the controller keeps for an installation that is no longer the one
	// in use is not ours to leave scaling. It is put out of use, as a pool with
	// no hosts is, and kept.
	for _, p := range elsewhere {
		if !p.Enabled && p.MaxRunners == 0 {
			continue
		}
		after := *p
		after.Enabled, after.MinRunners, after.MaxRunners = false, 0, 0
		plan.Changes = append(plan.Changes, AutoPoolChange{
			Kind: AutoPoolDisable, Key: p.AutoKey, Before: p, After: &after,
			Cause: "automatic pools now use another GitHub App installation, so this one is put out of use",
		})
	}

	plan.Findings = append(plan.Findings, skippedFindings(plan.Skipped)...)
	return plan
}

// autoClassOf is the architecture and class a host counts under, or the reason
// it counts under none.
func autoClassOf(h *store.Host, in AutoPoolInput) (arch string, class store.SizeClass, reason string) {
	switch {
	case h.Cordoned:
		return "", "", SkipCordoned
	case h.Incompatible:
		return "", "", SkipIncompatible
	case in.Now.Sub(laterOf(h.LastHeartbeat, in.Since)) > in.Grace:
		return "", "", SkipSilent
	}
	arch = naming.NormalizeArch(h.Arch)
	if arch == "" {
		return "", "", SkipArch
	}
	class, operator := h.EffectiveSizeClass()
	switch {
	case class.Valid():
		return arch, class, ""
	case operator:
		return "", "", SkipBadSize
	}
	return "", "", SkipNoClass
}

func laterOf(a, b time.Time) time.Time {
	if b.After(a) {
		return b
	}
	return a
}

// autoBackend is the backend a new pool is made for: docker where any of the
// hosts offers it, and otherwise podman. A host that offers neither is not a
// host the runner image can run on.
func autoBackend(hosts []*store.Host) store.BackendKind {
	for _, b := range []store.BackendKind{store.BackendDocker, store.BackendPodman} {
		if slices.ContainsFunc(hosts, func(h *store.Host) bool { return slices.Contains(h.Backends, string(b)) }) {
			return b
		}
	}
	return ""
}

// autoCollision reports an operator's pool that already uses the name or the
// class label a new pool would be made with. It is never taken over, and the
// pool is not made: two pools answering to the same class label would split the
// jobs that ask for it between a pool the operator tunes and one they did not
// ask for.
func autoCollision(in AutoPoolInput, arch string, class store.SizeClass) *AutoPoolFinding {
	name := AutoPoolName(arch, class)
	for _, p := range sortedPools(in.Pools) {
		// A pool kept for another installation, which stays where it is when the
		// installation the pools belong to is changed, still holds the name: pool
		// names are unique across the whole instance, so the pool for this one
		// cannot be made while it does. Said, because the alternative is a pool
		// that is never made and a finding-free fleet that wonders why.
		if p.FromHosts() && p.InstallationID != in.InstallationID && store.NormalizeLabel(p.Name) == store.NormalizeLabel(name) {
			return &AutoPoolFinding{Code: FindingNameTaken, Subject: name,
				Message: fmt.Sprintf("the pool for %s %s hosts would be called %s, which is the name of the pool the controller kept for another GitHub App installation before automatic pools were moved to this one", class, archPhrase(arch), name),
				Fix:     fmt.Sprintf("delete pool %s, which is out of use and holds the name, and the automatic pool for this installation will be made on the next pass.", p.Name)}
		}
		if p.FromHosts() {
			continue
		}
		if store.NormalizeLabel(p.Name) == store.NormalizeLabel(name) {
			return &AutoPoolFinding{Code: FindingNameTaken, Subject: name,
				Message: fmt.Sprintf("the pool for %s %s hosts would be called %s, which is the name of a pool you made", class, archPhrase(arch), name),
				Fix:     fmt.Sprintf("rename pool %s, or move its hosts into the automatic pool by removing its host selector and letting this one take them.", p.Name)}
		}
		if p.InstallationID == in.InstallationID && slices.Contains(store.NormalizeLabels(p.Labels), class.Label()) {
			return &AutoPoolFinding{Code: FindingLabelTaken, Subject: name,
				Message: fmt.Sprintf("pool %s already answers to %s, the label the pool for %s hosts would use, so jobs that ask for it would be split between the two", p.Name, class.Label(), class),
				Fix:     fmt.Sprintf("take %s off pool %s, or rename it, and the automatic pool will be made on the next pass.", class.Label(), p.Name)}
		}
	}
	return nil
}

// labelClash reports an operator's pool that answers to the class label of a
// pool the controller already keeps, which is how it happens when the operator's
// pool came second: autoCollision stops a new automatic pool being made beside
// one of theirs, and nothing stopped them making theirs beside it. It is a
// finding and not a refusal -- the pool is theirs, and so is the label -- but the
// two split the jobs that ask for the class between them, which is the thing the
// controller refuses to cause.
func labelClash(in AutoPoolInput, kept *store.Pool, class store.SizeClass) *AutoPoolFinding {
	for _, p := range sortedPools(in.Pools) {
		if p.FromHosts() || p.InstallationID != kept.InstallationID || !p.Enabled ||
			!slices.Contains(store.NormalizeLabels(p.Labels), class.Label()) {
			continue
		}
		return &AutoPoolFinding{Code: FindingLabelTaken, Subject: kept.Name,
			Message: fmt.Sprintf("pool %s answers to %s as well as the pool %s the controller keeps for %s hosts, so jobs that ask for it are split between the two", p.Name, class.Label(), kept.Name, class),
			Fix:     fmt.Sprintf("take %s off pool %s, or rename it and give it a label of its own.", class.Label(), p.Name)}
	}
	return nil
}

// reshape lays the fixed fields of a pool of this class over p and reports
// whether any of them differed.
func reshape(in AutoPoolInput, p *store.Pool, arch string, class store.SizeClass) bool {
	want := NewAutoPool(in, arch, class, p.Backend)
	changed := false
	set := func(differs bool, apply func()) {
		if differs {
			apply()
			changed = true
		}
	}
	set(!slices.Equal(store.NormalizeLabels(p.Labels), store.NormalizeLabels(want.Labels)), func() { p.Labels = want.Labels })
	set(p.Platform != want.Platform, func() { p.Platform = want.Platform })
	set(!sameSelector(p.HostSelector, want.HostSelector), func() { p.HostSelector = want.HostSelector })
	set(!p.SizeFromProfile, func() { p.SizeFromProfile = true })
	set(p.DockerMode != want.DockerMode, func() { p.DockerMode = want.DockerMode })
	set(!p.Ephemeral, func() { p.Ephemeral = true })
	set(p.Resources != (store.Resources{}), func() { p.Resources = store.Resources{} })
	return changed
}

func sameSelector(a, b store.StringMap) bool {
	if len(a) != len(b) {
		return false
	}
	for k, v := range a {
		if b[k] != v {
			return false
		}
	}
	return true
}

// autoSlots is how many runners of p the hosts hold between them: each host's
// room for the pool as the scheduler sizes it, which already accounts for the
// host's slot count, any throttle, its profile and whether the pool is kept off
// it by a size.
func autoSlots(p *store.Pool, hosts []*store.Host, size func(*store.Pool) *store.Pool) int {
	sized := size(p)
	total := 0
	for _, h := range hosts {
		total += HostRoomFor(withoutLiveDisk(h), sized).Room
	}
	return total
}

// withoutLiveDisk is a copy of h that has measured no disk. A pool's maximum is
// how many runners the machine can hold, and the free space on it is a reading
// that moves with every image pulled and every cache written: a host that
// crossed its disk reserve and came back would take its slots out of the pool
// and put them back, a line in the audit log each way and a pool disabled in
// between, for what the scheduler already does by itself -- it places nothing on
// a host whose disk is full, whatever the pool's maximum says.
func withoutLiveDisk(h *store.Host) *store.Host {
	c := *h
	c.DiskTotalMB, c.DiskFreeMB = 0, 0
	return &c
}

// capped applies an operator's cap; zero is none.
func capped(slots, cap int) int {
	if cap > 0 {
		return min(slots, cap)
	}
	return slots
}

func hostNames(hosts []*store.Host) []string {
	out := make([]string, len(hosts))
	for i, h := range hosts {
		out[i] = h.Name
	}
	return out
}

func archPhrase(arch string) string {
	if arch == naming.ArchAMD64 {
		return "x64"
	}
	return arch
}

func hostPhrase(hosts []*store.Host) string {
	switch len(hosts) {
	case 0:
		return "no host"
	case 1:
		return "host " + naming.ForSentence(hosts[0].Name)
	}
	return plural(len(hosts), "host")
}

func joinedWithHosts(hosts []*store.Host, slots int) string {
	names := hostNames(hosts)
	for i, n := range names {
		names[i] = naming.ForSentence(n)
	}
	return fmt.Sprintf("%s (%s)", strings.Join(names, ", "), plural(slots, "slot"))
}

// resizeCause says what moved a pool's maximum, from who joined and who left
// since the last look. Without a last look it can only say what the pool is now.
func resizeCause(before, after *store.Pool, previous []string, members, all []*store.Host, reasons map[string]string, slots int) string {
	head := fmt.Sprintf("maximum runners %d → %d", before.MaxRunners, after.MaxRunners)
	if before.MaxRunners == after.MaxRunners {
		head = fmt.Sprintf("warm runners %d → %d", before.MinRunners, after.MinRunners)
	}
	if previous == nil {
		return fmt.Sprintf("%s: recomputed from %s, %s", head, hostPhrase(members), plural(slots, "slot"))
	}
	now := hostNames(members)
	var parts []string
	for _, n := range now {
		if !slices.Contains(previous, n) {
			parts = append(parts, "host "+naming.ForSentence(n)+" joined")
		}
	}
	parts = append(parts, leftParts(previous, now, all, reasons)...)
	if len(parts) == 0 {
		switch {
		case before.MaxRunners == after.MaxRunners:
			parts = append(parts, fmt.Sprintf("an operator asked for %s kept warm", plural(after.AutoMin, "runner")))
		case after.AutoCap > 0 && slots > after.AutoCap:
			parts = append(parts, fmt.Sprintf("an operator capped the pool at %s", plural(after.AutoCap, "runner")))
		default:
			parts = append(parts, fmt.Sprintf("the slots of %s changed", hostPhrase(members)))
		}
	}
	return head + ": " + strings.Join(parts, "; ")
}

// leftParts names the hosts that counted last time and do not now, and why: a
// host that is cordoned, one that has gone quiet, one that is gone.
func leftParts(previous, now []string, all []*store.Host, reasons map[string]string) []string {
	var parts []string
	byName := map[string]*store.Host{}
	for _, h := range all {
		byName[h.Name] = h
	}
	for _, n := range previous {
		if slices.Contains(now, n) {
			continue
		}
		if h := byName[n]; h != nil {
			parts = append(parts, "host "+naming.ForSentence(n)+" "+skipPhrase(reasons[h.ID]))
		} else {
			parts = append(parts, "host "+naming.ForSentence(n)+" was removed")
		}
	}
	return parts
}

func skipPhrase(reason string) string {
	switch reason {
	case SkipCordoned:
		return "was cordoned"
	case SkipIncompatible:
		return "runs an agent this controller cannot place work on"
	case SkipSilent:
		return "has not been heard from for too long"
	case SkipBackend:
		return "offers no backend this pool can use"
	case SkipBadSize:
		return "has a size label that is not a class"
	case SkipArch:
		return "reports an architecture no pool is kept for"
	case SkipNoClass:
		return "has no class yet"
	}
	return "no longer counts"
}

// skippedFindings turns the hosts left out for a reason an operator has to act
// on into findings. A cordon or a silence is not one: both are things a fleet
// does, and both end by themselves.
func skippedFindings(skipped []HostSkip) []AutoPoolFinding {
	var out []AutoPoolFinding
	for _, s := range skipped {
		label := naming.ForSentence(s.Host.Name)
		var fix string
		switch s.Reason {
		case SkipBadSize:
			fix = fmt.Sprintf("set the size tag on host %s to small, medium or large exactly as written here, or remove it to let the controller work it out.", label)
		case SkipArch:
			fix = fmt.Sprintf("host %s reports %q; automatic pools are kept for amd64 and arm64 hosts only.", label, naming.ForSentence(s.Host.Arch))
		case SkipBackend:
			fix = fmt.Sprintf("host %s offers no backend the pool for its class uses; enable Docker or Podman on it.", label)
		default:
			continue
		}
		out = append(out, AutoPoolFinding{Code: FindingHostSkipped, Subject: s.Host.Name,
			Message: fmt.Sprintf("host %s is in no automatic pool: it %s", label, skipPhrase(s.Reason)), Fix: fix})
	}
	return out
}

package scheduler

import (
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// autoHost is a host with a held class, the way the controller leaves one after
// it has looked: sixteen slots, so that the machine and not the slot count is
// what limits it.
func autoHost(name string, cpus int, memoryMB int64, class store.SizeClass, opts ...func(*store.Host)) *store.Host {
	h := &store.Host{
		ID: "host_" + name, Name: name, CPUs: cpus, MemoryMB: memoryMB, Capacity: 16,
		Arch: "amd64", OS: "linux", Backends: store.StringSlice{"docker"},
		LastHeartbeat: sizeEpoch, SizeClass: store.HostSizeClass{Class: class},
	}
	for _, o := range opts {
		o(h)
	}
	return h
}

func arch(a string) func(*store.Host) { return func(h *store.Host) { h.Arch = a } }
func cordoned(h *store.Host)          { h.Cordoned = true }
func silentFor(d time.Duration) func(*store.Host) {
	return func(h *store.Host) { h.LastHeartbeat = sizeEpoch.Add(-d) }
}
func labelled(k, v string) func(*store.Host) {
	return func(h *store.Host) {
		if h.Labels == nil {
			h.Labels = store.StringMap{}
		}
		h.Labels[k] = v
	}
}
func offering(backends ...string) func(*store.Host) {
	return func(h *store.Host) { h.Backends = backends }
}

// sizingFor is the hook the controller supplies: a pool kept for a class is
// sized by that class's runner where the host says nothing of its own.
func sizingFor(cfg SizeConfig) func(*store.Pool) *store.Pool {
	return func(p *store.Pool) *store.Pool {
		if !p.FromHosts() {
			return p
		}
		_, class, _ := store.ParseAutoKey(p.AutoKey)
		cp := *p
		cp.FleetStandard = cfg.Runner(class)
		return &cp
	}
}

func autoInput(hosts []*store.Host, pools ...*store.Pool) AutoPoolInput {
	return AutoPoolInput{
		Now: sizeEpoch, Hosts: hosts, Pools: pools, InstallationID: "inst_1",
		Grace: 10 * time.Minute, Size: sizingFor(DefaultSizeConfig()),
	}
}

// existing is a pool the controller made earlier, as the store would return it.
func existing(in AutoPoolInput, a string, class store.SizeClass, max int, enabled bool) *store.Pool {
	p := NewAutoPool(in, a, class, store.BackendDocker)
	p.ID = "pool_" + a + "_" + string(class)
	p.MaxRunners, p.Enabled = max, enabled
	return p
}

// apply is what the controller does with a plan, for the tests that run it
// again: creates are stored, and every other change replaces the pool.
func apply(pools []*store.Pool, plan AutoPoolPlan) []*store.Pool {
	out := slices.Clone(pools)
	for _, c := range plan.Changes {
		after := *c.After
		if c.Kind == AutoPoolCreate {
			after.ID = "pool_" + c.Key
			out = append(out, &after)
			continue
		}
		for i, p := range out {
			if p.ID == c.Before.ID {
				out[i] = &after
			}
		}
	}
	return out
}

func changeFor(t *testing.T, plan AutoPoolPlan, key string) AutoPoolChange {
	t.Helper()
	for _, c := range plan.Changes {
		if c.Key == key {
			return c
		}
	}
	t.Fatalf("no change for %s in %+v", key, plan.Changes)
	return AutoPoolChange{}
}

func TestTheFirstHostOfAClassMakesItsPool(t *testing.T) {
	in := autoInput([]*store.Host{autoHost("build-1", 12, 32768, store.SizeMedium)})
	plan := PlanAutoPools(in)
	if len(plan.Changes) != 1 {
		t.Fatalf("a host with no pool for its class made %d changes: %+v", len(plan.Changes), plan.Changes)
	}
	c := plan.Changes[0]
	p := c.After
	if c.Kind != AutoPoolCreate || c.Key != "amd64/medium" || c.Before != nil {
		t.Fatalf("change = %+v", c)
	}
	if p.Name != "zoomies-medium" || !p.FromHosts() || p.AutoKey != "amd64/medium" || p.InstallationID != "inst_1" {
		t.Errorf("the pool is %+v", p)
	}
	if want := []string{"linux", "x64", "zoomies", "zoomies-medium"}; !slices.Equal(store.NormalizeLabels(p.Labels), want) {
		t.Errorf("labels = %v, want %v: the base label, the class, and the two that keep another machine's jobs off it", p.Labels, want)
	}
	if !p.SizeFromProfile || p.Platform.Arch != "amd64" || p.HostSelector[store.LabelSize] != "medium" || len(p.HostSelector) != 1 {
		t.Errorf("a pool for a class takes its size from the host, on the right machine and class: %+v", p)
	}
	if p.Backend != store.BackendDocker || !p.Ephemeral || !p.Enabled || p.Resources != (store.Resources{}) {
		t.Errorf("the pool's fixed settings are %+v", p)
	}
	// A 12-CPU, 32 GB host has 11.4 CPUs and 31130 MB left, and a medium runner
	// is 2 CPUs and 4 GB: five by CPU and seven by memory.
	if p.MaxRunners != 5 || p.MinRunners != 0 || c.Slots != 5 || !slices.Equal(c.Hosts, []string{"build-1"}) {
		t.Errorf("max %d, min %d, %d slots for %v; want 5, 0, 5 for build-1", p.MaxRunners, p.MinRunners, c.Slots, c.Hosts)
	}
	if !strings.Contains(c.Cause, "build-1") || !strings.Contains(c.Cause, "5 slots") {
		t.Errorf("the cause %q does not say which host and how many slots", c.Cause)
	}
	if got := plan.Members["amd64/medium"]; !slices.Equal(got, []string{"build-1"}) {
		t.Errorf("members = %v", got)
	}
}

func TestAHostJoiningRaisesTheMaximumByItsSlotsAndNothingIsRestarted(t *testing.T) {
	a, b := autoHost("build-1", 12, 32768, store.SizeMedium), autoHost("build-2", 12, 32768, store.SizeMedium)
	in := autoInput([]*store.Host{a, b})
	in.Pools = []*store.Pool{existing(in, "amd64", store.SizeMedium, 5, true)}
	in.Previous = map[string][]string{"amd64/medium": {"build-1"}}

	plan := PlanAutoPools(in)
	c := changeFor(t, plan, "amd64/medium")
	if c.Kind != AutoPoolResize || c.After.MaxRunners != 10 || c.Before.MaxRunners != 5 {
		t.Fatalf("a second host made %+v", c)
	}
	if c.Cause != "maximum runners 5 → 10: host build-2 joined" {
		t.Errorf("cause = %q", c.Cause)
	}
	if len(plan.Changes) != 1 {
		t.Errorf("a host joining changed more than its own pool: %+v", plan.Changes)
	}
	// Without a last look the cause can only say what the pool is now.
	in.Previous = nil
	if c := changeFor(t, PlanAutoPools(in), "amd64/medium"); !strings.Contains(c.Cause, "recomputed from 2 hosts, 10 slots") {
		t.Errorf("cause = %q", c.Cause)
	}
}

// A host that is cordoned, quiet for too long or running an agent this
// controller cannot place work on takes no new runners, so the pool does not
// promise its slots. A host that was merely quiet for a while still counts: that
// is what the grace is for.
func TestACordonedSilentOrIncompatibleHostStopsCounting(t *testing.T) {
	cases := []struct {
		name   string
		opt    func(*store.Host)
		counts bool
		text   string
	}{
		{"a cordon", cordoned, false, "host build-2 was cordoned"},
		{"quiet for longer than the grace", silentFor(11 * time.Minute), false, "host build-2 has not been heard from for too long"},
		{"quiet for less than the grace", silentFor(9 * time.Minute), true, ""},
		{"an agent this controller cannot place work on", func(h *store.Host) { h.Incompatible = true }, false, "runs an agent this controller cannot place work on"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			a, b := autoHost("build-1", 12, 32768, store.SizeMedium), autoHost("build-2", 12, 32768, store.SizeMedium, tc.opt)
			in := autoInput([]*store.Host{a, b})
			in.Pools = []*store.Pool{existing(in, "amd64", store.SizeMedium, 10, true)}
			in.Previous = map[string][]string{"amd64/medium": {"build-1", "build-2"}}
			plan := PlanAutoPools(in)
			if tc.counts {
				if len(plan.Changes) != 0 {
					t.Fatalf("a host inside the grace changed the pool: %+v", plan.Changes)
				}
				return
			}
			c := changeFor(t, plan, "amd64/medium")
			if c.After.MaxRunners != 5 || !c.After.Enabled || !strings.Contains(c.Cause, tc.text) {
				t.Fatalf("the pool after losing a host = max %d, enabled %v, cause %q; want 5, true and %q",
					c.After.MaxRunners, c.After.Enabled, c.Cause, tc.text)
			}
		})
	}
}

// Running jobs finish and nothing new is placed on the host: the plan lowers the
// maximum and does not touch a runner, which is the scheduler's to drain or let
// finish.
func TestTheLastHostGoingDisablesThePoolAndKeepsItWithItsHistory(t *testing.T) {
	in := autoInput([]*store.Host{autoHost("build-1", 12, 32768, store.SizeMedium, cordoned)})
	pool := existing(in, "amd64", store.SizeMedium, 5, true)
	pool.MinRunners = 0
	in.Pools = []*store.Pool{pool}
	in.Previous = map[string][]string{"amd64/medium": {"build-1"}}

	plan := PlanAutoPools(in)
	c := changeFor(t, plan, "amd64/medium")
	if c.Kind != AutoPoolDisable || c.After.Enabled || c.After.MaxRunners != 0 || c.After.MinRunners != 0 {
		t.Fatalf("the last host cordoned made %+v", c)
	}
	if c.After.ID != pool.ID || c.After.Name != pool.Name || c.After.AutoKey != pool.AutoKey {
		t.Fatalf("the pool lost its record: %+v", c.After)
	}
	if want := "no medium x64 host is left to take work: host build-1 was cordoned"; c.Cause != want {
		t.Errorf("cause = %q, want %q", c.Cause, want)
	}

	// Planning again from the disabled pool changes nothing: the pool is where it should be.
	in.Pools = apply(in.Pools, plan)
	if again := PlanAutoPools(in); len(again.Changes) != 0 {
		t.Fatalf("a disabled pool with no hosts was changed again: %+v", again.Changes)
	}

	// A host of the class comes back: the pool is in use again.
	in.Hosts = []*store.Host{autoHost("build-1", 12, 32768, store.SizeMedium)}
	in.Previous = map[string][]string{"amd64/medium": nil}
	back := changeFor(t, PlanAutoPools(in), "amd64/medium")
	if back.Kind != AutoPoolEnable || !back.After.Enabled || back.After.MaxRunners != 5 || !strings.Contains(back.Cause, "host build-1 is back") {
		t.Fatalf("a returning host made %+v", back)
	}
}

// A pool's page says what its maximum is made of, so the plan reports the room
// the hosts give each pool whether or not anything about it has to change.
func TestThePlanSaysWhatRoomEachPoolsHostsGiveItWhetherOrNotItChanges(t *testing.T) {
	hosts := []*store.Host{
		autoHost("build-1", 12, 32768, store.SizeMedium),
		autoHost("build-2", 12, 32768, store.SizeMedium),
		autoHost("tiny-1", 4, 16384, store.SizeSmall),
	}
	in := autoInput(hosts)
	plan := PlanAutoPools(in)
	if plan.Slots["amd64/medium"] != 10 || plan.Slots["amd64/small"] != 3 {
		t.Fatalf("slots = %v; two medium hosts give ten and a small one three", plan.Slots)
	}
	in.Pools = apply(in.Pools, plan)
	again := PlanAutoPools(in)
	if len(again.Changes) != 0 || again.Slots["amd64/medium"] != 10 || again.Slots["amd64/small"] != 3 {
		t.Fatalf("a pass with nothing to change reports slots %v and %d changes", again.Slots, len(again.Changes))
	}
	// A cap lowers the maximum and not what the hosts give.
	for _, p := range in.Pools {
		if p.AutoKey == "amd64/medium" {
			p.AutoCap = 4
		}
	}
	again = PlanAutoPools(in)
	if c := changeFor(t, again, "amd64/medium"); c.After.MaxRunners != 4 || again.Slots["amd64/medium"] != 10 {
		t.Fatalf("a cap of four made a maximum of %d and reported %v as what the hosts give", c.After.MaxRunners, again.Slots)
	}
}

// The figures docs/auto-pools.md works its example from, so that the page and the
// code cannot disagree about what a 12-CPU machine is, or how many runners of a
// class a host holds.
func TestTheWorkedExampleInTheDocsGivesTheFiguresTheDocsPrint(t *testing.T) {
	eight := func(h *store.Host) { h.Capacity = 8 }
	machines := []struct {
		name         string
		cpus         int
		memoryMB     int64
		class        store.SizeClass
		allocCPUs    float64
		allocMemory  int64
		wantSlots    int
		wantPoolName string
	}{
		{"big-1", 32, 131072, store.SizeLarge, 30.4, 124519, 7, "zoomies-large"},
		{"build-1", 12, 32768, store.SizeMedium, 11.4, 31130, 5, "zoomies-medium"},
		{"build-2", 12, 32768, store.SizeMedium, 11.4, 31130, 5, "zoomies-medium"},
		{"tiny-1", 4, 16384, store.SizeSmall, 3.5, 15565, 3, "zoomies-small"},
		{"tiny-2", 4, 16384, store.SizeSmall, 3.5, 15565, 3, "zoomies-small"},
	}
	cfg := DefaultSizeConfig()
	var hosts []*store.Host
	for _, m := range machines {
		h := autoHost(m.name, m.cpus, m.memoryMB, "", eight)
		a := h.Allocatable()
		if a.CPUs != m.allocCPUs || a.MemoryMB != m.allocMemory {
			t.Errorf("%s has %v CPUs and %d MB allocatable, the page says %v and %d", m.name, a.CPUs, a.MemoryMB, m.allocCPUs, m.allocMemory)
		}
		if class, ok := cfg.HostClass(h); !ok || class != m.class {
			t.Errorf("%s is in class %q, the page says %s", m.name, class, m.class)
		}
		h.SizeClass = store.HostSizeClass{Class: m.class}
		if room := HostRoomFor(h, sizingFor(cfg)(NewAutoPool(autoInput(nil), "amd64", m.class, store.BackendDocker))).Room; room != m.wantSlots {
			t.Errorf("%s holds %d runners of the %s class, the page says %d", m.name, room, m.class, m.wantSlots)
		}
		hosts = append(hosts, h)
	}
	plan := PlanAutoPools(autoInput(hosts))
	got := map[string]int{}
	for _, c := range plan.Changes {
		got[c.After.Name] = c.After.MaxRunners
	}
	if got["zoomies-large"] != 7 || got["zoomies-medium"] != 10 || got["zoomies-small"] != 6 || len(got) != 3 {
		t.Fatalf("the pools' maximums are %v; the page says 7, 10 and 6", got)
	}
}

