// A pool that needs its limits moved and its fixed settings corrected at once is
// one change that says both, so the controller can write both in one statement.
// Applied as limits alone, the second half waited for the next pass, and each of
// the two passes wrote an audit row for what was really one decision.
func TestAPoolThatNeedsBothItsLimitsAndItsFixedSettingsCorrectedIsOneChange(t *testing.T) {
	in := autoInput([]*store.Host{autoHost("build-1", 12, 32768, store.SizeMedium)})
	pool := existing(in, "amd64", store.SizeMedium, 2, true)
	pool.Labels = store.StringSlice{"zoomies", "zoomies-medium", "linux", "x64", "left-behind"}
	plan := PlanAutoPools(autoInput([]*store.Host{autoHost("build-1", 12, 32768, store.SizeMedium)}, pool))

	if len(plan.Changes) != 1 {
		t.Fatalf("changes = %+v; want the one", plan.Changes)
	}
	c := plan.Changes[0]
	if c.Kind != AutoPoolResize || !c.Reshaped {
		t.Fatalf("the change is %s, reshaped %v; want a resize that also reshapes", c.Kind, c.Reshaped)
	}
	if !strings.Contains(c.Cause, "also brought back in line") {
		t.Errorf("the cause %q does not say the fixed settings were corrected too", c.Cause)
	}
	if slices.Contains(c.After.Labels, "left-behind") || c.After.MaxRunners != 5 {
		t.Errorf("the pool after is %+v", c.After)
	}
	// And a pool that needs only one of the two says only that.
	only := existing(in, "amd64", store.SizeMedium, 5, true)
	only.Labels = store.StringSlice{"zoomies", "zoomies-medium", "linux", "x64", "left-behind"}
	plan = PlanAutoPools(autoInput([]*store.Host{autoHost("build-1", 12, 32768, store.SizeMedium)}, only))
	if len(plan.Changes) != 1 || plan.Changes[0].Kind != AutoPoolReshape || !plan.Changes[0].Reshaped {
		t.Fatalf("a pool whose limits are right and whose labels are not = %+v", plan.Changes)
	}
}

// Pool names are unique across the instance and a pool kept for the installation
// the pools used to belong to keeps its name when they are moved, so the pool for
// the new one cannot be made. It is said, with what to do about it.
func TestAPoolKeptForAnotherInstallationThatHoldsTheNameIsAFinding(t *testing.T) {
	hosts := []*store.Host{autoHost("build-1", 12, 32768, store.SizeMedium)}
	old := existing(AutoPoolInput{InstallationID: "inst_old"}, "amd64", store.SizeMedium, 5, false)
	plan := PlanAutoPools(autoInput(hosts, old))

	for _, c := range plan.Changes {
		if c.Kind == AutoPoolCreate {
			t.Fatalf("a pool was planned that the name already held: %+v", c)
		}
	}
	var named *AutoPoolFinding
	for i := range plan.Findings {
		if plan.Findings[i].Code == FindingNameTaken {
			named = &plan.Findings[i]
		}
	}
	if named == nil || !strings.Contains(named.Message, "another GitHub App installation") ||
		!strings.Contains(named.Fix, "delete pool zoomies-medium") {
		t.Fatalf("findings = %+v; want the name held by the old installation's pool to be said", plan.Findings)
	}
	// With the old pool gone the new one is made.
	plan = PlanAutoPools(autoInput(hosts))
	if len(plan.Changes) != 1 || plan.Changes[0].Kind != AutoPoolCreate {
		t.Fatalf("with the name free the plan is %+v", plan.Changes)
	}
}

// autoCollision stops the controller making a pool beside one an operator made,
// and nothing stopped an operator making theirs beside one the controller keeps.
// The two split the jobs that ask for the class, so it is said.
func TestAnOperatorPoolThatTakesTheClassLabelOfAKeptPoolIsAFinding(t *testing.T) {
	hosts := []*store.Host{autoHost("build-1", 12, 32768, store.SizeMedium)}
	in := autoInput(hosts)
	kept := existing(in, "amd64", store.SizeMedium, 5, true)
	mine := testPool("mine", "zoomies", "zoomies-medium", "linux", "x64")
	mine.InstallationID = "inst_1"

	plan := PlanAutoPools(autoInput(hosts, kept, mine))
	if len(plan.Changes) != 0 {
		t.Fatalf("a pool in order changed: %+v", plan.Changes)
	}
	if len(plan.Findings) != 1 || plan.Findings[0].Code != FindingLabelTaken || plan.Findings[0].Subject != "zoomies-medium" ||
		!strings.Contains(plan.Findings[0].Message, "pool mine answers to zoomies-medium") ||
		!strings.Contains(plan.Findings[0].Fix, "take zoomies-medium off pool mine") {
		t.Fatalf("findings = %+v", plan.Findings)
	}
	// A pool of theirs that does not carry the label, or is switched off, is none.
	other := testPool("other", "zoomies", "zoomies-ops", "linux", "x64")
	other.InstallationID = "inst_1"
	off := testPool("off", "zoomies", "zoomies-medium")
	off.InstallationID, off.Enabled = "inst_1", false
	if plan = PlanAutoPools(autoInput(hosts, kept, other, off)); len(plan.Findings) != 0 {
		t.Fatalf("findings = %+v for pools that do not split the class", plan.Findings)
	}
}

// A host that has crossed its disk reserve places nothing, and the scheduler
// already says so every pass. The pool's maximum is about what the machine holds:
// following the free space would put a line in the audit log every time a host
// dipped below the reserve and came back, and disable the pool in between.
func TestAHostLowOnDiskStillCountsItsSlotsTowardsThePoolsMaximum(t *testing.T) {
	roomy := autoHost("a", 12, 32768, store.SizeMedium, func(h *store.Host) { h.DiskTotalMB, h.DiskFreeMB = 500_000, 400_000 })
	full := autoHost("a", 12, 32768, store.SizeMedium, func(h *store.Host) { h.DiskTotalMB, h.DiskFreeMB = 500_000, 1_000 })
	slots := func(h *store.Host) int {
		plan := PlanAutoPools(autoInput([]*store.Host{h}))
		if len(plan.Changes) != 1 {
			t.Fatalf("changes = %+v; want the pool made", plan.Changes)
		}
		return plan.Slots["amd64/medium"]
	}
	if r, f := slots(roomy), slots(full); r != f || r == 0 {
		t.Fatalf("a host with 400 GB free holds %d runners and one with 1 GB free holds %d; the pool's maximum is not about the disk", r, f)
	}
	// The scheduler is the one that refuses the full host, and it still does.
	pool := NewAutoPool(autoInput(nil), "amd64", store.SizeMedium, store.BackendDocker)
	if room := HostRoomFor(full, sizingFor(DefaultSizeConfig())(pool)); room.Room != 0 || room.LimitedBy != "disk" {
		t.Fatalf("the full host's room is %+v; the scheduler places nothing on it", room)
	}
}

func TestSilenceIsCountedFromWhenTheControllerBeganListeningIfThatIsLater(t *testing.T) {
	quiet := autoHost("a", 12, 32768, store.SizeMedium, silentFor(3*time.Hour))
	in := autoInput([]*store.Host{quiet})
	if plan := PlanAutoPools(in); len(plan.Changes) != 0 || len(plan.Skipped) != 1 || plan.Skipped[0].Reason != SkipSilent {
		t.Fatalf("with no start time a host silent for three hours was %+v; want it dropped", plan)
	}

	in.Since = in.Now.Add(-time.Minute)
	plan := PlanAutoPools(in)
	if len(plan.Skipped) != 0 || len(plan.Changes) != 1 || plan.Changes[0].Kind != AutoPoolCreate {
		t.Fatalf("a host silent only while the controller was down was %+v; want it counted", plan)
	}

	// Not for ever: the grace runs from the later of the two.
	in.Since = in.Now.Add(-in.Grace - time.Minute)
	if plan := PlanAutoPools(in); len(plan.Skipped) != 1 {
		t.Fatalf("a host silent since before the grace ran from the start was %+v; want it dropped", plan.Skipped)
	}
}

package scheduler

import (
	"fmt"
	"math/rand/v2"
	"reflect"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// A claim does not need a whole pool. The controller reads the fields
// store.ClaimView keeps, and no others, to decide which pool takes a job, because
// reading the rest of every row was most of what a webhook cost at a hundred
// pools. This holds BestPool to that: each pool is filled in everywhere
// ClaimView lets go of it, with values no two pools share, and the job must land
// where it lands when those fields are gone. A choice that began to depend on,
// say, MaxRunners would come out differently here than it does for the
// controller, which never reads it, and this is where that would be found.

func TestChoosingAPoolDependsOnNothingAClaimViewLetsGoOf(t *testing.T) {
	rng := rand.New(rand.NewPCG(20261019, 7))
	routed, fromHosts, tied := 0, 0, 0
	for i := range 5000 {
		c := randomMatchingCase(rng)
		// Half the fleets fit the job equally well in every pool, so that the
		// choice between them is nothing but tie-break.
		if rng.IntN(2) == 0 {
			if tieFleet(&c) >= 2 {
				tied++
			}
		}
		// Routing by size class and the pools the controller keeps are what
		// lessPoolFor reads beyond a name, so some cases have them.
		if rng.IntN(3) == 0 {
			c.job.RoutedClass = store.SizeClasses()[rng.IntN(3)]
			routed++
		}
		for _, p := range c.pools {
			if p != nil && rng.IntN(3) == 0 {
				p.AutoKey = store.AutoKeyFor([]string{"amd64", "arm64"}[rng.IntN(2)], store.SizeClasses()[rng.IntN(3)])
				p.Platform.Arch = []string{"amd64", "arm64"}[rng.IntN(2)]
				fromHosts++
			}
		}

		whole := make([]*store.Pool, len(c.pools))
		view := make([]*store.Pool, len(c.pools))
		for k, p := range c.pools {
			if p != nil {
				whole[k] = withEverythingElse(p, k+1)
				view[k] = store.ClaimView(whole[k])
			}
		}
		wantPool, wantWhy := bestPool(whole, c.job, c.targets)
		gotPool, gotWhy := bestPool(view, c.job, c.targets)
		if indexIn(view, gotPool) != indexIn(whole, wantPool) || gotWhy != wantWhy {
			t.Fatalf("case %d: the claim views chose pool %d (%q), the whole pools pool %d (%q)\njob labels %q on installation %q routed to %q\npools:\n%s",
				i, indexIn(view, gotPool), gotWhy, indexIn(whole, wantPool), wantWhy,
				c.job.Labels, c.job.InstallationID, c.job.RoutedClass, describePools(whole))
		}
	}
	if routed < 1000 || fromHosts < 1000 || tied < 1000 {
		t.Fatalf("only %d cases were routed by class, %d pools were kept from hosts and %d fleets tied; the comparison needs all three", routed, fromHosts, tied)
	}
}

// tieFleet makes every pool fit the job exactly as well as the others, and
// returns how many pools there are to choose between.
func tieFleet(c *matchingCase) int {
	c.job.InstallationID = "ins_a"
	c.job.Labels = store.StringSlice{"gpu"}
	n := 0
	for _, p := range c.pools {
		if p != nil {
			p.InstallationID, p.Enabled, p.NoDefaultLabels = "ins_a", true, false
			p.Labels = store.StringSlice{"gpu", "linux"}
			n++
		}
	}
	return n
}

// indexIn is where a pool is among pools, or -1.
func indexIn(pools []*store.Pool, p *store.Pool) int {
	for i, q := range pools {
		if q != nil && q == p {
			return i
		}
	}
	return -1
}

// withEverythingElse is a copy of p with every field ClaimView lets go of, that p
// leaves unset, set to a value of its own. Which fields those are is found, not
// listed: a pool is filled in everywhere, and what its claim view lacks is what
// is let go. A value p sets itself on such a field is kept, so that a field the
// view should have kept, and a claim reads, is still there to be missed.
func withEverythingElse(p *store.Pool, seed int) *store.Pool {
	filled := &store.Pool{}
	fill(reflect.ValueOf(filled).Elem(), seed)
	kept := store.ClaimView(filled)

	out := *p
	letGo(reflect.ValueOf(&out).Elem(), reflect.ValueOf(filled).Elem(), reflect.ValueOf(kept).Elem())
	return &out
}

var timeType = reflect.TypeOf(time.Time{})

// fill sets every settable field under v to a value that is not the zero one.
func fill(v reflect.Value, seed int) {
	switch v.Kind() {
	case reflect.String:
		v.SetString(fmt.Sprintf("v%d", seed))
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		v.SetInt(int64(seed))
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		v.SetUint(uint64(seed))
	case reflect.Float32, reflect.Float64:
		v.SetFloat(float64(seed) + 0.5)
	case reflect.Bool:
		v.SetBool(true)
	case reflect.Slice:
		s := reflect.MakeSlice(v.Type(), 1, 1)
		fill(s.Index(0), seed)
		v.Set(s)
	case reflect.Map:
		m := reflect.MakeMap(v.Type())
		k, e := reflect.New(v.Type().Key()).Elem(), reflect.New(v.Type().Elem()).Elem()
		fill(k, seed)
		fill(e, seed)
		m.SetMapIndex(k, e)
		v.Set(m)
	case reflect.Pointer:
		n := reflect.New(v.Type().Elem())
		fill(n.Elem(), seed)
		v.Set(n)
	case reflect.Struct:
		if v.Type() == timeType {
			v.Set(reflect.ValueOf(time.Unix(int64(seed), 0).UTC()))
			return
		}
		for i := range v.NumField() {
			if f := v.Field(i); f.CanSet() {
				fill(f, seed)
			}
		}
	}
}

// letGo copies into dst each field of filled that kept does not have, where dst
// has none of its own.
func letGo(dst, filled, kept reflect.Value) {
	for i := range dst.NumField() {
		d, f, k := dst.Field(i), filled.Field(i), kept.Field(i)
		if !d.CanSet() || !f.CanInterface() {
			continue
		}
		switch {
		case f.Kind() == reflect.Struct && f.Type() != timeType:
			letGo(d, f, k)
		case d.IsZero() && !reflect.DeepEqual(f.Interface(), k.Interface()):
			d.Set(f)
		}
	}
}

package scheduler

import (
	"fmt"
	"math"
	"slices"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// How a job's class is worked out from its runs. These are the rules rather
// than settings: what an operator chooses is how big each class is and which
// one an unknown job starts in, and the evidence it takes to move a job is
// part of what the feature means. A figure that could be tuned per fleet would
// be one more thing to be wrong about when a job sits in the wrong class and
// somebody asks why.
const (
	// ClassWindow is how far back a job's runs count. A job rewritten a month
	// ago is classed on what it is now.
	ClassWindow = 14 * 24 * time.Hour

	// ClassRuns is how many of a job's newest runs its memory percentile and its
	// CPU evidence are worked out from: what it needs now, as the history sizing
	// of a pool reads it too. It is not how many runs the evidence for moving
	// down is read from. A job that runs a few times an hour has twenty runs
	// inside a day, and ten runs over a week "since it last moved" can only be
	// seen by looking further back than the newest twenty.
	ClassRuns = store.JobUsageHistoryLimit

	// DownRuns and DownSpan are the evidence it takes to move a job to a smaller
	// class: this many measured runs, spread over at least this long, every one
	// of which fits the smaller class. Moving up is quick because a job that
	// does not fit is killed, and moving down is slow because one that does
	// fit is only a little slower for the machine being too large; a class
	// that swung with every run would put the same job on a different host each
	// time.
	DownRuns = 10
	DownSpan = 7 * 24 * time.Hour

	// ThrottledShare is the share of its CPU periods a run is held back in for
	// the run to count as CPU-bound. The peak CPU of a build is its limit -- it
	// uses every core it is given -- so the peak says nothing about whether it
	// wanted more; being held back by the quota does.
	ThrottledShare = 0.25
	// ThrottleRuns is how many sampled runs it takes to say anything about a
	// job's CPU, and ThrottleFraction how many of them must be CPU-bound.
	ThrottleRuns     = 3
	ThrottleFraction = 0.5
	// ThrottleMinDuration is how long the CPU-bound runs must typically be. A
	// job that runs for twenty seconds is throttled in its first second by
	// arithmetic, and moving it up a class would buy it nothing.
	ThrottleMinDuration = 3 * time.Minute
)

// ClassifyInput is everything Classify decides from.
type ClassifyInput struct {
	// Labels are the job's runs-on labels. A size label among them is the whole
	// answer.
	Labels []string
	// Pin is an operator's pin for this job or its repository, or nil.
	Pin *store.SizePin
	// Runs are the job's measured runs that finished inside ClassWindow, newest
	// first. There may be many more than ClassRuns of them: the newest ClassRuns
	// say what the job needs, and all of them say how long it has been fitting a
	// smaller class.
	Runs []store.JobRun
	// Current is the class kept from the last time the job was worked out, or
	// nil if it never was.
	Current *store.JobClass
	Now     time.Time
}

// Classification is the answer: the class, the sentence for why, how it was
// reached, and what the history says the job needs.
type Classification struct {
	Class store.SizeClass
	// Reason finishes "classed X because": a lower-case clause that says what
	// decided it, in the words of the measurement.
	Reason string
	// Basis is one of the store.SizeBasis* constants.
	Basis string
	// FloorMB is the memory the job is known to need, and zero when its class
	// did not come from its runs.
	FloorMB int64
	// Runs is how many measured runs the answer was worked out from.
	Runs int
}

// Classify puts a job in a class.
//
// The order is the order of authority. A size label in the job's own runs-on
// is the author saying where it goes, and it is honoured whatever anyone
// measured. An operator's pin comes next, because it is a decision that takes
// the place of the measurements. Only then is the history asked, and with no
// history at all the job starts in the default class.
func (c SizeConfig) Classify(in ClassifyInput) Classification {
	if out, ok := c.authority(in.Labels, in.Pin); ok {
		return out
	}
	return c.fromRuns(in)
}

// authority is the part of the answer that does not depend on any measurement:
// a size label in the job's own runs-on, and an operator's pin.
func (c SizeConfig) authority(labels []string, pin *store.SizePin) (Classification, bool) {
	if class, ok := RequestedClass(labels); ok {
		return Classification{Class: class, Basis: store.SizeBasisExplicit,
			Reason: fmt.Sprintf("its runs-on asks for %s", class.Label())}, true
	}
	if pin != nil && pin.Class.Valid() {
		what := "this job"
		if pin.ForRepository() {
			what = "every job in " + pin.Repo
		}
		return Classification{Class: pin.Class, Basis: store.SizeBasisPin,
			Reason: fmt.Sprintf("an operator pinned %s to %s", what, pin.Class)}, true
	}
	return Classification{}, false
}

// RequestedClass is the class a runs-on asks for by name, if it does. A job that
// asks for two -- which no pool answers -- is taken to want the larger.
func RequestedClass(labels []string) (store.SizeClass, bool) {
	var out store.SizeClass
	for _, l := range labels {
		if k, ok := store.ClassOfLabel(l); ok && k.Rank() > out.Rank() {
			out = k
		}
	}
	return out, out != ""
}

// holding is the smallest class whose runner has at least mb of memory, and the
// largest class for a need that none does.
func (c SizeConfig) holding(mb int64) store.SizeClass {
	for _, k := range store.SizeClasses() {
		if c.Runner(k).MemoryMB >= mb {
			return k
		}
	}
	return store.SizeLarge
}

// defaultClass is the class of a job nothing is known about: the configured
// one, and small where that is not a class.
func (c SizeConfig) defaultClass() store.SizeClass {
	if c.DefaultClass.Valid() {
		return c.DefaultClass
	}
	return store.SizeSmall
}

func (c SizeConfig) fromRuns(in ClassifyInput) Classification {
	var current store.SizeClass
	var movedAt time.Time
	if in.Current != nil && in.Current.Class.Valid() {
		current, movedAt = in.Current.Class, in.Current.MovedAt
	}
	runs := in.Runs
	if len(runs) == 0 {
		if current != "" {
			return Classification{Class: current, Basis: store.SizeBasisHistory,
				Reason: fmt.Sprintf("it has had no measured run in the last %s, so it keeps the class it had", longSpan(ClassWindow))}
		}
		def := c.defaultClass()
		return Classification{Class: def, Basis: store.SizeBasisDefault,
			Reason: fmt.Sprintf("it has no measured runs yet, so it starts in the default class, %s", def)}
	}

	// What the job needs now is read from its newest runs; how long it has been
	// fitting a smaller class, below, from every run since it last moved.
	recent := runs[:min(len(runs), ClassRuns)]
	peaks := make([]store.JobPeak, len(recent))
	for i, r := range recent {
		peaks[i] = store.JobPeak{CPUs: r.PeakCPUs, MemoryMB: r.PeakMemoryMB, OOMKilled: r.OOMKilled}
	}
	req := Profile(peaks)
	memClass := c.holding(req.MemoryMB)

	// A run the kernel killed for memory is evidence that does not wait for a
	// percentile: its peak is the limit it hit, and the 90th percentile of
	// twenty runs ignores the two largest of them, which is exactly where a
	// single kill sits. Only kills since the class last moved count, because an
	// earlier one is what moved it.
	oomNeed, oomLimit := int64(0), int64(0)
	for _, r := range runs {
		if r.OOMKilled && r.CompletedAt.After(movedAt) {
			limit := max(r.PeakMemoryMB, r.GrantedMemoryMB)
			if need := roundUp(float64(limit)*ProfileOOMGrowth*ProfileMemoryMargin, profileMemoryStep); need > oomNeed {
				oomNeed, oomLimit = need, limit
			}
		}
	}
	oomClass := store.SizeSmall
	if oomNeed > 0 {
		oomClass = c.holding(oomNeed)
	}

	cpuClass, cpuNote := c.cpuClass(recent)

	proposed := memClass
	for _, k := range []store.SizeClass{oomClass, cpuClass} {
		if k.Rank() > proposed.Rank() {
			proposed = k
		}
	}
	floor := max(req.MemoryMB, oomNeed)
	out := Classification{Basis: store.SizeBasisHistory, FloorMB: floor, Runs: len(recent)}

	switch {
	case current == "" || proposed.Rank() > current.Rank():
		out.Class = proposed
		var because []string
		switch {
		case oomNeed > 0 && oomClass == proposed:
			because = append(because, fmt.Sprintf("the kernel killed a run for memory at %s, so it is taken to need about %s",
				formatMB(oomLimit), formatMB(oomNeed)))
		case memClass == proposed:
			because = append(because, c.memoryClause(req, len(recent), proposed))
		}
		if cpuClass == proposed && cpuNote != "" {
			because = append(because, cpuNote)
		}
		if len(because) == 0 {
			because = append(because, c.memoryClause(req, len(recent), proposed))
		}
		out.Reason = strings.Join(because, "; and ")
		if current != "" {
			out.Reason += fmt.Sprintf(", so it moved up from %s", current)
		}
	default:
		out.Class = current
		if lower, hasLower := current.Smaller(); hasLower {
			since := runsSince(runs, movedAt)
			fits, n, span, most := c.fitsBelow(since, lower)
			switch {
			// The runs since it moved fit the smaller class, and so does what
			// the newest runs say it needs. Without the second half a job whose
			// recent runs were light and whose earlier ones were heavy would move
			// down on the first, and be moved straight back up on the second the
			// next time it finished: two moves, and a job queued in between sent
			// to a host it does not fit.
			case fits && proposed.Rank() <= lower.Rank():
				out.Class, out.FloorMB = lower, most
				out.Reason = fmt.Sprintf("its last %d runs, over %s, all fit a %s runner (the most needed about %s), so it moved down from %s",
					n, longSpan(span), lower, formatMB(most), current)
				return out
			case proposed.Rank() < current.Rank():
				out.Reason = fmt.Sprintf("its runs would fit a %s runner, but moving down takes %d runs over %s since it moved to %s, and there have been %d over %s",
					proposed, DownRuns, longSpan(DownSpan), current, n, longSpan(span))
				return out
			}
		}
		out.Reason = c.memoryClause(req, len(recent), current)
		if cpuClass == current && cpuNote != "" {
			out.Reason += "; and " + cpuNote
		}
	}
	return out
}

// memoryClause is the sentence for a class chosen on memory.
func (c SizeConfig) memoryClause(req Requirement, runs int, class store.SizeClass) string {
	if req.MemoryMB <= 0 {
		return fmt.Sprintf("its last %d runs used almost no memory, which a %s runner holds", runs, class)
	}
	if limit := c.Runner(store.SizeLarge).MemoryMB; req.MemoryMB > limit && class == store.SizeLarge {
		return fmt.Sprintf("its memory needs about %s (the 90th percentile of %d runs, with a fifth added), which is more than a large runner has (%s)",
			formatMB(req.MemoryMB), runs, formatMB(limit))
	}
	return fmt.Sprintf("its memory needs about %s (the 90th percentile of %d runs, with a fifth added), which a %s runner holds",
		formatMB(req.MemoryMB), runs, class)
}

// cpuClass is the class a job's CPU evidence calls for, and the sentence for it:
// the smallest class whose runner has more CPU than the runs that were held
// back had. It is small, and says nothing, unless the job was sampled in enough
// runs, held back in enough of them, and long-running enough for being held
// back to cost it anything.
func (c SizeConfig) cpuClass(runs []store.JobRun) (store.SizeClass, string) {
	sampled, bound := 0, []store.JobRun{}
	for _, r := range runs {
		share, ok := r.Throttled()
		if !ok {
			continue
		}
		sampled++
		if share >= ThrottledShare {
			bound = append(bound, r)
		}
	}
	if sampled < ThrottleRuns || float64(len(bound)) < ThrottleFraction*float64(sampled) {
		return store.SizeSmall, ""
	}
	durations := make([]time.Duration, len(bound))
	cpus := []float64{}
	for i, r := range bound {
		durations[i] = r.Duration
		if r.GrantedCPUs > 0 {
			cpus = append(cpus, r.GrantedCPUs)
		}
	}
	slices.Sort(durations)
	if durations[len(durations)/2] < ThrottleMinDuration {
		return store.SizeSmall, ""
	}
	// The class that gives more CPU than the runs had. Runs that never said
	// what they were given are taken to have had the smallest class's runner,
	// which is what an unmeasured job lands on.
	had := c.Runner(store.SizeSmall).CPUs
	if len(cpus) > 0 {
		slices.Sort(cpus)
		had = cpus[len(cpus)/2]
	}
	class := store.SizeLarge
	for _, k := range store.SizeClasses() {
		if c.Runner(k).CPUs > had+cpuEpsilon {
			class = k
			break
		}
	}
	return class, fmt.Sprintf("%d of its %d sampled runs were held back by their CPU limit (%s CPU) for at least a quarter of their time",
		len(bound), sampled, FormatCPUs(had))
}

// runsSince is the runs that finished after t, newest first.
func runsSince(runs []store.JobRun, t time.Time) []store.JobRun {
	var out []store.JobRun
	for _, r := range runs {
		if r.CompletedAt.After(t) {
			out = append(out, r)
		}
	}
	return out
}

// fitsBelow reports whether the runs are enough evidence to move a job down to
// lower: at least DownRuns of them, spread over at least DownSpan, none killed
// for memory, none CPU-bound, and every one needing no more memory than lower's
// runner has. It also returns how many runs there were, how long they spanned,
// and the most memory any needed, for the sentence that says why not.
func (c SizeConfig) fitsBelow(runs []store.JobRun, lower store.SizeClass) (ok bool, n int, span time.Duration, most int64) {
	n = len(runs)
	if n == 0 {
		return false, 0, 0, 0
	}
	newest, oldest := runs[0].CompletedAt, runs[0].CompletedAt
	for _, r := range runs {
		if r.CompletedAt.After(newest) {
			newest = r.CompletedAt
		}
		if r.CompletedAt.Before(oldest) {
			oldest = r.CompletedAt
		}
	}
	span = newest.Sub(oldest)
	fits := true
	for _, r := range runs {
		need := roundUp(float64(r.PeakMemoryMB)*ProfileMemoryMargin, profileMemoryStep)
		most = max(most, need)
		if r.OOMKilled || need > c.Runner(lower).MemoryMB {
			fits = false
		}
	}
	if class, _ := c.cpuClass(runs); class.Rank() > store.SizeSmall.Rank() {
		fits = false
	}
	return fits && n >= DownRuns && span >= DownSpan, n, span, most
}

// roundUp rounds v up to a multiple of step.
func roundUp(v float64, step int64) int64 {
	return int64(math.Ceil(v/float64(step))) * step
}

// longSpan says a stretch of time the way an operator would in a sentence about
// days of history: "14 days", "6 hours", "40m".
func longSpan(d time.Duration) string {
	switch {
	case d >= 36*time.Hour:
		return plural(int(math.Round(d.Hours()/24)), "day")
	case d >= 90*time.Minute:
		return plural(int(math.Round(d.Hours())), "hour")
	}
	return formatDuration(d.Round(time.Minute))
}

package scheduler

import (
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// run is one measured, finished run of a job, daysAgo days before sizeEpoch, on a
// small runner unless the options say otherwise.
func run(daysAgo float64, memoryMB int64, opts ...func(*store.JobRun)) store.JobRun {
	r := store.JobRun{
		CompletedAt: sizeEpoch.Add(-time.Duration(daysAgo * float64(24*time.Hour))),
		Duration:    6 * time.Minute,
		PeakCPUs:    2, PeakMemoryMB: memoryMB,
		GrantedCPUs: 1, GrantedMemoryMB: 2048,
	}
	for _, o := range opts {
		o(&r)
	}
	return r
}

func oomKilled(r *store.JobRun) { r.OOMKilled = true }
func throttled(share float64) func(*store.JobRun) {
	return func(r *store.JobRun) { r.CPUPeriods, r.CPUThrottledPeriods = 1000, int64(share*1000) }
}
func on(cpus float64, memoryMB int64) func(*store.JobRun) {
	return func(r *store.JobRun) { r.GrantedCPUs, r.GrantedMemoryMB = cpus, memoryMB }
}
func lasting(d time.Duration) func(*store.JobRun) { return func(r *store.JobRun) { r.Duration = d } }

// history is n runs spread evenly over the last spanDays days, newest first, each
// with the given peak memory.
func history(n int, spanDays float64, memoryMB int64, opts ...func(*store.JobRun)) []store.JobRun {
	out := make([]store.JobRun, n)
	for i := range out {
		days := 0.0
		if n > 1 {
			days = spanDays * float64(i) / float64(n-1)
		}
		out[i] = run(days, memoryMB, opts...)
	}
	return out
}

// newestFirst puts runs in the order the store returns them.
func newestFirst(runs ...[]store.JobRun) []store.JobRun {
	var out []store.JobRun
	for _, r := range runs {
		out = append(out, r...)
	}
	slices.SortStableFunc(out, func(a, b store.JobRun) int { return b.CompletedAt.Compare(a.CompletedAt) })
	return out
}

func classify(in ClassifyInput) Classification {
	in.Now = sizeEpoch
	return DefaultSizeConfig().Classify(in)
}

func current(class store.SizeClass, movedDaysAgo float64) *store.JobClass {
	return &store.JobClass{Class: class, MovedAt: sizeEpoch.Add(-time.Duration(movedDaysAgo * float64(24*time.Hour)))}
}

func TestASizeLabelInRunsOnIsTheWholeAnswer(t *testing.T) {
	// The author said where the job goes, and that is honoured over a pin and
	// over every measurement: it is the one path that is guaranteed.
	got := classify(ClassifyInput{
		Labels: []string{"self-hosted", "Linux", "Zoomies-Large"},
		Pin:    &store.SizePin{Repo: "acme/api", Class: store.SizeSmall},
		Runs:   history(10, 5, 500),
	})
	if got.Class != store.SizeLarge || got.Basis != store.SizeBasisExplicit || got.FloorMB != 0 ||
		got.Reason != "its runs-on asks for zoomies-large" {
		t.Fatalf("an explicit label was classed as %+v", got)
	}

	// A job asking for two, which no pool answers, is taken to want the larger.
	got = classify(ClassifyInput{Labels: []string{"zoomies-small", "zoomies-medium"}})
	if got.Class != store.SizeMedium || got.Basis != store.SizeBasisExplicit {
		t.Fatalf("two size labels were classed as %+v", got)
	}

	// Labels that only look like one are not.
	got = classify(ClassifyInput{Labels: []string{"zoomies", "large", "zoomies-large-arm64", "x64"}})
	if got.Basis == store.SizeBasisExplicit {
		t.Fatalf("a look-alike label was taken for a size label: %+v", got)
	}
}

func TestAPinTakesThePlaceOfTheMeasurements(t *testing.T) {
	heavy := history(12, 6, 30000, oomKilled)
	job := classify(ClassifyInput{
		Pin: &store.SizePin{Repo: "acme/api", Workflow: "CI", JobName: "build", Class: store.SizeSmall}, Runs: heavy,
	})
	if job.Class != store.SizeSmall || job.Basis != store.SizeBasisPin || job.Reason != "an operator pinned this job to small" {
		t.Fatalf("a job pin was classed as %+v", job)
	}
	repo := classify(ClassifyInput{Pin: &store.SizePin{Repo: "acme/api", Class: store.SizeLarge}})
	if repo.Class != store.SizeLarge || repo.Reason != "an operator pinned every job in acme/api to large" {
		t.Fatalf("a repository pin was classed as %+v", repo)
	}
}

func TestAJobWithNoHistoryStartsInTheDefaultClass(t *testing.T) {
	got := classify(ClassifyInput{})
	if got.Class != store.SizeMedium || got.Basis != store.SizeBasisDefault || got.FloorMB != 0 || got.Runs != 0 ||
		!strings.Contains(got.Reason, "no measured runs") {
		t.Fatalf("a new job was classed as %+v", got)
	}

	cfg := DefaultSizeConfig()
	cfg.DefaultClass = store.SizeSmall
	if got := cfg.Classify(ClassifyInput{Now: sizeEpoch}); got.Class != store.SizeSmall || !strings.Contains(got.Reason, "small") {
		t.Fatalf("the configured default was ignored: %+v", got)
	}
	cfg.DefaultClass = "huge"
	if got := cfg.Classify(ClassifyInput{Now: sizeEpoch}); got.Class != store.SizeSmall {
		t.Fatalf("a default that is not a class gave %+v, want small", got)
	}
}

// A job nobody has run for a fortnight has no evidence either way, and the best
// guess at what it needs is what it needed last: sending it back to the default
// would have it killed on the way to relearning it.
func TestAJobThatHasNotRunLatelyKeepsItsClass(t *testing.T) {
	got := classify(ClassifyInput{Current: current(store.SizeMedium, 30)})
	if got.Class != store.SizeMedium || got.Basis != store.SizeBasisHistory || !strings.Contains(got.Reason, "14 days") {
		t.Fatalf("a job with no recent runs was classed as %+v", got)
	}
}

func TestMemoryDecidesTheClassFromTheNinetiethPercentileWithAMargin(t *testing.T) {
	// A small runner has 2 GB, a medium one 4 and a large one 8, and a fifth is
	// added to what the runs needed. 1700 MB becomes 2040 and fits 2048; 1800
	// becomes 2160 and does not.
	cases := []struct {
		name     string
		peakMB   int64
		want     store.SizeClass
		wantText string
	}{
		{"well inside a small runner", 1000, store.SizeSmall, "which a small runner holds"},
		{"inside it with the margin", 1700, store.SizeSmall, "which a small runner holds"},
		{"over it once the margin is added", 1800, store.SizeMedium, "which a medium runner holds"},
		{"inside a medium runner with the margin", 3400, store.SizeMedium, "which a medium runner holds"},
		{"over it", 3500, store.SizeLarge, "which a large runner holds"},
		{"more than any class holds", 10000, store.SizeLarge, "more than a large runner has (8 GB)"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := classify(ClassifyInput{Runs: history(12, 6, tc.peakMB)})
			if got.Class != tc.want || got.Basis != store.SizeBasisHistory || got.Runs != 12 {
				t.Fatalf("12 runs at %d MB were classed as %+v, want %s", tc.peakMB, got, tc.want)
			}
			if !strings.Contains(got.Reason, tc.wantText) || !strings.Contains(got.Reason, "12 runs") {
				t.Errorf("the reason %q does not say %q and how many runs it was worked out from", got.Reason, tc.wantText)
			}
			if got.FloorMB <= 0 {
				t.Errorf("a class worked out from memory has no floor: %+v", got)
			}
		})
	}
}

// One run that pulled a cold cache should not size every run after it, and a
// single bad one among many is what the percentile is for.
func TestOneHeavyRunAmongManyDoesNotMoveAJob(t *testing.T) {
	runs := history(19, 10, 1000)
	runs = append([]store.JobRun{run(0, 7000)}, runs...)
	if got := classify(ClassifyInput{Runs: runs}); got.Class != store.SizeSmall {
		t.Fatalf("one heavy run among twenty classed the job %s: %s", got.Class, got.Reason)
	}
	// Two, in twenty, are still inside what the percentile leaves out; three are not.
	runs = append([]store.JobRun{run(0, 7000), run(0.1, 7000), run(0.2, 7000)}, history(17, 10, 1000)...)
	if got := classify(ClassifyInput{Runs: runs}); got.Class != store.SizeLarge {
		t.Fatalf("three heavy runs among twenty classed the job %s: %s", got.Class, got.Reason)
	}
}

// A kill is evidence that does not wait for a percentile: the 90th of twenty
// ignores the two largest runs, which is exactly where a single kill sits.
func TestAKillForMemoryMovesAJobUpAtOnce(t *testing.T) {
	// Killed on a small runner's 2 GB it needs more than that: half as much
	// again, and a fifth on top, is about 3.6 GB, which a medium runner holds.
	runs := append([]store.JobRun{run(1, 2000, oomKilled)}, history(19, 10, 1000)...)
	got := classify(ClassifyInput{Runs: runs})
	if got.Class != store.SizeMedium || !strings.Contains(got.Reason, "killed a run for memory at 2 GB") ||
		!strings.Contains(got.Reason, "need about 3.6 GB") {
		t.Fatalf("a job killed for memory at 2 GB was classed as %+v", got)
	}
	if got.FloorMB < 3600 {
		t.Fatalf("its floor %d MB is under what a kill implies", got.FloorMB)
	}

	// Killed on a medium runner's 4 GB it needs more than medium has.
	runs = append([]store.JobRun{run(1, 4000, oomKilled, on(2, 4096))}, history(19, 10, 1000)...)
	if got := classify(ClassifyInput{Runs: runs}); got.Class != store.SizeLarge {
		t.Fatalf("a job killed at 4 GB was classed as %s: %s", got.Class, got.Reason)
	}

	// Moving up from medium says so.
	got = classify(ClassifyInput{Runs: runs, Current: current(store.SizeMedium, 5)})
	if got.Class != store.SizeLarge || !strings.HasSuffix(got.Reason, "so it moved up from medium") {
		t.Fatalf("a move up was classed as %+v", got)
	}

	// A kill before the class last moved is what moved it, and moves it no
	// further. The case that matters is the one where the class has since moved
	// down: the kill is still inside the window, and counting it again would put
	// the job straight back where the evidence had just taken it from.
	runs = newestFirst(history(12, 6, 1000, on(2, 4096)), []store.JobRun{run(10, 4000, oomKilled, on(2, 4096))})
	got = classify(ClassifyInput{Runs: runs, Current: current(store.SizeMedium, 1)})
	if got.Class != store.SizeMedium {
		t.Fatalf("a kill from before the last move moved the job again: %+v", got)
	}
	// The same kill with no move since is evidence, and is acted on.
	got = classify(ClassifyInput{Runs: runs, Current: current(store.SizeMedium, 12)})
	if got.Class != store.SizeLarge {
		t.Fatalf("a kill since the last move did not move the job: %+v", got)
	}
}

func TestAJobHeldBackByItsCPULimitMovesUpAClass(t *testing.T) {
	bound := func(n int, share float64, d time.Duration, opts ...func(*store.JobRun)) []store.JobRun {
		return history(n, 5, 900, append([]func(*store.JobRun){throttled(share), lasting(d)}, opts...)...)
	}
	cases := []struct {
		name string
		runs []store.JobRun
		want store.SizeClass
	}{
		{"held back in every sampled run, on a small runner's one CPU", bound(6, 0.4, 5*time.Minute), store.SizeMedium},
		{"on a medium runner's two, it needs a large one", bound(6, 0.4, 5*time.Minute, on(2, 4096)), store.SizeLarge},
		{"already on the largest, there is nowhere further", bound(6, 0.4, 5*time.Minute, on(4, 8192)), store.SizeLarge},
		{"only a little throttled is just a busy job", bound(6, 0.1, 5*time.Minute), store.SizeSmall},
		{"too few sampled runs to say anything", bound(2, 0.4, 5*time.Minute), store.SizeSmall},
		{"runs too short for being held back to cost anything", bound(6, 0.4, time.Minute), store.SizeSmall},
		{"never sampled", history(6, 5, 900), store.SizeSmall},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := classify(ClassifyInput{Runs: tc.runs})
			if got.Class != tc.want {
				t.Fatalf("classed %s, want %s: %s", got.Class, tc.want, got.Reason)
			}
		})
	}

	// Held back in under half of the runs it was sampled in is not a pattern.
	mixed := append(bound(2, 0.4, 5*time.Minute), history(4, 5, 900, throttled(0.01), lasting(5*time.Minute))...)
	if got := classify(ClassifyInput{Runs: mixed}); got.Class != store.SizeSmall {
		t.Fatalf("2 CPU-bound runs in 6 classed the job %s", got.Class)
	}
	// Half is.
	half := append(bound(3, 0.4, 5*time.Minute), history(3, 5, 900, throttled(0.01), lasting(5*time.Minute))...)
	got := classify(ClassifyInput{Runs: half})
	if got.Class != store.SizeMedium || !strings.Contains(got.Reason, "3 of its 6 sampled runs were held back by their CPU limit (1 CPU)") {
		t.Fatalf("3 CPU-bound runs in 6 were classed as %+v", got)
	}
}

// Moving up is quick because a job that does not fit is killed, and moving down
// is slow because one that does fit is only a little slower for the machine
// being too large. A class that swung with every run would put the same job on
// a different host each time.
func TestAJobMovesDownOnlyOnSustainedEvidence(t *testing.T) {
	light := func(n int, spanDays float64, opts ...func(*store.JobRun)) []store.JobRun {
		return history(n, spanDays, 1000, append([]func(*store.JobRun){on(2, 4096)}, opts...)...)
	}
	cases := []struct {
		name string
		runs []store.JobRun
		cur  *store.JobClass
		want store.SizeClass
		text string
	}{
		{"ten runs over nine days, all small", light(10, 9), current(store.SizeMedium, 12), store.SizeSmall, "all fit a small runner"},
		{"nine runs is not enough", light(9, 9), current(store.SizeMedium, 12), store.SizeMedium, "moving down takes 10 runs over 7 days"},
		{"ten runs over five days is not enough", light(10, 5), current(store.SizeMedium, 12), store.SizeMedium, "there have been 10 over 5 days"},
		{"runs from before the move are the evidence for it, not against it", light(12, 9), current(store.SizeMedium, 2), store.SizeMedium, "since it moved to medium"},
		{"one run that needs more than a small runner", newestFirst(light(11, 9), []store.JobRun{run(3, 3000, on(2, 4096))}), current(store.SizeMedium, 12), store.SizeMedium, ""},
		// A kill on a runner so small that it still fits the smaller class says
		// nothing about moving up, and everything about moving down.
		{"a kill among them", newestFirst(light(11, 9), []store.JobRun{run(3, 700, oomKilled, on(1, 512))}), current(store.SizeMedium, 12), store.SizeMedium, ""},
		// Held back at the smaller class's own CPU count is evidence the job
		// wants more than that, which is a reason not to move it there.
		{"held back by the CPU limit", light(12, 9, on(1, 4096), throttled(0.5), lasting(8*time.Minute)), current(store.SizeMedium, 12), store.SizeMedium, ""},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := classify(ClassifyInput{Runs: tc.runs, Current: tc.cur})
			if got.Class != tc.want {
				t.Fatalf("classed %s, want %s: %s", got.Class, tc.want, got.Reason)
			}
			if !strings.Contains(got.Reason, tc.text) {
				t.Errorf("the reason %q does not say %q", got.Reason, tc.text)
			}
		})
	}

	// It moves down a class, not to wherever the runs fit: a job in large whose
	// every run fits small goes to medium and has to earn the next step too.
	got := classify(ClassifyInput{Runs: light(12, 9), Current: current(store.SizeLarge, 20)})
	if got.Class != store.SizeMedium || !strings.Contains(got.Reason, "so it moved down from large") {
		t.Fatalf("a job in large was classed as %+v", got)
	}
}

// A job that finishes every few hours has twenty runs inside a day or two, so
// "ten runs over a week since it moved" cannot be read from its newest twenty.
// The controller reads far more than that, and the classifier takes the
// percentile from the newest twenty and the evidence for moving down from all of
// them: otherwise every busy job could only ever move up.
func TestABusyJobMovesDownOnAWeekOfRunsNotOnTheNewestTwenty(t *testing.T) {
	// Seven runs a day for two weeks, every one light, in a class it moved to
	// thirteen days ago.
	busy := history(98, 13, 700, on(2, 4096))
	if got := classify(ClassifyInput{Runs: busy, Current: current(store.SizeMedium, 13)}); got.Class != store.SizeSmall ||
		!strings.Contains(got.Reason, "so it moved down from medium") {
		t.Fatalf("98 light runs over 13 days classed the job %+v", got)
	}
	// The newest twenty alone span less than three days: no evidence of a week,
	// which is the answer a caller that read only those would have got for ever.
	if got := classify(ClassifyInput{Runs: busy[:ClassRuns], Current: current(store.SizeMedium, 13)}); got.Class != store.SizeMedium {
		t.Fatalf("the newest %d runs alone moved the job to %s", ClassRuns, got.Class)
	}
	// And what it needs is still read from the newest twenty: a run that needed
	// a great deal, twelve days ago among ninety-eight, is not what it needs now.
	old := append(append([]store.JobRun{}, busy...), run(12.5, 9000, on(2, 4096)))
	if got := classify(ClassifyInput{Runs: newestFirst(old), Current: current(store.SizeMedium, 13)}); got.Class != store.SizeMedium {
		t.Fatalf("a heavy run among ninety-nine light ones should keep the job in medium, got %+v", got)
	}
}

// Moving down looks at the runs since the job moved, and moving up at its newest
// runs, so a job whose light runs came after its heavy ones used to be moved down
// on the first reading and back up on the second. A move down now has to be one
// the newest runs agree with, and once made it is not undone by the runs it was
// made on.
func TestAJobIsNotMovedDownOnlyToBeMovedStraightBackUp(t *testing.T) {
	runs := newestFirst(
		history(11, 8, 1000, on(2, 4096)),
		// Heavy runs from before it moved, still among its newest.
		history(3, 1, 3000, on(2, 4096)),
	)
	// The heavy ones are eleven and twelve days ago.
	for i := range runs {
		if runs[i].PeakMemoryMB == 3000 {
			runs[i].CompletedAt = runs[i].CompletedAt.Add(-11 * 24 * time.Hour)
		}
	}
	runs = newestFirst(runs)
	first := classify(ClassifyInput{Runs: runs, Current: current(store.SizeMedium, 9)})
	if first.Class != store.SizeMedium {
		t.Fatalf("the job moved down to %s although its newest runs still say it needs about 3.6 GB: %s", first.Class, first.Reason)
	}
	// Nothing about a second look changes the answer.
	if again := classify(ClassifyInput{Runs: runs, Current: current(first.Class, 9)}); again.Class != store.SizeMedium {
		t.Fatalf("the second reading moved the job to %s", again.Class)
	}
}

func TestAJobStaysWhereItIsWhenItsRunsFitThere(t *testing.T) {
	got := classify(ClassifyInput{Runs: history(12, 6, 3000), Current: current(store.SizeMedium, 9)})
	if got.Class != store.SizeMedium || got.Basis != store.SizeBasisHistory || !strings.Contains(got.Reason, "which a medium runner holds") {
		t.Fatalf("a job that fits where it is was classed as %+v", got)
	}
}

// Classifying the same history twice gives the same answer, because the
// controller does it on every job that finishes.
func TestClassifyingTheSameHistoryTwiceGivesTheSameAnswer(t *testing.T) {
	in := ClassifyInput{Runs: history(14, 8, 2500), Current: current(store.SizeMedium, 3)}
	first := classify(in)
	for range 3 {
		if again := classify(in); again != first {
			t.Fatalf("classification is not stable: %+v then %+v", first, again)
		}
	}
}

package scheduler

import (
	"fmt"
	"reflect"
	"slices"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// Decide runs on every reconcile pass whether or not anything is happening, so
// what it costs is paid continuously, and a change that makes it a little
// slower is paid for just as long. These benchmarks put a number on a pass at
// three fleet sizes in five situations, to be set beside the same run after a
// change to the scheduler (benchstat before.txt after.txt).
//
// Each snapshot is built before the timer starts and checked once. A fleet
// that was meant to be full but quietly had room would report a flattering
// number for a code path its name does not describe.

// benchScale is the size of fleet a pass decides over. The ladder shows how the
// cost grows rather than naming a fleet anyone runs: Decide sets every queued
// job against every pool, so one size cannot say whether the next is twice as
// slow or a hundred times.
type benchScale struct {
	name           string
	pools, hosts   int
	runnersPerPool int
	jobsPerPool    int
}

var benchScales = []benchScale{
	{name: "4pools", pools: 4, hosts: 2, runnersPerPool: 4, jobsPerPool: 2},
	{name: "20pools", pools: 20, hosts: 8, runnersPerPool: 8, jobsPerPool: 5},
	{name: "100pools", pools: 100, hosts: 40, runnersPerPool: 8, jobsPerPool: 10},
}

// benchFleet is what a situation changes about the fleet a scale describes.
type benchFleet struct {
	// idle is how many of each pool's runners are idle; the rest hold a job.
	idle int
	// queued says each pool has jobs waiting for it, and stray that as many
	// again wait for a label no pool advertises. Distinct gives each of those a
	// label of its own, so that no two jobs ask the same thing.
	queued, stray, distinct bool
	// spare is the slots every host has beyond the runners already on it.
	spare int
	// sized gives the hosts measured CPUs, memory and disk and the pools a limit
	// on each runner, so that placement does its resource accounting too.
	sized bool
}

// benchJob is a job as the store hands it to the scheduler, with its labels put
// through NormalizeLabels as every job's are on the way in. The tests' own
// queued helper leaves them as given, and labels out of order are ones the
// matching has to normalise again at every comparison, which no job that came
// from the store ever needs.
func benchJob(j *store.Job) *store.Job {
	j.Labels = store.NormalizeLabels(j.Labels)
	return j
}

// snapshot builds the fleet: every pool is asked for by a label of its own, and
// its runners are spread over the hosts in turn, which is what each host's
// active count is then taken from.
func (f benchFleet) snapshot(sc benchScale) Snapshot {
	hosts := make([]*store.Host, sc.hosts)
	for i := range hosts {
		id := fmt.Sprintf("host_%03d", i)
		if f.sized {
			// Far more than the pools can ask of it, so that the accounting
			// runs without ever being what refuses a runner.
			hosts[i] = sized(id, 0, 128, 512*1024, 4<<20)
		} else {
			hosts[i] = testHost(id, 0, 0)
		}
	}

	var pools []*store.Pool
	var runners []*store.Runner
	var jobs []*store.Job
	placed := 0
	for i := range sc.pools {
		name := fmt.Sprintf("pool%03d", i)
		p := testPool(name, "self-hosted", name)
		p.MaxRunners = sc.runnersPerPool + sc.jobsPerPool
		if f.sized {
			p.Resources = store.Resources{CPUs: 2, MemoryMB: 4096}
		}
		pools = append(pools, p)

		for k := range sc.runnersPerPool {
			id := fmt.Sprintf("run_%s_%02d", name, k)
			var r *store.Runner
			if k < f.idle {
				r = idleRunner(id, p, time.Minute)
			} else {
				r = testRunner(id, p, store.RunnerBusy, 10*time.Minute)
				job := benchJob(queued("job_"+id, 5*time.Minute, "self-hosted", name))
				job.State, job.RunnerID = store.JobInProgress, id
				jobs = append(jobs, job)
			}
			h := hosts[placed%len(hosts)]
			placed++
			r.HostID = h.ID
			h.ActiveRunners++
			runners = append(runners, r)
		}
		if f.queued {
			for k := range sc.jobsPerPool {
				jobs = append(jobs, benchJob(queued(fmt.Sprintf("job_%s_wait%02d", name, k), time.Minute, "self-hosted", name)))
			}
		}
		if f.stray {
			for k := range sc.jobsPerPool {
				label := "no-such-pool"
				if f.distinct {
					label = fmt.Sprintf("no-such-pool-%s-%02d", name, k)
				}
				jobs = append(jobs, benchJob(queued(fmt.Sprintf("job_%s_stray%02d", name, k), time.Minute, "self-hosted", label)))
			}
		}
	}
	for _, h := range hosts {
		h.Capacity = h.ActiveRunners + f.spare
	}
	return snap(pools, runners, jobs, hosts)
}

// benchSituations are the shapes of pass a fleet spends its time in. Quiet is
// the commonest, since most passes find nothing to do, so it is the number
// that sets the steady cost; the others are the passes an operator is waiting
// on.
var benchSituations = []struct {
	name  string
	fleet benchFleet
	// expect says what the pass must have done for the number to mean what
	// the name claims, and returns the complaint when it did not.
	expect func(sc benchScale, plan Plan) string
}{
	{
		// Nothing is waiting and nothing has outlived its welcome, so the
		// pass reads the whole fleet and changes none of it.
		name:  "quiet",
		fleet: benchFleet{idle: 1, spare: 4},
		expect: func(sc benchScale, plan Plan) string {
			if len(plan.Actions) != 0 || len(plan.Unmatched) != 0 {
				return fmt.Sprintf("%d actions and %d unmatched jobs", len(plan.Actions), len(plan.Unmatched))
			}
			return ""
		},
	},
	{
		// A queue arrives where the hosts have room, so the pass places
		// runners, up to the shipped cap on creates per pass.
		name:   "burst",
		fleet:  benchFleet{queued: true, spare: 20},
		expect: expectCreates,
	},
	{
		// The same burst on hosts that report their size, so every placement
		// is weighed against CPU, memory and disk as well as slots.
		name:   "burst_sized",
		fleet:  benchFleet{queued: true, spare: 20, sized: true},
		expect: expectCreates,
	},
	{
		// The queue is there and the hosts are full, so every pool has to
		// work out and word why nothing can be started for it. This is the
		// pass an operator is looking at when jobs are waiting.
		name:  "saturated",
		fleet: benchFleet{queued: true},
		expect: func(sc benchScale, plan Plan) string {
			blocked := 0
			for _, pp := range plan.Pools {
				if pp.Blocked != "" {
					blocked++
				}
			}
			if n := countOf(plan.Actions, ActionCreate); n != 0 || blocked != sc.pools {
				return fmt.Sprintf("%d creates and %d of %d pools blocked", n, blocked, sc.pools)
			}
			return ""
		},
	},
	{
		// Jobs asking for labels no pool has: the pass has to try every pool
		// before it can say so.
		name:   "stray_jobs",
		fleet:  benchFleet{stray: true, spare: 4},
		expect: expectUnmatched,
	},
	{
		// The same jobs, each asking for a label of its own, so that none can be
		// given another's answer: a pass that answers a kind of job once pays for
		// every job here, and this is what it costs when that never helps.
		name:   "distinct_jobs",
		fleet:  benchFleet{stray: true, distinct: true, spare: 4},
		expect: expectDistinct,
	},
}

// expectUnmatched is what a pass over jobs no pool will take must do: say so of
// every one of them.
func expectUnmatched(sc benchScale, plan Plan) string {
	if want := sc.pools * sc.jobsPerPool; len(plan.Unmatched) != want {
		return fmt.Sprintf("%d unmatched jobs, want %d", len(plan.Unmatched), want)
	}
	return ""
}

// expectDistinct is expectUnmatched for jobs of which no two ask for the same.
func expectDistinct(sc benchScale, plan Plan) string {
	if msg := expectUnmatched(sc, plan); msg != "" {
		return msg
	}
	asked := map[string]bool{}
	for _, u := range plan.Unmatched {
		key := fmt.Sprint(u.Job.Labels)
		if asked[key] {
			return fmt.Sprintf("two jobs ask for %s", key)
		}
		asked[key] = true
	}
	return ""
}

// expectCreates is what a burst on hosts with room must do: start as many
// runners as there are jobs waiting, or as many as one pass may start.
func expectCreates(sc benchScale, plan Plan) string {
	want := min(sc.pools*sc.jobsPerPool, testPolicy().MaxCreatesPerTick)
	if n := countOf(plan.Actions, ActionCreate); n != want {
		return fmt.Sprintf("%d creates, want %d", n, want)
	}
	return ""
}

func BenchmarkDecide(b *testing.B) {
	for _, sit := range benchSituations {
		b.Run(sit.name, func(b *testing.B) {
			for _, sc := range benchScales {
				b.Run(sc.name, func(b *testing.B) {
					s := sit.fleet.snapshot(sc)
					first := Decide(s)
					if msg := sit.expect(sc, first); msg != "" {
						b.Fatalf("this fleet is not a %s one: %s", sit.name, msg)
					}
					// What the store hands over is already normalised, and the
					// matching has a fast path for exactly that. A fleet whose
					// labels are not would time the slow path, which no stored
					// job or pool takes.
					for _, j := range s.Jobs {
						if !slices.Equal(j.Labels, store.NormalizeLabels(j.Labels)) {
							b.Fatalf("job %s has labels the store would have normalised: %v", j.ID, j.Labels)
						}
					}
					for _, p := range s.Pools {
						if !slices.Equal(p.Labels, store.NormalizeLabels(p.Labels)) {
							b.Fatalf("pool %s has labels the store would have normalised: %v", p.Name, p.Labels)
						}
					}
					if sit.fleet.sized && Reserved(s.Hosts[0], s.Pools, s.Runners).MemoryMB == 0 {
						b.Fatal("the hosts report their size but the runners on them are charged nothing against it")
					}
					// Decide is meant to be deterministic and to leave its
					// snapshot alone. If it did not, every iteration after the
					// first would be measuring a different fleet.
					if !reflect.DeepEqual(first, Decide(s)) {
						b.Fatal("a second pass over the same snapshot decided differently")
					}

					b.ReportAllocs()
					for b.Loop() {
						Decide(s)
					}
				})
			}
		})
	}
}

package scheduler

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// The documentation names the figures size advice is computed from, and this
// holds the page to the constants: a changed percentile, margin, growth or
// minimum that left the page as it was would have the page lying in the one
// place an operator checks the rule.
func TestTheFiguresSectionNamesTheConstants(t *testing.T) {
	body, err := os.ReadFile(filepath.Join("..", "..", "docs", "auto-pools.md"))
	if err != nil {
		t.Fatal(err)
	}
	page := string(body)
	section := between(t, page, "### How the figures are computed", "### What is deliberately not inferred")
	for name, want := range map[string]string{
		"the percentile":      fmt.Sprintf("%.0fth percentile", ProfilePercentile*100),
		"the memory margin":   fractionWords(t, ProfileMemoryMargin-1) + " added",
		"the kill growth":     fractionWords(t, ProfileOOMGrowth) + " times",
		"the minimum":         numberWords(t, AdviceMinRuns) + " measured runs",
		"ProfilePercentile":   "`ProfilePercentile`",
		"ProfileMemoryMargin": "`ProfileMemoryMargin`",
		"ProfileOOMGrowth":    "`ProfileOOMGrowth`",
		"AdviceMinRuns":       "`AdviceMinRuns`",
	} {
		if !strings.Contains(section, want) {
			t.Errorf("the figures section never says %s as %q", name, want)
		}
	}
	notInferred := between(t, page, "### What is deliberately not inferred", "\n## ")
	for _, want := range []string{"single run", "pinned", "retention", "cordoned"} {
		if !strings.Contains(notInferred, want) {
			t.Errorf("the section on what is not inferred never mentions %q", want)
		}
	}
}

// between is the text from one heading to the next, so a sentence is held to
// the section it belongs in and not found by chance elsewhere on the page.
func between(t *testing.T, page, from, to string) string {
	t.Helper()
	i := strings.Index(page, from)
	if i < 0 {
		t.Fatalf("docs/auto-pools.md has no %q", from)
	}
	rest := page[i+len(from):]
	if j := strings.Index(rest, to); j >= 0 {
		rest = rest[:j]
	}
	return rest
}

// fractionWords is how the prose says a ratio: the page is for people, and
// "a fifth added" is what ProfileMemoryMargin means to one.
func fractionWords(t *testing.T, v float64) string {
	t.Helper()
	words := map[string]string{"0.20": "a fifth", "0.25": "a quarter", "0.50": "half", "1.50": "one and a half", "2.00": "two"}
	w, ok := words[fmt.Sprintf("%.2f", v)]
	if !ok {
		t.Fatalf("no words for %v; teach fractionWords the new constant and write it into the page", v)
	}
	return w
}

func numberWords(t *testing.T, n int) string {
	t.Helper()
	words := []string{"zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten"}
	if n < 0 || n >= len(words) {
		t.Fatalf("no words for %d; teach numberWords the new constant and write it into the page", n)
	}
	return words[n]
}

package scheduler

import (
	"math"
	"slices"
)

// ElasticCPUWorkload is one live runner in the host CPU ledger. Every live
// workload belongs in the input, including ones that may not burst: their base
// is already promised and therefore is not spare CPU.
type ElasticCPUWorkload struct {
	ID        string
	BaseCPUs  float64
	MaxCPUs   float64
	Demanding bool
	// Idle is a live runner waiting for a job. Idle runners are charged
	// together only the largest single guarantee among them, not the sum: at
	// most one of them can be handed the next job before the following plan,
	// and CPU they are not using is the whole point of lending.
	Idle bool
}

// ElasticCPUPlan lends a host's genuinely unpromised CPU to demanding
// workloads with max-min fairness.
//
// total is the host's allocatable CPU after its operator reserve. startReserve
// protects an imminent runner when compatible work is queued. A workload with
// MaxCPUs at or below BaseCPUs stays at its guarantee. Returned targets always
// include every workload, so an agent can restore a runner whose demand ended.
//
// Idle workloads are charged collectively as a start reserve -- the largest
// idle guarantee -- rather than each in full, or a host holding warm runners
// would never have anything to lend. The oversubscription that allows is
// bounded: when a second idle runner turns busy it is charged in full on the
// very next plan, and the plan is complete, so the lent CPU comes back then.
func ElasticCPUPlan(total, startReserve float64, workloads []ElasticCPUWorkload) map[string]float64 {
	targets := make(map[string]float64, len(workloads))
	ordered := slices.Clone(workloads)
	slices.SortFunc(ordered, func(a, b ElasticCPUWorkload) int {
		if a.ID < b.ID {
			return -1
		}
		if a.ID > b.ID {
			return 1
		}
		return 0
	})

	committed, idleReserve := 0.0, 0.0
	var active []ElasticCPUWorkload
	for _, w := range ordered {
		base := max(w.BaseCPUs, 0)
		targets[w.ID] = base
		if w.Idle {
			idleReserve = max(idleReserve, base)
			continue
		}
		committed += base
		if w.Demanding && w.MaxCPUs > base+cpuEpsilon {
			active = append(active, w)
		}
	}
	spare := max(total-max(startReserve, 0)-idleReserve-committed, 0)

	// Water-fill rather than divide once: a runner with a low ceiling gives
	// what it cannot use back to the remaining runners instead of stranding it.
	for spare > cpuEpsilon && len(active) > 0 {
		share := spare / float64(len(active))
		next := active[:0]
		used := 0.0
		for _, w := range active {
			room := w.MaxCPUs - targets[w.ID]
			give := min(share, room)
			if give > 0 {
				targets[w.ID] += give
				used += give
			}
			if room-give > cpuEpsilon {
				next = append(next, w)
			}
		}
		if used <= cpuEpsilon {
			break
		}
		spare -= used
		active = next
	}

	// The daemon works in hundredths of a core. Floor each target so rounding
	// can never promise more CPU than total, even across many runners.
	for id, target := range targets {
		targets[id] = math.Floor((target+cpuEpsilon)*100) / 100
	}
	return targets
}

package scheduler

import (
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

func TestElasticCPUPlanLendsIdleCPUAndProtectsAStart(t *testing.T) {
	work := []ElasticCPUWorkload{{ID: "busy", BaseCPUs: 2, MaxCPUs: 8, Demanding: true}}
	if got := ElasticCPUPlan(8, 0, work)["busy"]; got != 8 {
		t.Fatalf("without queued work target = %v, want 8", got)
	}
	if got := ElasticCPUPlan(8, 2, work)["busy"]; got != 6 {
		t.Fatalf("with one start protected target = %v, want 6", got)
	}
}

func TestElasticCPUPlanIsFairAndReturnsUnusedCeilings(t *testing.T) {
	work := []ElasticCPUWorkload{
		{ID: "a", BaseCPUs: 2, MaxCPUs: 3, Demanding: true},
		{ID: "b", BaseCPUs: 2, MaxCPUs: 8, Demanding: true},
	}
	got := ElasticCPUPlan(8, 0, work)
	if got["a"] != 3 || got["b"] != 5 {
		t.Fatalf("targets = %v, want a=3 and b=5", got)
	}
}

func TestElasticCPUPlanCountsWorkloadsThatCannotBurst(t *testing.T) {
	work := []ElasticCPUWorkload{
		{ID: "fixed", BaseCPUs: 4, MaxCPUs: 4},
		{ID: "busy", BaseCPUs: 2, MaxCPUs: 8, Demanding: true},
	}
	got := ElasticCPUPlan(8, 0, work)
	if got["fixed"] != 4 || got["busy"] != 4 {
		t.Fatalf("targets = %v, want fixed=4 and busy=4", got)
	}
}

func TestElasticCPUPlanRestoresTheBaseWithoutDemand(t *testing.T) {
	got := ElasticCPUPlan(8, 0, []ElasticCPUWorkload{{ID: "quiet", BaseCPUs: 2, MaxCPUs: 8}})
	if got["quiet"] != 2 {
		t.Fatalf("quiet target = %v, want its base 2", got["quiet"])
	}
}

// Warm runners were the owners' commonest disappointment: sixteen CPUs, four
// slots, one busy job and three idle runners left nothing to lend, because
// every idle guarantee was charged in full. Only one of them can be handed the
// next job before the following plan, so only one is held back.
func TestElasticCPUPlanHoldsBackOneIdleGuaranteeNotAll(t *testing.T) {
	work := []ElasticCPUWorkload{
		{ID: "busy", BaseCPUs: 4, MaxCPUs: 16, Demanding: true},
		{ID: "idle-1", BaseCPUs: 4, MaxCPUs: 4, Idle: true},
		{ID: "idle-2", BaseCPUs: 4, MaxCPUs: 4, Idle: true},
		{ID: "idle-3", BaseCPUs: 4, MaxCPUs: 4, Idle: true},
	}
	got := ElasticCPUPlan(16, 0, work)
	if got["busy"] != 12 {
		t.Fatalf("busy target = %v, want 12: three idle runners hold back one guarantee between them", got["busy"])
	}
	for _, id := range []string{"idle-1", "idle-2", "idle-3"} {
		if got[id] != 4 {
			t.Errorf("%s target = %v, want its guarantee of 4", id, got[id])
		}
	}

	// One of them takes a job. The next plan charges it in full, and the
	// boost shrinks back so that everyone has their guarantee again.
	work[1].Idle = false
	got = ElasticCPUPlan(16, 0, work)
	if got["busy"] != 8 {
		t.Fatalf("after an idle runner turned busy the boost is %v, want 8", got["busy"])
	}
	// The two busy runners and the one idle guarantee still held back fit.
	if sum := got["busy"] + got["idle-1"] + 4; sum > 16 {
		t.Fatalf("busy targets plus the idle reserve are %v, more than the host's 16", sum)
	}
}

// A boost being used is load the plan chose, and the next plan takes it back
// for a start. Read as pressure it held new starts and kept a host on its
// throttle rung for doing what the plan asked.
func TestLentCPUInUseIsNotHostPressure(t *testing.T) {
	now := time.Now()
	cpu := 97.0
	h := &store.Host{CPUs: 16, Usage: store.HostUsage{CPUPercent: &cpu, SampledAt: now, LentCPUPercent: 40}}
	if hostUnderCPUPressure(h, now) {
		t.Error("a host at 97% with 40% of it lent CPU in use was under CPU pressure")
	}
	if !hostCalm(h) {
		t.Error("a host at 97% with 40% of it lent CPU in use was not calm")
	}
	h.Usage.LentCPUPercent = 0
	if !hostUnderCPUPressure(h, now) || hostCalm(h) {
		t.Error("a host at 97% with nothing lent was not judged under pressure")
	}
}

package scheduler

import (
	"fmt"
	"time"
)

// These thresholds decide when CPU lent to a runner comes back because the
// runner is not using it, and how long the controller then waits before
// lending to that runner again. They are deliberately far apart from the
// thresholds that lend in the first place, because the failure being designed
// out is a quota that moves on every heartbeat.
const (
	// LoanInUseShare is how much of a loan a runner must be using, above its
	// guarantee, for the loan to count as used. A quarter, not a half: a
	// build's usage is spiky between link and compile steps, and a loan that
	// is doing a quarter of its job on average is still shortening the job.
	// Below it, a runner lent two cores that uses its guarantee and a sliver
	// is holding CPU a neighbour could use.
	LoanInUseShare = 0.25
	// LoanReclaimSamples is how many fresh samples in a row must show a loan
	// unused before it is withdrawn. One low sample is a link step or a test
	// waiting on a socket; three -- a minute and a half at the default sample
	// interval -- is a job that has settled below what it was given.
	LoanReclaimSamples = 3
	// LoanBackoff is how long a runner whose loan was withdrawn waits before
	// it may be lent again on ordinary demand. Without it, a runner that
	// saturates its guarantee but not a loan is demanding again on the very
	// next sample, and is lent, wastes it and loses it in a loop.
	LoanBackoff = 5 * time.Minute
	// LoanBackoffMax caps the backoff, which doubles each time a loan is
	// wasted again straight after one. A job whose demand really has changed
	// is never kept waiting longer than this.
	LoanBackoffMax = 30 * time.Minute
	// LoanSaturatedShare is the share of its current limit a runner must use
	// to count as pressing against it. Short of the whole limit, because a
	// cgroup at its quota still reads a little under it once the sample's
	// window is averaged.
	LoanSaturatedShare = 0.95
)

// LoanMemory is what the planner remembers about one runner's loan between
// heartbeats. The zero value is a runner nothing is known about.
type LoanMemory struct {
	// LastSampleAt is the sample the memory was last advanced by. A heartbeat
	// that carries the same sample again counts for nothing: the thresholds
	// are counted in samples, not heartbeats.
	LastSampleAt time.Time
	// LowSamples is how many fresh samples in a row showed the current loan
	// unused.
	LowSamples int
	// WastedAt is when a loan was last withdrawn as unused; zero when none
	// has been, or the backoff has been spent by a loan that was used.
	WastedAt time.Time
	// Strikes is how many loans in a row were withdrawn unused. It doubles the
	// backoff, and a loan that is used clears it.
	Strikes int
	// WastedPeakCPUs is the most CPU the runner used while it held the loan
	// that was withdrawn. It is what makes a saturated guarantee a new signal
	// or an old one: see DecideLoan.
	WastedPeakCPUs float64
	// PeakCPUs is the most CPU the runner has used under its current loan.
	PeakCPUs float64
}

// LoanInput is one runner at one heartbeat. Now is passed in rather than
// read, so the decision is a function of its input and can be tested one
// heartbeat at a time.
type LoanInput struct {
	Now time.Time
	// SampledAt is when UsedCPUs was measured; zero is no sample at all.
	SampledAt time.Time
	// BaseCPUs is the runner's guarantee and LimitCPUs the quota it holds
	// now: above BaseCPUs while it is lent CPU, equal to it otherwise.
	BaseCPUs  float64
	LimitCPUs float64
	UsedCPUs  float64
	// HolderBaseCPUs and HolderUsedCPUs are the guarantee and use of the
	// container the loan is actually given to, where that is not the whole
	// runner: a docker-in-docker pair's loan goes to its busier half alone,
	// so the pair's sum -- the idle half's share included -- would read a
	// daemon using two lent cores as a loan barely touched. Zero means the
	// runner is one container, and BaseCPUs and UsedCPUs are the holder's.
	HolderBaseCPUs float64
	HolderUsedCPUs float64
	// Saturated is a signal besides UsedCPUs that the runner is pressing
	// against its limit: the cgroup's throttling counters rose, or the busier
	// half of a docker-in-docker pair is at its own quota.
	Saturated bool
	// Demanding is the ordinary entry test: the runner is using most of its
	// guarantee or being throttled at it.
	Demanding bool
	Memory    LoanMemory
}

// LoanCode is a stable name for a loan decision, for metrics and tests.
type LoanCode string

const (
	LoanNotDemanding    LoanCode = "not_demanding"
	LoanLend            LoanCode = "lend"
	LoanInUse           LoanCode = "in_use"
	LoanWatching        LoanCode = "watching"
	LoanReclaimed       LoanCode = "reclaimed"
	LoanBackingOff      LoanCode = "backing_off"
	LoanBackoffOverride LoanCode = "backoff_overridden"
)

// LoanDecision says whether a runner may take part in this heartbeat's
// water-fill, and why, in words an operator reading a log can act on.
type LoanDecision struct {
	Lend   bool
	Code   LoanCode
	Reason string
	Memory LoanMemory
}

// Backoff is how long the runner waits after its latest wasted loan.
func (m LoanMemory) Backoff() time.Duration {
	d := LoanBackoff
	for i := 1; i < m.Strikes && d < LoanBackoffMax; i++ {
		d *= 2
	}
	return min(d, LoanBackoffMax)
}

// DecideLoan decides whether a runner should be lent CPU at this heartbeat.
//
// A runner that holds a loan keeps it while it uses at least a quarter of it;
// after LoanReclaimSamples fresh samples below that, the loan is withdrawn and
// the runner backs off. During the backoff it is lent again only when it
// presses against its guarantee and did not while it held the wasted loan --
// that is a job whose demand changed, not the same job asking again. A job
// that used a sliver more than its guarantee under the loan is expected to
// saturate its guarantee without it, and re-lending on that would be the
// flap this exists to stop.
func DecideLoan(in LoanInput) LoanDecision {
	m := in.Memory
	fresh := !in.SampledAt.IsZero() && in.SampledAt.After(m.LastSampleAt)
	if fresh {
		m.LastSampleAt = in.SampledAt
	}
	lent := in.LimitCPUs > in.BaseCPUs+cpuEpsilon
	loan := in.LimitCPUs - in.BaseCPUs

	if !m.WastedAt.IsZero() {
		since := in.Now.Sub(m.WastedAt)
		if since < m.Backoff() {
			// A sample can still show the loan for a heartbeat after it was
			// withdrawn, because the agent moves the quota only once it has
			// the plan. That is not the runner holding a loan, and judging it
			// as one would lend the CPU straight back.
			pressing := !lent && (in.UsedCPUs >= LoanSaturatedShare*in.LimitCPUs || in.Saturated)
			// The wasted loan's peak is what separates a new demand from the
			// old one: a job that stayed under its guarantee while it was lent
			// more, and now fills it, has started doing something else.
			if pressing && m.WastedPeakCPUs < LoanSaturatedShare*in.BaseCPUs {
				m.WastedAt, m.WastedPeakCPUs, m.LowSamples, m.PeakCPUs = time.Time{}, 0, 0, 0
				return LoanDecision{Lend: true, Code: LoanBackoffOverride, Memory: m, Reason: fmt.Sprintf(
					"lent again before its backoff ended: now at its %.2f CPU limit, where it used only %.2f while it last held a loan",
					in.LimitCPUs, in.Memory.WastedPeakCPUs)}
			}
			m.LowSamples, m.PeakCPUs = 0, 0
			return LoanDecision{Code: LoanBackingOff, Memory: m, Reason: fmt.Sprintf(
				"not lent: its last loan went unused, and it waits another %s before it is lent again",
				(m.Backoff() - since).Round(time.Second))}
		}
		if since >= m.Backoff()+LoanBackoffMax {
			// Long enough ago that the next waste is a new story, not a
			// repeat of the last one.
			m.WastedAt, m.WastedPeakCPUs, m.Strikes = time.Time{}, 0, 0
		}
	}

	if lent {
		if fresh {
			m.PeakCPUs = max(m.PeakCPUs, in.UsedCPUs)
		}
		holderBase, holderUsed := in.BaseCPUs, in.UsedCPUs
		if in.HolderBaseCPUs > 0 {
			holderBase, holderUsed = in.HolderBaseCPUs, in.HolderUsedCPUs
		}
		floor := holderBase + LoanInUseShare*loan
		if holderUsed >= floor {
			m.LowSamples, m.Strikes, m.WastedAt, m.WastedPeakCPUs = 0, 0, time.Time{}, 0
			return LoanDecision{Lend: true, Code: LoanInUse, Memory: m, Reason: fmt.Sprintf(
				"keeps its loan: using %.2f CPUs where the loan is, at least a quarter of the %.2f lent above a %.2f share",
				holderUsed, loan, holderBase)}
		}
		if fresh {
			m.LowSamples++
		}
		if m.LowSamples < LoanReclaimSamples {
			return LoanDecision{Lend: true, Code: LoanWatching, Memory: m, Reason: fmt.Sprintf(
				"keeps its loan for now: using %.2f CPUs where the loan is, under %.2f, for %d of %d samples before it is taken back",
				holderUsed, floor, m.LowSamples, LoanReclaimSamples)}
		}
		m.Strikes++
		m.WastedAt, m.WastedPeakCPUs = in.Now, m.PeakCPUs
		m.LowSamples, m.PeakCPUs = 0, 0
		return LoanDecision{Code: LoanReclaimed, Memory: m, Reason: fmt.Sprintf(
			"loan taken back: used at most %.2f CPUs of %.2f for %d samples in a row; not lent again for %s unless its demand changes",
			m.WastedPeakCPUs, in.LimitCPUs, LoanReclaimSamples, m.Backoff())}
	}

	m.LowSamples, m.PeakCPUs = 0, 0
	if in.Demanding {
		return LoanDecision{Lend: true, Code: LoanLend, Memory: m, Reason: fmt.Sprintf(
			"may be lent CPU: using %.2f CPUs of its %.2f guarantee, or throttled at it", in.UsedCPUs, in.BaseCPUs)}
	}
	return LoanDecision{Code: LoanNotDemanding, Memory: m, Reason: fmt.Sprintf(
		"not lent: using %.2f CPUs of its %.2f guarantee, short of what would count as demand", in.UsedCPUs, in.BaseCPUs)}
}

package scheduler

import (
	"strings"
	"testing"
	"time"
)

// beat is one heartbeat of one runner: what the agent measured and what quota
// the runner held when it did.
type beat struct {
	after     time.Duration // since the first heartbeat
	limit     float64
	used      float64
	saturated bool
	demanding bool
	stale     bool // the same sample as the previous heartbeat
	// holderBase and holderUsed are a docker-in-docker pair's busier half.
	holderBase, holderUsed float64
	want                   LoanCode
}

// Each case is a runner followed across heartbeats, because what this rule
// exists to get right -- reclaim once, back off, and do not flap -- only shows
// over a sequence. A guarantee of 2 CPUs throughout; a loan is a limit of 4.
func TestDecideLoanFollowsARunnerAcrossHeartbeats(t *testing.T) {
	const base = 2.0
	s := 30 * time.Second
	cases := []struct {
		name  string
		beats []beat
	}{
		{"a runner using its guarantee is lent", []beat{
			{after: 0, limit: 2, used: 1.9, demanding: true, want: LoanLend},
		}},
		// Codex review: the pair's sum counts the idle half's share as if it
		// were the loan's, and read a daemon using two lent cores as a loan
		// barely touched.
		{"a docker-in-docker daemon using its loan keeps it though the pair's sum is low", []beat{
			{after: 0, limit: 4, used: 2.4, holderBase: 1, holderUsed: 2.3, want: LoanInUse},
			{after: s, limit: 4, used: 2.4, holderBase: 1, holderUsed: 2.3, want: LoanInUse},
			{after: 2 * s, limit: 4, used: 2.4, holderBase: 1, holderUsed: 2.3, want: LoanInUse},
			{after: 3 * s, limit: 4, used: 2.4, holderBase: 1, holderUsed: 2.3, want: LoanInUse},
		}},
		{"a docker-in-docker pair whose busier half ignores its loan loses it", []beat{
			{after: 0, limit: 4, used: 2.6, holderBase: 1, holderUsed: 1.1, want: LoanWatching},
			{after: s, limit: 4, used: 2.6, holderBase: 1, holderUsed: 1.1, want: LoanWatching},
			{after: 2 * s, limit: 4, used: 2.6, holderBase: 1, holderUsed: 1.1, want: LoanReclaimed},
		}},
		{"a quiet runner is not lent", []beat{
			{after: 0, limit: 2, used: 0.4, want: LoanNotDemanding},
		}},
		{"a runner using a quarter of its loan holds it", []beat{
			{after: 0, limit: 4, used: 2.5, want: LoanInUse},
			{after: s, limit: 4, used: 3.9, want: LoanInUse},
		}},
		{"an unused loan is watched, then reclaimed after three samples", []beat{
			{after: 0, limit: 4, used: 2.1, want: LoanWatching},
			{after: s, limit: 4, used: 2.2, want: LoanWatching},
			{after: 2 * s, limit: 4, used: 2.0, want: LoanReclaimed},
		}},
		{"one busy sample resets the count", []beat{
			{after: 0, limit: 4, used: 2.1, want: LoanWatching},
			{after: s, limit: 4, used: 2.1, want: LoanWatching},
			{after: 2 * s, limit: 4, used: 3.5, want: LoanInUse},
			{after: 3 * s, limit: 4, used: 2.1, want: LoanWatching},
			{after: 4 * s, limit: 4, used: 2.1, want: LoanWatching},
			{after: 5 * s, limit: 4, used: 2.1, want: LoanReclaimed},
		}},
		{"a heartbeat repeating a sample does not count towards a reclaim", []beat{
			{after: 0, limit: 4, used: 2.1, want: LoanWatching},
			{after: s, limit: 4, used: 2.1, stale: true, want: LoanWatching},
			{after: 2 * s, limit: 4, used: 2.1, stale: true, want: LoanWatching},
			{after: 3 * s, limit: 4, used: 2.1, want: LoanWatching},
			{after: 4 * s, limit: 4, used: 2.1, want: LoanReclaimed},
		}},
		{"a reclaimed runner saturating its guarantee is not lent again straight away", []beat{
			{after: 0, limit: 4, used: 2.1, want: LoanWatching},
			{after: s, limit: 4, used: 2.1, want: LoanWatching},
			{after: 2 * s, limit: 4, used: 2.1, want: LoanReclaimed},
			// The agent has not moved the quota yet: still no loan.
			{after: 3 * s, limit: 4, used: 2.1, demanding: true, want: LoanBackingOff},
			{after: 4 * s, limit: 2, used: 2.0, demanding: true, saturated: true, want: LoanBackingOff},
			{after: 4*s + 3*time.Minute, limit: 2, used: 2.0, demanding: true, saturated: true, want: LoanBackingOff},
		}},
		{"after the backoff a demanding runner is lent again", []beat{
			{after: 0, limit: 4, used: 2.1, want: LoanWatching},
			{after: s, limit: 4, used: 2.1, want: LoanWatching},
			{after: 2 * s, limit: 4, used: 2.1, want: LoanReclaimed},
			{after: 2*s + LoanBackoff, limit: 2, used: 2.0, demanding: true, want: LoanLend},
		}},
		{"a second wasted loan doubles the backoff", []beat{
			{after: 0, limit: 4, used: 2.1, want: LoanWatching},
			{after: s, limit: 4, used: 2.1, want: LoanWatching},
			{after: 2 * s, limit: 4, used: 2.1, want: LoanReclaimed},
			{after: 2*s + LoanBackoff, limit: 4, used: 2.1, want: LoanWatching},
			{after: 3*s + LoanBackoff, limit: 4, used: 2.1, want: LoanWatching},
			{after: 4*s + LoanBackoff, limit: 4, used: 2.1, want: LoanReclaimed},
			{after: 4*s + 2*LoanBackoff, limit: 2, used: 2.0, demanding: true, want: LoanBackingOff},
			{after: 4*s + 3*LoanBackoff, limit: 2, used: 2.0, demanding: true, want: LoanLend},
		}},
		{"a runner that was quiet under its loan and now fills its guarantee is lent inside the backoff", []beat{
			{after: 0, limit: 4, used: 0.5, want: LoanWatching},
			{after: s, limit: 4, used: 0.6, want: LoanWatching},
			{after: 2 * s, limit: 4, used: 0.5, want: LoanReclaimed},
			{after: 3 * s, limit: 2, used: 0.5, want: LoanBackingOff},
			{after: 4 * s, limit: 2, used: 1.98, demanding: true, want: LoanBackoffOverride},
			{after: 5 * s, limit: 4, used: 3.8, want: LoanInUse},
		}},
	}
	start := time.Date(2026, 9, 27, 12, 0, 0, 0, time.UTC)
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			var m LoanMemory
			sampled := time.Time{}
			for i, b := range tc.beats {
				now := start.Add(b.after)
				if !b.stale {
					sampled = now.Add(-time.Second)
				}
				d := DecideLoan(LoanInput{
					Now: now, SampledAt: sampled, BaseCPUs: base, LimitCPUs: b.limit, UsedCPUs: b.used,
					HolderBaseCPUs: b.holderBase, HolderUsedCPUs: b.holderUsed,
					Saturated: b.saturated, Demanding: b.demanding, Memory: m,
				})
				if d.Code != b.want {
					t.Fatalf("heartbeat %d: %s (%q), want %s", i, d.Code, d.Reason, b.want)
				}
				if d.Lend != (b.want == LoanLend || b.want == LoanInUse || b.want == LoanWatching || b.want == LoanBackoffOverride) {
					t.Fatalf("heartbeat %d: lend = %v for %s", i, d.Lend, d.Code)
				}
				if strings.TrimSpace(d.Reason) == "" {
					t.Fatalf("heartbeat %d: %s has no reason an operator can read", i, d.Code)
				}
				m = d.Memory
			}
		})
	}
}

// The flap this rule exists to stop: a job that sized its workers to a little
// over its guarantee is demanding at the guarantee, wastes any loan, and was
// lent, reclaimed and lent again every few heartbeats. Across an hour it may
// change its quota only a handful of times.
func TestDecideLoanDoesNotFlapOnAJobThatUsesALittleMoreThanItsGuarantee(t *testing.T) {
	const base = 2.0
	start := time.Date(2026, 9, 27, 12, 0, 0, 0, time.UTC)
	var m LoanMemory
	limit, changes := base, 0
	for i := range 120 {
		now := start.Add(time.Duration(i) * 30 * time.Second)
		used := min(limit, 2.2)
		d := DecideLoan(LoanInput{
			Now: now, SampledAt: now, BaseCPUs: base, LimitCPUs: limit, UsedCPUs: used,
			Saturated: used >= limit*LoanSaturatedShare, Demanding: used >= 0.8*base, Memory: m,
		})
		m = d.Memory
		next := base
		if d.Lend {
			next = 4
		}
		if next != limit {
			changes++
		}
		limit = next
	}
	// Lent and reclaimed at 0, 5, 15 and 35 minutes, then held off for the
	// capped half hour: under a dozen changes, where a rule without memory
	// makes one every few heartbeats.
	if changes > 12 {
		t.Fatalf("the quota changed %d times in an hour, want a handful", changes)
	}
}

func TestLoanBackoffIsCapped(t *testing.T) {
	if got := (LoanMemory{Strikes: 20}).Backoff(); got != LoanBackoffMax {
		t.Fatalf("backoff after twenty strikes = %s, want the cap %s", got, LoanBackoffMax)
	}
	if got := (LoanMemory{Strikes: 1}).Backoff(); got != LoanBackoff {
		t.Fatalf("backoff after one strike = %s, want %s", got, LoanBackoff)
	}
}

package scheduler

import (
	"github.com/eyupio/zoomies/internal/store"
)

// DefaultMemoryCeilingFactor is how much memory one runner may hold, as a
// multiple of its guarantee, when neither its pool nor its host has named a
// ceiling. Half as much again is enough to turn most kills that a build just
// failed to fit under into a job that finished, and little enough that one
// runaway job cannot take a machine from the runners beside it.
const DefaultMemoryCeilingFactor = 1.5

// MemoryPoolSafetyShare is the share of a host's memory that is kept free over
// and above the reserve the operator set, before any of it is lent. The reserve
// is what the host's own software needs; this is what the page cache, the
// daemon and a runner that is still starting need, so that a loan never leaves
// the machine with exactly as much room as it has just been measured to need.
const MemoryPoolSafetyShare = 0.05

// LaunchedMemoryMB is the memory a runner's containers were created with, summed
// over them, read from its row: what the host actually put at risk when the
// runner started, and so the figure a loan is a loan on top of.
//
// The pool's current size is not that figure. A pool or a host edited while the
// runner lives -- a capacity changed, a standard resized -- changes what
// Reserve says a runner of that pool costs, and a valve that took its guarantee
// from there would read a runner holding 7782 MB as guaranteed 3891, give it a
// ceiling it is already above, and call a refusal a policy. The row is the one
// place the size it was launched at is written down. It is false for a runner
// with none, which is every runner of a backend that sets no limit.
//
// A docker-in-docker runner's typed size is per container, so the pair holds
// twice it; a size taken from the host is one slot the pair splits, so it holds
// it once. That is the distinction Reserve draws, read from how the runner was
// sized rather than from how the pool is sized now.
func LaunchedMemoryMB(p *store.Pool, r *store.Runner) (int64, bool) {
	if p == nil || r == nil || r.AllocatedMemoryMB <= 0 {
		return 0, false
	}
	mb := r.AllocatedMemoryMB
	if p.DockerMode == store.DockerDinD && (r.AllocationSource == store.AllocationFromPool ||
		((r.AllocationSource == store.AllocationReduced || r.AllocationSource == store.AllocationHistory) && p.Resources.MemoryMB > 0)) {
		mb *= 2
	}
	return mb, true
}

// MemoryCeiling is the most one runner of p may hold on h, given what it was
// guaranteed. It is the ceiling the pool named or, where it named none,
// DefaultMemoryCeilingFactor times the guarantee; the host's own ceiling then
// lowers that and never raises it, for the reason CPU's does -- whoever owns the
// machine has the last word on how much of it one job may take, and a host that
// caps its runners at 32 GB has not asked for a pool that left the figure alone
// to be given 32 GB. It is never below the guarantee, because a ceiling lower
// than what a runner already has would be a request to take memory back, which
// nothing here can do; and never more than the memory of the host, or of the
// daemon the runner runs on where that is the smaller machine.
//
// That last is the one easily forgotten, as it is for CPU: a Docker Desktop or
// VM daemon is smaller than the machine the agent measured, and refuses a limit
// above its own memory outright, so a ceiling past it would be a loan that fails
// on every attempt.
func MemoryCeiling(p *store.Pool, h *store.Host, guaranteeMB int64) int64 {
	if guaranteeMB <= 0 {
		return 0
	}
	ceiling := int64(float64(guaranteeMB) * DefaultMemoryCeilingFactor)
	if p != nil && p.MemoryBurst.MaxMemoryMB > 0 {
		ceiling = p.MemoryBurst.MaxMemoryMB
	}
	if h != nil {
		if capMB := h.RunnerProfile.Standard.BurstMaxMemoryMB; capMB > 0 {
			ceiling = min(ceiling, capMB)
		}
		if h.MemoryMB > 0 {
			ceiling = min(ceiling, h.MemoryMB)
		}
		if p != nil {
			if info, ok := h.BackendInfo.Find(p.Backend); ok && info.MemoryMB > 0 {
				ceiling = min(ceiling, info.MemoryMB)
			}
		}
	}
	return max(ceiling, guaranteeMB)
}

// MemoryPoolFloor is the least free memory a host is left with by any loan: the
// reserve its operator set, or the floor where that is larger (Host.MemoryReserve),
// and a twentieth of the machine beyond it (MemoryPoolSafetyShare). Zero for a
// host that has not reported its memory, which has nothing to be left.
func MemoryPoolFloor(h *store.Host) int64 {
	if h == nil || h.MemoryMB <= 0 {
		return 0
	}
	return h.MemoryReserve() + int64(MemoryPoolSafetyShare*float64(h.MemoryMB))
}

// MemoryWorkload is one live runner in a host's memory ledger. Every live runner
// belongs in the input, including ones that will never be lent anything: their
// guarantee is already promised, so it is not memory to lend.
type MemoryWorkload struct {
	ID string
	// GuaranteeMB is what the runner was created with, summed over its
	// containers: its guarantee, without any loan (RunnerGuarantee).
	GuaranteeMB int64
	// LentMB is what it has been lent since, which is still held.
	LentMB int64
	// Idle is a live runner waiting for a job. Idle runners are charged together
	// only the largest single guarantee among them, as they are for CPU: at most
	// one of them can be handed the next job before the next plan, and memory
	// they are not using is the whole of what there is to lend. The oversubscription
	// that allows is bounded by the next plan, which charges whichever turned busy
	// in full, and by the agent's own look at the host before each raise.
	Idle bool
}

// MemoryPoolInput is one host at one heartbeat.
type MemoryPoolInput struct {
	// TotalMB is the host's memory, and FloorMB what a loan must leave free
	// (MemoryPoolFloor).
	TotalMB, FloorMB int64
	// StartReserveMB protects an imminent runner when compatible work is queued:
	// the guarantee of the largest one, as it is for CPU.
	StartReserveMB int64
	// AvailableMB is what the host measured as available now, nil when it did
	// not. A loan is made out of memory that is free, not out of memory the
	// ledger says nobody promised, so the smaller of the two is what there is.
	AvailableMB *int64
	Workloads   []MemoryWorkload
}

// MemoryPool is what a host can lend, and how that was worked out, in words the
// Hosts page can say.
type MemoryPool struct {
	// CapacityMB is the most that may be lent on the host in total, what is
	// lent already included. It is what an agent compares its own running total
	// with, so a loan it has made since the controller last counted still comes
	// out of it.
	CapacityMB int64
	// LentMB is what is lent now, and PoolMB what is left to lend: the shared
	// pool the runners that need memory draw on.
	LentMB, PoolMB int64
	// CommittedMB, IdleReserveMB and StartReserveMB are the lines of the
	// ledger the capacity was taken from, so a pool of nothing can say whose
	// guarantees it went to.
	CommittedMB, IdleReserveMB, StartReserveMB int64
	// Binding says what limited CapacityMB: MemoryBoundLedger when it was the
	// promises already made, MemoryBoundMeasured when it was the memory the host
	// measured as free.
	Binding MemoryBound
}

// MemoryBound names what limited a host's pool of memory.
type MemoryBound string

const (
	MemoryBoundLedger   MemoryBound = "ledger"
	MemoryBoundMeasured MemoryBound = "measured"
)

// PlanMemoryPool works out how much memory a host may lend: what is neither
// promised to a runner nor needed to leave the machine its floor, and is free
// now.
//
// It is the memory counterpart of ElasticCPUPlan, and the two differ in the
// one way that matters. CPU is lent and taken back by the same plan, one
// heartbeat at a time; memory cannot be taken back, so this does not say what
// each runner is to have -- it says how much the host as a whole may give away,
// and the agent hands it out as runners need it, bounded by the ceilings. What
// has been given away already comes off the pool, and never comes back until
// the runner that holds it is gone.
//
// Busy and starting runners are charged their guarantee in full; idle runners
// the largest one between them; one compatible queued start is protected. What
// is left of the machine beyond that, above its floor, is the capacity.
func PlanMemoryPool(in MemoryPoolInput) MemoryPool {
	out := MemoryPool{StartReserveMB: max(in.StartReserveMB, 0)}
	// The ledger is sums and one maximum, so the order the runners come in changes
	// nothing and nothing is sorted.
	for _, w := range in.Workloads {
		out.LentMB += max(w.LentMB, 0)
		if w.Idle {
			out.IdleReserveMB = max(out.IdleReserveMB, max(w.GuaranteeMB, 0))
			continue
		}
		out.CommittedMB += max(w.GuaranteeMB, 0)
	}

	ledger := max(in.TotalMB-max(in.FloorMB, 0)-out.CommittedMB-out.IdleReserveMB-out.StartReserveMB, 0)
	out.CapacityMB, out.Binding = ledger, MemoryBoundLedger
	if in.AvailableMB != nil {
		// What is free now, above the floor, is what can still be handed out;
		// what is lent already is in use, so it is added back to make a total.
		if measured := max(*in.AvailableMB-max(in.FloorMB, 0), 0) + out.LentMB; measured < out.CapacityMB {
			out.CapacityMB, out.Binding = measured, MemoryBoundMeasured
		}
	}
	out.PoolMB = max(out.CapacityMB-out.LentMB, 0)
	return out
}

package scheduler

import (
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

func memoryPool(max int64) *store.Pool {
	p := limited("mem", 0, 4096)
	p.MemoryBurst = store.MemoryBurstPolicy{Mode: store.MemoryBurstAutomatic, MaxMemoryMB: max}
	return p
}

func hostWithMemoryCeiling(memoryMB, ceiling int64) *store.Host {
	h := sized("host_a", 4, 8, memoryMB, 100*1024)
	h.RunnerProfile.Standard.BurstMaxMemoryMB = ceiling
	return h
}

// A ceiling is where the owner of the machine and the owner of the pool meet,
// and the host's word is the last: a pool asking for more than the host will
// give simply gets what it will. It is a cap, so it lowers whatever the pool
// asked for -- a ceiling it named or the default half as much again -- and never
// raises it.
func TestTheHostsMemoryCeilingOnlyEverLowersThePoolsAndNeverRaisesIt(t *testing.T) {
	for _, tc := range []struct {
		name       string
		pool, host int64
		want       int64
	}{
		{"neither says: half as much again", 0, 0, 6144},
		{"only the pool says", 12288, 0, 12288},
		{"only a host that caps higher than the default leaves the default", 0, 8192, 6144},
		{"only a host that caps lower than the default lowers it", 0, 5000, 5000},
		{"the host is lower than the pool", 12288, 8192, 8192},
		{"the pool is lower than the host", 6144, 8192, 6144},
		{"a host cap under the guarantee is read as lend nothing", 0, 2048, 4096},
	} {
		if got := MemoryCeiling(memoryPool(tc.pool), hostWithMemoryCeiling(32*1024, tc.host), 4096); got != tc.want {
			t.Errorf("%s: ceiling = %d, want %d", tc.name, got, tc.want)
		}
	}
}

// What a runner was launched with is on its row, and a pool or host edited
// since must not move it.
func TestAGuaranteeIsReadFromTheRunnerNotFromThePoolAsItIsNow(t *testing.T) {
	typedPair := &store.Pool{DockerMode: store.DockerDinD, Resources: store.Resources{MemoryMB: 4096}}
	automaticPair := &store.Pool{DockerMode: store.DockerDinD}
	typed := &store.Pool{Resources: store.Resources{MemoryMB: 4096}}
	for _, tc := range []struct {
		name   string
		pool   *store.Pool
		runner *store.Runner
		want   int64
		ok     bool
	}{
		{"a typed size is what the one container was given", typed, &store.Runner{AllocatedMemoryMB: 4096, AllocationSource: store.AllocationFromPool}, 4096, true},
		{"a typed pair holds it twice", typedPair, &store.Runner{AllocatedMemoryMB: 4096, AllocationSource: store.AllocationFromPool}, 8192, true},
		{"a slot taken from the host is one slot the pair shares", automaticPair, &store.Runner{AllocatedMemoryMB: 7782, AllocationSource: store.AllocationFromHost}, 7782, true},
		{"so is a slot taken from the host's profile", automaticPair, &store.Runner{AllocatedMemoryMB: 7782, AllocationSource: store.AllocationFromProfile}, 7782, true},
		{"a reduced typed pair is still twice what each was given", typedPair, &store.Runner{AllocatedMemoryMB: 3000, AllocationSource: store.AllocationReduced}, 6000, true},
		{"a reduced slot is still one", automaticPair, &store.Runner{AllocatedMemoryMB: 3000, AllocationSource: store.AllocationReduced}, 3000, true},
		{"a runner with no recorded size has none", typed, &store.Runner{}, 0, false},
		{"no pool, no answer", nil, &store.Runner{AllocatedMemoryMB: 4096}, 0, false},
	} {
		got, ok := LaunchedMemoryMB(tc.pool, tc.runner)
		if got != tc.want || ok != tc.ok {
			t.Errorf("%s: %d, %v; want %d, %v", tc.name, got, ok, tc.want, tc.ok)
		}
	}
}

func TestAMemoryCeilingIsHalfAsMuchAgainUnlessSomeoneSaidOtherwise(t *testing.T) {
	h := hostWithMemoryCeiling(32*1024, 0)
	for _, tc := range []struct {
		name      string
		pool      int64
		guarantee int64
		want      int64
	}{
		{"the default", 0, 4096, 6144},
		{"a ceiling the operator named is the ceiling, not a multiple", 16384, 4096, 16384},
		// A ceiling under the guarantee would be a request to take memory back,
		// which nothing can do, so it is read as "lend nothing".
		{"never below the guarantee", 2048, 4096, 4096},
		{"no guarantee has no ceiling", 0, 0, 0},
	} {
		if got := MemoryCeiling(memoryPool(tc.pool), h, tc.guarantee); got != tc.want {
			t.Errorf("%s: ceiling = %d, want %d", tc.name, got, tc.want)
		}
	}
}

func TestAMemoryCeilingNeverPassesTheMachineItRunsOn(t *testing.T) {
	h := hostWithMemoryCeiling(8*1024, 0)
	if got := MemoryCeiling(memoryPool(64*1024), h, 4096); got != 8*1024 {
		t.Fatalf("ceiling on an 8 GB host = %d, want the host's own 8192", got)
	}
	// A daemon smaller than the machine the agent measured refuses a limit
	// above its own memory, so the ceiling is the daemon's.
	h.BackendInfo = store.HostBackends{{Kind: store.BackendDocker, Available: true, MemoryMB: 6 * 1024}}
	if got := MemoryCeiling(memoryPool(64*1024), h, 4096); got != 6*1024 {
		t.Fatalf("ceiling on a 6 GB daemon = %d, want 6144", got)
	}
}

func TestTheFloorIsTheReservePlusAnotherTwentiethOfTheMachine(t *testing.T) {
	h := sized("host_a", 4, 8, 16*1024, 100*1024)
	h.ReserveMemoryMB = 2048
	want := h.MemoryReserve() + 16*1024/20
	if got := MemoryPoolFloor(h); got != want {
		t.Fatalf("floor = %d, want %d (reserve %d plus 5%%)", got, want, h.MemoryReserve())
	}
	if got := MemoryPoolFloor(&store.Host{}); got != 0 {
		t.Fatalf("a host that has not reported its memory has a floor of %d, want 0", got)
	}
	if got := MemoryPoolFloor(nil); got != 0 {
		t.Fatalf("no host has a floor of %d, want 0", got)
	}
}

func ptr[T any](v T) *T { return &v }

// The pool is what is left of the machine once every promise is kept: busy and
// starting runners in full, idle ones by the largest between them, one queued
// start protected, and the floor left alone.
func TestThePoolIsWhatNoGuaranteeNeeds(t *testing.T) {
	const gb = 1024
	work := []MemoryWorkload{
		{ID: "busy", GuaranteeMB: 4 * gb},
		{ID: "idle-1", GuaranteeMB: 4 * gb, Idle: true},
		{ID: "idle-2", GuaranteeMB: 2 * gb, Idle: true},
	}
	got := PlanMemoryPool(MemoryPoolInput{TotalMB: 16 * gb, FloorMB: 2 * gb, StartReserveMB: 0, Workloads: work})
	// 16 - 2 floor - 4 busy - 4 largest idle = 6 GB, none lent.
	if got.CapacityMB != 6*gb || got.PoolMB != 6*gb || got.LentMB != 0 {
		t.Fatalf("pool = %+v, want 6 GB capacity, all of it left", got)
	}
	if got.CommittedMB != 4*gb || got.IdleReserveMB != 4*gb || got.Binding != MemoryBoundLedger {
		t.Fatalf("ledger lines = %+v", got)
	}

	protected := PlanMemoryPool(MemoryPoolInput{TotalMB: 16 * gb, FloorMB: 2 * gb, StartReserveMB: 4 * gb, Workloads: work})
	if protected.CapacityMB != 2*gb {
		t.Fatalf("with a start protected capacity = %d, want 2048", protected.CapacityMB)
	}
}

// A host whose runners are all busy has promised every byte it has, and the
// valve lends none of it: the promise is what the guarantee is. Lending out of
// a busy runner's unused share would be the oversubscription the ceiling and
// the floor exist to prevent.
func TestAFullyPromisedHostLendsNothing(t *testing.T) {
	const gb = 1024
	work := []MemoryWorkload{{ID: "a", GuaranteeMB: 7 * gb}, {ID: "b", GuaranteeMB: 7 * gb}}
	got := PlanMemoryPool(MemoryPoolInput{TotalMB: 16 * gb, FloorMB: 2 * gb, Workloads: work})
	if got.CapacityMB != 0 || got.PoolMB != 0 {
		t.Fatalf("a host with every byte promised has a pool of %+v, want nothing", got)
	}
}

// What has been lent comes off the pool and stays off it: a loan cannot be
// recalled, so the memory it holds is not there for the next runner whatever
// the runner that holds it is doing.
func TestMemoryAlreadyLentComesOffThePoolButNotOffTheCapacity(t *testing.T) {
	const gb = 1024
	work := []MemoryWorkload{{ID: "a", GuaranteeMB: 4 * gb, LentMB: 1 * gb}}
	got := PlanMemoryPool(MemoryPoolInput{TotalMB: 16 * gb, FloorMB: 2 * gb, Workloads: work})
	if got.CapacityMB != 10*gb || got.LentMB != 1*gb || got.PoolMB != 9*gb {
		t.Fatalf("pool = %+v, want capacity 10 GB, lent 1 GB, 9 GB left", got)
	}
}

// A ledger says what was promised; the machine says what is free. The pool is
// out of the smaller, so a host with something else eating its memory lends
// less than its books allow.
func TestTheMemoryTheHostMeasuredAsFreeCanLimitThePool(t *testing.T) {
	const gb = 1024
	work := []MemoryWorkload{{ID: "a", GuaranteeMB: 4 * gb, LentMB: 512}}
	in := MemoryPoolInput{TotalMB: 16 * gb, FloorMB: 2 * gb, AvailableMB: ptr(int64(3 * gb)), Workloads: work}
	got := PlanMemoryPool(in)
	// 3 GB free, 2 GB of it the floor: 1 GB can still be handed out, on top of
	// the 512 MB already out.
	if got.PoolMB != 1*gb || got.CapacityMB != 1*gb+512 || got.Binding != MemoryBoundMeasured {
		t.Fatalf("pool = %+v, want 1 GB left, bound by what was measured", got)
	}

	// Plenty free: the books are the limit again.
	in.AvailableMB = ptr(int64(14 * gb))
	if got := PlanMemoryPool(in); got.Binding != MemoryBoundLedger || got.CapacityMB != 10*gb {
		t.Fatalf("with plenty free the pool = %+v, want the ledger's 10 GB", got)
	}

	// Below the floor there is nothing, and the figure is not negative.
	in.AvailableMB = ptr(int64(gb))
	if got := PlanMemoryPool(in); got.PoolMB != 0 {
		t.Fatalf("below the floor the pool = %+v, want nothing", got)
	}
}

// A runner waiting for a job holds almost none of its memory, which is the whole
// of what there is to lend -- but a host cannot count every warm runner as free,
// or the first burst of jobs would find them all claiming memory it had lent.
// One guarantee is held back between them, the same line the CPU plan draws.
func TestWarmRunnersAreHeldBackByTheLargestOneNotAll(t *testing.T) {
	const gb = 1024
	work := []MemoryWorkload{{ID: "busy", GuaranteeMB: 4 * gb}}
	for _, id := range []string{"i1", "i2", "i3"} {
		work = append(work, MemoryWorkload{ID: id, GuaranteeMB: 4 * gb, Idle: true})
	}
	got := PlanMemoryPool(MemoryPoolInput{TotalMB: 32 * gb, FloorMB: 2 * gb, Workloads: work})
	if got.PoolMB != 22*gb {
		t.Fatalf("pool = %d, want 22 GB: one busy and one idle guarantee held, not four", got.PoolMB)
	}
}

func TestThePlanDoesNotDependOnTheOrderOfTheRunners(t *testing.T) {
	const gb = 1024
	a := []MemoryWorkload{{ID: "x", GuaranteeMB: 4 * gb}, {ID: "y", GuaranteeMB: 2 * gb, Idle: true}, {ID: "z", GuaranteeMB: 3 * gb, Idle: true}}
	b := []MemoryWorkload{a[2], a[0], a[1]}
	in := MemoryPoolInput{TotalMB: 16 * gb, FloorMB: gb}
	in.Workloads = a
	first := PlanMemoryPool(in)
	in.Workloads = b
	if second := PlanMemoryPool(in); first != second {
		t.Fatalf("plans differ with the order: %+v and %+v", first, second)
	}
}

// A lent runner is charged what it holds, so the host has less room for the
// next one -- which is the point of a ledger that does not forget a loan.
func TestALentRunnerIsChargedWhatItHoldsAndGuaranteedWhatItWasPromised(t *testing.T) {
	p := limited("p", 0, 4096)
	h := sized("host_a", 4, 8, hostFor(16*1024), 100*1024)
	r := onHost(testRunner("r1", p, store.RunnerBusy, 0), "host_a")
	r.AllocatedMemoryMB = 4096
	r.AllocationSource = store.AllocationFromPool
	r.LentMemoryMB = 1536

	if got := RunnerGuarantee(p, h, r).MemoryMB; got != 4096 {
		t.Fatalf("guarantee = %d, want 4096: a loan is not part of what was promised", got)
	}
	if got := RunnerCharge(p, h, r).MemoryMB; got != 4096+1536 {
		t.Fatalf("charge = %d, want 5632: the host has lent 1536 on top of the guarantee", got)
	}
	if got := Reserved(h, []*store.Pool{p}, map[string][]*store.Runner{p.ID: {r}}).MemoryMB; got != 4096+1536 {
		t.Fatalf("the host's reserved memory = %d, want the loan counted", got)
	}
	if got := RunnerCharge(p, h, nil).MemoryMB; got != 4096 {
		t.Fatalf("a nil runner is charged %d, want the pool's own 4096", got)
	}
}

package scheduler

import (
	"math"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// HostAdmissionReason is empty when measured pressure permits new runners.
// Connectivity, configured capacity and manual cordons remain separate facts.
func HostAdmissionReason(h *store.Host, now time.Time) string {
	if !h.Usage.Fresh(now) {
		return ""
	}
	if h.Usage.CPUHeld {
		return "new starts held after sustained CPU pressure; they resume when CPU usage falls below 85%"
	}
	if v := h.Usage.MemoryAvailableMB; v != nil && *v <= h.MemoryReserve() {
		return "new starts held because available memory is at or below the host reserve"
	}
	return ""
}

func hostUnderCPUPressure(h *store.Host, now time.Time) bool {
	// Lent CPU in use is load the elastic plan chose, and the next plan
	// takes it back for a start, so it is not pressure.
	v := h.Usage.UnlentCPUPercent()
	return h.Usage.Fresh(now) && v != nil && *v >= 85
}

func (hs *hostSet) score(h *store.Host, p *store.Pool) float64 {
	if h.Slots() <= 0 {
		return -1
	}
	want, left, alloc := Reserve(p, h), hs.left[h.ID], hs.alloc[h.ID]
	score, dimensions := 0.0, 0.0
	if alloc.CPUsKnown && alloc.CPUs > 0 {
		cpu := left.CPUs
		if measured, ok := hs.observedCPU[h.ID]; ok {
			cpu = min(cpu, measured)
		}
		score += max(cpu-want.CPUs, 0) / alloc.CPUs
		dimensions++
	}
	if alloc.MemoryKnown && alloc.MemoryMB > 0 {
		score += float64(max(left.MemoryMB-want.MemoryMB, 0)) / float64(alloc.MemoryMB)
		dimensions++
	}
	if dimensions > 0 {
		return score / dimensions
	}
	// Preserve the old greatest-free-slots choice when there are no resource
	// specifications. Missing telemetry must not make an existing fleet stop.
	return float64(hs.free[h.ID]-1) / float64(h.Slots())
}

func (hs *hostSet) prefer(h, best *store.Host, p *store.Pool) bool {
	if hs.preferReadiness {
		a, b := hs.readyDelay(h, p), hs.readyDelay(best, p)
		// A small timing difference is noise; headroom breaks near ties.
		if a+5*time.Second < b {
			return true
		}
		if b+5*time.Second < a {
			return false
		}
	}
	// Spec priority decides first: it is what ranks a bigger, faster machine
	// ahead of a smaller, slower one, whichever placement order is in force.
	// Hosts that score the same fall through to the order, and hosts that
	// measure nothing all score 0, which is what keeps an old fleet placed
	// exactly as before the score existed.
	if a, b := HostPriority(h), HostPriority(best); a.Score != b.Score {
		return a.Score > b.Score
	}
	a, b := hs.alloc[h.ID], hs.alloc[best.ID]
	measured := (a.CPUsKnown || a.MemoryKnown) && (b.CPUsKnown || b.MemoryKnown)
	switch hs.order {
	case HostOrderLargestStandard:
		if c := compareStandard(Reserve(p, h), Reserve(p, best)); c != 0 {
			return c > 0
		}
	case HostOrderBestFit:
		return hs.tighter(h, best, p, measured)
	}
	if !a.CPUsKnown && !a.MemoryKnown && !b.CPUsKnown && !b.MemoryKnown {
		return hs.free[h.ID] > hs.free[best.ID]
	}
	score, bestScore := hs.score(h, p), hs.score(best, p)
	return score > bestScore+cpuEpsilon ||
		(math.Abs(score-bestScore) <= cpuEpsilon && hs.free[h.ID] > hs.free[best.ID])
}

// A serial admission queue costs one estimated service interval per start.
// Unknown hosts use a bounded prior and remain eligible; metrics never relax fit.
func (hs *hostSet) readyDelay(h *store.Host, p *store.Pool) time.Duration {
	d := hs.readiness[p.ID][h.ID]
	if d <= 0 {
		d = time.Minute
	}
	d = min(max(d, 5*time.Second), 10*time.Minute)
	warming := hs.warming[h.ID]
	// The agent starts DinD creates and everything else on separate lanes, so
	// a pool that starts no daemon of its own is not behind a warming one.
	// Counting the whole host made a host look slow to every pool whenever its
	// DinD lane was busy, and could place a runner elsewhere for no reason.
	if p.DockerMode == store.DockerDinD {
		warming = hs.warmingDinD[h.ID]
	} else {
		warming -= hs.warmingDinD[h.ID]
	}
	return time.Duration(warming+1) * d
}

package scheduler

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

func withUsage(h *store.Host, cpu float64, memoryMB int64) *store.Host {
	h.Usage = store.HostUsage{CPUPercent: &cpu, MemoryAvailableMB: &memoryMB, SampledAt: now}
	return h
}

func TestPlacementUsesHostSizeAndMeasuredHeadroomInsteadOfFreeSlots(t *testing.T) {
	p := limited("build", 2, 2048)
	for _, tc := range []struct {
		name string
		a, b *store.Host
		want string
	}{
		{"larger machine", sized("a", 4, 4, 8192, 100000), sized("b", 4, 16, 32768, 100000), "b"},
		{"busy machine has more slots", withUsage(sized("a", 10, 16, 32768, 100000), 90, 28000), withUsage(sized("b", 4, 16, 32768, 100000), 20, 28000), "b"},
		{"outside work consumes memory", withUsage(sized("a", 10, 16, 32768, 100000), 10, 1024), withUsage(sized("b", 4, 8, 16384, 100000), 40, 12000), "b"},
		{"equal measurements break ties by ID", withUsage(sized("a", 4, 8, 16384, 100000), 20, 12000), withUsage(sized("b", 4, 8, 16384, 100000), 20, 12000), "a"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			hs := newHostSet([]*store.Host{tc.b, tc.a}, []*store.Pool{p}, nil, now)
			if got := hs.place(p, 1); len(got) != 1 || got[0] != tc.want {
				t.Fatalf("placed on %v, want %s", got, tc.want)
			}
		})
	}
}

// placeAvoiding is a preference, not a refusal: a host named in avoid is
// skipped in favour of any other eligible host, but is still used once it is
// the only one left, because a host that failed a create a few minutes ago is
// still better than no host at all.
func TestPlaceAvoidingPrefersAnyOtherEligibleHost(t *testing.T) {
	a := sized("a", 4, 16, 32768, 100000)
	b := sized("b", 4, 16, 32768, 100000)
	p := limited("build", 2, 2048)

	hs := newHostSet([]*store.Host{a, b}, []*store.Pool{p}, nil, now)
	if got := hs.placeAvoiding(p, 1, map[string]bool{"a": true}); len(got) != 1 || got[0].hostID != "b" {
		t.Fatalf("placed on %v, want the host not in avoid", got)
	}

	hs = newHostSet([]*store.Host{a}, []*store.Pool{p}, nil, now)
	if got := hs.placeAvoiding(p, 1, map[string]bool{"a": true}); len(got) != 1 || got[0].hostID != "a" {
		t.Fatalf("placed on %v, want the only host even though it is avoided", got)
	}
}

func TestPlacementRebalancesEachNewReservationAcrossPools(t *testing.T) {
	a := withUsage(sized("a", 8, 16, 32768, 100000), 10, 30000)
	b := withUsage(sized("b", 8, 16, 32768, 100000), 10, 30000)
	p, q := limited("one", 4, 4096), limited("two", 4, 4096)
	hs := newHostSet([]*store.Host{a, b}, []*store.Pool{p, q}, nil, now)
	if got := hs.place(p, 1); len(got) != 1 || got[0] != "a" {
		t.Fatal(got)
	}
	if got := hs.place(q, 1); len(got) != 1 || got[0] != "b" {
		t.Fatalf("second pool ignored first reservation: %v", got)
	}
}

func TestPendingStartsAreChargedBetweenPassesWithoutChargingBusyMemoryTwice(t *testing.T) {
	p := limited("build", 1, 4096)
	for _, state := range []store.RunnerState{store.RunnerProvisioning, store.RunnerRegistering, store.RunnerBusy} {
		t.Run(string(state), func(t *testing.T) {
			h := withUsage(sized("host_a", 4, 8, 16384, 100000), 20, 6656)
			h.ActiveRunners = 1
			r := testRunner("existing", p, state, time.Minute)
			hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, map[string][]*store.Runner{p.ID: {r}}, now)
			got := hs.place(p, 1)
			if state == store.RunnerBusy && len(got) != 1 {
				t.Fatal("busy memory was subtracted twice")
			}
			if state != store.RunnerBusy && len(got) != 0 {
				t.Fatal("another pass reused memory promised to a pending start")
			}
		})
	}
}

func TestPressureHoldsNewWorkButLeavesBusyRunnersAndManualLimitsAlone(t *testing.T) {
	p := limited("build", 1, 1024)
	h := withUsage(sized("host_a", 4, 8, 16384, 100000), 99, 12000)
	h.Usage.CPUHeld = true
	h.ActiveRunners = 1
	r := testRunner("busy", p, store.RunnerBusy, time.Minute)
	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, map[string][]*store.Runner{p.ID: {r}}, now)
	if got := hs.place(p, 2); len(got) != 0 {
		t.Fatalf("held host got %v", got)
	}
	if !strings.Contains(hs.why(p).what, "pressure") {
		t.Fatal("hold had no useful reason")
	}
	if r.State != store.RunnerBusy || h.Capacity != 4 || h.Cordoned {
		t.Fatal("pressure changed existing work or operator settings")
	}
	h.Usage.CPUHeld = false
	*h.Usage.CPUPercent = 30
	if got := hs.place(p, 1); len(got) != 1 {
		t.Fatal("recovery did not allow new work")
	}
	h.Cordoned = true
	if got := hs.place(p, 1); len(got) != 0 {
		t.Fatal("recovery undid manual cordon")
	}
}

func TestBusyCPUAllowsOnlyOneStartUntilItRegisters(t *testing.T) {
	p := limited("build", 1, 1024)
	h := withUsage(sized("host_a", 8, 16, 32768, 100000), 90, 28000)
	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
