func TestProvisioningControlsAndLimits(t *testing.T) {
	p := testPool("linux", "linux")
	j := queued("job", time.Second, "linux")
	snap := Snapshot{Now: now, Pools: []*store.Pool{p}, Hosts: []*store.Host{testHost("host_a", 10, 0)}, Jobs: []*store.Job{j}, Policy: testPolicy()}
	snap.Policy.ScaleUpDelay = time.Minute
	createsFor := func() int {
		n := 0
		for _, p := range Decide(snap).Pools {
			n += creates(p.Actions)
		}
		return n
	}
	if n := createsFor(); n != 0 {
		t.Fatalf("delay bypassed: %d", n)
	}
	j.ProvisionNow = true
	if n := createsFor(); n != 1 {
		t.Fatalf("run now did not bypass delay: %d", n)
	}
	for _, state := range []string{"paused", "deleted"} {
		j.Provisioning = state
		if n := createsFor(); n != 0 {
			t.Fatalf("%s created %d", state, n)
		}
	}
	j.Provisioning = ""
	p.MaxRunners = 0
	if n := createsFor(); n != 0 {
		t.Fatalf("run now bypassed pool maximum: %d", n)
	}
	p.MaxRunners = 10
	snap.Hosts[0].Capacity = 0
	if n := createsFor(); n != 0 {
		t.Fatalf("run now bypassed host capacity: %d", n)
	}
}

func TestProvisioningFairnessAcrossPassesAndPriority(t *testing.T) {
	a, b := testPool("a", "a"), testPool("b", "b")
	ja, jb := queued("a", time.Minute, "a"), queued("b", time.Minute, "b")
	snap := Snapshot{Now: now, Pools: []*store.Pool{b, a}, Jobs: []*store.Job{jb, ja}, Hosts: []*store.Host{testHost("host_a", 10, 0)}, Policy: testPolicy(), LastProvisioned: map[string]time.Time{a.ID: ago(time.Second), b.ID: ago(time.Minute)}}
	snap.Policy.MaxCreatesPerTick = 1
	winner := func() string {
		for _, p := range Decide(snap).Pools {
			if creates(p.Actions) > 0 {
				return p.PoolID
			}
		}
		return ""
	}
	if got := winner(); got != b.ID {
		t.Fatalf("least recently served pool: %s", got)
	}
	snap.LastProvisioned[b.ID] = now
	if got := winner(); got != a.ID {
		t.Fatalf("next pass did not rotate: %s", got)
	}
	jb.ProvisionNow = true
	if got := winner(); got != b.ID {
		t.Fatalf("run now not prioritised: %s", got)
	}
	a.Priority = 10
	if got := winner(); got != a.ID {
		t.Fatalf("run now bypassed pool priority: %s", got)
	}
}

func TestProvisioningOrderingIsStable(t *testing.T) {
	a, b, c := queued("a", time.Minute), queued("b", time.Minute), queued("c", time.Second)
	c.ProvisionNow = true
	got := sortedJobs([]*store.Job{b, c, a})
	if got[0] != c || got[1] != a || got[2] != b {
		t.Fatalf("ordering: %+v", got)
	}
}

func TestExecutionOrderPreservesFairAllocation(t *testing.T) {
	a, b := testPool("a", "a"), testPool("b", "b")
	a.MinRunners, b.MinRunners = 2, 2
	snap := Snapshot{Now: now, Pools: []*store.Pool{a, b}, Hosts: []*store.Host{testHost("host", 10, 0)}, Policy: testPolicy(), LastProvisioned: map[string]time.Time{a.ID: now}}
	snap.Policy.MaxCreatesPerTick = 4
	plan := Decide(snap)
	want := []string{b.ID, a.ID, b.ID, a.ID}
	if len(plan.Actions) != len(want) {
		t.Fatalf("actions: %+v", plan.Actions)
	}
	for i, a := range plan.Actions {
		if a.PoolID != want[i] {
			t.Fatalf("action %d: %s, want %s", i, a.PoolID, want[i])
		}
	}
	if plan.Pools[0].PoolID != a.ID {
		t.Fatal("display order changed")
	}
	a.Priority = 10
	plan = Decide(snap)
	if plan.Actions[0].PoolID != a.ID || plan.Actions[1].PoolID != a.ID {
		t.Fatal("execution lost priority tiers")
	}
}

// The order pools are served in has to be a total order, or which pool gets
// the one create a tight budget allows depends on how the caller happened to
// collect them rather than on who has waited. Here a pool with nothing queued
// but a minimum to keep warm sits between two with jobs: it beats the first on
// ID, loses to the second on ID, and the second beats the first on wait -- a
// cycle, so the winner was whichever pool the sort left in front. Every
// arrangement of the names, which is what sets the input order, must serve the
// pool whose job has waited longest.
func TestTheOldestWaitingPoolIsServedFirstWhateverOrderThePoolsArriveIn(t *testing.T) {
	names := []string{"n1", "n2", "n3"}
	for _, perm := range [][3]int{{0, 1, 2}, {0, 2, 1}, {1, 0, 2}, {1, 2, 0}, {2, 0, 1}, {2, 1, 0}} {
		t.Run(strings.Join([]string{names[perm[0]], names[perm[1]], names[perm[2]]}, "-"), func(t *testing.T) {
			recent := testPool(names[perm[0]], "recent")
			recent.ID = "pool_1"
			warm := testPool(names[perm[1]], "warm")
			warm.ID = "pool_2"
			warm.MinRunners = 1
			oldest := testPool(names[perm[2]], "oldest")
			oldest.ID = "pool_3"

			s := snap([]*store.Pool{recent, warm, oldest}, nil, []*store.Job{
				queued("j_recent", time.Minute, "recent"),
				queued("j_oldest", 10*time.Minute, "oldest"),
			}, []*store.Host{testHost("host_a", 10, 0)})
			s.Policy.MaxCreatesPerTick = 1

			var served []string
			for _, p := range Decide(s).Pools {
				if creates(p.Actions) > 0 {
					served = append(served, p.PoolID)
				}
			}
			if !slices.Equal(served, []string{"pool_3"}) {
				t.Fatalf("served %v, want only the pool whose job has waited longest (pool_3)", served)
			}
		})
	}
}

package scheduler

import (
	"go/ast"
	"go/build"
	"go/parser"
	"go/token"
	"os"
	"slices"
	"strings"
	"testing"
)

// AGENTS.md calls this package pure: Decide takes a snapshot and returns a Plan,
// with no clock read, no database and no network, and that is what makes scaling
// behaviour testable and every decision's reason string the one the decision
// actually had. internal/updates has a test that holds it to the same rule; this
// package, whose reasons operators read most, had only the promise.
//
// It may use the standard library's pure parts, and the two internal packages
// whose types it is written in terms of: the store's domain model (a Runner, a
// Host, a Pool, not the database behind them) and the naming grammar.
var allowedInternal = map[string]string{
	"github.com/eyupio/zoomies/internal/store":  "its domain types; the database behind them is the store's and is never opened here",
	"github.com/eyupio/zoomies/internal/naming": "the grammar for pool, host and runner names, which is pure",
}

// The standard library is not all pure: these reach the network, the disk, a
// process, a database or a source of chance, each of which would let a decision
// depend on something other than the snapshot it was handed. A package listed
// here stands for itself and everything beneath it.
var impurePackages = []string{"net", "os", "database/sql", "math/rand", "crypto/rand", "syscall"}

func TestTheSchedulerImportsNothingThatReachesOutsideTheSnapshot(t *testing.T) {
	pkg, err := build.ImportDir(".", 0)
	if err != nil {
		t.Fatalf("reading this package: %v", err)
	}
	if len(pkg.Imports) == 0 {
		t.Fatal("no imports were found at all; the walk is wrong, not the package")
	}
	for _, problem := range impureImports(pkg.Imports) {
		t.Error(problem)
	}
}

func impureImports(imports []string) []string {
	var problems []string
	for _, path := range imports {
		first, _, _ := strings.Cut(path, "/")
		if strings.Contains(first, ".") {
			if _, ok := allowedInternal[path]; !ok {
				problems = append(problems, "internal/scheduler imports "+path+"; it may import only the standard library's pure parts and "+
					strings.Join(sortedKeys(allowedInternal), ", ")+", and what needs anything else belongs to the controller that calls Decide")
			}
			continue
		}
		for _, banned := range impurePackages {
			if path == banned || strings.HasPrefix(path, banned+"/") {
				problems = append(problems, "internal/scheduler imports "+path+", which reaches outside its snapshot; the network, the disk, a process, a database and a random source belong to the caller")
			}
		}
	}
	return problems
}

func sortedKeys(m map[string]string) []string {
	var out []string
	for k := range m {
		out = append(out, k)
	}
	slices.Sort(out)
	return out
}

// The denylist is only worth having if it would catch what it names.
func TestThePurityCheckRefusesWhatReachesOutsideTheSnapshot(t *testing.T) {
	for _, path := range []string{
		"net", "net/http", "os", "os/exec", "database/sql", "math/rand", "math/rand/v2", "crypto/rand", "syscall",
		"github.com/eyupio/zoomies/internal/controller",
		"github.com/eyupio/zoomies/internal/config",
		"github.com/eyupio/zoomies/internal/github",
	} {
		if got := impureImports([]string{path}); len(got) != 1 {
			t.Errorf("importing %s raised %d complaints, want 1", path, len(got))
		}
	}
	for _, path := range []string{
		"fmt", "sort", "strings", "time", "slices", "cmp", "math", "strconv", "unicode",
		"github.com/eyupio/zoomies/internal/store",
		"github.com/eyupio/zoomies/internal/naming",
	} {
		if got := impureImports([]string{path}); len(got) != 0 {
			t.Errorf("importing %s was refused: %v", path, got)
		}
	}
}

// A decision's reason string is built from the snapshot's own instant, so the
// sentence an operator reads and the decision it explains cannot be a
// millisecond apart. A read of the clock inside the package is what would let
// them differ, so the instant arrives as an argument and nothing here asks for it.
func TestTheSchedulerNeverReadsTheClock(t *testing.T) {
	entries, err := os.ReadDir(".")
	if err != nil {
		t.Fatalf("reading this package: %v", err)
	}
	files := 0
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
			continue
		}
		files++
		fset := token.NewFileSet()
		file, err := parser.ParseFile(fset, name, nil, parser.SkipObjectResolution)
		if err != nil {
			t.Fatalf("parsing %s: %v", name, err)
		}
		ast.Inspect(file, func(n ast.Node) bool {
			sel, ok := n.(*ast.SelectorExpr)
			if !ok {
				return true
			}
			if pkg, ok := sel.X.(*ast.Ident); ok && pkg.Name == "time" {
				switch sel.Sel.Name {
				case "Now", "Since", "Until", "After", "Sleep", "NewTimer", "NewTicker", "Tick", "AfterFunc":
					t.Errorf("%s: time.%s reads the clock; pass the instant in", fset.Position(sel.Pos()), sel.Sel.Name)
				}
			}
			return true
		})
	}
	if files == 0 {
		t.Fatal("no source files were scanned at all; the walk is wrong, not the rule")
	}
}

