	if err != nil {
		t.Fatal(err)
	}
	if len(ids) != MaxEliRepairSelection || total != MaxEliRepairSelection+5 {
		t.Fatalf("got %d ids and a total of %d, want %d and %d", len(ids), total, MaxEliRepairSelection, MaxEliRepairSelection+5)
