		t.Fatal(err)
	}
	var n int
	if err := s.read.QueryRowContext(ctx, `SELECT COUNT(*) FROM host_check_acceptances`).Scan(&n); err != nil || n != 0 {
		t.Fatalf("%d acceptances survived their host (%v)", n, err)
