		t.Fatalf("a new host follows the fleet and has never been moved: %+v %v", got, err)
	}
	moved := time.Now().UTC().Truncate(time.Millisecond)
	if err := s.MarkHostAutoAdjusted(ctx, h.ID, moved); err != nil {
		t.Fatal(err)
