package store

import (
	"context"
	"time"
)

var pendingHostCleanupQuery = hot(`SELECT ` + runnerCols + ` FROM runners
	WHERE id > ? AND state IN ('removed', 'failed') AND host_removed_at IS NULL
	AND (host_cleanup_error != '' OR EXISTS
		(SELECT 1 FROM jobs WHERE jobs.runner_id=runners.id AND jobs.state='completed')
		OR COALESCE(finished_at, created_at) < ?)
	AND NOT EXISTS (SELECT 1 FROM jobs WHERE jobs.runner_id=runners.id AND jobs.state='in_progress')
	ORDER BY id LIMIT ?`)

// PendingHostCleanup recovers removal intent from completed jobs, failed host
// removals, and finished runners nobody has confirmed gone since before
// unconfirmedBefore. A keyset cursor prevents offline hosts starving later rows.
//
// The last of the three is the one a lost report leaves behind. A runner
// withdrawn while idle ran no job, so its row carried nothing that said the
// host still owed a confirmation, and the agent's one report of the removal
// (sent after it has kept the container for its logs) was the only thing
// that could ever stamp it. A restart on either side in that window left the
// row waiting for ever, with no error to show and nothing left on the host.
// Asking again is safe: a removal the host already did is answered as done.
// The grace is the caller's, and outlasts the agent's own removal window so
// that a container kept for its logs is not taken early.
func (s *Store) PendingHostCleanup(ctx context.Context, afterID string, limit int, unconfirmedBefore time.Time) ([]*Runner, error) {
	rows, err := s.hotRead().Query(ctx, pendingHostCleanupQuery, afterID, ms(unconfirmedBefore), min(max(limit, 1), 200))
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*Runner
	for rows.Next() {
		r, err := scanRunner(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, r)
	}
	return out, rows.Err()
}

package store

import (
	"context"
	"testing"
	"time"
)

// A runner withdrawn while idle ran no job, so nothing on its row said the
// host still owed a confirmation that it was gone: only runners with a
// finished job or a recorded failure were ever asked about again. Lose the
// agent's one removal report (a restart on either side) and the row waited
// for ever, which is what held an instance transfer at "awaiting cleanup"
// with nothing left on any host. After a grace that outlasts the agent's own
// removal window the host is asked again; a removal it already did is
// answered as done.
func TestAStoppedRunnerNobodyConfirmedGoneIsAskedAboutAgainAfterAGrace(t *testing.T) {
	now := time.Date(2026, 10, 10, 18, 0, 0, 0, time.UTC)
	s := newTestStoreAt(t, func() time.Time { return now })
	ctx := context.Background()
	_, pool, host := seedPool(t, s)
	r := &Runner{PoolID: pool.ID, HostID: host.ID, Name: "pool-a-aaaaaaaa", State: RunnerIdle}
	if err := s.CreateRunner(ctx, r); err != nil {
		t.Fatal(err)
	}
	if _, err := s.TransitionRunner(ctx, r.ID, RunnerRemoved, "withdrawn while idle"); err != nil {
		t.Fatal(err)
	}

	// Inside the grace the agent may still be keeping the container for its
	// logs, and asking would cut that short.
	pending, err := s.PendingHostCleanup(ctx, "", 10, now.Add(-15*time.Minute))
	if err != nil {
		t.Fatal(err)
	}
	if len(pending) != 0 {
		t.Fatalf("asked about a runner still inside the grace: %+v", pending)
	}

	now = now.Add(16 * time.Minute)
	pending, err = s.PendingHostCleanup(ctx, "", 10, now.Add(-15*time.Minute))
	if err != nil {
		t.Fatal(err)
	}
	if len(pending) != 1 || pending[0].ID != r.ID {
		t.Fatalf("a runner nobody confirmed gone was not asked about: %+v", pending)
	}

	// Once the host has said so, there is nothing to ask.
	if _, err := s.ConfirmRunnerCleanup(ctx, r.ID, true); err != nil {
		t.Fatal(err)
	}
	pending, err = s.PendingHostCleanup(ctx, "", 10, now.Add(-15*time.Minute))
	if err != nil {
		t.Fatal(err)
	}
	if len(pending) != 0 {
		t.Fatalf("a confirmed removal was asked about again: %+v", pending)
	}
}

// A runner whose job is still in progress is not asked about, whatever its
// age: the controller's row may be behind the host's.
func TestARunnerWhoseJobIsStillRunningIsNotAskedAboutHoweverOldItIs(t *testing.T) {
	now := time.Date(2026, 10, 10, 18, 0, 0, 0, time.UTC)
	s := newTestStoreAt(t, func() time.Time { return now })
	ctx := context.Background()
	_, pool, host := seedPool(t, s)
	r := &Runner{PoolID: pool.ID, HostID: host.ID, Name: "pool-a-aaaaaaaa", State: RunnerBusy}
	if err := s.CreateRunner(ctx, r); err != nil {
		t.Fatal(err)
	}
	if _, err := s.UpsertJob(ctx, &Job{GitHubJobID: 1, Repo: "acme/widgets", JobName: "build", State: JobInProgress, RunnerID: r.ID, RunnerName: r.Name}); err != nil {
		t.Fatal(err)
	}
	if _, err := s.TransitionRunner(ctx, r.ID, RunnerFailed, "lost"); err != nil {
		t.Fatal(err)
	}
	pending, err := s.PendingHostCleanup(ctx, "", 10, now.Add(time.Hour))
	if err != nil {
		t.Fatal(err)
	}
	if len(pending) != 0 {
		t.Fatalf("a runner with a job still running was asked about: %+v", pending)
	}
}

package store

import (
	"context"
	"database/sql/driver"
	"encoding/json"
	"fmt"
	"github.com/eyupio/zoomies/internal/hosttune"
	"time"
)

type HostDoctor struct{ *hosttune.Report }

func (h HostDoctor) Value() (driver.Value, error) {
	if h.Report == nil {
		return "{}", nil
	}
	return marshalJSON(h.Report)
}
func (h *HostDoctor) Scan(value any) error {
	h.Report = nil
	var b []byte
	switch v := value.(type) {
	case string:
		b = []byte(v)
	case []byte:
		b = v
	case nil:
		return nil
	default:
		return fmt.Errorf("doctor: unexpected database value %T", value)
	}
	if string(b) == "{}" || string(b) == "null" || len(b) == 0 {
		return nil
	}
	var r hosttune.Report
	if err := json.Unmarshal(b, &r); err != nil {
		return err
	}
	h.Report = &r
	return nil
}
func (s *Store) SetHostDoctor(ctx context.Context, id string, r *hosttune.Report) error {
	var at int64
	if r != nil {
		at = ms(r.CheckedAt)
	}
	_, err := s.exec(ctx, `UPDATE hosts SET doctor=?, doctor_checked_at=? WHERE id=?`, HostDoctor{r}, at, id)
	return wrapWrite(err)
}

// SetHostDoctorChecked records that a host's agent looked at `at`, without
// touching the stored body or last_heartbeat. A task result is not a heartbeat
// and must not make a wedged heartbeat loop look alive. MAX stops a result that
// overtook a newer report moving freshness backwards.
func (s *Store) SetHostDoctorChecked(ctx context.Context, id string, at time.Time) error {
	res, err := s.exec(ctx, `UPDATE hosts SET doctor_checked_at=MAX(doctor_checked_at, ?) WHERE id=?`, ms(at), id)
	if err != nil {
		return wrapWrite(err)
	}
	return affected(res, "host", id)
}

