import (
	"context"
	"database/sql"
	"errors"
	"testing"
	"time"
)

// The two halves of the column are written by different paths -- the
// heartbeat and a task result -- and each must leave the other alone, or a
// beat that says the runtime is fine would wipe the image a pool cannot pull.
func TestHostIncidentsRoundTripAndEachHalfLeavesTheOtherAlone(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	_, _, h := seedPool(t, s)

	got, err := s.GetHost(ctx, h.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.Incidents.Runtime != nil || got.Incidents.ImagePull != nil {
		t.Fatalf("a new host has incidents: %+v", got.Incidents)
	}

	at := time.Date(2026, 9, 22, 12, 0, 0, 0, time.UTC)
	rt := &RuntimeIncident{Failures: 3, Kind: "unavailable", Error: "no socket", RetryAt: at.Add(40 * time.Second), Since: at, ObservedAt: at}
	pull := &ImagePullIncident{PoolID: "pool_1", Pool: "linux", Image: "ghcr.io/x/y:1", Registry: "ghcr.io", Source: "start", Since: at, ObservedAt: at}
	if err := s.SetHostRuntimeIncident(ctx, h.ID, rt); err != nil {
		t.Fatal(err)
	}
	if err := s.SetHostImagePullIncident(ctx, h.ID, pull); err != nil {
		t.Fatal(err)
	}
	got, err = s.GetHost(ctx, h.ID)
	if err != nil {
		t.Fatal(err)
	}
	if r := got.Incidents.Runtime; r == nil || r.Failures != 3 || r.Kind != "unavailable" || !r.RetryAt.Equal(rt.RetryAt) || !r.ObservedAt.Equal(at) {
		t.Fatalf("the runtime incident came back as %+v", r)
	}
	if p := got.Incidents.ImagePull; p == nil || p.Registry != "ghcr.io" || p.Pool != "linux" || !p.ObservedAt.Equal(at) {
		t.Fatalf("the image pull incident came back as %+v", p)
	}

	if err := s.SetHostRuntimeIncident(ctx, h.ID, nil); err != nil {
		t.Fatal(err)
	}
	got, _ = s.GetHost(ctx, h.ID)
	if got.Incidents.Runtime != nil || got.Incidents.ImagePull == nil {
		t.Fatalf("clearing the runtime half took the wrong half: %+v", got.Incidents)
	}
	if err := s.SetHostRuntimeIncident(ctx, h.ID, rt); err != nil {
		t.Fatal(err)
	}
	if err := s.SetHostImagePullIncident(ctx, h.ID, nil); err != nil {
		t.Fatal(err)
	}
	got, _ = s.GetHost(ctx, h.ID)
	if got.Incidents.Runtime == nil || got.Incidents.ImagePull != nil {
		t.Fatalf("clearing the image half took the wrong half: %+v", got.Incidents)
	}

	// The general host writes do not carry the column, so an operator's
	// PATCH cannot put back an incident the heartbeat has cleared.
	got.Capacity = 7
	if err := s.UpdateHost(ctx, got); err != nil {
		t.Fatal(err)
	}
	if err := s.SetHostRuntimeIncident(ctx, h.ID, nil); err != nil {
		t.Fatal(err)
	}
	if err := s.UpdateHost(ctx, got); err != nil {
		t.Fatal(err)
	}
	if again, _ := s.GetHost(ctx, h.ID); again.Incidents.Runtime != nil {
		t.Fatal("a whole-row host write put a cleared incident back")
	}

	if err := s.SetHostRuntimeIncident(ctx, "host_missing", rt); !errors.Is(err, ErrNotFound) {
		t.Fatalf("an unknown host gave %v, want ErrNotFound", err)
	}
}

// 0049 adds a nullable column with no default, so every host that existed
// before it reads NULL. That has to read as "nothing has happened here", and
// the first incident written to such a row has to land.
func TestAHostFromBeforeIncidentsWereKeptUpgradesWithNone(t *testing.T) {
	ctx := context.Background()
	path := atSchemaBefore(t, "0049_host_incidents.sql")
	db, err := sql.Open("sqlite", "file:"+path)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := db.ExecContext(ctx, `INSERT INTO hosts (id, name, created_at) VALUES ('host_old', 'old', 1)`); err != nil {
		t.Fatalf("seeding a host at the old schema: %v", err)
	}
	if err := db.Close(); err != nil {
		t.Fatal(err)
	}

	s, err := Open(ctx, Options{Path: path})
	if err != nil {
		t.Fatalf("upgrading: %v", err)
	}
	defer s.Close()
	var raw sql.NullString
	if err := s.read.QueryRowContext(ctx, `SELECT incidents FROM hosts WHERE id='host_old'`).Scan(&raw); err != nil {
		t.Fatal(err)
	}
	if raw.Valid {
		t.Fatalf("the upgrade wrote %q into an existing host; the column is meant to arrive NULL", raw.String)
	}
	h, err := s.GetHost(ctx, "host_old")
	if err != nil {
		t.Fatalf("reading an upgraded host: %v", err)
	}
	if h.Incidents.Runtime != nil || h.Incidents.ImagePull != nil {
		t.Fatalf("an upgraded host has incidents: %+v", h.Incidents)
	}
	at := time.Unix(100, 0).UTC()
	if err := s.SetHostImagePullIncident(ctx, "host_old", &ImagePullIncident{PoolID: "p", Registry: "docker.io", ObservedAt: at}); err != nil {
		t.Fatalf("writing an incident onto a NULL column: %v", err)
	}
	if h, _ := s.GetHost(ctx, "host_old"); h.Incidents.ImagePull == nil || h.Incidents.ImagePull.Registry != "docker.io" {
		t.Fatalf("the incident did not land on the upgraded row: %+v", h.Incidents)
	}
}

package store

import "testing"

func TestHostEditsKeepConcurrentCordonAndReportedFacts(t *testing.T) {
	s := newTestStore(t)
	_, _, host := seedPool(t, s)
	ctx := t.Context()
	if err := s.SetHostCordoned(ctx, host.ID, true); err != nil {
		t.Fatal(err)
	}
	host.CPUs = 16
	if err := s.SetHostReported(ctx, host); err != nil {
		t.Fatal(err)
	}
	capacity, reserve := 2, 1
	labels := StringMap{"rack": "east"}
	if err := s.PatchHost(ctx, host.ID, HostChanges{Labels: &labels, ReserveCPUs: &reserve}); err != nil {
		t.Fatal(err)
	}
	if err := s.PatchHost(ctx, host.ID, HostChanges{Capacity: &capacity}); err != nil {
		t.Fatal(err)
	}
	got, err := s.GetHost(ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	if !got.Cordoned || got.CPUs != 16 || got.Capacity != 2 || got.ReserveCPUs != 1 || got.Labels["rack"] != "east" {
		t.Fatalf("an edit overwrote another change: %+v", got)
	}
	// Zero and an empty map are edits, not omitted values.
	capacity = 0
	labels = StringMap{}
	if err := s.PatchHost(ctx, host.ID, HostChanges{Capacity: &capacity, Labels: &labels}); err != nil {
		t.Fatal(err)
	}
	got, err = s.GetHost(ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.Capacity != 0 || len(got.Labels) != 0 || !got.Cordoned || got.ReserveCPUs != 1 {
		t.Fatalf("explicit zero or empty labels were not applied independently: %+v", got)
	}
}

// The priority is the operator's pin on placement: a patch sets it, another
// clears it back to the spec score, and one that says nothing about it
// changes nothing. A rebuilt machine's re-join keeps the pin, the way it
// keeps its labels: the operator set it on the row, not on the agent.
func TestAPriorityPinIsSetClearedAndQuietlyLeftAlone(t *testing.T) {
	s := newTestStore(t)
	_, _, host := seedPool(t, s)
	ctx := t.Context()

	pin := 90
	if err := s.PatchHost(ctx, host.ID, HostChanges{PriorityOverride: &pin}); err != nil {
		t.Fatal(err)
	}
	got, err := s.GetHost(ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.PriorityOverride == nil || *got.PriorityOverride != 90 {
		t.Fatalf("PriorityOverride = %+v, want 90", got.PriorityOverride)
	}

	if err := s.PatchHost(ctx, host.ID, HostChanges{}); err != nil {
		t.Fatalf("a patch that names nothing: %v", err)
	}
	got, err = s.GetHost(ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.PriorityOverride == nil || *got.PriorityOverride != 90 {
		t.Fatalf("a quiet patch moved the pin: %+v", got.PriorityOverride)
	}

	if err := s.PatchHost(ctx, host.ID, HostChanges{ClearPriorityOverride: true}); err != nil {
		t.Fatal(err)
	}
	got, err = s.GetHost(ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.PriorityOverride != nil {
		t.Fatalf("ClearPriorityOverride left the pin: %+v", got.PriorityOverride)
	}

	// The report never carries the pin: an agent cannot take a place its
	// operator pinned, and GetHostReported has nothing to say here either.
	host.PriorityOverride = nil
	if err := s.SetHostReported(ctx, host); err != nil {
		t.Fatal(err)
	}
	host.PriorityOverride = &pin
	if err := s.SetHostReported(ctx, host); err != nil {
		t.Fatal(err)
	}
	got, err = s.GetHost(ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.PriorityOverride != nil {
		t.Fatalf("a heartbeat wrote the pin: %+v", got.PriorityOverride)
	}
}

func TestHostFeaturesFollowWhatTheAgentReports(t *testing.T) {
	// A feature is the agent's claim about itself, re-read from every
	// heartbeat: an agent rolled back to a release that cannot move a live
	// quota must stop being recorded as one that can, or an elastic pool keeps
	// counting runners there as boostable when they are held at their share.
	s := newTestStore(t)
	_, _, host := seedPool(t, s)
	ctx := t.Context()
	if host.Supports("elastic-cpu") {
		t.Fatal("a host that has claimed nothing supports elastic CPU")
	}
	host.Features = StringSlice{"elastic-cpu"}
	if err := s.SetHostReported(ctx, host); err != nil {
		t.Fatal(err)
	}
	got, err := s.GetHost(ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	if !got.Supports("elastic-cpu") {
		t.Fatalf("features = %v, want the agent's claim kept", got.Features)
	}
	host.Features = nil
	if err := s.SetHostReported(ctx, host); err != nil {
		t.Fatal(err)
	}
	if got, err = s.GetHost(ctx, host.ID); err != nil {
		t.Fatal(err)
	} else if got.Supports("elastic-cpu") {
		t.Fatalf("features = %v, want an empty report to withdraw the claim", got.Features)
	}
}

package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"time"
)

// MarkTransferredHosts discards source liveness, never credentials or history.
func (s *Store) MarkTransferredHosts(ctx context.Context) error {
	return s.tx(ctx, func(tx *sql.Tx) error {
		if _, err := tx.ExecContext(ctx, `INSERT OR IGNORE INTO host_recovery(host_id) SELECT id FROM hosts`); err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, `UPDATE host_recovery SET completed_at=NULL WHERE retired_at IS NULL AND host_id IN (SELECT id FROM hosts)`); err != nil {
			return err
		}
		_, err := tx.ExecContext(ctx, `UPDATE hosts SET last_heartbeat=0`)
		return err
	})
}

// DuplicateAgentWindow is shared with the controller's ownership warning.
const DuplicateAgentWindow = time.Hour

type RecoveryHost struct {
	HostID     string     `json:"host_id"`
	Name       string     `json:"name"`
	State      string     `json:"state"`
	VerifiedAt *time.Time `json:"verified_at,omitempty"`
	RetiredAt  *time.Time `json:"retired_at,omitempty"`
	RetiredBy  string     `json:"retired_by,omitempty"`
}

func (h *Host) RecoveryState(now time.Time) string {
	if h.Retired {
		return "retired"
	}
	if !h.RecoveryRequired {
		return ""
	}
	if h.LastHeartbeat.UnixMilli() > 0 && h.Healthy(now) && !h.Incompatible && h.TokenHash != "" && (h.AgentSessionAltAt == nil || now.Sub(*h.AgentSessionAltAt) >= DuplicateAgentWindow) {
		return "verified"
	}
	return "awaiting_recovery"
}

func (s *Store) RecoveryHosts(ctx context.Context) ([]RecoveryHost, error) {
	rows, err := s.read.QueryContext(ctx, `SELECT host_id, COALESCE(h.name,''), retired_at, retired_by, completed_at FROM host_recovery r LEFT JOIN hosts h ON h.id=r.host_id ORDER BY host_id`)
	if err != nil {
		return nil, err
	}
	out := []RecoveryHost{}
	for rows.Next() {
		var v RecoveryHost
		var retired, completed sql.NullInt64
		if err := rows.Scan(&v.HostID, &v.Name, &retired, &v.RetiredBy, &completed); err != nil {
			rows.Close()
			return nil, err
		}
		v.RetiredAt = atp(retired)
		v.VerifiedAt = atp(completed)
		v.State = "awaiting_recovery"
		if completed.Valid {
			v.State = "verified"
		}
		if retired.Valid {
			v.State = "retired"
		}
		out = append(out, v)
	}
	err = rows.Err()
	rows.Close()
	if err != nil {
		return nil, err
	}
	for i := range out {
		if out[i].State == "retired" || out[i].VerifiedAt != nil {
			continue
		}
		h, err := s.GetHost(ctx, out[i].HostID)
		if err == nil {
			out[i].State = h.RecoveryState(s.Now())
		} else if !errors.Is(err, ErrNotFound) {
			return nil, err
		}
	}
	return out, nil
}

// RetireRecoveryHost changes destination records only. No task is queued and
// no runner cleanup confirmation is fabricated for a machine we cannot see.
func (s *Store) RetireRecoveryHost(ctx context.Context, id, confirm, actor string) error {
	if confirm != id || id == "" {
		return fmt.Errorf("confirm the exact host ID to retire: %w", ErrConflict)
	}
	return s.tx(ctx, func(tx *sql.Tx) error {
		var fenced string
		err := tx.QueryRowContext(ctx, `SELECT value FROM settings WHERE key=?`, SettingRecoveryFenced).Scan(&fenced)
		if err != nil && !errors.Is(err, sql.ErrNoRows) {
			return err
		}
		if err != nil || fenced != "true" {
			return fmt.Errorf("retirement requires the recovery fence: %w", ErrConflict)
		}
		var beat int64
		var retired sql.NullInt64
		err = tx.QueryRowContext(ctx, `SELECT h.last_heartbeat,r.retired_at FROM hosts h LEFT JOIN host_recovery r ON r.host_id=h.id WHERE h.id=?`, id).Scan(&beat, &retired)
		if err == sql.ErrNoRows {
			return ErrNotFound
		}
		if err != nil {
			return err
		}
		var required int
		if err = tx.QueryRowContext(ctx, `SELECT COUNT(*) FROM host_recovery WHERE host_id=? AND completed_at IS NULL`, id).Scan(&required); err != nil {
			return err
		}
		if required != 1 || retired.Valid || s.Now().Sub(at(beat)) < HeartbeatTimeout {
			return fmt.Errorf("only an unreachable carried-over host may be retired: %w", ErrConflict)
		}
		if _, err = tx.ExecContext(ctx, `UPDATE host_recovery SET retired_at=?,retired_by=? WHERE host_id=?`, ms(s.Now()), actor, id); err != nil {
			return err
		}
		_, err = tx.ExecContext(ctx, `UPDATE hosts SET cordoned=1,token_hash='' WHERE id=?`, id)
		return err
	})
}

func (s *Store) CheckHostRecovery(ctx context.Context) error {
	hosts, err := s.RecoveryHosts(ctx)
	if err != nil {
		return err
	}
	for _, h := range hosts {
		if h.State == "awaiting_recovery" {
			return fmt.Errorf("host %s must reconnect and pass checks or be explicitly retired: %w", h.HostID, ErrConflict)
		}
	}
	return nil
}

// ReenrolRecoveryHost keeps historical runner references during cutover.
func (s *Store) ReenrolRecoveryHost(ctx context.Context, h *Host) error {
	if err := s.UpdateHost(ctx, h); err != nil {
		return err
	}
	res, err := s.exec(ctx, `UPDATE hosts SET token_hash=?,features=?,throttle=? WHERE id=? AND NOT EXISTS(SELECT 1 FROM host_recovery WHERE host_id=hosts.id AND retired_at IS NOT NULL)`, h.TokenHash, h.Features, h.Throttle, h.ID)
	if err != nil {
		return err
	}
	return affected(res, "host", h.ID)
}

// CompleteRecovery checks and lifts in one writer transaction: a concurrent
// heartbeat reporting incompatible or duplicate agents cannot slip between
// validation and the write that permits the controller to act.
func (s *Store) CompleteRecovery(ctx context.Context) error {
	return s.tx(ctx, func(tx *sql.Tx) error {
		rows, err := tx.QueryContext(ctx, `SELECT r.host_id,r.retired_at,h.last_heartbeat,h.incompatible,h.token_hash,h.agent_session_alt_at FROM host_recovery r LEFT JOIN hosts h ON h.id=r.host_id WHERE r.completed_at IS NULL`)
		if err != nil {
			return err
		}
		now := s.Now()
		for rows.Next() {
			var id string
			var retired, beat, incompatible, alternated sql.NullInt64
			var token sql.NullString
			if err := rows.Scan(&id, &retired, &beat, &incompatible, &token, &alternated); err != nil {
				rows.Close()
				return err
			}
			if retired.Valid {
				continue
			}
			h := Host{ID: id, RecoveryRequired: true, LastHeartbeat: at(beat.Int64), Incompatible: incompatible.Int64 != 0, TokenHash: token.String, AgentSessionAltAt: atp(alternated)}
			if !beat.Valid || h.RecoveryState(now) != "verified" {
				rows.Close()
				return fmt.Errorf("host %s must reconnect and pass checks or be explicitly retired: %w", id, ErrConflict)
			}
		}
		err = rows.Err()
		rows.Close()
		if err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, `UPDATE host_recovery SET completed_at=? WHERE retired_at IS NULL AND completed_at IS NULL`, ms(now)); err != nil {
			return err
		}
		_, err = tx.ExecContext(ctx, `DELETE FROM settings WHERE key IN (?,?,?)`, SettingRecoveryFenced, SettingRecoveryFencedReason, SettingTransferDraining)
		return err
	})
}

package store

import (
	"context"
	"errors"
	"reflect"
	"testing"
	"time"
)

func TestCarriedOverHostsNeedFreshChecksOrExplicitRetirement(t *testing.T) {
	ctx := context.Background()
	now := time.Date(2026, 10, 13, 12, 0, 0, 0, time.UTC)
	s := newTestStoreAt(t, func() time.Time { return now })
	offline := &Host{Name: "offline", TokenHash: "old-token", Capacity: 4}
	online := &Host{Name: "online", TokenHash: "online-token", Capacity: 4}
	for _, h := range []*Host{offline, online} {
		if err := s.CreateHost(ctx, h); err != nil {
			t.Fatal(err)
		}
	}
	if err := s.MarkTransferredHosts(ctx); err != nil {
		t.Fatal(err)
	}
	if err := s.CheckHostRecovery(ctx); !errors.Is(err, ErrConflict) {
		t.Fatalf("unresolved recovery: %v", err)
	}
	if err := s.RetireRecoveryHost(ctx, offline.ID, offline.ID, "actor"); !errors.Is(err, ErrConflict) {
		t.Fatalf("unfenced retirement: %v", err)
	}
	if err := s.SetRecoveryFence(ctx, true, "transfer"); err != nil {
		t.Fatal(err)
	}
	for _, tc := range []struct {
		id, confirm string
		want        error
	}{
		{offline.ID, "", ErrConflict}, {offline.ID, online.ID, ErrConflict}, {"missing", "missing", ErrNotFound},
	} {
		if err := s.RetireRecoveryHost(ctx, tc.id, tc.confirm, "actor"); !errors.Is(err, tc.want) {
			t.Fatalf("retire %+v: %v", tc, err)
		}
	}
	if err := s.Heartbeat(ctx, online.ID, now); err != nil {
		t.Fatal(err)
	}
	if err := s.SetHostProtocol(ctx, online.ID, 1, true); err != nil {
		t.Fatal(err)
	}
	if err := s.CheckHostRecovery(ctx); !errors.Is(err, ErrConflict) {
		t.Fatalf("incompatible host: %v", err)
	}
	if err := s.RetireRecoveryHost(ctx, online.ID, online.ID, "actor"); !errors.Is(err, ErrConflict) {
		t.Fatalf("online retirement: %v", err)
	}
	if err := s.RetireRecoveryHost(ctx, offline.ID, offline.ID, "actor"); err != nil {
		t.Fatal(err)
	}
	if err := s.RetireRecoveryHost(ctx, offline.ID, offline.ID, "actor"); !errors.Is(err, ErrConflict) {
		t.Fatalf("repeated retirement: %v", err)
	}
	retired, err := s.GetHost(ctx, offline.ID)
	if err != nil {
		t.Fatal(err)
	}
	if n, err := s.CountHosts(ctx); err != nil || n != 1 {
		t.Fatalf("retired host consumed enrolment limit: %d %v", n, err)
	}
	if retired.Free() != 0 {
		t.Fatal("retired host advertises free capacity")
	}
	if !retired.Retired || retired.Healthy(now) || retired.Available(now) || retired.TokenHash != "" {
		t.Fatalf("retired host can work: %+v", retired)
	}
	if _, err := s.FindHostByTokenHash(ctx, "old-token"); !errors.Is(err, ErrNotFound) {
		t.Fatalf("retired credential accepted: %v", err)
	}
	if err := s.SetHostCordoned(ctx, offline.ID, false); err != nil {
		t.Fatal(err)
	}
	if err := s.Heartbeat(ctx, offline.ID, now); err != nil {
		t.Fatal(err)
	}
	retired, _ = s.GetHost(ctx, offline.ID)
	if retired.Healthy(now) || retired.Available(now) {
		t.Fatal("heartbeat or uncordon revived retirement")
	}
	if err := s.SetHostProtocol(ctx, online.ID, 1, false); err != nil {
		t.Fatal(err)
	}
	if err := s.CheckHostRecovery(ctx); err != nil {
		t.Fatal(err)
	}
	hosts, err := s.RecoveryHosts(ctx)
	if err != nil {
		t.Fatal(err)
	}
	for _, h := range hosts {
		if h.HostID == offline.ID && (h.State != "retired" || h.RetiredBy != "actor" || h.RetiredAt == nil) {
			t.Fatalf("retirement lost attribution: %+v", h)
		}
	}
	now = now.Add(HeartbeatTimeout)
	if err := s.CheckHostRecovery(ctx); !errors.Is(err, ErrConflict) {
		t.Fatalf("stale verification: %v", err)
	}
	fresh := &Host{Name: "not-imported"}
	if err := s.CreateHost(ctx, fresh); err != nil {
		t.Fatal(err)
	}
	now = now.Add(HeartbeatTimeout)
	if err := s.RetireRecoveryHost(ctx, fresh.ID, fresh.ID, "actor"); !errors.Is(err, ErrConflict) {
		t.Fatalf("new host retired: %v", err)
	}
}

func TestRetirementPreservesUsageSessionsAndAuditReferences(t *testing.T) {
	ctx := context.Background()
	now := time.Date(2026, 9, 10, 12, 0, 0, 0, time.UTC)
	s := newTestStoreAt(t, func() time.Time { return now })
	_, pool, host := seedPool(t, s)
	pricedPool(t, s, pool, 0.36)
	runner := confirmed(t, s, &now, pool, host, "historical", now.Add(-2*time.Hour), now.Add(-time.Hour))
	if _, err := s.RollUpUsage(ctx, now.Add(48*time.Hour)); err != nil {
		t.Fatal(err)
	}
	if err := s.AppendAudit(ctx, &AuditEvent{ActorID: "historical-actor", Action: "host.join", TargetKind: "host", TargetID: host.ID}); err != nil {
		t.Fatal(err)
	}
	beforeDays := usageDays(t, s)
	beforeSessions := sessionsFor(t, s, runner.ID)
	if len(beforeDays) == 0 || len(beforeSessions) == 0 {
		t.Fatal("test has no historical usage")
	}
	if err := s.MarkTransferredHosts(ctx); err != nil {
		t.Fatal(err)
	}
	if err := s.SetRecoveryFence(ctx, true, "transfer"); err != nil {
		t.Fatal(err)
	}
	if err := s.RetireRecoveryHost(ctx, host.ID, host.ID, "retiring-actor"); err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(beforeDays, usageDays(t, s)) || !reflect.DeepEqual(beforeSessions, sessionsFor(t, s, runner.ID)) {
		t.Fatal("retirement rewrote usage or sessions")
	}
	if _, err := s.GetRunner(ctx, runner.ID); err != nil {
		t.Fatal("retirement removed historical runner", err)
	}
	audits, _, err := s.ListAudit(ctx, AuditFilter{Actions: []string{"host.join"}}, Page{Limit: 10})
	if err != nil || len(audits) != 1 || audits[0].TargetID != host.ID {
		t.Fatalf("historical audit lost: %+v %v", audits, err)
	}
	if _, err := s.DeleteHost(ctx, host.ID); !errors.Is(err, ErrConflict) {
		t.Fatalf("retired history was deletable: %v", err)
	}
	if err := s.MarkTransferredHosts(ctx); err != nil {
		t.Fatal(err)
	}
	after, err := s.GetHost(ctx, host.ID)
	if err != nil || !after.Retired {
		t.Fatalf("another import revived retirement: %+v %v", after, err)
	}
}

func TestCompletedRecoveryRestoresNormalHostLifecycleWithoutRevivingRetirement(t *testing.T) {
	ctx := context.Background()
	now := time.Date(2026, 10, 13, 12, 0, 0, 0, time.UTC)
	s := newTestStoreAt(t, func() time.Time { return now })
	_, _, host := seedPool(t, s)
	host.TokenHash = "owned"
	if err := s.ReenrolRecoveryHost(ctx, host); err != nil {
		t.Fatal(err)
	}
	if err := s.MarkTransferredHosts(ctx); err != nil {
		t.Fatal(err)
	}
	if err := s.SetRecoveryFence(ctx, true, "transfer"); err != nil {
		t.Fatal(err)
	}
	if err := s.CompleteRecovery(ctx); !errors.Is(err, ErrConflict) {
		t.Fatalf("unresolved transaction lifted fence: %v", err)
	}
	if f, err := s.RecoveryFenced(ctx); err != nil || !f.Fenced {
		t.Fatalf("failure changed fence: %+v %v", f, err)
	}
	if err := s.Heartbeat(ctx, host.ID, now); err != nil {
		t.Fatal(err)
	}
	if err := s.CompleteRecovery(ctx); err != nil {
		t.Fatal(err)
	}
	after, err := s.GetHost(ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	if after.RecoveryRequired {
		t.Fatal("verified host permanently stuck in cutover lifecycle")
	}
	entries, err := s.RecoveryHosts(ctx)
	if err != nil || len(entries) != 1 || entries[0].State != "verified" || entries[0].VerifiedAt == nil {
		t.Fatalf("completion evidence missing: %+v %v", entries, err)
	}
	now = now.Add(HeartbeatTimeout)
	if err := s.SetRecoveryFence(ctx, true, "ordinary restore"); err != nil {
		t.Fatal(err)
	}
	if err := s.RetireRecoveryHost(ctx, host.ID, host.ID, "actor"); !errors.Is(err, ErrConflict) {
		t.Fatalf("completed cutover host eligible for retirement: %v", err)
	}
	if _, err := s.DeleteHost(ctx, host.ID); err != nil {
		t.Fatal("normal verified host lifecycle blocked", err)
	}
	if err := s.CompleteRecovery(ctx); err != nil {
		t.Fatal("completed host deletion reopened cutover obligation", err)
	}
}

package store

import (
	"context"
	"database/sql"
	"database/sql/driver"
	"errors"
	"fmt"
	"time"
)

// HostThrottle is how far the controller has stepped a host down after its
// measurements said it was overwhelmed, and why.
//
// It is a ladder rather than a switch. The pressure holds refuse every new
// start while CPU or memory is acutely short, and release the moment a sample
// says otherwise; a host that is overwhelmed on and off for an hour spends that
// hour bouncing in and out of them, taking a fresh runner each time it is let
// back in. The throttle is what outlasts a sample: each rung takes a quarter
// of the host's slots and, down to half, a quarter of every runner's CPU
// quota; it climbs while the pressure keeps coming back, and it comes down one
// rung at a time after a stretch of calm long enough to mean something.
//
// The controller owns every field. A heartbeat carries the measurements the
// decision is made from and never the decision, so a host cannot talk its way
// off its own rung.
type HostThrottle struct {
	// Level is the rung, 0 for none up to MaxThrottleLevel.
	Level int `json:"level,omitempty"`
	// Since is when this episode started: the first step up from zero.
	Since *time.Time `json:"since,omitempty"`
	// ChangedAt is the last step in either direction, which is what the next
	// step up is paced from.
	ChangedAt *time.Time `json:"changed_at,omitempty"`
	// CalmSince is the start of the calm streak the next step down waits on,
	// nil while the host is not calm.
	CalmSince *time.Time `json:"calm_since,omitempty"`
	// Reason is the sentence for the last step up: which measurement did it.
	Reason string `json:"reason,omitempty"`
}

// MaxThrottleLevel is the top rung. Three rungs leave a host a quarter of its
// slots; a fourth would take it to nothing, and a host taking nothing is a
// cordon, which is the operator's to apply and the operator's to see.
const MaxThrottleLevel = 3

// throttleStepFraction is what one rung takes of the slots, and of every
// runner's CPU quota down to MinCPUFactor.
const throttleStepFraction = 0.25

// Active reports whether the host is on any rung at all.
func (t HostThrottle) Active() bool { return t.Level > 0 }

// Factor is the share of a host's slots the current rung leaves: 1 on no
// rung, then 0.75, 0.5 and 0.25.
func (t HostThrottle) Factor() float64 {
	level := min(max(t.Level, 0), MaxThrottleLevel)
	return 1 - throttleStepFraction*float64(level)
}

// MinCPUFactor is the least share of its CPU quota a running job is ever left
// with. Half speed doubles a job's time, which the timeout-minutes most
// workflows set survives; a quarter turns "slow" into "timed out", and a
// throttle that made jobs fail would be doing the thing it exists to prevent.
// The top rung therefore takes slots and nothing else.
const MinCPUFactor = 0.5

// CPUFactor is the share of its CPU quota each runner on the host is left:
// the rung's factor, floored at MinCPUFactor.
func (t HostThrottle) CPUFactor() float64 {
	return max(MinCPUFactor, t.Factor())
}

func (t HostThrottle) Value() (driver.Value, error) { return marshalJSON(t) }

func (t *HostThrottle) Scan(value any) error {
	*t = HostThrottle{}
	switch v := value.(type) {
	case string:
		return unmarshalJSON(v, t)
	case []byte:
		return unmarshalJSON(string(v), t)
	case nil:
		return nil
	default:
		return fmt.Errorf("host throttle: unexpected database value %T", value)
	}
}

// ErrThrottleMoved is returned by SetHostThrottle when the host is no longer
// on the rung the caller decided from: another decider -- the heartbeat, the
// housekeeping pass, or an operator's clear -- wrote first.
var ErrThrottleMoved = errors.New("the host's throttle was decided elsewhere first")

// SetHostThrottle records the controller's decision for one host, provided
// the host is still on the rung the decision was made from.
//
// Its own statement, like the reserve and the usage: the path a heartbeat's
// facts take through UpdateHost and SetHostReported cannot reach this column,
// and an operator's PATCH cannot either. The throttle is decided from what a
// host measured, never written by what a host said.
//
// The write is conditional on fromLevel because two things decide a throttle
// -- every heartbeat, and the housekeeping tick -- and an operator can clear
// one between a read and the write that follows it. A step recorded twice
// would be two audit rows for one decision, and a stale rung written back
// over an operator's clear would be a lift silently undone; a caller that
// finds the rung moved leaves the decision to whoever moved it.
func (s *Store) SetHostThrottle(ctx context.Context, id string, throttle HostThrottle, fromLevel int) error {
	res, err := s.exec(ctx, `UPDATE hosts SET throttle=? WHERE id=? AND COALESCE(json_extract(throttle, '$.level'), 0)=?`,
		throttle, id, fromLevel)
	if err != nil {
		return wrapWrite(err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return err
	}
	if n > 0 {
		return nil
	}
	var exists int
	if err := s.read.QueryRowContext(ctx, `SELECT 1 FROM hosts WHERE id=?`, id).Scan(&exists); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return ErrNotFound
		}
		return err
	}
	return ErrThrottleMoved
}

package store

import (
	"context"
	"errors"
	"testing"
	"time"
)

// A throttled host takes fewer runners, and the number it takes is what every
// slot count on it has to be measured against: the scheduler's free-slot rule
// and the Hosts page's "n of m slots" both read it, and a page that promised
// slots the pass then refused would be worse than a page saying nothing.
func TestAThrottleTakesAQuarterOfTheSlotsPerRungAndNeverTheLastOne(t *testing.T) {
	cases := []struct {
		capacity, level, want int
	}{
		{4, 0, 4}, {4, 1, 3}, {4, 2, 2}, {4, 3, 1},
		// A small host reaches its floor early: a throttle is not a cordon,
		// and a host with one slot left is still a host in the fleet.
		{2, 1, 1}, {2, 3, 1}, {1, 3, 1},
		{16, 1, 12}, {16, 2, 8}, {16, 3, 4},
		// A capacity of zero is the operator's "take nothing", and the
		// throttle has nothing to add to it.
		{0, 2, 0},
		// A level past the top rung is treated as the top rung.
		{8, 9, 2},
	}
	for _, tc := range cases {
		h := Host{Capacity: tc.capacity, Throttle: HostThrottle{Level: tc.level}}
		if got := h.EffectiveCapacity(); got != tc.want {
			t.Errorf("capacity %d at level %d: effective = %d, want %d", tc.capacity, tc.level, got, tc.want)
		}
	}
	h := Host{Capacity: 4, ActiveRunners: 2, Throttle: HostThrottle{Level: 2}}
	if h.Free() != 0 || h.Available(time.Now()) {
		t.Fatalf("a host at its throttled capacity still offered slots: free=%d", h.Free())
	}
	h.Throttle = HostThrottle{}
	if h.Free() != 2 {
		t.Fatalf("lifting the throttle did not give the slots back: free=%d", h.Free())
	}
}

// The throttle survives a restart and cannot be reached by the paths a host
// writes through: it is the controller's decision about the host, and a host
// that could rewrite it on a heartbeat could talk its way off its own rung.
func TestAThrottleIsStoredByItsOwnStatementAndSurvivesTheHostsOwnWrites(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	h := &Host{Name: "pressed", Capacity: 4, Backends: StringSlice{"docker"}, Labels: StringMap{}}
	if err := s.CreateHost(ctx, h); err != nil {
		t.Fatalf("CreateHost: %v", err)
	}
	since := time.Date(2026, 9, 13, 12, 0, 0, 0, time.UTC)
	want := HostThrottle{Level: 2, Since: &since, ChangedAt: &since, Reason: "CPU has been at or above 95% for 30 s"}
	if err := s.SetHostThrottle(ctx, h.ID, want, 0); err != nil {
		t.Fatalf("SetHostThrottle: %v", err)
	}
	got, err := s.GetHost(ctx, h.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if got.Throttle.Level != 2 || got.Throttle.Reason != want.Reason || got.Throttle.Since == nil || !got.Throttle.Since.Equal(since) {
		t.Fatalf("throttle = %+v after a round trip, want %+v", got.Throttle, want)
	}
	if got.EffectiveCapacity() != 2 {
		t.Fatalf("effective capacity = %d, want 2 from a level-2 throttle on 4 slots", got.EffectiveCapacity())
	}

	// The heartbeat's path and the operator's path both leave it alone.
	got.Capacity = 8
	if err := s.UpdateHost(ctx, got); err != nil {
		t.Fatalf("UpdateHost: %v", err)
	}
	if err := s.SetHostReported(ctx, got); err != nil {
		t.Fatalf("SetHostReported: %v", err)
	}
	if err := s.SetHostUsage(ctx, h.ID, HostUsage{}); err != nil {
		t.Fatalf("SetHostUsage: %v", err)
	}
	again, err := s.GetHost(ctx, h.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if again.Throttle.Level != 2 {
		t.Fatalf("a host's own write moved its throttle: %+v", again.Throttle)
	}
	if err := s.SetHostThrottle(ctx, h.ID, HostThrottle{}, 2); err != nil {
		t.Fatalf("SetHostThrottle: %v", err)
	}
	if again, _ = s.GetHost(ctx, h.ID); again.Throttle.Active() || again.EffectiveCapacity() != 8 {
		t.Fatalf("clearing the throttle did not give the host its capacity back: %+v", again)
	}
	if err := s.SetHostThrottle(ctx, "host_missing", HostThrottle{Level: 1}, 0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("a throttle written for a host that does not exist: %v", err)
	}
	// Two deciders, one decision. The write says which rung it was decided
	// from, and a rung that has moved since -- a heartbeat that got there
	// first, or an operator's clear -- refuses the stale one rather than
	// recording it twice or undoing the clear.
	if err := s.SetHostThrottle(ctx, h.ID, HostThrottle{Level: 1}, 0); err != nil {
		t.Fatalf("SetHostThrottle from rung 0: %v", err)
	}
	if err := s.SetHostThrottle(ctx, h.ID, HostThrottle{Level: 1}, 0); !errors.Is(err, ErrThrottleMoved) {
		t.Fatalf("a decision from a rung the host has left was written: %v", err)
	}
	if got, _ := s.GetHost(ctx, h.ID); got.Throttle.Level != 1 {
		t.Fatalf("the refused write moved the rung: %+v", got.Throttle)
	}
}

// A host's row counts its live runners on every read, and now also how many
// of them nothing binds: a sustained CPU hold means overload only on a host
// carrying a runner that can take more than its share, so the count has to
// come from the rows rather than from memory, and it has to leave finished
// runners out exactly as the slot count does.
func TestAHostCountsTheLiveRunnersNoCPULimitBinds(t *testing.T) {
	s := newTestStore(t)
	_, p, h := seedPool(t, s)
	ctx := context.Background()
	limited := &Runner{PoolID: p.ID, HostID: h.ID, Name: "limited", AllocatedCPUs: 2, AllocationSource: AllocationFromHost}
	unlimited := &Runner{PoolID: p.ID, HostID: h.ID, Name: "unlimited"}
	finished := &Runner{PoolID: p.ID, HostID: h.ID, Name: "finished"}
	for _, r := range []*Runner{limited, unlimited, finished} {
		if err := s.CreateRunner(ctx, r); err != nil {
			t.Fatalf("CreateRunner: %v", err)
		}
	}
	if _, err := s.TransitionRunner(ctx, finished.ID, RunnerFailed, "gone"); err != nil {
		t.Fatalf("TransitionRunner: %v", err)
	}
	got, err := s.GetHost(ctx, h.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if got.ActiveRunners != 2 || got.UnlimitedRunners != 1 {
		t.Fatalf("active = %d, unlimited = %d; want 2 live of which 1 has no CPU limit", got.ActiveRunners, got.UnlimitedRunners)
	}
}

// The throttle column is JSON, and it has to come back from every shape the
// driver hands over: a string, bytes, and the NULL a row written before the
// column existed would have carried had the migration not defaulted it.
func TestAThrottleScansFromEveryShapeTheDriverOffers(t *testing.T) {
	since := time.Date(2026, 9, 13, 12, 0, 0, 0, time.UTC)
	want := HostThrottle{Level: 2, Since: &since, Reason: "memory at the reserve"}
	v, err := want.Value()
	if err != nil {
		t.Fatalf("Value: %v", err)
	}
	raw, ok := v.(string)
	if !ok {
		t.Fatalf("Value() = %T, want the JSON as a string", v)
	}
	for name, in := range map[string]any{"string": raw, "bytes": []byte(raw)} {
		var got HostThrottle
		if err := got.Scan(in); err != nil {
			t.Fatalf("Scan(%s): %v", name, err)
		}
		if got.Level != 2 || got.Reason != want.Reason || got.Since == nil || !got.Since.Equal(since) {
			t.Fatalf("Scan(%s) = %+v, want %+v", name, got, want)
		}
	}
	var empty HostThrottle
	if err := empty.Scan(nil); err != nil || empty.Active() {
		t.Fatalf("Scan(nil) = %+v, %v; want an inactive throttle and no error", empty, err)
	}
	if err := empty.Scan(42); err == nil {
		t.Fatal("a number scanned as a throttle")
	}
}

package store

import (
	"context"
	"database/sql/driver"
	"fmt"
	"math"
	"time"
)

// HostUsage is a recent whole-host measurement, separate from reservations.
// Pointers distinguish an idle/full host from a host that could not measure.
// The controller owns the timestamps and the sustained-CPU hold.
type HostUsage struct {
	CPUPercent        *float64 `json:"cpu_percent,omitempty"`
	MemoryAvailableMB *int64   `json:"memory_available_mb,omitempty"`
	// LoadAverage1 is the kernel's one-minute load average for the whole
	// machine. CPU occupancy stops at 100%; this keeps counting the tasks
	// queued behind the cores, so it is what says how far past its size a
	// host has been pushed rather than merely that it is busy.
	LoadAverage1 *float64   `json:"load_average_1m,omitempty"`
	SampledAt    time.Time  `json:"sampled_at,omitempty"`
	CPUHighSince *time.Time `json:"cpu_high_since,omitempty"`
	CPUHeld      bool       `json:"cpu_held,omitempty"`
	// LentCPUPercent is the part of CPUPercent that runners were using out of
	// CPU elastic CPU lent them, as a share of the whole host. The controller
	// works it out from the same heartbeat's runner samples; whatever an agent
	// put here is replaced. A boost doing its job is load the plan chose, and
	// judging admission and the throttle on it would have a boost trip the
	// very hold that then withdraws it.
	LentCPUPercent float64 `json:"lent_cpu_percent,omitempty"`
	// IOWaitPercent is the share of CPU time the machine spent idle with
	// something waiting on disk, as the agent measured it between heartbeats.
	// CPUPercent counts that time as busy, so a build stalled on a saturated disk
	// reads as a host hard at work; this is the figure that says otherwise.
	IOWaitPercent *float64 `json:"io_wait_percent,omitempty"`
	// IOWaitHighSince is when I/O wait rose to IOWaitHighPercent and has not
	// fallen below IOWaitCalmPercent since. The controller owns it, for the reason
	// it owns CPUHighSince: an agent that sent its own could keep a host looking
	// disk-bound, or never.
	IOWaitHighSince *time.Time `json:"io_wait_high_since,omitempty"`
}

// UnlentCPUPercent is the host's CPU less what runners were using of CPU lent
// to them: the load the plan did not account for. Nil where CPU was not
// measured.
func (u HostUsage) UnlentCPUPercent() *float64 {
	if u.CPUPercent == nil {
		return nil
	}
	v := max(*u.CPUPercent-max(u.LentCPUPercent, 0), 0)
	return &v
}

const HostUsageMaxAge = 90 * time.Second

// CPUHoldWindow is how long CPU has to sit at or above 95% before new starts
// are held. It is a constant rather than a literal because the throttle
// ladder is paced against it: a rung may not be climbed faster than the hold
// that feeds it can trip, and internal/controller pins the two together.
const CPUHoldWindow = 30 * time.Second

// I/O wait is judged the way CPU is: one threshold to start the clock and a
// lower one to stop it, so a host hovering around the line is one sustained
// condition rather than a dozen short ones. The advice that rests on it -- that
// a pool's scratch folders could live in memory -- is persistent, and a clock
// that reset on every dip would never reach IOWaitSustained on a busy disk,
// which dips constantly.
const (
	IOWaitHighPercent = 20.0
	IOWaitCalmPercent = 10.0
	// IOWaitSustained is how long a host has to have been waiting on disk before
	// anything is said about it. A build's checkout is a burst of I/O, and a
	// notification for each one would teach an operator to ignore the list.
	IOWaitSustained = 10 * time.Minute
)

// DiskBound reports whether this host has been waiting on its disk, steadily,
// for long enough to say so.
func (u HostUsage) DiskBound(now time.Time) bool {
	return u.Fresh(now) && u.IOWaitHighSince != nil && now.Sub(*u.IOWaitHighSince) >= IOWaitSustained
}

func (u HostUsage) Fresh(now time.Time) bool {
	return !u.SampledAt.IsZero() && !now.Before(u.SampledAt) && now.Sub(u.SampledAt) < HostUsageMaxAge
}

// ObserveHostUsage validates just the measurements an agent may supply. A
// forged timestamp cannot keep a reading fresh, or shorten a pressure hold.
// Sustained CPU pressure pauses admission after 30 seconds above 95%; a
// reading below 85% releases it. Busy runners are never changed by this state.
//
// lentPercent is the controller's own figure for the share of the host that
// runners were using out of lent CPU, and both thresholds are judged without
// it. The recorded CPUPercent stays the raw measurement.
func ObserveHostUsage(previous, measured HostUsage, lentPercent float64, memoryMB int64, now time.Time) HostUsage {
	u := HostUsage{SampledAt: now}
	if v := measured.CPUPercent; v != nil && !math.IsNaN(*v) && !math.IsInf(*v, 0) && *v >= 0 && *v <= 100 {
		raw := *v
		u.CPUPercent = &raw
		if !math.IsNaN(lentPercent) && lentPercent > 0 {
			u.LentCPUPercent = min(lentPercent, raw)
		}
		value := *u.UnlentCPUPercent()
		if previous.Fresh(now) && previous.CPUPercent != nil {
			u.CPUHeld = previous.CPUHeld && value >= 85
		}
		if value >= 95 {
			since := now
			if previous.Fresh(now) && previous.CPUHighSince != nil {
				since = *previous.CPUHighSince
			}
			u.CPUHighSince = &since
			u.CPUHeld = u.CPUHeld || now.Sub(since) >= CPUHoldWindow
		}
	}
	if v := measured.MemoryAvailableMB; v != nil && *v >= 0 && memoryMB > 0 && *v <= memoryMB {
		value := *v
		u.MemoryAvailableMB = &value
	}
	if v := measured.IOWaitPercent; v != nil && !math.IsNaN(*v) && !math.IsInf(*v, 0) && *v >= 0 && *v <= 100 {
		wait := *v
		u.IOWaitPercent = &wait
		held := previous.Fresh(now) && previous.IOWaitHighSince != nil
		switch {
		case wait >= IOWaitHighPercent && held:
			since := *previous.IOWaitHighSince
			u.IOWaitHighSince = &since
		case wait >= IOWaitHighPercent:
			since := now
			u.IOWaitHighSince = &since
		case wait >= IOWaitCalmPercent && held:
			since := *previous.IOWaitHighSince
			u.IOWaitHighSince = &since
		}
	}
	// A load average has no ceiling -- that is the point of it -- but it is
	// never negative, and a NaN or an infinity is an agent that read
	// something other than /proc/loadavg. A figure that is only a load
	// average, with no CPU and no memory, is still a measurement.
	if v := measured.LoadAverage1; v != nil && !math.IsNaN(*v) && !math.IsInf(*v, 0) && *v >= 0 {
		value := *v
		u.LoadAverage1 = &value
	}
	if u.CPUPercent == nil && u.MemoryAvailableMB == nil && u.LoadAverage1 == nil {
		return HostUsage{}
	}
	return u
}

func (u HostUsage) Value() (driver.Value, error) { return marshalJSON(u) }

func (u *HostUsage) Scan(value any) error {
	*u = HostUsage{}
	switch v := value.(type) {
	case string:
		return unmarshalJSON(v, u)
	case []byte:
		return unmarshalJSON(string(v), u)
	case nil:
		return nil
	default:
		return fmt.Errorf("host usage: unexpected database value %T", value)
	}
}

// SetHostUsage cannot write an operator's capacity, cordon or reserves.
func (s *Store) SetHostUsage(ctx context.Context, id string, usage HostUsage) error {
	res, err := s.exec(ctx, `UPDATE hosts SET usage=? WHERE id=?`, usage, id)
	if err != nil {
		return wrapWrite(err)
	}
	return affected(res, "host", id)
}

package store

import (
	"testing"
	"time"
)

func ioWaitUsage(v float64) HostUsage {
	cpu := 50.0
	return HostUsage{CPUPercent: &cpu, IOWaitPercent: &v}
}

// Disk-bound is a state a host has been in for a while, not a reading: a
// checkout is a burst of I/O, and the advice resting on this is persistent, so
// it must not be raised by a spike or lost to a dip.
func TestAHostIsDiskBoundOnlyAfterWaitingOnDiskForTheWholeWindow(t *testing.T) {
	start := time.Date(2026, 10, 4, 12, 0, 0, 0, time.UTC)
	step := func(prev HostUsage, wait float64, at time.Duration) HostUsage {
		return ObserveHostUsage(prev, ioWaitUsage(wait), 0, 16384, start.Add(at))
	}

	u := step(HostUsage{}, 35, 0)
	if u.IOWaitHighSince == nil || !u.IOWaitHighSince.Equal(start) {
		t.Fatalf("a first reading above the threshold should start the clock at once: %+v", u)
	}
	if u.DiskBound(start) {
		t.Fatal("a host is not disk-bound the moment I/O wait rises")
	}

	// Heartbeats every 30s, wait wandering between 12 and 38: above the calm
	// line throughout, so it is one stretch even though it dips under the
	// start line.
	waits := []float64{38, 12, 25, 14, 30, 11, 22}
	at := time.Duration(0)
	for i := 0; i < 24; i++ {
		at += 30 * time.Second
		u = step(u, waits[i%len(waits)], at)
	}
	if !u.DiskBound(start.Add(at)) {
		t.Fatalf("a host that has waited on disk for %s should be disk-bound: %+v", at, u)
	}
	if !u.IOWaitHighSince.Equal(start) {
		t.Fatalf("the clock moved to %v; it should stay where the stretch began", u.IOWaitHighSince)
	}

	// Falling below the calm line ends it, and the next rise starts a new one.
	u = step(u, 4, at+30*time.Second)
	if u.IOWaitHighSince != nil || u.DiskBound(start.Add(at+30*time.Second)) {
		t.Fatalf("a host whose disk has calmed is still called bound: %+v", u)
	}
	u = step(u, 40, at+time.Minute)
	if u.IOWaitHighSince == nil || !u.IOWaitHighSince.Equal(start.Add(at+time.Minute)) {
		t.Fatalf("a new stretch should start its own clock: %+v", u)
	}
}

// A stale reading proves nothing about a host that has gone quiet, and neither
// does a clock a silent agent could have left running.
func TestAStaleHostIsNotDiskBoundAndAStaleClockIsNotCarried(t *testing.T) {
	start := time.Date(2026, 10, 4, 12, 0, 0, 0, time.UTC)
	u := ObserveHostUsage(HostUsage{}, ioWaitUsage(40), 0, 16384, start)
	if u.DiskBound(start.Add(HostUsageMaxAge + time.Hour)) {
		t.Fatal("a reading from an hour ago was taken as the host's state now")
	}
	// The agent comes back after a silence: the old clock must not make the
	// first new reading look like ten minutes of waiting.
	later := start.Add(time.Hour)
	back := ObserveHostUsage(u, ioWaitUsage(40), 0, 16384, later)
	if back.IOWaitHighSince == nil || !back.IOWaitHighSince.Equal(later) {
		t.Fatalf("clock = %v after a silence, want it restarted at %v", back.IOWaitHighSince, later)
	}
}

// What an agent sends is checked: a wait outside 0..100 is an agent that read
// something other than /proc/stat, and is dropped rather than recorded.
func TestAnImpossibleIOWaitIsNotRecorded(t *testing.T) {
	now := time.Date(2026, 10, 4, 12, 0, 0, 0, time.UTC)
	for _, v := range []float64{-1, 101, 1e9} {
		if u := ObserveHostUsage(HostUsage{}, ioWaitUsage(v), 0, 16384, now); u.IOWaitPercent != nil || u.IOWaitHighSince != nil {
			t.Errorf("io wait %v was recorded: %+v", v, u)
		}
	}
}

package store

import (
	"math"
	"testing"
	"time"
)

func TestCPUAdmissionRequiresSustainedPressureAndHasRecoveryHysteresis(t *testing.T) {
	now := time.Date(2026, 9, 13, 12, 0, 0, 0, time.UTC)
	observe := func(old HostUsage, cpu float64, seconds int) HostUsage {
		return ObserveHostUsage(old, HostUsage{CPUPercent: &cpu}, 0, 8192, now.Add(time.Duration(seconds)*time.Second))
	}
	u := observe(HostUsage{}, 98, 0)
	if u.CPUHeld {
		t.Fatal("one high sample stopped new work")
	}
	u = observe(u, 98, 15)
	if u.CPUHeld {
		t.Fatal("less than 30 seconds of pressure stopped new work")
	}
	u = observe(u, 98, 30)
	if !u.CPUHeld {
		t.Fatal("sustained saturation did not hold admission")
	}
	u = observe(u, 90, 60)
	if !u.CPUHeld {
		t.Fatal("a small CPU dip released the hold")
	}
	u = observe(u, 84, 90)
	if u.CPUHeld {
		t.Fatal("recovered CPU did not release the hold")
	}
	u = observe(u, 98, 120)
	if u.CPUHeld {
		t.Fatal("old pressure was reused after recovery")
	}
	u = observe(u, 98, 240)
	if u.CPUHeld {
		t.Fatal("a stale observation counted as sustained pressure")
	}
}

// A load average is the one figure with no upper bound, so the validation is
// about the lower one and about numbers that are not numbers: a negative,
// a NaN or an infinity is an agent reading the wrong file, and none of them
// may become a reading the throttle then acts on.
func TestLoadAverageIsKeptWhenSaneAndDroppedWhenNot(t *testing.T) {
	now := time.Now()
	for _, v := range []float64{0, 0.5, 17.25, 400} {
		load := v
		u := ObserveHostUsage(HostUsage{}, HostUsage{LoadAverage1: &load}, 0, 8192, now)
		if u.LoadAverage1 == nil || *u.LoadAverage1 != v || !u.Fresh(now) {
			t.Fatalf("a load average of %v was not kept: %+v", v, u)
		}
	}
	for _, v := range []float64{-1, math.NaN(), math.Inf(1), math.Inf(-1)} {
		load := v
		u := ObserveHostUsage(HostUsage{}, HostUsage{LoadAverage1: &load}, 0, 8192, now)
		if u.LoadAverage1 != nil || u.Fresh(now) {
			t.Fatalf("a load average of %v became a measurement: %+v", v, u)
		}
	}
}

func TestUsageIgnoresAgentTimestampsAndRejectsImpossibleValues(t *testing.T) {
	now := time.Now()
	zero, full := 0.0, int64(0)
	future := now.Add(time.Hour)
	u := ObserveHostUsage(HostUsage{}, HostUsage{CPUPercent: &zero, MemoryAvailableMB: &full,
		SampledAt: future, CPUHighSince: &future, CPUHeld: true}, 0, 8192, now)
	if u.CPUHeld || u.CPUHighSince != nil || !u.SampledAt.Equal(now) || u.CPUPercent == nil || u.MemoryAvailableMB == nil {
		t.Fatalf("agent control fields or measured zero were mishandled: %+v", u)
	}
	if u.Fresh(now.Add(HostUsageMaxAge)) || u.Fresh(now.Add(-time.Second)) {
		t.Fatal("stale/future sample is fresh")
	}
	for _, cpu := range []float64{-1, 101, math.NaN(), math.Inf(1)} {
		if got := ObserveHostUsage(u, HostUsage{CPUPercent: &cpu}, 0, 8192, now); !got.SampledAt.IsZero() {
			t.Fatalf("invalid CPU accepted: %v", cpu)
		}
	}
	for _, mem := range []int64{-1, 8193} {
		if got := ObserveHostUsage(u, HostUsage{MemoryAvailableMB: &mem}, 0, 8192, now); got.MemoryAvailableMB != nil {
			t.Fatalf("invalid memory accepted: %d", mem)
		}
	}
}

func TestUsageRoundTripCannotUndoCordonCapacityOrReserves(t *testing.T) {
	s := newTestStore(t)
	_, _, host := seedPool(t, s)
	ctx := t.Context()
	if err := s.SetHostCordoned(ctx, host.ID, true); err != nil {
		t.Fatal(err)
	}
	capacity, reserve := 0, 1
	if err := s.PatchHost(ctx, host.ID, HostChanges{Capacity: &capacity, ReserveCPUs: &reserve}); err != nil {
		t.Fatal(err)
	}
	cpu, mem := 97.0, int64(2048)
	u := HostUsage{CPUPercent: &cpu, MemoryAvailableMB: &mem, SampledAt: s.Now(), CPUHeld: true}
	if err := s.SetHostUsage(ctx, host.ID, u); err != nil {
		t.Fatal(err)
	}
	h, err := s.GetHost(ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	if !h.Cordoned || h.Capacity != 0 || h.ReserveCPUs != 1 || !h.Usage.CPUHeld || h.Usage.CPUPercent == nil || *h.Usage.CPUPercent != cpu {
		t.Fatalf("usage or operator state lost: %+v", h)
	}
}

// A host at full CPU because its runners are using the CPU they were lent is
// doing what the plan chose. Holding new starts for it would punish a boost
// for working; CPU nobody lent still holds them.
func TestLentCPUInUseDoesNotTripTheSustainedCPUHold(t *testing.T) {
	now := time.Now()
	cpu := 99.0
	u := HostUsage{}
	for s := 0; s <= 40; s += 10 {
		u = ObserveHostUsage(u, HostUsage{CPUPercent: &cpu}, 30, 8192, now.Add(time.Duration(s)*time.Second))
	}
	if u.CPUHeld || u.CPUHighSince != nil {
		t.Fatalf("a host at 99%% with 30%% of it lent CPU in use was held: %+v", u)
	}
	if *u.CPUPercent != 99 || u.LentCPUPercent != 30 || *u.UnlentCPUPercent() != 69 {
		t.Fatalf("usage = %+v, want the raw 99%% recorded beside 30%% lent", u)
	}

	u = HostUsage{}
	for s := 0; s <= 40; s += 10 {
		u = ObserveHostUsage(u, HostUsage{CPUPercent: &cpu}, 2, 8192, now.Add(time.Duration(s)*time.Second))
	}
	if !u.CPUHeld {
		t.Fatalf("a host at 99%% with only 2%% of it lent was not held: %+v", u)
	}
}

package store

import "strings"

// Runner labels somebody else operates.
//
// A job whose labels all name GitHub's own runners, or a hosted-runner
// vendor's, runs where its labels say. This fleet has no pool for it and never
// will, so it is neither this fleet's work nor this fleet's fault, and every
// question the product answers about "our jobs" has to be able to leave it out
// -- the Jobs page's default view, the Overview's counts, the usage figures and
// the unmatched warning alike.
//
// The lists live here rather than in internal/migrate, which is where the
// migration wizard first needed them, because internal/store is what the SQL
// asking the same question is written against and internal/migrate imports it.
// migrate.IsHostedLabel and migrate.IsManagedLabel are now the wizard's names
// for these.

// hostedPrefixes are the runner labels GitHub itself provides, as of the runner
// images published for github.com.
//
// It is a prefix list, not an exact one: GitHub keeps adding sizes and versions
// ("ubuntu-22.04-arm", "windows-11-arm", the larger-runner names an
// organisation configures), and a list of only the exact names we shipped with
// would go quietly blind as they change.
var hostedPrefixes = []string{"ubuntu-", "windows-", "macos-"}

// vendorPrefixes are the label shapes of the hosted-runner vendors that sit in
// front of GitHub Actions -- Blacksmith, BuildJet, WarpBuild, Namespace, Depot
// and Ubicloud.
//
// They belong beside GitHub's own for the same reason: a repository on
// "blacksmith-4vcpu-ubuntu-2404" is renting somebody else's machines by the
// minute, and this fleet has no more to do with that job than with one on
// "ubuntu-latest". A prefix list again, and for the same reason -- every one of
// these vendors keeps adding sizes.
var vendorPrefixes = []string{
	"blacksmith",
	"buildjet-",
	"warp-",
	"namespace-profile-",
	"nscloud-",
	"depot-",
	"ubicloud",
}

// IsHostedLabel reports whether label is one of GitHub's own runner labels.
func IsHostedLabel(label string) bool {
	return hasAnyPrefix(NormalizeLabel(label), hostedPrefixes)
}

// IsManagedLabel reports whether label names a runner somebody else operates:
// GitHub's own, or one of the vendors above. The distinction that matters to an
// operator is not "GitHub or not" but "rented or ours".
func IsManagedLabel(label string) bool {
	l := NormalizeLabel(label)
	return hasAnyPrefix(l, hostedPrefixes) || hasAnyPrefix(l, vendorPrefixes)
}

func hasAnyPrefix(label string, prefixes []string) bool {
	if label == "" {
		return false
	}
	for _, p := range prefixes {
		if strings.HasPrefix(label, p) {
			return true
		}
	}
	return false
}

// HostedJob reports whether every label a job asked for names a runner somebody
// else operates. Such a job is theirs to run: it being unmatched here is what
// the workflow asked for rather than a job going nowhere.
//
// A job with no labels at all is not hosted. GitHub always sends the labels it
// resolved, so an empty set means a delivery we could not read rather than a
// job nobody has to run, and guessing "somebody else's" about it would hide it
// from the one page that could show the gap.
func HostedJob(labels []string) bool {
	if len(labels) == 0 {
		return false
	}
	for _, l := range labels {
		if !IsManagedLabel(l) {
			return false
		}
	}
	return true
}

// hostedJobSQL is HostedJob in SQL, over the JSON array the labels are stored
// as. The two spellings are built from the same prefix lists, because a page
// that hides a vendor's job while the warning above it still counts one is
// worse than either behaviour on its own.
//
// The caller names the jobs table as its own query spells it, because pools
// have labels too and a query that joins the two cannot say `labels` at all.
func hostedJobSQL(jobs string) string {
	tests := make([]string, 0, len(hostedPrefixes)+len(vendorPrefixes))
	for _, p := range append(append([]string{}, hostedPrefixes...), vendorPrefixes...) {
		// The prefixes are literal words and hyphens, but ESCAPE keeps that
		// from being load-bearing: a vendor prefix with an underscore in it
		// would otherwise match anything.
		tests = append(tests, `value NOT LIKE '`+likeEscape(p)+`%' ESCAPE '\'`)
	}
	return `(json_array_length(` + jobs + `.labels) > 0 AND NOT EXISTS (
		SELECT 1 FROM json_each(` + jobs + `.labels) WHERE ` + strings.Join(tests, " AND ") + `))`
}

package store

import "testing"

// The prefixes are what tells a runner this fleet could own from one it never
// will, and both halves of the product read them: the migration wizard offers
// to migrate the labels, and the Jobs page decides from them whether a job is
// this fleet's business at all.
func TestManagedLabelsAreTheOnesSomebodyElseOperates(t *testing.T) {
	for _, tc := range []struct {
		label   string
		hosted  bool
		managed bool
	}{
		{"ubuntu-latest", true, true},
		{"ubuntu-22.04-arm", true, true},
		{"windows-11-arm", true, true},
		// GitHub's own images are written both ways in the wild, and a label
		// is case-insensitive to GitHub, so it must be here too.
		{"macOS-14", true, true},
		{"blacksmith-4vcpu-ubuntu-2404", false, true},
		{"buildjet-8vcpu-ubuntu-2204", false, true},
		{"ubicloud-standard-2", false, true},
		// Ours, or an organisation's own invention. Neither is somebody
		// else's to run, and a job asking for one waits on this fleet.
		{"self-hosted", false, false},
		{"gpu", false, false},
		{"ubuntu", false, false},
		{"", false, false},
	} {
		if got := IsHostedLabel(tc.label); got != tc.hosted {
			t.Errorf("IsHostedLabel(%q) = %v, want %v", tc.label, got, tc.hosted)
		}
		if got := IsManagedLabel(tc.label); got != tc.managed {
			t.Errorf("IsManagedLabel(%q) = %v, want %v", tc.label, got, tc.managed)
		}
	}
}

// A job is somebody else's only when every label says so. One label this fleet
// could answer makes the job ours to run, or ours to explain.
func TestOneLabelThisFleetCouldAnswerMakesTheJobOurs(t *testing.T) {
	for _, tc := range []struct {
		name   string
		labels []string
		want   bool
	}{
		{"a vendor's", []string{"blacksmith-4vcpu-ubuntu-2404"}, true},
		{"GitHub's own", []string{"ubuntu-latest"}, true},
		{"mixed", []string{"ubuntu-latest", "gpu"}, false},
		{"ours", []string{"self-hosted", "linux", "x64"}, false},
		// A delivery we could not read the labels of, rather than a job
		// nobody has to run: guessing "somebody else's" would hide it.
		{"none at all", nil, false},
	} {
		if got := HostedJob(tc.labels); got != tc.want {
			t.Errorf("HostedJob(%v) [%s] = %v, want %v", tc.labels, tc.name, got, tc.want)
		}
	}
}

package store

import (
	"context"
	"fmt"
	"testing"
	"time"
)

// ListHosts is one of the dozen reads that take a reconcile pass's snapshot, and
// it is three questions: the hosts, how many runners are live on each, and which
// checks an operator has accepted on them. A fifth of the fleet has accepted one,
// as a fleet that has been looked after does. The scenario is checked before
// anything is timed, because a fleet with no acceptances would time a read that
// has nothing to carry.
func BenchmarkListHosts(b *testing.B) {
	ctx := context.Background()
	for _, n := range []int{4, 20, 100} {
		b.Run(fmt.Sprintf("hosts=%d", n), func(b *testing.B) {
			s := newTestStore(b)
			accepted := 0
			for i := range n {
				h := &Host{Name: fmt.Sprintf("vm-%03d", i), Capacity: 4, Backends: StringSlice{"docker"}}
				if err := s.CreateHost(ctx, h); err != nil {
					b.Fatalf("CreateHost: %v", err)
				}
				if i%5 == 0 {
					a := &HostCheckAcceptance{HostID: h.ID, CheckID: "docker.logs", Current: "none", Reason: "pinned on purpose",
						By: "usr_1", ByName: "Sam", ExpiresAt: time.Now().Add(24 * time.Hour)}
					if err := s.UpsertHostCheckAcceptance(ctx, a); err != nil {
						b.Fatalf("UpsertHostCheckAcceptance: %v", err)
					}
					accepted++
				}
			}
			hosts, err := s.ListHosts(ctx)
			if err != nil {
				b.Fatalf("ListHosts: %v", err)
			}
			carried := 0
			for _, h := range hosts {
				carried += len(h.Acceptances)
			}
			if len(hosts) != n || carried != accepted {
				b.Fatalf("ListHosts returned %d hosts carrying %d acceptances; want %d carrying %d", len(hosts), carried, n, accepted)
			}

			b.ReportAllocs()
			for b.Loop() {
				if _, err := s.ListHosts(ctx); err != nil {
					b.Fatal(err)
				}
			}
		})
	}
}

package store

import (
	"context"
	"database/sql"
	"sync"
	"sync/atomic"
)

// The driver parses every statement it is given, every time it is given it, and
// in a CPU profile of a webhook delivery, of a poller sweep and of a reconcile
// pass that parsing was a third, a third and a sixth of all the time they took.
// A hot query is a statement the store prepares once and runs from that
// preparation ever after, for the dozen or so statements the paths that run
// most often make.
//
// It is opt-in, statement by statement, and not a cache behind every query,
// because a cache keyed on the text of whatever it is handed grows with the
// variety of what it is handed: a query built around a list of ids is a new
// statement each time its list is a new length. A hot query is a constant,
// registered when the package is initialised, so the set is fixed and small.
//
// Two things to keep to. A hot query is run to completion before the same one is
// run again on the same connection, which is true of anything that is scanned as
// it is read and not interleaved with itself: a prepared statement has one
// cursor, and a second run of it would rewind the first. And inside a
// transaction each run takes a statement of the transaction's own from the
// prepared one, which lasts until the transaction ends, so it is for statements
// a transaction runs a few times and not for one it runs in a loop.

// hotQuery is a statement registered with hot. Its id is its place in each
// pool's table of prepared statements.
type hotQuery struct {
	id  int
	sql string
}

// hotQueries is the text of every registered hot query, by id. It is written
// while the package initialises and only read after.
var hotQueries []string

// hot registers a statement as a hot query. Call it from a package-level
// variable, so that registration is done before any Store is opened.
func hot(query string) hotQuery {
	hotQueries = append(hotQueries, query)
	return hotQuery{id: len(hotQueries) - 1, sql: query}
}

// stmtCache holds one pool's prepared statements, a slot for each registered hot
// query, filled the first time the query is run on that pool.
//
// A *sql.Stmt prepared on a pool is prepared again by database/sql on each of
// that pool's connections as they are first used, and is safe for any number of
// goroutines at once, so the slot holds the one handle. What it cannot be is
// prepared while a transaction holds the pool's only connection, which the
// writer's always is: asking the pool for a connection then waits for the
// transaction, which is waiting for the statement. A statement first run inside
// a transaction therefore runs unprepared that once, and is prepared the next
// time the writer is taken outside one.
type stmtCache struct {
	db    *sql.DB
	slots []atomic.Pointer[sql.Stmt]

	mu     sync.Mutex
	wanted []int
	// pending is set while wanted is not empty, so that the writer can check
	// whether there is anything to prepare without taking mu.
	pending atomic.Bool
	// hits and misses count the times a hot query ran with a prepared statement
	// and without one. They are for the tests, which hold each statement that has
	// been made hot to being run as one.
	hits, misses atomic.Int64
}

func newStmtCache(db *sql.DB) *stmtCache {
	return &stmtCache{db: db, slots: make([]atomic.Pointer[sql.Stmt], len(hotQueries))}
}

// prepared returns the statement prepared for q on this pool, preparing it if
// that can be done now, and nil if it cannot. inTx says the pool's connection is
// held by a transaction, in which case nothing is prepared.
func (c *stmtCache) prepared(ctx context.Context, q hotQuery, inTx bool) *sql.Stmt {
	if c == nil || q.id >= len(c.slots) {
		return nil
	}
	if st := c.slots[q.id].Load(); st != nil {
		c.hits.Add(1)
		return st
	}
	c.misses.Add(1)
	if inTx {
		c.want(q.id)
		return nil
	}
	st := c.prepare(ctx, q)
	if st != nil {
		c.hits.Add(1)
	}
	return st
}

func (c *stmtCache) prepare(ctx context.Context, q hotQuery) *sql.Stmt {
	st, err := c.db.PrepareContext(ctx, q.sql)
	if err != nil {
		// Run it unprepared: the statement fails again, with the error that says
		// what is wrong, wherever it is actually run.
		return nil
	}
	if !c.slots[q.id].CompareAndSwap(nil, st) {
		st.Close()
		return c.slots[q.id].Load()
	}
	return st
}

func (c *stmtCache) want(id int) {
	c.mu.Lock()
	defer c.mu.Unlock()
	for _, w := range c.wanted {
		if w == id {
			return
		}
	}
	c.wanted = append(c.wanted, id)
	c.pending.Store(true)
}

// prepareWanted prepares the statements that were first run inside a
// transaction. It is called with the writer held and no transaction begun.
func (c *stmtCache) prepareWanted(ctx context.Context) {
	if c == nil || !c.pending.Load() {
		return
	}
	c.mu.Lock()
	wanted := c.wanted
	c.wanted = nil
	c.pending.Store(false)
	c.mu.Unlock()
	for _, id := range wanted {
		if c.slots[id].Load() == nil {
			c.prepare(ctx, hotQuery{id: id, sql: hotQueries[id]})
		}
	}
}

// close releases every prepared statement. It is called before the pool is
// closed.
func (c *stmtCache) close() {
	if c == nil {
		return
	}
	for i := range c.slots {
		if st := c.slots[i].Swap(nil); st != nil {
			st.Close()
		}
	}
}

// runner is what a pool and a transaction have in common.
type runner interface {
	ExecContext(ctx context.Context, query string, args ...any) (sql.Result, error)
	QueryContext(ctx context.Context, query string, args ...any) (*sql.Rows, error)
	QueryRowContext(ctx context.Context, query string, args ...any) *sql.Row
}

// hotConn runs hot queries on one pool, in one transaction if tx is set.
type hotConn struct {
	cache *stmtCache
	run   runner
	tx    *sql.Tx
}

// stmt is the statement to run q with, or nil to run its text instead.
func (h hotConn) stmt(ctx context.Context, q hotQuery) *sql.Stmt {
	st := h.cache.prepared(ctx, q, h.tx != nil)
	if st != nil && h.tx != nil {
		return h.tx.StmtContext(ctx, st)
	}
	return st
}

// Exec is ExecContext of a hot query.
func (h hotConn) Exec(ctx context.Context, q hotQuery, args ...any) (sql.Result, error) {
	if st := h.stmt(ctx, q); st != nil {
		return st.ExecContext(ctx, args...)
	}
	return h.run.ExecContext(ctx, q.sql, args...)
}

// Query is QueryContext of a hot query.
func (h hotConn) Query(ctx context.Context, q hotQuery, args ...any) (*sql.Rows, error) {
	if st := h.stmt(ctx, q); st != nil {
		return st.QueryContext(ctx, args...)
	}
	return h.run.QueryContext(ctx, q.sql, args...)
}

// QueryRow is QueryRowContext of a hot query.
func (h hotConn) QueryRow(ctx context.Context, q hotQuery, args ...any) *sql.Row {
	if st := h.stmt(ctx, q); st != nil {
		return st.QueryRowContext(ctx, args...)
	}
	return h.run.QueryRowContext(ctx, q.sql, args...)
}

// hotRead is the read pool, for hot queries.
func (s *Store) hotRead() hotConn { return hotConn{cache: s.rstmts, run: s.read} }

// hotTx is a write transaction, for hot queries.
func (s *Store) hotTx(tx *sql.Tx) hotConn { return hotConn{cache: s.wstmts, run: tx, tx: tx} }

// execHot is exec for a hot query: it takes the writer, runs the statement as
// its own transaction and lets the writer go.
func (s *Store) execHot(ctx context.Context, q hotQuery, args ...any) (sql.Result, error) {
	if s.readOnly {
		return nil, ErrReadOnly
	}
	defer s.lockWriter()()
	return hotConn{cache: s.wstmts, run: s.write}.Exec(ctx, q, args...)
}

package store

import (
	"context"
	"database/sql"
	"fmt"
	"path/filepath"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

// A hot query is a statement the store prepares once and runs from that
// preparation: the driver parses whatever it is handed every time it is handed
// it, and that parsing was a third of a webhook delivery. These hold the
// mechanism to what it promises (parsed once, the same answers as the text,
// never a deadlock on the writer's one connection), and hold each statement that
// has been made hot to being run as one.

// The queries the mechanism's tests run. Registered as any hot query is, at
// initialisation, before a store is opened.
var (
	hotTestSum      = hot(`SELECT ?1 + ?2`)
	hotTestList     = hot(`SELECT column1 FROM (VALUES (1),(2),(3),(4),(5)) WHERE column1 > ?1 ORDER BY column1`)
	hotTestInsert   = hot(`INSERT INTO usage_capacity_samples(pool_id,at,blocked) VALUES (?,?,0)`)
	hotTestCount    = hot(`SELECT COUNT(*) FROM usage_capacity_samples`)
	hotTestNoTable  = hot(`SELECT id FROM a_table_that_does_not_exist WHERE id = ?`)
	hotTestBadWrite = hot(`INSERT INTO a_table_that_does_not_exist(id) VALUES (?)`)
)

func TestAHotQueryAnswersAsItsTextDoes(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()

	for _, a := range [][2]int{{1, 2}, {40, 2}, {-5, 5}} {
		var hotSum, textSum int
		if err := s.hotRead().QueryRow(ctx, hotTestSum, a[0], a[1]).Scan(&hotSum); err != nil {
			t.Fatalf("hot sum: %v", err)
		}
		if err := s.read.QueryRowContext(ctx, hotTestSum.sql, a[0], a[1]).Scan(&textSum); err != nil {
			t.Fatalf("text sum: %v", err)
		}
		if hotSum != textSum {
			t.Errorf("%d + %d: the hot query says %d, its text %d", a[0], a[1], hotSum, textSum)
		}
	}

	list := func(rows *sql.Rows, err error) string {
		t.Helper()
		if err != nil {
			t.Fatalf("list: %v", err)
		}
		defer rows.Close()
		var out []string
		for rows.Next() {
			var n int
			if err := rows.Scan(&n); err != nil {
				t.Fatalf("scan: %v", err)
			}
			out = append(out, fmt.Sprint(n))
		}
		if err := rows.Err(); err != nil {
			t.Fatalf("rows: %v", err)
		}
		return strings.Join(out, ",")
	}
	for _, from := range []int{0, 2, 4, 9} {
		hotList := list(s.hotRead().Query(ctx, hotTestList, from))
		textList := list(s.read.QueryContext(ctx, hotTestList.sql, from))
		if hotList != textList {
			t.Errorf("above %d: the hot query lists %q, its text %q", from, hotList, textList)
		}
	}
}

func TestAHotQueryIsPreparedOncePerPoolAndRunFromThatPreparation(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()

	missesBefore := s.rstmts.misses.Load()
	var n int
	for i := range 50 {
		if err := s.hotRead().QueryRow(ctx, hotTestSum, i, 1).Scan(&n); err != nil || n != i+1 {
			t.Fatalf("run %d: %d, %v", i, n, err)
		}
	}
	if got := s.rstmts.misses.Load() - missesBefore; got != 1 {
		t.Errorf("50 runs of a hot query ran it without a prepared statement %d times, want 1: the first", got)
	}
	first := s.rstmts.slots[hotTestSum.id].Load()
	if first == nil {
		t.Fatal("the hot query has no prepared statement after being run")
	}
	if err := s.hotRead().QueryRow(ctx, hotTestSum, 1, 1).Scan(&n); err != nil {
		t.Fatalf("run: %v", err)
	}
	if again := s.rstmts.slots[hotTestSum.id].Load(); again != first {
		t.Error("the prepared statement was replaced by a later run")
	}
	if s.wstmts.slots[hotTestSum.id].Load() != nil {
		t.Error("a statement run on the read pool was prepared on the writer too")
	}
}

func TestAHotWriteIsPreparedOnceAndTakesTheWriterEachTime(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	var writes atomic.Int32
	s.ObserveWrites(func(_, _ time.Duration) { writes.Add(1) })

	missesBefore := s.wstmts.misses.Load()
	for i := range 20 {
		if _, err := s.execHot(ctx, hotTestInsert, fmt.Sprintf("pool_%02d", i), int64(i)); err != nil {
			t.Fatalf("execHot %d: %v", i, err)
		}
	}
	if got := s.wstmts.misses.Load() - missesBefore; got != 1 {
		t.Errorf("20 hot writes ran without a prepared statement %d times, want 1", got)
	}
	if got := writes.Load(); got != 20 {
		t.Errorf("20 hot writes took the writer %d times, want 20: each is a write of its own", got)
	}
	var n int
	if err := s.hotRead().QueryRow(ctx, hotTestCount).Scan(&n); err != nil || n != 20 {
		t.Errorf("the writes left %d rows, err = %v; want 20", n, err)
	}
}

func TestAHotWriteOnAReadOnlyStoreIsRefused(t *testing.T) {
	ctx := context.Background()
	path := filepath.Join(t.TempDir(), "zoomies.db")
	rw, err := Open(ctx, Options{Path: path})
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	rw.Close()
	ro, err := Open(ctx, Options{Path: path, ReadOnly: true})
	if err != nil {
		t.Fatalf("Open read-only: %v", err)
	}
	defer ro.Close()

	if _, err := ro.execHot(ctx, hotTestInsert, "pool_a", 1); err != ErrReadOnly {
		t.Errorf("execHot on a read-only store = %v, want ErrReadOnly", err)
	}
	var n int
	if err := ro.hotRead().QueryRow(ctx, hotTestCount).Scan(&n); err != nil || n != 0 {
		t.Errorf("a hot read on a read-only store = %d, %v; want 0 and no error", n, err)
	}
}

// The writer's one connection is held by a transaction for as long as it lasts,
// so a statement first run in one cannot be prepared there: asking the pool for a
// connection would wait for the transaction, which is waiting for the statement.
// It runs as its text that once, and is prepared the next time the writer is
// taken outside a transaction.
func TestAHotQueryFirstRunInATransactionRunsAsItsTextAndIsPreparedAtTheNextEntry(t *testing.T) {
	s := newTestStore(t)
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()

	insert := func(pool string) {
		t.Helper()
		err := s.tx(ctx, func(tx *sql.Tx) error {
			_, err := s.hotTx(tx).Exec(ctx, hotTestInsert, pool, 1)
			return err
		})
		if err != nil {
			t.Fatalf("a hot write in a transaction: %v", err)
		}
	}

	insert("pool_a")
	if s.wstmts.slots[hotTestInsert.id].Load() != nil {
		t.Error("the statement was prepared while the transaction held the writer's connection")
	}
	missesAfterFirst := s.wstmts.misses.Load()

	// Any entry to the writer prepares what was asked for in the one before.
	if err := s.tx(ctx, func(*sql.Tx) error { return nil }); err != nil {
		t.Fatalf("an empty transaction: %v", err)
	}
	if s.wstmts.slots[hotTestInsert.id].Load() == nil {
		t.Fatal("the statement was not prepared when the writer was next taken")
	}

	insert("pool_b")
	insert("pool_c")
	if got := s.wstmts.misses.Load(); got != missesAfterFirst {
		t.Errorf("runs after the statement was prepared still missed: %d, was %d", got, missesAfterFirst)
	}
	var n int
	if err := s.hotRead().QueryRow(ctx, hotTestCount).Scan(&n); err != nil || n != 3 {
		t.Errorf("the writes left %d rows, err = %v; want 3", n, err)
	}
}

// A statement the database will not prepare is run as its text, which fails as
// the text fails, with the error that says why, wherever it is run. Nothing about
// the failure is remembered: the statement is tried again, and the writer is not
// left held.
func TestAHotQueryThatCannotBePreparedFailsAsItsTextDoes(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()

	for range 3 {
		var id string
		err := s.hotRead().QueryRow(ctx, hotTestNoTable, "x").Scan(&id)
		if err == nil || !strings.Contains(err.Error(), "no such table") {
			t.Fatalf("a hot read of a missing table = %v, want no such table", err)
		}
		if _, err := s.execHot(ctx, hotTestBadWrite, "x"); err == nil || !strings.Contains(err.Error(), "no such table") {
			t.Fatalf("a hot write to a missing table = %v, want no such table", err)
		}
		err = s.tx(ctx, func(tx *sql.Tx) error {
			_, err := s.hotTx(tx).Exec(ctx, hotTestBadWrite, "x")
			return err
		})
		if err == nil || !strings.Contains(err.Error(), "no such table") {
			t.Fatalf("a hot write to a missing table in a transaction = %v, want no such table", err)
		}
	}
	if s.rstmts.slots[hotTestNoTable.id].Load() != nil || s.wstmts.slots[hotTestBadWrite.id].Load() != nil {
		t.Error("a statement that failed to prepare has a prepared statement")
	}
	// And the store is as usable as it was.
	var n int
	if err := s.hotRead().QueryRow(ctx, hotTestSum, 2, 2).Scan(&n); err != nil || n != 4 {
		t.Errorf("a hot read afterwards = %d, %v", n, err)
	}
	if _, err := s.execHot(ctx, hotTestInsert, "pool_a", 1); err != nil {
		t.Errorf("a hot write afterwards: %v", err)
	}
}

// A query registered after a store was opened has no slot in it, and runs as its
// text. Registration is meant to be done at initialisation; this is what a
// mistake costs.
func TestAHotQueryRegisteredAfterTheStoreWasOpenedRunsAsItsText(t *testing.T) {
	s := newTestStore(t)
	late := hot(`SELECT 7`)
	var n int
	for range 2 {
		if err := s.hotRead().QueryRow(context.Background(), late).Scan(&n); err != nil || n != 7 {
			t.Fatalf("a late hot query = %d, %v; want 7", n, err)
		}
	}
}

// A prepared statement is shared by everything that runs the query, on every
// connection of the pool: under the race detector, many goroutines running the
// same ones against a database in a file, whose read pool has several
// connections, while others write.
func TestHotQueriesAreRunByManyGoroutinesAtOnce(t *testing.T) {
	ctx := context.Background()
	s, err := Open(ctx, Options{Path: filepath.Join(t.TempDir(), "zoomies.db")})
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	defer s.Close()

	var wg sync.WaitGroup
	var failures atomic.Int32
	fail := func(format string, args ...any) {
		failures.Add(1)
		t.Errorf(format, args...)
	}
	for g := range 8 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range 200 {
				var n int
				if err := s.hotRead().QueryRow(ctx, hotTestSum, g, i).Scan(&n); err != nil || n != g+i {
					fail("reader %d run %d: %d, %v", g, i, n, err)
					return
				}
				rows, err := s.hotRead().Query(ctx, hotTestList, 1)
				if err != nil {
					fail("reader %d run %d: %v", g, i, err)
					return
				}
				count := 0
				for rows.Next() {
					count++
				}
				rows.Close()
				if count != 4 {
					fail("reader %d run %d listed %d rows, want 4", g, i, count)
					return
				}
			}
		}()
	}
	for g := range 3 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range 100 {
				pool := fmt.Sprintf("pool_%d_%03d", g, i)
				if i%2 == 0 {
					if _, err := s.execHot(ctx, hotTestInsert, pool, int64(i)); err != nil {
						fail("writer %d run %d: %v", g, i, err)
						return
					}
					continue
				}
				err := s.tx(ctx, func(tx *sql.Tx) error {
					_, err := s.hotTx(tx).Exec(ctx, hotTestInsert, pool, int64(i))
					return err
				})
				if err != nil {
					fail("writer %d run %d in a transaction: %v", g, i, err)
					return
				}
			}
		}()
	}
	wg.Wait()
	if failures.Load() > 0 {
		return
	}
	var n int
	if err := s.hotRead().QueryRow(ctx, hotTestCount).Scan(&n); err != nil || n != 300 {
		t.Errorf("the writers left %d rows, err = %v; want 300", n, err)
	}
}

func TestClosingAStoreReleasesItsPreparedStatements(t *testing.T) {
	s, err := Open(context.Background(), Options{Path: ":memory:"})
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	var n int
	if err := s.hotRead().QueryRow(context.Background(), hotTestSum, 1, 1).Scan(&n); err != nil {
		t.Fatalf("run: %v", err)
	}
	st := s.rstmts.slots[hotTestSum.id].Load()
	if st == nil {
		t.Fatal("no prepared statement to release")
	}
	if err := s.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}
	if s.rstmts.slots[hotTestSum.id].Load() != nil {
		t.Error("Close left the prepared statement in its slot")
	}
	if err := st.QueryRowContext(context.Background(), 1, 1).Scan(&n); err == nil {
		t.Error("the prepared statement still runs after the store was closed")
	}
}

// Making a statement hot only helps if the code that runs it asks for the hot
// query, and nothing fails when it does not. Each method that runs statements
// made hot is run until it is warm, and then once more: the once more must run
// exactly the statements it is expected to as prepared ones, and none without.
func TestEveryStatementMadeHotIsRunAsAHotQuery(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	inst, pool, host := seedPool(t, s)

	newJob := func(id int64) *Job {
		return &Job{GitHubJobID: id, GitHubRunID: 77, Repo: "acme/widgets", Workflow: "CI", JobName: "build",
			Labels: StringSlice{"self-hosted"}, State: JobQueued, InstallationID: inst.ID, PoolID: pool.ID, Matched: true,
			QueuedAt: time.Now()}
	}
	known, _, err := s.ApplyJob(ctx, newJob(1))
	if err != nil {
		t.Fatalf("ApplyJob: %v", err)
	}
	must := func(err error) {
		t.Helper()
		if err != nil {
			t.Fatal(err)
		}
	}
	runner := &Runner{PoolID: pool.ID, HostID: host.ID, Name: "zoomies-hot-1", State: RunnerProvisioning, Ephemeral: true}
	must(s.CreateRunner(ctx, runner))

	for _, op := range []struct {
		name string
		hot  int // the statements the method runs as hot queries
		run  func(n int)
	}{
		{"ApplyJob of a job it has not seen", 2, func(n int) {
			_, _, err := s.ApplyJob(ctx, newJob(int64(1000+n)))
			must(err)
		}},
		// A delivery that says something new reads the row and writes it back. One
		// that does not only reads it: the write is skipped (see ApplyJob).
		{"ApplyJob of a job it knows, with news each time", 2, func(n int) {
			j := newJob(1)
			j.RunAttempt = 2 + n
			_, _, err := s.ApplyJob(ctx, j)
			must(err)
		}},
		{"ApplyJob of a job it knows, with nothing new", 1, func(int) {
			_, _, err := s.ApplyJob(ctx, newJob(1))
			must(err)
		}},
		{"StampJobVersions", 2, func(int) {
			_, err := s.StampJobVersions(ctx, known.ID, JobVersions{ControllerVersion: "v1"})
			must(err)
		}},
		{"StampJobGranted", 1, func(int) {
			_, err := s.StampJobGranted(ctx, known.ID, 2, 2048, "pool")
			must(err)
		}},
		{"SetJobRunnerFault", 1, func(int) {
			_, _, err := s.SetJobRunnerFault(ctx, known.ID, "gone", FaultRunnerExited)
			must(err)
		}},
		{"AppendJobEvent", 1, func(int) {
			must(s.AppendJobEvent(ctx, &JobEvent{JobID: known.ID, Kind: JobEventQueued, Source: "test"}))
		}},
		{"RecordDelivery", 1, func(n int) {
			must(s.RecordDelivery(ctx, &WebhookDelivery{DeliveryID: fmt.Sprintf("d-%d", n), Event: "workflow_job", Status: "accepted"}))
		}},
		{"QueueEnrichment", 1, func(n int) {
			must(s.QueueEnrichment(ctx, "run", fmt.Sprintf("acme/widgets#%d", n)))
		}},
		{"GetPool", 1, func(int) {
			_, err := s.GetPool(ctx, pool.ID)
			must(err)
		}},
		{"ListPoolsForClaim", 1, func(int) {
			_, err := s.ListPoolsForClaim(ctx)
			must(err)
		}},
		{"FindInstallationByTarget", 1, func(int) {
			_, err := s.FindInstallationByTarget(ctx, "acme/widgets")
			must(err)
		}},
		{"RunNumberForRun", 1, func(int) {
			if _, err := s.RunNumberForRun(ctx, 77); err != nil && err != ErrNotFound {
				t.Fatal(err)
			}
		}},
		{"EliRepairPolicies", 1, func(int) {
			_, err := s.EliRepairPolicies(ctx)
			must(err)
		}},
		// What a reconcile pass reads. ListHosts' third query, the acceptances of
		// the hosts it found, is built around their ids and is not hot.
		{"ListPools", 1, func(int) {
			_, err := s.ListPools(ctx)
			must(err)
		}},
		// The hosts, the runners on them and, for the acceptances of the hosts it
		// has read, one statement whether there is one host or many.
		{"ListHosts", 3, func(int) {
			_, err := s.ListHosts(ctx)
			must(err)
		}},
		{"GetHost", 2, func(int) {
			_, err := s.GetHost(ctx, host.ID)
			must(err)
		}},
		{"GetRunner", 1, func(int) {
			_, err := s.GetRunner(ctx, runner.ID)
			must(err)
		}},
		// With no state named it is the list a heartbeat reads; with some, it is built
		// around them and is not hot.
		{"ListRunnersForHost", 1, func(int) {
			_, err := s.ListRunnersForHost(ctx, host.ID)
			must(err)
		}},
		{"ListRunnersForHost naming states", 0, func(int) {
			_, err := s.ListRunnersForHost(ctx, host.ID, RunnerIdle, RunnerBusy)
			must(err)
		}},
		{"RecordUsageCapacityBatch of a hundred pools", 1, func(int) {
			batch := make([]UsageCapacitySample, 100)
			for i := range batch {
				batch[i] = UsageCapacitySample{PoolID: fmt.Sprintf("pool_%03d", i), At: time.Now(), Blocked: i%9 == 0}
			}
			must(s.RecordUsageCapacityBatch(ctx, batch))
		}},
		{"ListInstallations", 1, func(int) {
			_, err := s.ListInstallations(ctx)
			must(err)
		}},
		{"ListQueuedJobs", 1, func(int) {
			_, err := s.ListQueuedJobs(ctx)
			must(err)
		}},
		{"SchedulingRunners", 1, func(int) {
			_, err := s.SchedulingRunners(ctx)
			must(err)
		}},
		{"PendingHostCleanup", 1, func(int) {
			_, err := s.PendingHostCleanup(ctx, "", 10, time.Now())
			must(err)
		}},
		{"LastProvisioned", 1, func(int) {
			_, err := s.LastProvisioned(ctx)
			must(err)
		}},
		{"RepositoryJobCounts", 1, func(int) {
			_, _, err := s.RepositoryJobCounts(ctx)
			must(err)
		}},
		{"RunnersWithAJob", 1, func(int) {
			_, err := s.RunnersWithAJob(ctx)
			must(err)
		}},
	} {
		t.Run(op.name, func(t *testing.T) {
			// Twice to warm up: a statement first run in a transaction is prepared
			// at the next entry to the writer, which the second run makes.
			op.run(10)
			op.run(11)
			hits := s.rstmts.hits.Load() + s.wstmts.hits.Load()
			misses := s.rstmts.misses.Load() + s.wstmts.misses.Load()
			op.run(12)
			if got := s.rstmts.hits.Load() + s.wstmts.hits.Load() - hits; got != int64(op.hot) {
				t.Errorf("ran %d statements as hot queries, want %d: the code that runs the others does not ask for the hot query", got, op.hot)
			}
			if got := s.rstmts.misses.Load() + s.wstmts.misses.Load() - misses; got != 0 {
				t.Errorf("ran %d statements without a prepared statement once warm, want none", got)
			}
		})
	}
}

