func TestAttentionFollowsNewRunsWithoutCrossingBranchesOrJobs(t *testing.T) {
	for _, tc := range []struct {
		name, branch, workflow, job, conclusion string
		wantOld                                 bool
	}{
		{"fixed on new commit", "feature", "CI", "Test", "success", false},
		{"new failure replaces old", "feature", "CI", "Test", "failure", false},
		{"cancelled is not a fix", "feature", "CI", "Test", "cancelled", true},
		{"skipped is not a fix", "feature", "CI", "Test", "skipped", true},
		{"neutral is not a fix", "feature", "CI", "Test", "neutral", true},
		{"newer run in progress", "feature", "CI", "Test", "", false},
		{"other branch", "other", "CI", "Test", "success", true},
		{"other workflow", "feature", "Deploy", "Test", "success", true},
		{"other matrix job", "feature", "CI", "Test (arm)", "success", true},
		{"missing branch", "", "CI", "Test", "success", true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			now := time.Now().UTC()
			s := newTestStoreAt(t, func() time.Time { return now })
			ctx := context.Background()
			old := &Job{GitHubJobID: 1, GitHubRunID: 1, Repo: "acme/repo", Workflow: "CI", JobName: "Test", HeadBranch: "feature", State: JobCompleted, Conclusion: "failure", QueuedAt: now.Add(-time.Hour)}
			if _, err := s.UpsertJob(ctx, old); err != nil {
				t.Fatal(err)
			}
			later := &Job{GitHubJobID: 2, GitHubRunID: 2, Repo: "acme/repo", Workflow: tc.workflow, JobName: tc.job, HeadBranch: tc.branch, State: JobCompleted, Conclusion: tc.conclusion, QueuedAt: now.Add(-time.Minute)}
			if tc.conclusion == "" {
				later.State = JobInProgress
			}
			if _, err := s.UpsertJob(ctx, later); err != nil {
				t.Fatal(err)
			}
			rows, _, err := s.ListJobs(ctx, JobFilter{AttentionOnly: true}, Page{})
			if err != nil {
				t.Fatal(err)
			}
			found := false
			for _, row := range rows {
				if row.GitHubJobID == 1 {
					found = true
				}
			}
			if found != tc.wantOld {
				t.Fatalf("old failure visible = %v, want %v", found, tc.wantOld)
			}
		})
	}
}

func TestGitHubAttentionObservationsDoNotAcknowledgeOrHideNewFailures(t *testing.T) {
	now := time.Now().UTC().Truncate(time.Millisecond)
	s := newTestStoreAt(t, func() time.Time { return now })
	ctx := context.Background()
	completed := now.Add(-time.Minute)
	job := &Job{GitHubJobID: 1, GitHubRunID: 1, Repo: "acme/repo", State: JobCompleted, Conclusion: "failure", QueuedAt: now.Add(-time.Hour), CompletedAt: &completed}
	if _, err := s.UpsertJob(ctx, job); err != nil {
		t.Fatal(err)
	}
	assertCount := func(want int) {
		t.Helper()
		_, n, err := s.ListJobs(ctx, JobFilter{AttentionOnly: true}, Page{})
		if err != nil || n != want {
			t.Fatalf("attention count = %d, error %v; want %d", n, err, want)
		}
	}
	assertCount(1)
	for _, reason := range []string{"closed", "superseded", "fixed"} {
		if err := s.RecordJobAttentionRun(ctx, job.Repo, 1, reason, now, true); err != nil {
			t.Fatal(err)
		}
		assertCount(0)
	}
	// A reopened PR becomes actionable without undoing a person's triage.
	if err := s.RecordJobAttentionRun(ctx, job.Repo, 1, "", now, true); err != nil {
		t.Fatal(err)
	}
	assertCount(1)
	if err := s.RecordJobAttentionRun(ctx, job.Repo, 1, "fixed", now, true); err != nil {
		t.Fatal(err)
	}
	now = now.Add(time.Minute)
	completed = now
	fresh := &Job{GitHubJobID: 2, GitHubRunID: 1, Repo: job.Repo, State: JobCompleted, Conclusion: "failure", QueuedAt: now, CompletedAt: &completed}
	if _, err := s.UpsertJob(ctx, fresh); err != nil {
		t.Fatal(err)
	}
	assertCount(1)
	// A network failure must not advance the evidence timestamp and apply an
	// old success to a failure that arrived after it.
	if err := s.RecordJobAttentionRun(ctx, job.Repo, 1, "", now, false); err != nil {
		t.Fatal(err)
	}
	assertCount(1)
	all, total, err := s.ListJobs(ctx, JobFilter{FailedOnly: true}, Page{})
	if err != nil || total != 2 {
		t.Fatalf("history = %d, %v", total, err)
	}
	for _, row := range all {
		if row.AcknowledgedAt != nil {
			t.Fatal("GitHub observation forged an acknowledgement")
		}
	}
	if err := s.PruneJobAttentionRuns(ctx); err != nil {
		t.Fatal(err)
	}
}

// legacyUnreplacedJobSQL is the replacement test as it was first written: one
// NOT EXISTS with the two kinds of later job joined by an OR. It is kept here,
// and only here, as the definition the split into two has to agree with. The
// arguments leave out one half or the other, so a test can tell that a fixture
// really contains both kinds.
func legacyUnreplacedJobSQL(laterAttempt, laterRun bool) string {
	var kinds []string
	if laterAttempt {
		kinds = append(kinds, `(later.github_run_id = jobs.github_run_id AND later.github_run_id != 0
				AND later.run_attempt > jobs.run_attempt)`)
	}
	if laterRun {
		kinds = append(kinds, `(jobs.github_run_id != 0 AND later.github_run_id != 0
				AND jobs.head_branch != '' AND jobs.workflow != ''
				AND later.head_branch = jobs.head_branch AND later.workflow = jobs.workflow
				AND later.github_run_id != jobs.github_run_id
				AND later.queued_at > jobs.queued_at)`)
	}
	return `NOT EXISTS (
		SELECT 1 FROM jobs later
		WHERE later.repo = jobs.repo AND later.job_name = jobs.job_name
			AND (later.state != 'completed' OR later.conclusion NOT IN ('cancelled','skipped','neutral')
				OR later.runner_fault != '' OR later.fault_kind != '')
			AND (` + strings.Join(kinds, " OR ") + `))`
}

// The replacement test was split in two so that SQLite can find a later
// attempt through the run and a later run through the branch. NOT EXISTS (A OR
// B) is NOT EXISTS (A) AND NOT EXISTS (B) on paper; this holds the SQL to it,
// on a small pseudo-random fleet whose few repositories, runs, branches and
// workflows collide constantly, so every combination of the two kinds of later
// job, the guards on missing metadata and the jobs that do not count as a
// replacement turn up many times over.
func TestSplittingTheReplacementTestKeepsTheSameJobs(t *testing.T) {
	now := time.Now().UTC().Truncate(time.Millisecond)
	s := newTestStoreAt(t, func() time.Time { return now })
	ctx := context.Background()
	rng := rand.New(rand.NewPCG(7, 11))
	pick := func(from ...string) string { return from[rng.IntN(len(from))] }
	for i := 1; i <= 600; i++ {
		state, conclusion := "completed", pick("success", "failure", "failure", "cancelled", "skipped", "neutral", "timed_out")
		if rng.IntN(8) == 0 {
			state, conclusion = pick("queued", "in_progress", "waiting"), ""
		}
		fault, kind := "", ""
		if rng.IntN(10) == 0 {
			fault, kind = "runner exited with code 137", "out_of_memory"
		}
		_, err := s.write.ExecContext(ctx, `INSERT INTO jobs
			(id, github_job_id, github_run_id, repo, workflow, job_name, head_branch, run_attempt,
			 state, conclusion, runner_fault, fault_kind, queued_at)
			VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)`,
			fmt.Sprintf("job_%d", i), i, rng.IntN(6), pick("acme/a", "acme/b"), pick("", "CI", "CI", "Deploy"),
			pick("Test", "Lint"), pick("", "main", "main", "feature"), rng.IntN(4), state, conclusion, fault, kind,
			ms(now.Add(-time.Duration(rng.IntN(12))*time.Minute)))
		if err != nil {
			t.Fatalf("seeding job %d: %v", i, err)
		}
	}
	unreplaced := func(test string) []int64 {
		t.Helper()
		rows, err := s.read.QueryContext(ctx, `SELECT github_job_id FROM jobs WHERE `+test+` ORDER BY github_job_id`)
		if err != nil {
			t.Fatalf("%v in %s", err, test)
		}
		defer rows.Close()
		var ids []int64
		for rows.Next() {
			var id int64
			if err := rows.Scan(&id); err != nil {
				t.Fatal(err)
			}
			ids = append(ids, id)
		}
		return ids
	}

	single, split := unreplaced(legacyUnreplacedJobSQL(true, true)), unreplaced(unreplacedJobSQL())
	if !slices.Equal(single, split) {
		t.Fatalf("splitting the replacement test changed which jobs are unreplaced: %d before, %d after", len(single), len(split))
	}
	// A fixture in which only one kind of later job ever mattered would pass
	// the comparison above whatever the second half did.
	byAttempt, byRun := unreplaced(legacyUnreplacedJobSQL(true, false)), unreplaced(legacyUnreplacedJobSQL(false, true))
	if len(single) == 0 || len(byAttempt) <= len(single) || len(byRun) <= len(single) {
		t.Fatalf("the fixture does not need both kinds of later job: %d unreplaced, %d if only a later attempt replaced, %d if only a later run did",
			len(single), len(byAttempt), len(byRun))
	}
}

// Every check of a run costs GitHub requests the runner registrations share the
// installation's quota with, and the loop makes a fixed number of checks an
// hour whenever enough runs are waiting, so what it spends them on matters. A
// run GitHub has settled (its PR closed, a newer commit, a passing re-run) is
// looked at again only in case that changes, and an hour is soon enough for a
// PR to be reopened; a run it has not settled, or has said nothing about, is
// the one a person is waiting on and keeps the short interval. A failure newer
// than the observation is not settled by it, so it is not made to wait either.
func TestSettledRunsAreCheckedAgainHourlyAndTheRestEveryFiveMinutes(t *testing.T) {
	start := time.Now().UTC().Truncate(time.Millisecond)
	clock := start
	s := newTestStoreAt(t, func() time.Time { return clock })
	ctx := context.Background()
	failure := func(id, run int64, completed time.Time) {
		t.Helper()
		job := &Job{GitHubJobID: id, GitHubRunID: run, Repo: "acme/repo", State: JobCompleted, Conclusion: "failure",
			QueuedAt: completed.Add(-time.Minute), CompletedAt: &completed}
		if _, err := s.UpsertJob(ctx, job); err != nil {
			t.Fatalf("UpsertJob: %v", err)
		}
	}
	earlier := start.Add(-10 * time.Minute)
	failure(1, 1, earlier) // closed
	failure(2, 2, earlier) // checked, still failing
	failure(3, 3, earlier) // fixed, and then a new failure
	failure(4, 4, earlier) // never checked
	for run, reason := range map[int64]string{1: "closed", 2: "", 3: "fixed"} {
		if err := s.RecordJobAttentionRun(ctx, "acme/repo", run, reason, start, true); err != nil {
			t.Fatalf("RecordJobAttentionRun: %v", err)
		}
	}
	failure(5, 3, start.Add(30*time.Second))

	dueAt := func(after time.Duration) []int64 {
		t.Helper()
		clock = start.Add(after)
		runs, err := s.JobAttentionRunsToCheck(ctx, 10)
		if err != nil {
			t.Fatalf("JobAttentionRunsToCheck: %v", err)
		}
		var ids []int64
		for _, r := range runs {
			ids = append(ids, r.RunID)
		}
		slices.Sort(ids)
		return ids
	}
	if got := dueAt(time.Minute); !slices.Equal(got, []int64{4}) {
		t.Fatalf("a minute later the runs due are %v, want only the one never checked", got)
	}
	if got := dueAt(6 * time.Minute); !slices.Equal(got, []int64{2, 3, 4}) {
		t.Fatalf("six minutes later the runs due are %v, want every run but the closed one", got)
	}
	if got := dueAt(59 * time.Minute); !slices.Equal(got, []int64{2, 3, 4}) {
		t.Fatalf("just under an hour later the runs due are %v, want the closed run still left alone", got)
	}
	if got := dueAt(61 * time.Minute); !slices.Equal(got, []int64{1, 2, 3, 4}) {
		t.Fatalf("an hour later the runs due are %v, want the closed run looked at again", got)
	}
}

package store

import (
	"context"
	"fmt"
	"strings"
	"testing"
	"time"
)

// pageKind is what became of a job, for the jobs a fleet's history is made of.
type pageKind int

const (
	pageManagedOK        pageKind = iota // ran on this fleet and passed
	pageManagedFailed                    // ran on this fleet and its workflow failed
	pageManagedCancelled                 // ran on this fleet and somebody stopped it
	pageFleetFault                       // its runner stopped under it
	pageHostedOK                         // somebody else's runner, passed
	pageHostedFailed                     // somebody else's runner, failed
)

// pageCycle is how a run of twenty jobs divides: three in five ran here and
// passed, and the rest are the other five kinds, so that a fifth of a history is
// somebody else's jobs, which is what an organisation that also uses hosted
// runners has.
var pageCycle = [20]pageKind{
	pageManagedOK, pageManagedOK, pageManagedOK, pageManagedOK, pageManagedOK, pageManagedOK,
	pageManagedOK, pageManagedOK, pageManagedOK, pageManagedOK, pageManagedOK, pageManagedOK,
	pageManagedFailed, pageManagedCancelled, pageFleetFault,
	pageHostedOK, pageHostedOK, pageHostedOK, pageHostedOK, pageHostedFailed,
}

// pageLive is how many of the newest jobs are still in hand: a quarter of them
// running, a quarter queued for a pool, a quarter queued with a label no pool
// claims, and a quarter queued for somebody else's runner, except that one of
// those is held by GitHub for a review instead.
const pageLive = 12

// pageWant is what each view of the Jobs page should say of a history, counted
// from what was written and not asked of the store, so that the benchmark is
// checked against something other than the statement it times.
type pageWant struct {
	running, queued, failed, finished, all, attention, lastDay, search int
}

// pageHistory puts n jobs in the store over the last seven days, oldest first as
// they arrive, and says what the views of the page should find. Every job is on a
// branch of its own, so that no failure has been replaced by a later one and the
// attention view is a question about the failures alone. It returns the jobs as
// the store kept them, for a test that wants to count them another way.
func pageHistory(tb testing.TB, s *Store, now time.Time, n int) ([]*Job, pageWant) {
	tb.Helper()
	ctx := context.Background()
	spacing := (7 * 24 * time.Hour / time.Duration(n)).Truncate(time.Millisecond)
	var want pageWant
	var written []*Job
	for i := n - 1; i >= 0; i-- {
		queued := now.Add(-time.Duration(i+1) * spacing)
		started := queued.Add(20 * time.Second)
		j := &Job{
			GitHubJobID: int64(5000 + i), GitHubRunID: int64(900000 + i/3),
			Repo: fmt.Sprintf("acme/svc-%d", i%5), Workflow: []string{"CI", "Release", "Nightly", "Docs"}[i%4],
			JobName: fmt.Sprintf("build-%d", i%5), HeadBranch: fmt.Sprintf("feature/%d", i), HeadSHA: fmt.Sprintf("%040x", i),
			RunAttempt: 1, QueuedAt: queued, StartedAt: &started,
		}
		managed, failed := false, false
		switch {
		case i < pageLive:
			switch i % 4 {
			case 0: // running here
				j.State, j.Matched, j.PoolID, j.RunnerID, j.RunnerName = JobInProgress, true, "pool_0", "run_live", "zoomies-live"
				j.Labels = StringSlice{"self-hosted", "zoomies-linux-x64"}
				managed = true
				want.running++
			case 1: // queued for a pool
				j.State, j.Matched, j.PoolID, j.StartedAt = JobQueued, true, "pool_0", nil
				j.Labels = StringSlice{"self-hosted", "zoomies-linux-x64"}
				managed = true
				want.queued++
			case 2: // queued with a label no pool claims
				j.State, j.StartedAt = JobQueued, nil
				j.Labels = StringSlice{"self-hosted", "gpu"}
				managed = true
				want.queued++
			default:
				if i == 7 { // held by GitHub for a deployment review
					j.State, j.Matched, j.PoolID, j.StartedAt = JobWaiting, true, "pool_0", nil
					j.Labels = StringSlice{"self-hosted", "zoomies-linux-x64"}
					managed = true
					break
				}
				// queued for somebody else's runner
				j.State, j.StartedAt = JobQueued, nil
				j.Labels = StringSlice{"ubuntu-latest"}
			}
		default:
			done := started.Add(time.Duration(30+i%90) * time.Second)
			j.State, j.CompletedAt = JobCompleted, &done
			j.Steps = pageSteps(started, done)
			switch kind := pageCycle[i%len(pageCycle)]; kind {
			case pageManagedOK, pageManagedFailed, pageManagedCancelled, pageFleetFault:
				j.Matched, j.PoolID = true, fmt.Sprintf("pool_%d", i%8)
				j.RunnerID, j.RunnerName = fmt.Sprintf("run_%d", i%40), fmt.Sprintf("zoomies-%d", i%40)
				j.Labels = StringSlice{"self-hosted", "zoomies-linux-x64"}
				managed = true
				switch kind {
				case pageManagedOK:
					j.Conclusion = "success"
				case pageManagedFailed:
					j.Conclusion, failed = "failure", true
				case pageManagedCancelled:
					j.Conclusion = "cancelled"
				case pageFleetFault:
					j.Conclusion, j.RunnerFault, j.FaultKind, failed = "failure", "the runner stopped under the job", FaultHostLost, true
				}
			case pageHostedOK:
				j.Conclusion, j.Labels = "success", StringSlice{"ubuntu-latest"}
			case pageHostedFailed:
				j.Conclusion, j.Labels = "failure", StringSlice{"ubuntu-latest"}
			}
		}
		kept, err := s.UpsertJob(ctx, j)
		if err != nil {
			tb.Fatalf("UpsertJob: %v", err)
		}
		written = append(written, kept)
		if !managed {
			continue
		}
		want.all++
		if j.JobName == "build-3" {
			want.search++
		}
		if j.State != JobCompleted {
			continue
		}
		want.finished++
		if !j.QueuedAt.Before(now.Add(-24 * time.Hour)) {
			want.lastDay++
		}
		if failed {
			want.failed++
			if !j.QueuedAt.Before(now.Add(-AttentionWindow)) {
				want.attention++
			}
		}
	}
	return written, want
}

// pageSteps are the steps a job on a pool's runner reports, which are most of
// what the Jobs page's rows weigh.
func pageSteps(started, done time.Time) JobSteps {
	names := []string{"Set up job", "Run actions/checkout", "Run ./.github/actions/setup-go", "Run the suite", "Post Run actions/checkout", "Complete job"}
	steps := make(JobSteps, len(names))
	step := done.Sub(started) / time.Duration(len(names))
	for i, name := range names {
		from := started.Add(time.Duration(i) * step)
		to := from.Add(step)
		steps[i] = JobStep{Number: i + 1, Name: name, Status: "completed", Conclusion: "success", StartedAt: &from, CompletedAt: &to}
	}
	return steps
}

// BenchmarkListJobs is the Jobs page: a page of jobs, and the count of every job
// the page's filters match, for each of the views an operator can ask for. The page
// is the first fifty of the default order, as the grid sends it, and every view
// is the filter the page writes for it, narrowed to the jobs this fleet had a hand
// in as the page does unless it is asked for the rest.
//
// What each view should find is counted while the history is written and checked
// before anything is timed, so that a view that matched nothing, or somebody
// else's jobs as well, is not timed under the name of the one that did not.
func BenchmarkListJobs(b *testing.B) {
	ctx := context.Background()
	for _, n := range []int{2000, 10000} {
		b.Run(fmt.Sprintf("jobs=%d", n), func(b *testing.B) {
			now := time.Now().Truncate(time.Millisecond)
			s := newTestStoreAt(b, func() time.Time { return now })
			_, want := pageHistory(b, s, now, n)
			notCancelling := false
			lastDay := now.Add(-24 * time.Hour)
			views := []struct {
				name   string
				filter JobFilter
				total  int
			}{
				{"running", JobFilter{ManagedOnly: true, States: []JobState{JobInProgress}, Cancelling: &notCancelling}, want.running},
				{"queued", JobFilter{ManagedOnly: true, States: []JobState{JobQueued}, Cancelling: &notCancelling}, want.queued},
				{"failed", JobFilter{ManagedOnly: true, FailedOnly: true}, want.failed},
				{"attention", JobFilter{ManagedOnly: true, AttentionOnly: true}, want.attention},
				{"finished", JobFilter{ManagedOnly: true, States: []JobState{JobCompleted}}, want.finished},
				{"finished_last_day", JobFilter{ManagedOnly: true, States: []JobState{JobCompleted}, Since: &lastDay}, want.lastDay},
				{"all", JobFilter{ManagedOnly: true, States: []JobState{JobWaiting, JobQueued, JobInProgress, JobCompleted}}, want.all},
				{"search", JobFilter{ManagedOnly: true, States: []JobState{JobWaiting, JobQueued, JobInProgress, JobCompleted}, Search: "build-3"}, want.search},
			}
			page := Page{Limit: 50, Desc: true}
			for _, v := range views {
				b.Run("view="+v.name, func(b *testing.B) {
					jobs, total, err := s.ListJobs(ctx, v.filter, page)
					if err != nil {
						b.Fatalf("ListJobs: %v", err)
					}
					if total != v.total || len(jobs) != min(v.total, page.Limit) {
						b.Fatalf("the %s view found %d jobs and returned %d; the history holds %d for it", v.name, total, len(jobs), v.total)
					}
					for i := 1; i < len(jobs); i++ {
						if jobs[i].QueuedAt.After(jobs[i-1].QueuedAt) {
							b.Fatalf("the %s view is not newest first", v.name)
						}
					}
					if v.name == "search" && !strings.Contains(jobs[0].JobName, "build-3") {
						b.Fatalf("the search view returned %q", jobs[0].JobName)
					}

					b.ReportAllocs()
					for b.Loop() {
						if _, _, err := s.ListJobs(ctx, v.filter, page); err != nil {
							b.Fatal(err)
						}
					}
				})
			}
		})
	}
}

package store

import (
	"context"
	"encoding/json"
	"slices"
	"testing"
	"time"
)

// GitHub delivers a job's events at least once, and the poller finds jobs the
// webhook already announced, so most of the deliveries a job gets after its
// first say nothing the row does not already hold. ApplyJob used to put the row
// back anyway, in a write transaction of its own: a third of a poller sweep over
// known jobs in memory, and on disk most of what a redelivery cost.
//
// These tests ask the database what it was given to write, not the store what it
// meant to write: a trigger on the jobs table counts the UPDATEs it receives.

// countJobUpdates puts a canary on the jobs table and returns a function that
// reads how many UPDATEs the table has received since the canary went in.
func countJobUpdates(t *testing.T, s *Store) func() int {
	t.Helper()
	ctx := context.Background()
	for _, q := range []string{
		`CREATE TABLE job_update_canary (n INTEGER)`,
		`CREATE TRIGGER job_update_canary_trigger AFTER UPDATE ON jobs BEGIN INSERT INTO job_update_canary VALUES (1); END`,
	} {
		if _, err := s.exec(ctx, q); err != nil {
			t.Fatalf("setting up the canary on the jobs table: %v", err)
		}
	}
	return func() int {
		t.Helper()
		var n int
		if err := s.read.QueryRowContext(ctx, `SELECT COUNT(*) FROM job_update_canary`).Scan(&n); err != nil {
			t.Fatalf("reading the canary on the jobs table: %v", err)
		}
		return n
	}
}

// jobWriteClock is a clock that moves a second on every reading, so that a
// moment the store stamps is never the one it stamped before.
func jobWriteClock() func() time.Time {
	now := time.Date(2025, 3, 4, 12, 0, 0, 0, time.UTC)
	return func() time.Time {
		now = now.Add(time.Second)
		return now
	}
}

func jobJSON(t *testing.T, j *Job) string {
	t.Helper()
	b, err := json.Marshal(j)
	if err != nil {
		t.Fatalf("encoding a job: %v", err)
	}
	return string(b)
}

func TestADeliveryThatSaysNothingNewDoesNotWriteTheJob(t *testing.T) {
	cases := []struct {
		name  string
		first func() *Job
		again func() *Job
	}{
		{"the same queued delivery again",
			func() *Job { return benchDelivery(1, JobQueued) },
			func() *Job { return benchDelivery(1, JobQueued) }},
		{"the same in_progress delivery again",
			func() *Job { return benchDelivery(1, JobInProgress) },
			func() *Job { return benchDelivery(1, JobInProgress) }},
		{"the same completed delivery again, steps and all",
			func() *Job { return benchDelivery(1, JobCompleted) },
			func() *Job { return benchDelivery(1, JobCompleted) }},
		{"labels in another case and order, which normalise to the stored set",
			func() *Job { return benchDelivery(1, JobQueued) },
			func() *Job {
				j := benchDelivery(1, JobQueued)
				j.Labels = StringSlice{"zoomies", "X64", "LINUX", "Self-Hosted"}
				return j
			}},
		{"a thinner view of the same job, as the poller sees it",
			func() *Job { return benchDelivery(1, JobQueued) },
			func() *Job {
				j := benchDelivery(1, JobQueued)
				j.Labels, j.HTMLURL, j.HeadBranch, j.HeadSHA, j.RunAttempt = nil, "", "", "", 0
				return j
			}},
		{"a queued delivery that arrives after the job completed",
			func() *Job { return benchDelivery(1, JobCompleted) },
			func() *Job { return benchDelivery(1, JobQueued) }},
		{"an in_progress delivery that arrives after the job completed, naming the runner it already has",
			func() *Job {
				j := benchDelivery(1, JobCompleted)
				j.RunnerID, j.RunnerName = "run_bench", "zoomies-bench"
				return j
			},
			func() *Job { return benchDelivery(1, JobInProgress) }},
		{"an in_progress delivery with no steps, after one that had them",
			func() *Job { return benchDelivery(1, JobInProgress) },
			func() *Job {
				j := benchDelivery(1, JobInProgress)
				j.Steps = nil
				return j
			}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			ctx := context.Background()
			s := newTestStoreAt(t, jobWriteClock())
			updates := countJobUpdates(t, s)

			first := tc.first()
			if _, _, err := s.ApplyJob(ctx, first); err != nil {
				t.Fatalf("the first delivery: %v", err)
			}
			stored, err := s.GetJobByGitHubID(ctx, 1)
			if err != nil {
				t.Fatalf("reading the job back: %v", err)
			}
			wrote := updates()

			got, change, err := s.ApplyJob(ctx, tc.again())
			if err != nil {
				t.Fatalf("the delivery that follows: %v", err)
			}

			if n := updates() - wrote; n != 0 {
				t.Errorf("the delivery ran %d UPDATEs of the jobs table; want none, it says nothing the row does not already hold", n)
			}
			// Not writing is not the same as not answering. The caller is told what
			// it always was: the job as it now stands, and that nothing moved.
			if change.Created || change.StateChanged || change.Claimed || change.RunnerLinked || change.PreviousState != stored.State {
				t.Errorf("change = %+v; want nothing moved, from %s", change, stored.State)
			}
			if a, b := jobJSON(t, got), jobJSON(t, stored); a != b {
				t.Errorf("the job returned is not the job stored\n got: %s\nwant: %s", a, b)
			}
			after, err := s.GetJobByGitHubID(ctx, 1)
			if err != nil {
				t.Fatalf("reading the job back: %v", err)
			}
			if a, b := jobJSON(t, after), jobJSON(t, stored); a != b {
				t.Errorf("the stored job moved though nothing was written\n got: %s\nwant: %s", a, b)
			}
		})
	}
}

// Skipping the write is only right when the write would have changed nothing.
// Each case here is a delivery that differs from the stored row in one column
// the UPDATE writes, and each must still reach the row. The list of columns is
// the UPDATE's, so a column that stopped being compared would show up as the
// case that names it failing.
func TestADeliveryThatChangesAColumnStillWritesIt(t *testing.T) {
	completedWith := func(edit func(*Job)) func() *Job {
		return func() *Job {
			j := benchDelivery(1, JobCompleted)
			edit(j)
			return j
		}
	}
	cases := []struct {
		name    string
		first   func() *Job
		prepare string // SQL run after the first delivery, for a row the store would not leave like that itself
		change  func(*Job)
		took    func(got, stored *Job) bool
	}{
		{"repository", nil, "",
			func(j *Job) { j.Repo = "acme/gadgets" },
			func(g, _ *Job) bool { return g.Repo == "acme/gadgets" }},
		{"workflow", nil, "",
			func(j *Job) { j.Workflow = "Release" },
			func(g, _ *Job) bool { return g.Workflow == "Release" }},
		{"job name", nil, "",
			func(j *Job) { j.JobName = "build (linux, arm64)" },
			func(g, _ *Job) bool { return g.JobName == "build (linux, arm64)" }},
		{"labels", nil, "",
			func(j *Job) { j.Labels = append(j.Labels, "gpu") },
			func(g, _ *Job) bool { return slices.Contains(g.Labels, "gpu") }},
		{"state", nil, "",
			func(j *Job) { j.State = JobInProgress },
			func(g, _ *Job) bool { return g.State == JobInProgress }},
		{"conclusion",
			completedWith(func(j *Job) { j.Conclusion = "" }), "",
			func(j *Job) { j.Conclusion = "failure" },
			func(g, _ *Job) bool { return g.Conclusion == "failure" }},
		{"installation", nil, "",
			func(j *Job) { j.InstallationID = "ins_other" },
			func(g, _ *Job) bool { return g.InstallationID == "ins_other" }},
		{"pool", nil, "",
			func(j *Job) { j.PoolID = "pool_other" },
			func(g, _ *Job) bool { return g.PoolID == "pool_other" }},
		{"runner id", nil, "",
			func(j *Job) { j.RunnerID = "run_other" },
			func(g, _ *Job) bool { return g.RunnerID == "run_other" }},
		{"runner name", nil, "",
			func(j *Job) { j.RunnerName = "zoomies-other" },
			func(g, _ *Job) bool { return g.RunnerName == "zoomies-other" }},
		{"url", nil, "",
			func(j *Job) { j.HTMLURL = "https://github.com/acme/widgets/actions/runs/1/job/2" },
			func(g, _ *Job) bool { return g.HTMLURL == "https://github.com/acme/widgets/actions/runs/1/job/2" }},
		{"start", nil, "",
			func(j *Job) { j.StartedAt = &benchStart },
			func(g, _ *Job) bool { return g.StartedAt != nil && g.StartedAt.Equal(benchStart) }},
		{"completion",
			completedWith(func(j *Job) { j.CompletedAt = nil }), "",
			func(j *Job) { j.CompletedAt = &benchEnd },
			func(g, _ *Job) bool { return g.CompletedAt != nil && g.CompletedAt.Equal(benchEnd) }},
		{"match, and the moment the job became eligible",
			func() *Job {
				j := benchDelivery(1, JobQueued)
				j.Matched, j.PoolID = false, ""
				return j
			}, "",
			func(j *Job) { j.Matched = true },
			func(g, _ *Job) bool { return g.Matched && g.EligibleAt != nil }},
		// A job held for review is matched but not yet eligible: the match is all
		// that changes, and it has to reach the row on its own.
		{"match alone, while the job is held for review",
			func() *Job {
				j := benchDelivery(1, JobWaiting)
				j.Matched, j.PoolID = false, ""
				return j
			}, "",
			func(j *Job) { j.Matched = true },
			func(g, _ *Job) bool { return g.Matched && g.EligibleAt == nil }},
		// A row from before the eligible_at column existed is matched and has no
		// moment for it. The next delivery stamps one, and that is the only change.
		{"the moment a job became eligible, alone",
			nil, `UPDATE jobs SET eligible_at = NULL`,
			func(j *Job) {},
			func(g, _ *Job) bool { return g.EligibleAt != nil }},
		{"branch", nil, "",
			func(j *Job) { j.HeadBranch = "release/1.2" },
			func(g, _ *Job) bool { return g.HeadBranch == "release/1.2" }},
		{"commit", nil, "",
			func(j *Job) { j.HeadSHA = "0000000000000000000000000000000000000000" },
			func(g, _ *Job) bool { return g.HeadSHA == "0000000000000000000000000000000000000000" }},
		{"attempt", nil, "",
			func(j *Job) { j.RunAttempt = 2 },
			func(g, _ *Job) bool { return g.RunAttempt == 2 }},
		{"run number", nil, "",
			func(j *Job) { j.RunNumber = 77 },
			func(g, _ *Job) bool { return g.RunNumber == 77 }},
		{"run", nil, "",
			func(j *Job) { j.GitHubRunID++ },
			func(g, _ *Job) bool { return g.GitHubRunID == benchDelivery(1, JobQueued).GitHubRunID+1 }},
		{"steps",
			func() *Job { return benchDelivery(1, JobInProgress) }, "",
			func(j *Job) { j.Steps = benchSteps(3) },
			func(g, _ *Job) bool { return len(g.Steps) > 2 && g.Steps[2].Status == "completed" }},
		{"runner fault",
			completedWith(func(j *Job) {}), "",
			func(j *Job) { j.RunnerFault = "the runner exited before the job finished" },
			func(g, _ *Job) bool { return g.RunnerFault == "the runner exited before the job finished" }},
		{"fault kind",
			completedWith(func(j *Job) {}), "",
			func(j *Job) { j.FaultKind = FaultOutOfMemory },
			func(g, _ *Job) bool { return g.FaultKind == FaultOutOfMemory }},
		{"the moment a held job joined the queue",
			func() *Job {
				j := benchDelivery(1, JobWaiting)
				j.Matched, j.PoolID = false, ""
				return j
			}, "",
			func(j *Job) { j.State, j.Matched, j.PoolID = JobQueued, false, "" },
			func(g, was *Job) bool { return g.State == JobQueued && g.QueuedAt.After(was.QueuedAt) }},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			ctx := context.Background()
			s := newTestStoreAt(t, jobWriteClock())
			updates := countJobUpdates(t, s)

			first := benchDelivery(1, JobQueued)
			if tc.first != nil {
				first = tc.first()
			}
			if _, _, err := s.ApplyJob(ctx, first); err != nil {
				t.Fatalf("the first delivery: %v", err)
			}
			if tc.prepare != "" {
				if _, err := s.exec(ctx, tc.prepare); err != nil {
					t.Fatalf("preparing the row: %v", err)
				}
			}
			stored, err := s.GetJobByGitHubID(ctx, 1)
			if err != nil {
				t.Fatalf("reading the job back: %v", err)
			}
			wrote := updates()

			// The delivery repeats the stored job and changes the one thing the
			// case names, so that nothing else can be what makes it write.
			next := *stored
			next.Labels = slices.Clone(stored.Labels)
			next.Steps = slices.Clone(stored.Steps)
			tc.change(&next)
			if _, _, err := s.ApplyJob(ctx, &next); err != nil {
				t.Fatalf("the delivery that changes the %s: %v", tc.name, err)
			}

			if n := updates() - wrote; n != 1 {
				t.Errorf("a delivery that changes the %s ran %d UPDATEs of the jobs table; want 1", tc.name, n)
			}
			got, err := s.GetJobByGitHubID(ctx, 1)
			if err != nil {
				t.Fatalf("reading the job back: %v", err)
			}
			if !tc.took(got, stored) {
				t.Errorf("the stored job did not take the new %s: %s", tc.name, jobJSON(t, got))
			}
		})
	}
}

// A delivery that arrives late may only fill in what the row does not have yet,
// and when it does fill something in, that is a write like any other: the
// runner a completed job was never linked to is exactly the kind of gap a late
// in_progress delivery closes.
func TestAStaleDeliveryThatFillsAGapStillWritesIt(t *testing.T) {
	ctx := context.Background()
	s := newTestStoreAt(t, jobWriteClock())
	updates := countJobUpdates(t, s)

	if _, _, err := s.ApplyJob(ctx, benchDelivery(1, JobCompleted)); err != nil {
		t.Fatal(err)
	}
	wrote := updates()

	got, change, err := s.ApplyJob(ctx, benchDelivery(1, JobInProgress))
	if err != nil {
		t.Fatal(err)
	}
	if n := updates() - wrote; n != 1 {
		t.Errorf("a late delivery that links the job's runner ran %d UPDATEs of the jobs table; want 1", n)
	}
	if got.State != JobCompleted || !change.RunnerLinked || got.RunnerID != "run_bench" {
		t.Errorf("got state %s, runner %q, change %+v; want the job still completed, now linked to run_bench", got.State, got.RunnerID, change)
	}
	stored, err := s.GetJobByGitHubID(ctx, 1)
	if err != nil {
		t.Fatal(err)
	}
	if stored.RunnerID != "run_bench" || stored.RunnerName != "zoomies-bench" {
		t.Errorf("the stored job has runner %q (%q); want the one the late delivery named", stored.RunnerID, stored.RunnerName)
	}
}

package store

import (
	"context"
	"slices"
	"strings"
	"testing"
	"time"
)

// The Jobs page's All view asks for the jobs in all four states, newest first, and
// SQLite used to answer by seeking the state index for each of the four and then
// sorting every row it found, read whole: 61 ms over 10,000 jobs where reading
// them in queued order and stopping after fifty takes less than one, and the
// first grows with the table. This holds the plan, because a result that was right
// and slow would pass every other test here.
func TestAStateListThatIncludesCompletedAndAnotherIsReadInQueuedOrder(t *testing.T) {
	s := newTestStore(t)
	all := []JobState{JobWaiting, JobQueued, JobInProgress, JobCompleted}
	for name, states := range map[string][]JobState{
		"every state":             all,
		"completed and queued":    {JobCompleted, JobQueued},
		"completed and running":   {JobInProgress, JobCompleted},
		"completed named twice":   {JobCompleted, JobQueued, JobCompleted},
		"completed and a mistake": {"bogus", JobCompleted},
	} {
		where, args := jobWhere(JobFilter{ManagedOnly: true, States: states}, s.Now())
		plan := explain(t, s, `SELECT `+jobCols+` FROM jobs `+where+` ORDER BY queued_at DESC, id ASC LIMIT 50`, args...)
		if !strings.Contains(plan, "idx_jobs_queued_id") || strings.Contains(plan, "TEMP B-TREE") {
			t.Errorf("%s: the page is not read in queued order from idx_jobs_queued_id: %s", name, plan)
		}
	}
}

// The other half of the same choice. The live states are few, and an index finds
// them at once; read in queued order they would be looked for in a history that
// grows without bound, for a page that is nearly empty. Completed on its own is
// left to the index as well: it reads it in queued order and, given a window of
// dates, only the window.
func TestAStateListWithoutBothCompletedAndAnotherIsFoundThroughTheStateIndex(t *testing.T) {
	s := newTestStore(t)
	for name, states := range map[string][]JobState{
		"running":                      {JobInProgress},
		"queued":                       {JobQueued},
		"queued and running":           {JobQueued, JobInProgress},
		"everything in hand":           {JobWaiting, JobQueued, JobInProgress},
		"running named twice":          {JobInProgress, JobInProgress},
		"waiting for a review":         {JobWaiting},
		"completed alone":              {JobCompleted},
		"completed alone, named twice": {JobCompleted, JobCompleted},
	} {
		where, args := jobWhere(JobFilter{ManagedOnly: true, States: states}, s.Now())
		plan := explain(t, s, `SELECT `+jobCols+` FROM jobs `+where+` ORDER BY queued_at DESC, id ASC LIMIT 50`, args...)
		if !strings.Contains(plan, "(state=?)") || strings.Contains(plan, "SCAN jobs") {
			t.Errorf("%s: the states are not sought through an index on the state: %s", name, plan)
		}
	}
}

func TestAStateListNamesEachStateOnce(t *testing.T) {
	for name, c := range map[string]struct {
		states []JobState
		term   string
		args   []any
	}{
		"one":          {[]JobState{JobQueued}, "state IN (?)", []any{"queued"}},
		"two":          {[]JobState{JobQueued, JobInProgress}, "state IN (?,?)", []any{"queued", "in_progress"}},
		"twice":        {[]JobState{JobQueued, JobQueued, JobWaiting}, "state IN (?,?)", []any{"queued", "waiting"}},
		"completed":    {[]JobState{JobCompleted}, "state IN (?)", []any{"completed"}},
		"and another":  {[]JobState{JobQueued, JobCompleted}, "+state IN (?,?)", []any{"queued", "completed"}},
		"only twice":   {[]JobState{JobCompleted, JobCompleted}, "state IN (?)", []any{"completed"}},
		"not a state":  {[]JobState{"bogus"}, "state IN (?)", []any{"bogus"}},
		"among others": {[]JobState{"bogus", JobCompleted}, "+state IN (?,?)", []any{"bogus", "completed"}},
	} {
		term, args := jobStateTerm(c.states)
		// The order of the arguments is not the list's meaning, only that there is one
		// for each placeholder.
		got := make([]string, len(args))
		for i, a := range args {
			got[i] = a.(string)
		}
		want := make([]string, len(c.args))
		for i, a := range c.args {
			want[i] = a.(string)
		}
		slices.Sort(got)
		slices.Sort(want)
		if term != c.term || !slices.Equal(got, want) {
			t.Errorf("%s: jobStateTerm(%v) = %q, %v; want %q, %v", name, c.states, term, args, c.term, c.args)
		}
	}
}

// managedByHand is the Jobs page's "this fleet had a hand in it", worked out in Go
// from the job and not in SQL, so that the listing can be held to something other
// than itself.
func managedByHand(j *Job) bool {
	return j.Matched || j.PoolID != "" || j.RunnerID != "" ||
		(!j.Matched && (j.State == JobQueued || j.State == JobWaiting) && !HostedJob(j.Labels))
}

// Whichever states are asked for, and however the list is spelled, the page and the
// count are the jobs in those states and no others, in the order the page shows
// them. The plan above is what keeps the All view fast; this is what keeps it right
// when the planner reads the states as a test and not as a seek.
func TestEveryChoiceOfStatesListsTheJobsInThemAndNoOthers(t *testing.T) {
	ctx := context.Background()
	now := time.Now().Truncate(time.Millisecond)
	s := newTestStoreAt(t, func() time.Time { return now })
	jobs, _ := pageHistory(t, s, now, 120)

	byQueued := slices.Clone(jobs)
	slices.SortFunc(byQueued, func(a, b *Job) int {
		switch {
		case a.QueuedAt.After(b.QueuedAt):
			return -1
		case a.QueuedAt.Before(b.QueuedAt):
			return 1
		}
		return strings.Compare(a.ID, b.ID)
	})
	seen := map[JobState]int{}
	for _, j := range jobs {
		seen[j.State]++
	}
	for _, st := range []JobState{JobWaiting, JobQueued, JobInProgress, JobCompleted} {
		if seen[st] == 0 {
			t.Fatalf("the history has no job in the %s state, so no choice of states is held to it", st)
		}
	}

	states := []JobState{JobWaiting, JobQueued, JobInProgress, JobCompleted}
	choices := 0
	for mask := 1; mask < 1<<len(states); mask++ {
		var choice []JobState
		for i, st := range states {
			if mask>>i&1 == 1 {
				choice = append(choice, st)
			}
		}
		// The same states, named again, as a caller that builds the list from several
		// places might.
		for _, spelling := range [][]JobState{choice, append(slices.Clone(choice), choice[0])} {
			for _, managedOnly := range []bool{false, true} {
				var want []string
				for _, j := range byQueued {
					if slices.Contains(choice, j.State) && (!managedOnly || managedByHand(j)) {
						want = append(want, j.ID)
					}
				}
				f := JobFilter{States: spelling, ManagedOnly: managedOnly}
				for _, p := range []Page{{Limit: 7}, {Limit: 7, Offset: 14}, {Limit: 7, Offset: 112}, {Limit: 500}} {
					got, total, err := s.ListJobs(ctx, f, p)
					if err != nil {
						t.Fatalf("ListJobs(%v, managed=%v, %+v): %v", spelling, managedOnly, p, err)
					}
					from := min(p.Offset, len(want))
					to := min(from+p.limit(50, 500), len(want))
					if total != len(want) || !slices.Equal(idsOf(got), want[from:to]) {
						t.Errorf("states %v, managed only %v, page %+v: got %d jobs of %d, %v; want %d of %d, %v",
							spelling, managedOnly, p, len(got), total, idsOf(got), to-from, len(want), want[from:to])
					}
				}
				// Read by keyset instead, a page at a time, it is the same listing.
				var walked []string
				var cursor *JobCursor
				for range len(want)/7 + 2 {
					page, total, next, err := s.ListJobsAfter(ctx, f, cursor, 7)
					if err != nil {
						t.Fatalf("ListJobsAfter(%v): %v", spelling, err)
					}
					if total != len(want) {
						t.Errorf("states %v, managed only %v: the keyset count is %d; want %d", spelling, managedOnly, total, len(want))
					}
					walked = append(walked, idsOf(page)...)
					if next == nil {
						break
					}
					cursor = next
				}
				if !slices.Equal(walked, want) {
					t.Errorf("states %v, managed only %v: the keyset walk found %d jobs; want %d", spelling, managedOnly, len(walked), len(want))
				}
				choices++
			}
		}
	}
	if want := 15 * 2 * 2; choices != want {
		t.Fatalf("held %d choices of states; want %d", choices, want)
	}
}

func idsOf(jobs []*Job) []string {
	ids := make([]string, len(jobs))
	for i, j := range jobs {
		ids[i] = j.ID
	}
	return ids
}

package store

import (
	"context"
	"fmt"
	"testing"
	"time"
)

// completedJobs puts n completed jobs in the last day in the store, over four pools.
func completedJobs(tb testing.TB, s *Store, n int) {
	tb.Helper()
	now := time.Now()
	for i := range n {
		queued := now.Add(-time.Duration(1+i%600) * time.Minute)
		started, done := queued.Add(20*time.Second), queued.Add(time.Duration(30+i%90)*time.Second)
		if _, err := s.UpsertJob(context.Background(), &Job{
			GitHubJobID: int64(1000 + i), Repo: "acme/api", Workflow: "CI", JobName: fmt.Sprintf("build-%d", i%5),
			State: JobCompleted, Conclusion: "success", PoolID: fmt.Sprintf("pool_%d", i%4),
			QueuedAt: queued, StartedAt: &started, CompletedAt: &done,
		}); err != nil {
			tb.Fatalf("UpsertJob: %v", err)
		}
	}
}

// JobStats is what the dashboard asks of the jobs table every pass: how many ran
// in each pool, how they ended and how long they waited and took. It is six
// statements, and each is a page of SQL, so a table with nothing in it is the cost
// of the statements themselves and a table with a lot in it is the cost of running
// them. The scenario is checked before anything is timed: a table that did not
// hold the jobs it was meant to would time the empty one under another name.
func BenchmarkJobStats(b *testing.B) {
	ctx := context.Background()
	for _, n := range []int{0, 1000, 10000} {
		b.Run(fmt.Sprintf("jobs=%d", n), func(b *testing.B) {
			s := newTestStore(b)
			completedJobs(b, s, n)
			since := time.Now().Add(-24 * time.Hour)
			f := JobFilter{Since: &since}

			res, err := s.JobStats(ctx, f, []string{GroupByPool})
			if err != nil {
				b.Fatalf("JobStats: %v", err)
			}
			counted := 0
			for _, g := range res.Groups {
				counted += g.Count
			}
			if counted != n {
				b.Fatalf("the statistics counted %d jobs; the table holds %d", counted, n)
			}

			b.ReportAllocs()
			for b.Loop() {
				if _, err := s.JobStats(ctx, f, []string{GroupByPool}); err != nil {
					b.Fatal(err)
				}
			}
		})
	}
}

// The same table read for one figure, which is what each reader of the dashboard's
// passes does: the pools' queue wait, the job names' duration, the pools' peak
// memory, the counts of jobs by pool and host. Every one is the statement that
// names the groups and the statement for its figure, so what they cost is read
// against the full answer's six at BenchmarkJobStats. The figure is checked before
// anything is timed, for the reason that one is.
func BenchmarkJobStatsOf(b *testing.B) {
	ctx := context.Background()
	for _, c := range []struct {
		name string
		want JobMeasures
		// read is what a group contributes, and total what the groups of a table of n
		// jobs add up to if the figure was worked out. The jobs have no peaks, so the
		// peaks are read as the groups themselves, which are the four pools.
		read  func(JobStatsGroup) int
		total func(n int) int
	}{
		{"counts", MeasureCounts, func(g JobStatsGroup) int { return g.Count }, func(n int) int { return n }},
		{"peaks", MeasurePeaks, func(JobStatsGroup) int { return 1 }, func(int) int { return 4 }},
		{"duration", MeasureDuration, func(g JobStatsGroup) int { return g.Duration.Samples }, func(n int) int { return n }},
		{"queue_wait", MeasureQueueWait, func(g JobStatsGroup) int { return g.QueueWait.Samples }, func(n int) int { return n }},
	} {
		for _, n := range []int{1000, 10000} {
			b.Run(fmt.Sprintf("figures=%s/jobs=%d", c.name, n), func(b *testing.B) {
				s := newTestStore(b)
				completedJobs(b, s, n)
				since := time.Now().Add(-24 * time.Hour)
				f := JobFilter{Since: &since}

				res, err := s.JobStatsOf(ctx, f, []string{GroupByPool}, c.want)
				if err != nil {
					b.Fatalf("JobStatsOf: %v", err)
				}
				read := 0
				for _, g := range res.Groups {
					read += c.read(g)
				}
				if want := c.total(n); read != want {
					b.Fatalf("the %s figure added up to %d over the table of %d jobs; want %d", c.name, read, n, want)
				}

				b.ReportAllocs()
				for b.Loop() {
					if _, err := s.JobStatsOf(ctx, f, []string{GroupByPool}, c.want); err != nil {
						b.Fatal(err)
					}
				}
			})
		}
	}
}

package store

import (
	"context"
	"fmt"
	"math/rand"
	"reflect"
	"testing"
	"time"
)

// The dashboard reads one figure of the six that JobStats works out, each by a
// statement over the whole window, and the dearest are the three percentiles. A
// caller can now ask for the figures it reads (JobStatsOf), and these tests hold
// that to the answer JobStats gives: the groups, their order and where the list is
// cut off do not move, the figures asked for are exactly the figures JobStats has,
// and the ones not asked for are left at zero.

// mixedJobs puts a history in the store that gives every figure something to count:
// n completed jobs over three days, in three pools (one of them blank), under three
// job names, from two releases and from jobs nothing stamped, on two hosts and on
// none, ending every way a job can, some lost to the fleet with a kind and some
// without, some measured and some not, some that never started, and some whose
// runner row is still kept. Durations come in whole seconds so that samples tie.
func mixedJobs(t *testing.T, s *Store, n int) {
	t.Helper()
	ctx := context.Background()
	rng := rand.New(rand.NewSource(7))
	_, pool, host := seedPool(t, s)

	// A runner whose container started before it was created has no startup: that is
	// two clocks disagreeing, and the figure leaves it out.
	var runners []string
	for i := range 12 {
		r := &Runner{PoolID: pool.ID, HostID: host.ID, Name: fmt.Sprintf("zoomies-%d", i), Ephemeral: true}
		if err := s.CreateRunner(ctx, r); err != nil {
			t.Fatalf("CreateRunner: %v", err)
		}
		created := versionsEpoch.Add(time.Duration(i) * time.Hour)
		started := created.Add(time.Duration(1+rng.Intn(9)) * time.Second)
		if i%5 == 4 {
			started = created.Add(-time.Second)
		}
		if _, err := s.exec(ctx, `UPDATE runners SET created_at = ?, container_started_at = ? WHERE id = ?`, ms(created), ms(started), r.ID); err != nil {
			t.Fatalf("dating runner %d: %v", i, err)
		}
		runners = append(runners, r.ID)
	}

	pools := []string{"pool_a", "pool_b", ""}
	names := []string{"build", "test", "lint"}
	conclusions := []string{"success", "success", "success", "success", "success", "success", "failure", "failure", "cancelled", "skipped"}
	releases := []any{"v1.0.0", "v1.1.0", nil}
	hosts := []any{"host_1", "host_2", nil}
	for i := range n {
		queued := versionsEpoch.Add(time.Duration(i) * 37 * time.Minute)
		started := queued.Add(time.Duration(rng.Intn(24)) * 5 * time.Second)
		done := started.Add(time.Duration(rng.Intn(120)) * 5 * time.Second)
		j := &Job{
			GitHubJobID: int64(2000 + i), Repo: "acme/widgets", Workflow: "ci", JobName: names[rng.Intn(len(names))],
			State: JobCompleted, Conclusion: conclusions[rng.Intn(len(conclusions))], Matched: true,
			PoolID: pools[rng.Intn(len(pools))], QueuedAt: queued, StartedAt: &started, CompletedAt: &done,
		}
		if rng.Intn(15) == 0 {
			// Cancelled before a runner took it.
			j.StartedAt = nil
		}
		out, err := s.UpsertJob(ctx, j)
		if err != nil {
			t.Fatalf("UpsertJob %d: %v", i, err)
		}

		var fault, kind string
		if rng.Intn(6) == 0 {
			fault, kind = "the runner stopped", []string{string(FaultRunnerExited), string(FaultOutOfMemory), ""}[rng.Intn(3)]
		}
		var source string
		var cpus float64
		var memory int64
		if rng.Intn(3) > 0 {
			source, cpus, memory = AllocationHistory, []float64{0, 1, 2, 4}[rng.Intn(4)], []int64{0, 2048, 3000, 8192}[rng.Intn(4)]
		}
		var peakCPUs float64
		var peakMemory, peakRunner, peakDaemon int64
		var oom int
		if rng.Intn(2) == 0 {
			peakCPUs, peakMemory = float64(1+rng.Intn(4))/2, int64(256*(1+rng.Intn(20)))
			if rng.Intn(3) == 0 {
				peakRunner, peakDaemon = peakMemory/3, peakMemory-peakMemory/3
			}
			if rng.Intn(8) == 0 {
				oom = 1
			}
		}
		runner := ""
		if rng.Intn(3) == 0 {
			runner = runners[rng.Intn(len(runners))]
		} else if rng.Intn(10) == 0 {
			runner = "run_gone"
		}
		if _, err := s.exec(ctx, `UPDATE jobs SET controller_version = ?, host_id = ?, runner_fault = ?, fault_kind = ?,
				granted_source = ?, granted_cpus = ?, granted_memory_mb = ?, peak_cpus = ?, peak_memory_mb = ?, oom_killed = ?,
				peak_runner_memory_mb = ?, peak_daemon_memory_mb = ?, runner_id = ? WHERE id = ?`,
			releases[rng.Intn(len(releases))], hosts[rng.Intn(len(hosts))], fault, kind, source, cpus, memory,
			peakCPUs, peakMemory, oom, peakRunner, peakDaemon, runner, out.ID); err != nil {
			t.Fatalf("measuring job %d: %v", i, err)
		}
	}
}

// only is a full answer with the figures that were not asked for put back to
// zero, which is what asking for the others must give. It is written out figure
// by figure and does not share anything with JobStatsOf, so that a figure the
// real thing leaks or loses is the difference.
func only(full *JobStatsResult, want JobMeasures) *JobStatsResult {
	out := &JobStatsResult{Truncated: full.Truncated}
	for _, g := range full.Groups {
		if want&MeasureCounts == 0 {
			g.Count, g.Succeeded, g.Failed, g.Cancelled, g.FleetFailed, g.FleetFailureRate = 0, 0, 0, 0, 0, 0
		}
		if want&MeasureFaultKinds == 0 {
			g.FleetFailedByKind = nil
		}
		if want&MeasurePeaks == 0 {
			g.PeakCPUs, g.PeakMemoryMB, g.OOMKilled, g.MeasuredMemory = nil, nil, 0, 0
			g.PeakRunnerMemoryMB, g.PeakDaemonMemoryMB, g.MeasuredHalves = 0, 0, 0
		}
		if want&MeasureDuration == 0 {
			g.Duration = JobPercentiles{}
		}
		if want&MeasureQueueWait == 0 {
			g.QueueWait = JobPercentiles{}
		}
		if want&MeasureStartup == 0 {
			g.Startup = JobPercentiles{}
		}
		out.Groups = append(out.Groups, g)
	}
	return out
}

func TestAskingForSomeOfTheJobFiguresGivesThoseAndLeavesTheRestAtZero(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	mixedJobs(t, s, 150)

	later := versionsEpoch.Add(24 * time.Hour)
	cases := []struct {
		name string
		f    JobFilter
		by   []string
	}{
		{"as one total", JobFilter{}, nil},
		{"by pool", JobFilter{}, []string{GroupByPool}},
		{"by job name and pool, after the first day", JobFilter{Since: &later}, []string{GroupByJobName, GroupByPool}},
		{"by release, which reads in the order they were first seen", JobFilter{}, []string{GroupByControllerVersion}},
		{"by day and host", JobFilter{}, []string{GroupByDay, GroupByHost}},
		{"by size, in one pool", JobFilter{PoolIDs: []string{"pool_a"}}, []string{GroupBySize}},
	}

	// The comparison says something only if the history gave each figure something
	// to be different about.
	var counted, lost, named, unnamed, cancelled, measured, killed, halves, timed, waited, started, fewer int
	for _, c := range cases {
		full, err := s.JobStats(ctx, c.f, c.by)
		if err != nil {
			t.Fatalf("%s: JobStats: %v", c.name, err)
		}
		if len(full.Groups) == 0 {
			t.Fatalf("%s: the history gave no groups", c.name)
		}
		for _, g := range full.Groups {
			counted += g.Count
			lost += g.FleetFailed
			cancelled += g.Cancelled
			named += g.FleetFailedByKind[string(FaultRunnerExited)]
			unnamed += g.FleetFailedByKind["unclassified"]
			killed += g.OOMKilled
			halves += g.MeasuredHalves
			timed += g.Duration.Samples
			waited += g.QueueWait.Samples
			started += g.Startup.Samples
			if g.PeakMemoryMB != nil {
				measured++
			}
			if g.Duration.Samples < g.Count {
				fewer++
			}
		}

		for want := JobMeasures(0); want <= MeasureAll; want++ {
			got, err := s.JobStatsOf(ctx, c.f, c.by, want)
			if err != nil {
				t.Fatalf("%s, figures %06b: JobStatsOf: %v", c.name, want, err)
			}
			if exp := only(full, want); !reflect.DeepEqual(got, exp) {
				t.Fatalf("%s, figures %06b: JobStatsOf differs from JobStats with the other figures put back to zero\n got: %+v\nwant: %+v", c.name, want, got.Groups, exp.Groups)
			}
		}
	}
	if counted == 0 || lost == 0 || cancelled == 0 || named == 0 || unnamed == 0 || measured == 0 || killed == 0 || halves == 0 ||
		timed == 0 || waited == 0 || started == 0 || fewer == 0 {
		t.Fatalf("the history exercised too little: counted %d, lost %d, cancelled %d, named kinds %d, unclassified %d, measured groups %d, killed %d, halves %d, timed %d, waited %d, started %d, groups with fewer durations than jobs %d",
			counted, lost, cancelled, named, unnamed, measured, killed, halves, timed, waited, started, fewer)
	}

	// Each figure is a statement over the whole window, so the saving is in not
	// running the ones that are not read. The groups come from the first.
	statements := func(want JobMeasures, f JobFilter) int64 {
		t.Helper()
		before := s.texts.hits.Load() + s.texts.misses.Load()
		if _, err := s.JobStatsOf(ctx, f, []string{GroupByPool}, want); err != nil {
			t.Fatalf("JobStatsOf: %v", err)
		}
		return s.texts.hits.Load() + s.texts.misses.Load() - before
	}
	for _, c := range []struct {
		name string
		want JobMeasures
		ran  int64
	}{
		{"nothing but the groups", 0, 1},
		{"the counts", MeasureCounts, 1},
		// A figure nearly every job has is gathered by the statement that names
		// the groups when it is the only one, because that statement goes through
		// every job anyway.
		{"the duration alone", MeasureDuration, 1},
		{"the queue wait alone", MeasureQueueWait, 1},
		{"the startup alone, which few jobs have", MeasureStartup, 2},
		{"the peaks", MeasurePeaks, 2},
		{"the fault kinds", MeasureFaultKinds, 2},
		{"the counts and the duration", MeasureCounts | MeasureDuration, 2},
		{"the duration and the queue wait", MeasureDuration | MeasureQueueWait, 3},
		{"queue wait and startup", MeasureQueueWait | MeasureStartup, 3},
		{"everything", MeasureAll, 6},
	} {
		if ran := statements(c.want, JobFilter{}); ran != c.ran {
			t.Errorf("asking for %s ran %d statements, want %d", c.name, ran, c.ran)
		}
	}
	// A window with no job in it has no group for the other statements to fill in.
	nothing := versionsEpoch.Add(30 * 24 * time.Hour)
	if ran := statements(MeasureAll, JobFilter{Since: &nothing}); ran != 1 {
		t.Errorf("a window with no job in it ran %d statements, want only the one that found there were no groups", ran)
	}
}

// Only the first MaxJobStatsGroups groups are kept, in the order of their keys, and
// a group with no sample of the figure asked for is still a group: it takes its
// place in the list and its turn to be cut off. Taking the groups from the figure's
// own statement would move the line, and lose the answer's Truncated.
func TestAskingForSomeOfTheJobFiguresCutsTheGroupsOffWhereAskingForAllDoes(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	for i := range MaxJobStatsGroups + 20 {
		queued := versionsEpoch.Add(time.Duration(i) * time.Minute)
		started, done := queued.Add(5*time.Second), queued.Add(time.Duration(10+i)*time.Second)
		conclusion := "success"
		if i < 30 {
			// The first thirty names took no measured time.
			conclusion = "skipped"
		}
		if _, err := s.UpsertJob(ctx, &Job{
			GitHubJobID: int64(3000 + i), Repo: "acme/widgets", Workflow: "ci", JobName: fmt.Sprintf("job-%04d", i),
			State: JobCompleted, Conclusion: conclusion, Matched: true, PoolID: "pool_a",
			QueuedAt: queued, StartedAt: &started, CompletedAt: &done,
		}); err != nil {
			t.Fatalf("UpsertJob %d: %v", i, err)
		}
	}
	full, err := s.JobStats(ctx, JobFilter{}, []string{GroupByJobName})
	if err != nil {
		t.Fatalf("JobStats: %v", err)
	}
	if !full.Truncated || len(full.Groups) != MaxJobStatsGroups || full.Groups[0].Duration.Samples != 0 {
		t.Fatalf("the history gave %d groups, truncated %v, first with %d duration samples; want %d, truncated, the first with none",
			len(full.Groups), full.Truncated, full.Groups[0].Duration.Samples, MaxJobStatsGroups)
	}
	for _, want := range []JobMeasures{0, MeasureDuration, MeasureQueueWait | MeasurePeaks} {
		got, err := s.JobStatsOf(ctx, JobFilter{}, []string{GroupByJobName}, want)
		if err != nil {
			t.Fatalf("figures %06b: JobStatsOf: %v", want, err)
		}
		if exp := only(full, want); !reflect.DeepEqual(got, exp) {
			t.Fatalf("figures %06b: the %d groups kept, truncated %v, are not the %d groups, truncated %v, that JobStats keeps",
				want, len(got.Groups), got.Truncated, len(exp.Groups), exp.Truncated)
		}
	}
}

package store

import (
	"context"
	"fmt"
	"math/rand"
	"slices"
	"strings"
	"testing"
	"time"
)

// A percentile is the sample at index round((n-1)*q) of the group's samples in
// order, the position the Overview's percentiles use, so a figure here and the same
// one there cannot differ by a rounding rule. These tests hold the statistics to
// that, from jobs whose waits and durations are known because the test made them,
// and not from another run of the statement that is being held to it.

// rankOf is the index of the sample for q = 1/2 and q = 19/20, as integers. The
// statement works the same position out in floating point, (n-1)*q + 0.5 cut to an
// integer, which agrees with this wherever the product is a half, because a double
// is within half a unit of its last place of the exact product.
func rankOf(n int) (p50, p95 int) { return n / 2, ((n-1)*19 + 10) / 20 }

func spreadOfSamples(samples []int64) JobPercentiles {
	if len(samples) == 0 {
		return JobPercentiles{}
	}
	sorted := slices.Clone(samples)
	slices.Sort(sorted)
	i50, i95 := rankOf(len(sorted))
	return JobPercentiles{Samples: len(sorted), P50MS: &sorted[i50], P95MS: &sorted[i95]}
}

func TestPercentilesAreTheSamplesAtTheRankTheOverviewUses(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	rng := rand.New(rand.NewSource(11))

	// One pool for each size of group from one job to thirty, so every position
	// the two ranks can fall on in a small group is taken, and one of a thousand.
	// Durations come in whole seconds so that samples tie, and a tenth of the jobs
	// are cancelled (they waited, and ran for as long as somebody let them, which
	// the duration leaves out) and a seventh never started (they have neither).
	sizes := make([]int, 0, 31)
	for n := 1; n <= 30; n++ {
		sizes = append(sizes, n)
	}
	sizes = append(sizes, 1000)

	waits, durs := map[string][]int64{}, map[string][]int64{}
	id := 0
	for _, size := range sizes {
		pool := fmt.Sprintf("pool_%04d", size)
		for i := range size {
			id++
			queued := versionsEpoch.Add(time.Duration(id) * time.Minute)
			wait := time.Duration(rng.Intn(40)) * time.Second
			ran := time.Duration(rng.Intn(60)) * time.Second
			started, done := queued.Add(wait), queued.Add(wait+ran)
			j := &Job{
				GitHubJobID: int64(4000 + id), Repo: "acme/widgets", Workflow: "ci", JobName: "build", PoolID: pool,
				State: JobCompleted, Conclusion: "success", Matched: true, QueuedAt: queued, StartedAt: &started, CompletedAt: &done,
			}
			switch {
			case i%7 == 6:
				j.StartedAt = nil
			case i%10 == 9:
				j.Conclusion = "cancelled"
			}
			if _, err := s.UpsertJob(ctx, j); err != nil {
				t.Fatalf("UpsertJob: %v", err)
			}
			if j.StartedAt != nil {
				waits[pool] = append(waits[pool], wait.Milliseconds())
				if j.Conclusion != "cancelled" {
					durs[pool] = append(durs[pool], ran.Milliseconds())
				}
			}
		}
	}

	check := func(name string, res *JobStatsResult, durationToo, waitToo bool) {
		t.Helper()
		if len(res.Groups) != len(sizes) {
			t.Fatalf("%s: %d groups, want %d", name, len(res.Groups), len(sizes))
		}
		for _, g := range res.Groups {
			pool := g.Keys[GroupByPool]
			if durationToo {
				if want := spreadOfSamples(durs[pool]); !equalSpread(g.Duration, want) {
					t.Errorf("%s: %s duration = %s, want %s", name, pool, showSpread(g.Duration), showSpread(want))
				}
			}
			if waitToo {
				if want := spreadOfSamples(waits[pool]); !equalSpread(g.QueueWait, want) {
					t.Errorf("%s: %s queue wait = %s, want %s", name, pool, showSpread(g.QueueWait), showSpread(want))
				}
			}
		}
	}
	full, err := s.JobStats(ctx, JobFilter{}, []string{GroupByPool})
	if err != nil {
		t.Fatal(err)
	}
	check("all figures", full, true, true)
	one, err := s.JobStatsOf(ctx, JobFilter{}, []string{GroupByPool}, MeasureDuration)
	if err != nil {
		t.Fatal(err)
	}
	check("the duration alone", one, true, false)

	// The comparison says something only if the groups gave it something to tell
	// apart: a median below its 95th percentile, and ties at the ranks, where a
	// wrong pick of one of the equal samples still gives the right figure and a
	// wrong rank usually does not.
	apart, tied := 0, 0
	for _, g := range full.Groups {
		if g.Duration.P50MS != nil && *g.Duration.P50MS != *g.Duration.P95MS {
			apart++
		}
		pool := g.Keys[GroupByPool]
		for _, samples := range [][]int64{waits[pool], durs[pool]} {
			sorted := slices.Clone(samples)
			slices.Sort(sorted)
			i50, i95 := rankOf(len(sorted))
			for _, i := range []int{i50, i95} {
				if len(sorted) > 1 && (i+1 < len(sorted) && sorted[i] == sorted[i+1] || i > 0 && sorted[i-1] == sorted[i]) {
					tied++
				}
			}
		}
	}
	if apart < 10 || tied < 10 {
		t.Fatalf("the groups exercised too little: %d with a median below their 95th percentile, %d ranks with a tie beside them", apart, tied)
	}
}

func equalSpread(a, b JobPercentiles) bool {
	if a.Samples != b.Samples || (a.P50MS == nil) != (b.P50MS == nil) || (a.P95MS == nil) != (b.P95MS == nil) {
		return false
	}
	return (a.P50MS == nil || *a.P50MS == *b.P50MS) && (a.P95MS == nil || *a.P95MS == *b.P95MS)
}

func showSpread(sp JobPercentiles) string {
	return fmt.Sprintf("%d samples, p50 %s, p95 %s", sp.Samples, p(sp.P50MS), p(sp.P95MS))
}

// A group's samples come back as one string and two of them are read out of it. It
// reads only those two, so a figure it was not asked for cannot make it fail, and
// it says so, and does not answer, when the string has fewer samples than it was
// asked for: a count and a list that disagree are a bug to be seen, not a figure.
func TestTwoSamplesAreReadOutOfTheListWithoutParsingTheRest(t *testing.T) {
	for _, c := range []struct {
		name string
		list string
		i, j int
		a, b int64
		// err is what the refusal says, and empty when there is to be none.
		err string
	}{
		{"one sample", "5", 0, 0, 5, 5, ""},
		{"the first and the last", "1,2,3", 0, 2, 1, 3, ""},
		{"the same one twice", "1,2,3", 1, 1, 2, 2, ""},
		{"samples of different widths stay in the order given", "9,10,100,1000", 1, 3, 10, 1000, ""},
		{"the largest a figure can be", "0,9223372036854775807", 0, 1, 0, 9223372036854775807, ""},
		{"the others are not looked at", "1,not a number,3", 0, 2, 1, 3, ""},
		{"one sample too few", "1,2", 0, 2, 0, 0, "has 2 samples"},
		{"a sample that is not a number", "1,x", 0, 1, 0, 0, "not a whole number"},
		{"a sample that is empty", "1,,3", 0, 1, 0, 0, "not a whole number"},
	} {
		a, b, err := samplesAt(c.list, c.i, c.j)
		if c.err == "" && err != nil || c.err != "" && (err == nil || !strings.Contains(err.Error(), c.err)) || a != c.a || b != c.b {
			t.Errorf("%s: samplesAt(%q, %d, %d) = %d, %d, %v; want %d, %d, error %q", c.name, c.list, c.i, c.j, a, b, err, c.a, c.b, c.err)
		}
	}
}

package store

import (
	"context"
	"strings"
	"testing"
	"time"
)

// usageJob records a job on a runner in the given state.
func usageJob(t *testing.T, s *Store, n int, name, pool, runner string, state JobState, queued time.Time) *Job {
	t.Helper()
	j := &Job{
		GitHubJobID: int64(5000 + n), Repo: "eyupio/zoomies", Workflow: "CI", JobName: name,
		Labels: StringSlice{"self-hosted"}, State: state, QueuedAt: queued, Matched: true,
		PoolID: pool, RunnerID: runner,
	}
	if state == JobCompleted {
		done := queued.Add(time.Hour)
		j.StartedAt, j.CompletedAt, j.Conclusion = &queued, &done, "success"
	}
	out, _, err := s.ApplyJob(context.Background(), j)
	if err != nil {
		t.Fatalf("recording job %d: %v", n, err)
	}
	return out
}

// Samples arrive on every heartbeat, out of order after a reconnect, and
// before and after the job. Only the job GitHub says is running is charged,
// and a later, smaller sample must not lower what was already seen.
func TestRecordJobUsageRaisesOnlyTheRunningJobsPeaks(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	running := usageJob(t, s, 1, "Go (controller)", "pool_a", "run_1", JobInProgress, versionsEpoch)
	done := usageJob(t, s, 2, "Go (controller)", "pool_a", "run_1", JobCompleted, versionsEpoch.Add(-time.Hour))

	for _, sample := range []struct {
		cpus float64
		mb   int64
	}{{1.5, 900}, {3.9, 2800}, {0.2, 100}, {0, 0}} {
		if err := s.RecordJobUsage(ctx, "run_1", sample.cpus, sample.mb); err != nil {
			t.Fatalf("RecordJobUsage: %v", err)
		}
	}
	got, err := s.GetJob(ctx, running.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.PeakCPUs != 3.9 || got.PeakMemoryMB != 2800 {
		t.Fatalf("running job's peaks = %v CPU, %d MB, want 3.9 and 2800", got.PeakCPUs, got.PeakMemoryMB)
	}
	other, err := s.GetJob(ctx, done.ID)
	if err != nil {
		t.Fatal(err)
	}
	if other.PeakCPUs != 0 || other.PeakMemoryMB != 0 {
		t.Fatalf("a finished job was charged a later sample: %v CPU, %d MB", other.PeakCPUs, other.PeakMemoryMB)
	}
}

// A step killed with exit 137 leaves a runner that finishes the job, so the
// kill is reported after GitHub has closed it. It is recorded all the same,
// once, and a fault the runner reported first keeps its own words.
func TestMarkJobOOMKilledMarksTheRunnersLastJobOnce(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	usageJob(t, s, 1, "older", "pool_a", "run_1", JobCompleted, versionsEpoch.Add(-2*time.Hour))
	last := usageJob(t, s, 2, "Go (controller)", "pool_a", "run_1", JobCompleted, versionsEpoch)

	j, marked, err := s.MarkJobOOMKilled(ctx, "run_1", "runner r1 was killed for memory")
	if err != nil || !marked {
		t.Fatalf("MarkJobOOMKilled = %v, %v; want the job marked", marked, err)
	}
	if j.ID != last.ID || !j.OOMKilled || j.FaultKind != FaultOutOfMemory || j.RunnerFault != "runner r1 was killed for memory" {
		t.Fatalf("marked %+v, want the runner's last job, out of memory", j)
	}
	if _, again, err := s.MarkJobOOMKilled(ctx, "run_1", "a second report"); err != nil || again {
		t.Fatalf("a second report marked it again (%v, %v)", again, err)
	}

	// A fault recorded first keeps its sentence and category.
	lost := usageJob(t, s, 3, "lost", "pool_a", "run_2", JobInProgress, versionsEpoch)
	if _, _, err := s.SetJobRunnerFault(ctx, lost.ID, "runner exited with code 137", FaultOutOfMemory); err != nil {
		t.Fatal(err)
	}
	j, marked, err = s.MarkJobOOMKilled(ctx, "run_2", "ignored")
	if err != nil || !marked || j.RunnerFault != "runner exited with code 137" {
		t.Fatalf("MarkJobOOMKilled = %+v, %v, %v", j, marked, err)
	}

	if j, marked, err := s.MarkJobOOMKilled(ctx, "run_none", "x"); j != nil || marked || err != nil {
		t.Fatalf("a runner with no job marked %+v, %v, %v", j, marked, err)
	}
}

// The history a profile is taken from is the job's own measured runs, per
// pool, newest first, at most JobUsageHistoryLimit of them -- and a run that
// was never measured is not in it at all, because a zero is "unknown", not
// "needed nothing".
func TestJobUsageHistoryIsEachPoolsRecentMeasuredRuns(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	n := 0
	record := func(pool string, mb int64, oom bool, at time.Time) {
		n++
		runner := "run_" + strings.Repeat("x", n)
		usageJob(t, s, n, "Go (controller)", pool, runner, JobInProgress, at)
		if mb > 0 {
			if err := s.RecordJobUsage(ctx, runner, 2, mb); err != nil {
				t.Fatal(err)
			}
		}
		done := at.Add(time.Hour)
		if _, _, err := s.ApplyJob(ctx, &Job{GitHubJobID: int64(5000 + n), State: JobCompleted, Conclusion: "failure",
			Repo: "eyupio/zoomies", Workflow: "CI", JobName: "Go (controller)", StartedAt: &at, CompletedAt: &done}); err != nil {
			t.Fatal(err)
		}
		if oom {
			if _, _, err := s.MarkJobOOMKilled(ctx, runner, "killed"); err != nil {
				t.Fatal(err)
			}
		}
	}
	for i := range JobUsageHistoryLimit + 5 {
		record("pool_a", int64(1000+i), false, versionsEpoch.Add(time.Duration(i)*time.Hour))
	}
	record("pool_b", 3000, true, versionsEpoch)
	record("pool_b", 0, false, versionsEpoch.Add(time.Hour)) // never measured

	got, err := s.JobUsageHistory(ctx, []JobUsageKey{{Repo: "eyupio/zoomies", Workflow: "CI", JobName: "Go (controller)"}})
	if err != nil {
		t.Fatalf("JobUsageHistory: %v", err)
	}
	a := got[JobUsageKey{Repo: "eyupio/zoomies", Workflow: "CI", JobName: "Go (controller)", PoolID: "pool_a"}]
	if len(a) != JobUsageHistoryLimit || a[0].MemoryMB != int64(1000+JobUsageHistoryLimit+4) {
		t.Fatalf("pool_a history = %d runs, newest %+v; want %d, newest first", len(a), a[0], JobUsageHistoryLimit)
	}
	b := got[JobUsageKey{Repo: "eyupio/zoomies", Workflow: "CI", JobName: "Go (controller)", PoolID: "pool_b"}]
	if len(b) != 1 || !b[0].OOMKilled || b[0].MemoryMB != 3000 {
		t.Fatalf("pool_b history = %+v, want the one measured, killed run", b)
	}
}

// The history is read for every distinct queued job on every pass, so it must
// seek its index rather than walk a jobs table that grows without bound.
func TestJobUsageHistorySeeksItsIndex(t *testing.T) {
	s := newTestStore(t)
	rows, err := s.read.QueryContext(t.Context(), "EXPLAIN QUERY PLAN "+jobUsageHistorySQL, "r", "w", "j", 10)
	if err != nil {
		t.Fatalf("EXPLAIN QUERY PLAN: %v", err)
	}
	defer rows.Close()
	var plan []string
	for rows.Next() {
		var id, parent, notused int
		var detail string
		if err := rows.Scan(&id, &parent, &notused, &detail); err != nil {
			t.Fatal(err)
		}
		plan = append(plan, detail)
	}
	if joined := strings.Join(plan, "\n"); !strings.Contains(joined, "idx_jobs_usage_profile") {
		t.Fatalf("the history lookup does not use its index:\n%s", joined)
	}
}

// job_stats carries the heaviest job in each group and how many were killed
// for memory, so "which of our jobs need big hosts" is one call.
func TestJobStatsCarryPeakUsageAndMemoryKills(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	usageJob(t, s, 1, "light", "pool_a", "run_1", JobInProgress, versionsEpoch)
	usageJob(t, s, 2, "heavy", "pool_a", "run_2", JobInProgress, versionsEpoch)
	for _, u := range []struct {
		runner string
		cpus   float64
		mb     int64
	}{{"run_1", 0.5, 400}, {"run_2", 3.5, 5200}} {
		if err := s.RecordJobUsage(ctx, u.runner, u.cpus, u.mb); err != nil {
			t.Fatal(err)
		}
	}
	for n := 1; n <= 2; n++ {
		done := versionsEpoch.Add(time.Hour)
		if _, _, err := s.ApplyJob(ctx, &Job{GitHubJobID: int64(5000 + n), State: JobCompleted, Conclusion: "failure",
			Repo: "eyupio/zoomies", StartedAt: &versionsEpoch, CompletedAt: &done}); err != nil {
			t.Fatal(err)
		}
	}
	if _, _, err := s.MarkJobOOMKilled(ctx, "run_2", "killed"); err != nil {
		t.Fatal(err)
	}
	res, err := s.JobStats(ctx, JobFilter{}, []string{GroupByJobName})
	if err != nil {
		t.Fatalf("JobStats: %v", err)
	}
	by := map[string]JobStatsGroup{}
	for _, g := range res.Groups {
		by[g.Keys[GroupByJobName]] = g
	}
	heavy := by["heavy"]
	if heavy.PeakCPUs == nil || *heavy.PeakCPUs != 3.5 || heavy.PeakMemoryMB == nil || *heavy.PeakMemoryMB != 5200 || heavy.OOMKilled != 1 {
		t.Fatalf("heavy = %+v", heavy)
	}
	if light := by["light"]; light.OOMKilled != 0 || light.PeakMemoryMB == nil || *light.PeakMemoryMB != 400 {
		t.Fatalf("light = %+v", light)
	}
	// Both were measured, so the coverage is the whole group.
	if heavy.MeasuredMemory != 1 || by["light"].MeasuredMemory != 1 {
		t.Fatalf("measured = %d and %d, want 1 each", heavy.MeasuredMemory, by["light"].MeasuredMemory)
	}
}

// A job too short to be sampled has no peak, so a group's measured count is
// smaller than its job count: the figure advice rests on is how many were measured.
func TestJobStatsSayHowManyJobsWereMeasured(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	usageJob(t, s, 1, "build", "pool_a", "run_1", JobInProgress, versionsEpoch)
	usageJob(t, s, 2, "build", "pool_a", "run_2", JobInProgress, versionsEpoch)
	if err := s.RecordJobUsage(ctx, "run_1", 1, 900); err != nil {
		t.Fatal(err)
	}
	for n := 1; n <= 2; n++ {
		done := versionsEpoch.Add(time.Hour)
		if _, _, err := s.ApplyJob(ctx, &Job{GitHubJobID: int64(5000 + n), State: JobCompleted, Conclusion: "success",
			Repo: "eyupio/zoomies", StartedAt: &versionsEpoch, CompletedAt: &done}); err != nil {
			t.Fatal(err)
		}
	}
	res, err := s.JobStats(ctx, JobFilter{}, []string{GroupByPool})
	if err != nil || len(res.Groups) != 1 {
		t.Fatalf("JobStats = %+v, %v", res, err)
	}
	if g := res.Groups[0]; g.Count != 2 || g.MeasuredMemory != 1 {
		t.Fatalf("count %d, measured %d; want 2 completed and 1 measured", g.Count, g.MeasuredMemory)
	}
}

// A pair's halves are kept per job, as the most each used, and the statistics say how many
// jobs have them: a job that ran before they were kept has none and is not counted, so the
// advice that sizes a floor by them can wait for enough that do.
func TestRecordJobHalfPeaksKeepsTheMostEachHalfUsedAndCountsTheJobsThatHaveThem(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	running := usageJob(t, s, 1, "build", "pool_a", "run_1", JobInProgress, versionsEpoch)
	old := usageJob(t, s, 2, "build", "pool_a", "run_old", JobCompleted, versionsEpoch.Add(-time.Hour))
	_ = old
	for _, h := range [][2]int64{{800, 200}, {400, 2600}, {100, 50}, {0, 0}} {
		if err := s.RecordJobHalfPeaks(ctx, "run_1", h[0], h[1]); err != nil {
			t.Fatalf("RecordJobHalfPeaks: %v", err)
		}
	}
	// The job completes; it is the week's statistics that read it.
	done := *running
	done.State = JobCompleted
	when := versionsEpoch.Add(time.Minute)
	done.StartedAt, done.CompletedAt, done.Conclusion = &versionsEpoch, &when, "success"
	if _, _, err := s.ApplyJob(ctx, &done); err != nil {
		t.Fatal(err)
	}
	if err := s.RecordJobUsage(ctx, "run_old", 1, 500); err != nil {
		t.Fatal(err)
	}
	since := versionsEpoch.Add(-24 * time.Hour)
	res, err := s.JobStats(ctx, JobFilter{Since: &since}, []string{GroupByPool})
	if err != nil {
		t.Fatal(err)
	}
	if len(res.Groups) != 1 {
		t.Fatalf("groups = %d", len(res.Groups))
	}
	g := res.Groups[0]
	if g.PeakRunnerMemoryMB != 800 || g.PeakDaemonMemoryMB != 2600 || g.MeasuredHalves != 1 {
		t.Errorf("halves = runner %d, daemon %d from %d jobs; want 800, 2600 from 1", g.PeakRunnerMemoryMB, g.PeakDaemonMemoryMB, g.MeasuredHalves)
	}
}

// Every host read counts its live runners, and removed and failed ones are kept for the
// history, so the count has to be answered from the live rows alone: a covering read of the
// partial index, not a walk of every runner the host ever had.
func TestLiveRunnerCountReadsOnlyThePartialIndex(t *testing.T) {
	s := newTestStore(t)
	rows, err := s.read.QueryContext(t.Context(), "EXPLAIN QUERY PLAN "+countRunnersByHostSQL)
	if err != nil {
		t.Fatalf("EXPLAIN QUERY PLAN: %v", err)
	}
	defer rows.Close()
	var plan []string
	for rows.Next() {
		var id, parent, notused int
		var detail string
		if err := rows.Scan(&id, &parent, &notused, &detail); err != nil {
			t.Fatal(err)
		}
		plan = append(plan, detail)
	}
	if joined := strings.Join(plan, "\n"); !strings.Contains(joined, "COVERING INDEX idx_runners_live_host") {
		t.Fatalf("the live runner count does not read its partial index:\n%s", joined)
	}
}

// How full each of a job's in-memory folders got is kept on the job the way
// its memory peak is: raised by every sample and never lowered, only while
// GitHub says the job is in progress on that runner. A folder that filled is
// what the explanation reads from after the runner, and the folder, are gone.
func TestAJobKeepsTheFullestEachInMemoryFolderGot(t *testing.T) {
	ctx := context.Background()
	s := newTestStore(t)
	_, pool, host := seedPool(t, s)
	r := &Runner{PoolID: pool.ID, HostID: host.ID, Name: "full", State: RunnerBusy}
	if err := s.CreateRunner(ctx, r); err != nil {
		t.Fatal(err)
	}
	started := s.Now()
	job, err := s.UpsertJob(ctx, &Job{GitHubJobID: 77, Repo: "acme/widgets", Workflow: "CI", JobName: "build",
		State: JobInProgress, PoolID: pool.ID, RunnerID: r.ID, QueuedAt: started, StartedAt: &started, Matched: true})
	if err != nil {
		t.Fatal(err)
	}
	for _, sample := range [][]ScratchPeak{
		{{Path: "/tmp", PeakMB: 400, SizeMB: 1024}, {Path: "/home/runner/_work", PeakMB: 300, SizeMB: 4096}},
		{{Path: "/tmp", PeakMB: 962, SizeMB: 1024}},
		{{Path: "/tmp", PeakMB: 10, SizeMB: 1024}, {Path: "/home/runner/_work", PeakMB: 250, SizeMB: 4096}},
	} {
		if err := s.RecordJobScratchPeaks(ctx, r.ID, sample); err != nil {
			t.Fatal(err)
		}
	}
	got, err := s.GetJob(ctx, job.ID)
	if err != nil {
		t.Fatal(err)
	}
	want := ScratchPeaks{{Path: "/home/runner/_work", PeakMB: 300, SizeMB: 4096}, {Path: "/tmp", PeakMB: 962, SizeMB: 1024}}
	if len(got.ScratchPeaks) != 2 || got.ScratchPeaks[0] != want[0] || got.ScratchPeaks[1] != want[1] {
		t.Fatalf("scratch peaks = %+v, want %+v: the fullest each folder got, by path", got.ScratchPeaks, want)
	}
	fullest, fraction, ok := got.ScratchPeaks.Fullest()
	if !ok || fullest.Path != "/tmp" || fraction < 0.93 || fraction > 0.95 {
		t.Fatalf("fullest = %+v at %.2f, %v; want /tmp at about 0.94", fullest, fraction, ok)
	}

	// A sample after the job is over charges nothing to it.
	done := s.Now()
	if _, err := s.UpsertJob(ctx, &Job{GitHubJobID: 77, Repo: job.Repo, State: JobCompleted, Conclusion: "failure", StartedAt: &started, CompletedAt: &done}); err != nil {
		t.Fatal(err)
	}
	if err := s.RecordJobScratchPeaks(ctx, r.ID, []ScratchPeak{{Path: "/tmp", PeakMB: 1024, SizeMB: 1024}}); err != nil {
		t.Fatal(err)
	}
	if got, _ := s.GetJob(ctx, job.ID); got.ScratchPeaks[1].PeakMB != 962 {
		t.Fatalf("scratch peaks = %+v after the job ended, want them untouched", got.ScratchPeaks)
	}
	if _, _, ok := (ScratchPeaks{}).Fullest(); ok {
		t.Fatal("no folders is no fullest folder")
	}
}

package store

import (
	"context"
	"database/sql"
	"fmt"
	"slices"
	"testing"
	"time"
)

var versionsEpoch = time.Date(2026, 3, 1, 12, 0, 0, 0, time.UTC)

// versionJob records a completed job with the given timings and stamps it. A
// blank version leaves the job the way one recorded before migration 0060 is:
// never stamped.
func versionJob(t *testing.T, s *Store, n int, version, name string, queued time.Time, wait, run time.Duration, conclusion string) *Job {
	t.Helper()
	ctx := context.Background()
	started, done := queued.Add(wait), queued.Add(wait+run)
	j, _, err := s.ApplyJob(ctx, &Job{
		GitHubJobID: int64(1000 + n), Repo: "acme/widgets", Workflow: "ci", JobName: name,
		Labels: StringSlice{"self-hosted"}, State: JobCompleted, Conclusion: conclusion,
		QueuedAt: queued, StartedAt: &started, CompletedAt: &done, Matched: true, PoolID: "pool_a",
	})
	if err != nil {
		t.Fatalf("recording job %d: %v", n, err)
	}
	if version != "" {
		j, err = s.StampJobVersions(ctx, j.ID, JobVersions{
			ControllerVersion: version, ControllerChannel: "stable", AgentVersion: "agent-" + version, HostID: "host_1",
		})
		if err != nil {
			t.Fatalf("stamping job %d: %v", n, err)
		}
	}
	return j
}

// A job's numbers belong to the build that produced them. If a later delivery
// -- the completion, a re-run, the poller repeating the claim -- could restamp
// the row, a release comparison would move jobs between releases whenever the
// controller was upgraded mid-flight.
func TestJobVersionsAreStampedOnceAndSurviveLaterUpdates(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	j, _, err := s.ApplyJob(ctx, &Job{GitHubJobID: 1, Repo: "acme/widgets", JobName: "build", State: JobQueued,
		Labels: StringSlice{"self-hosted"}, PoolID: "pool_a", Matched: true})
	if err != nil {
		t.Fatal(err)
	}
	if j.ControllerVersion != "" || j.HostID != "" {
		t.Fatalf("a new job carries versions: %+v", j)
	}

	// The claim knows the controller; the host is not known yet.
	got, err := s.StampJobVersions(ctx, j.ID, JobVersions{ControllerVersion: "v1.3.2", ControllerChannel: "stable"})
	if err != nil {
		t.Fatal(err)
	}
	if got.ControllerVersion != "v1.3.2" || got.ControllerChannel != "stable" || got.AgentVersion != "" || got.HostID != "" {
		t.Fatalf("claim stamp = %+v, want the controller's pair only", got)
	}

	// The runner's pickup fills in the host's pair and must not touch the first.
	got, err = s.StampJobVersions(ctx, j.ID, JobVersions{
		ControllerVersion: "v1.3.3", ControllerChannel: "edge", AgentVersion: "v1.3.1", HostID: "host_a"})
	if err != nil {
		t.Fatal(err)
	}
	if got.ControllerVersion != "v1.3.2" || got.ControllerChannel != "stable" || got.AgentVersion != "v1.3.1" || got.HostID != "host_a" {
		t.Fatalf("pickup stamp = %+v, want the controller's pair kept and the host's added", got)
	}

	// Nothing after that moves any of it, not another stamp and not a status update.
	if _, err := s.StampJobVersions(ctx, j.ID, JobVersions{
		ControllerVersion: "v9", ControllerChannel: "x", AgentVersion: "v9", HostID: "host_b"}); err != nil {
		t.Fatal(err)
	}
	started, done := versionsEpoch, versionsEpoch.Add(time.Minute)
	final, _, err := s.ApplyJob(ctx, &Job{GitHubJobID: 1, State: JobCompleted, Conclusion: "success",
		StartedAt: &started, CompletedAt: &done})
	if err != nil {
		t.Fatal(err)
	}
	reread, err := s.GetJob(ctx, j.ID)
	if err != nil {
		t.Fatal(err)
	}
	for name, job := range map[string]*Job{"the update's result": final, "a fresh read": reread} {
		if job.ControllerVersion != "v1.3.2" || job.ControllerChannel != "stable" || job.AgentVersion != "v1.3.1" || job.HostID != "host_a" {
			t.Errorf("%s = %+v, want the first stamps", name, job)
		}
	}
}

