// "Occupies a slot on its host" is defined twice: RunnerState.Live for the
// scheduler's pool arithmetic, and the state filter in the SQL that fills
// Host.ActiveRunners for host capacity. Nothing held the two definitions
// equal, so a state added to one and not the other would have a pool and its
// hosts disagreeing about how full the fleet is. This test is the equation.
func TestAHostsActiveRunnersAreExactlyItsLiveRows(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	_, pool, host := seedPool(t, s)

	states := []RunnerState{
		RunnerProvisioning, RunnerRegistering, RunnerIdle, RunnerBusy,
		RunnerDraining, RunnerRemoved, RunnerFailed,
	}
	live := 0
	for _, state := range states {
		if err := s.CreateRunner(ctx, &Runner{PoolID: pool.ID, HostID: host.ID, Name: "runner-" + string(state), State: state}); err != nil {
			t.Fatalf("CreateRunner in %s: %v", state, err)
		}
		if state.Live() {
			live++
		}
	}

	got, err := s.GetHost(ctx, host.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if got.ActiveRunners != live {
		t.Fatalf("ActiveRunners = %d with one runner in each of the %d states, want the %d whose state is Live", got.ActiveRunners, len(states), live)
	}
	if live == 0 || live == len(states) {
		t.Fatalf("Live is true for %d of %d states; the test needs both kinds to mean anything", live, len(states))
	}
}

package store

import (
	"fmt"
	"path/filepath"
	"strings"
)

// LockPath is the file a controller takes an exclusive lock on before it opens
// the database. It sits beside the database rather than in the state directory
// as such, because the database is the thing two controllers actually contend
// for: a second one pointed at the same file through a different state
// directory is the same disaster.
func LockPath(dbPath string) string {
	return filepath.Join(filepath.Dir(dbPath), filepath.Base(dbPath)+".lock")
}

// Lock takes an exclusive, non-blocking lock for the database at path and
// returns the release. It answers ErrLocked when another process holds it.
//
// Non-blocking on purpose: a controller that waited would look like a
// controller that is starting slowly, and the operator would be left watching
// a process that never binds its port and never says why.
//
// An in-memory database is nobody else's, so it is not locked.
func Lock(dbPath string) (func() error, error) {
	if dbPath == "" || strings.HasPrefix(dbPath, ":memory:") || strings.Contains(dbPath, "mode=memory") {
		return func() error { return nil }, nil
	}
	return lockFile(LockPath(dbPath))
}

// ErrLocked is another process holding the database lock on this host. It is
// distinct from a permission or disk failure, because the answer differs: one
// is "a controller is already running here", the other is "this process cannot
// write where it was told to".
var ErrLocked = fmt.Errorf("another process holds the database lock")

//go:build !unix && !windows

package store

// lockFile is the fallback for a platform this project does not release
// binaries for. There is no lock, and the controller lease in the database is
// the only thing standing between two controllers -- which is what catches the
// cross-machine case anyway, so the gap is narrower than it looks.
func lockFile(string) (func() error, error) {
	return func() error { return nil }, nil
}

