	pub := &OptimisationShardingPublication{PreviewID: r.ID, InstallationID: r.InstallationID, Repository: r.Repository, PublishedBy: "usr_actor", Branch: "zoomies/sharding-" + r.ID, BaseBranch: "main", BaseSHA: head, HeadSHA: head, SourceSHA256: source, PreviewSHA256: r.SHA256, PullNumber: 12, PullURL: "https://github.com/acme/repo/pull/12"}
	if err := s.PutOptimisationShardingPublication(ctx, pub, optimisationAudit()); !errors.Is(err, ErrConflict) {
		t.Fatalf("unapproved preview published: %v", err)
	}
	if _, err := s.ApproveOptimisationShardingPreview(ctx, r.InstallationID, r.Repository, r.ID, head, source, r.SHA256, optimisationAudit()); err != nil {
		t.Fatal(err)
	}
	now = now.Add(OptimisationShardingPreviewRetention)
	if err := s.PutOptimisationShardingPublication(ctx, pub, optimisationAudit()); !errors.Is(err, ErrNotFound) {
		t.Fatalf("expired preview published: %v", err)
	}
}

