import (
	"context"
	"reflect"
	"testing"
	"time"
)

// A claim asks which pool takes a job, and answers from a handful of a pool's
// fields. Reading the other thirty of every row, and decoding ten JSON
// documents in each, was most of what a webhook delivery cost at a hundred
// pools, so a claim reads the handful, and the pools it gets carry only those.
// ClaimView says which they are, so that what a read returns and what a test
// strips a whole pool to cannot drift apart.

func TestListPoolsForClaimReturnsWhatAClaimReadsOfEveryPool(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()

	one := &Installation{AppID: 1, InstallationID: 2, Target: "acme", TargetType: TargetOrg}
	two := &Installation{AppID: 1, InstallationID: 3, Target: "widgets", TargetType: TargetOrg}
	for _, inst := range []*Installation{one, two} {
		if err := s.CreateInstallation(ctx, inst); err != nil {
			t.Fatalf("CreateInstallation: %v", err)
		}
	}

	// Pools that differ in the fields a claim reads and, as they do in a real
	// fleet, in a good many it does not.
	pools := []*Pool{
		{Name: "linux-x64", InstallationID: one.ID, Labels: StringSlice{"linux", "docker"},
			Backend: BackendDocker, Platform: Platform{OS: "ubuntu", OSVersion: "24.04", Arch: "amd64"},
			MaxRunners: 4, Enabled: true, Ephemeral: true, Image: "ghcr.io/example/runner:1", DockerMode: DockerNone},
		{Name: "arm", InstallationID: one.ID, Labels: StringSlice{"arm64"}, NoDefaultLabels: true,
			Backend: BackendProcess, Platform: Platform{Arch: "arm64"}, MaxRunners: 2, Enabled: true, DockerMode: DockerNone,
			Env: StringMap{"A": "b"}, HostSelector: StringMap{"zone": "a"}},
		{Name: "kept", InstallationID: two.ID, Labels: StringSlice{"gpu"}, AutoKey: "arm64/large",
			Backend: BackendDocker, Platform: Platform{Arch: "arm64"}, MaxRunners: 8, Enabled: false, DockerMode: DockerNone,
			Resources: Resources{CPUs: 8, MemoryMB: 16384}, ProviderSelector: StringMap{"kind": "proxmox"}},
		{Name: "bare", InstallationID: two.ID, Backend: BackendDocker, MaxRunners: 1, Enabled: true, DockerMode: DockerNone},
	}
	for _, p := range pools {
		if err := s.CreatePool(ctx, p); err != nil {
			t.Fatalf("CreatePool %s: %v", p.Name, err)
		}
	}

	whole, err := s.ListPools(ctx)
	if err != nil {
		t.Fatalf("ListPools: %v", err)
	}
	got, err := s.ListPoolsForClaim(ctx)
	if err != nil {
		t.Fatalf("ListPoolsForClaim: %v", err)
	}
	if len(got) != len(whole) || len(whole) != len(pools) {
		t.Fatalf("ListPoolsForClaim returned %d pools, ListPools %d, and %d were made", len(got), len(whole), len(pools))
	}
	for i, p := range whole {
		if want := ClaimView(p); !reflect.DeepEqual(got[i], want) {
			t.Errorf("pool %s as read for a claim is\n%+v\nwant the claim view of the whole pool\n%+v", p.Name, got[i], want)
		}
	}
}

func TestAClaimViewKeepsWhatAClaimReadsAndNothingElse(t *testing.T) {
	now := time.Date(2026, 10, 18, 12, 0, 0, 0, time.UTC)
	p := &Pool{
		ID: "pool_1", Name: "gpu", InstallationID: "inst_1", Labels: StringSlice{"gpu", "linux"},
		Backend: BackendDocker, Platform: Platform{OS: "ubuntu", OSVersion: "24.04", Arch: "arm64"},
		AutoKey: "arm64/large", Enabled: true, NoDefaultLabels: true,
		MaxRunners: 8, Priority: 3, Image: "img", Env: StringMap{"A": "b"}, CreatedAt: now, UpdatedAt: now,
	}
	want := &Pool{
		ID: "pool_1", Name: "gpu", InstallationID: "inst_1", Labels: StringSlice{"gpu", "linux"},
		Backend: BackendDocker, Platform: Platform{Arch: "arm64"},
		AutoKey: "arm64/large", Enabled: true, NoDefaultLabels: true,
	}
	if got := ClaimView(p); !reflect.DeepEqual(got, want) {
		t.Errorf("ClaimView = %+v, want %+v", got, want)
	}
	if p.MaxRunners != 8 || p.Image != "img" || p.Platform.OS != "ubuntu" {
		t.Errorf("ClaimView changed the pool it was given: %+v", p)
	}
}

package store

import (
	"context"
	"encoding/json"
	"fmt"
	"reflect"
	"testing"
	"time"
)

// A pool row keeps ten documents in TEXT columns, and nearly all of them are
// what a column holds until somebody sets it: an empty object, an empty list, or
// the encoding of a type with nothing set. Those decode to the zero value and to
// nothing else, so reading a row does not hand them to the decoder, which was
// most of what reading a pool cost. These tests hold that shortcut to the
// decoder's own answer, for the documents it takes and for the ones that only
// look like them.

// scanPoolDecodingEverything is scanPool as it was before the shortcut: every
// document goes through encoding/json, and the columns that are lists and maps
// are read as text and decoded here, the way StringSlice and StringMap used to
// read them.
func scanPoolDecodingEverything(sc interface{ Scan(...any) error }) (*Pool, error) {
	var p Pool
	var idle, created, updated int64
	var ephemeral, runAsRoot, enabled, noDefaultLabels, sizeFromProfile, autoPaused int
	var labels, hostSelector, env, providerSelector string
	var resources, cache, runnerSettings, cpuBurst, tmpfs, memoryBurst string
	err := sc.Scan(&p.ID, &p.Name, &p.InstallationID, &labels, &p.RunnerGroup, &p.Backend,
		&p.Platform.OS, &p.Platform.OSVersion, &p.Platform.Arch,
		&p.Image, &p.PullPolicy, &p.RunnerVersion, &p.MinRunners, &p.MaxRunners, &p.Priority,
		&idle, &ephemeral, &p.DockerMode, &resources, &cache, &hostSelector, &env,
		&runAsRoot, &enabled, &created, &updated, &p.RepositoryScaleUpLimit, &p.CostPerRunnerHour,
		&runnerSettings, &cpuBurst, &noDefaultLabels, &sizeFromProfile, &tmpfs,
		&p.AutoKey, &p.AutoMin, &p.AutoCap, &autoPaused, &memoryBurst, &providerSelector, &p.DinDImage)
	if err != nil {
		return nil, err
	}
	p.NoDefaultLabels = noDefaultLabels == 1
	p.SizeFromProfile = sizeFromProfile == 1
	p.AutoPaused = autoPaused == 1
	p.IdleTimeout = Duration(time.Duration(idle) * time.Millisecond)
	p.Ephemeral, p.RunAsRoot, p.Enabled = ephemeral == 1, runAsRoot == 1, enabled == 1
	p.CreatedAt, p.UpdatedAt = at(created), at(updated)
	for _, d := range []struct {
		doc string
		out any
	}{
		{labels, &p.Labels}, {hostSelector, &p.HostSelector}, {env, &p.Env}, {providerSelector, &p.ProviderSelector},
		{resources, &p.Resources}, {cache, &p.Cache}, {runnerSettings, &p.RunnerSettings},
		{cpuBurst, &p.CPUBurst}, {tmpfs, &p.Tmpfs}, {memoryBurst, &p.MemoryBurst},
	} {
		if err := unmarshalJSON(d.doc, d.out); err != nil {
			return nil, err
		}
	}
	return &p, nil
}

func listPoolsDecodingEverything(t *testing.T, s *Store) []*Pool {
	t.Helper()
	rows, err := s.read.QueryContext(context.Background(), `SELECT `+poolCols+` FROM pools ORDER BY name`)
	if err != nil {
		t.Fatalf("reading the pools: %v", err)
	}
	defer rows.Close()
	var out []*Pool
	for rows.Next() {
		p, err := scanPoolDecodingEverything(rows)
		if err != nil {
			t.Fatalf("decoding a pool: %v", err)
		}
		out = append(out, p)
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("reading the pools: %v", err)
	}
	return out
}

func TestPoolsReadBackAsTheDecoderAloneWouldReadThem(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	inst := &Installation{AppID: 1, InstallationID: 2, Target: "acme", TargetType: TargetOrg}
	if err := s.CreateInstallation(ctx, inst); err != nil {
		t.Fatalf("CreateInstallation: %v", err)
	}

	// Pools as they are made: nothing configured, and a good deal configured.
	n := 0
	for _, make := range []func(*Installation, int) *Pool{defaultBenchPool, configuredBenchPool} {
		n++
		if err := s.CreatePool(ctx, make(inst, n)); err != nil {
			t.Fatalf("CreatePool: %v", err)
		}
	}

	// And one pool for each document a column could hold that is not one of those:
	// the shapes the shortcut takes, and the ones that merely look like them.
	zeroCache, zeroTmpfs := zeroDoc[CacheConfig](), zeroDoc[TmpfsConfig]()
	structs := []string{"", "{}", " {} ", "{ }", "null", `{"unknown":1}`, `{"cpus":2}`}
	byColumn := map[string][]string{
		"resources":         structs,
		"runner_settings":   structs,
		"cpu_burst":         structs,
		"memory_burst":      structs,
		"cache":             append([]string{zeroCache, `{"scope":"","enabled":false}`, " " + zeroCache, `{"enabled":true}`}, structs...),
		"tmpfs":             append([]string{zeroTmpfs, " " + zeroTmpfs, `{"work":{"enabled":true}}`}, structs...),
		"labels":            {"", "[]", " [] ", "[ ]", "null", `["b","a"]`, `[""]`},
		"host_selector":     {"", "{}", " {} ", "{ }", "null", `{"a":"b"}`},
		"env":               {"", "{}", " {} ", "{ }", "null", `{"a":"b"}`},
		"provider_selector": {"", "{}", " {} ", "{ }", "null", `{"a":"b"}`},
	}
	for column, docs := range byColumn {
		for i, doc := range docs {
			n++
			p := defaultBenchPool(inst, n)
			p.Name = fmt.Sprintf("%s-%d", column, i)
			if err := s.CreatePool(ctx, p); err != nil {
				t.Fatalf("CreatePool: %v", err)
			}
			if _, err := s.write.ExecContext(ctx, `UPDATE pools SET `+column+` = ? WHERE id = ?`, doc, p.ID); err != nil {
				t.Fatalf("setting %s to %q: %v", column, doc, err)
			}
		}
	}

	want := listPoolsDecodingEverything(t, s)
	got, err := s.ListPools(ctx)
	if err != nil {
		t.Fatalf("ListPools: %v", err)
	}
	if len(got) != len(want) || len(want) != n {
		t.Fatalf("ListPools returned %d pools, the decoder alone %d, and %d were made", len(got), len(want), n)
	}
	for i := range want {
		if !reflect.DeepEqual(got[i], want[i]) {
			t.Errorf("pool %s reads back as\n%+v\nwant what the decoder alone gives\n%+v", want[i].Name, got[i], want[i])
		}
		one, err := s.GetPool(ctx, want[i].ID)
		if err != nil || !reflect.DeepEqual(one, want[i]) {
			t.Errorf("GetPool(%s) = %+v, %v; want what the decoder alone gives\n%+v", want[i].Name, one, err, want[i])
		}
	}
}

// StringSlice and StringMap persist a list and a map in a TEXT column, in a
// good many tables. Scanning the empty one does not call the decoder, and has to
// leave exactly what the decoder would: an empty list that is not nil.
func TestScanningAnEmptyListOrMapGivesWhatTheDecoderGives(t *testing.T) {
	inputs := []any{
		nil, "", []byte(nil), []byte{}, "[]", []byte("[]"), "{}", []byte("{}"), " [] ", " {} ", "null", []byte("null"),
		`["a"]`, `{"a":"b"}`, `[]x`, `{}x`,
	}
	for _, in := range inputs {
		var gotSlice StringSlice
		var gotMap StringMap
		gotSliceErr, gotMapErr := gotSlice.Scan(in), gotMap.Scan(in)

		wantSlice, wantSliceErr := decodeAsBefore[StringSlice](in)
		wantMap, wantMapErr := decodeAsBefore[StringMap](in)

		if (gotSliceErr == nil) != (wantSliceErr == nil) || !reflect.DeepEqual(gotSlice, wantSlice) {
			t.Errorf("StringSlice.Scan(%#v) = %#v, %v; the decoder gives %#v, %v", in, gotSlice, gotSliceErr, wantSlice, wantSliceErr)
		}
		if (gotMapErr == nil) != (wantMapErr == nil) || !reflect.DeepEqual(gotMap, wantMap) {
			t.Errorf("StringMap.Scan(%#v) = %#v, %v; the decoder gives %#v, %v", in, gotMap, gotMapErr, wantMap, wantMapErr)
		}
	}
}

// decodeAsBefore is what StringSlice.Scan and StringMap.Scan did with every
// input before they knew the empty ones.
func decodeAsBefore[T any](in any) (T, error) {
	var out T
	switch t := in.(type) {
	case nil:
		return out, nil
	case []byte:
		if len(t) == 0 {
			return out, nil
		}
		err := json.Unmarshal(t, &out)
		return out, err
	case string:
		if t == "" {
			return out, nil
		}
		err := json.Unmarshal([]byte(t), &out)
		return out, err
	}
	return out, fmt.Errorf("cannot scan %T", in)
}

// The shortcut is only right while a type's zero value encodes to a document that
// decodes back to the zero value. Add a field whose zero does not, and this fails
// before a pool reads back wrong.
func TestTheDocumentAZeroPoolSettingEncodesToDecodesBackToIt(t *testing.T) {
	check := func(name string, doc string, decoded any, zero any) {
		t.Helper()
		if doc == "" {
			t.Errorf("%s: the zero value does not encode", name)
			return
		}
		if err := json.Unmarshal([]byte(doc), decoded); err != nil {
			t.Errorf("%s: %q does not decode: %v", name, doc, err)
			return
		}
		if !reflect.DeepEqual(reflect.ValueOf(decoded).Elem().Interface(), zero) {
			t.Errorf("%s: %q decodes to %+v, not to the zero value", name, doc, reflect.ValueOf(decoded).Elem().Interface())
		}
	}
	check("resources", zeroDoc[Resources](), new(Resources), Resources{})
	check("cache", zeroDoc[CacheConfig](), new(CacheConfig), CacheConfig{})
	check("runner settings", zeroDoc[RunnerSettings](), new(RunnerSettings), RunnerSettings{})
	check("CPU burst", zeroDoc[CPUBurstPolicy](), new(CPUBurstPolicy), CPUBurstPolicy{})
	check("tmpfs", zeroDoc[TmpfsConfig](), new(TmpfsConfig), TmpfsConfig{})
	check("memory burst", zeroDoc[MemoryBurstPolicy](), new(MemoryBurstPolicy), MemoryBurstPolicy{})
}

package store

import (
	"context"
	"database/sql"
	"errors"
	"time"
)

// ErrTooManyDismissals is what ApplyProblemDismissals returns when the change
// would leave an account holding more than the limit it was given. Nothing of
// the change is applied.
var ErrTooManyDismissals = errors.New("too many dismissed problems")

// ProblemDismissal is one problem, or one kind of problem, an account has put
// away. The store treats Key as opaque: what makes two reports "the same
// problem" is the UI's definition, and a second one here would only drift.
type ProblemDismissal struct {
	Key         string
	Severity    string
	DismissedAt time.Time
	// Until is when a snooze ends. Nil is a dismissal that lasts until the
	// client sees the problem resolved.
	Until *time.Time
}

// ProblemDismissals returns what the account has put away and that still
// stands. A snooze whose time has passed is spent, so it is deleted here rather
// than returned: reading is the one moment every client passes through, which
// keeps the table from collecting rows nobody will ever look at again.
func (s *Store) ProblemDismissals(ctx context.Context, userID string) ([]ProblemDismissal, error) {
	if !s.readOnly {
		if _, err := s.exec(ctx,
			`DELETE FROM problem_dismissals WHERE user_id = ? AND until IS NOT NULL AND until <= ?`,
			userID, ms(s.Now())); err != nil {
			return nil, err
		}
	}
	rows, err := s.read.QueryContext(ctx,
		`SELECT key, severity, dismissed_at, until FROM problem_dismissals
		 WHERE user_id = ? ORDER BY dismissed_at, key`, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []ProblemDismissal{}
	for rows.Next() {
		var (
			d     ProblemDismissal
			dAt   int64
			until sql.NullInt64
		)
		if err := rows.Scan(&d.Key, &d.Severity, &dAt, &until); err != nil {
			return nil, err
		}
		d.DismissedAt = at(dAt)
		d.Until = atp(until)
		out = append(out, d)
	}
	return out, rows.Err()
}

// ApplyProblemDismissals adds, replaces and removes an account's dismissals as
// one change. A set for a key already held replaces it, so snoozing a problem
// again with a different length is the same call as the first time. The batch
// is atomic because "dismiss all" is one gesture: half of it applying would
// leave the drawer showing a state nobody chose.
//
// limit bounds what the account holds afterwards, and is checked on the rows
// the transaction actually leaves rather than on arithmetic over the request: a
// removal of a key never held frees nothing, and two requests that each looked
// small beside the count they read would otherwise both fit. The single writer
// is what makes the count inside the transaction the count that is kept.
func (s *Store) ApplyProblemDismissals(ctx context.Context, userID string, set []ProblemDismissal, remove []string, limit int) error {
	return wrapWrite(s.tx(ctx, func(t *sql.Tx) error {
		for _, key := range remove {
			if _, err := t.ExecContext(ctx,
				`DELETE FROM problem_dismissals WHERE user_id = ? AND key = ?`, userID, key); err != nil {
				return err
			}
		}
		for _, d := range set {
			if _, err := t.ExecContext(ctx,
				`INSERT INTO problem_dismissals (user_id, key, severity, dismissed_at, until)
				 VALUES (?, ?, ?, ?, ?) ON CONFLICT(user_id, key) DO UPDATE SET
				 severity=excluded.severity, dismissed_at=excluded.dismissed_at, until=excluded.until`,
				userID, d.Key, d.Severity, ms(d.DismissedAt), msp(d.Until)); err != nil {
				return err
			}
		}
		var held int
		if err := t.QueryRowContext(ctx,
			`SELECT COUNT(*) FROM problem_dismissals WHERE user_id = ?`, userID).Scan(&held); err != nil {
			return err
		}
		if limit > 0 && held > limit {
			return ErrTooManyDismissals
		}
		return nil
	}))
}

// CountProblemDismissals is how many an account holds, for the API to bound
// what one account can keep.
func (s *Store) CountProblemDismissals(ctx context.Context, userID string) (int, error) {
	var n int
	err := s.read.QueryRowContext(ctx,
		`SELECT COUNT(*) FROM problem_dismissals WHERE user_id = ?`, userID).Scan(&n)
	return n, err
}

package store

import (
	"context"
	"errors"
	"fmt"
	"testing"
	"time"
)

// A snooze exists so an operator stops being asked for a while. If it lived
// only in one browser, the second tab or the phone would ask again -- so it is
// the account's, and private to it.
func TestProblemDismissalsBelongToTheAccountAndSurviveReopening(t *testing.T) {
	ctx := context.Background()
	now := time.Date(2026, 10, 5, 12, 0, 0, 0, time.UTC)
	s := newTestStoreAt(t, func() time.Time { return now })
	alice := &User{Username: "alice", Role: RoleViewer}
	bob := &User{Username: "bob", Role: RoleViewer}
	for _, u := range []*User{alice, bob} {
		if err := s.CreateUser(ctx, u); err != nil {
			t.Fatalf("CreateUser(%s): %v", u.Username, err)
		}
	}
	until := now.Add(24 * time.Hour)
	err := s.ApplyProblemDismissals(ctx, alice.ID, []ProblemDismissal{
		{Key: "type:pool.no_capacity", Severity: "warning", DismissedAt: now, Until: &until},
		{Key: "auth.disabled|||", Severity: "error", DismissedAt: now},
	}, nil, 100)
	if err != nil {
		t.Fatalf("ApplyProblemDismissals: %v", err)
	}

	got, err := s.ProblemDismissals(ctx, alice.ID)
	if err != nil {
		t.Fatalf("ProblemDismissals(alice): %v", err)
	}
	if len(got) != 2 {
		t.Fatalf("alice holds %d dismissals, want 2: %+v", len(got), got)
	}
	var snooze *ProblemDismissal
	for i := range got {
		if got[i].Key == "type:pool.no_capacity" {
			snooze = &got[i]
		}
	}
	if snooze == nil || snooze.Until == nil || !snooze.Until.Equal(until) || snooze.Severity != "warning" {
		t.Fatalf("the snooze did not round-trip: %+v", snooze)
	}

	other, err := s.ProblemDismissals(ctx, bob.ID)
	if err != nil {
		t.Fatalf("ProblemDismissals(bob): %v", err)
	}
	if len(other) != 0 {
		t.Fatalf("bob inherited alice's dismissals: %+v", other)
	}
}

// Two tabs each put a different problem away. The second write must add to the
// first, not replace it -- that last-writer-wins overwrite is what the browser
// copy suffered from.
func TestApplyingProblemDismissalsAddsToWhatIsHeldAndReplacesTheSameKey(t *testing.T) {
	ctx := context.Background()
	now := time.Date(2026, 10, 5, 12, 0, 0, 0, time.UTC)
	s := newTestStoreAt(t, func() time.Time { return now })
	u := &User{Username: "alice", Role: RoleViewer}
	if err := s.CreateUser(ctx, u); err != nil {
		t.Fatal(err)
	}
	short := now.Add(15 * time.Minute)
	long := now.Add(24 * time.Hour)
	apply := func(set []ProblemDismissal, remove []string) {
		t.Helper()
		if err := s.ApplyProblemDismissals(ctx, u.ID, set, remove, 100); err != nil {
			t.Fatalf("ApplyProblemDismissals: %v", err)
		}
	}
	apply([]ProblemDismissal{{Key: "a", Severity: "info", DismissedAt: now, Until: &short}}, nil)
	apply([]ProblemDismissal{{Key: "b", Severity: "info", DismissedAt: now}}, nil)
	apply([]ProblemDismissal{{Key: "a", Severity: "warning", DismissedAt: now, Until: &long}}, nil)

	got, _ := s.ProblemDismissals(ctx, u.ID)
	if len(got) != 2 {
		t.Fatalf("held %d, want both tabs' decisions: %+v", len(got), got)
	}
	for _, d := range got {
		if d.Key == "a" && (d.Severity != "warning" || d.Until == nil || !d.Until.Equal(long)) {
			t.Fatalf("snoozing again did not replace the earlier snooze: %+v", d)
		}
	}

	apply(nil, []string{"a", "never-held"})
	got, _ = s.ProblemDismissals(ctx, u.ID)
	if len(got) != 1 || got[0].Key != "b" {
		t.Fatalf("after restoring a, held %+v, want only b", got)
	}
}

// A snooze is spent when its clock runs out, and it must not need a browser
// open at that moment to be so: the row is gone the next time anyone asks.
func TestAnExpiredSnoozeIsNotReturnedAndAPlainDismissalIsKept(t *testing.T) {
	ctx := context.Background()
	now := time.Date(2026, 10, 5, 12, 0, 0, 0, time.UTC)
	s := newTestStoreAt(t, func() time.Time { return now })
	u := &User{Username: "alice", Role: RoleViewer}
	if err := s.CreateUser(ctx, u); err != nil {
		t.Fatal(err)
	}
	until := now.Add(time.Hour)
	if err := s.ApplyProblemDismissals(ctx, u.ID, []ProblemDismissal{
		{Key: "snoozed", Severity: "info", DismissedAt: now, Until: &until},
		{Key: "plain", Severity: "info", DismissedAt: now},
	}, nil, 100); err != nil {
		t.Fatal(err)
	}

	now = now.Add(2 * time.Hour)
	got, err := s.ProblemDismissals(ctx, u.ID)
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 1 || got[0].Key != "plain" {
		t.Fatalf("after the snooze ran out got %+v, want only the plain dismissal", got)
	}
	if n, _ := s.CountProblemDismissals(ctx, u.ID); n != 1 {
		t.Fatalf("the expired snooze row was left behind: %d rows", n)
	}
}

func TestDeletingAnAccountDeletesItsDismissals(t *testing.T) {
	ctx := context.Background()
	s := newTestStore(t)
	u := &User{Username: "alice", Role: RoleViewer}
	if err := s.CreateUser(ctx, u); err != nil {
		t.Fatal(err)
	}
	if err := s.ApplyProblemDismissals(ctx, u.ID,
		[]ProblemDismissal{{Key: "a", Severity: "info", DismissedAt: s.Now()}}, nil, 100); err != nil {
		t.Fatal(err)
	}
	if err := s.DeleteUser(ctx, u.ID); err != nil {
		t.Fatal(err)
	}
	if n, _ := s.CountProblemDismissals(ctx, u.ID); n != 0 {
		t.Fatalf("%d dismissals outlived their account", n)
	}
}

// The limit is on what the account is left holding. A removal of keys that were
// never there frees no room, so padding a request with them must not let it
// past a limit that counted on them -- and a refused change leaves nothing of
// itself behind.
func TestTheDismissalLimitIsCheckedOnTheRowsLeftAfterTheChange(t *testing.T) {
	ctx := context.Background()
	s := newTestStore(t)
	u := &User{Username: "alice", Role: RoleViewer}
	if err := s.CreateUser(ctx, u); err != nil {
		t.Fatal(err)
	}
	keys := func(prefix string, n int) []ProblemDismissal {
		out := make([]ProblemDismissal, n)
		for i := range out {
			out[i] = ProblemDismissal{Key: fmt.Sprintf("%s%d", prefix, i), Severity: "info", DismissedAt: s.Now()}
		}
		return out
	}
	if err := s.ApplyProblemDismissals(ctx, u.ID, keys("a", 3), nil, 3); err != nil {
		t.Fatalf("filling the account to its limit: %v", err)
	}

	err := s.ApplyProblemDismissals(ctx, u.ID, keys("b", 3), []string{"never-held-1", "never-held-2", "never-held-3"}, 3)
	if !errors.Is(err, ErrTooManyDismissals) {
		t.Fatalf("padding with removals that free nothing got %v, want ErrTooManyDismissals", err)
	}
	if n, _ := s.CountProblemDismissals(ctx, u.ID); n != 3 {
		t.Fatalf("a refused change left %d rows, want the original 3", n)
	}

	// Removing real rows in the same request does make room.
	if err := s.ApplyProblemDismissals(ctx, u.ID, keys("b", 3), []string{"a0", "a1", "a2"}, 3); err != nil {
		t.Fatalf("replacing what is held within the limit: %v", err)
	}
}

package store

import (
	"context"
	"database/sql"
	"testing"
)

// What this controller trusts when it reaches a hypervisor, and what a machine
// built there trusts when it reaches this controller, are two different
// certificates in general. One field answered both, so a cluster's own
// authority became the only thing every machine would accept from the
// controller, and a controller on a public certificate was refused by every
// machine it rented. They are stored apart, and changing one leaves the other.
func TestAProviderKeepsTheCertificateItsMachinesTrustApartFromItsOwn(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()

	p := &Provider{Kind: ProviderFake, Name: "lab", CAPEM: "the-clusters-authority", MachineCAPEM: "the-controllers-authority"}
	if err := s.CreateProvider(ctx, p); err != nil {
		t.Fatalf("CreateProvider: %v", err)
	}
	got, err := s.GetProvider(ctx, p.ID)
	if err != nil {
		t.Fatalf("GetProvider: %v", err)
	}
	if got.CAPEM != "the-clusters-authority" || got.MachineCAPEM != "the-controllers-authority" {
		t.Fatalf("the provider came back with ca_pem %q and machine_ca_pem %q", got.CAPEM, got.MachineCAPEM)
	}

	got.MachineCAPEM = ""
	if err := s.UpdateProvider(ctx, got); err != nil {
		t.Fatalf("UpdateProvider: %v", err)
	}
	again, err := s.GetProvider(ctx, p.ID)
	if err != nil {
		t.Fatalf("GetProvider: %v", err)
	}
	if again.MachineCAPEM != "" {
		t.Errorf("clearing the machines' certificate left %q", again.MachineCAPEM)
	}
	if again.CAPEM != "the-clusters-authority" {
		t.Errorf("clearing the machines' certificate changed the provider's own to %q", again.CAPEM)
	}

	again.MachineCAPEM = "a-new-controller-authority"
	again.CAPEM = "a-new-cluster-authority"
	if err := s.UpdateProvider(ctx, again); err != nil {
		t.Fatalf("UpdateProvider: %v", err)
	}
	last, err := s.GetProvider(ctx, p.ID)
	if err != nil {
		t.Fatalf("GetProvider: %v", err)
	}
	if last.CAPEM != "a-new-cluster-authority" || last.MachineCAPEM != "a-new-controller-authority" {
		t.Errorf("an edit of both came back as ca_pem %q and machine_ca_pem %q", last.CAPEM, last.MachineCAPEM)
	}
}

// Until now a provider's certificate was also the one its machines trusted, so
// a provider already set up that way has to go on working after the upgrade: the
// machines it builds next must be given what the machines before them were. The
// copy preserves that, and a provider with no certificate gets none, so a
// machine of its own goes on using the system's trust.
func TestAnUpgradeGivesAnExistingProviderItsCertificateAsTheOneItsMachinesTrust(t *testing.T) {
	ctx := context.Background()
	path := atSchemaBefore(t, "0101_provider_machine_ca.sql")

	const authority = "-----BEGIN CERTIFICATE-----\nthe-clusters-authority\n-----END CERTIFICATE-----"
	db, err := sql.Open("sqlite", "file:"+path+"?_pragma=foreign_keys(1)")
	if err != nil {
		t.Fatalf("sql.Open: %v", err)
	}
	for _, row := range []struct{ id, name, ca string }{
		{"prv_with", "with-authority", authority},
		{"prv_without", "without-authority", ""},
	} {
		if _, err := db.ExecContext(ctx, `INSERT INTO providers (id, kind, name, endpoint, ca_pem, created_at, updated_at)
			VALUES (?, 'fake', ?, 'https://pve.example:8006', ?, 0, 0)`, row.id, row.name, row.ca); err != nil {
			t.Fatalf("writing %s as an older release did: %v", row.id, err)
		}
	}
	if err := db.Close(); err != nil {
		t.Fatalf("closing the fixture: %v", err)
	}

	s, err := Open(ctx, Options{Path: path})
	if err != nil {
		t.Fatalf("opening the older database: %v", err)
	}
	defer s.Close()

	with, err := s.GetProvider(ctx, "prv_with")
	if err != nil {
		t.Fatalf("GetProvider: %v", err)
	}
	if with.MachineCAPEM != authority {
		t.Errorf("a provider with a certificate came out of the upgrade with machine_ca_pem %q", with.MachineCAPEM)
	}
	if with.CAPEM != authority {
		t.Errorf("the upgrade changed the provider's own certificate to %q", with.CAPEM)
	}

	without, err := s.GetProvider(ctx, "prv_without")
	if err != nil {
		t.Fatalf("GetProvider: %v", err)
	}
	if without.MachineCAPEM != "" {
		t.Errorf("a provider with no certificate came out of the upgrade with machine_ca_pem %q", without.MachineCAPEM)
	}
}

