func TestProvisioningSurvivesReplayAndRestart(t *testing.T) {
	ctx := context.Background()
	path := filepath.Join(t.TempDir(), "queue.db")
	s, err := Open(ctx, Options{Path: path})
	if err != nil {
		t.Fatal(err)
	}
	j, err := s.UpsertJob(ctx, &Job{GitHubJobID: 1, State: JobQueued, Labels: StringSlice{"self-hosted"}, Repo: "acme/app"})
	if err != nil {
		t.Fatal(err)
	}
	for _, action := range []string{"pause", "delete", "run_now", "resume"} {
		if _, err := s.ControlProvisioning(ctx, []string{j.ID}, action); err != nil {
			t.Fatal(err)
		}
		replay, err := s.UpsertJob(ctx, &Job{GitHubJobID: 1, State: JobQueued})
		if err != nil {
			t.Fatal(err)
		}
		want := ""
		if action == "pause" {
			want = "paused"
		}
		if action == "delete" {
			want = "deleted"
		}
		if replay.Provisioning != want || replay.ProvisionNow != (action == "run_now") {
			t.Fatalf("%s lost on replay: %+v", action, replay)
		}
	}
	if _, err := s.ControlProvisioning(ctx, []string{j.ID}, "pause"); err != nil {
		t.Fatal(err)
	}
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}
	s, err = Open(ctx, Options{Path: path})
	if err != nil {
		t.Fatal(err)
	}
	defer s.Close()
	got, err := s.GetJob(ctx, j.ID)
	if err != nil || got.Provisioning != "paused" {
		t.Fatalf("restart: %+v %v", got, err)
	}
}

func TestProvisioningSelectionAndStaleItems(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	makeJob := func(id int64, repo, branch string) *Job {
		j, err := s.UpsertJob(ctx, &Job{GitHubJobID: id, State: JobQueued, Repo: repo, HeadBranch: branch, Labels: StringSlice{"self-hosted", "linux"}})
		if err != nil {
			t.Fatal(err)
		}
		return j
	}
	first := makeJob(1, "acme/one", "main")
	second := makeJob(2, "acme/two", "main")
	makeJob(3, "acme/one", "dev")
	ids, err := s.ProvisioningSelection(ctx, JobFilter{Repos: []string{"acme/one", "acme/two"}, Branches: []string{"main"}, Labels: []string{"linux"}})
	if err != nil || len(ids) != 2 {
		t.Fatalf("selection: %v %v", ids, err)
	}
	late := makeJob(4, "acme/one", "main")
	if _, err := s.UpsertJob(ctx, &Job{GitHubJobID: second.GitHubJobID, State: JobInProgress}); err != nil {
		t.Fatal(err)
	}
	results, err := s.ControlProvisioning(ctx, append(ids, first.ID, "missing"), "delete")
	if err != nil || len(results) != 3 {
		t.Fatalf("deduplicated results: %+v %v", results, err)
	}
	ok := 0
	for _, r := range results {
		if r.OK {
			ok++
		}
	}
	if ok != 1 {
		t.Fatalf("expected only still-queued original item to change: %+v", results)
	}
	got, _ := s.GetJob(ctx, late.ID)
	if got.Provisioning != "" {
		t.Fatal("later arrival included")
	}
	selected, err := s.ProvisioningSelection(ctx, JobFilter{Provisioning: []string{"deleted"}})
	if err != nil || len(selected) != 1 || selected[0] != first.ID {
		t.Fatalf("deleted filter: %v %v", selected, err)
	}
	counts, err := s.ProvisioningCounts(ctx, JobFilter{Branches: []string{"main"}, Provisioning: []string{"deleted"}})
	if err != nil || counts["deleted"] != 1 || counts["ready"] != 1 {
		t.Fatalf("faceted counts: %v %v", counts, err)
	}
	if _, err := s.ControlProvisioning(ctx, []string{late.ID}, "invalid"); err == nil {
		t.Fatal("invalid action accepted")
	}
}

// Removing a job from the queue has to move the numbers an operator reads, or
// the removal reads as having done nothing. The Overview's queue depth, the
// pool bars beside it and the queue gauges all come from StatsSince and
// ListQueuedJobs, and an operator who empties the queue and then finds the
// tile still holding its old number has been told the button is broken.
//
// Pausing is a different word and stays counted: that job is on hold, still
// waiting, and the Queue page lists it by default.
func TestRemovingAJobFromTheQueueStopsItCountingAsWaiting(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	queue := func(id int64) *Job {
		j, err := s.UpsertJob(ctx, &Job{
			GitHubJobID: id, State: JobQueued, Repo: "acme/app", PoolID: "pool_1",
			Matched: true, Labels: StringSlice{"self-hosted", "linux"},
		})
		if err != nil {
			t.Fatal(err)
		}
		return j
	}
	ready, paused, removed := queue(1), queue(2), queue(3)
	if _, err := s.ControlProvisioning(ctx, []string{paused.ID}, "pause"); err != nil {
		t.Fatal(err)
	}
	if _, err := s.ControlProvisioning(ctx, []string{removed.ID}, "delete"); err != nil {
		t.Fatal(err)
	}

	// Both scopes: the Overview counts each of them, and the tile follows the
	// "other runners" switch between the two.
	for _, managedOnly := range []bool{false, true} {
		st, err := s.StatsSince(ctx, time.Time{}, managedOnly)
		if err != nil {
			t.Fatal(err)
		}
		if st.Queued != 2 {
			t.Errorf("managedOnly=%v: queued = %d, want the ready and the paused job only", managedOnly, st.Queued)
		}
	}

	jobs, err := s.ListQueuedJobs(ctx)
	if err != nil {
		t.Fatal(err)
	}
	ids := make([]string, len(jobs))
	for i, j := range jobs {
		ids[i] = j.ID
	}
	if len(ids) != 2 || ids[0] != ready.ID || ids[1] != paused.ID {
		t.Errorf("queued demand = %v, want %v and %v", ids, ready.ID, paused.ID)
	}

	// Restoring it puts the number back: the row was never anywhere else.
	if _, err := s.ControlProvisioning(ctx, []string{removed.ID}, "resume"); err != nil {
		t.Fatal(err)
	}
	st, err := s.StatsSince(ctx, time.Time{}, true)
	if err != nil {
		t.Fatal(err)
	}
	if st.Queued != 3 {
		t.Errorf("queued after restoring = %d, want 3", st.Queued)
	}
}

// The sweep that retires jobs GitHub stopped talking about is the one caller
// that wants the removed rows too. Removing a job suppresses this fleet's
// demand for it; it says nothing about whether GitHub still has the work, and
// a row left queued for ever would sit in the Queue's removed view for ever.
func TestStaleQueuedJobsIncludeTheOnesRemovedFromTheQueue(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	old := time.Now().Add(-48 * time.Hour)
	j, err := s.UpsertJob(ctx, &Job{GitHubJobID: 1, State: JobQueued, Repo: "acme/app", QueuedAt: old})
	if err != nil {
		t.Fatal(err)
	}
	fresh, err := s.UpsertJob(ctx, &Job{GitHubJobID: 2, State: JobQueued, Repo: "acme/app", QueuedAt: time.Now()})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s.ControlProvisioning(ctx, []string{j.ID}, "delete"); err != nil {
		t.Fatal(err)
	}
	stale, err := s.ListStaleQueuedJobs(ctx, time.Now().Add(-24*time.Hour))
	if err != nil {
		t.Fatal(err)
	}
	if len(stale) != 1 || stale[0].ID != j.ID {
		t.Fatalf("stale queued jobs = %+v, want only the removed one queued %v ago", stale, time.Since(old))
	}
	if _, err := s.GetJob(ctx, fresh.ID); err != nil {
		t.Fatal(err)
	}
}

// A cancellation reaches GitHub at once; GitHub's completion delivery can be
// minutes behind it. For that whole window the row still reads `queued` or
// `in_progress`, and the fleet used to report the work as waiting or running:
// a queue depth nobody could clear, and a running count for work whose runner
// had already been taken away.
func TestACancelledRunStopsCountingAsWaitingOrRunning(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	job := func(id int64, state JobState) *Job {
		j, err := s.UpsertJob(ctx, &Job{
			GitHubJobID: id, GitHubRunID: 7, State: state, Repo: "acme/app",
			PoolID: "pool_1", Matched: true, Labels: StringSlice{"self-hosted"},
		})
		if err != nil {
			t.Fatal(err)
		}
		return j
	}
	queued, running, done := job(1, JobQueued), job(2, JobInProgress), job(3, JobQueued)
	finished, err := s.UpsertJob(ctx, &Job{GitHubJobID: 3, State: JobCompleted, Conclusion: "success"})
	if err != nil {
		t.Fatal(err)
	}
	_ = done

	at := time.Now()
	changed, err := s.MarkCancelRequested(ctx, []string{queued.ID, running.ID, finished.ID}, at)
	if err != nil {
		t.Fatal(err)
	}
	// The finished sibling ran to its own conclusion; calling it cancelled
	// would be a worse lie than the one this fixes.
	if len(changed) != 2 {
		t.Fatalf("stamped %v, want only the two jobs the run still owned", changed)
	}

	st, err := s.StatsSince(ctx, time.Time{}, true)
	if err != nil {
		t.Fatal(err)
	}
	if st.Queued != 0 || st.Running != 0 {
		t.Errorf("queued = %d, running = %d, want 0 and 0 once the run was cancelled", st.Queued, st.Running)
	}
	if jobs, err := s.ListQueuedJobs(ctx); err != nil || len(jobs) != 0 {
		t.Errorf("queued demand = %v (%v), want none", jobs, err)
	}

	// A second cancellation -- an ordinary one followed by a forced one --
	// must not restart the clock.
	later := at.Add(time.Minute)
	if changed, err := s.MarkCancelRequested(ctx, []string{queued.ID}, later); err != nil || len(changed) != 0 {
		t.Fatalf("a repeated cancellation changed %v (%v), want nothing", changed, err)
	}
	got, err := s.GetJob(ctx, queued.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.CancelRequestedAt == nil || !got.CancelRequestedAt.Equal(at.Truncate(time.Millisecond)) {
		t.Errorf("cancel_requested_at = %v, want the first request at %v", got.CancelRequestedAt, at)
	}
	if !got.Cancelling() {
		t.Error("a queued job whose run was cancelled must report itself as cancelling")
	}

	// Once GitHub reports the job over, the stamp is history and the
	// conclusion says what happened.
	closed, err := s.UpsertJob(ctx, &Job{GitHubJobID: 1, State: JobCompleted, Conclusion: "cancelled"})
	if err != nil {
		t.Fatal(err)
	}
	if closed.CancelRequestedAt == nil {
		t.Error("a delivery must not clear the fleet's own note that a cancellation was asked for")
	}
	if closed.Cancelling() {
		t.Error("a completed job is not still cancelling")
	}
}

// The Jobs page's Running and Queued views ask for this, and its history
// views do not: a cancelled job belongs in the record, badged for what it is.
func TestTheCancellingFilterHasThreeAnswers(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	for i, state := range []JobState{JobQueued, JobInProgress} {
		if _, err := s.UpsertJob(ctx, &Job{GitHubJobID: int64(i + 1), State: state, Repo: "acme/app"}); err != nil {
			t.Fatal(err)
		}
	}
	cancelled, err := s.UpsertJob(ctx, &Job{GitHubJobID: 3, State: JobQueued, Repo: "acme/app"})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s.MarkCancelRequested(ctx, []string{cancelled.ID}, time.Now()); err != nil {
		t.Fatal(err)
	}
	yes, no := true, false
	for _, tc := range []struct {
		name   string
		filter *bool
		want   int
	}{
		{"unasked is every job", nil, 3},
		{"false is the work still in hand", &no, 2},
		{"true is what is on its way out", &yes, 1},
	} {
		t.Run(tc.name, func(t *testing.T) {
			jobs, total, err := s.ListJobs(ctx, JobFilter{Cancelling: tc.filter}, Page{Limit: 10})
			if err != nil || total != tc.want || len(jobs) != tc.want {
				t.Fatalf("got %d jobs (total %d, %v), want %d", len(jobs), total, err, tc.want)
			}
		})
	}
}

package store

import (
	"context"
	"fmt"
	"testing"
	"time"
)

// Retention is the only thing standing between a controller and a database that
// grows for ever, and three of its five queries had no test at all: a cutoff
// comparison written the wrong way round deletes everything or nothing, and
// both look like a working fleet until somebody goes looking for last week.
//
// Each of these seeds one row either side of the cutoff and checks that exactly
// the old one goes, which is the whole contract: strictly older than the
// cutoff, and the count is what the caller logs.

func TestPruningScalingEventsKeepsTheOnesInsideTheWindow(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	_, pool, _ := seedPool(t, s)
	now := time.Now()

	old := &ScalingEvent{PoolID: pool.ID, PoolName: pool.Name, From: 0, To: 1,
		Reason: "old", CreatedAt: now.Add(-48 * time.Hour)}
	recent := &ScalingEvent{PoolID: pool.ID, PoolName: pool.Name, From: 1, To: 2,
		Reason: "recent", CreatedAt: now.Add(-time.Hour)}
	for _, e := range []*ScalingEvent{old, recent} {
		if err := s.AppendScalingEvent(ctx, e); err != nil {
			t.Fatalf("AppendScalingEvent: %v", err)
		}
	}

	n, err := s.PruneScalingEvents(ctx, now.Add(-24*time.Hour))
	if err != nil {
		t.Fatalf("PruneScalingEvents: %v", err)
	}
	if n != 1 {
		t.Errorf("pruned %d rows, want 1: the count is what the controller logs when somebody asks where their history went", n)
	}
	left, err := s.ListScalingEvents(ctx, "", 10)
	if err != nil {
		t.Fatalf("ListScalingEvents: %v", err)
	}
	if len(left) != 1 || left[0].Reason != "recent" {
		t.Fatalf("scaling events after the prune = %+v, want just the recent one", left)
	}
}

func TestPruningDeliveriesKeepsTheOnesInsideTheWindow(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	now := time.Now()

	for _, d := range []*WebhookDelivery{
		{DeliveryID: "old", Event: "workflow_job", Status: "accepted", ReceivedAt: now.Add(-48 * time.Hour)},
		{DeliveryID: "recent", Event: "workflow_job", Status: "accepted", ReceivedAt: now.Add(-time.Hour)},
	} {
		if err := s.RecordDelivery(ctx, d); err != nil {
			t.Fatalf("RecordDelivery: %v", err)
		}
	}

	n, err := s.PruneDeliveries(ctx, now.Add(-24*time.Hour))
	if err != nil {
		t.Fatalf("PruneDeliveries: %v", err)
	}
	if n != 1 {
		t.Errorf("pruned %d deliveries, want 1", n)
	}
	left, err := s.ListDeliveries(ctx, "", 10)
	if err != nil {
		t.Fatalf("ListDeliveries: %v", err)
	}
	if len(left) != 1 || left[0].DeliveryID != "recent" {
		t.Fatalf("deliveries after the prune = %+v, want just the recent one", left)
	}
}

func TestPruningSamplesKeepsTheOnesInsideTheWindow(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	now := time.Now()

	for _, at := range []time.Time{now.Add(-48 * time.Hour), now.Add(-time.Hour)} {
		if err := s.RecordSample(ctx, FleetSample{At: at, TotalRunners: 1}); err != nil {
			t.Fatalf("RecordSample: %v", err)
		}
	}

	n, err := s.PruneSamples(ctx, now.Add(-24*time.Hour))
	if err != nil {
		t.Fatalf("PruneSamples: %v", err)
	}
	if n != 1 {
		t.Errorf("pruned %d samples, want 1", n)
	}
	left, err := s.ListSamples(ctx, now.Add(-72*time.Hour))
	if err != nil {
		t.Fatalf("ListSamples: %v", err)
	}
	if len(left) != 1 {
		t.Fatalf("samples after the prune = %d, want 1: the sparkline is drawn from these, and a prune that took both would flatten it", len(left))
	}
	// Which one survived, not merely how many: counting alone passes just as
	// happily when the comparison is the wrong way round and the prune has kept
	// the ancient sample and deleted the recent one.
	if kept := left[0].At; kept.Before(now.Add(-24 * time.Hour)) {
		t.Errorf("the sample left behind is from %s, which is older than the cutoff: the prune kept the wrong side", kept.UTC())
	}
}

// Each prune deletes a bounded batch so the single writer is never held for
// long, and a pass used to run exactly one. Retention then stopped bounding a
// table as soon as its inflow beat 500 jobs or 1000 rows an hour, and turning
// retention on for an old database drained a backlog at that rate for months.
// A pass now repeats the batch, each one its own transaction, until a batch
// comes back short. These seed more than one batch of old rows and one recent
// row, and expect the whole backlog gone and the recent row kept.

func TestPruningJobsDrainsABacklogLargerThanOneBatchInOnePass(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	now := time.Now().UTC().Truncate(time.Millisecond)
	old := now.Add(-48 * time.Hour)
	done := old.Add(time.Minute)

	const backlog = 1200
	for i := 1; i <= backlog; i++ {
		j, err := s.UpsertJob(ctx, &Job{GitHubJobID: int64(i), State: JobCompleted, Conclusion: "success", QueuedAt: old, CompletedAt: &done})
		if err != nil {
			t.Fatalf("UpsertJob: %v", err)
		}
		// Timelines go with their job in every batch, not just the first.
		if i%100 == 0 {
			if err := s.AppendJobEvent(ctx, &JobEvent{JobID: j.ID, Kind: JobEventQueued, Source: "webhook", Message: "queued", At: old}); err != nil {
				t.Fatalf("AppendJobEvent: %v", err)
			}
		}
	}
	if _, err := s.UpsertJob(ctx, &Job{GitHubJobID: backlog + 1, State: JobQueued, QueuedAt: now}); err != nil {
		t.Fatalf("UpsertJob: %v", err)
	}

	n, err := s.PruneJobs(ctx, now.Add(-24*time.Hour))
	if err != nil {
		t.Fatalf("PruneJobs: %v", err)
	}
	if n != backlog {
		t.Errorf("pruned %d jobs in one pass, want %d", n, backlog)
	}
	var jobs, events int
	if err := s.read.QueryRowContext(ctx, `SELECT COUNT(*) FROM jobs`).Scan(&jobs); err != nil {
		t.Fatal(err)
	}
	if err := s.read.QueryRowContext(ctx, `SELECT COUNT(*) FROM job_events`).Scan(&events); err != nil {
		t.Fatal(err)
	}
	if jobs != 1 || events != 0 {
		t.Fatalf("after the prune there are %d jobs and %d events, want the one recent job and no events", jobs, events)
	}
}

func TestPruningDeliveriesDrainsABacklogLargerThanOneBatchInOnePass(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	now := time.Now()

	const backlog = 2500
	for i := 0; i < backlog; i++ {
		d := &WebhookDelivery{DeliveryID: fmt.Sprintf("old-%d", i), Event: "workflow_job", Status: "accepted", ReceivedAt: now.Add(-48 * time.Hour)}
		if err := s.RecordDelivery(ctx, d); err != nil {
			t.Fatalf("RecordDelivery: %v", err)
		}
	}
	if err := s.RecordDelivery(ctx, &WebhookDelivery{DeliveryID: "recent", Event: "workflow_job", Status: "accepted", ReceivedAt: now.Add(-time.Hour)}); err != nil {
		t.Fatalf("RecordDelivery: %v", err)
	}

	n, err := s.PruneDeliveries(ctx, now.Add(-24*time.Hour))
	if err != nil {
		t.Fatalf("PruneDeliveries: %v", err)
	}
	if n != backlog {
		t.Errorf("pruned %d deliveries in one pass, want %d", n, backlog)
	}
	left, err := s.ListDeliveries(ctx, "", 10)
	if err != nil {
		t.Fatalf("ListDeliveries: %v", err)
	}
	if len(left) != 1 || left[0].DeliveryID != "recent" {
		t.Fatalf("deliveries after the prune = %+v, want just the recent one", left)
	}
}

func TestPruningScalingEventsDrainsABacklogLargerThanOneBatchInOnePass(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	_, pool, _ := seedPool(t, s)
	now := time.Now()

	const backlog = 2500
	for i := 0; i < backlog; i++ {
		e := &ScalingEvent{PoolID: pool.ID, PoolName: pool.Name, From: 0, To: 1, Reason: "old", CreatedAt: now.Add(-48 * time.Hour)}
		if err := s.AppendScalingEvent(ctx, e); err != nil {
			t.Fatalf("AppendScalingEvent: %v", err)
		}
	}
	if err := s.AppendScalingEvent(ctx, &ScalingEvent{PoolID: pool.ID, PoolName: pool.Name, From: 1, To: 2, Reason: "recent", CreatedAt: now.Add(-time.Hour)}); err != nil {
		t.Fatalf("AppendScalingEvent: %v", err)
	}

	n, err := s.PruneScalingEvents(ctx, now.Add(-24*time.Hour))
	if err != nil {
		t.Fatalf("PruneScalingEvents: %v", err)
	}
	if n != backlog {
		t.Errorf("pruned %d scaling events in one pass, want %d", n, backlog)
	}
}

func TestPruningSamplesDrainsABacklogLargerThanOneBatchInOnePass(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	now := time.Now()

	const backlog = 2500
	for i := 0; i < backlog; i++ {
		// A sample is keyed on its minute, so each old one gets its own.
		if err := s.RecordSample(ctx, FleetSample{At: now.Add(-72*time.Hour - time.Duration(i)*time.Minute), TotalRunners: 1}); err != nil {
			t.Fatalf("RecordSample: %v", err)
		}
	}
	if err := s.RecordSample(ctx, FleetSample{At: now.Add(-time.Hour), TotalRunners: 1}); err != nil {
		t.Fatalf("RecordSample: %v", err)
	}

	n, err := s.PruneSamples(ctx, now.Add(-24*time.Hour))
	if err != nil {
		t.Fatalf("PruneSamples: %v", err)
	}
	if n != backlog {
		t.Errorf("pruned %d samples in one pass, want %d", n, backlog)
	}
}

// A pass must not be able to hold the writer, batch after batch, for as long
// as a backlog is deep: the bound leaves the rest for the next hourly pass, and
// a cancelled context ends the pass between batches.
func TestABatchedPruneStopsAtTheBoundAndWhenTheContextEnds(t *testing.T) {
	always := func(size int64) func(context.Context) (int64, error) {
		return func(context.Context) (int64, error) { return size, nil }
	}
	ctx, cancel := context.WithCancel(context.Background())
	calls := 0
	cancelling := func(context.Context) (int64, error) {
		calls++
		if calls == 3 {
			cancel()
		}
		return 10, nil
	}
	short := func() func(context.Context) (int64, error) {
		sizes := []int64{10, 10, 4}
		return func(context.Context) (int64, error) {
			n := sizes[0]
			sizes = sizes[1:]
			return n, nil
		}
	}

	tests := []struct {
		name string
		ctx  context.Context
		fn   func(context.Context) (int64, error)
		want int64
	}{
		{"a short batch ends the pass", context.Background(), short(), 24},
		{"a backlog that never runs short stops at the bound", context.Background(), always(10), 10 * 5},
		{"a cancelled context ends the pass between batches", ctx, cancelling, 30},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := pruneInBatches(tt.ctx, 10, 5, tt.fn)
			if err != nil {
				t.Fatalf("pruneInBatches: %v", err)
			}
			if got != tt.want {
				t.Errorf("pruned %d rows, want %d", got, tt.want)
			}
		})
	}
}

package store

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/aicontext"
)

type AIContextRepository struct {
	Freshness *AIContextFreshness `json:"freshness,omitempty"`
	// Diagnosis is why the last run of the managed workflow did not publish, when
	// the controller has read it. The controller sets it on the way out and the
	// store never saves it: it is a reading of GitHub that goes stale in minutes,
	// and a row would only keep the wrong answer.
	Diagnosis  *aicontext.Diagnosis `json:"diagnosis,omitempty"`
	SetupState string               `json:"setup_state,omitempty"`
	SetupPRURL string               `json:"setup_pr_url,omitempty"`
	// WorkflowOutdated is true while the installed workflow, or the generator's
	// lockfile, is exactly one an earlier release wrote: still trusted, but due a
	// repair to pick up fixes.
	WorkflowOutdated bool                    `json:"workflow_outdated"`
	ID               string                  `json:"id"`
	Key              aicontext.RepositoryKey `json:"repository"`
	FullName         string                  `json:"full_name"`
	Config           aicontext.Config        `json:"config"`
	Revision         int64                   `json:"revision"`
	// Available is a verified repository-access state, not whether a snapshot
	// exists. Access removal closes this gate before retained blobs are read.
	Available bool      `json:"available"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

// MarshalJSON derives shareable setup guidance from the saved destination, so
// it remains available after the preparation wizard has finished.
func (r AIContextRepository) MarshalJSON() ([]byte, error) {
	type repository AIContextRepository
	return json.Marshal(struct {
		repository
		Instructions  string `json:"instructions"`
		BadgeMarkdown string `json:"badge_markdown"`
	}{repository: repository(r), Instructions: aicontext.AssistantInstructions(r.Key, r.FullName, r.Config), BadgeMarkdown: aicontext.BadgeMarkdown(r.Key, r.FullName)})
}

const aiContextColumns = `id, installation_id, github_host, repository_id, full_name, config_json, revision, available, created_at, updated_at`

const aiContextReadColumns = aiContextColumns + `, COALESCE((SELECT state FROM ai_context_setups WHERE repository_id=ai_context_repositories.id),''), COALESCE((SELECT pr_url FROM ai_context_setups WHERE repository_id=ai_context_repositories.id),''), COALESCE((SELECT json_object('state',state,'desired_commit',desired_commit,'published_commit',published_commit,'snapshot_id',digest,'checked_at',checked_at,'failure',failure) FROM ai_context_freshness WHERE repository_id=ai_context_repositories.id),'null'), workflow_outdated`

func scanAIContext(sc interface{ Scan(...any) error }) (*AIContextRepository, error) {
	var r AIContextRepository
	var config, freshness string
	var available, outdated int
	var created, updated int64
	err := sc.Scan(&r.ID, &r.Key.InstallationID, &r.Key.GitHubHost, &r.Key.RepositoryID, &r.FullName, &config, &r.Revision, &available, &created, &updated, &r.SetupState, &r.SetupPRURL, &freshness, &outdated)
	if err != nil {
		return nil, err
	}
	if err := json.Unmarshal([]byte(config), &r.Config); err != nil {
		return nil, err
	}
	if freshness != "null" {
		var stored struct {
			State           string `json:"state"`
			DesiredCommit   string `json:"desired_commit"`
			PublishedCommit string `json:"published_commit"`
			Digest          string `json:"snapshot_id"`
			CheckedAt       int64  `json:"checked_at"`
			Failure         string `json:"failure"`
		}
		if err := json.Unmarshal([]byte(freshness), &stored); err != nil {
			return nil, err
		}
		r.Freshness = &AIContextFreshness{State: stored.State, DesiredCommit: stored.DesiredCommit, PublishedCommit: stored.PublishedCommit, Digest: stored.Digest, CheckedAt: at(stored.CheckedAt), Failure: stored.Failure}
	}
	r.Available, r.WorkflowOutdated, r.CreatedAt, r.UpdatedAt = available == 1, outdated == 1, at(created), at(updated)
	return &r, nil
}

func (s *Store) CreateAIContextRepository(ctx context.Context, r *AIContextRepository) error {
	if err := r.Key.Validate(); err != nil {
		return err
	}
	if err := r.Config.Validate(); err != nil {
		return err
	}
	if r.FullName == "" || len(r.FullName) > 255 {
		return fmt.Errorf("context needs the repository's full name")
	}
	if r.ID == "" {
		r.ID = NewID(PrefixAIContext)
	}
	body, err := json.Marshal(r.Config)
	if err != nil {
		return err
	}
	now := s.Now()
	_, err = s.exec(ctx, `INSERT INTO ai_context_repositories (`+aiContextColumns+`) VALUES (?,?,?,?,?,?,1,0,?,?)`,
		r.ID, r.Key.InstallationID, r.Key.GitHubHost, r.Key.RepositoryID, r.FullName, string(body), ms(now), ms(now))
	if err != nil {
		return wrapWrite(err)
	}
	r.Revision, r.Available, r.CreatedAt, r.UpdatedAt = 1, false, now, now
	return nil
}

// SetAIContextWorkflowOutdated records what the last verification found. It
// leaves revision and updated_at alone: this is an observation about GitHub, not
// an edit, and bumping the revision would reject a wizard write in progress.
func (s *Store) SetAIContextWorkflowOutdated(ctx context.Context, id string, outdated bool) error {
	v := 0
	if outdated {
		v = 1
	}
	_, err := s.exec(ctx, `UPDATE ai_context_repositories SET workflow_outdated=? WHERE id=? AND workflow_outdated<>?`, v, id, v)
	return wrapWrite(err)
}

func (s *Store) GetAIContextRepository(ctx context.Context, id string) (*AIContextRepository, error) {
	r, err := scanAIContext(s.read.QueryRowContext(ctx, `SELECT `+aiContextReadColumns+` FROM ai_context_repositories WHERE id=?`, id))
	if errors.Is(err, sql.ErrNoRows) {
		return nil, fmt.Errorf("context repository %s: %w", id, ErrNotFound)
	}
	return r, err
}

// SaveAIContextConfig is compare-and-swap: resuming yesterday's wizard cannot
// silently replace the exclusions or destination somebody changed today.
func (s *Store) SaveAIContextConfig(ctx context.Context, id string, revision int64, config aicontext.Config) error {
	if err := config.Validate(); err != nil {
		return err
	}
	if revision < 1 {
		return ErrConflict
	}
	body, err := json.Marshal(config)
	if err != nil {
		return err
	}
	res, err := s.exec(ctx, `UPDATE ai_context_repositories SET config_json=?, revision=revision+1, updated_at=? WHERE id=? AND revision=? AND NOT EXISTS (SELECT 1 FROM ai_context_setups WHERE repository_id=ai_context_repositories.id)`, string(body), ms(s.Now()), id, revision)
	if err != nil {
		return err
	}
	n, err := res.RowsAffected()
	if err != nil {
		return err
	}
	if n == 0 {
		return ErrConflict
	}
	return nil
}

func (s *Store) SetAIContextAvailable(ctx context.Context, id string, available bool) error {
	res, err := s.exec(ctx, `UPDATE ai_context_repositories SET available=?, updated_at=? WHERE id=?`, boolInt(available), ms(s.Now()), id)
	if err != nil {
		return err
	}
	return affected(res, "context repository", id)
}

func (s *Store) DeleteAIContextRepository(ctx context.Context, id string) error {
	res, err := s.exec(ctx, `DELETE FROM ai_context_repositories WHERE id=?`, id)
	if err != nil {
		return err
	}
	return affected(res, "context repository", id)
}

// ReplaceAIContextMembers also removes consent for users losing membership.
// Adding the user back later must not quietly re-enable an old app connection.
func (s *Store) ReplaceAIContextMembers(ctx context.Context, repositoryID string, users []string) error {
	if len(users) > 200 {
		return fmt.Errorf("select at most 200 context readers")
	}
	return wrapWrite(s.tx(ctx, func(tx *sql.Tx) error {
		var exists int
		if err := tx.QueryRowContext(ctx, `SELECT 1 FROM ai_context_repositories WHERE id=?`, repositoryID).Scan(&exists); errors.Is(err, sql.ErrNoRows) {
			return ErrNotFound
		} else if err != nil {
			return err
		}
		// The temporary selection is held in Go; all changes still commit as
		// one writer transaction, so a failed member insert retains old grants.
		old := map[string]bool{}
		rows, err := tx.QueryContext(ctx, `SELECT user_id FROM ai_context_members WHERE repository_id=?`, repositoryID)
		if err != nil {
			return err
		}
		for rows.Next() {
			var user string
			if err := rows.Scan(&user); err != nil {
				rows.Close()
				return err
			}
			old[user] = true
		}
		if err := rows.Err(); err != nil {
			rows.Close()
			return err
		}
		rows.Close()
		if _, err := tx.ExecContext(ctx, `DELETE FROM ai_context_members WHERE repository_id=?`, repositoryID); err != nil {
			return err
		}
		seen := map[string]bool{}
		for _, user := range users {
			if user == "" || seen[user] {
				return fmt.Errorf("select each context reader once")
			}
			seen[user] = true
			if _, err := tx.ExecContext(ctx, `INSERT INTO ai_context_members(repository_id,user_id) VALUES(?,?)`, repositoryID, user); err != nil {
				return err
			}
		}
		for user := range old {
			if !seen[user] {
				if _, err := tx.ExecContext(ctx, `DELETE FROM ai_context_connection_repositories WHERE repository_id=? AND grant_id IN (SELECT id FROM oauth_grants WHERE user_id=?)`, repositoryID, user); err != nil {
					return err
				}
			}
		}
		return nil
	}))
}

func (s *Store) AIContextUserAccess(ctx context.Context, repositoryID, userID string) (bool, error) {
	var allowed int
	err := s.read.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM ai_context_members m
		JOIN ai_context_repositories r ON r.id=m.repository_id JOIN users u ON u.id=m.user_id
		WHERE m.repository_id=? AND m.user_id=? AND r.available=1 AND u.disabled=0)`, repositoryID, userID).Scan(&allowed)
	return allowed == 1, err
}

// ReplaceAIContextConnectionAccess is called only after explicit consent.
// Ownership, live user membership and connection revocation are checked here
// as well as by the caller; a cached identity cannot restore revoked access.
//
// publish is the subset of repositories this connection may also write notes
// to. nil keeps the publish consent already given for repositories that stay
// selected, so a client that only knows about read consent cannot widen or
// clear the write half by accident; an empty slice clears it.
func (s *Store) ReplaceAIContextConnectionAccess(ctx context.Context, grantID, userID string, repositories, publish []string) error {
	if len(repositories) > 100 {
		return fmt.Errorf("select at most 100 repositories for one connection")
	}
	selected := map[string]bool{}
	for _, repository := range repositories {
		selected[repository] = true
	}
	for _, repository := range publish {
		if !selected[repository] {
			return fmt.Errorf("a connection can only publish notes to repositories it may also read")
		}
	}
	return s.tx(ctx, func(tx *sql.Tx) error {
		var active int
		err := tx.QueryRowContext(ctx, `SELECT 1 FROM oauth_grants g JOIN users u ON u.id=g.user_id JOIN oauth_clients c ON c.id=g.client_id
			WHERE g.id=? AND g.user_id=? AND g.revoked_at IS NULL AND c.revoked_at IS NULL AND u.disabled=0`, grantID, userID).Scan(&active)
		if errors.Is(err, sql.ErrNoRows) {
			return ErrNotFound
		}
		if err != nil {
			return err
		}
		writes := map[string]bool{}
		if publish == nil {
			rows, err := tx.QueryContext(ctx, `SELECT repository_id FROM ai_context_connection_repositories WHERE grant_id=? AND publish=1`, grantID)
			if err != nil {
				return err
			}
			for rows.Next() {
				var id string
				if err := rows.Scan(&id); err != nil {
					rows.Close()
					return err
				}
				writes[id] = true
			}
			rows.Close()
			if err := rows.Err(); err != nil {
				return err
			}
		} else {
			for _, id := range publish {
				writes[id] = true
			}
		}
		if _, err := tx.ExecContext(ctx, `DELETE FROM ai_context_connection_repositories WHERE grant_id=?`, grantID); err != nil {
			return err
		}
		seen := map[string]bool{}
		for _, repository := range repositories {
			if seen[repository] {
				return fmt.Errorf("select each context repository once")
			}
			seen[repository] = true
			var allowed int
			err := tx.QueryRowContext(ctx, `SELECT 1 FROM ai_context_members m JOIN ai_context_repositories r ON r.id=m.repository_id WHERE m.repository_id=? AND m.user_id=? AND r.available=1`, repository, userID).Scan(&allowed)
			if errors.Is(err, sql.ErrNoRows) {
				return ErrNotFound
			}
			if err != nil {
				return err
			}
			if _, err := tx.ExecContext(ctx, `INSERT INTO ai_context_connection_repositories(grant_id,repository_id,publish) VALUES(?,?,?)`, grantID, repository, boolInt(writes[repository])); err != nil {
				return err
			}
		}
		return nil
	})
}

func (s *Store) AIContextConnectionAccess(ctx context.Context, repositoryID, grantID, userID string) (bool, error) {
	return s.aiContextConnectionAccess(ctx, repositoryID, grantID, userID, false)
}

// AIContextConnectionPublishAccess is read access plus the owner's separate
// consent for this connection to write notes to the repository.
func (s *Store) AIContextConnectionPublishAccess(ctx context.Context, repositoryID, grantID, userID string) (bool, error) {
	return s.aiContextConnectionAccess(ctx, repositoryID, grantID, userID, true)
}

func (s *Store) aiContextConnectionAccess(ctx context.Context, repositoryID, grantID, userID string, publish bool) (bool, error) {
	var allowed int
	err := s.read.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM ai_context_connection_repositories a
		JOIN oauth_grants g ON g.id=a.grant_id JOIN oauth_clients c ON c.id=g.client_id
		JOIN ai_context_members m ON m.repository_id=a.repository_id AND m.user_id=g.user_id
		JOIN ai_context_repositories r ON r.id=a.repository_id JOIN users u ON u.id=g.user_id
		WHERE a.repository_id=? AND g.id=? AND g.user_id=? AND r.available=1 AND u.disabled=0
		AND g.revoked_at IS NULL AND c.revoked_at IS NULL AND (?=0 OR a.publish=1))`, repositoryID, grantID, userID, boolInt(publish)).Scan(&allowed)
	return allowed == 1, err
}

// ListAIContextRepositories bounds configuration metadata separately from source
// retrieval. Ordering includes the ID so equally named drafts cannot skip rows.
func (s *Store) ListAIContextRepositories(ctx context.Context, limit, offset int) ([]AIContextRepository, int, error) {
	return s.ListAIContextRepositoriesFiltered(ctx, limit, offset, "", "")
}

func (s *Store) ListAIContextRepositoriesFiltered(ctx context.Context, limit, offset int, installationID, query string) ([]AIContextRepository, int, error) {
	return s.listAIContextRepositories(ctx, limit, offset, installationID, query, "")
}

// ListAIContextRepositoriesOwnedBy is the same page restricted to installations
// the user owns, so an owner's listing cannot reach another installation's rows
// however the filters are combined.
func (s *Store) ListAIContextRepositoriesOwnedBy(ctx context.Context, limit, offset int, installationID, query, userID string) ([]AIContextRepository, int, error) {
	if userID == "" {
		return nil, 0, fmt.Errorf("an owner is required")
	}
	return s.listAIContextRepositories(ctx, limit, offset, installationID, query, userID)
}

func (s *Store) listAIContextRepositories(ctx context.Context, limit, offset int, installationID, query, ownerID string) ([]AIContextRepository, int, error) {
	if limit < 1 || limit > 100 || offset < 0 || len(query) > 200 {
		return nil, 0, fmt.Errorf("choose a page size between 1 and 100 and a non-negative offset")
	}
	pattern := "%" + strings.NewReplacer(`\`, `\\`, `%`, `\%`, `_`, `\_`).Replace(query) + "%"
	const where = ` WHERE (?='' OR installation_id=?) AND full_name LIKE ? ESCAPE '\'
		AND (?='' OR installation_id IN (SELECT o.installation_id FROM ai_context_installation_owners o JOIN users u ON u.id=o.user_id WHERE o.user_id=? AND u.disabled=0))`
	var total int
	if err := s.read.QueryRowContext(ctx, `SELECT COUNT(*) FROM ai_context_repositories`+where, installationID, installationID, pattern, ownerID, ownerID).Scan(&total); err != nil {
		return nil, 0, err
	}
	rows, err := s.read.QueryContext(ctx, `SELECT `+aiContextReadColumns+` FROM ai_context_repositories`+where+` ORDER BY full_name,id LIMIT ? OFFSET ?`, installationID, installationID, pattern, ownerID, ownerID, limit, offset)
	if err != nil {
		return nil, 0, err
	}
	defer rows.Close()
	out := make([]AIContextRepository, 0)
	for rows.Next() {
		row, err := scanAIContext(rows)
		if err != nil {
			return nil, 0, err
		}
		out = append(out, *row)
	}
	return out, total, rows.Err()
}

func (s *Store) AIContextMembers(ctx context.Context, repositoryID string) ([]string, error) {
	if _, err := s.GetAIContextRepository(ctx, repositoryID); err != nil {
		return nil, err
	}
	rows, err := s.read.QueryContext(ctx, `SELECT user_id FROM ai_context_members WHERE repository_id=? ORDER BY user_id`, repositoryID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		out = append(out, id)
	}
	return out, rows.Err()
}

// AIContextChoice exposes only repository names a person already has source
// membership for. Configuration, source and other users' grants stay private.
type AIContextChoice struct {
	ID       string `json:"id"`
	FullName string `json:"full_name"`
}

type AIContextConnectionSelection struct {
	Items                 []AIContextChoice `json:"items"`
	Total                 int               `json:"total"`
	Limit                 int               `json:"limit"`
	Offset                int               `json:"offset"`
	SelectedRepositoryIDs []string          `json:"selected_repository_ids"`
	// PublishRepositoryIDs is the subset this connection may also write
	// notes to, likewise complete rather than per page.
	PublishRepositoryIDs []string `json:"publish_repository_ids"`
}

// AIContextConnectionChoices checks the live owner/client/grant on every query,
// so revocation closes both metadata discovery and the subsequent consent write.
func (s *Store) AIContextConnectionChoices(ctx context.Context, grantID, userID string, limit, offset int) (*AIContextConnectionSelection, error) {
	if limit < 1 || limit > 100 || offset < 0 {
		return nil, fmt.Errorf("choose a page size between 1 and 100 and a non-negative offset")
	}
	const active = `EXISTS(SELECT 1 FROM oauth_grants g JOIN users u ON u.id=g.user_id JOIN oauth_clients c ON c.id=g.client_id WHERE g.id=? AND g.user_id=? AND g.revoked_at IS NULL AND c.revoked_at IS NULL AND u.disabled=0)`
	var valid bool
	if err := s.read.QueryRowContext(ctx, `SELECT `+active, grantID, userID).Scan(&valid); err != nil {
		return nil, err
	}
	if !valid {
		return nil, ErrNotFound
	}
	const eligible = ` FROM ai_context_repositories r JOIN ai_context_members m ON m.repository_id=r.id WHERE m.user_id=? AND r.available=1 AND ` + active
	out := &AIContextConnectionSelection{Items: []AIContextChoice{}, SelectedRepositoryIDs: []string{}, PublishRepositoryIDs: []string{}, Limit: limit, Offset: offset}
	if err := s.read.QueryRowContext(ctx, `SELECT COUNT(*)`+eligible, userID, grantID, userID).Scan(&out.Total); err != nil {
		return nil, err
	}
	rows, err := s.read.QueryContext(ctx, `SELECT r.id,r.full_name`+eligible+` ORDER BY r.full_name,r.id LIMIT ? OFFSET ?`, userID, grantID, userID, limit, offset)
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		var choice AIContextChoice
		if err := rows.Scan(&choice.ID, &choice.FullName); err != nil {
			rows.Close()
			return nil, err
		}
		out.Items = append(out.Items, choice)
	}
	err = rows.Err()
	rows.Close()
	if err != nil {
		return nil, err
	}
	// Return the complete eligible selection, not merely the current page. A
	// save on page one must not quietly revoke choices made on page two.
	rows, err = s.read.QueryContext(ctx, `SELECT r.id,(SELECT a.publish FROM ai_context_connection_repositories a WHERE a.repository_id=r.id AND a.grant_id=?)`+eligible+` AND EXISTS(SELECT 1 FROM ai_context_connection_repositories a WHERE a.repository_id=r.id AND a.grant_id=?) ORDER BY r.id`, grantID, userID, grantID, userID, grantID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var id string
		var publish int
		if err := rows.Scan(&id, &publish); err != nil {
			return nil, err
		}
		out.SelectedRepositoryIDs = append(out.SelectedRepositoryIDs, id)
		if publish == 1 {
			out.PublishRepositoryIDs = append(out.PublishRepositoryIDs, id)
		}
	}
	return out, rows.Err()
}

func (s *Store) FindAIContextRepository(ctx context.Context, key aicontext.RepositoryKey) (*AIContextRepository, error) {
	if err := key.Validate(); err != nil {
		return nil, err
	}
	row, err := scanAIContext(s.read.QueryRowContext(ctx, `SELECT `+aiContextReadColumns+` FROM ai_context_repositories WHERE github_host=? AND installation_id=? AND repository_id=?`, key.GitHubHost, key.InstallationID, key.RepositoryID))
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	return row, err
}

// Reader metadata is gated in the query, before paging: an ordinary fleet
// viewer cannot enumerate private drafts, names or configuration.
func (s *Store) ListAIContextReaderRepositories(ctx context.Context, userID string, limit, offset int, query string) ([]AIContextChoice, int, error) {
	if limit < 1 || limit > 100 || offset < 0 || len(query) > 200 {
		return nil, 0, fmt.Errorf("choose a bounded page and search query")
	}
	pattern := "%" + strings.NewReplacer(`\`, `\\`, `%`, `\%`, `_`, `\_`).Replace(query) + "%"
	const from = ` FROM ai_context_repositories r JOIN ai_context_members m ON m.repository_id=r.id JOIN users u ON u.id=m.user_id WHERE m.user_id=? AND u.disabled=0 AND r.available=1 AND r.full_name LIKE ? ESCAPE '\'`
	var total int
	if err := s.read.QueryRowContext(ctx, `SELECT COUNT(*)`+from, userID, pattern).Scan(&total); err != nil {
		return nil, 0, err
	}
	rows, err := s.read.QueryContext(ctx, `SELECT r.id,r.full_name`+from+` ORDER BY r.full_name,r.id LIMIT ? OFFSET ?`, userID, pattern, limit, offset)
	if err != nil {
		return nil, 0, err
	}
	defer rows.Close()
	out := []AIContextChoice{}
	for rows.Next() {
		var c AIContextChoice
		if err := rows.Scan(&c.ID, &c.FullName); err != nil {
			return nil, 0, err
		}
		out = append(out, c)
	}
	return out, total, rows.Err()
}

// ListAIContextGrantedRepositories reveals only repositories selected for this
// connection, never the owner's wider membership or other connections' grants.
func (s *Store) ListAIContextGrantedRepositories(ctx context.Context, grantID, userID string, limit, offset int, query string) ([]AIContextChoice, int, error) {
	if limit < 1 || limit > 100 || offset < 0 || len(query) > 200 {
		return nil, 0, fmt.Errorf("choose a bounded page and search query")
	}
	pattern := "%" + strings.NewReplacer(`\`, `\\`, `%`, `\%`, `_`, `\_`).Replace(query) + "%"
	const from = ` FROM ai_context_repositories r JOIN ai_context_connection_repositories a ON a.repository_id=r.id JOIN oauth_grants g ON g.id=a.grant_id JOIN oauth_clients c ON c.id=g.client_id JOIN ai_context_members m ON m.repository_id=r.id AND m.user_id=g.user_id JOIN users u ON u.id=g.user_id WHERE g.id=? AND g.user_id=? AND g.revoked_at IS NULL AND c.revoked_at IS NULL AND u.disabled=0 AND r.available=1 AND r.full_name LIKE ? ESCAPE '\'`
	var total int
	if err := s.read.QueryRowContext(ctx, `SELECT COUNT(*)`+from, grantID, userID, pattern).Scan(&total); err != nil {
		return nil, 0, err
	}
	rows, err := s.read.QueryContext(ctx, `SELECT r.id,r.full_name`+from+` ORDER BY r.full_name,r.id LIMIT ? OFFSET ?`, grantID, userID, pattern, limit, offset)
	if err != nil {
		return nil, 0, err
	}
	defer rows.Close()
	out := []AIContextChoice{}
	for rows.Next() {
		var choice AIContextChoice
		if err := rows.Scan(&choice.ID, &choice.FullName); err != nil {
			return nil, 0, err
		}
		out = append(out, choice)
	}
	return out, total, rows.Err()
}

package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"regexp"
	"strings"
	"time"
	"unicode/utf8"
)

// The bounds on assistant-written notes. A note is prose about a repository,
// not a copy of it, so it is small; versions are kept so an edit never loses
// what an earlier run concluded, but not without end.
const (
	MaxArtifactBodyBytes      = 128 << 10
	MaxArtifactTitle          = 200
	MaxArtifactVersions       = 20
	MaxArtifactsPerRepository = 100
)

// ErrInvalidArtifact is a note that breaks one of the rules every note must
// keep; the wrapped text says which, for the person or agent to fix.
var ErrInvalidArtifact = errors.New("invalid note")

var artifactSlug = regexp.MustCompile(`^[a-z0-9][a-z0-9-]{0,63}$`)

// ArtifactKinds are the kinds of note an assistant may publish.
var ArtifactKinds = map[string]bool{"report": true, "plan": true, "note": true}

// AIContextArtifact is one version of an assistant-written note.
type AIContextArtifact struct {
	ID           string    `json:"id"`
	RepositoryID string    `json:"repository_id"`
	Slug         string    `json:"slug"`
	Version      int       `json:"version"`
	Kind         string    `json:"kind"`
	Title        string    `json:"title"`
	Body         string    `json:"body,omitempty"`
	SourceCommit string    `json:"source_commit"`
	AuthorName   string    `json:"author_name"`
	ViaKind      string    `json:"via_kind"`
	ViaName      string    `json:"via_name,omitempty"`
	CreatedAt    time.Time `json:"created_at"`
	// Versions is how many versions of this slug are kept; set on listings.
	Versions int `json:"versions,omitempty"`
}

// PublishAIContextArtifact stores a new version of a note, numbering it after
// the slug's latest. Who may publish is decided before this is called; this
// enforces what any note must be, whoever wrote it.
func (s *Store) PublishAIContextArtifact(ctx context.Context, a *AIContextArtifact, authorUserID string) error {
	switch {
	case !artifactSlug.MatchString(a.Slug):
		return fmt.Errorf("%w: name the note with 1-64 lower-case letters, digits and hyphens, starting with a letter or digit", ErrInvalidArtifact)
	case !ArtifactKinds[a.Kind]:
		return fmt.Errorf("%w: choose report, plan or note as the kind", ErrInvalidArtifact)
	case strings.TrimSpace(a.Title) == "" || utf8.RuneCountInString(a.Title) > MaxArtifactTitle || strings.ContainsAny(a.Title, "\r\n\x00"):
		return fmt.Errorf("%w: give the note a one-line title of at most %d characters", ErrInvalidArtifact, MaxArtifactTitle)
	case a.Body == "" || len(a.Body) > MaxArtifactBodyBytes || !utf8.ValidString(a.Body) || strings.ContainsRune(a.Body, 0):
		return fmt.Errorf("%w: a note's body is UTF-8 Markdown of 1 byte to %d KiB", ErrInvalidArtifact, MaxArtifactBodyBytes>>10)
	case a.ViaKind != "user" && a.ViaKind != "token" && a.ViaKind != "connection":
		return fmt.Errorf("%w: unknown publishing route %q", ErrInvalidArtifact, a.ViaKind)
	}
	return wrapWrite(s.tx(ctx, func(tx *sql.Tx) error {
		var available int
		if err := tx.QueryRowContext(ctx, `SELECT available FROM ai_context_repositories WHERE id=?`, a.RepositoryID).Scan(&available); errors.Is(err, sql.ErrNoRows) {
			return ErrNotFound
		} else if err != nil {
			return err
		}
		if available != 1 {
			return fmt.Errorf("%w: notes can only be published to a repository whose context is verified", ErrConflict)
		}
		var latest int
		if err := tx.QueryRowContext(ctx, `SELECT COALESCE(MAX(version),0) FROM ai_context_artifacts WHERE repository_id=? AND slug=?`, a.RepositoryID, a.Slug).Scan(&latest); err != nil {
			return err
		}
		if latest == 0 {
			var slugs int
			if err := tx.QueryRowContext(ctx, `SELECT COUNT(DISTINCT slug) FROM ai_context_artifacts WHERE repository_id=?`, a.RepositoryID).Scan(&slugs); err != nil {
				return err
			}
			if slugs >= MaxArtifactsPerRepository {
				return fmt.Errorf("%w: this repository already has %d notes; publish a new version of an existing one instead", ErrConflict, MaxArtifactsPerRepository)
			}
		}
		// The commit the repository's verified context was at: what the author
		// could have read when it wrote this.
		if err := tx.QueryRowContext(ctx, `SELECT COALESCE((SELECT published_commit FROM ai_context_freshness WHERE repository_id=?),'')`, a.RepositoryID).Scan(&a.SourceCommit); err != nil {
			return err
		}
		a.ID, a.Version, a.CreatedAt = NewID(PrefixAIArtifact), latest+1, s.Now().UTC().Truncate(time.Millisecond)
		var author any
		if authorUserID != "" {
			author = authorUserID
		}
		if _, err := tx.ExecContext(ctx, `INSERT INTO ai_context_artifacts(id,repository_id,slug,version,kind,title,body,source_commit,author_user_id,author_name,via_kind,via_name,created_at)
			VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)`, a.ID, a.RepositoryID, a.Slug, a.Version, a.Kind, a.Title, a.Body, a.SourceCommit, author, a.AuthorName, a.ViaKind, a.ViaName, ms(a.CreatedAt)); err != nil {
			return err
		}
		_, err := tx.ExecContext(ctx, `DELETE FROM ai_context_artifacts WHERE repository_id=? AND slug=? AND version<=?`, a.RepositoryID, a.Slug, a.Version-MaxArtifactVersions)
		return err
	}))
}

// ListAIContextArtifacts is the latest version of each note, newest first,
// without bodies.
func (s *Store) ListAIContextArtifacts(ctx context.Context, repositoryID string, limit, offset int) ([]AIContextArtifact, int, error) {
	if limit < 1 || limit > 100 || offset < 0 {
		return nil, 0, fmt.Errorf("choose a page size between 1 and 100 and a non-negative offset")
	}
	var total int
	if err := s.read.QueryRowContext(ctx, `SELECT COUNT(DISTINCT slug) FROM ai_context_artifacts WHERE repository_id=?`, repositoryID).Scan(&total); err != nil {
		return nil, 0, err
	}
	rows, err := s.read.QueryContext(ctx, `SELECT a.id,a.repository_id,a.slug,a.version,a.kind,a.title,'',a.source_commit,a.author_name,a.via_kind,a.via_name,a.created_at,
		(SELECT COUNT(*) FROM ai_context_artifacts v WHERE v.repository_id=a.repository_id AND v.slug=a.slug)
		FROM ai_context_artifacts a WHERE a.repository_id=? AND a.version=(SELECT MAX(version) FROM ai_context_artifacts l WHERE l.repository_id=a.repository_id AND l.slug=a.slug)
		ORDER BY a.created_at DESC, a.slug LIMIT ? OFFSET ?`, repositoryID, limit, offset)
	if err != nil {
		return nil, 0, err
	}
	defer rows.Close()
	out := []AIContextArtifact{}
	for rows.Next() {
		a, err := scanArtifact(rows, true)
		if err != nil {
			return nil, 0, err
		}
		out = append(out, *a)
	}
	return out, total, rows.Err()
}

// GetAIContextArtifact returns one version of a note, or its latest when
// version is zero.
func (s *Store) GetAIContextArtifact(ctx context.Context, repositoryID, slug string, version int) (*AIContextArtifact, error) {
	if version < 0 {
		return nil, fmt.Errorf("%w: choose a positive version", ErrInvalidArtifact)
	}
	row := s.read.QueryRowContext(ctx, `SELECT id,repository_id,slug,version,kind,title,body,source_commit,author_name,via_kind,via_name,created_at FROM ai_context_artifacts
		WHERE repository_id=? AND slug=? AND (?=0 OR version=?) ORDER BY version DESC LIMIT 1`, repositoryID, slug, version, version)
	a, err := scanArtifact(row, false)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, fmt.Errorf("note %s: %w", slug, ErrNotFound)
	}
	return a, err
}

func scanArtifact(sc interface{ Scan(...any) error }, withVersions bool) (*AIContextArtifact, error) {
	var a AIContextArtifact
	var created int64
	dest := []any{&a.ID, &a.RepositoryID, &a.Slug, &a.Version, &a.Kind, &a.Title, &a.Body, &a.SourceCommit, &a.AuthorName, &a.ViaKind, &a.ViaName, &created}
	if withVersions {
		dest = append(dest, &a.Versions)
	}
	if err := sc.Scan(dest...); err != nil {
		return nil, err
	}
	a.CreatedAt = at(created)
	return &a, nil
}

package store

import (
	"errors"
	"strings"
	"testing"
)

func publishFixture(t *testing.T) (*Store, *AIContextRepository, *User, *OAuthGrant) {
	t.Helper()
	s := newTestStore(t)
	r, u, g := contextFixture(t, s)
	if err := s.ReplaceAIContextMembers(t.Context(), r.ID, []string{u.ID}); err != nil {
		t.Fatal(err)
	}
	if err := s.SetAIContextAvailable(t.Context(), r.ID, true); err != nil {
		t.Fatal(err)
	}
	return s, r, u, g
}

// A note is versioned rather than overwritten, so an edit never loses what an
// earlier run concluded; the listing shows the latest of each.
func TestANoteIsVersionedAndListedByItsLatest(t *testing.T) {
	s, r, u, _ := publishFixture(t)
	for i, title := range []string{"First look", "Second look"} {
		a := &AIContextArtifact{RepositoryID: r.ID, Slug: "review", Kind: "report", Title: title, Body: "# " + title, AuthorName: u.Username, ViaKind: "user"}
		if err := s.PublishAIContextArtifact(t.Context(), a, u.ID); err != nil {
			t.Fatal(err)
		}
		if a.Version != i+1 {
			t.Fatalf("version = %d, want %d", a.Version, i+1)
		}
	}
	items, total, err := s.ListAIContextArtifacts(t.Context(), r.ID, 10, 0)
	if err != nil || total != 1 || len(items) != 1 || items[0].Title != "Second look" || items[0].Versions != 2 || items[0].Body != "" {
		t.Fatalf("listing = %+v, %d, %v", items, total, err)
	}
	first, err := s.GetAIContextArtifact(t.Context(), r.ID, "review", 1)
	if err != nil || first.Title != "First look" || first.Body != "# First look" {
		t.Fatalf("version 1 = %+v, %v", first, err)
	}
	latest, err := s.GetAIContextArtifact(t.Context(), r.ID, "review", 0)
	if err != nil || latest.Version != 2 {
		t.Fatalf("latest = %+v, %v", latest, err)
	}
}

func TestANoteBreakingTheRulesIsRefusedWithTheRuleItBroke(t *testing.T) {
	s, r, u, _ := publishFixture(t)
	for name, a := range map[string]AIContextArtifact{
		"a slug with capitals": {Slug: "Review", Kind: "report", Title: "t", Body: "b"},
		"an unknown kind":      {Slug: "review", Kind: "essay", Title: "t", Body: "b"},
		"a two-line title":     {Slug: "review", Kind: "report", Title: "t\nu", Body: "b"},
		"an empty body":        {Slug: "review", Kind: "report", Title: "t"},
		"an oversized body":    {Slug: "review", Kind: "report", Title: "t", Body: strings.Repeat("x", MaxArtifactBodyBytes+1)},
	} {
		a.RepositoryID, a.AuthorName, a.ViaKind = r.ID, u.Username, "user"
		if err := s.PublishAIContextArtifact(t.Context(), &a, u.ID); !errors.Is(err, ErrInvalidArtifact) {
			t.Errorf("%s: %v", name, err)
		}
	}
	if err := s.SetAIContextAvailable(t.Context(), r.ID, false); err != nil {
		t.Fatal(err)
	}
	a := &AIContextArtifact{RepositoryID: r.ID, Slug: "review", Kind: "report", Title: "t", Body: "b", AuthorName: u.Username, ViaKind: "user"}
	if err := s.PublishAIContextArtifact(t.Context(), a, u.ID); !errors.Is(err, ErrConflict) {
		t.Errorf("published to a repository whose context is not verified: %v", err)
	}
}

func TestOnlyTheNewestVersionsOfANoteAreKept(t *testing.T) {
	s, r, u, _ := publishFixture(t)
	for i := 0; i < MaxArtifactVersions+3; i++ {
		a := &AIContextArtifact{RepositoryID: r.ID, Slug: "plan", Kind: "plan", Title: "Plan", Body: "step", AuthorName: u.Username, ViaKind: "user"}
		if err := s.PublishAIContextArtifact(t.Context(), a, u.ID); err != nil {
			t.Fatal(err)
		}
	}
	items, _, _ := s.ListAIContextArtifacts(t.Context(), r.ID, 10, 0)
	if items[0].Versions != MaxArtifactVersions || items[0].Version != MaxArtifactVersions+3 {
		t.Fatalf("kept %d versions, latest %d", items[0].Versions, items[0].Version)
	}
	if _, err := s.GetAIContextArtifact(t.Context(), r.ID, "plan", 3); !errors.Is(err, ErrNotFound) {
		t.Fatal("a pruned version is still readable", err)
	}
}

// Reading consent is not writing consent. A connection publishes only where its
// owner said it may, and a client that knows nothing of publishing cannot
// clear or widen that by saving read consent.
func TestAConnectionPublishesOnlyWhereItsOwnerSaidSo(t *testing.T) {
	s, r, u, g := publishFixture(t)
	if err := s.ReplaceAIContextConnectionAccess(t.Context(), g.ID, u.ID, []string{r.ID}, nil); err != nil {
		t.Fatal(err)
	}
	if ok, _ := s.AIContextConnectionPublishAccess(t.Context(), r.ID, g.ID, u.ID); ok {
		t.Fatal("read consent alone let a connection publish")
	}
	if err := s.ReplaceAIContextConnectionAccess(t.Context(), g.ID, u.ID, []string{r.ID}, []string{r.ID}); err != nil {
		t.Fatal(err)
	}
	if ok, _ := s.AIContextConnectionPublishAccess(t.Context(), r.ID, g.ID, u.ID); !ok {
		t.Fatal("explicit publish consent was not recorded")
	}
	// Saving read consent again without saying anything about publishing
	// keeps it.
	if err := s.ReplaceAIContextConnectionAccess(t.Context(), g.ID, u.ID, []string{r.ID}, nil); err != nil {
		t.Fatal(err)
	}
	choices, err := s.AIContextConnectionChoices(t.Context(), g.ID, u.ID, 10, 0)
	if err != nil || len(choices.PublishRepositoryIDs) != 1 {
		t.Fatalf("publish consent lost on a read-only save: %+v, %v", choices, err)
	}
	if err := s.ReplaceAIContextConnectionAccess(t.Context(), g.ID, u.ID, []string{r.ID}, []string{}); err != nil {
		t.Fatal(err)
	}
	if ok, _ := s.AIContextConnectionPublishAccess(t.Context(), r.ID, g.ID, u.ID); ok {
		t.Fatal("an explicit empty publish list did not clear it")
	}
	// Removing the member removes every consent, publishing included.
	if err := s.ReplaceAIContextConnectionAccess(t.Context(), g.ID, u.ID, []string{r.ID}, []string{r.ID}); err != nil {
		t.Fatal(err)
	}
	if err := s.ReplaceAIContextMembers(t.Context(), r.ID, nil); err != nil {
		t.Fatal(err)
	}
	if ok, _ := s.AIContextConnectionPublishAccess(t.Context(), r.ID, g.ID, u.ID); ok {
		t.Fatal("a removed member's connection can still publish")
	}
}

package store

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"time"

	"github.com/eyupio/zoomies/internal/aicontext"
)

// ClaimAIContextMaintenance atomically replaces a settled proposal. Source
// availability closes before publication and never falls back to old context.
func (s *Store) ClaimAIContextMaintenance(ctx context.Context, operation *AIContextSetup, previousHash string, config aicontext.Config) error {
	if err := config.Validate(); err != nil {
		return err
	}
	if operation.Revision < 2 || len(operation.PlanHash) != 64 || len(operation.PlanJSON) > 4<<20 || len(previousHash) != 64 {
		return fmt.Errorf("invalid reviewed maintenance plan")
	}
	encoded, err := json.Marshal(config)
	if err != nil {
		return err
	}
	token, now := NewID("ctxlease"), s.Now()
	err = s.tx(ctx, func(tx *sql.Tx) error {
		res, err := tx.ExecContext(ctx, `UPDATE ai_context_repositories SET config_json=?,revision=revision+1,available=0,updated_at=? WHERE id=? AND revision=? AND EXISTS(SELECT 1 FROM ai_context_setups WHERE repository_id=? AND plan_hash=? AND lease_until<=?)`, string(encoded), ms(now), operation.RepositoryID, operation.Revision-1, operation.RepositoryID, previousHash, ms(now))
		if err != nil {
			return err
		}
		n, err := res.RowsAffected()
		if err != nil {
			return err
		}
		if n != 1 {
			return ErrConflict
		}
		if _, err = tx.ExecContext(ctx, `UPDATE ai_context_setups SET revision=?,plan_hash=?,plan_json=?,state='pending',pr_number=0,pr_url='',lease_token=?,lease_until=?,updated_at=? WHERE repository_id=?`, operation.Revision, operation.PlanHash, operation.PlanJSON, token, ms(now.Add(5*time.Minute)), ms(now), operation.RepositoryID); err != nil {
			return err
		}
		if _, err = tx.ExecContext(ctx, `DELETE FROM ai_context_freshness WHERE repository_id=?`, operation.RepositoryID); err != nil {
			return err
		}
		if config.Disabled {
			for _, table := range []string{"ai_context_connection_repositories", "ai_context_members", "ai_context_snapshots", "ai_context_artifacts"} {
				if _, err = tx.ExecContext(ctx, `DELETE FROM `+table+` WHERE repository_id=?`, operation.RepositoryID); err != nil {
					return err
				}
			}
		}
		return nil
	})
	if err == nil {
		operation.LeaseToken = token
		operation.State = "pending"
	}
	return err
}

