package store

import (
	"context"
	"database/sql"
	"fmt"
	"slices"
	"strings"
	"time"
)

// The reads in this file are what the controller's analyses (internal/analysis)
// are assembled from. Each is one statement on the reader, and each takes a
// limit and says when it stopped at it: an analysis that ranks causes over a
// sample nobody told it was cut would read a busy period's newest hour as the
// whole period. What comes back to Go is the answer, never the window: an
// average is taken in SQL, and a narrowed analysis narrows the read rather
// than filtering a fleet-wide one, so the pool asked about cannot be the part
// a limit cut away.
//
// Each seeks an index rather than walking a table, which
// TestTheAnalysisReadsSeekTheirIndexes holds them to, and most of those ranges
// are the window itself or the window and a fixed tail. Two cannot be bounded
// below, and their cost is set by retention instead. A runner of a
// non-ephemeral pool can live for as long as the fleet runs, so a runner alive
// in the window may have been created at any time before it: RunnerSpans reads
// rows created before the window's end, which is what retention.runners keeps
// of finished runners plus every live one, and sessions that ended since the
// window opened, which reaches to now. The starting rungs HostThrottleChanges
// reads are the same: a throttle can stand for any length of time, so each
// host's last change before the window is looked for in every throttle row
// before it, which is few because a rung moves at most a few times an hour.

// maxJobLife is the longest a GitHub Actions job can last from being queued to
// completing: GitHub cancels a job left queued for 24 hours, and a job on a
// self-hosted runner may run for at most 5 days. A job that started in a
// window therefore completed before the window's end plus this, which bounds
// above the index range a ByActivity read seeks; without it a read of a day a
// month ago walks every job completed in the month since.
const maxJobLife = 24*time.Hour + 5*24*time.Hour

// needLimit refuses an unbounded analysis read. A zero limit is a caller that
// forgot one, and reading the whole window in its place is the failure these
// reads exist to design out.
func needLimit(limit int) error {
	if limit < 1 {
		return fmt.Errorf("store: an analysis read needs a limit of at least one, got %d", limit)
	}
	return nil
}

// JobWaitFilter selects the jobs JobWaits reads.
type JobWaitFilter struct {
	// Since is inclusive and Until exclusive, as JobFilter's are.
	Since, Until time.Time
	// PoolID and HostID narrow the read in SQL; empty is every pool or host.
	PoolID, HostID string
	// ByActivity selects the jobs that started or completed in the window
	// instead of those queued in it. A host's failures are placed when they
	// happened, and a job queued the evening before that failed this morning
	// is this morning's failure: read by queue time it would belong to no
	// period at all.
	ByActivity bool
	// ManagedOnly keeps the jobs this controller has a hand in, as JobFilter's
	// ManagedOnly does and by the same predicate. GitHub reports every job in
	// an installed repository, and one whose labels all name another vendor's
	// runners is that vendor's to run: read for the queue wait it was "no pool
	// claimed it" while still queued, or seconds nothing here explains once it
	// had started, and on a busy installation it took up the read's limit
	// before this fleet's own jobs did.
	ManagedOnly bool
}

// JobWait is one job as the queue-wait breakdown and host pressure need it:
// when each thing happened to it, and when its runner was asked for and came
// up.
type JobWait struct {
	ID, PoolID, HostID, Repo, Workflow, JobName, Conclusion string
	// ControllerVersion is empty for a job recorded before releases were
	// stamped.
	ControllerVersion string
	FaultKind         FaultKind
	// RunnerFault is set when a runner of this fleet stopped under the job; a
	// fault recorded before categories existed has it with no FaultKind.
	RunnerFault                        string
	OOMKilled                          bool
	QueuedAt                           time.Time
	EligibleAt, StartedAt, CompletedAt *time.Time
	// HeldAt, ApprovedAt and FirstStartFailureAt are the first waiting,
	// approved and runner_start_failed entries on the job's timeline. A
	// webhook is delivered at least once, so a repeat must not move a phase's
	// start; the first is the one that counts.
	HeldAt, ApprovedAt, FirstStartFailureAt *time.Time
	// RunnerID is the runner the job last ran on, kept from the job even when
	// neither the runner's row nor its session remains.
	RunnerID string
	// RunnerRequestedAt and RunnerRegisteredAt come from the runner's row
	// while it is kept (retention.runners) and from its session after: the
	// session keeps both for a year. RunnerContainerStartedAt is the row's
	// alone, because the session table has no container start; it is nil once
	// the row is pruned, which says the phase is unknown rather than zero.
	RunnerRequestedAt, RunnerContainerStartedAt, RunnerRegisteredAt *time.Time
}

// jobWaitsQuery builds JobWaits' one statement. It asks for limit+1 rows, so
// the extra row says whether more matched without a second COUNT over the
// window.
func jobWaitsQuery(f JobWaitFilter, limit int) (string, []any) {
	since, until := ms(f.Since), ms(f.Until)
	var cond []string
	var args []any
	if f.ByActivity {
		// Index ranges rather than one test on started_at, which has no
		// index: a job completed in the window, or after it within
		// maxJobLife and started in it, from one range on the completed
		// index; and a job still running that started in it, from the few
		// rows in progress, which have no completed_at to bound and need none.
		cond = append(cond, `((j.state = 'completed' AND j.completed_at >= ? AND j.completed_at < ?
				AND (j.completed_at < ? OR (j.started_at >= ? AND j.started_at < ?)))
			OR (j.state = 'in_progress' AND j.started_at >= ? AND j.started_at < ?))`)
		args = append(args, since, ms(f.Until.Add(maxJobLife)), until, since, until, since, until)
	} else {
		cond = append(cond, `j.queued_at >= ? AND j.queued_at < ?`)
		args = append(args, since, until)
	}
	if f.PoolID != "" {
		cond = append(cond, `j.pool_id = ?`)
		args = append(args, f.PoolID)
	}
	if f.HostID != "" {
		cond = append(cond, `j.host_id = ?`)
		args = append(args, f.HostID)
	}
	if f.ManagedOnly {
		cond = append(cond, managedJobSQL("j"))
	}
	first := func(kind JobEventKind) string {
		return `(SELECT MIN(e.at) FROM job_events e WHERE e.job_id = j.id AND e.kind = '` + string(kind) + `')`
	}
	// The row wins over the session whenever it exists, column by column
	// included: a row with no registration is a runner that never
	// registered, and the session written from it says the same.
	q := `SELECT j.id, j.pool_id, COALESCE(j.host_id, ''), j.repo, j.workflow, j.job_name, j.conclusion,
		COALESCE(j.controller_version, ''), j.fault_kind, j.runner_fault, j.oom_killed,
		j.queued_at, j.eligible_at, j.started_at, j.completed_at,
		` + first(JobEventWaiting) + `, ` + first(JobEventApproved) + `, ` + first(JobEventRunnerStartFailed) + `,
		j.runner_id,
		CASE WHEN r.id IS NOT NULL THEN COALESCE(r.create_task_issued_at, r.created_at)
			ELSE COALESCE(rs.create_task_issued_at, rs.started_at) END,
		r.container_started_at,
		CASE WHEN r.id IS NOT NULL THEN r.registered_at ELSE rs.registered_at END
		FROM jobs j
		LEFT JOIN runners r ON r.id = j.runner_id
		LEFT JOIN runner_sessions rs ON rs.runner_id = j.runner_id
		WHERE ` + strings.Join(cond, " AND ") + `
		ORDER BY j.queued_at DESC, j.id ASC LIMIT ?`
	return q, append(args, limit+1)
}

// JobWaits returns the jobs f selects, newest queued first, at most limit of
// them; more is true when more matched. Queued in [Since, Until) by default,
// or started or completed in it with ByActivity.
func (s *Store) JobWaits(ctx context.Context, f JobWaitFilter, limit int) (jobs []JobWait, more bool, err error) {
	if err := needLimit(limit); err != nil {
		return nil, false, err
	}
	q, args := jobWaitsQuery(f, limit)
	rows, err := s.read.QueryContext(ctx, q, args...)
	if err != nil {
		return nil, false, err
	}
	defer rows.Close()
	for rows.Next() {
		var j JobWait
		var queued int64
		var oom int
		var eligible, started, done, held, approved, failed, requested, container, registered sql.NullInt64
		if err := rows.Scan(&j.ID, &j.PoolID, &j.HostID, &j.Repo, &j.Workflow, &j.JobName, &j.Conclusion,
			&j.ControllerVersion, &j.FaultKind, &j.RunnerFault, &oom,
			&queued, &eligible, &started, &done, &held, &approved, &failed,
			&j.RunnerID, &requested, &container, &registered); err != nil {
			return nil, false, err
		}
		j.OOMKilled, j.QueuedAt = oom == 1, at(queued)
		j.EligibleAt, j.StartedAt, j.CompletedAt = atp(eligible), atp(started), atp(done)
		j.HeldAt, j.ApprovedAt, j.FirstStartFailureAt = atp(held), atp(approved), atp(failed)
		j.RunnerRequestedAt, j.RunnerContainerStartedAt, j.RunnerRegisteredAt = atp(requested), atp(container), atp(registered)
		jobs = append(jobs, j)
	}
	if err := rows.Err(); err != nil {
		return nil, false, err
	}
	if len(jobs) > limit {
		return jobs[:limit], true, nil
	}
	return jobs, false, nil
}

// RunnerSpanFilter selects the runners RunnerSpans reads.
type RunnerSpanFilter struct {
	// Since is inclusive and Until exclusive.
	Since, Until time.Time
	// PoolID and HostID narrow the read in SQL; empty is every pool or host.
	PoolID, HostID string
}

// RunnerSpan is one runner's life: when it was asked for, came up and ended,
// and how it ended.
type RunnerSpan struct {
	RunnerID, PoolID, HostID string
	// RequestedAt is the first delivery of the runner's create task to its
	// host, or its creation for a runner from before that was stamped.
	RequestedAt time.Time
	// ContainerStartedAt is nil for a span read from a session, which keeps
	// no container start. EndedAt is nil for a runner still alive.
	ContainerStartedAt, RegisteredAt, EndedAt *time.Time
	// State, FaultKind and Message are the row's. A span read from the
	// session of a pruned runner has none of them: the session table keeps no
	// state, fault or message, so State is "" and the outcome of a start that
	// never registered is not known.
	State     RunnerState
	FaultKind FaultKind
	// Message is written by a host, so whoever shows it to a model treats it
	// as untrusted.
	Message string
}

// runnerSpansQuery builds RunnerSpans' one statement: the rows, then the
// sessions whose row is gone, newest request first across both.
//
// A runner counts as alive in the window when it was asked for before its end
// and either was asked for inside it or ended at or after its start. The first
// half keeps a runner that was asked for inside the window and whose end
// stamps were lost; the second draws the line at the start on the same side
// for a row as for a session, so a runner reads the same before and after its
// row is pruned. Neither half can be bounded below (see the file's comment).
func runnerSpansQuery(f RunnerSpanFilter, limit int) (string, []any) {
	since, until := ms(f.Since), ms(f.Until)
	rowCond := []string{`r.created_at < ?`,
		`(r.created_at >= ? OR r.state NOT IN ('removed','failed')
			OR COALESCE(r.finished_at, r.host_removed_at, r.cleaned_up_at, r.created_at) >= ?)`}
	rowArgs := []any{until, since, since}
	// A session always ends at or after it starts, so "started inside or
	// ended after the start" is "ended at or after the start", which is a
	// range on the finished index: the sessions that ended since the window
	// opened. The start's own index would be a range over a year of them;
	// the unary plus keeps the planner off it.
	sessCond := []string{`+rs.started_at < ?`, `rs.finished_at >= ?`,
		`NOT EXISTS (SELECT 1 FROM runners x WHERE x.id = rs.runner_id)`}
	sessArgs := []any{until, since}
	if f.PoolID != "" {
		rowCond, sessCond = append(rowCond, `r.pool_id = ?`), append(sessCond, `rs.pool_id = ?`)
		rowArgs, sessArgs = append(rowArgs, f.PoolID), append(sessArgs, f.PoolID)
	}
	if f.HostID != "" {
		rowCond, sessCond = append(rowCond, `r.host_id = ?`), append(sessCond, `rs.host_id = ?`)
		rowArgs, sessArgs = append(rowArgs, f.HostID), append(sessArgs, f.HostID)
	}
	q := `SELECT r.id, r.pool_id, COALESCE(r.host_id, ''), COALESCE(r.create_task_issued_at, r.created_at) AS requested,
			r.container_started_at, r.registered_at,
			CASE WHEN r.state IN ('removed','failed') THEN COALESCE(r.finished_at, r.host_removed_at, r.cleaned_up_at) END,
			r.state, r.fault_kind, r.message
		FROM runners r WHERE ` + strings.Join(rowCond, " AND ") + `
		UNION ALL
		SELECT rs.runner_id, rs.pool_id, rs.host_id, COALESCE(rs.create_task_issued_at, rs.started_at),
			NULL, rs.registered_at, rs.finished_at, '', '', ''
		FROM runner_sessions rs WHERE ` + strings.Join(sessCond, " AND ") + `
		ORDER BY requested DESC, 1 ASC LIMIT ?`
	args := append(rowArgs, sessArgs...)
	return q, append(args, limit+1)
}

// RunnerSpans returns the runners f selects that were alive at any point of
// [Since, Until), newest request first, at most limit of them; more is true
// when more matched. A runner whose row is kept is read from the row; one
// whose row was pruned is read from its session; none is read twice.
func (s *Store) RunnerSpans(ctx context.Context, f RunnerSpanFilter, limit int) (spans []RunnerSpan, more bool, err error) {
	if err := needLimit(limit); err != nil {
		return nil, false, err
	}
	q, args := runnerSpansQuery(f, limit)
	rows, err := s.read.QueryContext(ctx, q, args...)
	if err != nil {
		return nil, false, err
	}
	defer rows.Close()
	for rows.Next() {
		var x RunnerSpan
		var requested int64
		var container, registered, ended sql.NullInt64
		if err := rows.Scan(&x.RunnerID, &x.PoolID, &x.HostID, &requested, &container, &registered, &ended,
			&x.State, &x.FaultKind, &x.Message); err != nil {
			return nil, false, err
		}
		x.RequestedAt = at(requested)
		x.ContainerStartedAt, x.RegisteredAt, x.EndedAt = atp(container), atp(registered), atp(ended)
		spans = append(spans, x)
	}
	if err := rows.Err(); err != nil {
		return nil, false, err
	}
	if len(spans) > limit {
		return spans[:limit], true, nil
	}
	return spans, false, nil
}

// capacityBlockedQuery builds CapacityBlockedMinutes' statement: newest
// first, so a cut keeps the minutes nearest the window's end, as the other
// reads keep their newest rows.
func capacityBlockedQuery(from, to time.Time, poolID string, limit int) (string, []any) {
	q := `SELECT pool_id, at FROM usage_capacity_samples WHERE at >= ? AND at < ? AND blocked = 1`
	args := []any{ms(from), ms(to)}
	if poolID != "" {
		q += ` AND pool_id = ?`
		args = append(args, poolID)
	}
	return q + ` ORDER BY at DESC, pool_id LIMIT ?`, append(args, limit+1)
}

// CapacityBlockedMinutes returns the minutes in [from, to) that
// usage_capacity_samples records as blocked at capacity, by pool and oldest
// first within each, at most limit minutes in all; more is true when more
// matched. An empty poolID is every pool.
func (s *Store) CapacityBlockedMinutes(ctx context.Context, from, to time.Time, poolID string, limit int) (map[string][]time.Time, bool, error) {
	if err := needLimit(limit); err != nil {
		return nil, false, err
	}
	q, args := capacityBlockedQuery(from, to, poolID, limit)
	rows, err := s.read.QueryContext(ctx, q, args...)
	if err != nil {
		return nil, false, err
	}
	defer rows.Close()
	out := map[string][]time.Time{}
	n, more := 0, false
	for rows.Next() {
		var pool string
		var minute int64
		if err := rows.Scan(&pool, &minute); err != nil {
			return nil, false, err
		}
		if n == limit {
			more = true
			break
		}
		n++
		out[pool] = append(out[pool], at(minute))
	}
	if err := rows.Err(); err != nil {
		return nil, false, err
	}
	for _, minutes := range out {
		slices.Reverse(minutes)
	}
	return out, more, nil
}

// VersionSpan is the completed jobs of one release in a window: when the
// first and last of them were queued, and how many there were.
type VersionSpan struct {
	// Version is UnknownVersion for jobs recorded before releases were
	// stamped.
	Version     string
	First, Last time.Time
	Jobs        int
}

// jobVersionSpansQuery builds JobVersionSpans' statement, latest release
// first so a cut drops the oldest.
func jobVersionSpansQuery(from, to time.Time, exclude []string, limit int) (string, []any) {
	q := `SELECT COALESCE(controller_version, '` + UnknownVersion + `') AS v, MIN(queued_at), MAX(queued_at), COUNT(*)
		FROM jobs WHERE queued_at >= ? AND queued_at < ? AND state = 'completed'`
	args := []any{ms(from), ms(to)}
	if len(exclude) > 0 {
		q += ` AND conclusion NOT IN (` + strings.TrimSuffix(strings.Repeat("?,", len(exclude)), ",") + `)`
		for _, c := range exclude {
			args = append(args, c)
		}
	}
	return q + ` GROUP BY v ORDER BY MAX(queued_at) DESC, v LIMIT ?`, append(args, limit+1)
}

// JobVersionSpans returns the completed jobs queued in [from, to) grouped by
// the release that ran them, latest last job first, at most limit releases;
// more is true when more matched. Jobs with a conclusion in exclude are left
// out of every figure, so a release whose jobs were all cancelled is not
// offered as a side with nothing to compare.
func (s *Store) JobVersionSpans(ctx context.Context, from, to time.Time, exclude []string, limit int) ([]VersionSpan, bool, error) {
	if err := needLimit(limit); err != nil {
		return nil, false, err
	}
	q, args := jobVersionSpansQuery(from, to, exclude, limit)
	rows, err := s.read.QueryContext(ctx, q, args...)
	if err != nil {
		return nil, false, err
	}
	defer rows.Close()
	var out []VersionSpan
	for rows.Next() {
		var v VersionSpan
		var first, last int64
		if err := rows.Scan(&v.Version, &first, &last, &v.Jobs); err != nil {
			return nil, false, err
		}
		v.First, v.Last = at(first), at(last)
		out = append(out, v)
	}
	if err := rows.Err(); err != nil {
		return nil, false, err
	}
	if len(out) > limit {
		return out[:limit], true, nil
	}
	return out, false, nil
}

// meanFleetCapacitySQL averages, over the sampled minutes of a window, the
// slots every host together was taking at that minute.
const meanFleetCapacitySQL = `SELECT AVG(slots) FROM (SELECT SUM(capacity) AS slots
	FROM host_samples WHERE at >= ? AND at < ? GROUP BY at)`

// MeanFleetCapacity is the fleet's slots on offer averaged over the minutes
// in [from, to) that a host sample covers, or nil when none does: no samples
// is not zero slots. It is one figure, so it is worked out in SQL; read into
// Go it would be every host's every minute of the window.
func (s *Store) MeanFleetCapacity(ctx context.Context, from, to time.Time) (*float64, error) {
	var mean sql.NullFloat64
	if err := s.read.QueryRowContext(ctx, meanFleetCapacitySQL, ms(from), ms(to)).Scan(&mean); err != nil {
		return nil, err
	}
	if !mean.Valid {
		return nil, nil
	}
	return &mean.Float64, nil
}

// hostSamplesBetweenSQL reads one host's minutes newest first, so a cut keeps
// the ones nearest the window's end.
const hostSamplesBetweenSQL = `SELECT ` + hostSampleCols + ` FROM host_samples
	WHERE host_id = ? AND at >= ? AND at < ? ORDER BY at DESC LIMIT ?`

// HostSamplesBetween returns one host's samples in [from, to), oldest first,
// at most limit of them; more is true when more matched, and the ones kept
// are the newest. ListHostSamples reads to now and has no limit, which suits
// the Hosts page's day and not an analysis over a month.
func (s *Store) HostSamplesBetween(ctx context.Context, hostID string, from, to time.Time, limit int) ([]HostSample, bool, error) {
	if err := needLimit(limit); err != nil {
		return nil, false, err
	}
	rows, err := s.read.QueryContext(ctx, hostSamplesBetweenSQL, hostID, ms(from), ms(to), limit+1)
	if err != nil {
		return nil, false, err
	}
	defer rows.Close()
	var out []HostSample
	for rows.Next() {
		h, err := scanHostSample(rows)
		if err != nil {
			return nil, false, err
		}
		out = append(out, h)
	}
	if err := rows.Err(); err != nil {
		return nil, false, err
	}
	more := len(out) > limit
	if more {
		out = out[:limit]
	}
	slices.Reverse(out)
	return out, more, nil
}

// ThrottleChange is one step of a host's throttle as the audit log recorded
// it: the host, when, and the rung it stood on after.
//
// It carries no actor and no detail on purpose. An operator's clear is
// written under their name, and the analyses built from these rows are shown
// to anyone who can read jobs or runners, who could not read the audit log
// itself; when a host was throttled is theirs to know, who lifted it is not.
type ThrottleChange struct {
	HostID string
	// Action is host.throttle, host.throttle_lift or host.throttle_clear.
	Action string
	// Level is the rung after the change: zero after a clear, whose detail
	// names the rung that was cleared rather than the one left, and zero for
	// a row whose detail cannot be read.
	Level int
	At    time.Time
}

// throttleLevelSQL is a throttle row's rung after the change. json_valid
// guards json_extract, which fails the whole statement on one malformed
// document.
const throttleLevelSQL = `CASE WHEN action = 'host.throttle_clear' THEN 0
	WHEN json_valid(after) THEN COALESCE(json_extract(after, '$.level'), 0) ELSE 0 END`

// throttleActionsSQL names the three throttle actions. They are written for
// hosts alone, so the action index is the whole test: a condition on
// target_kind would invite the target index, which is every host's audit
// trail since the fleet began.
const throttleActionsSQL = `action IN ('host.throttle', 'host.throttle_lift', 'host.throttle_clear')`

// hostThrottleChangesSQL is two reads in one statement. The first is the
// window's rows newest first, so a cut keeps the ones nearest its end. The
// second is each host's last row before the window, the rung it started the
// window on (SQLite takes a bare column from the row MAX chose); the last
// column tells the two apart, so the limit counts only the window's rows.
const hostThrottleChangesSQL = `SELECT * FROM (SELECT target_id, action, ` + throttleLevelSQL + `, created_at, 0
		FROM audit_events WHERE ` + throttleActionsSQL + ` AND created_at >= ? AND created_at < ?
		ORDER BY created_at DESC, id LIMIT ?)
	UNION ALL
	SELECT target_id, action, ` + throttleLevelSQL + `, MAX(created_at), 1
		FROM audit_events WHERE ` + throttleActionsSQL + ` AND created_at < ?
		GROUP BY target_id`

// HostThrottleChanges returns every host's throttle steps in [from, to),
// oldest first, at most limit of them; more is true when more matched, and
// the ones kept are the newest. Ahead of them, and outside the limit, it
// returns each host's last step before from: a throttle that went on before
// the window and came off after it leaves no row inside, and is otherwise
// invisible once the host's own Throttle.Since has been cleared. There is at
// most one such row a host, so they cannot crowd the window's out.
func (s *Store) HostThrottleChanges(ctx context.Context, from, to time.Time, limit int) ([]ThrottleChange, bool, error) {
	if err := needLimit(limit); err != nil {
		return nil, false, err
	}
	rows, err := s.read.QueryContext(ctx, hostThrottleChangesSQL, ms(from), ms(to), limit+1, ms(from))
	if err != nil {
		return nil, false, err
	}
	defer rows.Close()
	var starting, window []ThrottleChange
	for rows.Next() {
		var c ThrottleChange
		var created int64
		var before bool
		if err := rows.Scan(&c.HostID, &c.Action, &c.Level, &created, &before); err != nil {
			return nil, false, err
		}
		c.At = at(created)
		if before {
			starting = append(starting, c)
		} else {
			window = append(window, c)
		}
	}
	if err := rows.Err(); err != nil {
		return nil, false, err
	}
	more := len(window) > limit
	if more {
		window = window[:limit]
	}
	slices.Reverse(window)
	slices.SortFunc(starting, func(a, b ThrottleChange) int {
		if c := a.At.Compare(b.At); c != 0 {
			return c
		}
		return strings.Compare(a.HostID, b.HostID)
	})
	return append(starting, window...), more, nil
}

package store

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"time"
)

// AssistantConversation is one person's past chat with Eli: the messages as
// the page sent them, bounded and redacted by the API before they got here,
// under a title taken from the first question.
type AssistantConversation struct {
	ID     string
	UserID string
	Title  string
	// Messages is the conversation as JSON, opaque here. Nil on a row read
	// from the list, which carries the count instead.
	Messages     json.RawMessage
	MessageCount int
	CreatedAt    time.Time
	UpdatedAt    time.Time
}

// MaxAssistantConversations is how many one person keeps. Saving one past
// that removes their oldest, so the list stays a list and not an archive;
// the retention window removes the rest by age.
const MaxAssistantConversations = 50

const assistantConversationCols = `id, user_id, title, message_count, created_at, updated_at`

func scanAssistantConversation(sc interface{ Scan(...any) error }, withMessages bool) (*AssistantConversation, error) {
	var c AssistantConversation
	var created, updated int64
	var err error
	if withMessages {
		var raw string
		err = sc.Scan(&c.ID, &c.UserID, &c.Title, &c.MessageCount, &created, &updated, &raw)
		c.Messages = json.RawMessage(raw)
	} else {
		err = sc.Scan(&c.ID, &c.UserID, &c.Title, &c.MessageCount, &created, &updated)
	}
	if err != nil {
		return nil, err
	}
	c.CreatedAt, c.UpdatedAt = at(created), at(updated)
	return &c, nil
}

// SaveAssistantConversation writes a conversation: a new row when it has no
// ID, otherwise a replacement of the row with that ID, which must be the same
// person's (ErrNotFound otherwise, so one account cannot overwrite another's
// by guessing an id). The person's oldest conversations past the cap go with
// the same write.
func (s *Store) SaveAssistantConversation(ctx context.Context, c *AssistantConversation) error {
	now := s.Now()
	return s.tx(ctx, func(tx *sql.Tx) error {
		if c.ID == "" {
			c.ID = NewID(PrefixAssistantConversation)
			c.CreatedAt, c.UpdatedAt = now, now
			if _, err := tx.ExecContext(ctx, `INSERT INTO assistant_conversations (`+assistantConversationCols+`, messages)
				VALUES (?, ?, ?, ?, ?, ?, ?)`, c.ID, c.UserID, c.Title, c.MessageCount, ms(now), ms(now), string(c.Messages)); err != nil {
				return wrapWrite(err)
			}
		} else {
			res, err := tx.ExecContext(ctx, `UPDATE assistant_conversations SET title = ?, messages = ?, message_count = ?, updated_at = ?
				WHERE id = ? AND user_id = ?`, c.Title, string(c.Messages), c.MessageCount, ms(now), c.ID, c.UserID)
			if err != nil {
				return wrapWrite(err)
			}
			if n, _ := res.RowsAffected(); n == 0 {
				return ErrNotFound
			}
			c.UpdatedAt = now
		}
		_, err := tx.ExecContext(ctx, `DELETE FROM assistant_conversations WHERE user_id = ? AND id NOT IN (
			SELECT id FROM assistant_conversations WHERE user_id = ? ORDER BY updated_at DESC, id DESC LIMIT ?)`,
			c.UserID, c.UserID, MaxAssistantConversations)
		return wrapWrite(err)
	})
}

// ListAssistantConversations is one person's conversations, newest first,
// without their messages.
func (s *Store) ListAssistantConversations(ctx context.Context, userID string) ([]*AssistantConversation, error) {
	rows, err := s.read.QueryContext(ctx, `SELECT `+assistantConversationCols+` FROM assistant_conversations
		WHERE user_id = ? ORDER BY updated_at DESC, id DESC`, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []*AssistantConversation{}
	for rows.Next() {
		c, err := scanAssistantConversation(rows, false)
		if err != nil {
			return nil, err
		}
		out = append(out, c)
	}
	return out, rows.Err()
}

// GetAssistantConversation is one conversation with its messages, and
// ErrNotFound for another person's as much as for none.
func (s *Store) GetAssistantConversation(ctx context.Context, userID, id string) (*AssistantConversation, error) {
	c, err := scanAssistantConversation(s.read.QueryRowContext(ctx, `SELECT `+assistantConversationCols+`, messages
		FROM assistant_conversations WHERE id = ? AND user_id = ?`, id, userID), true)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	return c, err
}

// DeleteAssistantConversation removes one of a person's conversations.
func (s *Store) DeleteAssistantConversation(ctx context.Context, userID, id string) error {
	res, err := s.exec(ctx, `DELETE FROM assistant_conversations WHERE id = ? AND user_id = ?`, id, userID)
	if err != nil {
		return err
	}
	return affected(res, "assistant conversation", id)
}

// PruneAssistantConversations removes every conversation not touched since
// before: the retention window, applied to everyone's.
func (s *Store) PruneAssistantConversations(ctx context.Context, before time.Time) (int64, error) {
	res, err := s.exec(ctx, `DELETE FROM assistant_conversations WHERE updated_at < ?`, ms(before))
	if err != nil {
		return 0, err
	}
	return res.RowsAffected()
}

package store

import (
	"context"
	"database/sql"
	"time"
)

// AssistantProvider is one model the assistant may talk to. KeyEnc is the
// API key sealed with the instance key and is never rendered; LastCheck is
// the JSON the last check returned, which the controller writes and reads.
type AssistantProvider struct {
	ID        string
	Name      string
	Kind      string
	BaseURL   string
	Model     string
	KeyEnc    []byte
	Enabled   bool
	IsDefault bool
	// FleetAccess is whether the assistant may read this fleet through the
	// provider. Off unless an administrator turned it on for this one.
	FleetAccess bool
	// ReasoningEffort is how hard the provider's model should think before it
	// answers, in the provider's own words (none, low, medium or high), or empty
	// for the provider's default. It is the provider's to interpret: a thinking
	// model at its default effort can spend an answer's whole room on reasoning.
	ReasoningEffort string
	// MaxOutputTokens is how much the model may write in one round, thinking
	// included, or zero for automatic, which the controller works out. A number
	// is kept exactly. The right number is the model's, and the cost of the room
	// is the provider's price.
	MaxOutputTokens int
	// OwnerID is the account a provider belongs to, and empty for one that is
	// shared by every administrator. Set when it is created and never changed.
	OwnerID       string
	LastCheck     []byte
	LastCheckedAt *time.Time
	CreatedAt     time.Time
	UpdatedAt     time.Time
}

const assistantProviderCols = `id, name, kind, base_url, model, key_enc, enabled, is_default, fleet_access, reasoning_effort, max_output_tokens, owner_id,
	last_check, last_checked_at, created_at, updated_at`

func scanAssistantProvider(sc interface{ Scan(...any) error }) (*AssistantProvider, error) {
	var p AssistantProvider
	var enabled, isDefault, fleetAccess int
	var created, updated int64
	var check sql.NullString
	var checked sql.NullInt64
	if err := sc.Scan(&p.ID, &p.Name, &p.Kind, &p.BaseURL, &p.Model, &p.KeyEnc, &enabled, &isDefault, &fleetAccess, &p.ReasoningEffort, &p.MaxOutputTokens, &p.OwnerID,
		&check, &checked, &created, &updated); err != nil {
		return nil, err
	}
	p.Enabled, p.IsDefault, p.FleetAccess = enabled == 1, isDefault == 1, fleetAccess == 1
	if check.Valid {
		p.LastCheck = []byte(check.String)
	}
	p.LastCheckedAt = atp(checked)
	p.CreatedAt, p.UpdatedAt = at(created), at(updated)
	return &p, nil
}

// ListAssistantProviders returns every provider, by name.
func (s *Store) ListAssistantProviders(ctx context.Context) ([]*AssistantProvider, error) {
	rows, err := s.read.QueryContext(ctx, `SELECT `+assistantProviderCols+` FROM assistant_providers ORDER BY name`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*AssistantProvider
	for rows.Next() {
		p, err := scanAssistantProvider(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, p)
	}
	return out, rows.Err()
}

// GetAssistantProvider returns one provider, or ErrNotFound.
func (s *Store) GetAssistantProvider(ctx context.Context, id string) (*AssistantProvider, error) {
	p, err := scanAssistantProvider(s.read.QueryRowContext(ctx,
		`SELECT `+assistantProviderCols+` FROM assistant_providers WHERE id = ?`, id))
	if err == sql.ErrNoRows {
		return nil, ErrNotFound
	}
	return p, err
}

// CreateAssistantProvider inserts a provider. The key is not part of it:
// SetAssistantProviderKey writes the sealed bytes, so the one place that has
// to think about the instance key is the one place that holds it.
func (s *Store) CreateAssistantProvider(ctx context.Context, p *AssistantProvider) error {
	if p.ID == "" {
		p.ID = NewID(PrefixAssistantProvider)
	}
	now := s.Now()
	p.CreatedAt, p.UpdatedAt = now, now
	_, err := s.exec(ctx, `INSERT INTO assistant_providers
		(id, name, kind, base_url, model, enabled, is_default, fleet_access, reasoning_effort, max_output_tokens, owner_id, created_at, updated_at)
		VALUES (?, ?, ?, ?, ?, ?, 0, ?, ?, ?, ?, ?, ?)`,
		p.ID, p.Name, p.Kind, p.BaseURL, p.Model, boolInt(p.Enabled), boolInt(p.FleetAccess), p.ReasoningEffort, p.MaxOutputTokens, p.OwnerID, ms(now), ms(now))
	return wrapWrite(err)
}

// UpdateAssistantProvider persists the operator's half of a row: name, kind,
// address, model, whether it is enabled, whether it may read the fleet and how
// hard its model thinks. The key and the default have
// their own writers, so a form submitted from yesterday's page carries
// neither.
func (s *Store) UpdateAssistantProvider(ctx context.Context, p *AssistantProvider) error {
	now := s.Now()
	res, err := s.exec(ctx, `UPDATE assistant_providers
		SET name=?, kind=?, base_url=?, model=?, enabled=?, fleet_access=?, reasoning_effort=?, max_output_tokens=?, updated_at=? WHERE id=?`,
		p.Name, p.Kind, p.BaseURL, p.Model, boolInt(p.Enabled), boolInt(p.FleetAccess), p.ReasoningEffort, p.MaxOutputTokens, ms(now), p.ID)
	if err != nil {
		return wrapWrite(err)
	}
	p.UpdatedAt = now
	return affected(res, "assistant provider", p.ID)
}

// SetAssistantProviderKey replaces the sealed key.
func (s *Store) SetAssistantProviderKey(ctx context.Context, id string, enc []byte) error {
	res, err := s.exec(ctx, `UPDATE assistant_providers SET key_enc=?, updated_at=? WHERE id=?`, enc, ms(s.Now()), id)
	if err != nil {
		return err
	}
	return affected(res, "assistant provider", id)
}

// SetDefaultAssistantProvider makes one provider the default and no other,
// in one transaction, so no reader ever sees two or none in between.
func (s *Store) SetDefaultAssistantProvider(ctx context.Context, id string) error {
	return s.tx(ctx, func(tx *sql.Tx) error {
		if _, err := tx.ExecContext(ctx, `UPDATE assistant_providers SET is_default=0 WHERE is_default=1 AND owner_id=(SELECT owner_id FROM assistant_providers WHERE id=?) AND id<>?`, id, id); err != nil {
			return err
		}
		res, err := tx.ExecContext(ctx, `UPDATE assistant_providers SET is_default=1 WHERE id=?`, id)
		if err != nil {
			return err
		}
		return affected(res, "assistant provider", id)
	})
}

// SetAssistantProviderCheck records what the last check returned, leaving
// updated_at alone: a check is an observation, not a change.
func (s *Store) SetAssistantProviderCheck(ctx context.Context, id string, result []byte, checkedAt time.Time) error {
	res, err := s.exec(ctx, `UPDATE assistant_providers SET last_check=?, last_checked_at=? WHERE id=?`,
		string(result), ms(checkedAt), id)
	if err != nil {
		return err
	}
	return affected(res, "assistant provider", id)
}

// DeleteAssistantProvider removes a provider. Deleting the default leaves no
// default rather than promoting another: which model answers is a choice an
// administrator makes, not one the database makes for them.
func (s *Store) DeleteAssistantProvider(ctx context.Context, id string) error {
	res, err := s.exec(ctx, `DELETE FROM assistant_providers WHERE id = ?`, id)
	if err != nil {
		return err
	}
	return affected(res, "assistant provider", id)
}

package store

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"
)

// ---------------------------------------------------------------------------
// Users
// ---------------------------------------------------------------------------

const userCols = `id, username, email, display_name, role, password_hash, oidc_subject,
	disabled, must_change_password, created_at, last_login_at`

func scanUser(sc interface{ Scan(...any) error }) (*User, error) {
	var u User
	var disabled, mustChange int
	var created int64
	var login sql.NullInt64
	err := sc.Scan(&u.ID, &u.Username, &u.Email, &u.DisplayName, &u.Role, &u.PasswordHash,
		&u.OIDCSubject, &disabled, &mustChange, &created, &login)
	if err != nil {
		return nil, err
	}
	u.Disabled, u.MustChangePassword = disabled == 1, mustChange == 1
	u.CreatedAt, u.LastLoginAt = at(created), atp(login)
	return &u, nil
}

// CreateUser inserts a local or OIDC-provisioned user. Usernames are stored
// lowercased so logins are case-insensitive.
func (s *Store) CreateUser(ctx context.Context, u *User) error {
	if u.ID == "" {
		u.ID = NewID(PrefixUser)
	}
	u.Username = strings.ToLower(strings.TrimSpace(u.Username))
	u.CreatedAt = s.Now()
	_, err := s.exec(ctx, `INSERT INTO users (`+userCols+`) VALUES (?,?,?,?,?,?,?,?,?,?,?)`,
		u.ID, u.Username, u.Email, u.DisplayName, string(u.Role), u.PasswordHash,
		u.OIDCSubject, boolInt(u.Disabled), boolInt(u.MustChangePassword),
		ms(u.CreatedAt), msp(u.LastLoginAt))
	return wrapWrite(err)
}

// GetUser returns a user by ID.
func (s *Store) GetUser(ctx context.Context, id string) (*User, error) {
	row := s.read.QueryRowContext(ctx, `SELECT `+userCols+` FROM users WHERE id = ?`, id)
	u, err := scanUser(row)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, fmt.Errorf("user %s: %w", id, ErrNotFound)
	}
	return u, err
}

// GetUserByUsername looks a user up for password login.
func (s *Store) GetUserByUsername(ctx context.Context, username string) (*User, error) {
	row := s.read.QueryRowContext(ctx, `SELECT `+userCols+` FROM users WHERE username = ?`,
		strings.ToLower(strings.TrimSpace(username)))
	u, err := scanUser(row)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, fmt.Errorf("user %q: %w", username, ErrNotFound)
	}
	return u, err
}

// GetUserByOIDCSubject looks a user up during an OIDC callback.
func (s *Store) GetUserByOIDCSubject(ctx context.Context, sub string) (*User, error) {
	row := s.read.QueryRowContext(ctx, `SELECT `+userCols+` FROM users
		WHERE oidc_subject = ? AND oidc_subject != ''`, sub)
	u, err := scanUser(row)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	return u, err
}

// ListUsers returns every account, ordered by username.
func (s *Store) ListUsers(ctx context.Context) ([]*User, error) {
	rows, err := s.read.QueryContext(ctx, `SELECT `+userCols+` FROM users ORDER BY username`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*User
	for rows.Next() {
		u, err := scanUser(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, u)
	}
	return out, rows.Err()
}

// CountUsers returns how many accounts exist. Zero means the instance has not
// been bootstrapped and the API should say so rather than 401 into a void.
func (s *Store) CountUsers(ctx context.Context) (int, error) {
	var n int
	err := s.read.QueryRowContext(ctx, `SELECT COUNT(*) FROM users`).Scan(&n)
	return n, err
}

// CountOutstandingJoinTokens counts join tokens that could still enrol a host:
// unused and unexpired. It is what limits.join_tokens is measured against,
// because a spent or lapsed token holds nothing an attacker could use and the
// row count would refuse an operator for history.
func (s *Store) CountOutstandingJoinTokens(ctx context.Context) (int, error) {
	var n int
	err := s.read.QueryRowContext(ctx,
		`SELECT COUNT(*) FROM join_tokens WHERE used_at IS NULL AND expires_at >= ?`, ms(s.Now())).Scan(&n)
	return n, err
}

// CountAdmins returns how many enabled admins exist, so the API can refuse to
// delete or demote the last one.
func (s *Store) CountAdmins(ctx context.Context) (int, error) {
	var n int
	// Platform counts: it is above administrator, so an instance whose only
	// remaining account holds it is not an instance nobody can administer.
	err := s.read.QueryRowContext(ctx,
		`SELECT COUNT(*) FROM users WHERE role IN ('admin','platform') AND disabled=0`).Scan(&n)
	return n, err
}

// CountPlatform counts the enabled accounts that may operate the process
// itself. An administrator cannot stand in for one, which is why it is
// counted separately from CountAdmins.
func (s *Store) CountPlatform(ctx context.Context) (int, error) {
	var n int
	err := s.read.QueryRowContext(ctx,
		`SELECT COUNT(*) FROM users WHERE role='platform' AND disabled=0`).Scan(&n)
	return n, err
}

// UpdateUser persists profile and role changes.
func (s *Store) UpdateUser(ctx context.Context, u *User) error {
	res, err := s.exec(ctx, `UPDATE users SET username=?, email=?, display_name=?, role=?,
		password_hash=?, oidc_subject=?, disabled=?, must_change_password=?, last_login_at=?
		WHERE id=?`,
		strings.ToLower(strings.TrimSpace(u.Username)), u.Email, u.DisplayName, string(u.Role),
		u.PasswordHash, u.OIDCSubject, boolInt(u.Disabled), boolInt(u.MustChangePassword),
		msp(u.LastLoginAt), u.ID)
	if err != nil {
		return wrapWrite(err)
	}
	return affected(res, "user", u.ID)
}

// SetPassword stores a new argon2id hash and clears the change-on-login flag.
func (s *Store) SetPassword(ctx context.Context, userID, hash string) error {
	res, err := s.exec(ctx,
		`UPDATE users SET password_hash=?, must_change_password=0 WHERE id=?`, hash, userID)
	if err != nil {
		return err
	}
	return affected(res, "user", userID)
}

// TouchLogin records a successful authentication.
func (s *Store) TouchLogin(ctx context.Context, userID string, now time.Time) error {
	_, err := s.exec(ctx, `UPDATE users SET last_login_at=? WHERE id=?`, ms(now), userID)
	return err
}

// DeleteUser removes an account and cascades to its sessions.
func (s *Store) DeleteUser(ctx context.Context, id string) error {
	res, err := s.exec(ctx, `DELETE FROM users WHERE id = ?`, id)
	if err != nil {
		return err
	}
	return affected(res, "user", id)
}

// UserPreferences returns the account's private UI preferences. No row is the
// ordinary state for an account that has never changed a persisted layout.
func (s *Store) UserPreferences(ctx context.Context, userID string) (json.RawMessage, error) {
	var raw string
	err := s.read.QueryRowContext(ctx,
		`SELECT preferences FROM user_preferences WHERE user_id = ?`, userID).Scan(&raw)
	if errors.Is(err, sql.ErrNoRows) {
		return json.RawMessage(`{}`), nil
	}
	if err != nil {
		return nil, err
	}
	if !json.Valid([]byte(raw)) {
		return nil, fmt.Errorf("preferences for user %s are not valid JSON", userID)
	}
	return json.RawMessage(raw), nil
}

// SetUserPreferences replaces the account's private UI preferences. The API
// validates and bounds the document; the store keeps it opaque so UI choices
// do not become domain fields or migrations of their own.
func (s *Store) SetUserPreferences(ctx context.Context, userID string, value json.RawMessage) error {
	_, err := s.exec(ctx, `INSERT INTO user_preferences (user_id, preferences, updated_at)
		VALUES (?, ?, ?) ON CONFLICT(user_id) DO UPDATE SET
		preferences=excluded.preferences, updated_at=excluded.updated_at`,
		userID, string(value), ms(s.Now()))
	return wrapWrite(err)
}

// ---------------------------------------------------------------------------
// Sessions
// ---------------------------------------------------------------------------

// CreateSession stores a browser session keyed on a hashed cookie value.
func (s *Store) CreateSession(ctx context.Context, sess *Session) error {
	if sess.ID == "" {
		sess.ID = NewID(PrefixSession)
	}
	sess.CreatedAt = s.Now()
	_, err := s.exec(ctx, `INSERT INTO sessions (id, user_id, token_hash, user_agent, ip,
		created_at, expires_at, oidc_sid) VALUES (?,?,?,?,?,?,?,?)`,
		sess.ID, sess.UserID, sess.TokenHash, sess.UserAgent, sess.IP,
		ms(sess.CreatedAt), ms(sess.ExpiresAt), sess.OIDCSessionID)
	return wrapWrite(err)
}

// GetSessionByTokenHash resolves a cookie to its session and user in one hop.
func (s *Store) GetSessionByTokenHash(ctx context.Context, hash string) (*Session, *User, error) {
	row := s.read.QueryRowContext(ctx, `SELECT s.id, s.user_id, s.token_hash, s.user_agent,
		s.ip, s.created_at, s.expires_at, `+prefixed(userCols, "u")+`
		FROM sessions s JOIN users u ON u.id = s.user_id WHERE s.token_hash = ?`, hash)

	var sess Session
	var u User
	var created, expires int64
	var disabled, mustChange int
	var uCreated int64
	var login sql.NullInt64
	err := row.Scan(&sess.ID, &sess.UserID, &sess.TokenHash, &sess.UserAgent, &sess.IP,
		&created, &expires,
		&u.ID, &u.Username, &u.Email, &u.DisplayName, &u.Role, &u.PasswordHash,
		&u.OIDCSubject, &disabled, &mustChange, &uCreated, &login)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, nil, ErrNotFound
	}
	if err != nil {
		return nil, nil, err
	}
	sess.CreatedAt, sess.ExpiresAt = at(created), at(expires)
	u.Disabled, u.MustChangePassword = disabled == 1, mustChange == 1
	u.CreatedAt, u.LastLoginAt = at(uCreated), atp(login)
	return &sess, &u, nil
}

// prefixed qualifies a column list with a table alias.
func prefixed(cols, alias string) string {
	parts := strings.Split(cols, ",")
	for i, p := range parts {
		parts[i] = alias + "." + strings.TrimSpace(strings.ReplaceAll(p, "\n\t", ""))
	}
	return strings.Join(parts, ", ")
}

// DeleteSession logs one session out.
func (s *Store) DeleteSession(ctx context.Context, hash string) error {
	_, err := s.exec(ctx, `DELETE FROM sessions WHERE token_hash = ?`, hash)
	return err
}

// DeleteUserSessions logs a user out everywhere, e.g. after a password change.
func (s *Store) DeleteUserSessions(ctx context.Context, userID string) error {
	_, err := s.exec(ctx, `DELETE FROM sessions WHERE user_id = ?`, userID)
	return err
}

// DeleteUserSessionsFromOIDC ends the sessions a user holds that were created
// from one session of the identity provider, and no others: the same person
// signed in from another browser has another provider session, and keeps theirs.
func (s *Store) DeleteUserSessionsFromOIDC(ctx context.Context, userID, oidcSessionID string) error {
	if oidcSessionID == "" {
		return nil
	}
	_, err := s.exec(ctx, `DELETE FROM sessions WHERE user_id = ? AND oidc_sid = ?`, userID, oidcSessionID)
	return err
}

// DeleteUserSessionsExcept logs a user out everywhere but the session whose
// cookie hashes to keep -- the browser that made the change which called for
// it. An empty keep ends them all.
func (s *Store) DeleteUserSessionsExcept(ctx context.Context, userID, keep string) error {
	_, err := s.exec(ctx, `DELETE FROM sessions WHERE user_id = ? AND token_hash != ?`, userID, keep)
	return err
}

// PruneSessions removes expired sessions, and the expired sign-ins that were
// waiting for a second step and never became one.
func (s *Store) PruneSessions(ctx context.Context, now time.Time) (int64, error) {
	res, err := s.exec(ctx, `DELETE FROM sessions WHERE expires_at < ?`, ms(now))
	if err != nil {
		return 0, err
	}
	n, err := res.RowsAffected()
	if err != nil {
		return 0, err
	}
	res, err = s.exec(ctx, `DELETE FROM sign_in_challenges WHERE expires_at < ?`, ms(now))
	if err != nil {
		return n, err
	}
	m, err := res.RowsAffected()
	return n + m, err
}

// ---------------------------------------------------------------------------
// API tokens
// ---------------------------------------------------------------------------

const tokenCols = `id, name, role, owner_role, user_id, scopes, token_hash, prefix, revoked,
	created_at, expires_at, last_used_at`

func scanToken(sc interface{ Scan(...any) error }) (*APIToken, error) {
	var t APIToken
	var revoked int
	var created int64
	var expires, used sql.NullInt64
	err := sc.Scan(&t.ID, &t.Name, &t.Role, &t.OwnerRole, &t.UserID, &t.Scopes, &t.TokenHash, &t.Prefix,
		&revoked, &created, &expires, &used)
	if err != nil {
		return nil, err
	}
	t.Revoked = revoked == 1
	t.CreatedAt = at(created)
	t.ExpiresAt, t.LastUsedAt = atp(expires), atp(used)
	return &t, nil
}

// CreateAPIToken stores a hashed automation credential.
func (s *Store) CreateAPIToken(ctx context.Context, t *APIToken) error {
	if t.ID == "" {
		t.ID = NewID(PrefixToken)
	}
	t.CreatedAt = s.Now()
	_, err := s.exec(ctx, `INSERT INTO api_tokens (`+tokenCols+`) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`,
		t.ID, t.Name, string(t.Role), string(t.OwnerRole), t.UserID, t.Scopes, t.TokenHash, t.Prefix,
		boolInt(t.Revoked), ms(t.CreatedAt), msp(t.ExpiresAt), msp(t.LastUsedAt))
	return wrapWrite(err)
}

// GetAPITokenByHash authenticates a bearer token.
func (s *Store) GetAPITokenByHash(ctx context.Context, hash string) (*APIToken, error) {
	row := s.read.QueryRowContext(ctx, `SELECT `+tokenCols+` FROM api_tokens WHERE token_hash = ?`, hash)
	t, err := scanToken(row)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	return t, err
}

// ListAPITokens returns every token, newest first. Hashes never leave the store.
func (s *Store) ListAPITokens(ctx context.Context) ([]*APIToken, error) {
	rows, err := s.read.QueryContext(ctx, `SELECT `+tokenCols+` FROM api_tokens ORDER BY created_at DESC`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*APIToken
	for rows.Next() {
		t, err := scanToken(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, t)
	}
	return out, rows.Err()
}

// TouchAPIToken records that a token was just used.
func (s *Store) TouchAPIToken(ctx context.Context, id string, now time.Time) error {
	_, err := s.exec(ctx, `UPDATE api_tokens SET last_used_at=? WHERE id=?`, ms(now), id)
	return err
}

// RevokeAPIToken permanently disables a token without losing its audit trail.
func (s *Store) RevokeAPIToken(ctx context.Context, id string) error {
	res, err := s.exec(ctx, `UPDATE api_tokens SET revoked=1 WHERE id=?`, id)
	if err != nil {
		return err
	}
	return affected(res, "api token", id)
}

// DeleteAPIToken removes a token's row for good. It refuses a token that could
// still authenticate -- not revoked and not past its expiry -- with
// ErrConflict. The condition is in the DELETE itself rather than checked first,
// so a live credential can never vanish from the list while it still works:
// deleting is tidying up after a revocation, never a quieter way to do one.
func (s *Store) DeleteAPIToken(ctx context.Context, id string) error {
	res, err := s.exec(ctx, `DELETE FROM api_tokens WHERE id = ?
		AND (revoked = 1 OR (expires_at IS NOT NULL AND expires_at < ?))`, id, ms(s.Now()))
	if err != nil {
		return err
	}
	if n, err := res.RowsAffected(); err != nil {
		return err
	} else if n == 1 {
		return nil
	}
	var exists int
	if err := s.read.QueryRowContext(ctx, `SELECT COUNT(*) FROM api_tokens WHERE id = ?`, id).Scan(&exists); err != nil {
		return err
	}
	if exists == 0 {
		return fmt.Errorf("api token %s: %w", id, ErrNotFound)
	}
	return fmt.Errorf("api token %s is still active; revoke it before deleting it: %w", id, ErrConflict)
}

// RevokeAPITokensForUser revokes every token an account owns, and reports how
// many it revoked.
//
// It is what makes disabling or deleting an account mean something. A session
// dies with the row it points at, but a token is a bearer credential with its
// own role on it: nothing about the account is consulted when one is presented,
// so a departed administrator's token outlived the account it was issued to
// until this was called alongside.
//
// Tokens with no owner -- the empty user_id a token created out of band
// carries -- belong to nobody and are left alone.
func (s *Store) RevokeAPITokensForUser(ctx context.Context, userID string) (int64, error) {
	if userID == "" {
		return 0, nil
	}
	res, err := s.exec(ctx, `UPDATE api_tokens SET revoked=1 WHERE user_id=? AND revoked=0`, userID)
	if err != nil {
		return 0, err
	}
	n, err := res.RowsAffected()
	if err != nil {
		return 0, nil
	}
	return n, nil
}

// ---------------------------------------------------------------------------
// Join tokens
// ---------------------------------------------------------------------------

const joinCols = `id, token_hash, prefix, created_by, labels, capacity, created_at,
	expires_at, used_at, used_by_id, machine_id, expected_name`

func scanJoin(sc interface{ Scan(...any) error }) (*JoinToken, error) {
	var t JoinToken
	var created, expires int64
	var used sql.NullInt64
	err := sc.Scan(&t.ID, &t.TokenHash, &t.Prefix, &t.CreatedBy, &t.Labels, &t.Capacity,
		&created, &expires, &used, &t.UsedByID, &t.MachineID, &t.ExpectedName)
	if err != nil {
		return nil, err
	}
	t.CreatedAt, t.ExpiresAt, t.UsedAt = at(created), at(expires), atp(used)
	return &t, nil
}

// CreateJoinToken mints a short-lived agent enrolment credential.
func (s *Store) CreateJoinToken(ctx context.Context, t *JoinToken) error {
	if t.ID == "" {
		t.ID = NewID(PrefixJoin)
	}
	t.CreatedAt = s.Now()
	_, err := s.exec(ctx, `INSERT INTO join_tokens (`+joinCols+`) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`,
		t.ID, t.TokenHash, t.Prefix, t.CreatedBy, t.Labels, t.Capacity,
		ms(t.CreatedAt), ms(t.ExpiresAt), msp(t.UsedAt), t.UsedByID, t.MachineID, t.ExpectedName)
	return wrapWrite(err)
}

// ListJoinTokens returns outstanding and spent join tokens, newest first.
func (s *Store) ListJoinTokens(ctx context.Context) ([]*JoinToken, error) {
	rows, err := s.read.QueryContext(ctx, `SELECT `+joinCols+` FROM join_tokens ORDER BY created_at DESC LIMIT 200`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*JoinToken
	for rows.Next() {
		t, err := scanJoin(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, t)
	}
	return out, rows.Err()
}

// GetJoinToken returns one join token by ID, spent or not.
//
// It exists for the page that waits for a host to arrive: once the token is
// redeemed, used_by_id is the host the agent became, and that is the only link
// between the credential an operator handed out and the machine that used it.
func (s *Store) GetJoinToken(ctx context.Context, id string) (*JoinToken, error) {
	row := s.read.QueryRowContext(ctx, `SELECT `+joinCols+` FROM join_tokens WHERE id = ?`, id)
	t, err := scanJoin(row)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, fmt.Errorf("join token %s: %w", id, ErrNotFound)
	}
	return t, err
}

// JoinClaim is what the agent redeeming a token says it is: the host row the
// join will land on, and the name it asked for.
//
// The name is carried because it is the only part of the claim a scoped token
// can be checked against. The host id is minted by the controller for this
// join, so it proves nothing about who is joining.
type JoinClaim struct {
	HostID string
	Name   string
}

// RedeemJoinToken atomically marks a join token used and returns it. A second
// attempt with the same token fails, which is what makes it single-use.
//
// It takes the claim rather than a bare host id so that a token minted for one
// machine cannot enrol another, and the scope check runs inside the same
// transaction that spends the token: a credential that lives inside a guest is
// readable by more people than one an operator pastes, and checking the scope
// after the redemption would leave a race in which a copied token spends
// itself first and is refused second.
//
// A token with no scope -- the ones an operator hands out by hand -- is
// unaffected, because the person who pasted it chose the name themselves.
func (s *Store) RedeemJoinToken(ctx context.Context, hash string, claim JoinClaim, now time.Time) (*JoinToken, error) {
	var out *JoinToken
	err := s.tx(ctx, func(tx *sql.Tx) error {
		row := tx.QueryRowContext(ctx, `SELECT `+joinCols+` FROM join_tokens WHERE token_hash = ?`, hash)
		t, err := scanJoin(row)
		if errors.Is(err, sql.ErrNoRows) {
			return ErrNotFound
		}
		if err != nil {
			return err
		}
		if !t.Usable(now) {
			if t.UsedAt != nil {
				return ErrJoinTokenUsed
			}
			return ErrJoinTokenExpired
		}
		if t.ExpectedName != "" && t.ExpectedName != claim.Name {
			return fmt.Errorf("%w: this token was minted for %q and was offered by %q",
				ErrJoinTokenScope, t.ExpectedName, claim.Name)
		}
		if _, err := tx.ExecContext(ctx,
			`UPDATE join_tokens SET used_at=?, used_by_id=? WHERE id=?`,
			ms(now), claim.HostID, t.ID); err != nil {
			return err
		}
		t.UsedAt, t.UsedByID = &now, claim.HostID
		out = t
		return nil
	})
	return out, err
}

// DeleteJoinToken revokes an unused join token.
func (s *Store) DeleteJoinToken(ctx context.Context, id string) error {
	res, err := s.exec(ctx, `DELETE FROM join_tokens WHERE id = ?`, id)
	if err != nil {
		return err
	}
	return affected(res, "join token", id)
}

// PruneJoinTokens removes expired, unused join tokens.
func (s *Store) PruneJoinTokens(ctx context.Context, now time.Time) (int64, error) {
	res, err := s.exec(ctx, `DELETE FROM join_tokens WHERE used_at IS NULL AND expires_at < ?`, ms(now))
	if err != nil {
		return 0, err
	}
	return res.RowsAffected()
}

// ---------------------------------------------------------------------------
// Settings
// ---------------------------------------------------------------------------

// GetSetting returns one setting value, or "" if it is unset.
func (s *Store) GetSetting(ctx context.Context, key string) (string, error) {
	var v string
	err := s.read.QueryRowContext(ctx, `SELECT value FROM settings WHERE key = ?`, key).Scan(&v)
	if errors.Is(err, sql.ErrNoRows) {
		return "", nil
	}
	return v, err
}

// SetSetting upserts one setting.
func (s *Store) SetSetting(ctx context.Context, key, value string, secret bool) error {
	_, err := s.exec(ctx, `INSERT INTO settings (key, value, secret, updated_at) VALUES (?,?,?,?)
		ON CONFLICT(key) DO UPDATE SET value=excluded.value, secret=excluded.secret,
		updated_at=excluded.updated_at`,
		key, value, boolInt(secret), ms(s.Now()))
	return err
}

// ListSettings returns every setting. Values of secret rows are blanked, so
// this is safe to hand to an API handler.
func (s *Store) ListSettings(ctx context.Context) ([]Setting, error) {
	rows, err := s.read.QueryContext(ctx, `SELECT key, value, secret, updated_at FROM settings ORDER BY key`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []Setting
	for rows.Next() {
		var st Setting
		var secret int
		var updated int64
		if err := rows.Scan(&st.Key, &st.Value, &secret, &updated); err != nil {
			return nil, err
		}
		st.Secret, st.UpdatedAt = secret == 1, at(updated)
		if st.Secret {
			st.Value = ""
		}
		out = append(out, st)
	}
	return out, rows.Err()
}

// DeleteSetting removes a setting.
func (s *Store) DeleteSetting(ctx context.Context, key string) error {
	_, err := s.exec(ctx, `DELETE FROM settings WHERE key = ?`, key)
	return err
}

// RevokeUnusedJoinToken serialises revocation with redemption. A token already
// used is retained as enrolment evidence and must never be replaced.
func (s *Store) RevokeUnusedJoinToken(ctx context.Context, id string) error {
	return s.tx(ctx, func(tx *sql.Tx) error {
		t, err := scanJoin(tx.QueryRowContext(ctx, `SELECT `+joinCols+` FROM join_tokens WHERE id=?`, id))
		if errors.Is(err, sql.ErrNoRows) {
			return ErrNotFound
		}
		if err != nil {
			return err
		}
		if t.UsedAt != nil {
			return ErrJoinTokenUsed
		}
		_, err = tx.ExecContext(ctx, `DELETE FROM join_tokens WHERE id=?`, id)
		return err
	})
}

