func TestPruneJoinTokensSparesSpentAndLiveOnes(t *testing.T) {
	ctx := context.Background()
	now := time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC)
	s := newTestStoreAt(t, func() time.Time { return now })

	stale := &JoinToken{TokenHash: "h-stale", ExpiresAt: now.Add(-time.Hour)}
	live := &JoinToken{TokenHash: "h-live", ExpiresAt: now.Add(time.Hour)}
	spent := &JoinToken{TokenHash: "h-spent", ExpiresAt: now.Add(time.Minute)}
	for _, tok := range []*JoinToken{stale, live, spent} {
		if err := s.CreateJoinToken(ctx, tok); err != nil {
			t.Fatalf("CreateJoinToken: %v", err)
		}
	}
	if _, err := s.RedeemJoinToken(ctx, "h-spent", JoinClaim{HostID: "hst_1"}, now); err != nil {
		t.Fatalf("RedeemJoinToken: %v", err)
	}

	// A spent token is expired by the time this runs, but it is the record of
	// which host joined with which credential, so pruning must leave it.
	n, err := s.PruneJoinTokens(ctx, now.Add(2*time.Hour))
	if err != nil {
		t.Fatalf("PruneJoinTokens: %v", err)
	}
	if n != 2 {
		t.Fatalf("PruneJoinTokens removed %d, want 2", n)
	}
	if _, err := s.GetJoinToken(ctx, spent.ID); err != nil {
		t.Fatalf("a spent token was pruned: %v", err)
	}
	if _, err := s.GetJoinToken(ctx, stale.ID); !errors.Is(err, ErrNotFound) {
		t.Fatalf("the stale token survived: %v", err)
	}
}

func TestDeleteJoinTokenRevokesAnUnusedOne(t *testing.T) {
	ctx := context.Background()
	s := newTestStore(t)

	tok := &JoinToken{TokenHash: "h-1", ExpiresAt: s.Now().Add(time.Hour)}
	if err := s.CreateJoinToken(ctx, tok); err != nil {
		t.Fatalf("CreateJoinToken: %v", err)
	}
	if err := s.DeleteJoinToken(ctx, tok.ID); err != nil {
		t.Fatalf("DeleteJoinToken: %v", err)
	}
	if _, err := s.GetJoinToken(ctx, tok.ID); !errors.Is(err, ErrNotFound) {
		t.Fatalf("deleted join token still resolves: %v", err)
	}
	if err := s.DeleteJoinToken(ctx, tok.ID); !errors.Is(err, ErrNotFound) {
		t.Fatalf("DeleteJoinToken on a missing row = %v, want ErrNotFound", err)
	}
}

// The settings list is handed straight to an API handler, so a secret's value
// must not be in it -- the key and the fact that it is set are what an operator
// needs to see.
func TestListSettingsBlanksSecretValues(t *testing.T) {
	ctx := context.Background()
	s := newTestStore(t)

	if err := s.SetSetting(ctx, "ui.theme", "dark", false); err != nil {
		t.Fatalf("SetSetting: %v", err)
	}
	if err := s.SetSetting(ctx, "github.webhook_secret", "hunter2", true); err != nil {
		t.Fatalf("SetSetting: %v", err)
	}

	got, err := s.ListSettings(ctx)
	if err != nil {
		t.Fatalf("ListSettings: %v", err)
	}
	if len(got) != 2 {
		t.Fatalf("ListSettings returned %d rows, want 2", len(got))
	}
	// Ordered by key, so the secret comes first.
	if got[0].Key != "github.webhook_secret" || !got[0].Secret || got[0].Value != "" {
		t.Fatalf("secret row = %+v, want a blanked value", got[0])
	}
	if got[1].Key != "ui.theme" || got[1].Secret || got[1].Value != "dark" {
		t.Fatalf("plain row = %+v", got[1])
	}
	if got[1].UpdatedAt.IsZero() {
		t.Fatal("updated_at was not recorded")
	}

	// The value itself is still readable through the single-key accessor, which
	// is what the controller uses.
	if v, err := s.GetSetting(ctx, "github.webhook_secret"); err != nil || v != "hunter2" {
		t.Fatalf("GetSetting = %q, %v; want hunter2, nil", v, err)
	}
}

func TestSetSettingUpsertsAndDeleteRemoves(t *testing.T) {
	ctx := context.Background()
	s := newTestStore(t)

	if v, err := s.GetSetting(ctx, "absent"); err != nil || v != "" {
		t.Fatalf("GetSetting on an unset key = %q, %v; want \"\", nil", v, err)
	}

	if err := s.SetSetting(ctx, "k", "one", false); err != nil {
		t.Fatalf("SetSetting: %v", err)
	}
	if err := s.SetSetting(ctx, "k", "two", true); err != nil {
		t.Fatalf("SetSetting: %v", err)
	}
	if v, err := s.GetSetting(ctx, "k"); err != nil || v != "two" {
		t.Fatalf("GetSetting = %q, %v; want two, nil", v, err)
	}
	rows, err := s.ListSettings(ctx)
	if err != nil {
		t.Fatalf("ListSettings: %v", err)
	}
	if len(rows) != 1 || !rows[0].Secret {
		t.Fatalf("upsert produced %d rows (%+v), want one secret row", len(rows), rows)
	}

	if err := s.DeleteSetting(ctx, "k"); err != nil {
		t.Fatalf("DeleteSetting: %v", err)
	}
	if v, err := s.GetSetting(ctx, "k"); err != nil || v != "" {
		t.Fatalf("GetSetting after delete = %q, %v", v, err)
	}
}

// Deleting is tidying up after a revocation: a token that still works must
// never vanish from the list, so the store refuses it rather than trusting
// every caller to have checked.
func TestDeleteAPITokenRefusesATokenThatStillWorks(t *testing.T) {
	ctx := context.Background()
	now := time.Unix(1_700_000_000, 0)
	s := newTestStoreAt(t, func() time.Time { return now })
	past := now.Add(-time.Minute)
	future := now.Add(time.Hour)

	cases := []struct {
		name    string
		revoked bool
		expires *time.Time
		want    error
	}{
		{name: "active, never expires", want: ErrConflict},
		{name: "active, expires later", expires: &future, want: ErrConflict},
		{name: "revoked", revoked: true},
		{name: "expired", expires: &past},
	}
	for i, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			tok := &APIToken{Name: tc.name, Role: RoleViewer, TokenHash: fmt.Sprintf("h-%d", i), Revoked: tc.revoked, ExpiresAt: tc.expires}
			if err := s.CreateAPIToken(ctx, tok); err != nil {
				t.Fatalf("CreateAPIToken: %v", err)
			}
			err := s.DeleteAPIToken(ctx, tok.ID)
			if tc.want == nil && err != nil || tc.want != nil && !errors.Is(err, tc.want) {
				t.Fatalf("DeleteAPIToken = %v, want %v", err, tc.want)
			}
		})
	}
}

package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"time"
)

// The offsite destinations an administrator keeps in the database.
//
// They are the same thing `backup.remotes` describes in zoomies.yaml, stored
// where a page can edit them. The file's are still read, and still win a name
// collision: a fleet whose database is gone has only the file, so the file has
// to remain the authority on what it says.
//
// The two secrets are written by their own statement rather than by the update
// that carries the form, for the reason SetProviderCredentials exists: an
// operator pasting a new secret key is not also re-submitting the retention
// from a page they opened yesterday.

// BackupRemote is one S3-compatible destination as the database holds it.
type BackupRemote struct {
	ID string `json:"id"`
	// Name is what every other surface addresses this destination by -- the
	// API route, the log line, the problems drawer -- so it is unique.
	Name string `json:"name"`
	// Endpoint is the service's URL; its scheme decides whether the
	// connection is encrypted. Region is what requests are signed for.
	Endpoint string `json:"endpoint"`
	Region   string `json:"region"`
	// Bucket and Prefix are where the archives land. Zoomies never creates a
	// bucket.
	Bucket string `json:"bucket"`
	Prefix string `json:"prefix"`
	// AccessKeyID is not sealed: it is an identifier, it appears in the
	// service's own access logs, and an operator comparing two destinations
	// needs to see it. The secret beside it is.
	AccessKeyID string `json:"access_key_id"`
	// SecretKeyEnc and PassphraseEnc are sealed with the instance key and
	// never leave this process in plaintext.
	SecretKeyEnc  []byte `json:"-"`
	PassphraseEnc []byte `json:"-"`
	// PathStyle puts the bucket in the path rather than the hostname. Nil
	// chooses from the endpoint, which is the answer that is right without
	// anybody having to know what it means.
	PathStyle *bool `json:"path_style"`
	// Keep is this destination's own retention; 0 keeps every copy.
	Keep int `json:"keep"`
	// Enabled off stops uploads without losing what the bucket holds or what
	// it took to describe it.
	Enabled   bool      `json:"enabled"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

const backupRemoteCols = `id, name, endpoint, region, bucket, prefix, access_key_id,
	secret_key_enc, passphrase_enc, path_style, keep, enabled, created_at, updated_at`

func scanBackupRemote(sc interface{ Scan(...any) error }) (*BackupRemote, error) {
	var r BackupRemote
	var enabled int
	var pathStyle sql.NullInt64
	var created, updated int64
	err := sc.Scan(&r.ID, &r.Name, &r.Endpoint, &r.Region, &r.Bucket, &r.Prefix, &r.AccessKeyID,
		&r.SecretKeyEnc, &r.PassphraseEnc, &pathStyle, &r.Keep, &enabled, &created, &updated)
	if err != nil {
		return nil, err
	}
	r.Enabled = enabled == 1
	if pathStyle.Valid {
		style := pathStyle.Int64 == 1
		r.PathStyle = &style
	}
	r.CreatedAt, r.UpdatedAt = at(created), at(updated)
	return &r, nil
}

// CreateBackupRemote inserts a destination. The secrets are not part of it:
// SetBackupRemoteSecrets writes the sealed bytes, so the one place that has to
// hold the instance key is the one place that holds it.
func (s *Store) CreateBackupRemote(ctx context.Context, r *BackupRemote) error {
	if r.ID == "" {
		r.ID = NewID(PrefixBackupRemote)
	}
	now := s.Now()
	r.CreatedAt, r.UpdatedAt = now, now
	_, err := s.exec(ctx, `INSERT INTO backup_remotes
		(id, name, endpoint, region, bucket, prefix, access_key_id, path_style, keep, enabled, created_at, updated_at)
		VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`,
		r.ID, r.Name, r.Endpoint, r.Region, r.Bucket, r.Prefix, r.AccessKeyID,
		nullableBool(r.PathStyle), r.Keep, boolInt(r.Enabled), ms(now), ms(now))
	return wrapWrite(err)
}

// UpdateBackupRemote persists the form. The secrets are absent on purpose.
func (s *Store) UpdateBackupRemote(ctx context.Context, r *BackupRemote) error {
	now := s.Now()
	r.UpdatedAt = now
	res, err := s.exec(ctx, `UPDATE backup_remotes SET name=?, endpoint=?, region=?, bucket=?,
		prefix=?, access_key_id=?, path_style=?, keep=?, enabled=?, updated_at=? WHERE id=?`,
		r.Name, r.Endpoint, r.Region, r.Bucket, r.Prefix, r.AccessKeyID,
		nullableBool(r.PathStyle), r.Keep, boolInt(r.Enabled), ms(now), r.ID)
	if err != nil {
		return wrapWrite(err)
	}
	return affected(res, "backup remote", r.ID)
}

// SetBackupRemoteSecrets replaces the sealed secret key and passphrase. A nil
// slice clears that secret; leaving one out entirely is the caller's job,
// which is why both are explicit here.
func (s *Store) SetBackupRemoteSecrets(ctx context.Context, id string, secretKey, passphrase []byte) error {
	res, err := s.exec(ctx, `UPDATE backup_remotes SET secret_key_enc=?, passphrase_enc=?, updated_at=?
		WHERE id=?`, secretKey, passphrase, ms(s.Now()), id)
	if err != nil {
		return err
	}
	return affected(res, "backup remote", id)
}

// GetBackupRemote returns one destination by id.
func (s *Store) GetBackupRemote(ctx context.Context, id string) (*BackupRemote, error) {
	row := s.read.QueryRowContext(ctx, `SELECT `+backupRemoteCols+` FROM backup_remotes WHERE id = ?`, id)
	r, err := scanBackupRemote(row)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, fmt.Errorf("backup remote %s: %w", id, ErrNotFound)
	}
	return r, err
}

// GetBackupRemoteByName returns one destination by the name every surface
// addresses it with.
func (s *Store) GetBackupRemoteByName(ctx context.Context, name string) (*BackupRemote, error) {
	row := s.read.QueryRowContext(ctx, `SELECT `+backupRemoteCols+` FROM backup_remotes WHERE name = ?`, name)
	r, err := scanBackupRemote(row)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, fmt.Errorf("backup remote %q: %w", name, ErrNotFound)
	}
	return r, err
}

// ListBackupRemotes returns every destination, by name. Unpaginated for the
// reason ListProviders is: a fleet has a handful of these and every offsite
// pass reads the lot.
func (s *Store) ListBackupRemotes(ctx context.Context) ([]*BackupRemote, error) {
	rows, err := s.read.QueryContext(ctx, `SELECT `+backupRemoteCols+` FROM backup_remotes ORDER BY name`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*BackupRemote
	for rows.Next() {
		r, err := scanBackupRemote(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, r)
	}
	return out, rows.Err()
}

// DeleteBackupRemote removes a destination. What the bucket holds is not
// touched: the copies are somebody's backups, and forgetting where they are is
// not the same as deciding they should not exist.
func (s *Store) DeleteBackupRemote(ctx context.Context, id string) error {
	res, err := s.exec(ctx, `DELETE FROM backup_remotes WHERE id = ?`, id)
	if err != nil {
		return err
	}
	return affected(res, "backup remote", id)
}

// nullableBool renders an unset tri-state for a SQLite INTEGER column.
func nullableBool(b *bool) any {
	if b == nil {
		return nil
	}
	return boolInt(*b)
}

package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
)

func (s *Store) GetCapacityDemandDelivery(ctx context.Context, poolID, eventType string) (*CapacityDemandDelivery, error) {
	var d CapacityDemandDelivery
	var observed int64
	var attempted, delivered sql.NullInt64
	err := s.read.QueryRowContext(ctx, `SELECT pool_id,event_type,event_id,payload,observed_since,attempted_at,delivered_at,status_code,attempts,last_error FROM capacity_demand_deliveries WHERE pool_id=? AND event_type=?`, poolID, eventType).Scan(&d.PoolID, &d.EventType, &d.EventID, &d.Payload, &observed, &attempted, &delivered, &d.StatusCode, &d.Attempts, &d.LastError)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, err
	}
	d.ObservedSince = at(observed)
	if attempted.Valid {
		t := at(attempted.Int64)
		d.AttemptedAt = &t
	}
	if delivered.Valid {
		t := at(delivered.Int64)
		d.DeliveredAt = &t
	}
	return &d, nil
}

func (s *Store) PutCapacityDemandDelivery(ctx context.Context, d *CapacityDemandDelivery) error {
	_, err := s.exec(ctx, `INSERT INTO capacity_demand_deliveries(pool_id,event_type,event_id,payload,observed_since,attempted_at,delivered_at,status_code,attempts,last_error) VALUES(?,?,?,?,?,?,?,?,?,?) ON CONFLICT(pool_id,event_type) DO UPDATE SET event_id=excluded.event_id,payload=excluded.payload,observed_since=excluded.observed_since,attempted_at=excluded.attempted_at,delivered_at=excluded.delivered_at,status_code=excluded.status_code,attempts=excluded.attempts,last_error=excluded.last_error`, d.PoolID, d.EventType, d.EventID, d.Payload, ms(d.ObservedSince), msp(d.AttemptedAt), msp(d.DeliveredAt), d.StatusCode, d.Attempts, d.LastError)
	if err != nil {
		return fmt.Errorf("saving capacity-demand delivery: %w", err)
	}
	return nil
}

func (s *Store) ListCapacityDemandDeliveries(ctx context.Context) ([]*CapacityDemandDelivery, error) {
	rows, err := s.read.QueryContext(ctx, `SELECT pool_id,event_type,event_id,payload,observed_since,attempted_at,delivered_at,status_code,attempts,last_error FROM capacity_demand_deliveries WHERE attempted_at IS NOT NULL ORDER BY attempted_at DESC`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*CapacityDemandDelivery
	for rows.Next() {
		var d CapacityDemandDelivery
		var o int64
		var a, z sql.NullInt64
		if err := rows.Scan(&d.PoolID, &d.EventType, &d.EventID, &d.Payload, &o, &a, &z, &d.StatusCode, &d.Attempts, &d.LastError); err != nil {
			return nil, err
		}
		d.ObservedSince = at(o)
		if a.Valid {
			t := at(a.Int64)
			d.AttemptedAt = &t
		}
		if z.Valid {
			t := at(z.Int64)
			d.DeliveredAt = &t
		}
		out = append(out, &d)
	}
	return out, rows.Err()
}

func (s *Store) DeleteCapacityDemandObservation(ctx context.Context, poolID, eventType string) error {
	_, err := s.exec(ctx, `DELETE FROM capacity_demand_deliveries WHERE pool_id=? AND event_type=? AND attempted_at IS NULL`, poolID, eventType)
	return err
}

package store

import (
	"context"
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"errors"
	"strings"
	"time"
	"unicode/utf8"
)

const ComparisonEvidenceVersion = "observed-comparison-v1"
const MaxComparisonEvidenceBytes = 2 << 20
const MaxComparisonsPerInstallation = 32
const MaxRetainedComparisons = 256
const ComparisonEvidenceRetention = 30 * 24 * time.Hour

var ErrInvalidComparisonEvidence = errors.New("invalid retained comparison evidence")

type ComparisonEvidence struct {
	ID             string          `json:"id"`
	InstallationID string          `json:"installation_id"`
	Repository     string          `json:"repository"`
	InitiatingUser string          `json:"initiating_user"`
	Version        string          `json:"version"`
	SHA256         string          `json:"sha256"`
	Payload        json.RawMessage `json:"payload"`
	CreatedAt      time.Time       `json:"created_at"`
}

// PutComparisonEvidence accepts an already authorised actor. The row and audit
// are one transaction; retries cannot overwrite evidence or renew its lifetime.
func (s *Store) PutComparisonEvidence(ctx context.Context, r *ComparisonEvidence, actor *AuditEvent) error {
	if r == nil || actor == nil || !strings.HasPrefix(r.ID, PrefixComparison+"_") || len(r.ID) > 128 || strings.ContainsAny(r.ID, " /\r\n\x00") || r.InstallationID == "" || len(r.InstallationID) > 128 || r.InitiatingUser == "" || len(r.InitiatingUser) > 128 || actor.ActorID != r.InitiatingUser || strings.TrimSpace(actor.ActorKind) == "" || len(actor.ActorKind) > 64 || len(actor.ActorName) > 200 || len(actor.IP) > 128 || r.Version != ComparisonEvidenceVersion || len(r.Payload) == 0 || len(r.Payload) > MaxComparisonEvidenceBytes || !utf8.Valid(r.Payload) {
		return ErrInvalidComparisonEvidence
	}
	owner, name, ok := strings.Cut(r.Repository, "/")
	if !ok || owner == "" || name == "" || strings.Contains(name, "/") || len(r.Repository) > 1024 {
		return ErrInvalidComparisonEvidence
	}
	var envelope map[string]json.RawMessage
	if json.Unmarshal(r.Payload, &envelope) != nil || envelope == nil {
		return ErrInvalidComparisonEvidence
	}
	var version string
	if json.Unmarshal(envelope["version"], &version) != nil || version != r.Version {
		return ErrInvalidComparisonEvidence
	}
	sum := sha256.Sum256(r.Payload)
	digest := hex.EncodeToString(sum[:])
	now := s.Now().UTC().Truncate(time.Millisecond)
	created := now
	err := s.tx(ctx, func(tx *sql.Tx) error {
		var target, kind string
		if err := tx.QueryRowContext(ctx, `SELECT target,target_type FROM installations WHERE id = ?`, r.InstallationID).Scan(&target, &kind); err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				return ErrInvalidComparisonEvidence
			}
			return err
		}
		if !(kind == string(TargetRepo) && target == r.Repository || kind == string(TargetOrg) && target == owner) {
			return ErrInvalidComparisonEvidence
		}
		var installation, repo, user, oldVersion, oldHash string
		var at int64
		var oldPayload []byte
		err := tx.QueryRowContext(ctx, `SELECT installation_id,repository,initiating_user,version,sha256,created_at,payload FROM comparison_evidence WHERE id = ?`, r.ID).Scan(&installation, &repo, &user, &oldVersion, &oldHash, &at, &oldPayload)
		if err == nil {
			if installation != r.InstallationID || repo != r.Repository || user != r.InitiatingUser || oldVersion != r.Version || oldHash != digest {
				return ErrConflict
			}
			if sha256.Sum256(oldPayload) != sum {
				return ErrInvalidComparisonEvidence
			}
			if at <= ms(now.Add(-ComparisonEvidenceRetention)) {
				return ErrNotFound
			}
			created = time.UnixMilli(at).UTC()
			return nil
		}
		if !errors.Is(err, sql.ErrNoRows) {
			return err
		}
		if _, err := tx.ExecContext(ctx, `INSERT INTO comparison_evidence(id,installation_id,repository,initiating_user,version,sha256,payload,created_at) VALUES(?,?,?,?,?,?,?,?)`, r.ID, r.InstallationID, r.Repository, r.InitiatingUser, r.Version, digest, []byte(r.Payload), ms(now)); err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, `INSERT INTO audit_events (`+auditCols+`) VALUES (?,?,?,?,?,?,?,?,?,?,?)`, NewID(PrefixAudit), actor.ActorID, actor.ActorName, actor.ActorKind, "comparison.evidence_retained", "comparison", r.ID, "", "", actor.IP, ms(now)); err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, `DELETE FROM comparison_evidence WHERE created_at <= ?`, ms(now.Add(-ComparisonEvidenceRetention))); err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, `DELETE FROM comparison_evidence WHERE installation_id = ? AND id NOT IN (SELECT id FROM comparison_evidence WHERE installation_id = ? ORDER BY sequence DESC LIMIT ?)`, r.InstallationID, r.InstallationID, MaxComparisonsPerInstallation); err != nil {
			return err
		}
		_, err = tx.ExecContext(ctx, `DELETE FROM comparison_evidence WHERE id NOT IN (SELECT id FROM comparison_evidence ORDER BY sequence DESC LIMIT ?)`, MaxRetainedComparisons)
		return err
	})
	if err == nil {
		r.SHA256 = digest
		r.CreatedAt = created
	}
	return err
}

// A scoped miss includes expired or evicted evidence. It must not be rendered
// as an empty cohort. The hash detects corruption; it is not an authorisation.
func (s *Store) GetComparisonEvidence(ctx context.Context, installation, repo, id string) (*ComparisonEvidence, error) {
	r := &ComparisonEvidence{}
	var payload []byte
	var created int64
	err := s.read.QueryRowContext(ctx, `SELECT id,installation_id,repository,initiating_user,version,sha256,payload,created_at FROM comparison_evidence WHERE installation_id = ? AND repository = ? AND id = ? AND created_at > ?`, installation, repo, id, ms(s.Now().Add(-ComparisonEvidenceRetention))).Scan(&r.ID, &r.InstallationID, &r.Repository, &r.InitiatingUser, &r.Version, &r.SHA256, &payload, &created)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, err
	}
	sum := sha256.Sum256(payload)
	if len(payload) > MaxComparisonEvidenceBytes || hex.EncodeToString(sum[:]) != r.SHA256 {
		return nil, ErrInvalidComparisonEvidence
	}
	r.Payload = payload
	r.CreatedAt = time.UnixMilli(created).UTC()
	return r, nil
}

package store

import (
	"context"
	"time"
)

// EliRepairUsage is how much of a repository's allowance the last 24 hours have
// spent, and when each of those attempts was made, oldest first, so a caller can
// say when the count will have fallen far enough to let another in.
type EliRepairUsage struct {
	Used  int
	Times []time.Time
}

// FreesAt is the instant the window will hold fewer than limit attempts, which
// is when the attempt that many from the oldest leaves it. With room to spare it
// is the oldest, the first thing to change. A limit lowered below what has been
// spent needs several to leave, and the oldest alone would promise a place that
// is not there.
func (u EliRepairUsage) FreesAt(limit int) time.Time {
	if len(u.Times) == 0 {
		return time.Time{}
	}
	i := min(max(u.Used-limit, 0), len(u.Times)-1)
	return u.Times[i].Add(24 * time.Hour)
}

// EliRepairUsage counts, for every repository with an attempt in the last 24
// hours, the attempts EnqueueEliRepair weighs against the daily limit: by anyone,
// by any trigger, and including a repair cleared from the history, because
// clearing hides a row and never gives its place back. It is the same window and
// the same rows on purpose; an allowance shown to an administrator that differed
// from the one enforced would say a repository has room when the next failure is
// refused.
func (s *Store) EliRepairUsage(ctx context.Context) (map[string]EliRepairUsage, error) {
	rows, err := s.read.QueryContext(ctx, `SELECT repo, created_at FROM eli_repairs WHERE created_at>=? ORDER BY repo, created_at`, ms(s.Now().Add(-24*time.Hour)))
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := map[string]EliRepairUsage{}
	for rows.Next() {
		var repo string
		var created int64
		if err := rows.Scan(&repo, &created); err != nil {
			return nil, err
		}
		u := out[repo]
		u.Used++
		u.Times = append(u.Times, at(created))
		out[repo] = u
	}
	return out, rows.Err()
}

// EliAutomaticLast is the newest automatic repair a repository still shows in
// its history, in the few fields a row of the overview needs.
type EliAutomaticLast struct {
	ID         string    `json:"id"`
	State      string    `json:"state"`
	PullNumber int       `json:"pull_number"`
	UpdatedAt  time.Time `json:"updated_at"`
}

// EliAutomaticActivity is what the automation is doing at one repository now and
// what it last did.
type EliAutomaticActivity struct {
	Running int
	Last    *EliAutomaticLast
}

// EliAutomaticActivity answers for the repositories it is asked about, and only
// those, so the scan for the newest row of each can stop as soon as every one has
// been found. A repository the automation has never touched has no entry, and a
// repair the administrator cleared from the history is not offered back as the
// latest: clearing is how they say they are finished looking at it.
func (s *Store) EliAutomaticActivity(ctx context.Context, repos []string) (map[string]EliAutomaticActivity, error) {
	out := map[string]EliAutomaticActivity{}
	want := make(map[string]bool, len(repos))
	for _, repo := range repos {
		want[repo] = true
	}
	if len(want) == 0 {
		return out, nil
	}

	running, err := s.read.QueryContext(ctx, `SELECT repo, count(*) FROM eli_repairs WHERE trigger='automatic' AND state IN `+eliRepairActive+` GROUP BY repo`)
	if err != nil {
		return nil, err
	}
	defer running.Close()
	for running.Next() {
		var repo string
		var n int
		if err := running.Scan(&repo, &n); err != nil {
			return nil, err
		}
		if want[repo] {
			out[repo] = EliAutomaticActivity{Running: n}
		}
	}
	if err := running.Err(); err != nil {
		return nil, err
	}

	newest, err := s.read.QueryContext(ctx, `SELECT repo, id, state, pull_number, updated_at FROM eli_repairs WHERE trigger='automatic' AND cleared_at IS NULL ORDER BY created_at DESC, id DESC`)
	if err != nil {
		return nil, err
	}
	defer newest.Close()
	found := map[string]bool{}
	for newest.Next() && len(found) < len(want) {
		var repo string
		var last EliAutomaticLast
		var updated int64
		if err := newest.Scan(&repo, &last.ID, &last.State, &last.PullNumber, &updated); err != nil {
			return nil, err
		}
		if !want[repo] || found[repo] {
			continue
		}
		found[repo] = true
		last.UpdatedAt = at(updated)
		activity := out[repo]
		activity.Last = &last
		out[repo] = activity
	}
	return out, newest.Err()
}

