const eliRepairCols = `id,dedup_key,installation_id,repo,pull_number,job_id,run_id,head_sha,commit_sha,user_id,github_user_id,github_login,provider_id,trigger,requester_admin,instruction,state,message,comment_id,published_at,created_at,updated_at,details`

func scanEliRepair(row interface{ Scan(...any) error }) (*EliRepair, error) {
	var v EliRepair
	var created, updated int64
	var published sql.NullInt64
	var details string
	err := row.Scan(&v.ID, &v.DedupKey, &v.InstallationID, &v.Repo, &v.PullNumber, &v.JobID, &v.RunID, &v.HeadSHA, &v.CommitSHA, &v.UserID, &v.GitHubUserID, &v.GitHubLogin, &v.ProviderID, &v.Trigger, &v.RequesterAdmin, &v.Instruction, &v.State, &v.Message, &v.CommentID, &published, &created, &updated, &details)
	if err == nil {
		err = json.Unmarshal([]byte(details), &v.Details)
	}
	v.CreatedAt, v.UpdatedAt = at(created), at(updated)
	v.PublishedAt = atp(published)
	return &v, err
}

// GetEliRepair reads one repair by its id under the rule the history is read by:
// with scoped, only a repair whose owner is ownerID, and an empty owner matches
// nothing (an automatic repair has none). A missing id and one the caller may
// not see are the same ErrNotFound, so the answer cannot be used to find out
// which ids exist. A repair cleared from the history is still returned: clearing
// hides a row from the list and does nothing else.
func (s *Store) GetEliRepair(ctx context.Context, id, ownerID string, scoped bool) (*EliRepair, error) {
	r, err := scanEliRepair(s.read.QueryRowContext(ctx, `SELECT `+eliRepairCols+` FROM eli_repairs WHERE id=?`, id))
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, err
	}
	if scoped && (r.UserID == "" || r.UserID != ownerID) {
		return nil, ErrNotFound
	}
	return r, nil
}

// Admission and deduplication share the writer transaction, so a webhook burst cannot outrun the budget.
func (s *Store) EnqueueEliRepair(ctx context.Context, r *EliRepair, limit int) (bool, error) {
	added := false
	err := s.tx(ctx, func(tx *sql.Tx) error {
		var existing string
		err := tx.QueryRowContext(ctx, `SELECT id FROM eli_repairs WHERE dedup_key=?`, r.DedupKey).Scan(&existing)
		if err == nil {
			saved, err := scanEliRepair(tx.QueryRowContext(ctx, `SELECT `+eliRepairCols+` FROM eli_repairs WHERE id=?`, existing))
			if err != nil {
				return err
			}
			if strings.HasPrefix(r.DedupKey, "offer:") && saved.UserID != r.UserID {
				return ErrConflict
			}
			// A new explicit UI request may retry a finished failure. Webhook delivery
			// keys remain permanent, and an in-flight UI request is still idempotent.
			retry := strings.HasPrefix(r.DedupKey, "ui:") && (saved.State == "failed" || saved.State == "blocked" || saved.State == "interrupted" || saved.State == "unverified" || saved.State == "checks_failed" || saved.State == "superseded")
			if !retry {
				// A person asking again for something already done brings it back into
				// view. Without this a person who cleared the repair would be answered
				// with a history that does not contain what they just asked for. Only a
				// key a person made counts: "ui:" is the page and "offer:" is an offer
				// they accepted. A "comment:" duplicate is the webhook redelivering the
				// same comment (only action "created" is admitted, keyed by comment id),
				// and every later failing job on the same head hits the same
				// "automatic:" key, so neither is anyone asking and neither may undo a
				// clear. They still deduplicate here; the row just stays out of sight.
				//
				// cleared_at has three sites and no others: the history's where clause
				// (reads), ClearEliRepairs (writes) and this un-clear (writes). The
				// budget, the own-commit guard and the deduplication must go on counting
				// a cleared row, so none of them may ever look at the column.
				if strings.HasPrefix(r.DedupKey, "ui:") || strings.HasPrefix(r.DedupKey, "offer:") {
					if _, err := tx.ExecContext(ctx, `UPDATE eli_repairs SET cleared_at=NULL WHERE id=? AND cleared_at IS NOT NULL`, saved.ID); err != nil {
						return err
					}
				}
				*r = *saved
				return nil
			}
			if _, err := tx.ExecContext(ctx, `UPDATE eli_repairs SET dedup_key=? WHERE id=?`, saved.DedupKey+":retry:"+saved.ID, saved.ID); err != nil {
				return err
			}

		}
		if err != nil && !errors.Is(err, sql.ErrNoRows) {
			return err
		}
		var count int
		if err := tx.QueryRowContext(ctx, `SELECT count(*) FROM eli_repairs WHERE repo=? AND created_at>=?`, r.Repo, ms(s.Now().Add(-24*time.Hour))).Scan(&count); err != nil {
			return err
		}
		if limit < 1 || count >= limit {
			return ErrEliRepoBudget
		}
		if r.UserID != "" {
			if err := tx.QueryRowContext(ctx, `SELECT count(*) FROM eli_repairs WHERE user_id=? AND created_at>=?`, r.UserID, ms(s.Now().Add(-24*time.Hour))).Scan(&count); err != nil {
				return err
			}
			if count >= EliPersonDailyLimit {
				return ErrEliPersonBudget
			}
		}
		r.ID = NewID(PrefixEliRepair)
		r.State = "queued"
		r.CreatedAt = s.Now()
		r.UpdatedAt = r.CreatedAt
		_, err = tx.ExecContext(ctx, `INSERT INTO eli_repairs (`+eliRepairCols+`) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`, r.ID, r.DedupKey, r.InstallationID, r.Repo, r.PullNumber, r.JobID, r.RunID, r.HeadSHA, r.CommitSHA, r.UserID, r.GitHubUserID, r.GitHubLogin, r.ProviderID, r.Trigger, boolInt(r.RequesterAdmin), r.Instruction, r.State, r.Message, r.CommentID, msp(r.PublishedAt), ms(r.CreatedAt), ms(r.UpdatedAt), repairDetailsJSON(r.Details))
		added = err == nil
		return err
	})
	return added, wrapWrite(err)
}
func (s *Store) NextEliRepair(ctx context.Context) (*EliRepair, error) {
	r, err := scanEliRepair(s.read.QueryRowContext(ctx, `SELECT `+eliRepairCols+` FROM eli_repairs WHERE state='queued' ORDER BY created_at LIMIT 1`))
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	return r, err
}
func (s *Store) SaveEliRepair(ctx context.Context, r *EliRepair) error {
	r.UpdatedAt = s.Now()
	_, err := s.exec(ctx, `UPDATE eli_repairs SET pull_number=?,head_sha=?,commit_sha=?,user_id=?,provider_id=?,state=?,message=?,comment_id=?,published_at=?,updated_at=?,details=? WHERE id=?`, r.PullNumber, r.HeadSHA, r.CommitSHA, r.UserID, r.ProviderID, r.State, r.Message, r.CommentID, msp(r.PublishedAt), ms(r.UpdatedAt), repairDetailsJSON(r.Details), r.ID)
	return err
}

// An interrupted write has an uncertain outcome. Never automatically repeat it after restart.
func (s *Store) InterruptEliRepairs(ctx context.Context) error {
	_, err := s.exec(ctx, `UPDATE eli_repairs SET state='interrupted',message='The controller restarted during this repair. Check the PR before asking again.',updated_at=? WHERE state='working'`, ms(s.Now()))
	return err
}

// Repair commits remain protected from automatic recursion beyond the history page's limit.
func (s *Store) IsEliRepairCommit(ctx context.Context, repo, sha string) (bool, error) {
	var count int
	err := s.read.QueryRowContext(ctx, `SELECT count(*) FROM eli_repairs WHERE repo=? AND commit_sha=?`, repo, sha).Scan(&count)
	return count > 0, err
}
func (s *Store) CheckingEliRepairs(ctx context.Context) ([]*EliRepair, error) {
	rows, err := s.read.QueryContext(ctx, `SELECT `+eliRepairCols+` FROM eli_repairs WHERE state='checking' ORDER BY created_at`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []*EliRepair{}
	for rows.Next() {
		r, err := scanEliRepair(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, r)
	}
	return out, rows.Err()
}

// Only the owner can approve a verified link. Pinning the numeric ID prevents a stale
// confirmation screen from approving a different account linked in the meantime.
func (s *Store) ConfirmEliIdentity(ctx context.Context, userID string, githubID int64, enabled bool) error {
	result, err := s.exec(ctx, `UPDATE eli_github_identities SET confirmed=?,updated_at=? WHERE user_id=? AND github_user_id=?`, boolInt(enabled), ms(s.Now()), userID, githubID)
	if err != nil {
		return err
	}
	n, err := result.RowsAffected()
	if err == nil && n == 0 {
		return ErrNotFound
	}
	return err
}

func repairDetailsJSON(v EliRepairDetails) string { b, _ := json.Marshal(v); return string(b) }

package store

import (
	"context"
	"database/sql"
	"time"
)

type Enrichment struct {
	Kind, Target string
	Generation   int64
}

var queueEnrichmentQuery = hot(`INSERT INTO control_enrichment(kind,target) VALUES (?,?) ON CONFLICT(kind,target) DO UPDATE SET generation=generation+1`)

func (s *Store) QueueEnrichment(ctx context.Context, kind, target string) error {
	_, err := s.execHot(ctx, queueEnrichmentQuery, kind, target)
	return err
}

// Claim under the writer so concurrent workers cannot fetch the same item.
// A crashed worker's lease expires; generation prevents an old ACK from losing
// an event that arrived during its lookup.
func (s *Store) ClaimEnrichment(ctx context.Context, limit int) (out []Enrichment, err error) {
	err = s.tx(ctx, func(tx *sql.Tx) error {
		rows, e := tx.QueryContext(ctx, `SELECT kind,target,generation FROM control_enrichment WHERE next_attempt<=? ORDER BY next_attempt,kind,target LIMIT ?`, ms(s.Now()), limit)
		if e != nil {
			return e
		}
		for rows.Next() {
			var v Enrichment
			if e = rows.Scan(&v.Kind, &v.Target, &v.Generation); e != nil {
				rows.Close()
				return e
			}
			out = append(out, v)
		}
		e = rows.Err()
		rows.Close()
		if e != nil {
			return e
		}
		for _, v := range out {
			if _, e = tx.ExecContext(ctx, `UPDATE control_enrichment SET next_attempt=? WHERE kind=? AND target=?`, ms(s.Now().Add(time.Minute)), v.Kind, v.Target); e != nil {
				return e
			}
		}
		return nil
	})
	return
}
func (s *Store) FinishEnrichment(ctx context.Context, v Enrichment, success bool) error {
	if !success {
		return nil
	} // the claim's retry deadline provides backoff
	_, err := s.exec(ctx, `DELETE FROM control_enrichment WHERE kind=? AND target=? AND generation=?`, v.Kind, v.Target, v.Generation)
	return err
}

package store

import (
	"context"
	"fmt"
	"strings"
)

const MaxExperimentAttemptJobs = 1000

// ListExperimentAttemptJobs reads retained fleet rows, not GitHub's complete
// workflow. Truncation is explicit so a partial successful subset cannot be
// mistaken for a complete attempt. No outcome is filtered from the cohort.
func (s *Store) ListExperimentAttemptJobs(ctx context.Context, repo, installation string, runID int64, attempt, limit int) ([]*Job, bool, error) {
	if strings.TrimSpace(repo) == "" || strings.TrimSpace(installation) == "" || runID <= 0 || attempt <= 0 || limit < 1 || limit > MaxExperimentAttemptJobs {
		return nil, false, fmt.Errorf("provide repository, installation, positive run/attempt identities and a job limit from 1 to %d", MaxExperimentAttemptJobs)
	}
	rows, err := s.read.QueryContext(ctx, `SELECT `+jobCols+` FROM jobs WHERE repo = ? AND installation_id = ? AND github_run_id = ? AND run_attempt = ? ORDER BY queued_at, id LIMIT ?`, repo, installation, runID, attempt, limit+1)
	if err != nil {
		return nil, false, err
	}
	defer rows.Close()
	out := make([]*Job, 0)
	for rows.Next() {
		j, err := scanJob(rows)
		if err != nil {
			return nil, false, err
		}
		out = append(out, j)
	}
	if err := rows.Err(); err != nil {
		return nil, false, err
	}
	cut := len(out) > limit
	if cut {
		out = out[:limit]
	}
	return out, cut, nil
}

package store

// The queries behind the failure taxonomy: who has been failing, how often, and
// in which category. They are here rather than beside the jobs or the runners
// because they are one subject read from both tables, and an operator asking
// "is it us or is it them" is asking one question.

import (
	"context"
	"database/sql"
	"errors"
	"time"
)

// JobFaultCountsSince counts the fleet's own failures in a window, by category.
//
// It answers the question the taxonomy was added for and the one a single
// job's page cannot: not "why did this job fail" but "what is this fleet doing
// wrong, and how often". Rows written before the category existed count as
// FaultRunnerExited, which is what the migration gave them.
//
// Kinds with no jobs are absent rather than zero. A caller that wants the full
// set iterates FaultKinds; one that wants "what is actually happening" reads
// what is here, and a map of nine zeroes reads as nine problems at a glance.
func (s *Store) JobFaultCountsSince(ctx context.Context, since time.Time, managedOnly bool) (map[FaultKind]int, error) {
	scope := ""
	if managedOnly {
		scope = " AND " + managedJobSQL("jobs")
	}
	rows, err := s.read.QueryContext(ctx, `SELECT fault_kind, COUNT(*) FROM jobs
		WHERE `+fleetFailedJobSQL()+` AND COALESCE(completed_at, queued_at) >= ?`+scope+`
		GROUP BY fault_kind`, ms(since))
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := map[FaultKind]int{}
	for rows.Next() {
		var kind FaultKind
		var n int
		if err := rows.Scan(&kind, &n); err != nil {
			return nil, err
		}
		// A job whose runner died before GitHub closed it has no completion
		// stamp, and it is the case an operator most wants to see, so the
		// window falls back to when it was queued rather than dropping it.
		out[kind.Normalise()] += n
	}
	return out, rows.Err()
}

// RunnerFaultCountsSince counts the runners that failed in a window, by
// category.
//
// This is the half no job ever sees. A runner that fails before it registers
// never reaches a job at all: the job stays queued, waits for the next runner,
// and waits again, so a pool whose containers will not start reads from the
// Jobs page as a pool that is merely slow. The count is per attempt, not per
// runner name -- twenty attempts in an hour is the shape of the problem.
func (s *Store) RunnerFaultCountsSince(ctx context.Context, since time.Time) (map[FaultKind]int, error) {
	rows, err := s.read.QueryContext(ctx, `SELECT fault_kind, COUNT(*) FROM runners
		WHERE state = ? AND COALESCE(finished_at, created_at) >= ?
		GROUP BY fault_kind`, string(RunnerFailed), ms(since))
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := map[FaultKind]int{}
	for rows.Next() {
		var kind FaultKind
		var n int
		if err := rows.Scan(&kind, &n); err != nil {
			return nil, err
		}
		out[kind.Normalise()] += n
	}
	return out, rows.Err()
}

// FailedRunnersForPoolSince lists a pool's recent failed runners, newest
// first, capped at limit.
//
// It exists for the question "why is my job still queued?" on a fleet that is
// trying and failing to answer it: the pool has demand, the scheduler keeps
// placing runners, and every one of them dies before it registers. Nothing the
// job itself carries can say that.
//
// The id breaks a tie on the stamp. Two runners failing inside one millisecond
// is ordinary on a pool that cannot start a container at all, and without it
// the "most recent failure" whose message the problems drawer and the job's
// explanation both quote would be whichever row SQLite happened to reach
// first -- a sentence that changes between two identical reads.
func (s *Store) FailedRunnersForPoolSince(ctx context.Context, poolID string, since time.Time, limit int) ([]*Runner, error) {
	if limit <= 0 {
		limit = 5
	}
	rows, err := s.read.QueryContext(ctx, `SELECT `+runnerCols+` FROM runners
		WHERE pool_id = ? AND state = ? AND COALESCE(finished_at, created_at) >= ?
		ORDER BY COALESCE(finished_at, created_at) DESC, id DESC LIMIT ?`,
		poolID, string(RunnerFailed), ms(since), limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*Runner
	for rows.Next() {
		r, err := scanRunner(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, r)
	}
	return out, rows.Err()
}

// LastJobEventKind returns the kind of a job's most recent timeline entry, or
// empty when it has none.
//
// It is the guard on a repeating entry. A pool whose runners will not start
// tries again every pass, and appending one entry per attempt to every job
// waiting on that pool turns a timeline into a log file -- the thing an
// operator opens the timeline to avoid. One entry per job per run of failures
// says the same thing and stays readable.
func (s *Store) LastJobEventKind(ctx context.Context, jobID string) (JobEventKind, error) {
	var kind JobEventKind
	err := s.read.QueryRowContext(ctx,
		`SELECT kind FROM job_events WHERE job_id = ? ORDER BY at DESC, id DESC LIMIT 1`, jobID).Scan(&kind)
	if errors.Is(err, sql.ErrNoRows) {
		return "", nil
	}
	return kind, err
}

