)

func TestStaleRunningJobsUseTheStartAndKeepOtherStates(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	cutoff := time.Date(2026, 10, 20, 0, 0, 0, 0, time.UTC)
	fallback := cutoff.Add(-30 * 24 * time.Hour)
	old, edge, fresh := cutoff.Add(-time.Second), cutoff, cutoff.Add(time.Second)
	for _, tc := range []struct {
		id     int64
		state  JobState
		queued time.Time
		start  *time.Time
	}{
		{1, JobInProgress, fallback, &old}, {2, JobInProgress, fallback, &edge},
		{3, JobInProgress, fallback, &fresh}, {4, JobQueued, fallback.Add(-time.Second), nil},
		{5, JobCompleted, fallback, &old}, {6, JobInProgress, fallback.Add(-time.Second), nil},
		{7, JobInProgress, fallback, nil}, {8, JobInProgress, fallback.Add(time.Second), nil},
	} {
		if _, _, err := s.ApplyJob(ctx, &Job{GitHubJobID: tc.id, State: tc.state, QueuedAt: tc.queued, StartedAt: tc.start}); err != nil {
			t.Fatal(err)
		}
	}
	got, err := s.ListStaleRunningJobs(ctx, cutoff, fallback)
	if err != nil {
		t.Fatal(err)
	}
	ids := map[int64]bool{}
	for _, j := range got {
		ids[j.GitHubJobID] = true
	}
	if len(got) != 2 || !ids[1] || !ids[6] {
		t.Fatalf("stale jobs = %v, want only old started and old missing-start jobs", ids)
	}
}

// A delivery can finish a job between the sweep's read and its write. The
// presumption must never replace a result GitHub has already confirmed.
func TestAStaleCompletionDoesNotOverwriteAKnownOutcome(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	ended := time.Now().Add(-time.Hour).Truncate(time.Millisecond)
	for i, conclusion := range []string{"success", "failure"} {
		id := int64(i + 20)
		if _, _, err := s.ApplyJob(ctx, &Job{GitHubJobID: id, State: JobCompleted, Conclusion: conclusion, CompletedAt: &ended}); err != nil {
			t.Fatal(err)
		}
		later := ended.Add(time.Hour)
		got, change, err := s.ApplyJob(ctx, &Job{GitHubJobID: id, State: JobCompleted, Conclusion: "stale", CompletedAt: &later}, JobCondition{State: JobInProgress})
		if err != nil {
			t.Fatal(err)
		}
		if change.StateChanged || got.Conclusion != conclusion || got.CompletedAt == nil || !got.CompletedAt.Equal(ended) {
			t.Fatalf("stale sweep replaced %s: %+v (%+v)", conclusion, got, change)
		}
		saved, err := s.GetJobByGitHubID(ctx, id)
		if err != nil || saved.Conclusion != conclusion || !saved.CompletedAt.Equal(ended) {
			t.Fatalf("stored completion = %+v (%v)", saved, err)
		}

		corrected, _, err := s.ApplyJob(ctx, &Job{GitHubJobID: id, State: JobCompleted, Conclusion: "cancelled", CompletedAt: &later})
		if err != nil || corrected.Conclusion != "cancelled" || !corrected.CompletedAt.Equal(later) {
			t.Fatalf("a real completion correction was refused: %+v (%v)", corrected, err)
		}
	}
}

func TestAStaleCompletionDoesNotRetireAJobWhoseStartWasJustLearned(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	if _, _, err := s.ApplyJob(ctx, &Job{GitHubJobID: 31, State: JobCompleted, Conclusion: "stale"}, JobCondition{State: JobInProgress}); !errors.Is(err, ErrConflict) {
		t.Fatalf("a conditioned update recreated a missing row: %v", err)
	}
	now := time.Now()
	if _, _, err := s.ApplyJob(ctx, &Job{GitHubJobID: 30, State: JobInProgress, QueuedAt: now.Add(-36 * 24 * time.Hour)}); err != nil {
		t.Fatal(err)
	}
	// The sweep selected this row with no start; a delivery fills it before
	// the sweep writes. That new evidence must keep the workload protected.
	if _, _, err := s.ApplyJob(ctx, &Job{GitHubJobID: 30, State: JobInProgress, StartedAt: &now}); err != nil {
		t.Fatal(err)
	}
	got, change, err := s.ApplyJob(ctx, &Job{GitHubJobID: 30, State: JobCompleted, Conclusion: "stale", CompletedAt: &now}, JobCondition{State: JobInProgress})
	if err != nil {
		t.Fatal(err)
	}
	if change.StateChanged || got.State != JobInProgress || got.CompletedAt != nil {
		t.Fatalf("newly learned start was ignored: %+v (%+v)", got, change)
	}
}

package store

import (
	"context"
	"testing"
	"time"
)

// The Overview's start-up percentiles used to come from a page of runner rows
// whose limit was silently clamped to 500, so on a fleet that starts more
// runners than that in a day they described the newest few hundred and called
// it the window. The query covers the window, however many runners it holds.
func TestStartupSamplesCoverTheWholeWindow(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	_, pool, host := seedPool(t, s)

	const runners = 505
	for i := 0; i < runners; i++ {
		r := &Runner{PoolID: pool.ID, HostID: host.ID, Name: "r" + itoa(i), State: RunnerIdle}
		if err := s.CreateRunner(ctx, r); err != nil {
			t.Fatalf("CreateRunner: %v", err)
		}
		row, err := s.GetRunner(ctx, r.ID)
		if err != nil {
			t.Fatalf("GetRunner: %v", err)
		}
		started := row.CreatedAt.Add(time.Duration(i+1) * time.Second)
		row.ContainerStartedAt = &started
		if i%2 == 0 {
			// Half registered; the other half never did, and count for the
			// start only.
			registered := started.Add(2 * time.Second)
			row.RegisteredAt = &registered
		}
		if err := s.UpdateRunner(ctx, row); err != nil {
			t.Fatalf("UpdateRunner: %v", err)
		}
	}
	// And one that is still starting, which contributes nothing.
	if err := s.CreateRunner(ctx, &Runner{PoolID: pool.ID, HostID: host.ID, Name: "starting", State: RunnerProvisioning}); err != nil {
		t.Fatalf("CreateRunner: %v", err)
	}

	startup, registration, err := s.StartupSamples(ctx, time.Now().Add(-time.Hour))
	if err != nil {
		t.Fatalf("StartupSamples: %v", err)
	}
	if len(startup) != runners || len(registration) != (runners+1)/2 {
		t.Fatalf("%d start and %d registration samples, want %d and %d", len(startup), len(registration), runners, (runners+1)/2)
	}
	if startup[0] != 1000 || startup[len(startup)-1] != int64(runners)*1000 {
		t.Fatalf("start samples run %d..%d ms, want 1000..%d sorted", startup[0], startup[len(startup)-1], runners*1000)
	}
	for _, r := range registration {
		if r != 2000 {
			t.Fatalf("registration sample %d, want 2000", r)
		}
	}

	if startup, _, err = s.StartupSamples(ctx, time.Now().Add(time.Hour)); err != nil || len(startup) != 0 {
		t.Fatalf("a window that starts in the future sampled %d runners (%v)", len(startup), err)
	}
}

func itoa(i int) string {
	return time.Duration(i).String()[:len(time.Duration(i).String())-2]
}

package store

import (
	"context"
	"database/sql"
	"embed"
	"errors"
	"fmt"
	"io/fs"
	"log/slog"
	"net/url"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	_ "modernc.org/sqlite" // pure-Go driver: no cgo, so the binary stays static
)

// The migrations run in lexical order of their full file name, and the ledger
// that records what has been applied is keyed by that full name too. Two
// things follow, and a test holds both. A shipped file's name is immutable:
// renaming one re-applies its DDL on every existing database, which fails or
// worse. And a new file takes the next unused numeric prefix, alone: two files
// sharing a prefix sort on what follows the underscore, which is a fact about
// spelling and not about the order the schema needs. Pairs which already shipped stay as they are, because of the first rule.
// migrations_test.go records those exceptions and refuses another file in a pair.
//
//go:embed migrations/*.sql
var migrationFS embed.FS

// ErrNotFound is returned by every Get* method when the row does not exist.
var ErrNotFound = errors.New("not found")

// ErrConflict is returned when a uniqueness constraint would be violated.
var ErrConflict = errors.New("already exists")

// ErrEliRepoBudget and ErrEliPersonBudget say which daily limit refused a repair
// request: the repository's, which explicit and automatic attempts share, or the
// one person's. Both are an ErrConflict too, so a caller that only needs to know
// it was refused still matches on that; the two exist so a person who asked for
// a repair can be told which limit they met, instead of being left with silence.
var (
	ErrEliRepoBudget   = fmt.Errorf("this repository has used its repair attempts for the last 24 hours: %w", ErrConflict)
	ErrEliPersonBudget = fmt.Errorf("this person has used their repair attempts for the last 24 hours: %w", ErrConflict)

	// ErrEliIdentityHeld says the GitHub account being linked is already linked
	// to another Zoomies user, a row the old link's owner still holds after an
	// instance move or a re-created account. It is an ErrConflict, so a caller
	// that cares only that the write was refused still matches; it exists so
	// the API can offer moving the link (RelinkEliIdentity) instead of letting
	// the driver's constraint sentence reach the page.
	ErrEliIdentityHeld = fmt.Errorf("this GitHub account is already linked to another Zoomies user: %w", ErrConflict)
)

// EliPersonDailyLimit is how many repairs one person may ask for in a rolling 24
// hours, whatever the repository's own limit allows.
const EliPersonDailyLimit = 10

// ErrInvalidTransition is returned when a runner state change is not legal.
var ErrInvalidTransition = errors.New("invalid state transition")

// ErrSchemaNewer is returned by Open when the database's migration ledger
// names migrations this build does not have.
//
// It is a refusal rather than a warning because the alternative is worse than
// stopping: an older binary against a newer schema reads columns whose meaning
// it does not know and writes rows the newer one will not accept, and it does
// it silently. Rolling a release back is a thing operators do under pressure,
// and this is the moment to tell them the database went forward with it.
var ErrSchemaNewer = errors.New("database is newer than this build of Zoomies")

// ErrReadOnly is returned when a write is attempted on a store opened with
// Options.ReadOnly.
var ErrReadOnly = errors.New("store: this database was opened read-only")

// ErrJoinTokenUsed and ErrJoinTokenExpired are the two ways a join token that
// exists can still be refused. They are sentinels rather than prose so the
// caller can tell a refusal, which is the agent operator's to act on, from a
// failure of the database, which is not.
var (
	ErrJoinTokenUsed    = errors.New("join token has already been used")
	ErrJoinTokenExpired = errors.New("join token has expired")
)

// ErrOwnershipUnverified is a refusal, not a failure: the row and the resource
// disagree about who owns it, and the answer is a person looking rather than a
// retry.
var ErrOwnershipUnverified = errors.New("this machine's ownership could not be verified")

// ErrMachineBusy is a machine whose current step another pass already holds.
// It is a sentinel because the caller's answer is to come back on the next
// pass, which is not what it does with a database failure.
var ErrMachineBusy = errors.New("an operation is already in flight for this machine")

// ErrJoinTokenScope is a token redeemed by something other than the machine it
// was minted for. It is separate from ErrJoinTokenUsed and ErrJoinTokenExpired
// because it is the only one of the three that means somebody copied a
// credential out of a guest.
var ErrJoinTokenScope = errors.New("join token was issued for a different machine")

// walSizeLimit is the size the write-ahead log is truncated back to whenever a
// checkpoint resets it; see the journal_size_limit pragma in Open.
const walSizeLimit = 16 << 20

// Store is the single owner of the SQLite database.
//
// SQLite allows exactly one writer at a time. Rather than hope callers behave,
// writes are funnelled through a mutex and a single connection, while reads use
// a separate pooled connection in WAL mode. This keeps the "database is locked"
// failure mode -- the usual reason small SQLite services fall over -- out of
// the codebase entirely.
type Store struct {
	read  *sql.DB
	write *sql.DB
	wmu   sync.Mutex
	// rstmts and wstmts hold the prepared statements of the hot queries, one set
	// for each pool; see hot.go.
	rstmts, wstmts *stmtCache
	// texts holds the prepared statements of the few queries built from the shape of
	// what they are asked, on the reading pool; see text_stmts.go.
	texts *textStmts
	// writes, when set, is told how long each write waited for wmu and how
	// long it then held it; see ObserveWrites.
	writes atomic.Pointer[WriteObserver]
	path   string
	now    func() time.Time
	// readOnly refuses writes here rather than letting SQLite refuse them,
	// because "attempt to write a readonly database" names the file and not
	// the decision that made it read-only.
	readOnly bool
}

// Options configures Open.
type Options struct {
	// Path is the database file. ":memory:" is accepted for tests.
	Path string
	// Now overrides the clock; tests set this for deterministic timestamps.
	Now func() time.Time
	// ReadOnly opens the file without writing to it and without migrating.
	//
	// Migration is the reason this exists. Opening a database read-write
	// applies every pending migration as a side effect, so a command that only
	// wanted to look -- has this install finished, which runners does GitHub
	// still hold -- upgraded the schema on the way past. That is the wrong
	// moment for it in the ordinary case and the wrong thing entirely when the
	// file is a backup somebody is verifying, which must come back exactly as
	// it was written.
	ReadOnly bool
}

// Open opens (creating if necessary) the database at path and applies all
// pending migrations.
func Open(ctx context.Context, opts Options) (*Store, error) {
	if opts.Path == "" {
		return nil, errors.New("store: database path is required")
	}
	if opts.Now == nil {
		opts.Now = time.Now
	}

	memory := opts.Path == ":memory:" || strings.HasPrefix(opts.Path, "file::memory:")
	if opts.ReadOnly && memory {
		return nil, errors.New("store: a read-only in-memory database has nothing in it to read")
	}
	var dsn string
	if opts.ReadOnly {
		abs, err := filepath.Abs(opts.Path)
		if err != nil {
			return nil, fmt.Errorf("store: resolving %q: %w", opts.Path, err)
		}
		// No journal_mode and no synchronous: both are writes to the file, and
		// setting them is how a "read-only" open silently touches the copy it
		// was asked to leave alone.
		dsn = "file:" + abs + "?" + url.Values{
			"mode":    []string{"ro"},
			"_pragma": []string{"busy_timeout(10000)", "foreign_keys(1)"},
		}.Encode()
	} else if !memory {
		abs, err := filepath.Abs(opts.Path)
		if err != nil {
			return nil, fmt.Errorf("store: resolving %q: %w", opts.Path, err)
		}
		// "Creating if necessary" has to include the directory. SQLite will not
		// make one, and what it reports when the directory is missing or not
		// writable is a bare "unable to open database file (14)" that says
		// nothing about which of the two it was.
		if err := os.MkdirAll(filepath.Dir(abs), 0o750); err != nil {
			return nil, fmt.Errorf("store: creating %s: %w", filepath.Dir(abs), err)
		}
		// _txlock=immediate makes write transactions take the write lock up
		// front, which turns a would-be mid-transaction "database is locked"
		// into a clean, retryable start-of-transaction wait. Both pools share
		// this DSN, so a transaction begun on the read pool takes the write lock
		// too: reads are single statements, and must stay so.
		//
		// journal_size_limit is what gives the write-ahead log's space back. A
		// reader holding an old snapshot stops checkpoints reaching the end of
		// the log, so it grows while the reader lasts -- that is SQLite working
		// as designed -- but without a limit the file then stays at its
		// high-water mark for the life of the process: seventy-five megabytes
		// after one long read, in the test that pins this, on the disk the
		// runners' images and caches share. With the limit, the next checkpoint
		// that resets the log truncates it back. Sixteen megabytes is four times
		// the log a thousand-page automatic checkpoint leaves in steady state.
		dsn = "file:" + abs + "?" + url.Values{
			"_pragma": []string{
				"journal_mode(WAL)",
				"busy_timeout(10000)",
				"foreign_keys(1)",
				"synchronous(NORMAL)",
				"journal_size_limit(" + strconv.Itoa(walSizeLimit) + ")",
			},
			"_txlock": []string{"immediate"},
		}.Encode()
	} else {
		// An in-memory database is per-connection unless it is shared, and the
		// read/write split below needs both handles to see the same data.
		dsn = "file:zoomies-test-" + NewSecret(6) + "?mode=memory&cache=shared&_pragma=foreign_keys(1)"
	}

	write, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, fmt.Errorf("store: opening database: %w", err)
	}
	write.SetMaxOpenConns(1)
	write.SetMaxIdleConns(1)
	write.SetConnMaxLifetime(0)

	read, err := sql.Open("sqlite", dsn)
	if err != nil {
		write.Close()
		return nil, fmt.Errorf("store: opening database for reads: %w", err)
	}
	if memory {
		// A shared in-memory database vanishes when the last connection closes,
		// so keep the reader pool pinned open too.
		read.SetMaxOpenConns(1)
		read.SetMaxIdleConns(1)
		read.SetConnMaxLifetime(0)
	} else {
		read.SetMaxOpenConns(8)
		read.SetMaxIdleConns(4)
	}

	if err := write.PingContext(ctx); err != nil {
		read.Close()
		write.Close()
		switch {
		case opts.ReadOnly:
			// A read-only open is not asking for a writable directory, so the
			// hint below would send the reader to check the wrong thing. What
			// it is usually looking at is a file that is not a database, or is
			// one that has been damaged -- which is precisely the case
			// `zoomies restore` opens a backup to find out about.
			return nil, fmt.Errorf("store: reading %s (is it a Zoomies database, and is it intact?): %w", opts.Path, err)
		case !memory:
			// The overwhelmingly common cause is a directory the running user
			// cannot write to -- a container volume owned by root, say. SQLite
			// will not say so, so say it here.
			return nil, fmt.Errorf("store: connecting to %s (is the directory writable by the user running zoomies?): %w", opts.Path, err)
		}
		return nil, fmt.Errorf("store: connecting to %s: %w", opts.Path, err)
	}

	s := &Store{read: read, write: write, path: opts.Path, now: opts.Now, readOnly: opts.ReadOnly,
		rstmts: newStmtCache(read), wstmts: newStmtCache(write), texts: newTextStmts(read)}
	if opts.ReadOnly {
		// Not migrating is the point, so the ledger check that migrate would
		// have made is made here instead: a caller reading a database from a
		// newer build is reading rows whose meaning it does not know.
		if err := s.checkLedger(ctx); err != nil {
			s.Close()
			return nil, err
		}
		return s, nil
	}
	if memory {
		if restored, err := s.restoreMemoryTemplate(ctx); err != nil {
			s.Close()
			return nil, err
		} else if restored {
			return s, nil
		}
	}
	// Before migrating, not during: migrate holds the write lock and so does
	// Backup, and unlocking around the copy to get past that would be a
	// deadlock waiting for the first caller who does not read the comment.
	if err := s.backupIfMigrationsPending(ctx); err != nil {
		s.Close()
		return nil, err
	}
	if err := s.migrate(ctx); err != nil {
		s.Close()
		return nil, err
	}
	if memory {
		s.captureMemoryTemplate(ctx)
	}
	return s, nil
}

// Close releases both connection pools.
func (s *Store) Close() error {
	var errs []error
	s.rstmts.close()
	s.wstmts.close()
	s.texts.close()
	if s.read != nil {
		errs = append(errs, s.read.Close())
	}
	if s.write != nil {
		errs = append(errs, s.write.Close())
	}
	return errors.Join(errs...)
}

// Path returns the database file this store was opened from.
func (s *Store) Path() string { return s.path }

// Now returns the store's clock. Everything that stamps a timestamp uses this
// so tests can freeze time.
func (s *Store) Now() time.Time { return s.now().UTC() }

// ---------------------------------------------------------------------------
// Migrations
// ---------------------------------------------------------------------------

type migration struct {
	name string
	sql  string
}

func loadMigrations() ([]migration, error) {
	entries, err := fs.ReadDir(migrationFS, "migrations")
	if err != nil {
		return nil, err
	}
	var out []migration
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".sql") {
			continue
		}
		b, err := migrationFS.ReadFile("migrations/" + e.Name())
		if err != nil {
			return nil, err
		}
		out = append(out, migration{name: e.Name(), sql: string(b)})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].name < out[j].name })
	return out, nil
}

// checkLedger refuses a database written by a newer build.
//
// A missing ledger table is not a newer database, it is an empty one, so it
// passes: Open creates the table a moment later.
func (s *Store) checkLedger(ctx context.Context) error {
	rows, err := s.read.QueryContext(ctx, `SELECT name FROM schema_migrations ORDER BY name`)
	if err != nil {
		// The table does not exist yet on a database this build is about to
		// create, and a real failure to read it will be reported by the next
		// query rather than swallowed: nothing here depends on having read it.
		return nil
	}
	defer rows.Close()
	var applied []string
	for rows.Next() {
		var n string
		if err := rows.Scan(&n); err != nil {
			return fmt.Errorf("store: reading migration ledger: %w", err)
		}
		applied = append(applied, n)
	}
	if err := rows.Err(); err != nil {
		return fmt.Errorf("store: reading migration ledger: %w", err)
	}
	return unknownMigrations(applied)
}

// unknownMigrations names the applied migrations this build does not embed.
func unknownMigrations(applied []string) error {
	migs, err := loadMigrations()
	if err != nil {
		return fmt.Errorf("store: loading embedded migrations: %w", err)
	}
	known := make(map[string]bool, len(migs))
	for _, m := range migs {
		known[m.name] = true
	}
	var unknown []string
	for _, name := range applied {
		if !known[name] {
			unknown = append(unknown, name)
		}
	}
	if len(unknown) == 0 {
		return nil
	}
	return fmt.Errorf("store: %w: its ledger names %s, which this build does not have; "+
		"run the release that wrote it, or restore a backup taken with this one",
		ErrSchemaNewer, strings.Join(unknown, ", "))
}

// backupIfMigrationsPending copies the database before any migration touches
// it, when there is both something pending and something to lose.
//
// Migrations are one-way and the binary that wrote this database will refuse
// to open it afterwards, so this is the one moment a rollback is most likely
// to be wanted and least likely to have been prepared for: an operator
// upgrading is not thinking about backups. It costs a file copy once per
// release.
//
// A database being created has no ledger to read, which is how "nothing to
// lose" is recognised: a fresh install gets no empty copy beside it.
func (s *Store) backupIfMigrationsPending(ctx context.Context) error {
	if s.readOnly || s.path == "" {
		return nil
	}
	rows, err := s.read.QueryContext(ctx, `SELECT name FROM schema_migrations`)
	if err != nil {
		// No ledger: this database is being created.
		return nil
	}
	applied := map[string]bool{}
	for rows.Next() {
		var n string
		if err := rows.Scan(&n); err != nil {
			rows.Close()
			return fmt.Errorf("store: reading migration ledger: %w", err)
		}
		applied[n] = true
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return fmt.Errorf("store: reading migration ledger: %w", err)
	}
	if len(applied) == 0 {
		return nil
	}

	migs, err := loadMigrations()
	if err != nil {
		return fmt.Errorf("store: loading embedded migrations: %w", err)
	}
	var pending []string
	for _, m := range migs {
		if !applied[m.name] {
			pending = append(pending, m.name)
		}
	}
	dest, err := s.backupBeforeMigrate(ctx, pending)
	if err != nil {
		return fmt.Errorf("store: copying the database before migrating it: %w "+
			"(the upgrade has not started; free space beside the database, or move the old copies out of the way)", err)
	}
	if dest != "" {
		slog.Info("copied the database before migrating it",
			"copy", dest, "migrations", len(pending),
			"detail", "migrations are one-way; this is what an older release could be restored onto")
	}
	return nil
}

func (s *Store) migrate(ctx context.Context) error {
	defer s.lockWriter()()

	if _, err := s.write.ExecContext(ctx, `CREATE TABLE IF NOT EXISTS schema_migrations (
		name       TEXT PRIMARY KEY,
		applied_at INTEGER NOT NULL
	)`); err != nil {
		return fmt.Errorf("store: creating migration ledger: %w", err)
	}

	applied := map[string]bool{}
	rows, err := s.write.QueryContext(ctx, `SELECT name FROM schema_migrations`)
	if err != nil {
		return fmt.Errorf("store: reading migration ledger: %w", err)
	}
	for rows.Next() {
		var n string
		if err := rows.Scan(&n); err != nil {
			rows.Close()
			return err
		}
		applied[n] = true
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return err
	}
	// Before applying anything: a database that has been further than this
	// build can go is not one to migrate forward.
	names := make([]string, 0, len(applied))
	for n := range applied {
		names = append(names, n)
	}
	sort.Strings(names)
	if err := unknownMigrations(names); err != nil {
		return err
	}

	migs, err := loadMigrations()
	if err != nil {
		return fmt.Errorf("store: loading embedded migrations: %w", err)
	}

	return s.applyMigrations(ctx, migs, applied)
}

// applyMigrations runs the ones not already in the ledger, each in its own
// transaction.
//
// It is separate from migrate so a test can hand it a migration that fails:
// what happens then is the behaviour that matters, and it cannot be exercised
// through the embedded set, every member of which works. The rule it holds is
// that a failure stops startup and leaves the ledger clean, so the same
// migration is tried again on the next start rather than being skipped as
// though it had worked.
func (s *Store) applyMigrations(ctx context.Context, migs []migration, applied map[string]bool) error {
	for _, m := range migs {
		if applied[m.name] {
			continue
		}
		tx, err := s.write.BeginTx(ctx, nil)
		if err != nil {
			return fmt.Errorf("store: begin migration %s: %w", m.name, err)
		}
		if _, err := tx.ExecContext(ctx, m.sql); err != nil {
			tx.Rollback()
			return fmt.Errorf("store: applying migration %s: %w", m.name, err)
		}
		if _, err := tx.ExecContext(ctx,
			`INSERT INTO schema_migrations (name, applied_at) VALUES (?, ?)`,
			m.name, ms(s.Now())); err != nil {
			tx.Rollback()
			return fmt.Errorf("store: recording migration %s: %w", m.name, err)
		}
		if err := tx.Commit(); err != nil {
			return fmt.Errorf("store: committing migration %s: %w", m.name, err)
		}
		slog.Info("applied database migration", "migration", m.name)
	}
	return nil
}

// ---------------------------------------------------------------------------
// Small helpers shared by every query file
// ---------------------------------------------------------------------------

// exec runs a write statement under the single-writer lock.
// AppliedMigration is one row of the ledger: which migration, and when this
// database took it.
type AppliedMigration struct {
	Name      string    `json:"name"`
	AppliedAt time.Time `json:"applied_at"`
}

// AppliedMigrations lists the ledger in the order the migrations apply, which
// is the lexical order of their file names. It is what a readiness probe, a
// bug report or a backup manifest means by "schema version": there is no
// number, only the names, and the last one is the one that matters.
func (s *Store) AppliedMigrations(ctx context.Context) ([]AppliedMigration, error) {
	rows, err := s.read.QueryContext(ctx, `SELECT name, applied_at FROM schema_migrations ORDER BY name`)
	if err != nil {
		return nil, fmt.Errorf("store: reading migration ledger: %w", err)
	}
	defer rows.Close()
	var out []AppliedMigration
	for rows.Next() {
		var m AppliedMigration
		var applied int64
		if err := rows.Scan(&m.Name, &applied); err != nil {
			return nil, fmt.Errorf("store: reading migration ledger: %w", err)
		}
		m.AppliedAt = at(applied)
		out = append(out, m)
	}
	return out, rows.Err()
}

// WriteObserver is told, for every write, how long it waited for the single
// writer and how long it then held it.
type WriteObserver func(waited, held time.Duration)

// ObserveWrites reports every write's wait and hold to fn.
//
// One writer is the design: it is what keeps "database is locked" out of the
// codebase. It is also the one place every heartbeat, webhook, scheduling pass
// and API call queues, so it is where a busy instance slows down first -- and
// until this, nothing said how long the queue was. A heartbeat that took four
// seconds and a webhook GitHub gave up on after ten looked like a slow host
// and a lost delivery, not like writes waiting their turn.
//
// fn runs after the writer is released, so an observer that is slow to record
// cannot lengthen the hold it is measuring.
func (s *Store) ObserveWrites(fn WriteObserver) {
	if fn == nil {
		s.writes.Store(nil)
		return
	}
	s.writes.Store(&fn)
}

// lockWriter takes the single writer and returns what releases it, timing
// both halves for ObserveWrites. Every write goes through here, so a lock
// taken anywhere else is a write the measurement cannot see.
func (s *Store) lockWriter() (release func()) {
	asked := time.Now()
	s.wmu.Lock()
	got := time.Now()
	return func() {
		s.wmu.Unlock()
		if fn := s.writes.Load(); fn != nil {
			(*fn)(got.Sub(asked), time.Since(got))
		}
	}
}

func (s *Store) exec(ctx context.Context, query string, args ...any) (sql.Result, error) {
	if s.readOnly {
		return nil, ErrReadOnly
	}
	defer s.lockWriter()()
	return s.write.ExecContext(ctx, query, args...)
}

// tx runs fn inside a write transaction under the single-writer lock.
func (s *Store) tx(ctx context.Context, fn func(*sql.Tx) error) error {
	if s.readOnly {
		return ErrReadOnly
	}
	defer s.lockWriter()()
	s.wstmts.prepareWanted(ctx)
	t, err := s.write.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	if err := fn(t); err != nil {
		t.Rollback()
		return err
	}
	return t.Commit()
}

// ms converts a time to the Unix-millisecond integers the schema stores.
func ms(t time.Time) int64 { return t.UTC().UnixMilli() }

// msp converts an optional time.
func msp(t *time.Time) any {
	if t == nil {
		return nil
	}
	return t.UTC().UnixMilli()
}

// at converts stored milliseconds back to a time.
func at(v int64) time.Time { return time.UnixMilli(v).UTC() }

// atp converts an optional stored timestamp.
func atp(v sql.NullInt64) *time.Time {
	if !v.Valid || v.Int64 == 0 {
		return nil
	}
	t := time.UnixMilli(v.Int64).UTC()
	return &t
}

// isUnique reports whether err is a SQLite uniqueness violation.
func isUnique(err error) bool {
	if err == nil {
		return false
	}
	msg := err.Error()
	return strings.Contains(msg, "UNIQUE constraint failed") ||
		strings.Contains(msg, "constraint failed: UNIQUE")
}

// wrapWrite converts driver-level constraint errors into the package's sentinels.
func wrapWrite(err error) error {
	if isUnique(err) {
		return fmt.Errorf("%w: %v", ErrConflict, err)
	}
	return err
}

// boolInt renders a bool for a SQLite INTEGER column.
func boolInt(b bool) int {
	if b {
		return 1
	}
	return 0
}

// KnownMigrations names every migration this build carries, in the order they
// apply. It is what lets a backup's manifest be compared with this binary
// without opening the backup: a ledger naming a migration not in this list was
// written by a newer release, and Open would refuse it.
func KnownMigrations() []string {
	migs, err := loadMigrations()
	if err != nil {
		return nil
	}
	out := make([]string, 0, len(migs))
	for _, m := range migs {
		out = append(out, m.name)
	}
	return out
}

package store

import (
	"context"
	"database/sql"
	"sync"
	"sync/atomic"
)

// The driver parses every statement it is given, every time it is given it (see
// hot.go), and a hot query is the answer for a statement that is a constant. The
// job statistics are not: they are built from the shape of what they are asked, the
// group-by keys and which fields of the filter are set, so there is no one text to
// register. There are few of them, though. The dashboard asks for the same handful
// every pass, each a statement as large as a page of SQL, and they were the
// largest fixed cost of a pass that someone was watching.
//
// textStmts keeps the first maxTextStmts distinct texts it is handed prepared, on
// the reading pool, and runs them from the preparation; a text past that runs as
// it always did. It is a fixed number and never evicts, because a statement taken
// out from under a query another goroutine is about to run is an error, and
// because what could outgrow the cap, a filter by a list of ids, is a new text for
// each length of the list and changes only when the fleet does.
type textStmts struct {
	db *sql.DB

	mu    sync.RWMutex
	stmts map[string]*sql.Stmt
	// hits and misses count the queries run from a prepared statement and
	// without one, for the tests.
	hits, misses atomic.Int64
}

// maxTextStmts is how many texts are kept prepared. A statement is prepared again by
// database/sql on each of the pool's connections as it is first used there, and the
// pool has eight, so this bounds what is held to sixty-four programs on each.
const maxTextStmts = 64

func newTextStmts(db *sql.DB) *textStmts {
	return &textStmts{db: db, stmts: make(map[string]*sql.Stmt)}
}

// query is QueryContext of a text, from its preparation if it has one or can be
// given one, and as the text if it cannot, in which case it fails again, with the
// error that says what is wrong, wherever it is run.
func (c *textStmts) query(ctx context.Context, text string, args ...any) (*sql.Rows, error) {
	if st := c.prepared(ctx, text); st != nil {
		return st.QueryContext(ctx, args...)
	}
	return c.db.QueryContext(ctx, text, args...)
}

func (c *textStmts) prepared(ctx context.Context, text string) *sql.Stmt {
	c.mu.RLock()
	st, full := c.stmts[text], len(c.stmts) >= maxTextStmts
	c.mu.RUnlock()
	if st != nil {
		c.hits.Add(1)
		return st
	}
	c.misses.Add(1)
	if full {
		return nil
	}
	prepared, err := c.db.PrepareContext(ctx, text)
	if err != nil {
		return nil
	}
	return c.keep(text, prepared)
}

// keep records a statement that has just been prepared, unless another goroutine
// prepared the same text while this one did, in which case that one is kept and
// this one let go, or the cap was reached in the meantime, in which case neither is
// and the text runs as text.
func (c *textStmts) keep(text string, prepared *sql.Stmt) *sql.Stmt {
	c.mu.Lock()
	defer c.mu.Unlock()
	if kept := c.stmts[text]; kept != nil {
		prepared.Close()
		return kept
	}
	if len(c.stmts) >= maxTextStmts {
		prepared.Close()
		return nil
	}
	c.stmts[text] = prepared
	return prepared
}

// close releases every statement kept. It is called before the pool is closed.
func (c *textStmts) close() {
	if c == nil {
		return
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	for text, st := range c.stmts {
		st.Close()
		delete(c.stmts, text)
	}
}

package store

import (
	"context"
	"database/sql"
	"fmt"
	"path/filepath"
	"reflect"
	"sync"
	"testing"
	"time"
)

// The job statistics are built from the shape of what they are asked, so they
// are not hot queries, and the few that the dashboard asks for every pass are kept
// prepared instead (text_stmts.go). These hold that to what it promises: a text is
// parsed once, what it answers does not change, the number kept is bounded, and a
// statement that cannot be prepared fails as it always did.

// One store serves the first three, because opening a store runs every migration
// and that is most of what a test of this size costs.
func TestTheTextsTheStoreKeepsPrepared(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()

	t.Run("the job statistics are parsed once and answer as they did", func(t *testing.T) {
		completedJobs(t, s, 12)
		since := time.Now().Add(-24 * time.Hour)
		f := JobFilter{Since: &since}

		first, err := s.JobStats(ctx, f, []string{GroupByPool})
		if err != nil {
			t.Fatalf("JobStats: %v", err)
		}
		total := 0
		for _, g := range first.Groups {
			total += g.Count
		}
		if total != 12 || len(first.Groups) != 4 {
			t.Fatalf("the statistics counted %d jobs in %d pools; want the 12 in 4 that were put there", total, len(first.Groups))
		}

		hits, misses := s.texts.hits.Load(), s.texts.misses.Load()
		second, err := s.JobStats(ctx, f, []string{GroupByPool})
		if err != nil {
			t.Fatalf("JobStats: %v", err)
		}
		if !reflect.DeepEqual(first, second) {
			t.Errorf("the statistics changed between the first run, which prepared its statements, and the second, which used them")
		}
		// Counts, fleet-failure kinds, peaks and three percentiles: six statements.
		if ran, parsed := s.texts.hits.Load()-hits, s.texts.misses.Load()-misses; ran != 6 || parsed != 0 {
			t.Errorf("the second run took %d of its statements from a preparation and parsed %d; want all 6 and none", ran, parsed)
		}
		if len(s.texts.stmts) != 6 {
			t.Errorf("%d statements were kept; want the 6 that were run", len(s.texts.stmts))
		}
	})

	t.Run("only the first few texts are kept", func(t *testing.T) {
		before := len(s.texts.stmts)
		ask := func(i int) {
			t.Helper()
			rows, err := s.texts.query(ctx, fmt.Sprintf("SELECT ?1 + %d", i), 1000)
			if err != nil {
				t.Fatalf("query %d: %v", i, err)
			}
			defer rows.Close()
			var got int
			if !rows.Next() || rows.Scan(&got) != nil || got != 1000+i {
				t.Fatalf("query %d answered %d; want %d", i, got, 1000+i)
			}
		}
		for i := range maxTextStmts + 10 {
			ask(i)
		}
		if len(s.texts.stmts) != maxTextStmts {
			t.Errorf("%d texts were kept after %d more were asked for on top of %d; want the first %d and no more", len(s.texts.stmts), maxTextStmts+10, before, maxTextStmts)
		}
		// The cap is full, so what is kept is what was kept first: the statistics.
		hits := s.texts.hits.Load()
		ask(maxTextStmts + 5)
		if s.texts.hits.Load() != hits {
			t.Errorf("a text past the cap ran from a preparation")
		}
	})

	// Two goroutines can each find room for a text, prepare it and come to keep it
	// when there is room for one of them.
	t.Run("a text prepared as the cap is reached, or twice, is kept once", func(t *testing.T) {
		texts := newTextStmts(s.read)
		prepare := func(text string) *sql.Stmt {
			t.Helper()
			st, err := s.read.PrepareContext(ctx, text)
			if err != nil {
				t.Fatalf("PrepareContext(%q): %v", text, err)
			}
			return st
		}
		for i := range maxTextStmts - 1 {
			if texts.keep(fmt.Sprintf("SELECT %d", i), prepare(fmt.Sprintf("SELECT %d", i))) == nil {
				t.Fatalf("text %d was not kept with room to spare", i)
			}
		}
		last, late := prepare("SELECT 1001"), prepare("SELECT 1002")
		if texts.keep("SELECT 1001", last) != last {
			t.Fatal("the text that filled the last place was not kept")
		}
		if texts.keep("SELECT 1002", late) != nil || len(texts.stmts) != maxTextStmts {
			t.Errorf("a text prepared as the cap was reached was kept: %d texts held, want %d", len(texts.stmts), maxTextStmts)
		}
		if again := texts.keep("SELECT 1001", prepare("SELECT 1001")); again != last || len(texts.stmts) != maxTextStmts {
			t.Errorf("a text prepared twice was kept twice")
		}
	})

	t.Run("a text that cannot be prepared fails as it did without the cache", func(t *testing.T) {
		const bad = `SELECT nothing FROM a_table_that_does_not_exist WHERE x = ?`
		_, want := s.read.QueryContext(ctx, bad, 1)
		rows, got := s.texts.query(ctx, bad, 1)
		if rows != nil {
			rows.Close()
		}
		if want == nil || got == nil || want.Error() != got.Error() {
			t.Errorf("the text failed with %v and its kept form with %v; want the same error", want, got)
		}
	})
}

// A file-backed store has a pool of connections, and a prepared statement is
// prepared again on each as it first runs there; asking from several goroutines at
// once makes it use more than one. Closing the store then lets go of what it kept.
func TestTheStatisticsAskedForAtOnceAreKeptOnceEachAndLetGoOfOnClose(t *testing.T) {
	ctx := context.Background()
	s, err := Open(ctx, Options{Path: filepath.Join(t.TempDir(), "zoomies.db")})
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	t.Cleanup(func() { s.Close() })
	completedJobs(t, s, 8)
	since := time.Now().Add(-24 * time.Hour)

	var wg sync.WaitGroup
	errs := make(chan error, 8)
	for range 8 {
		wg.Go(func() {
			for range 3 {
				if _, err := s.JobStats(ctx, JobFilter{Since: &since}, []string{GroupByPool}); err != nil {
					errs <- err
					return
				}
			}
		})
	}
	wg.Wait()
	close(errs)
	for err := range errs {
		t.Fatalf("JobStats: %v", err)
	}
	if len(s.texts.stmts) != 6 {
		t.Errorf("%d texts were kept after one shape of statistics was asked for 24 times at once; want 6", len(s.texts.stmts))
	}

	if err := s.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}
	if len(s.texts.stmts) != 0 {
		t.Errorf("%d statements were still kept after the store was closed", len(s.texts.stmts))
	}
}

package store

import (
	"database/sql/driver"
	"encoding/json"
	"fmt"
	"sort"
)

// A pool's RAM-backed scratch space. A runner's work folder and /tmp normally
// live on its container's writable layer, which is on the host's Docker data
// root; on a host with slow disks and spare memory that layer is where every
// checkout, install and build waits. Mounting a tmpfs over them moves that
// traffic into RAM.
//
// It is opt-in, and the reason is the trade it makes: tmpfs pages are charged
// to the runner's own memory cgroup, so the size below is room taken out of the
// pool's memory limit, not added to it. A pool that turns this on without
// raising its limit has a job that can run out of memory sooner, which is why
// the controller proposes the raise (ReserveMB) rather than making it quietly.

const (
	// DefaultTmpfsWorkMB and DefaultTmpfsTmpMB are what an enabled mount with no
	// size of its own is given when the runner has no memory limit to fit them to.
	//
	// /tmp is given as much as the work folder because it holds the same kind of
	// thing: a compiler keeps a whole cold build there until the command exits.
	// Go compiles every package into its work directory under /tmp and leaves
	// them there, with the linker's output on top, until the build is done; a
	// cold cross-compile of this repository is 962 MB of that. It used to ask for
	// 1 GB, and the darwin/amd64 link of main died on the fleet in it with
	// "mapping output file failed: no space left on device", on the fleet's
	// biggest runners, while the small ones, whose /tmp was on disk, passed.
	DefaultTmpfsWorkMB int64 = 4096
	DefaultTmpfsTmpMB  int64 = 4096
	// DefaultTmpfsDaemonMB is the same for the docker-in-docker sidecar's image
	// store. It is larger because what lives there -- every image a job pulls and
	// every layer it builds -- is larger than a checkout, and a pull that does not
	// fit fails the job rather than slowing it.
	DefaultTmpfsDaemonMB int64 = 8192
	// AutoMinWorkMB, AutoMinTmpMB and AutoMinDaemonMB are the least an automatic
	// folder is worth. An auto folder that would be fitted below its floor is kept
	// on disk instead: a checkout, a build's temporary files or an image pull
	// that does not fit fails with "no space left on device", which names neither
	// the mount nor the setting, and a folder that small saves little disk traffic
	// anyway. A size an operator typed lowers the floor to itself, because they
	// asked for exactly that much. The floor for /tmp clears a cold Go build of
	// this repository twice (DefaultTmpfsTmpMB says why that is the measure); a
	// 1 GB /tmp did not clear it once.
	AutoMinWorkMB   int64 = 2048
	AutoMinTmpMB    int64 = 2048
	AutoMinDaemonMB int64 = 4096
	// MinTmpfsMB is the least a tmpfs may be. Below it a checkout fails in a way
	// that reads as a broken runner rather than a small mount.
	MinTmpfsMB int64 = 64
)

// TmpfsMount is one RAM-backed folder.
type TmpfsMount struct {
	Enabled bool `json:"enabled"`
	// SizeMB is the mount's ceiling. Zero lets the runner's memory limit pick it
	// (TmpfsConfig.Sizes), which is what a pool that has not thought about it
	// wants: a size that fits whatever machine share the runner was given.
	SizeMB int64 `json:"size_mb,omitempty"`
	// Auto lets each runner decide: the folder is in memory where the runner has
	// room for it to be useful (see the AutoMin* floors) and on disk where it has
	// not. Without it an enabled folder is always in memory, fitted as small as
	// the limit demands, which is the choice for an operator who knows better than
	// the arithmetic. Meaningless unless Enabled.
	Auto bool `json:"auto,omitempty"`
}

// TmpfsConfig says which of a runner's folders are kept in memory. The zero
// value is nothing, so an upgrade never changes an existing pool.
type TmpfsConfig struct {
	// Work is the runner's _work folder: the checkout, build output and the
	// runner's own temporary files. It is the one worth having, and the one the
	// editor offers first.
	Work TmpfsMount `json:"work"`
	// Tmp is /tmp. It is separate because some toolchains put their heaviest
	// traffic there and some jobs leave gigabytes in it, and an operator should
	// choose that cost knowingly.
	Tmp TmpfsMount `json:"tmp"`
	// Daemon is the docker-in-docker sidecar's image store, /var/lib/docker in
	// the daemon's container: where every image a job pulls and every layer it
	// builds is written. It is a different container from the two above, with a
	// memory limit of its own -- the daemon's half of the pair for a pool sized by
	// its host, the full typed limit otherwise -- and the tmpfs is charged to that
	// limit, not the runner's. It is its own choice, and only a pool with
	// docker_mode dind has the container to mount it on, because filling it is
	// the one way this setting can fail a job that used to pass: an image bigger
	// than the mount does not pull.
	Daemon TmpfsMount `json:"daemon"`
}

// Any reports whether any folder is kept in memory.
func (c TmpfsConfig) Any() bool { return c.Work.Enabled || c.Tmp.Enabled || c.Daemon.Enabled }

// AnyAuto reports whether any folder that is in memory is placed per runner.
func (c TmpfsConfig) AnyAuto() bool {
	return c.Work.Enabled && c.Work.Auto || c.Tmp.Enabled && c.Tmp.Auto || c.Daemon.Enabled && c.Daemon.Auto
}

// AskedMB is what a folder is asked for: the size the pool typed, or else the
// host's own standard for a folder the pool leaves to size itself, or else the
// built-in default. It is the one place that order is written, because the
// warnings, the pool editor's plan and what a runner's row says it was asked
// for must agree about it.
func (m TmpfsMount) AskedMB(standard, def int64) int64 {
	switch {
	case m.SizeMB > 0:
		return m.SizeMB
	case standard > 0:
		return standard
	default:
		return def
	}
}

// ReserveMB is the memory this configuration may take, which is what a memory
// limit sized for the job alone should be raised by. A mount with no size of
// its own counts at its default, because that is what it would be given on a
// runner with room.
func (c TmpfsConfig) ReserveMB() int64 {
	var total int64
	for _, m := range []struct {
		mount TmpfsMount
		def   int64
	}{{c.Work, DefaultTmpfsWorkMB}, {c.Tmp, DefaultTmpfsTmpMB}} {
		switch {
		case !m.mount.Enabled:
		case m.mount.SizeMB > 0:
			total += m.mount.SizeMB
		default:
			total += m.def
		}
	}
	return total
}

// DaemonReserveMB is the memory the sidecar's image store may take: what was
// typed, or the default for one left to size itself, and nothing when it is off.
// It is counted apart from ReserveMB because it is charged to another container.
func (c TmpfsConfig) DaemonReserveMB() int64 {
	switch {
	case !c.Daemon.Enabled:
		return 0
	case c.Daemon.SizeMB > 0:
		return c.Daemon.SizeMB
	default:
		return DefaultTmpfsDaemonMB
	}
}

// RecommendedMemoryMB is the limit that leaves a runner capMB's worth of room
// for its job on top of whatever the tmpfs mounts may fill. Zero when there is
// nothing to propose: no limit to raise, or no mount in memory.
//
// A typed limit is given to the runner and to the daemon alike, and each
// container is charged for its own folders, so the limit has to cover whichever
// needs more: the sum would pay for room neither container uses.
func (c TmpfsConfig) RecommendedMemoryMB(capMB int64) int64 {
	if capMB <= 0 || !c.Any() {
		return 0
	}
	reserve := max(c.ReserveMB(), c.DaemonReserveMB())
	// At least twice what the folders may take, as well as the limit plus them:
	// folders are fitted into half a limit, so a proposal that left them more than
	// half would still be tight when it was taken, and the next would follow it
	// upward. On a limit smaller than the folders the sum alone falls short of that.
	return max(capMB+reserve, 2*reserve)
}

// DaemonSize returns what the image store is given on a daemon whose memory
// limit is capMB (zero is no limit): a typed size as it stands, otherwise the
// default fitted into half the limit, for the reason Sizes fits the others -- a
// store filling to its ceiling while the build also wants memory is the
// out-of-memory this setting must not cause by itself.
func (c TmpfsConfig) DaemonSize(capMB int64) int64 {
	return c.daemonSize(capMB, DefaultTmpfsDaemonMB)
}

// daemonSize is DaemonSize with the size an untyped store is asked for, which a
// host's own standard replaces.
func (c TmpfsConfig) daemonSize(capMB, def int64) int64 {
	switch {
	case !c.Daemon.Enabled:
		return 0
	case c.Daemon.SizeMB > 0 && capMB > 0 && c.Daemon.SizeMB >= capMB:
		// The same reduction Sizes makes: a typed size the daemon's real limit cannot
		// hold would OOM-kill it as the store filled.
		return max(capMB/2, MinTmpfsMB)
	case c.Daemon.SizeMB > 0:
		return c.Daemon.SizeMB
	case capMB <= 0:
		return def
	default:
		return min(def, max(capMB/2, MinTmpfsMB))
	}
}

// Sizes returns what each mount is actually given on a runner whose memory
// limit is capMB (zero is no limit).
//
// A size an operator typed is used as it stands. A mount left to the limit
// shares half of it, which is the most that leaves a job room to use the
// folder it asked for: a tmpfs filling to its ceiling while the build also
// wants memory is the OOM this feature must not cause on its own. With no limit
// there is nothing to fit to, and the defaults apply.
func (c TmpfsConfig) Sizes(capMB int64) (workMB, tmpMB int64) {
	return c.sizes(capMB, DefaultTmpfsWorkMB, DefaultTmpfsTmpMB)
}

// sizes is Sizes with the sizes untyped folders are asked for, which a host's
// own standards replace.
func (c TmpfsConfig) sizes(capMB, defWork, defTmp int64) (workMB, tmpMB int64) {
	var explicit, auto int64
	want := func(m TmpfsMount, def int64) (size int64, isAuto bool) {
		switch {
		case !m.Enabled:
			return 0, false
		case m.SizeMB > 0:
			explicit += m.SizeMB
			return m.SizeMB, false
		default:
			auto += def
			return def, true
		}
	}
	workMB, workAuto := want(c.Work, defWork)
	tmpMB, tmpAuto := want(c.Tmp, defTmp)
	if capMB <= 0 {
		return workMB, tmpMB
	}
	if auto == 0 {
		// Typed sizes were validated against the pool's stored limit, but the limit
		// a runner is really given can be smaller: an automatic pool takes its host's
		// share, and a fixed one is reduced on a small machine. Folders that together
		// reach that limit would OOM-kill the runner the moment a job filled them, so
		// they are scaled into half of it, in proportion, as auto sizes are.
		if explicit >= capMB {
			shrink := func(size int64) int64 {
				if size == 0 {
					return 0
				}
				return max(capMB/2*size/explicit, MinTmpfsMB)
			}
			return shrink(workMB), shrink(tmpMB)
		}
		return workMB, tmpMB
	}
	room := capMB/2 - explicit
	if room >= auto {
		return workMB, tmpMB
	}
	fit := func(def int64) int64 { return max(room*def/auto, MinTmpfsMB) }
	if workAuto {
		workMB = fit(defWork)
	}
	if tmpAuto {
		tmpMB = fit(defTmp)
	}
	return workMB, tmpMB
}

// HostTmpfs is a host's say over a pool's in-memory folders: some machines have
// memory to spare for them and some do not, and the pool, which is one setting
// for every host it lands on, cannot know which is which.
//
// It belongs to the host's runner profile, beside how big a runner is there,
// because it is the same kind of answer -- what a runner on this machine is
// built like -- and the operator's alone: an agent reports what it measures and
// never writes it. Zero is "not said", which leaves the pool's setting as it
// stands, so a host that says nothing changes nothing.
type HostTmpfs struct {
	// Disabled keeps every in-memory folder off this host, whatever a pool asks
	// for: its runners use disk, as they did before the setting existed. It is
	// for a machine with less memory than the pools that land on it assume.
	Disabled bool `json:"disabled,omitempty"`
	// MaxMB is the most any single in-memory folder may be on this host, applied
	// after a pool's own size is fitted to the runner's limit. Zero is no host
	// ceiling. A pool's size can lower it and never raise it, so a machine's
	// owner has the last word on how much of it a folder may take.
	MaxMB int64 `json:"max_mb,omitempty"`
	// WorkMB, TmpMB and DaemonMB are the sizes a folder is asked for on this
	// host when the pool leaves it to size itself, in place of the built-in
	// defaults: the folder-sized counterpart of a host's standard runner size. A
	// machine with 256 GB of memory can offer a work folder far larger than the
	// default, and one with 16 GB less. They are what is asked for, so the fit to
	// the runner's limit and MaxMB still apply; a size the pool typed is the
	// pool's and is not replaced. Zero is the default.
	WorkMB   int64 `json:"work_mb,omitempty"`
	TmpMB    int64 `json:"tmp_mb,omitempty"`
	DaemonMB int64 `json:"daemon_mb,omitempty"`
}

// Apply is the configuration a runner on this host is created with, and the
// ceiling its agent applies to each folder after fitting it to the runner's
// limit. A disabled host gets no folders, and no ceiling, since there is
// nothing to cap.
func (h HostTmpfs) Apply(c TmpfsConfig) (TmpfsConfig, int64) {
	if h.Disabled {
		return TmpfsConfig{}, 0
	}
	return c, h.MaxMB
}

// Cap lowers a folder's size to the host's ceiling, if it has one.
func Cap(sizeMB, maxMB int64) int64 {
	if maxMB > 0 && sizeMB > maxMB {
		return maxMB
	}
	return sizeMB
}

// pick is the host's standard where it has one, the built-in default otherwise.
func pick(standard, def int64) int64 {
	if standard > 0 {
		return standard
	}
	return def
}

// floorFor is the least an automatic folder is worth: its floor, or a typed
// size when that is smaller, since an operator who typed 1 GB asked for 1 GB.
func floorFor(m TmpfsMount, floor int64) int64 {
	if m.SizeMB > 0 {
		return min(floor, m.SizeMB)
	}
	return floor
}

// PlaceRunner is what the runner's work folder and /tmp are given on a runner
// whose memory limit is capMB, on a host with policy h: zero for a folder that
// stays on disk. It is the one answer the agent mounts from and the controller
// warns from, so what an operator is told is what a runner is given.
//
// The folders are fitted to the limit (Sizes) from the host's standards,
// lowered to the host's ceiling, and then each automatic folder that came out
// below its floor is put on disk -- the one furthest below first, since giving
// that one up frees room for the other -- and the rest refitted, until what is
// left is worth having. A folder that is not automatic is never dropped.
func (c TmpfsConfig) PlaceRunner(capMB int64, h HostTmpfs) (workMB, tmpMB int64) {
	cc := c
	defWork, defTmp := pick(h.WorkMB, DefaultTmpfsWorkMB), pick(h.TmpMB, DefaultTmpfsTmpMB)
	for range 3 {
		workMB, tmpMB = cc.sizes(capMB, defWork, defTmp)
		workMB, tmpMB = Cap(workMB, h.MaxMB), Cap(tmpMB, h.MaxMB)
		// How far each automatic folder is from being worth having, as a part of
		// its floor; the worst below one goes. /tmp is judged first so that a tie
		// goes against it: the two are asked for the same size by default and so
		// come out of the fit the same distance below their floors, and the work
		// folder is the one worth having. A build whose /tmp is on disk is slower;
		// one whose checkout is on disk gets nothing from the setting.
		worst, ratio := "", 1.0
		if cc.Tmp.Enabled && cc.Tmp.Auto {
			if r := float64(tmpMB) / float64(floorFor(cc.Tmp, AutoMinTmpMB)); r < ratio {
				worst, ratio = "tmp", r
			}
		}
		if cc.Work.Enabled && cc.Work.Auto {
			if r := float64(workMB) / float64(floorFor(cc.Work, AutoMinWorkMB)); r < ratio {
				worst, ratio = "work", r
			}
		}
		switch worst {
		case "work":
			cc.Work.Enabled = false
		case "tmp":
			cc.Tmp.Enabled = false
		default:
			return workMB, tmpMB
		}
	}
	workMB, tmpMB = cc.sizes(capMB, defWork, defTmp)
	return Cap(workMB, h.MaxMB), Cap(tmpMB, h.MaxMB)
}

// PlaceDaemon is PlaceRunner for the sidecar's image store, on a daemon whose
// memory limit is capMB. Zero is on disk.
func (c TmpfsConfig) PlaceDaemon(capMB int64, h HostTmpfs) int64 {
	size := Cap(c.daemonSize(capMB, pick(h.DaemonMB, DefaultTmpfsDaemonMB)), h.MaxMB)
	if c.Daemon.Enabled && c.Daemon.Auto && size < floorFor(c.Daemon, AutoMinDaemonMB) {
		return 0
	}
	return size
}

// Validate checks the configuration against the pool's memory limit (zero is
// none). It refuses what cannot work rather than what is merely unwise: sizes
// below the floor, and sizes that together take the whole limit, because a
// tmpfs counts against the cgroup and a job could never run in what is left.
//
// It returns the dotted name of the field to blame, so a form can put the
// message beside the control, and what is wrong; both are empty when the
// configuration is valid.
func (c TmpfsConfig) Validate(capMB int64) (field, problem string) {
	var explicit int64
	last := ""
	for _, m := range []struct {
		name  string
		mount TmpfsMount
	}{{"work", c.Work}, {"tmp", c.Tmp}, {"daemon", c.Daemon}} {
		name := "tmpfs." + m.name + ".size_mb"
		if m.mount.SizeMB < 0 {
			return name, "a size cannot be negative; use 0 to size it from the memory limit"
		}
		if m.mount.Auto && !m.mount.Enabled {
			return "tmpfs." + m.name + ".auto", "auto decides where an in-memory folder lives, so the folder has to be turned on for it to mean anything"
		}
		if !m.mount.Enabled {
			continue
		}
		if m.mount.SizeMB > 0 && m.mount.SizeMB < MinTmpfsMB {
			return name, fmt.Sprintf("a size must be at least %d MB, or 0 to size it from the memory limit", MinTmpfsMB)
		}
		// The image store is charged to the daemon's container, whose limit is
		// checked on its own below; only the runner's folders add up against the
		// runner's.
		if m.mount.SizeMB > 0 && m.name != "daemon" {
			explicit += m.mount.SizeMB
			last = name
		}
	}
	if capMB > 0 && c.Daemon.Enabled && c.Daemon.SizeMB >= capMB {
		return "tmpfs.daemon.size_mb", fmt.Sprintf("the image store is %d MB and the memory limit is %d MB; the daemon's tmpfs is charged to that limit, "+
			"so raise the limit (to at least %d MB) or shrink the store", c.Daemon.SizeMB, capMB, capMB+c.Daemon.SizeMB)
	}
	if capMB > 0 && explicit >= capMB {
		return last, fmt.Sprintf("the sizes total %d MB and the runner's memory limit is %d MB; a tmpfs is charged to that limit, "+
			"so raise the limit (to at least %d MB) or shrink the folders", explicit, capMB, capMB+explicit)
	}
	return "", ""
}

// ScratchKind names one of a runner's folders that a pool may keep in memory.
type ScratchKind string

const (
	// ScratchWork is the runner's _work folder, ScratchTmp its /tmp, and
	// ScratchDaemon the docker-in-docker sidecar's image store.
	ScratchWork   ScratchKind = "work"
	ScratchTmp    ScratchKind = "tmp"
	ScratchDaemon ScratchKind = "daemon"
)

// ScratchWhy says why a folder a pool keeps in memory is on disk for one runner.
// Empty for a folder that is in memory.
type ScratchWhy string

const (
	// ScratchAutoTooSmall: the folder is automatic, and the runner's limit left
	// it less than it is worth having (the AutoMin* floors).
	ScratchAutoTooSmall ScratchWhy = "auto_too_small"
	// ScratchHostOff: the host's owner has said no folder is kept in memory on it.
	ScratchHostOff ScratchWhy = "host_off"
	// ScratchUnsupported: the agent on the host is too old to mount one.
	ScratchUnsupported ScratchWhy = "unsupported"
	// ScratchBound: the work folder is a directory bound from the host, and
	// two mounts at one path is an error the daemon reports only at create.
	ScratchBound ScratchWhy = "bound"
)

// ScratchFolder is one in-memory folder of one runner: what was asked for and
// what it was given.
type ScratchFolder struct {
	Kind ScratchKind `json:"kind"`
	// AskedMB is what the pool, or the host's standard for a folder the pool
	// leaves to size itself, asked for. SizeMB is what the runner was given,
	// fitted to its limit, and zero is on disk.
	AskedMB int64 `json:"asked_mb,omitempty"`
	SizeMB  int64 `json:"size_mb,omitempty"`
	// Auto is the folder letting each runner decide where it lives.
	Auto bool       `json:"auto,omitempty"`
	Why  ScratchWhy `json:"why,omitempty"`
}

// InMemory reports whether the runner was given the folder in memory.
func (f ScratchFolder) InMemory() bool { return f.SizeMB > 0 }

// RunnerScratch is the folders a pool keeps in memory, as they were worked out
// for one runner when it was created. Empty for a runner whose pool keeps none.
type RunnerScratch struct {
	Folders []ScratchFolder `json:"folders,omitempty"`
	// ControllerVersion is the build that worked the folders out, and
	// AgentVersion the build of the agent on the host, which mounts them from
	// its own copy of the placement rule. While the two are the same build the
	// row is what the runner was given; while they differ, as they do for the
	// hours after a release reaches the controller and before every host has
	// followed it, it is the controller's estimate, and whoever reads it has to
	// be told. Empty on rows from before the builds were recorded, and on a row
	// written with no host to ask.
	ControllerVersion string `json:"controller_version,omitempty"`
	AgentVersion      string `json:"agent_version,omitempty"`
}

// Any reports whether the pool asked for any folder to be kept in memory.
func (s RunnerScratch) Any() bool { return len(s.Folders) > 0 }

// InMemory counts the folders the runner was given in memory.
func (s RunnerScratch) InMemory() int {
	n := 0
	for _, f := range s.Folders {
		if f.InMemory() {
			n++
		}
	}
	return n
}

// ScratchPeak is the fullest one in-memory folder of a job's runner got while
// the job ran: the folder by its path in the container, the most that was
// written in it at any sample, and its ceiling.
type ScratchPeak struct {
	Path   string `json:"path"`
	PeakMB int64  `json:"peak_mb"`
	SizeMB int64  `json:"size_mb"`
}

// Fraction is how full the folder got, as a share of its ceiling.
func (p ScratchPeak) Fraction() float64 {
	if p.SizeMB <= 0 {
		return 0
	}
	return float64(p.PeakMB) / float64(p.SizeMB)
}

// ScratchPeaks is a job's folders, one entry per path, kept as JSON in a TEXT
// column. Nil is never measured.
type ScratchPeaks []ScratchPeak

// Scan reads the column; an empty column is nil, as a job before the peaks
// were kept has.
func (s *ScratchPeaks) Scan(v any) error {
	*s = nil
	switch t := v.(type) {
	case nil:
		return nil
	case []byte:
		if len(t) == 0 {
			return nil
		}
		return json.Unmarshal(t, s)
	case string:
		if t == "" {
			return nil
		}
		return json.Unmarshal([]byte(t), s)
	default:
		return fmt.Errorf("cannot scan %T into ScratchPeaks", v)
	}
}

// Value writes the column: nothing measured is the empty string the column
// defaults to, so a row written and a row never touched read the same.
func (s ScratchPeaks) Value() (driver.Value, error) {
	if len(s) == 0 {
		return "", nil
	}
	b, err := json.Marshal([]ScratchPeak(s))
	return string(b), err
}

// Raise merges one sample into the peaks: a folder seen before keeps the
// larger of its peak and the sample, a folder new to the job is added, and
// the ceiling follows the sample, which is the mount's own figure. The result
// is ordered by path, so two readings of one job compare equal.
func (s ScratchPeaks) Raise(sample []ScratchPeak) ScratchPeaks {
	byPath := map[string]ScratchPeak{}
	for _, p := range s {
		byPath[p.Path] = p
	}
	for _, p := range sample {
		if p.Path == "" || p.SizeMB <= 0 {
			continue
		}
		have, ok := byPath[p.Path]
		if !ok || p.PeakMB > have.PeakMB {
			have.PeakMB = p.PeakMB
		}
		have.Path, have.SizeMB = p.Path, p.SizeMB
		byPath[p.Path] = have
	}
	out := make(ScratchPeaks, 0, len(byPath))
	for _, p := range byPath {
		out = append(out, p)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Path < out[j].Path })
	return out
}

// Fullest is the folder that came nearest its ceiling, and how near, as a
// share of it. False when nothing was measured.
func (s ScratchPeaks) Fullest() (ScratchPeak, float64, bool) {
	var best ScratchPeak
	fraction, found := -1.0, false
	for _, p := range s {
		if f := p.Fraction(); !found || f > fraction {
			best, fraction, found = p, f, true
		}
	}
	if !found {
		return ScratchPeak{}, 0, false
	}
	return best, fraction, true
}

package store

import (
	"context"
	"strings"
	"testing"
)

func TestTmpfsSizesFitAutomaticMountsToTheMemoryLimit(t *testing.T) {
	cases := []struct {
		name              string
		cfg               TmpfsConfig
		capMB             int64
		wantWork, wantTmp int64
	}{
		{"nothing in memory", TmpfsConfig{}, 16384, 0, 0},
		{"no limit takes the defaults", TmpfsConfig{Work: TmpfsMount{Enabled: true}, Tmp: TmpfsMount{Enabled: true}}, 0, DefaultTmpfsWorkMB, DefaultTmpfsTmpMB},
		{"a roomy limit takes the defaults", TmpfsConfig{Work: TmpfsMount{Enabled: true}}, 32768, DefaultTmpfsWorkMB, 0},
		{"a small limit shrinks the work folder to half of it", TmpfsConfig{Work: TmpfsMount{Enabled: true}}, 4096, 2048, 0},
		{"two automatic mounts share half the limit in proportion", TmpfsConfig{Work: TmpfsMount{Enabled: true}, Tmp: TmpfsMount{Enabled: true}}, 5120, 1280, 1280},
		{"a typed size is never shrunk", TmpfsConfig{Work: TmpfsMount{Enabled: true, SizeMB: 3000}}, 4096, 3000, 0},
		{"automatic mounts fit what a typed one leaves", TmpfsConfig{Work: TmpfsMount{Enabled: true, SizeMB: 1000}, Tmp: TmpfsMount{Enabled: true}}, 4096, 1000, 1048},
		{"an absurdly small limit still gets a usable mount", TmpfsConfig{Work: TmpfsMount{Enabled: true}}, 100, MinTmpfsMB, 0},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			work, tmp := tc.cfg.Sizes(tc.capMB)
			if work != tc.wantWork || tmp != tc.wantTmp {
				t.Fatalf("Sizes(%d) = %d, %d; want %d, %d", tc.capMB, work, tmp, tc.wantWork, tc.wantTmp)
			}
		})
	}
}

// The proposal is cap plus what the mounts may fill, because the cap was sized
// for the job and a tmpfs spends it. Nothing is proposed where there is nothing
// to raise: no limit, or nothing in memory.
func TestTmpfsProposesRaisingTheLimitByWhatItMayFill(t *testing.T) {
	cfg := TmpfsConfig{Work: TmpfsMount{Enabled: true, SizeMB: 6000}, Tmp: TmpfsMount{Enabled: true}}
	if got, want := cfg.ReserveMB(), 6000+DefaultTmpfsTmpMB; got != want {
		t.Fatalf("ReserveMB = %d, want %d", got, want)
	}
	// The limit plus the folders, and never less than twice the folders: with
	// /tmp asking for as much as the work folder, twice is the larger here.
	if got, want := cfg.RecommendedMemoryMB(8192), max(int64(8192)+6000+DefaultTmpfsTmpMB, 2*(6000+DefaultTmpfsTmpMB)); got != want {
		t.Fatalf("RecommendedMemoryMB = %d, want %d", got, want)
	}
	if got := cfg.RecommendedMemoryMB(0); got != 0 {
		t.Fatalf("a pool with no limit is proposed %d, want nothing", got)
	}
	if got := (TmpfsConfig{}).RecommendedMemoryMB(8192); got != 0 {
		t.Fatalf("a pool with nothing in memory is proposed %d, want nothing", got)
	}
}

func TestTmpfsValidateRefusesWhatCannotWork(t *testing.T) {
	cases := []struct {
		name      string
		cfg       TmpfsConfig
		capMB     int64
		wantField string // empty means valid
		want      string
	}{
		{"off is always valid", TmpfsConfig{}, 1024, "", ""},
		{"automatic sizes are valid on any limit", TmpfsConfig{Work: TmpfsMount{Enabled: true}}, 1024, "", ""},
		{"a disabled mount's size is ignored", TmpfsConfig{Work: TmpfsMount{SizeMB: 1}}, 1024, "", ""},
		{"below the floor", TmpfsConfig{Work: TmpfsMount{Enabled: true, SizeMB: 8}}, 0, "tmpfs.work.size_mb", "at least 64 MB"},
		{"negative", TmpfsConfig{Tmp: TmpfsMount{Enabled: true, SizeMB: -1}}, 0, "tmpfs.tmp.size_mb", "negative"},
		{"the whole limit", TmpfsConfig{Work: TmpfsMount{Enabled: true, SizeMB: 4096}}, 4096, "tmpfs.work.size_mb", "to at least 8192 MB"},
		{"together they take the limit", TmpfsConfig{Work: TmpfsMount{Enabled: true, SizeMB: 3000}, Tmp: TmpfsMount{Enabled: true, SizeMB: 1200}}, 4096, "tmpfs.tmp.size_mb", "total 4200 MB"},
		{"no limit to exceed", TmpfsConfig{Work: TmpfsMount{Enabled: true, SizeMB: 999999}}, 0, "", ""},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			field, problem := tc.cfg.Validate(tc.capMB)
			if field != tc.wantField {
				t.Fatalf("Validate blamed %q, want %q (%s)", field, tc.wantField, problem)
			}
			if tc.want == "" && problem != "" {
				t.Fatalf("Validate = %q, want valid", problem)
			}
			if tc.want != "" && !strings.Contains(problem, tc.want) {
				t.Fatalf("Validate = %q, want it to contain %q", problem, tc.want)
			}
		})
	}
}

// The image store is charged to the daemon's container, which has a memory
// limit of its own, so it is sized from that limit and not the runner's.
func TestTheImageStoreIsFittedToTheDaemonsMemoryLimit(t *testing.T) {
	on := TmpfsConfig{Daemon: TmpfsMount{Enabled: true}}
	cases := []struct {
		name  string
		cfg   TmpfsConfig
		capMB int64
		want  int64
	}{
		{"off", TmpfsConfig{}, 16384, 0},
		{"no limit takes the default", on, 0, DefaultTmpfsDaemonMB},
		{"a roomy limit takes the default", on, 65536, DefaultTmpfsDaemonMB},
		{"a small limit shrinks it to half", on, 6000, 3000},
		{"a typed size is never shrunk", TmpfsConfig{Daemon: TmpfsMount{Enabled: true, SizeMB: 5000}}, 6000, 5000},
		{"an absurdly small limit still gets a usable store", on, 100, MinTmpfsMB},
	}
	for _, tc := range cases {
		if got := tc.cfg.DaemonSize(tc.capMB); got != tc.want {
			t.Errorf("%s: DaemonSize(%d) = %d, want %d", tc.name, tc.capMB, got, tc.want)
		}
	}
}

// A typed limit is given to the runner and to the daemon alike, and each is
// charged for its own folders, so the proposed limit covers whichever needs more
// -- not both, which would pay for room neither container uses.
func TestTheProposedLimitCoversTheContainerThatNeedsMore(t *testing.T) {
	cfg := TmpfsConfig{
		Work:   TmpfsMount{Enabled: true, SizeMB: 2000},
		Daemon: TmpfsMount{Enabled: true, SizeMB: 6000},
	}
	if got, want := cfg.RecommendedMemoryMB(8192), int64(8192+6000); got != want {
		t.Fatalf("RecommendedMemoryMB = %d, want the daemon's 6000 added once, %d", got, want)
	}
	cfg.Daemon.SizeMB = 1000
	if got, want := cfg.RecommendedMemoryMB(8192), int64(8192+2000); got != want {
		t.Fatalf("RecommendedMemoryMB = %d, want the runner's 2000 added once, %d", got, want)
	}
	if got := (TmpfsConfig{Daemon: TmpfsMount{Enabled: true}}).DaemonReserveMB(); got != DefaultTmpfsDaemonMB {
		t.Fatalf("DaemonReserveMB = %d, want the default %d", got, DefaultTmpfsDaemonMB)
	}
	if !(TmpfsConfig{Daemon: TmpfsMount{Enabled: true}}).Any() {
		t.Fatal("a pool keeping only its image store in memory reads as keeping nothing")
	}
}

// The image store is held to its own container's limit: it does not add up with
// the runner's folders, which are charged to another cgroup.
func TestTheImageStoreIsValidatedAgainstTheDaemonsOwnLimit(t *testing.T) {
	both := TmpfsConfig{
		Work:   TmpfsMount{Enabled: true, SizeMB: 3000},
		Daemon: TmpfsMount{Enabled: true, SizeMB: 3000},
	}
	if field, problem := both.Validate(4096); field != "" {
		t.Fatalf("each fits its own 4096 MB limit, but %s was refused: %s", field, problem)
	}
	whole := TmpfsConfig{Daemon: TmpfsMount{Enabled: true, SizeMB: 4096}}
	field, problem := whole.Validate(4096)
	if field != "tmpfs.daemon.size_mb" || !strings.Contains(problem, "to at least 8192 MB") {
		t.Fatalf("Validate = %q, %q; want the image store named with the limit that fits it", field, problem)
	}
	if field, _ := (TmpfsConfig{Daemon: TmpfsMount{Enabled: true, SizeMB: 8}}).Validate(0); field != "tmpfs.daemon.size_mb" {
		t.Fatalf("a store below the floor blamed %q", field)
	}
}

// A proposal that is taken must end the warning, or the next one follows it
// upward. Folders are fitted into half a limit, so the proposed limit is at
// least twice what they may take -- which is more than the limit plus them when
// the limit is smaller than they are.
func TestAProposedLimitEndsTheWarningWhenItIsTaken(t *testing.T) {
	for _, cfg := range []TmpfsConfig{
		{Work: TmpfsMount{Enabled: true}},
		{Daemon: TmpfsMount{Enabled: true}},
		{Work: TmpfsMount{Enabled: true}, Tmp: TmpfsMount{Enabled: true}, Daemon: TmpfsMount{Enabled: true}},
	} {
		for _, limit := range []int64{1024, 2048, 6144, 8192} {
			rec := cfg.RecommendedMemoryMB(limit)
			work, tmp := cfg.Sizes(rec)
			if work+tmp < cfg.ReserveMB() || cfg.DaemonSize(rec) < cfg.DaemonReserveMB() {
				t.Errorf("%+v: at the proposed %d MB (from %d) the folders are still fitted down: %d+%d, store %d",
					cfg, rec, limit, work, tmp, cfg.DaemonSize(rec))
			}
		}
	}
	// And where the sum is already enough, it is the sum.
	cfg := TmpfsConfig{Work: TmpfsMount{Enabled: true}}
	if got, want := cfg.RecommendedMemoryMB(6144), int64(6144+4096); got != want {
		t.Errorf("RecommendedMemoryMB(6144) = %d, want %d", got, want)
	}
}

// A host's policy is its owner's last word: off means none, a ceiling lowers a
// folder and never raises it, and a host that says nothing changes nothing.
func TestAHostsPolicyLowersAFolderAndNeverRaisesIt(t *testing.T) {
	pool := TmpfsConfig{Work: TmpfsMount{Enabled: true, SizeMB: 4096}, Daemon: TmpfsMount{Enabled: true}}

	if got, max := (HostTmpfs{}).Apply(pool); got != pool || max != 0 {
		t.Errorf("a silent host changed the pool's setting: %+v max %d", got, max)
	}
	if got, max := (HostTmpfs{Disabled: true, MaxMB: 1024}).Apply(pool); got.Any() || max != 0 {
		t.Errorf("a disabled host kept %+v with a ceiling of %d", got, max)
	}
	if got, max := (HostTmpfs{MaxMB: 2048}).Apply(pool); got != pool || max != 2048 {
		t.Errorf("a ceiling must leave the setting as it was and hand the agent the number: %+v max %d", got, max)
	}

	for _, tc := range []struct{ size, max, want int64 }{
		{4096, 0, 4096},    // no ceiling
		{4096, 2048, 2048}, // lowered
		{1024, 2048, 1024}, // never raised
		{0, 2048, 0},       // a folder that is off stays off
	} {
		if got := Cap(tc.size, tc.max); got != tc.want {
			t.Errorf("Cap(%d, %d) = %d, want %d", tc.size, tc.max, got, tc.want)
		}
	}
}

// The policy is part of the runner profile, so it must survive being stored and
// read back with the figures beside it, and a profile that says only this is
// still a profile an operator set.
func TestAHostsInMemoryPolicyIsStoredWithItsRunnerProfile(t *testing.T) {
	ctx := context.Background()
	s := newTestStore(t)
	h := &Host{Name: "builder", Capacity: 2, Backends: StringSlice{"docker"}, Labels: StringMap{}, OS: "linux", Arch: "amd64"}
	if err := s.CreateHost(ctx, h); err != nil {
		t.Fatal(err)
	}
	profile := RunnerProfile{
		Standard: RunnerStandard{CPUs: 2, MemoryMB: 8192},
		Tmpfs:    HostTmpfs{Disabled: true},
	}
	if !(RunnerProfile{Tmpfs: HostTmpfs{MaxMB: 512}}).Set() {
		t.Fatal("a profile that only caps the folders reads as one nobody set")
	}
	if err := s.PatchHost(ctx, h.ID, HostChanges{RunnerProfile: &profile}); err != nil {
		t.Fatal(err)
	}
	got, err := s.GetHost(ctx, h.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.RunnerProfile != profile {
		t.Fatalf("profile = %+v, want %+v", got.RunnerProfile, profile)
	}
}

// A typed size is checked against the pool's stored limit, but the runner may be
// given less (a host's share, or a reduced fixed size); folders that reach the
// real limit would OOM-kill the runner as they filled.
func TestTypedTmpfsSizesAreScaledIntoARunnerLimitSmallerThanTheyAssume(t *testing.T) {
	c := TmpfsConfig{Work: TmpfsMount{Enabled: true, SizeMB: 4096}, Tmp: TmpfsMount{Enabled: true, SizeMB: 1024}}
	work, tmp := c.Sizes(1024)
	if work+tmp > 512 || work <= tmp {
		t.Fatalf("sizes %d and %d should fit in half of 1024 MB, work larger", work, tmp)
	}
	if work, tmp := c.Sizes(16384); work != 4096 || tmp != 1024 {
		t.Fatalf("a roomy limit must leave typed sizes alone, got %d and %d", work, tmp)
	}
	d := TmpfsConfig{Daemon: TmpfsMount{Enabled: true, SizeMB: 8192}}
	if got := d.DaemonSize(2048); got != 1024 {
		t.Fatalf("daemon size = %d, want 1024", got)
	}
}

func TestADaemonShareDividesASlotUnevenlyAndEvenByDefault(t *testing.T) {
	slot := Resources{CPUs: 10, MemoryMB: 10000}
	r, d := slot.SplitWithDaemon()
	if r.CPUs != 5 || d.CPUs != 5 || r.MemoryMB != 5000 || d.MemoryMB != 5000 {
		t.Fatalf("default split = %+v / %+v, want even", r, d)
	}
	r, d = slot.SplitWithDaemonShare(70)
	if d.CPUs != 7 || r.CPUs != 3 || d.MemoryMB != 7000 || r.MemoryMB != 3000 {
		t.Fatalf("70%% split = %+v / %+v", r, d)
	}
	if r2, d2 := slot.SplitWithDaemonShare(5); r2 != r0(slot) || d2 != d0(slot) {
		t.Fatalf("a share out of range must fall back to even, got %+v / %+v", r2, d2)
	}
	if got := (Resources{DaemonSharePercent: 80}).MemoryPairFactor(); got != 5 {
		t.Fatalf("MemoryPairFactor(80) = %v, want 5", got)
	}
	if got := (Resources{}).CPUPairFactor(); got != 2 {
		t.Fatalf("CPUPairFactor() = %v, want 2", got)
	}
}

func r0(s Resources) Resources { r, _ := s.SplitWithDaemon(); return r }
func d0(s Resources) Resources { _, d := s.SplitWithDaemon(); return d }

// An automatic folder is in memory where the runner has room for it to be
// worth having, and on disk where it has not; the one furthest below its floor
// goes first, because giving it up leaves the other more.
func TestAnAutomaticFolderGoesToDiskWhereTheRunnerIsTooSmallForIt(t *testing.T) {
	auto := TmpfsConfig{Work: TmpfsMount{Enabled: true, Auto: true}, Tmp: TmpfsMount{Enabled: true, Auto: true}}
	for _, tc := range []struct {
		name          string
		cfg           TmpfsConfig
		capMB         int64
		host          HostTmpfs
		work, tmp     int64
		wantWorkAtMin bool
	}{
		{"a 2 GB runner has no room for either", auto, 2048, HostTmpfs{}, 0, 0, false},
		{"a roomy runner takes both at their defaults", auto, 32768, HostTmpfs{}, 4096, 4096, false},
		{"/tmp gives way first and the work folder takes the room", auto, 5120, HostTmpfs{}, 2560, 0, true},
		{"a host's bigger standard is asked for, and fitted", TmpfsConfig{Work: TmpfsMount{Enabled: true, Auto: true}}, 65536, HostTmpfs{WorkMB: 16384}, 16384, 0, false},
		{"a host ceiling under the floor puts the folder on disk", TmpfsConfig{Work: TmpfsMount{Enabled: true, Auto: true}}, 65536, HostTmpfs{MaxMB: 1024}, 0, 0, false},
		{"a folder that is not automatic is never dropped", TmpfsConfig{Work: TmpfsMount{Enabled: true}, Tmp: TmpfsMount{Enabled: true}}, 2048, HostTmpfs{}, 512, 512, false},
		{"a typed size lowers the floor to itself", TmpfsConfig{Work: TmpfsMount{Enabled: true, Auto: true, SizeMB: 1024}}, 4096, HostTmpfs{}, 1024, 0, false},
	} {
		work, tmp := tc.cfg.PlaceRunner(tc.capMB, tc.host)
		if work != tc.work || tmp != tc.tmp {
			t.Errorf("%s: placed %d and %d MB, want %d and %d", tc.name, work, tmp, tc.work, tc.tmp)
		}
	}

	d := TmpfsConfig{Daemon: TmpfsMount{Enabled: true, Auto: true}}
	if got := d.PlaceDaemon(3072, HostTmpfs{}); got != 0 {
		t.Errorf("a 3 GB daemon was given %d MB of image store, want disk", got)
	}
	if got := d.PlaceDaemon(16384, HostTmpfs{}); got != 8192 {
		t.Errorf("a 16 GB daemon was given %d MB of image store, want 8192", got)
	}
	manual := TmpfsConfig{Daemon: TmpfsMount{Enabled: true}}
	if got := manual.PlaceDaemon(3072, HostTmpfs{}); got != 1536 {
		t.Errorf("a manual store on a 3 GB daemon was given %d MB, want 1536", got)
	}
}

// Three places say what a folder was asked for -- the pool editor's plan, the
// warnings, and the line on a runner's row -- and an operator reads them side by
// side, so the order has to be written once: what the pool typed, then what the
// host's profile says, then the built-in default.
func TestAFolderIsAskedForWhatThePoolTypedThenTheHostsStandardThenTheDefault(t *testing.T) {
	for _, tc := range []struct {
		name     string
		mount    TmpfsMount
		standard int64
		want     int64
	}{
		{"the pool's own size wins over everything", TmpfsMount{Enabled: true, SizeMB: 3072}, 8192, 3072},
		{"a folder the pool leaves to size itself takes the host's standard", TmpfsMount{Enabled: true}, 8192, 8192},
		{"and the default where the host names none", TmpfsMount{Enabled: true}, 0, 4096},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := tc.mount.AskedMB(tc.standard, 4096); got != tc.want {
				t.Errorf("asked for %d MB, want %d", got, tc.want)
			}
		})
	}
}

// CPU and memory are split on their own: a build is CPU in the daemon, while the
// runner keeps the memory its checkout and an in-memory work folder need. The
// general figure applies to both unless a specific one overrides it, so a pool
// that set one number before keeps meaning it.
func TestCPUAndMemoryAreSplitIndependently(t *testing.T) {
	slot := Resources{CPUs: 10, MemoryMB: 10000}
	r, d := slot.SplitWithDaemonShares(70, 30)
	if d.CPUs != 7 || r.CPUs != 3 || d.MemoryMB != 3000 || r.MemoryMB != 7000 {
		t.Fatalf("70%% CPU, 30%% memory = runner %+v, daemon %+v", r, d)
	}
	if r, d := slot.SplitWithDaemonShares(70, 50); d.CPUs != 7 || r.MemoryMB != 5000 || d.MemoryMB != 5000 {
		t.Fatalf("an even memory share was not even: %+v / %+v", r, d)
	}
	// A figure out of range is even for that resource only.
	if r, d := slot.SplitWithDaemonShares(5, 70); d.CPUs != 5 || d.MemoryMB != 7000 || r.MemoryMB != 3000 {
		t.Fatalf("a bad CPU share spoiled the memory one: %+v / %+v", r, d)
	}

	for _, tc := range []struct {
		name     string
		r        Resources
		cpu, mem int
	}{
		{"nothing said is even", Resources{}, 50, 50},
		{"the general figure applies to both", Resources{DaemonSharePercent: 70}, 70, 70},
		{"a specific figure overrides it for its own resource", Resources{DaemonSharePercent: 70, DaemonCPUSharePercent: 60}, 60, 70},
		{"each can stand alone", Resources{DaemonCPUSharePercent: 80, DaemonMemorySharePercent: 25}, 80, 25},
	} {
		if cpu, mem := tc.r.DaemonCPUPercent(), tc.r.DaemonMemoryPercent(); cpu != tc.cpu || mem != tc.mem {
			t.Errorf("%s: cpu %d memory %d, want %d and %d", tc.name, cpu, mem, tc.cpu, tc.mem)
		}
	}
	if got := (Resources{DaemonCPUSharePercent: 80, DaemonMemorySharePercent: 50}); got.CPUPairFactor() != 5 || got.MemoryPairFactor() != 2 {
		t.Errorf("pair factors are per resource: cpu %v memory %v", got.CPUPairFactor(), got.MemoryPairFactor())
	}
}

// The floor for /tmp is what a toolchain keeps there until a command exits. Go
// is the measure: it compiles every package of a cold build into its work
// directory under /tmp and keeps them there, with the linker's output on top,
// until the build finishes. A cold cross-compile of this repository leaves 962
// MB there, and the darwin/amd64 link of main died twice on the fleet with
// "mapping output file failed: no space left on device" in a 1 GB /tmp. The
// floor is the least an in-memory /tmp is worth having, so it has to clear a
// build like that with room for the binary to grow, and the default is what a
// runner with room is given: the same as the work folder, which holds the
// same kind of thing.
func TestAnInMemoryTmpIsNeverTooSmallForAColdGoBuild(t *testing.T) {
	const coldGoBuildMB = 962
	if AutoMinTmpMB < 2*coldGoBuildMB {
		t.Fatalf("AutoMinTmpMB = %d; a cold Go build of this repository leaves %d MB in /tmp and a floor that does not clear it twice fails the next link", AutoMinTmpMB, coldGoBuildMB)
	}
	if DefaultTmpfsTmpMB < DefaultTmpfsWorkMB {
		t.Fatalf("DefaultTmpfsTmpMB = %d, DefaultTmpfsWorkMB = %d; /tmp holds a whole cold build the way the work folder holds a checkout, so it is given no less", DefaultTmpfsTmpMB, DefaultTmpfsWorkMB)
	}
}

// With the two folders asked for the same size they come out of the fit the
// same distance below their floors, and on a runner too small for both the
// one that goes has to be /tmp: the work folder is the one worth having (it is
// what the editor offers first), and a build whose /tmp is on disk is slower
// while one whose checkout is on disk gets nothing from the setting.
func TestATieBetweenTheFoldersGoesAgainstTmp(t *testing.T) {
	auto := TmpfsConfig{Work: TmpfsMount{Enabled: true, Auto: true}, Tmp: TmpfsMount{Enabled: true, Auto: true}}
	host := HostTmpfs{WorkMB: 4096, TmpMB: 4096}
	work, tmp := auto.PlaceRunner(5120, host)
	if work != 2560 || tmp != 0 {
		t.Fatalf("placed work %d and /tmp %d MB on a 5 GB runner, want the work folder to take the half and /tmp to go to disk", work, tmp)
	}
}

package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"strings"
	"time"
)

// What an attempt was for: the controller's own binary, or one host's.
const (
	UpdateScopeController = "controller"
	UpdateScopeHost       = "host"
)

// Who asked: a person pressing the button, or the planner acting on the
// update mode.
const (
	UpdateTriggerManual = "manual"
	UpdateTriggerAuto   = "auto"
)

// An attempt is requested until it ends, and ends once, in one of four ways.
const (
	UpdateRequested = "requested"
	UpdateSucceeded = "succeeded"
	UpdateFailed    = "failed"
	UpdateTimedOut  = "timed_out"
	UpdateCancelled = "cancelled"
)

// hostGoneReason is what an attempt says when the host it was for was deleted
// before the host reported. It is written for the person reading the history.
const hostGoneReason = "The host was removed before the update finished, so nothing will report on it. Enrol the host again to update it."

// UpdateAttempt is one request to change one target's version. HostID is empty
// for the controller's own attempts. It is not a foreign key: a host that
// joins again under the same id keeps its history (see migration 0086).
type UpdateAttempt struct {
	ID          string
	Scope       string
	HostID      string
	FromVersion string
	ToVersion   string
	Trigger     string
	RequestedBy string
	State       string
	Error       string
	// RolloutID is the rollout that asked for the attempt, or empty for the
	// controller's own and for a button pressed by a person (migration 0090).
	RolloutID string
	// Backup is the directory of the copy the engine took before it changed
	// anything, and RolledBack says it put the previous release back because the
	// new one did not answer (migration 0108). Both are empty on an attempt
	// whose result carried neither.
	Backup     string
	RolledBack bool
	// Stuck is the controller's record of a stalled update helper found while
	// this attempt was being handed over (migration 0116): a JSON document the
	// controller reads and writes, opaque here, and empty when there was none.
	Stuck       string
	RequestedAt time.Time
	FinishedAt  *time.Time
}

const updateAttemptCols = `id, scope, host_id, from_version, to_version, trigger, requested_by, state, error, rollout_id, backup, rolled_back, requested_at, finished_at, stuck`

func scanUpdateAttempt(sc interface{ Scan(...any) error }) (UpdateAttempt, error) {
	var a UpdateAttempt
	var requested int64
	var finished sql.NullInt64
	var rolledBack bool
	err := sc.Scan(&a.ID, &a.Scope, &a.HostID, &a.FromVersion, &a.ToVersion, &a.Trigger,
		&a.RequestedBy, &a.State, &a.Error, &a.RolloutID, &a.Backup, &rolledBack, &requested, &finished, &a.Stuck)
	a.RequestedAt, a.FinishedAt, a.RolledBack = at(requested), atp(finished), rolledBack
	return a, err
}

// ErrRolloutNotRunning refuses a rollout's step once the rollout has halted,
// ended or never existed. It is checked in the insert's own transaction, so a
// person's cancel that lands after the planner read the rollout still stops
// the host being asked.
var ErrRolloutNotRunning = errors.New("the rollout is no longer running")

// CreateUpdateAttempt records a request and sets its ID, state and RequestedAt.
// A target with an open attempt answers ErrConflict: the partial unique index
// is the rule, so two callers racing cannot both succeed. An attempt that names
// a rollout answers ErrRolloutNotRunning unless that rollout is running.
//
// RequestedAt is the store's clock, unless that is not after the target's
// previous attempt, in which case it is a millisecond after it. The listings
// order a target's attempts by it, it is kept in whole milliseconds, and the id
// that would break a tie is random. Two attempts asked for within one
// millisecond (a person cancelling and asking again, a clock that does not move
// in a test) were therefore ordered by chance, and "the host's latest attempt"
// was sometimes the one before. A clock that was put back is treated the same
// way, for the same reason.
func (s *Store) CreateUpdateAttempt(ctx context.Context, a *UpdateAttempt) error {
	switch {
	case a.Scope != UpdateScopeController && a.Scope != UpdateScopeHost:
		return fmt.Errorf("update attempt scope %q is neither %q nor %q", a.Scope, UpdateScopeController, UpdateScopeHost)
	case a.Scope == UpdateScopeHost && a.HostID == "":
		return fmt.Errorf("an update attempt for a host must name the host")
	case a.Scope == UpdateScopeController && a.HostID != "":
		return fmt.Errorf("an update attempt for the controller cannot name a host (%s)", a.HostID)
	case a.Trigger != UpdateTriggerManual && a.Trigger != UpdateTriggerAuto:
		return fmt.Errorf("update attempt trigger %q is neither %q nor %q", a.Trigger, UpdateTriggerManual, UpdateTriggerAuto)
	case strings.TrimSpace(a.ToVersion) == "":
		// Every ending is judged against the release the attempt asked for, so a
		// row without one could never be seen to have arrived.
		return fmt.Errorf("an update attempt must name the release it is for")
	}
	a.ID = NewID(PrefixUpdateAttempt)
	a.State, a.Error, a.FinishedAt = UpdateRequested, "", nil
	a.RequestedAt = s.Now()
	return s.tx(ctx, func(tx *sql.Tx) error {
		if a.RolloutID != "" {
			var running int
			err := tx.QueryRowContext(ctx, `SELECT COUNT(*) FROM update_rollouts WHERE id = ? AND state = ?`,
				a.RolloutID, RolloutRunning).Scan(&running)
			if err != nil {
				return err
			}
			if running == 0 {
				return fmt.Errorf("%w: %s", ErrRolloutNotRunning, a.RolloutID)
			}
		}
		// Read inside the transaction, under the single writer, so no other
		// attempt of the target can be recorded between this and the insert.
		var newest sql.NullInt64
		if err := tx.QueryRowContext(ctx, `SELECT MAX(requested_at) FROM update_attempts
			WHERE scope = ? AND host_id = ?`, a.Scope, a.HostID).Scan(&newest); err != nil {
			return err
		}
		if newest.Valid && ms(a.RequestedAt) <= newest.Int64 {
			a.RequestedAt = at(newest.Int64 + 1)
		}
		_, err := tx.ExecContext(ctx, `INSERT INTO update_attempts (`+updateAttemptCols+`)
			VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, '', 0, ?, NULL, '')`,
			a.ID, a.Scope, a.HostID, a.FromVersion, a.ToVersion, a.Trigger, a.RequestedBy,
			a.State, a.Error, a.RolloutID, ms(a.RequestedAt))
		return wrapWrite(err)
	})
}

// FinishUpdateAttempt ends an open attempt in state, one of the four end
// states, and reports whether it did. It is false when the attempt was not
// open (already finished, or unknown): the first ending stands, so a late
// result or a timeout racing the helper's answer cannot rewrite it.
func (s *Store) FinishUpdateAttempt(ctx context.Context, id, state, errText string) (bool, error) {
	switch state {
	case UpdateSucceeded, UpdateFailed, UpdateTimedOut, UpdateCancelled:
	default:
		return false, fmt.Errorf("%q does not end an update attempt", state)
	}
	res, err := s.exec(ctx, `UPDATE update_attempts SET state = ?, error = ?, finished_at = ?
		WHERE id = ? AND state = ?`, state, errText, ms(s.Now()), id, UpdateRequested)
	if err != nil {
		return false, err
	}
	n, err := res.RowsAffected()
	return n == 1, err
}

// SetUpdateAttemptFacts records what the helper reported about the engine's
// run on an attempt: the copy it took before it changed anything, and whether
// it rolled back. It is written after the attempt has ended, so a write that
// fails loses only the facts and never the ending.
func (s *Store) SetUpdateAttemptFacts(ctx context.Context, id, backup string, rolledBack bool) error {
	_, err := s.exec(ctx, `UPDATE update_attempts SET backup = ?, rolled_back = ? WHERE id = ?`, backup, rolledBack, id)
	return err
}

// SetUpdateAttemptStuck records what was found wrong with the update helper
// while the attempt was handed over. Like the facts above it is written apart
// from the ending, so a write that fails loses only the record.
func (s *Store) SetUpdateAttemptStuck(ctx context.Context, id, stuck string) error {
	_, err := s.exec(ctx, `UPDATE update_attempts SET stuck = ? WHERE id = ?`, stuck, id)
	return err
}

// OpenUpdateAttempts returns every attempt still waiting on its target,
// oldest first.
func (s *Store) OpenUpdateAttempts(ctx context.Context) ([]UpdateAttempt, error) {
	return s.queryUpdateAttempts(ctx, `SELECT `+updateAttemptCols+` FROM update_attempts
		WHERE state = ? ORDER BY requested_at, id`, UpdateRequested)
}

// ListUpdateAttempts returns attempts newest first. An empty scope matches
// every scope and an empty hostID every target; limit is capped at 500, and
// 50 stands for a limit of 0 or less.
//
// Within one target that is the order they were asked for, which
// CreateUpdateAttempt guarantees. Attempts of different targets can share a
// millisecond, and then only their random ids tell them apart.
func (s *Store) ListUpdateAttempts(ctx context.Context, scope, hostID string, limit int) ([]UpdateAttempt, error) {
	if limit <= 0 {
		limit = 50
	}
	limit = min(limit, 500)
	return s.queryUpdateAttempts(ctx, `SELECT `+updateAttemptCols+` FROM update_attempts
		WHERE (?1 = '' OR scope = ?1) AND (?2 = '' OR host_id = ?2)
		ORDER BY requested_at DESC, id DESC LIMIT ?3`, scope, hostID, limit)
}

// maxAttemptsFor bounds UpdateAttemptsFor. Two tags and two rollouts hold a few
// attempts per machine, since the planner stops after two failures of one tag;
// this is far above any fleet and is there so a fault cannot read the table whole.
const maxAttemptsFor = 5000

// UpdateAttemptsFor returns the attempts, open or ended, that take a machine to
// one of tags or are steps of one of rollouts, newest first.
//
// It is what the planner reads instead of the newest attempts fleet-wide: the
// failures that hand a machine to an operator are the ones to the release it
// would be taken to now, however many other attempts are newer.
func (s *Store) UpdateAttemptsFor(ctx context.Context, tags, rollouts []string) ([]UpdateAttempt, error) {
	var cond []string
	var args []any
	in := func(col string, vals []string) {
		if len(vals) == 0 {
			return
		}
		cond = append(cond, col+" IN ("+strings.TrimSuffix(strings.Repeat("?, ", len(vals)), ", ")+")")
		for _, v := range vals {
			args = append(args, v)
		}
	}
	in("to_version", tags)
	in("rollout_id", rollouts)
	if len(cond) == 0 {
		return nil, nil
	}
	args = append(args, maxAttemptsFor)
	return s.queryUpdateAttempts(ctx, `SELECT `+updateAttemptCols+` FROM update_attempts
		WHERE `+strings.Join(cond, " OR ")+` ORDER BY requested_at DESC, id DESC LIMIT ?`, args...)
}

func (s *Store) queryUpdateAttempts(ctx context.Context, query string, args ...any) ([]UpdateAttempt, error) {
	rows, err := s.read.QueryContext(ctx, query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []UpdateAttempt
	for rows.Next() {
		a, err := scanUpdateAttempt(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, a)
	}
	return out, rows.Err()
}

// PruneUpdateAttempts deletes attempts that finished before the cutoff and
// returns how many went. An open attempt is never pruned however old: it is
// the only record that something is in flight, and the controller's timeout
// closes it, after which it ages like any other.
//
// A failed or timed-out attempt to one of keepFailedTo is kept too. Those are
// the failures that hand a machine to an operator, and losing them to age
// would have the planner ask the machine a third time. Which releases are
// still in question is the caller's to say: the store knows no release rules.
func (s *Store) PruneUpdateAttempts(ctx context.Context, before time.Time, keepFailedTo []string) (int, error) {
	keep := "0"
	args := []any{UpdateRequested, ms(before)}
	if len(keepFailedTo) > 0 {
		keep = `state IN (?, ?) AND to_version IN (` + strings.TrimSuffix(strings.Repeat("?, ", len(keepFailedTo)), ", ") + `)`
		args = append(args, UpdateFailed, UpdateTimedOut)
		for _, tag := range keepFailedTo {
			args = append(args, tag)
		}
	}
	args = append(args, pruneRowBatch)
	n, err := pruneInBatches(ctx, pruneRowBatch, pruneMaxBatches, func(ctx context.Context) (int64, error) {
		res, err := s.exec(ctx, `DELETE FROM update_attempts WHERE id IN
			(SELECT id FROM update_attempts WHERE state <> ? AND finished_at < ? AND NOT (`+keep+`) LIMIT ?)`,
			args...)
		if err != nil {
			return 0, err
		}
		return res.RowsAffected()
	})
	return int(n), err
}

// cancelUpdateAttemptsForHost closes a host's open attempts inside the
// transaction that deletes the host, so no moment exists in which the host is
// gone and its attempt still reads as in flight.
func cancelUpdateAttemptsForHost(ctx context.Context, tx *sql.Tx, now time.Time, hostID string) error {
	_, err := tx.ExecContext(ctx, `UPDATE update_attempts SET state = ?, error = ?, finished_at = ?
		WHERE scope = ? AND host_id = ? AND state = ?`,
		UpdateCancelled, hostGoneReason, ms(now), UpdateScopeHost, hostID, UpdateRequested)
	return err
}

package store

import (
	"context"
	"errors"
	"testing"
	"time"
