// A late or repeated report must not rewrite how an attempt ended: a
// result.json read twice, or a timeout racing the helper's answer, would
// otherwise turn a success into a failure after the planner had acted on it.
func TestFinishingAnAttemptIsMonotonic(t *testing.T) {
	ctx := context.Background()
	s, clock := updateAttemptStore(t)
	a := mustCreateAttempt(t, s, controllerAttempt())

	clock.at = updateAttemptsNow.Add(time.Minute)
	if ok, err := s.FinishUpdateAttempt(ctx, a.ID, UpdateSucceeded, ""); err != nil || !ok {
		t.Fatalf("first FinishUpdateAttempt = %v, %v, want true", ok, err)
	}
	clock.at = updateAttemptsNow.Add(time.Hour)
	if ok, err := s.FinishUpdateAttempt(ctx, a.ID, UpdateTimedOut, "gave up waiting"); err != nil || ok {
		t.Fatalf("second FinishUpdateAttempt = %v, %v, want false", ok, err)
	}

	got, err := s.ListUpdateAttempts(ctx, UpdateScopeController, "", 10)
	if err != nil || len(got) != 1 {
		t.Fatalf("ListUpdateAttempts = %d rows (%v), want 1", len(got), err)
	}
	if got[0].State != UpdateSucceeded || got[0].Error != "" {
		t.Errorf("state = %q, error = %q, want the first finish to stand", got[0].State, got[0].Error)
	}
	if got[0].FinishedAt == nil || !got[0].FinishedAt.Equal(updateAttemptsNow.Add(time.Minute)) {
		t.Errorf("finished at %v, want the moment of the first finish", got[0].FinishedAt)
	}

	if ok, err := s.FinishUpdateAttempt(ctx, "upd_nothere", UpdateFailed, "x"); err != nil || ok {
		t.Errorf("finishing an unknown attempt = %v, %v, want false and no error", ok, err)
	}
	if _, err := s.FinishUpdateAttempt(ctx, a.ID, UpdateRequested, ""); err == nil {
		t.Error("finishing an attempt as requested was accepted; only an end state closes one")
	}
}

// A host that goes away mid-rollout leaves an attempt nobody will ever report
// on. It closes in the same transaction as the delete, so there is no moment
// at which the host is gone and its attempt still reads as in flight.
func TestDeletingAHostClosesItsOpenAttemptsAsCancelled(t *testing.T) {
	ctx := context.Background()
	s, clock := updateAttemptStore(t)
	host := &Host{Name: "vm-1", Capacity: 2, Backends: StringSlice{"docker"}}
	other := &Host{Name: "vm-2", Capacity: 2, Backends: StringSlice{"docker"}}
	for _, h := range []*Host{host, other} {
		if err := s.CreateHost(ctx, h); err != nil {
			t.Fatalf("CreateHost: %v", err)
		}
	}
	gone := mustCreateAttempt(t, s, hostAttempt(host.ID))
	kept := mustCreateAttempt(t, s, hostAttempt(other.ID))
	controller := mustCreateAttempt(t, s, controllerAttempt())

	clock.at = updateAttemptsNow.Add(5 * time.Minute)
	if _, err := s.DeleteHostForgettingMachine(ctx, host.ID, ""); err != nil {
		t.Fatalf("DeleteHostForgettingMachine: %v", err)
	}

	all, err := s.ListUpdateAttempts(ctx, "", "", 10)
	if err != nil || len(all) != 3 {
		t.Fatalf("ListUpdateAttempts = %d rows (%v), want 3", len(all), err)
	}
	byID := map[string]UpdateAttempt{}
	for _, a := range all {
		byID[a.ID] = a
	}
	if a := byID[gone.ID]; a.State != UpdateCancelled || a.Error == "" || a.FinishedAt == nil || !a.FinishedAt.Equal(clock.at) {
		t.Errorf("the deleted host's attempt = %+v, want cancelled with a reason and the delete's time", a)
	}
	if a := byID[kept.ID]; a.State != UpdateRequested {
		t.Errorf("another host's attempt = %q, want it left open", a.State)
	}
	if a := byID[controller.ID]; a.State != UpdateRequested {
		t.Errorf("the controller's attempt = %q, want it left open", a.State)
	}

	// The plain DeleteHost is the same delete.
	if _, err := s.DeleteHost(ctx, other.ID); err != nil {
		t.Fatalf("DeleteHost: %v", err)
	}
	if a, err := s.ListUpdateAttempts(ctx, UpdateScopeHost, other.ID, 10); err != nil || len(a) != 1 || a[0].State != UpdateCancelled {
		t.Errorf("after DeleteHost the second host's attempts = %+v (%v), want one cancelled", a, err)
	}
}

// A host that is removed and joins again under the same id keeps what was
// done to it. A foreign key would either have refused the delete or taken the
// history with it.
func TestAReJoinKeepsAHostsAttemptHistory(t *testing.T) {
	ctx := context.Background()
	s, _ := updateAttemptStore(t)
	host := &Host{Name: "vm-1", Capacity: 2, Backends: StringSlice{"docker"}}
	if err := s.CreateHost(ctx, host); err != nil {
		t.Fatalf("CreateHost: %v", err)
	}
	a := mustCreateAttempt(t, s, hostAttempt(host.ID))
	if ok, err := s.FinishUpdateAttempt(ctx, a.ID, UpdateSucceeded, ""); err != nil || !ok {
		t.Fatalf("FinishUpdateAttempt = %v, %v", ok, err)
	}

	if _, err := s.DeleteHost(ctx, host.ID); err != nil {
		t.Fatalf("DeleteHost: %v", err)
	}
	again := &Host{ID: host.ID, Name: "vm-1", Capacity: 2, Backends: StringSlice{"docker"}}
	if err := s.CreateHost(ctx, again); err != nil {
		t.Fatalf("CreateHost under the same id: %v", err)
	}

	got, err := s.ListUpdateAttempts(ctx, UpdateScopeHost, host.ID, 10)
	if err != nil || len(got) != 1 || got[0].ID != a.ID || got[0].State != UpdateSucceeded {
		t.Fatalf("the re-joined host's history = %+v (%v), want its finished attempt untouched", got, err)
	}
}

// An open attempt is the only record that something is in flight. Age never
// makes it history; the controller's timeout does, by finishing it.
func TestPruneSparesOpenAttempts(t *testing.T) {
	ctx := context.Background()
	s, clock := updateAttemptStore(t)

	open := mustCreateAttempt(t, s, controllerAttempt())
	done := mustCreateAttempt(t, s, hostAttempt("host_a"))
	recent := mustCreateAttempt(t, s, hostAttempt("host_b"))

	clock.at = updateAttemptsNow.Add(time.Minute)
	if ok, err := s.FinishUpdateAttempt(ctx, done.ID, UpdateFailed, "no space left"); err != nil || !ok {
		t.Fatalf("FinishUpdateAttempt = %v, %v", ok, err)
	}
	clock.at = updateAttemptsNow.Add(100 * 24 * time.Hour)
	if ok, err := s.FinishUpdateAttempt(ctx, recent.ID, UpdateSucceeded, ""); err != nil || !ok {
		t.Fatalf("FinishUpdateAttempt = %v, %v", ok, err)
	}

	n, err := s.PruneUpdateAttempts(ctx, updateAttemptsNow.Add(50*24*time.Hour), nil)
	if err != nil || n != 1 {
		t.Fatalf("PruneUpdateAttempts = %d, %v, want the one old finished attempt", n, err)
	}
	left, err := s.ListUpdateAttempts(ctx, "", "", 10)
	if err != nil || len(left) != 2 {
		t.Fatalf("after the prune %d attempts remain (%v), want the open one and the recent one", len(left), err)
	}
	for _, a := range left {
		if a.ID == done.ID {
			t.Errorf("the old finished attempt survived the prune")
		}
	}
	if still, err := s.OpenUpdateAttempts(ctx); err != nil || len(still) != 1 || still[0].ID != open.ID {
		t.Errorf("OpenUpdateAttempts = %+v (%v), want the old open attempt kept", still, err)
	}
}

// Two failures on one release hand a machine to an operator. If age took
// those rows, the planner would count none and ask the host a third time, so a
// failure on a release still in question outlives the window. Everything else
// ages as before: a success, and a failure on a release nobody is asking for.
func TestPruneKeepsTheFailuresOnAReleaseStillInQuestion(t *testing.T) {
	ctx := context.Background()
	s, clock := updateAttemptStore(t)

	end := func(a *UpdateAttempt, state string) *UpdateAttempt {
		t.Helper()
		mustCreateAttempt(t, s, a)
		clock.at = clock.at.Add(time.Minute)
		if ok, err := s.FinishUpdateAttempt(ctx, a.ID, state, "x"); err != nil || !ok {
			t.Fatalf("FinishUpdateAttempt = %v, %v", ok, err)
		}
		return a
	}
	failed := end(hostAttempt("host_a"), UpdateFailed)
	timedOut := end(hostAttempt("host_a"), UpdateTimedOut)
	succeeded := end(hostAttempt("host_b"), UpdateSucceeded)
	older := hostAttempt("host_a")
	older.ToVersion = "v1.3.4"
	older = end(older, UpdateFailed)
	ctl := controllerAttempt()
	ctl.ToVersion = "v1.3.6"
	ctl = end(ctl, UpdateFailed)

	clock.at = updateAttemptsNow.Add(200 * 24 * time.Hour)
	n, err := s.PruneUpdateAttempts(ctx, updateAttemptsNow.Add(100*24*time.Hour), []string{"v1.3.5", "v1.3.6"})
	if err != nil || n != 2 {
		t.Fatalf("PruneUpdateAttempts = %d, %v, want the success and the failure on v1.3.4", n, err)
	}
	left, err := s.ListUpdateAttempts(ctx, "", "", 10)
	if err != nil {
		t.Fatalf("ListUpdateAttempts: %v", err)
	}
	kept := map[string]bool{}
	for _, a := range left {
		kept[a.ID] = true
	}
	for _, a := range []*UpdateAttempt{failed, timedOut, ctl} {
		if !kept[a.ID] {
			t.Errorf("the %s attempt of %q to %s was pruned, want it kept while its release is in question", a.State, a.Scope, a.ToVersion)
		}
	}
	for _, a := range []*UpdateAttempt{succeeded, older} {
		if kept[a.ID] {
			t.Errorf("the %s attempt to %s survived the prune", a.State, a.ToVersion)
		}
	}
}

func TestUpdateAttemptsListNewestFirstForOneTargetOrAll(t *testing.T) {
	ctx := context.Background()
	s, clock := updateAttemptStore(t)

	var ids []string
	for i := 0; i < 3; i++ {
		clock.at = updateAttemptsNow.Add(time.Duration(i) * time.Hour)
		a := mustCreateAttempt(t, s, hostAttempt("host_a"))
		ids = append(ids, a.ID)
		if ok, err := s.FinishUpdateAttempt(ctx, a.ID, UpdateFailed, "x"); err != nil || !ok {
			t.Fatalf("FinishUpdateAttempt = %v, %v", ok, err)
		}
	}
	mustCreateAttempt(t, s, hostAttempt("host_b"))
	mustCreateAttempt(t, s, controllerAttempt())

	got, err := s.ListUpdateAttempts(ctx, UpdateScopeHost, "host_a", 2)
	if err != nil || len(got) != 2 || got[0].ID != ids[2] || got[1].ID != ids[1] {
		t.Fatalf("host_a's two newest = %+v (%v), want %s then %s", got, err, ids[2], ids[1])
	}
	if got, err = s.ListUpdateAttempts(ctx, UpdateScopeHost, "", 10); err != nil || len(got) != 4 {
		t.Errorf("every host attempt = %d rows (%v), want 4", len(got), err)
	}
	if got, err = s.ListUpdateAttempts(ctx, "", "", 10); err != nil || len(got) != 5 {
		t.Errorf("every attempt = %d rows (%v), want 5", len(got), err)
	}
}

// Two attempts of one target can be asked for within a millisecond: a person
// cancelling and asking again, or the planner retrying the moment a failure is
// recorded. requested_at is whole milliseconds and the id that broke the tie is
// random, so the attempt asked for last was listed second about half the time.
// Everything that reads "this host's latest attempt" (an agent's answer, a
// heartbeat's report, the host's card) then judged the new attempt by the old
// one.
func TestTheLatestAttemptOfATargetIsTheLastAskedForEvenWithinOneMillisecond(t *testing.T) {
	ctx := context.Background()
	s, _ := updateAttemptStore(t)

	// The clock never moves, so every ask ties with the one before it. Forty of
	// them leave no room to pass on a coin flip per pair.
	const asks = 40
	latestIs := func(when string, n int, want string) {
		t.Helper()
		got, err := s.ListUpdateAttempts(ctx, UpdateScopeHost, "host_a", 1)
		if err != nil || len(got) != 1 || got[0].ID != want {
			t.Fatalf("ask %d, %s: host_a's latest attempt = %+v (%v), want %s", n, when, got, err, want)
		}
	}
	var asked []string
	for n := 1; n <= asks; n++ {
		a := mustCreateAttempt(t, s, hostAttempt("host_a"))
		asked = append(asked, a.ID)
		latestIs("open", n, a.ID)
		if ok, err := s.FinishUpdateAttempt(ctx, a.ID, UpdateCancelled, "closed elsewhere"); err != nil || !ok {
			t.Fatalf("FinishUpdateAttempt = %v, %v", ok, err)
		}
		latestIs("ended", n, a.ID)
	}

	got, err := s.ListUpdateAttempts(ctx, UpdateScopeHost, "host_a", asks)
	if err != nil || len(got) != asks {
		t.Fatalf("host_a's attempts = %d rows (%v), want %d", len(got), err, asks)
	}
	for i, a := range got {
		if want := asked[asks-1-i]; a.ID != want {
			t.Fatalf("host_a's attempts newest first: position %d is %s, want %s, the order they were asked for reversed", i, a.ID, want)
		}
	}
}

// An attempt keeps the store's clock unless that would not make it the newest of
// its target. Only then is it recorded a millisecond after its predecessor, the
// smallest step the schema stores, so a timestamp is still the time it was asked
// for wherever it can be, and the nudge neither reaches other targets nor
// carries forward.
func TestAnAttemptKeepsTheClockUnlessItWouldNotBeItsTargetsNewest(t *testing.T) {
	ctx := context.Background()
	s, clock := updateAttemptStore(t)
	end := func(a *UpdateAttempt) {
		t.Helper()
		if ok, err := s.FinishUpdateAttempt(ctx, a.ID, UpdateFailed, "x"); err != nil || !ok {
			t.Fatalf("FinishUpdateAttempt = %v, %v", ok, err)
		}
	}
	wantAt := func(what string, a *UpdateAttempt, want time.Time) {
		t.Helper()
		if !a.RequestedAt.Equal(want) {
			t.Errorf("%s was requested at %v, want %v", what, a.RequestedAt, want)
		}
	}

	first := mustCreateAttempt(t, s, hostAttempt("host_a"))
	wantAt("the first attempt of a target", first, updateAttemptsNow)
	end(first)

	// Asked for in the same millisecond as its predecessor, it is the one after.
	second := mustCreateAttempt(t, s, hostAttempt("host_a"))
	wantAt("a second attempt in the same instant", second, updateAttemptsNow.Add(time.Millisecond))

	// Other targets are not behind host_a's attempts, so they keep the clock.
	wantAt("another host's attempt", mustCreateAttempt(t, s, hostAttempt("host_b")), updateAttemptsNow)
	wantAt("the controller's attempt", mustCreateAttempt(t, s, controllerAttempt()), updateAttemptsNow)

	// A later instant is taken as it is: the step above does not carry forward.
	end(second)
	clock.at = updateAttemptsNow.Add(time.Hour)
	third := mustCreateAttempt(t, s, hostAttempt("host_a"))
	wantAt("an attempt asked for an hour later", third, clock.at)

	// A clock that was put back must not bury the newest attempt behind older ones.
	end(third)
	clock.at = updateAttemptsNow
	fourth := mustCreateAttempt(t, s, hostAttempt("host_a"))
	wantAt("an attempt asked for under a clock put back", fourth, third.RequestedAt.Add(time.Millisecond))
	if got, err := s.ListUpdateAttempts(ctx, UpdateScopeHost, "host_a", 1); err != nil || len(got) != 1 || got[0].ID != fourth.ID {
		t.Errorf("host_a's latest attempt = %+v (%v), want %s", got, err, fourth.ID)
	}
}

// The planner reads the attempts to the releases it would take machines to, and
// a rollout's steps, and nothing else: however many other attempts are newer, a
// machine's failures to its release are among what it reads.
func TestUpdateAttemptsForReadsByReleaseAndByRollout(t *testing.T) {
	ctx := context.Background()
	s, clock := updateAttemptStore(t)
	toTarget := mustCreateAttempt(t, s, hostAttempt("host_a"))
	if _, err := s.FinishUpdateAttempt(ctx, toTarget.ID, UpdateFailed, "no"); err != nil {
		t.Fatal(err)
	}
	rollout := mustCreateRollout(t, s, newRollout())
	step := hostAttempt("host_b")
	step.ToVersion, step.RolloutID = "v1.3.4", rollout.ID
	mustCreateAttempt(t, s, step)
	for i := range 3 {
		clock.at = clock.at.Add(time.Minute)
		other := hostAttempt("host_c")
		other.ToVersion = "v1.2." + string(rune('0'+i))
		mustCreateAttempt(t, s, other)
		if _, err := s.FinishUpdateAttempt(ctx, other.ID, UpdateSucceeded, ""); err != nil {
			t.Fatal(err)
		}
	}

	got, err := s.UpdateAttemptsFor(ctx, []string{"v1.3.5"}, []string{rollout.ID})
	if err != nil {
		t.Fatal(err)
	}
	ids := map[string]bool{}
	for _, a := range got {
		ids[a.ID] = true
	}
	if len(got) != 2 || !ids[toTarget.ID] || !ids[step.ID] {
		t.Errorf("UpdateAttemptsFor = %+v, want the attempt to v1.3.5 and the rollout's step", got)
	}
	if got, err := s.UpdateAttemptsFor(ctx, nil, nil); err != nil || len(got) != 0 {
		t.Errorf("UpdateAttemptsFor with nothing asked = %+v, %v, want nothing", got, err)
	}
}

package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"strings"
	"time"
)

// A rollout is running until it ends, halted while it waits for a person, and
// done or cancelled for good. Running and halted are the open states.
const (
	RolloutRunning   = "running"
	RolloutHalted    = "halted"
	RolloutDone      = "done"
	RolloutCancelled = "cancelled"
)

// UpdateRollout is one walk of the fleet to one release. Target is the tag it
// was started for and does not change. FinishedAt is nil while it is open.
type UpdateRollout struct {
	ID           string
	Target       string
	Trigger      string
	State        string
	StartedBy    string
	HaltedReason string
	// HostIDs is the hosts it was started for, and empty for every host that is
	// behind.
	HostIDs StringSlice
	// CancelledBy is the person who cancelled it, and empty when it was not
	// cancelled or the planner did.
	CancelledBy string
	StartedAt   time.Time
	// ResumedAt is when it started or was last resumed.
	ResumedAt  time.Time
	FinishedAt *time.Time
}

const updateRolloutCols = `id, target, trigger, state, started_by, halted_reason, host_ids, cancelled_by, started_at, resumed_at, finished_at`

func scanUpdateRollout(sc interface{ Scan(...any) error }) (UpdateRollout, error) {
	var r UpdateRollout
	var started, resumed int64
	var finished sql.NullInt64
	err := sc.Scan(&r.ID, &r.Target, &r.Trigger, &r.State, &r.StartedBy, &r.HaltedReason, &r.HostIDs, &r.CancelledBy,
		&started, &resumed, &finished)
	r.StartedAt, r.ResumedAt, r.FinishedAt = at(started), at(resumed), atp(finished)
	return r, err
}

// CreateUpdateRollout starts a rollout and sets its ID, state and StartedAt.
// While another is running or halted it answers ErrConflict: the partial
// unique index is the rule, so two callers racing cannot both succeed.
func (s *Store) CreateUpdateRollout(ctx context.Context, r *UpdateRollout) error {
	switch {
	case strings.TrimSpace(r.Target) == "":
		return fmt.Errorf("an update rollout must name the release it is for")
	case r.Trigger != UpdateTriggerManual && r.Trigger != UpdateTriggerAuto:
		return fmt.Errorf("update rollout trigger %q is neither %q nor %q", r.Trigger, UpdateTriggerManual, UpdateTriggerAuto)
	}
	r.ID = NewID(PrefixUpdateRollout)
	r.State, r.HaltedReason, r.CancelledBy, r.FinishedAt = RolloutRunning, "", "", nil
	r.StartedAt = s.Now()
	r.ResumedAt = r.StartedAt
	return s.tx(ctx, func(tx *sql.Tx) error {
		_, err := tx.ExecContext(ctx, `INSERT INTO update_rollouts (`+updateRolloutCols+`)
			VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL)`,
			r.ID, r.Target, r.Trigger, r.State, r.StartedBy, r.HaltedReason, r.HostIDs, r.CancelledBy,
			ms(r.StartedAt), ms(r.ResumedAt))
		return wrapWrite(err)
	})
}

// OpenUpdateRollout returns the rollout that is running or halted, or
// ErrNotFound when the fleet is not being rolled out.
func (s *Store) OpenUpdateRollout(ctx context.Context) (*UpdateRollout, error) {
	r, err := scanUpdateRollout(s.read.QueryRowContext(ctx, `SELECT `+updateRolloutCols+`
		FROM update_rollouts WHERE state IN (?, ?)`, RolloutRunning, RolloutHalted))
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, err
	}
	return &r, nil
}

// HaltUpdateRollout stops a running rollout for a person to look at, with the
// sentence they will read, and reports whether it did. It is false when the
// rollout was not running (halted already, ended, or unknown): the first
// reason stands.
func (s *Store) HaltUpdateRollout(ctx context.Context, id, reason string) (bool, error) {
	return s.moveUpdateRollout(ctx, `UPDATE update_rollouts SET state = ?, halted_reason = ?
		WHERE id = ? AND state = ?`, RolloutHalted, reason, id, RolloutRunning)
}

// ResumeUpdateRollout lets a halted rollout carry on, forgetting why it had
// stopped, and reports whether it did. It is false when the rollout was not
// halted. The resume is stamped, so that the failure it was resumed from is
// not taken as a reason to halt again.
func (s *Store) ResumeUpdateRollout(ctx context.Context, id string) (bool, error) {
	return s.moveUpdateRollout(ctx, `UPDATE update_rollouts SET state = ?, halted_reason = '', resumed_at = ?
		WHERE id = ? AND state = ?`, RolloutRunning, ms(s.Now()), id, RolloutHalted)
}

// FinishUpdateRollout ends an open rollout, running or halted, as done or
// cancelled, and reports whether it did. It is false when the rollout had
// already ended or is unknown: the first ending stands, so a late cancel
// cannot rewrite how a rollout went. A halted rollout keeps the reason it
// stopped for.
func (s *Store) FinishUpdateRollout(ctx context.Context, id, state string) (bool, error) {
	if state != RolloutDone && state != RolloutCancelled {
		return false, fmt.Errorf("%q does not end an update rollout", state)
	}
	return s.moveUpdateRollout(ctx, `UPDATE update_rollouts SET state = ?, finished_at = ?
		WHERE id = ? AND state IN (?, ?)`, state, ms(s.Now()), id, RolloutRunning, RolloutHalted)
}

// CancelUpdateRollout ends an open rollout as cancelled by a person, and
// reports whether it did, as FinishUpdateRollout does. Who is kept, because a
// person's cancel is a decision the planner honours and its own is not.
func (s *Store) CancelUpdateRollout(ctx context.Context, id, by string) (bool, error) {
	if strings.TrimSpace(by) == "" {
		return false, fmt.Errorf("a rollout cancelled by a person must say who")
	}
	return s.moveUpdateRollout(ctx, `UPDATE update_rollouts SET state = ?, cancelled_by = ?, finished_at = ?
		WHERE id = ? AND state IN (?, ?)`, RolloutCancelled, by, ms(s.Now()), id, RolloutRunning, RolloutHalted)
}

// LastEndedUpdateRollout returns the most recent rollout that has ended, or
// ErrNotFound when none has.
func (s *Store) LastEndedUpdateRollout(ctx context.Context) (*UpdateRollout, error) {
	r, err := scanUpdateRollout(s.read.QueryRowContext(ctx, `SELECT `+updateRolloutCols+`
		FROM update_rollouts WHERE state IN (?, ?) ORDER BY finished_at DESC, started_at DESC, id DESC LIMIT 1`,
		RolloutDone, RolloutCancelled))
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, err
	}
	return &r, nil
}

// moveUpdateRollout runs one guarded UPDATE, whose WHERE names the state the
// move is allowed from, and reports whether a row moved.
func (s *Store) moveUpdateRollout(ctx context.Context, query string, args ...any) (bool, error) {
	res, err := s.exec(ctx, query, args...)
	if err != nil {
		return false, err
	}
	n, err := res.RowsAffected()
	return n == 1, err
}

// PruneUpdateRollouts deletes rollouts that ended before the cutoff and
// returns how many went. An open rollout is never pruned however old: it is
// the only record that the fleet is mid-update, and an operator or the
// planner ends it, after which it ages like any other.
//
// A rollout a person cancelled is kept too, while it is the newest that ended
// for its release. It is the record of their decision, which auto honours by
// not starting a rollout to that release again; pruned, the next pass would
// start the one they stopped. Once a later rollout to the same release has
// ended, the cancel is no longer the last word and ages like any other: kept,
// it would become the newest ended rollout again when the later one went, and
// stop auto by itself.
func (s *Store) PruneUpdateRollouts(ctx context.Context, before time.Time) (int, error) {
	n, err := pruneInBatches(ctx, pruneRowBatch, pruneMaxBatches, func(ctx context.Context) (int64, error) {
		res, err := s.exec(ctx, `DELETE FROM update_rollouts WHERE id IN
			(SELECT id FROM update_rollouts WHERE state IN (?, ?) AND finished_at < ?
				AND id NOT IN (SELECT id FROM (SELECT id, state, cancelled_by, ROW_NUMBER() OVER
					(PARTITION BY target ORDER BY finished_at DESC, id DESC) AS newest
					FROM update_rollouts WHERE state IN (?, ?))
					WHERE newest = 1 AND state = ? AND cancelled_by <> '')
			LIMIT ?)`,
			RolloutDone, RolloutCancelled, ms(before), RolloutDone, RolloutCancelled, RolloutCancelled, pruneRowBatch)
		if err != nil {
			return 0, err
		}
		return res.RowsAffected()
	})
	return int(n), err
}

package store

import (
	"context"
	"database/sql"
	"errors"
	"slices"
	"testing"
	"time"
)

func rolloutStore(t *testing.T) (*Store, *updateClock) {
	t.Helper()
	return updateAttemptStore(t)
}

func newRollout() *UpdateRollout {
	return &UpdateRollout{Target: "v1.3.5", Trigger: UpdateTriggerManual, StartedBy: "usr_1"}
}

func mustCreateRollout(t *testing.T, s *Store, r *UpdateRollout) *UpdateRollout {
	t.Helper()
	if err := s.CreateUpdateRollout(context.Background(), r); err != nil {
		t.Fatalf("CreateUpdateRollout: %v", err)
	}
	return r
}

// rolloutByID reads a rollout whatever its state; the store's own readers
// answer for the open one only.
func rolloutByID(s *Store, id string) (UpdateRollout, error) {
	return scanUpdateRollout(s.read.QueryRowContext(context.Background(),
		`SELECT `+updateRolloutCols+` FROM update_rollouts WHERE id = ?`, id))
}

func mustRollout(t *testing.T, s *Store, id string) UpdateRollout {
	t.Helper()
	got, err := rolloutByID(s, id)
	if err != nil {
		t.Fatalf("reading rollout %s: %v", id, err)
	}
	return got
}

// Two rollouts walking the fleet at once would each decide the next host from
// a different picture of it, so a second never starts while one is running or
// halted. The rule is the table's, so it holds however two callers interleave.
func TestOnlyOneRolloutIsOpenAtATime(t *testing.T) {
	ctx := context.Background()
	s, _ := rolloutStore(t)

	first := mustCreateRollout(t, s, newRollout())
	if first.ID == "" || first.State != RolloutRunning || !first.StartedAt.Equal(updateAttemptsNow) || first.FinishedAt != nil {
		t.Fatalf("a created rollout = %+v, want an id, state running, the store's clock and no end", first)
	}

	if err := s.CreateUpdateRollout(ctx, newRollout()); !errors.Is(err, ErrConflict) {
		t.Fatalf("a second rollout while one is running = %v, want ErrConflict", err)
	}

	// A halted rollout is still open: it is waiting for an operator, and a new
	// one must not slip past it.
	if ok, err := s.HaltUpdateRollout(ctx, first.ID, "vm-2 did not come back"); err != nil || !ok {
		t.Fatalf("HaltUpdateRollout = %v, %v, want true", ok, err)
	}
	if err := s.CreateUpdateRollout(ctx, newRollout()); !errors.Is(err, ErrConflict) {
		t.Fatalf("a second rollout while one is halted = %v, want ErrConflict", err)
	}

	// Finished rollouts are history, and the fleet may be rolled out again.
	if ok, err := s.FinishUpdateRollout(ctx, first.ID, RolloutCancelled); err != nil || !ok {
		t.Fatalf("FinishUpdateRollout = %v, %v, want true", ok, err)
	}
	second := mustCreateRollout(t, s, newRollout())
	if second.ID == first.ID {
		t.Errorf("a second rollout reused the id %s", second.ID)
	}
}

func TestARolloutMustNameItsTargetAndHowItStarted(t *testing.T) {
	ctx := context.Background()
	s, _ := rolloutStore(t)
	for name, r := range map[string]*UpdateRollout{
		"no target":      {Trigger: UpdateTriggerManual},
		"a blank target": {Target: "  ", Trigger: UpdateTriggerAuto},
		"an odd trigger": {Target: "v1.3.5", Trigger: "cron"},
	} {
		if err := s.CreateUpdateRollout(ctx, r); err == nil || errors.Is(err, ErrConflict) {
			t.Errorf("%s: CreateUpdateRollout = %v, want a refusal that is not a conflict", name, err)
		}
	}
	if _, err := s.OpenUpdateRollout(ctx); !errors.Is(err, ErrNotFound) {
		t.Errorf("after refused creates OpenUpdateRollout = %v, want ErrNotFound", err)
	}
}

func TestTheOpenRolloutIsTheRunningOrHaltedOne(t *testing.T) {
	ctx := context.Background()
	s, _ := rolloutStore(t)

	if _, err := s.OpenUpdateRollout(ctx); !errors.Is(err, ErrNotFound) {
		t.Fatalf("OpenUpdateRollout with none = %v, want ErrNotFound", err)
	}
	r := mustCreateRollout(t, s, newRollout())
	got, err := s.OpenUpdateRollout(ctx)
	if err != nil || got.ID != r.ID || got.State != RolloutRunning {
		t.Fatalf("OpenUpdateRollout = %+v (%v), want the running rollout", got, err)
	}
	if ok, err := s.HaltUpdateRollout(ctx, r.ID, "vm-2 did not come back"); err != nil || !ok {
		t.Fatalf("HaltUpdateRollout = %v, %v", ok, err)
	}
	got, err = s.OpenUpdateRollout(ctx)
	if err != nil || got.ID != r.ID || got.State != RolloutHalted || got.HaltedReason != "vm-2 did not come back" {
		t.Fatalf("OpenUpdateRollout = %+v (%v), want the halted rollout and its reason", got, err)
	}
	if ok, err := s.FinishUpdateRollout(ctx, r.ID, RolloutDone); err != nil || !ok {
		t.Fatalf("FinishUpdateRollout = %v, %v", ok, err)
	}
	if _, err := s.OpenUpdateRollout(ctx); !errors.Is(err, ErrNotFound) {
		t.Errorf("OpenUpdateRollout after the end = %v, want ErrNotFound", err)
	}
}

// Halting and resuming race the planner's own pass, and an operator's click
// can arrive late. Each is a move out of one named state, so the loser learns
// it lost instead of overwriting the winner.
func TestHaltingAndResumingAreGuardedByState(t *testing.T) {
	ctx := context.Background()
	s, clock := rolloutStore(t)
	r := mustCreateRollout(t, s, newRollout())

	if ok, err := s.ResumeUpdateRollout(ctx, r.ID); err != nil || ok {
		t.Fatalf("resuming a running rollout = %v, %v, want false and no error", ok, err)
	}
	if ok, err := s.HaltUpdateRollout(ctx, r.ID, "vm-2 did not come back"); err != nil || !ok {
		t.Fatalf("first halt = %v, %v, want true", ok, err)
	}
	if ok, err := s.HaltUpdateRollout(ctx, r.ID, "a different reason"); err != nil || ok {
		t.Fatalf("halting a halted rollout = %v, %v, want false and no error", ok, err)
	}
	if got := mustRollout(t, s, r.ID); got.HaltedReason != "vm-2 did not come back" {
		t.Errorf("reason = %q, want the first halt's to stand", got.HaltedReason)
	}
	if ok, err := s.ResumeUpdateRollout(ctx, r.ID); err != nil || !ok {
		t.Fatalf("resuming a halted rollout = %v, %v, want true", ok, err)
	}
	if got := mustRollout(t, s, r.ID); got.State != RolloutRunning || got.HaltedReason != "" {
		t.Errorf("after resume = %+v, want running and no reason left over", got)
	}

	// A finished rollout can be neither halted nor resumed.
	clock.at = updateAttemptsNow.Add(time.Hour)
	if ok, err := s.FinishUpdateRollout(ctx, r.ID, RolloutDone); err != nil || !ok {
		t.Fatalf("FinishUpdateRollout = %v, %v", ok, err)
	}
	if ok, err := s.HaltUpdateRollout(ctx, r.ID, "late"); err != nil || ok {
		t.Errorf("halting a done rollout = %v, %v, want false", ok, err)
	}
	if ok, err := s.ResumeUpdateRollout(ctx, r.ID); err != nil || ok {
		t.Errorf("resuming a done rollout = %v, %v, want false", ok, err)
	}
	if ok, err := s.HaltUpdateRollout(ctx, "rol_nothere", "x"); err != nil || ok {
		t.Errorf("halting an unknown rollout = %v, %v, want false and no error", ok, err)
	}
	if got := mustRollout(t, s, r.ID); got.State != RolloutDone {
		t.Errorf("state = %q, want done to stand", got.State)
	}
}

// A rollout that has ended stays ended: a late cancel from a second tab, or a
// finish from a pass that read the rollout before it ended, must not rewrite
// how it went or when.
func TestFinishingARolloutIsFinal(t *testing.T) {
	ctx := context.Background()
	s, clock := rolloutStore(t)
	r := mustCreateRollout(t, s, newRollout())

	clock.at = updateAttemptsNow.Add(time.Minute)
	if ok, err := s.FinishUpdateRollout(ctx, r.ID, RolloutDone); err != nil || !ok {
		t.Fatalf("first FinishUpdateRollout = %v, %v, want true", ok, err)
	}
	clock.at = updateAttemptsNow.Add(time.Hour)
	if ok, err := s.FinishUpdateRollout(ctx, r.ID, RolloutCancelled); err != nil || ok {
		t.Fatalf("second FinishUpdateRollout = %v, %v, want false", ok, err)
	}
	got := mustRollout(t, s, r.ID)
	if got.State != RolloutDone {
		t.Errorf("state = %q, want the first finish to stand", got.State)
	}
	if got.FinishedAt == nil || !got.FinishedAt.Equal(updateAttemptsNow.Add(time.Minute)) {
		t.Errorf("finished at %v, want the moment of the first finish", got.FinishedAt)
	}

	if ok, err := s.FinishUpdateRollout(ctx, "rol_nothere", RolloutDone); err != nil || ok {
		t.Errorf("finishing an unknown rollout = %v, %v, want false and no error", ok, err)
	}
	for _, state := range []string{RolloutRunning, RolloutHalted, "paused"} {
		if _, err := s.FinishUpdateRollout(ctx, r.ID, state); err == nil {
			t.Errorf("finishing a rollout as %q was accepted; only done or cancelled ends one", state)
		}
	}

	// A halted rollout can be cancelled: that is how an operator gives up on it.
	next := mustCreateRollout(t, s, newRollout())
	if ok, err := s.HaltUpdateRollout(ctx, next.ID, "vm-2 did not come back"); err != nil || !ok {
		t.Fatalf("HaltUpdateRollout = %v, %v", ok, err)
	}
	if ok, err := s.FinishUpdateRollout(ctx, next.ID, RolloutCancelled); err != nil || !ok {
		t.Fatalf("cancelling a halted rollout = %v, %v, want true", ok, err)
	}
	if got := mustRollout(t, s, next.ID); got.State != RolloutCancelled || got.HaltedReason != "vm-2 did not come back" {
		t.Errorf("a cancelled rollout = %+v, want cancelled with the reason it had stopped for kept as history", got)
	}
}

// An open rollout is the only record that the fleet is mid-update. Age never
// makes it history; an operator or the planner does, by finishing it.
func TestPruneSparesAnOpenRollout(t *testing.T) {
	ctx := context.Background()
	s, clock := rolloutStore(t)

	old := mustCreateRollout(t, s, newRollout())
	clock.at = updateAttemptsNow.Add(time.Minute)
	if ok, err := s.FinishUpdateRollout(ctx, old.ID, RolloutDone); err != nil || !ok {
		t.Fatalf("FinishUpdateRollout = %v, %v", ok, err)
	}
	halted := mustCreateRollout(t, s, newRollout())
	if ok, err := s.HaltUpdateRollout(ctx, halted.ID, "vm-2 did not come back"); err != nil || !ok {
		t.Fatalf("HaltUpdateRollout = %v, %v", ok, err)
	}

	clock.at = updateAttemptsNow.Add(200 * 24 * time.Hour)
	n, err := s.PruneUpdateRollouts(ctx, updateAttemptsNow.Add(100*24*time.Hour))
	if err != nil || n != 1 {
		t.Fatalf("PruneUpdateRollouts = %d, %v, want the one finished rollout", n, err)
	}
	if _, err := rolloutByID(s, old.ID); !errors.Is(err, sql.ErrNoRows) {
		t.Errorf("the old finished rollout survived the prune: %v", err)
	}
	if got, err := s.OpenUpdateRollout(ctx); err != nil || got.ID != halted.ID {
		t.Errorf("OpenUpdateRollout = %+v (%v), want the halted rollout kept however old", got, err)
	}

	// Running ones are spared too.
	if ok, err := s.ResumeUpdateRollout(ctx, halted.ID); err != nil || !ok {
		t.Fatalf("ResumeUpdateRollout = %v, %v", ok, err)
	}
	if n, err := s.PruneUpdateRollouts(ctx, updateAttemptsNow.Add(300*24*time.Hour)); err != nil || n != 0 {
		t.Errorf("PruneUpdateRollouts = %d, %v, want a running rollout kept", n, err)
	}
}

// A person's cancel is what stops auto starting the same rollout again. If
// age took that row, the next pass would start the rollout they cancelled, so
// the newest rollout a person cancelled for each release outlives the window.
// An older cancel of the same release, the planner's own and a finished one
// age as before.
func TestPruneKeepsTheNewestCancelByAPersonForEachRelease(t *testing.T) {
	ctx := context.Background()
	s, clock := rolloutStore(t)

	end := func(target, by string) *UpdateRollout {
		t.Helper()
		r := newRollout()
		r.Target = target
		mustCreateRollout(t, s, r)
		clock.at = clock.at.Add(time.Minute)
		var ok bool
		var err error
		switch by {
		case "":
			ok, err = s.FinishUpdateRollout(ctx, r.ID, RolloutCancelled)
		case "done":
			ok, err = s.FinishUpdateRollout(ctx, r.ID, RolloutDone)
		default:
			ok, err = s.CancelUpdateRollout(ctx, r.ID, by)
		}
		if err != nil || !ok {
			t.Fatalf("ending the rollout = %v, %v", ok, err)
		}
		return r
	}
	firstCancel := end("v1.3.5", "usr_1")
	byPlanner := end("v1.3.5", "")
	lastCancel := end("v1.3.5", "usr_2")
	done := end("v1.3.4", "done")
	otherRelease := end("v1.3.4", "usr_1")
	// A cancel that a later rollout to the same release has since ended is no
	// longer the last word on it: kept, it would become the newest ended rollout
	// again once the later one was pruned, and stop auto by itself.
	overtakenCancel := end("v1.3.3", "usr_1")
	overtakenBy := end("v1.3.3", "done")

	clock.at = updateAttemptsNow.Add(200 * 24 * time.Hour)
	n, err := s.PruneUpdateRollouts(ctx, updateAttemptsNow.Add(100*24*time.Hour))
	if err != nil || n != 5 {
		t.Fatalf("PruneUpdateRollouts = %d, %v, want the older cancel, the planner's, the overtaken cancel and the two finished ones", n, err)
	}
	for _, r := range []*UpdateRollout{lastCancel, otherRelease} {
		if _, err := rolloutByID(s, r.ID); err != nil {
			t.Errorf("the newest cancel by a person of %s was pruned: %v", r.Target, err)
		}
	}
	for _, r := range []*UpdateRollout{firstCancel, byPlanner, done, overtakenCancel, overtakenBy} {
		if _, err := rolloutByID(s, r.ID); !errors.Is(err, sql.ErrNoRows) {
			t.Errorf("rollout %s to %s survived the prune: %v", r.ID, r.Target, err)
		}
	}
}

// Attempts are what a rollout is made of, and the page that explains a
// rollout lists them, so each remembers which one asked for it. A lone button
// press has none.
func TestAnAttemptRemembersItsRollout(t *testing.T) {
	ctx := context.Background()
	s, _ := rolloutStore(t)
	r := mustCreateRollout(t, s, newRollout())

	part := hostAttempt("host_a")
	part.RolloutID = r.ID
	mustCreateAttempt(t, s, part)
	alone := mustCreateAttempt(t, s, hostAttempt("host_b"))

	got, err := s.ListUpdateAttempts(ctx, UpdateScopeHost, "host_a", 10)
	if err != nil || len(got) != 1 || got[0].RolloutID != r.ID {
		t.Fatalf("the rollout's attempt = %+v (%v), want it to carry %s", got, err, r.ID)
	}
	got, err = s.ListUpdateAttempts(ctx, UpdateScopeHost, "host_b", 10)
	if err != nil || len(got) != 1 || got[0].ID != alone.ID || got[0].RolloutID != "" {
		t.Fatalf("a button press's attempt = %+v (%v), want no rollout", got, err)
	}
	open, err := s.OpenUpdateAttempts(ctx)
	if err != nil || len(open) != 2 {
		t.Fatalf("OpenUpdateAttempts = %d rows (%v), want 2", len(open), err)
	}
}

// A host that goes away mid-rollout has its attempt cancelled, but the rollout
// is the controller's to judge: it sees the cancelled attempt and halts. The
// delete itself must not decide that.
func TestDeletingAHostLeavesTheRolloutAlone(t *testing.T) {
	ctx := context.Background()
	s, _ := rolloutStore(t)
	host := &Host{Name: "vm-1", Capacity: 2, Backends: StringSlice{"docker"}}
	if err := s.CreateHost(ctx, host); err != nil {
		t.Fatalf("CreateHost: %v", err)
	}
	r := mustCreateRollout(t, s, newRollout())
	a := hostAttempt(host.ID)
	a.RolloutID = r.ID
	mustCreateAttempt(t, s, a)

	if _, err := s.DeleteHostForgettingMachine(ctx, host.ID, ""); err != nil {
		t.Fatalf("DeleteHostForgettingMachine: %v", err)
	}
	if got := mustRollout(t, s, r.ID); got.State != RolloutRunning || got.FinishedAt != nil {
		t.Errorf("after the delete the rollout = %+v, want it still running", got)
	}
	got, err := s.ListUpdateAttempts(ctx, UpdateScopeHost, host.ID, 10)
	if err != nil || len(got) != 1 || got[0].RolloutID != r.ID || got[0].State != UpdateCancelled {
		t.Errorf("the host's attempt = %+v (%v), want cancelled and still naming its rollout", got, err)
	}
}

// A rollout started for named hosts must remember them, or the planner would
// walk it over every host that is behind.
func TestARolloutRemembersTheHostsItWasStartedFor(t *testing.T) {
	s, _ := rolloutStore(t)
	named := newRollout()
	named.HostIDs = StringSlice{"host_b", "host_a"}
	mustCreateRollout(t, s, named)
	if got := mustRollout(t, s, named.ID); !slices.Equal(got.HostIDs, []string{"host_b", "host_a"}) {
		t.Errorf("host ids = %v, want the two it was started for", got.HostIDs)
	}
	if _, err := s.FinishUpdateRollout(context.Background(), named.ID, RolloutDone); err != nil {
		t.Fatal(err)
	}
	every := mustCreateRollout(t, s, newRollout())
	if got := mustRollout(t, s, every.ID); len(got.HostIDs) != 0 {
		t.Errorf("host ids = %v, want none: a rollout of every host behind", got.HostIDs)
	}
}

// The failure a rollout halted on happened before it was resumed; the planner
// reads that from resumed_at, so a resume that did not move it would halt the
// rollout again on the next pass.
func TestResumingARolloutStampsWhenItResumed(t *testing.T) {
	ctx := context.Background()
	s, clock := rolloutStore(t)
	r := mustCreateRollout(t, s, newRollout())
	if got := mustRollout(t, s, r.ID); !got.ResumedAt.Equal(updateAttemptsNow) {
		t.Fatalf("resumed at %v, want the start", got.ResumedAt)
	}
	if ok, err := s.HaltUpdateRollout(ctx, r.ID, "vm-2 did not come back"); err != nil || !ok {
		t.Fatalf("HaltUpdateRollout = %v, %v", ok, err)
	}
	clock.at = updateAttemptsNow.Add(time.Hour)
	if ok, err := s.ResumeUpdateRollout(ctx, r.ID); err != nil || !ok {
		t.Fatalf("ResumeUpdateRollout = %v, %v", ok, err)
	}
	got := mustRollout(t, s, r.ID)
	if !got.ResumedAt.Equal(updateAttemptsNow.Add(time.Hour)) || !got.StartedAt.Equal(updateAttemptsNow) {
		t.Errorf("after the resume started %v and resumed %v, want the start kept and the resume stamped", got.StartedAt, got.ResumedAt)
	}
}

// A person's cancel is a decision auto honours, and the planner's own is not,
// so who cancelled is kept; and the last ended rollout is what the planner
// reads it from.
func TestACancelByAPersonIsRecordedAndTheLastEndedRolloutIsFound(t *testing.T) {
	ctx := context.Background()
	s, clock := rolloutStore(t)
	if _, err := s.LastEndedUpdateRollout(ctx); !errors.Is(err, ErrNotFound) {
		t.Fatalf("LastEndedUpdateRollout with none = %v, want ErrNotFound", err)
	}
	first := mustCreateRollout(t, s, newRollout())
	clock.at = updateAttemptsNow.Add(time.Minute)
	if ok, err := s.FinishUpdateRollout(ctx, first.ID, RolloutCancelled); err != nil || !ok {
		t.Fatalf("FinishUpdateRollout = %v, %v", ok, err)
	}
	second := mustCreateRollout(t, s, newRollout())
	if _, err := s.CancelUpdateRollout(ctx, second.ID, ""); err == nil {
		t.Error("a cancel naming nobody was accepted")
	}
	clock.at = updateAttemptsNow.Add(time.Hour)
	if ok, err := s.CancelUpdateRollout(ctx, second.ID, "alice"); err != nil || !ok {
		t.Fatalf("CancelUpdateRollout = %v, %v", ok, err)
	}
	if ok, err := s.CancelUpdateRollout(ctx, second.ID, "bob"); err != nil || ok {
		t.Errorf("a second cancel = %v, %v, want false: the first ending stands", ok, err)
	}
	got, err := s.LastEndedUpdateRollout(ctx)
	if err != nil || got.ID != second.ID || got.State != RolloutCancelled || got.CancelledBy != "alice" {
		t.Fatalf("LastEndedUpdateRollout = %+v (%v), want the second, cancelled by alice", got, err)
	}
	if got := mustRollout(t, s, first.ID); got.CancelledBy != "" {
		t.Errorf("the planner's cancel recorded %q as who cancelled", got.CancelledBy)
	}
	// An open rollout is not the last ended one.
	mustCreateRollout(t, s, newRollout())
	if got, err := s.LastEndedUpdateRollout(ctx); err != nil || got.ID != second.ID {
		t.Errorf("LastEndedUpdateRollout with one open = %+v (%v), want the second still", got, err)
	}
}

// A rollout's step is written only while the rollout runs. The planner reads
// the rollout and then asks the host, and a person's cancel can land between
// the two; checking in the insert's own transaction means a host is never
// asked to restart for a rollout somebody has just stopped.
func TestARolloutsStepIsRecordedOnlyWhileTheRolloutRuns(t *testing.T) {
	s, _ := rolloutStore(t)
	ctx := context.Background()
	r := mustCreateRollout(t, s, newRollout())

	step := hostAttempt("hst_a")
	step.RolloutID = r.ID
	mustCreateAttempt(t, s, step)
	if _, err := s.FinishUpdateAttempt(ctx, step.ID, UpdateSucceeded, ""); err != nil {
		t.Fatal(err)
	}

	for _, tc := range []struct {
		name string
		move func() (bool, error)
	}{
		{"halted", func() (bool, error) { return s.HaltUpdateRollout(ctx, r.ID, "vm-a did not come back") }},
		{"cancelled", func() (bool, error) { return s.CancelUpdateRollout(ctx, r.ID, "alice") }},
	} {
		if moved, err := tc.move(); err != nil || !moved {
			t.Fatalf("moving the rollout to %s: %v, %v", tc.name, moved, err)
		}
		late := hostAttempt("hst_b")
		late.RolloutID = r.ID
		if err := s.CreateUpdateAttempt(ctx, late); !errors.Is(err, ErrRolloutNotRunning) {
			t.Errorf("a step of a %s rollout: err = %v, want ErrRolloutNotRunning", tc.name, err)
		}
		if open, err := s.OpenUpdateAttempts(ctx); err != nil || len(open) != 0 {
			t.Errorf("a step of a %s rollout left %d open attempt(s) (%v)", tc.name, len(open), err)
		}
	}

	unknown := hostAttempt("hst_c")
	unknown.RolloutID = "rol_nothere"
	if err := s.CreateUpdateAttempt(ctx, unknown); !errors.Is(err, ErrRolloutNotRunning) {
		t.Errorf("a step of a rollout that does not exist: err = %v, want ErrRolloutNotRunning", err)
	}
	// A person's press belongs to no rollout and is not held to one.
	mustCreateAttempt(t, s, hostAttempt("hst_d"))
}

package store

import (
	"context"
	"errors"
	"fmt"
	"math/rand"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"sync/atomic"
	"testing"
	"time"
)

// A reconcile pass records one capacity observation for every pool, so the
// number of writes it makes is the size of the fleet: a hundred pools were a
// hundred transactions, each with its statement parsed afresh, and in a profile
// of a quiet pass at a hundred pools that was a quarter of the pass.
// RecordUsageCapacityBatch takes the same observations as one write. These hold
// it to what recording them one at a time leaves behind, and to being one write.

type capacityRow struct {
	Pool    string
	At      int64
	Blocked int
}

func capacityRows(t testing.TB, s *Store) []capacityRow {
	t.Helper()
	rows, err := s.read.QueryContext(context.Background(), `SELECT pool_id, at, blocked FROM usage_capacity_samples ORDER BY pool_id, at`)
	if err != nil {
		t.Fatalf("reading the capacity samples: %v", err)
	}
	defer rows.Close()
	var out []capacityRow
	for rows.Next() {
		var r capacityRow
		if err := rows.Scan(&r.Pool, &r.At, &r.Blocked); err != nil {
			t.Fatalf("scanning a capacity sample: %v", err)
		}
		out = append(out, r)
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("reading the capacity samples: %v", err)
	}
	return out
}

// randomCapacitySamples is n observations over the given number of pools and
// minutes, at arbitrary seconds and milliseconds so that truncation to the minute
// is exercised, and mostly unblocked so that a blocked observation has to survive
// the unblocked ones that follow it in the same minute and an unblocked minute
// has to stay unblocked.
func randomCapacitySamples(rng *rand.Rand, n, pools, minutes int) []UsageCapacitySample {
	epoch := time.Date(2026, 3, 1, 12, 0, 0, 0, time.UTC)
	out := make([]UsageCapacitySample, n)
	for i := range out {
		out[i] = UsageCapacitySample{
			PoolID:  fmt.Sprintf("pool_%03d", rng.Intn(pools)),
			At:      epoch.Add(time.Duration(rng.Intn(minutes*60*1000)) * time.Millisecond),
			Blocked: rng.Intn(10) == 0,
		}
	}
	return out
}

func recordEachSample(t *testing.T, s *Store, samples []UsageCapacitySample) {
	t.Helper()
	for _, sm := range samples {
		if err := s.RecordUsageCapacity(context.Background(), sm.PoolID, sm.At, sm.Blocked); err != nil {
			t.Fatalf("RecordUsageCapacity: %v", err)
		}
	}
}

// bothKinds reports whether the rows are not all one kind. A comparison of two
// stores means something only if some minutes were observed blocked and some
// never were.
func bothKinds(rows []capacityRow) bool {
	blocked := 0
	for _, r := range rows {
		blocked += r.Blocked
	}
	return blocked > 0 && blocked < len(rows)
}

func TestRecordingUsageCapacityInBatchesLeavesWhatRecordingEachLeaves(t *testing.T) {
	ctx := context.Background()
	rng := rand.New(rand.NewSource(7))
	samples := randomCapacitySamples(rng, 600, 8, 10)

	each, batched := newTestStore(t), newTestStore(t)
	recordEachSample(t, each, samples)
	for rest := samples; len(rest) > 0; {
		n := min(1+rng.Intn(40), len(rest))
		if err := batched.RecordUsageCapacityBatch(ctx, rest[:n]); err != nil {
			t.Fatalf("RecordUsageCapacityBatch of %d: %v", n, err)
		}
		rest = rest[n:]
	}

	got, want := capacityRows(t, batched), capacityRows(t, each)
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("recording in batches left\n%v\nwant what recording each sample leaves\n%v", got, want)
	}
	if len(want) != 8*10 || !bothKinds(want) {
		t.Fatalf("the samples left %d rows; want %d, with blocked and free minutes among them", len(want), 8*10)
	}
}

// More observations than one statement carries are split over several, and the
// split must not show: the same rows, whichever side of a boundary an
// observation fell, including a minute whose observations straddle one.
func TestAUsageCapacityBatchLongerThanOneStatementLeavesWhatRecordingEachLeaves(t *testing.T) {
	ctx := context.Background()
	rng := rand.New(rand.NewSource(11))
	samples := randomCapacitySamples(rng, 2*usageCapacityChunk+500, 40, 6)

	each, batched := newTestStore(t), newTestStore(t)
	recordEachSample(t, each, samples)
	if err := batched.RecordUsageCapacityBatch(ctx, samples); err != nil {
		t.Fatalf("RecordUsageCapacityBatch of %d: %v", len(samples), err)
	}

	got, want := capacityRows(t, batched), capacityRows(t, each)
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("a batch of %d left %d rows that differ from the %d recording each sample leaves", len(samples), len(got), len(want))
	}
	if len(want) != 40*6 || !bothKinds(want) {
		t.Fatalf("the samples left %d rows; want %d, with blocked and free minutes among them", len(want), 40*6)
	}
}

// The reason an observation is a MAX and not a plain overwrite: a pool that was
// held at its limit early in a minute and placed a runner later in it was held
// at its limit that minute, and the analysis counts the minute that way.
func TestAUsageCapacityBatchKeepsABlockedObservationWhateverFollowsIt(t *testing.T) {
	ctx := context.Background()
	at := time.Date(2026, 3, 1, 12, 0, 20, 0, time.UTC)
	for name, blocked := range map[string][]bool{
		"blocked then free": {true, false},
		"free then blocked": {false, true},
		"never blocked":     {false, false},
	} {
		t.Run(name, func(t *testing.T) {
			s := newTestStore(t)
			var batch []UsageCapacitySample
			for i, b := range blocked {
				batch = append(batch, UsageCapacitySample{PoolID: "pool_a", At: at.Add(time.Duration(i) * time.Second), Blocked: b})
			}
			if err := s.RecordUsageCapacityBatch(ctx, batch); err != nil {
				t.Fatalf("RecordUsageCapacityBatch: %v", err)
			}
			rows := capacityRows(t, s)
			want := 0
			for _, b := range blocked {
				if b {
					want = 1
				}
			}
			if len(rows) != 1 || rows[0].Blocked != want || rows[0].At != ms(at.Truncate(time.Minute)) {
				t.Fatalf("rows = %+v, want one row for the minute with blocked = %d", rows, want)
			}
		})
	}
}

func TestAUsageCapacityBatchIsOneWrite(t *testing.T) {
	for _, n := range []int{1, 8, usageCapacityChunk, usageCapacityChunk + 1, 2*usageCapacityChunk + 500} {
		t.Run(fmt.Sprintf("n=%d", n), func(t *testing.T) {
			s := newTestStore(t)
			var writes atomic.Int32
			s.ObserveWrites(func(_, _ time.Duration) { writes.Add(1) })

			at := time.Date(2026, 3, 1, 12, 0, 0, 0, time.UTC)
			batch := make([]UsageCapacitySample, n)
			for i := range batch {
				batch[i] = UsageCapacitySample{PoolID: fmt.Sprintf("pool_%04d", i), At: at, Blocked: i%7 == 0}
			}
			if err := s.RecordUsageCapacityBatch(context.Background(), batch); err != nil {
				t.Fatalf("RecordUsageCapacityBatch: %v", err)
			}
			if got := writes.Load(); got != 1 {
				t.Errorf("a batch of %d samples took %d writes, want 1: the writer is taken once for the whole batch", n, got)
			}
			if rows := capacityRows(t, s); len(rows) != n {
				t.Errorf("the batch left %d rows, want %d", len(rows), n)
			}
		})
	}
}

// A pass over no pools has nothing to record, and a store that is not to be
// written to is not asked to take the writer for it.
func TestAnEmptyUsageCapacityBatchWritesNothing(t *testing.T) {
	s := newTestStore(t)
	var writes atomic.Int32
	s.ObserveWrites(func(_, _ time.Duration) { writes.Add(1) })

	for _, batch := range [][]UsageCapacitySample{nil, {}} {
		if err := s.RecordUsageCapacityBatch(context.Background(), batch); err != nil {
			t.Errorf("RecordUsageCapacityBatch(%#v) = %v, want nil", batch, err)
		}
	}
	if got := writes.Load(); got != 0 {
		t.Errorf("empty batches took %d writes, want none", got)
	}
}

// The schema accepts every sample, on purpose: history outlives its pool. So the
// only way a batch fails is the database failing, and a trigger that refuses one
// pool stands in for that. What was written before the failure goes with it,
// whether the refused pool is in the only statement or in a later one, and the
// error carries the cause.
func TestAFailedUsageCapacityBatchRecordsNone(t *testing.T) {
	for name, n := range map[string]int{
		"within one statement": 5,
		"in the last of three": 2*usageCapacityChunk + 500,
	} {
		t.Run(name, func(t *testing.T) {
			s := newTestStore(t)
			ctx := context.Background()
			if _, err := s.exec(ctx, `CREATE TRIGGER refuse_one_pool BEFORE INSERT ON usage_capacity_samples
				WHEN NEW.pool_id = 'pool_refused' BEGIN SELECT RAISE(ABORT, 'refused'); END`); err != nil {
				t.Fatalf("creating the trigger: %v", err)
			}

			at := time.Date(2026, 3, 1, 12, 0, 0, 0, time.UTC)
			batch := make([]UsageCapacitySample, n)
			for i := range batch {
				batch[i] = UsageCapacitySample{PoolID: fmt.Sprintf("pool_%04d", i), At: at}
			}
			batch[n-2] = UsageCapacitySample{PoolID: "pool_refused", At: at, Blocked: true}

			err := s.RecordUsageCapacityBatch(ctx, batch)
			if err == nil {
				t.Fatal("RecordUsageCapacityBatch = nil, want the refusal")
			}
			if !strings.Contains(err.Error(), "refused") {
				t.Errorf("the error is %q, want it to carry the cause", err)
			}
			if rows := capacityRows(t, s); len(rows) != 0 {
				t.Errorf("a failed batch left %d rows, want none: it is all or nothing", len(rows))
			}
		})
	}
}

func TestAUsageCapacityBatchHonoursACancelledContext(t *testing.T) {
	s := newTestStore(t)
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	err := s.RecordUsageCapacityBatch(ctx, []UsageCapacitySample{{PoolID: "pool_a", At: time.Now()}})
	if err == nil {
		t.Fatal("RecordUsageCapacityBatch on a cancelled context = nil, want its error")
	}
	if rows := capacityRows(t, s); len(rows) != 0 {
		t.Errorf("a cancelled batch left %+v", rows)
	}
}

func TestAReadOnlyStoreRefusesAUsageCapacityBatch(t *testing.T) {
	ctx := context.Background()
	path := filepath.Join(t.TempDir(), "zoomies.db")
	rw, err := Open(ctx, Options{Path: path})
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	if err := rw.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}
	if _, err := os.Stat(path); err != nil {
		t.Fatalf("the database was not written: %v", err)
	}
	ro, err := Open(ctx, Options{Path: path, ReadOnly: true})
	if err != nil {
		t.Fatalf("Open read-only: %v", err)
	}
	defer ro.Close()

	for _, n := range []int{1, usageCapacityChunk + 1} {
		batch := make([]UsageCapacitySample, n)
		for i := range batch {
			batch[i] = UsageCapacitySample{PoolID: fmt.Sprintf("pool_%04d", i), At: time.Now()}
		}
		if err := ro.RecordUsageCapacityBatch(ctx, batch); !errors.Is(err, ErrReadOnly) {
			t.Errorf("RecordUsageCapacityBatch of %d on a read-only store = %v, want ErrReadOnly", n, err)
		}
	}
}

package store

import (
	"context"
	"fmt"
	"testing"
	"time"
)

// A reconcile pass records one capacity observation for every pool, once in ten
// seconds. A minute therefore sees one pass that writes a row for each pool and
// five that find those rows already there and change nothing, and this times
// passes at that rhythm, with the observation recorded one write at a time and as
// a batch, for fleets of three sizes. Both end up with the same rows; the
// scenario is checked before anything is timed.
func BenchmarkRecordUsageCapacity(b *testing.B) {
	ctx := context.Background()
	epoch := time.Date(2026, 3, 1, 12, 0, 0, 0, time.UTC)

	for _, n := range []int{4, 20, 100} {
		samples := make([]UsageCapacitySample, n)
		for i := range samples {
			samples[i] = UsageCapacitySample{PoolID: fmt.Sprintf("pool_%03d", i), At: epoch, Blocked: i%5 == 0}
		}
		record := map[string]func(s *Store, at time.Time) error{
			"each": func(s *Store, at time.Time) error {
				for _, sm := range samples {
					if err := s.RecordUsageCapacity(ctx, sm.PoolID, at, sm.Blocked); err != nil {
						return err
					}
				}
				return nil
			},
			"batch": func(s *Store, at time.Time) error {
				for i := range samples {
					samples[i].At = at
				}
				return s.RecordUsageCapacityBatch(ctx, samples)
			},
		}
		for _, way := range []string{"each", "batch"} {
			b.Run(fmt.Sprintf("%s/pools=%d", way, n), func(b *testing.B) {
				s := newTestStore(b)
				if err := record[way](s, epoch); err != nil {
					b.Fatalf("recording a pass: %v", err)
				}
				rows := capacityRows(b, s)
				blocked := 0
				for _, r := range rows {
					blocked += r.Blocked
				}
				if len(rows) != n || blocked != (n+4)/5 {
					b.Fatalf("a pass left %d rows of which %d blocked, want %d rows of which %d", len(rows), blocked, n, (n+4)/5)
				}

				b.ReportAllocs()
				for i := 1; b.Loop(); i++ {
					if err := record[way](s, epoch.Add(time.Duration(i)*10*time.Second)); err != nil {
						b.Fatal(err)
					}
				}
			})
		}
	}
}

package store

import (
	"context"
	"fmt"
	"math/bits"
	"testing"
	"time"
)

// A batch is recorded by the statement of the next width up, because a statement
// as long as the fleet is a new statement for each length and the driver parses
// every one it is handed. The rows past the end of the batch are NULLs the
// statement drops. These hold that to recording exactly the samples it was given,
// whichever side of a width it falls.

func TestAUsageCapacityBatchRecordsExactlyItsSamplesWhateverItsWidth(t *testing.T) {
	sizes := []int{1, 2, 3, 4, 5, 7, 8, 9, 15, 16, 17, 31, 33, 63, 65, 100, 127, 128, 129, 255, 257, 511, 513,
		usageCapacityChunk - 1, usageCapacityChunk, usageCapacityChunk + 1, 2*usageCapacityChunk - 1, 2*usageCapacityChunk + 1}
	for _, n := range sizes {
		t.Run(fmt.Sprintf("n=%d", n), func(t *testing.T) {
			s := newTestStore(t)
			at := time.Date(2026, 3, 1, 12, 0, 0, 0, time.UTC)
			batch := make([]UsageCapacitySample, n)
			for i := range batch {
				batch[i] = UsageCapacitySample{PoolID: fmt.Sprintf("pool_%05d", i), At: at, Blocked: i%3 == 0}
			}
			if err := s.RecordUsageCapacityBatch(context.Background(), batch); err != nil {
				t.Fatalf("RecordUsageCapacityBatch of %d: %v", n, err)
			}
			rows := capacityRows(t, s)
			if len(rows) != n {
				t.Fatalf("a batch of %d left %d rows; want one for each sample and none for the padding", n, len(rows))
			}
			for i, r := range rows {
				// The rows come back in pool order, which is the order they were made in.
				if want := (capacityRow{Pool: batch[i].PoolID, At: at.UnixMilli(), Blocked: boolInt(batch[i].Blocked)}); r != want {
					t.Fatalf("row %d is %+v; want %+v", i, r, want)
				}
			}
		})
	}
}

// An empty pool ID is a value, and NULL is the padding. A filter that took one
// for the other would drop a sample that recording it alone would have kept.
func TestAUsageCapacitySampleWithAnEmptyPoolIDIsStillRecorded(t *testing.T) {
	for _, n := range []int{1, 3, 5} {
		t.Run(fmt.Sprintf("among %d", n), func(t *testing.T) {
			s := newTestStore(t)
			at := time.Date(2026, 3, 1, 12, 0, 0, 0, time.UTC)
			batch := make([]UsageCapacitySample, n)
			for i := range batch {
				batch[i] = UsageCapacitySample{PoolID: fmt.Sprintf("pool_%d", i), At: at}
			}
			batch[n-1].PoolID = ""
			if err := s.RecordUsageCapacityBatch(context.Background(), batch); err != nil {
				t.Fatal(err)
			}
			if rows := capacityRows(t, s); len(rows) != n || rows[0].Pool != "" {
				t.Errorf("a batch of %d with an empty pool ID left %+v; want %d rows, the empty ID among them", n, rows, n)
			}
		})
	}
}

func TestTheWidthOfAUsageCapacityStatementIsTheNextPowerOfTwo(t *testing.T) {
	for n := 1; n <= usageCapacityChunk; n++ {
		q, width := usageCapacityStatement(n)
		if width < n || width/2 >= n || bits.OnesCount(uint(width)) != 1 {
			t.Fatalf("a statement for %d samples has %d rows; want the next power of two", n, width)
		}
		if got, want := countPlaceholders(q.sql), 3*width; got != want {
			t.Fatalf("the statement for %d samples binds %d values; want %d, three for each of its %d rows", n, got, want, width)
		}
	}
}

func countPlaceholders(sql string) int {
	n := 0
	for _, r := range sql {
		if r == '?' {
			n++
		}
	}
	return n
}

package store

import (
	"context"
	"fmt"
	"math"
	"reflect"
	"sort"
	"testing"
	"time"
)

// ledgerFleet is one store run through a hundred simulated days, with the
// names its random IDs stand for so two stores' reports can be compared.
type ledgerFleet struct {
	s     *Store
	now   time.Time
	names map[string]string
}

// simulateLedgerFleet drives a fleet through days of runners -- two pools,
// one priced and one not, on two hosts, some crossing midnight, some whose
// cleanup is never confirmed -- and after each day runs what the controller's
// prune pass runs, with the given retention. Zero keeps everything.
//
// Every instant is a whole multiple of 100 seconds from midnight, so every
// slice of a runner is a whole number of seconds and, at 0.36 an hour, a whole
// number of cents: equality to the second is then a fair thing to ask.
func simulateLedgerFleet(t *testing.T, days int, runners, sessions time.Duration) *ledgerFleet {
	t.Helper()
	ctx := context.Background()
	f := &ledgerFleet{now: time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC), names: map[string]string{"": ""}}
	f.s = newTestStoreAt(t, func() time.Time { return f.now })
	inst, priced, h1 := seedPool(t, f.s)
	pricedPool(t, f.s, priced, 0.36)
	unpriced := &Pool{Name: "unpriced", InstallationID: inst.ID, Labels: StringSlice{"unpriced"}, Backend: BackendDocker,
		MaxRunners: 4, IdleTimeout: Duration(5 * time.Minute), Ephemeral: true, DockerMode: DockerNone, Enabled: true}
	if err := f.s.CreatePool(ctx, unpriced); err != nil {
		t.Fatal(err)
	}
	h2 := &Host{Name: "vm-2", Capacity: 4, Backends: StringSlice{"docker"}}
	if err := f.s.CreateHost(ctx, h2); err != nil {
		t.Fatal(err)
	}
	f.names[inst.ID], f.names[priced.ID], f.names[unpriced.ID] = "installation", "priced", "unpriced"
	f.names[h1.ID], f.names[h2.ID] = "vm-1", "vm-2"

	seed := uint32(20260101)
	next := func(n int) int {
		seed = seed*1664525 + 1013904223
		return int(seed>>8) % n
	}
	day0 := f.now
	job := int64(1)
	for d := range days {
		midnight := day0.Add(time.Duration(d) * 24 * time.Hour)
		for i := range 3 + next(4) {
			start := midnight.Add(time.Duration(next(864)) * 100 * time.Second)
			finish := start.Add(time.Duration(1+next(180)) * 100 * time.Second)
			pool, host := priced, h1
			if next(3) == 0 {
				pool = unpriced
			}
			if next(2) == 0 {
				host = h2
			}
			r := runnerLife(t, f.s, &f.now, pool, host, fmt.Sprintf("d%d-r%d", d, i), start, finish, job)
			job++
			// One in five never has its cleanup confirmed: the host went away
			// or GitHub kept the registration, and the prune is what records it.
			if next(5) != 0 {
				for _, side := range []bool{true, false} {
					if _, err := f.s.ConfirmRunnerCleanup(ctx, r.ID, side); err != nil {
						t.Fatal(err)
					}
				}
			}
		}
		f.now = midnight.Add(24 * time.Hour)
		if _, err := f.s.RollUpUsage(ctx, f.now); err != nil {
			t.Fatal(err)
		}
		if runners > 0 {
			if _, err := f.s.PruneRunners(ctx, f.now.Add(-runners)); err != nil {
				t.Fatal(err)
			}
		}
		if sessions > 0 {
			if _, err := f.s.PruneRunnerSessions(ctx, f.now.Add(-sessions)); err != nil {
				t.Fatal(err)
			}
		}
	}
	// The report is read part way through a day, as it would be.
	f.now = f.now.Add(5 * time.Hour)
	return f
}

// report is a Usage call with every ID replaced by the name it stands for and
// each cost rounded to the cent, so two stores' reports compare directly.
func (f *ledgerFleet) report(t *testing.T, from, to time.Time, group UsageGroup, interval UsageInterval) []UsageRow {
	t.Helper()
	rows, err := f.s.UsageWithInterval(context.Background(), from, to, group, interval)
	if err != nil {
		t.Fatalf("Usage: %v", err)
	}
	for i := range rows {
		name, ok := f.names[rows[i].Key]
		if !ok {
			t.Fatalf("report has a key %q the fleet never made", rows[i].Key)
		}
		rows[i].Key = name
		if c := rows[i].EstimatedCost; c != nil {
			rounded := math.Round(*c*100) / 100
			rows[i].EstimatedCost = &rounded
		}
	}
	sort.Slice(rows, func(i, j int) bool { return rows[i].Key < rows[j].Key })
	return rows
}

// allocation is the part of a report the roll-up answers for: runner time and
// its cost, in total and per bucket. Job figures come from job rows and are
// retention.jobs' to keep, and a job's host is read through its runner's
// session, so neither is the roll-up's to vouch for once the sessions are gone.
type allocation struct {
	Key     string
	Seconds float64
	Cost    *float64
	Buckets []float64
}

func allocations(rows []UsageRow) []allocation {
	var out []allocation
	for _, r := range rows {
		if r.AllocatedRunnerSeconds == nil || *r.AllocatedRunnerSeconds == 0 {
			continue
		}
		a := allocation{Key: r.Key, Seconds: *r.AllocatedRunnerSeconds, Cost: r.EstimatedCost}
		for _, b := range r.History {
			a.Buckets = append(a.Buckets, b.AllocatedSeconds)
		}
		out = append(out, a)
	}
	return out
}

// A 90-day report is what an operator reconciles against a quarter's bill.
// Before the ledger it was computed from runner rows, which retention.runners
// deletes after a week, so it quietly lost every runner-hour older than that.
// With the sessions and the daily roll-up behind it, a report taken with
// seven-day runner retention must match one taken with retention off to the
// second -- and still match once the sessions themselves have been pruned
// down to a fortnight, leaving only the roll-up for the older days.
func TestANinetyDayReportWithAWeekOfRunnerRetentionMatchesOneWithRetentionOff(t *testing.T) {
	const days = 100
	week, fortnight := 7*24*time.Hour, 14*24*time.Hour
	kept := simulateLedgerFleet(t, days, 0, 0)
	pruned := simulateLedgerFleet(t, days, week, 0)
	rolledOnly := simulateLedgerFleet(t, days, week, fortnight)

	// The retention has to have bitten, or the comparison proves nothing.
	var keptRunners, prunedRunners int
	if err := kept.s.read.QueryRow(`SELECT COUNT(*) FROM runners`).Scan(&keptRunners); err != nil {
		t.Fatal(err)
	}
	if err := pruned.s.read.QueryRow(`SELECT COUNT(*) FROM runners`).Scan(&prunedRunners); err != nil {
		t.Fatal(err)
	}
	if prunedRunners*5 > keptRunners {
		t.Fatalf("the pruned fleet still has %d of %d runner rows; retention did not run", prunedRunners, keptRunners)
	}
	oldest, err := rolledOnly.s.RunnerSessions(context.Background(), time.Unix(0, 0), rolledOnly.now.Add(-30*24*time.Hour))
	if err != nil || len(oldest) != 0 {
		t.Fatalf("the fleet with a fortnight of sessions still has %d month-old sessions, %v", len(oldest), err)
	}

	end := kept.now
	today := time.Date(end.Year(), end.Month(), end.Day(), 0, 0, 0, 0, time.UTC)
	windows := []struct {
		name     string
		from, to time.Time
		interval UsageInterval
		// sessionsNeeded marks a window the roll-up cannot serve whole -- a
		// day split by the window's edge or by an hourly bucket -- which is
		// then read from the sessions, and so is complete only while they are.
		sessionsNeeded bool
	}{
		{"ninety whole days", today.Add(-90 * 24 * time.Hour), today, UsageDaily, false},
		{"ninety days to now", end.Add(-90 * 24 * time.Hour), end, UsageAutoInterval, true},
		{"ninety days from midnight to now", today.Add(-90 * 24 * time.Hour), end, UsageDaily, false},
		{"a fortnight of hours", today.Add(-14 * 24 * time.Hour), today, UsageHourly, true},
	}
	for _, w := range windows {
		for _, group := range []UsageGroup{UsageByPool, UsageByHost, UsageByInstallation} {
			want := kept.report(t, w.from, w.to, group, w.interval)
			if len(want) == 0 {
				t.Fatalf("%s by %s: the reference report is empty", w.name, group)
			}
			if got := pruned.report(t, w.from, w.to, group, w.interval); !reflect.DeepEqual(got, want) {
				t.Errorf("%s by %s with a week of runner retention:\n got %+v\nwant %+v", w.name, group, summary(got), summary(want))
			}
			if w.sessionsNeeded {
				continue
			}
			if got := rolledOnly.report(t, w.from, w.to, group, w.interval); !reflect.DeepEqual(allocations(got), allocations(want)) {
				t.Errorf("%s by %s from the roll-up alone:\n got %+v\nwant %+v", w.name, group, summary(got), summary(want))
			}
		}
	}
}

// summary is the part of a row worth reading when two differ.
func summary(rows []UsageRow) []string {
	out := make([]string, 0, len(rows))
	for _, r := range rows {
		alloc, cost := -1.0, -1.0
		if r.AllocatedRunnerSeconds != nil {
			alloc = *r.AllocatedRunnerSeconds
		}
		if r.EstimatedCost != nil {
			cost = *r.EstimatedCost
		}
		out = append(out, fmt.Sprintf("%s: %.0fs, cost %.2f, jobs %d, exec %.0fs, peak %d", r.Key, alloc, cost, r.Jobs, r.JobExecutionSeconds, r.PeakConcurrency))
	}
	return out
}

// A price change is not retrospective. A runner that has a session is priced
// at the rate its session recorded, whether the report reads it from the row,
// the session or the roll-up, so a report across the change agrees with
// itself and with last month's reconciliation.
func TestTheReportPricesARecordedRunnerAtTheRateWhenItRan(t *testing.T) {
	day := time.Date(2026, 5, 10, 0, 0, 0, 0, time.UTC)
	now := day
	s := newTestStoreAt(t, func() time.Time { return now })
	_, pool, host := seedPool(t, s)
	pricedPool(t, s, pool, 0.36)
	confirmed(t, s, &now, pool, host, "before-the-change", day.Add(time.Hour), day.Add(2*time.Hour))
	pricedPool(t, s, pool, 9)
	now = day.Add(3 * time.Hour)

	row := usageRow(t, s, day, day.Add(24*time.Hour), UsageByPool, pool.ID)
	if row.EstimatedCost == nil || math.Abs(*row.EstimatedCost-0.36) > 1e-9 {
		t.Fatalf("cost = %v, want the 0.36 the hour cost when it ran", row.EstimatedCost)
	}
}

