// Anything in request.json that is not provably this attempt's is somebody
// else's business: another attempt's request, a file that is not a request, or a
// link. It is left exactly where it is, and the answer says so.
func TestWithdrawRequestLeavesWhatIsNotItsOwn(t *testing.T) {
	foreign, err := json.Marshal(testRequest("upd_theirs"))
	if err != nil {
		t.Fatal(err)
	}
	for _, tc := range []struct {
		name  string
		plant func(t *testing.T, dir string) bool
	}{
		{"another attempt's request", func(t *testing.T, dir string) bool { writeRaw(t, dir, foreign); return true }},
		{"a file that is not a request", func(t *testing.T, dir string) bool { writeRaw(t, dir, []byte(`{"id":"upd_mine"`)); return true }},
		{"a request over the size limit", func(t *testing.T, dir string) bool {
			writeRaw(t, dir, append([]byte(`{"id":"upd_mine","pad":"`), make([]byte, updates.MaxRequestBytes)...))
			return true
		}},
		{"a folder", func(t *testing.T, dir string) bool {
			if err := os.Mkdir(filepath.Join(dir, RequestFile), 0o750); err != nil {
				t.Fatal(err)
			}
			return true
		}},
		{"a link to this attempt's own request", func(t *testing.T, dir string) bool {
			mine, err := json.Marshal(testRequest("upd_mine"))
			if err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(filepath.Join(dir, "elsewhere.json"), mine, 0o640); err != nil {
				t.Fatal(err)
			}
			return os.Symlink("elsewhere.json", filepath.Join(dir, RequestFile)) == nil
		}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			_, dir := updateFolder(t)
			if !tc.plant(t, dir) {
				t.Skip("cannot make a symbolic link here")
			}
			before, err := os.Lstat(filepath.Join(dir, RequestFile))
			if err != nil {
				t.Fatal(err)
			}
			got, err := WithdrawRequest(dir, "upd_mine")
			if err != nil || got != RequestNotOurs {
				t.Fatalf("WithdrawRequest = %v, %v; want RequestNotOurs", got, err)
			}
			after, err := os.Lstat(filepath.Join(dir, RequestFile))
			if err != nil || !os.SameFile(before, after) || before.Mode() != after.Mode() {
				t.Errorf("request.json was touched: before %v, after %v (%v)", before, after, err)
			}
		})
	}
}

// The folder itself must be the one the installer made, as WriteRequest
// insists: a link in its place is refused, and nothing behind it is removed.
func TestWithdrawRequestRefusesAFolderThatIsALink(t *testing.T) {
	parent, dir := updateFolder(t)
	if err := WriteRequest(dir, testRequest("upd_mine")); err != nil {
		t.Fatal(err)
	}
	link := filepath.Join(parent, "link")
	if err := os.Symlink(dir, link); err != nil {
		t.Skipf("cannot make a symbolic link here: %v", err)
	}
	if _, err := WithdrawRequest(link, "upd_mine"); err == nil {
		t.Error("WithdrawRequest through a linked folder succeeded")
	}
	if got := names(t, dir); !slices.Equal(got, []string{RequestFile}) {
		t.Errorf("the folder holds %v, want the request still there", got)
	}
}

// An agent asked again for an update finds a request waiting, and has to tell
// its own (the same attempt, the same release) from anybody else's before it
// answers. So the waiting request is read as WithdrawRequest reads it: never
// through a link, within the helper's bound, and only as a document the helper
// would accept.
func TestPendingRequestReadsOnlyARequestTheHelperWouldRead(t *testing.T) {
	_, dir := updateFolder(t)
	if _, found, err := PendingRequest(dir); found || err != nil {
		t.Fatalf("an empty folder: found %v, err %v; want nothing found", found, err)
	}
	if _, found, err := PendingRequest(filepath.Join(dir, "gone")); found || err != nil {
		t.Fatalf("no folder: found %v, err %v; want nothing found", found, err)
	}
	if err := WriteRequest(dir, testRequest("upd_mine")); err != nil {
		t.Fatal(err)
	}
	req, found, err := PendingRequest(dir)
	if err != nil || !found || req.ID != "upd_mine" || req.Tag != testRequest("upd_mine").Tag {
		t.Fatalf("PendingRequest = %+v, %v, %v; want the request written", req, found, err)
	}

	for _, tc := range []struct {
		name  string
		plant func(t *testing.T, dir string) bool
	}{
		{"a file that is not a request", func(t *testing.T, dir string) bool { writeRaw(t, dir, []byte(`{"id":"upd_mine"`)); return true }},
		{"a request over the size limit", func(t *testing.T, dir string) bool {
			writeRaw(t, dir, append([]byte(`{"id":"upd_mine","pad":"`), make([]byte, updates.MaxRequestBytes)...))
			return true
		}},
		{"a link to a request", func(t *testing.T, dir string) bool {
			mine, err := json.Marshal(testRequest("upd_mine"))
			if err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(filepath.Join(dir, "elsewhere.json"), mine, 0o640); err != nil {
				t.Fatal(err)
			}
			return os.Symlink("elsewhere.json", filepath.Join(dir, RequestFile)) == nil
		}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			_, dir := updateFolder(t)
			if !tc.plant(t, dir) {
				t.Skip("cannot make a symbolic link here")
			}
			if req, _, err := PendingRequest(dir); err == nil {
				t.Errorf("PendingRequest read %+v from what is not a request", req)
			}
		})
	}
}

package channel

import (
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"time"

	"github.com/eyupio/zoomies/internal/updates"
)

// LockFile is the engine's lock, in the deployment's configuration directory
// and not in the update folder. Its name is the engine's own.
const LockFile = "upgrade.lock"

// ErrRepairPending is returned by WriteRepair while an earlier repair request is
// still in the folder: root has not read it, and a second would only replace it.
var ErrRepairPending = errors.New("a repair request is already waiting for root")

// Facts is what the folder itself says of a stuck helper. The unit states and the
// processes are not in it: they are not files, and the agent asks systemd for them.
type Facts struct {
	RequestPresent bool
	RequestAge     time.Duration
	// RequestID is the waiting request's attempt, empty when it cannot be read.
	RequestID   string
	LockPresent bool
	LockAge     time.Duration
}

// Look reads the folder's request and the configuration directory's lock without
// following a link or opening anything but the request, which is read with the
// helper's own bounds. now is the caller's clock. A configDir of "" means the lock
// is not looked for.
func Look(dir, configDir string, now time.Time) (Facts, error) {
	var f Facts
	root, err := os.OpenRoot(dir)
	if err != nil {
		return f, fmt.Errorf("cannot open the update folder %s: %w", dir, err)
	}
	defer root.Close()
	switch info, err := root.Lstat(RequestFile); {
	case errors.Is(err, fs.ErrNotExist):
	case err != nil:
		return f, fmt.Errorf("cannot look for the request in %s: %w", dir, err)
	default:
		f.RequestPresent, f.RequestAge = true, ageOf(now, info.ModTime())
	}
	// Unreadable is an answer too: the age is what matters, and a request that is
	// not a request is exactly the kind a stuck helper leaves.
	if req, found, err := PendingRequest(dir); err == nil && found {
		f.RequestID = req.ID
	}
	if configDir != "" {
		switch info, err := os.Lstat(filepath.Join(configDir, LockFile)); {
		case errors.Is(err, fs.ErrNotExist):
		case err != nil:
			return f, fmt.Errorf("cannot look for %s in %s: %w", LockFile, configDir, err)
		default:
			f.LockPresent, f.LockAge = true, ageOf(now, info.ModTime())
		}
	}
	return f, nil
}

// ageOf is how long ago t was, never negative: a file stamped in the future by a
// skewed clock is brand new, not old.
func ageOf(now, t time.Time) time.Duration {
	if d := now.Sub(t); d > 0 {
		return d
	}
	return 0
}

// WriteRepair asks root to look at the helper. It is WriteRequest's counterpart
// for the repair units, with the same promises: written under a temporary name and
// renamed, so the path unit never sees half a document, and never making the
// folder.
func WriteRepair(dir string, r updates.RepairRequest) error {
	body, err := json.Marshal(r)
	if err != nil {
		return fmt.Errorf("cannot encode the repair request: %w", err)
	}
	if _, err := updates.ParseRepairRequest(body); err != nil {
		return fmt.Errorf("refusing to write a repair request root would refuse: %w", err)
	}
	root, err := os.OpenRoot(dir)
	if err != nil {
		return fmt.Errorf("cannot open the update folder %s: %w; %s", dir, err, installHint)
	}
	defer root.Close()
	if _, err := root.Lstat(updates.RepairFile); err == nil {
		return fmt.Errorf("%w: %s is still in %s", ErrRepairPending, updates.RepairFile, dir)
	} else if !errors.Is(err, fs.ErrNotExist) {
		return fmt.Errorf("cannot look for an earlier repair request in %s: %w", dir, err)
	}
	tmp, f, err := createTemp(root)
	if err != nil {
		return fmt.Errorf("cannot write in the update folder %s: %w; %s", dir, err, installHint)
	}
	renamed := false
	defer func() {
		if !renamed {
			_ = root.Remove(tmp)
		}
	}()
	if err := f.Chmod(0o640); err != nil {
		_ = f.Close()
		return fmt.Errorf("cannot set the mode of the repair request in %s: %w", dir, err)
	}
	if _, err := f.Write(body); err != nil {
		_ = f.Close()
		return fmt.Errorf("cannot write the repair request in %s: %w", dir, err)
	}
	if err := f.Close(); err != nil {
		return fmt.Errorf("cannot finish the repair request in %s: %w", dir, err)
	}
	if err := root.Rename(tmp, updates.RepairFile); err != nil {
		return fmt.Errorf("cannot put the repair request in place in %s: %w", dir, err)
	}
	renamed = true
	return nil
}

// WithdrawRepair takes back a repair request root has not read, when it is the
// one with this id. It is for an attempt that ends before root answers, so that a
// request nobody wants is not acted on later.
func WithdrawRepair(dir, id string) {
	root, err := os.OpenRoot(dir)
	if err != nil {
		return
	}
	defer root.Close()
	info, err := root.Lstat(updates.RepairFile)
	if err != nil || !info.Mode().IsRegular() {
		return
	}
	f, err := root.Open(updates.RepairFile)
	if err != nil {
		return
	}
	body, err := readOpened(f, info, updates.MaxRepairBytes)
	_ = f.Close()
	if err != nil {
		return
	}
	if r, err := updates.ParseRepairRequest(body); err == nil && r.ID == id {
		_ = root.Remove(updates.RepairFile)
	}
}

// ReadRepairResult reads root's answer. Absent is not an error.
func ReadRepairResult(dir string) (updates.RepairResult, bool, error) {
	var r updates.RepairResult
	found, err := readOptional(filepath.Join(dir, updates.RepairResultFile), updates.MaxRepairBytes, &r)
	if err != nil || !found {
		return updates.RepairResult{}, false, err
	}
	if r.V != updates.WireVersion {
		return updates.RepairResult{}, false, fmt.Errorf("%s is version %d and this release reads version %d", updates.RepairResultFile, r.V, updates.WireVersion)
	}
	return r, true, nil
}

package channel

import (
	"bytes"
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/updates"
)

// The helper's units, as systemctl names them. The installer owns their
// contents; the names are here because the agent that diagnoses and the root
// side that repairs both have to ask about them, and neither imports the other.
const (
	PathUnit    = "zoomies-update.path"
	ServiceUnit = "zoomies-update.service"
)

// RunFunc runs a command and returns what it printed. A command that exits
// non-zero returns its output with the error, because systemctl's is-active and
// is-enabled answer in words on exactly that path.
type RunFunc func(ctx context.Context, name string, args ...string) (string, error)

// systemctlTimeout bounds one question to systemd, so a wedged bus cannot hold
// an update task for ever.
const systemctlTimeout = 10 * time.Second

// RunCommand is the RunFunc that runs the real command.
func RunCommand(ctx context.Context, name string, args ...string) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, systemctlTimeout)
	defer cancel()
	path, err := exec.LookPath(name)
	if err != nil {
		return "", err
	}
	var out bytes.Buffer
	cmd := exec.CommandContext(ctx, path, args...)
	cmd.Stdout, cmd.Stderr = &out, &out
	err = cmd.Run()
	return strings.TrimSpace(out.String()), err
}

// QueryUnit asks systemd what it thinks of one unit. It changes nothing and needs
// no privilege. A question that cannot be asked (no systemctl, no bus) leaves its
// field empty, which Diagnosis reads as not known and never as healthy.
func QueryUnit(ctx context.Context, run RunFunc, unit string) updates.UnitState {
	word := func(verb string) string {
		out, _ := run(ctx, "systemctl", verb, unit)
		out, _, _ = strings.Cut(strings.TrimSpace(out), "\n")
		// A word systemd would not say is an error message, and is not a state.
		if len(out) > 24 || strings.ContainsAny(out, " :/") {
			return ""
		}
		return out
	}
	return updates.UnitState{
		Active:  word("is-active"),
		Enabled: word("is-enabled"),
		Failed:  word("is-failed") == "failed",
	}
}

// Processes reads the command lines of every process this account can see. It is
// best effort: /proc may hide other accounts' processes, in which case an engine
// started by root is not seen here, and root asks again for itself before it
// acts.
func Processes() [][]string {
	dirs, err := filepath.Glob("/proc/[0-9]*/cmdline")
	if err != nil {
		return nil
	}
	var out [][]string
	for _, path := range dirs {
		body, err := os.ReadFile(path)
		if err != nil || len(body) == 0 {
			continue
		}
		out = append(out, strings.Split(strings.TrimRight(string(body), "\x00"), "\x00"))
	}
	return out
}

// Diagnose gathers everything Classify needs. lockDir is the deployment's
// configuration directory, or "" when it is not known.
func Diagnose(ctx context.Context, run RunFunc, dir, lockDir string, now time.Time, procs func() [][]string) (updates.Diagnosis, error) {
	facts, err := Look(dir, lockDir, now)
	if err != nil {
		return updates.Diagnosis{}, err
	}
	if procs == nil {
		procs = Processes
	}
	return updates.Diagnosis{
		RequestPresent: facts.RequestPresent, RequestAge: facts.RequestAge, RequestID: facts.RequestID,
		LockPresent: facts.LockPresent, LockAge: facts.LockAge,
		Path:          QueryUnit(ctx, run, PathUnit),
		Service:       QueryUnit(ctx, run, ServiceUnit),
		EngineRunning: updates.EngineRunning(procs()),
	}, nil
}

package updates

// HelperUnsupported is why the update helper cannot be installed beside a
// service, as a fixed word: the controller says it of itself, an agent sends it
// on its heartbeat, and the status keys its sentence on it. Empty is nothing
// known, which the status shows as a helper not yet installed.
//
// It is a word and not a sentence because it crosses the wire from an agent,
// and the controller does not show an agent's text where every role reads it.
type HelperUnsupported string

const (
	// HelperUnsupportedOS is a host that is not Linux: the helper is a pair of
	// systemd units, and `zoomies updates helper install` refuses anywhere else.
	HelperUnsupportedOS HelperUnsupported = "os"
	// HelperUnsupportedNoSystemd is a Linux host that systemd does not run, which
	// ResolveHelperInstall refuses.
	HelperUnsupportedNoSystemd HelperUnsupported = "no-systemd"
	// HelperUnsupportedRootless is a container under a rootless runtime, which
	// owns what the container writes under another uid than the image's; the
	// helper refuses every request it did not see written by the image's account.
	HelperUnsupportedRootless HelperUnsupported = "rootless"
	// HelperUnsupportedNoSharedFolder is a container that runs no runners, so it
	// does not mount the shared folder the helper on the host reads requests
	// from. The installer offers such a container no helper.
	HelperUnsupportedNoSharedFolder HelperUnsupported = "no-shared-folder"
)

// Known says whether u is one of the causes above. A word an agent sends that
// is not is read as nothing known.
func (u HelperUnsupported) Known() bool {
	switch u {
	case HelperUnsupportedOS, HelperUnsupportedNoSystemd, HelperUnsupportedRootless, HelperUnsupportedNoSharedFolder:
		return true
	}
	return false
}

// HelperHost is what a service can see of the machine it runs on that decides
// whether the update helper could be installed there. The caller gathers it, so
// the decision is a table test and never a look at the real host.
type HelperHost struct {
	// GOOS is the operating system the service runs on.
	GOOS string
	// InContainer says the service runs in a container. The helper is then
	// installed on the host around it, which the container cannot see.
	InContainer bool
	// Systemd says systemd runs this machine. It means nothing in a container,
	// whose host may run systemd whatever the container sees.
	Systemd bool
	// RunsRunners says the service creates runners: an agent always does, a
	// controller when its embedded agent is on. A container mounts the shared
	// folder only then.
	RunsRunners bool
	// RootlessRuntime says the container runtime this service's runners use runs
	// without root. In a container that is the runtime the container runs under.
	RootlessRuntime bool
}

// HelperSupport says why the update helper can never serve the service on h, or
// nothing when it could, or when the service cannot tell.
//
// Only its first two answers are refusals of the installer's, and only the
// systemd one is the installer's own look: `zoomies updates helper install`
// refuses where /run/systemd/system is missing (backend.HasSystemd, which
// agent.LocalHelperHost reads too) and is not built for a platform that is not
// Unix, and an operating system other than Linux always meets one of the two.
// The two container answers are not refusals at all. The installer would put
// the helper on the host around such a container, and it would never act on
// what the container writes: a container that runs no runners mounts no shared
// folder, and the installer only stops offering it one; one under a rootless
// runtime writes as an account the helper refuses. Anything the service cannot
// see (a service that runs as root, a user-namespace-remapped Docker daemon, a
// Linux host around a container that does not run systemd) is left to the
// installer, which says so itself, and the status keeps offering the command.
func HelperSupport(h HelperHost) HelperUnsupported {
	switch {
	case h.GOOS != "linux":
		return HelperUnsupportedOS
	case !h.InContainer && !h.Systemd:
		return HelperUnsupportedNoSystemd
	case h.InContainer && !h.RunsRunners:
		return HelperUnsupportedNoSharedFolder
	case h.InContainer && h.RootlessRuntime:
		return HelperUnsupportedRootless
	}
	return ""
}

package updates

import "testing"

// Each row is a host the installer would refuse the helper on, or one it would
// not, described by what the service can see of it. The status says "manual,
// with the reason" only where the install is certain to refuse; anywhere the
// service cannot tell, it says nothing, and the host is shown as missing a
// helper as before, with the command that installs one.
func TestTheHelperIsUnsupportedOnlyWhereTheInstallerWouldRefuseIt(t *testing.T) {
	for _, tc := range []struct {
		name string
		host HelperHost
		want HelperUnsupported
	}{
		{"a native systemd host", HelperHost{GOOS: "linux", Systemd: true, RunsRunners: true}, ""},
		{"a native systemd controller that runs no runners", HelperHost{GOOS: "linux", Systemd: true}, ""},
		{"macOS", HelperHost{GOOS: "darwin", Systemd: true, RunsRunners: true}, HelperUnsupportedOS},
		{"Windows", HelperHost{GOOS: "windows", RunsRunners: true}, HelperUnsupportedOS},
		{"an operating system nobody named", HelperHost{RunsRunners: true}, HelperUnsupportedOS},
		{"a Linux host that systemd does not run", HelperHost{GOOS: "linux", RunsRunners: true}, HelperUnsupportedNoSystemd},
		// Inside a container the host's systemd cannot be seen, so its absence
		// says nothing about the host the helper would be installed on.
		{"a container that runs runners", HelperHost{GOOS: "linux", InContainer: true, RunsRunners: true}, ""},
		{"a container that runs no runners", HelperHost{GOOS: "linux", InContainer: true}, HelperUnsupportedNoSharedFolder},
		{"a container under a rootless runtime", HelperHost{GOOS: "linux", InContainer: true, RunsRunners: true, RootlessRuntime: true}, HelperUnsupportedRootless},
		// A native service is unaffected by how the runtime its runners use is
		// run: the helper serves the service's own account, not the runtime's.
		{"a native host whose runners use a rootless runtime", HelperHost{GOOS: "linux", Systemd: true, RunsRunners: true, RootlessRuntime: true}, ""},
		// The shared folder is the first thing missing: without it there is
		// nowhere to write a request, whatever owns what the container writes.
		{"a rootless container that runs no runners", HelperHost{GOOS: "linux", InContainer: true, RootlessRuntime: true}, HelperUnsupportedNoSharedFolder},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := HelperSupport(tc.host); got != tc.want {
				t.Errorf("HelperSupport(%+v) = %q, want %q", tc.host, got, tc.want)
			}
		})
	}
}

// The cause crosses the wire from an agent, and the controller keys a sentence
// on it, so a word it does not know has to read as nothing known rather than as
// a reason nobody wrote.
func TestOnlyTheNamedCausesAreKnown(t *testing.T) {
	for _, c := range []HelperUnsupported{HelperUnsupportedOS, HelperUnsupportedNoSystemd, HelperUnsupportedRootless, HelperUnsupportedNoSharedFolder} {
		if !c.Known() {
			t.Errorf("%q is not known", c)
		}
	}
	for _, c := range []HelperUnsupported{"", "OS", "no systemd", "because I said so"} {
		if c.Known() {
			t.Errorf("%q is known", c)
		}
	}
}

package updates

import (
	"cmp"
	"fmt"
	"slices"
	"strconv"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/version"
)

// AttemptTimeout is how long an update may stay open before it is recorded as
// timed out. The engine's own worst case is fifty minutes, so a shorter limit
// would fail an update that was still working.
const AttemptTimeout = 90 * time.Minute

// RetryAfter is how long the planner leaves a machine alone after an update of
// it failed, so that a cause outside Zoomies (a held upgrade.lock, a registry
// that is down) has time to clear before the next try.
const RetryAfter = 30 * time.Minute

// MaxFailuresPerTag is how many failed or timed-out attempts to take one machine
// to one release the planner makes before it leaves that release on that
// machine to a person. Twice is a pattern, and a third try would only add to the
// log.
const MaxFailuresPerTag = 2

// The words the store keeps an attempt's scope and state and a rollout's state
// in. This package may not import the store, so they are written out here as
// well, and the two change together.
const (
	scopeController = "controller"
	scopeHost       = "host"
	attemptOpen     = "requested"
	attemptFailed   = "failed"
	attemptTimedOut = "timed_out"
	rolloutRunning  = "running"
	rolloutHalted   = "halted"
	rolloutCanceled = "cancelled"
	triggerManual   = "manual"
)

// Attempt is one update: the controller's own, or one host's, open or ended.
type Attempt struct {
	ID string
	// Scope is "controller" or "host". HostID names the host for a host's
	// attempt and is empty for the controller's.
	Scope, HostID string
	// To is the tag the attempt takes the machine to. A sentence repeats it only
	// when ValidTag says it is a tag.
	To string
	// State is the store's word for it: "requested" while it is open, then
	// "succeeded", "failed", "timed_out" or "cancelled".
	State string
	// RequestedAt is when it was asked for. Zero is not known, and an attempt
	// whose start is not known is never timed out by arithmetic on it.
	RequestedAt time.Time
	// FinishedAt is when it ended, zero while it is open. Error is why it did
	// not succeed; the planner never repeats it, because the helper's text can
	// name a path on the host and every role reads the sentence.
	FinishedAt time.Time
	Error      string
}

// Rollout is a walk of the fleet to one release: the open one, or the last
// one that ended.
type Rollout struct {
	ID string
	// Target is the tag the rollout was started for.
	Target string
	// Trigger is "manual" for one a person started and "auto" for the planner's.
	Trigger string
	// State is "running" or "halted" while it is open, then "done" or
	// "cancelled".
	State        string
	HaltedReason string
	// HostIDs is the hosts it was started for; nil or empty is every host that
	// is behind.
	HostIDs []string
	// Since is when it started or was last resumed. A failure before it is one
	// an operator has resumed past, and must not halt it again.
	Since time.Time
	// CancelledBy is the person who cancelled it, and empty when it was not
	// cancelled or the planner cancelled it.
	CancelledBy string
}

// HostFacts is what the planner knows of one host.
type HostFacts struct {
	ID, Name string
	// Version is what the host's agent last reported, which for a release binary
	// is "1.3.5" without the v of its tag. Empty is not known.
	Version string
	// GOOS and GOARCH are the host's system, as its agent reported it; empty is
	// not known, and a release is then not held against it.
	GOOS, GOARCH string
	// Embedded is the agent inside the controller, which the controller's own
	// update takes with it.
	Embedded bool
	Healthy  bool
	// CanSelfUpdate and WhyNot are the controller's hostCanSelfUpdate, the one
	// answer the host's card and the planner share. WhyNot is its sentence when
	// the host cannot, and holds no path.
	CanSelfUpdate bool
	WhyNot        string
	ActiveRunners int
	// Open is the host's open attempt, or nil.
	Open *Attempt
	// Ended is the host's recent attempts that have ended, in any order. Every
	// count of failures, and whether the open rollout halts, is worked out from
	// them here, so the rule that stops a rollout on a failure is one a table of
	// snapshots can try.
	Ended []Attempt
}

// HelperState is the update helper beside the controller as the planner reads
// it.
type HelperState string

const (
	// HelperStateReady is installed and answering.
	HelperStateReady HelperState = "ready"
	// HelperStateMissing is not installed, and somebody with root could install
	// it. Any word the planner does not know is read as missing.
	HelperStateMissing HelperState = "missing"
	// HelperStateUnsupported can never be installed beside this controller.
	// Telling a person to install it would send them to a command that only
	// refuses, and waiting for it would be waiting for ever.
	HelperStateUnsupported HelperState = "unsupported"
)

// Snapshot is everything Decide reads, gathered by the controller.
type Snapshot struct {
	// Now is the decision time; nothing here reads a clock.
	Now  time.Time
	Mode Mode
	Soak time.Duration
	// Running is the controller's version as it reports itself.
	Running      string
	GOOS, GOARCH string
	Releases     []Release
	// Helper is the update helper beside the controller. HelperWhyNot is, for
	// an unsupported one, why it can never be installed, as the middle of a
	// sentence that names no path.
	Helper       HelperState
	HelperWhyNot string
	// Fenced says the controller may not act: it is fenced for recovery or does
	// not hold the database's lease.
	Fenced bool
	// HostGraceUntil holds back the time-out of hosts' attempts until this
	// instant, and the zero time holds back nothing. The controller sets it when
	// it stops being fenced: it timed nothing out while fenced, and an agent
	// whose report it held sends it again on its next beat, so a time-out in the
	// moment the fence lifts would close the attempt first and lose the helper's
	// sentence. The controller's own attempt has no agent to wait for.
	HostGraceUntil time.Time
	// Controller is the controller's open attempt, or nil.
	Controller *Attempt
	// ControllerEnded is the controller's recent attempts that have ended, in any
	// order.
	ControllerEnded []Attempt
	// Rollout is the open rollout, or nil. LastRollout is the most recent one
	// that has ended, or nil.
	Rollout     *Rollout
	LastRollout *Rollout
	Hosts       []HostFacts
}

// ActionKind is one thing the controller is asked to do.
type ActionKind string

const (
	// ActionRequestController asks the helper beside the controller to take it
	// to Tag.
	ActionRequestController ActionKind = "request_controller"
	// ActionStartRollout opens a rollout to Tag.
	ActionStartRollout ActionKind = "start_rollout"
	// ActionUpdateHost asks the host HostID to take itself to Tag, as part of the
	// open rollout.
	ActionUpdateHost ActionKind = "update_host"
	// ActionTimeOut records the attempt AttemptID as timed out.
	ActionTimeOut ActionKind = "time_out"
	// ActionHalt halts the open rollout on a failure of the host HostID.
	ActionHalt ActionKind = "halt"
	// ActionFinishRollout closes the open rollout as done.
	ActionFinishRollout ActionKind = "finish_rollout"
	// ActionCancelRollout closes the open rollout as cancelled.
	ActionCancelRollout ActionKind = "cancel_rollout"
)

// Action is one step of a plan, and the reason for it in a person's words.
type Action struct {
	Kind                   ActionKind
	HostID, AttemptID, Tag string
	Reason                 string
}

// Plan is what to do now, in order, and the sentence the status shows.
type Plan struct {
	Actions  []Action
	Sentence string
}

// Decide says what automatic updating does next, and why.
//
// It is pure, as the scheduler's Decide is: time is Snapshot.Now and everything
// else arrives in the snapshot, so a pass that is missed, run twice or run by the
// next process after a restart comes to the same answer, and every edge can be
// tried in a table. Hosts and releases are sorted before they are read, so the
// order rows arrive in never picks a host or changes a word.
//
// The rules, in order; each but the time-outs ends the pass once it decides:
//
//  1. Fenced: nothing at all. A fenced controller may be one of two.
//  2. Time-outs, in every mode: closing an attempt that has had 90 minutes is
//     bookkeeping, not a decision to update, and the controller's own closer
//     does the same. An attempt timed out this pass still counts as open.
//  3. Off (or a mode nothing knows): cancel an open rollout and nothing else.
//     Manual cancels a rollout auto started, since switching to manual is how an
//     operator stops automation, and nothing in manual moves without a click.
//  4. A failure in a running rollout halts it; a halted rollout moves nothing,
//     not even the controller, until an operator resumes or cancels it.
//  5. In auto, the controller: once Choose says its release is due, it goes
//     before any host, or waits with the reason it cannot go. A controller the
//     helper can never be installed beside is left to a person and holds no host
//     back, since waiting for it would be waiting for ever.
//  6. The rollout: carried on in manual or auto, one host at a time, among the
//     hosts it was started for; started only in auto, and not again to a release
//     whose last rollout a person cancelled. Manual never starts anything; a
//     rollout a person started is carried on, because moving it is what they
//     asked for.
//
// The helper's path unit allows five starts in ten minutes. A plan holds at most
// one action that writes a request, an open attempt blocks the next, and
// RetryAfter spaces the retries of a failure, so no machine nears that limit.
func Decide(s Snapshot) Plan {
	if s.Fenced {
		return Plan{Sentence: "This controller is fenced for recovery or does not hold the database's lease, " +
			"so automatic updating starts, halts and closes nothing until it may act again."}
	}
	p := newPlanner(s)
	p.timeOuts()
	if s.Mode != ModeManual && s.Mode != ModeAuto {
		p.off()
		return p.plan
	}
	if s.Mode == ModeManual && p.rollout != nil && p.rollout.Trigger != triggerManual {
		p.stopAuto()
		return p.plan
	}
	if p.halt() || p.halted() {
		return p.plan
	}
	if s.Mode == ModeAuto && p.controller() {
		return p.plan
	}
	if p.rollout != nil {
		p.advance()
	} else {
		p.start()
	}
	return p.plan
}

type planner struct {
	s        Snapshot
	hosts    []HostFacts
	releases []Release
	choice   Target
	// target is the controller's release as a tag, which every host is taken
	// to, or empty when the controller is not on a release.
	target  string
	rollout *Rollout
	// timedOut is the reason given for each attempt this pass timed out.
	timedOut map[string]string
	// controllerNote is what is said, when nothing else is, about a controller
	// release that is due and that only a person can install.
	controllerNote string
	plan           Plan
}

func newPlanner(s Snapshot) *planner {
	p := &planner{s: s, timedOut: map[string]string{}}
	p.hosts = slices.Clone(s.Hosts)
	slices.SortStableFunc(p.hosts, func(a, b HostFacts) int {
		return cmp.Or(cmp.Compare(a.ActiveRunners, b.ActiveRunners), strings.Compare(a.Name, b.Name), strings.Compare(a.ID, b.ID))
	})
	// Ordered by text, which is total, rather than by CompareBuilds, which is not.
	// Choose and the binary check already answer alike whatever the order; the
	// sorted copy keeps any later reader of the list from depending on the order
	// the rows arrived in.
	p.releases = slices.Clone(s.Releases)
	slices.SortStableFunc(p.releases, func(a, b Release) int {
		return cmp.Or(strings.Compare(a.Tag, b.Tag), a.PublishedAt.Compare(b.PublishedAt), strings.Compare(a.URL, b.URL),
			compareBool(a.Prerelease, b.Prerelease), compareBool(a.Draft, b.Draft),
			strings.Compare(strings.Join(a.Assets, "\n"), strings.Join(b.Assets, "\n")))
	})
	p.choice = Choose(ChooseInput{Mode: s.Mode, Soak: s.Soak, Now: s.Now, Running: s.Running, Releases: p.releases, GOOS: s.GOOS, GOARCH: s.GOARCH})
	p.target, _ = HostTarget(s.Running)
	if r := s.Rollout; r != nil && (r.State == rolloutRunning || r.State == rolloutHalted) {
		p.rollout = r
	}
	return p
}

func compareBool(a, b bool) int {
	switch {
	case a == b:
		return 0
	case !a:
		return -1
	}
	return 1
}

func (p *planner) act(a Action)        { p.plan.Actions = append(p.plan.Actions, a) }
func (p *planner) say(sentence string) { p.plan.Sentence = sentence }

// controllerAttempt is the controller's open attempt, or nil. One that is not
// the controller's, or has ended, is not.
func (p *planner) controllerAttempt() *Attempt {
	if a := p.s.Controller; a != nil && a.Scope == scopeController && a.State == attemptOpen {
		return a
	}
	return nil
}

// hostAttempt is h's open attempt, or nil. One for another host, which a host
// re-joined under a new id can leave behind, is not h's to wait on or time out.
func hostAttempt(h HostFacts) *Attempt {
	if a := h.Open; a != nil && a.Scope == scopeHost && a.HostID == h.ID && a.State == attemptOpen {
		return a
	}
	return nil
}

// expired matches the controller's own closer: at exactly 90 minutes an attempt
// is still waited on, so the two never disagree about the minute. An attempt
// whose start is not known is not timed out: the zero time is not when anything
// began, and from it every attempt would look centuries old.
func (p *planner) expired(a *Attempt) bool {
	return !a.RequestedAt.IsZero() && p.s.Now.Sub(a.RequestedAt) > AttemptTimeout
}

func (p *planner) timeOuts() {
	if a := p.controllerAttempt(); a != nil && p.expired(a) {
		reason := fmt.Sprintf("The controller's update to %s did not finish within 90 minutes, so it is recorded as timed out.", tagOr(a.To, "a new release"))
		p.timedOut[a.ID] = reason
		p.act(Action{Kind: ActionTimeOut, AttemptID: a.ID, Reason: reason})
	}
	if p.s.Now.Before(p.s.HostGraceUntil) {
		return
	}
	for _, h := range p.hosts {
		if a := hostAttempt(h); a != nil && p.expired(a) {
			reason := fmt.Sprintf("The update of %s to %s did not finish within 90 minutes, so it is recorded as timed out.", label(h), tagOr(a.To, "a new release"))
			p.timedOut[a.ID] = reason
			p.act(Action{Kind: ActionTimeOut, HostID: h.ID, AttemptID: a.ID, Reason: reason})
		}
	}
}

// off cancels the open rollout. An update already handed to a helper is not the
// planner's to stop: it finishes by itself, and the controller records it.
func (p *planner) off() {
	if p.rollout != nil {
		reason := fmt.Sprintf("Updates are off, so the rollout to %s is cancelled. An update already under way finishes by itself and is recorded.",
			tagOr(p.rollout.Target, "its release"))
		p.act(Action{Kind: ActionCancelRollout, Reason: reason})
		p.say(reason)
		return
	}
	if sentence, open := p.blocked(); open {
		p.say(sentence)
		return
	}
	p.say(p.choice.Reason)
}

// stopAuto cancels, in manual, a rollout auto started.
func (p *planner) stopAuto() {
	reason := fmt.Sprintf("Updating is manual, so the rollout auto started to %s is cancelled and nothing moves without a click. "+
		"An update already under way finishes by itself and is recorded.", tagOr(p.rollout.Target, "its release"))
	p.act(Action{Kind: ActionCancelRollout, Reason: reason})
	p.say(reason)
}

// member says whether the open rollout was started for h: every host, when it
// was started for no host in particular.
func (p *planner) member(h HostFacts) bool {
	return p.rollout == nil || len(p.rollout.HostIDs) == 0 || slices.Contains(p.rollout.HostIDs, h.ID)
}

// failedIn says whether h's update to the rollout's release failed or timed out
// since the rollout started or was last resumed. One before that is a failure
// an operator has resumed past, and halting on it again would make resuming
// impossible.
//
// It does not ask which rollout the attempt belonged to, on purpose: a person's
// press on a host in the rollout that fails is as much a reason to stop and look
// as the rollout's own step failing, so it halts the rollout too.
func (p *planner) failedIn(h HostFacts) bool {
	for _, a := range h.Ended {
		if a.Scope == scopeHost && a.HostID == h.ID && failed(a.State) && !a.FinishedAt.Before(p.rollout.Since) &&
			version.CompareBuilds(a.To, p.rollout.Target) == version.SkewNone {
			return true
		}
	}
	return false
}

func failed(state string) bool { return state == attemptFailed || state == attemptTimedOut }

// failures is how many of the ended attempts of one machine, those that keep
// says are its own, failed or timed out taking it to tag, and when the latest of
// them ended. A failure on the way to another release says nothing about this
// one.
func failures(ended []Attempt, tag string, keep func(Attempt) bool) (n int, last time.Time) {
	for _, a := range ended {
		if !keep(a) || !failed(a.State) || version.CompareBuilds(a.To, tag) != version.SkewNone {
			continue
		}
		n++
		if a.FinishedAt.After(last) {
			last = a.FinishedAt
		}
	}
	return n, last
}

// halt halts a running rollout on the first host, in planning order, whose update
// in it failed. The helper's error is not copied into the reason: it can name a
// path on the host, and the attempt already holds it where only the platform
// role reads it.
func (p *planner) halt() bool {
	if p.rollout == nil || p.rollout.State != rolloutRunning {
		return false
	}
	for _, h := range p.hosts {
		if !p.member(h) || !p.failedIn(h) {
			continue
		}
		reason := fmt.Sprintf("The update of %s to %s did not succeed, so the rollout is halted. Read why on the host's card, then resume the rollout or cancel it.",
			label(h), tagOr(p.rollout.Target, "its release"))
		p.act(Action{Kind: ActionHalt, HostID: h.ID, Reason: reason})
		p.say(reason)
		return true
	}
	return false
}

func (p *planner) halted() bool {
	if p.rollout == nil || p.rollout.State != rolloutHalted {
		return false
	}
	p.say(fmt.Sprintf("The rollout to %s is halted, so nothing is updated until an administrator resumes or cancels it.",
		tagOr(p.rollout.Target, "its release")))
	return true
}

// controller updates the controller once its release is due, and says why it
// cannot when it cannot. Until it is due, hosts follow the release it runs.
func (p *planner) controller() bool {
	t := p.choice
	if t.Replaces || !t.DueBy(p.s.Now) {
		return false
	}
	tag := t.Release.Tag
	if p.s.Helper == HelperStateUnsupported {
		why := strings.TrimSpace(p.s.HelperWhyNot)
		if why == "" {
			why = "this controller runs where the helper's units cannot"
		}
		p.controllerNote = fmt.Sprintf("%s can be taken now, but the update helper cannot be installed here: %s. "+
			"Auto leaves the controller to a person and takes hosts to the release it runs; update the controller on its host with sudo zoomies upgrade.",
			tag, why)
		return false
	}
	if sentence, open := p.blocked(); open {
		p.say(sentence)
		return true
	}
	n, lastFailed := failures(p.s.ControllerEnded, tag, func(a Attempt) bool { return a.Scope == scopeController })
	switch {
	case p.s.Helper != HelperStateReady:
		p.say(fmt.Sprintf("%s can be taken now, but the update helper is not installed beside the controller, so auto waits, and no host is updated before the controller. "+
			"Run sudo zoomies updates helper install on the controller's host.", tag))
	case n >= MaxFailuresPerTag:
		p.say(fmt.Sprintf("Auto stops trying to update the controller to %s after %d failed attempts, and no host is updated before the controller; an operator must act. "+
			"Read why in Settings → Updates, then press Update there or run sudo zoomies upgrade on the controller's host.", tag, n))
	case n > 0 && lastFailed.IsZero():
		p.say(fmt.Sprintf("The controller's last update to %s did not succeed and when it ended is not known, so auto does not try it again; an operator must act. "+
			"Press Update in Settings → Updates, or run sudo zoomies upgrade on the controller's host.", tag))
	case p.waiting(lastFailed):
		p.say(fmt.Sprintf("The controller's last update did not succeed; auto tries %s again in %s.", tag, p.retryIn(lastFailed)))
	default:
		p.act(Action{Kind: ActionRequestController, Tag: tag, Reason: t.Reason})
		p.say(t.Reason)
	}
	return true
}

// advance moves the running rollout on by one host, or ends it.
func (p *planner) advance() {
	r := p.rollout
	if !ValidTarget(r.Target) {
		p.say("The open rollout's target is not a release tag, so it updates nothing. Cancel it and start another.")
		return
	}
	if p.target == "" {
		reason := "The controller no longer runs a release, so there is nothing to take hosts to and the rollout is cancelled."
		p.act(Action{Kind: ActionCancelRollout, Reason: reason})
		p.say(reason)
		return
	}
	skew := CompareTargets(r.Target, p.target)
	if skew == version.SkewDiffers && (version.IsMainBuild(r.Target) || version.IsMainBuild(p.target)) {
		// Main builds have no order, so a rollout to one that is not the
		// controller's is not behind it or past it, only stale.
		reason := fmt.Sprintf("The controller now runs %s, not this rollout's %s, so the rollout is cancelled; hosts follow the controller's build in a new one.", p.target, r.Target)
		p.act(Action{Kind: ActionCancelRollout, Reason: reason})
		p.say(reason)
		return
	}
	switch skew {
	case version.SkewNone:
	case version.SkewBehind:
		next := "hosts follow " + p.target + " in a new one."
		if p.s.Mode != ModeAuto {
			next = "start another to bring hosts to " + p.target + "."
		}
		reason := fmt.Sprintf("The controller now runs %s, newer than this rollout's %s, so the rollout is finished; %s", p.target, r.Target, next)
		p.act(Action{Kind: ActionFinishRollout, Reason: reason})
		p.say(reason)
		return
	default:
		reason := fmt.Sprintf("The controller runs %s, not this rollout's %s, so the rollout is cancelled: a host is never taken past its controller.", p.target, r.Target)
		p.act(Action{Kind: ActionCancelRollout, Reason: reason})
		p.say(reason)
		return
	}
	if sentence, open := p.blocked(); open {
		p.say(sentence)
		return
	}
	sv := p.survey()
	switch {
	case sv.ready != nil:
		p.updateHost(*sv.ready)
	case sv.pending != "":
		p.say(fmt.Sprintf("The rollout to %s is waiting. %s", p.target, sv.pending))
	default:
		reason := fmt.Sprintf("Every host that can be updated from here runs %s, so the rollout is finished.", p.target)
		p.act(Action{Kind: ActionFinishRollout, Reason: reason})
		p.say(withNote(reason, sv.note))
	}
}

// start opens a rollout in auto when a host can be taken to the controller's
// release now. A host that cannot is never the reason one starts, or each pass
// would start one and the next finish it.
func (p *planner) start() {
	if sentence, open := p.blocked(); open {
		p.say(sentence)
		return
	}
	if p.s.Mode != ModeAuto || p.target == "" {
		p.say(p.idle())
		return
	}
	sv := p.survey()
	if sv.ready == nil {
		p.say(withNote(p.idle(), sv.note))
		return
	}
	// A person who cancelled a rollout meant it to stop. Starting the same one
	// on the next pass would undo them ten seconds later.
	if lr := p.s.LastRollout; lr != nil && lr.State == rolloutCanceled && lr.CancelledBy != "" &&
		CompareTargets(lr.Target, p.target) == version.SkewNone {
		p.say(fmt.Sprintf("The rollout to %s was cancelled by hand, so auto will not start another rollout to %s until a newer release is out or somebody starts one.", p.target, p.target))
		return
	}
	hosts := strconv.Itoa(sv.updatable) + " hosts are behind it and are"
	if sv.updatable == 1 {
		hosts = "1 host is behind it and is"
	}
	reason := fmt.Sprintf("Starting a rollout to %s, the release the controller runs: %s updated one at a time.", p.target, hosts)
	p.act(Action{Kind: ActionStartRollout, Tag: p.target, Reason: reason})
	p.say(reason)
}

// idle is what is said when no rollout moves: Choose's sentence, unless the
// controller's release is due and only a person can install it, where Choose's
// "can be taken now" would promise something auto will never do.
func (p *planner) idle() string {
	if p.controllerNote != "" {
		return p.controllerNote
	}
	return p.choice.Reason
}

func (p *planner) updateHost(h HostFacts) {
	p.act(Action{Kind: ActionUpdateHost, HostID: h.ID, Tag: p.target, Reason: fmt.Sprintf(
		"%s is behind %s and runs the fewest jobs (%d) of the hosts that can be updated now, so it goes next.", label(h), p.target, h.ActiveRunners)})
	p.say(fmt.Sprintf("Updating %s to %s. Hosts are updated one at a time, the one running the fewest jobs first.", label(h), p.target))
}

// blocked is the sentence for an open attempt, if there is one: while any is
// open, nothing new starts, so that one machine is updated at a time and the
// controller is never updated under a host's update or the other way round.
func (p *planner) blocked() (string, bool) {
	if a := p.controllerAttempt(); a != nil {
		if reason, ok := p.timedOut[a.ID]; ok {
			return reason, true
		}
		return fmt.Sprintf("The controller is being updated to %s; nothing else starts until that finishes.", tagOr(a.To, "a new release")), true
	}
	for _, h := range p.hosts {
		if a := hostAttempt(h); a != nil {
			if reason, ok := p.timedOut[a.ID]; ok {
				return reason, true
			}
			return fmt.Sprintf("%s is being updated to %s; nothing else starts until that finishes.", label(h), tagOr(a.To, "a new release")), true
		}
	}
	return "", false
}

// survey is where the hosts stand against the controller's release, in planning
// order.
type survey struct {
	// ready is the first host that can be updated now, or nil.
	ready *HostFacts
	// pending is why the first host that can be updated, but not yet, waits.
	pending string
	// note is the first thing worth saying about a host that is not updated.
	note string
	// updatable counts the hosts that can be updated now or soon.
	updatable int
}

func (p *planner) survey() survey {
	var sv survey
	for i := range p.hosts {
		h := &p.hosts[i]
		// A host the open rollout was not started for is not its business, nor a
		// reason for it to wait, nor something to say about it.
		if !p.member(*h) {
			continue
		}
		stand, note := p.assess(*h)
		switch stand {
		case standReady:
			sv.updatable++
			if sv.ready == nil {
				sv.ready = h
			}
		case standPending:
			sv.updatable++
			if sv.pending == "" {
				sv.pending = note
			}
		}
		if sv.note == "" {
			sv.note = note
		}
	}
	return sv
}

type standing int

const (
	standCurrent standing = iota // on the release: nothing to do and nothing to say
	standSkipped                 // left alone, with the reason
	standPending                 // to be updated once a wait is over
	standReady                   // can be updated now
)

// assess places one host. Every comparison with the release goes through
// CompareBuilds, because a release binary says 1.3.5 where its tag says v1.3.5.
func (p *planner) assess(h HostFacts) (standing, string) {
	name := label(h)
	if strings.TrimSpace(h.Version) == "" {
		return standSkipped, name + " has not said which version it runs, so it is left alone."
	}
	// Only a release build can be behind. CompareBuilds reads what follows a
	// hyphen as a pre-release, so a describe build such as 1.3.5-3-gabcdef1,
	// which is ahead of v1.3.5, would otherwise read as behind it and be taken
	// back. The version is the agent's word, so it is not repeated.
	if version.IsMainBuild(p.target) {
		if HostSkew(h.Version, p.target) == version.SkewDiffers {
			return standSkipped, name + " runs a build that is neither a release nor one from main, so it is left alone."
		}
	} else if _, ok := TargetTag(h.Version); !ok {
		return standSkipped, name + " does not run a release build, so automatic updating leaves it alone."
	}
	switch HostSkew(h.Version, p.target) {
	case version.SkewNone:
		return standCurrent, ""
	case version.SkewAhead:
		return standSkipped, fmt.Sprintf("%s runs a later release than the controller's %s and is never taken back.", name, p.target)
	case version.SkewDiffers:
		return standSkipped, name + " runs a build that is not a release, so it is left alone."
	}
	switch {
	case h.Embedded:
		return standSkipped, name + " is the agent inside the controller, so it is updated with the controller."
	case !h.CanSelfUpdate:
		if why := strings.TrimSpace(h.WhyNot); why != "" {
			return standSkipped, name + " cannot be updated from here. " + why
		}
		return standSkipped, name + " cannot be updated from here."
	case !p.carriesBinaryFor(h):
		return standSkipped, fmt.Sprintf("%s carries no binary for the system %s runs on, so it is left alone.", p.target, name)
	}
	n, lastFailed := failures(h.Ended, p.target, func(a Attempt) bool { return a.Scope == scopeHost && a.HostID == h.ID })
	switch {
	case n >= MaxFailuresPerTag:
		return standSkipped, fmt.Sprintf("%d attempts to update %s to %s have failed, so Zoomies stops trying; an operator must act. "+
			"Read why on the host's card, then press Update there or run sudo zoomies upgrade on the host.", n, name, p.target)
	case !h.Healthy:
		return standPending, name + " is not answering, so it is updated once it is back."
	case n > 0 && lastFailed.IsZero():
		return standPending, fmt.Sprintf("%s's last update did not succeed and when it ended is not known, so it is not tried again until an operator updates it from its card.", name)
	case p.waiting(lastFailed):
		return standPending, fmt.Sprintf("%s's last update did not succeed; it is tried again in %s.", name, p.retryIn(lastFailed))
	}
	return standReady, ""
}

// carriesBinaryFor says whether the controller's release, as the list has it,
// has a binary for h's system. A release the list does not hold, or a system not
// known, is not held against the host: the download says, and the attempt fails
// with its reason.
func (p *planner) carriesBinaryFor(h HostFacts) bool {
	if h.GOOS == "" || h.GOARCH == "" {
		return true
	}
	listed := false
	for _, r := range p.releases {
		if !ValidTag(r.Tag) || r.Draft || r.Prerelease || version.CompareBuilds(r.Tag, p.target) != version.SkewNone {
			continue
		}
		if r.Complete(h.GOOS, h.GOARCH) {
			return true
		}
		listed = true
	}
	return !listed
}

func (p *planner) waiting(failedAt time.Time) bool {
	return !failedAt.IsZero() && p.s.Now.Before(failedAt.Add(RetryAfter))
}

func (p *planner) retryIn(failedAt time.Time) span {
	return spanOf(failedAt.Add(RetryAfter).Sub(p.s.Now))
}

// tagOr is tag when it is a release tag and fallback when it is not, so that a
// sentence never repeats text that only claimed to be one.
func tagOr(tag, fallback string) string {
	if ValidTarget(tag) {
		return tag
	}
	return fallback
}

func label(h HostFacts) string {
	if h.Name != "" {
		return h.Name
	}
	return h.ID
}

func withNote(sentence, note string) string {
	if note == "" {
		return sentence
	}
	return sentence + " " + note
}

package updates

import (
	"go/ast"
	"go/build"
	"go/parser"
	"go/token"
	"os"
	"slices"
	"strings"
	"testing"
)

// The rule is only testable to the nanosecond, and only agrees with itself
// between the status and the update, while it reaches for nothing but its
// arguments. Once it imports the store or the controller it can be handed a
// different answer than the one it was asked for, and "which release would be
// taken" is back to being two questions.
func TestTheUpdateRuleImportsOnlyTheStandardLibraryAndVersion(t *testing.T) {
	pkg, err := build.ImportDir(".", 0)
	if err != nil {
		t.Fatalf("reading this package: %v", err)
	}
	if len(pkg.Imports) == 0 {
		t.Fatal("no imports were found at all; the walk is wrong, not the package")
	}
	for _, problem := range impureImports(pkg.Imports) {
		t.Error(problem)
	}
}

// The standard library is not all pure: these are the packages that reach the
// network, the disk, a process, a database or a source of chance, each of which
// makes "which release would be taken" depend on something other than the
// arguments. A package listed here stands for itself and everything beneath it.
var impurePackages = []string{"net", "os", "database/sql", "math/rand", "crypto/rand"}

// pureWithinImpure are packages beneath one of those that only compute: reading
// a URL from a string touches nothing outside it, and a release's address is one.
var pureWithinImpure = []string{"net/url"}

// impureImports names each import the rule may not have, in the words of the
// failure, so the test and its own check read alike.
func impureImports(imports []string) []string {
	var problems []string
	for _, path := range imports {
		first, _, _ := strings.Cut(path, "/")
		if strings.Contains(first, ".") && path != "github.com/eyupio/zoomies/internal/version" {
			problems = append(problems, "internal/updates imports "+path+"; the rule may use the standard library and internal/version, and what needs a file, a command or the clock belongs to its caller")
			continue
		}
		if slices.Contains(pureWithinImpure, path) {
			continue
		}
		for _, banned := range impurePackages {
			if path == banned || strings.HasPrefix(path, banned+"/") {
				problems = append(problems, "internal/updates imports "+path+", which reaches outside its arguments; the network, the disk, a process, a database and a random source belong to the caller")
			}
		}
	}
	return problems
}

// The denylist is only worth having if it would catch what it names, so this
// hands it each of them and a package it must leave alone.
func TestThePurityCheckRefusesWhatReachesOutsideTheArguments(t *testing.T) {
	for _, path := range []string{
		"net", "net/http", "os", "os/exec", "database/sql", "database/sql/driver",
		"math/rand", "math/rand/v2", "crypto/rand",
		"github.com/eyupio/zoomies/internal/store",
	} {
		if got := impureImports([]string{path}); len(got) != 1 {
			t.Errorf("importing %s raised %d complaints, want 1", path, len(got))
		}
	}
	for _, path := range []string{
		"fmt", "sort", "strings", "time", "slices", "regexp", "crypto/sha256", "math", "net/url",
		"github.com/eyupio/zoomies/internal/version",
	} {
		if got := impureImports([]string{path}); len(got) != 0 {
			t.Errorf("importing %s was refused: %v", path, got)
		}
	}
}

// Time arrives as an argument. A read of the clock inside the rule is what
// would let the sentence say a release is due while the decision says it is
// not, a millisecond apart.
func TestTheUpdateRuleNeverReadsTheClock(t *testing.T) {
	entries, err := os.ReadDir(".")
	if err != nil {
		t.Fatalf("reading this package: %v", err)
	}
	files := 0
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
			continue
		}
		files++
		fset := token.NewFileSet()
		file, err := parser.ParseFile(fset, name, nil, parser.SkipObjectResolution)
		if err != nil {
			t.Fatalf("parsing %s: %v", name, err)
		}
		ast.Inspect(file, func(n ast.Node) bool {
			sel, ok := n.(*ast.SelectorExpr)
			if !ok {
				return true
			}
			if pkg, ok := sel.X.(*ast.Ident); ok && pkg.Name == "time" {
				switch sel.Sel.Name {
				case "Now", "Since", "Until", "After", "Sleep", "NewTimer", "NewTicker", "Tick", "AfterFunc":
					t.Errorf("%s: time.%s reads the clock; pass the instant in", fset.Position(sel.Pos()), sel.Sel.Name)
				}
			}
			return true
		})
	}
	if files == 0 {
		t.Fatal("no source files were scanned at all; the walk is wrong, not the rule")
	}
}

// Package updates is the rule for which GitHub release an update mode would
// take, and the sentence that says why.
//
// It is pure: it reads no clock, opens no database and makes no request. Time
// arrives as an argument and releases arrive as a list, which is what lets the
// moments that matter -- a soak ending this second, a release dated tomorrow --
// be tried to the nanosecond instead of waited for, and what lets the status the
// UI shows and the update the controller starts come from one answer instead of
// two that drift apart.
//
// Anything that reads a file, runs a command or asks the clock belongs to the
// code that calls this.
package updates

import (
	"regexp"
	"slices"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/version"
)

// checksumsAsset is the file a release publishes the SHA-256 of each binary in.
// SelfUpdate installs nothing it cannot find an entry for there.
const checksumsAsset = "checksums.txt"

// Release is one entry of GitHub's release list, cut down to what the rule reads.
type Release struct {
	// Tag is the release's tag, such as "v1.3.5". It comes off the network, so
	// nothing here relies on its shape until ValidTag has said it is one.
	Tag string
	// URL is the release's page, so an operator can read its notes before
	// choosing to update.
	URL string
	// PublishedAt is GitHub's published_at, where the soak starts. The zero time
	// means no date was given -- encoding/json yields it for a null, a missing or
	// a zero published_at without an error -- and a release that cannot be dated
	// cannot be soaked, so it is never offered.
	PublishedAt time.Time
	// Prerelease and Draft are GitHub's own flags, honoured whatever the tag
	// looks like: a maintainer can mark a release with a stable-looking tag as
	// either.
	Prerelease, Draft bool
	// Assets are the names of the files attached to the release.
	Assets []string
}

// tagPattern is the only shape of tag an update ever names. A tag is network
// data on its way into a download address and into the request a privileged
// helper reads, so it is matched whole against one strict pattern rather than
// parsed and trusted. Go's $ matches only at the very end of the text, so
// "v1.3.5\n" is refused here where an engine whose $ also matches before a final
// newline would let it through.
var tagPattern = regexp.MustCompile(`^v[0-9]+\.[0-9]+\.[0-9]+$`)

// ValidTag says whether tag is exactly vMAJOR.MINOR.PATCH: no capital V, no
// prerelease suffix, no whitespace, nothing before or after.
func ValidTag(tag string) bool { return tagPattern.MatchString(tag) }

// TargetTag is the tag a host follows: the release its controller is running, or
// false when that build is not one a tag can name.
//
// A host is never sent to "latest", so that an agent is never left ahead of its
// controller. The tag is built from version.Release and not from
// version.InstallTag, which answers "dev" for a build from main -- right for
// choosing an image, wrong here, where the answer has to be a tag the helper
// will accept or nothing. Release binaries report their version without the
// leading v, so the v is put back before the shape is checked.
func TargetTag(running string) (string, bool) {
	release, ok := version.Release(running)
	if !ok {
		return "", false
	}
	tag := "v" + release
	if !ValidTag(tag) {
		return "", false
	}
	return tag, true
}

// DevTag is the wire tag for the rolling build from main. It is the one tag
// besides a release that the helper accepts, and it is what "zoomies upgrade
// --version" already takes for that channel.
const DevTag = "dev"

// ValidWireTag says whether tag may travel in a task or a request: a release
// tag, or the rolling dev channel. The helper runs as root, so this is still a
// closed set and never a pattern.
func ValidWireTag(tag string) bool { return tag == DevTag || ValidTag(tag) }

// ValidTarget says whether target is something a host can be taken to: a
// release tag, or the exact main build the controller runs.
func ValidTarget(target string) bool { return ValidTag(target) || version.IsMainBuild(target) }

// HostTarget is what a host follows: the release its controller runs, or for a
// controller built from main that exact build, so hosts on development builds
// can follow it as hosts on releases follow a release. It is false when the
// controller is neither, such as a local describe build.
func HostTarget(running string) (string, bool) {
	if tag, ok := TargetTag(running); ok {
		return tag, true
	}
	if running = strings.TrimSpace(running); version.IsMainBuild(running) {
		return running, true
	}
	return "", false
}

// WireTag is the tag that asks for target: the release itself, or the dev
// channel for a main build, whose commit the download cannot name.
func WireTag(target string) string {
	if version.IsMainBuild(target) {
		return DevTag
	}
	return target
}

// CompareTargets orders two targets. Releases are ordered by CompareBuilds; two
// main builds are the same or different and never ahead of one another.
func CompareTargets(a, b string) version.Skew {
	if version.IsMainBuild(a) || version.IsMainBuild(b) {
		if strings.TrimSpace(a) == strings.TrimSpace(b) {
			return version.SkewNone
		}
		return version.SkewDiffers
	}
	return version.CompareBuilds(a, b)
}

// HostSkew says how a host's build stands to target. A release target is
// compared as it always was, and only a release build can be behind it. A main
// target is followed exactly: a host on another main build or on a release is
// behind it, since the controller is the authority on what the fleet runs, and
// a build that is neither, such as a local describe build, is Differs and left
// alone so that whatever a developer is testing is not replaced.
func HostSkew(hostVersion, target string) version.Skew {
	if !version.IsMainBuild(target) {
		if _, ok := TargetTag(hostVersion); !ok {
			return version.SkewDiffers
		}
		return version.CompareBuilds(hostVersion, target)
	}
	hostVersion = strings.TrimSpace(hostVersion)
	switch {
	case hostVersion == strings.TrimSpace(target):
		return version.SkewNone
	case version.IsMainBuild(hostVersion):
		return version.SkewBehind
	}
	if _, ok := TargetTag(hostVersion); ok {
		return version.SkewBehind
	}
	return version.SkewDiffers
}

// AssetName is the binary a release publishes for a system, named as
// installer.SelfUpdate downloads it, or empty for a system SelfUpdate does not
// serve. This package may not import the installer, so the name is written out
// here as well, and the two change together.
func AssetName(goos, goarch string) string {
	if goos != "linux" && goos != "darwin" {
		return ""
	}
	return "zoomies_" + goos + "_" + goarch
}

// Complete says whether the release carries what SelfUpdate fetches for this
// system: checksums.txt to verify against, and the binary itself.
//
// A release is public before its files have all been uploaded -- binaries
// first, checksums last -- so for a while there is a tag that exists and cannot
// be installed, and offering it would send a host to a download that fails.
func (r Release) Complete(goos, goarch string) bool {
	asset := AssetName(goos, goarch)
	return asset != "" && slices.Contains(r.Assets, checksumsAsset) && slices.Contains(r.Assets, asset)
}

// eligible is the whole of "a release an update could take": a tag of the strict
// shape, neither a draft nor a prerelease, a publication date, its files, and a
// tag that CompareBuilds can place.
//
// The date matters in every mode, not only auto. The soak is counted from it, so
// a release that cannot be dated cannot be soaked, and it is treated as not yet
// released rather than as old: read as the zero time it would count as public
// for centuries and pass any wait, in the one mode that exists to hold a release
// back. Nothing upstream is certain to refuse it first, because encoding/json
// hands over the zero time without an error.
//
// The last condition is for a number too large for an int, which matches the
// pattern and which CompareBuilds can say nothing about. Ranked anyway, it would
// sit at the head of the list whenever it came first and hide every release that
// can be ordered. Any tag it can place compares as ahead of or equal to v0.0.0,
// and one it cannot parse compares as differing, which is the difference tested
// for.
func (r Release) eligible(goos, goarch string) bool {
	return ValidTag(r.Tag) && !r.Prerelease && !r.Draft && !r.PublishedAt.IsZero() && r.Complete(goos, goarch) &&
		version.CompareBuilds(r.Tag, "v0.0.0") != version.SkewDiffers
}

// Newest is the newest release an update could take, and false when there is
// none.
//
// It orders with version.CompareBuilds, the only ordering this repository
// trusts, and not by publish date: a maintainer can publish a patch to an old
// line after the new one, and the text of "v1.3.10" sorts before "v1.3.9". Two
// entries of one version -- a release deleted and made again -- are told apart
// by publish date, the later being the one whose files are current.
func Newest(releases []Release, goos, goarch string) (Release, bool) {
	var best Release
	found := false
	for _, r := range releases {
		if !r.eligible(goos, goarch) {
			continue
		}
		if !found || r.supersedes(best) {
			best, found = r, true
		}
	}
	return best, found
}

// supersedes says whether r is a better answer to "newest" than other.
func (r Release) supersedes(other Release) bool {
	switch version.CompareBuilds(r.Tag, other.Tag) {
	case version.SkewAhead:
		return true
	case version.SkewNone:
		return r.PublishedAt.After(other.PublishedAt)
	}
	return false
}

// displaced is the release that newest pushed aside: the newest release an
// update could take that is older than newest and still ahead of what is
// running. Under a soak it is the one an operator asks about, having perhaps
// been public for the whole wait and still not been taken. Only it is named,
// because each of the earlier ones was pushed aside by the release after it. It
// asks Newest rather than restating what makes a release eligible, so the two
// cannot drift apart.
func displaced(releases []Release, goos, goarch string, newest Release, running string) (Release, bool) {
	between := make([]Release, 0, len(releases))
	for _, r := range releases {
		if version.CompareBuilds(r.Tag, newest.Tag) == version.SkewBehind &&
			version.CompareBuilds(running, r.Tag) == version.SkewBehind {
			between = append(between, r)
		}
	}
	return Newest(between, goos, goarch)
}

package updates

import (
	"slices"
	"strconv"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/version"
)

// finished is the file list of a release once CI has uploaded all of it. The
// rule reads two of these, but a release in the wild lists every one, and a test
// that gave it only the two it reads could not notice a rule that matched too
// loosely.
var finished = []string{
	"checksums.txt",
	"zoomies_darwin_amd64", "zoomies_darwin_arm64",
	"zoomies_linux_amd64", "zoomies_linux_arm64",
	"zoomies_windows_amd64.exe",
	"zoomies-provenance.intoto.jsonl", "zoomies-provenance.sigstore.json",
}

// published is a finished release that went public at the given time.
func published(tag string, at time.Time) Release {
	return Release{
		Tag:         tag,
		URL:         "https://github.com/eyupio/zoomies/releases/tag/" + tag,
		PublishedAt: at,
		Assets:      slices.Clone(finished),
	}
}

// without is the release as it looks while its files are still uploading:
// public, and short of one asset.
func without(r Release, asset string) Release {
	r.Assets = slices.DeleteFunc(slices.Clone(r.Assets), func(a string) bool { return a == asset })
	return r
}

// inEveryRotation runs check on the list started from each entry in turn.
// GitHub promises no order, and a rule that finds the right answer only when it
// comes first is a rule that works until the day it does not.
func inEveryRotation(releases []Release, check func(rotated []Release)) {
	for i := range releases {
		check(append(slices.Clone(releases[i:]), releases[:i]...))
	}
}

// The tag is the one part of a release that is put into a download address and
// into a request a privileged helper reads, so the check is a yes or a no on the
// whole string. Each refusal here is a way a tag has been, or could be, almost
// right -- and "almost" is how a newline or a semicolon gets through.
func TestValidTagIsStrict(t *testing.T) {
	for _, tag := range []string{"v1.3.5", "v10.0.12", "v0.0.0"} {
		if !ValidTag(tag) {
			t.Errorf("ValidTag(%q) = false, want true", tag)
		}
	}
	for _, tc := range []struct{ name, tag string }{
		{"a capital V", "V1.3.5"},
		{"no v", "1.3.5"},
		{"two numbers", "v1.3"},
		{"four numbers", "v1.3.5.1"},
		{"a prerelease suffix", "v1.3.5-rc1"},
		{"a trailing newline", "v1.3.5\n"},
		{"a trailing carriage return", "v1.3.5\r"},
		{"a leading space", " v1.3.5"},
		{"a trailing space", "v1.3.5 "},
		{"text before the v", "xv1.3.5"},
		{"a shell separator", "v1.3.5;x"},
		{"fullwidth digits", "v\uff11.\uff13.\uff15"},
		{"an empty number", "v1..5"},
		{"a sign", "v1.-3.5"},
		{"nothing", ""},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if ValidTag(tc.tag) {
				t.Errorf("ValidTag(%q) = true, want false", tc.tag)
			}
		})
	}
}

// A release binary reports 1.3.5 while its tag is v1.3.5, and a host is only
// ever sent to the release its controller runs. A build that is not exactly
// such a release has no tag to be sent to -- "dev" least of all, which is a real
// install tag and not one the helper accepts.
func TestTargetTagUsesTheRunningRelease(t *testing.T) {
	for _, tc := range []struct {
		running string
		want    string
		ok      bool
	}{
		{"1.3.5", "v1.3.5", true},
		{"v1.3.5", "v1.3.5", true},
		{"dev", "", false},
		{"main-sha-abc1234", "", false},
		{"v0.2-beta-5-gabc1234", "", false},
		{"v1.2", "", false},
		{"0.2-beta", "", false},
		{"", "", false},
	} {
		t.Run(strconv.Quote(tc.running), func(t *testing.T) {
			got, ok := TargetTag(tc.running)
			if got != tc.want || ok != tc.ok {
				t.Errorf("TargetTag(%q) = %q, %v; want %q, %v", tc.running, got, ok, tc.want, tc.ok)
			}
		})
	}
}

// The names are the ones SelfUpdate downloads, and it serves only linux and
// darwin. An empty name for anything else is what keeps a release from looking
// complete for a system nothing can install it on.
func TestAssetNameNamesOnlyTheSystemsSelfUpdateServes(t *testing.T) {
	for _, tc := range []struct{ goos, goarch, want string }{
		{"linux", "amd64", "zoomies_linux_amd64"},
		{"linux", "arm64", "zoomies_linux_arm64"},
		{"darwin", "amd64", "zoomies_darwin_amd64"},
		{"darwin", "arm64", "zoomies_darwin_arm64"},
		{"windows", "amd64", ""},
		{"freebsd", "amd64", ""},
		{"", "", ""},
	} {
		if got := AssetName(tc.goos, tc.goarch); got != tc.want {
			t.Errorf("AssetName(%q, %q) = %q, want %q", tc.goos, tc.goarch, got, tc.want)
		}
	}
}

// A release is public before its files finish uploading -- binaries first, the
// checksums last -- so for a while there is a tag SelfUpdate would fail on.
// Offering it is the mistake this check exists to prevent: it sends a host to a
// download that cannot be verified.
func TestCompleteNeedsTheChecksumsAndTheHostsBinary(t *testing.T) {
	for _, tc := range []struct {
		name         string
		assets       []string
		goos, goarch string
		want         bool
	}{
		{"the checksums and the binary", []string{"checksums.txt", "zoomies_linux_amd64"}, "linux", "amd64", true},
		{"everything a finished release carries", finished, "linux", "amd64", true},
		{"a darwin host reads its own binary", finished, "darwin", "arm64", true},
		{"the binary without the checksums", []string{"zoomies_linux_amd64"}, "linux", "amd64", false},
		{"the checksums without the binary", []string{"checksums.txt"}, "linux", "amd64", false},
		{"only the other architecture's binary", []string{"checksums.txt", "zoomies_linux_arm64"}, "linux", "amd64", false},
		{"only the other system's binary", []string{"checksums.txt", "zoomies_darwin_amd64"}, "linux", "amd64", false},
		{"nothing at all", nil, "linux", "amd64", false},
		// SelfUpdate serves no windows host, so no release is complete for one,
		// whatever it is called and however many names it carries.
		{"windows, under every name it could have", append([]string{"zoomies_windows_amd64"}, finished...), "windows", "amd64", false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			r := Release{Tag: "v1.3.5", Assets: tc.assets}
			if got := r.Complete(tc.goos, tc.goarch); got != tc.want {
				t.Errorf("Complete(%q, %q) with %v = %v, want %v", tc.goos, tc.goarch, tc.assets, got, tc.want)
			}
		})
	}
}

// Every release below is one a careless rule would take, and all but the capital
// V are newer than the one that is right, so a filter that fails to drop one
// shows as the wrong answer rather than as a quiet pass. Three are tags
// CompareBuilds can order -- it reads a missing v, a missing patch number and a
// suffix without complaint -- so only the check on the shape of the tag keeps
// them out, and the last is perfect in every way but has no publication date.
// The list is tried in every rotation because a tag CompareBuilds cannot order
// only wins when it comes first.
func TestNewestIgnoresIncompletePrereleaseDraftAndOddTags(t *testing.T) {
	t0 := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
	flagged := published("v1.6.0", t0)
	flagged.Prerelease = true
	candidate := published("v1.4.0-rc1", t0)
	candidate.Prerelease = true
	draft := published("v1.5.0", t0)
	draft.Draft = true
	undated := published("v2.0.0", time.Time{})
	releases := []Release{
		published("V1.1.0", t0),
		published("v1.3.4", t0),
		without(published("v1.3.5", t0), "checksums.txt"),
		candidate,
		draft,
		flagged,
		published("v1.7", t0),
		published("1.8.0", t0),
		published("v1.9.0-rc2", t0),
		undated,
	}

	inEveryRotation(releases, func(rotated []Release) {
		got, ok := Newest(rotated, "linux", "amd64")
		if !ok || got.Tag != "v1.3.4" {
			t.Errorf("Newest = %q, %v from %s first; want v1.3.4", got.Tag, ok, rotated[0].Tag)
		}
	})

	ineligible := slices.DeleteFunc(slices.Clone(releases), func(r Release) bool { return r.Tag == "v1.3.4" })
	if got, ok := Newest(ineligible, "linux", "amd64"); ok {
		t.Errorf("Newest of releases none of which qualifies = %q, true; want nothing", got.Tag)
	}
	if got, ok := Newest(nil, "linux", "amd64"); ok {
		t.Errorf("Newest of no releases = %q, true; want nothing", got.Tag)
	}
}

// 1.3.10 is later than 1.3.9, and a sort on the text or on the date says
// otherwise: the first because "1" comes before "9", the second because a
// maintainer can publish a patch to an old line after the new one.
func TestNewestOrdersByVersionNotByPublishTime(t *testing.T) {
	t0 := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
	releases := []Release{
		published("v1.3.9", t0.Add(2*time.Hour)),
		published("v1.3.10", t0),
		published("v1.2.40", t0.Add(3*time.Hour)),
	}
	inEveryRotation(releases, func(rotated []Release) {
		if got, ok := Newest(rotated, "linux", "amd64"); !ok || got.Tag != "v1.3.10" {
			t.Errorf("Newest = %q, %v from %s first; want v1.3.10", got.Tag, ok, rotated[0].Tag)
		}
	})
}

// A release deleted and made again for the same tag is two entries of one
// version. The one made last is the one whose files are current.
func TestNewestBreaksAVersionTieByPublishTime(t *testing.T) {
	t0 := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
	first := published("v1.3.5", t0)
	first.URL += "?first"
	second := published("v1.3.5", t0.Add(time.Hour))
	second.URL += "?second"

	inEveryRotation([]Release{first, second}, func(rotated []Release) {
		if got, ok := Newest(rotated, "linux", "amd64"); !ok || got.URL != second.URL {
			t.Errorf("Newest = %q, %v from %s first; want the one published last", got.URL, ok, rotated[0].URL)
		}
	})
}

// A number too large for an int still matches the tag pattern, and
// CompareBuilds can say nothing about such a tag. Left in, it would sit at the
// head of the list whenever it came first and hide every release that can be
// ordered.
func TestNewestSkipsATagTooBigToOrder(t *testing.T) {
	t0 := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
	huge := published("v99999999999999999999.0.0", t0.Add(time.Hour))
	if !ValidTag(huge.Tag) {
		t.Fatalf("%q is not a valid tag, so this test no longer tries what it says", huge.Tag)
	}
	inEveryRotation([]Release{huge, published("v1.3.4", t0), published("v1.3.3", t0)}, func(rotated []Release) {
		if got, ok := Newest(rotated, "linux", "amd64"); !ok || got.Tag != "v1.3.4" {
			t.Errorf("Newest = %q, %v from %s first; want v1.3.4", got.Tag, ok, rotated[0].Tag)
		}
	})
}

func TestHostSkewFollowsAControllerBuiltFromMainExactly(t *testing.T) {
	const main = "main-sha-abc1234"
	for _, tc := range []struct {
		host string
		want version.Skew
	}{
		{"main-sha-abc1234", version.SkewNone},
		{"main-sha-1c5b8378", version.SkewBehind},
		{"1.3.5", version.SkewBehind},
		{"1.3.5-3-gabcdef1", version.SkewDiffers},
		{"weird", version.SkewDiffers},
	} {
		if got := HostSkew(tc.host, main); got != tc.want {
			t.Errorf("HostSkew(%q, %q) = %q, want %q", tc.host, main, got, tc.want)
		}
	}
}

func TestHostTargetAndWireTagForADevelopmentController(t *testing.T) {
	if got, ok := HostTarget("main-sha-abc1234"); !ok || got != "main-sha-abc1234" {
		t.Errorf("HostTarget = %q, %v; want the exact build", got, ok)
	}
	if _, ok := HostTarget("1.3.5-3-gabcdef1"); ok {
		t.Error("a local build was given as a target")
	}
	if got := WireTag("main-sha-abc1234"); got != "dev" {
		t.Errorf("WireTag = %q, want dev", got)
	}
	if got := WireTag("v1.3.5"); got != "v1.3.5" {
		t.Errorf("WireTag = %q, want a release tag unchanged", got)
	}
}

package updates

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"path/filepath"
	"slices"
	"strings"
	"time"
)

// A helper that has stopped answering looks the same from the service as one
// that is slow: request.json sits in the update folder and nothing reads it.
// The service cannot tell the two apart by waiting, and it cannot repair the
// root-owned units itself, so this file is the shared vocabulary of the three
// parties that deal with it: the agent that diagnoses, the root helper that
// repairs, and the controller that tells the operator. Like the rest of this
// package it reads no clock and no file.

const (
	// StuckPathDown is a helper whose path unit is not waiting for a request:
	// disabled, inactive or failed, most often because systemd stopped it for
	// starting the service too often.
	StuckPathDown = "path_down"
	// StuckStaleRequest is a request nobody has read for longer than a healthy
	// helper takes to pick one up, with the units apparently fine.
	StuckStaleRequest = "stale_request"
	// StuckBusy is not a fault: the helper is running an update now, or the
	// engine is. It is a verdict so that nothing in the folder is touched.
	StuckBusy = "helper_busy"

	// OrphanAfter is how old a request or a lock must be, with no helper and no
	// engine running, before it is called abandoned. A healthy helper takes a
	// request within seconds and the engine finishes within fifty minutes while
	// its process is alive, so a file this old with nothing alive behind it is
	// left over.
	OrphanAfter = 15 * time.Minute

	// RepairMinInterval and RepairMaxPerDay bound how often a host's units are
	// repaired. They are enforced by root against its own record, and by the
	// agent against its own memory, so a loop in either is stopped by the other.
	RepairMinInterval = 10 * time.Minute
	RepairMaxPerDay   = 3

	// RepairFile is what the agent writes to ask root to look at the helper, and
	// RepairResultFile is what root answers in. They sit beside request.json and
	// are watched by their own units, so a helper whose path unit has died can
	// still be repaired.
	RepairFile       = "repair.json"
	RepairResultFile = "repair-result.json"

	// MaxRepairBytes bounds both documents.
	MaxRepairBytes = 8 << 10
)

// UnitState is what systemctl says of one unit, as its own words. An empty
// field is a question that could not be asked.
type UnitState struct {
	// Active is the is-active word: active, inactive, failed, activating...
	Active string `json:"active"`
	// Enabled is the is-enabled word: enabled, disabled, static, masked...
	Enabled string `json:"enabled"`
	// Failed says the unit is in the failed state, which is what a start limit
	// leaves behind and what reset-failed clears.
	Failed bool `json:"failed"`
}

// Diagnosis is everything looked at before a request is refused for one
// already waiting.
type Diagnosis struct {
	RequestPresent bool          `json:"request_present"`
	RequestAge     time.Duration `json:"request_age"`
	// RequestID is the waiting request's attempt, when it could be read.
	RequestID   string        `json:"request_id,omitempty"`
	LockPresent bool          `json:"lock_present"`
	LockAge     time.Duration `json:"lock_age"`
	Path        UnitState     `json:"path"`
	Service     UnitState     `json:"service"`
	// EngineRunning says a zoomies upgrade process is alive on the host.
	EngineRunning bool `json:"engine_running"`
}

var busyWords = []string{"active", "activating", "deactivating", "reloading"}

// ServiceBusy says the helper's service, or the engine it starts, is working.
func (d Diagnosis) ServiceBusy() bool {
	return d.EngineRunning || slices.Contains(busyWords, d.Service.Active)
}

// PathWaiting says the path unit is the one that would start the helper for the
// request: running and enabled, and not failed.
func (d Diagnosis) PathWaiting() bool {
	return d.Path.Active == "active" && !d.Path.Failed &&
		(d.Path.Enabled == "enabled" || d.Path.Enabled == "static" || d.Path.Enabled == "")
}

// UnitsKnown says systemd could be asked about the path unit at all. A host
// where it could not (no systemctl, a container, no bus) is one nothing can be
// concluded about, and is never repaired on a guess.
func (d Diagnosis) UnitsKnown() bool { return d.Path.Active != "" || d.Path.Enabled != "" }

// Verdict is Classify's answer.
type Verdict struct {
	// Kind is one of the Stuck constants, or empty for a helper that is merely
	// not done yet.
	Kind string
	// Repair says asking root to repair the helper is justified.
	Repair bool
}

// Classify says what a waiting request means. A busy helper is never repaired
// and nothing in the folder is touched, whatever else is wrong with it: a live
// helper may still be reading the request, and a live engine owns the lock.
func Classify(d Diagnosis, staleAfter time.Duration) Verdict {
	switch {
	case d.ServiceBusy():
		return Verdict{Kind: StuckBusy}
	case !d.UnitsKnown():
		return Verdict{}
	case !d.PathWaiting():
		return Verdict{Kind: StuckPathDown, Repair: true}
	case d.Service.Failed:
		return Verdict{Kind: StuckPathDown, Repair: true}
	case d.RequestPresent && d.RequestAge > staleAfter:
		return Verdict{Kind: StuckStaleRequest, Repair: true}
	}
	return Verdict{}
}

// Orphaned says the request and the lock left in the folder are provably
// abandoned: nothing is running, and they are older than OrphanAfter. It is
// asked only after the units have been put right, since a helper that comes
// back reads a request itself, and the answer is per file.
func (d Diagnosis) Orphaned() (request, lock bool) {
	if d.ServiceBusy() {
		return false, false
	}
	return d.RequestPresent && d.RequestAge > OrphanAfter, d.LockPresent && d.LockAge > OrphanAfter
}

// EngineRunning says one of the command lines is a zoomies upgrade engine. The
// caller reads /proc; this only reads the arguments, so the match is a table
// test.
func EngineRunning(cmdlines [][]string) bool {
	for _, argv := range cmdlines {
		if len(argv) < 2 || !strings.HasPrefix(filepath.Base(argv[0]), "zoomies") {
			continue
		}
		// A flag may take a value ahead of the subcommand, so the word is looked
		// for anywhere; the helper's own "updates helper run" never carries it.
		if slices.Contains(argv[1:], "upgrade") && !slices.Contains(argv[1:], "updates") {
			return true
		}
	}
	return false
}

// RepairRequest is what the agent leaves for root. It carries nothing root acts
// on but the attempt it is for: the diagnosis is made again by root.
type RepairRequest struct {
	V           int       `json:"v"`
	ID          string    `json:"id"`
	RequestedAt time.Time `json:"requested_at"`
}

// RepairResult is root's account of a repair.
type RepairResult struct {
	V  int    `json:"v"`
	ID string `json:"id"`
	// Healed says the helper is waiting for requests again and the folder holds
	// nothing that would stop a new one.
	Healed bool `json:"healed"`
	// Actions are the steps taken, in order, as fixed words.
	Actions []string `json:"actions,omitempty"`
	// Verdict is what root found, one of the Stuck constants.
	Verdict    string    `json:"verdict,omitempty"`
	Error      string    `json:"error,omitempty"`
	FinishedAt time.Time `json:"finished_at"`
}

// The actions a repair reports.
const (
	ActionResetFailed       = "reset_failed"
	ActionRewroteUnits      = "rewrote_units"
	ActionStartedPath       = "started_path"
	ActionRemovedRequest    = "removed_request"
	ActionRemovedLock       = "removed_lock"
	ActionRefusedBusy       = "refused_busy"
	ActionRefusedRateLimit  = "refused_rate_limit"
	maxRepairActionsAllowed = 8
)

// ParseRepairRequest reads a repair.json. The folder belongs to the service,
// so anything may be in it: the document is read strictly and checked.
func ParseRepairRequest(body []byte) (RepairRequest, error) {
	var r RepairRequest
	if err := decodeStrict(body, &r); err != nil {
		return RepairRequest{}, fmt.Errorf("the repair request is not a document this release reads: %w", err)
	}
	if r.V != WireVersion {
		return RepairRequest{}, fmt.Errorf("the repair request is version %d and this release reads version %d", r.V, WireVersion)
	}
	if err := checkID(r.ID); err != nil {
		return RepairRequest{}, fmt.Errorf("the repair request's id: %w", err)
	}
	return r, nil
}

// ParseRepairResult reads a repair-result.json.
func ParseRepairResult(body []byte) (RepairResult, error) {
	var r RepairResult
	if err := decodeStrict(body, &r); err != nil {
		return RepairResult{}, fmt.Errorf("the repair result is not a document this release reads: %w", err)
	}
	if r.V != WireVersion {
		return RepairResult{}, fmt.Errorf("the repair result is version %d and this release reads version %d", r.V, WireVersion)
	}
	if len(r.Actions) > maxRepairActionsAllowed {
		return RepairResult{}, fmt.Errorf("the repair result lists %d actions, over the limit of %d", len(r.Actions), maxRepairActionsAllowed)
	}
	return r, nil
}

func checkID(id string) error {
	switch {
	case id == "":
		return errors.New("is empty")
	case len(id) > 64:
		return errors.New("is over 64 bytes")
	}
	for _, r := range id {
		if !(r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || r == '_' || r == '-') {
			return fmt.Errorf("has %q in it", r)
		}
	}
	return nil
}

func decodeStrict(body []byte, into any) error {
	dec := json.NewDecoder(bytes.NewReader(body))
	dec.DisallowUnknownFields()
	if err := dec.Decode(into); err != nil {
		return err
	}
	if _, err := dec.Token(); !errors.Is(err, io.EOF) {
		return errors.New("has more in it than one document")
	}
	return nil
}

// RepairLedger is the record that bounds repairs: the times of the ones made.
// Root keeps its own, in a folder only root writes; the agent keeps one in
// memory. Both ask Admit.
type RepairLedger struct {
	Times []time.Time `json:"times"`
}

// Admit says whether a repair may start at now, and when the next may if not.
// An admitted repair is recorded; the ledger is pruned to the last day.
func (l *RepairLedger) Admit(now time.Time) (ok bool, next time.Time) {
	kept := l.Times[:0]
	for _, t := range l.Times {
		if now.Sub(t) < 24*time.Hour {
			kept = append(kept, t)
		}
	}
	l.Times = kept
	if n := len(l.Times); n > 0 {
		if next = l.Times[n-1].Add(RepairMinInterval); now.Before(next) {
			return false, next
		}
	}
	if len(l.Times) >= RepairMaxPerDay {
		return false, l.Times[0].Add(24 * time.Hour)
	}
	l.Times = append(l.Times, now)
	return true, time.Time{}
}

package updates

import (
	"strings"
	"testing"
	"time"
)

func healthyDiagnosis() Diagnosis {
	return Diagnosis{
		Path:    UnitState{Active: "active", Enabled: "enabled"},
		Service: UnitState{Active: "inactive", Enabled: "static"},
	}
}

// What the service must never do is repair a helper that is working, and what
// it must always do is repair one that cannot work. Every row is a state a host
// has been seen in or could reach.
func TestClassifyTellsABrokenHelperFromAWorkingOne(t *testing.T) {
	for _, tc := range []struct {
		name   string
		change func(*Diagnosis)
		want   string
		repair bool
	}{
		{"a fresh request under a healthy helper is just not read yet", func(d *Diagnosis) {
			d.RequestPresent, d.RequestAge = true, 20*time.Second
		}, "", false},
		{"a disabled and dead path unit is the stall that failed updates for days", func(d *Diagnosis) {
			d.RequestPresent, d.RequestAge = true, 72*time.Hour
			d.Path = UnitState{Active: "inactive", Enabled: "disabled"}
		}, StuckPathDown, true},
		{"a path unit in the failed state, as a start limit leaves it", func(d *Diagnosis) {
			d.Path = UnitState{Active: "failed", Enabled: "enabled", Failed: true}
		}, StuckPathDown, true},
		{"a failed service unit blocks the next start", func(d *Diagnosis) {
			d.Service = UnitState{Active: "failed", Failed: true}
		}, StuckPathDown, true},
		{"a request older than a healthy helper takes", func(d *Diagnosis) {
			d.RequestPresent, d.RequestAge = true, time.Hour
		}, StuckStaleRequest, true},
		{"a helper that is mid-upgrade is left entirely alone", func(d *Diagnosis) {
			d.RequestPresent, d.RequestAge = true, 3*time.Hour
			d.Service = UnitState{Active: "activating"}
			d.Path = UnitState{Active: "inactive", Enabled: "disabled"}
		}, StuckBusy, false},
		{"an engine alive with the service idle is still mid-upgrade", func(d *Diagnosis) {
			d.EngineRunning, d.LockPresent, d.LockAge = true, true, 4*time.Hour
			d.Path = UnitState{Active: "failed", Failed: true}
		}, StuckBusy, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			d := healthyDiagnosis()
			tc.change(&d)
			got := Classify(d, OrphanAfter)
			if got.Kind != tc.want || got.Repair != tc.repair {
				t.Errorf("Classify = %+v, want kind %q repair %v", got, tc.want, tc.repair)
			}
		})
	}
}

func TestOnlyAbandonedFilesAreCalledOrphaned(t *testing.T) {
	old := Diagnosis{RequestPresent: true, RequestAge: time.Hour, LockPresent: true, LockAge: 2 * time.Hour}
	if r, l := old.Orphaned(); !r || !l {
		t.Errorf("an hour-old request and a two-hour-old lock with nothing running: orphaned = %v, %v", r, l)
	}
	young := old
	young.RequestAge, young.LockAge = time.Minute, time.Minute
	if r, l := young.Orphaned(); r || l {
		t.Errorf("files a minute old are not abandoned, got %v, %v", r, l)
	}
	for name, busy := range map[string]Diagnosis{
		"a service running": {Service: UnitState{Active: "active"}},
		"an engine running": {EngineRunning: true},
	} {
		d := old
		d.Service, d.EngineRunning = busy.Service, busy.EngineRunning
		if r, l := d.Orphaned(); r || l {
			t.Errorf("with %s nothing is orphaned, got %v, %v", name, r, l)
		}
	}
}

func TestEngineRunningReadsTheSubcommandNotAnyArgument(t *testing.T) {
	for _, tc := range []struct {
		argv []string
		want bool
	}{
		{[]string{"/usr/local/bin/zoomies", "upgrade", "--version", "v1.4.0", "--non-interactive"}, true},
		{[]string{"zoomies", "--config", "/etc/zoomies/zoomies.yaml", "upgrade"}, true},
		{[]string{"/usr/local/bin/zoomies", "updates", "helper", "run"}, false},
		{[]string{"/usr/local/bin/zoomies", "controller"}, false},
		{[]string{"vim", "upgrade"}, false},
		{[]string{"zoomies"}, false},
	} {
		if got := EngineRunning([][]string{tc.argv}); got != tc.want {
			t.Errorf("EngineRunning(%q) = %v, want %v", strings.Join(tc.argv, " "), got, tc.want)
		}
	}
}

func TestTheRepairLedgerSpacesAndBoundsRepairs(t *testing.T) {
	var l RepairLedger
	t0 := time.Date(2026, 10, 20, 9, 0, 0, 0, time.UTC)
	if ok, _ := l.Admit(t0); !ok {
		t.Fatal("the first repair must be admitted")
	}
	if ok, next := l.Admit(t0.Add(time.Minute)); ok || !next.Equal(t0.Add(RepairMinInterval)) {
		t.Errorf("a second repair a minute later: ok=%v next=%v, want refused until %v", ok, next, t0.Add(RepairMinInterval))
	}
	at := t0
	for range RepairMaxPerDay - 1 {
		at = at.Add(RepairMinInterval)
		if ok, _ := l.Admit(at); !ok {
			t.Fatalf("a repair at %v is within the day's budget", at)
		}
	}
	if ok, next := l.Admit(at.Add(time.Hour)); ok || !next.Equal(t0.Add(24*time.Hour)) {
		t.Errorf("past the day's budget: ok=%v next=%v, want refused until %v", ok, next, t0.Add(24*time.Hour))
	}
	if ok, _ := l.Admit(t0.Add(24*time.Hour + time.Minute)); !ok {
		t.Error("a day later the budget is back")
	}
}

func TestRepairDocumentsAreReadStrictly(t *testing.T) {
	if _, err := ParseRepairRequest([]byte(`{"v":1,"id":"upd_abc123","requested_at":"2026-10-20T09:00:00Z"}`)); err != nil {
		t.Errorf("a good repair request was refused: %v", err)
	}
	for name, body := range map[string]string{
		"an unknown field": `{"v":1,"id":"upd_abc","requested_at":"2026-10-20T09:00:00Z","cmd":"rm -rf /"}`,
		"a path in the id": `{"v":1,"id":"../etc/passwd","requested_at":"2026-10-20T09:00:00Z"}`,
		"another version":  `{"v":9,"id":"upd_abc","requested_at":"2026-10-20T09:00:00Z"}`,
		"two documents":    `{"v":1,"id":"upd_abc","requested_at":"2026-10-20T09:00:00Z"}{}`,
		"no id":            `{"v":1,"requested_at":"2026-10-20T09:00:00Z"}`,
	} {
		if _, err := ParseRepairRequest([]byte(body)); err == nil {
			t.Errorf("%s was accepted", name)
		}
	}
}

package updates

import (
	"fmt"
	"strconv"
	"time"

	"github.com/eyupio/zoomies/internal/version"
)

// Mode is what the platform has chosen to do about new releases. The values are
// those of the updates.mode setting.
//
// internal/config lists the same three words for the setting. This package does
// not import it, so a word added to one is a word to add to the other.
type Mode string

const (
	// ModeOff considers no release at all.
	ModeOff Mode = "off"
	// ModeManual offers the newest release to a person, who is the only wait.
	ModeManual Mode = "manual"
	// ModeAuto takes the newest release once it has been public for the soak.
	ModeAuto Mode = "auto"
)

// ChooseInput is everything Choose needs, gathered by the caller.
type ChooseInput struct {
	Mode Mode
	// Soak is how long auto waits after a release is published; manual ignores
	// it. It is never negative: the configuration refuses a negative soak when
	// it loads.
	Soak time.Duration
	// Now is the decision time. It is a field rather than a clock read so that a
	// test can place a soak one nanosecond either side of its end.
	Now time.Time
	// Running is the version of the build being updated as it reports itself,
	// which for a release binary is "1.3.5" without the v its tag has.
	Running  string
	Releases []Release
	// GOOS and GOARCH name the system whose binary would be installed.
	GOOS, GOARCH string
}

// Target is what the mode would do about the releases on offer, and why.
type Target struct {
	// Release is the newest complete release for the system, whether or not it
	// is newer than what is running. It is the zero Release when there is none,
	// and when updates are off.
	Release Release
	// Newer says whether Release is a later release than the one running. Only
	// then is there anything to take.
	Newer bool
	// Replaces says the running build is not from a release, so Release would
	// replace it rather than succeed it. It may be a step back, since a build from
	// main is usually ahead of the newest release, which is why only a person takes
	// it: the planner never does.
	Replaces bool
	// DueAt is the earliest time the mode takes Release: the end of the soak in
	// auto, and zero in manual, where the person asking is the only wait. It
	// means nothing unless Newer.
	DueAt time.Time
	// Reason is the text the status shows, in an operator's words.
	Reason string
}

// DueBy says whether the mode may take the release at now. It is the one place
// the wait is compared with a clock: Choose asks it too when it words the
// reason, so the sentence and the decision cannot disagree about the instant the
// wait ends.
func (t Target) DueBy(now time.Time) bool {
	return t.Newer && !now.Before(t.DueAt)
}

// Choose says which release the mode would take, when, and why.
//
// Off is decided first, before any release is looked at, so that nothing a
// release says can read as an offer. After that it is Newest, then a comparison
// of what is running with that release, then the mode's own wait. Only a build
// that is behind is Newer: one that is ahead would be a downgrade, and the same
// release written two ways, 1.3.5 and v1.3.5, is no change at all.
func Choose(in ChooseInput) Target {
	if in.Mode != ModeManual && in.Mode != ModeAuto {
		return Target{Reason: "Updates are off. Set updates.mode to manual or auto to be offered new releases."}
	}
	best, found := Newest(in.Releases, in.GOOS, in.GOARCH)
	t := Target{Release: best}

	release, fromRelease := version.Release(in.Running)
	if !found {
		t.Reason = noReleaseReason(in.GOOS, in.GOARCH)
		return t
	}
	if !fromRelease {
		// A controller on :dev is usually ahead of the newest release, and there is
		// no order to compare, so this is offered and never taken by itself: the
		// person who presses the button is the one who knows whether a release is
		// where they want to be.
		t.Newer, t.Replaces = true, true
		t.Reason = fmt.Sprintf("Available: %s can replace this build, %s, which is not from a release. A build from main is usually ahead of the newest release, so this may be a step back; it is taken only when someone asks, in manual and in auto.",
			best.Tag, in.Running)
		return t
	}

	running := "v" + release
	switch version.CompareBuilds(in.Running, best.Tag) {
	case version.SkewBehind:
		t.Newer = true
	case version.SkewNone:
		t.Reason = "Up to date: " + best.Tag + " is the newest release that can be installed."
		return t
	case version.SkewAhead:
		t.Reason = fmt.Sprintf("Ahead of the newest release that can be installed (%s): this build is %s, and updates never go back.", best.Tag, running)
		return t
	default:
		t.Reason = fmt.Sprintf("This build, %s, cannot be ordered against %s, so updates leave it alone. Run a released build such as %s and this clears.", running, best.Tag, best.Tag)
		return t
	}

	if in.Mode == ModeManual {
		t.Reason = fmt.Sprintf("Available: %s is newer than the %s running now; manual mode waits for someone to update.", best.Tag, running)
		return t
	}
	t.DueAt = best.PublishedAt.Add(in.Soak)
	skipped, _ := displaced(in.Releases, in.GOOS, in.GOARCH, best, in.Running)
	t.Reason = autoReason(t, skipped.Tag, in.Soak, in.Now)
	return t
}

// noReleaseReason says why no release can be offered to this system. The two
// causes are told apart because their fixes differ: a system nothing here
// updates has none, and anywhere else the release itself is what to look at.
func noReleaseReason(goos, goarch string) string {
	asset := AssetName(goos, goarch)
	if asset == "" {
		return fmt.Sprintf("Updates are available only on linux and darwin, and this is %s/%s.", goos, goarch)
	}
	return fmt.Sprintf("No complete release is available for %s/%s. A complete release has a vX.Y.Z tag and a publication date, is not a draft or a prerelease, and carries %s and %s.",
		goos, goarch, checksumsAsset, asset)
}

// autoReason words an auto target that is newer: inside the soak, past it, or
// dated ahead of the clock. skipped is the tag of the release the target pushed
// aside, or empty when it pushed none.
func autoReason(t Target, skipped string, soak time.Duration, now time.Time) string {
	tag := t.Release.Tag
	age := now.Sub(t.Release.PublishedAt)
	if age < 0 {
		// GitHub's clock and this controller's can disagree, and a release can be
		// dated ahead on purpose. Either way the wait has not started, and an age
		// below zero in the sentence would read as nonsense.
		return fmt.Sprintf("Waiting: %s is dated in the future, so it does not count as public yet; it can be taken in %s.",
			tag, spanOf(t.DueAt.Sub(now)))
	}
	wait := "auto does not wait"
	if soak > 0 {
		wait = "auto waits for " + spanOf(soak).following(spanOf(age))
	}
	if t.DueBy(now) {
		return fmt.Sprintf("Ready: %s has been public for %s and %s; it can be taken now.", tag, spanOf(age), wait)
	}
	waiting := fmt.Sprintf("Waiting: %s has been public for %s and %s; it can be taken in %s.",
		tag, spanOf(age), wait, spanOf(t.DueAt.Sub(now)))
	if skipped == "" {
		return waiting
	}
	// A newer release restarts the wait, so an older one that has already been
	// public for the whole soak is passed over. Without this the operator is left
	// to work out why it was not taken, and that a project publishing faster than
	// the soak is never updated by auto.
	return waiting + fmt.Sprintf(" It replaced %s, which is skipped, and a newer release would start the wait again.", skipped)
}

// span is a length of time as the sentences say it: whole hours from an hour up,
// whole minutes below that, and nothing finer.
type span struct {
	n    int
	unit string // "hour", "minute", or empty for less than a minute
}

// spanOf rounds down: a release is never said to have been public for longer
// than it has, and the time left, recomputed on every pass, only ever errs short.
func spanOf(d time.Duration) span {
	switch {
	case d >= time.Hour:
		return span{int(d / time.Hour), "hour"}
	case d >= time.Minute:
		return span{int(d / time.Minute), "minute"}
	}
	return span{}
}

func (s span) String() string {
	switch {
	case s.unit == "":
		return "less than a minute"
	case s.n == 1:
		return "1 " + s.unit
	}
	return strconv.Itoa(s.n) + " " + s.unit + "s"
}

// following words s for a sentence that has just said prev. When both count the
// same unit it is not said twice, as in "public for 6 hours and auto waits for
// 24", unless that would leave a bare 1, which reads as a count of nothing.
func (s span) following(prev span) string {
	if s.unit != "" && s.unit == prev.unit && s.n > 1 {
		return strconv.Itoa(s.n)
	}
	return s.String()
}

package updates

import (
	"strconv"
	"strings"
	"testing"
	"time"
)

// noon is the instant these tests treat as now unless they say otherwise.
var noon = time.Date(2026, 10, 8, 12, 0, 0, 0, time.UTC)

// asking is a linux/amd64 controller running the given build, offered releases
// under mode with the default soak of a day.
func asking(mode Mode, running string, now time.Time, releases ...Release) ChooseInput {
	return ChooseInput{
		Mode: mode, Soak: 24 * time.Hour, Now: now, Running: running,
		Releases: releases, GOOS: "linux", GOARCH: "amd64",
	}
}

// Off is not "nothing is newer": no release is considered at all, so nothing a
// status page shows can read as an offer. The release is one a person would
// take at once, which leaves only the mode to explain why it is not offered. A
// word this package does not know is read the same way. The configuration
// refuses one when it loads, so arriving with one is a bug, and the safe reading
// of a bug is that nothing gets replaced.
func TestChooseOffersNothingWhenTheModeIsOff(t *testing.T) {
	newer := published("v1.3.5", noon.Add(-72*time.Hour))
	for _, tc := range []struct {
		name string
		mode Mode
	}{
		{"off", ModeOff},
		{"no mode at all", ""},
		{"a word nobody defined", "automatic"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			got := Choose(asking(tc.mode, "1.3.4", noon, newer))
			if got.Newer || got.Release.Tag != "" {
				t.Errorf("offered %q (newer: %v) with the mode %q", got.Release.Tag, got.Newer, tc.mode)
			}
			if got.DueBy(noon.AddDate(1, 0, 0)) {
				t.Error("due a year on, with updates off")
			}
			if !strings.HasPrefix(got.Reason, "Updates are off") {
				t.Errorf("Reason = %q, want it to start %q", got.Reason, "Updates are off")
			}
		})
	}
}

// The usual state of a healthy controller, and the one the status shows most.
// It reads the same in both modes: a mode only matters once something newer
// exists to take.
func TestChooseSaysUpToDateWhenRunningTheNewest(t *testing.T) {
	older := published("v1.3.4", noon.Add(-200*time.Hour))
	newest := published("v1.3.5", noon.Add(-72*time.Hour))
	for _, mode := range []Mode{ModeManual, ModeAuto} {
		t.Run(string(mode), func(t *testing.T) {
			// A release binary reports 1.3.5 while the tag says v1.3.5.
			got := Choose(asking(mode, "1.3.5", noon, older, newest))
			if got.Newer || got.DueBy(noon.AddDate(1, 0, 0)) {
				t.Errorf("a controller on the newest release was offered %q (newer: %v)", got.Release.Tag, got.Newer)
			}
			if got.Release.Tag != "v1.3.5" {
				t.Errorf("Release = %q, want the newest, v1.3.5", got.Release.Tag)
			}
			if !strings.HasPrefix(got.Reason, "Up to date") {
				t.Errorf("Reason = %q, want it to say the controller is up to date", got.Reason)
			}
			// "The newest release" alone would be untrue the day a newer one is
			// still uploading: the sentence means the newest one that can be
			// installed, and says so.
			if !strings.Contains(got.Reason, "the newest release that can be installed") {
				t.Errorf("Reason = %q, want it to say which newest release it means", got.Reason)
			}
		})
	}
}

// A build ahead of the newest release is a candidate, a fork, or a build cut
// after the last tag, and an older binary may not read a database a newer one
// has migrated -- the reason SelfUpdate has its own guard. "Up to date" would be
// untrue of such a build, so the sentence says why nothing happens instead.
func TestChooseNeverOffersADowngrade(t *testing.T) {
	releases := []Release{
		published("v1.3.4", noon.Add(-72*time.Hour)),
		published("v1.3.3", noon.Add(-300*time.Hour)),
	}
	for _, mode := range []Mode{ModeManual, ModeAuto} {
		t.Run(string(mode), func(t *testing.T) {
			got := Choose(asking(mode, "1.4.0", noon, releases...))
			if got.Newer || got.DueBy(noon.AddDate(1, 0, 0)) {
				t.Errorf("offered a downgrade to %q (newer: %v)", got.Release.Tag, got.Newer)
			}
			if got.Release.Tag != "v1.3.4" {
				t.Errorf("Release = %q, want the newest, v1.3.4", got.Release.Tag)
			}
			for _, want := range []string{"v1.4.0", "v1.3.4", "the newest release that can be installed", "never go back"} {
				if !strings.Contains(got.Reason, want) {
					t.Errorf("Reason = %q, want it to contain %q", got.Reason, want)
				}
			}
		})
	}
}

// A controller on :dev is stamped main-sha-abc1234 and is usually ahead of the
// newest release, so a release is offered to it as a replacement and never as
// the next step: nothing orders the two, and the sentence says it may be a step
// back. Only a person takes it, in auto as in manual, so no wait is attached.
func TestChooseOffersABuildThatIsNotFromAReleaseTheNewestToReplaceIt(t *testing.T) {
	newest := published("v9.9.9", noon.Add(-72*time.Hour))
	for _, running := range []string{"main-sha-abc1234", "dev", "v0.2-beta-5-gabc1234", "some-fork-build", ""} {
		for _, mode := range []Mode{ModeManual, ModeAuto} {
			t.Run(string(mode)+" "+strconv.Quote(running), func(t *testing.T) {
				got := Choose(asking(mode, running, noon, newest))
				if !got.Newer || !got.Replaces || !got.DueAt.IsZero() {
					t.Errorf("got %+v, want v9.9.9 offered as a replacement with no wait", got)
				}
				if got.Release.Tag != "v9.9.9" {
					t.Errorf("Release = %q, want the newest, v9.9.9", got.Release.Tag)
				}
				for _, want := range []string{"v9.9.9", "not from a release", "step back", "only when someone asks"} {
					if !strings.Contains(got.Reason, want) {
						t.Errorf("Reason = %q, want it to contain %q", got.Reason, want)
					}
				}
			})
		}
	}
}

// With nothing complete to replace it with, a build that is not from a release
// is told that and not offered a release that cannot be installed.
func TestChooseHasNothingToOfferABuildThatIsNotFromAReleaseWithoutACompleteRelease(t *testing.T) {
	got := Choose(asking(ModeManual, "main-sha-abc1234", noon))
	if got.Newer || got.Replaces {
		t.Errorf("got %+v, want nothing offered", got)
	}
	if !strings.Contains(got.Reason, "No complete release") {
		t.Errorf("Reason = %q, want it to say no complete release is available", got.Reason)
	}
}

// "1.2.x" starts like a release and still cannot be placed against one.
// CompareBuilds answers "differs" rather than guess an order, and a guess here
// would be a downgrade. It is a different fault from a build that is not from a
// release, and the sentence says which -- and what to do about it, since the
// person reading it can run the newest release and make it go away. The release
// is reported here too, as it is for a build that is not from one.
func TestChooseLeavesABuildItCannotOrderAlone(t *testing.T) {
	got := Choose(asking(ModeManual, "1.2.x", noon, published("v1.3.5", noon.Add(-72*time.Hour))))
	if got.Newer || got.DueBy(noon.AddDate(1, 0, 0)) {
		t.Errorf("offered %q to a build that cannot be ordered", got.Release.Tag)
	}
	if got.Release.Tag != "v1.3.5" {
		t.Errorf("Release = %q, want the newest, v1.3.5, reported although it is not offered", got.Release.Tag)
	}
	for _, want := range []string{"v1.2.x", "v1.3.5", "cannot be ordered", "Run a released build such as v1.3.5"} {
		if !strings.Contains(got.Reason, want) {
			t.Errorf("Reason = %q, want it to contain %q", got.Reason, want)
		}
	}
}

// An update that never comes is usually a release still uploading, or a fork
// that publishes differently, and either is quicker to fix when the sentence
// says what a release has to have.
func TestChooseSaysWhatAReleaseNeedsWhenNoneIsComplete(t *testing.T) {
	unfinished := without(published("v1.3.5", noon.Add(-72*time.Hour)), "checksums.txt")
	for _, tc := range []struct {
		name     string
		releases []Release
	}{
		{"no releases listed", nil},
		{"only one that is still uploading", []Release{unfinished}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			got := Choose(asking(ModeManual, "1.3.4", noon, tc.releases...))
			if got.Newer || got.Release.Tag != "" {
				t.Errorf("offered %q with nothing complete to offer", got.Release.Tag)
			}
			for _, want := range []string{"No complete release", "linux/amd64", "publication date", "checksums.txt", "zoomies_linux_amd64"} {
				if !strings.Contains(got.Reason, want) {
					t.Errorf("Reason = %q, want it to contain %q", got.Reason, want)
				}
			}
		})
	}
}

// encoding/json turns a null, a missing or a zero published_at into the zero
// time without an error, and the soak is counted from that date. A release that
// cannot be dated cannot be soaked, so it must not be mistaken for an old one:
// the release below is perfect and the newest, and read as the zero time it
// would have passed the soak at once, in the one mode meant to hold a release
// back. Manual refuses it too, because a release GitHub cannot date is not one
// to offer to anybody.
func TestChooseNeverOffersAReleaseThatHasNoPublicationDate(t *testing.T) {
	dated := published("v1.3.4", noon.Add(-72*time.Hour))
	undated := published("v1.3.5", time.Time{})
	for _, mode := range []Mode{ModeManual, ModeAuto} {
		t.Run(string(mode), func(t *testing.T) {
			inEveryRotation([]Release{dated, undated}, func(rotated []Release) {
				got := Choose(asking(mode, "1.3.3", noon, rotated...))
				if got.Release.Tag != "v1.3.4" || !got.Newer {
					t.Errorf("chose %q (newer: %v) from %s first, want the dated v1.3.4", got.Release.Tag, got.Newer, rotated[0].Tag)
				}
			})

			got := Choose(asking(mode, "1.3.3", noon, undated))
			if got.Newer || got.Release.Tag != "" || got.DueBy(noon.AddDate(1, 0, 0)) {
				t.Errorf("offered %q (newer: %v) when it was the only release and had no date", got.Release.Tag, got.Newer)
			}
			for _, want := range []string{"No complete release", "publication date"} {
				if !strings.Contains(got.Reason, want) {
					t.Errorf("Reason = %q, want it to contain %q", got.Reason, want)
				}
			}
		})
	}
}

// Naming a windows binary a release never carries would send somebody looking
// for a file that nothing here installs, so the sentence says the system is the
// reason.
func TestChooseSaysSoWhenNothingUpdatesOnThisSystem(t *testing.T) {
	in := asking(ModeManual, "1.3.4", noon, published("v1.3.5", noon.Add(-72*time.Hour)))
	in.GOOS = "windows"
	got := Choose(in)
	if got.Newer || got.Release.Tag != "" {
		t.Errorf("offered %q on windows", got.Release.Tag)
	}
	for _, want := range []string{"linux and darwin", "windows/amd64"} {
		if !strings.Contains(got.Reason, want) {
			t.Errorf("Reason = %q, want it to contain %q", got.Reason, want)
		}
	}
	if strings.Contains(got.Reason, "zoomies_windows") {
		t.Errorf("Reason = %q, which names a binary nothing would download", got.Reason)
	}
}

// In manual mode the person pressing the button is the soak, so the wait the
// platform chose for auto must not hold them back: the release below went public
// a minute ago, the soak is a day, and it is theirs to take. The rule says so by
// giving no due time at all.
func TestChooseManualTakesTheNewestAtOnce(t *testing.T) {
	older := published("v1.3.4", noon.Add(-48*time.Hour))
	newest := published("v1.3.5", noon.Add(-time.Minute))
	got := Choose(asking(ModeManual, "1.3.4", noon, older, newest))
	if !got.Newer || got.Release.Tag != "v1.3.5" {
		t.Fatalf("Release = %q, newer = %v; want v1.3.5 and newer", got.Release.Tag, got.Newer)
	}
	if !got.DueAt.IsZero() {
		t.Errorf("DueAt = %s, want none: manual has no wait", got.DueAt)
	}
	if !got.DueBy(noon) {
		t.Error("not due in manual mode a minute after the release")
	}
	for _, want := range []string{"v1.3.5", "v1.3.4", "manual"} {
		if !strings.Contains(got.Reason, want) {
			t.Errorf("Reason = %q, want it to contain %q", got.Reason, want)
		}
	}
}

// The soak counts from the day GitHub published the release, so the sentence is
// the whole of what an operator needs: how long it has been public, how long
// auto waits, and how long is left.
func TestChooseAutoWaitsForTheSoak(t *testing.T) {
	r := published("v1.3.5", noon.Add(-6*time.Hour))
	got := Choose(asking(ModeAuto, "1.3.4", noon, r))
	if !got.Newer || got.Release.Tag != "v1.3.5" {
		t.Fatalf("Release = %q, newer = %v; want v1.3.5 and newer", got.Release.Tag, got.Newer)
	}
	if want := r.PublishedAt.Add(24 * time.Hour); !got.DueAt.Equal(want) {
		t.Errorf("DueAt = %s, want %s: the publication plus the soak", got.DueAt, want)
	}
	if got.DueBy(noon) {
		t.Error("due six hours into a soak of twenty-four")
	}
	const want = "Waiting: v1.3.5 has been public for 6 hours and auto waits for 24; it can be taken in 18 hours."
	if got.Reason != want {
		t.Errorf("Reason = %q, want %q", got.Reason, want)
	}
}

// "Is it due" is asked in one place, DueBy, and the sentence asks it too, so
// what the status says and what the planner does cannot disagree about the
// instant the wait ends. The wait is over at that instant, not after it, and a
// nanosecond earlier it is not.
func TestChooseAutoIsDueExactlyAtTheBoundary(t *testing.T) {
	r := published("v1.3.5", noon.Add(-6*time.Hour))
	due := Choose(asking(ModeAuto, "1.3.4", noon, r)).DueAt
	target := Choose(asking(ModeAuto, "1.3.4", due, r))

	if !target.DueBy(due) {
		t.Error("not due at the instant the soak ends")
	}
	if target.DueBy(due.Add(-time.Nanosecond)) {
		t.Error("due a nanosecond before the soak ends")
	}
	if !strings.HasPrefix(target.Reason, "Ready:") {
		t.Errorf("Reason at the boundary = %q, want it to start Ready:", target.Reason)
	}
	if early := Choose(asking(ModeAuto, "1.3.4", due.Add(-time.Nanosecond), r)); !strings.HasPrefix(early.Reason, "Waiting:") {
		t.Errorf("Reason a nanosecond early = %q, want it to start Waiting:", early.Reason)
	}
}

// The cost of the soak is that a release replaced inside it is never taken, and
// that is the point: v1.3.1 has been public for 25 hours here and would be due,
// but v1.3.2 landed four and a half hours after it, so the controller waits a
// day from v1.3.2 instead. v1.3.1 is not the target at any time, whichever way
// round GitHub lists the two, and the sentence says it was skipped: an operator
// looking at a release that has been public for 25 hours will ask why it was
// not taken.
func TestANewerReleaseRestartsTheSoak(t *testing.T) {
	t0 := time.Date(2026, 10, 6, 7, 0, 0, 0, time.UTC)
	first := published("v1.3.1", t0)
	second := published("v1.3.2", t0.Add(4*time.Hour+26*time.Minute))
	ends := second.PublishedAt.Add(24 * time.Hour)
	now := t0.Add(25 * time.Hour)

	inEveryRotation([]Release{first, second}, func(rotated []Release) {
		got := Choose(asking(ModeAuto, "1.3.0", now, rotated...))
		if got.Release.Tag != "v1.3.2" {
			t.Fatalf("target = %q from %s first, want v1.3.2", got.Release.Tag, rotated[0].Tag)
		}
		if !got.DueAt.Equal(ends) {
			t.Errorf("DueAt = %s, want %s: a day from v1.3.2's own publication", got.DueAt, ends)
		}
		if got.DueBy(now) {
			t.Error("due at 25 hours, which only v1.3.1 had waited for")
		}
		const want = "Waiting: v1.3.2 has been public for 20 hours and auto waits for 24; it can be taken in 3 hours. It replaced v1.3.1, which is skipped, and a newer release would start the wait again."
		if got.Reason != want {
			t.Errorf("Reason = %q, want %q", got.Reason, want)
		}
		for _, hours := range []int{5, 24, 25, 28, 29, 100} {
			at := t0.Add(time.Duration(hours) * time.Hour)
			if tag := Choose(asking(ModeAuto, "1.3.0", at, rotated...)).Release.Tag; tag != "v1.3.2" {
				t.Errorf("target = %q at %d hours, want v1.3.2 whenever it is asked", tag, hours)
			}
		}
		if !Choose(asking(ModeAuto, "1.3.0", ends, rotated...)).DueBy(ends) {
			t.Error("v1.3.2 is not due once its own day has passed")
		}
	})
}

// The price of the soak is that a project publishing faster than the wait is
// never updated by auto, and the sentence has to be the thing that says so. Five
// releases about five hours apart, 25 hours after the first: only the one just
// before the target is named, because the earlier ones were pushed aside by it
// in turn and a list of them would grow with every release.
func TestOnlyTheReleaseJustBeforeTheTargetIsNamedAsSkipped(t *testing.T) {
	t0 := time.Date(2026, 10, 6, 7, 0, 0, 0, time.UTC)
	releases := []Release{
		published("v1.3.1", t0),
		published("v1.3.2", t0.Add(5*time.Hour)),
		published("v1.3.3", t0.Add(10*time.Hour)),
		published("v1.3.4", t0.Add(15*time.Hour)),
		published("v1.3.5", t0.Add(19*time.Hour)),
	}
	now := t0.Add(25 * time.Hour)

	const want = "Waiting: v1.3.5 has been public for 6 hours and auto waits for 24; it can be taken in 18 hours. It replaced v1.3.4, which is skipped, and a newer release would start the wait again."
	inEveryRotation(releases, func(rotated []Release) {
		if got := Choose(asking(ModeAuto, "1.3.0", now, rotated...)); got.Reason != want {
			t.Errorf("Reason = %q from %s first, want %q", got.Reason, rotated[0].Tag, want)
		}
	})
}

// "It replaced v1.3.4, which is skipped" is true only of a release that could
// have been taken and was passed over. One that is already installed, older than
// what is running, or never complete, dated or final was never in the way, and
// naming it would send an operator looking for a release that cannot exist. In
// each case the sentence is the plain one, byte for byte.
func TestAReleaseThatWasNeverInTheWayIsNotCalledSkipped(t *testing.T) {
	const plain = "Waiting: v1.3.5 has been public for 6 hours and auto waits for 24; it can be taken in 18 hours."
	target := published("v1.3.5", noon.Add(-6*time.Hour))
	draft := published("v1.3.4", noon.Add(-20*time.Hour))
	draft.Draft = true
	prerelease := published("v1.3.4", noon.Add(-20*time.Hour))
	prerelease.Prerelease = true

	for _, tc := range []struct {
		name    string
		running string
		others  []Release
	}{
		{"nothing else was published", "1.3.4", nil},
		{"the only other release is the one running", "1.3.4", []Release{published("v1.3.4", noon.Add(-30*time.Hour))}},
		{"the only other release is older than the one running", "1.3.4", []Release{published("v1.3.2", noon.Add(-30*time.Hour))}},
		{"the other release is the target's own version, made again", "1.3.4", []Release{published("v1.3.5", noon.Add(-30*time.Hour))}},
		{"the release between is still uploading", "1.3.3", []Release{without(published("v1.3.4", noon.Add(-20*time.Hour)), "checksums.txt")}},
		{"the release between is a draft", "1.3.3", []Release{draft}},
		{"the release between is a prerelease", "1.3.3", []Release{prerelease}},
		{"the release between has no date", "1.3.3", []Release{published("v1.3.4", time.Time{})}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			inEveryRotation(append([]Release{target}, tc.others...), func(rotated []Release) {
				if got := Choose(asking(ModeAuto, tc.running, noon, rotated...)); got.Reason != plain {
					t.Errorf("Reason = %q from %s first, want the plain %q", got.Reason, rotated[0].Tag, plain)
				}
			})
		})
	}
}

// The second sentence belongs to a wait that was restarted and to nothing else.
// Once the wait is over the release is on its way and there is nothing to
// explain; a release dated in the future has not started a wait at all; and
// manual has no wait to restart, so a person asking is told what is there
// without a history of what auto would have done. Each of these has a skipped
// release in the list, which is what would tempt a careless rule to mention it.
func TestTheRestartIsOnlyMentionedWhileAutoIsWaiting(t *testing.T) {
	t0 := time.Date(2026, 10, 6, 7, 0, 0, 0, time.UTC)
	first := published("v1.3.1", t0)
	second := published("v1.3.2", t0.Add(4*time.Hour+26*time.Minute))
	ends := second.PublishedAt.Add(24 * time.Hour)

	for _, tc := range []struct {
		name string
		mode Mode
		now  time.Time
		want string
	}{
		{"the wait is over", ModeAuto, ends, "Ready: v1.3.2 has been public for 24 hours and auto waits for 24; it can be taken now."},
		{"the release is dated in the future", ModeAuto, t0.Add(time.Hour), "Waiting: v1.3.2 is dated in the future, so it does not count as public yet; it can be taken in 27 hours."},
		{"manual", ModeManual, t0.Add(25 * time.Hour), "Available: v1.3.2 is newer than the v1.3.0 running now; manual mode waits for someone to update."},
	} {
		t.Run(tc.name, func(t *testing.T) {
			inEveryRotation([]Release{first, second}, func(rotated []Release) {
				if got := Choose(asking(tc.mode, "1.3.0", tc.now, rotated...)); got.Reason != tc.want {
					t.Errorf("Reason = %q from %s first, want %q", got.Reason, rotated[0].Tag, tc.want)
				}
			})
		})
	}
}

// GitHub's clock and this controller's can disagree, and a release can be
// dated ahead on purpose. Either way it has not been public yet, so the wait
// has not started. The sentence must not show a negative age, which would read
// as "public for -1 hours".
func TestChooseTreatsAFuturePublishedAtAsNotYetDue(t *testing.T) {
	r := published("v1.3.5", noon.Add(time.Hour))
	got := Choose(asking(ModeAuto, "1.3.4", noon, r))
	if !got.Newer {
		t.Fatal("a release dated in the future was not offered as newer; it should be, and merely not yet due")
	}
	if got.DueBy(noon) {
		t.Error("due before the release was published")
	}
	if want := r.PublishedAt.Add(24 * time.Hour); !got.DueAt.Equal(want) {
		t.Errorf("DueAt = %s, want %s: the soak still counts from the date GitHub gave", got.DueAt, want)
	}
	if strings.Contains(got.Reason, "-") {
		t.Errorf("Reason = %q, which shows a negative number", got.Reason)
	}
	for _, want := range []string{"v1.3.5", "dated in the future", "25 hours"} {
		if !strings.Contains(got.Reason, want) {
			t.Errorf("Reason = %q, want it to contain %q", got.Reason, want)
		}
	}
}

// The sentence is read at a glance and recomputed on every pass, so it says
// whole units and rounds down: a release is never said to have waited longer than
// it has, and the unit of the soak is left off when the age has just said it.
func TestChooseReasonsRoundDurationsDown(t *testing.T) {
	const day = 24 * time.Hour
	for _, tc := range []struct {
		name      string
		age, soak time.Duration
		want      string
	}{
		{"just published", 0, day, "Waiting: v1.3.5 has been public for less than a minute and auto waits for 24 hours; it can be taken in 24 hours."},
		{"a few seconds in", 59 * time.Second, day, "Waiting: v1.3.5 has been public for less than a minute and auto waits for 24 hours; it can be taken in 23 hours."},
		{"one minute in", time.Minute, day, "Waiting: v1.3.5 has been public for 1 minute and auto waits for 24 hours; it can be taken in 23 hours."},
		{"a second short of an hour", time.Hour - time.Second, day, "Waiting: v1.3.5 has been public for 59 minutes and auto waits for 24 hours; it can be taken in 23 hours."},
		{"an hour in", time.Hour, day, "Waiting: v1.3.5 has been public for 1 hour and auto waits for 24; it can be taken in 23 hours."},
		{"a second short of two hours", 2*time.Hour - time.Second, day, "Waiting: v1.3.5 has been public for 1 hour and auto waits for 24; it can be taken in 22 hours."},
		{"an hour from the end", 23 * time.Hour, day, "Waiting: v1.3.5 has been public for 23 hours and auto waits for 24; it can be taken in 1 hour."},
		{"a minute from the end", day - time.Minute, day, "Waiting: v1.3.5 has been public for 23 hours and auto waits for 24; it can be taken in 1 minute."},
		{"half a minute from the end", day - 30*time.Second, day, "Waiting: v1.3.5 has been public for 23 hours and auto waits for 24; it can be taken in less than a minute."},
		{"a soak in minutes", 10 * time.Minute, 30 * time.Minute, "Waiting: v1.3.5 has been public for 10 minutes and auto waits for 30; it can be taken in 20 minutes."},
		{"a soak of an hour and a half", 30 * time.Minute, 90 * time.Minute, "Waiting: v1.3.5 has been public for 30 minutes and auto waits for 1 hour; it can be taken in 1 hour."},
		{"a soak of an hour", 10 * time.Minute, time.Hour, "Waiting: v1.3.5 has been public for 10 minutes and auto waits for 1 hour; it can be taken in 50 minutes."},
		{"an hour against a soak of an hour", time.Hour, time.Hour, "Ready: v1.3.5 has been public for 1 hour and auto waits for 1 hour; it can be taken now."},
		{"the day is up", day, day, "Ready: v1.3.5 has been public for 24 hours and auto waits for 24; it can be taken now."},
		{"long past the soak", 26 * time.Hour, day, "Ready: v1.3.5 has been public for 26 hours and auto waits for 24; it can be taken now."},
		{"no soak at all", 5 * time.Minute, 0, "Ready: v1.3.5 has been public for 5 minutes and auto does not wait; it can be taken now."},
	} {
		t.Run(tc.name, func(t *testing.T) {
			in := asking(ModeAuto, "1.3.4", noon, published("v1.3.5", noon.Add(-tc.age)))
			in.Soak = tc.soak
			got := Choose(in)
			if got.Reason != tc.want {
				t.Errorf("Reason = %q, want %q", got.Reason, tc.want)
			}
			if want := noon.Add(-tc.age).Add(tc.soak); !got.DueAt.Equal(want) {
				t.Errorf("DueAt = %s, want %s", got.DueAt, want)
			}
		})
	}
}

package updates

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"regexp"
	"strings"
	"time"
	"unicode"
)

// The two documents the service and the helper exchange through the update
// folder. They are here, with no file in sight, so that both sides parse the same
// bytes the same way: the service refuses to write what the helper would refuse,
// and the helper treats what it reads as hostile.
const (
	// WireVersion is the "v" both documents carry. A release that changes either
	// shape has to refresh the helper's unit, because nothing else will.
	WireVersion = 1
	// MaxRequestBytes bounds a request. The real document is a couple of hundred
	// bytes; the rest is room for a long requested_by and no more.
	MaxRequestBytes = 4096
	// MaxLogTailBytes bounds the tail of the engine's output a result carries, so
	// that a failed upgrade can say why without the result becoming a log store.
	MaxLogTailBytes = 16384

	// maxRequestIDLength bounds an id so that it stays a name and not a payload.
	maxRequestIDLength = 64
	// maxRequestedByLength bounds who asked, which the helper writes into a log
	// root owns: room for any account name, and none for a payload.
	maxRequestedByLength = 128
)

// Request asks the helper to take this host to one release. It names exactly one
// thing, and holds no URL, path, command or flag: the release source and the
// binary come from the helper's own root-owned environment, never from here.
type Request struct {
	V int `json:"v"`
	// ID is the attempt's id, which the result echoes so that the controller can
	// tell its own answer from one left over from before.
	ID  string `json:"id"`
	Tag string `json:"tag"`
	// RequestedBy is who pressed the button, for the helper's log. It is never
	// acted on.
	RequestedBy string    `json:"requested_by"`
	RequestedAt time.Time `json:"requested_at"`
}

// Result is the helper's answer to one request, written whether the upgrade ran,
// failed, or was refused before it started.
type Result struct {
	V  int    `json:"v"`
	ID string `json:"id"`
	OK bool   `json:"ok"`
	// Tag is the release asked for; From and To are the versions before and after
	// as the helper observed them, and To is empty when nothing changed.
	Tag  string `json:"tag"`
	From string `json:"from"`
	To   string `json:"to"`
	// Error is the sentence an operator reads when OK is false.
	Error string `json:"error"`
	// Backup is the directory of the copy the engine took before it changed
	// anything, empty when none was taken. It is what a page offers to restore
	// from after a failed update.
	Backup string `json:"backup"`
	// RolledBack says the engine put the previous release back because the new
	// one did not answer. The attempt is then a failure that was undone rather
	// than one left in place, which is a different thing to tell an operator.
	RolledBack bool `json:"rolled_back"`
	// LogTail is the end of the engine's output, at most MaxLogTailBytes.
	LogTail    string    `json:"log_tail"`
	StartedAt  time.Time `json:"started_at"`
	FinishedAt time.Time `json:"finished_at"`
}

// requestIDPattern is what store.NewID("upd") makes: the prefix, an underscore
// and lowercase base32. It is spelled out here because this package cannot
// import the store.
var requestIDPattern = regexp.MustCompile(`^upd_[a-z0-9]+$`)

// ParseRequest reads one request and refuses anything but the documented shape.
//
// The checks run cheapest first, and the length before anything is decoded, so a
// large file costs a comparison. Unknown fields are an error and not a shrug: a
// field the helper does not know is something the writer hoped it would act on.
//
// encoding/json matches a field name without regard to case and, for a name that
// appears twice, keeps the last value. Neither is refused here, because every
// value is checked after decoding and the helper acts only on what this function
// returns, so there is no second reading of the document for the two to disagree.
func ParseRequest(body []byte) (Request, error) {
	if len(body) > MaxRequestBytes {
		return Request{}, fmt.Errorf("the request is %d bytes, over the limit of %d", len(body), MaxRequestBytes)
	}
	dec := json.NewDecoder(bytes.NewReader(body))
	dec.DisallowUnknownFields()
	var r Request
	if err := dec.Decode(&r); err != nil {
		return Request{}, fmt.Errorf("the request is not the document the helper reads: %w", err)
	}
	// A second document after the first is not part of the request, and the
	// decoder alone would stop at the end of the first.
	if _, err := dec.Token(); !errors.Is(err, io.EOF) {
		return Request{}, errors.New("the request has more in it than one document")
	}
	if r.V != WireVersion {
		return Request{}, fmt.Errorf("the request is version %d and this helper reads version %d", r.V, WireVersion)
	}
	if len(r.ID) > maxRequestIDLength || !requestIDPattern.MatchString(r.ID) {
		return Request{}, fmt.Errorf("the request id %q is not an update attempt id: upd_ followed by lowercase letters and digits, at most %d characters", r.ID, maxRequestIDLength)
	}
	if !ValidWireTag(r.Tag) {
		return Request{}, fmt.Errorf("the tag %q is not a release tag of the form vMAJOR.MINOR.PATCH, or dev", r.Tag)
	}
	// requested_by is only ever logged, but it is logged by root: a newline in it
	// would let the less privileged side write a line of root's log, and an escape
	// sequence would repaint the terminal of whoever reads it. The length is
	// checked first so that the refusal below quotes at most this much.
	if len(r.RequestedBy) > maxRequestedByLength {
		return Request{}, fmt.Errorf("requested_by is %d bytes, over the limit of %d", len(r.RequestedBy), maxRequestedByLength)
	}
	// Printable characters only, not merely no control characters: a right-to-left
	// override reorders what the reader sees, and a line or paragraph separator
	// ends a line in some viewers, and neither is a control character.
	if strings.ContainsFunc(r.RequestedBy, func(c rune) bool { return !unicode.IsGraphic(c) }) {
		return Request{}, fmt.Errorf("requested_by %q has a character in it that is not printable, which a log line must not carry", r.RequestedBy)
	}
	// encoding/json leaves a missing or null time as the zero time without an
	// error, and a request that cannot say when it was made cannot be placed in
	// the log against the attempt that made it.
	if r.RequestedAt.IsZero() {
		return Request{}, errors.New("the request has no requested_at, so it cannot say when it was made")
	}
	return r, nil
}

package updates

import (
	"strings"
	"testing"
	"time"
)

const documentedRequest = `{ "v": 1, "id": "upd_k3fqz2mx7abcd", "tag": "v1.3.5",
  "requested_by": "user:alice", "requested_at": "2026-10-08T09:00:00Z" }`

func TestParseRequestAcceptsTheDocumentedShape(t *testing.T) {
	got, err := ParseRequest([]byte(documentedRequest))
	if err != nil {
		t.Fatalf("ParseRequest: %v", err)
	}
	want := Request{
		V: 1, ID: "upd_k3fqz2mx7abcd", Tag: "v1.3.5", RequestedBy: "user:alice",
		RequestedAt: time.Date(2026, 10, 8, 9, 0, 0, 0, time.UTC),
	}
	if got.V != want.V || got.ID != want.ID || got.Tag != want.Tag || got.RequestedBy != want.RequestedBy || !got.RequestedAt.Equal(want.RequestedAt) {
		t.Fatalf("ParseRequest = %+v, want %+v", got, want)
	}
}

// The request is the one thing the less privileged side hands to root, so a
// field the helper does not know is a field somebody hoped it would act on. A
// URL, a path or a flag has to be refused loudly, not ignored.
func TestParseRequestRefusesAnUnknownField(t *testing.T) {
	for _, field := range []string{`"url": "https://example.com/zoomies"`, `"flags": ["--yes"]`, `"path": "/tmp/x"`} {
		doc := `{"v":1,"id":"upd_k3fqz2mx7abcd","tag":"v1.3.5","requested_by":"user:alice","requested_at":"2026-10-08T09:00:00Z",` + field + `}`
		if _, err := ParseRequest([]byte(doc)); err == nil {
			t.Errorf("a request carrying %s was accepted", field)
		}
	}
}

func TestParseRequestRefusesAnythingAfterTheDocument(t *testing.T) {
	if _, err := ParseRequest([]byte(documentedRequest + `{"v":1}`)); err == nil {
		t.Error("a second document after the first was accepted")
	}
	if _, err := ParseRequest([]byte(documentedRequest + "\n")); err != nil {
		t.Errorf("a trailing newline was refused: %v", err)
	}
}

func TestParseRequestRefusesAWireVersionItDoesNotKnow(t *testing.T) {
	for _, v := range []string{`"v": 2,`, `"v": 0,`, ``} {
		doc := `{` + v + `"id":"upd_k3fqz2mx7abcd","tag":"v1.3.5","requested_by":"user:alice","requested_at":"2026-10-08T09:00:00Z"}`
		_, err := ParseRequest([]byte(doc))
		if err == nil {
			t.Errorf("version field %q was accepted", v)
		}
	}
}

func TestParseRequestAcceptsTheDevChannel(t *testing.T) {
	doc := `{"v":1,"id":"upd_k3fqz2mx7abcd","tag":"dev","requested_by":"user:alice","requested_at":"2026-10-08T09:00:00Z"}`
	if _, err := ParseRequest([]byte(doc)); err != nil {
		t.Errorf("a request for the dev channel was refused: %v", err)
	}
}

func TestParseRequestRefusesABadTag(t *testing.T) {
	for _, tag := range []string{
		"", "1.3.5", "v1.3", "v1.3.5.1", "V1.3.5", "v1.3.5-rc1", "v1.3.5+build", "latest", "Dev", "dev ", "main-sha-abc1234",
		"v1.3.5\n", " v1.3.5", "v1.3.5 --yes", "../v1.3.5", "v1.3.5/../../x", "v1.3.x",
	} {
		doc := `{"v":1,"id":"upd_k3fqz2mx7abcd","tag":` + quote(tag) + `,"requested_by":"user:alice","requested_at":"2026-10-08T09:00:00Z"}`
		if _, err := ParseRequest([]byte(doc)); err == nil {
			t.Errorf("tag %q was accepted", tag)
		}
	}
}

func TestParseRequestRefusesABodyOverFourKilobytes(t *testing.T) {
	// Leading spaces keep the document valid JSON, so the size is the only
	// thing wrong with it.
	pad := func(n int) []byte {
		return []byte(strings.Repeat(" ", n-len(documentedRequest)) + documentedRequest)
	}
	if _, err := ParseRequest(pad(MaxRequestBytes)); err != nil {
		t.Errorf("a body of exactly %d bytes was refused: %v", MaxRequestBytes, err)
	}
	body := pad(MaxRequestBytes + 1)
	if len(body) != 4097 {
		t.Fatalf("test body is %d bytes, want 4097", len(body))
	}
	if _, err := ParseRequest(body); err == nil {
		t.Error("a body of 4097 bytes was accepted")
	}
}

func TestParseRequestRefusesAnEmptyOrOverlongID(t *testing.T) {
	tooLong := "upd_" + strings.Repeat("a", 61) // 65 characters
	if len(tooLong) != 65 {
		t.Fatalf("test id is %d characters, want 65", len(tooLong))
	}
	for _, id := range []string{"", tooLong, "upd_", "k3fqz2mx7abcd", "UPD_k3fqz2mx7abcd", "upd_K3FQ", "upd_k3 fq", "upd_../x", "upd_k3fq\n"} {
		doc := `{"v":1,"id":` + quote(id) + `,"tag":"v1.3.5","requested_by":"user:alice","requested_at":"2026-10-08T09:00:00Z"}`
		if _, err := ParseRequest([]byte(doc)); err == nil {
			t.Errorf("id %q was accepted", id)
		}
	}
	longest := "upd_" + strings.Repeat("a", 60) // 64 characters
	doc := `{"v":1,"id":"` + longest + `","tag":"v1.3.5","requested_by":"user:alice","requested_at":"2026-10-08T09:00:00Z"}`
	if _, err := ParseRequest([]byte(doc)); err != nil {
		t.Errorf("an id of 64 characters was refused: %v", err)
	}
}

// requested_by is never acted on, but the helper writes it into a log root
// owns. A newline in it would let the less privileged side write a line of
// root's, and an escape sequence would let it repaint the terminal reading it.
func TestParseRequestRefusesARequestedByThatCouldForgeALogLine(t *testing.T) {
	for _, by := range []string{
		strings.Repeat("a", 129), "user:alice\n", "user:alice\rforged", "user:\x00alice",
		"user:\x1b[31malice", "user:alice\x7f", "user:\talice", "user:alice\u0085",
		// Not control characters, and no better in a log: a right-to-left
		// override reorders what the reader sees, and the separators end a line
		// in some viewers.
		"user:\u202eecila", "user:alice\u2028forged", "user:alice\u2029forged", "user:al\u200bice",
	} {
		doc := `{"v":1,"id":"upd_k3fqz2mx7abcd","tag":"v1.3.5","requested_by":` + quote(by) + `,"requested_at":"2026-10-08T09:00:00Z"}`
		if _, err := ParseRequest([]byte(doc)); err == nil {
			t.Errorf("requested_by %q was accepted", by)
		}
	}
	for _, by := range []string{"", "user:alice", "user:zoë", "user:alice smith", strings.Repeat("a", 128)} {
		doc := `{"v":1,"id":"upd_k3fqz2mx7abcd","tag":"v1.3.5","requested_by":` + quote(by) + `,"requested_at":"2026-10-08T09:00:00Z"}`
		if _, err := ParseRequest([]byte(doc)); err != nil {
			t.Errorf("requested_by %q was refused: %v", by, err)
		}
	}
}

// A request with no time cannot be placed in the helper's log or against the
// attempt that made it, and encoding/json yields the zero time for a missing
// field without complaint.
func TestParseRequestRefusesARequestWithNoRequestedAt(t *testing.T) {
	for _, at := range []string{``, `,"requested_at":"0001-01-01T00:00:00Z"`, `,"requested_at":null`} {
		doc := `{"v":1,"id":"upd_k3fqz2mx7abcd","tag":"v1.3.5","requested_by":"user:alice"` + at + `}`
		if _, err := ParseRequest([]byte(doc)); err == nil {
			t.Errorf("requested_at %q was accepted", at)
		}
	}
}

func TestParseRequestRefusesWhatIsNotJSON(t *testing.T) {
	for _, body := range []string{"", "null", "[]", `"v1.3.5"`, "{", "not json"} {
		if _, err := ParseRequest([]byte(body)); err == nil {
			t.Errorf("%q was accepted", body)
		}
	}
}

// quote writes s as a JSON string without the encoder, so a test table can hold
// a newline or a quote and still say exactly what reached the parser.
func quote(s string) string {
	r := strings.NewReplacer(`\`, `\\`, `"`, `\"`, "\n", `\n`, "\r", `\r`, "\t", `\t`, "\x00", `\u0000`, "\x1b", `\u001b`)
	return `"` + r.Replace(s) + `"`
}

package version

import (
	"regexp"
	"strconv"
	"strings"
)

// Skew is how one build relates to another.
type Skew string

const (
	// SkewNone means the two are the same release.
	SkewNone Skew = ""
	// SkewBehind means the first build is an earlier release than the second.
	SkewBehind Skew = "behind"
	// SkewAhead means it is a later one, which for an agent against its
	// controller is the direction nobody tests.
	SkewAhead Skew = "ahead"
	// SkewDiffers means they are not the same and nothing here can say which
	// came first: a development build, a fork's tag, anything not shaped like
	// a release. Saying "differs" is the honest answer, and it is still worth
	// saying -- a fleet running two builds is a fleet whose behaviour has two
	// explanations.
	SkewDiffers Skew = "differs"
)

// CompareBuilds says how build a stands to build b.
//
// It compares releases, not commits. Two builds of one tag are the same
// release: a fleet where they differ has been rebuilt, which is worth knowing
// in a bug report and is not skew, and treating it as skew made every
// development fleet warn about itself constantly.
//
// The parser is deliberately small. It understands the shape this project
// tags -- v0.1-alpha, v1.2.3, 1.2 -- and answers SkewDiffers for anything
// else rather than guessing an order it cannot defend. A wrong order is worse
// than no order: it would tell an operator to upgrade the wrong side.
func CompareBuilds(a, b string) Skew {
	a, b = strings.TrimSpace(a), strings.TrimSpace(b)
	if a == "" || b == "" || a == b {
		return SkewNone
	}
	na, oka := parseRelease(a)
	nb, okb := parseRelease(b)
	if !oka || !okb {
		return SkewDiffers
	}
	for i := range na.parts {
		switch {
		case na.parts[i] < nb.parts[i]:
			return SkewBehind
		case na.parts[i] > nb.parts[i]:
			return SkewAhead
		}
	}
	// Same numbers, different text: a pre-release against the release it leads
	// to. "v1.0-rc1" is behind "v1.0", and an empty pre-release is the later
	// of the two, which is the one rule of pre-release ordering that matters
	// here and the one this project's own tags need.
	switch {
	case na.pre == nb.pre:
		// The same release written two ways -- "v1.2" and "v1.2.0", or with
		// and without the leading v. A person reading the two would say they
		// match, and so does this.
		return SkewNone
	case na.pre == "":
		return SkewAhead
	case nb.pre == "":
		return SkewBehind
	case na.pre < nb.pre:
		return SkewBehind
	default:
		return SkewAhead
	}
}

// release is a tag broken into the three numbers and whatever followed them.
type release struct {
	parts [3]int
	pre   string
}

// parseRelease reads "v1.2.3-rc1" and its shorter forms. Missing numbers are
// zero, so "v1.2" and "v1.2.0" are the same release, which is what a person
// reading the two would say.
func parseRelease(s string) (release, bool) {
	var out release
	s = strings.TrimPrefix(strings.TrimSpace(s), "v")
	if s == "" {
		return out, false
	}
	// The pre-release marker is the first hyphen or plus after the numbers.
	if i := strings.IndexAny(s, "-+"); i >= 0 {
		out.pre, s = s[i+1:], s[:i]
	}
	fields := strings.Split(s, ".")
	if len(fields) == 0 || len(fields) > 3 {
		return out, false
	}
	for i, f := range fields {
		n, err := strconv.Atoi(f)
		if err != nil || n < 0 {
			return out, false
		}
		out.parts[i] = n
	}
	return out, true
}

// releaseLike matches a version stamped from a release tag: 0.2-beta, v1.4.0.
// A build from main is stamped main-sha-abc1234 and matches nothing here.
var releaseLike = regexp.MustCompile(`^v?\d+\.\d+`)

// describeSuffix matches what `git describe` adds to a tag once commits have
// landed on top of it -- v0.2-beta-5-gabc1234 -- which is a local build of
// something past that release rather than the release itself.
var describeSuffix = regexp.MustCompile(`-\d+-g[0-9a-f]{7,}(-dirty)?$`)

// mainBuild matches the version CI stamps into every artifact built from the
// default branch. The moving dev tag carries those artifacts; the commit in
// the stamp is still what makes two concrete builds distinguishable.
var mainBuild = regexp.MustCompile(`^main-sha-[0-9a-f]{7,}$`)

// IsMainBuild says whether v is stamped from a commit on main, such as
// main-sha-abc1234. Two such builds cannot be ordered, only told apart.
func IsMainBuild(v string) bool { return mainBuild.MatchString(strings.TrimSpace(v)) }

// Release reports the release a build came from, and whether it came from one
// at all.
//
// Two callers need the same answer for different reasons, which is why it lives
// here rather than beside either of them. The update check asks so that it does
// not tell a controller running :dev -- stamped main-sha-abc1234, and usually
// *ahead* of the newest release -- to downgrade. InstallTag builds on the same
// answer to distinguish immutable versioned releases from the moving dev
// channel.
func Release(v string) (string, bool) {
	v = strings.TrimSpace(v)
	if v == "" || !releaseLike.MatchString(v) || describeSuffix.MatchString(v) {
		return "", false
	}
	return strings.TrimPrefix(v, "v"), true
}

// InstallTag returns the downloadable channel that carries this build.
//
// Releases have an immutable v-prefixed tag. Builds from main share the moving
// dev tag, which CI updates for the binary and every stock image on each push.
// A local git-describe build has neither, so callers must not pretend it can be
// downloaded from this repository.
func InstallTag(v string) (string, bool) {
	v = strings.TrimSpace(v)
	if release, ok := Release(v); ok {
		return "v" + release, true
	}
	if v == "dev" || mainBuild.MatchString(v) {
		return "dev", true
	}
	return "", false
}

// Channel is the image/download tag operators should use for this build, or
// empty for a local or otherwise unpublished build.
func Channel(v string) string {
	tag, _ := InstallTag(v)
	return tag
}

package version

import "testing"

// The comparison exists to tell an operator which side to upgrade, so the
// answer it must never get wrong is the direction. A wrong order sends them to
// the wrong machine; "differs" sends them to look, which is always safe.
func TestCompareBuildsOrdersReleasesAndRefusesToGuess(t *testing.T) {
	cases := []struct {
		a, b string
		want Skew
	}{
		// The same release, however it is written.
		{"v1.2.3", "v1.2.3", SkewNone},
		{"v1.2", "v1.2.0", SkewNone},
		{"1.2.3", "v1.2.3", SkewNone},
		{"", "v1.2.3", SkewNone},
		{"v1.2.3", "", SkewNone},

		// Ordered.
		{"v1.2.3", "v1.2.4", SkewBehind},
		{"v1.2.4", "v1.2.3", SkewAhead},
		{"v1.2.3", "v1.3.0", SkewBehind},
		{"v2.0.0", "v1.9.9", SkewAhead},
		{"v0.1-alpha", "v0.2", SkewBehind},

		// A pre-release leads to the release it names.
		{"v1.0-rc1", "v1.0", SkewBehind},
		{"v1.0", "v1.0-rc1", SkewAhead},
		{"v1.0-rc1", "v1.0-rc2", SkewBehind},

		// Two builds of one tag are the same release. Treating a rebuild as
		// skew made every development fleet warn about itself.
		{"dev", "dev", SkewNone},

		// Nothing here can order these, and guessing would be worse than
		// saying so.
		{"dev", "v1.2.3", SkewDiffers},
		{"v1.2.3", "some-fork-build", SkewDiffers},
		{"v1.2.3.4", "v1.2.3", SkewDiffers},
		{"v1.x", "v1.2", SkewDiffers},
	}

	for _, tc := range cases {
		if got := CompareBuilds(tc.a, tc.b); got != tc.want {
			t.Errorf("CompareBuilds(%q, %q) = %q, want %q", tc.a, tc.b, got, tc.want)
		}
	}
}

// Whatever the pair, reversing it reverses the answer. It is the property a
// direction has to have, and the one a hand-written comparator loses first.
func TestCompareBuildsIsSymmetric(t *testing.T) {
	opposite := map[Skew]Skew{
		SkewNone: SkewNone, SkewDiffers: SkewDiffers,
		SkewBehind: SkewAhead, SkewAhead: SkewBehind,
	}
	builds := []string{"", "dev", "v0.1-alpha", "v0.1", "v0.2", "v1.0-rc1", "v1.0", "v1.2.3", "weird"}
	for _, a := range builds {
		for _, b := range builds {
			forward, back := CompareBuilds(a, b), CompareBuilds(b, a)
			if back != opposite[forward] {
				t.Errorf("CompareBuilds(%q,%q) = %q but CompareBuilds(%q,%q) = %q", a, b, forward, b, a, back)
			}
		}
	}
}

func TestInstallTagNamesThePublishedChannel(t *testing.T) {
	for _, tc := range []struct {
		build string
		tag   string
		ok    bool
	}{
		{"1.2.3", "v1.2.3", true},
		{"v1.2.3", "v1.2.3", true},
		{"0.2-beta", "v0.2-beta", true},
		{"main-sha-117bc18", "dev", true},
		{"dev", "dev", true},
		{"v0.2-beta-276-g394254b", "", false},
		{"some-fork-build", "", false},
	} {
		t.Run(tc.build, func(t *testing.T) {
			got, ok := InstallTag(tc.build)
			if got != tc.tag || ok != tc.ok {
				t.Errorf("InstallTag(%q) = %q, %v; want %q, %v", tc.build, got, ok, tc.tag, tc.ok)
			}
			if channel := Channel(tc.build); channel != tc.tag {
				t.Errorf("Channel(%q) = %q, want %q", tc.build, channel, tc.tag)
			}
		})
	}
}

// Package version carries build metadata stamped in at link time.
package version

import (
	"fmt"
	"runtime"
	"runtime/debug"
)

// These are overridden with -ldflags "-X github.com/eyupio/zoomies/internal/version.Version=..."
var (
	Version = "dev"
	Commit  = ""
	Date    = ""
)

func init() {
	if info, ok := debug.ReadBuildInfo(); ok {
		Commit, Date = fill(Commit, Date, info.Settings)
	}
}

// fill decides the commit and the date, taking each from the link-time stamp
// when there is one and from the build information Go embeds otherwise.
//
// Each independently, which is the point: this used to give up entirely the
// moment a commit had been stamped, so a build that passed one and not the
// other -- the container image, which had no DATE build argument -- reported
// no date at all, and `zoomies version` on a compose install was quieter than
// the same release installed natively.
func fill(commit, date string, settings []debug.BuildSetting) (string, string) {
	if commit != "" && date != "" {
		return commit, date
	}
	for _, s := range settings {
		switch s.Key {
		case "vcs.revision":
			if commit == "" {
				commit = s.Value
			}
		case "vcs.time":
			if date == "" {
				date = s.Value
			}
		}
	}
	return commit, date
}

// Short returns a compact "v1.2.3 (abc1234)" style identifier.
func Short() string {
	if len(Commit) >= 7 {
		return fmt.Sprintf("%s (%s)", Version, Commit[:7])
	}
	return Version
}

// String returns the full human readable version banner line.
func String() string {
	return fmt.Sprintf("zoomies %s %s/%s %s", Short(), runtime.GOOS, runtime.GOARCH, runtime.Version())
}

// UserAgent is sent on every outbound GitHub API call.
func UserAgent() string { return "zoomies/" + Version }

package version

import (
	"runtime/debug"
	"testing"
)

// A build stamps what it knows. The container image stamps a commit and, until
// it was given a DATE build argument, no date -- and this used to abandon the
// build information the moment a commit was present, so the image reported no
// date at all while the same release installed natively reported one.
func TestEachStampIsFilledInOnItsOwn(t *testing.T) {
	embedded := []debug.BuildSetting{
		{Key: "vcs.revision", Value: "1a2b3c4d5e6f"},
		{Key: "vcs.time", Value: "2026-09-06T08:00:00Z"},
	}
	cases := []struct {
		name                 string
		commit, date         string
		wantCommit, wantDate string
		settings             []debug.BuildSetting
	}{
		{"nothing stamped", "", "", "1a2b3c4d5e6f", "2026-09-06T08:00:00Z", embedded},
		{"a commit stamped, no date", "deadbeef", "", "deadbeef", "2026-09-06T08:00:00Z", embedded},
		{"both stamped", "deadbeef", "yesterday", "deadbeef", "yesterday", embedded},
		{"nothing anywhere", "", "", "", "", nil},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			commit, date := fill(tc.commit, tc.date, tc.settings)
			if commit != tc.wantCommit || date != tc.wantDate {
				t.Fatalf("fill = %q, %q; want %q, %q", commit, date, tc.wantCommit, tc.wantDate)
			}
		})
	}
}

package wsl

import "strings"

// bootMarker is what identifies a boot command as ours, so that a second run
// finds it and changes nothing.
const bootMarker = "agent --wsl-ensure"

// BootCommand is the line written for boot.command: it runs as root when the
// distro starts, does its idempotent work and exits, so it never delays boot.
func BootCommand(binary string) string { return binary + " " + bootMarker }

// WithBootCommand returns conf with boot.command set to cmd under [boot] and
// whether that changed anything. A boot command the operator already had is
// kept and ours is chained after it, because wsl.conf has room for exactly one.
// Everything else in the file, comments included, is left as it was.
func WithBootCommand(conf, cmd string) (string, bool) {
	lines := strings.Split(conf, "\n")
	boot, end := -1, len(lines)
	for i, line := range lines {
		t := strings.TrimSpace(line)
		if !strings.HasPrefix(t, "[") {
			continue
		}
		if boot >= 0 {
			end = i
			break
		}
		if strings.EqualFold(strings.Trim(t, "[] "), "boot") {
			boot = i
		}
	}
	if boot < 0 {
		out := strings.TrimRight(conf, "\n")
		if out != "" {
			out += "\n\n"
		}
		return out + "[boot]\ncommand=" + cmd + "\n", true
	}
	for i := boot + 1; i < end; i++ {
		k, v, ok := strings.Cut(strings.TrimSpace(lines[i]), "=")
		if !ok || !strings.EqualFold(strings.TrimSpace(k), "command") {
			continue
		}
		existing := strings.Trim(strings.TrimSpace(v), `"`)
		switch {
		case strings.Contains(existing, bootMarker) && strings.Contains(existing, cmd):
			return conf, false
		case strings.Contains(existing, bootMarker):
			// Ours, from another binary path (the binary moved): replace it.
			lines[i] = "command=" + cmd
		case existing == "":
			lines[i] = "command=" + cmd
		default:
			lines[i] = "command=" + existing + "; " + cmd
		}
		return strings.Join(lines, "\n"), true
	}
	lines = append(lines[:boot+1], append([]string{"command=" + cmd}, lines[boot+1:]...)...)
	return strings.Join(lines, "\n"), true
}

// HasSystemd reports whether conf asks for systemd, which linger and the
// agent's unit both depend on.
func HasSystemd(conf string) bool {
	section := ""
	for _, line := range strings.Split(conf, "\n") {
		line = strings.TrimSpace(line)
		switch {
		case strings.HasPrefix(line, "["):
			section = strings.ToLower(strings.Trim(line, "[] "))
		case section == "boot":
			if k, v, ok := strings.Cut(line, "="); ok && strings.EqualFold(strings.TrimSpace(k), "systemd") {
				return strings.EqualFold(strings.TrimSpace(v), "true")
			}
		}
	}
	return false
}

package wsl

import (
	"context"
	"errors"
	"io/fs"
	"path"
	"path/filepath"
	"strings"
)

// Status is how one step of Ensure ended.
type Status string

const (
	StatusOK      Status = "ok"      // already as wanted; nothing was changed
	StatusChanged Status = "changed" // written or created
	StatusSkipped Status = "skipped" // not applicable here, and why
	StatusWarn    Status = "warning" // could not be done; what to do about it
	StatusPending Status = "pending" // DryRun only: would be written or created
)

// Step is one thing Ensure checked.
type Step struct {
	Name   string
	Status Status
	Detail string
}

// Report is what one Ensure found and did.
type Report struct {
	Distro string
	Steps  []Step
}

// Warnings returns the steps that could not be completed.
func (r Report) Warnings() []Step {
	var w []Step
	for _, s := range r.Steps {
		if s.Status == StatusWarn {
			w = append(w, s)
		}
	}
	return w
}

// Pending returns the steps a DryRun found would change something.
func (r Report) Pending() []Step {
	var p []Step
	for _, s := range r.Steps {
		if s.Status == StatusPending {
			p = append(p, s)
		}
	}
	return p
}

// Changed reports whether any step wrote something.
func (r Report) Changed() bool {
	for _, s := range r.Steps {
		if s.Status == StatusChanged {
			return true
		}
	}
	return false
}

// Options names what Ensure sets up for.
type Options struct {
	// Binary is the zoomies binary the boot command runs.
	Binary string
	// User is the account the agent service runs as, for linger. Empty means
	// it is read from the installed unit.
	User string
	// ConfPath overrides /etc/wsl.conf, for tests.
	ConfPath string
	// DryRun reports what would change as StatusPending and writes nothing,
	// creates no task and enables no linger. It only reads, which is what lets
	// an installer show the operator the list before asking.
	DryRun bool
}

// Ensure brings the distro's self-management into the wanted state, and does
// nothing when it is already there, so it is safe to run from a scheduled task
// every few minutes. A step that cannot be done is a warning in the report and
// never an error: a task that fails on every run teaches nobody anything, and
// the other steps are still worth taking.
//
// It restarts nothing and ends no process, so it cannot interrupt a running
// job. A changed wsl.conf takes effect the next time the distro starts.
func Ensure(ctx context.Context, sys System, opts Options) Report {
	rep := Report{}
	add := func(s Step) { rep.Steps = append(rep.Steps, s) }
	if !Detect(sys) {
		add(Step{Name: "wsl2", Status: StatusSkipped, Detail: "this is not a WSL2 distro, so there is nothing to do"})
		return rep
	}
	rep.Distro = Distro(ctx, sys)
	add(Step{Name: "wsl2", Status: StatusOK, Detail: "WSL2 detected, distro " + orUnknown(rep.Distro)})
	add(ensureBootCommand(sys, opts))
	add(ensureLinger(ctx, sys, opts))
	for _, s := range ensureTasks(ctx, sys, rep.Distro, opts.DryRun) {
		add(s)
	}
	return rep
}

func orUnknown(s string) string {
	if s == "" {
		return "(unknown)"
	}
	return s
}

func ensureBootCommand(sys System, opts Options) Step {
	step := Step{Name: "wsl.conf boot.command"}
	path := opts.ConfPath
	if path == "" {
		path = ConfPath
	}
	if opts.Binary == "" {
		step.Status, step.Detail = StatusSkipped, "the zoomies binary's path is unknown"
		return step
	}
	data, err := sys.ReadFile(path)
	if err != nil && !errors.Is(err, fs.ErrNotExist) {
		step.Status, step.Detail = StatusWarn, "reading "+path+": "+err.Error()
		return step
	}
	want, changed := WithBootCommand(string(data), BootCommand(opts.Binary))
	if !changed {
		step.Status, step.Detail = StatusOK, "already in "+path
		return step
	}
	if opts.DryRun {
		step.Status, step.Detail = StatusPending, "set boot.command in "+path+" so the distro starts the agent's checks at boot"
		return step
	}
	if sys.Geteuid() != 0 {
		step.Status, step.Detail = StatusWarn, "writing "+path+" needs root; run `sudo zoomies agent --wsl-ensure` once"
		return step
	}
	if err == nil && !sys.Exists(path+".zoomies-bak") {
		if werr := sys.WriteFile(path+".zoomies-bak", data, 0o644); werr != nil {
			step.Status, step.Detail = StatusWarn, "keeping a copy of "+path+": "+werr.Error()
			return step
		}
	}
	if werr := sys.WriteFile(path, []byte(want), 0o644); werr != nil {
		step.Status, step.Detail = StatusWarn, "writing "+path+": "+werr.Error()
		return step
	}
	step.Status, step.Detail = StatusChanged, "set in "+path+"; it runs the next time the distro starts"
	if !HasSystemd(want) {
		step.Detail += " (systemd is not on in it, so the agent is not a service here; see docs/hosts-and-pools.md)"
	}
	return step
}

// agentUser is who linger is enabled for.
func agentUser(sys System, opts Options) string {
	if opts.User != "" {
		return opts.User
	}
	if b, err := sys.ReadFile(unitFile); err == nil {
		for _, l := range strings.Split(string(b), "\n") {
			if k, v, ok := strings.Cut(strings.TrimSpace(l), "="); ok && k == "User" {
				return strings.TrimSpace(v)
			}
		}
	}
	return ""
}

func ensureLinger(ctx context.Context, sys System, opts Options) Step {
	step := Step{Name: "systemd linger"}
	user := agentUser(sys, opts)
	if user == "" {
		step.Status, step.Detail = StatusSkipped, "the agent's user is unknown (no installed zoomies-agent unit)"
		return step
	}
	if sys.Exists(path.Join(lingerDir, user)) {
		step.Status, step.Detail = StatusOK, "enabled for "+user
		return step
	}
	if opts.DryRun {
		step.Status, step.Detail = StatusPending, "enable systemd linger for "+user+" so its services outlive login sessions"
		return step
	}
	if _, err := sys.Run(ctx, "loginctl", "enable-linger", user); err != nil {
		step.Status, step.Detail = StatusWarn, "loginctl enable-linger "+user+" failed: "+err.Error()
		return step
	}
	step.Status, step.Detail = StatusChanged, "enabled for "+user
	return step
}

func ensureTasks(ctx context.Context, sys System, distro string, dry bool) []Step {
	skip := func(why string) []Step {
		return []Step{{Name: "windows scheduled tasks", Status: StatusSkipped, Detail: why}}
	}
	if distro == "" {
		return skip("the distro's name could not be found, so no task can start it")
	}
	if !sys.Exists(SchtasksPath) {
		return skip("Windows interop is off here (" + SchtasksPath + " is missing); enable [interop] in /etc/wsl.conf")
	}
	winScript, err := writeScript(ctx, sys, distro, dry)
	if err != nil {
		return []Step{{Name: "windows start script", Status: StatusWarn, Detail: err.Error()}}
	}
	steps := []Step{{Name: "windows start script", Status: StatusOK, Detail: winScript.detail}}
	switch {
	case winScript.pending:
		steps[0].Status, steps[0].Detail = StatusPending, "write the start script "+winScript.windowsPath
	case winScript.changed:
		steps[0].Status = StatusChanged
	}
	for _, spec := range taskSpecs() {
		steps = append(steps, ensureTask(ctx, sys, spec, winScript.windowsPath, dry))
	}
	return steps
}

type scriptResult struct {
	windowsPath string
	detail      string
	changed     bool
	pending     bool
}

// writeScript puts the start script under %LOCALAPPDATA%, which needs no
// elevation, writing it only when its content differs.
func writeScript(ctx context.Context, sys System, distro string, dry bool) (scriptResult, error) {
	var res scriptResult
	out, err := sys.Run(ctx, CmdExePath, "/c", "echo", "%LOCALAPPDATA%")
	if err != nil {
		return res, errors.New("asking Windows for %LOCALAPPDATA%: " + err.Error())
	}
	local := strings.TrimSpace(decodeConsole(out))
	if local == "" || strings.Contains(local, "%") {
		return res, errors.New("the Windows side did not say where %LOCALAPPDATA% is")
	}
	unixOut, err := sys.Run(ctx, "wslpath", "-u", local)
	if err != nil {
		return res, errors.New("translating " + local + " to a Linux path: " + err.Error())
	}
	dir := filepath.Join(strings.TrimSpace(string(unixOut)), "Zoomies")
	path := filepath.Join(dir, scriptName)
	want := startScript(distro)
	res.windowsPath = local + `\Zoomies\` + scriptName
	res.detail = res.windowsPath
	if cur, err := sys.ReadFile(path); err == nil && string(cur) == want {
		return res, nil
	}
	if dry {
		res.pending = true
		return res, nil
	}
	if err := sys.MkdirAll(dir, 0o755); err != nil {
		return res, errors.New("creating " + dir + ": " + err.Error())
	}
	if err := sys.WriteFile(path, []byte(want), 0o644); err != nil {
		return res, errors.New("writing " + path + ": " + err.Error())
	}
	res.changed = true
	return res, nil
}

package wsl

import (
	"context"
	"log/slog"
	"os"
	"strconv"
	"strings"
	"time"
)

// Keepalive holds a Windows-side session open on the distro for as long as the
// agent lives, because WSL2 stops a distro when its last such session closes
// and a process inside it does not count. The session is `wsl.exe -d <distro>
// --exec sleep infinity`, started through interop.
//
// The process is started in its own session and left running when the agent
// stops, so restarting the agent (an update, a crash, systemd's Restart=)
// never lets the distro go down under the jobs the agent leaves running. Its
// pid is recorded, and the next agent adopts it instead of starting another.
type Keepalive struct {
	Distro  string
	WSLExe  string // path to wsl.exe; empty falls back to a plain sleep
	PidFile string
	Log     *slog.Logger

	// Seams for tests.
	Start func(ctx context.Context, argv []string) (pid int, err error)
	Alive func(pid int) bool
	Sleep func(ctx context.Context, d time.Duration) bool
	Read  func(path string) ([]byte, error)
	Write func(path string, data []byte, perm os.FileMode) error
}

// Argv is the command that holds the session open.
func (k *Keepalive) Argv() []string {
	if k.WSLExe == "" {
		return []string{"/bin/sleep", "infinity"}
	}
	return []string{k.WSLExe, "-d", k.Distro, "--exec", "/bin/sleep", "infinity"}
}

const (
	pollEvery  = 5 * time.Second
	backoffMin = 2 * time.Second
	backoffMax = time.Minute
)

// Run keeps one session open until ctx ends. It returns only then.
func (k *Keepalive) Run(ctx context.Context) {
	k.defaults()
	backoff := backoffMin
	if k.WSLExe == "" {
		k.Log.Warn("Windows interop is unavailable, so the keepalive is a plain sleep and cannot hold this WSL2 distro up; the scheduled tasks are the only recovery",
			"expected", WSLExePath)
	}
	for ctx.Err() == nil {
		pid, adopted := k.adopt()
		if !adopted {
			var err error
			pid, err = k.Start(ctx, k.Argv())
			if err != nil {
				k.Log.Warn("could not start the WSL2 keepalive; retrying", "error", err, "in", backoff.String())
				if !k.Sleep(ctx, backoff) {
					return
				}
				backoff = min(backoff*2, backoffMax)
				continue
			}
			if err := k.Write(k.PidFile, []byte(strconv.Itoa(pid)), 0o644); err != nil {
				k.Log.Warn("could not record the keepalive's pid; a restarted agent will start another", "error", err)
			}
			k.Log.Info("holding the WSL2 distro open", "pid", pid, "distro", k.Distro)
		} else {
			k.Log.Info("adopted the WSL2 keepalive an earlier agent started", "pid", pid)
		}
		backoff = backoffMin
		for k.Alive(pid) {
			if !k.Sleep(ctx, pollEvery) {
				return
			}
		}
		if ctx.Err() == nil {
			k.Log.Warn("the WSL2 keepalive exited; starting another", "pid", pid)
		}
	}
}

func (k *Keepalive) adopt() (int, bool) {
	b, err := k.Read(k.PidFile)
	if err != nil {
		return 0, false
	}
	pid, err := strconv.Atoi(strings.TrimSpace(string(b)))
	if err != nil || pid <= 1 || !k.Alive(pid) {
		return 0, false
	}
	return pid, true
}

func (k *Keepalive) defaults() {
	if k.Log == nil {
		k.Log = slog.Default()
	}
	if k.Start == nil {
		k.Start = startDetached
	}
	if k.Alive == nil {
		k.Alive = processAlive
	}
	if k.Sleep == nil {
		k.Sleep = sleepCtx
	}
	if k.Read == nil {
		k.Read = os.ReadFile
	}
	if k.Write == nil {
		k.Write = os.WriteFile
	}
}

func sleepCtx(ctx context.Context, d time.Duration) bool {
	t := time.NewTimer(d)
	defer t.Stop()
	select {
	case <-ctx.Done():
		return false
	case <-t.C:
		return true
	}
}

