//go:build unix

package wsl

import (
	"context"
	"errors"
	"os"
	"os/exec"
	"strconv"
	"strings"
	"syscall"
)

// startDetached starts argv in its own session and does not tie it to ctx:
// cancelling the agent must leave the session open.
func startDetached(_ context.Context, argv []string) (int, error) {
	cmd := exec.Command(argv[0], argv[1:]...)
	cmd.SysProcAttr = &syscall.SysProcAttr{Setsid: true}
	if err := cmd.Start(); err != nil {
		return 0, err
	}
	// Reaped in the background so that an exit shows as gone, not as a zombie
	// that still answers signal 0.
	go func() { _ = cmd.Wait() }()
	return cmd.Process.Pid, nil
}

// processAlive is whether pid is a live keepalive. The command line is checked
// as well as the signal because a recorded pid outlives its process and can be
// reused by something unrelated.
func processAlive(pid int) bool {
	if err := syscall.Kill(pid, 0); err != nil && !errors.Is(err, syscall.EPERM) {
		return false
	}
	b, err := os.ReadFile("/proc/" + strconv.Itoa(pid) + "/cmdline")
	if err != nil {
		return false
	}
	c := string(b)
	return strings.Contains(c, "sleep") || strings.Contains(c, "wsl.exe")
}

package wsl

import (
	"context"
	"fmt"
	"strings"
	"unicode/utf16"
)

// The scheduled tasks Windows runs to start the distro when nothing else has.
// Both run the same script, which checks first, so a task firing while the
// distro is already up does nothing.
const (
	taskOnStart = `Zoomies\WslOnStart`
	taskEvery5  = `Zoomies\WslEvery5Minutes`
	scriptName  = "wsl-ensure.ps1"
)

// startScript is the PowerShell the tasks run. wsl.exe prints UTF-16, which
// arrives with NULs between the letters, so they are stripped before matching.
// The command it starts holds the distro for two minutes: long enough for
// systemd to start the agent, which then holds it open for good.
func startScript(distro string) string {
	d := strings.ReplaceAll(distro, "'", "''")
	return strings.Join([]string{
		"# Written by `zoomies agent --wsl-ensure`; rewritten if it differs.",
		"$distro = '" + d + "'",
		`$wsl = Join-Path $env:SystemRoot 'System32\wsl.exe'`,
		"$running = ((& $wsl -l --running -q) -join \"`n\") -replace \"`0\", ''",
		"if ($running -notmatch ('(?m)^' + [regex]::Escape($distro) + '\\s*$')) {",
		"  & $wsl -d $distro --exec /bin/sleep 120",
		"}",
		"",
	}, "\r\n")
}

// decodeConsole turns schtasks' output into text. Piped through interop it is
// UTF-16LE with or without a byte-order mark.
func decodeConsole(b []byte) string {
	if len(b) >= 2 && (b[0] == 0xFF && b[1] == 0xFE || len(b) > 3 && b[1] == 0 && b[3] == 0) {
		if b[0] == 0xFF && b[1] == 0xFE {
			b = b[2:]
		}
		u := make([]uint16, 0, len(b)/2)
		for i := 0; i+1 < len(b); i += 2 {
			u = append(u, uint16(b[i])|uint16(b[i+1])<<8)
		}
		return string(utf16.Decode(u))
	}
	return strings.TrimPrefix(string(b), "\xef\xbb\xbf")
}

type taskSpec struct {
	name       string
	args       []string // the schedule part of /Create
	trigger    string   // what the exported XML must contain to be this schedule
	needsAdmin bool
}

func taskSpecs() []taskSpec {
	return []taskSpec{
		{name: taskOnStart, args: []string{"/SC", "ONSTART"}, trigger: "<BootTrigger>", needsAdmin: true},
		{name: taskEvery5, args: []string{"/SC", "MINUTE", "/MO", "5"}, trigger: "<Interval>PT5M</Interval>"},
	}
}

// ensureTask creates or repairs one task. It is current when it exists, has the
// right schedule and runs this script; otherwise it is created again with /F.
// No credentials are ever passed: without /RU and /RP a task runs as the
// current user and only while they are signed in, and an ONSTART task needs
// elevation, which is reported rather than asked for.
func ensureTask(ctx context.Context, sys System, spec taskSpec, winScript string, dry bool) Step {
	step := Step{Name: "task " + spec.name}
	action := `powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -WindowStyle Hidden -File "` + winScript + `"`
	if out, err := sys.Run(ctx, SchtasksPath, "/Query", "/TN", spec.name, "/XML"); err == nil {
		xml := decodeConsole(out)
		if strings.Contains(xml, spec.trigger) && strings.Contains(xml, winScript) {
			step.Status, step.Detail = StatusOK, "already in place"
			return step
		}
	}
	if dry {
		step.Status, step.Detail = StatusPending, "create the Windows scheduled task "+spec.name
		return step
	}
	args := append([]string{"/Create", "/TN", spec.name, "/TR", action}, spec.args...)
	args = append(args, "/F")
	out, err := sys.Run(ctx, SchtasksPath, args...)
	if err != nil {
		msg := strings.TrimSpace(decodeConsole([]byte(err.Error())) + " " + decodeConsole(out))
		msg = strings.ReplaceAll(msg, "\x00", "")
		if strings.Contains(strings.ToLower(msg), "access is denied") {
			step.Status = StatusWarn
			step.Detail = "Windows refused it without elevation, so it was skipped; " + spec.name + " needs an elevated session once (this never asks for a password)"
			return step
		}
		step.Status, step.Detail = StatusWarn, fmt.Sprintf("schtasks failed: %s", msg)
		return step
	}
	step.Status, step.Detail = StatusChanged, "created"
	return step
}

// Package wsl keeps a Zoomies agent alive inside a WSL2 distro.
//
// A WSL2 distro is not a machine that stays up. It is stopped when the last
// Windows-side session attached to it closes, whatever is running inside, so an
// agent that is correctly a systemd service (PID 1 is its parent) still goes
// away when the terminal that first started the distro is closed, and nothing
// brings it back after a reboot. This package holds the three things that
// prevent that: a session the agent owns for as long as it lives (Keepalive),
// systemd linger and a boot command inside the distro, and Windows scheduled
// tasks that start the distro when nobody has (Ensure).
//
// Nothing here restarts anything. Every step is a write that takes effect the
// next time the distro starts, or a process that only holds the distro up, so
// no step can end a job that is running: there is nothing to defer until idle.
//
// All host access goes through System so tests never touch the machine.
package wsl

import (
	"context"
	"os"
	"os/exec"
	"runtime"
	"strings"
)

// Conventional locations. WSL mounts the Windows system drive at /mnt/c unless
// the operator changed automount.root, in which case interop is probed for and
// the step skips with a reason rather than guessing.
const (
	ConfPath     = "/etc/wsl.conf"
	SchtasksPath = "/mnt/c/Windows/System32/schtasks.exe"
	WSLExePath   = "/mnt/c/Windows/System32/wsl.exe"
	CmdExePath   = "/mnt/c/Windows/System32/cmd.exe"
	lingerDir    = "/var/lib/systemd/linger"
	unitFile     = "/etc/systemd/system/zoomies-agent.service"
)

// System is everything this package needs from the host.
type System interface {
	GOOS() string
	Getenv(key string) string
	ReadFile(path string) ([]byte, error)
	WriteFile(path string, data []byte, perm os.FileMode) error
	MkdirAll(path string, perm os.FileMode) error
	Exists(path string) bool
	Geteuid() int
	// Run executes a command and returns its standard output. Standard error
	// is folded into the error so a refusal's wording reaches the operator.
	Run(ctx context.Context, name string, args ...string) ([]byte, error)
}

// OS is the System of the machine the process runs on.
type OS struct{}

func (OS) GOOS() string                      { return runtime.GOOS }
func (OS) Getenv(k string) string            { return os.Getenv(k) }
func (OS) ReadFile(p string) ([]byte, error) { return os.ReadFile(p) }
func (OS) WriteFile(p string, d []byte, m os.FileMode) error {
	return os.WriteFile(p, d, m)
}
func (OS) MkdirAll(p string, m os.FileMode) error { return os.MkdirAll(p, m) }
func (OS) Geteuid() int                           { return os.Geteuid() }
func (OS) Exists(p string) bool {
	_, err := os.Stat(p)
	return err == nil
}

// Run starts the command in /mnt/c when it exists: cmd.exe and the tasks it
// starts warn about, and sometimes refuse, a working directory that is a UNC
// path into the distro's own filesystem.
func (OS) Run(ctx context.Context, name string, args ...string) ([]byte, error) {
	cmd := exec.CommandContext(ctx, name, args...)
	if _, err := os.Stat("/mnt/c"); err == nil {
		cmd.Dir = "/mnt/c"
	}
	var stderr strings.Builder
	cmd.Stderr = &stderr
	out, err := cmd.Output()
	if err != nil {
		if msg := strings.TrimSpace(stderr.String()); msg != "" {
			return out, &runError{err: err, msg: msg}
		}
		if msg := strings.TrimSpace(string(out)); msg != "" {
			return out, &runError{err: err, msg: msg}
		}
	}
	return out, err
}

type runError struct {
	err error
	msg string
}

func (e *runError) Error() string { return e.err.Error() + ": " + e.msg }
func (e *runError) Unwrap() error { return e.err }

// Detect reports whether this process runs inside WSL2: WSL_DISTRO_NAME, which
// WSL sets in login sessions but not in systemd's services, or the WSL2 kernel's name in /proc/version, which is always there. WSL1 is
// not a target: it has no kernel to name and no distro lifetime to hold.
func Detect(sys System) bool {
	if sys.GOOS() != "linux" {
		return false
	}
	if sys.Getenv("WSL_DISTRO_NAME") != "" {
		return true
	}
	b, err := sys.ReadFile("/proc/version")
	return err == nil && strings.Contains(strings.ToLower(string(b)), "microsoft-standard-wsl2")
}

// Distro is the name Windows knows this distro by. A systemd service does not
// inherit WSL_DISTRO_NAME, so when the variable is missing it asks wslpath for
// the Windows path of "/" (\\wsl.localhost\Ubuntu\), which carries the
// name. An empty answer is honest: the Windows-side steps then skip, because
// starting the wrong distro would be worse than starting none.
func Distro(ctx context.Context, sys System) string {
	if d := strings.TrimSpace(sys.Getenv("WSL_DISTRO_NAME")); d != "" {
		return d
	}
	out, err := sys.Run(ctx, "wslpath", "-w", "/")
	if err != nil {
		return ""
	}
	return distroFromWindowsPath(string(out))
}

// distroFromWindowsPath pulls "Ubuntu" out of \\wsl.localhost\Ubuntu\ or the
// older \\wsl$\Ubuntu\ form.
func distroFromWindowsPath(p string) string {
	p = strings.TrimSpace(strings.ReplaceAll(p, "/", `\`))
	p = strings.TrimLeft(p, `\`)
	parts := strings.Split(p, `\`)
	if len(parts) < 2 {
		return ""
	}
	if h := strings.ToLower(parts[0]); h != "wsl.localhost" && h != "wsl$" {
		return ""
	}
	return parts[1]
}

package wsl

