//go:build load

// Package load builds a fleet with a history and measures the reads an
// operator's pages make against it.
//
// It is a separate tier for the same reason the drills are: it takes tens of
// seconds and writes a record rather than an exit code. The fixture is here and
// not in the demo seed on purpose -- the seed is what a person points at a
// running controller to look at a fleet, and ten thousand jobs is not something
// anybody should be able to do to a real database by setting an environment
// variable.
package load

import (
	"context"
	"fmt"
	"math/rand/v2"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// The shape of the fixture. Ten hosts is a fleet somebody runs; ten thousand
// jobs is a busy month of history, which is what the retention windows allow
// and therefore what the queries have to stay honest over.
const (
	hosts      = 10
	pools      = 5
	jobs       = 10_000
	runners    = 2_000
	auditRows  = 5_000
	historyFor = 30 * 24 * time.Hour
)

// build writes the fixture through the store's own writer, which is the only
// way it can be written: the store owns the single write connection, and a
// fixture that went around it would be measuring a database no controller
// could have produced.
func build(t *testing.T, s *store.Store) {
	t.Helper()
	ctx := context.Background()
	started := time.Now()
	now := time.Now()
	// Deterministic: a measurement whose fixture changes between runs cannot be
	// compared with the last one, which is the whole point of recording it.
	rng := rand.New(rand.NewPCG(1, 2))

	inst := &store.Installation{
		AppID: 1234, InstallationID: 5678, Target: "acme", TargetType: store.TargetOrg,
		AppSlug: "zoomies-load", PrivateKeyEnc: []byte("sealed"), WebhookSecretEnc: []byte("sealed"),
	}
	if err := s.CreateInstallation(ctx, inst); err != nil {
		t.Fatalf("CreateInstallation: %v", err)
	}

	hostIDs := make([]string, 0, hosts)
	for i := range hosts {
		h := &store.Host{
			Name: fmt.Sprintf("builder-%02d", i), Address: "127.0.0.1", Capacity: 8,
			Backends: store.StringSlice{string(store.BackendDocker)}, LastHeartbeat: now,
		}
		if err := s.CreateHost(ctx, h); err != nil {
			t.Fatalf("CreateHost: %v", err)
		}
		hostIDs = append(hostIDs, h.ID)
	}

	poolIDs := make([]string, 0, pools)
	for i := range pools {
		p := &store.Pool{
			Name: fmt.Sprintf("linux-x64-%02d", i), InstallationID: inst.ID,
			Labels:  []string{"self-hosted", "linux", "x64", fmt.Sprintf("pool-%02d", i)},
			Backend: store.BackendDocker, Image: "ghcr.io/eyupio/zoomies-runner:test",
			DockerMode: store.DockerNone,
			MinRunners: 0, MaxRunners: 20, Enabled: true,
		}
		if err := s.CreatePool(ctx, p); err != nil {
			t.Fatalf("CreatePool: %v", err)
		}
		poolIDs = append(poolIDs, p.ID)
	}

	runnerIDs := make([]string, 0, runners)
	for i := range runners {
		r := &store.Runner{
			PoolID: poolIDs[i%len(poolIDs)], HostID: hostIDs[i%len(hostIDs)],
			Name:  fmt.Sprintf("zoomies-load-%05d", i),
			State: store.RunnerRemoved,
		}
		if i < 40 {
			// A live tail, so the lists a page shows first are not all history.
			r.State = store.RunnerIdle
		}
		if err := s.CreateRunner(ctx, r); err != nil {
			t.Fatalf("CreateRunner: %v", err)
		}
		runnerIDs = append(runnerIDs, r.ID)
	}

	conclusions := []string{"success", "success", "success", "failure", "cancelled"}
	for i := range jobs {
		age := time.Duration(rng.Int64N(int64(historyFor)))
		queued := now.Add(-age)
		j := &store.Job{
			GitHubJobID:    int64(100_000 + i),
			GitHubRunID:    int64(900_000 + i/10),
			Repo:           fmt.Sprintf("acme/service-%02d", i%20),
			Workflow:       "CI",
			JobName:        fmt.Sprintf("build-%03d", i%50),
			Labels:         store.NormalizeLabels([]string{"self-hosted", "linux", "x64"}),
			State:          store.JobCompleted,
			Conclusion:     conclusions[i%len(conclusions)],
			InstallationID: inst.ID,
			PoolID:         poolIDs[i%len(poolIDs)],
			RunnerID:       runnerIDs[i%len(runnerIDs)],
			RunnerName:     fmt.Sprintf("zoomies-load-%05d", i%runners),
			QueuedAt:       queued,
			Matched:        true,
		}
		started := queued.Add(time.Duration(rng.Int64N(int64(2 * time.Minute))))
		completed := started.Add(time.Duration(rng.Int64N(int64(20 * time.Minute))))
		j.StartedAt, j.CompletedAt = &started, &completed
		if i%97 == 0 {
			// A queue with something in it: the Overview and the scheduler both
			// read this, and a fixture with none would measure the easy case.
			j.State, j.Conclusion, j.StartedAt, j.CompletedAt = store.JobQueued, "", nil, nil
		}
		if _, err := s.UpsertJob(ctx, j); err != nil {
			t.Fatalf("UpsertJob %d: %v", i, err)
		}
	}

	// The Overview's sparkline and its feed, which are read on every page load
	// and were empty in the first version of this fixture -- so the two fastest
	// figures in the record were measuring nothing.
	for i := range 24 * 60 {
		if err := s.RecordSample(ctx, store.FleetSample{
			At: now.Add(-time.Duration(i) * time.Minute), QueuedJobs: i % 7, RunningJobs: i % 11,
			IdleRunners: 3, BusyRunners: i % 5, TotalRunners: 8,
		}); err != nil {
			t.Fatalf("RecordSample: %v", err)
		}
	}
	for i := range 500 {
		if err := s.AppendScalingEvent(ctx, &store.ScalingEvent{
			PoolID: poolIDs[i%len(poolIDs)], PoolName: fmt.Sprintf("linux-x64-%02d", i%len(poolIDs)),
			From: i % 4, To: (i % 4) + 1,
			Reason:    fmt.Sprintf("%d jobs queued > 30s", 1+i%3),
			CreatedAt: now.Add(-time.Duration(i) * time.Minute),
		}); err != nil {
			t.Fatalf("AppendScalingEvent: %v", err)
		}
	}

	actions := []string{"pool.update", "runner.drain", "host.cordon", "token.create", "settings.update"}
	for i := range auditRows {
		if err := s.AppendAudit(ctx, &store.AuditEvent{
			ActorID: "usr_load", ActorName: "loadtest", ActorKind: "user",
			Action:     actions[i%len(actions)],
			TargetKind: "pool", TargetID: poolIDs[i%len(poolIDs)],
			CreatedAt: now.Add(-time.Duration(rng.Int64N(int64(historyFor)))),
		}); err != nil {
			t.Fatalf("AppendAudit: %v", err)
		}
	}

	t.Logf("fixture: %d hosts, %d pools, %d runners, %d jobs, %d audit rows in %s",
		hosts, pools, runners, jobs, auditRows, time.Since(started).Round(time.Millisecond))
}

//go:build load

package load

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"sort"
	"strings"
	"sync/atomic"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/api"
	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/cryptox"
	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

// How many times each read is timed. Enough for a p95 to mean something and
// few enough that the whole measurement is a couple of minutes.
const samples = 40

// reading is one endpoint's timings.
type reading struct {
	what   string
	path   string
	p50    time.Duration
	p95    time.Duration
	worst  time.Duration
	status int
	bytes  int
}

func percentile(sorted []time.Duration, p float64) time.Duration {
	if len(sorted) == 0 {
		return 0
	}
	i := int(float64(len(sorted)-1)*p + 0.5)
	return sorted[i]
}

// measure times one path `samples` times and returns the spread.
func measure(t *testing.T, client *http.Client, base, what, path string) reading {
	t.Helper()
	times := make([]time.Duration, 0, samples)
	r := reading{what: what, path: path}
	for range samples {
		started := time.Now()
		resp, err := client.Get(base + path)
		if err != nil {
			t.Fatalf("GET %s: %v", path, err)
		}
		n, err := io.Copy(io.Discard, resp.Body)
		resp.Body.Close()
		if err != nil {
			t.Fatalf("reading %s: %v", path, err)
		}
		times = append(times, time.Since(started))
		r.status, r.bytes = resp.StatusCode, int(n)
	}
	sort.Slice(times, func(i, j int) bool { return times[i] < times[j] })
	r.p50, r.p95, r.worst = percentile(times, .5), percentile(times, .95), times[len(times)-1]
	return r
}

// TestTheReadsAPageMakesOverAMonthOfHistory is the measurement.
//
// It is not a pass/fail gate and deliberately asserts almost nothing: the
// roadmap's figures are recorded evidence, and a threshold in here would either
// be so loose it never fires or so tight that a slower CI runner fails a pull
// request that changed nothing. What it does assert is that every read still
// answers, and answers correctly, with a month of history under it -- a query
// that starts erroring or returning an empty page at depth is a defect whatever
// its latency.
func TestTheReadsAPageMakesOverAMonthOfHistory(t *testing.T) {
	dir := t.TempDir()
	ctx := context.Background()

	// On disk with the real journal, not in memory: the measurement is about
	// what SQLite does with indexes and page cache, and :memory: answers a
	// different question.
	st, err := store.Open(ctx, store.Options{Path: filepath.Join(dir, "zoomies.db")})
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	defer st.Close()
	build(t, st)

	cfg := config.Default()
	cfg.Server.Bind = "127.0.0.1:0"
	cfg.Database.Path = filepath.Join(dir, "zoomies.db")
	cfg.Security.DisableAuth = true
	cfg.Security.EncryptionKey = strings.Repeat("a", 64)
	cfg.Security.EncryptionKeyFile = ""
	cfg.Agent.Embedded = false
	key, err := cryptox.ParseKey(cfg.Security.EncryptionKey)
	if err != nil {
		t.Fatalf("ParseKey: %v", err)
	}
	bus := events.New()
	logger := slog.New(slog.NewTextHandler(io.Discard, nil))
	gh := github.NewFake()
	defer gh.Close()
	ctrl, err := controller.New(controller.Options{
		Store: st, Config: cfg, Key: key,
		Auth:   auth.New(st, cfg, bus, auth.WithLogger(logger)),
		Events: bus, Logger: logger, Clock: time.Now,
	})
	if err != nil {
		t.Fatalf("controller.New: %v", err)
	}
	server, err := api.New(api.Options{Controller: ctrl, Logger: logger})
	if err != nil {
		t.Fatalf("api.New: %v", err)
	}
	srv := httptest.NewServer(server.Handler())
	defer srv.Close()
	client := srv.Client()

	// Work going on underneath, which is the state the pages are actually read
	// in: an idle database answers a question nobody asks. One writer, because
	// the store has one.
	var writes atomic.Int64
	stop := make(chan struct{})
	done := make(chan struct{})
	go func() {
		defer close(done)
		tick := time.NewTicker(20 * time.Millisecond)
		defer tick.Stop()
		for i := 0; ; i++ {
			select {
			case <-stop:
				return
			case <-tick.C:
				j := &store.Job{
					GitHubJobID: int64(9_000_000 + i), Repo: "acme/live", Workflow: "CI",
					JobName: "live", State: store.JobQueued, QueuedAt: time.Now(),
				}
				if _, err := st.UpsertJob(ctx, j); err == nil {
					writes.Add(1)
				}
			}
		}
	}()

	rightNow := time.Now().UTC().Format(time.RFC3339)
	monthAgo := time.Now().Add(-historyFor).UTC().Format(time.RFC3339)

	// The reads a page makes: the primary navigation's first screen, the deep
	// pages an operator reaches by scrolling, and the two reports.
	reads := []struct{ what, path string }{
		{"Overview: the statistics tiles", "/api/v1/stats"},
		{"Overview: the sparkline samples", "/api/v1/samples?window=1h"},
		{"Overview: the problems drawer", "/api/v1/problems"},
		{"Overview: recent scaling", "/api/v1/scaling-events?limit=10"},
		{"Runners: the first page", "/api/v1/runners?limit=50"},
		{"Runners: page 20 of the history", "/api/v1/runners?limit=50&offset=950&include_removed=true"},
		{"Runners: filtered to idle", "/api/v1/runners?limit=50&state=idle"},
		{"Jobs: the first page", "/api/v1/jobs?limit=50"},
		{"Jobs: page 100", "/api/v1/jobs?limit=50&offset=4950"},
		{"Jobs: one repository", "/api/v1/jobs?limit=50&repo=acme/service-01"},
		{"Hosts", "/api/v1/hosts"},
		{"Pools", "/api/v1/pools"},
		{"Audit: the first page", "/api/v1/audit?limit=50"},
		{"Audit: filtered by action", "/api/v1/audit?limit=50&action=runner.drain"},
		{"Audit: page 50", "/api/v1/audit?limit=50&offset=2450"},
		{"Usage: a month by pool", "/api/v1/usage?group_by=pool&from=" + monthAgo + "&to=" + rightNow},
		{"Usage: a month by repository", "/api/v1/usage?group_by=repository&from=" + monthAgo + "&to=" + rightNow},
	}

	results := make([]reading, 0, len(reads))
	for _, r := range reads {
		got := measure(t, client, srv.URL, r.what, r.path)
		if got.status != http.StatusOK {
			t.Errorf("%s (%s) answered %d, not 200", r.what, r.path, got.status)
		}
		results = append(results, got)
	}
	close(stop)
	<-done

	// A deep page is still a page of rows, not an empty one: a read that got
	// fast by stopping at the first thousand rows would look excellent here.
	var body struct {
		Items []json.RawMessage `json:"items"`
		Total int               `json:"total"`
	}
	resp, err := client.Get(srv.URL + "/api/v1/jobs?limit=50&offset=4950")
	if err != nil {
		t.Fatalf("deep page: %v", err)
	}
	if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
		t.Fatalf("decoding the deep page: %v", err)
	}
	resp.Body.Close()
	if len(body.Items) != 50 {
		t.Errorf("the deep jobs page returned %d rows, want 50", len(body.Items))
	}
	if body.Total < jobs {
		t.Errorf("the deep jobs page reported a total of %d, want at least the %d written", body.Total, jobs)
	}

	writeRecord(t, results, int(writes.Load()))
}

// writeRecord prints the table and, when asked, files it under
// roadmap/validation/ where the evidence lives.
func writeRecord(t *testing.T, results []reading, writes int) {
	t.Helper()
	var b strings.Builder
	fmt.Fprintf(&b, "| Read | Path | p50 | p95 | worst | bytes |\n| --- | --- | --- | --- | --- | --- |\n")
	for _, r := range results {
		fmt.Fprintf(&b, "| %s | `%s` | %s | %s | %s | %s |\n",
			r.what, r.path,
			r.p50.Round(100*time.Microsecond), r.p95.Round(100*time.Microsecond),
			r.worst.Round(100*time.Microsecond), humanBytes(r.bytes))
	}
	t.Logf("\n%s\nwrites while reading: %d", b.String(), writes)

	out := os.Getenv("ZOOMIES_LOAD_RECORD")
	if out == "" {
		return
	}
	header := fmt.Sprintf(`# Load measurement: %s

Written by `+"`make measure`"+` on %s.

| | |
| --- | --- |
| Commit | `+"`%s`"+` |
| Machine | %s/%s, %d CPUs, %s |
| Fixture | %d hosts, %d pools, %d runners, %d jobs, %d audit rows over %s of history |
| Written through | `+"`internal/store`"+`, the same single writer the controller uses |
| Read through | the real router and the real store, on disk with its usual journal |
| Load while reading | %d job writes landed during the timings |
| Samples | %d requests per row |

%s
`, commit(), time.Now().UTC().Format(time.RFC3339), commit(),
		runtime.GOOS, runtime.GOARCH, runtime.NumCPU(), runtime.Version(),
		hosts, pools, runners, jobs, auditRows, historyFor, writes, samples, b.String())
	if err := os.WriteFile(out, []byte(header), 0o644); err != nil {
		t.Fatalf("writing the record to %s: %v", out, err)
	}
	t.Logf("record written to %s", out)
}

func commit() string {
	out, err := exec.Command("git", "rev-parse", "--short", "HEAD").Output()
	if err != nil {
		return "unknown"
	}
	return strings.TrimSpace(string(out))
}

func humanBytes(n int) string {
	switch {
	case n >= 1<<20:
		return fmt.Sprintf("%.1f MB", float64(n)/(1<<20))
	case n >= 1<<10:
		return fmt.Sprintf("%.0f KB", float64(n)/(1<<10))
	default:
		return fmt.Sprintf("%d B", n)
	}
}

import js from '@eslint/js';
import ts from 'typescript-eslint';
import svelte from 'eslint-plugin-svelte';
import globals from 'globals';

export default ts.config(
  js.configs.recommended,
  ...ts.configs.recommended,
  ...svelte.configs.recommended,
  {
    languageOptions: {
      globals: { ...globals.browser, ...globals.node },
    },
    rules: {
      '@typescript-eslint/no-unused-vars': [
        'error',
        { argsIgnorePattern: '^_', varsIgnorePattern: '^_' },
      ],
      // The API client is generated and typed, and the source has no explicit any
      // today, so a new one is a mistake to fix and not a warning to scroll past.
      '@typescript-eslint/no-explicit-any': 'error',
      eqeqeq: ['error', 'always', { null: 'ignore' }],
    },
  },
  {
    // `.svelte.ts` modules (the runes-based stores) are parsed by the Svelte
    // parser too, so they need the TypeScript parser handed to it as well --
    // without this they fail to parse rather than fail to lint.
    files: ['**/*.svelte', '**/*.svelte.ts', '**/*.svelte.js'],
    languageOptions: { parserOptions: { parser: ts.parser } },
  },
  {
    ignores: [
      'dist/',
      'node_modules/',
      'src/lib/api/schema.d.ts',
      'playwright-report/',
      'test-results/',
    ],
  },
);

import { defineConfig, devices } from '@playwright/test';
import { browserOverride, SETUP_TOKEN_FILE } from './tests/support/fixtures';

/**
