  background: var(--z-bg);
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--z-bg);
  color: var(--z-text);
  font-family: var(--z-font-sans);
  font-size: var(--z-text-sm);
  line-height: var(--z-leading-sm);
  font-weight: var(--z-weight-normal);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  font-feature-settings:
    'cv05' 1,
    'ss03' 1; /* single-storey g, rounded quotes */
}

/* Numbers in tables must line up. */
table,
.tabular {
  font-variant-numeric: tabular-nums;
}

code,
kbd,
samp,
pre,
.mono {
  font-family: var(--z-font-mono);
  font-size: 0.95em;
}

/*
 * A visible focus ring, everywhere, always. :focus-visible means a mouse click
 * does not draw one but a keyboard tab does -- which is the behaviour that makes
 * a permanent focus ring acceptable to designers and keyboard users at once.
 */
:focus-visible {
  outline: var(--z-focus-width) solid var(--z-focus-colour);
  outline-offset: var(--z-focus-offset);
  border-radius: var(--z-radius-sm);
}
:focus:not(:focus-visible) {
  outline: none;
}

::selection {
  background: var(--z-accent-subtle);
  color: var(--z-text);
}

/*
 * Scrollbars that belong to the theme rather than to the browser.
 *
 * Only where there is a pointer to aim with. On a touchscreen the thumb is not
 * a control -- a finger scrolls the content, never the bar -- and the browser's
 * own overlay scrollbar, which takes no space and fades when idle, is the right
 * thing there. Styling it would turn it into a permanent column down the edge
 * of a phone.
 *
 * Two mechanisms, deliberately kept apart. Chromium and WebKit draw from the
 * `::-webkit-scrollbar` pseudo-elements, which is the only way to get a thumb
 * that is inset in its track and rounded. The standard `scrollbar-width` and
 * `scrollbar-color` properties must not be set alongside them: a browser that
 * knows both ignores the pseudo-elements the moment the standard properties are
 * set, and draws its own thin bar instead -- which, in a hairline border grey,
 * is what an operator used to get here. So the standard properties are set only
 * where the pseudo-elements are unknown, which today means Firefox.
 */
@media (pointer: fine) {
  @supports not selector(::-webkit-scrollbar) {
    * {
      scrollbar-width: auto;
      scrollbar-color: var(--z-scrollbar-thumb) var(--z-scrollbar-track);
    }
  }
  *::-webkit-scrollbar {
    width: var(--z-scrollbar-size);
    height: var(--z-scrollbar-size);
  }
  *::-webkit-scrollbar-track,
  *::-webkit-scrollbar-corner {
    background: var(--z-scrollbar-track);
  }
  /*
   * The transparent border is the inset: the whole column is the hit target,
   * and the visible thumb is the column less the inset on each side. It darkens
   * under the pointer and again while held, like any other control here.
   */
  *::-webkit-scrollbar-thumb {
    background-color: var(--z-scrollbar-thumb);
    border: var(--z-scrollbar-inset) solid transparent;
    border-radius: var(--z-radius-full);
    background-clip: content-box;
  }
  *::-webkit-scrollbar-thumb:hover {
    background-color: var(--z-scrollbar-thumb-hover);
  }
  *::-webkit-scrollbar-thumb:active {
    background-color: var(--z-scrollbar-thumb-active);
  }
}

/* Visually hidden but available to assistive technology. */
/*
 * Visible to a screen reader, invisible to everyone else.
 *
 * The one-pixel box and the negative margin that cancels it are the standard
 * recipe, and the reason it is not `display: none` or `visibility: hidden` is
 * that both of those take the text out of the accessibility tree as well.
 */
.sr-only {
  position: absolute;
  width: var(--z-nudge-1);
  height: var(--z-nudge-1);
  padding: 0;
  margin: calc(-1 * var(--z-nudge-1));
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/*
  A label that carries help: a table header, a figure's name. The dotted rule is
  how it says so, since the help is in a bubble and nothing else on the page
  hints that there is one. It is a button, so the keyboard reaches it and the
  bubble opens on focus, and the reset makes it read as the text it is.
*/
.help-term {
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  letter-spacing: inherit;
  text-align: inherit;
  text-transform: inherit;
  text-decoration: underline dotted;
  text-decoration-color: var(--z-text-subtle);
  text-underline-offset: 4px;
  cursor: help;
}

/* The skip link is the first focusable thing on the page. */
.skip-link {
  position: absolute;
  left: var(--z-space-4);
  top: -100px;
  z-index: var(--z-layer-toast);
  padding: var(--z-space-2) var(--z-space-4);
  background: var(--z-accent);
  color: var(--z-accent-contrast);
  border-radius: var(--z-radius-md);
  transition: top var(--z-motion-fast) var(--z-ease);
}
.skip-link:focus {
  top: var(--z-space-4);
}

/**
 * Entry point for /gallery.html, the development-only component gallery.
 *
 * Its own Vite entry rather than a route of the app: `vite build` never builds
 * this document, so the gallery costs the shell budget nothing and no operator
 * can reach it. It imports the app stylesheet, which is where the tokens and
 * the fonts are, so what it renders is what a page renders.
 *
 * The style and colour mode are applied before the first component mounts. The
 * body is empty until then, so there is nothing to flash. Reading the choice
 * from the query string rather than from `localStorage` means opening the
 * gallery never changes the developer's real Appearance settings, which a
 * review tool must not do.
 */
import { mount } from 'svelte';
import '../app.css';
import { installShortcuts } from '$lib/keys';
import Gallery from './Gallery.svelte';
import { applyChoice, readChoice } from './style';

applyChoice(readChoice(location.search));

// The shell installs this, and the overlays depend on it: Escape is handled
// here and nowhere else, so the gallery must have it for a Drawer or a Dialog
// to close with the keyboard exactly as it does in the product. The actions
// are deliberately empty, because there is no fleet here to refresh, search
// or navigate.
installShortcuts({
  palette: () => {},
  help: () => {},
  search: () => {},
  refresh: () => {},
  eli: () => {},
  go: () => {},
});

const target = document.getElementById('gallery');
if (!target) {
  throw new Error('The #gallery element is missing from gallery.html; the gallery cannot mount.');
}

export default mount(Gallery, { target });

/**
 * Which style and colour mode the gallery is showing.
 *
 * The gallery is a development tool, so it does not touch the operator's saved
 * preferences: opening it must not change what Settings, Appearance does on
 * the next real page. It reads the combination from the query string, which
 * also makes a combination something a test or a capture command can name:
 *
 *   /gallery.html?style=mission-control&mode=dark
 *
 * Style validation stays in `$lib/state/ui-style` so the gallery and the
 * product cannot disagree about what a valid style is. Mode is the same three
 * values `ThemeChoice` has, resolved here because the gallery never persists
 * one.
 */
import { resolveUIStyle, type UIStyle } from '$lib/state/ui-style';

/** The three colour modes, spelled as `ThemeChoice` spells them. */
export type GalleryMode = 'system' | 'light' | 'dark';

const MODES: readonly GalleryMode[] = ['system', 'light', 'dark'];

export interface GalleryChoice {
  style: UIStyle;
  mode: GalleryMode;
}

/**
 * An unknown mode, a missing one or an unsupported one is System: the gallery
 * should still open with something sensible rather than fail to render.
 */
export function resolveMode(value: unknown): GalleryMode {
  return MODES.find((mode) => mode === value) ?? 'system';
}

/** The combination a URL's query string asks for. */
export function readChoice(search: string): GalleryChoice {
  const params = new URLSearchParams(search);
  return {
    style: resolveUIStyle(params.get('style')),
    mode: resolveMode(params.get('mode')),
  };
}

/**
 * Put the combination on the document root.
 *
 * Removing an attribute is not the same as setting the default one: Classic
 * and System are the absence of an attribute, exactly as they are in index.html,
 * so the token cascade follows the operating system again.
 */
export function applyChoice({ style, mode }: GalleryChoice): void {
  const root = document.documentElement;
  if (style === 'classic') root.removeAttribute('data-ui-style');
  else root.setAttribute('data-ui-style', style);
  if (mode === 'system') root.removeAttribute('data-theme');
  else root.setAttribute('data-theme', mode);
}

/** The query string that names a combination, for the switcher and for links. */
export function choiceQuery({ style, mode }: GalleryChoice): string {
  const params = new URLSearchParams({ style, mode });
  return `?${params.toString()}`;
}

/**
 * The two column gestures -- pick a heading up and move it, and pull a column's
 * edge -- driven by pointer events, so a finger can do both.
 *
 * Reordering used to be the HTML5 drag-and-drop protocol, which a touchscreen
 * does not speak: a browser raises `dragstart` for a mouse and a stylus, and
 * from a finger only after a long press on Android and never on iOS. So a
 * column order was a preference an operator could set with a mouse and not with
 * a finger, on the one phone layout -- Rows -- that has columns to arrange at
 * all. Pointer events are one code path for mouse, pen and touch alike, which
 * is also one behaviour to keep working rather than two.
 *
 * Resizing was already pointer-driven but listened on the document and never
 * captured the pointer, which holds up for a mouse and not for a finger: a
 * touch that the browser takes over mid-drag (a back-swipe, a second finger, a
 * notification) raises `pointercancel` and no `pointerup`, leaving the listener
 * attached and the column following a finger that had long since let go.
 */

/**
 * How far a pointer travels before a press on the grip becomes a drag.
 *
 * A finger never presses a 24px target without moving a pixel or two, so
 * without a threshold every tap on the grip would reorder the columns.
 */
const DRAG_THRESHOLD_PX = 4;

/**
 * The column under a point, or the empty string if the point is not over one.
 *
 * `elementsFromPoint` rather than `elementFromPoint`: the heading carries the
 * grip and the resize handle on top of it, and the one nearest the pointer is
 * whichever control it happens to be over. Searching down the stack finds the
 * heading under them either way.
 */
function columnAt(root: HTMLElement, x: number, y: number): string {
  for (const element of document.elementsFromPoint(x, y)) {
    if (!root.contains(element)) continue;
    const cell = element.closest<HTMLElement>('[data-table-column]');
    const id = cell?.dataset.tableColumn;
    if (id) return id;
  }
  return '';
}

/**
 * Hold the pointer for the rest of the gesture, so the drag survives the finger
 * leaving the control it started on.
 *
 * Tolerated when it fails: a synthetic pointer dispatched by a test has no
 * capture to take, and a gesture that works without capture is better than a
 * gesture that throws before it begins.
 */
function capture(node: HTMLElement, pointerId: number): void {
  try {
    node.setPointerCapture(pointerId);
  } catch {
    /* as above */
  }
}

export interface ColumnDragHandlers {
  /** The column the pointer is over now, or '' for none. Called as it moves. */
  over(id: string): void;
  /** Where the pointer was lifted, after a drag that really began. */
  drop(id: string): void;
  /**
   * Nothing happened: a press that never travelled far enough to be a drag, or
   * one the browser took the pointer back from. Told apart from a drop so that
   * an interrupted drag abandons the column rather than posting it wherever the
   * finger last happened to be.
   */
  cancel(): void;
}

/**
 * Drag a column by its grip, reporting what the pointer is over as it moves.
 *
 * `root` bounds the hit test to this table: two grids on one page must not be
 * able to drop a column into each other.
 */
export function startColumnDrag(
  event: PointerEvent,
  root: HTMLElement,
  handlers: ColumnDragHandlers,
): void {
  // A secondary touch is a second finger on the screen, not a second drag.
  if (!event.isPrimary || (event.pointerType === 'mouse' && event.button !== 0)) return;
  const grip = event.currentTarget as HTMLElement;
  event.preventDefault();
  event.stopPropagation();
  // preventDefault suppresses the focus the press would have moved, and the
  // grip is also the keyboard control for the same job -- so it takes focus
  // explicitly, and the arrow keys carry on from wherever the drag ended.
  grip.focus();
  capture(grip, event.pointerId);

  const startX = event.clientX;
  const startY = event.clientY;
  // One abort for the three listeners, so there is one way for the gesture to
  // end and no way to leave two of them attached.
  const gesture = new AbortController();
  const { signal } = gesture;
  let dragging = false;

  const finish = (target: string | null): void => {
    gesture.abort();
    if (target === null) handlers.cancel();
    else handlers.drop(target);
  };

  grip.addEventListener(
    'pointermove',
    (move: PointerEvent) => {
      if (move.pointerId !== event.pointerId) return;
      if (
        !dragging &&
        Math.abs(move.clientX - startX) < DRAG_THRESHOLD_PX &&
        Math.abs(move.clientY - startY) < DRAG_THRESHOLD_PX
      )
        return;
      dragging = true;
      move.preventDefault();
      handlers.over(columnAt(root, move.clientX, move.clientY));
    },
    { signal },
  );
  grip.addEventListener(
    'pointerup',
    (up: PointerEvent) => {
      if (up.pointerId !== event.pointerId) return;
      // A press that never became a drag is a press: reporting a target the
      // operator never aimed at is how a stray tap rearranges a table.
      finish(dragging ? columnAt(root, up.clientX, up.clientY) : null);
    },
    { signal },
  );
  grip.addEventListener(
    'pointercancel',
    (cancel: PointerEvent) => {
      if (cancel.pointerId === event.pointerId) finish(null);
    },
    { signal },
  );
}

export interface ColumnResizeHandlers {
  /** The width the pointer is asking for, as it moves. */
  move(width: number): void;
  /** The gesture is over; the last width offered is the one to keep. */
  done(): void;
}

/**
 * Pull a column's trailing edge, from `startWidth` as the pointer went down.
 *
 * A cancelled gesture keeps the width it had reached rather than snapping back:
 * the operator was dragging towards a width, and an interruption they did not
 * ask for is a poor reason to throw away the part of it they had.
 */
export function startColumnResize(
  event: PointerEvent,
  startWidth: number,
  handlers: ColumnResizeHandlers,
): void {
  if (!event.isPrimary || (event.pointerType === 'mouse' && event.button !== 0)) return;
  const handle = event.currentTarget as HTMLElement;
  event.preventDefault();
  event.stopPropagation();
  handle.focus();
  capture(handle, event.pointerId);

  const startX = event.clientX;
  const gesture = new AbortController();
  const { signal } = gesture;
  const finish = (ended: PointerEvent): void => {
    if (ended.pointerId !== event.pointerId) return;
    gesture.abort();
    handlers.done();
  };

  handle.addEventListener(
    'pointermove',
    (move: PointerEvent) => {
      if (move.pointerId !== event.pointerId) return;
      move.preventDefault();
      handlers.move(startWidth + move.clientX - startX);
    },
    { signal },
  );
  handle.addEventListener('pointerup', finish, { signal });
  handle.addEventListener('pointercancel', finish, { signal });
}

import { prefs } from '../state/prefs.svelte';
import { attachTip } from '../tooltip-attach';
import { startColumnDrag, startColumnResize } from './columnGesture';

export interface TableLayoutOptions {
  /** Stable preference key, shared with no other table. */
  id: string;
  /** Stable column ids in the order the component renders them. */
  columns: readonly string[];
}

const MIN_WIDTH = 56;
const MAX_WIDTH = 640;

/**
 * Add the same resize and reorder behaviour to the few hand-written tables
 * that are too small or specialised to be DataGrids. The action owns only a
 * colgroup and the two controls it adds to each heading; the component keeps
 * owning every row and cell.
 */
export function tableLayout(node: HTMLTableElement, initial: TableLayoutOptions) {
  let options = initial;
  let applying = false;
  const widths: Record<string, number> = {};
  const defaults: Record<string, number> = {};
  const disposers: Array<() => void> = [];

  node.dataset.managedTable = 'true';
  const frame = node.parentElement;
  frame?.classList.add('managed-table-frame');

  let colgroup = node.querySelector<HTMLTableColElement>('colgroup[data-table-layout]');
  if (!colgroup) {
    colgroup = document.createElement('colgroup');
    colgroup.dataset.tableLayout = 'true';
    node.insertBefore(colgroup, node.firstChild);
  }

  function cells(row: HTMLTableRowElement): HTMLElement[] {
    return Array.from(row.children).filter(
      (child): child is HTMLElement => child instanceof HTMLTableCellElement,
    );
  }

  function tagSourceCells(): void {
    for (const row of node.querySelectorAll<HTMLTableRowElement>('tr')) {
      const rowCells = cells(row);
      for (let index = 0; index < rowCells.length; index += 1) {
        if (!rowCells[index]!.dataset.tableColumn && options.columns[index]) {
          rowCells[index]!.dataset.tableColumn = options.columns[index]!;
        }
      }
    }
  }

  function measure(columnID: string): number {
    const candidates = Array.from(
      node.querySelectorAll<HTMLElement>(`[data-table-column="${CSS.escape(columnID)}"]`),
    ).slice(0, 21);
    const content = candidates.reduce((largest, cell) => Math.max(largest, cell.scrollWidth), 0);
    return Math.max(MIN_WIDTH, Math.min(MAX_WIDTH, content + 20));
  }

  /**
   * How the table is sized, and in what units its columns are written.
   *
   * `share` is the case a table gets before anybody has touched it: the
   * measured columns want more room than the frame has, so the table takes the
   * frame and the columns take it in the proportions they asked for. Writing
   * the table `100%` and leaving the columns in pixels is not enough -- a
   * colgroup in absolute units wins, and the table went on being drawn at the
   * measured total inside a frame two hundred pixels narrower, which is a
   * sideways scroll on a table nobody had resized.
   *
   * `measure` is every other case: on a phone, and once an operator has
   * resized a column, the explicit measure wins and the frame scrolls if it
   * must. Shrinking every other column to keep the table inside the window
   * would make the resize handle lie about what it did.
   */
  function sizing(): { mode: 'share' | 'measure'; total: number } {
    const total = prefs
      .columnOrder(options.id, options.columns)
      .reduce((sum, id) => sum + (widths[id] ?? defaults[id] ?? MIN_WIDTH), 0);
    const custom = options.columns.some((id) => widths[id] !== undefined);
    const phone = matchMedia('(max-width: 768px)').matches;
    const share = !phone && !custom && frame !== null && total >= frame.clientWidth && total > 0;
    return { mode: share ? 'share' : 'measure', total };
  }

  function setTableWidth(): void {
    if (matchMedia('(max-width: 768px)').matches) {
      node.style.removeProperty('width');
      return;
    }
    const { mode, total } = sizing();
    node.style.width = mode === 'share' ? '100%' : `${Math.ceil(total)}px`;
  }

  function apply(): void {
    if (applying) return;
    applying = true;
    tagSourceCells();
    const order = prefs.columnOrder(options.id, options.columns);
    for (const id of order) {
      const saved = prefs.columnWidth(options.id, id);
      if (saved !== undefined) widths[id] = saved;
      if (defaults[id] === undefined) defaults[id] = measure(id);
    }
    for (const row of node.querySelectorAll<HTMLTableRowElement>('tr')) {
      const byID = new Map(cells(row).map((cell) => [cell.dataset.tableColumn ?? '', cell]));
      const desired = order.flatMap((id) => {
        const cell = byID.get(id);
        return cell ? [cell] : [];
      });
      const present = cells(row);
      if (desired.some((cell, index) => present[index] !== cell)) {
        for (const cell of desired) row.appendChild(cell);
      }
    }
    // Decided before the columns are written, because it decides their units.
    const layout = sizing();
    const existing = new Map(
      Array.from(colgroup!.children).map((col) => [(col as HTMLElement).dataset.tableColumn, col]),
    );
    const desiredCols: HTMLTableColElement[] = [];
    for (const id of order) {
      let col = existing.get(id) as HTMLTableColElement | undefined;
      if (!col) {
        col = document.createElement('col');
        col.dataset.tableColumn = id;
      }
      const want = widths[id] ?? defaults[id] ?? MIN_WIDTH;
      col.style.width =
        layout.mode === 'share' ? `${((want / layout.total) * 100).toFixed(4)}%` : `${want}px`;
      desiredCols.push(col);
    }
    if (desiredCols.some((col, index) => colgroup!.children[index] !== col)) {
      for (const col of desiredCols) colgroup!.appendChild(col);
    }
    setTableWidth();
    applying = false;
  }

  function move(source: string, target: string): void {
    if (!source || source === target) return;
    const order = prefs.columnOrder(options.id, options.columns);
    const from = order.indexOf(source);
    const to = order.indexOf(target);
    if (from < 0 || to < 0) return;
    order.splice(from, 1);
    order.splice(to, 0, source);
    prefs.setColumnOrder(options.id, order);
    apply();
  }

  function addControls(): void {
    for (const heading of node.querySelectorAll<HTMLTableCellElement>('thead th')) {
      const id = heading.dataset.tableColumn;
      if (!id || heading.querySelector('[data-table-layout-control]')) continue;
      heading.classList.add('managed-table-heading');
      const label = heading.textContent?.trim() || 'this';

      const grip = document.createElement('button');
      grip.type = 'button';
      grip.className = 'managed-table-move';
      grip.dataset.tableLayoutControl = 'true';
      grip.textContent = '⋮⋮';
      grip.setAttribute('aria-label', `Reposition ${label} column`);
      disposers.push(
        attachTip(grip, {
          text: 'Drag to reposition; use left and right arrow keys for keyboard control',
        }),
      );
      const onGripKey = (event: KeyboardEvent): void => {
        if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
        event.preventDefault();
        const order = prefs.columnOrder(options.id, options.columns);
        const index = order.indexOf(id);
        const target = order[index + (event.key === 'ArrowLeft' ? -1 : 1)];
        if (target) move(id, target);
      };
      const clearDragMarks = (): void => {
        for (const th of node.querySelectorAll<HTMLElement>('thead th')) {
          th.classList.remove('managed-table-drop-target', 'managed-table-dragging');
        }
      };
      const onGripPointerDown = (event: PointerEvent): void => {
        // As in the grid: the last heading crossed stays the target, so a drag
        // that ends a little off the heading row still lands.
        let target = '';
        startColumnDrag(event, node, {
          over: (over) => {
            if (over) target = over;
            heading.classList.add('managed-table-dragging');
            for (const th of node.querySelectorAll<HTMLElement>('thead th')) {
              th.classList.toggle(
                'managed-table-drop-target',
                th.dataset.tableColumn === target && target !== id,
              );
            }
          },
          drop: (dropped) => {
            if (dropped) target = dropped;
            clearDragMarks();
            if (target) move(id, target);
          },
          cancel: clearDragMarks,
        });
      };
      grip.addEventListener('keydown', onGripKey);
      grip.addEventListener('pointerdown', onGripPointerDown);
      disposers.push(() => grip.removeEventListener('keydown', onGripKey));
      disposers.push(() => grip.removeEventListener('pointerdown', onGripPointerDown));
      heading.insertBefore(grip, heading.firstChild);

      const resize = document.createElement('button');
      resize.type = 'button';
      resize.className = 'managed-table-resizer';
      resize.dataset.tableLayoutControl = 'true';
      resize.setAttribute('aria-label', `Resize ${label} column`);
      disposers.push(
        attachTip(resize, { text: 'Drag to resize; double-click to restore the default width' }),
      );
      const onPointerDown = (event: PointerEvent): void => {
        startColumnResize(event, heading.getBoundingClientRect().width, {
          move: (width) => {
            widths[id] = Math.max(MIN_WIDTH, Math.min(MAX_WIDTH, width));
            apply();
          },
          done: () => {
            if (widths[id] !== undefined) prefs.setColumnWidth(options.id, id, widths[id]);
          },
        });
      };
      const onResizeKey = (event: KeyboardEvent): void => {
        if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
        event.preventDefault();
        const current = heading.getBoundingClientRect().width;
        widths[id] = Math.max(
          MIN_WIDTH,
          Math.min(MAX_WIDTH, current + (event.key === 'ArrowRight' ? 8 : -8)),
        );
        prefs.setColumnWidth(options.id, id, widths[id]!);
        apply();
      };
      const onDoubleClick = (): void => {
        delete widths[id];
        prefs.clearColumnWidth(options.id, id);
        apply();
      };
      resize.addEventListener('pointerdown', onPointerDown);
      resize.addEventListener('keydown', onResizeKey);
      resize.addEventListener('dblclick', onDoubleClick);
      disposers.push(() => resize.removeEventListener('pointerdown', onPointerDown));
      disposers.push(() => resize.removeEventListener('keydown', onResizeKey));
      disposers.push(() => resize.removeEventListener('dblclick', onDoubleClick));
      heading.appendChild(resize);
    }
  }

  const onViewport = (): void => setTableWidth();
  tagSourceCells();
  addControls();
  apply();
  const observer = new MutationObserver(() => {
    if (applying) return;
    queueMicrotask(() => {
      tagSourceCells();
      addControls();
      apply();
    });
  });
  observer.observe(node.tBodies.item(0) ?? node, { childList: true, subtree: true });
  addEventListener('resize', onViewport);

  return {
    update(next: TableLayoutOptions) {
      options = next;
      tagSourceCells();
      addControls();
      apply();
    },
    destroy() {
      observer.disconnect();
      removeEventListener('resize', onViewport);
      for (const dispose of disposers) dispose();
      frame?.classList.remove('managed-table-frame');
    },
  };
}

/**
 * Whether an address only the controller's own machine can reach.
 *
 * The same rule as `loopbackHost` in `internal/config`: localhost, any name
 * under `.localhost`, and the loopback ranges. Two dialogs had a copy of this
 * each and they did not agree -- one knew about `.localhost` and the whole
 * `127.0.0.0/8` range, the other matched exactly `127.0.0.1` -- so a controller
 * reached on `127.0.0.2` was refused by the host flow and accepted by the
 * GitHub App dialog, which is the one that bakes the address into an App for
 * ever.
 */
export function isLoopbackHost(host: string): boolean {
  const bare = host.replace(/^\[|\]$/g, '').toLowerCase();
  if (bare === 'localhost' || bare.endsWith('.localhost')) return true;
  if (bare === '::1' || bare === '0:0:0:0:0:0:0:1') return true;
  return /^127\.\d{1,3}\.\d{1,3}\.\d{1,3}$/.test(bare);
}

/**
 * The same question asked of a whole URL. An address that will not parse is
 * not treated as local: the caller's next step is to complain about it, and
 * "this is only reachable from here" would be the wrong complaint.
 */
export function isLoopbackURL(raw: string): boolean {
  try {
    return isLoopbackHost(new URL(raw).hostname);
  } catch {
    return false;
  }
}

/**
 * Where a command run on another machine should be told to find the controller.
 *
 * `server.external_url` is right when it is set and is not loopback: the default
 * single-VM install sets it to http://localhost:8080, which no other machine
 * answers on. Failing that, the address this browser is using is the best guess
 * there is, because a machine on the same network usually reaches the controller
 * the way an operator does.
 *
 * It is one function because two places hand an address to somebody to paste --
 * the command that adds a host and the one that reads its health -- and an
 * address that differed between them would be one of them wrong.
 */
export function suggestedControllerURL(configured: string | undefined, origin: string): string {
  const url = (configured ?? '').replace(/\/+$/, '');
  if (url && !isLoopbackURL(url)) return url;
  return origin;
}

/**
 * Whether AI Context needs somebody, and how many repositories it is for.
 *
 * The controller raises one problem for each repository whose last workflow run
 * failed, and says which repository in the problem's target. Those problems are
 * already on every page, so the answer needs no request of its own and follows the
 * stream: the badge appears when a run fails and goes when the next one passes.
 *
 * It counts repositories whose run failed, and nothing else. A repository waiting
 * for its setup pull request to be merged is not failing, and one that has never
 * been enabled is not anybody's problem, so a fleet with AI Context working, or
 * with none, has no badge at all.
 */
import type { Problem } from '../api/types';

export interface AiContextAttention {
  /** Repositories whose last AI Context workflow run failed. */
  count: number;
  /** The worst severity among them, which is how the badge is drawn. */
  worst: 'error' | 'warning';
  /** The same, in a sentence, for a tooltip and for somebody who cannot see the badge. */
  text: string;
}

export function aiContextAttention(
  problems: readonly Pick<Problem, 'target_kind' | 'severity'>[],
): AiContextAttention | null {
  const failing = problems.filter((problem) => problem.target_kind === 'ai_context');
  if (failing.length === 0) return null;
  const count = failing.length;
  return {
    count,
    worst: failing.some((problem) => problem.severity === 'error') ? 'error' : 'warning',
    text: count === 1 ? '1 repository needs attention' : `${count} repositories need attention`,
  };
}

/*
 * Setup opened from a repository's page.
 *
 * A repository's AI Context tab links to setup with the repository's GitHub ID,
 * and the wizard ticks it once, when the installation's list of repositories
 * arrives. Anything else about choosing repositories stays as it was: nothing is
 * preselected unless a person came from one.
 *
 * The address is anybody's to write, so the ID in it is trusted only as far as it
 * looks like one of GitHub's, and then only to be looked for in the list the server
 * returned. It selects nothing that list does not hold, and selecting is not
 * publishing: setup still ends in a pull request somebody reviews.
 */

/**
 * The repository an address names: a positive whole number, as GitHub's IDs are,
 * or nothing. Past the largest integer a number holds exactly, two IDs would be
 * one, so those name nothing either.
 */
export function repositoryIdFromAddress(raw: string): number | undefined {
  if (!/^[1-9]\d*$/.test(raw)) return undefined;
  const id = Number(raw);
  return Number.isSafeInteger(id) ? id : undefined;
}

/** What the installation step says about choosing, given the repository the person came from, if any. */
export function installationHint(cameFrom: string | null): string {
  return cameFrom
    ? `Choose one installation at a time. ${cameFrom} is selected because you came from its page.`
    : 'Choose one installation at a time. No repository is preselected.';
}

// Said instead of nothing: a person who followed a link from a repository and
// finds none chosen would otherwise wonder what the link was for.

/** The repository the person came from is not in the list the server returned. */
export const NOT_FOUND_NOTE =
  "The repository you came from is not among this installation's repositories, so none is selected.";

/** The repository the person came from is listed, but setup is not offered for an archived one. */
export function archivedNote(name: string): string {
  return `${name} is archived and cannot be set up, so none is selected.`;
}

import type { AiContextItem } from './types';

/**
 * The one state a card is drawn in. The page and the card share it so a count
 * in the summary and the badge on the row can never disagree.
 */
export type AiContextItemState =
  | 'stale'
  | 'unavailable'
  | 'ready'
  | 'draft'
  | 'review'
  | 'awaiting_merge'
  | 'attention'
  | 'working'
  | 'available';

export function aiContextItemState(item: AiContextItem): AiContextItemState {
  if (!('config' in item)) return 'available';
  if (item.freshness?.state) return item.freshness.state;
  if (item.available) return 'available';
  if (item.setup_state === 'awaiting_merge') return 'awaiting_merge';
  if (item.setup_state === 'pending') return 'working';
  if (item.diagnosis) return 'attention';
  return 'draft';
}

export function aiContextNeedsAttention(state: AiContextItemState): boolean {
  return state === 'stale' || state === 'unavailable' || state === 'attention';
}

export function aiContextReady(state: AiContextItemState): boolean {
  return state === 'ready' || state === 'available';
}

export function aiContextInSetup(state: AiContextItemState): boolean {
  return (
    state === 'draft' || state === 'review' || state === 'awaiting_merge' || state === 'working'
  );
}

import type { AIContextRepository } from '../api/types';

/** An installation this person may enable repositories for, by the name it is shown under. */
export type KnownInstallation = { id: string; target: string };

/**
 * What the card draws. An administrator or an installation's owner is given the
 * whole record; somebody who has only been made a reader of the source is given the
 * little that lets them use it, so the card has to cope with both.
 */
export type AiContextItem =
  | AIContextRepository
  | { id: string; full_name: string; instructions?: string; badge_markdown?: string };

/**
 * Reading an assistant's answer.
 *
 * The answer is a Server-Sent Events body that arrives in whatever pieces the
 * network cuts it into, so a frame can begin in one chunk and end in the next.
 * The parser holds the unfinished part until the blank line that ends it, and
 * says nothing about a frame whose kind or payload it does not understand: a
 * newer controller may send one, and an older page should keep reading.
 */

export type ChatFrame =
  | { kind: 'delta'; text: string }
  | { kind: 'usage'; inputTokens: number; outputTokens: number }
  | { kind: 'tool'; name: string; status: 'running' | 'done' | 'failed'; reason?: string }
  | {
      kind: 'done';
      provider: string;
      model: string;
      fleetAccess: boolean;
      tools: string[];
      /** How many credentials and email addresses were hidden from the model. */
      redacted: { credentials: number; emails: number };
      /** The provider stopped the answer at its output ceiling, not because the model had finished. */
      cut: boolean;
      /** The provider that answered, and the ceiling in force, so a cut answer can say what to raise. */
      providerId: string;
      outputLimit: number;
    }
  | { kind: 'error'; message: string };

export class FrameParser {
  private pending = '';

  /** The frames a chunk completes, in order. */
  push(chunk: string): ChatFrame[] {
    this.pending += chunk.replace(/\r\n/g, '\n');
    const frames: ChatFrame[] = [];
    let end: number;
    while ((end = this.pending.indexOf('\n\n')) >= 0) {
      const block = this.pending.slice(0, end);
      this.pending = this.pending.slice(end + 2);
      const frame = parseBlock(block);
      if (frame) frames.push(frame);
    }
    return frames;
  }
}

function parseBlock(block: string): ChatFrame | undefined {
  let kind = '';
  const data: string[] = [];
  for (const line of block.split('\n')) {
    if (line.startsWith('event:')) kind = line.slice(6).trim();
    else if (line.startsWith('data:')) data.push(line.slice(5).replace(/^ /, ''));
  }
  if (!kind) return undefined;
  let payload: Record<string, unknown>;
  try {
    const parsed: unknown = JSON.parse(data.join('\n'));
    if (typeof parsed !== 'object' || parsed === null) return undefined;
    payload = parsed as Record<string, unknown>;
  } catch {
    return undefined;
  }
  const text = (key: string) => (typeof payload[key] === 'string' ? (payload[key] as string) : '');
  const count = (key: string) => (typeof payload[key] === 'number' ? (payload[key] as number) : 0);
  switch (kind) {
    case 'delta':
      return { kind, text: text('text') };
    case 'usage':
      return { kind, inputTokens: count('input_tokens'), outputTokens: count('output_tokens') };
    case 'tool': {
      const status = text('status');
      // A status this page does not know is not a look it can show.
      if (status !== 'running' && status !== 'done' && status !== 'failed') return undefined;
      const reason = text('reason');
      return reason
        ? { kind, name: text('name'), status, reason }
        : { kind, name: text('name'), status };
    }
    case 'done': {
      const redacted =
        typeof payload['redacted'] === 'object' && payload['redacted'] !== null
          ? (payload['redacted'] as Record<string, unknown>)
          : {};
      const tools = Array.isArray(payload['tools'])
        ? payload['tools'].filter((t): t is string => typeof t === 'string')
        : [];
      return {
        kind,
        provider: text('provider'),
        model: text('model'),
        fleetAccess: payload['fleet_access'] === true,
        tools,
        redacted: {
          credentials: wholeCount(redacted['credentials']),
          emails: wholeCount(redacted['emails']),
        },
        cut: payload['cut'] === true,
        providerId: text('provider_id'),
        outputLimit: wholeCount(payload['output_limit']),
      };
    }
    case 'error':
      return { kind, message: text('message') };
    default:
      return undefined;
  }
}

/** A count from the controller, and nothing at all when it is not a whole number. */
function wholeCount(v: unknown): number {
  return typeof v === 'number' && Number.isInteger(v) && v > 0 ? v : 0;
}

/**
 * One shared connection to /api/v1/events for the whole application.
 *
 * This, and not the refresh button, is what stands between the operator and a
 * stale screen: refreshing is a thing somebody chooses to do, and a dashboard
 * on a second monitor has nobody choosing anything. It therefore never throws:
 * a dead connection is a state the top bar renders, not an exception a page has
 * to catch.
 *
 * Reconnection has two paths, deliberately:
 *
 *  * The browser's own EventSource retry, which resends `Last-Event-ID` and so
 *    lets the server replay what it buffered. We leave that alone and just
 *    report `reconnecting` while it happens.
 *  * Our own backoff, for when the browser gives up (a non-2xx response closes
 *    an EventSource for good). Because a fresh EventSource has no last id to
 *    send, we carry it in the query string instead.
 *
 * Either way, regaining focus or coming back online retries immediately rather
 * than waiting out the backoff -- an operator who has just opened the laptop
 * lid should not stare at "reconnecting" for fifteen seconds.
 */
import { api, apiBase } from './client';
import type { EventKind, EventPayloads } from './types';

export type SseStatus = 'connecting' | 'live' | 'reconnecting' | 'offline';

type AnyListener = (data: unknown, id: string | undefined) => void;
type StatusListener = (status: SseStatus) => void;

const BACKOFF_BASE = 500;
const BACKOFF_CAP = 15_000;
/** Server heartbeat is every 20s; three missed ones means something is wrong. */
const WATCHDOG_MS = 70_000;

class EventStream {
  #source: EventSource | null = null;
  #status: SseStatus = 'offline';
  #lastEventId: string | null = null;
  #attempt = 0;
  #retryTimer: ReturnType<typeof setTimeout> | null = null;
  #watchdog: ReturnType<typeof setTimeout> | null = null;
  #heartbeats = false;
  #started = false;
  #bound = false;

  readonly #listeners = new Map<EventKind, Set<AnyListener>>();
  readonly #statusListeners = new Set<StatusListener>();

  get status(): SseStatus {
    return this.#status;
  }

  get lastEventId(): string | null {
    return this.#lastEventId;
  }

  /** Open the stream. Safe to call more than once. */
  start(): void {
    if (this.#started) return;
    this.#started = true;
    this.#bindWindow();
    this.#openAfterLoad();
  }

  /**
   * Open once the page has finished loading, not while it is.
   *
   * A stream that never ends and is opened during load keeps the tab's spinner
   * going for as long as it stays open -- Firefox and Safari count it as part of
   * the page still loading. The shell starts us from an effect that runs well
   * before `load` on a cold open, so wait for it, then one more task so the
   * browser has settled before the connection goes out.
   */
  #openAfterLoad(): void {
    if (typeof document === 'undefined' || document.readyState === 'complete') {
      this.#open();
      return;
    }
    window.addEventListener(
      'load',
      () => {
        setTimeout(() => {
          // stop() or reconnectNow() may have run while we waited.
          if (this.#started && !this.#source && !this.#retryTimer) this.#open();
        }, 0);
      },
      { once: true },
    );
  }

  /** Close the stream and stop retrying. Used on sign-out. */
  stop(): void {
    this.#started = false;
    this.#clearTimers();
    this.#close();
    this.#setStatus('offline');
  }

  /** Drop the current connection and open a new one now, resetting the backoff. */
  reconnectNow(): void {
    if (!this.#started) return;
    this.#clearTimers();
    this.#close();
    this.#attempt = 0;
    this.#open();
  }

  /**
   * Listen for one or more event kinds. Returns the unsubscribe function; call
   * it from an `$effect` teardown.
   */
  subscribe<K extends EventKind>(
    kinds: K | readonly K[],
    handler: (data: EventPayloads[K], id: string | undefined) => void,
  ): () => void {
    const list = (Array.isArray(kinds) ? kinds : [kinds]) as readonly K[];
    const wrapped: AnyListener = (data, id) => handler(data as EventPayloads[K], id);
    for (const kind of list) {
      let set = this.#listeners.get(kind);
      if (!set) {
        set = new Set();
        this.#listeners.set(kind, set);
      }
      set.add(wrapped);
      if (this.#source) this.#attachKind(this.#source, kind);
    }
    return () => {
      for (const kind of list) this.#listeners.get(kind)?.delete(wrapped);
    };
  }

  /** Listen for connection-state changes. Fires immediately with the current one. */
  onStatus(handler: StatusListener): () => void {
    this.#statusListeners.add(handler);
    handler(this.#status);
    return () => this.#statusListeners.delete(handler);
  }

  /* -- internals --------------------------------------------------------- */

  #bindWindow(): void {
    if (this.#bound || typeof window === 'undefined') return;
    this.#bound = true;
    const wake = () => {
      if (!this.#started) return;
      if (this.#status === 'live') return;
      this.reconnectNow();
    };
    window.addEventListener('online', wake);
    window.addEventListener('focus', wake);
    window.addEventListener('offline', () => {
      if (this.#started) this.#setStatus('offline');
    });
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible') wake();
    });
  }

  #open(): void {
    if (typeof EventSource === 'undefined') return;
    if (typeof navigator !== 'undefined' && navigator.onLine === false) {
      this.#setStatus('offline');
      return;
    }
    this.#setStatus(this.#attempt === 0 ? 'connecting' : 'reconnecting');

    // A fresh EventSource cannot send the Last-Event-ID header, so the id
    // travels in the query string on a manual reconnect. Servers that only
    // read the header ignore it, which costs nothing.
    const query = this.#lastEventId
      ? `?last_event_id=${encodeURIComponent(this.#lastEventId)}`
      : '';
    let source: EventSource;
    try {
      source = new EventSource(`${apiBase}/events${query}`);
    } catch {
      this.#scheduleRetry();
      return;
    }
    this.#source = source;

    source.onopen = () => {
      this.#attempt = 0;
      this.#setStatus('live');
      this.#armWatchdog();
    };
    source.onmessage = (e) => this.#dispatch('heartbeat', e);
    // The controller saying "stop": the credential this stream was opened with
    // has been signed out, revoked, disabled or has expired. Without this the
    // stream still ends -- the response closes and the retry's session probe
    // eventually asks -- but the tab spends a reconnect cycle looking merely
    // unlucky first, and the probe is what has to notice. Acting on the frame
    // asks straight away, and stops the retry that would otherwise reopen a
    // stream the server has just refused.
    source.addEventListener('end', () => {
      this.#close();
      this.#setStatus('reconnecting');
      void this.#probeSession();
    });
    source.onerror = () => {
      // readyState CONNECTING means the browser is retrying by itself and will
      // resend Last-Event-ID; leave it to do that and just report the state.
      if (source.readyState === EventSource.CONNECTING) {
        this.#setStatus('reconnecting');
        return;
      }
      this.#close();
      this.#scheduleRetry();
    };
    for (const kind of this.#listeners.keys()) this.#attachKind(source, kind);
    // Heartbeats are always listened for: they drive the stall watchdog.
    this.#attachKind(source, 'heartbeat');
  }

  #attachKind(source: EventSource, kind: EventKind): void {
    const flag = `zoomies:${kind}`;
    const marked = source as EventSource & { [key: string]: unknown };
    if (marked[flag]) return;
    marked[flag] = true;
    source.addEventListener(kind, (e) => this.#dispatch(kind, e as MessageEvent<string>));
  }

  #dispatch(kind: EventKind, e: MessageEvent<string>): void {
    if (e.lastEventId) this.#lastEventId = e.lastEventId;
    if (kind === 'heartbeat') {
      this.#heartbeats = true;
      this.#armWatchdog();
    } else {
      this.#armWatchdog();
    }
    const listeners = this.#listeners.get(kind);
    if (!listeners || listeners.size === 0) return;
    let data: unknown;
    try {
      data = e.data ? JSON.parse(e.data) : undefined;
    } catch {
      // A malformed frame is the server's problem, not something a page should
      // ever see as an exception. Drop it and keep the stream alive.
      return;
    }
    for (const fn of listeners) {
      try {
        fn(data, e.lastEventId || undefined);
      } catch {
        // A broken subscriber must not take the connection down with it.
      }
    }
  }

  /**
   * Guards against the connection that is open but silent -- a proxy holding a
   * dead socket. Only armed once we have actually seen a heartbeat event, so a
   * server that heartbeats with comment frames does not get reconnected every
   * seventy seconds for no reason.
   */
  #armWatchdog(): void {
    if (this.#watchdog) clearTimeout(this.#watchdog);
    if (!this.#heartbeats) return;
    this.#watchdog = setTimeout(() => {
      if (this.#started) this.reconnectNow();
    }, WATCHDOG_MS);
  }

  /**
   * Find out whether the server is refusing us rather than merely absent.
   *
   * EventSource cannot see why a connection was closed, and a 401 -- the
   * session expiring while the Overview sat on a second monitor -- looks
   * exactly like a controller restart from here: "Reconnecting" for ever
   * over numbers that have quietly stopped moving. One ordinary request per
   * retry answers the question. A 401 runs the client's sign-out hook, which
   * takes the operator to the login page; anything else is left to the retry.
   */
  async #probeSession(): Promise<void> {
    if (typeof navigator !== 'undefined' && navigator.onLine === false) return;
    try {
      await api.get('/auth/session');
    } catch {
      // Either the 401 hook has already acted, or the controller is not
      // answering at all, which the retry is for.
    }
  }

  #scheduleRetry(): void {
    if (!this.#started) return;
    this.#setStatus(navigator?.onLine === false ? 'offline' : 'reconnecting');
    void this.#probeSession();
    const delay = Math.min(BACKOFF_CAP, BACKOFF_BASE * 2 ** this.#attempt);
    // A little jitter so a controller restart does not bring every open dashboard
    // back at exactly the same instant.
    const jittered = delay * (0.75 + Math.random() * 0.5);
    this.#attempt += 1;
    if (this.#retryTimer) clearTimeout(this.#retryTimer);
    this.#retryTimer = setTimeout(() => this.#open(), jittered);
  }

  #close(): void {
    if (this.#source) {
      this.#source.onopen = null;
      this.#source.onerror = null;
      this.#source.onmessage = null;
      this.#source.close();
      this.#source = null;
    }
  }

  #clearTimers(): void {
    if (this.#retryTimer) clearTimeout(this.#retryTimer);
    if (this.#watchdog) clearTimeout(this.#watchdog);
    this.#retryTimer = null;
    this.#watchdog = null;
  }

  #setStatus(next: SseStatus): void {
    if (this.#status === next) return;
    this.#status = next;
    for (const fn of this.#statusListeners) {
      try {
        fn(next);
      } catch {
        // Same reasoning as above.
      }
    }
  }
}

/** The one stream. Started by the shell once the visitor is authenticated. */
export const events = new EventStream();

/**
 * Friendly names for the generated OpenAPI types, plus the small amount of type
 * machinery the hand-written client needs.
 *
 * `schema.d.ts` is generated from `api/openapi.yaml` and must never be edited.
 * Everything in the UI that touches the API goes through the aliases here, so a
 * change to the OpenAPI document breaks the build rather than the runtime.
 */
import type { components, operations } from './schema';

export type Schemas = components['schemas'];
export type Ops = operations;

/* -- enumerations ------------------------------------------------------- */

export type Role = Schemas['Role'];
export type TargetType = Schemas['TargetType'];
export type BackendKind = Schemas['BackendKind'];
export type DockerMode = Schemas['DockerMode'];
export type RunnerState = Schemas['RunnerState'];
export type JobState = Schemas['JobState'];
export type Severity = Schemas['Severity'];
export type MachineState = Schemas['MachineState'];
export type GoDuration = Schemas['Duration'];
export type ErrorCode = Schemas['ErrorEnvelope']['error']['code'];

/** Every runner state, in the order an operator thinks about them. */
export const RUNNER_STATES: readonly RunnerState[] = [
  'provisioning',
  'registering',
  'idle',
  'busy',
  'draining',
  'failed',
  'removed',
];

/** Every job state. */
export const JOB_STATES: readonly JobState[] = ['waiting', 'queued', 'in_progress', 'completed'];

/**
 * What an operator has done to a queued job's provisioning demand.
 *
 * Taken from the API's own enumeration so the Queue and the Jobs page cannot
 * drift apart on the spelling. `ready` and `expedited` are the two halves of
 * an untouched job -- normal demand, and demand an operator expedited -- and
 * the other two are the ways of standing it down.
 */
export type ProvisioningStatus = NonNullable<Query<'listJobs'>['provisioning']>[number];

export const PROVISIONING_STATUSES: readonly ProvisioningStatus[] = [
  'ready',
  'expedited',
  'paused',
  'deleted',
];

/**
 * The statuses that still mean "waiting for a runner here".
 *
 * A paused job is on hold and still waiting; a removed one is an operator
 * saying it should not run here at all, and it stops counting as queued work
 * everywhere the fleet reports queue depth. Any list that calls itself Queued
 * narrows to these, so the list and the figure above it say the same thing.
 */
export const WAITING_PROVISIONING: readonly ProvisioningStatus[] = ['ready', 'expedited', 'paused'];

/**
 * Every machine state, in the order a machine passes through them. Deleted,
 * failed and quarantined are exits from the flow rather than steps of it, and
 * come last for that reason.
 */
export const MACHINE_STATES: readonly MachineState[] = [
  'planned',
  'creating',
  'starting',
  'bootstrapping',
  'enrolling',
  'ready',
  'draining',
  'deleting',
  'deleted',
  'failed',
  'quarantined',
];

/** The roles, weakest first. `atLeast` below compares by this order. */
export const ROLES: readonly Role[] = ['viewer', 'operator', 'admin', 'platform'];

