}

export interface UsageRowFacts {
  key: string;
  jobs: number;
  jobs_completed: number;
  job_execution_seconds: number;
  allocated_runner_seconds: number | null;
  average_queue_wait_seconds: number | null;
  peak_concurrency: number;
  estimated_cost?: number;
}

export interface UsageFacts {
  grouping: string;
  since: string;
  until: string;
  /** The one group the page is focused on, or empty for all of them. */
  entity?: string;
  rows: readonly UsageRowFacts[];
  /** Whether runner time can be attributed at this grouping at all. */
  attributable: boolean;
}

/**
 * The usage report's totals, not its rows: a report is a table, and a table
 * pasted into a question is read by nobody. Eli has get_usage for the rows.
 */
export function usageContext(usage: UsageFacts): EliContext {
  const sum = (pick: (r: UsageRowFacts) => number | null | undefined): number =>
    usage.rows.reduce((total, r) => total + (pick(r) ?? 0), 0);
  const hours = (seconds: number): number => Math.round((seconds / 3600) * 100) / 100;
  const executed = sum((r) => r.job_execution_seconds);
  const allocated = usage.attributable ? sum((r) => r.allocated_runner_seconds) : null;
  const priced = usage.attributable && usage.rows.some((r) => r.estimated_cost !== undefined);
  const waits = usage.rows
    .map((r) => r.average_queue_wait_seconds)
    .filter((w): w is number => w !== null);
  return {
    kind: 'usage report',
    title: usage.entity ? `${usage.grouping} ${usage.entity}` : `Usage by ${usage.grouping}`,
    facts: {
      From: usage.since,
      To: usage.until,
      'Grouped by': usage.grouping,
      Groups: usage.rows.length,
      Jobs: sum((r) => r.jobs),
      'Jobs completed': sum((r) => r.jobs_completed),
      'Execution hours': hours(executed),
      'Runner-hours': allocated === null ? undefined : hours(allocated),
      'Utilisation (%)':
        allocated !== null && allocated > 0 ? Math.round((executed / allocated) * 100) : undefined,
      'Longest mean queue wait (s)': waits.length ? Math.round(Math.max(...waits)) : undefined,
      'Peak concurrency': usage.rows.length
        ? Math.max(...usage.rows.map((r) => r.peak_concurrency))
        : undefined,
      'Estimated cost': priced ? Math.round(sum((r) => r.estimated_cost) * 100) / 100 : undefined,
    },
    question: 'What stands out in this usage, and where is the waste or the waiting?',
  };
}

/**
 * One conversation with Eli, held in memory.
 *
 * The controller keeps nothing between questions: the page sends what was said
 * with each new one, so this is the only place a conversation lives, and a
 * reload ends it. It is a module and not a component's state so that the same
 * conversation can be shown in more than one place and survives moving between
 * pages, which a floating panel needs.
 */
import {
  ApiError,
  createAssistantConversation,
  replaceAssistantConversation,
  streamAssistantChat,
} from '$lib/api/client';
import { session } from '$lib/state/session.svelte';
import { historyFor, transcript, turnsFrom, type StoredMessage } from './history';
import { sentence, supportHint } from '$lib/errors';
import { isRefusal, refusalKind, type RefusalKind } from './limits';
import { router } from '$lib/router';
import { prefs } from '$lib/state/prefs.svelte';
import { hiddenNote } from './redaction';
import { splitFollowUps, type EliContext, type Suggestion } from './prompts';

export interface Turn {
  id: number;
  role: 'user' | 'assistant';
  content: string;
  context?: EliContext;
  /** Who answered, once the answer says: the provider and the model. */
  by?: string;
  tokens?: string;
  /** What Eli looked at while answering, in the order it looked. */
  tools?: ToolLook[];
  /** Whether the fleet could be read through the provider that answered. */
  fleetAccess?: boolean;
  /** What was hidden from the model before it answered, in words, or empty. */
  hidden?: string;
  /** The provider stopped the answer at its output ceiling before the model had finished. */
  cut?: boolean;
  /** Who answered and the ceiling in force, so a cut answer can offer to raise it. */
  providerId?: string;
  outputLimit?: number;
  /** Questions the model proposed to ask next, once the answer is complete. */
  suggestions?: Suggestion[];
  error?: string;
  streaming?: boolean;
  /**
   * The controller refused this question, or the answer to it, for what it said:
   * asking again cannot change that. Such a turn is never sent as history or
   * kept, and offers no Try again.
   */
  refused?: boolean;
}

/** Why the last question was not sent, for the notice above the box. */
export interface Refusal {
  kind: RefusalKind;
  /** The controller's own words, as a sentence. */
  message: string;
}

export interface ToolLook {
  name: string;
  status: 'running' | 'done' | 'failed';
  /** Why a look failed, in one line, when the controller says. */
  reason?: string;
}

function failure(cause: unknown): string {
  return cause instanceof ApiError ? cause.message : `That could not be done. ${supportHint()}`;
}

/** Record a look: a new one when it starts, and the end of the last one still running. */
function note(answer: Turn, name: string, status: ToolLook['status'], reason?: string): void {
  const looks = (answer.tools ??= []);
  if (status === 'running') {
    looks.push({ name, status });
    return;
  }
  const open = looks.findLast((l) => l.name === name && l.status === 'running');
  if (open) {
    open.status = status;
    if (reason) open.reason = reason;
  } else looks.push({ name, status, ...(reason ? { reason } : {}) });
}

export class Conversation {
  turns = $state<Turn[]>([]);
  busy = $state(false);
  draft = $state('');
  /** The kept conversation this is, once an answer has been kept; nothing until then. */
  id = $state<string | undefined>();
  /**
   * Why the last question was not sent, until the next one is. The words went
   * back to the box, so the notice is the only trace the refusal leaves.
   */
  refusal = $state<Refusal | undefined>();
  #controller: AbortController | undefined;
  #next = 0;
  #keeping: Promise<void> | undefined;
  /** Which provider the last question went to, so that asking again goes to the same one. */
  #provider: string | undefined;

  /** Whether the last answer failed in a way asking again could cure, so the page can offer to. */
  get failed(): boolean {
    const last = this.turns[this.turns.length - 1];
    return last?.role === 'assistant' && !!last.error && !last.refused;
  }

  async send(text: string, context?: EliContext, providerId?: string): Promise<void> {
    const question = text.trim();
    if (!question || this.busy) return;
    this.#provider = providerId ?? this.#provider;
    this.refusal = undefined;
    // What was said before is what the model is told it said: a turn that failed
    // before it began has nothing to repeat, and a question the controller
    // refused was never heard.
    const history = historyFor(this.turns);
    this.turns.push({ id: this.#next++, role: 'user', content: question, context });
    const asked = this.turns[this.turns.length - 1]!;
    this.turns.push({ id: this.#next++, role: 'assistant', content: '', streaming: true });
    const answer = this.turns[this.turns.length - 1]!;
    let refused = false;
    this.busy = true;
    const controller = new AbortController();
    this.#controller = controller;
    // The answer as the model wrote it, follow-up block included; the turn holds only what is read.
    let raw = '';
    try {
      await streamAssistantChat(
        {
          messages: [...history, { role: 'user', content: question }],
          // Where the question was asked from, so "here" means something, and
          // how this person wants the answer written.
          page: router.pathname,
          style: prefs.eliStyle,
          ...(this.#provider ? { provider_id: this.#provider } : {}),
        },
        (frame) => {
          if (frame.kind === 'delta') {
            raw += frame.text;
            answer.content = splitFollowUps(raw).text;
          } else if (frame.kind === 'usage')
            answer.tokens = `${frame.inputTokens} in, ${frame.outputTokens} out`;
          else if (frame.kind === 'tool') note(answer, frame.name, frame.status, frame.reason);
          else if (frame.kind === 'done') {
            answer.suggestions = splitFollowUps(raw).suggestions;
            answer.by = `${frame.provider}, ${frame.model}`;
            answer.fleetAccess = frame.fleetAccess;
            answer.hidden = hiddenNote(frame.redacted.credentials, frame.redacted.emails);
            answer.cut = frame.cut;
            answer.providerId = frame.providerId;
            answer.outputLimit = frame.outputLimit;
          } else answer.error = frame.message || 'The model stopped answering.';
        },
        controller.signal,
      );
    } catch (cause) {
      // Stop is the person's, not a failure.
      if (cause instanceof DOMException && cause.name === 'AbortError') {
        // Nothing to record.
      } else if (cause instanceof ApiError && isRefusal(cause.status)) {
        refused = true;
        this.#refuse(cause, history.length + 1, asked, answer);
      } else answer.error = failure(cause);
    } finally {
      answer.streaming = false;
      // A conversation cleared mid-answer may already be on its next question.
      if (this.#controller === controller) {
        this.busy = false;
        this.#controller = undefined;
      }
    }
    if (!answer.error && !refused && this.#controller === undefined) await this.keep();
  }

  /**
   * The controller would not take this question as it was asked, and asking
   * again cannot change that. The person's own words go back in the box, with
   * the reason beside it, rather than staying in the thread as a bubble that
   * can only be retried into the same refusal. A question the page built from
   * what it was showing (an Ask Eli snapshot) is not words the person typed
   * and cannot be edited in the box, so it stays where it is, flagged so it is
   * not sent again, and the thread says why.
   */
  #refuse(cause: ApiError, sent: number, asked: Turn, answer: Turn): void {
    const message = sentence(cause.message);
    asked.refused = true;
    answer.refused = true;
    if (asked.context) {
      answer.error = message;
      return;
    }
    this.turns = this.turns.filter((t) => t.id !== asked.id && t.id !== answer.id);
    // A question typed while this one was being refused is not overwritten.
    this.draft = this.draft.trim() ? `${asked.content}\n\n${this.draft}` : asked.content;
    this.refusal = { kind: refusalKind(cause, sent), message };
  }

  /**
   * Keep the thread under the account, once an answer has landed. Nothing is
   * kept for a session with no account, and a keep that fails is not the
   * person's problem: the thread is still on the page, and the next answer
   * tries again. Keeps are serialised so a fast second question cannot
   * create a second conversation before the first keep has an id.
   */
  async keep(): Promise<void> {
    if (session.authDisabled || session.identity?.kind !== 'user') return;
    const messages = transcript(this.turns);
    if (messages.length < 2) return;
    const run = async () => {
      try {
        if (this.id) await replaceAssistantConversation(this.id, { messages });
        else this.id = (await createAssistantConversation({ messages })).id;
      } catch {
        // Kept next time, or not at all; a thread is never lost over it.
      }
    };
    this.#keeping = (this.#keeping ?? Promise.resolve()).then(run);
    await this.#keeping;
  }

  /** Pick a kept conversation up where it was left. */
  load(id: string, messages: readonly StoredMessage[]): void {
    this.clear();
    this.turns = turnsFrom(messages, this.#next);
    this.#next += messages.length;
    this.id = id;
  }

  /** Ask the last question again, replacing the answer that failed. */
  async retry(): Promise<void> {
    if (this.busy || !this.failed) return;
    await this.resend();
  }

  /**
   * Ask the last question again, replacing its answer, whatever that answer was:
   * after the provider's limit was raised, the cut answer is the one to replace.
   */
  async resend(): Promise<void> {
    if (this.busy) return;
    const last = this.turns[this.turns.length - 1];
    if (last?.role !== 'assistant') return;
    this.turns.pop();
    const question = this.turns.pop();
    if (question?.role === 'user') await this.send(question.content, question.context);
  }

  stop(): void {
    this.#controller?.abort();
  }

  clear(): void {
    this.#controller?.abort();
    this.#controller = undefined;
    this.busy = false;
    this.turns = [];
    this.draft = '';
    this.id = undefined;
    this.refusal = undefined;
  }
}

/**
 * Eli, as the rest of the page sees Eli: whether there is one to ask, whether the
 * panel is open, and the one conversation.
 *
 * Each signed-in account uses its personal providers. The conversation survives
 * navigation and is forgotten on sign-out or reload.
 */
import { tick } from 'svelte';
import type { EliContext } from './prompts';
import {
  deleteAssistantConversation,
  getAssistantConversation,
  listAssistantConversations,
  listAssistantProviders,
} from '$lib/api/client';
import type { AssistantConversation, AssistantProvider } from '$lib/api/types';
import { answeringProvider } from '$lib/settings/assistant';
import { session } from '$lib/state/session.svelte';
import { Conversation } from './conversation.svelte';

class Eli {
  readonly conversation = new Conversation();
  providers = $state<readonly AssistantProvider[]>([]);
  open = $state(false);
  pending = $state<EliContext[]>([]);
  /** Whether the panel shows the kept conversations instead of the thread. */
  history = $state(false);
  conversations = $state<AssistantConversation[]>([]);
  historyError = $state('');
  returnFocus: HTMLElement | null = null;
  #revision = 0;

  /**
   * The provider that answers this person: the default, if it is enabled and they
   * may use it, and otherwise the first they may. Somebody else's own subscription
   * is never one.
   */
  get answering(): AssistantProvider | undefined {
    return answeringProvider(this.providers);
  }

  /** Whether the widget is shown at all. */
  get available(): boolean {
    return session.phase === 'ready' && session.can('viewer');
  }

  /** Whether Eli can read the fleet through the provider that answers. */
  get fleetAccess(): boolean {
    return this.answering?.fleet_access === true;
  }

  /** Ask the controller which providers there are. Quiet when it cannot say. */
  async refresh(): Promise<void> {
    const revision = ++this.#revision;
    if (session.phase !== 'ready' || !session.can('viewer')) {
      this.providers = [];
      this.open = false;
      return;
    }
    try {
      const result = await listAssistantProviders();
      if (revision !== this.#revision) return;
      this.providers = result.items ?? [];
    } catch {
      // The widget is an extra: a page that cannot say whether there is a model
      // simply does not offer one, and the Settings page says what is wrong.
      if (revision !== this.#revision) return;
      this.providers = [];
    }
  }

  /** Use the providers a page has just read, without asking again. */
  know(providers: readonly AssistantProvider[]): void {
    this.#revision++;
    this.providers = providers;
  }

  show(): void {
    if (this.available) this.open = true;
  }

  hide(): void {
    this.close();
  }

  toggle(): void {
    if (this.open) this.hide();
    else this.show();
  }

  /**
   * Start a fresh conversation about what the operator is looking at. An answer
   * about one problem carried into the next would be read against the wrong
   * context, so an earlier thread, and any reply still streaming into it, is
   * dropped first.
   */
  ask(context: EliContext): void {
    this.returnFocus =
      document.activeElement instanceof HTMLElement ? document.activeElement : null;
    this.newConversation();
    this.pending.push(structuredClone($state.snapshot(context)));
    this.open = true;
  }
  close(): void {
    this.open = false;
    const previous = this.returnFocus;
    void tick().then(() =>
      requestAnimationFrame(() => {
        if (this.open) return;
        const target = previous?.isConnected
          ? previous
          : document.querySelector<HTMLButtonElement>('[aria-controls="eli-widget"]');
        target?.focus();
      }),
    );
  }
  /** Show the kept conversations, freshly listed. */
  async openHistory(): Promise<void> {
    this.history = true;
    this.historyError = '';
    try {
      this.conversations = (await listAssistantConversations()).items;
    } catch {
      this.historyError = 'The kept conversations could not be read.';
    }
  }

  closeHistory(): void {
    this.history = false;
  }

  /** Pick a kept conversation up where it was left, in place of the thread. */
  async resume(id: string): Promise<void> {
    try {
      const kept = await getAssistantConversation(id);
      this.pending = [];
      this.conversation.load(kept.id, kept.messages ?? []);
      this.history = false;
    } catch {
      this.historyError = 'That conversation could not be read; it may have expired.';
    }
  }

  async remove(id: string): Promise<void> {
    try {
      await deleteAssistantConversation(id);
      this.conversations = this.conversations.filter((c) => c.id !== id);
      if (this.conversation.id === id) this.conversation.clear();
    } catch {
      this.historyError = 'That conversation could not be deleted.';
    }
  }

  newConversation(): void {
    this.history = false;
    this.conversation.clear();
    this.pending = [];
  }

  /** Forget everything: somebody else may sign in on this tab. */
  reset(): void {
    this.#revision++;
    this.conversation.clear();
    this.providers = [];
    this.pending = [];
    this.open = false;
  }
}

export const eli = new Eli();

/**
 * The pure half of keeping a conversation: what of a thread is kept, and how
 * a kept one becomes a thread again. Kept out of the class so a test can hold
 * it without a browser.
 */

import type { Turn } from './conversation.svelte';

export interface StoredMessage {
  role: 'user' | 'assistant';
  content: string;
}

/**
 * What the model is told was said: the words, in order, without an answer that
 * failed and without a question the controller refused. A question whose answer
 * failed is still a question, and is kept. A refused one was never answered and
 * cannot be: left in, every later question would carry it and be refused the
 * same way, and the person could only start again.
 */
export function historyFor(turns: readonly Turn[]): StoredMessage[] {
  return turns
    .filter((t) => t.content && !t.error && !t.refused)
    .map((t) => ({ role: t.role, content: t.content }));
}

/**
 * What is kept of a thread: the same words, without the one still streaming. It
 * is what the page sends the model as history, so a kept conversation resumes
 * as it was being read.
 */
export function transcript(turns: readonly Turn[]): StoredMessage[] {
  return historyFor(turns.filter((t) => !t.streaming));
}

/**
 * A kept conversation as a thread again. What the answer was built from (its
 * looks, its provider, its follow-ups) was not kept, so a resumed answer is the
 * words alone, which is what somebody re-reading it wants.
 */
export function turnsFrom(messages: readonly StoredMessage[], firstId: number): Turn[] {
  return messages.map((m, i) => ({ id: firstId + i, role: m.role, content: m.content }));
}

/**
 * What one chat request may carry, and what to do when a message is over it.
 *
 * The controller holds the real limits (internal/controller/assistant_chat.go)
 * and refuses what is over them. They are repeated here only so the page can
 * say so before the person presses Send, instead of after a round trip that
 * could only fail the same way. The controller stays the authority: a refusal
 * it still sends, because a build disagrees with this page, is handled as a
 * refusal, not as a bug.
 *
 * Everything here is pure, so a test can hold it without a browser.
 */

export const MESSAGE_LIMIT_BYTES = 8 << 10;

const encoder = new TextEncoder();
const decoder = new TextDecoder('utf-8');

const NEWLINE = 0x0a;
/** A UTF-8 continuation byte: the second to fourth byte of a character. */
const isContinuation = (byte: number | undefined): boolean => ((byte ?? 0) & 0xc0) === 0x80;

/**
 * The size the controller counts: the UTF-8 bytes of the trimmed text. Counting
 * characters would let a paste of accented text through the page to be refused
 * by the server, which is the surprise this exists to remove.
 */
export function messageBytes(text: string): number {
  return encoder.encode(text.trim()).length;
}

/** A size as the controller says it, to one decimal: 14541 bytes is "14.2 KiB". */
export function formatKiB(bytes: number): string {
  return `${(bytes / 1024).toFixed(1)} KiB`;
}

export interface Trimmed {
  text: string;
  /** How many bytes were taken off, for the person to be told. */
  cut: number;
}

function result(whole: Uint8Array, kept: string): Trimmed {
  return { text: kept, cut: whole.length - encoder.encode(kept).length };
}

/**
 * The newest part of a message that fits: what a log's failure is, since it is
 * at the end. It starts on a whole line, because a first line cut through its
 * middle reads as garbage, and never splits a character. A message that
 * already fits comes back as it was (trimmed), with nothing cut.
 */
export function keepEnd(text: string, limit: number = MESSAGE_LIMIT_BYTES): Trimmed {
  const whole = encoder.encode(text.trim());
  if (whole.length <= limit) return result(whole, decoder.decode(whole));
  let start = whole.length - limit;
  while (start < whole.length && isContinuation(whole[start])) start++;
  let kept = decoder.decode(whole.subarray(start));
  // Cut mid-line unless the window happens to begin right after a line break.
  if (whole[start - 1] !== NEWLINE) {
    const at = kept.indexOf('\n');
    const rest = at >= 0 ? kept.slice(at + 1).trim() : '';
    // One huge line has no boundary to cut at: keep the window as it is.
    if (rest) kept = rest;
  }
  return result(whole, kept.trim());
}

/**
 * The oldest part of a message that fits, ending on a whole line, for text whose
 * beginning is what matters (a configuration, a stack trace's cause).
 */
export function keepStart(text: string, limit: number = MESSAGE_LIMIT_BYTES): Trimmed {
  const whole = encoder.encode(text.trim());
  if (whole.length <= limit) return result(whole, decoder.decode(whole));
  let end = limit;
  while (end > 0 && isContinuation(whole[end])) end--;
  let kept = decoder.decode(whole.subarray(0, end));
  if (whole[end] !== NEWLINE) {
    const at = kept.lastIndexOf('\n');
    const rest = at > 0 ? kept.slice(0, at).trim() : '';
    if (rest) kept = rest;
  }
  return result(whole, kept.trim());
}

/**
 * Whether a status is the controller saying "not as asked" rather than "not
 * now". Asking again with the same words cannot change a 422, a 409 or a 403,
 * so those are refusals; a rate limit, a timeout, a sign-in that lapsed and a
 * controller that is down are cured by asking again, and keep Try again.
 */
export function isRefusal(status: number): boolean {
  return status >= 400 && status < 500 && status !== 401 && status !== 408 && status !== 429;
}

export type RefusalKind = 'newest' | 'earlier' | 'conversation' | 'other';

/**
 * Which part of the request a 422 faulted. The controller names it (`messages`
 * for the thread as a whole, `messages[2]` for one message); `sent` is how many
 * messages the page sent, so the newest is the last index. The newest is the one
 * the person can cut. An older one is out of their reach, and so is a thread
 * that is too long: both are cured by a new conversation.
 */
export function refusalKind(error: { status: number; field?: string }, sent: number): RefusalKind {
  if (error.status !== 422) return 'other';
  if (error.field === 'messages') return 'conversation';
  const match = /^messages\[(\d+)\]$/.exec(error.field ?? '');
  if (!match) return 'other';
  return Number(match[1]) === sent - 1 ? 'newest' : 'earlier';
}

/**
 * The Markdown a model writes, as a tree the page draws itself.
 *
 * What a model writes is not markup the page should trust, so nothing here
 * produces HTML: it returns a small tree of plain data, and the component that
 * draws it makes an element for each node and puts every string in as text. A
 * thing this does not understand stays on the page as the characters it was
 * written with, which is also what a half-finished answer looks like while it is
 * still being streamed (an unclosed `**` or fence is text until it closes).
 *
 * The subset is what models actually write in an answer: paragraphs, headings,
 * lists (one level inside another), quotes, fenced code, tables, rules, and
 * inline bold, italic, code and links. A link is kept only if it is http or
 * https; `javascript:`, `data:` and the rest are left as their words.
 */

export type Inline =
  | { t: 'text'; v: string }
  | { t: 'br' }
  | { t: 'strong'; c: Inline[] }
  | { t: 'em'; c: Inline[] }
  | { t: 'code'; v: string }
  | { t: 'a'; href: string; c: Inline[] };

export type Align = 'left' | 'center' | 'right' | undefined;

export type Block =
  | { t: 'p'; c: Inline[] }
  | { t: 'h'; level: 1 | 2 | 3; c: Inline[] }
  | { t: 'code'; lang: string; v: string }
  | { t: 'list'; ordered: boolean; start: number; items: Block[][] }
  | { t: 'quote'; c: Block[] }
  | { t: 'hr' }
  | { t: 'table'; head: Inline[][]; align: Align[]; rows: Inline[][][] };

/** How deep quotes and lists may nest. A hostile answer cannot grow the tree without limit. */
const MAX_DEPTH = 4;

const FENCE = /^ {0,3}(`{3,}|~{3,})\s*([\w+#.-]*)[^`]*$/;
const HEADING = /^ {0,3}(#{1,6})\s+(.*?)\s*#*\s*$/;
const RULE = /^ {0,3}([-*_])(?:\s*\1){2,}\s*$/;
const QUOTE = /^ {0,3}>\s?(.*)$/;
const BULLET = /^( *)([-*+])\s+(.*)$/;
const NUMBERED = /^( *)(\d{1,9})[.)]\s+(.*)$/;
const TABLE_SEPARATOR = /^\s*\|?\s*:?-{1,}:?\s*(\|\s*:?-{1,}:?\s*)*\|?\s*$/;

export function parseMarkdown(source: string): Block[] {
  return blocks(source.replace(/\r\n?/g, '\n').split('\n'), 0);
}

function blocks(lines: string[], depth: number): Block[] {
  const out: Block[] = [];
  let i = 0;
  while (i < lines.length) {
    const line = lines[i]!;
    if (line.trim() === '') {
      i++;
      continue;
    }

    const fence = FENCE.exec(line);
    if (fence) {
      // A fence with no closing line runs to the end: that is what an answer
      // looks like while its code is still arriving, and it is code, not prose.
      const mark = fence[1]!;
      const body: string[] = [];
      i++;
      while (i < lines.length && !closes(lines[i]!, mark)) body.push(lines[i++]!);
      i++;
      out.push({ t: 'code', lang: fence[2] ?? '', v: body.join('\n') });
      continue;
    }

    const heading = HEADING.exec(line);
    if (heading) {
      // A model's "# Title" is not the page's outline: all six levels draw as
      // three small ones, below the page's own headings.
      const level = Math.min(heading[1]!.length, 3) as 1 | 2 | 3;
      out.push({ t: 'h', level, c: inlines(heading[2]!) });
      i++;
      continue;
    }

    if (RULE.test(line)) {
      out.push({ t: 'hr' });
      i++;
      continue;
    }

    if (QUOTE.test(line)) {
      const inner: string[] = [];
      while (i < lines.length && QUOTE.test(lines[i]!)) inner.push(QUOTE.exec(lines[i++]!)![1]!);
      out.push({ t: 'quote', c: depth < MAX_DEPTH ? blocks(inner, depth + 1) : plain(inner) });
      continue;
    }

    if (isTable(lines, i)) {
      const head = cells(lines[i]!);
      const align = cells(lines[i + 1]!).map(alignment);
      i += 2;
      const rows: Inline[][][] = [];
      while (i < lines.length && lines[i]!.trim() !== '' && lines[i]!.includes('|')) {
        rows.push(
          Array.from({ length: head.length }, (_, k) => inlines(cells(lines[i]!)[k] ?? '')),
        );
        i++;
      }
      out.push({ t: 'table', head: head.map(inlines), align, rows });
      continue;
    }

    if (BULLET.test(line) || NUMBERED.test(line)) {
      const taken = takeList(lines, i);
      i = taken.next;
      out.push(list(taken.lines, depth));
      continue;
    }

    // A paragraph runs until a blank line or the start of another block.
    const text: string[] = [];
    while (
      i < lines.length &&
      lines[i]!.trim() !== '' &&
      (text.length === 0 || !startsBlock(lines, i))
    ) {
      text.push(lines[i++]!);
    }
    out.push({ t: 'p', c: inlines(text.join('\n')) });
  }
  return out;
}

function closes(line: string, mark: string): boolean {
  const t = line.trim();
  return t.length >= mark.length && t[0] === mark[0] && /^(`+|~+)$/.test(t);
}

function startsBlock(lines: string[], i: number): boolean {
  const line = lines[i]!;
  return (
    FENCE.test(line) ||
    HEADING.test(line) ||
    RULE.test(line) ||
    QUOTE.test(line) ||
    BULLET.test(line) ||
    NUMBERED.test(line) ||
    isTable(lines, i)
  );
}

function plain(lines: string[]): Block[] {
  return [{ t: 'p', c: [{ t: 'text', v: lines.join('\n') }] }];
}

/**
 * The lines of one list: items of its own kind, their indented continuations, and
 * nothing after a blank line followed by anything else. A list of the other kind
 * is a new list, so numbers that follow bullets are not swallowed by the last one.
 */
function takeList(lines: string[], from: number): { lines: string[]; next: number } {
  const ordered = NUMBERED.test(lines[from]!);
  const item = (line: string): boolean => (ordered ? NUMBERED : BULLET).test(line);
  const continued = (line: string): boolean => /^ {2,}\S/.test(line);
  const taken: string[] = [];
  let i = from;
  while (i < lines.length) {
    const line = lines[i]!;
    if (line.trim() === '') {
      // A blank line stays in the list only when another of its items follows.
      const after = lines[i + 1];
      if (after !== undefined && (item(after) || continued(after))) {
        i++;
        continue;
      }
      break;
    }
    if (!item(line) && !continued(line)) break;
    taken.push(line);
    i++;
  }
  return { lines: taken, next: i };
}

function list(lines: string[], depth: number): Block {
  const first = lines[0]!;
  const numbered = NUMBERED.exec(first);
  const ordered = numbered !== null;
  const base = (numbered ?? BULLET.exec(first))![1]!.length;
  const start = numbered ? Number(numbered[2]) : 1;
  const items: string[][] = [];
  for (const line of lines) {
    const marker = (ordered ? NUMBERED : BULLET).exec(line);
    if (marker && marker[1]!.length <= base + 1) {
      items.push([marker[3]!]);
    } else if (items.length > 0) {
      // Deeper lines belong to the item above: a nested list or a continued sentence.
      items[items.length - 1]!.push(line.replace(new RegExp(`^ {0,${base + 2}}`), ''));
    }
  }
  return {
    t: 'list',
    ordered,
    start,
    items: items.map((item) => (depth < MAX_DEPTH ? blocks(item, depth + 1) : plain(item))),
  };
}

function isTable(lines: string[], i: number): boolean {
  const head = lines[i];
  const rule = lines[i + 1];
  if (head === undefined || rule === undefined) return false;
  if (!head.includes('|') || !rule.includes('-') || !TABLE_SEPARATOR.test(rule)) return false;
  return cells(head).length === cells(rule).length && cells(head).length > 0;
}

function cells(line: string): string[] {
  let t = line.trim();
  if (t.startsWith('|')) t = t.slice(1);
  if (t.endsWith('|') && !t.endsWith('\\|')) t = t.slice(0, -1);
  const out: string[] = [];
  let cur = '';
  for (let i = 0; i < t.length; i++) {
    if (t[i] === '\\' && t[i + 1] === '|') {
      cur += '|';
      i++;
    } else if (t[i] === '|') {
      out.push(cur.trim());
      cur = '';
    } else cur += t[i];
  }
  out.push(cur.trim());
  return out;
}

function alignment(cell: string): Align {
  const left = cell.startsWith(':');
  const right = cell.endsWith(':');
  if (left && right) return 'center';
  if (right) return 'right';
  if (left) return 'left';
  return undefined;
}

// ---------------------------------------------------------------------------

/** Only a web address is a link. Anything else, including a scheme in disguise, is not. */
export function safeHref(raw: string): string | undefined {
  const text = raw.trim();
  // Control characters and whitespace inside a URL are how a scheme is hidden.
  for (const ch of text) {
    const n = ch.charCodeAt(0);
    if (n <= 0x20 || (n >= 0x7f && n <= 0x9f)) return undefined;
  }
  try {
    const url = new URL(text);
    return url.protocol === 'http:' || url.protocol === 'https:' ? url.href : undefined;
  } catch {
    return undefined;
  }
}

const SPECIAL = /[`*_[\\\n]|https?:\/\//;

export function inlines(source: string, depth = 0): Inline[] {
  const out: Inline[] = [];
  let text = '';
  const flush = (): void => {
    if (text) out.push({ t: 'text', v: text });
    text = '';
  };
  let i = 0;
  while (i < source.length) {
    const rest = source.slice(i);
    const ch = source[i]!;

    if (ch === '\\' && i + 1 < source.length && /[\\`*_{}[\]()#+\-.!|>~]/.test(source[i + 1]!)) {
      text += source[i + 1];
      i += 2;
      continue;
    }

    if (ch === '\n') {
      flush();
      out.push({ t: 'br' });
      i++;
      continue;
    }

    if (ch === '`') {
      const run = /^`+/.exec(rest)![0];
      const end = source.indexOf(run, i + run.length);
      if (end !== -1) {
        flush();
        out.push({ t: 'code', v: source.slice(i + run.length, end).replace(/^ (.*) $/s, '$1') });
        i = end + run.length;
        continue;
      }
      text += run;
      i += run.length;
      continue;
    }

    if ((ch === '*' || ch === '_') && depth < MAX_DEPTH) {
      const double = source.startsWith(ch + ch, i);
      const mark = double ? ch + ch : ch;
      const close = closer(source, i, mark);
      if (close !== -1) {
        flush();
        const inner = inlines(source.slice(i + mark.length, close), depth + 1);
        out.push(double ? { t: 'strong', c: inner } : { t: 'em', c: inner });
        i = close + mark.length;
        continue;
      }
      text += mark;
      i += mark.length;
      continue;
    }

    if (ch === '[' && depth < MAX_DEPTH) {
      const link = /^\[([^\]\n]*)\]\(\s*<?([^\s)>]+)>?(?:\s+"[^"]*")?\s*\)/.exec(rest);
      const href = link ? safeHref(link[2]!) : undefined;
      if (link && href) {
        flush();
        out.push({ t: 'a', href, c: inlines(link[1]!, depth + 1) });
        i += link[0].length;
        continue;
      }
      text += ch;
      i++;
      continue;
    }

    const bare = /^https?:\/\/[^\s<>()[\]]+/.exec(rest);
    if (bare && (i === 0 || /[\s(]/.test(source[i - 1]!))) {
      // Sentence punctuation after an address is the sentence's, not the address's.
      const url = bare[0].replace(/[.,;:!?'"]+$/, '');
      const href = safeHref(url);
      if (href) {
        flush();
        out.push({ t: 'a', href, c: [{ t: 'text', v: url }] });
        i += url.length;
        continue;
      }
    }

    // Everything up to the next character that can start something is plain text.
    const next = rest.slice(1).search(SPECIAL);
    const run = next === -1 ? rest : rest.slice(0, next + 1);
    text += run;
    i += run.length;
  }
  flush();
  return out;
}

/**
 * Where an emphasis mark opened at `open` closes, or -1. The mark must hug its
 * text (no space just inside), an underscore must not sit inside a word (so
 * `snake_case_name` is a name and not italics), and the first mark that could
 * close it wins.
 */
function closer(source: string, open: number, mark: string): number {
  const ch = mark[0]!;
  const after = source[open + mark.length];
  if (after === undefined || /\s/.test(after)) return -1;
  if (ch === '_' && open > 0 && /\w/.test(source[open - 1]!)) return -1;
  for (let j = open + mark.length; j < source.length; j++) {
    if (source[j] === '`') {
      // Code inside emphasis keeps its own marks.
      const end = source.indexOf('`', j + 1);
      if (end === -1) return -1;
      j = end;
      continue;
    }
    if (source[j] === '\\') {
      j++;
      continue;
    }
    if (!source.startsWith(mark, j)) continue;
    const before = source[j - 1]!;
    if (/\s/.test(before) && j > open + mark.length) continue;
    if (j === open + mark.length) continue;
    if (mark.length === 1 && source[j + 1] === ch) {
      // A single mark does not close on half of a double one.
      j++;
      continue;
    }
    if (ch === '_' && /\w/.test(source[j + mark.length] ?? '')) continue;
    return j;
  }
  return -1;
}

/** Clamp the panel after dragging, resizing or a viewport change. */
export function movable(node: HTMLElement, enabled: boolean) {
  let position: { x: number; y: number } | undefined;
  let drag: { id: number; x: number; y: number } | undefined;
  function place(x: number, y: number) {
    const rect = node.getBoundingClientRect();
    position = {
      x: Math.max(0, Math.min(x, document.documentElement.clientWidth - rect.width)),
      y: Math.max(0, Math.min(y, window.innerHeight - rect.height)),
    };
    Object.assign(node.style, {
      left: position.x + 'px',
      top: position.y + 'px',
      right: 'auto',
      bottom: 'auto',
    });
  }
  function clamp() {
    if (enabled && position) place(position.x, position.y);
  }
  function down(event: PointerEvent) {
    if (!enabled || event.button !== 0 || !(event.target instanceof Element)) return;
    // The whole drag area grabs, not only the handle, so the panel moves from
    // any empty stretch of its header. A control inside that area keeps its
    // click: grabbing there would capture the pointer and swallow it.
    const control = event.target.closest('button, a, input, select, textarea, [role="button"]');
    if (
      control ? !control.matches('[data-drag-handle]') : !event.target.closest('[data-drag-area]')
    )
      return;
    const rect = node.getBoundingClientRect();
    drag = { id: event.pointerId, x: event.clientX - rect.left, y: event.clientY - rect.top };
    node.setPointerCapture(event.pointerId);
    event.preventDefault();
    node.querySelector<HTMLElement>('[data-drag-handle]')?.focus();
  }
  function move(event: PointerEvent) {
    if (drag?.id === event.pointerId) place(event.clientX - drag.x, event.clientY - drag.y);
  }
  function stop() {
    drag = undefined;
  }
  function key(event: KeyboardEvent) {
    if (
      !enabled ||
      !(event.target instanceof Element) ||
      !event.target.closest('[data-drag-handle]')
    )
      return;
    const directions: Record<string, [number, number]> = {
      ArrowLeft: [-1, 0],
      ArrowRight: [1, 0],
      ArrowUp: [0, -1],
      ArrowDown: [0, 1],
    };
    const direction = directions[event.key];
    if (!direction) return;
    event.preventDefault();
    const rect = node.getBoundingClientRect();
    const step = event.shiftKey ? 40 : 10;
    place(rect.left + direction[0] * step, rect.top + direction[1] * step);
  }
  function reset() {
    stop();
    position = undefined;
    for (const property of ['left', 'top', 'right', 'bottom']) node.style.removeProperty(property);
  }
  const observer = new ResizeObserver(clamp);
  observer.observe(node);
  window.addEventListener('resize', clamp);
  node.addEventListener('pointerdown', down);
  node.addEventListener('pointermove', move);
  node.addEventListener('pointerup', stop);
  node.addEventListener('pointercancel', stop);
  node.addEventListener('lostpointercapture', stop);
  node.addEventListener('keydown', key);
  node.addEventListener('eli-place', reset);
  return {
    update(value: boolean) {
      if (value !== enabled) {
        enabled = value;
        reset();
      }
    },
    destroy() {
      observer.disconnect();
      window.removeEventListener('resize', clamp);
      node.removeEventListener('pointerdown', down);
      node.removeEventListener('pointermove', move);
      node.removeEventListener('pointerup', stop);
      node.removeEventListener('pointercancel', stop);
      node.removeEventListener('lostpointercapture', stop);
      node.removeEventListener('keydown', key);
      node.removeEventListener('eli-place', reset);
    },
  };
}

/** Explicit display facts only: callers must never pass credentials or whole API objects. */
export interface EliContext {
  kind: string;
  title: string;
  facts: Record<string, string | number | boolean | null | undefined>;
  question?: string;
  /** A bounded, manually collected diagnostic should not collect itself again. */
  snapshotOnly?: boolean;
}

export interface Suggestion {
  label: string;
  prompt: string;
}

export function contextPrompt(context: EliContext): string {
  const facts = Object.entries(context.facts)
    .filter(([, value]) => value !== undefined && value !== null && value !== '')
    .map(([key, value]) => `${key}: ${value}`)
    .join('\n');
  const currentness = context.snapshotOnly
    ? 'Explain this recorded snapshot; a fresh diagnostic requires a new explicit request.'
    : 'If you have tools, use them to check the current state before you rely on the snapshot.';
  return `${context.question ?? 'What is going on here, and what should I check or do first?'}\n\nContext shared from the ${context.kind} UI: ${context.title}\n${facts}\n\nThese facts are a snapshot of what the page showed when I asked, not the fleet now. ${currentness} Ask for missing evidence and distinguish facts from possible causes.`;
}

const OPEN = '<follow-ups>';
const CLOSE = '</follow-ups>';
const MAX_SUGGESTIONS = 3;

/**
 * Split an answer into what the person reads and the next questions the model
 * proposed. The controller asks the model to end every answer with a
 * `<follow-ups>` block, one question per line, so the suggestions are about this
 * conversation and not a fixed list.
 *
 * It is safe to call on a half-written answer: the block, and any prefix of its
 * opening tag at the very end, is withheld so the tag never flashes on screen as
 * it streams. A block that never closes (the model ran out of room) yields no
 * suggestions rather than a cut-off question.
 */
export function splitFollowUps(raw: string): { text: string; suggestions: Suggestion[] } {
  const start = raw.indexOf(OPEN);
  if (start < 0) {
    for (let n = Math.min(OPEN.length - 1, raw.length); n > 0; n--) {
      if (raw.endsWith(OPEN.slice(0, n)))
        return { text: raw.slice(0, -n).trimEnd(), suggestions: [] };
    }
    return { text: raw, suggestions: [] };
  }
  const text = raw.slice(0, start).trimEnd();
  const end = raw.indexOf(CLOSE, start);
  if (end < 0) return { text, suggestions: [] };
  const seen = new Set<string>();
  const suggestions: Suggestion[] = [];
  for (const line of raw.slice(start + OPEN.length, end).split('\n')) {
    const question = line.replace(/^\s*(?:[-*]|\d+[.)])\s*/, '').trim();
    if (!question || question.length > 200 || seen.has(question)) continue;
    seen.add(question);
    suggestions.push({ label: question, prompt: question });
    if (suggestions.length === MAX_SUGGESTIONS) break;
  }
  return { text, suggestions };
}

/**
 * What the controller hid from the model before it answered, said to the person.
 * Only counts come from the controller: what was hidden is never sent back.
 */
export function hiddenNote(credentials: number, emails: number): string {
  const parts: string[] = [];
  if (credentials > 0)
    parts.push(`${credentials} ${credentials === 1 ? 'credential' : 'credentials'}`);
  if (emails > 0) parts.push(`${emails} ${emails === 1 ? 'email address' : 'email addresses'}`);
  if (parts.length === 0) return '';
  return `${parts.join(' and ')} ${credentials + emails === 1 ? 'was' : 'were'} hidden before this went to the model.`;
}

/**
 * Keeps Eli's phone sheet inside the part of the screen an operator can see.
 *
 * A phone's keyboard does not shrink the layout viewport, only the visual
 * one, and `position: fixed` is laid out against the first. A sheet anchored
 * to the bottom edge and as tall as `100dvh` therefore keeps its full height
 * under the keyboard, the browser scrolls the visual viewport down to show the
 * message box, and the head of the sheet (Eli's name, New conversation, the
 * way to close it) goes off the top of the screen with nothing to bring it
 * back short of putting the keyboard away.
 *
 * So the sheet follows the visual viewport instead: it starts where that
 * starts and is as tall as that is, written as two custom properties the
 * phone's CSS reads. With the keyboard down the two agree with `100dvh` and
 * nothing changes; with it up the sheet is shortened to the space above the
 * keyboard, and its header stays where it was.
 */

/** The part of `VisualViewport` this needs, so a test can supply its own. */
export interface ViewportLike {
  offsetTop: number;
  height: number;
  addEventListener(type: 'resize' | 'scroll', listener: () => void): void;
  removeEventListener(type: 'resize' | 'scroll', listener: () => void): void;
}

/** The part of an element this writes to. */
export interface SheetLike {
  style: {
    setProperty(name: string, value: string): void;
    removeProperty(name: string): void;
  };
}

const TOP = '--z-eli-sheet-top';
const HEIGHT = '--z-eli-sheet-height';

/**
 * Sizes `sheet` to `viewport` now and whenever it moves, until the returned
 * function is called; that clears both properties so the CSS is back in
 * charge. A browser with no visual viewport (`null`) is left to the CSS from
 * the start.
 */
export function followViewport(sheet: SheetLike, viewport: ViewportLike | null | undefined) {
  if (!viewport) return () => {};
  const follow = () => {
    // Whole pixels: a sheet half a pixel short of the viewport shows a seam
    // of the page it is drawn over.
    sheet.style.setProperty(TOP, `${Math.round(viewport.offsetTop)}px`);
    sheet.style.setProperty(HEIGHT, `${Math.round(viewport.height)}px`);
  };
  follow();
  viewport.addEventListener('resize', follow);
  viewport.addEventListener('scroll', follow);
  return () => {
    viewport.removeEventListener('resize', follow);
    viewport.removeEventListener('scroll', follow);
    sheet.style.removeProperty(TOP);
    sheet.style.removeProperty(HEIGHT);
  };
}

/**
 * The questions the empty conversation offers. Without the fleet to look at
 * they are about Zoomies in general. With it, the first is always the open
 * one, so the entry point is the same every time, and the rest are about what
 * the fleet is doing now: with a problem open, what changed lately, and then
 * the worst open problem by name, the jobs waiting, the jobs that failed, the
 * host that is unwell. A fixed list of four read the same on a quiet fleet and
 * a burning one; these read differently, which is what makes one worth
 * pressing.
 */

export const GENERAL_STARTERS = [
  'How do labels decide which pool runs a job?',
  'Why might a job sit queued?',
  'How do ephemeral runners work?',
  'What should I check when a host goes unhealthy?',
] as const;

export const FLEET_STARTERS = [
  'How is the fleet doing right now?',
  'Is anything wrong that I should look at?',
  'Which jobs are queued, and why?',
  'How busy are the pools?',
] as const;

/**
 * Asked second whenever a problem is open. A problem is usually the end of
 * something that happened, and Eli can read what the fleet did lately, so
 * the question that finds the start of it comes before the one about the end.
 */
export const CHANGED_STARTER = 'What changed in the last ten minutes?';

/** How many the panel shows: a glance, not a menu. */
const COUNT = 4;

export interface StarterInput {
  fleetAccess: boolean;
  stats: {
    window?: string;
    queued_jobs?: number;
    failed?: number;
    fleet_failed?: number;
  } | null;
  problems: readonly { code: string; severity: string; title: string }[];
  hosts: readonly { name?: string; healthy?: boolean }[];
}

const RANK: Record<string, number> = { error: 0, warning: 1, info: 2 };

export function starterQuestions(input: StarterInput): string[] {
  if (!input.fleetAccess) return [...GENERAL_STARTERS];
  const out: string[] = [FLEET_STARTERS[0]];
  const add = (q: string | undefined) => {
    if (q && !out.includes(q) && out.length < COUNT) out.push(q);
  };
  if (input.problems.length > 0) add(CHANGED_STARTER);
  // The problems, worst first; the drawer's own order is by time, which is
  // not what decides where to look first.
  const problems = [...input.problems].sort(
    (a, b) => (RANK[a.severity] ?? 3) - (RANK[b.severity] ?? 3),
  );
  const [worst, next] = problems;
  if (worst) add(`Explain "${worst.title}" and what to do about it.`);
  const queued = input.stats?.queued_jobs ?? 0;
  if (queued > 0) add(`Why ${queued === 1 ? 'is 1 job' : `are ${queued} jobs`} queued right now?`);
  const failed = input.stats?.failed ?? 0;
  if (failed > 0) {
    const window = windowWords(input.stats?.window);
    add(
      `Why did ${failed === 1 ? '1 job' : `${failed} jobs`} fail ${window}, and was the fleet at fault for any?`,
    );
  }
  const sick = input.hosts.find((h) => h.healthy === false && h.name);
  if (sick) add(`What is wrong with host ${sick.name}?`);
  if (next && next.title !== worst?.title) add(`Explain "${next.title}" and what to do about it.`);
  for (const q of FLEET_STARTERS) {
    // "Is anything wrong?" is answered by the problem already named above it.
    if (worst && q === FLEET_STARTERS[1]) continue;
    add(q);
  }
  return out;
}

/** "in the last hour" for "1h", "in the last 24 hours" for "24h", and so on. */
function windowWords(window: string | undefined): string {
  const m = /^(\d+)([hdm])$/.exec(window ?? '');
  if (!m) return 'recently';
  const n = Number(m[1]);
  const unit = { h: 'hour', d: 'day', m: 'minute' }[m[2] as 'h' | 'd' | 'm'];
  return n === 1 ? `in the last ${unit}` : `in the last ${n} ${unit}s`;
}

/**
 * Whether a band draws its dog, and how large it is when it does.
 *
 * The dog's size is separate from the band's cut: the cut is about air and
 * type, the dog's size is about the brand. `auto` follows the cut, so a slim
 * band draws a smaller dog than an expanded one; the three named sizes pin it
 * whichever cut the band takes, because an operator who wants the numbers up
 * front may still want the brand large beside them.
 */

export const BAND_LOGO_SIZES = ['auto', 'small', 'medium', 'large'] as const;
export type BandLogoSize = (typeof BAND_LOGO_SIZES)[number];

export const DEFAULT_BAND_LOGO_SIZE: BandLogoSize = 'auto';

export const BAND_LOGO_SIZE_OPTIONS = [
  { value: 'auto', label: 'Auto', name: 'Follows the band size' },
  { value: 'small', label: 'Small', name: 'A smaller dog' },
  { value: 'medium', label: 'Medium', name: 'The middle dog' },
  { value: 'large', label: 'Large', name: 'A larger dog' },
] as const;

export function isBandLogoSize(value: unknown): value is BandLogoSize {
  return BAND_LOGO_SIZES.some((size) => size === value);
}

/**
 * The sizes BrandStage actually draws. `auto` is a preference, resolved here to
 * an explicit width by PageBand, so the stage itself only ever hears a size.
 */
export type BandLogoArtSize = Exclude<BandLogoSize, 'auto'>;

/**
 * The figures the Runners band carries: how much work is waiting, how it divides by
 * provisioning status, and how long the oldest has waited.
 *
 * Plain functions, as the sentences beside them are, so each figure can be held to its
 * input by a test. They are the figures the provisioning strip above the runner list
 * used to show, moved into the band to give the rows that height back.
 */
import { formatNumber } from '../format';
import type { BandMore, BandStat } from './stats';

export type DemandStatus = 'ready' | 'expedited' | 'paused' | 'deleted';
const ORDER: readonly DemandStatus[] = ['ready', 'expedited', 'paused', 'deleted'];

export interface DemandInput {
  /** Jobs waiting for a runner; null or undefined while the figure has not arrived. */
  queued: number | null | undefined;
  /** Runners executing a job now; null or undefined while the figure has not arrived. */
  running: number | null | undefined;
  /**
   * What "Running" does when the runners list is on this page. It narrows that
   * list and jumps to it; without it the figure opens the runners list.
   */
  onPageRunning?: {
    section: string;
    onselect: () => void;
    active?: boolean;
  };
  /** The queue is deep enough to be worth the warning colour on a plain panel. */
  queuedWarning: boolean;
  /** Provisioning counts by status; null until the first answer. */
  counts: Readonly<Record<string, number>> | null;
  /** The instant the oldest queued demand arrived, if any. */
  oldest: string | null;
  /** Narrows every link to one pool; empty for the whole fleet. */
  poolId: string;
  /** What each status is called, from the shared map, so every surface says the same. */
  labels: Readonly<Record<DemandStatus, string>>;
}

const poolQuery = (poolId: string) => (poolId ? `&pool_id=${encodeURIComponent(poolId)}` : '');
const queueQuery = (poolId: string) => (poolId ? `?pool_id=${encodeURIComponent(poolId)}` : '');

export function demandStats(input: DemandInput): BandStat[] {
  const stats: BandStat[] = [
    {
      label: input.queued === 1 ? 'Job queued' : 'Jobs queued',
      value: formatNumber(input.queued),
      hint: 'Jobs waiting for a runner. Open the queue.',
      href: `/queue${queueQuery(input.poolId)}#queue-list`,
      tone: input.queuedWarning ? 'warning' : undefined,
    },
    {
      label: 'Running',
      value:
        input.running === null || input.running === undefined
          ? undefined
          : formatNumber(input.running),
      hint: input.onPageRunning
        ? 'Runners executing a job right now. Show them below.'
        : 'Runners executing a job right now. Open them.',
      ...(input.onPageRunning
        ? {
            section: input.onPageRunning.section,
            onselect: input.onPageRunning.onselect,
            active: input.onPageRunning.active,
          }
        : { href: `/runners?state=busy${poolQuery(input.poolId)}#runners-list` }),
    },
  ];
  for (const status of ORDER) {
    stats.push({
      label: input.labels[status],
      // Not zero while the answer is on its way: zero is a claim.
      value: input.counts ? formatNumber(input.counts[status] ?? 0) : undefined,
      hint: `Provisioning demand that is ${input.labels[status].toLowerCase()}. Open it in the queue.`,
      href: `/queue?provisioning=${status}${poolQuery(input.poolId)}#queue-list`,
    });
  }
  if (input.oldest) {
    stats.push({
      label: 'Oldest demand',
      since: input.oldest,
      hint: 'How long the oldest queued demand has been waiting.',
    });
  }
  return stats;
}

export function demandMore(poolId: string): BandMore {
  return {
    label: 'Manage queue',
    href: `/queue${queueQuery(poolId)}#queue-list`,
  };
}

import { tick } from 'svelte';

/**
 * Bring the evidence for a band figure into view, and put the keyboard there.
 *
 * A figure and the list it counts are on one page, so pressing it is a jump
 * and not a navigation. The hash is replaced rather than pushed: a place on
 * the page should not fill the back button, and the page's own filters are
 * already history entries when they mean something.
 */
export function jumpToSection(id: string): void {
  const target = document.getElementById(id);
  if (!target) return;
  const calm = matchMedia('(prefers-reduced-motion: reduce)').matches;
  target.scrollIntoView({ behavior: calm ? 'auto' : 'smooth', block: 'start' });
  if (!target.hasAttribute('tabindex')) target.setAttribute('tabindex', '-1');
  target.focus({ preventScroll: true });
  if (location.hash !== `#${id}`) {
    history.replaceState(history.state, '', `${location.pathname}${location.search}#${id}`);
  }
}

/**
 * A section that a link from another page may name.
 *
 * The route changes before this node exists, so the browser's own fragment
 * jump has nothing to land on. The action waits until the section is mounted,
 * then does what an in-page figure does. It also follows a hash that changes
 * while the page is open, which is how a browser's back button returns to a
 * section on a page it has already shown.
 */
export function revealHash(node: HTMLElement) {
  const reveal = (): void => {
    if (!node.id || location.hash !== `#${node.id}`) return;
    void tick().then(() => jumpToSection(node.id));
  };
  reveal();
  addEventListener('hashchange', reveal);
  return {
    destroy(): void {
      removeEventListener('hashchange', reveal);
    },
  };
}

/**
 * What each page's band says, from the figures the page already has.
 *
 * Plain functions, as the Overview's status line is, so each sentence can be held to
 * its numbers by a test: a band that said "3 hosts are connected" over a count that
 * included one that had stopped sending heartbeats would be wrong in a way a layout
 * change is very good at hiding. The Runners band lives beside these in
 * runners-line.ts.
 */

export interface BandLine {
  headline: string;
  /** The line drawn in the brand's blue; empty when there is nothing to split. */
  accent: string;
  lede: string;
}

const count = (n: number, one: string, many: string) => `${n} ${n === 1 ? one : many}`;
const is = (n: number) => (n === 1 ? 'is' : 'are');

export function poolsLine(p: {
  enabled: number;
  total: number;
  live: number;
  max: number;
  atCeiling: number;
}): BandLine {
  if (p.total === 0) {
    return {
      headline: 'No pools yet.',
      accent: '',
      lede: 'A pool decides what labels your runners answer to.',
    };
  }
  return {
    headline:
      p.enabled === p.total
        ? `${count(p.total, 'pool', 'pools')} ${is(p.total)} enabled.`
        : `${p.enabled} of ${p.total} pools are enabled.`,
    accent: `${p.live} of ${p.max} runners live.`,
    lede:
      p.atCeiling > 0
        ? `${p.atCeiling} ${is(p.atCeiling)} at its ceiling.`
        : 'None is at its ceiling.',
  };
}

export function queueLine(q: {
  queued: number;
  running: number;
  /** The median wait, already worded, or null when there is not one. */
  medianWait: string | null;
}): BandLine {
  if (q.queued === 0) {
    return {
      headline: 'Nothing is waiting.',
      accent: `${q.running} running.`,
      lede: 'Every job has a runner.',
    };
  }
  return {
    headline: `${count(q.queued, 'job', 'jobs')} ${is(q.queued)} waiting for a runner.`,
    accent: `${q.running} running.`,
    lede: q.medianWait ? `The median wait is ${q.medianWait}.` : 'Jobs start oldest first.',
  };
}

export function jobsLine(j: {
  running: number;
  queued: number;
  succeeded: number;
  failed: number;
  /** The window the finished counts cover, as a phrase: "the last hour". */
  windowText: string;
}): BandLine {
  return {
    headline: `${count(j.running, 'job', 'jobs')} ${is(j.running)} running.`,
    accent: `${j.queued} waiting for a runner.`,
    lede: `${j.failed} failed and ${j.succeeded} succeeded in ${j.windowText}.`,
  };
}

export function workflowsLine(w: { running: number; queued: number }): BandLine {
  const inFlight = w.running + w.queued;
  return {
    headline: `${count(inFlight, 'job', 'jobs')} ${is(inFlight)} in flight.`,
    accent: `${w.running} running, ${w.queued} waiting.`,
    lede: 'Open a run to see its jobs.',
  };
}

export function hostsLine(h: {
  connected: number;
  total: number;
  inUse: number;
  capacity: number;
}): BandLine {
  if (h.total === 0) {
    return {
      headline: 'No hosts yet.',
      accent: '',
      lede: 'Add one to give runners somewhere to start.',
    };
  }
  const silent = h.total - h.connected;
  return {
    headline:
      silent === 0
        ? `${count(h.total, 'host', 'hosts')} ${is(h.total)} connected.`
        : `${h.connected} of ${h.total} hosts are connected.`,
    accent: `${h.inUse} of ${h.capacity} slots in use.`,
    lede:
      silent === 0
        ? 'Every host has checked in.'
        : `${silent} ${silent === 1 ? 'has' : 'have'} not checked in.`,
  };
}

export function providersLine(p: {
  providers: number;
  owned: number;
  ceiling: number;
  paused: number;
  review: number;
}): BandLine {
  if (p.providers === 0) {
    return {
      headline: 'No providers yet.',
      accent: '',
      lede: 'A provider rents machines for pools that need them.',
    };
  }
  return {
    headline: `${count(p.owned, 'machine', 'machines')} ${is(p.owned)} owned.`,
    accent: `Up to ${p.ceiling} at once.`,
    lede:
      p.review > 0
        ? `${p.review} ${p.review === 1 ? 'needs' : 'need'} review.`
        : p.paused > 0
          ? `${count(p.paused, 'provider', 'providers')} ${is(p.paused)} paused.`
          : 'Nothing needs review.',
  };
}

export function installationsLine(i: {
  connections: number;
  healthy: number;
  unhealthy: number;
  unchecked: number;
  pools: number;
  lowQuota: number;
}): BandLine {
  if (i.connections === 0) {
    return {
      headline: 'GitHub is not connected.',
      accent: '',
      lede: 'Connect the App before a pool or a runner can exist.',
    };
  }
  return {
    headline: `${count(i.connections, 'connection', 'connections')} to GitHub.`,
    accent:
      i.unhealthy > 0
        ? `${i.unhealthy} not working.`
        : i.unchecked > 0
          ? `${i.unchecked} not checked yet.`
          : 'Every one answered.',
    lede:
      i.lowQuota > 0
        ? `${count(i.lowQuota, 'App is', 'Apps are')} below 10% of the API quota.`
        : i.pools > 0
          ? `${count(i.pools, 'pool depends', 'pools depend')} on them.`
          : 'No pool depends on them yet.',
  };
}

export function repairsLine(r: { offers: number; running: number }): BandLine {
  if (r.offers === 0 && r.running === 0) {
    return {
      headline: 'Nothing needs you.',
      accent: 'No repairs are running.',
      lede: 'Eli is watching for failed PR checks.',
    };
  }
  return {
    headline:
      r.offers > 0
        ? `${count(r.offers, 'offer needs', 'offers need')} review.`
        : 'Nothing needs you.',
    accent: `${count(r.running, 'repair is', 'repairs are')} running.`,
    lede:
      r.offers > 0
        ? 'Failed PR checks on Ask me first repositories.'
        : 'Eli is working through failed checks.',
  };
}

export function migrateLine(): BandLine {
  return {
    headline: 'Move repositories onto this fleet.',
    accent: 'You see every diff first.',
    lede: 'Rewrite runs-on and open a pull request for each repository.',
  };
}

export function kennelLine(k: {
  enabled: boolean;
  repositories: number;
  notTracked: number;
  attention: number;
  clean: number;
  first: { name: string; findings: string; public: boolean } | null;
  more: number;
}): BandLine {
  if (!k.enabled) {
    return {
      headline: 'Kennel Club is off.',
      accent: '',
      lede: 'Turn it on to check the repositories this fleet serves.',
    };
  }
  if (k.repositories === 0) {
    // A repository somebody chose not to track is a decision, not an absence,
    // and the page's own empty state says which of the two this is.
    if (k.notTracked > 0) {
      return {
        headline: 'Every repository is set aside.',
        accent: '',
        lede: 'Kennel Club has been told not to look at them.',
      };
    }
    return {
      headline: 'No repositories to check yet.',
      accent: '',
      lede: 'Kennel Club checks the repositories this fleet has run jobs for.',
    };
  }
  const clean =
    k.clean > 0 ? `${count(k.clean, 'repository', 'repositories')} with nothing open.` : '';
  if (k.attention === 0) {
    return {
      headline: 'No repository needs attention.',
      accent: clean,
      lede: 'No repository has an error or a warning open.',
    };
  }
  return {
    headline: `${count(k.attention, 'repository needs', 'repositories need')} attention.`,
    accent: clean,
    lede: k.first
      ? `${k.first.name} has ${k.first.findings} open.${
          k.first.public
            ? ' It is public, so a pull request from a stranger can reach this fleet.'
            : ''
        }${
          k.more > 0
            ? ` ${count(k.more, 'more repository needs', 'more repositories need')} attention.`
            : ''
        }`
      : 'Open the repositories to see what is wrong.',
  };
}

/** A window as describeWindow words it ("1 hour", "24 hours") as a period: "the last hour". */
export function windowPhrase(window: string): string {
  return window ? `the last ${window.replace(/^1 /, '')}` : 'the reported window';
}

/**
 * The pages that open on a band, in the order Appearance lists them. A page not
 * listed here has no band to switch off.
 */
export const BAND_PAGES = [
  { key: 'overview', label: 'Overview' },
  { key: 'runners', label: 'Runners' },
  { key: 'pools', label: 'Pools' },
  { key: 'queue', label: 'Queue' },
  { key: 'jobs', label: 'Jobs' },
  { key: 'workflows', label: 'Workflows' },
  { key: 'usage', label: 'Usage' },
  { key: 'hosts', label: 'Hosts' },
  { key: 'providers', label: 'Providers' },
  { key: 'installations', label: 'Installations' },
  { key: 'repairs', label: 'Eli repairs' },
  { key: 'migrate', label: 'Migrate' },
  { key: 'kennel', label: 'Kennel Club' },
] as const;

export type BandPage = (typeof BAND_PAGES)[number]['key'];

export function isBandPage(value: unknown): value is BandPage {
  return BAND_PAGES.some((page) => page.key === value);
}

/**
 * How tall a band stands, from the shortest cut to the tallest. The order is the
 * order the choices appear in, so the control reads as a scale rather than a list.
 */
export const BAND_SIZES = [
  { key: 'slim', label: 'Slim', name: 'The shortest cut, for a page with rows to show' },
  { key: 'compact', label: 'Compact', name: 'The working pages cut' },
  { key: 'standard', label: 'Standard', name: 'The Overview cut' },
  { key: 'expanded', label: 'Expanded', name: 'The tallest cut, for a page with room' },
] as const;

export type BandSize = (typeof BAND_SIZES)[number]['key'];

export function isBandSize(value: unknown): value is BandSize {
  return BAND_SIZES.some((size) => size.key === value);
}

/**
 * The size a page's band has until somebody chooses another. The Overview is the
 * front door and keeps its full stage; every page under it is a working page, where
 * the rows are the point, so its band is the compact one.
 */
export function defaultBandSize(page: BandPage): BandSize {
  return page === 'overview' ? 'standard' : 'compact';
}

/**
 * Where a page's band figures are drawn: in the band, on their own, or on their own
 * only where the band is not drawn.
 *
 * A pure function so the rule can be held by a test. The failure it exists to prevent
 * is a quiet one: figures that loaded fine, hidden because the sentence over them had
 * not, which no layout change would ever show.
 */
export type FiguresPlacement =
  /** No figures to place. */
  | 'none'
  /** The band is drawn and carries them; a phone, which hides the band, shows them alone. */
  | 'phone-only'
  /** Always on their own: the band is off, or has no sentence to be drawn with. */
  | 'always';

export function figuresPlacement(input: {
  shown: boolean;
  hasLine: boolean;
  hasStats: boolean;
}): FiguresPlacement {
  if (!input.hasStats) return 'none';
  return input.shown && input.hasLine ? 'phone-only' : 'always';
}

/**
 * What the Runners page's band says: how many runners are live and how they split,
 * in words, from the counts the page already has.
 *
 * A plain function, as the Overview's status line is, so the sentence can be held to
 * the numbers by a test. A band that said "5 runners are live" over a count that
 * left out the ones still starting up would be wrong in a way a layout change is
 * very good at hiding.
 */

export interface RunnerCounts {
  provisioning: number;
  registering: number;
  idle: number;
  busy: number;
  draining: number;
}

export interface RunnersLine {
  headline: string;
  /** The line drawn in the brand's blue; empty when there is nothing to split. */
  accent: string;
  lede: string;
}

const runners = (n: number) => `${n} ${n === 1 ? 'runner' : 'runners'}`;

export function runnersLine(counts: RunnerCounts): RunnersLine {
  const starting = counts.provisioning + counts.registering;
  const live = starting + counts.idle + counts.busy + counts.draining;
  if (live === 0) {
    return {
      headline: 'No runners are live.',
      accent: '',
      lede: 'The next job that needs one will start it.',
    };
  }
  const notes = [
    starting > 0 ? `${starting} ${starting === 1 ? 'is' : 'are'} starting up` : '',
    counts.draining > 0
      ? `${counts.draining} ${counts.draining === 1 ? 'is' : 'are'} draining`
      : '',
  ].filter(Boolean);
  return {
    headline: `${runners(live)} ${live === 1 ? 'is' : 'are'} live.`,
    accent: `${counts.busy} busy, ${counts.idle} idle.`,
    lede: notes.length ? `${notes.join(' and ')}.` : 'Every one is working or ready for work.',
  };
}

/**
 * A figure a band carries, and the shape every page hands it.
 *
 * The values arrive already worded (`"12"`, `"1,204"`, the no-value placeholder), as a
 * band's sentence does: the band lays figures out and never decides what a number
 * means, so a page cannot be made to say something its counts do not.
 */
export interface BandStat {
  label: string;
  /** The figure, already formatted. Ignored when `since` is set. */
  value?: string;
  /** An instant to show as a live age ("4m 10s") instead of a fixed figure. */
  since?: string;
  /** One sentence for the tooltip and the accessible description. */
  hint?: string;
  /** Makes the figure a link. */
  href?: string;
  /**
   * The section on this page that holds the figure's evidence. Pressing the
   * figure jumps there, so a band's number is a way into the list under it
   * rather than only a link somewhere else.
   */
  section?: string;
  /** Makes the figure a button, as the Queue's status filters are. */
  onselect?: () => void;
  /** The button is the filter that is on now. */
  active?: boolean;
  /** Drawn in the pending colour on the plain panel; a band carries no status colour. */
  tone?: 'warning';
}

/** The way on to the page's fuller view, drawn at the end of the strip. */
export interface BandMore {
  label: string;
  href: string;
}

/**
 * The figures the Usage band carries: what the chosen range did, and how much
 * runner time it took.
 *
 * The report already answers these questions in its table and charts. The
 * figures live here so the page opens on the same sentence as every other
 * fleet page, and so a phone, which never draws the band, still gets the
 * numbers at the top instead of below a wall of controls.
 *
 * Plain functions, as the sentences beside them are, so each figure can be
 * held to its input by a test.
 */
import { formatDuration, formatNumber, NO_VALUE } from '../format';
import type { UsageRow } from '../api/types';
import type { BandStat } from './stats';
import type { BandLine } from './lines';

export interface UsageTotals {
  jobs: number;
  started: number;
  completed: number;
  succeeded: number;
  failed: number;
  cancelled: number;
  unknown: number;
  seconds: number;
  allocated: number;
  wait: number;
}

const count = (n: number, one: string, many: string) => `${n} ${n === 1 ? one : many}`;

export function usageTotals(rows: readonly UsageRow[]): UsageTotals {
  return rows.reduce(
    (a, r) => ({
      jobs: a.jobs + r.jobs,
      started: a.started + r.jobs_started,
      completed: a.completed + r.jobs_completed,
      succeeded: a.succeeded + (r.succeeded ?? 0),
      failed: a.failed + (r.failed ?? 0),
      cancelled: a.cancelled + (r.cancelled ?? 0),
      unknown: a.unknown + (r.unknown ?? 0),
      seconds: a.seconds + r.job_execution_seconds,
      allocated: a.allocated + (r.allocated_runner_seconds ?? 0),
      wait: a.wait + (r.average_queue_wait_seconds ?? 0) * r.jobs_started,
    }),
    {
      jobs: 0,
      started: 0,
      completed: 0,
      succeeded: 0,
      failed: 0,
      cancelled: 0,
      unknown: 0,
      seconds: 0,
      allocated: 0,
      wait: 0,
    },
  );
}

/**
 * The same figures the page's tiles used to show, in the order the table reads
 * them. `attributable` is false for a repository or workflow grouping, where a
 * runner has no owner to charge, so the busy share is left out rather than
 * claimed.
 */
export function usageStats(
  total: UsageTotals,
  attributable: boolean,
  section?: string,
): BandStat[] {
  const onPage = section === undefined ? {} : { section };
  const stats: BandStat[] = [
    {
      label: 'Jobs queued',
      value: formatNumber(total.jobs),
      hint: `${formatNumber(total.started)} started inside this range.`,
      ...onPage,
    },
    {
      label: 'Success rate',
      value: total.completed
        ? `${((100 * total.succeeded) / total.completed).toFixed(1)}%`
        : NO_VALUE,
      hint: total.completed
        ? `${formatNumber(total.succeeded)} of ${formatNumber(total.completed)} completed jobs succeeded.`
        : 'Nothing has finished in this range yet.',
      ...onPage,
    },
    {
      label: 'Failed jobs',
      value: formatNumber(total.failed),
      hint: `${formatNumber(total.cancelled)} cancelled or skipped, ${formatNumber(
        total.unknown,
      )} with no outcome on record.`,
      ...onPage,
    },
    {
      label: 'Execution hours',
      value: (total.seconds / 3600).toFixed(2),
      hint: 'Running time inside this range.',
      ...onPage,
    },
    {
      label: 'Average queue wait',
      value: total.started ? formatDuration((1000 * total.wait) / total.started) : NO_VALUE,
      hint: 'Weighted across the jobs that started.',
      ...onPage,
    },
  ];
  if (attributable) {
    stats.push({
      label: 'Runner busy share',
      // A share only while the runner records are all there. A range that
      // reaches past runner retention has some of its jobs' hours and only
      // some of its runners', and the ratio then means nothing.
      value:
        total.allocated && total.allocated >= total.seconds
          ? `${((100 * total.seconds) / total.allocated).toFixed(1)}%`
          : NO_VALUE,
      hint:
        total.allocated && total.allocated < total.seconds
          ? 'Runner records for part of this range are no longer retained.'
          : `${(total.allocated / 3600).toFixed(2)} allocated runner-hours.`,
      ...onPage,
    });
  }
  return stats;
}

/**
 * What the band says: how much work the range held, and how it went. `when`
 * is the range as a phrase the sentence can use ("today", "in the last day",
 * "in this range").
 */
export function usageLine(total: UsageTotals, when: string): BandLine {
  if (total.jobs === 0) {
    return {
      headline: 'Nothing was queued in this range.',
      accent: '',
      lede: 'Widen the range, or change what the report is grouped by.',
    };
  }
  return {
    headline: `${count(total.jobs, 'job', 'jobs')} queued ${when}.`,
    accent: total.completed
      ? `${((100 * total.succeeded) / total.completed).toFixed(1)}% succeeded.`
      : 'Nothing has finished yet.',
    lede: `${total.failed} failed. ${(total.seconds / 3600).toFixed(2)} execution hours.`,
  };
}

/**
 * The brand, as it appears on GitHub.
 *
 * This is the browser's half of internal/store/brand.go. The two have to agree
 * exactly: the server brands the labels it stores, and the wizard shows the
 * operator what it is about to store. A disagreement would show one label in
 * the preview and save another.
 */

/** The product name, lowercased, as it appears in a label. */
export const BRAND = 'zoomies';

/** The one label every Zoomies pool answers to. */
export const BRAND_LABEL = BRAND;

/** What every runner name starts with. */
export const RUNNER_NAME_PREFIX = `${BRAND}-`;

/** The labels GitHub attaches to every self-hosted runner by itself. */
export const IMPLICIT_LABELS: readonly string[] = [
  'self-hosted',
  'linux',
  'windows',
  'macos',
  'x64',
  'arm64',
  'arm',
];

/** How long the part of a label derived from a pool name may be. */
const MAX_LABEL_SEGMENT = 40;

export function isImplicit(label: string): boolean {
  return IMPLICIT_LABELS.includes(label.trim().toLowerCase());
}

/** Lowercase and trim, which is how GitHub compares two labels. */
export function normalizeLabel(label: string): string {
  return label.trim().toLowerCase();
}

/** Lowercase, de-duplicate and sort, which is what the server stores. */
export function normalizeLabels(labels: readonly string[]): string[] {
  const seen = new Set<string>();
  for (const label of labels) {
    const l = normalizeLabel(label);
    if (l !== '') seen.add(l);
  }
  return [...seen].sort();
}

/**
 * Reduce an arbitrary string to the characters GitHub accepts in a label:
 * lowercase letters, digits and single hyphens, trimmed.
 */
export function sanitizeLabel(value: string): string {
  const collapsed = normalizeLabel(value)
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
  return collapsed.slice(0, MAX_LABEL_SEGMENT).replace(/-+$/, '');
}

/**
 * The label a pool of this name should answer to: the brand, then the name.
 * A name that already starts with the brand keeps it rather than gaining a
 * second one.
 */
export function brandedLabel(name: string): string {
  const s = sanitizeLabel(name);
  if (s === '' || s === BRAND) return BRAND_LABEL;
  return s.startsWith(RUNNER_NAME_PREFIX) ? s : RUNNER_NAME_PREFIX + s;
}

/**
 * The name a pool of this name will be saved under: the brand, then the name.
 *
 * The server brands every pool name on the way in, so a field left saying
 * "gpu" would be showing the operator a name that is not the one they get.
 * A name that already carries the brand keeps it rather than gaining a second.
 * An empty name stays empty, because "give the pool a name" is what should be
 * said about it, not "zoomies-".
 */
export function brandedName(name: string): string {
  const s = name.trim();
  const lower = normalizeLabel(s);
  if (s === '' || lower === BRAND || lower.startsWith(RUNNER_NAME_PREFIX)) return s;
  return RUNNER_NAME_PREFIX + s.replace(/^-+/, '');
}

/** These labels, with the brand guaranteed present. */
export function brandLabels(labels: readonly string[]): string[] {
  return normalizeLabels([BRAND_LABEL, ...labels]);
}

/**
 * The shortest `runs-on` value that reaches a pool with these labels.
 *
 * One label of its own is enough, and it is what a workflow should write:
 * "runs-on: zoomies-linux-x64" says where the job runs. Where a pool needs
 * several labels to be identified, the list form is rendered instead, because
 * dropping one would send the job somewhere else.
 */
export function runsOn(labels: readonly string[]): string {
  const all = normalizeLabels(labels);
  const specific = all.filter((l) => !isImplicit(l) && l !== BRAND_LABEL);
  if (specific.length === 1) return specific[0]!;
  if (specific.length === 0) return all.includes(BRAND_LABEL) ? BRAND_LABEL : 'self-hosted';
  return `[${specific.join(', ')}]`;
}

/** The workflow snippet a `runs-on` value belongs in. */
export function runsOnSnippet(labels: readonly string[]): string {
  return `jobs:\n  build:\n    runs-on: ${runsOn(labels)}`;
}

/**
 * Loading route code over a connection that drops things.
 *
 * Every page but the login form arrives as its own content-hashed chunk,
 * fetched the moment somebody navigates to it. Two ordinary events break that
 * fetch, and neither is a bug in the page being opened:
 *
 *  * A phone on a flaky link -- a VPN reconnecting, a lift, a tunnel -- loses
 *    the request. Nothing is wrong; the bytes stopped arriving.
 *  * The controller was upgraded while the tab sat open. Chunk names carry a
 *    content hash, so the URL the open page holds is gone from the new build
 *    and the server answers 404. Every navigation from that tab fails until it
 *    is reloaded.
 *
 * Both look identical to `import()`, and both are fixed by the thing an
 * operator does out of habit anyway: reload. So this does it for them -- a
 * couple of quiet retries first, then a single reload, and only once the
 * controller has been proven reachable. That last condition is the point: when
 * the network really is down, reloading trades a working shell for the
 * browser's offline page, so the caller's error state is the better answer.
 */

import { sleep } from './sleep';

/** How long to wait before each retry, in milliseconds. */
const RETRY_DELAYS = [200, 700] as const;

/**
 * Where a spent reload is recorded, so a chunk that is broken rather than
 * missing cannot put the tab in a reload loop.
 */
const RELOAD_KEY = 'zoomies.chunk-reload';

/**
 * The controller version a reload has already been spent on. An upgrade is a
 * new reason to reload however recently one was spent; the same upgrade twice
 * is a loop.
 */
const RELOAD_VERSION_KEY = 'zoomies.chunk-reload-version';

/** A second failure this soon after a reload is not one a reload fixes. */
const RELOAD_COOLDOWN = 30_000;

/**
 * Load a route chunk, retrying a failure that looks transient.
 *
 * @param load the route's `() => import(...)`.
 * @param abandoned true once a later navigation has superseded this one, so a
 *   retry is not spent on a page nobody is waiting for any more.
 */
export async function loadChunk<T>(
  load: () => Promise<T>,
  abandoned: () => boolean = () => false,
): Promise<T> {
  let last: unknown;
  try {
    return await load();
  } catch (cause) {
    last = cause;
  }
  for (const delay of RETRY_DELAYS) {
    if (abandoned()) throw last;
    await sleep(delay);
    if (abandoned()) throw last;
    try {
      return await load();
    } catch (cause) {
      last = cause;
    }
  }
  throw last;
}

/**
 * Reload the page to recover from a chunk that would not load, if a reload is
 * both likely to help and safe to spend.
 *
 * @returns true when a reload is under way, so the caller should keep waiting
 *   rather than rendering an error the operator has no time to read.
 */
export async function reloadForFailedChunk(): Promise<boolean> {
  const now = Date.now();
  let spent: number;
  let reloadedFor: string | null;
  try {
    spent = Number(sessionStorage.getItem(RELOAD_KEY) ?? 0);
    reloadedFor = sessionStorage.getItem(RELOAD_VERSION_KEY);
  } catch {
    // Private mode, or storage denied. Without somewhere to record the reload
    // there is no way to stop it repeating, so leave it to the operator.
    return false;
  }

  const health = await controllerHealth();
  // Nothing is answering. Reloading now would trade a working shell for the
  // browser's offline page, so the caller's error state is the better answer.
  if (!health) return false;

  // An upgrade is what actually renames chunks, and the controller says which
  // version it is. Seeing a version this tab has not already reloaded for is
  // proof that a reload will help, so it is spent whatever the cooldown says:
  // the cooldown exists to stop a broken chunk looping, and a version that has
  // moved is not that. Without this, an upgrade landing within thirty seconds
  // of any earlier failure left the tab stuck on an error for a page that a
  // single reload would have fixed -- and every other page in that tab still
  // running code the fleet had moved on from.
  const upgraded = health.version !== '' && health.version !== reloadedFor;
  if (!upgraded && Number.isFinite(spent) && now - spent < RELOAD_COOLDOWN) return false;

  try {
    sessionStorage.setItem(RELOAD_KEY, String(now));
    if (health.version !== '') sessionStorage.setItem(RELOAD_VERSION_KEY, health.version);
  } catch {
    return false;
  }
  location.reload();
  return true;
}

/**
 * What the controller is, if it is there at all.
 *
 * A cheap unauthenticated request, uncached, answers two questions at once:
 * whether this phone is online, and which build is now being served. The
 * second is what tells "the upgrade moved the chunk" from "the request was
 * dropped", which are the two things that break an `import()` and want
 * different answers.
 *
 * It asks `/api/v1/meta` rather than `/healthz`. Liveness deliberately touches
 * nothing and says nothing but `{"ok":true}`, so reading a version from it got
 * an empty string every time and the upgrade case below could never fire --
 * which left the tab on an error for exactly the failure a reload fixes. Meta
 * is the route that already carries the build, it is already unauthenticated
 * because the shell needs it before anybody signs in, and it is equally cheap.
 *
 * Version and commit are both taken, because either moving means a new build
 * and new chunk names. A response with neither is still a reachable controller
 * -- an older one, or a proxy answering the probe -- so the identity is
 * optional and its absence falls back to the cooldown alone.
 */
async function controllerHealth(): Promise<{ version: string } | null> {
  try {
    const res = await fetch('/api/v1/meta', { cache: 'no-store', credentials: 'same-origin' });
    if (!res.ok) return null;
    const body: unknown = await res.json().catch(() => null);
    if (!body || typeof body !== 'object') return { version: '' };
    const meta = body as { version?: unknown; commit?: unknown };
    const parts = [meta.version, meta.commit].filter(
      (v): v is string => typeof v === 'string' && v !== '',
    );
    return { version: parts.join(' ') };
  } catch {
    return null;
  }
}

import type { ComparisonCaptureRequest } from '../api/types';

/** Refuse rounding a GitHub identity before JSON serialisation. */
export function parseAttempts(text: string): ComparisonCaptureRequest['baseline'] {
  const lines = text.trim().split(/\n/);
  if (!text.trim() || lines.length > 9) throw new Error('Select 1 to 9 attempts per arm.');
  return lines.map((line) => {
    const match = /^\s*(\d+)\s*:\s*(\d+)\s*$/.exec(line);
    if (!match) throw new Error('Enter one run ID:attempt per line, for example 123456:1.');
    const run_id = Number(match[1]);
    const attempt = Number(match[2]);
    if (
      !Number.isSafeInteger(run_id) ||
      run_id < 1 ||
      !Number.isSafeInteger(attempt) ||
      attempt < 1
    )
      throw new Error('Run IDs and attempts must be positive, safely representable whole numbers.');
    return { run_id, attempt };
  });
}

export function validateSelection(
  a: ComparisonCaptureRequest['baseline'],
  b: ComparisonCaptureRequest['candidate'],
): void {
  const all = [...a, ...b];
  if (all.length > 10) throw new Error('Select at most 10 attempts across both arms.');
  if (new Set(all.map((x) => `${x.run_id}:${x.attempt}`)).size !== all.length)
    throw new Error('An exact run attempt can appear only once across both arms.');
}

export function measuredMS(value: number | null): string {
  return value === null ? 'Unknown' : `${value.toLocaleString()} ms`;
}

import {
  Activity,
  Handshake,
  Hourglass,
  LoaderCircle,
  TrendingDown,
  TrendingUp,
  Zap,
  type LucideIcon,
} from '@lucide/svelte';

/**
 * How an Off status icon moves, chosen by glyph rather than by state: one
 * glyph means one thing wherever it appears, so the thing being set up turns
 * whether it is a runner or a machine. Only work still in progress moves, and
 * quietly; whatever is waiting or finished holds still, so a page of idle
 * runners is a calm one and a failure never draws the eye by moving. The
 * three CPU states are work too, and each one says which way the CPU went:
 * the trend line hops when there is extra, the bolt buzzes and charges up at
 * maximum, and the line sags and drags itself back up when the CPU is being
 * held back, so a runner on a lead is told apart from one that is simply idle.
 */
export type OffMotion = 'spin' | 'trace' | 'breathe' | 'turn' | 'lift' | 'buzz' | 'sag' | 'none';

const MOTIONS = new Map<LucideIcon, OffMotion>([
  [LoaderCircle, 'spin'],
  [Activity, 'trace'],
  [Handshake, 'breathe'],
  [Hourglass, 'turn'],
  [TrendingUp, 'lift'],
  [Zap, 'buzz'],
  [TrendingDown, 'sag'],
]);

/**
 * A glyph missing from the map holds still by default, which is right for
 * waiting and finished states but wrong for work in progress: a new busy
 * glyph that nobody mapped yet would look finished. Busy-toned glyphs
 * therefore fall back to the quiet breathe rather than to stillness.
 */
export function offMotion(icon: LucideIcon, tone?: string): OffMotion {
  const mapped = MOTIONS.get(icon);
  if (mapped) return mapped;
  return tone === 'busy' ? 'breathe' : 'none';
}

/**
 * Turning an API failure into something an operator can act on.
 *
 * The sign-in and first-run cards are the same screen at two moments in a
 * controller's life, and they meet the same failures: a controller that never
 * answered, a rate limiter, an origin check, a password that was refused. They
 * used to disagree about all of it -- Login.svelte separated four kinds and
 * Bootstrap.svelte printed `failure.message` raw -- so the two halves of the
 * first five minutes read as two different products. This is the one ladder
 * both of them climb.
 */
import { ApiError } from './api/client';

/**
 * The server's sentences are terse and lowercase, because they are also read
 * in a terminal and in a log line. On a card they are prose, so they start
 * with a capital and end with a full stop.
 *
 * Only ever the first letter and the last mark: not a word is changed, because
 * a 403 names the role required. Two things are left as written. A message that
 * opens with an identifier (`limits.job_stats_window ...`, `pool_ab12 ...`)
 * keeps its case, since a capital would name a setting that does not exist; and
 * one that ends in a path, an address or a colon takes no full stop, which
 * would be copied along with the address.
 */
export function sentence(text: string): string {
  const trimmed = text.trim();
  if (trimmed === '') return '';
  const identifier = /^\S*[._]\S*(\s|$)/.test(trimmed);
  const capitalised = identifier ? trimmed : trimmed.charAt(0).toUpperCase() + trimmed.slice(1);
  const open = /[.!?:]$/.test(capitalised) || /\S*\/\S*$/.test(capitalised);
  return open ? capitalised : `${capitalised}.`;
}

/**
 * What actually went wrong, in the operator's terms.
 *
 * A controller that never answered and a password that was refused look
 * identical in a generic "that did not work", and they need completely
 * different next steps. A 401 or 403 is shown in the server's own words: it
 * distinguishes a wrong password from a disabled account, from an account that
 * signs in through SSO, and -- on a 403 -- from the origin check refusing the
 * request, which is a proxy or external_url problem that "wrong password"
 * would send the operator off to fix in entirely the wrong place.
 */
export function authFailureText(error: unknown): string {
  if (!(error instanceof ApiError)) {
    if (error instanceof Error && error.message) return sentence(error.message);
    return 'That did not work, and the controller did not say why. Its logs will.';
  }
  if (error.status === 0) {
    return 'The controller did not answer. Check that it is running and that this address can reach it.';
  }
  if (error.status === 429) {
    return 'Too many attempts from this address. Wait a minute, then try again.';
  }
  // The one 5xx that is not the controller's fault: GitHub, or the network to it,
  // would not let a release check finish. The controller wrote a sentence for the
  // person who pressed the button (the outbound rule to api.github.com to check,
  // or that the check can be tried again later), and the generic line below would
  // swap it for a pointer to a log that does not hold the cause.
  if (error.code === 'update.check_failed') return sentence(error.message);
  if (error.status >= 500) {
    return 'The controller answered with an error. Its logs will say more than this page can.';
  }
  return sentence(error.message);
}

/**
 * The one sentence every "we could not tell you why" ends with.
 *
 * It used to say the controller log would have the cause, which assumes the
 * reader can read that log. On an instance one team operates while another
 * uses the fleet they cannot: the log belongs to the process, and the person
 * reading this runs pools on it. Naming the request ID and who to hand it to
 * is true for both, someone running their own instance is "whoever operates
 * this instance", and its log is theirs to open.
 *
 * One function rather than nine sentences, because nine sentences is how the
 * ninth came to say something the other eight had stopped saying.
 */
export function supportHint(requestId?: string): string {
  return requestId
    ? `Quote ${requestId} to whoever operates this instance; the cause is in its log.`
    : 'Quote the request ID to whoever operates this instance; the cause is in its log.';
}

/**
 * The fault vocabulary: whose a failure is, and what kind of failure it was.
 *
 * GitHub records a job whose runner died exactly as it records a job whose
 * tests failed. The server decides which is which -- it is the only side that
 * can -- and sends `fault_domain`, `fault_kind` and `fault_fix` on every job.
 * This file is the browser's half: the short label a badge shows and the
 * sentence a panel shows, neither of which belongs in a Go string.
 *
 * It is kept apart from status.ts for the same reason outcomes.ts is: that file
 * imports icon components and cannot be loaded outside a browser, and these
 * labels are wanted by tests that run in Node.
 */
import type { FaultKind } from '$lib/api/types';

/** Whose a failure is. Empty on a job that did not fail. */
export type FaultDomain = 'fleet' | 'workflow' | '';

interface FaultMeta {
  /** Two or three words, for a badge beside the outcome. */
  label: string;
  /** What happened, for the panel. The remedy comes from the server. */
  detail: string;
}

/**
 * Every category, in the order the docs list them: the ones that happen to a
 * running job first, then the ones that stop a runner ever taking one.
 *
 * The detail says what happened rather than what to do. What to do is
 * `fault_fix`, which the server sends with the job: one table of remedies, read
 * by the UI, the CLI and the problems drawer, rather than three that drift.
 */
const FAULTS: Record<FaultKind, FaultMeta> = {
  host_lost: {
    label: 'Host lost',
    detail:
      'The host stopped answering while it was running this job, and the runner went with the machine.',
  },
  out_of_memory: {
    label: 'Out of memory',
    detail: 'The runner was killed for exceeding its memory limit.',
  },
  out_of_disk: {
    label: 'Out of disk',
    detail: 'The host ran out of room. This job was the one running when the disk filled.',
  },
  removed: {
    label: 'Removed',
    detail: 'Somebody removed this runner with force while it was working.',
  },
  image: {
    label: 'Image',
    detail: 'The runner image could not be pulled or would not start.',
  },
  registration: {
    label: 'Registration',
    detail: 'GitHub would not register the runner, so it had nothing to attach to.',
  },
  backend: {
    label: 'Container backend',
    detail: 'The container backend on the host refused the work or did not answer.',
  },
  container_conflict: {
    label: 'Container name conflict',
    detail:
      'A container still occupies this name, and it could not be safely reclaimed. Check its ownership and whether another agent uses the same daemon.',
  },
  backend_busy: {
    label: 'Backend overloaded',
    detail:
      'The container backend on the host is there and did not answer in time, or was too slow to finish creating a container. The daemon is running; the machine is carrying more work than it can keep up with.',
  },
  config: {
    label: 'Configuration',
    detail:
      'The runner refused a setting it was given. Every runner in this pool will do the same until it is changed.',
  },
  runner_exited: {
    label: 'Runner stopped',
    detail: 'The runner stopped and the fleet could not narrow down why.',
  },
};

/**
 * The label for a category. A kind this build does not know falls back to its
 * own identifier made readable, rather than to nothing: a fleet running a newer
 * controller should show an unfamiliar word, not an empty badge.
 */
export function faultLabel(kind: string | null | undefined): string {
  if (!kind) return '';
  const known = FAULTS[kind as FaultKind];
  if (known) return known.label;
  return kind.replace(/_/g, ' ').replace(/^./, (c) => c.toUpperCase());
}

/** What happened, for a panel. Empty for a category this build does not know. */
export function faultDetail(kind: string | null | undefined): string {
  if (!kind) return '';
  return FAULTS[kind as FaultKind]?.detail ?? '';
}

/** Every category this build knows, for a filter's options. */
export const FAULT_KINDS = Object.keys(FAULTS) as FaultKind[];

/**
 * Whose a failure is, from the fields the server sends.
 *
 * It reads `fault_domain` and falls back to the same rule the server applies,
 * because a job delivered by an older controller carries the prose and not the
 * domain, and reading such a job as the workflow's would blame somebody for a
 * failure that was ours.
 */
export function faultDomain(job: {
  fault_domain?: string | null;
  fault_kind?: string | null;
  runner_fault?: string | null;
  conclusion?: string | null;
}): FaultDomain {
  if (job.fault_domain === 'fleet' || job.fault_domain === 'workflow') return job.fault_domain;
  if (job.fault_kind || job.runner_fault) return 'fleet';
  return '';
}

/** Whether this deployment, rather than the workflow, is why a job went wrong. */
export function fleetFailed(job: {
  fault_domain?: string | null;
  fault_kind?: string | null;
  runner_fault?: string | null;
}): boolean {
  return faultDomain(job) === 'fleet';
}

/**
 * Why the controller did something it did on its own.
 *
 * Kept apart from the entries that show it because it is plain data handling and
 * wants a test, and the module those entries live in imports components.
 */
import type { AuditEvent } from '../api/types';

/**
 * The sentence an automatic change carries as its reason, where this is one.
 *
 * Every change the controller makes by itself -- an automatic pool following its
 * hosts, a host moving class, a job's class moving -- is recorded under the
 * system identity with a `cause` in the row's after-picture, so that the audit
 * log answers "why did that change" without anybody having read the controller's
 * decision. An operator's own action has no such field, and an after-picture
 * that is not JSON at all is somebody else's shape, so both read as no cause.
 */
export function causeOf(event: Pick<AuditEvent, 'after'>): string | undefined {
  if (!event.after) return undefined;
  try {
    const after: unknown = JSON.parse(event.after);
    const cause = (after as { cause?: unknown } | null)?.cause;
    return typeof cause === 'string' && cause.trim() !== '' ? cause.trim() : undefined;
  } catch {
    return undefined;
  }
}

/**
 * What each thing the controller does on its own is called in the feed.
 *
 * Every one of these is recorded under the system identity with a `cause`, and
 * the sentence is what an entry is read for, so the title only says what kind of
 * change it was. The action names are what the Audit page filters on and are
 * kept as the target of the entry's link; this is the plain-words side.
 */
export const AUTOMATIC_ACTIONS: Readonly<Record<string, string>> = {
  'pool.auto_create': 'Automatic pool made',
  'pool.auto_reshape': 'Automatic pool brought back in line',
  'pool.auto_resize': 'Automatic pool resized',
  'pool.auto_enable': 'Automatic pool put back in use',
  'pool.auto_disable': 'Automatic pool put out of use',
  'host.size_class': 'Host size class changed',
  'size_class.move': 'Job size class changed',
};

/** The feed's title for an action the controller took on its own, or undefined for any other. */
export function automaticTitle(action: string | undefined): string | undefined {
  return action ? AUTOMATIC_ACTIONS[action] : undefined;
}

/**
 * What an automatic change was about, by name: the pool's, or the host's. The
 * audit row carries the id of what it concerns, which says nothing to a person,
 * and the name beside it in the after-picture, which does.
 */
export function subjectOf(event: Pick<AuditEvent, 'after'>): string | undefined {
  if (!event.after) return undefined;
  try {
    const after: unknown = JSON.parse(event.after);
    const doc = (after ?? {}) as { name?: unknown; host?: unknown };
    for (const name of [doc.name, doc.host]) {
      if (typeof name === 'string' && name.trim() !== '') return name.trim();
    }
  } catch {
    // Somebody else's shape; the entry says what it concerns by id instead.
  }
  return undefined;
}

/**
 * What in a frame is actually news.
 *
 * Kept apart from `entries.ts`, which imports the state map and its icon
 * components, for the same reason `outcomes.ts` is kept apart from
 * `status.ts`: this is the half a person would argue about -- what is news --
 * with no wording or icons to read past, and it is tested in Node. (The unit
 * runner stubs a Svelte import, so `entries.ts` loads there too and has a test
 * of its own, for the wording.)
 *
 * The rule every function here exists to enforce is that **a frame is not an
 * event**. A host publishes one whenever a heartbeat moves its CPU reading; a
 * machine publishes one on every step of an operation it is already in; a
 * runner publishes one for each state on the way up. A feed fed by frames is a
 * feed nobody reads -- and worse, it is one an operator turns off, losing the
 * lines that were worth having. So each of these answers the narrower
 * question: what is different about this that a person would want to be told,
 * and nothing that is merely different.
 */
import type {
  Host,
  Installation,
  Job,
  Machine,
  MachineState,
  Problem,
  Provider,
  RunnerState,
} from '../api/types';
import { outcomeOf } from '../outcomes';
import { problemKey } from '../problems/identity';

/* -- hosts ---------------------------------------------------------------- */

/**
 * The facts about a host worth a line. Everything else a host frame carries --
 * its load, its free slots, when it last spoke -- moves every thirty seconds
 * and says nothing that has not already been said by the capacity map.
 *
 * The OS report is the extreme case of that: a native agent sends one about
 * every minute and its `checked_at` is different every time, so the signal
 * holds the controller's verdict on it and never the report.
 */
export interface HostSignal {
  healthy: boolean;
  cordoned: boolean;
  /** The throttle rung the controller has it on; 0 for none. */
  throttle: number;
  /** An agent too old to talk to Zoomies at all. */
  incompatible: boolean;
  /** Whether pressure is holding new runners off this host right now. */
  holding: boolean;
  /**
   * Whether there is a verdict on the host's OS: a full report, with the
   * controller's count of it. A container's partial report is not one -- it
   * skips most checks and warns about the image's distribution for ever -- and
   * a payload with no count reads as not reported rather than as healthy.
   */
  reported: boolean;
  /**
   * How badly the counted checks say it is doing: 0 none, 1 warnings, 2 errors.
   * The throttle ladder's shape, so a warning becoming an error is news and an
   * error easing to a warning is not.
   */
  attention: number;
  rebootPending: boolean;
}

export type HostChange =
  | 'joined'
  | 'unreachable'
  | 'recovered'
  | 'cordoned'
  | 'uncordoned'
  | 'throttled'
  | 'calm'
  | 'holding'
  | 'admitting'
  | 'incompatible'
  | 'attention'
  | 'failing'
  | 'clear'
  | 'reboot';

export function hostSignal(host: Host): HostSignal {
  // Optional chains all the way down: this runs on every host frame, and a
  // controller that sends no count must make a host that has not reported, not
  // a feed that throws. Nothing here reads a clock or `checked_at` -- a value
  // that moves with the time is a value that flaps.
  const summary = host.doctor?.container === true ? undefined : host.doctor?.summary;
  return {
    healthy: host.healthy !== false,
    cordoned: host.cordoned === true,
    throttle: host.throttle?.level ?? 0,
    incompatible: host.incompatible === true,
    holding: Boolean(host.admission_reason),
    reported: Boolean(summary),
    attention: summary ? (summary.errors > 0 ? 2 : summary.warnings > 0 ? 1 : 0) : 0,
    rebootPending: Boolean(summary) && host.doctor?.reboot_pending === true,
  };
}

/**
 * What changed between two readings of a host, worst first.
 *
 * A host seen for the first time has joined the fleet, which is news exactly
 * once; the caller is responsible for not calling this for every host in the
 * first snapshot it loads.
 */
export function hostChanges(next: HostSignal, previous: HostSignal | undefined): HostChange[] {
  if (!previous) return ['joined'];
  const out: HostChange[] = [];
  if (next.healthy !== previous.healthy) out.push(next.healthy ? 'recovered' : 'unreachable');
  if (next.incompatible && !previous.incompatible) out.push('incompatible');
  if (next.cordoned !== previous.cordoned) out.push(next.cordoned ? 'cordoned' : 'uncordoned');
  // Every rung is its own line: a host climbing the ladder is a host under
  // worsening pressure, which is the thing an operator is watching for.
  if (next.throttle > previous.throttle) out.push('throttled');
  else if (next.throttle === 0 && previous.throttle > 0) out.push('calm');
  // The hold is not the throttle: a throttle takes slots away for minutes, a
  // hold is this moment's pressure refusing the next start. Both are answers
  // to "why is nothing starting here", and only the transitions are reported
  // -- the reason's wording moves with the load and would flap.
  if (next.holding !== previous.holding) out.push(next.holding ? 'holding' : 'admitting');
  // Both readings must be verdicts, and that one condition is the whole of the
  // noise story. A host's first report is a baseline, not news -- or a rolling
  // upgrade would print a line per host. A report with the same verdict as the
  // last, and a full report swapping with a container's partial one, change
  // nothing here. Going unreachable changes no summary, so it says nothing
  // about health. There is no stale line: no frame announces time passing, and
  // `host.health_stale` reaches people as a problem.
  if (previous.reported && next.reported) {
    if (next.attention > previous.attention)
      out.push(next.attention === 2 ? 'failing' : 'attention');
    // Only reaching zero is clear; an error easing to a warning is still a
    // host that needs attention, and has said so already.
    else if (next.attention === 0 && previous.attention > 0) out.push('clear');
    if (next.rebootPending && !previous.rebootPending) out.push('reboot');
  }
  return out;
}

/* -- runners ---------------------------------------------------------------- */

/**
 * The two moments in an ordinary runner's life worth a line.
 *
 * Not the six states it passes through: a fleet of ephemeral runners would
 * write one line per state per job, which is a log rather than a feed. A
 * runner reaching `idle` for the first time is the one that says the pool can
 * actually start containers -- the success the failures are the exception to
 * -- and a runner removed is the end of it. Coming back to idle from a job is
 * neither: the job's own line already said that.
 */
export type RunnerMilestone = 'ready' | 'retired';

export function runnerMilestone(
  next: RunnerState | undefined,
  previous: RunnerState | undefined,
): RunnerMilestone | null {
  if (!next || next === previous) return null;
  if (next === 'idle') return previous === 'busy' ? null : 'ready';
  if (next === 'removed') return 'retired';
  return null;
}

/* -- elastic CPU ------------------------------------------------------------ */

/**
 * A runner's elastic-CPU state changing: it was lent spare CPU, or had it
 * taken back, or the host it is on came under enough pressure to slow it.
 *
 * The state rather than the factor, because the factor moves with every
 * heartbeat and the six states are what the runner's own page shows. A
 * runner seen for the first time says nothing: the state it is already in is
 * not something that just happened.
 */
export function cpuChange(next: string | undefined, previous: string | undefined): string | null {
  if (!next || previous === undefined || next === previous) return null;
  return next;
}

/* -- machines -------------------------------------------------------------- */

/**
 * The states of a rented machine worth a line: it is costing money, it is
 * earning it, it is going away, or it went wrong. The steps between -- being
 * powered on, being bootstrapped, enrolling -- are progress rather than news,
 * and the machine's own page has them with their timings.
 */
const MACHINE_NEWS: ReadonlySet<MachineState> = new Set<MachineState>([
  'creating',
  'ready',
  'draining',
  'deleted',
  'failed',
  'quarantined',
]);

/** The state a machine has reached that is worth telling somebody, or null. */
export function machineChange(
  next: Pick<Machine, 'state'>,
  previous: MachineState | undefined,
): MachineState | null {
  const state = next.state;
  if (!state || state === previous) return null;
  return MACHINE_NEWS.has(state) ? state : null;
}

/* -- jobs ------------------------------------------------------------------ */

/**
 * What a finished job is worth saying, and on whose account.
 *
 * Every finished job is news of some kind -- this is the one category where a
 * frame that changes nothing does not exist, because a job is reported over
 * exactly once. What differs is which category it lands in: the failures are
 * what an operator acts on and stay on by default, and the rest are the panel
 * this feed replaced, which on a fleet finishing a job a minute is the noisiest
 * thing here and is a switch of its own for that reason.
 *
 * `runner_lost` is kept apart from `failed` although GitHub records both as a
 * failure: the runner stopped under the job, so that one is the fleet's own,
 * and telling the two apart is what the Overview is for.
 */
export type JobNews = 'runner_lost' | 'failed' | 'succeeded' | 'cancelled' | 'unknown';

export function jobNews(job: Job): JobNews | null {
  if (job.state !== 'completed') return null;
  if (job.runner_fault) return 'runner_lost';
  const outcome = outcomeOf(job);
  return outcome === 'failed' ? 'failed' : outcome;
}

/** Whether this is one of the two an operator is meant to act on. */
export function jobFailure(news: JobNews): boolean {
  return news === 'failed' || news === 'runner_lost';
}

/* -- providers and installations ------------------------------------------- */

export type ProviderChange =
  'paused' | 'resumed' | 'disabled' | 'enabled' | 'unreachable' | 'reachable';

export interface ProviderSignal {
  enabled: boolean;
  paused: boolean;
  /** Whether the last preflight had something to complain about. */
  failing: boolean;
}

export function providerSignal(provider: Provider): ProviderSignal {
  return {
    enabled: provider.enabled !== false,
    paused: provider.paused === true,
    failing: Boolean(provider.last_check_error),
  };
}

export function providerChanges(
  next: ProviderSignal,
  previous: ProviderSignal | undefined,
): ProviderChange[] {
  // A provider first seen is a provider somebody has just added, and adding
  // one is an audit entry rather than an incident.
  if (!previous) return [];
  const out: ProviderChange[] = [];
  if (next.enabled !== previous.enabled) out.push(next.enabled ? 'enabled' : 'disabled');
  if (next.paused !== previous.paused) out.push(next.paused ? 'paused' : 'resumed');
  if (next.failing !== previous.failing) out.push(next.failing ? 'unreachable' : 'reachable');
  return out;
}

export type InstallationChange = 'connected' | 'failing' | 'working';

export function installationChange(
  next: Installation,
  previous: boolean | undefined,
): InstallationChange | null {
  const healthy = next.healthy !== false;
  if (previous === undefined) return healthy ? null : 'failing';
  if (healthy === previous) return null;
  return healthy ? 'working' : 'failing';
}

/* -- problems -------------------------------------------------------------- */

/**
 * The problems in this report that were not in the last one.
 *
 * Identity is the drawer's, not the prose's, so "5 deliveries were rejected"
 * becoming "6 deliveries were rejected" is the same problem and is reported
 * once. `seen` is updated in place: the caller holds the set for as long as
 * the tab is open, and a problem that clears and comes back is news again.
 */
export function newProblems(items: readonly Problem[], seen: Set<string>): Problem[] {
  const live = new Set(items.map(problemKey));
  for (const key of seen) if (!live.has(key)) seen.delete(key);
  const out: Problem[] = [];
  for (const problem of items) {
    const key = problemKey(problem);
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(problem);
  }
  return out;
}

/**
 * One line of the Overview's feed, whatever it is about.
 *
 * Every entry is the same four things -- a mark in one of the six status
 * tones, what happened, what it happened to, and when -- so that a feed
 * carrying nine kinds of news still reads as one list rather than nine
 * stacked widgets. The detail line underneath is the controller's own
 * sentence where there is one: the scheduler's reason, the throttle's
 * explanation, the hypervisor's complaint. Paraphrasing those is how a
 * dashboard stops being trustworthy.
 *
 * The tones are the fixed status mapping every other page uses, and they are
 * used for the same meanings: danger for something that went wrong, draining
 * for something going away, pending for something under way or under
 * pressure, idle for something that came good, neutral for a fact.
 */
import {
  Boxes,
  Bot,
  CircleMinus,
  HeartPulse,
  Plug,
  Minus,
  Plus,
  RotateCw,
  ScrollText,
  ServerCog,
  TrendingDown,
  TrendingUp,
  TriangleAlert,
} from '@lucide/svelte';
import type { LucideIcon } from '@lucide/svelte';
import type {
  AuditEvent,
  Host,
  Installation,
  Job,
  Machine,
  MachineState,
  Pool,
  Problem,
  Provider,
  Runner,
  ScalingEvent,
  WebhookDelivery,
} from '../api/types';
import { faultLabel } from '../faults';
import { NO_VALUE, formatDuration, pluralise, shortId } from '../format';
import { findingsLabel } from '../hosts/health';
import {
  cpuResourceStatus,
  deliveryStatus,
  hostStatus,
  jobStatus,
  machineStatus,
  managedJob,
  runnerStatus,
  severityStatus,
  ELSEWHERE,
  RUNNER_LOST,
  type StatusTone,
} from '../status';
import type { FeedCategoryID } from './categories';
import { automaticTitle, causeOf, subjectOf } from './cause';
import {
  jobFailure,
  type HostChange,
  type InstallationChange,
  type JobNews,
  type ProviderChange,
  type RunnerMilestone,
} from './changes';

export interface FeedEntry {
  /**
   * Stable for the fact rather than for the frame, so the same thing arriving
   * twice -- a fetch and the replay of the frame it overlapped with -- is one
   * line. A repeated key in a keyed list is a framework error, not a cosmetic
   * one.
   */
  id: string;
  category: FeedCategoryID;
  /** When it happened, as the payload said, or when it arrived. */
  at: string;
  tone: StatusTone;
  icon: LucideIcon;
  /** What happened, in the fewest words that are still true. */
  title: string;
  /** The controller's own sentence about it, where there is one. */
  detail?: string;
  /** What it happened to, and the page that has the whole of it. */
  target?: { label: string; href?: string };
  /**
   * True for a job no runner of this fleet ran. The panel keeps these and
   * shows them only when the Overview is asked for every runner GitHub
   * reports on, which is the same switch its other job panels read.
   */
  elsewhere?: boolean;
}

/** Now, in the shape every timestamp in the API has. */
export function now(): string {
  return new Date().toISOString();
}

/* -- scaling --------------------------------------------------------------- */

/**
 * A scheduler decision.
 *
 * `index` is only there for a controller old enough to have written a
 * decision without an id; two decisions in the same second on the same pool
 * would otherwise share a key.
 */
export function scalingEntry(event: ScalingEvent, index: number): FeedEntry {
  const from = event.from;
  const to = event.to;
  const direction =
    from === undefined || to === undefined || to === from ? 'hold' : to > from ? 'up' : 'down';
  const counts = from !== undefined && to !== undefined ? ` ${from} → ${to}` : '';
  return {
    id: `scaling:${event.id ?? `${event.pool_id ?? ''}:${event.created_at ?? ''}:${index}`}`,
    category: 'scaling',
    at: event.created_at ?? '',
    tone: direction === 'up' ? 'pending' : direction === 'down' ? 'draining' : 'neutral',
    icon: direction === 'up' ? TrendingUp : direction === 'down' ? TrendingDown : Minus,
    title:
      direction === 'up'
        ? `Scaled up${counts}`
        : direction === 'down'
          ? `Scaled down${counts}`
          : 'Held',
    detail: event.reason || undefined,
    target: {
      label: event.pool_name ?? 'Unnamed pool',
      href: event.pool_id ? `/pools/${event.pool_id}` : undefined,
    },
  };
}

/* -- runners --------------------------------------------------------------- */

/**
 * A runner that failed. The fix is the detail rather than the message where
 * there is one: a runner that died before ever taking a job is the case this
 * exists for, and nothing else in the fleet says why a pool's containers will
 * not start.
 */
export function runnerFailureEntry(runner: Runner): FeedEntry | null {
  if (runner.state !== 'failed' || !runner.id) return null;
  const status = runnerStatus('failed');
  return {
    id: `runner:${runner.id}:failed`,
    category: 'runners',
    at: runner.finished_at ?? runner.created_at ?? '',
    tone: status.tone,
    icon: status.icon,
    title: 'A runner failed',
    detail: runner.fault_fix || runner.message || undefined,
    target: { label: runner.name ?? shortId(runner.id), href: `/runners/${runner.id}` },
  };
}

/**
 * A runner reaching the two moments of an ordinary life: ready for work, and
 * gone when the work was done.
 *
 * This is the half of the fleet that goes right, and it is here because a
 * panel that only ever reports failures teaches an operator that silence is
 * the good state -- which is the same thing as teaching them not to read it.
 */
export function runnerMilestoneEntry(
  runner: Runner,
  milestone: RunnerMilestone,
  at: string,
): FeedEntry | null {
  if (!runner.id) return null;
  const ready = milestone === 'ready';
  const status = runnerStatus(ready ? 'idle' : 'removed');
  const handled = runner.jobs_handled ?? 0;
  return {
    id: `runner:${runner.id}:${milestone}`,
    category: 'runner-lifecycle',
    at: (ready ? runner.registered_at : runner.finished_at) ?? at,
    tone: ready ? 'idle' : 'neutral',
    icon: status.icon,
    title: ready ? 'A runner is ready for work' : 'A runner finished and was removed',
    detail: ready
      ? [runner.pool_name, runner.host_name].filter(Boolean).join(' · ') || undefined
      : // What it was for, which is the only thing that distinguishes an
        // ephemeral runner's end from a scale-down taking an idle one away.
        [
          handled > 0 ? pluralise(handled, 'job') : 'no jobs',
          runner.pool_name ?? '',
          runner.host_name ?? '',
        ]
          .filter(Boolean)
          .join(' · '),
    target: { label: runner.name ?? shortId(runner.id), href: `/runners/${runner.id}` },
  };
}

/* -- elastic CPU ------------------------------------------------------------ */

/**
 * A runner lent spare CPU, or having it taken back.
 *
 * The title is the controller's own label -- "Squirrel spotted, maximum
 * zoomies" -- because that vocabulary is the product's, it is what the
 * runner's own page says, and a feed that translated it into "CPU allocation
 * factor 1.8" would be describing a different system from the one beside it
 * -- unless the operator has turned that vocabulary off, when it says the
 * same thing plainly instead.
 */
export function cpuEntry(
  runner: Runner,
  state: string,
  at: string,
  quirky = true,
): FeedEntry | null {
  if (!runner.id) return null;
  const cpu = runner.cpu_resource;
  const status = cpuResourceStatus(state, cpu?.label, quirky);
  const current = cpu?.current_cpus;
  const guaranteed = cpu?.guaranteed_cpus;
  return {
    id: `cpu:${runner.id}:${state}:${at}`,
    category: 'cpu',
    at,
    tone: status.tone,
    icon: status.icon,
    title: status.label,
    detail:
      current !== undefined && guaranteed !== undefined
        ? `${formatCPUs(current)} CPUs now against a guarantee of ${formatCPUs(guaranteed)}` +
          (runner.host_name ? ` · ${runner.host_name}` : '')
        : status.hint,
    target: { label: runner.name ?? shortId(runner.id), href: `/runners/${runner.id}` },
  };
}

/** CPUs as the runner's own page prints them: whole where they are whole. */
function formatCPUs(value: number): string {
  return Number.isInteger(value) ? String(value) : value.toFixed(1);
}

/* -- jobs ------------------------------------------------------------------ */

/**
 * One finished job, in the shape the recent-outcomes panel used to give it:
 * what it was, how it ended, the step it stopped at or the fault behind it,
 * the repository and branch, and how long it took. That panel is gone, and
 * this is where its rows went -- a job ending is news like anything else, and
 * two reverse-chronological lists on one page, each with its own idea of what
 * belongs on it, is one list too many.
 *
 * The failures land in their own category, so an operator on a busy fleet can
 * switch off the hundred jobs that succeeded without switching off the two
 * that did not.
 */
export function jobEntry(job: Job, news: JobNews, at = now()): FeedEntry | null {
  if (!job.id) return null;
  const failure = jobFailure(news);
  const status = news === 'runner_lost' ? RUNNER_LOST : jobStatus('completed', job.conclusion);
  return {
    id: `job:${job.id}`,
    category: failure ? 'jobs' : 'outcomes',
    at: job.completed_at ?? job.started_at ?? at,
    tone: failure ? 'danger' : status.tone,
    icon: status.icon,
    title: jobTitle(job, news),
    detail: jobDetail(job, news),
    // Kept rather than dropped, and hidden unless the page is asked for
    // everything: GitHub reports every job in the repositories an installation
    // covers, and on an organisation that also uses hosted runners most of
    // them are somebody else's.
    elsewhere: !managedJob(job),
    target: {
      label: `${job.workflow ?? 'Unknown workflow'} / ${job.job_name ?? 'unnamed job'}`,
      href: `/jobs?q=${encodeURIComponent(job.job_name ?? '')}&repo=${encodeURIComponent(job.repo ?? '')}`,
    },
  };
}

function jobTitle(job: Job, news: JobNews): string {
  if (news === 'runner_lost') return 'A job’s runner stopped under it';
  if (news === 'failed') return 'A job failed';
  switch ((job.conclusion ?? '').toLowerCase()) {
    case 'success':
      return 'A job succeeded';
    case 'cancelled':
      return 'A job was cancelled';
    case 'skipped':
      return 'A job was skipped';
    default:
      return 'A job finished';
  }
}

/**
 * The one line under it, in the order the outcomes panel read: why it ended
 * that way, where it came from, and how long it took.
 *
 * The fault's category rather than "the runner stopped under it" for the
 * fleet's own failures, because the sentence above already says that and the
 * word that differs between two lines is the one worth the space.
 */
function jobDetail(job: Job, news: JobNews): string | undefined {
  const why =
    news === 'runner_lost'
      ? faultLabel(job.fault_kind).toLowerCase() || 'the runner stopped under it'
      : news === 'failed' && job.failed_step
        ? `at ${job.failed_step.name ?? `step ${job.failed_step.number ?? '?'}`}`
        : '';
  const parts = [
    !managedJob(job) ? ELSEWHERE.label.toLowerCase() : '',
    why,
    job.repo ?? '',
    job.head_branch ?? '',
    formatDuration(job.duration_ms),
  ].filter((part) => part && part !== NO_VALUE);
  return parts.length > 0 ? parts.join(' · ') : undefined;
}

/* -- hosts ----------------------------------------------------------------- */

const HOST_NEWS: Record<HostChange, { title: string; tone: StatusTone }> = {
  joined: { title: 'A host joined the fleet', tone: 'idle' },
  unreachable: { title: 'A host stopped answering', tone: 'danger' },
  recovered: { title: 'A host is answering again', tone: 'idle' },
  cordoned: { title: 'A host was cordoned', tone: 'draining' },
  uncordoned: { title: 'A host was uncordoned', tone: 'idle' },
  throttled: { title: 'A host was throttled', tone: 'pending' },
  calm: { title: 'A host’s throttle lifted', tone: 'idle' },
  holding: { title: 'A host is holding new runners', tone: 'pending' },
  admitting: { title: 'A host is taking runners again', tone: 'idle' },
  incompatible: { title: 'A host’s agent is too old for Zoomies', tone: 'danger' },
  attention: { title: 'A host needs attention', tone: 'pending' },
  failing: { title: 'A host has a health error', tone: 'danger' },
  clear: { title: 'A host no longer needs attention', tone: 'idle' },
  reboot: { title: 'A host is waiting for a reboot', tone: 'pending' },
};

/**
 * The four lines about a host's OS get a mark of their own. The host's status
 * icon is the host's -- for a healthy one, a plain circle -- and a line about
 * its settings drawn with it would look like a line about its heartbeat. Clear
 * has the same mark as attention on purpose: it is the same subject coming
 * good, and the tone says which way.
 */
const HOST_HEALTH_ICON: Partial<Record<HostChange, LucideIcon>> = {
  attention: HeartPulse,
  failing: TriangleAlert,
  clear: HeartPulse,
  reboot: RotateCw,
};

/**
 * The one line under a host's entry, where there is one.
 *
 * The OS lines say the controller's count, in the pill's own words, and for a
 * reboot whether it can be done now -- the question an operator reads it to
 * answer. The active runner count is always sent, so 0 means nothing is
 * running rather than nothing is known.
 */
function hostDetail(host: Host, change: HostChange): string | undefined {
  switch (change) {
    case 'holding':
      return host.admission_reason || undefined;
    case 'throttled':
      return host.throttle_reason || hostStatus(host).hint;
    case 'incompatible':
      return host.incompatible_reason || undefined;
    case 'unreachable':
      return hostStatus(host).hint;
    case 'attention':
    case 'failing':
      return (host.doctor?.summary && findingsLabel(host.doctor.summary)) || undefined;
    case 'reboot':
      return host.active_runners === 0
        ? 'Nothing is running on it, so it can be rebooted now.'
        : 'Runners are on it, and one kept warm for a pool never finishes by itself. Cordon it and reboot when none is running a job; Zoomies never reboots a host itself.';
    default:
      return undefined;
  }
}

export function hostEntry(host: Host, change: HostChange, at: string): FeedEntry | null {
  if (!host.id) return null;
  const news = HOST_NEWS[change];
  const osIcon = HOST_HEALTH_ICON[change];
  const aboutOS = osIcon !== undefined;
  return {
    id: `host:${host.id}:${change}:${at}`,
    category: 'hosts',
    at,
    tone: news.tone,
    icon: osIcon ?? (change === 'joined' ? Plus : hostStatus(host).icon),
    title: news.title,
    detail: hostDetail(host, change),
    // The host's own page for a line about its OS, because that is where the
    // report and its rows are. `at` stays the arrival time rather than the
    // report's `checked_at`, which is the agent's clock: a host whose clock is
    // wrong would otherwise date its own news.
    target: {
      label: host.name ?? shortId(host.id),
      href: aboutOS ? `/hosts/${host.id}` : '/hosts',
    },
  };
}

export function hostRemovedEntry(id: string, name: string | undefined, at: string): FeedEntry {
  return {
    id: `host:${id}:removed:${at}`,
    category: 'hosts',
    at,
    tone: 'neutral',
    icon: CircleMinus,
    title: 'A host was removed',
    target: { label: name ?? shortId(id), href: '/hosts' },
  };
}

/* -- machines and providers ------------------------------------------------- */

const MACHINE_NEWS: Record<string, string> = {
  creating: 'A machine is being rented',
  ready: 'A machine became a host',
  draining: 'A machine is draining',
  deleted: 'A machine was returned',
  failed: 'A machine failed',
  quarantined: 'A machine was quarantined',
};

export function machineEntry(machine: Machine, state: MachineState, at: string): FeedEntry {
  const status = machineStatus(state);
  return {
    id: `machine:${machine.id}:${state}`,
    category: 'machines',
    at: machine.updated_at ?? at,
    tone: status.tone,
    icon: status.icon,
    title: MACHINE_NEWS[state] ?? `A machine is ${status.label.toLowerCase()}`,
    detail:
      machine.provider_error ||
      machine.bootstrap_error ||
      machine.ownership_error ||
      machine.message ||
      undefined,
    target: { label: machine.name, href: `/machines/${machine.id}` },
  };
}

