}

/**
 * One recorded action. The action name is printed as it was recorded rather
 * than translated into prose: it is what the Audit page filters on and what a
 * support conversation quotes.
 */
export function auditEntry(event: AuditEvent): FeedEntry | null {
  if (!event.id || !event.action) return null;
  const actor = event.actor_name || event.actor_kind || 'somebody';
  const target =
    event.target_kind && event.target_id
      ? `${event.target_kind} ${shortId(event.target_id)}`
      : undefined;
  // What the controller did on its own is not "who changed what": nobody did,
  // and it has a reason, which is what the entry is read for -- "pool.auto_resize"
  // alone is a number that moved. It has a category of its own, on by default,
  // because a fleet that has turned automatic pools on wants to watch them work.
  const automatic = automaticTitle(event.action);
  const cause = causeOf(event);
  const subject = automatic ? (subjectOf(event) ?? target) : target;
  return {
    id: `audit:${event.id}`,
    category: automatic ? 'automatic' : 'audit',
    at: event.created_at ?? now(),
    tone: 'neutral',
    icon: automatic ? Bot : ScrollText,
    title: automatic ?? `${actor} ran ${event.action}`,
    detail: cause ? (subject ? `${subject}: ${cause}` : cause) : subject,
    target: {
      label: 'Audit',
      href: `/audit?action=${encodeURIComponent(event.action)}`,
    },
  };
}

/**
 * Formatting helpers. Every number an operator reads goes through one of these,
 * so "4m ago" means the same thing on every page.
 */

/**
 * What a value that is not there reads as, on every page. The formatters below
 * answer with it for a null, and a page that has no formatter to call (a tile
 * whose figure is simply not known yet) writes the same thing, so a table cell
 * and the tile above it cannot disagree about what "nothing to show" looks like.
 */
export const NO_VALUE = '--';

/* -- the shared clock ----------------------------------------------------
 * A thousand runner rows must not mean a thousand timers. One interval ticks,
 * and every RelativeTime on screen recomputes from it.
 * --------------------------------------------------------------------- */

type Tick = (now: number) => void;

const tickers = new Set<Tick>();
let clock: ReturnType<typeof setInterval> | null = null;

/** How often relative times refresh. Ten seconds keeps "just now" honest. */
export const CLOCK_INTERVAL_MS = 10_000;

function fire(): void {
  const now = Date.now();
  for (const fn of tickers) fn(now);
}

/**
 * Subscribe to the shared clock. Returns the unsubscribe function; the last
 * unsubscriber stops the interval, so an idle page costs nothing.
 */
export function onClockTick(fn: Tick): () => void {
  tickers.add(fn);
  if (clock === null && typeof window !== 'undefined') {
    clock = setInterval(fire, CLOCK_INTERVAL_MS);
    document.addEventListener('visibilitychange', onVisible);
  }
  return () => {
    tickers.delete(fn);
    if (tickers.size === 0 && clock !== null) {
      clearInterval(clock);
      clock = null;
      document.removeEventListener('visibilitychange', onVisible);
    }
  };
}

function onVisible(): void {
  // A backgrounded tab throttles timers, so catch up the moment it returns.
  if (document.visibilityState === 'visible') fire();
}

/* -- time ---------------------------------------------------------------- */

export type TimeInput = string | number | Date | null | undefined;

/** Milliseconds since the epoch, or null when there is no usable value. */
export function toMillis(value: TimeInput): number | null {
  if (value === null || value === undefined || value === '') return null;
  const ms = value instanceof Date ? value.getTime() : new Date(value).getTime();
  return Number.isNaN(ms) ? null : ms;
}

const ABSOLUTE = new Intl.DateTimeFormat(undefined, {
  dateStyle: 'medium',
  timeStyle: 'medium',
});

/** The local wall-clock rendering, for detail panels and tooltips. */
export function formatAbsolute(value: TimeInput): string {
  const ms = toMillis(value);
  return ms === null ? NO_VALUE : ABSOLUTE.format(ms);
}

/** Both forms, for a `title` attribute: local time first, then the exact ISO value. */
export function formatTimestampTitle(value: TimeInput): string {
  const ms = toMillis(value);
  if (ms === null) return 'No timestamp recorded';
  return `${ABSOLUTE.format(ms)} (${new Date(ms).toISOString()})`;
}

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

/**
 * "4m ago", "in 2h", "just now". Past and future both read naturally, which
 * matters because token expiry and job queue times sit in the same table.
 */
export function relativeTime(value: TimeInput, now: number = Date.now()): string {
  const ms = toMillis(value);
  if (ms === null) return NO_VALUE;
  const delta = now - ms;
  const abs = Math.abs(delta);
  const past = delta >= 0;

  if (abs < 10_000) return 'just now';
  const unit =
    abs < MINUTE
      ? `${Math.round(abs / 1000)}s`
      : abs < HOUR
        ? `${Math.round(abs / MINUTE)}m`
        : abs < DAY
          ? `${Math.round(abs / HOUR)}h`
          : abs < 7 * DAY
            ? `${Math.round(abs / DAY)}d`
            : null;
  if (unit === null) return formatAbsolute(ms);
  return past ? `${unit} ago` : `in ${unit}`;
}

/* -- durations ------------------------------------------------------------ */

function pad(n: number): string {
  return n < 10 ? `0${n}` : String(n);
}

/**
 * A humanised duration: "820ms", "4.2s", "1m 04s", "3h 12m", "2d 04h".
 * Two units at most -- more than that is noise in a table cell.
 */
export function formatDuration(ms: number | null | undefined): string {
  if (ms === null || ms === undefined || Number.isNaN(ms)) return NO_VALUE;
  const value = Math.max(0, Math.round(ms));
  if (value < 1000) return `${value}ms`;
  const seconds = value / 1000;
  if (seconds < 10) return `${seconds.toFixed(1)}s`;
  if (seconds < 60) return `${Math.round(seconds)}s`;
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) return `${minutes}m ${pad(Math.floor(seconds % 60))}s`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours}h ${pad(minutes % 60)}m`;
  const days = Math.floor(hours / 24);
  return `${days}d ${pad(hours % 24)}h`;
}

const GO_UNITS: Record<string, number> = {
  ns: 1e-6,
  us: 1e-3,
  µs: 1e-3,
  ms: 1,
  s: 1000,
  m: 60_000,
  h: 3_600_000,
};

/**
 * Parse a Go duration string ("5m", "1h30s") into milliseconds. Returns null
 * for anything it does not understand, so a form can report it as invalid.
 */
export function parseGoDuration(input: string | null | undefined): number | null {
  if (!input) return null;
  const text = input.trim();
  if (text === '0') return 0;
  const pattern = /(\d+(?:\.\d+)?)(ns|us|µs|ms|s|m|h)/g;
  let total = 0;
  let matched = 0;
  let consumed = 0;
  for (const m of text.matchAll(pattern)) {
    const amount = Number(m[1]);
    const unit = GO_UNITS[m[2] ?? ''];
    if (unit === undefined || Number.isNaN(amount)) return null;
    total += amount * unit;
    matched += 1;
    consumed += m[0].length;
  }
  if (matched === 0 || consumed !== text.length) return null;
  return total;
}

/** Render milliseconds as the Go duration string the API expects. */
export function toGoDuration(ms: number): string {
  if (ms <= 0) return '0s';
  const parts: string[] = [];
  let rest = Math.round(ms);
  const hours = Math.floor(rest / 3_600_000);
  rest -= hours * 3_600_000;
  const minutes = Math.floor(rest / 60_000);
  rest -= minutes * 60_000;
  const seconds = rest / 1000;
  if (hours) parts.push(`${hours}h`);
  if (minutes) parts.push(`${minutes}m`);
  if (seconds) parts.push(`${Number(seconds.toFixed(3))}s`);
  return parts.join('') || '0s';
}

/**
 * A Go duration in the shortest spelling a person would write: the API says
 * "5m0s" and an operator says "5m". Anything that cannot be read is left as it
 * was typed, so a half-typed value is never rewritten under the cursor.
 */
export function shortGoDuration(input: string | null | undefined): string {
  const ms = parseGoDuration(input);
  return ms === null ? (input ?? '').trim() : toGoDuration(ms);
}

/** A Go duration string, spelled out for a person: "5m" becomes "5m". */
export function formatGoDuration(input: string | null | undefined): string {
  const ms = parseGoDuration(input);
  return ms === null ? (input ?? NO_VALUE) : formatDuration(ms);
}

/**
 * A Go duration, as a period a sentence can name: "24h0m0s" becomes
 * "24 hours".
 *
 * The API says what window a figure covers and the page used to claim one of
 * its own in prose, which is how the Overview came to promise waits "over the
 * last hour" for figures the controller computes over a day. Returns an empty
 * string for anything it cannot read, so a caller leaves the claim out
 * altogether rather than making a worse one.
 */
export function describeWindow(input: string | null | undefined): string {
  const ms = parseGoDuration(input);
  if (ms === null || ms <= 0) return '';
  const units: [number, string, number][] = [
    // A day only once there is more than one of them: the default window is a
    // day, and "the last 24 hours" is how an operator says it -- "the last 1
    // day" is how nothing says it.
    [86_400_000, 'day', 2],
    [3_600_000, 'hour', 1],
    [60_000, 'minute', 1],
    [1000, 'second', 1],
  ];
  for (const [size, name, least] of units) {
    if (ms < size * least) continue;
    // Only whole units read as a period; 90 minutes is not "1 hour", and
    // rounding it to one would be the same lie in a smaller font.
    if (ms % size !== 0) continue;
    return pluralise(ms / size, name);
  }
  return formatDuration(ms);
}

/* -- numbers -------------------------------------------------------------- */

const NUMBER = new Intl.NumberFormat();

/** Grouped digits. Pair with the `.tabular` class so columns line up. */
export function formatNumber(value: number | null | undefined): string {
  if (value === null || value === undefined || Number.isNaN(value)) return NO_VALUE;
  return NUMBER.format(value);
}

const BYTE_UNITS = ['B', 'KB', 'MB', 'GB', 'TB', 'PB'] as const;

/** Binary-scaled bytes: 1536 becomes "1.5 KB". */
export function formatBytes(value: number | null | undefined): string {
  if (value === null || value === undefined || Number.isNaN(value)) return NO_VALUE;
  let n = value;
  let unit = 0;
  while (Math.abs(n) >= 1024 && unit < BYTE_UNITS.length - 1) {
    n /= 1024;
    unit += 1;
  }
  const digits = unit === 0 ? 0 : Math.abs(n) < 10 ? 1 : 0;
  return `${n.toFixed(digits)} ${BYTE_UNITS[unit]}`;
}

/** Megabytes as the API reports them (`memory_mb`). */
export function formatMegabytes(value: number | null | undefined): string {
  if (value === null || value === undefined) return NO_VALUE;
  return formatBytes(value * 1024 * 1024);
}

/**
 * A ratio in the range 0..1 as a percentage. Utilisation arrives as a double,
 * so this is what every bar and tile uses.
 */
export function formatPercent(value: number | null | undefined, digits = 0): string {
  if (value === null || value === undefined || Number.isNaN(value)) return NO_VALUE;
  return `${(value * 100).toFixed(digits)}%`;
}

/** Clamp to 0..1, for anything that drives a width. */
export function ratio(value: number | null | undefined): number {
  if (value === null || value === undefined || Number.isNaN(value)) return 0;
  return Math.min(1, Math.max(0, value));
}

/* -- words ---------------------------------------------------------------- */

/** A word with its first letter in capitals, for a status or a count read aloud mid-sentence. */
export function capitalise(word: string): string {
  return word ? word.charAt(0).toUpperCase() + word.slice(1) : word;
}

/** "1 runner", "3 runners". Pass the plural when it is irregular. */
export function pluralise(count: number, one: string, many = `${one}s`): string {
  return `${formatNumber(count)} ${count === 1 ? one : many}`;
}

/** A list read aloud: "a, b and c". British serial comma rules, so none. */
export function joinWords(items: readonly string[]): string {
  if (items.length === 0) return '';
  if (items.length === 1) return items[0] ?? '';
  return `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`;
}

/** Shorten an identifier for a dense cell, keeping the prefix that means something. */
export function shortId(id: string | null | undefined, keep = 8): string {
  if (!id) return NO_VALUE;
  const underscore = id.indexOf('_');
  if (underscore > 0 && id.length > underscore + keep + 1) {
    return `${id.slice(0, underscore + 1)}${id.slice(underscore + 1, underscore + 1 + keep)}…`;
  }
  return id.length > keep * 2 ? `${id.slice(0, keep * 2)}…` : id;
}

/**
 * The words and choices for accepting a host check as deliberate.
 *
 * Route-only on purpose: health.ts is shell code under the app-shell budget, and
 * only the host page needs these sentences. Everything here describes a decision
 * recorded on the controller; none of it changes the host, and none of it implies
 * the controller ran anything there.
 */
import { relativeTime } from '../format';
import type { DoctorResult } from './health';

/**
 * How long an acceptance can run. The longest is a day short of the 365 the
 * controller allows, so that a browser whose clock is a little ahead of the
 * controller's does not turn the longest choice into a refusal.
 */
export const ACCEPT_EXPIRY_CHOICES = [
  { value: '7', label: '7 days' },
  { value: '30', label: '30 days' },
  { value: '90', label: '90 days' },
  { value: '180', label: '6 months' },
  { value: '364', label: 'A year' },
] as const;

/** An acceptance is a decision to be made again, and a year is the default for that. */
export const ACCEPT_DEFAULT_DAYS = '364';

/** When an acceptance of `days` days ends, if it is made at `now`. */
export function acceptEndsAt(days: number, now: Date): string {
  return new Date(now.getTime() + days * 24 * 60 * 60 * 1000).toISOString();
}

const DAY_MONTH = new Intl.DateTimeFormat(undefined, { day: 'numeric', month: 'short' });
const DAY_MONTH_YEAR = new Intl.DateTimeFormat(undefined, {
  day: 'numeric',
  month: 'short',
  year: 'numeric',
});

function dayOf(value: string, withYear: boolean): string {
  const ms = Date.parse(value);
  if (!Number.isFinite(ms)) return 'an unknown date';
  return (withYear ? DAY_MONTH_YEAR : DAY_MONTH).format(ms);
}

/** The end date as the toast and the note both say it: "4 Oct 2027". */
export function untilDay(value: string): string {
  return dayOf(value, true);
}

/** "Accepted by Sam 3d ago, until 4 Oct 2027: “reason”". The reason is a person's, shown as text. */
export function acceptNote(
  accepted: NonNullable<DoctorResult['accepted']>,
  now: number = Date.now(),
): string {
  return `Accepted by ${accepted.by} ${relativeTime(accepted.at, now)}, until ${dayOf(accepted.expires_at, true)}: “${accepted.reason}”`;
}

/** Why a row counts again, or null when no acceptance has ended on it. */
export function endedNote(check: Pick<DoctorResult, 'ended' | 'current'>): string | null {
  const ended = check.ended;
  if (!ended) return null;
  const on = dayOf(ended.at, false);
  switch (ended.why) {
    case 'changed':
      return `Accepted by ${ended.by} on ${on} while it read “${ended.was}”. It now reads “${check.current}”, so it counts again. Accept it again if that is deliberate.`;
    case 'expired':
      return `${ended.by}’s acceptance ended on ${on}, so it counts again.`;
    case 'worse':
      return `${ended.by}’s acceptance ended on ${on} because the check could not run, so it counts again.`;
    default:
      return null;
  }
}

/**
 * A row is accepted, or can be: a counted warning the controller marked
 * acceptable. The mark is the controller's, never the page's, so an unknown id
 * or an error never offers the button.
 */
export function canAccept(check: DoctorResult): boolean {
  return check.acceptable === true && !check.accepted;
}

/** The rows in the order the findings table shows them: unaccepted first, accepted after. */
export function acceptedLast(rows: readonly DoctorResult[]): DoctorResult[] {
  return [...rows].sort((a, b) => Number(Boolean(a.accepted)) - Number(Boolean(b.accepted)));
}

/** The ids of the accepted rows, sorted, for telling an accept or a revoke frame from a heartbeat. */
export function acceptedIds(results: readonly DoctorResult[]): string {
  return results
    .filter((r) => r.accepted)
    .map((r) => r.id)
    .sort()
    .join('\n');
}

/**
 * What an operator does to a host from more than one page.
 *
 * One function, so the Hosts card menu and the host page's Next step panel word
 * a cordon the same way and put it back the same way. The command palette still
 * cordons through its own copy: it is shell code, so importing this would move
 * these lines into the app shell, and its toast copy is different.
 */
import { cordonHost, requestHostUpdate } from '../api/client';
import type { Host } from '../api/types';
import { fleet } from '../state/fleet.svelte';
import { toasts } from '../state/toasts.svelte';

/**
 * Cordon or uncordon a host. Optimistic: the cache shows the new state at once
 * and `fleet.optimistic` puts it back, and raises the error toast, if the
 * controller refuses -- so a caller never has to catch.
 */
export async function cordon(host: Pick<Host, 'id' | 'name'>, cordoned: boolean): Promise<void> {
  if (!host.id) return;
  const id = host.id;
  const name = host.name || id;
  const result = await fleet.optimistic(
    id,
    { cordoned },
    () => cordonHost(id, { cordoned }),
    cordoned ? `${name} was not cordoned` : `${name} was not uncordoned`,
  );
  if (result === undefined) return;
  if (cordoned) {
    toasts.info(
      `${name} cordoned`,
      'Its runners keep going and finish their jobs. No new runner will be placed here.',
    );
  } else {
    toasts.success(`${name} uncordoned`, 'The scheduler may place runners here again.');
  }
}

/**
 * Ask a host's agent to update itself. Not optimistic: the card says "Updating"
 * only once the controller has recorded the attempt, because showing it first
 * would claim a request the controller may still refuse (the mode is off, the
 * host is not behind, another administrator got there first). The answer is the
 * host with the attempt on it, and goes straight into the cache.
 *
 * Returns whether the controller took the request. A refusal is reported here,
 * in the controller's words, so a caller never has to catch.
 */
export async function requestUpdate(host: Pick<Host, 'id' | 'name'>): Promise<boolean> {
  if (!host.id) return false;
  try {
    fleet.ingestHosts([await requestHostUpdate(host.id)]);
    return true;
  } catch (cause) {
    toasts.fromError(cause, `${host.name || host.id} was not asked to update`);
    return false;
  }
}

/**
 * What a host reports it can run a job in.
 *
 * The Backends block lists these, and a closed host card has to know whether
 * there is anything in them it may not fold away: an unavailable backend is the
 * reason a host takes no work, and its own explanation is in that block.
 */
import type { BackendInfo, Host } from '$lib/api/types';

/** The rich report where an agent sent one, and its plain list of kinds where that is all it sent. */
export function backendRows(
  info: readonly BackendInfo[] | undefined,
  kinds: readonly string[] | undefined,
): readonly BackendInfo[] {
  if (info && info.length > 0) return info;
  return (kinds ?? []).map((kind) => ({ kind: kind as BackendInfo['kind'] }));
}

/**
 * Whether the host has nothing to place a runner in: no backend reported, or
 * every one of them unavailable. One that works is enough. Docker without
 * Podman is how most hosts are, and the agent words that absence with the
 * commands to install it, so a card that surfaced it would carry the same
 * paragraph on every host in the fleet. An omitted `available` is how an older
 * agent says nothing is wrong, so only an explicit false counts against a row.
 */
export function backendTrouble(host: Pick<Host, 'backend_info' | 'backends'>): boolean {
  const rows = backendRows(host.backend_info, host.backends);
  return rows.length === 0 || rows.every((row) => row.available === false);
}

/**
 * Which host cards an operator has opened, remembered per browser.
 *
 * A card is closed unless its host is on this list, so a host nobody has chosen
 * for costs nothing. That stops being a short list once "Expand all" is pressed:
 * it puts every host that was on show on the list, and a host that joins later
 * is not on it, so it arrives closed. The list is written when a choice is made
 * and never on sight, for the reason the capacity map gives: a browser that had
 * merely looked would otherwise have "chosen".
 */
export const EXPANDED_KEY = 'zoomies.hosts.expanded';

/**
 * Whether a stored value is still something to trust. A value left by an older
 * build, or edited by hand, falls back to every card closed rather than
 * throwing on the first card that asks.
 */
export function isIdList(value: unknown): value is string[] {
  return Array.isArray(value) && value.every((id) => typeof id === 'string');
}

/**
 * The list after one card is opened or closed. Hosts that no longer exist are
 * dropped on the way past: machines come and go as pools scale, and without
 * this the list would keep an id for every host anyone ever opened. It returns
 * a new list and leaves the one it was given alone, because the page replaces
 * its state with the answer and an edit in place would repaint nothing.
 */
export function setExpanded(
  ids: readonly string[],
  id: string,
  open: boolean,
  known: readonly string[],
): string[] {
  const kept = ids.filter((held) => held !== id && known.includes(held));
  return open ? [...kept, id] : kept;
}

/**
 * Whether every card on show is open. No card on show is not "all open": the
 * page offers to close what it can see, and with nothing to see it has nothing
 * to offer.
 */
export function allExpanded(ids: readonly string[], shown: readonly string[]): boolean {
  return shown.length > 0 && shown.every((id) => ids.includes(id));
}

/**
 * The list after every card on show is opened or closed together. Only the
 * cards on show are asked: somebody who narrowed the page to the hosts that need
 * attention and pressed "Collapse all" has said nothing about the others, so a
 * card the filter has taken off the page keeps whatever it had. Hosts that no
 * longer exist are dropped on the way past, as setExpanded drops them, and the
 * lists it is handed are left alone.
 */
export function setAllExpanded(
  ids: readonly string[],
  shown: readonly string[],
  open: boolean,
  known: readonly string[],
): string[] {
  const kept = ids.filter((held) => known.includes(held));
  if (!open) return kept.filter((held) => !shown.includes(held));
  return [...kept, ...shown.filter((id) => known.includes(id) && !kept.includes(id))];
}

/**
 * "Check now" on the host page: what the button and the line beside it say.
 *
 * Route-only, like no-report.ts: the shell must not import this. Pure on purpose
 * -- the clock is an argument -- so every row of the state table is a line in a
 * test rather than a timing in a browser.
 *
 * Every sentence says the agent runs the checks. Nothing here may suggest that
 * the controller changes anything on a host or dials one: the request goes out on
 * the agent's own poll, and the checks only read. The gate is `host.features`,
 * which the agent sets from what it can really do, and never the report's
 * `container` flag: the host-health service of a Compose install reports
 * `container: false` and still cannot answer.
 */
import type { Host } from '$lib/api/types';

/** How long an ask goes unanswered before the line admits it is taking a while. */
export const WAITING_AFTER_MS = 5_000;
/**
 * The page's own patience for an ask it made, not a promised latency. The
 * controller gives up at 60 s; this is longer, for the one case it cannot speak
 * for: a controller restarted since the ask, which forgot it.
 */
export const CEILING_MS = 75_000;
/** How long the controller keeps an answer on the view; a ceiling failure is kept as long. */
export const KEEP_MS = 30_000;

/** The flag an agent advertises when it can run its checks on request. */
export const FEATURE = 'host-check';

export const ROLE_SENTENCE = 'Asking a host to check itself needs the operator role.';

export type CheckNowKind =
  'idle' | 'role' | 'unavailable' | 'asking' | 'waiting' | 'done' | 'cooling' | 'failed';

type HostFields = Pick<
  Host,
  'name' | 'features' | 'healthy' | 'incompatible' | 'incompatible_reason' | 'health_check'
>;

export interface CheckNowInput {
  host: HostFields;
  canOperate: boolean;
  now: number;
  /**
   * When this page pressed the button, kept after the request returns until the
   * controller shows an answer. It is what lets the page time out an ask that a
   * restarted controller forgot, which leaves nothing on the view to say so.
   */
  localAskedAt?: number | null;
  /** The request is in flight. */
  posting?: boolean;
  /** How many changes the report this check brought produced, from the page's own diff. */
  changes?: number;
  /** A press landed inside the cooldown: say how long is left instead of asking. */
  restate?: boolean;
}

export interface CheckNow {
  show: boolean;
  disabled: boolean;
  /** Why the button is off, as a sentence the page prints beside it. */
  reason?: string;
  loading: boolean;
  /** A press now would be refused for being too soon, so the page restates instead. */
  cooling: boolean;
  /** The status line. Plain text, set outside any live region. */
  status?: string;
  statusKind: CheckNowKind;
  /** What a screen reader is told, once, when the state arrives. Never the countdown. */
  announce?: string;
  /** The button's tooltip. */
  title: string;
  /** Identifies one failure, so the page toasts it once. */
  failureKey?: string;
}

export function idleTitle(name: string): string {
  return `Ask the agent on ${name} to run its read-only OS checks once and send the report. Nothing on the host is changed.`;
}

/** Why this host cannot be asked, or null when it can. Order follows the controller's refusals. */
export function unavailableReason(host: HostFields): string | null {
  const name = host.name || 'This host';
  if (host.healthy === false)
    return `${name} is not connected, so it cannot be asked. Check that its agent is running.`;
  if (host.incompatible === true)
    return (
      host.incompatible_reason ||
      `The agent on ${name} speaks a different protocol from this controller, so it cannot be asked. Update the agent.`
    );
  if (!host.features?.includes(FEATURE))
    return `The agent on ${name} cannot check on request. Agents running in a container, and agents older than this release, send their report on their own schedule instead. The last report is still shown.`;
  return null;
}

function seconds(until: number, now: number): number {
  return Math.max(1, Math.ceil((until - now) / 1000));
}

function failedMessage(name: string): string {
  return `${name} did not answer in time. Check that its agent is running; the last report is still shown.`;
}

function doneLine(name: string, outcome: string | undefined, changes: number): string {
  switch (outcome) {
    case 'first':
      return `Checked just now. This is the first report from ${name}.`;
    case 'changed':
      return changes > 0
        ? `Checked just now. ${changes} ${changes === 1 ? 'change' : 'changes'} since the last report, listed below.`
        : 'Checked just now. The report changed, but nothing that counts towards this host’s health.';
    case 'unchanged':
      return 'Checked just now. Nothing has changed since the last report.';
    case 'not_newer':
      return `${name} answered, but its clock is behind the last report, so the time did not move. Check its time settings.`;
    default:
      return 'Checked just now.';
  }
}

/**
 * Whether the host a POST answered with is older than the one the page already
 * holds. An agent that answers in a few milliseconds sends its frame before the
 * 202 arrives, and writing the 202 over it would put the old report and a
 * check that is "still asked" back on the page, for good: no later frame is
 * coming. Only the check can tell, so it is compared by when it was asked.
 */
export function superseded(current: Host['health_check'], answer: Host['health_check']): boolean {
  if (!current || !answer) return false;
  const have = Date.parse(current.asked_at);
  const got = Date.parse(answer.asked_at);
  if (!Number.isFinite(have) || !Number.isFinite(got)) return false;
  return have > got || (have === got && current.state !== 'asked' && answer.state === 'asked');
}

export function checkNow(i: CheckNowInput): CheckNow {
  const { host, now } = i;
  const name = host.name || 'This host';
  const title = idleTitle(name);
  const base: CheckNow = {
    show: true,
    disabled: false,
    loading: false,
    cooling: false,
    statusKind: 'idle',
    title,
  };
  if (!i.canOperate) return { ...base, show: false, status: ROLE_SENTENCE, statusKind: 'role' };

  const reason = unavailableReason(host);
  const off = reason === null ? {} : { disabled: true, reason };
  const hc = host.health_check;
  const local = i.localAskedAt ?? null;

  if (i.posting) {
    const line = `Asked ${name} to check itself…`;
    return { ...base, ...off, loading: true, status: line, statusKind: 'asking', announce: line };
  }

  if (hc?.state === 'asked') {
    const since = local ?? Date.parse(hc.asked_at);
    const elapsed = Number.isFinite(since) ? now - since : 0;
    if (elapsed >= CEILING_MS) {
      const message = failedMessage(name);
      return {
        ...base,
        ...off,
        status: message,
        statusKind: 'failed',
        failureKey: `asked:${hc.asked_at}`,
      };
    }
    if (elapsed >= WAITING_AFTER_MS)
      return {
        ...base,
        ...off,
        loading: true,
        status: `Still waiting for ${name} to answer. A busy host can take a little longer.`,
        statusKind: 'waiting',
      };
    const line = `Asked ${name} to check itself…`;
    return { ...base, ...off, loading: true, status: line, statusKind: 'asking', announce: line };
  }

  if (hc?.state === 'done' || hc?.state === 'failed') {
    const next = hc.next_at ? Date.parse(hc.next_at) : NaN;
    const cooling = Number.isFinite(next) && now < next;
    const failed = hc.state === 'failed';
    if (cooling && i.restate) {
      const left = seconds(next, now);
      const status = failed
        ? `${name} was asked a moment ago. You can ask again in ${left} s.`
        : `Checked just now. You can check again in ${left} s.`;
      return { ...base, ...off, cooling, status, statusKind: 'cooling' };
    }
    if (failed)
      return {
        ...base,
        ...off,
        cooling,
        status: hc.message || failedMessage(name),
        statusKind: 'failed',
        failureKey: `failed:${hc.asked_at}`,
      };
    const line = doneLine(name, hc.outcome, i.changes ?? 0);
    return {
      ...base,
      ...off,
      cooling,
      status: line,
      statusKind: 'done',
      // The count can land a beat after the frame, so the announcement leaves it out.
      announce: hc.outcome === 'changed' ? 'Checked just now. The report has changed.' : line,
    };
  }

  // Nothing on the view. A page that asked, and whose controller has since
  // forgotten the ask, would otherwise wait for ever.
  if (local !== null) {
    const elapsed = now - local;
    if (elapsed >= CEILING_MS) {
      if (elapsed >= CEILING_MS + KEEP_MS) return { ...base, ...off };
      return {
        ...base,
        ...off,
        status: failedMessage(name),
        statusKind: 'failed',
        failureKey: `local:${local}`,
      };
    }
    if (elapsed >= WAITING_AFTER_MS)
      return {
        ...base,
        ...off,
        loading: true,
        status: `Still waiting for ${name} to answer. A busy host can take a little longer.`,
        statusKind: 'waiting',
      };
    const line = `Asked ${name} to check itself…`;
    return { ...base, ...off, loading: true, status: line, statusKind: 'asking', announce: line };
  }

  return reason === null ? base : { ...base, ...off, statusKind: 'unavailable' };
}

/**
 * What a closed host card says about the CPU and memory its runners have
 * already promised away.
 *
 * The Committed bars are detail and stay behind Details. What they explain is
 * not: a host whose idle runners have reserved all its allocatable memory takes
 * nothing, yet its slot line counts slots only ("2 of 8 slots in use · 6 free")
 * and the Memory bar beside it is usage, not reservations. Folded, nothing on
 * the card says why the free slots stay empty, which is the one thing the card
 * exists to say.
 *
 * Route-only, like vitals.ts: the host card and its Committed bars are the only
 * callers.
 */

/**
 * The share of what may be placed that is already promised, from which the next
 * runner is the one that may not fit. ResourceBar draws its bar and figure amber
 * from the same line, so the bars and the sentence can never disagree about it.
 */
export const COMMITTED_TIGHT = 0.9;

/** One resource's row of the Committed block, as the card builds it from the host. */
export interface CommittedRow {
  /** "CPU" or "Memory". */
  label: string;
  /** What the live runners have promised away. */
  used: number;
  /** What the scheduler may place onto: the machine less its reserve. */
  total: number;
  /** The two figures as the block prints them: "8 of 14.2", "19.5 GB of 29.4 GB". */
  text: string;
}

/** Whether a resource is close enough to fully promised to be worth a sentence. */
export function isCommittedTight(row: Pick<CommittedRow, 'used' | 'total'>): boolean {
  return row.total > 0 && row.used / row.total >= COMMITTED_TIGHT;
}

/**
 * The sentence for a host whose free slots a nearly promised resource may leave
 * empty, or an empty string where there is nothing to explain.
 *
 * It needs a free slot to be about anything. A full host has everything
 * promised away by design, so without that condition the sentence would be on
 * every busy card and explain none of them: the slot line already says why a
 * host with no slot left takes nothing.
 */
export function committedNotice(rows: readonly CommittedRow[] | null, free: number): string {
  if (!rows || free <= 0) return '';
  const tight = rows.filter(isCommittedTight);
  if (tight.length === 0) return '';
  const named = tight.map(
    (row) => `${row.label === 'CPU' ? row.label : row.label.toLowerCase()} ${row.text}`,
  );
  return `Committed to runners already: ${named.join(', ')}. A free slot here may not take another runner until one finishes.`;
}

import type { Host } from '$lib/api/types';

/** The sentence around a relative time: the markup puts the time between `lead` and `tail`. */
export interface Freshness {
  lead: string;
  tail: string;
  /** `checked_at` is after the page's clock; print "just now", never "in 5s". */
  future: boolean;
}

/**
 * How old the report on the page is, and what that means, with no number for how
 * often a newer one arrives. The page cannot see the agent's heartbeat interval
 * and the monitor's period is derived rather than measured, so a figure here would
 * be a guess that read as a promise. `stale` comes from `healthSummary`, which owns
 * the threshold, so the header and the pill cannot disagree about it.
 *
 * Null when there is no report to date, which the no-report copy already covers.
 */
export function freshness(i: {
  report?: Host['doctor'];
  healthy: boolean;
  stale: boolean;
  now: number;
}): Freshness | null {
  const { report } = i;
  if (!report || !report.summary) return null;
  const checked = Date.parse(report.checked_at);
  if (!Number.isFinite(checked)) return null;
  const future = checked > i.now;
  if (!i.healthy)
    return {
      lead: 'Last report checked',
      tail: '. The agent is not connected, so nothing newer can arrive until it is.',
      future,
    };
  if (i.stale)
    return {
      lead: 'Last report checked',
      tail: '. The agent is connected but has sent nothing newer.',
      future,
    };
  if (report.container)
    return {
      lead: 'Report checked',
      tail: ', from inside the container. This page updates by itself when a newer one arrives.',
      future,
    };
  return {
    lead: 'Report checked',
    tail: '. This page updates by itself when the agent sends a newer one.',
    future,
  };
}

/**
 * The one line a host card says about the checks that need attention, and the
 * address the health pill takes you to.
 *
 * Route-only on purpose: health.ts is shell code (the feed reads it), and the
 * card is the only caller, so none of this belongs in the app shell's budget.
 */
import type { Host } from '$lib/api/types';
import { attention, type HealthSummary } from './health';

export interface CardLine {
  /** Empty when the card has nothing honest to name. */
  text: string;
  /** The first check named, which the host page scrolls to; null when there is none. */
  firstId: string | null;
  href: string;
}

/** A title is written by the host, up to 200 characters; a card has room for a phrase. */
const TITLE_LIMIT = 40;

function clip(title: string): string {
  const chars = [...title.trim()];
  return chars.length > TITLE_LIMIT
    ? `${chars.slice(0, TITLE_LIMIT - 1).join('')}…`
    : chars.join('');
}

/**
 * Names the worst checks, in the order Needs attention lists them.
 *
 * Empty for a stale report, a container and a reboot-only report: a stale
 * report must never list last-known checks as if they were current, and the
 * pill's own label already says the state. Never "findings": the glossary
 * keeps that word for the controller's own problems.
 */
export function cardLine(
  host: Pick<Host, 'id' | 'doctor'>,
  health: Pick<HealthSummary, 'stale'>,
): CardLine {
  const plain: CardLine = { text: '', firstId: null, href: `/hosts/${host.id}` };
  if (!host.doctor || health.stale) return plain;
  const list = attention(host.doctor);
  const first = list[0];
  if (!first) return plain;
  const [a, b] = list.map((r) => clip(r.title || r.id));
  const text =
    list.length === 1
      ? `${a}`
      : list.length === 2
        ? `${a} and ${b}`
        : `${a}, ${b} and ${list.length - 2} more`;
  const firstId = first.id;
  return { text, firstId, href: `/hosts/${host.id}#${encodeURIComponent(firstId)}` };
}

/** -- keep in step with diskCheck in internal/hosttune/checks.go */
export const DISK_LOW_PERCENT = 10;
/** -- keep in step with diskCheck in internal/hosttune/checks.go (10 GiB, in MiB) */
export const DISK_LOW_FLOOR_MB = 10 * 1024;

/**
 * Whether the card should call the disk low: the rule the Work directory free
 * space check warns by, so the amber figure and the Warning row never disagree.
 *
 * Strictly less than on both limbs, as the check is, so exactly 10% or exactly
 * 10 GiB free is not low. Zero total means the agent did not measure it.
 */
export function diskIsLow(freeMb: number, totalMb: number): boolean {
  if (!(totalMb > 0)) return false;
  return (freeMb * 100) / totalMb < DISK_LOW_PERCENT || freeMb < DISK_LOW_FLOOR_MB;
}

/**
 * Where the card's disk figure leads: the check that reads the same filesystem.
 *
 * Null when there is no honest destination -- no report, a container's partial
 * view, a stale report, or a report without the check -- so the figure stays
 * plain text rather than linking to a row that is not there.
 */
export function diskLink(
  host: Pick<Host, 'id' | 'doctor'>,
  health: Pick<HealthSummary, 'stale'>,
): string | null {
  const report = host.doctor;
  if (!host.id || !report || report.container || health.stale) return null;
  if (!report.results.some((r) => r.id === 'disk.space')) return null;
  return `/hosts/${encodeURIComponent(host.id)}#disk.space`;
}

/**
 * Which hosts the Hosts page's filter row holds, and how many there are in each.
 *
 * Route-only, and a module of its own rather than more of health.ts: that file
 * is in the app shell (the feed imports from it), so anything added there spends
 * shell bytes that only this page would use.
 *
 * The pill on each card is the one authority on a host's health, and the filter
 * asks it. `healthBucket` calls `healthSummary` exactly as the card does, so the
 * count on the "Need attention" tile, the chip and the pills can never disagree.
 * Three things follow from that, and each is said where it shows:
 *
 *  - The three buckets are exclusive and do not add up to All. A host with a
 *    clean report, a partial report or "Checks unavailable" is in none of them,
 *    because its pill says nothing is wrong and nothing is missing.
 *  - A host whose agent is not connected is "Report stale" even with a fresh
 *    report, because its pill reads "Last known report". A stale host that is
 *    also waiting for a reboot is stale rather than attention, because its pill
 *    is neutral and never says "reboot pending".
 *  - The page goes stale at three minutes, where the controller's own
 *    `host.health_stale` problem waits ten, so a count here can be higher than
 *    the problems list for a few minutes. The pill is what the card shows, and
 *    the count follows the card.
 */
import type { Host } from '$lib/api/types';
import { pluralise } from '../format';
import { healthSummary } from './health';

export const HEALTH_FILTERS = [
  { value: 'all', label: 'All', title: 'Every host.', note: '' },
  {
    value: 'attention',
    label: 'Need attention',
    title:
      'OS settings below the recommendation, or a reboot pending. The same hosts whose health pill says warnings, errors or a reboot.',
    note: 'OS settings below the recommendation, or a reboot pending.',
  },
  {
    value: 'stale',
    label: 'Report stale',
    title:
      'No OS report in the last three minutes, or the agent is not connected. What the host last reported may still be true.',
    note: 'no OS report in the last three minutes, or the agent is not connected.',
  },
  {
    value: 'no-report',
    label: 'No report',
    title: 'No OS report has arrived from this host’s agent yet.',
    note: 'no OS report has arrived from the agent yet.',
  },
] as const;

export type HealthFilter = (typeof HEALTH_FILTERS)[number]['value'];
export type HealthBucket = Exclude<HealthFilter, 'all'>;
export type HealthCounts = Record<HealthFilter, number>;

/** What the pill reads, and nothing else of the host. */
type Judged = Pick<Host, 'doctor' | 'healthy'>;

/**
 * The filter a query value names. Exact matches only: an address somebody
 * typed or an older bookmark that names nothing here shows every host, which is
 * what no filter means, rather than an empty page that looks like good news.
 */
export function healthFilterFrom(raw: string): HealthFilter {
  return HEALTH_FILTERS.find((option) => option.value === raw)?.value ?? 'all';
}

/**
 * The one bucket a host is in, or null when its pill has nothing to say about
 * it: Health OK, Partial report and Checks unavailable.
 */
export function healthBucket(host: Judged, now: number): HealthBucket | null {
  // "Health unavailable": no report, or one that arrived without the
  // controller's count of it. Asked first, because healthSummary also calls a
  // missing report stale and would put it in the wrong bucket.
  if (!host.doctor?.summary) return 'no-report';
  const { stale, tone } = healthSummary(host.doctor, now, host.healthy);
  // Unreachable, an unreadable time, or older than three minutes.
  if (stale) return 'stale';
  return tone === 'danger' || tone === 'pending' ? 'attention' : null;
}

export function healthCounts(hosts: readonly Judged[], now: number): HealthCounts {
  const counts: HealthCounts = { all: hosts.length, attention: 0, stale: 0, 'no-report': 0 };
  for (const host of hosts) {
    const bucket = healthBucket(host, now);
    if (bucket) counts[bucket] += 1;
  }
  return counts;
}

/** The hosts a filter shows. With All it is the same array, so nothing downstream re-renders for it. */
export function hostsFor<T extends Judged>(
  hosts: readonly T[],
  filter: HealthFilter,
  now: number,
): readonly T[] {
  if (filter === 'all') return hosts;
  return hosts.filter((host) => healthBucket(host, now) === filter);
}

/** The line under the chips while a filter is on, or nothing for All. Written for a screen reader as much as for the eye. */
export function filterSentence(filter: HealthFilter, shown: number, total: number): string {
  const note = HEALTH_FILTERS.find((option) => option.value === filter)?.note ?? '';
  return note === '' ? '' : `Showing ${shown} of ${pluralise(total, 'host')}: ${note}`;
}

/**
 * What the "Need attention" tile says under its number.
 *
 * Zero beside hosts that have said nothing is not a clean bill of health, and a
 * tile that read "0" with the usual line under it would be the false calm the
 * filter exists to avoid. So at zero it says how many have no current report.
 */
export function attentionDetail(counts: HealthCounts): string {
  const silent = counts.stale + counts['no-report'];
  if (counts.attention === 0 && silent > 0) return `${silent} without a current OS report`;
  return 'OS settings below the recommendation, or a reboot pending';
}

/** What the page says when a filter matches nothing. */
export function emptyCopy(
  filter: HealthBucket,
  counts: HealthCounts,
): { title: string; description: string } {
  const silent = counts.stale + counts['no-report'];
  const has = (n: number) => (n === 1 ? 'has' : 'have');
  if (filter === 'attention') {
    return {
      title: 'No host needs attention',
      description:
        'Every host with a current report is within what Zoomies recommends, and none is waiting for a reboot.' +
        (silent > 0
          ? ` ${pluralise(silent, 'host')} ${has(silent)} no current report, so nothing is known about ${silent === 1 ? 'it' : 'them'} yet.`
          : ''),
    };
  }
  if (filter === 'stale') {
    const none = counts['no-report'];
    return {
      title: 'No stale reports',
      description:
        'Every OS report that has arrived is less than three minutes old, and every host that sent one is connected.' +
        (none > 0 ? ` ${pluralise(none, 'host')} ${has(none)} not reported at all.` : ''),
    };
  }
  return {
    title: 'Every host has reported',
    description:
      'Each host has sent at least one OS report. A host that never does is an agent from before OS reports, or one that has only just joined.',
  };
}

import type { Host } from '$lib/api/types';
import type { StatusTone } from '$lib/status';
import { pluralise } from '../format';
export type DoctorReport = NonNullable<Host['doctor']>;
export type DoctorResult = DoctorReport['results'][number];

/**
 * Whether a result counts towards a host's health: the safe tier, and not an
 * optional suggestion.
 *
 * That is what `zoomies doctor` counts by default. The monitor reports every
 * tier, and the aggressive and dedicated ones are choices an operator opts into
 * (docs/host-health.md) -- a stock Ubuntu host has swappiness at 60 and a /tmp
 * that is not tmpfs from its first minute -- so counting them here put "9
 * warnings" on a host whose every safe check passed, and a number that
 * disagreed with the command the page tells the operator to run.
 */
export function counts(result: DoctorResult): boolean {
  return result.tier === 'safe' && result.optional !== true;
}

export function isFinding(result: DoctorResult): boolean {
  return result.status === 'warn' || result.status === 'error';
}

const RANK: Record<DoctorResult['status'], number> = { error: 0, warn: 1, ok: 2, skip: 3 };

/** Worst first. The sort is stable, so within a rank the engine's own order holds. */
export function bySeverity(results: readonly DoctorResult[]): DoctorResult[] {
  return [...results].sort((a, b) => RANK[a.status] - RANK[b.status]);
}

/**
 * The check whose warning is the reboot flag. The agent sets `reboot_pending`
 * from it, so the one fact arrives twice in a report; the controller counts it
 * once, as the reboot, and so does this list. Must match hosttune.KernelPending.
 */
export const KERNEL_PENDING = 'kernel.pending';

/**
 * What needs doing: the counted warnings and errors, errors first, and never
 * the kernel.pending warning of a report that already says a reboot is pending.
 *
 * Its length is `summary.warnings + summary.errors`, the controller's own count,
 * and the host-health spec checks that against a real controller -- this is the
 * one place the rule is written a second time, so it is where the two would
 * drift.
 *
 * Nor an accepted warning: an operator decided it is deliberate, and the
 * controller stops counting it (hosttune.Summary), so this list must drop it too
 * or its length would stop being `warnings + errors`. The row stays in the
 * tables below, with its badge and its reason.
 *
 * Empty for a container's partial report. The pill calls that report no verdict
 * and the controller raises nothing for it, so a list of what "needs attention"
 * on the same page would contradict both -- and its one warning, the image's own
 * distribution, is one nobody can clear. The rows stay in the tables below.
 */
export function attention(report: DoctorReport): DoctorResult[] {
  if (report.container) return [];
  return bySeverity(
    report.results.filter(
      (r) =>
        counts(r) &&
        isFinding(r) &&
        !r.accepted &&
        !(report.reboot_pending && r.id === KERNEL_PENDING && r.status === 'warn'),
    ),
  );
}

/**
 * The counted findings in words, errors first: "1 health error · 2 warnings".
 * Empty when there are none. The pill and the feed both say it this way, so a
 * line in the feed and the badge it came from read alike.
 */
export function findingsLabel(found: { errors: number; warnings: number }): string {
  const parts: string[] = [];
  if (found.errors) parts.push(pluralise(found.errors, 'health error'));
  if (found.warnings) parts.push(pluralise(found.warnings, 'warning'));
  return parts.join(' · ');
}

export interface HealthSummary {
  label: string;
  tone: StatusTone;
  hint: string;
  stale: boolean;
  errors: number;
  warnings: number;
  skipped: number;
  /** Warnings that do not count: other tiers, and anything optional. */
  suggestions: number;
  /** Counted warnings an operator accepted as deliberate. Zero from a controller that predates it. */
  accepted: number;
}

/**
 * The badge for one host, read from the controller's own count (`summary`).
 *
 * The count is not worked out here: the problems, the metrics, the feed and
 * `zoomies hosts list` read the same six numbers, and a pill that tallied the
 * results itself would be the one surface that could disagree with them. What
 * stays here is what only a browser knows -- the clock the report is judged
 * against -- and the wording.
 */
export function healthSummary(
  report: Host['doctor'],
  now: number,
  reachable = true,
): HealthSummary {
  const empty = { errors: 0, warnings: 0, skipped: 0, suggestions: 0, accepted: 0 };
  if (!report)
    return {
      label: 'Health unavailable',
      tone: 'neutral',
      hint: 'No OS report has arrived from this host yet.',
      stale: true,
      ...empty,
    };
  // A controller older than this page sends the report without its count.
  // Counting the results here instead would put a second opinion on the screen,
  // so the page says what it does not know.
  const summary = report.summary;
  if (!summary)
    return {
      label: 'Health unavailable',
      tone: 'neutral',
      hint: 'This host’s OS report arrived without the controller’s count of it, so no verdict is shown. Reload the page; if this stays, the controller is older than the page.',
      stale: true,
      ...empty,
    };
  const checked = Date.parse(report.checked_at);
  const dated = Number.isFinite(checked);
  const stale = !reachable || !dated || now - checked > 3 * 60_000;
  const { errors, warnings, skipped, suggestions } = summary;
  const accepted = summary.accepted ?? 0;
  const tally = { errors, warnings, skipped, suggestions, accepted };
  // Old and gone are different problems with different fixes, so the page says
  // which: a host that is not connected has nothing newer to send, while a
  // connected one has an agent or a clock that needs a person. The label never
  // asserts a reboot either, because the flag may have cleared since; the hint
  // says it was pending and the report's own rows stay in Needs attention.
  const staleNote = !stale
    ? ''
    : !reachable
      ? ' The agent is not connected, so this is the last report it sent, not the host’s state now. No runner is placed here until it reconnects.'
      : ` The agent is connected, but its last OS report ${dated ? 'is more than three minutes old' : 'could not be dated'}. On the host, restart the agent (sudo systemctl restart zoomies-agent) and check its clock (timedatectl).`;
  // A container's report is the container's view, not the host's: most checks
  // are skipped and the image's distribution warns for ever. The controller
  // raises nothing for it, so neither does the pill, and the counts are left
  // out of the hint rather than offered as a verdict.
  const partial = report.container === true;
  // A partial report's reboot flag is no more a verdict than its checks are.
  const reboot = report.reboot_pending && !partial;
  const rebootNote = reboot && stale ? ' That report said a reboot was pending.' : '';
  const hint = partial
    ? 'Partial report from the container. It can see only what the container can, so Zoomies draws no conclusion from it and raises no problem for it. The native host health service supplies the full OS report.' +
      staleNote
    : 'Host OS report from the native Zoomies binary. ' +
      `${pluralise(warnings, 'warning')}, ${pluralise(errors, 'error')}, ` +
      `${pluralise(skipped, 'skipped check')}.` +
      (suggestions
        ? ` Also ${pluralise(suggestions, 'optional suggestion')}, which do not count towards health.`
        : '') +
      (accepted
        ? ` Also ${pluralise(accepted, 'accepted check')}, which do not count towards health.`
        : '') +
      rebootNote +
      staleNote;
  if (stale)
    return {
      label: reachable ? 'Report stale' : 'Last known report',
      tone: 'neutral',
      hint,
      stale,
      ...tally,
    };
  if (partial) return { label: 'Partial report', tone: 'neutral', hint, stale, ...tally };
  // Half or more skipped cannot vouch for the host. A healthy Linux host skips
  // 1-5 of the 14 counted checks (kernel.hwe off Ubuntu 24.04, docker.* with the
  // daemon down, no unit), so the trip point is 7; revisit it when the catalogue
  // changes.
  const mostlySkipped = skipped * 2 >= summary.counted;
  const couldNotRun = ` ${skipped} of ${summary.counted} checks could not run.`;
  // Worst first, and every state that applies is said: a reboot used to return
  // before the errors were read, so a full disk showed as an amber "Reboot
  // pending" and the danger tone could not be reached at all.
  const label = [findingsLabel(tally), reboot ? 'reboot pending' : ''].filter(Boolean).join(' · ');
  if (label)
    return {
      label: label.charAt(0).toUpperCase() + label.slice(1),
      tone: errors ? 'danger' : 'pending',
      hint: mostlySkipped ? hint + couldNotRun : hint,
      stale,
      ...tally,
    };
  if (skipped === summary.counted) {
    const env = report.results.find((r) => r.id === 'environment');
    return {
      label: 'Checks unavailable',
      tone: 'neutral',
      hint:
        env?.status === 'skip'
          ? `Zoomies checks Linux hosts only; this host reports ${env.current || report.os || 'another system'}. ` +
            hint
          : hint,
      stale,
      ...tally,
    };
  }
  if (mostlySkipped)
    return {
      label: 'Partial report',
      tone: 'neutral',
      hint:
        hint +
        `${couldNotRun} So “no warnings” covers only the others. A stopped Docker daemon or an unreadable work directory skips several at once.`,
      stale,
      ...tally,
    };
  return { label: 'Health OK', tone: 'idle', hint, stale, ...tally };
}

/**
 * What the host page says a person should do about the host in front of them,
 * and whether it is safe to reboot it.
 *
 * Pure, so the words and the order they are chosen in can be tested without a
 * browser. Route-only: the app shell must not import this (the shell has a byte
 * budget, and only the host page needs it).
 *
 * Two rules shape every sentence. Zoomies never runs a command on a host and
 * never reboots one, so the page offers the one thing the controller can do --
 * cordon, which is a scheduling decision and touches nothing on the machine --
 * and a command for a person to run themselves. And a runner count is not a job
 * count: a runner kept warm for a pool waits for work and never finishes by
 * itself, so "none" can be said but "they will finish" cannot.
 *
 * The word for holding work back is cordon, never drain. Drain cordons the host
 * and then stops a runner that is still busy after five minutes, which is the
 * wrong advice for waiting for jobs to finish; the controller's own fix text for
 * a pending reboot (host_health_problems.go) makes the same choice.
 */
import type { Host } from '$lib/api/types';
import { pluralise } from '../format';
import { attention, type DoctorReport } from './health';
import { reportOnly } from './report-only';

/**
 * The one command the panel offers. Never built from the host's name or
 * address: those are written by the agent, so a name with a newline in it could
 * otherwise put a second command on somebody's clipboard.
 */
export const DOCTOR_COMMAND = 'sudo zoomies doctor --interactive';

type Subject = Pick<Host, 'id' | 'name' | 'address' | 'embedded' | 'healthy' | 'active_runners'>;

/**
 * What can be said about rebooting. `cordoned` is the verdict for a host that
 * is cordoned with nothing waiting on it: it gives no reboot advice at all, only
 * the way back to taking work.
 */
export type Verdict = 'unknown' | 'busy' | 'idle' | 'safe' | 'cordoned';

export interface NextStepInput {
  host: Subject;
  report: DoctorReport | undefined;
  /**
   * The cordon state the controller has CONFIRMED. The page passes the value
   * from before the click while a request is in flight: the cache already
   * shows the optimistic one, and "safe to reboot" must not be said on the
   * strength of a request nobody has heard back from.
   */
  cordoned: boolean;
}

export interface NextStep {
  verdict: Verdict;
  /** The sentence a screen reader hears. It carries no count, so it changes only when the state does. */
  headline: string;
  detail: string;
  /** 'Not reported', 'None', '1 runner', '3 runners'. */
  runners: string;
  /** 'Taking new work' or 'Cordoned: no new runner is placed here'. */
  placement: string;
  cordoned: boolean;
  button: { label: 'Cordon this host' | 'Uncordon this host'; help: string };
  /** The caption above the command; null when there is nothing to run. */
  where: string | null;
  embeddedNote: string | null;
}

/**
 * A reboot the pill and the controller both call one. A container's report is
 * the container's view, so its flag is no verdict (health.ts, and the
 * controller's hostHealthReport returns nothing for it).
 */
export function rebootPending(report: DoctorReport | undefined): boolean {
  return report !== undefined && !report.container && report.reboot_pending === true;
}

/**
 * The panel for a host, or null when there is nothing to say.
 *
 * It is wanted for two reasons: the host has a counted finding or is waiting
 * for a reboot (a full report only), or it is cordoned. The second is what keeps
 * an Uncordon button on the page of a host that has been rebooted and is clean:
 * a cordon is easy to forget, and the host would sit there taking no work.
 */
export function nextStep(input: NextStepInput): NextStep | null {
  const { host, report, cordoned } = input;
  const reboot = rebootPending(report);
  // On a report-only distribution the `environment` warning is the report
  // saying so, and nothing an operator can fix, so it alone is not a reason to
  // put a panel on the page. It stays in Needs attention: the controller counts it.
  const kind = reportOnly(report);
  const waiting =
    reboot ||
    (report !== undefined &&
      attention(report).some((r) => !(kind === 'distro' && r.id === 'environment')));
  if (!waiting && !cordoned) return null;

  const name = host.name || host.id || 'this host';
  const count = host.active_runners;
  const base = {
    runners:
      count === undefined ? 'Not reported' : count === 0 ? 'None' : pluralise(count, 'runner'),
    placement: cordoned ? 'Cordoned: no new runner is placed here' : 'Taking new work',
    cordoned,
    button: cordoned
      ? {
          label: 'Uncordon this host' as const,
          help: `Uncordoning lets the scheduler place runners on ${name} again.`,
        }
      : {
          label: 'Cordon this host' as const,
          help: `Cordoning stops new runners being placed on ${name}. It does not stop or reboot anything: runners already there carry on.`,
        },
    embeddedNote: host.embedded
      ? `${name} runs inside the controller, so rebooting it takes Zoomies offline until it is back.`
      : null,
  };

  // Nothing to run and nothing to reboot, so no advice about either: this is
  // the host that was cordoned for a reboot, came back clean, and is still
  // cordoned. It is judged before the others because it is true whatever the
  // report is -- none, a container's, or one from a host that has gone quiet.
  if (!waiting) {
    return {
      ...base,
      verdict: 'cordoned',
      headline: `${name} is cordoned and nothing is waiting on it`,
      detail: 'Uncordon it so that it takes work again.',
      where: null,
    };
  }

  // `zoomies doctor --interactive` offers fixes that do not exist for a
  // distribution or container that cannot be tuned, so no command is offered;
  // the cordon and the reboot advice are about scheduling and stay.
  const where =
    kind === 'distro' || kind === 'container'
      ? null
      : host.embedded
        ? `Run this on the controller's own machine (${name}), in a shell there:`
        : `Run this on ${name}${host.address ? ` (${host.address})` : ''}, in a shell on that machine:`;
  const rebootLine = 'Zoomies never reboots a host itself.';

  // A host nobody can hear has a runner count that is the last one recorded,
  // and that is the least safe number to reboot on.
  if (host.healthy !== true || count === undefined) {
    return {
      ...base,
      verdict: 'unknown',
      headline: 'Check before rebooting',
      detail:
        host.healthy !== true
          ? `${name} is not connected, so the runner count and cordon state below are the last the controller recorded. Look at its runners before rebooting it.`
          : `The controller has not said how many runners are on ${name}. Look at its runners before rebooting it.`,
      where,
    };
  }
  if (count > 0) {
    const place = cordoned
      ? 'It is cordoned, so no new runner is placed here.'
      : 'New runners can still be placed here; cordon it to stop them.';
    const warm =
      'A runner kept warm for a pool waits for work and never finishes by itself, so this count cannot say whether any of them is running a job.';
    const tail = reboot ? ` Reboot ${name} when none is, then uncordon it. ${rebootLine}` : '';
    return {
      ...base,
      verdict: 'busy',
      headline: `Runners are still on ${name}`,
      detail: `${place} ${warm}${tail}`,
      where,
    };
  }
  if (cordoned) {
    return {
      ...base,
      verdict: 'safe',
      headline: 'Idle and cordoned: safe to reboot now',
      detail: reboot
        ? `Reboot ${name} yourself, then uncordon it so it takes work again. ${rebootLine}`
        : `Nothing is running on ${name} and nothing new will be placed there. If you do reboot it, uncordon it afterwards so it takes work again. ${rebootLine}`,
      where,
    };
  }
  return {
    ...base,
    verdict: 'idle',
    headline: `Nothing is running on ${name} right now`,
    detail: reboot
      ? `It can be rebooted now. Cordon it first so that a job cannot land on it in the meantime, and uncordon it afterwards. ${rebootLine}`
      : 'Cordon it first if you want to make changes without a job landing on it.',
    where,
  };
}

/**
 * What a viewer, who cannot cordon, is told in the host report instead of the
 * panel. It names the role they lack, so that a refusal has somewhere to go.
 */
export function rebootAdvice(): string {
  return 'A reboot is pending. Cordon the host so that no job lands on it, reboot it yourself once none of its runners is running a job, then uncordon it. Cordoning needs the operator role. Zoomies never reboots a host itself.';
}

/**
 * Why a host has no OS report, and what a person can do about it.
 *
 * Route-only, like report-only.ts: health.ts is shell code, so the sentences only
 * the host page needs live here. Pure on purpose -- the clock is an argument --
 * so every cause is a table row in a test rather than a timing in a browser.
 *
 * The page used to give one answer to five different situations, and half of it
 * was wrong for a container deployment. Each cause here is told apart from fields
 * the page already has; where the page cannot tell, it says so and offers a
 * read-only command rather than guessing.
 */
import type { Host } from '$lib/api/types';

/**
 * How long a new host is given before silence reads as a fault. The first check
 * waits for a heartbeat, and the page cannot see the agent's interval, so this
 * is generous on purpose and never shown to a person as a promise.
 */
export const FIRST_REPORT_GRACE_MS = 5 * 60_000;

/**
 * Read-only on purpose: next-step.ts's DOCTOR_COMMAND offers fixes, and a person
 * who is only trying to learn why there is no report should not be handed one.
 * Never interpolated with anything.
 */
export const READ_ONLY_DOCTOR_COMMAND = 'sudo zoomies doctor';

export type NoReportKind =
  'disconnected' | 'release' | 'joining' | 'embedded' | 'no-release' | 'unknown';

export interface NoReport {
  kind: NoReportKind;
  /** The panel's description: one sentence. */
  description: string;
  detail: string;
  /** The controller's own words about the upgrade, passed through. */
  note: string | null;
  /** host.upgrade_command byte for byte, or the read-only constant, or nothing. */
  command: string | null;
  commandCaption: string | null;
  copyLabel: 'Copy the upgrade command' | 'Copy command' | null;
  /** A sentence under the command block. */
  after: string | null;
  /** Which RelativeTime sentence the markup appends, if any. */
  tail: 'heartbeat' | 'joined' | 'joined-late' | 'since-joined' | null;
}

type HostFields = Pick<
  Host,
  | 'healthy'
  | 'version'
  | 'version_skew'
  | 'upgrade_command'
  | 'upgrade_note'
  | 'embedded'
  | 'machine_id'
  | 'created_at'
  | 'last_heartbeat'
>;

const NONE = { note: null, command: null, commandCaption: null, copyLabel: null, after: null };

function joinedRecently(created: string | undefined, now: number): boolean {
  const at = created ? Date.parse(created) : NaN;
  // An unparseable date is not recent: guessing "just joined" would hide a real fault.
  return Number.isFinite(at) && now - at < FIRST_REPORT_GRACE_MS;
}

/**
 * First match wins, and the order matters. Skew precedes the grace period
 * because an old agent never reports however new its row is; the embedded case
 * follows it because created_at is the row's first start only.
 */
export function noReport(i: { host: HostFields; now: number; canOperate: boolean }): NoReport {
  const { host, now, canOperate } = i;

  if (host.healthy === false) {
    return {
      ...NONE,
      kind: 'disconnected',
      description: 'This host is not connected, so no report can reach the controller.',
      detail:
        'Reports travel with the agent’s heartbeat. Check that the agent is running on that machine and can reach this controller; there is nothing to read until it is back.',
      tail: host.last_heartbeat ? 'heartbeat' : null,
    };
  }

  if (host.version_skew === 'behind' || host.version_skew === 'differs') {
    const description =
      host.version_skew === 'behind'
        ? 'This agent is an earlier release than the controller, and may be too old to send OS reports.'
        : 'This agent is a different build from the controller’s, and may be too old to send OS reports.';
    const tail: NoReport['tail'] = joinedRecently(host.created_at, now) ? 'joined-late' : null;
    const base = { kind: 'release' as const, description, tail };
    if (!canOperate) {
      // A machine Zoomies rents is not updated on the host, by anybody: its
      // agent is the one its provider's template carried, and the way to a
      // newer one is that template.
      if (host.machine_id) {
        return {
          ...NONE,
          ...base,
          detail:
            'This is a machine Zoomies rents, cloned from its provider’s template, so its agent is the one that image carried. Ask an administrator to prepare that template again from the controller’s release: the machines built afterwards carry it, and this one is replaced as it goes idle.',
        };
      }
      return {
        ...NONE,
        ...base,
        detail:
          'An agent is updated by an administrator, who can press Update on its host card where the update helper is installed, by an operator, who can run its upgrade command on the host, or by Zoomies itself where the helper is installed, while updates.mode is auto. Ask an administrator or an operator to update this host’s agent.',
      };
    }
    if (host.upgrade_command && !host.embedded) {
      return {
        ...base,
        detail:
          'A release from before OS reports were added cannot send one, so updating it is the first thing to try.',
        note: host.upgrade_note || null,
        command: host.upgrade_command,
        commandCaption: 'Run this on the host:',
        copyLabel: 'Copy the upgrade command',
        after:
          'Running runner containers stay in place. This page fills in by itself once the agent restarts and reports. Once the update helper is installed on the host, Zoomies updates the agent itself when an administrator presses Update on the host’s card or starts a rollout from the Hosts page, and by itself while updates.mode is auto.',
      };
    }
    return {
      ...NONE,
      ...base,
      detail: host.upgrade_note || 'Zoomies has no command to offer for this build.',
    };
  }

  if (joinedRecently(host.created_at, now)) {
    return {
      ...NONE,
      kind: 'joining',
      description: 'Waiting for this host’s first report.',
      detail:
        'An agent sends its first OS report shortly after it starts. This page fills in by itself when it arrives.',
      tail: 'joined',
    };
  }

  if (host.embedded) {
    return {
      ...NONE,
      kind: 'embedded',
      description: 'This is the controller’s own agent, and it has not sent a report.',
      detail:
        'It checks itself from the moment the controller starts, so a report should be here by now. It is the same program as the controller, so updating it cannot help. Zoomies cannot tell why from this page.',
      tail: null,
    };
  }

  if (!host.version) {
    return {
      ...NONE,
      kind: 'no-release',
      description:
        'This agent has not said which release it is, so Zoomies cannot tell whether it is new enough to send OS reports.',
      // No command, deliberately: an unversioned upgrade could move an agent past its controller.
      detail: `An agent from before OS reports cannot send one. Update it the way it was installed; Zoomies has no command to offer because it does not know which release to give it.${canOperate ? '' : ' Ask an operator to update it.'}`,
      tail: null,
    };
  }

  return {
    kind: 'unknown',
    description:
      'This agent reports the same release as the controller, or a later one, and has still not sent a report.',
    detail:
      'Zoomies cannot tell why from this page, and two builds can share a release name, so an older agent is still possible. On the host, run the command below to see whether its checks run at all.',
    note: null,
    command: READ_ONLY_DOCTOR_COMMAND,
    commandCaption: 'Run this on the host:',
    copyLabel: 'Copy command',
    after: 'It makes no change. Zoomies never runs it for you.',
    tail: 'since-joined',
  };
}

export function noReportSubtitle(): string {
  return 'No OS report has arrived from this host yet.';
}

import type { Host } from '$lib/api/types';

/**
 * Where one host stands in placement.
 *
 * The controller ranks hosts from the specs their agents report: more and
 * faster CPU, memory and disk score higher out of 100, and a higher score is
 * offered a runner first. An operator may pin a host to their own number, on
 * the same scale, and the pin outranks the score; clearing it hands the
 * ranking back to the machine. These are the words and the state the card and
 * the dialog show for it, so both say the same thing.
 */

/** Whether an operator's pin stands on this host at all. */
export function isPinned(host: Pick<Host, 'priority_override'>): boolean {
  return host.priority_override != null;
}

/** The words for what set the host's priority, beside the number on the card. */
export function prioritySourceWords(host: Pick<Host, 'priority_override'>): string {
  return isPinned(host) ? 'set by an operator' : 'scored from its specs';
}

/**
 * The body one PATCH sends for this host's priority, in its three states: no
 * field at all when there is nothing to change, a pin when one is wanted, and
 * a null when the operator hands the ranking back to the specs.
 */
export function priorityBody(
  host: Pick<Host, 'priority_override'> | null,
  next: 'auto' | 'pinned',
  pin: number | null,
): { priority?: { override: number | null } } {
  const had = host?.priority_override == null ? 'auto' : 'pinned';
  if (next === had && (next === 'auto' || pin === host?.priority_override)) return {};
  return { priority: next === 'pinned' ? { override: pin ?? 0 } : { override: null } };
}

/** The refusal the dialog says about a typed pin, before trying the server. */
export function pinError(pin: number | null): string {
  if (pin == null || !Number.isInteger(pin)) return 'Write a whole number between 0 and 100.';
  if (pin < 0 || pin > 100) return `${pin} is outside the 0..100 scale placement ranks hosts on.`;
  return '';
}

/**
 * A host's runner profile: from the form to the request and back, the rules the
 * API will hold it to, and the slots it gives.
 *
 * Pure, and imported by a unit test. The slot count is the controller's own
 * arithmetic (`Host.Slots` in the store) worked out again, for one use: the
 * sentence under the fields while the operator is still typing. It runs against
 * the machine less its reserve as the controller last reported it, so a reserve
 * changed in the other dialog is not in it until that is saved. Once the profile
 * is saved the host's card shows the controller's own figure, and where the two
 * ever disagree that one is right.
 */
import type { Host, RunnerProfile } from '../api/types';
import { MIN_TMPFS_MB, cpuLabel, memoryLabel } from '../pools/sizing';

/**
 * The figures a profile holds. Zero is "not set": the fleet's setting
 * stands in for it, which is how every host starts. The last two are not sizes
 * but the host's say over pools' in-memory folders, and are "not said" the same
 * way: off is false and no ceiling is zero.
 */
export interface ProfileFigures {
  /** The least a runner is given here. */
  minCpus: number;
  minMemoryMb: number;
  /** One runner's size here, for a pool that takes its size from the host. */
  standardCpus: number;
  standardMemoryMb: number;
  /** The most CPU one runner may use, its guaranteed share and any CPU lent to it together. */
  burstMaxCpus: number;
  /**
   * The most memory one runner may hold, its guaranteed share and anything the
   * memory valve has lent it together, in MB. Zero is no ceiling of this host's.
   */
  burstMaxMemoryMb: number;
  /** Keep every in-memory folder off this host, whatever a pool asks for. */
  tmpfsOff: boolean;
  /** The most any one in-memory folder may be here, in MB; zero is no host ceiling. */
  tmpfsMaxMb: number;
  /**
   * The size each in-memory folder is asked for here when a pool leaves it to size
   * itself, in MB, in place of the built-in default; zero is the default. The
   * folder-sized counterpart of a standard runner size.
   */
  tmpfsWorkMb: number;
  tmpfsTmpMb: number;
  tmpfsDaemonMb: number;
}

export const NO_FIGURES: Readonly<ProfileFigures> = {
  minCpus: 0,
  minMemoryMb: 0,
  standardCpus: 0,
  standardMemoryMb: 0,
  burstMaxCpus: 0,
  burstMaxMemoryMb: 0,
  tmpfsOff: false,
  tmpfsMaxMb: 0,
  tmpfsWorkMb: 0,
  tmpfsTmpMb: 0,
  tmpfsDaemonMb: 0,
};

/**
 * The floors under any runner, which the API enforces on a number somebody
 * typed: below them the runner binary cannot keep up with its own job, or is
 * killed before it takes one.
 */
export const MIN_RUNNER_CPUS = 0.25;
export const MIN_RUNNER_MEMORY_MB = 512;

/** The form's figures for a host's stored profile; every field it does not name is zero. */
export function figuresOf(profile: RunnerProfile | null | undefined): ProfileFigures {
  return {
    minCpus: profile?.minimum?.cpus ?? 0,
    minMemoryMb: profile?.minimum?.memory_mb ?? 0,
    standardCpus: profile?.standard?.cpus ?? 0,
    standardMemoryMb: profile?.standard?.memory_mb ?? 0,
    burstMaxCpus: profile?.standard?.burst_max_cpus ?? 0,
    burstMaxMemoryMb: profile?.standard?.burst_max_memory_mb ?? 0,
    tmpfsOff: profile?.tmpfs?.disabled === true,
    tmpfsMaxMb: profile?.tmpfs?.max_mb ?? 0,
    tmpfsWorkMb: profile?.tmpfs?.work_mb ?? 0,
    tmpfsTmpMb: profile?.tmpfs?.tmp_mb ?? 0,
    tmpfsDaemonMb: profile?.tmpfs?.daemon_mb ?? 0,
  };
}

/**
 * The request's `runner_profile`: only the figures that are set, and `{}` where
 * none is. The API replaces the whole profile with what it is sent, so an empty
 * object is how "follow the fleet everywhere" is said, and a field left out is
 * one the host stops overriding.
 */
export function profileBody(f: ProfileFigures): RunnerProfile {
  const minimum: NonNullable<RunnerProfile['minimum']> = {};
  if (f.minCpus > 0) minimum.cpus = f.minCpus;
  if (f.minMemoryMb > 0) minimum.memory_mb = f.minMemoryMb;
  const standard: NonNullable<RunnerProfile['standard']> = {};
  if (f.standardCpus > 0) standard.cpus = f.standardCpus;
  if (f.standardMemoryMb > 0) standard.memory_mb = f.standardMemoryMb;
  if (f.burstMaxCpus > 0) standard.burst_max_cpus = f.burstMaxCpus;
  if (f.burstMaxMemoryMb > 0) standard.burst_max_memory_mb = f.burstMaxMemoryMb;
  const tmpfs: NonNullable<RunnerProfile['tmpfs']> = {};
  if (f.tmpfsOff) tmpfs.disabled = true;
  // A ceiling on a host that keeps the folders off is a contradiction the API
  // refuses, and nothing to send: the toggle is the stronger of the two.
  if (f.tmpfsMaxMb > 0 && !f.tmpfsOff) tmpfs.max_mb = f.tmpfsMaxMb;
  // The same for the sizes: there is no folder to size where they are off.
  if (!f.tmpfsOff) {
    if (f.tmpfsWorkMb > 0) tmpfs.work_mb = f.tmpfsWorkMb;
    if (f.tmpfsTmpMb > 0) tmpfs.tmp_mb = f.tmpfsTmpMb;
    if (f.tmpfsDaemonMb > 0) tmpfs.daemon_mb = f.tmpfsDaemonMb;
  }
  const body: RunnerProfile = {};
  if (Object.keys(minimum).length > 0) body.minimum = minimum;
  if (Object.keys(standard).length > 0) body.standard = standard;
  if (Object.keys(tmpfs).length > 0) body.tmpfs = tmpfs;
  return body;
}

/** True when nothing is set, which is a host that follows the fleet in everything. */
export function isUnset(f: ProfileFigures): boolean {
  return (
    f.minCpus <= 0 &&
    f.minMemoryMb <= 0 &&
    f.standardCpus <= 0 &&
    f.standardMemoryMb <= 0 &&
    f.burstMaxCpus <= 0 &&
    f.burstMaxMemoryMb <= 0 &&
    !f.tmpfsOff &&
    f.tmpfsMaxMb <= 0 &&
    f.tmpfsWorkMb <= 0 &&
    f.tmpfsTmpMb <= 0 &&
    f.tmpfsDaemonMb <= 0
  );
}

/** Whether two sets of figures say the same thing, for a Save that has nothing to save. */
export function sameFigures(a: ProfileFigures, b: ProfileFigures): boolean {
  return (
    a.minCpus === b.minCpus &&
    a.minMemoryMb === b.minMemoryMb &&
    a.standardCpus === b.standardCpus &&
    a.standardMemoryMb === b.standardMemoryMb &&
    a.burstMaxCpus === b.burstMaxCpus &&
    a.burstMaxMemoryMb === b.burstMaxMemoryMb &&
    a.tmpfsOff === b.tmpfsOff &&
    a.tmpfsMaxMb === b.tmpfsMaxMb &&
    a.tmpfsWorkMb === b.tmpfsWorkMb &&
    a.tmpfsTmpMb === b.tmpfsTmpMb &&
    a.tmpfsDaemonMb === b.tmpfsDaemonMb
  );
}

/** What a host's machine is, as far as it has said. Zero is "not measured". */
export interface MachineShape {
  cpus: number;
  memoryMb: number;
  /** The machine less its reserve, with the documented floors applied: what the scheduler places onto. */
  allocatableCpus: number;
  allocatableMemoryMb: number;
}

export function machineOf(host: Host | null | undefined): MachineShape {
  return {
    cpus: host?.cpus ?? 0,
    memoryMb: host?.memory_mb ?? 0,
    allocatableCpus: host?.allocatable_cpus ?? 0,
    allocatableMemoryMb: host?.allocatable_memory_mb ?? 0,
  };
}

/**
 * The rules the API will hold a profile to, keyed by the field names it answers
 * with so a server refusal and one found here sit under the same input.
 *
 * Found here so the operator learns while typing, not after Save: the checks are
 * the server's own, in the same order, and the server still makes them.
 */
export function profileErrors(f: ProfileFigures, machine: MachineShape): Record<string, string> {
  const errors: Record<string, string> = {};
  const key = (field: string) => `runner_profile.${field}`;

  const cpuFloor = (field: string, value: number): void => {
    if (value > 0 && value < MIN_RUNNER_CPUS)
      errors[key(field)] =
        'A runner needs at least a quarter of a core. Leave it empty to follow the fleet.';
  };
  const memoryFloor = (field: string, value: number): void => {
    if (value > 0 && value < MIN_RUNNER_MEMORY_MB)
      errors[key(field)] = 'A runner needs at least 512 MB. Leave it empty to follow the fleet.';
  };
  cpuFloor('minimum.cpus', f.minCpus);
  memoryFloor('minimum.memory_mb', f.minMemoryMb);
  cpuFloor('standard.cpus', f.standardCpus);
  memoryFloor('standard.memory_mb', f.standardMemoryMb);
  cpuFloor('standard.burst_max_cpus', f.burstMaxCpus);
  memoryFloor('standard.burst_max_memory_mb', f.burstMaxMemoryMb);

  // A folder smaller than the floor is not one a checkout fits in. The ceiling
  // is moot on a host that keeps the folders off, so it is only held to the floor
  // while it is in force.
  if (!f.tmpfsOff && f.tmpfsMaxMb > 0 && f.tmpfsMaxMb < MIN_TMPFS_MB)
    errors[key('tmpfs.max_mb')] =
      `A ceiling below ${MIN_TMPFS_MB} MB leaves no folder a checkout fits in. Leave it empty to set none, or keep the folders off here instead.`;

  // The sizes a folder is asked for here are held to the same floor.
  if (!f.tmpfsOff) {
    for (const [name, mb] of [
      ['tmpfs.work_mb', f.tmpfsWorkMb],
      ['tmpfs.tmp_mb', f.tmpfsTmpMb],
      ['tmpfs.daemon_mb', f.tmpfsDaemonMb],
    ] as const) {
      if (mb > 0 && mb < MIN_TMPFS_MB)
        errors[key(name)] =
          `A folder below ${MIN_TMPFS_MB} MB is not one a checkout fits in. Leave it empty to use the default.`;
    }
  }

  // A minimum above the standard is a floor above the size it floors.
  if (
    !errors[key('minimum.cpus')] &&
    f.minCpus > 0 &&
    f.standardCpus > 0 &&
    f.minCpus > f.standardCpus
  )
    errors[key('minimum.cpus')] =
      `The minimum is above the standard, ${cpuLabel(f.standardCpus)}. A runner is never given less than the minimum, so it has to be the smaller of the two.`;
  if (
    !errors[key('minimum.memory_mb')] &&
    f.minMemoryMb > 0 &&
    f.standardMemoryMb > 0 &&
    f.minMemoryMb > f.standardMemoryMb
  )
    errors[key('minimum.memory_mb')] =
      `The minimum is above the standard, ${memoryLabel(f.standardMemoryMb)}. A runner is never given less than the minimum, so it has to be the smaller of the two.`;
  // The ceiling is the most a runner may use, its own share included.
  if (
    !errors[key('standard.burst_max_cpus')] &&
    f.burstMaxCpus > 0 &&
    f.standardCpus > 0 &&
    f.burstMaxCpus < f.standardCpus
  )
    errors[key('standard.burst_max_cpus')] =
      `The ceiling is the most a runner may use, its own share included, so it has to be at least the standard, ${cpuLabel(f.standardCpus)}.`;

  // The same for memory: the ceiling is the most a runner may hold, so under its
  // own share it would be a request to take memory back, which nothing does.
  if (
    !errors[key('standard.burst_max_memory_mb')] &&
    f.burstMaxMemoryMb > 0 &&
    f.standardMemoryMb > 0 &&
    f.burstMaxMemoryMb < f.standardMemoryMb
  )
    errors[key('standard.burst_max_memory_mb')] =
      `The ceiling is the most a runner may hold, its own share included, so it has to be at least the standard, ${memoryLabel(f.standardMemoryMb)}.`;

  // What the machine can give. A figure above all of it could never run one
  // runner, which is the host refusing every pool.
  if (machine.cpus > 0) {
    const room = machine.allocatableCpus;
    if (!errors[key('standard.cpus')] && f.standardCpus > room + 1e-6)
      errors[key('standard.cpus')] =
        `This host has ${cpuLabel(room)} to place runners on once its reserve is held back, so a standard of ${cpuLabel(f.standardCpus)} could never run a runner here.`;
    if (!errors[key('minimum.cpus')] && f.minCpus > room + 1e-6)
      errors[key('minimum.cpus')] =
        `This host has ${cpuLabel(room)} to place runners on once its reserve is held back, which is less than this minimum.`;
  }
  if (machine.memoryMb > 0) {
    const room = machine.allocatableMemoryMb;
    if (!errors[key('standard.memory_mb')] && f.standardMemoryMb > room)
      errors[key('standard.memory_mb')] =
        `This host has ${memoryLabel(room)} to place runners on once its reserve is held back, so a standard of ${memoryLabel(f.standardMemoryMb)} could never run a runner here.`;
    if (!errors[key('minimum.memory_mb')] && f.minMemoryMb > room)
      errors[key('minimum.memory_mb')] =
        `This host has ${memoryLabel(room)} to place runners on once its reserve is held back, which is less than this minimum.`;
  }
  return errors;
}

/** What sets a derived slot count: the machine's cores or memory, or the operator's own capacity. */
export type SlotLimit = '' | 'cpu' | 'memory' | 'capacity';

export interface SlotCount {
  slots: number;
  /** What the machine holds of the standard before the capacity is applied. The capacity itself where nothing was divided. */
  held: number;
  /** What sets the count where a standard size gave it. Empty where nothing does. */
  limitedBy: SlotLimit;
  /** Whether a standard size gave the count, rather than the capacity alone. */
  derived: boolean;
}

/** Absorbs the rounding of CPU that does not divide evenly; the store's own constant. */
const SLOT_EPSILON = 1e-6;

/**
 * How many runners a host takes with this standard size: as many as its
 * allocatable machine holds, never more than its capacity.
 *
 * Only a standard the host was given counts. The fleet's default size is what a
 * pool that takes its size from the host is given where the host names none, and
 * it does not set slots: a host that says nothing keeps the capacity it has
 * always had. A capacity of zero is how an operator pauses a host, and a size
 * never un-pauses one.
 */
export function slotsFor(machine: MachineShape, capacity: number, f: ProfileFigures): SlotCount {
  if (capacity <= 0) return { slots: 0, held: 0, limitedBy: '', derived: false };
  if (f.standardCpus <= 0 && f.standardMemoryMb <= 0)
    return { slots: capacity, held: capacity, limitedBy: '', derived: false };
  let byCpu = capacity;
  let byMemory = capacity;
  let bound = false;
  if (f.standardCpus > 0 && machine.cpus > 0) {
    byCpu = Math.floor((machine.allocatableCpus + SLOT_EPSILON) / f.standardCpus);
    bound = true;
  }
  if (f.standardMemoryMb > 0 && machine.memoryMb > 0) {
    byMemory = Math.floor(machine.allocatableMemoryMb / f.standardMemoryMb);
    bound = true;
  }
  // A host that has not measured its machine has nothing to divide, and is
  // placed by its capacity exactly as it was before it had a size.
  if (!bound) return { slots: capacity, held: capacity, limitedBy: '', derived: false };
  const held = Math.max(Math.min(byCpu, byMemory), 0);
  const slots = Math.min(capacity, held);
  let limitedBy: SlotLimit = '';
  if (slots < capacity) limitedBy = byCpu <= byMemory ? 'cpu' : 'memory';
  else if (capacity < held) limitedBy = 'capacity';
  return { slots, held, limitedBy, derived: true };
}

/**
 * What to suggest for a host's capacity and reserve, from what the machine is
 * and what a runner in this fleet asks for.
 *
 * Pure, and imported by a unit test. The numbers are a starting point an
 * operator can see the reasoning of, not a promise: the scheduler still
 * places by fit, and a host above its recommendation is one where jobs can
 * wait on slots that read as free.
 */
import type { Pool } from '../api/types';

/** The machine, as the host reported it. Zero means it has not said. */
export interface HostShape {
  cpus: number;
  memoryMb: number;
}

/** What one runner asks for: the largest ask across the enabled pools. */
export interface RunnerAsk {
  cpus: number;
  memoryMb: number;
  /** Where the ask came from, for the sentence under the slider. */
  source: 'pools' | 'default';
  /**
   * The pool whose figures won, when one did. It is the other half of the
   * sentence: an operator told a runner here asks for eight cores can go and
   * look at the pool that says so.
   */
  pool?: string;
  /**
   * Whether the ask was doubled because a slot is a pair. It is the figure
   * that needs explaining: an operator who typed 2 cores on the pool and
   * reads 4 here has to be told which of the two is wrong, and neither is.
   */
  pair: boolean;
}

/**
 * The default a pool created today gets, where the fleet has not said.
 *
 * It is the same pair of figures `runners.default_cpus` and
 * `runners.default_memory_mb` start at, and it stands in only until those have
 * been read -- on the first paint, or where the call for them failed. Passing
 * the fleet's own is what keeps this page's recommendation and the pool
 * wizard's sliders describing the same fleet.
 */
export const DEFAULT_ASK: RunnerAsk = { cpus: 2, memoryMb: 4096, source: 'default', pair: false };

export function runnerAsk(
  // Only what the ask is made of, so a caller (and a test) hands over those
  // four fields and not a whole pool it would have to invent a priority for.
  pools: readonly Pick<Pool, 'name' | 'enabled' | 'docker_mode' | 'resources'>[],
  fleetDefault?: { cpus?: number; memory_mb?: number } | null,
): RunnerAsk {
  const fallbackCPUs =
    fleetDefault?.cpus && fleetDefault.cpus > 0 ? fleetDefault.cpus : DEFAULT_ASK.cpus;
  const fallbackMemoryMb =
    fleetDefault?.memory_mb && fleetDefault.memory_mb > 0
      ? fleetDefault.memory_mb
      : DEFAULT_ASK.memoryMb;
  let cpus = 0;
  let memoryMb = 0;
  let winner = '';
  // Whether the figure that won is a pair's, which is the only thing the
  // sentence has to explain. A dind pool that does not win says nothing here:
  // this function has no host in hand, so it cannot know whether that pool
  // places on the machine being adjusted, and inflating every host in the
  // fleet for one pool would be a recommendation nobody could act on.
  // `host.overprovisioned` is the half that does know, host by host.
  let cpuPair = false;
  let memoryPair = false;
  let anyPair = false;
  for (const pool of pools) {
    if (pool.enabled !== true) continue;
    // A docker-in-docker slot is two containers where the pool typed its own
    // limits: the daemon runs the build, so it is given what the job was
    // promised and the machine carries both. A pool that leaves its size to
    // the host puts the pair in one slot between them and asks for no more
    // than anybody else.
    const typed = (pool.resources?.cpus ?? 0) > 0 || (pool.resources?.memory_mb ?? 0) > 0;
    const containers = pool.docker_mode === 'dind' && typed ? 2 : 1;
    anyPair = anyPair || containers > 1;
    const wantCpus = (pool.resources?.cpus ?? 0) * containers;
    const wantMemoryMb = (pool.resources?.memory_mb ?? 0) * containers;
    if (wantCpus > cpus) {
      cpus = wantCpus;
      cpuPair = containers > 1;
      winner = pool.name ?? winner;
    }
    if (wantMemoryMb > memoryMb) {
      memoryMb = wantMemoryMb;
      memoryPair = containers > 1;
      if (winner === '') winner = pool.name ?? '';
    }
  }
  if (cpus <= 0 && memoryMb <= 0) {
    // Nothing was set anywhere, so the fleet's default answers -- twice over
    // only where a pool typed a daemon's worth beside it, which nothing here
    // did. A pool that leaves its size to the host puts its runner and its
    // daemon in one slot, so its ask is one runner's like everybody else's.
    if (!anyPair)
      return { cpus: fallbackCPUs, memoryMb: fallbackMemoryMb, source: 'default', pair: false };
    return {
      cpus: fallbackCPUs * 2,
      memoryMb: fallbackMemoryMb * 2,
      source: 'default',
      pair: true,
    };
  }
  const ask: RunnerAsk = {
    cpus: cpus > 0 ? cpus : fallbackCPUs,
    memoryMb: memoryMb > 0 ? memoryMb : fallbackMemoryMb,
    source: 'pools',
    pair: cpuPair || memoryPair,
  };
  if (winner !== '') ask.pool = winner;
  return ask;
}

/**
 * Cores to hold back for the machine itself: one on anything up to sixteen,
 * then one more for every sixteen. Never the whole machine.
 */
export function recommendedReserveCores(cpus: number): number {
  if (cpus <= 1) return 0;
  return Math.min(cpus - 1, Math.max(1, Math.ceil(cpus / 16)));
}

/**
 * Memory to hold back: a tenth of the machine, between one and eight
 * gigabytes, on the nearest notch of the slider -- so the recommendation is
 * somewhere the slider can actually stop.
 */
export function recommendedReserveMemoryMb(memoryMb: number): number {
  if (memoryMb <= 1024) return 0;
  const tenth = Math.min(memoryMb - 512, Math.max(1024, Math.min(8192, memoryMb * 0.1)));
  let best = 0;
  for (const n of memoryNotches(memoryMb)) {
    if (Math.abs(n - tenth) <= Math.abs(best - tenth)) best = n;
  }
  return best;
}

/**
 * Disk to hold back for the machine: a tenth of the filesystem, between the
 * scheduler's own two-gigabyte floor and sixty-four gigabytes, on the nearest
 * notch of the slider. Runner checkouts and caches land here, so the reserve
 * is what stops a full disk turning into a job that fails part-way through.
 */
export function recommendedReserveDiskMb(diskTotalMb: number): number {
  if (diskTotalMb <= 4096) return 0;
  const tenth = Math.min(diskTotalMb - 2048, Math.max(2048, Math.min(65536, diskTotalMb * 0.1)));
  let best = 0;
  for (const n of diskNotches(diskTotalMb)) {
    if (Math.abs(n - tenth) <= Math.abs(best - tenth)) best = n;
  }
  return best;
}

/** How many runners of this ask fit on what is left after the reserve. At least one. */
export function recommendedCapacity(
  host: HostShape,
  reserveCores: number,
  reserveMb: number,
  ask: RunnerAsk,
): number {
  const byCpu = host.cpus > 0 ? Math.floor((host.cpus - reserveCores) / ask.cpus) : Infinity;
  const byMemory =
    host.memoryMb > 0 ? Math.floor((host.memoryMb - reserveMb) / ask.memoryMb) : Infinity;
  const fit = Math.min(byCpu, byMemory);
  return Number.isFinite(fit) ? Math.max(1, fit) : 0;
}

/** The notches of the capacity slider: every count up to a ceiling worth seeing. */
export function capacityCeiling(host: HostShape, recommended: number, current: number): number {
  const sized = host.cpus > 0 ? Math.max(host.cpus, recommended * 2) : Math.max(8, current * 2);
  return Math.max(4, sized, current);
}

/** The notches of the memory slider: half a gigabyte, then doubling-ish steps, then gigabytes. */
export function memoryNotches(memoryMb: number): number[] {
  if (memoryMb <= 512) return [0];
  const top = memoryMb - 512;
  const out = [0];
  const steps = [512, 1024, 2048, 3072, 4096, 6144, 8192, 12288, 16384, 24576, 32768];
  for (const s of steps) if (s <= top) out.push(s);
  let next = 49152;
  while (next <= top) {
    out.push(next);
    next += 16384;
  }
  return out;
}

/**
 * The notches of the disk slider: two gigabytes -- the scheduler's floor --
 * and then doublings. A disk is two orders of magnitude larger than memory,
 * and a slider that stepped it in gigabytes would be a thousand notches long.
 */
export function diskNotches(diskTotalMb: number): number[] {
  if (diskTotalMb <= 4096) return [0];
  const top = diskTotalMb - 2048;
  const out = [0];
  for (let step = 2048; step <= top; step *= 2) out.push(step);
  return out;
}

/** "4 GB", "512 MB". */
export function memoryLabel(mb: number): string {
  if (mb === 0) return 'none';
  if (mb < 1024) return `${mb} MB`;
  return `${(mb / 1024).toLocaleString(undefined, { maximumFractionDigits: 1 })} GB`;
}

export interface Overcommit {
  /** Cores the runners would ask for, over what is placeable. Zero when they fit. */
  cpus: number;
  memoryMb: number;
}

/** What `capacity` runners of the ask would take beyond the room the reserve leaves. */
export function overcommit(
  host: HostShape,
  capacity: number,
  reserveCores: number,
  reserveMb: number,
  ask: RunnerAsk,
): Overcommit {
  return {
    cpus: host.cpus > 0 ? Math.max(0, capacity * ask.cpus - (host.cpus - reserveCores)) : 0,
    memoryMb:
      host.memoryMb > 0 ? Math.max(0, capacity * ask.memoryMb - (host.memoryMb - reserveMb)) : 0,
  };
}

/**
 * What changed between two reports from the same host, for the host page to say
 * out loud.
 *
 * Route-only, like next-step.ts: health.ts is shell code (the feed imports it),
 * so the words that only this page needs live here.
 *
 * The diff reads `attention()` rather than the raw results, so it inherits the
 * rules the pill already follows -- counted checks only, the optional and tier
 * rules, and the kernel.pending warning folded into the reboot flag. A change
 * announced here can therefore never disagree with the badge beside it.
 */
import { attention, healthSummary, type DoctorReport, type DoctorResult } from './health';
import { reportOnly } from './report-only';

export interface ReportChange {
  id: string;
  title: string;
  kind: 'resolved' | 'new' | 'escalated';
  /** What a `new` check now says, so the words can tell a warning from an error. */
  status?: 'warn' | 'error';
}

/** A title is the agent's text and the page's only copy of it in a live region; bound it. */
const TITLE_LIMIT = 60;

function titleOf(result: DoctorResult): string {
  const text = [...(result.title || result.id)];
  return text.length > TITLE_LIMIT ? `${text.slice(0, TITLE_LIMIT).join('')}…` : text.join('');
}

function index(report: DoctorReport): Map<string, DoctorResult> {
  const byId = new Map<string, DoctorResult>();
  // First wins: a report that repeats an id is the agent's mistake, and both
  // sides of the diff read it the same way.
  for (const r of report.results) if (!byId.has(r.id)) byId.set(r.id, r);
  return byId;
}

function time(report: DoctorReport): number {
  return Date.parse(report.checked_at);
}

/**
 * The same source, so the diff compares like with like: a host that was
 * reinstalled, upgraded or moved into a container changes which checks exist,
 * and "resolved" would then be a statement about the agent, not the host.
 */
export function sameSource(
  prev: DoctorReport,
  next: DoctorReport,
  ctx: { prevVersion: string; nextVersion: string },
): boolean {
  return (
    prev.os === next.os &&
    prev.distro === next.distro &&
    prev.container === next.container &&
    ctx.prevVersion === ctx.nextVersion
  );
}

/**
 * Checks that cleared or started needing attention between two reports. Empty
 * unless every gate passes:
 *
 * 1. there is a previous report (the first one seen is the baseline, so opening
 *    the page announces nothing);
 * 2. the new one is strictly later, which is the controller's own rule -- a
 *    repeated frame, a cordon frame or a replay is a no-op, and a frame count is
 *    never a signal;
 * 3. both come from the same source (the caller rebaselines silently when not);
 * 4. both carry the controller's count and neither is a partial report, whose
 *    checks are mostly skipped and which the pill calls no verdict.
 *
 * Only ids present in both reports count: a check that appeared or vanished
 * with an agent change says nothing about the host.
 */
export function reportChanges(
  prev: DoctorReport | undefined,
  next: DoctorReport | undefined,
  ctx: { prevVersion: string; nextVersion: string },
): ReportChange[] {
  if (!prev || !next) return [];
  const before = time(prev);
  const after = time(next);
  if (!Number.isFinite(before) || !Number.isFinite(after) || after <= before) return [];
  if (!sameSource(prev, next, ctx)) return [];
  if (!prev.summary || !next.summary) return [];
  if (prev.container || next.container || reportOnly(prev) || reportOnly(next)) return [];

  const was = new Map(attention(prev).map((r) => [r.id, r]));
  const now = new Map(attention(next).map((r) => [r.id, r]));
  const before2 = index(prev);
  const after2 = index(next);
  const changes: ReportChange[] = [];

  for (const [id, old] of was) {
    const current = after2.get(id);
    if (!current) continue;
    // A skipped check is not an OK one: a stopped Docker daemon skips a whole
    // group at once, and "now OK" for it would be false.
    if (current.status === 'ok') changes.push({ id, title: titleOf(current), kind: 'resolved' });
    else if (current.status === 'error' && old.status === 'warn' && now.has(id))
      changes.push({ id, title: titleOf(current), kind: 'escalated' });
  }
  for (const [id, current] of now) {
    if (was.has(id) || !before2.has(id)) continue;
    changes.push({
      id,
      title: titleOf(current),
      kind: 'new',
      status: current.status === 'error' ? 'error' : 'warn',
    });
  }
  return changes;
}

/** "A", "A and B", "A, B and C": no verb follows, so no agreement to get wrong. */
function list(titles: string[]): string {
  return titles.length < 2
    ? (titles[0] ?? '')
    : `${titles.slice(0, -1).join(', ')} and ${titles[titles.length - 1]}`;
}

/** One group of check names and what happened to them, collapsing to a count when long. */
function group(titles: string[], single: string, many: (n: number) => string): string {
  if (titles.length === 0) return '';
  if (titles.length > 3) return many(titles.length);
  return `${list(titles)}, ${single}`;
}

/**
 * One string for a whole report, so a screen reader hears one announcement
 * rather than one per check. Contains no time: a reconnect can legitimately
 * announce a change that happened during a gap, and "just now" would be false.
 */
export function announcement(changes: ReportChange[], allClear: boolean): string {
  if (changes.length === 0) return '';
  const titles = (pick: (c: ReportChange) => boolean) => changes.filter(pick).map((c) => c.title);
  const parts = [
    group(
      titles((c) => c.kind === 'resolved'),
      'now OK',
      (n) => `${n} checks are now OK`,
    ),
    group(
      titles((c) => c.kind === 'new' && c.status !== 'error'),
      'now needs attention',
      (n) => `${n} checks now need attention`,
    ),
    group(
      titles((c) => c.kind === 'new' && c.status === 'error'),
      'now has an error',
      (n) => `${n} checks now have an error`,
    ),
    group(
      titles((c) => c.kind === 'escalated'),
      'warning became an error',
      (n) => `${n} warnings became errors`,
    ),
    allClear ? 'Nothing on this host needs attention now' : '',
  ].filter(Boolean);
  return parts.join('. ');
}

/** The same facts one per row for the visible list. */
export function logLine(c: ReportChange): string {
  if (c.kind === 'resolved') return `${c.title}, now OK`;
  if (c.kind === 'escalated') return `${c.title}, warning became an error`;
  return `${c.title}, ${c.status === 'error' ? 'now has an error' : 'now needs attention'}`;
}

/** Whether a report now says everything is fine, for the "nothing needs attention" sentence. */
export function allClear(report: DoctorReport, now: number): boolean {
  return attention(report).length === 0 && healthSummary(report, now, true).label === 'Health OK';
}

/**
 * Hosts whose report can be read but not acted on, and the words for them.
 *
 * Route-only, like next-step.ts: health.ts is shell code (the feed imports it),
 * so the sentences that only the host page needs live here instead of growing
 * the app shell.
 *
 * The page used to tell every host to "review changes locally" with
 * `zoomies tune`, which is a command that changes nothing on a macOS host, an
 * unsupported distribution or a container. Saying so is the point: a person
 * following the old sentence on a Mac was sent to a command that refuses.
 */
import type { DoctorReport } from './health';

export type ReportOnly = 'os' | 'distro' | 'container';

/**
 * Why a report cannot be acted on, or null when it can.
 *
 * Not `os === 'linux'`: the engine adds its `environment` row exactly when the
 * platform is unsupported (a skip for another system, a warning for a Linux
 * distribution outside the list), so reading that row keeps a second list of
 * distributions out of the UI. An agent that predates the row is treated as
 * tunable, which is what the page did before this existed.
 */
export function reportOnly(report: DoctorReport | undefined): ReportOnly | null {
  if (!report) return null;
  if (report.container) return 'container';
  const env = report.results.find((r) => r.id === 'environment');
  if (env?.status === 'skip') return 'os';
  if (env?.status === 'warn') return 'distro';
  return null;
}

/** The sentence that replaces "Review changes locally with ...". Words only: no command here is run by Zoomies. */
export function reportOnlySentence(kind: ReportOnly, os: string): string {
  switch (kind) {
    case 'os':
      return `Zoomies does not tune ${os ? `${os} hosts` : 'this kind of host'}, its OS checks need Linux, so this report is informational and there is nothing to change on this host.`;
    case 'distro':
      return 'This distribution is report-only: run sudo zoomies doctor on the host to read its checks. zoomies tune will not change it.';
    case 'container':
      return 'Run sudo zoomies doctor on the host itself with the native binary, not inside the container, a container cannot be tuned.';
  }
}

/** The page subtitle: null keeps the usual one. */
export function reportOnlySubtitle(kind: ReportOnly | null): string | null {
  return kind === 'os'
    ? 'OS checks run on Linux hosts only. Zoomies does not change this host.'
    : null;
}

/** The Safe tier's description when nothing on this host can be applied. */
export const REPORT_ONLY_SAFE_DESCRIPTION = 'Read-only. Zoomies does not change this host.';

/** "linux · ubuntu 24.04", without a stray separator when the distribution is blank. */
export function reportOrigin(report: Pick<DoctorReport, 'os' | 'distro'>): string {
  return [report.os, report.distro?.trim()].filter(Boolean).join(' · ');
}

/**
 * What a flagged check row says about fixing it, and the command to preview that.
 *
 * Route-only on purpose: health.ts is shell code under the app-shell budget, and
 * only the host page needs these words. Zoomies never runs any of this -- the
 * command is text for a person to run on the host.
 */
import type { DoctorResult } from './health';
import { shellQuote } from './terminal';

export type RowKind = 'fixable' | 'advice' | 'optional';

export const KIND_WORDS: Record<RowKind, string> = {
  fixable: 'Fixable',
  advice: 'Advice',
  optional: 'Optional',
};

/**
 * A check id is `family.name`, and some names are real mixed-case unit names
 * (`service.ModemManager`), so a lower-case-only pattern would silently drop a
 * row. The `environment` row has no dot and never matches.
 */
export const CHECK_ID = /^[a-z]+(\.[A-Za-z0-9-]+)+$/;
export const CHECK_ID_MAX = 64;

/**
 * Null unless this is a warning on a host that can be tuned at all. `=== true`
 * means an older agent that omits `actionable` reads as Advice, the safe way to
 * be wrong; Optional wins because a trade-off is read about before it is fixed.
 */
export function rowKind(check: DoctorResult, readOnly: boolean): RowKind | null {
  // An accepted row is a decision already taken: it says so in its badge, and a
  // word about fixing it would argue with that.
  if (check.status !== 'warn' || readOnly || check.accepted) return null;
  if (check.optional === true) return 'optional';
  if (check.actionable === true) return 'fixable';
  return 'advice';
}

// tune refuses an aggressive or dedicated id without its flag, and there is no
// `--tier dedicated`, so each tier spells its own.
const TIER_FLAGS: Record<string, string[]> = {
  safe: [],
  aggressive: ['--tier', 'aggressive'],
  dedicated: ['--dedicated'],
};

/**
 * The dry-run a person runs on the host, or null for anything unvalidated -- never
 * a sanitised guess. The quoted id is the only agent-written text in the string,
 * and the quoting is defence in depth behind the pattern.
 */
export function previewCommand(check: DoctorResult): string | null {
  const tier: unknown = check.tier;
  if (typeof tier !== 'string' || !Object.hasOwn(TIER_FLAGS, tier)) return null;
  const flags = TIER_FLAGS[tier] ?? [];
  const id: unknown = check.id;
  if (typeof id !== 'string' || id.length > CHECK_ID_MAX || !CHECK_ID.test(id)) return null;
  return ['sudo', 'zoomies', 'tune', ...flags, '--only', shellQuote(id), '--dry-run'].join(' ');
}

/**
 * The text a person runs on the host to fix this row, or null when there is none
 * to give. The agent's own by-hand command wins, being the one that fits what it
 * found; a row tune can change falls back to the preview. Advice rows have
 * neither, and the page says so rather than inventing a command for them.
 */
export function fixCommand(check: DoctorResult): string | null {
  if (check.status !== 'warn' || check.accepted) return null;
  if (check.command) return check.command;
  // An Optional row is a trade-off to read about first, so it gets no preview to copy.
  return check.actionable === true && check.optional !== true ? previewCommand(check) : null;
}

/**
 * How many runners a host takes before any throttle.
 *
 * `slots` is the controller's count: the host's capacity, or -- where the
 * operator has given the host a standard runner size -- as many runners of that
 * size as its machine holds, never more than the capacity. `capacity` on its
 * own is only the operator's ceiling, and over-counts on a host that is sized
 * by a profile, so nothing that counts runners reads it directly. A host held
 * by a cached or older response has no `slots` to say, and its capacity is what
 * it always was.
 */
import type { Host } from '../api/types';

export function slotsOf(host: Pick<Host, 'slots' | 'capacity'>): number {
  return host.slots ?? host.capacity ?? 0;
}

/**
 * A host's tags, size class and pool, as the card and the dialog say them.
 *
 * Every sentence that is a decision -- why a host is in its class, why it counts
 * towards no pool -- is written by the controller, because it is the side that
 * knows. What is here is only the arrangement of those, so the card and the
 * dialog order and word a tag the same way and one screen never writes it two
 * ways.
 */
import type { Host, HostAutoPool, HostSizeClass, HostTag, SizeClass } from '../api/types';

/** The classes in the order a host grows through them. */
export const SIZE_CLASSES: readonly SizeClass[] = ['small', 'medium', 'large'];

/** `Medium`, for a badge. */
export function classWord(size: SizeClass | undefined): string {
  return size ? size.charAt(0).toUpperCase() + size.slice(1) : '';
}

/** `rack=b4`, or `gpu` for a tag whose value is empty. */
export function tagText(tag: Pick<HostTag, 'key' | 'value'>): string {
  return tag.value === '' ? tag.key : `${tag.key}=${tag.value}`;
}

/**
 * The labels a dialog's rows say, as the API takes them.
 *
 * A row with a name and no value is a flag, and a flag is `key=true` -- what
 * `zoomies hosts edit --tag gpu` writes -- so that a pool's host selector asks
 * for it the same way whichever surface set it. A label the host already carries
 * with an empty value keeps it, because saving the dialog must not rewrite what
 * nobody touched.
 */
export function labelsFromRows(
  rows: readonly { key: string; value: string }[],
  was: Readonly<Record<string, string>> = {},
): Record<string, string> {
  const labels: Record<string, string> = {};
  for (const row of rows) {
    const key = row.key.trim();
    if (!key) continue;
    const value = row.value.trim();
    labels[key] = value !== '' ? value : was[key] === '' ? '' : 'true';
  }
  return labels;
}

export interface TagRow {
  key: string;
  text: string;
  /** Worked out from the machine by the controller, never stored, never edited here. */
  automatic: boolean;
  /** What the tag is, for a tooltip: where it came from and what changing it does. */
  hint: string;
}

/**
 * The tags to list.
 *
 * The operator's come first, because those are the ones the card's own Edit
 * button changes and the card has always shown them in this place; the ones the
 * controller derives follow, so a host that has none of its own still says what
 * machine it is. Each group keeps the order the API sent, which is by key.
 */
export function tagRows(tags: readonly HostTag[] | undefined): TagRow[] {
  const rows = (tags ?? []).map((tag): TagRow => {
    const automatic = tag.source === 'automatic';
    return {
      key: tag.key,
      text: tagText(tag),
      automatic,
      hint: automatic ? automaticHint(tag.key) : operatorHint(tag),
    };
  });
  return [...rows.filter((row) => !row.automatic), ...rows.filter((row) => row.automatic)];
}

/**
 * The rows for one host. A host the API describes without `tags` -- an older
 * controller's, or a fixture that predates them -- has its labels listed as the
 * operator's own, which is what they were.
 */
export function hostTagRows(host: Pick<Host, 'tags' | 'labels'>): TagRow[] {
  if (host.tags) return tagRows(host.tags);
  return tagRows(
    Object.entries(host.labels ?? {})
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([key, value]) => ({ key, value, source: 'operator' as const })),
  );
}

function automaticHint(key: string): string {
  if (key === 'size') {
    return "Worked out by the controller from the host's CPU and memory, and held before it changes. Set a size tag of your own to say otherwise.";
  }
  return 'Worked out by the controller from what the agent reports about the machine. It is not stored and is not edited here.';
}

function operatorHint(tag: HostTag): string {
  if (tag.overrides) {
    return `Stored on this host. It replaces ${tag.key}=${tag.overrides}, which is what the controller would have worked out. Remove it to go back to that.`;
  }
  return 'Stored on this host. A pool whose host selector names it runs only on hosts that have it.';
}

/**
 * A sentence for a class an operator set, or '' for one that was measured.
 *
 * A measured class explains itself in the controller's `reason`, which sits in
 * a tooltip. A tag changes the answer the machine would give, so the card says
 * so in the open: otherwise a host that reads "large" beside a machine that
 * plainly is not leaves its operator to find the tag.
 */
export function overrideNote(size: HostSizeClass | undefined): string {
  if (!size || size.source !== 'tag') return '';
  if (size.measured && size.measured !== size.class) {
    return `Set by this host's size tag. Its machine measures as ${size.measured}.`;
  }
  return "Set by this host's size tag, which agrees with what its machine measures.";
}

/** A class move the host is being held before making, or null while it is not waiting on one. */
export function pendingMove(
  size: HostSizeClass | undefined,
): { to: SizeClass; since?: string; until?: string } | null {
  if (!size?.pending) return null;
  return { to: size.pending, since: size.pending_since, until: size.pending_until };
}

/**
 * The line saying whether this host's slots count towards an automatic pool.
 * Null where the controller has no view of it, which is every host while both
 * switches are off.
 */
export function autoPoolLine(
  auto: HostAutoPool | undefined,
): { counted: boolean; text: string; poolId?: string } | null {
  if (!auto) return null;
  if (!auto.counted) return { counted: false, text: auto.reason || 'It counts towards no pool.' };
  const name = auto.pool ?? 'an automatic pool';
  return auto.pool_id
    ? { counted: true, text: `Its slots count towards ${name}.`, poolId: auto.pool_id }
    : {
        counted: true,
        text: `Its slots would count towards ${name}, which has not been made yet.`,
      };
}

/**
 * Commands the UI hands somebody to paste into a terminal.
 *
 * What is built here is text a person runs, so each value is quoted for a shell
 * unless it is made only of characters a shell leaves alone. An address is
 * whatever an administrator typed into a setting, and "it is only ever a URL" is
 * the sort of belief a command line is a poor place to keep.
 */

const PLAIN = /^[A-Za-z0-9_@%+=:,./-]+$/;

/** A value as one shell word: itself when plain, and otherwise in single quotes. */
export function shellQuote(value: string): string {
  if (PLAIN.test(value)) return value;
  return `'${value.replace(/'/g, `'\\''`)}'`;
}

/**
 * `zoomies doctor --host`, with everything it needs: the host, the controller's
 * address and, when the controller wants one, a token. Without a token the
 * command is the one for a controller that has authentication off.
 */
export function doctorCommand(hostId: string, url: string, token?: string): string {
  const parts = ['zoomies', 'doctor', '--host', shellQuote(hostId), '--verbose'];
  parts.push('--url', shellQuote(url));
  if (token) parts.push('--token', shellQuote(token));
  return parts.join(' ');
}

/**
 * What a host's card says about updating it from the web UI.
 *
 * Every word is a function of the host as the controller sent it, and nothing
 * here reads a clock: the controller's `update` block holds nothing that moves
 * with a heartbeat, so the card is repainted only when an attempt changes. A
 * sentence that an update worked is written from an attempt the controller
 * closed as succeeded, or from the host itself reporting the release the
 * controller runs, and never from a request having been accepted.
 *
 * Pure, so each state is a table row in a test and not a timing in a browser.
 */
import type { Host } from '../api/types';
import { UPGRADING_AGENT_URL } from '../links';

export type HostUpdateBlock = NonNullable<Host['update']>;
export type HostUpdateState = HostUpdateBlock['state'];

type HostFields = Pick<
  Host,
  | 'name'
  | 'id'
  | 'version'
  | 'version_skew'
  | 'upgrade_version'
  | 'upgrade_command'
  | 'embedded'
  | 'machine_id'
  | 'update'
>;

/**
 * The badge for a host that is updated on the host itself. The controller sends
 * a command wherever it can name a release to install, a PowerShell one to a
 * Windows agent; a host with none (the controller is a local build, or the
 * machine is rented) says "by hand" rather than promise a command that is not
 * there.
 */
function byHandLabel(host: Pick<Host, 'upgrade_command'>): string {
  return host.upgrade_command ? 'Update by command' : 'Update by hand';
}

/**
 * Where the steps for updating a host by hand are, or empty when the card has a
 * command to copy, which is the way. Only a Windows agent with a note and no
 * command is pointed at them, because the page explains its installer; any other
 * host's note, such as an unpublished controller build's, stands alone with no
 * published steps to link to.
 */
export function byHandLink(
  host: Pick<Host, 'os' | 'upgrade_command' | 'embedded' | 'upgrade_note'>,
): string {
  if (host.embedded || host.upgrade_command || !host.upgrade_note) return '';
  return host.os === 'windows' ? UPGRADING_AGENT_URL : '';
}

export interface SkewFact {
  label: string;
  /** Always neutral: a host on another release is not in a state, it is a fact worth knowing. */
  tone: 'neutral';
  hint: string;
}

/**
 * How a host's release stands to the controller's, or null when they match.
 *
 * Neutral on purpose. The status palette is a fixed mapping that operators have
 * learned, and a host that is behind is not idle, busy, pending, draining or
 * failing; reusing one of those colours would teach it a second meaning.
 *
 * `rented` is whether Zoomies rents this host as a machine, which is the one
 * thing that changes what "behind" means. A machine is cloned from its
 * provider's template and holds the agent that image carried, so it is behind
 * because the template is, and it is replaced rather than upgraded: telling its
 * operator to upgrade it would be telling them to do something nobody can do.
 */
export function skewFact(
  skew: Host['version_skew'] | '' | undefined,
  rented = false,
): SkewFact | null {
  switch (skew) {
    case undefined:
    case '':
      return null;
    case 'behind':
      return rented
        ? {
            label: 'Behind',
            tone: 'neutral',
            hint: "This machine runs the agent its provider's template carried when it was cloned, so it is behind because that image is. Prepare the template again to change what the machines built next run; this one is replaced as it goes idle.",
          }
        : {
            label: 'Behind',
            tone: 'neutral',
            hint: 'This agent is an earlier release than the controller. It is placing work as normal; upgrade it when convenient.',
          };
    case 'ahead':
      return {
        label: 'Ahead',
        tone: 'neutral',
        hint: 'This agent is a later release than the controller, which is the direction nothing is tested in. Upgrade the controller first.',
      };
    default:
      return {
        label: 'Different build',
        tone: 'neutral',
        hint: 'This agent is a build the controller cannot order against its own. Both are running; check which is which before reporting a bug.',
      };
  }
}

export interface HostUpdateWords {
  /** One word for the badge. */
  label: string;
  /** Never a status colour except for an update that did not work, which is what danger is for. */
  tone: 'neutral' | 'accent' | 'danger';
  /** The sentence shown beside the badge, as plain text. */
  sentence: string;
  /** Whether the Update button is drawn at all: not while an attempt is open, and not once it worked. */
  offered: boolean;
  /** Whether the drawn button can be pressed. A disabled one has the reason beside it as text. */
  canPress: boolean;
  /** The button's visible word. */
  action: 'Update' | 'Try again';
  /** An attempt is open: the card keeps watching and says nothing final. */
  inFlight: boolean;
  /** What the polite region says when the state changes. */
  live: string;
}

/** Release binaries report 1.3.5 where the tag is v1.3.5, so a version is named with its v. */
function tagOf(version: string | undefined): string {
  const bare = (version ?? '').trim().replace(/^v/, '');
  return bare === '' ? '' : `v${bare}`;
}

/**
 * The release the controller would take this host to, as a tag, or empty.
 *
 * `upgrade_version` is the controller's build, set for every host that is
 * behind it, which is every host `can_update` is true for.
 */
export function targetTag(host: Pick<Host, 'upgrade_version'>): string {
  return tagOf(host.upgrade_version);
}

/**
 * The host's update row, or null when there is nothing to say.
 *
 * Nothing to say is a host that matches the controller and has no attempt worth
 * showing: a row on every up-to-date card would bury the ones that differ. The
 * agent inside the controller is updated with the controller, so it has none.
 *
 * `reached` is the host reporting the controller's release, or a later one, while
 * its attempt is still open. The controller closes the attempt on the same
 * heartbeat, but a frame is a moment behind the heartbeat it came from, and the
 * host's own version is what the attempt was waiting for.
 */
export function hostUpdateWords(host: HostFields): HostUpdateWords | null {
  const update = host.update;
  if (!update || host.embedded) return null;
  // A machine Zoomies rents is offered nothing here, and not because it is
  // current: it is behind from the moment it joins, and every machine its
  // provider builds is. There is nowhere to run a command inside one -- nobody
  // logs into a clone, and it is destroyed once it has been idle -- so the only
  // way to change what it runs is the template its provider builds from. Its
  // card's own guidance, and the provider's page, say that; a button nothing
  // could ever keep would say the opposite.
  if (host.machine_id) return null;
  const name = host.name || host.id || 'this host';
  const reached =
    update.state === 'requested' && (!host.version_skew || host.version_skew === 'ahead');
  // An attempt that worked for an earlier release says nothing about a host the
  // controller has since moved ahead of: it is behind again, and can be asked again.
  const outdated =
    update.state === 'succeeded' &&
    (host.version_skew === 'behind' || host.version_skew === 'differs');
  const state: HostUpdateState = reached ? 'succeeded' : outdated ? 'none' : update.state;
  const done = `${name} runs ${host.version || 'the new release'} now.`;
  switch (state) {
    case 'requested':
      return {
        label: 'Updating',
        tone: 'accent',
        sentence: update.reason,
        offered: false,
        canPress: false,
        action: 'Update',
        inFlight: true,
        live: `${name}: updating. ${update.reason}`,
      };
    case 'succeeded':
      return {
        label: 'Updated',
        tone: 'accent',
        sentence: done,
        offered: false,
        canPress: false,
        action: 'Update',
        inFlight: false,
        live: `${name}: updated. ${done}`,
      };
    case 'failed':
    case 'timed_out':
      return {
        // A failure with a cause of its own says so in the badge: the helper on
        // the host had stopped, which is the host's to put right and not a
        // release that did not install.
        label:
          update.code === 'host.update_helper_stuck'
            ? 'Helper stopped'
            : state === 'failed'
              ? 'Failed'
              : 'Timed out',
        tone: 'danger',
        sentence: update.reason,
        offered: true,
        canPress: update.can_update,
        action: 'Try again',
        inFlight: false,
        live: `${name}: the update ${state === 'failed' ? 'failed' : 'timed out'}. ${update.reason}`,
      };
    case 'cancelled':
      return {
        label: 'Cancelled',
        tone: 'neutral',
        sentence: update.reason,
        offered: true,
        canPress: update.can_update,
        action: 'Try again',
        inFlight: false,
        live: `${name}: the update was cancelled. ${update.reason}`,
      };
    case 'unsupported':
      // The helper can never be installed there, so a button would be a promise
      // nothing can keep. Said only for a host that is not on the release.
      if (host.version_skew !== 'behind' && host.version_skew !== 'differs') return null;
      return {
        label: byHandLabel(host),
        tone: 'neutral',
        sentence: update.reason,
        offered: false,
        canPress: false,
        action: 'Update',
        inFlight: false,
        live: '',
      };
    default: {
      // No attempt. Said only for a host that is not on the controller's release.
      if (host.version_skew !== 'behind' && host.version_skew !== 'differs') return null;
      return update.can_update
        ? {
            label: 'Can be updated',
            tone: 'neutral',
            sentence: update.reason,
            offered: true,
            canPress: true,
            action: 'Update',
            inFlight: false,
            live: '',
          }
        : {
            label: byHandLabel(host),
            tone: 'neutral',
            sentence: update.reason,
            offered: true,
            canPress: false,
            action: 'Update',
            inFlight: false,
            live: '',
          };
    }
  }
}

/**
 * What the confirmation says before a host is asked to update.
 *
 * Each line is as true as the code behind it. `zoomies upgrade --mode agent`
 * restarts the agent's unit, whose KillMode is `process`, so a stop reaches the
 * agent and not the runners; the restarted agent adopts what it finds running.
 * The restart does not wait for jobs, and the page does not say it does.
 */
export function confirmHostUpdate(
  name: string,
  running: string,
  tag: string,
): {
  title: string;
  description: string;
  consequences: readonly string[];
  confirmLabel: string;
} {
  const target = tag || 'the controller’s release';
  return {
    title: `Update the agent on ${name}`,
    description: `Update the agent on ${name} from ${running || 'its current release'} to ${target}?`,
    consequences: [
      `The agent on ${name} restarts.`,
      'Jobs that are running keep running: their runners stay in place and the new agent takes them over. The restart does not wait for them to finish.',
      `The host reports back when it runs ${target}. This page says the update is done then, and not before.`,
    ],
    confirmLabel: tag ? `Update to ${tag}` : 'Update',
  };
}

/**
 * The three figures a closed host card keeps in view: how much of the machine's
 * CPU, memory and disk is in use.
 *
 * They are the capacity map's own arithmetic (hostSeries.ts), not a second
 * opinion, so the newest point on that chart and this card are one figure by
 * construction. Amber is drawn where the product itself acts on a figure, by
 * the rule it uses for that resource: the scheduler's pressure line for CPU
 * (without the CPU it lent to runners), the host reserve it holds new starts at
 * for memory, and the doctor's low-disk rule for the disk.
 *
 * Route-only, like health-card.ts: the card is the only caller.
 */
import type { Host, HostSample } from '$lib/api/types';
import { NO_VALUE, formatMegabytes, formatNumber } from '$lib/format';
import { PRESSURE, liveSample, metricValue } from '$lib/insights/hostSeries';
import { throttled } from '$lib/status';
import { DISK_LOW_FLOOR_MB, DISK_LOW_PERCENT, diskIsLow } from './health-card';

export type VitalKey = 'cpu' | 'memory' | 'disk';

export interface Vital {
  key: VitalKey;
  /** "CPU", "Memory", "Disk". */
  label: string;
  /** The share of the machine in use, 0 to 100 and unrounded; null where it is not measured. */
  percent: number | null;
  /** The share as the card says it: "34%", or the absent-value mark. */
  value: string;
  /** What the share is of: "8 vCPU", "6.4 / 16 GB". Empty where the machine's size is unknown. */
  detail: string;
  /** Past the line where the product itself starts to act on it, by its own rule for this resource. */
  tight: boolean;
  /** One sentence for the tooltip and for assistive technology, so colour is never the only cue. */
  summary: string;
}

export interface Vitals {
  /** Always CPU, memory and disk in that order, so the card's layout does not move. */
  items: Vital[];
  /** Why nothing could be measured, when nothing could; empty while any figure is. */
  unavailable: string;
}

const LABEL: Record<VitalKey, string> = { cpu: 'CPU', memory: 'Memory', disk: 'Disk' };
const KEYS: readonly VitalKey[] = ['cpu', 'memory', 'disk'];

const MB_PER_GB = 1024;
const MB_PER_TB = 1024 * MB_PER_GB;

/**
 * "6.4 / 16 GB", or "16 GB" with nothing used to pair it with. Written in
 * terabytes from one up, because the pair sits in a narrow column and
 * "1,024 / 2,048 GB" does not fit it. One decimal under ten and none above:
 * 6.4 is worth its digit, 158.2 is noise.
 *
 * Under a tenth of a terabyte used, the pair stays in gigabytes: 20 GB of a
 * terabyte would round to "0 / 1 TB", which says less than the share beside it,
 * and a tenth is the least that survives the decimal place.
 */
function sizeText(totalMb: number, usedMb: number | null): string {
  const tb = totalMb >= MB_PER_TB && (usedMb === null || usedMb >= MB_PER_TB / 10);
  const per = tb ? MB_PER_TB : MB_PER_GB;
  const figure = (mb: number) => {
    const n = mb / per;
    return formatNumber(n < 10 ? Math.round(n * 10) / 10 : Math.round(n));
  };
  const unit = tb ? 'TB' : 'GB';
  return usedMb === null
    ? `${figure(totalMb)} ${unit}`
    : `${figure(usedMb)} / ${figure(totalMb)} ${unit}`;
}

function detailOf(key: VitalKey, host: Host, measured: boolean): string {
  switch (key) {
    case 'cpu':
      return (host.cpus ?? 0) > 0 ? `${formatNumber(host.cpus)} vCPU` : '';
    case 'memory': {
      const total = host.memory_mb ?? 0;
      if (total <= 0) return '';
      const used = Math.max(0, total - (host.usage?.memory_available_mb ?? 0));
      return sizeText(total, measured ? used : null);
    }
    case 'disk': {
      const total = host.disk_total_mb ?? 0;
      if (total <= 0) return '';
      const used = Math.max(0, total - (host.disk_free_mb ?? 0));
      return sizeText(total, measured ? used : null);
    }
  }
}

/** Why a figure is missing, in words that say what to do about it where there is something to do. */
function reasonOf(key: VitalKey, host: Host, silent: boolean): string {
  if (silent) return 'No heartbeat, so no figure is shown as current.';
  if (host.resources_known === false)
    return "This agent has not reported its machine's size, usage or disk. Upgrade the agent and the figures appear on its next heartbeat.";
  if (key === 'disk') return 'This agent has not reported its disk.';
  // A throttle outlives the sample that put it there: the rung stands on the last
  // measurements and is lifted after ten minutes without a fresh one, so "cannot
  // be throttled" would be untrue of a host whose card says it is.
  if (!host.usage_fresh)
    return throttled(host.throttle)
      ? 'Current usage unavailable. The throttle stands on its last measurements and lifts after ten minutes without a fresh one.'
      : 'Current usage unavailable. Placement uses configured capacity and reservations, and this host cannot be throttled.';
  return key === 'cpu'
    ? 'This agent has not reported CPU usage.'
    : 'This agent has not reported available memory.';
}

/** The CPU elastic CPU has lent to runners, as a share of the whole host. Zero where none is. */
function lentOf(host: Host): number {
  return Math.max(host.usage?.lent_cpu_percent ?? 0, 0);
}

/**
 * What the host holds back of its memory: the machine less what may be placed on
 * it, which is the operator's reserve or the floor under it, whichever is larger.
 * Read from the two figures the API sends, so the card never has to know the
 * floors (5% with a 512 MB minimum, and a gigabyte more where the controller
 * runs). A reserve that covers the machine arrives as no allocatable memory at
 * all, which is the whole machine held back.
 */
function reserveOf(host: Host): number {
  return Math.max((host.memory_mb ?? 0) - (host.allocatable_memory_mb ?? 0), 0);
}

/**
 * Whether the scheduler would act on this figure, by the rule it uses for that
 * resource. The three are not one rule, and a card that drew one line through
 * all of them would be amber where the scheduler does nothing:
 *
 * - CPU: from 85%, counted without what elastic CPU lent to runners. That load
 *   is the plan's own choice, and counting it would have a boost trip the very
 *   limit that then withdraws it.
 * - Memory: not a share at all. New starts are held when available memory is at
 *   or below the host's reserve, so a host 94% used can have room to spare.
 * - Disk: the doctor's rule for a low disk.
 *
 * The comparison is on the raw figure, as the scheduler's is, and the value
 * beside the bar is that figure rounded: 84.6% reads "85%" and is not past
 * the line. Keep in step with internal/scheduler/headroom.go.
 */
function pressed(key: VitalKey, host: Host, sample: HostSample): boolean {
  switch (key) {
    case 'cpu': {
      const cpu = sample.cpu_percent;
      return cpu !== undefined && cpu - lentOf(host) >= PRESSURE;
    }
    case 'memory': {
      const available = sample.memory_available_mb;
      return available !== undefined && (host.memory_mb ?? 0) > 0 && available <= reserveOf(host);
    }
    case 'disk':
      return diskIsLow(host.disk_free_mb ?? 0, host.disk_total_mb ?? 0);
  }
}

/**
 * What a figure's colour means, in words, so that colour is never the only cue.
 * Empty where there is nothing to add.
 */
function noteOf(key: VitalKey, host: Host, sample: HostSample, tight: boolean): string {
  switch (key) {
    case 'disk':
      return tight
        ? `Low: the Work directory free space check warns below ${DISK_LOW_PERCENT}% or ${DISK_LOW_FLOOR_MB / MB_PER_GB} GB free.`
        : '';
    case 'memory':
      return tight
        ? `Available memory is at or below the ${formatMegabytes(reserveOf(host))} reserve, so the scheduler holds new starts here.`
        : '';
    case 'cpu': {
      const lent = lentOf(host);
      if (tight)
        return lent > 0
          ? `From ${PRESSURE}% of the CPU not lent to runners the scheduler places one runner at a time here.`
          : `From ${PRESSURE}% the scheduler places one runner at a time here.`;
      // Busy, but only because runners were lent CPU. A bar at 92% that is not
      // amber would otherwise look like a mistake, and the capacity map beside
      // it still draws the raw figure.
      return lent > 0 && (sample.cpu_percent ?? 0) >= PRESSURE
        ? `${formatNumber(Math.round(lent))}% of it is CPU lent to runners, which the scheduler does not count as pressure.`
        : '';
    }
  }
}

function summaryOf(item: Omit<Vital, 'summary'>, reason: string, note: string): string {
  if (item.percent === null) return `${item.label}: not shown as current. ${reason}`;
  const sentence = `${item.label}: ${item.value} ${item.key === 'disk' ? 'full' : 'in use'}${item.detail ? `, ${item.detail}` : ''}.`;
  return note ? `${sentence} ${note}` : sentence;
}

export function hostVitals(host: Host, now: number): Vitals {
  // A host that has stopped sending heartbeats shows nothing as current. The
  // disk figure is whatever the agent last said, and beside "No heartbeat since
  // twenty minutes ago" it would read as now.
  const silent = host.healthy === false;
  const sample = liveSample(host, now);
  const items = KEYS.map((key): Vital => {
    const percent = silent ? null : metricValue(sample, key);
    const tight = percent !== null && pressed(key, host, sample);
    const item = {
      key,
      label: LABEL[key],
      percent,
      value: percent === null ? NO_VALUE : `${Math.round(percent)}%`,
      detail: detailOf(key, host, percent !== null),
      tight,
    };
    return {
      ...item,
      summary: summaryOf(item, reasonOf(key, host, silent), noteOf(key, host, sample, tight)),
    };
  });
  const measured = items.some((item) => item.percent !== null);
  return { items, unavailable: measured ? '' : reasonOf('cpu', host, silent) };
}

/**
 * What the Add a host dialog knows about Windows, in one place.
 *
 * Windows is a platform the agent runs on, not yet one the project has
 * qualified: the support matrix (`roadmap/support-and-measurement.md`) moves
 * its row only when a person has run a job on a real Windows machine and kept
 * the evidence. Until then the dialog says so, and says it from one constant so
 * that the day the row moves is a one-line change here and not a hunt through
 * components.
 */

/** Flip to true in the same change that moves the Windows row in the support matrix. */
export const WINDOWS_QUALIFIED = false;

export type HostOS = 'linux' | 'windows';

/**
 * The operating system the person is most likely adding a host for: the one
 * their browser is on. Most people add a host from the machine they are at, and
 * the choice is one click away when they are not. macOS gets the Linux command,
 * which is the shell installer.
 */
export function defaultHostOS(platform: string = browserPlatform()): HostOS {
  return /win/i.test(platform) && !/darwin/i.test(platform) ? 'windows' : 'linux';
}

function browserPlatform(): string {
  if (typeof navigator === 'undefined') return '';
  const nav = navigator as Navigator & { userAgentData?: { platform?: string } };
  return nav.userAgentData?.platform || nav.platform || '';
}

/** The host selector that places a pool's runners on Windows hosts, and only those. */
export const WINDOWS_HOST_SELECTOR = 'os=windows';

/**
 * A host the Windows agent enrolled: it reports `os=windows` and offers only
 * the process backend (there are no Windows containers here), so a pool has to
 * name that backend and ask for the OS to reach it.
 */
export function isWindowsProcessHost(
  host: { os?: string; backends?: string[] } | null | undefined,
): boolean {
  return Boolean(host && host.os === 'windows' && (host.backends ?? []).includes('process'));
}

/**
 * The activity matrix's arithmetic: which square an interval is, how it is
 * painted, what its label says, and how a job arriving over the stream lands
 * in it.
 *
 * Pure functions with no DOM and no clock of their own, so the calendar can be
 * tested in Node and so the Overview and the Usage page -- which draw the same
 * squares from the same usage buckets -- cannot drift in what a square means.
 */
import type { Job, UsageRow } from '../api/types';
import { formatNumber, pluralise, toMillis } from '../format';
import { outcomeOf } from '../outcomes';

export { outcomeOf };

/** One interval of the usage history, exactly as `GET /usage` reports it. */
export type ActivityBucket = NonNullable<UsageRow['history']>[number];

/**
 * The API's interval widths: an hour, a day, and every whole number of hours a
 * day divides into. The route's own rule is hourly up to 48 hours and daily
 * beyond; the rest are asked for, by the ranges that cut a day into squares.
 */
export type Interval = 'hour' | '2h' | '3h' | '4h' | '6h' | '8h' | '12h' | 'day';

/**
 * What the squares are coloured by. Outcomes is the default and the one the
 * Overview opens on; the others recolour the same squares by a different
 * figure, so a queue that backs up every Monday or a pool that hits its
 * ceiling every night is a shape rather than a table.
 */
export type ActivityMode = 'outcomes' | 'queue' | 'runtime' | 'capacity';

export const MODES: ReadonlyArray<{ value: ActivityMode; label: string }> = [
  { value: 'outcomes', label: 'Job outcomes' },
  { value: 'queue', label: 'Queued jobs' },
  { value: 'runtime', label: 'Runner time' },
  { value: 'capacity', label: 'Capacity reached' },
];

/** Four steps of colour above "nothing", as a contribution graph has. */
export type Level = 0 | 1 | 2 | 3 | 4;

/**
 * What kind of square this is. Colour never carries it alone: a failing square
 * has a hole in it, a waiting square is hollow, and an unobserved one is
 * dashed, so the calendar reads in greyscale and to anyone who cannot tell
 * the green from the red.
 */
export type CellKind = 'quiet' | 'healthy' | 'failing' | 'waiting' | 'active' | 'unsampled';

/** The status hues a square may use. Fixed meanings; see docs/ui-guidelines.md. */
export type CellTone = 'idle' | 'danger' | 'pending' | 'busy';

export interface CellPaint {
  kind: CellKind;
  tone: CellTone;
  level: Level;
}

export const HOUR_MS = 3_600_000;
export const DAY_MS = 24 * HOUR_MS;

/** The width of one bucket, in milliseconds. */
export function intervalWidth(interval: Interval): number {
  if (interval === 'day') return DAY_MS;
  if (interval === 'hour') return HOUR_MS;
  return parseInt(interval, 10) * HOUR_MS;
}

/** How many buckets of this width a day is cut into: one, three for eight hours, 24 for an hour. */
export function slicesPerDay(interval: Interval): number {
  return Math.round(DAY_MS / intervalWidth(interval));
}

/**
 * The most buckets narrower than a day the API will cut a row into: a
 * fortnight of hours, or 56 days of four hours, or 112 of eight.
 */
export const MAX_SUB_DAILY_BUCKETS = 14 * 24;

/**
 * The square a window of this length is drawn in: the narrowest of the
 * widths the Overview's ranges use that the API will cut the whole window
 * into. A week is the punch card of hours, a month six squares a day, a
 * quarter three, and anything longer whole days -- so a window chosen on the
 * Usage page is drawn the way the Overview draws one as long.
 *
 * Measured in elapsed time, which is what the API bounds: a fortnight that
 * takes in a clock change is an hour longer than 336 hours, and gets
 * four-hour squares rather than a refusal.
 */
export function matrixInterval(span: number): Interval {
  for (const interval of ['hour', '4h', '8h'] as const) {
    if (span <= MAX_SUB_DAILY_BUCKETS * intervalWidth(interval)) return interval;
  }
  return 'day';
}

export function emptyBucket(from: string): ActivityBucket {
  return {
    from,
    queued: 0,
    started: 0,
    succeeded: 0,
    failed: 0,
    cancelled: 0,
    unknown: 0,
    execution_seconds: 0,
    allocated_seconds: 0,
    capacity_samples: 0,
    capacity_reached: 0,
  };
}

/** Add one bucket's figures into another, in place. */
export function addInto(target: ActivityBucket, source: ActivityBucket): void {
  target.queued += source.queued;
  target.started += source.started;
  target.succeeded += source.succeeded;
  target.failed += source.failed;
  target.cancelled += source.cancelled;
  target.unknown += source.unknown;
  target.execution_seconds += source.execution_seconds;
  target.allocated_seconds += source.allocated_seconds;
  target.capacity_samples += source.capacity_samples;
  target.capacity_reached += source.capacity_reached;
}

/** How many jobs finished in a bucket, however they finished. */
export function completedIn(b: ActivityBucket): number {
  return b.succeeded + b.failed + b.cancelled + b.unknown;
}

/**
 * Every row's history summed into one series, oldest first. The report is
 * grouped -- by pool, by repository -- and the matrix is about the fleet, so
 * the groups are added back together here.
 */
export function mergeHistories(rows: readonly UsageRow[]): ActivityBucket[] {
  const map = new Map<number, ActivityBucket>();
  for (const row of rows) {
    for (const b of row.history ?? []) {
      const at = toMillis(b.from);
      if (at === null) continue;
      const existing = map.get(at);
      if (existing) addInto(existing, b);
      else map.set(at, { ...b });
    }
  }
  return [...map.entries()].sort((a, b) => a[0] - b[0]).map(([, b]) => b);
}

/**
 * A complete series for a window: one bucket per interval from `from`, with
 * whatever the API reported laid over it.
 *
 * The API leaves out a group with nothing to say and a window with no jobs at
 * all comes back with no history whatsoever, so the empty squares of a quiet
 * fortnight have to be made here rather than read.
 */
export function fillWindow(
  buckets: readonly ActivityBucket[],
  from: Date,
  count: number,
  interval: Interval,
): ActivityBucket[] {
  const width = intervalWidth(interval);
  const start = from.getTime();
  const out: ActivityBucket[] = [];
  for (let i = 0; i < count; i++) out.push(emptyBucket(new Date(start + i * width).toISOString()));
  for (const b of buckets) {
    const at = toMillis(b.from);
    if (at === null) continue;
    const i = Math.floor((at - start) / width);
    const target = out[i];
    if (target) addInto(target, b);
  }
  return out;
}

/** Midnight at the start of `at`'s local day. */
export function startOfLocalDay(at: Date): Date {
  return new Date(at.getFullYear(), at.getMonth(), at.getDate());
}

/** The same local time, `days` calendar days later. Survives daylight saving. */
export function addDays(at: Date, days: number): Date {
  return new Date(at.getFullYear(), at.getMonth(), at.getDate() + days, at.getHours());
}

/** The calendar date, `YYYY-MM-DD`, in local time: what the Jobs and Usage pages filter by. */
export function localDate(at: Date): string {
  const two = (n: number) => String(n).padStart(2, '0');
  return `${at.getFullYear()}-${two(at.getMonth() + 1)}-${two(at.getDate())}`;
}

/** Monday is 0. A calendar that starts on Sunday is a calendar for shops. */
export function weekday(at: Date): number {
  return (at.getDay() + 6) % 7;
}

export interface CalendarWindow {
  /** Midnight at the start of the first Monday, local time. */
  from: Date;
  /** Exactly `days` elapsed days after `from`, so every bucket has a day. */
  to: Date;
  days: number;
}

/**
 * The window a calendar of `weeks` columns ending today covers: from the
 * Monday `weeks - 1` weeks ago, through the end of today.
 *
 * `to` is elapsed rather than calendar time on purpose. The API cuts elapsed
 * 24-hour buckets from `from`, so asking for a `to` that is a whole number of
 * them is what keeps bucket `i` and calendar day `i` the same thing across a
 * daylight-saving change -- an hour adrift within the day, never a day out.
 */
export function calendarWindow(weeks: number, now: Date = new Date()): CalendarWindow {
  const today = startOfLocalDay(now);
  const monday = addDays(today, -weekday(today));
  const from = addDays(monday, -7 * (weeks - 1));
  const tomorrow = addDays(today, 1);
  const days = Math.round((tomorrow.getTime() - from.getTime()) / DAY_MS);
  return { from, to: new Date(from.getTime() + days * DAY_MS), days };
}

export interface RangeWindow {
  /** Midnight at the start of the first day, local time. */
  from: Date;
  /** `count` whole buckets after `from`, elapsed rather than calendar time. */
  to: Date;
  /** How many buckets the window is. */
  count: number;
  interval: Interval;
}

/**
 * The window of the last `days` days, today included, cut into buckets of
 * the given width. A day of hours is a row of twenty-four squares; a week of
 * them is the punch card that shows when the fleet is busy; a month of
 * four-hour buckets is a calendar with six squares to the day.
 */
export function rangeWindow(days: number, interval: Interval, now: Date = new Date()): RangeWindow {
  const from = addDays(startOfLocalDay(now), -(days - 1));
  const count = days * slicesPerDay(interval);
  return { from, to: new Date(from.getTime() + count * intervalWidth(interval)), count, interval };
}

export interface CalendarCell {
  /** Index into the series this cell was cut from. */
  index: number;
  /** When the cell begins on the local clock: the calendar day, or the hour a slice of it starts at. */
  date: Date;
  bucket: ActivityBucket;
}

export interface CalendarColumn {
  /** The month's short name, on the column where a month begins. */
  label: string | null;
  /**
   * Seven days, Monday first, each `slices` cells long and in order through
   * the day -- so weekday `r`'s slice `k` is `cells[r * slices + k]`. Null
   * where the window has no such day.
   */
  cells: Array<CalendarCell | null>;
}

const MONTH = {
  short: new Intl.DateTimeFormat(undefined, { month: 'short' }),
  narrow: new Intl.DateTimeFormat(undefined, { month: 'narrow' }),
};

/**
 * Buckets laid out as a contribution graph: a column per week, a row per
 * weekday. `first` is the local day of bucket 0.
 *
 * A day is `slices` buckets, one after another -- one for daily buckets,
 * three for eight-hour ones -- so bucket `i` is slice `i % slices` of day
 * `i / slices`, and each day of the week holds that many cells side by side.
 * A range that could only draw a month as five columns of squares draws it
 * as five columns of six instead, and the band has something to fill itself
 * with that is not white.
 *
 * Placed by index rather than by the time a bucket starts, which is what the
 * window above guarantees: the API cuts elapsed buckets from `from`, so after
 * a daylight-saving change a slice is an hour adrift of the clock it is
 * labelled with -- an hour out within the day, never a day out.
 */
export function calendar(
  buckets: readonly ActivityBucket[],
  first: Date,
  slices = 1,
): CalendarColumn[] {
  const columns: CalendarColumn[] = [];
  const offset = weekday(first);
  const hours = 24 / slices;
  buckets.forEach((bucket, index) => {
    const day = Math.floor(index / slices);
    const slice = index % slices;
    const column = Math.floor((day + offset) / 7);
    const row = (day + offset) % 7;
    let col = columns[column];
    if (!col) {
      col = { label: null, cells: Array.from({ length: 7 * slices }, () => null) };
      columns[column] = col;
    }
    const date = addDays(first, day);
    if (slice > 0) date.setHours(slice * hours);
    col.cells[row * slices + slice] = { index, date, bucket };
  });
  monthLabels(columns).forEach((label, c) => {
    columns[c]!.label = label;
  });
  return columns;
}

/**
 * A month's name above the week it begins in, for whichever columns are on
 * screen. Two adjacent labels would overlap at this width, so the earlier
 * gives way, which is the first column when the window happens to start in
 * the last days of a month.
 *
 * A year on a phone is columns a few pixels across, and "May" and "Jun" four
 * of them apart run into each other; there the caller asks for the one-letter
 * names instead, which the row of them still reads as a year.
 */
export function monthLabels(
  columns: readonly CalendarColumn[],
  width: 'short' | 'narrow' = 'short',
): Array<string | null> {
  const labels: Array<string | null> = columns.map(() => null);
  let previous = -1;
  columns.forEach((col, c) => {
    const start = col.cells.find((cell) => cell !== null);
    if (!start) return;
    const month = start.date.getMonth() + 12 * start.date.getFullYear();
    if (month !== previous) labels[c] = MONTH[width].format(start.date);
    previous = month;
  });
  for (let c = 0; c + 1 < labels.length; c++) {
    if (labels[c] && labels[c + 1]) labels[c] = null;
  }
  return labels;
}

export interface HourRow {
  /** Midnight of the local day this row is. */
  date: Date;
  /** Twenty-four slots; null where the window has no such hour. */
  cells: Array<CalendarCell | null>;
}

/**
 * Hourly buckets laid out with a row per local day and a column per hour.
 * Each bucket is placed by the local time it starts at, so a daylight-saving
 * change puts an hour in the slot it was actually lived in.
 */
export function hourGrid(buckets: readonly ActivityBucket[]): HourRow[] {
  const rows = new Map<number, HourRow>();
  buckets.forEach((bucket, index) => {
    const at = toMillis(bucket.from);
    if (at === null) return;
    const date = new Date(at);
    const day = startOfLocalDay(date);
    let row = rows.get(day.getTime());
    if (!row) {
      row = { date: day, cells: Array.from({ length: 24 }, () => null) };
      rows.set(day.getTime(), row);
    }
    const hour = date.getHours();
    const existing = row.cells[hour];
    // The hour a clock change repeats is two buckets in one slot.
    if (existing) addInto(existing.bucket, bucket);
    else row.cells[hour] = { index, date, bucket: { ...bucket } };
  });
  return [...rows.values()].sort((a, b) => a.date.getTime() - b.date.getTime());
}

/**
 * The darkness of a square: nothing, then quarters of the busiest square in
 * the window, as a contribution graph does it. The busiest square is always
 * the darkest, so a fleet that runs ten jobs a day and one that runs a
 * thousand both get a calendar with a full range of colour.
 */
export function level(value: number, max: number): Level {
  if (value <= 0 || max <= 0) return 0;
  return Math.min(4, Math.max(1, Math.ceil((4 * value) / max))) as Level;
}

/**
 * The share of a square's completions that failed, banded. Fixed bands rather
 * than quarters of the worst square: "half of everything failed" should look
 * the same on a good week as on a bad one.
 */
export function failureLevel(failed: number, completed: number): Level {
  if (failed <= 0) return 0;
  const share = completed > 0 ? failed / completed : 1;
  if (share < 0.1) return 1;
  if (share < 0.25) return 2;
  if (share < 0.5) return 3;
  return 4;
}

/** The share of observed pool-minutes that were blocked on capacity, banded the same way. */
export function capacityLevel(reached: number, samples: number): Level {
  if (samples <= 0 || reached <= 0) return 0;
  const share = reached / samples;
  if (share < 0.05) return 1;
  if (share < 0.25) return 2;
  if (share < 0.5) return 3;
  return 4;
}

/** The busiest square in each figure, which is what the quarters are cut from. */
export interface Scale {
  completed: number;
  queued: number;
  execution: number;
}

export function scaleOf(buckets: readonly ActivityBucket[]): Scale {
  let completed = 0;
  let queued = 0;
  let execution = 0;
  for (const b of buckets) {
    completed = Math.max(completed, completedIn(b));
    queued = Math.max(queued, b.queued);
    execution = Math.max(execution, b.execution_seconds);
  }
  return { completed, queued, execution };
}

/** How one square is painted under a mode. */
export function paint(b: ActivityBucket, mode: ActivityMode, scale: Scale): CellPaint {
  switch (mode) {
    case 'queue': {
      const l = level(b.queued, scale.queued);
      return { kind: l ? 'active' : 'quiet', tone: 'pending', level: l };
    }
    case 'runtime': {
      const l = level(b.execution_seconds, scale.execution);
      return { kind: l ? 'active' : 'quiet', tone: 'busy', level: l };
    }
    case 'capacity': {
      if (b.capacity_samples === 0) return { kind: 'unsampled', tone: 'pending', level: 0 };
      const l = capacityLevel(b.capacity_reached, b.capacity_samples);
      return { kind: l ? 'active' : 'quiet', tone: 'pending', level: l };
    }
    default: {
      const completed = completedIn(b);
      if (b.failed > 0) {
        return { kind: 'failing', tone: 'danger', level: failureLevel(b.failed, completed) };
      }
      if (completed > 0) {
        return { kind: 'healthy', tone: 'idle', level: level(completed, scale.completed) };
      }
      const waiting = Math.max(b.queued, b.started);
      if (waiting > 0) {
        return { kind: 'waiting', tone: 'pending', level: level(waiting, scale.queued) };
      }
      return { kind: 'quiet', tone: 'idle', level: 0 };
    }
  }
}

/** Whether any square in the series carries capacity telemetry at all. */
export function hasCapacity(buckets: readonly ActivityBucket[]): boolean {
  return buckets.some((b) => b.capacity_samples > 0);
}

/* -- words ---------------------------------------------------------------- */

const DAY_LONG = new Intl.DateTimeFormat(undefined, {
  weekday: 'long',
  day: 'numeric',
  month: 'long',
  year: 'numeric',
});
const DAY_SHORT = new Intl.DateTimeFormat(undefined, { day: 'numeric', month: 'short' });
const DAY_WEEKDAY = new Intl.DateTimeFormat(undefined, {
  weekday: 'short',
  day: 'numeric',
  month: 'short',
});
const CLOCK = new Intl.DateTimeFormat(undefined, { hour: '2-digit', minute: '2-digit' });

/**
 * "Tuesday 9 September 2026", "9 Sep, 14:00 to 15:00", or "Tue 9 Sep, 08:00
 * to 16:00". A slice of a day names its weekday, because in the calendar it
 * sits in that weekday's row; an hour is a week at most and its row says the
 * date.
 */
export function intervalName(at: Date, interval: Interval): string {
  if (interval === 'day') return DAY_LONG.format(at);
  if (interval === 'hour') {
    const end = new Date(at.getTime() + HOUR_MS);
    return `${DAY_SHORT.format(at)}, ${CLOCK.format(at)} to ${CLOCK.format(end)}`;
  }
  // The wall clock rather than elapsed time: a slice is the stretch of the
  // day its square stands for, so the last one ends at midnight even on the
  // day the clocks change.
  const end = new Date(at);
  end.setHours(at.getHours() + intervalWidth(interval) / HOUR_MS);
  return `${DAY_WEEKDAY.format(at)}, ${CLOCK.format(at)} to ${CLOCK.format(end)}`;
}

/**
 * What a square is, as a noun for the words around it: "the selected day",
 * "the selected hour", and for a slice of a day, "the selected hours".
 */
export function intervalNoun(interval: Interval): 'day' | 'hour' | 'hours' {
  if (interval === 'day') return 'day';
  return interval === 'hour' ? 'hour' : 'hours';
}

/** Seconds as the hours an invoice is written in: "6.4 h". */
export function hours(seconds: number): string {
  return `${(seconds / 3600).toFixed(seconds >= 36_000 ? 0 : 1)} h`;
}

/** The one line a square is summed up in: "38 jobs finished, 2 failed". */
export function headline(b: ActivityBucket): string {
  const completed = completedIn(b);
  if (completed > 0) {
    const finished = `${pluralise(completed, 'job')} finished`;
    return b.failed > 0 ? `${finished}, ${formatNumber(b.failed)} failed` : finished;
  }
  if (b.queued > 0 || b.started > 0) {
    return `${pluralise(Math.max(b.queued, b.started), 'job')} queued, none finished`;
  }
  return 'No jobs';
}

/**
 * Everything a square knows, as one sentence. It is the square's accessible
 * name and the text a screen reader gets, so nothing may live only in the
 * tooltip.
 */
export function describe(b: ActivityBucket, at: Date, interval: Interval): string {
  const parts = [
    `${headline(b)}: ${b.succeeded} succeeded, ${b.failed} failed, ${b.cancelled} cancelled or skipped, ${b.unknown} unknown`,
    `${b.queued} queued, ${b.started} started`,
  ];
  if (b.execution_seconds > 0) parts.push(`${hours(b.execution_seconds)} executing`);
  if (b.capacity_samples > 0) {
    parts.push(
      `${formatNumber(b.capacity_reached)} of ${formatNumber(b.capacity_samples)} observed pool-minutes at capacity`,
    );
  }
  return `${intervalName(at, interval)}. ${parts.join('; ')}.`;
}

/** The window's totals, for the panel's header. */
export interface Summary {
  completed: number;
  succeeded: number;
  failed: number;
  cancelled: number;
  unknown: number;
  queued: number;
  execution_seconds: number;
  /** Intervals with any activity at all. */
  active: number;
}

export function summarise(buckets: readonly ActivityBucket[]): Summary {
  const s: Summary = {
    completed: 0,
    succeeded: 0,
    failed: 0,
    cancelled: 0,
    unknown: 0,
    queued: 0,
    execution_seconds: 0,
    active: 0,
  };
  for (const b of buckets) {
    s.succeeded += b.succeeded;
    s.failed += b.failed;
    s.cancelled += b.cancelled;
    s.unknown += b.unknown;
    s.queued += b.queued;
    s.execution_seconds += b.execution_seconds;
    if (completedIn(b) > 0 || b.queued > 0 || b.started > 0) s.active += 1;
  }
  s.completed = s.succeeded + s.failed + s.cancelled + s.unknown;
  return s;
}

/* -- the stream ------------------------------------------------------------- */

/**
 * The jobs already counted since the last fetch, per count. A `job.updated`
 * frame arrives once per change of state and again whenever GitHub adds a
 * detail to a finished job, so without this a job that failed at step three
 * would be counted as failed twice.
 */
export interface Seen {
  queued: Set<string>;
  started: Set<string>;
  completed: Set<string>;
}

export function newSeen(): Seen {
  return { queued: new Set(), started: new Set(), completed: new Set() };
}

/** The bucket a moment falls in, or -1 when it is outside the series. */
export function bucketIndex(
  series: readonly ActivityBucket[],
  at: number,
  interval: Interval,
): number {
  const width = intervalWidth(interval);
  let lo = 0;
  let hi = series.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const start = toMillis(series[mid]?.from) ?? 0;
    if (at < start) hi = mid - 1;
    else if (at >= start + width) lo = mid + 1;
    else return mid;
  }
  return -1;
}

/**
 * Fold one job frame into the series, returning a new series when a square
 * changed and null when nothing did.
 *
 * Only moments after `since` -- when the series was fetched -- are counted:
 * anything earlier is already in it. Counts move; runner time does not, since
 * a frame cannot say how much of a job's running fell inside which hour, and
 * a guess there would be a claim on a page that is read by finance. The next
 * fetch carries the exact figure.
 */
export function foldJob(
  series: readonly ActivityBucket[],
  interval: Interval,
  job: Job,
  since: number,
  seen: Seen,
): ActivityBucket[] | null {
  if (!job.id) return null;
  const id = job.id;
  const touched = new Map<number, ActivityBucket>();
  const bucket = (at: string | null | undefined): ActivityBucket | null => {
    const ms = toMillis(at);
    if (ms === null || ms < since) return null;
    const i = bucketIndex(series, ms, interval);
    if (i < 0) return null;
    let copy = touched.get(i);
    if (!copy) {
      copy = { ...series[i]! };
      touched.set(i, copy);
    }
    return copy;
  };
  if (!seen.queued.has(id)) {
    const b = bucket(job.queued_at);
    if (b) {
      b.queued += 1;
      seen.queued.add(id);
    }
  }
  if (!seen.started.has(id) && (job.state === 'in_progress' || job.state === 'completed')) {
    const b = bucket(job.started_at);
    if (b) {
      b.started += 1;
      seen.started.add(id);
    }
  }
  if (!seen.completed.has(id) && job.state === 'completed') {
    const b = bucket(job.completed_at);
    if (b) {
      b[outcomeOf(job)] += 1;
      seen.completed.add(id);
    }
  }
  if (touched.size === 0) return null;
  return series.map((b, i) => touched.get(i) ?? b);
}

/**
 * The pure half of the analysis card: how a confidence reads, how a next step
 * becomes a line with a setting and a link, which period a page asks about,
 * and what Eli is handed. Kept out of the component so a unit test can hold it
 * without rendering anything, as the job drawer's why.ts is.
 *
 * The card reasons about nothing. The summary, the confidence and the steps
 * are the controller's, and the same words the CLI, the MCP tools and Eli
 * read, so the page cannot disagree with them; what is here is wording for
 * the evidence's enumerations and the plumbing around the one request.
 */
import type { EliContext } from '../assistant/prompts';
import { sentence, supportHint } from '../errors';
import { capitalise, formatDuration, formatPercent, joinWords } from '../format';
import { readableJobText } from '../jobs/name';

/** How far to lean on a finding, as words: the level, and what was thin. */
export function confidenceWords(c: string, reason?: string | null): string {
  const level = c ? capitalise(c) : 'Unknown';
  const why = reason?.trim();
  return why ? `${level} confidence: ${why}` : `${level} confidence`;
}

export interface StepLine {
  text: string;
  /** The setting to change, named as the settings and the API name it. */
  setting: string | null;
  /** The code's catalog page, to read on in a new tab. */
  href: string | null;
}

/**
 * One next step as the card draws it. The link is the one the controller put
 * on the step (F8: `catalogLink` reads a link a step already carries and
 * cannot make one from a code), so a code the catalog has no page for is shown
 * as the code alone rather than as an address the card made up.
 */
export function stepLine(s: {
  text: string;
  setting?: string;
  code?: string;
  link?: string;
}): StepLine {
  const href = s.code && s.link && /^https?:\/\//.test(s.link) ? s.link : null;
  return { text: s.text, setting: s.setting || null, href };
}

/**
 * The period a page asks about. Its end is always explicit, so the finding on
 * screen is the one anyone asking with the same address is given; the route's
 * own default would have moved on by the time they asked.
 *
 * A page with no window of its own leaves `since` out, so the route takes its
 * own default before that end: a day, or `limits.job_stats_window` where that
 * is shorter. Asking for a day by name would be refused on a fleet that set the
 * limit lower, where the CLI and the tools, which also leave it out, answer.
 *
 * A window that runs past now ends now: the rest has not happened, and a job
 * still waiting would have its wait counted into it. The controller clamps the
 * same way for every caller; doing it here too keeps the period the card
 * describes the one it was given. A window that does not end after it starts
 * asks nothing, and `whyNoWindow` says why where the answer would be.
 */
export function analysisWindow(
  since: string | undefined,
  until: string | undefined,
  now: number,
): { since?: string; until: string } | null {
  const end = Math.min(until ? Date.parse(until) : now, now);
  if (Number.isNaN(end)) return null;
  if (!since) return { until: new Date(end).toISOString() };
  const start = Date.parse(since);
  if (Number.isNaN(start) || start >= end) return null;
  return { since: new Date(start).toISOString(), until: new Date(end).toISOString() };
}

/**
 * Why `analysisWindow` asked nothing, as the card says it in place of a
 * finding: a titled frame with nothing under it says nothing at all. The date
 * picker points out a range that runs backwards, in an alert of its own, and
 * nothing points out one that has not started, where the list is merely empty,
 * so the card names whichever it is. The future one repeats the route's own
 * refusal of a start that is not in the past (ErrSinceNotPast), which is why
 * the page does not ask.
 *
 * Only for a window `analysisWindow` gave null, with the same two bounds; any
 * other has an answer. A bound left out is undefined, as there; one that is
 * there and empty, or not a date, is one the page could not read (Usage's
 * address parses to empty bounds, and does not reach `analysisWindow`).
 */
export function whyNoWindow(since: string | undefined, until: string | undefined): string {
  const start = since === undefined ? Number.NEGATIVE_INFINITY : Date.parse(since);
  // An end left out is now, which a start is after only by not having happened
  // yet, so only an end that was written can make a range run backwards.
  const end = until === undefined ? undefined : Date.parse(until);
  if (Number.isNaN(start) || (end !== undefined && Number.isNaN(end))) {
    return 'The range has a date this page cannot read, so there is no period to analyse.';
  }
  if (end !== undefined && start >= end) {
    return 'The end is before the start, so there is no period to analyse.';
  }
  return 'This period has not started, and an analysis reads only what has already happened; choose a start in the past.';
}

/** The list's filters, as far as the queue-wait card needs to know them. */
export interface QueueListFilters {
  pool_id: readonly string[];
  repo: readonly string[];
  workflow: readonly string[];
  host_id: readonly string[];
  label: readonly string[];
  q: string;
  /** Provisioning statuses the address chose; never the Queued view's default. */
  provisioning?: readonly string[];
  /** Unmatched, when an address keeps the list queued with it on. */
  unmatched?: boolean;
  /** "Include other runners": the list holds jobs another vendor's runners ran. */
  all?: boolean;
}

/**
 * What the Queued view's card covers, and which of the list's filters it does
 * not. The route narrows to one pool or none, and the list beside it can be
 * narrowed by much more; the fleet's answer under a list narrowed to one
 * repository would read as that repository's, and could send an operator to
 * raise the wrong pool's ceiling. So the card says its scope, and names the
 * filters it leaves out rather than borrowing their meaning.
 *
 * The switch for other runners is the odd one out. The list leaves another
 * vendor's jobs out until it is on, and the analysis leaves them out always,
 * so it is named only when on, when the list holds jobs the card does not.
 */
export function queueWaitScope(
  f: QueueListFilters,
  poolName: (id: string) => string,
): { scope: string; unapplied: string | null } {
  const one = f.pool_id.length === 1 ? f.pool_id[0] : undefined;
  const left = [
    f.pool_id.length > 1 ? 'pool' : '',
    f.repo.length ? 'repository' : '',
    f.workflow.length ? 'workflow' : '',
    f.host_id.length ? 'host' : '',
    f.label.length ? 'label' : '',
    f.q.trim() ? 'search' : '',
    f.provisioning?.length ? 'provisioning' : '',
    f.unmatched ? 'unmatched' : '',
  ].filter((w) => w !== '');
  const sentences = [
    left.length
      ? `The list's ${joinWords(left)} ${left.length === 1 ? 'filter is' : 'filters are'} not applied here: this analysis reads every pool, or one pool.`
      : '',
    f.all
      ? "The list's Include other runners switch is not applied here: this analysis leaves out the jobs another vendor's runners ran."
      : '',
  ].filter((s) => s !== '');
  return {
    scope: one ? `Pool ${poolName(one)}` : 'Every pool',
    unapplied: sentences.length ? sentences.join(' ') : null,
  };
}

/**
 * What the failed runners' card covers, and which of the list's filters it
 * does not. The route reads every start in the period, narrowed to the pool
 * and host the page chose; the list beside it also takes a search, which an
 * analysis of starts has no use for. The fleet's answer under a list searched
 * down to one runner would read as that runner's, so the card says what it
 * covers and names the search it leaves out, as the Queued card does its own.
 */
export function startupFailuresScope(
  f: { pool_id: string; host_id: string; q: string },
  name: { pool: (id: string) => string; host: (id: string) => string },
): { scope: string; unapplied: string | null } {
  const covered = [
    f.pool_id ? `Pool ${name.pool(f.pool_id)}` : '',
    f.host_id ? `${f.pool_id ? 'host' : 'Host'} ${name.host(f.host_id)}` : '',
  ].filter((w) => w !== '');
  return {
    scope: covered.length ? covered.join(', ') : 'Every pool and host',
    unapplied: f.q.trim()
      ? "The list's search filter is not applied here: this analysis reads every start in the period, narrowed only by pool and host."
      : null,
  };
}

/** The fields a card's description line is drawn from. */
export interface DescribedFinding {
  analysis: string;
  since: string;
  until: string;
  evidence?: unknown;
}

interface ComparedSides {
  a: { label: string; since: string; until: string };
  b: { label: string; since: string; until: string };
  excluded: readonly string[];
}

/**
 * The line under a card's title: its scope and period. A comparison names
 * each side's own dates instead, since a side can cover less than the period
 * asked for (a release ran for part of it, a roll-up side ends at a midnight)
 * and the asked period would read as the span both cover; and it says what
 * it left out, because that is what every figure below it means.
 */
export function findingDescription(
  f: DescribedFinding,
  format: (iso: string) => string,
  scope?: string,
): string {
  if (f.analysis === 'compare' && f.evidence) {
    const ev = f.evidence as ComparedSides;
    const side = (x: ComparedSides['a']) =>
      `${x.label} from ${format(x.since)} to ${format(x.until)}`;
    const left = joinWords(ev.excluded);
    const out = left
      ? ` ${capitalise(left)} jobs are left out of every figure read from the job rows.`
      : '';
    return `${side(ev.a)}; ${side(ev.b)}.${out}`;
  }
  const period = `${format(f.since)} to ${format(f.until)}`;
  return scope ? `${scope}, ${period}` : period;
}

/**
 * The refusals whose own sentence names a remedy the page has no control for,
 * said instead in terms of what the page does have. Too few releases tells a
 * caller to name the releases with a and b, to widen the period, or to compare
 * by period; the Usage card asks by version with no a and b and never compares
 * periods, so two of the three are not on the page and the third is its range.
 * A Map, since a code is whatever the server sent and a plain object would
 * answer "constructor".
 */
const SAID_ON_THE_PAGE = new Map([
  [
    'analysis.too_few_releases',
    'Fewer than two releases completed a job in this range, so there is no pair to compare; widen the range.',
  ],
]);

/**
 * What a card shows when its analysis was not given, and whether that is a
 * refusal. A 4xx is the route declining a question it understood (a period
 * over limits.job_stats_window, too few releases to compare), in its own
 * sentence that says what to change; on Usage's default day that is the
 * ordinary answer, so it is a status, not an alert. Anything else is a
 * request that failed. A server failure names no cause on purpose and carries
 * its request ID in `detail`, so the card says which request to quote.
 */
export function refusalOf(cause: unknown): { message: string; refused: boolean } {
  const c = (cause ?? {}) as {
    status?: unknown;
    code?: unknown;
    message?: unknown;
    detail?: unknown;
  };
  const status = typeof c.status === 'number' ? c.status : undefined;
  const raw =
    typeof c.message === 'string' && c.message.trim()
      ? c.message
      : 'The analysis could not be read';
  if (status !== undefined && status >= 500) {
    const id = typeof c.detail === 'string' ? /^request (\S+)$/.exec(c.detail)?.[1] : undefined;
    const said = raw.replace(supportHint(), '').trim();
    return { message: `${sentence(said)} ${supportHint(id)}`, refused: false };
  }
  const refused = status !== undefined && status >= 400 && status < 500;
  const onThePage =
    refused && typeof c.code === 'string' ? SAID_ON_THE_PAGE.get(c.code) : undefined;
  return { message: onThePage ?? sentence(raw), refused };
}

/** What the card hands Eli: the fields every finding shares. */
export interface FindingFacts {
  analysis: string;
  since: string;
  until: string;
  summary: string;
  confidence: string;
  confidence_reason?: string;
  next_steps: readonly { text: string; setting?: string; code?: string }[];
  codes: readonly string[];
}

/** The pool or host a card was narrowed to, which its finding does not say. */
export interface AnalysisNarrowing {
  pool?: { id: string; name?: string };
  host?: { id: string; name?: string };
}

/** A name with its id, or the id alone when the page does not know the name. */
function namedWithId(x: { id: string; name?: string }): string {
  return x.name && x.name !== x.id ? `${x.name} (${x.id})` : x.id;
}

/**
 * The finding as the card shows it, named one by one. The evidence stays on
 * the page: it quotes names a workflow wrote, and Eli has the analysis tools
 * to read it whole.
 *
 * What the card was narrowed to goes with it, and so does the instruction to
 * pass it. The prompt tells Eli to check the snapshot with its tools, which
 * read the last day of the whole fleet unless told otherwise, and a finding
 * narrowed to one pool says nothing of the pool ("No start failed in this
 * period") for Eli to repeat.
 */
export function analysisContext(
  title: string,
  f: FindingFacts,
  narrowed: AnalysisNarrowing = {},
): EliContext {
  const passed = joinWords(
    [
      narrowed.pool ? `pool_id ${narrowed.pool.id}` : '',
      narrowed.host ? `host_id ${narrowed.host.id}` : '',
    ].filter((a) => a !== ''),
  );
  const of =
    narrowed.pool && narrowed.host
      ? 'this pool and host'
      : narrowed.pool
        ? 'this pool'
        : narrowed.host
          ? 'this host'
          : 'this fleet';
  return {
    kind: 'analysis',
    title,
    facts: {
      Analysis: f.analysis,
      From: f.since,
      To: f.until,
      Pool: narrowed.pool ? namedWithId(narrowed.pool) : undefined,
      Host: narrowed.host ? namedWithId(narrowed.host) : undefined,
      Summary: f.summary,
      Confidence: confidenceWords(f.confidence, f.confidence_reason),
      'Next steps': f.next_steps.length
        ? f.next_steps.map((s) => (s.setting ? `${s.text} (${s.setting})` : s.text)).join(' ')
        : undefined,
      Codes: f.codes.length ? f.codes.join(', ') : undefined,
    },
    question:
      `What does this analysis mean for ${of}, and what should I change first? ` +
      `To check it against the fleet now, ask for the same analysis again with since ${f.since}, until ${f.until}` +
      `${passed ? `, ${passed}` : ''}; without them it reads the last day of the whole fleet.`,
  };
}

/**
 * A job's repository, workflow and name, the empty ones skipped: with the
 * names withheld every one is empty, and a row of separators would read as
 * names that are blank rather than left out. The step that says they were
 * withheld is the controller's, and the card shows it once.
 */
export function jobWords(e: { repo?: string; workflow?: string; job_name?: string }): string {
  return [e.repo, e.workflow, readableJobText(e.job_name)]
    .map((s) => (s ?? '').trim())
    .filter((s) => s !== '')
    .join(' · ');
}

/**
 * The pool the jobs no pool claimed are counted under, which has no id or name
 * of its own. The MCP tools say it in the same words, so a person and an agent
 * read the row alike.
 */
export const UNCLAIMED_POOL = 'unclaimed (no pool claimed these jobs)';

/**
 * Every pool's longest waits, longest first, as one list, each naming its
 * pool. A row with no pool is the jobs no pool claimed, which would otherwise
 * read as waiting "in" nothing.
 */
export function longestWaits<J extends { wait_seconds: number }>(
  pools: readonly { pool_id: string; pool_name?: string; longest: readonly J[] }[],
  n = 5,
): (J & { pool: string })[] {
  return pools
    .flatMap((p) =>
      p.longest.map((j) => ({ ...j, pool: p.pool_name || p.pool_id || UNCLAIMED_POOL })),
    )
    .sort((a, b) => b.wait_seconds - a.wait_seconds)
    .slice(0, n);
}

