/**
 * Whether one repository in a plan can be migrated, and why not when it cannot.
 *
 * This lives on its own because two places need the same answer: the
 * Repositories step, which decides what an operator may tick, and the wizard,
 * which decides what to tick by default and which repositories to name in the
 * call that opens the pull requests. Those two disagreeing is how a repository
 * that is greyed out on screen ends up in the request anyway.
 */

import type { MigrationRepo } from '$lib/api/types';

/** The API's MaxApplyRepos limit: a migration opens at most this many pull requests. */
export const MAX_SELECTED_REPOSITORIES = 25;

/** How many runs-on lines the migration would rewrite in this repository. */
export function jobsIn(repo: MigrationRepo): number {
  return (repo.workflows ?? []).reduce((n, w) => n + (w.rewrites ?? []).length, 0);
}

/** How many files it would change. */
export function filesIn(repo: MigrationRepo): number {
  return (repo.workflows ?? []).filter((w) => (w.rewrites ?? []).length > 0).length;
}

/** How many runs-on lines it would deliberately leave alone. */
export function skipsIn(repo: MigrationRepo): number {
  return (repo.workflows ?? []).reduce((n, w) => n + (w.skips ?? []).length, 0);
}

/**
 * Whether this repository is one the operator can choose.
 *
 * The test is "it asks for a runner somebody else operates", not "it would
 * change under the mapping guessed so far" -- the labels are mapped on the
 * next step. Being archived is the exception worth spelling out: an archived
 * repository can ask for as many rented runners as it likes, and GitHub still
 * refuses every write to it, so counting its labels alone would tick it, walk
 * the operator through mapping and review, and only then report that nothing
 * could be opened.
 */
export function isMigratable(repo: MigrationRepo): boolean {
  return !repo.error && !repo.archived && (repo.hosted_labels ?? []).length > 0;
}

/**
 * One line saying what this repository would get out of the migration, or why
 * it is not on offer.
 *
 * The order is the order an operator needs the answers in: a repository that
 * could not be read explains itself first, one that cannot be written to next,
 * then what would change, then what was found but not yet mapped -- and only
 * then the several different ways of having nothing to do. "Already on
 * Zoomies" and "nothing to move" look identical in a plan and mean opposite
 * things -- finished work, and work nobody has started -- so they are never
 * collapsed into one sentence.
 */
export function noteFor(repo: MigrationRepo): string {
  if (repo.error) return repo.error;
  if (repo.archived) return 'Archived, accepts no pull requests';

  const jobs = jobsIn(repo);
  const files = filesIn(repo);
  const skipped = skipsIn(repo);
  const labels = repo.hosted_labels ?? [];

  if (jobs > 0) {
    const moved = `${jobs} ${jobs === 1 ? 'job' : 'jobs'} in ${files} ${files === 1 ? 'file' : 'files'}`;
    return repo.on_zoomies ? `${moved}; the rest already on Zoomies` : moved;
  }
  if (labels.length > 0) {
    return `Runs on ${labels.join(', ')}; choose what those become on the next step`;
  }
  if ((repo.workflows ?? []).length === 0) return 'No workflows';
  if (repo.on_zoomies) {
    return skipped > 0 ? `Already on Zoomies; ${skipped} left alone` : 'Already on Zoomies';
  }
  return skipped > 0 ? `Nothing to move; ${skipped} left alone` : 'Nothing to move';
}

import type { CheckoutSelection } from '../api/types';

export interface CheckoutSelectionText {
  runId: string;
  attempt: string;
  jobId: string;
}

const DECIMAL_ID = /^[1-9][0-9]{0,18}$/;
const INT64_MAX = 9223372036854775807n;

/**
 * GitHub's run and job IDs stay strings end to end: a number would round the
 * identity before the server ever saw it, and the server would then read some
 * other run's workflow.
 */
function githubId(text: string, what: string): string {
  const value = text.trim();
  if (!DECIMAL_ID.test(value) || BigInt(value) > INT64_MAX)
    throw new Error(`Enter ${what} as a positive whole number, exactly as GitHub shows it.`);
  return value;
}

/**
 * A run, attempt and job only. The server finds the checkout step in the file
 * itself, so nobody counts positions.
 */
export function parseCheckoutSelection(text: CheckoutSelectionText): CheckoutSelection {
  const attempt = text.attempt.trim();
  if (!/^[1-9][0-9]{0,8}$/.test(attempt))
    throw new Error('Enter the run attempt as a whole number from 1.');
  return {
    run_id: githubId(text.runId, 'the run ID'),
    attempt: Number(attempt),
    github_job_id: githubId(text.jobId, 'the GitHub job ID'),
  };
}

/** A checkout step's time as the page shows it: a measurement, not a saving. */
export function checkoutSeconds(ms: number): string {
  return `${(ms / 1000).toLocaleString(undefined, { maximumFractionDigits: 1 })} s`;
}

/**
 * How a finished job is counted. Kept apart from the state map in status.ts,
 * which imports icon components and so cannot be loaded outside a browser,
 * because the activity matrix's arithmetic counts jobs the same way and is
 * tested in Node.
 */

/** The conclusions GitHub counts as a job going wrong, as the failed filter does. */
export const FAILING_CONCLUSIONS: ReadonlySet<string> = new Set([
  'failure',
  'timed_out',
  'startup_failure',
]);

/** The four ways a completed job is counted, matching the store's split. */
export type Outcome = 'succeeded' | 'failed' | 'cancelled' | 'unknown';

/**
 * Whether a job went wrong on either side: a failing conclusion, or a runner
 * that stopped under it -- including one GitHub still believes is running.
 */
export function jobFailed(job: {
  conclusion?: string | null;
  runner_fault?: string | null;
}): boolean {
  return Boolean(job.runner_fault) || FAILING_CONCLUSIONS.has((job.conclusion ?? '').toLowerCase());
}

/**
 * Which of the four counts a finished job lands in. Unknown is never a
 * success: a job GitHub stopped reporting is not a job that went well.
 */
export function outcomeOf(job: {
  conclusion?: string | null;
  runner_fault?: string | null;
}): Outcome {
  if (jobFailed(job)) return 'failed';
  const conclusion = (job.conclusion ?? '').toLowerCase();
  if (conclusion === 'success') return 'succeeded';
  if (conclusion === 'cancelled' || conclusion === 'skipped') return 'cancelled';
  return 'unknown';
}

import type { Installation } from '../api/types';

/** A repository name never becomes an arbitrary external URL. */
export function activationRepository(value: string, installation: Installation): string | null {
  const repo = value.trim();
  if (!/^[A-Za-z0-9][A-Za-z0-9-]*\/[A-Za-z0-9_.-]+$/.test(repo)) return null;
  if (['.', '..'].includes(repo.split('/')[1] ?? '')) return null;
  const target = installation.target?.toLowerCase();
  if (!target) return null;
  if (installation.target_type === 'repo') return repo.toLowerCase() === target ? repo : null;
  return repo.split('/')[0]?.toLowerCase() === target ? repo : null;
}

export function activationActionsUrl(repo: string, installation: Installation): string | null {
  try {
    const base = new URL(
      installation.web_url || (installation.enterprise ? '' : 'https://github.com'),
    );
    if (base.protocol !== 'https:' || base.username || base.password) return null;
    return `${base.origin}/${repo}/actions/workflows/zoomies-test.yml`;
  } catch {
    return null;
  }
}

/**
 * What the Overview's stage says: one answer to "is anything wrong", in words,
 * from the numbers the page already has.
 *
 * It is a plain function and not a template so the sentence can be held to the
 * numbers by a test. A stage that said "Everything is running" over a fleet with
 * an unhealthy host would be worse than no stage, and that is a mistake a
 * layout change is very good at making without anyone seeing it.
 */

export interface StatusInput {
  /** The problems a person has not put away, worst first. */
  problems: readonly { severity: 'error' | 'warning' | 'info' }[];
  running: number;
  slotsUsed: number;
  slots: number;
  /** Nothing is configured yet: no installation, no pool, no host. */
  setupPending: boolean;
}

export interface StatusLine {
  headline: string;
  accent: string;
  lede: string;
  /** Whether there is something to review, and so a way into it to offer. */
  needsYou: boolean;
}

const NOUN = { error: 'error', warning: 'warning', info: 'note' } as const;

/** "1 error, 2 warnings and a note", worst first: counts, never a problem's own words. */
function counts(problems: StatusInput['problems']): string {
  const parts = (['error', 'warning', 'info'] as const)
    .map((severity) => [severity, problems.filter((p) => p.severity === severity).length] as const)
    .filter(([, n]) => n > 0)
    .map(([severity, n]) => `${n} ${NOUN[severity]}${n === 1 ? '' : 's'}`);
  return parts.length > 1
    ? `${parts.slice(0, -1).join(', ')} and ${parts.at(-1)}`
    : (parts[0] ?? '');
}

const jobs = (n: number): string => `${n} ${n === 1 ? 'job is' : 'jobs are'} running.`;

export function statusLine(input: StatusInput): StatusLine {
  if (input.setupPending) {
    return {
      headline: 'Your fleet is empty.',
      accent: 'Three steps fill it.',
      lede: 'Connect GitHub, give Zoomies a machine to run on, and say which jobs it should pick up.',
      needsYou: false,
    };
  }
  if (input.problems.length > 0) {
    const n = input.problems.length;
    return {
      headline: `${n} ${n === 1 ? 'thing needs' : 'things need'} you.`,
      accent: jobs(input.running),
      // Counts and no more: what each one is, and what to do about it, is the
      // drawer behind the Review button. The page keeps to a sentence and a way
      // in, and never quotes a problem.
      lede: `${counts(input.problems)} ${n === 1 ? 'needs' : 'need'} your attention.`,
      needsYou: true,
    };
  }
  return {
    headline: 'Everything is running.',
    accent: jobs(input.running),
    lede: `${input.slotsUsed} of ${input.slots} host slots are in use and nothing needs your attention.`,
    needsYou: false,
  };
}

/**
 * The one place the browser knows how long a password has to be.
 *
 * It is `auth.MinPasswordLength` in Go and `minLength: 12` in
 * api/openapi.yaml, and it was a literal in two Svelte components that had no
 * way of noticing when it changed. Length rather than a zoo of character
 * classes is the deliberate choice -- see internal/auth/auth.go, which explains
 * why.
 */
export const MIN_PASSWORD_LENGTH = 12;

/**
 * A hint that helps rather than scolds. It counts up to the minimum and then
 * says what actually makes a password stronger, which is more of it.
 */
export function passwordStrength(password: string): string {
  if (password.length === 0) {
    return `At least ${MIN_PASSWORD_LENGTH} characters. A phrase works well.`;
  }
  if (password.length < MIN_PASSWORD_LENGTH) {
    return `${password.length} of ${MIN_PASSWORD_LENGTH} characters.`;
  }
  // Length is the thing worth asking for, and the one thing it cannot promise
  // is variety: twenty of the same character is twenty characters long, and
  // calling that "Strong." on the account that owns the whole fleet is the one
  // claim this hint is not entitled to make.
  if (new Set(password).size < 6) {
    return 'Long, but it repeats. A few unrelated words beat one character held down.';
  }
  if (password.length < 20) return 'Good. Longer is stronger than more punctuation.';
  return 'Long enough. Store it somewhere you will still have it next month.';
}

/**
 * Automatic pools, in the words the pages use for them.
 *
 * A pool the controller keeps is the one kind of pool an operator cannot fully
 * edit, so where a page shows or offers something on a pool it asks here first.
 * The sentences that explain a decision come from the controller; what is here
 * is the vocabulary around them, kept in one place so the Pools page, a pool's
 * own page and the hosts that count towards it never name the same thing three
 * ways.
 */
import type { AutoPoolPending, AutoPools, Pool, SizeClassLimits } from '../api/types';
import { memoryLabel } from './sizing';

export type SwitchMode = AutoPools['auto_pools'];

/** True for a pool the controller keeps. */
export function isAutomatic(pool: Pick<Pool, 'auto'> | null | undefined): boolean {
  return pool?.auto !== undefined && pool.auto !== null;
}

/**
 * An architecture as the controller's own sentences say it, which is the word
 * GitHub's runner label uses: amd64 is "x64" there, and a panel that called it
 * one thing beside a sentence that called it another would read as two kinds.
 */
export function archWords(arch: string): string {
  return arch === 'amd64' ? 'x64' : arch;
}

/** The switch's own spelling, for a badge. */
export function modeWords(mode: SwitchMode | undefined): string {
  if (mode === 'on') return 'On';
  if (mode === 'shadow') return 'Report only';
  return 'Off';
}

/** What a switch does at each setting, for the sentence beside it. */
export function modeHint(setting: 'auto_pools' | 'size_routing', mode: SwitchMode): string {
  if (setting === 'auto_pools') {
    if (mode === 'on') return 'The controller makes and keeps these pools.';
    if (mode === 'shadow') {
      return 'The controller says what it would do below and changes nothing. Hosts are still given a class.';
    }
    return 'The controller keeps no pool. Pools you made are unaffected either way.';
  }
  if (mode === 'on') return 'Each job is sent to the pool of its class.';
  if (mode === 'shadow') {
    return 'Each job is given a class and where it ran is recorded. Nothing is sent anywhere.';
  }
  return 'No job is given a class.';
}

const PENDING: Record<AutoPoolPending['kind'], string> = {
  create: 'Would make',
  resize: 'Would resize',
  enable: 'Would put back in use',
  disable: 'Would put out of use',
  reshape: 'Would bring back in line',
};

/** The verb for a change the controller has worked out and is not allowed to make yet. */
export function pendingWords(kind: AutoPoolPending['kind']): string {
  return PENDING[kind] ?? 'Would change';
}

/** "up to 4 CPUs and 16 GB", or "anything larger" for the class with no limit above it. */
export function limitWords(limits: SizeClassLimits): string {
  const cpus = limits.host_max_cpus ?? 0;
  const memory = limits.host_max_memory_mb ?? 0;
  if (cpus <= 0 && memory <= 0) return 'anything larger';
  const parts: string[] = [];
  if (cpus > 0) parts.push(`${Math.round(cpus * 10) / 10} CPUs`);
  if (memory > 0) parts.push(memoryLabel(memory));
  return `up to ${parts.join(' and ')}`;
}

/** What one runner of the class is, where a host's own profile names no size. */
export function runnerWords(limits: SizeClassLimits): string {
  return `${Math.round(limits.runner_cpus * 10) / 10} CPU${limits.runner_cpus === 1 ? '' : 's'} and ${memoryLabel(limits.runner_memory_mb)}`;
}

/**
 * A pool's own figures as a line for the cap and the warm count: zero means
 * "none" for a warm count and "no cap" for a cap, and neither reads as a number.
 */
export function warmWords(warm: number): string {
  return warm > 0 ? `${warm} kept ready` : 'none kept ready';
}

export function capWords(cap: number): string {
  return cap > 0 ? `capped at ${cap}` : 'no cap';
}

/**
 * What it takes to move a pool to another backend in one request.
 *
 * Moving to the process backend is more than naming it. A process has no Docker
 * daemon to give a job, and no container whose limits can be measured or moved,
 * so a pool that has Docker for jobs, elastic CPU or the memory valve on loses
 * each in the same change -- and the API refuses a pool that keeps them, with an
 * error on a field the one-click remedy never showed. Working the change out in
 * one place says what is switched off both in the request and in the sentence
 * that asks for confirmation, so the two cannot disagree.
 */
import type { BackendKind, Body, Pool } from '$lib/api/types';

export interface BackendSwitch {
  /** The request body: the new backend, and whatever has to go with it. */
  body: Body<'updatePool'>;
  /** What the change switches off, as a sentence each, for the confirmation. */
  switchedOff: string[];
}

const on = (mode: string | undefined): boolean =>
  mode !== undefined && mode !== '' && mode !== 'off';

export function backendSwitch(pool: Pool, backend: BackendKind): BackendSwitch {
  const body: Body<'updatePool'> = { backend };
  const switchedOff: string[] = [];
  if (backend !== 'process') return { body, switchedOff };

  body.docker_mode = 'none';
  if (pool.docker_mode !== undefined && pool.docker_mode !== 'none') {
    switchedOff.push(
      'Docker for jobs is switched off, because the process backend cannot provide it.',
    );
  }

  const cpu = on(pool.cpu_burst?.mode);
  const memory = on(pool.memory_burst?.mode);
  if (cpu) {
    body.cpu_burst = {
      mode: 'off',
      max_cpus: 0,
      size_for_ceiling: pool.cpu_burst?.size_for_ceiling ?? true,
    };
  }
  if (memory) body.memory_burst = { mode: 'off' };
  const because = 'because a process has no container limits to measure or move.';
  if (cpu && memory)
    switchedOff.push(`Elastic CPU and the memory valve are switched off, ${because}`);
  else if (cpu) switchedOff.push(`Elastic CPU is switched off, ${because}`);
  else if (memory) switchedOff.push(`The memory valve is switched off, ${because}`);
  return { body, switchedOff };
}

/**
 * What deleting a pool will actually do, in the order an operator cares about.
 *
 * Both places that offer the deletion -- the list and the pool's own page --
 * showed this, in two copies that had to be kept in step by hand. The wording
 * is deliberate: it names what happens to *running work* rather than to rows,
 * because the difference between "drained, then removed" and "destroyed
 * immediately" is somebody's build.
 */
import { pluralise } from '$lib/format';

export interface PoolCounts {
  live?: number;
  busy?: number;
  /** Jobs still queued and matched to this pool -- not yet on a runner. */
  queued?: number;
}

export function deletionConsequences(counts: PoolCounts, force: boolean): string[] {
  const live = counts.live ?? 0;
  const busy = counts.busy ?? 0;
  const queued = counts.queued ?? 0;
  const lines = [
    live === 0
      ? 'It has no runners right now, so nothing is interrupted.'
      : force
        ? `${pluralise(live, 'runner')} will be destroyed immediately.`
        : `${pluralise(live, 'runner')} will be drained, then removed.`,
  ];
  if (busy > 0) {
    lines.push(
      force
        ? `${pluralise(busy, 'job')} running right now will be interrupted.`
        : `${pluralise(busy, 'job')} running right now will be allowed to finish first.`,
    );
  }
  if (queued > 0) {
    lines.push(
      `${pluralise(queued, 'queued job')} asking for this pool will be removed from the queue too, ` +
        'the same as deleting it from the Queue page. You can restore it from the Removed view.',
    );
  }
  lines.push('The runners are deregistered from GitHub either way.');
  return lines;
}

/**
 * The pool editor's draft: what is being edited, how it becomes a request body,
 * and the rules that can be checked without asking the server.
 *
 * Pure, and in a `.ts` rather than in the form's `<script module>`, so that the
 * unit tests -- which run under Node with no Svelte compiler -- can import it.
 * A rule that lives inside a component is a rule nothing can test without a
 * browser, and these are the rules an operator meets first.
 */
import type {
  BackendKind,
  DockerMode,
  Platform,
  Pool,
  PoolCreate,
  Resources,
} from '$lib/api/types';
import { brandedName } from '$lib/brand';
import { parseGoDuration } from '$lib/format';
import { MIN_TMPFS_MB, memoryLabel } from './sizing';
import { backendUnavailable } from './vocabulary';
import type { BackendOffer } from './vocabulary';

/**
 * What the editor is editing.
 *
 * Numbers are held as strings because that is what a text input gives back,
 * and because "" and "0" are different answers -- one is "not filled in yet",
 * the other is a deliberate zero. They become numbers exactly once, in
 * `toPoolBody`.
 */
export interface PoolDraft {
  name: string;
  installation_id: string;
  runner_group: string;
  labels: string[];
  backend: BackendKind;
  /**
   * The machine these runners need. Empty means the pool promises nothing,
   * which is what a pool created before platforms existed looks like.
   */
  platform_os: string;
  platform_os_version: string;
  platform_arch: string;
  image: string;
  runner_version: string;
  dind_image: string;
  min_runners: string;
  max_runners: string;
  priority: string;
  idle_timeout: string;
  ephemeral: boolean;
  no_default_labels: boolean;
  docker_mode: DockerMode;
  run_as_root: boolean;
  enabled: boolean;
  /**
   * How this pool decides what one runner gets.
   *
   * `automatic` sets no CPU and no memory on the pool at all: the scheduler
   * charges each runner one slot's share of the host it lands on and gives
   * it exactly that share as a real cgroup limit, so a fleet of unequal
   * machines is sized correctly on every one of them without anybody typing
   * a number. `profile` is the same absence with one more answer given: each
   * runner is the standard size of the host's own runner profile, and the
   * pool carries `size_from_profile` to say so. `fixed` is the two figures
   * below, the same on every host.
   *
   * It is editor state rather than a pool field because `automatic` and
   * `fixed` are told apart by emptiness, and holding the choice separately is
   * what keeps the sliders' last position while an operator looks at the
   * other answers and changes their mind back.
   */
  sizing: 'automatic' | 'fixed' | 'profile';
  cpu_burst_mode: 'off' | 'observe' | 'automatic';
  cpu_burst_max: string;
  cpu_burst_size_builds: boolean;
  /**
   * The memory valve: `off`, `observe` (decide what it would lend and record it,
   * changing nothing) or `automatic` (raise a live runner's limit out of memory
   * its host has not promised to anyone). A new pool starts on observe, for the
   * reason elastic CPU does: the honest first step is to watch.
   */
  memory_burst_mode: 'off' | 'observe' | 'automatic';
  /** The most one runner may hold, its own share and what it is lent together, in MB; empty is half as much again as it starts with. */
  memory_burst_max: string;
  /** The swap each container may use past its limit as the last resort, in MB; empty is none. */
  memory_burst_spill: string;
  cpus: string;
  memory_mb: string;
  /** The least a runner may be given where no host has room for the size above; empty is none. */
  min_cpus: string;
  min_memory_mb: string;
  /**
   * The sidecar's share of a slot's CPU and of its memory, in percent, as typed;
   * empty is the even split. Two figures because a build is CPU in the sidecar
   * while the runner holds the memory.
   */
  daemon_cpu_share: string;
  daemon_memory_share: string;
  /** Whether the division has been chosen, so a recommended one is only ever the start. */
  split_chosen: boolean;
  disk_gb: string;
  /**
   * The fleet timings this pool overrides. Empty is "follow the fleet",
   * which is what every pool does until somebody says otherwise -- and an
   * operator who clears one of these inputs is saying it again.
   */
  provision_timeout: string;
  drain_timeout: string;
  max_runner_lifetime: string;
  scale_up_delay: string;
  docker_wait: string;
  cache_enabled: boolean;
  cache_tools: boolean;
  cache_scope: 'pool' | 'repository';
  cache_size_limit: string;
  cache_source: string;
  cache_repository: string;
  /**
   * Folders kept in memory instead of on the host's disk. Off for every pool
   * until somebody chooses otherwise, because a tmpfs is charged to the
   * runner's memory limit: the size here is room taken out of it. A size left
   * empty is fitted to the limit by the controller.
   */
  /**
   * Whether each in-memory folder is placed per runner (in memory where it has
   * room to be useful, on disk where it has not) rather than always in memory.
   * It is the recommended answer, so it is what a pool starts with; a pool saved
   * with a folder that was always in memory keeps that.
   */
  tmpfs_auto: boolean;
  tmpfs_work: boolean;
  tmpfs_work_size: string;
  tmpfs_tmp: boolean;
  tmpfs_tmp_size: string;
  /** The Docker-in-Docker sidecar's image store; only a dind pool has one. */
  tmpfs_daemon: boolean;
  tmpfs_daemon_size: string;
  /** Carried through untouched: the editor does not edit it, and must not lose it. */
  pids_limit: string;
  host_selector: Record<string, string>;
  /** Which providers may rent machines for this pool; empty means any provider. */
  provider_selector: Record<string, string>;
  /**
   * The editor's own state, not the pool's: whether the operator chose to
   * keep this pool to some hosts. The selector cannot answer it, because
   * "only hosts that match" with no rule typed yet is an empty map exactly
   * like "any host" -- and reading the choice back off the selector is how
   * a half-made rule reset itself when the section was shut and opened again.
   */
  restrict_hosts: boolean;
  env: Record<string, string>;
}

export function emptyDraft(): PoolDraft {
  return {
    name: '',
    installation_id: '',
    runner_group: '',
    labels: [],
    backend: 'docker',
    platform_os: '',
    platform_os_version: '',
    platform_arch: '',
    image: '',
    runner_version: '',
    dind_image: '',
    min_runners: '0',
    max_runners: '4',
    priority: '0',
    idle_timeout: '5m',
    ephemeral: true,
    no_default_labels: false,
    docker_mode: 'none',
    run_as_root: false,
    enabled: true,
    // A new pool leaves its size to its hosts, which is what the server
    // does with a pool that names none. The sliders below are filled from
    // the fleet's suggestion as soon as it is known -- see the effect that
    // fetches it -- so that an operator who switches to a fixed size opens
    // on the fleet's own answer rather than on an empty box.
    sizing: 'automatic',
    cpu_burst_mode: 'observe',
    cpu_burst_max: '',
    cpu_burst_size_builds: true,
    memory_burst_mode: 'observe',
    memory_burst_max: '',
    memory_burst_spill: '',
    cpus: '',
    memory_mb: '',
    min_cpus: '',
    min_memory_mb: '',
    daemon_cpu_share: '',
    daemon_memory_share: '',
    split_chosen: false,
    disk_gb: '',
    provision_timeout: '',
    drain_timeout: '',
    max_runner_lifetime: '',
    scale_up_delay: '',
    docker_wait: '',
    cache_enabled: false,
    cache_tools: false,
    cache_scope: 'pool',
    cache_size_limit: '',
    cache_source: '',
    cache_repository: '',
    tmpfs_auto: true,
    tmpfs_work: false,
    tmpfs_work_size: '',
    tmpfs_tmp: false,
    tmpfs_tmp_size: '',
    tmpfs_daemon: false,
    tmpfs_daemon_size: '',
    pids_limit: '',
    host_selector: {},
    provider_selector: {},
    restrict_hosts: false,
    env: {},
  };
}

function fromNumber(value: number | undefined): string {
  return value === undefined || value === null ? '' : String(value);
}

export function draftFromPool(pool: Pool): PoolDraft {
  const base = emptyDraft();
  const resources = pool.resources ?? {};
  return {
    ...base,
    name: pool.name ?? '',
    installation_id: pool.installation_id ?? '',
    runner_group: pool.runner_group ?? '',
    labels: [...(pool.labels ?? [])],
    backend: pool.backend ?? 'docker',
    platform_os: pool.platform?.os ?? '',
    platform_os_version: pool.platform?.os_version ?? '',
    platform_arch: pool.platform?.arch ?? '',
    image: pool.image ?? '',
    runner_version: pool.runner_version ?? '',
    dind_image: pool.dind_image ?? '',
    min_runners: fromNumber(pool.min_runners),
    max_runners: fromNumber(pool.max_runners),
    priority: fromNumber(pool.priority),
    idle_timeout: pool.idle_timeout ?? base.idle_timeout,
    ephemeral: pool.ephemeral !== false,
    no_default_labels: pool.no_default_labels === true,
    docker_mode: pool.docker_mode ?? 'none',
    run_as_root: pool.run_as_root === true,
    enabled: pool.enabled !== false,
    // The server says which of the two this pool is doing rather than the
    // browser inferring it from two absent numbers, because "no CPU limit"
    // alone cannot tell "the host decides" from "nobody set one".
    sizing: pool.sizing === 'fixed' ? 'fixed' : pool.sizing === 'profile' ? 'profile' : 'automatic',
    cpu_burst_mode: pool.cpu_burst?.mode ?? 'off',
    cpu_burst_max: fromNumber(pool.cpu_burst?.max_cpus),
    cpu_burst_size_builds: pool.cpu_burst?.size_for_ceiling ?? true,
    memory_burst_mode: pool.memory_burst?.mode ?? 'off',
    memory_burst_max: fromNumber(pool.memory_burst?.max_memory_mb || undefined),
    memory_burst_spill: fromNumber(pool.memory_burst?.spill_mb || undefined),
    cpus: fromNumber(resources.cpus),
    memory_mb: fromNumber(resources.memory_mb),
    min_cpus: fromNumber(resources.min_cpus),
    min_memory_mb: fromNumber(resources.min_memory_mb),
    // A pool that said one figure said it for both; a specific one wins. A pool
    // being edited has its division already, so it is never preselected over.
    daemon_cpu_share: fromNumber(
      resources.daemon_cpu_share_percent ?? resources.daemon_share_percent,
    ),
    daemon_memory_share: fromNumber(
      resources.daemon_memory_share_percent ?? resources.daemon_share_percent,
    ),
    split_chosen: true,
    disk_gb: fromNumber(resources.disk_gb),
    provision_timeout: pool.runner_settings?.provision_timeout ?? '',
    drain_timeout: pool.runner_settings?.drain_timeout ?? '',
    max_runner_lifetime: pool.runner_settings?.max_runner_lifetime ?? '',
    scale_up_delay: pool.runner_settings?.scale_up_delay ?? '',
    docker_wait: pool.runner_settings?.docker_wait ?? '',
    cache_enabled: pool.cache?.enabled === true,
    cache_tools: pool.cache?.tools === true,
    cache_scope: pool.cache?.scope ?? 'pool',
    cache_size_limit: fromNumber(pool.cache?.size_limit),
    cache_source: pool.cache?.source ?? '',
    cache_repository: pool.cache?.repository ?? '',
    tmpfs_auto: (['work', 'tmp', 'daemon'] as const).every((k) => {
      const m = pool.tmpfs?.[k];
      return !m?.enabled || m.auto === true;
    }),
    tmpfs_work: pool.tmpfs?.work?.enabled === true,
    tmpfs_work_size: fromNumber(pool.tmpfs?.work?.size_mb),
    tmpfs_tmp: pool.tmpfs?.tmp?.enabled === true,
    tmpfs_tmp_size: fromNumber(pool.tmpfs?.tmp?.size_mb),
    tmpfs_daemon: pool.tmpfs?.daemon?.enabled === true,
    tmpfs_daemon_size: fromNumber(pool.tmpfs?.daemon?.size_mb),
    pids_limit: fromNumber(resources.pids_limit),
    host_selector: { ...(pool.host_selector ?? {}) },
    provider_selector: { ...(pool.provider_selector ?? {}) },
    restrict_hosts: Object.keys(pool.host_selector ?? {}).length > 0,
    env: { ...(pool.env ?? {}) },
  };
}

/**
 * Whether this draft holds anything the simple path cannot show.
 *
 * It decides which path an edit opens on, and it is deliberately generous:
 * the cost of opening the advanced path on a plain pool is one extra click,
 * and the cost of opening the simple path on a tuned one is an operator
 * saving away a host selector or a provision timeout they never saw.
 */
export function poolIsTuned(draft: PoolDraft): boolean {
  return (
    draft.sizing !== 'automatic' ||
    draft.cpu_burst_mode === 'automatic' ||
    draft.memory_burst_mode === 'automatic' ||
    draft.restrict_hosts ||
    Object.keys(draft.host_selector).length > 0 ||
    Object.keys(draft.provider_selector).length > 0 ||
    draft.backend !== 'docker' ||
    draft.docker_mode === 'host-socket' ||
    draft.run_as_root ||
    draft.cache_enabled ||
    draft.tmpfs_work ||
    draft.tmpfs_tmp ||
    draft.tmpfs_daemon ||
    draft.image.trim() !== '' ||
    draft.runner_version.trim() !== '' ||
    draft.dind_image.trim() !== '' ||
    draft.platform_os.trim() !== '' ||
    draft.platform_arch.trim() !== '' ||
    draft.disk_gb.trim() !== '' ||
    draft.pids_limit.trim() !== '' ||
    draft.provision_timeout.trim() !== '' ||
    draft.drain_timeout.trim() !== '' ||
    draft.max_runner_lifetime.trim() !== '' ||
    draft.scale_up_delay.trim() !== '' ||
    draft.docker_wait.trim() !== ''
  );
}

/** A duration input as the API takes it: the text, or null for "follow the fleet". */
function nullableDuration(value: string): string | null {
  const trimmed = value.trim();
  return trimmed === '' ? null : trimmed;
}

export function toNumber(value: string): number | undefined {
  const trimmed = value.trim();
  if (trimmed === '') return undefined;
  const parsed = Number(trimmed);
  return Number.isFinite(parsed) ? parsed : undefined;
}

export function toInteger(value: string): number | undefined {
  const parsed = toNumber(value);
  return parsed !== undefined && Number.isInteger(parsed) ? parsed : undefined;
}

/**
 * The request body this draft produces.
 *
 * On create, empty optional fields are left out and the server fills in its
 * defaults. On edit they are sent as empty: a PATCH treats an absent key as
 * "leave it as it is", so leaving them out would make clearing the image, a
 * resource limit or the last host-selector entry a change the server never
 * hears about -- while the toast says it was saved.
 */
export function toPoolBody(draft: PoolDraft, options: { complete?: boolean } = {}): PoolCreate {
  const resources: Resources = {};
  const fixed = draft.sizing === 'fixed';
  const elasticBackend = draft.backend === 'docker' || draft.backend === 'podman';
  const hasSidecar = draft.backend === 'docker' && draft.docker_mode === 'dind';
  const cpus = toNumber(draft.cpus);
  const memory = toInteger(draft.memory_mb);
  const disk = toInteger(draft.disk_gb);
  const pids = toInteger(draft.pids_limit);
  // Only a fixed pool sends a size. An automatic one sends neither figure,
  // whatever the sliders happen to be holding, because absence is how the
  // API is told to leave the size to the host -- and the sliders keep their
  // position so that switching back does not lose what was chosen.
  if (fixed && cpus !== undefined) resources.cpus = cpus;
  if (fixed && memory !== undefined) resources.memory_mb = memory;
  // A minimum is a floor under either kind of size: the figures of a fixed
  // pool, or the host's share for an automatic one, where it is what lets a
  // runner start on a host with a free slot but less than a share left. An
  // empty field sends nothing, which the fleet reads as "follow
  // runners.minimum_*" -- live, so a later change to that setting moves
  // this pool too.
  const minCpus = toNumber(draft.min_cpus);
  const minMemory = toInteger(draft.min_memory_mb);
  if (minCpus !== undefined && minCpus > 0) resources.min_cpus = minCpus;
  if (minMemory !== undefined && minMemory > 0) resources.min_memory_mb = minMemory;
  // How a host-sized slot is divided between the runner and its Docker
  // sidecar. It means nothing for a fixed size (both containers get the whole
  // figure), so it is not sent there, and empty is the even split.
  if (draft.backend === 'docker' && draft.docker_mode === 'dind' && !fixed) {
    // Each share is sent on its own, and an even one is left out: absent is the
    // even split, so the stored pool stays as small as what was said.
    const cpuShare = toInteger(draft.daemon_cpu_share);
    const memoryShare = toInteger(draft.daemon_memory_share);
    if (cpuShare !== undefined && cpuShare > 0 && cpuShare !== 50)
      resources.daemon_cpu_share_percent = cpuShare;
    if (memoryShare !== undefined && memoryShare > 0 && memoryShare !== 50)
      resources.daemon_memory_share_percent = memoryShare;
  }
  // Disk and the pids limit are independent of the choice: neither has a
  // share to be given, so a pool may cap its cache's disk and still leave
  // its size to the host.
  if (disk !== undefined) resources.disk_gb = disk;
  if (pids !== undefined) resources.pids_limit = pids;

  const body: PoolCreate = {
    // Always sent, true or false, because a PATCH reads an absent key as
    // "leave it alone": a pool moved back from the host's profile to a share
    // or a stated size would otherwise keep taking its size from the host
    // while the toast says it was saved.
    size_from_profile: draft.sizing === 'profile',
    name: brandedName(draft.name),
    installation_id: draft.installation_id,
    labels: draft.labels.map((label) => label.trim()).filter(Boolean),
    backend: draft.backend,
    min_runners: toInteger(draft.min_runners) ?? 0,
    max_runners: toInteger(draft.max_runners) ?? 1,
    priority: toInteger(draft.priority) ?? 0,
    idle_timeout: draft.idle_timeout.trim() || '5m',
    ephemeral: draft.ephemeral,
    // GitHub adds the default labels to every ephemeral runner itself, so
    // the setting only survives on a pool that reuses its runners.
    no_default_labels: !draft.ephemeral && draft.no_default_labels,
    docker_mode: draft.docker_mode,
    cpu_burst: {
      mode: fixed || !elasticBackend ? 'off' : draft.cpu_burst_mode,
      max_cpus: fixed || !elasticBackend ? 0 : (toNumber(draft.cpu_burst_max) ?? 0),
      size_for_ceiling: draft.cpu_burst_size_builds,
    },
    // The valve is a container runtime's feature, and its figures mean something
    // only while it is on: the server refuses swap on a valve that is off, so an
    // off valve sends none, whatever the fields still hold.
    memory_burst: {
      mode: elasticBackend ? draft.memory_burst_mode : 'off',
      max_memory_mb:
        elasticBackend && draft.memory_burst_mode !== 'off'
          ? (toInteger(draft.memory_burst_max) ?? 0)
          : 0,
      spill_mb:
        elasticBackend && draft.memory_burst_mode !== 'off'
          ? (toInteger(draft.memory_burst_spill) ?? 0)
          : 0,
    },
    run_as_root: draft.run_as_root,
    enabled: draft.enabled,
    cache: {
      enabled: draft.cache_enabled,
      // Only a container runner has a tool cache to keep, and only with the
      // cache on; anything else would be refused by the server.
      tools:
        draft.cache_enabled &&
        draft.cache_tools &&
        (draft.backend === 'docker' || draft.backend === 'podman'),
      scope: draft.cache_scope,
      size_limit: toInteger(draft.cache_size_limit) ?? 0,
      source: draft.cache_source.trim(),
      repository: draft.cache_scope === 'repository' ? draft.cache_repository.trim() : '',
    },
    // Only a container runner has a folder to mount over; a process runner
    // would be refused, so its draft sends both off whatever the toggles say.
    // A size is sent only for a folder that is on, and an empty one means "fit
    // it to the memory limit", which is how the API reads a zero.
    tmpfs: {
      work: {
        enabled: elasticBackend && draft.tmpfs_work,
        auto: elasticBackend && draft.tmpfs_work && draft.tmpfs_auto,
        size_mb: elasticBackend && draft.tmpfs_work ? (toInteger(draft.tmpfs_work_size) ?? 0) : 0,
      },
      tmp: {
        enabled: elasticBackend && draft.tmpfs_tmp,
        auto: elasticBackend && draft.tmpfs_tmp && draft.tmpfs_auto,
        size_mb: elasticBackend && draft.tmpfs_tmp ? (toInteger(draft.tmpfs_tmp_size) ?? 0) : 0,
      },
      // The image store is the sidecar's, so only a Docker-in-Docker pool on the
      // Docker backend has one; anything else would be refused by the server.
      daemon: {
        enabled: hasSidecar && draft.tmpfs_daemon,
        auto: hasSidecar && draft.tmpfs_daemon && draft.tmpfs_auto,
        size_mb: hasSidecar && draft.tmpfs_daemon ? (toInteger(draft.tmpfs_daemon_size) ?? 0) : 0,
      },
    },
  };
  // The draft holds plain strings because that is what a <select> gives
  // back; the API's enums are narrower, and the server is the one that
  // rejects a value outside them.
  const platform: Platform = {};
  if (draft.platform_os) platform.os = draft.platform_os as Platform['os'];
  if (draft.platform_os_version) platform.os_version = draft.platform_os_version;
  if (draft.platform_arch) platform.arch = draft.platform_arch as Platform['arch'];
  // Always sent, so that clearing a platform on an edit actually clears it
  // rather than being read as "leave it alone".
  body.platform = platform;

  const complete = options.complete === true;
  if (complete || draft.runner_group.trim()) body.runner_group = draft.runner_group.trim();
  if (complete || draft.image.trim()) body.image = draft.image.trim();
  if (complete || draft.runner_version.trim()) body.runner_version = draft.runner_version.trim();
  // Only a pool that gives its jobs a Docker daemon of its own has a sidecar,
  // and the server refuses an image on any other, so a pool switched away
  // from it sends the field empty rather than carrying a forgotten value.
  const dindImage = draft.docker_mode === 'dind' ? draft.dind_image.trim() : '';
  if (complete || dindImage) body.dind_image = dindImage;
  // Always sent, like the platform and for the same reason: a pool moved
  // from a fixed size to automatic clears its figures, and an absent key
  // would be read as "leave them alone".
  body.resources = resources;
  // Every override is sent on every save, as a duration or as null. Null is
  // how the API is told to hand a setting back to the fleet, and a form that
  // left a cleared input out would make "stop overriding this" unsayable.
  body.runner_settings = {
    provision_timeout: nullableDuration(draft.provision_timeout),
    drain_timeout: nullableDuration(draft.drain_timeout),
    max_runner_lifetime: nullableDuration(draft.max_runner_lifetime),
    scale_up_delay: nullableDuration(draft.scale_up_delay),
    docker_wait: nullableDuration(draft.docker_wait),
  };
  if (complete || Object.keys(draft.host_selector).length > 0) {
    body.host_selector = draft.host_selector;
  }
  if (complete || Object.keys(draft.provider_selector).length > 0) {
    body.provider_selector = draft.provider_selector;
  }
  if (complete || Object.keys(draft.env).length > 0) body.env = draft.env;
  return body;
}

const NAME_SHAPE = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;

/** The part of a draft the memory valve's rules are about. */
export type MemoryBurstFields = Pick<
  PoolDraft,
  | 'backend'
  | 'sizing'
  | 'memory_mb'
  | 'docker_mode'
  | 'memory_burst_mode'
  | 'memory_burst_max'
  | 'memory_burst_spill'
>;

/**
 * The memory valve's figures, held to the server's own rules and said beside the
 * control. Separate from the rest of a draft's errors because a pool the
 * controller keeps edits only this, in a dialog with no draft behind it.
 */
export function memoryBurstErrors(draft: MemoryBurstFields): Record<string, string> {
  const errors: Record<string, string> = {};
  if (
    (draft.backend === 'docker' || draft.backend === 'podman') &&
    draft.memory_burst_mode !== 'off'
  ) {
    if (draft.memory_burst_max.trim() !== '') {
      const ceiling = toInteger(draft.memory_burst_max);
      // A docker-in-docker pair is two containers, each given the typed limit.
      const started =
        draft.sizing === 'fixed'
          ? (toInteger(draft.memory_mb) ?? 0) * (draft.docker_mode === 'dind' ? 2 : 1)
          : 0;
      if (ceiling === undefined || ceiling < 512)
        errors['memory_burst.max_memory_mb'] =
          'Use at least 512 MB, or leave it empty for half as much again as a runner starts with.';
      else if (started > 0 && ceiling <= started)
        errors['memory_burst.max_memory_mb'] =
          `A ceiling at or below what a runner starts with (${memoryLabel(started)}) leaves nothing to lend. Raise it, or leave it empty for half as much again.`;
    }
    if (draft.memory_burst_spill.trim() !== '') {
      const spill = toInteger(draft.memory_burst_spill);
      if (spill === undefined || spill < 0)
        errors['memory_burst.spill_mb'] =
          'Use a whole number of megabytes, or leave it empty to allow no swap.';
      else if (spill > 1048576)
        errors['memory_burst.spill_mb'] = 'That is more than a terabyte of swap, which is a typo.';
    }
  }
  return errors;
}

/**
 * The rules the editor can check without asking the server. The server checks
 * the same things and more; these exist so the operator finds out while they
 * are still typing rather than at the end.
 */
export function draftErrors(
  draft: PoolDraft,
  socketConfirmed: boolean,
  offers: readonly BackendOffer[] = [],
  hostsKnown = false,
): Record<string, string> {
  const errors: Record<string, string> = {};
  const name = draft.name.trim();
  if (name === '') errors['name'] = 'Give the pool a name so it can be told apart in the fleet.';
  else if (name.length > 64) errors['name'] = 'Keep the name to 64 characters or fewer.';
  else if (!NAME_SHAPE.test(name))
    errors['name'] =
      'Use letters, digits, dots, dashes and underscores, starting with a letter or digit.';

  if (draft.installation_id === '')
    errors['installation_id'] = 'Choose the GitHub installation these runners register with.';

  if (draft.labels.length === 0)
    errors['labels'] = 'Add at least one label, or no workflow can ask for this pool.';

  const min = toInteger(draft.min_runners);
  const max = toInteger(draft.max_runners);
  const priority = toInteger(draft.priority);
  if (min === undefined || min < 0) errors['min_runners'] = 'Use a whole number, zero or more.';
  if (max === undefined || max < 1) errors['max_runners'] = 'Use a whole number, one or more.';
  else if (min !== undefined && max < min)
    errors['max_runners'] = `The maximum must be at least the minimum, which is ${min}.`;
  if (priority === undefined) errors['priority'] = 'Use a whole number.';

  if (parseGoDuration(draft.idle_timeout) === null)
    errors['idle_timeout'] = 'Use a Go duration such as 5m, 90s or 1h30m.';

  // Only a pool that has chosen a fixed size has a figure to be wrong about.
  // The floors are the server's own: below them the runner binary cannot
  // keep up with its own job, or is killed before it takes one.
  // An automatic pool sends neither, and the floors below are the server's
  // rules for a number somebody typed -- applying them to a slider nothing
  // is going to read would refuse a pool the server would happily create.
  if (draft.sizing === 'fixed') {
    const cpus = toNumber(draft.cpus);
    if (cpus === undefined || cpus <= 0)
      errors['resources.cpus'] = 'A fixed size needs a CPU limit. Move the slider to choose one.';
    else if (cpus < 0.25) errors['resources.cpus'] = 'A runner needs at least a quarter of a core.';
    const memory = toInteger(draft.memory_mb);
    if (memory === undefined || memory <= 0)
      errors['resources.memory_mb'] =
        'A fixed size needs a memory limit. Move the slider to choose one.';
    else if (memory < 512) errors['resources.memory_mb'] = 'A runner needs at least 512 MB.';
    // The same rule the server keeps, said where the sliders are rather
    // than at the foot of the page: a minimum sits under a stated standard.
    const minCpus = toNumber(draft.min_cpus);
    if (minCpus !== undefined && cpus !== undefined && minCpus > cpus)
      errors['resources.min_cpus'] = 'The minimum has to be at or below the standard CPU.';
    const minMemory = toInteger(draft.min_memory_mb);
    if (minMemory !== undefined && memory !== undefined && minMemory > memory)
      errors['resources.min_memory_mb'] = 'The minimum has to be at or below the standard memory.';
  }
  for (const [value, field, what] of [
    [draft.daemon_cpu_share, 'resources.daemon_cpu_share_percent', 'CPU'],
    [draft.daemon_memory_share, 'resources.daemon_memory_share_percent', 'memory'],
  ] as const) {
    const pct = toInteger(value);
    if (pct !== undefined && (pct < 10 || pct > 90))
      errors[field] =
        `Give the sidecar between 10 and 90 percent of the ${what}, or leave it empty for an even split.`;
  }
  // Under either kind of size a minimum is held to what any runner needs:
  // it is sent for an automatic pool too, so the floor applies there.
  const minCpusFloor = toNumber(draft.min_cpus);
  if (
    !errors['resources.min_cpus'] &&
    minCpusFloor !== undefined &&
    minCpusFloor > 0 &&
    minCpusFloor < 0.25
  )
    errors['resources.min_cpus'] = 'A runner needs at least a quarter of a core.';
  const minMemoryFloor = toInteger(draft.min_memory_mb);
  if (
    !errors['resources.min_memory_mb'] &&
    minMemoryFloor !== undefined &&
    minMemoryFloor > 0 &&
    minMemoryFloor < 512
  )
    errors['resources.min_memory_mb'] = 'A runner needs at least 512 MB.';
  if (
    draft.sizing !== 'fixed' &&
    (draft.backend === 'docker' || draft.backend === 'podman') &&
    draft.cpu_burst_max.trim() !== ''
  ) {
    const ceiling = toNumber(draft.cpu_burst_max);
    if (ceiling === undefined || ceiling < 0.25)
      errors['cpu_burst.max_cpus'] =
        'Use at least a quarter of a core, or leave it empty to use the host ceiling.';
  }
  Object.assign(errors, memoryBurstErrors(draft));
  if (draft.disk_gb.trim() !== '') {
    const disk = toInteger(draft.disk_gb);
    if (disk === undefined || disk <= 0)
      errors['resources.disk_gb'] =
        'Use a whole number of gigabytes, or leave it empty for no limit.';
  }

  if (
    draft.cache_enabled &&
    (toInteger(draft.cache_size_limit) ?? 0) > 0 &&
    !draft.cache_source.trim().startsWith('/')
  )
    errors['cache.size_limit'] =
      'A size limit is kept by evicting from a directory on the host, so the cache source has to be an absolute host path. There is nothing to measure inside a named volume.';

  // The server's own rules for the folders, said beside the control. A tmpfs
  // is charged to the runner's memory limit, so typed sizes that take the
  // whole of a typed limit leave a job nothing to run in.
  // The runner's folders add up against the runner's limit; the image store is
  // charged to the daemon's container and is held to its own.
  let typedTmpfs = 0;
  let typedDaemon = 0;
  for (const [on, raw, key] of [
    [draft.tmpfs_work, draft.tmpfs_work_size, 'tmpfs.work.size_mb'],
    [draft.tmpfs_tmp, draft.tmpfs_tmp_size, 'tmpfs.tmp.size_mb'],
    [draft.tmpfs_daemon, draft.tmpfs_daemon_size, 'tmpfs.daemon.size_mb'],
  ] as const) {
    if (!on || raw.trim() === '') continue;
    const mb = toInteger(raw);
    if (mb === undefined || mb < MIN_TMPFS_MB)
      errors[key] =
        `Use a whole number of megabytes, at least ${MIN_TMPFS_MB}, or leave it empty to size it from the memory limit.`;
    else if (key === 'tmpfs.daemon.size_mb') typedDaemon += mb;
    else typedTmpfs += mb;
  }
  if (draft.sizing === 'fixed') {
    const memory = toInteger(draft.memory_mb);
    if (memory !== undefined && memory > 0 && typedTmpfs >= memory && typedTmpfs > 0)
      errors['tmpfs.work.size_mb'] ||=
        `These folders may take ${typedTmpfs} MB and the memory limit is ${memory} MB. They are charged to that limit, so raise it to at least ${memory + typedTmpfs} MB or shrink them.`;
    if (memory !== undefined && memory > 0 && typedDaemon >= memory && typedDaemon > 0)
      errors['tmpfs.daemon.size_mb'] ||=
        `The image store may take ${typedDaemon} MB and the memory limit is ${memory} MB. The daemon's tmpfs is charged to that limit, so raise it to at least ${memory + typedDaemon} MB or shrink the store.`;
  }

  if (draft.docker_mode === 'host-socket' && !socketConfirmed)
    errors['docker_mode'] =
      'Confirm that you understand what mounting the host socket gives every job on this pool.';

  const unrunnable = backendUnavailable(
    draft.backend,
    offers,
    hostsKnown,
    Object.keys(draft.host_selector).length > 0,
  );
  if (unrunnable) errors['backend'] = unrunnable;

  return errors;
}

import type { Host } from '$lib/api/types';

/** The selector keys a host answers for from its agent's report, not a label. */
export const REPORTED_KEYS = ['os', 'arch'] as const;

/** Mirrors Host.SelectorValue in the Go store. */
export function hostSelectorValue(host: Host, key: string): string {
  const labels = host.labels ?? {};
  if (key in labels) return labels[key] ?? '';
  if (key === 'os') return host.os ?? '';
  if (key === 'arch') return host.arch ?? '';
  return '';
}

/** Whether a host satisfies every entry of a selector. Empty means any host. */
export function hostMatchesSelector(host: Host, selector: Record<string, string>): boolean {
  return Object.entries(selector).every(([key, value]) => hostSelectorValue(host, key) === value);
}

/** Values currently reported for a selector key, including a disconnected saved value. */
export function reportedValues(
  hosts: readonly Host[],
  key: string,
  extra: string,
): { value: string; hosts: number }[] {
  const counts: Record<string, number> = {};
  for (const host of hosts) {
    const value = hostSelectorValue(host, key);
    if (value) counts[value] = (counts[value] ?? 0) + 1;
  }
  if (extra && counts[extra] === undefined) counts[extra] = 0;
  return Object.entries(counts)
    .map(([value, count]) => ({ value, hosts: count }))
    .sort((a, b) => b.hosts - a.hosts || a.value.localeCompare(b.value));
}

/**
 * How one pool is sized on one host, in the words a row says it in.
 *
 * Pure, and imported by a unit test. A runner's size is decided from three
 * places -- the pool, the host's runner profile and the fleet's runners.*
 * settings -- and an operator reading a number needs to know which of them it
 * came from before they know where to change it. The controller says which, in
 * `PoolHostSizing`; this only puts it into a sentence, so that every page that
 * shows a size says the same thing about it.
 */
import type { PoolHostSizing } from '../api/types';
import { cpuLabel, memoryLabel } from './sizing';

/** The tiers a figure can belong to, which decides what "the fleet's" means for it. */
export type Tier = 'standard' | 'floor' | 'ceiling';

/**
 * Whose a figure is. The fleet's setting is a different one for each tier --
 * `runners.default_*` stands in for a standard and `runners.minimum_*` for a
 * floor -- and an operator told "from the fleet" has to be told which.
 */
export function sourceWords(source: string | undefined, tier: Tier): string {
  switch (source) {
    case 'pool':
      return 'the pool';
    case 'host':
      return 'the host';
    case 'global':
      return tier === 'floor' ? "the fleet's minimum" : "the fleet's default";
    default:
      return '';
  }
}

/** One tier as "3 cores and 8 GB, from the host", or with a clause each where the two have different owners. */
export function tierWords(
  cpus: number | undefined,
  cpusSource: string | undefined,
  memoryMb: number | undefined,
  memorySource: string | undefined,
  tier: Tier,
): string {
  const hasCpus = (cpus ?? 0) > 0;
  const hasMemory = (memoryMb ?? 0) > 0;
  if (!hasCpus && !hasMemory) return '';
  if (hasCpus && hasMemory && cpusSource !== memorySource) {
    return `${cpuLabel(cpus ?? 0)} from ${sourceWords(cpusSource, tier)} and ${memoryLabel(memoryMb ?? 0)} from ${sourceWords(memorySource, tier)}`;
  }
  const figures = [hasCpus ? cpuLabel(cpus ?? 0) : '', hasMemory ? memoryLabel(memoryMb ?? 0) : '']
    .filter(Boolean)
    .join(' and ');
  const owner = sourceWords(hasCpus ? cpusSource : memorySource, tier);
  return owner === '' ? figures : `${figures}, from ${owner}`;
}

export interface HostSizingWords {
  /** What one runner is given on the host. */
  standard: string;
  /** The least it is given, where anybody has set one. */
  floor: string;
  /** The most CPU it may use, its own share and any lent to it together, where the pool lends CPU. */
  ceiling: string;
}

export function hostSizingWords(sizing: PoolHostSizing | undefined): HostSizingWords {
  return {
    standard: tierWords(
      sizing?.standard?.cpus,
      sizing?.standard_cpus_source,
      sizing?.standard?.memory_mb,
      sizing?.standard_memory_mb_source,
      'standard',
    ),
    floor: tierWords(
      sizing?.floor?.cpus,
      sizing?.floor_cpus_source,
      sizing?.floor?.memory_mb,
      sizing?.floor_memory_mb_source,
      'floor',
    ),
    ceiling:
      (sizing?.ceiling_cpus ?? 0) > 0
        ? tierWords(sizing?.ceiling_cpus, sizing?.ceiling_source, undefined, undefined, 'ceiling')
        : '',
  };
}

/**
 * Whether the host's own settings are doing anything to this pool's runners
 * there, which is the only time a row owes an operator the explanation. A host
 * that gives one slot's share and holds no floor of its own is the case every
 * fleet was before profiles, and says nothing more than it ever did.
 */
export function hostIsInvolved(sizing: PoolHostSizing | undefined, fromProfile: boolean): boolean {
  if (!sizing) return false;
  if (fromProfile) return true;
  return (
    sizing.floor_cpus_source === 'host' ||
    sizing.floor_memory_mb_source === 'host' ||
    sizing.ceiling_source === 'host'
  );
}

/**
 * The name a new pool arrives with, and the dice that roll another one.
 *
 * A blank name field is the first thing an operator meets in the pool editor, and
 * the name they invent to get past it -- "test", "pool1" -- is then in every
 * runner name, every audit line and every `runs-on` for the life of the fleet.
 * Renaming a pool later does not un-write the workflows that already point at
 * it. So the editor fills one in instead.
 *
 * The name it fills in is the pool's shape -- `zoomies-4vcpu-ubuntu-2404`, the
 * grammar in docs/naming.md -- because that is what a workflow author reading a
 * `runs-on` needs to know before they send a job to it, and because it is the
 * same name `zoomies init` suggests for a machine of that size. The editor used
 * to lead with a kennel word instead, which left an operator who met both with
 * two conventions for one thing.
 *
 * The spaniel is still here, and still earns its place: it is what tells two
 * pools of the same shape apart, and what names a pool created before anything
 * about it is known. The brand prefix is not optional either -- it is what marks
 * a runner in the GitHub UI as ours rather than GitHub's.
 */

import type { BackendKind, Host } from '$lib/api/types';
import { RUNNER_NAME_PREFIX, sanitizeLabel } from '$lib/brand';

/**
 * Cocker spaniels, as cocker spaniels are actually named.
 *
 * The mark is a cocker spaniel doing zoomies, so the fleet is a kennel. Every
 * word here is one segment of lowercase letters -- no spaces, nothing to
 * sanitise away -- and short enough that the infrastructure half of the name
 * survives the length budget below.
 */
export const KENNEL: readonly string[] = [
  'banjo',
  'biscuit',
  'boogie',
  'bramble',
  'bubbles',
  'cocoa',
  'crumpet',
  'custard',
  'digby',
  'disco',
  'flapjack',
  'gizmo',
  'hazel',
  'jellybean',
  'jitterbug',
  'maple',
  'marmalade',
  'muffin',
  'noodle',
  'pancake',
  'pepper',
  'pickles',
  'popcorn',
  'rascal',
  'rocket',
  'rusty',
  'scampi',
  'toffee',
  'truffle',
  'waffles',
  'wiggles',
  'ziggy',
];

/**
 * How long a generated name may be.
 *
 * `sanitizeLabel` truncates at 40 characters, so a longer name would produce a
 * label that is a chopped-off version of it -- two strings an operator has to
 * hold in their head at once, for no gain.
 */
const MAX_NAME = 40;

/** The value every entry agrees on, or "" when they do not all agree. */
function agreed(values: readonly (string | undefined)[]): string {
  let found = '';
  for (const value of values) {
    const clean = sanitizeLabel(value ?? '');
    if (clean === '') continue;
    if (found === '') found = clean;
    else if (found !== clean) return '';
  }
  return found;
}

function offersBackend(host: Host, backend: BackendKind): boolean {
  const info = (host.backend_info ?? []).find((entry) => entry.kind === backend);
  return info?.available === true || (host.backends ?? []).includes(backend);
}

/**
 * The size every pool in this fleet gets unless it says otherwise.
 *
 * It is passed in rather than assumed because it is a fleet setting, and
 * because of what the name does with it: a figure every pool shares says
 * nothing about any of them. See `shape`.
 */
export interface FleetSize {
  cpus?: number;
  memory_mb?: number;
}

/**
 * The parts of a draft a name is made of.
 *
 * Structural rather than the editor's own PoolDraft, so this module owes the
 * editor nothing: a draft satisfies it by having the fields, and the naming
 * rules can be read without opening a component.
 */
export interface NameShape {
  backend: BackendKind;
  /**
   * How the pool decides its runners' size. A pool that leaves it to the host
   * -- by a share of the machine, or by the standard size the host's own
   * profile names -- has no size to be named for: its runners are 3.8 cores
   * here and 7.6 on the next machine to join, so `4vcpu` in the name would be a
   * promise it stopped keeping the day the fleet grew.
   */
  sizing: 'automatic' | 'fixed' | 'profile';
  cpus: string;
  memory_mb: string;
  platform_os: string;
  platform_os_version: string;
  platform_arch: string;
}

/**
 * A version with its dots taken out: 24.04 becomes 2404, 12 stays 12.
 *
 * The same rule as naming.CompactVersion in Go, because the name a pool is
 * suggested here has to be the name `zoomies init` would suggest for the same
 * machine -- an operator who meets both should meet one convention.
 */
function compactVersion(v: string): string {
  return v
    .trim()
    .split(/[._]/)
    .slice(0, 2)
    .map((part) => part.replace(/\D/g, ''))
    .join('');
}

/**
 * What a pool of this draft is made of, most significant part first.
 *
 * This is the shape half of the grammar in docs/naming.md: how much machine,
 * running what. The draft's own fields win, and where it has not said, the
 * connected hosts answer -- but only when every host that could run this pool
 * agrees, because a name that picked one of two answers is a name that lies
 * about half the fleet.
 *
 * Architecture follows the same rule the rest of the grammar does: amd64 is the
 * overwhelming default and saying it on every pool stops the word carrying
 * information, so only the others are spelled out.
 */
export function shape(
  draft: NameShape,
  hosts: readonly Host[],
  fleetDefault?: FleetSize | null,
): string[] {
  const parts: string[] = [];

  // Size is stated when the pool has one of its own and it is not what every
  // pool here gets. Naming it unconditionally would put the same two words on
  // every pool in the fleet -- which is the argument that keeps amd64 out of
  // these names, applied to the figure it applies to twice as hard. A pool
  // that asks for more than the fleet's usual is exactly the pool a workflow
  // author is choosing, and it says so.
  //
  // A pool that leaves the size to its host says nothing at all: the figure
  // the sliders happen to be holding is not this pool's, and a name built from
  // it would advertise a size the pool does not have on any machine.
  if (draft.sizing === 'fixed') {
    const cpus = Math.ceil(Number(draft.cpus));
    if (Number.isFinite(cpus) && cpus > 0 && cpus !== defaultCPUs(fleetDefault)) {
      parts.push(`${cpus}vcpu`);
    }
    const gb = Math.floor(Number(draft.memory_mb) / 1024);
    if (Number.isFinite(gb) && gb > 0 && gb !== defaultGB(fleetDefault)) parts.push(`${gb}gb`);
  }

  const offering = hosts.filter((host) => offersBackend(host, draft.backend));
  const from = offering.length > 0 ? offering : hosts;

  const os = sanitizeLabel(draft.platform_os) || agreed(from.map((host) => host.platform?.os));
  if (os !== '') {
    parts.push(os);
    const version =
      compactVersion(draft.platform_os_version) ||
      compactVersion(unanimous(from.map((host) => host.platform?.os_version)));
    if (version !== '') parts.push(version);
  }

  const arch =
    sanitizeLabel(draft.platform_arch) || agreed(from.map((host) => host.platform?.arch));
  if (arch !== '' && arch !== 'amd64') parts.push(arch);

  return parts;
}

/**
 * The fleet's default in the units a name is written in: whole cores rounded
 * the way a pool's own figure is, and whole gigabytes. A fleet that has not
 * said, or a call that did not pass it, has no default to compare against and
 * every figure is worth stating.
 */
function defaultCPUs(fleetDefault?: FleetSize | null): number {
  const cpus = fleetDefault?.cpus;
  return cpus !== undefined && cpus > 0 ? Math.ceil(cpus) : -1;
}

function defaultGB(fleetDefault?: FleetSize | null): number {
  const mb = fleetDefault?.memory_mb;
  return mb !== undefined && mb > 0 ? Math.floor(mb / 1024) : -1;
}

/** The raw value every entry agrees on, before sanitising, or "". */
function unanimous(values: readonly (string | undefined)[]): string {
  let found = '';
  for (const value of values) {
    const clean = (value ?? '').trim();
    if (clean === '') continue;
    if (found === '') found = clean;
    else if (found !== clean) return '';
  }
  return found;
}

/**
 * The name for a pool of this draft, and the kennel word it falls back on.
 *
 * A pool is named for its shape, which is the same name `zoomies init` prints
 * for a machine of that size and platform -- so the editor and the installer
 * stop offering an operator two conventions for the same thing.
 *
 * The kennel word earns its place where the shape cannot carry the name on its
 * own. A pool created before anything about it is known has no shape to be
 * named for, and two pools of the same shape are two pools GitHub needs two
 * names for; in both cases a spaniel tells them apart, which
 * `zoomies-4vcpu-ubuntu-2404-2` never would.
 *
 * Over budget, the least significant parts go first -- architecture, then the
 * release, then the operating system -- because the size is what an operator is
 * choosing between and the word is what they recognise the pool by.
 */
export function poolName(
  word: string,
  draft: NameShape,
  hosts: readonly Host[],
  taken: readonly string[] = [],
  fleetDefault?: FleetSize | null,
): string {
  const parts = named(draft, hosts, fleetDefault);
  const spelled = new Set(taken.map((name) => sanitizeLabel(name)));
  const bare = fit(parts);
  if (parts.length > 0 && !spelled.has(sanitizeLabel(bare))) return bare;
  return nicknamedPoolName(word, draft, hosts, fleetDefault);
}

/**
 * The same name with a spaniel in it whether it needs one or not.
 *
 * This is what the dice ask for. A pool whose shape is already unique is
 * offered a name without a word, so a button that only sometimes changed
 * anything would read as broken -- and an operator who wants a handle for a
 * pool is entitled to one without having to invent it themselves.
 */
export function nicknamedPoolName(
  word: string,
  draft: NameShape,
  hosts: readonly Host[],
  fleetDefault?: FleetSize | null,
): string {
  return fit(named(draft, hosts, fleetDefault), sanitizeLabel(word) || 'pool');
}

/**
 * The shape, plus the marker a process-backend pool carries.
 *
 * That backend is a different thing to ask for at the same shape -- its jobs get
 * the host itself rather than a container -- and a workflow author choosing
 * between two pools needs the name to say which. `zoomies init` marks it the
 * same way.
 */
function named(
  draft: NameShape,
  hosts: readonly Host[],
  fleetDefault?: FleetSize | null,
): string[] {
  const parts = shape(draft, hosts, fleetDefault);
  if (draft.backend === 'process') parts.push('host');
  return parts;
}

/**
 * These parts as a branded name, dropping the least significant until it fits.
 *
 * `keep` is never dropped: when it is there at all it is the only thing telling
 * this pool from one of the same shape, so a budget that spent it would produce
 * the name it was added to avoid.
 */
function fit(parts: readonly string[], keep = ''): string {
  const kept = [...parts];
  const tail = keep === '' ? '' : `-${keep}`;
  while (kept.length > 0) {
    const candidate = RUNNER_NAME_PREFIX + kept.join('-') + tail;
    if (candidate.length <= MAX_NAME) return candidate;
    kept.pop();
  }
  return (RUNNER_NAME_PREFIX + keep).slice(0, MAX_NAME).replace(/-+$/, '');
}

/**
 * A word from the kennel, never the one already on screen.
 *
 * Rolling the dice and getting the same name back reads as a broken button,
 * so the previous word is taken out of the hat rather than left to chance.
 */
export function spinWord(previous?: string): string {
  const choices = KENNEL.filter((word) => word !== previous);
  const pool = choices.length > 0 ? choices : KENNEL;
  return pool[Math.floor(Math.random() * pool.length)] ?? 'biscuit';
}

/**
 * The notches a runner's size moves between, and the words for them.
 *
 * Pure, and imported by a unit test. The sliders exist because the three
 * figures they carry -- how much of a machine one runner gets, and how much
 * disk its cache may keep -- are the settings an operator is least equipped to
 * type into an empty box: a number field accepts 3000 MB as readily as 4096,
 * and neither the field nor the pool says which of them the hosts can actually
 * back. A notch is a value somebody has a reason to choose.
 *
 * The arithmetic that says how many runners a fleet has room for is the
 * controller's, not this file's: what a runner is charged is not always what
 * the pool says -- a docker-in-docker slot is charged for its sidecar too --
 * and a browser that worked it out again would disagree with where the fleet
 * actually places runners. This file's counting is only what a slider needs
 * before the server's answer lands.
 */

/**
 * The CPU notches: shares of a core below one, then whole cores, then the
 * steps a build machine is actually bought in. A quarter core is the floor the
 * API enforces -- below it the runner binary cannot keep up with its own job.
 */
export const CPU_NOTCHES: readonly number[] = [
  0.25, 0.5, 1, 1.5, 2, 3, 4, 6, 8, 12, 16, 24, 32, 48, 64,
];

/** The memory notches, in megabytes. 512 MB is the API's floor. */
export const MEMORY_NOTCHES: readonly number[] = [
  512, 1024, 2048, 3072, 4096, 6144, 8192, 12288, 16384, 24576, 32768, 49152, 65536, 98304, 131072,
];

/**
 * The swap notches, in megabytes, with zero for none. Swap is the memory valve's
 * last resort: it turns a kill into a slowdown, and some operators would rather
 * have the kill, so none is the answer a pool gives until somebody asks.
 */
export const SWAP_NOTCHES: readonly number[] = [0, 512, 1024, 2048, 4096, 8192, 16384];

/**
 * The disk notches, in gigabytes, with zero for "no limit".
 *
 * Disk is the one runner limit that is genuinely optional: it is advisory on
 * every backend, and what stops a host filling up is its own disk reserve
 * rather than a figure on a pool. A pool that asks for it is charged it, which
 * is why it belongs on the same panel as the other two.
 */
export const DISK_NOTCHES: readonly number[] = [
  0, 10, 20, 40, 60, 80, 120, 160, 240, 320, 480, 640,
];

/**
 * The cache notches, in gigabytes, with zero for "no limit". The limit is kept
 * by evicting whole entries between one runner and the next, so it is a
 * high-water mark on a host's disk rather than an allocation.
 */
export const CACHE_NOTCHES: readonly number[] = [
  0, 1, 2, 5, 10, 20, 30, 50, 75, 100, 150, 200, 300, 500,
];

const BYTES_PER_GB = 1024 * 1024 * 1024;

/** Bytes as the API carries a cache limit, from the gigabytes a slider moves in. */
export function cacheBytes(gb: number): number {
  return Math.round(gb * BYTES_PER_GB);
}

/**
 * The gigabytes a stored cache limit comes to. It is not snapped to a notch:
 * a limit typed as 7 GB is 7 GB, and the slider takes it in as a notch of its
 * own the way it takes any other figure set off the notches.
 */
export function cacheGb(bytes: number | undefined): number {
  if (!bytes || bytes <= 0) return 0;
  return Math.round((bytes / BYTES_PER_GB) * 100) / 100;
}

/** The notch nearest a value, so a figure typed elsewhere lands on the slider. */
export function nearest(notches: readonly number[], value: number): number {
  let best = notches[0] ?? 0;
  for (const n of notches) {
    if (Math.abs(n - value) < Math.abs(best - value)) best = n;
  }
  return best;
}

/**
 * A notch list that includes a value the notches do not have.
 *
 * A pool created through the API, or before these sliders existed, can hold
 * 3000 MB; snapping it to 3072 the moment its page opens would change a pool
 * an operator came to read. The value joins the list instead, and the slider
 * moves off it onto the notches.
 */
export function withValue(notches: readonly number[], value: number): number[] {
  if (!Number.isFinite(value) || value <= 0 || notches.includes(value)) return [...notches];
  return [...notches, value].sort((a, b) => a - b);
}

/** "2 cores", "half a core", "1 core". */
export function cpuLabel(cpus: number): string {
  if (cpus === 0.5) return 'half a core';
  if (cpus === 0.25) return 'a quarter core';
  if (cpus === 1) return '1 core';
  return `${trimNumber(cpus)} cores`;
}

/** "4 GB", "512 MB". */
export function memoryLabel(mb: number): string {
  if (mb <= 0) return 'none';
  if (mb < 1024) return `${mb} MB`;
  return `${trimNumber(mb / 1024)} GB`;
}

/** "no limit" is a real answer for disk and for the cache, and reads as one. */
export function gbLabel(gb: number): string {
  return gb <= 0 ? 'no limit' : `${trimNumber(gb)} GB`;
}

function trimNumber(value: number): string {
  return value.toLocaleString(undefined, { maximumFractionDigits: 1 });
}

/** One runner's size as a phrase: "2 cores and 4 GB". */
export function sizeLabel(cpus: number, memoryMb: number): string {
  return `${cpuLabel(cpus)} and ${memoryLabel(memoryMb)}`;
}

/**
 * What a runner of this pool is charged, which is twice the size it was given
 * where the pool gives its jobs a daemon of their own: the build runs in that
 * daemon, so it is given the same limits and the machine carries the pair.
 *
 * It is asked only about a size somebody typed. A pool sized by its host puts
 * the runner and the daemon in one slot between them, so it is charged one --
 * a slot is one runner, whatever the runner brought with it.
 *
 * It is the figure the fleet's room is counted from, and the one an operator
 * reading "2 cores" against a ten-core host cannot otherwise arrive at.
 */
export function chargedSize(
  cpus: number,
  memoryMb: number,
  dockerMode: string | undefined,
): { cpus: number; memoryMb: number; pair: boolean } {
  const pair = dockerMode === 'dind';
  const factor = pair ? 2 : 1;
  return { cpus: cpus * factor, memoryMb: memoryMb * factor, pair };
}

/**
 * How many runners of a size a machine has room for, on an empty host.
 *
 * This is the browser's copy of the controller's arithmetic, and it is used
 * for one thing: the sentence under a slider while the server's own answer is
 * still in flight. Where the two disagree the server wins, because it knows
 * what the fleet is actually charged.
 */
export function roomOn(
  machine: { cpus: number; memoryMb: number },
  charge: { cpus: number; memoryMb: number },
): number {
  let room = Infinity;
  if (machine.cpus > 0 && charge.cpus > 0)
    room = Math.min(room, Math.floor(machine.cpus / charge.cpus));
  if (machine.memoryMb > 0 && charge.memoryMb > 0)
    room = Math.min(room, Math.floor(machine.memoryMb / charge.memoryMb));
  return Number.isFinite(room) ? Math.max(0, room) : 0;
}

/**
 * What ran out on a host, as the clause that follows what the machine is.
 *
 * The distinction it carries is the one an operator acts on: a host held to
 * fewer runners than its machine could take is an operator's own ceiling and
 * is working as asked, while one whose machine runs out first is a host that
 * will refuse creates for slots every page counts as free.
 */
export function limitPhrase(limitedBy: string | undefined): string {
  switch (limitedBy) {
    case 'cpu':
      return 'its cores run out first';
    case 'memory':
      return 'its memory runs out first';
    case 'disk':
      return 'its disk runs out first';
    case 'slots':
      return 'held there by its slot count';
    case 'profile':
      return 'its runner profile keeps this pool off it';
    default:
      return '';
  }
}

/**
 * The folders a pool may keep in memory, and what they cost.
 *
 * A tmpfs is charged to the runner's own memory limit, so what a folder may
 * fill comes out of the limit the pool was sized with for the job rather than
 * being added to it. These mirror the controller's arithmetic
 * (store.TmpfsConfig) so the editor can propose the limit that leaves the job
 * the room it has now, before the server's answer lands; the server's own
 * warning, pool.tmpfs_memory_tight, is the authority and says the same number.
 */
export const MIN_TMPFS_MB = 64;
/** What a folder with no size of its own is given on a runner with room. */
export const DEFAULT_TMPFS_WORK_MB = 4096;
export const DEFAULT_TMPFS_TMP_MB = 1024;
/** The Docker-in-Docker sidecar's image store: larger, because a pull that does not fit fails the job. */
export const DEFAULT_TMPFS_DAEMON_MB = 8192;

export interface TmpfsFolder {
  enabled: boolean;
  /** The typed size in MB; undefined or zero lets the memory limit pick it. */
  sizeMb: number | undefined;
}

/**
 * The memory the enabled folders may take: what was typed, or the default for
 * one left to size itself. This is what a limit sized for the job alone should
 * be raised by.
 */
export function tmpfsReserveMb(work: TmpfsFolder, tmp: TmpfsFolder): number {
  const one = (f: TmpfsFolder, fallback: number) =>
    !f.enabled ? 0 : f.sizeMb && f.sizeMb > 0 ? f.sizeMb : fallback;
  return one(work, DEFAULT_TMPFS_WORK_MB) + one(tmp, DEFAULT_TMPFS_TMP_MB);
}

/** What the sidecar's image store may take: what was typed, or the default. */
export function daemonReserveMb(daemon: TmpfsFolder): number {
  return !daemon.enabled
    ? 0
    : daemon.sizeMb && daemon.sizeMb > 0
      ? daemon.sizeMb
      : DEFAULT_TMPFS_DAEMON_MB;
}

/**
 * The limit that leaves the job the room the current one gives it, with the
 * folders on top. Zero when there is nothing to propose: no limit to raise
 * (the host's share is sized from the machine), or nothing in memory.
 *
 * A typed limit is given to the runner and to the daemon alike, and each is
 * charged for its own folders, so the limit covers whichever needs more. Adding
 * the two would pay for room neither container uses.
 */
export function recommendedMemoryMb(
  limitMb: number,
  work: TmpfsFolder,
  tmp: TmpfsFolder,
  daemon: TmpfsFolder = { enabled: false, sizeMb: undefined },
): number {
  const reserve = Math.max(tmpfsReserveMb(work, tmp), daemonReserveMb(daemon));
  // At least twice what the folders may take, as well as the limit plus them:
  // folders are fitted into half a limit, so a proposal that left them more than
  // half would still be tight when it was taken. On a limit smaller than the
  // folders the sum alone falls short of that.
  return limitMb > 0 && reserve > 0 ? Math.max(limitMb + reserve, 2 * reserve) : 0;
}

/**
 * Whether the folders take enough of the limit to be worth a word: more than
 * half of it, the line the controller's pool.tmpfs_memory_tight draws too.
 *
 * Without it the proposal would follow the limit upward -- accept 12 GB and the
 * folders are proposed on top of that -- when what an operator needs is one
 * answer, and silence once the job has its room. Folders left to size
 * themselves are fitted into half the limit, so at the line they are not a
 * problem; past it they are either shrunk or, if typed, a job that fills them
 * is killed for want of memory.
 */
export function tmpfsIsTight(limitMb: number, reserveMb: number): boolean {
  return limitMb > 0 && reserveMb * 2 > limitMb;
}

/**
 * The ways of dividing a host-sized slot between a runner and its Docker sidecar
 * that the pool editor offers, as the sidecar's share of CPU and of memory. They
 * mirror the controller's priced presets (`room.split_plan`), which carry the same
 * ids and figures; the words are here because they are guidance, not data.
 */
export interface SplitPreset {
  id: 'even' | 'build' | 'runner';
  label: string;
  /** The sidecar's share of a slot's CPU, in percent. */
  cpu: number;
  /** The sidecar's share of a slot's memory, in percent. */
  memory: number;
  description: string;
}

export const SPLIT_PRESETS: readonly SplitPreset[] = [
  {
    id: 'even',
    label: 'Even',
    cpu: 50,
    memory: 50,
    description:
      'Half of the CPU and half of the memory to each. The right start when you do not yet know where the work is.',
  },
  {
    id: 'build',
    label: 'Image builds in the sidecar',
    cpu: 70,
    memory: 50,
    description:
      'The sidecar gets 70% of the CPU and the memory stays even. For jobs that build images or run containers: the CPU is spent in the sidecar while the runner waits.',
  },
  {
    id: 'runner',
    label: 'Work in the runner',
    cpu: 35,
    memory: 35,
    description:
      'The runner gets 65% of both. For jobs that compile, test or install in the runner with a Docker step at the end, and for an in-memory work folder, which is charged to the runner.',
  },
];

/**
 * Which preset a pair of typed shares is, or `custom`. An empty share is the even
 * split, which is how the API reads zero; anything out of step with every preset is
 * the person's own.
 */
export function splitPreset(cpu: string, memory: string): SplitPreset['id'] | 'custom' {
  const read = (s: string): number | null => {
    const t = s.trim();
    if (t === '') return 50;
    const n = Number(t);
    return Number.isInteger(n) ? n : null;
  };
  const c = read(cpu);
  const m = read(memory);
  if (c === null || m === null) return 'custom';
  return SPLIT_PRESETS.find((p) => p.cpu === c && p.memory === m)?.id ?? 'custom';
}

import type { Problem, Settings } from '$lib/api/types';
import { parseGoDuration } from '$lib/format';

const remedies: Record<string, { key: string; value: unknown }> = {
  'scheduler.default_runner_limits_off': { key: 'scheduler.default_runner_limits', value: true },
  'scheduler.host_throttling_off': { key: 'scheduler.host_throttling', value: true },
  'agent.bootstrap_cpu_grace_short': { key: 'agent.bootstrap_cpu_grace', value: '2m' },
  'runners.docker_wait_short': { key: 'runners.docker_wait', value: '3m' },
  'scheduler.provision_timeout_short': { key: 'scheduler.provision_timeout', value: '20m' },
};
export function isStartupFinding(problem: Problem): boolean {
  return !!remedies[problem.code ?? ''];
}

/** Only fix current findings. Never write through an environment pin or clear a pending restart. */
export function startupFix(settings: Settings, problems: readonly Problem[]) {
  const changes: Record<string, unknown> = {};
  const blocked: string[] = [];
  const pending: string[] = [];
  for (const problem of problems) {
    const remedy = remedies[problem.code ?? ''];
    if (!remedy) continue;
    const row = settings.settings?.find((s) => s.key === remedy.key);
    if (
      !row?.editable ||
      row.source === 'environment' ||
      settings.pinned_by_environment?.includes(remedy.key)
    ) {
      blocked.push(remedy.key);
    } else if (row.pending) {
      pending.push(remedy.key);
    } else {
      changes[remedy.key] = remedy.value;
      if (remedy.key === 'scheduler.provision_timeout') {
        const wait = settings.settings?.find((s) => s.key === 'runners.docker_wait')?.value;
        const milliseconds = typeof wait === 'string' ? (parseGoDuration(wait) ?? 0) : 0;
        // Leave five minutes beyond creation and Docker readiness, including a
        // deliberately long wait. parseGoDuration returns milliseconds.
        changes[remedy.key] = `${Math.max(20, Math.ceil(milliseconds / 60000) + 15)}m`;
      }
    }
  }
  return { changes, blocked, pending };
}

/**
 * What each section of the pool editor answers, in a line.
 *
 * Every section is a row that says its current answer without being opened, so
 * the whole pool can be read down the page: "One share of each host · elastic
 * CPU observing" tells an operator more than a closed row labelled "Size", and
 * it is the reason a first-time reader can see that every default has already
 * been chosen for them. The line is derived from the draft rather than stored,
 * so it cannot disagree with the controls under it.
 *
 * Pure, so the unit tests can hold the wording: this is the sentence an operator
 * reads instead of the form, and a figure that drifted from the control would
 * be believed.
 */
import type { Platform } from '$lib/api/types';
import { shortGoDuration } from '$lib/format';
import type { PoolDraft } from './draft';
import type { SectionId } from './sections';
import { cpuLabel, memoryLabel } from './sizing';
import { backendLabel, platformLabel } from './vocabulary';

export interface SummaryContext {
  /** The GitHub organisation or repository the chosen installation covers. */
  installation: string;
  /** How many hosts the fleet has, or null until it has been asked. */
  hostsTotal: number | null;
  /** How many of them this pool's host selector reaches, or null until known. */
  hostsMatching: number | null;
  /** How many providers are configured, or null until they have been asked. */
  providersTotal: number | null;
  /** How many of them this pool's provider selector allows, or null until known. */
  providersMatching: number | null;
}

const NONE: SummaryContext = {
  installation: '',
  hostsTotal: null,
  hostsMatching: null,
  providersTotal: null,
  providersMatching: null,
};

function count(value: string): number {
  const n = Number(value.trim());
  return Number.isFinite(n) ? n : 0;
}

function join(parts: readonly (string | false | undefined)[]): string {
  return parts
    .filter((part): part is string => typeof part === 'string' && part !== '')
    .join(' · ');
}

function basics(draft: PoolDraft, ctx: SummaryContext): string {
  const labels = draft.labels.map((label) => label.trim()).filter(Boolean);
  return join([
    labels.length > 0 ? `runs-on ${labels.join(', ')}` : 'no labels yet',
    ctx.installation || 'no GitHub connection chosen',
    draft.docker_mode === 'dind' && 'Docker for jobs',
    draft.docker_mode === 'host-socket' && 'the host’s Docker socket',
  ]);
}

function hosts(draft: PoolDraft, ctx: SummaryContext): string {
  const rules = Object.entries(draft.host_selector);
  if (!draft.restrict_hosts && rules.length === 0) {
    return ctx.hostsTotal === null || ctx.hostsTotal === 0
      ? 'Any host that can run it'
      : `Any host that can run it · ${ctx.hostsTotal} connected`;
  }
  if (rules.length === 0) return 'Only some hosts · no rule chosen yet';
  const shown = rules.map(([key, value]) => `${key}=${value}`).join(', ');
  return join([
    `Only hosts where ${shown}`,
    ctx.hostsMatching !== null && `${ctx.hostsMatching} match`,
  ]);
}

function providers(draft: PoolDraft, ctx: SummaryContext): string {
  const rules = Object.entries(draft.provider_selector);
  if (rules.length === 0) {
    return ctx.providersTotal === null || ctx.providersTotal === 0
      ? 'Any provider that can build a machine for it'
      : `Any provider that can build a machine for it · ${ctx.providersTotal} configured`;
  }
  const shown = rules.map(([key, value]) => (value === '' ? key : `${key}=${value}`)).join(', ');
  return join([
    `Only providers where ${shown}`,
    ctx.providersMatching !== null && `${ctx.providersMatching} match`,
  ]);
}

function runner(draft: PoolDraft): string {
  // The draft holds plain strings because that is what a <select> gives back;
  // the API's enums are narrower, and the server is what rejects a value
  // outside them.
  const platform: Platform = {};
  if (draft.platform_os) platform.os = draft.platform_os as Platform['os'];
  if (draft.platform_os_version) platform.os_version = draft.platform_os_version;
  if (draft.platform_arch) platform.arch = draft.platform_arch as Platform['arch'];
  return join([
    backendLabel(draft.backend),
    draft.backend === 'process' ? false : platformLabel(platform) || 'default image',
    draft.image.trim() !== '' && 'your own image',
    draft.runner_version.trim() !== '' && `runner ${draft.runner_version.trim()}`,
    draft.docker_mode === 'dind' && draft.dind_image.trim() !== '' && 'your own Docker sidecar',
    draft.run_as_root && 'runs as root',
  ]);
}

function size(draft: PoolDraft): string {
  const containers = draft.backend === 'docker' || draft.backend === 'podman';
  const base =
    draft.sizing === 'fixed'
      ? `${cpuLabel(count(draft.cpus))} and ${memoryLabel(count(draft.memory_mb))} on every host`
      : draft.sizing === 'profile'
        ? 'The size each host sets'
        : 'One share of each host';
  const floor = [
    count(draft.min_cpus) > 0 ? cpuLabel(count(draft.min_cpus)) : '',
    count(draft.min_memory_mb) > 0 ? memoryLabel(count(draft.min_memory_mb)) : '',
  ].filter(Boolean);
  return join([
    base,
    floor.length > 0 && `never below ${floor.join(' and ')}`,
    containers && elastic(draft),
  ]);
}

/**
 * What the pool may borrow, in one phrase. CPU needs a size left to the host,
 * because the host's share is its guaranteed base; memory needs only a limit to
 * watch, so a pool with a fixed size still says it. Two valves on the same
 * footing are one phrase rather than two.
 */
function elastic(draft: PoolDraft): string {
  const cpu = draft.sizing === 'fixed' ? 'off' : draft.cpu_burst_mode;
  const memory = draft.memory_burst_mode;
  if (cpu === 'observe' && memory === 'observe') return 'elastic CPU and memory observing';
  return join([
    cpu !== 'off' && `elastic CPU ${cpu === 'automatic' ? 'boosting' : 'observing'}`,
    memory !== 'off' && `elastic memory ${memory === 'automatic' ? 'lending' : 'observing'}`,
  ]);
}

function timings(draft: PoolDraft): number {
  return [
    draft.provision_timeout,
    draft.drain_timeout,
    draft.max_runner_lifetime,
    draft.scale_up_delay,
    draft.docker_wait,
  ].filter((value) => value.trim() !== '').length;
}

function scaling(draft: PoolDraft): string {
  // "5m" is how an operator says it; the API says "5m0s" and the display form
  // of the same duration reads "5m 00s".
  const idle = shortGoDuration(draft.idle_timeout);
  const overrides = timings(draft);
  return join([
    `${count(draft.min_runners)} to ${count(draft.max_runners)} runners`,
    idle && `idle ${idle}`,
    !draft.ephemeral && 'reused between jobs',
    count(draft.priority) !== 0 && `priority ${count(draft.priority)}`,
    overrides > 0 && `${overrides} timing ${overrides === 1 ? 'override' : 'overrides'}`,
  ]);
}

function speed(draft: PoolDraft): string {
  const folders = [
    draft.tmpfs_work && 'work folder',
    draft.tmpfs_tmp && '/tmp',
    draft.tmpfs_daemon && draft.backend === 'docker' && draft.docker_mode === 'dind'
      ? 'image store'
      : false,
  ].filter((name): name is string => typeof name === 'string');
  const containers = draft.backend === 'docker' || draft.backend === 'podman';
  return join([
    containers && folders.length > 0
      ? `${folders.join(', ')} in memory${draft.tmpfs_auto ? ' where there is room' : ''}`
      : 'Scratch space on disk',
    draft.cache_enabled
      ? `${draft.cache_scope === 'repository' ? 'per-repository' : 'shared'} cache${draft.cache_tools ? ' with tools' : ''}`
      : 'no cache',
  ]);
}

/** The line each section's row carries, for the draft as it stands. */
export function summarise(
  draft: PoolDraft,
  context: Partial<SummaryContext> = {},
): Record<SectionId, string> {
  const ctx = { ...NONE, ...context };
  return {
    basics: basics(draft, ctx),
    hosts: hosts(draft, ctx),
    providers: providers(draft, ctx),
    runner: runner(draft),
    size: size(draft),
    scaling: scaling(draft),
    speed: speed(draft),
  };
}

/**
 * The smallest workflow that proves a fleet works.
 *
 * A new operator's first job used to need a real repository's workflow edited
 * and pushed, or the migration wizard, which opens pull requests on real
 * repositories. Neither is a thing to do to find out whether the thing you have
 * just installed runs a job at all. This is the alternative: a file that
 * touches nothing of theirs, starts by hand, and prints the one fact that says
 * where it ran.
 *
 * `workflow_dispatch` and not a push trigger, so the file does not fire on every
 * commit afterwards -- it is a probe, and it should sit there until somebody
 * presses the button.
 */
import { runsOn } from '../brand';

/** What the Actions tab lists it as. */
export const TEST_JOB_NAME = 'Zoomies test job';

/** Where it goes in a repository. */
export const TEST_JOB_FILE = '.github/workflows/zoomies-test.yml';

/**
 * The complete file for a pool with these labels.
 *
 * It asks for the pool by the same `runs-on` value everything else in the
 * product prints, so a pool labelled with several labels gets the list form and
 * the job reaches that pool and no other.
 */
export function testJobWorkflow(labels: readonly string[], windows = false): string {
  return [
    `name: ${TEST_JOB_NAME}`,
    'on: workflow_dispatch',
    'permissions: {}',
    'jobs:',
    '  hello:',
    `    runs-on: ${runsOn(labels)}`,
    '    timeout-minutes: 5',
    '    steps:',
    // The sleep is the point of the third line: a job that finishes in
    // milliseconds is over before an operator has looked from GitHub to this
    // page, and they would see a runner appear and vanish without ever having
    // seen it busy.
    '      - run: |',
    ...(windows
      ? [
          '          Write-Output "Hello from $env:COMPUTERNAME"',
          '          Start-Sleep -Seconds 5',
        ]
      : ['          echo "Hello from $(hostname)"', '          uname -a', '          sleep 5']),
    '',
  ].join('\n');
}

/**
 * What the controller's dry run comes to, in a line.
 *
 * The sticky bar beside the Create button is the one place the whole pool's
 * state is on screen at once, so what it says has to be decided in one place
 * and held by a test: whether something is wrong, whether nothing has changed,
 * whether the controller has not been heard from, and -- when all of that is
 * clear -- the sentence that matters most to a pool nobody has run yet, how
 * many machines can actually run it.
 *
 * Pure, so the wording can be pinned. The order of the checks is the point: a
 * rule the browser can see is said before anything the controller thinks, and
 * a controller that has not answered is said before it is trusted.
 */
import type { Problem, Result } from '$lib/api/types';
import { pluralise } from '$lib/format';
import { isStartupFinding } from './startupStability';

type Verdict = Result<'validatePool'>;

/**
 * The warnings that have somewhere better to be. The sections that change them
 * render the three room warnings themselves, with the fix one click away; the
 * fleet's own account of which host is out is the controller panel's; and the
 * startup recommendations have a panel with the button that applies them.
 */
const ROOM_CODES = ['pool.max_above_room', 'pool.host_overcommitted', 'pool.cache_above_disk'];

export function visibleWarnings(verdict: Verdict | null): Problem[] {
  return (verdict?.warnings ?? []).filter(
    (warning) =>
      warning.code !== 'pool.no_matching_hosts' &&
      !ROOM_CODES.includes(warning.code ?? '') &&
      !isStartupFinding(warning),
  );
}

export interface Status {
  tone: 'neutral' | 'ok' | 'warning' | 'danger';
  text: string;
  /** Present when the line has something to open: the first thing to fix. */
  action?: string;
}

export interface StatusInput {
  /** The rules the browser can check on its own, however many are being broken. */
  blockers: number;
  /** How many of the controller's refusals the browser has not already said. */
  refusals: number;
  editing: boolean;
  /** Whether an edit has changed anything. Always true for a pool being created. */
  dirty: boolean;
  /** The dry run failed to answer. */
  unreachable: boolean;
  verdict: Verdict | null;
  /** True once the fleet has been asked, so a count of none is a fact and not a blank. */
  fleetKnown: boolean;
}

export function statusLine(input: StatusInput): Status {
  const { blockers, refusals, editing, dirty, unreachable, verdict, fleetKnown } = input;
  const saved = editing ? 'saved' : 'created';

  if (blockers > 0) {
    return {
      tone: 'danger',
      text:
        blockers === 1
          ? `1 thing to fix before this can be ${saved}.`
          : `${blockers} things to fix before this can be ${saved}.`,
      action: 'Show',
    };
  }
  if (editing && !dirty) return { tone: 'neutral', text: 'No changes yet.' };
  if (unreachable) {
    return {
      tone: 'warning',
      text: 'The controller could not check this pool. It is checked again when you save.',
    };
  }
  if (verdict === null) return { tone: 'neutral', text: 'Checking with the controller…' };
  if (refusals > 0) {
    return {
      tone: 'danger',
      text: 'The controller will not accept this pool yet.',
      action: 'Show',
    };
  }

  const matching = verdict.matching_hosts;
  if (fleetKnown && matching === 0) {
    return {
      tone: 'warning',
      text: `No connected host can run this pool yet. It is ${saved} anyway, and waits for one.`,
    };
  }
  const warnings = visibleWarnings(verdict).length;
  if (warnings > 0) {
    return {
      tone: 'warning',
      text: `Ready, with ${warnings === 1 ? 'a warning' : `${warnings} warnings`} to read below.`,
    };
  }
  const runners = verdict.room?.runners ?? 0;
  if (matching !== undefined && matching > 0) {
    return {
      tone: 'ok',
      text:
        runners > 0
          ? `Room for ${pluralise(runners, 'runner')} on ${pluralise(matching, 'host')}.`
          : `${pluralise(matching, 'connected host')} can run this pool.`,
    };
  }
  return { tone: 'neutral', text: 'Nothing to flag.' };
}

/**
 * The words the pool pages share: backend and Docker-mode names, and the human
 * label for every field the API can reject.
 *
 * This file has no markup on purpose. The editor, the pools grid and the pool
 * detail page all need the same vocabulary, and an operator who reads "Host
 * socket" in a table and then "host-socket" in the editor has to work out that
 * they are the same thing. Keeping the strings here means they cannot drift --
 * and it keeps the editor's sections importable without the sections importing
 * the editor back.
 */
import type { BackendKind, DockerMode, Host, MemoryBurstPolicy, Platform } from '$lib/api/types';
import { pluralise } from '$lib/format';
import { memoryLabel } from './sizing';

export interface Choice<T> {
  value: T;
  label: string;
  /** One line: what choosing this actually means for a job. */
  consequence: string;
}

export const BACKENDS: readonly Choice<BackendKind>[] = [
  {
    value: 'docker',
    label: 'Docker',
    consequence: 'Each runner is a container, thrown away when the job ends.',
  },
  {
    value: 'podman',
    label: 'Podman',
    consequence: 'The same as Docker, without a root daemon on the host.',
  },
  {
    value: 'process',
    label: 'Process',
    consequence:
      'The runner is a plain process on the host, so a job can see and change the host filesystem.',
  },
];

export const DOCKER_MODES: readonly Choice<DockerMode>[] = [
  {
    value: 'none',
    label: 'None',
    consequence:
      'Jobs get no Docker daemon, so a docker step, a container: or a services: block fails on this pool. The safe default.',
  },
  {
    value: 'dind',
    label: 'Docker in Docker',
    consequence: 'Each job gets a private, privileged Docker daemon of its own.',
  },
  {
    value: 'host-socket',
    label: 'Host socket',
    consequence:
      "Jobs share the host's Docker daemon, which means any job on this pool can become root on the host.",
  },
];

export function backendLabel(kind: BackendKind | undefined): string {
  return BACKENDS.find((b) => b.value === kind)?.label ?? 'Not set';
}

export function dockerModeLabel(mode: DockerMode | undefined): string {
  return DOCKER_MODES.find((m) => m.value === (mode ?? 'none'))?.label ?? 'None';
}

/* -- platforms ----------------------------------------------------------- */

/**
 * How an operating system is spelled in prose. The API sends the canonical
 * lowercase form; this is the only place that decides it reads "macOS" and
 * not "macos".
 */
const OS_NAMES: Readonly<Record<string, string>> = {
  ubuntu: 'Ubuntu',
  debian: 'Debian',
  fedora: 'Fedora',
  rocky: 'Rocky Linux',
  alpine: 'Alpine',
  macos: 'macOS',
  windows: 'Windows',
};

export function osLabel(os: string | undefined): string {
  if (!os) return '';
  return OS_NAMES[os] ?? os;
}

/**
 * A platform as one line: "Ubuntu 24.04, arm64". Empty fields are left out
 * rather than filled with "any", because a pool that says only "arm64" is
 * making exactly one promise and the line should read as one.
 */
export function platformLabel(platform: Platform | undefined): string {
  const parts: string[] = [];
  const os = osLabel(platform?.os);
  if (os) parts.push(platform?.os_version ? `${os} ${platform.os_version}` : os);
  if (platform?.arch) parts.push(platform.arch);
  return parts.join(', ');
}

/** The same, but with the word an empty platform deserves. */
export function platformLabelOrAny(platform: Platform | undefined): string {
  return platformLabel(platform) || 'Any host';
}

/** The value a platform select uses: "ubuntu-24.04", or "" for "any". */
export function platformKey(os: string | undefined, version: string | undefined): string {
  if (!os) return '';
  return version ? `${os}-${version}` : os;
}

/** What the fleet can actually run right now, counted from the connected hosts. */
export interface BackendOffer {
  kind: BackendKind;
  /** Hosts where this backend is available. */
  hosts: number;
  /** Hosts where Docker in Docker is possible. */
  dindHosts: number;
  /** The first host's explanation of why it is unavailable, when there is one. */
  detail?: string;
}

export function backendOffers(hosts: readonly Host[]): BackendOffer[] {
  const kinds: BackendKind[] = ['docker', 'podman', 'process'];
  return kinds.map((kind) => {
    let available = 0;
    let dind = 0;
    let detail: string | undefined;
    for (const host of hosts) {
      const info = (host.backend_info ?? []).find((entry) => entry.kind === kind);
      const listed = info?.available === true || (host.backends ?? []).includes(kind);
      if (listed) available += 1;
      if (listed && info?.supports_dind === true) dind += 1;
      if (!listed && detail === undefined && info?.detail) detail = info.detail;
    }
    const offer: BackendOffer = { kind, hosts: available, dindHosts: dind };
    if (detail !== undefined) offer.detail = detail;
    return offer;
  });
}

/**
 * Why this backend cannot be chosen, or "" when it can.
 *
 * A pool whose backend no host offers never makes a runner and looks perfectly
 * healthy doing it, so the editor refuses to create one while the fleet has
 * something else to offer. The escape hatch is deliberate: when nothing is
 * connected, or nothing is offering anything, there is no better answer to
 * insist on and the pool is allowed through with a warning -- which is how the
 * first pool gets created before the first agent joins.
 */
export function backendUnavailable(
  backend: BackendKind,
  offers: readonly BackendOffer[],
  hostsKnown: boolean,
  /** True when the offers were counted over a pool's selected hosts only. */
  restricted = false,
): string {
  if (!hostsKnown) return '';
  const chosen = offers.find((offer) => offer.kind === backend);
  if (!chosen || chosen.hosts > 0) return '';
  const others = offers.filter((offer) => offer.kind !== backend && offer.hosts > 0);
  if (others.length === 0) return '';
  const alternatives = others
    .map((offer) => `${backendLabel(offer.kind)} (${pluralise(offer.hosts, 'host')})`)
    .join(' or ');
  const because = chosen.detail ? ` ${chosen.detail}` : '';
  // Once a pool is kept to some of the fleet, "no connected host offers it"
  // is false as often as it is true -- the daemon may be running happily on
  // the machines this pool is not allowed to use. Say which set was counted.
  const nobody = restricted
    ? `No matching host offers ${backendLabel(backend)}`
    : `No connected host offers ${backendLabel(backend)}`;
  const fix = restricted
    ? `, widen which hosts this pool may use, or make ${backendLabel(backend)} work on one of them first.`
    : `, or make ${backendLabel(backend)} work on a host first.`;
  return `${nobody}, so this pool would never start a runner.${because} Choose ${alternatives}${fix}`;
}

