/**
 * What a pool's memory valve is set to, in a line: the mode, the most a runner
 * may hold and the swap it may fall back on. The pool page and the CLI say it the
 * same way, so an operator reading one finds the other.
 */
export function memoryBurstLabel(policy: MemoryBurstPolicy | undefined): string {
  if (policy?.mode === 'observe') return 'Observe only';
  if (policy?.mode !== 'automatic') return 'Off';
  const ceiling =
    (policy.max_memory_mb ?? 0) > 0
      ? `up to ${memoryLabel(policy.max_memory_mb ?? 0)} per runner`
      : 'up to half as much again as a runner starts with';
  const swap =
    (policy.spill_mb ?? 0) > 0
      ? `, with up to ${memoryLabel(policy.spill_mb ?? 0)} of swap as the last resort`
      : '';
  return `Automatic, ${ceiling}${swap}`;
}

/**
 * The rules for what an operator's dismissals still cover, kept apart from the
 * store that holds them because they are plain enough to test in Node and
 * because the store has three places that must agree on them: what hides a
 * problem, what a sweep may forget, and what is worth sending to the server.
 */
import type { Problem, ProblemDismissal, Severity } from '../api/types';

/** Worst first. The panel, the badge and the summary all read this order. */
export const SEVERITY_ORDER: readonly Severity[] = ['error', 'warning', 'info'];

export function severityOf(problem: Problem): Severity {
  return problem.severity ?? 'info';
}

export function rank(value: Severity): number {
  const i = SEVERITY_ORDER.indexOf(value);
  return i < 0 ? SEVERITY_ORDER.length : i;
}

export interface Dismissal {
  /** The severity that was read. Anything worse comes back. */
  severity: Severity;
  /** When it was dismissed, so the drawer can say how old the decision is. */
  at: string;
  /** Set on a snooze: the moment it expires and the problem becomes active
   * again on its own. Absent on a plain "dismiss until resolved". */
  until?: string;
}

export type Dismissals = Record<string, Dismissal>;

export function expired(record: Dismissal, now: number): boolean {
  return record.until !== undefined && new Date(record.until).getTime() <= now;
}

/** Whether this decision still hides a problem of the given severity. */
export function covers(record: Dismissal | undefined, problem: Problem, now: number): boolean {
  if (!record || expired(record, now)) return false;
  // A warning that has since become an error was never read as an error.
  return rank(severityOf(problem)) >= rank(record.severity);
}

/**
 * The keys a sweep may forget.
 *
 * A plain dismissal is spent the moment the controller stops reporting the
 * problem, so the fault recurring is news again. A snooze is not: the operator
 * chose how long, and a problem that clears for one reconciliation pass and
 * comes back -- a queue that drains and refills, a host that blips -- is the
 * very thing a 24 hour snooze is for. Dropping it on the first quiet pass is
 * what made "snooze for 24 hours" last until the next gap, and a snooze of a
 * whole kind could not outlive the last problem of that kind at all. A snooze
 * ends when its clock does, and not before.
 */
export function spentKeys(
  dismissals: Dismissals,
  reported: ReadonlySet<string>,
  now: number,
): string[] {
  const out: string[] = [];
  for (const [key, record] of Object.entries(dismissals)) {
    if (expired(record, now)) out.push(key);
    else if (record.until === undefined && !reported.has(key)) out.push(key);
  }
  return out;
}

/** What the server holds, in the shape the store keeps. Expired snoozes are
 * left out: the server drops them on read, but a clock that disagrees must not
 * resurrect one. */
export function fromServer(items: readonly ProblemDismissal[], now: number): Dismissals {
  const out: Dismissals = {};
  for (const item of items) {
    const record: Dismissal = {
      severity: item.severity,
      at: item.at ?? new Date(now).toISOString(),
      ...(item.until ? { until: item.until } : {}),
    };
    if (!expired(record, now)) out[item.key] = record;
  }
  return out;
}

export function toServer(key: string, record: Dismissal): ProblemDismissal {
  return {
    key,
    severity: record.severity,
    at: record.at,
    ...(record.until ? { until: record.until } : {}),
  };
}

/**
 * What a browser's older, local-only dismissals add to an account's. Anything
 * the account already holds wins: it was made on purpose, more recently than a
 * copy that has been sitting in a browser, and uploading over it would undo it.
 */
export function carriedOver(
  local: Dismissals,
  remote: Dismissals,
  now: number,
): ProblemDismissal[] {
  return Object.entries(local)
    .filter(([key, record]) => !(key in remote) && !expired(record, now))
    .map(([key, record]) => toServer(key, record));
}

/**
 * Where a host problem's "open" link goes.
 *
 * Kept apart from `ProblemItem.svelte`, which cannot be loaded outside a
 * browser, so the one rule here is tested in Node: the three OS health codes
 * are about what a host's report says, and the page that has the report is the
 * host's own. The two update codes are about one host's agent being updated, and
 * the host's page is where an administrator asks for that. No other host
 * problem belongs there: those are about the agent going quiet, the host's
 * capacity or its folders, and the list is where a host's state and its slots
 * are.
 */
const HOST_PAGE_CODES: ReadonlySet<string> = new Set([
  'host.os_health',
  'host.health_stale',
  'host.reboot_pending',
  'host.update_failed',
  'host.update_helper_stuck',
  'host.update_unavailable',
]);

export function hostTarget(code: string | undefined, id: string): { href: string; label: string } {
  return code !== undefined && HOST_PAGE_CODES.has(code)
    ? { href: `/hosts/${id}`, label: 'Open the host' }
    : { href: '/hosts', label: 'Open hosts' };
}

/**
 * Where a controller problem's "open" link goes, or null for one with no page
 * of its own.
 *
 * A controller problem names no pool, host or setting, so the code is all there
 * is to go by. The notice that a newer release exists is about updating, and the
 * Updates page reads that same release in full and says what the update mode
 * would do about it. A code is added here when it has been given a page, never
 * guessed at: a link to a page that says nothing about what the problem said is
 * worse than no link.
 */
export function controllerTarget(code: string | undefined): { href: string; label: string } | null {
  return code === 'controller.update_available'
    ? { href: '/settings/updates', label: 'Open Updates' }
    : null;
}

/**
 * Clearing out machines in bulk: which can be ticked, what the confirmation says
 * it is about to do, and how to read the answer.
 *
 * Pure, and in a `.ts` rather than a component, for the reason `machines.ts` is.
 * The sentence "this destroys three VMs" is the one that has to be right,
 * because the operator reads it to decide whether to type the count, and it is
 * testable here without a browser.
 */
import type { Machine, MachineState } from '../api/types';
import { formatNumber, pluralise } from '../format';
import { ownsResource } from './machines';

/**
 * Why a machine cannot be ticked, for the states the controller would only
 * refuse. The rest of the rules (a quarantined machine, one with runners on it)
 * are the controller's to apply, and a refusal comes back against its row.
 */
const CANNOT: Readonly<Partial<Record<MachineState, string>>> = {
  planned:
    'Not created yet, so there is nothing to delete. It becomes failed if its create is never issued, and can be deleted then.',
  deleting: 'Already being deleted.',
  deleted: 'Already deleted.',
  quarantined:
    'Quarantined: nothing could prove the resource is ours, so it is never deleted from here. Open it to release the row instead.',
};

/** Why a machine cannot be ticked, or '' when it can. */
export function cannotDeleteBecause(machine: Machine): string {
  // A row with no state is one nobody has checked the rules against, and the
  // safe answer to "may this be destroyed?" is no.
  if (machine.state === undefined)
    return 'The controller has not said what state this machine is in.';
  return CANNOT[machine.state] ?? '';
}

/** The machines that can be ticked, in the order they were listed. */
export function deletable(machines: readonly Machine[]): Machine[] {
  return machines.filter((machine) => cannotDeleteBecause(machine) === '');
}

export interface DeletionPlan {
  total: number;
  /** Machines with a VM behind them: deleting these destroys something. */
  withVM: number;
  /** Machines that never got as far as a VM, or whose VM is confirmed gone. */
  withoutVM: number;
}

export function planDeletion(machines: readonly Machine[]): DeletionPlan {
  const withVM = machines.filter(ownsResource).length;
  return { total: machines.length, withVM, withoutVM: machines.length - withVM };
}

export interface DeletionWords {
  title: string;
  description: string;
  consequences: string[];
  confirmLabel: string;
  /** What has to be typed to confirm, or null when a click will do. */
  confirmWord: string | null;
}

/**
 * What the confirmation says. Typing is for the delete that destroys a VM and
 * cannot be taken back; a pile of machines that never got one is cleared with a
 * click, because making an operator type a number to tidy up rows that cost
 * nothing teaches them to type it without reading it.
 */
export function deletionWords(plan: DeletionPlan, force: boolean): DeletionWords {
  const machines = pluralise(plan.total, 'machine');
  const consequences: string[] = [];

  let description: string;
  if (plan.withVM === 0) {
    description = `Deletes ${machines} that never got as far as a VM. Nothing at the provider is touched.`;
  } else {
    const vms = `${pluralise(plan.withVM, 'VM')} ${plan.withVM === 1 ? 'is' : 'are'}`;
    description = `Deletes ${machines}. ${vms} destroyed at the provider.`;
    if (plan.withoutVM > 0) {
      const rest = plan.withoutVM === 1 ? 'one' : formatNumber(plan.withoutVM);
      description += ` The other ${rest} never got as far as a VM, so nothing is destroyed for ${plan.withoutVM === 1 ? 'it' : 'them'}.`;
    }
    consequences.push(
      'A machine is not counted as gone until the provider can no longer find its VM.',
    );
  }
  consequences.push(
    force
      ? 'Runners on them stop, and any job they are running fails.'
      : 'A machine that still has runners on it is skipped, and stays selected so you can see why.',
    'Nothing rebuilds them. A pool with work will ask for new machines instead.',
  );

  return {
    title: `Delete ${machines}`,
    description,
    consequences,
    confirmLabel: `Delete ${machines}`,
    confirmWord: plan.withVM > 0 ? String(plan.total) : null,
  };
}

/** One machine's answer, as POST /machines/bulk gives it. */
export interface BulkResult {
  id?: string;
  ok?: boolean;
  error?: string;
}

export interface Outcome {
  /** The machines the controller took, in the order they were asked. */
  deleted: string[];
  /** The machines it did not, each with the reason, in the order they were asked. */
  refused: Map<string, string>;
}

/**
 * Read the answer machine by machine. A machine the answer says nothing about
 * is a refusal, never a success: the alternative is telling an operator a VM is
 * on its way out when nothing said so.
 */
export function readOutcome(
  asked: readonly string[],
  answer: { results?: readonly BulkResult[] } | undefined,
): Outcome {
  const byId = new Map<string, BulkResult>();
  for (const result of answer?.results ?? []) {
    if (result.id) byId.set(result.id, result);
  }
  const deleted: string[] = [];
  const refused = new Map<string, string>();
  for (const id of asked) {
    const result = byId.get(id);
    if (result?.ok) {
      deleted.push(id);
    } else if (result === undefined) {
      refused.set(
        id,
        'The controller did not answer for this machine, so it may not have been deleted.',
      );
    } else {
      refused.set(id, result.error || 'The controller refused this machine and did not say why.');
    }
  }
  return { deleted, refused };
}

export interface OutcomeWords {
  tone: 'success' | 'warning' | 'error';
  title: string;
  message: string;
}

/** The toast for how it went. A partial failure is a warning, announced as one. */
export function outcomeWords(deleted: number, refused: number): OutcomeWords {
  if (deleted === 0) {
    return {
      tone: 'error',
      title: 'No machine was deleted',
      message:
        refused === 1
          ? 'It was refused, and the reason is on its row.'
          : `${formatNumber(refused)} were refused, and the reason is on each row.`,
    };
  }
  const machines = pluralise(deleted, 'machine');
  if (refused === 0) {
    return {
      tone: 'success',
      title: `Deleting ${machines}`,
      message: 'A machine is not gone until the provider cannot find its VM.',
    };
  }
  return {
    tone: 'warning',
    title: `Deleting ${machines}, ${formatNumber(refused)} refused`,
    message:
      refused === 1
        ? 'The refused one stays selected, with the reason on its row.'
        : 'The refused ones stay selected, with the reason on each row.',
  };
}

/**
 * The provider wizard's draft, and the words it renders with.
 *
 * Pure, and in a `.ts` rather than in the form's `<script module>`, for one
 * reason: the unit tests run under Node with no Svelte compiler, so machinery
 * kept inside a component is machinery nothing can test without a browser.
 * The pool editor's draft is a `.ts` for the same reason (`pools/draft.ts`).
 *
 * Numbers are held as strings because that is what a text input gives back,
 * and because '' and '0' are different answers -- one is "not filled in", the
 * other is a deliberate zero, and `max_machines: 0` is the setting that rents
 * nothing. They become numbers exactly once, in `toProviderBody`.
 */
import type {
  BackendKind,
  Provider,
  ProviderChoice,
  ProviderDiscovery,
  ProviderInput,
  ProviderKindName,
  ProviderSetting,
} from '../api/types';

export interface WizardStepDef {
  id: string;
  title: string;
  description?: string;
}

/**
 * The steps, in the order the questions are asked: where it is and how we
 * sign in, what it should build, how big a machine is, what it may spend, and
 * then what the controller makes of all that.
 */
export const WIZARD_STEPS: readonly WizardStepDef[] = [
  {
    id: 'connect',
    title: 'Connect',
    description: 'Where Zoomies reaches the provider, and what it signs in with.',
  },
  {
    id: 'placement',
    title: 'Placement',
    description: "The driver's own settings: where a machine is built and from what.",
  },
  {
    id: 'machine',
    title: 'Machine',
    description: 'The one machine shape this provider offers. A second shape is a second provider.',
  },
  {
    id: 'limits',
    title: 'Limits',
    description:
      'The most machines it may rent, and how many stay warm. A maximum of zero rents nothing.',
  },
  { id: 'review', title: 'Review', description: 'What the controller makes of it.' },
];

/** Which API field names live on which step, so a rejection lands on the right one. */
export const STEP_FIELDS: readonly (readonly string[])[] = [
  [
    'kind',
    'setup_id',
    'name',
    'endpoint',
    'connection',
    'tailcat_address',
    'credential',
    'ca_pem',
    'insecure_skip_verify',
  ],
  ['settings', 'machine_ca_pem'],
  [
    'machine_capacity',
    'machine_backend',
    'machine_cpus',
    'machine_memory_mb',
    'machine_disk_mb',
    'machine_platform',
    'machine_labels',
  ],
  [
    'max_machines',
    'min_machines',
    'max_creates_in_flight',
    'idle_timeout',
    'cost_per_machine_hour',
    'enabled',
    'pool_selector',
  ],
  [],
];

/** Human labels for the field names the API rejects things under. */
export const FIELD_LABELS: Readonly<Record<string, string>> = {
  kind: 'Kind',
  setup_id: 'Proxmox connection',
  name: 'Name',
  endpoint: 'Address',
  connection: 'Connection',
  tailcat_address: 'Private connection address',
  credential: 'Credential',
  ca_pem: 'Certificate authority',
  machine_ca_pem: 'Certificate for machines',
  insecure_skip_verify: 'Certificate verification',
  settings: 'Placement settings',
  machine_capacity: 'Runner slots per machine',
  machine_backend: 'Backend',
  machine_cpus: 'vCPUs',
  machine_memory_mb: 'Memory',
  machine_disk_mb: 'Disk',
  machine_platform: 'Operating system',
  machine_labels: 'Machine labels',
  max_machines: 'Maximum machines',
  min_machines: 'Warm machines',
  max_creates_in_flight: 'Machines built at once',
  idle_timeout: 'Idle timeout',
  cost_per_machine_hour: 'Cost per machine-hour',
  enabled: 'Enabled',
  pool_selector: 'Pools it rents for',
};

/**
 * Which step a field belongs to. A driver's own setting arrives as
 * `settings.<key>`, which is the placement step whatever the key is; anything
 * unrecognised falls back to the review step, where every message is shown at
 * once.
 */
export function stepForField(field: string): number {
  const key = field.startsWith('settings.') ? 'settings' : field;
  const index = STEP_FIELDS.findIndex((fields) => fields.includes(key));
  return index === -1 ? WIZARD_STEPS.length - 1 : index;
}

export interface ProviderDraft {
  setup_id?: string;
  /**
   * Plain strings, not the generated unions. Every control in the form binds a
   * string, and a draft typed as the union would make the two disagree the
   * moment a `<select>` was involved; the narrowing happens once, on the way
   * out, in `toProviderBody`.
   */
  kind: string;
  name: string;
  endpoint: string;
  ca_pem: string;
  /**
   * The certificate a machine built here trusts for the controller. Not the
   * cluster's: that authority has no reason to have signed the controller, and
   * a machine accepts only this one when it is set.
   */
  machine_ca_pem: string;
  insecure_skip_verify: boolean;
  /** How the controller reaches the address: 'direct' or 'tailcat'. */
  connection: string;
  /**
   * The gateway's address. Handled as the credential is: never populated from
   * a provider that already exists, and an empty box on an edit means "leave
   * the stored one alone". `tailcat_configured` is what the form is told
   * instead, so it can show that one is set without holding it.
   */
  tailcat_address: string;
  tailcat_configured: boolean;
  /**
   * Never populated from a provider that already exists: the controller seals
   * it and never gives it back, so an empty box on an edit means "leave the
   * stored one alone" rather than "erase it".
   */
  credential: string;
  /** The driver's own answers, keyed by SettingSpec.key. */
  settings: Record<string, string>;
  machine_labels: Record<string, string>;
  /** Which pools this provider will rent machines for; empty means every pool. */
  pool_selector: Record<string, string>;
  machine_capacity: string;
  machine_backend: string;
  machine_cpus: string;
  machine_memory_mb: string;
  machine_disk_mb: string;
  machine_os: string;
  machine_os_version: string;
  machine_arch: string;
  max_machines: string;
  min_machines: string;
  max_creates_in_flight: string;
  idle_timeout: string;
  cost_per_machine_hour: string;
  enabled: boolean;
}

export function emptyDraft(): ProviderDraft {
  return {
    kind: '',
    name: '',
    endpoint: '',
    ca_pem: '',
    machine_ca_pem: '',
    insecure_skip_verify: false,
    connection: 'direct',
    tailcat_address: '',
    tailcat_configured: false,
    credential: '',
    settings: {},
    machine_labels: {},
    pool_selector: {},
    machine_capacity: '2',
    machine_backend: 'docker',
    machine_cpus: '',
    machine_memory_mb: '',
    machine_disk_mb: '',
    machine_os: '',
    machine_os_version: '',
    machine_arch: '',
    // A small start rather than zero, which rents nothing and is no answer to
    // "how many machines". The Proxmox wizard replaces both with what the
    // cluster can hold once it has been asked (`recommend.ts`); this is what a
    // driver that cannot be asked, and the manual path, open on.
    max_machines: '2',
    // One kept warm, so the first job after a quiet spell does not wait for a clone.
    min_machines: '1',
    max_creates_in_flight: '1',
    idle_timeout: '15m',
    cost_per_machine_hour: '',
    enabled: true,
  };
}

function fromNumber(value: number | undefined): string {
  return value === undefined || value === null ? '' : String(value);
}

export function draftFromProvider(provider: Provider): ProviderDraft {
  const base = emptyDraft();
  return {
    ...base,
    kind: provider.kind ?? '',
    name: provider.name ?? '',
    endpoint: provider.endpoint ?? '',
    // The box opens with what is trusted. The credential and the gateway address
    // come back empty because they are sealed and an empty box keeps them; the
    // certificate is neither, so an empty box means "none" and saving one would
    // clear what the connection depends on.
    ca_pem: provider.ca_pem ?? '',
    machine_ca_pem: provider.machine_ca_pem ?? '',
    insecure_skip_verify: provider.insecure_skip_verify === true,
    connection: provider.connection === 'tailcat' ? 'tailcat' : 'direct',
    tailcat_configured: provider.connection === 'tailcat',
    settings: { ...(provider.settings ?? {}) },
    machine_labels: { ...(provider.machine_labels ?? {}) },
    pool_selector: { ...(provider.pool_selector ?? {}) },
    machine_capacity: fromNumber(provider.machine_capacity) || base.machine_capacity,
    machine_backend: provider.machine_backend ?? base.machine_backend,
    machine_cpus: fromNumber(provider.machine_cpus),
    machine_memory_mb: fromNumber(provider.machine_memory_mb),
    machine_disk_mb: fromNumber(provider.machine_disk_mb),
    machine_os: provider.machine_platform?.os ?? '',
    machine_os_version: provider.machine_platform?.os_version ?? '',
    machine_arch: provider.machine_platform?.arch ?? '',
    max_machines: fromNumber(provider.max_machines) || '0',
    min_machines: fromNumber(provider.min_machines) || '0',
    max_creates_in_flight: fromNumber(provider.max_creates_in_flight) || '1',
    idle_timeout: msToDuration(provider.idle_timeout_ms) || base.idle_timeout,
    cost_per_machine_hour: fromNumber(provider.cost_per_machine_hour),
    enabled: provider.enabled !== false,
  };
}

/** A Go duration from milliseconds, in the units an operator typed them in. */
function msToDuration(ms: number | undefined): string {
  if (!ms || ms <= 0) return '';
  if (ms % 3_600_000 === 0) return `${ms / 3_600_000}h`;
  if (ms % 60_000 === 0) return `${ms / 60_000}m`;
  return `${Math.round(ms / 1000)}s`;
}

/**
 * Fill in the answers the driver has a default for, without touching one the
 * operator has already given.
 *
 * A form that comes filled in is the difference between a wizard and an
 * interrogation -- `AddHostFlow` arrives with the controller address already
 * in it for the same reason -- and a default the driver published is a better
 * answer than an empty box every time.
 */
export function applySettingDefaults(
  draft: ProviderDraft,
  specs: readonly ProviderSetting[],
): ProviderDraft {
  const settings = { ...draft.settings };
  let changed = false;
  for (const spec of specs) {
    if (!spec.default) continue;
    if (settings[spec.key] !== undefined && settings[spec.key] !== '') continue;
    settings[spec.key] = spec.default;
    changed = true;
  }
  return changed ? { ...draft, settings } : draft;
}

function num(value: string): number | undefined {
  const trimmed = value.trim();
  if (trimmed === '') return undefined;
  const n = Number(trimmed);
  return Number.isFinite(n) ? n : undefined;
}

/**
 * The request body.
 *
 * `complete` is for an edit: a PATCH leaves what it does not name alone, so a
 * field an operator cleared has to be sent as its empty value or clearing it
 * does nothing. The credential is the one exception in both directions -- an
 * empty one is never sent, because the server reads that as "keep the stored
 * one" and sending it would be the only way to make a blank box erase a
 * working credential.
 */
export function toProviderBody(
  draft: ProviderDraft,
  options: { complete?: boolean } = {},
): ProviderInput {
  const complete = options.complete === true;
  const body: ProviderInput = {
    name: draft.name.trim(),
    endpoint: draft.endpoint.trim(),
    insecure_skip_verify: draft.insecure_skip_verify,
    connection: draft.connection === 'tailcat' ? 'tailcat' : 'direct',
    settings: trimmedMap(draft.settings),
    machine_labels: trimmedMap(draft.machine_labels),
    pool_selector: trimmedMap(draft.pool_selector),
    machine_capacity: num(draft.machine_capacity) ?? 2,
    machine_backend: draft.machine_backend as BackendKind,
    max_machines: num(draft.max_machines) ?? 0,
    min_machines: num(draft.min_machines) ?? 0,
    max_creates_in_flight: num(draft.max_creates_in_flight) ?? 1,
    enabled: draft.enabled,
  };
  if (draft.setup_id) body.setup_id = draft.setup_id;
  if (draft.kind !== '') body.kind = draft.kind as ProviderKindName;
  if (draft.credential.trim() !== '') body.credential = draft.credential;
  // Only ever sent alongside a private connection, and never empty: the
  // server reads an empty one as "keep the stored address", and naming
  // 'direct' is what clears it.
  if (draft.connection === 'tailcat' && draft.tailcat_address.trim() !== '')
    body.tailcat_address = draft.tailcat_address.trim();
  if (draft.ca_pem.trim() !== '' || complete) body.ca_pem = draft.ca_pem.trim();
  if (draft.machine_ca_pem.trim() !== '' || complete)
    body.machine_ca_pem = draft.machine_ca_pem.trim();

  const platform: NonNullable<ProviderInput['machine_platform']> = {};
  if (draft.machine_os !== '') platform.os = draft.machine_os as NonNullable<typeof platform.os>;
  if (draft.machine_os_version.trim() !== '') platform.os_version = draft.machine_os_version.trim();
  if (draft.machine_arch !== '')
    platform.arch = draft.machine_arch as NonNullable<typeof platform.arch>;
  if (Object.keys(platform).length > 0 || complete) body.machine_platform = platform;

  assignNumber(body, 'machine_cpus', draft.machine_cpus, complete);
  assignNumber(body, 'machine_memory_mb', draft.machine_memory_mb, complete);
  assignNumber(body, 'machine_disk_mb', draft.machine_disk_mb, complete);
  assignNumber(body, 'cost_per_machine_hour', draft.cost_per_machine_hour, complete);

  const idle = draft.idle_timeout.trim();
  if (idle !== '' || complete) body.idle_timeout = idle;
  return body;
}

type NumericField =
  'machine_cpus' | 'machine_memory_mb' | 'machine_disk_mb' | 'cost_per_machine_hour';

function assignNumber(
  body: ProviderInput,
  field: NumericField,
  value: string,
  complete: boolean,
): void {
  const parsed = num(value);
  if (parsed !== undefined) body[field] = parsed;
  else if (complete) body[field] = 0;
}

function trimmedMap(map: Record<string, string>): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [key, value] of Object.entries(map)) {
    const k = key.trim();
    if (k === '') continue;
    out[k] = value.trim();
  }
  return out;
}

/** A Go duration, as the API's Duration type spells one. */
const DURATION = /^\d+(\.\d+)?(ns|us|µs|ms|s|m|h)$/;

/**
 * Whether an address names the machine the controller is on, which is the one
 * case where plain HTTP carries nothing off the box.
 *
 * The server decides this too and its answer is the one that counts -- the form
 * asks it on every keystroke. This exists so the wizard does not offer
 * "or switch certificate checking off" as a way round a rule that is not about
 * certificates: a provider saved that way is refused by the driver at its first
 * call, long after the row was written.
 */
export function isLoopbackEndpoint(endpoint: string): boolean {
  let host: string;
  try {
    host = new URL(endpoint).hostname;
  } catch {
    return false;
  }
  host = host.replace(/^\[|\]$/g, '');
  if (host.toLowerCase() === 'localhost') return true;
  if (host === '::1') return true;
  return /^127\.\d{1,3}\.\d{1,3}\.\d{1,3}$/.test(host);
}

/**
 * What is wrong with the draft, keyed by the field name the API would use.
 *
 * Client rules only. Anything that needs the hypervisor -- whether the node
 * exists, whether the token may clone -- is the preflight's to answer, and
 * guessing at it here would produce a form that disagrees with the button
 * beside it.
 */
export function draftErrors(
  draft: ProviderDraft,
  specs: readonly ProviderSetting[],
  options: { editing?: boolean } = {},
): Record<string, string> {
  const out: Record<string, string> = {};
  if (draft.kind === '') out.kind = 'Choose which kind of provider this is.';
  if (draft.name.trim() === '') out.name = 'Give this provider a name you will recognise.';
  const endpoint = draft.endpoint.trim();
  if (endpoint === '') out.endpoint = 'Give the address Zoomies reaches the provider on.';
  else if (!/^https?:\/\//i.test(endpoint))
    out.endpoint = 'The address needs a scheme: https://pve.example.com:8006.';
  else if (/^http:\/\//i.test(endpoint) && !isLoopbackEndpoint(endpoint))
    out.endpoint =
      'Plain HTTP would send the credential across the network in the clear, and that credential can ' +
      'create and destroy machines. Use https. Turning certificate verification off does not permit this.';
  // An edit leaves the stored credential alone, so an empty box is an answer
  // there and a missing one only on the way in.
  if (!options.editing && !draft.setup_id && draft.credential.trim() === '')
    out.credential = 'A credential is needed before anything can be created.';
  if (draft.connection === 'tailcat') {
    const address = draft.tailcat_address.trim();
    if (address === '' && !draft.tailcat_configured)
      out.tailcat_address =
        'Paste the address zoomies gateway printed. It begins with tc and is the whole of the connection.';
    else if (address !== '' && !/^tc[A-Za-z0-9_-]{16,}$/.test(address))
      out.tailcat_address =
        'That does not look like a Tailcat address. Copy the whole address the gateway printed, beginning with tc.';
  }

  for (const spec of specs) {
    const value = (draft.settings[spec.key] ?? '').trim();
    const field = `settings.${spec.key}`;
    if (spec.required && value === '') {
      out[field] = `${spec.label} is needed.`;
      continue;
    }
    if (value !== '' && spec.kind === 'number' && num(value) === undefined) {
      out[field] = `${spec.label} has to be a number.`;
    }
  }

  const capacity = num(draft.machine_capacity);
  if (capacity === undefined || capacity < 1)
    out.machine_capacity = 'A machine has to offer at least one runner slot.';
  for (const [field, label] of [
    ['machine_cpus', 'vCPUs'],
    ['machine_memory_mb', 'Memory'],
    ['machine_disk_mb', 'Disk'],
    ['cost_per_machine_hour', 'Cost per machine-hour'],
  ] as const) {
    const raw = draft[field];
    if (raw.trim() === '') continue;
    const parsed = num(raw);
    if (parsed === undefined || parsed < 0) out[field] = `${label} has to be a number, or empty.`;
  }

  const max = num(draft.max_machines);
  if (max === undefined || max < 0 || !Number.isInteger(max))
    out.max_machines = 'A whole number of machines, or zero to rent nothing.';
  const min = num(draft.min_machines);
  if (min === undefined || min < 0 || !Number.isInteger(min))
    out.min_machines = 'A whole number of machines, or zero to keep none.';
  else if (max !== undefined && min > max)
    out.min_machines = 'No more than the maximum, which it counts against.';
  const inFlight = num(draft.max_creates_in_flight);
  if (inFlight === undefined || inFlight < 1)
    out.max_creates_in_flight = 'At least one, or nothing would ever be built.';
  const idle = draft.idle_timeout.trim();
  if (idle !== '' && !DURATION.test(idle)) out.idle_timeout = 'A duration like 15m, 1h or 90s.';
  return out;
}

/**
 * What Warm machines becomes when Maximum has just been typed.
 *
 * Zero is how an operator says rent nothing, and the box says so. A draft opens
 * on one warm machine, and a warm machine counts against the maximum, so a zero
 * typed on its own was refused for a figure in the other box, with no word of
 * why until that box was touched. Only a maximum of zero changes anything, and
 * only when it is the maximum being typed: a warm figure typed afterwards is the
 * operator's, and nothing here moves it again.
 */
export function warmForMaximum(maximum: string, warm: string): string {
  return num(maximum) === 0 ? '0' : warm;
}

/**
 * What saving a provider sets going, for the note under the toast.
 *
 * Saving creates nothing. The warm machine is bought on the next pass, so the
 * check is worth running now rather than before a first machine that nothing is
 * waiting for; without one, a machine is rented only when a pool has work with
 * nowhere to run.
 */
export function savedNote(maximum: number, warm: number): string {
  if (maximum === 0)
    return 'Nothing is rented yet: its ceiling is zero. Raise it when you are ready to spend.';
  if (warm === 0)
    return 'Machines are rented when a pool has work with nowhere to run. Run the check to see what the provider would refuse.';
  return 'Its warm machine is bought on the next pass, so run the check now to see what the provider would refuse.';
}

/**
 * Whether this draft would rent anything at all, and why not.
 *
 * A provider saved with a ceiling of zero is a legal answer, and the way to say
 * rent nothing, so this is a note beside the setting rather than an error on it.
 */
export function willRentNothing(draft: ProviderDraft): string {
  if (!draft.enabled) return 'This provider is switched off, so nothing will be built.';
  if ((num(draft.max_machines) ?? 0) === 0)
    return 'The ceiling is zero, so nothing will be built until it is raised.';
  return '';
}

/* -- filling the form in ------------------------------------------------------ */

/**
 * An address the way the driver expects one, from what somebody typed: a bare
 * host name gets the scheme, and a host with no port gets the port the
 * example uses, because "pve.home" is what people type and
 * "https://pve.home:8006" is what the API needs. Anything already complete,
 * or too odd to parse, is left exactly as it was.
 */
export function normaliseEndpoint(raw: string, example: string | undefined): string {
  let value = raw.trim();
  if (value === '') return '';
  if (!/^[a-z][a-z0-9+.-]*:\/\//i.test(value)) value = `https://${value}`;
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    return raw;
  }
  if (url.port === '' && example) {
    try {
      const port = new URL(example).port;
      if (port !== '') url.port = port;
    } catch {
      /* no usable example: the address is left without a port */
    }
  }
  // URL adds a trailing slash to a bare origin; the API wants the origin.
  return url.toString().replace(/\/$/, '');
}

/**
 * A name to suggest from the address, for the box left empty: the host's own
 * first label -- "pve" from https://pve.example.com:8006 -- which is what an
 * operator calls the cluster when they talk about it.
 */
export function suggestName(endpoint: string, fallback: string): string {
  try {
    const host = new URL(endpoint).hostname.replace(/^\[|\]$/g, '');
    const label = host.split('.')[0] ?? '';
    const slug = label
      .toLowerCase()
      .replace(/[^a-z0-9-]+/g, '-')
      .replace(/^-+|-+$/g, '');
    if (slug !== '' && !/^\d+$/.test(slug)) return slug;
  } catch {
    /* not an address yet */
  }
  return fallback;
}

/** The choices discovery offers for one setting, or none when it offers nothing. */
export function choicesFor(
  spec: ProviderSetting,
  discovery: ProviderDiscovery | null,
): ProviderChoice[] {
  if (!discovery || !spec.discovers) return [];
  const list = (discovery as unknown as Record<string, ProviderChoice[] | undefined>)[
    spec.discovers
  ];
  return Array.isArray(list) ? list : [];
}

/**
 * Fill in what discovery leaves no choice about, without touching an answer
 * the operator gave.
 *
 * A list with one entry is not a question, so it is answered. A default the
 * driver published -- vmbr0 -- that the cluster turns out not to have is
 * replaced when there is one thing to replace it with, and left alone
 * otherwise: a wrong default the operator can see beats a guess they cannot.
 */
export function applyDiscovery(
  draft: ProviderDraft,
  specs: readonly ProviderSetting[],
  discovery: ProviderDiscovery | null,
): ProviderDraft {
  if (!discovery) return draft;
  const settings = { ...draft.settings };
  let changed = false;
  for (const spec of specs) {
    const choices = choicesFor(spec, discovery);
    if (choices.length !== 1) continue;
    const only = choices[0]?.value ?? '';
    if (only === '') continue;
    const current = (settings[spec.key] ?? '').trim();
    const untouched = current === '' || current === (spec.default ?? '');
    const offered = choices.some((c) => c.value === current);
    if (current === only || (!untouched && offered)) continue;
    if (!untouched && !offered && spec.kind !== 'list') continue;
    settings[spec.key] = only;
    changed = true;
  }
  return changed ? { ...draft, settings } : draft;
}

/**
 * What a rented machine is doing, worked out from the row alone.
 *
 * Pure, and in a `.ts` rather than a component, for the reason
 * `insights/signals.ts` is: the arithmetic behind "this one has been
 * bootstrapping for eleven minutes" and "these three need a person" is what
 * goes wrong, and it is testable here without a browser.
 *
 * Nothing here reads a clock of its own. `now` is passed in, so a test can say
 * what time it is and a component can hand it the same tick it renders with.
 */
import type { Machine, MachineState, Provider } from '../api/types';

/**
 * The lifecycle as the band draws it: the states a machine passes through on
 * its way to being a host. Deleting, deleted, failed and quarantined are exits
 * from the flow rather than steps of it, and are counted separately.
 */
export const MACHINE_FLOW: readonly MachineState[] = [
  'planned',
  'creating',
  'starting',
  'bootstrapping',
  'enrolling',
  'ready',
  'draining',
];

/** The states a machine is in while the fleet is still waiting for it. */
const PENDING: ReadonlySet<MachineState> = new Set([
  'planned',
  'creating',
  'starting',
  'bootstrapping',
  'enrolling',
]);

/** The phases a timeline entry can carry, as a sentence for the page. */
const PHASES: Readonly<Record<string, string>> = {
  planned: 'Planned',
  creating: 'Creating the machine',
  created: 'Machine created',
  starting: 'Powering on',
  bootstrapped: 'Agent installed',
  enrolled: 'Enrolled with the controller',
  ready: 'Ready for work',
  draining: 'Draining',
  deleting: 'Deleting',
  deleted: 'Resource confirmed gone',
};

/**
 * What a phase is called on the page. Two consecutive rows both reading
 * "Creating" say nothing, and those rows are exactly the diagnosis: a clone
 * that never finished is a problem at the hypervisor, and a machine that
 * cloned and never enrolled is a problem inside the guest.
 */
export function phaseLabel(phase: string | undefined): string {
  if (!phase) return 'Unknown';
  return PHASES[phase] ?? phase.charAt(0).toUpperCase() + phase.slice(1);
}

/**
 * The state a timeline phase belongs to, so a row is drawn in the colour the
 * rest of the product gives that part of a machine's life. The timeline has
 * more entries than there are states -- "created" and "creating" are two marks
 * on one state -- because what an operator wants to know is which half of a
 * slow create is slow.
 */
const PHASE_STATES: Readonly<Record<string, MachineState>> = {
  planned: 'planned',
  creating: 'creating',
  created: 'creating',
  starting: 'starting',
  bootstrapped: 'bootstrapping',
  enrolled: 'enrolling',
  ready: 'ready',
  draining: 'draining',
  deleting: 'deleting',
  deleted: 'deleted',
};

export function phaseState(phase: string | undefined): MachineState | undefined {
  return phase ? PHASE_STATES[phase] : undefined;
}

export interface MachineSignals {
  /** Whether the fleet is still waiting for this machine to become a host. */
  pending: boolean;
  /** Whether it holds a resource somebody is being billed for. */
  owns: boolean;
  /** How long it has been in its current state, or null when that is unknown. */
  elapsedMs: number | null;
  /** The operation in flight, as a word, or '' when none is. */
  operation: string;
  /**
   * Whether an operator has to look at this one. It is deliberately not "the
   * state is failed": a machine whose ownership nothing could confirm, and one
   * whose last call went out and was never answered, are both running
   * hardware nothing will tidy up on its own.
   */
  needsReview: boolean;
  /** Why, in one sentence, or '' when it does not. */
  reviewReason: string;
  /** The row's own reading of whether a delete would be safe. */
  safeToDelete: boolean;
  safeToDeleteWhy: string;
}

/**
 * Whether a resource stands behind this machine: one the provider has been
 * asked for and has not confirmed gone. It mirrors `store.Machine.Owns()`, and
 * it is about the resource rather than the lifecycle, so a failed machine whose
 * VM exists still counts.
 */
export function ownsResource(machine: Machine): boolean {
  return Boolean(machine.resource_id) && !machine.deleted_at;
}

export function machineSignals(machine: Machine, now: number = Date.now()): MachineSignals {
  const since = machine.updated_at ? Date.parse(machine.updated_at) : Number.NaN;
  const state = machine.state;
  return {
    pending: state !== undefined && PENDING.has(state),
    owns: ownsResource(machine),
    elapsedMs: Number.isFinite(since) ? Math.max(0, now - since) : null,
    operation: machine.operation ?? '',
    ...review(machine),
    safeToDelete: machine.safe_to_delete === true,
    safeToDeleteWhy: machine.safe_to_delete_why ?? '',
  };
}

function review(machine: Machine): { needsReview: boolean; reviewReason: string } {
  if (machine.state === 'quarantined') {
    return {
      needsReview: true,
      reviewReason:
        machine.ownership_error ||
        'Nothing could prove this resource is ours, so nothing here will act on it.',
    };
  }
  if (machine.ownership_error) return { needsReview: true, reviewReason: machine.ownership_error };
  if (machine.state === 'failed') {
    return {
      needsReview: true,
      reviewReason:
        machine.provider_error ||
        machine.bootstrap_error ||
        'This machine never became a host. Its resource may still exist.',
    };
  }
  if (machine.outcome_unknown) {
    return {
      needsReview: true,
      reviewReason: 'A call went out and was never answered, so what happened is not known yet.',
    };
  }
  return { needsReview: false, reviewReason: '' };
}

/** Every machine an operator has to look at, in the order they were listed. */
export function machinesNeedingReview(machines: readonly Machine[]): Machine[] {
  return machines.filter((m) => review(m).needsReview);
}

export interface LifecycleStep {
  state: MachineState;
  count: number;
}

/**
 * How many machines are at each step of the flow.
 *
 * Deleted machines are left out rather than counted as zero: a fleet that has
 * been running for a month has hundreds of them, and a band whose largest
 * number is the history is a band nobody reads.
 */
export function lifecycleCounts(machines: readonly Machine[]): LifecycleStep[] {
  const counts = new Map<MachineState, number>();
  for (const state of MACHINE_FLOW) counts.set(state, 0);
  for (const machine of machines) {
    const state = machine.state;
    if (state === undefined || !counts.has(state)) continue;
    counts.set(state, (counts.get(state) ?? 0) + 1);
  }
  return MACHINE_FLOW.map((state) => ({ state, count: counts.get(state) ?? 0 }));
}

/**
 * What a machine has cost so far, or null when its provider has no opinion.
 *
 * A provider with no price is the common case -- a hypervisor in a cupboard
 * has no hourly rate -- and inventing one would be worse than saying nothing.
 */
export function machineCost(
  machine: Machine,
  provider: Pick<Provider, 'cost_per_machine_hour'> | undefined,
  now: number = Date.now(),
): number | null {
  const rate = provider?.cost_per_machine_hour ?? 0;
  if (rate <= 0) return null;
  const from = machine.created_at ? Date.parse(machine.created_at) : Number.NaN;
  if (!Number.isFinite(from)) return null;
  const to = machine.deleted_at ? Date.parse(machine.deleted_at) : now;
  if (!Number.isFinite(to)) return null;
  return (Math.max(0, to - from) / 3_600_000) * rate;
}

/**
 * A cost as a figure. Two decimals, because that is what an invoice has, and
 * an empty string rather than "0.00" when there is no price to report -- a
 * zero reads as free, which is a different claim from "nobody said".
 */
export function formatCost(value: number | null): string {
  return value === null ? '' : value.toFixed(2);
}

import type { Pool, Provider } from '$lib/api/types';

/*
  The two halves of a pool's agreement with a provider, mirrored from
  internal/scheduler/providers.go for the one place the page cannot wait for the
  server: the editor of a selector, which says which providers (or pools) the
  selector being typed would let through. Every saved pairing is read from
  GET /providers/pairings instead, so the Go rule stays the only one that acts.
*/

/** What a pool answers for a key in a provider's `pool_selector`, or undefined if it has no answer. */
export function poolSelectorValue(
  pool: Pick<Pool, 'name' | 'backend' | 'labels'>,
  key: string,
): string | undefined {
  const k = key.toLowerCase();
  if (k === 'name') return pool.name ?? '';
  if (k === 'backend') return pool.backend ? String(pool.backend) : undefined;
  for (const label of pool.labels ?? []) {
    if (label.toLowerCase() === k) return '';
    const at = label.indexOf('=');
    if (at > 0 && label.slice(0, at).toLowerCase() === k) return label.slice(at + 1);
  }
  return undefined;
}

/** What a provider answers for a key in a pool's `provider_selector`, or undefined if it has no answer. */
export function providerSelectorValue(
  provider: Pick<Provider, 'name' | 'kind' | 'machine_labels'>,
  key: string,
): string | undefined {
  const k = key.toLowerCase();
  if (k === 'name') return provider.name ?? '';
  if (k === 'kind') return provider.kind ?? '';
  const labels = provider.machine_labels ?? {};
  return key in labels ? labels[key] : undefined;
}

function satisfies(
  selector: Record<string, string>,
  value: (key: string) => string | undefined,
): boolean {
  return Object.entries(selector).every(([key, want]) => {
    const got = value(key);
    if (got === undefined) return false;
    // An entry with no value asks only that the subject carries the key.
    return want === '' || got.toLowerCase() === want.toLowerCase();
  });
}

/** Whether a pool satisfies a provider's `pool_selector`. Empty means every pool. */
export function poolMatchesSelector(
  pool: Pick<Pool, 'name' | 'backend' | 'labels'>,
  selector: Record<string, string>,
): boolean {
  return satisfies(selector, (key) => poolSelectorValue(pool, key));
}

/** Whether a provider satisfies a pool's `provider_selector`. Empty means any provider. */
export function providerMatchesSelector(
  provider: Pick<Provider, 'name' | 'kind' | 'machine_labels'>,
  selector: Record<string, string>,
): boolean {
  return satisfies(selector, (key) => providerSelectorValue(provider, key));
}

import type { ProviderCheck } from '$lib/api/types';

/**
 * What a private provider's page says about its connection, and when.
 *
 * The sentences about a dropped private connection live here rather than in
 * the component so they can be tested as copy, and so the provider page and
 * anything else that names the same failure uses the same facts: the gateway
 * reconnection is automatic and takes no restart from anybody, and the things
 * to check are on the provider's machine, not on this controller.
 */

/** Whether this provider is reached through a gateway beside it at all. */
export function isPrivate(provider: { connection?: string | null }): boolean {
  return provider.connection === 'tailcat';
}

/** Whether the last check, when there was one, got no answer through the tunnel. */
export function lostConnection(check?: ProviderCheck | null): boolean {
  return check != null && check.reachable === false;
}

/**
 * What the connection is, told once and never as an error: a healthy provider
 * shows this sentence alone.
 */
export const connectionIntro =
  'This provider is reached through a zoomies gateway running beside the cluster, over ' +
  'Tailcat. There is no address from this controller to the cluster, so a dropped ' +
  'connection is answered on that machine: reconnection is automatic here, and what to ' +
  'check lives there.';

/**
 * The checklist for a connection the last check could not reach, in the order
 * to look. Both ends keep dialling on their own, so nothing here asks anybody
 * to reconnect or restart anything: the first three are the reasons an
 * automatic recovery can be stuck, and the fourth is the one thing that
 * genuinely needs doing again.
 */
export function reconnectSteps(): string[] {
  return [
    "On the machine beside the provider, `systemctl status 'zoomies-proxmox-*'` shows whether its " +
      "gateway service is running, and `journalctl -u 'zoomies-proxmox-*'` what happened to it.",
    'That machine needs outbound HTTPS to the relay network; a firewall, proxy or DNS change is the usual cause.',
    'The API the gateway forwards to must answer there too, usually on 127.0.0.1:8006 when it runs on the node itself.',
    'If that machine was reinstalled, or its gateway state was deleted, run a fresh setup command from the ' +
      'wizard on it; the stored credential and the template answers are reused.',
  ];
}

/**
 * What to suggest for a new hypervisor provider's limits, from what the nodes
 * can hold and how big one machine is.
 *
 * Pure, and imported by a unit test, like the host capacity recommendation it
 * mirrors (`hosts/recommend.ts`). The figures are a starting point with the
 * reasoning shown, not a promise: memory is what fills a hypervisor first, so
 * it is the binding constraint, and processors are allowed to be shared.
 */
import type { ProviderChoice } from '../api/types';

/** One machine's size, as the template or the operator says it is. */
export interface MachineSize {
  cpus: number;
  memoryMb: number;
  /** Where the figures came from, for the sentence under the field. */
  source: 'typed' | 'template' | 'default';
}

/** Used only when nothing has said how big a machine is. */
export const DEFAULT_MACHINE: MachineSize = { cpus: 2, memoryMb: 4096, source: 'default' };

/** Never more than this many suggested: a first ceiling is one to grow into. */
export const SUGGESTED_CEILING = 8;

/** Processors are shared between machines, so a node offers this many per core. */
const CPU_SHARING = 2;

/** The least a node keeps back for the hypervisor, whatever a fifth of it comes to. */
const NODE_RESERVE_FLOOR_MB = 2048;

/**
 * The disk each runner is given to work in, above the host's reserve. Mirrors
 * `scheduler.RunnerDiskMB`; a change to one is a change to both, or the form
 * and the provider's check would disagree about what a machine needs. A test
 * in `internal/docs` fails while they differ.
 */
export const RUNNER_DISK_MB = 10 * 1024;

/**
 * The least disk a machine keeps back for itself before any runner is placed.
 * Mirrors `store.MinHostReserveDiskMB`; a change to one is a change to both.
 */
export const HOST_RESERVE_DISK_FLOOR_MB = 2048;

/**
 * The disk a machine needs for this many slots: the reserve plus a working
 * room each. A machine always runs at least one runner, so a slot count of
 * zero (nothing typed yet) is read as one.
 */
export function machineDiskNeededMb(slots: number): number {
  return HOST_RESERVE_DISK_FLOOR_MB + Math.max(slots, 1) * RUNNER_DISK_MB;
}

/**
 * A disk figure the way the provider's check writes one (Go's `formatMB`):
 * whole gigabytes where it divides evenly, one decimal where it does not. The
 * decimal is floored rather than rounded, so a disk a megabyte short of what
 * the slots need never prints as that figure and contradicts the sentence it
 * sits in.
 */
function diskSize(mb: number): string {
  if (mb < 1024) return `${mb} MB`;
  if (mb % 1024 === 0) return `${mb / 1024} GB`;
  return `${(Math.floor((mb / 1024) * 10) / 10).toFixed(1)} GB`;
}

/**
 * What sits under the Disk field: the arithmetic the provider's check applies,
 * so an operator sees what the slots imply before saving rather than from a
 * warning afterwards. A disk of zero means the template decides, and the
 * template's size is only known once the check has read it.
 */
export function machineDiskHint(slots: number, diskMb: number): string {
  const n = Math.max(slots, 1);
  const needed = diskSize(machineDiskNeededMb(n));
  const noun = n === 1 ? 'slot needs' : 'slots need';
  if (diskMb <= 0) {
    return `Each runner is given ${diskSize(RUNNER_DISK_MB)} of working room above a ${diskSize(HOST_RESERVE_DISK_FLOOR_MB)} reserve, so ${n} ${noun} at least ${needed}; the template's disk counts once the check has read it.`;
  }
  if (diskMb < machineDiskNeededMb(n)) {
    return `${diskSize(diskMb)} is under the ${needed} ${n} ${noun}.`;
  }
  return `${n} ${noun} at least ${needed}.`;
}

/**
 * Memory kept back for the hypervisor itself: a fifth of the node, and never
 * less than two gigabytes. A node filled to the brim swaps, and every machine
 * on it slows down with it.
 */
export function nodeReserveMb(memoryMb: number): number {
  return Math.min(
    Math.max(NODE_RESERVE_FLOOR_MB, Math.round(memoryMb * 0.2)),
    Math.max(memoryMb - 1024, 0),
  );
}

/** How many machines of this size one node holds, after its reserve. */
export function machinesPerNode(
  node: { cpus: number; memoryMb: number },
  size: MachineSize,
): number {
  if (size.cpus <= 0 || size.memoryMb <= 0) return 0;
  const byMemory =
    node.memoryMb > 0
      ? Math.floor((node.memoryMb - nodeReserveMb(node.memoryMb)) / size.memoryMb)
      : Infinity;
  const byCpu = node.cpus > 0 ? Math.floor((node.cpus * CPU_SHARING) / size.cpus) : Infinity;
  const fits = Math.min(byMemory, byCpu);
  return Number.isFinite(fits) ? Math.max(fits, 0) : 0;
}

/** The size one machine will be: what was typed, else the template's, else the default. */
export function machineSize(
  typed: { cpus?: string; memoryMb?: string },
  template?: Pick<ProviderChoice, 'cpus' | 'memory_mb'> | null,
): MachineSize {
  const cpus = Number(typed.cpus);
  const memoryMb = Number(typed.memoryMb);
  if (cpus > 0 && memoryMb > 0) return { cpus, memoryMb, source: 'typed' };
  if ((template?.cpus ?? 0) > 0 && (template?.memory_mb ?? 0) > 0) {
    return {
      cpus: cpus > 0 ? cpus : (template?.cpus ?? 0),
      memoryMb: memoryMb > 0 ? memoryMb : (template?.memory_mb ?? 0),
      source: 'template',
    };
  }
  return DEFAULT_MACHINE;
}

export interface LimitsRecommendation {
  /** The most machines to allow at once. At least one. */
  max: number;
  /** How many to keep warm. At least one, and never more than `max`. */
  min: number;
  /** How many machines the nodes could hold, before the cap. Zero when not known. */
  fits: number;
  /** One sentence on where the figures came from. */
  reason: string;
}

/**
 * The suggestion: as many machines as the chosen nodes hold, up to a ceiling
 * worth growing into, with one kept warm so the first job after a quiet spell
 * does not wait for a clone.
 *
 * A node the cluster could not size is not guessed at: the suggestion falls
 * back to two and one, and says so.
 */
export function recommendLimits(
  nodes: readonly Pick<ProviderChoice, 'value' | 'cpus' | 'memory_mb'>[],
  size: MachineSize,
): LimitsRecommendation {
  const sized = nodes.filter((n) => (n.memory_mb ?? 0) > 0 || (n.cpus ?? 0) > 0);
  const machine = `${size.cpus} CPUs and ${gigabytes(size.memoryMb)} each`;
  if (sized.length === 0) {
    return {
      max: 2,
      min: 1,
      fits: 0,
      reason:
        'The cluster did not say how big its nodes are, so this starts small: two machines, one kept warm. Raise the maximum once you know what a node holds.',
    };
  }
  const fits = sized.reduce(
    (total, n) => total + machinesPerNode({ cpus: n.cpus ?? 0, memoryMb: n.memory_mb ?? 0 }, size),
    0,
  );
  const one = sized.length === 1;
  const where = one ? `node ${sized[0]?.value}` : `${sized.length} nodes`;
  const basis =
    size.source === 'default'
      ? ` (a guess, because no template size was given: ${machine})`
      : ` at ${machine}`;
  // The reserve as the arithmetic applies it. An operator checks one against
  // the other, and "a fifth of its memory" was wrong for every node under 10 GB,
  // where the two gigabytes are what is kept.
  const kept = `after keeping memory for Proxmox (at least ${gigabytes(NODE_RESERVE_FLOOR_MB)}, or a fifth of ${one ? 'its' : "each node's"} memory, whichever is larger)`;
  if (fits < 1) {
    return {
      max: 1,
      min: 1,
      fits,
      reason: `${capitalise(where)} cannot hold even one machine${basis} ${kept}. Give the machine less, or choose a larger node.`,
    };
  }
  const max = Math.min(fits, SUGGESTED_CEILING);
  const min = 1;
  const capped = fits > max ? `, held to ${max} as a first ceiling` : '';
  // The figure is from what a node has, not from what is free on it: the
  // cluster is not asked what its other guests use, so a shared node holds fewer.
  const counted = `That counts ${one ? "the node's" : "each node's"} total memory, not what other guests are using, so a node shared with other guests holds fewer.`;
  return {
    max,
    min,
    fits,
    reason: `${capitalise(where)} can hold ${fits} machine${fits === 1 ? '' : 's'}${basis}, ${kept}${capped}. ${counted} One stays warm so the first job after a quiet spell does not wait for a clone.`,
  };
}

function gigabytes(mb: number): string {
  const gb = mb / 1024;
  return `${Number.isInteger(gb) ? gb : gb.toFixed(1)} GB`;
}

function capitalise(text: string): string {
  return text.charAt(0).toUpperCase() + text.slice(1);
}

import type { PoolRenting, ProviderRenting } from '$lib/api/types';

/*
  What the renting notice says and offers, as data, so node:test can reach it.

  The server owns every sentence about why nothing is rented (`summary` and
  `fix`), so they pass through untouched: a second wording here would drift from
  the problems list, the pool text and the MCP tools that say the same thing.
  This file decides only whether a notice is due, which one click fits, and the
  settings that click writes.
*/

type RentingSetting = 'provider.enabled' | 'provider.max_machines';

export interface RentingNoticeModel {
  id: 'off' | 'no_ceiling';
  title: string;
  /** The server's summary, unchanged. */
  body: string;
  /** The server's fix, unchanged. */
  fix: string;
  /** The verdicts renting itself is holding back, not the ones a host or a limit explains. */
  pools: PoolRenting[];
  /** What an administrator may click; null for everyone else, who get `hint`. */
  action: { label: string; ceiling: number; keys: RentingSetting[] } | null;
  hint: string;
}

/** The pool states a switch is responsible for: `off` and the fleet ceiling. */
const SWITCH_STATES: readonly PoolRenting['state'][] = ['off', 'ceiling'];

export function rentingNotice(
  renting: ProviderRenting | null,
  admin: boolean,
): RentingNoticeModel | null {
  if (!renting || (renting.state !== 'off' && renting.state !== 'no_ceiling')) return null;

  // The server always sends at least one, but the schema marks it optional, and
  // a click that wrote a ceiling of zero would leave the notice standing.
  const ceiling = clampCeiling(renting.suggested_max_machines ?? 1, 1);
  const pools = renting.pools.filter((p) => SWITCH_STATES.includes(p.state));
  const off = renting.state === 'off';

  return {
    id: renting.state,
    title: off ? 'Renting is switched off' : 'Renting is on, but the fleet may rent no machines',
    body: renting.summary,
    fix: renting.fix ?? '',
    pools,
    action: admin
      ? off
        ? {
            label: 'Turn on renting',
            ceiling,
            keys: ['provider.enabled', 'provider.max_machines'],
          }
        : {
            label: `Allow ${ceiling} ${ceiling === 1 ? 'machine' : 'machines'}`,
            ceiling,
            keys: ['provider.max_machines'],
          }
      : null,
    hint: `An administrator can change this under Settings, ${
      off ? 'Rent machines' : 'Machines the fleet may rent'
    }.`,
  };
}

/** The settings patch the notice's button sends. */
export function settingsFor(
  notice: RentingNoticeModel,
  ceiling: number,
): Record<string, boolean | number> {
  const patch: Record<string, boolean | number> = {};
  for (const key of notice.action?.keys ?? []) {
    patch[key] = key === 'provider.enabled' ? true : ceiling;
  }
  return patch;
}

/**
 * A ceiling is a whole number from one to MAX_CEILING; anything else falls
 * back. The upper bound is not a policy: it keeps a runaway figure (a sum that
 * overflowed, a typo with too many zeros) from being offered as the most an
 * operator is willing to pay for, and no real fleet rents that many machines.
 */
const MAX_CEILING = 100_000;

export function clampCeiling(value: number, fallback: number): number {
  if (!Number.isFinite(value)) return fallback;
  const whole = Math.floor(value);
  return whole >= 1 && whole <= MAX_CEILING ? whole : fallback;
}

/** One pool's verdict, or null when there is none to show. */
export function poolRenting(renting: ProviderRenting | null, poolId: string): PoolRenting | null {
  return renting?.pools.find((p) => p.pool_id === poolId) ?? null;
}

/**
 * What a refused click shows. The settings route answers a pinned key with a
 * general message and the reason under the key; the reason is the half that
 * says where the setting lives and what to change, so it wins when there is one.
 */
export function refusalText(
  message: string,
  errors: readonly { message: string }[] | undefined,
): string {
  const reasons = (errors ?? []).map((e) => e.message).filter((m) => m !== '');
  return reasons.length > 0 ? reasons.join(' ') : message;
}

/**
 * Where a provider's test machine has got to, worked out from its row alone.
 *
 * Pure, and in a `.ts` for the reason `machines.ts` is. A test is a real
 * machine going through every step a rented one does, so the steps are the
 * timeline's own phases: an operator who sees the clone pass and the agent
 * never enrol knows the fault is inside the guest, not at the hypervisor.
 */
import type { Machine } from '../api/types';

export type StepStatus = 'done' | 'active' | 'waiting' | 'failed';

export interface TestStep {
  id: string;
  label: string;
  status: StepStatus;
}

export type TestOutcome = 'running' | 'passed' | 'failed';

export interface TestProgress {
  outcome: TestOutcome;
  steps: TestStep[];
  /** One sentence for the headline. */
  summary: string;
  /** What the machine itself said went wrong, when it did. */
  problem: string;
}

/** The phases a machine must reach, in order, and what each one proves. */
const STEPS: readonly { id: string; phase: string; label: string }[] = [
  { id: 'created', phase: 'created', label: 'Cloned from the template' },
  { id: 'started', phase: 'starting', label: 'Powered on' },
  { id: 'agent', phase: 'bootstrapped', label: 'Agent installed' },
  { id: 'enrolled', phase: 'enrolled', label: 'Enrolled as a host' },
  { id: 'ready', phase: 'ready', label: 'Reported ready' },
];

/**
 * What a step says about itself to somebody who is told rather than shown. The
 * icon and the colour that say it to everyone else are drawn, and a screen
 * reader gets five identical list items without these.
 */
const STEP_WORDS: Record<StepStatus, string> = {
  done: 'done',
  active: 'in progress',
  waiting: 'not reached',
  failed: 'failed',
};

export function stepStatusText(status: StepStatus): string {
  return STEP_WORDS[status];
}

/** Whether this is the machine a provider's test built. */
export function isTestMachine(machine: Machine): boolean {
  return machine.test === true;
}

/**
 * Whether the controller would turn down another test because of this machine.
 *
 * It starts one at a time and counts a test as still there until its machine has
 * been deleted, apart from one a failure or a quarantine left in place to be read
 * (StartTestMachine in internal/controller/testmachine.go; keep the two in step).
 * So a test that has passed is in the way while it is being released, and a
 * button that offered the next one then would be offering a certain 409.
 */
export function blocksAnotherTest(machine: Machine): boolean {
  return (
    machine.state !== 'deleted' && machine.state !== 'failed' && machine.state !== 'quarantined'
  );
}

/** The newest test machine in a list, or null when there is none. */
export function latestTest(machines: readonly Machine[]): Machine | null {
  let best: Machine | null = null;
  for (const machine of machines) {
    if (!isTestMachine(machine)) continue;
    if (!best || Date.parse(machine.created_at) > Date.parse(best.created_at)) best = machine;
  }
  return best;
}

export function testProgress(machine: Machine): TestProgress {
  const reached = new Set((machine.timeline ?? []).map((entry) => entry.phase));
  const ready = reached.has('ready');
  const broken = machine.state === 'failed' || machine.state === 'quarantined';
  const gone = machine.state === 'deleted' && !ready;
  const failed = !ready && (broken || gone);
  const problem = failed
    ? machine.bootstrap_error ||
      machine.provider_error ||
      machine.ownership_error ||
      machine.message ||
      ''
    : '';

  // A skipped phase (a clone that leaves the guest running never "starts")
  // is passed over by the one after it, so a step is done when it or any later
  // step was reached.
  const lastReached = STEPS.reduce(
    (last, step, index) => (reached.has(step.phase) ? index : last),
    -1,
  );
  let activeSeen = false;
  const steps: TestStep[] = STEPS.map((step, index) => {
    if (index <= lastReached) return { id: step.id, label: step.label, status: 'done' };
    if (failed && !activeSeen) {
      activeSeen = true;
      return { id: step.id, label: step.label, status: 'failed' };
    }
    if (!failed && !activeSeen) {
      activeSeen = true;
      return { id: step.id, label: step.label, status: 'active' };
    }
    return { id: step.id, label: step.label, status: 'waiting' };
  });

  if (ready) {
    return {
      outcome: 'passed',
      steps,
      summary:
        machine.state === 'deleted'
          ? 'The test passed and its machine has been released.'
          : 'The test passed. The machine is being released.',
      problem: '',
    };
  }
  if (failed) {
    return {
      outcome: 'failed',
      steps,
      summary:
        machine.state === 'deleted'
          ? 'The test machine was removed before it was ready.'
          : 'The test machine did not get to ready. It is kept so its errors can be read; release it when you are done.',
      problem,
    };
  }
  return {
    outcome: 'running',
    steps,
    summary: 'Building a real machine, the same way a job would ask for one.',
    problem: '',
  };
}

/**
 * How a person's reason for a decision is measured and prompted for.
 *
 * Shared by the two forms that record one -- a Kennel waiver and a host check
 * accepted as deliberate -- because the controller counts them the same way and
 * a form that argued with it about the tenth character would do so twice.
 */

/** The controller's own bounds on a reason, in characters. A test holds them to what it says. */
export const REASON_MIN = 10;
export const REASON_MAX = 500;

/**
 * How long a reason is, counted the way the controller counts it: characters,
 * after the ends are trimmed. `.length` counts UTF-16 units, so an emoji would
 * be two, and a form that says "9 of 10" while the controller says "10" is a
 * form that argues with the person typing.
 */
export function reasonLength(reason: string): number {
  return [...reason.trim()].length;
}

/**
 * What the reason field says about itself: the rule while it is unmet, the count
 * after. `what` finishes "say why this is ...", so each form asks its own question.
 */
export function reasonHint(reason: string, what = 'acceptable here'): string {
  const n = reasonLength(reason);
  if (n < REASON_MIN) {
    return `At least ${REASON_MIN} characters: say why this is ${what}, for whoever reads the audit log in a year.`;
  }
  return `${n} of ${REASON_MAX} characters.`;
}

import type { Schemas } from '../api/types';
import { isActive, stateLabel } from './history';

/*
  What the attempt page says about one repair that is not already a status or a
  case: who asked, which kind of provider paid, how long it took, and the moments
  the row actually recorded. It reads the row and nothing else, so a moment the
  controller did not write down is not on the timeline, rather than being
  invented to make it look fuller.
*/

type Repair = Schemas['EliRepair'];

/** Who began the repair, in the words the header shows. */
export function requestedBy(repair: Pick<Repair, 'trigger' | 'github_login'>): string {
  if (repair.trigger === 'automatic') return 'Started automatically';
  return repair.github_login ? `Requested by @${repair.github_login}` : 'Requested by someone';
}

/**
 * Whose provider the model call was made through. An automatic repair uses the
 * installation's provider, which an administrator chose, and a requested one
 * uses the provider of the person who asked.
 */
export function providerWords(repair: Pick<Repair, 'trigger'>): string {
  return repair.trigger === 'automatic' ? 'Installation provider' : 'Personal provider';
}

/**
 * How long a finished repair took. A repair still going has taken nothing yet,
 * and a clock that disagrees with the one that wrote the row is not a negative
 * time: it is nothing worth saying, so it reads as no time at all.
 */
export function tookMs(
  repair: Pick<Repair, 'state' | 'created_at' | 'updated_at'>,
): number | undefined {
  if (isActive(repair.state)) return undefined;
  const took = Date.parse(repair.updated_at) - Date.parse(repair.created_at);
  return Number.isNaN(took) ? undefined : Math.max(0, took);
}

export interface TimelineEntry {
  /** When it happened, if the row recorded when. A pushed commit has no time of its own. */
  at?: string;
  text: string;
}

/**
 * The moments of a repair, from the row alone: it was queued, a commit was
 * pushed, and (once it has stopped) how it ended. The ending is named by its
 * state; the controller's sentence about it is the outcome card's to say, and
 * saying it twice on one screen would only make the second copy harder to trust.
 */
export function timeline(
  repair: Pick<Repair, 'state' | 'commit_sha' | 'created_at' | 'updated_at'>,
): TimelineEntry[] {
  const out: TimelineEntry[] = [{ at: repair.created_at, text: 'Queued' }];
  if (repair.commit_sha) out.push({ text: `Pushed commit ${repair.commit_sha.slice(0, 7)}` });
  if (!isActive(repair.state)) out.push({ at: repair.updated_at, text: stateLabel(repair.state) });
  return out;
}

/**
 * The facts of a repair as plain text, for pasting into a bug report. The
 * figures are exact where the page rounds them, because an investigation wants
 * the number that was recorded. It holds ids, states and sizes and nothing that
 * Eli read or wrote (no job names, no log lines, no pull request title), and it
 * says nothing about a fact the row does not have.
 */
export function investigationText(repair: Repair): string {
  const d = repair.details;
  const out: string[] = [`Eli repair ${repair.id}`, `Repository: ${repair.repo}`];
  if (repair.pull_number > 0) out.push(`Pull request: #${repair.pull_number}`);
  if (repair.run_id > 0) out.push(`Run: ${repair.run_id}`);
  out.push(`Failing head: ${repair.head_sha}`);
  out.push(`Commit pushed: ${repair.commit_sha || 'none'}`);
  out.push(`State: ${repair.state}`);
  if (repair.message) out.push(`Message: ${repair.message}`);
  if (d?.stage) out.push(`Stage reached: ${d.stage}`);
  if (d?.failure_code) out.push(`Failure code: ${d.failure_code}`);
  if (d?.model) out.push(`Model: ${d.model}`);
  if (d?.source_bytes) out.push(`Source supplied: ${d.source_bytes} bytes`);
  if (d?.steps?.length) {
    out.push(`Model calls: ${d.steps.length}`);
    d.steps.forEach((step, index) => {
      const usage = step.usage_reported
        ? `${step.input_tokens} input tokens, ${step.output_tokens} output tokens`
        : 'usage not reported';
      out.push(
        `  ${index + 1}. ${usage}, request ${step.request_bytes} bytes, ${step.elapsed_ms} ms`,
      );
    });
  }
  out.push(`Started: ${repair.created_at}`, `Updated: ${repair.updated_at}`);
  return out.join('\n');
}

import type { Schemas } from '../api/types';
import { pluralise, relativeTime } from '../format';
import { stateLabel } from './history';

/*
  What the pages about automatic repairs say, so a test can hold it without a
  browser: how much of the allowance is used and when a place frees, what the
  automation did last, what the stop dialog promises, what a stop reports, and
  what the repair page tells a person about a repository that repairs itself.

  The numbers come from the controller and are not recomputed here. The allowance
  is the figure the daily limit is held against, so the words are about that, and
  a limit lowered below what is used reads as full and never as "7 of 5".
*/

type Repository = Schemas['EliAutomaticRepository'];
type Repair = Schemas['EliRepair'];
type StopResult = Schemas['EliAutomaticStopResult'];
export type StopChoice = Schemas['EliAutomaticStopRequest']['then'];

export interface Allowance {
  used: number;
  limit: number;
  /** No place is left. True too when the limit has been lowered below what is used. */
  full: boolean;
  /** How much of the bar to fill, never past full. */
  ratio: number;
  words: string;
}

export function allowanceOf(repo: Pick<Repository, 'used' | 'daily_limit'>): Allowance {
  const limit = Math.max(0, repo.daily_limit);
  const used = Math.max(0, repo.used);
  const full = used >= limit;
  const ratio = limit === 0 ? 1 : Math.min(1, used / limit);
  const words = full
    ? `All ${pluralise(limit, 'attempt')} used in the last 24 hours`
    : `${used} of ${pluralise(limit, 'attempt')} used in the last 24 hours`;
  return { used, limit, full, ratio, words };
}

const CLOCK = new Intl.DateTimeFormat(undefined, { hour: 'numeric', minute: '2-digit' });

/**
 * When automatic repairs resume, for a repository with no place left. Empty
 * otherwise. A place frees within a day of the attempt that holds it, so it is
 * said as a time of day, with "tomorrow" when midnight comes first, and how long
 * that is as well, because "in 40m" is the part somebody acts on.
 */
export function waitsUntil(
  repo: Pick<Repository, 'used' | 'daily_limit' | 'next_free_at'>,
  now: number = Date.now(),
): string {
  if (!allowanceOf(repo).full) return '';
  const free = repo.next_free_at ? new Date(repo.next_free_at) : null;
  if (!free || Number.isNaN(free.getTime())) {
    return 'Automatic repairs here wait until a place frees.';
  }
  const time = CLOCK.format(free);
  const today = new Date(now).toDateString() === free.toDateString();
  return `Automatic repairs here wait until ${today ? time : `tomorrow ${time}`} (${relativeTime(free.getTime(), now)}).`;
}

/** The newest automatic repair still in the history, as a row of the overview shows it. */
export function lastWords(repo: Pick<Repository, 'last'>, now: number = Date.now()): string {
  const last = repo.last;
  if (!last) return 'None yet';
  const on = last.pull_number > 0 ? ` on #${last.pull_number}` : '';
  return `${stateLabel(last.state)}${on}, ${relativeTime(last.updated_at, now)}`;
}

export function runningWords(running: number): string {
  return running > 0 ? `${running} running now` : '';
}

/** Who pays, or that nobody can: a deleted provider leaves a policy with none. */
export function paidByWords(
  repo: Pick<Repository, 'provider_id' | 'provider_name' | 'model'>,
): string {
  if (!repo.provider_name) {
    return repo.provider_id
      ? 'The installation provider cannot be found'
      : 'No installation provider is set';
  }
  return repo.model
    ? `Paid by ${repo.provider_name} (${repo.model})`
    : `Paid by ${repo.provider_name}`;
}

export interface StopCopy {
  title: string;
  intro: string;
  question: string;
  askFirst: { label: string; hint: string };
  off: { label: string; hint: string };
  /** What happens to a repair that is running, which is the first thing a person worries about. */
  inFlight: string;
  confirm: string;
}

function namesOf(repos: readonly string[]): string {
  if (repos.length > 3) return `${repos.slice(0, 3).join(', ')} and ${repos.length - 3} more`;
  if (repos.length === 3) return `${repos[0]}, ${repos[1]} and ${repos[2]}`;
  return repos.join(' and ');
}

/** The stop dialog, for one repository or for several. */
export function stopCopy(repos: readonly string[]): StopCopy {
  const one = repos.length === 1;
  return {
    title: one
      ? 'Stop automatic repairs'
      : `Stop automatic repairs on ${repos.length} repositories`,
    intro: one
      ? `Eli will stop repairing ${repos[0]} by itself.`
      : `Eli will stop repairing ${pluralise(repos.length, 'repository', 'repositories')} by itself: ${namesOf(repos)}.`,
    question: 'What should happen instead?',
    askFirst: {
      label: 'Ask me first',
      hint: 'When checks fail, Eli offers a repair under Needs you and waits for you.',
    },
    off: {
      label: 'Turn repairs off',
      hint: one
        ? 'Eli neither offers nor starts a repair here, and nobody can request one, until it is turned on again in setup.'
        : 'Eli neither offers nor starts a repair on these repositories, and nobody can request one, until each is turned on again in setup.',
    },
    inFlight:
      'A repair that has not pushed yet stops before it changes the branch, unless it is already publishing. One that has pushed carries on watching its checks.',
    confirm: 'Stop automatic repairs',
  };
}

export interface StopOutcome {
  tone: 'success' | 'error';
  title: string;
  message: string;
}

/**
 * What a stop reports. A repository that was already stopped is not an error:
 * somebody else got there first, which is the result that was wanted.
 */
export function stoppedWords(results: readonly StopResult[], then: StopChoice): StopOutcome {
  const failed = results.filter((r) => r.error);
  const changed = results.filter((r) => r.changed);
  if (failed.length > 0) {
    return {
      tone: 'error',
      title: changed.length > 0 ? 'Stopped some, not all' : 'Could not stop automatic repairs',
      message: failed.map((r) => `${r.repo}: ${r.error}`).join(' '),
    };
  }
  if (changed.length === 0) {
    return {
      tone: 'success',
      title: 'Already stopped',
      message: 'Automatic repairs were already off there, so nothing changed.',
    };
  }
  const where = changed.length === 1 ? changed[0]!.repo : `${changed.length} repositories`;
  const now =
    then === 'off'
      ? 'Repairs are off there now.'
      : changed.length === 1
        ? 'It asks first now.'
        : 'They ask first now.';
  return { tone: 'success', title: `Stopped automatic repairs on ${where}`, message: now };
}

/**
 * The attempt Eli made on this commit by itself, newest first. The history's
 * repository filter is a substring, so the name is compared whole, without
 * regard to case as GitHub does.
 */
export function findAutomaticAttempt(
  repairs: readonly Repair[],
  target: { repo: string; pull: number; head: string },
): Repair | undefined {
  const repo = target.repo.toLowerCase();
  return repairs
    .filter(
      (r) =>
        r.trigger === 'automatic' &&
        r.repo.toLowerCase() === repo &&
        r.pull_number === target.pull &&
        r.head_sha === target.head,
    )
    .sort((a, b) => Date.parse(b.created_at) - Date.parse(a.created_at))[0];
}

export interface AutomaticNote {
  kind: 'tried' | 'none' | 'neutral';
  title: string;
  body: string;
  /** The attempt to link to, for `tried`. */
  attemptId?: string;
}

/**
 * What the repair page says about a repository that repairs itself, which
 * depends on what the person looking is allowed to know. Automatic repairs have
 * no owner, so only an administrator can say whether Eli tried this failure; for
 * anyone else a claim either way would be a guess.
 */
export function automaticNote(input: {
  mode: string | undefined;
  admin: boolean;
  attempt: Repair | undefined;
  /** The repository's row of the overview, when it could be read. */
  repository: Repository | undefined;
  now?: number;
}): AutomaticNote | null {
  if (input.mode !== 'automatic') return null;
  if (!input.admin) {
    return {
      kind: 'neutral',
      title: 'This repository repairs itself',
      body: 'Eli repairs failed checks here automatically. An administrator can see what it has done.',
    };
  }
  if (input.attempt) {
    return {
      kind: 'tried',
      title: 'Eli already tried this on its own',
      body: `${stateLabel(input.attempt.state)}. Eli does not try the same commit twice by itself, so starting another attempt here is the retry.`,
      attemptId: input.attempt.id,
    };
  }
  const title = 'Nothing has started on its own for this failure';
  const repo = input.repository;
  if (repo?.problem) {
    return { kind: 'none', title, body: `${repo.problem} That is why nothing has started.` };
  }
  if (repo && allowanceOf(repo).full) {
    return {
      kind: 'none',
      title,
      body: `This repository’s allowance is used up, and automatic repairs share it with requests, so none has started. ${waitsUntil(repo, input.now)} The same allowance holds back a repair you start yourself.`,
    };
  }
  return {
    kind: 'none',
    title,
    body: 'Eli starts from GitHub’s report of a failed job, so a failure from before Automatic was switched on, or one whose report did not arrive, is not picked up on its own. You can start one yourself below.',
  };
}

import type { Job, Schemas } from '../api/types';
import { faultDomain, faultLabel } from '../faults';
import { commitUrl, githubJobIdFromUrl, linksFromJobUrl, pullUrl, safeHttpUrl } from './links';

/*
  The case: what a repair is about, as the page draws it. There are two ways to
  know it. While a person is deciding, it is read from what Zoomies holds about
  the failing run and from what readiness found about the pull request. After a
  repair has started, it is read back from the snapshot the repair kept, because
  Zoomies prunes its job records and a pull request's title changes. Both give
  the same view, so the card that shows it does not care which it was handed.

  Everything here was written by someone who can open a pull request or edit a
  workflow. Text is passed through as text, for the page to draw as text, and an
  address is kept only if it is a plain web link.
*/

type Readiness = Schemas['EliReadiness'];
type Repair = Schemas['EliRepair'];

/** One step of a failed job, as GitHub reported it. */
export interface CaseStep {
  number: number;
  name: string;
  /** How it ended: success, failure, skipped, cancelled, or empty while it has not. */
  conclusion: string;
  durationMs?: number;
}

export interface CaseJob {
  /** Stable for the list: the Zoomies job id, or a stand-in when there is none. */
  key: string;
  name: string;
  step?: string;
  /** The failing step's number, which GitHub numbers from 1. */
  stepNumber?: number;
  url?: string;
  durationMs?: number;
  /** Whose the failure is: the workflow's, this fleet's, or not known. */
  domain: 'workflow' | 'fleet' | '';
  faultLabel?: string;
  fix?: string;
  /** The job the person opened to get here. */
  opened: boolean;
  githubJobId?: number;
  /** Every step the job reported, when the job is still on record. A snapshot has none. */
  steps?: CaseStep[];
}

export interface CaseView {
  repo: string;
  repoUrl?: string;
  title: string;
  /** Whether the pull request has been looked up, which is what decides if its title is known. */
  hasPull: boolean;
  pullNumber?: number;
  pullUrl?: string;
  author?: string;
  branch?: string;
  base?: string;
  sha?: string;
  commitUrl?: string;
  runLabel?: string;
  runUrl?: string;
  failedAt?: string;
  ran?: { pool?: string; runner?: string; poolId?: string; runnerId?: string };
  jobs: CaseJob[];
}

/** "CI #482 failed on fix/retry-502": what ran, when the pull request's own title is not known. */
function runTitle(workflow: string | undefined, runNumber: number | undefined, branch?: string) {
  if (!workflow && !runNumber) return '';
  const run = [workflow || 'Run', runNumber ? `#${runNumber}` : ''].filter(Boolean).join(' ');
  return branch ? `${run} failed on ${branch}` : `${run} failed`;
}

function runLabel(workflow: string | undefined, runNumber: number | undefined): string | undefined {
  if (workflow && runNumber) return `${workflow} #${runNumber}`;
  if (workflow) return workflow;
  return runNumber ? `Run #${runNumber}` : undefined;
}

/** The last words: what any repair has, for the case that knows nothing else. */
function plainTitle(repo: string, pullNumber: number | undefined): string {
  return pullNumber ? `Pull request #${pullNumber} in ${repo}` : `A repair in ${repo}`;
}

function liveSteps(job: Job): CaseStep[] {
  return (job.steps ?? []).map((step, index) => {
    const out: CaseStep = {
      number: step.number ?? index + 1,
      name: step.name ?? '',
      conclusion: step.conclusion ?? '',
    };
    const took =
      step.started_at && step.completed_at
        ? Date.parse(step.completed_at) - Date.parse(step.started_at)
        : NaN;
    if (took > 0) out.durationMs = took;
    return out;
  });
}

function liveJob(job: Job, index: number, openedJobId: string | undefined): CaseJob {
  const domain = faultDomain(job);
  const out: CaseJob = {
    key: job.id || (job.github_job_id ? `gh-${job.github_job_id}` : `job-${index}`),
    name: job.job_name ?? '',
    domain,
    opened: Boolean(openedJobId) && job.id === openedJobId,
  };
  if (job.failed_step?.name) {
    out.step = job.failed_step.name;
    if (job.failed_step.number) out.stepNumber = job.failed_step.number;
  }
  const url = safeHttpUrl(job.html_url);
  if (url) out.url = url;
  if (job.duration_ms) out.durationMs = job.duration_ms;
  const label = domain === 'fleet' ? faultLabel(job.fault_kind) : '';
  if (label) out.faultLabel = label;
  if (job.fault_fix) out.fix = job.fault_fix;
  if (job.github_job_id) out.githubJobId = job.github_job_id;
  if (job.steps?.length) out.steps = liveSteps(job);
  return out;
}

/** The latest of the jobs' completion times, which is when the run's failure was settled. */
function lastCompleted(jobs: readonly Job[]): string | undefined {
  let best: string | undefined;
  let bestAt = -Infinity;
  for (const job of jobs) {
    const at = job.completed_at ? Date.parse(job.completed_at) : NaN;
    if (job.completed_at && at > bestAt) {
      best = job.completed_at;
      bestAt = at;
    }
  }
  return best;
}

const RUN_PAGE = /^\/([^/]+)\/([^/]+)\/actions\/runs\/\d+\/?$/;
const PULL_PAGE = /^\/([^/]+)\/([^/]+)\/pull\/\d+\/?$/;

/** The repository's address, read off a run's or a pull request's when no job gave it. */
function repoFromPage(page: string | undefined, pattern: RegExp): string | undefined {
  if (!page) return undefined;
  const url = new URL(page);
  const match = pattern.exec(url.pathname);
  return match ? `${url.origin}/${match[1]}/${match[2]}` : undefined;
}

export function caseFromLive(input: {
  repo: string;
  jobs: readonly Job[];
  readiness: Readiness | null;
  openedJobId?: string;
  /** GitHub's id for the run the address names, which is all there is to say of it without jobs. */
  run?: number;
}): CaseView {
  const { repo, jobs, readiness, openedJobId, run } = input;
  const first = jobs[0];
  const links = linksFromJobUrl(first?.html_url);
  const pull = readiness?.pull;
  // A job's own address says which host the repository is on. With no job on
  // record, the pull request's does.
  const repoUrl = links.repo ?? repoFromPage(safeHttpUrl(pull?.url), PULL_PAGE);
  const pullNumber =
    pull?.number || (readiness && readiness.pull_number > 0 ? readiness.pull_number : undefined);
  const sha = readiness?.head_sha || first?.head_sha || undefined;
  const branch = pull?.branch || first?.head_branch || undefined;
  const ranOn = jobs.find((j) => j.pool_name || j.runner_name || j.pool_id || j.runner_id);

  const view: CaseView = {
    repo,
    title:
      pull?.title ||
      runTitle(first?.workflow, first?.run_number, branch) ||
      plainTitle(repo, pullNumber),
    hasPull: Boolean(pull),
    jobs: jobs.map((job, index) => liveJob(job, index, openedJobId)),
  };
  if (repoUrl) view.repoUrl = repoUrl;
  if (pullNumber) view.pullNumber = pullNumber;
  const pullLink = safeHttpUrl(pull?.url) ?? pullUrl(repoUrl, pullNumber ?? 0);
  if (pullLink) view.pullUrl = pullLink;
  if (pull?.author) view.author = pull.author;
  if (branch) view.branch = branch;
  if (pull?.base) view.base = pull.base;
  if (sha) {
    view.sha = sha;
    const commit = commitUrl(repoUrl, sha);
    if (commit) view.commitUrl = commit;
  }
  const label = runLabel(first?.workflow, first?.run_number) ?? (run ? `Run ${run}` : undefined);
  if (label) view.runLabel = label;
  const runLink = links.run ?? (repoUrl && run ? `${repoUrl}/actions/runs/${run}` : undefined);
  if (runLink) view.runUrl = runLink;
  const failedAt = lastCompleted(jobs);
  if (failedAt) view.failedAt = failedAt;
  if (ranOn) {
    view.ran = {};
    if (ranOn.pool_name) view.ran.pool = ranOn.pool_name;
    if (ranOn.runner_name) view.ran.runner = ranOn.runner_name;
    if (ranOn.pool_id) view.ran.poolId = ranOn.pool_id;
    if (ranOn.runner_id) view.ran.runnerId = ranOn.runner_id;
  }
  return view;
}

export function caseFromSnapshot(repair: Repair): CaseView {
  const kept = repair.details?.case;
  const jobs = kept?.jobs ?? [];
  const runLink = safeHttpUrl(kept?.run_url);
  const pullLink = safeHttpUrl(kept?.pull_url);
  const repoUrl =
    linksFromJobUrl(jobs[0]?.url).repo ??
    repoFromPage(runLink, RUN_PAGE) ??
    repoFromPage(pullLink, PULL_PAGE);
  const pullNumber = repair.pull_number > 0 ? repair.pull_number : undefined;

  const view: CaseView = {
    repo: repair.repo,
    title:
      kept?.pull_title ||
      runTitle(kept?.workflow, kept?.run_number, kept?.branch) ||
      plainTitle(repair.repo, pullNumber),
    hasPull: Boolean(kept?.pull_title || kept?.pull_url),
    jobs: jobs.map((job, index): CaseJob => {
      const out: CaseJob = { key: `job-${index}`, name: job.name, domain: '', opened: false };
      if (job.step) out.step = job.step;
      const url = safeHttpUrl(job.url);
      if (url) out.url = url;
      if (job.duration_ms) out.durationMs = job.duration_ms;
      const githubJobId = githubJobIdFromUrl(job.url);
      if (githubJobId) out.githubJobId = githubJobId;
      return out;
    }),
  };
  if (repoUrl) view.repoUrl = repoUrl;
  if (pullNumber) view.pullNumber = pullNumber;
  const pullAt = pullLink ?? pullUrl(repoUrl, pullNumber ?? 0);
  if (pullAt) view.pullUrl = pullAt;
  if (kept?.author) view.author = kept.author;
  if (kept?.branch) view.branch = kept.branch;
  if (repair.head_sha) {
    view.sha = repair.head_sha;
    const commit = commitUrl(repoUrl, repair.head_sha);
    if (commit) view.commitUrl = commit;
  }
  const label = runLabel(kept?.workflow, kept?.run_number);
  if (label) view.runLabel = label;
  if (runLink) view.runUrl = runLink;
  return view;
}

import type { Schemas } from '../api/types';
import { safeHttpUrl } from './links';

/*
  The nine things readiness looks at, as rows a person can read. The controller
  says what each one found, in its own words; this file gives each a name and,
  when it is blocked, the one way forward that helps. The names are the UI's and
  are keyed by the check's code, so a code this build has not heard of is shown
  as itself instead of being hidden.
*/

export type CheckStatus = 'ok' | 'blocked' | 'unchecked';

/**
 * What a blocked check offers. `recheck` is for the ones that only need time or
 * a fix made elsewhere, `setup` opens the repair setup for the failure in hand,
 * `choose` picks a different pull request, and `link` goes somewhere else.
 */
export type CheckAction =
  | { kind: 'recheck' }
  | { kind: 'setup' }
  | { kind: 'choose' }
  | { kind: 'link'; href: string; label: string; external?: boolean };

export interface CheckRow {
  code: string;
  label: string;
  status: CheckStatus;
  message: string;
  /**
   * Why a blocked check is blocked: the code of the blocker the controller
   * recorded for it, which the check's own code cannot say. A controller older
   * than this build sends none, and the row reads by the check alone.
   */
  blocker?: string;
  action?: CheckAction;
}

/**
 * Blockers that say a check could not be made, not that it failed. The controller
 * folds them into the check it was making, so the check's own code would send the
 * person to choose another pull request or to open the installations because GitHub
 * did not answer. Whichever check it was, the way forward is to look again.
 */
const COULD_NOT_CHECK = ['github', 'budget_unavailable'];
export const couldNotCheck = (blocker: string | undefined): blocker is string =>
  blocker !== undefined && COULD_NOT_CHECK.includes(blocker);

type Readiness = Schemas['EliReadiness'];

/** A controller older than this build answers with blockers and no checks. */
type ReadinessLike = Omit<Readiness, 'checks'> & { checks?: Readiness['checks'] };

/** The checks in the order the controller makes them. */
const ORDER = [
  'identity',
  'provider',
  'installation',
  'access',
  'policy',
  'budget',
  'pull',
  'checks',
  'permissions',
];

const LABELS: Record<string, string> = {
  identity: 'GitHub account',
  provider: 'Model provider',
  installation: 'GitHub App installation',
  access: 'Write access',
  policy: 'Repository policy',
  budget: 'Attempts left',
  pull: 'Pull request',
  checks: 'Failing checks',
  permissions: 'App permissions',
  github: 'GitHub',
};

/**
 * The check each blocker belongs to, for an answer with no checks in it. A
 * blocker about the target changing says what became of the pull request or of
 * the checks, so it sits with the check that found it. GitHub not answering
 * belongs to none of them, so it is a row of its own, and the way forward from
 * it is to look again.
 */
const CHECK_OF_BLOCKER: Record<string, string> = {
  identity: 'identity',
  provider: 'provider',
  installation: 'installation',
  github: 'github',
  access: 'access',
  policy: 'policy',
  budget: 'budget',
  budget_unavailable: 'budget',
  pull: 'pull',
  closed: 'pull',
  superseded: 'pull',
  fixed: 'checks',
  checks_pending: 'checks',
  permissions: 'permissions',
};

function wayForward(code: string, repoUrl: string | undefined): CheckAction {
  switch (code) {
    case 'identity':
    case 'policy':
      return { kind: 'setup' };
    case 'provider':
      return { kind: 'link', href: '/settings/assistant', label: 'Add a model provider' };
    case 'installation':
      return { kind: 'link', href: '/installations', label: 'Open installations' };
    case 'permissions':
      return { kind: 'link', href: '/installations', label: 'Review installation permissions' };
    case 'pull':
      return { kind: 'choose' };
    case 'access': {
      // The host is the one the job's address named. With none known there is
      // nowhere honest to send somebody, so the row offers to look again.
      const repo = safeHttpUrl(repoUrl);
      if (!repo) return { kind: 'recheck' };
      return {
        kind: 'link',
        href: `${repo.replace(/\/+$/, '')}/settings/access`,
        label: 'Manage access on GitHub',
        external: true,
      };
    }
    default:
      return { kind: 'recheck' };
  }
}

function row(
  code: string,
  status: CheckStatus,
  message: string,
  repoUrl?: string,
  blocker?: string,
): CheckRow {
  const out: CheckRow = { code, label: LABELS[code] ?? code, status, message };
  if (status === 'blocked') {
    if (blocker) out.blocker = blocker;
    out.action = wayForward(couldNotCheck(blocker) ? blocker : code, repoUrl);
  }
  return out;
}

const rank = (code: string): number => {
  const at = ORDER.indexOf(code);
  return at < 0 ? ORDER.length : at;
};

function rowsFromBlockers(blockers: Readiness['blockers'], repoUrl?: string): CheckRow[] {
  const seen = new Map<string, { message: string; blocker: string }>();
  for (const blocker of blockers) {
    const code = CHECK_OF_BLOCKER[blocker.code] ?? blocker.code;
    if (!seen.has(code)) seen.set(code, { message: blocker.message, blocker: blocker.code });
  }
  return [...seen.entries()]
    .sort(([a], [b]) => rank(a) - rank(b))
    .map(([code, { message, blocker }]) => row(code, 'blocked', message, repoUrl, blocker));
}

/**
 * Every check readiness made, as rows. `repoUrl` is the repository's address on
 * the host that served the failure, which the access row sends somebody to; it
 * is not guessed when it is not known.
 */
export function checkRows(readiness: ReadinessLike, repoUrl?: string): CheckRow[] {
  const checks = readiness.checks ?? [];
  if (checks.length === 0) return rowsFromBlockers(readiness.blockers, repoUrl);
  return checks.map((check) =>
    row(
      check.code,
      check.status === 'ok' || check.status === 'blocked' ? check.status : 'unchecked',
      check.message,
      repoUrl,
      check.blocker,
    ),
  );
}

const HEADLINES: Record<string, string> = {
  identity: 'Link your GitHub account',
  provider: 'Add a model provider',
  installation: 'Connect the GitHub installation',
  access: 'Fix write access first',
  policy: 'Turn repairs on for this repository',
  budget: 'No attempts left today',
  pull: 'Choose a pull request',
  checks: 'Wait for the checks',
  permissions: 'Grant the GitHub App its permissions',
  github: 'GitHub did not answer',
  budget_unavailable: 'Could not check the allowance',
};

/**
 * What the decision card says about the check that blocks, as the one thing to do.
 * A check that could not be made says so in place of what it was checking.
 */
export function blockedHeadline(code: string, blocker?: string): string {
  return HEADLINES[couldNotCheck(blocker) ? blocker : code] ?? 'Something needs your attention';
}

/** The first thing in the way, which is the one the card is about. */
export function blockingRow(rows: readonly CheckRow[]): CheckRow | undefined {
  return rows.find((r) => r.status === 'blocked');
}

/*
  A failed job's error lines, made fit to show. They are what a program printed
  to a terminal, so they arrive with the colour codes it wrote for one. Those are
  noise on a page, and any other control character is a way to confuse a reader
  or to hide text, so they go too. The text itself is never altered: it is drawn
  as text by the component, whatever markup it holds.
*/

const ESC = String.fromCharCode(27);

// A control sequence introducer: ESC [ parameters intermediates final.
const SEQUENCE = new RegExp(`${ESC}\\[[0-9;?]*[ -/]*[@-~]`, 'g');

// Everything below a space except the tab, and DEL.
// eslint-disable-next-line no-control-regex
const CONTROL = /[\u0000-\u0008\u000a-\u001f\u007f]/g;

/** The lines with escape sequences and control characters removed, and empty ones dropped. */
export function cleanLines(lines: readonly string[]): string[] {
  return lines
    .map((line) => line.replace(SEQUENCE, '').replace(CONTROL, ''))
    .filter((line) => line.trim() !== '');
}

import type { Schemas } from '../api/types';

/*
  What to try next. A repair that did not end well says why in the controller's
  words; this adds what a person can do about it, keyed by the failure code the
  worker recorded or, when there is none, by the state the repair ended in. The
  copy is the first draft of the design and a change to a sentence is welcome;
  the mapping from code to advice is what the tests hold.
*/

export interface Guidance {
  /** What happened, in one line. */
  headline: string;
  /** What to do about it, at most three. */
  steps: string[];
}

const UNSUPPORTED_FIX: Guidance = {
  headline: 'Eli could not produce a fix it was willing to push',
  steps: [
    'Add a note that points at the file or the test, then try again.',
    'Read the error output: the quickest fix may be yours.',
  ],
};

/** What a repair that has not finished says: nothing is wrong, and nothing needs doing. */
const STILL_WORKING: Guidance = {
  headline: 'Eli is still working on it',
  steps: ['You can leave this page. The repair carries on without it.'],
};

const TABLE: Record<string, Guidance> = {
  unsupported_fix: UNSUPPORTED_FIX,
  context_limit: {
    headline: 'The failure and the source were too big for one attempt',
    steps: ['Name the file or the test in a note so Eli reads less, then try again.'],
  },
  source_unavailable: {
    headline: 'Eli could not read the source',
    steps: [
      'Check that the GitHub App has the Contents permission.',
      'Check that the pull request changes fewer than 100 files.',
    ],
  },
  provider_unavailable: {
    headline: 'The model provider failed',
    steps: ['Test it in Eli settings, then try again.'],
  },
  provider_billing: {
    headline: 'The provider’s account cannot pay for the repair',
    steps: ['Add credit to the provider’s account, or choose another provider in Eli settings.'],
  },
  rate_limited: {
    headline: 'The model provider is rate limiting you',
    steps: ['Wait a few minutes, then try again.', 'Check the quota on your provider account.'],
  },
  provider_credentials: {
    headline: 'The provider refused your key',
    steps: ['Update the key in Eli settings, then try again.'],
  },
  output_limit: {
    headline: 'The model ran out of room to answer',
    steps: ['Lower its reasoning effort, or choose a model that can write more, in Eli settings.'],
  },
  setup_needed: {
    headline: 'Eli’s access changed',
    steps: ['Check repair setup.', 'Then check readiness again before asking for another attempt.'],
  },
  checks_failed: {
    headline: 'Eli pushed a commit and the checks still fail',
    steps: [
      'Open the commit to see what changed and which checks failed.',
      'Another attempt starts from the new head, so it sees Eli’s change.',
    ],
  },
  interrupted: {
    headline: 'The controller restarted while Eli was working',
    steps: ['Check whether a commit was pushed to the branch, then try again.'],
  },
  unverified: {
    headline: 'No complete check result was seen',
    steps: ['Open the pull request’s checks before you accept the fix.'],
  },
  superseded: {
    headline: 'The pull request moved on',
    steps: [
      'Check the current pull request: a newer commit replaced the one Eli worked on, or its checks already passed.',
    ],
  },
  blocked: {
    headline: 'Something stopped the repair before it began',
    steps: ['Read the message above for what to fix, then check readiness again.'],
  },
  succeeded: {
    headline: 'The checks on Eli’s commit passed',
    steps: ['Review the commit as you would any other change. Eli never merges.'],
  },
  queued: STILL_WORKING,
  working: STILL_WORKING,
  checking: STILL_WORKING,
};

/**
 * The advice for a repair. A failure code outranks the state the repair ended
 * in, because the code says why; a code this build does not know, and a failure
 * with none, get the advice that is true of any repair that did not produce a
 * fix, so the card is never empty.
 */
export function guidanceFor(repair: Pick<Schemas['EliRepair'], 'state' | 'details'>): Guidance {
  const code = repair.details?.failure_code ?? '';
  if (Object.hasOwn(TABLE, code)) return TABLE[code]!;
  if (Object.hasOwn(TABLE, repair.state)) return TABLE[repair.state]!;
  return UNSUPPORTED_FIX;
}

import type { Query } from '../api/types';
import { formatNumber, pluralise } from '../format';

/*
  What the Recent repairs history needs to know that is not about drawing it:
  which filters there are, what each one sends, and where the page should be
  after rows leave it. The server does the filtering and the paging, so this
  file never looks at a repair's fields beyond its state.
*/

export type RepairGroup = 'all' | 'attention' | 'active' | 'passed';
export type RepairTrigger = 'any' | 'automatic' | 'requested';

export interface RepairFilters {
  group: RepairGroup;
  repo: string;
  trigger: RepairTrigger;
}

export const NO_REPAIR_FILTERS: RepairFilters = { group: 'all', repo: '', trigger: 'any' };

/**
 * Whether any filter is set. It decides between "No repairs yet" and "No
 * repairs match these filters", which an operator acts on differently, so a
 * repository box holding only spaces is not a filter: it is not sent either.
 */
export const filtered = (f: RepairFilters): boolean =>
  f.group !== 'all' || f.repo.trim() !== '' || f.trigger !== 'any';

const IN_PROGRESS = ['queued', 'working', 'checking'];

/** A repair Eli is still on, which cannot be retried or cleared from the history. */
export const isActive = (state: string): boolean => IN_PROGRESS.includes(state);

export const stateLabel = (state: string) =>
  ({
    queued: 'Queued',
    working: 'Investigating',
    checking: 'Waiting for CI',
    succeeded: 'Checks passed',
    checks_failed: 'Checks failed',
    interrupted: 'Interrupted',
    unverified: 'Unverified',
    superseded: 'Newer commit',
    blocked: 'Needs attention',
    failed: 'Could not repair',
  })[state] ?? state;

/**
 * The filters as the selection endpoint takes them: what a select-all means is
 * everything the same filters would list, with no page in it. A default is
 * left out rather than spelled out, so the page never depends on the server
 * agreeing that `group=all` means no filter.
 */
export function selectionQuery(f: RepairFilters): Query<'selectEliRepairs'> {
  const query: Query<'selectEliRepairs'> = {};
  if (f.group !== 'all') query.group = f.group;
  const repo = f.repo.trim();
  if (repo) query.repo = repo;
  if (f.trigger !== 'any') query.trigger = f.trigger;
  return query;
}

export function listQuery(
  f: RepairFilters,
  limit: number,
  offset: number,
): Query<'listEliRepairs'> {
  return { ...selectionQuery(f), limit, offset };
}

/**
 * Where to read from once `cleared` rows have left a history of `total`: the
 * page the operator was on if it still has a row, otherwise the last page that
 * does. Staying put would show an empty list beside a total that says there
 * are repairs, and the empty state is for a history with none.
 */
export function offsetAfterClear(
  offset: number,
  limit: number,
  total: number,
  cleared: number,
): number {
  const remaining = Math.max(0, total - cleared);
  if (limit <= 0 || remaining === 0) return 0;
  const lastStart = Math.floor((remaining - 1) / limit) * limit;
  return Math.max(0, Math.min(offset, lastStart));
}

/** What the closed History section still says, from the list it last read. */
export interface RepairHistorySummary {
  loaded: boolean;
  error: string;
  total: number;
  /** The newest repair on the first page, when there is one. */
  latest?: string;
  /** Whether the total is narrowed by a filter. */
  filtered: boolean;
}

/** What the bulk route will take in one request. A longer list is refused outright. */
export const BULK_LIMIT = 500;

/** The ids cut into requests the bulk route accepts, in the order they were chosen. */
export function batches<T>(items: readonly T[], size: number): T[][] {
  const parts: T[][] = [];
  for (let start = 0; start < items.length; start += size)
    parts.push(items.slice(start, start + size));
  return parts;
}

export interface ClearReport {
  cleared: number;
  skipped: { id: string; error: string }[];
}

/**
 * What a clear did, from the route's answer for each id. The route answers 200
 * however many it refused, so a partial failure is only visible here; the
 * skipped ones keep the order they were asked in. `unattempted` are the ids a
 * clear never reached because a later request failed: they are listed after the
 * refused ones, since saying "0 skipped" would leave them nowhere on the screen.
 */
export function clearReport(
  results: readonly { id: string; ok: boolean; error?: string }[],
  unattempted: readonly string[] = [],
): ClearReport {
  const report: ClearReport = { cleared: 0, skipped: [] };
  for (const result of results) {
    if (result.ok) report.cleared++;
    else report.skipped.push({ id: result.id, error: result.error || 'not cleared' });
  }
  for (const id of unattempted) report.skipped.push({ id, error: 'not attempted' });
  return report;
}

/**
 * What a clear did, in one line: what the outcome shows and what a screen
 * reader is told. One function so the two cannot say different things.
 */
export function clearSummary(cleared: number, skipped: number): string {
  const done = `${pluralise(cleared, 'repair')} cleared from the history`;
  return skipped > 0 ? `${done}, ${formatNumber(skipped)} skipped` : done;
}

/**
 * What the confirmation says. The count comes first because after a select-all
 * it is the one thing the operator cannot see from the dialog: up to 500
 * repairs, most of them on pages they never looked at. The page has no way to
 * bring a cleared repair back, so that is said here too. The rest is what
 * clearing leaves alone: a cleared repair is hidden and kept, still the record
 * the daily limit and the guard against Eli repairing its own commits read, and
 * an operator who thinks otherwise would take clearing for a way round the limit.
 */
export function clearConsequences(count: number): readonly string[] {
  const how = `${formatNumber(count)} ${count === 1 ? 'repair' : 'repairs'}`;
  return [
    `${how} will stop showing in this list, and this cannot be undone from this page.`,
    "They still count towards each repository's daily limit.",
    'Eli will not repair its own commits from them again.',
  ];
}

import type { Job, Schemas } from '../api/types';
import { caseFromLive, type CaseView } from './case';
import { pullUrl } from './links';

/*
  What the hub works out from what it was given, so a test can hold it without a
  browser: the case behind each repair offer, and what the setup bar says.
*/

type Offer = Schemas['EliOpportunity'];

/**
 * How many running repairs the hub lists. A person has a handful at most, and a
 * list this long is read as a list rather than paged; the badge says how many
 * there are in all. It is not a page size the history offers, which is what lets
 * the history's own tests tell the two reads apart.
 */
export const RUNNING_LIMIT = 20;

/**
 * The case behind each offer, by the offer's id, built from the failed jobs of
 * its run.
 *
 * The hub asks for the jobs of every offer's run in one read, and a run id is a
 * key only within its repository, so what comes back may hold another
 * repository's run of the same number. Each offer takes only the jobs that are
 * its own, with the repository compared the way GitHub does, without regard to
 * case. An offer with no run, or whose jobs Zoomies has pruned, has a case with
 * nothing in it rather than none, so the card can still say what it is about.
 */
export function offerCases(
  offers: readonly Offer[],
  jobs: readonly Job[],
): Record<string, CaseView> {
  const out: Record<string, CaseView> = {};
  for (const offer of offers) {
    const repo = offer.repo.toLowerCase();
    const mine =
      offer.run_id > 0
        ? jobs.filter(
            (job) => job.github_run_id === offer.run_id && job.repo?.toLowerCase() === repo,
          )
        : [];
    const view = caseFromLive({
      repo: offer.repo,
      jobs: mine,
      readiness: null,
      run: offer.run_id > 0 ? offer.run_id : undefined,
    });
    // The offer knows its pull request, which no job does.
    view.pullNumber = offer.pull_number;
    if (offer.title) view.title = offer.title;
    const link = pullUrl(view.repoUrl, offer.pull_number);
    if (link) view.pullUrl = link;
    out[offer.id] = view;
  }
  return out;
}

export interface SetupSummary {
  state: 'loading' | 'ready' | 'needed' | 'off';
  /** The one word an operator looks for. */
  headline: string;
  /** What is known about the GitHub account, or what is missing. */
  account: string;
  /** How many repositories are on Ask me first, for an administrator and nobody else. */
  askFirst: number | null;
  /** How many repair themselves, counted the same way and for the same people. */
  automatic: number | null;
}

/**
 * Whether the person looking at the hub can repair, and what stands in the way.
 * It is about that person: another person's link does not make them ready. With
 * sign-in off there is nobody to repair as, which outranks everything else, and
 * until the settings arrive the bar says so rather than claiming either.
 */
export function setupSummary(input: {
  settings: Schemas['EliRepairSettings'] | null;
  userId: string | undefined;
  admin: boolean;
  authDisabled: boolean;
}): SetupSummary {
  const { settings, userId, admin, authDisabled } = input;
  if (authDisabled) {
    return {
      state: 'off',
      headline: 'Sign-in is off',
      account: 'Repairs need a signed-in person with a linked GitHub account',
      askFirst: null,
      automatic: null,
    };
  }
  if (!settings)
    return {
      state: 'loading',
      headline: 'Checking setup',
      account: '',
      askFirst: null,
      automatic: null,
    };

  const askFirst = admin
    ? settings.policies.filter((policy) => policy.enabled && policy.ask_first).length
    : null;
  const automatic = admin
    ? settings.policies.filter((policy) => policy.enabled && policy.automatic).length
    : null;
  const own = userId
    ? settings.identities.find((identity) => identity.user_id === userId)
    : undefined;
  if (!own) {
    return {
      state: 'needed',
      headline: 'Setup needed',
      account: 'No GitHub account linked',
      askFirst,
      automatic,
    };
  }
  if (!own.confirmed) {
    return {
      state: 'needed',
      headline: 'Setup needed',
      account: `GitHub @${own.github_login} linked, repairs not allowed yet`,
      askFirst,
      automatic,
    };
  }
  return {
    state: 'ready',
    headline: 'Ready to repair',
    account: `GitHub @${own.github_login} linked`,
    askFirst,
    automatic,
  };
}

import type { Schemas, User } from '../api/types';

/*
  What the link form needs to know about a link it cannot write: the server
  refused it because the GitHub account is already linked to another Zoomies
  user, and a person holding two accounts after an instance move deserves to
  see whose row is in the way and one press to move the link, not a driver
  error and a hunt through the accounts page.
*/

export interface HeldLink {
  /** The holder's Zoomies account id, as the refusal carried in detail. */
  holderId: string;
  /** The holder by name when the page's user list has their row, else null. */
  user: User | null;
}

/**
 * The held-link refusal, as the page's data for it, or null for any other
 * refusal: the toast keeps those. The refusal's detail names the holder, and
 * the link row the page already holds is the fallback for a list drawn before
 * the link landed where it now is. The typed login decides which row the
 * page agrees with, compared without case, because the form holds what was
 * typed and the row what GitHub verified.
 */
export function heldLink(
  error: { code?: string; detail?: string },
  login: string,
  identities: readonly (Schemas['EliIdentity'] | undefined)[] | undefined,
  users: readonly User[],
): HeldLink | null {
  if (error?.code !== 'assistant.identity_held') return null;
  const wanted = login.trim().toLowerCase();
  const row = (identities ?? []).find(
    (i) => i !== undefined && i.github_login.toLowerCase() === wanted,
  );
  const holderId = error.detail || row?.user_id || '';
  return { holderId, user: users.find((u) => u.id === holderId) ?? null };
}

/**
 * The sentence the page shows for a held link: whose it is, and what moving
 * it does to them. An unknown holder keeps the generic sentence rather than
 * an empty at-sign.
 */
export function heldLinkMessage(held: HeldLink): string {
  const name = held.user?.username || held.holderId;
  if (!name) {
    return 'The GitHub account is already linked to another Zoomies user. Move the link to the person chosen above; their confirmation resets, so they must allow provider use again.';
  }
  return `@${name} already holds this GitHub account's link. Move the link to the person chosen above; their confirmation resets, so they must allow provider use again.`;
}

/*
  Where a repair that is running has got to: the five steps the worker takes, in
  order, and the mark on the one it is on. The attempt page's track, the hub's
  small bars and the live region all read it, so they cannot tell different
  stories about the same repair, and a test can hold it without a browser.
*/

import { isActive } from './history';

/** A step of the track against the mark: behind it, on it, or still to come. */
export type StepState = 'done' | 'current' | 'todo';

/**
 * The work a running repair is doing, in the order the worker does it. The
 * labels are what the operator reads while they wait, so they say what is
 * happening rather than which function is running.
 */
export const REPAIR_TRACK = [
  { id: 'queued', label: 'Queued' },
  { id: 'evidence', label: 'Reading the failed checks' },
  { id: 'prepare', label: 'Preparing the fix' },
  { id: 'publish', label: 'Pushing the commit' },
  { id: 'watch', label: 'Watching CI' },
] as const;

/**
 * A row read between two writes can lack fields, and the queue's own word for
 * a repair it has not touched yet is the queued state: an absent state is not
 * a terminal one, or every follow would read a half-written row as finished.
 */
export const stateOf = (repair: { state?: string } | null): string => repair?.state || 'queued';

/**
 * Where a repair is on its track. The stage field is the worker's own word and
 * the commit is proof: a row read between two writes may still carry yesterday's
 * stage, so a published commit only ever moves the mark forwards.
 */
export function trackIndex(repair: {
  state?: string;
  commit_sha?: string;
  details?: { stage?: string } | null;
}): number {
  const state = stateOf(repair);
  const stage = repair.details?.stage ?? '';
  let index = 0;
  if (state !== 'queued' || stage === 'evidence' || stage === 'source') index = 1;
  if (stage === 'prepare_fix') index = 2;
  if (stage === 'publish') index = 3;
  if (stage === 'watch_ci' || state === 'checking') index = 4;
  if (repair.commit_sha) index = Math.max(index, REPAIR_TRACK.length - 1);
  return Math.min(index, REPAIR_TRACK.length - 1);
}

/** The fields of a repair that say what it is for, and so whether it is the one being looked for. */
interface RepairRow {
  state: string;
  repo: string;
  run_id: number;
  pull_number: number;
  head_sha: string;
}

/** What a failure is known by when its repair is looked for. */
export interface RepairWanted {
  repo: string;
  /** The run the failure was reached by, which only a repair Eli queued itself records. */
  run?: number;
  pull?: number;
  /** The commit readiness resolved, which a repair a person queued is pinned to. */
  head?: string;
}

/**
 * The repair already working on a failure, if there is one.
 *
 * A failure reached from a run is first looked for by the run's id, but only a
 * repair Eli queues by itself records a run: one a person queued from this page
 * carries the pull request and the commit and no run, so by the run alone it is
 * never found and is offered a second time. Once readiness has said which pull
 * request and commit the run is, the same question is asked again of those.
 * Pressing the button would not queue a second repair, because the server answers
 * with the first, but it would offer as new something that is already under way.
 */
export function runningRepair<T extends RepairRow>(
  rows: readonly T[],
  want: RepairWanted,
): T | undefined {
  const repo = want.repo.toLowerCase();
  return rows.find((row) => {
    if (!isActive(row.state) || row.repo.toLowerCase() !== repo) return false;
    if (want.run) return row.run_id === want.run;
    return row.pull_number === want.pull && (want.head === undefined || row.head_sha === want.head);
  });
}

/**
 * The track with each step's place against the mark, which is what draws it:
 * the steps behind the mark are done, the one on it is current, the rest are
 * still to come. A repair that has finished is not drawn on the track at all
 * (its outcome is), so this answers for a repair that is still going.
 */
export function trackSteps(repair: Parameters<typeof trackIndex>[0]): {
  id: (typeof REPAIR_TRACK)[number]['id'];
  label: string;
  state: StepState;
}[] {
  const at = trackIndex(repair);
  return REPAIR_TRACK.map((step, index) => ({
    id: step.id,
    label: step.label,
    state: index < at ? 'done' : index === at ? 'current' : 'todo',
  }));
}

const STAGE_WORDS: Record<string, string> = {
  evidence: REPAIR_TRACK[1].label,
  source: 'Reading the source',
  prepare_fix: REPAIR_TRACK[2].label,
  publish: REPAIR_TRACK[3].label,
  watch_ci: REPAIR_TRACK[4].label,
};

/**
 * A stage the worker recorded, in words. The technical details say which stage a
 * repair reached, and a stage a newer worker invented is still readable: its id
 * is made into a sentence rather than hidden or shown as a code.
 */
export function stageWords(stage: string | null | undefined): string {
  if (!stage) return 'Not recorded';
  if (Object.hasOwn(STAGE_WORDS, stage)) return STAGE_WORDS[stage]!;
  const spaced = stage.replace(/_+/g, ' ').trim();
  return spaced ? spaced.charAt(0).toUpperCase() + spaced.slice(1) : 'Not recorded';
}

/*
  Addresses on a repair page. Every one of them came from somewhere that is not
  this build: a job's address from GitHub, a pull request's from whoever opened
  it. So a link is only ever an http or https address, and the repository, run
  and commit addresses are read off the host the job's address names rather than
  written as github.com, which would send a GitHub Enterprise Server user to the
  wrong site.
*/

const JOB_PATH = /^\/([^/]+)\/([^/]+)\/actions\/runs\/(\d+)\/job\/(\d+)\/?$/;
const COMMIT = /^[0-9a-f]{7,64}$/i;

const trimSlash = (value: string): string => value.replace(/\/+$/, '');

/**
 * The address if it is a web link, otherwise nothing. A scheme that runs script
 * or names a local file, an address with credentials in it, and anything that is
 * not an absolute address at all are all refused.
 */
export function safeHttpUrl(value: string | null | undefined): string | undefined {
  if (!value) return undefined;
  let url: URL;
  try {
    url = new URL(value.trim());
  } catch {
    return undefined;
  }
  if (url.protocol !== 'http:' && url.protocol !== 'https:') return undefined;
  if (!url.hostname || url.username || url.password) return undefined;
  return url.href;
}

/**
 * The job, its run and its repository, from the job's own address. An address
 * that is a web link but not a job page gives the job alone: it is still a place
 * to send somebody, and nothing more can be said about it.
 */
export function linksFromJobUrl(jobUrl: string | null | undefined): {
  job?: string;
  run?: string;
  repo?: string;
} {
  const job = safeHttpUrl(jobUrl);
  if (!job) return {};
  const url = new URL(job);
  const match = JOB_PATH.exec(url.pathname);
  if (!match) return { job };
  const repo = `${url.origin}/${match[1]}/${match[2]}`;
  return { job, run: `${repo}/actions/runs/${match[3]}`, repo };
}

/**
 * GitHub's id for a job, read off the job's own address. A repair keeps the
 * addresses of the jobs it was asked about and not their ids, and a job's log is
 * asked for by id, so the id comes back out of the address it was kept with.
 */
export function githubJobIdFromUrl(jobUrl: string | null | undefined): number | undefined {
  const job = safeHttpUrl(jobUrl);
  if (!job) return undefined;
  const match = JOB_PATH.exec(new URL(job).pathname);
  if (!match) return undefined;
  const id = Number(match[4]);
  return Number.isSafeInteger(id) && id > 0 ? id : undefined;
}

/** A commit's page, built on the repository's address. Nothing without both. */
export function commitUrl(repoUrl: string | undefined, sha: string): string | undefined {
  const repo = safeHttpUrl(repoUrl);
  if (!repo || !COMMIT.test(sha)) return undefined;
  return `${trimSlash(repo)}/commit/${sha}`;
}

/** A pull request's page, built on the repository's address. Nothing without it. */
export function pullUrl(repoUrl: string | undefined, number: number): string | undefined {
  const repo = safeHttpUrl(repoUrl);
  if (!repo || !Number.isSafeInteger(number) || number < 1) return undefined;
  return `${trimSlash(repo)}/pull/${number}`;
}

import { ApiError, stopEliAutomaticRepairs } from '$lib/api/client';
import { toasts } from '$lib/state/toasts.svelte';
import { stoppedWords, type StopChoice } from './automatic';

export interface StopResult {
  /** Something was stopped, or everything asked for was already stopped. */
  done: boolean;
  /** Why nothing could be stopped, for the dialog to say and stay open on. */
  error: string;
}

/**
 * Sends a stop and tells the person what became of it, the same way on every
 * page that offers one. When nothing could be stopped it says nothing itself and
 * returns the reason, so the dialog stays open and the same press is another
 * try; when some were stopped and some were not, it says which in an error toast
 * and counts as done, because the repositories that did stop are no longer there
 * to try again.
 */
export async function stopAutomatic(
  repos: readonly string[],
  then: StopChoice,
): Promise<StopResult> {
  try {
    const { results } = await stopEliAutomaticRepairs({ repos: [...repos], then });
    const outcome = stoppedWords(results, then);
    if (outcome.tone === 'error' && !results.some((r) => r.changed)) {
      return { done: false, error: outcome.message };
    }
    if (outcome.tone === 'error') toasts.error(outcome.title, outcome.message);
    else toasts.success(outcome.title, outcome.message);
    return { done: true, error: '' };
  } catch (cause) {
    return {
      done: false,
      error:
        cause instanceof ApiError ? cause.message : 'Could not stop automatic repairs. Try again.',
    };
  }
}

/** Only GitHub PR addresses are accepted, never arbitrary fetch destinations. */
export function parseRepairTarget(value: string): { repo: string; pull_number: number } | null {
  try {
    const url = new URL(value.trim());
    if (
      url.protocol !== 'https:' ||
      url.hostname !== 'github.com' ||
      url.username ||
      url.password ||
      url.port
    )
      return null;
    const match = /^\/([^/]+)\/([^/]+)\/pull\/([1-9]\d*)\/?$/.exec(url.pathname);
    if (!match || !Number.isSafeInteger(Number(match[3]))) return null;
    return { repo: `${match[1]}/${match[2]}`, pull_number: Number(match[3]) };
  } catch {
    return null;
  }
}

import type { Schemas } from '../api/types';

/*
  The repair page's state, held in its hands rather than in a component: what
  the address says it is about, and which of five things it is showing. It
  replaces the stage machine the old single-card flow kept in journey.ts, which
  also had to follow a running repair; the attempt now has a page of its own.
*/

export type WorkspaceStage = 'checking' | 'blocked' | 'ready' | 'changed' | 'error';

/**
 * What the address names. `run` and `pull` are zero when absent, `job` is a
 * Zoomies job id (the one the person opened, so it can be marked), and `offer`
 * is an offer's id.
 */
export interface RepairTarget {
  repo: string;
  pull: number;
  run: number;
  job: string;
  offer: string;
}

/** A positive whole number, or 0. The address is typed into, so nothing else gets through. */
function whole(value: string | null): number {
  if (!value || !/^[0-9]+$/.test(value)) return 0;
  const n = Number(value);
  return Number.isSafeInteger(n) && n > 0 ? n : 0;
}

export function parseTarget(query: URLSearchParams): RepairTarget {
  return {
    repo: (query.get('repo') ?? '').trim(),
    pull: whole(query.get('pull')),
    run: whole(query.get('run')),
    job: (query.get('job') ?? '').trim(),
    offer: (query.get('offer') ?? '').trim(),
  };
}

/** The repair page's address for a target, leaving out whatever is empty or zero. */
export function targetHref(target: Partial<RepairTarget>): string {
  const parts: string[] = [];
  const add = (key: string, value: string | number | undefined): void => {
    if (value === undefined || value === '' || value === 0) return;
    parts.push(`${key}=${encodeURIComponent(String(value))}`);
  };
  add('repo', target.repo);
  add('pull', target.pull);
  add('run', target.run);
  add('job', target.job);
  add('offer', target.offer);
  return parts.length ? `/repairs/new?${parts.join('&')}` : '/repairs/new';
}

/**
 * Whether a failed job can be offered to Eli at all. Eli pushes one commit to an
 * existing pull request's branch and never raises one, so the failure of a push,
 * merge or scheduled run has nothing to repair. A run whose trigger the
 * controller has not read yet is still offered: the repair page says why if it
 * turns out not to be one.
 */
export function eliCanRepairRun(job: { run_event?: string }): boolean {
  const event = job.run_event ?? '';
  return event === '' || event === 'pull_request' || event === 'pull_request_target';
}

const CHANGED = ['fixed', 'closed', 'superseded'] as const;

/**
 * The reason the target is no longer worth repairing, when it is not: the checks
 * passed, the pull request closed, or a newer commit replaced the one that
 * failed. These are answers, not obstacles, and they replace the page's card.
 */
export function changedBlocker(
  r: Schemas['EliReadiness'],
): { code: (typeof CHANGED)[number]; message: string } | undefined {
  for (const blocker of r.blockers) {
    const code = CHANGED.find((c) => c === blocker.code);
    if (code) return { code, message: blocker.message };
  }
  return undefined;
}

/**
 * Which of the five things the page is showing. A read that failed outranks an
 * answer left over from the one before; an answer that is not ready is blocked
 * even when it names no blocker, because the page must not offer a start on it.
 */
export function stageOf(r: Schemas['EliReadiness'] | null, failed: boolean): WorkspaceStage {
  if (failed) return 'error';
  if (!r) return 'checking';
  if (changedBlocker(r)) return 'changed';
  return r.ready && r.blockers.length === 0 ? 'ready' : 'blocked';
}

/**
 * The roles, in one place, in the words an operator sees.
 *
 * There were two copies of this list -- one in the accounts panel, one in the
 * tokens panel -- and they had already drifted: an administrator "also manages
 * accounts, tokens, installations and settings" in the first and "everything,
 * including accounts and settings" in the second. A third place printed the
 * bare id, so an operator was told their role was `admin` on one screen and
 * Administrator on the next.
 *
 * `internal/auth/rbac.go` is where the roles are actually enforced; this is
 * only how they are named and described.
 */
import type { Role } from './api/types';

export interface RoleOption {
  value: Role;
  label: string;
  /** One sentence, in ascending order of what it can do. */
  description: string;
}

export const ROLE_OPTIONS: readonly RoleOption[] = [
  { value: 'viewer', label: 'Viewer', description: 'Reads everything except secrets.' },
  { value: 'operator', label: 'Operator', description: 'Acts on the fleet and manages pools.' },
  {
    value: 'admin',
    label: 'Administrator',
    description: 'Also manages accounts, tokens, installations and settings.',
  },
  {
    value: 'platform',
    label: 'Platform',
    description: 'Also operates the process itself: its timers, backups and recovery.',
  },
];

/**
 * The display name for a role. Unknown values are shown as they arrived rather
 * than hidden: a role this build does not know about is worth seeing.
 */
export function roleLabel(role: string | undefined | null): string {
  if (!role) return 'Unknown';
  return ROLE_OPTIONS.find((option) => option.value === role)?.label ?? role;
}

/** The sentence saying what the role may do, or empty for one with no entry. */
export function roleDescription(role: string | undefined | null): string {
  if (!role) return '';
  return ROLE_OPTIONS.find((option) => option.value === role)?.description ?? '';
}

