};

/**
 * The same three states, said plainly, for when the kennel vocabulary is off.
 *
 * The two boosts each get a word of their own. They both said "Boost active"
 * once, and an operator scanning the grid could not tell an extra boost from
 * a maximum one without learning which icon was which.
 */
const activityStandard: Record<string, Activity> = {
  maximum_zoomies: {
    label: 'Zoomies',
    title: 'Maximum boost',
    detail: 'A major CPU boost is active. This runner is borrowing spare host capacity.',
    tone: 'busy',
  },
  zoomies: {
    label: 'Extra',
    title: 'Extra boost',
    detail: 'Extra CPU is available to this runner while its host has room to spare.',
    tone: 'busy',
  },
  throttled: {
    label: 'Throttled',
    title: 'Host pressure protection',
    detail: 'CPU has been reduced to protect the host. It can recover as pressure eases.',
    tone: 'pending',
  },
};

const quietCPUQuirky: Record<string, string> = {
  observing: 'Nose to the wind: spare CPU is being observed, without changing this allocation.',
  guaranteed: 'Steady paws: this runner has its guaranteed CPU allocation.',
  sit_and_stay: 'Sit and stay: elastic CPU is off for this pool.',
};

const quietCPUStandard: Record<string, string> = {
  observing: 'Spare CPU is being observed, without changing this allocation.',
  guaranteed: 'This runner has its guaranteed CPU allocation.',
  sit_and_stay: 'Elastic CPU is off for this pool.',
};

/**
 * Lifecycle stays authoritative. Only an active allocation replaces Busy/Idle.
 *
 * `quirky` is passed in by the caller rather than read here -- see the note
 * on `runnerStatus` in `../status` for why this module stays free of it too.
 */
export function runnerDisplayStatus(runner: StatusRunner, quirky = true) {
  const lifecycle = runnerStatus(runner.state, quirky);
  const canBoost = runner.state === 'busy' || runner.state === 'idle';
  const resource = runner.cpu_resource;
  const activity = quirky ? activityQuirky : activityStandard;
  const active = canBoost ? activity[resource?.state ?? ''] : undefined;
  const key = active ? resource!.state! : lifecycle.key;
  const detail = active?.detail ?? lifecycle.hint ?? 'No runner state has been reported.';
  const quietCPU = quirky ? quietCPUQuirky : quietCPUStandard;
  const cpuDetail = !active && canBoost ? quietCPU[resource?.state ?? ''] : undefined;
  const icon = active ? cpuResourceStatus(resource!.state, undefined, quirky).icon : lifecycle.icon;
  return {
    key,
    label: active?.label ?? lifecycle.label,
    title: active?.title ?? lifecycle.label,
    detail,
    cpuDetail,
    lifecycle,
    active: Boolean(active),
    canBoost,
    icon,
    tone: active?.tone ?? lifecycle.tone,
    ...toneTokens(active?.tone ?? lifecycle.tone),
  };
}

import { dogPhase } from '../mascot/dog-motion';

/** The gestures StandardStatusIcon draws. Every state keeps at least one
 *  living motion, so a stalled runner never looks like a broken image; the
 *  terminal three move slowly and sadly rather than freezing. */
export type DogMotion =
  'trot' | 'dash' | 'sit' | 'sniff' | 'wave' | 'strain' | 'settle' | 'low' | 'ghost' | 'scan';

/** The glyph in the icon's corner, which stays when motion is off. */
export type DogCue =
  | 'work'
  | 'boost'
  | 'maximum'
  | 'ready'
  | 'search'
  | 'hello'
  | 'pause'
  | 'rest'
  | 'error'
  | 'gone'
  | 'question';

const STATES = [
  'busy',
  'zoomies',
  'maximum_zoomies',
  'idle',
  'provisioning',
  'registering',
  'throttled',
  'draining',
  'failed',
  'removed',
  'unknown',
] as const;
export type StandardMotionState = (typeof STATES)[number];

const MOTIONS: Record<StandardMotionState, { motion: DogMotion; cue: DogCue; duration: number }> = {
  busy: { motion: 'trot', cue: 'work', duration: 1.3 },
  zoomies: { motion: 'dash', cue: 'boost', duration: 0.8 },
  maximum_zoomies: { motion: 'dash', cue: 'maximum', duration: 0.5 },
  idle: { motion: 'sit', cue: 'ready', duration: 6 },
  provisioning: { motion: 'sniff', cue: 'search', duration: 3.6 },
  registering: { motion: 'wave', cue: 'hello', duration: 3.2 },
  throttled: { motion: 'strain', cue: 'pause', duration: 2.2 },
  draining: { motion: 'settle', cue: 'rest', duration: 5 },
  failed: { motion: 'low', cue: 'error', duration: 6.5 },
  removed: { motion: 'ghost', cue: 'gone', duration: 5 },
  unknown: { motion: 'scan', cue: 'question', duration: 5 },
};

/** Status cues survive reduced motion; failures move slowly, never happily. */
export function standardMotion(state: string, seed: string) {
  const known = STATES.includes(state as StandardMotionState)
    ? (state as StandardMotionState)
    : 'unknown';
  const animation = MOTIONS[known];
  const phase = dogPhase(seed);
  const duration = animation.duration + phase * 0.15;
  return {
    state: known,
    ...animation,
    duration,
    // A negative delay starts each runner partway through its lap, so a page
    // of busy dogs never bobs in unison.
    phase: -phase * duration,
  };
}

/**
 * The Assistant settings page's words and shapes. The API calls live in the
 * client; this is what the page says about what they return.
 */
import type {
  AssistantProvider,
  AssistantProviderCheck,
  AssistantProviderKind,
} from '$lib/api/types';

/**
 * The title a toast about a switch gets: the row's label, as the page shows
 * it, and the key only when the rows are not loaded (a toast about a key no
 * row carries is still better than one with no title).
 */
export function settingTitle(rows: readonly { key: string; label: string }[], key: string): string {
  return rows.find((row) => row.key === key)?.label ?? key;
}

/** One line for a card: what the last Test learned, or that none was run. */
export function checkSummary(check: AssistantProviderCheck | null | undefined): string {
  if (!check) return 'Never tested';
  if (!check.ok) return check.error || 'The last test failed and gave no reason.';
  const usage = check.usage_reported ? 'usage reported' : 'usage not reported';
  return `Answered as ${check.model || 'the model'} in ${check.latency_ms} ms; ${usage}`;
}

