import {
  ApiError,
  createTransferUpload,
  getTransferUpload,
  uploadTransferChunk,
  verifyTransferUpload,
} from '../api/client';
import type { Schemas } from '../api/types';

/** Keep the receipt between attempts so a lost response does not require re-uploading. */
export async function uploadInstanceArchive(
  file: File,
  passphrase: string,
  previous: Schemas['TransferUpload'] | null,
  update: (value: Schemas['TransferUpload']) => void,
): Promise<Schemas['Backup']> {
  let upload = previous
    ? await getTransferUpload(previous.id)
    : await createTransferUpload(file.size);
  update(upload);
  while (upload.offset < file.size && upload.state === 'uploading') {
    const end = Math.min(upload.offset + upload.chunk_bytes, file.size);
    const chunk = file.slice(upload.offset, end);
    // A request can have saved its bytes even when its response was lost.
    // Ask for the durable offset before retrying that same bounded chunk.
    let received = false;
    for (let attempt = 0; attempt < 3; attempt++) {
      try {
        upload = await uploadTransferChunk(upload.id, upload.offset, chunk);
        received = true;
        break;
      } catch (cause) {
        if (!(cause instanceof ApiError) || (cause.status > 0 && cause.status < 500)) throw cause;
        upload = await getTransferUpload(upload.id);
        if (upload.offset === end) {
          received = true;
          break;
        }
        if (attempt === 2) throw cause;
      }
    }
    if (!received) throw new Error('The upload did not complete. Try again.');
    update(upload);
  }
  if (upload.state === 'uploading') upload = await verifyTransferUpload(upload.id, passphrase);
  update(upload);
  while (upload.state === 'verifying') {
    await new Promise((resolve) => setTimeout(resolve, 1000));
    upload = await getTransferUpload(upload.id);
    update(upload);
  }
  if (upload.state !== 'verified' || !upload.backup) {
    throw new Error(upload.error || 'The archive was not verified. Choose it again to retry.');
  }
  return upload.backup;
}

/**
 * What the transfer panel shows of a preparation: the four things the fence
 * waits on as a checklist, and each thing still in the way with the tone it
 * deserves.
 *
 * The counts come from the controller and the sentences are its own; this
 * decides only how they are laid out, so that "8 awaiting cleanup" is a step
 * with eight named rows under it rather than a number in a paragraph.
 */
import type { Schemas } from '$lib/api/types';
import type { StatusTone } from '$lib/status';

export type TransferProgress = Schemas['TransferProgress'];
export type TransferWait = Schemas['TransferWait'];

export interface TransferStep {
  /** Matches `TransferWait.kind`, so the rows under a step are found by it. */
  kind: TransferWait['kind'];
  label: string;
  count: number;
  /** A step is done when nothing of its kind is left. */
  done: boolean;
  tone: StatusTone;
  /** Said under the label while the step is not done. */
  note: string;
}

/**
 * The checklist. A step is `pending` while its count is above zero, `danger`
 * when something under it needs a person (a host that has stopped talking,
 * or a cleanup that failed), and `idle` once it is done: the tone operators
 * already read as "nothing to do here".
 */
export function transferSteps(p: TransferProgress): TransferStep[] {
  const waits = p.waiting ?? [];
  const silent = (kind: TransferWait['kind']) =>
    waits.some((w) => w.kind === kind && w.host && !w.host_healthy);
  const step = (
    kind: TransferWait['kind'],
    label: string,
    count: number,
    note: string,
    needsSomebody: boolean,
  ): TransferStep => ({
    kind,
    label,
    count,
    done: count === 0,
    tone: count === 0 ? 'idle' : needsSomebody ? 'danger' : 'pending',
    note: count === 0 ? '' : note,
  });
  const idle = Math.max(0, p.live_runners - p.busy_runners);
  return [
    step(
      'job',
      'Jobs on this fleet finish',
      p.active_jobs,
      'Running jobs are left to finish; nothing new is started.',
      silent('job'),
    ),
    step(
      'runner',
      'Runners are withdrawn',
      p.live_runners,
      idle > 0 && p.busy_runners > 0
        ? `${p.busy_runners} busy, ${idle} idle being withdrawn.`
        : p.busy_runners > 0
          ? 'Busy runners stop once their job is done.'
          : 'Idle runners are withdrawn from GitHub and stopped.',
      silent('runner'),
    ),
    step(
      'cleanup',
      'Removed runners are confirmed gone',
      p.pending_cleanup,
      cleanupNote(p),
      silent('cleanup') || p.cleanup_failed > 0,
    ),
    step(
      'machine',
      'Machine operations finish',
      p.machine_operations,
      'A clone or a delete under way at a provider is left to finish.',
      false,
    ),
  ];
}

function cleanupNote(p: TransferProgress): string {
  const sides: string[] = [];
  if (p.cleanup_awaiting_host > 0) sides.push(`${p.cleanup_awaiting_host} by the host`);
  if (p.cleanup_awaiting_github > 0) sides.push(`${p.cleanup_awaiting_github} by GitHub`);
  const failed = p.cleanup_failed > 0 ? `; ${p.cleanup_failed} failed` : '';
  return sides.length > 0
    ? `Waiting to be confirmed gone: ${sides.join(', ')}${failed}.`
    : 'Waiting to be confirmed gone.';
}

/** The tone of one row: danger where a person is needed, pending otherwise. */
export function waitTone(w: TransferWait): StatusTone {
  if (w.error) return 'danger';
  if (w.host && !w.host_healthy) return 'danger';
  if (w.kind === 'runner' && w.state === 'busy') return 'busy';
  return 'pending';
}

/** The short word on a row's pill: its state, or what it is waiting on. */
export function waitLabel(w: TransferWait): string {
  if (w.error) return 'Failed';
  if (w.host && !w.host_healthy) return 'Host silent';
  switch (w.kind) {
    case 'cleanup':
      return !w.host_confirmed ? 'Host' : 'GitHub';
    case 'job':
      return 'Running';
    default:
      return w.state ? w.state.charAt(0).toUpperCase() + w.state.slice(1) : 'Waiting';
  }
}

/**
 * What the side panel says about the controller build this page is talking
 * to, and where that points.
 *
 * Three kinds of build reach an operator, and each is identified differently:
 * a release by its tag, because that is what an upgrade and a bug report name;
 * a build from main by its commit, because every one of them is published under
 * the same moving `dev` tag and the tag alone cannot tell two apart; and a
 * local build, which is neither and is said to be so rather than dressed up as
 * one of them. It is plain enough to test in Node, which is why it lives apart
 * from the component.
 */
import { REPO_URL } from '../links';

export interface BuildMeta {
  version?: string;
  version_channel?: string;
  commit?: string;
}

export interface BuildLabel {
  /** "Release", "Dev" or "Local build". */
  kind: string;
  /** The tag or the short commit. */
  name: string;
  /** Where on GitHub that release or commit is, when it is published there. */
  href?: string;
  /** The full line, for a tooltip and a screen reader. */
  title: string;
}

export function buildLabel(meta: BuildMeta | null | undefined): BuildLabel | null {
  const channel = meta?.version_channel?.trim() ?? '';
  const commit = meta?.commit?.trim() ?? '';
  const short = commit.slice(0, 7);
  // version is "1.3.0 (abc1234)": the part before the commit is the build.
  const version = (meta?.version ?? '').replace(/\s*\([0-9a-f]+\)\s*$/, '').trim();

  if (channel.startsWith('v')) {
    return {
      kind: 'Release',
      name: channel,
      href: `${REPO_URL}/releases/tag/${channel}`,
      title: `Zoomies ${channel}${short ? ` (${short})` : ''}, a published release`,
    };
  }
  if (channel === 'dev') {
    return {
      kind: 'Dev',
      name: short || version || 'dev',
      href: commit ? `${REPO_URL}/commit/${commit}` : undefined,
      title: `Zoomies development build${short ? ` from commit ${short}` : ''}, published under the dev tag`,
    };
  }
  if (!version && !short) return null;
  return {
    kind: 'Local build',
    name: short || version,
    title: `Zoomies ${version || 'local build'}${short ? ` (${short})` : ''}, built locally and not published`,
  };
}

