/**
 * The shared tooltip for an element that is built by hand rather than by a
 * component, such as the grips and edges `tableLayout` adds to a table heading.
 *
 * It is the same controller and the same bubble as `Tooltip`, so these follow the
 * same timing, close on the same Escape and never open beside another one. What
 * it cannot do is wrap its element, so the sentence is linked to it with
 * `aria-describedby`, and the bubble is mounted when it opens and taken away
 * when it closes. It returns what undoes all of that.
 */
import { mount, unmount } from 'svelte';
import { focusWasPlaced } from './keys';
import TooltipBubble from './components/TooltipBubble.svelte';
import { tooltips, type Bubble, type Wait } from './tooltip';
import { descriptionHost } from './tooltip-description';
import { whenPointerMoves } from './tooltip-intent';
import type { Side } from './tooltip-place';

export interface AttachedTip {
  text: string;
  placement?: Side;
  wait?: Wait;
}

let counter = 0;

export function attachTip(el: HTMLElement, tip: AttachedTip): () => void {
  let shown: ReturnType<typeof mount> | null = null;

  const handle: Bubble = {
    show() {
      if (shown) return;
      shown = mount(TooltipBubble, {
        target: document.body,
        props: {
          anchor: el,
          placement: tip.placement ?? 'top',
          text: tip.text,
          onclose: () => tooltips.dismiss(handle),
          onenter: () => tooltips.bubbleEnter(handle),
          onleave: () => tooltips.bubbleLeave(handle),
        },
      });
    },
    hide() {
      if (!shown) return;
      void unmount(shown);
      shown = null;
    },
  };

  const description = document.createElement('span');
  description.id = `tip-attached-${++counter}`;
  description.textContent = tip.text;
  descriptionHost().append(description);
  const described = (el.getAttribute('aria-describedby') ?? '').split(/\s+/).filter(Boolean);
  el.setAttribute('aria-describedby', [...described, description.id].join(' '));

  let pointerReached = false;
  const stopIntent = whenPointerMoves(el, (event) => {
    // A finger has no hover; the sentence is still the description.
    if (event.pointerType === 'touch' || pointerReached) return;
    pointerReached = true;
    tooltips.hover(handle, tip.wait);
  });
  const onLeave = () => {
    pointerReached = false;
    tooltips.unhover(handle);
  };
  // A press inside the wait means the help is not wanted, and must not arrive late.
  const onPress = () => {
    pointerReached = true;
    tooltips.dismiss(handle);
  };
  const onFocus = () => {
    if (!focusWasPlaced() && el.matches(':focus-visible')) tooltips.focus(handle);
  };
  const onBlur = () => tooltips.blur(handle);
  el.addEventListener('pointerleave', onLeave);
  el.addEventListener('pointerdown', onPress);
  el.addEventListener('focus', onFocus);
  el.addEventListener('blur', onBlur);

  return () => {
    stopIntent();
    el.removeEventListener('pointerleave', onLeave);
    el.removeEventListener('pointerdown', onPress);
    el.removeEventListener('focus', onFocus);
    el.removeEventListener('blur', onBlur);
    tooltips.release(handle);
    handle.hide();
    description.remove();
    const rest = (el.getAttribute('aria-describedby') ?? '')
      .split(/\s+/)
      .filter((id) => id && id !== description.id);
    if (rest.length > 0) el.setAttribute('aria-describedby', rest.join(' '));
    else el.removeAttribute('aria-describedby');
  };
}

/**
 * Where tooltip descriptions live: one hidden element at the end of the page, so
 * that a sentence of help never sits in the middle of the text it is about.
 *
 * A control's `aria-describedby` reaches it from anywhere, and what is read as
 * text (a heading's, a table cell's, a test's) is not changed by there being
 * help. The host is hidden from the reading order because a description is only
 * ever read as a description.
 */
export function descriptionHost(): HTMLElement {
  let host = document.getElementById('tip-descriptions');
  if (!host) {
    host = document.createElement('div');
    host.id = 'tip-descriptions';
    host.className = 'sr-only';
    host.setAttribute('aria-hidden', 'true');
    document.body.append(host);
  }
  return host;
}

/** A Svelte action: move a description to the host, and take it away with the component. */
export function hosted(node: HTMLElement) {
  descriptionHost().append(node);
  return {
    destroy() {
      node.remove();
    },
  };
}

/**
 * Hover that means something: wait for the pointer to move over the trigger.
 *
 * When the page changes under a pointer that is resting (a sheet rising where
 * the finger-sized "More" button was, a list re-rendering) the browser fires
 * enter events for whatever is now beneath it, with no pointer move behind
 * them. A real arrival is a pointer move whose target is inside the trigger.
 * The listener is installed before that move, so it still counts when enter
 * arrives after it.
 *
 * Returns the function that stops listening.
 */
export function whenPointerMoves(el: Element, arm: (event: PointerEvent) => void): () => void {
  const moved: EventListener = (event) => arm(event as PointerEvent);
  el.addEventListener('pointermove', moved);
  return () => el.removeEventListener('pointermove', moved);
}

/**
 * Where a tooltip bubble goes, and where its caret points.
 *
 * Pure arithmetic on rectangles, so the rules that make a bubble feel right at
 * the edge of the window (when it flips, how far it is held in, where the
 * caret lands once it has been held) are tested without a browser.
 */

/** The space between a trigger and its bubble, which the caret crosses. */
export const GAP = 8;
/** How close to the window's edge a bubble may come. */
export const MARGIN = 8;
/** How far from either end of the bubble the caret is kept, so it never sits on a corner. */
export const ARROW_INSET = 14;
/** Below this width a `right` bubble has no room beside its trigger and drops below. */
export const NARROW_QUERY = '(max-width: 760px)';

export type Side = 'top' | 'bottom' | 'left' | 'right';

export interface Box {
  left: number;
  top: number;
  right: number;
  bottom: number;
}

export interface Size {
  width: number;
  height: number;
}

export interface Placement {
  /** The side of the trigger the bubble ended up on, after any flip. */
  side: Side;
  /** The bubble's top left corner in the window. */
  left: number;
  top: number;
  /**
   * How far along the bubble's edge facing the trigger the caret sits, from the
   * bubble's own start: the trigger's centre, kept {@link ARROW_INSET} from
   * either end.
   */
  arrow: number;
}

export interface PlaceInput {
  anchor: Box;
  /**
   * A box whose left and right edges stand in for the trigger's, for a side
   * placement. A sidebar entry is inset inside its rail, and a bubble that
   * started at the entry's edge would sit on the rail.
   */
  edge?: Box;
  size: Size;
  viewport: Size;
  preferred: Side;
}

const OPPOSITE: Record<Side, Side> = { top: 'bottom', bottom: 'top', left: 'right', right: 'left' };

/** A `right` preference on a phone: there is no room beside the trigger, so it goes below. */
export function narrowPlacement(preferred: Side, narrow: boolean): Side {
  return narrow && preferred === 'right' ? 'bottom' : preferred;
}

/** `value` held between `lo` and `hi`, with `lo` winning when they cross. */
function hold(value: number, lo: number, hi: number): number {
  return Math.max(lo, Math.min(value, hi));
}

export function place({ anchor, edge, size, viewport, preferred }: PlaceInput): Placement {
  const sideways = preferred === 'left' || preferred === 'right';
  // The edge only replaces the horizontal extent, and only when the bubble is
  // going beside the trigger; above or below it the trigger's own width is
  // what the caret has to find.
  const target: Box = sideways && edge ? { ...anchor, left: edge.left, right: edge.right } : anchor;

  const space: Record<Side, number> = {
    top: target.top,
    bottom: viewport.height - target.bottom,
    left: target.left,
    right: viewport.width - target.right,
  };
  const need = (sideways ? size.width : size.height) + GAP + MARGIN;
  const opposite = OPPOSITE[preferred];
  const side = space[preferred] < need && space[opposite] > space[preferred] ? opposite : preferred;

  const centreX = (anchor.left + anchor.right) / 2;
  const centreY = (anchor.top + anchor.bottom) / 2;

  let x = centreX - size.width / 2;
  let y = centreY - size.height / 2;
  if (side === 'top') y = target.top - size.height - GAP;
  if (side === 'bottom') y = target.bottom + GAP;
  if (side === 'left') x = target.left - size.width - GAP;
  if (side === 'right') x = target.right + GAP;

  const left = hold(x, MARGIN, viewport.width - size.width - MARGIN);
  const top = hold(y, MARGIN, viewport.height - size.height - MARGIN);

  const along = side === 'top' || side === 'bottom';
  const length = along ? size.width : size.height;
  // A bubble too short to keep the inset at both ends puts the caret in the
  // middle rather than letting the two bounds cross.
  const inset = Math.min(ARROW_INSET, length / 2);
  const arrow = hold(along ? centreX - left : centreY - top, inset, length - inset);

  return { side, left, top, arrow };
}

/**
 * When a tooltip shows, and when it goes: one set of rules for every bubble in
 * the product.
 *
 * Each `Tooltip` used to keep its own flags and its own listeners, which is how
 * two of them end up open at once and how a sweep down the sidebar costs a
 * wait per entry. Here there is one controller, so "only one bubble is open"
 * is a property of the code rather than a hope, and the timings are written
 * once.
 *
 * The controller is plain TypeScript with an injectable clock: the numbers are
 * the behaviour, and a test that has to sleep for them is a test nobody runs.
 */
import { layers } from './keys';

/** How long the pointer rests on a trigger before the first bubble shows. */
export const OPEN_DELAY = 250;
/**
 * After a bubble has shown, and while one is open, moving to a neighbour shows
 * its bubble at once for this long. It is what makes a sweep down the sidebar
 * feel instant after the first entry.
 */
export const WARM = 300;
/** How long a bubble outlives the pointer leaving, so the pointer can cross onto it. */
export const GRACE = 100;

/** `none` is the opt-out for things people scrub across, like the matrix squares. */
export type Wait = 'default' | 'none';

/**
 * The wait a rich card takes. They opened the instant the pointer touched them
 * before the shared shell, which made a card flash over anything the pointer
 * crossed on its way elsewhere. Set this to `'none'` to give them that back.
 */
export const RICH_CARD_WAIT: Wait = 'default';

/** What the controller drives. A `Tooltip` instance is one of these. */
export interface Bubble {
  show(): void;
  hide(): void;
}

export interface Clock {
  now(): number;
  setTimeout(fn: () => void, ms: number): unknown;
  clearTimeout(id: unknown): void;
}

export const browserClock: Clock = {
  now: () => Date.now(),
  setTimeout: (fn, ms) => setTimeout(fn, ms),
  clearTimeout: (id) => clearTimeout(id as ReturnType<typeof setTimeout>),
};

interface Holds {
  /** The pointer is on the trigger. */
  hover: boolean;
  /** The pointer is on the bubble. */
  inside: boolean;
  /** Keyboard focus is on the trigger. */
  focus: boolean;
  /**
   * Its owner opened it (a tap, through the bound `open`). It stays until focus
   * leaves or a press puts it away, because a finger lifting is a pointer
   * leaving and must not take it with it.
   */
  pinned: boolean;
  opening: unknown;
  closing: unknown;
}

export interface TooltipController {
  /** The bubble showing now, if any. */
  readonly current: Bubble | null;
  hover(bubble: Bubble, wait?: Wait): void;
  unhover(bubble: Bubble): void;
  bubbleEnter(bubble: Bubble): void;
  bubbleLeave(bubble: Bubble): void;
  focus(bubble: Bubble): void;
  blur(bubble: Bubble): void;
  /** Put one bubble away now, and forget any wait it was in. */
  dismiss(bubble: Bubble): void;
  /** Put whatever is showing away. Returns whether there was anything to put away. */
  dismissCurrent(): boolean;
  /** A bubble its owner opened by itself: it takes the place of whatever was showing. */
  adopt(bubble: Bubble): void;
  /** A bubble its owner closed by itself. */
  forget(bubble: Bubble): void;
  /** A bubble that is going away for good. */
  release(bubble: Bubble): void;
}

export interface ControllerHooks {
  /** Called when the first bubble opens and again when the last one has closed. */
  onActive?: (active: boolean) => void;
}

export function createTooltipController(
  clock: Clock = browserClock,
  hooks: ControllerHooks = {},
): TooltipController {
  let current: Bubble | null = null;
  /** Until when a neighbour of a bubble that has just closed still opens at once. */
  let warmUntil = -Infinity;
  const holds = new Map<Bubble, Holds>();

  function of(bubble: Bubble): Holds {
    let h = holds.get(bubble);
    if (!h) {
      h = {
        hover: false,
        inside: false,
        focus: false,
        pinned: false,
        opening: null,
        closing: null,
      };
      holds.set(bubble, h);
    }
    return h;
  }

  function cancelOpening(bubble: Bubble): void {
    const h = of(bubble);
    if (h.opening !== null) clock.clearTimeout(h.opening);
    h.opening = null;
  }

  function cancelClosing(bubble: Bubble): void {
    const h = of(bubble);
    if (h.closing !== null) clock.clearTimeout(h.closing);
    h.closing = null;
  }

  function isWarm(): boolean {
    return current !== null || clock.now() < warmUntil;
  }

  function setCurrent(next: Bubble | null): void {
    const was = current !== null;
    current = next;
    if (was !== (next !== null)) hooks.onActive?.(next !== null);
  }

  /**
   * Whichever bubble takes over, the other waits are for something the person
   * has moved on from: a pointer that rested on A and a Tab that has since
   * reached B. A's timer must not come round later and put A's help over B.
   */
  function cancelOtherOpenings(except: Bubble): void {
    for (const other of holds.keys()) {
      if (other !== except) cancelOpening(other);
    }
  }

  function open(bubble: Bubble): void {
    cancelOtherOpenings(bubble);
    cancelOpening(bubble);
    cancelClosing(bubble);
    if (current === bubble) return;
    const other = current;
    if (other) {
      cancelClosing(other);
      cancelOpening(other);
      // Hidden before the new one is shown, so there is never a frame with two.
      other.hide();
    }
    setCurrent(bubble);
    bubble.show();
  }

  function close(bubble: Bubble): void {
    cancelOpening(bubble);
    cancelClosing(bubble);
    if (current !== bubble) return;
    warmUntil = clock.now() + WARM;
    of(bubble).pinned = false;
    setCurrent(null);
    bubble.hide();
  }

  function held(h: Holds): boolean {
    return h.hover || h.inside || h.focus || h.pinned;
  }

  /** Close after the grace, unless something is still holding it open. */
  function settle(bubble: Bubble): void {
    const h = of(bubble);
    if (current !== bubble || held(h) || h.closing !== null) return;
    h.closing = clock.setTimeout(() => {
      h.closing = null;
      if (!held(h)) close(bubble);
    }, GRACE);
  }

  return {
    get current() {
      return current;
    },
    hover(bubble, wait = 'default') {
      const h = of(bubble);
      h.hover = true;
      cancelClosing(bubble);
      if (current === bubble) return;
      if (wait === 'none' || isWarm()) {
        open(bubble);
        return;
      }
      cancelOpening(bubble);
      h.opening = clock.setTimeout(() => {
        h.opening = null;
        if (h.hover) open(bubble);
      }, OPEN_DELAY);
    },
    unhover(bubble) {
      of(bubble).hover = false;
      cancelOpening(bubble);
      settle(bubble);
    },
    bubbleEnter(bubble) {
      of(bubble).inside = true;
      cancelClosing(bubble);
    },
    bubbleLeave(bubble) {
      of(bubble).inside = false;
      settle(bubble);
    },
    focus(bubble) {
      of(bubble).focus = true;
      open(bubble);
    },
    blur(bubble) {
      const h = of(bubble);
      h.focus = false;
      h.pinned = false;
      if (h.hover || h.inside) return;
      close(bubble);
    },
    dismiss(bubble) {
      close(bubble);
    },
    dismissCurrent() {
      if (!current) return false;
      close(current);
      return true;
    },
    adopt(bubble) {
      cancelOtherOpenings(bubble);
      cancelOpening(bubble);
      cancelClosing(bubble);
      of(bubble).pinned = true;
      if (current === bubble) return;
      const other = current;
      if (other) {
        cancelClosing(other);
        cancelOpening(other);
        other.hide();
      }
      setCurrent(bubble);
    },
    forget(bubble) {
      cancelOpening(bubble);
      cancelClosing(bubble);
      of(bubble).pinned = false;
      if (current !== bubble) return;
      warmUntil = clock.now() + WARM;
      setCurrent(null);
    },
    release(bubble) {
      cancelOpening(bubble);
      cancelClosing(bubble);
      holds.delete(bubble);
      if (current === bubble) {
        warmUntil = clock.now() + WARM;
        setCurrent(null);
      }
    },
  };
}

/* -- the keyboard, the pointer and the layer stack ----------------------------- */

/**
 * The controller, joined to the parts of the page it has to answer to while a
 * bubble is up.
 *
 * Escape is heard in the capture phase, ahead of the menu or the dialog the
 * bubble is sitting over, and is stopped only when it closed a bubble: a menu
 * item's reason closes first and the next press closes the menu. The listener
 * exists only while a bubble does.
 *
 * The bubble is also on the layer stack, so `layers.closeTop()` agrees with
 * the listener about what Escape closes first. `layers.size` does not count it
 * (see keys.ts), so it never switches a global shortcut off.
 */
export function createAppTooltips(
  clock: Clock = browserClock,
  target: EventTarget | null = typeof document === 'undefined' ? null : document,
): { controller: TooltipController } {
  let layer: number | null = null;
  let detach: (() => void) | null = null;

  const controller: TooltipController = createTooltipController(clock, {
    onActive(active) {
      if (active) {
        layer = layers.push('tooltip', () => void controller.dismissCurrent());
        if (!target) return;
        const onKey = (event: Event) => {
          if ((event as KeyboardEvent).key !== 'Escape') return;
          if (!controller.dismissCurrent()) return;
          event.stopPropagation();
          event.preventDefault();
        };
        // A press anywhere puts the bubble away: on its trigger, on the bubble
        // itself, or somewhere else entirely.
        const onPointer = () => void controller.dismissCurrent();
        target.addEventListener('keydown', onKey, true);
        target.addEventListener('pointerdown', onPointer, true);
        detach = () => {
          target.removeEventListener('keydown', onKey, true);
          target.removeEventListener('pointerdown', onPointer, true);
        };
      } else {
        if (layer !== null) layers.remove(layer);
        layer = null;
        detach?.();
        detach = null;
      }
    },
  });
  return { controller };
}

/** The one controller every `Tooltip` in the page answers to. */
export const tooltips: TooltipController = createAppTooltips().controller;

/**
 * Sizes as a person writes them, and as the page writes them back.
 *
 * Pure, and imported by a unit test. A size field used to be a number box with
 * the unit in its label -- "Memory (MB)" -- so the operator who thinks in
 * gigabytes did the arithmetic, and the one who typed "4g" the way Docker
 * spells it was told nothing at all, because a number box reports anything it
 * cannot read as an empty string. Every size field now reads the spellings
 * people actually use -- 4gb, 4096mb, 4g, 4 GiB, 1.5 -- and, once the value is
 * committed, writes it back in the largest unit that says it exactly, so the
 * field shows what was understood rather than what was typed.
 *
 * A gigabyte here is 1024 megabytes. That is what the rest of the UI means by
 * GB, what Docker means by `4g`, and what a cgroup is given; offering a decimal
 * gigabyte beside it would make "4 GB" mean two different limits on one page.
 */

/**
 * A quantity a field can hold, named by the unit it is carried in: cores,
 * megabytes, gigabytes, a plain count, or a length of time in milliseconds.
 */
export type Quantity = 'cpus' | 'mb' | 'gb' | 'count' | 'ms';

/** What a parse makes of some text: a value, nothing (the field was cleared), or why not. */
export type Parsed = { ok: true; value: number | null } | { ok: false; error: string };

const MB_PER: Record<string, number> = {
  k: 1 / 1024,
  m: 1,
  g: 1024,
  t: 1024 * 1024,
  p: 1024 * 1024 * 1024,
};

/**
 * Reads a byte size into megabytes. A bare number is taken in `bare`, the unit
 * the field is labelled in, so "4096" in a megabyte field stays 4096 MB and "4"
 * in a gigabyte field stays 4 GB.
 */
function parseBytes(text: string, bare: 'mb' | 'gb'): number | undefined {
  const m = /^(\d+(?:\.\d+)?|\.\d+)\s*([kmgtp]?)(?:i?b)?$/i.exec(text);
  if (!m) return undefined;
  const n = Number(m[1]);
  const unit = (m[2] ?? '').toLowerCase();
  if (unit === '') {
    // "4b" would read as four megabytes, which nobody meant.
    if (/b$/i.test(text)) return undefined;
    return bare === 'gb' ? n * 1024 : n;
  }
  return n * (MB_PER[unit] ?? NaN);
}

/**
 * Reads a CPU figure. Cores are the unit, and fractions are allowed: "1.5",
 * "1.5 cores", "2 vCPUs". Millicores are read too, because "1500m" is how
 * anyone who has written a Kubernetes manifest spells one and a half cores.
 */
function parseCpus(text: string): number | undefined {
  const milli = /^(\d+)\s*m$/i.exec(text);
  if (milli) return Number(milli[1]) / 1000;
  const m = /^(\d+(?:\.\d+)?|\.\d+)\s*(?:v?cpus?|cores?|c)?$/i.exec(text);
  return m ? Number(m[1]) : undefined;
}

/** Milliseconds in each unit a duration can be written in, largest first. */
const MS_PER: [string, number][] = [
  ['w', 7 * 24 * 3600 * 1000],
  ['d', 24 * 3600 * 1000],
  ['h', 3600 * 1000],
  ['m', 60 * 1000],
  ['s', 1000],
  ['ms', 1],
];

/** Every spelling of a duration unit, to the short one `MS_PER` names. */
function durationUnit(word: string): string | undefined {
  const w = word.toLowerCase();
  if (w === 'ms' || /^millis(econds?)?$/.test(w)) return 'ms';
  if (/^(s|secs?|seconds?)$/.test(w)) return 's';
  if (/^(m|mins?|minutes?)$/.test(w)) return 'm';
  if (/^(h|hrs?|hours?)$/.test(w)) return 'h';
  if (/^(d|days?)$/.test(w)) return 'd';
  if (/^(w|wks?|weeks?)$/.test(w)) return 'w';
  return undefined;
}

/**
 * Reads a length of time into milliseconds: Go's own spelling ("1h30m",
 * "168h", "500ms"), the one a person says ("7 days", "2 weeks", "90 seconds"),
 * and anything between ("1d 12h", "1.5h"). A bare number is seconds, which is
 * what the one setting that ever took a bare number meant by it.
 */
function parseDuration(text: string): number | undefined {
  if (/^\d+(?:\.\d+)?$/.test(text)) return Number(text) * 1000;
  const part = /(\d+(?:\.\d+)?|\.\d+)\s*([a-z]+)\s*/giy;
  let total = 0;
  let at = 0;
  for (let m = part.exec(text); m; m = part.exec(text)) {
    const unit = durationUnit(m[2] ?? '');
    if (!unit) return undefined;
    total += Number(m[1]) * (MS_PER.find(([u]) => u === unit)?.[1] ?? NaN);
    at = part.lastIndex;
  }
  return at === text.length && at > 0 ? total : undefined;
}

const EXAMPLES: Record<Quantity, string> = {
  cpus: 'a number of cores, such as 2 or 1.5',
  mb: 'a size such as 4 GB, 4096 MB or 4g',
  gb: 'a size such as 40 GB, 1.5 TB or 500g',
  count: 'a whole number, such as 10',
  ms: 'a length of time, such as 30s, 5m, 1h30m or 7d',
};

/**
 * Reads what somebody typed into a size field, in the field's own unit.
 *
 * Megabytes and gigabytes come back whole, because that is what the API
 * carries: "1.5g" in a megabyte field is 1536, and a gigabyte field rounds to
 * the nearest gigabyte. The rounding is visible, because the field then shows
 * the value it kept. CPU keeps two decimal places, finer than any quota a
 * runtime applies.
 */
export function parseQuantity(input: string, quantity: Quantity): Parsed {
  const text = input
    .trim()
    .replace(/[\s_]+/g, ' ')
    .replace(/,/g, '');
  if (text === '') return { ok: true, value: null };
  let value: number | undefined;
  if (quantity === 'cpus') {
    const cpus = parseCpus(text);
    value = cpus === undefined ? undefined : Math.round(cpus * 100) / 100;
  } else if (quantity === 'count') {
    value = /^\d+$/.test(text) ? Number(text) : undefined;
  } else if (quantity === 'ms') {
    const ms = parseDuration(text);
    value = ms === undefined ? undefined : Math.round(ms);
  } else {
    const mb = parseBytes(text, quantity);
    if (mb !== undefined) value = quantity === 'gb' ? Math.round(mb / 1024) : Math.round(mb);
  }
  if (value === undefined || !Number.isFinite(value) || value < 0) {
    return { ok: false, error: `Write ${EXAMPLES[quantity]}.` };
  }
  return { ok: true, value };
}

const BYTE_UNITS = ['MB', 'GB', 'TB', 'PB'] as const;

/**
 * Writes a size in the largest unit that says it exactly, to two decimal
 * places: 4096 MB is "4 GB", 1536 MB is "1.5 GB", and 3000 MB stays "3000 MB",
 * because "2.93 GB" would be a different limit from the one that is set.
 */
export function formatQuantity(value: number, quantity: Quantity): string {
  if (!Number.isFinite(value)) return '';
  if (quantity === 'cpus') return `${trim(value)} ${value === 1 ? 'core' : 'cores'}`;
  if (quantity === 'count') return String(value);
  if (quantity === 'ms') return formatDuration(value);
  let at = quantity === 'gb' ? 1 : 0;
  let n = value;
  while (at < BYTE_UNITS.length - 1 && n >= 1024 && exact(n / 1024)) {
    n /= 1024;
    at++;
  }
  return `${trim(n)} ${BYTE_UNITS[at]}`;
}

/** Whether a figure survives being written to two decimal places. */
function exact(n: number): boolean {
  return Math.abs(Math.round(n * 100) - n * 100) < 1e-6;
}

function trim(n: number): string {
  return String(Math.round(n * 100) / 100);
}

/**
 * Writes a length of time in the largest units that say it exactly, largest
 * first: 3600000 is "1h", 5400000 is "1h 30m", 604800000 is "7d". Weeks are
 * read but not written, because "30d" says a retention period plainly and
 * "4w 2d" does not.
 */
export function formatDuration(ms: number): string {
  if (!Number.isFinite(ms)) return '';
  if (ms === 0) return '0s';
  let left = Math.round(ms);
  const parts: string[] = [];
  for (const [unit, size] of MS_PER) {
    if (unit === 'w') continue;
    const n = Math.floor(left / size);
    if (n > 0) {
      parts.push(`${n}${unit}`);
      left -= n * size;
    }
  }
  return parts.join(' ');
}

/**
 * The same length of time in Go's spelling, which is what the controller's
 * settings API reads: days become hours, because Go has no day.
 */
export function goDuration(ms: number): string {
  let left = Math.round(ms);
  if (left === 0) return '0s';
  const out: string[] = [];
  for (const [unit, size] of [
    ['h', 3600 * 1000],
    ['m', 60 * 1000],
    ['s', 1000],
    ['ms', 1],
  ] as const) {
    const n = Math.floor(left / size);
    if (n > 0) {
      out.push(`${n}${unit}`);
      left -= n * size;
    }
  }
  return out.join('');
}

/**
 * What the Updates page says, as functions of what the API answered.
 *
 * When auto would take a release is in the conditional, because whether it
 * does is the planner's to say (a missing helper or a halted rollout holds it),
 * and that sentence is shown beside the line. What each mode does is described
 * as it is. An update a person has asked for is in the present,
 * and only as far as the controller has said so: a sentence that an update
 * worked is written from an attempt the controller closed as succeeded, or from
 * a build it reports running the release, and never from a request having been
 * accepted. The controller's own sentence for each state travels with the status
 * and is shown as it was given; these are the lines around it, kept out of the
 * components so that they are tested once and read the same wherever they appear.
 */
import type { Host, Role, UpdatesStatus } from '../api/types';
import { describeWindow, parseGoDuration, pluralise, toMillis } from '../format';
import { shellQuote } from '../hosts/terminal';
import type { RestartCopy } from '../settings/restart-copy';

export type UpdateMode = UpdatesStatus['mode'];
/** The controller's latest update attempt, open or ended. */
export type ControllerAttempt = NonNullable<UpdatesStatus['controller']>;

const HOUR = 3_600_000;
const MINUTE = 60_000;

const MODE_LABELS: Record<UpdateMode, string> = { off: 'Off', manual: 'Manual', auto: 'Auto' };

/** The setting's own word for the mode, capitalised for a badge. */
export function modeLabel(mode: UpdateMode): string {
  return MODE_LABELS[mode];
}

const MODE_SENTENCES: Record<UpdateMode, string> = {
  off: 'Zoomies tells you when a newer release exists and does nothing about it. Updating stays a command you run yourself.',
  manual:
    'Zoomies offers the newest release that can be installed on this system, with an Update button for this controller and for each host whose update helper is installed, and one on the Hosts page that updates every host behind this controller, one at a time. Nothing moves until someone presses one.',
  // The cost is part of the choice: a release replaced inside the soak is never
  // taken, so a project that publishes faster than the soak is never updated by
  // auto, and an operator is told so before they depend on it. So is what stops
  // it, because a halted rollout waits for a person and somebody has to know to
  // look.
  auto: 'Zoomies takes the newest release that can be installed on this system once it has been public for the soak: it updates this controller through its update helper, then every host behind the controller, one at a time. A newer release restarts the wait, so if releases are published faster than the soak, auto never takes one. A host whose update fails halts the rollout until an administrator resumes or cancels it.',
};

/** What the mode would do, and what it costs, in the words the choice is made by. */
export function describeMode(mode: UpdateMode): string {
  return MODE_SENTENCES[mode];
}

/**
 * A length of time as the controller's own sentences say it: whole hours from
 * an hour up, whole minutes below that. It rounds down, as they do, because the
 * line this feeds sits beside one of theirs and two different times for one
 * release is worse than either being a little short.
 */
function spanText(ms: number): string {
  if (ms >= HOUR) return pluralise(Math.floor(ms / HOUR), 'hour');
  if (ms >= MINUTE) return pluralise(Math.floor(ms / MINUTE), 'minute');
  return 'less than a minute';
}

/**
 * What the mode would do about the release, in one line, or nothing when there
 * is nothing to take. Only a release ahead of the build is something to take;
 * why there is not one is the controller's sentence, shown beside this.
 *
 * `now` is a parameter so the line can be tried at the second it changes. The
 * page passes none: the line is worked out when a status arrives, which is when
 * the controller's sentence beside it was, so the two count from the same moment.
 */
export function targetLine(
  status: Pick<UpdatesStatus, 'mode' | 'target'>,
  now: number = Date.now(),
): string {
  const { mode, target } = status;
  if (mode === 'off' || !target?.newer) return '';
  if (mode === 'manual') return `Manual offers ${target.tag} and waits for a person to take it.`;
  // A due time that cannot be read leaves the line without one rather than
  // with a date that is not a date.
  const due = toMillis(target.due_at);
  if (due === null) return `Auto would take ${target.tag}.`;
  if (due <= now) return `Auto would take ${target.tag} now.`;
  return `Auto would take ${target.tag} in ${spanText(due - now)}.`;
}

export interface UpdateState {
  label: string;
  /** Never a status colour: nothing is wrong when a release is waiting, and those are the fleet's. */
  tone: 'neutral' | 'accent';
}

/**
 * The state the status is in, as one word. They are the words the controller
 * opens its own sentences with, so the badge and the sentence under it agree.
 */
export function updateState(status: UpdatesStatus, now: number = Date.now()): UpdateState {
  if (status.mode === 'off') return { label: 'Off', tone: 'neutral' };
  if (status.checked_at === null) return { label: 'Not read yet', tone: 'neutral' };
  const { target } = status;
  if (target === null) return { label: 'Nothing to take', tone: 'neutral' };
  if (!target.newer) return { label: 'Nothing newer', tone: 'neutral' };
  if (status.mode === 'manual') return { label: 'Available', tone: 'accent' };
  const due = toMillis(target.due_at);
  if (due === null) return { label: 'Available', tone: 'accent' };
  return { label: due > now ? 'Waiting' : 'Ready', tone: 'accent' };
}

/** The soak as a period, and zero as what it means: auto does not wait. */
export function soakText(soak: string): string {
  if (parseGoDuration(soak) === 0) return 'No wait';
  // Whatever this page cannot read is shown as it came rather than dropped.
  return describeWindow(soak) || soak;
}

/** Who the soak applies to, since it is shown in every mode. */
export function soakNote(mode: UpdateMode): string {
  return mode === 'auto'
    ? 'Counted from the day GitHub published the release.'
    : 'Only auto waits; manual and off ignore it.';
}

/** What the build says about where it came from. */
export function buildText(release: boolean): string {
  return release
    ? 'From a release'
    : 'Not from a release, so an update moves it onto the newest release';
}

/** A main-branch comparison is not proof that a dev image has finished publishing. */
export function developmentStatus(dev: NonNullable<UpdatesStatus['development']>): string {
  if (dev.state === 'current') return 'This dev build matches the latest checked commit on main.';
  if (dev.state === 'available')
    return 'Newer changes are on main. The dev build may still be publishing; check the installed commit after upgrading.';
  return 'The latest dev build has not been confirmed. Check for updates before choosing a build.';
}

/**
 * Said when an update failed but the engine put the previous release back: the
 * host is on what it ran, which is a different thing to tell an operator from a
 * failure left in place.
 */
export function rollbackNote(rolledBack: boolean): string {
  return rolledBack
    ? 'The new release did not answer, so the previous release was put back and is running again.'
    : '';
}

/**
 * The restore command for the copy an upgrade took, or empty when none was.
 *
 * The directory is a path an operator configured, so it is quoted for a shell:
 * this is text a person is told to run, and a path with a space or a shell
 * character would otherwise be read as more than one argument.
 */
export function restoreCommand(backup: string): string {
  return backup ? `zoomies restore ${shellQuote(backup)} --replace` : '';
}

/**
 * Whether this build holds a release's checksums to a signature, and by which
 * keys. No keys is a build from before a key was committed, which takes a
 * release's checksums on trust rather than holding them to a signature.
 */
export function signingLine(keys: string[]): string {
  if (keys.length === 0) {
    return "No release key is built in, so a release's checksums are taken on trust.";
  }
  if (keys.length === 1) {
    return `Releases are verified with key ${keys[0]}.`;
  }
  return `Releases are verified with ${keys.length} keys: ${keys.join(', ')}.`;
}

/**
 * The address to link a release to, or null to show its tag as plain text.
 *
 * The address is GitHub's `html_url`, which is text that came off the network
 * and is going into an `href`. Only a web page over TLS is plainly one; a
 * `javascript:` or `data:` address would run in this origin, and a plain `http:`
 * one is a link that can be rewritten on the way.
 */
export function releaseHref(url: string | null | undefined): string | null {
  return typeof url === 'string' && url.startsWith('https://') ? url : null;
}

/**
 * Where the mode is changed, for a reader who can see it there, or null.
 *
 * `updates.mode` and `updates.soak` are platform-scoped, and the settings list
 * leaves out a platform row for anyone below that role, so a link offered to an
 * administrator lands on a Configuration page that does not show the setting.
 */
export function modeSettingHref(can: (needed: Role) => boolean): string | null {
  return can('platform') ? '/settings/configuration?setting=updates.mode' : null;
}

/* -- updating the controller ---------------------------------------------- */

/** Release binaries report 1.3.5 where the tag is v1.3.5, so the two are compared without the v. */
function bare(version: string): string {
  return version.trim().replace(/^v/, '');
}

/** Whether the build the controller reports is the release the attempt asked for. */
export function runsRelease(running: string, tag: string): boolean {
  return bare(running) !== '' && bare(running) === bare(tag);
}

/**
 * Where to look when an update did not end well. Both are on the controller's
 * host, and neither names a path, so every role may be told.
 */
export const HELPER_LOOK_AT =
  "Look at zoomies updates helper status, and at the journal of the unit zoomies-update (journalctl -u zoomies-update), on the controller's host.";

export interface AttemptWords {
  /** One word for the badge. */
  label: string;
  /** Never a status colour except for an update that did not work, which is what danger is for. */
  tone: 'neutral' | 'accent' | 'danger';
  title: string;
  detail: string;
  /** Still in flight: the page keeps watching and says nothing final. */
  open: boolean;
  /** Where to look when it did not end well, or empty. */
  lookAt: string;
}

/**
 * The controller's latest attempt, in words.
 *
 * `running` is the build the controller reports now. An attempt still open
 * while the controller already runs the release it asked for is shown as done:
 * the new process records the ending a moment after it starts, and for that
 * moment the status already says what happened. That is the controller's word,
 * not this page's guess. An open attempt with the old build running is never
 * shown as done, however long the page has waited.
 */
export function attemptWords(attempt: ControllerAttempt, running: string): AttemptWords {
  const { to, from } = attempt;
  const arrived = runsRelease(running, to);
  const state = attempt.state === 'requested' && arrived ? 'succeeded' : attempt.state;
  // Which build the controller runs, said without "still" once it is the target:
  // an attempt that ended without the update can be read after somebody upgraded
  // by hand, and "still" is a claim about the build it left.
  const runs = arrived
    ? `This controller runs ${running} now.`
    : `This controller still runs ${running}.`;
  switch (state) {
    case 'requested':
      return {
        label: 'In progress',
        tone: 'accent',
        title: `Updating to ${to}`,
        detail:
          `The update from ${from} was asked for. The update helper on the controller's host installs ${to} and the controller restarts. ` +
          'This page says how it ended when the controller does, and not before.',
        open: true,
        lookAt: '',
      };
    case 'succeeded':
      return {
        label: 'Updated',
        tone: 'accent',
        title: `Updated to ${to}`,
        detail: `This controller was on ${from} and runs ${running} now.`,
        open: false,
        lookAt: '',
      };
    case 'timed_out':
      return {
        label: 'Timed out',
        tone: 'danger',
        title: `The update to ${to} timed out`,
        detail: arrived
          ? `No answer came from the update helper within 90 minutes. ${runs}`
          : `No answer came from the update helper within 90 minutes, and this controller still runs ${running}.`,
        open: false,
        lookAt: HELPER_LOOK_AT,
      };
    case 'cancelled':
      return {
        label: 'Cancelled',
        tone: 'neutral',
        title: `The update to ${to} was cancelled`,
        detail: runs,
        open: false,
        lookAt: '',
      };
    default:
      return {
        label: 'Failed',
        tone: 'danger',
        title: `The update to ${to} did not succeed`,
        detail: runs,
        open: false,
        lookAt: HELPER_LOOK_AT,
      };
  }
}

/** Whether an attempt is one the page is waiting on, read the way `attemptWords` reads it. */
export function attemptIsOpen(attempt: ControllerAttempt | null, running: string): boolean {
  return attempt !== null && attemptWords(attempt, running).open;
}

export type UpdateOffer =
  /** The button is offered, for this release. */
  | { kind: 'offer'; tag: string }
  /** An attempt is open, so the progress is shown in place of the button. */
  | { kind: 'in-flight' }
  /**
   * No button, and the sentence says why. At most one command comes with it: the
   * install where the helper is missing, or the upgrade by hand where it can
   * never be installed.
   */
  | { kind: 'none'; sentence: string; installCommand: string; upgradeCommand: string };

/**
 * Whether the controller can be updated from this page, by this reader, and if
 * not, why not in the words of the first thing in the way.
 *
 * The order is the order an operator would fix them in: who you are, whether
 * updating is on, whether this build is one that updates, whether the helper is
 * there (or can never be), and last whether there is anything to take.
 */
export function controllerOffer(status: UpdatesStatus, canPlatform: boolean): UpdateOffer {
  if (attemptIsOpen(status.controller, status.running.version)) return { kind: 'in-flight' };
  const none = (sentence: string, installCommand = '', upgradeCommand = ''): UpdateOffer => ({
    kind: 'none',
    sentence,
    installCommand,
    upgradeCommand,
  });
  if (!canPlatform) return none('Updating the controller needs the platform role.');
  if (status.mode === 'off')
    return none('Updating is off. Set updates.mode to manual or auto to update from here.');
  // A helper that can never be installed is never offered the command that
  // installs one, whatever arrived beside it: that command would only refuse.
  if (status.helper.state === 'unsupported')
    return none(status.helper.reason, '', status.helper.upgrade_command);
  if (status.helper.state !== 'ready')
    return none(status.helper.reason, status.helper.install_command);
  const target = status.target;
  if (!target?.newer)
    return none('No newer release is on offer, so there is nothing to update to.');
  return { kind: 'offer', tag: target.tag };
}

/**
 * What the confirmation says before the controller is updated.
 *
 * The last line is as true as the code that makes the copy: the store copies the
 * database before it applies a migration, and only when one is pending, so a
 * release that changes nothing there takes none.
 */
export function confirmControllerUpdate(
  tag: string,
  running: string,
  release = true,
  rollback = false,
): {
  title: string;
  description: string;
  consequences: readonly string[];
  confirmLabel: string;
} {
  return {
    title: 'Update the controller',
    description: `Update this controller from ${running} to ${tag}?`,
    consequences: [
      ...(tag === 'dev'
        ? [
            'DEV installs the latest development build from main. It may contain untested changes and is a moving channel.',
          ]
        : release
          ? []
          : [
              'This build is not from a release. A build from main is usually ahead of the newest release, so this may take the controller back to older code.',
            ]),
      'The controller restarts. This page loses its connection for a short while and finds it again by itself.',
      'Jobs that are running keep running.',
      'A verified copy of the database is taken before anything changes. If the update fails, this page names the copy and the command that restores it.',
      ...(rollback
        ? [
            'If the controller does not come back, and the release changed nothing in the database, the previous release is put back automatically.',
          ]
        : []),
    ],
    confirmLabel: `Update to ${tag}`,
  };
}

/** What the restart state says while the controller is stopped and started again by an update. */
export const UPDATE_RESTART: RestartCopy = {
  titles: {
    stopping: 'Waiting for the controller to restart',
    starting: 'Waiting for the controller to answer',
    back: 'The controller is answering again',
    'stuck-up': 'The controller has not stopped',
    'stuck-down': 'The controller has not come back yet',
  },
  stopping: 'The update helper is replacing the controller. This page waits for the restart.',
  starting:
    'This page has lost its connection to the controller, which is what the restart of an update looks like. It finds the controller again by itself. Jobs that are running keep running.',
  back: 'Reloading, to read how the update ended.',
  stuckUp: () => 'The controller is still answering.',
  stuckDown: (seconds) =>
    `The controller has not answered in ${pluralise(Math.round(seconds / 60), 'minute')}. ` +
    'It serves nothing while it migrates its database, which on a large one can take minutes, so it may still be starting. ' +
    `The update stays open until the controller says how it ended, and a build that fails to start is not rolled back for you. ${HELPER_LOOK_AT}`,
  command: 'zoomies updates helper status',
};

/* -- updating the hosts ----------------------------------------------------- */

/** The open rollout, or the last one that ended. */
export type Rollout = NonNullable<UpdatesStatus['rollout']>;

/** What the hosts action reads of a host: its own update block, as its card does. */
export type RolloutHost = Pick<Host, 'embedded' | 'version_skew' | 'update'>;

export interface RolloutWords {
  /** One word for the badge. */
  label: string;
  /**
   * A status colour only where the mapping gives one: halted is held until an
   * operator acts, which is draining, and done is idle. A running rollout is
   * news, as an update in flight is, and a cancelled one is a fact.
   */
  tone: 'accent' | 'draining' | 'idle' | 'neutral';
  title: string;
  /** How many hosts it has updated, of how many. */
  progress: string;
  /** The host being updated now, or the controller's sentence for the halt, or empty. */
  detail: string;
  /** What Resume and Cancel each do, for a halted rollout; empty otherwise. */
  next: string;
  /** Running or halted: Cancel is offered. */
  open: boolean;
  /** Halted: Resume is offered. */
  canResume: boolean;
  /** What the polite region says. */
  live: string;
}

/**
 * The rollout, in words. Only the controller's figures and sentences are used:
 * which host is next, and why, is the planner's, and the status shows its
 * sentence beside this rather than this page guessing at it.
 */
export function rolloutWords(rollout: Rollout): RolloutWords {
  const { target, done, total } = rollout;
  const progress = `${done} of ${pluralise(total, 'host')} updated.`;
  const words = (
    over: Pick<RolloutWords, 'label' | 'tone' | 'title'> & Partial<RolloutWords>,
  ): RolloutWords => {
    const all: RolloutWords = {
      progress,
      detail: '',
      next: '',
      open: false,
      canResume: false,
      live: '',
      ...over,
    };
    all.live = `${all.title}. ${progress}${all.detail ? ` ${all.detail}` : ''}`;
    return all;
  };
  switch (rollout.state) {
    case 'running':
      return words({
        label: 'Rolling out',
        tone: 'accent',
        title: `Updating hosts to ${target}`,
        detail: rollout.current ? `${rollout.current} is being updated now.` : '',
        open: true,
      });
    case 'halted':
      // What each button does is the API's own account of it: the failure stays
      // on that host's attempt, and an update already handed over finishes.
      return words({
        label: 'Halted',
        tone: 'draining',
        title: `The rollout to ${target} is halted`,
        detail:
          rollout.halted_reason ||
          "A host's update did not succeed, so nothing more is updated until an administrator acts.",
        next:
          'Resume goes on to the next host, and the one that failed waits out its retry. ' +
          'Cancel stops the rollout; an update a host has already been handed finishes by itself.',
        open: true,
        canResume: true,
      });
    case 'done':
      return words({ label: 'Done', tone: 'idle', title: `The rollout to ${target} is done` });
    default:
      return words({
        label: 'Cancelled',
        tone: 'neutral',
        title: `The rollout to ${target} was cancelled`,
      });
  }
}

/** Whether a rollout is still moving or waiting for a person. */
export function rolloutIsOpen(rollout: Rollout | null | undefined): boolean {
  return rollout?.state === 'running' || rollout?.state === 'halted';
}

export type RolloutOffer =
  /** "Update N hosts", for the release the controller runs. */
  | { kind: 'offer'; count: number; tag: string }
  /** Drawn and not pressable, with the reason beside it, as a host card is with the mode off. */
  | { kind: 'off'; sentence: string }
  | { kind: 'none' };

/**
 * Whether an administrator is offered to update every host that is behind.
 *
 * The count is the hosts whose own update block says they can be asked now,
 * the answer each card's button is drawn from, so the page never works out
 * eligibility for itself. With the mode off no block says so, and the action is
 * drawn disabled while any host is behind, which is the card's fact too.
 */
export function rolloutOffer(
  status: UpdatesStatus | null,
  hosts: readonly RolloutHost[],
  canAdmin: boolean,
): RolloutOffer {
  if (!canAdmin || !status || rolloutIsOpen(status.rollout)) return { kind: 'none' };
  if (status.mode === 'off') {
    return hosts.some((h) => h.version_skew === 'behind' && !h.embedded)
      ? {
          kind: 'off',
          sentence:
            'Updating is off. Set updates.mode to manual or auto to update hosts from here.',
        }
      : { kind: 'none' };
  }
  const count = hosts.filter((h) => h.update?.can_update === true).length;
  const tag = bare(status.running.version);
  if (count === 0 || tag === '') return { kind: 'none' };
  return { kind: 'offer', count, tag: `v${tag}` };
}

/**
 * What the confirmation says before every host behind is updated.
 *
 * Each line is as true as the code behind it. The planner asks one host at a
 * time and waits for it to report the release; the agent's restart does not
 * wait for its jobs, which keep running and are taken over, so it is not said
 * to; the first failure halts the rollout; and a host that has failed twice on
 * this release is counted in the button but passed over by the planner.
 */
export function confirmRollout(
  tag: string,
  count: number,
): {
  title: string;
  description: string;
  consequences: readonly string[];
  confirmLabel: string;
} {
  const hosts = pluralise(count, 'host');
  return {
    title: `Update ${hosts}`,
    description: `Update ${hosts} to ${tag}, one at a time?`,
    consequences: [
      `The host running the fewest jobs goes first, and each waits until the one before it reports ${tag}.`,
      'Each host’s agent restarts when its turn comes. Jobs that are running keep running: their runners stay in place and the new agent takes them over. The restart does not wait for them to finish.',
      'If one host’s update fails or times out, the rollout halts, and nothing more is updated until an administrator resumes or cancels it.',
      `A host whose update to ${tag} has already failed twice is skipped, and left for a person to update.`,
    ],
    confirmLabel: `Update ${hosts}`,
  };
}

/**
 * Entry point. Mounts the shell and nothing else -- every decision about what
 * to render lives in App.svelte, so the boot sequence is readable in one file.
 */
import { mount } from 'svelte';
import './app.css';
import App from './App.svelte';

const target = document.getElementById('app');
if (!target) {
  throw new Error('The #app element is missing from index.html; the UI cannot mount.');
}

export default mount(App, { target });

/**
 * Entry point for /status, the page for readers with no account.
 *
 * Its own Vite entry rather than a route of the app, so it pulls in the
 * tokens and this one component and nothing else: no app shell, no router, no
 * event stream. vite.config.ts holds it to its own, much smaller, budget.
 */
import { mount } from 'svelte';
import '../lib/styles/tokens.css';
import StatusPage from './StatusPage.svelte';

// Dark is the default and status.html already carries it, so it is there for
// the first paint and for a browser that will not let this page read its
// storage. All that is left to do is undo it for a reader who chose otherwise:
// System takes the attribute away, which hands the choice back to tokens.css
// and the operating system, and Light pins the other palette. It is done here
// rather than inline in status.html because the page's CSP carries no hash for
// an inline script of its own.
try {
  const theme = localStorage.getItem('zoomies.theme');
  if (theme === 'system') document.documentElement.removeAttribute('data-theme');
  else if (theme === 'light') document.documentElement.setAttribute('data-theme', 'light');
} catch {
  /* storage cannot be read: the dark in status.html stands, as it does in the app */
}

const target = document.getElementById('status');
if (!target) {
  throw new Error('The #status element is missing from status.html; the page cannot mount.');
}

export default mount(StatusPage, { target });

/**
 * How the status page says what GET /api/v1/status returns.
 *
 * Kept apart from the component, and free of imports, so the unit tests can
 * hold it and so the page's own entry stays a few kilobytes: it is the one
 * page in the build that people with no account load, often on a phone.
 */
import type { components } from '../lib/api/schema';

export type FleetStatus = components['schemas']['FleetStatus'];
export type FleetState = FleetStatus['state'];
export type CountBand = components['schemas']['CountBand'];

/**
 * The three states on the fixed status mapping in docs/ui-guidelines.md:
 * blocked is danger, degraded is pending, healthy is idle. They are the tones
 * an operator already reads on every other page, and each carries the shape
 * that goes with it, so colour is never the only thing saying which.
 */
export const STATE_PRESENTATION: Record<
  FleetState,
  { tone: 'danger' | 'pending' | 'idle'; shape: 'triangle' | 'dashed' | 'hollow'; headline: string }
> = {
  healthy: { tone: 'idle', shape: 'hollow', headline: 'The fleet is running normally' },
  degraded: {
    tone: 'pending',
    shape: 'dashed',
    headline: 'The fleet is running, with problems that may slow jobs down',
  },
  blocked: {
    tone: 'danger',
    shape: 'triangle',
    headline: 'Some jobs cannot run until the fleet’s operators act',
  },
};

const BAND_WORDS: Record<CountBand, string> = {
  none: 'none',
  few: 'a few',
  many: 'many',
  backed_up: 'backed up',
};

/** A band as a reader would say it. */
export function bandWords(band: CountBand): string {
  return BAND_WORDS[band] ?? band;
}

/** A wait in whole minutes, said the way a person would. */
export function waitWords(minutes: number): string {
  if (minutes <= 0) return 'under a minute';
  if (minutes === 1) return 'about a minute';
  if (minutes < 60) return `about ${minutes} minutes`;
  const hours = Math.round(minutes / 60);
  return hours === 1 ? 'about an hour' : `about ${hours} hours`;
}

/** How long ago an instant was, coarsely: the page refreshes every thirty seconds. */
export function sinceWords(iso: string | undefined, now: Date): string {
  if (!iso) return '';
  const then = Date.parse(iso);
  if (Number.isNaN(then)) return '';
  const minutes = Math.max(0, Math.floor((now.getTime() - then) / 60_000));
  if (minutes < 1) return 'just now';
  if (minutes < 60) return minutes === 1 ? '1 minute ago' : `${minutes} minutes ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 48) return hours === 1 ? '1 hour ago' : `${hours} hours ago`;
  return `${Math.floor(hours / 24)} days ago`;
}

/** How often the page asks again. Thirty seconds, as docs/ui.md promises. */
export const POLL_MS = 30_000;

import { vitePreprocess } from '@sveltejs/vite-plugin-svelte';

export default {
  preprocess: vitePreprocess(),
  compilerOptions: {
    // Runes mode everywhere. This is a Svelte 5 codebase; the legacy reactive
    // syntax is not used and should not compile.
    runes: true,
  },
};

/**
 * The accessibility checklist from docs/ui-guidelines.md section 6, as tests.
 *
 * These are the parts of that list a machine can check honestly: the landmark
 * structure a screen-reader user navigates by, an accessible name on every
 * control, alternative text or an explicit exemption on every image, a skip
 * link that really is the first thing in the tab order, a dialog that keeps
 * focus and gives it back, and no positive tabindex anywhere -- the one
 * mistake that quietly reorders the whole page for keyboard users.
 *
 * They run in both projects. A phone is not a different accessibility
 * standard.
 */
import { expect, test, type Page } from '@playwright/test';
import { FIXTURE, focusIsInMain, goto, isFocused, shiftTabTo } from './support/fixtures';
import { mockRepairWorld, REPAIR_PAGES } from './support/repairs';

// Every page in the navigation. It used to be four of the ten, which meant the
// audit of "every button has an accessible name" was an audit of the four
// pages least likely to be missing one.
const PAGES = [
  { path: '/', heading: 'Overview' },
  { path: '/pools', heading: 'Pools' },
  { path: '/runners', heading: 'Runners' },
  { path: '/workflows', heading: 'Workflows' },
  // Not in the navigation any more, and audited for that reason: it is the
  // page every link that names a job lands on.
  { path: '/jobs', heading: 'Jobs' },
  // The Queue puts four buttons on every row rather than a menu, which is four
  // times as many controls to get the name of right.
  { path: '/queue', heading: 'Queue' },
  { path: '/usage', heading: 'Usage' },
  { path: '/hosts', heading: 'Hosts' },
  { path: '/providers', heading: 'Providers' },
  // The three journey pages. They are not in the navigation, which is exactly
  // why they were missed: an operator setting a fleet up for the first time
  // spends more time on these than on anything in the sidebar, and every
  // control on them is one they have never seen before.
  { path: '/hosts/new', heading: 'Add a host' },
  { path: '/pools/new', heading: 'Create a pool' },
  { path: '/providers/new', heading: 'Add a provider' },
  // The two pages an operator reaches from a card rather than from the
  // navigation, and the pair a machine that is taking too long is diagnosed
  // from. Both are named after a fixture row, because a detail page with
  // nothing behind it is an error state rather than the page.
  { path: `/providers/${FIXTURE.providerId}`, heading: FIXTURE.provider },
  { path: `/machines/${FIXTURE.readyMachineId}`, heading: FIXTURE.readyMachine },
  // The page with a conversation on it: a log that scrolls, a box that grows, and
  // buttons that are only icons.
  { path: '/settings/assistant', heading: 'Eli AI Assistant' },
  { path: '/installations', heading: 'Installations' },
  { path: '/migrate', heading: 'Migrate repositories' },
  // Kennel Club is off in the fixture fleet, so these are the pages somebody
  // meets first: the one that explains itself, and the list that says why it is
  // empty. kennel.spec.ts audits what they show once it is on.
  { path: '/kennel', heading: 'Kennel Club' },
  { path: '/kennel/repositories', heading: 'Repositories' },
  { path: '/audit', heading: 'Audit' },
  // Three of the settings pages: the one with a table and a row menu, the one
  // with the most controls on it, and the one that is nothing but switches --
  // each of which has to name itself without the label beside it.
  { path: '/settings/users', heading: 'Users' },
  { path: '/settings/configuration', heading: 'Configuration' },
  { path: '/settings/events', heading: 'Events' },
  // Facts and sentences rather than controls, read from a status the controller
  // works out; on this fixture the mode is off, which is the state an operator
  // meets first. updates.spec.ts audits it once there is a release on offer.
  { path: '/settings/updates', heading: 'Updates' },
] as const;

/** The pages whose main content is a grid of rows to wait for. */
const GRID_PAGES = new Set(['/pools', '/runners', '/workflows', '/jobs', '/queue', '/audit']);

/**
 * Let the page finish rendering before auditing it.
 *
 * A grid page paints a skeleton first, so counting controls too early counts
 * the wrong page. Waiting for a real row is the honest signal.
 */
async function settle(page: Page, path: string): Promise<void> {
  await expect(page.getByRole('main')).toBeVisible();
  if (path === '/') {
    await expect(page.getByRole('region', { name: 'Recent events' })).toBeVisible();
    return;
  }
  if (GRID_PAGES.has(path)) {
    await expect(page.locator('tbody tr[data-row]').first()).toBeVisible();
    return;
  }
  // The rest settle on their own heading: a page with nothing seeded behind it
  // shows an empty state, which is a finished page and worth auditing too.
  await expect(page.getByRole('heading', { level: 1 })).toBeVisible();
}

for (const { path, heading } of PAGES) {
  test(`${heading} has one h1 and the landmarks to navigate by`, async ({ page }) => {
    await goto(page, path, heading);
    await settle(page, path);

    await expect(page.getByRole('heading', { level: 1 })).toHaveCount(1);
    await expect(page.getByRole('main')).toHaveCount(1);
    // At least one navigation landmark, and the sections one is named so it
    // can be told apart from the grid's pagination.
    expect(await page.getByRole('navigation').count()).toBeGreaterThanOrEqual(1);
    await expect(page.getByRole('navigation', { name: 'Sections', exact: true })).toHaveCount(1);
  });
}

test('every button and link has an accessible name', async ({ page }) => {
  // This audit deliberately visits every route. On a loaded CI runner that is
  // valid work for more than the ordinary single-page 30 second budget.
  test.slow();

  // This one caught a real bug on the phone: the bottom bar hid each entry's
  // label with `display: none`, which took its accessible name with it, and a
  // screen reader announced eight links called "link". The bar shows its four
  // labels outright now, and the collapsed desktop sidebar hides its own off
  // screen rather than removing them -- so both projects assert the same
  // thing.

  // `getByRole` uses the browser's own name computation and skips anything
  // hidden from the accessibility tree, so this is the real question rather
  // than a guess at aria-label attributes.
  for (const { path, heading } of PAGES) {
    await goto(page, path, heading);
    await settle(page, path);

    // An element with no accessible name has the empty one, so this asks for
    // exactly the offenders rather than comparing two counts taken at two
    // different moments.
    await expect(
      page.getByRole('button', { name: /^$/ }),
      `${path}: every button has an accessible name`,
    ).toHaveCount(0);
    await expect(
      page.getByRole('link', { name: /^$/ }),
      `${path}: every link has an accessible name`,
    ).toHaveCount(0);
  }
});

/*
 * A segmented option is named for the label it shows, and described after it.
 * Both halves have been got wrong in turn: a name that was the description
 * alone left the button reading "1m" with nothing by that name to ask for, and
 * a description that opened with the label again had a screen reader saying
 * "Rows -- Rows: the table". Voice control asks for what it can see, so the
 * label leads and is said once.
 */
test('a segmented option is asked for by the label it shows', async ({ page }) => {
  test.slow();

  let audited = 0;
  for (const { path, heading } of PAGES) {
    await goto(page, path, heading);
    await settle(page, path);

    // Nothing in the accessibility tree marks a choice as segmented, so the
    // group is reached structurally; the names it is judged on are the
    // rendered ones.
    const seen = await page.locator('.segmented button').evaluateAll((buttons) =>
      buttons.map((button) => ({
        label: (button.textContent ?? '').trim(),
        name: (button.getAttribute('aria-label') ?? button.textContent ?? '').trim(),
      })),
    );
    audited += seen.length;

    const offenders = seen.filter(({ label, name }) => {
      if (label === '') return false;
      if (!name.startsWith(label)) return true;
      // What follows the label is the description, and it is a description of
      // the option rather than the option's name a second time. The separator
      // between the two is the component's to choose, so it is stepped over
      // rather than spelled out here.
      return name
        .slice(label.length)
        .replace(/^[\s\p{Pd}:,.-]+/u, '')
        .startsWith(label);
    });

    expect(
      offenders,
      `${path}: a segmented option's accessible name says its label once, first`,
    ).toEqual([]);
  }

  // An audit that found no buttons to audit passes for the wrong reason.
  expect(audited, 'no segmented choice was found on any page').toBeGreaterThan(0);
});

/*
 * A definition list may hold terms and descriptions, and groups of them, and
 * nothing else. Seven pages' summary tiles and a pool's configuration list each
 * put a paragraph or a bar directly inside one, which is invalid and which a
 * screen reader answers by losing the pairing of term and value altogether.
 */
test('a definition list holds only terms and their descriptions', async ({ page }) => {
  test.slow();

  const pools = (await page.request.get('/api/v1/pools').then((r) => r.json())) as {
    items: { id: string; name: string }[];
  };
  const pool = pools.items.find((p) => p.name === FIXTURE.linuxPool)!;
  const pages = [...PAGES, { path: `/pools/${pool.id}`, heading: FIXTURE.linuxPool }];

  let audited = 0;
  for (const { path, heading } of pages) {
    await goto(page, path, heading);
    await settle(page, path);

    const result = await page.evaluate(() => {
      const allowed = new Set(['DT', 'DD', 'SCRIPT', 'TEMPLATE']);
      const lists = Array.from(document.querySelectorAll('dl'));
      const offenders = lists.flatMap((list) =>
        Array.from(list.children)
          .filter((child) => {
            if (allowed.has(child.tagName)) return false;
            // A wrapper is allowed, but only around terms and descriptions.
            if (child.tagName === 'DIV') {
              return Array.from(child.children).some(
                (inner) => !['DT', 'DD'].includes(inner.tagName),
              );
            }
            return true;
          })
          .map((child) => `<${child.tagName.toLowerCase()} class="${child.className}">`),
      );
      return { lists: lists.length, offenders };
    });
    audited += result.lists;
    expect(result.offenders, `${path}: a definition list holds only dt and dd`).toEqual([]);
  }

  // An audit that found no list to audit passes for the wrong reason.
  expect(audited, 'no definition list was found on any page').toBeGreaterThan(0);
});

test('every image has alternative text or is hidden from assistive technology', async ({
  page,
}) => {
  test.slow();

  for (const { path, heading } of PAGES) {
    await goto(page, path, heading);
    await settle(page, path);

    const offenders = await page.evaluate(() =>
      Array.from(document.querySelectorAll('img'))
        .filter(
          (image) =>
            image.getAttribute('alt') === null &&
            image.getAttribute('aria-hidden') !== 'true' &&
            image.closest('[aria-hidden="true"]') === null,
        )
        .map((image) => image.outerHTML.slice(0, 120)),
    );
    expect(offenders, `${path}: images carry alt text or are marked decorative`).toEqual([]);

    // An <svg role="img"> is an image too, and every one that is exposed must
    // say what it shows. A status shape beside its own printed label is
    // deliberately hidden instead, so it is not read out twice.
    const unlabelled = await page.evaluate(() =>
      Array.from(document.querySelectorAll('svg[role="img"]'))
        .filter(
          (svg) =>
            (svg.getAttribute('aria-label') ?? '').trim() === '' &&
            svg.getAttribute('aria-hidden') !== 'true' &&
            svg.closest('[aria-hidden="true"]') === null,
        )
        .map((svg) => svg.outerHTML.slice(0, 120)),
    );
    expect(unlabelled, `${path}: every svg image is described`).toEqual([]);
  }
});

test('no element carries a positive tabindex', async ({ page }) => {
  test.slow();

  for (const { path, heading } of PAGES) {
    await goto(page, path, heading);
    await settle(page, path);

    const positive = await page.evaluate(() =>
      Array.from(document.querySelectorAll('[tabindex]'))
        .filter((element) => Number(element.getAttribute('tabindex')) > 0)
        .map((element) => element.outerHTML.slice(0, 120)),
    );
    expect(positive, `${path}: the tab order is the document order`).toEqual([]);
  }
});

test('the skip link is first in the tab order and lands in main', async ({ page }) => {
  await goto(page, '/', 'Overview');
  const skip = page.getByRole('link', { name: 'Skip to the main content' });

  // The shell moves focus to the page heading after a navigation, so "from the
  // top" means walking backwards until there is nothing before us.
  const presses = await shiftTabTo(page, skip);
  expect(presses, 'the skip link is reachable from the keyboard').toBeGreaterThan(0);

  // It is off-screen until it has focus, and slides on-screen once it does;
  // polling rather than measuring once, because that slide is a transition.
  await expect
    .poll(async () => (await skip.boundingBox())?.y ?? -1, {
      message: 'a focused skip link comes on screen',
    })
    .toBeGreaterThanOrEqual(0);

  // Nothing at all comes before it.
  await page.keyboard.press('Shift+Tab');
  expect(await isFocused(skip)).toBe(false);
  expect(
    await page.evaluate(() => document.activeElement === document.body),
    'the skip link is the first stop in the page',
  ).toBe(true);

  await page.keyboard.press('Tab');
  expect(await isFocused(skip)).toBe(true);
  await page.keyboard.press('Enter');
  expect(await focusIsInMain(page), 'activating it moves focus into the main landmark').toBe(true);
});

test('a dialog keeps focus, closes on Escape and hands focus back', async ({ page }) => {
  // Opened from the runner's own page rather than from the grid's row menu, so
  // the same assertions hold at both widths.
  await goto(page, `/runners/${FIXTURE.busyRunnerId}`, FIXTURE.busyRunner);

  const trigger = page.getByRole('button', { name: 'Drain', exact: true });
  await trigger.click();

  const dialog = page.getByRole('dialog');
  await expect(dialog).toBeVisible();
  await expect(dialog).toHaveAttribute('aria-modal', 'true');
  // Focus moved in by itself.
  expect(
    await page.evaluate(() =>
      document.querySelector('[role="dialog"]')?.contains(document.activeElement),
    ),
  ).toBe(true);

  // And it stays in: tabbing round the dialog never escapes it.
  for (let press = 0; press < 6; press++) {
    await page.keyboard.press('Tab');
    expect(
      await page.evaluate(() =>
        document.querySelector('[role="dialog"]')?.contains(document.activeElement),
      ),
      'focus stays inside the dialog',
    ).toBe(true);
  }

  await page.keyboard.press('Escape');
  await expect(dialog).toBeHidden();
  // Focus comes back a frame after the dialog has gone, so wait for it rather
  // than sampling once.
  await expect(trigger, 'focus returns to what opened the dialog').toBeFocused();
});

// A heading that skips a level tells a screen-reader user who navigates by
// heading that a section is missing. Checked on the settings pages, which
// share a layout and so should share an outline: Backups, Configuration and
// About once went from the page's h1 straight to h3. Each names a heading that
// only exists once the page's data has loaded, so an outline read too early
// cannot pass for want of anything to skip.
const SETTINGS_OUTLINES = [
  { path: '/settings/backups', heading: 'Backups', loaded: '#backup-schedule' },
  { path: '/settings/configuration', heading: 'Configuration', loaded: '[id^="section-"]' },
  { path: '/settings/about', heading: 'About', loaded: '#docs-heading' },
  { path: '/settings/events', heading: 'Events', loaded: '[id^="feed-group-"]' },
  { path: '/settings/updates', heading: 'Updates', loaded: '#update-reason' },
];

for (const { path, heading, loaded } of SETTINGS_OUTLINES) {
  test(`${heading} settings never skip a heading level`, async ({ page }) => {
    await goto(page, path, heading);
    await expect(page.locator(loaded).first()).toBeVisible();

    const levels = await page
      .getByRole('main')
      .getByRole('heading')
      .evaluateAll((els) => els.map((el) => Number(el.tagName.slice(1))));
    expect(levels[0], 'the outline starts at the page heading').toBe(1);
    const skips = levels.filter((level, i) => i > 0 && level > (levels[i - 1] ?? 0) + 1);
    expect(skips, `heading levels in order: ${levels.join(', ')}`).toEqual([]);
  });
}

// A file input is visually hidden behind a button that opens its picker, so if
// it takes focus itself nothing is drawn: the ring is clipped away with the
// input, and a keyboard user loses the focus for a Tab. The button is the
// control; the input must not be a stop of its own.
const FILE_PICKERS = [
  { path: '/pools', heading: 'Pools', open: 'Import', dialog: 'Import pools' },
  {
    path: '/settings/configuration',
    heading: 'Configuration',
    open: 'Import',
    dialog: 'Import settings',
  },
  {
    path: '/settings/backups',
    heading: 'Backups',
    open: 'Upload a backup',
    dialog: 'Upload a backup',
  },
];

for (const { path, heading, open, dialog } of FILE_PICKERS) {
  test(`the ${dialog} dialog's file picker is reached through its button, not a hidden input`, async ({
    page,
  }) => {
    await goto(page, path, heading);
    await page.getByRole('button', { name: open, exact: true }).click();
    await expect(page.getByRole('dialog', { name: dialog })).toBeVisible();

    const chooser = page.getByRole('dialog', { name: dialog }).getByRole('button', {
      name: 'Choose a file',
    });
    let reached = false;
    for (let press = 0; press < 10; press++) {
      await page.keyboard.press('Tab');
      expect(
        await page.evaluate(() => (document.activeElement as HTMLInputElement | null)?.type),
        'focus never rests on an input nobody can see',
      ).not.toBe('file');
      reached ||= await chooser.evaluate((el) => el === document.activeElement);
    }
    expect(reached, 'the visible button is a tab stop').toBe(true);
  });
}

test('a drawer keeps focus the way a dialog does, and gives it back', async ({ page }) => {
  // A drawer is a modal too. It was untested, and it is the one an operator
  // opens most: every row of the Jobs grid opens one.
  await goto(page, '/jobs', 'Jobs');
  const row = page.locator('tbody tr[data-row]').first();
  await expect(row).toBeVisible();
  await row.click();

  const drawer = page.getByRole('dialog');
  await expect(drawer).toBeVisible();
  await expect(drawer).toHaveAttribute('aria-modal', 'true');
  expect(
    await page.evaluate(() =>
      document.querySelector('[role="dialog"]')?.contains(document.activeElement),
    ),
    'focus moves into the drawer by itself',
  ).toBe(true);

  for (let press = 0; press < 8; press++) {
    await page.keyboard.press('Tab');
    expect(
      await page.evaluate(() =>
        document.querySelector('[role="dialog"]')?.contains(document.activeElement),
      ),
      'focus stays inside the drawer',
    ).toBe(true);
  }

  // And the page behind it is not merely covered: it is inert, so a screen
  // reader's virtual cursor cannot read on into it either.
  // `inert` is set on every sibling of the overlay on the way up to <body>,
  // and it is not inherited as a property, so the answer is a walk. The grid
  // is the thing that matters: it is what an operator could otherwise read on
  // into, or click a row of, from behind an open drawer.
  expect(
    await page.evaluate(() => {
      let node: HTMLElement | null = document.querySelector('table[role="grid"]');
      while (node) {
        if (node.inert) return true;
        node = node.parentElement;
      }
      return false;
    }),
    'the grid behind the drawer is inert',
  ).toBe(true);

  await page.keyboard.press('Escape');
  await expect(drawer).toBeHidden();
  // Waited for rather than sampled once, for the reason the dialog above gives:
  // the overlay hands focus back a frame after it has gone, because clearing
  // the `inert` it put on the page has to happen first. Which frame that lands
  // on is the browser's business -- on a grid page it is a frame later again
  // when the columns have just been remeasured -- and it is not what this test
  // is about, which is that focus comes back at all rather than being left on
  // <body> at the top of the document.
  await expect
    .poll(() => focusIsInMain(page), { message: 'focus comes back to the page' })
    .toBe(true);
});

test('asking for less motion gets none', async ({ page }) => {
  // The tokens collapse to 1ms rather than the components each remembering to
  // check, so this is the honest place to assert it: if the tokens are right,
  // every transition and animation in the product is.
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await goto(page, '/', 'Overview');

  const motion = await page.evaluate(() => {
    const style = getComputedStyle(document.documentElement);
    return ['--z-motion-fast', '--z-motion-base', '--z-motion-slow'].map((token) =>
      style.getPropertyValue(token).trim(),
    );
  });
  expect(motion, 'every motion token collapses').toEqual(['1ms', '1ms', '1ms']);

  await page.emulateMedia({ reducedMotion: 'no-preference' });
  await page.reload();
  const restored = await page.evaluate(() =>
    getComputedStyle(document.documentElement).getPropertyValue('--z-motion-base').trim(),
  );
  expect(restored, 'and comes back for anyone who did not ask').not.toBe('1ms');
});

test('the page has the two live regions everything announces through', async ({ page }) => {
