        expect(before.y + before.height).toBeLessThan(nav.y);
      }
      await page.screenshot({ path: info.outputPath(`${style}-${mode}-${width}.png`) });
      await page.evaluate(() => scrollTo(0, document.documentElement.scrollHeight));
      await expect
