  expect(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth)).toBe(
    true,
  );
  await page.reload();
  await expect(page.getByRole('heading', { name: 'Retained report' })).toBeVisible();
  expect(reads).toBe(1);
  expect(captures).toBe(1);
});

