/*
 * Saving with the keyboard must not throw the keyboard out of the row. A button
 * that is natively disabled while its request runs is blurred by the browser, so
 * focus falls to the document and, when the save is refused and the editor stays
 * open, the next Tab starts from the top of the page. Busy is announced with
 * aria-busy and refused in the click handler instead, as Button does.
 */
test('the save button keeps focus while a change is being saved', async ({ page }) => {
  await openConfiguration(page);

  let release: () => void = () => {};
  const held = new Promise<void>((resolve) => (release = resolve));
  await page.route('**/api/v1/settings', async (route) => {
    if (route.request().method() !== 'PATCH') return route.fallback();
    await held;
    return route.fulfill({
      status: 422,
      contentType: 'application/json',
      body: JSON.stringify({ error: { code: 'invalid_input', message: 'That value is refused.' } }),
    });
  });

  const target = row(page, 'Keep webhook deliveries for');
  await target.getByRole('button', { name: 'Change' }).click();
  await target.getByRole('textbox').fill('97h');

  const save = target.getByRole('button', { name: /^Save / });
  await save.focus();
  await page.keyboard.press('Enter');

  await expect(save).toHaveAttribute('aria-busy', 'true');
  await expect(save, 'focus stays on the button that was pressed').toBeFocused();

  release();
  await expect(target.getByText('That value is refused.')).toBeVisible();
  await expect(save, 'and is still there when the save is refused').toBeFocused();
  await expect(save).not.toHaveAttribute('aria-busy', 'true');
});

/**
 * Connecting a GitHub App, from the browser, against a GitHub the browser can
 * reach.
 *
 * The suite drives the real binary, but its fake GitHub is an in-process test
 * server -- so the connect and verify pages, which are the first two an
 * operator meets after creating an account, were exercised at every layer
 * except the one they live on. This project runs that same fake as a program on
 * a loopback port beside an empty controller, so the whole path is real: the
 * form, the seal, the probe, the verdict.
 *
 * It is also the suite's only fail-then-recover journey outside a wrong
 * password. Setting a fleet up is mostly a sequence of things that do not work
 * yet, and a page is only trustworthy if it says which one.
 */
import { createHmac, randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';

import { expect, test } from '@playwright/test';
import { goto, reload } from './support/fixtures';

test.describe.configure({ mode: 'serial' });

interface Fake {
  url: string;
  appId: string;
  installationId: string;
  privateKey: string;
}

/** What the fixture left behind when it started the fake. */
function fake(): Fake {
  return JSON.parse(readFileSync('test-results/fakegithub.json', 'utf8')) as Fake;
}

/** Fill the "use an App you already have" form and submit it. */
async function connectWith(page: import('@playwright/test').Page, key: string): Promise<void> {
  const details = fake();
  await page.getByRole('button', { name: 'Connect GitHub' }).first().click();
  const dialog = page.getByRole('dialog');
  await expect(dialog).toBeVisible();
  await dialog.getByRole('tab', { name: 'Existing App' }).click();

  await dialog.getByLabel('Organisation login').fill('acme');
  await dialog.getByLabel('App ID').fill(details.appId);
  await dialog.getByLabel('Installation ID').fill(details.installationId);
  await dialog.getByLabel('API base URL').fill(details.url);
  await dialog.getByLabel('Private key').fill(key);
  await dialog.getByRole('button', { name: 'Connect', exact: true }).click();
}

test('both tab labels are whole on a phone', async ({ page }) => {
  // "Use an App you already have" was clipped to "Use an App you already h" in a
  // tab list that scrolls sideways, so the way through for a controller with no
  // webhook was the part of the dialog that could not be read.
  await page.setViewportSize({ width: 375, height: 812 });
