/**
 * The Undo on "Marked as known", when it is pressed after the drawer has moved on.
 *
 * The toast outlives the drawer that raised it by up to five seconds. A drawer
 * shows whatever job its page last selected, and Escape clears the selection, so
 * an Undo that looked at the drawer when it was pressed rather than when it was
 * offered did nothing at all once the drawer was closed, and put back the wrong
 * failure (while saying it had put back the right one) once another drawer was
 * open. It has to be for the failure it was offered for.
 */
import { expect, test, type Page } from '@playwright/test';
import { dataRows, goto, grid } from './support/fixtures';

const jobs = (page: Page) => grid(page, 'Jobs');

test('Undo puts the failure back after the drawer it was marked in has closed', async ({
  page,
}) => {
  await goto(page, '/jobs?attention=true', 'Jobs');
  const rows = dataRows(jobs(page));
  await expect(rows.first()).toBeVisible();
  const before = await rows.count();
  expect(before, 'the fixture has failures nobody has read').toBeGreaterThan(0);

  await rows.first().click();
  const drawer = page.getByRole('dialog');
  await drawer.getByRole('button', { name: 'Mark as known' }).click();
  await expect(drawer.getByText('Known', { exact: true })).toBeVisible();

  // Escape closes the drawer, and the page forgets which job it was showing.
  await page.keyboard.press('Escape');
  await expect(drawer).toBeHidden();
  await expect(rows).toHaveCount(before - 1);

  await page.getByRole('button', { name: 'Undo' }).click();
  await expect(page.getByText('Back on the attention list')).toBeVisible();
  await expect(rows).toHaveCount(before);
});

test('Undo puts back the failure that was marked, not the one whose drawer is open', async ({
  page,
}) => {
  await goto(page, '/jobs?attention=true', 'Jobs');
  const rows = dataRows(jobs(page));
  await expect(rows.first()).toBeVisible();
  const before = await rows.count();
  expect(before, 'the fixture has more than one failure nobody has read').toBeGreaterThan(1);

  await rows.first().click();
  const drawer = page.getByRole('dialog');
  await drawer.getByRole('button', { name: 'Mark as known' }).click();
  await expect(drawer.getByText('Known', { exact: true })).toBeVisible();
  await page.keyboard.press('Escape');
  await expect(drawer).toBeHidden();
  await expect(rows).toHaveCount(before - 1);

  // A different failure's drawer is open when Undo is pressed. The toast sits
  // outside the drawer's inert page on purpose, so it is still within reach.
  await rows.first().click();
  await expect(drawer).toBeVisible();
  await page.getByRole('button', { name: 'Undo' }).click();
  await expect(page.getByText('Back on the attention list')).toBeVisible();
  await page.keyboard.press('Escape');
  await expect(drawer).toBeHidden();
  await expect(rows).toHaveCount(before);
});

/**
 * The shortcuts the guidelines promise, from the keyboard alone.
 *
 * These are the ones an operator learns and then relies on: `g` then a letter
 * to reach any page, `/` to get into the search on whatever page they are on,
 * `?` to be reminded of the rest. They are also the ones most easily broken by
 * a change somewhere else, because they are global listeners on a window that
 * every page shares -- and, until this file, nothing tested them at all.
 *
 * The chord's refusals matter as much as the chord: `g r` typed into an open
 * confirmation must not navigate away from the thing being confirmed, and `g`
 * typed into a search box is a letter, not a shortcut.
 */
import { expect, test, type Page } from '@playwright/test';
import { FIXTURE, goto, isFocused, pageHeading } from './support/fixtures';

/** `g` then a letter, with the pause an operator actually leaves between them. */
async function chord(page: Page, letter: string): Promise<void> {
  await page.keyboard.press('g');
  await page.keyboard.press(letter);
}

// The whole list, from docs/ui-guidelines.md section 4. Each is checked from
// the Overview so a failure names the destination rather than the starting
// point, and the headings are the pages' own <h1>s.
const JUMPS = [
  { key: 'p', path: '/pools', heading: 'Pools' },
  { key: 'r', path: '/runners', heading: 'Runners' },
  { key: 'w', path: '/workflows', heading: 'Workflows' },
  // Out of the navigation, still one chord away: the page every link that
  // names a job lands on.
  { key: 'j', path: '/jobs', heading: 'Jobs' },
  { key: 'u', path: '/usage', heading: 'Usage' },
  { key: 'h', path: '/hosts', heading: 'Hosts' },
  { key: 'v', path: '/providers', heading: 'Providers' },
  { key: 'i', path: '/installations', heading: 'Installations' },
  { key: 'm', path: '/migrate', heading: 'Migrate repositories' },
  { key: 'a', path: '/audit', heading: 'Audit' },
  // Settings is a section: on a desktop its address goes straight to the
  // first page, on a phone it is the list of them.
  {
    key: 's',
    path: '/settings',
    heading: /^(Account|Settings)$/,
    lands: /\/settings(\/account)?$/,
    /** What the shortcut sheet calls it, where the heading is a pattern. */
    label: 'Settings',
  },
] as const;

test('g then a letter reaches every page in the navigation', async ({ page }) => {
  await goto(page, '/', 'Overview');

  for (const jump of JUMPS) {
    await chord(page, jump.key);
    await expect(
      pageHeading(page, jump.heading),
      `g ${jump.key} reaches ${jump.path}`,
    ).toBeVisible();
    await expect(page).toHaveURL('lands' in jump ? jump.lands : new RegExp(`${jump.path}$`));

    // Back to the Overview by its own chord, which checks `g o` nine times
    // over without a test of its own.
    await chord(page, 'o');
    await expect(pageHeading(page, 'Overview')).toBeVisible();
  }
});

test('a chord typed into a field is text, and one typed under a dialog goes nowhere', async ({
  page,
}) => {
  await goto(page, '/runners', 'Runners');
  const search = page.getByRole('searchbox', { name: 'Search runners' });

  // Into a text field, `g` is the letter g: the chord never fires, so the page
  // does not change under somebody in the middle of typing a runner's name.
  //
  // And the field keeps the keyboard while it does. The search writes itself
  // into the query string, which used to re-run the shell's post-navigation
