/**
 * The Build log and Runner diagnostics tabs, as assistive technology meets them.
 *
 * Two things were wrong, and neither shows to someone with a mouse. Choosing a tab
 * announced whether long lines wrap (the call that redraws the screen also spoke
 * for the wrap switch) and never said which log had just replaced the other. And
 * every tab claimed `aria-controls` for a panel that was never on the page,
 * because the log is drawn by the viewer and not handed to the tabs.
 */
import { expect, test } from '@playwright/test';
import { FIXTURE, goto } from './support/fixtures';

test('choosing a log source says which log is now showing', async ({ page }) => {
  await goto(page, `/runners/${FIXTURE.busyRunnerId}`, FIXTURE.busyRunner);
  // The terminal loads after the page, and the stream announces that it has
  // attached in the same place a view is announced. Waiting for that keeps the
  // first from landing on top of the second.
  await expect(page.getByRole('switch', { name: 'Follow' })).toBeVisible();
  await expect(page.getByText('Attached to the log stream.', { exact: true })).toBeAttached();

  await page.getByRole('tab', { name: 'Runner diagnostics' }).click();
  await expect(page.getByText('Showing the runner diagnostics.', { exact: true })).toBeAttached();
  await expect(page.getByText('Long lines wrap.', { exact: true })).toHaveCount(0);

  await page.getByRole('tab', { name: 'Build log', exact: true }).click();
  await expect(page.getByText('Showing the build log.', { exact: true })).toBeAttached();
});

test('the log source tabs claim no panel that is not on the page', async ({ page }) => {
  await goto(page, `/runners/${FIXTURE.busyRunnerId}`, FIXTURE.busyRunner);
  const tabs = page.getByRole('tablist', { name: 'Log source' }).getByRole('tab');
  await expect(tabs).toHaveCount(2);

  for (const tab of await tabs.all()) {
    const controls = await tab.getAttribute('aria-controls');
    if (controls === null) continue;
    await expect(
      page.locator(`[id="${controls}"]`),
      `the tab names ${controls}, which has to exist`,
    ).toHaveCount(1);
  }
});

/**
 * The runner log pane.
 *
 * Two failures live here and neither shows up in a unit test, because both are
 * geometry: the terminal standing proud of the pane that clips it -- so the
 * newest lines are drawn underneath the panel's bottom edge, which on a log
 * that is still being written is the only part anybody wants -- and xterm's own
 * layers climbing over the jump button, which then looks like a button and
 * ignores every click.
 *
 * Neither needs output to reproduce, so these run against the fixture runner
 * with nothing streaming.
 */
import { expect, test, type Page } from '@playwright/test';
import { FIXTURE, goto } from './support/fixtures';

const RUNNER = `/runners/${FIXTURE.busyRunnerId}`;

/** How far the terminal hangs below the pane. Anything above zero is clipped. */
async function overhang(page: Page): Promise<number> {
  return page.evaluate(() => {
    const term = document.querySelector('.xterm');
    const pane = document.querySelector('.screen');
    if (!term || !pane) return Number.NaN;
    return term.getBoundingClientRect().bottom - pane.getBoundingClientRect().bottom;
  });
}

async function openLog(page: Page): Promise<void> {
  await goto(page, RUNNER, FIXTURE.busyRunner);
  await expect(page.locator('.xterm')).toBeVisible();
  // The mono web font arrives after the first fit and makes the cells taller,
  // which is the moment the terminal used to outgrow its pane.
  await page.evaluate(() => document.fonts.ready);
  await expect.poll(() => overhang(page)).toBeLessThanOrEqual(0);
}

test('the terminal is fitted inside the pane, so the newest line is on screen', async ({
  page,
}) => {
  await openLog(page);

  // A resize is the other moment the fit can go stale.
  const size = page.viewportSize();
  if (size)
    await page.setViewportSize({ width: size.width, height: Math.round(size.height * 0.7) });
  await expect.poll(() => overhang(page)).toBeLessThanOrEqual(0);
});

test('the jump button can be clicked rather than only seen', async ({ page }) => {
  await openLog(page);

  // Turning follow off is what offers the button, output or none.
  const follow = page.getByRole('switch', { name: 'Follow' });
  await expect(follow).toHaveAttribute('aria-checked', 'true');
  await follow.click();

  // `click` is the assertion: Playwright refuses to click through whatever is
  // painted on top, which is exactly the bug.
  const jump = page.getByRole('button', { name: /Jump to latest/ });
  await expect(jump).toBeVisible();
  await jump.click();
  await expect(jump).toBeHidden();
  await expect(follow).toHaveAttribute('aria-checked', 'true');
});

/**
 * The log viewer.
 *
 * The most intricate component in the product and, until this file, the one
 * with no test at all: a terminal, an event stream, a search over what has
 * arrived, and a follow mode that has to know the difference between "the
 * operator scrolled up to read something" and "there is nothing new".
 *
 * The seeded fixture has no agent behind it, so no line is ever relayed. That
 * turns out to be the state most worth protecting: the viewer has to say it is
 * waiting rather than claim the runner produced nothing, has to offer the whole
 * log on the host rather than only the lines on screen, and has to refuse
 * honestly for a runner whose host can no longer be asked. Feeding synthetic
 * lines through the stream is deliberately not done here -- a mocked
 * text/event-stream is a different object from the relayed one, and a test that
 * passes against the mock proves nothing about the relay.
 */
import { expect, test, type Page } from '@playwright/test';
import { FIXTURE, goto } from './support/fixtures';

const follow = (page: Page) => page.getByRole('switch', { name: 'Follow' });
const wrap = (page: Page) => page.getByRole('switch', { name: 'Wrap' });
const search = (page: Page) => page.getByRole('searchbox', { name: 'Search the log' });

/** Wait for the dynamic xterm import to land and the toolbar to exist. */
async function booted(page: Page): Promise<void> {
  await expect(follow(page)).toBeVisible();
}

async function openLog(page: Page): Promise<void> {
  await goto(page, `/runners/${FIXTURE.busyRunnerId}`, FIXTURE.busyRunner);
  await page.getByRole('tab', { name: 'Runner diagnostics' }).click();
  await booted(page);
}

test('build output comes first and changing log source reuses the stream', async ({ page }) => {
  const logRequests: string[] = [];
  page.on('request', (request) => {
    if (request.url().includes(`/runners/${FIXTURE.busyRunnerId}/logs?`))
      logRequests.push(request.url());
  });
  await goto(page, `/runners/${FIXTURE.busyRunnerId}`, FIXTURE.busyRunner);
  const output = page.getByRole('region', { name: 'Job output', exact: true });
  await output.getByText('Step summary', { exact: true }).click();
  await expect(output.getByRole('list', { name: 'Steps' })).toBeVisible();
  await expect(output.getByText('Set up job', { exact: true })).toBeVisible();
  const link = output.getByRole('link', { name: /Open on GitHub/ });
  await expect(link).toHaveAttribute('href', /^https:\/\/github.com\/acme\/.+\/actions\/runs\//);
  await expect(link).toHaveAttribute('target', '_blank');
  await expect(page.getByRole('tab', { name: 'Build log', exact: true })).toHaveAttribute(
    'aria-selected',
    'true',
  );
  await expect(page.getByText('Waiting for build output', { exact: true })).toBeVisible();
  await expect(page.getByRole('button', { name: 'Save log', exact: true })).toBeDisabled();
  await page.getByRole('tab', { name: 'Runner diagnostics' }).click();
  await booted(page);
  await expect(page.getByText('Waiting for output. Nothing has been written yet.')).toBeVisible();
  expect(logRequests).toHaveLength(1);
  await page.getByRole('tab', { name: 'Build log', exact: true }).click();
  await expect(page.getByRole('group', { name: /^Build output for/ })).toBeVisible();
  expect(logRequests).toHaveLength(1);
});

test('with nothing relayed it says it is waiting, not that there was nothing', async ({ page }) => {
  await openLog(page);

  // The difference matters: "nothing has been written yet" is a runner that is
  // still starting, "this runner produced no output" is a finished job that
  // said nothing, and the viewer must not claim the second while waiting for
  // the first.
  await expect(page.getByText('Waiting for output. Nothing has been written yet.')).toBeVisible();
  await expect(page.getByText('This runner produced no output.')).toHaveCount(0);

  // The terminal is a named region rather than an anonymous box of text.
  await expect(
    page.getByRole('group', { name: `Log output for ${FIXTURE.busyRunner}` }),
  ).toBeVisible();
});

test('follow and wrap are switches, and turning follow off offers the way back', async ({
  page,
}) => {
  await openLog(page);

  // Both on by default: an operator opening a log wants the newest line, and
  // does not want to lose the right-hand end of it.
  await expect(follow(page)).toBeChecked();
  await expect(wrap(page)).toBeChecked();

  await follow(page).click();
  await expect(follow(page)).not.toBeChecked();
  // Turning follow off is what puts the jump control on screen. Without it,
  // scrolling up to read something is a trap.
  // It is asserted rather than pressed: with no lines relayed the "waiting for
  // output" overlay is on top of it, which is right -- there is nothing to
  // jump to -- and pressing it here would be testing the overlay.
  const jump = page.getByRole('button', { name: /^Jump to latest/ });
  await expect(jump).toBeVisible();

  await follow(page).click();
  await expect(follow(page)).toBeChecked();
  await expect(jump).toBeHidden();

  await wrap(page).click();
  await expect(wrap(page)).not.toBeChecked();
});

test('search answers honestly when there is nothing to search', async ({ page }) => {
  await openLog(page);

  // Both step buttons are dead until there is a query, and the count says "no
  // matches" rather than staying blank -- "is this error in here?" needs an
  // answer, and no is an answer.
  await expect(page.getByRole('button', { name: 'Next match' })).toBeDisabled();
  await expect(page.getByRole('button', { name: 'Previous match' })).toBeDisabled();

  await search(page).fill('npm ERR!');
  await expect(page.getByText('No matches')).toBeVisible();
});

test('clearing empties the screen and promises the host still has the log', async ({ page }) => {
  await openLog(page);

  await page.getByRole('button', { name: 'Clear' }).click();
  await expect(
    page.getByText('Cleared. Anything the runner writes from now on appears here.'),
  ).toBeVisible();

  // The wording is the promise, and the download beside it is what makes the
  // promise checkable: it fetches the log on the host, not the lines that were
  // on screen.
  await expect(page.getByRole('link', { name: 'Download' })).toHaveAttribute(
    'href',
    new RegExp(`/runners/${FIXTURE.busyRunnerId}/logs/download$`),
  );
});

test('a runner that is gone says the log cannot be read, rather than waiting for ever', async ({
  page,
}) => {
  // run_demo10 is seeded as removed, so its host can no longer be asked.
  await page.goto('/runners/run_demo10', { waitUntil: 'domcontentloaded' });
  await expect(page.getByRole('heading', { name: 'Job output', exact: true })).toBeVisible();
  await page.getByText('Runner diagnostics', { exact: true }).click();
  await expect(page.getByText('The log cannot be read right now')).toBeVisible();
  await expect(follow(page), 'no toolbar for a stream that cannot open').toHaveCount(0);
});

/**
 * Clearing out a pile of failed machines, from the page that lists them.
 *
 * A wrong template or a wrong address fills a fleet with machines that never
 * became hosts, and deleting them one page at a time is how that becomes a
 * chore nobody does. The list therefore lets an administrator tick several and
 * delete them together, with a confirmation that is as heavy as what it does:
 * a click when nothing is destroyed, the count typed when a VM is.
 *
 * The demo fleet has two healthy machines and must keep them for the specs
 * that read them, and a delete is the one act that cannot be put back. So the
 * list is given extra failed machines in the response, and the bulk request is
 * answered in the test. What is under test is the page: who can be ticked, what
 * the dialog says, what is sent, and where the controller's reasons land. The
 * controller's own rules are the Go tests', which run the real route.
 */
import { expect, test, type Page, type Route } from '@playwright/test';
import { FIXTURE, goto, readThrough } from './support/fixtures';

interface Row {
  id: string;
  name: string;
  state: string;
  resource_zone?: string;
  resource_id?: string;
}

const NO_VM_A: Row = { id: 'mach_bulk_a', name: 'zoomies-mach-bulk-a', state: 'failed' };
const NO_VM_B: Row = { id: 'mach_bulk_b', name: 'zoomies-mach-bulk-b', state: 'failed' };
const WITH_VM: Row = {
  id: 'mach_bulk_c',
  name: 'zoomies-mach-bulk-c',
  state: 'failed',
  resource_zone: 'pve-1',
  resource_id: '143',
};
const DOUBTFUL: Row = {
  id: 'mach_bulk_d',
  name: 'zoomies-mach-bulk-d',
  state: 'quarantined',
  resource_zone: 'pve-1',
  resource_id: '144',
};

/** A machine as the API renders it, with only what the list reads filled in. */
function view(row: Row) {
  return {
    ...row,
    provider_id: 'prv_demoproxmox',
    provider_name: 'demo-pve',
    labels: {},
    timeline: [],
    safe_to_delete: false,
    created_at: '2026-09-14T11:00:00Z',
    updated_at: '2026-09-14T11:30:00Z',
  };
}

interface Asked {
  action?: string;
  ids?: string[];
  force?: boolean;
}

/**
 * Add the failed machines to the list, and answer the bulk route.
 *
 * `refuse` maps a machine id to the sentence the controller would give for it;
 * every other machine is taken. The requests are collected so the test can say
 * exactly what the page sent.
 */
async function arrange(page: Page, refuse: Record<string, string> = {}): Promise<Asked[]> {
  const asked: Asked[] = [];
  await page.route(/\/api\/v1\/machines(?:\?.*)?$/, async (route: Route) => {
    if (route.request().method() !== 'GET') return route.fallback();
    const read = await readThrough(route);
    if (!read) return;
    const { body } = read;
    body.items = [...body.items, ...[NO_VM_A, NO_VM_B, WITH_VM, DOUBTFUL].map(view)];
    return route.fulfill({ json: body });
  });
  await page.route(/\/api\/v1\/machines\/bulk$/, async (route: Route) => {
    const body = route.request().postDataJSON() as Asked;
    asked.push(body);
    await route.fulfill({
      json: {
        results: (body.ids ?? []).map((id) =>
          refuse[id] ? { id, ok: false, error: refuse[id] } : { id, ok: true },
        ),
      },
    });
  });
  return asked;
}

