/**
 * Plant something a reload would lose, then check it is still there.
 *
 * A page that got its new numbers by reloading itself would pass a weaker
 * test and still be the bug: every page is expected to update in place, with
 * nobody pressing anything.
 */
export async function plantMarker(page: Page): Promise<void> {
  await page.evaluate(() => {
    (window as unknown as { __zoomiesStayedPut: boolean }).__zoomiesStayedPut = true;
  });
}

export async function expectNoReload(page: Page): Promise<void> {
  const stayed = await page.evaluate(
    () => (window as unknown as { __zoomiesStayedPut?: boolean }).__zoomiesStayedPut === true,
  );
  expect(stayed, 'the page updated in place rather than reloading').toBe(true);
}

/** The page's `<h1>`, optionally by name -- exactly, or by a pattern. */
export function pageHeading(page: Page, name?: string | RegExp): Locator {
  if (name === undefined) return page.getByRole('heading', { level: 1 });
  if (name instanceof RegExp) return page.getByRole('heading', { level: 1, name });
  return page.getByRole('heading', { level: 1, name, exact: true });
}

/**
 * Go to a path and wait for the page itself, never for the network.
 *
 * @param heading the `<h1>` that proves the route rendered.
 */
export async function goto(page: Page, path: string, heading?: string | RegExp): Promise<void> {
  await page.goto(path, { waitUntil: 'domcontentloaded' });
  await expect(pageHeading(page, heading)).toBeVisible();
}

/** Reload and wait for the same proof `goto` waits for. */
export async function reload(page: Page, heading?: string | RegExp): Promise<void> {
  await page.reload({ waitUntil: 'domcontentloaded' });
  await expect(pageHeading(page, heading)).toBeVisible();
}

/** The persistent navigation: the left sidebar, or the phone's bottom bar. */
export function nav(page: Page): Locator {
  return page.getByRole('navigation', { name: 'Sections', exact: true });
}

/**
 * One navigation entry, by the path it points at.
 *
 * By href rather than by accessible name, because the sidebar empties the name
 * of its own labels when it is collapsed (see the note in a11y.spec.ts) and
 * this helper has to work in both projects. Scoped to the list so the brand
 * mark, which also points at "/", is not one of the entries.
 *
 * On a phone the bar carries only the four primary sections; the rest are in
 * the sheet More opens, so reach those with `menuEntry`.
 */
export function navEntry(page: Page, path: string): Locator {
  return nav(page).getByRole('listitem').locator(`a[href="${path}"]`);
}

/** The paths the phone's bottom bar carries itself, from `lib/shell/sections.ts`. */
export const PRIMARY_SECTIONS: readonly string[] = ['/', '/pools', '/runners', '/workflows'];

/** The phone's menu -- the sheet More opens -- once it is open. */
export function navMenu(page: Page): Locator {
  return page.getByRole('dialog', { name: 'All sections' });
}

/** Press "More" in the bottom bar and wait for the sheet it opens. */
export async function openNavMenu(page: Page): Promise<Locator> {
  await nav(page).getByRole('button', { name: 'More', exact: true }).click();
  const menu = navMenu(page);
  await expect(menu).toBeVisible();
  return menu;
}

/** One entry of the phone's menu, by the path it points at. */
export function menuEntry(page: Page, path: string): Locator {
  return navMenu(page).getByRole('listitem').locator(`a[href="${path}"]`);
}

/**
 * Go to a section the way an operator would at this width.
 *
 * The sidebar lists all twelve; the phone's bar lists four and keeps the rest
 * in the sheet. Which of those a test is looking at is not the thing under
 * test in most specs, so they ask for the section and get there.
 */
export async function openSection(page: Page, path: string): Promise<void> {
  if ((await navEntry(page, path).count()) > 0) {
    await navEntry(page, path).click();
    return;
  }
  await openNavMenu(page);
  await menuEntry(page, path).click();
  await expect(navMenu(page)).toHaveCount(0);
}

/**
 * That the navigation marks this section as the one being looked at -- and
 * marks exactly one, since a mark two entries carry means nothing.
 */
export async function expectCurrentSection(page: Page, path: string): Promise<void> {
  if ((await navEntry(page, path).count()) > 0) {
    await expect(navEntry(page, path)).toHaveAttribute('aria-current', 'page');
    await expect(nav(page).locator('[aria-current="page"]')).toHaveCount(1);
    return;
  }
  const menu = await openNavMenu(page);
  await expect(menuEntry(page, path)).toHaveAttribute('aria-current', 'page');
  await expect(menu.locator('[aria-current="page"]')).toHaveCount(1);
  await page.keyboard.press('Escape');
  await expect(navMenu(page)).toHaveCount(0);
}

/** A DataGrid by its accessible name: "Runners", "Pools", "Jobs". */
export function grid(page: Page, label: string): Locator {
  return page.getByRole('grid', { name: label });
}

/**
 * The grid's real data rows.
 *
 * Structural rather than by role for two reasons: nothing in ARIA separates a
 * body row from the header row, and the loading skeleton draws rows that are
 * just as visible as real ones. Only a real row carries `data-row`.
 */
export function dataRows(gridLocator: Locator): Locator {
  return gridLocator.locator('tbody tr[data-row]');
}

/** Wait for a grid to have rows -- never for the network, which never idles. */
export async function waitForRows(gridLocator: Locator): Promise<Locator> {
  const rows = dataRows(gridLocator);
  await expect(rows.first()).toBeVisible();
  return rows;
}

/**
 * The pagination summary -- "1–9 of 9 runners" -- which is how a filter proves
 * it narrowed the set rather than merely repainting it. The line carries no
 * role of its own, so it is reached inside the landmark that does.
 */
export function rowCount(page: Page): Locator {
  return page.getByRole('navigation', { name: 'Pagination' }).locator('p');
}

/**
 * The index of a column, so a cell can be read by what its header says.
 *
 * Read from the elements rather than from the accessibility tree: on a phone
 * every row is a card and the heading row is hidden, so `columnheader` does not
 * resolve there -- but the column is still the same column, in the same place,
 * and its cell still carries the heading as its own label.
 */
export async function columnIndex(gridLocator: Locator, header: string): Promise<number> {
  const headers = await gridLocator
    .locator('thead th')
    .evaluateAll((cells) => cells.map((cell) => (cell.textContent ?? '').trim()));
  const index = headers.findIndex((text) => text.toLowerCase().startsWith(header.toLowerCase()));
  expect(index, `the grid has a "${header}" column`).toBeGreaterThanOrEqual(0);
  return index;
}

/**
 * One cell of one row, named by its column header rather than its position.
 *
 * The table carries `role="grid"`, so its cells are `gridcell`s.
 */
export async function cellUnder(
  gridLocator: Locator,
  row: Locator,
  header: string,
): Promise<Locator> {
  return row.getByRole('gridcell').nth(await columnIndex(gridLocator, header));
}

/** Every value in one column of the grid, in the order the rows are shown. */
export async function columnTexts(gridLocator: Locator, header: string): Promise<string[]> {
  const index = await columnIndex(gridLocator, header);
  return dataRows(gridLocator).evaluateAll(
    (rows, at) =>
      rows.map(
        (row) => (row.querySelectorAll('td')[at] as HTMLElement | undefined)?.innerText ?? '',
      ),
    index,
  );
}

/**
 * A filter menu trigger on the Jobs page.
 *
 * The column header that sorts by the same field is also a button with the
 * same words, so the trigger is picked out by the `aria-expanded` that only a
 * popup trigger carries.
 */
export function facetTrigger(page: Page, label: string, open = false): Locator {
  return page.getByRole('button', { name: label, expanded: open });
}

/**
 * Store a choice before the app runs, once for each tab.
 *
 * An init script runs again on every navigation, so one that wrote its value
 * every time would put a test back on it after the test had chosen otherwise in
 * the page and then reloaded, which is exactly what a test about choosing a
 * style or a theme does. `sessionStorage` lasts as long as the tab and survives
 * a reload: the first document seeds, and the ones after it leave the choice
 * alone.
 */
async function seedOnce(page: Page, key: string, value: string): Promise<void> {
  await page.addInitScript(
    ([key, value]) => {
      const seeded = `seeded ${key}`;
      if (sessionStorage.getItem(seeded)) return;
      sessionStorage.setItem(seeded, '1');
      localStorage.setItem(key, value);
    },
    [key, value] as const,
  );
}

/**
 * Start the page on Classic, the visual style these specs were written for.
 *
 * Mission Control is the default, so a test that measures Classic's type
 * scale or its history-first layout says so rather than relying on an empty
 * browser. Storage starts empty in every context, so this runs before the app.
 * It seeds once for each tab, so a test may choose another style in the page
 * and reload.
 */
export async function useClassic(page: Page): Promise<void> {
  await seedOnce(page, 'zoomies.ui-style', 'classic');
}

/**
 * Start the page following the operating system's colour scheme.
 *
 * Dark is the default, so a test that flips `prefers-color-scheme` to see both
 * themes opts into System first. Seeded once for each tab, like useClassic.
 */
export async function useSystemTheme(page: Page): Promise<void> {
  await seedOnce(page, 'zoomies.theme', 'system');
}

/**
 * Open the Jobs page's Filters disclosure when the page has folded it away.
 *
 * Mission Control does that on a phone, behind a summary that counts what is in
 * force, so the facet menus, the date range and the switches are not there to be
 * pressed until it is opened; everywhere else they are simply on the page and the
 * summary is hidden. Idempotent, and safe to call before the grid has answered:
 * the disclosure is part of the page's frame.
 */
export async function openFilters(page: Page): Promise<void> {
  const fold = page.locator('details.advanced');
  if ((await fold.count()) === 0 || (await fold.evaluate((el: HTMLDetailsElement) => el.open))) {
    return;
  }
  await fold.locator(':scope > summary').click();
}

/**
 * Open the Jobs page's "Fleet context and activity" fold when the page has
 * folded it away.
 *
 * Mission Control does that on a phone to put the rows first; the summary is
 * hidden at other widths, where the section is simply open.
 */
export async function openFleetContext(page: Page): Promise<void> {
  const fold = page.locator('details.fleet-context');
  if ((await fold.count()) === 0 || (await fold.evaluate((el: HTMLDetailsElement) => el.open))) {
    return;
  }
  await fold.locator(':scope > summary').click();
}

/**
 * A size token as the page in front of the test computes it, in pixels.
 *
 * A test that pins a size to a number is pinned to one visual style's type
 * scale, and Mission Control's is larger than Classic's. Asking the page what the
 * token comes to makes the claim "this is the size the token says", which holds
 * in both styles, so the test need not choose one.
 */
export async function tokenPixels(page: Page, token: string): Promise<string> {
  return page.evaluate((name) => {
    const probe = document.createElement('span');
    probe.style.fontSize = `var(${name})`;
    document.body.append(probe);
    const pixels = getComputedStyle(probe).fontSize;
    probe.remove();
    return pixels;
  }, token);
}

/** What the theme currently is: the attribute on `<html>` and what was stored. */
export async function readTheme(
  page: Page,
): Promise<{ attribute: string | null; stored: string | null }> {
  return page.evaluate(() => ({
    attribute: document.documentElement.getAttribute('data-theme'),
    stored: (() => {
      try {
        return localStorage.getItem('zoomies.theme');
      } catch {
        return null;
      }
    })(),
  }));
}

/** The top bar's command-palette hint. */
export function paletteOpener(page: Page): Locator {
  // By its own label, not by the key cap inside it. The cap is hidden on a
  // phone -- it names a key that is not there -- and the words beside it are
  // hidden below the sidebar breakpoint, so the button carries the name itself
  // and it is the same at every width.
  return page.getByRole('button', { name: 'Search or jump to' });
}

/** The top bar's account menu, opened. */
export async function openAccountMenu(page: Page): Promise<Locator> {
  await page.getByRole('button', { name: 'Account menu' }).click();
  const menu = page.getByRole('menu', { name: 'Account menu' });
  await expect(menu).toBeVisible();
  return menu;
}

/**
 * Choose a theme the way an operator does: from the account menu, where the
 * three options are visible and the one in force is marked.
 */
export async function chooseTheme(page: Page, choice: 'light' | 'dark' | 'system'): Promise<void> {
  const menu = await openAccountMenu(page);
  const name = choice === 'dark' ? 'Dark' : choice === 'light' ? 'Light' : 'System';
  await menu.getByRole('menuitemradio', { name }).click();
  if (choice === 'system') await expect(page.locator('html')).not.toHaveAttribute('data-theme');
  else await expect(page.locator('html')).toHaveAttribute('data-theme', choice);
}

/**
 * Forget every stored preference for this origin.
 *
 * Playwright gives each test its own context, so storage starts empty anyway;
 * this is for the tests that write a preference and then want to prove what
 * happens without one.
 */
export async function clearStoredPreferences(page: Page): Promise<void> {
  await page.evaluate(() => {
    try {
      localStorage.clear();
    } catch {
      /* private mode: there was nothing stored to begin with */
    }
  });
}

/** How wide the document is against how wide the window is. */
export async function documentWidth(
  page: Page,
): Promise<{ scrollWidth: number; clientWidth: number }> {
  return page.evaluate(() => ({
    scrollWidth: document.documentElement.scrollWidth,
    clientWidth: document.documentElement.clientWidth,
  }));
}

/**
 * Open the Hosts page's capacity map, which is folded away until somebody asks,
 * and return its region.
 *
 * Idempotent, because the choice is remembered: a test that opened it and then
 * reloads, or that visits the page twice, finds it open and must not close it.
 */
export async function openHostCapacityMap(page: Page): Promise<Locator> {
  const toggle = page.getByRole('button', { name: 'Host capacity map', exact: true });
  if ((await toggle.getAttribute('aria-expanded')) !== 'true') await toggle.click();
  const map = page.getByRole('region', { name: 'Host capacity map', exact: true });
  await expect(map).toBeVisible();
  return map;
}

/**
 * Open a host card's Details, which a card does not show until it is asked, and
 * return the card.
 *
 * Idempotent, because the choice is remembered: a test that opened it and then
 * reloads, or that visits the page twice, finds it open and must not close it.
 * It waits for the card, so it is also how a test says "once the host is on the
 * page".
 *
 * `keyboard` opens it with Enter instead of a click. A test about what keyboard
 * focus does needs it: after a mouse click the browser stops counting a scripted
 * `focus()` as keyboard focus (`:focus-visible`), and that is what opens help
 * on focus.
 */
export async function openHostCard(
  card: Locator,
  via: 'pointer' | 'keyboard' = 'pointer',
): Promise<Locator> {
  const toggle = card.getByRole('button', { name: /^Details for / });
  if ((await toggle.getAttribute('aria-expanded')) !== 'true') {
    if (via === 'keyboard') {
      await toggle.focus();
      await card.page().keyboard.press('Enter');
    } else {
      await toggle.click();
    }
  }
  await expect(toggle).toHaveAttribute('aria-expanded', 'true');
  return card;
}

/**
 * Close a host card's Details again, for a test that has looked at what is behind
 * it and then needs to see what the card says without it: a reason is meant to be
 * there with the fold shut, and a spec that left it open could not tell.
 *
 * Idempotent, like openHostCard, and returns the card.
 */
export async function closeHostCard(card: Locator): Promise<Locator> {
  const toggle = card.getByRole('button', { name: /^Details for / });
  if ((await toggle.getAttribute('aria-expanded')) === 'true') await toggle.click();
  await expect(toggle).toHaveAttribute('aria-expanded', 'false');
  return card;
}

/** True when the element currently holds focus. */
export function isFocused(locator: Locator): Promise<boolean> {
  return locator.evaluate((element) => element === document.activeElement);
}

/** Whether focus is somewhere inside the main landmark. */
export function focusIsInMain(page: Page): Promise<boolean> {
  return page.evaluate(
    () => document.querySelector('main')?.contains(document.activeElement) ?? false,
  );
}

/**
 * Walk backwards to the top of the tab order.
 *
 * The shell moves focus to the page heading after every navigation, so a plain
 * `Tab` starts from the middle of the document. Shift+Tab until the given
 * element has focus; the number of presses is returned so a caller can assert
 * that nothing else came first.
 */
export async function shiftTabTo(page: Page, target: Locator, limit = 40): Promise<number> {
  for (let presses = 1; presses <= limit; presses++) {
    await page.keyboard.press('Shift+Tab');
    if (await isFocused(target)) return presses;
  }
  return -1;
}

/**
 * Pretend the page was opened by a signed-in user holding `role`.
 *
 * The suite's controller runs with authentication off, so every request is an
 * administrator and a viewer's page cannot be reached honestly. The two routes
 * a page asks first, the instance's meta and the session, are answered as though
 * authentication were on, and everything after them is the real binary. Pass
 * `externalURL` when the page under test shows the address the controller says
 * it is served at.
 */
export async function signedInAs(
  page: Page,
  role: 'viewer' | 'operator' | 'admin',
  externalURL?: string,
): Promise<void> {
  await page.route('**/api/v1/meta', async (route) => {
    const response = await route.fetch();
    const body = (await response.json()) as Record<string, unknown>;
    return route.fulfill({
      response,
      json: {
        ...body,
        auth_disabled: false,
        bootstrap_required: false,
        ...(externalURL ? { external_url: externalURL } : {}),
      },
    });
  });
  await page.route('**/api/v1/auth/session', (route) =>
    route.fulfill({ json: { kind: 'token', id: 'tok_pretend', name: 'a token', role } }),
  );
}

/** The page is no wider than its window, so nothing makes it scroll sideways. */
export async function expectNoSidewaysScroll(page: Page, where: string): Promise<void> {
  const { scrollWidth, clientWidth } = await documentWidth(page);
  expect(
    scrollWidth,
    `${where} is ${scrollWidth}px wide in a ${clientWidth}px window, so the page scrolls sideways`,
  ).toBeLessThanOrEqual(clientWidth);
}

/** A dialog by its accessible name. */
export const dialog = (page: Page, name: string | RegExp): Locator =>
  page.getByRole('dialog', { name });

/**
 * The Overview's feed, opened out. It previews its three newest entries and
 * keeps the rest behind "Expand events", so a test that is about what the feed
 * carries, rather than about what it previews, asks for all of it. The
 * choice is remembered by the browser, and this is harmless when it already is.
 */
export async function openEventsFeed(page: Page): Promise<Locator> {
  const feed = page.getByRole('region', { name: 'Recent events', exact: true });
  await expect(feed).toBeVisible();
  const expand = feed.getByRole('button', { name: 'Expand events' });
  if (await expand.isVisible().catch(() => false)) await expand.click();
  await expect(feed.getByRole('button', { name: 'Show fewer events' })).toBeVisible();
  return feed;
}

/**
 * The server's own answer to a request, for a handler that changes a little of
 * it, or null when the page gave up on the request while the handler was
 * waiting for the server.
 *
 * A grid that asks again, or a navigation, abandons the read it had out. A
 * handler that then parses a disposed body throws, the request is never
 * answered, and the test fails on a page that did nothing wrong. A read is
 * handed on instead, a write dropped, and the caller has nothing left to answer.
 *
 * `T` defaults to `any` because a handler that rewrites a response knows its
 * shape better than this file can, and the ones that say nothing read it as
 * loosely as `response.json()` always has.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export async function readThrough<T = any>(
  route: Route,
  options?: Parameters<Route['fetch']>[0],
): Promise<{ response: APIResponse; body: T } | null> {
  try {
    const response = await route.fetch(options);
    return { response, body: (await response.json()) as T };
  } catch {
    // Handing the request on is only safe when it is the request that was read:
    // a GET the handler fetched as itself. A handler that answers a write with a
    // read (the page's PATCH, fetched as a GET so the controller never sees it)
    // would send the write to the real controller, which the test chose not to
    // do, so anything else is dropped. The page had given up on it anyway.
    const asked = route.request().method();
    const same = (asked === 'GET' || asked === 'HEAD') && (options?.method ?? asked) === asked;
    if (same) await route.fallback().catch(() => undefined);
    else await route.abort().catch(() => undefined);
    return null;
  }
}

/**
 * Take the event stream away, for a test that decides what the page reads.
 *
 * A page that replaces what it holds from a stream frame is raced by one: a
 * frame that lands first leaves the real document on the page and the one the
 * test wrote is never shown, and one that lands later removes what the test was
 * about to act on. A stream that is down cannot send. Do not use it where the
 * test needs the stream, a dispatched `resync` or a held read, say.
 */
export async function withoutTheStream(page: Page): Promise<void> {
  await page.route('**/api/v1/events*', (route) => route.abort('connectionfailed'));
}

// Captures the development-only component gallery, in every style and colour
// mode, at desktop and phone widths.
//
// The gallery is not part of the built binary, so this cannot use the same
// controller fixture as tests/support/screenshots.mjs: it starts the Vite dev
// server the gallery actually lives on, photographs gallery.html, and stops
// the server again. Nothing here touches the application's own captures.
//
//   make screenshots-gallery                    writes design/theme-review/gallery/*.webp
//   node tests/support/gallery-screenshots.mjs DIR  writes them somewhere else
//
// Pillow is the encoder, as it is for the documentation screenshots.

import { spawn } from 'node:child_process';
import { mkdirSync, mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { chromium } from '@playwright/test';
import { encodeWebp } from './webp.mjs';

const web = resolve(import.meta.dirname, '..', '..');
const root = resolve(web, '..');
const outDir = resolve(process.argv[2] ?? join(root, 'design', 'theme-review', 'gallery'));
const PORT = Number(process.env.ZOOMIES_GALLERY_PORT ?? 8091);
const BASE = `http://127.0.0.1:${PORT}`;
const DESKTOP = { width: 1440, height: 900 };
/** The width the plan names first, and the one the phone layout is judged at. */
const PHONE = { width: 375, height: 900 };

/**
 * One capture per combination and width. Full page: the gallery is a column of
 * panels, and a viewport shot would only ever show the buttons and the fields.
 */
const SHOTS = [
  { style: 'classic', mode: 'light', viewport: DESKTOP },
  { style: 'classic', mode: 'dark', viewport: DESKTOP },
  { style: 'mission-control', mode: 'light', viewport: DESKTOP },
  { style: 'mission-control', mode: 'dark', viewport: DESKTOP },
  { style: 'classic', mode: 'light', viewport: PHONE },
  { style: 'classic', mode: 'dark', viewport: PHONE },
  { style: 'mission-control', mode: 'light', viewport: PHONE },
  { style: 'mission-control', mode: 'dark', viewport: PHONE },
];

async function waitForGallery(deadlineMs = 60_000) {
  const until = Date.now() + deadlineMs;
  while (Date.now() < until) {
    try {
      const response = await fetch(`${BASE}/gallery.html`);
      if (response.ok) return;
    } catch {
      /* not up yet */
    }
    await new Promise((resolveWait) => setTimeout(resolveWait, 250));
  }
  throw new Error(`the gallery dev server did not answer on ${BASE} within a minute`);
}

const child = spawn(
  process.execPath,
  [join(web, 'tests', 'support', 'serve-gallery.mjs'), String(PORT)],
  {
    cwd: web,
    stdio: 'inherit',
  },
);

mkdirSync(outDir, { recursive: true });
const pngDir = mkdtempSync(join(tmpdir(), 'zoomies-gallery-png-'));
const browser = await chromium.launch();
try {
  await waitForGallery();
  for (const shot of SHOTS) {
    const page = await browser.newPage({ viewport: shot.viewport });
    await page.goto(`${BASE}/gallery.html?style=${shot.style}&mode=${shot.mode}`, {
      waitUntil: 'domcontentloaded',
    });
    await page.getByRole('heading', { level: 1, name: 'Component gallery', exact: true }).waitFor();
    // The fonts and the grid's first fetch both land after the heading; a
    // capture with a fallback typeface or skeleton rows is not the state.
    await page.evaluate(() => document.fonts.ready);
    await page.locator('table[role="grid"] tbody tr[data-row]').first().waitFor();
    await page.waitForTimeout(250);
    const name = `gallery-${shot.style}-${shot.mode}-${shot.viewport.width}`;
    await page.screenshot({
      path: join(pngDir, `${name}.png`),
      fullPage: true,
      animations: 'disabled',
      caret: 'hide',
    });
    await page.close();
    console.log(`  captured ${name}`);
  }
  console.log(`encoding into ${outDir}`);
  encodeWebp(pngDir, outDir);
} finally {
  await browser.close();
  if (child.exitCode === null) {
    child.kill('SIGTERM');
    // Wait for the wrapper to take Vite down with it, so the captured files
    // are the last thing on the port and the process list is clean.
    await new Promise((resolveExit) => child.once('exit', resolveExit));
  }
  rmSync(pngDir, { recursive: true, force: true });
}
console.log(`wrote ${SHOTS.length} gallery captures to ${outDir}`);

// The look a capture pass is photographing, and how to tell the page opened on it.
//
// An empty browser opens on Mission Control in the dark theme whatever the
// operating system says, so a pass that means light, or Classic, has to say so in
// storage: emulating the system's colour scheme no longer reaches a browser that
// has chosen nothing. A runner that leaned on the emulation wrote dark pictures
// into *-light.webp and Mission Control ones into the Classic set.

/** @typedef {'light' | 'dark'} Scheme */
/** @typedef {'classic' | 'mission-control'} Style */

/**
 * What a pass stores in the browser before the app runs, under the keys the app
 * reads them from. Both are written for either style, Classic included: Classic is
 * only remembered when it is stored.
 *
 * @param {Scheme} scheme
 * @param {Style} style
 * @returns {Record<string, string>}
 */
export function storedLook(scheme, style) {
  return { 'zoomies.theme': scheme, 'zoomies.ui-style': style };
}

/**
 * What the root element carries once the page has booted on that look: the theme
 * as an attribute, and the style only when it is not Classic.
 *
 * @param {Scheme} scheme
 * @param {Style} style
 * @returns {{ theme: string, style: string | null }}
 */
export function expectedLook(scheme, style) {
  return { theme: scheme, style: style === 'mission-control' ? 'mission-control' : null };
}

/**
 * Store a look before the page's own scripts run. Playwright sends this function
 * to the browser as text, so it names nothing from this file.
 *
 * @param {Record<string, string>} stored
 */
export function rememberLook(stored) {
  for (const [key, value] of Object.entries(stored)) localStorage.setItem(key, value);
}

/**
 * Stop the run unless the page it has just opened is on the look the pass asked
 * for, so a picture is never filed under a look it does not show.
 *
 * @param {{ evaluate: (read: () => { theme: string | null, style: string | null }) => Promise<{ theme: string | null, style: string | null }> }} page
 * @param {string} name  The shot, for the message.
 * @param {Scheme} scheme
 * @param {Style} style
 */
export async function assertLook(page, name, scheme, style) {
  const want = expectedLook(scheme, style);
  const got = await page.evaluate(() => ({
    theme: document.documentElement.getAttribute('data-theme'),
    style: document.documentElement.getAttribute('data-ui-style'),
  }));
  if (got.theme === want.theme && got.style === want.style) return;
  const words = (/** @type {string | null} */ theme, /** @type {string | null} */ look) =>
    `${theme ?? 'system'} ${look ?? 'classic'}`;
  throw new Error(
    `${name} opened on ${words(got.theme, got.style)} but this pass is ${words(want.theme, want.style)}. ` +
      `The picture would be filed under the wrong look, so the run stops here: ` +
      `check that the pass stores its look (support/look.mjs) and that the app still reads it.`,
  );
}

// The documentation's sample repair history. This runs only against the
// screenshot harness's disposable database while its controller is stopped.
// It neither calls a model nor contacts GitHub. Terminal states are saved
// before restart, so the repair worker has nothing to execute.
package main

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

func main() {
	if err := seed(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func seed() error {
	if len(os.Args) != 2 {
		return fmt.Errorf("expected the screenshot database path")
	}
	path := filepath.Clean(os.Args[1])
	if filepath.Base(path) != "zoomies.db" || !strings.HasPrefix(filepath.Base(filepath.Dir(path)), "zoomies-screenshots-") {
		return fmt.Errorf("refusing to seed a database outside the screenshot fixture")
	}
	ctx := context.Background()
	// A clock that moves on each time it is read, so the samples began some time ago and
	// took a while, as repairs do, instead of all starting and ending in one instant.
	clock := time.Now().Add(-26 * time.Hour)
	st, err := store.Open(ctx, store.Options{Path: path, Now: func() time.Time {
		clock = clock.Add(41 * time.Second)
		return clock
	}})
	if err != nil {
		return err
	}
	defer st.Close()
	user, err := st.GetUserByUsername(ctx, "alice")
	if err != nil {
		return err
	}
	inst, err := st.FindInstallationByTarget(ctx, "acme/widgets")
	if err != nil {
		return err
	}
	for _, sample := range []struct {
		pull                             int
		state, message, stage, failure   string
		commit, title, branch, job, step string
	}{
		{42, "succeeded", "Sample repair: corrected a failing assertion; the PR checks passed. Normal review is still required.", "checks_passed", "",
			"7c0d1ab9e3f24b6a1d8c5e0f7a2b4c6d8e1f3a5b", "Retry transient 502s in the registry client", "fix/registry-retry", "Go (api-2)", "Run go test -race ./internal/..."},
		{43, "blocked", "Sample repair: workflow edits are disabled for this repository. Review the policy before another attempt.", "prepare_fix", "unsupported_fix",
			"", "Pin the base image digest in the runner Dockerfile", "chore/pin-base-digest", "Build runner image", "docker build"},
		{44, "failed", "Sample repair: Eli could not produce a fix it was willing to push.", "prepare_fix", "unsupported_fix",
			"", "Show the retention window on the Usage page", "feat/usage-retention", "UI (e2e)", "Playwright"},
	} {
		// What the repair was about, kept as it was when it began, so the pages show the
		// pull request and the job that failed and not only a number.
		const run = 4820
		kept := &store.EliRepairCase{
			PullTitle: sample.title,
			PullURL:   fmt.Sprintf("https://github.com/acme/widgets/pull/%d", sample.pull),
			Author:    "alice", Branch: sample.branch,
			RunURL:   fmt.Sprintf("https://github.com/acme/widgets/actions/runs/%d", run),
			Workflow: "CI", RunNumber: run,
			Jobs: []store.EliRepairCaseJob{{
				Name: sample.job, Step: sample.step, DurationMS: 192000,
				URL: fmt.Sprintf("https://github.com/acme/widgets/actions/runs/%d/job/%d", run, 90000+sample.pull),
			}},
		}
		r := &store.EliRepair{
			DedupKey: fmt.Sprintf("screenshots:%d", sample.pull), InstallationID: inst.ID,
			Repo: "acme/widgets", PullNumber: sample.pull, RunID: run, UserID: user.ID,
			GitHubLogin: "alice", Trigger: "manual", CommitSHA: sample.commit,
			Details: store.EliRepairDetails{Model: "demo (sample history)", Stage: sample.stage, FailureCode: sample.failure, Case: kept},
		}
		// A repair that got as far as the model made calls, and one provider did not report usage
		// for, which the page says is unknown and never shows as zero.
		if sample.state != "blocked" {
			r.Details.SourceBytes = 38912
			r.Details.Steps = []store.EliRepairStep{
				{InputTokens: 21400, OutputTokens: 1800, UsageReported: true, RequestBytes: 80312, ElapsedMS: 41000},
				{RequestBytes: 91234, ElapsedMS: 9000},
			}
		}
		if _, err := st.EnqueueEliRepair(ctx, r, 5); err != nil {
			return err
		}
		r.State, r.Message = sample.state, sample.message
		if err := st.SaveEliRepair(ctx, r); err != nil {
			return err
		}
	}
	return seedAutomatic(ctx, st, inst.ID, &clock)
}

// seedAutomatic makes two repositories repair themselves, with an installation
// provider to pay for it and a few repairs the policy started, so the hub shows its
// Automatic repairs panel and an attempt shows the card that says where its policy
// stands. The repairs are recent, inside the 24-hour window the allowance counts, and
// every one is terminal, so the worker has nothing to run.
func seedAutomatic(ctx context.Context, st *store.Store, installation string, clock *time.Time) error {
	provider := &store.AssistantProvider{Name: "Team provider (sample)", Kind: "fake", Model: "demo", Enabled: true}
	if err := st.CreateAssistantProvider(ctx, provider); err != nil {
		return err
	}
	for _, repo := range []string{"acme/gateway", "acme/docs"} {
		if err := st.SetEliRepairPolicy(ctx, store.EliRepairPolicy{
			Repo: repo, InstallationID: installation, ProviderID: provider.ID,
			Enabled: true, Automatic: true, DailyLimit: 5,
		}); err != nil {
			return err
		}
	}
	*clock = time.Now().Add(-5 * time.Hour)
	for _, sample := range []struct {
		repo                             string
		pull                             int
		state, message, stage, failure   string
		commit, title, branch, job, step string
	}{
		{"acme/gateway", 109, "checks_failed", "Sample repair: Eli's commit did not make the checks pass. Automatic repair does not try the same commit twice; a maintainer can ask again.", "watch_ci", "",
			"3a9e5c7d1f0b2468ace02468ace13579bdf02468", "Cap the retry budget in the gateway client", "feat/gateway-retry-cap", "Go (gateway)", "Run go test ./..."},
		{"acme/gateway", 112, "succeeded", "Sample repair: restored the missing nil check; the PR checks passed. Normal review is still required.", "checks_passed", "",
			"b2d4f6081a3c5e7092b4d6f8a0c2e4681a3c5e70", "Add a retry budget to the gateway client", "feat/gateway-retry-budget", "Go (gateway)", "Run go test ./..."},
		{"acme/docs", 31, "failed", "Sample repair: Eli could not produce a fix it was willing to push.", "prepare_fix", "unsupported_fix",
			"", "Fix the broken link check on the install page", "docs/fix-link-check", "Docs build", "mkdocs build --strict"},
	} {
		const run = 5210
		// A commit that looks like one: forty hex digits with no run of zeros at the front.
		head := fmt.Sprintf("%016x%016x%08x", uint64(sample.pull)*0x9e3779b97f4a7c15, uint64(sample.pull)*0xc2b2ae3d27d4eb4f, uint32(sample.pull)*0x85ebca6b)
		kept := &store.EliRepairCase{
			PullTitle: sample.title,
			PullURL:   fmt.Sprintf("https://github.com/%s/pull/%d", sample.repo, sample.pull),
			Author:    "alice", Branch: sample.branch,
			RunURL:   fmt.Sprintf("https://github.com/%s/actions/runs/%d", sample.repo, run+sample.pull),
			Workflow: "CI", RunNumber: run + int64(sample.pull),
			Jobs: []store.EliRepairCaseJob{{
				Name: sample.job, Step: sample.step, DurationMS: 143000,
				URL: fmt.Sprintf("https://github.com/%s/actions/runs/%d/job/%d", sample.repo, run+sample.pull, 91000+sample.pull),
			}},
		}
		r := &store.EliRepair{
			DedupKey: "automatic:" + sample.repo + ":" + head, InstallationID: installation,
			Repo: sample.repo, PullNumber: sample.pull, RunID: int64(run + sample.pull), HeadSHA: head,
			ProviderID: provider.ID, Trigger: "automatic", CommitSHA: sample.commit,
			Details: store.EliRepairDetails{Model: "demo (sample history)", Stage: sample.stage, FailureCode: sample.failure, Case: kept,
				SourceBytes: 27648,
				Steps:       []store.EliRepairStep{{InputTokens: 18200, OutputTokens: 1400, UsageReported: true, RequestBytes: 61440, ElapsedMS: 33000}},
			},
		}
		if _, err := st.EnqueueEliRepair(ctx, r, 5); err != nil {
			return err
		}
		r.State, r.Message = sample.state, sample.message
		if err := st.SaveEliRepair(ctx, r); err != nil {
			return err
		}
	}
	return nil
}

/**
 * A stand-in for the controller's API, as far as the Eli repair pages reach it.
 *
 * The repair specs drive the real UI against stubbed answers, so each test says
 * exactly what the controller said (the run's failed jobs, what readiness found,
 * what a job's log held) and then checks what the page did with it, including
 * the writes that must never happen on a read. The helper answers every other
 * request with an empty list, so the shell around the page stays quiet.
 *
 * State is returned, not hidden: a test that needs the controller to change its
 * mind between two reads (the checks passed while the page was open) changes
 * `state` and presses the button again.
 */
import type { Page } from '@playwright/test';
import type { Job, Schemas } from '../../src/lib/api/types';

export type Readiness = Schemas['EliReadiness'];
export type Check = Schemas['EliReadinessCheck'];
export type Repair = Schemas['EliRepair'];

export interface RepairApiState {
  role: 'viewer' | 'operator' | 'admin';
  /** The failed jobs of the run, as `GET /jobs` lists them. */
  jobs: Job[];
  /** What readiness answers; a function sees the query it was asked with. */
  readiness: Readiness | ((query: URLSearchParams) => Readiness);
  /** Error output by GitHub's job id. A status says the controller refused. */
  errorOutput: Record<
    string,
    { lines: string[]; note?: string } | { status: number; message: string }
  >;
  /**
   * The history `GET /assistant/repairs` lists, which is where an active repair is
   * found. The stub answers `group`, `limit` and `offset` as the controller does.
   */
  repairs: Repair[];
  /** What `GET /assistant/repairs/settings` answers: who is linked and the repository policies. */
  settings: Schemas['EliRepairSettings'];
  /** Repair offers. */
  offers: Schemas['EliOpportunity'][];
  /** What starting a repair answers: a status and a body. */
  start: { status: number; body: unknown } | (() => { status: number; body: unknown });
  /**
   * What `GET /assistant/repairs/{id}` answers, by id: the repair, or the status
   * the controller answers with. An id named nowhere here is a 404, which is what
   * a repair that does not exist and one that is not yours both get. A test moves
   * a repair on by replacing its entry and letting the page ask again.
   */
  attempts: Record<string, Repair | { status: number; message: string }>;
  /**
   * What `GET /assistant/repairs/automatic` answers: the repositories that repair
   * themselves, or the status the controller refuses with.
   */
  automatic: Schemas['EliAutomaticRepository'][] | { status: number; message: string };
  /**
   * What `POST /assistant/repairs/automatic/stop` answers. Left null, the stub does
   * what the controller does: each repository that is automatic stops being, and
   * leaves the overview and the policies' automatic count; one that is not is
   * `changed: false`.
   */
  stop: ((body: { repos: string[]; then: string }) => { status: number; body: unknown }) | null;
}

export interface RepairApiCalls {
  jobs: URLSearchParams[];
  readiness: URLSearchParams[];
  errorOutput: URLSearchParams[];
  /** The bodies of every `POST /assistant/repairs`. */
  starts: unknown[];
  /** The offer ids and bodies of every accept or dismiss. */
  offerActions: { id: string; body: unknown }[];
  /** The id of every `GET /assistant/repairs/{id}`, in the order they were asked. */
  attempts: string[];
  /** The query of every `GET /assistant/repairs`, which is the history and the running list. */
  lists: URLSearchParams[];
  /** How many times the offers were read. */
  offerReads: number;
  /** How many times the automatic repairs overview was read. */
  automaticReads: number;
  /** The body of every stop. */
  stops: { repos: string[]; then: string }[];
}

const ACTIVE = ['queued', 'working', 'checking'];

export const SHA = 'a41c9e2f0b7d5c3e8a1f6d4b2c9e7a5f3d1b8c6e';

/**
 * The commit a repair in the world is working on. It is not the head readiness
 * reports (`SHA`): a repair on the very commit a page is about is the one that page
 * follows, so a world whose running repair sat on `SHA` would move the repair page to
 * the attempt before anything could be audited on it.
 */
export const EARLIER_HEAD = '3f9c1d7a5b2e4c8d6a0f1e9b7d5c3a2e4f6b8d0c';

const CHECK_ORDER: Check['code'][] = [
  'identity',
  'provider',
  'installation',
  'access',
  'policy',
  'budget',
  'pull',
  'checks',
  'permissions',
];

export const allOk = (): Check[] =>
  CHECK_ORDER.map((code): Check => ({ code, status: 'ok', message: `${code} is fine.` }));

/**
 * The checks as the controller answers when `code` stops it: the rest are never reached.
 * `blocker` is the code of the blocker that stopped it, which says why, not only where.
 */
export function stoppedAt(code: Check['code'], message: string, blocker?: string): Check[] {
  const at = CHECK_ORDER.indexOf(code);
  return CHECK_ORDER.map((c, i): Check =>
    i < at
      ? { code: c, status: 'ok', message: `${c} is fine.` }
      : i === at
        ? { code: c, status: 'blocked', message, ...(blocker ? { blocker } : {}) }
        : { code: c, status: 'unchecked', message: 'Not checked yet.' },
  );
}

