// Lossless WebP encoding for the committed captures, through Pillow.
//
// The browser can write WebP itself, but its encoder compresses these pages
// several times worse than Pillow's, and a documentation gallery that is
// hundreds of kilobytes per page stops being worth committing. Pillow's
// lossless mode keeps every pixel while making a full refresh practical, so
// the browser writes PNGs to a temporary directory and this turns them into
// the files that are committed.
//
// `npm` does not install this: the site build already needs Python, and
// `pip install pillow` is the one prerequisite, named in docs/ui-guidelines.md.

import { spawnSync } from 'node:child_process';

/** Encode every PNG in `pngDir` as lossless WebP in `outDir`. */
export function encodeWebp(pngDir, outDir) {
  const script = [
    'import pathlib, sys',
    'from PIL import Image',
    'src, dst = map(pathlib.Path, sys.argv[1:3])',
    'for png in sorted(src.glob("*.png")):',
    '    out = dst / (png.stem + ".webp")',
    // Lossless WebP's quality controls compression effort, not image quality.
    // This keeps every pixel while making a full-gallery refresh practical.
    '    Image.open(png).convert("RGB").save(out, lossless=True, quality=80, method=4)',
    '    print(f"  {out.name}  {out.stat().st_size // 1024} KB")',
  ].join('\n');
  const run = spawnSync('python3', ['-u', '-c', script, pngDir, outDir], { stdio: 'inherit' });
  if (run.error || run.status !== 0) {
    throw new Error(
      'encoding the screenshots needs Python 3 with Pillow: pip install pillow\n' +
        `(python3 ${run.error ? `could not start: ${run.error.message}` : `exited ${run.status}`})`,
    );
  }
}

/**
 * Every default table fits the window it is shown in.
 *
 * A table that scrolls sideways hides the column somebody is looking for behind
 * a gesture they have no reason to try, and takes the row's name off the left
 * edge the moment they do -- so the value they scrolled to belongs to a row they
 * can no longer name. The grids therefore divide whatever width there is and
 * truncate, and on a phone each row becomes a card and reads down instead.
 *
 * This is the file that holds that to be true, at the widths the product claims
 * to support: the reference desktop, the two documented breakpoints and either
 * side of them, and the two phone widths the mobile project uses.
 *
 * Two layouts are exempt, and say so where they are measured: a phone whose grids
 * are in the row layout scrolls its table inside the grid's own frame, because
 * ten columns do not divide 360 pixels. That is the trade the layout exists to
 * make and the reason Cards is one press away; what is never exempt is the page,
 * which is measured here in both layouts, each pressed rather than assumed, since
 * which of the two a fresh grid starts in depends on the visual style. The other
 * is a desktop layout the operator deliberately widened: that table scrolls in
 * its frame rather than silently shrinking some other column behind the
 * resize handle.
 */
import { expect, test, type Page } from '@playwright/test';
import {
  dataRows,
  goto,
  grid,
  rowCount,
  SECTIONS,
  sectionHeading,
  waitForRows,
} from './support/fixtures';

/** Every page whose main content is a grid, with the name its table carries. */
const GRIDS = [
  { path: '/runners', heading: 'Runners', label: 'Runners' },
  { path: '/workflows?state=completed', heading: 'Workflows', label: 'Workflow runs' },
  { path: '/jobs?state=completed', heading: 'Jobs', label: 'Jobs' },
  { path: '/pools', heading: 'Pools', label: 'Pools' },
  { path: '/queue', heading: 'Queue', label: 'Provisioning queue' },
  { path: '/audit', heading: 'Audit', label: 'Audit log' },
] as const;

/**
 * The widths that matter: the reference desktop the screenshots are taken at,
 * `--z-bp-lg` and just below it, `--z-bp-md`, and the two phone widths.
 */
const WIDTHS = [1440, 1180, 1179, 768, 412, 360] as const;

/** `--z-bp-md`, as a `max-width`: at this width and below, a row can be a card. */
const PHONE_BREAKPOINT = 768;

/** The two of those the mobile project runs at. */
const PHONES = [412, 360] as const;

/**
 * Put a phone-width grid into one of its two layouts, the way an operator does.
 *
 * A fresh grid is Cards under Mission Control, the default, and Rows under
 * Classic, so neither can be assumed as the start. The promise this file holds
 * -- a table that fits its frame -- is the card layout's below the phone
 * threshold, and the row layout's is that the page holds still around it.
 * Pressed rather than written into storage, because a preference set behind
 * the UI's back is a preference this suite would keep passing on after the
 * control that sets it broke.
 */
async function chooseLayout(page: Page, name: 'Cards' | 'Rows'): Promise<void> {
  const layout = page.getByRole('button', { name: new RegExp(`^${name}\\b`) });
  await layout.click();
  await expect(layout).toHaveAttribute('aria-pressed', 'true');
}

const chooseCards = (page: Page) => chooseLayout(page, 'Cards');
const chooseRows = (page: Page) => chooseLayout(page, 'Rows');

/**
 * How far the table overflows the frame around it, and how far the document
 * overflows the window.
 *
 * Both, because they fail separately: a table can stay inside a frame that is
 * itself too wide for the page, and a page can hold together while the table in
 * it is quietly cut off.
 */
async function overflow(page: Page, label: string): Promise<{ table: number; document: number }> {
  return grid(page, label).evaluate((table) => {
    const frame = table.parentElement as HTMLElement;
    return {
      table: table.scrollWidth - frame.clientWidth,
      document: document.documentElement.scrollWidth - document.documentElement.clientWidth,
    };
  });
}

/** Every table on the page, against the box each one is drawn in. */
async function expectTablesFit(page: Page, where: string): Promise<void> {
  const measured = await page.evaluate(() =>
    [...document.querySelectorAll('table')].map((table) => ({
      caption: (table.caption?.textContent ?? table.getAttribute('aria-label') ?? '?').trim(),
      over: table.scrollWidth - (table.parentElement as HTMLElement).clientWidth,
    })),
  );
  expect(measured.length, `${where} has a table to measure`).toBeGreaterThan(0);
  for (const { caption, over } of measured) {
    expect(over, `${caption} is wider than its frame, in ${where}`).toBeLessThanOrEqual(1);
  }
}

/**
 * A host's name is whatever its agent called itself, up to 128 characters, and the
 * agent is the actor of its own join in the audit log. The seeded fleet's names are
 * short, so a card that cannot hold a long one passes every width above and fails
 * the first operator whose hosts are named after their cloud's addresses.
 */
test('a long actor name is cut short in the Audit card instead of widening it', async ({
  page,
}) => {
  await page.setViewportSize({ width: 360, height: 900 });
  const minted = await page.request.post('/api/v1/join-tokens', {
    data: { ttl: '15m', capacity: 1 },
  });
  expect(minted.ok(), 'a join token was minted').toBeTruthy();
  const { token } = (await minted.json()) as { token: string };
  const name = `ip-10-0-12-34.eu-west-1.compute.internal-${'a'.repeat(60)}`;
  const join = await page.request.post('/api/v1/agent/join', {
    data: {
      protocol_version: 1,
      join_token: token,
      name,
      capacity: 1,
      os: 'linux',
      arch: 'amd64',
      version: 'dev',
      backends: [{ kind: 'docker', available: true }],
    },
  });
  expect(join.ok(), 'the agent joined under its long name').toBeTruthy();
  const { host_id: hostId } = (await join.json()) as { host_id: string };
  try {
    await goto(page, '/audit', 'Audit');
    await waitForRows(grid(page, 'Audit log'));
    await chooseCards(page);
    // The row is on the page, so the measure below is of a card that holds the name.
    const actor = page.locator('.actor-name', { hasText: name }).first();
    await expect(actor).toBeVisible();
    const measured = await overflow(page, 'Audit log');
    expect(measured.table, 'the Audit card is wider than its frame').toBeLessThanOrEqual(1);
    expect(measured.document, 'the Audit page scrolls sideways').toBeLessThanOrEqual(1);
    // Cut short rather than dropped: the full name is still the cell's text.
    expect(
      await actor.evaluate((el) => el.scrollWidth > el.clientWidth),
      'the name is ellipsised',
    ).toBe(true);
  } finally {
    await page.request.delete(`/api/v1/hosts/${hostId}`);
  }
});

for (const width of WIDTHS) {
  test(`no grid scrolls sideways at ${width}px`, async ({ page }) => {
    await page.setViewportSize({ width, height: 900 });

    // `--z-bp-md` is a `max-width`, so 768 is itself a phone: the card layout
    // is offered at every width in this list up to and including it.
    const phone = width <= PHONE_BREAKPOINT;

    for (const { path, heading, label } of GRIDS) {
      await goto(page, path, heading);
      await waitForRows(grid(page, label));

      // The page is measured in the table layout first: a grid that scrolls
      // inside its own frame must not take the document with it. On a phone that
      // is the row layout, pressed, because a fresh grid starts as Cards under
      // Mission Control. Above the threshold every grid is the table already.
      if (phone) await chooseRows(page);
      const rows = await overflow(page, label);
      expect(rows.document, `the ${heading} page scrolls sideways`).toBeLessThanOrEqual(1);

      // Then the card layout, whose table is the one that has to fit its frame.
      if (phone) await chooseCards(page);

      // A pixel of slack: the columns are shared out by arithmetic, and a
      // fractional width rounded up is not a table anybody can scroll.
      const measured = await overflow(page, label);
      expect(measured.table, `the ${heading} table is wider than its frame`).toBeLessThanOrEqual(1);
      expect(measured.document, `the ${heading} page scrolls sideways`).toBeLessThanOrEqual(1);
    }
  });
}

/*
 * The tables are the hard half of fitting a phone, but they are not the whole
 * claim: a page that holds its tables inside the window and then puts a chart,
 * a wizard or a row of buttons through the side of it is still a page nobody
 * can read one-handed. So every section is walked at both phone widths, and
 * the document itself is measured.
 *
 * The whole document rather than a chosen element, because whatever is too wide
 * is by definition the thing nobody thought to measure -- and the failure names
 * what stuck out, so the next person does not have to go looking for it.
 */
for (const width of PHONES) {
  test(`no page scrolls sideways at ${width}px`, async ({ page }) => {
    await page.setViewportSize({ width, height: 900 });

    for (const section of SECTIONS) {
      await goto(page, section.path, sectionHeading(section));

      // Polled, because a page settles: a grid's columns are shared out once
      // it has measured its frame, and a skeleton one frame wide is not a
      // mobile view anybody sees.
      const culprits = async (): Promise<string[]> =>
        page.evaluate(() => {
          const root = document.documentElement;
          // A pixel of slack, for the same reason the tables get one.
          if (root.scrollWidth - root.clientWidth <= 1) return [];
          return [...document.querySelectorAll<HTMLElement>('main *')]
            .filter((el) => el.getBoundingClientRect().right > root.clientWidth + 1)
            .map((el) => `${el.tagName.toLowerCase()}.${el.className?.toString().trim()}`)
            .slice(0, 5);
        });
      await expect
        .poll(culprits, { message: `${sectionHeading(section)} scrolls sideways at ${width}px` })
        .toEqual([]);
    }
  });
}

