test('a large instance archive stays below a proxy request limit and failed verification cannot import it', async ({
  page,
}) => {
  // A sparse file exercises the browser's file path without allocating the
  // complete archive in the test runner. Its contents are deliberately invalid.
  const { mkdtempSync, openSync, ftruncateSync, closeSync, rmSync } = await import('node:fs');
  const { tmpdir } = await import('node:os');
  const { join } = await import('node:path');
  const dir = mkdtempSync(join(tmpdir(), 'zoomies-large-transfer-'));
  const path = join(dir, 'large-instance.zbk');
  const size = 106910 * 1024;
  const fd = openSync(path, 'w');
  ftruncateSync(fd, size);
  closeSync(fd);
  const chunks: number[] = [];
  try {
    await page.route('**/api/v1/transfers/**', async (route) => {
      const request = route.request();
      const length = request.postDataBuffer()?.byteLength ?? 0;
      if (request.url().includes('/chunks?')) chunks.push(length);
      if (length > 8 * 1024 * 1024)
        await route.fulfill({ status: 413, body: 'Proxy request limit exceeded' });
      else await route.continue();
    });
    await goto(page, '/settings/backups', 'Backups');
    await page
      .locator('summary')
      .getByText('Bring an instance to this controller', { exact: true })
      .click();
    await page.getByLabel('Encrypted instance archive', { exact: true }).setInputFiles(path);
    await page
      .getByLabel('Archive passphrase', { exact: true })
      .last()
      .fill('large archive passphrase');
    await page.getByRole('button', { name: 'Verify archive', exact: true }).click();
    await expect(
      page.getByText(/That file is not an instance archive this controller can use/),
    ).toBeVisible({ timeout: 30000 });
    expect(chunks).toHaveLength(14);
    expect(chunks.every((n) => n > 0 && n <= 8 * 1024 * 1024)).toBeTruthy();
    expect(chunks.reduce((sum, n) => sum + n, 0)).toBe(size);
    await expect(page.getByRole('button', { name: 'Import and restart', exact: true })).toHaveCount(
      0,
    );
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

/**
 * Two-step verification, from turning it on to signing in with it.
 *
 * It runs on the first-run controller -- authentication on -- after
 * first-run.spec.ts has created the account it signs in with, because under
 * the shared harness authentication is off and there is no sign-in to add a
 * step to. The steps are serial: each one leaves the account in the state the
 * next one starts from, and the last turns two-step off again.
 *
 * The authenticator app is RFC 6238 written out below with node:crypto, so
 * the test types the code a phone would show rather than one the server told
 * it.
 */
import { createHmac } from 'node:crypto';
import { test, expect, type Page } from '@playwright/test';
import { setupToken, useSystemTheme } from './support/fixtures';

const ADMIN = { username: 'ada', password: 'correct horse battery staple' };

test.describe.configure({ mode: 'serial' });

/** The six digits an authenticator app shows for this key at this moment. */
function totp(secret: string, at = Date.now()): string {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  let bits = '';
  for (const ch of secret.replace(/\s+/g, '')) {
    bits += alphabet.indexOf(ch).toString(2).padStart(5, '0');
  }
  const key = Buffer.alloc(Math.floor(bits.length / 8));
  for (let i = 0; i < key.length; i++) key[i] = parseInt(bits.slice(i * 8, i * 8 + 8), 2);
  const counter = Buffer.alloc(8);
  counter.writeBigUInt64BE(BigInt(Math.floor(at / 1000 / 30)));
  const mac = createHmac('sha1', key).update(counter).digest();
  const offset = mac.readUInt8(mac.length - 1) & 0x0f;
  const value = (mac.readUInt32BE(offset) & 0x7fffffff) % 1_000_000;
  return String(value).padStart(6, '0');
}

let secret = '';
let recovery: string[] = [];

/** One of the recovery codes the first test was shown. */
function spare(i: number): string {
  const code = recovery[i];
  if (!code) throw new Error(`there is no recovery code ${i}; did the first test run?`);
  return code;
}

/**
 * The account first-run.spec.ts makes. Created here when this file runs on
 * its own, so it does not depend on being run after the other one.
 */
async function ensureAccount(page: Page): Promise<void> {
  const meta = await (await page.request.get('/api/v1/meta')).json();
  if (!meta.bootstrap_required) return;
  const res = await page.request.post('/api/v1/auth/bootstrap', {
    data: { ...ADMIN, setup_token: setupToken() },
  });
  expect(res.ok()).toBeTruthy();
}

async function password(page: Page): Promise<void> {
  await page.context().clearCookies();
  await page.goto('/login');
  await page.fill('input[name="username"]', ADMIN.username);
  await page.fill('input[name="password"]', ADMIN.password);
  await page.getByRole('button', { name: 'Sign in' }).click();
}

