/** A run's name is not a pattern: it carries slashes and dots of its own. */
function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/*
 * The Queue page's controls, on a run and on the jobs inside it. An operator
 * who knows the run from a pull request should be able to hold or hurry all
 * of it from its row, and one job of it from the row under that, without
 * going to the Queue page and finding the same jobs there by name.
 */
test('a run and the jobs inside it take the Queue page’s controls', async ({ page, request }) => {
  // A queued run this fleet has a hand in, and its queued jobs.
  const response = await request.get(
    '/api/v1/workflow-runs?state=queued&managed=true&cancelling=false&limit=1&sort=queued_at&order=asc',
  );
  const { items } = await response.json();
  expect(items.length).toBeGreaterThan(0);
  const run = items[0];
  const number = run.run_number || run.github_run_id;
  const subject = `${run.repo} · ${run.workflow || 'workflow'} #${number}`;
  const jobsResponse = await request.get(
    `/api/v1/jobs?repo=${encodeURIComponent(run.repo)}&run_id=${run.github_run_id}&state=queued`,
  );
  const queuedJobs: { id: string; job_name: string; repo: string }[] = (await jobsResponse.json())
    .items;
  expect(queuedJobs.length).toBeGreaterThan(0);
  const ids = queuedJobs.map((job) => job.id);
  try {
    await goto(page, `/workflows?state=queued&repo=${encodeURIComponent(run.repo)}`, 'Workflows');
    const row = dataRows(runs(page))
      .filter({ hasText: `#${number}` })
      .first();
    await expect(row).toBeVisible();

    // Pause on the run's row is one press and a confirmation, and every
    // queued job of the run is paused by it. The row says so itself, and
    // pressing Pause again is refused with the reason.
    await row.getByRole('button', { name: `Pause: ${subject}`, exact: true }).click();
    await page.getByRole('dialog').getByRole('button', { name: 'Pause', exact: true }).click();
    await expect(row).toContainText(/paused/i);
    for (const id of ids) {
      const job = await (await request.get(`/api/v1/jobs/${id}`)).json();
      expect(job.state).toBe('queued');
      expect(job.provisioning).toBe('paused');
    }
    const pause = row.getByRole('button', {
      name: new RegExp(`^Pause: ${escapeRegExp(subject)}\\.`),
    });
    await expect(pause).toHaveAttribute('aria-disabled', 'true');
    await expect(pause).toHaveAccessibleName(/already paused/);

    // Inside the run, each job wears the hold, and Run now on one of them
    // lifts that job alone: the endpoint is the Queue page's own, and so is
    // the state it leaves behind.
    await row.getByRole('button', { name: 'Show jobs' }).click();
    const jobs = page.getByRole('table', { name: `Jobs in run #${number}` });
    await expect(jobs).toBeVisible();
    const first = queuedJobs[0];
    if (!first) throw new Error('expected at least one queued job');
    const jobRow = jobs.locator('tbody tr').filter({ hasText: first.job_name }).first();
    await expect(jobRow).toContainText('Paused');
    await jobRow
      .getByRole('button', { name: `Run now: ${first.job_name} in ${first.repo}`, exact: true })
      .click();
    await page.getByRole('dialog').getByRole('button', { name: 'Run now', exact: true }).click();
    await expect(jobRow).toContainText('Run now');
    const updated = await (await request.get(`/api/v1/jobs/${first.id}`)).json();
    expect(updated.state).toBe('queued');
    expect(updated.provisioning).toBe('');
    expect(updated.provision_now).toBe(true);
  } finally {
    await request.post('/api/v1/provisioning/bulk', { data: { ids, action: 'resume' } });
  }
});

{
  // The unit tests run on Node with types stripped, so nothing else compiles
  // them, and a fixture that falls behind the API's shape would go on passing
  // with fields the controller no longer sends. This is the check that says so.
  // The .mjs helpers beside them are plain scripts and are not part of it.
  "extends": "./tsconfig.json",
  "compilerOptions": {
    "allowImportingTsExtensions": true,
    "noEmit": true
  },
  "include": ["unit/**/*.ts"],
  "exclude": ["node_modules", "dist"]
}

import assert from 'node:assert/strict';
import { readdirSync, readFileSync } from 'node:fs';
import { join, relative } from 'node:path';
import test from 'node:test';
import * as format from '../src/lib/format.ts';

const lib = join(import.meta.dirname, '..', 'src');

// Three glyphs for "nothing to show" meant a table cell and the tile above it
// disagreed about what an empty value looks like. The formatters already
// answered with one; the constant is how a page that has no formatter to call
// says the same thing.
test('the formatters and the pages agree on one marker for a missing value', () => {
  assert.equal(format.NO_VALUE, '--');
  for (const missing of [
    format.formatAbsolute(null),
    format.formatDuration(null),
    format.formatNumber(null),
  ]) {
    assert.equal(missing, format.NO_VALUE);
  }
});

// The first version of this guard named nine pages, and the next page to write
// a dash of its own was the tenth: two host-health views did exactly that. So it
// reads every source file, not the ones somebody remembered.
function sources(dir: string): string[] {
  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) return sources(path);
    return /\.(svelte|ts)$/.test(entry.name) ? [path] : [];
  });
}

// A dash standing alone as a value: a string literal of one, or one between
// tags, written as the shared marker's two hyphens or as an en or em dash.
// Dashes inside a sentence, number ranges and a quoted "--" in a comment are
// prose, so a double-quoted pair is only caught as an attribute value.
const LONE_DASH = /(['"`])[\u2014\u2013]\1|(?<![\w$"])'--'|="--"|>--<|>[\u2014\u2013]</;

test('no source file writes a missing value with a dash of its own', () => {
  const offenders: string[] = [];
  for (const file of sources(lib)) {
    if (file === join(lib, 'lib', 'format.ts')) continue;
    readFileSync(file, 'utf8')
      .split('\n')
      .forEach((line, i) => {
        if (LONE_DASH.test(line)) offenders.push(`${relative(lib, file)}:${i + 1}`);
      });
  }
  assert.deepEqual(offenders, [], 'import NO_VALUE from format.ts instead of spelling the marker');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { registerHooks } from 'node:module';

const LUCIDE = 'zoomies-test:lucide-stub';
const iconNames = (
  /import\s*\{([^}]*)\}\s*from\s*'@lucide\/svelte'/.exec(
    readFileSync(new URL('../src/lib/status.ts', import.meta.url), 'utf8'),
  )?.[1] ?? ''
)
  .split(',')
  .map((name) => name.trim())
  .filter((name) => name !== '');

registerHooks({
  resolve(specifier, context, next) {
    if (specifier === '@lucide/svelte')
      return { url: LUCIDE, format: 'module', shortCircuit: true };
    return next(specifier, context);
  },
  load(url, context, next) {
    if (url === LUCIDE)
      return {
        format: 'module',
        shortCircuit: true,
        source: iconNames.map((name) => `export function ${name}() {}`).join('\n'),
      };
    return next(url, context);
  },
});

const { queuedActivity, workflowActivity } = await import('../src/lib/jobs/activity-status.ts');

// The four words the Jobs page filters provisioning by, as the fields a job
// carries. A job's own provisioning is "", "paused" or "deleted"; "ready" is the
// first of those and "expedited" is provision_now, so a fixture that wrote the
// filter's words into the field was handing the code a value no job has.
const PROVISIONING = {
  ready: {},
  expedited: { provision_now: true },
  paused: { provisioning: 'paused' },
  deleted: { provisioning: 'deleted' },
} as const;
const { jobEventStatus } = await import('../src/lib/status.ts');

test('queue cancellation overrides priority and pause without claiming work is running', () => {
  for (const demand of Object.values(PROVISIONING)) {
    assert.equal(
      queuedActivity({ ...demand, cancel_requested_at: '2026-09-20T12:00:00Z' }).status.key,
      'cancelling',
    );
  }
  assert.equal(queuedActivity({}).label, 'Sit, wait');
  assert.equal(queuedActivity({ provision_now: true }).status.label, 'Run now');
  assert.equal(
    queuedActivity({ provisioning: 'paused', provision_now: true }).status.label,
    'Paused',
  );
  assert.notEqual(queuedActivity(PROVISIONING.expedited).motion, 'busy');
});

test('workflow pack preserves outcomes and cancellation precedence', () => {
  assert.equal(workflowActivity({ state: 'in_progress' }).motion, 'busy');
  assert.equal(
    workflowActivity({ state: 'in_progress', cancelling: true }).status.key,
    'cancelling',
  );
  assert.equal(workflowActivity({ state: 'completed', conclusion: 'success' }).label, 'Good pack!');
  for (const conclusion of ['failure', 'timed_out', 'startup_failure']) {
    const result = workflowActivity({ state: 'completed', conclusion });
    assert.equal(result.status.key, conclusion);
    assert.equal(result.motion, 'failed');
  }
  assert.equal(workflowActivity({ state: 'completed', conclusion: 'cancelled' }).motion, 'removed');
  assert.equal(workflowActivity({}).motion, 'unknown');
});

test('a run with a failed job says so before GitHub has finished the run', () => {
  // GitHub keeps the run in progress until its last job ends, so the row is
  // the only place the operator sees the failure early. The leader shows it;
  // the rest of the pack keeps the pose the run's own state gives it.
  const failing = workflowActivity({ state: 'in_progress', jobs: { total: 10, failed: 1 } });
  assert.equal(failing.status.key, 'failing');
  assert.equal(failing.status.tone, 'danger');
  assert.equal(failing.label, 'Pack in trouble');
  assert.equal(failing.motion, 'failed');
  assert.equal(failing.packMotion, 'busy');
  assert.match(failing.detail, /1 of its 10 jobs has failed/);

  const queued = workflowActivity({ state: 'queued', jobs: { total: 4, failed: 2 } });
  assert.equal(queued.status.key, 'failing');
  assert.equal(queued.packMotion, 'idle');
  assert.match(queued.detail, /2 of its 4 jobs have failed/);

  assert.equal(
    workflowActivity({ state: 'in_progress', jobs: { failed: 1 } }, false).label,
    'Failing',
  );

  // A cancellation, and a run that has actually finished, still win: the
  // first is the operator's own decision, the second is GitHub's conclusion.
  assert.equal(
    workflowActivity({ state: 'in_progress', cancelling: true, jobs: { failed: 1 } }).status.key,
    'cancelling',
  );
  assert.equal(
    workflowActivity({ state: 'completed', conclusion: 'failure', jobs: { failed: 1 } }).status.key,
    'failure',
  );
  // A re-run that passed leaves nothing failed on the latest attempt.
  assert.equal(workflowActivity({ state: 'in_progress', jobs: { failed: 0 } }).motion, 'busy');
  assert.equal(
    workflowActivity({ state: 'in_progress', jobs: { failed: 0 } }).packMotion,
    undefined,
  );
});

test('turning the kennel vocabulary off gives the plain status word instead, motion unchanged', () => {
  assert.equal(queuedActivity({}, false).label, 'Ready');
  assert.equal(queuedActivity({ provisioning: 'paused' }, false).label, 'Paused');
  assert.equal(queuedActivity({ provisioning: 'deleted' }, false).label, 'Removed');
  assert.equal(queuedActivity({ provision_now: true }, false).label, 'Run now');
  assert.equal(
    queuedActivity({ cancel_requested_at: '2026-09-20T12:00:00Z' }, false).label,
    'Cancelling',
  );
  assert.equal(queuedActivity({}, false).motion, queuedActivity({}).motion);

  assert.equal(workflowActivity({ state: 'in_progress' }, false).label, 'Running');
  assert.equal(
    workflowActivity({ state: 'completed', conclusion: 'success' }, false).label,
    'Success',
  );
  assert.equal(
    workflowActivity({ state: 'in_progress' }, false).motion,
    workflowActivity({ state: 'in_progress' }).motion,
  );
});

/*
 * The Queue's and the Workflows page's row actions: Run now, Pause, Resume,
 * Delete from queue and Re-run. A status drawn with one of them reads as that
 * action -- a paused job with a Pause glyph beside it looked like a button to
 * pause it.
 */
const ACTION_ICONS = ['Zap', 'Pause', 'Play', 'Trash2', 'RotateCcw'];

test('with the vocabulary off, no queue or workflow status is drawn with an action icon', () => {
  const drawn = [
    ...Object.values(PROVISIONING).map((demand) => queuedActivity(demand, false).status),
