import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  archWords,
  capWords,
  isAutomatic,
  limitWords,
  modeHint,
  modeWords,
  pendingWords,
  runnerWords,
  warmWords,
} from '../src/lib/pools/auto.ts';
import type { PoolAuto, SizeClassLimits } from '../src/lib/api/types.ts';

const auto: PoolAuto = {
  key: 'amd64/medium',
  arch: 'amd64',
  class: 'medium',
  warm: 0,
  cap: 0,
  paused: false,
  kept: true,
  hosts: [],
  slots: 0,
  summary: 'x',
};

test('a pool is automatic only when the controller says it keeps it', () => {
  assert.equal(isAutomatic({ auto }), true);
  assert.equal(isAutomatic({}), false);
  assert.equal(isAutomatic(null), false);
  assert.equal(isAutomatic(undefined), false);
});

test('the middle setting is called what it does, not what it is spelled', () => {
  assert.equal(modeWords('off'), 'Off');
  assert.equal(modeWords('shadow'), 'Report only');
  assert.equal(modeWords('on'), 'On');
  assert.equal(modeWords(undefined), 'Off');
});

test('each switch says what it does at each setting, and never promises what it cannot', () => {
  for (const setting of ['auto_pools', 'size_routing'] as const) {
    for (const mode of ['off', 'shadow', 'on'] as const) {
      assert.ok(modeHint(setting, mode).endsWith('.'), `${setting} ${mode} is a sentence`);
    }
  }
  // Report-only changes nothing, and the sentence has to say so, because it is
  // the one setting that reads as though it might.
  assert.match(modeHint('auto_pools', 'shadow'), /changes nothing/);
  assert.match(modeHint('size_routing', 'shadow'), /Nothing is sent anywhere/);
  // Pools an operator made are untouched whatever the switch says.
  assert.match(modeHint('auto_pools', 'off'), /Pools you made are unaffected/);
});

test('a change the controller has not made is worded as one it would make', () => {
  assert.equal(pendingWords('create'), 'Would make');
  assert.equal(pendingWords('resize'), 'Would resize');
  assert.equal(pendingWords('disable'), 'Would put out of use');
  assert.equal(pendingWords('enable'), 'Would put back in use');
  assert.equal(pendingWords('reshape'), 'Would bring back in line');
});

test('a class says where it ends, and the largest says it has no end', () => {
  const small: SizeClassLimits = {
    class: 'small',
    label: 'zoomies-small',
    host_max_cpus: 4,
    host_max_memory_mb: 16384,
    runner_cpus: 1,
    runner_memory_mb: 2048,
  };
  assert.equal(limitWords(small), 'up to 4 CPUs and 16 GB');
  assert.equal(runnerWords(small), '1 CPU and 2 GB');

  const large: SizeClassLimits = {
    class: 'large',
    label: 'zoomies-large',
    runner_cpus: 4,
    runner_memory_mb: 8192,
  };
  assert.equal(limitWords(large), 'anything larger');
  assert.equal(runnerWords(large), '4 CPUs and 8 GB');
});

test('zero is not a number for a warm count or a cap', () => {
  assert.equal(warmWords(0), 'none kept ready');
  assert.equal(warmWords(3), '3 kept ready');
  assert.equal(capWords(0), 'no cap');
  assert.equal(capWords(12), 'capped at 12');
});

test('an architecture is said the way the controller says it', () => {
  assert.equal(archWords('amd64'), 'x64');
  assert.equal(archWords('arm64'), 'arm64');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { backendSwitch } from '../src/lib/pools/backend-switch.ts';
import type { Pool } from '../src/lib/api/types.ts';

const pool = (over: Partial<Pool>): Pool => ({ backend: 'docker', ...over }) as Pool;

// The one-click remedy for a pool no host can run has to be a request the API
// accepts, and the API refuses a pool on the process backend that still has
// elastic CPU or the memory valve on.
test('moving to the process backend turns off what a process cannot have', () => {
  const { body, switchedOff } = backendSwitch(
    pool({
      docker_mode: 'dind',
      cpu_burst: { mode: 'observe', max_cpus: 6, size_for_ceiling: false },
      memory_burst: { mode: 'automatic', max_memory_mb: 8192, spill_mb: 1024 },
    }),
    'process',
  );
  assert.equal(body.backend, 'process');
  assert.equal(body.docker_mode, 'none');
  assert.deepEqual(body.memory_burst, { mode: 'off' });
  assert.equal(body.cpu_burst?.mode, 'off');
  assert.equal(body.cpu_burst?.size_for_ceiling, false);
  assert.equal(switchedOff.length, 2);
  assert.match(switchedOff[0] ?? '', /Docker for jobs is switched off/);
  assert.match(switchedOff[1] ?? '', /^Elastic CPU and the memory valve are switched off/);
});

test('a pool that has neither is sent only what it always was, and told nothing extra', () => {
  const { body, switchedOff } = backendSwitch(
    pool({
      docker_mode: 'none',
      cpu_burst: { mode: 'off', size_for_ceiling: true },
      memory_burst: { mode: 'off' },
    }),
    'process',
  );
  assert.deepEqual(body, { backend: 'process', docker_mode: 'none' });
  assert.deepEqual(switchedOff, []);
});

test('each of the two is named alone when only one was on', () => {
  const memory = backendSwitch(pool({ memory_burst: { mode: 'observe' } }), 'process');
  assert.deepEqual(memory.switchedOff, [
    'The memory valve is switched off, because a process has no container limits to measure or move.',
  ]);
  assert.equal(memory.body.cpu_burst, undefined);
  const cpu = backendSwitch(
    pool({ cpu_burst: { mode: 'automatic', size_for_ceiling: true } }),
    'process',
  );
  assert.match(cpu.switchedOff[0] ?? '', /^Elastic CPU is switched off/);
  assert.equal(cpu.body.memory_burst, undefined);
});

test('moving between container backends changes the backend and nothing else', () => {
  const { body, switchedOff } = backendSwitch(
    pool({
      memory_burst: { mode: 'automatic' },
      cpu_burst: { mode: 'automatic', size_for_ceiling: true },
    }),
    'podman',
  );
  assert.deepEqual(body, { backend: 'podman' });
  assert.deepEqual(switchedOff, []);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { demandMore, demandStats, type DemandInput } from '../src/lib/bands/demand-stats.ts';

const labels = { ready: 'Ready', expedited: 'Run now', paused: 'Paused', deleted: 'Removed' };
const base: DemandInput = {
  queued: 7,
  running: 4,
  queuedWarning: true,
  counts: { ready: 5, expedited: 1, paused: 2 },
  oldest: null,
  poolId: '',
  labels,
};

test('the strip says how much is queued, what is running, then each provisioning status', () => {
  const stats = demandStats(base);
  assert.deepEqual(
    stats.map((s) => [s.label, s.value]),
    [
      ['Jobs queued', '7'],
      ['Running', '4'],
      ['Ready', '5'],
      ['Run now', '1'],
      ['Paused', '2'],
      // A status the answer does not mention is none, not unknown.
      ['Removed', '0'],
    ],
  );
  assert.equal(stats[0]?.tone, 'warning');
  assert.equal(stats[1]?.href, '/runners?state=busy#runners-list');
  assert.equal(stats[2]?.href, '/queue?provisioning=ready#queue-list');
});

test('a count that has not arrived is not drawn as zero', () => {
  const stats = demandStats({ ...base, counts: null });
  assert.equal(stats[2]?.value, undefined);
  assert.equal(stats[5]?.value, undefined);
  assert.equal(stats[0]?.value, '7');
  assert.equal(stats[1]?.value, '4');
  assert.equal(demandStats({ ...base, running: null })[1]?.value, undefined);
});

test('one queued job is singular, and the oldest shows only when there is one', () => {
  assert.equal(demandStats({ ...base, queued: 1 })[0]?.label, 'Job queued');
  assert.equal(
    demandStats(base).some((s) => s.label === 'Oldest demand'),
    false,
  );
  const withOldest = demandStats({ ...base, oldest: '2026-01-01T00:00:00Z' });
  assert.equal(withOldest.at(-1)?.since, '2026-01-01T00:00:00Z');
});

test('on the runners page, Running narrows the list on this page instead of opening one', () => {
  let selected = 0;
  const stats = demandStats({
    ...base,
    onPageRunning: {
      section: 'runners-list',
      active: true,
      onselect: () => {
        selected += 1;
      },
    },
  });
  assert.equal(stats[1]?.href, undefined);
  assert.equal(stats[1]?.section, 'runners-list');
  assert.equal(stats[1]?.active, true);
  assert.match(stats[1]?.hint ?? '', /below/);
  stats[1]?.onselect?.();
  assert.equal(selected, 1);
  // Every other figure still goes where it did.
  assert.equal(stats[0]?.href, '/queue#queue-list');
  assert.equal(stats[2]?.href, '/queue?provisioning=ready#queue-list');
});

test('a pool filter narrows every link to that pool', () => {
  const stats = demandStats({ ...base, poolId: 'pool 1' });
  assert.equal(stats[0]?.href, '/queue?pool_id=pool%201#queue-list');
  assert.equal(stats[1]?.href, '/runners?state=busy&pool_id=pool%201#runners-list');
  assert.equal(stats[3]?.href, '/queue?provisioning=expedited&pool_id=pool%201#queue-list');
  assert.equal(demandMore('pool 1').href, '/queue?pool_id=pool%201#queue-list');
  assert.equal(demandMore('').href, '/queue#queue-list');
});

