import { test } from 'node:test';
import assert from 'node:assert/strict';
import { cuteMotion, cutePose } from '../src/lib/runners/cute-motion';

test('Cute keeps its existing gait and speed tiers when Standard changes style', () => {
  for (const seed of ['runner-one', 'runner-two', 'workflow-left', 'workflow-right']) {
    const maximum = cuteMotion('maximum_zoomies', seed);
    const extra = cuteMotion('zoomies', seed);
    const busy = cuteMotion('busy', seed);
    assert.ok(maximum.stride >= 0.56 && maximum.stride < 0.58);
    assert.ok(extra.stride >= 0.8 && extra.stride < 0.82);
    assert.ok(busy.stride >= 1.6 && busy.stride < 1.72);
    assert.ok(busy.walking && !extra.walking && !maximum.walking);
    assert.ok(maximum.spinning && extra.spinning && !busy.spinning);
    assert.deepEqual(cuteMotion('maximum_zoomies', seed), maximum);
  }
  for (const state of [
    'idle',
    'provisioning',
    'registering',
    'throttled',
    'draining',
    'failed',
    'removed',
    'unknown',
  ]) {
    assert.equal(cuteMotion(state, 'runner').walking, false);
    assert.equal(cuteMotion(state, 'runner').spinning, false);
  }
});

test('every state holds a pose that separates it at grid size', () => {
  // At 31px and below CuteStatusIcon hides the props, the brows, the freckles
  // and the highlights, so posture, ears, eyes and mouth are all that tell one
  // state from another. Two states that agree on all four are the same picture
  // in a grid whatever their props say, so only the pairs named here may, and
  // each has to be there for a reason.
  const mayCoincide: { pair: [string, string]; why: string }[] = [
    {
      pair: ['zoomies', 'maximum_zoomies'],
      why: 'the sparkle that sets maximum zoomies apart steps aside at grid size, so its faster run, which the first test pins, carries the tier',
    },
  ];
  const states = [
    'idle',
    'busy',
    'provisioning',
    'registering',
    'throttled',
    'draining',
    'failed',
    'removed',
    'unknown',
    'zoomies',
    'maximum_zoomies',
  ];
  const atGridSize = (state: string) => {
    const p = cutePose(state);
    return `${p.pose}/${p.ears}/${p.eyes}/${p.mouth}`;
  };
  for (const [i, a] of states.entries()) {
    for (const b of states.slice(i + 1)) {
      const listed = mayCoincide.find(({ pair }) => pair.includes(a) && pair.includes(b));
      if (listed) {
        assert.equal(
          atGridSize(a),
          atGridSize(b),
          `${a} and ${b} no longer look alike at grid size; take the pair off mayCoincide (it was there because ${listed.why})`,
        );
      } else {
        assert.notEqual(
          atGridSize(a),
          atGridSize(b),
          `${a} and ${b} are the same picture at grid size (${atGridSize(a)}); give one a different posture, ears, eyes or mouth, or name the pair in mayCoincide with the reason`,
        );
      }
    }
  }
  // Posture cannot tell the sitting states from one another, so their ears
  // have to vary: they must not all wear the same pair.
  const sitting = states.filter((state) => cutePose(state).pose === 'sit');
  assert.ok(
    new Set(sitting.map((state) => cutePose(state).ears)).size > 1,
    `the sitting states (${sitting.join(', ')}) all wear the same ears`,
  );
  // The collar tag and props borrow the status tone, the same fixed mapping
  // the rest of the UI uses.
  assert.equal(cutePose('idle').tone, 'idle');
  assert.equal(cutePose('zoomies').tone, 'busy');
  assert.equal(cutePose('throttled').tone, 'pending');
  assert.equal(cutePose('draining').tone, 'draining');
  assert.equal(cutePose('failed').tone, 'danger');
  assert.equal(cutePose('removed').tone, 'neutral');
  // Transitional states carry one prop each; the boosts carry their dust.
  assert.equal(cutePose('provisioning').props, 'trail');
  assert.equal(cutePose('registering').props, 'ring');
  assert.equal(cutePose('draining').props, 'leash');
  assert.equal(cutePose('throttled').props, 'leash');
  assert.ok(cutePose('maximum_zoomies').props.includes('sparkle'));
});

test('a state this build does not recognise falls back to the questioning pose', () => {
  assert.deepEqual(cutePose('future-state'), cutePose('unknown'));
});

import assert from 'node:assert/strict';
import { readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import test from 'node:test';

const src = join(import.meta.dirname, '..', 'src');

function* sources(dir: string): Generator<string> {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) yield* sources(path);
    else if (/\.(svelte|css|ts)$/.test(entry.name) && !entry.name.endsWith('.d.ts')) yield path;
  }
}

// A var() naming a token that does not exist is not an error anywhere: the
// declaration is dropped at computed-value time, so `--z-radius-pill` quietly
// draws square corners and `--z-weight-regular` inherits whatever the parent
// had. Nothing else catches a misspelt token, so this does.
test('every design token a component reads is defined somewhere', () => {
  const used: [string, string][] = [];
  const defined = new Set<string>();
  for (const path of sources(src)) {
    const text = readFileSync(path, 'utf8');
    // A name built by interpolation (`--z-radius-${size}`) is checked by
    // whatever chooses the suffix, not here.
    for (const [, name] of text.matchAll(/var\(\s*(--z-[a-z0-9-]+)/g)) {
      if (!name!.endsWith('-')) used.push([name!, path]);
    }
    // A component may declare a local property for its own children, in a
    // rule or through style:--z-x; both count as a definition.
    for (const [, name] of text.matchAll(/(?:^|[\s;{"'`]|style:)(--z-[a-z0-9-]+)\s*[:=]/g)) {
      defined.add(name!);
    }
  }
  const missing = [...used].filter(([name]) => !defined.has(name));
  assert.deepEqual(
    missing.map(([name, path]) => `${name} (${path.slice(src.length + 1)})`),
    [],
  );
});

// The other direction. A redesign removes the component and forgets the
// colours it read: the Standard spaniel's roles (coat, line, ear, rim, blaze,
// far, ink, cue) stayed in tokens.css, in both themes, for weeks after the dog
// was redrawn, and nothing noticed because an unread token is invisible. Every
// token tokens.css declares has to be read by something.
//
// These are the ones that are not, with the reason. The list is also checked
// the other way, so an entry that starts being read has to leave it and it can
// only shrink.
const UNREAD_ON_PURPOSE: Record<string, string> = {
  '--z-brand-mid-grey': 'the brand record; --z-text-muted darkens it, as tokens.css says',
  '--z-brand-paw-black': 'the favicon artwork is a PNG, not a colour any rule sets',
  // docs/ui-guidelines.md ("The panel") documents these as the colours drawn on
  // a Zoomies Black ground. The stage and the footer of the pages before sign
  // in now read the text, muted text, subtle text and border; these two are
  // still documented and not yet read, which is a design decision, so they are
  // named here rather than deleted.
  '--z-panel-ring': 'documented, not yet read',
};

test('every design token tokens.css defines is read somewhere, or is unread on purpose', () => {
  const declared = new Set<string>();
  const read = new Set<string>();
  const prefixes = new Set<string>();
  for (const path of sources(src)) {
    const text = readFileSync(path, 'utf8');
    if (path.endsWith(join('styles', 'tokens.css'))) {
      for (const [, name] of text.matchAll(/(?:^|[\s;{])(--z-[a-z0-9-]+)\s*:/gm)) {
        declared.add(name!);
      }
    }
    for (const [, name] of text.matchAll(/var\(\s*(--z-[a-z0-9-]+)/g)) read.add(name!);
    // A property named in a string, to be set or read from script.
    for (const [, name] of text.matchAll(/['"`](--z-[a-z0-9-]+)['"`]/g)) read.add(name!);
    // `--z-chart-${i}` reads every token that starts that way. A bare `--z-${tone}`
    // would cover everything, so it covers nothing here: the tones it builds are
    // also read by name, and a token read only that way will fail this test
    // until it is listed above with its reason.
    for (const [, prefix] of text.matchAll(/(--z-[a-z0-9-]*)\$\{/g)) {
      if (prefix !== '--z-') prefixes.add(prefix!);
    }
  }
  const isRead = (name: string) =>
    read.has(name) || [...prefixes].some((prefix) => name.startsWith(prefix));

  const unread = [...declared].filter((name) => !isRead(name) && !(name in UNREAD_ON_PURPOSE));
  assert.deepEqual(unread.sort(), [], 'tokens.css declares tokens that nothing reads');

  const stale = Object.keys(UNREAD_ON_PURPOSE).filter(
    (name) => !declared.has(name) || isRead(name),
  );
  assert.deepEqual(stale.sort(), [], 'these are listed as unread but are gone or now read');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { contextPrompt } from '../src/lib/assistant/prompts';
import {
  findingContext,
  jobContext,
  poolContext,
  usageContext,
} from '../src/lib/assistant/contexts';

// A job's snapshot is the drawer's own verdict, flattened: the evidence and
// the next steps as a line each, so the question stays the size of a
// paragraph, and nothing the explanation does not have is invented.
test('a job context carries the verdict and reads as one paragraph', () => {
  const ctx = jobContext(
    {
      id: 'job_1',
      job_name: 'Go (api-1)',
      repo: 'eyupio/zoomies',
      state: 'completed',
      conclusion: 'failure',
      pool_name: 'linux',
      labels: ['self-hosted', 'linux'],
    },
    {
      summary: 'The runner ran out of memory.',
      class: 'oom',
      confidence: 'high',
      problem_code: 'runner.oom',
      fix: 'Give the pool a bigger runner.',
      evidence: [
        { label: 'Memory limit', value: '4096', unit: 'MB' },
        { label: 'Peak', value: '4100', unit: 'MB' },
      ],
      next_steps: [{ text: 'Raise the memory ceiling.' }, { text: 'Re-run the job.' }],
    },
    'failed',
  );
  assert.equal(ctx.kind, 'job');
  assert.equal(ctx.title, 'Go (api-1)');
  assert.equal(ctx.facts['State'], 'completed (failure)');
  assert.equal(ctx.facts['Class'], 'oom (high confidence)');
  assert.equal(ctx.facts['Evidence'], 'Memory limit: 4096 MB; Peak: 4100 MB');
  assert.equal(ctx.facts['Next steps'], 'Raise the memory ceiling. Re-run the job.');
  assert.match(ctx.question ?? '', /Why did this job fail/);
  const waiting = jobContext({ id: 'job_2', state: 'queued' }, null, 'waiting');
  assert.equal(waiting.title, 'job_2');
  assert.equal(waiting.facts['Class'], undefined);
  assert.match(waiting.question ?? '', /still waiting/);
  // Absent facts are left out of the prompt, not written as "undefined".
  assert.doesNotMatch(contextPrompt(waiting), /undefined/);
});

// A pool's snapshot is its limits and what it is doing now, with utilisation
// worked out so the model does not have to, and left out when nothing is live
// (a utilisation of nothing is not zero).
test('a pool context has the limits, the counts and a utilisation when there is one', () => {
  const ctx = poolContext(
    {
      id: 'pool_1',
      name: 'linux',
      enabled: true,
      min_runners: 1,
      max_runners: 8,
      queued_jobs: 3,
      labels: ['linux'],
    },
    { live: 4, busy: 3, idle: 1, provisioning: 1, registering: 1 },
  );
  assert.equal(ctx.facts['Utilisation (%)'], 75);
  assert.equal(ctx.facts['Starting'], 2);
  assert.equal(ctx.facts['Queued jobs'], 3);
  assert.equal(poolContext({ id: 'pool_2' }, {}).facts['Utilisation (%)'], undefined);
});

// A finding's snapshot is the evaluator's sentences and where it was seen;
// the coding-agent prompt is not pasted in, because it is written for a
// different reader and Eli can fetch the finding itself.
test('a finding context names the repository and leaves the agent prompt out', () => {
  const ctx = findingContext('eyupio/zoomies', {
    code: 'ci.no_timeout',
    severity: 'warning',
    subject: 'build.yml',
    title: 'A job has no timeout',
    detail: 'd',
    fix: 'f',
    evidence: [{ kind: 'pool', label: 'linux', ref: 'pool_1' }],
  });
  assert.equal(ctx.facts['Repository'], 'eyupio/zoomies');
  assert.equal(ctx.facts['About'], 'build.yml');
  assert.equal(ctx.facts['Where it was seen'], 'pool: linux');
  assert.doesNotMatch(JSON.stringify(ctx), /prompt/);
});

// A usage snapshot is the totals, not the rows, and says nothing about runner
// time at a grouping where it cannot be attributed: a zero there would be a
// claim.
test('a usage context totals the rows and withholds what is not attributable', () => {
  const rows = [
    {
      key: 'a',
      jobs: 10,
      jobs_completed: 9,
      job_execution_seconds: 3600,
      allocated_runner_seconds: 7200,
      average_queue_wait_seconds: 12,
      peak_concurrency: 3,
      estimated_cost: 1.5,
    },
    {
      key: 'b',
      jobs: 5,
      jobs_completed: 5,
      job_execution_seconds: 1800,
      allocated_runner_seconds: 1800,
      average_queue_wait_seconds: null,
      peak_concurrency: 5,
      estimated_cost: 0.25,
    },
  ];
  const ctx = usageContext({
    grouping: 'pool',
    since: '2026-10-01T00:00',
    until: '2026-10-11T23:59',
    rows,
    attributable: true,
  });
  assert.equal(ctx.facts['Jobs'], 15);
  assert.equal(ctx.facts['Execution hours'], 1.5);
  assert.equal(ctx.facts['Runner-hours'], 2.5);
  assert.equal(ctx.facts['Utilisation (%)'], 60);
  assert.equal(ctx.facts['Longest mean queue wait (s)'], 12);
  assert.equal(ctx.facts['Peak concurrency'], 5);
  assert.equal(ctx.facts['Estimated cost'], 1.75);
  const byRepo = usageContext({
    grouping: 'repository',
    since: 's',
    until: 'u',
    rows,
    attributable: false,
    entity: 'eyupio/zoomies',
  });
  assert.equal(byRepo.title, 'repository eyupio/zoomies');
  assert.equal(byRepo.facts['Runner-hours'], undefined);
  assert.equal(byRepo.facts['Estimated cost'], undefined);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { historyFor, transcript, turnsFrom } from '../src/lib/assistant/history';

// What is kept is what the model would be sent as history: the words, in
// order, without a turn that failed before it began and without one still
// streaming, so a kept conversation resumes as it was being read.
test('a transcript keeps the words and leaves out failures and the turn in flight', () => {
  const kept = transcript([
    { id: 0, role: 'user', content: 'Why is the queue slow?' },
    { id: 1, role: 'assistant', content: 'The pool is full.' },
    { id: 2, role: 'user', content: 'What now?' },
    { id: 3, role: 'assistant', content: '', error: 'The model stopped answering.' },
    { id: 4, role: 'user', content: 'Again?' },
    { id: 5, role: 'assistant', content: 'Half an', streaming: true },
  ]);
  assert.deepEqual(kept, [
    { role: 'user', content: 'Why is the queue slow?' },
    { role: 'assistant', content: 'The pool is full.' },
    { role: 'user', content: 'What now?' },
    { role: 'user', content: 'Again?' },
  ]);
});

// A question the controller refused for what it said was never answered and
// cannot be: if it stayed in what the model is told, every later question would
// carry it and be refused the same way, and the person could only start again.
test('a refused question is neither sent as history nor kept', () => {
  const turns = [
    { id: 0, role: 'user', content: 'Why is the queue slow?' },
    { id: 1, role: 'assistant', content: 'The pool is full.' },
    { id: 2, role: 'user', content: 'x'.repeat(9000), refused: true },
    { id: 3, role: 'assistant', content: '', error: 'Your message is 8.8 KiB.', refused: true },
    { id: 4, role: 'user', content: 'What now?' },
    { id: 5, role: 'assistant', content: 'Add a host.' },
  ] as const;
  const said = [
    { role: 'user', content: 'Why is the queue slow?' },
    { role: 'assistant', content: 'The pool is full.' },
    { role: 'user', content: 'What now?' },
    { role: 'assistant', content: 'Add a host.' },
  ];
  assert.deepEqual(historyFor(turns), said);
  assert.deepEqual(transcript(turns), said);
});

// What the model is told it said leaves out an answer that failed, and is not
// the same as what is kept: a question whose answer failed is still a question.
test('a question whose answer failed is still history, and the failed answer is not', () => {
  assert.deepEqual(
    historyFor([
      { id: 0, role: 'user', content: 'Again?' },
      { id: 1, role: 'assistant', content: '', error: 'The model stopped answering.' },
    ]),
    [{ role: 'user', content: 'Again?' }],
