import assert from 'node:assert/strict';
import test from 'node:test';
import { ApiError } from '../src/lib/api/client.ts';
import { authFailureText, sentence } from '../src/lib/errors.ts';

// The server's refusals are lowercase and unpunctuated because they are also a
// log line. Shown in a toast under a sentence-case title they read as raw
// output, so they are capitalised and stopped -- and only that: not a word of
// them changes, because a 403 names the role required.
test('a server refusal is capitalised and given a full stop without changing a word', () => {
  const cases: [string, string][] = [
    ['your account is not allowed to do that', 'Your account is not allowed to do that.'],
    [
      'no such thing; it may have been removed since the page loaded',
      'No such thing; it may have been removed since the page loaded.',
    ],
    ['  needs the admin role.  ', 'Needs the admin role.'],
    ['Already a sentence!', 'Already a sentence!'],
    ['', ''],
  ];
  for (const [given, want] of cases) assert.equal(sentence(given), want);
});

// A setting key or an ID leading the message is the operator's own word for a
// thing: capitalising `limits.job_stats_window` names a setting that does not
// exist, and the string they would search for is gone.
test('a message that opens with an identifier keeps it exactly as written', () => {
  const cases: [string, string][] = [
    [
      'limits.job_stats_window caps the range at 90 days',
      'limits.job_stats_window caps the range at 90 days.',
    ],
    ['pool_abc123 is still draining', 'pool_abc123 is still draining.'],
  ];
  for (const [given, want] of cases) assert.equal(sentence(given), want);
});

// A message that ends in an address or a path is not a sentence a full stop can
// close: the stop would be copied with the URL.
test('a message that ends in an address or a path gains no full stop', () => {
  for (const given of [
    'the callback must be registered at https://ci.example/oauth/callback',
    'the database is at /var/lib/zoomies/zoomies.db',
    'cannot continue:',
  ]) {
    assert.equal(sentence(given), given.charAt(0).toUpperCase() + given.slice(1));
  }
});

// A release check that GitHub would not finish is a 502, and every other 5xx is
// answered with "the controller answered with an error, its logs will say". That
// is wrong here twice over: the controller is fine, and the sentence it wrote
// (the outbound rule to api.github.com to check, or that the check can be tried
// again later) is the only thing the operator who pressed the button can act on.
test('a failed release check shows the controller sentence and not the generic server error', () => {
  const cause = new ApiError({
    status: 502,
    code: 'update.check_failed',
    message:
      'could not reach GitHub for the release list (dial tcp: i/o timeout); check that this controller may make outbound HTTPS requests to api.github.com',
  });
  const shown = authFailureText(cause);
  assert.match(shown, /api\.github\.com/);
  assert.doesNotMatch(shown, /Its logs will say/);
  // Capitalised and stopped like every other refusal on a card.
  assert.match(shown, /^Could not reach GitHub/);
});

// The exception is for the one code that promises a sentence. A server failure
// with no such promise still points at the log, because its message may carry
// detail that was never meant for the page.
test('a server failure with no sentence of its own still gets the generic text', () => {
  for (const [status, code] of [
    [500, 'internal'],
    [502, 'assistant.provider_failed'],
    [503, 'internal'],
  ] as const) {
    const cause = new ApiError({ status, code, message: 'something with api.github.com in it' });
    assert.doesNotMatch(authFailureText(cause), /api\.github\.com/);
    assert.match(authFailureText(cause), /Its logs will say more/);
  }
});

/**
 * The fault vocabulary, which is pure and is read by every page that shows a
 * failure.
 *
 * `faults.ts` deliberately imports no icons, so it loads in Node as-is. That is
 * the whole reason it is a file of its own rather than part of `status.ts`, and
 * this walks the two things a Playwright pass cannot: every category the server
 * can send, and the older-controller case where a job carries the fleet's prose
 * and no domain at all.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  FAULT_KINDS,
  faultDetail,
  faultDomain,
  faultLabel,
  fleetFailed,
} from '../src/lib/faults.ts';

test('every category has a label and a sentence', () => {
  for (const kind of FAULT_KINDS) {
    assert.notEqual(faultLabel(kind), '', `${kind} has no label`);
    assert.notEqual(faultDetail(kind), '', `${kind} has no detail`);
  }
});

test('a category this build does not know reads as itself, never as nothing', () => {
  // A fleet whose controller is newer sends kinds this bundle has never heard
  // of. An empty badge would say the failure had no category, which is the one
  // thing that is not true of it.
  assert.equal(faultLabel('quantum_decoherence'), 'Quantum decoherence');
  assert.equal(faultDetail('quantum_decoherence'), '');
  assert.equal(faultLabel(''), '');
  assert.equal(faultLabel(null), '');
  assert.equal(faultLabel(undefined), '');
});

test("the domain is the server's answer, and the fallback never blames a workflow", () => {
  assert.equal(faultDomain({ fault_domain: 'fleet' }), 'fleet');
  assert.equal(faultDomain({ fault_domain: 'workflow' }), 'workflow');
  assert.equal(faultDomain({ conclusion: 'success' }), '');

  // A job from a controller too old to send the domain carries the prose and
  // the category only. Reading it as the workflow's would hand somebody a bug
  // hunt for a failure this fleet caused, which is the exact mistake the whole
  // split exists to prevent.
  assert.equal(
    faultDomain({ runner_fault: 'runner zoomies-a stopped', conclusion: 'failure' }),
    'fleet',
  );
  assert.equal(faultDomain({ fault_kind: 'out_of_memory' }), 'fleet');
  assert.equal(fleetFailed({ runner_fault: 'runner zoomies-a stopped' }), true);
  // A job GitHub says failed, with nothing in it that blames the fleet. Passed by
  // name because `conclusion` is what GitHub sent, not a field the check reads.
  const plainFailure = { fault_kind: null, conclusion: 'failure' };
  assert.equal(fleetFailed(plainFailure), false);
});

test('a domain the server sends that this build does not know falls back rather than being trusted', () => {
  // Not 'fleet' and not 'workflow', so the fields decide. Trusting an unknown
  // string would put it straight into a comparison that fails every branch and
  // renders nothing.
  assert.equal(faultDomain({ fault_domain: 'cosmic', fault_kind: 'out_of_memory' }), 'fleet');
  assert.equal(faultDomain({ fault_domain: 'cosmic' }), '');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { AUTOMATIC_ACTIONS, automaticTitle, causeOf, subjectOf } from '../src/lib/feed/cause.ts';

test('an automatic change carries its reason, and an operator’s own action has none', () => {
  assert.equal(
    causeOf({ after: JSON.stringify({ max_runners: 10, cause: ' a host joined ' }) }),
    'a host joined',
  );
  assert.equal(causeOf({ after: JSON.stringify({ max_runners: 10 }) }), undefined);
  assert.equal(causeOf({ after: JSON.stringify({ cause: '' }) }), undefined);
  assert.equal(causeOf({ after: JSON.stringify({ cause: 7 }) }), undefined);
  assert.equal(causeOf({ after: 'not json' }), undefined);
  assert.equal(causeOf({ after: 'null' }), undefined);
  assert.equal(causeOf({ after: undefined }), undefined);
});

test('every automatic change has a title, and an operator’s action is not one', () => {
  for (const action of [
    'pool.auto_create',
    'pool.auto_resize',
    'pool.auto_enable',
    'pool.auto_disable',
    'pool.auto_reshape',
    'host.size_class',
    'size_class.move',
  ]) {
    assert.ok(automaticTitle(action), `${action} is named`);
  }
  // What an operator did to the same pool or host is "who changed what", and
  // stays in that category: the pin they set, the pool they edited.
  for (const action of ['pool.update', 'size_pin.set', 'size_pin.delete', 'host.update', '']) {
    assert.equal(automaticTitle(action), undefined, `${action} is not automatic`);
  }
  assert.equal(automaticTitle(undefined), undefined);
  assert.equal(Object.keys(AUTOMATIC_ACTIONS).length, 7);
});

test('an automatic change is about something by name, not by the id the row carries', () => {
  assert.equal(
    subjectOf({ after: JSON.stringify({ name: 'zoomies-medium', cause: 'x' }) }),
    'zoomies-medium',
  );
  assert.equal(
    subjectOf({ after: JSON.stringify({ class: 'large', host: 'build-2' }) }),
    'build-2',
  );
  // A pool's name wins where a row carries both.
  assert.equal(subjectOf({ after: JSON.stringify({ name: 'p', host: 'h' }) }), 'p');
  assert.equal(subjectOf({ after: JSON.stringify({ class: 'large' }) }), undefined);
  assert.equal(subjectOf({ after: JSON.stringify({ name: 3 }) }), undefined);
  assert.equal(subjectOf({ after: 'not json' }), undefined);
  assert.equal(subjectOf({ after: undefined }), undefined);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import type { Host, Job, Machine, Problem, Provider } from '../src/lib/api/types.ts';
import {
  cpuChange,
  hostChanges,
  hostSignal,
  installationChange,
  jobFailure,
  jobNews,
  machineChange,
  newProblems,
  providerChanges,
  providerSignal,
  runnerMilestone,
} from '../src/lib/feed/changes.ts';

function host(fields: Partial<Host> = {}): Host {
  return { id: 'hst_1', name: 'builder-1', healthy: true, ...fields } as Host;
}

test('a host that has only moved its CPU reading is not news', () => {
  // The case the whole module exists for: every host publishes a frame on
  // every heartbeat, and a feed that reported them would be a feed nobody
  // reads -- and then one an operator switches off, losing the lines that
  // mattered.
  const before = hostSignal(host({ cpu_percent: 4 } as Partial<Host>));
  const after = hostSignal(host({ cpu_percent: 91 } as Partial<Host>));
  assert.deepEqual(hostChanges(after, before), []);
});

test('a host is reported when it stops answering and again when it comes back', () => {
  const healthy = hostSignal(host());
  const silent = hostSignal(host({ healthy: false }));
  assert.deepEqual(hostChanges(silent, healthy), ['unreachable']);
  assert.deepEqual(hostChanges(healthy, silent), ['recovered']);
});

test('every rung of the throttle ladder is its own line, and calm is one line', () => {
  // A host climbing the ladder is a host under worsening pressure, which is
  // the thing an operator watches for; coming off it happens once.
  const none = hostSignal(host());
  const first = hostSignal(host({ throttle: { level: 1 } } as Partial<Host>));
  const second = hostSignal(host({ throttle: { level: 2 } } as Partial<Host>));
  assert.deepEqual(hostChanges(first, none), ['throttled']);
  assert.deepEqual(hostChanges(second, first), ['throttled']);
  assert.deepEqual(hostChanges(first, second), [], 'stepping back down is not news on its own');
  assert.deepEqual(hostChanges(none, first), ['calm']);
});

test('a host holding new runners under pressure says so once, and says when it stops', () => {
  // Not the same thing as a throttle: a throttle takes slots away for minutes,
  // a hold is this moment's pressure refusing the next start. Both answer
  // "why is nothing starting here".
  const easy = hostSignal(host());
  const pressed = hostSignal(host({ admission_reason: 'load average 19.2 on 8 CPUs' }));
  assert.deepEqual(hostChanges(pressed, easy), ['holding']);
  assert.deepEqual(hostChanges(easy, pressed), ['admitting']);
  // The reason's wording moves with the load; only the transition is news.
  const worse = hostSignal(host({ admission_reason: 'load average 24.7 on 8 CPUs' }));
  assert.deepEqual(hostChanges(worse, pressed), []);
});

test('a runner reaching idle for the first time is the success worth reporting', () => {
  // The half of the fleet that goes right. A panel that only ever reported
  // failures would teach an operator that silence is the good state, which is
  // the same thing as teaching them not to read it.
  assert.equal(runnerMilestone('idle', 'registering'), 'ready');
  assert.equal(runnerMilestone('idle', undefined), 'ready');
  assert.equal(runnerMilestone('removed', 'draining'), 'retired');
});

test('a runner coming back from a job is not ready news again', () => {
  // The job's own line already said that, and a persistent runner would
  // otherwise write one of these after every job it takes.
  assert.equal(runnerMilestone('idle', 'busy'), null);
});

test('the states on the way up are not milestones', () => {
  // Six states per ephemeral runner, one runner per job: a feed that carried
  // them all would be a log.
  assert.equal(runnerMilestone('registering', 'provisioning'), null);
  assert.equal(runnerMilestone('busy', 'idle'), null);
  assert.equal(runnerMilestone('draining', 'busy'), null);
  assert.equal(runnerMilestone('idle', 'idle'), null);
});

test('a runner is reported when its elastic CPU state changes, not when the factor moves', () => {
  // The six states are what the runner's own page shows; the factor behind
  // them moves with every heartbeat.
  assert.equal(cpuChange('zoomies', 'guaranteed'), 'zoomies');
  assert.equal(cpuChange('maximum_zoomies', 'zoomies'), 'maximum_zoomies');
  assert.equal(cpuChange('throttled', 'maximum_zoomies'), 'throttled');
  assert.equal(cpuChange('zoomies', 'zoomies'), null);
  // The lead coming off a runner whose pool lends nothing is news too: it was
  // slowed by its host, and it is back at its share.
  assert.equal(cpuChange('sit_and_stay', 'throttled'), 'sit_and_stay');
  assert.equal(cpuChange('sit_and_stay', 'sit_and_stay'), null);
});

test('a runner already lent CPU when this tab opened is not news', () => {
  // The state it is already in is not something that just happened, and a
  // reconnect delivers one frame per runner.
  assert.equal(cpuChange('maximum_zoomies', undefined), null);
});

test('a host nobody here has seen before has joined the fleet', () => {
  assert.deepEqual(hostChanges(hostSignal(host()), undefined), ['joined']);
});

test('two things going wrong on one host are two lines, worst first', () => {
  const before = hostSignal(host());
  const after = hostSignal(host({ healthy: false, cordoned: true }));
  assert.deepEqual(hostChanges(after, before), ['unreachable', 'cordoned']);
});

/**
 * A host as the controller sends it once its agent has reported: the report,
 * and beside it the controller's count of it. Only the count is read.
 */
function reporting(
  count: { warnings?: number; errors?: number },
  doctor: { container?: boolean; reboot_pending?: boolean; checked_at?: string } = {},
): Partial<Host> {
  return {
    doctor: {
      checked_at: '2026-10-04T10:00:00Z',
      os: 'linux',
      distro: 'ubuntu 24.04',
      container: false,
      reboot_pending: false,
      results: [],
      summary: {
        counted: 12,
        warnings: 0,
        errors: 0,
        skipped: 0,
        suggestions: 0,
        accepted: 0,
        ...count,
      },
      ...doctor,
    },
  } as Partial<Host>;
}

// The report arrives about once a minute per host and its checked_at is
// different every time, so a feed that noticed the report would write a line a
// minute per host. The signal holds the verdict and nothing else.
test('a refreshed report with the same verdict is not news', () => {
  const before = hostSignal(
    host(reporting({ warnings: 2 }, { checked_at: '2026-10-04T10:00:00Z' })),
  );
  const after = hostSignal(
    host(reporting({ warnings: 2 }, { checked_at: '2026-10-04T10:01:00Z' })),
  );
  assert.deepEqual(after, before);
  assert.deepEqual(hostChanges(after, before), []);
});

// Otherwise a rolling upgrade would print "needs attention" once per host, the
// first time each reported, about a state it had been in for months.
test('the first report a host ever sends is a baseline and says nothing', () => {
  const never = hostSignal(host());
  assert.equal(never.reported, false);
  assert.deepEqual(hostChanges(hostSignal(host(reporting({ warnings: 3 }))), never), []);
  assert.deepEqual(hostChanges(hostSignal(host(reporting({ errors: 1 }))), never), []);
  assert.deepEqual(
    hostChanges(hostSignal(host(reporting({}, { reboot_pending: true }))), never),
    [],
    'a reboot already pending on the first report is part of the baseline too',
  );
});

test('a host that starts needing attention says so once, and a worse verdict says it again', () => {
  const calm = hostSignal(host(reporting({})));
  const warned = hostSignal(host(reporting({ warnings: 1 })));
  const failing = hostSignal(host(reporting({ errors: 1, warnings: 1 })));
  assert.deepEqual(hostChanges(warned, calm), ['attention']);
  assert.deepEqual(hostChanges(failing, warned), ['failing']);
  assert.deepEqual(hostChanges(failing, calm), ['failing'], 'straight to an error is an error');
});

test('more warnings, or fewer, are not a new verdict', () => {
  // The count moves as an operator fixes things one at a time, and the host
  // needed attention before and after: that is the same news.
  const one = hostSignal(host(reporting({ warnings: 1 })));
  const three = hostSignal(host(reporting({ warnings: 3 })));
  assert.deepEqual(hostChanges(three, one), []);
  assert.deepEqual(hostChanges(one, three), []);
});

test('an error easing to a warning is not clear, and only reaching zero is', () => {
  const failing = hostSignal(host(reporting({ errors: 1, warnings: 2 })));
  const warned = hostSignal(host(reporting({ warnings: 2 })));
  const calm = hostSignal(host(reporting({})));
  assert.deepEqual(hostChanges(warned, failing), []);
  assert.deepEqual(hostChanges(calm, warned), ['clear']);
  assert.deepEqual(hostChanges(calm, failing), ['clear']);
});

test('a pending reboot is announced when it appears, not while it stays', () => {
  const calm = hostSignal(host(reporting({})));
  const waiting = hostSignal(host(reporting({}, { reboot_pending: true })));
  assert.deepEqual(hostChanges(waiting, calm), ['reboot']);
  assert.deepEqual(hostChanges(waiting, waiting), []);
  assert.deepEqual(hostChanges(calm, waiting), [], 'having rebooted is not a line of its own');
});

test('a verdict and a reboot arriving together are two lines, the verdict first', () => {
  const calm = hostSignal(host(reporting({})));
  const both = hostSignal(host(reporting({ warnings: 1 }, { reboot_pending: true })));
  assert.deepEqual(hostChanges(both, calm), ['attention', 'reboot']);
});

// A container's report skips most checks and warns about its image's
// distribution for ever; the controller raises nothing for it, so the feed
// treats it as no report at all rather than as a host that got better or worse.
test('a container’s partial report is not a verdict', () => {
  const partial = hostSignal(
    host(reporting({ errors: 2, warnings: 4 }, { container: true, reboot_pending: true })),
  );
  assert.equal(partial.reported, false);
  assert.equal(partial.attention, 0);
  assert.equal(partial.rebootPending, false);
});

test('swapping between a full report and a partial one says nothing either way', () => {
  const full = hostSignal(host(reporting({ errors: 1 })));
  const partial = hostSignal(host(reporting({}, { container: true })));
  // Not "clear": nothing got better, the host is simply being looked at
  // through a smaller window.
  assert.deepEqual(hostChanges(partial, full), []);
  // And not a failure when the full report returns, for the same reason it
  // would not be for a host's first.
  assert.deepEqual(hostChanges(full, partial), []);
});

test('a host that goes unreachable says nothing about its health', () => {
  const warned = hostSignal(host(reporting({ warnings: 2 })));
  const silent = hostSignal(host({ ...reporting({ warnings: 2 }), healthy: false }));
  assert.deepEqual(hostChanges(silent, warned), ['unreachable']);
  assert.deepEqual(hostChanges(warned, silent), ['recovered']);
});

test('a host’s reachability comes before what its report says', () => {
  const calm = hostSignal(host(reporting({})));
  const worse = hostSignal(host({ ...reporting({ errors: 1 }), healthy: false }));
  assert.deepEqual(hostChanges(worse, calm), ['unreachable', 'failing']);
});

// A payload with no count is a controller older than the page, or a host that
// has not reported. Reading it must not throw -- this runs on every host frame
// -- and it must not read as a host that is well, or the first count to arrive
// would look like a recovery.
test('a host with no count reads as not reported, and never throws', () => {
  const bare = { checked_at: '2026-10-04T10:00:00Z', container: false, reboot_pending: true };
  for (const fields of [
    {},
    { doctor: undefined },
    { doctor: null },
    { doctor: bare },
    { doctor: { ...bare, summary: undefined } },
    { doctor: { ...bare, summary: null } },
  ]) {
    const signal = hostSignal(host(fields as Partial<Host>));
    assert.equal(signal.reported, false, JSON.stringify(fields));
    assert.equal(signal.attention, 0, JSON.stringify(fields));
    assert.equal(signal.rebootPending, false, JSON.stringify(fields));
  }
  const withCount = hostSignal(host(reporting({ errors: 1 })));
  assert.deepEqual(hostChanges(withCount, hostSignal(host({ doctor: bare } as Partial<Host>))), []);
});

function machine(state: string): Machine {
  return { id: 'mach_1', state, name: 'zoomies-mach-1' } as unknown as Machine;
}

test('a machine is reported when it starts costing money, earns it, or goes wrong', () => {
  assert.equal(machineChange(machine('creating'), undefined), 'creating');
  assert.equal(machineChange(machine('ready'), 'enrolling'), 'ready');
  assert.equal(machineChange(machine('failed'), 'bootstrapping'), 'failed');
  assert.equal(machineChange(machine('quarantined'), 'ready'), 'quarantined');
});

test('the steps on the way up are progress rather than news', () => {
  // The machine's own page has them, with their timings. A feed that carried
  // five lines per machine would bury everything else on a fleet renting any
  // number of them.
  assert.equal(machineChange(machine('starting'), 'creating'), null);
  assert.equal(machineChange(machine('bootstrapping'), 'starting'), null);
  assert.equal(machineChange(machine('enrolling'), 'bootstrapping'), null);
});

test('a machine republished in the state it is already in says nothing', () => {
  assert.equal(machineChange(machine('ready'), 'ready'), null);
});

function job(fields: Partial<Job>): Job {
  return { id: 'job_1', state: 'completed', ...fields } as Job;
}

test('a finished job lands in the category its ending belongs to', () => {
  // The failures are what an operator acts on, so they are their own
  // category and stay on; everything else is the panel this feed replaced,
  // which on a busy fleet is the noisiest thing here.
  assert.equal(jobNews(job({ conclusion: 'failure' })), 'failed');
  assert.equal(jobNews(job({ conclusion: 'timed_out' })), 'failed');
  assert.equal(jobNews(job({ conclusion: 'success' })), 'succeeded');
  assert.equal(jobNews(job({ conclusion: 'cancelled' })), 'cancelled');
  assert.equal(jobFailure('failed'), true);
  assert.equal(jobFailure('runner_lost'), true);
  assert.equal(jobFailure('succeeded'), false);
});

test('a job that has not finished is not news yet', () => {
  // It is on the Overview twice already -- in the running list and in the
  // matrix -- and a feed that repeated every step of it would say nothing.
  assert.equal(jobNews(job({ state: 'in_progress' })), null);
  assert.equal(jobNews(job({ state: 'queued' })), null);
});

test('a job whose runner stopped under it is the fleet’s failure, and says so', () => {
  // GitHub records it as an ordinary failure. The distinction is the one an
  // operator on this page is paid to make, so it survives into the feed --
  // and it survives a conclusion that says the job succeeded, which is what a
  // runner dying between the last step and the report looks like.
  assert.equal(
    jobNews(job({ conclusion: 'failure', runner_fault: 'runner_lost' } as Partial<Job>)),
    'runner_lost',
  );
  assert.equal(
    jobNews(job({ conclusion: 'success', runner_fault: 'runner_lost' } as Partial<Job>)),
    'runner_lost',
  );
});

function provider(fields: Partial<Provider> = {}): Provider {
  return { id: 'prv_1', name: 'proxmox-lab', enabled: true, paused: false, ...fields } as Provider;
}

test('a provider is reported when somebody stops it and when it stops answering', () => {
  const running = providerSignal(provider());
  const paused = providerSignal(provider({ paused: true }));
  const failing = providerSignal(provider({ last_check_error: 'certificate expired' }));
  assert.deepEqual(providerChanges(paused, running), ['paused']);
  assert.deepEqual(providerChanges(running, paused), ['resumed']);
  assert.deepEqual(providerChanges(failing, running), ['unreachable']);
  assert.deepEqual(providerChanges(running, failing), ['reachable']);
});

test('a provider seen for the first time is not an incident', () => {
  // Somebody has just added it, which the audit log records. Reporting it as
  // a change would mean every reconnect announced the whole fleet.
  assert.deepEqual(providerChanges(providerSignal(provider()), undefined), []);
});

test('an installation already failing when the tab opened is still worth saying once', () => {
  assert.equal(installationChange({ id: 'ins_1', healthy: false }, undefined), 'failing');
  assert.equal(installationChange({ id: 'ins_1', healthy: true }, undefined), null);
  assert.equal(installationChange({ id: 'ins_1', healthy: true }, false), 'working');
  assert.equal(installationChange({ id: 'ins_1', healthy: true }, true), null);
});

function problem(code: string, title: string): Problem {
  return { code, title, severity: 'warning' } as Problem;
}

test('a problem is reported once, however many times it is republished', () => {
  const seen = new Set<string>();
  const first = [problem('host.unhealthy', '1 host is not answering')];
  assert.equal(newProblems(first, seen).length, 1);
  assert.equal(newProblems(first, seen).length, 0);
});

test('a problem whose prose has changed is the same problem', () => {
  // "5 webhook deliveries were rejected" becoming "6 webhook deliveries were
  // rejected" is one fault, and re-reporting it every minute is the nagging
  // this identity exists to stop.
  const seen = new Set<string>();
  newProblems([problem('webhook.rejected', '5 deliveries were rejected')], seen);
  assert.equal(
    newProblems([problem('webhook.rejected', '6 deliveries were rejected')], seen).length,
    0,
  );
});

test('a problem that cleared and came back is news again', () => {
  const seen = new Set<string>();
  const fault = [problem('host.unhealthy', '1 host is not answering')];
  newProblems(fault, seen);
  newProblems([], seen);
  assert.equal(newProblems(fault, seen).length, 1);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import type { Host } from '../src/lib/api/types.ts';
import type { HostChange } from '../src/lib/feed/changes.ts';
import { hostEntry } from '../src/lib/feed/entries.ts';
import { hostStatus } from '../src/lib/status.ts';

const AT = '2026-10-04T10:05:00.000Z';

function host(fields: Partial<Host> = {}): Host {
  return { id: 'hst_1', name: 'builder-1', healthy: true, active_runners: 0, ...fields } as Host;
}

function reporting(warnings: number, errors: number, checkedAt = '2020-01-01T00:00:00Z'): Host {
  return host({
    doctor: {
      checked_at: checkedAt,
      os: 'linux',
      distro: 'ubuntu 24.04',
      container: false,
      reboot_pending: false,
      results: [],
      summary: { counted: 12, warnings, errors, skipped: 0, suggestions: 0, accepted: 0 },
    },
  } as Partial<Host>);
}

const OS_LINES: HostChange[] = ['attention', 'failing', 'clear', 'reboot'];

// These are the lines an operator reads on the Overview, so what they say, how
// loudly they say it and where they lead are the contract, not an accident of
// the map they are built from.
test('the four lines about a host’s OS say what changed, in the right tone', () => {
  const lines = Object.fromEntries(
    OS_LINES.map((change) => [change, hostEntry(reporting(2, 0), change, AT)]),
  );
  assert.equal(lines.attention?.title, 'A host needs attention');
  assert.equal(lines.attention?.tone, 'pending');
  assert.equal(lines.failing?.title, 'A host has a health error');
  assert.equal(lines.failing?.tone, 'danger');
  assert.equal(lines.clear?.title, 'A host no longer needs attention');
  assert.equal(lines.clear?.tone, 'idle');
  assert.equal(lines.reboot?.title, 'A host is waiting for a reboot');
  assert.equal(lines.reboot?.tone, 'pending');
  for (const line of Object.values(lines)) {
    assert.equal(line?.category, 'hosts', 'on by default, with the rest of the host lines');
  }
});

test('the detail is the controller’s count in the pill’s own words', () => {
  assert.equal(hostEntry(reporting(2, 0), 'attention', AT)?.detail, '2 warnings');
  assert.equal(hostEntry(reporting(1, 0), 'attention', AT)?.detail, '1 warning');
  assert.equal(hostEntry(reporting(2, 1), 'failing', AT)?.detail, '1 health error · 2 warnings');
  assert.equal(hostEntry(reporting(0, 0), 'clear', AT)?.detail, undefined);
});

// The question the line is read to answer: can it be done now. The count of
// runners is always sent, so zero means nothing is running.
test('a reboot line says whether the host can be rebooted now', () => {
  const idle = hostEntry(host({ active_runners: 0 }), 'reboot', AT);
  assert.equal(idle?.detail, 'Nothing is running on it, so it can be rebooted now.');
  const busy = hostEntry(host({ active_runners: 2 }), 'reboot', AT);
  assert.equal(
    busy?.detail,
    'Runners are on it, and one kept warm for a pool never finishes by itself. Cordon it and reboot when none is running a job; Zoomies never reboots a host itself.',
  );
});

// The report is on the host's own page, and its rows are what the line is
// about; the list of hosts is where every other host line goes.
test('a line about a host’s OS opens the host, and the others still open the list', () => {
  for (const change of OS_LINES) {
    const entry = hostEntry(reporting(1, 0), change, AT);
    assert.deepEqual(entry?.target, { label: 'builder-1', href: '/hosts/hst_1' }, change);
  }
  for (const change of ['joined', 'unreachable', 'cordoned', 'throttled'] as HostChange[]) {
    assert.equal(hostEntry(host(), change, AT)?.target?.href, '/hosts', change);
  }
});

// A healthy host's own icon is a plain circle, which on a line about its
// settings would read as a line about its heartbeat.
test('the OS lines carry marks of their own, apart from the host’s status icon', () => {
  const own = hostStatus(host()).icon;
  const icons = OS_LINES.map((change) => hostEntry(reporting(1, 0), change, AT)?.icon);
  for (const icon of icons) assert.notEqual(icon, own);
  const [attention, failing, , reboot] = icons;
  assert.equal(
    new Set([attention, failing, reboot]).size,
    3,
    'a warning, an error and a reboot differ',
  );
  // The ones that were already there keep theirs.
  assert.equal(hostEntry(host(), 'cordoned', AT)?.icon, hostStatus(host()).icon);
});

// checked_at is the agent's clock. A host whose clock is wrong would date its
// own news a year ago, and a line that moves with a clock is one that flaps.
test('a line is dated by when it arrived, never by the report’s own time', () => {
  const entry = hostEntry(reporting(1, 0, '2020-01-01T00:00:00Z'), 'attention', AT);
  assert.equal(entry?.at, AT);
  assert.equal(entry?.id, `host:hst_1:attention:${AT}`);
});

test('the lines the host already had are as they were', () => {
  const entry = hostEntry(
    host({ throttle_reason: 'load average 19.2' } as Partial<Host>),
    'throttled',
    AT,
  );
  assert.equal(entry?.title, 'A host was throttled');
  assert.equal(entry?.detail, 'load average 19.2');
  assert.equal(hostEntry(host({ id: undefined } as Partial<Host>), 'attention', AT), null);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { shapeDiffers } from '../src/lib/state/fleet-shape.ts';

const host = {
  id: 'hst_1',
  name: 'builder-1',
  healthy: true,
  capacity: 4,
  cpu_percent: 4,
  last_heartbeat: '2026-01-01T00:00:00Z',
  memory_pool: { total_mb: 32768, lent_mb: 0, free_mb: 20000 },
};

test('a host whose memory pool moved is still the same fleet', () => {
  // The case this list exists for. A host's pool carries the free memory its
  // agent measured, so it differs on every heartbeat; if that counted as a
  // change to the fleet, every Runners and Pools grid would fetch its page
  // again once per host per heartbeat to learn nothing.
  const next = { ...host, memory_pool: { total_mb: 32768, lent_mb: 1536, free_mb: 17000 } };
  assert.equal(shapeDiffers(host, next), false);
});

test('a host that only has a pool now, or has lost it, is still the same fleet', () => {
  // The first heartbeat after a pool turns the valve on adds the figure, and the
  // last before it is switched off takes it away; neither is a host appearing,
  // changing health or moving pool.
  const { memory_pool: _gone, ...bare } = host;
  assert.equal(shapeDiffers(bare, host), false);
  assert.equal(shapeDiffers(host, bare), false);
});

test('a runner whose valve view moved is still the same fleet, and one that changed state is not', () => {
  // The Runners grid draws its pills from the cache row, so a loan made, or a
  // would-be loan that grew, repaints it without a round trip; a runner that
  // moved from idle to busy is a change to what the grid lists.
  const runner = {
    id: 'run_1',
    name: 'zoomies-1',
    state: 'busy',
    memory_resource: { state: 'observing', mode: 'observe', would_lend_mb: 128 },
  };
  const grown = { ...runner, memory_resource: { ...runner.memory_resource, would_lend_mb: 512 } };
  assert.equal(shapeDiffers(runner, grown), false);
  const { memory_resource: _gone, ...bare } = runner;
  assert.equal(shapeDiffers(bare, runner), false);
  assert.equal(shapeDiffers(runner, { ...runner, state: 'idle' }), true);
});

test('the figures every heartbeat reports do not move the fleet either', () => {
  for (const [key, value] of [
    ['cpu_percent', 91],
    ['memory_bytes', 123456],
    ['last_heartbeat', '2026-01-01T00:00:30Z'],
    ['usage', { cpu_percent: 80 }],
    ['resource_sample', { cpu_percent: 80 }],
  ] as const) {
    assert.equal(shapeDiffers(host, { ...host, [key]: value }), false, key);
  }
});

test('a host that changed in anything else is a change worth fetching again', () => {
  // The counterpart: the rule is a list of what may move, not a way to hide a
  // host from the grids. Health, capacity and name are what a row is.
  assert.equal(shapeDiffers(host, { ...host, healthy: false }), true);
  assert.equal(shapeDiffers(host, { ...host, capacity: 8 }), true);
  assert.equal(shapeDiffers(host, { ...host, name: 'builder-2' }), true);
});

test('a row the cache has not seen is a change', () => {
  assert.equal(shapeDiffers(undefined, host), true);
});

test('a report that only moved its own time does not move the fleet', () => {
  // The controller sends no frame for such a report, but a frame can still carry
  // a newer checked_at beside a heartbeat. Refetching the Runners and Pools grids
  // for it is a round trip that has nothing to show.
  const summary = { counted: 3, warnings: 1, errors: 0, skipped: 0, suggestions: 0, accepted: 0 };
  const before = { ...host, doctor: { checked_at: '2026-01-01T00:00:00Z', summary, results: [] } };
  const later = { ...before, doctor: { ...before.doctor, checked_at: '2026-01-01T00:01:30Z' } };
  assert.equal(shapeDiffers(before, later), false);
  const worse = {
    ...later,
    doctor: { ...later.doctor, summary: { ...summary, warnings: 2 } },
  };
  assert.equal(shapeDiffers(before, worse), true);
  assert.equal(shapeDiffers(host, before), true, 'a first report is news');
});

test('a host’s update block is the same fleet from one heartbeat to the next, and a new state is not', () => {
  // The controller's block holds nothing that moves with the clock or with a
  // heartbeat, so a frame that repeats it is the fleet unchanged. Were any part
  // of it to move on every beat, every Runners and Pools grid would fetch its
  // page again once per host per heartbeat to learn nothing.
  const update = {
    state: 'requested',
    reason: 'The update to v1.3.0 has been asked for.',
    can_update: false,
    attempt_id: 'upd_1',
  };
  const open = { ...host, version: '1.2.0', version_skew: 'behind', update };
  const nextBeat = {
    ...open,
    cpu_percent: 40,
    last_heartbeat: '2026-01-01T00:00:30Z',
    usage: { cpu_percent: 40 },
    memory_pool: { total_mb: 32768, lent_mb: 512, free_mb: 19000 },
    update: { ...update },
  };
  assert.equal(shapeDiffers(open, nextBeat), false);
  // The attempt closing is news: the host's card, and its version, changed.
  const closed = {
    ...open,
    version: '1.3.0',
    version_skew: undefined,
    update: { ...update, state: 'succeeded' },
  };
  assert.equal(shapeDiffers(open, closed), true);
  assert.equal(shapeDiffers(open, { ...open, update: { ...update, state: 'failed' } }), true);
});

