import { test } from 'node:test';
import assert from 'node:assert/strict';
import { focusIsUnclaimed } from '../src/lib/keys';

// Stand-ins for the three places focus can be when an overlay finishes closing.
// The decision only compares identities and asks the closing panel whether it
// contains the focused element, so plain objects are enough to pin it down.
const body = { name: 'body' };
const insideTheClosingPanel = { name: 'a control that has not been removed yet' };
const elsewhere = { name: 'the message box of a panel that opened as this one closed' };
const closing = { contains: (other: object) => other === insideTheClosingPanel };

// A drawer gives focus back to its opener a frame after it unmounts. That is
// right when nothing else has asked for focus in the meantime, and wrong when it
// has: "Ask Eli" closes the Problems drawer and opens a panel that is not modal,
// and the restore took focus from it and left it on the bell.
test('a closing overlay gives focus back only while nobody else has claimed it', () => {
  assert.equal(focusIsUnclaimed(null, body, closing), true, 'nothing holds focus');
  assert.equal(focusIsUnclaimed(body, body, closing), true, 'the focused control was removed');
  assert.equal(focusIsUnclaimed(insideTheClosingPanel, body, closing), true, 'still in the panel');
  assert.equal(focusIsUnclaimed(elsewhere, body, closing), false, 'another panel took it');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { FrameReads } from '../src/lib/state/frame-reads.ts';

/** A read the test answers by hand, so two can be in flight at once. */
function deferredReads() {
  const pending: ((value: string) => void)[] = [];
  const get = () => new Promise<string>((resolve) => pending.push(resolve));
  return { pending, get };
}

// The overlap the Hosts page met: a read is in flight, a frame lands, the
// rollout button's answer is overtaken, and the page asks again. Joining the
// read already in flight would end on nothing, because that read began before
// the frame and its answer is thrown away; the page would keep the button's
// older picture until something else moved.
test('a fresh read after a frame is not the read that began before it', async () => {
  const { pending, get } = deferredReads();
  const taken: string[] = [];
  const reads = new FrameReads<string>({
    get,
    answer: (value) => taken.push(value),
    failed: () => assert.fail('no read fails here'),
  });

  const first = reads.refresh();
  reads.took();
  const second = reads.fresh();
  assert.equal(pending.length, 2, 'the fresh read is a request of its own');

  pending[0]!('older than the frame');
  await first;
  pending[1]!('newer than the frame');
  await second;
  assert.deepEqual(taken, ['newer than the frame']);
});

// Several pages asking at once is one request, which is what refresh is for.
test('a refresh while a read is in flight joins it', async () => {
  const { pending, get } = deferredReads();
  const taken: string[] = [];
  const reads = new FrameReads<string>({ get, answer: (v) => taken.push(v), failed: () => {} });

  const one = reads.refresh();
  const two = reads.refresh();
  assert.equal(pending.length, 1);
  pending[0]!('the answer');
  await Promise.all([one, two]);
  assert.deepEqual(taken, ['the answer']);
});

// A read that began before a frame says nothing the frame did not say better,
// and its failure is not an error the page has.
test('a read overtaken by a frame neither answers nor fails', async () => {
  let reject: (cause: unknown) => void = () => {};
  const failures: unknown[] = [];
  const reads = new FrameReads<string>({
    get: () => new Promise<string>((_, no) => (reject = no)),
    answer: () => assert.fail('an overtaken read must not answer'),
    failed: (cause) => failures.push(cause),
  });
  const read = reads.refresh();
  reads.took();
  reject(new Error('the network went away'));
  await read;
  assert.deepEqual(failures, []);
});

// The page's spinner is the reads in flight, so it stays on until the last
// one, fresh or joined, has answered.
test('loading lasts until every read has answered', async () => {
  const { pending, get } = deferredReads();
  const reads = new FrameReads<string>({ get, answer: () => {}, failed: () => {} });
  const first = reads.refresh();
  reads.took();
  const second = reads.fresh();
  pending[0]!('a');
  await first;
  assert.equal(reads.loading, true);
  pending[1]!('b');
  await second;
  assert.equal(reads.loading, false);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  ACCEPT_EXPIRY_CHOICES,
  acceptEndsAt,
  acceptNote,
  acceptedIds,
  acceptedLast,
  canAccept,
  endedNote,
} from '../src/lib/hosts/accept.ts';
import { attention, healthSummary } from '../src/lib/hosts/health.ts';
import type { DoctorResult } from '../src/lib/hosts/health.ts';
import { reportChanges } from '../src/lib/hosts/report-changes.ts';
import { rowKind } from '../src/lib/hosts/row-kind.ts';
import { REASON_MAX, REASON_MIN, reasonHint, reasonLength } from '../src/lib/reason.ts';
import type { Host } from '../src/lib/api/types.ts';

type Report = NonNullable<Host['doctor']>;
const t0 = Date.parse('2026-10-04T10:00:00Z');
const ctx = { prevVersion: 'v1', nextVersion: 'v1' };
const grant = {
  reason: 'Pinned on purpose until the vendor kernel ships',
  by: 'Sam',
  at: '2026-10-01T10:00:00Z',
  expires_at: '2027-10-01T10:00:00Z',
};

function row(id: string, status: DoctorResult['status'], over: Partial<DoctorResult> = {}) {
  return {
    id,
    title: `Title of ${id}`,
    tier: 'safe',
    status,
    current: 'now',
    recommended: 'later',
    rationale: '',
    actionable: false,
    ...over,
  } as DoctorResult;
}
function report(results: DoctorResult[], at = t0): Report {
  const counted = results.filter((r) => r.tier === 'safe' && r.optional !== true);
  const accepted = counted.filter((r) => r.accepted).length;
  return {
    checked_at: new Date(at).toISOString(),
    os: 'linux',
    distro: 'ubuntu 24.04',
    container: false,
    reboot_pending: false,
    results,
    summary: {
      counted: counted.length,
      warnings: counted.filter((r) => r.status === 'warn').length - accepted,
      errors: counted.filter((r) => r.status === 'error').length,
      skipped: counted.filter((r) => r.status === 'skip').length,
      suggestions: 0,
      accepted,
    },
  } as Report;
}

test('an accepted warning leaves Needs attention, so its length is still warnings plus errors', () => {
  // The controller stops counting it; a list that kept it would disagree with
  // the pill beside it.
  const r = report([row('a', 'warn', { accepted: grant }), row('b', 'warn')]);
  assert.deepEqual(
    attention(r).map((c) => c.id),
    ['b'],
  );
  assert.equal(attention(r).length, r.summary.warnings + r.summary.errors);
});

test('the pill hint says how many checks were accepted, and says nothing when none were', () => {
  const some = report([row('a', 'warn', { accepted: grant }), row('b', 'ok')]);
  const hint = healthSummary(some, t0 + 1000).hint;
  assert.match(hint, /Also 1 accepted check, which do not count towards health\./);
  assert.equal(healthSummary(some, t0 + 1000).label, 'Health OK');
  assert.doesNotMatch(healthSummary(report([row('b', 'ok')]), t0 + 1000).hint, /accepted/);
});

test('a controller that predates acceptance reads as none accepted', () => {
  const old = report([row('b', 'ok')]);
  delete (old.summary as Partial<Report['summary']>).accepted;
  assert.equal(healthSummary(old, t0 + 1000).accepted, 0);
});

test('an accepted row has no Fixable, Advice or Optional word', () => {
  assert.equal(rowKind(row('a', 'warn', { accepted: grant, actionable: true }), false), null);
  assert.equal(rowKind(row('a', 'warn', { actionable: true }), false), 'fixable');
});

test('only a row the controller marks acceptable offers Accept, and an accepted one no longer does', () => {
  assert.equal(canAccept(row('a', 'warn', { acceptable: true })), true);
  assert.equal(canAccept(row('a', 'warn')), false);
  assert.equal(canAccept(row('a', 'warn', { acceptable: true, accepted: grant })), false);
});

test('accepted rows sort after the unaccepted ones and keep their order otherwise', () => {
  const rows = [
    row('a', 'warn', { accepted: grant }),
    row('b', 'warn'),
    row('c', 'warn', { accepted: grant }),
    row('d', 'warn'),
  ];
  assert.deepEqual(
    acceptedLast(rows).map((r) => r.id),
    ['b', 'd', 'a', 'c'],
  );
});

test('the accepted note names who, when, until when and the reason, as plain text', () => {
  const now = Date.parse('2026-10-04T10:00:00Z');
  const note = acceptNote({ ...grant, reason: '<b>why</b>' }, now);
  assert.match(note, /^Accepted by Sam 3d ago, until [^:]*2027: “<b>why<\/b>”$/);
});

test('an ended acceptance says why the row counts again, in the three ways it can', () => {
  const was = { by: 'Sam', at: '2026-10-01T10:00:00Z', was: '5.15' };
  assert.match(
    endedNote({ current: '5.4', ended: { ...was, why: 'changed' } }) ?? '',
    /while it read “5\.15”\. It now reads “5\.4”, so it counts again\. Accept it again/,
  );
  assert.match(
    endedNote({ current: '5.15', ended: { ...was, why: 'expired' } }) ?? '',
    /^Sam’s acceptance ended on .+, so it counts again\.$/,
  );
  assert.match(
    endedNote({ current: '', ended: { ...was, why: 'worse' } }) ?? '',
    /because the check could not run/,
  );
  assert.equal(endedNote({ current: 'x' }), null);
});

test('an accept frame announces nothing, and neither does an accepted check turning OK', () => {
  // The decision is the person's own; announcing "resolved" for it, or "needs
  // attention" for a revoke, would be the page contradicting what they just did.
  const before = report([row('a', 'warn')]);
  const accepted = report([row('a', 'warn', { accepted: grant })]);
  assert.deepEqual(reportChanges(before, accepted, ctx), []);
  const ok = report([row('a', 'ok')], t0 + 60_000);
  assert.deepEqual(reportChanges(accepted, ok, ctx), []);
});

test('the accepted ids are compared as a sorted set, so a frame that moves one is told from a heartbeat', () => {
  const one = [row('b', 'warn', { accepted: grant }), row('a', 'warn')];
  const two = [row('b', 'warn', { accepted: grant }), row('a', 'warn', { accepted: grant })];
  assert.equal(acceptedIds(one), 'b');
  assert.equal(acceptedIds(two), 'a\nb');
  assert.equal(acceptedIds([...two].reverse()), acceptedIds(two));
});

test('every way to choose how long an acceptance runs is shorter than the controller allows, and none is shorter than a week', () => {
  const days = ACCEPT_EXPIRY_CHOICES.map((choice) => Number(choice.value));
  assert.ok(Math.max(...days) <= 364);
  assert.equal(Math.min(...days), 7);
  const now = new Date('2026-10-04T10:00:00Z');
  assert.equal(acceptEndsAt(7, now), '2026-10-11T10:00:00.000Z');
});

test('the reason is held to the bounds the controller states', () => {
  assert.equal(REASON_MIN, 10);
  assert.equal(REASON_MAX, 500);
  assert.equal(reasonLength('🐕🐕🐕🐕🐕🐕🐕🐕🐕🐕'), 10);
  assert.match(reasonHint('short', 'deliberate'), /say why this is deliberate/);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { backendRows, backendTrouble } from '../src/lib/hosts/backends.ts';

// A closed host card folds the Backends block away. That block is where the
// agent explains why a host has nothing to run a job in, so these are the cases
// in which the card must not fold it, and the ordinary ones in which it must.

test('a host with no backend that works is trouble, whatever the agent says about each', () => {
  assert.equal(
    backendTrouble({
      backend_info: [
        { kind: 'docker', available: false, detail: 'permission denied on the socket' },
        { kind: 'podman', available: false, detail: 'no socket' },
      ],
    }),
    true,
  );
  assert.equal(backendTrouble({ backend_info: [{ kind: 'podman', available: false }] }), true);
});

test('one working backend is enough: a missing second one is the ordinary case, not trouble', () => {
  // Docker without Podman is how most hosts are. The agent reports Podman as
  // unavailable with the commands to install it, and a card that surfaced that
  // paragraph would put the same one on every host in the fleet.
  assert.equal(
    backendTrouble({
      backend_info: [
        { kind: 'docker', available: true },
        { kind: 'podman', available: false, detail: 'no socket at /run/user/1000/podman.sock' },
      ],
    }),
    false,
  );
});

test('a backend that does not say it is unavailable counts as working', () => {
  // `available` omitted is how an older agent says nothing is wrong.
  assert.equal(backendTrouble({ backend_info: [{ kind: 'docker' }] }), false);
});

test('a host that reports no backend at all is trouble, because no runner can be placed on it', () => {
  assert.equal(backendTrouble({}), true);
  assert.equal(backendTrouble({ backend_info: [], backends: [] }), true);
});

test('the plain list of kinds stands in for the rich one when that is all an agent sends', () => {
  assert.equal(backendTrouble({ backend_info: [], backends: ['docker'] }), false);
  assert.deepEqual(backendRows([], ['docker', 'podman']), [{ kind: 'docker' }, { kind: 'podman' }]);
});

test('the rich list wins over the plain one when both are present', () => {
  // Otherwise a kinds list that still names a backend the agent has since
  // marked unavailable would hide the trouble.
  assert.equal(
    backendTrouble({
      backend_info: [{ kind: 'docker', available: false }],
      backends: ['docker'],
    }),
    true,
  );
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { allExpanded, isIdList, setAllExpanded, setExpanded } from '../src/lib/hosts/card-fold.ts';

test('a stored choice is trusted only while it is a list of host ids', () => {
  // A value left by an older build, or edited by hand, must fall back to every
  // card closed rather than throw on the first card that asks.
  assert.equal(isIdList([]), true);
  assert.equal(isIdList(['host_a', 'host_b']), true);
  for (const bad of [null, undefined, 'host_a', 7, {}, [1], ['host_a', 2], [null]]) {
    assert.equal(isIdList(bad), false, JSON.stringify(bad));
  }
});

test('opening a card remembers it once, however many times it is opened', () => {
  const known = ['host_a', 'host_b', 'host_c'];
  const once = setExpanded([], 'host_b', true, known);
  assert.deepEqual(once, ['host_b']);
  assert.deepEqual(setExpanded(once, 'host_b', true, known), ['host_b']);
  assert.deepEqual(setExpanded(once, 'host_a', true, known), ['host_b', 'host_a']);
});

test('closing a card forgets it and leaves the others open', () => {
  const known = ['host_a', 'host_b', 'host_c'];
  assert.deepEqual(setExpanded(['host_a', 'host_b'], 'host_a', false, known), ['host_b']);
  assert.deepEqual(
    setExpanded(['host_b'], 'host_c', false, known),
    ['host_b'],
    'not open: no change',
  );
});

test('hosts that no longer exist are forgotten the next time a choice is made', () => {
  // Machines come and go as pools scale, so without this the list would keep an
  // id for every host anyone ever opened.
  const remembered = ['host_gone', 'host_a'];
  assert.deepEqual(setExpanded(remembered, 'host_b', true, ['host_a', 'host_b']), [
    'host_a',
    'host_b',
  ]);
  assert.deepEqual(setExpanded(remembered, 'host_a', false, ['host_a']), []);
});

test('the list it is handed is never changed', () => {
  // The page replaces its state with the answer. A function that edited the old
  // array in place would hand back the very array already held, and nothing
  // would repaint.
  const held = ['host_a'];
  const next = setExpanded(held, 'host_b', true, ['host_a', 'host_b']);
  assert.deepEqual(held, ['host_a']);
  assert.notEqual(next, held);
});

test('every card on show is open only when each of them is on the list', () => {
  const shown = ['host_a', 'host_b'];
  assert.equal(allExpanded(['host_a', 'host_b'], shown), true);
  assert.equal(
    allExpanded(['host_b', 'host_a', 'host_z'], shown),
    true,
    'a card the filter hides, open or not, does not change the answer',
  );
  assert.equal(allExpanded(['host_a'], shown), false);
  assert.equal(allExpanded([], shown), false);
});

test('no card on show is never "all open", so the button cannot offer to close what is not there', () => {
  assert.equal(allExpanded([], []), false);
  assert.equal(allExpanded(['host_a'], []), false);
});

test('opening all opens the cards on show and leaves the others as they were', () => {
  const known = ['host_a', 'host_b', 'host_c'];
  assert.deepEqual(setAllExpanded(['host_c'], ['host_a', 'host_b'], true, known), [
    'host_c',
    'host_a',
    'host_b',
  ]);
  // A card that was already open is kept where it was and not listed twice.
  assert.deepEqual(setAllExpanded(['host_b'], ['host_a', 'host_b'], true, known), [
    'host_b',
    'host_a',
  ]);
});

test('closing all closes the cards on show and leaves the others open', () => {
  const known = ['host_a', 'host_b', 'host_c'];
  assert.deepEqual(
    setAllExpanded(['host_a', 'host_b', 'host_c'], ['host_a', 'host_b'], false, known),
    ['host_c'],
  );
  assert.deepEqual(setAllExpanded([], ['host_a'], false, known), [], 'nothing open: no change');
});

test('hosts that no longer exist are forgotten when every card is opened or closed together', () => {
  assert.deepEqual(setAllExpanded(['host_gone'], ['host_a'], true, ['host_a']), ['host_a']);
  assert.deepEqual(setAllExpanded(['host_gone', 'host_a'], ['host_a'], false, ['host_a']), []);
  // A card that is not in the known list is not a card, so it is not opened.
  assert.deepEqual(setAllExpanded([], ['host_a', 'host_ghost'], true, ['host_a']), ['host_a']);
});

test('the lists it is handed are never changed, however many cards it opens', () => {
  const held = ['host_a'];
  const shown = ['host_b', 'host_c'];
  const next = setAllExpanded(held, shown, true, ['host_a', 'host_b', 'host_c']);
  assert.deepEqual(held, ['host_a']);
  assert.deepEqual(shown, ['host_b', 'host_c']);
  assert.notEqual(next, held);
});

test('the lists it is handed are not changed when it prunes or closes either', () => {
  // The test above has nothing to prune and only opens, so a version that tidied
  // the stored list in place, or closed cards in place and handed the same array
  // back, would pass it and then repaint nothing. Frozen lists make any edit in
  // place throw, in both directions and with a host that has gone in the way.
  const held = Object.freeze(['host_gone', 'host_a', 'host_b']);
  const shown = Object.freeze(['host_a']);
  const known = Object.freeze(['host_a', 'host_b']);
  assert.deepEqual(setAllExpanded(held, shown, false, known), ['host_b']);
  assert.deepEqual(setAllExpanded(held, shown, true, known), ['host_a', 'host_b']);
  assert.deepEqual(held, ['host_gone', 'host_a', 'host_b']);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  CEILING_MS,
  FEATURE,
  KEEP_MS,
  ROLE_SENTENCE,
  WAITING_AFTER_MS,
  checkNow,
  idleTitle,
  superseded,
  unavailableReason,
  type CheckNow,
  type CheckNowInput,
} from '../src/lib/hosts/check-now.ts';

const now = Date.parse('2026-10-08T10:00:00Z');
const at = (offsetMs: number) => new Date(now + offsetMs).toISOString();

function host(over: Partial<CheckNowInput['host']> = {}): CheckNowInput['host'] {
  return { name: 'build-1', healthy: true, features: [FEATURE], ...over };
}
const run = (over: Partial<CheckNowInput> = {}): CheckNow =>
  checkNow({ host: host(), canOperate: true, now, ...over });
const withCheck = (hc: NonNullable<CheckNowInput['host']['health_check']>) =>
  host({ health_check: hc });

// The page used to have no button and a test that asserts there is none matching
// /apply|tune/. A word like "fortunate" would sneak one in through a tooltip, so
// every string this module can produce is held to the same rule.
const FORBIDDEN = /apply|tune/i;

function everyString(): string[] {
  const hosts = [
    host(),
    host({ healthy: false }),
    host({ incompatible: true }),
    host({ incompatible: true, incompatible_reason: 'The agent speaks protocol 3.' }),
    host({ features: [] }),
    withCheck({ state: 'asked', asked_at: at(0) }),
    withCheck({ state: 'asked', asked_at: at(-CEILING_MS) }),
    withCheck({ state: 'failed', asked_at: at(-1000), message: 'It could not run.' }),
    withCheck({ state: 'failed', asked_at: at(-1000) }),
    ...(['first', 'changed', 'unchanged', 'not_newer', 'odd'] as const).map((outcome) =>
      withCheck({
        state: 'done',
        asked_at: at(-1000),
        outcome: outcome as 'first',
        next_at: at(9000),
      }),
    ),
  ];
  const out: string[] = [ROLE_SENTENCE, idleTitle('build-1')];
  for (const h of hosts)
    for (const changes of [0, 1, 3])
      for (const restate of [false, true])
        for (const posting of [false, true])
          for (const localAskedAt of [null, now - 10_000, now - CEILING_MS - 1]) {
            const r = checkNow({
              host: h,
              canOperate: true,
              now,
              changes,
              restate,
              posting,
              localAskedAt,
            });
            out.push(r.title);
            for (const s of [r.reason, r.status, r.announce]) if (s) out.push(s);
          }
  return out;
}

test('no sentence the button can produce mentions applying or tuning', () => {
  const all = everyString();
  assert.ok(all.length > 20);
  for (const s of all) assert.doesNotMatch(s, FORBIDDEN, s);
  // The label itself is the page's, and it must not match either.
  assert.doesNotMatch('Check now', FORBIDDEN);
});

test('a viewer sees no button, only the sentence naming the role', () => {
  // A button the controller would refuse is a trap, and the viewer still needs
  // to know why the page offers nothing.
  const r = run({ canOperate: false });
  assert.equal(r.show, false);
  assert.equal(r.status, ROLE_SENTENCE);
  assert.equal(r.statusKind, 'role');
});

test('an idle host that advertises host-check gets an enabled button and no line', () => {
  const r = run();
  assert.deepEqual(
    { show: r.show, disabled: r.disabled, loading: r.loading, kind: r.statusKind },
    { show: true, disabled: false, loading: false, kind: 'idle' },
  );
  assert.equal(r.status, undefined);
  assert.equal(r.reason, undefined);
  assert.equal(r.title, idleTitle('build-1'));
});

test('the gate is the advertised feature, whatever the report says about containers', () => {
  // The Compose host-health service reports container=false and still cannot
  // answer, so a report flag must never decide this.
  const nativeLooking = {
    ...host({ features: ['tool-cache-fill'] }),
    doctor: { container: false, os: 'linux' },
  };
  const r = run({ host: nativeLooking });
  assert.equal(r.disabled, true);
  assert.match(r.reason ?? '', /cannot check on request/);
  assert.match(r.reason ?? '', /container/);
  const containerLooking = {
    ...host(),
    doctor: { container: true, os: 'linux' },
  };
  assert.equal(run({ host: containerLooking }).disabled, false);
  assert.equal(run({ host: host({ features: undefined }) }).disabled, true);
});

test('each reason the button is off is a sentence beside it, in the controller’s order', () => {
  const cases: [string, CheckNowInput['host'], RegExp][] = [
    ['not connected', host({ healthy: false }), /^build-1 is not connected, so it cannot be asked/],
    [
      'incompatible with the controller’s own words',
      host({ incompatible: true, incompatible_reason: 'The agent speaks protocol 3.' }),
      /^The agent speaks protocol 3\.$/,
    ],
    ['incompatible without words', host({ incompatible: true }), /Update the agent\.$/],
    ['cannot check', host({ features: [] }), /^The agent on build-1 cannot check on request/],
    [
      'not connected wins over the missing flag',
      host({ healthy: false, features: [] }),
      /is not connected/,
    ],
    [
      'incompatible wins over the missing flag',
      host({ incompatible: true, features: [] }),
      /Update the agent/,
    ],
  ];
  for (const [label, h, want] of cases) {
    const r = run({ host: h });
    assert.equal(r.show, true, label);
    assert.equal(r.disabled, true, label);
    assert.match(r.reason ?? '', want, label);
    assert.equal(r.statusKind, 'unavailable', label);
  }
  assert.equal(unavailableReason(host()), null);
});

test('a press in flight reads as asking, and is announced once', () => {
  const r = run({ posting: true });
  assert.equal(r.loading, true);
  assert.equal(r.statusKind, 'asking');
  assert.equal(r.status, 'Asked build-1 to check itself…');
  assert.equal(r.announce, r.status);
});

test('an ask the controller holds is asking, then waiting after five seconds, which is not announced', () => {
  const fresh = run({ host: withCheck({ state: 'asked', asked_at: at(-1000) }) });
  assert.equal(fresh.statusKind, 'asking');
  assert.equal(fresh.loading, true);
  assert.ok(fresh.announce);
  const slow = run({ host: withCheck({ state: 'asked', asked_at: at(-WAITING_AFTER_MS) }) });
  assert.equal(slow.statusKind, 'waiting');
  assert.equal(slow.loading, true);
  assert.match(slow.status ?? '', /^Still waiting for build-1 to answer\./);
  // The sentence changing is not news, so a screen reader is not told again.
  assert.equal(slow.announce, undefined);
});

test('the page’s own press time wins over the server’s clock, which may be skewed', () => {
  const skewed = withCheck({ state: 'asked', asked_at: at(-60_000) });
  assert.equal(run({ host: skewed, localAskedAt: now - 1000 }).statusKind, 'asking');
});

test('an ask the controller still shows after the page’s patience is a failure', () => {
  const r = run({ host: withCheck({ state: 'asked', asked_at: at(-CEILING_MS) }) });
  assert.equal(r.statusKind, 'failed');
  assert.match(r.status ?? '', /^build-1 did not answer in time\./);
  assert.equal(r.loading, false);
  assert.ok(r.failureKey);
  // A failure is inline text and a toast, never a polite announcement read twice.
  assert.equal(r.announce, undefined);
});

test('a controller that forgot the ask leaves the page its own ceiling', () => {
  // Nothing on the view at all: a restart empties the controller's memory.
  const waiting = run({ localAskedAt: now - 10_000 });
  assert.equal(waiting.statusKind, 'waiting');
  assert.equal(waiting.loading, true);
  const failed = run({ localAskedAt: now - CEILING_MS });
  assert.equal(failed.statusKind, 'failed');
  assert.equal(failed.failureKey, `local:${now - CEILING_MS}`);
  const gone = run({ localAskedAt: now - CEILING_MS - KEEP_MS });
  assert.equal(gone.statusKind, 'idle');
  assert.equal(gone.status, undefined);
});

test('a done check says what it found, with the count from the page’s own diff', () => {
  const done = (outcome: string, extra: Partial<CheckNowInput> = {}) =>
    run({
      host: withCheck({
        state: 'done',
        asked_at: at(-3000),
        outcome: outcome as 'first',
      }),
      ...extra,
    });
  assert.equal(done('first').status, 'Checked just now. This is the first report from build-1.');
  assert.equal(
    done('unchanged').status,
    'Checked just now. Nothing has changed since the last report.',
  );
  assert.equal(
    done('changed', { changes: 1 }).status,
    'Checked just now. 1 change since the last report, listed below.',
  );
  assert.equal(
    done('changed', { changes: 4 }).status,
    'Checked just now. 4 changes since the last report, listed below.',
  );
  assert.match(done('changed', { changes: 0 }).status ?? '', /nothing that counts towards/);
  const stale = done('not_newer');
  assert.match(stale.status ?? '', /^build-1 answered, but its clock is behind the last report/);
  for (const o of ['first', 'unchanged', 'changed', 'not_newer'])
    assert.equal(done(o).statusKind, 'done', o);
  // The count may land a beat after the frame, so what is spoken leaves it out.
  assert.equal(
    done('changed', { changes: 3 }).announce,
    'Checked just now. The report has changed.',
  );
  assert.equal(done('unchanged').announce, done('unchanged').status);
});

test('a press inside the cooldown restates the wait and the button stays enabled', () => {
  const hc = {
    state: 'done' as const,
    asked_at: at(-3000),
    outcome: 'unchanged' as const,
    next_at: at(9500),
  };
  const quiet = run({ host: withCheck(hc) });
  assert.equal(quiet.cooling, true);
  assert.equal(quiet.disabled, false);
  assert.equal(quiet.statusKind, 'done');
  const pressed = run({ host: withCheck(hc), restate: true });
  assert.equal(pressed.statusKind, 'cooling');
  assert.equal(pressed.disabled, false);
  assert.equal(pressed.status, 'Checked just now. You can check again in 10 s.');
  // A countdown that ticks is never read out.
  assert.equal(pressed.announce, undefined);
  const later = checkNow({
    host: withCheck(hc),
    canOperate: true,
    now: now + 9000,
    restate: true,
  });
  assert.equal(later.status, 'Checked just now. You can check again in 1 s.');
  const over = checkNow({
    host: withCheck(hc),
    canOperate: true,
    now: now + 9500,
    restate: true,
  });
  assert.equal(over.cooling, false);
  assert.equal(over.statusKind, 'done');
});

test('a failure keeps the cooldown, because failing fast must not make asking free', () => {
  const hc = {
    state: 'failed' as const,
    asked_at: at(-2000),
    message: 'build-1 could not run its checks: boom',
    next_at: at(13_000),
  };
  const r = run({ host: withCheck(hc) });
  assert.equal(r.statusKind, 'failed');
  assert.equal(r.status, hc.message);
  assert.equal(r.cooling, true);
  assert.equal(r.failureKey, `failed:${hc.asked_at}`);
  const pressed = run({ host: withCheck(hc), restate: true });
  assert.equal(pressed.statusKind, 'cooling');
  assert.match(
    pressed.status ?? '',
    /^build-1 was asked a moment ago\. You can ask again in 13 s\.$/,
  );
});

test('a failure with no message from the controller still says something to act on', () => {
  const r = run({ host: withCheck({ state: 'failed', asked_at: at(-2000) }) });
  assert.match(r.status ?? '', /Check that its agent is running/);
});

test('an unavailable host that was just checked keeps the answer and the reason', () => {
  const r = run({
    host: host({
      healthy: false,
      health_check: { state: 'done', asked_at: at(-3000), outcome: 'unchanged' },
    }),
  });
  assert.equal(r.disabled, true);
  assert.match(r.reason ?? '', /not connected/);
  assert.equal(r.statusKind, 'done');
});

test('an answer to the ask that is older than what the page holds is not written over it', () => {
  // The agent can answer before the 202 comes back. Writing the 202 afterwards
  // would put the old report back, and nothing would ever send another frame.
  const asked = { state: 'asked' as const, asked_at: at(-2000) };
  const done = { state: 'done' as const, asked_at: at(-2000), outcome: 'changed' as const };
  assert.equal(superseded(done, asked), true);
  assert.equal(superseded(asked, asked), false);
  assert.equal(superseded(asked, done), false);
  assert.equal(superseded(undefined, asked), false);
  assert.equal(superseded(done, undefined), false);
  // Somebody else asked again since: that ask is newer than this answer.
  assert.equal(superseded({ state: 'asked', asked_at: at(-1000) }, asked), true);
  assert.equal(superseded({ state: 'done', asked_at: at(-5000) }, asked), false);
});

