  assert.equal(line.firstId, 'disk space/x');
  assert.equal(line.href, '/hosts/host_1#disk%20space%2Fx');
});

test('a stale report, a container and a clean host get no line and no hash', () => {
  // A stale or container card must never list last-known checks as current.
  const warn = [check('a', 'Disk space')];
  for (const line of [
    cardLine(host(warn), { stale: true }),
    cardLine(host(warn, { container: true }), fresh),
    cardLine(host([check('a', 'Disk space', 'ok')]), fresh),
    cardLine(host([check('kernel.pending', 'Reboot')], { reboot_pending: true }), fresh),
    cardLine({ id: 'host_1', doctor: undefined }, fresh),
  ]) {
    assert.equal(line.text, '');
    assert.equal(line.firstId, null);
    assert.equal(line.href, '/hosts/host_1');
  }
});

test('a title a host wrote at length is clipped so the card keeps its shape', () => {
  const line = cardLine(host([check('a', 'x'.repeat(200), 'error')]), fresh);
  assert.equal([...line.text].length, 40);
  assert.ok(line.text.endsWith('…'));
});

test('the card calls a disk low by the same rule as the check, strictly below both limits', () => {
  // The card and the Warning row must never disagree: 8 GiB free of 60 is a
  // Warning row, so it must be amber too.
  assert.equal(diskIsLow(8 * 1024, 60 * 1024), true, 'under 10 GiB');
  assert.equal(diskIsLow(10 * 1024, 100 * 1024), false, 'exactly 10 GiB and 10 percent');
  assert.equal(diskIsLow(10 * 1024 - 1, 100 * 1024), true, 'a MiB under 10 GiB');
  assert.equal(diskIsLow(51_200, 512_000), false, 'exactly 10 percent of a big disk');
  assert.equal(diskIsLow(51_199, 512_000), true, 'just under 10 percent of a big disk');
  assert.equal(diskIsLow(31 * 1024, 512 * 1024), true, 'six percent');
  assert.equal(diskIsLow(0, 0), false, 'unmeasured is not full');
  assert.equal(diskIsLow(500, 0), false, 'no total, no verdict');
});

test('the disk figure links to its check only when a current full report has one', () => {
  const withDisk = host([check('disk.space', 'Work directory free space', 'ok')]);
  assert.equal(diskLink(withDisk, fresh), '/hosts/host_1#disk.space');
  assert.equal(diskLink(withDisk, { stale: true }), null, 'a stale report is not evidence');
  assert.equal(diskLink(host([check('a', 'Other')]), fresh), null, 'no disk row to land on');
  assert.equal(
    diskLink(host([check('disk.space', 'Free', 'warn')], { container: true }), fresh),
    null,
    'a container sees its own filesystem',
  );
  assert.equal(diskLink({ id: 'host_1' }, fresh), null, 'no report at all');
  assert.equal(
    diskLink({ ...withDisk, id: 'a/b' }, fresh),
    '/hosts/a%2Fb#disk.space',
    'the id is escaped in the path',
  );
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import type { Host } from '../src/lib/api/types.ts';
import { healthSummary, type DoctorReport, type DoctorResult } from '../src/lib/hosts/health.ts';
import {
  HEALTH_FILTERS,
  attentionDetail,
  emptyCopy,
  filterSentence,
  healthBucket,
  healthCounts,
  healthFilterFrom,
  hostsFor,
  type HealthCounts,
} from '../src/lib/hosts/health-filter.ts';

const now = Date.parse('2026-10-04T10:00:00Z');
const MINUTE = 60_000;

function result(id: string, status: DoctorResult['status']): DoctorResult {
  return {
    id,
    title: id,
    tier: 'safe',
    status,
    current: '',
    recommended: '',
    rationale: '',
    actionable: false,
  };
}

/**
 * The controller's count of a report, written out as a stand-in for the real one
 * (hosttune.Report.Summary), because the bucket reads `summary` through the pill
 * and a fixture without one would be "No report" every time. That this agrees
 * with a real controller is the host-health Playwright spec's to prove.
 */
function summaryOf(results: DoctorResult[], reboot: boolean): DoctorReport['summary'] {
  const out = { counted: 0, warnings: 0, errors: 0, skipped: 0, suggestions: 0, accepted: 0 };
  for (const r of results) {
    if (reboot && r.id === 'kernel.pending' && r.status === 'warn') continue;
    out.counted++;
    if (r.status === 'warn') out.warnings++;
    if (r.status === 'error') out.errors++;
    if (r.status === 'skip') out.skipped++;
  }
  return out;
}

function report(
  results: DoctorResult[],
  { reboot = false, container = false, age = 0 } = {},
): DoctorReport {
  return {
    checked_at: new Date(now - age).toISOString(),
    os: 'linux',
    distro: 'ubuntu 24.04',
    container,
    reboot_pending: reboot,
    results,
    summary: summaryOf(results, reboot),
  };
}

// `healthy` has no default on purpose: a default parameter would turn an explicit
// `undefined` into `true`, and "the payload left it out" is a case worth testing.
function host(doctor: DoctorReport | undefined, healthy?: boolean) {
  return { doctor, healthy } satisfies Pick<Host, 'doctor' | 'healthy'>;
}

/** A host whose agent is connected, which is what nearly every case wants. */
function connected(doctor: DoctorReport | undefined) {
  return host(doctor, true);
}

const ok = [result('disk.space', 'ok')];

test('a host that has sent no OS report is in No report', () => {
  assert.equal(healthBucket(connected(undefined), now), 'no-report');
});

// The pill calls a report that arrived without the controller's count "Health
// unavailable", and healthSummary also calls a missing report stale. If the
// stale test ran first, both would land in Report stale and the chip called No
// report would be empty for the one host it exists to find.
test('a report that arrived without the controller’s count is No report, not stale', () => {
  const r = report(ok);
  delete (r as Partial<DoctorReport>).summary;
  assert.equal(healthBucket(connected(r), now), 'no-report');
});

test('a fresh report with an error, a warning or only a pending reboot needs attention', () => {
  assert.equal(healthBucket(connected(report([result('disk.space', 'error')])), now), 'attention');
  assert.equal(healthBucket(connected(report([result('disk.space', 'warn')])), now), 'attention');
  assert.equal(healthBucket(connected(report(ok, { reboot: true })), now), 'attention');
});

test('a fresh report with nothing to do, or nothing it can say, is in no bucket at all', () => {
  assert.equal(healthBucket(connected(report(ok)), now), null);
  // Every check skipped is "Checks unavailable", which is not a finding.
  assert.equal(healthBucket(connected(report([result('disk.space', 'skip')])), now), null);
  assert.equal(healthBucket(connected(report([])), now), null);
});

// The pill ignores a container's findings and its reboot flag, because the
// controller raises nothing for them. A filter that counted them would put a
// host in "Need attention" that nothing else on the page, or in the problems
// drawer, says needs it.
test('a container’s partial report is never counted, whatever it found', () => {
  const partial = report([result('environment', 'warn'), result('disk.space', 'error')], {
    reboot: true,
    container: true,
  });
  assert.equal(healthBucket(connected(partial), now), null);
});

// Mirrors the strict `>` in healthSummary. If the threshold moves, this fails,
// and so do the "three minutes" strings in the chip titles and the empty state,
// which is the point: they are written for this number.
test('a report is stale only once it is older than three minutes', () => {
  const errored = [result('disk.space', 'error')];
  assert.equal(healthBucket(connected(report(errored, { age: 3 * MINUTE })), now), 'attention');
  assert.equal(healthBucket(connected(report(errored, { age: 3 * MINUTE + 1 })), now), 'stale');
});

test('a host whose agent is not connected is stale, even with a fresh report', () => {
  const fresh = report([result('disk.space', 'error')]);
  assert.equal(healthBucket(host(fresh, false), now), 'stale');
  // A payload that leaves `healthy` out (the generated type makes it optional)
  // reads as reachable, as the card's pill does. If the bucket ever read
  // `healthy === true` instead, this host would land in Report stale while its
  // pill still said warnings, and the tile and the pill would disagree.
  assert.equal(host(fresh).healthy, undefined, 'the fixture must really omit it');
  assert.equal(healthBucket(host(fresh), now), 'attention');
});

// Its pill is the neutral "Report stale", not the amber one, so the
// chip that says "Need attention" must not hold it.
test('a stale host that is also waiting for a reboot is stale, not attention', () => {
  const waiting = report(ok, { reboot: true, age: 4 * MINUTE });
  assert.equal(healthSummary(waiting, now).label, 'Report stale');
  assert.equal(healthBucket(connected(waiting), now), 'stale');
});

// The tile, the chip and the card's pill must agree, and the only way to be sure
// they always do is to ask the pill. This walks every shape of report the page
// can meet and checks the bucket against the pill's own words.
test('a host is in Need attention exactly when its pill is amber or red and current', () => {
  const shapes: Array<[string, Pick<Host, 'doctor' | 'healthy'>]> = [
    ['no report', connected(undefined)],
    ['clean', connected(report(ok))],
    ['warning', connected(report([result('a', 'warn')]))],
    ['error', connected(report([result('a', 'error')]))],
    ['reboot only', connected(report(ok, { reboot: true }))],
    ['error and reboot', connected(report([result('a', 'error')], { reboot: true }))],
    ['skipped', connected(report([result('a', 'skip')]))],
    ['empty', connected(report([]))],
    ['container', connected(report([result('a', 'warn')], { reboot: true, container: true }))],
    ['old error', connected(report([result('a', 'error')], { age: 10 * MINUTE }))],
    ['old reboot', connected(report(ok, { reboot: true, age: 10 * MINUTE }))],
    ['unknown reachability error', host(report([result('a', 'error')]))],
    ['unreachable error', host(report([result('a', 'error')]), false)],
    ['unreachable clean', host(report(ok), false)],
  ];
  for (const [name, h] of shapes) {
    const pill = h.doctor?.summary ? healthSummary(h.doctor, now, h.healthy) : undefined;
    const expected = pill !== undefined && !pill.stale && ['danger', 'pending'].includes(pill.tone);
    assert.equal(healthBucket(h, now) === 'attention', expected, name);
  }
});

// The shortfall is the point: a clean host is in none of the three, and the
// page says so rather than letting the chips look as though they sum to All.
test('the buckets are exclusive and do not add up to All', () => {
  const hosts = [
    connected(undefined),
    connected(report(ok)),
    connected(report([result('a', 'warn')])),
    connected(report(ok, { reboot: true })),
    connected(report(ok, { age: 5 * MINUTE })),
    host(report(ok), false),
    connected(report([], { container: true })),
  ];
  const counts = healthCounts(hosts, now);
  assert.equal(counts.all, hosts.length);
  assert.deepEqual(
    [counts.attention, counts.stale, counts['no-report']],
    [2, 2, 1],
    'each host is counted once, in one bucket',
  );
  assert.ok(counts.attention + counts.stale + counts['no-report'] < counts.all);
});

test('filtering by All hands back the same array, and a bucket keeps only its hosts', () => {
  const warned = { ...connected(report([result('a', 'warn')])), id: 'warned' };
  const clean = { ...connected(report(ok)), id: 'clean' };
  const silent = { ...connected(undefined), id: 'silent' };
  const hosts = [warned, clean, silent];
  assert.equal(hostsFor(hosts, 'all', now), hosts);
  assert.deepEqual(
    hostsFor(hosts, 'attention', now).map((h) => h.id),
    ['warned'],
  );
  assert.deepEqual(
    hostsFor(hosts, 'no-report', now).map((h) => h.id),
    ['silent'],
  );
  assert.deepEqual(hostsFor(hosts, 'stale', now), []);
});

// An unknown value in the address is what somebody typed or an old bookmark
// carried. Showing every host is what no filter means; an empty page would look
// like good news about a fleet nobody had checked.
test('an address that names no filter shows every host', () => {
  for (const raw of ['bogus', '', 'Attention', 'ATTENTION', 'none', 'all ']) {
    assert.equal(healthFilterFrom(raw), 'all', JSON.stringify(raw));
  }
  for (const option of HEALTH_FILTERS) assert.equal(healthFilterFrom(option.value), option.value);
});

test('the chips are named as the page promises, in order', () => {
  assert.deepEqual(
    HEALTH_FILTERS.map((option) => option.label),
    ['All', 'Need attention', 'Report stale', 'No report'],
  );
});

test('the sentence under the chips names the filter, and is empty for All', () => {
  assert.equal(filterSentence('all', 3, 3), '');
  assert.equal(
    filterSentence('attention', 2, 5),
    'Showing 2 of 5 hosts: OS settings below the recommendation, or a reboot pending.',
  );
  assert.equal(
    filterSentence('no-report', 0, 1),
    'Showing 0 of 1 host: no OS report has arrived from the agent yet.',
  );
});

function counted(over: Partial<HealthCounts>): HealthCounts {
  return { all: 3, attention: 0, stale: 0, 'no-report': 0, ...over };
}

// Zero beside hosts that have said nothing must not read as a clean bill of
// health, which is what a bare "0" on an amber tile would be.
test('the tile says how many hosts are silent only when none needs attention', () => {
  assert.equal(
    attentionDetail(counted({ stale: 1, 'no-report': 2 })),
    '3 without a current OS report',
  );
  assert.equal(
    attentionDetail(counted({ attention: 1, stale: 1 })),
    'OS settings below the recommendation, or a reboot pending',
  );
  assert.equal(
    attentionDetail(counted({})),
    'OS settings below the recommendation, or a reboot pending',
  );
});

test('an empty Need attention view mentions silent hosts only when there are some', () => {
  const quiet = emptyCopy('attention', counted({}));
  assert.equal(quiet.title, 'No host needs attention');
  assert.doesNotMatch(quiet.description, /no current report/);

  const one = emptyCopy('attention', counted({ 'no-report': 1 }));
  assert.match(one.description, /1 host has no current report, so nothing is known about it yet\./);

  const two = emptyCopy('attention', counted({ stale: 1, 'no-report': 1 }));
  assert.match(
    two.description,
    /2 hosts have no current report, so nothing is known about them yet\./,
  );
});

test('an empty Report stale view says how many have never reported, and an empty No report view says why it matters', () => {
  assert.equal(emptyCopy('stale', counted({})).title, 'No stale reports');
  assert.doesNotMatch(emptyCopy('stale', counted({})).description, /not reported at all/);
  assert.match(
    emptyCopy('stale', counted({ 'no-report': 1 })).description,
    /1 host has not reported at all\./,
  );
  assert.match(
    emptyCopy('stale', counted({ 'no-report': 3 })).description,
    /3 hosts have not reported at all\./,
  );
  const none = emptyCopy('no-report', counted({}));
  assert.equal(none.title, 'Every host has reported');
  assert.match(none.description, /from before OS reports, or one that has only just joined/);
  // The old copy sent people to a service that a native host does not have.
  assert.doesNotMatch(none.description, /health service/);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  attention,
  bySeverity,
  findingsLabel,
  healthSummary,
  type DoctorReport,
  type DoctorResult,
} from '../src/lib/hosts/health.ts';
const now = Date.parse('2026-10-04T10:00:00Z');

/**
 * The controller's count of a report, written out as a stand-in for the real
 * one (hosttune.Report.Summary in Go). The pill reads `summary` and never the
 * results, so a fixture without one would test nothing; the rule is repeated
 * here only so a fixture's numbers are the ones a controller would send. That
 * the stand-in and the controller agree is not proved here but by the
 * host-health Playwright spec, which sends results to the real binary.
 */
function summaryOf(results: DoctorResult[], reboot: boolean): DoctorReport['summary'] {
  const out = { counted: 0, warnings: 0, errors: 0, skipped: 0, suggestions: 0, accepted: 0 };
  for (const r of results) {
    // A pending reboot is counted once, as the reboot.
    if (reboot && r.id === 'kernel.pending' && r.status === 'warn') continue;
    if (!(r.tier === 'safe' && r.optional !== true)) {
      if (r.status === 'warn') out.suggestions++;
      continue;
    }
    out.counted++;
    if (r.status === 'warn') out.warnings++;
    if (r.status === 'error') out.errors++;
    if (r.status === 'skip') out.skipped++;
  }
  return out;
}

function report(status: 'ok' | 'warn' | 'error' | 'skip'): DoctorReport {
  const results: DoctorResult[] = [
    {
      id: 'disk.space',
      title: 'Disk space',
      tier: 'safe',
      status,
      current: '',
      recommended: '',
      rationale: '',
      actionable: false,
    },
  ];
  return {
    checked_at: new Date(now).toISOString(),
    os: 'linux',
    distro: 'ubuntu 24.04',
    container: false,
    reboot_pending: false,
    results,
    summary: summaryOf(results, false),
  };
}
test('health badges distinguish warning, error, unknown and healthy', () => {
  assert.equal(healthSummary(undefined, now).label, 'Health unavailable');
  assert.equal(healthSummary(report('ok'), now).label, 'Health OK');
  assert.equal(healthSummary(report('warn'), now).label, '1 warning');
  assert.equal(healthSummary(report('error'), now).tone, 'danger');
  assert.equal(healthSummary(report('skip'), now).label, 'Checks unavailable');
});
test('freshness and reboot status update when time or the report changes', () => {
  const r = report('ok');
  r.reboot_pending = true;
  assert.equal(healthSummary(r, now).label, 'Reboot pending');
  assert.equal(healthSummary(r, now + 4 * 60_000).label, 'Report stale');
  assert.equal(healthSummary(r, now, false).stale, true);
  r.reboot_pending = false;
  assert.equal(healthSummary(r, now).label, 'Health OK');
});
test('partial container reports never claim full OS visibility', () => {
  const r = report('ok');
  r.container = true;
  assert.match(healthSummary(r, now).hint, /Partial report/);
});

function result(
  id: string,
  status: DoctorResult['status'],
  tier: DoctorResult['tier'] = 'safe',
  optional = false,
): DoctorResult {
  return {
    id,
    title: id,
    tier,
    status,
    current: '',
    recommended: '',
    rationale: '',
    actionable: false,
    optional,
  };
}
function reportOf(results: DoctorResult[], reboot = false): DoctorReport {
  return {
    checked_at: new Date(now).toISOString(),
    os: 'linux',
    distro: 'ubuntu 24.04',
    container: false,
    reboot_pending: reboot,
    results,
    summary: summaryOf(results, reboot),
  };
}

// The monitor reports every tier, but `zoomies doctor` counts the safe one, and
// the docs call the others choices. A host that has made none of them is not
// unwell, and a badge that disagrees with the command the page names is
// believed by nobody.
test("only safe, non-optional checks count towards a host's health", () => {
  const r = reportOf([
    result('inotify.watches', 'ok'),
    result('memory.swappiness', 'warn', 'aggressive'),
    result('service.multipathd', 'warn', 'dedicated'),
    result('service.apport', 'warn', 'dedicated'),
    result('tmp.tmpfs', 'warn', 'aggressive', true),
    result('docker.logs', 'warn', 'safe', true),
  ]);
  const s = healthSummary(r, now);
  assert.equal(s.label, 'Health OK');
  assert.equal(s.tone, 'idle');
  assert.equal(s.warnings, 0);
  assert.equal(s.suggestions, 5);
  assert.match(s.hint, /Also 5 optional suggestions/);
  assert.deepEqual(attention(r), []);
});

test('a safe warning still counts when other tiers are noisy', () => {
  const r = reportOf([
    result('inotify.watches', 'warn'),
    result('service.apport', 'warn', 'dedicated'),
  ]);
  assert.equal(healthSummary(r, now).label, '1 warning');
});

// A reboot used to return before the errors were read, so a full disk showed as
// an amber "Reboot pending" and the danger tone could not be reached at all.
test('an error outranks a pending reboot, and both are said', () => {
  const r = reportOf([result('disk.space', 'error'), result('inotify.watches', 'warn')], true);
  const s = healthSummary(r, now);
  assert.equal(s.label, '1 health error · 1 warning · reboot pending');
  assert.equal(s.tone, 'danger');
  const calm = healthSummary(reportOf([result('inotify.watches', 'warn')], true), now);
  assert.equal(calm.label, '1 warning · reboot pending');
  assert.equal(calm.tone, 'pending');
});

test('a stale report is never worse than stale, whatever it says', () => {
  const r = reportOf([result('disk.space', 'error')]);
  assert.equal(healthSummary(r, now + 4 * 60_000).label, 'Report stale');
  assert.equal(healthSummary(r, now + 4 * 60_000).tone, 'neutral');
});

test('a report with nothing counted to read is unavailable, not OK', () => {
  assert.equal(healthSummary(reportOf([]), now).label, 'Checks unavailable');
  const dedicatedOnly = reportOf([result('service.apport', 'warn', 'dedicated')]);
  assert.equal(healthSummary(dedicatedOnly, now).label, 'Checks unavailable');
});

test("findings come first, worst first, in the engine's order within a rank", () => {
  const rows = [
    result('a', 'ok'),
    result('b', 'warn'),
    result('c', 'skip'),
    result('d', 'error'),
    result('e', 'warn'),
  ];
  assert.deepEqual(
    bySeverity(rows).map((r) => r.id),
    ['d', 'b', 'e', 'a', 'c'],
  );
  assert.deepEqual(
    attention(reportOf(rows)).map((r) => r.id),
    ['d', 'b', 'e'],
  );
});

// The problems, the metrics, the feed and `zoomies hosts list` all read the
// controller's count. A pill that tallied the rows itself would be the one
// surface that could disagree with them, and the day the two rules drift it is
// the badge that gets believed.
test("the pill says the controller's count, not its own tally of the rows", () => {
  const r = reportOf([
    result('inotify.watches', 'warn'),
    result('docker.logs', 'warn'),
    result('disk.space', 'warn'),
  ]);
  r.summary = { counted: 3, warnings: 1, errors: 0, skipped: 0, suggestions: 0, accepted: 0 };
  const s = healthSummary(r, now);
  assert.equal(s.label, '1 warning');
  assert.equal(s.warnings, 1);
  assert.match(s.hint, /1 warning, 0 errors, 0 skipped checks/);
});

// A payload with no summary is a controller older than this page, and the
// badge must not throw on every host card because of it. It also must not make
// up an answer: counting the rows would be a second opinion.
test('a report without the controller’s count reads as unavailable and never throws', () => {
  const r = reportOf([result('disk.space', 'error')]);
  delete (r as Partial<DoctorReport>).summary;
  const s = healthSummary(r, now);
  assert.equal(s.label, 'Health unavailable');
  assert.equal(s.tone, 'neutral');
  assert.match(s.hint, /without the controller’s count/);
});

// The agent sets reboot_pending from the kernel.pending warning, so a report
// says the one fact twice. The controller counts it once, as the reboot: a
// host whose only finding is a restart is waiting for one, not failing a check,
// and the Needs attention list must not show a row the count left out.
test('a pending reboot is counted once, as the reboot', () => {
  const only = reportOf([result('inotify.watches', 'ok'), result('kernel.pending', 'warn')], true);
  const s = healthSummary(only, now);
  assert.equal(s.label, 'Reboot pending');
  assert.equal(s.tone, 'pending');
  assert.equal(s.warnings, 0);
  assert.deepEqual(attention(only), []);

  // Beside a real finding, the reboot is said once and the finding once.
  const both = reportOf(
    [result('inotify.watches', 'warn'), result('kernel.pending', 'warn')],
    true,
  );
  assert.equal(healthSummary(both, now).label, '1 warning · reboot pending');
  assert.deepEqual(
    attention(both).map((r) => r.id),
    ['inotify.watches'],
  );
});

test('the list of what needs attention is as long as the count says', () => {
  const cases: DoctorReport[] = [
    reportOf([result('a', 'warn'), result('b', 'error'), result('c', 'ok')]),
    reportOf([result('a', 'warn'), result('kernel.pending', 'warn'), result('b', 'error')], true),
    reportOf([result('kernel.pending', 'warn'), result('t', 'warn', 'aggressive')], true),
    reportOf([result('a', 'warn', 'safe', true), result('s', 'skip')]),
  ];
  for (const r of cases) {
    const s = r.summary;
    assert.equal(attention(r).length, s.warnings + s.errors);
  }
});

// Only a warning is the reboot. A kernel.pending that could not run, or a
// report that contradicts itself, is judged by its rows rather than hidden.
test('only the kernel.pending warning of a report that says reboot is left out', () => {
  const noFlag = reportOf([result('kernel.pending', 'warn')], false);
  assert.deepEqual(
    attention(noFlag).map((r) => r.id),
    ['kernel.pending'],
  );
  const errored = reportOf([result('kernel.pending', 'error')], true);
  assert.deepEqual(
    attention(errored).map((r) => r.id),
    ['kernel.pending'],
  );
});

// A container's report is the container's view: most checks skipped, and its
// image's distribution warns for ever. The controller raises nothing for it,
// so a pill that painted it red or amber would be a verdict nobody else gives.
test('a container’s partial report is Partial report, whatever it found', () => {
  const r = reportOf(
    [result('environment', 'warn'), result('disk.space', 'error'), result('kernel.pending', 'ok')],
    true,
  );
  r.container = true;
  const s = healthSummary(r, now);
  assert.equal(s.label, 'Partial report');
  assert.equal(s.tone, 'neutral');
  assert.match(s.hint, /Partial report from the container/);
  assert.doesNotMatch(s.hint, /warning|error/);
  // Nor does a stale one carry its reboot flag: that is no more a verdict than
  // its rows are, and a reboot label would say it was.
  assert.equal(healthSummary(r, now + 4 * 60_000).label, 'Report stale');
});

test('findings are said errors first, in the words the pill and the feed share', () => {
  assert.equal(findingsLabel({ errors: 0, warnings: 0 }), '');
  assert.equal(findingsLabel({ errors: 0, warnings: 1 }), '1 warning');
  assert.equal(findingsLabel({ errors: 0, warnings: 2 }), '2 warnings');
  assert.equal(findingsLabel({ errors: 1, warnings: 0 }), '1 health error');
  assert.equal(findingsLabel({ errors: 1, warnings: 2 }), '1 health error · 2 warnings');
  assert.equal(findingsLabel({ errors: 3, warnings: 1 }), '3 health errors · 1 warning');
});

// The pill calls a container's report no verdict and the controller raises
// nothing for it, so a list of what needs attention beside them would say the
// opposite, about a warning (the image's own distribution) nobody can clear.
test('a container’s partial report has nothing that needs attention, whatever its rows say', () => {
  const r = reportOf([result('environment', 'warn'), result('disk.space', 'warn')]);
  assert.equal(attention(r).length, 2);
  r.container = true;
  assert.deepEqual(attention(r), []);
});

// An operator reads "stale" as "the host is fine, the page is slow" unless the
// label says the agent is gone. Which of the two it is decides what to do next,
// so the label and the hint both carry it.
test('an old report from a connected host is Report stale, and from a gone host Last known report', () => {
  const r = reportOf([result('disk.space', 'ok')]);
  const old = now + 4 * 60_000;
  const connected = healthSummary(r, old, true);
  assert.equal(connected.label, 'Report stale');
  assert.match(connected.hint, /connected, but its last OS report is more than three minutes old/);
  assert.match(connected.hint, /sudo systemctl restart zoomies-agent/);
  const gone = healthSummary(r, old, false);
  assert.equal(gone.label, 'Last known report');
  assert.match(gone.hint, /not connected/);
  assert.doesNotMatch(gone.hint, /systemctl/);
  // Both stay stale, so the Report stale filter chip holds them either way.
  assert.equal(connected.stale && gone.stale, true);
  assert.equal(connected.tone, 'neutral');
  assert.equal(gone.tone, 'neutral');
});

// The flag may have cleared since the report was written, so a stale label that
// said "reboot pending" would assert something nobody has checked.
test('a stale report never says reboot pending in its label, only in its hint', () => {
  const r = reportOf([result('disk.space', 'ok')], true);
  for (const reachable of [true, false]) {
    const s = healthSummary(r, now + 4 * 60_000, reachable);
    assert.doesNotMatch(s.label, /reboot/i);
    assert.match(s.hint, /That report said a reboot was pending\./);
  }
  assert.doesNotMatch(healthSummary(r, now).hint, /said a reboot was pending/);
});

function skipping(skipped: number, counted: number, extra: DoctorResult[] = []): DoctorReport {
  const results = [
    ...Array.from({ length: counted - skipped }, (_, i) => result(`ok.${i}`, 'ok')),
    ...Array.from({ length: skipped }, (_, i) => result(`skip.${i}`, 'skip')),
    ...extra,
  ];
  return reportOf(results);
}

// A healthy Linux host skips 1-5 of 14 checks; half or more cannot vouch for the
// host, and a green pill would be a claim nobody checked.
test('a native report that skipped half its checks is Partial report, not Health OK', () => {
  const six = healthSummary(skipping(6, 14), now);
  assert.equal(six.label, 'Health OK');
  const seven = healthSummary(skipping(7, 14), now);
  assert.equal(seven.label, 'Partial report');
  assert.equal(seven.tone, 'neutral');
  assert.equal(seven.stale, false);
  assert.match(seven.hint, /7 of 14 checks could not run/);
});

test('a report that skipped every check is still Checks unavailable, not Partial report', () => {
  assert.equal(healthSummary(skipping(14, 14), now).label, 'Checks unavailable');
  assert.equal(healthSummary(reportOf([]), now).label, 'Checks unavailable');
});

// The skip rule is about green only: a host with a finding or a reboot says so
// whatever else it skipped, and the hint says how much of the report is missing.
test('findings and a pending reboot win over the mostly skipped rule', () => {
  const warned = healthSummary(skipping(8, 14, [result('disk.space', 'warn')]), now);
  assert.equal(warned.label, '1 warning');
  assert.equal(warned.tone, 'pending');
  assert.match(warned.hint, /8 of 15 checks could not run/);
  const r = skipping(8, 14);
  r.reboot_pending = true;
  assert.equal(healthSummary(r, now).label, 'Reboot pending');
});

// A finding with a few skips is a finding; saying "could not run" there would
// make an ordinary Linux host look as though its report were missing.
test('a finding with few skipped checks does not say checks could not run', () => {
  const warned = healthSummary(skipping(1, 14, [result('disk.space', 'warn')]), now);
  assert.equal(warned.label, '1 warning');
  assert.doesNotMatch(warned.hint, /could not run/);
});

// An operator on a Mac or a BSD box needs to be told why there is no verdict,
// not shown the generic skipped-check count.
test('a non-Linux report that skipped everything says Zoomies checks Linux hosts only', () => {
  const r = reportOf([{ ...result('environment', 'skip'), current: 'darwin' }]);
  r.os = 'darwin';
  const s = healthSummary(r, now);
  assert.equal(s.label, 'Checks unavailable');
  assert.match(s.hint, /Linux hosts only; this host reports darwin/);
});

// A report with no usable time cannot be called fresh, and the hint must say
// the date is the problem rather than that the report is old.
test('a report whose time cannot be read is stale and says it could not be dated', () => {
  const r = reportOf([result('ok.0', 'ok')]);
  r.checked_at = 'garbage';
  const s = healthSummary(r, now);
  assert.equal(s.stale, true);
  assert.equal(s.label, 'Report stale');
  assert.match(s.hint, /could not be dated/);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import type { DoctorReport, DoctorResult } from '../src/lib/hosts/health.ts';
import {
  DOCTOR_COMMAND,
  nextStep,
  rebootAdvice,
  rebootPending,
  type NextStep,
  type NextStepInput,
} from '../src/lib/hosts/next-step.ts';

const now = Date.parse('2026-10-04T10:00:00Z');

function result(
  id: string,
  status: DoctorResult['status'],
  tier: DoctorResult['tier'] = 'safe',
): DoctorResult {
  return {
    id,
    title: id,
    tier,
    status,
    current: '',
    recommended: '',
    rationale: '',
    actionable: false,
  };
}

/** A full report: only what the page reads from it is filled in, and `summary` is zeros because nextStep never reads it. */
function report(results: DoctorResult[], { reboot = false, container = false } = {}): DoctorReport {
  return {
    checked_at: new Date(now).toISOString(),
    os: 'linux',
    distro: 'ubuntu 24.04',
    container,
    reboot_pending: reboot,
    results,
    summary: { counted: 0, warnings: 0, errors: 0, skipped: 0, suggestions: 0, accepted: 0 },
  };
}

const clean = report([result('disk.space', 'ok')]);
const warned = report([result('disk.space', 'warn')]);
const rebootOnly = report([result('disk.space', 'ok')], { reboot: true });

function input(
  over: Partial<NextStepInput> & { host?: Partial<NextStepInput['host']> } = {},
): NextStepInput {
  return {
    report: rebootOnly,
    cordoned: false,
    ...over,
    host: {
      id: 'host_1',
      name: 'builder-1',
      healthy: true,
      active_runners: 0,
      ...over.host,
    },
  };
}

function step(over: Parameters<typeof input>[0] = {}): NextStep {
  const out = nextStep(input(over));
  assert.ok(out, 'a next step was expected');
  return out;
}

test('there is no next step for a clean host that takes work', () => {
  // Nothing to do and nothing held back: a panel here would be noise on every
  // healthy host's page.
  assert.equal(nextStep(input({ report: undefined })), null);
  assert.equal(nextStep(input({ report: clean })), null);
});

test('a container report gives no next step, even with a reboot flag', () => {
  // The pill ignores a container's reboot flag and the controller raises
  // nothing for it, so a panel that said "reboot" would contradict both.
  const partial = report([result('environment', 'warn')], { reboot: true, container: true });
  assert.equal(rebootPending(partial), false);
  assert.equal(nextStep(input({ report: partial })), null);
});

test('a counted finding or a pending reboot is a next step', () => {
  assert.ok(nextStep(input({ report: warned })));
  assert.ok(nextStep(input({ report: rebootOnly })));
});

test('a kernel.pending warning beside the reboot flag counts once, as the reboot', () => {
  // The agent says a pending reboot twice; the controller counts it once.
  const twice = report([result('kernel.pending', 'warn')], { reboot: true });
  assert.ok(nextStep(input({ report: twice })));
  // And without the flag it is an ordinary counted warning.
  assert.ok(nextStep(input({ report: report([result('kernel.pending', 'warn')]) })));
  assert.equal(nextStep(input({ report: report([result('kernel.pending', 'ok')]) })), null);
});

test('an unreachable host or an unknown count is never called safe or idle', () => {
  // `?? 0` would call a missing count an empty host, and a host nobody can hear
  // has only the last count anyone recorded.
  for (const cordoned of [false, true]) {
    const missing = step({ cordoned, host: { active_runners: undefined } });
    assert.equal(missing.verdict, 'unknown');
    assert.equal(missing.headline, 'Check before rebooting');
    assert.match(missing.detail, /has not said how many runners/);
    assert.equal(missing.runners, 'Not reported');

    for (const healthy of [false, undefined]) {
      const quiet = step({ cordoned, host: { healthy, active_runners: 0 } });
      assert.equal(quiet.verdict, 'unknown');
      assert.match(quiet.detail, /is not connected/);
    }
  }
});

test('runners still on the host are said to be unknown jobs, never counted as jobs', () => {
  const busy = step({ host: { active_runners: 2 } });
  assert.equal(busy.verdict, 'busy');
  assert.equal(busy.headline, 'Runners are still on builder-1');
  assert.equal(busy.runners, '2 runners');
  assert.match(busy.detail, /never finishes by itself/);
  assert.match(busy.detail, /cordon it to stop them/);
  // The count is runners. Nothing here may say how many jobs there are.
  assert.doesNotMatch(busy.runners, /job/);
  assert.match(step({ host: { active_runners: 1 } }).runners, /^1 runner$/);

  const held = step({ cordoned: true, host: { active_runners: 2 } });
  assert.equal(held.verdict, 'busy');
  assert.match(held.detail, /It is cordoned, so no new runner is placed here/);
  assert.match(held.detail, /Reboot builder-1 when none is, then uncordon it/);

  // Findings only: there is nothing to reboot, so the sentence does not say to.
  assert.doesNotMatch(step({ report: warned, host: { active_runners: 2 } }).detail, /Reboot/);
});

test('an idle and cordoned host is safe to reboot, and says what to do afterwards', () => {
  const safe = step({ cordoned: true });
  assert.equal(safe.verdict, 'safe');
  assert.equal(safe.headline, 'Idle and cordoned: safe to reboot now');
  assert.equal(safe.runners, 'None');
  assert.equal(safe.placement, 'Cordoned: no new runner is placed here');
  assert.match(safe.detail, /Reboot builder-1 yourself, then uncordon it/);

  // Findings only: "safe to reboot" is true but nothing asks for a reboot.
  const findingsOnly = step({ cordoned: true, report: warned });
  assert.equal(findingsOnly.verdict, 'safe');
  assert.doesNotMatch(findingsOnly.detail, /Reboot builder-1 yourself/);
  assert.match(findingsOnly.detail, /uncordon it afterwards/);
});

test('an idle host that still takes work is not safe until the cordon is confirmed', () => {
  // This is the in-flight case: the page passes the state from before the
  // click, so a request nobody has heard back from never reads as safe.
  const idle = step({ cordoned: false });
  assert.equal(idle.verdict, 'idle');
  assert.equal(idle.headline, 'Nothing is running on builder-1 right now');
  assert.equal(idle.placement, 'Taking new work');
  assert.match(idle.detail, /Cordon it first so that a job cannot land on it/);
  assert.doesNotMatch(idle.headline, /safe/);

  // Findings only: the reboot sentence is not offered.
  assert.doesNotMatch(step({ report: warned }).detail, /rebooted now/);
});

test('a cordoned host with nothing waiting on it is told to uncordon, and is given no command', () => {
  // The host that was cordoned for a reboot, came back clean and is still
  // cordoned takes no work and nothing on its page would say so. Whatever the
  // report is, the verdict gives no reboot advice, so it holds even for a host
  // that has gone quiet or sent a container's partial report.
  const container = report([result('environment', 'warn')], { reboot: true, container: true });
  for (const r of [clean, undefined, container]) {
    const cordoned = step({ cordoned: true, report: r });
    assert.equal(cordoned.verdict, 'cordoned');
    assert.equal(cordoned.headline, 'builder-1 is cordoned and nothing is waiting on it');
    assert.equal(cordoned.detail, 'Uncordon it so that it takes work again.');
    assert.equal(cordoned.where, null, 'there is nothing to run, so no command is offered');
    assert.equal(cordoned.button.label, 'Uncordon this host');
    assert.match(cordoned.button.help, /lets the scheduler place runners on builder-1 again/);
    assert.equal(cordoned.runners, 'None');
    assert.equal(cordoned.placement, 'Cordoned: no new runner is placed here');
  }
  for (const host of [{ healthy: false }, { healthy: undefined }, { active_runners: undefined }]) {
    assert.equal(step({ cordoned: true, report: clean, host }).verdict, 'cordoned');
  }
  assert.equal(
    step({ cordoned: true, report: clean, host: { active_runners: 3 } }).runners,
    '3 runners',
  );

  // The same clean host, taking work, has no panel at all.
  assert.equal(nextStep(input({ report: clean, cordoned: false })), null);
  // And the moment something is waiting, the verdicts above take over.
  assert.equal(step({ cordoned: true, report: warned }).verdict, 'safe');
  assert.equal(step({ cordoned: true, report: rebootOnly }).verdict, 'safe');
  assert.ok(step({ cordoned: true, report: rebootOnly }).where);
});

test('the command is named for the host and address, and never contains them', () => {
  const caption = step({ host: { address: '10.0.0.7' } }).where;
  assert.equal(caption, 'Run this on builder-1 (10.0.0.7), in a shell on that machine:');
  assert.equal(
    step().where,
    'Run this on builder-1, in a shell on that machine:',
    'no address, no brackets',
  );
  assert.equal(
    step({ host: { embedded: true } }).where,
    "Run this on the controller's own machine (builder-1), in a shell there:",
  );
  assert.match(step({ host: { embedded: true } }).embeddedNote ?? '', /takes Zoomies offline/);
  assert.equal(step().embeddedNote, null);

  assert.equal(DOCTOR_COMMAND, 'sudo zoomies doctor --interactive');
  // A host writes its own name; a name with a newline must not reach the clipboard.
  assert.ok(!DOCTOR_COMMAND.includes('builder'));
});

test('the button says what a press will do', () => {
  const taking = step({ cordoned: false });
  assert.equal(taking.cordoned, false);
  assert.equal(taking.button.label, 'Cordon this host');
  assert.match(taking.button.help, /does not stop or reboot anything/);
  const held = step({ cordoned: true });
  assert.equal(held.cordoned, true);
  assert.equal(held.button.label, 'Uncordon this host');
});

test('a host with no name is called by its id, and then by nothing at all', () => {
  assert.match(step({ host: { name: '' } }).headline, /host_1/);
  assert.match(step({ host: { name: '', id: '' } }).headline, /this host/);
});

test('no sentence on the host page says drain', () => {
  // Drain cordons and then stops a runner that is still busy after five
  // minutes, which is the wrong advice for waiting for jobs to finish. The
  // controller's own fix text for a pending reboot (host_health_problems.go)
  // makes the same choice, and the two should read alike.
  const everything: NextStep[] = [];
  for (const cordoned of [false, true]) {
    for (const r of [clean, warned, rebootOnly, undefined]) {
      for (const host of [
        { active_runners: 0 },
        { active_runners: 2 },
        { active_runners: undefined },
        { healthy: false },
        { embedded: true, address: '10.0.0.7' },
      ]) {
        const out = nextStep(input({ cordoned, report: r, host }));
        if (out) everything.push(out);
      }
    }
  }
  assert.ok(everything.length > 10);
  for (const out of everything) {
    const words = [
      out.headline,
      out.detail,
      out.runners,
      out.placement,
      out.button.label,
      out.button.help,
      out.where ?? '',
      out.embeddedNote ?? '',
    ].join('\n');
    assert.doesNotMatch(words, /drain/i);
  }
  assert.doesNotMatch(rebootAdvice(), /drain/i);
});

test('a viewer is told to cordon, and which role it takes', () => {
  assert.match(rebootAdvice(), /operator role/);
  assert.match(rebootAdvice(), /Zoomies never reboots a host itself/);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  FIRST_REPORT_GRACE_MS,
  READ_ONLY_DOCTOR_COMMAND,
  noReport,
  noReportSubtitle,
  type NoReport,
} from '../src/lib/hosts/no-report.ts';

const now = Date.parse('2026-10-04T10:00:00Z');
const longAgo = new Date(now - 3 * 3_600_000).toISOString();
const UPGRADE = 'sudo zoomies upgrade --mode agent --version v1.2.0';

function host(over: Partial<Parameters<typeof noReport>[0]['host']> = {}) {
  return {
    healthy: true,
    version: 'v1.2.0',
    created_at: longAgo,
    last_heartbeat: new Date(now - 5_000).toISOString(),
    ...over,
  };
}
const run = (h = host(), canOperate = true): NoReport => noReport({ host: h, now, canOperate });

test('a host that is not connected is told so before anything about its release', () => {
  // Version skew and a fresh row are both true of a host that has dropped off,
  // and neither is the reason nothing can arrive.
  const r = run(host({ healthy: false, version_skew: 'behind', upgrade_command: UPGRADE }));
  assert.equal(r.kind, 'disconnected');
  assert.equal(r.command, null);
  assert.equal(r.tail, 'heartbeat');
  assert.equal(run(host({ healthy: false, last_heartbeat: undefined })).tail, null);
});

test('a behind or different agent may be too old, and an operator gets the controller-made command byte for byte', () => {
  for (const skew of ['behind', 'differs'] as const) {
    const r = run(
      host({ version_skew: skew, upgrade_command: UPGRADE, upgrade_note: 'Updates it.' }),
    );
    assert.equal(r.kind, 'release');
    assert.match(r.description, /may be too old to send OS reports/);
    assert.equal(r.command, UPGRADE);
    // Zoomies can update a host, on a press or by itself in auto, so the line
    // under the command says when it does and claims neither never nor only.
    assert.match(r.after ?? '', /when an administrator presses Update on the host’s card/);
    assert.match(r.after ?? '', /starts a rollout from the Hosts page/);
    assert.match(r.after ?? '', /while updates\.mode is auto/);
    assert.doesNotMatch(r.after ?? '', /never runs it for you|\bonly when\b/);
    assert.equal(r.copyLabel, 'Copy the upgrade command');
    assert.equal(r.note, 'Updates it.');
  }
  // Ahead is the card's business ("upgrade the controller first"), not a cause here.
  assert.notEqual(run(host({ version_skew: 'ahead' })).kind, 'release');
});
test('a machine Zoomies rents and cannot be asked is told about its provider’s template', () => {
  const r = run(host({ version_skew: 'behind', machine_id: 'mach_1' }), false);
  assert.equal(r.kind, 'release');
  assert.equal(r.command, null);
  assert.match(r.detail, /machine Zoomies rents/);
  assert.match(r.detail, /template/);
  assert.doesNotMatch(r.detail, /update helper|upgrade command/);
  // An operator is given the controller's note, which names the template too.
  const withNote = run(
    host({
      version_skew: 'behind',
      machine_id: 'mach_1',
      upgrade_note: 'Prepare that template again.',
    }),
  );
  assert.equal(withNote.kind, 'release');
  assert.equal(withNote.detail, 'Prepare that template again.');
});

test('the upgrade command is never built from a host field and never reaches a viewer', () => {
  const evil = host({
    version: 'v1; rm -rf /',
    version_skew: 'behind',
    upgrade_command: UPGRADE,
  });
  assert.equal(run(evil).command, UPGRADE);
  const viewer = run(evil, false);
  assert.equal(viewer.kind, 'release');
  assert.equal(viewer.command, null);
  // Both people who can update it are named, because a viewer can ask either,
  // and so is auto, which updates it by itself where the helper is.
  assert.match(viewer.detail, /an administrator, who can press Update/);
  // The button is there only where the helper is, so the sentence says so.
  assert.match(viewer.detail, /press Update on its host card where the update helper is installed/);
  assert.match(viewer.detail, /an operator, who can run its upgrade command/);
  assert.match(viewer.detail, /while updates\.mode is auto/);
  assert.doesNotMatch(viewer.detail, /\bneeds an administrator\b/);
  assert.doesNotMatch(viewer.detail, /never updates a host itself/);
  // No command to offer: say so rather than invent one.
  const none = run(host({ version_skew: 'differs' }));
  assert.equal(none.command, null);
  assert.match(none.detail, /no command to offer/);
  // The embedded agent is the controller; updating it cannot help.
  assert.equal(
    run(host({ version_skew: 'behind', embedded: true, upgrade_command: UPGRADE })).command,
    null,
  );
});

test('skew outranks the grace period, because an old agent never reports however new its row is', () => {
  const r = run(
    host({ version_skew: 'differs', created_at: new Date(now - 60_000).toISOString() }),
  );
  assert.equal(r.kind, 'release');
  assert.equal(r.tail, 'joined-late');
});

test('a host that joined within the grace period is waiting, not faulty', () => {
  const young = new Date(now - FIRST_REPORT_GRACE_MS + 1_000).toISOString();
  const r = run(host({ created_at: young }));
  assert.equal(r.kind, 'joining');
  assert.equal(r.tail, 'joined');
  assert.equal(r.command, null);
  // The page cannot see the agent's heartbeat interval, so a figure would be a guess.
  assert.doesNotMatch(r.detail, /\d|minute/i);
  const old = new Date(now - FIRST_REPORT_GRACE_MS).toISOString();
  assert.notEqual(run(host({ created_at: old })).kind, 'joining');
  // An unreadable date must not read as "just joined": that would hide a fault.
  assert.notEqual(run(host({ created_at: 'not a date' })).kind, 'joining');
  assert.notEqual(run(host({ created_at: undefined })).kind, 'joining');
});

test('the embedded agent is not told to update itself', () => {
  const r = run(host({ embedded: true }));
  assert.equal(r.kind, 'embedded');
  assert.equal(r.command, null);
  assert.match(r.detail, /updating it cannot help/);
  assert.doesNotMatch(r.detail, /\d|minute/i);
});

test('an agent that gives no release gets no command, because Zoomies would not know which to offer', () => {
  const op = run(host({ version: '' }));
  assert.equal(op.kind, 'no-release');
  assert.equal(op.command, null);
  assert.doesNotMatch(op.detail, /Ask an operator/);
  assert.match(run(host({ version: '' }), false).detail, /Ask an operator to update it/);
});

test('when nothing explains it, both roles get the read-only doctor command and nothing else', () => {
  for (const canOperate of [true, false]) {
    const r = run(host(), canOperate);
    assert.equal(r.kind, 'unknown');
    assert.equal(r.command, READ_ONLY_DOCTOR_COMMAND);
    assert.equal(r.command, 'sudo zoomies doctor');
    assert.doesNotMatch(r.command ?? '', /interactive|tune/);
    assert.equal(r.copyLabel, 'Copy command');
  }
  // Even a host whose fields look hostile never changes the constant.
  assert.equal(run(host({ version: '$(reboot)' })).command, READ_ONLY_DOCTOR_COMMAND);
});

test('no cause offers tuning, draining or an American spelling, or implies the controller runs anything', () => {
  const cases = [
    host({ healthy: false }),
    host({ version_skew: 'behind', upgrade_command: UPGRADE, upgrade_note: 'n' }),
    host({ version_skew: 'differs' }),
    host({ created_at: new Date(now - 1000).toISOString() }),
    host({ embedded: true }),
    host({ version: '' }),
    host(),
  ];
  for (const h of cases) {
    for (const canOperate of [true, false]) {
      const r = run(h, canOperate);
      const text = [r.description, r.detail, r.after, r.commandCaption].join(' ');
      assert.doesNotMatch(text, /No tuning|tune|apply|drain|behavior|utiliz|authoriz/i);
      assert.doesNotMatch(text, /Zoomies (will )?(run|runs) it/);
    }
  }
  assert.equal(noReportSubtitle(), 'No OS report has arrived from this host yet.');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
