  // nothing should not look like a decision the operator made.
  assert.deepEqual(priorityBody(unpinned, 'auto', null), {});
  assert.deepEqual(priorityBody(pinned, 'pinned', 90), {});
  assert.deepEqual(priorityBody(unpinned, 'pinned', 90), {
