import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  NO_FIGURES,
  figuresOf,
  isUnset,
  profileBody,
  profileErrors,
  sameFigures,
} from '../src/lib/hosts/profile.ts';

const machine = { cpus: 8, memoryMb: 32768, allocatableCpus: 7, allocatableMemoryMb: 28672 };

// The policy is part of the profile the API replaces whole, so it has to go out
// with the figures beside it and come back the same.
test("a host's in-memory policy round-trips with its runner profile", () => {
  const profile = {
    standard: { cpus: 2, memory_mb: 8192 },
    tmpfs: { disabled: true },
  };
  const figures = figuresOf(profile);
  assert.equal(figures.tmpfsOff, true);
  assert.equal(figures.standardCpus, 2);
  assert.deepEqual(profileBody(figures), profile);
  assert.deepEqual(profileBody(figuresOf({ tmpfs: { max_mb: 2048 } })), {
    tmpfs: { max_mb: 2048 },
  });
});

// A host that says nothing sends nothing, so it keeps following each pool.
test('a host that says nothing about in-memory folders sends nothing about them', () => {
  assert.deepEqual(profileBody(NO_FIGURES), {});
  assert.equal(isUnset(NO_FIGURES), true);
  assert.equal(isUnset({ ...NO_FIGURES, tmpfsOff: true }), false);
  assert.equal(isUnset({ ...NO_FIGURES, tmpfsMaxMb: 512 }), false);
  assert.equal(sameFigures(NO_FIGURES, { ...NO_FIGURES, tmpfsMaxMb: 512 }), false);
});

// Off is stronger than a ceiling: the API refuses both together, so the form
// never sends the ceiling of a host that keeps the folders off.
test('a ceiling is not sent for a host that keeps the folders off', () => {
  const body = profileBody({ ...NO_FIGURES, tmpfsOff: true, tmpfsMaxMb: 2048 });
  assert.deepEqual(body, { tmpfs: { disabled: true } });
});

test('a ceiling below the floor is refused where it is typed, and only while it is in force', () => {
  const small = profileErrors({ ...NO_FIGURES, tmpfsMaxMb: 32 }, machine);
  assert.match(small['runner_profile.tmpfs.max_mb'] ?? '', /below 64 MB/);
  assert.deepEqual(profileErrors({ ...NO_FIGURES, tmpfsMaxMb: 64 }, machine), {});
  // Moot on a host that keeps the folders off.
  assert.deepEqual(profileErrors({ ...NO_FIGURES, tmpfsOff: true, tmpfsMaxMb: 32 }, machine), {});
});

// A host's standard folder sizes are the folder-sized counterpart of its standard
// runner size: part of the profile the API replaces whole, so they round-trip
// with the rest, are not sent for a host that falls back to disk, and are held to
// the same floor as a ceiling.
test("a host's standard folder sizes round-trip and are not sent where the folders are off", () => {
  const profile = { tmpfs: { work_mb: 16384, tmp_mb: 2048, daemon_mb: 32768, max_mb: 20000 } };
  const figures = figuresOf(profile);
  assert.equal(figures.tmpfsWorkMb, 16384);
  assert.equal(figures.tmpfsDaemonMb, 32768);
  assert.deepEqual(profileBody(figures), profile);
  assert.deepEqual(profileBody({ ...figures, tmpfsOff: true }), { tmpfs: { disabled: true } });
  assert.equal(isUnset({ ...NO_FIGURES, tmpfsWorkMb: 4096 }), false);
  assert.equal(sameFigures(NO_FIGURES, { ...NO_FIGURES, tmpfsTmpMb: 512 }), false);
});

test('a standard folder size below the floor is refused where it is typed', () => {
  const errors = profileErrors({ ...NO_FIGURES, tmpfsWorkMb: 10, tmpfsDaemonMb: 20 }, machine);
  assert.match(errors['runner_profile.tmpfs.work_mb'] ?? '', /below 64 MB/);
  assert.match(errors['runner_profile.tmpfs.daemon_mb'] ?? '', /below 64 MB/);
  assert.equal(errors['runner_profile.tmpfs.tmp_mb'], undefined);
  assert.deepEqual(profileErrors({ ...NO_FIGURES, tmpfsTmpMb: 64 }, machine), {});
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { allClear, announcement, logLine, reportChanges } from '../src/lib/hosts/report-changes.ts';
import type { Host } from '../src/lib/api/types.ts';

type Report = NonNullable<Host['doctor']>;
type Result = Report['results'][number];
const t0 = Date.parse('2026-10-04T10:00:00Z');
const ctx = { prevVersion: 'v1', nextVersion: 'v1' };

function row(id: string, status: Result['status'], extra: Partial<Result> = {}): Result {
  return {
    id,
    title: `Title of ${id}`,
    tier: 'safe',
    status,
    current: '',
    recommended: '',
    rationale: '',
    actionable: false,
    ...extra,
  } as Result;
}
function report(results: Result[], over: Record<string, unknown> = {}, at = t0): Report {
  const counted = results.filter((r) => r.tier === 'safe' && r.optional !== true);
  return {
    checked_at: new Date(at).toISOString(),
    os: 'linux',
    distro: 'ubuntu 24.04',
    container: false,
    reboot_pending: false,
    results,
    summary: {
      counted: counted.length,
      warnings: counted.filter((r) => r.status === 'warn').length,
      errors: counted.filter((r) => r.status === 'error').length,
      skipped: counted.filter((r) => r.status === 'skip').length,
      suggestions: 0,
    },
    ...over,
  } as Report;
}
const later = (s: number) => t0 + s * 1000;

test('a check that goes from warning to OK is reported as resolved', () => {
  const prev = report([row('a', 'warn'), row('b', 'ok')]);
  const next = report([row('a', 'ok'), row('b', 'ok')], {}, later(60));
  assert.deepEqual(
    reportChanges(prev, next, ctx).map((c) => [c.id, c.kind]),
    [['a', 'resolved']],
  );
});

test('a check that goes from OK to warning is new, and warning to error is escalated', () => {
  const prev = report([row('a', 'ok'), row('b', 'warn'), row('c', 'ok')]);
  const next = report([row('a', 'warn'), row('b', 'error'), row('c', 'ok')], {}, later(60));
  const kinds = Object.fromEntries(reportChanges(prev, next, ctx).map((c) => [c.id, c.kind]));
  assert.deepEqual(kinds, { b: 'escalated', a: 'new' });
});

test('an error that eases to a warning is not announced', () => {
  // Better, but not fixed: telling someone it cleared would be wrong.
  const prev = report([row('a', 'error')]);
  const next = report([row('a', 'warn')], {}, later(60));
  assert.deepEqual(reportChanges(prev, next, ctx), []);
});

test('a skipped check is not an OK one', () => {
  // A stopped Docker daemon skips a group at once; "now OK" would be false.
  const prev = report([row('a', 'warn')]);
  const next = report([row('a', 'skip')], {}, later(60));
  assert.deepEqual(reportChanges(prev, next, ctx), []);
});

test('only counted checks are announced', () => {
  // The pill ignores optional and non-safe tiers, so the page must too.
  const prev = report([
    row('a', 'warn', { optional: true }),
    row('b', 'warn', { tier: 'aggressive' }),
  ]);
  const next = report(
    [row('a', 'ok', { optional: true }), row('b', 'ok', { tier: 'aggressive' })],
    {},
    later(60),
  );
  assert.deepEqual(reportChanges(prev, next, ctx), []);
});

test('the first report seen announces nothing', () => {
  assert.deepEqual(reportChanges(undefined, report([row('a', 'warn')]), ctx), []);
  assert.deepEqual(reportChanges(report([row('a', 'warn')]), undefined, ctx), []);
});

test('a repeated, older or undated report announces nothing', () => {
  // Frames are replayed and cordon frames carry the same report; only a later check time is news.
  const prev = report([row('a', 'warn')]);
  const ok = [row('a', 'ok')];
  assert.deepEqual(reportChanges(prev, report(ok), ctx), []);
  assert.deepEqual(reportChanges(prev, report(ok, {}, t0 - 1000), ctx), []);
  assert.deepEqual(reportChanges(prev, report(ok, { checked_at: 'soon' }), ctx), []);
});

test('a different source is not compared', () => {
  const prev = report([row('a', 'warn')]);
  const next = report([row('a', 'ok')], {}, later(60));
  assert.deepEqual(reportChanges(prev, next, { prevVersion: 'v1', nextVersion: 'v2' }), []);
  assert.deepEqual(reportChanges(prev, { ...next, distro: 'debian 12' }, ctx), []);
});

test('partial and report-only reports are never compared', () => {
  const prev = report([row('a', 'warn')]);
  assert.deepEqual(
    reportChanges(prev, report([row('a', 'ok')], { container: true }, later(60)), ctx),
    [],
  );
  const envSkip = [row('environment', 'skip'), row('a', 'ok')];
  assert.deepEqual(reportChanges(prev, report(envSkip, {}, later(60)), ctx), []);
  assert.deepEqual(
    reportChanges(prev, report([row('a', 'ok')], { summary: undefined }, later(60)), ctx),
    [],
  );
});

test('a check present in only one report is unknown and stays silent', () => {
  const prev = report([row('a', 'warn')]);
  const next = report([row('b', 'warn')], {}, later(60));
  assert.deepEqual(reportChanges(prev, next, ctx), []);
});

test('the kernel warning folded into a pending reboot is not a change', () => {
  const prev = report([row('kernel.pending', 'warn')], { reboot_pending: true });
  const next = report([row('kernel.pending', 'ok')], { reboot_pending: false }, later(60));
  assert.deepEqual(reportChanges(prev, next, ctx), []);
});

test('several changes make one announcement, worded without a verb to agree', () => {
  const one = reportChanges(
    report([row('a', 'warn')]),
    report([row('a', 'ok')], {}, later(60)),
    ctx,
  );
  assert.equal(announcement(one, false), 'Title of a, now OK');
  const ids = ['a', 'b', 'c', 'd', 'e'];
  const prev = report(ids.map((i) => row(i, 'warn')));
  const next = report(
    ids.map((i) => row(i, 'ok')),
    {},
    later(60),
  );
  const many = reportChanges(prev, next, ctx);
  assert.equal(
    announcement(many, true),
    '5 checks are now OK. Nothing on this host needs attention now',
  );
  assert.equal(announcement(many.slice(0, 2), false), 'Title of a and Title of b, now OK');
  assert.equal(announcement([], true), '');
});

test('new, error and escalated changes are each worded as what they are', () => {
  const prev = report([row('a', 'ok'), row('b', 'ok'), row('c', 'warn')]);
  const next = report([row('a', 'warn'), row('b', 'error'), row('c', 'error')], {}, later(60));
  const lines = reportChanges(prev, next, ctx).map(logLine);
  assert.deepEqual(lines.sort(), [
    'Title of a, now needs attention',
    'Title of b, now has an error',
    'Title of c, warning became an error',
  ]);
  assert.match(announcement(reportChanges(prev, next, ctx), false), /warning became an error/);
});

test('a long title is cut and no announcement carries a time', () => {
  const prev = report([row('a', 'warn', { title: 'x'.repeat(200) })]);
  const next = report([row('a', 'ok', { title: 'x'.repeat(200) })], {}, later(60));
  const text = announcement(reportChanges(prev, next, ctx), false);
  assert.ok(text.length < 100);
  assert.doesNotMatch(text, /just now|ago|\d+s\b/);
});

test('allClear needs no findings and a Health OK verdict', () => {
  assert.equal(allClear(report([row('a', 'ok'), row('b', 'ok')]), t0), true);
  assert.equal(allClear(report([row('a', 'warn'), row('b', 'ok')]), t0), false);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import type { DoctorReport, DoctorResult } from '../src/lib/hosts/health.ts';
import {
  REPORT_ONLY_SAFE_DESCRIPTION,
  reportOnly,
  reportOnlySentence,
  reportOnlySubtitle,
  reportOrigin,
} from '../src/lib/hosts/report-only.ts';
import { nextStep } from '../src/lib/hosts/next-step.ts';

function row(id: string, status: DoctorResult['status']): DoctorResult {
  return {
    id,
    title: id,
    tier: 'safe',
    status,
    current: '',
    recommended: '',
    rationale: '',
    actionable: false,
  };
}

function report(results: DoctorResult[], over: Partial<DoctorReport> = {}): DoctorReport {
  return {
    checked_at: '2026-10-04T10:00:00Z',
    os: 'linux',
    distro: 'ubuntu 24.04',
    container: false,
    reboot_pending: false,
    results,
    summary: { counted: 0, warnings: 0, errors: 0, skipped: 0, suggestions: 0, accepted: 0 },
    ...over,
  };
}

const host = { id: 'host_1', name: 'builder-1', healthy: true, active_runners: 0 };

test('a host that reports no environment row is treated as tunable', () => {
  // An agent that predates the row must keep today's behaviour: telling a real
  // Linux host it is report-only would hide the one command that helps it.
  assert.equal(reportOnly(report([row('disk.space', 'ok')])), null);
  assert.equal(reportOnly(undefined), null);
});

test('the environment row, not the operating system name, decides what is report-only', () => {
  assert.equal(reportOnly(report([row('environment', 'skip')], { os: 'darwin' })), 'os');
  assert.equal(reportOnly(report([row('environment', 'warn')])), 'distro');
  // A container wins: its image's distribution warning is not something to act on either.
  assert.equal(reportOnly(report([row('environment', 'warn')], { container: true })), 'container');
});

test('the report-only sentences never offer to change the host and name the right place to look', () => {
  assert.match(reportOnlySentence('os', 'darwin'), /does not tune darwin hosts/);
  assert.match(reportOnlySentence('os', ''), /does not tune this kind of host/);
  assert.match(reportOnlySentence('distro', 'linux'), /zoomies tune will not change it/);
  assert.match(reportOnlySentence('container', 'linux'), /not inside the container/);
  assert.equal(reportOnlySubtitle('distro'), null);
  assert.match(reportOnlySubtitle('os') ?? '', /Linux hosts only/);
  assert.match(REPORT_ONLY_SAFE_DESCRIPTION, /does not change this host/);
});

test('a blank distribution prints no stray separators', () => {
  // A Mac reports no distribution, and "darwin ·  · Checked" read as a bug.
  assert.equal(reportOrigin({ os: 'darwin', distro: '' }), 'darwin');
  assert.equal(reportOrigin({ os: 'darwin', distro: '  ' }), 'darwin');
  assert.equal(reportOrigin({ os: 'linux', distro: 'ubuntu 24.04' }), 'linux · ubuntu 24.04');
});

test('an unsupported distribution gives no next step on its own warning, and no command when cordoned', () => {
  // The environment warning is counted by the controller, but nobody can clear
  // it, so it must not put a panel with a doctor command on every such host.
  const distro = report([row('environment', 'warn')]);
  assert.equal(nextStep({ host, report: distro, cordoned: false }), null);

  const cordoned = nextStep({ host, report: distro, cordoned: true });
  assert.ok(cordoned);
  assert.equal(cordoned.where, null);
});

test('an unsupported distribution with a real finding or a reboot still gets cordon advice but no command', () => {
  const finding = report([row('environment', 'warn'), row('disk.space', 'warn')]);
  const step = nextStep({ host, report: finding, cordoned: false });
  assert.ok(step, 'a real finding still deserves the panel');
  assert.equal(step.where, null);
  assert.equal(step.button.label, 'Cordon this host');

  const reboot = report([row('environment', 'warn')], { reboot_pending: true });
  const rebooting = nextStep({ host, report: reboot, cordoned: false });
  assert.ok(rebooting);
  assert.equal(rebooting.where, null);
  assert.match(rebooting.detail, /Reboot|reboot/);
});

test('a tunable Linux host keeps its command', () => {
  const step = nextStep({ host, report: report([row('disk.space', 'warn')]), cordoned: false });
  assert.ok(step);
  assert.ok(step.where);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import type { DoctorResult } from '../src/lib/hosts/health.ts';
import { KIND_WORDS, fixCommand, previewCommand, rowKind } from '../src/lib/hosts/row-kind.ts';

function row(over: Partial<DoctorResult> = {}): DoctorResult {
  return {
    id: 'inotify.watches',
    title: 'inotify watches',
    tier: 'safe',
    status: 'warn',
    current: '',
    recommended: '',
    rationale: '',
    actionable: false,
    ...over,
  };
}

test('a warning the report marks actionable reads Fixable', () => {
  assert.equal(rowKind(row({ actionable: true }), false), 'fixable');
  assert.equal(KIND_WORDS.fixable, 'Fixable');
});

test('a warning that is not actionable reads Advice', () => {
  assert.equal(rowKind(row(), false), 'advice');
});

test('optional wins over actionable, because a trade-off is read before it is fixed', () => {
  assert.equal(rowKind(row({ optional: true, actionable: true }), false), 'optional');
});

test('only a true actionable counts, so an old agent that omits it reads Advice', () => {
  // The safe way to be wrong: never offer a command the agent did not vouch for.
  const old = row() as Partial<DoctorResult>;
  delete old.actionable;
  assert.equal(rowKind(old as DoctorResult, false), 'advice');
  const odd = row({ actionable: 'yes' as unknown as boolean });
  assert.equal(rowKind(odd, false), 'advice');
});

test('a report-only host and a row that is not a warning have no kind', () => {
  assert.equal(rowKind(row({ actionable: true }), true), null);
  for (const status of ['ok', 'skip', 'error'] as const) {
    assert.equal(rowKind(row({ status, actionable: true }), false), null);
  }
});

test('each tier previews with the flags tune demands, in the documented order', () => {
  assert.equal(previewCommand(row()), 'sudo zoomies tune --only inotify.watches --dry-run');
  assert.equal(
    previewCommand(row({ id: 'cpu.governor', tier: 'aggressive' })),
    'sudo zoomies tune --tier aggressive --only cpu.governor --dry-run',
  );
  assert.equal(
    previewCommand(row({ id: 'journal.size', tier: 'dedicated' })),
    'sudo zoomies tune --dedicated --only journal.size --dry-run',
  );
});

test('a mixed-case unit name such as service.ModemManager is accepted', () => {
  // Rejecting it would drop a real row's button without saying why.
  assert.equal(
    previewCommand(row({ id: 'service.ModemManager' })),
    'sudo zoomies tune --only service.ModemManager --dry-run',
  );
});

test('a hostile or malformed id gives no command at all', () => {
  const bad = [
    'inotify watches',
    "inotify.watches'",
    'inotify.watches; rm -rf /',
    'inotify.`id`',
    'inotify.$HOME',
    'inotify.watches\nsudo reboot',
    'Inotify.watches',
    'a.' + 'b'.repeat(63),
    '',
    'environment',
  ];
  for (const id of bad) assert.equal(previewCommand(row({ id })), null, JSON.stringify(id));
});

test('an id of exactly 64 characters passes and 65 does not', () => {
  const ok = 'a.' + 'b'.repeat(62);
  assert.equal(ok.length, 64);
  assert.notEqual(previewCommand(row({ id: ok })), null);
  assert.equal(previewCommand(row({ id: ok + 'b' })), null);
});

test('an unknown or missing tier gives no command', () => {
  assert.equal(previewCommand(row({ tier: 'root' as unknown as DoctorResult['tier'] })), null);
  assert.equal(previewCommand(row({ tier: undefined as unknown as DoctorResult['tier'] })), null);
  assert.equal(previewCommand(row({ tier: '__proto__' as unknown as DoctorResult['tier'] })), null);
});

test('the preview never carries a flag that changes the host', () => {
  const cmd = previewCommand(row({ tier: 'aggressive' })) ?? '';
  for (const flag of ['--yes', '--revert', '--background', '--force']) {
    assert.ok(!cmd.includes(flag), flag);
  }
});

test('a row the agent gives a command for copies that command, not the preview', () => {
  const cmd = 'sudo apt-get install linux-generic-hwe-24.04';
  assert.equal(fixCommand(row({ command: cmd, actionable: true })), cmd);
});

test('an actionable row with no command of its own copies the dry-run preview', () => {
  assert.equal(
    fixCommand(row({ actionable: true })),
    'sudo zoomies tune --only inotify.watches --dry-run',
  );
});

test('advice with no command has nothing to copy, rather than an invented one', () => {
  assert.equal(fixCommand(row()), null);
});

test('a row that is not a live warning has no fix to copy', () => {
  assert.equal(fixCommand(row({ status: 'ok', actionable: true })), null);
  assert.equal(
    fixCommand(
      row({ actionable: true, accepted: { by: 'a', at: '2026-01-01T00:00:00Z' } as never }),
    ),
    null,
  );
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  hostIsInvolved,
  hostSizingWords,
  sourceWords,
  tierWords,
} from '../src/lib/pools/hostSizing.ts';

test('the fleet is two different settings, and a row says which one stands in', () => {
  assert.equal(sourceWords('global', 'standard'), "the fleet's default");
  assert.equal(sourceWords('global', 'floor'), "the fleet's minimum");
  assert.equal(sourceWords('host', 'standard'), 'the host');
  assert.equal(sourceWords('pool', 'floor'), 'the pool');
  assert.equal(sourceWords(undefined, 'standard'), '');
});

test('a tier with one owner says it once, and a tier with two says each', () => {
  assert.equal(tierWords(3, 'host', 8192, 'host', 'standard'), '3 cores and 8 GB, from the host');
  // The operator set the CPU on the host and left the memory to the fleet: the
  // sentence has to say which of the two to go and change.
  assert.equal(
    tierWords(3, 'host', 4096, 'global', 'standard'),
    "3 cores from the host and 4 GB from the fleet's default",
  );
  assert.equal(tierWords(0, undefined, 0, undefined, 'floor'), '');
  assert.equal(tierWords(2, 'global', 0, undefined, 'floor'), "2 cores, from the fleet's minimum");
});

test('a host row carries what a runner there is given, at least, and at most', () => {
  assert.deepEqual(
    hostSizingWords({
      standard: { cpus: 3, memory_mb: 8192 },
      standard_cpus_source: 'host',
      standard_memory_mb_source: 'host',
      floor: { cpus: 2, memory_mb: 4096 },
      floor_cpus_source: 'host',
      floor_memory_mb_source: 'global',
      ceiling_cpus: 4,
      ceiling_source: 'pool',
    }),
    {
      standard: '3 cores and 8 GB, from the host',
      floor: "2 cores from the host and 4 GB from the fleet's minimum",
      ceiling: '4 cores, from the pool',
    },
  );
  // A pool that lends no CPU has no ceiling to explain, and one that nobody
  // set a floor for has no floor.
  assert.deepEqual(
    hostSizingWords({
      standard: { cpus: 2, memory_mb: 4096 },
      standard_cpus_source: 'pool',
      standard_memory_mb_source: 'pool',
      floor: { cpus: 0, memory_mb: 0 },
    }),
    { standard: '2 cores and 4 GB, from the pool', floor: '', ceiling: '' },
  );
  assert.deepEqual(hostSizingWords(undefined), { standard: '', floor: '', ceiling: '' });
});

// A fleet that has never set a profile must see no more than it did before:
// the explanation is owed only where the host's own settings are doing
// something to the pool's runners.
test('a row explains itself only where the host is involved', () => {
  assert.equal(hostIsInvolved(undefined, true), false);
  assert.equal(hostIsInvolved({ standard: { cpus: 2, memory_mb: 4096 } }, false), false);
  assert.equal(
    hostIsInvolved({ standard: { cpus: 2, memory_mb: 4096 }, floor_cpus_source: 'global' }, false),
    false,
  );
  assert.equal(hostIsInvolved({ floor_cpus_source: 'host' }, false), true);
  assert.equal(hostIsInvolved({ floor_memory_mb_source: 'host' }, false), true);
  assert.equal(hostIsInvolved({ ceiling_source: 'host' }, false), true);
  // A pool that takes its size from the host is always about the host.
  assert.equal(hostIsInvolved({ standard: { cpus: 2, memory_mb: 4096 } }, true), true);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { healthSummary, type DoctorReport } from '../src/lib/hosts/health.ts';
import { hostStatus } from '../src/lib/status.ts';

// The pill that says a host is sending heartbeats used to read "Healthy", beside
// a separate pill for the host's OS report. Two pills on one card, one saying
// "Healthy" and one saying "2 warnings", read as the page contradicting itself.
// Only the label moved: the key mirrors the API's `host.healthy`, and the tone
// and shape are what operators have learned, so they are pinned here too.
test('a host that is sending heartbeats reads Connected, in the colour and shape it always had', () => {
  const status = hostStatus({ healthy: true });
  assert.equal(status.label, 'Connected');
  assert.equal(status.key, 'healthy');
  assert.equal(status.tone, 'idle');
  assert.equal(status.shape, 'hollow');
});

test('a host that is not sending heartbeats is Unreachable', () => {
  const status = hostStatus({ healthy: false });
  assert.equal(status.label, 'Unreachable');
  assert.equal(status.tone, 'danger');
});

test('a cordoned host reads Cordoned, and a throttled one Throttled', () => {
  const cordoned = hostStatus({ healthy: true, cordoned: true });
  assert.equal(cordoned.label, 'Cordoned');
  assert.equal(cordoned.tone, 'draining');
  const throttled = hostStatus({ healthy: true, throttle: { level: 1 } as never });
  assert.equal(throttled.label, 'Throttled');
  assert.equal(throttled.tone, 'pending');
});

test('what is wrong with a host outranks what is right: unreachable, then cordoned, then throttled, then connected', () => {
  const throttle = { level: 2 } as never;
  assert.equal(hostStatus({ healthy: false, cordoned: true, throttle }).label, 'Unreachable');
  assert.equal(hostStatus({ healthy: true, cordoned: true, throttle }).label, 'Cordoned');
  assert.equal(hostStatus({ healthy: true, throttle }).label, 'Throttled');
  assert.equal(hostStatus({ healthy: true }).label, 'Connected');
  // A host whose reachability is not known yet is not called unreachable.
  assert.equal(hostStatus({}).label, 'Connected');
});

// "Healthy" is the OS report's word now, and "Connected" is the heartbeat's. A
// label that crept back into either set would put the two meanings on one card
// again.
test('no host status label says healthy, and the OS health pill never says Connected', () => {
  const throttle = { level: 1 } as never;
  const labels = [
    hostStatus({ healthy: true }),
    hostStatus({ healthy: false }),
    hostStatus({ healthy: true, cordoned: true }),
    hostStatus({ healthy: true, throttle }),
  ].map((status) => status.label);
  for (const label of labels) assert.doesNotMatch(label, /healthy/i);

  const now = Date.parse('2026-10-04T10:00:00Z');
  const fine: DoctorReport = {
    checked_at: new Date(now).toISOString(),
    os: 'linux',
    distro: 'ubuntu 24.04',
    container: false,
    reboot_pending: false,
    results: [],
    summary: { counted: 1, warnings: 0, errors: 0, skipped: 0, suggestions: 0, accepted: 0 },
  };
  for (const report of [undefined, fine, { ...fine, reboot_pending: true }]) {
    for (const reachable of [true, false]) {
      assert.notEqual(healthSummary(report, now, reachable).label, 'Connected');
    }
  }
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  autoPoolLine,
  classWord,
  labelsFromRows,
  overrideNote,
  pendingMove,
  tagRows,
  tagText,
} from '../src/lib/hosts/tags.ts';
import type { HostAutoPool, HostSizeClass, HostTag } from '../src/lib/api/types.ts';

const tags: HostTag[] = [
  { key: 'arch', value: 'amd64', source: 'automatic' },
  { key: 'gpu', value: '', source: 'operator' },
  { key: 'os', value: 'linux', source: 'automatic' },
  { key: 'rack', value: 'b4', source: 'operator' },
  { key: 'size', value: 'large', source: 'operator', overrides: 'medium' },
];

test('a tag is written the way an operator types it, and a flag is just its name', () => {
  assert.equal(tagText({ key: 'rack', value: 'b4' }), 'rack=b4');
  assert.equal(tagText({ key: 'gpu', value: '' }), 'gpu');
});

test('the operator’s tags come first and keep their order, then the ones worked out', () => {
  const rows = tagRows(tags);
  assert.deepEqual(
    rows.map((row) => `${row.automatic ? 'auto' : 'own'}:${row.text}`),
    ['own:gpu', 'own:rack=b4', 'own:size=large', 'auto:arch=amd64', 'auto:os=linux'],
  );
  assert.deepEqual(tagRows(undefined), []);
});

test('a tag that replaces what the machine measures says what it replaced', () => {
  const size = tagRows(tags).find((row) => row.key === 'size');
  assert.match(size?.hint ?? '', /replaces size=medium/);
  // And an ordinary tag does not claim to replace anything.
  const rack = tagRows(tags).find((row) => row.key === 'rack');
  assert.doesNotMatch(rack?.hint ?? '', /replaces/);
});

test('a derived tag cannot be mistaken for one that can be edited', () => {
  for (const row of tagRows(tags).filter((r) => r.automatic)) {
    assert.match(row.hint, /controller/);
  }
  const derivedSize = tagRows([{ key: 'size', value: 'medium', source: 'automatic' }])[0];
  assert.match(derivedSize?.hint ?? '', /Set a size tag of your own/);
});

test('a class is capitalised for a badge, and nothing is a class of no name', () => {
  assert.equal(classWord('medium'), 'Medium');
  assert.equal(classWord(undefined), '');
});

test('only a class an operator set is explained in the open', () => {
  const measured: HostSizeClass = { class: 'medium', source: 'measured', reason: 'x' };
  assert.equal(overrideNote(measured), '');
  assert.equal(overrideNote(undefined), '');

  const set: HostSizeClass = { class: 'large', source: 'tag', measured: 'medium', reason: 'x' };
  assert.equal(overrideNote(set), "Set by this host's size tag. Its machine measures as medium.");

  // A tag that merely agrees with the machine is still the operator's, and
  // saying so is what stops it silently becoming wrong when the machine changes.
  const agrees: HostSizeClass = { class: 'medium', source: 'tag', reason: 'x' };
  assert.match(overrideNote(agrees), /agrees with what its machine measures/);
});

test('a move being held is reported with when it began and when it takes effect', () => {
  assert.equal(pendingMove({ class: 'small', source: 'measured', reason: 'x' }), null);
  assert.deepEqual(
    pendingMove({
      class: 'small',
      source: 'measured',
      reason: 'x',
      pending: 'medium',
      pending_since: '2026-10-04T10:00:00Z',
      pending_until: '2026-10-04T10:10:00Z',
    }),
    { to: 'medium', since: '2026-10-04T10:00:00Z', until: '2026-10-04T10:10:00Z' },
  );
});

test('the pool line says whether the pool exists, and otherwise gives the controller’s reason', () => {
  assert.equal(autoPoolLine(undefined), null);

  const counted: HostAutoPool = { counted: true, pool: 'zoomies-medium', pool_id: 'pol_1' };
  assert.deepEqual(autoPoolLine(counted), {
    counted: true,
    text: 'Its slots count towards zoomies-medium.',
    poolId: 'pol_1',
  });

  // Report-only: the pool is the one that would be made, so it has no id yet.
  const wouldBe: HostAutoPool = { counted: true, pool: 'zoomies-medium' };
  assert.equal(
    autoPoolLine(wouldBe)?.text,
    'Its slots would count towards zoomies-medium, which has not been made yet.',
  );
  assert.equal(autoPoolLine(wouldBe)?.poolId, undefined);

  const skipped: HostAutoPool = {
    counted: false,
    reason:
      'It is cordoned, so its slots do not count towards an automatic pool until it is uncordoned.',
    reason_code: 'cordoned',
  };
  assert.deepEqual(autoPoolLine(skipped), { counted: false, text: skipped.reason });
});

test('a tag with no value is a flag, and a flag is true whichever surface set it', () => {
  assert.deepEqual(
    labelsFromRows([
      { key: ' rack ', value: ' b4 ' },
      { key: 'gpu', value: '' },
      { key: '  ', value: 'ignored' },
    ]),
    { rack: 'b4', gpu: 'true' },
  );
});

test('saving the dialog does not rewrite a label somebody left empty on purpose', () => {
  // The host already carries `legacy=` with an empty value, and nobody touched
  // it; turning it into `legacy=true` would change what a selector matches.
  assert.deepEqual(
    labelsFromRows(
      [
        { key: 'legacy', value: '' },
        { key: 'gpu', value: '' },
      ],
      { legacy: '' },
    ),
    { legacy: '', gpu: 'true' },
  );
  // A value that was not empty and has been cleared is a new flag, not a keep.
  assert.deepEqual(labelsFromRows([{ key: 'zone', value: '' }], { zone: 'demo' }), {
    zone: 'true',
  });
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  byHandLink,
  confirmHostUpdate,
  hostUpdateWords,
  skewFact,
  targetTag,
  type HostUpdateBlock,
} from '../src/lib/hosts/update.ts';

/** A remote host on 1.2.0 under a controller on 1.3.0, whose agent offers to update itself. */
function host(over: Record<string, unknown> = {}, update: Partial<HostUpdateBlock> = {}) {
  return {
    id: 'hst_1',
    name: 'builder-1',
    version: '1.2.0',
    version_skew: 'behind' as const,
    upgrade_version: '1.3.0',
    upgrade_command: "sudo zoomies upgrade --mode agent --version 'v1.3.0'",
    os: 'linux',
    embedded: false,
    update: {
      state: 'none' as const,
      reason: 'builder-1 runs 1.2.0 and can be updated to v1.3.0.',
      can_update: true,
      attempt_id: '',
      code: '' as const,
      ...update,
    },
    ...over,
  };
}
test('a machine Zoomies rents is offered no update, however it is doing', () => {
  // It is behind from the moment it joins, and the update row is where a card
  // would promise a button: there is nowhere to run a command inside a clone,
  // and the way to change what it runs is its provider's template, which the
  // card's own guidance and the provider's page name.
  const words = hostUpdateWords(
    host(
      { machine_id: 'mach_1' },
      { state: 'none', can_update: false, reason: 'It is a machine.' },
    ),
  );
  assert.equal(words, null);
  // Even while an attempt is open, which cannot happen for one and must not
  // draw anything if it somehow did.
  assert.equal(hostUpdateWords(host({ machine_id: 'mach_1' }, { state: 'requested' })), null);
});

test('behind means the template for a machine, and the agent for a host somebody owns', () => {
  const owned = skewFact('behind');
  const rented = skewFact('behind', true);
  assert.equal(owned?.label, 'Behind');
  assert.equal(rented?.label, 'Behind');
  assert.match(owned?.hint ?? '', /upgrade it when convenient/);
  assert.doesNotMatch(rented?.hint ?? '', /upgrade it when convenient/);
  assert.match(rented?.hint ?? '', /template/);
  assert.match(rented?.hint ?? '', /replaced as it goes idle/);
  // The other two answers are about the two builds and are the same either way.
  assert.equal(skewFact('ahead', true)?.hint, skewFact('ahead')?.hint);
  assert.equal(skewFact('differs', true)?.hint, skewFact('differs')?.hint);
});

test('a host that is behind and can be updated is offered the button, and its state is not a status colour', () => {
  const words = hostUpdateWords(host());
  assert.ok(words);
  assert.equal(words.canPress, true);
  assert.equal(words.action, 'Update');
  assert.equal(words.inFlight, false);
  // Behind is a fact about the release and not a state the host is in.
  assert.equal(words.tone, 'neutral');
  assert.equal(words.sentence, 'builder-1 runs 1.2.0 and can be updated to v1.3.0.');
});

test('behind, ahead and different are neutral facts and a matching host has none', () => {
  for (const skew of ['behind', 'ahead', 'differs'] as const) {
    const fact = skewFact(skew);
    assert.ok(fact, skew);
    assert.equal(fact.tone, 'neutral', skew);
  }
  assert.equal(skewFact('behind')?.label, 'Behind');
  assert.equal(skewFact('ahead')?.label, 'Ahead');
  assert.equal(skewFact('differs')?.label, 'Different build');
  assert.equal(skewFact(undefined), null);
  assert.equal(skewFact(''), null);
});

test('each state of an attempt has a label, a tone and whether it can be pressed', () => {
  const rows = [
    // state, can_update, label, tone, drawn, canPress, inFlight
    ['none', true, 'Can be updated', 'neutral', true, true, false],
    ['none', false, 'Update by command', 'neutral', true, false, false],
    ['requested', false, 'Updating', 'accent', false, false, true],
    ['succeeded', false, 'Updated', 'accent', false, false, false],
    ['failed', true, 'Failed', 'danger', true, true, false],
    ['failed', false, 'Failed', 'danger', true, false, false],
    ['timed_out', true, 'Timed out', 'danger', true, true, false],
    ['cancelled', true, 'Cancelled', 'neutral', true, true, false],
  ] as const;
  for (const [state, can, label, tone, offered, canPress, inFlight] of rows) {
    // An attempt that ended without the update leaves the host behind, and so
    // does a running one; a success is a host that matches the controller.
    const where = state === 'succeeded' ? { version: '1.3.0', version_skew: undefined } : {};
    const words = hostUpdateWords(host(where, { state, can_update: can, reason: 'Why.' }));
    assert.ok(words, `${state}/${can}`);
    assert.equal(words.label, label, `${state}/${can} label`);
    assert.equal(words.tone, tone, `${state}/${can} tone`);
    assert.equal(words.offered, offered, `${state}/${can} offered`);
    assert.equal(words.canPress, canPress, `${state}/${can} canPress`);
    assert.equal(words.inFlight, inFlight, `${state}/${can} inFlight`);
  }
});

test('an update the stopped helper could not be handed to says the helper stopped, in words', () => {
  // The card must not read as a release that failed to install: the helper on
  // the host stopped reading requests, and the sentence says what to run.
  const reason =
    'The update helper on builder-1 has stopped (its path unit is inactive, disabled, failed; a request had been waiting for 3 days).';
  const words = hostUpdateWords(
    host({}, { state: 'failed', code: 'host.update_helper_stuck', reason }),
  );
  assert.equal(words?.label, 'Helper stopped');
  assert.equal(words?.tone, 'danger');
  assert.equal(words?.sentence, reason);
  assert.equal(words?.action, 'Try again');
});

test('a failed update can be tried again, and says so in its action', () => {
  const words = hostUpdateWords(host({}, { state: 'failed', reason: 'The helper said no.' }));
  assert.equal(words?.action, 'Try again');
  assert.equal(words?.sentence, 'The helper said no.');
});

test('a request that is open is never shown as done while the host reports its old release', () => {
  const words = hostUpdateWords(
    host(
      {},
      {
        state: 'requested',
        can_update: false,
        attempt_id: 'upd_1',
        reason: 'The update to v1.3.0 has been asked for.',
      },
    ),
  );
  assert.equal(words?.label, 'Updating');
  assert.equal(words?.inFlight, true);
  assert.equal(words?.canPress, false);
  assert.doesNotMatch(words?.live ?? '', /updated|done|now runs/i);
  assert.doesNotMatch(words?.sentence ?? '', /updated\b/i);
});

test('the host reporting the release is the update done, before the controller has closed the attempt', () => {
  // The heartbeat that carries the version and the one that closes the attempt
  // are one, but their frames are not: the version is what the attempt waited for.
  const words = hostUpdateWords(
    host({ version: '1.3.0', version_skew: undefined }, { state: 'requested', can_update: false }),
  );
  assert.equal(words?.label, 'Updated');
  assert.equal(words?.inFlight, false);
  assert.equal(words?.sentence, 'builder-1 runs 1.3.0 now.');
  assert.match(words?.live ?? '', /builder-1: updated/);
});

test('an attempt the controller closed as succeeded is shown as done, in the version the host reports', () => {
  const words = hostUpdateWords(
    host({ version: '1.3.0', version_skew: undefined }, { state: 'succeeded', can_update: false }),
  );
  assert.equal(words?.label, 'Updated');
  assert.equal(words?.sentence, 'builder-1 runs 1.3.0 now.');
});

test('an update that worked for an earlier release does not hide that the host is behind again', () => {
  // The controller has moved on since: the latest attempt is a success, and the
  // host is behind the new release and can be asked again.
  const words = hostUpdateWords(host({}, { state: 'succeeded', can_update: true }));
  assert.equal(words?.label, 'Can be updated');
  assert.equal(words?.canPress, true);
});

test('the controller’s sentence is passed through as text and never interpreted', () => {
  const sentence = '<img src=x onerror=alert(1)> **bold** [a](javascript:alert(1))';
  const words = hostUpdateWords(host({}, { state: 'failed', reason: sentence }));
  assert.equal(words?.sentence, sentence);
});

test('a host that matches the controller, or is ahead of it, has no row unless an attempt is worth showing', () => {
  assert.equal(hostUpdateWords(host({ version_skew: undefined }, { can_update: false })), null);
  assert.equal(hostUpdateWords(host({ version_skew: 'ahead' }, { can_update: false })), null);
  // An attempt that failed and left the host behind is worth showing; one the
  // controller dropped because the host got there another way arrives as none.
  assert.ok(
    hostUpdateWords(host({ version_skew: undefined }, { state: 'succeeded', can_update: false })),
  );
});

test('the agent inside the controller and a controller that sends no block have no row', () => {
  assert.equal(hostUpdateWords(host({ embedded: true })), null);
  assert.equal(hostUpdateWords(host({ update: undefined })), null);
});

test('a host that cannot be updated from here says why in the controller’s words and offers no button', () => {
  const why =
    'This host’s agent does not offer to update itself. Run sudo zoomies updates helper install there, or update it with the command below.';
  const words = hostUpdateWords(host({}, { can_update: false, reason: why }));
  assert.equal(words?.canPress, false);
  assert.equal(words?.sentence, why);
  assert.equal(words?.label, 'Update by command');
});

// With updating off the controller refuses every press, so the card must not
// hold a button that only ever says no: what it holds is the controller's
// sentence saying why, as text, and a button that cannot be pressed.
test('with updating off the card says so as text and nothing on it can be pressed', () => {
  const why =
    'Updating is off, so hosts are not updated from here. Somebody with the platform role can turn it on by setting updates.mode to manual or auto on the Configuration page.';
  const words = hostUpdateWords(host({}, { can_update: false, reason: why }));
  assert.ok(words);
  assert.equal(words.canPress, false);
  assert.equal(words.sentence, why);
  assert.equal(words.inFlight, false);
  // An update that failed before updating was switched off is not offered again.
  const failed = hostUpdateWords(
    host({}, { state: 'failed', can_update: false, reason: 'It failed.' }),
  );
  assert.equal(failed?.canPress, false);
});

// The helper can never be installed there, so a button that can never be
// pressed would only be a promise; the reason is the card's text, and the
// command beneath the card is the way.
test('a host the helper can never be installed on says why, draws no button and suggests no install', () => {
  const why =
    'The update helper cannot be installed on this host: its agent runs on a host that systemd does not run, and the update helper is a pair of systemd units. Update it on the host with the command below.';
  const words = hostUpdateWords(host({}, { state: 'unsupported', can_update: false, reason: why }));
  assert.equal(words?.label, 'Update by command');
  assert.equal(words?.sentence, why);
  assert.equal(words?.offered, false);
  assert.equal(words?.canPress, false);
  assert.equal(words?.tone, 'neutral');
  assert.doesNotMatch(words?.sentence ?? '', /helper install/);
});

// zoomies upgrade knows no Windows service and Windows has no sudo, so the
// controller sends a Windows agent no command. Its card must not promise one:
// it says the update is by hand and links to the steps.
test('a Windows host is updated by hand, and its card links to the steps rather than promising a command', () => {
  const why =
    'The update helper cannot be installed on this host: its agent runs on an operating system other than Linux, and the update helper is a pair of systemd units, which need Linux. Update it by hand on the host, with the steps at the foot of this card.';
  const windows = host(
    { os: 'windows', upgrade_command: undefined, upgrade_note: 'Update this one by hand.' },
    { state: 'unsupported', can_update: false, reason: why },
  );
  assert.equal(hostUpdateWords(windows)?.label, 'Update by hand');
  assert.match(byHandLink(windows), /\/upgrading\/#upgrading-an-agent-host$/);
  // A host that has a command to copy needs no link: the command is the way.
  for (const os of ['linux', 'darwin']) {
    const other = host({ os }, { state: 'unsupported', can_update: false, reason: why });
    assert.equal(hostUpdateWords(other)?.label, 'Update by command', os);
    assert.equal(byHandLink(other), '', os);
  }
});

test('a host the helper cannot be installed on has no row once it runs the controller’s release', () => {
  assert.equal(
    hostUpdateWords(host({ version_skew: '' }, { state: 'unsupported', can_update: false })),
    null,
  );
});

test('the target is named with a v whether the controller reports one or not', () => {
  assert.equal(targetTag({ upgrade_version: '1.3.0' }), 'v1.3.0');
  assert.equal(targetTag({ upgrade_version: 'v1.3.0' }), 'v1.3.0');
  assert.equal(targetTag({ upgrade_version: ' 1.3.0 ' }), 'v1.3.0');
  assert.equal(targetTag({ upgrade_version: '' }), '');
  assert.equal(targetTag({}), '');
});

test('the confirmation names the host and the release, and says what is true of the restart', () => {
  const words = confirmHostUpdate('builder-1', '1.2.0', 'v1.3.0');
  assert.match(words.title, /builder-1/);
  assert.equal(words.description, 'Update the agent on builder-1 from 1.2.0 to v1.3.0?');
  assert.equal(words.confirmLabel, 'Update to v1.3.0');
  const text = words.consequences.join('\n');
  assert.match(text, /The agent on builder-1 restarts\./);
