});

test('a minimum sits at or under the standard and above the floor', () => {
  const over = draftErrors(
    valid({ sizing: 'fixed', cpus: '2', memory_mb: '4096', min_cpus: '4', min_memory_mb: '8192' }),
    false,
  );
  assert.match(over['resources.min_cpus'] ?? '', /at or below the standard CPU/);
  assert.match(over['resources.min_memory_mb'] ?? '', /at or below the standard memory/);
  // Under an automatic size the floor still applies, because it is sent.
  const tiny = draftErrors(valid({ min_cpus: '0.1', min_memory_mb: '128' }), false);
  assert.match(tiny['resources.min_cpus'] ?? '', /quarter of a core/);
  assert.match(tiny['resources.min_memory_mb'] ?? '', /512 MB/);
});

test('each sidecar share stays between ten and ninety percent, and says which resource it is about', () => {
  for (const [key, field, what] of [
    ['daemon_cpu_share', 'resources.daemon_cpu_share_percent', 'CPU'],
    ['daemon_memory_share', 'resources.daemon_memory_share_percent', 'memory'],
  ] as const) {
    for (const share of ['5', '95']) {
      assert.match(
        draftErrors(valid({ [key]: share }), false)[field] ?? '',
        new RegExp(`between 10 and 90 percent of the ${what}`),
        `${key} ${share}`,
      );
    }
    for (const share of ['70', '']) {
      assert.equal(
        draftErrors(valid({ [key]: share }), false)[field],
        undefined,
        `${key} ${share}`,
      );
    }
  }
});

// A pool saved with one figure meant it for both resources, so opening it shows
// that, and a specific figure beats the general one. A pool being edited has its
// division already, which is why it is marked chosen: the recommended preset is
// only ever the start of a new pool.
test('a pool saved with one share opens with it for both, and is never preselected over', () => {
  const general = draftFromPool({ resources: { daemon_share_percent: 70 } } as Pool);
  assert.equal(general.daemon_cpu_share, '70');
  assert.equal(general.daemon_memory_share, '70');
  assert.equal(general.split_chosen, true);
  const specific = draftFromPool({
    resources: { daemon_share_percent: 70, daemon_memory_share_percent: 35 },
  } as Pool);
  assert.equal(specific.daemon_cpu_share, '70');
  assert.equal(specific.daemon_memory_share, '35');
  assert.equal(emptyDraft().split_chosen, false);
});

// A size limit is kept by evicting from a directory on the host: there is
// nothing to measure inside a named volume.
test('a cache size limit needs an absolute host path', () => {
  const named = valid({
    cache_enabled: true,
    cache_size_limit: '1073741824',
    cache_source: 'volume-prefix',
  });
  assert.ok(draftErrors(named, false)['cache.size_limit']);
  const path = { ...named, cache_source: '/var/lib/zoomies/cache' };
  assert.equal(draftErrors(path, false)['cache.size_limit'], undefined);
});

// A tmpfs is charged to the runner's memory limit, so typed sizes that take the
// whole of a typed limit leave a job nothing to run in.
test('in-memory folders that take the whole limit are refused where they are typed', () => {
  const tight = valid({
    sizing: 'fixed',
    cpus: '2',
    memory_mb: '2048',
    tmpfs_work: true,
    tmpfs_work_size: '2048',
  });
  assert.match(
    draftErrors(tight, false)['tmpfs.work.size_mb'] ?? '',
    /raise it to at least 4096 MB/,
  );
  const tiny = valid({ tmpfs_tmp: true, tmpfs_tmp_size: '8' });
  assert.match(draftErrors(tiny, false)['tmpfs.tmp.size_mb'] ?? '', /at least 64/);
});

// Consent is per decision, and the editor resets it when the answer changes.
test('the host socket cannot be saved without the confirmation', () => {
  const socket = valid({ docker_mode: 'host-socket' });
  assert.ok(draftErrors(socket, false)['docker_mode']);
  assert.equal(draftErrors(socket, true)['docker_mode'], undefined);
});

// A pool whose backend no host offers never makes a runner and looks perfectly
// healthy doing it, so the draft refuses it while the fleet has something else.
test('a backend nothing offers is refused while another is on offer', () => {
  const offers: BackendOffer[] = [
    { kind: 'docker', hosts: 2, dindHosts: 2 },
    { kind: 'podman', hosts: 0, dindHosts: 0 },
    { kind: 'process', hosts: 0, dindHosts: 0 },
  ];
  assert.match(
    draftErrors(valid({ backend: 'podman' }), false, offers, true)['backend'] ?? '',
    /Docker \(2 hosts\)/,
  );
  assert.equal(
    draftErrors(valid({ backend: 'docker' }), false, offers, true)['backend'],
    undefined,
  );
  // Until the fleet is known, nothing is claimed about it.
  assert.equal(
    draftErrors(valid({ backend: 'podman' }), false, offers, false)['backend'],
    undefined,
  );
});

// The server refuses a sidecar image on a pool that starts no sidecar, so a pool
// switched away from dind must not keep sending the one it had.
test('the sidecar image is sent only for a pool that runs a sidecar', () => {
  const dind = toPoolBody(valid({ docker_mode: 'dind', dind_image: ' registry.example/dind:27 ' }));
  assert.equal(dind.dind_image, 'registry.example/dind:27');
  const none = toPoolBody(valid({ docker_mode: 'none', dind_image: 'registry.example/dind:27' }), {
    complete: true,
  });
  assert.equal(none.dind_image, '');
  assert.equal('dind_image' in toPoolBody(valid({ docker_mode: 'none', dind_image: 'x' })), false);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { emptyDraft, draftErrors } from '../src/lib/pools/draft.ts';
import type { PoolDraft } from '../src/lib/pools/draft.ts';
import {
  SECTIONS,
  editedSections,
  sectionDef,
  sectionForField,
} from '../src/lib/pools/sections.ts';
import { summarise } from '../src/lib/pools/summaries.ts';

const draft = (over: Partial<PoolDraft> = {}): PoolDraft => ({
  ...emptyDraft(),
  name: 'zoomies-linux-x64',
  installation_id: 'ins_1',
  labels: ['zoomies-linux-x64'],
  ...over,
});

// A refusal is only useful if it opens the part of the page that can fix it,
// and the server's field names are the only thing that says which that is. A
// field no section lists would be refused with nowhere to go.
test('every field the editor can be refused on belongs to exactly one section', () => {
  const seen = new Map<string, string>();
  for (const section of SECTIONS) {
    for (const field of section.fields) {
      assert.equal(seen.get(field), undefined, `${field} is listed twice`);
      seen.set(field, section.id);
    }
  }
  // The rules the browser checks for itself, whichever field they are filed under.
  const everyRule = draftErrors(
    draft({
      name: '',
      installation_id: '',
      labels: [],
      min_runners: 'x',
      max_runners: '0',
      priority: 'x',
      idle_timeout: 'soon',
      sizing: 'fixed',
      cpus: '',
      memory_mb: '',
      min_cpus: '0.1',
      min_memory_mb: '1',
      daemon_cpu_share: '5',
      daemon_memory_share: '5',
      disk_gb: '-1',
      cpu_burst_max: '0.1',
      cache_enabled: true,
      cache_size_limit: '5',
      cache_source: 'volume',
      tmpfs_work: true,
      tmpfs_work_size: '1',
      tmpfs_tmp: true,
      tmpfs_tmp_size: '1',
      docker_mode: 'host-socket',
    }),
    false,
  );
  for (const field of Object.keys(everyRule)) {
    assert.notEqual(sectionForField(field), null, `${field} has no section to open`);
  }
});

test('a field is pointed at the section that owns it', () => {
  assert.equal(sectionForField('name'), 'basics');
  assert.equal(sectionForField('host_selector'), 'hosts');
  assert.equal(sectionForField('docker_mode'), 'runner');
  assert.equal(sectionForField('resources.memory_mb'), 'size');
  assert.equal(sectionForField('cpu_burst.max_cpus'), 'size');
  assert.equal(sectionForField('runner_settings.provision_timeout'), 'scaling');
  assert.equal(sectionForField('tmpfs.daemon.size_mb'), 'speed');
  assert.equal(sectionForField('cache.size_limit'), 'speed');
  // The environment is carried through untouched, so there is nothing to open.
  assert.equal(sectionForField('env'), null);
});

test('seven sections, each with a name and a sentence about what it decides', () => {
  assert.equal(SECTIONS.length, 7);
  assert.deepEqual(
    SECTIONS.map((section) => section.id),
    ['basics', 'hosts', 'providers', 'runner', 'size', 'scaling', 'speed'],
  );
  for (const section of SECTIONS) {
    assert.ok(section.title.length > 0);
    assert.ok(section.description.endsWith('.'), `${section.id} says what it decides`);
    assert.equal(sectionDef(section.id), section);
  }
});

// "Edited" is the promise that Save will change something there, so it is a
// comparison of what is in the section now with what it started as -- typing a
// figure and typing the old one back is not an edit.
test('a section is edited only while its answers differ from where it started', () => {
  const start = draft();
  assert.equal(editedSections(start, start).size, 0);

  const changed = draft({ max_runners: '9', cache_enabled: true });
  assert.deepEqual([...editedSections(changed, start)].sort(), ['scaling', 'speed']);

  const typedBack = draft({ max_runners: '9' });
  typedBack.max_runners = start.max_runners;
  assert.equal(editedSections(typedBack, start).size, 0);
});

// Docker is asked on the first section and set on the third, so changing it
// from either place marks both: each of them holds the answer.
test('the Docker answer marks both the section that asks it and the one that sets it', () => {
  const edited = editedSections(draft({ docker_mode: 'dind' }), draft());
  assert.deepEqual([...edited].sort(), ['basics', 'runner']);
});

test('the first section says what a workflow writes, who it is for and whether Docker is on', () => {
  const lines = summarise(draft({ labels: ['zoomies-gpu', 'cuda12'], docker_mode: 'dind' }), {
    installation: 'eyupio',
  });
  assert.equal(lines.basics, 'runs-on zoomies-gpu, cuda12 · eyupio · Docker for jobs');
  assert.equal(
    summarise(draft({ labels: [], installation_id: '' })).basics,
    'no labels yet · no GitHub connection chosen',
  );
});

test('hosts say whether a pool may use any machine or only some, and how many that is', () => {
  assert.equal(summarise(draft()).hosts, 'Any host that can run it');
  assert.equal(
    summarise(draft(), { hostsTotal: 3 }).hosts,
    'Any host that can run it · 3 connected',
  );
  const some = draft({ restrict_hosts: true, host_selector: { arch: 'arm64', os: 'linux' } });
  assert.equal(
    summarise(some, { hostsTotal: 3, hostsMatching: 1 }).hosts,
    'Only hosts where arch=arm64, os=linux · 1 match',
  );
  // A rule chosen but not yet written is not claimed to be anything.
  assert.equal(
    summarise(draft({ restrict_hosts: true })).hosts,
    'Only some hosts · no rule chosen yet',
  );
});

test('the runner says what it is made of, and only what was changed from the default', () => {
  assert.equal(summarise(draft()).runner, 'Docker · default image');
  const tuned = draft({
    backend: 'podman',
    platform_os: 'debian',
    platform_os_version: '12',
    image: 'registry.example/runner:1',
    runner_version: '2.330.0',
    run_as_root: true,
  });
  assert.equal(
    summarise(tuned).runner,
    'Podman · Debian 12 · your own image · runner 2.330.0 · runs as root',
  );
  // A process runner has no image to speak of.
  assert.equal(summarise(draft({ backend: 'process' })).runner, 'Process');
});

test('the size says what one runner gets and whether it may borrow CPU', () => {
  assert.equal(
    summarise(draft()).size,
    'One share of each host · elastic CPU and memory observing',
    'a new pool starts both valves on observe, and says it once',
  );
  assert.equal(
    summarise(draft({ cpu_burst_mode: 'automatic' })).size,
    'One share of each host · elastic CPU boosting · elastic memory observing',
  );
  assert.equal(
    summarise(draft({ cpu_burst_mode: 'off', memory_burst_mode: 'off', sizing: 'profile' })).size,
    'The size each host sets',
  );
  assert.equal(
    summarise(
      draft({
        sizing: 'fixed',
        cpus: '4',
        memory_mb: '8192',
        min_memory_mb: '4096',
        memory_burst_mode: 'off',
      }),
    ).size,
    '4 cores and 8 GB on every host · never below 4 GB',
    'a fixed size cannot borrow, so it says nothing of elastic CPU',
  );
  assert.equal(
    summarise(draft({ backend: 'process', cpu_burst_mode: 'observe' })).size,
    'One share of each host',
    'a process runner has no live quota to borrow against, and no limit to raise',
  );
});

test('a fixed size can still lend memory, which needs only a limit to watch', () => {
  assert.equal(
    summarise(
      draft({
        sizing: 'fixed',
        cpus: '4',
        memory_mb: '8192',
        memory_burst_mode: 'automatic',
      }),
    ).size,
    '4 cores and 8 GB on every host · elastic memory lending',
  );
});

test('scaling says how many runners, for how long, and only the unusual', () => {
  assert.equal(summarise(draft()).scaling, '0 to 4 runners · idle 5m');
  const unusual = draft({
    min_runners: '1',
    max_runners: '8',
    ephemeral: false,
    priority: '2',
    provision_timeout: '45m',
    drain_timeout: '10m',
  });
  assert.equal(
    summarise(unusual).scaling,
    '1 to 8 runners · idle 5m · reused between jobs · priority 2 · 2 timing overrides',
  );
  assert.equal(
    summarise(draft({ provision_timeout: '45m' })).scaling,
    '0 to 4 runners · idle 5m · 1 timing override',
  );
});

// A pool loaded from the API carries Go's own spelling, "5m0s", and an operator
// reading the row says "5m"; a value half typed is left as it is.
test('the idle timeout is said the way an operator says it', () => {
  assert.equal(summarise(draft({ idle_timeout: '5m0s' })).scaling, '0 to 4 runners · idle 5m');
  assert.equal(summarise(draft({ idle_timeout: '90s' })).scaling, '0 to 4 runners · idle 1m30s');
  assert.equal(summarise(draft({ idle_timeout: '1h0m0s' })).scaling, '0 to 4 runners · idle 1h');
  assert.equal(summarise(draft({ idle_timeout: '5mm' })).scaling, '0 to 4 runners · idle 5mm');
});

test('speed-ups say what is kept in memory and whether there is a cache', () => {
  assert.equal(summarise(draft()).speed, 'Scratch space on disk · no cache');
  assert.equal(
    summarise(draft({ tmpfs_work: true, tmpfs_tmp: true })).speed,
    'work folder, /tmp in memory where there is room · no cache',
  );
  assert.equal(
    summarise(draft({ tmpfs_work: true, tmpfs_auto: false, cache_enabled: true })).speed,
    'work folder in memory · shared cache',
  );
  // The image store is the sidecar's, so a pool without one does not claim it.
  assert.equal(
    summarise(draft({ tmpfs_daemon: true, tmpfs_work: true })).speed,
    'work folder in memory where there is room · no cache',
  );
  assert.equal(
    summarise(
      draft({
        docker_mode: 'dind',
        tmpfs_daemon: true,
        cache_enabled: true,
        cache_scope: 'repository',
        cache_tools: true,
      }),
    ).speed,
    'image store in memory where there is room · per-repository cache with tools',
  );
  // A process runner has nothing to mount over.
  assert.equal(
    summarise(draft({ backend: 'process', tmpfs_work: true })).speed,
    'Scratch space on disk · no cache',
  );
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { statusLine, visibleWarnings } from '../src/lib/pools/verdict.ts';
import type { StatusInput } from '../src/lib/pools/verdict.ts';
import type { Result } from '../src/lib/api/types.ts';

type Verdict = Result<'validatePool'>;

const verdict = (over: Partial<Verdict> = {}): Verdict =>
  ({ valid: true, errors: [], warnings: [], matching_hosts: 2, ...over }) as Verdict;

const input = (over: Partial<StatusInput> = {}): StatusInput => ({
  blockers: 0,
  refusals: 0,
  editing: false,
  dirty: true,
  unreachable: false,
  verdict: verdict(),
  fleetKnown: true,
  ...over,
});

// The order of the checks is the whole of this: what the browser can see is
// said before anything the controller thinks, and a controller that has not
// answered is said before it is trusted.
test('a rule being broken is said first, and says what saving would be', () => {
  assert.deepEqual(statusLine(input({ blockers: 1 })), {
    tone: 'danger',
    text: '1 thing to fix before this can be created.',
    action: 'Show',
  });
  assert.equal(
    statusLine(input({ blockers: 3, editing: true })).text,
    '3 things to fix before this can be saved.',
  );
  // Even a verdict that says all is well does not outrank a rule being broken.
  assert.equal(statusLine(input({ blockers: 1, verdict: verdict() })).tone, 'danger');
});

test('an edit that changed nothing says so rather than offering good news', () => {
  assert.deepEqual(statusLine(input({ editing: true, dirty: false })), {
    tone: 'neutral',
    text: 'No changes yet.',
  });
  // A pool being created has always changed.
  assert.notEqual(statusLine(input({ editing: false, dirty: false })).text, 'No changes yet.');
});

test('a controller that did not answer is not reported as agreeing', () => {
  const unreachable = statusLine(input({ unreachable: true, verdict: null }));
  assert.equal(unreachable.tone, 'warning');
  assert.match(unreachable.text, /could not check this pool/);
  assert.deepEqual(statusLine(input({ verdict: null })), {
    tone: 'neutral',
    text: 'Checking with the controller…',
  });
});

test('a refusal the browser did not already say is the controller disagreeing', () => {
  assert.deepEqual(statusLine(input({ refusals: 1 })), {
    tone: 'danger',
    text: 'The controller will not accept this pool yet.',
    action: 'Show',
  });
});

// A pool no host can run is the failure that looks like health, so it is the
// loudest thing the line says once nothing is wrong with the form -- and it
// does not stop the pool being made, because the first pool is made before the
// first agent joins.
test('a pool no host can run says so, and says it is still made', () => {
  const none = statusLine(input({ verdict: verdict({ matching_hosts: 0 }) }));
  assert.equal(none.tone, 'warning');
  assert.match(none.text, /No connected host can run this pool yet/);
  assert.match(none.text, /created anyway/);
  assert.match(
    statusLine(input({ editing: true, verdict: verdict({ matching_hosts: 0 }) })).text,
    /saved anyway/,
  );
  // Before the fleet has been asked a count of none is a blank, not a fact.
  assert.notEqual(
    statusLine(input({ fleetKnown: false, verdict: verdict({ matching_hosts: 0 }) })).tone,
    'warning',
  );
});

test('a pool that can run says how much room it has, in the controller’s own count', () => {
  assert.deepEqual(
    statusLine(input({ verdict: verdict({ matching_hosts: 3, room: { runners: 12 } as never }) })),
    { tone: 'ok', text: 'Room for 12 runners on 3 hosts.' },
  );
  assert.equal(
    statusLine(input({ verdict: verdict({ matching_hosts: 1, room: { runners: 1 } as never }) }))
      .text,
    'Room for 1 runner on 1 host.',
  );
  assert.equal(
    statusLine(input({ verdict: verdict({ matching_hosts: 2 }) })).text,
    '2 connected hosts can run this pool.',
  );
});

test('warnings are counted only when they have nowhere better to be said', () => {
  const rest = {
    code: 'pool.root',
    severity: 'warning',
    title: 'runs as root',
  } as never;
  const room = { code: 'pool.max_above_room', severity: 'warning', title: 'room' } as never;
  const nobody = { code: 'pool.no_matching_hosts', severity: 'warning', title: 'x' } as never;
  const startup = {
    code: 'scheduler.provision_timeout_short',
    severity: 'warning',
    title: 'short',
  } as never;

  const one = verdict({ warnings: [rest, room, nobody, startup] });
  assert.equal(visibleWarnings(one).length, 1);
  assert.equal(statusLine(input({ verdict: one })).text, 'Ready, with a warning to read below.');
  assert.equal(
    statusLine(
      input({
        verdict: verdict({ warnings: [rest, { ...(rest as object), code: 'b' } as never] }),
      }),
    ).text,
    'Ready, with 2 warnings to read below.',
  );
  assert.equal(visibleWarnings(null).length, 0);
});

import assert from 'node:assert/strict';
import { test } from 'node:test';
import {
  delayDuration,
  delaySummary,
  prDelayContext,
  prNumber,
  type PRDelayReport,
} from '../src/lib/jobs/pr-delay';
import { contextPrompt } from '../src/lib/assistant/prompts';
import { retryAfterTime } from '../src/lib/api/client';

const report: PRDelayReport = {
  job_id: 'job_1',
  repository: 'acme/repo',
  installation_id: 'ins_private',
  pull_number: 42,
  window_basis: 'earliest_observed_job',
  result: {
    version: 'v1',
    head_sha: 'pinned',
    target_branch: 'release',
    observed_at: '2026-10-12T12:00:00Z',
    window_start: '2026-10-12T11:00:00Z',
    protection_coverage: 'complete',
    observation_coverage: 'partial',
    state: 'incomplete',
    checks: [],
    last_finishing_check_id: '',
    ignored_other_heads: 2,
  },
};

test('unknown timing never becomes zero and PR numbers cannot select another route', () => {
  assert.equal(delayDuration(null), 'Unknown');
  assert.notEqual(delayDuration(0), 'Unknown');
  assert.equal(delayDuration(-1), 'Invalid timing');
  for (const bad of ['', '-1', '0', '1.5', '1e2', '42/path', '2147483648'])
    assert.equal(prNumber(bad), null);
  assert.equal(prNumber(' 42 '), 42);
});

test('the shared Eli snapshot retains uncertainty and excludes installation credentials', () => {
  const context = prDelayContext(report);
  assert.equal(context.facts.Head, 'pinned');
  assert.equal(context.facts['Observation coverage'], 'partial');
  assert.match(String(context.facts.Verdict), /incomplete/);
  assert.match(context.question!, /Do not fetch another/);
  assert.match(contextPrompt(context), /fresh diagnostic requires a new explicit request/);
  assert.equal(contextPrompt(context).includes('use them to check the current state'), false);
  assert.equal(JSON.stringify(context).includes('ins_private'), false);
  assert.match(
    delaySummary({ ...report, result: { ...report.result, state: 'superseded' } }),
    /head changed/,
  );
});

test('Retry-After admits another manual read only after the server hold', () => {
  const now = Date.parse('2026-10-12T12:00:00Z');
  assert.equal(retryAfterTime('60', now), now + 60_000);
  assert.equal(retryAfterTime('Mon, 12 Oct 2026 12:01:00 GMT', now), now + 60_000);
  for (const value of [null, '', 'nonsense', '-1', '0', 'Mon, 12 Oct 2026 11:00:00 GMT'])
    assert.equal(retryAfterTime(value, now), undefined);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  connectionIntro,
  isPrivate,
  lostConnection,
  reconnectSteps,
} from '../src/lib/providers/private-connection.ts';
import type { ProviderCheck } from '../src/lib/api/types.ts';

const check = (reachable: boolean): ProviderCheck =>
  ({ reachable, findings: [] }) as unknown as ProviderCheck;

// The guidance is private-provider business: a direct provider's page has
// nothing to say about gateways, and must never show what it has no need of.
test('only a provider reached through a gateway shows connection guidance', () => {
  assert.equal(isPrivate({ connection: 'tailcat' }), true);
  assert.equal(isPrivate({ connection: 'direct' }), false);
  assert.equal(isPrivate({}), false);
  assert.equal(isPrivate({ connection: undefined }), false);
});

test('a lost connection is what the last check says, and only that', () => {
  assert.equal(lostConnection(check(false)), true);
  assert.equal(lostConnection(check(true)), false);
  // No check yet, or one from a build that kept no report: nothing is lost
  // until something says so.
  assert.equal(lostConnection(null), false);
  assert.equal(lostConnection(undefined), false);
});

test('the steps ask nobody to reconnect and name commands to run elsewhere', () => {
  const steps = reconnectSteps();
  assert.ok(steps.length >= 4);
  for (const step of steps) {
    // Reconnection is automatic at both ends; a step that asked the operator
    // to do it would be the wrong instruction next to a recovery already
    // under way.
    assert.doesNotMatch(step, /reconnect|restart zoomies/i);
  }
  const joined = steps.join(' ');
  // The commands are on the provider's machine, so they arrive as commands a
  // person can run there, not as descriptions of one.
  assert.match(joined, /systemctl status 'zoomies-proxmox-\*'/);
  assert.match(joined, /journalctl -u 'zoomies-proxmox-\*'/);
  // Reinstalling the machine is the case rerunning setup exists for; the
  // stored credential surviving it is the reason to say so.
  assert.match(joined, /reinstalled/);
  assert.match(joined, /credential/);
});

test('the intro says what the connection is without borrowing the error', () => {
  assert.doesNotMatch(connectionIntro, /could not|unreachable|cannot/);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  carriedOver,
  covers,
  fromServer,
  spentKeys,
  type Dismissals,
} from '../src/lib/problems/dismissals.ts';
import type { Problem } from '../src/lib/api/types.ts';

const NOW = Date.parse('2026-10-05T12:00:00Z');
const iso = (offsetMs: number) => new Date(NOW + offsetMs).toISOString();
const HOUR = 60 * 60_000;

const problem = (over: Partial<Problem> = {}): Problem => ({
  code: 'pool.no_capacity',
  severity: 'warning',
  title: 'pool zoomies-linux-x64 has 6 jobs waiting for a host with room',
  target_kind: 'pool',
  target_id: 'pool_x64',
  audience: 'fleet',
  ...over,
});

// The bug this guards: a queue drains for one reconciliation pass, the
// controller stops reporting pool.no_capacity, and the sweep treated that as
// "resolved" and forgot a 24 hour snooze. The fault came back and so did the
// banner, hours early.
test('a snooze outlives the problem clearing for a pass', () => {
  const held: Dismissals = {
    'pool.no_capacity|pool|pool_x64||': { severity: 'warning', at: iso(0), until: iso(24 * HOUR) },
    'type:pool.no_capacity': { severity: 'warning', at: iso(0), until: iso(24 * HOUR) },
  };
  assert.deepEqual(spentKeys(held, new Set(), NOW + HOUR), []);
});

test('a snooze of a whole kind survives with no problem of that kind reported', () => {
  const held: Dismissals = {
    'type:pool.no_capacity': { severity: 'warning', at: iso(0), until: iso(4 * HOUR) },
  };
  assert.deepEqual(spentKeys(held, new Set(['host.unhealthy|host|h1||']), NOW + HOUR), []);
});

test('a snooze is spent when its own clock runs out, and not before', () => {
  const held: Dismissals = {
    a: { severity: 'info', at: iso(0), until: iso(HOUR) },
  };
  assert.deepEqual(spentKeys(held, new Set(['a']), NOW + HOUR - 1), []);
  assert.deepEqual(spentKeys(held, new Set(['a']), NOW + HOUR), ['a']);
});

test('a plain dismissal is still forgotten once the problem stops being reported', () => {
  const held: Dismissals = {
    a: { severity: 'info', at: iso(0) },
    b: { severity: 'info', at: iso(0) },
  };
  assert.deepEqual(spentKeys(held, new Set(['a']), NOW), ['b']);
});

test('a dismissal does not cover a problem that has become worse', () => {
  const record = { severity: 'warning' as const, at: iso(0), until: iso(HOUR) };
  assert.equal(covers(record, problem({ severity: 'warning' }), NOW), true);
  assert.equal(covers(record, problem({ severity: 'info' }), NOW), true);
  assert.equal(covers(record, problem({ severity: 'error' }), NOW), false);
});

test('an expired snooze covers nothing', () => {
  const record = { severity: 'warning' as const, at: iso(-2 * HOUR), until: iso(-HOUR) };
  assert.equal(covers(record, problem(), NOW), false);
});

test('what the server returns is adopted, and a snooze the clock says is over is not', () => {
  const got = fromServer(
    [
      { key: 'live', severity: 'warning', at: iso(0), until: iso(HOUR) },
      { key: 'stale', severity: 'warning', at: iso(-2 * HOUR), until: iso(-HOUR) },
      { key: 'plain', severity: 'info', at: iso(0) },
    ],
    NOW,
  );
  assert.deepEqual(Object.keys(got).sort(), ['live', 'plain']);
  assert.equal(got.plain?.until, undefined);
});

// A decision already on the account was made on purpose and more recently than
// whatever has sat in a browser, so uploading the old copy over it would undo it.
test('carrying a browser copy up never overwrites what the account already holds', () => {
  const local: Dismissals = {
    held: { severity: 'info', at: iso(-HOUR) },
    fresh: { severity: 'warning', at: iso(-HOUR), until: iso(HOUR) },
    spent: { severity: 'warning', at: iso(-3 * HOUR), until: iso(-HOUR) },
  };
  const remote: Dismissals = { held: { severity: 'error', at: iso(0), until: iso(HOUR) } };
  assert.deepEqual(
    carriedOver(local, remote, NOW).map((d) => d.key),
    ['fresh'],
  );
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { problemKey } from '../src/lib/problems/identity.ts';
import type { Problem } from '../src/lib/api/types.ts';

const problem = (over: Partial<Problem> = {}): Problem => ({
  code: 'pool.no_capacity',
  severity: 'error',
  title: 'pool zoomies-linux-x64 has 21 jobs waiting and nowhere to run them',
  target_kind: 'pool',
  target_id: 'pool_x64',
  audience: 'fleet',
  ...over,
});

// The count in the title moves every reconciliation pass. If it were part of
// the key, a snooze made at 21 jobs would stop covering the same outage the
// moment a 22nd job queued -- the exact nagging the dismissals exist to stop.
test('a pool.no_capacity problem keeps its identity as the queue length changes', () => {
  const before = problemKey(
    problem({ title: 'pool zoomies-linux-x64 has 21 jobs waiting and nowhere to run them' }),
  );
  const after = problemKey(
    problem({ title: 'pool zoomies-linux-x64 has 22 jobs waiting and nowhere to run them' }),
  );
  assert.equal(before, after);
});

// pool.dangerous is raised once per weakened setting on the same pool, so two
// of them share a code and a target and the title is the only thing telling
// them apart -- folding the title out of the key entirely would collapse
// "host docker socket mounted" and "runners execute as root" into one problem.
test('two pool.dangerous problems on the same pool keep separate identities', () => {
  const socket = problemKey(
    problem({
      code: 'pool.dangerous',
      title: 'pool spaniel: host docker socket mounted: any job on this pool can become root',
    }),
  );
  const root = problemKey(
    problem({
      code: 'pool.dangerous',
      title: 'pool spaniel: runners execute as root inside the container',
    }),
  );
  assert.notEqual(socket, root);
});

// A host with both a docker and a podman daemon that cannot apply limits (or
// cannot mount the shared folder) raises the same code twice against one host.
// The backend in the title is all that separates them, so muting docker's must
// not mute podman's.
test('the same host problem raised for two backends keeps separate identities', () => {
  for (const code of ['host.limits_unenforceable', 'host.shared_folder_unmounted']) {
    const docker = problemKey(
      problem({ code, target_kind: 'host', target_id: 'host_a', title: 'a docker problem' }),
    );
    const podman = problemKey(
      problem({ code, target_kind: 'host', target_id: 'host_a', title: 'a podman problem' }),
    );
    assert.notEqual(docker, podman, code);
  }
});

test('two problems for different pools never collide regardless of code', () => {
  const first = problemKey(problem({ target_id: 'pool_x64' }));
  const second = problemKey(problem({ target_id: 'pool_arm64' }));
  assert.notEqual(first, second);
});

// A snooze of "all like this" has to cover a pool that runs short after the
// snooze was made, so its key is the code alone -- and it must never be
// mistaken for one problem's key, or restoring one would lift the other.
test('every problem of one code shares a type key that no problem key equals', async () => {
  const { problemTypeKey } = await import('../src/lib/problems/identity.ts');
  const a = problem({ target_id: 'pool_x64' });
  const b = problem({ target_id: 'pool_arm64', title: 'another title entirely' });
  assert.equal(problemTypeKey(a), problemTypeKey(b));
  assert.notEqual(problemTypeKey(a), problemTypeKey(problem({ code: 'host.unhealthy' })));
  assert.notEqual(problemTypeKey(a), problemKey(a));
});

