});

/**
 * The provisioning controls the Queue page and the Workflows page share: which
 * of Run now, Pause, Resume and Delete a job's row offers, and why each is
 * refused when it is. Three pages read this, so a refusal that is right here
 * is right on all of them, and one that is wrong is wrong three times over.
 *
 * `status.ts` imports Lucide components, which cannot load outside a browser;
 * the hook below swaps them for plain functions, as the other tests do.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { registerHooks } from 'node:module';

const LUCIDE = 'zoomies-test:lucide-stub';
// Both files' icons: the actions' glyphs are the buttons' own, and the state
// map deliberately shares none of them, so neither list covers the other.
const iconNames = [
  ...new Set(
    ['../src/lib/status.ts', '../src/lib/jobs/provisioning.ts'].flatMap((file) =>
      (
        /import\s*\{([^}]*)\}\s*from\s*'@lucide\/svelte'/.exec(
          readFileSync(new URL(file, import.meta.url), 'utf8'),
        )?.[1] ?? ''
      )
        .split(',')
        .map((name) => name.trim())
        .filter((name) => name !== ''),
    ),
  ),
];

registerHooks({
  resolve(specifier, context, next) {
    if (specifier === '@lucide/svelte')
      return { url: LUCIDE, format: 'module', shortCircuit: true };
    return next(specifier, context);
  },
  load(url, context, next) {
    if (url === LUCIDE)
      return {
        format: 'module',
        shortCircuit: true,
        source: iconNames.map((name) => `export function ${name}() {}`).join('\n'),
      };
    return next(url, context);
  },
});

const {
  jobProvisioningActions,
  PROVISIONING_ACTIONS,
  PROVISIONING_IN_FORCE,
  provisioningStatus,
  provisioningUnavailable,
  RUN_PROVISIONING_ACTIONS,
} = await import('../src/lib/jobs/provisioning.ts');

const queued = { state: 'queued' as const, matched: true, hosted: false };

test('a queued job offers every action but the one already in force', () => {
  const noop = () => {};
  const on = (job: Parameters<typeof jobProvisioningActions>[0]) =>
    Object.fromEntries(jobProvisioningActions(job, noop).map((a) => [a.id, a])) as Record<
      'run_now' | 'pause' | 'resume' | 'delete',
      ReturnType<typeof jobProvisioningActions>[number]
    >;

  const ready = on(queued);
  assert.equal(ready.resume.disabled, true);
  assert.equal(ready.resume.reason, PROVISIONING_IN_FORCE.resume);
  for (const id of ['run_now', 'pause', 'delete'] as const) {
    assert.equal(ready[id].disabled, false, id);
  }

  const expedited = on({ ...queued, provision_now: true });
  assert.equal(expedited.run_now.disabled, true);
  assert.equal(expedited.resume.disabled, false);

  const paused = on({ ...queued, provisioning: 'paused' });
  assert.equal(paused.pause.disabled, true);
  assert.equal(paused.pause.reason, PROVISIONING_IN_FORCE.pause);
  // Run now on a paused job resumes it as well, so it is offered.
  assert.equal(paused.run_now.disabled, false);

  const removed = on({ ...queued, provisioning: 'deleted' });
  assert.equal(removed.delete.disabled, true);
  assert.equal(removed.resume.disabled, false);
});

test('a job that raises no demand refuses every action with the same reason', () => {
  // Nothing to hold once something has started it, and nothing here to hurry
  // for a job whose labels all name somebody else's runners. The refusal is
  // one sentence on every button rather than four different ones.
  for (const job of [
    { ...queued, state: 'in_progress' as const },
    { ...queued, state: 'completed' as const },
    { ...queued, state: 'waiting' as const },
    { ...queued, matched: false, hosted: true },
    { ...queued, cancel_requested_at: '2026-09-20T12:00:00Z' },
  ]) {
    const why = provisioningUnavailable(job);
    assert.ok(why, JSON.stringify(job));
    for (const a of jobProvisioningActions(job, () => {})) {
      assert.equal(a.disabled, true, `${a.id} on ${JSON.stringify(job)}`);
      assert.equal(a.reason, why);
    }
  }
  assert.equal(provisioningUnavailable(queued), undefined);
});

test('the run offers the Queue page’s actions less removal, in its order', () => {
  // A removal is a decision about one job, made where the Removed view can
  // undo it. The other three keep the Queue page's order, so an operator's
  // hand finds Pause in the same place on either page.
  assert.deepEqual(
    RUN_PROVISIONING_ACTIONS.map((a) => a.id),
    PROVISIONING_ACTIONS.map((a) => a.id).filter((id) => id !== 'delete'),
  );
  assert.deepEqual(
    PROVISIONING_ACTIONS.map((a) => a.id),
    ['run_now', 'pause', 'resume', 'delete'],
  );
});

test('the status is read the way the Queue page reads it', () => {
  assert.equal(provisioningStatus({}), 'ready');
  assert.equal(provisioningStatus({ provision_now: true }), 'expedited');
  assert.equal(provisioningStatus({ provisioning: 'paused', provision_now: true }), 'paused');
  assert.equal(provisioningStatus({ provisioning: 'deleted' }), 'deleted');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  DEFAULT_ASK,
  capacityCeiling,
  diskNotches,
  memoryNotches,
  overcommit,
  recommendedCapacity,
  recommendedReserveCores,
  recommendedReserveDiskMb,
  recommendedReserveMemoryMb,
  runnerAsk,
} from '../src/lib/hosts/recommend.ts';

test('the runner ask is the largest enabled pool asks for, or the default', () => {
  assert.deepEqual(runnerAsk([]), DEFAULT_ASK);
  const ask = runnerAsk([
    { enabled: true, resources: { cpus: 2, memory_mb: 4096 } },
    { enabled: true, resources: { cpus: 4, memory_mb: 2048 } },
    { enabled: false, resources: { cpus: 16, memory_mb: 65536 } },
  ]);
  assert.deepEqual(ask, { cpus: 4, memoryMb: 4096, source: 'pools', pair: false });
});

// A docker-in-docker slot is two containers with the same limits where the
// pool typed those limits, so the ask is twice its figures. A pool that leaves
// its size to the host asks for one runner's worth: its runner and its daemon
// split the slot they land in rather than taking two.
test('a docker-in-docker pool asks for both of its containers when it sized them', () => {
  assert.deepEqual(runnerAsk([{ enabled: true, docker_mode: 'dind', resources: {} }]), {
    cpus: 2,
    memoryMb: 4096,
    source: 'default',
    pair: false,
  });
  assert.deepEqual(
    runnerAsk([{ enabled: true, docker_mode: 'dind', resources: { cpus: 2, memory_mb: 4096 } }]),
    { cpus: 4, memoryMb: 8192, source: 'pools', pair: true },
  );
  // A dind pool that is not the largest ask leaves the figure alone, and
  // says nothing about a pair: this function has no host in hand, so it
  // cannot know whether that pool places on the machine being adjusted.
  assert.deepEqual(
    runnerAsk([
      { enabled: true, resources: { cpus: 2, memory_mb: 4096 } },
      { enabled: true, docker_mode: 'dind', resources: {} },
    ]),
    { cpus: 2, memoryMb: 4096, source: 'pools', pair: false },
  );
  // Twelve cores less a core held back is room for two pairs at four cores
  // each, which is what a pool that typed two cores asks for here.
  assert.equal(
    recommendedCapacity(
      { cpus: 12, memoryMb: 32768 },
      1,
      3072,
      runnerAsk([{ enabled: true, docker_mode: 'dind', resources: { cpus: 2, memory_mb: 4096 } }]),
    ),
    2,
  );
  // The same fleet with that pool sized by its host has room for five: the
  // pair shares a slot, so a slot is one runner.
  assert.equal(
    recommendedCapacity(
      { cpus: 12, memoryMb: 32768 },
      1,
      3072,
      runnerAsk([{ enabled: true, docker_mode: 'dind', resources: {} }]),
    ),
    5,
  );
});

test('the reserve keeps a core and a tenth of memory, and never the whole machine', () => {
  assert.equal(recommendedReserveCores(1), 0);
  assert.equal(recommendedReserveCores(2), 1);
  assert.equal(recommendedReserveCores(16), 1);
  assert.equal(recommendedReserveCores(48), 3);
  assert.equal(recommendedReserveMemoryMb(1024), 0);
  assert.equal(recommendedReserveMemoryMb(1536), 1024);
  assert.equal(recommendedReserveMemoryMb(32768), 3072);
  // A tenth of sixteen gigabytes is between two notches; the next one up.
  assert.equal(recommendedReserveMemoryMb(16384), 2048);
  assert.equal(recommendedReserveMemoryMb(262144), 8192);
});

test('the disk reserve is a tenth of the filesystem, on a notch the slider stops at', () => {
  // Nothing worth holding back on a disk barely larger than the floor.
  assert.equal(recommendedReserveDiskMb(4096), 0);
  assert.deepEqual(diskNotches(4096), [0]);
  // 100 GB: a tenth is 10 GB, and 8 GB is the notch nearest it.
  assert.equal(recommendedReserveDiskMb(102_400), 8192);
  // Capped, so a terabyte does not hold back a hundred gigabytes.
  assert.equal(recommendedReserveDiskMb(1_048_576), 65_536);
  // The notches double from the scheduler's own floor, and never reach the
  // whole disk -- a reserve that leaves nothing to place on is refused.
  assert.deepEqual(diskNotches(65_536), [0, 2048, 4096, 8192, 16_384, 32_768]);
  assert.ok((diskNotches(65_536).at(-1) ?? 0) < 65_536);
});

test('capacity is what fits after the reserve, on the tighter of CPU and memory', () => {
  const host = { cpus: 16, memoryMb: 32768 };
  // 15 cores / 2 = 7; 29.7 GB / 4 GB = 7.
  assert.equal(recommendedCapacity(host, 1, 3072, DEFAULT_ASK), 7);
  // Memory is the tighter one here.
  assert.equal(
    recommendedCapacity(host, 1, 3072, { cpus: 1, memoryMb: 8192, source: 'pools', pair: false }),
    3,
  );
  // A host that has said nothing about itself gets no recommendation.
  assert.equal(recommendedCapacity({ cpus: 0, memoryMb: 0 }, 0, 0, DEFAULT_ASK), 0);
  // Never zero on a machine, however small: one runner is what a host is for.
  assert.equal(recommendedCapacity({ cpus: 2, memoryMb: 2048 }, 1, 1024, DEFAULT_ASK), 1);
});

test('the sliders reach far enough to include what is set today', () => {
  assert.equal(capacityCeiling({ cpus: 16, memoryMb: 32768 }, 7, 6), 16);
  assert.equal(capacityCeiling({ cpus: 16, memoryMb: 32768 }, 7, 20), 20);
  assert.equal(capacityCeiling({ cpus: 0, memoryMb: 0 }, 0, 3), 8);
  assert.deepEqual(memoryNotches(4096), [0, 512, 1024, 2048, 3072]);
  assert.equal(memoryNotches(65536).at(-1), 49152);
});

test('overcommit says how far past the room the runners would reach', () => {
  const host = { cpus: 8, memoryMb: 16384 };
  assert.deepEqual(overcommit(host, 3, 1, 1024, DEFAULT_ASK), { cpus: 0, memoryMb: 0 });
  assert.deepEqual(overcommit(host, 6, 1, 1024, DEFAULT_ASK), { cpus: 5, memoryMb: 9216 });
});

// Lets the unit tests import the app's modules as the app does.
//
// Vite resolves `import { x } from '../format'` to format.ts; Node's module
// loader does not, and would otherwise confine the unit tests to modules that
// import nothing. The hook tries the `.ts` spelling of any extensionless
// relative import first, and falls back to Node's own resolution for anything
// else, so a bare package import is untouched.
import { register } from 'node:module';

register('./resolve.mjs', import.meta.url);

import assert from 'node:assert/strict';
import test from 'node:test';
import {
  clampCeiling,
  poolRenting,
  refusalText,
  rentingNotice,
  settingsFor,
} from '../src/lib/providers/renting.ts';
import type { PoolRenting, ProviderRenting } from '../src/lib/api/types.ts';

const base: ProviderRenting = {
  state: 'on',
  summary: '',
  enabled: false,
  paused: false,
  max_machines: 0,
  owned: 0,
  pools: [],
};

function pool(id: string, state: PoolRenting['state']): PoolRenting {
  return {
    pool_id: id,
    pool_name: id,
    state,
    summary: `${id} is ${state}`,
    queued: 1,
    short: 1,
    machines: 0,
  };
}

test('renting off asks an administrator for one click that sets both settings', () => {
  const n = rentingNotice(
    { ...base, state: 'off', summary: 'S', fix: 'F', suggested_max_machines: 2 },
    true,
  );
  assert.equal(n?.title, 'Renting is switched off');
  assert.equal(n?.body, 'S');
  assert.equal(n?.fix, 'F');
  assert.equal(n?.action?.label, 'Turn on renting');
  assert.deepEqual(settingsFor(n!, 2), { 'provider.enabled': true, 'provider.max_machines': 2 });
});

test('someone who cannot change settings is told who can', () => {
  const n = rentingNotice({ ...base, state: 'off' }, false);
  assert.equal(n?.action, null);
  assert.equal(n?.hint, 'An administrator can change this under Settings, Rent machines.');
});

test('no ceiling offers the ceiling alone', () => {
  const pools = [pool('a', 'ceiling'), pool('b', 'waiting')];
  const n = rentingNotice(
    { ...base, state: 'no_ceiling', fix: 'Set a ceiling.', suggested_max_machines: 2, pools },
    true,
  );
  assert.equal(n?.title, 'Renting is on, but the fleet may rent no machines');
  assert.equal(n?.fix, 'Set a ceiling.');
  assert.deepEqual(
    n?.pools.map((p) => p.pool_id),
    ['a'],
  );
  assert.equal(n?.action?.label, 'Allow 2 machines');
  assert.deepEqual(settingsFor(n!, 2), { 'provider.max_machines': 2 });
  assert.equal(
    rentingNotice({ ...base, state: 'no_ceiling' }, false)?.hint,
    'An administrator can change this under Settings, Machines the fleet may rent.',
  );
});

test('a suggestion of one machine is worded in the singular', () => {
  const n = rentingNotice({ ...base, state: 'no_ceiling', suggested_max_machines: 1 }, true);
  assert.equal(n?.action?.label, 'Allow 1 machine');
});

test('a missing suggestion falls back to one machine', () => {
  const n = rentingNotice({ ...base, state: 'no_ceiling' }, true);
  assert.equal(n?.action?.ceiling, 1);
  assert.equal(n?.action?.label, 'Allow 1 machine');
});

test('there is nothing to say when nothing is wrong', () => {
  for (const state of ['none', 'on'] as const)
    assert.equal(rentingNotice({ ...base, state }, true), null);
  assert.equal(rentingNotice(null, true), null);
});

test('only pools renting cannot help are listed', () => {
  const pools = [
    pool('a', 'off'),
    pool('b', 'ceiling'),
    pool('c', 'waiting'),
    pool('d', 'renting'),
    pool('e', 'held'),
  ];
