test('a ceiling is a whole number of at least one', () => {
  assert.equal(clampCeiling(0, 2), 2);
  assert.equal(clampCeiling(Number.NaN, 2), 2);
  assert.equal(clampCeiling(3.9, 2), 3);
  assert.equal(clampCeiling(Infinity, 2), 2);
