import { test } from 'node:test';
import assert from 'node:assert/strict';
import { guidanceFor } from '../src/lib/repairs/guidance.ts';
import { repair } from './repair-fixtures.ts';

// A pause written as two hyphens between spaces is not a dash either; the check is built
// from parts so this file does not carry the very thing it forbids.
const SPACED_DOUBLE_HYPHEN = [' ', '-', '-', ' '].join('');

const failed = (code: string) => guidanceFor({ state: 'failed', details: { failure_code: code } });
const text = (g: { headline: string; steps: string[] }) => [g.headline, ...g.steps].join(' ');

// "What to try next" is the part of a failed attempt a person reads and acts on,
// so each failure code says what happened in one line and at most three things
// to do about it.
test('every failure code says what happened and gives at most three things to do', () => {
  for (const code of [
    'unsupported_fix',
    'context_limit',
    'source_unavailable',
    'provider_unavailable',
    'provider_billing',
    'rate_limited',
    'provider_credentials',
    'output_limit',
    'setup_needed',
  ]) {
    const g = failed(code);
    assert.notEqual(g.headline, '', `${code} has no headline`);
    assert.ok(g.steps.length >= 1 && g.steps.length <= 3, `${code} has ${g.steps.length} steps`);
  }
});

test('an unsupported fix starts with a note that points at the file or the test', () => {
  const g = failed('unsupported_fix');
  assert.ok(g.steps[0]?.startsWith('Add a note'), g.steps[0] ?? 'no steps');
  assert.match(text(g), /error output/i);
});

test('each code names the one thing that fixes it', () => {
  assert.match(text(failed('context_limit')), /too big/i);
  assert.match(text(failed('context_limit')), /file or the test/i);
  assert.match(text(failed('source_unavailable')), /Contents permission/);
  assert.match(text(failed('source_unavailable')), /100 files/);
  assert.match(text(failed('provider_unavailable')), /Eli settings/);
  assert.match(text(failed('provider_billing')), /cannot pay/i);
  assert.match(text(failed('provider_billing')), /credit/i);
  assert.match(text(failed('provider_billing')), /another provider/i);
  assert.match(text(failed('rate_limited')), /quota/i);
  assert.match(text(failed('provider_credentials')), /key/i);
  assert.match(text(failed('provider_credentials')), /Eli settings/);
  assert.match(text(failed('output_limit')), /reasoning effort/i);
  assert.match(text(failed('setup_needed')), /repair setup/i);
  assert.match(text(failed('setup_needed')), /readiness/i);
});

// An attempt that pushed a commit and still failed its checks has no failure
// code, only a terminal state, and the advice is about the commit it made.
test('a repair with no code is read from its state', () => {
  const failedChecks = guidanceFor(repair({ state: 'checks_failed' }));
  assert.match(text(failedChecks), /commit/i);
  assert.match(text(failedChecks), /new head|next attempt|another attempt/i);
  for (const state of ['interrupted', 'unverified', 'superseded', 'blocked']) {
    const g = guidanceFor(repair({ state }));
    assert.notEqual(g.headline, '', `${state} has no headline`);
    assert.equal(g.steps.length, 1, `${state} should say the one thing to check`);
  }
});

test('a code outranks the state it arrived in', () => {
  assert.match(
    text(guidanceFor(repair({ state: 'failed', details: { failure_code: 'rate_limited' } }))),
    /quota/i,
  );
  assert.match(
    text(guidanceFor(repair({ state: 'blocked', details: { failure_code: 'setup_needed' } }))),
    /repair setup/i,
  );
});

// A controller newer than this build can invent a code. The person still gets
// the advice that is true of any failed repair rather than a blank card.
test('an unknown code, or a failure with none, falls back to the unsupported-fix advice', () => {
  const unsupported = failed('unsupported_fix');
  assert.deepEqual(failed('something_new'), unsupported);
  assert.deepEqual(guidanceFor(repair({ state: 'failed' })), unsupported);
  assert.deepEqual(guidanceFor({ state: 'failed' }), unsupported);
});

// The prose in this repository has no em dash and no double hyphen standing in
// for one, and the copy here is the part a person reads at the worst moment.
test('the copy follows the repository voice', () => {
  const codes = [
    'unsupported_fix',
    'context_limit',
    'source_unavailable',
    'provider_unavailable',
    'provider_billing',
    'rate_limited',
    'provider_credentials',
    'output_limit',
    'setup_needed',
  ];
  const states = ['checks_failed', 'interrupted', 'unverified', 'superseded', 'blocked'];
  const all = [...codes.map(failed), ...states.map((state) => guidanceFor(repair({ state })))];
  for (const g of all) {
    const copy = text(g);
    assert.ok(!copy.includes('\u2014'), `an em dash in: ${copy}`);
    assert.ok(!copy.includes(SPACED_DOUBLE_HYPHEN), `a double hyphen in: ${copy}`);
    for (const american of ['behavior', 'authoriz', 'organiz', 'utiliz']) {
      assert.ok(!copy.toLowerCase().includes(american), `${american} in: ${copy}`);
    }
  }
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  BULK_LIMIT,
  NO_REPAIR_FILTERS,
  batches,
  clearConsequences,
  clearReport,
  clearSummary,
  filtered,
  isActive,
  listQuery,
  offsetAfterClear,
  selectionQuery,
  stateLabel,
} from '../src/lib/repairs/history';

// The server treats a missing parameter as "no filter" and a spelled-out
// default as a value it must recognise, so the page leaves the defaults out
// rather than send `group=all` and depend on the server agreeing about it.
test('the list query leaves out the defaults and trims the repository', () => {
  assert.deepEqual(listQuery({ group: 'all', repo: ' site ', trigger: 'any' }, 50, 0), {
    repo: 'site',
    limit: 50,
    offset: 0,
  });
  assert.deepEqual(listQuery(NO_REPAIR_FILTERS, 25, 75), { limit: 25, offset: 75 });
  assert.deepEqual(listQuery({ group: 'attention', repo: '', trigger: 'automatic' }, 100, 100), {
    group: 'attention',
    trigger: 'automatic',
    limit: 100,
    offset: 100,
  });
});

// A box holding only spaces is not a filter; sending repo=%20%20 would match
// nothing and leave an operator looking at an empty history with no idea why.
test('a repository box holding only spaces is not sent', () => {
  assert.deepEqual(listQuery({ group: 'all', repo: '   ', trigger: 'any' }, 50, 0), {
    limit: 50,
    offset: 0,
  });
});

// The selection endpoint takes the same filters as the list and nothing about
// paging, because a select-all means everything the filters match.
test('the selection query carries the filters and no paging', () => {
  assert.deepEqual(selectionQuery(NO_REPAIR_FILTERS), {});
  assert.deepEqual(selectionQuery({ group: 'passed', repo: ' widgets', trigger: 'requested' }), {
    group: 'passed',
    repo: 'widgets',
    trigger: 'requested',
  });
});

// "Filtered" decides between "No repairs yet" and "No repairs match these
// filters", which are different facts that an operator acts on differently.
test('a filter counts as set when any of the three is away from its default', () => {
  assert.equal(filtered(NO_REPAIR_FILTERS), false);
  assert.equal(filtered({ ...NO_REPAIR_FILTERS, group: 'active' }), true);
  assert.equal(filtered({ ...NO_REPAIR_FILTERS, repo: 'site' }), true);
  assert.equal(filtered({ ...NO_REPAIR_FILTERS, trigger: 'requested' }), true);
  assert.equal(filtered({ ...NO_REPAIR_FILTERS, repo: '  ' }), false);
});

// These are the states a repair cannot be cleared or retried from, so the set
// must match the server's idea of in progress exactly.
test('a repair is in progress in exactly the queued, working and checking states', () => {
  for (const state of ['queued', 'working', 'checking']) assert.equal(isActive(state), true);
  for (const state of [
    'succeeded',
    'checks_failed',
    'interrupted',
    'unverified',
    'superseded',
    'blocked',
    'failed',
    '',
    'something_new',
  ])
    assert.equal(isActive(state), false, state);
});

test('a state reads as a phrase and an unknown one comes back as it was given', () => {
  assert.equal(stateLabel('checks_failed'), 'Checks failed');
  assert.equal(stateLabel('working'), 'Investigating');
  assert.equal(stateLabel('a_state_from_a_newer_controller'), 'a_state_from_a_newer_controller');
});

// After a clear the page the operator was on may no longer exist. Stepping
// back to the last page that still has rows keeps them looking at repairs
// rather than at an empty list beside a total that says there are some.
test('after a clear the offset steps back only when its page would be empty', () => {
  // 102 matched, 1 cleared: 101 remain, and the page starting at 100 still has a row.
  assert.equal(offsetAfterClear(100, 50, 102, 1), 100);
  // 101 matched, 1 cleared: 100 remain, so the page starting at 100 is empty.
  assert.equal(offsetAfterClear(100, 50, 101, 1), 50);
  assert.equal(offsetAfterClear(100, 50, 101, 2), 50);
  // Everything cleared: the first page, never a negative offset.
  assert.equal(offsetAfterClear(0, 50, 3, 3), 0);
  assert.equal(offsetAfterClear(50, 50, 51, 51), 0);
  // Clearing more than the total says is as good as clearing all of it.
  assert.equal(offsetAfterClear(100, 50, 101, 500), 0);
});

// The bar says how many were cleared and the disclosure says which were not and
// why, so the order of the skipped list is the order the operator chose in.
test('a clear report counts what was cleared and lists the rest with their reasons in order', () => {
  assert.deepEqual(
    clearReport([
      { id: 'rep-1', ok: true },
      { id: 'rep-2', ok: false, error: 'still running' },
      { id: 'rep-3', ok: true },
      { id: 'rep-4', ok: false, error: 'not found' },
    ]),
    {
      cleared: 2,
      skipped: [
        { id: 'rep-2', error: 'still running' },
        { id: 'rep-4', error: 'not found' },
      ],
    },
  );
  assert.deepEqual(clearReport([]), { cleared: 0, skipped: [] });
});

// A refusal with no message would otherwise be listed as a bare id and leave an
// operator wondering what was wrong with it.
test('a refusal that carries no reason still says that it was not cleared', () => {
  assert.deepEqual(clearReport([{ id: 'rep-9', ok: false }]).skipped, [
    { id: 'rep-9', error: 'not cleared' },
  ]);
});

// The dialog is the only place an operator is told what clearing leaves
// untouched, so its sentences are held here rather than only in markup. After a
// select-all the count is the one thing they cannot see from where they stand:
// most of the repairs are on other pages.
test('the clear confirmation says how many go, that it cannot be undone here, and what stays', () => {
  const kept = [
    "They still count towards each repository's daily limit.",
    'Eli will not repair its own commits from them again.',
  ];
  assert.deepEqual(clearConsequences(35), [
    '35 repairs will stop showing in this list, and this cannot be undone from this page.',
    ...kept,
  ]);
  assert.deepEqual(
    clearConsequences(500)[0],
    '500 repairs will stop showing in this list, and this cannot be undone from this page.',
  );
  // One repair is not "1 repairs".
  assert.deepEqual(clearConsequences(1), [
    '1 repair will stop showing in this list, and this cannot be undone from this page.',
    ...kept,
  ]);
});

// A clear that stops part-way has cleared some and not tried the rest. Saying
// "0 skipped" would leave the repairs it never reached nowhere on the screen.
test('repairs a clear never reached are listed after the refused ones as not attempted', () => {
  assert.deepEqual(
    clearReport(
      [
        { id: 'rep-1', ok: true },
        { id: 'rep-2', ok: false, error: 'still running' },
      ],
      ['rep-8', 'rep-9'],
    ),
    {
      cleared: 1,
      skipped: [
        { id: 'rep-2', error: 'still running' },
        { id: 'rep-8', error: 'not attempted' },
        { id: 'rep-9', error: 'not attempted' },
      ],
    },
  );
  assert.deepEqual(clearReport([{ id: 'rep-1', ok: true }], []).skipped, []);
});

// The bulk route takes 1 to 500 ids and refuses a longer list outright, so a
// selection that has grown past that is sent as several requests.
test('a selection past the bulk limit is cut into requests the route accepts', () => {
  assert.equal(BULK_LIMIT, 500);
  const ids = Array.from({ length: 1201 }, (_, i) => `rep-${i}`);
  const parts = batches(ids, BULK_LIMIT);
  assert.deepEqual(
    parts.map((part) => part.length),
    [500, 500, 201],
  );
  assert.deepEqual(parts.flat(), ids);
  assert.deepEqual(batches(['a'], BULK_LIMIT), [['a']]);
  assert.deepEqual(batches([], BULK_LIMIT), []);
});

test('the summary of a clear counts what was cleared and what was skipped', () => {
  assert.equal(clearSummary(1, 0), '1 repair cleared from the history');
  assert.equal(clearSummary(2, 1), '2 repairs cleared from the history, 1 skipped');
  assert.equal(clearSummary(0, 3), '0 repairs cleared from the history, 3 skipped');
  assert.equal(clearSummary(1500, 1200), '1,500 repairs cleared from the history, 1,200 skipped');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import type { Schemas } from '../src/lib/api/types.ts';
import { offerCases, setupSummary } from '../src/lib/repairs/hub.ts';
import { SHA, failedJob } from './repair-fixtures.ts';

type Offer = Schemas['EliOpportunity'];
type Policy = Schemas['EliRepairPolicy'];
type Settings = Schemas['EliRepairSettings'];

const offer = (over: Partial<Offer> = {}): Offer => ({
  id: 'opp_1',
  repo: 'acme/widgets',
  installation_id: 'ins_1',
  pull_number: 17,
  head_sha: SHA,
  run_id: 482,
  title: 'Retry transient 502s',
  state: 'open',
  created_at: '2026-10-18T09:15:00Z',
  updated_at: '2026-10-18T09:15:00Z',
  ...over,
});

// An offer names its run, and the jobs that failed in it are what the person
// came to decide about, so they are read for the offers all at once. A run id is
// only a key within its repository, and that read asks for several runs and
// several repositories together, so what comes back is sorted by whose it is.
test('an offer’s case holds the jobs of its own run in its own repository and no others', () => {
  const unit = failedJob({ id: 'job_unit', github_job_id: 1, job_name: 'unit' });
  const lint = failedJob({ id: 'job_lint', github_job_id: 2, job_name: 'lint' });
  const otherRun = failedJob({ id: 'job_other', github_run_id: 999, job_name: 'other run' });
  const otherRepo = failedJob({ id: 'job_api', repo: 'acme/api', job_name: 'other repo' });
  const cases = offerCases([offer()], [unit, lint, otherRun, otherRepo]);

  const view = cases['opp_1']!;
  assert.deepEqual(
    view.jobs.map((job) => job.name),
    ['unit', 'lint'],
  );
  assert.equal(view.branch, 'fix/retry-502');
  assert.equal(view.runUrl, 'https://github.com/acme/widgets/actions/runs/482');
  assert.equal(view.failedAt, '2026-10-18T09:14:00Z');
});

test('two offers on different runs each get their own jobs', () => {
  const first = failedJob({ job_name: 'first' });
  const second = failedJob({ github_run_id: 500, job_name: 'second', head_branch: 'chore/pin' });
  const cases = offerCases(
    [offer({ id: 'a' }), offer({ id: 'b', run_id: 500, pull_number: 20 })],
    [first, second],
  );
  assert.deepEqual(
    cases['a']!.jobs.map((job) => job.name),
    ['first'],
  );
  assert.deepEqual(
    cases['b']!.jobs.map((job) => job.name),
    ['second'],
  );
  assert.equal(cases['b']!.branch, 'chore/pin');
});

test('repository names are compared without regard to case, as GitHub does', () => {
  const cases = offerCases([offer({ repo: 'Acme/Widgets' })], [failedJob()]);
  assert.equal(cases['opp_1']!.jobs.length, 1);
});

// An offer older than Zoomies' records of the run, or one made without a run, is
// still an offer: it has a case with nothing in it, never a missing one.
test('an offer with no run or no recorded jobs still has a case', () => {
  const cases = offerCases([offer({ id: 'a', run_id: 0 }), offer({ id: 'b' })], []);
  for (const id of ['a', 'b']) {
    assert.deepEqual(cases[id]!.jobs, [], id);
    assert.equal(cases[id]!.repo, 'acme/widgets');
    assert.equal(cases[id]!.pullNumber, 17);
  }
});

const identity = (confirmed: boolean) => ({
  user_id: 'usr_1',
  github_user_id: 42,
  github_login: 'dana',
  confirmed,
});
const policy = (repo: string, over: Partial<Policy> = {}): Policy => ({
  repo,
  installation_id: 'ins_1',
  provider_id: 'prv_1',
  enabled: true,
  automatic: false,
  ask_first: true,
  allow_workflows: false,
  daily_limit: 5,
  ...over,
});
const input = (
  settings: Settings | null,
  over: Partial<Parameters<typeof setupSummary>[0]> = {},
) => ({
  settings,
  userId: 'usr_1',
  admin: false,
  authDisabled: false,
  ...over,
});

// The bar says whether the person can repair, in the one word an operator looks
// for, and what stands in the way in words that name the next thing to do.
test('a linked account that has allowed repairs is ready', () => {
  const summary = setupSummary(input({ identities: [identity(true)], policies: [] }));
  assert.deepEqual(summary, {
    state: 'ready',
    headline: 'Ready to repair',
    account: 'GitHub @dana linked',
    askFirst: null,
