import { test } from 'node:test';
import assert from 'node:assert/strict';
import { REPAIR_TRACK, stageWords, trackIndex, trackSteps } from '../src/lib/repairs/journey.ts';
import { repair } from './repair-fixtures.ts';

const at = (stage: string, state = 'working') => repair({ state, details: { stage } });

// The attempt page draws a running repair as five steps, and the stage the worker
// records is the only thing that says which. The mapping is pinned by the
// worker's own stage ids, so a renamed stage breaks here and not on a person's
// screen.
test('each stage the worker records puts the mark on its step', () => {
  assert.equal(trackIndex(repair({ state: 'queued' })), 0);
  assert.equal(trackIndex(at('evidence')), 1);
  assert.equal(trackIndex(at('source')), 1);
  assert.equal(trackIndex(at('prepare_fix')), 2);
  assert.equal(trackIndex(at('publish')), 3);
  assert.equal(trackIndex(at('watch_ci')), 4);
  assert.equal(trackIndex(repair({ state: 'checking' })), 4);
  // A commit is proof, and a row read between two writes may still say an old stage.
  assert.equal(
    trackIndex(repair({ state: 'working', commit_sha: 'abc1234', details: { stage: 'evidence' } })),
    4,
  );
});

test('the track has the five steps a person waits through, in order', () => {
  assert.deepEqual(
    REPAIR_TRACK.map((step) => step.label),
    [
      'Queued',
      'Reading the failed checks',
      'Preparing the fix',
      'Pushing the commit',
      'Watching CI',
    ],
  );
});

test('the steps before the mark are done, the one it is on is current, and the rest are to come', () => {
  assert.deepEqual(
    trackSteps(at('prepare_fix')).map((step) => step.state),
    ['done', 'done', 'current', 'todo', 'todo'],
  );
  assert.deepEqual(
    trackSteps(repair({ state: 'queued' })).map((step) => step.state),
    ['current', 'todo', 'todo', 'todo', 'todo'],
  );
  assert.deepEqual(
    trackSteps(repair({ state: 'checking', commit_sha: 'abc1234' })).map((step) => step.state),
    ['done', 'done', 'done', 'done', 'current'],
  );
  assert.equal(trackSteps(at('prepare_fix'))[2]?.label, 'Preparing the fix');
});

// The technical details say which stage a repair reached, in the words the track
// uses, and a stage this build has not heard of is still readable.
test('a stage is said in words, and an unknown one is made readable', () => {
  assert.equal(stageWords('evidence'), 'Reading the failed checks');
  assert.equal(stageWords('source'), 'Reading the source');
  assert.equal(stageWords('prepare_fix'), 'Preparing the fix');
  assert.equal(stageWords('publish'), 'Pushing the commit');
  assert.equal(stageWords('watch_ci'), 'Watching CI');
  assert.equal(stageWords('verify_signature'), 'Verify signature');
  assert.equal(stageWords(''), 'Not recorded');
  assert.equal(stageWords(undefined), 'Not recorded');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { changedBlocker, parseTarget, stageOf, targetHref } from '../src/lib/repairs/workspace.ts';
import { allOk, readiness, stoppedAt } from './repair-fixtures.ts';

const query = (href: string) => new URLSearchParams(href.split('?')[1] ?? '');

test('a target is read from the address and written back to it', () => {
  const target = { repo: 'acme/widgets', pull: 17, run: 482, job: 'job_unit', offer: 'opp_1' };
  assert.deepEqual(parseTarget(query(targetHref(target))), target);
  assert.deepEqual(parseTarget(new URLSearchParams('')), {
    repo: '',
    pull: 0,
    run: 0,
    job: '',
    offer: '',
  });
});

test('an address is built without the parts that are empty or zero', () => {
  assert.equal(targetHref({}), '/repairs/new');
  assert.equal(
    targetHref({ repo: 'acme/widgets', pull: 0, run: 0, job: '', offer: '' }),
    '/repairs/new?repo=acme%2Fwidgets',
  );
  assert.equal(
    targetHref({ repo: 'acme/widgets', run: 482, job: 'job_unit' }),
    '/repairs/new?repo=acme%2Fwidgets&run=482&job=job_unit',
  );
  assert.equal(targetHref({ offer: 'opp_1' }), '/repairs/new?offer=opp_1');
});

// The address is the page's input and anybody can type into it. A number that
// is not a positive whole number is no number, and a value never reaches the
// page as anything but a string to look up.
test('what the address says is read defensively', () => {
  for (const bad of ['abc', '-4', '0', '1.5', '1e3', '99999999999999999999', '']) {
    const target = parseTarget(new URLSearchParams({ repo: 'a/b', pull: bad, run: bad }));
    assert.equal(target.pull, 0, `pull=${bad}`);
    assert.equal(target.run, 0, `run=${bad}`);
  }
  assert.equal(parseTarget(new URLSearchParams({ repo: '  acme/widgets  ' })).repo, 'acme/widgets');
  assert.equal(parseTarget(new URLSearchParams({ pull: '17' })).pull, 17);
});

test('a target that changed is told apart from one that is only blocked', () => {
  for (const code of ['fixed', 'closed', 'superseded'] as const) {
    const r = readiness({ ready: false, blockers: [{ code, message: `It is ${code}.` }] });
    assert.deepEqual(changedBlocker(r), { code, message: `It is ${code}.` });
    assert.equal(stageOf(r, false), 'changed');
  }
  const blocked = readiness({
    ready: false,
    blockers: [{ code: 'access', message: 'No write access.' }],
    checks: stoppedAt('access', 'No write access.'),
  });
  assert.equal(changedBlocker(blocked), undefined);
  assert.equal(stageOf(blocked, false), 'blocked');
});

test('the stage follows what readiness found', () => {
  assert.equal(stageOf(null, false), 'checking');
  assert.equal(stageOf(readiness({ checks: allOk() }), false), 'ready');
  assert.equal(stageOf(null, true), 'error');
  // A read that failed outranks an answer left over from the last one.
  assert.equal(stageOf(readiness(), true), 'error');
  // An answer that says it is not ready but names no blocker is not ready.
  assert.equal(stageOf(readiness({ ready: false }), false), 'blocked');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { heldLink, heldLinkMessage } from '../src/lib/repairs/identity.ts';
import type { Schemas, User } from '../src/lib/api/types.ts';

/*
  The held-link branch of the link form: which refusals it answers, whose row
  it names, and the sentence it shows. Anything else keeps the toast, and a
  refusal nobody can act on is not turned into a move button by accident.
*/

const held = (detail = 'usr_old') => ({ code: 'assistant.identity_held', detail });

const row = (over: Partial<Schemas['EliIdentity']> = {}): Schemas['EliIdentity'] => ({
  user_id: 'usr_old',
  github_user_id: 42,
  github_login: 'octo',
  confirmed: true,
  ...over,
});

const users: User[] = [
  { id: 'usr_old', username: 'previous-owner' },
  { id: 'usr_new', username: 'fresh-account' },
];

test('only the held-link refusal becomes a move offer', () => {
  assert.equal(heldLink({ code: 'conflict', detail: 'usr_old' }, 'octo', [row()], users), null);
  assert.equal(heldLink({ code: 'assistant.provider_not_yours' }, 'octo', [row()], users), null);
  assert.equal(heldLink(held(), 'octo', [row()], users)?.holderId, 'usr_old');
});

test('the refusal carries the holder, and the rows only agree with it', () => {
  // The user list was drawn before the link landed where it now sits: the
  // refusal, read as this call's truth, wins over a stale row.
  const moved = heldLink(held('usr_new'), 'octo', [row()], users);
  assert.equal(moved?.holderId, 'usr_new');
  assert.equal(moved?.user?.username, 'fresh-account');
  assert.equal(heldLink(held('usr_old'), 'Octo', [row()], users)?.holderId, 'usr_old');
  // The refusal is the truth about the row: a holder the page's list has no
  // name for stays the holder, and the message falls back instead of
  // pointing at the typed row only.
  const unknown = heldLink(held('usr_other'), 'octo', [row()], users);
  assert.equal(unknown?.holderId, 'usr_other');
  assert.equal(unknown?.user, null);
});

test('a page whose records predate the row names the holder by the detail alone', () => {
  assert.equal(heldLink(held('usr_old'), 'octo', [], users)?.holderId, 'usr_old');
  assert.equal(heldLink(held('usr_old'), 'octo', [], users)?.user?.username, 'previous-owner');
});

test('a refusal with nothing to name keeps its move button and loses its at-sign', () => {
  const unknown = heldLink({ code: 'assistant.identity_held' }, 'octo', [], users);
  assert.equal(unknown?.holderId, '');
  assert.equal(unknown?.user, null);
  const said = heldLinkMessage({ holderId: '', user: null });
  assert.match(said, /another Zoomies user/);
  assert.match(said, /Move the link/);
});

test('the sentence names the holder by username, then id', () => {
  assert.match(
    heldLinkMessage({ holderId: 'usr_old', user: users.find((u) => u.id === 'usr_old') ?? null }),
    /@previous-owner already holds/,
  );
  assert.match(heldLinkMessage({ holderId: 'usr_gone', user: null }), /@usr_gone already holds/);
});

import { fileURLToPath, pathToFileURL } from 'node:url';
import { dirname, resolve as resolvePath } from 'node:path';

// Vite's `$lib` alias, which the unit runner does not otherwise know about.
// Without it a module can only be unit-tested if it happens to import nothing
// across the alias -- which is not a property worth choosing test coverage by.
const LIB = pathToFileURL(
  resolvePath(dirname(fileURLToPath(import.meta.url)), '../src/lib') + '/',
).href;

export async function resolve(specifier, context, next) {
  if (specifier === '$lib' || specifier.startsWith('$lib/')) {
    const rest = specifier === '$lib' ? '' : specifier.slice('$lib/'.length);
    const url = LIB + rest;
    // The same extensionless-TypeScript retry the relative branch below does.
    if (!/\.[a-z]+$/i.test(url)) {
      try {
        return await next(`${url}.ts`, context);
      } catch {
        // Not a TypeScript module after all; fall through.
      }
    }
    return next(url, context);
  }
  if (specifier.startsWith('.') && !/\.[a-z]+$/i.test(specifier)) {
    try {
      return await next(`${specifier}.ts`, context);
    } catch {
      // Not a TypeScript module after all; let Node say what it is.
    }
  }
  return next(specifier, context);
}

// A Svelte component of our own -- an icon drawn for a status -- cannot be
// compiled here any more than Lucide's can, and nothing a unit test checks
// needs it to be: a state map only needs its icon to be a distinct value. So
// every `.svelte` import resolves to a stub, for every test at once, rather
// than each test that reaches one learning the same lesson.
export async function load(url, context, next) {
  if (url.endsWith('.svelte')) {
    return { format: 'module', shortCircuit: true, source: 'export default function () {}' };
  }
  return next(url, context);
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  NO_FIGURES,
  figuresOf,
  isUnset,
  machineOf,
  profileBody,
  profileErrors,
  sameFigures,
  slotsFor,
} from '../src/lib/hosts/profile.ts';
import { slotsOf } from '../src/lib/hosts/slots.ts';

// The machines the docs' mixed-fleet example uses: a 12-CPU host and a 4-CPU
// host, each less the reserve the controller holds back.
const big = { cpus: 12, memoryMb: 32768, allocatableCpus: 11.4, allocatableMemoryMb: 31130 };
const small = { cpus: 4, memoryMb: 16384, allocatableCpus: 3.5, allocatableMemoryMb: 15565 };

test('a stored profile reads back into the form, and an empty one is every figure at zero', () => {
  assert.deepEqual(figuresOf(undefined), NO_FIGURES);
  assert.deepEqual(figuresOf({}), NO_FIGURES);
  assert.deepEqual(
    figuresOf({
      minimum: { cpus: 2, memory_mb: 4096 },
      standard: { cpus: 3, memory_mb: 8192, burst_max_cpus: 6, burst_max_memory_mb: 12288 },
    }),
    {
      minCpus: 2,
      minMemoryMb: 4096,
      standardCpus: 3,
      standardMemoryMb: 8192,
      burstMaxCpus: 6,
      burstMaxMemoryMb: 12288,
      tmpfsOff: false,
      tmpfsMaxMb: 0,
      tmpfsWorkMb: 0,
      tmpfsTmpMb: 0,
      tmpfsDaemonMb: 0,
    },
  );
});

// The API replaces the whole profile with what it is sent. A field that is
// zero in the form has to be absent from the request, or the host would be
// saved with an explicit zero the server refuses, and an empty form has to be
// `{}` because that is how "follow the fleet everywhere" is said.
test('the request carries only the figures that are set, and {} where none is', () => {
  assert.deepEqual(profileBody(NO_FIGURES), {});
  assert.deepEqual(profileBody({ ...NO_FIGURES, standardCpus: 3 }), { standard: { cpus: 3 } });
  assert.deepEqual(profileBody({ ...NO_FIGURES, minMemoryMb: 2048, burstMaxCpus: 4 }), {
    minimum: { memory_mb: 2048 },
    standard: { burst_max_cpus: 4 },
  });
  const full = {
    minCpus: 1,
    minMemoryMb: 2048,
    standardCpus: 3,
    standardMemoryMb: 8192,
    burstMaxCpus: 6,
    burstMaxMemoryMb: 12288,
    tmpfsOff: false,
    tmpfsMaxMb: 0,
    tmpfsWorkMb: 0,
    tmpfsTmpMb: 0,
    tmpfsDaemonMb: 0,
  };
  assert.deepEqual(figuresOf(profileBody(full)), full);
  assert.ok(isUnset(NO_FIGURES));
  assert.ok(!isUnset({ ...NO_FIGURES, burstMaxCpus: 1 }));
  assert.ok(
    !isUnset({ ...NO_FIGURES, burstMaxMemoryMb: 4096 }),
    'a memory ceiling alone is a profile',
  );
  assert.ok(sameFigures(full, { ...full }));
  assert.ok(!sameFigures(full, { ...full, minCpus: 2 }));
  assert.ok(!sameFigures(full, { ...full, burstMaxMemoryMb: 16384 }));
});

test('a memory ceiling is sent with the standard size, where the API keeps it', () => {
  assert.deepEqual(profileBody({ ...NO_FIGURES, burstMaxMemoryMb: 16384 }), {
    standard: { burst_max_memory_mb: 16384 },
  });
  assert.deepEqual(
    profileBody({ ...NO_FIGURES, standardMemoryMb: 8192, burstMaxMemoryMb: 16384 }),
    {
      standard: { memory_mb: 8192, burst_max_memory_mb: 16384 },
    },
  );
});

test('a host takes as many runners of its standard size as its machine holds', () => {
  // 11.4 CPUs hold three runners of 3 and 31130 MB holds three of 8 GB: the
  // cores run out first, by the controller's own tie-break.
  assert.deepEqual(slotsFor(big, 8, { ...NO_FIGURES, standardCpus: 3, standardMemoryMb: 8192 }), {
    slots: 3,
    held: 3,
    limitedBy: 'cpu',
    derived: true,
  });
  // Two runners of 1.5 CPU and 4 GB on a small host: 3.5/1.5 and 15565/4096.
  assert.deepEqual(
    slotsFor(small, 8, { ...NO_FIGURES, standardCpus: 1.5, standardMemoryMb: 4096 }),
    {
      slots: 2,
      held: 2,
      limitedBy: 'cpu',
      derived: true,
    },
  );
  // Memory is the smaller when the runners are memory-heavy.
  assert.deepEqual(slotsFor(big, 8, { ...NO_FIGURES, standardCpus: 1, standardMemoryMb: 16384 }), {
    slots: 1,
    held: 1,
    limitedBy: 'memory',
    derived: true,
  });
});

// 11.4 divided by 3.8 is 2.9999999999999996 in floating point, and a host that
// holds three runners must not be told it holds two.
test('a CPU share that does not divide evenly is not rounded down a runner', () => {
  const machine = { ...big, allocatableCpus: 3 * 3.8 };
  assert.equal(slotsFor(machine, 8, { ...NO_FIGURES, standardCpus: 3.8 }).slots, 3);
});

test('the capacity caps the derived count and is named as the limit when it is lower', () => {
  assert.deepEqual(slotsFor(big, 2, { ...NO_FIGURES, standardCpus: 3, standardMemoryMb: 8192 }), {
    slots: 2,
    held: 3,
    limitedBy: 'capacity',
    derived: true,
  });
  // Capacity equal to what the machine holds is nobody's limit.
  assert.deepEqual(slotsFor(big, 3, { ...NO_FIGURES, standardCpus: 3, standardMemoryMb: 8192 }), {
    slots: 3,
    held: 3,
    limitedBy: '',
    derived: true,
  });
});

test('a size never un-pauses a host, and a host with no size keeps its capacity', () => {
  assert.deepEqual(slotsFor(big, 0, { ...NO_FIGURES, standardCpus: 3 }), {
    slots: 0,
    held: 0,
    limitedBy: '',
    derived: false,
  });
  assert.deepEqual(slotsFor(big, 5, NO_FIGURES), {
    slots: 5,
    held: 5,
    limitedBy: '',
    derived: false,
  });
  // A minimum or a ceiling is not a size: neither gives the host a count.
  assert.deepEqual(slotsFor(big, 5, { ...NO_FIGURES, minCpus: 2, burstMaxCpus: 4 }), {
    slots: 5,
    held: 5,
    limitedBy: '',
    derived: false,
  });
});

test('a host that has not measured its machine has nothing to divide', () => {
  const unmeasured = machineOf({});
  assert.deepEqual(slotsFor(unmeasured, 4, { ...NO_FIGURES, standardCpus: 3 }), {
    slots: 4,
    held: 4,
    limitedBy: '',
    derived: false,
  });
  // Only the figures the machine has reported are divided: CPU is known and
  // memory is not, so memory does not bind.
  const cpusOnly = { ...big, memoryMb: 0, allocatableMemoryMb: 0 };
  assert.equal(
    slotsFor(cpusOnly, 8, { ...NO_FIGURES, standardCpus: 3, standardMemoryMb: 8192 }).slots,
    3,
  );
});

test('a standard larger than the machine gives no slots rather than a negative one', () => {
  assert.equal(slotsFor(small, 4, { ...NO_FIGURES, standardCpus: 8 }).slots, 0);
});

test('the controller counts slots, and the capacity stands in only where it has not said', () => {
  assert.equal(slotsOf({ capacity: 8, slots: 3 }), 3);
  assert.equal(slotsOf({ capacity: 8 }), 8);
  assert.equal(slotsOf({ capacity: 8, slots: 0 }), 0);
  assert.equal(slotsOf({}), 0);
});

test('a profile is held to the same floors as a pool', () => {
  const errors = profileErrors(
    {
      ...NO_FIGURES,
      minCpus: 0.1,
      minMemoryMb: 100,
      standardCpus: 0.1,
      standardMemoryMb: 100,
      burstMaxCpus: 0.1,
    },
    machineOf({}),
  );
  assert.deepEqual(Object.keys(errors).sort(), [
    'runner_profile.minimum.cpus',
    'runner_profile.minimum.memory_mb',
    'runner_profile.standard.burst_max_cpus',
    'runner_profile.standard.cpus',
    'runner_profile.standard.memory_mb',
  ]);
  assert.deepEqual(profileErrors(NO_FIGURES, big), {});
  assert.match(
    profileErrors({ ...NO_FIGURES, burstMaxMemoryMb: 100 }, machineOf({}))[
      'runner_profile.standard.burst_max_memory_mb'
    ] ?? '',
    /at least 512 MB/,
  );
});

test('a minimum above the standard, and a ceiling below it, are refused where they are typed', () => {
  const errors = profileErrors(
    {
      ...NO_FIGURES,
      minCpus: 4,
      minMemoryMb: 8192,
      standardCpus: 2,
      standardMemoryMb: 4096,
      burstMaxCpus: 1,
    },
    machineOf({}),
  );
  assert.match(errors['runner_profile.minimum.cpus'] ?? '', /above the standard, 2 cores/);
  assert.match(errors['runner_profile.minimum.memory_mb'] ?? '', /above the standard, 4 GB/);
  assert.match(errors['runner_profile.standard.burst_max_cpus'] ?? '', /at least the standard/);
  // Alone, neither has anything to be compared with.
  assert.deepEqual(profileErrors({ ...NO_FIGURES, minCpus: 4 }, machineOf({})), {});
  assert.deepEqual(profileErrors({ ...NO_FIGURES, burstMaxCpus: 1 }, machineOf({})), {});
});

test('a memory ceiling below the standard is refused: it would be a request to take memory back', () => {
  const errors = profileErrors(
    { ...NO_FIGURES, standardMemoryMb: 8192, burstMaxMemoryMb: 4096 },
    machineOf({}),
  );
  assert.match(
    errors['runner_profile.standard.burst_max_memory_mb'] ?? '',
    /at least the standard, 8 GB/,
  );
  assert.deepEqual(
    profileErrors({ ...NO_FIGURES, standardMemoryMb: 8192, burstMaxMemoryMb: 8192 }, machineOf({})),
    {},
    'at the standard is a ceiling with nothing to lend, which the server allows',
  );
  assert.deepEqual(profileErrors({ ...NO_FIGURES, burstMaxMemoryMb: 4096 }, machineOf({})), {});
});

test('a size the machine could never hold is refused only once the machine has said what it is', () => {
  const tooBig = { ...NO_FIGURES, standardCpus: 8, standardMemoryMb: 32768, minCpus: 6 };
  const errors = profileErrors(tooBig, small);
  assert.match(errors['runner_profile.standard.cpus'] ?? '', /could never run a runner here/);
  assert.match(errors['runner_profile.standard.memory_mb'] ?? '', /could never run a runner here/);
  assert.match(errors['runner_profile.minimum.cpus'] ?? '', /less than this minimum/);
  // The same figures on a host that has not reported its machine are saved:
  // there is nothing to compare them with, and the host is placed by slots.
  assert.deepEqual(profileErrors(tooBig, machineOf({})), {});
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { registerHooks } from 'node:module';

const LUCIDE = 'zoomies-test:lucide-stub';
const iconNames = (
  /import\s*\{([^}]*)\}\s*from\s*'@lucide\/svelte'/.exec(
    readFileSync(new URL('../src/lib/status.ts', import.meta.url), 'utf8'),
  )?.[1] ?? ''
)
  .split(',')
  .map((name) => name.trim())
  .filter((name) => name !== '');

registerHooks({
  resolve(specifier, context, next) {
    if (specifier === '@lucide/svelte')
      return { url: LUCIDE, format: 'module', shortCircuit: true };
    return next(specifier, context);
  },
  load(url, context, next) {
    if (url === LUCIDE)
      return {
        format: 'module',
        shortCircuit: true,
        source: iconNames.map((name) => `export function ${name}() {}`).join('\n'),
      };
    return next(url, context);
  },
});

const { runnerDisplayStatus } = await import('../src/lib/runners/runner-status.ts');
const { runnerStatus, runnerStatuses } = await import('../src/lib/status.ts');

test('active boosts and throttles replace busy or idle but retain lifecycle detail', () => {
  for (const state of ['busy', 'idle'] as const) {
    for (const [cpu, label] of [
      ['maximum_zoomies', 'Squirrel spotted'],
      ['zoomies', 'Rabbit spotted'],
      ['throttled', 'Leash tightened'],
    ] as const) {
      const status = runnerDisplayStatus({ state, cpu_resource: { state: cpu } });
      assert.equal(status.label, label);
      assert.equal(status.lifecycle.key, state);
      assert.equal(status.active, true);
    }
  }
});

test('stale CPU allocation never masks startup, draining or terminal states', () => {
  for (const state of ['provisioning', 'registering', 'draining', 'failed', 'removed'] as const) {
    for (const cpu of ['maximum_zoomies', 'zoomies', 'throttled'] as const) {
      const status = runnerDisplayStatus({ state, cpu_resource: { state: cpu } });
      assert.equal(status.key, state);
      assert.equal(status.active, false);
    }
  }
});

test('observation and normal allocations keep the lifecycle label', () => {
  // The lifecycle's own word, read from the state map rather than written
  // here: what is being tested is that a quiet allocation does not replace it,
  // not what the word is, and the runner vocabulary has already changed once
  // under a test that spelt it out.
  for (const cpu of ['observing', 'guaranteed', 'sit_and_stay'] as const) {
    const status = runnerDisplayStatus({ state: 'busy', cpu_resource: { state: cpu } });
    assert.equal(status.label, runnerStatus('busy').label);
    assert.ok(status.cpuDetail);
  }
  assert.equal(
    runnerDisplayStatus({ state: 'registering' }).label,
    runnerStatus('registering').label,
  );
  assert.equal(runnerDisplayStatus({}).label, 'Unknown');
});

test('turning the kennel vocabulary off gives every state a plain label, lifecycle and boosted alike', () => {
  assert.equal(runnerStatus('provisioning', false).label, 'Provisioning');
  assert.equal(runnerStatus('idle', false).label, 'Idle');
  for (const state of ['busy', 'idle'] as const) {
    for (const [cpu, label] of [
      ['maximum_zoomies', 'Zoomies'],
      ['zoomies', 'Extra'],
      ['throttled', 'Throttled'],
    ] as const) {
      const status = runnerDisplayStatus({ state, cpu_resource: { state: cpu } }, false);
      assert.equal(status.label, label);
      assert.equal(status.active, true);
    }
  }
  // The default stays the kennel vocabulary: a caller that does not say
  // otherwise gets what the product has always shown.
  assert.equal(
    runnerDisplayStatus({ state: 'busy', cpu_resource: { state: 'maximum_zoomies' } }).label,
    'Squirrel spotted',
  );
});

/*
 * The Runners grid's own buttons: Drain and Delete. A state drawn with one of
 * them, or with a media control, reads as something to press -- busy runners
 * drawn with Play looked like runners waiting to be started.
 */
const BUTTON_ICONS = ['Play', 'Pause', 'CircleSlash', 'Trash2'];

test('with the vocabulary off, no runner state is drawn with an icon a button uses', () => {
  const drawn = [
    ...runnerStatuses(false).map((status) => [status.key, status.icon.name] as [string, string]),
    ...(['maximum_zoomies', 'zoomies', 'throttled'] as const).map((cpu) => {
      const status = runnerDisplayStatus({ state: 'busy', cpu_resource: { state: cpu } }, false);
      return [status.key, status.icon.name] as [string, string];
    }),
  ];
  for (const [key, icon] of drawn) {
    assert.ok(!BUTTON_ICONS.includes(icon), `${key} is drawn with ${icon}`);
  }
});

test('every runner state has an icon of its own', () => {
  // Provisioning and registering were one dashed ring, and a runner stuck on
  // GitHub's side looked exactly like one still being built on the host's.
  const icons = runnerStatuses(false).map((status) => status.icon.name);
  assert.equal(new Set(icons).size, icons.length, icons.join(', '));
  assert.equal(runnerStatus('busy', false).icon.name, 'Activity');
});

test('the two boosts and the throttle are told apart by label and by icon', () => {
  // Both boosts said "Boost active" in the grid with the vocabulary off, and
  // the icon alone did not tell an operator which was extra and which maximum.
  const shown = (cpu: 'maximum_zoomies' | 'zoomies' | 'throttled') =>
    runnerDisplayStatus({ state: 'busy', cpu_resource: { state: cpu } }, false);
  const states = [shown('maximum_zoomies'), shown('zoomies'), shown('throttled')];
  const labels = states.map((status) => status.label);
  const icons = states.map((status) => status.icon.name);
  assert.equal(new Set(labels).size, 3, labels.join(', '));
  assert.equal(new Set(icons).size, 3, icons.join(', '));
});

