import { test } from 'node:test';
import assert from 'node:assert/strict';
import { focusWasPlaced, layers, placeFocus } from '../src/lib/keys';
import {
  GRACE,
  OPEN_DELAY,
  WARM,
  createAppTooltips,
  createTooltipController,
  type Bubble,
  type Clock,
} from '../src/lib/tooltip';

/**
 * A clock the test winds by hand. Real timers would make every one of these
 * a sleep, and the numbers under test are the product: 250, 300 and 100.
 */
function fakeClock(): Clock & { advance(ms: number): void } {
  let now = 1_000;
  let nextId = 1;
  const timers = new Map<number, { at: number; fn: () => void }>();
  return {
    now: () => now,
    setTimeout(fn, ms) {
      const id = nextId++;
      timers.set(id, { at: now + ms, fn });
      return id;
    },
    clearTimeout(id) {
      timers.delete(id as number);
    },
    advance(ms) {
      const end = now + ms;
      for (;;) {
        const due = [...timers.entries()]
          .filter(([, t]) => t.at <= end)
          .sort((a, b) => a[1].at - b[1].at)[0];
        if (!due) break;
        timers.delete(due[0]);
        now = due[1].at;
        due[1].fn();
      }
      now = end;
    },
  };
}

/** A bubble that remembers whether it is showing, and how often it was told to. */
function bubble(name: string): Bubble & { name: string; open: boolean; shown: number } {
  const b = {
    name,
    open: false,
    shown: 0,
    show() {
      b.open = true;
      b.shown++;
    },
    hide() {
      b.open = false;
    },
  };
  return b;
}

function setup() {
  const clock = fakeClock();
  const ctl = createTooltipController(clock);
  return { clock, ctl, a: bubble('a'), b: bubble('b'), c: bubble('c') };
}

test('the first bubble waits out the open delay before it shows', () => {
  const { clock, ctl, a } = setup();
  ctl.hover(a);
  clock.advance(OPEN_DELAY - 1);
  assert.equal(a.open, false, 'nothing yet one millisecond early');
  clock.advance(1);
  assert.equal(a.open, true);
  assert.equal(ctl.current, a);
});

test('leaving before the wait is over cancels the bubble altogether', () => {
  // A pointer crossing the page on its way somewhere else must not leave a
  // trail of help behind it.
  const { clock, ctl, a } = setup();
  ctl.hover(a);
  clock.advance(OPEN_DELAY - 50);
  ctl.unhover(a);
  clock.advance(1_000);
  assert.equal(a.open, false);
  assert.equal(a.shown, 0);
});

test('moving to a neighbour while one is open shows it at once', () => {
  // This is the sidebar sweep: the first entry costs a wait, the next seven
  // cost nothing.
  const { clock, ctl, a, b } = setup();
  ctl.hover(a);
  clock.advance(OPEN_DELAY);
  ctl.unhover(a);
  clock.advance(10);
  ctl.hover(b);
  assert.equal(b.open, true, 'no wait for the neighbour');
  assert.equal(a.open, false, 'and the first one is gone with it');
});

test('a neighbour is still instant for the warm window after the last one closed', () => {
  const { clock, ctl, a, b, c } = setup();
  ctl.hover(a);
  clock.advance(OPEN_DELAY);
  ctl.unhover(a);
  clock.advance(GRACE); // closes here
  assert.equal(a.open, false);
  clock.advance(WARM - 1);
  ctl.hover(b);
  assert.equal(b.open, true, 'one millisecond inside the window');
  ctl.unhover(b);
  clock.advance(GRACE + WARM + 1);
  assert.equal(b.open, false);
  ctl.hover(c);
  clock.advance(OPEN_DELAY - 1);
  assert.equal(c.open, false, 'a pointer that rested elsewhere pays the wait again');
  clock.advance(1);
  assert.equal(c.open, true);
});

test('closing waits out the grace so the pointer can cross onto the bubble', () => {
  const { clock, ctl, a } = setup();
  ctl.hover(a);
  clock.advance(OPEN_DELAY);
  ctl.unhover(a);
  clock.advance(GRACE - 1);
  assert.equal(a.open, true, 'still there a millisecond before the grace ends');
  clock.advance(1);
  assert.equal(a.open, false);
});

test('coming back to the trigger inside the grace keeps it open', () => {
  const { clock, ctl, a } = setup();
  ctl.hover(a);
  clock.advance(OPEN_DELAY);
  ctl.unhover(a);
  clock.advance(GRACE - 20);
  ctl.hover(a);
  clock.advance(1_000);
  assert.equal(a.open, true);
  assert.equal(a.shown, 1, 'and it was not shown a second time');
});

test('entering the bubble cancels the close, and leaving it starts the grace again', () => {
  const { clock, ctl, a } = setup();
  ctl.hover(a);
  clock.advance(OPEN_DELAY);
  ctl.unhover(a);
  clock.advance(GRACE - 10);
  ctl.bubbleEnter(a);
  clock.advance(5_000);
  assert.equal(a.open, true, 'a pointer resting on the bubble keeps it');
  ctl.bubbleLeave(a);
  clock.advance(GRACE - 1);
  assert.equal(a.open, true);
  clock.advance(1);
  assert.equal(a.open, false);
});

test('keyboard focus shows the bubble immediately and blur takes it away', () => {
  const { clock, ctl, a } = setup();
  ctl.focus(a);
  assert.equal(a.open, true, 'no timer ran');
  ctl.blur(a);
  assert.equal(a.open, false, 'and blur is as immediate');
  clock.advance(1_000);
  assert.equal(a.open, false);
});

test('a focused trigger keeps its bubble when the pointer drifts off it', () => {
  const { clock, ctl, a } = setup();
  ctl.focus(a);
  ctl.hover(a);
  ctl.unhover(a);
  clock.advance(1_000);
  assert.equal(a.open, true, 'the keyboard is still there');
  ctl.blur(a);
  assert.equal(a.open, false);
});

test('blur leaves the bubble up while the pointer is still on the trigger', () => {
  const { clock, ctl, a } = setup();
  ctl.hover(a);
  clock.advance(OPEN_DELAY);
  ctl.focus(a);
  ctl.blur(a);
  assert.equal(a.open, true);
  ctl.unhover(a);
  clock.advance(GRACE);
  assert.equal(a.open, false);
});

test('an opt-out opens at once even from cold, which is what the matrix squares do', () => {
  const { ctl, a } = setup();
  ctl.hover(a, 'none');
  assert.equal(a.open, true);
});

test('a pointer press hides the bubble and cancels one that has not shown yet', () => {
  const { clock, ctl, a, b } = setup();
  ctl.hover(a);
  clock.advance(OPEN_DELAY);
  assert.equal(ctl.dismissCurrent(), true);
  assert.equal(a.open, false);
  // A click made inside the wait must not be answered by help arriving late.
  ctl.hover(b);
  clock.advance(OPEN_DELAY - 50);
  ctl.dismiss(b);
  clock.advance(1_000);
  assert.equal(b.open, false);
});

test('escape closes the open bubble and says so, and says nothing when there is none', () => {
  // The caller stops the event only when this returns true, so an Escape that
  // belongs to a menu or a dialog is never swallowed by a tooltip that is not
  // there.
  const { clock, ctl, a } = setup();
  assert.equal(ctl.dismissCurrent(), false);
  ctl.hover(a);
  clock.advance(OPEN_DELAY);
  assert.equal(ctl.dismissCurrent(), true);
  assert.equal(a.open, false);
  assert.equal(ctl.dismissCurrent(), false, 'the second press is the dialog');
});

test('only one bubble is ever showing, whatever the pointer and the keyboard do', () => {
  const { clock, ctl, a, b, c } = setup();
  const all = [a, b, c];
  // A fixed pseudo-random walk, so a failure can be replayed.
  let seed = 7;
  const next = (n: number) => {
    seed = (seed * 1103515245 + 12345) & 0x7fffffff;
    return seed % n;
  };
  for (let step = 0; step < 2_000; step++) {
    const target = all[next(3)]!;
    switch (next(9)) {
      case 0:
        ctl.hover(target);
        break;
      case 1:
        ctl.hover(target, 'none');
        break;
      case 2:
        ctl.unhover(target);
        break;
      case 3:
        ctl.focus(target);
        break;
      case 4:
        ctl.blur(target);
        break;
      case 5:
        ctl.bubbleEnter(target);
        break;
      case 6:
        ctl.bubbleLeave(target);
        break;
      case 7:
        ctl.dismissCurrent();
        break;
      default:
        clock.advance(next(400));
    }
    const open = all.filter((x) => x.open);
    assert.ok(open.length <= 1, `step ${step}: ${open.map((x) => x.name)} are all open`);
    assert.equal(ctl.current, open[0] ?? null, `step ${step}: the controller agrees`);
  }
});

test('a bubble opened by its owner is adopted, and closes whatever was showing', () => {
  // The rich cards on a touch screen open from a tap through their bound
  // `open`, bypassing the pointer rules. They still have to be the only one.
  const { ctl, a, b } = setup();
  ctl.focus(a);
  b.show();
  ctl.adopt(b);
  assert.equal(a.open, false);
  assert.equal(ctl.current, b);
  b.hide();
  ctl.forget(b);
  assert.equal(ctl.current, null);
});

test('a wait still pending on another trigger does not take the bubble from the one the keyboard is on', () => {
  // The pointer rests on A, starting its 250ms. Before it is over, Tab moves
  // focus to B, which opens at once. A's timer must not later fire, close B and
  // show help for a control the keyboard has left.
  const { clock, ctl, a, b } = setup();
  ctl.hover(a);
  clock.advance(OPEN_DELAY - 100);
  ctl.focus(b);
  assert.equal(b.open, true);
  clock.advance(1_000);
  assert.equal(b.open, true, 'B is still the one showing');
  assert.equal(a.open, false, 'and A never came');
  assert.equal(ctl.current, b);
});

test('a bubble opened by its owner also cancels waits pending elsewhere', () => {
  const { clock, ctl, a, b } = setup();
  ctl.hover(a);
  clock.advance(OPEN_DELAY - 100);
  b.show();
  ctl.adopt(b);
  clock.advance(1_000);
  assert.equal(b.open, true);
  assert.equal(a.open, false);
});

test('a bubble its owner opened stays through a pointer leaving, until focus goes or something is pressed', () => {
  // A tap on a touch screen opens a rich card through its bound `open`, and a
  // finger lifting is a pointer leaving. The card must not go with it.
  const { clock, ctl, a } = setup();
  a.show();
  ctl.adopt(a);
  ctl.hover(a);
  ctl.unhover(a);
  clock.advance(5_000);
  assert.equal(a.open, true, 'a finger lifting is not a reason to close');
  ctl.blur(a);
  assert.equal(a.open, false, 'focus leaving is');
});

test('a pinned bubble can still be put away by a press', () => {
  const { ctl, a } = setup();
  a.show();
  ctl.adopt(a);
  assert.equal(ctl.dismissCurrent(), true);
  assert.equal(a.open, false);
});

/* -- the keyboard and the layer stack ------------------------------------------ */

/** An Escape the way the browser makes one, minus the DOM Node does not have. */
function escape(): Event & { key: string; stopped: boolean } {
  const event = new Event('keydown', { cancelable: true }) as Event & {
    key: string;
    stopped: boolean;
  };
  event.key = 'Escape';
  event.stopped = false;
  event.stopPropagation = () => {
    event.stopped = true;
  };
  return event;
}

test('escape stops where it is heard only while a bubble is open', () => {
  const clock = fakeClock();
  const target = new EventTarget();
  const { controller } = createAppTooltips(clock, target);
  const a = bubble('a');

  const idle = escape();
  target.dispatchEvent(idle);
  assert.equal(idle.stopped, false, 'with nothing open the key goes on to whoever wants it');

  controller.focus(a);
  const open = escape();
  target.dispatchEvent(open);
  assert.equal(open.stopped, true);
  assert.equal(open.defaultPrevented, true);
  assert.equal(a.open, false);

  const after = escape();
  target.dispatchEvent(after);
  assert.equal(after.stopped, false, 'and the next press is not the tooltip’s');
});

test('a pointer press anywhere puts the bubble away', () => {
  const clock = fakeClock();
  const target = new EventTarget();
  const { controller } = createAppTooltips(clock, target);
  const a = bubble('a');
  controller.focus(a);
  target.dispatchEvent(new Event('pointerdown'));
  assert.equal(a.open, false);
});

test('an open bubble is the top of the layer stack but never takes the keyboard', () => {
  // Shortcuts stand down under any overlay. A tooltip is not one: with this
  // wrong, resting the pointer on the sidebar would switch `g p` and `r` off.
  const clock = fakeClock();
  const { controller } = createAppTooltips(clock, new EventTarget());
  const a = bubble('a');
  const before = layers.size;
  controller.focus(a);
  assert.equal(layers.top()?.kind, 'tooltip');
  assert.equal(layers.size, before, 'it does not count');
  assert.equal(layers.closeTop(), true, 'but the stack can still close it');
  assert.equal(a.open, false);
  assert.equal(layers.top()?.kind, undefined);
});

test('a tooltip over a menu closes before the menu does', () => {
  const clock = fakeClock();
  const { controller } = createAppTooltips(clock, new EventTarget());
  const a = bubble('a');
  let menuOpen = true;
  const menu = layers.push('dropdown', () => (menuOpen = false));
  try {
    controller.focus(a);
    assert.equal(layers.size, 1, 'only the menu counts');
    layers.closeTop();
    assert.equal(a.open, false, 'the bubble goes first');
    assert.equal(menuOpen, true, 'the menu is untouched');
    layers.closeTop();
    assert.equal(menuOpen, false, 'and the next Escape is the menu’s');
  } finally {
    layers.remove(menu);
  }
});

test('focus an overlay places itself is not somebody reaching for a control', () => {
  // A dialog opened from the keyboard puts focus on its first control. A bubble
  // that opened on that would take the first Escape, which belongs to the dialog.
  assert.equal(focusWasPlaced(), false, 'nothing has been placed yet');
  let focused = false;
  placeFocus({ focus: () => (focused = true) } as unknown as HTMLElement);
  assert.equal(focused, true, 'the element is still focused');
  assert.equal(focusWasPlaced(), true, 'and the tooltip is told it was placed');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  ARROW_INSET,
  GAP,
  MARGIN,
  narrowPlacement,
  place,
  type Box,
} from '../src/lib/tooltip-place';

const viewport = { width: 1000, height: 800 };
const size = { width: 200, height: 60 };

/** A 40 by 20 trigger whose top left corner is at (left, top). */
const trigger = (left: number, top: number): Box => ({
  left,
  top,
  right: left + 40,
  bottom: top + 20,
});

test('a bubble sits above its trigger, centred on it, with the caret in the middle', () => {
  const t = trigger(480, 400);
  const p = place({ anchor: t, size, viewport, preferred: 'top' });
  assert.equal(p.side, 'top');
  assert.equal(p.left, 500 - 100);
  assert.equal(p.top, 400 - 60 - GAP);
  assert.equal(p.arrow, 100, 'the caret is at the middle of a bubble that is centred');
});

test('it goes below when the preference is bottom', () => {
  const p = place({ anchor: trigger(480, 400), size, viewport, preferred: 'bottom' });
  assert.equal(p.side, 'bottom');
  assert.equal(p.top, 420 + GAP);
});

test('it flips to the other side when there is no room and the other side has more', () => {
  // 60 + GAP + MARGIN = 76 wanted above; only 50 there.
  const t = trigger(480, 50);
  const p = place({ anchor: t, size, viewport, preferred: 'top' });
  assert.equal(p.side, 'bottom');
  assert.equal(p.top, 70 + GAP);
});

test('the room it asks for includes the margin, not just the gap', () => {
  const need = size.height + GAP + MARGIN;
  const fits = place({ anchor: trigger(480, need), size, viewport, preferred: 'top' });
  assert.equal(fits.side, 'top', 'exactly enough room stays put');
  const short = place({ anchor: trigger(480, need - 1), size, viewport, preferred: 'top' });
  assert.equal(short.side, 'bottom', 'one pixel less flips');
});

test('it stays on its preferred side when the opposite side is no better', () => {
  // A bubble taller than either side: flipping would only move the problem.
  const tall = { width: 200, height: 500 };
  const t = trigger(480, 300); // 300 above, 480 below... below is more
  const flipped = place({ anchor: t, size: tall, viewport, preferred: 'top' });
  assert.equal(flipped.side, 'bottom');
  const worse = place({ anchor: trigger(480, 560), size: tall, viewport, preferred: 'top' });
  assert.equal(worse.side, 'top', 'only 220 below against 560 above');
});

test('it is held inside the margin, and the caret still points at the trigger', () => {
  // A trigger near the left edge: the bubble cannot centre on it, so it is
  // held at the margin, and the caret has to slide to keep pointing at it.
  const t = trigger(20, 400); // centre x = 40
  const p = place({ anchor: t, size, viewport, preferred: 'top' });
  assert.equal(p.left, MARGIN, 'clamped to the margin');
  assert.equal(p.left + p.arrow, 40, 'the caret is still under the trigger\u2019s centre');
});

test('the caret keeps its distance from the ends of the bubble', () => {
  // The trigger is so near the corner that its centre is inside the rounded end.
  const t = trigger(0, 400); // centre x = 20, bubble held at left = 8, so 12 in
  const p = place({ anchor: t, size, viewport, preferred: 'top' });
  assert.equal(p.arrow, ARROW_INSET, 'held 14px in from the start');

  const farRight = trigger(viewport.width - 40, 400); // centre x = 980
  const q = place({ anchor: farRight, size, viewport, preferred: 'top' });
  assert.equal(q.left, viewport.width - size.width - MARGIN);
  assert.equal(q.arrow, size.width - ARROW_INSET, 'and 14px in from the end');
});

test('a bubble narrower than two caret insets puts the caret in the middle', () => {
  const tiny = { width: 20, height: 20 };
  const p = place({ anchor: trigger(480, 400), size: tiny, viewport, preferred: 'top' });
  assert.equal(p.arrow, 10);
});

test('a side bubble is centred on the trigger vertically and clamped the same way', () => {
  const t = trigger(100, 400);
  const p = place({ anchor: t, size, viewport, preferred: 'right' });
  assert.equal(p.side, 'right');
  assert.equal(p.left, 140 + GAP);
  assert.equal(p.top, 410 - 30);
  assert.equal(p.arrow, 30);

  const top = place({ anchor: trigger(100, 0), size, viewport, preferred: 'right' });
  assert.equal(top.top, MARGIN);
  assert.equal(top.arrow, ARROW_INSET, 'the trigger\u2019s centre is 2px in, so the inset wins');
});

test('a side bubble flips across the trigger when the window has no room', () => {
  const t = trigger(viewport.width - 60, 400);
  const p = place({ anchor: t, size, viewport, preferred: 'right' });
  assert.equal(p.side, 'left');
  assert.equal(p.left, t.left - size.width - GAP);
});

test('an entry in the sidebar anchors to the sidebar’s edge so the bubble clears the rail', () => {
  // The entry is inset in a rail that ends at x = 240. The bubble must start
  // past the rail, not past the entry, or it sits on top of the rail.
  const entry: Box = { left: 12, top: 300, right: 228, bottom: 332 };
  const rail: Box = { left: 0, top: 0, right: 240, bottom: 800 };
  const p = place({ anchor: entry, edge: rail, size, viewport, preferred: 'right' });
  assert.equal(p.side, 'right');
  assert.equal(p.left, 240 + GAP);
  assert.equal(p.top, 316 - 30, 'vertical still follows the entry itself');
  assert.equal(p.arrow, 30);
});

test('the sidebar’s edge matters only to a side placement', () => {
  const entry: Box = { left: 12, top: 300, right: 228, bottom: 332 };
  const rail: Box = { left: 0, top: 0, right: 240, bottom: 800 };
  const withEdge = place({ anchor: entry, edge: rail, size, viewport, preferred: 'top' });
  const without = place({ anchor: entry, size, viewport, preferred: 'top' });
  assert.deepEqual(withEdge, without);
});

test('on a narrow screen a right preference becomes bottom', () => {
  assert.equal(narrowPlacement('right', true), 'bottom');
  assert.equal(narrowPlacement('right', false), 'right');
  for (const side of ['top', 'bottom', 'left'] as const) {
    assert.equal(narrowPlacement(side, true), side, `${side} is not touched`);
  }
});

test('a bubble bigger than the window is pinned to the margin rather than off-screen', () => {
  const huge = { width: 2000, height: 2000 };
  const p = place({ anchor: trigger(480, 400), size: huge, viewport, preferred: 'top' });
  assert.equal(p.left, MARGIN);
  assert.equal(p.top, MARGIN);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  transferSteps,
  waitLabel,
  waitTone,
  type TransferProgress,
  type TransferWait,
} from '../src/lib/settings/transfer.ts';

function progress(over: Partial<TransferProgress> = {}): TransferProgress {
  return {
    draining: true,
    ready: false,
    live_runners: 0,
    busy_runners: 0,
    pending_cleanup: 0,
    active_jobs: 0,
    machine_operations: 0,
    cleanup_awaiting_host: 0,
    cleanup_awaiting_github: 0,
    cleanup_failed: 0,
    waiting: [],
    summary: 'Preparing.',
    ...over,
  };
}

function wait(over: Partial<TransferWait> = {}): TransferWait {
  return {
    kind: 'cleanup',
    id: 'run_1',
    name: 'pool-a-aaaaaaaa',
    host: 'vm-1',
    host_healthy: true,
    host_confirmed: false,
    registration_confirmed: false,
    detail: 'waiting for vm-1 to confirm it is gone',
    ...over,
  };
}

// The paragraph that read "0 busy runners, 0 runners remaining, 8 awaiting
// cleanup, 11 running jobs" gave the operator five numbers and no order. The
// checklist is the four things the fence waits on, each done or not, so what
// is holding the transfer is the one step that is not ticked.
test('a drained fleet is four steps done, and a count above zero is the one step that is not', () => {
  const done = transferSteps(progress());
  assert.deepEqual(
    done.map((s) => [s.kind, s.done, s.tone]),
    [
      ['job', true, 'idle'],
      ['runner', true, 'idle'],
      ['cleanup', true, 'idle'],
      ['machine', true, 'idle'],
    ],
  );
  const stuck = transferSteps(
    progress({ pending_cleanup: 8, cleanup_awaiting_host: 5, cleanup_awaiting_github: 8 }),
  );
  const cleanup = stuck.find((s) => s.kind === 'cleanup');
  assert.ok(cleanup);
  assert.equal(cleanup.done, false);
  assert.equal(cleanup.count, 8);
  assert.equal(cleanup.tone, 'pending');
  assert.equal(cleanup.note, 'Waiting to be confirmed gone: 5 by the host, 8 by GitHub.');
  assert.ok(stuck.filter((s) => !s.done).length === 1);
});

// A host that has stopped sending heartbeats is the one thing waiting cannot
// fix, so its step is red rather than amber, and so is each row on it.
test('a silent host turns its step and its rows to danger, and says so on the pill', () => {
  const silent = wait({ host: 'vm-silent', host_healthy: false });
  const steps = transferSteps(progress({ pending_cleanup: 1, waiting: [silent] }));
  assert.equal(steps.find((s) => s.kind === 'cleanup')?.tone, 'danger');
  assert.equal(waitTone(silent), 'danger');
  assert.equal(waitLabel(silent), 'Host silent');
  // A healthy host still to confirm is merely pending, and the pill names the
  // side that is outstanding.
  assert.equal(waitTone(wait()), 'pending');
  assert.equal(waitLabel(wait()), 'Host');
  assert.equal(waitLabel(wait({ host_confirmed: true })), 'GitHub');
});

test('a failed cleanup is danger whatever its host is doing, and a busy runner is busy', () => {
  const failed = wait({ error: 'container is in use' });
  assert.equal(waitTone(failed), 'danger');
  assert.equal(waitLabel(failed), 'Failed');
  assert.equal(
    transferSteps(progress({ pending_cleanup: 1, cleanup_failed: 1, waiting: [failed] })).find(
      (s) => s.kind === 'cleanup',
    )?.tone,
    'danger',
  );
  const busy = wait({ kind: 'runner', state: 'busy' });
  assert.equal(waitTone(busy), 'busy');
  assert.equal(waitLabel(busy), 'Busy');
  assert.equal(waitLabel(wait({ kind: 'job' })), 'Running');
});

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { uploadInstanceArchive } from '../src/lib/settings/transfer-upload.ts';
const chunkBytes = 8 * 1024 * 1024;
function fixture(size: number, lostResponse = false) {
  let offset = 0,
    chunks = 0,
    probes = 0,
    verifying = false;
  const sizes: number[] = [];
  const snapshot = () => ({
    id: 'upload_test',
    size,
    offset,
    chunk_bytes: chunkBytes,
    state: verifying ? 'verifying' : 'uploading',
  });
  const saved = globalThis.fetch;
  globalThis.fetch = async (url, init) => {
    const path = String(url);
    if (path.endsWith('/transfers/uploads')) {
      assert.equal(JSON.parse(String(init?.body)).size, size);
      return Response.json(snapshot(), { status: 201 });
    }
    if (path.includes('/chunks?')) {
      assert.equal(new URL(path, 'http://localhost').searchParams.get('offset'), String(offset));
      assert.ok(init?.body instanceof Blob);
      assert.ok(init.body.size <= chunkBytes);
      sizes.push(init.body.size);
      offset += init.body.size;
      chunks++;
      if (lostResponse && chunks === 1) throw new TypeError('response lost after saving bytes');
      return Response.json(snapshot());
    }
    if (path.endsWith('/verify')) {
      assert.equal(offset, size);
      assert.equal(JSON.parse(String(init?.body)).passphrase, 'archive passphrase');
      verifying = true;
      return Response.json(snapshot(), { status: 202 });
    }
    assert.ok(path.endsWith('/upload_test'));
    probes++;
    return Response.json(
      verifying
        ? { ...snapshot(), state: 'verified', backup: { id: 'verified_copy' } }
        : snapshot(),
    );
  };
  return {
    restore: () => {
      globalThis.fetch = saved;
    },
    sizes,
    probes: () => probes,
  };
}
test('a large instance archive uses bounded requests and polls its verified receipt', async () => {
