/* -- the hosts' rollout ----------------------------------------------------- */

function rollout(overrides: Partial<Rollout> = {}): Rollout {
  return {
    id: 'rol_k3fqz2mx7abcd',
    target: 'v1.3.0',
    state: 'running',
    halted_reason: '',
    done: 1,
    total: 3,
    current: 'build-02',
    ...overrides,
  };
}

const HALTED_BECAUSE =
  "The update of build-02 to v1.3.0 did not succeed, so the rollout is halted. Read why on the host's card, then resume the rollout or cancel it.";

test('a running rollout says how far it has got and which host is being updated now', () => {
  const words = rolloutWords(rollout());
  assert.equal(words.label, 'Rolling out');
  assert.equal(words.title, 'Updating hosts to v1.3.0');
  assert.equal(words.progress, '1 of 3 hosts updated.');
  assert.equal(words.detail, 'build-02 is being updated now.');
  assert.equal(words.open, true);
  assert.equal(words.canResume, false);
  assert.match(words.live, /1 of 3 hosts updated/);
  // Between two hosts there is nobody to name, and nothing is made up.
  assert.equal(rolloutWords(rollout({ current: '' })).detail, '');
  assert.equal(rolloutWords(rollout({ done: 0, total: 1 })).progress, '0 of 1 host updated.');
});

// Held until an operator acts is what the draining colour means, so a halted
// rollout wears it, names the host in the controller's own sentence, and says
// what each of the two ways on does.
test('a halted rollout names the host in the controller’s words and says to resume or cancel', () => {
  const words = rolloutWords(
    rollout({ state: 'halted', current: '', halted_reason: HALTED_BECAUSE }),
  );
  assert.equal(words.label, 'Halted');
  assert.equal(words.tone, 'draining');
  assert.equal(words.title, 'The rollout to v1.3.0 is halted');
  assert.equal(words.detail, HALTED_BECAUSE);
  assert.match(words.detail, /build-02/);
  assert.match(words.next, /^Resume goes on to the next host/);
  assert.match(words.next, /Cancel stops the rollout/);
  assert.equal(words.open, true);
  assert.equal(words.canResume, true);
  assert.match(words.live, /halted/);
  // A halted rollout whose sentence did not arrive still says how to go on.
  const bare = rolloutWords(rollout({ state: 'halted', current: '', halted_reason: '' }));
  assert.match(bare.detail, /did not succeed/);
  assert.match(bare.next, /Resume/);
  assert.match(bare.next, /Cancel/);
});

test('a rollout that is done is idle, and one that was cancelled says so without alarm', () => {
  const done = rolloutWords(rollout({ state: 'done', done: 3, total: 3, current: '' }));
  assert.equal(done.label, 'Done');
  assert.equal(done.tone, 'idle');
  assert.equal(done.title, 'The rollout to v1.3.0 is done');
  assert.equal(done.progress, '3 of 3 hosts updated.');
  assert.equal(done.open, false);
  assert.equal(done.canResume, false);

  const cancelled = rolloutWords(rollout({ state: 'cancelled', current: '' }));
  assert.equal(cancelled.label, 'Cancelled');
  assert.equal(cancelled.tone, 'neutral');
  assert.equal(cancelled.title, 'The rollout to v1.3.0 was cancelled');
  assert.equal(cancelled.open, false);
});

// The status colours are a fixed mapping: running is news (accent, as an update
// in flight is), halted is held, done is idle. Danger is a host's failed update,
// which its card shows; the rollout itself never wears it.
test('each rollout state has the colour the mapping gives it', () => {
  const tones = Object.fromEntries(
    (['running', 'halted', 'done', 'cancelled'] as const).map((state) => [
      state,
      rolloutWords(rollout({ state })).tone,
    ]),
  );
  assert.deepEqual(tones, {
    running: 'accent',
    halted: 'draining',
    done: 'idle',
    cancelled: 'neutral',
  });
});

function rolloutHost(overrides: Partial<RolloutHost> = {}): RolloutHost {
  return {
    embedded: false,
    version_skew: 'behind',
    update: {
      state: 'none',
      reason: 'This host runs 1.2.0.',
      can_update: true,
      attempt_id: '',
      code: '',
    },
    ...overrides,
  };
}

// The count is the controller's: each host's own update block says whether it
// can be asked, which is the same answer its card's button is drawn from.
test('the hosts action counts the hosts whose own update block says they can be updated', () => {
  const hosts = [
    rolloutHost(),
    rolloutHost(),
    rolloutHost({
      update: { state: 'none', reason: 'No helper.', can_update: false, attempt_id: '', code: '' },
    }),
    rolloutHost({ version_skew: undefined, update: undefined }),
  ];
  assert.deepEqual(rolloutOffer(status(), hosts, true), {
    kind: 'offer',
    count: 2,
    tag: 'v1.3.0',
  });
  assert.equal(rolloutOffer(status(), [hosts[2]!], true).kind, 'none');
});

test('the hosts action is an administrator’s, and is not offered while a rollout is open', () => {
  const hosts = [rolloutHost()];
  assert.equal(rolloutOffer(status(), hosts, false).kind, 'none');
  assert.equal(rolloutOffer(null, hosts, true).kind, 'none');
  for (const state of ['running', 'halted'] as const) {
    assert.equal(rolloutOffer(status({ rollout: rollout({ state }) }), hosts, true).kind, 'none');
  }
  for (const state of ['done', 'cancelled'] as const) {
    assert.equal(rolloutOffer(status({ rollout: rollout({ state }) }), hosts, true).kind, 'offer');
  }
});

// As on a host's card: with the mode off the action is there and cannot be
// pressed, with the reason beside it as text, for as long as a host is behind.
test('with updating off the hosts action is disabled and says why, while a host is behind', () => {
  const off = status({ mode: 'off' });
  const behind = rolloutHost({
    update: {
      state: 'none',
      reason: 'Updating is off.',
      can_update: false,
      attempt_id: '',
      code: '',
    },
  });
  assert.deepEqual(rolloutOffer(off, [behind], true), {
    kind: 'off',
    sentence: 'Updating is off. Set updates.mode to manual or auto to update hosts from here.',
  });
  assert.equal(rolloutOffer(off, [rolloutHost({ version_skew: undefined })], true).kind, 'none');
  assert.equal(rolloutOffer(off, [rolloutHost({ embedded: true })], true).kind, 'none');
  assert.equal(rolloutOffer(off, [behind], false).kind, 'none');
});

// The confirmation is the last thing before a fleet of agents restart, so each
// thing it promises is pinned, and none of it is more than the code does: the
// restart does not wait for jobs, so it is not said to.
test('the rollout confirmation names the release and the hosts and says what a failure does', () => {
  const words = confirmRollout('v1.3.0', 2);
  assert.equal(words.title, 'Update 2 hosts');
  assert.equal(words.description, 'Update 2 hosts to v1.3.0, one at a time?');
  assert.equal(words.confirmLabel, 'Update 2 hosts');
  const lines = words.consequences.join('\n');
  assert.match(lines, /Each host’s agent restarts when its turn comes/);
  assert.match(lines, /Jobs that are running keep running/);
  assert.match(lines, /does not wait for them to finish/);
  assert.match(lines, /one host’s update fails or times out, the rollout halts/);
  assert.match(lines, /until an administrator resumes or cancels it/);
  // The count includes a host the planner will pass over, so the dialog says so.
  assert.match(lines, /A host whose update to v1\.3\.0 has already failed twice is skipped/);
  assert.doesNotMatch(`${words.description}\n${lines}`, /\u2014| -- /);
  assert.equal(confirmRollout('v1.3.0', 1).title, 'Update 1 host');
});

test('nothing a rollout says carries an em dash or its stand-in', () => {
  for (const state of ['running', 'halted', 'done', 'cancelled'] as const) {
    const words = rolloutWords(rollout({ state, halted_reason: '' }));
    assert.doesNotMatch(JSON.stringify(words), /\u2014| -- /, state);
  }
});

test('DEV confirmation identifies the moving development channel without a release downgrade warning', () => {
  const words = confirmControllerUpdate('dev', 'main-sha-abc1234', false);
  assert.match(words.description, /to dev/);
  assert.ok(words.consequences.some((line) => line.includes('moving channel')));
  assert.ok(!words.consequences.some((line) => line.includes('older code')));
});

test('development status distinguishes main from a published dev image', () => {
  const dev = { current: 'abc1234', latest: '', state: 'unknown' as const, checked_at: null };
  assert.match(developmentStatus(dev), /has not been confirmed/);
  assert.match(
    developmentStatus({ ...dev, latest: 'abc1234', state: 'current' }),
    /matches the latest checked commit/,
  );
  assert.match(
    developmentStatus({ ...dev, latest: 'def5678', state: 'available' }),
    /may still be publishing/,
  );
});

/*
 * The usage chart's figures. The arithmetic is here rather than in the
 * component so that "this day has not happened yet" and "the fleet had
 * nowhere to put a runner" can be tested without a browser.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { emptyBucket, type ActivityBucket } from '../src/lib/insights/activity.ts';
import {
  capacityRuns,
  inProgress,
  usageFigures,
  usageFormat,
  usageLines,
} from '../src/lib/insights/usageSeries.ts';

const DAY = 86_400_000;
const first = new Date(2026, 8, 14).getTime();
const day = (i: number, fill: Partial<ActivityBucket> = {}): ActivityBucket => ({
  ...emptyBucket(new Date(first + i * DAY).toISOString()),
  ...fill,
});
const figure = (key: string) => usageFigures('jobs', true).filter((f) => f.key === key);

/*
 * A report runs to the end of its last day, so a window chosen today has
 * hours in it that have not happened. Drawn as zeroes, they are a line that
 * dives to the floor and stays there -- a fleet that stopped, rather than one
 * whose week is not over.
 */
test('an interval that has not begun is a gap, and the one being filled is drawn', () => {
  const buckets = [day(0, { queued: 4 }), day(1, { queued: 2 }), day(2), day(3)];
  const [queued] = usageLines(buckets, figure('queued'), first + DAY + 3_600_000);
  assert.deepEqual(
    queued?.points.map((p) => p.value),
    [4, 2, null, null],
  );
  // The newest reading is the interval being filled, which is what the label
  // at the end of the line and the meters below are showing.
  assert.deepEqual(queued?.last, { i: 1, value: 2 });
  // An interval with nothing in it is still an interval: zero jobs queued on
  // a day that happened is news, and a gap is not.
  const quiet = usageLines([day(0)], figure('queued'), first + DAY);
  assert.deepEqual(
    quiet[0]?.points.map((p) => p.value),
    [0],
  );

  assert.equal(inProgress(day(1), 'day', first + DAY + 60_000), true);
  assert.equal(inProgress(day(0), 'day', first + DAY + 60_000), false);
  assert.equal(inProgress(day(2), 'day', first + DAY + 60_000), false);
});

/*
 * A runner idles on behalf of a pool and never on behalf of a repository, so
 * at those groupings its hours are not the group's to claim. The table drops
 * the column; the chart drops the line, rather than drawing somebody else's
 * time as this repository's.
 */
test('allocated runner time is only drawn where it can be attributed', () => {
  assert.deepEqual(
    usageFigures('runtime', true).map((f) => f.key),
    ['execution', 'allocated'],
  );
  assert.deepEqual(
    usageFigures('runtime', false).map((f) => f.key),
    ['execution'],
  );
  // The job counts belong to whoever ran them, at every grouping.
  assert.deepEqual(usageFigures('jobs', false).length, usageFigures('jobs', true).length);

  // Hours, not seconds: the axis is read in the unit the tiles above use.
  const [executing] = usageLines(
    [day(0, { execution_seconds: 5400 })],
    usageFigures('runtime', true),
    first + DAY,
  );
  assert.equal(executing?.points[0]?.value, 1.5);
});

/*
 * The band is the fleet trend's starvation shading, drawn from what the
 * report already counts: the minutes a pool had work to place and nowhere to
 * put it.
 */
test('the capacity band is a spell, and an interval nobody observed ends it', () => {
  const buckets = [
    day(0, { capacity_samples: 10, capacity_reached: 2 }),
    day(1, { capacity_samples: 10, capacity_reached: 1 }),
    day(2, { capacity_samples: 10 }),
    day(3, { capacity_samples: 0 }),
    day(4, { capacity_samples: 10, capacity_reached: 5 }),
  ];
  assert.deepEqual(capacityRuns(buckets), [
    { from: 0, to: 1 },
    { from: 4, to: 4 },
  ]);
  // A report with no capacity observations at all -- a repository grouping,
  // or a fleet that predates the counting -- shades nothing rather than
  // claiming the fleet was never short.
  assert.deepEqual(capacityRuns([day(0), day(1)]), []);
  assert.deepEqual(capacityRuns([]), []);
});

/* Colour alone never tells two lines apart; nor does the stroke alone. */
test('no two figures on one chart are drawn the same way, and hours keep their fractions', () => {
  for (const measure of ['jobs', 'runtime'] as const) {
    const drawn = new Set<string>();
    for (const f of usageFigures(measure, true)) {
      const mark = `${f.tone} ${f.dash}`;
      assert.ok(!drawn.has(mark), `${f.key} is drawn exactly like another figure`);
      drawn.add(mark);
      assert.match(f.tone, /^var\(--z-/, `${f.key} must take a token, not a colour`);
    }
  }
  // A count of jobs is whole; a quarter of an hour of runner time is not.
  assert.equal(usageFormat('jobs')(3), usageFormat('runtime')(3));
  assert.notEqual(usageFormat('jobs')(1.23456), usageFormat('runtime')(1.23456));
  assert.ok(!usageFormat('runtime')(1.23456).includes('456'));
});

import assert from 'node:assert/strict';
import test from 'node:test';
import {
  NAV_GROUPS,
  SECTIONS,
  hiddenFromVisitors,
  navGroupsFor,
  sectionsFor,
} from '../src/lib/shell/sections.ts';

// A public view's visitor is refused the audit log, settings, AI context and
// every change. A link that can only lead to "sign in to see this" is a link
// that teaches them to distrust the ones that work, so the navigation leaves
// those pages out.
test('a visitor is offered the fleet and not the pages about the people who run it', () => {
  const paths = sectionsFor(true).map((item) => item.path);
  for (const hidden of ['/audit', '/settings', '/migrate', '/repairs']) {
    assert.ok(!paths.includes(hidden), `${hidden} is offered to a visitor`);
  }
  for (const shown of ['/', '/pools', '/runners', '/queue', '/workflows', '/hosts', '/kennel']) {
    assert.ok(paths.includes(shown), `${shown} is not offered to a visitor`);
  }
});

// The pages under a hidden one are hidden with it: a settings tab is still
// settings, and AI context is source files whichever address reaches it.
test('everything under a hidden page is hidden too, and nothing that only shares a prefix', () => {
  assert.ok(hiddenFromVisitors('/settings/account'));
  assert.ok(hiddenFromVisitors('/kennel/ai-context'));
  assert.ok(hiddenFromVisitors('/ai-context/setup'));
  assert.ok(!hiddenFromVisitors('/kennel'));
  assert.ok(!hiddenFromVisitors('/auditorium'));
});

// Everybody else's navigation is the one they learnt, entry for entry.
test('somebody signed in is offered every section', () => {
  assert.deepEqual(sectionsFor(false), SECTIONS);
  assert.deepEqual(navGroupsFor(false), NAV_GROUPS);
});

// Hiding the Administration pages must not leave its heading over nothing.
test('a visitor sees no heading with nothing under it', () => {
  for (const group of navGroupsFor(true)) {
    assert.ok(group.items.length > 0, `the ${group.label ?? 'top'} heading is empty`);
  }
  assert.ok(!navGroupsFor(true).some((group) => group.label === 'Administration'));
});

